-- Name: graphql(text, text, jsonb, jsonb); Type: FUNCTION; Schema: graphql_public; Owner: postgres
--

CREATE FUNCTION graphql_public.graphql("operationName" text DEFAULT NULL::text, query text DEFAULT NULL::text, variables jsonb DEFAULT NULL::jsonb, extensions jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;


ALTER FUNCTION graphql_public.graphql("operationName" text, query text, variables jsonb, extensions jsonb) OWNER TO postgres;

--
-- Name: drop_unused_batch(integer); Type: FUNCTION; Schema: ops_rollback; Owner: postgres
--

CREATE FUNCTION ops_rollback.drop_unused_batch(p_limit integer DEFAULT 75) RETURNS TABLE(dropped integer, skipped integer, remaining integer)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops_rollback'
    AS $$
declare r record; d int := 0; s int := 0;
begin
  perform set_config('lock_timeout','2s',true);
  for r in
    select id, schemaname, idx from ops_rollback.index_drops_20260905
    where status='pending' order by bytes asc limit p_limit
  loop
    begin
      execute format('drop index if exists %I.%I', r.schemaname, r.idx);
      update ops_rollback.index_drops_20260905
         set status='dropped', dropped_at=now() where id=r.id;
      d := d + 1;
    exception when others then
      update ops_rollback.index_drops_20260905
         set status='skipped', err=sqlerrm where id=r.id;
      s := s + 1;
    end;
  end loop;
  return query select d, s, (select count(*)::int from ops_rollback.index_drops_20260905 where status='pending');
end $$;


ALTER FUNCTION ops_rollback.drop_unused_batch(p_limit integer) OWNER TO postgres;

--
-- Name: take_snapshot(text); Type: FUNCTION; Schema: ops_rollback; Owner: postgres
--

CREATE FUNCTION ops_rollback.take_snapshot(p_label text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'extensions', 'ops_rollback', 'public'
    AS $$
begin
  insert into ops_rollback.perf_snapshots(
    label, realtime_decode_total_s, realtime_decode_calls, realtime_decode_mean_ms,
    wal_lsn, db_size_bytes, index_bytes, deadlocks, rollbacks, commits, temp_bytes, cache_hit_pct)
  select p_label,
    round((s.total_exec_time/1000)::numeric,1), s.calls, round(s.mean_exec_time::numeric,2),
    pg_current_wal_lsn(),
    pg_database_size(current_database()),
    (select sum(pg_relation_size(indexrelid)) from pg_stat_user_indexes),
    d.deadlocks, d.xact_rollback, d.xact_commit, d.temp_bytes,
    round((100.0*d.blks_hit/nullif(d.blks_hit+d.blks_read,0))::numeric,2)
  from pg_stat_database d
  left join lateral (
    select total_exec_time, calls, mean_exec_time from extensions.pg_stat_statements
    where query like 'SELECT wal->>%' order by total_exec_time desc limit 1) s on true
  where d.datname = current_database();
end $$;


ALTER FUNCTION ops_rollback.take_snapshot(p_label text) OWNER TO postgres;

--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: postgres
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO postgres;

--
-- Name: accept_friendship(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.accept_friendship(p_friendship_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.friendships%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000'; END IF;
  SELECT * INTO v_row FROM public.friendships
   WHERE id = p_friendship_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Friend request not found'); END IF;
  IF v_row.friend_id <> v_uid THEN
    RAISE EXCEPTION 'Only the recipient can accept this friend request' USING ERRCODE = '42501';
  END IF;
  IF v_row.status = 'accepted' THEN
    RETURN jsonb_build_object('success', true, 'alreadyAccepted', true);
  END IF;
  IF v_row.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Friend request is no longer pending');
  END IF;
  UPDATE public.friendships SET status = 'accepted' WHERE id = p_friendship_id;
  RETURN jsonb_build_object('success', true, 'alreadyAccepted', false);
END;
$$;


ALTER FUNCTION public.accept_friendship(p_friendship_id uuid) OWNER TO postgres;

--
-- Name: activate_vip(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.activate_vip(p_user_id uuid, p_stripe_subscription_id text, p_stripe_customer_id text, p_plan text, p_period_end timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  INSERT INTO vip_subscriptions (
    user_id, stripe_subscription_id, stripe_customer_id, plan, 
    status, current_period_start, current_period_end
  )
  VALUES (
    p_user_id, p_stripe_subscription_id, p_stripe_customer_id, p_plan,
    'active', NOW(), p_period_end
  )
  ON CONFLICT (user_id) DO UPDATE SET
    stripe_subscription_id = EXCLUDED.stripe_subscription_id,
    stripe_customer_id = EXCLUDED.stripe_customer_id,
    plan = EXCLUDED.plan,
    status = 'active',
    current_period_start = NOW(),
    current_period_end = EXCLUDED.current_period_end,
    updated_at = NOW();
END;
$$;


