--
-- Name: admit_vip_subscription_checkout(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admit_vip_subscription_checkout(p_user_id uuid, p_stripe_subscription_id text, p_request_id text, p_intent_hash text, p_session_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_profile public.profiles%ROWTYPE;
  v_claim public.vip_subscription_checkout_claims%ROWTYPE;
  v_subscription public.vip_subscriptions%ROWTYPE;
  v_prior_subscription public.vip_subscriptions%ROWTYPE;
  v_claim_found boolean := false;
  v_barrier_expires_at timestamptz := now() + interval '7 days';
BEGIN
  IF p_user_id IS NULL
     OR p_stripe_subscription_id IS NULL
     OR btrim(p_stripe_subscription_id) = ''
     OR length(p_stripe_subscription_id) > 255
     OR p_request_id IS NULL
     OR btrim(p_request_id) = ''
     OR length(p_request_id) > 200
     OR p_intent_hash IS NULL
     OR p_intent_hash !~ '^[a-f0-9]{64}$'
     OR (p_session_id IS NOT NULL AND (
       btrim(p_session_id) = '' OR length(p_session_id) > 255
     )) THEN
    RETURN jsonb_build_object(
      'success', false,
      'admitted', false,
      'state', 'invalid'
    );
  END IF;

  -- All Card and Diamond admissions serialize on this same row first.
  SELECT * INTO v_profile
    FROM public.profiles
   WHERE id = p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'admitted', false,
      'state', 'profile_not_found'
    );
  END IF;

  -- Preserve the shared lock order: profile, Card claim, subscription ledger.
  SELECT * INTO v_claim
    FROM public.vip_subscription_checkout_claims
   WHERE user_id = p_user_id
   FOR UPDATE;
  v_claim_found := FOUND;

  SELECT * INTO v_subscription
    FROM public.vip_subscriptions
   WHERE stripe_subscription_id = p_stripe_subscription_id
   FOR UPDATE;
  IF FOUND THEN
    IF v_subscription.user_id IS DISTINCT FROM p_user_id THEN
      RETURN jsonb_build_object(
        'success', false,
        'admitted', false,
        'state', 'subscription_conflict'
      );
    END IF;
    IF v_claim_found
       AND v_claim.state = 'admitting'
       AND (
         v_claim.request_id <> p_request_id
         OR v_claim.intent_hash <> p_intent_hash
       ) THEN
      RETURN jsonb_build_object(
        'success', false,
        'admitted', false,
        'state', 'claim_conflict'
      );
    END IF;
    IF v_claim_found
       AND v_claim.request_id = p_request_id
       AND v_claim.intent_hash = p_intent_hash THEN
      IF v_claim.session_id IS NOT NULL
         AND p_session_id IS DISTINCT FROM v_claim.session_id THEN
        RETURN jsonb_build_object(
          'success', false,
          'admitted', false,
          'state', 'session_conflict'
        );
      END IF;
      IF v_claim.state <> 'admitting' THEN
        UPDATE public.vip_subscription_checkout_claims
           SET state = 'admitting',
               session_id = COALESCE(session_id, p_session_id),
               expires_at = GREATEST(expires_at, v_barrier_expires_at),
               updated_at = now()
         WHERE user_id = p_user_id
           AND request_id = p_request_id
           AND intent_hash = p_intent_hash;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'VIP subscription replay barrier disappeared while locked';
        END IF;
      END IF;
    END IF;
    RETURN jsonb_build_object(
      'success', true,
      'admitted', false,
      'state', 'replay',
      'finalize_required', (
        v_claim_found
        AND v_claim.request_id = p_request_id
        AND v_claim.intent_hash = p_intent_hash
      ),
      'stripe_subscription_id', p_stripe_subscription_id
    );
  END IF;

  -- Production intentionally keeps one current subscription row per user.
  -- Lock that row now. A live Card obligation or unexpired Diamond grant is an
  -- overlap; an expired/terminal row is recycled only after every entitlement
  -- and claim check below succeeds, inside this same admission transaction.
  SELECT * INTO v_prior_subscription
    FROM public.vip_subscriptions subscription
   WHERE subscription.user_id = p_user_id
     AND subscription.stripe_subscription_id IS DISTINCT FROM p_stripe_subscription_id
   FOR UPDATE;
  IF FOUND AND (
    (
      v_prior_subscription.stripe_subscription_id IS NOT NULL
      AND left(v_prior_subscription.stripe_subscription_id, 8) <> 'diamond_'
      AND v_prior_subscription.status IN (
        'active', 'trialing', 'past_due', 'unpaid', 'incomplete', 'paused'
      )
    ) OR (
      v_prior_subscription.stripe_subscription_id IS NOT NULL
      AND left(v_prior_subscription.stripe_subscription_id, 8) = 'diamond_'
      AND v_prior_subscription.status IN ('active', 'trialing')
      AND (
        v_prior_subscription.tier = 'lifetime'
        OR v_prior_subscription.current_period_end > now()
      )
    )
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'admitted', false,
      'state', 'vip_entitlement_active'
    );
  END IF;

  IF v_profile.vip_tier = 'lifetime'
     OR (v_profile.vip_expires_at IS NOT NULL AND v_profile.vip_expires_at > now()) THEN
    RETURN jsonb_build_object(
      'success', false,
      'admitted', false,
      'state', 'vip_entitlement_active'
    );
  END IF;

  IF v_claim_found THEN
    IF v_claim.request_id = p_request_id
       AND v_claim.intent_hash = p_intent_hash THEN
      IF v_claim.session_id IS NOT NULL
         AND p_session_id IS DISTINCT FROM v_claim.session_id THEN
        RETURN jsonb_build_object(
          'success', false,
          'admitted', false,
          'state', 'session_conflict'
        );
      END IF;

      UPDATE public.vip_subscription_checkout_claims
         SET state = 'admitting',
             session_id = COALESCE(session_id, p_session_id),
             expires_at = GREATEST(expires_at, v_barrier_expires_at),
             updated_at = now()
       WHERE user_id = p_user_id
         AND request_id = p_request_id
         AND intent_hash = p_intent_hash;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'VIP subscription admission barrier disappeared while locked';
      END IF;
      IF v_prior_subscription.id IS NOT NULL THEN
        UPDATE public.vip_subscriptions
           SET stripe_subscription_id = p_stripe_subscription_id,
               updated_at = now()
         WHERE id = v_prior_subscription.id;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'Terminal VIP subscription row disappeared while locked';
        END IF;
      END IF;
      RETURN jsonb_build_object(
        'success', true,
        'admitted', true,
        'state', 'admitted',
        'finalize_required', true,
        'claim_adopted', true,
        'barrier_expires_at', v_barrier_expires_at,
        'stripe_subscription_id', p_stripe_subscription_id
      );
    END IF;

    IF v_claim.state = 'admitting'
       OR v_claim.expires_at > now() THEN
      RETURN jsonb_build_object(
        'success', false,
        'admitted', false,
        'state', 'claim_conflict'
      );
    END IF;

    DELETE FROM public.vip_subscription_checkout_claims
     WHERE user_id = p_user_id
       AND state <> 'admitting';
  END IF;

  -- A classified legacy subscription can supply a deterministic synthetic
  -- request/hash. It is safe to establish that barrier only after proving no
  -- active entitlement and no unexpired conflicting claim above.
  INSERT INTO public.vip_subscription_checkout_claims(
    user_id,
    request_id,
    intent_hash,
    state,
    session_id,
    expires_at,
    updated_at
  ) VALUES (
    p_user_id,
    p_request_id,
    p_intent_hash,
    'admitting',
    p_session_id,
    v_barrier_expires_at,
    now()
  );

  IF v_prior_subscription.id IS NOT NULL THEN
    UPDATE public.vip_subscriptions
       SET stripe_subscription_id = p_stripe_subscription_id,
           updated_at = now()
     WHERE id = v_prior_subscription.id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Terminal VIP subscription row disappeared while locked';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'admitted', true,
    'state', 'admitted',
    'finalize_required', true,
    'claim_adopted', false,
    'barrier_expires_at', v_barrier_expires_at,
    'stripe_subscription_id', p_stripe_subscription_id
  );
END;
$_$;


ALTER FUNCTION public.admit_vip_subscription_checkout(p_user_id uuid, p_stripe_subscription_id text, p_request_id text, p_intent_hash text, p_session_id text) OWNER TO postgres;

--
-- Name: FUNCTION admit_vip_subscription_checkout(p_user_id uuid, p_stripe_subscription_id text, p_request_id text, p_intent_hash text, p_session_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.admit_vip_subscription_checkout(p_user_id uuid, p_stripe_subscription_id text, p_request_id text, p_intent_hash text, p_session_id text) IS 'marketplace_phase7_vip_acquisition_mutex:v1';


--
-- Name: analyze_spots_by_game_type(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.analyze_spots_by_game_type(p_game_type text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(game_type text, count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '5s'
    AS $_$
  SELECT artifact.game_type, count(*)::bigint
  FROM public.solved_spots_gold artifact
  WHERE coalesce(p_game_type, '') ~ '^[a-z0-9_]{1,64}$'
    AND artifact.game_type = p_game_type
  GROUP BY artifact.game_type
  ORDER BY count(*) DESC
  LIMIT greatest(1, least(1000, coalesce(p_limit, 100)))
$_$;


ALTER FUNCTION public.analyze_spots_by_game_type(p_game_type text, p_limit integer) OWNER TO postgres;

--
-- Name: apply_personal_assistant_retention(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_personal_assistant_retention(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_days integer;
  v_last_run timestamptz;
  v_cutoff timestamptz;
  v_counts jsonb := '{}'::jsonb;
  v_count integer := 0;
  v_old_leak_ids uuid[] := '{}'::uuid[];
  v_old_drill_batch_ids uuid[] := '{}'::uuid[];
  v_old_session_ids uuid[] := '{}'::uuid[];
  v_fingerprint text;
BEGIN
  SELECT retention_days, last_retention_run_at INTO v_days, v_last_run
  FROM public.pa_coaching_preferences
  WHERE user_id = p_user_id;
  IF v_days IS NULL THEN RETURN jsonb_build_object('applied', false, 'retention_days', null); END IF;
  IF v_last_run IS NOT NULL AND v_last_run > now() - interval '24 hours' THEN
    RETURN jsonb_build_object('applied', false, 'retention_days', v_days, 'reason', 'recently_applied');
  END IF;
  v_cutoff := now() - make_interval(days => v_days);

  SELECT coalesce(array_agg(id), '{}'::uuid[]) INTO v_old_leak_ids
  FROM public.user_leaks
  WHERE user_id = p_user_id AND status = 'resolved' AND coalesce(resolved_at, updated_at, created_at) < v_cutoff;
  DELETE FROM public.leak_hand_examples WHERE leak_id = ANY(v_old_leak_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('hand_examples', v_count);
  DELETE FROM public.user_leaks WHERE id = ANY(v_old_leak_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('resolved_leaks', v_count);
  DELETE FROM public.hand_audit_decisions WHERE user_id = p_user_id AND audited_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('audit_decisions', v_count);
  DELETE FROM public.pa_leak_audit_jobs WHERE user_id = p_user_id AND status IN ('completed', 'failed', 'cancelled') AND updated_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('audit_jobs', v_count);
  DELETE FROM public.pa_coach_feedback WHERE user_id = p_user_id AND status = 'resolved' AND updated_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('coach_feedback', v_count);
  DELETE FROM public.pa_coaching_goals WHERE user_id = p_user_id AND status = 'completed' AND updated_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('coaching_goals', v_count);

  SELECT coalesce(array_agg(batch_id), '{}'::uuid[]) INTO v_old_drill_batch_ids
  FROM public.leak_drill_sessions
  WHERE user_id = p_user_id AND completed_at IS NOT NULL AND completed_at < v_cutoff;
  DELETE FROM public.leak_drill_answers WHERE user_id = p_user_id AND batch_id = ANY(v_old_drill_batch_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('drill_answers', v_count);
  DELETE FROM public.leak_drill_attempts WHERE user_id = p_user_id AND batch_id = ANY(v_old_drill_batch_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('drill_attempts', v_count);
  DELETE FROM public.leak_drill_sessions WHERE user_id = p_user_id AND batch_id = ANY(v_old_drill_batch_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('drill_sessions', v_count);

  SELECT coalesce(array_agg(id), '{}'::uuid[]) INTO v_old_session_ids
  FROM public.sandbox_sessions WHERE user_id = p_user_id AND created_at < v_cutoff;
  DELETE FROM public.sandbox_coach_results
  WHERE user_id = p_user_id AND (created_at < v_cutoff OR session_id = ANY(v_old_session_ids));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('sandbox_coach_results', v_count);
  DELETE FROM public.sandbox_equity_history
  WHERE user_id = p_user_id AND (created_at < v_cutoff OR session_id = ANY(v_old_session_ids));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('sandbox_equity_history', v_count);
  DELETE FROM public.sandbox_results WHERE session_id = ANY(v_old_session_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('sandbox_results', v_count);
  DELETE FROM public.sandbox_sessions WHERE id = ANY(v_old_session_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('sandbox_sessions', v_count);
  DELETE FROM public.sandbox_saved_hands WHERE user_id = p_user_id AND created_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('saved_hands', v_count);
  DELETE FROM public.sandbox_analytics WHERE user_id = p_user_id AND created_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('sandbox_analytics', v_count);
  DELETE FROM public.sandbox_quiz_results WHERE user_id = p_user_id AND created_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('sandbox_quiz_results', v_count);
  DELETE FROM public.sandbox_bookmarks WHERE user_id = p_user_id AND created_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('sandbox_bookmarks', v_count);
  DELETE FROM public.sandbox_templates WHERE user_id = p_user_id AND created_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('sandbox_templates', v_count);
  DELETE FROM public.sandbox_shared_scenarios WHERE creator_id = p_user_id AND created_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('sandbox_shared_scenarios', v_count);
  DELETE FROM public.solution_bookmarks WHERE user_id = p_user_id AND created_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('solution_bookmarks', v_count);

  UPDATE public.pa_coaching_preferences SET last_retention_run_at = now(), updated_at = now()
  WHERE user_id = p_user_id;
  v_fingerprint := md5(p_user_id::text || ':retention:' || v_counts::text || ':' || clock_timestamp()::text || ':' || gen_random_uuid()::text);
  INSERT INTO public.pa_data_lifecycle_receipts (user_id, action, scope, item_counts, receipt_fingerprint)
  VALUES (p_user_id, 'retention', 'all', v_counts, v_fingerprint);
  RETURN jsonb_build_object('applied', true, 'retention_days', v_days, 'cutoff', v_cutoff, 'counts', v_counts);
END;
$$;


ALTER FUNCTION public.apply_personal_assistant_retention(p_user_id uuid) OWNER TO postgres;

--
-- Name: apply_personal_assistant_retention_batch(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_personal_assistant_retention_batch(p_limit integer DEFAULT 250) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id uuid;
  v_result jsonb;
  v_processed integer := 0;
  v_applied integer := 0;
BEGIN
  IF current_user NOT IN ('postgres', 'service_role', 'supabase_admin') THEN
    RAISE EXCEPTION 'service role required' USING ERRCODE = '42501';
  END IF;

  FOR v_user_id IN
    SELECT user_id
    FROM public.pa_coaching_preferences
    WHERE retention_days IS NOT NULL
      AND (last_retention_run_at IS NULL OR last_retention_run_at <= now() - interval '24 hours')
    ORDER BY last_retention_run_at NULLS FIRST, user_id
    LIMIT greatest(1, least(coalesce(p_limit, 250), 1000))
    FOR UPDATE SKIP LOCKED
  LOOP
    v_result := public.apply_personal_assistant_retention(v_user_id);
    v_processed := v_processed + 1;
    IF coalesce((v_result ->> 'applied')::boolean, false) THEN
      v_applied := v_applied + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', v_processed,
    'applied', v_applied,
    'batch_limit', greatest(1, least(coalesce(p_limit, 250), 1000))
  );
END;
$$;


ALTER FUNCTION public.apply_personal_assistant_retention_batch(p_limit integer) OWNER TO postgres;

--
-- Name: apply_rakeback_player_stats(uuid, uuid, uuid, integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_rakeback_player_stats(p_rake_record_id uuid, p_user_id uuid, p_club_id uuid, p_hands integer, p_rake numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inserted integer;
BEGIN
  IF p_rake_record_id IS NULL OR p_user_id IS NULL OR p_club_id IS NULL THEN
    RETURN false;
  END IF;

  INSERT INTO public.rakeback_stats_applied (rake_record_id, user_id, hands, rake)
  VALUES (p_rake_record_id, p_user_id, p_hands, p_rake)
  ON CONFLICT (rake_record_id, user_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 0 THEN
    RETURN false;
  END IF;

  INSERT INTO public.player_stats (
    user_id, club_id, hands_played, total_rake,
    total_winnings, total_losses, vpip, pfr, tournaments_played, tournaments_won
  ) VALUES (
    p_user_id, p_club_id, COALESCE(p_hands, 0), COALESCE(p_rake, 0),
    0, 0, 0, 0, 0, 0
  )
  ON CONFLICT (user_id, club_id) DO UPDATE SET
    hands_played = public.player_stats.hands_played + EXCLUDED.hands_played,
    total_rake   = ROUND((public.player_stats.total_rake + EXCLUDED.total_rake) * 100) / 100,
    updated_at   = NOW();

  RETURN true;
END;
$$;


ALTER FUNCTION public.apply_rakeback_player_stats(p_rake_record_id uuid, p_user_id uuid, p_club_id uuid, p_hands integer, p_rake numeric) OWNER TO postgres;

--
-- Name: apply_venue_directory_enrichment(integer, timestamp with time zone, text, text, text, text, text, text, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_venue_directory_enrichment(p_venue_id integer, p_expected_revision timestamp with time zone, p_phone text, p_website text, p_profile_photo_url text, p_cover_photo_url text, p_logo_url text, p_source_url text, p_confidence numeric, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_before public.poker_venues%ROWTYPE;
  v_after public.poker_venues%ROWTYPE;
  v_actor_role text;
BEGIN
  SELECT role::text INTO v_actor_role FROM public.profiles WHERE id = p_actor_id;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'superadmin', 'god') THEN
    RAISE EXCEPTION 'platform admin role required' USING ERRCODE = '42501';
  END IF;
  IF p_expected_revision IS NULL THEN
    RAISE EXCEPTION 'expected venue revision required' USING ERRCODE = '22023';
  END IF;
  IF char_length(trim(coalesce(p_reason, ''))) < 12 OR char_length(trim(p_reason)) > 500 THEN
    RAISE EXCEPTION 'audit reason must contain 12 to 500 characters' USING ERRCODE = '22023';
  END IF;
  IF nullif(trim(coalesce(p_source_url, '')), '') IS NULL THEN
    RAISE EXCEPTION 'source URL required' USING ERRCODE = '22023';
  END IF;
  IF p_confidence IS NULL OR p_confidence < 0 OR p_confidence > 1 THEN
    RAISE EXCEPTION 'confidence must be between 0 and 1' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_before FROM public.poker_venues WHERE id = p_venue_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'venue not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_before.location_integrity_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'venue revision changed' USING ERRCODE = '40001';
  END IF;

  UPDATE public.poker_venues
  SET phone = nullif(trim(p_phone), ''),
      website = nullif(trim(p_website), ''),
      profile_photo_url = nullif(trim(p_profile_photo_url), ''),
      cover_photo_url = nullif(trim(p_cover_photo_url), ''),
      logo_url = nullif(trim(p_logo_url), ''),
      last_verified_at = now(),
      location_integrity_revision = clock_timestamp()
  WHERE id = p_venue_id
  RETURNING * INTO v_after;

  INSERT INTO public.venue_directory_enrichment_log (
    venue_id, actor_id, reason, source_url, confidence, before_record, after_record
  ) VALUES (
    p_venue_id, p_actor_id, trim(p_reason), trim(p_source_url), p_confidence,
    jsonb_build_object(
      'phone', v_before.phone,
      'website', v_before.website,
      'profile_photo_url', v_before.profile_photo_url,
      'cover_photo_url', v_before.cover_photo_url,
      'logo_url', v_before.logo_url,
      'revision', v_before.location_integrity_revision
    ),
    jsonb_build_object(
      'phone', v_after.phone,
      'website', v_after.website,
      'profile_photo_url', v_after.profile_photo_url,
      'cover_photo_url', v_after.cover_photo_url,
      'logo_url', v_after.logo_url,
      'revision', v_after.location_integrity_revision
    )
  );

  RETURN jsonb_build_object(
    'venue_id', v_after.id,
    'name', v_after.name,
    'revision', v_after.location_integrity_revision
  );
END;
$$;


ALTER FUNCTION public.apply_venue_directory_enrichment(p_venue_id integer, p_expected_revision timestamp with time zone, p_phone text, p_website text, p_profile_photo_url text, p_cover_photo_url text, p_logo_url text, p_source_url text, p_confidence numeric, p_reason text, p_actor_id uuid) OWNER TO postgres;

--
-- Name: apply_vip_subscription_projection(uuid, text, text, text, text, text, text, numeric, timestamp with time zone, timestamp with time zone, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_vip_subscription_projection(p_user_id uuid, p_stripe_subscription_id text, p_stripe_customer_id text, p_request_id text, p_intent_hash text, p_tier text, p_status text, p_price_usd numeric, p_current_period_start timestamp with time zone, p_current_period_end timestamp with time zone, p_cancel_at_period_end boolean, p_canceled_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_profile public.profiles%ROWTYPE;
  v_claim public.vip_subscription_checkout_claims%ROWTYPE;
  v_subscription public.vip_subscriptions%ROWTYPE;
  v_other_subscription public.vip_subscriptions%ROWTYPE;
  v_projection_id uuid;
  v_has_exact_admission boolean := false;
  v_preserve_non_card_entitlement boolean := false;
BEGIN
  IF p_user_id IS NULL
     OR p_stripe_subscription_id IS NULL
     OR btrim(p_stripe_subscription_id) = ''
     OR length(p_stripe_subscription_id) > 255
     OR p_stripe_customer_id IS NULL
     OR btrim(p_stripe_customer_id) = ''
     OR length(p_stripe_customer_id) > 255
     OR p_request_id IS NULL
     OR btrim(p_request_id) = ''
     OR length(p_request_id) > 200
     OR p_intent_hash IS NULL
     OR p_intent_hash !~ '^[a-f0-9]{64}$'
     OR p_tier NOT IN ('monthly', 'yearly')
     OR p_status NOT IN (
       'active', 'trialing', 'past_due', 'unpaid', 'incomplete', 'paused',
       'canceled', 'incomplete_expired'
     )
     OR p_price_usd IS NULL
     OR p_price_usd < 0
     OR p_current_period_start IS NULL
     OR p_current_period_end IS NULL
     OR p_current_period_end < p_current_period_start
     OR p_cancel_at_period_end IS NULL
     OR (p_status = 'canceled' AND p_canceled_at IS NULL) THEN
    RETURN jsonb_build_object(
      'success', false,
      'projected', false,
      'state', 'invalid'
    );
  END IF;

  SELECT * INTO v_profile
    FROM public.profiles
   WHERE id = p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'projected', false,
      'state', 'profile_not_found'
    );
  END IF;
  SELECT * INTO v_claim
    FROM public.vip_subscription_checkout_claims
   WHERE user_id = p_user_id
   FOR UPDATE;
  v_has_exact_admission := FOUND
    AND v_claim.request_id = p_request_id
    AND v_claim.intent_hash = p_intent_hash
    AND v_claim.state = 'admitting';
  IF FOUND
     AND v_claim.state = 'admitting'
     AND NOT v_has_exact_admission THEN
    RETURN jsonb_build_object(
      'success', false,
      'projected', false,
      'state', 'claim_conflict'
    );
  END IF;
  IF v_profile.stripe_customer_id IS NOT NULL
     AND v_profile.stripe_customer_id <> p_stripe_customer_id
     AND NOT v_has_exact_admission THEN
    RETURN jsonb_build_object(
      'success', false,
      'projected', false,
      'state', 'customer_conflict'
    );
  END IF;

  SELECT * INTO v_subscription
    FROM public.vip_subscriptions
   WHERE stripe_subscription_id = p_stripe_subscription_id
   FOR UPDATE;
  IF FOUND AND v_subscription.user_id IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object(
      'success', false,
      'projected', false,
      'state', 'subscription_conflict'
    );
  END IF;
  IF FOUND
     AND v_subscription.stripe_customer_id IS NOT NULL
     AND v_subscription.stripe_customer_id <> p_stripe_customer_id
     AND NOT v_has_exact_admission THEN
    RETURN jsonb_build_object(
      'success', false,
      'projected', false,
      'state', 'subscription_customer_conflict'
    );
  END IF;
  IF FOUND
     AND v_subscription.status IN ('canceled', 'incomplete_expired')
     AND p_status IN (
       'active', 'trialing', 'past_due', 'unpaid', 'incomplete', 'paused'
     )
     AND (
       v_profile.vip_tier = 'lifetime'
       OR (
         v_profile.vip_expires_at IS NOT NULL
         AND v_profile.vip_expires_at > now()
         AND (
           v_subscription.current_period_end IS NULL
           OR v_profile.vip_tier IS DISTINCT FROM v_subscription.tier
           OR v_profile.vip_expires_at > v_subscription.current_period_end
         )
       )
     ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'projected', false,
      'state', 'reactivation_entitlement_conflict'
    );
  END IF;

  SELECT * INTO v_other_subscription
    FROM public.vip_subscriptions subscription
   WHERE subscription.user_id = p_user_id
     AND subscription.stripe_subscription_id IS DISTINCT FROM p_stripe_subscription_id
   FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'projected', false,
      'state', 'user_row_conflict'
    );
  END IF;

  IF v_subscription.id IS NULL AND NOT v_has_exact_admission THEN
    RETURN jsonb_build_object(
      'success', false,
      'projected', false,
      'state', 'admission_missing'
    );
  END IF;

  INSERT INTO public.vip_subscriptions(
    user_id,
    stripe_subscription_id,
    stripe_customer_id,
    tier,
    status,
    price_usd,
    current_period_start,
    current_period_end,
    cancel_at_period_end,
    canceled_at,
    updated_at
  ) VALUES (
    p_user_id,
    p_stripe_subscription_id,
    p_stripe_customer_id,
    p_tier,
    p_status,
    p_price_usd,
    p_current_period_start,
    p_current_period_end,
    COALESCE(p_cancel_at_period_end, false),
    p_canceled_at,
    now()
  )
  ON CONFLICT (stripe_subscription_id) DO UPDATE
     SET stripe_customer_id = EXCLUDED.stripe_customer_id,
         tier = EXCLUDED.tier,
         status = EXCLUDED.status,
         price_usd = EXCLUDED.price_usd,
         current_period_start = EXCLUDED.current_period_start,
         current_period_end = EXCLUDED.current_period_end,
         cancel_at_period_end = EXCLUDED.cancel_at_period_end,
         canceled_at = EXCLUDED.canceled_at,
         updated_at = now()
   WHERE public.vip_subscriptions.user_id = EXCLUDED.user_id
  RETURNING id INTO v_projection_id;
  IF v_projection_id IS NULL THEN
    RAISE EXCEPTION 'VIP subscription projection did not write the exact user row';
  END IF;

  IF p_status IN ('active', 'trialing') THEN
    IF v_profile.vip_tier = 'lifetime'
       OR (
         v_profile.vip_expires_at IS NOT NULL
         AND v_profile.vip_expires_at > p_current_period_end
       ) THEN
      UPDATE public.profiles
         SET stripe_customer_id = p_stripe_customer_id,
             is_vip = true,
             updated_at = now()
       WHERE id = p_user_id;
    ELSE
      UPDATE public.profiles
         SET stripe_customer_id = p_stripe_customer_id,
             is_vip = true,
             vip_tier = p_tier,
             vip_expires_at = p_current_period_end,
             updated_at = now()
       WHERE id = p_user_id;
    END IF;
  ELSE
    v_preserve_non_card_entitlement := v_profile.vip_tier = 'lifetime'
      OR (
        v_profile.vip_expires_at IS NOT NULL
        AND v_profile.vip_expires_at > now()
      );
    IF v_preserve_non_card_entitlement THEN
      UPDATE public.profiles
         SET stripe_customer_id = p_stripe_customer_id,
             is_vip = true,
             updated_at = now()
       WHERE id = p_user_id;
    ELSE
      UPDATE public.profiles
         SET stripe_customer_id = p_stripe_customer_id,
             is_vip = false,
             vip_tier = NULL,
             vip_expires_at = NULL,
             updated_at = now()
       WHERE id = p_user_id;
    END IF;
  END IF;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'VIP profile projection matched zero rows while locked';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'projected', true,
    'state', 'projected',
    'stripe_subscription_id', p_stripe_subscription_id,
    'status', p_status
  );
END;
$_$;


ALTER FUNCTION public.apply_vip_subscription_projection(p_user_id uuid, p_stripe_subscription_id text, p_stripe_customer_id text, p_request_id text, p_intent_hash text, p_tier text, p_status text, p_price_usd numeric, p_current_period_start timestamp with time zone, p_current_period_end timestamp with time zone, p_cancel_at_period_end boolean, p_canceled_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION apply_vip_subscription_projection(p_user_id uuid, p_stripe_subscription_id text, p_stripe_customer_id text, p_request_id text, p_intent_hash text, p_tier text, p_status text, p_price_usd numeric, p_current_period_start timestamp with time zone, p_current_period_end timestamp with time zone, p_cancel_at_period_end boolean, p_canceled_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.apply_vip_subscription_projection(p_user_id uuid, p_stripe_subscription_id text, p_stripe_customer_id text, p_request_id text, p_intent_hash text, p_tier text, p_status text, p_price_usd numeric, p_current_period_start timestamp with time zone, p_current_period_end timestamp with time zone, p_cancel_at_period_end boolean, p_canceled_at timestamp with time zone) IS 'marketplace_phase7_vip_acquisition_mutex:v1';


--
-- Name: approve_venue_claim(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approve_venue_claim(p_claim_id uuid, p_admin_user_id uuid, p_admin_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_claim RECORD; v_admin_role text; v_previous_owner uuid;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_admin_user_id THEN 
        RAISE EXCEPTION 'UNAUTHORIZED'; 
    END IF;

    -- Only admins can approve
    SELECT role INTO v_admin_role FROM profiles WHERE id = p_admin_user_id;
    IF v_admin_role IS NULL OR v_admin_role NOT IN ('admin','superadmin','moderator') THEN
        RAISE EXCEPTION 'NOT_ADMIN';
    END IF;

    SELECT id, venue_id, user_id, status INTO v_claim FROM venue_claims
     WHERE id = p_claim_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'CLAIM_NOT_FOUND'; END IF;
    IF v_claim.status NOT IN ('pending','under_review') THEN
        RAISE EXCEPTION 'CLAIM_NOT_ACTIONABLE';
    END IF;

    -- Check if venue already claimed by someone else
    SELECT claimed_by INTO v_previous_owner FROM poker_venues WHERE id = v_claim.venue_id;
    IF v_previous_owner IS NOT NULL AND v_previous_owner <> v_claim.user_id THEN
        RAISE EXCEPTION 'VENUE_ALREADY_CLAIMED_BY_ANOTHER';
    END IF;

    -- Update claim
    UPDATE venue_claims 
       SET status = 'approved', verified_at = now(), 
           verified_by = p_admin_user_id,
           admin_notes = COALESCE(p_admin_notes, admin_notes),
           updated_at = now()
     WHERE id = p_claim_id;

    -- Flip the venue to claimed - this fires trg_venue_claim_wiring which:
    --   (a) auto-creates social_page, and
    --   (b) sets commander_enabled=true
    UPDATE poker_venues
       SET is_claimed = true,
           claimed_by = v_claim.user_id,
           claimed_at = COALESCE(claimed_at, now())
     WHERE id = v_claim.venue_id;

    -- Add claimant as the venue's primary manager
    INSERT INTO venue_managers (
        venue_id, user_id, role,
        can_edit_info, can_edit_hours, can_edit_games, can_post_updates,
        can_respond_reviews, can_manage_promotions, can_view_analytics, can_invite_staff,
        is_active, invited_by
    ) VALUES (
        v_claim.venue_id, v_claim.user_id, 'owner',
        true, true, true, true, true, true, true, true, true, p_admin_user_id
    ) ON CONFLICT DO NOTHING;

    -- Dismiss other pending claims for the same venue
    UPDATE venue_claims
       SET status = 'rejected',
           rejection_reason = 'Another claim was approved first',
           updated_at = now()
     WHERE venue_id = v_claim.venue_id AND id <> p_claim_id 
       AND status IN ('pending','under_review');

    RETURN jsonb_build_object(
        'success', true, 'claim_id', p_claim_id, 'venue_id', v_claim.venue_id,
        'new_owner_id', v_claim.user_id,
        'commander_enabled', true, 'social_page_auto_provisioned', true
    );
END; $$;


ALTER FUNCTION public.approve_venue_claim(p_claim_id uuid, p_admin_user_id uuid, p_admin_notes text) OWNER TO postgres;

--
-- Name: FUNCTION approve_venue_claim(p_claim_id uuid, p_admin_user_id uuid, p_admin_notes text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.approve_venue_claim(p_claim_id uuid, p_admin_user_id uuid, p_admin_notes text) IS 'Phase 29/D: Admin approves a venue claim → auto-fires social_page + commander_enabled via trigger + creates venue_manager row.';


--
-- Name: archive_signup_errors(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archive_signup_errors(older_than_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    moved_count int := 0;
    cutoff timestamptz := now() - (older_than_days || ' days')::interval;
BEGIN
    -- Idempotent: skip rows we've already archived
    WITH moved AS (
        INSERT INTO public.signup_errors_archive
            (original_id, user_id, email, trigger_name, error_code, error_msg,
             raw_meta, occurred_at, forwarded_to_sentry)
        SELECT id, user_id, email, trigger_name, error_code, error_msg,
               raw_meta, occurred_at, forwarded_to_sentry
        FROM public.signup_errors
        WHERE occurred_at < cutoff
          AND NOT EXISTS (
              SELECT 1 FROM public.signup_errors_archive a
              WHERE a.original_id = signup_errors.id
          )
        RETURNING original_id
    )
    DELETE FROM public.signup_errors WHERE id IN (SELECT original_id FROM moved);

    GET DIAGNOSTICS moved_count = ROW_COUNT;

    RETURN jsonb_build_object(
        'moved', moved_count,
        'cutoff', cutoff,
        'older_than_days', older_than_days
    );
END;
$$;


ALTER FUNCTION public.archive_signup_errors(older_than_days integer) OWNER TO postgres;

--
-- Name: FUNCTION archive_signup_errors(older_than_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.archive_signup_errors(older_than_days integer) IS 'Moves signup_errors rows older than N days (default 30) to signup_errors_archive. Idempotent — safe to run repeatedly. Returns jsonb with count moved.';


--
-- Name: assign_home_game_seat(uuid, integer, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assign_home_game_seat(p_game_id uuid, p_seat_number integer, p_user_id uuid, p_player_name text DEFAULT NULL::text, p_caller_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_game RECORD;
  v_group RECORD;
  v_resolved_name text;
  v_new_status text;
  v_new_seated_at timestamptz;
BEGIN
  IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
    RAISE EXCEPTION 'UNAUTHORIZED';
  END IF;
  IF p_seat_number < 1 OR p_seat_number > 20 THEN
    RAISE EXCEPTION 'INVALID_SEAT_NUMBER';
  END IF;

  SELECT * INTO v_game FROM public.commander_home_games WHERE id = p_game_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
  IF v_game.status NOT IN ('scheduled','confirmed','in_progress') THEN
    RAISE EXCEPTION 'GAME_NOT_ACTIVE';
  END IF;

  SELECT * INTO v_group FROM public.commander_home_groups WHERE id = v_game.group_id;

  IF v_game.host_id <> p_caller_user_id
     AND v_group.owner_id <> p_caller_user_id
     AND NOT EXISTS (
       SELECT 1 FROM public.commander_home_members
        WHERE group_id = v_game.group_id AND user_id = p_caller_user_id
          AND role = 'admin' AND status = 'approved'
     )
  THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED';
  END IF;

  IF p_seat_number > COALESCE(v_game.max_players, 9) THEN
    RAISE EXCEPTION 'SEAT_EXCEEDS_MAX_PLAYERS';
  END IF;

  v_resolved_name := COALESCE(
    p_player_name,
    (SELECT COALESCE(display_name, full_name, username) FROM public.profiles WHERE id = p_user_id)
  );
  v_new_status := CASE WHEN p_user_id IS NULL THEN 'empty' ELSE 'seated' END;
  v_new_seated_at := CASE WHEN p_user_id IS NULL THEN NULL ELSE NOW() END;

  -- FIX: match the legacy partial unique index
  --   UNIQUE(game_id, seat_number) WHERE table_id IS NULL
  INSERT INTO public.commander_home_seats
    (game_id, seat_number, user_id, player_name, status, seated_at)
  VALUES
    (p_game_id, p_seat_number, p_user_id, v_resolved_name, v_new_status, v_new_seated_at)
  ON CONFLICT (game_id, seat_number) WHERE table_id IS NULL
  DO UPDATE
    SET user_id     = EXCLUDED.user_id,
        player_name = EXCLUDED.player_name,
        status      = EXCLUDED.status,
        seated_at   = EXCLUDED.seated_at,
        away_since  = NULL,
        updated_at  = NOW();

  RETURN jsonb_build_object(
    'success', true,
    'seat_number', p_seat_number,
    'user_id', p_user_id
  );
END;
$$;


ALTER FUNCTION public.assign_home_game_seat(p_game_id uuid, p_seat_number integer, p_user_id uuid, p_player_name text, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION assign_home_game_seat(p_game_id uuid, p_seat_number integer, p_user_id uuid, p_player_name text, p_caller_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.assign_home_game_seat(p_game_id uuid, p_seat_number integer, p_user_id uuid, p_player_name text, p_caller_user_id uuid) IS 'Phase 40: race-safe via INSERT ... ON CONFLICT DO UPDATE. Staff can override any seat state intentionally. (game_id, user_id) unique index prevents a user from being double-seated.';


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: user_daily_challenges; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.user_daily_challenges (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    challenge_id text NOT NULL,
    assigned_date text DEFAULT CURRENT_DATE NOT NULL,
    progress integer DEFAULT 0 NOT NULL,
    completed boolean DEFAULT false NOT NULL,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    claimed boolean DEFAULT false NOT NULL,
    claimed_at timestamp with time zone,
    challenge_name_snapshot text NOT NULL,
    challenge_description_snapshot text NOT NULL,
    challenge_type_snapshot text NOT NULL,
    tier_snapshot text NOT NULL,
    requirement_snapshot integer NOT NULL,
    chip_reward_snapshot numeric NOT NULL,
    diamond_reward_snapshot integer NOT NULL,
    threshold_snapshot integer,
    expired_at timestamp with time zone,
    CONSTRAINT user_daily_challenges_chip_reward_snapshot_nonnegative CHECK ((chip_reward_snapshot >= (0)::numeric)),
    CONSTRAINT user_daily_challenges_diamond_reward_snapshot_nonnegative CHECK ((diamond_reward_snapshot >= 0)),
    CONSTRAINT user_daily_challenges_requirement_snapshot_positive CHECK ((requirement_snapshot > 0))
);


ALTER TABLE public.user_daily_challenges OWNER TO postgres;

--
-- Name: COLUMN user_daily_challenges.chip_reward_snapshot; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.user_daily_challenges.chip_reward_snapshot IS 'DEAD SINCE 2026-09-05, AND DELIBERATELY NOT ZEROED. Held 695,783,800 chips across 32,793 assigned rows - 425,819,000 of them completed and one "claim all" from being minted, against ~121M chips in every member wallet combined. No row was ever claimed, so none was ever paid. It is not rewritten because fn_snapshot_daily_challenge_contract makes an assigned contract immutable, which is correct: the fix is that nothing pays chips any more. Read nothing from this column; diamond_reward_snapshot is the reward.';


--
-- Name: COLUMN user_daily_challenges.expired_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.user_daily_challenges.expired_at IS 'Set when a completed reward passed its seven-day claim window unclaimed (ruling 3). Both claim paths refuse by the clock regardless; this is what the dashboard reads.';


--
-- Name: assign_user_challenges(text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assign_user_challenges(p_assigned_date text, p_challenge_ids text[]) RETURNS SETOF public.user_daily_challenges
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_today text := to_char((now() AT TIME ZONE 'utc')::date, 'YYYY-MM-DD');
  v_week text := 'W' || to_char(date_trunc('week', now() AT TIME ZONE 'utc')::date, 'YYYY-MM-DD');
  v_month text := 'M' || to_char(now() AT TIME ZONE 'utc', 'YYYY-MM');
  v_tier text;
  v_count integer;
BEGIN
  IF v_uid IS NULL AND public.fn_caller_is_engine() THEN v_uid := NULLIF(current_setting('app.challenge_user_id', true), '')::uuid; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000'; END IF;

  IF p_assigned_date = v_today THEN v_tier := 'daily'; v_count := 5;
  ELSIF p_assigned_date = v_week THEN v_tier := 'weekly'; v_count := 3;
  ELSIF p_assigned_date = v_month THEN v_tier := 'monthly'; v_count := 2;
  ELSE RAISE EXCEPTION 'Only the current UTC Daily Missions period may be assigned';
  END IF;

  -- p_challenge_ids remains in the signature for deployed-client compatibility,
  -- but the server owns the draw and never reads caller-selected IDs.
  PERFORM public.fn_assign_current_challenge_period(v_uid, v_tier, p_assigned_date, v_count);
  RETURN QUERY SELECT * FROM public.user_daily_challenges
    WHERE user_id = v_uid AND assigned_date = p_assigned_date
    ORDER BY created_at, id;
END;
$$;


ALTER FUNCTION public.assign_user_challenges(p_assigned_date text, p_challenge_ids text[]) OWNER TO postgres;

--
-- Name: atomic_cancel_tournament(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_cancel_tournament(p_tournament_id uuid, p_admin_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_uid uuid:=auth.uid();
  v_managed_close_owned boolean:=false;
  v_token uuid;
  v_result jsonb;
BEGIN
  -- The authenticated managed-game gateway inserts this exact processing
  -- receipt in the same transaction before its private close function reaches
  -- us. An uncommitted receipt from another backend is invisible, so this is
  -- a transaction-bound capability rather than a caller-controlled flag.
  v_managed_close_owned:=
    COALESCE(current_setting('app.managed_game_lifecycle',true),'')='on'
    AND v_uid IS NOT NULL
    AND p_admin_id IS NOT DISTINCT FROM v_uid
    AND EXISTS (
      SELECT 1 FROM public.managed_game_command_receipts r
       WHERE r.actor_id=v_uid
         AND r.game_kind='tournament'
         AND r.game_id=p_tournament_id
         AND r.command_action='close'
         AND r.status='processing');
  IF NOT public.fn_caller_is_engine()
     AND NOT v_managed_close_owned THEN
    RAISE EXCEPTION 'atomic_cancel_tournament requires service authority'
      USING ERRCODE='28000';
  END IF;
  v_token:=public.fn_ca_open_tournament_seat_exit_authority(
    p_tournament_id,'cancel',NULL);
  BEGIN
    v_result:=public.atomic_cancel_tournament_pre_seat_guard(
      p_tournament_id,p_admin_id);
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(
      v_token,COALESCE((v_result->>'success')::boolean,false));
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
    RAISE;
  END;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.atomic_cancel_tournament(p_tournament_id uuid, p_admin_id uuid) OWNER TO postgres;

--
-- Name: atomic_cancel_tournament_pre_seat_guard(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_cancel_tournament_pre_seat_guard(p_tournament_id uuid, p_admin_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_actor uuid := COALESCE(
    auth.uid(),p_admin_id,'2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);
  v_t public.tournaments%ROWTYPE;
  v_stored public.tournament_cancellation_receipts%ROWTYPE;
  v_e public.tournament_escrow%ROWTYPE;
  v_player record;
  v_entitlement public.tournament_refund_entitlements%ROWTYPE;
  v_fee record;
  v_contribution public.spin_reserve_ledger%ROWTYPE;
  v_draw public.spin_reserve_ledger%ROWTYPE;
  v_pool public.spin_bonus_pools%ROWTYPE;
  v_settle jsonb;
  v_ticket jsonb;
  v_receipt jsonb;
  v_refunds jsonb := '[]'::jsonb;
  v_ticket_returns jsonb := '[]'::jsonb;
  v_source_player_ids uuid[] := ARRAY[]::uuid[];
  v_refunded_registration_ids uuid[] := ARRAY[]::uuid[];
  v_ticket_return_ids uuid[] := ARRAY[]::uuid[];
  v_zero_refund_registration_ids uuid[] := ARRAY[]::uuid[];
  v_closed_table_ids uuid[] := ARRAY[]::uuid[];
  v_source_seat_ids uuid[] := ARRAY[]::uuid[];
  v_released_seat_ids uuid[] := ARRAY[]::uuid[];
  v_fee_reversal_ids uuid[] := ARRAY[]::uuid[];
  v_registration_id uuid;
  v_fee_reversal_id uuid;
  v_original_entry_journal_id uuid;
  v_original_draw_journal_id uuid;
  v_draw_reversal_id uuid;
  v_draw_reversal_journal_id uuid;
  v_contribution_reversal_id uuid;
  v_contribution_reversal_journal_id uuid;
  v_spin_unwind_id uuid;
  v_source_player_count integer := 0;
  v_refunded_count integer := 0;
  v_refund_line_count integer := 0;
  v_ticket_return_count integer := 0;
  v_zero_refund_count integer := 0;
  v_closed_table_count integer := 0;
  v_source_seat_count integer := 0;
  v_released_seat_count integer := 0;
  v_total_refunded numeric := 0;
  v_total_ticket_returned numeric := 0;
  v_fees_reversed numeric := 0;
  v_total_rake_before numeric := 0;
  v_total_rake_after numeric := 0;
  v_total_owed numeric;
  v_draw_amount numeric := 0;
  v_pool_balance_before numeric;
  v_pool_balance_after numeric;
  v_rows integer;
  v_journal_count integer;
  v_cancelled_at timestamptz := transaction_timestamp();
  v_close_note constant text := 'atomic cancellation receipt: exact zero';
BEGIN
  -- Every terminal authority takes this lock before any row lock. Cancellation,
  -- satellite finish and cash finish can touch the same wallets and event rows.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'Tournament id is required' USING ERRCODE = '22004';
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_uid IS NOT NULL
     AND NOT public.fn_can_create_games(v_t.club_id,v_uid) THEN
    RAISE EXCEPTION 'Only the governed game operator may cancel a tournament'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_stored FROM public.tournament_cancellation_receipts h
   WHERE h.tournament_id=p_tournament_id FOR UPDATE;
  IF FOUND THEN
    RETURN public.fn_ca_tournament_cancellation_receipt(p_tournament_id,NULL);
  END IF;
  IF upper(COALESCE(v_t.status::text,'')) IN
       ('COMPLETED','CANCELLED','CANCELED','COMPLETING') THEN
    RAISE EXCEPTION 'Tournament is already %',v_t.status USING ERRCODE='55000';
  END IF;

  -- Freeze every identity before any payer runs. Any concurrent registration,
  -- seat move or hand settlement either committed before these locks and is in
  -- the receipt, or waits behind this transaction and sees a terminal parent.
  PERFORM 1 FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
   ORDER BY tp.user_id,tp.id FOR UPDATE;
  PERFORM 1 FROM public.tables tb
   WHERE tb.tournament_id=p_tournament_id ORDER BY tb.id FOR UPDATE;
  PERFORM 1 FROM public.table_seats s
   JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
   ORDER BY s.table_id,s.id FOR UPDATE OF s;
  SELECT COALESCE(array_agg(tp.id ORDER BY tp.id),ARRAY[]::uuid[])
    INTO v_source_player_ids FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id;
  SELECT COALESCE(array_agg(tb.id ORDER BY tb.id),ARRAY[]::uuid[])
    INTO v_closed_table_ids FROM public.tables tb
   WHERE tb.tournament_id=p_tournament_id;
  SELECT COALESCE(array_agg(s.id ORDER BY s.table_id,s.id),ARRAY[]::uuid[])
    INTO v_source_seat_ids FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id;
  v_source_player_count := cardinality(v_source_player_ids);
  v_closed_table_count := cardinality(v_closed_table_ids);
  v_source_seat_count := cardinality(v_source_seat_ids);

  PERFORM public.fn_ca_escrow_apply(
    p_tournament_id,'atomic cancellation escrow prelock');
  SELECT * INTO v_e FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id FOR UPDATE;
  IF v_e.tournament_id IS NULL OR v_e.enforced IS DISTINCT FROM true
     OR v_t.prize_pool IS DISTINCT FROM v_e.prize_balance
     OR v_t.bounty_pool IS DISTINCT FROM v_e.bounty_balance
     OR v_t.total_rake IS DISTINCT FROM v_e.fee_balance THEN
    RAISE EXCEPTION 'tournament % caches do not equal exact escrow before cancellation',
      p_tournament_id USING ERRCODE='P0404';
  END IF;

  -- A booked Spin first gives back its draw, then withdraws this event's own
  -- contribution. Each pool movement creates its strict journal before the
  -- matching immutable reversal row and all four ids are stored together.
  PERFORM 1 FROM public.spin_reserve_ledger r
   WHERE r.tournament_id=p_tournament_id ORDER BY r.created_at,r.id FOR UPDATE;
  SELECT * INTO v_contribution FROM public.spin_reserve_ledger r
   WHERE r.tournament_id=p_tournament_id AND r.kind='contribution';
  IF FOUND THEN
    IF (SELECT count(*) FROM public.spin_reserve_ledger r
         WHERE r.tournament_id=p_tournament_id AND r.kind='contribution') <> 1
       OR EXISTS (SELECT 1 FROM public.spin_reserve_ledger r
                   WHERE r.tournament_id=p_tournament_id
                     AND r.kind IN ('draw_reversal','contribution_reversal'))
       OR EXISTS (SELECT 1 FROM public.tournament_spin_cancellation_unwinds u
                   WHERE u.tournament_id=p_tournament_id) THEN
      RAISE EXCEPTION 'Spin % has an ambiguous or partially unwound reserve contract',
        p_tournament_id USING ERRCODE='P0404';
    END IF;
    SELECT * INTO v_draw FROM public.spin_reserve_ledger r
     WHERE r.tournament_id=p_tournament_id AND r.kind='jackpot_draw';
    IF FOUND AND (SELECT count(*) FROM public.spin_reserve_ledger r
                   WHERE r.tournament_id=p_tournament_id
                     AND r.kind='jackpot_draw') <> 1 THEN
      RAISE EXCEPTION 'Spin % has more than one immutable draw',p_tournament_id
        USING ERRCODE='P0404';
    END IF;
    SELECT * INTO v_pool FROM public.spin_bonus_pools p
     WHERE p.club_id=v_contribution.club_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Spin % original reserve owner is missing',p_tournament_id
        USING ERRCODE='P0404';
    END IF;
    v_pool_balance_before := v_pool.balance;
    IF v_pool_balance_before IS NULL
       OR v_pool_balance_before::text IN ('NaN','Infinity','-Infinity')
       OR v_pool_balance_before<0 THEN
      RAISE EXCEPTION 'Spin % reserve balance is invalid',p_tournament_id
        USING ERRCODE='22003';
    END IF;
    SELECT count(*),(array_agg(l.id ORDER BY l.created_at,l.id))[1]
      INTO v_journal_count,v_original_entry_journal_id
      FROM public.chip_ledger l
     WHERE l.tournament_id=p_tournament_id
       AND l.category='spin_entry'
       AND l.from_type='prize_liability'
       AND l.from_entity_id=p_tournament_id
       AND l.to_type='spin_reserve' AND l.to_entity_id=v_pool.id
       AND l.amount=v_contribution.amount;
    IF v_journal_count<>1 OR v_contribution.amount<=0 THEN
      RAISE EXCEPTION 'Spin % contribution has no single exact journal',p_tournament_id
        USING ERRCODE='P0404';
    END IF;

    IF v_draw.id IS NOT NULL THEN
      IF v_draw.club_id IS DISTINCT FROM v_contribution.club_id
         OR v_draw.amount>=0 THEN
        RAISE EXCEPTION 'Spin % draw disagrees with its contribution owner',p_tournament_id
          USING ERRCODE='P0404';
      END IF;
      v_draw_amount := round(-v_draw.amount,2);
      SELECT count(*),(array_agg(l.id ORDER BY l.created_at,l.id))[1]
        INTO v_journal_count,v_original_draw_journal_id
        FROM public.chip_ledger l
       WHERE l.tournament_id=p_tournament_id
         AND l.category='spin_prize'
         AND l.from_type='spin_reserve' AND l.from_entity_id=v_pool.id
         AND l.to_type='prize_liability' AND l.to_entity_id=p_tournament_id
         AND l.amount=v_draw_amount;
      IF v_journal_count<>1 THEN
        RAISE EXCEPTION 'Spin % draw has no single exact journal',p_tournament_id
          USING ERRCODE='P0404';
      END IF;
      PERFORM public.fn_ca_declare_ledger(
        'reversal','prize_liability',p_tournament_id,NULL,
        'spin:'||p_tournament_id::text||':cancel:draw',NULL);
      UPDATE public.spin_bonus_pools
         SET balance=balance+v_draw_amount,updated_at=now()
       WHERE id=v_pool.id RETURNING balance INTO v_pool_balance_after;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Spin % reserve vanished during draw reversal',p_tournament_id
          USING ERRCODE='40001';
      END IF;
      INSERT INTO public.spin_reserve_ledger
        (club_id,tournament_id,kind,amount,balance_after,multiplier,
         buy_in,seats,house_rake,note)
      VALUES
        (v_draw.club_id,p_tournament_id,'draw_reversal',v_draw_amount,
         v_pool_balance_after,v_draw.multiplier,v_draw.buy_in,v_draw.seats,
         v_draw.house_rake,'atomic cancellation reversed the exact reserve draw')
      RETURNING id INTO v_draw_reversal_id;
      SELECT count(*),(array_agg(l.id ORDER BY l.created_at,l.id))[1]
        INTO v_journal_count,v_draw_reversal_journal_id
        FROM public.chip_ledger l
       WHERE l.idempotency_key='spin:'||p_tournament_id::text||':cancel:draw'
         AND l.tournament_id=p_tournament_id AND l.category='reversal'
         AND l.from_type='prize_liability' AND l.from_entity_id=p_tournament_id
         AND l.to_type='spin_reserve' AND l.to_entity_id=v_pool.id
         AND l.amount=v_draw_amount;
      IF v_journal_count<>1 THEN
        RAISE EXCEPTION 'Spin % draw reversal has no single exact journal',p_tournament_id
          USING ERRCODE='P0404';
      END IF;
    ELSE
      v_pool_balance_after := v_pool_balance_before;
    END IF;

    IF v_pool_balance_after<v_contribution.amount THEN
      RAISE EXCEPTION 'Spin % reserve cannot return its own contribution',p_tournament_id
        USING ERRCODE='P0403';
    END IF;
    PERFORM public.fn_ca_declare_ledger(
      'reversal','prize_liability',p_tournament_id,NULL,
      'spin:'||p_tournament_id::text||':cancel:entry',NULL);
    UPDATE public.spin_bonus_pools
       SET balance=balance-v_contribution.amount,updated_at=now()
     WHERE id=v_pool.id RETURNING balance INTO v_pool_balance_after;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Spin % reserve vanished during contribution reversal',p_tournament_id
        USING ERRCODE='40001';
    END IF;
    INSERT INTO public.spin_reserve_ledger
      (club_id,tournament_id,kind,amount,balance_after,multiplier,
       buy_in,seats,house_rake,note)
    VALUES
      (v_contribution.club_id,p_tournament_id,'contribution_reversal',
       -v_contribution.amount,v_pool_balance_after,v_contribution.multiplier,
       v_contribution.buy_in,v_contribution.seats,v_contribution.house_rake,
       'atomic cancellation returned the exact entry contribution')
    RETURNING id INTO v_contribution_reversal_id;
    SELECT count(*),(array_agg(l.id ORDER BY l.created_at,l.id))[1]
      INTO v_journal_count,v_contribution_reversal_journal_id
      FROM public.chip_ledger l
     WHERE l.idempotency_key='spin:'||p_tournament_id::text||':cancel:entry'
       AND l.tournament_id=p_tournament_id AND l.category='reversal'
       AND l.from_type='spin_reserve' AND l.from_entity_id=v_pool.id
       AND l.to_type='prize_liability' AND l.to_entity_id=p_tournament_id
       AND l.amount=v_contribution.amount;
    IF v_journal_count<>1 THEN
      RAISE EXCEPTION 'Spin % contribution reversal has no single exact journal',
        p_tournament_id USING ERRCODE='P0404';
    END IF;
    INSERT INTO public.tournament_spin_cancellation_unwinds(
      tournament_id,pool_id,reserve_owner_id,
      original_contribution_id,original_draw_id,
      original_entry_journal_id,original_draw_journal_id,
      draw_reversal_id,draw_reversal_journal_id,
      contribution_reversal_id,contribution_reversal_journal_id,
      contribution_amount,draw_amount,pool_balance_before,pool_balance_after,
      settled_at)
    VALUES(
      p_tournament_id,v_pool.id,v_contribution.club_id,
      v_contribution.id,v_draw.id,
      v_original_entry_journal_id,v_original_draw_journal_id,
      v_draw_reversal_id,v_draw_reversal_journal_id,
      v_contribution_reversal_id,v_contribution_reversal_journal_id,
      v_contribution.amount,v_draw_amount,v_pool_balance_before,
      v_pool_balance_after,v_cancelled_at)
    RETURNING tournament_id INTO v_spin_unwind_id;
  ELSIF EXISTS (
    SELECT 1 FROM public.spin_reserve_ledger r
     WHERE r.tournament_id=p_tournament_id
       AND r.kind IN ('jackpot_draw','draw_reversal','contribution_reversal')) THEN
    RAISE EXCEPTION 'Spin % has reserve evidence without its contribution',p_tournament_id
      USING ERRCODE='P0404';
  END IF;

  -- Consume one immutable entitlement at a time. Wallet charges go back as
  -- chips to their exact source club. A satellite-funded seat or spent entry
  -- ticket is not chips: it becomes a tournament-entry-only ticket carrying
  -- the same immutable rails and original satellite identity.
  IF EXISTS (
    SELECT 1 FROM public.tournament_refund_entitlements e
    JOIN public.tournament_players tp ON tp.id=e.registration_id
    JOIN public.tournament_tickets tk
      ON tk.source_refund_entitlement_id=e.id
   WHERE e.tournament_id=p_tournament_id
     AND tp.tournament_id=p_tournament_id) THEN
    RAISE EXCEPTION 'active qualifier roster already has an unreceipted return ticket'
      USING ERRCODE='P0404';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_refund_entitlements e
    LEFT JOIN public.tournament_players tp
      ON tp.tournament_id=e.tournament_id AND tp.user_id=e.user_id
   WHERE e.tournament_id=p_tournament_id
     AND (tp.id IS NULL OR (e.entitlement_kind IN (
            'satellite_seat','tournament_ticket')
          AND e.registration_id IS DISTINCT FROM tp.id))) THEN
    RAISE EXCEPTION 'refund entitlement is detached from the frozen roster'
      USING ERRCODE='P0404';
  END IF;
  FOR v_player IN
    SELECT DISTINCT ON (tp.user_id) tp.id,tp.user_id
      FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id IS NOT NULL
     ORDER BY tp.user_id,tp.id
  LOOP
    -- The owner-only plan validates every source ledger, wallet debit and
    -- escrow rail. Identity comes from the locked entitlement table below.
    PERFORM 1 FROM public.fn_ca_tournament_refund_plan(
      p_tournament_id,v_player.user_id);
    LOOP
      SELECT e.* INTO v_entitlement
        FROM public.tournament_refund_entitlements e
       WHERE e.tournament_id=p_tournament_id
         AND e.user_id=v_player.user_id
         AND NOT EXISTS (
           SELECT 1 FROM public.tournament_refund_tranches tr
            WHERE tr.entitlement_id=e.id)
         AND NOT EXISTS (
           SELECT 1 FROM public.tournament_tickets tk
            WHERE tk.source_refund_entitlement_id=e.id)
       ORDER BY e.entitlement_kind,e.id
       LIMIT 1 FOR UPDATE OF e;
      EXIT WHEN NOT FOUND;
      v_registration_id:=COALESCE(v_entitlement.registration_id,v_player.id);
      IF v_entitlement.entitlement_kind='wallet_charge' THEN
        SELECT COALESCE(o.amount_paid,0)+v_entitlement.gross
          INTO v_total_owed FROM public.tournament_obligations o
         WHERE o.tournament_id=p_tournament_id AND o.kind='refund'
           AND o.place IS NULL AND o.user_id=v_player.user_id FOR UPDATE;
        IF NOT FOUND THEN v_total_owed:=v_entitlement.gross; END IF;
        v_settle:=public.fn_settle_tournament_refund_exact(
          p_tournament_id,v_player.user_id,
          v_entitlement.refund_wallet_club_id,v_total_owed,
          v_entitlement.refund_prize,v_entitlement.refund_bounty,
          v_entitlement.refund_fee,'atomic_cancel_tournament',
          'Tournament cancellation refund: '||COALESCE(v_t.name,'Unknown'));
        IF COALESCE((v_settle->>'ok')::boolean,false) IS NOT TRUE
           OR COALESCE((v_settle->>'fully_settled')::boolean,false) IS NOT TRUE
           OR COALESCE((v_settle->>'remaining')::numeric,-1)<>0
           OR (v_settle->>'entitlement_id')::uuid
                IS DISTINCT FROM v_entitlement.id
           OR v_settle->>'entitlement_kind' IS DISTINCT FROM 'wallet_charge'
           OR (v_settle->>'paid')::numeric IS DISTINCT FROM v_entitlement.gross
           OR (v_settle->>'refund_prize')::numeric
                IS DISTINCT FROM v_entitlement.refund_prize
           OR (v_settle->>'refund_bounty')::numeric
                IS DISTINCT FROM v_entitlement.refund_bounty
           OR (v_settle->>'refund_fee')::numeric
                IS DISTINCT FROM v_entitlement.refund_fee THEN
          RAISE EXCEPTION 'exact cancellation refund refused entitlement %: %',
            v_entitlement.id,v_settle USING ERRCODE='55000';
        END IF;
        v_refunds:=v_refunds||jsonb_build_array(jsonb_build_object(
          'registration_id',v_registration_id,
          'user_id',v_player.user_id,
          'entitlement_id',v_entitlement.id,
          'entitlement_kind','wallet_charge',
          'source_wallet_club_id',v_entitlement.refund_wallet_club_id,
          'gross_paid',v_entitlement.gross,
          'amount_paid_before',(v_settle->>'already_paid')::numeric,
          'amount_paid_now',(v_settle->>'paid')::numeric,
          'refund_prize',(v_settle->>'refund_prize')::numeric,
          'refund_bounty',(v_settle->>'refund_bounty')::numeric,
          'refund_fee',(v_settle->>'refund_fee')::numeric,
          'obligation_id',(v_settle->>'obligation_id')::uuid,
          'idempotency_key',v_settle->>'idempotency_key',
          'credit_ledger_id',(v_settle->>'credit_ledger_id')::uuid,
          'wallet_transaction_id',(v_settle->>'wallet_transaction_id')::uuid));
        v_refund_line_count:=v_refund_line_count+1;
        v_total_refunded:=round(
          v_total_refunded+(v_settle->>'paid')::numeric,2);
      ELSIF v_entitlement.entitlement_kind IN (
          'satellite_seat','tournament_ticket') THEN
        v_ticket:=public.fn_ca_return_satellite_entitlement_as_ticket(
          v_entitlement.id,'atomic_cancel_tournament',
          'Cancelled tournament seat returned as entry ticket: '
            ||COALESCE(v_t.name,'Unknown'));
        IF COALESCE((v_ticket->>'ok')::boolean,false) IS NOT TRUE
           OR COALESCE((v_ticket->>'replayed')::boolean,true) IS NOT FALSE
           OR (v_ticket->>'entitlement_id')::uuid
                IS DISTINCT FROM v_entitlement.id
           OR (v_ticket->>'value')::numeric IS DISTINCT FROM v_entitlement.gross
           OR (v_ticket->>'refund_prize')::numeric
                IS DISTINCT FROM v_entitlement.refund_prize
           OR (v_ticket->>'refund_bounty')::numeric
                IS DISTINCT FROM v_entitlement.refund_bounty
           OR (v_ticket->>'refund_fee')::numeric
                IS DISTINCT FROM v_entitlement.refund_fee
           OR (v_ticket->>'refund_wallet_club_id')::uuid
                IS DISTINCT FROM v_entitlement.refund_wallet_club_id
           OR NULLIF(v_ticket->>'ticket_id','') IS NULL
           OR NULLIF(v_ticket->>'ledger_id','') IS NULL
           OR NULLIF(v_ticket->>'transaction_id','') IS NULL THEN
          RAISE EXCEPTION 'satellite ticket return refused entitlement %: %',
            v_entitlement.id,v_ticket USING ERRCODE='55000';
        END IF;
        v_ticket_return_ids:=array_append(
          v_ticket_return_ids,(v_ticket->>'ticket_id')::uuid);
        v_ticket_returns:=v_ticket_returns||jsonb_build_array(jsonb_build_object(
          'registration_id',v_registration_id,
          'user_id',v_player.user_id,
          'entitlement_id',v_entitlement.id,
          'entitlement_kind',v_entitlement.entitlement_kind,
          'ticket_id',(v_ticket->>'ticket_id')::uuid,
          'value',(v_ticket->>'value')::numeric,
          'source_wallet_club_id',v_entitlement.refund_wallet_club_id,
          'source_satellite_id',v_entitlement.source_satellite_id,
          'refund_prize',(v_ticket->>'refund_prize')::numeric,
          'refund_bounty',(v_ticket->>'refund_bounty')::numeric,
          'refund_fee',(v_ticket->>'refund_fee')::numeric,
          'ledger_id',(v_ticket->>'ledger_id')::uuid,
          'transaction_id',(v_ticket->>'transaction_id')::uuid));
        v_ticket_return_count:=v_ticket_return_count+1;
        v_total_ticket_returned:=round(
          v_total_ticket_returned+(v_ticket->>'value')::numeric,2);
      ELSE
        RAISE EXCEPTION 'unknown cancellation entitlement kind %',
          v_entitlement.entitlement_kind USING ERRCODE='P0404';
      END IF;
      IF NOT v_registration_id=ANY(v_refunded_registration_ids) THEN
        v_refunded_registration_ids:=array_append(
          v_refunded_registration_ids,v_registration_id);
      END IF;
    END LOOP;
  END LOOP;
  SELECT COALESCE(array_agg(id ORDER BY id),ARRAY[]::uuid[])
    INTO v_refunded_registration_ids
    FROM unnest(v_refunded_registration_ids) ids(id);
  SELECT COALESCE(array_agg(id ORDER BY id),ARRAY[]::uuid[])
    INTO v_zero_refund_registration_ids
    FROM unnest(v_source_player_ids) ids(id)
   WHERE NOT id=ANY(v_refunded_registration_ids);
  v_refunded_count:=cardinality(v_refunded_registration_ids);
  v_zero_refund_count:=cardinality(v_zero_refund_registration_ids);

  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.fn_ca_tournament_refund_plan(
                    p_tournament_id,tp.user_id))) THEN
    RAISE EXCEPTION 'cancellation left a refundable entitlement unpaid'
      USING ERRCODE='55000';
  END IF;

  -- Rake reversal is attribution only: the exact refund payer already returned
  -- the fee component from escrow. Reverse each current player's net fee and
  -- each aggregate Spin source exactly once, retaining immutable source ids.
  IF EXISTS (SELECT 1 FROM public.rake_records r
              WHERE r.tournament_id=p_tournament_id
                AND r.source='atomic_cancel_tournament') THEN
    RAISE EXCEPTION 'unreceipted cancellation rake evidence already exists'
      USING ERRCODE='P0404';
  END IF;
  SELECT round(COALESCE(sum(r.rake_amount),0),2)
    INTO v_total_rake_before FROM public.rake_records r
   WHERE r.tournament_id=p_tournament_id AND r.is_tournament;
  IF v_total_rake_before<0
     OR v_total_rake_before::text IN ('NaN','Infinity','-Infinity')
     OR round(COALESCE(v_t.total_rake,0),2) IS DISTINCT FROM v_total_rake_before THEN
    RAISE EXCEPTION 'tournament % rake cache and evidence disagree',p_tournament_id
      USING ERRCODE='P0404';
  END IF;

  FOR v_fee IN
    SELECT tp.user_id,r.club_id,
           round(sum(r.rake_amount),2) AS amount,
           jsonb_agg(r.id ORDER BY r.id) AS source_ids
      FROM (SELECT DISTINCT p.user_id FROM public.tournament_players p
             WHERE p.tournament_id=p_tournament_id AND p.user_id IS NOT NULL) tp
      JOIN public.rake_records r
        ON r.tournament_id=p_tournament_id AND r.is_tournament
       AND r.metadata->>'user_id'=tp.user_id::text
     GROUP BY tp.user_id,r.club_id HAVING round(sum(r.rake_amount),2)>0
     ORDER BY tp.user_id,r.club_id
  LOOP
    INSERT INTO public.rake_records(
      hand_id,table_id,club_id,rake_amount,pot_size,num_players,
      bbj_contribution,is_tournament,tournament_id,source,metadata)
    VALUES(NULL,NULL,v_fee.club_id,-v_fee.amount,v_fee.amount,1,0,true,
      p_tournament_id,'atomic_cancel_tournament',jsonb_build_object(
        'kind','tournament_fee_refund','user_id',v_fee.user_id,
        'original_rake_record_ids',v_fee.source_ids))
    RETURNING id INTO v_fee_reversal_id;
    v_fee_reversal_ids:=array_append(v_fee_reversal_ids,v_fee_reversal_id);
    v_fees_reversed:=round(v_fees_reversed+v_fee.amount,2);
  END LOOP;
  FOR v_fee IN
    SELECT r.*,round(r.rake_amount+COALESCE((SELECT sum(rr.rake_amount)
      FROM public.rake_records rr WHERE rr.tournament_id=p_tournament_id
       AND rr.source='atomic_cancel_tournament'
       AND rr.metadata->>'original_rake_record_id'=r.id::text),0),2) AS amount
      FROM public.rake_records r
     WHERE r.tournament_id=p_tournament_id AND r.is_tournament
       AND r.source IN ('fn_spin_book_entry','fn_spin_settle_game')
       AND r.rake_amount>0 AND NULLIF(r.metadata->>'user_id','') IS NULL
     ORDER BY r.id FOR UPDATE
  LOOP
    IF v_fee.amount>0 THEN
      INSERT INTO public.rake_records(
        hand_id,table_id,club_id,rake_amount,pot_size,num_players,
        bbj_contribution,is_tournament,tournament_id,source,
        player_contributions,metadata)
      VALUES(NULL,NULL,v_fee.club_id,-v_fee.amount,v_fee.pot_size,
        v_fee.num_players,0,true,p_tournament_id,'atomic_cancel_tournament',
        v_fee.player_contributions,jsonb_build_object(
          'kind','spin_rake_refund','original_source',v_fee.source,
          'original_rake_record_id',v_fee.id))
      RETURNING id INTO v_fee_reversal_id;
      v_fee_reversal_ids:=array_append(v_fee_reversal_ids,v_fee_reversal_id);
      v_fees_reversed:=round(v_fees_reversed+v_fee.amount,2);
    END IF;
  END LOOP;
  SELECT round(COALESCE(sum(r.rake_amount),0),2)
    INTO v_total_rake_after FROM public.rake_records r
   WHERE r.tournament_id=p_tournament_id AND r.is_tournament;
  IF v_total_rake_after IS DISTINCT FROM 0::numeric
     OR v_fees_reversed IS DISTINCT FROM v_total_rake_before THEN
    RAISE EXCEPTION 'tournament % fee reversal did not close exactly',p_tournament_id
      USING ERRCODE='P0404';
  END IF;

  SELECT * INTO v_e FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id FOR UPDATE;
  IF v_e.tournament_id IS NULL OR v_e.enforced IS DISTINCT FROM true
     OR v_e.prize_balance IS DISTINCT FROM 0::numeric
     OR v_e.bounty_balance IS DISTINCT FROM 0::numeric
     OR v_e.fee_balance IS DISTINCT FROM 0::numeric THEN
    RAISE EXCEPTION 'tournament % cancellation did not close all escrow banks',
      p_tournament_id USING ERRCODE='P0404';
  END IF;
  UPDATE public.tournament_escrow
     SET closed_at=v_cancelled_at,close_note=v_close_note,updated_at=now()
   WHERE tournament_id=p_tournament_id AND closed_at IS NULL
     AND prize_balance=0 AND bounty_balance=0 AND fee_balance=0;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament % lost its exact-zero escrow close',p_tournament_id
      USING ERRCODE='40001';
  END IF;

  UPDATE public.tournament_players
     SET status='eliminated',eliminated_at=v_cancelled_at,
         chips=0,current_bounty=0
   WHERE tournament_id=p_tournament_id;
  WITH released AS (
    UPDATE public.table_seats s
       SET left_at=v_cancelled_at,status='left',leave_pending=false,
           is_sitting_out=false,is_away=false,sit_out_at=NULL,
           scheduled_leave_hands=NULL
      FROM public.tables tb
     WHERE tb.id=s.table_id AND tb.tournament_id=p_tournament_id
       AND s.left_at IS NULL RETURNING s.id)
  SELECT COALESCE(array_agg(id ORDER BY id),ARRAY[]::uuid[])
    INTO v_released_seat_ids FROM released;
  v_released_seat_count:=cardinality(v_released_seat_ids);
  UPDATE public.table_seats s
     SET status='left',leave_pending=false,is_sitting_out=false,is_away=false,
         sit_out_at=NULL,scheduled_leave_hands=NULL
   WHERE s.id=ANY(v_source_seat_ids) AND s.left_at IS NOT NULL;

  UPDATE public.tournaments
     SET status='CANCELLED',ended_at=v_cancelled_at,updated_at=now(),
         prize_pool=0,bounty_pool=0,total_rake=0,current_players=0,
         on_break=false,break_started_at=NULL,break_ends_at=NULL
   WHERE id=p_tournament_id
     AND upper(COALESCE(status::text,'')) NOT IN
         ('COMPLETED','CANCELLED','CANCELED','COMPLETING');
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament % lost its cancellation lifecycle claim',
      p_tournament_id USING ERRCODE='40001';
  END IF;
  UPDATE public.tables
     SET status='closed',lifecycle='closed',current_players=0,
         terminal_closed_at=v_cancelled_at,updated_at=now()
   WHERE tournament_id=p_tournament_id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>v_closed_table_count THEN
    RAISE EXCEPTION 'tournament % did not close every table',p_tournament_id
      USING ERRCODE='40001';
  END IF;

  SELECT COALESCE(array_agg(id ORDER BY id),ARRAY[]::uuid[])
    INTO v_fee_reversal_ids FROM unnest(v_fee_reversal_ids) ids(id);
  SELECT COALESCE(array_agg(id ORDER BY id),ARRAY[]::uuid[])
    INTO v_ticket_return_ids FROM unnest(v_ticket_return_ids) ids(id);
  v_receipt:=jsonb_build_object(
    'ok',true,'success',true,'fully_settled',true,'receipt_version',2,
    'tournament_id',p_tournament_id,'actor_id',v_actor,'status','CANCELLED',
    'source_player_count',v_source_player_count,
    'refunded_count',v_refunded_count,'refund_line_count',v_refund_line_count,
    'ticket_return_count',v_ticket_return_count,
    'total_ticket_returned',v_total_ticket_returned,
    'total_refunded',v_total_refunded,'fees_reversed',v_fees_reversed,
    'closed_table_count',v_closed_table_count,
    'source_seat_count',v_source_seat_count,
    'released_seat_count',v_released_seat_count,
    'refunds',v_refunds,'ticket_returns',v_ticket_returns,
    'settled_at',v_cancelled_at);
  INSERT INTO public.tournament_cancellation_receipts(
    tournament_id,actor_id,receipt_version,
    source_player_count,source_player_ids,
    refunded_count,refunded_registration_ids,refund_line_count,
    ticket_return_count,ticket_return_ids,total_ticket_returned,
    zero_refund_count,zero_refund_registration_ids,
    total_refunded,fees_reversed,total_rake_before,total_rake_after,
    closed_table_count,closed_table_ids,source_seat_count,source_seat_ids,
    released_seat_count,released_seat_ids,fee_reversal_ids,
    escrow_closed_at,escrow_close_note,spin_unwind_tournament_id,
    receipt,settled_at)
  VALUES(
    p_tournament_id,v_actor,2,
    v_source_player_count,v_source_player_ids,
    v_refunded_count,v_refunded_registration_ids,v_refund_line_count,
    v_ticket_return_count,v_ticket_return_ids,v_total_ticket_returned,
    v_zero_refund_count,v_zero_refund_registration_ids,
    v_total_refunded,v_fees_reversed,v_total_rake_before,v_total_rake_after,
    v_closed_table_count,v_closed_table_ids,v_source_seat_count,v_source_seat_ids,
    v_released_seat_count,v_released_seat_ids,v_fee_reversal_ids,
    v_cancelled_at,v_close_note,v_spin_unwind_id,v_receipt,v_cancelled_at);

  RETURN public.fn_ca_tournament_cancellation_receipt(p_tournament_id,v_actor);
END;
$$;


ALTER FUNCTION public.atomic_cancel_tournament_pre_seat_guard(p_tournament_id uuid, p_admin_id uuid) OWNER TO postgres;

--
-- Name: atomic_chip_transfer(uuid, uuid, numeric, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_chip_transfer(p_from_user_id uuid, p_to_user_id uuid, p_amount numeric, p_category text, p_description text, p_related_entity_id uuid DEFAULT NULL::uuid, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION
    'WALLET_POOL_RETIRED: This Transfer Path Writes A Retired Wallet Pool And Has Been Disabled. Chips Sent Here Would Not Appear Anywhere.'
    USING ERRCODE = '55000',
          HINT = 'Use the club cashier transfer paths (fn_club_bank_send, fn_agent_wallet_send, fn_wallet_type_transfer). Retirement decision: docs/runbooks/public-wallets-retirement.md.';
END;
$$;


ALTER FUNCTION public.atomic_chip_transfer(p_from_user_id uuid, p_to_user_id uuid, p_amount numeric, p_category text, p_description text, p_related_entity_id uuid, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: FUNCTION atomic_chip_transfer(p_from_user_id uuid, p_to_user_id uuid, p_amount numeric, p_category text, p_description text, p_related_entity_id uuid, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.atomic_chip_transfer(p_from_user_id uuid, p_to_user_id uuid, p_amount numeric, p_category text, p_description text, p_related_entity_id uuid, p_idempotency_key uuid) IS 'DISARMED 2026-09-01 (Dan, #2563 item 13). Previously transferred balances inside the retired public.wallets pool - money invisible to every screen. Refuses loudly; the client feature repoints to the live economy as the follow-up.';


--
-- Name: atomic_credit_wallet_and_log(uuid, numeric, text, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_credit_wallet_and_log(p_user_id uuid, p_amount numeric, p_category text DEFAULT 'credit'::text, p_description text DEFAULT ''::text, p_table_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_related_entity_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_club_id uuid;
  v_inserted integer;
  v_new_balance numeric;
  v_has_club boolean;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO wallet_credit_idempotency (key, user_id, amount)
    VALUES (p_idempotency_key, p_user_id, p_amount)
    ON CONFLICT (key) DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted = 0 THEN RETURN true; END IF;
  END IF;

  -- ZERO-DRIFT phase 5: tournament stacks are play chips and never cash
  -- out to a wallet. Blocked here exactly as in atomic_table_cashout.
  IF p_table_id IS NOT NULL AND EXISTS (
       SELECT 1 FROM public.tables t WHERE t.id = p_table_id AND t.tournament_id IS NOT NULL) THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'atomic_credit_wallet_and_log:tournament_mint_blocked', 'unauthorized_adjustment', 'info',
      'tourney-cashout-blocked:' || to_char(now(), 'YYYY-MM-DD'),
      p_amount, 0, p_amount, 'ledger', 'tables', p_table_id, NULL,
      NULL, p_table_id, NULL, NULL, NULL, NULL, NULL,
      'a tournament-table stack was about to credit a real wallet via atomic_credit_wallet_and_log - blocked. Tournament chips are play chips. This now blocks EVERY category, not just cashout; the category the caller used is in the metadata.',
      NULL, jsonb_build_object('user_id', p_user_id, 'amount', p_amount, 'category', p_category));
    RETURN true;
  END IF;

  /* ZERO-DRIFT (2026-08-31): tell the club_members ledger writer what this
     credit IS. 'cashout' maps to the table_cashout flow off the felt. */
  PERFORM set_config('app.ledger_category',
    CASE WHEN p_category IN ('cashout') THEN 'table_cashout'
         WHEN p_category IN ('buyin','rake','commission','transfer','rakeback',
                             'settlement','tournament_buyin','tournament_prize',
                             'bounty','refund','addon','rebuy','promo')
              THEN p_category
         ELSE 'player_funding' END, true);
  IF p_table_id IS NOT NULL THEN
    PERFORM set_config('app.ledger_counterparty', 'table_stack', true);
    PERFORM set_config('app.ledger_counterparty_entity', p_table_id::text, true);
  END IF;

  IF p_table_id IS NOT NULL THEN
    SELECT ts.club_id INTO v_club_id
      FROM table_seats ts
     WHERE ts.table_id = p_table_id AND ts.user_id = p_user_id
     ORDER BY ts.joined_at DESC LIMIT 1;
  END IF;
  IF v_club_id IS NULL THEN
    -- A caller that KNOWS which club a credit belongs to says so in
    -- app.ledger_club_id. Rakeback earned at a club is paid into THAT
    -- club's wallet, not into whichever club the player joined first.
    -- Unset - which is every existing caller - is the old behaviour
    -- exactly, because fn_player_home_club ignores a NULL hint.
    v_club_id := public.fn_player_home_club(p_user_id,
      NULLIF(current_setting('app.ledger_club_id', true), '')::uuid);
  END IF;

  IF v_club_id IS NOT NULL THEN
    PERFORM public.fn_ensure_club_wallet(p_user_id, v_club_id);
    UPDATE club_members
       SET chip_balance = COALESCE(chip_balance,0) + p_amount, updated_at = now()
     WHERE user_id = p_user_id AND club_id = v_club_id
     RETURNING chip_balance INTO v_new_balance;
  ELSE
    SELECT EXISTS (SELECT 1 FROM club_members m WHERE m.user_id = p_user_id) INTO v_has_club;
    IF v_has_club THEN
      RAISE EXCEPTION 'No club wallet resolves for Club Arena credit to player %', p_user_id;
    END IF;
    UPDATE wallets SET balance = COALESCE(balance,0) + p_amount, updated_at = now()
     WHERE user_id = p_user_id AND wallet_type = 'PLAYER'
     RETURNING balance INTO v_new_balance;
    IF NOT FOUND THEN
      INSERT INTO wallets (user_id, wallet_type, balance, locked_balance)
      VALUES (p_user_id, 'PLAYER', p_amount, 0)
      ON CONFLICT (user_id, wallet_type) DO UPDATE
        SET balance = wallets.balance + p_amount, updated_at = now()
      RETURNING balance INTO v_new_balance;
    END IF;
  END IF;

  IF p_category = 'cashout' THEN
    INSERT INTO wallet_transactions (user_id, wallet_type, type, amount, category,
                                     description, table_id, balance_after)
    VALUES (p_user_id, 'PLAYER', 'credit', p_amount, 'cashout',
            COALESCE(NULLIF(p_description, ''), 'Cash-out to club wallet'),
            p_table_id, v_new_balance);
  END IF;

  IF v_club_id IS NOT NULL THEN
    INSERT INTO chip_transactions (club_id, to_user_id, amount, transaction_type,
                                   notes, table_id, metadata)
    VALUES (v_club_id, p_user_id, p_amount, p_category,
            COALESCE(NULLIF(p_description, ''), 'Wallet credit'), p_table_id,
            CASE WHEN p_category = 'cashout'
                 THEN jsonb_build_object('mirrored_to_wallet', true)
                 ELSE '{}'::jsonb END);
  END IF;

  RETURN true;
END; $$;


ALTER FUNCTION public.atomic_credit_wallet_and_log(p_user_id uuid, p_amount numeric, p_category text, p_description text, p_table_id uuid, p_hand_id uuid, p_related_entity_id uuid, p_idempotency_key text) OWNER TO postgres;

--
-- Name: FUNCTION atomic_credit_wallet_and_log(p_user_id uuid, p_amount numeric, p_category text, p_description text, p_table_id uuid, p_hand_id uuid, p_related_entity_id uuid, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.atomic_credit_wallet_and_log(p_user_id uuid, p_amount numeric, p_category text, p_description text, p_table_id uuid, p_hand_id uuid, p_related_entity_id uuid, p_idempotency_key text) IS 'AUDIT M17: service_role ONLY. This is the generic credit primitive - it takes the amount from its caller, so a browser-reachable grant on it is a chip mint. Client features credit through purpose-built SECURITY DEFINER functions that derive the amount from authoritative state (fn_claim_special_bonus, fn_admin_kick_player, and so on). Do not grant this to authenticated.';


--
-- Name: atomic_deduct_wallet_and_log(uuid, numeric, text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_deduct_wallet_and_log(p_user_id uuid, p_amount numeric, p_category text DEFAULT 'debit'::text, p_description text DEFAULT ''::text, p_table_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_related_entity_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_balance numeric; v_club_id uuid; v_has_club boolean;
BEGIN
  IF p_table_id IS NOT NULL THEN
    SELECT ts.club_id INTO v_club_id
      FROM table_seats ts
     WHERE ts.table_id = p_table_id AND ts.user_id = p_user_id
     ORDER BY ts.joined_at DESC LIMIT 1;
  END IF;
  IF v_club_id IS NULL THEN
    v_club_id := public.fn_player_home_club(p_user_id, NULL);
  END IF;

  IF v_club_id IS NOT NULL THEN
    PERFORM public.fn_ensure_club_wallet(p_user_id, v_club_id);
    SELECT chip_balance INTO v_balance FROM club_members
     WHERE user_id = p_user_id AND club_id = v_club_id FOR UPDATE;
    IF v_balance IS NULL OR v_balance < p_amount THEN RETURN false; END IF;
    UPDATE club_members SET chip_balance = chip_balance - p_amount, updated_at = now()
     WHERE user_id = p_user_id AND club_id = v_club_id;

    INSERT INTO chip_transactions (club_id, from_user_id, amount, transaction_type, notes)
    VALUES (v_club_id, p_user_id, p_amount, p_category,
            COALESCE(NULLIF(p_description, ''), 'Wallet debit'));
    RETURN true;
  END IF;

  SELECT EXISTS (SELECT 1 FROM club_members m WHERE m.user_id = p_user_id) INTO v_has_club;
  IF v_has_club THEN
    RAISE EXCEPTION 'No club wallet resolves for Club Arena debit from player %', p_user_id;
  END IF;

  -- smarter.poker user only.
  SELECT balance INTO v_balance FROM wallets
   WHERE user_id = p_user_id AND wallet_type = 'PLAYER' FOR UPDATE;
  IF v_balance IS NULL OR v_balance < p_amount THEN RETURN false; END IF;
  UPDATE wallets SET balance = balance - p_amount, updated_at = now()
   WHERE user_id = p_user_id AND wallet_type = 'PLAYER';
  RETURN true;
END; $$;


ALTER FUNCTION public.atomic_deduct_wallet_and_log(p_user_id uuid, p_amount numeric, p_category text, p_description text, p_table_id uuid, p_hand_id uuid, p_related_entity_id uuid) OWNER TO postgres;

--
-- Name: atomic_distribute_rake(uuid, uuid, uuid, integer, numeric, numeric, numeric, integer, jsonb, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_distribute_rake(p_table_id uuid, p_club_id uuid, p_hand_id uuid, p_hand_number integer, p_rake numeric, p_bbj numeric DEFAULT 0, p_pot numeric DEFAULT NULL::numeric, p_num_players integer DEFAULT (NULL::numeric)::integer, p_contributions jsonb DEFAULT NULL::jsonb, p_tournament_id uuid DEFAULT NULL::uuid, p_returned_uncalled jsonb DEFAULT NULL::jsonb, p_rake_method text DEFAULT 'DEALT_EQUAL'::text) RETURNS TABLE(applied boolean, already_processed boolean, recovered boolean, rake_record_id uuid, club_net_credit numeric, spendable_route text, spendable_amount numeric, union_id_out uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_union_id     uuid;
  v_g_union      uuid;
  v_is_private   boolean := false;
  v_club_name    text;
  v_net          numeric;
  v_bbj          numeric := COALESCE(p_bbj, 0);
  v_rr_id        uuid;
  v_first_claim  boolean := false;
  v_recovered    boolean := false;
  v_leg_key      uuid;
  v_n            integer;
  v_cw_after     numeric;
  v_union_rake   numeric;
  v_route        text;
  v_method       text;
  v_alloc_sum    numeric;
  v_st           text;
  v_msg          text;
  v_dup_id       uuid;
BEGIN
  IF p_club_id IS NULL OR p_rake IS NULL OR p_rake <= 0 THEN
    RETURN QUERY SELECT false, false, false, NULL::uuid, 0::numeric,
                        NULL::text, 0::numeric, NULL::uuid;
    RETURN;
  END IF;

  /* ZERO-DRIFT (2026-08-31): declare the ledger context for this transaction
     so every auto-journaled balance delta below is categorized as rake coming
     off the felt, not an anonymous adjustment against suspense. */
  PERFORM set_config('app.ledger_category', 'rake', true);
  PERFORM set_config('app.ledger_counterparty', 'table_stack', true);
  PERFORM set_config('app.ledger_counterparty_entity', COALESCE(p_table_id::text, ''), true);
  -- PHASE 6.4 (2026-09-05): the rake's legs name the hand when it is known.
  PERFORM set_config('app.ledger_hand_id', COALESCE(p_hand_id::text, ''), true);

  v_method := CASE WHEN p_rake_method = 'WEIGHTED_CONTRIBUTED'
                   THEN 'WEIGHTED_CONTRIBUTED' ELSE 'DEALT_EQUAL' END;

  v_net := p_rake - v_bbj;

  SELECT c.name INTO v_club_name FROM public.clubs c WHERE c.id = p_club_id;

  -- UNION LAW (Dan, restored 2026-08-30): route by the GAME's union stamp,
  -- not club membership. A private club game's rake NEVER touches the union.
  IF p_table_id IS NOT NULL THEN
    SELECT COALESCE(t.is_private, false), t.union_id
      INTO v_is_private, v_g_union
      FROM public.tables t WHERE t.id = p_table_id;
  END IF;
  IF p_tournament_id IS NOT NULL AND NOT v_is_private AND v_g_union IS NULL THEN
    SELECT COALESCE(tr.is_private, false), tr.union_id
      INTO v_is_private, v_g_union
      FROM public.tournaments tr WHERE tr.id = p_tournament_id;
  END IF;

  IF v_is_private THEN
    v_union_id := NULL;
  ELSE
    v_union_id := v_g_union;
    IF v_union_id IS NULL THEN
      SELECT c.union_id INTO v_union_id FROM public.clubs c WHERE c.id = p_club_id;
    END IF;
  END IF;

  /* A HAND THAT CANNOT NAME ITSELF BY ID STILL NAMES ITSELF BY TABLE AND
     NUMBER (2026-09-06). Both idempotency guards below key on p_hand_id, and
     both are disabled when it is NULL: ON CONFLICT (hand_id) WHERE hand_id IS
     NOT NULL matches nothing, and v_leg_key fell back to a FRESH RANDOM uuid,
     so rake_distribution_legs could not dedupe either. The engine calls this
     before logHandHistory has produced a hand row and again after, and the
     second call was treated as a new hand: a duplicate rake_records row, and
     a second increment of the club wallet's period and lifetime rake. 4,452
     such rows exist, 2026-04-16 to 2026-09-05, carrying 16,426.46 of rake and
     2,068.82 of BBJ contribution that no hand ever dropped - measured against
     hand_history and bbj_contributions, which agree with the LINKED rows alone
     in 283 of the 284 cases where the hand still exists.

     So: ask hand_history for the id first, and if it genuinely is not there
     yet, key on what the caller always knows - the table and the hand number. */
  IF p_hand_id IS NULL AND p_table_id IS NOT NULL AND p_hand_number IS NOT NULL THEN
    SELECT h.id INTO p_hand_id
      FROM public.hand_history h
     WHERE h.table_id = p_table_id
       AND h.hand_number = p_hand_number
     ORDER BY h.created_at DESC
     LIMIT 1;
    -- Phase 6.4: the legs name the hand as soon as we know it.
    PERFORM set_config('app.ledger_hand_id', COALESCE(p_hand_id::text, ''), true);
  END IF;

  IF p_hand_id IS NULL AND p_table_id IS NOT NULL AND p_hand_number IS NOT NULL THEN
    SELECT rr.id INTO v_dup_id
      FROM public.rake_records rr
     WHERE rr.table_id = p_table_id
       AND rr.hand_id IS NULL
       AND (rr.metadata->>'hand_number') = p_hand_number::text
       AND rr.created_at > now() - interval '2 days'
     ORDER BY rr.created_at
     LIMIT 1;
    IF v_dup_id IS NOT NULL THEN
      RETURN QUERY SELECT false, true, false, v_dup_id, 0::numeric,
                          NULL::text, 0::numeric, v_union_id;
      RETURN;
    END IF;
  END IF;

  INSERT INTO public.rake_records (
    hand_id, table_id, club_id, rake_amount, bbj_contribution, pot_size,
    num_players, player_contributions, is_tournament, tournament_id, source,
    metadata, rake_method, returned_uncalled
  ) VALUES (
    p_hand_id, p_table_id, p_club_id, p_rake, v_bbj, p_pot,
    p_num_players, p_contributions, (p_tournament_id IS NOT NULL), p_tournament_id,
    'atomic_distribute_rake',
    jsonb_build_object('hand_number', p_hand_number, 'is_private', v_is_private),
    v_method, p_returned_uncalled
  )
  ON CONFLICT (hand_id) WHERE hand_id IS NOT NULL DO NOTHING
  RETURNING id INTO v_rr_id;

  IF v_rr_id IS NOT NULL THEN
    v_first_claim := true;
  ELSE
    SELECT id INTO v_rr_id FROM public.rake_records
      WHERE hand_id = p_hand_id ORDER BY created_at LIMIT 1;
  END IF;

  IF v_first_claim AND p_hand_id IS NOT NULL
     AND p_contributions IS NOT NULL AND jsonb_typeof(p_contributions) = 'object' THEN
    INSERT INTO public.rake_attributions (
      hand_id, player_id, rake_amount, rake_record_id, table_id, club_id,
      gross_contribution, returned_uncalled, eligible_contribution,
      contribution_weight, weighted_rake_credit, bbj_attributed_contribution,
      rake_method
    )
    SELECT p_hand_id,
           a.user_id,
           a.credit,
           v_rr_id, p_table_id,
           COALESCE((SELECT ts.club_id FROM public.table_seats ts
                      WHERE ts.table_id = p_table_id AND ts.user_id = a.user_id
                      ORDER BY ts.joined_at DESC NULLS LAST LIMIT 1), p_club_id),
           (p_contributions ->> a.user_id::text)::numeric
             + COALESCE((p_returned_uncalled ->> a.user_id::text)::numeric, 0),
           COALESCE((p_returned_uncalled ->> a.user_id::text)::numeric, 0),
           (p_contributions ->> a.user_id::text)::numeric,
           a.weight,
           a.credit,
           COALESCE(b.credit, 0),
           v_method
      FROM public.fn_allocate_rake_credits(p_rake, p_contributions, v_method) a
      LEFT JOIN public.fn_allocate_rake_credits(v_bbj, p_contributions, v_method) b
        ON b.user_id = a.user_id
    ON CONFLICT (hand_id, player_id) DO NOTHING;

    SELECT COALESCE(SUM(a.credit), 0) INTO v_alloc_sum
      FROM public.fn_allocate_rake_credits(p_rake, p_contributions, v_method) a;
    IF v_alloc_sum <> round(p_rake, 2) AND v_alloc_sum <> 0 THEN
      INSERT INTO public.financial_alerts (severity, source, message, context)
      VALUES ('critical', 'atomic_distribute_rake', 'RAKE_ALLOCATION_MISMATCH',
        jsonb_build_object('hand_id', p_hand_id, 'rake', p_rake,
          'allocated', v_alloc_sum, 'method', v_method));
    END IF;
  END IF;

  /* THE LEG KEY IS DERIVED, NEVER RANDOM (2026-09-06). A random key made
     rake_distribution_legs' ON CONFLICT (leg_key, leg) unreachable, so the
     club wallet's period and lifetime rake were incremented again for a hand
     already counted. When the hand has no id, the key is the table and the
     hand number - the same hand always produces the same key. */
  v_leg_key := COALESCE(
    p_hand_id,
    CASE WHEN p_table_id IS NOT NULL AND p_hand_number IS NOT NULL
         THEN md5('rake:' || p_table_id::text || ':' || p_hand_number::text)::uuid
    END,
    gen_random_uuid());
  PERFORM set_config('app.ledger_settlement', 'rake:' || v_leg_key::text, true);

  INSERT INTO public.rake_distribution_legs (leg_key, leg, club_id, union_id, amount)
  VALUES (v_leg_key, 'club_accumulator', p_club_id, v_union_id, v_net)
  ON CONFLICT (leg_key, leg) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    UPDATE public.club_wallets
       SET period_rake_collected     = period_rake_collected     + p_rake,
           period_bbj_contribution   = period_bbj_contribution   + v_bbj,
           lifetime_rake_collected   = lifetime_rake_collected   + p_rake,
           lifetime_bbj_contribution = lifetime_bbj_contribution + v_bbj,
           chip_balance              = chip_balance,  -- 2026-09-02 ruling: the club share is paid weekly from the rake treasury, not per hand
           updated_at                = NOW()
     WHERE club_id = p_club_id
     RETURNING chip_balance INTO v_cw_after;

    IF v_cw_after IS NULL THEN
      INSERT INTO public.club_wallets (
        club_id, chip_balance, period_rake_collected, period_bbj_contribution,
        lifetime_rake_collected, lifetime_bbj_contribution
      ) VALUES (
        p_club_id, 0, p_rake, v_bbj, p_rake, v_bbj
      )
      ON CONFLICT (club_id) DO UPDATE SET
        period_rake_collected     = club_wallets.period_rake_collected     + EXCLUDED.period_rake_collected,
        period_bbj_contribution   = club_wallets.period_bbj_contribution   + EXCLUDED.period_bbj_contribution,
        lifetime_rake_collected   = club_wallets.lifetime_rake_collected   + EXCLUDED.lifetime_rake_collected,
        lifetime_bbj_contribution = club_wallets.lifetime_bbj_contribution + EXCLUDED.lifetime_bbj_contribution,
        chip_balance              = club_wallets.chip_balance              + EXCLUDED.chip_balance,
        updated_at                = NOW()
      RETURNING chip_balance INTO v_cw_after;
    END IF;

    INSERT INTO public.club_wallet_transactions (
      club_id, type, amount, balance_after, related_id, reason
    ) VALUES (
      p_club_id, 'rake_in', v_net, v_cw_after, p_hand_id,
      'Rake collected (hand ' || COALESCE('#' || p_hand_number::text, 'unknown') ||
        ', BBJ contribution ' || v_bbj::text || ')'
    );

    IF NOT v_first_claim THEN v_recovered := true; END IF;
  END IF;

  IF v_union_id IS NOT NULL THEN
    v_route := 'union_rake_wallet';
    INSERT INTO public.rake_distribution_legs (leg_key, leg, club_id, union_id, amount)
    VALUES (v_leg_key, 'union_rake', p_club_id, v_union_id, p_rake)
    ON CONFLICT (leg_key, leg) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n > 0 THEN
      -- UNION LAW (restored 2026-08-30): RAKE TREASURY ONLY. chip_balance
      -- (Union Bank) is deliberately NOT touched.
      INSERT INTO public.union_wallets (union_id, chip_balance, rake_wallet, total_rake_collected)
           VALUES (v_union_id, 0, p_rake, p_rake)
      ON CONFLICT (union_id) DO UPDATE SET
           rake_wallet          = public.union_wallets.rake_wallet + p_rake,
           total_rake_collected = COALESCE(public.union_wallets.total_rake_collected, 0) + p_rake,
           updated_at           = NOW()
      RETURNING rake_wallet INTO v_union_rake;

      INSERT INTO public.union_wallet_transactions (
        union_id, club_id, amount, tx_type, wallet, direction, balance_after, notes
      ) VALUES (
        v_union_id, p_club_id, p_rake, 'rake', 'rake_wallet', 'credit', v_union_rake,
        'Cash game rake: hand #' || COALESCE(p_hand_number::text, '?') ||
          ' (' || COALESCE(v_club_name, 'club') || ')'
      );

      IF NOT v_first_claim THEN v_recovered := true; END IF;
    END IF;
  ELSE
    v_route := 'club_chip_treasury';
    INSERT INTO public.rake_distribution_legs (leg_key, leg, club_id, union_id, amount)
    VALUES (v_leg_key, 'chip_treasury', p_club_id, NULL, p_rake)
    ON CONFLICT (leg_key, leg) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n > 0 THEN
      /* ZERO-DRIFT: this leg writes its own chip_ledger row below; suppress
         the clubs auto-journal for this one statement. */
      PERFORM set_config('app.ledger_autoskip_clubs', '1', true);
      UPDATE public.clubs
         SET chip_treasury = COALESCE(chip_treasury, 0) + p_rake,
             total_rake    = COALESCE(total_rake, 0) + p_rake,
             updated_at    = NOW()
       WHERE id = p_club_id;
      PERFORM set_config('app.ledger_autoskip_clubs', '0', true);

      /* JOURNAL THE TREASURY LEG (2026-08-31). Inside the leg_key first-claim
         guard, so a replayed hand credits once and journals once. Journal failure rolls back this distribution. */
      BEGIN
        INSERT INTO public.chip_ledger
          (performed_by, from_type, from_entity_id, to_type, to_entity_id,
           amount, category, club_id, table_id, hand_id, tournament_id, description)
        VALUES (
          COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
          'table_stack',   p_table_id,
          'club_treasury', p_club_id,
          p_rake, 'rake', p_club_id, p_table_id, p_hand_id, p_tournament_id,
          'Rake to club treasury, hand ' || COALESCE('#' || p_hand_number::text, 'unknown')
            || ' (atomic_distribute_rake)');
      EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;

      IF NOT v_first_claim THEN v_recovered := true; END IF;
    END IF;
  END IF;

  RETURN QUERY SELECT v_first_claim, (NOT v_first_claim), v_recovered, v_rr_id,
                      v_net, v_route, p_rake, v_union_id;
END;
$$;


ALTER FUNCTION public.atomic_distribute_rake(p_table_id uuid, p_club_id uuid, p_hand_id uuid, p_hand_number integer, p_rake numeric, p_bbj numeric, p_pot numeric, p_num_players integer, p_contributions jsonb, p_tournament_id uuid, p_returned_uncalled jsonb, p_rake_method text) OWNER TO postgres;

--
-- Name: atomic_pay_player_rakeback(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_pay_player_rakeback(p_user_id uuid, p_amount numeric) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF p_amount <= 0 THEN RETURN; END IF;
  -- UNION LAW: rakeback goes back to the club whose chips generated the rake.
  PERFORM public.fn_pay_player_chips(p_user_id, p_amount, 'rakeback', 'Rakeback payout', NULL, NULL);
END; $$;


ALTER FUNCTION public.atomic_pay_player_rakeback(p_user_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: atomic_pay_player_rakeback(uuid, uuid, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_pay_player_rakeback(p_snapshot_id uuid, p_player_id uuid, p_amount numeric, p_period_id uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_inserted integer;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN RETURN; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO wallet_credit_idempotency (key, user_id, amount)
    VALUES (p_idempotency_key, p_player_id, p_amount)
    ON CONFLICT (key) DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted = 0 THEN RETURN; END IF;
  END IF;

  PERFORM public.fn_pay_player_chips(
    p_player_id, p_amount, 'rakeback',
    'Rakeback payout (snapshot ' || p_snapshot_id::text || ', period ' || p_period_id::text || ')',
    NULL, p_snapshot_id);
END;
$$;


ALTER FUNCTION public.atomic_pay_player_rakeback(p_snapshot_id uuid, p_player_id uuid, p_amount numeric, p_period_id uuid, p_idempotency_key text) OWNER TO postgres;

--
-- Name: atomic_seat_cashout_locked(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_seat_cashout_locked(p_user_id uuid, p_table_id uuid, p_seat_number integer DEFAULT NULL::integer, p_leave_mode text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_tournament_id uuid;
BEGIN
  SELECT tb.tournament_id INTO v_tournament_id
    FROM public.tables tb WHERE tb.id=p_table_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CASHOUT_TABLE_NOT_FOUND' USING ERRCODE='22023';
  END IF;
  IF v_tournament_id IS NOT NULL THEN
    RAISE EXCEPTION 'TOURNAMENT_SEAT_EXIT_REQUIRES_TOURNAMENT_AUTHORITY'
      USING ERRCODE='55000';
  END IF;
  RETURN public.atomic_seat_cashout_locked_pre_tournament_guard(
    p_user_id,p_table_id,p_seat_number,p_leave_mode);
END;
$$;


ALTER FUNCTION public.atomic_seat_cashout_locked(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_leave_mode text) OWNER TO postgres;

--
-- Name: atomic_seat_cashout_locked_pre_tournament_guard(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_seat_cashout_locked_pre_tournament_guard(p_user_id uuid, p_table_id uuid, p_seat_number integer DEFAULT NULL::integer, p_leave_mode text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_seat      record;
  v_stack     numeric;
  v_key       text;
  v_legacy    text;
  v_credited  boolean := false;
  v_seat_rows integer;
  v_tournament uuid;
  v_engine    boolean;
  v_mode      text;
  v_admin_forced boolean;
  v_enforce   boolean;
  v_chk       jsonb;
BEGIN
  v_engine := public.fn_caller_is_engine();
  -- H6: the mode is one of two words or nothing. 'vpip_evicted' (Dan
  -- 2026-09-05) is a system exit for the clock (a forced one) that closes
  -- the session with its own reason, so the two-hour bar is written.
  v_mode := CASE WHEN p_leave_mode IN ('voluntary', 'forced') THEN p_leave_mode
                 WHEN p_leave_mode = 'vpip_evicted' THEN 'forced' ELSE NULL END;
  -- H2: a club admin's kick, marked by fn_admin_kick_player in THIS transaction
  -- only, after is_club_admin() passed. A browser cannot set a GUC through
  -- PostgREST; one request is one function call in one transaction.
  v_admin_forced := (v_mode = 'forced')
                    AND COALESCE(current_setting('app.cash_exit_authority', true), '') = 'club_admin';

  IF NOT v_engine AND NOT v_admin_forced
     AND (auth.uid() IS NULL OR ( auth.uid() <> p_user_id)) THEN
    RAISE EXCEPTION 'Cannot cash out for another user';
  END IF;

  -- H1: the same lock atomic_table_buyin holds while it reads the floor, taken
  -- BEFORE the seat row so the two functions lock in one order.
  PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:' || p_user_id::text, 0));

  /* THE GAME BEFORE THE SEAT (20260906). A seat change on a seat-first game
     (spin, SNG, heads-up) fires trg_seat_change_syncs_seat_first_count, which
     writes tournaments.current_players - a lock on the game's row taken AFTER
     the seat row. The engine finishing that same game does the reverse: its
     UPDATE tournaments ... status holds the game row and its trigger
     fn_clear_seats_on_game_end then locks every seat. 131 deadlocks a day,
     every one this pair, every one at the end of a spin or heads-up. Parent
     before child: take the game row first, in the mode the trigger's UPDATE
     needs, so a cashout racing a finish waits for it instead of dying.
     Cash tables have no game row and skip this. */
  SELECT t.tournament_id INTO v_tournament FROM tables t WHERE t.id = p_table_id;
  IF v_tournament IS NOT NULL THEN
    PERFORM 1 FROM tournaments WHERE id = v_tournament FOR NO KEY UPDATE;
  END IF;

  IF p_seat_number IS NOT NULL THEN
    SELECT id, stack, joined_at, seat_number INTO v_seat
      FROM table_seats
     WHERE table_id = p_table_id AND user_id = p_user_id
       AND seat_number = p_seat_number AND left_at IS NULL
     FOR UPDATE;
  ELSE
    SELECT id, stack, joined_at, seat_number INTO v_seat
      FROM table_seats
     WHERE table_id = p_table_id AND user_id = p_user_id AND left_at IS NULL
     ORDER BY joined_at DESC
     LIMIT 1
     FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'stack', 0, 'reason', 'no_active_seat');
  END IF;

  v_stack := COALESCE(v_seat.stack, 0);

  /* CHIP CONTINUITY (OPORD 1.3 s6.4 / I5). A browser caller is always checked
     unless it is a club admin's kick (H2); the engine is checked when it says
     the exit is the player's own choice. Raised BEFORE any credit. */
  v_enforce := v_tournament IS NULL
               AND ((NOT v_engine AND NOT v_admin_forced) OR (v_engine AND v_mode = 'voluntary'));
  IF v_enforce THEN
    v_chk := public.fn_cash_leave_check(p_user_id, p_table_id);
    IF NOT COALESCE((v_chk->>'allowed')::boolean, true) THEN
      RAISE EXCEPTION 'LEAVE_LOCKED:%', COALESCE(v_chk->>'stay_remaining_ms', '0')
        USING HINT = 'Leave available when the stay clock reaches zero';
    END IF;
  END IF;

  -- to_json, NOT to_char. See 20260901002242: to_char pads microseconds and
  -- breaks dedupe against every key the TypeScript already wrote.
  v_key := CASE
             WHEN v_seat.joined_at IS NOT NULL
               THEN 'cashout:' || v_seat.id || ':' || btrim(to_json(v_seat.joined_at)::text, '"')
             ELSE 'cashout:' || v_seat.id
           END;
  v_legacy := 'cashout:' || v_seat.id;

  /* ZERO-DRIFT (2026-09-01): a tournament-table stack is play chips. */
  IF v_tournament IS NOT NULL THEN
    v_stack := 0;
    v_credited := false;
  ELSIF v_stack > 0 THEN
    IF EXISTS (SELECT 1 FROM wallet_credit_idempotency WHERE key = v_legacy) THEN
      v_credited := false;
    ELSE
      PERFORM public.atomic_credit_wallet_and_log(
        p_user_id, v_stack, 'cashout', 'Cash-out from table',
        p_table_id, NULL, NULL, v_key
      );
      v_credited := true;
    END IF;
  END IF;

  UPDATE table_seats
     SET left_at = NOW(), leave_pending = false
   WHERE table_id = p_table_id AND user_id = p_user_id
     AND seat_number = v_seat.seat_number AND left_at IS NULL;
  GET DIAGNOSTICS v_seat_rows = ROW_COUNT;

  IF v_seat_rows = 0 THEN
    RAISE EXCEPTION
      'Cash-out could not vacate the locked seat (table %, player %, seat %)',
      p_table_id, p_user_id, v_seat.seat_number;
  END IF;

  IF v_tournament IS NULL THEN
    PERFORM public.fn_cash_session_close(
      p_user_id, p_table_id, v_stack,
      CASE WHEN v_mode = 'voluntary' THEN 'voluntary'
           WHEN p_leave_mode = 'vpip_evicted' THEN 'vpip_evicted'
           WHEN v_admin_forced THEN 'kicked'
           ELSE 'system' END);
  END IF;

  UPDATE tables
     SET current_players = (
       SELECT count(*) FROM table_seats
        WHERE table_id = p_table_id AND left_at IS NULL)
   WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'ok', true, 'stack', v_stack, 'credited', v_credited,
    'seat_number', v_seat.seat_number, 'idempotency_key', v_key,
    'tournament_table', v_tournament IS NOT NULL);
END;
$$;


ALTER FUNCTION public.atomic_seat_cashout_locked_pre_tournament_guard(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_leave_mode text) OWNER TO postgres;

--
-- Name: atomic_table_addon(uuid, uuid, numeric, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_table_addon(p_user_id uuid, p_table_id uuid, p_amount numeric, p_apply_to_seat boolean DEFAULT true, p_idempotency_key text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_request jsonb;
  v_response jsonb;
  v_balance numeric;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);

  v_request := jsonb_build_object(
    'door', 'atomic_table_addon',
    'user_id', p_user_id,
    'table_id', p_table_id,
    'amount', p_amount,
    'apply_to_seat', p_apply_to_seat
  );
  v_response := public.fn_claim_entry_purchase_receipt(
    'cash_addon', p_idempotency_key, v_request
  );
  IF NOT COALESCE((v_response->>'claimed')::boolean, false) THEN
    RETURN (v_response->'response'->>'balance')::numeric;
  END IF;
  IF p_idempotency_key IS NOT NULL AND length(btrim(p_idempotency_key)) > 0
     AND EXISTS (
       SELECT 1 FROM public.table_addon_idempotency k
        WHERE k.key = p_idempotency_key
     ) THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_RECEIPT_UNBOUND: this historical add-on key has no exact response receipt'
      USING ERRCODE = '55000';
  END IF;

  IF public.fn_entry_purchases_frozen() THEN
    RAISE EXCEPTION
      'PLATFORM_FROZEN: scheduled maintenance has closed cash add-ons; no chips moved'
      USING ERRCODE = '55006', HINT = 'Retry after the maintenance break has ended.';
  END IF;
  PERFORM public.fn_assert_cash_chip_purchase_table(p_table_id);
  v_balance := public.atomic_table_addon_before_maintenance_announcement_gate(
    p_user_id, p_table_id, p_amount, p_apply_to_seat, p_idempotency_key
  );
  v_response := public.fn_record_entry_purchase_receipt(
    'cash_addon',
    p_idempotency_key,
    v_request,
    jsonb_build_object('balance', v_balance)
  );
  RETURN (v_response->>'balance')::numeric;
END;
$$;


ALTER FUNCTION public.atomic_table_addon(p_user_id uuid, p_table_id uuid, p_amount numeric, p_apply_to_seat boolean, p_idempotency_key text) OWNER TO postgres;

--
-- Name: atomic_table_addon_before_maintenance_announcement_gate(uuid, uuid, numeric, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_table_addon_before_maintenance_announcement_gate(p_user_id uuid, p_table_id uuid, p_amount numeric, p_apply_to_seat boolean DEFAULT true, p_idempotency_key text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_new_balance numeric; v_claimed integer; v_seat_club uuid; v_seat_rows integer;
        v_stack numeric; v_max numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Add-on amount must be positive';
  END IF;

  IF auth.uid() IS NOT NULL AND auth.uid() <> p_user_id THEN
    RAISE EXCEPTION 'Cannot add on for another user';
  END IF;

  PERFORM set_config('app.ledger_category', 'addon', true);
  PERFORM set_config('app.ledger_counterparty', 'table_stack', true);
  PERFORM set_config('app.ledger_counterparty_entity', COALESCE(p_table_id::text, ''), true);

  SELECT ts.club_id, ts.stack INTO v_seat_club, v_stack
    FROM table_seats ts
   WHERE ts.table_id = p_table_id AND ts.user_id = p_user_id AND ts.left_at IS NULL
   LIMIT 1
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Player not seated at this table'; END IF;

  /* CHIP CONTINUITY (A0.17, I2): the table maximum is a hard ceiling in the
     database as well as in the engine. Between hands the chips land on the
     seat here; mid-hand resolve_pending_addon already caps at delivery. */
  IF p_apply_to_seat THEN
    SELECT t.max_buy_in INTO v_max FROM tables t WHERE t.id = p_table_id;
    IF v_max IS NOT NULL AND v_max > 0 AND COALESCE(v_stack, 0) + p_amount > v_max THEN
      RAISE EXCEPTION 'BUYIN_ABOVE_MAX: add-on of % would take the stack above the table maximum (%)', p_amount, v_max;
    END IF;
  END IF;

  IF v_seat_club IS NULL THEN
    v_seat_club := public.fn_seat_club_for_user(p_user_id, p_table_id, NULL);
  END IF;
  IF v_seat_club IS NULL THEN
    RAISE EXCEPTION 'No club wallet resolves for this add-on';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO table_addon_idempotency (key, user_id, table_id, amount, applied_to_seat)
    VALUES (p_idempotency_key, p_user_id, p_table_id, p_amount, p_apply_to_seat)
    ON CONFLICT (key) DO NOTHING;
    GET DIAGNOSTICS v_claimed = ROW_COUNT;
    IF v_claimed = 0 THEN
      SELECT chip_balance INTO v_new_balance FROM club_members
       WHERE user_id = p_user_id AND club_id = v_seat_club;
      RETURN v_new_balance;
    END IF;
  END IF;

  PERFORM public.fn_ensure_club_wallet(p_user_id, v_seat_club);

  UPDATE club_members
     SET chip_balance = chip_balance - p_amount, updated_at = NOW()
   WHERE user_id = p_user_id AND club_id = v_seat_club AND chip_balance >= p_amount
   RETURNING chip_balance INTO v_new_balance;
  IF v_new_balance IS NULL THEN
    RAISE EXCEPTION 'Insufficient club chips for add-on (club %)', v_seat_club;
  END IF;

  IF p_apply_to_seat THEN
    UPDATE table_seats SET stack = stack + p_amount
     WHERE table_id = p_table_id AND user_id = p_user_id AND left_at IS NULL;
    GET DIAGNOSTICS v_seat_rows = ROW_COUNT;
    IF v_seat_rows = 0 THEN
      RAISE EXCEPTION
        'Add-on of % could not be applied: seat vacated mid-add-on (table %, player %)',
        p_amount, p_table_id, p_user_id;
    END IF;
    -- CHIP CONTINUITY: chips landed on the seat -> baseline rises with them.
    PERFORM public.fn_cash_session_add_baseline(p_user_id, p_table_id, p_amount);
  ELSE
    INSERT INTO table_pending_addons (table_id, user_id, amount)
    VALUES (p_table_id, p_user_id, p_amount);
  END IF;

  INSERT INTO wallet_transactions
    (user_id, wallet_type, type, amount, category, description, table_id, balance_after)
    VALUES (p_user_id, 'PLAYER', 'debit', p_amount, 'addon',
            'Table add-on (club wallet)', p_table_id, v_new_balance);

  RETURN v_new_balance;
END;
$$;


ALTER FUNCTION public.atomic_table_addon_before_maintenance_announcement_gate(p_user_id uuid, p_table_id uuid, p_amount numeric, p_apply_to_seat boolean, p_idempotency_key text) OWNER TO postgres;

--
-- Name: atomic_table_buyin(uuid, uuid, integer, numeric, boolean, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_table_buyin(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_amount numeric, p_auto_rebuy boolean DEFAULT false, p_club_id uuid DEFAULT NULL::uuid, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_request jsonb;
  v_replay jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);

  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'SESSION_REVOKED: this session is signed out - sign in again'
      USING ERRCODE = '28000';
  END IF;
  IF NOT public.fn_caller_is_engine()
     AND (auth.uid() IS NULL OR auth.uid() <> p_user_id) THEN
    RAISE EXCEPTION 'Cannot buy in for another user' USING ERRCODE = '42501';
  END IF;

  v_request := jsonb_build_object(
    'door', 'atomic_table_buyin',
    'user_id', p_user_id,
    'table_id', p_table_id,
    'seat_number', p_seat_number,
    'amount', p_amount,
    'auto_rebuy', p_auto_rebuy,
    'club_id', p_club_id
  );
  v_replay := public.fn_claim_entry_purchase_receipt(
    'cash_transaction', p_idempotency_key::text, v_request
  );
  IF NOT COALESCE((v_replay->>'claimed')::boolean, false) THEN
    RETURN;
  END IF;
  IF p_idempotency_key IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.transaction_idempotency_keys k
     WHERE k.key = p_idempotency_key
  ) THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_RECEIPT_UNBOUND: this historical cash key does not prove its table and seat'
      USING ERRCODE = '55000';
  END IF;

  IF public.fn_entry_purchases_frozen() THEN
    RAISE EXCEPTION
      'PLATFORM_FROZEN: scheduled maintenance has closed cash buy-ins; no chips moved'
      USING ERRCODE = '55006', HINT = 'Retry after the maintenance break has ended.';
  END IF;
  PERFORM public.fn_assert_cash_chip_purchase_table(p_table_id);
  PERFORM public.atomic_table_buyin_before_maintenance_announcement_gate(
    p_user_id, p_table_id, p_seat_number, p_amount, p_auto_rebuy,
    p_club_id, p_idempotency_key
  );
  PERFORM public.fn_record_entry_purchase_receipt(
    'cash_transaction',
    p_idempotency_key::text,
    v_request,
    jsonb_build_object('completed', true)
  );
END;
$$;


ALTER FUNCTION public.atomic_table_buyin(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_amount numeric, p_auto_rebuy boolean, p_club_id uuid, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: atomic_table_buyin_before_maintenance_announcement_gate(uuid, uuid, integer, numeric, boolean, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_table_buyin_before_maintenance_announcement_gate(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_amount numeric, p_auto_rebuy boolean DEFAULT false, p_club_id uuid DEFAULT NULL::uuid, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_is_template boolean;
  v_vip_only boolean;
  v_is_vip boolean;
  v_staff boolean;
  v_floor numeric;
  v_effective_min numeric;
  v_max_players integer;
  v_seats_taken integer;
  v_holds integer := 0;
  v_new_balance NUMERIC;
  v_club_id UUID;
  v_union_id UUID;
  v_ban_id UUID;
  v_min_buy_in NUMERIC;
  v_max_buy_in NUMERIC;
  v_tournament_id UUID;
  v_active_tables INT;
  v_seat_club UUID;
  v_max_tables CONSTANT INT := 4;
BEGIN
  PERFORM set_config('app.money_path', 'atomic_table_buyin', true); -- CHIP STANDARD C2: sanctioned seat creator (trg_ca_guard_seat_creation)
    -- THE ONLY IDEMPOTENCY GUARD IN THIS FUNCTION. Do not add a second one.
    IF p_idempotency_key IS NOT NULL THEN
        INSERT INTO public.transaction_idempotency_keys (key, user_id, action, amount)
        VALUES (p_idempotency_key, p_user_id, 'atomic_table_buyin', p_amount) ON CONFLICT (key) DO NOTHING;
        IF NOT FOUND THEN
            RETURN;
        END IF;
    END IF;
  -- ── A DEAD SESSION MOVES NO MONEY (Dan 2026-09-03) ────────────────────
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'SESSION_REVOKED: this session is signed out - sign in again'
      USING ERRCODE = '28000';
  END IF;
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( auth.uid() <> p_user_id)) THEN
    RAISE EXCEPTION 'Cannot buy in for another user';
  END IF;

  /* ZERO-DRIFT (2026-08-31): declare the ledger context so the wallet debit
     journals as a buy-in against the table, not an anonymous adjustment. */
  PERFORM set_config('app.ledger_category', 'buyin', true);
  PERFORM set_config('app.ledger_counterparty', 'table_stack', true);
  PERFORM set_config('app.ledger_counterparty_entity', COALESCE(p_table_id::text, ''), true);

  PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:' || p_user_id::text, 0));

  SELECT t.club_id, c.union_id, t.min_buy_in, t.max_buy_in, COALESCE(t.max_players, 0),
         COALESCE(t.is_vip_only, false), COALESCE(t.is_template, false), t.tournament_id
    INTO v_club_id, v_union_id, v_min_buy_in, v_max_buy_in, v_max_players,
         v_vip_only, v_is_template, v_tournament_id
    FROM tables t LEFT JOIN clubs c ON c.id = t.club_id
   WHERE t.id = p_table_id LIMIT 1;

  IF v_is_template THEN
    RAISE EXCEPTION 'IS_TEMPLATE: this is a saved table template, not a live game';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Invalid buy-in amount';
  END IF;
  IF v_min_buy_in IS NOT NULL AND v_min_buy_in > 0 AND p_amount < v_min_buy_in THEN
    RAISE EXCEPTION 'Buy-in below table minimum (min %)', v_min_buy_in;
  END IF;
  IF v_max_buy_in IS NOT NULL AND v_max_buy_in > 0 AND p_amount > v_max_buy_in THEN
    RAISE EXCEPTION 'Buy-in above table maximum (max %)', v_max_buy_in;
  END IF;

  /* CHIP CONTINUITY (2026-09-04, I7): the rejoin floor. Keyed on club +
     variant + sb + bb, never on this table, so it follows the player to any
     table of the same game in this club and to no other game (A0.7-A0.10).
     effective_min = min(table.max, max(table.min, required)). This replaces
     the per-table opt-in column block that stood here. */
  IF v_tournament_id IS NULL THEN
    v_floor := public.fn_cash_rejoin_floor(p_user_id, p_table_id);
    IF v_floor IS NOT NULL THEN
      v_effective_min := GREATEST(COALESCE(v_min_buy_in, 0), v_floor);
      IF v_max_buy_in IS NOT NULL AND v_max_buy_in > 0 THEN
        v_effective_min := LEAST(v_effective_min, v_max_buy_in);
      END IF;
      IF p_amount < v_effective_min THEN
        RAISE EXCEPTION 'BUYIN_BELOW_FLOOR: minimum buy-in for this game right now is %', v_effective_min
          USING HINT = 'The minimum for this game is higher for you at the moment.';
      END IF;
    END IF;
  END IF;

  IF v_club_id IS NOT NULL THEN
    SELECT id INTO v_ban_id FROM blacklists
     WHERE user_id = p_user_id
       AND (expires_at IS NULL OR expires_at > now())
       AND (club_id = v_club_id OR (v_union_id IS NOT NULL AND union_id = v_union_id))
     LIMIT 1;
    IF v_ban_id IS NOT NULL THEN
      RAISE EXCEPTION 'Banned from this club';
    END IF;
  END IF;

  IF v_vip_only THEN
    SELECT COALESCE(p.is_vip, false)
           AND (p.vip_expires_at IS NULL OR p.vip_expires_at > now())
      INTO v_is_vip
      FROM profiles p WHERE p.id = p_user_id LIMIT 1;

    IF NOT COALESCE(v_is_vip, false) AND v_club_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1 FROM club_members cm
         WHERE cm.club_id = v_club_id AND cm.user_id = p_user_id
           AND cm.role IN ('owner', 'co_owner', 'admin', 'manager', 'agent')
      ) OR EXISTS (
        SELECT 1 FROM clubs c WHERE c.id = v_club_id AND c.owner_id = p_user_id
      ) INTO v_staff;
    END IF;

    IF NOT COALESCE(v_is_vip, false) AND NOT COALESCE(v_staff, false) THEN
      RAISE EXCEPTION 'VIP_ONLY: this table is open to VIP members only'
        USING HINT = 'VIP membership is required to take a seat at this table.';
    END IF;
  END IF;

  DECLARE v_nit jsonb;
  BEGIN
    v_nit := public.fn_nit_check(p_table_id, p_user_id, NULL);
    IF (v_nit->>'ok')::boolean = false AND v_nit->>'reason' = 'career_vpip' THEN
      RAISE EXCEPTION 'NIT_GAME: this table needs a career VPIP of at least %, and yours is % over % hands',
        v_nit->>'required', v_nit->>'vpip', v_nit->>'hands'
        USING HINT = 'The host has set a minimum voluntarily-put-in-pot rate for this game.';
    END IF;
  END;

  IF EXISTS (SELECT 1 FROM table_seats
              WHERE table_id = p_table_id AND user_id = p_user_id AND left_at IS NULL) THEN
    RAISE EXCEPTION 'Player already seated at this table';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('table_seat:' || p_table_id::text, 0));

  IF v_max_players > 0 AND p_seat_number > v_max_players THEN
    RAISE EXCEPTION 'TABLE_SIZE: seat % does not exist at this table (% max)',
      p_seat_number, v_max_players;
  END IF;

  IF v_max_players > 0 THEN
    SELECT COUNT(*) INTO v_seats_taken
      FROM table_seats
     WHERE table_id = p_table_id AND left_at IS NULL;
    IF v_seats_taken >= v_max_players THEN
      RAISE EXCEPTION 'TABLE_SIZE: table is full (% of % seats taken)',
        v_seats_taken, v_max_players;
    END IF;

    SELECT COUNT(*) INTO v_holds
      FROM public.table_waitlist w
     WHERE w.table_id = p_table_id
       AND w.status = 'notified'
       AND w.user_id <> p_user_id
       AND COALESCE(w.hold_expires_at, w.notified_at + interval '60 seconds') > now();
    IF v_seats_taken + v_holds >= v_max_players THEN
      RAISE EXCEPTION 'SEAT_RESERVED: the open seat is held for the next player on the waiting list'
        USING HINT = 'Join the waitlist to get the next seat in order.';
    END IF;
  END IF;

  SELECT COUNT(*) INTO v_active_tables
    FROM table_seats ts JOIN tables t ON t.id = ts.table_id
   WHERE ts.user_id = p_user_id AND ts.left_at IS NULL
     AND t.tournament_id IS NULL AND t.status NOT IN ('closed','deleted');
  IF v_active_tables >= v_max_tables THEN
    RAISE EXCEPTION 'TABLE_CAP_REACHED: already seated at % cash tables (max %)', v_active_tables, v_max_tables;
  END IF;

  v_seat_club := public.fn_seat_club_for_user(p_user_id, p_table_id, p_club_id);
  IF v_seat_club IS NULL THEN
    RAISE EXCEPTION 'No club wallet resolves for this player at this table'
      USING HINT = 'The player must hold a membership in a club that belongs to this game''s union.';
  END IF;

  PERFORM public.fn_ensure_club_wallet(p_user_id, v_seat_club);

  UPDATE club_members
     SET chip_balance = chip_balance - p_amount, updated_at = NOW()
   WHERE user_id = p_user_id AND club_id = v_seat_club AND chip_balance >= p_amount
   RETURNING chip_balance INTO v_new_balance;

  IF v_new_balance IS NULL THEN
    RAISE EXCEPTION 'Insufficient club chips for buy-in (club %)', v_seat_club;
  END IF;

  DELETE FROM table_seats
   WHERE table_id = p_table_id AND seat_number = p_seat_number AND left_at IS NOT NULL;

  INSERT INTO table_seats (table_id, seat_number, user_id, stack, status, auto_rebuy, club_id)
       VALUES (p_table_id, p_seat_number, p_user_id, p_amount, 'active', p_auto_rebuy, v_seat_club);

  -- CHIP CONTINUITY: the session opens with the seat. baseline = this buy-in.
  PERFORM public.fn_cash_session_open(p_user_id, p_table_id, p_amount);

  UPDATE public.table_waitlist
     SET status = 'seated'
   WHERE table_id = p_table_id
     AND user_id = p_user_id
     AND status IN ('waiting', 'notified');

  INSERT INTO wallet_transactions
    (user_id, wallet_type, type, amount, category, description, table_id, balance_after)
    VALUES (p_user_id, 'PLAYER', 'debit', p_amount, 'buyin',
            'Cash game buy-in (club wallet)', p_table_id, v_new_balance);

  UPDATE tables
     SET current_players = (SELECT COUNT(*) FROM table_seats
                             WHERE table_id = p_table_id AND left_at IS NULL)
   WHERE id = p_table_id;
END;
$$;


ALTER FUNCTION public.atomic_table_buyin_before_maintenance_announcement_gate(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_amount numeric, p_auto_rebuy boolean, p_club_id uuid, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: atomic_table_cashout(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_table_cashout(p_user_id uuid, p_table_id uuid, p_seat_number integer DEFAULT NULL::integer) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_res jsonb;
BEGIN
  /* CHIP STANDARD C1 (2026-09-02): one cash-out path. This function used to
     carry its own unkeyed copy of the credit (a direct club_members write plus
     its own wallet_transactions row), so a retry of a committed-but-unacknowledged call
     credited twice. atomic_seat_cashout_locked keys the credit per seat
     occupancy (cashout:<seat id>:<joined_at>), locks the seat, closes it, and
     treats a tournament stack as play chips (no credit) - the same three
     rules this body had, minus the second copy of the money. The caller
     guard stays here so the error text is unchanged for callers. */
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( auth.uid() <> p_user_id)) THEN
    RAISE EXCEPTION 'Cannot cash out for another user';
  END IF;

  PERFORM public.fn_ca_declare_ledger('table_cashout', 'table_stack', p_table_id);

  v_res := public.atomic_seat_cashout_locked(p_user_id, p_table_id, p_seat_number);

  IF COALESCE(v_res->>'reason', '') = 'no_active_seat' THEN
    RAISE EXCEPTION 'Active seat not found for cash-out';
  END IF;

  RETURN COALESCE((v_res->>'stack')::numeric, 0);
END;
$$;


ALTER FUNCTION public.atomic_table_cashout(p_user_id uuid, p_table_id uuid, p_seat_number integer) OWNER TO postgres;

--
-- Name: FUNCTION atomic_table_cashout(p_user_id uuid, p_table_id uuid, p_seat_number integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.atomic_table_cashout(p_user_id uuid, p_table_id uuid, p_seat_number integer) IS 'BUG 018 FIX 2026-04-15 — now writes balance_after on wallet_transactions row.';


--
-- Name: atomic_table_rebuy(uuid, uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_table_rebuy(p_user_id uuid, p_table_id uuid, p_amount numeric, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_request jsonb;
  v_response jsonb;
  v_balance numeric;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);

  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'SESSION_REVOKED: this session is signed out - sign in again'
      USING ERRCODE = '28000';
  END IF;
  IF NOT public.fn_caller_is_engine()
     AND (auth.uid() IS NULL OR auth.uid() <> p_user_id) THEN
    RAISE EXCEPTION 'Cannot rebuy for another player' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NULL OR p_table_id IS NULL OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'Rebuy requires a player, table and purchase key' USING ERRCODE='22023';
  END IF;
  IF p_amount IS NULL OR p_amount::text IN ('NaN','Infinity','-Infinity')
     OR p_amount<=0 OR p_amount<>round(p_amount,2) THEN
    RAISE EXCEPTION 'Rebuy amount must be positive whole cents' USING ERRCODE='22023';
  END IF;

  v_request := jsonb_build_object(
    'door', 'atomic_table_rebuy',
    'user_id', p_user_id,
    'table_id', p_table_id,
    'amount', p_amount
  );
  v_response := public.fn_claim_entry_purchase_receipt(
    'cash_transaction', p_idempotency_key::text, v_request
  );
  IF NOT COALESCE((v_response->>'claimed')::boolean, false) THEN
    RETURN (v_response->'response'->>'balance')::numeric;
  END IF;
  IF p_idempotency_key IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.transaction_idempotency_keys k
     WHERE k.key = p_idempotency_key
  ) THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_RECEIPT_UNBOUND: this historical cash key does not prove its table'
      USING ERRCODE = '55000';
  END IF;

  IF public.fn_entry_purchases_frozen() THEN
    RAISE EXCEPTION
      'PLATFORM_FROZEN: scheduled maintenance has closed cash rebuys; no chips moved'
      USING ERRCODE = '55006', HINT = 'Retry after the maintenance break has ended.';
  END IF;
  PERFORM public.fn_assert_cash_chip_purchase_table(p_table_id);
  v_balance := public.atomic_table_rebuy_before_maintenance_announcement_gate(
    p_user_id, p_table_id, p_amount, p_idempotency_key
  );
  v_response := public.fn_record_entry_purchase_receipt(
    'cash_transaction',
    p_idempotency_key::text,
    v_request,
    jsonb_build_object('balance', v_balance)
  );
  RETURN (v_response->>'balance')::numeric;
END;
$$;


ALTER FUNCTION public.atomic_table_rebuy(p_user_id uuid, p_table_id uuid, p_amount numeric, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: atomic_table_rebuy_before_maintenance_announcement_gate(uuid, uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_table_rebuy_before_maintenance_announcement_gate(p_user_id uuid, p_table_id uuid, p_amount numeric, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_new_balance numeric; v_club_id uuid; v_union_id uuid; v_ban_id uuid; v_seat_club uuid;
  v_seat_id uuid; v_pending uuid;
  v_context jsonb; v_setting text;
BEGIN
  -- ── A DEAD SESSION MOVES NO MONEY (Dan 2026-09-03) ────────────────────
  -- "I WAS LOGGED OUT, BUT SOMEHOW ABLE TO SIT DOWN AND BUY CHIPS AND GET
  -- DEALT A HAND. THAT CAN NEVER HAPPEN." It could, because this project
  -- issues SEVEN-DAY access tokens and PostgREST verifies a JWT locally -
  -- signature and exp only. It never asks GoTrue whether the session behind
  -- that token still exists, so signing out left a bearer token that kept
  -- spending real chips as its owner for the rest of the week. The engine
  -- was never fooled (it verifies through auth.getUser, which checks the
  -- session), only the database was. fn_caller_session_is_live closes that
  -- gap at the money door itself.
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'SESSION_REVOKED: this session is signed out - sign in again'
      USING ERRCODE = '28000';
  END IF;
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( auth.uid() <> p_user_id)) THEN
    RAISE EXCEPTION 'Cannot rebuy for another player';
  END IF;

  IF p_user_id IS NULL OR p_table_id IS NULL OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'Rebuy requires a player, table and purchase key' USING ERRCODE='22023';
  END IF;
  IF p_amount IS NULL OR p_amount::text IN ('NaN','Infinity','-Infinity')
     OR p_amount<=0 OR p_amount<>round(p_amount,2) THEN
    RAISE EXCEPTION 'Rebuy amount must be positive whole cents' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.transaction_idempotency_keys(key,user_id,action,amount)
  VALUES(p_idempotency_key,p_user_id,'atomic_table_rebuy',p_amount) ON CONFLICT(key) DO NOTHING;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unbound rebuy key must be resolved by the shared purchase receipt' USING ERRCODE='55000';
  END IF;

  /* ZERO-DRIFT (2026-08-31): lock the seat so it cannot vacate between this
     check and the debit below. */
  SELECT ts.id, ts.club_id INTO v_seat_id, v_seat_club
    FROM table_seats ts
   WHERE ts.table_id = p_table_id AND ts.user_id = p_user_id AND ts.left_at IS NULL
   LIMIT 1
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Player not seated at this table (cannot rebuy a vacated seat)';
  END IF;

  SELECT t.club_id, c.union_id INTO v_club_id, v_union_id
    FROM tables t LEFT JOIN clubs c ON c.id = t.club_id WHERE t.id = p_table_id LIMIT 1;
  IF v_club_id IS NOT NULL THEN
    SELECT id INTO v_ban_id FROM blacklists
     WHERE user_id = p_user_id AND (expires_at IS NULL OR expires_at > now())
       AND (club_id = v_club_id OR (v_union_id IS NOT NULL AND union_id = v_union_id))
     LIMIT 1;
    IF v_ban_id IS NOT NULL THEN RAISE EXCEPTION 'Banned from this club'; END IF;
  END IF;

  IF v_seat_club IS NULL THEN
    v_seat_club := public.fn_seat_club_for_user(p_user_id, p_table_id, NULL);
  END IF;
  IF v_seat_club IS NULL THEN
    RAISE EXCEPTION 'No club wallet resolves for this rebuy';
  END IF;

  SELECT jsonb_object_agg(k,coalesce(current_setting(k,true),'')) INTO v_context
   FROM unnest(array['app.money_path','app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_tournament']) settings(k);
  PERFORM set_config('app.money_path','atomic_table_rebuy',true);
  PERFORM set_config('app.ledger_category','rebuy',true);
  PERFORM set_config('app.ledger_counterparty','table_stack',true);
  PERFORM set_config('app.ledger_counterparty_entity',p_table_id::text,true);
  PERFORM set_config('app.ledger_tournament','',true);
  PERFORM public.fn_ensure_club_wallet(p_user_id, v_seat_club);

  UPDATE club_members
     SET chip_balance = chip_balance - p_amount, updated_at = NOW()
   WHERE user_id = p_user_id AND club_id = v_seat_club AND chip_balance >= p_amount
   RETURNING chip_balance INTO v_new_balance;
  IF v_new_balance IS NULL THEN
    RAISE EXCEPTION 'Insufficient club chips for rebuy (club %)', v_seat_club;
  END IF;

  /* CHIP STANDARD C3 (2026-09-02): the chips do NOT go onto the seat here.
     This used to be a relative `stack + p_amount` UPDATE on table_seats,
     racing the engine's absolute writes: a rebuy committing after
     loadSeatedPlayers and before the next syncStacks was erased from the felt
     while the wallet stayed debited. The debit and this row land in ONE
     transaction; the engine's resolve_pending_addon delivers the chips into its
     own memory first and only then persists, so nothing can overwrite them. */
  INSERT INTO public.table_pending_addons (table_id, user_id, amount, kind)
  VALUES (p_table_id, p_user_id, p_amount, 'rebuy')
  RETURNING id INTO v_pending;

  INSERT INTO wallet_transactions
    (user_id, wallet_type, type, amount, category, description, table_id, balance_after)
    VALUES (p_user_id, 'PLAYER', 'debit', p_amount, 'rebuy',
            'Cash game rebuy (club wallet)', p_table_id, v_new_balance);

  FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
    PERFORM set_config(v_setting,v_context->>v_setting,true);
  END LOOP;
  RETURN v_new_balance;
END;
$$;


ALTER FUNCTION public.atomic_table_rebuy_before_maintenance_announcement_gate(p_user_id uuid, p_table_id uuid, p_amount numeric, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: atomic_tournament_register(uuid, uuid, text, numeric, numeric, numeric, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_tournament_register(p_tournament_id uuid, p_user_id uuid, p_username text, p_total_cost numeric, p_current_bounty numeric, p_mystery_bounty_value numeric, p_is_bounty_tournament boolean, p_club_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_balance NUMERIC; v_player_id UUID; v_club uuid;
  v_t_club uuid; v_t_union uuid; v_ban uuid;
BEGIN
  /* THE TOURNAMENT ROW FIRST (2026-09-06). This read the tournament without a
     lock and never looked at max_players at all, while inserting a
     tournament_players row and debiting a club wallet - and it is reachable
     from the browser. Parent before child, the order every other door uses. */
  SELECT t.club_id, t.union_id INTO v_t_club, v_t_union
    FROM tournaments t WHERE t.id = p_tournament_id
    FOR NO KEY UPDATE;

  IF public.fn_tournament_entry_cap_reached(p_tournament_id) THEN
    RAISE EXCEPTION 'Tournament full' USING ERRCODE = '23514';
  END IF;

  IF v_t_club IS NOT NULL OR v_t_union IS NOT NULL THEN
    SELECT id INTO v_ban FROM blacklists
     WHERE user_id = p_user_id AND (expires_at IS NULL OR expires_at > now())
       AND (club_id = v_t_club OR (v_t_union IS NOT NULL AND union_id = v_t_union))
     LIMIT 1;
    IF v_ban IS NOT NULL THEN RAISE EXCEPTION 'Banned from this club'; END IF;
  END IF;

  v_club := public.fn_tournament_club_for_user(p_user_id, p_tournament_id, p_club_id);
  IF v_club IS NULL THEN
    RAISE EXCEPTION 'No club wallet resolves for this tournament entry'
      USING HINT = 'The player must hold a membership in a club belonging to this tournament''s union.';
  END IF;

  PERFORM public.fn_ensure_club_wallet(p_user_id, v_club);

  SELECT chip_balance INTO v_balance FROM club_members
   WHERE user_id = p_user_id AND club_id = v_club FOR UPDATE;
  IF v_balance IS NULL OR v_balance < p_total_cost THEN
    RAISE EXCEPTION 'Insufficient club chips for tournament entry.';
  END IF;
  UPDATE club_members SET chip_balance = chip_balance - p_total_cost, updated_at = NOW()
   WHERE user_id = p_user_id AND club_id = v_club;

  IF p_is_bounty_tournament THEN
    INSERT INTO tournament_players (
      tournament_id, user_id, username, chips, status,
      current_bounty, mystery_bounty_value, bounties_collected, bounty_winnings, club_id
    ) VALUES (
      p_tournament_id, p_user_id, p_username, 0, 'registered',
      p_current_bounty, p_mystery_bounty_value, 0, 0, v_club
    ) RETURNING id INTO v_player_id;
  ELSE
    INSERT INTO tournament_players (tournament_id, user_id, username, chips, status, club_id)
    VALUES (p_tournament_id, p_user_id, p_username, 0, 'registered', v_club)
    RETURNING id INTO v_player_id;
  END IF;

  RETURN v_player_id;
END;
$$;


ALTER FUNCTION public.atomic_tournament_register(p_tournament_id uuid, p_user_id uuid, p_username text, p_total_cost numeric, p_current_bounty numeric, p_mystery_bounty_value numeric, p_is_bounty_tournament boolean, p_club_id uuid) OWNER TO postgres;

--
-- Name: atomic_wallet_transfer(uuid, uuid, numeric, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atomic_wallet_transfer(p_from_user_id uuid, p_to_user_id uuid, p_amount numeric, p_category text DEFAULT 'transfer'::text, p_debit_description text DEFAULT ''::text, p_credit_description text DEFAULT ''::text, p_related_entity_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_from_balance numeric; v_club_id uuid;
BEGIN
  SELECT balance INTO v_from_balance FROM wallets WHERE user_id = p_from_user_id AND wallet_type = 'PLAYER' FOR UPDATE;
  IF v_from_balance IS NULL OR v_from_balance < p_amount THEN RETURN false; END IF;
  UPDATE wallets SET balance = balance - p_amount, updated_at = now() WHERE user_id = p_from_user_id AND wallet_type = 'PLAYER';
  UPDATE wallets SET balance = COALESCE(balance, 0) + p_amount, updated_at = now() WHERE user_id = p_to_user_id AND wallet_type = 'PLAYER';
  IF NOT FOUND THEN
    INSERT INTO wallets (user_id, wallet_type, balance, locked_balance) VALUES (p_to_user_id, 'PLAYER', p_amount, 0)
    ON CONFLICT (user_id, wallet_type) DO UPDATE SET balance = wallets.balance + p_amount, updated_at = now();
  END IF;
  SELECT club_id INTO v_club_id FROM club_members WHERE user_id = p_from_user_id LIMIT 1;
  IF v_club_id IS NULL THEN v_club_id := 'a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid; END IF;
  INSERT INTO chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes)
  VALUES (v_club_id, p_from_user_id, p_to_user_id, p_amount, p_category, COALESCE(NULLIF(p_debit_description, ''), 'Wallet transfer'));
  RETURN true;
END; $$;


ALTER FUNCTION public.atomic_wallet_transfer(p_from_user_id uuid, p_to_user_id uuid, p_amount numeric, p_category text, p_debit_description text, p_credit_description text, p_related_entity_id uuid) OWNER TO postgres;

--
-- Name: audit_auth_integrity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audit_auth_integrity() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    real_no_profile  int := 0;
    real_no_wallet   int := 0;
    real_no_diamonds int := 0;
    sys_no_profile   int := 0;
    sys_no_wallet    int := 0;
    sys_no_diamonds  int := 0;
    total_users      int := 0;
BEGIN
    SELECT count(*) INTO total_users FROM auth.users WHERE deleted_at IS NULL;

    SELECT
        count(*) FILTER (WHERE NOT public.is_system_user(u.email) AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = u.id)),
        count(*) FILTER (WHERE NOT public.is_system_user(u.email) AND NOT EXISTS (SELECT 1 FROM public.wallets w WHERE w.user_id = u.id AND w.wallet_type = 'PLAYER')),
        count(*) FILTER (WHERE NOT public.is_system_user(u.email) AND NOT EXISTS (SELECT 1 FROM public.user_diamonds d WHERE d.user_id = u.id)),
        count(*) FILTER (WHERE public.is_system_user(u.email) AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = u.id)),
        count(*) FILTER (WHERE public.is_system_user(u.email) AND NOT EXISTS (SELECT 1 FROM public.wallets w WHERE w.user_id = u.id AND w.wallet_type = 'PLAYER')),
        count(*) FILTER (WHERE public.is_system_user(u.email) AND NOT EXISTS (SELECT 1 FROM public.user_diamonds d WHERE d.user_id = u.id))
    INTO real_no_profile, real_no_wallet, real_no_diamonds,
         sys_no_profile,  sys_no_wallet,  sys_no_diamonds
    FROM auth.users u
    WHERE u.deleted_at IS NULL;

    RETURN jsonb_build_object(
        'total_users', total_users,
        'real_orphans', jsonb_build_object(
            'no_profile',  real_no_profile,
            'no_wallet',   real_no_wallet,
            'no_diamonds', real_no_diamonds
        ),
        'system_orphans', jsonb_build_object(
            'no_profile',  sys_no_profile,
            'no_wallet',   sys_no_wallet,
            'no_diamonds', sys_no_diamonds
        ),
        'audited_at', now()
    );
END;
$$;


ALTER FUNCTION public.audit_auth_integrity() OWNER TO postgres;

--
-- Name: FUNCTION audit_auth_integrity(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.audit_auth_integrity() IS 'Counts orphan auth.users by missing-table, splitting REAL users from system/test users. Used by /api/cron/auth-integrity-audit. Real orphans alert on; system orphans are noise.';


--
-- Name: auto_add_group_owner(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_add_group_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.owner_id IS NULL THEN
    RAISE EXCEPTION 'commander_home_groups.owner_id cannot be NULL - '
      'the creator of a home game is always the top admin';
  END IF;

  INSERT INTO commander_home_members (
    group_id, user_id, role, status, joined_at, can_host, is_regular,
    notifications_enabled, notify_announcements, notify_new_games,
    notify_game_reminders, notify_rsvp_updates
  ) VALUES (
    NEW.id, NEW.owner_id, 'owner', 'approved', now(), true, true,
    true, true, true, true, true
  )
  ON CONFLICT (group_id, user_id) WHERE user_id IS NOT NULL
  DO UPDATE
    SET role = 'owner',
        status = 'approved',
        can_host = true,
        joined_at = COALESCE(commander_home_members.joined_at, now());

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.auto_add_group_owner() OWNER TO postgres;

--
-- Name: auto_audit_log(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_audit_log() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO data_audit_log (table_name, record_id, action, new_data, scrape_proof, agent_id)
    VALUES (TG_TABLE_NAME, NEW.id::text, 'INSERT',
      row_to_json(NEW)::jsonb,
      json_build_object('scrape_html_hash', NEW.scrape_html_hash, 'scrape_timestamp', NEW.scrape_timestamp)::jsonb,
      'trigger_auto');
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO data_audit_log (table_name, record_id, action, old_data, new_data, scrape_proof, agent_id)
    VALUES (TG_TABLE_NAME, NEW.id::text, 'UPDATE',
      row_to_json(OLD)::jsonb,
      row_to_json(NEW)::jsonb,
      json_build_object('scrape_html_hash', NEW.scrape_html_hash, 'scrape_timestamp', NEW.scrape_timestamp)::jsonb,
      'trigger_auto');
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO data_audit_log (table_name, record_id, action, old_data, agent_id)
    VALUES (TG_TABLE_NAME, OLD.id::text, 'DELETE', row_to_json(OLD)::jsonb, 'trigger_auto');
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


