-- Name: autofix_budget_exhausted(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.autofix_budget_exhausted(p_daily_cap_usd numeric DEFAULT 1.60) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
