$$;


ALTER FUNCTION public.autofix_budget_exhausted(p_daily_cap_usd numeric) OWNER TO postgres;

--
-- Name: FUNCTION autofix_budget_exhausted(p_daily_cap_usd numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.autofix_budget_exhausted(p_daily_cap_usd numeric) IS 'Returns true if today''s autofix spend has hit the daily cap. Default cap $1.60/day ≈ $48/month.';


--
-- Name: autofix_budget_exhausted(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.autofix_budget_exhausted(p_source text DEFAULT '_global'::text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  cap     numeric;
  spent   numeric;
  -- Claude Haiku 4.5 token pricing ($/MTok)
  price_in  numeric := 1.00;
  price_out numeric := 5.00;
begin
  select daily_cap_usd into cap
    from public.autofix_budget
   where source = p_source;
  if cap is null then
    -- Unknown source → fall back to global
    select daily_cap_usd into cap from public.autofix_budget where source = '_global';
  end if;

  select coalesce(sum(
            (coalesce(claude_tokens_in,  0)::numeric / 1000000) * price_in +
            (coalesce(claude_tokens_out, 0)::numeric / 1000000) * price_out
         ), 0)
    into spent
    from public.autofix_attempts
   where created_at >= date_trunc('day', now() at time zone 'utc')
     and (p_source = '_global' or source = p_source);

  return spent >= cap;
end;
$_$;


ALTER FUNCTION public.autofix_budget_exhausted(p_source text) OWNER TO postgres;

--
-- Name: autofix_daily_spend_usd(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.autofix_daily_spend_usd(p_day date DEFAULT ((now() AT TIME ZONE 'UTC'::text))::date) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    ROUND(
      SUM(COALESCE(claude_tokens_in, 0))::numeric  / 1000000 * 1.0
      + SUM(COALESCE(claude_tokens_out, 0))::numeric / 1000000 * 5.0
    , 4), 0
  )
  FROM public.autofix_attempts
  WHERE (created_at AT TIME ZONE 'UTC')::date = p_day
    AND claude_tokens_in IS NOT NULL;
$$;


ALTER FUNCTION public.autofix_daily_spend_usd(p_day date) OWNER TO postgres;

--
-- Name: FUNCTION autofix_daily_spend_usd(p_day date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.autofix_daily_spend_usd(p_day date) IS 'Approximate autofix Claude API spend in USD for a given UTC day, assuming Haiku 4.5 pricing ($1/$5 per MTok). Use as a circuit-breaker: if value > $1.60, halt new dispatches to stay under $50/month.';


--
-- Name: autofix_is_paused(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.autofix_is_paused() RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  select coalesce((select paused from public.autofix_config where id = 1), false);
$$;


ALTER FUNCTION public.autofix_is_paused() OWNER TO postgres;

--
-- Name: autogeocode_home_group(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.autogeocode_home_group() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  rec record;
BEGIN
  IF NEW.latitude IS NULL AND NEW.state IS NOT NULL AND trim(NEW.state) <> '' THEN
    -- Try the city table first.
    IF NEW.city IS NOT NULL AND trim(NEW.city) <> '' THEN
      SELECT lat, lng INTO rec FROM public.geocode_us_city(NEW.city, NEW.state);
      IF rec.lat IS NOT NULL THEN
        NEW.latitude  := rec.lat;
        NEW.longitude := rec.lng;
        RETURN NEW;
      END IF;
    END IF;
    -- Fallback to state center.
    SELECT lat, lng INTO rec FROM public.geocode_us_state_center(NEW.state);
    IF rec.lat IS NOT NULL THEN
      NEW.latitude  := rec.lat;
      NEW.longitude := rec.lng;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.autogeocode_home_group() OWNER TO postgres;

