--
-- Name: award_diamonds(uuid, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.award_diamonds(p_user_id uuid, p_amount integer, p_source text DEFAULT 'game_reward'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_new_balance INTEGER;
BEGIN
    IF p_amount <= 0 THEN RETURN jsonb_build_object('success', false, 'error', 'Amount must be positive'); END IF;
    UPDATE profiles SET diamonds = COALESCE(diamonds, 0) + p_amount, diamond_balance = COALESCE(diamond_balance, 0) + p_amount, updated_at = NOW()
    WHERE id = p_user_id RETURNING diamonds INTO v_new_balance;
    IF v_new_balance IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'User not found'); END IF;
    UPDATE user_diamonds SET balance = balance + p_amount, lifetime_earned = lifetime_earned + p_amount, updated_at = NOW() WHERE user_id = p_user_id;
    INSERT INTO diamond_transactions (user_id, amount, transaction_type, type, source, description, metadata, balance_after)
    VALUES (p_user_id, p_amount, p_source, 'earn', p_source, 'Diamond award: ' || p_source, p_metadata, v_new_balance);
    RETURN jsonb_build_object('success', true, 'balance', v_new_balance, 'awarded', p_amount);
END; $$;


ALTER FUNCTION public.award_diamonds(p_user_id uuid, p_amount integer, p_source text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: award_diamonds_v2(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.award_diamonds_v2(p_user_id uuid, p_action_key text, p_reference_id text DEFAULT NULL::text, p_target_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    c_catalog_version   constant integer := 3;
    c_platform_budget   constant bigint  := 2500000;

    c_login_base        constant integer := 10;
    c_login_step        constant integer := 5;
    c_login_max         constant integer := 110;

    c_egg_monthly_cap   constant integer := 1000;
    c_egg_max_single    constant integer := 1000;

    c_streak_monthly_cap       constant integer := 1000;
    c_daily_bonus_monthly_cap  constant integer := 3750;
    c_training_monthly_cap     constant integer := 1500;
    c_achievement_monthly_cap  constant integer := 1000;
    c_challenge_monthly_cap    constant integer := 1000;

    v_now               timestamptz := now();
    v_today             date;
    v_day_start         timestamptz;
    v_day_end           timestamptz;
    v_month_start       timestamptz;
    v_month_end         timestamptz;
    v_period            text;

    v_found_action      boolean;
    v_base_diamonds     integer;
    v_max_per_day       integer;
    v_counts_cap        boolean;
    v_lifetime          boolean;
    v_category          text;

    v_balance           integer := 0;
    v_multiplier        numeric(6,2) := 1.00;
    v_is_vip            boolean := false;
    v_vip_tier          text;
    v_vip_expires_at    timestamptz;

    v_daily_cap         integer;
    v_monthly_cap       integer;
    v_daily_used        integer := 0;
    v_monthly_used      integer := 0;
    v_daily_remaining   integer;
    v_monthly_remaining integer;

    v_reference_id      text;
    v_requested         integer := 0;
    v_award             integer := 0;
    v_capped            boolean := false;
    v_streak            integer := 0;
    v_action_count      integer := 0;
    v_egg_request       integer := 0;
    v_family_request    integer := 0;
    v_streak_entitlement_continuation boolean := false;
    v_streak_entitlement_initialization boolean := false;
    v_streak_milestone_days integer := 0;
    v_streak_milestone_base integer := 0;
    v_streak_entitlement integer := 0;
    v_streak_already_awarded integer := 0;
    v_streak_claim_count integer := 0;
    v_expected_streak_reference text;

    -- These values always describe the same action family. The allowance is
    -- deliberately applied only after v_requested has been multiplied.
    v_family_monthly_cap integer;
    v_family_month_total bigint := 0;
    v_family_remaining   bigint := 0;
    v_family_all_or_nothing boolean := false;

    v_budget_total      bigint;
    v_budget_spent      bigint;
    v_budget_left       bigint;
    v_new_balance       integer;
    v_metadata          jsonb;
    v_profile_rows      integer := 0;
    v_constraint_name   text;
BEGIN
    v_today       := (v_now AT TIME ZONE 'America/Chicago')::date;
    v_day_start   := v_today::timestamp AT TIME ZONE 'America/Chicago';
    v_day_end     := (v_today + 1)::timestamp AT TIME ZONE 'America/Chicago';
    v_month_start := date_trunc('month', v_today::timestamp) AT TIME ZONE 'America/Chicago';
    v_month_end   := (date_trunc('month', v_today::timestamp) + interval '1 month')
                     AT TIME ZONE 'America/Chicago';
    v_period      := to_char(v_today, 'YYYY-MM');

    IF p_user_id IS NULL OR p_action_key IS NULL OR btrim(p_action_key) = '' THEN
        RETURN jsonb_build_object(
            'success', false, 'awarded', 0, 'requested', 0,
            'reason', 'invalid_input', 'capped', false,
            'daily_remaining', 0, 'monthly_remaining', 0, 'balance_after', 0
        );
    END IF;

    v_reference_id := COALESCE(btrim(p_reference_id), '');
    v_metadata     := COALESCE(p_metadata, '{}'::jsonb);

    -- Only the server-owned milestone claim ledger may submit an amount that
    -- is already post-multiplier. The row and exact part reference are checked
    -- again below; arbitrary service callers cannot use metadata to bypass a
    -- user's multiplier or manufacture an entitlement.
    BEGIN
        v_streak_entitlement_continuation :=
            p_action_key = 'streak_reward'
            AND COALESCE(v_metadata ->> '_source', '') = 'fn_claim_training_streak_milestone_v2'
            AND COALESCE((v_metadata ->> 'post_multiplier_entitlement')::boolean, false);
        v_streak_entitlement_initialization :=
            p_action_key = 'streak_reward'
            AND COALESCE(v_metadata ->> '_source', '') = 'fn_claim_training_streak_milestone_v2'
            AND NOT v_streak_entitlement_continuation;
    EXCEPTION WHEN invalid_text_representation THEN
        v_streak_entitlement_continuation := false;
        v_streak_entitlement_initialization := false;
    END;

    -- Serialize every award for one user before reading any user-owned state.
    -- The first integer is a namespace reserved for award_diamonds_v2; a hash
    -- collision can only over-serialize two users, never weaken correctness.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        1799876946,
        pg_catalog.hashtext(p_user_id::text)
    );

    SELECT true, c.diamonds, c.max_per_day, c.counts_toward_daily_cap,
           c.lifetime, c.category
      INTO v_found_action, v_base_diamonds, v_max_per_day, v_counts_cap,
           v_lifetime, v_category
      FROM public.diamond_reward_catalog c
     WHERE c.action_key = p_action_key
       AND c.active = true;

    IF NOT FOUND OR NOT COALESCE(v_found_action, false) THEN
        RETURN jsonb_build_object(
            'success', false, 'awarded', 0, 'requested', 0,
            'reason', 'unknown_action', 'capped', false,
            'daily_remaining', 0, 'monthly_remaining', 0, 'balance_after', 0
        );
    END IF;

    -- This row lock is both a cross-function serialization boundary and the
    -- authoritative balance/multiplier snapshot used by every write below.
    SELECT COALESCE(pr.diamonds, 0),
           COALESCE(pr.diamond_multiplier, 1.00),
           COALESCE(pr.is_vip, false),
           pr.vip_tier,
           pr.vip_expires_at
      INTO v_balance, v_multiplier, v_is_vip, v_vip_tier, v_vip_expires_at
      FROM public.profiles pr
     WHERE pr.id = p_user_id
     FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false, 'awarded', 0, 'requested', 0,
            'reason', 'user_not_found', 'capped', false,
            'daily_remaining', 0, 'monthly_remaining', 0, 'balance_after', 0
        );
    END IF;

    -- Keep the currently deployed 1x..10x validation contract. Regardless of
    -- the stored multiplier, the post-multiplier caps below remain absolute.
    IF v_multiplier IS NULL OR v_multiplier <= 0 OR v_multiplier > 10 THEN
        v_multiplier := 1.00;
    END IF;

    -- COALESCE is intentional: SQL NULL must never make this VIP check fail
    -- open. The standing economy invariant inspects this exact property.
    v_is_vip := COALESCE(v_is_vip, false)
        AND (
            COALESCE(v_vip_tier, '') = 'lifetime'
            OR (v_vip_expires_at IS NOT NULL AND v_vip_expires_at > v_now)
        );

    -- Kill switch (Diamond Accounting Standard 3.4 layer 6, review D11): a human-opened
    -- diamond_issuance freeze refuses every promotional award until it is cleared.
    IF EXISTS (SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope = 'diamond_issuance' AND f.cleared_at IS NULL) THEN
        RETURN jsonb_build_object(
            'success', false, 'awarded', 0, 'requested', 0,
            'reason', 'diamond_issuance_frozen', 'capped', false,
            'daily_remaining', 0, 'monthly_remaining', 0, 'balance_after', v_balance
        );
    END IF;

    v_daily_cap   := CASE WHEN v_is_vip THEN 150 ELSE 110 END;
    v_monthly_cap := CASE WHEN v_is_vip THEN 4500 ELSE 3300 END;

    IF v_counts_cap THEN
        SELECT COALESCE(SUM(t.amount), 0)::int
          INTO v_daily_used
          FROM public.diamond_transactions t
          JOIN public.diamond_reward_catalog c ON c.action_key = t.transaction_type
         WHERE t.user_id = p_user_id
           AND t.amount > 0
           AND c.counts_toward_daily_cap = true
           AND t.created_at >= v_day_start
           AND t.created_at < v_day_end;

        SELECT COALESCE(SUM(t.amount), 0)::int
          INTO v_monthly_used
          FROM public.diamond_transactions t
          JOIN public.diamond_reward_catalog c ON c.action_key = t.transaction_type
         WHERE t.user_id = p_user_id
           AND t.amount > 0
           AND c.counts_toward_daily_cap = true
           AND t.created_at >= v_month_start
           AND t.created_at < v_month_end;
    END IF;

    v_daily_remaining   := GREATEST(v_daily_cap - v_daily_used, 0);
    v_monthly_remaining := GREATEST(v_monthly_cap - v_monthly_used, 0);

    IF v_max_per_day IS NOT NULL THEN
        SELECT COUNT(*)::int
          INTO v_action_count
          FROM public.diamond_transactions t
         WHERE t.user_id = p_user_id
           AND t.transaction_type = p_action_key
           AND t.amount > 0
           AND t.created_at >= v_day_start
           AND t.created_at < v_day_end;

        IF v_action_count >= v_max_per_day THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', 0,
                'reason', 'action_limit', 'capped', true,
                'daily_remaining', v_daily_remaining,
                'monthly_remaining', v_monthly_remaining,
                'balance_after', v_balance,
                'multiplier', v_multiplier
            );
        END IF;
    END IF;

    IF v_lifetime AND EXISTS (
        SELECT 1
          FROM public.diamond_transactions t
         WHERE t.user_id = p_user_id
           AND t.transaction_type = p_action_key
           AND t.amount > 0
    ) THEN
        RETURN jsonb_build_object(
            'success', false, 'awarded', 0, 'requested', 0,
            'reason', 'already_claimed', 'capped', false,
            'daily_remaining', v_daily_remaining,
            'monthly_remaining', v_monthly_remaining,
            'balance_after', v_balance
        );
    END IF;

    IF v_reference_id <> '' AND EXISTS (
        SELECT 1
          FROM public.diamond_transactions t
         WHERE t.user_id = p_user_id
           AND t.reference_id = v_reference_id
    ) THEN
        RETURN jsonb_build_object(
            'success', false, 'awarded', 0, 'requested', 0,
            'reason', 'duplicate', 'capped', false,
            'daily_remaining', v_daily_remaining,
            'monthly_remaining', v_monthly_remaining,
            'balance_after', v_balance
        );
    END IF;

    v_requested := COALESCE(v_base_diamonds, 0);

    IF p_action_key = 'daily_login' THEN
        BEGIN
            WITH ranked AS (
                SELECT (created_at AT TIME ZONE 'America/Chicago')::date AS d,
                       ROW_NUMBER() OVER (
                           ORDER BY (created_at AT TIME ZONE 'America/Chicago')::date DESC
                       ) AS rn
                  FROM public.diamond_transactions
                 WHERE user_id = p_user_id
                   AND transaction_type = 'daily_login'
                   AND amount > 0
                   AND (created_at AT TIME ZONE 'America/Chicago')::date < v_today
                 GROUP BY 1
            )
            SELECT COUNT(*)::int
              INTO v_streak
              FROM ranked
             WHERE d = v_today - rn;
        EXCEPTION WHEN others THEN
            v_streak := 0;
        END;

        v_streak    := v_streak + 1;
        v_requested := LEAST(c_login_base + (v_streak - 1) * c_login_step, c_login_max);

    ELSIF p_action_key = 'easter_egg' THEN
        BEGIN
            v_egg_request := COALESCE((v_metadata ->> 'egg_diamonds')::int, 0);
        EXCEPTION WHEN others THEN
            v_egg_request := 0;
        END;

        v_egg_request := LEAST(GREATEST(v_egg_request, 0), c_egg_max_single);
        v_requested := v_egg_request;
        v_family_monthly_cap := c_egg_monthly_cap;
        v_family_all_or_nothing := true;

    ELSIF p_action_key = 'streak_reward' THEN
        IF v_streak_entitlement_continuation OR v_streak_entitlement_initialization THEN
            BEGIN
                v_streak_milestone_days := COALESCE((v_metadata ->> 'milestone_days')::int, 0);
            EXCEPTION WHEN others THEN
                v_streak_milestone_days := 0;
            END;

            v_streak_milestone_base := CASE v_streak_milestone_days
                WHEN 3 THEN 25
                WHEN 7 THEN 75
                WHEN 14 THEN 150
                WHEN 30 THEN 400
                WHEN 60 THEN 800
                WHEN 100 THEN 2000
                WHEN 365 THEN 10000
                ELSE 0
            END;

            SELECT claims.entitlement_diamonds,
                   claims.diamonds_awarded,
                   claims.claim_count
              INTO v_streak_entitlement,
                   v_streak_already_awarded,
                   v_streak_claim_count
              FROM public.training_streak_milestone_claims claims
             WHERE claims.user_id = p_user_id
               AND claims.milestone_days = v_streak_milestone_days
               AND claims.completed_at IS NULL
             FOR UPDATE;

            v_expected_streak_reference := 'streak_' || p_user_id::text || '_'
                || v_streak_milestone_days::text || '_part_'
                || (v_streak_claim_count + 1)::text;
            v_family_request := CASE
                WHEN v_streak_entitlement_continuation THEN GREATEST(
                    COALESCE(v_streak_entitlement, 0)
                      - COALESCE(v_streak_already_awarded, 0),
                    0
                )
                ELSE v_streak_milestone_base
            END;

            IF NOT FOUND
               OR (
                 v_streak_entitlement_continuation
                 AND COALESCE(v_streak_entitlement, 0) <= 0
               )
               OR (
                 v_streak_entitlement_initialization
                 AND v_streak_entitlement IS NOT NULL
               )
               OR v_streak_milestone_base <= 0
               OR COALESCE(v_streak_already_awarded, 0) > v_streak_milestone_base * 10
               OR v_family_request <= 0
               OR v_family_request > 100000
               OR v_reference_id <> v_expected_streak_reference
               OR COALESCE((v_metadata ->> 'streak_diamonds')::int, -1) <> v_family_request THEN
                RETURN jsonb_build_object(
                    'success', false, 'awarded', 0, 'requested', 0,
                    'reason', 'invalid_entitlement', 'capped', false,
                    'daily_remaining', v_daily_remaining,
                    'monthly_remaining', v_monthly_remaining,
                    'balance_after', v_balance
                );
            END IF;
        ELSE
            BEGIN
                v_family_request := COALESCE((v_metadata ->> 'streak_diamonds')::int, 0);
            EXCEPTION WHEN others THEN
                v_family_request := 0;
            END;
            v_family_request := LEAST(GREATEST(v_family_request, 0), 10000);
        END IF;
        IF v_family_request <= 0 THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', v_family_request,
                'reason', 'invalid_amount', 'capped', false,
                'daily_remaining', v_daily_remaining,
                'monthly_remaining', v_monthly_remaining,
                'balance_after', v_balance
            );
        END IF;
        v_requested := v_family_request;
        v_family_monthly_cap := c_streak_monthly_cap;

    ELSIF p_action_key = 'daily_bonus' THEN
        BEGIN
            v_family_request := COALESCE((v_metadata ->> 'bonus_diamonds')::int, 0);
        EXCEPTION WHEN others THEN
            v_family_request := 0;
        END;
        v_family_request := LEAST(GREATEST(v_family_request, 0), 125);
        IF v_family_request <= 0 THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', v_family_request,
                'reason', 'invalid_amount', 'capped', false,
                'daily_remaining', v_daily_remaining,
                'monthly_remaining', v_monthly_remaining,
                'balance_after', v_balance
            );
        END IF;
        v_requested := v_family_request;
        v_family_monthly_cap := c_daily_bonus_monthly_cap;

    ELSIF p_action_key = 'training_reward' THEN
        BEGIN
            v_family_request := COALESCE((v_metadata ->> 'reward_diamonds')::int, 0);
        EXCEPTION WHEN others THEN
            v_family_request := 0;
        END;
        v_family_request := LEAST(GREATEST(v_family_request, 0), 50);
        IF v_family_request <= 0 THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', v_family_request,
                'reason', 'invalid_amount', 'capped', false,
                'daily_remaining', v_daily_remaining,
                'monthly_remaining', v_monthly_remaining,
                'balance_after', v_balance
            );
        END IF;
        v_requested := v_family_request;
        v_family_monthly_cap := c_training_monthly_cap;

    ELSIF p_action_key = 'achievement' THEN
        BEGIN
            v_family_request := COALESCE((v_metadata ->> 'achievement_diamonds')::int, 0);
        EXCEPTION WHEN others THEN
            v_family_request := 0;
        END;
        v_family_request := LEAST(GREATEST(v_family_request, 0), 500);
        IF v_family_request <= 0 THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', v_family_request,
                'reason', 'invalid_amount', 'capped', false,
                'daily_remaining', v_daily_remaining,
                'monthly_remaining', v_monthly_remaining,
                'balance_after', v_balance
            );
        END IF;
        v_requested := v_family_request;
        v_family_monthly_cap := c_achievement_monthly_cap;

    ELSIF p_action_key = 'challenge' THEN
        BEGIN
            v_family_request := COALESCE((v_metadata ->> 'challenge_diamonds')::int, 0);
        EXCEPTION WHEN others THEN
            v_family_request := 0;
        END;
        v_family_request := LEAST(GREATEST(v_family_request, 0), 500);
        IF v_family_request <= 0 THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', v_family_request,
                'reason', 'invalid_amount', 'capped', false,
                'daily_remaining', v_daily_remaining,
                'monthly_remaining', v_monthly_remaining,
                'balance_after', v_balance
            );
        END IF;
        v_requested := v_family_request;
        v_family_monthly_cap := c_challenge_monthly_cap;

    ELSIF p_action_key = 'tournament_prize' THEN
        BEGIN
            v_family_request := COALESCE((v_metadata ->> 'prize_diamonds')::int, 0);
        EXCEPTION WHEN others THEN
            v_family_request := 0;
        END;
        v_family_request := LEAST(GREATEST(v_family_request, 0), 10000);
        IF v_family_request <= 0 THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', 0,
                'reason', 'invalid_amount', 'capped', false,
                'daily_remaining', v_daily_remaining,
                'monthly_remaining', v_monthly_remaining,
                'balance_after', v_balance
            );
        END IF;
        v_requested := v_family_request;
    END IF;

    IF v_requested <= 0 THEN
        RETURN jsonb_build_object(
            'success', false, 'awarded', 0, 'requested', 0,
            'reason', 'not_eligible', 'capped', false,
            'daily_remaining', v_daily_remaining,
            'monthly_remaining', v_monthly_remaining,
            'balance_after', v_balance
        );
    END IF;

    -- This is the only multiplier application. Every family and general cap
    -- below is therefore enforced against the amount that could be credited.
    IF NOT v_streak_entitlement_continuation THEN
        v_requested := GREATEST(ROUND(v_requested * v_multiplier)::int, 1);
    END IF;

    IF v_streak_entitlement_initialization THEN
        -- Snapshot the full post-multiplier milestone entitlement only after
        -- the server-owned claim RPC proves post-epoch eligibility. Historical
        -- transaction-backed credit is then deducted exactly once; it is not
        -- multiplied a second time.
        v_streak_entitlement := GREATEST(
            v_requested,
            COALESCE(v_streak_already_awarded, 0)
        );
        IF v_streak_entitlement > v_requested THEN
            -- Historical exact-reference credit can exceed today's price when
            -- the claim-time multiplier was higher. Report an effective
            -- multiplier that reproduces the clamped integer entitlement so
            -- every replay/API response remains internally consistent.
            v_multiplier := ROUND(
                v_streak_entitlement::numeric / v_streak_milestone_base::numeric,
                6
            );
        END IF;
        v_requested := GREATEST(
            v_streak_entitlement - COALESCE(v_streak_already_awarded, 0),
            0
        );
        IF v_requested = 0 THEN
            RETURN jsonb_build_object(
                'success', true, 'awarded', 0, 'requested', 0,
                'entitlement', v_streak_entitlement,
                'reason', 'entitlement_already_paid', 'capped', false,
                'daily_remaining', v_daily_remaining,
                'monthly_remaining', v_monthly_remaining,
                'balance_after', v_balance,
                'multiplier', v_multiplier
            );
        END IF;
    END IF;
    v_award := v_requested;

    IF v_family_monthly_cap IS NOT NULL THEN
        SELECT COALESCE(SUM(t.amount), 0)::bigint
          INTO v_family_month_total
          FROM public.diamond_transactions t
         WHERE t.user_id = p_user_id
           AND t.transaction_type = p_action_key
           AND t.amount > 0
           AND t.created_at >= v_month_start
           AND t.created_at < v_month_end;

        v_family_remaining := GREATEST(
            v_family_monthly_cap::bigint - v_family_month_total,
            0::bigint
        );

        IF v_family_remaining <= 0 THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', v_requested,
                'entitlement', CASE
                    WHEN v_streak_entitlement_initialization
                      OR v_streak_entitlement_continuation
                      THEN v_streak_entitlement
                    ELSE NULL
                END,
                'reason', 'action_limit', 'capped', true,
                'daily_remaining', v_daily_remaining,
                'monthly_remaining', v_monthly_remaining,
                'balance_after', v_balance,
                'multiplier', v_multiplier
            );
        END IF;

        -- Easter eggs preserve their documented whole-award/defer behavior.
        IF v_family_all_or_nothing AND v_award::bigint > v_family_remaining THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', v_requested,
                'reason', 'action_limit', 'capped', true,
                'daily_remaining', v_daily_remaining,
                'monthly_remaining', v_monthly_remaining,
                'balance_after', v_balance
            );
        END IF;

        v_award := LEAST(v_award::bigint, v_family_remaining)::int;
    END IF;

    IF v_counts_cap THEN
        IF v_daily_remaining <= 0 THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', v_requested,
                'entitlement', CASE
                    WHEN v_streak_entitlement_initialization
                      OR v_streak_entitlement_continuation
                      THEN v_streak_entitlement
                    ELSE NULL
                END,
                'reason', 'daily_cap', 'capped', true,
                'daily_remaining', 0,
                'monthly_remaining', v_monthly_remaining,
                'balance_after', v_balance,
                'multiplier', v_multiplier
            );
        END IF;

        IF v_monthly_remaining <= 0 THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', v_requested,
                'entitlement', CASE
                    WHEN v_streak_entitlement_initialization
                      OR v_streak_entitlement_continuation
                      THEN v_streak_entitlement
                    ELSE NULL
                END,
                'reason', 'monthly_cap', 'capped', true,
                'daily_remaining', v_daily_remaining,
                'monthly_remaining', 0,
                'balance_after', v_balance,
                'multiplier', v_multiplier
            );
        END IF;

        v_award := LEAST(v_award, v_daily_remaining, v_monthly_remaining);
    END IF;

    -- RULING 21 (Dan, 2026-09-08): a platform-wide pot never refuses a player, and never
    -- quietly shrinks what they earned. This block read diamond_platform_budget FOR UPDATE,
    -- refused with 'budget_exhausted' when the shared pot was dry, and - worse - did
    --
    --     v_award := LEAST(v_award::bigint, v_budget_left)::int;
    --
    -- so a player owed 100 who arrived when the pot held 7 was paid 7, flagged `capped`, with no
    -- way to learn that the number had nothing to do with anything they had done. Both are gone.
    -- The per-user daily and monthly allowances above are the whole of the limit now, and they
    -- have already been applied to v_award.
    --
    -- v_budget_total, v_budget_spent and v_budget_left are left declared and unused rather than
    -- editing the DECLARE block of a long money function for cosmetics.
    IF v_award <= 0 THEN
            RETURN jsonb_build_object(
                'success', false, 'awarded', 0, 'requested', v_requested,
                'entitlement', CASE
                    WHEN v_streak_entitlement_initialization
                      OR v_streak_entitlement_continuation
                      THEN v_streak_entitlement
                    ELSE NULL
                END,
                'reason', 'nothing_to_award', 'capped', true,
            'daily_remaining', v_daily_remaining,
            'monthly_remaining', v_monthly_remaining,
            'balance_after', v_balance,
            'multiplier', v_multiplier
        );
    END IF;

    v_capped := v_award < v_requested;
    v_new_balance := v_balance + v_award;

    -- The running total on this one row is gone with the gate it fed. It was also the same
    -- one-hot-row-per-month shape that lost 5,860 awards to lock timeouts on the engine table
    -- this morning, so removing it takes a second contention point out of an award path. What
    -- this award cost is recorded by the journal trigger, in ca_diamond_engine_spend.

    UPDATE public.profiles
       SET diamonds = v_new_balance,
           diamond_balance = v_new_balance,
           updated_at = now()
     WHERE id = p_user_id;
    GET DIAGNOSTICS v_profile_rows = ROW_COUNT;

    IF v_profile_rows <> 1 THEN
        RAISE EXCEPTION 'award_diamonds_v2 profile row disappeared for user %', p_user_id
            USING ERRCODE = 'P0001';
    END IF;

    v_metadata := v_metadata || jsonb_build_object(
        'catalog_version', c_catalog_version,
        'action_key', p_action_key,
        'target_id', p_target_id,
        'requested', v_requested,
        'awarded', v_award,
        'capped', v_capped,
        'multiplier', v_multiplier,
        'entitlement', CASE
            WHEN v_streak_entitlement_initialization
              OR v_streak_entitlement_continuation
              THEN v_streak_entitlement
            ELSE NULL
        END,
        'category', v_category,
        'reference_id', v_reference_id,
        'streak', CASE WHEN p_action_key = 'daily_login' THEN v_streak ELSE NULL END,
        'is_vip', v_is_vip
    );

    INSERT INTO public.diamond_transactions (
        user_id, amount, transaction_type, type, description,
        balance_after, reference_id, metadata, created_at,
        counterparty, issuance_class
    ) VALUES (
        p_user_id,
        v_award,
        p_action_key,
        p_action_key,
        format(
            'Diamond Rewards v2: %s%s',
            p_action_key,
            CASE WHEN v_capped THEN ' (capped)' ELSE '' END
        ),
        v_new_balance,
        CASE WHEN v_reference_id = '' THEN NULL ELSE v_reference_id END,
        v_metadata,
        v_now,
        'promo_budget:catalog_v2',
        'promotional'
    );

    IF v_counts_cap THEN
        v_daily_remaining := GREATEST(v_daily_remaining - v_award, 0);
        v_monthly_remaining := GREATEST(v_monthly_remaining - v_award, 0);
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'awarded', v_award,
        'requested', v_requested,
        'entitlement', CASE
            WHEN v_streak_entitlement_initialization
              OR v_streak_entitlement_continuation
              THEN v_streak_entitlement
            ELSE NULL
        END,
        'reason', 'ok',
        'capped', v_capped,
        'daily_remaining', v_daily_remaining,
        'monthly_remaining', v_monthly_remaining,
        'balance_after', v_new_balance
        , 'multiplier', v_multiplier
    );

EXCEPTION
    WHEN unique_violation THEN
        -- Entering this handler rolls back every statement in the function
        -- body, including budget/profile updates. Only the two canonical
        -- reference-id idempotency indexes represent a duplicate award;
        -- unrelated uniqueness defects must stay loud and roll back.
        GET STACKED DIAGNOSTICS v_constraint_name = CONSTRAINT_NAME;
        IF v_constraint_name NOT IN (
            'idx_diamond_transactions_reference_id',
            'diamond_transactions_user_reference_uidx'
        ) THEN
            RAISE;
        END IF;
        RETURN jsonb_build_object(
            'success', false, 'awarded', 0,
            'requested', COALESCE(v_requested, 0),
            'reason', 'duplicate', 'capped', false,
            'daily_remaining', COALESCE(v_daily_remaining, 0),
            'monthly_remaining', COALESCE(v_monthly_remaining, 0),
            'balance_after', COALESCE(v_balance, 0)
        );
END;
$$;


ALTER FUNCTION public.award_diamonds_v2(p_user_id uuid, p_action_key text, p_reference_id text, p_target_id text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: FUNCTION award_diamonds_v2(p_user_id uuid, p_action_key text, p_reference_id text, p_target_id text, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.award_diamonds_v2(p_user_id uuid, p_action_key text, p_reference_id text, p_target_id text, p_metadata jsonb) IS 'Diamond Rewards v2 serialized award path. Per-user advisory and profile-row locks precede balance/cap reads; family, daily, monthly and platform caps apply to the final post-multiplier award; profile, ledger and platform writes are atomic. service_role only.';


--
-- Name: award_trivia_run(uuid, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.award_trivia_run(p_session_id uuid, p_score integer, p_correct integer, p_total integer, p_diamonds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_session public.trivia_sessions%ROWTYPE;
    v_score integer := GREATEST(0, COALESCE(p_score, 0));
    v_correct integer := GREATEST(0, COALESCE(p_correct, 0));
    v_total integer := GREATEST(0, COALESCE(p_total, 0));
    v_award integer := GREATEST(0, COALESCE(p_diamonds, 0));
    v_result jsonb;
    v_now timestamptz;
BEGIN
    IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'service_role required';
    END IF;
    IF p_session_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_session_id');
    END IF;
    IF v_correct > v_total THEN
        RETURN jsonb_build_object('success', false, 'error', 'correct_exceeds_total');
    END IF;

    -- One sampled wall-clock instant is used by both assignment and predicate;
    -- separate VOLATILE calls could straddle the exact deadline.
    v_now := clock_timestamp();
    UPDATE public.trivia_sessions
       SET status = 'submitted', submitted_at = v_now, score = v_score,
           correct_count = v_correct, diamonds_awarded = v_award
     WHERE id = p_session_id
       AND status = 'open'
       AND expires_at IS NOT NULL
       AND expires_at >= v_now
     RETURNING * INTO v_session;

    IF NOT FOUND THEN
        SELECT * INTO v_session
          FROM public.trivia_sessions
         WHERE id = p_session_id
         FOR UPDATE;
        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'error', 'session_not_found');
        END IF;
        v_now := clock_timestamp();
        IF v_session.status = 'open'
           AND (v_session.expires_at IS NULL OR v_session.expires_at < v_now) THEN
            UPDATE public.trivia_sessions
               SET status = 'expired'
             WHERE id = p_session_id
               AND status = 'open'
               AND (expires_at IS NULL OR expires_at < v_now);
            RETURN jsonb_build_object(
                'success', false,
                'error', 'session_expired',
                'expires_at', v_session.expires_at,
                'deadline_missing', v_session.expires_at IS NULL
            );
        END IF;
        RETURN jsonb_build_object('success', false, 'error',
            CASE WHEN v_session.status = 'submitted' THEN 'already_submitted' ELSE 'session_closed' END);
    END IF;

    IF v_award > 0 THEN
        SELECT public.add_diamonds_to_balance(
            v_session.user_id, v_award, 'trivia_run',
            'Trivia run reward (' || COALESCE(v_session.mode, 'unknown') || ')',
            'trivia_session_' || p_session_id::text
        ) INTO v_result;
        IF COALESCE((v_result ->> 'success')::boolean, false) IS NOT TRUE
           AND COALESCE((v_result ->> 'duplicate')::boolean, false) IS NOT TRUE THEN
            RAISE EXCEPTION 'trivia payout rejected: %', COALESCE(v_result ->> 'error', 'unknown');
        END IF;
    END IF;
    RETURN jsonb_build_object(
        'success', true, 'session_id', p_session_id, 'score', v_score,
        'correct_count', v_correct, 'diamonds_awarded', v_award,
        'deduped', COALESCE((v_result ->> 'duplicate')::boolean, false),
        'new_balance', v_result -> 'new_balance'
    );
END;
$$;


ALTER FUNCTION public.award_trivia_run(p_session_id uuid, p_score integer, p_correct integer, p_total integer, p_diamonds integer) OWNER TO postgres;

--
-- Name: FUNCTION award_trivia_run(p_session_id uuid, p_score integer, p_correct integer, p_total integer, p_diamonds integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.award_trivia_run(p_session_id uuid, p_score integer, p_correct integer, p_total integer, p_diamonds integer) IS 'Atomically closes an open trivia session and credits diamonds via add_diamonds_to_balance with an idempotent reference id. Service role only.';


--
-- Name: award_trivia_run_v2(uuid, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.award_trivia_run_v2(p_session_id uuid, p_score integer, p_correct integer, p_total integer, p_answered integer, p_diamonds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_session public.trivia_sessions%ROWTYPE;
    v_award jsonb;
    v_result jsonb;
    v_bonus jsonb;
    v_score_id uuid;
    v_existing public.trivia_scores%ROWTYPE;
    v_streak public.trivia_streaks%ROWTYPE;
    v_play_date date:=(now() AT TIME ZONE 'America/Chicago')::date;
    v_total_for_stats int;
    v_mode_cap int;
    v_earned_today int;
    v_clamped int;
    v_bonus_amount int:=0;
    v_new_streak int:=0;
    v_gap int;
    v_item_qty int;
BEGIN
    SELECT * INTO v_session FROM public.trivia_sessions WHERE id=p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','session_not_found'); END IF;
    IF v_session.user_id IS NULL THEN RETURN jsonb_build_object('success',false,'error','session_owner_missing'); END IF;
    IF v_session.status='submitted' THEN
        IF v_session.settlement_result IS NOT NULL THEN
            RETURN v_session.settlement_result || jsonb_build_object('replayed',true);
        END IF;
        SELECT id INTO v_score_id FROM public.trivia_scores WHERE session_id=p_session_id LIMIT 1;
        RETURN jsonb_build_object('success',true,'replayed',true,'session_id',p_session_id,
            'score',v_session.score,'correct_count',v_session.correct_count,
            'diamonds_awarded',COALESCE(v_session.diamonds_awarded,0),'score_id',v_score_id);
    END IF;
    IF v_session.status<>'open' THEN RETURN jsonb_build_object('success',false,'error','session_closed'); END IF;

    IF v_session.mode IN ('arcade','mtt','cash','icm','gto','mixed','endless','survival','time-attack')
       AND v_session.entry_state NOT IN ('charged','vip','continuation','ticket') THEN
        RETURN jsonb_build_object('success',false,'error','entry_not_verified');
    END IF;
    v_total_for_stats:=CASE WHEN v_session.mode IN ('endless','time-attack')
        THEN GREATEST(COALESCE(p_answered,0),COALESCE(p_correct,0))
        ELSE GREATEST(COALESCE(p_total,0),COALESCE(p_correct,0)) END;
    PERFORM pg_advisory_xact_lock(hashtextextended(
        v_session.user_id::text||':'||v_session.mode||':'||v_play_date::text,0));
    v_mode_cap:=CASE v_session.mode
        WHEN 'daily' THEN 10 WHEN 'history' THEN 10 WHEN 'rules' THEN 10 WHEN 'pro' THEN 10
        WHEN 'arcade' THEN 40 WHEN 'survival' THEN 80 WHEN 'mtt' THEN 40
        WHEN 'cash' THEN 40 WHEN 'icm' THEN 40 WHEN 'gto' THEN 60
        WHEN 'mixed' THEN 40 WHEN 'endless' THEN 40 WHEN 'time-attack' THEN 40 ELSE 0 END;
    SELECT COALESCE(sum(diamonds_awarded),0)::int INTO v_earned_today
      FROM public.trivia_sessions WHERE user_id=v_session.user_id AND mode=v_session.mode
       AND status='submitted'
       AND (COALESCE(submitted_at,created_at) AT TIME ZONE 'America/Chicago')::date=v_play_date;
    v_clamped:=LEAST(GREATEST(COALESCE(p_diamonds,0),0),GREATEST(v_mode_cap-v_earned_today,0));

    SELECT public.award_trivia_run(p_session_id,p_score,p_correct,p_total,v_clamped) INTO v_award;
    IF COALESCE((v_award->>'success')::boolean,false) IS NOT TRUE THEN RETURN v_award; END IF;

    IF v_session.mode='daily' THEN
        SELECT * INTO v_existing FROM public.trivia_scores
         WHERE user_id=v_session.user_id AND mode='daily' AND play_date=v_play_date
         ORDER BY created_at LIMIT 1 FOR UPDATE;
        IF FOUND THEN
            IF v_existing.server_verified IS NOT TRUE OR COALESCE(p_score,0)>COALESCE(v_existing.score,0) THEN
                UPDATE public.trivia_scores SET score=GREATEST(COALESCE(p_score,0),0),
                    correct_count=GREATEST(COALESCE(p_correct,0),0),total_questions=v_total_for_stats,
                    diamonds_earned=v_clamped,session_id=p_session_id,server_verified=true
                 WHERE id=v_existing.id RETURNING id INTO v_score_id;
            ELSE
                v_score_id:=v_existing.id;
            END IF;
        ELSE
            INSERT INTO public.trivia_scores(user_id,username,mode,score,correct_count,total_questions,
                diamonds_earned,play_date,session_id,server_verified)
            SELECT v_session.user_id,p.username,'daily',GREATEST(COALESCE(p_score,0),0),
                GREATEST(COALESCE(p_correct,0),0),v_total_for_stats,v_clamped,v_play_date,p_session_id,true
              FROM public.profiles p WHERE p.id=v_session.user_id RETURNING id INTO v_score_id;
        END IF;
    ELSE
        INSERT INTO public.trivia_scores(user_id,username,mode,score,correct_count,total_questions,
            diamonds_earned,play_date,session_id,server_verified)
        SELECT v_session.user_id,p.username,v_session.mode,GREATEST(COALESCE(p_score,0),0),
            GREATEST(COALESCE(p_correct,0),0),v_total_for_stats,v_clamped,v_play_date,p_session_id,true
          FROM public.profiles p WHERE p.id=v_session.user_id RETURNING id INTO v_score_id;
    END IF;
    IF v_score_id IS NULL THEN RAISE EXCEPTION 'profile_not_found_for_trivia_score'; END IF;

    -- Streak totals now follow the verified settlement path. A shield protects
    -- exactly one missed day and its consumption has an immutable ledger row.
    SELECT * INTO v_streak FROM public.trivia_streaks WHERE user_id=v_session.user_id FOR UPDATE;
    IF NOT FOUND THEN
        v_new_streak:=CASE WHEN v_session.mode='daily' THEN 1 ELSE 0 END;
        INSERT INTO public.trivia_streaks(user_id,current_streak,best_streak,last_play_date,
            total_games_played,total_correct,updated_at)
        VALUES(v_session.user_id,v_new_streak,v_new_streak,
            CASE WHEN v_session.mode='daily' THEN v_play_date ELSE NULL END,
            1,GREATEST(COALESCE(p_correct,0),0),now());
    ELSE
        v_new_streak:=COALESCE(v_streak.current_streak,0);
        IF v_session.mode='daily' AND v_streak.last_play_date IS DISTINCT FROM v_play_date THEN
            v_gap:=CASE WHEN v_streak.last_play_date IS NULL THEN NULL ELSE v_play_date-v_streak.last_play_date END;
            IF v_gap IS NULL THEN v_new_streak:=1;
            ELSIF v_gap=1 THEN v_new_streak:=v_new_streak+1;
            ELSIF v_gap=2 THEN
                UPDATE public.trivia_user_items SET quantity=quantity-1,updated_at=now()
                 WHERE user_id=v_session.user_id AND item_type='streak_shield' AND quantity>0
                RETURNING quantity INTO v_item_qty;
                IF FOUND THEN
                    v_new_streak:=v_new_streak+1;
                    INSERT INTO public.trivia_item_transactions(
                        user_id,item_type,amount,balance_after,transaction_type,reference_id,metadata)
                    VALUES(v_session.user_id,'streak_shield',-1,v_item_qty,'streak_protection',
                        'trivia_shield_'||p_session_id::text,jsonb_build_object('session_id',p_session_id));
                ELSE v_new_streak:=1; END IF;
            ELSE v_new_streak:=1; END IF;
        END IF;
        UPDATE public.trivia_streaks SET current_streak=v_new_streak,
            best_streak=GREATEST(COALESCE(best_streak,0),v_new_streak),
            last_play_date=CASE WHEN v_session.mode='daily' THEN v_play_date ELSE last_play_date END,
            total_games_played=COALESCE(total_games_played,0)+1,
            total_correct=COALESCE(total_correct,0)+GREATEST(COALESCE(p_correct,0),0),updated_at=now()
         WHERE user_id=v_session.user_id;
    END IF;

    IF v_session.mode='daily' AND COALESCE(p_total,0)>=10 AND COALESCE(p_answered,0)>=p_total THEN
        SELECT public.add_diamonds_to_balance(v_session.user_id,10,'trivia_daily_bonus',
            'Daily trivia completion bonus','trivia_daily_bonus_'||v_session.user_id::text||'_'||v_play_date::text)
          INTO v_bonus;
        IF COALESCE((v_bonus->>'success')::boolean,false) IS TRUE THEN v_bonus_amount:=10;
        ELSIF COALESCE((v_bonus->>'duplicate')::boolean,false) IS NOT TRUE THEN
            RAISE EXCEPTION 'daily bonus rejected: %',COALESCE(v_bonus->>'error','unknown');
        END IF;
    END IF;

    v_result:=v_award||jsonb_build_object('score_id',v_score_id,
        'daily_bonus_awarded',v_bonus_amount,
        'new_balance',COALESCE(v_bonus->'new_balance',v_award->'new_balance'),
        'replayed',false);
    UPDATE public.trivia_sessions SET settlement_result=v_result WHERE id=p_session_id;
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.award_trivia_run_v2(p_session_id uuid, p_score integer, p_correct integer, p_total integer, p_answered integer, p_diamonds integer) OWNER TO postgres;

--
-- Name: balance_tournament_tables(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.balance_tournament_tables(p_tournament_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_min_players integer;
  v_max_players integer;
  v_imbalanced integer := 0;
BEGIN
  IF p_tournament_id IS NULL THEN RETURN 0; END IF;
  SELECT MIN(c), MAX(c) INTO v_min_players, v_max_players FROM (
    SELECT COUNT(*) AS c FROM public.table_seats ts
      JOIN public.tables t ON t.id = ts.table_id
     WHERE t.tournament_id = p_tournament_id AND ts.left_at IS NULL
     GROUP BY ts.table_id
  ) sub;
  IF v_max_players IS NULL OR v_min_players IS NULL THEN RETURN 0; END IF;
  IF v_max_players - v_min_players > 1 THEN
    v_imbalanced := v_max_players - v_min_players;
    UPDATE public.tournaments SET updated_at = NOW() WHERE id = p_tournament_id;
  END IF;
  RETURN v_imbalanced;
END $$;


ALTER FUNCTION public.balance_tournament_tables(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: bbj_atomic_payout(uuid, uuid, bigint, numeric, uuid, uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bbj_atomic_payout(p_pool_id uuid, p_table_id uuid, p_hand_number bigint, p_payout_total_percent numeric, p_loser_user_id uuid, p_winner_user_id uuid, p_dealt_in_count integer, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(applied boolean, already_paid boolean, payout_id uuid, total_payout numeric, loser_share numeric, winner_share numeric, table_share numeric, balance_after numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN RAISE EXCEPTION 'bbj_atomic_payout retired 2026-08-18 - use bbj_atomic_payout_v2'; END;
$$;


ALTER FUNCTION public.bbj_atomic_payout(p_pool_id uuid, p_table_id uuid, p_hand_number bigint, p_payout_total_percent numeric, p_loser_user_id uuid, p_winner_user_id uuid, p_dealt_in_count integer, p_metadata jsonb) OWNER TO postgres;

--
-- Name: bbj_atomic_payout_v2(uuid, uuid, bigint, numeric, uuid, uuid, uuid[], uuid[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bbj_atomic_payout_v2(p_pool_id uuid, p_table_id uuid, p_hand_number bigint, p_payout_total_percent numeric, p_loser_user_id uuid, p_winner_user_id uuid, p_dealt_in_ids uuid[], p_seated_ids uuid[], p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(applied boolean, already_paid boolean, recovered boolean, payout_id uuid, total_payout numeric, loser_share numeric, winner_share numeric, table_share numeric, per_player_share numeric, balance_after numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_main numeric; v_backup numeric;
  v_total numeric; v_loser numeric; v_winner numeric; v_table numeric;
  v_per numeric; v_remainder numeric; v_payout_id uuid; v_existing uuid;
  v_club_id uuid; v_pre_hit_balance numeric; v_winner_name text; v_loser_name text;
  v_table_ids uuid[]; v_n_table integer; v_recovered boolean := false; v_uid uuid;
  v_hand_id uuid; v_pending record; v_reserved numeric;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'bbj_atomic_payout_v2 is service only' USING ERRCODE = '42501';
  END IF;
  IF p_payout_total_percent IS NULL OR p_payout_total_percent <= 0 OR p_payout_total_percent > 100 THEN
    RAISE EXCEPTION 'bbj payout percent % out of range (0,100]', p_payout_total_percent;
  END IF;
  /* PHASE 6.2 (2026-09-05): the kill switch. An open freeze on jackpot payouts
     refuses the payout with a message the engine's queue retries (it retries
     everything but 'out of range', 'service only' and 42501), so a jackpot
     hit during a freeze is paid the moment the freeze is cleared. */
  IF EXISTS (SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope = 'bbj_payouts' AND f.cleared_at IS NULL) THEN
    RAISE EXCEPTION 'payout_frozen: jackpot payouts are frozen by the kill switch (ca_payout_freeze scope bbj_payouts); the engine retries when it is cleared'
      USING ERRCODE = 'P0404';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_table_ids
    FROM unnest(COALESCE(p_dealt_in_ids, ARRAY[]::uuid[])) AS x
   WHERE x IS NOT NULL AND x <> p_loser_user_id AND x <> p_winner_user_id;
  v_n_table := COALESCE(array_length(v_table_ids, 1), 0);

  IF p_pool_id IS NULL OR p_table_id IS NULL OR p_hand_number IS NULL
     OR p_loser_user_id IS NULL OR p_winner_user_id IS NULL
     OR p_loser_user_id = p_winner_user_id THEN
    RAISE EXCEPTION 'main jackpot requires a hand and two distinct recipients' USING ERRCODE='22023';
  END IF;
  -- Allocation and replay share the pool lock before reading the hand key.
  PERFORM 1 FROM public.bbj_pools WHERE id=p_pool_id FOR UPDATE;
  SELECT id INTO v_existing FROM bbj_payouts
   WHERE pool_id = p_pool_id AND table_id = p_table_id AND hand_number = p_hand_number LIMIT 1;

  IF v_existing IS NOT NULL THEN
    SELECT bp.total_amount, bp.loser_share, bp.winner_share, bp.table_share, bp.table_player_count
      INTO v_total, v_loser, v_winner, v_table, v_n_table FROM bbj_payouts bp WHERE bp.id=v_existing;
    v_per := CASE WHEN v_n_table>0 THEN v_table/v_n_table ELSE 0 END;
    -- Only durable unpaid obligations can authorize a recovery credit.
    -- Caller-supplied players/amounts never create recipients on replay.
    FOR v_pending IN SELECT u.user_id,u.amount FROM public.bbj_unclaimed_shares u
      WHERE u.payout_id=v_existing AND u.paid_at IS NULL ORDER BY u.user_id
    LOOP
      IF public.bbj_credit_one_recipient(v_existing,p_table_id,v_pending.user_id,v_pending.amount,
        EXISTS(SELECT 1 FROM public.table_seats s WHERE s.table_id=p_table_id
          AND s.user_id=v_pending.user_id AND s.left_at IS NULL)) THEN v_recovered:=true; END IF;
    END LOOP;

    -- A replay is also the second chance to attach the hand: on the first pass
    -- the hand_history insert may have been the step that failed.
    UPDATE bbj_payouts bp
       SET hand_id = h.id
      FROM public.hand_history h
     WHERE bp.id = v_existing AND bp.hand_id IS NULL
       AND h.table_id = p_table_id AND h.hand_number = p_hand_number;

    RETURN QUERY SELECT false, true, v_recovered, v_existing, v_total, v_loser, v_winner, v_table, v_per, NULL::numeric;
    RETURN;
  END IF;

  SELECT main_balance, COALESCE(backup_balance,0) INTO v_main, v_backup FROM bbj_pools WHERE id = p_pool_id FOR UPDATE;
  v_reserved := public.fn_bbj_parked_reserve(p_pool_id,'main');
  v_main := v_main-v_reserved;
  IF v_main IS NULL OR v_main <= 0 THEN
    RETURN QUERY SELECT false, false, false, NULL::uuid, 0::numeric,0::numeric,0::numeric,0::numeric,0::numeric, COALESCE(v_main,0);
    RETURN;
  END IF;

  v_pre_hit_balance := v_main;
  v_total  := ROUND(v_main * (p_payout_total_percent / 100.0), 2);
  -- CLAMP TO MAIN ONLY. The backup jackpot is a reserve and is never a payout
  -- source (Dan, 2026-08-18). This replaces the earlier LEAST(v_total,
  -- main+backup), which had authorised spending the reserve.
  v_total  := LEAST(v_total, v_main);
  v_loser  := ROUND(v_total * 0.50, 2);
  v_winner := ROUND(v_total * 0.25, 2);
  v_table  := ROUND(v_total - v_loser - v_winner, 2);
  IF v_n_table > 0 THEN v_per := ROUND(v_table / v_n_table, 2); ELSE v_per := 0; END IF;
  v_remainder := ROUND(v_table - (v_per * v_n_table), 2);
  v_loser := v_loser + v_remainder;
  v_table := v_per * v_n_table;

  -- THE HAND. Written before the payout by postHandTasks, so it is normally
  -- here. NULL when that step failed, which is exactly the case worth being
  -- able to see.
  SELECT h.id INTO v_hand_id FROM public.hand_history h
   WHERE h.table_id = p_table_id AND h.hand_number = p_hand_number
   ORDER BY h.created_at DESC LIMIT 1;

  INSERT INTO bbj_payouts (pool_id, hand_id, table_id, hand_number, winner_user_id, loser_user_id,
    total_amount, winner_share, loser_share, table_share, table_player_count, metadata)
  VALUES (p_pool_id, v_hand_id, p_table_id, p_hand_number, p_loser_user_id, p_winner_user_id,
    v_total, v_winner, v_loser, v_table, v_n_table, COALESCE(p_metadata, '{}'::jsonb))
  ON CONFLICT (pool_id, table_id, hand_number) DO NOTHING RETURNING id INTO v_payout_id;

  IF v_payout_id IS NULL THEN
    RETURN QUERY SELECT false, true, false, NULL::uuid, 0::numeric,0::numeric,0::numeric,0::numeric,0::numeric, v_main;
    RETURN;
  END IF;

  /* THE PAYOUT IS DECLARED (chip standard Phase 4.3, 2026-09-04): the main
     jackpot pays the felt of the hitting table. Seated recipients hold their
     share on that felt; a departed recipient's share leaves the felt for the
     wallet in bbj_credit_one_recipient, declared there. Before today this
     debit fell to settlement_suspense. */
  PERFORM public.fn_ca_declare_ledger('bbj_payout', 'table_stack', p_table_id, NULL,
                                      'bbj_payout:' || v_payout_id::text, NULL);
  -- MAIN ONLY. backup_balance is deliberately absent from this statement: a
  -- jackpot payout must never touch the reserve.
  UPDATE bbj_pools
     SET main_balance   = GREATEST(0, main_balance - v_total),
         total_paid_out = COALESCE(total_paid_out, 0) + v_total,
         hit_count      = COALESCE(hit_count, 0) + 1,
         last_hit_at    = now(), last_hit_amount = v_total,
         last_winner_id = p_loser_user_id, last_loser_id = p_winner_user_id, updated_at = now()
   WHERE id = p_pool_id RETURNING main_balance, club_id INTO v_main, v_club_id;
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_idempotency_key', '', true);

  -- RESEED (Dan 2026-08-18): the back-up jackpot exists so that when a hit
  -- takes 100% of main, the jackpot does not restart at zero. If main is now
  -- empty, TRANSFER the reserve into it. A transfer, not a payout: no player
  -- is ever paid from the reserve, and chips are conserved. Recorded as a
  -- bank move; an empty reserve raises an incident (Phase 4.3).
  IF v_main <= v_reserved THEN
    v_main := GREATEST(v_main, public.fn_bbj_reseed_main_from_backup(p_pool_id));
  END IF;

  PERFORM public.bbj_credit_one_recipient(v_payout_id, p_table_id, p_loser_user_id, v_loser, p_loser_user_id = ANY(p_seated_ids));
  PERFORM public.bbj_credit_one_recipient(v_payout_id, p_table_id, p_winner_user_id, v_winner, p_winner_user_id = ANY(p_seated_ids));
  FOREACH v_uid IN ARRAY v_table_ids LOOP
    PERFORM public.bbj_credit_one_recipient(v_payout_id, p_table_id, v_uid, v_per, v_uid = ANY(p_seated_ids));
  END LOOP;

  SELECT public.fn_arena_name(alias, username, display_name, first_name, last_name, full_name) INTO v_winner_name FROM profiles WHERE id = p_loser_user_id;
  SELECT public.fn_arena_name(alias, username, display_name, first_name, last_name, full_name) INTO v_loser_name FROM profiles WHERE id = p_winner_user_id;

  /* THE CLUB THE HAND WAS PLAYED IN (BBJ audit 2026-09-05). A union pool has
     no club_id of its own, so v_club_id from the pool row above is NULL for
     every union hit and the Previous Winners row said the jackpot happened
     nowhere. The hitting table always knows its club. */
  SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = p_table_id AND t.club_id IS NOT NULL;
  IF v_club_id IS NULL THEN
    SELECT bp2.club_id INTO v_club_id FROM public.bbj_pools bp2 WHERE bp2.id = p_pool_id;
  END IF;
  INSERT INTO bbj_winners (pool_id, club_id, winner_id, loser_id, winner_display_name, loser_display_name,
    winner_hand, loser_hand, winner_payout, loser_payout, table_share_payout, total_payout,
    pool_amount_at_hit, table_id, hand_number, awarded_at)
  VALUES (p_pool_id, v_club_id, p_loser_user_id, p_winner_user_id, v_winner_name, v_loser_name,
    COALESCE(p_metadata->>'winner_hand_name', 'Unknown'), COALESCE(p_metadata->>'loser_hand_name', 'Unknown'),
    v_loser, v_winner, v_table, v_total, v_pre_hit_balance, p_table_id, p_hand_number, now())
  ON CONFLICT DO NOTHING;

  RETURN QUERY SELECT true, false, false, v_payout_id, v_total, v_loser, v_winner, v_table, v_per, v_main;
END;
$$;


ALTER FUNCTION public.bbj_atomic_payout_v2(p_pool_id uuid, p_table_id uuid, p_hand_number bigint, p_payout_total_percent numeric, p_loser_user_id uuid, p_winner_user_id uuid, p_dealt_in_ids uuid[], p_seated_ids uuid[], p_metadata jsonb) OWNER TO postgres;

--
-- Name: bbj_credit_one_recipient(uuid, uuid, uuid, numeric, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bbj_credit_one_recipient(p_payout_id uuid, p_table_id uuid, p_user_id uuid, p_amount numeric, p_seated boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_claimed integer; v_club uuid; v_after numeric; v_key text; v_park_pool uuid; v_kind text; v_parked numeric; v_paid_at timestamptz;
  v_on_felt boolean := false;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'bbj_credit_one_recipient is service only' USING ERRCODE = '42501';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN false;
  END IF;

  -- All recipient transitions serialize on the same pool lock as allocation.
  SELECT bp.pool_id, bp.kind INTO v_park_pool, v_kind
    FROM public.bbj_payouts bp WHERE bp.id=p_payout_id AND bp.table_id=p_table_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'jackpot payout/table identity mismatch'; END IF;
  PERFORM 1 FROM public.bbj_pools WHERE id=v_park_pool FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'jackpot funding pool missing'; END IF;
  SELECT u.amount,u.paid_at INTO v_parked,v_paid_at
    FROM public.bbj_unclaimed_shares u
   WHERE u.payout_id=p_payout_id AND u.user_id=p_user_id FOR UPDATE;
  IF v_parked IS NOT NULL AND v_parked <> p_amount THEN
    RAISE EXCEPTION 'parked jackpot amount cannot change on replay';
  END IF;
  IF v_paid_at IS NOT NULL THEN RETURN false; END IF;

  INSERT INTO bbj_payout_recipients (payout_id, user_id, amount)
  VALUES (p_payout_id, p_user_id, p_amount)
  ON CONFLICT (payout_id, user_id) DO NOTHING;
  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 0 THEN
    RETURN false;  -- already credited under this payout
  END IF;

  IF p_seated THEN
    -- The felt is a derived account: the pool debit (bbj_pool -> table_stack)
    -- is the leg, and the seat row simply holds the chips. Delta-mode hand
    -- writes preserve a credit the engine has not seen yet.
    UPDATE table_seats
       SET stack = COALESCE(stack, 0) + p_amount
     WHERE table_id = p_table_id AND user_id = p_user_id AND left_at IS NULL;
    GET DIAGNOSTICS v_claimed = ROW_COUNT;
    IF v_claimed > 1 THEN RAISE EXCEPTION 'multiple active seats for jackpot recipient'; END IF;
    IF v_claimed = 1 THEN
      v_on_felt := true;
    END IF;
    -- Seat vanished since the engine snapshot: fall through to the wallet.
  END IF;

  IF NOT v_on_felt THEN
  /* A departed recipient is paid to the wallet of the TABLE's club - the one
     the seat was bought in from - never to a "home" club. Keyed, so a replay
     of the payout cannot pay twice; declared as the felt paying out to the
     wallet, which is what the pool debit already put on the felt. */
  v_key := 'bbj:' || p_payout_id::text || ':' || p_user_id::text;
  INSERT INTO public.wallet_credit_idempotency (key, user_id, amount)
  VALUES (v_key, p_user_id, p_amount)
  ON CONFLICT (key) DO NOTHING;
  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 0 THEN
    RETURN false;
  END IF;

  /* THE SEAT'S CLUB FIRST (BBJ audit 2026-09-05). On a union table the
     table belongs to the union's shell club and the player is a member of
     SHARK CLUB or Club JAQK - table_seats.club_id says which one the buy-in
     came from. Resolving tables.club_id first picked the shell club, no
     club_members row matched, the UPDATE below took nothing, the RAISE fired,
     and the entire jackpot payout rolled back unpaid. Every candidate is
     checked for an active membership so a club that cannot take the credit is
     never chosen. */
  SELECT s.club_id INTO v_club FROM public.table_seats s
   WHERE s.table_id = p_table_id AND s.user_id = p_user_id AND s.club_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.club_members cm
                  WHERE cm.user_id = p_user_id AND cm.club_id = s.club_id
                    AND cm.status IN ('active', 'approved'))
   ORDER BY s.joined_at DESC LIMIT 1;
  IF v_club IS NULL THEN
    SELECT t.club_id INTO v_club FROM public.tables t
     WHERE t.id = p_table_id AND t.club_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.club_members cm
                    WHERE cm.user_id = p_user_id AND cm.club_id = t.club_id
                      AND cm.status IN ('active', 'approved'));
  END IF;
  IF v_club IS NULL THEN
    v_club := public.fn_player_home_club(p_user_id, NULL);
  END IF;
  /* PARKED, NOT RAISED (BBJ phase 2.3, 2026-09-06). This used to raise, and
     because every credit runs inside bbj_atomic_payout_v2's single
     transaction, that rolled back the ENTIRE jackpot: the bad-beat holder,
     the hand winner and the whole table were paid nothing because ONE
     table-share recipient held no club membership anywhere. Release the
     claim so a later re-drive can still pay them, hand the chips back to the
     pool they left moments ago in this same transaction (conservation stays
     exact), and record the debt as data. */
  IF v_club IS NULL THEN
    DELETE FROM public.bbj_payout_recipients
     WHERE payout_id = p_payout_id AND user_id = p_user_id;
    DELETE FROM public.wallet_credit_idempotency WHERE key = v_key;

    -- The durable parking row owns the refund. A retry that finds the row
    -- cannot return the same money to the bank a second time.
    INSERT INTO public.bbj_unclaimed_shares (payout_id,pool_id,table_id,user_id,amount,reason)
    VALUES (p_payout_id,v_park_pool,p_table_id,p_user_id,p_amount,
      'no club wallet resolved; share returned once to its funding bank and remains owed')
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_claimed = ROW_COUNT;
    IF v_claimed = 1 THEN
      PERFORM public.fn_ca_declare_ledger('bbj_payout','table_stack',p_table_id,NULL,
        'bbj_park:' || v_key,NULL);
      UPDATE public.bbj_pools
         SET main_balance=main_balance + CASE WHEN v_kind='mini' THEN 0 ELSE p_amount END,
             backup_balance=backup_balance + CASE WHEN v_kind='mini' THEN p_amount ELSE 0 END,
             total_paid_out=total_paid_out-p_amount, updated_at=now()
       WHERE id=v_park_pool;
      PERFORM set_config('app.ledger_category','',true);
      PERFORM set_config('app.ledger_counterparty','',true);
      PERFORM set_config('app.ledger_counterparty_entity','',true);
      PERFORM set_config('app.ledger_idempotency_key','',true);
    END IF;

    RAISE WARNING 'bbj_credit_one_recipient: parked % for % (no club wallet resolves at table %); the rest of the payout stands',
      p_amount, p_user_id, p_table_id;
    RETURN false;
  END IF;
  PERFORM public.fn_ensure_club_wallet(p_user_id, v_club);
  PERFORM public.fn_ca_declare_ledger('bbj_payout', 'table_stack', p_table_id, NULL, v_key, NULL);
  UPDATE public.club_members
     SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = now()
   WHERE user_id = p_user_id AND club_id = v_club
   RETURNING chip_balance INTO v_after;
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_idempotency_key', '', true);
  IF v_after IS NULL THEN
    RAISE EXCEPTION 'bbj_credit_one_recipient: the club wallet for % in % did not take the credit', p_user_id, v_club;
  END IF;
  INSERT INTO public.chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after, table_id)
  VALUES (v_club, NULL, p_user_id, p_amount, 'bbj_payout',
          'Bad Beat Jackpot share paid to your club wallet (you had left the table)', v_after, p_table_id);
  END IF;

  -- A previously parked share is NOT still funded on the felt. Its returned
  -- amount must leave the same bank in the same transaction as this credit.
  -- Failure rolls back the seat/wallet credit and its idempotency claims.
  IF v_parked IS NOT NULL THEN
    PERFORM public.fn_ca_declare_ledger('bbj_payout','table_stack',p_table_id,NULL,
      'bbj_redeem:' || p_payout_id::text || ':' || p_user_id::text,NULL);
    UPDATE public.bbj_pools
       SET main_balance=main_balance - CASE WHEN v_kind='mini' THEN 0 ELSE p_amount END,
           backup_balance=backup_balance - CASE WHEN v_kind='mini' THEN p_amount ELSE 0 END,
           total_paid_out=total_paid_out+p_amount, updated_at=now()
     WHERE id=v_park_pool
       AND CASE WHEN v_kind='mini' THEN backup_balance ELSE main_balance END >= p_amount;
    IF NOT FOUND THEN RAISE EXCEPTION 'parked jackpot share lacks its original funding'; END IF;
    PERFORM set_config('app.ledger_category','',true);
    PERFORM set_config('app.ledger_counterparty','',true);
    PERFORM set_config('app.ledger_counterparty_entity','',true);
    PERFORM set_config('app.ledger_idempotency_key','',true);
    UPDATE public.bbj_unclaimed_shares SET paid_at=now(),
      paid_note=CASE WHEN v_on_felt THEN 'credited to table seat; funding reclaimed once'
                    ELSE 'credited to club wallet; funding reclaimed once' END
     WHERE payout_id=p_payout_id AND user_id=p_user_id;
  END IF;
  RETURN true;
END;
$$;


ALTER FUNCTION public.bbj_credit_one_recipient(p_payout_id uuid, p_table_id uuid, p_user_id uuid, p_amount numeric, p_seated boolean) OWNER TO postgres;

--
-- Name: bbj_drift_since(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bbj_drift_since(p_since timestamp with time zone) RETURNS TABLE(booked numeric, received numeric, booked_rows bigint, received_rows bigint, unlinkable_rows bigint, unlinkable_chips numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH r AS (
    SELECT hand_id, bbj_contribution
    FROM rake_records
    WHERE created_at >= p_since
      AND bbj_contribution > 0
  ),
  settled AS (
    -- 6 minutes: STRICTLY GREATER than fn_bbj_repair_unbanked's 5-minute
    -- grace. An alarm that judges hands its own healer is still waiting on
    -- reports the healer's patience as a shortfall.
    SELECT hand_id, bbj_contribution
    FROM rake_records
    WHERE created_at >= p_since
      AND created_at < now() - interval '6 minutes'
      AND bbj_contribution > 0
      AND hand_id IS NOT NULL
  ),
  j AS (
    -- Join by hand, never by a second time window (2026-08-30): a slice
    -- banked late by a self-heal still belongs to its hand.
    SELECT s.bbj_contribution AS booked,
           COALESCE((SELECT sum(b.amount) FROM bbj_contributions b
                      WHERE b.hand_id = s.hand_id), 0) AS received
    FROM settled s
  )
  SELECT
    COALESCE(sum(j.booked), 0)::numeric,
    COALESCE(sum(j.received), 0)::numeric,
    count(*)::bigint,
    count(*) FILTER (WHERE j.received > 0)::bigint,
    (SELECT count(*) FROM r WHERE r.hand_id IS NULL)::bigint,
    COALESCE((SELECT sum(r.bbj_contribution) FROM r WHERE r.hand_id IS NULL), 0)::numeric
  FROM j;
$$;


ALTER FUNCTION public.bbj_drift_since(p_since timestamp with time zone) OWNER TO postgres;

