)
WITH (autovacuum_enabled='true', autovacuum_analyze_scale_factor='0.0', autovacuum_analyze_threshold='2000', autovacuum_vacuum_scale_factor='0.0', autovacuum_vacuum_threshold='2000', autovacuum_vacuum_cost_delay='2', autovacuum_vacuum_cost_limit='2000');


ALTER TABLE public.bbj_contributions OWNER TO postgres;

--
-- Name: TABLE bbj_contributions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.bbj_contributions IS 'Per-HAND jackpot funding ledger (one row per hand, three bank portions). Per-PLAYER BBJ attribution lives in rake_attributions.bbj_attributed_contribution (weighted by eligible contribution, Dan 2026-08-29) and rolls up into bbj_daily_user. The never-written player_id column was dropped 2026-08-30.';


--
-- Name: bbj_record_contribution(uuid, uuid, uuid, numeric, numeric, numeric, numeric, numeric, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bbj_record_contribution(p_pool_id uuid, p_hand_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid, p_amount numeric DEFAULT 0, p_main_portion numeric DEFAULT 0, p_backup_portion numeric DEFAULT 0, p_promo_portion numeric DEFAULT 0, p_big_blind numeric DEFAULT 2.00, p_hand_number integer DEFAULT NULL::integer, p_club_id uuid DEFAULT NULL::uuid) RETURNS public.bbj_contributions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
    v_contribution bbj_contributions;
    v_prev_cum numeric;
    v_main_now numeric;
    v_main     numeric;
    v_backup   numeric;
    v_promo    numeric;
    v_context jsonb;
    v_setting text;
BEGIN
    IF p_pool_id IS NULL OR p_amount IS NULL OR p_amount::text IN ('NaN','Infinity','-Infinity')
       OR p_amount <= 0 OR p_amount <> round(p_amount, 2)
       OR (p_hand_id IS NULL AND (p_table_id IS NULL OR p_hand_number IS NULL)) THEN
        RAISE EXCEPTION 'BBJ contribution requires a stable hand identity and positive whole-cent amount'
            USING ERRCODE = '22023';
    END IF;

    -- Identity is independent of its destination. Serialize a retry before
    -- reading the receipt, including requests that have no history UUID.
    IF p_hand_id IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('bbj:hand:' || p_hand_id::text, 0));
    END IF;
    IF p_table_id IS NOT NULL AND p_hand_number IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended(
            'bbj:table-hand:' || p_table_id::text || ':' || p_hand_number::text, 0));
    END IF;

    SELECT COALESCE(alloc_cum_amount, 0), COALESCE(main_balance, 0) INTO v_prev_cum, v_main_now
      FROM bbj_pools WHERE id = p_pool_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'bbj_record_contribution: pool % not found', p_pool_id;
    END IF;

    SELECT * INTO v_contribution FROM bbj_contributions
     WHERE (p_hand_id IS NOT NULL AND hand_id = p_hand_id)
        OR (p_table_id IS NOT NULL AND p_hand_number IS NOT NULL
            AND table_id = p_table_id AND hand_number = p_hand_number)
     ORDER BY created_at LIMIT 1;
    IF v_contribution.id IS NOT NULL THEN
        IF v_contribution.hand_id IS DISTINCT FROM p_hand_id
           OR v_contribution.pool_id IS DISTINCT FROM p_pool_id
           OR v_contribution.table_id IS DISTINCT FROM p_table_id
           OR v_contribution.club_id IS DISTINCT FROM p_club_id
           OR v_contribution.amount IS DISTINCT FROM p_amount
           OR v_contribution.big_blind IS DISTINCT FROM p_big_blind
           OR v_contribution.hand_number IS DISTINCT FROM p_hand_number THEN
            RAISE EXCEPTION 'BBJ contribution identity reused with a different payment payload'
                USING ERRCODE = '22023';
        END IF;
        RETURN v_contribution;
    END IF;

    /* ONE ALLOCATOR (chip standard Phase 4.3, 2026-09-04). The split is the
       policy's, read against the pool's main balance under the lock, with the
       pool's rounding residue carried so the long-run split is exact. The
       caller's p_main_portion / p_backup_portion / p_promo_portion are
       accepted for the signature's sake and ignored. alloc_cum_amount is kept
       running for continuity; it no longer decides anything. */
    SELECT a.main_portion, a.backup_portion, a.promo_portion INTO v_main, v_backup, v_promo
      FROM public.fn_bbj_allocate(COALESCE(p_amount, 0), v_main_now, p_pool_id) a;

    INSERT INTO bbj_contributions (
        pool_id, hand_id, table_id, club_id, amount,
        main_portion, backup_portion, promo_portion, big_blind, hand_number
    ) VALUES (
        p_pool_id, p_hand_id, p_table_id, p_club_id, p_amount,
        v_main, v_backup, v_promo, p_big_blind, p_hand_number
    )
    RETURNING * INTO v_contribution;

    /* ZERO-DRIFT (2026-08-31): the pool credit below auto-journals via
       trg_ca_autoledger; declare what it is. */
    SELECT jsonb_object_agg(k, COALESCE(current_setting(k, true), '')) INTO v_context
      FROM unnest(ARRAY['app.ledger_category','app.ledger_counterparty',
                       'app.ledger_counterparty_entity','app.ledger_settlement',
                       'app.ledger_hand_id']) AS settings(k);
    PERFORM set_config('app.ledger_category', 'bbj_contribution', true);
    PERFORM set_config('app.ledger_counterparty', 'table_stack', true);
    PERFORM set_config('app.ledger_counterparty_entity', COALESCE(p_table_id::text, ''), true);
    -- PHASE 6.4 (2026-09-05): the drop's legs name the hand.
    PERFORM set_config('app.ledger_settlement', CASE WHEN p_hand_id IS NULL THEN '' ELSE 'bbj:' || p_hand_id::text END, true);
    PERFORM set_config('app.ledger_hand_id', COALESCE(p_hand_id::text, ''), true);

    UPDATE bbj_pools
    SET
        main_balance      = main_balance   + v_main,
        backup_balance    = backup_balance + v_backup,
        promo_balance     = promo_balance  + v_promo,
        total_contributed = total_contributed + p_amount,
        alloc_cum_amount  = v_prev_cum + COALESCE(p_amount, 0),
        hands_contributed = COALESCE(hands_contributed, 0) + 1,
        updated_at        = now()
    WHERE id = p_pool_id;

    FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
        PERFORM set_config(v_setting, v_context->>v_setting, true);
    END LOOP;

    RETURN v_contribution;
END;
$$;


ALTER FUNCTION public.bbj_record_contribution(p_pool_id uuid, p_hand_id uuid, p_table_id uuid, p_amount numeric, p_main_portion numeric, p_backup_portion numeric, p_promo_portion numeric, p_big_blind numeric, p_hand_number integer, p_club_id uuid) OWNER TO postgres;

--
-- Name: bbj_record_table_contribution(uuid, uuid, integer, numeric, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bbj_record_table_contribution(p_table_id uuid, p_club_id uuid, p_hand_number integer, p_amount numeric, p_big_blind numeric, p_hand_id uuid DEFAULT NULL::uuid) RETURNS public.bbj_contributions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    SET statement_timeout TO '30s'
    AS $$
DECLARE v_club uuid; v_pool uuid;
BEGIN
 IF p_table_id IS NULL OR p_club_id IS NULL OR p_hand_number IS NULL THEN
  RAISE EXCEPTION 'BBJ table payment requires table, club and hand number' USING ERRCODE='22023';
 END IF;
 -- The same identity locks as the underlying posting function: a retry
 -- retains its original pool even if the club changes union membership.
 IF p_hand_id IS NOT NULL THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('bbj:hand:' || p_hand_id::text, 0));
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(
  'bbj:table-hand:' || p_table_id::text || ':' || p_hand_number::text, 0));

 SELECT club_id INTO v_club FROM public.tables WHERE id=p_table_id FOR SHARE;
 IF NOT FOUND OR v_club IS DISTINCT FROM p_club_id THEN
  RAISE EXCEPTION 'BBJ table does not belong to the supplied club' USING ERRCODE='22023';
 END IF;
 SELECT pool_id INTO v_pool FROM public.bbj_contributions
 WHERE (p_hand_id IS NOT NULL AND hand_id=p_hand_id)
    OR (table_id=p_table_id AND hand_number=p_hand_number)
 ORDER BY created_at LIMIT 1;
 IF v_pool IS NULL THEN
  v_pool := public.fn_resolve_bbj_pool(p_table_id, p_club_id);
 END IF;
 RETURN public.bbj_record_contribution(
  v_pool,p_hand_id,p_table_id,p_amount,0,0,0,p_big_blind,p_hand_number,p_club_id);
END;
$$;


ALTER FUNCTION public.bbj_record_table_contribution(p_table_id uuid, p_club_id uuid, p_hand_number integer, p_amount numeric, p_big_blind numeric, p_hand_id uuid) OWNER TO postgres;

--
-- Name: block_user(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.block_user(p_blocked_user_id uuid, p_caller_user_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;
    IF p_caller_user_id = p_blocked_user_id THEN
        RAISE EXCEPTION 'CANNOT_BLOCK_SELF';
    END IF;

    INSERT INTO user_blocks (blocker_id, blocked_id, reason)
    VALUES (p_caller_user_id, p_blocked_user_id, p_reason)
    ON CONFLICT (blocker_id, blocked_id) DO UPDATE
        SET reason = EXCLUDED.reason;

    RETURN jsonb_build_object('success', true, 'blocked_user_id', p_blocked_user_id);
END;
$$;


ALTER FUNCTION public.block_user(p_blocked_user_id uuid, p_caller_user_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: broadcast_to_home_game_rsvps(uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.broadcast_to_home_game_rsvps(p_game_id uuid, p_message text, p_caller_user_id uuid, p_include_maybe boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_game RECORD; v_group RECORD; v_slug text;
    v_recipient RECORD; v_sent int := 0;
    v_title text;
    v_role text := auth.role();
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
      RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;
    IF p_message IS NULL OR length(trim(p_message)) = 0 THEN
      RAISE EXCEPTION 'EMPTY_MESSAGE';
    END IF;
    IF length(p_message) > 1000 THEN RAISE EXCEPTION 'MESSAGE_TOO_LONG'; END IF;

    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;

    IF v_game.host_id <> p_caller_user_id AND v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members
                        WHERE group_id = v_game.group_id AND user_id = p_caller_user_id
                          AND role = 'admin' AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;

    -- Pass 46.1 BJ-2: atomic rate limit, 10/hr per caller (service_role bypass)
    IF v_role IS DISTINCT FROM 'service_role' AND NOT public.fn_try_consume_home_rate_limit(
         p_caller_user_id, 'home_broadcast_game', 10, 60) THEN
      RAISE EXCEPTION 'RATE_LIMIT_EXCEEDED'
        USING HINT = 'Host broadcasts limited to 10 per hour per sender.';
    END IF;

    SELECT sp.slug INTO v_slug FROM social_pages sp
     WHERE sp.linked_entity_type='home_group' AND sp.linked_entity_id=v_group.id::text LIMIT 1;

    v_title := 'Host message: ' || COALESCE(v_game.title, v_group.name);

    FOR v_recipient IN
        SELECT DISTINCT user_id FROM commander_home_rsvps
         WHERE game_id = p_game_id
           AND ( response = 'yes' OR (p_include_maybe AND response = 'maybe') )
    LOOP
        PERFORM public.fn_emit_home_notification(
            v_recipient.user_id, 'home_game_host_broadcast',
            v_title, LEFT(p_message, 500),
            '/hub/home-games/' || COALESCE(v_slug, v_group.id::text),
            jsonb_build_object('game_id', p_game_id, 'from_host', p_caller_user_id, 'full_message', p_message),
            NULL
        );
        v_sent := v_sent + 1;
    END LOOP;

    INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (v_group.id, p_caller_user_id, 'game', p_game_id, 'host_broadcast',
            jsonb_build_object('recipients', v_sent, 'preview', LEFT(p_message, 100)));

    RETURN jsonb_build_object('success', true, 'recipients_count', v_sent);
END;
$$;


ALTER FUNCTION public.broadcast_to_home_game_rsvps(p_game_id uuid, p_message text, p_caller_user_id uuid, p_include_maybe boolean) OWNER TO postgres;

--
-- Name: FUNCTION broadcast_to_home_game_rsvps(p_game_id uuid, p_message text, p_caller_user_id uuid, p_include_maybe boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.broadcast_to_home_game_rsvps(p_game_id uuid, p_message text, p_caller_user_id uuid, p_include_maybe boolean) IS 'Phase 40: fixed AND/OR precedence that caused p_include_maybe=true to broadcast to every ''maybe''-RSVPer platform-wide instead of just this game.';


--
-- Name: broadcast_to_home_group_roster(uuid, uuid, text, text, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.broadcast_to_home_group_roster(p_group_id uuid, p_caller_user_id uuid, p_title text, p_body text, p_include_members boolean DEFAULT true, p_include_followers boolean DEFAULT true, p_link_path text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
    v_caller uuid := auth.uid();
    v_role   text := auth.role();
    v_group  RECORD;
    v_recipient uuid;
    v_members_sent int := 0;
    v_followers_sent int := 0;
    v_slug text;
    v_link text;
BEGIN
    IF v_role IS DISTINCT FROM 'service_role' THEN
      IF v_caller IS NULL OR v_caller <> p_caller_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'AUTH_MISMATCH');
      END IF;
    END IF;

    IF COALESCE(TRIM(p_title), '') = '' OR COALESCE(TRIM(p_body), '') = '' THEN
      RETURN jsonb_build_object('success', false, 'error', 'MISSING_TITLE_OR_BODY');
    END IF;
    IF length(p_title) > 200 OR length(p_body) > 2000 THEN
      RETURN jsonb_build_object('success', false, 'error', 'CONTENT_TOO_LONG');
    END IF;
    IF p_include_members = false AND p_include_followers = false THEN
      RETURN jsonb_build_object('success', false, 'error', 'NO_AUDIENCE');
    END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'GROUP_NOT_FOUND');
    END IF;

    IF NOT (
      v_group.owner_id = p_caller_user_id
      OR EXISTS (SELECT 1 FROM commander_home_members
                  WHERE group_id = p_group_id AND user_id = p_caller_user_id
                    AND role = 'admin' AND status = 'approved')
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'NOT_GROUP_STAFF');
    END IF;

    IF v_role IS DISTINCT FROM 'service_role' AND NOT public.fn_try_consume_home_rate_limit(
         p_caller_user_id, 'home_broadcast_group', 5, 60) THEN
      RETURN jsonb_build_object(
        'success', false, 'error', 'RATE_LIMIT_EXCEEDED',
        'detail', 'Group broadcasts limited to 5 per hour per sender.'
      );
    END IF;

    SELECT sp.slug INTO v_slug FROM social_pages sp
     WHERE sp.linked_entity_type='home_group'
       AND sp.linked_entity_id = p_group_id::text LIMIT 1;

    v_link := COALESCE(p_link_path,
                       '/hub/home-games/' || COALESCE(v_slug, p_group_id::text));

    IF p_include_members THEN
      FOR v_recipient IN
        SELECT m.user_id FROM commander_home_members m
         WHERE m.group_id = p_group_id AND m.status = 'approved'
           AND m.user_id <> p_caller_user_id
           AND COALESCE(m.notify_announcements, true) = true
      LOOP
        PERFORM public.fn_emit_home_notification(
            v_recipient, 'home_group_announcement',
            v_group.name || ': ' || p_title, p_body, v_link,
            jsonb_build_object('group_id', p_group_id, 'via', 'announcement'),
            'home_game_announcements'
        );
        v_members_sent := v_members_sent + 1;
      END LOOP;
    END IF;

    IF p_include_followers THEN
      FOR v_recipient IN
        SELECT f.user_id FROM commander_home_group_follows f
         WHERE f.group_id = p_group_id
           AND f.notify_announcements = true
           AND f.user_id <> p_caller_user_id
           AND (NOT p_include_members
                OR NOT EXISTS (SELECT 1 FROM commander_home_members m
                                WHERE m.group_id = p_group_id
                                  AND m.user_id = f.user_id
                                  AND m.status = 'approved'))
      LOOP
        PERFORM public.fn_emit_home_notification(
            v_recipient, 'home_group_announcement_followed',
            v_group.name || ': ' || p_title, p_body, v_link,
            jsonb_build_object('group_id', p_group_id, 'via', 'follow'),
            NULL
        );
        v_followers_sent := v_followers_sent + 1;
      END LOOP;
    END IF;

    -- ★ NEW: audit-log the broadcast (recipient counts + content preview only)
    INSERT INTO public.commander_home_audit_log
      (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (p_group_id, p_caller_user_id, 'group', p_group_id, 'roster_broadcast',
            jsonb_build_object(
              'members_notified',   v_members_sent,
              'followers_notified', v_followers_sent,
              'title',              LEFT(p_title, 100),
              'body_preview',       LEFT(p_body,  200)));

    RETURN jsonb_build_object(
      'success', true,
      'members_notified', v_members_sent,
      'followers_notified', v_followers_sent,
      'total', v_members_sent + v_followers_sent
    );
END;
$$;


ALTER FUNCTION public.broadcast_to_home_group_roster(p_group_id uuid, p_caller_user_id uuid, p_title text, p_body text, p_include_members boolean, p_include_followers boolean, p_link_path text) OWNER TO postgres;

--
-- Name: FUNCTION broadcast_to_home_group_roster(p_group_id uuid, p_caller_user_id uuid, p_title text, p_body text, p_include_members boolean, p_include_followers boolean, p_link_path text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.broadcast_to_home_group_roster(p_group_id uuid, p_caller_user_id uuid, p_title text, p_body text, p_include_members boolean, p_include_followers boolean, p_link_path text) IS 'Phase 40: host fan-out push/in-app notification to roster. Independent toggles for members vs followers. Respects per-row notify_announcements.';


--
-- Name: bump_challenge_progress(uuid, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bump_challenge_progress(p_user_id uuid, p_amounts jsonb, p_magnitudes jsonb, p_daily_key text, p_weekly_key text, p_monthly_key text) RETURNS TABLE(id uuid, challenge_id text, progress integer, requirement integer, chip_reward numeric, newly_completed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'Daily Missions progress requires a trusted server event'
      USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT event.id, event.challenge_id, event.progress, event.requirement,
         event.chip_reward, event.newly_completed
  FROM public.record_daily_challenge_event(
    p_user_id,
    'legacy:' || gen_random_uuid()::text,
    p_amounts,
    COALESCE(p_magnitudes, '{}'::jsonb),
    now()
  ) event;
END;
$$;


ALTER FUNCTION public.bump_challenge_progress(p_user_id uuid, p_amounts jsonb, p_magnitudes jsonb, p_daily_key text, p_weekly_key text, p_monthly_key text) OWNER TO postgres;

--
-- Name: bump_daily_challenge_dashboard_revision(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bump_daily_challenge_dashboard_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_revision bigint;
BEGIN
  IF TG_TABLE_NAME = 'profiles' THEN
    v_user_id := NEW.id;
  ELSIF TG_OP = 'DELETE' THEN
    v_user_id := OLD.user_id;
  ELSE
    v_user_id := NEW.user_id;
  END IF;

  -- Cascading account deletion removes the profile before child triggers run.
  -- A cursor for a deleted user is unusable and would violate the cursor FK.
  IF v_user_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = v_user_id) THEN
    INSERT INTO public.daily_challenge_dashboard_revisions (user_id, revision, updated_at)
    VALUES (v_user_id, 1, clock_timestamp())
    ON CONFLICT (user_id) DO UPDATE
      SET revision = public.daily_challenge_dashboard_revisions.revision + 1,
          updated_at = EXCLUDED.updated_at
    RETURNING revision INTO v_revision;

    BEGIN
      PERFORM realtime.send(
        jsonb_build_object('revision', v_revision),
        'daily_mission_revision_changed',
        'daily-mission-revision:' || v_user_id::text,
        true
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Daily Mission revision broadcast failed: %', SQLERRM;
    END;

    IF TG_TABLE_NAME = 'user_daily_challenges' THEN
      IF TG_OP = 'UPDATE'
         AND OLD.completed IS NOT TRUE
         AND NEW.completed IS TRUE THEN
        BEGIN
          PERFORM realtime.send(
            jsonb_build_object(
              'id', NEW.id,
              'challengeId', NEW.challenge_id,
              'name', NEW.challenge_name_snapshot,
              'diamondReward', NEW.diamond_reward_snapshot
            ),
            'daily_mission_completed',
            'daily-mission-completion:' || v_user_id::text,
            true
          );
        EXCEPTION WHEN OTHERS THEN
          RAISE WARNING 'Daily Mission completion broadcast failed: %', SQLERRM;
        END;
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.bump_daily_challenge_dashboard_revision() OWNER TO postgres;

