--
-- Name: ca_can_read_club_production(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_can_read_club_production(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    public.ca_can_view_club_finances(p_club_id)
    -- Overseeing a union the club belongs to. Scoped through union_clubs, so
    -- it never reaches a club that is not in a union this caller oversees.
    OR EXISTS (
      SELECT 1 FROM union_clubs uc
       WHERE uc.club_id = p_club_id
         AND public.fn_is_union_overseer(uc.union_id, auth.uid())
    );
$$;


ALTER FUNCTION public.ca_can_read_club_production(p_club_id uuid) OWNER TO postgres;

--
-- Name: ca_can_view_club(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_can_view_club(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    session_user IN ('postgres', 'supabase_admin')
    OR coalesce(auth.role(), '') = 'service_role'
    OR (
      auth.uid() IS NOT NULL
      AND (
        EXISTS (
          SELECT 1 FROM club_members cm
          WHERE cm.club_id = p_club_id
            AND cm.user_id = auth.uid()
            AND coalesce(cm.status, 'active') NOT IN ('banned', 'suspended')
        )
        OR EXISTS (
          SELECT 1 FROM clubs c WHERE c.id = p_club_id AND c.owner_id = auth.uid()
        )
        OR EXISTS (
          SELECT 1 FROM profiles pr
          WHERE pr.id = auth.uid() AND coalesce(pr.is_admin, false)
        )
      )
    );
$$;


ALTER FUNCTION public.ca_can_view_club(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION ca_can_view_club(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_can_view_club(p_club_id uuid) IS 'May the caller read this club? Internal callers (postgres, supabase_admin, service_role) yes; otherwise a signed-in non-banned member, the club owner, or a platform admin. Since 2026-09-04 a caller with no account is refused rather than admitted.';


--
-- Name: ca_can_view_club_finances(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_can_view_club_finances(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    session_user IN ('postgres', 'supabase_admin')
    OR coalesce(auth.role(), '') = 'service_role'
    OR (
      auth.uid() IS NOT NULL
      AND (
        EXISTS (
          SELECT 1 FROM club_members cm
           WHERE cm.club_id = p_club_id
             AND cm.user_id = auth.uid()
             AND coalesce(cm.status, 'active') NOT IN ('banned', 'suspended')
             AND cm.role IN ('owner', 'co_owner', 'admin', 'super_agent')
        )
        OR EXISTS (SELECT 1 FROM clubs c WHERE c.id = p_club_id AND c.owner_id = auth.uid())
        OR EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = auth.uid() AND coalesce(pr.is_admin, false))
      )
    );
$$;


ALTER FUNCTION public.ca_can_view_club_finances(p_club_id uuid) OWNER TO postgres;

