-- Name: FUNCTION ca_can_view_club_finances(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_can_view_club_finances(p_club_id uuid) IS 'May the caller read this club''s money? Internal callers yes; otherwise a signed-in owner / co_owner / admin / super_agent, the club owner, or a platform admin. Since 2026-09-04 a caller with no account is refused rather than admitted.';


--
-- Name: ca_club_activity(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_activity(p_club_id uuid, p_limit integer DEFAULT 20) RETURNS TABLE(id text, activity_type text, message text, created_at timestamp with time zone, user_id uuid, display_name text, avatar_url text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF NOT ca_can_view_club(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH events AS (
    (SELECT
       'join-' || cm.user_id::text AS id,
       'member_join'::text         AS activity_type,
       'joined the club'::text     AS message,
       cm.created_at               AS created_at,
       cm.user_id                  AS user_id
     FROM club_members cm
     WHERE cm.club_id = p_club_id
       AND cm.created_at > now() - interval '30 days'
     ORDER BY cm.created_at DESC
     LIMIT 50)
    UNION ALL
    (SELECT
       'ann-' || an.id::text,
       'announcement',
       coalesce(nullif(an.title, ''), left(coalesce(an.content, an.message, 'New announcement'), 120)),
       an.created_at,
       coalesce(an.author_id, an.created_by)
     FROM club_announcements an
     WHERE an.club_id = p_club_id
       AND an.created_at > now() - interval '30 days'
       AND coalesce(an.is_active, true)
     ORDER BY an.created_at DESC
     LIMIT 20)
    UNION ALL
    (SELECT
       'hand-' || hh.id::text,
       'big_hand',
       'won a ' || to_char(coalesce(hh.pot_size, 0), 'FM999,999,990.00') || ' pot'
         || CASE WHEN hh.hand_name IS NOT NULL THEN ' with ' || hh.hand_name ELSE '' END,
       hh.created_at,
       CASE
         WHEN (hh.winners->0->>'userId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
         THEN (hh.winners->0->>'userId')::uuid
         ELSE NULL
       END
     FROM hand_history hh
     JOIN tables t ON t.id = hh.table_id
     WHERE t.club_id = p_club_id
       AND hh.created_at > now() - interval '48 hours'
       AND coalesce(hh.pot_size, 0) >= 40 * greatest(coalesce(hh.big_blind, 0.02), 0.02)
     ORDER BY hh.created_at DESC
     LIMIT 30)
    UNION ALL
    (SELECT
       'table-' || t.id::text,
       'table_start',
       'Table "' || coalesce(t.name, 'Unnamed') || '" was created',
       t.created_at,
       t.created_by
     FROM tables t
     WHERE t.club_id = p_club_id
       AND t.created_at > now() - interval '7 days'
       AND coalesce(t.is_deleted, false) = false
     ORDER BY t.created_at DESC
     LIMIT 10)
  )
  SELECT
    e.id, e.activity_type, e.message, e.created_at, e.user_id,
    public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                         pr.first_name, pr.last_name, pr.full_name),
    pr.avatar_url
  FROM events e
  LEFT JOIN profiles pr ON pr.id = e.user_id
  WHERE e.created_at IS NOT NULL
  ORDER BY e.created_at DESC
  LIMIT least(greatest(coalesce(p_limit, 20), 1), 100);
END;
$_$;


ALTER FUNCTION public.ca_club_activity(p_club_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: ca_club_chip_ledger(uuid, integer, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_chip_ledger(p_club_id uuid, p_limit integer DEFAULT 25, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_include_hand_rows boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer := GREATEST(LEAST(coalesce(p_limit, 25), 100), 1);
  v jsonb;
BEGIN
  IF NOT ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  WITH page AS (
    SELECT l.id, l.performed_by, l.from_type, l.from_entity_id, l.from_label,
           l.to_type, l.to_entity_id, l.to_label, l.amount, l.category,
           l.description, l.created_at, l.club_id, l.union_id, l.table_id,
           l.tournament_id, l.status
      FROM chip_ledger l
     WHERE l.club_id = p_club_id
       AND (p_before IS NULL OR l.created_at < p_before)
       AND (coalesce(p_include_hand_rows, false)
            OR l.category NOT IN ('rake', 'bbj_contribution'))
     ORDER BY l.created_at DESC
     LIMIT v_limit + 1
  )
  SELECT jsonb_build_object(
    'rows', coalesce((
      SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at DESC)
      FROM (SELECT * FROM page ORDER BY created_at DESC LIMIT v_limit) p
    ), '[]'::jsonb),
    'has_more', (SELECT count(*) FROM page) > v_limit,
    'next_before', (SELECT min(p.created_at) FROM (SELECT * FROM page ORDER BY created_at DESC LIMIT v_limit) p),
    'hand_rows_included', coalesce(p_include_hand_rows, false),
    'generated_at', now()
  ) INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION public.ca_club_chip_ledger(p_club_id uuid, p_limit integer, p_before timestamp with time zone, p_include_hand_rows boolean) OWNER TO postgres;

--
-- Name: ca_club_dashboard_stats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_dashboard_stats(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
  v_today date := (now() AT TIME ZONE 'UTC')::date;
BEGIN
  IF NOT ca_can_view_club(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  WITH days AS (
    SELECT g.day::date AS d,
           coalesce(h.hands, 0)::bigint AS hands,
           coalesce(r.rake, 0)::numeric AS rake,
           coalesce(r.hands, 0)::bigint AS raked_hands,
           coalesce(m.fee, 0)::numeric AS tournament_fees
    FROM generate_series(v_today - 13, v_today, interval '1 day') g(day)
    LEFT JOIN club_hand_daily h ON h.club_id = p_club_id AND h.stat_date = g.day::date
    LEFT JOIN ca_club_rake_daily r ON r.club_id = p_club_id AND r.stat_date = g.day::date
    LEFT JOIN (
      SELECT t.stat_date, sum(t.fee) AS fee FROM ca_club_tournament_daily t
       WHERE t.club_id = p_club_id AND t.stat_date >= v_today - 13
       GROUP BY t.stat_date
    ) m ON m.stat_date = g.day::date
  )
  SELECT jsonb_build_object(
    'total_members', (
      SELECT count(*) FROM club_members cm
      WHERE cm.club_id = p_club_id
        AND coalesce(cm.status, 'active') NOT IN ('banned', 'suspended')
    ),
    'online_now', (
      SELECT count(*) FROM (
        SELECT ts.user_id
        FROM table_seats ts
        JOIN tables t ON t.id = ts.table_id
        WHERE t.club_id = p_club_id AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
        UNION
        SELECT cm.user_id FROM club_members cm
        WHERE cm.club_id = p_club_id
          AND cm.last_active > now() - interval '15 minutes'
      ) x
    ),
    'active_tables', (
      SELECT count(*) FROM tables t
      WHERE t.club_id = p_club_id AND t.status IN ('running', 'waiting', 'active')
    ),
    'total_tables', (
      SELECT count(*) FROM tables t
      WHERE t.club_id = p_club_id
        AND (coalesce(t.is_deleted, false) = false OR t.status IN ('running', 'waiting', 'active'))
    ),
    'hands_today', (SELECT hands FROM days WHERE d = v_today),
    'raked_hands_today', (SELECT raked_hands FROM days WHERE d = v_today),
    'rake_today',  (SELECT rake  FROM days WHERE d = v_today),
    'tournament_fees_today', (SELECT tournament_fees FROM days WHERE d = v_today),
    'new_this_week', (
      SELECT count(*) FROM club_members cm
      WHERE cm.club_id = p_club_id AND cm.created_at > now() - interval '7 days'
    ),
    'hands_week', (SELECT sum(hands) FROM days WHERE d >= v_today - 6),
    'raked_hands_week', (SELECT sum(raked_hands) FROM days WHERE d >= v_today - 6),
    'rake_week',  (SELECT sum(rake)  FROM days WHERE d >= v_today - 6),
    'tournament_fees_week', (SELECT sum(tournament_fees) FROM days WHERE d >= v_today - 6),
    -- PEOPLE, not seat rows. A player at two tables is one person seated.
    -- Measured 2026-09-04: 479 seat rows for 243 people at this club.
    'seated_now', (
      SELECT count(DISTINCT ts.user_id)
      FROM table_seats ts JOIN tables t ON t.id = ts.table_id
      WHERE t.club_id = p_club_id AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
    ),
    'daily_series', (
      SELECT jsonb_agg(jsonb_build_object('d', d, 'hands', hands, 'rake', rake,
                                          'raked_hands', raked_hands,
                                          'tournament_fees', tournament_fees) ORDER BY d)
      FROM days
    ),
    'rake_source', 'rake_records'
  ) INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION public.ca_club_dashboard_stats(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_dashboard_stats(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_dashboard_stats(p_club_id uuid) IS 'Club dashboard metric cards and 14-day series, read from the per-hand rollup in one pass. seated_now counts distinct people since 2026-09-04 (it counted seat rows before). Membership-gated by ca_can_view_club.';


--
-- Name: ca_club_data_export_cancel(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_data_export_cancel(p_export_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deleted integer;
BEGIN
  DELETE FROM public.ca_club_data_exports
   WHERE id=p_export_id AND user_id=auth.uid();
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted=1;
END;
$$;


ALTER FUNCTION public.ca_club_data_export_cancel(p_export_id uuid) OWNER TO postgres;

--
-- Name: ca_club_data_export_page(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_data_export_page(p_export_id uuid, p_offset integer DEFAULT 0, p_limit integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_job public.ca_club_data_exports%ROWTYPE;
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_limit integer := GREATEST(LEAST(COALESCE(p_limit, 1000), 2000), 1);
  v_rows jsonb;
BEGIN
  SELECT *
    INTO v_job
    FROM public.ca_club_data_exports
   WHERE id = p_export_id
     AND user_id = v_user
     AND expires_at >= now();

  IF v_job.id IS NULL OR NOT public.ca_can_view_club_finances(v_job.club_id) THEN
    RAISE EXCEPTION 'export not found or no longer authorized' USING ERRCODE = '42501';
  END IF;

  -- A player job prepared while this viewer was entitled can contain facts a
  -- super agent may not know. Recheck before EVERY page; if a later page sees
  -- the downgrade, fetchClubDataExport discards every earlier page and never
  -- hands a mixed result to the downloader.
  IF v_job.kind = 'players'
     AND NOT COALESCE(public.fn_can_see_horse_flag(v_job.club_id), false)
     AND EXISTS (
       SELECT 1
         FROM public.ca_club_data_export_rows sensitive
        WHERE sensitive.export_id = p_export_id
          AND sensitive.payload @> '{"is_horse": true}'::jsonb
     ) THEN
    RAISE EXCEPTION 'player export permissions changed; prepare a new export'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(jsonb_agg(r.payload ORDER BY r.ordinal), '[]'::jsonb)
    INTO v_rows
    FROM public.ca_club_data_export_rows r
   WHERE r.export_id = p_export_id
     AND r.ordinal > v_offset
     AND r.ordinal <= v_offset + v_limit;

  RETURN jsonb_build_object(
    'rows', v_rows,
    'total_rows', v_job.total_rows,
    'next_offset', LEAST(v_offset + jsonb_array_length(v_rows), v_job.total_rows),
    'has_more', v_offset + jsonb_array_length(v_rows) < v_job.total_rows,
    'expires_at', v_job.expires_at
  );
END;
$$;


ALTER FUNCTION public.ca_club_data_export_page(p_export_id uuid, p_offset integer, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_data_export_page(p_export_id uuid, p_offset integer, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_data_export_page(p_export_id uuid, p_offset integer, p_limit integer) IS 'Pages an immutable Club Data export after rechecking finance access and, for sensitive prepared player jobs, the current horse-flag entitlement.';


--
-- Name: ca_club_data_snapshot(uuid, date, date, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_data_snapshot(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_game text DEFAULT 'ALL'::text, p_stakes text DEFAULT 'ALL'::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date:=(now() AT TIME ZONE 'UTC')::date;
  v_end date:=LEAST(COALESCE(p_end,v_today),v_today);
  v_start date:=COALESCE(p_start,v_end-13); v_days int; v_pstart date; v_pend date;
  v_game text:=UPPER(COALESCE(NULLIF(p_game,''),'ALL'));
  v_stakes text:=UPPER(COALESCE(NULLIF(p_stakes,''),'ALL'));
  v_q text:=NULLIF(btrim(COALESCE(p_search,'')),'');
  v_lim int:=GREATEST(LEAST(COALESCE(p_limit,100),500),1);
  v_union uuid; v_cur jsonb; v_prev jsonb; v_rows jsonb;
BEGIN
  IF NOT public.ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE='42501'; END IF;
  IF v_start<v_end-92 THEN v_start:=v_end-92; END IF;
  IF v_start>v_end THEN v_start:=v_end; END IF;
  v_days:=(v_end-v_start)+1; v_pend:=v_start-1; v_pstart:=v_pend-(v_days-1);
  SELECT uc.union_id INTO v_union FROM public.union_clubs uc WHERE uc.club_id=p_club_id LIMIT 1;
  v_cur:=public.fn_ca_club_game_summary(p_club_id,v_start,v_end,v_game,v_stakes,v_q);
  v_prev:=public.fn_ca_club_game_summary(p_club_id,v_pstart,v_pend,v_game,v_stakes,v_q);
  v_rows:=public.fn_ca_club_game_rows(p_club_id,v_start,v_end,v_game,v_stakes,v_q,v_lim);
  RETURN jsonb_build_object(
    'range',jsonb_build_object('start',v_start,'end',v_end,'days',v_days),
    'previous_range',jsonb_build_object('start',v_pstart,'end',v_pend,'days',v_days),
    'filters',jsonb_build_object('game',v_game,'stakes',v_stakes,'search',v_q),
    'summary',v_cur,'previous',v_prev,'delta',jsonb_build_object(
      'fee_pct',CASE WHEN COALESCE((v_prev->>'fee')::numeric,0)=0 THEN NULL ELSE round(((v_cur->>'fee')::numeric-(v_prev->>'fee')::numeric)/abs((v_prev->>'fee')::numeric)*100,1) END,
      'games_pct',CASE WHEN COALESCE((v_prev->>'games')::numeric,0)=0 THEN NULL ELSE round(((v_cur->>'games')::numeric-(v_prev->>'games')::numeric)/abs((v_prev->>'games')::numeric)*100,1) END,
      'winnings_abs',round((v_cur->>'total_winnings')::numeric-(v_prev->>'total_winnings')::numeric,2),
      'fee_abs',round((v_cur->>'fee')::numeric-(v_prev->>'fee')::numeric,2)),
    'rows',v_rows,'row_count',(v_cur->>'games')::int,'union_id',v_union,
    'data_updated_at',GREATEST(
      (SELECT max(c.updated_at) FROM public.club_table_daily c WHERE c.club_id=p_club_id AND c.stat_date BETWEEN v_start AND v_end),
      (SELECT max(d.updated_at) FROM public.ca_club_tournament_daily d WHERE d.club_id=p_club_id AND d.stat_date BETWEEN v_start AND v_end)),
    'generated_at',now());
END;
$$;


ALTER FUNCTION public.ca_club_data_snapshot(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text, p_limit integer) OWNER TO postgres;

--
-- Name: ca_club_financials(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_financials(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_end date := LEAST(coalesce(p_end, v_today), v_today);
  v_start date := coalesce(p_start, LEAST(coalesce(p_end, v_today), v_today) - 6);
  v_first date;
  v_series_from date;
  v_union uuid;
  v_from_ts timestamptz;
  v_to_ts timestamptz;
  v jsonb;
BEGIN
  IF NOT ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  SELECT c.union_id INTO v_union FROM clubs c WHERE c.id = p_club_id;

  SELECT LEAST(
           (SELECT (c.created_at AT TIME ZONE 'UTC')::date FROM clubs c WHERE c.id = p_club_id),
           (SELECT min(r.stat_date) FROM ca_club_rake_daily r WHERE r.club_id = p_club_id),
           (SELECT min(t.stat_date) FROM ca_club_tournament_daily t WHERE t.club_id = p_club_id),
           (SELECT min(k.stat_date) FROM ca_club_commission_daily k WHERE k.club_id = p_club_id))
    INTO v_first;
  v_first := coalesce(v_first, v_today);

  IF v_start > v_end THEN v_start := v_end; END IF;
  IF v_start < v_first THEN v_start := v_first; END IF;
  IF v_start > v_end THEN v_start := v_end; END IF;
  v_series_from := GREATEST(v_start, v_end - 91);
  v_from_ts := (v_start::timestamp AT TIME ZONE 'UTC');
  v_to_ts := ((v_end + 1)::timestamp AT TIME ZONE 'UTC');

  WITH days AS (
    SELECT gs::date AS d FROM generate_series(v_start, v_end, interval '1 day') gs
  ),
  cash AS (
    SELECT r.stat_date AS d, r.hands, r.rake, r.bbj, r.pot, r.updated_at
      FROM ca_club_rake_daily r
     WHERE r.club_id = p_club_id AND r.stat_date BETWEEN v_start AND v_end
  ),
  mtt AS (
    SELECT t.stat_date AS d, sum(t.fee) AS fee, max(t.updated_at) AS updated_at
      FROM ca_club_tournament_daily t
     WHERE t.club_id = p_club_id AND t.stat_date BETWEEN v_start AND v_end
     GROUP BY t.stat_date
  ),
  comm AS (
    SELECT k.stat_date AS d, k.amount, k.updated_at
      FROM ca_club_commission_daily k
     WHERE k.club_id = p_club_id AND k.stat_date BETWEEN v_start AND v_end
  ),
  rb AS (
    SELECT (x.created_at AT TIME ZONE 'UTC')::date AS d, sum(x.amount) AS amount, count(*) AS n
      FROM chip_transactions x
     WHERE x.club_id = p_club_id AND x.transaction_type = 'rakeback'
       AND x.created_at >= v_from_ts AND x.created_at < v_to_ts
     GROUP BY (x.created_at AT TIME ZONE 'UTC')::date
  ),
  uf AS (
    SELECT (i.created_at AT TIME ZONE 'UTC')::date AS d,
           sum(CASE WHEN coalesce(i.breakdown->>'union_fee_kept', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                    THEN (i.breakdown->>'union_fee_kept')::numeric ELSE 0 END) AS fee,
           count(*) AS n,
           sum(CASE WHEN i.breakdown->>'direction' = 'club owes union' THEN coalesce(i.net_amount, 0)
                    WHEN i.breakdown->>'direction' = 'union owes club' THEN -coalesce(i.net_amount, 0)
                    ELSE 0 END) AS squareup
      FROM settlement_invoices i
     WHERE i.club_id = p_club_id AND i.invoice_type = 'union_weekly_squareup'
       AND i.created_at >= v_from_ts AND i.created_at < v_to_ts
     GROUP BY (i.created_at AT TIME ZONE 'UTC')::date
  ),
  merged AS (
    SELECT dd.d,
           coalesce(c.hands, 0) AS raked_hands,
           coalesce(c.rake, 0) AS gross_rake,
           coalesce(c.bbj, 0) AS bbj_drop,
           coalesce(c.pot, 0) AS pot_volume,
           coalesce(m.fee, 0) AS tournament_fees,
           coalesce(r.amount, 0) AS rakeback_paid,
           coalesce(r.n, 0) AS rakeback_rows,
           coalesce(k.amount, 0) AS agent_commissions,
           coalesce(u.fee, 0) AS union_fee,
           coalesce(u.n, 0) AS union_statements,
           coalesce(u.squareup, 0) AS union_squareup
      FROM days dd
      LEFT JOIN cash c ON c.d = dd.d
      LEFT JOIN mtt m ON m.d = dd.d
      LEFT JOIN rb r ON r.d = dd.d
      LEFT JOIN comm k ON k.d = dd.d
      LEFT JOIN uf u ON u.d = dd.d
  ),
  tot AS (
    SELECT sum(x.raked_hands)::bigint AS raked_hands,
           round(sum(x.gross_rake), 2) AS gross_rake,
           round(sum(x.bbj_drop), 2) AS bbj_drop,
           round(sum(x.pot_volume), 2) AS pot_volume,
           round(sum(x.tournament_fees), 2) AS tournament_fees,
           round(sum(x.rakeback_paid), 2) AS rakeback_paid,
           sum(x.rakeback_rows)::bigint AS rakeback_rows,
           round(sum(x.agent_commissions), 2) AS agent_commissions,
           round(sum(x.union_fee), 2) AS union_fee,
           sum(x.union_statements)::bigint AS union_statements,
           round(sum(x.union_squareup), 2) AS union_squareup
      FROM merged x
  )
  SELECT jsonb_build_object(
    'range', jsonb_build_object('start', v_start, 'end', v_end, 'days', (v_end - v_start) + 1,
                                'first_day', v_first, 'series_from', v_series_from),
    'union_id', v_union,
    'totals', (
      SELECT jsonb_build_object(
        'raked_hands', t.raked_hands,
        'gross_rake', t.gross_rake,
        'bbj_drop', t.bbj_drop,
        'net_rake', round(t.gross_rake - t.bbj_drop, 2),
        'pot_volume', t.pot_volume,
        'tournament_fees', t.tournament_fees,
        'rakeback_paid', t.rakeback_paid,
        'rakeback_rows', t.rakeback_rows,
        'agent_commissions', t.agent_commissions,
        'union_fee', t.union_fee,
        'union_statements', t.union_statements,
        'union_squareup', t.union_squareup,
        'net_revenue', round(t.gross_rake - t.bbj_drop + t.tournament_fees
                             - t.rakeback_paid - t.agent_commissions - t.union_fee, 2))
      FROM tot t
    ),
    'daily', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'd', x.d,
               'raked_hands', x.raked_hands,
               'gross_rake', round(x.gross_rake, 2),
               'bbj_drop', round(x.bbj_drop, 2),
               'pot_volume', round(x.pot_volume, 2),
               'tournament_fees', round(x.tournament_fees, 2),
               'rakeback_paid', round(x.rakeback_paid, 2),
               'agent_commissions', round(x.agent_commissions, 2),
               'union_fee', round(x.union_fee, 2))
             ORDER BY x.d)
      FROM merged x WHERE x.d >= v_series_from
    ), '[]'::jsonb),
    'by_table', coalesce((
      SELECT jsonb_agg(q ORDER BY (q->>'rake')::numeric DESC)
      FROM (
        SELECT jsonb_build_object(
                 'table_id', s.table_id,
                 'name', coalesce(t.name, 'Unnamed'),
                 'status', coalesce(t.status, 'unknown'),
                 'stakes', coalesce(t.stakes, concat(t.small_blind::text, '/', t.big_blind::text)),
                 'variant', upper(coalesce(t.game_variant, 'nlh')),
                 'raked_hands', sum(s.hands),
                 'rake', round(sum(s.rake), 2),
                 'players', max(s.players),
                 'table_net', round(sum(s.net), 2)) AS q
          FROM club_table_daily s
          LEFT JOIN tables t ON t.id = s.table_id
         WHERE s.club_id = p_club_id AND s.stat_date BETWEEN v_start AND v_end
         GROUP BY s.table_id, t.name, t.status, t.stakes, t.small_blind, t.big_blind, t.game_variant
         ORDER BY sum(s.rake) DESC
         LIMIT 10
      ) z
    ), '[]'::jsonb),
    'recent', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', r.id,
               'hand_id', r.hand_id,
               'global_hand_id', r.global_hand_id,
               'table_name', coalesce(t.name, CASE WHEN coalesce(r.is_tournament, false) THEN 'Tournament' ELSE 'Table' END),
               'kind', CASE WHEN coalesce(r.is_tournament, false)
                            THEN coalesce(r.metadata->>'kind', 'tournament_fee') ELSE 'cash_rake' END,
               'rake_amount', round(coalesce(r.rake_amount, 0), 2),
               'bbj_contribution', round(coalesce(r.bbj_contribution, 0), 2),
               'pot_size', round(coalesce(r.pot_size, 0), 2),
               'num_players', r.num_players,
               'created_at', r.created_at)
             ORDER BY r.created_at DESC)
      FROM (
        SELECT * FROM rake_records rr
         WHERE rr.club_id = p_club_id AND rr.rake_amount > 0
           AND rr.created_at >= v_from_ts AND rr.created_at < v_to_ts
         ORDER BY rr.created_at DESC LIMIT 20
      ) r
      LEFT JOIN tables t ON t.id = r.table_id
    ), '[]'::jsonb),
    'data_updated_at', GREATEST(
      (SELECT max(c.updated_at) FROM cash c),
      (SELECT max(m.updated_at) FROM mtt m),
      (SELECT max(k.updated_at) FROM comm k)),
    'club_table_daily_updated_at', (
      SELECT max(s.updated_at) FROM club_table_daily s
       WHERE s.club_id = p_club_id AND s.stat_date BETWEEN v_start AND v_end),
    'generated_at', now()
  ) INTO v;

  RETURN v;
END;
$_$;


ALTER FUNCTION public.ca_club_financials(p_club_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: ca_club_game_export_start(uuid, date, date, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_game_export_start(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_game text DEFAULT 'ALL'::text, p_stakes text DEFAULT 'ALL'::text, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'recent'::text, p_request_id uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_end date := LEAST(COALESCE(p_end,v_today),v_today);
  v_start date := COALESCE(p_start,v_end-13);
  v_game text := UPPER(COALESCE(NULLIF(p_game,''),'ALL'));
  v_stakes text := UPPER(COALESCE(NULLIF(p_stakes,''),'ALL'));
  v_search text := NULLIF(btrim(COALESCE(p_search,'')),'');
  v_sort text := LOWER(COALESCE(NULLIF(p_sort,''),'recent'));
  v_request uuid := COALESCE(p_request_id,gen_random_uuid());
  v_export_id uuid;
  v_total integer;
BEGIN
  IF v_user IS NULL OR NOT public.ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE='42501';
  END IF;
  IF v_start < v_end-92 THEN v_start := v_end-92; END IF;
  IF v_start > v_end THEN v_start := v_end; END IF;
  IF v_sort NOT IN ('recent','fee','winnings','hands') THEN v_sort := 'recent'; END IF;

  -- A retried HTTP request must resume the same immutable export, not create a
  -- second 43k-row copy. The advisory lock serializes that tiny idempotency key.
  PERFORM pg_advisory_xact_lock(hashtextextended(v_user::text||':'||v_request::text,0));
  DELETE FROM public.ca_club_data_exports WHERE expires_at < now();
  SELECT id,total_rows INTO v_export_id,v_total
    FROM public.ca_club_data_exports
   WHERE user_id=v_user AND request_id=v_request AND status='ready';
  IF v_export_id IS NOT NULL THEN
    RETURN jsonb_build_object('export_id',v_export_id,'total_rows',v_total,'status','ready');
  END IF;

  DELETE FROM public.ca_club_data_exports
   WHERE user_id=v_user AND request_id=v_request;
  INSERT INTO public.ca_club_data_exports(user_id,club_id,request_id,kind)
  VALUES(v_user,p_club_id,v_request,'games') RETURNING id INTO v_export_id;

  WITH cash AS MATERIALIZED (
    SELECT c.table_id,SUM(c.rake) fee,SUM(c.net) winnings,SUM(c.hands)::bigint hands,
           MAX(c.players)::integer players
      FROM public.club_table_daily c
     WHERE c.club_id=p_club_id AND c.stat_date BETWEEN v_start AND v_end
     GROUP BY c.table_id
  ), tournament_facts AS MATERIALIZED (
    SELECT d.tournament_id,SUM(d.fee) fee,SUM(d.winnings) winnings
      FROM public.ca_club_tournament_daily d
     WHERE d.club_id=p_club_id AND d.stat_date BETWEEN v_start AND v_end
     GROUP BY d.tournament_id
  ), tournament_players AS MATERIALIZED (
    SELECT p.tournament_id,count(DISTINCT p.user_id)::integer players
      FROM public.ca_club_tournament_player_daily p
     WHERE p.club_id=p_club_id AND p.stat_date BETWEEN v_start AND v_end
     GROUP BY p.tournament_id
  ), all_rows AS (
    SELECT 'CASH'::text kind,t.id::text id,COALESCE(t.name,'Unnamed') name,
           UPPER(COALESCE(t.game_variant,'nlh')) variant,
           CASE WHEN COALESCE(t.game_variant,'') ILIKE '%plo%'
                      OR COALESCE(t.game_variant,'') ILIKE '%omaha%' THEN 'OMAHA'
                WHEN COALESCE(t.game_variant,'') ILIKE '%mixed%'
                      OR COALESCE(t.game_mode,'') ILIKE '%mixed%' THEN 'MIXED'
                ELSE 'HOLDEM' END game_class,
           CASE WHEN COALESCE(t.big_blind,0)<1 THEN 'MICRO'
                WHEN COALESCE(t.big_blind,0)<5 THEN 'SMALL'
                WHEN COALESCE(t.big_blind,0)<25 THEN 'MID' ELSE 'HIGH' END stakes_tier,
           COALESCE(t.small_blind,0) small_blind,COALESCE(t.big_blind,0) big_blind,
           CASE WHEN COALESCE(t.rake_percent,-1)>=0 THEN t.rake_percent END rake_percent,
           t.created_at started_at,t.created_by,t.status,round(c.fee,2) fee,
           round(c.winnings,2) winnings,c.hands,c.players,
           COALESCE(pr.username,'') creator_name,pr.avatar_url creator_avatar
      FROM cash c JOIN public.tables t ON t.id=c.table_id
      LEFT JOIN public.profiles pr ON pr.id=t.created_by
    UNION ALL
    SELECT CASE WHEN tr.tournament_type='SPIN' THEN 'SPIN'
                WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,
           tr.id::text,COALESCE(tr.name,'Tournament'),
           UPPER(COALESCE(tr.variant,tr.game_type,'nlh')),
           CASE WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,
           'NA',0::numeric,0::numeric,NULL::numeric,tr.start_time,NULL::uuid,tr.status,
           round(COALESCE(f.fee,0),2),round(COALESCE(f.winnings,0),2),0::bigint,
           COALESCE(tp.players,0)::integer,''::text,NULL::text
      FROM tournament_facts f JOIN public.tournaments tr ON tr.id=f.tournament_id
      LEFT JOIN tournament_players tp ON tp.tournament_id=f.tournament_id
  ), filtered AS MATERIALIZED (
    SELECT r.* FROM all_rows r
     WHERE (v_game='ALL' OR r.game_class=v_game)
       AND (v_stakes='ALL' OR r.stakes_tier=v_stakes)
       AND (v_search IS NULL OR r.name ILIKE '%'||v_search||'%' OR r.id ILIKE '%'||v_search||'%'
            OR r.creator_name ILIKE '%'||v_search||'%')
  ), scored AS (
    SELECT f.*,
           CASE v_sort WHEN 'fee' THEN f.fee WHEN 'winnings' THEN f.winnings
                       WHEN 'hands' THEN f.hands::numeric
                       ELSE extract(epoch FROM COALESCE(f.started_at,'0001-01-01'::timestamptz))::numeric
            END sort_value,
           extract(epoch FROM COALESCE(f.started_at,'0001-01-01'::timestamptz))::numeric sort_time
      FROM filtered f
  ), ordered AS (
    SELECT row_number() OVER (
             ORDER BY sort_value DESC,sort_time DESC,kind DESC,id DESC
           )::integer ordinal,
           jsonb_build_object(
             'kind',kind,'id',id,'name',name,'variant',variant,
             'game_class',game_class,'stakes_tier',stakes_tier,
             'blinds',CASE WHEN big_blind>0 THEN
               trim(trailing '.' from trim(trailing '0' from small_blind::text))||'/'||
               trim(trailing '.' from trim(trailing '0' from big_blind::text)) END,
             'rake_percent',rake_percent,'started_at',started_at,'status',status,
             'creator_id',created_by,'creator_name',NULLIF(creator_name,''),
             'creator_avatar',creator_avatar,
             'fee',fee,'winnings',winnings,'hands',hands,'players',players
           ) payload
      FROM scored
  )
  INSERT INTO public.ca_club_data_export_rows(export_id,ordinal,payload)
  SELECT v_export_id,ordinal,payload FROM ordered;

  GET DIAGNOSTICS v_total = ROW_COUNT;
  UPDATE public.ca_club_data_exports
     SET total_rows=v_total,status='ready'
   WHERE id=v_export_id;
  RETURN jsonb_build_object('export_id',v_export_id,'total_rows',v_total,'status','ready');
END;
$$;


ALTER FUNCTION public.ca_club_game_export_start(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text, p_sort text, p_request_id uuid) OWNER TO postgres;

--
-- Name: ca_club_game_page(uuid, date, date, text, text, text, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_game_page(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_game text DEFAULT 'ALL'::text, p_stakes text DEFAULT 'ALL'::text, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'recent'::text, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_end date := LEAST(COALESCE(p_end,v_today),v_today);
  v_start date := COALESCE(p_start,v_end-13);
  v_game text := UPPER(COALESCE(NULLIF(p_game,''),'ALL'));
  v_stakes text := UPPER(COALESCE(NULLIF(p_stakes,''),'ALL'));
  v_search text := NULLIF(btrim(COALESCE(p_search,'')),'');
  v_sort text := LOWER(COALESCE(NULLIF(p_sort,''),'recent'));
  v_limit integer := GREATEST(LEAST(COALESCE(p_limit,100),200),1);
  v_out jsonb;
BEGIN
  IF NOT public.ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE='42501';
  END IF;
  IF v_start < v_end-92 THEN v_start := v_end-92; END IF;
  IF v_start > v_end THEN v_start := v_end; END IF;
  IF v_sort NOT IN ('recent','fee','winnings','hands') THEN v_sort := 'recent'; END IF;

  -- EXECUTE forces a plan for this club/window.  Shark Club previously crossed
  -- 20 seconds when PostgreSQL reused a generic parameter plan here.
  EXECUTE $query$
    WITH cash AS (
      SELECT c.table_id,SUM(c.rake) fee,SUM(c.net) winnings,SUM(c.hands)::bigint hands,
             MAX(c.players)::integer players
        FROM public.club_table_daily c
       WHERE c.club_id=$1 AND c.stat_date BETWEEN $2 AND $3
       GROUP BY c.table_id
    ), tournament_facts AS MATERIALIZED (
      SELECT d.tournament_id,SUM(d.fee) fee,SUM(d.winnings) winnings
        FROM public.ca_club_tournament_daily d
       WHERE d.club_id=$1 AND d.stat_date BETWEEN $2 AND $3
       GROUP BY d.tournament_id
    ), tournament_players AS MATERIALIZED (
      SELECT p.tournament_id,count(DISTINCT p.user_id)::integer players
        FROM public.ca_club_tournament_player_daily p
       WHERE p.club_id=$1 AND p.stat_date BETWEEN $2 AND $3
       GROUP BY p.tournament_id
    ), keys AS MATERIALIZED (
      -- The ranking set carries the four sort keys and NOTHING the page does
      -- not filter on. Every other column is presentation, it is needed for at
      -- most $9 rows, and carrying it here is what spilled 42 MB to disk three
      -- times per read.
      SELECT 'CASH'::text kind,t.id::text id,
             CASE WHEN COALESCE(t.game_variant,'') ILIKE '%plo%'
                        OR COALESCE(t.game_variant,'') ILIKE '%omaha%' THEN 'OMAHA'
                  WHEN COALESCE(t.game_variant,'') ILIKE '%mixed%'
                        OR COALESCE(t.game_mode,'') ILIKE '%mixed%' THEN 'MIXED'
                  ELSE 'HOLDEM' END game_class,
             CASE WHEN COALESCE(t.big_blind,0)<1 THEN 'MICRO'
                  WHEN COALESCE(t.big_blind,0)<5 THEN 'SMALL'
                  WHEN COALESCE(t.big_blind,0)<25 THEN 'MID' ELSE 'HIGH' END stakes_tier,
             COALESCE(t.name,'Unnamed') name,COALESCE(pr.username,'') creator_name,
             CASE $7 WHEN 'fee' THEN round(c.fee,2)
                     WHEN 'winnings' THEN round(c.winnings,2)
                     WHEN 'hands' THEN c.hands::numeric
                     ELSE extract(epoch FROM COALESCE(t.created_at,'0001-01-01'::timestamptz))::numeric
              END sort_value,
             extract(epoch FROM COALESCE(t.created_at,'0001-01-01'::timestamptz))::numeric sort_time
        FROM cash c JOIN public.tables t ON t.id=c.table_id
        LEFT JOIN public.profiles pr ON pr.id=t.created_by
      UNION ALL
      SELECT CASE WHEN tr.tournament_type='SPIN' THEN 'SPIN'
                  WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,
             tr.id::text,
             CASE WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,
             'NA',
             COALESCE(tr.name,'Tournament'),''::text,
             CASE $7 WHEN 'fee' THEN round(COALESCE(f.fee,0),2)
                     WHEN 'winnings' THEN round(COALESCE(f.winnings,0),2)
                     WHEN 'hands' THEN 0::numeric
                     ELSE extract(epoch FROM COALESCE(tr.start_time,'0001-01-01'::timestamptz))::numeric
              END,
             extract(epoch FROM COALESCE(tr.start_time,'0001-01-01'::timestamptz))::numeric
        FROM tournament_facts f JOIN public.tournaments tr ON tr.id=f.tournament_id
    ), filtered AS MATERIALIZED (
      SELECT k.* FROM keys k
       WHERE ($4='ALL' OR k.game_class=$4)
         AND ($5='ALL' OR k.stakes_tier=$5)
         AND ($6 IS NULL OR k.name ILIKE '%'||$6||'%' OR k.id ILIKE '%'||$6||'%'
              OR k.creator_name ILIKE '%'||$6||'%')
    ), page_plus_one AS MATERIALIZED (
      SELECT s.* FROM filtered s
       WHERE $8 IS NULL OR ROW(s.sort_value,s.sort_time,s.kind,s.id) < ROW(
         ($8->>'value')::numeric,($8->>'time')::numeric,$8->>'kind',$8->>'id')
       ORDER BY s.sort_value DESC,s.sort_time DESC,s.kind DESC,s.id DESC
       LIMIT $9+1
    ), visible AS MATERIALIZED (
      SELECT * FROM page_plus_one
       ORDER BY sort_value DESC,sort_time DESC,kind DESC,id DESC LIMIT $9
    ), last_row AS (
      SELECT * FROM visible ORDER BY sort_value ASC,sort_time ASC,kind ASC,id ASC LIMIT 1
    ), detail AS (
      -- Presentation, for the <=$9 rows that survived the LIMIT and no others.
      SELECT v.kind,v.id,v.name,v.game_class,v.stakes_tier,v.creator_name,
             v.sort_value,v.sort_time,
             CASE WHEN v.kind='CASH' THEN UPPER(COALESCE(t.game_variant,'nlh'))
                  ELSE UPPER(COALESCE(tr.variant,tr.game_type,'nlh')) END variant,
             CASE WHEN v.kind='CASH' THEN COALESCE(t.small_blind,0) ELSE 0::numeric END small_blind,
             CASE WHEN v.kind='CASH' THEN COALESCE(t.big_blind,0) ELSE 0::numeric END big_blind,
             CASE WHEN v.kind='CASH' AND COALESCE(t.rake_percent,-1)>=0 THEN t.rake_percent END rake_percent,
             CASE WHEN v.kind='CASH' THEN t.created_at ELSE tr.start_time END started_at,
             CASE WHEN v.kind='CASH' THEN t.created_by END created_by,
             CASE WHEN v.kind='CASH' THEN t.status ELSE tr.status END status,
             CASE WHEN v.kind='CASH' THEN round(c.fee,2) ELSE round(COALESCE(f.fee,0),2) END fee,
             CASE WHEN v.kind='CASH' THEN round(c.winnings,2) ELSE round(COALESCE(f.winnings,0),2) END winnings,
             CASE WHEN v.kind='CASH' THEN c.hands ELSE 0::bigint END hands,
             CASE WHEN v.kind='CASH' THEN c.players ELSE COALESCE(tp.players,0)::integer END players,
             CASE WHEN v.kind='CASH' THEN pr.avatar_url END creator_avatar
        FROM visible v
        LEFT JOIN cash c ON v.kind='CASH' AND c.table_id=v.id::uuid
        LEFT JOIN public.tables t ON v.kind='CASH' AND t.id=v.id::uuid
        LEFT JOIN public.profiles pr ON v.kind='CASH' AND pr.id=t.created_by
        LEFT JOIN tournament_facts f ON v.kind<>'CASH' AND f.tournament_id=v.id::uuid
        LEFT JOIN public.tournaments tr ON v.kind<>'CASH' AND tr.id=v.id::uuid
        LEFT JOIN tournament_players tp ON v.kind<>'CASH' AND tp.tournament_id=v.id::uuid
    )
    SELECT jsonb_build_object(
      'sort',$7,
      'rows',COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'kind',q.kind,'id',q.id,'name',q.name,'variant',q.variant,
        'game_class',q.game_class,'stakes_tier',q.stakes_tier,
        'blinds',CASE WHEN q.big_blind>0 THEN
          trim(trailing '.' from trim(trailing '0' from q.small_blind::text))||'/'||
          trim(trailing '.' from trim(trailing '0' from q.big_blind::text)) END,
        'rake_percent',q.rake_percent,'started_at',q.started_at,'status',q.status,
        'creator_id',q.created_by,'creator_name',NULLIF(q.creator_name,''),
        'creator_avatar',q.creator_avatar,'fee',q.fee,'winnings',q.winnings,
        'hands',q.hands,'players',q.players)
        ORDER BY q.sort_value DESC,q.sort_time DESC,q.kind DESC,q.id DESC) FROM detail q),'[]'::jsonb),
      'next_cursor',CASE WHEN (SELECT count(*) FROM page_plus_one)>$9 THEN
        (SELECT jsonb_build_object('value',l.sort_value,'time',l.sort_time,'kind',l.kind,'id',l.id)
           FROM last_row l) ELSE NULL END,
      'has_more',(SELECT count(*) FROM page_plus_one)>$9,
      'filtered_count',(SELECT count(*) FROM filtered),
      'generated_at',now())
  $query$ INTO v_out
  USING p_club_id,v_start,v_end,v_game,v_stakes,v_search,v_sort,p_cursor,v_limit;

  RETURN v_out;
END;
$_$;


ALTER FUNCTION public.ca_club_game_page(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text, p_sort text, p_cursor jsonb, p_limit integer) OWNER TO postgres;

--
-- Name: ca_club_grantable_roles(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_grantable_roles(p_club_id uuid, p_target_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_roles text[];
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('roles', '[]'::jsonb); END IF;
  v_roles := fn_club_grantable_roles(p_club_id, auth.uid(), p_target_user_id);
  RETURN jsonb_build_object(
    'roles', COALESCE(to_jsonb(v_roles), '[]'::jsonb),
    'target_role', (SELECT role FROM club_members
                     WHERE club_id = p_club_id AND user_id = p_target_user_id
                       AND status IN ('active','approved')),
    'actor_role', (SELECT role FROM club_members
                    WHERE club_id = p_club_id AND user_id = auth.uid()
                      AND status IN ('active','approved')));
END;
$$;


ALTER FUNCTION public.ca_club_grantable_roles(p_club_id uuid, p_target_user_id uuid) OWNER TO postgres;

--
-- Name: ca_club_insurance_report(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_insurance_report(p_club_id uuid, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
  v_days integer := LEAST(GREATEST(COALESCE(p_days, 30), 1), 90);
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_from date;
  v_from_ts timestamptz;
BEGIN
  IF NOT ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;
  v_from := v_today - (v_days - 1);
  v_from_ts := (v_from::timestamp AT TIME ZONE 'UTC');

  WITH offers AS (
    SELECT e.table_id, coalesce(e.hand_number::text, e.id::text) AS hand_key, e.player_id,
           (min(e.created_at) AT TIME ZONE 'UTC')::date AS day,
           bool_or(e.event = 'cashed_out') AS cashed_out,
           bool_or(e.event = 'accepted')   AS accepted,
           bool_or(e.event = 'declined')   AS declined,
           bool_or(e.event = 'timeout')    AS timed_out,
           avg(e.equity_percent) FILTER (WHERE e.event = 'offered') AS equity,
           avg(e.pot) FILTER (WHERE e.event = 'offered') AS pot
      FROM insurance_offer_events e
     WHERE e.club_id = p_club_id AND e.created_at >= v_from_ts
     GROUP BY e.table_id, coalesce(e.hand_number::text, e.id::text), e.player_id
  ),
  funnel AS (
    SELECT o.day,
           count(*) AS offers,
           count(*) FILTER (WHERE o.cashed_out) AS cashouts,
           count(*) FILTER (WHERE o.accepted AND NOT o.cashed_out) AS accepted,
           count(*) FILTER (WHERE o.declined AND NOT o.accepted AND NOT o.cashed_out) AS declined,
           count(*) FILTER (WHERE o.timed_out AND NOT o.accepted AND NOT o.cashed_out AND NOT o.declined) AS timeouts,
           avg(o.equity) AS equity,
           avg(o.pot) AS pot
      FROM offers o GROUP BY o.day
  ),
  money AS (
    SELECT (t.created_at AT TIME ZONE 'UTC')::date AS day,
           count(*) AS contracts,
           count(*) FILTER (WHERE t.kind = 'insurance') AS insurance_contracts,
           count(*) FILTER (WHERE t.kind = 'ev_cashout') AS cashout_contracts,
           round(coalesce(sum(t.premium), 0), 2) AS bank_in,
           round(coalesce(sum(t.payout), 0), 2) AS bank_out,
           round(coalesce(sum(t.premium - t.payout), 0), 2) AS bank_net
      FROM insurance_transactions t
     WHERE t.club_id = p_club_id AND t.created_at >= v_from_ts
     GROUP BY (t.created_at AT TIME ZONE 'UTC')::date
  )
  SELECT jsonb_build_object(
    'window_days', v_days,
    'window_start', v_from,
    'window_end', v_today,
    'bank', (SELECT CASE WHEN c.union_id IS NOT NULL THEN 'union' ELSE 'club' END
             FROM clubs c WHERE c.id = p_club_id),
    'totals', (
      SELECT jsonb_build_object(
        'offers',   coalesce(sum(f.offers), 0),
        'accepted', coalesce(sum(f.accepted), 0),
        'declined', coalesce(sum(f.declined), 0),
        'timeouts', coalesce(sum(f.timeouts), 0),
        'cashouts', coalesce(sum(f.cashouts), 0),
        'take_rate_pct', CASE WHEN coalesce(sum(f.offers), 0) > 0
                              THEN round(100.0 * (sum(f.accepted) + sum(f.cashouts)) / sum(f.offers), 1) END,
        'avg_offer_equity', round((SELECT avg(o.equity) FROM offers o), 1),
        'avg_offer_pot',    round((SELECT avg(o.pot) FROM offers o), 2)
      )
      FROM funnel f
    ),
    'money', (
      SELECT jsonb_build_object(
        'contracts', coalesce(sum(m.contracts), 0),
        'insurance_contracts', coalesce(sum(m.insurance_contracts), 0),
        'cashout_contracts',   coalesce(sum(m.cashout_contracts), 0),
        'bank_in',  round(coalesce(sum(m.bank_in), 0), 2),
        'bank_out', round(coalesce(sum(m.bank_out), 0), 2),
        'bank_net', round(coalesce(sum(m.bank_net), 0), 2)
      )
      FROM money m
    ),
    'days', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'day', coalesce(f.day, m.day),
               'offers',   coalesce(f.offers, 0),
               'accepted', coalesce(f.accepted, 0),
               'declined', coalesce(f.declined, 0),
               'timeouts', coalesce(f.timeouts, 0),
               'cashouts', coalesce(f.cashouts, 0),
               'contracts', coalesce(m.contracts, 0),
               'bank_in',  coalesce(m.bank_in, 0),
               'bank_out', coalesce(m.bank_out, 0),
               'bank_net', coalesce(m.bank_net, 0))
             ORDER BY coalesce(f.day, m.day) DESC)
      FROM funnel f FULL OUTER JOIN money m ON m.day = f.day
    ), '[]'::jsonb),
    'generated_at', now()
  ) INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION public.ca_club_insurance_report(p_club_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: ca_club_member_detail(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_member_detail(p_club_id uuid, p_user_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_scope uuid[] := public.fn_club_scope_ids(p_club_id);
  v_access text := public.ca_club_roster_access(p_club_id, p_user_id);
  v_sensitive boolean := v_access IN ('staff', 'downline', 'service');
  v_overall boolean := p_from IS NULL AND p_to IS NULL;
  v_ts_from timestamptz := CASE WHEN p_from IS NULL THEN NULL ELSE p_from::timestamp AT TIME ZONE 'UTC' END;
  v_ts_to timestamptz := CASE WHEN p_to IS NULL THEN NULL ELSE (p_to + 1)::timestamp AT TIME ZONE 'UTC' END;
  v_out jsonb;
BEGIN
  IF v_access = 'none' OR v_scope IS NULL THEN
    RETURN NULL;
  END IF;

  WITH RECURSIVE mem AS MATERIALIZED (
    SELECT DISTINCT ON (cm.user_id)
           cm.user_id, cm.club_id, cm.role, cm.agent_id, cm.chip_balance,
           cm.promo_balance, cm.nickname, cm.notes, cm.display_name, cm.joined_at,
           public.fn_club_role_rank(cm.role) AS role_rank
      FROM public.club_members cm
     WHERE cm.user_id = p_user_id
       AND cm.club_id = p_club_id
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
     ORDER BY cm.user_id, public.fn_club_role_rank(cm.role) DESC, cm.joined_at ASC
  ), edges AS MATERIALIZED (
    SELECT DISTINCT cm.user_id AS child, cm.agent_id AS parent
      FROM public.club_members cm
     WHERE cm.club_id = p_club_id
       AND cm.agent_id IS NOT NULL AND cm.agent_id <> cm.user_id
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
  ), tree AS MATERIALIZED (
    SELECT e.child, 1 AS depth FROM edges e WHERE e.parent = p_user_id
    UNION ALL
    SELECT e.child, t.depth + 1 FROM tree t JOIN edges e ON e.parent = t.child
     WHERE t.depth < 20
  ), downline AS MATERIALIZED (
    SELECT count(DISTINCT child) FILTER (WHERE depth = 1)::int AS direct,
           count(DISTINCT child)::int AS total FROM tree
  ), seat AS MATERIALIZED (
    SELECT 1 AS seated
      FROM public.table_seats ts JOIN public.tables t ON t.id = ts.table_id
     WHERE ts.user_id = p_user_id AND ts.left_at IS NULL
       AND t.status IN ('waiting', 'running')
       AND (ts.club_id = p_club_id OR t.club_id = p_club_id) LIMIT 1
  ), member_wallet AS MATERIALIZED (
    SELECT sum(coalesce(cm.chip_balance, 0)) AS player_wallet,
           sum(coalesce(cm.promo_balance, 0)) AS member_promo
      FROM public.club_members cm
     WHERE v_sensitive AND cm.user_id = p_user_id AND cm.club_id = p_club_id
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
  ), agent_wallet AS MATERIALIZED (
    SELECT sum(coalesce(a.agent_wallet_balance, 0)) AS agent_wallet,
           sum(coalesce(a.promo_wallet_balance, 0)) AS agent_promo
      FROM public.agents a
     WHERE v_sensitive AND a.user_id = p_user_id AND a.club_id = p_club_id
       AND coalesce(a.status, 'active') = 'active'
  ), roll AS MATERIALIZED (
    SELECT count(DISTINCT r.hand_id) FILTER (WHERE r.tournament_id IS NULL)::bigint AS hands,
           count(DISTINCT r.hand_id) FILTER (WHERE r.tournament_id IS NOT NULL)::bigint AS mtt_hands,
           coalesce(sum(r.rake_paid) FILTER (WHERE r.tournament_id IS NULL), 0) AS fees,
           coalesce(sum(r.rake_paid) FILTER (WHERE r.tournament_id IS NOT NULL), 0) AS mtt_fees,
           coalesce(sum(r.net) FILTER (WHERE r.tournament_id IS NULL), 0) AS net,
           coalesce(sum(r.net) FILTER (WHERE r.tournament_id IS NOT NULL), 0) AS mtt_net
      FROM public.ca_hand_facts r
     WHERE v_sensitive AND r.user_id = p_user_id AND r.club_id = p_club_id
       AND (v_ts_from IS NULL OR r.played_at >= v_ts_from)
       AND (v_ts_to IS NULL OR r.played_at < v_ts_to)
  ), txn AS MATERIALIZED (
    SELECT coalesce(sum(ct.amount) FILTER (WHERE ct.to_user_id = p_user_id
             AND lower(coalesce(ct.transaction_type, '')) ~ '(rakeback|commission)'), 0) AS claimed_back,
           coalesce(sum(abs(ct.amount)) FILTER (WHERE ct.from_user_id = p_user_id
             AND lower(coalesce(ct.transaction_type, '')) ~ '(transfer|send|distribute)'), 0) AS sent_out
      FROM public.chip_transactions ct
     WHERE v_sensitive AND ct.club_id = p_club_id
       -- The player bound. Both FILTERs above already require one of these
       -- equalities; stating it here lets the planner use the two
       -- (club_id, <user>, created_at) indexes instead of reading the club.
       AND (ct.to_user_id = p_user_id OR ct.from_user_id = p_user_id)
       AND (v_ts_from IS NULL OR ct.created_at >= v_ts_from)
       AND (v_ts_to IS NULL OR ct.created_at < v_ts_to)
  )
  SELECT jsonb_build_object(
    'identity', jsonb_build_object(
      'user_id', p_user_id,
      'player_number', pr.player_number,
      'alias', coalesce(nullif(btrim(pr.alias), ''), nullif(btrim(m.display_name), ''),
                        nullif(btrim(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name)), ''), pr.username),
      'username', pr.username,
      'display_name', coalesce(nullif(btrim(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name)), ''), pr.username),
      'avatar_url', coalesce(nullif(pr.arena_avatar_url, ''), pr.avatar_url),
      'role', m.role,
      'role_rank', coalesce(m.role_rank, 0),
      'nickname', CASE WHEN v_sensitive THEN m.nickname END,
      'remark', CASE WHEN v_sensitive THEN m.notes END,
      'last_login', CASE WHEN v_sensitive THEN coalesce(pr.last_login, pr.last_seen) END,
      'joined_at', m.joined_at,
      'home_club_id', m.club_id,
      'home_club_name', cl.name,
      'upline_user_id', CASE WHEN v_sensitive THEN m.agent_id END,
      'upline_name', CASE WHEN v_sensitive THEN up.up_name END,
      'upline_player_number', CASE WHEN v_sensitive THEN up.up_number END
    ),
    'presence', jsonb_build_object(
      'is_online', s.seated IS NOT NULL OR (coalesce(pr.is_online, false) AND pr.last_seen > now() - interval '5 minutes'),
      'is_seated', s.seated IS NOT NULL
    ),
    'wallets', CASE WHEN v_sensitive THEN jsonb_build_object(
      'chip_balance', coalesce(m.chip_balance, 0),
      'player_wallet', coalesce(mw.player_wallet, 0),
      'agent_wallet', coalesce(aw.agent_wallet, 0),
      'promo_wallet', coalesce(mw.member_promo, 0) + coalesce(aw.agent_promo, 0)
    ) ELSE NULL END,
    'downline', CASE WHEN v_sensitive THEN jsonb_build_object(
      'downline_direct', coalesce(d.direct, 0), 'downline_total', coalesce(d.total, 0)
    ) ELSE NULL END,
    'stats', CASE WHEN v_sensitive THEN jsonb_build_object(
      'hands', coalesce(rl.hands, 0), 'mtt_hands', coalesce(rl.mtt_hands, 0),
      'total_fee', round(coalesce(rl.fees, 0), 2), 'mtt_fee', round(coalesce(rl.mtt_fees, 0), 2),
      'total_winnings', round(coalesce(rl.net, 0), 2), 'mtt_winnings', round(coalesce(rl.mtt_net, 0), 2),
      'claimed_back', round(coalesce(tx.claimed_back, 0), 2), 'sent_out', round(coalesce(tx.sent_out, 0), 2)
    ) ELSE NULL END,
    'range', jsonb_build_object('from', p_from, 'to', p_to, 'is_overall', v_overall),
    'capabilities', jsonb_build_object(
      'access', v_access,
      'can_view_financials', v_sensitive,
      'can_view_stats', v_sensitive,
      'can_view_downline', v_sensitive,
      'can_view_notes', v_sensitive,
      'can_edit_notes', v_sensitive AND auth.uid() IS DISTINCT FROM p_user_id,
      'can_manage_role', v_access IN ('staff', 'downline', 'service')
    )
  ) INTO v_out
  FROM (SELECT 1) anchor
  LEFT JOIN mem m ON true
  LEFT JOIN public.profiles pr ON pr.id = p_user_id
  LEFT JOIN public.clubs cl ON cl.id = m.club_id
  LEFT JOIN seat s ON true
  LEFT JOIN member_wallet mw ON true
  LEFT JOIN agent_wallet aw ON true
  LEFT JOIN downline d ON true
  LEFT JOIN roll rl ON true
  LEFT JOIN txn tx ON true
  LEFT JOIN LATERAL (
    SELECT coalesce(nullif(btrim(u.alias), ''), nullif(btrim(public.fn_arena_name(u.alias, u.username, u.display_name, u.first_name, u.last_name, u.full_name)), ''), u.username) AS up_name,
           u.player_number AS up_number
      FROM public.profiles u WHERE u.id = m.agent_id
  ) up ON true;

  RETURN v_out;
END;
$$;


ALTER FUNCTION public.ca_club_member_detail(p_club_id uuid, p_user_id uuid, p_from date, p_to date) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_member_detail(p_club_id uuid, p_user_id uuid, p_from date, p_to date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_member_detail(p_club_id uuid, p_user_id uuid, p_from date, p_to date) IS 'Member Management detail header for one member of a club or union: identity, role, upline, presence, wallets, downline counts and range-filtered hands/fees/winnings/rakeback/transfers, as one jsonb object. NULL p_from/p_to means Overall. Never errors on a missing member; returns nulls in identity and zeros in every number.';


--
-- Name: ca_club_member_downline(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_member_downline(p_club_id uuid, p_user_id uuid) RETURNS TABLE(user_id uuid, player_number text, alias text, username text, role text, role_rank integer, depth integer, chip_balance numeric, total_fees numeric, is_online boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_scope uuid[] := public.fn_club_scope_ids(p_club_id);
  v_access text := public.ca_club_roster_access(p_club_id, p_user_id);
BEGIN
  IF v_access NOT IN ('staff', 'downline', 'service') OR v_scope IS NULL THEN RETURN; END IF;

  RETURN QUERY
  WITH RECURSIVE edges AS MATERIALIZED (
    SELECT DISTINCT cm.user_id AS child, cm.agent_id AS parent
      FROM public.club_members cm
     WHERE cm.club_id = p_club_id AND cm.agent_id IS NOT NULL AND cm.agent_id <> cm.user_id
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
  ), tree AS (
    SELECT e.child, 1 AS depth FROM edges e WHERE e.parent = p_user_id
    UNION ALL
    SELECT e.child, t.depth + 1 FROM tree t JOIN edges e ON e.parent = t.child WHERE t.depth < 20
  ), flat AS MATERIALIZED (
    SELECT t.child AS uid, min(t.depth)::int AS depth FROM tree t GROUP BY t.child
  ), mem AS MATERIALIZED (
    SELECT DISTINCT ON (cm.user_id) cm.user_id AS uid, cm.role, cm.chip_balance,
           public.fn_club_role_rank(cm.role) AS role_rank
      FROM public.club_members cm
     WHERE cm.club_id = p_club_id AND cm.user_id IN (SELECT f.uid FROM flat f)
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
     ORDER BY cm.user_id, public.fn_club_role_rank(cm.role) DESC, cm.joined_at ASC
  ), seated AS MATERIALIZED (
    SELECT DISTINCT ts.user_id AS uid FROM public.table_seats ts
      JOIN public.tables t ON t.id = ts.table_id
     WHERE ts.left_at IS NULL AND ts.user_id IN (SELECT f.uid FROM flat f)
       AND t.status IN ('waiting', 'running')
       AND (ts.club_id = p_club_id OR t.club_id = p_club_id)
  ), fees AS MATERIALIZED (
    SELECT r.user_id AS uid, sum(COALESCE(r.rake_paid, 0)) AS fee_total
      FROM public.ca_hand_facts r
     WHERE r.club_id = p_club_id AND r.user_id IN (SELECT f.uid FROM flat f)
     GROUP BY r.user_id
  )
  SELECT f.uid, pr.player_number::text,
         public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                              pr.first_name, pr.last_name, pr.full_name)::text,
         coalesce(pr.username, '')::text, coalesce(m.role, 'player')::text,
         coalesce(m.role_rank, 0), f.depth, coalesce(m.chip_balance, 0)::numeric,
         round(coalesce(fe.fee_total, 0), 2)::numeric,
         s.uid IS NOT NULL OR (coalesce(pr.is_online, false) AND pr.last_seen > now() - interval '5 minutes')
    FROM flat f LEFT JOIN mem m ON m.uid = f.uid LEFT JOIN public.profiles pr ON pr.id = f.uid
    LEFT JOIN seated s ON s.uid = f.uid LEFT JOIN fees fe ON fe.uid = f.uid
   ORDER BY f.depth, coalesce(m.role_rank, 0) DESC,
            lower(public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                                       pr.first_name, pr.last_name, pr.full_name));
END;
$$;


ALTER FUNCTION public.ca_club_member_downline(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_member_downline(p_club_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_member_downline(p_club_id uuid, p_user_id uuid) IS 'Every member beneath one agent in the club_members.agent_id tree, within the club or union scope, depth-capped at 20 and shortest-path deduplicated. Ordered by depth, then role, then Club Arena name.';


--
-- Name: ca_club_member_notes_update(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_member_notes_update(p_club_id uuid, p_target_user_id uuid, p_nickname text, p_remark text, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_scope uuid[] := public.fn_club_scope_ids(p_club_id);
  v_access text;
  v_member_club uuid;
  v_before_nickname text;
  v_before_remark text;
  v_after_nickname text := nullif(btrim(left(coalesce(p_nickname, ''), 64)), '');
  v_after_remark text := nullif(btrim(left(coalesce(p_remark, ''), 240)), '');
  v_actor_role text;
  v_request_id text := nullif(left(btrim(coalesce(p_request_id, '')), 128), '');
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Member Note Updates Require An Auditable Actor';
  END IF;

  v_access := public.ca_club_roster_access(p_club_id, p_target_user_id);
  IF v_actor = p_target_user_id THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Member Notes Are Private Staff Context, Not Self-Editable Profile Fields';
  END IF;
  IF v_access NOT IN ('staff', 'downline', 'service') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'You Do Not Have Permission To Edit These Notes';
  END IF;

  IF v_request_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.audit_trail a
     WHERE a.actor_id IS NOT DISTINCT FROM v_actor
       AND a.action = 'update_member_notes'
       AND a.target_id = p_target_user_id
       AND a.club_id = p_club_id
       AND a.request_id = v_request_id
  ) THEN
    SELECT cm.nickname, cm.notes
      INTO v_after_nickname, v_after_remark
      FROM public.club_members cm
     WHERE cm.user_id = p_target_user_id AND cm.club_id = ANY(v_scope)
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
     ORDER BY public.fn_club_role_rank(cm.role) DESC, cm.joined_at ASC
     LIMIT 1;
    RETURN jsonb_build_object(
      'success', true, 'replayed', true,
      'nickname', v_after_nickname, 'remark', v_after_remark
    );
  END IF;

  SELECT cm.club_id, cm.nickname, cm.notes
    INTO v_member_club, v_before_nickname, v_before_remark
    FROM public.club_members cm
   WHERE cm.user_id = p_target_user_id AND cm.club_id = ANY(v_scope)
     AND coalesce(cm.status, 'approved') IN ('active', 'approved')
   ORDER BY public.fn_club_role_rank(cm.role) DESC, cm.joined_at ASC
   LIMIT 1 FOR UPDATE;

  IF v_member_club IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Member Not Found');
  END IF;

  PERFORM set_config('app.club_notes_update', 'on', true);
  UPDATE public.club_members
     SET nickname = v_after_nickname, notes = v_after_remark, updated_at = now()
   WHERE club_id = v_member_club AND user_id = p_target_user_id;
  PERFORM set_config('app.club_notes_update', '', true);

  SELECT cm.role INTO v_actor_role FROM public.club_members cm
   WHERE cm.user_id = v_actor AND cm.club_id = ANY(v_scope)
   ORDER BY public.fn_club_role_rank(cm.role) DESC LIMIT 1;

  INSERT INTO public.audit_trail (
    actor_id, actor_role, action, target_type, target_id, club_id,
    before_state, after_state, reason, request_id
  ) VALUES (
    v_actor, coalesce(v_actor_role, 'service_role'), 'update_member_notes',
    'club_member', p_target_user_id, p_club_id,
    jsonb_build_object(
      'nickname_present', v_before_nickname IS NOT NULL,
      'remark_present', v_before_remark IS NOT NULL,
      'nickname_length', length(coalesce(v_before_nickname, '')),
      'remark_length', length(coalesce(v_before_remark, ''))
    ),
    jsonb_build_object(
      'nickname_present', v_after_nickname IS NOT NULL,
      'remark_present', v_after_remark IS NOT NULL,
      'nickname_length', length(coalesce(v_after_nickname, '')),
      'remark_length', length(coalesce(v_after_remark, ''))
    ),
    'Authorized Member Note Update', v_request_id
  );

  RETURN jsonb_build_object(
    'success', true, 'replayed', false,
    'nickname', v_after_nickname, 'remark', v_after_remark
  );
END
$$;


ALTER FUNCTION public.ca_club_member_notes_update(p_club_id uuid, p_target_user_id uuid, p_nickname text, p_remark text, p_request_id text) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_member_notes_update(p_club_id uuid, p_target_user_id uuid, p_nickname text, p_remark text, p_request_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_member_notes_update(p_club_id uuid, p_target_user_id uuid, p_nickname text, p_remark text, p_request_id text) IS 'Audited, idempotent member-note writer. Replays return the complete persisted note response and never duplicate the audit row.';


--
-- Name: ca_club_member_statistics(uuid, uuid, text, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_member_statistics(p_club_id uuid, p_user_id uuid, p_variant text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_access text := public.ca_club_roster_access(p_club_id, p_user_id);
  v_variant text := NULLIF(lower(btrim(COALESCE(p_variant, ''))), '');
  v_from timestamptz := CASE WHEN p_from IS NULL THEN NULL ELSE p_from::timestamp AT TIME ZONE 'UTC' END;
  v_to timestamptz := CASE WHEN p_to IS NULL THEN NULL ELSE (p_to + 1)::timestamp AT TIME ZONE 'UTC' END;
  v_viewer_is_member boolean;
  v_target_is_member boolean;
  v_out jsonb;
BEGIN
  IF v_access NOT IN ('staff','downline','service') THEN
    -- A member of the club asking about somebody who is not one is told so;
    -- anyone else is told only that they may not look.
    v_viewer_is_member := auth.uid() IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.club_members cm
       WHERE cm.club_id = p_club_id AND cm.user_id = auth.uid()
         AND coalesce(cm.status, 'approved') IN ('active', 'approved'));
    v_target_is_member := EXISTS (
      SELECT 1 FROM public.club_members cm
       WHERE cm.club_id = p_club_id AND cm.user_id = p_user_id
         AND coalesce(cm.status, 'approved') IN ('active', 'approved'));
    RETURN jsonb_build_object(
      'authorized', false,
      'reason', CASE WHEN v_viewer_is_member AND NOT v_target_is_member
                     THEN 'not_member' ELSE 'restricted' END);
  END IF;

  WITH agg AS (
    SELECT count(DISTINCT f.hand_id)::bigint hands,
           count(DISTINCT f.hand_id) FILTER (WHERE f.net > 0)::bigint wins,
           count(*) FILTER (WHERE f.vpip)::bigint vpip_hands,
           count(*) FILTER (WHERE f.pfr)::bigint pfr_hands,
           count(*) FILTER (WHERE f.three_bet)::bigint tb_hands,
           -- faced_three_bet: this player OPENED and was 3-bet. The
           -- denominator of fold-to-3-bet, never of 3-bet.
           count(*) FILTER (WHERE f.faced_three_bet)::bigint faced_tb,
           count(*) FILTER (WHERE f.folded_to_three_bet)::bigint folded_tb,
           count(*) FILTER (WHERE f.cbet_flop)::bigint cb_hands,
           count(*) FILTER (WHERE f.had_cbet_flop_opp)::bigint cb_opps,
           COALESCE(sum(f.net),0) net, COALESCE(sum(f.rake_paid),0) fees
      FROM public.ca_hand_facts f
     WHERE f.club_id = p_club_id AND f.user_id = p_user_id
       AND (v_variant IS NULL OR v_variant = 'all' OR lower(f.game_variant) = v_variant)
       AND (v_from IS NULL OR f.played_at >= v_from) AND (v_to IS NULL OR f.played_at < v_to)
  ), vars AS (
    SELECT COALESCE(jsonb_agg(v.game_variant ORDER BY v.game_variant), '[]'::jsonb) list
      FROM (SELECT DISTINCT lower(f.game_variant) game_variant FROM public.ca_hand_facts f
             WHERE f.club_id = p_club_id AND f.user_id = p_user_id
               AND f.game_variant IS NOT NULL) v
  )
  SELECT jsonb_build_object(
    'authorized', true, 'variant', COALESCE(v_variant,'all'), 'variants', vars.list,
    'hands', a.hands,
    'hands_won', a.wins,
    'win_rate', COALESCE(round(100.0*a.wins/NULLIF(a.hands,0),2),0),
    'vpip', COALESCE(round(100.0*a.vpip_hands/NULLIF(a.hands,0),2),0),
    'pfr',  COALESCE(round(100.0*a.pfr_hands/NULLIF(a.hands,0),2),0),
    -- 3-bets per hand dealt. Not per opportunity: the facts table does not
    -- record whether this player faced an open they could have 3-bet.
    'three_bet', COALESCE(round(100.0*a.tb_hands/NULLIF(a.hands,0),2),0),
    'three_bet_basis', 'hands',
    'three_bets', a.tb_hands,
    'fold_to_three_bet', COALESCE(round(100.0*a.folded_tb/NULLIF(a.faced_tb,0),2),0),
    'faced_three_bets', a.faced_tb,
    'cbet', COALESCE(round(100.0*a.cb_hands/NULLIF(a.cb_opps,0),2),0),
    'cbet_opportunities', a.cb_opps,
    'net', round(a.net,2), 'fees', round(a.fees,2),
    'from', p_from, 'to', p_to, 'is_overall', p_from IS NULL AND p_to IS NULL
  ) INTO v_out FROM agg a CROSS JOIN vars;
  RETURN v_out;
END;
$$;


ALTER FUNCTION public.ca_club_member_statistics(p_club_id uuid, p_user_id uuid, p_variant text, p_from date, p_to date) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_member_statistics(p_club_id uuid, p_user_id uuid, p_variant text, p_from date, p_to date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_member_statistics(p_club_id uuid, p_user_id uuid, p_variant text, p_from date, p_to date) IS 'Poker statistics for one member of a club. three_bet is 3-bets per hand dealt (three_bet_basis says so); fold_to_three_bet is folds per open that was 3-bet. hands / hands_won / win_rate replace total_games / total_hands / winner, kept one release. authorized=false carries reason not_member or restricted.';


--
-- Name: ca_club_members(uuid, text, timestamp with time zone, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_members(p_club_id uuid, p_search text DEFAULT NULL::text, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_sort text DEFAULT 'hands'::text, p_role text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, display_name text, avatar_url text, is_horse boolean, is_online boolean, role text, status text, joined_at timestamp with time zone, last_active timestamp with time zone, chip_balance numeric, hands_played bigint, profit numeric, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_search text := nullif(btrim(coalesce(p_search, '')), '');
  v_role   text := nullif(btrim(coalesce(p_role, '')), '');
  v_sort   text := lower(coalesce(p_sort, 'hands'));
  v_may_see boolean := public.fn_can_see_horse_flag(p_club_id);
BEGIN
  IF NOT ca_can_view_club(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH seated AS (
    SELECT DISTINCT ts.user_id
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
    WHERE t.club_id = p_club_id AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
  ),
  roster AS (
    SELECT cm.user_id, cm.role, cm.status, cm.created_at AS joined_at,
           cm.last_active, cm.chip_balance::numeric AS chip_balance,
           coalesce(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), cm.display_name, 'Player') AS display_name,
           pr.avatar_url,
           -- MASKED: staff get the truth, everyone else gets a uniform false.
           (v_may_see AND coalesce(pr.is_horse, false)) AS is_horse,
           (s.user_id IS NOT NULL
            OR cm.last_active > now() - interval '15 minutes') AS is_online
    FROM club_members cm
    LEFT JOIN profiles pr ON pr.id = cm.user_id
    LEFT JOIN seated s ON s.user_id = cm.user_id
    WHERE cm.club_id = p_club_id
      AND coalesce(cm.status, 'active') NOT IN ('banned')
      AND (v_search IS NULL
           OR coalesce(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), cm.display_name, '') ILIKE '%' || v_search || '%')
      AND (v_role IS NULL OR coalesce(cm.role, 'member') = v_role)
  ),
  perf AS (
    SELECT s.user_id,
           sum(s.hands_played)::bigint AS hands_played,
           sum(s.profit)               AS profit
    FROM club_member_daily_stats s
    WHERE s.club_id = p_club_id
      AND (p_since IS NULL OR s.stat_date >= (p_since AT TIME ZONE 'UTC')::date)
    GROUP BY s.user_id
  ),
  counted AS (SELECT count(*) AS n FROM roster)
  SELECT
    r.user_id, r.display_name, r.avatar_url, r.is_horse, r.is_online,
    r.role, r.status, r.joined_at, r.last_active, r.chip_balance,
    coalesce(p.hands_played, 0)::bigint,
    coalesce(p.profit, 0),
    c.n
  FROM roster r
  LEFT JOIN perf p ON p.user_id = r.user_id
  CROSS JOIN counted c
  ORDER BY
    CASE WHEN v_sort = 'profit' THEN coalesce(p.profit, 0) END DESC NULLS LAST,
    CASE WHEN v_sort = 'hands'  THEN coalesce(p.hands_played, 0) END DESC NULLS LAST,
    CASE WHEN v_sort = 'joined' THEN r.joined_at END DESC NULLS LAST,
    CASE WHEN v_sort = 'last_active' THEN r.last_active END DESC NULLS LAST,
    CASE WHEN v_sort = 'name'   THEN lower(r.display_name) END ASC NULLS LAST,
    r.joined_at DESC NULLS LAST,
    r.user_id
  LIMIT least(greatest(coalesce(p_limit, 50), 1), 200)
  OFFSET greatest(coalesce(p_offset, 0), 0);
END;
$$;


ALTER FUNCTION public.ca_club_members(p_club_id uuid, p_search text, p_since timestamp with time zone, p_limit integer, p_offset integer, p_sort text, p_role text) OWNER TO postgres;

--
-- Name: ca_club_members_export(uuid, text, text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_members_export(p_club_id uuid, p_search text DEFAULT ''::text, p_filter text DEFAULT 'all'::text, p_sort text DEFAULT 'hierarchy'::text, p_user_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_scope uuid[] := public.fn_club_scope_ids(p_club_id);
  v_service boolean := coalesce(auth.role(), 'service_role') = 'service_role';
  v_platform_admin boolean := false;
  v_union_staff boolean := false;
  v_staff boolean := false;
  v_actor_role text := 'service_role';
  v_search text := lower(left(btrim(coalesce(p_search, '')), 120));
  v_filter text := lower(coalesce(nullif(btrim(p_filter), ''), 'all'));
  v_sort text := lower(coalesce(nullif(btrim(p_sort), ''), 'hierarchy'));
  v_rows jsonb;
  v_count int := 0;
  v_audit_id uuid;
BEGIN
  IF v_filter NOT IN ('all', 'mine', 'seated', 'online', 'agents', 'admins',
    'inactive_30', 'inactive_60', 'inactive_90', 'high_fees') THEN v_filter := 'all'; END IF;
  IF v_sort NOT IN ('hierarchy', 'activity', 'name', 'downlines', 'wallet', 'fees') THEN v_sort := 'hierarchy'; END IF;
  IF coalesce(array_length(p_user_ids, 1), 0) > 5000 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Select No More Than 5,000 Players Per Export';
  END IF;

  IF v_scope IS NULL OR array_length(v_scope, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Club Not Found');
  END IF;

  IF NOT v_service AND v_actor IS NOT NULL THEN
    SELECT coalesce(p.is_admin, false) INTO v_platform_admin
      FROM public.profiles p WHERE p.id = v_actor;
    v_union_staff := coalesce(public.fn_is_union_overseer(p_club_id, v_actor), false);
    SELECT cm.role INTO v_actor_role
      FROM public.club_members cm
     WHERE cm.user_id = v_actor AND cm.club_id = p_club_id
       AND cm.role IN ('owner', 'co_owner', 'admin')
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
     ORDER BY public.fn_club_role_rank(cm.role) DESC LIMIT 1;
    v_staff := v_platform_admin OR v_union_staff OR v_actor_role IS NOT NULL;
  ELSE
    v_staff := v_service;
  END IF;

  IF NOT v_staff THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Roster Export Requires Club Staff Access';
  END IF;
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Roster Export Requires An Auditable Actor';
  END IF;

  IF v_actor_role IS NULL THEN
    v_actor_role := CASE
      WHEN v_platform_admin THEN 'platform_admin'
      WHEN v_union_staff THEN 'union_admin'
      ELSE 'system'
    END;
  END IF;

  WITH rows AS MATERIALIZED (
    SELECT r.*,
           lower(r.alias) AS sort_name,
           CASE WHEN r.is_seated THEN 2 WHEN r.is_online THEN 1 ELSE 0 END AS presence_rank,
           coalesce(extract(epoch FROM r.last_login), 0)::numeric AS activity_epoch,
           coalesce(r.player_wallet, 0) + coalesce(r.agent_wallet, 0) AS wallet_total
      FROM public.ca_club_roster_rows(p_club_id) r
     WHERE r.can_view_financials
       AND (p_user_ids IS NULL OR r.user_id = ANY(p_user_ids))
       AND (
         v_search = '' OR position(v_search in lower(r.alias)) > 0
         OR position(v_search in lower(r.username)) > 0
         OR position(v_search in lower(coalesce(r.player_number, ''))) > 0
         OR position(v_search in lower(coalesce(r.home_club_name, ''))) > 0
         OR position(v_search in lower(coalesce(r.upline_name, ''))) > 0
       )
       AND CASE v_filter
         WHEN 'mine' THEN r.in_viewer_downline
         WHEN 'seated' THEN r.is_seated
         WHEN 'online' THEN r.is_online
         WHEN 'agents' THEN r.role IN ('super_agent', 'agent', 'sub_agent')
         WHEN 'admins' THEN r.role IN ('owner', 'co_owner', 'admin')
         WHEN 'inactive_30' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '30 days'
         WHEN 'inactive_60' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '60 days'
         WHEN 'inactive_90' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '90 days'
         WHEN 'high_fees' THEN coalesce(r.total_fees, 0) >= 100
         ELSE true END
  ), ordered AS (
    SELECT r.* FROM rows r
     ORDER BY
       CASE WHEN v_sort = 'hierarchy' THEN r.role_rank END DESC,
       CASE WHEN v_sort = 'hierarchy' THEN coalesce(r.downline_total, 0) END DESC,
       CASE WHEN v_sort = 'activity' THEN r.presence_rank END DESC,
       CASE WHEN v_sort = 'activity' THEN r.activity_epoch END DESC,
       CASE WHEN v_sort = 'name' THEN r.sort_name END ASC,
       CASE WHEN v_sort = 'downlines' THEN coalesce(r.downline_total, 0) END DESC,
       CASE WHEN v_sort = 'wallet' THEN r.wallet_total END DESC,
       CASE WHEN v_sort = 'fees' THEN coalesce(r.total_fees, 0) END DESC,
       r.sort_name ASC, r.user_id ASC
  )
  SELECT coalesce(jsonb_agg(
           to_jsonb(o) - ARRAY['sort_name', 'presence_rank', 'activity_epoch', 'wallet_total',
                                  'can_view_financials', 'can_view_notes', 'in_viewer_downline']::text[]
         ), '[]'::jsonb), count(*)::int
    INTO v_rows, v_count
    FROM ordered o;

  INSERT INTO public.audit_trail (
    actor_id, actor_role, action, target_type, target_id, club_id,
    after_state, reason
  ) VALUES (
    v_actor, v_actor_role,
    'export_club_roster', 'club', p_club_id, p_club_id,
    jsonb_build_object(
      'row_count', v_count,
      'selected_only', p_user_ids IS NOT NULL,
      'selected_count', coalesce(array_length(p_user_ids, 1), 0),
      'filter', v_filter,
      'sort', v_sort,
      'search_used', v_search <> ''
    ),
    'Authorized Club Roster Export'
  ) RETURNING id INTO v_audit_id;

  RETURN jsonb_build_object(
    'success', true,
    'rows', v_rows,
    'row_count', v_count,
    'audit_id', v_audit_id
  );
END;
$$;


ALTER FUNCTION public.ca_club_members_export(p_club_id uuid, p_search text, p_filter text, p_sort text, p_user_ids uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_members_export(p_club_id uuid, p_search text, p_filter text, p_sort text, p_user_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_members_export(p_club_id uuid, p_search text, p_filter text, p_sort text, p_user_ids uuid[]) IS 'Staff-only full or selected roster export. Every successful export writes an audit_trail row without storing the search text.';


--
-- Name: ca_club_members_overview(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_members_overview(p_club_id uuid) RETURNS TABLE(user_id uuid, home_club_id uuid, home_club_name text, player_number text, alias text, username text, display_name text, avatar_url text, role text, role_rank integer, is_online boolean, is_seated boolean, chip_balance numeric, player_wallet numeric, agent_wallet numeric, promo_wallet numeric, total_fees numeric, downline_fees numeric, total_hands bigint, downline_direct integer, downline_total integer, upline_user_id uuid, upline_name text, joined_at timestamp with time zone, last_login timestamp with time zone, nickname text, remark text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT r.user_id, r.home_club_id, r.home_club_name, r.player_number,
         r.alias, r.username, r.display_name, r.avatar_url, r.role, r.role_rank,
         r.is_online, r.is_seated, r.chip_balance, r.player_wallet,
         r.agent_wallet, r.promo_wallet, r.total_fees, r.downline_fees,
         r.total_hands, r.downline_direct, r.downline_total, r.upline_user_id,
         r.upline_name, r.joined_at, r.last_login, r.nickname, r.remark
    FROM public.ca_club_roster_rows(p_club_id) r
   ORDER BY r.role_rank DESC, coalesce(r.downline_total, 0) DESC, lower(r.alias), r.user_id;
$$;


ALTER FUNCTION public.ca_club_members_overview(p_club_id uuid) OWNER TO postgres;

--
-- Name: ca_club_members_page(uuid, text, text, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_members_page(p_club_id uuid, p_search text DEFAULT ''::text, p_filter text DEFAULT 'all'::text, p_sort text DEFAULT 'hierarchy'::text, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 80) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_search text := lower(left(btrim(coalesce(p_search, '')), 120));
  v_filter text := lower(coalesce(nullif(btrim(p_filter), ''), 'all'));
  v_sort text := lower(coalesce(nullif(btrim(p_sort), ''), 'hierarchy'));
  v_limit int := greatest(20, least(coalesce(p_limit, 80), 200));
  v_cursor jsonb := p_cursor;
  v_out jsonb;
BEGIN
  IF v_filter NOT IN (
    'all', 'mine', 'seated', 'online', 'agents', 'admins',
    'inactive_30', 'inactive_60', 'inactive_90', 'high_fees'
  ) THEN
    v_filter := 'all';
  END IF;
  IF v_sort NOT IN ('hierarchy', 'activity', 'name', 'downlines', 'wallet', 'fees') THEN
    v_sort := 'hierarchy';
  END IF;

  -- A cursor belongs to one viewer, club and normalized query. A token from
  -- another tab or saved view restarts safely instead of skipping rows.
  IF v_cursor IS NOT NULL AND (
    coalesce(v_cursor->>'v', '') <> '2'
    OR coalesce(v_cursor->>'club', '') <> p_club_id::text
    OR coalesce(v_cursor->>'actor', '') <> coalesce(v_actor::text, 'service')
    OR coalesce(v_cursor->>'search', '') <> md5(v_search)
    OR coalesce(v_cursor->>'filter', '') <> v_filter
    OR coalesce(v_cursor->>'sort', '') <> v_sort
  ) THEN
    v_cursor := NULL;
  END IF;

  -- A cursor is an opaque server token, but it still crosses a hostile client
  -- boundary. Treat malformed numeric components as an expired cursor instead
  -- of letting a text-to-number cast turn the whole roster into a 500.
  IF v_cursor IS NOT NULL AND (
    (v_cursor ? 'rank' AND coalesce(v_cursor->>'rank', '') !~ '^-?[0-9]+$')
    OR (v_cursor ? 'downlines' AND coalesce(v_cursor->>'downlines', '') !~ '^-?[0-9]+$')
    OR (v_cursor ? 'presence' AND coalesce(v_cursor->>'presence', '') !~ '^-?[0-9]+$')
    OR (v_cursor ? 'activity' AND coalesce(v_cursor->>'activity', '') !~ '^-?[0-9]+([.][0-9]+)?$')
    OR (v_cursor ? 'metric' AND coalesce(v_cursor->>'metric', '') !~ '^-?[0-9]+([.][0-9]+)?$')
  ) THEN
    v_cursor := NULL;
  END IF;

  WITH rows AS MATERIALIZED (
    SELECT r.*,
           lower(r.alias) AS sort_name,
           CASE WHEN r.is_seated THEN 2 WHEN r.is_online THEN 1 ELSE 0 END AS presence_rank,
           coalesce(extract(epoch FROM r.last_login), 0)::numeric AS activity_epoch,
           coalesce(r.player_wallet, 0) + coalesce(r.agent_wallet, 0) AS wallet_total
      FROM public.ca_club_roster_rows(p_club_id) r
     WHERE (
       v_search = ''
       OR position(v_search in lower(r.alias)) > 0
       OR position(v_search in lower(r.username)) > 0
       OR position(v_search in lower(coalesce(r.player_number, ''))) > 0
       OR position(v_search in lower(coalesce(r.home_club_name, ''))) > 0
       OR position(v_search in lower(coalesce(r.upline_name, ''))) > 0
     )
       AND CASE v_filter
         WHEN 'mine' THEN r.in_viewer_downline
         WHEN 'seated' THEN r.is_seated
         WHEN 'online' THEN r.is_online
         WHEN 'agents' THEN r.role IN ('super_agent', 'agent', 'sub_agent')
         WHEN 'admins' THEN r.role IN ('owner', 'co_owner', 'admin')
         WHEN 'inactive_30' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '30 days'
         WHEN 'inactive_60' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '60 days'
         WHEN 'inactive_90' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '90 days'
         WHEN 'high_fees' THEN coalesce(r.total_fees, 0) >= 100
         ELSE true
       END
  ), eligible AS MATERIALIZED (
    SELECT r.*
      FROM rows r
     WHERE v_cursor IS NULL OR CASE v_sort
       WHEN 'name' THEN
         (r.sort_name, r.user_id::text) >
         (coalesce(v_cursor->>'name', ''), coalesce(v_cursor->>'id', ''))
       WHEN 'activity' THEN
         r.presence_rank < coalesce((v_cursor->>'presence')::int, 0)
         OR (r.presence_rank = coalesce((v_cursor->>'presence')::int, 0)
             AND r.activity_epoch < coalesce((v_cursor->>'activity')::numeric, 0))
         OR (r.presence_rank = coalesce((v_cursor->>'presence')::int, 0)
             AND r.activity_epoch = coalesce((v_cursor->>'activity')::numeric, 0)
             AND r.user_id::text > coalesce(v_cursor->>'id', ''))
       WHEN 'downlines' THEN
         coalesce(r.downline_total, 0) < coalesce((v_cursor->>'metric')::numeric, 0)
         OR (coalesce(r.downline_total, 0) = coalesce((v_cursor->>'metric')::numeric, 0)
             AND r.user_id::text > coalesce(v_cursor->>'id', ''))
       WHEN 'wallet' THEN
         r.wallet_total < coalesce((v_cursor->>'metric')::numeric, 0)
         OR (r.wallet_total = coalesce((v_cursor->>'metric')::numeric, 0)
             AND r.user_id::text > coalesce(v_cursor->>'id', ''))
       WHEN 'fees' THEN
         coalesce(r.total_fees, 0) < coalesce((v_cursor->>'metric')::numeric, 0)
         OR (coalesce(r.total_fees, 0) = coalesce((v_cursor->>'metric')::numeric, 0)
             AND r.user_id::text > coalesce(v_cursor->>'id', ''))
       ELSE
         r.role_rank < coalesce((v_cursor->>'rank')::int, 0)
         OR (r.role_rank = coalesce((v_cursor->>'rank')::int, 0)
             AND coalesce(r.downline_total, 0) < coalesce((v_cursor->>'downlines')::int, 0))
         OR (r.role_rank = coalesce((v_cursor->>'rank')::int, 0)
             AND coalesce(r.downline_total, 0) = coalesce((v_cursor->>'downlines')::int, 0)
             AND r.sort_name > coalesce(v_cursor->>'name', ''))
         OR (r.role_rank = coalesce((v_cursor->>'rank')::int, 0)
             AND coalesce(r.downline_total, 0) = coalesce((v_cursor->>'downlines')::int, 0)
             AND r.sort_name = coalesce(v_cursor->>'name', '')
             AND r.user_id::text > coalesce(v_cursor->>'id', ''))
       END
  ), ordered AS MATERIALIZED (
    SELECT e.*,
           row_number() OVER (
             ORDER BY
               CASE WHEN v_sort = 'hierarchy' THEN e.role_rank END DESC,
               CASE WHEN v_sort = 'hierarchy' THEN coalesce(e.downline_total, 0) END DESC,
               CASE WHEN v_sort = 'hierarchy' THEN e.sort_name END ASC,
               CASE WHEN v_sort = 'activity' THEN e.presence_rank END DESC,
               CASE WHEN v_sort = 'activity' THEN e.activity_epoch END DESC,
               CASE WHEN v_sort = 'name' THEN e.sort_name END ASC,
               CASE WHEN v_sort = 'downlines' THEN coalesce(e.downline_total, 0) END DESC,
               CASE WHEN v_sort = 'wallet' THEN e.wallet_total END DESC,
               CASE WHEN v_sort = 'fees' THEN coalesce(e.total_fees, 0) END DESC,
               e.user_id ASC
           ) AS rn
      FROM eligible e
     ORDER BY
       CASE WHEN v_sort = 'hierarchy' THEN e.role_rank END DESC,
       CASE WHEN v_sort = 'hierarchy' THEN coalesce(e.downline_total, 0) END DESC,
       CASE WHEN v_sort = 'hierarchy' THEN e.sort_name END ASC,
       CASE WHEN v_sort = 'activity' THEN e.presence_rank END DESC,
       CASE WHEN v_sort = 'activity' THEN e.activity_epoch END DESC,
       CASE WHEN v_sort = 'name' THEN e.sort_name END ASC,
       CASE WHEN v_sort = 'downlines' THEN coalesce(e.downline_total, 0) END DESC,
       CASE WHEN v_sort = 'wallet' THEN e.wallet_total END DESC,
       CASE WHEN v_sort = 'fees' THEN coalesce(e.total_fees, 0) END DESC,
       e.user_id ASC
     LIMIT v_limit + 1
  ), visible AS MATERIALIZED (
    SELECT * FROM ordered WHERE rn <= v_limit
  ), last_row AS (
    SELECT * FROM visible ORDER BY rn DESC LIMIT 1
  )
  SELECT jsonb_build_object(
    'items', coalesce((
      SELECT jsonb_agg(
        to_jsonb(v) - ARRAY['sort_name', 'presence_rank', 'activity_epoch', 'wallet_total', 'rn']::text[]
        ORDER BY v.rn
      ) FROM visible v
    ), '[]'::jsonb),
    'next_cursor', CASE WHEN (SELECT count(*) FROM ordered) > v_limit THEN (
      SELECT jsonb_build_object(
        'v', 2,
        'club', p_club_id,
        'actor', coalesce(v_actor::text, 'service'),
        'search', md5(v_search),
        'filter', v_filter,
        'sort', v_sort,
        'id', l.user_id,
        'name', l.sort_name,
        'rank', l.role_rank,
        'downlines', coalesce(l.downline_total, 0),
        'presence', l.presence_rank,
        'activity', l.activity_epoch,
        'metric', CASE v_sort
          WHEN 'wallet' THEN l.wallet_total
          WHEN 'fees' THEN coalesce(l.total_fees, 0)
          WHEN 'downlines' THEN coalesce(l.downline_total, 0)
          ELSE 0 END
      ) FROM last_row l
    ) ELSE NULL END,
    'has_more', (SELECT count(*) FROM ordered) > v_limit,
    'filtered_total', (SELECT count(*) FROM rows),
    'query', jsonb_build_object('filter', v_filter, 'sort', v_sort)
  ) INTO v_out;

  RETURN coalesce(v_out, jsonb_build_object(
    'items', '[]'::jsonb,
    'next_cursor', NULL,
    'has_more', false,
    'filtered_total', 0,
    'query', jsonb_build_object('filter', v_filter, 'sort', v_sort)
  ));
END;
$_$;


ALTER FUNCTION public.ca_club_members_page(p_club_id uuid, p_search text, p_filter text, p_sort text, p_cursor jsonb, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_members_page(p_club_id uuid, p_search text, p_filter text, p_sort text, p_cursor jsonb, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_members_page(p_club_id uuid, p_search text, p_filter text, p_sort text, p_cursor jsonb, p_limit integer) IS 'Role-shaped keyset roster. Cursor v2 is bound to viewer, club, normalized search, filter and sort; stale or hostile cursors restart safely.';


--
-- Name: ca_club_members_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_members_summary(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_scope uuid[];
  v_service boolean := coalesce(auth.role(), 'service_role') = 'service_role';
  v_platform_admin boolean := false;
  v_union_staff boolean := false;
  v_viewer_role text := 'player';
  v_has_agent_scope boolean := false;
  v_has_staff_scope boolean := false;
  v_can_export boolean := false;
  v_out jsonb;
BEGIN
  v_scope := public.fn_club_scope_ids(p_club_id);
  IF v_scope IS NULL OR array_length(v_scope, 1) IS NULL THEN
    RETURN NULL;
  END IF;

  IF NOT v_service AND v_actor IS NOT NULL THEN
    SELECT coalesce(p.is_admin, false)
      INTO v_platform_admin FROM public.profiles p WHERE p.id = v_actor;
    v_union_staff := coalesce(public.fn_is_union_overseer(p_club_id, v_actor), false);
  END IF;

  IF NOT v_service AND NOT v_platform_admin AND NOT v_union_staff THEN
    SELECT cm.role
      INTO v_viewer_role
      FROM public.club_members cm
     WHERE cm.user_id = v_actor
       AND cm.club_id = ANY(v_scope)
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
     ORDER BY public.fn_club_role_rank(cm.role) DESC
     LIMIT 1;
    IF v_viewer_role IS NULL THEN
      RETURN NULL;
    END IF;
  ELSIF v_platform_admin OR v_union_staff OR v_service THEN
    v_viewer_role := 'owner';
  END IF;

  SELECT EXISTS (
           SELECT 1 FROM public.club_members cm
            WHERE cm.user_id = v_actor AND cm.club_id = ANY(v_scope)
              AND cm.role IN ('super_agent', 'agent', 'sub_agent')
              AND coalesce(cm.status, 'approved') IN ('active', 'approved')
         ),
         EXISTS (
           SELECT 1 FROM public.club_members cm
            WHERE cm.user_id = v_actor AND cm.club_id = ANY(v_scope)
              AND cm.role IN ('owner', 'co_owner', 'admin')
              AND coalesce(cm.status, 'approved') IN ('active', 'approved')
         )
    INTO v_has_agent_scope, v_has_staff_scope;

  v_can_export := v_service OR v_platform_admin OR v_union_staff OR EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.user_id = v_actor AND cm.club_id = p_club_id
       AND cm.role IN ('owner', 'co_owner', 'admin')
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
  );

  WITH base AS MATERIALIZED (
    -- THIS club, as ca_club_roster_rows counts it since 2026-09-01. The
    -- scope above still decides who the VIEWER is; it no longer decides
    -- what is counted.
    SELECT DISTINCT ON (cm.user_id)
           cm.user_id, cm.role, public.fn_club_role_rank(cm.role) AS role_rank,
           cm.updated_at
      FROM public.club_members cm
     WHERE cm.club_id = p_club_id
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
     ORDER BY cm.user_id, public.fn_club_role_rank(cm.role) DESC, cm.joined_at ASC
  ), seated AS MATERIALIZED (
    SELECT DISTINCT live.user_id
      FROM (
        SELECT ts.user_id
          FROM public.table_seats ts
          JOIN public.tables t ON t.id = ts.table_id
         WHERE ts.left_at IS NULL AND ts.user_id IS NOT NULL
           AND ts.club_id = p_club_id
           AND t.status IN ('waiting', 'running')
        UNION
        SELECT ts.user_id
          FROM public.tables t
          JOIN public.table_seats ts ON ts.table_id = t.id
         WHERE ts.left_at IS NULL AND ts.user_id IS NOT NULL
           AND t.club_id = p_club_id
           AND t.status IN ('waiting', 'running')
      ) live
  )
  SELECT jsonb_build_object(
    'viewer_role', coalesce(v_viewer_role, 'player'),
    'capabilities', jsonb_build_object(
      'can_view_financials', v_service OR v_platform_admin OR v_union_staff
                              OR v_has_staff_scope OR v_has_agent_scope,
      'can_export', v_can_export,
      'can_manage_members', v_service OR v_platform_admin OR v_union_staff OR v_has_staff_scope,
      'can_view_notes', v_service OR v_platform_admin OR v_union_staff
                        OR v_has_staff_scope OR v_has_agent_scope
    ),
    'counts', jsonb_build_object(
      'total', count(*),
      'online', count(*) FILTER (
        WHERE s.user_id IS NOT NULL
           OR (coalesce(pr.is_online, false) AND pr.last_seen > now() - interval '5 minutes')
      ),
      'seated', count(*) FILTER (WHERE s.user_id IS NOT NULL),
      'agents', count(*) FILTER (WHERE b.role IN ('super_agent', 'agent', 'sub_agent')),
      'admins', count(*) FILTER (WHERE b.role IN ('owner', 'co_owner', 'admin'))
    ),
    'data_version', max(b.updated_at),
    'page_size', 80
  ) INTO v_out
  FROM base b
  LEFT JOIN seated s ON s.user_id = b.user_id
  LEFT JOIN public.profiles pr ON pr.id = b.user_id;

  RETURN v_out;
END;
$$;


ALTER FUNCTION public.ca_club_members_summary(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_members_summary(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_members_summary(p_club_id uuid) IS 'Roster header: the viewer''s role and capabilities (resolved across the club''s scope) and the counts of THIS club''s members, seated, online, agents and admins - the same set ca_club_roster_rows lists.';


--
-- Name: ca_club_my_downline(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_my_downline(p_club_id uuid) RETURNS TABLE(agent_id uuid, path uuid[], depth integer, username text, full_name text, avatar_url text, total_members integer, direct_members integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH RECURSIVE
  user_roles AS (
    SELECT user_id, role FROM club_members WHERE club_id = p_club_id
  ),
  tree AS (
    SELECT cm.user_id, ARRAY[cm.user_id] AS path, 1 AS depth
    FROM club_members cm
    WHERE cm.club_id = p_club_id AND cm.user_id = auth.uid() AND cm.status = 'active'
    UNION ALL
    -- CYCLE SAFETY (2026-08-24). UNION ALL never dedupes, so a cycle in the
    -- agent graph recursed until the statement timeout. Not hypothetical:
    -- club_members.agent_id holds two two-node cycles right now, and running
    -- this walk against one blew past a 4s timeout even with a 2000-row cap.
    -- Every call by an agent at or below such a cycle burned the caller's whole
    -- 8s budget and returned nothing. `path` was already accumulated for
    -- display, so using it as the visited-set costs nothing.
    SELECT cm.user_id, t.path || cm.user_id, t.depth + 1
    FROM club_members cm
    JOIN tree t ON cm.agent_id = t.user_id
    WHERE cm.club_id = p_club_id AND cm.status = 'active'
      AND NOT (cm.user_id = ANY (t.path))
      AND t.depth < 64
  )
  SELECT t.user_id AS agent_id, t.path, t.depth,
         p.username, p.full_name, p.avatar_url,
         (SELECT count(*)::int - 1 FROM tree sub WHERE sub.path @> ARRAY[t.user_id]) AS total_members,
         (SELECT count(*)::int FROM club_members child
           WHERE child.agent_id = t.user_id AND child.club_id = p_club_id
             AND child.status = 'active') AS direct_members
  FROM tree t
  JOIN profiles p ON p.id = t.user_id
  JOIN user_roles ur ON ur.user_id = t.user_id
  WHERE ur.role IN ('owner', 'co_owner', 'admin', 'agent', 'super_agent')
  ORDER BY t.path;
$$;


ALTER FUNCTION public.ca_club_my_downline(p_club_id uuid) OWNER TO postgres;

--
-- Name: ca_club_operations_overview(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_operations_overview(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role              text;
  v_platform          boolean;
  v_internal          boolean;
  v_staff             boolean;
  v_finance           boolean;
  v_control           boolean;
  v_name              text;
  v_slug              text;
  v_treasury          numeric;
  v_locked            boolean;
  v_members           bigint;
  v_pending           bigint;
  v_new7              bigint;
  v_member_chips      numeric;
  v_online            bigint;
  v_seated            bigint;
  v_live_tables       bigint;
  v_running_tables    bigint;
  v_waiting_tables    bigint;
  v_reg_tourneys      bigint;
  v_run_tourneys      bigint;
  v_hands_today       bigint := 0;
  v_rake_today        numeric := 0;
  v_reports           bigint;
  v_disputes          bigint;
  v_disputes_aged     bigint;
  v_blacklist         bigint;
  v_blacklist_expired bigint;
  v_chip_requests     bigint;
  v_cashouts          bigint;
  v_credit            bigint;
  v_invoices          bigint;
  v_invoices_overdue  bigint;
  v_tickets           bigint;
  v_flags             bigint;
  v_alerts            jsonb := '[]'::jsonb;
  v_kpis              jsonb;
BEGIN
  IF p_club_id IS NULL THEN
    RAISE EXCEPTION 'a club id is required' USING ERRCODE = '22004';
  END IF;

  SELECT c.name, c.slug, coalesce(c.chip_treasury, 0), coalesce(c.settlement_locked, false)
    INTO v_name, v_slug, v_treasury, v_locked
    FROM clubs c
   WHERE c.id = p_club_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'club not found' USING ERRCODE = 'P0002';
  END IF;

  v_internal := session_user IN ('postgres', 'supabase_admin')
             OR coalesce(auth.role(), '') = 'service_role';
  v_platform := coalesce(fn_is_platform_admin(), false);
  v_role     := coalesce(fn_club_bank_role(p_club_id), '');

  v_staff := v_internal OR v_platform
             OR v_role IN ('owner', 'co_owner', 'admin', 'super_agent', 'agent');

  IF NOT v_staff THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  v_finance := v_internal OR v_platform
               OR v_role IN ('owner', 'co_owner', 'admin', 'super_agent');
  v_control := v_internal OR v_platform
               OR v_role IN ('owner', 'co_owner', 'admin');

  SELECT count(*) FILTER (
           WHERE coalesce(cm.status, 'active') NOT IN ('banned', 'suspended', 'pending')),
         count(*) FILTER (WHERE cm.status = 'pending'),
         count(*) FILTER (
           WHERE cm.created_at > now() - interval '7 days'
             AND coalesce(cm.status, 'active') NOT IN ('banned', 'suspended')),
         coalesce(sum(cm.chip_balance) FILTER (
           WHERE coalesce(cm.status, 'active') NOT IN ('banned', 'suspended')), 0)
    INTO v_members, v_pending, v_new7, v_member_chips
    FROM club_members cm
   WHERE cm.club_id = p_club_id;

  SELECT count(*) FILTER (WHERE t.status IN ('running', 'waiting', 'active')),
         count(*) FILTER (WHERE t.status = 'running'),
         count(*) FILTER (WHERE t.status = 'waiting')
    INTO v_live_tables, v_running_tables, v_waiting_tables
    FROM tables t
   WHERE t.club_id = p_club_id;

  SELECT count(DISTINCT ts.user_id)
    INTO v_seated
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
   WHERE t.club_id = p_club_id
     AND ts.left_at IS NULL
     AND ts.user_id IS NOT NULL
     AND t.status IN ('running', 'waiting', 'active');

  SELECT count(*)
    INTO v_online
    FROM (
      SELECT ts.user_id
        FROM table_seats ts
        JOIN tables t ON t.id = ts.table_id
       WHERE t.club_id = p_club_id AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
      UNION
      SELECT cm.user_id
        FROM club_members cm
       WHERE cm.club_id = p_club_id AND cm.last_active > now() - interval '15 minutes'
    ) x;

  SELECT count(*) FILTER (WHERE tr.status = 'REGISTERING'),
         count(*) FILTER (WHERE tr.status IN ('RUNNING', 'COMPLETING'))
    INTO v_reg_tourneys, v_run_tourneys
    FROM tournaments tr
   WHERE tr.club_id = p_club_id
     AND tr.status IN ('REGISTERING', 'RUNNING', 'COMPLETING');

  SELECT coalesce(d.hands, 0), coalesce(d.rake, 0)
    INTO v_hands_today, v_rake_today
    FROM club_hand_daily d
   WHERE d.club_id = p_club_id
     AND d.stat_date = (now() AT TIME ZONE 'UTC')::date;

  IF NOT FOUND THEN
    v_hands_today := 0;
    v_rake_today := 0;
  END IF;

  SELECT count(*)
    INTO v_reports
    FROM user_reports r
   WHERE coalesce(r.status, 'pending') = 'pending'
     AND EXISTS (SELECT 1 FROM club_members m
                  WHERE m.club_id = p_club_id AND m.user_id = r.reported_user_id);

  SELECT count(*), count(*) FILTER (WHERE d.created_at < now() - interval '72 hours')
    INTO v_disputes, v_disputes_aged
    FROM disputes d
   WHERE d.club_id = p_club_id
     AND coalesce(d.status, 'open') IN ('open', 'under_review', 'escalated');

  SELECT count(*) FILTER (WHERE b.expires_at IS NULL OR b.expires_at > now()),
         count(*) FILTER (WHERE b.expires_at IS NOT NULL AND b.expires_at <= now())
    INTO v_blacklist, v_blacklist_expired
    FROM blacklists b
   WHERE b.club_id = p_club_id;

  SELECT count(*)
    INTO v_chip_requests
    FROM chip_requests q
   WHERE q.club_id = p_club_id AND coalesce(q.status, 'pending') = 'pending';

  SELECT count(*)
    INTO v_cashouts
    FROM cashout_requests q
   WHERE q.club_id = p_club_id
     AND q.completed_at IS NULL
     AND q.cancelled_at IS NULL
     AND coalesce(q.status, 'pending') NOT IN ('completed', 'cancelled', 'rejected', 'failed');

  SELECT count(*)
    INTO v_credit
    FROM credit_requests q
   WHERE q.club_id = p_club_id AND coalesce(q.status, 'pending') = 'pending';

  SELECT count(*), count(*) FILTER (WHERE i.due_at IS NOT NULL AND i.due_at < now())
    INTO v_invoices, v_invoices_overdue
    FROM settlement_invoices i
   WHERE i.club_id = p_club_id
     AND coalesce(i.status, 'generated') NOT IN ('paid', 'settled', 'cancelled', 'void');

  SELECT count(*)
    INTO v_tickets
    FROM tournament_tickets tk
   WHERE tk.club_id = p_club_id
     AND tk.redeemed_at IS NULL
     AND tk.cancelled_at IS NULL
     AND coalesce(tk.status, 'issued') NOT IN ('redeemed', 'cancelled', 'expired');

  SELECT count(*)
    INTO v_flags
    FROM anti_cheat_flags f
   WHERE f.club_id = p_club_id AND coalesce(f.status, 'open') = 'open';

  IF v_finance AND v_invoices_overdue > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'invoices-overdue', 'severity', 'critical', 'tool', 'settlement',
      'title', 'Invoices Past Due', 'count', v_invoices_overdue));
  END IF;

  IF v_disputes_aged > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'disputes-aged', 'severity', 'critical', 'tool', 'disputes',
      'title', 'Disputes Past Seventy Two Hours', 'count', v_disputes_aged));
  ELSIF v_disputes > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'disputes-open', 'severity', 'warning', 'tool', 'disputes',
      'title', 'Disputes Open', 'count', v_disputes));
  END IF;

  IF v_chip_requests > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'chip-requests', 'severity', 'warning', 'tool', 'cashier',
      'title', 'Chip Requests Waiting', 'count', v_chip_requests));
  END IF;

  IF v_cashouts > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'cashouts', 'severity', 'warning', 'tool', 'cashier',
      'title', 'Cash Out Requests Waiting', 'count', v_cashouts));
  END IF;

  IF v_credit > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'credit-requests', 'severity', 'warning', 'tool', 'cashier',
      'title', 'Credit Requests Waiting', 'count', v_credit));
  END IF;

  IF v_pending > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'join-requests', 'severity', 'warning', 'tool', 'players',
      'title', 'Membership Requests Waiting', 'count', v_pending));
  END IF;

  IF v_reports > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'reports-open', 'severity', 'warning', 'tool', 'reports',
      'title', 'Player Reports To Review', 'count', v_reports));
  END IF;

  IF v_flags > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'anti-cheat-flags', 'severity', 'warning', 'tool', 'anti-cheat',
      'title', 'Integrity Flags Open', 'count', v_flags));
  END IF;

  IF v_finance AND v_treasury <= 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'club-bank-empty', 'severity', 'warning', 'tool', 'cashier',
      'title', 'The Club Bank Is Empty', 'count', 0));
  END IF;

  IF v_locked THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'settlement-locked', 'severity', 'info', 'tool', 'settlement',
      'title', 'Settlement Is Locked', 'count', 0));
  END IF;

  IF v_blacklist_expired > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'blacklist-expired', 'severity', 'info', 'tool', 'blacklist',
      'title', 'Expired Exclusions To Clear', 'count', v_blacklist_expired));
  END IF;

  v_kpis := jsonb_build_object(
    'members', v_members,
    'members_pending', v_pending,
    'members_new_7d', v_new7,
    'online_now', v_online,
    'seated_now', v_seated,
    'live_tables', v_live_tables,
    'running_tables', v_running_tables,
    'waiting_tables', v_waiting_tables,
    'tournaments_registering', v_reg_tourneys,
    'tournaments_running', v_run_tourneys,
    'hands_today', v_hands_today);

  IF v_finance THEN
    v_kpis := v_kpis || jsonb_build_object(
      'rake_today', v_rake_today,
      'club_bank', v_treasury,
      'member_chips', v_member_chips);
  END IF;

  RETURN jsonb_build_object(
    'generated_at', now(),
    'club', jsonb_build_object('id', p_club_id, 'name', v_name, 'slug', v_slug),
    'viewer', jsonb_build_object(
      'role', nullif(v_role, ''),
      'is_platform_staff', v_platform,
      'can_view_finance', v_finance,
      'can_control_club', v_control),
    'kpis', v_kpis,
    'counts', jsonb_build_object(
      'members', v_members,
      'members_pending', v_pending,
      'reports_open', v_reports,
      'disputes_open', v_disputes,
      'disputes_aged', v_disputes_aged,
      'blacklist_active', v_blacklist,
      'blacklist_expired', v_blacklist_expired,
      'chip_requests_pending', v_chip_requests,
      'cashouts_pending', v_cashouts,
      'credit_requests_pending', v_credit,
      'invoices_open', CASE WHEN v_finance THEN v_invoices ELSE NULL END,
      'invoices_overdue', CASE WHEN v_finance THEN v_invoices_overdue ELSE NULL END,
      'tickets_outstanding', v_tickets,
      'anti_cheat_flags_open', v_flags),
    'alerts', v_alerts,
    'settlement_locked', v_locked);
END;
$$;


ALTER FUNCTION public.ca_club_operations_overview(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_operations_overview(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_operations_overview(p_club_id uuid) IS 'One staff-gated read behind the club operations workspace: live floor, roster, and every queue that is waiting for a person, with the alert severity and the registry tool id each queue belongs to. Finance figures are returned only to the finance roles. Horses are counted like every other player.';


--
-- Name: ca_club_overlay_pnl(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_overlay_pnl(p_club_id uuid, p_days integer DEFAULT 14) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
  v_from date := (now() AT TIME ZONE 'UTC')::date - (greatest(least(coalesce(p_days,14), 90), 1) - 1);
BEGIN
  IF NOT ca_can_view_club(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'club_id', p_club_id,
    'range_days', greatest(least(coalesce(p_days,14), 90), 1),
    'totals', (
      SELECT jsonb_build_object(
        'events', coalesce(count(*), 0),
        'funded', round(coalesce(sum(o.amount), 0), 2),
        'bank', coalesce(max(o.bank_type),
                         (SELECT CASE WHEN c.union_id IS NULL THEN 'club' ELSE 'union' END
                            FROM clubs c WHERE c.id = p_club_id)))
      FROM tournament_guarantee_overlays o
      WHERE o.club_id = p_club_id AND o.funded_at >= v_from::timestamptz
    ),
    'events', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'tournament_id', o.tournament_id,
               'name', coalesce(t.name, 'Unknown'),
               'overlay', o.amount,
               'pool_before', o.pool_before,
               'pool_after', o.pool_after,
               'bank', o.bank_type,
               'at', o.funded_at)
             ORDER BY o.funded_at DESC)
      FROM tournament_guarantee_overlays o
      LEFT JOIN tournaments t ON t.id = o.tournament_id
      WHERE o.club_id = p_club_id AND o.funded_at >= v_from::timestamptz
    ), '[]'::jsonb),
    'generated_at', now()
  ) INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION public.ca_club_overlay_pnl(p_club_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: ca_club_player_breakdown(uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_player_breakdown(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date:=(now() AT TIME ZONE 'UTC')::date;
  v_end date:=LEAST(COALESCE(p_end,v_today),v_today);
  v_start date:=COALESCE(p_start,v_end-13);
  v_lim int:=GREATEST(LEAST(COALESCE(p_limit,100),500),1);
  v_union uuid; v_out jsonb;
BEGIN
  IF NOT public.ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE='42501'; END IF;
  IF v_start<v_end-92 THEN v_start:=v_end-92; END IF;
  IF v_start>v_end THEN v_start:=v_end; END IF;
  SELECT uc.union_id INTO v_union FROM public.union_clubs uc WHERE uc.club_id=p_club_id LIMIT 1;
  WITH att_club AS MATERIALIZED (
    SELECT a.user_id FROM (SELECT DISTINCT ON(cm.user_id) cm.user_id,cm.club_id
      FROM public.club_members cm JOIN public.union_clubs uc
       ON uc.club_id=cm.club_id AND uc.union_id=v_union WHERE v_union IS NOT NULL
      ORDER BY cm.user_id,cm.joined_at ASC NULLS LAST,cm.club_id) a WHERE a.club_id=p_club_id
    UNION SELECT cm.user_id FROM public.club_members cm
      WHERE v_union IS NULL AND cm.club_id=p_club_id
  ), wallet_pnl AS (
    SELECT d.user_id,SUM(d.cash_net) cash_net,SUM(d.tournament_net) tournament_net
      FROM public.ca_club_player_daily d WHERE d.club_id=p_club_id
       AND d.stat_date BETWEEN v_start AND v_end GROUP BY d.user_id
  ), rake AS (
    SELECT u.user_id,SUM(u.rake_amount) rake FROM public.union_rake_paid_daily_user u
      JOIN att_club a ON a.user_id=u.user_id WHERE v_union IS NOT NULL AND u.union_id=v_union
       AND u.day BETWEEN v_start AND v_end GROUP BY u.user_id
    UNION ALL
    SELECT c.user_id,SUM(c.rake_amount) FROM public.club_rake_daily_user c
      JOIN att_club a ON a.user_id=c.user_id WHERE v_union IS NULL AND c.club_id=p_club_id
       AND c.day BETWEEN v_start AND v_end GROUP BY c.user_id
  ), hands AS (
    SELECT s.user_id,SUM(s.hands_played)::bigint hands FROM public.club_member_daily_stats s
      JOIN att_club a ON a.user_id=s.user_id WHERE s.club_id=p_club_id
       AND s.stat_date BETWEEN v_start AND v_end GROUP BY s.user_id
  ), merged AS MATERIALIZED (
    SELECT a.user_id,round(COALESCE(w.cash_net,0),2) cash_net,
      round(COALESCE(w.tournament_net,0),2) tournament_net,
      round(COALESCE(w.cash_net,0)+COALESCE(w.tournament_net,0),2) net,
      round(COALESCE(r.rake,0),2) rake,COALESCE(h.hands,0) hands
      FROM att_club a LEFT JOIN wallet_pnl w ON w.user_id=a.user_id
      LEFT JOIN rake r ON r.user_id=a.user_id LEFT JOIN hands h ON h.user_id=a.user_id
      WHERE COALESCE(w.cash_net,0)<>0 OR COALESCE(w.tournament_net,0)<>0
         OR COALESCE(r.rake,0)<>0 OR COALESCE(h.hands,0)<>0
  )
  SELECT jsonb_build_object('range',jsonb_build_object('start',v_start,'end',v_end,'days',(v_end-v_start)+1),
    'rake_complete_through',LEAST(v_end,v_today-1),
    'totals',(SELECT jsonb_build_object('players',count(*),'net',round(COALESCE(SUM(net),0),2),
      'rake',round(COALESCE(SUM(rake),0),2),'hands',COALESCE(SUM(hands),0)) FROM merged),
    'players',COALESCE((SELECT jsonb_agg(jsonb_build_object('user_id',q.user_id,
      'username',COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name),pr.username,'Player'),'avatar_url',pr.avatar_url,
      'is_horse',(public.fn_can_see_horse_flag(p_club_id) AND COALESCE(pr.is_horse,false)),'net',q.net,'cash_net',q.cash_net,
      'tournament_net',q.tournament_net,'rake',q.rake,'hands',q.hands) ORDER BY q.net DESC)
      FROM (SELECT * FROM merged ORDER BY net DESC LIMIT v_lim) q
      LEFT JOIN public.profiles pr ON pr.id=q.user_id),'[]'::jsonb),
    'player_count',(SELECT count(*) FROM merged),'generated_at',now()) INTO v_out;
  RETURN v_out;
END;
$$;


ALTER FUNCTION public.ca_club_player_breakdown(p_club_id uuid, p_start date, p_end date, p_limit integer) OWNER TO postgres;

--
-- Name: ca_club_player_export_start(uuid, date, date, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_player_export_start(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_sort text DEFAULT 'winners'::text, p_request_id uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_end date := LEAST(COALESCE(p_end,v_today),v_today);
  v_start date := COALESCE(p_start,v_end-13);
  v_sort text := LOWER(COALESCE(NULLIF(p_sort,''),'winners'));
  v_request uuid := COALESCE(p_request_id,gen_random_uuid());
  v_union uuid;
  v_export_id uuid;
  v_total integer;
BEGIN
  IF v_user IS NULL OR NOT public.ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE='42501';
  END IF;
  IF v_start < v_end-92 THEN v_start := v_end-92; END IF;
  IF v_start > v_end THEN v_start := v_end; END IF;
  IF v_sort NOT IN ('winners','losers','rake','hands') THEN v_sort := 'winners'; END IF;
  SELECT uc.union_id INTO v_union FROM public.union_clubs uc
   WHERE uc.club_id=p_club_id LIMIT 1;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_user::text||':'||v_request::text,0));
  DELETE FROM public.ca_club_data_exports WHERE expires_at < now();
  SELECT id,total_rows INTO v_export_id,v_total
    FROM public.ca_club_data_exports
   WHERE user_id=v_user AND request_id=v_request AND status='ready';
  IF v_export_id IS NOT NULL THEN
    RETURN jsonb_build_object('export_id',v_export_id,'total_rows',v_total,'status','ready');
  END IF;
  DELETE FROM public.ca_club_data_exports
   WHERE user_id=v_user AND request_id=v_request;
  INSERT INTO public.ca_club_data_exports(user_id,club_id,request_id,kind)
  VALUES(v_user,p_club_id,v_request,'players') RETURNING id INTO v_export_id;

  WITH att_club AS MATERIALIZED (
    SELECT a.user_id FROM (
      SELECT DISTINCT ON(cm.user_id) cm.user_id,cm.club_id
        FROM public.club_members cm JOIN public.union_clubs uc
          ON uc.club_id=cm.club_id AND uc.union_id=v_union
       WHERE v_union IS NOT NULL
       ORDER BY cm.user_id,cm.joined_at ASC NULLS LAST,cm.club_id) a
     WHERE a.club_id=p_club_id
    UNION
    SELECT cm.user_id FROM public.club_members cm
     WHERE v_union IS NULL AND cm.club_id=p_club_id
  ), wallet_pnl AS (
    SELECT d.user_id,SUM(d.cash_net) cash_net,SUM(d.tournament_net) tournament_net
      FROM public.ca_club_player_daily d
     WHERE d.club_id=p_club_id AND d.stat_date BETWEEN v_start AND v_end
     GROUP BY d.user_id
  ), rake AS (
    SELECT u.user_id,SUM(u.rake_amount) rake
      FROM public.union_rake_paid_daily_user u JOIN att_club a ON a.user_id=u.user_id
     WHERE u.union_id=v_union AND u.day BETWEEN v_start AND v_end GROUP BY u.user_id
  ), hands AS (
    SELECT s.user_id,SUM(s.hands_played)::bigint hands
      FROM public.club_member_daily_stats s JOIN att_club a ON a.user_id=s.user_id
     WHERE s.club_id=p_club_id AND s.stat_date BETWEEN v_start AND v_end
     GROUP BY s.user_id
  ), merged AS MATERIALIZED (
    SELECT a.user_id,COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name),pr.username,'Player') username,
           pr.avatar_url,(public.fn_can_see_horse_flag(p_club_id) AND COALESCE(pr.is_horse,false)) is_horse,
           round(COALESCE(w.cash_net,0),2) cash_net,
           round(COALESCE(w.tournament_net,0),2) tournament_net,
           round(COALESCE(w.cash_net,0)+COALESCE(w.tournament_net,0),2) net,
           round(COALESCE(r.rake,0),2) rake,COALESCE(h.hands,0) hands
      FROM att_club a LEFT JOIN wallet_pnl w ON w.user_id=a.user_id
      LEFT JOIN rake r ON r.user_id=a.user_id LEFT JOIN hands h ON h.user_id=a.user_id
      LEFT JOIN public.profiles pr ON pr.id=a.user_id
     WHERE COALESCE(w.cash_net,0)<>0 OR COALESCE(w.tournament_net,0)<>0
        OR COALESCE(r.rake,0)<>0 OR COALESCE(h.hands,0)<>0
  ), scored AS (
    SELECT m.*,CASE v_sort WHEN 'losers' THEN -m.net WHEN 'rake' THEN m.rake
                           WHEN 'hands' THEN m.hands::numeric ELSE m.net END sort_value
      FROM merged m
  ), ordered AS (
    SELECT row_number() OVER (ORDER BY sort_value DESC,user_id::text DESC)::integer ordinal,
           jsonb_build_object(
             'user_id',user_id,'username',username,'avatar_url',avatar_url,
             'is_horse',is_horse,'net',net,'cash_net',cash_net,
             'tournament_net',tournament_net,'rake',rake,'hands',hands
           ) payload
      FROM scored
  )
  INSERT INTO public.ca_club_data_export_rows(export_id,ordinal,payload)
  SELECT v_export_id,ordinal,payload FROM ordered;

  GET DIAGNOSTICS v_total = ROW_COUNT;
  UPDATE public.ca_club_data_exports
     SET total_rows=v_total,status='ready'
   WHERE id=v_export_id;
  RETURN jsonb_build_object('export_id',v_export_id,'total_rows',v_total,'status','ready');
END;
$$;


ALTER FUNCTION public.ca_club_player_export_start(p_club_id uuid, p_start date, p_end date, p_sort text, p_request_id uuid) OWNER TO postgres;

--
-- Name: ca_club_player_page(uuid, date, date, text, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_player_page(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_sort text DEFAULT 'winners'::text, p_search text DEFAULT NULL::text, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_end date := LEAST(COALESCE(p_end,v_today),v_today);
  v_start date := COALESCE(p_start,v_end-13);
  v_sort text := LOWER(COALESCE(NULLIF(p_sort,''),'winners'));
  v_search text := NULLIF(btrim(COALESCE(p_search,'')),'');
  v_limit integer := GREATEST(LEAST(COALESCE(p_limit,100),200),1);
  v_union uuid;
  v_out jsonb;
BEGIN
  IF NOT public.ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE='42501';
  END IF;
  IF v_start < v_end-92 THEN v_start := v_end-92; END IF;
  IF v_start > v_end THEN v_start := v_end; END IF;
  IF v_sort NOT IN ('winners','losers','rake','hands') THEN v_sort := 'winners'; END IF;
  SELECT uc.union_id INTO v_union FROM public.union_clubs uc
   WHERE uc.club_id=p_club_id LIMIT 1;

  WITH att_club AS MATERIALIZED (
    SELECT a.user_id FROM (
      SELECT DISTINCT ON(cm.user_id) cm.user_id,cm.club_id
        FROM public.club_members cm JOIN public.union_clubs uc
          ON uc.club_id=cm.club_id AND uc.union_id=v_union
       WHERE v_union IS NOT NULL
       ORDER BY cm.user_id,cm.joined_at ASC NULLS LAST,cm.club_id) a
     WHERE a.club_id=p_club_id
    UNION
    SELECT cm.user_id FROM public.club_members cm
     WHERE v_union IS NULL AND cm.club_id=p_club_id
  ), wallet_pnl AS (
    SELECT d.user_id,SUM(d.cash_net) cash_net,SUM(d.tournament_net) tournament_net
      FROM public.ca_club_player_daily d
     WHERE d.club_id=p_club_id AND d.stat_date BETWEEN v_start AND v_end
     GROUP BY d.user_id
  ), rake AS (
    SELECT u.user_id,SUM(u.rake_amount) rake
      FROM public.union_rake_paid_daily_user u JOIN att_club a ON a.user_id=u.user_id
     WHERE v_union IS NOT NULL AND u.union_id=v_union AND u.day BETWEEN v_start AND v_end GROUP BY u.user_id
    UNION ALL
    SELECT c.user_id,SUM(c.rake_amount)
      FROM public.club_rake_daily_user c JOIN att_club a ON a.user_id=c.user_id
     WHERE v_union IS NULL AND c.club_id=p_club_id AND c.day BETWEEN v_start AND v_end GROUP BY c.user_id
  ), hands AS (
    SELECT s.user_id,SUM(s.hands_played)::bigint hands
      FROM public.club_member_daily_stats s JOIN att_club a ON a.user_id=s.user_id
     WHERE s.club_id=p_club_id AND s.stat_date BETWEEN v_start AND v_end
     GROUP BY s.user_id
  ), merged AS MATERIALIZED (
    SELECT a.user_id,COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name),pr.username,'Player') username,
           pr.avatar_url,(public.fn_can_see_horse_flag(p_club_id) AND COALESCE(pr.is_horse,false)) is_horse,
           round(COALESCE(w.cash_net,0),2) cash_net,
           round(COALESCE(w.tournament_net,0),2) tournament_net,
           round(COALESCE(w.cash_net,0)+COALESCE(w.tournament_net,0),2) net,
           round(COALESCE(r.rake,0),2) rake,COALESCE(h.hands,0) hands
      FROM att_club a LEFT JOIN wallet_pnl w ON w.user_id=a.user_id
      LEFT JOIN rake r ON r.user_id=a.user_id LEFT JOIN hands h ON h.user_id=a.user_id
      LEFT JOIN public.profiles pr ON pr.id=a.user_id
     WHERE COALESCE(w.cash_net,0)<>0 OR COALESCE(w.tournament_net,0)<>0
        OR COALESCE(r.rake,0)<>0 OR COALESCE(h.hands,0)<>0
  ), filtered AS MATERIALIZED (
    SELECT m.* FROM merged m
     WHERE v_search IS NULL OR m.username ILIKE '%'||v_search||'%'
        OR m.user_id::text ILIKE '%'||v_search||'%'
  ), scored AS MATERIALIZED (
    SELECT f.*,CASE v_sort WHEN 'losers' THEN -f.net
                           WHEN 'rake' THEN f.rake
                           WHEN 'hands' THEN f.hands::numeric
                           ELSE f.net END sort_value
      FROM filtered f
  ), page_plus_one AS MATERIALIZED (
    SELECT s.* FROM scored s
     WHERE p_cursor IS NULL OR ROW(s.sort_value,s.user_id::text) <
       ROW((p_cursor->>'value')::numeric,p_cursor->>'id')
     ORDER BY s.sort_value DESC,s.user_id::text DESC LIMIT v_limit+1
  ), visible AS MATERIALIZED (
    SELECT * FROM page_plus_one
     ORDER BY sort_value DESC,user_id::text DESC LIMIT v_limit
  ), last_row AS (
    SELECT * FROM visible ORDER BY sort_value ASC,user_id::text ASC LIMIT 1
  )
  SELECT jsonb_build_object(
    'sort',v_sort,
    'rows',COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'user_id',q.user_id,'username',q.username,'avatar_url',q.avatar_url,
      'is_horse',q.is_horse,'net',q.net,'cash_net',q.cash_net,
      'tournament_net',q.tournament_net,'rake',q.rake,'hands',q.hands)
      ORDER BY q.sort_value DESC,q.user_id::text DESC) FROM visible q),'[]'::jsonb),
    'next_cursor',CASE WHEN (SELECT count(*) FROM page_plus_one)>v_limit THEN
      (SELECT jsonb_build_object('value',l.sort_value,'id',l.user_id) FROM last_row l)
      ELSE NULL END,
    'has_more',(SELECT count(*) FROM page_plus_one)>v_limit,
    'filtered_count',(SELECT count(*) FROM filtered),
    'generated_at',now()) INTO v_out;

  RETURN v_out;
END;
$$;


ALTER FUNCTION public.ca_club_player_page(p_club_id uuid, p_start date, p_end date, p_sort text, p_search text, p_cursor jsonb, p_limit integer) OWNER TO postgres;

--
-- Name: ca_club_revenue(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_revenue(p_club_id uuid, p_days integer DEFAULT 14) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
  v_from date := (now() AT TIME ZONE 'UTC')::date - (greatest(least(coalesce(p_days,14), 90), 1) - 1);
  v_union uuid;
BEGIN
  IF NOT ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  SELECT union_id INTO v_union FROM clubs WHERE id = p_club_id;

  SELECT jsonb_build_object(
    'range_days', greatest(least(coalesce(p_days,14), 90), 1),
    'totals', (
      SELECT jsonb_build_object(
        'hands', coalesce(sum(d.hands), 0),
        'hands_dealt', coalesce((SELECT sum(h.hands) FROM club_hand_daily h
                                  WHERE h.club_id = p_club_id AND h.stat_date >= v_from), 0),
        'rake',  round(coalesce(sum(d.rake), 0), 2),
        'bbj',   round(coalesce(sum(d.bbj), 0), 2),
        'pot_total', round(coalesce(sum(d.pot), 0), 2),
        'tournament_fees', round(coalesce((SELECT sum(t.fee) FROM ca_club_tournament_daily t
                                            WHERE t.club_id = p_club_id AND t.stat_date >= v_from), 0), 2),
        'avg_pot', CASE WHEN coalesce(sum(d.hands),0) > 0
                        THEN round(sum(d.pot) / sum(d.hands), 4) ELSE 0 END,
        'rake_per_hand', CASE WHEN coalesce(sum(d.hands),0) > 0
                        THEN round(sum(d.rake) / sum(d.hands), 4) ELSE 0 END
      )
      FROM ca_club_rake_daily d
      WHERE d.club_id = p_club_id AND d.stat_date >= v_from
    ),
    'insurance', (
      SELECT jsonb_build_object(
        'contracts', coalesce(count(*), 0),
        'premiums',  round(coalesce(sum(it.premium), 0), 2),
        'payouts',   round(coalesce(sum(it.payout), 0), 2),
        'net',       round(coalesce(sum(it.premium - it.payout), 0), 2),
        'bank',      CASE WHEN v_union IS NULL THEN 'club' ELSE 'union' END)
      FROM insurance_transactions it
      WHERE it.club_id = p_club_id
        AND it.created_at >= (v_from::timestamp AT TIME ZONE 'UTC')
    ),
    'daily', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'd', g.day::date,
               'hands', coalesce(d.hands, 0),
               'hands_dealt', coalesce(h.hands, 0),
               'rake', round(coalesce(d.rake, 0), 2),
               'bbj', round(coalesce(d.bbj, 0), 2),
               'pot_total', round(coalesce(d.pot, 0), 2),
               'tournament_fees', round(coalesce(m.fee, 0), 2),
               'ins_net', coalesce(i.net, 0))
             ORDER BY g.day)
      FROM generate_series(v_from, (now() AT TIME ZONE 'UTC')::date, interval '1 day') g(day)
      LEFT JOIN ca_club_rake_daily d ON d.club_id = p_club_id AND d.stat_date = g.day::date
      LEFT JOIN club_hand_daily h ON h.club_id = p_club_id AND h.stat_date = g.day::date
      LEFT JOIN (
        SELECT t.stat_date, sum(t.fee) AS fee FROM ca_club_tournament_daily t
         WHERE t.club_id = p_club_id AND t.stat_date >= v_from GROUP BY t.stat_date
      ) m ON m.stat_date = g.day::date
      LEFT JOIN (
        SELECT (it.created_at AT TIME ZONE 'UTC')::date AS d,
               round(sum(it.premium - it.payout), 2) AS net
          FROM insurance_transactions it
         WHERE it.club_id = p_club_id AND it.created_at >= (v_from::timestamp AT TIME ZONE 'UTC')
         GROUP BY 1
      ) i ON i.d = g.day::date
    ), '[]'::jsonb),
    -- RAKED HANDS AT THE TABLE, not player-hands. See the header: this summed
    -- club_member_daily_stats.hands_played, one row per player per hand, and
    -- the client printed it as "Hands" - 2,113,324 against 596,730 dealt.
    'by_table', coalesce((
      SELECT jsonb_agg(x ORDER BY (x->>'hands')::bigint DESC, (x->>'players')::int DESC)
      FROM (
        SELECT jsonb_build_object(
                 'table_id', q.table_id,
                 'name', coalesce(t.name, 'Unnamed'),
                 'status', coalesce(t.status, 'unknown'),
                 'stakes', coalesce(t.stakes,
                            concat(t.small_blind::text, '/', t.big_blind::text)),
                 'hands', q.hands,
                 'rake', round(q.rake, 2),
                 'players', q.players
               ) AS x
        FROM (
          SELECT coalesce(c.table_id, s.table_id) AS table_id,
                 coalesce(c.hands, 0)::bigint AS hands,
                 coalesce(c.rake, 0)::numeric AS rake,
                 coalesce(s.players, 0)::integer AS players
            FROM (
              SELECT c.table_id, sum(c.hands)::bigint AS hands, sum(c.rake) AS rake
                FROM club_table_daily c
               WHERE c.club_id = p_club_id AND c.stat_date >= v_from
               GROUP BY c.table_id
            ) c
            FULL OUTER JOIN (
              SELECT s.table_id, count(DISTINCT s.user_id)::integer AS players
                FROM club_member_daily_stats s
               WHERE s.club_id = p_club_id AND s.stat_date >= v_from
               GROUP BY s.table_id
            ) s ON s.table_id = c.table_id
        ) q
        LEFT JOIN tables t ON t.id = q.table_id
        WHERE q.table_id IS NOT NULL
        ORDER BY q.hands DESC, q.players DESC
        LIMIT 20
      ) z
    ), '[]'::jsonb),
    'rake_source', 'rake_records',
    'data_updated_at', (SELECT max(d.updated_at) FROM ca_club_rake_daily d
                         WHERE d.club_id = p_club_id AND d.stat_date >= v_from)
  ) INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION public.ca_club_revenue(p_club_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_revenue(p_club_id uuid, p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_revenue(p_club_id uuid, p_days integer) IS 'Club dashboard Revenue tab over the last p_days (1..90) days. Finance-gated by ca_can_view_club_finances since 2026-09-04; before that any member could read it.';


--
-- Name: ca_club_roster_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_roster_access(p_club_id uuid, p_target_user_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_service boolean := COALESCE(auth.role(), 'service_role') = 'service_role';
BEGIN
  IF p_club_id IS NULL OR p_target_user_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.club_members target
     WHERE target.user_id = p_target_user_id AND target.club_id = p_club_id
       AND COALESCE(target.status, 'approved') IN ('active', 'approved')
  ) THEN RETURN 'none'; END IF;
  IF v_service THEN RETURN 'service'; END IF;
  IF v_actor IS NULL THEN RETURN 'none'; END IF;
  IF EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = v_actor AND COALESCE(p.is_admin, false))
     OR COALESCE(public.fn_is_union_overseer(p_club_id, v_actor), false)
  THEN RETURN 'staff'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.club_members actor
     WHERE actor.user_id = v_actor AND actor.club_id = p_club_id
       AND actor.role IN ('owner','co_owner','admin')
       AND COALESCE(actor.status, 'approved') IN ('active','approved')
  ) THEN RETURN 'staff'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.club_members actor
     WHERE actor.user_id = v_actor AND actor.club_id = p_club_id
       AND actor.role IN ('super_agent','agent','sub_agent')
       AND COALESCE(actor.status, 'approved') IN ('active','approved')
  ) THEN
    IF p_target_user_id = v_actor THEN RETURN 'downline'; END IF;
    IF EXISTS (
      WITH RECURSIVE edges AS (
        SELECT cm.agent_id parent, cm.user_id child
          FROM public.club_members cm
         WHERE cm.club_id = p_club_id AND cm.agent_id IS NOT NULL
           AND cm.agent_id <> cm.user_id
           AND COALESCE(cm.status, 'approved') IN ('active','approved')
      ), tree AS (
        SELECT e.child, 1 depth FROM edges e WHERE e.parent = v_actor
        UNION ALL
        SELECT e.child, t.depth + 1 FROM tree t JOIN edges e ON e.parent = t.child
         WHERE t.depth < 20
      ) SELECT 1 FROM tree WHERE child = p_target_user_id
    ) THEN RETURN 'downline'; END IF;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.club_members actor
     WHERE actor.user_id = v_actor AND actor.club_id = p_club_id
       AND COALESCE(actor.status, 'approved') IN ('active','approved')
  ) THEN RETURN 'identity'; END IF;
  RETURN 'none';
END;
$$;


ALTER FUNCTION public.ca_club_roster_access(p_club_id uuid, p_target_user_id uuid) OWNER TO postgres;

--
-- Name: ca_club_roster_rows(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_roster_rows(p_club_id uuid) RETURNS TABLE(user_id uuid, management_club_id uuid, home_club_id uuid, home_club_name text, player_number text, alias text, username text, display_name text, avatar_url text, role text, role_rank integer, is_online boolean, is_seated boolean, chip_balance numeric, player_wallet numeric, agent_wallet numeric, promo_wallet numeric, total_fees numeric, downline_fees numeric, total_hands bigint, downline_direct integer, downline_total integer, upline_user_id uuid, upline_name text, joined_at timestamp with time zone, last_login timestamp with time zone, nickname text, remark text, can_view_financials boolean, can_view_notes boolean, in_viewer_downline boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_scope uuid[];
  v_service boolean := coalesce(auth.role(), 'service_role') = 'service_role';
  v_platform_admin boolean := false;
  v_union_staff boolean := false;
  v_needs_hierarchy boolean := false;
BEGIN
  v_scope := public.fn_club_scope_ids(p_club_id);
  IF v_scope IS NULL OR array_length(v_scope, 1) IS NULL THEN
    RETURN;
  END IF;

  IF NOT v_service AND v_actor IS NOT NULL THEN
    SELECT coalesce(p.is_admin, false)
      INTO v_platform_admin
      FROM public.profiles p
     WHERE p.id = v_actor;
    v_union_staff := coalesce(public.fn_is_union_overseer(p_club_id, v_actor), false);
  END IF;

  v_needs_hierarchy := v_service OR v_platform_admin OR v_union_staff OR EXISTS (
    SELECT 1 FROM public.club_members viewer
     WHERE viewer.user_id = v_actor
       AND viewer.club_id = p_club_id
       AND viewer.role IN ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent')
       AND coalesce(viewer.status, 'approved') IN ('active', 'approved')
  );

  IF NOT v_service
     AND NOT v_platform_admin
     AND NOT v_union_staff
     AND (
       v_actor IS NULL OR NOT EXISTS (
         SELECT 1
           FROM public.club_members actor
          WHERE actor.user_id = v_actor
            AND actor.club_id = p_club_id
            AND coalesce(actor.status, 'approved') IN ('active', 'approved')
       )
     ) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH RECURSIVE base AS MATERIALIZED (
    SELECT DISTINCT ON (cm.user_id)
           cm.user_id AS m_user_id,
           cm.club_id AS m_club_id,
           cm.role AS m_role,
           cm.agent_id AS m_agent_id,
           cm.chip_balance AS m_chip_balance,
           cm.promo_balance AS m_promo_balance,
           cm.joined_at AS m_joined_at,
           cm.last_active_at AS m_last_active_at,
           cm.nickname AS m_nickname,
           cm.notes AS m_notes,
           cm.display_name AS m_display_name,
           public.fn_club_role_rank(cm.role) AS m_rank
      FROM public.club_members cm
     WHERE cm.club_id = p_club_id
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
     ORDER BY cm.user_id,
              public.fn_club_role_rank(cm.role) DESC,
              cm.joined_at ASC,
              cm.club_id
  ),
  edges AS MATERIALIZED (
    SELECT DISTINCT cm.agent_id AS parent, cm.user_id AS child
      FROM public.club_members cm
     WHERE cm.club_id = p_club_id
       AND cm.agent_id IS NOT NULL
       AND cm.agent_id <> cm.user_id
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
  ),
  closure AS MATERIALIZED (
    SELECT e.parent AS root, e.child AS descendant, 1 AS depth FROM edges e WHERE v_needs_hierarchy
    UNION ALL
    SELECT c.root, e.child, c.depth + 1
      FROM closure c
      JOIN edges e ON e.parent = c.descendant
     WHERE c.depth < 20
  ),
  viewer_tree AS MATERIALIZED (
    SELECT DISTINCT c.descendant AS uid
      FROM closure c
     WHERE c.root = v_actor
  ),
  downlines AS MATERIALIZED (
    SELECT c.root AS uid,
           count(DISTINCT c.descendant) FILTER (WHERE c.depth = 1)::int AS direct_count,
           count(DISTINCT c.descendant)::int AS total_count
      FROM closure c
     GROUP BY c.root
  ),
  staff_clubs AS MATERIALIZED (
    SELECT DISTINCT cm.club_id
      FROM public.club_members cm
     WHERE cm.user_id = v_actor
       AND cm.club_id = p_club_id
       AND cm.role IN ('owner', 'co_owner', 'admin')
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
  ),
  staff_targets AS MATERIALIZED (
    SELECT DISTINCT cm.user_id AS uid
      FROM public.club_members cm
     WHERE cm.club_id IN (SELECT sc.club_id FROM staff_clubs sc)
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
  ),
  viewer_agent AS MATERIALIZED (
    SELECT EXISTS (
      SELECT 1
        FROM public.club_members cm
       WHERE cm.user_id = v_actor
         AND cm.club_id = p_club_id
         AND cm.role IN ('super_agent', 'agent', 'sub_agent')
         AND coalesce(cm.status, 'approved') IN ('active', 'approved')
    ) AS yes
  ),
  access AS MATERIALIZED (
    SELECT b.m_user_id AS uid,
           (
             v_service OR v_platform_admin OR v_union_staff
             OR st.uid IS NOT NULL
             OR vt.uid IS NOT NULL
             OR (b.m_user_id = v_actor AND va.yes)
           ) AS sensitive,
           (vt.uid IS NOT NULL) AS is_downline
      FROM base b
      CROSS JOIN viewer_agent va
      LEFT JOIN staff_targets st ON st.uid = b.m_user_id
      LEFT JOIN viewer_tree vt ON vt.uid = b.m_user_id
  ),
  seated AS MATERIALIZED (
    SELECT DISTINCT live.uid
      FROM (
        SELECT ts.user_id AS uid
          FROM public.table_seats ts
          JOIN public.tables t ON t.id = ts.table_id
         WHERE ts.left_at IS NULL AND ts.user_id IS NOT NULL
           AND ts.club_id = p_club_id
           AND t.status IN ('waiting', 'running')
        UNION
        SELECT ts.user_id AS uid
          FROM public.tables t
          JOIN public.table_seats ts ON ts.table_id = t.id
         WHERE ts.left_at IS NULL AND ts.user_id IS NOT NULL
           AND t.club_id = p_club_id
           AND t.status IN ('waiting', 'running')
      ) live
  ),
  member_wallets AS MATERIALIZED (
    SELECT cm.user_id AS uid,
           sum(coalesce(cm.chip_balance, 0)) AS player_total,
           sum(coalesce(cm.promo_balance, 0)) AS member_promo_total
      FROM public.club_members cm
      JOIN base b ON b.m_user_id = cm.user_id
      JOIN access ac ON ac.uid = cm.user_id AND ac.sensitive
     WHERE cm.club_id = p_club_id
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
     GROUP BY cm.user_id
  ),
  agent_wallets AS MATERIALIZED (
    SELECT a.user_id AS uid,
           sum(coalesce(a.agent_wallet_balance, 0)) AS agent_total,
           sum(coalesce(a.promo_wallet_balance, 0)) AS agent_promo_total
      FROM public.agents a
      JOIN base b ON b.m_user_id = a.user_id
      JOIN access ac ON ac.uid = a.user_id AND ac.sensitive
     WHERE a.club_id = p_club_id
       AND coalesce(a.status, 'active') = 'active'
     GROUP BY a.user_id
  ),
  fees AS MATERIALIZED (
    SELECT r.user_id AS uid,
           sum(COALESCE(r.rake_paid, 0)) AS fee_total,
           count(DISTINCT r.hand_id)::bigint AS hand_total
      FROM public.ca_hand_facts r
      JOIN base b ON b.m_user_id = r.user_id
      JOIN access ac ON ac.uid = r.user_id AND ac.sensitive
     WHERE r.club_id = p_club_id
     GROUP BY r.user_id
  ),
  downline_fee_totals AS MATERIALIZED (
    SELECT c.root AS uid, sum(f.fee_total) AS fee_total
      FROM closure c
      JOIN fees f ON f.uid = c.descendant
     GROUP BY c.root
  )
  SELECT
    b.m_user_id,
    b.m_club_id,
    b.m_club_id,
    cl.name::text,
    pr.player_number::text,
    coalesce(nullif(btrim(pr.alias), ''),
             nullif(btrim(b.m_display_name), ''),
             nullif(btrim(pr.display_name), ''),
             pr.username,
             'Unknown')::text,
    coalesce(pr.username, '')::text,
    coalesce(nullif(btrim(pr.display_name), ''), pr.username, '')::text,
    coalesce(nullif(pr.arena_avatar_url, ''), pr.avatar_url)::text,
    b.m_role::text,
    b.m_rank,
    (s.uid IS NOT NULL)
      OR (coalesce(pr.is_online, false) AND pr.last_seen > now() - interval '5 minutes'),
    (s.uid IS NOT NULL),
    CASE WHEN ac.sensitive THEN coalesce(b.m_chip_balance, 0) END,
    CASE WHEN ac.sensitive THEN coalesce(mw.player_total, 0) END,
    CASE WHEN ac.sensitive THEN coalesce(aw.agent_total, 0) END,
    CASE WHEN ac.sensitive
         THEN coalesce(mw.member_promo_total, 0) + coalesce(aw.agent_promo_total, 0) END,
    CASE WHEN ac.sensitive THEN round(coalesce(f.fee_total, 0), 2) END,
    CASE WHEN ac.sensitive THEN round(coalesce(df.fee_total, 0), 2) END,
    CASE WHEN ac.sensitive THEN coalesce(f.hand_total, 0)::bigint END,
    CASE WHEN ac.sensitive THEN coalesce(d.direct_count, 0) END,
    CASE WHEN ac.sensitive THEN coalesce(d.total_count, 0) END,
    CASE WHEN ac.sensitive THEN b.m_agent_id END,
    CASE WHEN ac.sensitive THEN up.upline_name END,
    b.m_joined_at,
    CASE WHEN ac.sensitive
         THEN coalesce(pr.last_login, pr.last_seen, b.m_last_active_at) END,
    CASE WHEN ac.sensitive THEN b.m_nickname::text END,
    CASE WHEN ac.sensitive THEN b.m_notes::text END,
    ac.sensitive,
    ac.sensitive,
    ac.is_downline
  FROM base b
  JOIN access ac ON ac.uid = b.m_user_id
  LEFT JOIN public.profiles pr ON pr.id = b.m_user_id
  LEFT JOIN public.clubs cl ON cl.id = b.m_club_id
  LEFT JOIN seated s ON s.uid = b.m_user_id
  LEFT JOIN member_wallets mw ON mw.uid = b.m_user_id
  LEFT JOIN agent_wallets aw ON aw.uid = b.m_user_id
  LEFT JOIN fees f ON f.uid = b.m_user_id
  LEFT JOIN downlines d ON d.uid = b.m_user_id
  LEFT JOIN downline_fee_totals df ON df.uid = b.m_user_id
  LEFT JOIN LATERAL (
    SELECT coalesce(nullif(btrim(u.alias), ''),
                    nullif(btrim(u.display_name), ''),
                    u.username)::text AS upline_name
      FROM public.profiles u
     WHERE u.id = b.m_agent_id
  ) up ON true;
END;
$$;


ALTER FUNCTION public.ca_club_roster_rows(p_club_id uuid) OWNER TO postgres;

--
-- Name: ca_club_tables(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_tables(p_club_id uuid, p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
  v_union uuid;
  v_cap integer := least(greatest(coalesce(p_limit, 500), 1), 500);
BEGIN
  IF NOT ca_can_view_club(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  SELECT union_id INTO v_union FROM clubs WHERE id = p_club_id;

  WITH scoped AS (
    SELECT t.id, t.name, t.game_type, t.game_variant, t.stakes,
           t.small_blind, t.big_blind, t.status, t.max_players, t.created_at,
           coalesce(t.is_deleted, false) AS is_deleted,
           t.status IN ('running', 'waiting', 'active') AS is_live
    FROM tables t
    WHERE t.club_id = p_club_id
       OR (v_union IS NOT NULL AND t.union_id = v_union)
  ),
  seats AS (
    SELECT ts.table_id, count(*) AS seated
    FROM table_seats ts
    WHERE ts.left_at IS NULL
      AND ts.table_id IN (SELECT id FROM scoped WHERE is_live)
    GROUP BY ts.table_id
  ),
  live AS (
    SELECT s.*, coalesce(se.seated, 0)::integer AS current_players
    FROM scoped s
    LEFT JOIN seats se ON se.table_id = s.id
    WHERE s.is_live
    ORDER BY coalesce(se.seated, 0) DESC, s.created_at DESC
    LIMIT v_cap
  ),
  recent AS (
    SELECT s.*, 0 AS current_players
    FROM scoped s
    WHERE NOT s.is_live AND NOT s.is_deleted
    ORDER BY s.created_at DESC
    LIMIT 25
  )
  SELECT jsonb_build_object(
    'live', coalesce((SELECT jsonb_agg(to_jsonb(l) - 'is_live') FROM live l), '[]'::jsonb),
    'recent', coalesce((SELECT jsonb_agg(to_jsonb(r) - 'is_live') FROM recent r), '[]'::jsonb),
    'live_count', (SELECT count(*) FROM scoped WHERE is_live),
    'live_truncated', (SELECT count(*) FROM scoped WHERE is_live) > v_cap,
    'total_count', (SELECT count(*) FROM scoped WHERE NOT is_deleted OR is_live),
    'seated_people', (
      SELECT count(DISTINCT ts.user_id)
      FROM table_seats ts
      WHERE ts.left_at IS NULL AND ts.user_id IS NOT NULL
        AND ts.table_id IN (SELECT id FROM scoped WHERE is_live)
    ),
    'seat_rows', (
      SELECT count(*) FROM table_seats ts
      WHERE ts.left_at IS NULL
        AND ts.table_id IN (SELECT id FROM scoped WHERE is_live)
    )
  ) INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION public.ca_club_tables(p_club_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_tables(p_club_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_tables(p_club_id uuid, p_limit integer) IS 'Club dashboard Tables tab: every live table (fullest first, seats counted from table_seats, capped at 500 and saying so) plus the 25 most recently closed. Membership-gated by ca_can_view_club. Horses are counted like every other player.';


--
-- Name: ca_club_top_players(uuid, timestamp with time zone, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_top_players(p_club_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_sort text DEFAULT 'profit'::text) RETURNS TABLE(user_id uuid, display_name text, avatar_url text, is_horse boolean, hands_played bigint, hands_attributed bigint, hands_won bigint, total_won numeric, profit numeric, biggest_pot_won numeric, win_rate numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_may_see boolean := public.fn_can_see_horse_flag(p_club_id);
  v_sort text := lower(coalesce(p_sort, 'profit'));
BEGIN
  IF NOT ca_can_view_club(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  IF v_sort NOT IN ('profit', 'hands', 'winrate', 'biggest') THEN
    v_sort := 'profit';
  END IF;

  RETURN QUERY
  WITH agg AS (
    SELECT
      s.user_id,
      public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                           pr.first_name, pr.last_name, pr.full_name) AS display_name,
      pr.avatar_url,
      (v_may_see AND coalesce(pr.is_horse, false)) AS is_horse,
      sum(s.hands_played)::bigint              AS hands_played,
      sum(s.hands_attributed)::bigint          AS hands_attributed,
      sum(s.hands_won)::bigint                 AS hands_won,
      sum(s.total_won)                         AS total_won,
      sum(s.profit)                            AS profit,
      max(s.biggest_pot_won)                   AS biggest_pot_won,
      round(100.0 * sum(s.hands_won) / nullif(sum(s.hands_played), 0), 1) AS win_rate
    FROM club_member_daily_stats s
    LEFT JOIN profiles pr ON pr.id = s.user_id
    WHERE s.club_id = p_club_id
      AND (p_since IS NULL OR s.stat_date >= (p_since AT TIME ZONE 'UTC')::date)
    GROUP BY s.user_id, pr.alias, pr.username, pr.display_name,
             pr.first_name, pr.last_name, pr.full_name, pr.avatar_url, pr.is_horse
    HAVING sum(s.hands_played) > 0
  )
  SELECT a.user_id, a.display_name, a.avatar_url, a.is_horse,
         a.hands_played, a.hands_attributed, a.hands_won,
         a.total_won, a.profit, a.biggest_pot_won, a.win_rate
  FROM agg a
  ORDER BY
    CASE WHEN v_sort = 'hands'   THEN a.hands_played    END DESC NULLS LAST,
    CASE WHEN v_sort = 'winrate' THEN a.win_rate        END DESC NULLS LAST,
    CASE WHEN v_sort = 'biggest' THEN a.biggest_pot_won END DESC NULLS LAST,
    a.profit DESC,
    a.user_id
  LIMIT least(greatest(coalesce(p_limit, 50), 1), 200);
END;
$$;


ALTER FUNCTION public.ca_club_top_players(p_club_id uuid, p_since timestamp with time zone, p_limit integer, p_sort text) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_top_players(p_club_id uuid, p_since timestamp with time zone, p_limit integer, p_sort text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_top_players(p_club_id uuid, p_since timestamp with time zone, p_limit integer, p_sort text) IS 'Club dashboard leaderboard. p_sort (profit | hands | winrate | biggest) orders BEFORE the limit, so the top N shown under a key is the top N by that key. Membership-gated by ca_can_view_club; the horse flag is masked by fn_can_see_horse_flag.';


--
-- Name: ca_club_tournaments(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_tournaments(p_club_id uuid, p_limit integer DEFAULT 20, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
  v_union uuid;
  v_cap integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_days integer := least(greatest(coalesce(p_days, 30), 1), 365);
  v_from timestamptz := now() - make_interval(days => least(greatest(coalesce(p_days, 30), 1), 365));
BEGIN
  IF NOT ca_can_view_club(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  SELECT union_id INTO v_union FROM clubs WHERE id = p_club_id;

  WITH scoped AS (
    SELECT t.*
    FROM tournaments t
    WHERE t.club_id = p_club_id
       OR (v_union IS NOT NULL AND t.union_id = v_union)
  ),
  live AS (
    SELECT t.id, t.name, t.status,
           coalesce(t.variant, t.game_type) AS variant,
           coalesce(t.buy_in_amount, 0) AS buy_in,
           coalesce(t.prize_pool, 0) AS prize_pool,
           coalesce(t.current_players, 0) AS players,
           t.max_players, t.start_time
    FROM scoped t
    WHERE t.status IN ('running', 'registering', 'late_reg', 'starting', 'scheduled')
    ORDER BY t.start_time
    LIMIT v_cap
  ),
  recent AS (
    SELECT t.id, t.name, t.status,
           coalesce(t.variant, t.game_type) AS variant,
           coalesce(t.buy_in_amount, 0) AS buy_in,
           coalesce(t.prize_pool, 0) AS prize_pool,
           coalesce(t.current_players, 0) AS players,
           t.ended_at
    FROM scoped t
    WHERE t.ended_at IS NOT NULL AND t.ended_at > v_from
    ORDER BY t.ended_at DESC
    LIMIT v_cap
  )
  SELECT jsonb_build_object(
    'live', coalesce((SELECT jsonb_agg(to_jsonb(l) ORDER BY l.start_time) FROM live l), '[]'::jsonb),
    'recent', coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.ended_at DESC) FROM recent r), '[]'::jsonb),
    'summary', (
      SELECT jsonb_build_object(
        'window_days', v_days,
        'live_count', count(*) FILTER (WHERE t.status IN ('running','registering','late_reg','starting','scheduled')),
        'completed_in_window', count(*) FILTER (WHERE t.ended_at IS NOT NULL AND t.ended_at > v_from),
        'prize_pool_in_window', coalesce(sum(t.prize_pool) FILTER (WHERE t.ended_at IS NOT NULL AND t.ended_at > v_from), 0)
      )
      FROM scoped t
    )
  ) INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION public.ca_club_tournaments(p_club_id uuid, p_limit integer, p_days integer) OWNER TO postgres;

--
-- Name: FUNCTION ca_club_tournaments(p_club_id uuid, p_limit integer, p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_tournaments(p_club_id uuid, p_limit integer, p_days integer) IS 'Club dashboard Tournaments tab: live and upcoming, plus those finished inside p_days, each capped at p_limit BEFORE aggregation. Summary counts are over the whole window and say how long it is. Membership-gated by ca_can_view_club.';


--
-- Name: ca_club_union_invoices(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_union_invoices(p_club_id uuid, p_limit integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_lim int := GREATEST(LEAST(COALESCE(p_limit, 12), 52), 1);
BEGIN
  IF NOT ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
             'invoice_id', i.id,
             'status', i.status,
             -- Derived, never stored: a flag needs a job to maintain it, and a
             -- job that does not run leaves the row lying about itself. The
             -- union board has computed it this way since it was built; the
             -- club side used to show the raw status, so an owner read
             -- "generated" on a statement that was days past due.
             'overdue', (i.status NOT IN ('paid','cancelled')
                         AND i.due_at IS NOT NULL AND i.due_at < now()),
             'paid_total', round(COALESCE((i.breakdown->>'paid_total')::numeric, 0), 2),
             'outstanding', round(GREATEST(
                 abs(COALESCE(i.net_amount, 0))
                 - COALESCE((i.breakdown->>'paid_total')::numeric, 0), 0), 2),
             'issued_at', i.created_at,
             'due_at', i.due_at,
             'amount', i.net_amount,
             'direction', i.breakdown->>'direction',
             'period_start', i.breakdown->>'period_start',
             'period_end', i.breakdown->>'period_end',
             'breakdown', i.breakdown,
             'message_sent', COALESCE(i.message_sent, false))
           ORDER BY i.created_at DESC)
      FROM (
        SELECT * FROM settlement_invoices s
         WHERE s.club_id = p_club_id AND s.invoice_type = 'union_weekly_squareup'
         ORDER BY s.created_at DESC LIMIT v_lim
      ) i
  ), '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.ca_club_union_invoices(p_club_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: ca_clubs_missing_hand_daily(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_clubs_missing_hand_daily(p_date date) RETURNS TABLE(club_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT s.club_id
  FROM public.club_member_daily_stats s
  WHERE s.stat_date = p_date
    AND NOT EXISTS (
      SELECT 1
      FROM public.club_hand_daily_shard d
      WHERE d.club_id = s.club_id
        AND d.stat_date = p_date
    );
$$;


ALTER FUNCTION public.ca_clubs_missing_hand_daily(p_date date) OWNER TO postgres;

--
-- Name: ca_clubs_with_rebuild_backlog(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_clubs_with_rebuild_backlog(p_since timestamp with time zone DEFAULT (now() - '90 days'::interval), p_limit integer DEFAULT 10) RETURNS TABLE(club_id uuid, tables_pending bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT s.club_id, count(DISTINCT s.table_id)::bigint AS tables_pending
  FROM public.club_member_daily_stats s
  LEFT JOIN public.club_stats_rebuild_log l ON l.table_id = s.table_id
  WHERE s.stat_date >= p_since::date
    AND coalesce(l.complete, false) = false
  GROUP BY s.club_id
  ORDER BY tables_pending DESC
  LIMIT greatest(coalesce(p_limit, 10), 1);
$$;


ALTER FUNCTION public.ca_clubs_with_rebuild_backlog(p_since timestamp with time zone, p_limit integer) OWNER TO postgres;

--
-- Name: ca_drain_club_rebuild(uuid, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_drain_club_rebuild(p_club_id uuid, p_max_seconds integer DEFAULT 120, p_chunk integer DEFAULT 3000, p_since timestamp with time zone DEFAULT (now() - '90 days'::interval)) RETURNS TABLE(tables_touched integer, tables_completed integer, hands_processed bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '600s'
    AS $$
DECLARE
  v_deadline timestamptz := clock_timestamp() + make_interval(secs => greatest(coalesce(p_max_seconds, 120), 5));
  r          record;
  c          record;
  v_touched  integer := 0;
  v_done     integer := 0;
  v_hands    bigint  := 0;
BEGIN
  FOR r IN
    SELECT t.id
    FROM tables t
    JOIN LATERAL (
      SELECT max(hh.created_at) AS last_hand
      FROM hand_history hh
      WHERE hh.table_id = t.id AND hh.created_at >= p_since
    ) lh ON lh.last_hand IS NOT NULL
    LEFT JOIN club_stats_rebuild_log l ON l.table_id = t.id
    WHERE t.club_id = p_club_id
      AND coalesce(l.complete, false) = false
    ORDER BY lh.last_hand DESC
  LOOP
    EXIT WHEN clock_timestamp() >= v_deadline;
    v_touched := v_touched + 1;
    LOOP
      EXIT WHEN clock_timestamp() >= v_deadline;
      BEGIN
        SELECT * INTO c FROM ca_rebuild_table_chunk(r.id, p_chunk);
      EXCEPTION WHEN OTHERS THEN
        -- Never let one bad table stall the drain; it keeps its cursor and
        -- will be retried on the next run.
        RAISE WARNING 'chunk failed for table %: %', r.id, SQLERRM;
        EXIT;
      END;
      v_hands := v_hands + coalesce(c.hands_processed, 0);
      IF c.complete THEN
        v_done := v_done + 1;
        EXIT;
      END IF;
    END LOOP;
  END LOOP;

  tables_touched := v_touched;
  tables_completed := v_done;
  hands_processed := v_hands;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.ca_drain_club_rebuild(p_club_id uuid, p_max_seconds integer, p_chunk integer, p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: ca_hand_player_facts(timestamp with time zone, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_hand_player_facts(p_from timestamp with time zone, p_to timestamp with time zone, p_user uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid) RETURNS TABLE(user_id uuid, hand_id uuid, created_at timestamp with time zone, is_cash boolean, tournament_id uuid, game_variant text, big_blind numeric, small_blind numeric, n_players integer, seat_position text, my_blind numeric, won_amt numeric, is_winner boolean, invested_actions numeric, aggro_cnt integer, call_cnt integer, vpip boolean, pfr boolean, folded boolean, three_bet boolean, three_bet_opp boolean, faced_three_bet boolean, folded_to_three_bet boolean, cbet_opp boolean, cbet_made boolean, showdown boolean, hand_secs numeric, profit numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Dispatcher only. The body lives in _range and _one (see the DO block
  -- above); pick by access path so the planner never sees a parameter in
  -- an OR.
  IF p_hand_id IS NOT NULL THEN
    RETURN QUERY SELECT * FROM public.ca_hand_player_facts_one(p_hand_id, p_user);
  ELSE
    RETURN QUERY SELECT * FROM public.ca_hand_player_facts_range(p_from, p_to, p_user);
  END IF;
END;
$$;


ALTER FUNCTION public.ca_hand_player_facts(p_from timestamp with time zone, p_to timestamp with time zone, p_user uuid, p_hand_id uuid) OWNER TO postgres;

--
-- Name: ca_hand_player_facts_one(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_hand_player_facts_one(p_hand_id uuid, p_user uuid DEFAULT NULL::uuid) RETURNS TABLE(user_id uuid, hand_id uuid, created_at timestamp with time zone, is_cash boolean, tournament_id uuid, game_variant text, big_blind numeric, small_blind numeric, n_players integer, seat_position text, my_blind numeric, won_amt numeric, is_winner boolean, invested_actions numeric, aggro_cnt integer, call_cnt integer, vpip boolean, pfr boolean, folded boolean, three_bet boolean, three_bet_opp boolean, faced_three_bet boolean, folded_to_three_bet boolean, cbet_opp boolean, cbet_made boolean, showdown boolean, hand_secs numeric, profit numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
WITH my_hands AS MATERIALIZED (
  SELECT h.id, h.tournament_id,
         lower(coalesce(h.game_variant, 'nlh')) AS game_variant,
         coalesce(h.big_blind, 0)::numeric   AS big_blind,
         coalesce(h.small_blind, 0)::numeric AS small_blind,
         coalesce(h.pot_size, 0)::numeric    AS pot_size,
         h.button_seat, h.created_at, h.started_at, h.ended_at,
         h.players,
         coalesce(h.actions, '[]'::jsonb) AS actions,
         coalesce(h.winners, '[]'::jsonb) AS winners
  FROM hand_history h
  WHERE h.id = p_hand_id
),
acts AS MATERIALIZED (
  SELECT mh.id AS hand_id, x.ord,
         x.act->>'userId' AS auid, x.act->>'stage' AS stage,
         lower(x.act->>'action') AS action,
         coalesce((x.act->>'amount')::numeric, 0) AS amount,
         coalesce((x.act->>'dead')::boolean, false) AS dead_flag
  FROM my_hands mh
  CROSS JOIN LATERAL jsonb_array_elements(mh.actions) WITH ORDINALITY x(act, ord)
),
players_all AS (
  SELECT mh.id AS hand_id, pl->>'userId' AS puid, (pl->>'seat')::int AS seat
  FROM my_hands mh
  CROSS JOIN LATERAL jsonb_array_elements(mh.players) pl
),
seatmap AS (
  SELECT hand_id, array_agg(seat ORDER BY seat) AS seats
  FROM players_all GROUP BY hand_id
),
-- The ONLY thing p_user narrows.
seated AS (
  SELECT hand_id, puid::uuid AS uid, seat AS my_seat
  FROM players_all
  WHERE puid ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    AND (p_user IS NULL OR puid = p_user::text)
),
folders AS (
  SELECT DISTINCT hand_id, auid FROM acts WHERE action = 'fold' AND auid IS NOT NULL
),
no_fold AS (
  SELECT p.hand_id,
         count(*) FILTER (WHERE f.auid IS NULL AND p.puid IS NOT NULL) AS no_fold_players
  FROM players_all p
  LEFT JOIN folders f ON f.hand_id = p.hand_id AND f.auid = p.puid
  GROUP BY p.hand_id
),
pf_raise AS (
  SELECT hand_id, ord, auid FROM acts
  WHERE stage = 'preflop' AND action IN ('raise','all_in','allin')
),
pf_ranked AS (
  SELECT hand_id, ord, auid,
         first_value(auid) OVER w AS first_actor,
         first_value(ord)  OVER w AS first_ord,
         last_value(auid)  OVER (PARTITION BY hand_id ORDER BY ord
                                 ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS last_actor
  FROM pf_raise
  WINDOW w AS (PARTITION BY hand_id ORDER BY ord)
),
hand_pf AS (
  SELECT hand_id,
         min(first_ord)   AS first_ord,
         min(first_actor) AS first_actor,
         min(last_actor)  AS last_pf_raiser,
         min(ord) FILTER (WHERE auid IS DISTINCT FROM first_actor) AS first_other_ord
  FROM pf_ranked GROUP BY hand_id
),
flop_first AS (
  SELECT DISTINCT ON (hand_id) hand_id, auid AS first_flop_bettor
  FROM acts WHERE stage = 'flop' AND action IN ('bet','all_in','allin')
  ORDER BY hand_id, ord
),
-- ── MONEY. actions[].amount is NOT one unit (src/utils/handReplay.ts:16-35):
--    bet / raise / all_in  -> raise-TO level for the street (CUMULATIVE)
--    call, blind posts     -> chips actually added           (INCREMENTAL)
--    return                -> uncalled chips handed back     (SUBTRACT)
--    ante (or dead=true)   -> in the pot, NOT in the live bet level
-- Computed for EVERY seat in the hand, not just p_user: the uncalled-bet
-- inference below needs the whole table's bet levels.
money_acts AS (
  SELECT a.hand_id, a.auid, a.stage, a.ord, a.amount,
         CASE
           WHEN a.action IN ('bet','raise','all_in','allin') THEN 'to'
           WHEN a.action = 'return' THEN 'ret'
           WHEN a.action IN ('call','sb','bb','post','post_sb','post_bb','blind',
                             'small_blind','big_blind','straddle','ante') THEN 'inc'
           ELSE 'none'
         END AS kind,
         (a.dead_flag OR a.action = 'ante') AS dead,
         a.action IN ('sb','bb','post','post_sb','post_bb','blind','small_blind','big_blind') AS is_blind_post
  FROM acts a
  WHERE a.auid IS NOT NULL
),
hand_log_shape AS (
  SELECT hand_id,
         bool_or(is_blind_post) AS has_posts,
         bool_or(kind = 'ret')  AS has_returns
  FROM money_acts GROUP BY hand_id
),
-- Position-implied blind for every seat (the rows written before
-- FORCED_BETS_POSTED carry no post rows, so the blinds have to be synthesised
-- exactly as src/utils/handReplay.ts does when !logHasBlinds).
seat_blind AS (
  SELECT p.hand_id, p.puid AS auid, p.seat,
         CASE
           WHEN ofs.pos_offset IS NULL THEN 0
           WHEN array_length(sm.seats, 1) = 2 THEN
             CASE WHEN ofs.pos_offset = 0 THEN mh.small_blind ELSE mh.big_blind END
           WHEN ofs.pos_offset = 1 THEN mh.small_blind
           WHEN ofs.pos_offset = 2 THEN mh.big_blind
           ELSE 0
         END AS implied_blind
  FROM players_all p
  JOIN my_hands mh ON mh.id = p.hand_id
  JOIN seatmap sm ON sm.hand_id = p.hand_id
  CROSS JOIN LATERAL (SELECT CASE
      WHEN mh.button_seat IS NULL OR sm.seats IS NULL
        OR p.seat IS NULL OR array_length(sm.seats, 1) < 2
        OR array_position(sm.seats, mh.button_seat::int) IS NULL THEN NULL
      ELSE (array_position(sm.seats, p.seat)
            - array_position(sm.seats, mh.button_seat::int)
            + array_length(sm.seats, 1)) % array_length(sm.seats, 1)
    END AS pos_offset) ofs
  WHERE p.puid IS NOT NULL
),
money_w AS (
  SELECT m.*,
         max(ord) FILTER (WHERE kind = 'to')
           OVER (PARTITION BY hand_id, auid, stage ORDER BY ord
                 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_to_ord,
         coalesce(sum(amount) FILTER (WHERE kind = 'inc' AND NOT dead)
           OVER (PARTITION BY hand_id, auid, stage ORDER BY ord
                 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), 0) AS inc_cum,
         row_number() OVER (PARTITION BY hand_id, auid, stage ORDER BY ord DESC) AS rn_desc
  FROM money_acts m
),
street_committed_raw AS (
  SELECT w.hand_id, w.auid, w.stage,
         CASE WHEN w.last_to_ord IS NULL THEN w.inc_cum
              ELSE t.amount + (w.inc_cum - t.inc_cum) END AS committed,
         (w.last_to_ord IS NOT NULL) AS to_level
  FROM money_w w
  LEFT JOIN money_w t ON t.hand_id = w.hand_id AND t.auid = w.auid
                     AND t.stage = w.stage AND t.ord = w.last_to_ord
  WHERE w.rn_desc = 1
),
-- Seed the blinds into preflop when the log has no post rows. A player whose
-- preflop bet level is a raise-TO already has the blind inside it.
street_committed AS (
  SELECT r.hand_id, r.auid, r.stage,
         r.committed
           + CASE WHEN r.stage = 'preflop' AND NOT r.to_level AND NOT coalesce(hs.has_posts, false)
                  THEN coalesce(sb.implied_blind, 0) ELSE 0 END AS committed
  FROM street_committed_raw r
  LEFT JOIN hand_log_shape hs ON hs.hand_id = r.hand_id
  LEFT JOIN seat_blind sb ON sb.hand_id = r.hand_id AND sb.auid = r.auid
  UNION ALL
  -- Blind seats that never acted (walk, or a fold with no logged row).
  SELECT sb.hand_id, sb.auid, 'preflop', sb.implied_blind
  FROM seat_blind sb
  LEFT JOIN hand_log_shape hs ON hs.hand_id = sb.hand_id
  LEFT JOIN street_committed_raw r
         ON r.hand_id = sb.hand_id AND r.auid = sb.auid AND r.stage = 'preflop'
  WHERE sb.implied_blind > 0
    AND NOT coalesce(hs.has_posts, false)
    AND r.hand_id IS NULL
),
-- An uncalled bet on a log that does not record returns: the street's top
-- contributor's excess over the next highest was matched by nobody.
street_rank AS (
  SELECT sc.hand_id, sc.stage, sc.auid, sc.committed,
         row_number() OVER (PARTITION BY sc.hand_id, sc.stage ORDER BY sc.committed DESC) AS rn,
         lead(sc.committed) OVER (PARTITION BY sc.hand_id, sc.stage ORDER BY sc.committed DESC) AS next_committed
  FROM street_committed sc
),
inferred_ret AS (
  SELECT r.hand_id, r.auid,
         sum(r.committed - coalesce(r.next_committed, 0)) AS inferred
  FROM street_rank r
  JOIN hand_log_shape hs ON hs.hand_id = r.hand_id
  WHERE r.rn = 1 AND NOT hs.has_returns
    AND r.committed - coalesce(r.next_committed, 0) > 0.005
  GROUP BY r.hand_id, r.auid
),
money_extras AS (
  SELECT hand_id, auid,
         coalesce(sum(amount) FILTER (WHERE kind = 'inc' AND dead), 0) AS dead_money,
         coalesce(sum(amount) FILTER (WHERE kind = 'ret'), 0) AS returned,
         coalesce(sum(amount) FILTER (WHERE is_blind_post AND NOT dead), 0) AS posted_blind
  FROM money_acts GROUP BY hand_id, auid
),
money_per_player AS (
  SELECT sc.hand_id, sc.auid,
         sum(sc.committed) AS live_committed
  FROM street_committed sc GROUP BY sc.hand_id, sc.auid
),
-- THE STORED POT ARBITRATES THE INFERENCE (handReplay.ts, same rule): if the
-- rebuild WITH inferred returns misses pot_size and the rebuild WITHOUT them
-- lands on it, the inference was wrong for this hand and is withdrawn.
--
-- Per-hand totals are GROUPed once and joined, never re-scanned per hand:
-- the correlated form this replaced walked the whole CTE for every hand,
-- which is quadratic in the window and is why the range form took 10 s for
-- four minutes of hands (2026-09-04). Same numbers, hash joins.
pot_live AS (
  SELECT hand_id, sum(live_committed) AS s FROM money_per_player GROUP BY hand_id
),
pot_extras AS (
  SELECT hand_id, sum(dead_money - returned) AS s FROM money_extras GROUP BY hand_id
),
pot_inferred AS (
  SELECT hand_id, sum(inferred) AS s FROM inferred_ret GROUP BY hand_id
),
hand_pot_check AS (
  SELECT mh.id AS hand_id,
         mh.pot_size,
         coalesce(pl.s, 0) + coalesce(px.s, 0) AS pot_without,
         coalesce(pi.s, 0) AS inferred_total
  FROM my_hands mh
  LEFT JOIN pot_live     pl ON pl.hand_id = mh.id
  LEFT JOIN pot_extras   px ON px.hand_id = mh.id
  LEFT JOIN pot_inferred pi ON pi.hand_id = mh.id
),
inference_ok AS (
  SELECT hand_id,
         NOT (inferred_total > 0
              AND abs((pot_without - inferred_total) - pot_size) >= 0.02
              AND abs(pot_without - pot_size) < 0.02) AS use_inference
  FROM hand_pot_check
),
per_player_base AS (
  SELECT s.hand_id, s.uid, s.my_seat,
    coalesce(bool_or(a.stage = 'preflop' AND a.action IN ('call','bet','raise','all_in','allin')), false) AS vpip,
    coalesce(bool_or(a.stage = 'preflop' AND a.action IN ('raise','all_in','allin')), false) AS pfr,
    count(*) FILTER (WHERE a.action IN ('bet','raise','all_in','allin'))::int AS aggro_cnt,
    count(*) FILTER (WHERE a.action = 'call')::int AS call_cnt,
    coalesce(bool_or(a.action = 'fold'), false) AS folded,
    coalesce(bool_or(a.stage = 'flop'), false) AS acted_on_flop,
    min(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action IN ('raise','all_in','allin')) AS my_first_pf_raise,
    max(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action IN ('raise','all_in','allin')) AS my_last_pf_raise,
    max(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action NOT IN ('sb','bb','post','post_sb','post_bb','blind','small_blind','big_blind','ante','straddle','return')) AS my_last_pf_any,
    max(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action = 'fold') AS my_last_pf_fold
  FROM seated s
  LEFT JOIN acts a ON a.hand_id = s.hand_id AND a.auid = s.uid::text
  GROUP BY s.hand_id, s.uid, s.my_seat
),
with_first_other AS (
  SELECT b.*,
    CASE WHEN hp.first_actor IS DISTINCT FROM b.uid::text
         THEN hp.first_ord ELSE hp.first_other_ord END AS first_other_pf_raise,
    hp.last_pf_raiser
  FROM per_player_base b
  LEFT JOIN hand_pf hp ON hp.hand_id = b.hand_id
),
reraise AS (
  SELECT b.hand_id, b.uid, min(p.ord) AS reraise_after_me
  FROM with_first_other b
  JOIN pf_raise p ON p.hand_id = b.hand_id
  WHERE p.auid IS DISTINCT FROM b.uid::text AND p.ord > b.my_first_pf_raise
  GROUP BY b.hand_id, b.uid
)
SELECT
  d.uid, mh.id, mh.created_at,
  (mh.tournament_id IS NULL), mh.tournament_id, mh.game_variant,
  mh.big_blind, mh.small_blind, array_length(sm.seats, 1),
  pos.seat_position,
  -- my_blind: what the log says was posted when it says anything, else the
  -- blind the position implies (rows written before FORCED_BETS_POSTED).
  inv.my_blind,
  w.won_amt, w.is_winner,
  -- invested_actions EXCLUDES the blind above, so `invested_actions + my_blind`
  -- keeps meaning "everything this seat put in", as every reader assumes.
  inv.total_invested - inv.my_blind,
  d.aggro_cnt, d.call_cnt, d.vpip, d.pfr, d.folded,
  coalesce(d.my_last_pf_raise > d.first_other_pf_raise, false),
  coalesce(d.my_last_pf_any   > d.first_other_pf_raise, false),
  (r.reraise_after_me IS NOT NULL),
  coalesce(d.my_last_pf_fold > r.reraise_after_me, false),
  coalesce(d.last_pf_raiser = d.uid::text AND d.acted_on_flop, false),
  coalesce(d.last_pf_raiser = d.uid::text AND ff.first_flop_bettor = d.uid::text, false),
  (NOT d.folded AND nf.no_fold_players >= 2),
  CASE
    WHEN mh.started_at IS NOT NULL AND mh.ended_at IS NOT NULL
    THEN GREATEST(0, LEAST(1800, EXTRACT(epoch FROM (mh.ended_at - mh.started_at))))::numeric
    ELSE 45
  END,
  (w.won_amt - inv.total_invested)
FROM with_first_other d
JOIN my_hands mh ON mh.id = d.hand_id
JOIN seatmap  sm ON sm.hand_id = d.hand_id
JOIN no_fold  nf ON nf.hand_id = d.hand_id
LEFT JOIN reraise    r  ON r.hand_id  = d.hand_id AND r.uid = d.uid
LEFT JOIN flop_first ff ON ff.hand_id = d.hand_id
LEFT JOIN money_per_player mp ON mp.hand_id = d.hand_id AND mp.auid = d.uid::text
LEFT JOIN money_extras     mx ON mx.hand_id = d.hand_id AND mx.auid = d.uid::text
LEFT JOIN inferred_ret     ir ON ir.hand_id = d.hand_id AND ir.auid = d.uid::text
LEFT JOIN hand_log_shape   hs ON hs.hand_id = d.hand_id
LEFT JOIN inference_ok     io ON io.hand_id = d.hand_id
CROSS JOIN LATERAL (
  SELECT
    coalesce(sum((w1->>'amount')::numeric) FILTER (WHERE w1->>'userId' = d.uid::text), 0) AS won_amt,
    count(*) FILTER (WHERE w1->>'userId' = d.uid::text) > 0 AS is_winner
  FROM jsonb_array_elements(mh.winners) w1
) w
CROSS JOIN LATERAL (
  SELECT
    CASE
      WHEN ofs.pos_offset IS NULL THEN 0
      WHEN array_length(sm.seats, 1) = 2 THEN
        CASE WHEN ofs.pos_offset = 0 THEN mh.small_blind ELSE mh.big_blind END
      WHEN ofs.pos_offset = 1 THEN mh.small_blind
      WHEN ofs.pos_offset = 2 THEN mh.big_blind
      ELSE 0
    END AS my_blind,
    CASE
      WHEN ofs.pos_offset IS NULL THEN 'UNK'
      WHEN array_length(sm.seats, 1) = 2 THEN CASE WHEN ofs.pos_offset = 0 THEN 'BTN' ELSE 'BB' END
      WHEN ofs.pos_offset = 0 THEN 'BTN'
      WHEN ofs.pos_offset = 1 THEN 'SB'
      WHEN ofs.pos_offset = 2 THEN 'BB'
      WHEN ofs.pos_offset = array_length(sm.seats, 1) - 1 THEN 'CO'
      WHEN ofs.pos_offset = 3 THEN 'UTG'
      WHEN ofs.pos_offset = 4 AND array_length(sm.seats, 1) >= 8 THEN 'UTG+1'
      ELSE 'MP'
    END AS seat_position
  FROM (SELECT CASE
      WHEN mh.button_seat IS NULL OR sm.seats IS NULL
        OR d.my_seat IS NULL OR array_length(sm.seats, 1) < 2
        OR array_position(sm.seats, mh.button_seat::int) IS NULL THEN NULL
      ELSE (array_position(sm.seats, d.my_seat)
            - array_position(sm.seats, mh.button_seat::int)
            + array_length(sm.seats, 1)) % array_length(sm.seats, 1)
    END AS pos_offset) ofs
) pos
CROSS JOIN LATERAL (
  -- Everything this seat put in: live bet levels per street (blinds seeded
  -- when the log has no post rows), plus dead money, minus what came back -
  -- recorded, or inferred when the log predates recorded returns.
  SELECT coalesce(mp.live_committed, 0)
       + coalesce(mx.dead_money, 0)
       - coalesce(mx.returned, 0)
       - CASE WHEN coalesce(io.use_inference, true) THEN coalesce(ir.inferred, 0) ELSE 0 END AS total_invested,
         CASE WHEN coalesce(hs.has_posts, false) THEN coalesce(mx.posted_blind, 0) ELSE pos.my_blind END AS my_blind
) inv;
$_$;


ALTER FUNCTION public.ca_hand_player_facts_one(p_hand_id uuid, p_user uuid) OWNER TO postgres;

--
-- Name: FUNCTION ca_hand_player_facts_one(p_hand_id uuid, p_user uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_hand_player_facts_one(p_hand_id uuid, p_user uuid) IS 'Per player per hand stat facts for one hand. The trigger form of ca_hand_player_facts; same body as _range with an id predicate. Service role only.';


--
-- Name: ca_hand_player_facts_range(timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_hand_player_facts_range(p_from timestamp with time zone, p_to timestamp with time zone, p_user uuid DEFAULT NULL::uuid) RETURNS TABLE(user_id uuid, hand_id uuid, created_at timestamp with time zone, is_cash boolean, tournament_id uuid, game_variant text, big_blind numeric, small_blind numeric, n_players integer, seat_position text, my_blind numeric, won_amt numeric, is_winner boolean, invested_actions numeric, aggro_cnt integer, call_cnt integer, vpip boolean, pfr boolean, folded boolean, three_bet boolean, three_bet_opp boolean, faced_three_bet boolean, folded_to_three_bet boolean, cbet_opp boolean, cbet_made boolean, showdown boolean, hand_secs numeric, profit numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
WITH my_hands AS MATERIALIZED (
  SELECT h.id, h.tournament_id,
         lower(coalesce(h.game_variant, 'nlh')) AS game_variant,
         coalesce(h.big_blind, 0)::numeric   AS big_blind,
         coalesce(h.small_blind, 0)::numeric AS small_blind,
         coalesce(h.pot_size, 0)::numeric    AS pot_size,
         h.button_seat, h.created_at, h.started_at, h.ended_at,
         h.players,
         coalesce(h.actions, '[]'::jsonb) AS actions,
         coalesce(h.winners, '[]'::jsonb) AS winners
  FROM hand_history h
  WHERE h.created_at >= p_from AND h.created_at < p_to
),
acts AS MATERIALIZED (
  SELECT mh.id AS hand_id, x.ord,
         x.act->>'userId' AS auid, x.act->>'stage' AS stage,
         lower(x.act->>'action') AS action,
         coalesce((x.act->>'amount')::numeric, 0) AS amount,
         coalesce((x.act->>'dead')::boolean, false) AS dead_flag
  FROM my_hands mh
  CROSS JOIN LATERAL jsonb_array_elements(mh.actions) WITH ORDINALITY x(act, ord)
),
players_all AS (
  SELECT mh.id AS hand_id, pl->>'userId' AS puid, (pl->>'seat')::int AS seat
  FROM my_hands mh
  CROSS JOIN LATERAL jsonb_array_elements(mh.players) pl
),
seatmap AS (
  SELECT hand_id, array_agg(seat ORDER BY seat) AS seats
  FROM players_all GROUP BY hand_id
),
-- The ONLY thing p_user narrows.
seated AS (
  SELECT hand_id, puid::uuid AS uid, seat AS my_seat
  FROM players_all
  WHERE puid ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    AND (p_user IS NULL OR puid = p_user::text)
),
folders AS (
  SELECT DISTINCT hand_id, auid FROM acts WHERE action = 'fold' AND auid IS NOT NULL
),
no_fold AS (
  SELECT p.hand_id,
         count(*) FILTER (WHERE f.auid IS NULL AND p.puid IS NOT NULL) AS no_fold_players
  FROM players_all p
  LEFT JOIN folders f ON f.hand_id = p.hand_id AND f.auid = p.puid
  GROUP BY p.hand_id
),
pf_raise AS (
  SELECT hand_id, ord, auid FROM acts
  WHERE stage = 'preflop' AND action IN ('raise','all_in','allin')
),
pf_ranked AS (
  SELECT hand_id, ord, auid,
         first_value(auid) OVER w AS first_actor,
         first_value(ord)  OVER w AS first_ord,
         last_value(auid)  OVER (PARTITION BY hand_id ORDER BY ord
                                 ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS last_actor
  FROM pf_raise
  WINDOW w AS (PARTITION BY hand_id ORDER BY ord)
),
hand_pf AS (
  SELECT hand_id,
         min(first_ord)   AS first_ord,
         min(first_actor) AS first_actor,
         min(last_actor)  AS last_pf_raiser,
         min(ord) FILTER (WHERE auid IS DISTINCT FROM first_actor) AS first_other_ord
  FROM pf_ranked GROUP BY hand_id
),
flop_first AS (
  SELECT DISTINCT ON (hand_id) hand_id, auid AS first_flop_bettor
  FROM acts WHERE stage = 'flop' AND action IN ('bet','all_in','allin')
  ORDER BY hand_id, ord
),
-- ── MONEY. actions[].amount is NOT one unit (src/utils/handReplay.ts:16-35):
--    bet / raise / all_in  -> raise-TO level for the street (CUMULATIVE)
--    call, blind posts     -> chips actually added           (INCREMENTAL)
--    return                -> uncalled chips handed back     (SUBTRACT)
--    ante (or dead=true)   -> in the pot, NOT in the live bet level
-- Computed for EVERY seat in the hand, not just p_user: the uncalled-bet
-- inference below needs the whole table's bet levels.
money_acts AS (
  SELECT a.hand_id, a.auid, a.stage, a.ord, a.amount,
         CASE
           WHEN a.action IN ('bet','raise','all_in','allin') THEN 'to'
           WHEN a.action = 'return' THEN 'ret'
           WHEN a.action IN ('call','sb','bb','post','post_sb','post_bb','blind',
                             'small_blind','big_blind','straddle','ante') THEN 'inc'
           ELSE 'none'
         END AS kind,
         (a.dead_flag OR a.action = 'ante') AS dead,
         a.action IN ('sb','bb','post','post_sb','post_bb','blind','small_blind','big_blind') AS is_blind_post
  FROM acts a
  WHERE a.auid IS NOT NULL
),
hand_log_shape AS (
  SELECT hand_id,
         bool_or(is_blind_post) AS has_posts,
         bool_or(kind = 'ret')  AS has_returns
  FROM money_acts GROUP BY hand_id
),
-- Position-implied blind for every seat (the rows written before
-- FORCED_BETS_POSTED carry no post rows, so the blinds have to be synthesised
-- exactly as src/utils/handReplay.ts does when !logHasBlinds).
seat_blind AS (
  SELECT p.hand_id, p.puid AS auid, p.seat,
         CASE
           WHEN ofs.pos_offset IS NULL THEN 0
           WHEN array_length(sm.seats, 1) = 2 THEN
             CASE WHEN ofs.pos_offset = 0 THEN mh.small_blind ELSE mh.big_blind END
           WHEN ofs.pos_offset = 1 THEN mh.small_blind
           WHEN ofs.pos_offset = 2 THEN mh.big_blind
           ELSE 0
         END AS implied_blind
  FROM players_all p
  JOIN my_hands mh ON mh.id = p.hand_id
  JOIN seatmap sm ON sm.hand_id = p.hand_id
  CROSS JOIN LATERAL (SELECT CASE
      WHEN mh.button_seat IS NULL OR sm.seats IS NULL
        OR p.seat IS NULL OR array_length(sm.seats, 1) < 2
        OR array_position(sm.seats, mh.button_seat::int) IS NULL THEN NULL
      ELSE (array_position(sm.seats, p.seat)
            - array_position(sm.seats, mh.button_seat::int)
            + array_length(sm.seats, 1)) % array_length(sm.seats, 1)
    END AS pos_offset) ofs
  WHERE p.puid IS NOT NULL
),
money_w AS (
  SELECT m.*,
         max(ord) FILTER (WHERE kind = 'to')
           OVER (PARTITION BY hand_id, auid, stage ORDER BY ord
                 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_to_ord,
         coalesce(sum(amount) FILTER (WHERE kind = 'inc' AND NOT dead)
           OVER (PARTITION BY hand_id, auid, stage ORDER BY ord
                 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), 0) AS inc_cum,
         row_number() OVER (PARTITION BY hand_id, auid, stage ORDER BY ord DESC) AS rn_desc
  FROM money_acts m
),
street_committed_raw AS (
  SELECT w.hand_id, w.auid, w.stage,
         CASE WHEN w.last_to_ord IS NULL THEN w.inc_cum
              ELSE t.amount + (w.inc_cum - t.inc_cum) END AS committed,
         (w.last_to_ord IS NOT NULL) AS to_level
  FROM money_w w
  LEFT JOIN money_w t ON t.hand_id = w.hand_id AND t.auid = w.auid
                     AND t.stage = w.stage AND t.ord = w.last_to_ord
  WHERE w.rn_desc = 1
),
-- Seed the blinds into preflop when the log has no post rows. A player whose
-- preflop bet level is a raise-TO already has the blind inside it.
street_committed AS (
  SELECT r.hand_id, r.auid, r.stage,
         r.committed
           + CASE WHEN r.stage = 'preflop' AND NOT r.to_level AND NOT coalesce(hs.has_posts, false)
                  THEN coalesce(sb.implied_blind, 0) ELSE 0 END AS committed
  FROM street_committed_raw r
  LEFT JOIN hand_log_shape hs ON hs.hand_id = r.hand_id
  LEFT JOIN seat_blind sb ON sb.hand_id = r.hand_id AND sb.auid = r.auid
  UNION ALL
  -- Blind seats that never acted (walk, or a fold with no logged row).
  SELECT sb.hand_id, sb.auid, 'preflop', sb.implied_blind
  FROM seat_blind sb
  LEFT JOIN hand_log_shape hs ON hs.hand_id = sb.hand_id
  LEFT JOIN street_committed_raw r
         ON r.hand_id = sb.hand_id AND r.auid = sb.auid AND r.stage = 'preflop'
  WHERE sb.implied_blind > 0
    AND NOT coalesce(hs.has_posts, false)
    AND r.hand_id IS NULL
),
-- An uncalled bet on a log that does not record returns: the street's top
-- contributor's excess over the next highest was matched by nobody.
street_rank AS (
  SELECT sc.hand_id, sc.stage, sc.auid, sc.committed,
         row_number() OVER (PARTITION BY sc.hand_id, sc.stage ORDER BY sc.committed DESC) AS rn,
         lead(sc.committed) OVER (PARTITION BY sc.hand_id, sc.stage ORDER BY sc.committed DESC) AS next_committed
  FROM street_committed sc
),
inferred_ret AS (
  SELECT r.hand_id, r.auid,
         sum(r.committed - coalesce(r.next_committed, 0)) AS inferred
  FROM street_rank r
  JOIN hand_log_shape hs ON hs.hand_id = r.hand_id
  WHERE r.rn = 1 AND NOT hs.has_returns
    AND r.committed - coalesce(r.next_committed, 0) > 0.005
  GROUP BY r.hand_id, r.auid
),
money_extras AS (
  SELECT hand_id, auid,
         coalesce(sum(amount) FILTER (WHERE kind = 'inc' AND dead), 0) AS dead_money,
         coalesce(sum(amount) FILTER (WHERE kind = 'ret'), 0) AS returned,
         coalesce(sum(amount) FILTER (WHERE is_blind_post AND NOT dead), 0) AS posted_blind
  FROM money_acts GROUP BY hand_id, auid
),
money_per_player AS (
  SELECT sc.hand_id, sc.auid,
         sum(sc.committed) AS live_committed
  FROM street_committed sc GROUP BY sc.hand_id, sc.auid
),
-- THE STORED POT ARBITRATES THE INFERENCE (handReplay.ts, same rule): if the
-- rebuild WITH inferred returns misses pot_size and the rebuild WITHOUT them
-- lands on it, the inference was wrong for this hand and is withdrawn.
--
-- Per-hand totals are GROUPed once and joined, never re-scanned per hand:
-- the correlated form this replaced walked the whole CTE for every hand,
-- which is quadratic in the window and is why the range form took 10 s for
-- four minutes of hands (2026-09-04). Same numbers, hash joins.
pot_live AS (
  SELECT hand_id, sum(live_committed) AS s FROM money_per_player GROUP BY hand_id
),
pot_extras AS (
  SELECT hand_id, sum(dead_money - returned) AS s FROM money_extras GROUP BY hand_id
),
pot_inferred AS (
  SELECT hand_id, sum(inferred) AS s FROM inferred_ret GROUP BY hand_id
),
hand_pot_check AS (
  SELECT mh.id AS hand_id,
         mh.pot_size,
         coalesce(pl.s, 0) + coalesce(px.s, 0) AS pot_without,
         coalesce(pi.s, 0) AS inferred_total
  FROM my_hands mh
  LEFT JOIN pot_live     pl ON pl.hand_id = mh.id
  LEFT JOIN pot_extras   px ON px.hand_id = mh.id
  LEFT JOIN pot_inferred pi ON pi.hand_id = mh.id
),
inference_ok AS (
  SELECT hand_id,
         NOT (inferred_total > 0
              AND abs((pot_without - inferred_total) - pot_size) >= 0.02
              AND abs(pot_without - pot_size) < 0.02) AS use_inference
  FROM hand_pot_check
),
per_player_base AS (
  SELECT s.hand_id, s.uid, s.my_seat,
    coalesce(bool_or(a.stage = 'preflop' AND a.action IN ('call','bet','raise','all_in','allin')), false) AS vpip,
    coalesce(bool_or(a.stage = 'preflop' AND a.action IN ('raise','all_in','allin')), false) AS pfr,
    count(*) FILTER (WHERE a.action IN ('bet','raise','all_in','allin'))::int AS aggro_cnt,
    count(*) FILTER (WHERE a.action = 'call')::int AS call_cnt,
    coalesce(bool_or(a.action = 'fold'), false) AS folded,
    coalesce(bool_or(a.stage = 'flop'), false) AS acted_on_flop,
    min(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action IN ('raise','all_in','allin')) AS my_first_pf_raise,
    max(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action IN ('raise','all_in','allin')) AS my_last_pf_raise,
    max(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action NOT IN ('sb','bb','post','post_sb','post_bb','blind','small_blind','big_blind','ante','straddle','return')) AS my_last_pf_any,
    max(a.ord) FILTER (WHERE a.stage = 'preflop' AND a.action = 'fold') AS my_last_pf_fold
  FROM seated s
  LEFT JOIN acts a ON a.hand_id = s.hand_id AND a.auid = s.uid::text
  GROUP BY s.hand_id, s.uid, s.my_seat
),
with_first_other AS (
  SELECT b.*,
    CASE WHEN hp.first_actor IS DISTINCT FROM b.uid::text
         THEN hp.first_ord ELSE hp.first_other_ord END AS first_other_pf_raise,
    hp.last_pf_raiser
  FROM per_player_base b
  LEFT JOIN hand_pf hp ON hp.hand_id = b.hand_id
),
reraise AS (
  SELECT b.hand_id, b.uid, min(p.ord) AS reraise_after_me
  FROM with_first_other b
  JOIN pf_raise p ON p.hand_id = b.hand_id
  WHERE p.auid IS DISTINCT FROM b.uid::text AND p.ord > b.my_first_pf_raise
  GROUP BY b.hand_id, b.uid
)
SELECT
  d.uid, mh.id, mh.created_at,
  (mh.tournament_id IS NULL), mh.tournament_id, mh.game_variant,
  mh.big_blind, mh.small_blind, array_length(sm.seats, 1),
  pos.seat_position,
  -- my_blind: what the log says was posted when it says anything, else the
  -- blind the position implies (rows written before FORCED_BETS_POSTED).
  inv.my_blind,
  w.won_amt, w.is_winner,
  -- invested_actions EXCLUDES the blind above, so `invested_actions + my_blind`
  -- keeps meaning "everything this seat put in", as every reader assumes.
  inv.total_invested - inv.my_blind,
  d.aggro_cnt, d.call_cnt, d.vpip, d.pfr, d.folded,
  coalesce(d.my_last_pf_raise > d.first_other_pf_raise, false),
  coalesce(d.my_last_pf_any   > d.first_other_pf_raise, false),
  (r.reraise_after_me IS NOT NULL),
  coalesce(d.my_last_pf_fold > r.reraise_after_me, false),
  coalesce(d.last_pf_raiser = d.uid::text AND d.acted_on_flop, false),
  coalesce(d.last_pf_raiser = d.uid::text AND ff.first_flop_bettor = d.uid::text, false),
  (NOT d.folded AND nf.no_fold_players >= 2),
  CASE
    WHEN mh.started_at IS NOT NULL AND mh.ended_at IS NOT NULL
    THEN GREATEST(0, LEAST(1800, EXTRACT(epoch FROM (mh.ended_at - mh.started_at))))::numeric
    ELSE 45
  END,
  (w.won_amt - inv.total_invested)
FROM with_first_other d
JOIN my_hands mh ON mh.id = d.hand_id
JOIN seatmap  sm ON sm.hand_id = d.hand_id
JOIN no_fold  nf ON nf.hand_id = d.hand_id
LEFT JOIN reraise    r  ON r.hand_id  = d.hand_id AND r.uid = d.uid
LEFT JOIN flop_first ff ON ff.hand_id = d.hand_id
LEFT JOIN money_per_player mp ON mp.hand_id = d.hand_id AND mp.auid = d.uid::text
LEFT JOIN money_extras     mx ON mx.hand_id = d.hand_id AND mx.auid = d.uid::text
LEFT JOIN inferred_ret     ir ON ir.hand_id = d.hand_id AND ir.auid = d.uid::text
LEFT JOIN hand_log_shape   hs ON hs.hand_id = d.hand_id
LEFT JOIN inference_ok     io ON io.hand_id = d.hand_id
CROSS JOIN LATERAL (
  SELECT
    coalesce(sum((w1->>'amount')::numeric) FILTER (WHERE w1->>'userId' = d.uid::text), 0) AS won_amt,
    count(*) FILTER (WHERE w1->>'userId' = d.uid::text) > 0 AS is_winner
  FROM jsonb_array_elements(mh.winners) w1
) w
CROSS JOIN LATERAL (
  SELECT
    CASE
      WHEN ofs.pos_offset IS NULL THEN 0
      WHEN array_length(sm.seats, 1) = 2 THEN
        CASE WHEN ofs.pos_offset = 0 THEN mh.small_blind ELSE mh.big_blind END
      WHEN ofs.pos_offset = 1 THEN mh.small_blind
      WHEN ofs.pos_offset = 2 THEN mh.big_blind
      ELSE 0
    END AS my_blind,
    CASE
      WHEN ofs.pos_offset IS NULL THEN 'UNK'
      WHEN array_length(sm.seats, 1) = 2 THEN CASE WHEN ofs.pos_offset = 0 THEN 'BTN' ELSE 'BB' END
      WHEN ofs.pos_offset = 0 THEN 'BTN'
      WHEN ofs.pos_offset = 1 THEN 'SB'
      WHEN ofs.pos_offset = 2 THEN 'BB'
      WHEN ofs.pos_offset = array_length(sm.seats, 1) - 1 THEN 'CO'
      WHEN ofs.pos_offset = 3 THEN 'UTG'
      WHEN ofs.pos_offset = 4 AND array_length(sm.seats, 1) >= 8 THEN 'UTG+1'
      ELSE 'MP'
    END AS seat_position
  FROM (SELECT CASE
      WHEN mh.button_seat IS NULL OR sm.seats IS NULL
        OR d.my_seat IS NULL OR array_length(sm.seats, 1) < 2
        OR array_position(sm.seats, mh.button_seat::int) IS NULL THEN NULL
      ELSE (array_position(sm.seats, d.my_seat)
            - array_position(sm.seats, mh.button_seat::int)
            + array_length(sm.seats, 1)) % array_length(sm.seats, 1)
    END AS pos_offset) ofs
) pos
CROSS JOIN LATERAL (
  -- Everything this seat put in: live bet levels per street (blinds seeded
  -- when the log has no post rows), plus dead money, minus what came back -
  -- recorded, or inferred when the log predates recorded returns.
  SELECT coalesce(mp.live_committed, 0)
       + coalesce(mx.dead_money, 0)
       - coalesce(mx.returned, 0)
       - CASE WHEN coalesce(io.use_inference, true) THEN coalesce(ir.inferred, 0) ELSE 0 END AS total_invested,
         CASE WHEN coalesce(hs.has_posts, false) THEN coalesce(mx.posted_blind, 0) ELSE pos.my_blind END AS my_blind
) inv;
$_$;


ALTER FUNCTION public.ca_hand_player_facts_range(p_from timestamp with time zone, p_to timestamp with time zone, p_user uuid) OWNER TO postgres;

--
-- Name: FUNCTION ca_hand_player_facts_range(p_from timestamp with time zone, p_to timestamp with time zone, p_user uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_hand_player_facts_range(p_from timestamp with time zone, p_to timestamp with time zone, p_user uuid) IS 'Per player per hand stat facts for every hand in [p_from, p_to). The window form of ca_hand_player_facts; same body as _one with a range predicate. Service role only.';


--
-- Name: horse_daily_audit; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.horse_daily_audit (
    day date NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    stats jsonb DEFAULT '{}'::jsonb NOT NULL,
    findings jsonb DEFAULT '[]'::jsonb NOT NULL,
    agent_analysis jsonb,
    agent_analyzed_at timestamp with time zone
);


ALTER TABLE public.horse_daily_audit OWNER TO postgres;

--
-- Name: TABLE horse_daily_audit; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.horse_daily_audit IS 'Per-day audit of horse decision quality: machine findings from fn_run_horse_daily_audit (engine nightly job), plus the daily Claude deep-analysis in agent_analysis. Admin UI: smarter.poker/horses/hand-reviews.';


--
-- Name: ca_horse_daily_audit(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_horse_daily_audit(p_days integer DEFAULT 14) RETURNS SETOF public.horse_daily_audit
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not fn_is_horse_admin() then
    raise exception 'admin only';
  end if;
  return query
    select * from horse_daily_audit
    where day > current_date - least(greatest(coalesce(p_days, 14), 1), 90)
    order by day desc;
end $$;


ALTER FUNCTION public.ca_horse_daily_audit(p_days integer) OWNER TO postgres;

--
-- Name: ca_horse_data_ledger(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_horse_data_ledger(p_day date DEFAULT (CURRENT_DATE - 1)) RETURNS TABLE(key text, kind text, name text, source text, cadence text, consumer text, note text, ratio_of text, min_ratio numeric, fires bigint, denominator bigint, ratio numeric, proven text, since text, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
begin
  if not fn_is_horse_admin() then
    raise exception 'admin only';
  end if;
  return query
    with l as (
      select d.*, split_part(d.key, ':', 2) as name from horse_data_ledger d
    ),
    f as (
      select l.key,
             case when l.kind = 'receipt' then fn_ledger_fires(p_day, l.name) end as fires,
             case when l.kind = 'receipt' and l.ratio_of is not null then fn_ledger_fires(p_day, l.ratio_of) end as denominator
        from l
    )
    select l.key, l.kind, l.name, l.source, l.cadence, l.consumer, l.note,
           l.ratio_of, l.min_ratio, f.fires, f.denominator,
           case when f.denominator > 0 then round(f.fires::numeric / f.denominator, 6) end as ratio,
           case
             when l.kind = 'receipt' and f.fires > 0 then 'yes'
             when l.kind = 'receipt' and l.ratio_of is null then 'mix'
             when l.kind = 'receipt' and coalesce(f.denominator, 0) < 1000 then 'quiet'
             when l.kind = 'receipt' then 'NO'
             when l.cadence = 'legacy_unused' then 'legacy'
             else 'n/a'
           end as proven,
           l.since, l.updated_at
      from l left join f on f.key = l.key
     order by case l.kind when 'receipt' then 0 when 'table' then 1 when 'profile' then 2
                          when 'mind' then 3 when 'param' then 4 when 'state' then 5 else 6 end,
              l.key;
end
$$;


ALTER FUNCTION public.ca_horse_data_ledger(p_day date) OWNER TO postgres;

--
-- Name: ca_horse_frequency_card(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_horse_frequency_card(p_days integer DEFAULT 7) RETURNS TABLE(horse_user_id uuid, alias text, hands bigint, vpip numeric, pfr_of_vpip numeric, three_bet numeric, fold_to_3bet numeric, wwsf numeric, af numeric, leaks text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not fn_is_horse_admin() then
    raise exception 'admin only';
  end if;
  return query
    select f.horse_user_id,
           (select coalesce(p.alias, p.display_name, p.username) from profiles p where p.id = f.horse_user_id),
           f.hands, f.vpip, f.pfr_of_vpip, f.three_bet, f.fold_to_3bet, f.wwsf, f.af, f.leaks
      from fn_horse_frequency_leaks(
             (now() at time zone 'utc')::date - least(greatest(coalesce(p_days, 7), 1), 90)
           ) f
     where cardinality(f.leaks) > 0
     order by cardinality(f.leaks) desc, f.hands desc;
end $$;


ALTER FUNCTION public.ca_horse_frequency_card(p_days integer) OWNER TO postgres;

--
-- Name: horse_hand_reviews; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.horse_hand_reviews (
    id bigint NOT NULL,
    hand_id uuid NOT NULL,
    table_id uuid,
    tournament_id uuid,
    club_id uuid,
    played_at timestamp with time zone NOT NULL,
    game_variant text NOT NULL,
    format text DEFAULT 'cash'::text NOT NULL,
    big_blind numeric NOT NULL,
    horse_user_id uuid NOT NULL,
    seat integer,
    net_amount numeric NOT NULL,
    net_bb numeric NOT NULL,
    is_win boolean GENERATED ALWAYS AS ((net_bb > (0)::numeric)) STORED,
    pot_size numeric,
    hole_cards jsonb,
    board jsonb,
    actions jsonb,
    leak_tags text[] DEFAULT '{}'::text[] NOT NULL,
    review_status text DEFAULT 'auto_reviewed'::text NOT NULL,
    review_notes jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT horse_hand_reviews_review_status_check CHECK ((review_status = ANY (ARRAY['auto_reviewed'::text, 'flagged'::text, 'resolved'::text])))
);


