--
-- Name: TABLE horse_hand_reviews; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.horse_hand_reviews IS 'One row per horse per hand with |net| >= 20bb, written by the engine at settlement (server/src/services/HorseHandReview.ts). Exact nets, never reconstructed. Admin UI: smarter.poker/horses/hand-reviews.';


--
-- Name: ca_horse_hand_reviews(uuid, text, text, text, boolean, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_horse_hand_reviews(p_horse uuid DEFAULT NULL::uuid, p_variant text DEFAULT NULL::text, p_format text DEFAULT NULL::text, p_tag text DEFAULT NULL::text, p_win boolean DEFAULT NULL::boolean, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS SETOF public.horse_hand_reviews
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not fn_is_horse_admin() then
    raise exception 'admin only';
  end if;
  return query
    select * from horse_hand_reviews r
    where (p_horse is null or r.horse_user_id = p_horse)
      and (p_variant is null or r.game_variant = p_variant)
      and (p_format is null or r.format = p_format)
      and (p_tag is null or r.leak_tags @> array[p_tag])
      and (p_win is null or r.is_win = p_win)
      and (p_from is null or r.played_at >= p_from)
      and (p_to is null or r.played_at <= p_to)
    order by r.played_at desc
    limit least(greatest(coalesce(p_limit, 100), 1), 500)
    offset greatest(coalesce(p_offset, 0), 0);
end $$;


ALTER FUNCTION public.ca_horse_hand_reviews(p_horse uuid, p_variant text, p_format text, p_tag text, p_win boolean, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) OWNER TO postgres;

