--
-- Name: ca_horse_tag_trends(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_horse_tag_trends(p_days integer DEFAULT 7) RETURNS TABLE(day date, tag text, n bigint, hands bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not fn_is_horse_admin() then
    raise exception 'admin only';
  end if;
  return query
    with d as (
      select rv.played_at::date as dday, count(*) as dhands
      from horse_hand_reviews rv
      where rv.played_at >= (now() at time zone 'utc')::date - least(greatest(coalesce(p_days, 7), 1), 30)
      group by 1
    ),
    t as (
      select rv.played_at::date as dday, u.tag as dtag, count(*) as dn
      from horse_hand_reviews rv, lateral unnest(rv.leak_tags) as u(tag)
      where rv.played_at >= (now() at time zone 'utc')::date - least(greatest(coalesce(p_days, 7), 1), 30)
      group by 1, 2
    )
    select t.dday, t.dtag, t.dn, d.dhands
    from t join d using (dday)
    order by t.dday desc, t.dn desc;
end $$;


ALTER FUNCTION public.ca_horse_tag_trends(p_days integer) OWNER TO postgres;

--
-- Name: ca_horse_tournament_card(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_horse_tournament_card(p_days integer DEFAULT 7) RETURNS TABLE(tournament_type text, variant text, entries bigint, invested numeric, won numeric, roi_pct numeric, itm_pct numeric, avg_finish_pct numeric, horses bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not fn_is_horse_admin() then
    raise exception 'admin only';
  end if;
  return query
    select h.tournament_type, h.variant,
           sum(h.entries)::bigint,
           round(sum(h.invested), 2),
           round(sum(h.won), 2),
           case when sum(h.invested) > 0 then round(100 * (sum(h.won) - sum(h.invested)) / sum(h.invested), 1) end,
           case when sum(h.entries) > 0 then round(100.0 * sum(h.itm_entries) / sum(h.entries), 1) end,
           case when sum(h.entries) > 0 then round(sum(h.finish_pct_sum) / sum(h.entries), 3) end,
           count(distinct h.horse_user_id)::bigint
      from horse_tournament_daily h
     where h.day >= (now() at time zone 'utc')::date - least(greatest(coalesce(p_days, 7), 1), 90)
     group by 1, 2
     order by 3 desc;
end $$;


ALTER FUNCTION public.ca_horse_tournament_card(p_days integer) OWNER TO postgres;

--
-- Name: ca_index_every_seat(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_index_every_seat(p_minutes integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_from     timestamptz;
  v_to       timestamptz;
  v_end      timestamptz := now() - interval '2 minutes';
  v_deadline timestamptz := clock_timestamp() + interval '50 seconds';
  v_hands    bigint := 0;
  v_rows     bigint := 0;
  k int; kr int;
  v_done     boolean := false;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('ca_index_every_seat')) THEN
    RETURN jsonb_build_object('skipped', 'locked');
  END IF;

  SELECT cursor_at, done INTO v_from, v_done FROM public.ca_idx_every_seat_state WHERE id FOR UPDATE;
  IF v_done THEN RETURN jsonb_build_object('done', true, 'cursor_at', v_from); END IF;

  LOOP
    EXIT WHEN clock_timestamp() >= v_deadline OR v_from >= v_end;
    v_to := least(v_from + make_interval(mins => greatest(p_minutes, 1)), v_end);
    WITH src AS (
      SELECT h.id, h.created_at, h.players FROM public.hand_history h
      WHERE h.created_at >= v_from AND h.created_at < v_to
    ), expanded AS (
      SELECT DISTINCT ((pl->>'userId')::uuid) AS user_id, s.created_at, s.id AS hand_id
      FROM src s, jsonb_array_elements(coalesce(s.players, '[]'::jsonb)) pl
      WHERE pl->>'userId' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        AND NOT pl->>'userId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    ), ins AS (
      INSERT INTO public.ca_hand_player_idx (user_id, created_at, hand_id)
      SELECT user_id, created_at, hand_id FROM expanded
      ON CONFLICT DO NOTHING RETURNING 1
    )
    SELECT (SELECT count(*) FROM src)::int, (SELECT count(*) FROM ins)::int INTO k, kr;
    v_hands := v_hands + coalesce(k, 0);
    v_rows  := v_rows + coalesce(kr, 0);
    v_from  := v_to;
  END LOOP;

  v_done := v_from >= v_end;

  UPDATE public.ca_idx_every_seat_state
  SET cursor_at = v_from, hands_seen = hands_seen + v_hands,
      rows_added = rows_added + v_rows, done = v_done, updated_at = now()
  WHERE id;

  -- The live trigger now indexes every seat, so once the cursor reaches the
  -- present there is nothing left for this to do.
  IF v_done AND EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'ca-stats-idx-every-seat-1m') THEN
    PERFORM cron.unschedule('ca-stats-idx-every-seat-1m');
  END IF;

  RETURN jsonb_build_object('cursor_at', v_from, 'hands_seen', v_hands, 'rows_added', v_rows, 'done', v_done);
END;
$_$;


ALTER FUNCTION public.ca_index_every_seat(p_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION ca_index_every_seat(p_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_index_every_seat(p_minutes integer) IS 'One-off backfill: index rows in ca_hand_player_idx for seats whose uuid-shaped id the old RFC 4122 regex skipped (synthetic horse ids). Walks retained hand_history forward from ca_idx_every_seat_state.cursor_at in p_minutes windows under a 50 s deadline; unschedules its own cron when it reaches the present. Service role only.';


--
-- Name: ca_log_ddl_drop(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_log_ddl_drop() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.is_temporary OR obj.schema_name = 'pg_temp'
       OR obj.object_identity LIKE 'pg_temp.%' THEN
      CONTINUE;
    END IF;
    INSERT INTO public.ca_ddl_events
      (command_tag, object_type, object_identity, schema_name,
       triggers_pgrst_reload, application_name, query_snippet)
    VALUES
      ('DROP ' || upper(coalesce(obj.object_type, 'OBJECT')),
       obj.object_type, obj.object_identity, obj.schema_name,
       obj.object_type IN (
         'schema','table','foreign table','view','materialized view',
         'function','trigger','type','rule'
       ) AND obj.is_temporary IS FALSE,
       current_setting('application_name', true),
       left(current_query(), 300));
  END LOOP;
EXCEPTION WHEN OTHERS THEN
  NULL;
END;
$$;


ALTER FUNCTION public.ca_log_ddl_drop() OWNER TO postgres;

--
-- Name: ca_log_ddl_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_log_ddl_event() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.schema_name = 'pg_temp' OR cmd.object_identity LIKE 'pg_temp.%' THEN
      CONTINUE;
    END IF;
    INSERT INTO public.ca_ddl_events
      (command_tag, object_type, object_identity, schema_name,
       triggers_pgrst_reload, application_name, query_snippet)
    VALUES
      (cmd.command_tag, cmd.object_type, cmd.object_identity, cmd.schema_name,
       cmd.command_tag IN (
         'CREATE SCHEMA','ALTER SCHEMA','CREATE TABLE','CREATE TABLE AS',
         'SELECT INTO','ALTER TABLE','CREATE FOREIGN TABLE',
         'ALTER FOREIGN TABLE','CREATE VIEW','ALTER VIEW',
         'CREATE MATERIALIZED VIEW','ALTER MATERIALIZED VIEW',
         'CREATE FUNCTION','ALTER FUNCTION','CREATE TRIGGER','CREATE TYPE',
         'ALTER TYPE','CREATE RULE','COMMENT'
       ) AND cmd.schema_name IS DISTINCT FROM 'pg_temp',
       current_setting('application_name', true),
       left(current_query(), 300));
  END LOOP;
EXCEPTION WHEN OTHERS THEN
  NULL;
END;
$$;


ALTER FUNCTION public.ca_log_ddl_event() OWNER TO postgres;

--
-- Name: ca_player_class_hands(uuid, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_class_hands(p_user uuid, p_hand_class text, p_position text DEFAULT NULL::text, p_variant text DEFAULT NULL::text, p_days integer DEFAULT NULL::integer, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_cap    int := least(greatest(coalesce(p_limit, 20), 1), 100);
BEGIN
  PERFORM public.ca_assert_self(p_user);

  IF p_hand_class IS NULL OR btrim(p_hand_class) = '' THEN
    RETURN jsonb_build_object('hands', '[]'::jsonb, 'hand_class', NULL);
  END IF;

  SELECT jsonb_build_object(
    'hand_class', p_hand_class,
    'hands', coalesce((
      SELECT jsonb_agg(h ORDER BY (h->>'played_at') DESC)
      FROM (
        SELECT jsonb_build_object(
          'hand_id',    f.hand_id,
          'played_at',  f.played_at,
          'position',   f.position,
          'net',        round(f.net, 2),
          'net_bb',     round(f.net_bb, 2),
          'big_blind',  f.big_blind,
          'variant',    f.game_variant,
          'was_all_in', f.was_all_in,
          'showdown',   f.went_to_showdown,
          'won',        (f.net > 0),
          'hole_cards', f.hole_cards
        ) AS h
        FROM public.ca_hand_facts f
        WHERE f.user_id = p_user
          AND f.hand_class = p_hand_class
          AND (p_position IS NULL OR f.position = p_position)
          AND (p_variant  IS NULL OR f.game_variant = p_variant)
          AND (p_days     IS NULL OR f.played_at >= now() - make_interval(days => p_days))
        ORDER BY f.played_at DESC
        LIMIT v_cap
      ) sub
    ), '[]'::jsonb),
    'generated_at', now()
  ) INTO v_result;

  RETURN v_result;
END $$;


ALTER FUNCTION public.ca_player_class_hands(p_user uuid, p_hand_class text, p_position text, p_variant text, p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: ca_player_ev_curve(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_ev_curve(p_user uuid, p_days integer DEFAULT NULL::integer, p_limit integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_cap    int := least(greatest(coalesce(p_limit, 5000), 100), 20000);
BEGIN
  PERFORM public.ca_assert_self(p_user);

  WITH picked AS MATERIALIZED (
    SELECT f.played_at, f.net_bb, f.ev_net_bb, f.was_all_in, f.all_in_equity
    FROM public.ca_hand_facts f
    WHERE f.user_id = p_user
      AND f.went_to_showdown = true
      AND f.game_variant NOT IN ('mtt', 'sit_and_go')
      AND (p_days IS NULL OR f.played_at >= now() - make_interval(days => p_days))
    ORDER BY f.played_at DESC
    LIMIT v_cap
  ),
  accum AS MATERIALIZED (
    SELECT
      row_number() OVER w AS i,
      played_at AS at,
      net_bb,
      ev_net_bb,
      sum(net_bb) OVER w AS cum_net_bb,
      sum(ev_net_bb) OVER w AS cum_ev_net_bb,
      sum(net_bb - ev_net_bb) OVER w AS luck_bb,
      -- CARRY was_all_in THROUGH (2026-08-24). `agg` counts
      -- `FILTER (WHERE was_all_in = true)` but selects FROM accum, and accum
      -- projected only played_at, net_bb, ev_net_bb and the running sums - it
      -- dropped was_all_in on the floor. So every single call raised
      -- 42703 column "was_all_in" does not exist: the EV curve was broken 100%
      -- of the time, for every player, not merely wrong at an edge.
      was_all_in
    FROM picked
    WINDOW w AS (ORDER BY played_at ASC)
  ),
  agg AS MATERIALIZED (
    SELECT
      count(*) AS hands,
      count(*) FILTER (WHERE was_all_in = true) AS all_in_hands,
      sum(net_bb) AS net_bb,
      sum(ev_net_bb) AS ev_net_bb,
      sum(net_bb - ev_net_bb) AS luck_bb,
      max(net_bb - ev_net_bb) AS biggest_suckout,
      min(net_bb - ev_net_bb) AS biggest_beat,
      CASE WHEN count(*) = 0 THEN 0
           ELSE (sum(net_bb - ev_net_bb) / count(*)) * 100 END AS luck_bb_per_100,
      (count(*) = v_cap) AS capped
    FROM accum
  )
  SELECT jsonb_build_object(
    'points', coalesce((
      SELECT jsonb_agg(x) FROM (
        SELECT i, at, net_bb, ev_net_bb, cum_net_bb, cum_ev_net_bb
        FROM accum
      ) x
    ), '[]'::jsonb),
    'summary', (
      SELECT jsonb_build_object(
        'hands', hands,
        'all_in_hands', all_in_hands,
        'net_bb', round(coalesce(net_bb, 0), 2),
        'ev_net_bb', round(coalesce(ev_net_bb, 0), 2),
        'luck_bb', round(coalesce(luck_bb, 0), 2),
        'luck_bb_per_100', round(coalesce(luck_bb_per_100, 0), 2),
        'biggest_suckout', round(coalesce(biggest_suckout, 0), 2),
        'biggest_beat', round(coalesce(biggest_beat, 0), 2),
        'capped', capped
      )
      FROM agg
    ),
    'generated_at', now()
  ) INTO v_result;

  RETURN v_result;
END $$;


ALTER FUNCTION public.ca_player_ev_curve(p_user uuid, p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: ca_player_hand_grid(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_hand_grid(p_user uuid, p_position text DEFAULT NULL::text, p_variant text DEFAULT NULL::text, p_days integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM public.ca_assert_self(p_user);

  WITH picked AS MATERIALIZED (
    SELECT f.hand_class, f.vpip, f.net_bb, f.ev_net_bb, f.net
    FROM public.ca_hand_facts f
    WHERE f.user_id = p_user
      AND f.hand_class IS NOT NULL
      AND (p_position IS NULL OR f.position = p_position)
      AND (p_variant  IS NULL OR f.game_variant = p_variant)
      AND (p_days     IS NULL OR f.played_at >= now() - make_interval(days => p_days))
  ),
  grouped AS MATERIALIZED (
    SELECT
      hand_class,
      count(*) AS hands,
      count(*) FILTER (WHERE vpip) AS hands_vpip,
      count(*) FILTER (WHERE net > 0) AS hands_won,
      (count(*) FILTER (WHERE vpip)::numeric / count(*)) AS vpip_pct,
      round(sum(net_bb), 2) AS net_bb,
      round(sum(ev_net_bb), 2) AS ev_net_bb,
      round((sum(net_bb) / nullif(count(*), 0)) * 100, 2) AS bb100
    FROM picked
    GROUP BY hand_class
  )
  SELECT jsonb_build_object(
    'cells', coalesce((
      SELECT jsonb_agg(x) FROM (
        SELECT hand_class, hands, hands_vpip, hands_won, vpip_pct, net_bb, ev_net_bb, bb100
        FROM grouped
      ) x
    ), '[]'::jsonb),
    'totals', jsonb_build_object(
      'hands', (SELECT coalesce(sum(hands), 0) FROM grouped),
      'classes_seen', (SELECT count(*) FROM grouped)
    ),
    'filters', jsonb_build_object(
      'position', p_position,
      'variant',  p_variant,
      'days',     p_days
    ),
    'generated_at', now()
  ) INTO v_result;

  RETURN v_result;
END $$;


ALTER FUNCTION public.ca_player_hand_grid(p_user uuid, p_position text, p_variant text, p_days integer) OWNER TO postgres;

--
-- Name: ca_player_hand_rake_share(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_hand_rake_share(p_hand_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_rr record;
  v_ra record;
BEGIN
  IF v_uid IS NULL OR p_hand_id IS NULL THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT rake_amount, bbj_contribution, pot_size, rake_method, player_contributions
  INTO v_rr
  FROM public.rake_records
  WHERE hand_id = p_hand_id
  ORDER BY created_at
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT eligible_contribution, returned_uncalled, contribution_weight,
         weighted_rake_credit, bbj_attributed_contribution
  INTO v_ra
  FROM public.rake_attributions
  WHERE hand_id = p_hand_id AND player_id = v_uid;

  IF NOT FOUND THEN
    IF v_rr.player_contributions ? v_uid::text THEN
      RETURN (
        SELECT jsonb_build_object(
          'found', true,
          'hand_id', p_hand_id,
          'rake_method', coalesce(v_rr.rake_method, 'DEALT_EQUAL'),
          'pot_size', v_rr.pot_size,
          'hand_rake', round(v_rr.rake_amount, 2),
          'hand_bbj', round(coalesce(v_rr.bbj_contribution, 0), 2),
          'your_contribution', round((v_rr.player_contributions->>v_uid::text)::numeric, 2),
          'your_returned_uncalled', 0,
          'your_share_pct', round(a.weight * 100, 2),
          'your_rake', round(a.credit, 2),
          'your_bbj', 0,
          'from_ledger', false
        )
        FROM public.fn_allocate_rake_credits(
          v_rr.rake_amount,
          v_rr.player_contributions,
          coalesce(v_rr.rake_method, 'DEALT_EQUAL')
        ) a
        WHERE a.user_id = v_uid
      );
    END IF;
    RETURN jsonb_build_object('found', false);
  END IF;

  RETURN jsonb_build_object(
    'found', true,
    'hand_id', p_hand_id,
    'rake_method', coalesce(v_rr.rake_method, 'DEALT_EQUAL'),
    'pot_size', v_rr.pot_size,
    'hand_rake', round(v_rr.rake_amount, 2),
    'hand_bbj', round(coalesce(v_rr.bbj_contribution, 0), 2),
    'your_contribution', round(coalesce(v_ra.eligible_contribution, 0), 2),
    'your_returned_uncalled', round(coalesce(v_ra.returned_uncalled, 0), 2),
    'your_share_pct', round(coalesce(v_ra.contribution_weight, 0) * 100, 2),
    'your_rake', round(coalesce(v_ra.weighted_rake_credit, 0), 2),
    'your_bbj', round(coalesce(v_ra.bbj_attributed_contribution, 0), 2),
    'from_ledger', true
  );
END;
$$;


ALTER FUNCTION public.ca_player_hand_rake_share(p_hand_id uuid) OWNER TO postgres;

--
-- Name: ca_player_hands(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_hands(p_user uuid, p_mode text DEFAULT 'recent'::text, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_window constant int := 750;   -- same analysis window as ca_player_stats_full
  v_limit  int := LEAST(GREATEST(coalesce(p_limit, 25), 1), 100);
  v_self   boolean := (auth.uid() IS NOT NULL AND auth.uid() = p_user);
  v_mode   text := lower(coalesce(p_mode, 'recent'));
BEGIN
  IF v_mode NOT IN ('recent', 'biggest_won', 'biggest_lost') THEN
    v_mode := 'recent';
  END IF;

RETURN (
WITH mine AS (
  SELECT s.hand_id, s.created_at, s.tournament_id, s.game_variant AS variant,
         s.big_blind, s.seat_position AS position, s.is_winner, s.n_players,
         coalesce(x.returned, s.won_amt) AS won_amt,
         coalesce(x.net, s.profit) AS profit
  FROM ca_hand_player_stat s
  LEFT JOIN ca_hand_facts x ON x.hand_id = s.hand_id AND x.user_id = s.user_id
  WHERE s.user_id = p_user
    -- The "biggest" modes rank chips, and tournament chips are not money: a
    -- -71,330 in a freeroll outranked every cash hand the player ever lost.
    -- Cash only for those; "recent" shows everything.
    AND (v_mode = 'recent' OR s.is_cash)
  ORDER BY s.created_at DESC
  LIMIT CASE WHEN v_mode = 'recent' THEN v_limit ELSE c_window END
),
ranked AS (
  SELECT * FROM mine
  ORDER BY CASE WHEN v_mode = 'biggest_won'  THEN profit END DESC NULLS LAST,
           CASE WHEN v_mode = 'biggest_lost' THEN profit END ASC  NULLS LAST,
           CASE WHEN v_mode = 'recent'       THEN created_at END DESC NULLS LAST
  LIMIT v_limit
)
SELECT coalesce(jsonb_agg(jsonb_build_object(
  'id', r.hand_id,
  'played_at', r.created_at,
  'variant', r.variant,
  'big_blind', r.big_blind,
  'is_tournament', (r.tournament_id IS NOT NULL),
  'position', NULLIF(r.position, 'UNK'),
  'pot_size', round(coalesce(h.pot_size, 0)::numeric, 2),
  'won', round(r.won_amt, 2),
  'profit', round(r.profit, 2),
  'is_winner', r.is_winner,
  'players', coalesce(r.n_players, (SELECT count(*) FROM jsonb_array_elements(coalesce(h.players, '[]'::jsonb)))),
  'board', coalesce(h.board, to_jsonb(h.community_cards)),
  -- Own cards only. Never expose another player's hole cards.
  'hole_cards', CASE WHEN v_self THEN h.hole_cards -> p_user::text ELSE NULL END
) ORDER BY CASE WHEN v_mode = 'biggest_won'  THEN r.profit END DESC NULLS LAST,
           CASE WHEN v_mode = 'biggest_lost' THEN r.profit END ASC  NULLS LAST,
           CASE WHEN v_mode = 'recent'       THEN r.created_at END DESC NULLS LAST),
  '[]'::jsonb)
FROM ranked r
LEFT JOIN hand_history h ON h.id = r.hand_id
);
END;
$$;


ALTER FUNCTION public.ca_player_hands(p_user uuid, p_mode text, p_limit integer) OWNER TO postgres;

--
-- Name: ca_player_hands_v2(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_hands_v2(p_user uuid, p_mode text DEFAULT 'recent'::text, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.ca_assert_self(p_user);
  RETURN public.ca_player_hands(p_user, p_mode, p_limit);
END;
$$;


ALTER FUNCTION public.ca_player_hands_v2(p_user uuid, p_mode text, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION ca_player_hands_v2(p_user uuid, p_mode text, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_player_hands_v2(p_user uuid, p_mode text, p_limit integer) IS 'Owner-only bounded notable-hand evidence. Reads indexed hand ids only and does not scan the live raw-history tail.';


--
-- Name: ca_player_nemesis(uuid, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_nemesis(p_user uuid, p_days integer DEFAULT NULL::integer, p_min_hands integer DEFAULT 25, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM public.ca_assert_self(p_user);

  WITH flows AS MATERIALIZED (
    SELECT t.loser_id  AS opponent_id,  t.amount AS delta
    FROM public.ca_hand_transfers t
    WHERE t.winner_id = p_user
      AND (p_days IS NULL OR t.played_at >= now() - make_interval(days => p_days))
    UNION ALL
    SELECT t.winner_id AS opponent_id, -t.amount AS delta
    FROM public.ca_hand_transfers t
    WHERE t.loser_id = p_user
      AND (p_days IS NULL OR t.played_at >= now() - make_interval(days => p_days))
  ),
  netted AS MATERIALIZED (
    SELECT opponent_id, sum(delta) AS net_chips
    FROM flows
    GROUP BY opponent_id
  ),
  shared AS MATERIALIZED (
    SELECT o.opponent_id, count(*) AS hands_together, max(f.played_at) AS last_played_at
    FROM public.ca_hand_facts f
    CROSS JOIN LATERAL unnest(coalesce(f.opponent_ids, '{}'::uuid[])) AS o(opponent_id)
    WHERE f.user_id = p_user
      AND (p_days IS NULL OR f.played_at >= now() - make_interval(days => p_days))
    GROUP BY o.opponent_id
  ),
  joined AS MATERIALIZED (
    SELECT
      n.opponent_id,
      n.net_chips,
      coalesce(s.hands_together, 0) AS hands_together,
      s.last_played_at,
      pr.username,
      pr.avatar_url
    FROM netted n
    LEFT JOIN shared s   ON s.opponent_id = n.opponent_id
    LEFT JOIN public.profiles pr ON pr.id = n.opponent_id
    WHERE coalesce(s.hands_together, 0) >= p_min_hands
  )
  SELECT jsonb_build_object(
    'nemesis', (
      SELECT jsonb_build_object(
        'opponent_id', opponent_id, 'username', username, 'avatar_url', avatar_url,
        'net_chips', round(net_chips, 2), 'hands_together', hands_together,
        'last_played_at', last_played_at)
      FROM joined WHERE net_chips < 0 ORDER BY net_chips ASC LIMIT 1
    ),
    'target', (
      SELECT jsonb_build_object(
        'opponent_id', opponent_id, 'username', username, 'avatar_url', avatar_url,
        'net_chips', round(net_chips, 2), 'hands_together', hands_together,
        'last_played_at', last_played_at)
      FROM joined WHERE net_chips > 0 ORDER BY net_chips DESC LIMIT 1
    ),
    'worst', coalesce((
      SELECT jsonb_agg(x) FROM (
        SELECT opponent_id, username, avatar_url, round(net_chips, 2) AS net_chips,
               hands_together, last_played_at
        FROM joined WHERE net_chips < 0 ORDER BY net_chips ASC LIMIT p_limit
      ) x), '[]'::jsonb),
    'best', coalesce((
      SELECT jsonb_agg(x) FROM (
        SELECT opponent_id, username, avatar_url, round(net_chips, 2) AS net_chips,
               hands_together, last_played_at
        FROM joined WHERE net_chips > 0 ORDER BY net_chips DESC LIMIT p_limit
      ) x), '[]'::jsonb),
    'min_hands', p_min_hands,
    'opponents_qualified', (SELECT count(*) FROM joined),
    'generated_at', now()
  ) INTO v_result;

  RETURN v_result;
END $$;


ALTER FUNCTION public.ca_player_nemesis(p_user uuid, p_days integer, p_min_hands integer, p_limit integer) OWNER TO postgres;

--
-- Name: ca_player_rake_stats(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_rake_stats(p_user uuid DEFAULT NULL::uuid, p_days integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_since timestamptz;
  v_hands bigint := 0;
  v_raked_hands bigint := 0;
  v_rake numeric := 0;
  v_bb numeric := 0;
  v_first timestamptz;
  v_last timestamptz;
BEGIN
  IF public.fn_caller_is_engine() THEN
    v_uid := coalesce(p_user, auth.uid());
  ELSE
    v_uid := auth.uid();
  END IF;
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object(
      'hands', 0, 'raked_hands', 0, 'rake_paid', 0,
      'rake_per_100', 0, 'rake_in_bb', 0, 'days', p_days
    );
  END IF;

  v_since := CASE WHEN p_days IS NULL THEN '-infinity'::timestamptz
                  ELSE now() - make_interval(days => greatest(p_days, 1)) END;

  SELECT count(*),
         count(*) FILTER (WHERE coalesce(f.rake_paid, 0) > 0),
         coalesce(sum(f.rake_paid), 0),
         coalesce(sum(CASE WHEN f.big_blind > 0 THEN f.rake_paid / f.big_blind ELSE 0 END), 0),
         min(f.played_at),
         max(f.played_at)
  INTO v_hands, v_raked_hands, v_rake, v_bb, v_first, v_last
  FROM public.ca_hand_facts f
  WHERE f.user_id = v_uid
    AND f.played_at >= v_since
    AND f.tournament_id IS NULL;

  RETURN jsonb_build_object(
    'hands', v_hands,
    'raked_hands', v_raked_hands,
    'rake_paid', round(v_rake, 2),
    'rake_per_100', CASE WHEN v_hands > 0 THEN round(v_rake * 100.0 / v_hands, 2) ELSE 0 END,
    'rake_in_bb', round(v_bb, 2),
    'bb_per_100', CASE WHEN v_hands > 0 THEN round(v_bb * 100.0 / v_hands, 2) ELSE 0 END,
    'avg_rake_per_raked_hand',
      CASE WHEN v_raked_hands > 0 THEN round(v_rake / v_raked_hands, 4) ELSE 0 END,
    'first_hand_at', v_first,
    'last_hand_at', v_last,
    'days', p_days
  );
END;
$$;


ALTER FUNCTION public.ca_player_rake_stats(p_user uuid, p_days integer) OWNER TO postgres;

--
-- Name: ca_player_stats_full(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_full(p_user uuid, p_days integer DEFAULT NULL::integer, p_tz text DEFAULT 'UTC'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_cap constant int := 750;
  v_since timestamptz := CASE WHEN p_days IS NULL OR p_days <= 0
                              THEN NULL ELSE now() - make_interval(days => p_days) END;
  v_life_hands int := 0;
  v_life_first timestamptz;
  v_life_last  timestamptz;
  -- The player's zone for DAY buckets (phase 3). The analysis window itself
  -- is rolling (now() minus p_days), so it never needed a zone; the daily
  -- series and the "which days" wording did, and were UTC days for everyone.
  v_tz text := 'UTC';
BEGIN
  -- An unknown zone name falls back to UTC rather than failing the page.
  BEGIN
    IF p_tz IS NOT NULL AND length(p_tz) BETWEEN 1 AND 64 THEN
      PERFORM now() AT TIME ZONE p_tz;
      v_tz := p_tz;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_tz := 'UTC';
  END;
  SELECT count(*)::int, min(created_at), max(created_at)
  INTO v_life_hands, v_life_first, v_life_last
  FROM ca_hand_player_idx WHERE user_id = p_user;

RETURN (
WITH scored AS MATERIALIZED (
  -- The most recent c_cap rows for this player, whoever wrote them (the
  -- hand_history trigger, live, or the forward roll behind it). Where the
  -- engine wrote an exact settlement row (ca_hand_facts) the money columns
  -- come from it; the reconstruction is the fallback, and `exact` says which.
  SELECT s.created_at, s.is_cash, s.tournament_id, s.game_variant, s.big_blind,
         s.seat_position AS position,
         coalesce(x.returned, s.won_amt) AS won_amt,
         s.is_winner,
         coalesce(x.invested, s.invested_actions + s.my_blind) AS invested,
         s.aggro_cnt, s.call_cnt, s.vpip, s.pfr, s.three_bet,
         s.three_bet_opp, s.faced_three_bet, s.folded_to_three_bet, s.cbet_opp,
         s.cbet_made, s.showdown, s.hand_secs,
         coalesce(x.net, s.profit) AS profit,
         (x.hand_id IS NOT NULL) AS exact
  FROM ca_hand_player_stat s
  LEFT JOIN ca_hand_facts x ON x.hand_id = s.hand_id AND x.user_id = s.user_id
  WHERE s.user_id = p_user
    AND (v_since IS NULL OR s.created_at >= v_since)
  ORDER BY s.created_at DESC
  LIMIT c_cap
),
totals AS (
  SELECT
    count(*)::int AS hands,
    count(*) FILTER (WHERE is_cash)::int AS cash_hands,
    count(*) FILTER (WHERE is_cash AND exact)::int AS exact_cash_hands,
    count(*) FILTER (WHERE NOT is_cash)::int AS tourney_hands,
    count(DISTINCT tournament_id) FILTER (WHERE NOT is_cash)::int AS tournaments_with_hands,
    count(*) FILTER (WHERE is_winner)::int AS hands_won,
    count(*) FILTER (WHERE vpip)::int AS vpip_hands,
    count(*) FILTER (WHERE pfr)::int AS pfr_hands,
    count(*) FILTER (WHERE three_bet)::int AS three_bet_hands,
    count(*) FILTER (WHERE three_bet_opp)::int AS three_bet_opps,
    count(*) FILTER (WHERE faced_three_bet)::int AS faced_three_bet_hands,
    count(*) FILTER (WHERE folded_to_three_bet)::int AS folded_to_three_bet_hands,
    count(*) FILTER (WHERE cbet_opp)::int AS cbet_opps,
    count(*) FILTER (WHERE cbet_made)::int AS cbet_made_hands,
    coalesce(sum(aggro_cnt), 0)::int AS aggro_actions,
    coalesce(sum(call_cnt), 0)::int AS call_actions,
    count(*) FILTER (WHERE showdown)::int AS showdowns,
    count(*) FILTER (WHERE showdown AND is_winner)::int AS showdowns_won,
    coalesce(sum(profit) FILTER (WHERE is_cash), 0) AS cash_profit,
    coalesce(sum(won_amt) FILTER (WHERE is_cash), 0) AS cash_won,
    coalesce(sum(invested) FILTER (WHERE is_cash), 0) AS cash_invested,
    coalesce(max(won_amt) FILTER (WHERE is_cash), 0) AS biggest_pot_won,
    coalesce(min(profit) FILTER (WHERE is_cash), 0) AS biggest_hand_loss,
    coalesce(sum(profit / NULLIF(big_blind, 0)) FILTER (WHERE is_cash), 0) AS cash_bb_profit,
    coalesce(sum(hand_secs), 0) AS total_secs,
    min(created_at) AS first_hand_at,
    max(created_at) AS last_hand_at
  FROM scored
),
daily AS (
  SELECT date(created_at AT TIME ZONE v_tz) AS d, count(*)::int AS hands,
         round(coalesce(sum(profit), 0), 2) AS profit
  FROM scored WHERE is_cash AND created_at >= now() - interval '90 days'
  GROUP BY 1 ORDER BY 1
),
sess_marked AS (
  SELECT *, CASE WHEN created_at - lag(created_at) OVER (ORDER BY created_at) > interval '45 minutes'
                 OR lag(created_at) OVER (ORDER BY created_at) IS NULL
            THEN 1 ELSE 0 END AS new_sess
  FROM scored WHERE is_cash
),
sess_grouped AS (
  SELECT *, sum(new_sess) OVER (ORDER BY created_at) AS sess_no FROM sess_marked
),
sessions_agg AS (
  SELECT sess_no, min(created_at) AS started, max(created_at) AS ended,
         count(*)::int AS hands,
         round(coalesce(sum(profit), 0), 2) AS profit,
         round(coalesce(sum(invested), 0), 2) AS invested
  FROM sess_grouped GROUP BY sess_no ORDER BY sess_no DESC LIMIT 50
),
positions AS (
  SELECT position, count(*)::int AS hands_played,
         count(*) FILTER (WHERE vpip)::int AS vpip_count,
         count(*) FILTER (WHERE pfr)::int AS pfr_count,
         count(*) FILTER (WHERE three_bet)::int AS three_bet_count,
         count(*) FILTER (WHERE three_bet_opp)::int AS three_bet_opps,
         count(*) FILTER (WHERE is_winner)::int AS hands_won,
         round(coalesce(sum(profit) FILTER (WHERE is_cash), 0), 2) AS total_profit,
         CASE WHEN count(*) FILTER (WHERE is_cash) > 0
              THEN round(coalesce(sum(profit / NULLIF(big_blind, 0)) FILTER (WHERE is_cash), 0)
                   / count(*) FILTER (WHERE is_cash) * 100, 2)
              ELSE 0 END AS bb100
  FROM scored WHERE position <> 'UNK' GROUP BY position
),
stakes AS (
  SELECT big_blind, count(*)::int AS hands,
         count(*) FILTER (WHERE is_winner)::int AS hands_won,
         round(coalesce(sum(profit), 0), 2) AS profit,
         CASE WHEN count(*) > 0
              THEN round(coalesce(sum(profit / NULLIF(big_blind, 0)), 0) / count(*) * 100, 2)
              ELSE 0 END AS bb100
  FROM scored WHERE is_cash AND big_blind > 0
  GROUP BY big_blind ORDER BY big_blind DESC
),
variants AS (
  SELECT game_variant, count(*)::int AS hands,
         count(*) FILTER (WHERE is_winner)::int AS hands_won,
         round(coalesce(sum(profit) FILTER (WHERE is_cash), 0), 2) AS profit,
         CASE WHEN count(*) FILTER (WHERE is_cash) > 0
              THEN round(coalesce(sum(profit / NULLIF(big_blind, 0)) FILTER (WHERE is_cash), 0)
                   / count(*) FILTER (WHERE is_cash) * 100, 2)
              ELSE 0 END AS bb100
  FROM scored GROUP BY game_variant ORDER BY count(*) DESC
),
-- The tournament block honours the analysis window like everything else on
-- the page. It used to be lifetime under a "7 Days" label.
tourn_rows AS (
  SELECT tp.*, t.buy_in_amount, t.buy_in_fee, t.rebuy_cost, t.addon_cost,
         t.name, t.start_time, t.variant, t.is_mystery_bounty
  FROM tournament_players tp
  LEFT JOIN tournaments t ON t.id = tp.tournament_id
  WHERE tp.user_id = p_user
    AND (v_since IS NULL OR coalesce(t.start_time, tp.registered_at, now()) >= v_since)
),
tourn AS (
  SELECT count(*)::int AS entries,
         count(*) FILTER (WHERE coalesce(tp.prize, 0) > 0)::int AS cashes,
         count(*) FILTER (WHERE tp.position = 1 OR tp.status = 'winner')::int AS wins,
         min(tp.position) FILTER (WHERE tp.position IS NOT NULL) AS best_finish,
         coalesce(sum(coalesce(tp.buy_in_amount, 0) + coalesce(tp.buy_in_fee, 0)
           + coalesce(tp.rebuys, 0) * coalesce(tp.rebuy_cost, 0)
           + CASE WHEN tp.add_on THEN coalesce(tp.addon_cost, 0) ELSE 0 END), 0) AS total_buyins,
         coalesce(sum(coalesce(tp.prize, 0) + coalesce(tp.bounty_winnings, 0)), 0) AS total_winnings,
         coalesce(sum(coalesce(tp.prize, 0)), 0) AS total_prizes,
         coalesce(sum(coalesce(tp.bounty_winnings, 0)), 0) AS total_bounty_winnings,
         coalesce(sum(coalesce(tp.bounties_collected, 0)), 0)::int AS total_bounties
  FROM tourn_rows tp
),
tourn_recent AS (
  SELECT tp.tournament_id, tp.name, tp.start_time, tp.variant,
         coalesce(tp.is_mystery_bounty, false) AS is_mystery_bounty,
         tp.position AS finish_rank, tp.status,
         coalesce(tp.prize, 0) AS prize,
         coalesce(tp.bounty_winnings, 0) AS bounty_winnings,
         coalesce(tp.bounties_collected, 0)::int AS bounties,
         coalesce(tp.prize, 0) + coalesce(tp.bounty_winnings, 0) AS total_won,
         coalesce(tp.buy_in_amount, 0) + coalesce(tp.buy_in_fee, 0)
           + coalesce(tp.rebuys, 0) * coalesce(tp.rebuy_cost, 0)
           + CASE WHEN tp.add_on THEN coalesce(tp.addon_cost, 0) ELSE 0 END AS buyin
  FROM tourn_rows tp
  WHERE tp.tournament_id IS NOT NULL
  ORDER BY tp.start_time DESC NULLS LAST LIMIT 25
)
SELECT jsonb_build_object(
  'generated_at', now(),
  'window_days', p_days,
  'window_tz', v_tz,
  'lifetime', jsonb_build_object(
    'hands', v_life_hands,
    'first_hand_at', v_life_first,
    'last_hand_at', v_life_last,
    'indexed_complete', (SELECT backfill_complete FROM ca_hand_player_idx_state WHERE id)
  ),
  'user_id', p_user,
  'overall', (SELECT jsonb_build_object(
    'total_hands', hands,
    'cash_hands', cash_hands,
    'exact_cash_hands', exact_cash_hands,
    'tourney_hands', tourney_hands,
    'tournaments_with_hands', tournaments_with_hands,
    'hands_won', hands_won,
    'hands_lost', hands - hands_won,
    'vpip', CASE WHEN hands > 0 THEN round(vpip_hands::numeric / hands, 4) ELSE 0 END,
    'pfr', CASE WHEN hands > 0 THEN round(pfr_hands::numeric / hands, 4) ELSE 0 END,
    'three_bet_percent', CASE WHEN three_bet_opps > 0
        THEN round(three_bet_hands::numeric / three_bet_opps, 4) ELSE 0 END,
    'fold_to_three_bet', CASE WHEN faced_three_bet_hands > 0
        THEN round(folded_to_three_bet_hands::numeric / faced_three_bet_hands, 4) ELSE 0 END,
    'cbet_flop', CASE WHEN cbet_opps > 0
        THEN round(cbet_made_hands::numeric / cbet_opps, 4) ELSE 0 END,
    'aggression_factor', CASE WHEN call_actions > 0
        THEN round(aggro_actions::numeric / call_actions, 2) ELSE aggro_actions END,
    'showdowns_total', showdowns,
    'showdowns_won', showdowns_won,
    'wtsd', CASE WHEN hands > 0 THEN round(showdowns::numeric / hands, 4) ELSE 0 END,
    'total_profit', round(cash_profit, 2),
    'total_winnings', round(cash_won, 2),
    'total_invested', round(cash_invested, 2),
    'biggest_pot_won', round(biggest_pot_won, 2),
    'biggest_hand_loss', round(biggest_hand_loss, 2),
    'bb_per_100', CASE WHEN cash_hands > 0
        THEN round(cash_bb_profit / cash_hands * 100, 2) ELSE 0 END,
    'hours_played', round(total_secs / 3600.0, 2),
    'hand_cap', c_cap,
    'hands_capped', (hands >= c_cap),
    'first_hand_at', first_hand_at,
    'last_hand_at', last_hand_at
  ) FROM totals),
  'daily', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'date', d, 'hands', hands, 'profit', profit) ORDER BY d) FROM daily), '[]'::jsonb),
  'sessions', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id', sess_no, 'date', started, 'ended', ended,
      'duration_minutes', GREATEST(1, round(EXTRACT(epoch FROM (ended - started)) / 60)::int),
      'hands_played', hands, 'buy_in', invested,
      'cash_out', round(invested + profit, 2),
      'profit_loss', profit) ORDER BY sess_no DESC) FROM sessions_agg), '[]'::jsonb),
  'positions', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'position', position, 'hands_played', hands_played, 'vpip_count', vpip_count,
      'pfr_count', pfr_count, 'three_bet_count', three_bet_count,
      'three_bet_opps', three_bet_opps,
      'hands_won', hands_won, 'total_profit', total_profit,
      'bb100', bb100)) FROM positions), '[]'::jsonb),
  'variants', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'variant', game_variant, 'hands', hands, 'hands_won', hands_won,
      'profit', profit, 'bb100', bb100)) FROM variants), '[]'::jsonb),
  'stakes', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'big_blind', big_blind, 'hands', hands, 'hands_won', hands_won,
      'profit', profit, 'bb100', bb100) ORDER BY big_blind DESC) FROM stakes), '[]'::jsonb),
  'tournaments', (SELECT jsonb_build_object(
      'entries', entries, 'cashes', cashes, 'wins', wins, 'best_finish', best_finish,
      'itm_percent', CASE WHEN entries > 0 THEN round(cashes::numeric / entries, 4) ELSE 0 END,
      'total_buyins', round(total_buyins, 2),
      'total_winnings', round(total_winnings, 2),
      'total_prizes', round(total_prizes, 2),
      'total_bounty_winnings', round(total_bounty_winnings, 2),
      'total_bounties', total_bounties,
      'net_profit', round(total_winnings - total_buyins, 2),
      'roi', CASE WHEN total_buyins > 0
          THEN round((total_winnings - total_buyins) / total_buyins, 4) ELSE 0 END
  ) FROM tourn),
  'recent_tournaments', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'tournament_id', tournament_id,
      'name', name, 'start_time', start_time, 'variant', variant,
      'is_mystery_bounty', is_mystery_bounty,
      'finish_rank', finish_rank, 'status', status,
      'prize', prize,
      'bounty_winnings', bounty_winnings,
      'bounties', bounties,
      'total_won', total_won,
      'buyin', buyin) ORDER BY start_time DESC NULLS LAST) FROM tourn_recent), '[]'::jsonb)
)
);
END;
$$;


ALTER FUNCTION public.ca_player_stats_full(p_user uuid, p_days integer, p_tz text) OWNER TO postgres;

--
-- Name: FUNCTION ca_player_stats_full(p_user uuid, p_days integer, p_tz text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_player_stats_full(p_user uuid, p_days integer, p_tz text) IS 'The stats payload for one player: the most recent 750 stat rows (exact settlement overlaid), lifetime index counts, daily series in p_tz (IANA; unknown names fall back to UTC), cash sessions (a new session starts after a 45-minute gap between the player''s cash hands; session profit is the sum of its hands'' settlements), positions, stakes, variants, tournaments in the rolling window. Service role only; the browser reaches it through ca_player_stats_overview_v2.';


--
-- Name: ca_player_stats_overview_v2(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_overview_v2(p_user uuid, p_days integer DEFAULT NULL::integer, p_tz text DEFAULT 'UTC'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_rollup_ceil timestamptz;
  v_rollup_updated_at timestamptz;
  v_cash int;
  v_exact int;
  v_source text;
  v_days integer := CASE
    WHEN p_days IS NULL THEN NULL
    ELSE least(greatest(p_days, 1), 3650)
  END;
BEGIN
  PERFORM public.ca_assert_self(p_user);

  SELECT rolled_ceil, updated_at
    INTO v_rollup_ceil, v_rollup_updated_at
  FROM public.ca_hand_player_stat_state
  WHERE id;

  v_result := public.ca_player_stats_full(p_user, v_days, p_tz);
  v_cash  := coalesce((v_result #>> '{overall,cash_hands}')::int, 0);
  v_exact := coalesce((v_result #>> '{overall,exact_cash_hands}')::int, 0);
  -- The money source is a MEASUREMENT of this payload, not a constant.
  v_source := CASE
    WHEN v_cash = 0 OR v_exact = v_cash THEN 'exact_settlement'
    WHEN v_exact = 0 THEN 'reconstructed_actions'
    ELSE 'mixed'
  END;

  RETURN coalesce(v_result, '{}'::jsonb) || jsonb_build_object(
    'contract_version', 2,
    'scope', jsonb_build_object(
      'target_user_id', p_user,
      'club_id', NULL,
      'range_days', v_days,
      'range_tz', coalesce(v_result ->> 'window_tz', 'UTC'),
      'visibility', 'owner'
    ),
    'quality', jsonb_build_object(
      'cash_money_source', v_source,
      'cash_money_exact', (v_source = 'exact_settlement'),
      'exact_cash_hands', v_exact,
      'advanced_facts_source', 'ca_hand_player_stat',
      'historical_club_breakdown_available', false,
      -- The hand_history trigger writes the stat row in the same transaction
      -- as the hand, so the payload includes every recorded hand.
      'live_tail_included', true
    ),
    'coverage', jsonb_build_object(
      'analysis_hand_cap', coalesce((v_result #>> '{overall,hand_cap}')::integer, 750),
      'analysis_hands_capped', coalesce((v_result #>> '{overall,hands_capped}')::boolean, false),
      'lifetime_index_complete', coalesce((v_result #>> '{lifetime,indexed_complete}')::boolean, false),
      'first_hand_at', v_result #> '{lifetime,first_hand_at}',
      'last_hand_at', v_result #> '{lifetime,last_hand_at}',
      'rollup_covered_through', to_jsonb(v_rollup_ceil),
      'rollup_updated_at', to_jsonb(v_rollup_updated_at)
    )
  );
END;
$$;


ALTER FUNCTION public.ca_player_stats_overview_v2(p_user uuid, p_days integer, p_tz text) OWNER TO postgres;

--
-- Name: FUNCTION ca_player_stats_overview_v2(p_user uuid, p_days integer, p_tz text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_player_stats_overview_v2(p_user uuid, p_days integer, p_tz text) IS 'The browser''s door to the stats payload: asserts auth.uid() = p_user, wraps ca_player_stats_full(p_user, p_days, p_tz) and stamps the contract (scope, quality, coverage). p_tz is the player''s IANA zone for day buckets.';


--
-- Name: ca_player_stats_pulse(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_pulse(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_newest_hand timestamptz;
  v_tourn text;
BEGIN
  PERFORM public.ca_assert_self(p_user);

  -- idx_ca_hand_player_idx_user_time (user_id, created_at DESC): one probe.
  SELECT max(created_at) INTO v_newest_hand
  FROM public.ca_hand_player_idx WHERE user_id = p_user;

  -- idx_tourn_players_user: a player's rows number in the hundreds at most.
  -- Any finish, prize, bounty or new entry changes the fingerprint.
  SELECT md5(coalesce(string_agg(
           id::text || ':' || coalesce(status, '') || ':' || coalesce(position::text, '')
             || ':' || coalesce(prize::text, '') || ':' || coalesce(bounty_winnings::text, '')
             || ':' || coalesce(eliminated_at::text, ''),
           '|' ORDER BY id), ''))
    INTO v_tourn
  FROM public.tournament_players WHERE user_id = p_user;

  RETURN jsonb_build_object(
    'newest_hand_at', v_newest_hand,
    'tournaments', v_tourn,
    'pulse', coalesce(v_newest_hand::text, '') || '#' || coalesce(v_tourn, '')
  );
END;
$$;


ALTER FUNCTION public.ca_player_stats_pulse(p_user uuid) OWNER TO postgres;

--
-- Name: FUNCTION ca_player_stats_pulse(p_user uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_player_stats_pulse(p_user uuid) IS 'The stats page''s heartbeat: the newest hand in the player''s own index and a fingerprint of their tournament rows, as one string. The page polls it while visible and refetches when it changes. Owner only (ca_assert_self). Replaces the Realtime subscription on ca_hand_player_idx, which left the publication on 2026-09-04.';


--
-- Name: ca_promo_vault_buy(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_promo_vault_buy(p_club_id uuid, p_item_key text, p_quantity integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'You Must Be Signed In To Buy Items.');
  END IF;
  IF NOT public.fn_promo_vault_can_manage(p_club_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only An Owner, Co-Owner Or Admin Can Buy For This Vault.');
  END IF;
  /* 2026-09-07 ruling (Diamond Accounting Standard DR3, DR14). club_diamond_wallets is not an account in
     the chart of accounts: nothing funds it (both rows 0.00), and a debit from it wrote no journal row and
     carried no idempotency key. Promo Vault purchases in diamonds are refused until the Diamond Arena's
     house account funds club vaults through the Mint. Recorded so the attempt is visible. */
  PERFORM public.fn_ca_diamond_incident('DR3:promo_vault_diamond_purchase_refused', 'info', auth.uid(), NULL,
    'ca_promo_vault_buy', jsonb_build_object('club_id', p_club_id, 'item_key', p_item_key, 'quantity', p_quantity));
  RETURN jsonb_build_object('success', false,
    'error', 'Promo Vault Purchases In Diamonds Are Not Available Yet. Club Diamond Wallets Are Not Funded.');
END;
$$;


ALTER FUNCTION public.ca_promo_vault_buy(p_club_id uuid, p_item_key text, p_quantity integer) OWNER TO postgres;

--
-- Name: FUNCTION ca_promo_vault_buy(p_club_id uuid, p_item_key text, p_quantity integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_promo_vault_buy(p_club_id uuid, p_item_key text, p_quantity integer) IS 'Buy Promo Vault items with the club diamond wallet: locks the wallet, debits it, adds to inventory and writes a purchase record, atomically.';


--
-- Name: ca_promo_vault_catalog(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_promo_vault_catalog(p_club_id uuid) RETURNS TABLE(item_key text, category text, label text, description text, duration_days integer, pack_size integer, tier text, diamond_cost integer, icon_key text, sort_order integer, quantity integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    c.item_key,
    c.category,
    c.label,
    c.description,
    c.duration_days,
    c.pack_size,
    c.tier,
    c.diamond_cost,
    c.icon_key,
    c.sort_order,
    coalesce(i.quantity, 0) AS quantity
  FROM public.promo_vault_catalog c
  LEFT JOIN public.promo_vault_inventory i
    ON i.item_key = c.item_key AND i.club_id = p_club_id
  WHERE c.is_active
  ORDER BY c.sort_order, c.label;
$$;


ALTER FUNCTION public.ca_promo_vault_catalog(p_club_id uuid) OWNER TO postgres;

