-- Name: FUNCTION ca_promo_vault_catalog(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_promo_vault_catalog(p_club_id uuid) IS 'Active Promo Vault catalog with the quantity this club currently holds of each item.';


--
-- Name: ca_promo_vault_grant(uuid, text, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_promo_vault_grant(p_club_id uuid, p_item_key text, p_recipient_user_id uuid, p_quantity integer, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.ca_promo_vault_grant(p_club_id, p_item_key, p_recipient_user_id,
                                     p_quantity, p_note, NULL::uuid);
$$;


ALTER FUNCTION public.ca_promo_vault_grant(p_club_id uuid, p_item_key text, p_recipient_user_id uuid, p_quantity integer, p_note text) OWNER TO postgres;

--
-- Name: FUNCTION ca_promo_vault_grant(p_club_id uuid, p_item_key text, p_recipient_user_id uuid, p_quantity integer, p_note text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_promo_vault_grant(p_club_id uuid, p_item_key text, p_recipient_user_id uuid, p_quantity integer, p_note text) IS 'Compatibility wrapper for the bundle that predates the retry key. Forwards to the six-argument form with no key, so it delivers correctly but cannot be retried safely. New callers pass p_op_id.';


--
-- Name: ca_promo_vault_grant(uuid, text, uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_promo_vault_grant(p_club_id uuid, p_item_key text, p_recipient_user_id uuid, p_quantity integer, p_note text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_scope     uuid[];
  v_held      int;
  v_qty       int;
  v_remaining int;
  v_del       record;
  v_prior     record;
  v_purchase  uuid;
  v_expires   timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'You Must Be Signed In To Send Items.');
  END IF;

  IF NOT public.fn_promo_vault_can_manage(p_club_id) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Only An Owner, Co-Owner Or Admin Can Send From This Vault.'
    );
  END IF;

  -- A REPEAT UNDER THE SAME KEY REPLAYS. Checked before anything is read for
  -- update, so a retry costs nothing and cannot send twice.
  IF p_op_id IS NOT NULL THEN
    SELECT r.id, r.item_key, r.quantity, r.recipient_user_id, r.delivered_ref
      INTO v_prior
      FROM public.promo_vault_records r
     WHERE r.club_id = p_club_id AND r.op_id = p_op_id;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'success', true, 'error', NULL, 'replayed', true,
        'record_id', v_prior.id, 'item_key', v_prior.item_key,
        'quantity', v_prior.quantity, 'delivered_ref', v_prior.delivered_ref,
        'remaining', (SELECT quantity FROM public.promo_vault_inventory
                       WHERE club_id = p_club_id AND item_key = v_prior.item_key));
    END IF;
  END IF;

  v_qty := coalesce(p_quantity, 0);
  IF v_qty <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Choose At Least One Item To Send.');
  END IF;
  IF v_qty > 999 THEN
    RETURN jsonb_build_object('success', false, 'error', 'You Can Send At Most 999 At A Time.');
  END IF;

  IF p_recipient_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Choose A Player To Send This To.');
  END IF;

  -- CAN THIS ITEM REACH A PLAYER AT ALL? Asked BEFORE the stock is touched, so
  -- a refusal leaves the shelf exactly as it was.
  SELECT * INTO v_del FROM public.fn_promo_vault_delivery_for(p_item_key);
  IF v_del.why_not IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', v_del.why_not, 'undeliverable', true);
  END IF;

  v_scope := public.fn_club_scope_ids(p_club_id);
  IF NOT EXISTS (
    SELECT 1 FROM public.club_members cm
    WHERE cm.user_id = p_recipient_user_id
      AND cm.club_id = ANY(v_scope)
      AND coalesce(cm.status, 'approved') NOT IN ('banned', 'rejected', 'left')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'That Player Is Not A Member Of This Club Or Union.'
    );
  END IF;

  SELECT quantity INTO v_held
  FROM public.promo_vault_inventory
  WHERE club_id = p_club_id AND item_key = p_item_key
  FOR UPDATE;

  IF NOT FOUND OR coalesce(v_held, 0) < v_qty THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format(
        'Not Enough In The Vault. You Hold %s Of This Item.',
        coalesce(v_held, 0)::text
      ),
      'remaining', coalesce(v_held, 0)
    );
  END IF;

  UPDATE public.promo_vault_inventory
  SET quantity = quantity - v_qty,
      updated_at = now()
  WHERE club_id = p_club_id AND item_key = p_item_key
  RETURNING quantity INTO v_remaining;

  -- THE DELIVERY. One row per grant, carrying the whole pack, in the same
  -- transaction as the decrement - so the stock and the entitlement move
  -- together or neither moves.
  IF v_del.duration_days IS NOT NULL THEN
    v_expires := now() + make_interval(days => v_del.duration_days);
  END IF;

  INSERT INTO public.feature_purchases
    (user_id, feature, cost, usage_type, uses_remaining, expires_at)
  VALUES
    (p_recipient_user_id, v_del.feature, 0, 'per_use',
     v_del.uses_per_unit * v_qty, v_expires)
  RETURNING id INTO v_purchase;

  INSERT INTO public.promo_vault_records
    (club_id, item_key, action, quantity, diamonds_spent, actor_user_id,
     recipient_user_id, note, op_id, delivered_ref)
  VALUES
    (p_club_id, p_item_key, 'grant', v_qty, 0, auth.uid(),
     p_recipient_user_id, nullif(btrim(p_note), ''), p_op_id, v_purchase);

  RETURN jsonb_build_object(
    'success', true, 'error', NULL, 'replayed', false,
    'remaining', v_remaining,
    'delivered_ref', v_purchase,
    'delivered_feature', v_del.feature,
    'delivered_uses', v_del.uses_per_unit * v_qty,
    'expires_at', v_expires);
END;
$$;


ALTER FUNCTION public.ca_promo_vault_grant(p_club_id uuid, p_item_key text, p_recipient_user_id uuid, p_quantity integer, p_note text, p_op_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION ca_promo_vault_grant(p_club_id uuid, p_item_key text, p_recipient_user_id uuid, p_quantity integer, p_note text, p_op_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_promo_vault_grant(p_club_id uuid, p_item_key text, p_recipient_user_id uuid, p_quantity integer, p_note text, p_op_id uuid) IS 'Sends a vault item to a player and WRITES THE ENTITLEMENT, in the same transaction as the stock decrement. Refuses, without touching the stock, any item the platform has nothing to deliver into. Retryable on p_op_id.';


--
-- Name: ca_promo_vault_records(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_promo_vault_records(p_club_id uuid, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, created_at timestamp with time zone, action text, item_key text, item_label text, item_category text, item_duration_days integer, quantity integer, diamonds_spent integer, actor_user_id uuid, actor_name text, recipient_user_id uuid, recipient_name text, recipient_player_number text, note text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    r.id,
    r.created_at,
    r.action,
    r.item_key,
    coalesce(c.label, r.item_key)::text,
    coalesce(c.category, 'feature')::text,
    c.duration_days,
    r.quantity,
    r.diamonds_spent,
    r.actor_user_id,
    public.fn_arena_name(ap.alias, ap.username, ap.display_name,
                         ap.first_name, ap.last_name, ap.full_name)::text,
    r.recipient_user_id,
    public.fn_arena_name(rp.alias, rp.username, rp.display_name,
                         rp.first_name, rp.last_name, rp.full_name)::text,
    rp.player_number::text,
    r.note
  FROM public.promo_vault_records r
  LEFT JOIN public.promo_vault_catalog c ON c.item_key = r.item_key
  LEFT JOIN public.profiles ap ON ap.id = r.actor_user_id
  LEFT JOIN public.profiles rp ON rp.id = r.recipient_user_id
  WHERE r.club_id = p_club_id
  ORDER BY r.created_at DESC
  LIMIT greatest(1, least(coalesce(p_limit, 100), 500));
$$;


ALTER FUNCTION public.ca_promo_vault_records(p_club_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION ca_promo_vault_records(p_club_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_promo_vault_records(p_club_id uuid, p_limit integer) IS 'Promo Vault ledger for a club, newest first, with the item label and the recipient alias and player number resolved.';


--
-- Name: ca_prune_hand_player_stat(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_prune_hand_player_stat(p_keep integer DEFAULT 1000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '10min'
    AS $$
DECLARE v_deleted int;
BEGIN
  WITH ranked AS (
    SELECT user_id, hand_id,
           row_number() OVER (PARTITION BY user_id ORDER BY created_at DESC) AS rn
    FROM ca_hand_player_stat
  )
  DELETE FROM ca_hand_player_stat s
  USING ranked r
  WHERE r.rn > p_keep AND s.user_id = r.user_id AND s.hand_id = r.hand_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION public.ca_prune_hand_player_stat(p_keep integer) OWNER TO postgres;

--
-- Name: ca_rake_snapshot(text, uuid, uuid, date, date, uuid, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_rake_snapshot(p_scope text DEFAULT 'club'::text, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_agent_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'rake'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_scope text := lower(COALESCE(NULLIF(btrim(p_scope),''),'club'));
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_end date := LEAST(COALESCE(p_end, v_today), v_today);
  v_start date := COALESCE(p_start, v_end - 6);
  v_off int := GREATEST(COALESCE(p_offset,0),0);
  v_q text := NULLIF(btrim(COALESCE(p_search,'')),'');
  v_sort text := lower(COALESCE(NULLIF(btrim(p_sort),''),'rake'));
  v_days int; v_pstart date; v_pend date; v_bucket text;
  v_union uuid; v_clubs uuid[];
  v_cur jsonb; v_prev jsonb; v_series jsonb;
  v_pack jsonb := jsonb_build_object('rows','[]'::jsonb,'total',0,'total_direct',0);
  v_kind text := 'none'; v_label text;
  v_agent jsonb; v_agent_p jsonb; v_live boolean := false;
BEGIN
  IF v_scope NOT IN ('club','union','agent') THEN
    RAISE EXCEPTION 'unknown scope %', v_scope USING ERRCODE='22023'; END IF;
  IF v_start < v_end - 730 THEN v_start := v_end - 730; END IF;
  IF v_start > v_end THEN v_start := v_end; END IF;
  v_days := (v_end - v_start) + 1; v_pend := v_start - 1; v_pstart := v_pend - (v_days - 1);
  v_bucket := CASE WHEN v_days <= 62 THEN 'day' WHEN v_days <= 400 THEN 'week' ELSE 'month' END;

  IF v_scope = 'agent' THEN
    IF p_club_id IS NULL THEN RAISE EXCEPTION 'agent scope needs a club' USING ERRCODE='22023'; END IF;
    v_agent := public.fn_agent_downline_rake_summary(p_agent_user_id, p_club_id,
      (v_start::timestamp AT TIME ZONE 'UTC'), ((v_end+1)::timestamp AT TIME ZONE 'UTC'));
    v_agent_p := public.fn_agent_downline_rake_summary(p_agent_user_id, p_club_id,
      (v_pstart::timestamp AT TIME ZONE 'UTC'), ((v_pend+1)::timestamp AT TIME ZONE 'UTC'));
    IF v_sort NOT IN ('rake','name','hands') THEN v_sort := 'rake'; END IF;
    v_pack := public.fn_ca_rake_by_downline(p_agent_user_id, p_club_id,
      (v_start::timestamp AT TIME ZONE 'UTC'), ((v_end+1)::timestamp AT TIME ZONE 'UTC'),
      p_limit, v_off, v_q, v_sort);
    SELECT COALESCE(c.name,'Club') INTO v_label FROM public.clubs c WHERE c.id = p_club_id;
    RETURN jsonb_build_object(
      'scope','agent','scope_label',COALESCE(v_label,'Downline'),'club_id',p_club_id,
      'union_id',NULL,'agent_user_id',p_agent_user_id,
      'range',jsonb_build_object('start',v_start,'end',v_end,'days',v_days),
      'previous_range',jsonb_build_object('start',v_pstart,'end',v_pend,'days',v_days),
      'summary',jsonb_build_object(
        'fee',round(COALESCE((v_agent->>'rake_generated')::numeric,0),2),
        'cash_fee',NULL,'mtt_fee',NULL,'games',NULL,
        'hands',COALESCE((v_agent->>'hands')::bigint,0),
        'total_winnings',NULL,'mtt_winnings',NULL,
        'members',COALESCE((v_agent->>'members')::int,0),
        'active',COALESCE((v_agent->>'active')::int,0),
        'commission_rate',(v_agent->>'commission_rate')::numeric,
        'estimated_commission',round(COALESCE((v_agent->>'estimated_commission')::numeric,0),2)),
      'previous',jsonb_build_object('fee',round(COALESCE((v_agent_p->>'rake_generated')::numeric,0),2),
        'hands',COALESCE((v_agent_p->>'hands')::bigint,0)),
      'delta',jsonb_build_object(
        'fee_pct',CASE WHEN COALESCE((v_agent_p->>'rake_generated')::numeric,0)=0 THEN NULL
          ELSE round((COALESCE((v_agent->>'rake_generated')::numeric,0)-(v_agent_p->>'rake_generated')::numeric)
               /abs((v_agent_p->>'rake_generated')::numeric)*100,1) END,
        'fee_abs',round(COALESCE((v_agent->>'rake_generated')::numeric,0)-COALESCE((v_agent_p->>'rake_generated')::numeric,0),2),
        'games_pct',NULL,'winnings_abs',NULL),
      'series','[]'::jsonb,'series_bucket',v_bucket,
      'breakdown',v_pack->'rows','breakdown_kind','downline',
      'breakdown_total',(v_pack->>'total_direct')::numeric,
      'breakdown_count',(v_pack->>'total')::int,
      'breakdown_offset',v_off,'commission_total',(v_pack->>'total_commission')::numeric,
      'breakdown_live',true,'rake_complete_through',NULL,
      'applied_search',v_q,'applied_sort',v_sort,
      'top_earner',v_agent->'top_earner','generated_at',now());
  END IF;

  IF v_scope = 'union' THEN
    v_union := p_union_id;
    IF v_union IS NULL AND p_club_id IS NOT NULL THEN
      SELECT uc.union_id INTO v_union FROM public.union_clubs uc WHERE uc.club_id=p_club_id LIMIT 1; END IF;
    IF v_union IS NULL THEN RAISE EXCEPTION 'no union for this context' USING ERRCODE='22023'; END IF;
    IF NOT public.ca_can_oversee_union(v_union) THEN
      RAISE EXCEPTION 'not authorized for this union' USING ERRCODE='42501'; END IF;
    SELECT ARRAY(SELECT uc.club_id FROM public.union_clubs uc WHERE uc.union_id=v_union) INTO v_clubs;
    SELECT u.name INTO v_label FROM public.unions u WHERE u.id=v_union;
    IF v_sort NOT IN ('rake','name','hands') THEN v_sort := 'rake'; END IF;
    v_pack := public.fn_ca_rake_by_club(v_clubs, v_start, v_end, p_limit, v_off, v_q, v_sort);
    v_kind := 'club'; v_live := false;
  ELSE
    IF p_club_id IS NULL THEN RAISE EXCEPTION 'club scope needs a club' USING ERRCODE='22023'; END IF;
    IF NOT public.ca_can_read_club_production(p_club_id) THEN
      RAISE EXCEPTION 'not authorized for this club' USING ERRCODE='42501'; END IF;
    v_clubs := ARRAY[p_club_id];
    SELECT uc.union_id INTO v_union FROM public.union_clubs uc WHERE uc.club_id=p_club_id LIMIT 1;
    SELECT c.name INTO v_label FROM public.clubs c WHERE c.id=p_club_id;
    IF v_sort NOT IN ('rake','name','cost','players') THEN v_sort := 'rake'; END IF;
    v_pack := public.fn_ca_rake_by_agent(p_club_id, v_start, v_end, p_limit, v_off, v_q, v_sort);
    v_kind := 'agent'; v_live := true;
  END IF;

  IF v_clubs IS NULL OR array_length(v_clubs,1) IS NULL THEN v_clubs := ARRAY[]::uuid[]; END IF;

  v_cur := public.fn_ca_rake_window(v_clubs, v_start, v_end);
  v_prev := public.fn_ca_rake_window(v_clubs, v_pstart, v_pend);
  v_series := public.fn_ca_rake_series(v_clubs, v_start, v_end, v_bucket);

  RETURN jsonb_build_object(
    'scope',v_scope,'scope_label',COALESCE(v_label,initcap(v_scope)),
    'club_id',p_club_id,'union_id',v_union,'club_count',array_length(v_clubs,1),
    'range',jsonb_build_object('start',v_start,'end',v_end,'days',v_days),
    'previous_range',jsonb_build_object('start',v_pstart,'end',v_pend,'days',v_days),
    'summary',v_cur,'previous',v_prev,
    'delta',jsonb_build_object(
      'fee_pct',CASE WHEN COALESCE((v_prev->>'fee')::numeric,0)=0 THEN NULL
        ELSE round(((v_cur->>'fee')::numeric-(v_prev->>'fee')::numeric)/abs((v_prev->>'fee')::numeric)*100,1) END,
      'games_pct',CASE WHEN COALESCE((v_prev->>'games')::numeric,0)=0 THEN NULL
        ELSE round(((v_cur->>'games')::numeric-(v_prev->>'games')::numeric)/abs((v_prev->>'games')::numeric)*100,1) END,
      'fee_abs',round((v_cur->>'fee')::numeric-(v_prev->>'fee')::numeric,2),
      'winnings_abs',round((v_cur->>'total_winnings')::numeric-(v_prev->>'total_winnings')::numeric,2)),
    'series',v_series,'series_bucket',v_bucket,
    'breakdown',v_pack->'rows','breakdown_kind',v_kind,
    'breakdown_total',(v_pack->>'total_direct')::numeric,
    'breakdown_count',(v_pack->>'total')::int,
    'breakdown_offset',v_off,'commission_total',(v_pack->>'total_commission')::numeric,
    'breakdown_live',v_live,'rake_complete_through',NULL,
    'applied_search',v_q,'applied_sort',v_sort,
    'data_updated_at',GREATEST(
      (SELECT max(c.updated_at) FROM public.club_table_daily c
        WHERE c.club_id = ANY(v_clubs) AND c.stat_date BETWEEN v_start AND v_end),
      (SELECT max(d.updated_at) FROM public.ca_club_tournament_daily d
        WHERE d.club_id = ANY(v_clubs) AND d.stat_date BETWEEN v_start AND v_end)),
    'generated_at',now());
END;
$$;


ALTER FUNCTION public.ca_rake_snapshot(p_scope text, p_club_id uuid, p_union_id uuid, p_start date, p_end date, p_agent_user_id uuid, p_limit integer, p_offset integer, p_search text, p_sort text) OWNER TO postgres;

--
-- Name: ca_rebuild_club_member_stats(uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_rebuild_club_member_stats(p_club_id uuid, p_limit integer DEFAULT 25, p_since timestamp with time zone DEFAULT (now() - '90 days'::interval)) RETURNS TABLE(tables_done integer, tables_failed integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '600s'
    AS $$
DECLARE
  r record;
  v_done   integer := 0;
  v_failed integer := 0;
BEGIN
  FOR r IN
    SELECT t.id
    FROM tables t
    JOIN LATERAL (
      SELECT max(hh.created_at) AS last_hand
      FROM hand_history hh
      WHERE hh.table_id = t.id AND hh.created_at >= p_since
    ) lh ON lh.last_hand IS NOT NULL
    WHERE t.club_id = p_club_id
      AND NOT EXISTS (
        SELECT 1 FROM club_stats_rebuild_log l
        WHERE l.table_id = t.id AND l.rebuilt_at >= p_since
      )
    ORDER BY lh.last_hand DESC
    LIMIT greatest(coalesce(p_limit, 25), 1)
  LOOP
    BEGIN
      PERFORM ca_rebuild_club_member_stats_table(r.id);
      v_done := v_done + 1;
    EXCEPTION WHEN OTHERS THEN
      -- Most commonly 57014 (statement timeout) on a very large table.
      INSERT INTO club_stats_rebuild_log (table_id, rebuilt_at, rows_written)
      VALUES (r.id, now(), -1)
      ON CONFLICT (table_id) DO UPDATE SET rebuilt_at = now(), rows_written = -1;
      v_failed := v_failed + 1;
      RAISE WARNING 'rebuild failed for table %: %', r.id, SQLERRM;
    END;
  END LOOP;

  tables_done := v_done;
  tables_failed := v_failed;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.ca_rebuild_club_member_stats(p_club_id uuid, p_limit integer, p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: ca_rebuild_club_member_stats_table(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_rebuild_club_member_stats_table(p_table_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '170s'
    AS $_$
DECLARE
  v_club uuid;
  v_rows integer;
BEGIN
  SELECT club_id INTO v_club FROM tables WHERE id = p_table_id;
  IF v_club IS NULL THEN
    RETURN 0;
  END IF;

  DELETE FROM club_member_daily_stats WHERE table_id = p_table_id;

  WITH hseq AS (
    SELECT hh.hand_number, hh.created_at, coalesce(hh.pot_size, 0) AS pot_size,
           coalesce(hh.rake_amount, 0) + coalesce(hh.bbj_amount, 0) AS rake_bbj,
           hh.players, hh.winners,
           row_number() OVER (ORDER BY hh.hand_number, hh.created_at) AS rn
    FROM hand_history hh
    WHERE hh.table_id = p_table_id
  ),
  seats AS (
    SELECT
      h.rn, h.created_at, h.pot_size, h.rake_bbj,
      (p->>'userId')::uuid   AS uid,
      (p->>'stack')::numeric AS stack,
      coalesce((SELECT sum((w->>'amount')::numeric)
                FROM jsonb_array_elements(coalesce(h.winners, '[]'::jsonb)) w
                WHERE w->>'userId' = p->>'userId'), 0) AS won
    FROM hseq h
    CROSS JOIN LATERAL jsonb_array_elements(coalesce(h.players, '[]'::jsonb)) p
    WHERE (p->>'userId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      AND (p->>'stack') IS NOT NULL
  ),
  d AS (
    SELECT s.*,
           lag(stack) OVER (PARTITION BY uid ORDER BY rn) AS prev_stack,
           lag(rn)    OVER (PARTITION BY uid ORDER BY rn) AS prev_rn
    FROM seats s
  ),
  marked AS (
    SELECT d.*,
           (prev_rn = rn - 1) AS adjacent,
           CASE WHEN prev_stack IS NOT NULL THEN stack - prev_stack ELSE 0 END AS delta
    FROM d
  ),
  per_hand AS (
    SELECT rn,
           count(*) AS seated,
           count(*) FILTER (WHERE prev_stack IS NOT NULL) AS with_prior,
           coalesce(sum(delta) FILTER (WHERE prev_stack IS NOT NULL), 0) AS dsum,
           max(rake_bbj) AS rake_bbj
    FROM marked GROUP BY rn
  ),
  calc AS (
    SELECT
      m.uid,
      (m.created_at AT TIME ZONE 'UTC')::date AS stat_date,
      m.won, m.pot_size, m.delta,
      CASE
        WHEN ph.seated = ph.with_prior THEN abs(ph.dsum + ph.rake_bbj) < 0.005
        ELSE m.adjacent AND m.delta <= m.won + 0.001
      END AS attributable
    FROM marked m JOIN per_hand ph ON ph.rn = m.rn
  )
  INSERT INTO club_member_daily_stats
    (club_id, table_id, user_id, stat_date, hands_played, hands_attributed, hands_won,
     total_won, profit, biggest_pot_won, biggest_pot, topup_total)
  SELECT
    v_club, p_table_id, uid, stat_date,
    count(*),
    count(*) FILTER (WHERE attributable),
    count(*) FILTER (WHERE won > 0),
    sum(won),
    coalesce(sum(delta) FILTER (WHERE attributable), 0),
    max(won), max(pot_size),
    coalesce(sum(delta - won) FILTER (WHERE NOT attributable AND delta > won), 0)
  FROM calc
  GROUP BY uid, stat_date
  ON CONFLICT (club_id, table_id, user_id, stat_date) DO UPDATE SET
    hands_played     = EXCLUDED.hands_played,
    hands_attributed = EXCLUDED.hands_attributed,
    hands_won        = EXCLUDED.hands_won,
    total_won        = EXCLUDED.total_won,
    profit           = EXCLUDED.profit,
    biggest_pot_won  = EXCLUDED.biggest_pot_won,
    biggest_pot      = EXCLUDED.biggest_pot,
    topup_total      = EXCLUDED.topup_total,
    updated_at       = now();

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  WITH last_hand AS (
    SELECT hh.players, hh.hand_number
    FROM hand_history hh
    WHERE hh.table_id = p_table_id
    ORDER BY hh.hand_number DESC
    LIMIT 1
  )
  INSERT INTO club_member_table_state AS st (table_id, user_id, last_stack, last_hand_number)
  SELECT DISTINCT ON (p->>'userId')
         p_table_id, (p->>'userId')::uuid, (p->>'stack')::numeric, lh.hand_number
  FROM last_hand lh
  CROSS JOIN LATERAL jsonb_array_elements(coalesce(lh.players, '[]'::jsonb)) p
  WHERE (p->>'userId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    AND (p->>'stack') IS NOT NULL
  ON CONFLICT (table_id, user_id) DO UPDATE SET
    last_stack       = EXCLUDED.last_stack,
    last_hand_number = EXCLUDED.last_hand_number,
    updated_at       = now();

  INSERT INTO club_stats_rebuild_log (table_id, rebuilt_at, rows_written)
  VALUES (p_table_id, now(), v_rows)
  ON CONFLICT (table_id) DO UPDATE SET rebuilt_at = now(), rows_written = EXCLUDED.rows_written;

  RETURN v_rows;
END;
$_$;


ALTER FUNCTION public.ca_rebuild_club_member_stats_table(p_table_id uuid) OWNER TO postgres;

--
-- Name: ca_rebuild_table_chunk(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_rebuild_table_chunk(p_table_id uuid, p_max_hands integer DEFAULT 3000) RETURNS TABLE(hands_processed integer, complete boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '170s'
    AS $_$
DECLARE
  v_club    uuid;
  v_cur_ts  timestamptz;
  v_cur_id  uuid;
  v_count   integer := 0;
  v_last_ts timestamptz;
  v_last_id uuid;
  v_limit   integer := greatest(coalesce(p_max_hands, 3000), 1);
BEGIN
  SELECT club_id INTO v_club FROM tables WHERE id = p_table_id;
  IF v_club IS NULL THEN
    hands_processed := 0; complete := true; RETURN NEXT; RETURN;
  END IF;

  EXECUTE 'DROP TABLE IF EXISTS _chunk';

  SELECT l.cursor_created_at, l.cursor_id INTO v_cur_ts, v_cur_id
  FROM club_stats_rebuild_log l WHERE l.table_id = p_table_id;

  IF v_cur_ts IS NULL THEN
    DELETE FROM club_member_daily_stats WHERE table_id = p_table_id;
    DELETE FROM club_member_table_state WHERE table_id = p_table_id;
  END IF;

  CREATE TEMP TABLE _chunk ON COMMIT DROP AS
  WITH picked AS (
    SELECT hh.id, hh.created_at, hh.hand_number,
           coalesce(hh.pot_size, 0) AS pot_size,
           coalesce(hh.rake_amount, 0) + coalesce(hh.bbj_amount, 0) AS rake_bbj,
           hh.players, hh.winners
    FROM hand_history hh
    WHERE hh.table_id = p_table_id
      AND (v_cur_ts IS NULL OR (hh.created_at, hh.id) > (v_cur_ts, v_cur_id))
    ORDER BY hh.created_at, hh.id
    LIMIT v_limit
  ),
  seq AS (
    SELECT p.*,
           row_number() OVER (ORDER BY p.created_at, p.id) AS rn,
           lag(p.id) OVER (ORDER BY p.created_at, p.id) AS prev_hand_at_table
    FROM picked p
  )
  SELECT
    s.rn, s.id AS hand_id, s.created_at, s.hand_number, s.pot_size, s.rake_bbj,
    coalesce(s.prev_hand_at_table, v_cur_id) AS prev_hand_at_table,
    (pl->>'userId')::uuid   AS uid,
    (pl->>'stack')::numeric AS stack,
    coalesce((SELECT sum((w->>'amount')::numeric)
              FROM jsonb_array_elements(coalesce(s.winners, '[]'::jsonb)) w
              WHERE w->>'userId' = pl->>'userId'), 0) AS won
  FROM seq s
  CROSS JOIN LATERAL jsonb_array_elements(coalesce(s.players, '[]'::jsonb)) pl
  WHERE (pl->>'userId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    AND (pl->>'stack') IS NOT NULL;

  SELECT count(DISTINCT hand_id) INTO v_count FROM _chunk;

  IF v_count = 0 THEN
    INSERT INTO club_stats_rebuild_log (table_id, rebuilt_at, complete, rows_written)
    VALUES (p_table_id, now(), true, 0)
    ON CONFLICT (table_id) DO UPDATE SET complete = true, rebuilt_at = now();
    hands_processed := 0; complete := true; RETURN NEXT; RETURN;
  END IF;

  SELECT c.created_at, c.hand_id INTO v_last_ts, v_last_id
  FROM _chunk c ORDER BY c.created_at DESC, c.hand_id DESC LIMIT 1;

  WITH d AS (
    SELECT c.*,
           lag(c.stack)   OVER (PARTITION BY c.uid ORDER BY c.rn) AS prev_stack_in,
           lag(c.hand_id) OVER (PARTITION BY c.uid ORDER BY c.rn) AS prev_hand_in,
           st.last_stack   AS carried_stack,
           st.last_hand_id AS carried_hand
    FROM _chunk c
    LEFT JOIN club_member_table_state st
           ON st.table_id = p_table_id AND st.user_id = c.uid
  ),
  resolved AS (
    SELECT d.*,
           coalesce(d.prev_stack_in, d.carried_stack) AS prev_stack,
           coalesce(d.prev_hand_in,  d.carried_hand)  AS prev_hand
    FROM d
  ),
  marked AS (
    SELECT r.*,
           (r.prev_stack IS NOT NULL AND r.prev_hand IS NOT NULL
            AND r.prev_hand = r.prev_hand_at_table) AS adjacent,
           CASE WHEN r.prev_stack IS NOT NULL THEN r.stack - r.prev_stack ELSE 0 END AS delta
    FROM resolved r
  ),
  per_hand AS (
    SELECT hand_id,
           count(*) AS seated,
           count(*) FILTER (WHERE prev_stack IS NOT NULL) AS with_prior,
           coalesce(sum(delta) FILTER (WHERE prev_stack IS NOT NULL), 0) AS dsum,
           max(rake_bbj) AS rake_bbj
    FROM marked GROUP BY hand_id
  ),
  calc AS (
    SELECT m.uid, (m.created_at AT TIME ZONE 'UTC')::date AS stat_date,
           m.won, m.pot_size, m.delta,
           CASE
             WHEN ph.seated = ph.with_prior THEN abs(ph.dsum + ph.rake_bbj) < 0.005
             ELSE m.adjacent AND m.delta <= m.won + 0.001
           END AS attributable
    FROM marked m JOIN per_hand ph ON ph.hand_id = m.hand_id
  )
  INSERT INTO club_member_daily_stats AS s
    (club_id, table_id, user_id, stat_date, hands_played, hands_attributed, hands_won,
     total_won, profit, biggest_pot_won, biggest_pot, topup_total)
  SELECT
    v_club, p_table_id, uid, stat_date,
    count(*),
    count(*) FILTER (WHERE attributable),
    count(*) FILTER (WHERE won > 0),
    sum(won),
    coalesce(sum(delta) FILTER (WHERE attributable), 0),
    max(won), max(pot_size),
    coalesce(sum(delta - won) FILTER (WHERE NOT attributable AND delta > won), 0)
  FROM calc
  GROUP BY uid, stat_date
  ON CONFLICT (club_id, table_id, user_id, stat_date) DO UPDATE SET
    hands_played     = s.hands_played + EXCLUDED.hands_played,
    hands_attributed = s.hands_attributed + EXCLUDED.hands_attributed,
    hands_won        = s.hands_won + EXCLUDED.hands_won,
    total_won        = s.total_won + EXCLUDED.total_won,
    profit           = s.profit + EXCLUDED.profit,
    biggest_pot_won  = greatest(s.biggest_pot_won, EXCLUDED.biggest_pot_won),
    biggest_pot      = greatest(s.biggest_pot, EXCLUDED.biggest_pot),
    topup_total      = s.topup_total + EXCLUDED.topup_total,
    updated_at       = now();

  INSERT INTO club_member_table_state AS st
    (table_id, user_id, last_stack, last_hand_number, last_created_at, last_hand_id)
  SELECT DISTINCT ON (uid)
         p_table_id, uid, stack, hand_number, created_at, hand_id
  FROM _chunk
  ORDER BY uid, created_at DESC, hand_id DESC
  ON CONFLICT (table_id, user_id) DO UPDATE SET
    last_stack       = EXCLUDED.last_stack,
    last_hand_number = EXCLUDED.last_hand_number,
    last_created_at  = EXCLUDED.last_created_at,
    last_hand_id     = EXCLUDED.last_hand_id,
    updated_at       = now();

  INSERT INTO club_stats_rebuild_log
    (table_id, rebuilt_at, rows_written, cursor_created_at, cursor_id, complete, hands_done)
  VALUES (p_table_id, now(), v_count, v_last_ts, v_last_id, v_count < v_limit, v_count)
  ON CONFLICT (table_id) DO UPDATE SET
    rebuilt_at        = now(),
    rows_written      = EXCLUDED.rows_written,
    cursor_created_at = EXCLUDED.cursor_created_at,
    cursor_id         = EXCLUDED.cursor_id,
    complete          = EXCLUDED.complete,
    hands_done        = club_stats_rebuild_log.hands_done + EXCLUDED.hands_done;

  hands_processed := v_count;
  complete := v_count < v_limit;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION public.ca_rebuild_table_chunk(p_table_id uuid, p_max_hands integer) OWNER TO postgres;

--
-- Name: ca_refresh_hand_player_index(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_refresh_hand_player_index(p_max_hands integer DEFAULT 50000) RETURNS TABLE(hands_indexed integer, rows_added integer, floor_at timestamp with time zone, ceil_at timestamp with time zone, complete boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '10min'
    AS $_$
DECLARE
  f timestamptz; c timestamptz; done boolean; new_floor timestamptz; new_ceil timestamptz;
  n_hands int := 0; n_rows int := 0; k int; kr int;
  v_chunk constant int := 3000;
  v_budget int := least(greatest(coalesce(p_max_hands, 3000), 1), 200000);
  v_deadline timestamptz := clock_timestamp() + interval '90 seconds';
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('ca_refresh_hand_player_index')) THEN
    RETURN QUERY SELECT 0, 0, NULL::timestamptz, NULL::timestamptz, false;
    RETURN;
  END IF;

  SELECT idx_floor, idx_ceil, backfill_complete INTO f, c, done
  FROM public.ca_hand_player_idx_state WHERE id FOR UPDATE;
  IF f IS NULL THEN f := now(); END IF;
  IF c IS NULL THEN c := now(); END IF;

  LOOP
    EXIT WHEN n_hands >= v_budget OR clock_timestamp() >= v_deadline;
    SELECT max(created_at) INTO new_ceil
    FROM (
      SELECT created_at FROM public.hand_history
      WHERE created_at > c ORDER BY created_at, id LIMIT v_chunk
    ) bounded;
    EXIT WHEN new_ceil IS NULL;
    WITH src AS (
      SELECT h.id, h.created_at, h.players FROM public.hand_history h
      WHERE h.created_at > c AND h.created_at <= new_ceil
    ), expanded AS (
      SELECT DISTINCT ((pl->>'userId')::uuid) AS user_id, s.created_at, s.id AS hand_id
      FROM src s, jsonb_array_elements(s.players) pl
      WHERE pl->>'userId' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    ), ins AS (
      INSERT INTO public.ca_hand_player_idx (user_id, created_at, hand_id)
      SELECT user_id, created_at, hand_id FROM expanded
      ON CONFLICT DO NOTHING RETURNING 1
    )
    SELECT (SELECT count(*) FROM src)::int, (SELECT count(*) FROM ins)::int INTO k, kr;
    n_hands := n_hands + coalesce(k, 0); n_rows := n_rows + coalesce(kr, 0); c := new_ceil;
  END LOOP;

  IF NOT done AND clock_timestamp() < v_deadline THEN
    SELECT min(created_at) INTO new_floor FROM (
      SELECT created_at FROM public.hand_history
      WHERE created_at < f ORDER BY created_at DESC LIMIT v_chunk
    ) q;
    IF new_floor IS NULL THEN done := true;
    ELSE
      WITH src AS (
        SELECT h.id, h.created_at, h.players FROM public.hand_history h
        WHERE h.created_at < f AND h.created_at >= new_floor
      ), expanded AS (
        SELECT DISTINCT ((pl->>'userId')::uuid) AS user_id, s.created_at, s.id AS hand_id
        FROM src s, jsonb_array_elements(s.players) pl
        WHERE pl->>'userId' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      ), ins AS (
        INSERT INTO public.ca_hand_player_idx (user_id, created_at, hand_id)
        SELECT user_id, created_at, hand_id FROM expanded
        ON CONFLICT DO NOTHING RETURNING 1
      )
      SELECT (SELECT count(*) FROM src)::int, (SELECT count(*) FROM ins)::int INTO k, kr;
      n_hands := n_hands + coalesce(k, 0); n_rows := n_rows + coalesce(kr, 0); f := new_floor;
      IF NOT EXISTS (SELECT 1 FROM public.hand_history WHERE created_at < f) THEN done := true; END IF;
    END IF;
  END IF;

  UPDATE public.ca_hand_player_idx_state
  SET idx_floor = least(coalesce(idx_floor, f), f),
      idx_ceil = greatest(coalesce(idx_ceil, c), c),
      backfill_complete = done,
      rows_indexed = rows_indexed + n_rows,
      updated_at = now()
  WHERE id;

  RETURN QUERY SELECT n_hands, n_rows, f, c, done;
END;
$_$;


ALTER FUNCTION public.ca_refresh_hand_player_index(p_max_hands integer) OWNER TO postgres;

--
-- Name: ca_refresh_reporting_cash_rollup(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_refresh_reporting_cash_rollup(p_start date, p_end date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start date:=LEAST(p_start,p_end); v_end date:=GREATEST(p_start,p_end);
  v_from timestamptz; v_to timestamptz; v_rows bigint;
BEGIN
  IF v_start IS NULL OR v_end IS NULL OR v_end-v_start>400 THEN
    RAISE EXCEPTION 'cash reporting refresh requires a 0-400 day range'; END IF;
  PERFORM pg_advisory_xact_lock(918273645);
  v_from:=v_start::timestamp AT TIME ZONE 'UTC';
  v_to:=(v_end+1)::timestamp AT TIME ZONE 'UTC';
  UPDATE public.ca_club_player_daily SET cash_net=0,updated_at=now()
   WHERE stat_date BETWEEN v_start AND v_end AND cash_net<>0;
  WITH home AS MATERIALIZED (
    SELECT DISTINCT ON(uc.union_id,cm.user_id) uc.union_id,cm.user_id,cm.club_id
      FROM public.club_members cm JOIN public.union_clubs uc ON uc.club_id=cm.club_id
     ORDER BY uc.union_id,cm.user_id,cm.joined_at ASC NULLS LAST,cm.club_id
  ), cash AS (
    SELECT x.club_id,x.user_id,x.stat_date,SUM(x.cash_net) AS cash_net FROM (
      SELECT h.club_id,wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date stat_date,
             SUM(CASE WHEN wt.type='credit' THEN wt.amount
                      WHEN wt.type='debit' THEN -wt.amount ELSE 0 END) cash_net
        FROM public.wallet_transactions wt
        JOIN public.tables tb ON tb.id=wt.table_id AND tb.union_id IS NOT NULL
         AND tb.tournament_id IS NULL
        JOIN home h ON h.union_id=tb.union_id AND h.user_id=wt.user_id
       WHERE wt.created_at>=v_from AND wt.created_at<v_to
         AND wt.category IN('buyin','cashout','addon','rebuy','refund') AND wt.table_id IS NOT NULL
       GROUP BY 1,2,3
      UNION ALL
      -- 2026-09-04: standalone tables, which this rollup never read.
      SELECT tb.club_id,wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date,
             SUM(CASE WHEN wt.type='credit' THEN wt.amount
                      WHEN wt.type='debit' THEN -wt.amount ELSE 0 END)
        FROM public.wallet_transactions wt
        JOIN public.tables tb ON tb.id=wt.table_id AND tb.union_id IS NULL
         AND tb.tournament_id IS NULL AND tb.club_id IS NOT NULL
       WHERE wt.created_at>=v_from AND wt.created_at<v_to
         AND wt.category IN('buyin','cashout','addon','rebuy','refund') AND wt.table_id IS NOT NULL
       GROUP BY 1,2,3
    ) x GROUP BY 1,2,3
  )
  INSERT INTO public.ca_club_player_daily AS d
    (club_id,user_id,stat_date,cash_net,tournament_net,updated_at)
  SELECT club_id,user_id,stat_date,cash_net,0,now() FROM cash
  ON CONFLICT(club_id,user_id,stat_date) DO UPDATE
   SET cash_net=EXCLUDED.cash_net,updated_at=now();
  SELECT count(*) INTO v_rows FROM public.ca_club_player_daily
   WHERE stat_date BETWEEN v_start AND v_end AND cash_net<>0;
  RETURN jsonb_build_object('start',v_start,'end',v_end,'cash_facts',v_rows,'refreshed_at',now());
END;
$$;


ALTER FUNCTION public.ca_refresh_reporting_cash_rollup(p_start date, p_end date) OWNER TO postgres;

--
-- Name: ca_refresh_reporting_rollups(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_refresh_reporting_rollups(p_start date, p_end date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_base jsonb; v_cash jsonb;
BEGIN
  v_base:=public.ca_refresh_reporting_rollups_base(p_start,p_end);
  v_cash:=public.ca_refresh_reporting_cash_rollup(p_start,p_end);
  RETURN v_base || jsonb_build_object('cash_repair',v_cash);
END;
$$;


ALTER FUNCTION public.ca_refresh_reporting_rollups(p_start date, p_end date) OWNER TO postgres;

--
-- Name: ca_refresh_reporting_rollups_base(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_refresh_reporting_rollups_base(p_start date, p_end date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start date := LEAST(p_start, p_end);
  v_end date := GREATEST(p_start, p_end);
  v_from timestamptz;
  v_to timestamptz;
  v_players bigint;
  v_tournaments bigint;
  v_participants bigint;
BEGIN
  IF v_start IS NULL OR v_end IS NULL OR v_end - v_start > 400 THEN
    RAISE EXCEPTION 'reporting refresh requires a 0-400 day range';
  END IF;
  PERFORM pg_advisory_xact_lock(918273645);
  v_from := v_start::timestamp AT TIME ZONE 'UTC';
  v_to := (v_end + 1)::timestamp AT TIME ZONE 'UTC';

  DELETE FROM public.ca_club_player_daily WHERE stat_date BETWEEN v_start AND v_end;
  DELETE FROM public.ca_club_tournament_daily WHERE stat_date BETWEEN v_start AND v_end;
  DELETE FROM public.ca_club_tournament_player_daily WHERE stat_date BETWEEN v_start AND v_end;

  WITH home AS MATERIALIZED (
    SELECT DISTINCT ON (uc.union_id, cm.user_id)
           uc.union_id, cm.user_id, cm.club_id
      FROM public.club_members cm
      JOIN public.union_clubs uc ON uc.club_id = cm.club_id
     ORDER BY uc.union_id, cm.user_id, cm.joined_at ASC NULLS LAST, cm.club_id
  ), standalone AS MATERIALIZED (
    SELECT cm.user_id, cm.club_id
      FROM public.club_members cm
     WHERE NOT EXISTS (SELECT 1 FROM public.union_clubs uc WHERE uc.club_id=cm.club_id)
  ), affiliations AS MATERIALIZED (
    SELECT user_id, club_id FROM home
    UNION
    SELECT user_id, club_id FROM standalone
  ), mapped AS MATERIALIZED (
    -- 2026-09-04: cash rows are the ones with a table (buy-in, cash-out,
    -- add-on, rebuy, refund); tournament rows have a tournament and no table
    -- (buy-in, add-on, rebuy, refund, prize, bounty, prize reversal). The sign
    -- is the row's type. This read buy-in/cash-out and buy-in/prize/bounty.
    SELECT 'cash'::text AS kind,wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date AS stat_date,
           h.club_id,wt.category,wt.type,wt.amount,wt.related_entity_id AS tournament_id
      FROM public.wallet_transactions wt
      JOIN public.tables tb ON tb.id=wt.table_id AND tb.union_id IS NOT NULL
       AND tb.tournament_id IS NULL
      JOIN home h ON h.union_id=tb.union_id AND h.user_id=wt.user_id
     WHERE wt.created_at>=v_from AND wt.created_at<v_to
       AND wt.category IN ('buyin','cashout','addon','rebuy','refund') AND wt.table_id IS NOT NULL
    UNION ALL
    -- standalone tables, which this rollup never read.
    SELECT 'cash',wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date,
           tb.club_id,wt.category,wt.type,wt.amount,wt.related_entity_id
      FROM public.wallet_transactions wt
      JOIN public.tables tb ON tb.id=wt.table_id AND tb.union_id IS NULL
       AND tb.tournament_id IS NULL AND tb.club_id IS NOT NULL
     WHERE wt.created_at>=v_from AND wt.created_at<v_to
       AND wt.category IN ('buyin','cashout','addon','rebuy','refund') AND wt.table_id IS NOT NULL
    UNION ALL
    SELECT 'tournament',wt.user_id,(wt.created_at AT TIME ZONE 'UTC')::date,
           a.club_id,wt.category,wt.type,wt.amount,wt.related_entity_id
      FROM public.wallet_transactions wt
      JOIN affiliations a ON a.user_id=wt.user_id
     WHERE wt.created_at>=v_from AND wt.created_at<v_to
       AND wt.category IN ('tournament_buyin','prize','bounty','addon','rebuy','refund','prize_reversal')
       AND wt.related_entity_id IS NOT NULL AND wt.table_id IS NULL
  )
  INSERT INTO public.ca_club_player_daily
    (club_id,user_id,stat_date,cash_net,tournament_net,updated_at)
  SELECT m.club_id,m.user_id,m.stat_date,
         SUM(CASE WHEN m.kind='cash'
                  THEN CASE WHEN m.type='credit' THEN m.amount
                            WHEN m.type='debit' THEN -m.amount ELSE 0 END ELSE 0 END),
         SUM(CASE WHEN m.kind='tournament'
                  THEN CASE WHEN m.type='credit' THEN m.amount
                            WHEN m.type='debit' THEN -m.amount ELSE 0 END ELSE 0 END),now()
    FROM mapped m GROUP BY 1,2,3;

  WITH home AS MATERIALIZED (
    SELECT DISTINCT ON (uc.union_id,cm.user_id)
           uc.union_id,cm.user_id,cm.club_id
      FROM public.club_members cm JOIN public.union_clubs uc ON uc.club_id=cm.club_id
     ORDER BY uc.union_id,cm.user_id,cm.joined_at ASC NULLS LAST,cm.club_id
  ), standalone AS MATERIALIZED (
    SELECT cm.user_id,cm.club_id FROM public.club_members cm
     WHERE NOT EXISTS (SELECT 1 FROM public.union_clubs uc WHERE uc.club_id=cm.club_id)
  ), affiliations AS MATERIALIZED (
    SELECT user_id,club_id FROM home UNION SELECT user_id,club_id FROM standalone
  ), wallet_mapped AS MATERIALIZED (
    SELECT a.club_id,wt.related_entity_id AS tournament_id,wt.user_id,
           (wt.created_at AT TIME ZONE 'UTC')::date AS stat_date,
           CASE WHEN wt.type='credit' THEN wt.amount
                WHEN wt.type='debit' THEN -wt.amount ELSE 0 END AS winnings
      FROM public.wallet_transactions wt JOIN affiliations a ON a.user_id=wt.user_id
     WHERE wt.created_at>=v_from AND wt.created_at<v_to
       AND wt.category IN ('tournament_buyin','prize','bounty','addon','rebuy','refund','prize_reversal')
       AND wt.related_entity_id IS NOT NULL AND wt.table_id IS NULL
  ), entrant_totals AS MATERIALIZED (
    SELECT tp.tournament_id,count(*)::numeric AS total_players
      FROM public.tournament_players tp GROUP BY tp.tournament_id
  ), entrant_clubs AS MATERIALIZED (
    SELECT tp.tournament_id,a.club_id,count(*)::numeric AS club_players
      FROM public.tournament_players tp JOIN affiliations a ON a.user_id=tp.user_id
     GROUP BY tp.tournament_id,a.club_id
  ), rake_mapped AS MATERIALIZED (
    SELECT r.tournament_id,(r.created_at AT TIME ZONE 'UTC')::date AS stat_date,
           CASE WHEN r.metadata ? 'user_id' THEN a.club_id ELSE ec.club_id END AS club_id,
           CASE WHEN r.metadata ? 'user_id' THEN r.rake_amount
                ELSE r.rake_amount*ec.club_players/NULLIF(et.total_players,0) END AS fee
      FROM public.rake_records r
      LEFT JOIN affiliations a ON r.metadata ? 'user_id'
       AND a.user_id::text=r.metadata->>'user_id'
      LEFT JOIN entrant_clubs ec ON NOT (r.metadata ? 'user_id')
       AND ec.tournament_id=r.tournament_id
      LEFT JOIN entrant_totals et ON et.tournament_id=r.tournament_id
     WHERE r.created_at>=v_from AND r.created_at<v_to AND r.is_tournament
       AND r.tournament_id IS NOT NULL AND r.rake_amount<>0
  ), combined AS (
    SELECT wm.club_id,wm.tournament_id,wm.stat_date,0::numeric AS fee,
           sum(wm.winnings) AS winnings FROM wallet_mapped wm GROUP BY 1,2,3
    UNION ALL
    SELECT rm.club_id,rm.tournament_id,rm.stat_date,sum(rm.fee),0::numeric
      FROM rake_mapped rm WHERE rm.club_id IS NOT NULL GROUP BY 1,2,3
  )
  INSERT INTO public.ca_club_tournament_daily
    (club_id,tournament_id,stat_date,fee,winnings,updated_at)
  SELECT club_id,tournament_id,stat_date,sum(fee),sum(winnings),now()
    FROM combined GROUP BY 1,2,3;

  WITH home AS MATERIALIZED (
    SELECT DISTINCT ON (uc.union_id,cm.user_id) uc.union_id,cm.user_id,cm.club_id
      FROM public.club_members cm JOIN public.union_clubs uc ON uc.club_id=cm.club_id
     ORDER BY uc.union_id,cm.user_id,cm.joined_at ASC NULLS LAST,cm.club_id
  ), standalone AS MATERIALIZED (
    SELECT cm.user_id,cm.club_id FROM public.club_members cm
     WHERE NOT EXISTS (SELECT 1 FROM public.union_clubs uc WHERE uc.club_id=cm.club_id)
  ), affiliations AS MATERIALIZED (
    SELECT user_id,club_id FROM home UNION SELECT user_id,club_id FROM standalone
  )
  INSERT INTO public.ca_club_tournament_player_daily
    (club_id,tournament_id,user_id,stat_date,updated_at)
  SELECT DISTINCT a.club_id,wt.related_entity_id,wt.user_id,
         (wt.created_at AT TIME ZONE 'UTC')::date,now()
    FROM public.wallet_transactions wt JOIN affiliations a ON a.user_id=wt.user_id
   WHERE wt.created_at>=v_from AND wt.created_at<v_to
     AND wt.category IN ('tournament_buyin','prize','bounty','addon','rebuy','refund','prize_reversal')
     AND wt.related_entity_id IS NOT NULL AND wt.table_id IS NULL;

  SELECT count(*) INTO v_players FROM public.ca_club_player_daily
   WHERE stat_date BETWEEN v_start AND v_end;
  SELECT count(*) INTO v_tournaments FROM public.ca_club_tournament_daily
   WHERE stat_date BETWEEN v_start AND v_end;
  SELECT count(*) INTO v_participants FROM public.ca_club_tournament_player_daily
   WHERE stat_date BETWEEN v_start AND v_end;
  RETURN jsonb_build_object('start',v_start,'end',v_end,'player_facts',v_players,
    'tournament_facts',v_tournaments,'participant_facts',v_participants,
    'refreshed_at',now());
END;
$$;


ALTER FUNCTION public.ca_refresh_reporting_rollups_base(p_start date, p_end date) OWNER TO postgres;

--
-- Name: ca_refresh_stat_distribution(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_refresh_stat_distribution(p_min_hands integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows int := 0;
BEGIN
  WITH base AS (
    SELECT
      ps.user_id,
      sum(ps.hands_played)                        AS hands,
      avg(nullif(ps.vpip, 0))                     AS vpip,
      avg(nullif(ps.pfr, 0))                      AS pfr,
      CASE WHEN sum(ps.sum_big_blind) > 0
        THEN (sum(ps.total_winnings) - sum(ps.total_losses)) / sum(ps.sum_big_blind) * 100
        ELSE NULL END                             AS bb100
    FROM public.player_stats ps
    GROUP BY ps.user_id
    HAVING sum(ps.hands_played) >= p_min_hands
  ),
  pos AS (
    SELECT
      pps.user_id,
      CASE WHEN sum(pps.hands_played) > 0
        THEN sum(pps.three_bet_count)::numeric / sum(pps.hands_played) * 100
        ELSE NULL END AS three_bet,
      CASE WHEN sum(pps.hands_played) > 0
        THEN sum(pps.hands_won)::numeric / sum(pps.hands_played) * 100
        ELSE NULL END AS win_rate
    FROM public.player_position_stats pps
    GROUP BY pps.user_id
    HAVING sum(pps.hands_played) >= p_min_hands
  ),
  merged AS (
    SELECT b.user_id, b.vpip, b.pfr, b.bb100, p.three_bet, p.win_rate
    FROM base b LEFT JOIN pos p ON p.user_id = b.user_id
  ),
  unpivoted AS (
    SELECT 'vpip'::text AS metric, vpip AS v FROM merged
    UNION ALL SELECT 'pfr', pfr FROM merged
    UNION ALL SELECT 'bb100', bb100 FROM merged
    UNION ALL SELECT 'three_bet', three_bet FROM merged
    UNION ALL SELECT 'win_rate', win_rate FROM merged
  ),
  computed AS (
    SELECT
      metric,
      percentile_cont(0.10) WITHIN GROUP (ORDER BY v)::numeric AS p10,
      percentile_cont(0.25) WITHIN GROUP (ORDER BY v)::numeric AS p25,
      percentile_cont(0.50) WITHIN GROUP (ORDER BY v)::numeric AS p50,
      percentile_cont(0.75) WITHIN GROUP (ORDER BY v)::numeric AS p75,
      percentile_cont(0.90) WITHIN GROUP (ORDER BY v)::numeric AS p90,
      count(v) AS n
    FROM unpivoted
    WHERE v IS NOT NULL
    GROUP BY metric
  )
  INSERT INTO public.ca_stat_distribution
    (cohort, metric, p10, p25, p50, p75, p90, sample_size, computed_at)
  SELECT 'field', metric,
         round(p10, 3), round(p25, 3), round(p50, 3), round(p75, 3), round(p90, 3),
         n, now()
  FROM computed
  ON CONFLICT (cohort, metric) DO UPDATE SET
    p10 = EXCLUDED.p10, p25 = EXCLUDED.p25, p50 = EXCLUDED.p50,
    p75 = EXCLUDED.p75, p90 = EXCLUDED.p90,
    sample_size = EXCLUDED.sample_size, computed_at = EXCLUDED.computed_at;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN jsonb_build_object('metrics_written', v_rows, 'min_hands', p_min_hands, 'at', now());
END $$;


ALTER FUNCTION public.ca_refresh_stat_distribution(p_min_hands integer) OWNER TO postgres;

--
-- Name: ca_repair_hand_player_stat_money(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_repair_hand_player_stat_money(p_max_hands integer DEFAULT 24000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '4min'
    AS $$
DECLARE
  v_cur timestamptz;
  v_ceiling timestamptz;
  v_deadline timestamptz := clock_timestamp() + interval '100 seconds';
  v_chunk constant int := 2000;
  v_last timestamptz;
  v_end timestamptz;
  v_hands int := 0;
  v_changed int := 0;
  v_k int;
  v_done boolean := false;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('ca_repair_hand_player_stat_money')) THEN
    RETURN jsonb_build_object('skipped', 'locked');
  END IF;

  SELECT cursor_at, ceiling_at, done INTO v_cur, v_ceiling, v_done
  FROM public.ca_hand_player_stat_repair_state WHERE id FOR UPDATE;
  IF v_done OR v_cur IS NULL THEN
    RETURN jsonb_build_object('done', true);
  END IF;

  WHILE v_hands < p_max_hands AND clock_timestamp() < v_deadline AND v_cur < v_ceiling LOOP
    SELECT max(created_at) INTO v_last
    FROM (SELECT created_at FROM public.hand_history
          WHERE created_at >= v_cur AND created_at < v_ceiling
          ORDER BY created_at, id LIMIT v_chunk) b;
    IF v_last IS NULL THEN
      v_cur := v_ceiling;
      EXIT;
    END IF;
    v_end := least(v_ceiling, v_last + interval '1 microsecond');

    WITH f AS (
      SELECT * FROM public.ca_hand_player_facts(v_cur, v_end)
    ), upd AS (
      UPDATE public.ca_hand_player_stat s
      SET my_blind = f.my_blind,
          invested_actions = f.invested_actions,
          won_amt = f.won_amt,
          profit = f.profit
      FROM f
      WHERE s.user_id = f.user_id AND s.hand_id = f.hand_id
        AND (s.profit IS DISTINCT FROM f.profit
             OR s.invested_actions IS DISTINCT FROM f.invested_actions
             OR s.my_blind IS DISTINCT FROM f.my_blind)
      RETURNING 1
    )
    SELECT count(*) INTO v_k FROM upd;
    v_changed := v_changed + coalesce(v_k, 0);
    v_hands := v_hands + v_chunk;
    v_cur := v_end;
  END LOOP;

  v_done := (v_cur >= v_ceiling);

  UPDATE public.ca_hand_player_stat_repair_state
  SET cursor_at = v_cur, hands_seen = hands_seen + v_hands,
      rows_changed = rows_changed + v_changed, done = v_done, updated_at = now()
  WHERE id;

  IF v_done THEN
    BEGIN
      PERFORM cron.unschedule('ca-stats-money-repair');
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'ca_repair_hand_player_stat_money: could not unschedule: %', SQLERRM;
    END;
  END IF;

  RETURN jsonb_build_object('cursor_at', v_cur, 'ceiling_at', v_ceiling,
                            'hands', v_hands, 'rows_changed', v_changed, 'done', v_done);
END;
$$;


ALTER FUNCTION public.ca_repair_hand_player_stat_money(p_max_hands integer) OWNER TO postgres;

--
-- Name: ca_reporting_club_for_activity(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_reporting_club_for_activity(p_user_id uuid, p_union_id uuid, p_fallback_club_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_union_id IS NOT NULL THEN (
      SELECT cm.club_id
        FROM public.club_members cm
        JOIN public.union_clubs uc
          ON uc.club_id = cm.club_id
         AND uc.union_id = p_union_id
       WHERE cm.user_id = p_user_id
       ORDER BY cm.joined_at ASC NULLS LAST, cm.club_id
       LIMIT 1
    )
    WHEN p_fallback_club_id IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.club_members cm
         WHERE cm.club_id = p_fallback_club_id
           AND cm.user_id = p_user_id
      ) THEN p_fallback_club_id
    ELSE NULL
  END;
$$;


ALTER FUNCTION public.ca_reporting_club_for_activity(p_user_id uuid, p_union_id uuid, p_fallback_club_id uuid) OWNER TO postgres;

--
-- Name: ca_reporting_tournament_clubs_for_user(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_reporting_tournament_clubs_for_user(p_user_id uuid) RETURNS TABLE(club_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT h.club_id
    FROM (
      SELECT DISTINCT ON (uc.union_id) cm.club_id, uc.union_id
        FROM public.club_members cm
        JOIN public.union_clubs uc ON uc.club_id = cm.club_id
       WHERE cm.user_id = p_user_id
       ORDER BY uc.union_id, cm.joined_at ASC NULLS LAST, cm.club_id
    ) h
  UNION
  SELECT cm.club_id
    FROM public.club_members cm
   WHERE cm.user_id = p_user_id
     AND NOT EXISTS (
       SELECT 1 FROM public.union_clubs uc WHERE uc.club_id = cm.club_id
     );
$$;


ALTER FUNCTION public.ca_reporting_tournament_clubs_for_user(p_user_id uuid) OWNER TO postgres;

--
-- Name: ca_roll_hand_stats(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_roll_hand_stats(p_limit integer DEFAULT 20000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '10min'
    AS $$
DECLARE
  v_floor timestamptz;
  v_next  timestamptz;
  v_hands int;
BEGIN
  SELECT rolled_floor INTO v_floor FROM ca_hand_player_stat_state WHERE id;
  IF v_floor IS NULL THEN
    SELECT max(created_at) + interval '1 second' INTO v_floor FROM hand_history;
    IF v_floor IS NULL THEN RETURN 0; END IF;
  END IF;

  SELECT min(created_at), count(*) INTO v_next, v_hands
  FROM (SELECT created_at FROM hand_history
         WHERE created_at < v_floor
         ORDER BY created_at DESC LIMIT p_limit) q;

  IF v_next IS NULL OR v_hands = 0 THEN
    UPDATE ca_hand_player_stat_state SET complete = true, updated_at = now() WHERE id;
    RETURN 0;
  END IF;

  IF v_next >= v_floor THEN
    v_next := v_floor - interval '1 microsecond';
  END IF;

  INSERT INTO ca_hand_player_stat (
    user_id, hand_id, created_at, is_cash, tournament_id, game_variant,
    big_blind, small_blind, n_players, seat_position, my_blind, won_amt, is_winner,
    invested_actions, aggro_cnt, call_cnt, vpip, pfr, folded, three_bet,
    three_bet_opp, faced_three_bet, folded_to_three_bet, cbet_opp, cbet_made,
    showdown, hand_secs, profit)
  SELECT
    f.user_id, f.hand_id, f.created_at, f.is_cash, f.tournament_id, f.game_variant,
    f.big_blind, f.small_blind, f.n_players, f.seat_position, f.my_blind, f.won_amt, f.is_winner,
    f.invested_actions, f.aggro_cnt, f.call_cnt, f.vpip, f.pfr, f.folded, f.three_bet,
    f.three_bet_opp, f.faced_three_bet, f.folded_to_three_bet, f.cbet_opp, f.cbet_made,
    f.showdown, f.hand_secs, f.profit
  FROM ca_hand_player_facts(v_next, v_floor) f
  ON CONFLICT (user_id, hand_id) DO NOTHING;

  UPDATE ca_hand_player_stat_state
     SET rolled_floor = v_next,
         rolled_ceil  = coalesce(rolled_ceil, (SELECT max(created_at) FROM hand_history)),
         updated_at   = now()
   WHERE id;

  RETURN v_hands;
END;
$$;


ALTER FUNCTION public.ca_roll_hand_stats(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION ca_roll_hand_stats(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_roll_hand_stats(p_limit integer) IS 'Rolls one chunk of hand_history into ca_hand_player_stat, newest first, and returns the hand count consumed. Loop until it returns 0.';


--
-- Name: ca_roll_hand_stats_forward(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_roll_hand_stats_forward() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '4min'
    AS $$
DECLARE
  v_ceil timestamptz;
  v_start timestamptz;
  v_now timestamptz := now();
  v_deadline timestamptz := clock_timestamp() + interval '100 seconds';
  v_last_hand_at timestamptz;
  v_end timestamptz;
  v_hands int;
  v_total int := 0;
  v_over uuid[];
  v_chunk constant int := 2000;
  v_max_chunks constant int := 12;
  v_i int := 0;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('ca_roll_hand_stats_forward')) THEN
    RETURN 0;
  END IF;

  SELECT rolled_ceil INTO v_ceil
  FROM public.ca_hand_player_stat_state
  WHERE id
  FOR UPDATE;

  IF v_ceil IS NULL OR v_ceil >= v_now THEN RETURN 0; END IF;
  v_start := v_ceil;

  WHILE v_i < v_max_chunks AND clock_timestamp() < v_deadline AND v_ceil < v_now LOOP
    v_i := v_i + 1;

    SELECT max(created_at) INTO v_last_hand_at
    FROM (
      SELECT created_at
      FROM public.hand_history
      WHERE created_at >= v_ceil AND created_at < v_now
      ORDER BY created_at, id
      LIMIT v_chunk
    ) bounded;

    IF v_last_hand_at IS NULL THEN
      v_ceil := v_now;
      EXIT;
    END IF;

    v_end := least(v_now, v_last_hand_at + interval '1 microsecond');

    SELECT count(*) INTO v_hands
    FROM public.hand_history
    WHERE created_at >= v_ceil AND created_at < v_end;

    INSERT INTO public.ca_hand_player_stat (
      user_id, hand_id, created_at, is_cash, tournament_id, game_variant,
      big_blind, small_blind, n_players, seat_position, my_blind, won_amt, is_winner,
      invested_actions, aggro_cnt, call_cnt, vpip, pfr, folded, three_bet,
      three_bet_opp, faced_three_bet, folded_to_three_bet, cbet_opp, cbet_made,
      showdown, hand_secs, profit)
    SELECT
      f.user_id, f.hand_id, f.created_at, f.is_cash, f.tournament_id, f.game_variant,
      f.big_blind, f.small_blind, f.n_players, f.seat_position, f.my_blind, f.won_amt, f.is_winner,
      f.invested_actions, f.aggro_cnt, f.call_cnt, f.vpip, f.pfr, f.folded, f.three_bet,
      f.three_bet_opp, f.faced_three_bet, f.folded_to_three_bet, f.cbet_opp, f.cbet_made,
      f.showdown, f.hand_secs, f.profit
    FROM public.ca_hand_player_facts(v_ceil, v_end) f
    ON CONFLICT (user_id, hand_id) DO NOTHING;

    v_total := v_total + coalesce(v_hands, 0);
    v_ceil := v_end;
  END LOOP;

  -- Retention (1,000 rows per player), for every player with a row in the
  -- window this run covered, whoever wrote it.
  SELECT array_agg(user_id) INTO v_over
  FROM (
    SELECT user_id
    FROM public.ca_hand_player_stat
    WHERE user_id IN (SELECT DISTINCT user_id FROM public.ca_hand_player_stat
                      WHERE created_at >= v_start AND created_at < v_ceil)
    GROUP BY user_id
    HAVING count(*) > 1000
  ) o;

  IF v_over IS NOT NULL THEN
    DELETE FROM public.ca_hand_player_stat s
    USING (
      SELECT user_id, hand_id,
             row_number() OVER (PARTITION BY user_id ORDER BY created_at DESC) AS rn
      FROM public.ca_hand_player_stat
      WHERE user_id = ANY(v_over)
    ) r
    WHERE r.rn > 1000 AND s.user_id = r.user_id AND s.hand_id = r.hand_id;
  END IF;

  UPDATE public.ca_hand_player_stat_state
  SET rolled_ceil = greatest(coalesce(rolled_ceil, v_ceil), v_ceil), updated_at = now()
  WHERE id;

  RETURN v_total;
END;
$$;


ALTER FUNCTION public.ca_roll_hand_stats_forward() OWNER TO postgres;

--
-- Name: ca_stats_health(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_stats_health() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH idx AS (
    SELECT idx_ceil, backfill_complete, rows_indexed, updated_at
    FROM public.ca_hand_player_idx_state WHERE id
  ),
  -- The last three minutes of hands, less a 90 s grace for the write itself:
  -- every one must already carry a stat row, because the trigger writes it in
  -- the same transaction as the hand.
  recent AS (
    SELECT count(*)::int AS hands,
           count(*) FILTER (WHERE NOT EXISTS (
             SELECT 1 FROM public.ca_hand_player_stat s WHERE s.hand_id = h.id
           ))::int AS without_stat
    FROM hand_history h
    WHERE h.created_at >= now() - interval '3 minutes 30 seconds'
      AND h.created_at <  now() - interval '90 seconds'
  ),
  repair AS (
    SELECT done, cursor_at, ceiling_at, hands_seen, rows_changed, updated_at
    FROM public.ca_hand_player_stat_repair_state WHERE id
  ),
  seatfill AS (
    SELECT done, cursor_at, rows_added FROM public.ca_idx_every_seat_state WHERE id
  ),
  audit AS (
    SELECT ran_at, hands, button_disagree, showdown_disagree, hands_without_stat,
           player_hands_without_idx, human_player_hands, human_without_facts,
           allin_showdown_7d, allin_showdown_without_equity_7d, duration_ms
    FROM public.ca_stats_witness_audit_log
    ORDER BY ran_at DESC LIMIT 1
  )
  SELECT jsonb_build_object(
    'checkedAt',            now(),
    'indexCeil',            (SELECT idx_ceil FROM idx),
    'indexLagSeconds',      (SELECT extract(epoch FROM (now() - idx_ceil))::numeric(12,1) FROM idx),
    'indexBackfillComplete',(SELECT backfill_complete FROM idx),
    'indexRows',            (SELECT rows_indexed FROM idx),
    'recentHands',          (SELECT hands FROM recent),
    'recentHandsWithoutStat', (SELECT without_stat FROM recent),
    'repair', (SELECT jsonb_build_object(
                 'done', done, 'cursorAt', cursor_at, 'ceilingAt', ceiling_at,
                 'handsSeen', hands_seen, 'rowsChanged', rows_changed, 'updatedAt', updated_at)
               FROM repair),
    'seatBackfill', (SELECT jsonb_build_object('done', done, 'cursorAt', cursor_at, 'rowsAdded', rows_added)
                     FROM seatfill),
    'evCoverage7d', (SELECT jsonb_build_object(
                       'allInShowdowns', allin_showdown_7d,
                       'withoutEquity', allin_showdown_without_equity_7d,
                       'ratio', CASE WHEN allin_showdown_7d > 0
                                     THEN round((allin_showdown_7d - allin_showdown_without_equity_7d)::numeric
                                                / allin_showdown_7d, 4)
                                     ELSE NULL END)
                     FROM audit),
    'lastAudit', (SELECT jsonb_build_object(
                    'ranAt', ran_at, 'hands', hands,
                    'buttonDisagree', button_disagree,
                    'showdownDisagree', showdown_disagree,
                    'handsWithoutStat', hands_without_stat,
                    'playerHandsWithoutIdx', player_hands_without_idx,
                    'humanPlayerHands', human_player_hands,
                    'humanWithoutFacts', human_without_facts,
                    'durationMs', duration_ms)
                  FROM audit)
  );
$$;


ALTER FUNCTION public.ca_stats_health() OWNER TO postgres;

--
-- Name: FUNCTION ca_stats_health(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_stats_health() IS 'The stats pipeline in one cheap read: player->hand index lag, whether the last three minutes of hands all have stat rows, the money repair cursor, and the last witness audit. Polled by the engine every minute for /health and /metrics. Service role only.';


--
-- Name: ca_stats_witness_audit(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_stats_witness_audit(p_minutes integer DEFAULT 10, p_grace_seconds integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  t0                  timestamptz := clock_timestamp();
  v_to                timestamptz;
  v_from              timestamptz;
  v_hands             integer := 0;
  v_player_hands      integer := 0;
  v_with_posts        integer := 0;
  v_button_disagree   integer := 0;
  v_showdown_disagree integer := 0;
  v_without_stat      integer := 0;
  v_without_idx       integer := 0;
  v_human_hands       integer := 0;
  v_human_no_facts    integer := 0;
  v_allin_sd          integer := 0;
  v_allin_sd_no_eq    integer := 0;
  v_idx_lag           numeric;
  v_repair_done       boolean;
  v_row               public.ca_stats_witness_audit_log;
BEGIN
  -- The grace keeps the trigger's own write and the settlement writer's
  -- (asynchronous, seconds behind the hand) out of the window, so a hand
  -- that is simply still being written is not counted as a gap.
  v_to   := now() - make_interval(secs => greatest(p_grace_seconds, 0));
  v_from := v_to  - make_interval(mins => greatest(p_minutes, 1));

  -- 2a. The button against the blind posts. The seat that posted the small
  -- blind sits directly after the button in seat order (heads-up the small
  -- blind IS the button). A hand without post rows cannot be judged and is
  -- counted only in `hands`.
  WITH h AS (
    SELECT id, button_seat::int AS stored, players, coalesce(actions, '[]'::jsonb) AS actions
    FROM hand_history
    WHERE created_at >= v_from AND created_at < v_to
  ),
  seats AS (
    SELECT h.id AS hand_id, pl->>'userId' AS puid, (pl->>'seat')::int AS seat
    FROM h CROSS JOIN LATERAL jsonb_array_elements(h.players) pl
  ),
  sm AS (
    SELECT hand_id, array_agg(seat ORDER BY seat) AS seats, count(*)::int AS n
    FROM seats GROUP BY hand_id
  ),
  posts AS (
    SELECT a.hand_id, min(s.seat) AS sb_seat
    FROM (
      SELECT h.id AS hand_id, x.act->>'userId' AS auid, lower(x.act->>'action') AS action
      FROM h CROSS JOIN LATERAL jsonb_array_elements(h.actions) x(act)
    ) a
    JOIN seats s ON s.hand_id = a.hand_id AND s.puid = a.auid
    WHERE a.action IN ('sb', 'post_sb', 'small_blind')
    GROUP BY a.hand_id
  ),
  judged AS (
    SELECT h.id, h.stored, sm.n, (p.sb_seat IS NOT NULL) AS has_posts,
      CASE
        WHEN p.sb_seat IS NULL OR array_position(sm.seats, p.sb_seat) IS NULL THEN NULL
        WHEN sm.n = 2 THEN p.sb_seat
        ELSE sm.seats[((array_position(sm.seats, p.sb_seat) - 2 + sm.n) % sm.n) + 1]
      END AS derived
    FROM h
    JOIN sm ON sm.hand_id = h.id
    LEFT JOIN posts p ON p.hand_id = h.id
  )
  SELECT count(*)::int,
         coalesce(sum(n), 0)::int,
         count(*) FILTER (WHERE has_posts)::int,
         count(*) FILTER (WHERE has_posts AND derived IS DISTINCT FROM stored)::int
    INTO v_hands, v_player_hands, v_with_posts, v_button_disagree
  FROM judged;

  -- 2b. The derived showdown flag against the engine's showdown roster.
  SELECT count(*)::int INTO v_showdown_disagree
  FROM public.ca_hand_player_facts_range(v_from, v_to, NULL) f
  JOIN hand_history h ON h.id = f.hand_id
  WHERE f.showdown IS DISTINCT FROM EXISTS (
    SELECT 1 FROM jsonb_array_elements(coalesce(h.showdown, '[]'::jsonb)) sd
    WHERE sd->>'user_id' = f.user_id::text
  );

  -- 2c. Hands with no stat row at all (uses idx_ca_hand_player_stat_hand_id).
  SELECT count(*)::int INTO v_without_stat
  FROM hand_history h
  WHERE h.created_at >= v_from AND h.created_at < v_to
    AND NOT EXISTS (SELECT 1 FROM public.ca_hand_player_stat s WHERE s.hand_id = h.id);

  -- 2d. Seats with no index row. Every uuid-shaped seat, horse or human,
  -- must have one (uses idx_ca_hand_player_idx_hand_id).
  SELECT count(*)::int INTO v_without_idx
  FROM (
    SELECT h.id AS hand_id, (pl->>'userId')::uuid AS uid
    FROM hand_history h
    CROSS JOIN LATERAL jsonb_array_elements(coalesce(h.players, '[]'::jsonb)) pl
    WHERE h.created_at >= v_from AND h.created_at < v_to
      AND (pl->>'userId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  ) seat
  WHERE NOT EXISTS (
    SELECT 1 FROM public.ca_hand_player_idx i WHERE i.hand_id = seat.hand_id AND i.user_id = seat.uid
  );

  -- 2e. Human player-hands with no settlement row. ca_hand_facts is written
  -- for human seats (and horses at NIT tables) by the engine's handFacts
  -- writer; a human seat without one means the page fell back to
  -- reconstruction for that hand.
  SELECT count(*)::int,
         count(*) FILTER (WHERE NOT EXISTS (
           SELECT 1 FROM public.ca_hand_facts x
           WHERE x.hand_id = hp.hand_id AND x.user_id = hp.uid
         ))::int
    INTO v_human_hands, v_human_no_facts
  FROM (
    SELECT h.id AS hand_id, (pl->>'userId')::uuid AS uid
    FROM hand_history h
    CROSS JOIN LATERAL jsonb_array_elements(h.players) pl
    WHERE h.created_at >= v_from AND h.created_at < v_to
      AND h.has_human IS TRUE
      AND (pl->>'userId') ~ '^[0-9a-fA-F-]{36}$'
  ) hp
  JOIN public.profiles pr ON pr.id = hp.uid AND NOT coalesce(pr.is_horse, false);

  -- 2f. EV coverage, trailing seven days (phase 3, refined the same day).
  --
  -- What the engine prices: an ALL-IN RUNOUT, i.e. the moment a stack is
  -- committed with cards to come and NO FURTHER BETTING is possible
  -- (HandController.advanceStage parks the hand when fewer than two players
  -- can still act, and broadcastAllInEquity fires there). A short stack
  -- shoving into two players who keep betting a side pot is NOT a runout:
  -- the hand plays on, one of them may fold on the river, and the shover
  -- reaches showdown with no equity figure by design, the same rule every
  -- tracker uses. The first cut of this measure counted those as gaps and
  -- read 715 owed / 11 missing (98.46%); ten of the eleven were exactly
  -- that, side-pot action after the all-in. Read against the action log
  -- the owed set is 711 and the gap is ONE hand (7be0defa, a 3-way bomb pot
  -- runout on 2026-09-01 whose equity broadcast never reached settlement).
  --
  -- So a seat is OWED equity when it was all-in before the river, reached
  -- showdown, and either carries a figure or nobody checked, bet or raised
  -- after the hand's last all-in. hand_history is read by primary key for
  -- the ~400 all-in hands a week; a hand the pruner has already taken is
  -- unknown and counted as neither owed nor missing. A river all-in has no
  -- cards to come and is not counted at all.
  WITH cand AS (
    SELECT f.hand_id, f.all_in_equity
    FROM public.ca_hand_facts f
    WHERE f.was_all_in = true
      AND f.went_to_showdown
      AND coalesce(f.all_in_street, '') <> 'river'
      AND f.played_at >= now() - interval '7 days'
  ), hands AS (
    SELECT c.hand_id,
           (SELECT bool_or(a.act->>'action' IN ('check', 'bet', 'raise') AND a.ord > la.last_allin)
              FROM public.hand_history h
              CROSS JOIN LATERAL (
                SELECT max(b.ord) AS last_allin
                FROM jsonb_array_elements(h.actions) WITH ORDINALITY b(act, ord)
                WHERE b.act->>'action' IN ('all_in', 'allin')
              ) la
              CROSS JOIN LATERAL jsonb_array_elements(h.actions) WITH ORDINALITY a(act, ord)
             WHERE h.id = c.hand_id) AS betting_continued
    FROM (SELECT DISTINCT hand_id FROM cand) c
  )
  SELECT count(*) FILTER (WHERE c.all_in_equity IS NOT NULL
                             OR NOT coalesce(h.betting_continued, true))::int,
         count(*) FILTER (WHERE c.all_in_equity IS NULL
                            AND NOT coalesce(h.betting_continued, true))::int
    INTO v_allin_sd, v_allin_sd_no_eq
  FROM cand c
  JOIN hands h USING (hand_id);

  SELECT extract(epoch FROM (now() - idx_ceil))::numeric(12,1) INTO v_idx_lag
  FROM public.ca_hand_player_idx_state WHERE id;
  SELECT done INTO v_repair_done FROM public.ca_hand_player_stat_repair_state WHERE id;

  INSERT INTO public.ca_stats_witness_audit_log (
    window_from, window_to, hands, player_hands, hands_with_posts,
    button_disagree, showdown_disagree, hands_without_stat, player_hands_without_idx,
    human_player_hands, human_without_facts, allin_showdown_7d, allin_showdown_without_equity_7d,
    idx_lag_seconds, repair_done, duration_ms
  ) VALUES (
    v_from, v_to, v_hands, v_player_hands, v_with_posts,
    v_button_disagree, v_showdown_disagree, v_without_stat, v_without_idx,
    v_human_hands, v_human_no_facts, v_allin_sd, v_allin_sd_no_eq,
    v_idx_lag, v_repair_done,
    (extract(epoch FROM (clock_timestamp() - t0)) * 1000)::int
  )
  RETURNING * INTO v_row;

  -- Thirty days of history is plenty; the row is 100 bytes and it runs 96
  -- times a day.
  DELETE FROM public.ca_stats_witness_audit_log WHERE ran_at < now() - interval '30 days';

  RETURN to_jsonb(v_row);
END;
$_$;


ALTER FUNCTION public.ca_stats_witness_audit(p_minutes integer, p_grace_seconds integer) OWNER TO postgres;

--
-- Name: FUNCTION ca_stats_witness_audit(p_minutes integer, p_grace_seconds integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_stats_witness_audit(p_minutes integer, p_grace_seconds integer) IS 'Checks the engine''s recorded button_seat and showdown roster against the action log over a recent window, and counts hands with no stat row and human seats with no settlement row. Writes one row to ca_stats_witness_audit_log and returns it. Zero disagreements is healthy. Service role only.';


--
-- Name: ca_touch_member_fee_rollup(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_touch_member_fee_rollup() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE v_last timestamptz;
BEGIN
  SELECT last_run_at INTO v_last FROM public.member_fee_rollup_state WHERE id;
  IF v_last IS NOT NULL AND v_last > now() - interval '30 seconds' THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'refreshed recently');
  END IF;
  RETURN public.fn_refresh_member_fee_rollup(4000);
END;
$$;


ALTER FUNCTION public.ca_touch_member_fee_rollup() OWNER TO postgres;

--
-- Name: ca_union_insurance_pnl(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_union_insurance_pnl(p_union_id uuid, p_days integer DEFAULT 14) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
  v_from date := (now() AT TIME ZONE 'UTC')::date - (greatest(least(coalesce(p_days,14), 90), 1) - 1);
BEGIN
  IF NOT ca_can_oversee_union(p_union_id) THEN
    RAISE EXCEPTION 'not authorized for this union' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'union_id', p_union_id,
    'range_days', greatest(least(coalesce(p_days,14), 90), 1),
    'totals', (
      SELECT jsonb_build_object(
        'contracts', coalesce(count(*), 0),
        'premiums',  round(coalesce(sum(it.premium), 0), 2),
        'payouts',   round(coalesce(sum(it.payout), 0), 2),
        'net',       round(coalesce(sum(it.premium - it.payout), 0), 2))
      FROM insurance_transactions it
      WHERE it.union_id = p_union_id AND it.bank_type = 'union'
        AND it.created_at >= v_from::timestamptz
    ),
    -- Guarantee overlays this union's bank covered.
    'overlay', (
      SELECT jsonb_build_object(
        'events', coalesce(count(*), 0),
        'funded', round(coalesce(sum(o.amount), 0), 2))
      FROM tournament_guarantee_overlays o
      WHERE o.bank_type = 'union' AND o.bank_entity_id = p_union_id
        AND o.funded_at >= v_from::timestamptz
    ),
    'daily', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'd', g.day::date,
               'contracts', coalesce(i.n, 0),
               'premiums', coalesce(i.prem, 0),
               'payouts', coalesce(i.pay, 0),
               'net', coalesce(i.net, 0),
               'overlay', coalesce(ov.funded, 0))
             ORDER BY g.day)
      FROM generate_series(v_from, (now() AT TIME ZONE 'UTC')::date, interval '1 day') g(day)
      LEFT JOIN (
        SELECT (it.created_at AT TIME ZONE 'UTC')::date AS d,
               count(*) AS n,
               round(sum(it.premium), 2) AS prem,
               round(sum(it.payout), 2) AS pay,
               round(sum(it.premium - it.payout), 2) AS net
          FROM insurance_transactions it
         WHERE it.union_id = p_union_id AND it.bank_type = 'union'
           AND it.created_at >= v_from::timestamptz
         GROUP BY 1
      ) i ON i.d = g.day::date
      LEFT JOIN (
        SELECT (o.funded_at AT TIME ZONE 'UTC')::date AS d,
               round(sum(o.amount), 2) AS funded
          FROM tournament_guarantee_overlays o
         WHERE o.bank_type = 'union' AND o.bank_entity_id = p_union_id
           AND o.funded_at >= v_from::timestamptz
         GROUP BY 1
      ) ov ON ov.d = g.day::date
    ), '[]'::jsonb),
    'by_club', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'club_id', q.club_id, 'club_name', q.club_name,
               'contracts', q.n, 'premiums', q.prem, 'payouts', q.pay, 'net', q.net)
             ORDER BY q.net DESC)
      FROM (
        SELECT it.club_id, coalesce(c.name, 'Unknown') AS club_name,
               count(*) AS n,
               round(sum(it.premium), 2) AS prem,
               round(sum(it.payout), 2) AS pay,
               round(sum(it.premium - it.payout), 2) AS net
          FROM insurance_transactions it
          LEFT JOIN clubs c ON c.id = it.club_id
         WHERE it.union_id = p_union_id AND it.bank_type = 'union'
           AND it.created_at >= v_from::timestamptz
         GROUP BY it.club_id, c.name
      ) q
    ), '[]'::jsonb),
    'generated_at', now()
  ) INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION public.ca_union_insurance_pnl(p_union_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: ca_union_record_presettlement(uuid, uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_union_record_presettlement(p_union_id uuid, p_club_id uuid, p_amount numeric, p_method text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_res jsonb;
  v_total numeric;
BEGIN
  IF NOT ca_can_oversee_union(p_union_id) THEN
    RAISE EXCEPTION 'not authorized for this union' USING ERRCODE = '42501';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'enter an amount greater than zero');
  END IF;

  -- The underlying function does its own membership and authorization checks
  -- and returns a jsonb result rather than raising; pass it straight through.
  v_res := fn_union_record_presettlement(p_union_id, p_club_id, p_amount,
                                         p_method, p_reference, p_note);
  IF NOT COALESCE((v_res->>'success')::boolean, false) THEN
    RETURN v_res;
  END IF;

  -- What this club has been credited that is not yet tied to a statement -
  -- i.e. what the next square-up will subtract.
  SELECT COALESCE(SUM(amount), 0) INTO v_total
    FROM union_presettlements
   WHERE union_id = p_union_id AND club_id = p_club_id
     AND applied_settlement_id IS NULL;

  RETURN v_res || jsonb_build_object('unapplied_total', round(v_total, 2));
END;
$$;


ALTER FUNCTION public.ca_union_record_presettlement(p_union_id uuid, p_club_id uuid, p_amount numeric, p_method text, p_reference text, p_note text) OWNER TO postgres;

--
-- Name: ca_union_set_statement_paid(uuid, boolean, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_union_set_statement_paid(p_invoice_id uuid, p_paid boolean DEFAULT true, p_amount numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_inv      settlement_invoices%ROWTYPE;
  v_union    uuid;
  v_owed     numeric;
  v_prev     numeric;
  v_add      numeric;
  v_total    numeric;
  v_status   text;
  v_payments jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'sign in required' USING ERRCODE = '42501';
  END IF;

  -- lock the row: two union admins clicking at once must not both read the
  -- same paid_total and each add their payment to it
  SELECT * INTO v_inv FROM settlement_invoices
   WHERE id = p_invoice_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'statement not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_inv.invoice_type <> 'union_weekly_squareup' THEN
    RAISE EXCEPTION 'not a weekly square-up statement' USING ERRCODE = '22023';
  END IF;

  -- Authority follows the invoice issuer, never the club's later membership.
  v_union := NULLIF(v_inv.breakdown->>'union_id','')::uuid;
  IF v_union IS NULL OR NOT ca_can_oversee_union(v_union) THEN
    RAISE EXCEPTION 'not authorized for this union' USING ERRCODE = '42501';
  END IF;

  IF v_inv.status = 'cancelled' THEN
    RAISE EXCEPTION 'this statement was cancelled' USING ERRCODE = '22023';
  END IF;

  -- the amount owed is an absolute: a statement where the union owes the club
  -- is settled by the same act of paying it, in the other direction
  v_owed     := abs(COALESCE(v_inv.net_amount, 0));
  v_prev     := COALESCE((v_inv.breakdown->>'paid_total')::numeric, 0);
  v_payments := COALESCE(v_inv.breakdown->'payments', '[]'::jsonb);

  IF p_paid IS NULL THEN
    RAISE EXCEPTION 'payment action is required' USING ERRCODE = '22023';
  END IF;
  IF v_inv.net_amount IS NULL OR EXISTS (
    SELECT 1 FROM unnest(ARRAY[v_inv.net_amount, v_prev]) n
    WHERE n::text IN ('NaN','Infinity','-Infinity') OR n <> round(n,2)
  ) OR v_prev < 0 THEN
    RAISE EXCEPTION 'statement amounts must be finite whole cents' USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NOT NULL AND
    (p_amount::text IN ('NaN','Infinity','-Infinity') OR p_amount <= 0 OR p_amount <> round(p_amount,2)) THEN
    RAISE EXCEPTION 'payment amount must be positive finite whole cents' USING ERRCODE = '22023';
  END IF;

  IF p_paid THEN
    -- no amount given means "settled in full", which is the common case and
    -- should not require the caller to restate a number the row already holds
    v_add   := COALESCE(p_amount, GREATEST(v_owed - v_prev, 0));
    IF v_add <= 0 AND v_prev >= v_owed THEN
      RETURN jsonb_build_object(
        'success', true, 'already_settled', true,
        'invoice_id', p_invoice_id, 'status', v_inv.status,
        'paid_total', v_prev, 'owed', v_owed);
    END IF;
    v_total := round(v_prev + GREATEST(v_add, 0), 2);
    -- A short payment remains outstanding down to the last cent.
    v_status := CASE WHEN v_total >= v_owed THEN 'paid'
      WHEN v_inv.status = 'paid' THEN 'generated' ELSE v_inv.status END;
    v_payments := v_payments || jsonb_build_object(
      'amount', round(GREATEST(v_add, 0), 2),
      'at', now(),
      'by', v_uid,
      'note', NULLIF(btrim(COALESCE(p_note, '')), ''));
  ELSE
    -- reopening: mistakes get made, and a statement that can only ever move
    -- one way turns a misclick into a permanent falsehood in the record. The
    -- payment history is kept, with the reversal appended to it.
    v_total  := 0;
    v_status := 'generated';
    v_payments := v_payments || jsonb_build_object(
      'amount', 0, 'reversal', true, 'at', now(), 'by', v_uid,
      'note', NULLIF(btrim(COALESCE(p_note, '')), ''));
  END IF;

  UPDATE settlement_invoices
     SET status     = v_status,
         updated_at = now(),
         breakdown  = COALESCE(breakdown, '{}'::jsonb) || jsonb_build_object(
           'paid_total', v_total,
           'paid_at',    CASE WHEN v_status = 'paid' THEN now() ELSE NULL END,
           'paid_by',    CASE WHEN v_status = 'paid' THEN v_uid  ELSE NULL END,
           'payments',   v_payments)
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object(
    'success', true,
    'invoice_id', p_invoice_id,
    'status', v_status,
    'paid_total', v_total,
    'owed', v_owed,
    'fully_settled', (v_status = 'paid'));
END;
$$;


ALTER FUNCTION public.ca_union_set_statement_paid(p_invoice_id uuid, p_paid boolean, p_amount numeric, p_note text) OWNER TO postgres;

--
-- Name: ca_union_statement_board(uuid, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_union_statement_board(p_union_id uuid, p_period_end date DEFAULT NULL::date, p_history integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hist int := GREATEST(LEAST(COALESCE(p_history, 8), 52), 1);
  v_end  date;
  v_out  jsonb;
BEGIN
  IF NOT ca_can_oversee_union(p_union_id) THEN
    RAISE EXCEPTION 'not authorized for this union' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(p_period_end, MAX((s.breakdown->>'period_end')::date))
    INTO v_end
    FROM settlement_invoices s
   WHERE s.invoice_type = 'union_weekly_squareup'
     AND s.breakdown->>'union_id' = p_union_id::text;

  WITH clubs_in_union AS (
    -- Current members must show missing invoices. Former members keep their
    -- historical invoice under the union that issued it, after membership moves.
    SELECT c.id AS club_id, c.name AS club_name, c.code AS club_code, c.slug AS club_slug
      FROM clubs c
     WHERE EXISTS (SELECT 1 FROM union_clubs uc WHERE uc.club_id=c.id AND uc.union_id=p_union_id)
        OR EXISTS (SELECT 1 FROM settlement_invoices s WHERE s.club_id=c.id
          AND s.invoice_type='union_weekly_squareup'
          AND s.breakdown->>'union_id'=p_union_id::text
          AND (v_end IS NULL OR (s.breakdown->>'period_end')::date=v_end))
  ),
  period_invoices AS (
    SELECT DISTINCT ON (s.club_id) s.*
      FROM settlement_invoices s
      JOIN clubs_in_union cu ON cu.club_id = s.club_id
     WHERE s.invoice_type = 'union_weekly_squareup'
       AND s.breakdown->>'union_id' = p_union_id::text
       AND (v_end IS NULL OR (s.breakdown->>'period_end')::date = v_end)
     ORDER BY s.club_id, s.created_at DESC
  ),
  board AS (
    SELECT cu.club_id, cu.club_name, cu.club_code, cu.club_slug,
           i.id                            AS invoice_id,
           (i.net_amount IS NOT NULL
             AND i.breakdown->>'rake_generated' IS NOT NULL
             AND i.breakdown->>'rakeback_due' IS NOT NULL
             AND i.breakdown->>'union_fee_kept' IS NOT NULL) AS snapshot_complete,
           COALESCE(i.status, 'missing')   AS status,
           i.created_at                    AS issued_at,
           i.due_at,
           COALESCE(i.net_amount, 0)       AS amount,
           i.breakdown->>'direction'       AS direction,
           COALESCE(i.message_sent, false) AS message_sent,
           COALESCE((i.breakdown->>'paid_total')::numeric, 0)     AS paid_total,
           COALESCE((i.breakdown->>'rake_generated')::numeric, 0) AS rake_generated,
           COALESCE((i.breakdown->>'rakeback_due')::numeric, 0)   AS rakeback_due,
           COALESCE((i.breakdown->>'union_fee_kept')::numeric, 0) AS union_fee_kept,
           COALESCE((i.breakdown->>'players_won')::numeric, 0)    AS players_won,
           COALESCE((i.breakdown->>'eco_amount')::numeric, 0)     AS eco_amount,
           COALESCE((i.breakdown->>'presettled')::numeric, 0)     AS presettled
      FROM clubs_in_union cu
      LEFT JOIN period_invoices i ON i.club_id = cu.club_id
  ),
  history AS (
    SELECT (s.breakdown->>'period_end')::date AS period_end,
           MIN((s.breakdown->>'period_start')::date) AS period_start,
           count(*)                                  AS clubs,
           round(SUM(s.net_amount), 2)               AS total_amount,
           round(SUM(COALESCE((s.breakdown->>'rake_generated')::numeric, 0)), 2) AS rake_generated,
           round(SUM(COALESCE((s.breakdown->>'eco_amount')::numeric, 0)), 2)     AS eco_amount,
           count(*) FILTER (WHERE s.status = 'paid')                             AS paid,
           count(*) FILTER (WHERE COALESCE(s.message_sent, false))               AS delivered
      FROM settlement_invoices s
     WHERE s.invoice_type = 'union_weekly_squareup'
       AND s.breakdown->>'union_id' = p_union_id::text
       AND s.breakdown ? 'period_end'
     GROUP BY 1
     ORDER BY 1 DESC
     LIMIT v_hist
  )
  SELECT jsonb_build_object(
    'union_id', p_union_id,
    'union_name', (SELECT u.name FROM unions u WHERE u.id = p_union_id),
    'period_end', v_end,
    'period_start', (SELECT MIN((i.breakdown->>'period_start')::date) FROM period_invoices i),
    'totals', (SELECT jsonb_build_object(
                 'clubs',      count(*),
                 'issued',     count(*) FILTER (WHERE b.status <> 'missing'),
                 'missing',    count(*) FILTER (WHERE b.status = 'missing'),
                 'delivered',  count(*) FILTER (WHERE b.message_sent),
                 'paid',       count(*) FILTER (WHERE b.status = 'paid'),
                 'clubs_owe',  round(COALESCE(SUM(b.amount) FILTER (WHERE b.amount > 0), 0), 2),
                 'union_owes', round(COALESCE(SUM(-b.amount) FILTER (WHERE b.amount < 0), 0), 2),
                 'net',        round(COALESCE(SUM(b.amount), 0), 2),
                 'collected',  round(COALESCE(SUM(b.paid_total), 0), 2),
                 -- what is still out: the unpaid remainder, not the headline
                 'outstanding', round(COALESCE(SUM(
                     GREATEST(abs(b.amount) - b.paid_total, 0))
                     FILTER (WHERE b.status NOT IN ('missing','cancelled')), 0), 2),
                 'rake_generated', round(COALESCE(SUM(b.rake_generated), 0), 2),
                 'eco_amount',     round(COALESCE(SUM(b.eco_amount), 0), 2))
                 FROM board b),
    'clubs', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'club_id', b.club_id, 'club_name', b.club_name,
               'club_code', b.club_code, 'club_slug', b.club_slug,
               'invoice_id', b.invoice_id, 'status', b.status, 'snapshot_complete', b.snapshot_complete,
               'issued_at', b.issued_at, 'due_at', b.due_at,
               'amount', round(b.amount, 2), 'direction', b.direction,
               'message_sent', b.message_sent,
               'paid_total', round(b.paid_total, 2),
               'outstanding', round(GREATEST(abs(b.amount) - b.paid_total, 0), 2),
               -- overdue is derived, never stored: a stored flag needs a job to
               -- maintain it, and a job that does not run leaves the row lying
               'overdue', (b.status NOT IN ('paid','missing','cancelled')
                           AND b.due_at IS NOT NULL AND b.due_at < now()),
               'rake_generated', round(b.rake_generated, 2),
               'rakeback_due', round(b.rakeback_due, 2),
               'union_fee_kept', round(b.union_fee_kept, 2),
               'players_won', round(b.players_won, 2),
               'eco_amount', round(b.eco_amount, 2),
               'presettled', round(b.presettled, 2))
             ORDER BY (b.status = 'missing') DESC, b.amount DESC)
        FROM board b), '[]'::jsonb),
    'history', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'period_start', h.period_start, 'period_end', h.period_end,
               'clubs', h.clubs, 'total_amount', h.total_amount,
               'rake_generated', h.rake_generated, 'eco_amount', h.eco_amount,
               'paid', h.paid, 'delivered', h.delivered)
             ORDER BY h.period_end DESC)
        FROM history h), '[]'::jsonb),
    'generated_at', now()
  ) INTO v_out;

  RETURN v_out;
END;
$$;


ALTER FUNCTION public.ca_union_statement_board(p_union_id uuid, p_period_end date, p_history integer) OWNER TO postgres;

--
-- Name: calculate_agent_settlement(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_agent_settlement(p_period_id uuid, p_agent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := (SELECT auth.uid());
  v_period record;
  v_agent record;
  v_name text;
  v_earned numeric := 0;
  v_authorized boolean := false;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT * INTO v_period FROM settlement_periods WHERE id = p_period_id;
  IF v_period.id IS NULL THEN
    RAISE EXCEPTION 'settlement period % not found', p_period_id;
  END IF;

  SELECT * INTO v_agent FROM agents WHERE id = p_agent_id;
  IF v_agent.id IS NULL THEN
    RAISE EXCEPTION 'agent % not found', p_agent_id;
  END IF;

  -- Caller must be the agent, or administer the agent's club or its union
  SELECT (
    v_agent.user_id = v_caller
    OR EXISTS (
      SELECT 1 FROM clubs c
       WHERE c.id = v_agent.club_id
         AND (c.owner_id = v_caller
              OR EXISTS (SELECT 1 FROM club_members cm
                          WHERE cm.club_id = c.id AND cm.user_id = v_caller
                            AND cm.role IN ('owner','co_owner','admin')))
    )
    OR EXISTS (SELECT 1 FROM unions u
                WHERE u.id = v_period.union_id AND u.owner_id = v_caller)
  ) INTO v_authorized;
  IF NOT v_authorized THEN
    RAISE EXCEPTION 'not authorized for this agent settlement';
  END IF;

  SELECT COALESCE(SUM(amount),0) INTO v_earned
    FROM agent_commissions
   WHERE user_id = v_agent.user_id AND club_id = v_agent.club_id
     AND created_at >= v_period.start_at AND created_at < v_period.end_at;

  SELECT COALESCE(NULLIF(display_name,''), NULLIF(username,''), NULLIF(full_name,''))
    INTO v_name FROM profiles WHERE id = v_agent.user_id;

  RETURN jsonb_build_object(
    'id', v_agent.id,
    'periodId', p_period_id,
    'agentId', v_agent.id,
    'agentName', COALESCE(v_name, 'Agent ' || left(v_agent.id::text, 8)),
    'totalRakeGenerated', COALESCE(v_agent.weekly_rake_generated, 0),
    'commissionRate', v_agent.commission_rate,
    'commissionEarned', v_earned,
    'creditExtended', v_agent.credit_used,
    'creditRepaid', 0,
    'netSettlement', v_earned,
    'activePlayers', v_agent.active_player_count,
    'status', 'pending'
  );
END;
$$;


ALTER FUNCTION public.calculate_agent_settlement(p_period_id uuid, p_agent_id uuid) OWNER TO postgres;

--
-- Name: calculate_agent_spread(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_agent_spread(p_agent_id uuid, p_period_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := (SELECT auth.uid());
  v_agent record;
  v_start timestamptz;
  v_end timestamptz;
  v_own_earned numeric := 0;
  v_sub_earned numeric := 0;
  v_downlines jsonb;
  v_authorized boolean := false;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT * INTO v_agent FROM agents WHERE id = p_agent_id;
  IF v_agent.id IS NULL THEN
    RAISE EXCEPTION 'agent % not found', p_agent_id;
  END IF;

  SELECT (
    v_agent.user_id = v_caller
    OR EXISTS (
      SELECT 1 FROM clubs c
       WHERE c.id = v_agent.club_id
         AND (c.owner_id = v_caller
              OR EXISTS (SELECT 1 FROM club_members cm
                          WHERE cm.club_id = c.id AND cm.user_id = v_caller
                            AND cm.role IN ('owner','co_owner','admin')))
    )
  ) INTO v_authorized;
  IF NOT v_authorized THEN
    RAISE EXCEPTION 'not authorized for this agent';
  END IF;

  IF p_period_id IS NOT NULL THEN
    SELECT start_at, end_at INTO v_start, v_end
      FROM settlement_periods WHERE id = p_period_id;
    IF v_start IS NULL THEN
      RAISE EXCEPTION 'settlement period % not found', p_period_id;
    END IF;
  ELSE
    v_end := now();
    v_start := now() - interval '7 days';
  END IF;

  SELECT COALESCE(SUM(amount),0) INTO v_own_earned
    FROM agent_commissions
   WHERE user_id = v_agent.user_id AND club_id = v_agent.club_id
     AND created_at >= v_start AND created_at < v_end;

  SELECT COALESCE(SUM(c.amount),0) INTO v_sub_earned
    FROM sub_agents s
    JOIN agent_commissions c
      ON c.user_id = s.user_id AND c.club_id = s.club_id
     AND c.created_at >= v_start AND c.created_at < v_end
   WHERE s.parent_agent_id = v_agent.id AND s.status = 'active';

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'entityId', s.id,
      'entityType', 'agent',
      'name', COALESCE(NULLIF(pr.display_name,''), NULLIF(pr.username,''), NULLIF(pr.full_name,''), 'Sub-agent ' || left(s.id::text, 8)),
      'rate', s.commission_pct,
      'rakeGenerated', s.total_rake_generated,
      'commissionPaid', s.total_commission_paid
    ) ORDER BY s.total_rake_generated DESC), '[]'::jsonb)
    INTO v_downlines
    FROM sub_agents s
    LEFT JOIN profiles pr ON pr.id = s.user_id
   WHERE s.parent_agent_id = v_agent.id;

  RETURN jsonb_build_object(
    'agentId', v_agent.id,
    'grossCommissionRate', v_agent.commission_rate,
    'payoutToDownlines', v_sub_earned,
    'netMargin', v_own_earned,
    'downlineBreakdown', v_downlines
  );
END;
$$;


ALTER FUNCTION public.calculate_agent_spread(p_agent_id uuid, p_period_id uuid) OWNER TO postgres;

--
-- Name: calculate_cascading_commission(uuid, uuid, uuid, numeric, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_cascading_commission(p_hand_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_player_user_id uuid DEFAULT NULL::uuid, p_rake_amount numeric DEFAULT 0, p_rake_record_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_book_club     uuid;
  v_agent_user    uuid;
  v_cur_id        uuid;
  v_cur_user      uuid;
  v_cur_rate      numeric;
  v_cur_role      text;
  v_parent        uuid;
  v_remaining     numeric;
  v_slice         numeric;
  v_rate          numeric;
  v_results       jsonb := '[]'::jsonb;
  v_commission_id uuid;
  v_club_owner_id uuid;
  v_depth         int := 0;
BEGIN
  IF p_rake_amount IS NULL OR p_rake_amount <= 0 OR p_club_id IS NULL OR p_player_user_id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'commissions', v_results, 'skipped', 'missing_inputs');
  END IF;

  v_remaining := p_rake_amount;

  -- UNION LAW: attribute to the player's own club, not the union house club.
  v_book_club := COALESCE(
    public.fn_resolve_player_club_for_agent(p_player_user_id, p_club_id, p_table_id),
    p_club_id);

  -- The player's direct upline.
  SELECT cm.agent_id INTO v_agent_user
    FROM club_members cm
   WHERE cm.user_id = p_player_user_id AND cm.club_id = v_book_club
     AND cm.agent_id IS NOT NULL
   LIMIT 1;

  IF v_agent_user IS NOT NULL THEN
    SELECT a.id, a.user_id, a.commission_rate, a.role, a.parent_agent_id
      INTO v_cur_id, v_cur_user, v_cur_rate, v_cur_role, v_parent
      FROM agents a
     WHERE a.user_id = v_agent_user AND a.status = 'active'
     ORDER BY (a.club_id = v_book_club) DESC
     LIMIT 1;
  END IF;

  -- Climb: sub_agent -> agent -> super_agent, each taking its override on
  -- what remains below it.
  WHILE v_cur_id IS NOT NULL AND v_depth < 10 AND v_remaining > 0 LOOP
    v_depth := v_depth + 1;

    v_rate := CASE WHEN COALESCE(v_cur_rate,0) > 1 THEN v_cur_rate / 100.0
                   ELSE COALESCE(v_cur_rate,0) END;
    v_slice := ROUND(v_remaining * v_rate, 4);

    IF v_slice > 0 THEN
      INSERT INTO public.agent_commissions
        (club_id, user_id, amount, commission_rate, source_type, source_id, notes)
      VALUES
        (v_book_club, v_cur_user, v_slice, v_cur_rate, 'rake',
         COALESCE(p_rake_record_id, p_hand_id),
         COALESCE(v_cur_role,'agent') || ' slice (tier ' || v_depth || ')')
      RETURNING id INTO v_commission_id;

      v_results := v_results || jsonb_build_object(
        'tier', COALESCE(v_cur_role,'agent'), 'depth', v_depth,
        'user_id', v_cur_user, 'amount', v_slice, 'commission_id', v_commission_id);

      v_remaining := v_remaining - v_slice;
    END IF;

    -- step up to the override holder
    IF v_parent IS NULL THEN
      v_cur_id := NULL;
    ELSE
      SELECT a.id, a.user_id, a.commission_rate, a.role, a.parent_agent_id
        INTO v_cur_id, v_cur_user, v_cur_rate, v_cur_role, v_parent
        FROM agents a WHERE a.id = v_parent AND a.status = 'active';
      IF NOT FOUND THEN v_cur_id := NULL; END IF;
    END IF;
  END LOOP;

  -- Whatever survives the chain belongs to the club.
  SELECT owner_id INTO v_club_owner_id FROM public.clubs WHERE id = v_book_club;
  IF v_club_owner_id IS NOT NULL AND v_remaining > 0 THEN
    INSERT INTO public.agent_commissions
      (club_id, user_id, amount, commission_rate, source_type, source_id, notes)
    VALUES
      (v_book_club, v_club_owner_id, v_remaining, NULL, 'rake',
       COALESCE(p_rake_record_id, p_hand_id), 'club owner residual')
    RETURNING id INTO v_commission_id;
    v_results := v_results || jsonb_build_object('tier','owner',
      'user_id', v_club_owner_id, 'amount', v_remaining, 'commission_id', v_commission_id);
  END IF;

  UPDATE public.club_wallets
     SET period_commission_paid   = period_commission_paid   + p_rake_amount,
         lifetime_commission_paid = lifetime_commission_paid + p_rake_amount,
         updated_at = NOW()
   WHERE club_id = v_book_club;

  RETURN jsonb_build_object('success', true, 'hand_id', p_hand_id, 'club_id', v_book_club,
    'player_user_id', p_player_user_id, 'rake_amount', p_rake_amount,
    'tiers_paid', v_depth, 'commissions', v_results);
END;
$$;


ALTER FUNCTION public.calculate_cascading_commission(p_hand_id uuid, p_club_id uuid, p_player_user_id uuid, p_rake_amount numeric, p_rake_record_id uuid, p_table_id uuid) OWNER TO postgres;

--
-- Name: calculate_entry_investment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_entry_investment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE tournament_record RECORD;
BEGIN
  SELECT buyin_amount, buyin_fee, rebuy_amount, addon_amount INTO tournament_record FROM commander_tournaments WHERE id = NEW.tournament_id;
  NEW.total_invested := tournament_record.buyin_amount + COALESCE(tournament_record.buyin_fee, 0) + (NEW.rebuy_count * COALESCE(tournament_record.rebuy_amount, 0)) + (CASE WHEN NEW.addon_taken THEN COALESCE(tournament_record.addon_amount, 0) ELSE 0 END);
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.calculate_entry_investment() OWNER TO postgres;

--
-- Name: calculate_loyalty_tier(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_loyalty_tier(hours numeric) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF hours >= 500 THEN RETURN 'diamond';
  ELSIF hours >= 250 THEN RETURN 'platinum';
  ELSIF hours >= 100 THEN RETURN 'gold';
  ELSIF hours >= 50 THEN RETURN 'silver';
  ELSE RETURN 'bronze';
  END IF;
END;
$$;


ALTER FUNCTION public.calculate_loyalty_tier(hours numeric) OWNER TO postgres;

--
-- Name: calculate_pilot_metrics(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_pilot_metrics(p_venue_id integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_result JSONB;
  v_uptime DECIMAL;
  v_tickets INTEGER;
  v_adoption DECIMAL;
BEGIN
  SELECT 100 - COALESCE(AVG(CASE WHEN metric_type = 'error_rate' THEN metric_value ELSE 0 END), 0)
  INTO v_uptime FROM commander_system_health
  WHERE venue_id = p_venue_id AND recorded_at > now() - INTERVAL '7 days';

  SELECT COUNT(*) INTO v_tickets FROM commander_audit_logs
  WHERE venue_id = p_venue_id AND action_category = 'admin'
  AND action LIKE '%issue%' AND created_at > now() - INTERVAL '7 days';

  SELECT CASE WHEN COUNT(DISTINCT CASE WHEN player_id IS NOT NULL THEN id END) = 0 THEN 0
    ELSE (COUNT(DISTINCT CASE WHEN signup_method = 'app' THEN id END)::DECIMAL /
          COUNT(DISTINCT id)::DECIMAL) * 100 END
  INTO v_adoption FROM commander_waitlist
  WHERE venue_id = p_venue_id AND created_at > now() - INTERVAL '7 days';

  v_result := jsonb_build_object(
    'uptime_percentage', COALESCE(v_uptime, 100),
    'support_tickets', COALESCE(v_tickets, 0),
    'player_adoption', COALESCE(v_adoption, 0),
    'calculated_at', now()
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.calculate_pilot_metrics(p_venue_id integer) OWNER TO postgres;

--
-- Name: calculate_session_duration(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_session_duration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.check_out_at IS NOT NULL AND OLD.check_out_at IS NULL THEN
    NEW.total_time_minutes := EXTRACT(EPOCH FROM (NEW.check_out_at - NEW.check_in_at)) / 60;
    NEW.status := 'completed';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.calculate_session_duration() OWNER TO postgres;

--
-- Name: calculate_streak_multiplier(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_streak_multiplier() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$ BEGIN NEW.streak_multiplier := CASE WHEN NEW.streak >= 7 THEN 2.0 WHEN NEW.streak >= 5 THEN 1.75 WHEN NEW.streak >= 3 THEN 1.5 WHEN NEW.streak >= 1 THEN 1.25 ELSE 1.0 END; RETURN NEW; END; $$;


ALTER FUNCTION public.calculate_streak_multiplier() OWNER TO postgres;

--
-- Name: cancel_home_game(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_home_game(p_game_id uuid, p_caller_user_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_game RECORD; v_group RECORD;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;
    IF p_reason IS NOT NULL AND length(p_reason) > 1000 THEN
      RAISE EXCEPTION 'REASON_TOO_LONG' USING HINT = 'max 1000 chars';
    END IF;

    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
    IF v_game.status IN ('completed','cancelled') THEN
        RAISE EXCEPTION 'GAME_ALREADY_FINAL' USING HINT = 'status is ' || v_game.status;
    END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;

    IF v_game.host_id <> p_caller_user_id
       AND v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members
                        WHERE group_id = v_game.group_id AND user_id = p_caller_user_id
                          AND role = 'admin' AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_AUTHORIZED_TO_CANCEL'; END IF;

    UPDATE commander_home_games
       SET status='cancelled', cancelled_at=NOW(), cancelled_by=p_caller_user_id,
           cancellation_reason=p_reason, updated_at=NOW()
     WHERE id = p_game_id;

    INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (v_game.group_id, p_caller_user_id, 'game', p_game_id, 'cancelled',
            jsonb_build_object('reason', p_reason, 'scheduled_date', v_game.scheduled_date));

    RETURN jsonb_build_object(
        'success', true, 'game_id', p_game_id, 'new_status', 'cancelled',
        'rsvps_to_notify', (SELECT COUNT(*) FROM commander_home_rsvps
                             WHERE game_id = p_game_id AND response IN ('yes','maybe','waitlist'))
    );
END;
$$;


ALTER FUNCTION public.cancel_home_game(p_game_id uuid, p_caller_user_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: cash_tables_needing_engine(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cash_tables_needing_engine(p_min integer DEFAULT 2) RETURNS TABLE(table_id uuid, player_count bigint, human_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT ts.table_id,
         count(*) AS player_count,
         count(*) FILTER (WHERE p.is_horse IS NOT TRUE) AS human_count
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
    LEFT JOIN profiles p ON p.id = ts.user_id
   WHERE ts.left_at IS NULL
     AND t.tournament_id IS NULL
     AND t.status IN ('waiting', 'running', 'active')
   GROUP BY ts.table_id
  -- HORSES ARE PLAYERS (Dan 2026-08-27). The old second clause gave a lone
  -- HUMAN an engine and denied one to a lone HORSE. Any occupied table
  -- qualifies now. p_min is kept in the signature but no longer gates.
  -- human_count stays in the result: "needs an engine" and "should be dealing"
  -- remain two different questions.
  HAVING count(*) >= 1;
$$;


ALTER FUNCTION public.cash_tables_needing_engine(p_min integer) OWNER TO postgres;

--
-- Name: cash_tables_with_players(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cash_tables_with_players(p_min integer DEFAULT 2) RETURNS TABLE(table_id uuid, player_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT ts.table_id, count(*) AS player_count
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
   WHERE ts.left_at IS NULL
     AND t.tournament_id IS NULL
     AND t.status IN ('waiting', 'running')
   GROUP BY ts.table_id
  HAVING count(*) >= p_min;
$$;


ALTER FUNCTION public.cash_tables_with_players(p_min integer) OWNER TO postgres;

