--
-- Name: check_duplicate_clips(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_duplicate_clips(p_urls text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF p_urls IS NULL OR array_length(p_urls, 1) IS NULL OR array_length(p_urls, 1) = 0 THEN
    SELECT COALESCE(jsonb_agg(row_to_json(d)::jsonb), '[]'::jsonb) INTO v_result
    FROM (
      SELECT video_id, COUNT(*) AS occurrences, MIN(posted_at) AS first_seen, MAX(posted_at) AS last_seen
      FROM public.posted_clips
      GROUP BY video_id
      HAVING COUNT(*) > 1
      LIMIT 500
    ) d;
    RETURN COALESCE(v_result, '[]'::jsonb);
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(d)::jsonb), '[]'::jsonb) INTO v_result
  FROM (
    SELECT video_id, source_url, posted_at
    FROM public.posted_clips
    WHERE source_url = ANY(p_urls) OR video_id = ANY(p_urls)
    LIMIT 500
  ) d;

  RETURN COALESCE(v_result, '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'check_duplicate_clips failed: % %', SQLERRM, SQLSTATE;
  RETURN '[]'::jsonb;
END;
$$;


ALTER FUNCTION public.check_duplicate_clips(p_urls text[]) OWNER TO postgres;

--
-- Name: check_rate_limit(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_rate_limit(p_key text, p_limit integer, p_window_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_window_start timestamptz;
  v_count integer;
BEGIN
  -- Defensive: bad inputs → fail open with a warning (matches the
  -- prior phantom return-true behavior for malformed callers but
  -- now logged so we know it happened).
  IF p_key IS NULL OR p_limit IS NULL OR p_limit <= 0 OR p_window_seconds IS NULL OR p_window_seconds <= 0 THEN
    RAISE WARNING 'check_rate_limit: invalid args (key=%, limit=%, window=%)', p_key, p_limit, p_window_seconds;
    RETURN true;
  END IF;

  -- Bucket the window. For a 60s window we floor now() to the
  -- nearest minute boundary; for 3600s to the nearest hour. This
  -- gives a fixed window (cheap, deterministic).
  v_window_start := to_timestamp(
    (extract(epoch FROM now())::bigint / p_window_seconds) * p_window_seconds
  );

  INSERT INTO public.rate_limit_buckets (bucket_key, window_start, request_count, last_request_at)
  VALUES (p_key, v_window_start, 1, now())
  ON CONFLICT (bucket_key, window_start) DO UPDATE
    SET request_count = rate_limit_buckets.request_count + 1,
        last_request_at = now()
  RETURNING request_count INTO v_count;

  RETURN v_count <= p_limit;

EXCEPTION WHEN OTHERS THEN
  -- Fail open + warn so a malformed table state never bricks the API.
  RAISE WARNING 'check_rate_limit failed (key=%): % %', p_key, SQLERRM, SQLSTATE;
  RETURN true;
END;
$$;


ALTER FUNCTION public.check_rate_limit(p_key text, p_limit integer, p_window_seconds integer) OWNER TO postgres;

--
-- Name: check_rate_limit(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_rate_limit(p_user_id uuid, p_action text, p_max_per_minute integer DEFAULT 5) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count integer;
BEGIN
    SELECT count(*) INTO v_count FROM public.rate_limits
     WHERE user_id = p_user_id AND action = p_action
       AND created_at > now() - INTERVAL '1 minute';
    IF v_count >= p_max_per_minute THEN RETURN FALSE; END IF;
    INSERT INTO public.rate_limits (user_id, action) VALUES (p_user_id, p_action);
    RETURN TRUE;
END;
$$;


ALTER FUNCTION public.check_rate_limit(p_user_id uuid, p_action text, p_max_per_minute integer) OWNER TO postgres;

--
-- Name: check_rate_limit_strict(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_rate_limit_strict(p_key text, p_limit integer, p_window_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_window_start timestamptz;
  v_count integer;
BEGIN
  IF p_key IS NULL OR length(p_key) = 0 OR p_limit IS NULL OR p_limit <= 0
     OR p_window_seconds IS NULL OR p_window_seconds <= 0 THEN
    RETURN false;
  END IF;
  v_window_start := to_timestamp(
    (extract(epoch FROM now())::bigint / p_window_seconds) * p_window_seconds
  );
  INSERT INTO public.rate_limit_buckets (bucket_key, window_start, request_count, last_request_at)
  VALUES (p_key, v_window_start, 1, now())
  ON CONFLICT (bucket_key, window_start) DO UPDATE
    SET request_count = public.rate_limit_buckets.request_count + 1,
        last_request_at = now()
  RETURNING request_count INTO v_count;
  RETURN v_count <= p_limit;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'check_rate_limit_strict failed closed (key=%): % %', p_key, SQLERRM, SQLSTATE;
  RETURN false;
END;
$$;


ALTER FUNCTION public.check_rate_limit_strict(p_key text, p_limit integer, p_window_seconds integer) OWNER TO postgres;

--
-- Name: check_upcoming_tournament_pushes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_upcoming_tournament_pushes() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
    -- 15 Minute Push
    WITH candidates_15m AS (
        SELECT
            t.id AS tournament_id,
            t.name AS tournament_name,
            tp.user_id
        FROM public.tournaments t
        JOIN public.tournament_players tp ON t.id = tp.tournament_id
        WHERE t.status IN ('ANNOUNCED', 'REGISTERING')
          AND t.start_time IS NOT NULL
          AND t.game_type != 'spin'
          AND tp.push_15m_sent = false
          AND t.start_time <= now() + interval '15 minutes'
          AND t.start_time > now() + interval '2 minutes'
          AND NOT EXISTS (
            SELECT 1 FROM public.table_seats ts
            WHERE ts.user_id = tp.user_id AND ts.left_at IS NULL
          )
    ),
    inserted_15m AS (
        INSERT INTO public.push_outbox (recipient_user_id, title, body, url, event)
        SELECT
            user_id,
            'Tournament Starting Soon',
            'Your tournament "' || tournament_name || '" starts in 15 minutes!',
            '/tournaments/' || tournament_id,
            'tournament_reminder_15m'
        FROM candidates_15m
    )
    UPDATE public.tournament_players tp
    SET push_15m_sent = true
    FROM candidates_15m c
    WHERE tp.tournament_id = c.tournament_id AND tp.user_id = c.user_id;

    -- Players already in a seat: mark as sent so we do not push later when
    -- they stand up (mirrors the old user_presence 'playing' branch).
    UPDATE public.tournament_players tp
    SET push_15m_sent = true
    FROM public.tournaments t
    WHERE t.id = tp.tournament_id
      AND t.status IN ('ANNOUNCED', 'REGISTERING')
      AND t.start_time <= now() + interval '15 minutes'
      AND tp.push_15m_sent = false
      AND EXISTS (
        SELECT 1 FROM public.table_seats ts
        WHERE ts.user_id = tp.user_id AND ts.left_at IS NULL
      );

    -- 2 Minute Push
    WITH candidates_2m AS (
        SELECT
            t.id AS tournament_id,
            t.name AS tournament_name,
            tp.user_id
        FROM public.tournaments t
        JOIN public.tournament_players tp ON t.id = tp.tournament_id
        WHERE t.status IN ('ANNOUNCED', 'REGISTERING')
          AND t.start_time IS NOT NULL
          AND t.game_type != 'spin'
          AND tp.push_2m_sent = false
          AND t.start_time <= now() + interval '2 minutes'
          AND t.start_time > now()
          AND NOT EXISTS (
            SELECT 1 FROM public.table_seats ts
            WHERE ts.user_id = tp.user_id AND ts.left_at IS NULL
          )
    ),
    inserted_2m AS (
        INSERT INTO public.push_outbox (recipient_user_id, title, body, url, event)
        SELECT
            user_id,
            'Tournament Starting Soon',
            'Get ready! "' || tournament_name || '" starts in 2 minutes!',
            '/tournaments/' || tournament_id,
            'tournament_reminder_2m'
        FROM candidates_2m
    )
    UPDATE public.tournament_players tp
    SET push_2m_sent = true
    FROM candidates_2m c
    WHERE tp.tournament_id = c.tournament_id AND tp.user_id = c.user_id;

    UPDATE public.tournament_players tp
    SET push_2m_sent = true
    FROM public.tournaments t
    WHERE t.id = tp.tournament_id
      AND t.status IN ('ANNOUNCED', 'REGISTERING')
      AND t.start_time <= now() + interval '2 minutes'
      AND tp.push_2m_sent = false
      AND EXISTS (
        SELECT 1 FROM public.table_seats ts
        WHERE ts.user_id = tp.user_id AND ts.left_at IS NULL
      );
END;
$$;


ALTER FUNCTION public.check_upcoming_tournament_pushes() OWNER TO postgres;

--
-- Name: check_username_available(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_username_available(p_username text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_clean text;
  v_self uuid := auth.uid();
BEGIN
  v_clean := lower(trim(both ' @' from coalesce(p_username, '')));
  IF v_clean = '' OR public.is_reserved_username(v_clean) THEN
    RETURN false;
  END IF;
  RETURN NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE lower(username) = v_clean
      AND (v_self IS NULL OR id <> v_self)
  );
END;
$$;


ALTER FUNCTION public.check_username_available(p_username text) OWNER TO postgres;

--
-- Name: check_username_with_suggestions(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_username_with_suggestions(p_username text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_clean text;
  v_taken boolean;
  v_suggestions text[] := ARRAY[]::text[];
  v_candidate text;
  v_i int := 0;
  v_self uuid := auth.uid();
BEGIN
  v_clean := lower(trim(both ' @' from coalesce(p_username, '')));

  IF v_clean !~ '^[a-z0-9][a-z0-9_.]{2,19}$' THEN
    RETURN jsonb_build_object(
      'available', false,
      'reason', 'invalid_format',
      'message', 'Username Must Be 3-20 Characters Using Letters, Numbers, Underscores, Or Periods.',
      'suggestions', '[]'::jsonb
    );
  END IF;

  IF public.is_reserved_username(v_clean) THEN
    RETURN jsonb_build_object(
      'available', false,
      'reason', 'reserved',
      'message', 'That Username Is Reserved. Pick A Different One.',
      'suggestions', '[]'::jsonb
    );
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE lower(username) = v_clean
      AND (v_self IS NULL OR id <> v_self)
  ) INTO v_taken;

  IF NOT v_taken THEN
    RETURN jsonb_build_object(
      'available', true,
      'normalized', v_clean,
      'suggestions', '[]'::jsonb
    );
  END IF;

  WHILE array_length(v_suggestions, 1) IS NULL OR array_length(v_suggestions, 1) < 3 LOOP
    v_i := v_i + 1;
    IF v_i > 50 THEN EXIT; END IF;
    v_candidate := CASE
      WHEN v_i <= 9        THEN v_clean || v_i::text
      WHEN v_i <= 15       THEN v_clean || (10 + (v_i - 10) * 7)::text
      WHEN v_i = 16        THEN v_clean || '_' || floor(random() * 9000 + 1000)::text
      WHEN v_i = 17        THEN v_clean || '.' || to_char(now(), 'YY')
      ELSE                       v_clean || '_' || floor(random() * 90000 + 10000)::text
    END;
    IF length(v_candidate) > 20 THEN CONTINUE; END IF;
    -- Skip suggestion if it's also reserved (e.g., "admin1", "support2" etc)
    IF public.is_reserved_username(v_candidate) THEN CONTINUE; END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.profiles 
      WHERE lower(username) = v_candidate
        AND (v_self IS NULL OR id <> v_self)
    ) THEN
      IF NOT (v_candidate = ANY(v_suggestions)) THEN
        v_suggestions := v_suggestions || v_candidate;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'available', false,
    'reason', 'taken',
    'message', 'That Username Is Already Taken.',
    'suggestions', to_jsonb(v_suggestions)
  );
END;
$_$;


ALTER FUNCTION public.check_username_with_suggestions(p_username text) OWNER TO postgres;

--
-- Name: checkin_to_home_game(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.checkin_to_home_game(p_game_id uuid, p_member_user_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_game  RECORD;
    v_group RECORD;
    v_rsvp  RECORD;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;

    -- Only host/owner/admin can mark check-ins
    IF v_game.host_id <> p_caller_user_id 
       AND v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members 
                        WHERE group_id = v_game.group_id AND user_id = p_caller_user_id
                          AND role = 'admin' AND status = 'approved')
    THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    SELECT * INTO v_rsvp FROM commander_home_rsvps 
     WHERE game_id = p_game_id AND user_id = p_member_user_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'NO_RSVP' USING HINT = 'member has no RSVP for this game';
    END IF;

    UPDATE commander_home_rsvps
       SET checked_in_at = COALESCE(checked_in_at, NOW()),
           checked_in_by = p_caller_user_id,
           flaked        = false,
           updated_at    = NOW()
     WHERE id = v_rsvp.id;

    RETURN jsonb_build_object(
        'success', true, 
        'rsvp_id', v_rsvp.id, 
        'member_user_id', p_member_user_id,
        'checked_in_at', NOW()
    );
END;
$$;


ALTER FUNCTION public.checkin_to_home_game(p_game_id uuid, p_member_user_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: checkin_to_venue(integer, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.checkin_to_venue(p_venue_id integer, p_caller_user_id uuid, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_venue RECORD; v_user_name text; v_id uuid; v_recent_count int;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    IF p_message IS NOT NULL AND length(p_message) > 500 THEN RAISE EXCEPTION 'MESSAGE_TOO_LONG'; END IF;

    SELECT id, name INTO v_venue FROM poker_venues WHERE id = p_venue_id 
       AND COALESCE(is_active,true) AND NOT COALESCE(is_suppressed,false);
    IF NOT FOUND THEN RAISE EXCEPTION 'VENUE_NOT_FOUND'; END IF;

    -- Rate limit: max 10 check-ins per user per hour
    SELECT COUNT(*) INTO v_recent_count FROM venue_checkins 
     WHERE user_id = p_caller_user_id AND created_at > NOW() - INTERVAL '1 hour';
    IF v_recent_count >= 10 THEN 
        RAISE EXCEPTION 'RATE_LIMITED' USING HINT='max 10 check-ins per hour'; 
    END IF;

    SELECT COALESCE(display_name, username, 'Anonymous') INTO v_user_name 
      FROM profiles WHERE id = p_caller_user_id;

    -- Write to primary check-in log (now uuid + integer - clean types)
    INSERT INTO venue_checkins (venue_id, user_id, user_name, message)
    VALUES (p_venue_id, p_caller_user_id, v_user_name, p_message)
    RETURNING id INTO v_id;

    -- Also write to user_venue_checkins (was broken by type mismatch pre-Phase 31, now works)
    BEGIN
        INSERT INTO user_venue_checkins (venue_id, user_id, checkin_time)
        VALUES (p_venue_id, p_caller_user_id, NOW());
    EXCEPTION WHEN OTHERS THEN
        -- user_venue_checkins columns may differ slightly; don't fail the primary write
        RAISE WARNING 'user_venue_checkins write failed: %', SQLERRM;
    END;

    -- Increment poker_venues.follower_count is handled elsewhere;
    -- bump trust_score if it's a verified check-in can be added later.

    RETURN jsonb_build_object(
      'success', true, 'checkin_id', v_id, 
      'venue_id', p_venue_id, 'venue_name', v_venue.name,
      'recent_count_in_window', v_recent_count + 1
    );
END; $$;


ALTER FUNCTION public.checkin_to_venue(p_venue_id integer, p_caller_user_id uuid, p_message text) OWNER TO postgres;

--
-- Name: FUNCTION checkin_to_venue(p_venue_id integer, p_caller_user_id uuid, p_message text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.checkin_to_venue(p_venue_id integer, p_caller_user_id uuid, p_message text) IS 'Phase 27 + Phase 31: Record a venue check-in. Writes to both venue_checkins (primary log) and user_venue_checkins (per-user index, now functional post-Phase 31 venue_id fix).';


--
-- Name: pa_leak_audit_jobs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pa_leak_audit_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    stage text DEFAULT 'queued'::text NOT NULL,
    audit_cursor text,
    progress jsonb DEFAULT '{}'::jsonb NOT NULL,
    result jsonb,
    reconciliation jsonb,
    engine_version text DEFAULT 'pa-leak-audit-v2'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    worker_token uuid,
    lease_expires_at timestamp with time zone,
    error_code text,
    error_message text,
    queued_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    heartbeat_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pa_leak_audit_jobs_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT pa_leak_audit_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'completed'::text, 'failed'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.pa_leak_audit_jobs FORCE ROW LEVEL SECURITY;


ALTER TABLE public.pa_leak_audit_jobs OWNER TO postgres;

--
-- Name: checkpoint_pa_leak_audit_job(uuid, uuid, text, text, text, jsonb, jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.checkpoint_pa_leak_audit_job(p_job_id uuid, p_worker_token uuid, p_status text, p_stage text, p_audit_cursor text, p_progress jsonb, p_result jsonb DEFAULT NULL::jsonb, p_reconciliation jsonb DEFAULT NULL::jsonb, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text) RETURNS SETOF public.pa_leak_audit_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_job public.pa_leak_audit_jobs%ROWTYPE;
BEGIN
  IF p_status NOT IN ('queued', 'running', 'completed', 'failed', 'cancelled') THEN
    RAISE EXCEPTION 'invalid audit status';
  END IF;
  UPDATE public.pa_leak_audit_jobs
     SET status = p_status,
         stage = LEFT(COALESCE(NULLIF(p_stage, ''), stage), 80),
         audit_cursor = p_audit_cursor,
         progress = COALESCE(p_progress, progress),
         result = COALESCE(p_result, result),
         reconciliation = COALESCE(p_reconciliation, reconciliation),
         error_code = p_error_code,
         error_message = LEFT(p_error_message, 500),
         heartbeat_at = now(),
         queued_at = CASE WHEN p_status = 'queued' THEN now() ELSE queued_at END,
         completed_at = CASE WHEN p_status IN ('completed', 'failed', 'cancelled') THEN now() ELSE NULL END,
         worker_token = CASE WHEN p_status = 'running' THEN worker_token ELSE NULL END,
         lease_expires_at = CASE WHEN p_status = 'running' THEN lease_expires_at ELSE NULL END,
         updated_at = now()
   WHERE id = p_job_id AND status = 'running' AND worker_token = p_worker_token
   RETURNING * INTO v_job;
  IF FOUND THEN RETURN NEXT v_job; END IF;
END;
$$;


ALTER FUNCTION public.checkpoint_pa_leak_audit_job(p_job_id uuid, p_worker_token uuid, p_status text, p_stage text, p_audit_cursor text, p_progress jsonb, p_result jsonb, p_reconciliation jsonb, p_error_code text, p_error_message text) OWNER TO postgres;

