--

CREATE FUNCTION public.claim_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_reward_amount numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION 'Legacy claim RPC retired; use claim_daily_challenges with a request id';
END;
$$;


ALTER FUNCTION public.claim_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_reward_amount numeric) OWNER TO postgres;

--
-- Name: FUNCTION claim_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_reward_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_reward_amount numeric) IS 'Retired fail-closed legacy entry point. All one-card and multi-card Daily Mission claims use claim_daily_challenges with an immutable request id and exact settlement receipt.';


--
-- Name: claim_daily_challenge_serialized_body(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_daily_challenge_serialized_body(p_user_id uuid, p_challenge_row_id uuid, p_reward_amount numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.user_daily_challenges%ROWTYPE;
  v_new_diamonds integer;
BEGIN
  IF v_uid IS NULL AND public.fn_caller_is_engine() THEN
    v_uid := p_user_id;
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_user_id IS NULL OR p_user_id <> v_uid THEN
    RAISE EXCEPTION 'Cannot claim a challenge for another user' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row
  FROM public.user_daily_challenges
  WHERE id = p_challenge_row_id AND user_id = v_uid
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Challenge not found'; END IF;
  IF v_row.claimed THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'alreadyClaimed', true,
      'chips', 0,
      'diamonds', 0,
      'diamondBalance', (SELECT COALESCE(diamonds, 0) FROM public.profiles WHERE id = v_uid)
    );
  END IF;
  IF NOT v_row.completed THEN RAISE EXCEPTION 'Challenge not completed yet'; END IF;
  -- DIAMOND-RULINGS 3: a completed reward is claimable for seven days, for everyone. The stamp
  -- (expired_at) is what the dashboard reads; the clock is what this refuses by, so the rule
  -- holds whether or not the daily stamp has run.
  IF v_row.expired_at IS NOT NULL
     OR (v_row.completed_at IS NOT NULL AND v_row.completed_at < now() - interval '7 days') THEN
    RAISE EXCEPTION 'Challenge reward expired' USING ERRCODE = 'P0430';
  END IF;
  IF v_row.progress < v_row.requirement_snapshot THEN
    RAISE EXCEPTION 'Challenge progress %/% does not meet the assigned requirement',
      v_row.progress, v_row.requirement_snapshot;
  END IF;

  /* The optimistic-concurrency check used to compare against the CHIP snapshot,
     which is now always 0 and therefore no longer identifies anything. It reads
     the diamond snapshot - the reward the player is actually being paid - so a
     card that changed underneath the player still stops the claim. */
  IF p_reward_amount IS NOT NULL
     AND p_reward_amount IS DISTINCT FROM v_row.diamond_reward_snapshot
  THEN
    RAISE EXCEPTION 'Challenge reward changed; refresh and try again';
  END IF;

  UPDATE public.user_daily_challenges
  SET claimed = true, claimed_at = now()
  WHERE id = p_challenge_row_id;

  /* NO CHIP CREDIT. This is where `atomic_credit_wallet_and_log` stood until
     2026-09-05, paying chip_reward_snapshot into club_members.chip_balance. A
     mission reward is diamonds. Removed rather than guarded on a zeroed column,
     so a stale snapshot arriving from anywhere cannot mint a chip. */

  IF v_row.diamond_reward_snapshot > 0 THEN
    UPDATE public.profiles
    SET diamonds = COALESCE(diamonds, 0) + v_row.diamond_reward_snapshot,
        diamond_balance = COALESCE(diamonds, 0) + v_row.diamond_reward_snapshot,
        updated_at = now()
    WHERE id = v_uid
    RETURNING diamonds INTO v_new_diamonds;

    IF v_new_diamonds IS NULL THEN
      RAISE EXCEPTION 'Profile not found for user % - diamond credit failed', v_uid;
    END IF;

    INSERT INTO public.diamond_transactions (
      user_id, amount, transaction_type, type, description,
      balance_after, metadata, reference_id, created_at, counterparty, issuance_class
    ) VALUES (
      v_uid,
      v_row.diamond_reward_snapshot,
      'daily_challenge_claim',
      'daily_challenge_claim',
      'Challenge reward: ' || v_row.challenge_id,
      v_new_diamonds,
      jsonb_build_object(
        'challenge_row_id', p_challenge_row_id,
        'challenge_id', v_row.challenge_id,
        'assigned_diamond_reward', v_row.diamond_reward_snapshot
      ),
      'challenge_claim:' || p_challenge_row_id::text || ':diamonds',
      now(),
      'promo_budget:daily_challenges', 'earned'
    );
  ELSE
    SELECT COALESCE(diamonds, 0) INTO v_new_diamonds
    FROM public.profiles
    WHERE id = v_uid;
  END IF;

  RETURN jsonb_build_object(
    'claimed', true,
    'alreadyClaimed', false,
    'challengeId', v_row.challenge_id,
    'chips', 0,
    'diamonds', v_row.diamond_reward_snapshot,
    'diamondBalance', COALESCE(v_new_diamonds, 0)
  );
END;
$$;


ALTER FUNCTION public.claim_daily_challenge_serialized_body(p_user_id uuid, p_challenge_row_id uuid, p_reward_amount numeric) OWNER TO postgres;

--
-- Name: FUNCTION claim_daily_challenge_serialized_body(p_user_id uuid, p_challenge_row_id uuid, p_reward_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_daily_challenge_serialized_body(p_user_id uuid, p_challenge_row_id uuid, p_reward_amount numeric) IS 'Claims one mission and pays DIAMONDS. The chip credit was removed 2026-09-05 (Dan: nothing ever earns chips, only diamonds). `chips` stays in the result as a literal 0 so the client contract is unchanged.';


--
-- Name: claim_daily_challenges(uuid, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_daily_challenges(p_user_id uuid, p_challenge_row_ids uuid[], p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_requested_ids uuid[];
  v_bound_ids uuid[];
  v_receipt_found boolean;
  v_stored_result jsonb;
  v_result jsonb;
  v_challenge_diamonds numeric := 0;
  v_milestone_diamonds numeric := 0;
  v_diamonds_credited numeric := 0;
  v_milestones_before numeric := 0;
  v_milestones_after numeric := 0;
  v_total_challenge_diamonds numeric := 0;
  v_total_diamonds_earned numeric := 0;
  v_opening_diamond_balance numeric;
  v_diamond_balance numeric;
BEGIN
  IF v_uid IS NULL AND public.fn_caller_is_engine() THEN
    v_uid := p_user_id;
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_user_id IS NULL OR p_user_id <> v_uid THEN
    RAISE EXCEPTION 'Cannot claim challenges for another user' USING ERRCODE = '42501';
  END IF;
  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'A claim request id is required';
  END IF;
  IF p_challenge_row_ids IS NULL OR cardinality(p_challenge_row_ids) = 0 THEN
    RAISE EXCEPTION 'At least one challenge is required';
  END IF;
  IF cardinality(p_challenge_row_ids) > 100 THEN
    RAISE EXCEPTION 'At most 100 challenges can be claimed at once';
  END IF;
  IF array_position(p_challenge_row_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Challenge ids cannot be null';
  END IF;

  SELECT array_agg(id ORDER BY id)
  INTO v_requested_ids
  FROM (SELECT DISTINCT unnest(p_challenge_row_ids) AS id) requested;

  PERFORM public.fn_lock_daily_mission_user(v_uid);

  SELECT challenge_row_ids, result
  INTO v_bound_ids, v_stored_result
  FROM public.daily_challenge_claim_batches
  WHERE user_id = v_uid
    AND request_id = p_request_id
  FOR UPDATE;
  v_receipt_found := FOUND;

  IF v_receipt_found AND v_bound_ids IS DISTINCT FROM v_requested_ids THEN
    RAISE EXCEPTION 'Claim request id is already bound to another challenge set';
  END IF;

  IF v_receipt_found THEN
    IF v_stored_result IS NULL THEN
      RAISE EXCEPTION 'The prior claim request did not finish';
    END IF;

    IF (v_stored_result ->> 'settlementVersion') = '2'
       AND NOT (v_stored_result ?& ARRAY[
         'challengeDiamonds',
         'milestoneDiamonds',
         'diamondsCredited',
         'diamondBalance',
         'settlementDiamondBalance',
         'settlementVersion'
       ])
    THEN
      RAISE EXCEPTION 'The prior claim request has an incomplete v2 settlement receipt';
    END IF;

    SELECT COALESCE(diamonds, 0)
    INTO v_diamond_balance
    FROM public.profiles
    WHERE id = v_uid;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Profile not found - replay balance could not be reconciled';
    END IF;

    RETURN v_stored_result || jsonb_build_object(
      'replayed', true,
      'settlementDiamondBalance', COALESCE(
        (v_stored_result ->> 'settlementDiamondBalance')::numeric,
        (v_stored_result ->> 'diamondBalance')::numeric
      ),
      'diamondBalance', v_diamond_balance
    );
  END IF;

  SELECT COALESCE(diamonds, 0)
  INTO v_opening_diamond_balance
  FROM public.profiles
  WHERE id = v_uid
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profile not found - opening claim balance could not be locked';
  END IF;

  SELECT COALESCE(sum(amount), 0)
  INTO v_milestones_before
  FROM public.diamond_transactions
  WHERE user_id = v_uid
    AND transaction_type = 'daily_mission_milestone';

  v_result := public.claim_daily_challenges_serialized_body(
    p_user_id,
    p_challenge_row_ids,
    p_request_id
  );

  SELECT COALESCE(diamonds, 0)
  INTO v_diamond_balance
  FROM public.profiles
  WHERE id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profile not found - claim receipt could not be finalized';
  END IF;

  v_challenge_diamonds := COALESCE((v_result ->> 'diamonds')::numeric, 0);
  SELECT COALESCE(sum(amount), 0)
  INTO v_milestones_after
  FROM public.diamond_transactions
  WHERE user_id = v_uid
    AND transaction_type = 'daily_mission_milestone';
  v_milestone_diamonds := v_milestones_after - v_milestones_before;
  v_diamonds_credited := v_challenge_diamonds + v_milestone_diamonds;

  SELECT COALESCE(sum(diamond_reward_snapshot), 0)
  INTO v_total_challenge_diamonds
  FROM public.user_daily_challenges
  WHERE user_id = v_uid
    AND claimed = true;
  v_total_diamonds_earned := v_total_challenge_diamonds + v_milestones_after;

  IF v_challenge_diamonds < 0
     OR v_milestone_diamonds < 0
     OR v_diamonds_credited <> v_challenge_diamonds + v_milestone_diamonds
     OR v_diamond_balance - v_opening_diamond_balance <> v_diamonds_credited
  THEN
    RAISE EXCEPTION 'Claim Diamond settlement does not reconcile with the wallet';
  END IF;

  v_result := jsonb_set(
    v_result,
    '{stats,totalDiamondsEarned}',
    to_jsonb(v_total_diamonds_earned),
    true
  ) || jsonb_build_object(
    'challengeDiamonds', v_challenge_diamonds,
    'milestoneDiamonds', v_milestone_diamonds,
    'diamondsCredited', v_diamonds_credited,
    'diamondBalance', v_diamond_balance,
    'settlementDiamondBalance', v_diamond_balance,
    'settlementVersion', 2
  );

  UPDATE public.daily_challenge_claim_batches
  SET challenge_row_ids = COALESCE(challenge_row_ids, v_requested_ids),
      result = v_result
  WHERE user_id = v_uid
    AND request_id = p_request_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Claim request receipt was not persisted';
  END IF;

  SELECT challenge_row_ids, result
  INTO v_bound_ids, v_stored_result
  FROM public.daily_challenge_claim_batches
  WHERE user_id = v_uid
    AND request_id = p_request_id;

  IF NOT FOUND
     OR v_bound_ids IS DISTINCT FROM v_requested_ids
     OR v_stored_result IS DISTINCT FROM v_result
  THEN
    RAISE EXCEPTION 'Claim request receipt did not preserve its exact settlement';
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.claim_daily_challenges(p_user_id uuid, p_challenge_row_ids uuid[], p_request_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION claim_daily_challenges(p_user_id uuid, p_challenge_row_ids uuid[], p_request_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_daily_challenges(p_user_id uuid, p_challenge_row_ids uuid[], p_request_id uuid) IS 'Replay-safe Daily Missions batch claim. The immutable request receipt separates challengeDiamonds and milestoneDiamonds, reports their diamondsCredited sum, preserves settlementDiamondBalance, and refreshes diamondBalance to the current wallet projection on replay.';


--
-- Name: claim_daily_challenges_serialized_body(uuid, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_daily_challenges_serialized_body(p_user_id uuid, p_challenge_row_ids uuid[], p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_requested_ids uuid[];
  v_owned_ids uuid[] := ARRAY[]::uuid[];
  v_claimed_ids uuid[] := ARRAY[]::uuid[];
  v_already_claimed_ids uuid[] := ARRAY[]::uuid[];
  v_inserted integer := 0;
  v_existing jsonb;
  v_diamonds integer := 0;
  v_diamond_balance integer := 0;
  v_vault_count bigint := 0;
  v_vault_diamonds bigint := 0;
  v_vault_items jsonb := '[]'::jsonb;
  v_total_claimed bigint := 0;
  v_total_diamonds bigint := 0;
  v_result jsonb;
  VAULT_PAGE_SIZE constant integer := 100;
BEGIN
  IF v_uid IS NULL AND public.fn_caller_is_engine() THEN
    v_uid := p_user_id;
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_user_id IS NULL OR p_user_id <> v_uid THEN
    RAISE EXCEPTION 'Cannot claim challenges for another user' USING ERRCODE = '42501';
  END IF;
  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'A claim request id is required';
  END IF;
  IF p_challenge_row_ids IS NULL OR cardinality(p_challenge_row_ids) = 0 THEN
    RAISE EXCEPTION 'At least one challenge is required';
  END IF;
  IF cardinality(p_challenge_row_ids) > VAULT_PAGE_SIZE THEN
    RAISE EXCEPTION 'At most % challenges can be claimed at once', VAULT_PAGE_SIZE;
  END IF;
  IF array_position(p_challenge_row_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Challenge ids cannot be null';
  END IF;

  SELECT array_agg(id ORDER BY id)
    INTO v_requested_ids
    FROM (SELECT DISTINCT unnest(p_challenge_row_ids) AS id) requested;

  INSERT INTO public.daily_challenge_claim_batches (user_id, request_id)
  VALUES (v_uid, p_request_id)
  ON CONFLICT (user_id, request_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF v_inserted = 0 THEN
    SELECT result INTO v_existing
      FROM public.daily_challenge_claim_batches
     WHERE user_id = v_uid AND request_id = p_request_id
     FOR UPDATE;
    IF v_existing IS NULL THEN
      RAISE EXCEPTION 'The prior claim request did not finish';
    END IF;
    RETURN v_existing || jsonb_build_object('replayed', true);
  END IF;

  SELECT COALESCE(array_agg(locked.id ORDER BY locked.id), ARRAY[]::uuid[])
    INTO v_owned_ids
    FROM (
      SELECT id
        FROM public.user_daily_challenges
       WHERE user_id = v_uid
         AND id = ANY(v_requested_ids)
       ORDER BY id
       FOR UPDATE
    ) locked;

  IF cardinality(v_owned_ids) <> cardinality(v_requested_ids) THEN
    RAISE EXCEPTION 'One or more challenges do not belong to this player' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM public.user_daily_challenges
     WHERE id = ANY(v_owned_ids)
       AND (NOT completed OR progress < requirement_snapshot)
  ) THEN
    RAISE EXCEPTION 'One or more challenges are not complete';
  END IF;
  -- DIAMOND-RULINGS 3: seven days to claim, for everyone.
  IF EXISTS (
    SELECT 1
      FROM public.user_daily_challenges
     WHERE id = ANY(v_owned_ids)
       AND NOT claimed
       AND (expired_at IS NOT NULL OR completed_at < now() - interval '7 days')
  ) THEN
    RAISE EXCEPTION 'One or more challenge rewards have expired' USING ERRCODE = 'P0430';
  END IF;

  SELECT COALESCE(array_agg(id ORDER BY id) FILTER (WHERE NOT claimed), ARRAY[]::uuid[]),
         COALESCE(array_agg(id ORDER BY id) FILTER (WHERE claimed), ARRAY[]::uuid[]),
         COALESCE(sum(diamond_reward_snapshot) FILTER (WHERE NOT claimed), 0)
    INTO v_claimed_ids, v_already_claimed_ids, v_diamonds
    FROM public.user_daily_challenges
   WHERE id = ANY(v_owned_ids);

  IF cardinality(v_claimed_ids) > 0 THEN
    UPDATE public.user_daily_challenges
       SET claimed = true,
           claimed_at = now()
     WHERE id = ANY(v_claimed_ids)
       AND user_id = v_uid
       AND claimed = false;

    /* NO CHIP CREDIT. Until 2026-09-05 this summed chip_reward_snapshot across
       the whole batch and paid it through atomic_credit_wallet_and_log. With
       425,819,000 chips sitting completed-and-unclaimed and a page size of 100
       rows per call, this was the single largest unintended mint on the
       platform. A mission reward is diamonds. */

    IF v_diamonds > 0 THEN
      UPDATE public.profiles
         SET diamonds = COALESCE(diamonds, 0) + v_diamonds,
             diamond_balance = COALESCE(diamonds, 0) + v_diamonds,
             updated_at = now()
       WHERE id = v_uid
       RETURNING diamonds INTO v_diamond_balance;

      IF v_diamond_balance IS NULL THEN
        RAISE EXCEPTION 'Profile not found - diamond rewards could not be credited';
      END IF;

      INSERT INTO public.diamond_transactions (
        user_id, amount, transaction_type, type, description,
        balance_after, metadata, reference_id, created_at, counterparty, issuance_class
      ) VALUES (
        v_uid,
        v_diamonds,
        'daily_challenge_claim',
        'daily_challenge_claim',
        'Daily Missions batch reward',
        v_diamond_balance,
        jsonb_build_object(
          'challenge_row_ids', to_jsonb(v_claimed_ids),
          'request_id', p_request_id,
          'assigned_diamond_reward', v_diamonds
        ),
        'challenge_claim_batch:' || p_request_id::text || ':diamonds',
        now(),
        'promo_budget:daily_challenges', 'earned'
      );
    END IF;
  END IF;

  IF v_diamond_balance IS NULL OR v_diamond_balance = 0 THEN
    SELECT COALESCE(diamonds, 0)::integer INTO v_diamond_balance
      FROM public.profiles
     WHERE id = v_uid;
  END IF;

  SELECT count(*), COALESCE(sum(diamond_reward_snapshot), 0)
    INTO v_vault_count, v_vault_diamonds
    FROM public.user_daily_challenges
   WHERE user_id = v_uid
     AND completed = true
     AND claimed = false
     AND expired_at IS NULL
     AND completed_at >= now() - interval '7 days';

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'id', vault.id,
             'challenge_id', vault.challenge_id,
             'assigned_date', vault.assigned_date,
             'progress', vault.progress,
             'completed', vault.completed,
             'claimed', vault.claimed,
             'completed_at', vault.completed_at,
             'name', vault.challenge_name_snapshot,
             'description', vault.challenge_description_snapshot,
             'challenge_type', vault.challenge_type_snapshot,
             'requirement', vault.requirement_snapshot,
             'chip_reward', 0,
             'diamond_reward', vault.diamond_reward_snapshot,
             'tier', vault.tier_snapshot
           )
           ORDER BY vault.completed_at DESC NULLS LAST, vault.id
         ), '[]'::jsonb)
    INTO v_vault_items
    FROM (
      SELECT *
        FROM public.user_daily_challenges
       WHERE user_id = v_uid
         AND completed = true
         AND claimed = false
         AND expired_at IS NULL
         AND completed_at >= now() - interval '7 days'
       ORDER BY completed_at DESC NULLS LAST, created_at DESC, id
       LIMIT VAULT_PAGE_SIZE
    ) vault;

  SELECT count(*), COALESCE(sum(diamond_reward_snapshot), 0)
    INTO v_total_claimed, v_total_diamonds
    FROM public.user_daily_challenges
   WHERE user_id = v_uid
     AND claimed = true;

  v_result := jsonb_build_object(
    'success', true,
    'replayed', false,
    'claimedIds', to_jsonb(v_claimed_ids),
    'alreadyClaimedIds', to_jsonb(v_already_claimed_ids),
    'chips', 0,
    'diamonds', v_diamonds,
    'diamondBalance', COALESCE(v_diamond_balance, 0),
    'stats', jsonb_build_object(
      'totalClaimed', v_total_claimed,
      'totalChipsEarned', 0,
      'totalDiamondsEarned', v_total_diamonds
    ),
    'vault', jsonb_build_object(
      'count', v_vault_count,
      'chips', 0,
      'diamonds', v_vault_diamonds,
      'items', v_vault_items,
      'pageSize', VAULT_PAGE_SIZE,
      'hasMore', v_vault_count > VAULT_PAGE_SIZE
    )
  );

  UPDATE public.daily_challenge_claim_batches
     SET result = v_result
   WHERE user_id = v_uid AND request_id = p_request_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.claim_daily_challenges_serialized_body(p_user_id uuid, p_challenge_row_ids uuid[], p_request_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION claim_daily_challenges_serialized_body(p_user_id uuid, p_challenge_row_ids uuid[], p_request_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_daily_challenges_serialized_body(p_user_id uuid, p_challenge_row_ids uuid[], p_request_id uuid) IS 'Claims a batch of missions and pays DIAMONDS. The chip credit was removed 2026-09-05 (Dan: nothing ever earns chips, only diamonds); it would have minted up to 425.8M chips from the completed-and-unclaimed vault. Every chip field in the result is a literal 0 so the client contract is unchanged.';


--
-- Name: claim_engine_leadership(text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_engine_leadership(p_instance_id text, p_version text DEFAULT NULL::text, p_stale_seconds integer DEFAULT 30) RETURNS TABLE(granted boolean, holder text, holder_age_seconds numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_holder    text;
  v_heartbeat timestamptz;
begin
  if coalesce(p_instance_id, '') = '' then
    raise exception 'claim_engine_leadership requires a non-empty instance_id';
  end if;

  insert into public.engine_leader as l
    (id, instance_id, engine_version, acquired_at, heartbeat_at)
  values
    (true, p_instance_id, p_version, now(), now())
  on conflict (id) do update
     set instance_id    = excluded.instance_id,
         engine_version = excluded.engine_version,
         acquired_at    = case
                            when l.instance_id = excluded.instance_id then l.acquired_at
                            else now()
                          end,
         heartbeat_at   = now()
   where l.instance_id = excluded.instance_id
      or l.heartbeat_at < now() - make_interval(secs => p_stale_seconds)
  returning l.instance_id, l.heartbeat_at into v_holder, v_heartbeat;

  if v_holder is not null then
    return query select true, v_holder, 0::numeric;
    return;
  end if;

  select l.instance_id, l.heartbeat_at into v_holder, v_heartbeat
    from public.engine_leader l where l.id = true;

  return query
    select false, v_holder,
           round(extract(epoch from (now() - v_heartbeat))::numeric, 1);
end;
$$;


ALTER FUNCTION public.claim_engine_leadership(p_instance_id text, p_version text, p_stale_seconds integer) OWNER TO postgres;

--
-- Name: claim_home_game_seat(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_home_game_seat(p_game_id uuid, p_seat_number integer, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_game RECORD;
    v_rsvp RECORD;
    v_player_name text;
    v_updated boolean := false;
    v_seat_row_exists boolean;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
      RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;
    IF p_seat_number < 1 OR p_seat_number > 20 THEN
      RAISE EXCEPTION 'INVALID_SEAT_NUMBER';
    END IF;

    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
    IF v_game.status NOT IN ('scheduled','confirmed','in_progress') THEN
      RAISE EXCEPTION 'GAME_NOT_ACTIVE';
    END IF;
    IF p_seat_number > COALESCE(v_game.max_players, 9) THEN
      RAISE EXCEPTION 'SEAT_EXCEEDS_MAX_PLAYERS';
    END IF;

    SELECT * INTO v_rsvp FROM commander_home_rsvps
     WHERE game_id = p_game_id AND user_id = p_caller_user_id;
    IF NOT FOUND OR v_rsvp.response <> 'yes' THEN
        RAISE EXCEPTION 'NO_YES_RSVP' USING HINT = 'must RSVP yes before claiming a seat';
    END IF;

    IF EXISTS (SELECT 1 FROM commander_home_seats
                WHERE game_id = p_game_id AND user_id = p_caller_user_id
                  AND status IN ('seated','away')) THEN
        RAISE EXCEPTION 'ALREADY_SEATED';
    END IF;

    SELECT COALESCE(display_name, full_name, username, 'Player') INTO v_player_name
      FROM profiles WHERE id = p_caller_user_id;

    UPDATE commander_home_seats
       SET user_id    = p_caller_user_id,
           player_name = v_player_name,
           status     = 'seated',
           seated_at  = NOW(),
           away_since = NULL,
           updated_at = NOW()
     WHERE game_id = p_game_id
       AND seat_number = p_seat_number
       AND status = 'empty';
    GET DIAGNOSTICS v_updated = ROW_COUNT;

    IF NOT v_updated THEN
      SELECT EXISTS (SELECT 1 FROM commander_home_seats
                      WHERE game_id = p_game_id AND seat_number = p_seat_number)
        INTO v_seat_row_exists;

      IF v_seat_row_exists THEN
        RAISE EXCEPTION 'SEAT_TAKEN'
              USING HINT = 'seat ' || p_seat_number || ' is occupied';
      ELSE
        BEGIN
          INSERT INTO commander_home_seats
            (game_id, seat_number, user_id, player_name, status, seated_at)
          VALUES
            (p_game_id, p_seat_number, p_caller_user_id, v_player_name,
             'seated', NOW());
        EXCEPTION WHEN unique_violation THEN
          RAISE EXCEPTION 'SEAT_TAKEN'
                USING HINT = 'seat ' || p_seat_number || ' was claimed concurrently';
        END;
      END IF;
    END IF;

    -- Pass 13: mark this transaction as a legitimate self-checkin context
    -- so fn_enforce_home_rsvp_field_permissions allows the checked_in_at
    -- self-stamp below.
    PERFORM set_config('app.hg_self_checkin_allowed', '1', true);

    UPDATE commander_home_rsvps
       SET checked_in_at = COALESCE(checked_in_at, NOW()),
           flaked = false, updated_at = NOW()
     WHERE id = v_rsvp.id;

    RETURN jsonb_build_object('success', true, 'seat_number', p_seat_number);
END;
$$;


ALTER FUNCTION public.claim_home_game_seat(p_game_id uuid, p_seat_number integer, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION claim_home_game_seat(p_game_id uuid, p_seat_number integer, p_caller_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_home_game_seat(p_game_id uuid, p_seat_number integer, p_caller_user_id uuid) IS 'Phase 40: (a) race-safe via atomic conditional UPDATE + unique-index backstop; (b) fixed status drift — now writes ''seated'' matching the CHECK constraint (was ''occupied'', feature was silently broken).';


--
-- Name: claim_idempotency_key(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_idempotency_key(p_key text, p_rpc_name text) RETURNS TABLE(claimed boolean, cached_result jsonb, cached_status text)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing public.idempotency_keys%ROWTYPE;
BEGIN
  IF p_key IS NULL OR p_rpc_name IS NULL THEN
    RAISE EXCEPTION 'idempotency key and rpc_name required';
  END IF;

  -- Try to INSERT the key. If it already exists, we lose the race and fetch existing.
  INSERT INTO public.idempotency_keys (key, rpc_name, status)
  VALUES (p_key, p_rpc_name, 'in_flight')
  ON CONFLICT (key) DO NOTHING;

  SELECT * INTO v_existing FROM public.idempotency_keys WHERE key = p_key;

  IF v_existing.rpc_name IS DISTINCT FROM p_rpc_name THEN
    RAISE EXCEPTION 'idempotency key % already used with different rpc (%, tried: %)',
      p_key, v_existing.rpc_name, p_rpc_name;
  END IF;

  -- Claimed (just inserted) if created_at is very recent AND status is in_flight with no result
  claimed := (v_existing.status = 'in_flight' AND v_existing.result IS NULL
              AND v_existing.created_at >= NOW() - INTERVAL '500 milliseconds');
  cached_result := v_existing.result;
  cached_status := v_existing.status;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.claim_idempotency_key(p_key text, p_rpc_name text) OWNER TO postgres;

--
-- Name: FUNCTION claim_idempotency_key(p_key text, p_rpc_name text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_idempotency_key(p_key text, p_rpc_name text) IS 'Phase 4.1.3: claim an idempotency key. If claimed=true, caller runs the RPC and calls store_idempotency_result. If claimed=false and cached_status=completed, caller returns cached_result directly.';


--
-- Name: claim_lucky_wheel_spin(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_lucky_wheel_spin(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid    uuid;
  v_today  date := (now() AT TIME ZONE 'UTC')::date;
  v_last   date;
  v_pick   record;
  v_roll   numeric;
  v_acc    numeric := 0;
BEGIN
  IF COALESCE(auth.role(), '') = 'service_role' THEN
    v_uid := p_user_id;
  ELSE
    v_uid := auth.uid();
    IF v_uid IS NULL THEN
      RAISE EXCEPTION 'claim_lucky_wheel_spin requires an authenticated caller' USING ERRCODE = '28000';
    END IF;
    IF p_user_id IS NOT NULL AND p_user_id <> v_uid THEN
      RAISE EXCEPTION 'Cannot spin the wheel for another user';
    END IF;
  END IF;

  INSERT INTO public.user_lucky_wheel_spins (user_id, total_spins, updated_at)
  VALUES (v_uid, 0, now())
  ON CONFLICT (user_id) DO NOTHING;

  SELECT (last_spin_date AT TIME ZONE 'UTC')::date INTO v_last
    FROM public.user_lucky_wheel_spins WHERE user_id = v_uid FOR UPDATE;

  IF v_last IS NOT NULL AND v_last >= v_today THEN
    RAISE EXCEPTION 'Already spun today';
  END IF;

  v_roll := random() * (SELECT sum(weight) FROM public.lucky_wheel_segments WHERE active);
  FOR v_pick IN SELECT * FROM public.lucky_wheel_segments WHERE active ORDER BY id LOOP
    v_acc := v_acc + v_pick.weight;
    EXIT WHEN v_roll <= v_acc;
  END LOOP;

  UPDATE public.user_lucky_wheel_spins
     SET total_spins = total_spins + 1, last_spin_date = now(), updated_at = now()
   WHERE user_id = v_uid;

  IF v_pick.reward_type = 'chips' THEN
    IF NOT public.atomic_credit_wallet_and_log(
         v_uid, v_pick.amount, 'bonus',
         'Lucky wheel: ' || v_pick.id,
         NULL, NULL, NULL,
         'lucky_wheel:' || v_uid::text || ':' || v_today::text) THEN
      RAISE EXCEPTION 'lucky wheel credit failed';
    END IF;
  ELSIF v_pick.reward_type = 'vip_points' THEN
    PERFORM public.add_vip_points(v_uid, v_pick.amount::integer);
  ELSIF v_pick.reward_type = 'diamonds' THEN
    PERFORM public.add_diamonds_to_balance(
      v_uid, v_pick.amount::integer, 'bonus', 'Lucky wheel: ' || v_pick.id,
      'lucky_wheel:' || v_uid::text || ':' || v_today::text);
  END IF;

  RETURN jsonb_build_object(
    'segmentId', v_pick.id, 'rewardType', v_pick.reward_type, 'amount', v_pick.amount);
END;
$$;


ALTER FUNCTION public.claim_lucky_wheel_spin(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION claim_lucky_wheel_spin(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_lucky_wheel_spin(p_user_id uuid) IS 'service_role only since 2026-09-07: its segments pay chips and nothing ever earns chips (Dan 2026-09-05). Never spun (user_lucky_wheel_spins was empty) and rendered by no file. The Diamond Wheel programme replaces it.';


--
-- Name: claim_pa_leak_audit_job(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_pa_leak_audit_job(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer DEFAULT 90) RETURNS SETOF public.pa_leak_audit_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_job public.pa_leak_audit_jobs%ROWTYPE;
BEGIN
  IF p_job_id IS NULL OR p_worker_token IS NULL THEN RETURN; END IF;
  UPDATE public.pa_leak_audit_jobs
     SET status = 'running', stage = CASE WHEN stage = 'queued' THEN 'importing_hands' ELSE stage END,
         worker_token = p_worker_token,
         lease_expires_at = now() + make_interval(secs => LEAST(300, GREATEST(30, COALESCE(p_lease_seconds, 90)))),
         started_at = COALESCE(started_at, now()), heartbeat_at = now(),
         attempt_count = attempt_count + 1, updated_at = now()
   WHERE id = p_job_id
     AND (status = 'queued'
       OR (status = 'running' AND COALESCE(lease_expires_at, '-infinity'::timestamptz) <= now()))
   RETURNING * INTO v_job;
  IF FOUND THEN RETURN NEXT v_job; END IF;
END;
$$;


