--
-- Name: claim_push_outbox_batch(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_push_outbox_batch(p_limit integer DEFAULT 100, p_max_attempts integer DEFAULT 5) RETURNS SETOF public.push_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE public.push_outbox
     SET status = 'processing',
         attempts = attempts + 1,
         claimed_at = now()
   WHERE id IN (
     SELECT id FROM public.push_outbox
      WHERE status = 'pending'
        AND attempts < p_max_attempts
      ORDER BY created_at
      LIMIT p_limit
      FOR UPDATE SKIP LOCKED
   )
  RETURNING *;
END;
$$;


