--
-- Name: claim_reward(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_reward(p_user_id uuid, p_reward_id text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_reward reward_definitions%ROWTYPE;
    v_balance user_diamond_balance%ROWTYPE;
    v_multiplier DECIMAL(3,2) := 1.0;
    v_diamonds INTEGER;
    v_daily_cap INTEGER := 500;
    v_today_earned INTEGER;
    v_claim_id UUID;
BEGIN
    -- Get reward definition
    SELECT * INTO v_reward FROM reward_definitions WHERE id = p_reward_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Reward not found');
    END IF;
    
    -- Get or create user balance
    SELECT * INTO v_balance FROM user_diamond_balance WHERE user_id = p_user_id;
    IF NOT FOUND THEN
        INSERT INTO user_diamond_balance (user_id, balance, lifetime_earned)
        VALUES (p_user_id, 0, 0)
        RETURNING * INTO v_balance;
    END IF;
    
    -- Check if non-repeatable reward already claimed
    IF NOT v_reward.is_repeatable THEN
        IF EXISTS (SELECT 1 FROM reward_claims WHERE user_id = p_user_id AND reward_id = p_reward_id) THEN
            RETURN jsonb_build_object('success', false, 'error', 'Already claimed', 'already_claimed', true);
        END IF;
    END IF;
    
    -- Calculate streak multiplier
    IF v_balance.current_streak >= 7 THEN
        v_multiplier := 2.0;
    ELSIF v_balance.current_streak >= 3 THEN
        v_multiplier := 1.5;
    END IF;
    
    -- Calculate diamonds
    v_diamonds := FLOOR(v_reward.base_amount * v_multiplier);
    
    -- Check daily cap (unless bypasses_cap is true)
    IF NOT COALESCE(v_reward.bypasses_cap, false) THEN
        SELECT COALESCE(SUM(diamonds_awarded), 0) INTO v_today_earned
        FROM reward_claims
        WHERE user_id = p_user_id AND created_at::date = CURRENT_DATE;
        
        IF v_today_earned >= v_daily_cap THEN
            RETURN jsonb_build_object('success', false, 'error', 'Daily cap reached', 'cap_reached', true);
        END IF;
        
        -- Reduce to stay under cap
        IF v_today_earned + v_diamonds > v_daily_cap THEN
            v_diamonds := v_daily_cap - v_today_earned;
        END IF;
    END IF;
    
    -- Create the claim
    INSERT INTO reward_claims (user_id, reward_id, diamonds_awarded, multiplier, metadata)
    VALUES (p_user_id, p_reward_id, v_diamonds, v_multiplier, p_metadata)
    RETURNING id INTO v_claim_id;
    
    -- Update balance
    UPDATE user_diamond_balance
    SET balance = balance + v_diamonds,
        lifetime_earned = lifetime_earned + v_diamonds,
        updated_at = NOW()
    WHERE user_id = p_user_id;
    
    -- Queue celebration
    INSERT INTO celebration_queue (user_id, reward_id, reward_name, diamonds, rarity, icon, message)
    VALUES (
        p_user_id,
        p_reward_id,
        v_reward.name,
        v_diamonds,
        v_reward.rarity,
        v_reward.icon,
        CASE v_reward.rarity
            WHEN 'legendary' THEN 'LEGENDARY ACHIEVEMENT!'
            WHEN 'epic' THEN 'EPIC DISCOVERY!'
            WHEN 'rare' THEN 'RARE FIND!'
            ELSE 'DIAMONDS EARNED!'
        END
    );
    
    RETURN jsonb_build_object(
        'success', true,
        'claim_id', v_claim_id,
        'reward_id', p_reward_id,
        'reward_name', v_reward.name,
        'diamonds', v_diamonds,
        'multiplier', v_multiplier,
        'rarity', v_reward.rarity,
        'icon', v_reward.icon,
        'new_balance', v_balance.balance + v_diamonds
    );
END;
$$;


ALTER FUNCTION public.claim_reward(p_user_id uuid, p_reward_id text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: claim_social_profile(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_social_profile(p_full_name text, p_username text, p_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_clean_username text;
  v_clean_phone    text;
  v_clean_name     text;
  v_phone_digits   text;
  v_profile        public.profiles;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unauthenticated');
  END IF;

  v_clean_name     := nullif(btrim(coalesce(p_full_name, '')), '');
  v_clean_username := lower(trim(both ' @' from coalesce(p_username, '')));
  v_clean_phone    := nullif(btrim(coalesce(p_phone, '')), '');

  IF v_clean_name IS NULL OR length(v_clean_name) < 2 OR length(v_clean_name) > 80
     OR v_clean_name !~ '[A-Za-zÀ-ÖØ-öø-ÿ]' THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_name',
      'message', 'Please Enter Your Full Name (2-80 Characters).');
  END IF;

  IF v_clean_username !~ '^[a-z0-9][a-z0-9_.]{2,19}$' THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_username',
      'message', 'Username Must Be 3-20 Characters Using Letters, Numbers, Underscores, Or Periods.');
  END IF;

  IF public.is_reserved_username(v_clean_username) THEN
    RETURN jsonb_build_object('success', false, 'error', 'username_reserved',
      'message', 'That Username Is Reserved. Pick A Different One.');
  END IF;

  IF v_clean_phone IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_phone',
      'message', 'Phone Number Is Required.');
  END IF;
  v_phone_digits := regexp_replace(v_clean_phone, '[^0-9]', '', 'g');
  IF length(v_phone_digits) < 7 OR length(v_phone_digits) > 15 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_phone',
      'message', 'Enter A Valid Phone Number (7-15 Digits).');
  END IF;

  BEGIN
    UPDATE public.profiles
       SET full_name                 = v_clean_name,
           username                  = v_clean_username,
           phone                     = v_clean_phone,
           social_profile_completed  = true,
           last_active               = now()
     WHERE id = v_uid
     RETURNING * INTO v_profile;
  EXCEPTION
    WHEN unique_violation THEN
      RETURN jsonb_build_object('success', false, 'error', 'username_taken',
        'message', 'That Username Was Just Claimed By Someone Else. Pick Another.');
  END;

  IF v_profile.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'profile_missing',
      'message', 'Your Profile Row Is Missing - Refresh And Try Again.');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'profile', jsonb_build_object(
      'id',        v_profile.id,
      'full_name', v_profile.full_name,
      'username',  v_profile.username,
      'phone',     v_profile.phone,
      'social_profile_completed', v_profile.social_profile_completed
    )
  );
END;
$_$;


ALTER FUNCTION public.claim_social_profile(p_full_name text, p_username text, p_phone text) OWNER TO postgres;

--
-- Name: claim_stripe_webhook_event(text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_stripe_webhook_event(p_event_id text, p_event_type text, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event public.stripe_webhook_events%ROWTYPE;
BEGIN
  INSERT INTO public.stripe_webhook_events(event_id, event_type, processing_status, locked_at)
  VALUES (p_event_id, p_event_type, 'processing', now())
  ON CONFLICT (event_id) DO NOTHING
  RETURNING * INTO v_event;
  IF FOUND THEN RETURN jsonb_build_object('claimed', true, 'state', 'processing'); END IF;

  SELECT * INTO v_event FROM public.stripe_webhook_events WHERE event_id = p_event_id FOR UPDATE;
  IF v_event.processing_status = 'done' THEN
    RETURN jsonb_build_object('claimed', false, 'state', 'done');
  END IF;
  IF v_event.locked_at IS NULL
     OR v_event.locked_at < now() - make_interval(secs => GREATEST(30, p_lease_seconds)) THEN
    UPDATE public.stripe_webhook_events
       SET processing_status = 'processing', locked_at = now()
     WHERE event_id = p_event_id;
    RETURN jsonb_build_object('claimed', true, 'state', 'reclaimed');
  END IF;
  RETURN jsonb_build_object('claimed', false, 'state', 'processing');
END;
$$;


ALTER FUNCTION public.claim_stripe_webhook_event(p_event_id text, p_event_type text, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: claim_table_lease_v2(uuid, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_table_lease_v2(p_table_id uuid, p_instance_id text, p_version text DEFAULT NULL::text, p_requested_generation uuid DEFAULT NULL::uuid, p_stale_seconds integer DEFAULT 30) RETURNS TABLE(granted boolean, holder text, holder_age_seconds numeric, lease_generation uuid, protocol_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_holder text;
  v_heartbeat timestamptz;
  v_generation uuid;
  v_protocol integer;
BEGIN
  IF p_table_id IS NULL
     OR length(btrim(COALESCE(p_instance_id, ''))) = 0
     OR p_requested_generation IS NULL THEN
    RAISE EXCEPTION
      'claim_table_lease_v2 requires table_id, instance_id, and requested_generation'
      USING ERRCODE = '22023';
  END IF;
  IF p_stale_seconds IS DISTINCT FROM public.fn_engine_lease_stale_seconds() THEN
    RAISE EXCEPTION 'claim_table_lease_v2 requires the audited 30 second stale window'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.engine_table_leases AS l (
    table_id,
    instance_id,
    engine_version,
    acquired_at,
    heartbeat_at,
    lease_generation,
    protocol_version
  ) VALUES (
    p_table_id,
    p_instance_id,
    p_version,
    clock_timestamp(),
    clock_timestamp(),
    p_requested_generation,
    2
  )
  ON CONFLICT (table_id) DO UPDATE
     SET instance_id = EXCLUDED.instance_id,
         engine_version = EXCLUDED.engine_version,
         acquired_at = CASE
           WHEN l.protocol_version = 2
            AND l.instance_id = EXCLUDED.instance_id
            AND l.lease_generation = EXCLUDED.lease_generation THEN l.acquired_at
           ELSE clock_timestamp()
         END,
         heartbeat_at = clock_timestamp(),
         lease_generation = EXCLUDED.lease_generation,
         protocol_version = 2
   WHERE (
       l.protocol_version = 2
       AND l.instance_id = EXCLUDED.instance_id
       AND l.lease_generation = EXCLUDED.lease_generation
     )
      OR (
       l.protocol_version < 2
       AND l.instance_id = EXCLUDED.instance_id
     )
      OR (
           l.heartbeat_at < clock_timestamp() - make_interval(
             secs => public.fn_engine_lease_stale_seconds()
           )
       AND l.lease_generation IS DISTINCT FROM EXCLUDED.lease_generation
         )
  RETURNING l.instance_id,
            l.heartbeat_at,
            l.lease_generation,
            l.protocol_version
       INTO v_holder, v_heartbeat, v_generation, v_protocol;

  IF v_holder IS NOT NULL THEN
    RETURN QUERY SELECT true, v_holder, 0::numeric, v_generation, v_protocol;
    RETURN;
  END IF;

  SELECT l.instance_id,
         l.heartbeat_at,
         l.lease_generation,
         l.protocol_version
    INTO v_holder, v_heartbeat, v_generation, v_protocol
    FROM public.engine_table_leases l
   WHERE l.table_id = p_table_id;

  RETURN QUERY
    SELECT false,
           v_holder,
           round(extract(epoch FROM (clock_timestamp() - v_heartbeat))::numeric, 1),
           v_generation,
           v_protocol;
END;
$$;


ALTER FUNCTION public.claim_table_lease_v2(p_table_id uuid, p_instance_id text, p_version text, p_requested_generation uuid, p_stale_seconds integer) OWNER TO postgres;

--
-- Name: FUNCTION claim_table_lease_v2(p_table_id uuid, p_instance_id text, p_version text, p_requested_generation uuid, p_stale_seconds integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_table_lease_v2(p_table_id uuid, p_instance_id text, p_version text, p_requested_generation uuid, p_stale_seconds integer) IS 'Claims one caller-selected table generation. Exact retry is stable only while fresh; a different live protocol-2 generation is refused even for the same instance; a stale row requires a different generation.';


--
-- Name: claim_tournament_lease_v2(uuid, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_tournament_lease_v2(p_tournament_id uuid, p_instance_id text, p_version text DEFAULT NULL::text, p_requested_generation uuid DEFAULT NULL::uuid, p_stale_seconds integer DEFAULT 30) RETURNS TABLE(granted boolean, holder text, holder_age_seconds numeric, lease_generation uuid, protocol_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_holder text;
  v_heartbeat timestamptz;
  v_generation uuid;
BEGIN
  IF p_tournament_id IS NULL
     OR length(btrim(COALESCE(p_instance_id, ''))) = 0
     OR p_requested_generation IS NULL THEN
    RAISE EXCEPTION
      'claim_tournament_lease_v2 requires tournament_id, instance_id, and requested_generation'
      USING ERRCODE = '22023';
  END IF;
  IF p_stale_seconds IS DISTINCT FROM 30 THEN
    RAISE EXCEPTION 'claim_tournament_lease_v2 requires the audited 30-second stale window'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.engine_tournament_leases AS l (
    tournament_id,
    instance_id,
    engine_version,
    acquired_at,
    heartbeat_at,
    lease_generation,
    protocol_version
  ) VALUES (
    p_tournament_id,
    p_instance_id,
    p_version,
    clock_timestamp(),
    clock_timestamp(),
    p_requested_generation,
    2
  )
  ON CONFLICT (tournament_id) DO UPDATE
     SET instance_id = EXCLUDED.instance_id,
         engine_version = EXCLUDED.engine_version,
         acquired_at = CASE
           WHEN l.protocol_version = 2
            AND l.instance_id = EXCLUDED.instance_id
            AND l.lease_generation = EXCLUDED.lease_generation THEN l.acquired_at
           ELSE clock_timestamp()
         END,
         heartbeat_at = clock_timestamp(),
         lease_generation = EXCLUDED.lease_generation,
         protocol_version = 2
   WHERE (
           l.protocol_version = 2
       AND l.instance_id = EXCLUDED.instance_id
       AND l.lease_generation = EXCLUDED.lease_generation
         )
      OR (
           l.protocol_version < 2
       AND l.instance_id = EXCLUDED.instance_id
         )
      OR (
           l.heartbeat_at < clock_timestamp() - interval '30 seconds'
       AND l.lease_generation IS DISTINCT FROM EXCLUDED.lease_generation
         )
  RETURNING l.instance_id, l.heartbeat_at, l.lease_generation
       INTO v_holder, v_heartbeat, v_generation;

  IF v_holder IS NOT NULL THEN
    RETURN QUERY SELECT true, v_holder, 0::numeric, v_generation, 2;
    RETURN;
  END IF;

  SELECT l.instance_id, l.heartbeat_at, l.lease_generation
    INTO v_holder, v_heartbeat, v_generation
    FROM public.engine_tournament_leases l
   WHERE l.tournament_id = p_tournament_id;

  RETURN QUERY
    SELECT false,
           v_holder,
           round(extract(epoch FROM (clock_timestamp() - v_heartbeat))::numeric, 1),
           v_generation,
           (SELECT l.protocol_version
              FROM public.engine_tournament_leases l
             WHERE l.tournament_id = p_tournament_id);
END;
$$;


ALTER FUNCTION public.claim_tournament_lease_v2(p_tournament_id uuid, p_instance_id text, p_version text, p_requested_generation uuid, p_stale_seconds integer) OWNER TO postgres;

--
-- Name: FUNCTION claim_tournament_lease_v2(p_tournament_id uuid, p_instance_id text, p_version text, p_requested_generation uuid, p_stale_seconds integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_tournament_lease_v2(p_tournament_id uuid, p_instance_id text, p_version text, p_requested_generation uuid, p_stale_seconds integer) IS 'Claims one caller-selected tournament generation. Exact retry preserves it only while fresh; a distinct generation may replace a stale row, while same-instance protocol-1 rows may upgrade once. Upgrades the row to protocol 2 so legacy mutation doors self-close.';


--
-- Name: claim_vip_subscription_checkout(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_vip_subscription_checkout(p_user_id uuid, p_request_id text, p_intent_hash text, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_claim public.vip_subscription_checkout_claims%ROWTYPE;
  v_profile public.profiles%ROWTYPE;
BEGIN
  IF p_request_id IS NULL OR p_intent_hash !~ '^[a-f0-9]{64}$' THEN
    RETURN jsonb_build_object('claimed', false, 'state', 'invalid');
  END IF;

  -- Both purchase methods take this same row lock before inspecting the
  -- opposite rail. Whichever transaction commits first leaves durable state
  -- that makes the other transaction fail closed.
  SELECT * INTO v_profile
    FROM public.profiles
   WHERE id = p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('claimed', false, 'state', 'profile_not_found');
  END IF;

  -- Preserve existing Card claim replay and conflict behavior before testing
  -- whether a new Card acquisition may begin.
  SELECT * INTO v_claim
    FROM public.vip_subscription_checkout_claims
   WHERE user_id = p_user_id
   FOR UPDATE;
  IF FOUND AND (
    v_claim.state = 'admitting'
    OR v_claim.expires_at > now()
  ) THEN
    IF v_claim.request_id = p_request_id AND v_claim.intent_hash = p_intent_hash THEN
      IF v_claim.state IN ('initializing', 'admitting') THEN
        UPDATE public.vip_subscription_checkout_claims
           SET expires_at = GREATEST(
                 expires_at,
                 now() + make_interval(secs => GREATEST(60, p_lease_seconds))
               ),
               updated_at = now()
         WHERE user_id = p_user_id
           AND request_id = p_request_id
           AND intent_hash = p_intent_hash
        RETURNING * INTO v_claim;
      END IF;
      RETURN jsonb_build_object(
        'claimed', false,
        'state', v_claim.state,
        'session_id', v_claim.session_id,
        'session_url', v_claim.session_url
      );
    END IF;
    RETURN jsonb_build_object('claimed', false, 'state', 'conflict');
  END IF;

  DELETE FROM public.vip_subscription_checkout_claims
   WHERE user_id = p_user_id
     AND state <> 'admitting';

  -- Do not sell overlapping time. This covers current v3 Diamond purchases,
  -- older Diamond grants, promotional prepaid terms, and any legacy active
  -- profile that predates the durable Diamond request table.
  IF v_profile.vip_tier = 'lifetime'
     OR (v_profile.vip_expires_at IS NOT NULL AND v_profile.vip_expires_at > now()) THEN
    RETURN jsonb_build_object('claimed', false, 'state', 'vip_entitlement_active');
  END IF;

  INSERT INTO public.vip_subscription_checkout_claims(
    user_id, request_id, intent_hash, state, expires_at
  ) VALUES (
    p_user_id,
    p_request_id,
    p_intent_hash,
    'initializing',
    now() + make_interval(secs => GREATEST(60, p_lease_seconds))
  );
  RETURN jsonb_build_object('claimed', true, 'state', 'initializing');
END;
$_$;


ALTER FUNCTION public.claim_vip_subscription_checkout(p_user_id uuid, p_request_id text, p_intent_hash text, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: FUNCTION claim_vip_subscription_checkout(p_user_id uuid, p_request_id text, p_intent_hash text, p_lease_seconds integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_vip_subscription_checkout(p_user_id uuid, p_request_id text, p_intent_hash text, p_lease_seconds integer) IS 'marketplace_phase7_vip_acquisition_mutex:v1';


