--
-- Name: cleanup_reserved_certification_account(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cleanup_reserved_certification_account(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '10min'
    AS $$
DECLARE
  v_email text;
  v_audit_count integer;
  v_archived_count integer;
BEGIN
  SELECT email INTO v_email FROM auth.users WHERE id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    IF EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id)
       OR EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id) THEN
      RAISE EXCEPTION 'Cannot Verify Certification Marker For Residual Identity %', p_user_id
        USING ERRCODE = '42501';
    END IF;
    RETURN jsonb_build_object('success', true, 'already_removed', true);
  END IF;
  IF v_email NOT LIKE 'ca-customization-cert-%@example.invalid' THEN
    RAISE EXCEPTION 'Refusing To Remove Non-Certification Identity %', p_user_id
      USING ERRCODE = '42501';
  END IF;
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('success', false, 'reason', 'platform_is_frozen');
  END IF;

  PERFORM set_config(
    'app.ledger_maintenance',
    'certification-cleanup:20260906022000:' || p_user_id::text,
    true
  );
  PERFORM set_config('app.game_management_retention', 'on', true);

  DELETE FROM public.user_daily_challenges WHERE user_id = p_user_id;
  DELETE FROM public.challenge_streak_state WHERE user_id = p_user_id;
  DELETE FROM public.club_members WHERE user_id = p_user_id;

  DELETE FROM public.push_outbox WHERE recipient_user_id = p_user_id;
  DELETE FROM public.chip_transactions WHERE from_user_id = p_user_id OR to_user_id = p_user_id;
  DELETE FROM public.daily_mission_operations WHERE user_id = p_user_id;
  DELETE FROM public.daily_challenge_event_outbox WHERE user_id = p_user_id;
  DELETE FROM public.daily_challenge_progress_events WHERE user_id = p_user_id;
  DELETE FROM public.daily_challenge_milestone_claims WHERE user_id = p_user_id;
  DELETE FROM public.daily_challenge_claim_batches WHERE user_id = p_user_id;
  DELETE FROM public.user_notification_preferences WHERE user_id = p_user_id;
  DELETE FROM public.notifications WHERE user_id = p_user_id OR actor_id = p_user_id;
  DELETE FROM public.daily_challenge_dashboard_revisions WHERE user_id = p_user_id;
  DELETE FROM public.wallet_credit_idempotency WHERE user_id = p_user_id;
  DELETE FROM public.wallet_transactions WHERE user_id = p_user_id;
  DELETE FROM public.wallets WHERE user_id = p_user_id;
  DELETE FROM public.customization_operations WHERE user_id = p_user_id;
  DELETE FROM public.user_theme_settings WHERE user_id = p_user_id;
  DELETE FROM public.user_table_studio_preferences WHERE user_id = p_user_id;
  DELETE FROM public.theme_asset_unlocks WHERE user_id = p_user_id;
  DELETE FROM public.avatar_unlocks WHERE user_id = p_user_id;
  DELETE FROM public.feature_purchases WHERE user_id = p_user_id;
  DELETE FROM public.diamond_transactions WHERE user_id = p_user_id;
  DELETE FROM public.diamond_wallets WHERE user_id = p_user_id;
  DELETE FROM public.signup_errors WHERE user_id = p_user_id;
  DELETE FROM public.table_waitlist WHERE user_id = p_user_id;
  DELETE FROM public.rate_limits WHERE user_id = p_user_id;

  SELECT count(*) INTO v_audit_count
    FROM public.audit_trail WHERE actor_id = p_user_id;

  INSERT INTO public.ca_test_account_audit_archive
    (audit_id, actor_id, actor_email, audit_row)
  SELECT a.id, p_user_id, v_email, to_jsonb(a)
    FROM public.audit_trail a
   WHERE a.actor_id = p_user_id
  ON CONFLICT (audit_id) DO NOTHING;

  SELECT count(*) INTO v_archived_count
    FROM public.ca_test_account_audit_archive x
   WHERE x.audit_id IN (
     SELECT a.id FROM public.audit_trail a WHERE a.actor_id = p_user_id
   );
  IF v_archived_count <> v_audit_count THEN
    RAISE EXCEPTION
      'Reserved Certification Audit Archive Copied % Of % Rows For %',
      v_archived_count, v_audit_count, p_user_id;
  END IF;

  DELETE FROM public.audit_trail WHERE actor_id = p_user_id;
  DELETE FROM public.users WHERE id = p_user_id;
  DELETE FROM auth.users WHERE id = p_user_id;

  IF EXISTS (SELECT 1 FROM auth.users WHERE id = p_user_id)
     OR EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id)
     OR EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'Reserved Certification Identity % Was Not Fully Removed', p_user_id;
  END IF;
  RETURN jsonb_build_object(
    'success', true,
    'already_removed', false,
    'user_id', p_user_id,
    'audit_rows_archived', v_audit_count
  );
END;
$$;


ALTER FUNCTION public.cleanup_reserved_certification_account(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION cleanup_reserved_certification_account(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.cleanup_reserved_certification_account(p_user_id uuid) IS 'Removes only locked ca-customization-cert-* identities after preserving their complete audit rows in the immutable test-account audit archive.';


--
-- Name: cleanup_zombie_streams(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cleanup_zombie_streams() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  UPDATE live_streams SET status = 'ended', ended_at = NOW()
  WHERE status = 'live' AND started_at < NOW() - INTERVAL '6 hours';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  -- Also clean up viewer records for ended streams
  DELETE FROM live_viewers WHERE stream_id IN (
    SELECT id FROM live_streams WHERE status = 'ended'
  );
  RETURN v_count;
END; $$;


ALTER FUNCTION public.cleanup_zombie_streams() OWNER TO postgres;

--
-- Name: clone_home_game(uuid, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clone_home_game(p_source_game_id uuid, p_new_scheduled_date date, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_source  RECORD;
    v_group   RECORD;
    v_new_id  uuid;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    IF p_new_scheduled_date <= CURRENT_DATE THEN RAISE EXCEPTION 'DATE_MUST_BE_FUTURE'; END IF;

    SELECT * INTO v_source FROM commander_home_games WHERE id = p_source_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'SOURCE_GAME_NOT_FOUND'; END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_source.group_id;

    IF v_source.host_id <> p_caller_user_id 
       AND v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members 
                        WHERE group_id = v_source.group_id AND user_id = p_caller_user_id
                          AND role = 'admin' AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;

    -- Check dup on target date
    IF EXISTS (SELECT 1 FROM commander_home_games 
                WHERE group_id = v_source.group_id 
                  AND scheduled_date = p_new_scheduled_date 
                  AND status NOT IN ('cancelled'))
    THEN RAISE EXCEPTION 'DATE_ALREADY_SCHEDULED'; END IF;

    INSERT INTO commander_home_games (
        group_id, host_id, title, description, 
        game_type, stakes, format, 
        buyin_min, buyin_max,
        scheduled_date, start_time, end_time,
        address, address_visible_to, location_notes, neighborhood,
        max_players, min_players, allow_guests, guest_limit,
        food_drinks, special_rules, status
    ) VALUES (
        v_source.group_id, p_caller_user_id, v_source.title, v_source.description,
        v_source.game_type, v_source.stakes, v_source.format,
        v_source.buyin_min, v_source.buyin_max,
        p_new_scheduled_date, v_source.start_time, v_source.end_time,
        v_source.address, v_source.address_visible_to, v_source.location_notes, v_source.neighborhood,
        v_source.max_players, v_source.min_players, v_source.allow_guests, v_source.guest_limit,
        v_source.food_drinks, v_source.special_rules, 'scheduled'
    ) RETURNING id INTO v_new_id;

    INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (v_source.group_id, p_caller_user_id, 'game', v_new_id, 'cloned',
            jsonb_build_object('source_game_id', p_source_game_id, 'new_date', p_new_scheduled_date));

    RETURN jsonb_build_object('success', true, 'new_game_id', v_new_id);
END;
$$;


ALTER FUNCTION public.clone_home_game(p_source_game_id uuid, p_new_scheduled_date date, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: close_home_game_rsvps(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_home_game_rsvps(p_game_id uuid, p_caller_user_id uuid, p_reopen boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_game RECORD; v_group RECORD;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;

    IF v_game.host_id <> p_caller_user_id AND v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members 
                        WHERE group_id = v_game.group_id AND user_id = p_caller_user_id
                          AND role = 'admin' AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;

    UPDATE commander_home_games 
       SET rsvps_closed = NOT p_reopen, updated_at = NOW()
     WHERE id = p_game_id;

    RETURN jsonb_build_object('success', true, 'rsvps_closed', NOT p_reopen);
END;
$$;


ALTER FUNCTION public.close_home_game_rsvps(p_game_id uuid, p_caller_user_id uuid, p_reopen boolean) OWNER TO postgres;

--
-- Name: close_table_session(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_table_session(p_table_id uuid, p_player_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_table_id is null or p_player_id is null then return; end if;
  update table_sessions
     set is_active = false,
         left_at = coalesce(left_at, now()),
         kick_reason = coalesce(p_reason, kick_reason)
   where table_id = p_table_id
     and player_id = p_player_id
     and is_active is true;
end $$;


