--
-- Name: commander_claim_finish_position(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commander_claim_finish_position(p_entry_id uuid, p_tournament_id uuid, p_eliminated_by uuid DEFAULT NULL::uuid) RETURNS TABLE(finish_position integer, remaining_after integer, entry jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_remaining integer;
  v_pos integer;
  v_row commander_tournament_entries%ROWTYPE;
BEGIN
  PERFORM 1 FROM commander_tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament % not found', p_tournament_id;
  END IF;

  -- FIELD COUNT, not seat occupancy. Must match the status set the UPDATE
  -- below is willing to eliminate, or a player is busted out of a field they
  -- were never counted in.
  --   'registered' - paid and in the event; rooms start with players still in
  --                  this state, so excluding it broke the numbering outright.
  --   'bagged'     - multi-day, chips in a bag, still alive.
  --   'alternate'  - NOT in the field yet. Correctly excluded.
  SELECT count(*) INTO v_remaining
  FROM commander_tournament_entries e
  WHERE e.tournament_id = p_tournament_id
    AND e.status IN ('registered', 'seated', 'active', 'bagged');

  IF v_remaining IS NULL OR v_remaining < 1 THEN
    v_remaining := 1;
  END IF;

  v_pos := v_remaining;
  WHILE v_pos > 1 AND EXISTS (
    SELECT 1 FROM commander_tournament_entries e
    WHERE e.tournament_id = p_tournament_id
      AND e.finish_position = v_pos
      AND e.id <> p_entry_id
  ) LOOP
    v_pos := v_pos - 1;
  END LOOP;

  UPDATE commander_tournament_entries e
  SET status = 'eliminated',
      eliminated_at = now(),
      eliminated_by = COALESCE(p_eliminated_by, e.eliminated_by),
      finish_position = v_pos,
      table_number = NULL,
      seat_number = NULL
  WHERE e.id = p_entry_id
    AND e.tournament_id = p_tournament_id
    AND e.status IN ('registered', 'seated', 'active', 'bagged')
  RETURNING e.* INTO v_row;

  IF v_row.id IS NULL THEN
    RETURN;
  END IF;

  finish_position := v_pos;
  remaining_after := GREATEST(v_remaining - 1, 0);
  entry := to_jsonb(v_row);
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.commander_claim_finish_position(p_entry_id uuid, p_tournament_id uuid, p_eliminated_by uuid) OWNER TO postgres;

--
-- Name: commander_claim_member_time_minutes(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commander_claim_member_time_minutes(p_member_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_claimed integer;
  v_exists  boolean;
begin
  if p_member_id is null then
    raise exception 'commander_claim_member_time_minutes: p_member_id is required'
      using errcode = '22023';
  end if;

  select true, coalesce(m.time_balance_minutes, 0)
    into v_exists, v_claimed
    from public.commander_members m
   where m.id = p_member_id
     for update;

  if not coalesce(v_exists, false) then
    raise exception 'commander_claim_member_time_minutes: member % not found', p_member_id
      using errcode = 'P0002';
  end if;

  if v_claimed < 0 then
    raise exception 'commander_claim_member_time_minutes: member % has a negative prepaid balance (%)',
      p_member_id, v_claimed
      using errcode = 'P0001';
  end if;

  update public.commander_members m
     set time_balance_minutes = 0,
         updated_at           = now()
   where m.id = p_member_id;

  return v_claimed;
end
$$;


ALTER FUNCTION public.commander_claim_member_time_minutes(p_member_id uuid) OWNER TO postgres;

--
-- Name: commander_claim_open_seat(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commander_claim_open_seat(p_entry_id uuid, p_tournament_id uuid, p_expected_status text DEFAULT NULL::text) RETURNS TABLE(table_number integer, seat_number integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venue_id integer;
  v_starting_chips integer;
  v_seat record;
  v_current_status text;
BEGIN
  SELECT venue_id, starting_chips INTO v_venue_id, v_starting_chips
  FROM commander_tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament % not found', p_tournament_id;
  END IF;

  SELECT status INTO v_current_status
  FROM commander_tournament_entries
  WHERE id = p_entry_id AND tournament_id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  IF p_expected_status IS NOT NULL AND v_current_status IS DISTINCT FROM p_expected_status THEN
    RETURN;
  END IF;

  WITH pool AS (
    SELECT ct.table_number, COALESCE(ct.max_seats, 9) AS max_seats
    FROM commander_tables ct
    WHERE ct.venue_id = v_venue_id
      AND ct.tournament_id = p_tournament_id
      AND ct.status IS DISTINCT FROM 'maintenance'
    UNION
    SELECT e.table_number, 9
    FROM commander_tournament_entries e
    WHERE e.tournament_id = p_tournament_id
      AND e.status IN ('registered','seated','active')
      AND e.table_number IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM commander_tables ct2
        WHERE ct2.venue_id = v_venue_id AND ct2.tournament_id = p_tournament_id
      )
  ),
  occupancy AS (
    SELECT p.table_number, p.max_seats,
           (SELECT count(*) FROM commander_tournament_entries e
             WHERE e.tournament_id = p_tournament_id
               AND e.status IN ('registered','seated','active')
               AND e.seat_number IS NOT NULL
               AND e.table_number = p.table_number) AS seated_count
    FROM pool p
  ),
  candidates AS (
    SELECT o.table_number, s.seat_number, o.seated_count
    FROM occupancy o
    CROSS JOIN LATERAL generate_series(1, o.max_seats) AS s(seat_number)
    WHERE NOT EXISTS (
      SELECT 1 FROM commander_tournament_entries e
      WHERE e.tournament_id = p_tournament_id
        AND e.status IN ('registered','seated','active')
        AND e.table_number = o.table_number
        AND e.seat_number = s.seat_number
        AND e.id <> p_entry_id
    )
  )
  SELECT c.table_number, c.seat_number INTO v_seat
  FROM candidates c
  ORDER BY c.seated_count ASC, c.table_number ASC, c.seat_number ASC
  LIMIT 1;

  IF v_seat IS NULL THEN
    RETURN;
  END IF;

  UPDATE commander_tournament_entries e
  SET table_number = v_seat.table_number,
      seat_number  = v_seat.seat_number,
      status       = CASE WHEN e.status = 'active' THEN 'active' ELSE 'seated' END,
      current_chips = CASE
                        WHEN COALESCE(e.current_chips, 0) > 0 THEN e.current_chips
                        ELSE COALESCE(v_starting_chips, 0)
                      END
  WHERE e.id = p_entry_id AND e.tournament_id = p_tournament_id;

  table_number := v_seat.table_number;
  seat_number  := v_seat.seat_number;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.commander_claim_open_seat(p_entry_id uuid, p_tournament_id uuid, p_expected_status text) OWNER TO postgres;

--
-- Name: commander_clock_write(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commander_clock_write(p_tournament_id uuid, p_clock_state jsonb, p_updates jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  v_venue integer;
  v_is_engine boolean;
BEGIN
  v_is_engine := COALESCE(auth.role(), 'service_role') = 'service_role';

  SELECT venue_id INTO v_venue FROM commander_tournaments WHERE id = p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament % not found', p_tournament_id;
  END IF;

  -- The clock is the room's authority. Only the floor may move it.
  IF NOT v_is_engine THEN
    IF NOT EXISTS (
      SELECT 1 FROM commander_staff s
       WHERE s.venue_id = v_venue
         AND s.user_id = (SELECT auth.uid())
         AND s.is_active
    ) THEN
      RAISE EXCEPTION
        'commander_clock_write refused: not active staff at venue %', v_venue
        USING ERRCODE = '42501';
    END IF;
  END IF;

  UPDATE commander_tournaments SET
    settings = jsonb_set(COALESCE(settings, '{}'::jsonb), '{clock_state}', COALESCE(p_clock_state, 'null'::jsonb)),
    status = COALESCE(p_updates->>'status', status),
    current_level = COALESCE((p_updates->>'current_level')::integer, current_level),
    actual_start = COALESCE((p_updates->>'actual_start')::timestamptz, actual_start),
    ended_at = COALESCE((p_updates->>'ended_at')::timestamptz, ended_at),
    updated_at = now()
  WHERE id = p_tournament_id
  RETURNING to_jsonb(commander_tournaments.*) INTO result;

  IF result IS NULL THEN
    RAISE EXCEPTION 'Tournament % not found', p_tournament_id;
  END IF;

  RETURN result;
END;
$$;


ALTER FUNCTION public.commander_clock_write(p_tournament_id uuid, p_clock_state jsonb, p_updates jsonb) OWNER TO postgres;

--
-- Name: FUNCTION commander_clock_write(p_tournament_id uuid, p_clock_state jsonb, p_updates jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.commander_clock_write(p_tournament_id uuid, p_clock_state jsonb, p_updates jsonb) IS 'Atomic write of settings.clock_state plus status/current_level/actual_start/ended_at. Requires service_role or active commander_staff at the tournament venue - the same predicate as the captain_tournaments_update RLS policy this SECURITY DEFINER function would otherwise bypass. Hardened 2026-08-27.';


--
-- Name: commander_end_table_session(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commander_end_table_session(p_session_id uuid, p_ended_by text DEFAULT NULL::text) RETURNS public.commander_table_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.commander_table_sessions;
begin
  if p_session_id is null then
    raise exception 'commander_end_table_session: p_session_id is required'
      using errcode = '22023';
  end if;

  update public.commander_table_sessions s
     set status     = 'ended',
         ended_at   = now(),
         ended_by   = coalesce(p_ended_by, s.ended_by),
         updated_at = now()
   where s.id = p_session_id
     and s.status <> 'ended'
  returning s.* into v_row;

  -- v_row.id is NULL when the row was already ended (or does not exist); the
  -- caller treats that as "somebody else ended it" and does not pay out again.
  return v_row;
end
$$;


ALTER FUNCTION public.commander_end_table_session(p_session_id uuid, p_ended_by text) OWNER TO postgres;

--
-- Name: commander_entries_sync_reentry_marker(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commander_entries_sync_reentry_marker() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_flag text;
  v_of   text;
BEGIN
  v_flag := NEW.metadata ->> 'is_reentry';
  v_of   := NEW.metadata ->> 'reentry_of';

  IF v_flag IS NOT NULL THEN
    NEW.is_reentry := (lower(v_flag) IN ('true','t','1'));
  END IF;

  -- A malformed id must never reject the write: the entry matters more.
  IF v_of IS NOT NULL AND v_of <> '' THEN
    BEGIN
      NEW.reentry_of := v_of::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE WARNING 'sync_reentry_marker: metadata.reentry_of is not a uuid (%), left unset', v_of;
    END;
  END IF;

  IF NEW.reentry_of IS NOT NULL THEN
    NEW.is_reentry := true;
  END IF;

  -- An entry can never be its own origin.
  IF NEW.reentry_of IS NOT NULL AND NEW.reentry_of = NEW.id THEN
    NEW.reentry_of := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.commander_entries_sync_reentry_marker() OWNER TO postgres;

--
-- Name: commander_txn_award_comp(uuid, integer, numeric, numeric, integer, numeric, numeric, text, text, text, boolean, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commander_txn_award_comp(p_member_id uuid, p_venue_id integer, p_log_amount numeric, p_comp_delta numeric DEFAULT 0, p_time_delta integer DEFAULT 0, p_earned_delta numeric DEFAULT 0, p_redeemed_delta numeric DEFAULT 0, p_type text DEFAULT 'award'::text, p_reason text DEFAULT NULL::text, p_authorized_by text DEFAULT NULL::text, p_authorized_pin boolean DEFAULT false, p_processed_by uuid DEFAULT NULL::uuid, p_comp_category text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_member public.commander_members;
  v_txn    public.commander_member_comp_log;
begin
  if p_member_id is null or p_venue_id is null then
    raise exception 'commander_txn_award_comp: p_member_id and p_venue_id are required' using errcode = '22023';
  end if;

  begin
    insert into public.commander_member_comp_log
      (venue_id, member_id, amount, type, reason, authorized_by, authorized_pin,
       processed_by, balance_after, comp_category, notes, idempotency_key)
    values
      (p_venue_id, p_member_id, coalesce(p_log_amount, 0), coalesce(p_type, 'award'), p_reason,
       p_authorized_by, coalesce(p_authorized_pin, false), p_processed_by,
       0, p_comp_category, p_notes, p_idempotency_key)
    returning * into v_txn;
  exception when unique_violation then
    select * into v_txn from public.commander_member_comp_log where idempotency_key = p_idempotency_key;
    if v_txn.id is null then raise; end if;
    select * into v_member from public.commander_members where id = p_member_id;
    return jsonb_build_object('replayed', true, 'member', to_jsonb(v_member), 'transaction', to_jsonb(v_txn));
  end;

  v_member := public.commander_adjust_member_balances(
    p_member_id, p_comp_delta, p_time_delta, p_earned_delta, p_redeemed_delta
  );

  -- balance_after is only knowable once the balance has actually moved.
  update public.commander_member_comp_log l
     set balance_after = v_member.comp_balance
   where l.id = v_txn.id
  returning l.* into v_txn;

  return jsonb_build_object('replayed', false, 'member', to_jsonb(v_member), 'transaction', to_jsonb(v_txn));
end
$$;


ALTER FUNCTION public.commander_txn_award_comp(p_member_id uuid, p_venue_id integer, p_log_amount numeric, p_comp_delta numeric, p_time_delta integer, p_earned_delta numeric, p_redeemed_delta numeric, p_type text, p_reason text, p_authorized_by text, p_authorized_pin boolean, p_processed_by uuid, p_comp_category text, p_notes text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: commander_txn_member_time_purchase(uuid, integer, uuid, bigint, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commander_txn_member_time_purchase(p_member_id uuid, p_minutes integer, p_session_id uuid DEFAULT NULL::uuid, p_venue_id bigint DEFAULT NULL::bigint, p_amount_paid numeric DEFAULT NULL::numeric, p_payment_method text DEFAULT NULL::text, p_purchased_by text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_member   public.commander_members;
  v_txn      public.commander_time_purchases;
  v_prev     integer;
  v_new      integer;
  v_seated   boolean := p_session_id is not null;
begin
  if p_member_id is null then
    raise exception 'commander_txn_member_time_purchase: p_member_id is required' using errcode = '22023';
  end if;
  if p_minutes is null or p_minutes <= 0 then
    raise exception 'commander_txn_member_time_purchase: p_minutes must be positive (got %)', p_minutes
      using errcode = '22023';
  end if;

  select * into v_member from public.commander_members where id = p_member_id;
  if v_member.id is null then
    raise exception 'commander_txn_member_time_purchase: member % not found', p_member_id using errcode = 'P0002';
  end if;
  v_prev := coalesce(v_member.time_balance_minutes, 0);

  begin
    insert into public.commander_time_purchases
      (venue_id, member_id, minutes_purchased, amount_paid, payment_method, purchased_by, idempotency_key)
    values
      (p_venue_id, p_member_id, p_minutes, p_amount_paid, p_payment_method, p_purchased_by, p_idempotency_key)
    returning * into v_txn;
  exception when unique_violation then
    select * into v_txn from public.commander_time_purchases where idempotency_key = p_idempotency_key;
    if v_txn.id is null then raise; end if;
    select * into v_member from public.commander_members where id = p_member_id;
    return jsonb_build_object(
      'replayed', true,
      'member', to_jsonb(v_member),
      'transaction', to_jsonb(v_txn),
      'previous_balance', coalesce(v_member.time_balance_minutes, 0),
      'new_balance', coalesce(v_member.time_balance_minutes, 0),
      'added_to_active_session', v_seated
    );
  end;

  if v_seated then
    -- Minutes land on the table clock; the standing balance does not move.
    perform public.commander_adjust_session_added_minutes(p_session_id, p_minutes);
    v_new := v_prev;
    update public.commander_members m set updated_at = now() where m.id = p_member_id;
    select * into v_member from public.commander_members where id = p_member_id;
  else
    v_member := public.commander_adjust_member_balances(p_member_id, 0, p_minutes, 0, 0);
    v_new := coalesce(v_member.time_balance_minutes, 0);
  end if;

  return jsonb_build_object(
    'replayed', false,
    'member', to_jsonb(v_member),
    'transaction', to_jsonb(v_txn),
    'previous_balance', v_prev,
    'new_balance', v_new,
    'added_to_active_session', v_seated
  );
end
$$;


ALTER FUNCTION public.commander_txn_member_time_purchase(p_member_id uuid, p_minutes integer, p_session_id uuid, p_venue_id bigint, p_amount_paid numeric, p_payment_method text, p_purchased_by text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: commander_txn_session_buyin(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commander_txn_session_buyin(p_session_id uuid, p_amount numeric, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_session public.commander_player_sessions;
  v_txn     public.commander_buyin_transactions;
  v_total   integer;
begin
  if p_session_id is null then
    raise exception 'commander_txn_session_buyin: p_session_id is required' using errcode = '22023';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'commander_txn_session_buyin: p_amount must be a positive number (got %)', p_amount
      using errcode = '22023';
  end if;

  select * into v_session from public.commander_player_sessions where id = p_session_id;
  if v_session.id is null then
    raise exception 'commander_txn_session_buyin: session % not found', p_session_id using errcode = 'P0002';
  end if;
  if v_session.status is distinct from 'active' then
    raise exception 'commander_txn_session_buyin: session % is not active (status %)', p_session_id, v_session.status
      using errcode = 'P0001';
  end if;

  begin
    insert into public.commander_buyin_transactions
      (session_id, player_id, venue_id, amount, transaction_type, idempotency_key)
    values
      (p_session_id, v_session.player_id, v_session.venue_id, p_amount, 'buyin', p_idempotency_key)
    returning * into v_txn;
  exception when unique_violation then
    select * into v_txn
      from public.commander_buyin_transactions
     where idempotency_key = p_idempotency_key;
    if v_txn.id is null then raise; end if;
    select * into v_session from public.commander_player_sessions where id = p_session_id;
    return jsonb_build_object(
      'replayed', true,
      'session', to_jsonb(v_session),
      'transaction', to_jsonb(v_txn),
      'new_total', v_session.total_buyin
    );
  end;

  update public.commander_player_sessions s
     set total_buyin = coalesce(s.total_buyin, 0) + round(p_amount)::integer
   where s.id = p_session_id
  returning s.total_buyin into v_total;

  if v_total < 0 then
    raise exception 'commander_txn_session_buyin: total_buyin for session % would go negative', p_session_id
      using errcode = 'P0001';
  end if;

  select * into v_session from public.commander_player_sessions where id = p_session_id;

  return jsonb_build_object(
    'replayed', false,
    'session', to_jsonb(v_session),
    'transaction', to_jsonb(v_txn),
    'new_total', v_total
  );
end
$$;


ALTER FUNCTION public.commander_txn_session_buyin(p_session_id uuid, p_amount numeric, p_idempotency_key text) OWNER TO postgres;

--
-- Name: commander_txn_tournament_addon(uuid, uuid, integer, integer, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commander_txn_tournament_addon(p_entry_id uuid, p_tournament_id uuid, p_chips integer, p_venue_id integer DEFAULT NULL::integer, p_amount numeric DEFAULT 0, p_player_name text DEFAULT NULL::text, p_processed_by uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_entry public.commander_tournament_entries;
  v_txn   public.commander_cash_transactions;
begin
  if p_entry_id is null or p_tournament_id is null then
    raise exception 'commander_txn_tournament_addon: p_entry_id and p_tournament_id are required' using errcode='22023';
  end if;
  if p_chips is null or p_chips <= 0 then
    raise exception 'commander_txn_tournament_addon: p_chips must be positive (got %)', p_chips using errcode='22023';
  end if;

  if coalesce(p_amount,0) > 0 then
    begin
      -- 2026-08-22: tournament_id added, same reason as the rebuy RPC.
      insert into public.commander_cash_transactions
        (venue_id, tournament_id, player_name, type, amount, payment_method, processed_by, notes, idempotency_key)
      values
        (p_venue_id, p_tournament_id, coalesce(p_player_name,'Unknown'), 'buy_in', p_amount, 'cash', p_processed_by,
         'Tournament Add-on: ' || coalesce(p_player_name,'Unknown') || ' (ID: ' || p_entry_id::text || ')',
         p_idempotency_key)
      returning * into v_txn;
    exception when unique_violation then
      select * into v_txn from public.commander_cash_transactions where idempotency_key = p_idempotency_key;
      if v_txn.id is null then raise; end if;
      select * into v_entry from public.commander_tournament_entries where id = p_entry_id;
      return jsonb_build_object('replayed', true, 'entry', to_jsonb(v_entry), 'transaction', to_jsonb(v_txn));
    end;
  end if;

  update public.commander_tournament_entries e
     set current_chips = coalesce(e.current_chips,0) + p_chips,
         addon_taken   = true,
         metadata      = coalesce(e.metadata,'{}'::jsonb) || jsonb_build_object('addon_at', now())
   where e.id = p_entry_id
     and e.tournament_id = p_tournament_id
     and e.status in ('active','seated')
     and coalesce(e.addon_taken,false) = false
  returning e.* into v_entry;

  if v_entry.id is null then
    select * into v_entry from public.commander_tournament_entries
     where id = p_entry_id and tournament_id = p_tournament_id;
    if v_entry.id is null then
      raise exception 'commander_txn_tournament_addon: entry % not found in tournament %', p_entry_id, p_tournament_id using errcode='P0002';
    elsif coalesce(v_entry.addon_taken,false) then
      raise exception 'commander_txn_tournament_addon: entry % has already taken their add-on', p_entry_id using errcode='P0001';
    else
      raise exception 'commander_txn_tournament_addon: entry % must be active to take an add-on (status %)', p_entry_id, v_entry.status using errcode='P0001';
    end if;
  end if;

  return jsonb_build_object('replayed', false, 'entry', to_jsonb(v_entry), 'transaction', to_jsonb(v_txn));
end
$$;


ALTER FUNCTION public.commander_txn_tournament_addon(p_entry_id uuid, p_tournament_id uuid, p_chips integer, p_venue_id integer, p_amount numeric, p_player_name text, p_processed_by uuid, p_idempotency_key text) OWNER TO postgres;

--
-- Name: commander_txn_tournament_rebuy(uuid, uuid, integer, integer, integer, integer, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commander_txn_tournament_rebuy(p_entry_id uuid, p_tournament_id uuid, p_chips integer, p_max_rebuys integer, p_level integer DEFAULT 0, p_venue_id integer DEFAULT NULL::integer, p_amount numeric DEFAULT 0, p_player_name text DEFAULT NULL::text, p_processed_by uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_entry public.commander_tournament_entries;
  v_txn   public.commander_cash_transactions;
begin
  if p_entry_id is null or p_tournament_id is null then
    raise exception 'commander_txn_tournament_rebuy: p_entry_id and p_tournament_id are required' using errcode='22023';
  end if;
  if p_chips is null or p_chips <= 0 then
    raise exception 'commander_txn_tournament_rebuy: p_chips must be positive (got %)', p_chips using errcode='22023';
  end if;

  if coalesce(p_amount,0) > 0 then
    begin
      -- 2026-08-22: tournament_id added.
      insert into public.commander_cash_transactions
        (venue_id, tournament_id, player_name, type, amount, payment_method, processed_by, notes, idempotency_key)
      values
        (p_venue_id, p_tournament_id, coalesce(p_player_name,'Unknown'), 'buy_in', p_amount, 'cash', p_processed_by,
         'Tournament Rebuy: ' || coalesce(p_player_name,'Unknown') || ' (ID: ' || p_entry_id::text || ')',
         p_idempotency_key)
      returning * into v_txn;
    exception when unique_violation then
      select * into v_txn from public.commander_cash_transactions where idempotency_key = p_idempotency_key;
      if v_txn.id is null then raise; end if;
      select * into v_entry from public.commander_tournament_entries where id = p_entry_id;
      return jsonb_build_object('replayed', true, 'entry', to_jsonb(v_entry), 'transaction', to_jsonb(v_txn));
    end;
  end if;

  update public.commander_tournament_entries e
     set current_chips = coalesce(e.current_chips,0) + p_chips,
         rebuy_count   = coalesce(e.rebuy_count,0) + 1,
         status        = 'active',
         metadata      = coalesce(e.metadata,'{}'::jsonb)
                         || jsonb_build_object('last_rebuy_at', now(), 'last_rebuy_level', p_level)
   where e.id = p_entry_id
     and e.tournament_id = p_tournament_id
     and e.status is distinct from 'eliminated'
     and coalesce(e.rebuy_count,0) < coalesce(p_max_rebuys,999)
  returning e.* into v_entry;

  if v_entry.id is null then
    select * into v_entry from public.commander_tournament_entries
     where id = p_entry_id and tournament_id = p_tournament_id;
    if v_entry.id is null then
      raise exception 'commander_txn_tournament_rebuy: entry % not found in tournament %', p_entry_id, p_tournament_id using errcode='P0002';
    elsif v_entry.status = 'eliminated' then
      raise exception 'commander_txn_tournament_rebuy: entry % is eliminated', p_entry_id using errcode='P0001';
    else
      raise exception 'commander_txn_tournament_rebuy: entry % has reached the maximum of % rebuys', p_entry_id, coalesce(p_max_rebuys,999) using errcode='P0001';
    end if;
  end if;

  return jsonb_build_object('replayed', false, 'entry', to_jsonb(v_entry), 'transaction', to_jsonb(v_txn));
end
$$;


ALTER FUNCTION public.commander_txn_tournament_rebuy(p_entry_id uuid, p_tournament_id uuid, p_chips integer, p_max_rebuys integer, p_level integer, p_venue_id integer, p_amount numeric, p_player_name text, p_processed_by uuid, p_idempotency_key text) OWNER TO postgres;

--
-- Name: commit_leak_review_state(uuid, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commit_leak_review_state(p_user_id uuid, p_leak_id text, p_review_id text, p_expected_updated_at timestamp with time zone, p_candidate jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_state public.leak_review_state%ROWTYPE;
  v_exists boolean := false;
BEGIN
  IF p_user_id IS NULL OR p_leak_id !~ '^[A-Za-z0-9][A-Za-z0-9_:.-]{0,63}$'
     OR p_review_id !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{7,95}$'
     OR jsonb_typeof(COALESCE(p_candidate, '{}'::jsonb)) <> 'object' THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_payload');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('leak_review:' || p_user_id::text || ':' || p_leak_id, 0)
  );

  -- The operation ledger is authoritative even after later reviews advance
  -- the row: a delayed replay of A after B returns the current state unchanged.
  IF EXISTS (
    SELECT 1 FROM public.leak_review_operations
     WHERE user_id = p_user_id AND leak_id = p_leak_id AND review_id = p_review_id
  ) THEN
    SELECT * INTO v_state FROM public.leak_review_state
     WHERE user_id = p_user_id AND leak_id = p_leak_id;
    RETURN jsonb_build_object('success', true, 'idempotent', true, 'row', to_jsonb(v_state));
  END IF;

  SELECT * INTO v_state FROM public.leak_review_state
   WHERE user_id = p_user_id AND leak_id = p_leak_id
   FOR UPDATE;
  v_exists := FOUND;

  IF (v_exists AND (p_expected_updated_at IS NULL OR v_state.updated_at IS DISTINCT FROM p_expected_updated_at))
     OR (NOT v_exists AND p_expected_updated_at IS NOT NULL) THEN
    RETURN jsonb_build_object(
      'success', true, 'conflict', true,
      'row', CASE WHEN v_exists THEN to_jsonb(v_state) ELSE NULL END
    );
  END IF;

  INSERT INTO public.leak_review_state (
    user_id, leak_id, ease, interval_days, due_at, reps, lapses,
    strong_streak, retired, last_score, history, last_outcome,
    schema_version, created_at, updated_at
  ) VALUES (
    p_user_id, p_leak_id,
    LEAST(2.8, GREATEST(1.3, COALESCE((p_candidate->>'ease')::numeric, 2.3))),
    LEAST(21, GREATEST(0, COALESCE((p_candidate->>'interval_days')::integer, 0))),
    COALESCE((p_candidate->>'due_at')::timestamptz, now()),
    LEAST(100000, GREATEST(0, COALESCE((p_candidate->>'reps')::integer, 0))),
    LEAST(100000, GREATEST(0, COALESCE((p_candidate->>'lapses')::integer, 0))),
    LEAST(100000, GREATEST(0, COALESCE((p_candidate->>'strong_streak')::integer, 0))),
    COALESCE((p_candidate->>'retired')::boolean, false),
    CASE WHEN p_candidate->>'last_score' IS NULL THEN NULL
         ELSE LEAST(1, GREATEST(0, (p_candidate->>'last_score')::numeric)) END,
    COALESCE(p_candidate->'history', '[]'::jsonb),
    COALESCE(p_candidate->'last_outcome', '{}'::jsonb),
    GREATEST(1, COALESCE((p_candidate->>'schema_version')::integer, 1)),
    now(), now()
  )
  ON CONFLICT (user_id, leak_id) DO UPDATE SET
    ease = EXCLUDED.ease,
    interval_days = EXCLUDED.interval_days,
    due_at = EXCLUDED.due_at,
    reps = EXCLUDED.reps,
    lapses = EXCLUDED.lapses,
    strong_streak = EXCLUDED.strong_streak,
    retired = EXCLUDED.retired,
    last_score = EXCLUDED.last_score,
    history = EXCLUDED.history,
    last_outcome = EXCLUDED.last_outcome,
    schema_version = EXCLUDED.schema_version,
    updated_at = now()
  RETURNING * INTO v_state;

  INSERT INTO public.leak_review_operations (user_id, leak_id, review_id)
  VALUES (p_user_id, p_leak_id, p_review_id);

  RETURN jsonb_build_object('success', true, 'idempotent', false, 'row', to_jsonb(v_state));
END;
$_$;


ALTER FUNCTION public.commit_leak_review_state(p_user_id uuid, p_leak_id text, p_review_id text, p_expected_updated_at timestamp with time zone, p_candidate jsonb) OWNER TO postgres;

--
-- Name: complete_daily_challenge(uuid, uuid, integer, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_daily_challenge(p_user_id uuid, p_challenge_id uuid, p_score integer DEFAULT 0, p_accuracy numeric DEFAULT 0, p_time_taken integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_existing_id uuid;
  v_perfect boolean;
  v_diamonds integer;
  v_completion_id uuid;
  v_after integer;
BEGIN
  IF p_user_id IS NULL OR p_challenge_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'missing user_id or challenge_id');
  END IF;

  SELECT id INTO v_existing_id FROM memory_challenge_completions
   WHERE user_id = p_user_id AND challenge_id = p_challenge_id;

  IF v_existing_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'already_completed', true,
                              'completion_id', v_existing_id);
  END IF;

  v_perfect := (p_accuracy IS NOT NULL AND p_accuracy >= 1.0);
  v_diamonds := CASE
    WHEN v_perfect THEN 20
    WHEN p_accuracy >= 0.9 THEN 10
    WHEN p_accuracy >= 0.75 THEN 5
    ELSE 2 END;

  INSERT INTO memory_challenge_completions (
    id, user_id, challenge_id, score, accuracy, time_taken,
    perfect_completion, diamonds_earned, completed_at
  ) VALUES (
    gen_random_uuid(), p_user_id, p_challenge_id,
    COALESCE(p_score, 0), COALESCE(p_accuracy, 0), COALESCE(p_time_taken, 0),
    v_perfect, v_diamonds, NOW()
  ) RETURNING id INTO v_completion_id;

  UPDATE daily_challenges
     SET completed = true, completed_at = NOW()
   WHERE user_id = p_user_id AND completed = false AND challenge_date = CURRENT_DATE;

  UPDATE profiles
     SET diamonds = COALESCE(diamonds, 0) + v_diamonds,
         diamond_balance = COALESCE(diamond_balance, 0) + v_diamonds
   WHERE id = p_user_id
  RETURNING diamonds INTO v_after;

  -- ZERO-DRIFT: diamond_ledger is a side audit; diamond_transactions is what
  -- the supply snapshot reconciles against. This insert is NOT wrapped in a
  -- swallow-all handler - if the journal cannot be written the reward must
  -- fail, because an unjournalled credit is the bug we are here to close.
  IF v_after IS NOT NULL THEN
    INSERT INTO diamond_transactions (user_id, amount, type, balance_after, description, source)
    VALUES (p_user_id, v_diamonds, 'bonus', v_after,
            'daily challenge reward', 'complete_daily_challenge');
  END IF;

  BEGIN
    INSERT INTO diamond_ledger (user_id, delta, type, balance_after, created_at)
    VALUES (p_user_id, v_diamonds, 'daily_challenge_reward', COALESCE(v_after,0), NOW());
  EXCEPTION WHEN OTHERS THEN NULL;  -- side audit only; diamond_transactions above is authoritative
  END;

  RETURN jsonb_build_object('success', true, 'completion_id', v_completion_id,
                            'diamonds_earned', v_diamonds, 'perfect', v_perfect);
END;
$$;


ALTER FUNCTION public.complete_daily_challenge(p_user_id uuid, p_challenge_id uuid, p_score integer, p_accuracy numeric, p_time_taken integer) OWNER TO postgres;

--
-- Name: FUNCTION complete_daily_challenge(p_user_id uuid, p_challenge_id uuid, p_score integer, p_accuracy numeric, p_time_taken integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.complete_daily_challenge(p_user_id uuid, p_challenge_id uuid, p_score integer, p_accuracy numeric, p_time_taken integer) IS 'BUG 025: real impl. Idempotent insert into memory_challenge_completions + diamond reward (2-20 based on accuracy) + daily_challenges row update + diamond_ledger audit.';


--
-- Name: complete_hand_snapshot(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_hand_snapshot(p_table_id uuid, p_hand_number integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE hand_state_snapshots
  SET is_complete = TRUE, updated_at = NOW()
  WHERE table_id = p_table_id
    AND hand_number = p_hand_number
    AND is_complete = FALSE;
END;
$$;


