--
-- Name: complete_vip_subscription_checkout(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_vip_subscription_checkout(p_user_id uuid, p_request_id text, p_session_id text, p_session_url text, p_expires_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.vip_subscription_checkout_claims
     SET state = 'open',
         session_id = p_session_id,
         session_url = p_session_url,
         expires_at = GREATEST(
           expires_at,
           COALESCE(p_expires_at, now() + interval '30 minutes'),
           now() + interval '1 minute'
         ),
         updated_at = now()
   WHERE user_id = p_user_id
     AND request_id = p_request_id
     AND state <> 'admitting';
  RETURN FOUND;
END;
$$;


ALTER FUNCTION public.complete_vip_subscription_checkout(p_user_id uuid, p_request_id text, p_session_id text, p_session_url text, p_expires_at timestamp with time zone) OWNER TO postgres;

