--
-- Name: compute_group_vitality_score(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.compute_group_vitality_score(p_group_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group RECORD;
    v_score numeric := 0;
    v_games_30d int;
    v_games_90d int;
    v_attended_30d int;
    v_flake_rate numeric;
    v_active_members int;
    v_total_members int;
    v_posts_30d int;
BEGIN
    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    -- Games scheduled/completed (0-25)
    SELECT COUNT(*) INTO v_games_30d FROM commander_home_games
      WHERE group_id = p_group_id AND scheduled_date >= NOW() - INTERVAL '30 days';
    v_score := v_score + LEAST(25, v_games_30d * 6);

    -- Forward-looking games (0-15)
    v_score := v_score + LEAST(15, (SELECT COUNT(*) FROM commander_home_games 
                                     WHERE group_id = p_group_id 
                                       AND scheduled_date >= NOW() 
                                       AND status IN ('scheduled','confirmed')) * 5);

    -- Attendance vitality (0-20)
    SELECT COUNT(DISTINCT r.user_id) INTO v_attended_30d
      FROM commander_home_rsvps r
      JOIN commander_home_games g ON g.id = r.game_id
     WHERE g.group_id = p_group_id AND r.checked_in_at > NOW() - INTERVAL '30 days';
    v_score := v_score + LEAST(20, v_attended_30d * 2);

    -- Active member ratio (0-15)
    SELECT COUNT(*) INTO v_total_members FROM commander_home_members 
      WHERE group_id = p_group_id AND status='approved';
    SELECT COUNT(DISTINCT m.user_id) INTO v_active_members
      FROM commander_home_members m
      LEFT JOIN commander_home_rsvps r ON r.user_id = m.user_id
      LEFT JOIN commander_home_games g ON g.id = r.game_id AND g.group_id = p_group_id
     WHERE m.group_id = p_group_id AND m.status='approved'
       AND (r.responded_at > NOW() - INTERVAL '60 days' OR m.last_attended > NOW() - INTERVAL '60 days');
    IF v_total_members > 0 THEN
        v_score := v_score + LEAST(15, (v_active_members::numeric / v_total_members) * 15);
    END IF;

    -- Content life (0-10)
    SELECT COUNT(*) INTO v_posts_30d FROM commander_home_posts 
      WHERE group_id = p_group_id AND created_at > NOW() - INTERVAL '30 days';
    v_score := v_score + LEAST(10, v_posts_30d * 2);

    -- Flake rate penalty (0 to -15)
    SELECT CASE WHEN SUM(CASE WHEN r.response='yes' THEN 1 ELSE 0 END) = 0 THEN 0
                ELSE 100.0 * SUM(CASE WHEN r.flaked THEN 1 ELSE 0 END)::numeric / 
                     NULLIF(SUM(CASE WHEN r.response='yes' THEN 1 ELSE 0 END), 0) END
      INTO v_flake_rate
      FROM commander_home_rsvps r
      JOIN commander_home_games g ON g.id = r.game_id
     WHERE g.group_id = p_group_id AND r.responded_at > NOW() - INTERVAL '60 days';
    v_score := v_score - LEAST(15, (COALESCE(v_flake_rate, 0) / 100) * 15);

    -- Recency bonus/penalty (0-15)
    DECLARE v_recency_days int := EXTRACT(day FROM (NOW() - COALESCE(v_group.last_activity_at, v_group.created_at)))::int;
    BEGIN
        IF v_recency_days <= 7 THEN v_score := v_score + 15;
        ELSIF v_recency_days <= 21 THEN v_score := v_score + 10;
        ELSIF v_recency_days <= 45 THEN v_score := v_score + 3;
        ELSIF v_recency_days > 90 THEN v_score := v_score - 10;
        END IF;
    END;

    RETURN ROUND(GREATEST(0, LEAST(100, v_score)), 1);
END; $$;


ALTER FUNCTION public.compute_group_vitality_score(p_group_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION compute_group_vitality_score(p_group_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.compute_group_vitality_score(p_group_id uuid) IS 'Phase 26 redux/A: 0-100 ongoing vitality score. Distinct from quality_score (which drives discovery). No money.';


--
-- Name: compute_home_group_quality_score(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.compute_home_group_quality_score(p_group_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group        RECORD;
    v_score        numeric := 0;
    v_avg_rating   numeric;
    v_completion   numeric;
    v_recency_days int;
    v_review_count int;
BEGIN
    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    -- Logo: required for discovery
    IF v_group.profile_photo_url IS NOT NULL THEN v_score := v_score + 15; END IF;
    -- Description present
    IF v_group.description IS NOT NULL AND length(v_group.description) > 50 THEN v_score := v_score + 10; END IF;
    -- Tagline present
    IF v_group.tagline IS NOT NULL THEN v_score := v_score + 5; END IF;
    -- Location set
    IF v_group.city IS NOT NULL AND v_group.state IS NOT NULL THEN v_score := v_score + 8; END IF;
    IF v_group.location_geog IS NOT NULL THEN v_score := v_score + 4; END IF;
    -- Member traction (capped)
    v_score := v_score + LEAST(15, COALESCE(v_group.member_count, 0) * 1.5);
    -- Games hosted (capped)
    v_score := v_score + LEAST(20, COALESCE(v_group.games_hosted, 0) * 2.0);
    -- Recency bonus
    v_recency_days := EXTRACT(day FROM (NOW() - COALESCE(v_group.last_activity_at, v_group.created_at)))::int;
    IF v_recency_days <= 7 THEN v_score := v_score + 10;
    ELSIF v_recency_days <= 21 THEN v_score := v_score + 6;
    ELSIF v_recency_days <= 45 THEN v_score := v_score + 2;
    END IF;
    -- Reviews
    SELECT COALESCE(AVG(r.rating), 0), COUNT(*) 
      INTO v_avg_rating, v_review_count
      FROM commander_home_game_reviews r
      JOIN commander_home_games g ON g.id = r.game_id
     WHERE g.group_id = p_group_id;
    IF v_review_count >= 3 AND v_avg_rating >= 4.0 THEN v_score := v_score + 8;
    ELSIF v_review_count >= 1 AND v_avg_rating >= 3.5 THEN v_score := v_score + 4;
    END IF;
    -- Tags present
    IF v_group.tags IS NOT NULL AND array_length(v_group.tags, 1) > 0 THEN v_score := v_score + 3; END IF;
    -- Public visibility
    IF NOT v_group.is_private THEN v_score := v_score + 2; END IF;

    RETURN ROUND(LEAST(100, v_score), 1);
END;
$$;


ALTER FUNCTION public.compute_home_group_quality_score(p_group_id uuid) OWNER TO postgres;

