--
-- Name: create_trivia_pvp_session_v2(uuid, uuid, uuid, uuid[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_trivia_pvp_session_v2(p_session_id uuid, p_match_id uuid, p_user_id uuid, p_question_ids uuid[], p_permutations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_m public.trivia_pvp_matches%ROWTYPE;
    v_existing uuid;
    v_side smallint;
    v_stake integer;
    v_charge jsonb;
BEGIN
    IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'service_role required';
    END IF;
    IF p_session_id IS NULL OR p_match_id IS NULL OR p_user_id IS NULL
       OR array_ndims(p_question_ids) IS DISTINCT FROM 1
       OR cardinality(p_question_ids) <> 20
       OR array_position(p_question_ids, NULL::uuid) IS NOT NULL
       OR (SELECT count(DISTINCT question_id) FROM unnest(p_question_ids) AS question_id) <> 20
       OR jsonb_typeof(COALESCE(p_permutations, '{}'::jsonb)) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_session');
    END IF;

    SELECT * INTO v_m
      FROM public.trivia_pvp_matches
     WHERE id = p_match_id
     FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'match_not_found'); END IF;
    IF EXISTS (
        SELECT 1 FROM public.competitive_quarantine
         WHERE entity_type = 'trivia_pvp_match' AND entity_id = p_match_id
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'match_quarantined');
    END IF;
    IF v_m.status IS DISTINCT FROM 'active' THEN
        RETURN jsonb_build_object('success', false, 'error', 'match_not_active');
    END IF;
    IF v_m.player1_id IS NULL OR v_m.player2_id IS NULL
       OR v_m.player1_id = v_m.player2_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_match_players');
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.profiles AS profile
         WHERE profile.id = v_m.player1_id
    ) OR NOT EXISTS (
        SELECT 1 FROM public.profiles AS profile
         WHERE profile.id = v_m.player2_id
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_match_players');
    END IF;
    IF v_m.stake_amount IS NULL OR v_m.stake_amount NOT IN (10, 25, 50, 100) THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_match_stake');
    END IF;
    IF v_m.created_at IS NULL OR v_m.created_at > now() + interval '1 minute'
       OR v_m.created_at < now() - interval '30 minutes' THEN
        RETURN jsonb_build_object('success', false, 'error', 'match_expired');
    END IF;
    IF jsonb_typeof(v_m.questions) IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_m.questions) <> 20
       OR v_m.questions IS DISTINCT FROM to_jsonb(p_question_ids) THEN
        RETURN jsonb_build_object('success', false, 'error', 'roster_mismatch');
    END IF;

    IF p_user_id = v_m.player1_id THEN v_side := 1;
    ELSIF p_user_id = v_m.player2_id THEN v_side := 2;
    ELSE RETURN jsonb_build_object('success', false, 'error', 'not_your_match'); END IF;
    SELECT session_id INTO v_existing
      FROM public.trivia_pvp_session_links
     WHERE match_id = p_match_id AND side = v_side;
    IF FOUND THEN
        IF EXISTS (
            SELECT 1 FROM public.trivia_pvp_session_links
             WHERE match_id = p_match_id AND side = v_side AND user_id = p_user_id
        ) THEN
            RETURN jsonb_build_object('success', true, 'duplicate', true, 'session_id', v_existing);
        END IF;
        RETURN jsonb_build_object('success', false, 'error', 'session_link_conflict');
    END IF;
    IF EXISTS (SELECT 1 FROM public.trivia_pvp_session_links WHERE session_id = p_session_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'session_id_reused');
    END IF;
    IF EXISTS (SELECT 1 FROM public.trivia_sessions WHERE id = p_session_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'session_id_conflict');
    END IF;

    v_stake := v_m.stake_amount;
    SELECT public.add_diamonds_to_balance(
        p_user_id, -v_stake, 'pvp_stake',
        'PvP stake - match ' || p_match_id::text,
        'pvp_stake_' || p_match_id::text || '_' || p_user_id::text
    ) INTO v_charge;
    IF v_charge IS NULL
       OR (COALESCE((v_charge ->> 'success')::boolean, false) IS NOT TRUE
           AND COALESCE((v_charge ->> 'duplicate')::boolean, false) IS NOT TRUE) THEN
        RETURN jsonb_build_object('success', false, 'error',
            COALESCE(v_charge ->> 'error', 'insufficient_diamonds'));
    END IF;

    INSERT INTO public.trivia_sessions (
        id, user_id, mode, question_ids, permutations, status,
        entry_cost, entry_state, created_at, expires_at
    ) VALUES (
        p_session_id, p_user_id, 'pvp', p_question_ids,
        COALESCE(p_permutations, '{}'::jsonb), 'open',
        v_stake, 'charged', clock_timestamp(),
        v_m.created_at + interval '30 minutes'
    );
    INSERT INTO public.trivia_pvp_session_links (
        match_id, side, user_id, session_id, created_at
    ) VALUES (
        p_match_id, v_side, p_user_id, p_session_id, clock_timestamp()
    );

    RETURN jsonb_build_object(
        'success', true, 'duplicate', false, 'session_id', p_session_id,
        'new_balance', v_charge -> 'new_balance'
    );
END;
$$;


ALTER FUNCTION public.create_trivia_pvp_session_v2(p_session_id uuid, p_match_id uuid, p_user_id uuid, p_question_ids uuid[], p_permutations jsonb) OWNER TO postgres;

--
-- Name: create_trivia_session_v2(uuid, uuid, text, uuid[], jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_trivia_session_v2(p_session_id uuid, p_user_id uuid, p_mode text, p_question_ids uuid[], p_permutations jsonb, p_parent_session_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_existing public.trivia_sessions%ROWTYPE;
    v_parent public.trivia_sessions%ROWTYPE;
    v_cost int := CASE p_mode
        WHEN 'arcade' THEN 10 WHEN 'mtt' THEN 10 WHEN 'cash' THEN 10
        WHEN 'icm' THEN 10 WHEN 'gto' THEN 10 WHEN 'mixed' THEN 10
        WHEN 'endless' THEN 10 WHEN 'survival' THEN 10
        WHEN 'time-attack' THEN 10 ELSE 0 END;
    v_state text := 'free';
    v_charge jsonb;
    v_is_vip boolean := false;
    v_item_qty int;
    v_level int := NULL;
    v_run_id uuid := NULL;
    v_required int;
    v_expires timestamptz := CASE p_mode
        WHEN 'time-attack' THEN now() + interval '30 seconds'
        WHEN 'arcade' THEN now() + interval '180 seconds'
        ELSE now() + interval '6 hours' END;
BEGIN
    IF p_session_id IS NULL OR p_user_id IS NULL OR p_mode IS NULL
       OR COALESCE(array_length(p_question_ids, 1), 0) = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_session');
    END IF;

    SELECT * INTO v_existing FROM public.trivia_sessions WHERE id = p_session_id;
    IF FOUND THEN
        IF v_existing.user_id = p_user_id AND v_existing.mode = p_mode THEN
            RETURN jsonb_build_object('success', true, 'duplicate', true,
                'entry_cost', v_existing.entry_cost, 'entry_state', v_existing.entry_state,
                'expires_at', v_existing.expires_at);
        END IF;
        RETURN jsonb_build_object('success', false, 'error', 'session_id_conflict');
    END IF;

    IF p_mode = 'survival' THEN
        IF p_parent_session_id IS NULL THEN
            v_level := 1;
            v_run_id := p_session_id;
        ELSE
            SELECT * INTO v_parent FROM public.trivia_sessions
             WHERE id = p_parent_session_id FOR UPDATE;
            IF NOT FOUND OR v_parent.user_id IS DISTINCT FROM p_user_id
               OR v_parent.mode <> 'survival' OR v_parent.status <> 'submitted'
               OR v_parent.created_at < now() - interval '6 hours' THEN
                RETURN jsonb_build_object('success', false, 'error', 'invalid_survival_continuation');
            END IF;
            v_level := COALESCE(v_parent.survival_level, 1) + 1;
            v_run_id := COALESCE(v_parent.survival_run_id, v_parent.id);
            IF v_level > 10 THEN
                RETURN jsonb_build_object('success', false, 'error', 'survival_complete');
            END IF;
            v_required := (ARRAY[17,18,18,19,19,19,20,20,20,20])[COALESCE(v_parent.survival_level, 1)];
            IF COALESCE(v_parent.correct_count, 0) < v_required THEN
                RETURN jsonb_build_object('success', false, 'error', 'survival_level_not_passed');
            END IF;
            IF EXISTS (SELECT 1 FROM public.trivia_sessions WHERE parent_session_id = p_parent_session_id) THEN
                RETURN jsonb_build_object('success', false, 'error', 'survival_continuation_used');
            END IF;
            v_cost := 0;
            v_state := 'continuation';
        END IF;
    END IF;

    IF v_cost > 0 AND v_state <> 'continuation' THEN
        SELECT COALESCE(is_vip, false)
               AND (vip_tier = 'lifetime' OR vip_expires_at > now())
          INTO v_is_vip FROM public.profiles WHERE id = p_user_id;
        IF v_is_vip THEN
            v_cost := 0;
            v_state := 'vip';
        ELSIF p_mode = 'arcade' THEN
            UPDATE public.trivia_user_items
               SET quantity = quantity - 1, updated_at = now()
             WHERE user_id = p_user_id AND item_type = 'arcade_ticket' AND quantity > 0
            RETURNING quantity INTO v_item_qty;
            IF FOUND THEN
                v_cost := 0;
                v_state := 'ticket';
                INSERT INTO public.trivia_item_transactions
                    (user_id,item_type,amount,balance_after,transaction_type,reference_id,metadata)
                VALUES (p_user_id,'arcade_ticket',-1,v_item_qty,'arcade_entry',
                        'trivia_ticket_'||p_session_id::text,
                        jsonb_build_object('session_id',p_session_id));
            END IF;
        END IF;

        IF v_cost > 0 THEN
            SELECT public.add_diamonds_to_balance(
                p_user_id, -v_cost, 'trivia_entry',
                'Trivia entry ('||p_mode||')', 'trivia_entry_'||p_session_id::text
            ) INTO v_charge;
            IF COALESCE((v_charge->>'success')::boolean, false) IS NOT TRUE THEN
                RETURN jsonb_build_object('success', false, 'error',
                    COALESCE(v_charge->>'error','insufficient_diamonds'));
            END IF;
            v_state := 'charged';
        END IF;
    END IF;

    INSERT INTO public.trivia_sessions (
        id,user_id,mode,question_ids,permutations,status,parent_session_id,
        entry_cost,entry_state,expires_at,survival_run_id,survival_level
    ) VALUES (
        p_session_id,p_user_id,p_mode,p_question_ids,COALESCE(p_permutations,'{}'),
        'open',p_parent_session_id,v_cost,v_state,v_expires,v_run_id,v_level
    );

    RETURN jsonb_build_object('success',true,'duplicate',false,'entry_cost',v_cost,
        'entry_state',v_state,'new_balance',v_charge->'new_balance','expires_at',v_expires,
        'survival_level',v_level);
END;
$$;


ALTER FUNCTION public.create_trivia_session_v2(p_session_id uuid, p_user_id uuid, p_mode text, p_question_ids uuid[], p_permutations jsonb, p_parent_session_id uuid) OWNER TO postgres;

--
-- Name: create_user_wallets(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_user_wallets() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  /* Orphaned long before this migration - no trigger has pointed here for
     months - but it seeded every new account with a 100-chip phantom promo
     balance and 1,000 phantom player chips in wallets, a table outside the chip
     supply. Left inert rather than dropped so that re-attaching it is a no-op
     instead of a fresh phantom. A new account's chips come from its club, and a
     club's chips come from the Mint. */
  RETURN NEW;
END;
$$;


