--
-- Name: credit_club_rake_to_treasury(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.credit_club_rake_to_treasury(p_club_id uuid, p_amount numeric) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_st  text;
  v_msg text;
  v_from_type   text := 'table_stack';
  v_from_entity uuid := NULL;
BEGIN
  IF p_club_id IS NULL OR p_amount IS NULL OR p_amount = 0 THEN
    RETURN;
  END IF;

  /* CHIP STANDARD (2026-09-04): a caller that declared where the rake comes
     from is believed. fn_settle_tournament_rake declares prize_liability +
     the tournament; cash rake declares nothing and keeps the felt. Before
     this, every standalone-club tournament settlement journalled its rake
     as leaving table_stack - 1,178.96 an hour the felt never paid. */
  IF COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), '') <> '' THEN
    v_from_type := current_setting('app.ledger_counterparty', true);
    BEGIN
      v_from_entity := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
    EXCEPTION WHEN OTHERS THEN
      v_from_entity := NULL;
    END;
  END IF;

  PERFORM set_config('app.ledger_autoskip_clubs', '1', true);
  UPDATE public.clubs
     SET chip_treasury = COALESCE(chip_treasury, 0) + p_amount,
         total_rake    = COALESCE(total_rake, 0) + p_amount,
         updated_at    = now()
   WHERE id = p_club_id;
  PERFORM set_config('app.ledger_autoskip_clubs', '0', true);

  /* Rake comes off its declared source and lands in the treasury. amount > 0
     is a CHECK on chip_ledger, so a negative p_amount (a correction) is
     journaled with its sides swapped rather than dropped. Journal failure rolls back the credit. */
  BEGIN
    INSERT INTO public.chip_ledger
      (performed_by, from_type, from_entity_id, to_type, to_entity_id,
       amount, category, club_id, description)
    VALUES (
      COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
      CASE WHEN p_amount > 0 THEN v_from_type    ELSE 'club_treasury' END,
      CASE WHEN p_amount > 0 THEN v_from_entity  ELSE p_club_id       END,
      CASE WHEN p_amount > 0 THEN 'club_treasury' ELSE v_from_type    END,
      CASE WHEN p_amount > 0 THEN p_club_id       ELSE v_from_entity  END,
      abs(p_amount), 'rake', p_club_id,
      'Rake credited to club treasury (credit_club_rake_to_treasury)');
  EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;

END;
$$;


ALTER FUNCTION public.credit_club_rake_to_treasury(p_club_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: FUNCTION credit_club_rake_to_treasury(p_club_id uuid, p_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.credit_club_rake_to_treasury(p_club_id uuid, p_amount numeric) IS 'Credits a standalone club''s OPERATIONAL BANK (clubs.chip_treasury) and total_rake with collected rake. Does NOT touch clubs.chip_pool, which is the separate mint-and-distribute inventory. Replaces the misleadingly named increment_club_chip_pool.';


--
-- Name: credit_club_wallet_rake(uuid, numeric, numeric, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.credit_club_wallet_rake(p_club_id uuid, p_rake numeric, p_bbj numeric DEFAULT 0, p_hand_id uuid DEFAULT NULL::uuid, p_hand_number integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_balance_after numeric;
  v_net_credit    numeric;
BEGIN
  IF p_club_id IS NULL OR p_rake IS NULL OR p_rake <= 0 THEN
    RETURN;
  END IF;

  -- net credit (what stays with the club after BBJ contribution)
  v_net_credit := p_rake - COALESCE(p_bbj, 0);

  UPDATE public.club_wallets
     SET period_rake_collected     = period_rake_collected     + p_rake,
         period_bbj_contribution   = period_bbj_contribution   + COALESCE(p_bbj, 0),
         lifetime_rake_collected   = lifetime_rake_collected   + p_rake,
         lifetime_bbj_contribution = lifetime_bbj_contribution + COALESCE(p_bbj, 0),
         chip_balance              = chip_balance + v_net_credit,
         updated_at                = NOW()
   WHERE club_id = p_club_id
   RETURNING chip_balance INTO v_balance_after;

  -- If club_wallets row didn't exist (shouldn't happen - backfilled in
  -- migration 20260428000004 - but be defensive), insert one.
  IF v_balance_after IS NULL THEN
    INSERT INTO public.club_wallets (
      club_id, chip_balance,
      period_rake_collected, period_bbj_contribution,
      lifetime_rake_collected, lifetime_bbj_contribution
    ) VALUES (
      p_club_id, v_net_credit,
      p_rake, COALESCE(p_bbj, 0),
      p_rake, COALESCE(p_bbj, 0)
    )
    ON CONFLICT (club_id) DO UPDATE SET
      period_rake_collected     = club_wallets.period_rake_collected     + EXCLUDED.period_rake_collected,
      period_bbj_contribution   = club_wallets.period_bbj_contribution   + EXCLUDED.period_bbj_contribution,
      lifetime_rake_collected   = club_wallets.lifetime_rake_collected   + EXCLUDED.lifetime_rake_collected,
      lifetime_bbj_contribution = club_wallets.lifetime_bbj_contribution + EXCLUDED.lifetime_bbj_contribution,
      chip_balance              = club_wallets.chip_balance              + EXCLUDED.chip_balance,
      updated_at                = NOW()
    RETURNING chip_balance INTO v_balance_after;
  END IF;

  -- Append-only audit row in club_wallet_transactions.
  -- amount = net (post-BBJ) chip increment to the club balance.
  INSERT INTO public.club_wallet_transactions (
    club_id, type, amount, balance_after, related_id, reason
  ) VALUES (
    p_club_id, 'rake_in', v_net_credit, v_balance_after, p_hand_id,
    'Rake collected (hand ' ||
      COALESCE('#' || p_hand_number::text, 'unknown') ||
      ', BBJ contribution ' || COALESCE(p_bbj, 0)::text || ')'
  );
END;
$$;


ALTER FUNCTION public.credit_club_wallet_rake(p_club_id uuid, p_rake numeric, p_bbj numeric, p_hand_id uuid, p_hand_number integer) OWNER TO postgres;

--
-- Name: credit_player_rakeback(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.credit_player_rakeback(p_user_id uuid, p_amount numeric, p_description text DEFAULT ''::text, p_idempotency_key text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_club_id uuid;
  v_inserted integer;
  v_res jsonb;
BEGIN
  IF p_amount <= 0 THEN RETURN false; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO wallet_credit_idempotency (key, user_id, amount)
    VALUES (p_idempotency_key, p_user_id, p_amount)
    ON CONFLICT (key) DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted = 0 THEN RETURN false; END IF;
  END IF;

  v_res := public.fn_pay_player_chips(
    p_user_id, p_amount, 'rakeback',
    COALESCE(NULLIF(p_description, ''), 'Rakeback credit'), NULL, NULL);

  -- Audit row. The club is the RESOLVED payout club; the old code fell back to
  -- a hardcoded SHARK CLUB id, misattributing other clubs' rakeback.
  v_club_id := NULLIF(v_res->>'club_id','')::uuid;
  IF v_club_id IS NULL THEN
    SELECT club_id INTO v_club_id FROM club_members WHERE user_id = p_user_id
     ORDER BY joined_at ASC NULLS LAST LIMIT 1;
  END IF;

  IF v_club_id IS NOT NULL THEN
    INSERT INTO chip_transactions (club_id, to_user_id, amount, transaction_type, notes)
    VALUES (v_club_id, p_user_id, p_amount, 'rakeback',
            COALESCE(NULLIF(p_description, ''), 'Rakeback credit'));
  END IF;

  RETURN true;
END; $$;


ALTER FUNCTION public.credit_player_rakeback(p_user_id uuid, p_amount numeric, p_description text, p_idempotency_key text) OWNER TO postgres;

