--
-- Name: deduct_agent_balance(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.deduct_agent_balance(p_agent_id uuid, p_amount numeric, p_reason text DEFAULT 'Transfer'::text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- STUB: original body referenced a nonexistent "balance" column on the
  -- target table. Use the (agent_id, amount) overload for real deductions.
  RETURN false;
END; $$;


ALTER FUNCTION public.deduct_agent_balance(p_agent_id uuid, p_amount numeric, p_reason text) OWNER TO postgres;

--
-- Name: deduct_chip_balance(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.deduct_chip_balance(p_club_id uuid, p_user_id uuid, p_amount numeric) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    UPDATE club_members 
    SET chip_balance = chip_balance - p_amount
    WHERE club_id = p_club_id 
      AND user_id = p_user_id 
      AND chip_balance >= p_amount;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Insufficient chip balance or member not found';
    END IF;
END;
$$;


ALTER FUNCTION public.deduct_chip_balance(p_club_id uuid, p_user_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: FUNCTION deduct_chip_balance(p_club_id uuid, p_user_id uuid, p_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
