COMMENT ON FUNCTION public.deduct_chip_balance(p_club_id uuid, p_user_id uuid, p_amount numeric) IS 'DEPRECATED 2026-08-19 - DO NOT USE. Moves chips WITHOUT writing any transaction record, so the movement never reaches the transaction reports. Verified dead: 0 app callers, 0 triggers, 0 SQL callers, service_role-only. Use the audited equivalents instead: fn_credit_chips / fn_debit_chips / fn_transfer_chips / distribute_chips / fn_union_send_chips_to_club / transfer_chips_agent_to_player - all log, lock FOR UPDATE and guard balances.';


--
-- Name: deduct_diamonds(uuid, integer, text, text, text, jsonb, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.deduct_diamonds(p_user_id uuid, p_amount integer, p_description text DEFAULT ''::text, p_transaction_type text DEFAULT 'game_cost'::text, p_source text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_reference_id text DEFAULT NULL::text, p_cooldown_seconds integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_current integer;
    v_new_balance integer;
    v_effective_type text;
    v_issuance_class text;
    v_counterparty text;
    v_existing_amount numeric;
    v_existing_type text;
    v_existing_counterparty text;
    v_existing_issuance_class text;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Amount must be a positive integer');
    END IF;
    IF COALESCE(auth.role(), '') <> 'service_role'
       AND (auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_user_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot deduct diamonds for another user');
    END IF;

    v_effective_type := COALESCE(p_source, p_transaction_type);

    -- Derive the destination before the replay check so the same reference
    -- cannot be moved to another recipient or revenue account.
    IF COALESCE(p_source, '') IN ('wallet_transfer', 'wallet_diamond_transfer', 'stream_gift')
       OR COALESCE(p_transaction_type, '') IN ('diamond_gift_sent', 'live_gift_sent') THEN
        v_issuance_class := 'transferred';
        v_counterparty := 'player:' || COALESCE(p_metadata->>'recipient_id', 'unknown');
    ELSE
        v_issuance_class := 'spend';
        v_counterparty := 'revenue:' || COALESCE(p_source, p_transaction_type, 'unknown');
    END IF;

    -- The profile lock serializes the first attempt and every concurrent
    -- replay. A second request cannot pass an early lookup, wait for the first
    -- debit to commit, and then fall through to a duplicate insert error.
    SELECT COALESCE(diamonds, 0)
      INTO v_current
      FROM public.profiles
     WHERE id = p_user_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'User not found');
    END IF;

    IF p_reference_id IS NOT NULL THEN
        SELECT dt.amount,
               COALESCE(dt.transaction_type, dt.type),
               dt.counterparty,
               dt.issuance_class
          INTO v_existing_amount,
               v_existing_type,
               v_existing_counterparty,
               v_existing_issuance_class
          FROM public.diamond_transactions AS dt
         WHERE dt.reference_id = p_reference_id
           AND dt.user_id = p_user_id
         LIMIT 1;

        IF FOUND THEN
            IF v_existing_amount IS DISTINCT FROM -p_amount
               OR v_existing_type IS DISTINCT FROM v_effective_type
               OR v_existing_counterparty IS DISTINCT FROM v_counterparty
               OR v_existing_issuance_class IS DISTINCT FROM v_issuance_class THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'error', 'idempotency_conflict',
                    'balance', v_current,
                    'reference_id', p_reference_id
                );
            END IF;

            RETURN jsonb_build_object(
                'success', true,
                'balance', v_current,
                'charged', (-v_existing_amount)::integer,
                'transaction_type', v_existing_type,
                'reference_id', p_reference_id,
                'counterparty', v_existing_counterparty,
                'issuance_class', v_existing_issuance_class,
                'idempotent', true
            );
        END IF;
    END IF;

    IF v_current < p_amount THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Insufficient diamonds',
            'balance', v_current
        );
    END IF;

    IF p_cooldown_seconds > 0 THEN
        IF EXISTS (
            SELECT 1
              FROM public.diamond_transactions
             WHERE user_id = p_user_id
               AND transaction_type = v_effective_type
               AND created_at >= now() - make_interval(secs => p_cooldown_seconds)
        ) THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Please wait before sending again',
                'cooldown_active', true
            );
        END IF;
    END IF;

    UPDATE public.profiles
       SET diamonds = diamonds - p_amount,
           diamond_balance = diamonds - p_amount,
           updated_at = now()
     WHERE id = p_user_id
     RETURNING diamonds INTO v_new_balance;

    -- DIAMOND-RULINGS 1: purchased lots are consumed FIFO before promotional balance at every
    -- sink, so a refund or chargeback knows what is left of what was paid for.
    PERFORM public.fn_ca_consume_purchase_lots(p_user_id, p_amount);

    INSERT INTO public.diamond_transactions
        (user_id, amount, transaction_type, type, description, balance_after, metadata,
         reference_id, created_at, counterparty, issuance_class)
    VALUES
        (p_user_id, -p_amount, v_effective_type, v_effective_type, p_description,
         v_new_balance, p_metadata, p_reference_id, now(), v_counterparty, v_issuance_class);

    RETURN jsonb_build_object(
        'success', true,
        'balance', v_new_balance,
        'charged', p_amount,
        'transaction_type', v_effective_type,
        'reference_id', p_reference_id,
        'counterparty', v_counterparty,
        'issuance_class', v_issuance_class,
        'idempotent', false
    );
END;
$$;


ALTER FUNCTION public.deduct_diamonds(p_user_id uuid, p_amount integer, p_description text, p_transaction_type text, p_source text, p_metadata jsonb, p_reference_id text, p_cooldown_seconds integer) OWNER TO postgres;

--
-- Name: deduct_player_wallet(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.deduct_player_wallet(p_user_id uuid, p_amount numeric) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_balance DECIMAL;
BEGIN
    SELECT balance INTO v_balance FROM wallets WHERE user_id = p_user_id AND wallet_type = 'PLAYER';
    IF v_balance IS NULL OR v_balance < p_amount THEN RAISE EXCEPTION 'Insufficient balance: have %, need %', COALESCE(v_balance, 0), p_amount; END IF;
    UPDATE wallets SET balance = balance - p_amount, updated_at = NOW() WHERE user_id = p_user_id AND wallet_type = 'PLAYER';
END;
$$;


ALTER FUNCTION public.deduct_player_wallet(p_user_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: delete_home_group_post(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_home_group_post(p_post_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_post   RECORD;
    v_group  RECORD;
    v_is_host boolean;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    SELECT * INTO v_post FROM commander_home_posts WHERE id = p_post_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', true, 'already_gone', true); END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_post.group_id;

    v_is_host := (v_group.owner_id = p_caller_user_id)
              OR EXISTS (SELECT 1 FROM commander_home_members 
                          WHERE group_id = v_post.group_id AND user_id = p_caller_user_id
                            AND role = 'admin' AND status = 'approved');

    IF v_post.author_id <> p_caller_user_id AND NOT v_is_host THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    DELETE FROM commander_home_posts WHERE id = p_post_id;

    IF v_is_host AND v_post.author_id <> p_caller_user_id THEN
        INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
        VALUES (v_post.group_id, p_caller_user_id, 'post', p_post_id, 'moderated_delete',
                jsonb_build_object('original_author', v_post.author_id));
    END IF;

    RETURN jsonb_build_object('success', true, 'post_id', p_post_id);
END;
$$;


ALTER FUNCTION public.delete_home_group_post(p_post_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: delete_venue_post(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_venue_post(p_post_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_post RECORD; v_is_manager boolean;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    SELECT * INTO v_post FROM commander_venue_posts WHERE id = p_post_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'POST_NOT_FOUND'; END IF;
    IF v_post.author_id <> p_caller_user_id THEN
        v_is_manager := public.is_venue_manager(p_caller_user_id, v_post.venue_id);
        IF NOT v_is_manager THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;
    END IF;
    -- Soft-delete via is_published = false (preserves audit trail)
    UPDATE commander_venue_posts SET is_published = false, updated_at = NOW() WHERE id = p_post_id;
    RETURN jsonb_build_object('success', true);
END; $$;


ALTER FUNCTION public.delete_venue_post(p_post_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: detect_collusion_pairs(uuid, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_collusion_pairs(p_club_id uuid, p_threshold numeric DEFAULT 0.75, p_min_hands integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_analyzed   bigint;
  v_players    integer;
  v_dump       jsonb;
  v_dump_total integer;
  v_screen       jsonb;
  v_screen_total integer;
  v_cleared    integer;
  v_cap        constant integer := 50;
BEGIN
  IF NOT fn_ca_can_review_integrity(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  -- club_hand_daily is the maintained per-hand rollup; counting hand_history
  -- for the same answer cost 448ms against its 75ms.
  SELECT coalesce(sum(d.hands), 0)
    INTO v_analyzed
    FROM club_hand_daily d
   WHERE d.club_id = p_club_id
     AND d.stat_date > current_date - 30;

  SELECT count(DISTINCT ts.user_id)::integer
    INTO v_players
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
   WHERE t.club_id = p_club_id AND ts.user_id IS NOT NULL;

  WITH club_players AS MATERIALIZED (
    SELECT DISTINCT ts.user_id
      FROM table_seats ts
      JOIN tables t ON t.id = ts.table_id
     WHERE t.club_id = p_club_id AND ts.user_id IS NOT NULL
  ),
  in_scope AS (
    SELECT ct.player_a, ct.player_b, ct.pattern_type, ct.suspicion_score,
           ct.evidence, coalesce(ct.status, 'open') AS status
      FROM collusion_tracking ct
     WHERE ct.scan_date > current_date - 30
       AND EXISTS (SELECT 1 FROM club_players p WHERE p.user_id = ct.player_a)
       AND EXISTS (SELECT 1 FROM club_players p WHERE p.user_id = ct.player_b)
  ),
  paired AS (
    SELECT s.player_a, s.player_b, s.pattern_type,
           max(s.suspicion_score) AS score,
           coalesce(max((s.evidence->>'hands_together')::numeric),
                    max((s.evidence->>'hands')::numeric), 0)::integer AS hands_together,
           (array_agg(s.evidence ORDER BY s.suspicion_score DESC))[1] AS evidence
      FROM in_scope s
     WHERE s.status = 'open'
     GROUP BY s.player_a, s.player_b, s.pattern_type
    HAVING max(s.suspicion_score) >= p_threshold * 100
       AND coalesce(max((s.evidence->>'hands_together')::numeric),
                    max((s.evidence->>'hands')::numeric), p_min_hands) >= p_min_hands
  ),
  ranked AS (
    SELECT p.pattern_type,
           row_number() OVER (PARTITION BY (p.pattern_type = 'CHIP_DUMP') ORDER BY p.score DESC) AS rn,
           jsonb_build_object(
             'dumper_id', p.player_a,
             'receiver_id', p.player_b,
             'pattern_type', p.pattern_type,
             'hands_together', p.hands_together,
             'score', p.score,
             'chip_flow_ratio', round(p.score / 100.0, 2),
             'severity', CASE WHEN p.score >= 90 THEN 'high'
                              WHEN p.score >= 75 THEN 'medium'
                              ELSE 'low' END,
             'evidence', p.evidence) AS payload
      FROM paired p
  )
  SELECT
    count(*) FILTER (WHERE pattern_type = 'CHIP_DUMP')::integer,
    count(*) FILTER (WHERE pattern_type <> 'CHIP_DUMP')::integer,
    coalesce(jsonb_agg(payload) FILTER (WHERE pattern_type = 'CHIP_DUMP' AND rn <= v_cap), '[]'::jsonb),
    coalesce(jsonb_agg(payload) FILTER (WHERE pattern_type <> 'CHIP_DUMP' AND rn <= v_cap), '[]'::jsonb),
    (SELECT count(DISTINCT (player_a, player_b))::integer FROM in_scope WHERE status <> 'open')
    INTO v_dump_total, v_screen_total, v_dump, v_screen, v_cleared
  FROM ranked;

  RETURN jsonb_build_object(
    'analyzed_hands', coalesce(v_analyzed, 0),
    'club_players', coalesce(v_players, 0),
    'window_days', 30,
    'threshold', p_threshold,
    'cap', v_cap,
    'closed_pairs', coalesce(v_cleared, 0),
    'chip_dump', jsonb_build_object('total', coalesce(v_dump_total, 0), 'pairs', coalesce(v_dump, '[]'::jsonb)),
    'screening', jsonb_build_object('total', coalesce(v_screen_total, 0), 'pairs', coalesce(v_screen, '[]'::jsonb)),
    'generated_at', now());
END;
$$;


ALTER FUNCTION public.detect_collusion_pairs(p_club_id uuid, p_threshold numeric, p_min_hands integer) OWNER TO postgres;

--
-- Name: detect_home_abuse_patterns(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_home_abuse_patterns(p_lookback_days integer DEFAULT 30, p_min_reports integer DEFAULT 3) RETURNS TABLE(target_type text, target_id uuid, report_count bigint, unique_reporters bigint, reason_breakdown jsonb, first_reported timestamp with time zone, last_reported timestamp with time zone, suggested_action text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
BEGIN
    -- Require platform-admin caller. service_role bypass for server-side cron.
    IF COALESCE(auth.role(), '') <> 'service_role' THEN
      IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
      END IF;
      IF NOT EXISTS (
        SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin'
      ) THEN
        RAISE EXCEPTION 'ADMIN_ONLY' USING ERRCODE = '42501',
              HINT = 'detect_home_abuse_patterns requires platform admin';
      END IF;
    END IF;

    RETURN QUERY
    WITH agg AS (
        SELECT r.reported_type AS t_type, r.reported_id AS t_id,
               COUNT(*) AS rc, COUNT(DISTINCT r.reporter_id) AS ur,
               MIN(r.created_at) AS fr, MAX(r.created_at) AS lr
          FROM commander_home_content_reports r
         WHERE r.status = 'pending'
           AND r.created_at > NOW() - (p_lookback_days || ' days')::interval
         GROUP BY r.reported_type, r.reported_id
        HAVING COUNT(*) >= p_min_reports
    ),
    breakdown AS (
        SELECT r.reported_type AS t_type, r.reported_id AS t_id,
               jsonb_object_agg(r.reason_category, c) AS breakdown_json
          FROM (
            SELECT reported_type, reported_id, reason_category, COUNT(*) AS c
              FROM commander_home_content_reports
             WHERE status = 'pending'
               AND created_at > NOW() - (p_lookback_days || ' days')::interval
             GROUP BY reported_type, reported_id, reason_category
          ) r
         GROUP BY r.reported_type, r.reported_id
    )
    SELECT a.t_type, a.t_id, a.rc, a.ur,
           COALESCE(b.breakdown_json, '{}'::jsonb),
           a.fr, a.lr,
           CASE
               WHEN a.ur >= 5 AND a.rc >= 5 THEN 'auto_action_recommended'
               WHEN a.ur >= 3 THEN 'review_urgently'
               ELSE 'review_normally'
           END
      FROM agg a
      LEFT JOIN breakdown b ON b.t_type = a.t_type AND b.t_id = a.t_id
     ORDER BY a.ur DESC, a.rc DESC;
END;
$$;


ALTER FUNCTION public.detect_home_abuse_patterns(p_lookback_days integer, p_min_reports integer) OWNER TO postgres;

--
-- Name: FUNCTION detect_home_abuse_patterns(p_lookback_days integer, p_min_reports integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.detect_home_abuse_patterns(p_lookback_days integer, p_min_reports integer) IS 'Phase 40: requires platform admin (profiles.role=''admin''). Previously callable by any authenticated user — leaked report aggregates.';


--
-- Name: detect_multi_account_ips(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_multi_account_ips(p_since timestamp with time zone) RETURNS TABLE(ip_address text, user_ids uuid[], hit_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    ip_address,
    array_agg(DISTINCT user_id) AS user_ids,
    COUNT(*)                    AS hit_count
  FROM public.action_audit_logs
  WHERE created_at >= p_since
    AND ip_address IS NOT NULL
    AND user_id    IS NOT NULL
  GROUP BY ip_address
  HAVING COUNT(DISTINCT user_id) >= 2;
$$;


ALTER FUNCTION public.detect_multi_account_ips(p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: detect_suspicious_plays(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_suspicious_plays(p_club_id uuid, p_limit integer DEFAULT 500) RETURNS TABLE(hand_id uuid, player_id uuid, hand_rank text, pot_total numeric, completed_at timestamp with time zone, severity text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_caller uuid := (SELECT auth.uid());
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM clubs c WHERE c.id = p_club_id AND (
      c.owner_id = v_caller
      OR EXISTS (SELECT 1 FROM club_members cm WHERE cm.club_id = c.id AND cm.user_id = v_caller
                   AND cm.role IN ('owner','co_owner','admin')))
  ) THEN
    RAISE EXCEPTION 'not authorized for this club';
  END IF;

  RETURN QUERY
  SELECT hh.id,
         NULLIF(w.value->>'userId', '')::uuid,
         COALESCE(w.value->'hand'->>'name', 'Unknown'),
         hh.pot_size,
         COALESCE(hh.ended_at, hh.created_at),
         CASE WHEN hh.pot_size >= 100 * NULLIF(hh.big_blind, 0) THEN 'high'
              WHEN hh.pot_size >= 60 * NULLIF(hh.big_blind, 0) THEN 'medium'
              ELSE 'low' END
    FROM hand_history hh
    JOIN tables t ON t.id = hh.table_id AND t.club_id = p_club_id
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(hh.winners, '[]'::jsonb)) w
   WHERE hh.created_at > now() - interval '30 days'
     AND hh.big_blind > 0
     AND hh.pot_size >= 40 * hh.big_blind
   ORDER BY hh.pot_size / NULLIF(hh.big_blind, 0) DESC, hh.created_at DESC
   LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.detect_suspicious_plays(p_club_id uuid, p_limit integer) OWNER TO postgres;

