--
-- Name: economy_invariants(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.economy_invariants() RETURNS TABLE(check_name text, ok boolean, detail text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
    v_src text;
    c_write constant text := 'INSERT, UPDATE, DELETE, TRUNCATE';
BEGIN
    SELECT prosrc INTO v_src FROM pg_proc WHERE proname = 'deduct_diamonds' LIMIT 1;
    check_name := 'deduct_diamonds_writes_both_balance_columns';
    ok := v_src IS NOT NULL AND position('diamond_balance' in v_src) > 0;
    detail := 'profiles.diamonds and profiles.diamond_balance must be written together or they drift';
    RETURN NEXT;

    SELECT prosrc INTO v_src FROM pg_proc WHERE proname = 'add_diamonds_to_balance' LIMIT 1;
    check_name := 'add_diamonds_writes_both_balance_columns';
    ok := v_src IS NOT NULL AND position('diamond_balance' in v_src) > 0;
    detail := 'credits must keep both balance columns in step';
    RETURN NEXT;

    SELECT regexp_replace(prosrc, '--[^' || chr(10) || ']*', '', 'g') INTO v_src
      FROM pg_proc WHERE proname = 'initialize_player_profile' LIMIT 1;
    check_name := 'signup_seeds_both_diamond_columns';
    ok := v_src IS NOT NULL AND position('diamond_balance' in v_src) > 0;
    detail := 'initialize_player_profile must seed profiles.diamond_balance alongside profiles.diamonds. Granting the welcome bonus to one half of the pair makes every new account violate no_profiles_balance_drift, which blocks deploys estate-wide.';
    RETURN NEXT;

    check_name := 'signup_allocates_a_free_player_number';
    ok := v_src IS NOT NULL
          AND position('fn_next_player_number' in v_src) > 0
          AND position('public_player_number_seq' in v_src) = 0;
    detail := 'profiles.player_number is UNIQUE across everyone and only fn_next_player_number() loops until it finds a free value. A raw nextval made initialize_player_profile raise uq_profiles_player_number and swallow it into success=false, so profile creation failed silently.';
    RETURN NEXT;

    check_name := 'no_profiles_balance_drift';
    SELECT COUNT(*) = 0 INTO ok FROM public.profiles WHERE diamonds IS DISTINCT FROM diamond_balance;
    detail := 'profiles where diamonds <> diamond_balance';
    RETURN NEXT;

    check_name := 'balance_rpcs_not_executable_by_clients';
    SELECT bool_and(NOT has_function_privilege(r.role, p.oid, 'EXECUTE'))
      INTO ok
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      CROSS JOIN (VALUES ('anon'), ('authenticated')) AS r(role)
     WHERE n.nspname = 'public'
       AND p.proname IN ('add_diamonds_to_balance', 'deduct_diamonds',
                         'award_diamonds', 'award_diamonds_v2');
    ok := COALESCE(ok, true);
    detail := 'a browser-executable balance mutator is a mint';
    RETURN NEXT;

    check_name := 'award_v2_executable_by_service_role';
    SELECT bool_and(has_function_privilege('service_role', p.oid, 'EXECUTE'))
      INTO ok
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public' AND p.proname = 'award_diamonds_v2';
    ok := COALESCE(ok, false);
    detail := 'if this is false, all rewards are DOWN';
    RETURN NEXT;

    check_name := 'profiles_economic_column_guard_trigger_present';
    SELECT COUNT(*) > 0 INTO ok
      FROM pg_trigger
     WHERE tgrelid = 'public.profiles'::regclass
       AND NOT tgisinternal
       AND tgname = 'trg_guard_profile_privileged_columns';
    detail := 'blocks self-granted diamonds / is_vip / vip_tier via PostgREST';
    RETURN NEXT;

    check_name := 'authenticated_cannot_update_economic_columns';
    SELECT COUNT(*) = 0 INTO ok
      FROM unnest(ARRAY['diamonds', 'diamond_balance', 'diamond_multiplier',
                        'is_vip', 'vip_tier', 'vip_expires_at']) AS col
     WHERE has_column_privilege('authenticated', 'public.profiles', col, 'UPDATE');
    detail := 'column-level UPDATE grants on the money/VIP columns';
    RETURN NEXT;

    SELECT prosrc INTO v_src FROM pg_proc WHERE proname = 'award_diamonds_v2' LIMIT 1;
    check_name := 'award_v2_vip_check_is_null_safe';
    ok := v_src IS NOT NULL AND position('COALESCE(v_vip_tier' in v_src) > 0;
    detail := 'VIP tier comparison must COALESCE or it fails open on NULL';
    RETURN NEXT;

    check_name := 'easter_eggs_exempt_from_daily_cap';
    SELECT COALESCE(bool_and(NOT counts_toward_daily_cap), true) INTO ok
      FROM public.diamond_reward_catalog WHERE action_key = 'easter_egg';
    detail := 'the store promises eggs pay on top of the daily cap';
    RETURN NEXT;

    check_name := 'no_client_writable_views';
    SELECT COUNT(*) = 0 INTO ok
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
     WHERE c.relkind = 'v'
       AND c.relname NOT IN ('geography_columns', 'geometry_columns')
       AND (has_table_privilege('anon', c.oid, c_write)
         OR has_table_privilege('authenticated', c.oid, c_write));
    detail := 'a definer view with write grants is an RLS bypass';
    RETURN NEXT;

    check_name := 'anon_mutating_definer_functions_check_auth_uid';
    SELECT COUNT(*) = 0 INTO ok
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public'
       AND p.prosecdef
       AND has_function_privilege('anon', p.oid, 'EXECUTE')
       AND p.prosrc ~* '\m(insert|update|delete)\M'
       AND p.prosrc !~* 'auth\.uid\(\)';
    detail := 'anon-callable definer functions that write without checking auth.uid()';
    RETURN NEXT;

    check_name := 'no_rls_off_tables_writable_by_clients';
    SELECT COUNT(*) = 0 INTO ok
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
     WHERE c.relkind = 'r'
       AND NOT c.relrowsecurity
       AND c.relname <> 'spatial_ref_sys'
       AND (has_table_privilege('anon', c.oid, c_write)
         OR has_table_privilege('authenticated', c.oid, c_write));
    detail := 'tables with RLS disabled that clients can still write to';
    RETURN NEXT;

    RETURN;
END;
$$;


ALTER FUNCTION public.economy_invariants() OWNER TO postgres;

--
-- Name: FUNCTION economy_invariants(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.economy_invariants() IS 'Standing assertions for the diamond economy. Called by scripts/check-economy-invariants.mjs in CI (CHECK 10). Any row with ok=false is a regression. Carries its own statement_timeout: it is a schema audit, not a request-path query.';


--
-- Name: edit_home_game(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.edit_home_game(p_game_id uuid, p_caller_user_id uuid, p_updates jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_game    RECORD;
    v_group   RECORD;
    v_is_host boolean;
    v_allowed text[] := ARRAY[
        'title','description','game_type','stakes','format',
        'buyin_min','buyin_max','scheduled_date','start_time','end_time',
        'address','address_visible_to','location_notes','neighborhood',
        'max_players','min_players','allow_guests','guest_limit',
        'food_drinks','special_rules','cover_photo_url','status'
    ];
    v_key text;
    v_bad_keys text[] := ARRAY[]::text[];
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
    IF v_game.status IN ('completed','cancelled') THEN
        RAISE EXCEPTION 'GAME_IS_FINAL';
    END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;

    v_is_host := (v_game.host_id = p_caller_user_id)
              OR (v_group.owner_id = p_caller_user_id)
              OR EXISTS (SELECT 1 FROM commander_home_members 
                          WHERE group_id = v_game.group_id AND user_id = p_caller_user_id
                            AND role = 'admin' AND status = 'approved');
    IF NOT v_is_host THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;

    FOR v_key IN SELECT jsonb_object_keys(p_updates) LOOP
        IF NOT (v_key = ANY (v_allowed)) THEN
            v_bad_keys := array_append(v_bad_keys, v_key);
        END IF;
    END LOOP;
    IF array_length(v_bad_keys, 1) > 0 THEN
        RAISE EXCEPTION 'DISALLOWED_FIELDS: %', array_to_string(v_bad_keys, ',');
    END IF;

    -- Validate status transition
    IF p_updates ? 'status' AND NOT (p_updates->>'status' IN ('draft','scheduled','confirmed','in_progress')) THEN
        RAISE EXCEPTION 'INVALID_STATUS' 
              USING HINT = 'use cancel_home_game or complete_home_game for final states';
    END IF;

    UPDATE commander_home_games SET
        title              = CASE WHEN p_updates ? 'title' THEN p_updates->>'title' ELSE title END,
        description        = CASE WHEN p_updates ? 'description' THEN p_updates->>'description' ELSE description END,
        game_type          = CASE WHEN p_updates ? 'game_type' THEN p_updates->>'game_type' ELSE game_type END,
        stakes             = CASE WHEN p_updates ? 'stakes' THEN p_updates->>'stakes' ELSE stakes END,
        format             = CASE WHEN p_updates ? 'format' THEN p_updates->>'format' ELSE format END,
        buyin_min          = CASE WHEN p_updates ? 'buyin_min' THEN (p_updates->>'buyin_min')::int ELSE buyin_min END,
        buyin_max          = CASE WHEN p_updates ? 'buyin_max' THEN (p_updates->>'buyin_max')::int ELSE buyin_max END,
        scheduled_date     = CASE WHEN p_updates ? 'scheduled_date' THEN (p_updates->>'scheduled_date')::date ELSE scheduled_date END,
        start_time         = CASE WHEN p_updates ? 'start_time' THEN (p_updates->>'start_time')::time ELSE start_time END,
        end_time           = CASE WHEN p_updates ? 'end_time' THEN (p_updates->>'end_time')::time ELSE end_time END,
        address            = CASE WHEN p_updates ? 'address' THEN p_updates->>'address' ELSE address END,
        address_visible_to = CASE WHEN p_updates ? 'address_visible_to' THEN p_updates->>'address_visible_to' ELSE address_visible_to END,
        location_notes     = CASE WHEN p_updates ? 'location_notes' THEN p_updates->>'location_notes' ELSE location_notes END,
        neighborhood       = CASE WHEN p_updates ? 'neighborhood' THEN p_updates->>'neighborhood' ELSE neighborhood END,
        max_players        = CASE WHEN p_updates ? 'max_players' THEN (p_updates->>'max_players')::int ELSE max_players END,
        min_players        = CASE WHEN p_updates ? 'min_players' THEN (p_updates->>'min_players')::int ELSE min_players END,
        allow_guests       = CASE WHEN p_updates ? 'allow_guests' THEN (p_updates->>'allow_guests')::boolean ELSE allow_guests END,
        guest_limit        = CASE WHEN p_updates ? 'guest_limit' THEN (p_updates->>'guest_limit')::int ELSE guest_limit END,
        food_drinks        = CASE WHEN p_updates ? 'food_drinks' THEN p_updates->>'food_drinks' ELSE food_drinks END,
        special_rules      = CASE WHEN p_updates ? 'special_rules' THEN p_updates->>'special_rules' ELSE special_rules END,
        cover_photo_url    = CASE WHEN p_updates ? 'cover_photo_url' THEN p_updates->>'cover_photo_url' ELSE cover_photo_url END,
        status             = CASE WHEN p_updates ? 'status' THEN p_updates->>'status' ELSE status END,
        updated_at         = NOW()
     WHERE id = p_game_id;

    INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (v_game.group_id, p_caller_user_id, 'game', p_game_id, 'edited',
            jsonb_build_object('fields', (SELECT array_agg(k) FROM jsonb_object_keys(p_updates) k)));

    RETURN jsonb_build_object('success', true, 'game_id', p_game_id);
END;
$$;


ALTER FUNCTION public.edit_home_game(p_game_id uuid, p_caller_user_id uuid, p_updates jsonb) OWNER TO postgres;

--
-- Name: edit_home_group(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.edit_home_group(p_group_id uuid, p_caller_user_id uuid, p_updates jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group       RECORD;
    v_is_host     boolean;
    v_allowed     text[] := ARRAY[
        'name','description','tagline','profile_photo_url','cover_photo_url',
        'city','state','zip_code','latitude','longitude',
        'default_game_type','default_stakes','typical_buyin_min','typical_buyin_max',
        'max_players','typical_day','typical_time','frequency',
        'is_private','requires_approval','tags'
    ];
    v_key         text;
    v_bad_keys    text[] := ARRAY[]::text[];
    v_new_name    text;
    v_new_lat     numeric;
    v_new_lng     numeric;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;

    v_is_host := (v_group.owner_id = p_caller_user_id) OR EXISTS (
        SELECT 1 FROM commander_home_members
         WHERE group_id = p_group_id AND user_id = p_caller_user_id
           AND role = 'admin' AND status = 'approved');

    IF NOT v_is_host THEN RAISE EXCEPTION 'NOT_A_HOST'; END IF;

    -- Allow-list validation
    FOR v_key IN SELECT jsonb_object_keys(p_updates) LOOP
        IF NOT (v_key = ANY (v_allowed)) THEN
            v_bad_keys := array_append(v_bad_keys, v_key);
        END IF;
    END LOOP;
    IF array_length(v_bad_keys, 1) > 0 THEN
        RAISE EXCEPTION 'DISALLOWED_FIELDS: %', array_to_string(v_bad_keys, ',');
    END IF;

    -- F165: reject empty name if name is being set
    IF p_updates ? 'name' THEN
        v_new_name := p_updates->>'name';
        IF v_new_name IS NULL OR length(trim(v_new_name)) = 0 THEN
            RAISE EXCEPTION 'INVALID_NAME'
                  USING HINT = 'name cannot be empty or whitespace';
        END IF;
        -- Also surface the CHECK constraint as a clean app error
        IF length(v_new_name) > 120 THEN
            RAISE EXCEPTION 'NAME_TOO_LONG'
                  USING HINT = 'max 120 characters';
        END IF;
    END IF;

    -- F166: validate lat/lng ranges (Earth coords only)
    IF p_updates ? 'latitude' AND p_updates->>'latitude' IS NOT NULL THEN
        v_new_lat := (p_updates->>'latitude')::numeric;
        IF v_new_lat < -90 OR v_new_lat > 90 THEN
            RAISE EXCEPTION 'INVALID_LATITUDE'
                  USING HINT = 'latitude must be in [-90, 90]';
        END IF;
    END IF;
    IF p_updates ? 'longitude' AND p_updates->>'longitude' IS NOT NULL THEN
        v_new_lng := (p_updates->>'longitude')::numeric;
        IF v_new_lng < -180 OR v_new_lng > 180 THEN
            RAISE EXCEPTION 'INVALID_LONGITUDE'
                  USING HINT = 'longitude must be in [-180, 180]';
        END IF;
    END IF;

    -- Existing guard: profile_photo_url cannot be cleared
    IF p_updates ? 'profile_photo_url'
       AND (p_updates->>'profile_photo_url' IS NULL
            OR trim(p_updates->>'profile_photo_url') = '') THEN
        RAISE EXCEPTION 'CANNOT_CLEAR_LOGO';
    END IF;

    UPDATE commander_home_groups SET
        -- F165 fix: use CASE-WHEN like every other field (was COALESCE)
        name               = CASE WHEN p_updates ? 'name' THEN p_updates->>'name' ELSE name END,
        description        = CASE WHEN p_updates ? 'description' THEN p_updates->>'description' ELSE description END,
        tagline            = CASE WHEN p_updates ? 'tagline' THEN p_updates->>'tagline' ELSE tagline END,
        profile_photo_url  = COALESCE(p_updates->>'profile_photo_url', profile_photo_url),
        cover_photo_url    = CASE WHEN p_updates ? 'cover_photo_url' THEN p_updates->>'cover_photo_url' ELSE cover_photo_url END,
        city               = CASE WHEN p_updates ? 'city' THEN p_updates->>'city' ELSE city END,
        state              = CASE WHEN p_updates ? 'state' THEN p_updates->>'state' ELSE state END,
        zip_code           = CASE WHEN p_updates ? 'zip_code' THEN p_updates->>'zip_code' ELSE zip_code END,
        latitude           = CASE WHEN p_updates ? 'latitude' THEN (p_updates->>'latitude')::numeric ELSE latitude END,
        longitude          = CASE WHEN p_updates ? 'longitude' THEN (p_updates->>'longitude')::numeric ELSE longitude END,
        default_game_type  = CASE WHEN p_updates ? 'default_game_type' THEN p_updates->>'default_game_type' ELSE default_game_type END,
        default_stakes     = CASE WHEN p_updates ? 'default_stakes' THEN p_updates->>'default_stakes' ELSE default_stakes END,
        typical_buyin_min  = CASE WHEN p_updates ? 'typical_buyin_min' THEN (p_updates->>'typical_buyin_min')::int ELSE typical_buyin_min END,
        typical_buyin_max  = CASE WHEN p_updates ? 'typical_buyin_max' THEN (p_updates->>'typical_buyin_max')::int ELSE typical_buyin_max END,
        max_players        = CASE WHEN p_updates ? 'max_players' THEN (p_updates->>'max_players')::int ELSE max_players END,
        typical_day        = CASE WHEN p_updates ? 'typical_day' THEN p_updates->>'typical_day' ELSE typical_day END,
        typical_time       = CASE WHEN p_updates ? 'typical_time' THEN (p_updates->>'typical_time')::time ELSE typical_time END,
        frequency          = CASE WHEN p_updates ? 'frequency' THEN p_updates->>'frequency' ELSE frequency END,
        is_private         = CASE WHEN p_updates ? 'is_private' THEN (p_updates->>'is_private')::boolean ELSE is_private END,
        requires_approval  = CASE WHEN p_updates ? 'requires_approval' THEN (p_updates->>'requires_approval')::boolean ELSE requires_approval END,
        tags               = CASE WHEN p_updates ? 'tags'
                                  THEN ARRAY(SELECT jsonb_array_elements_text(p_updates->'tags'))::text[]
                                  ELSE tags END,
        updated_at         = NOW()
     WHERE id = p_group_id;

    INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (p_group_id, p_caller_user_id, 'group', p_group_id, 'edited',
            jsonb_build_object('fields', (SELECT array_agg(k) FROM jsonb_object_keys(p_updates) k)));

    RETURN jsonb_build_object(
        'success', true,
        'group_id', p_group_id,
        'fields_updated', (SELECT array_agg(k) FROM jsonb_object_keys(p_updates) k)
    );
END;
$$;


ALTER FUNCTION public.edit_home_group(p_group_id uuid, p_caller_user_id uuid, p_updates jsonb) OWNER TO postgres;

--
-- Name: edit_home_group_post(uuid, uuid, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.edit_home_group_post(p_post_id uuid, p_caller_user_id uuid, p_content text, p_image_urls text[] DEFAULT NULL::text[], p_is_pinned boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_post   RECORD;
    v_group  RECORD;
    v_is_host boolean;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    SELECT * INTO v_post FROM commander_home_posts WHERE id = p_post_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'POST_NOT_FOUND'; END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_post.group_id;

    v_is_host := (v_group.owner_id = p_caller_user_id)
              OR EXISTS (SELECT 1 FROM commander_home_members 
                          WHERE group_id = v_post.group_id AND user_id = p_caller_user_id
                            AND role = 'admin' AND status = 'approved');

    -- Author OR host can edit
    IF v_post.author_id <> p_caller_user_id AND NOT v_is_host THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    IF p_content IS NULL OR length(trim(p_content)) = 0 THEN
        RAISE EXCEPTION 'EMPTY_CONTENT';
    END IF;
    IF length(p_content) > 10000 THEN
        RAISE EXCEPTION 'CONTENT_TOO_LONG';
    END IF;

    -- Only hosts can pin
    IF p_is_pinned IS NOT NULL AND p_is_pinned <> v_post.is_pinned AND NOT v_is_host THEN
        RAISE EXCEPTION 'PIN_REQUIRES_HOST';
    END IF;

    UPDATE commander_home_posts
       SET content     = trim(p_content),
           image_urls  = COALESCE(p_image_urls, image_urls),
           is_pinned   = COALESCE(p_is_pinned, is_pinned),
           updated_at  = NOW()
     WHERE id = p_post_id;

    RETURN jsonb_build_object('success', true, 'post_id', p_post_id);
END;
$$;


ALTER FUNCTION public.edit_home_group_post(p_post_id uuid, p_caller_user_id uuid, p_content text, p_image_urls text[], p_is_pinned boolean) OWNER TO postgres;

--
-- Name: edit_venue_post(uuid, uuid, text, text, text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.edit_venue_post(p_post_id uuid, p_caller_user_id uuid, p_content text DEFAULT NULL::text, p_post_type text DEFAULT NULL::text, p_image_urls text[] DEFAULT NULL::text[], p_video_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_post RECORD; v_is_manager boolean;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    SELECT * INTO v_post FROM commander_venue_posts WHERE id = p_post_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'POST_NOT_FOUND'; END IF;

    -- Author OR any venue manager can edit
    IF v_post.author_id <> p_caller_user_id THEN
        v_is_manager := public.is_venue_manager(p_caller_user_id, v_post.venue_id);
        IF NOT v_is_manager THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;
    END IF;

    UPDATE commander_venue_posts 
       SET content = COALESCE(p_content, content),
           post_type = COALESCE(p_post_type, post_type),
           image_urls = COALESCE(p_image_urls, image_urls),
           video_url = COALESCE(p_video_url, video_url),
           updated_at = NOW()
     WHERE id = p_post_id;

    RETURN jsonb_build_object('success', true, 'post_id', p_post_id);
END; $$;


ALTER FUNCTION public.edit_venue_post(p_post_id uuid, p_caller_user_id uuid, p_content text, p_post_type text, p_image_urls text[], p_video_url text) OWNER TO postgres;

--
-- Name: enforce_chip_ledger_performed_by(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_chip_ledger_performed_by() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.performed_by = '00000000-0000-0000-0000-000000000000'::uuid THEN
    RAISE EXCEPTION 'chip_ledger.performed_by must be a real user, got all-zero sentinel'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  -- Cross-scope between two non-system entity types requires the operator
  -- to be identified - this catches callers who forget to thread userId.
  IF NEW.from_type <> NEW.to_type
     AND NEW.from_type NOT IN ('system_mint', 'system_burn')
     AND NEW.to_type   NOT IN ('system_mint', 'system_burn') THEN
    -- performed_by is already NOT NULL + non-zero here; nothing extra to do.
    NULL;
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION public.enforce_chip_ledger_performed_by() OWNER TO postgres;

