    IF NEW.profile_photo_url IS NULL OR trim(NEW.profile_photo_url) = '' THEN
        RAISE EXCEPTION 'PROFILE_PHOTO_REQUIRED' 
              USING HINT = 'home groups must have a logo (Phase 17 requirement)',
                    ERRCODE = '23514';
