--
-- Name: enforce_live_comment_author_name(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_live_comment_author_name() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_username TEXT;
    v_full_name TEXT;
BEGIN
    -- Resolve the canonical username from profiles
    SELECT username, full_name
      INTO v_username, v_full_name
      FROM public.profiles
     WHERE id = NEW.user_id
     LIMIT 1;

    -- Always overwrite - client value is ignored
    NEW.author_name := COALESCE(v_username, v_full_name, 'Viewer');

    RETURN NEW;
END;
$$;


