--
-- Name: enforce_scrape_provenance(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_scrape_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NEW.scrape_html_hash IS NULL OR NEW.scrape_timestamp IS NULL THEN
        RAISE EXCEPTION 'CRITICAL VIOLATION: Cannot insert/update without scrape_html_hash and scrape_timestamp. (15-Layer Scrapling Web Scraper Integrity Standard)';
    END IF;

    -- 'manual_research'   = compiled from an official published schedule and
    --                       re-verified by hand. Attributed, but deliberately NOT
    --                       claiming to be a scrape.
    -- 'scraped_inferred'  = scraped, but extracted by regex/heuristic block parse
    --                       rather than a structured field. Lower confidence than
    --                       'scraped_verified' and must stay distinguishable from it.
    IF NEW.data_quality NOT IN ('scraped_verified', 'scraped_inferred', 'stale', 'expired', 'manual_research') THEN
        RAISE EXCEPTION 'CRITICAL VIOLATION: data_quality must be scraped_verified, scraped_inferred, stale, expired, or manual_research.';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_scrape_provenance() OWNER TO postgres;

--
-- Name: enforce_tour_scrape_provenance(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_tour_scrape_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.scrape_html_hash IS NULL OR NEW.scrape_html_hash = '' THEN
    RAISE EXCEPTION 'tour_stop_events: scrape_html_hash required on all records';
  END IF;
  IF NEW.scrape_timestamp IS NULL THEN
    RAISE EXCEPTION 'tour_stop_events: scrape_timestamp required on all records';
  END IF;
  IF NEW.source_url IS NULL OR NEW.source_url = '' THEN
    RAISE EXCEPTION 'tour_stop_events: source_url required - must capture where data was scraped from';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_tour_scrape_provenance() OWNER TO postgres;

--
-- Name: enforce_user_leak_lifecycle(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_user_leak_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_legacy_resolution boolean := false;
  v_request_role text := COALESCE(auth.role(), current_setting('request.jwt.claim.role', true), current_user);
BEGIN
  -- Serialize quota decisions for every writer, including service-role API
  -- upserts. The existence recheck lets an upsert update an established
  -- identity at the cap while rejecting a genuinely new leak type.
  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('user_leaks:' || NEW.user_id::text, 0));
    IF NOT EXISTS (
      SELECT 1 FROM public.user_leaks
      WHERE user_id = NEW.user_id
        AND leak_type IS NOT DISTINCT FROM NEW.leak_type
    ) AND (SELECT count(*) FROM public.user_leaks WHERE user_id = NEW.user_id) >= 500 THEN
      RAISE EXCEPTION 'Per-account leak record limit reached' USING ERRCODE = '54000';
    END IF;
  END IF;

  -- The Training Accountant historically writes its own repetition counters
  -- through authenticated RLS. Preserve that workflow while making solver EV,
  -- status, and resolution provenance service-only fields.
  IF v_request_role IN ('anon', 'authenticated') THEN
    IF TG_OP = 'INSERT' THEN
      NEW.source_system := 'training_accountant';
      NEW.status := 'emerging';
      NEW.is_active := true;
      NEW.avg_ev_loss_bb := NULL;
      NEW.ev_loss_measured := false;
      NEW.detector_managed := false;
      NEW.resolved_at := NULL;
      NEW.remediation_completed_at := NULL;
      NEW.resolution_source := NULL;
    ELSE
      IF NOT (
        OLD.source_system = 'training_accountant'
        OR OLD.leak_type LIKE 'training_%'
        OR OLD.leak_type IS NULL
      ) THEN
        RAISE EXCEPTION 'Server-owned leak evidence cannot be changed directly'
          USING ERRCODE = '42501';
      END IF;
      NEW.user_id := OLD.user_id;
      NEW.leak_type := OLD.leak_type;
      NEW.source_system := OLD.source_system;
      NEW.status := OLD.status;
      NEW.is_active := OLD.is_active;
      NEW.avg_ev_loss_bb := OLD.avg_ev_loss_bb;
      NEW.ev_loss_measured := OLD.ev_loss_measured;
      NEW.detector_managed := OLD.detector_managed;
      NEW.resolved_at := OLD.resolved_at;
      NEW.remediation_completed_at := OLD.remediation_completed_at;
      NEW.resolution_source := OLD.resolution_source;
    END IF;
  END IF;

  -- Modern writers change status and the compatibility flag together. Older
  -- training clients may change only is_active, so honor that transition when
  -- status itself was not changed in the same UPDATE.
  IF TG_OP = 'INSERT' THEN
    v_legacy_resolution := NEW.is_active = false;
  ELSE
    v_legacy_resolution := NEW.is_active = false
      AND NEW.status IS NOT DISTINCT FROM OLD.status;
  END IF;

  IF NEW.status = 'resolved' OR v_legacy_resolution THEN
    NEW.status := 'resolved';
    NEW.is_active := false;
    NEW.resolved_at := COALESCE(NEW.resolved_at, NEW.remediation_completed_at, now());
    NEW.remediation_completed_at := COALESCE(NEW.remediation_completed_at, NEW.resolved_at, now());
    NEW.resolution_source := CASE
      WHEN NEW.resolution_source IN ('manual', 'detector') THEN NEW.resolution_source
      ELSE NULL
    END;
  ELSIF NEW.status IS NULL OR NEW.status IN ('emerging', 'persistent', 'improving') THEN
    NEW.status := COALESCE(NEW.status, 'emerging');
    NEW.is_active := true;
    NEW.resolved_at := NULL;
    NEW.remediation_completed_at := NULL;
    NEW.resolution_source := NULL;
  ELSE
    RAISE EXCEPTION 'Unsupported user_leaks status: %', NEW.status
      USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_user_leak_lifecycle() OWNER TO postgres;

--
-- Name: enforce_user_training_leak_quota(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_user_training_leak_quota() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  -- LeakService updates an existing row when possible, so every INSERT here
  -- is a new stored record and must participate in the account quota. The
  -- advisory lock prevents parallel clients from overshooting the limit.
  PERFORM pg_advisory_xact_lock(hashtextextended('user_training_leaks:' || NEW.user_id::text, 0));
  IF (SELECT count(*) FROM public.user_training_leaks WHERE user_id = NEW.user_id) >= 500 THEN
    RAISE EXCEPTION 'Per-account training leak record limit reached' USING ERRCODE = '54000';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_user_training_leak_quota() OWNER TO postgres;

--
-- Name: enforce_vdt_scrape_provenance_truth(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_vdt_scrape_provenance_truth() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.scrape_html_hash is null or new.scrape_timestamp is null then
    raise exception 'venue_daily_tournaments requires scrape_html_hash and scrape_timestamp';
  end if;
  if new.data_quality is null or new.data_quality not in (
    'scraped_verified', 'scraped_inferred', 'manual_research',
    'stale', 'expired', 'pending'
  ) then
    raise exception 'unsupported venue_daily_tournaments data_quality: %', new.data_quality;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.enforce_vdt_scrape_provenance_truth() OWNER TO postgres;

--
-- Name: enforce_venue_provenance(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_venue_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Allow name_only, unverified, pending for venue scaffolding
  IF NEW.data_quality IN ('name_only', 'unverified', 'pending') THEN
    RETURN NEW;
  END IF;
  -- For scraped_verified, require full provenance
  IF NEW.data_quality = 'scraped_verified' THEN
    IF NEW.scrape_html_hash IS NULL THEN
      RAISE EXCEPTION 'VENUE PROVENANCE VIOLATION: Cannot mark as scraped_verified without scrape_html_hash';
    END IF;
    IF NEW.scrape_timestamp IS NULL THEN
      RAISE EXCEPTION 'VENUE PROVENANCE VIOLATION: Cannot mark as scraped_verified without scrape_timestamp';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_venue_provenance() OWNER TO postgres;

--
-- Name: enqueue_daily_challenge_event(uuid, text, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enqueue_daily_challenge_event(p_user_id uuid, p_event_key text, p_amounts jsonb, p_magnitudes jsonb, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_event public.daily_challenge_event_outbox%ROWTYPE;
  v_receipt public.daily_challenge_progress_events%ROWTYPE;
  v_receipt_found boolean;
BEGIN
  PERFORM public.fn_lock_daily_mission_user(p_user_id);

  INSERT INTO public.daily_challenge_event_outbox (
    user_id,
    event_key,
    amounts,
    magnitudes,
    occurred_at
  ) VALUES (
    p_user_id,
    p_event_key,
    p_amounts,
    p_magnitudes,
    p_occurred_at
  )
  ON CONFLICT (user_id, event_key) DO NOTHING;

  SELECT * INTO STRICT v_event
  FROM public.daily_challenge_event_outbox
  WHERE user_id = p_user_id
    AND event_key = p_event_key
  FOR UPDATE;

  IF v_event.amounts IS DISTINCT FROM p_amounts
     OR v_event.magnitudes IS DISTINCT FROM p_magnitudes
     OR v_event.threshold_values IS DISTINCT FROM '{}'::jsonb
     OR v_event.occurred_at IS DISTINCT FROM p_occurred_at
  THEN
    RAISE EXCEPTION 'Daily Missions event key is already bound to another payload';
  END IF;

  SELECT * INTO v_receipt
  FROM public.daily_challenge_progress_events
  WHERE user_id = p_user_id
    AND event_key = p_event_key
  FOR UPDATE;
  v_receipt_found := FOUND;

  IF v_receipt_found
     AND (
       v_receipt.amounts IS DISTINCT FROM v_event.amounts
       OR v_receipt.magnitudes IS DISTINCT FROM v_event.magnitudes
       OR v_receipt.threshold_values IS DISTINCT FROM '{}'::jsonb
       OR v_receipt.occurred_at IS DISTINCT FROM v_event.occurred_at
     )
  THEN
    RAISE EXCEPTION 'Daily Missions event key is already bound to another payload';
  END IF;

  BEGIN
    PERFORM public.record_daily_challenge_event(
      v_event.user_id,
      v_event.event_key,
      v_event.amounts,
      v_event.magnitudes,
      v_event.occurred_at
    );
    DELETE FROM public.daily_challenge_event_outbox
    WHERE user_id = v_event.user_id
      AND event_key = v_event.event_key;
    RETURN true;
  EXCEPTION WHEN OTHERS THEN
    UPDATE public.daily_challenge_event_outbox
    SET attempts = attempts + 1,
        last_error = left(SQLERRM, 1000),
        next_attempt_at = now() + interval '1 minute'
    WHERE user_id = v_event.user_id
      AND event_key = v_event.event_key;
    RETURN false;
  END;
END;
$$;


ALTER FUNCTION public.enqueue_daily_challenge_event(p_user_id uuid, p_event_key text, p_amounts jsonb, p_magnitudes jsonb, p_occurred_at timestamp with time zone) OWNER TO postgres;

