--
-- Name: enqueue_daily_mission_reset_notifications(date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enqueue_daily_mission_reset_notifications(p_cycle_date date DEFAULT ((now() AT TIME ZONE 'UTC'::text))::date, p_limit integer DEFAULT 1000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_inserted integer;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'service role required';
  END IF;
  IF p_cycle_date IS NULL THEN
    RAISE EXCEPTION 'p_cycle_date is required';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 5000 THEN
    RAISE EXCEPTION 'p_limit must be between 1 and 5000';
  END IF;

  INSERT INTO public.notifications (
    user_id,
    type,
    title,
    message,
    link,
    action_url,
    read,
    is_read,
    data
  )
  SELECT p.user_id,
         'daily_challenge',
         'Daily Missions Are Live',
         'A Fresh Set Of Poker Missions And Rewards Is Ready In Club Arena.',
         '/hub/club-arena/challenges',
         '/hub/club-arena/challenges',
         false,
         false,
         jsonb_build_object(
           'source', 'club_arena_daily_missions',
           'cycle_date', p_cycle_date::text,
           'tier', 'daily'
         )
  FROM public.user_notification_preferences p
  WHERE p.daily_mission_reminders IS TRUE
    AND NOT EXISTS (
      SELECT 1
      FROM public.notifications n
      WHERE n.user_id = p.user_id
        AND n.type = 'daily_challenge'
        AND n.data ->> 'source' = 'club_arena_daily_missions'
        AND n.data ->> 'cycle_date' = p_cycle_date::text
    )
  ORDER BY p.user_id
  LIMIT p_limit
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted;
END;
$$;


ALTER FUNCTION public.enqueue_daily_mission_reset_notifications(p_cycle_date date, p_limit integer) OWNER TO postgres;

--
-- Name: enter_trivia_tournament_v2(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enter_trivia_tournament_v2(p_tournament_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_t public.trivia_tournaments%ROWTYPE;
    v_profile public.profiles%ROWTYPE;
    v_fee int;
    v_net int;
    v_cut int;
    v_house_after numeric(20,0);
    v_count int;
    v_charge jsonb;
    v_entry public.trivia_tournament_entries%ROWTYPE;
BEGIN
    IF (SELECT auth.role()) <> 'service_role' THEN RAISE EXCEPTION 'service_role required'; END IF;
    SELECT * INTO v_t FROM public.trivia_tournaments WHERE id=p_tournament_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','tournament_not_found'); END IF;
    IF v_t.status NOT IN ('upcoming','registration','active')
       OR (v_t.status='active' AND COALESCE(v_t.current_round,0)>=1) THEN
        RETURN jsonb_build_object('success',false,'error','registration_closed');
    END IF;
    IF EXISTS (SELECT 1 FROM public.trivia_tournament_entries
                WHERE tournament_id=p_tournament_id AND user_id=p_user_id) THEN
        RETURN jsonb_build_object('success',false,'error','already_entered','duplicate',true);
    END IF;
    SELECT count(*)::int INTO v_count FROM public.trivia_tournament_entries
     WHERE tournament_id=p_tournament_id;
    IF v_t.max_players IS NOT NULL AND v_count >= v_t.max_players THEN
        RETURN jsonb_build_object('success',false,'error','tournament_full');
    END IF;
    SELECT * INTO v_profile FROM public.profiles WHERE id=p_user_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','profile_not_found'); END IF;
    IF NOT (COALESCE(v_profile.is_vip,false)
            AND (v_profile.vip_tier='lifetime' OR v_profile.vip_expires_at>now())) THEN
        RETURN jsonb_build_object('success',false,'error','vip_required');
    END IF;
    v_fee := GREATEST(COALESCE(v_t.entry_fee,0),0);
    -- DIAMOND-RULINGS 8: the house cut is 10 percent rounded to the nearest diamond, at least
    -- one on any paid entry; never floored to zero and never burned by omission.
    v_net := CASE WHEN v_fee > 0 THEN v_fee - GREATEST(1, round(v_fee * 0.10))::int ELSE 0 END;
    IF v_fee > 0 THEN
        SELECT public.add_diamonds_to_balance(
            p_user_id,-v_fee,'tournament_entry',
            'Tournament entry - '||v_t.name,
            'trivia_tourn_entry_'||p_tournament_id::text||'_'||p_user_id::text
        ) INTO v_charge;
        IF COALESCE((v_charge->>'success')::boolean,false) IS NOT TRUE THEN
            RETURN jsonb_build_object('success',false,'error',
                COALESCE(v_charge->>'error','insufficient_diamonds'));
        END IF;
    END IF;
    INSERT INTO public.trivia_tournament_entries(tournament_id,user_id,score,created_at)
    VALUES(p_tournament_id,p_user_id,0,now()) RETURNING * INTO v_entry;
    UPDATE public.trivia_tournaments
       SET prize_pool=COALESCE(prize_pool,0)+v_net
     WHERE id=p_tournament_id
     RETURNING prize_pool INTO v_t.prize_pool;
    -- DR14: the slice of the fee that does not reach the prize pool reaches
    -- the house, with a ledger row, instead of vanishing.
    v_cut := v_fee - v_net;
    IF v_cut > 0 THEN
        UPDATE public.ca_diamond_house
           SET balance = balance + v_cut, updated_at = now()
         WHERE id = 1
         RETURNING balance INTO v_house_after;
        IF v_house_after IS NULL THEN
            PERFORM public.fn_ca_diamond_incident(
                'DR14:house_account_missing','critical',p_user_id,v_cut,
                'enter_trivia_tournament_v2',
                jsonb_build_object('tournament_id',p_tournament_id,'fee',v_fee,'net',v_net));
        ELSE
            INSERT INTO public.ca_diamond_house_ledger
                (delta, balance_after, reason, reference, user_id, tournament_id)
            VALUES (v_cut, v_house_after, 'trivia_tournament_entry_cut',
                    'trivia_tourn_cut_'||p_tournament_id::text||'_'||p_user_id::text,
                    p_user_id, p_tournament_id);
        END IF;
    END IF;
    v_count := v_count+1;
    RETURN jsonb_build_object('success',true,'entry',to_jsonb(v_entry),
        'new_balance',v_charge->'new_balance','new_prize_pool',v_t.prize_pool,
        'entries_count',v_count);
END;
$$;


ALTER FUNCTION public.enter_trivia_tournament_v2(p_tournament_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: expire_lapsed_vip(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_lapsed_vip() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_count integer := 0;
BEGIN
    UPDATE public.profiles
       SET is_vip     = false,
           vip_tier   = NULL,
           updated_at = now()
     WHERE is_vip = true
       AND vip_expires_at IS NOT NULL
       AND vip_expires_at < now()
       AND COALESCE(vip_tier, '') <> 'lifetime';

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION public.expire_lapsed_vip() OWNER TO postgres;

--
-- Name: FUNCTION expire_lapsed_vip(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.expire_lapsed_vip() IS 'Lapses expired VIP subscriptions (is_vip=false, vip_tier=NULL). Lifetime tiers are never lapsed. Returns the number of rows lapsed. Schedule hourly.';


--
-- Name: expire_old_buyin_requests(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_old_buyin_requests() RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH expired AS (
    UPDATE buyin_requests
    SET status = 'expired'
    WHERE status = 'pending' AND expires_at < NOW()
    RETURNING id
  )
  SELECT count(*)::integer FROM expired;
$$;


ALTER FUNCTION public.expire_old_buyin_requests() OWNER TO postgres;

--
-- Name: expire_old_queue_entries(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_old_queue_entries() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_n integer;
BEGIN
    UPDATE public.trivia_pvp_queue
       SET status = 'expired'
     WHERE status = 'waiting'
       AND expires_at < now();
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n;
END;
$$;


ALTER FUNCTION public.expire_old_queue_entries() OWNER TO postgres;

--
-- Name: FUNCTION expire_old_queue_entries(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.expire_old_queue_entries() IS 'Phase 80 — sweeps abandoned matchmaking entries. Call it from joinMatchmakingQueue()/findMatch() in src/services/pvpMatchmaking.js BEFORE enqueueing: a stale waiting row otherwise blocks the user against idx_pvp_queue_one_waiting permanently.';


--
-- Name: expire_settlement_locks(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_settlement_locks() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE expired_count INTEGER;
BEGIN
  UPDATE settlement_locks SET is_active = false, unlocked_at = now()
  WHERE is_active = true AND unlock_at <= now();
  GET DIAGNOSTICS expired_count = ROW_COUNT;
  UPDATE clubs SET settlement_locked = false, settlement_locked_until = NULL
  WHERE settlement_locked = true AND settlement_locked_until <= now();
  RETURN expired_count;
END;
$$;


ALTER FUNCTION public.expire_settlement_locks() OWNER TO postgres;

--
-- Name: export_home_group_members_csv(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.export_home_group_members_csv(p_group_id uuid, p_caller_user_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group   RECORD;
    v_csv     text := '';
    v_member  RECORD;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;
    IF v_group.owner_id <> p_caller_user_id 
       AND NOT EXISTS (SELECT 1 FROM commander_home_members 
                        WHERE group_id = p_group_id AND user_id = p_caller_user_id
                          AND role = 'admin' AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_A_HOST'; END IF;

    -- Header
    v_csv := 'display_name,username,email,role,status,is_regular,games_attended,flake_strikes,last_attended,joined_at' || chr(10);

    FOR v_member IN
        SELECT 
            COALESCE(p.display_name, p.full_name, '') AS display_name,
            COALESCE(p.username, '') AS username,
            COALESCE(au.email, '') AS email,
            m.role, m.status, 
            COALESCE(m.is_regular, false) AS is_regular,
            COALESCE(m.games_attended, 0) AS games_attended,
            COALESCE(m.flake_strikes, 0) AS flake_strikes,
            m.last_attended, m.joined_at
          FROM commander_home_members m
          LEFT JOIN profiles p ON p.id = m.user_id
          LEFT JOIN auth.users au ON au.id = m.user_id
         WHERE m.group_id = p_group_id
         ORDER BY m.joined_at
    LOOP
        v_csv := v_csv 
            || '"' || replace(v_member.display_name, '"', '""') || '",'
            || '"' || replace(v_member.username, '"', '""') || '",'
            || '"' || replace(v_member.email, '"', '""') || '",'
            || v_member.role || ','
            || v_member.status || ','
            || v_member.is_regular || ','
            || v_member.games_attended || ','
            || v_member.flake_strikes || ','
            || COALESCE(v_member.last_attended::text, '') || ','
            || COALESCE(v_member.joined_at::text, '')
            || chr(10);
    END LOOP;

    RETURN v_csv;
END;
$$;


ALTER FUNCTION public.export_home_group_members_csv(p_group_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: finalize_trivia_session_stats_v3(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finalize_trivia_session_stats_v3(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_session public.trivia_sessions%ROWTYPE;
    v_question_id uuid;
    v_category text;
    v_correct_index integer;
    v_answer jsonb;
    v_permutation jsonb;
    v_display_index integer;
    v_original_index integer;
    v_was_correct boolean;
    v_event_id uuid;
    v_answered integer := 0;
    v_correct integer := 0;
    v_skipped integer := 0;
    v_play_date date;
    v_streak integer := 0;
BEGIN
    SELECT * INTO v_session
      FROM public.trivia_sessions
     WHERE id = p_session_id
     FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'session_not_found');
    END IF;
    IF v_session.status <> 'submitted' OR v_session.settlement_result IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'session_not_settled');
    END IF;
    IF v_session.stats_recorded_at IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'deduped', true);
    END IF;

    -- Claim before the derived writes. Any later error rolls the claim back,
    -- making a retry safe and complete.
    UPDATE public.trivia_sessions
       SET stats_recorded_at = now()
     WHERE id = p_session_id;

    FOREACH v_question_id IN ARRAY COALESCE(v_session.question_ids, ARRAY[]::uuid[])
    LOOP
        SELECT category, correct_index
          INTO v_category, v_correct_index
          FROM public.trivia_questions
         WHERE id = v_question_id;
        IF NOT FOUND THEN
            CONTINUE;
        END IF;

        v_answer := COALESCE(v_session.answers, '{}'::jsonb) -> v_question_id::text;
        v_display_index := CASE
            WHEN v_answer IS NOT NULL AND (v_answer->>'d') ~ '^-?[0-9]+$'
                THEN (v_answer->>'d')::integer
            ELSE NULL
        END;
        v_permutation := COALESCE(v_session.permutations, '{}'::jsonb) -> v_question_id::text;
        v_original_index := NULL;
        IF v_display_index IS NOT NULL
           AND v_display_index >= 0
           AND jsonb_typeof(v_permutation) = 'array'
           AND v_display_index < jsonb_array_length(v_permutation)
           AND (v_permutation->>v_display_index) ~ '^[0-9]+$' THEN
            v_original_index := (v_permutation->>v_display_index)::integer;
        END IF;

        v_was_correct := CASE
            WHEN v_original_index IS NULL OR v_correct_index IS NULL THEN NULL
            ELSE v_original_index = v_correct_index
        END;

        v_event_id := NULL;
        INSERT INTO public.trivia_question_result_events
            (user_id, question_id, mode, source_type, source_id,
             display_index, original_index, was_correct, was_skipped)
        VALUES
            (v_session.user_id, v_question_id, v_session.mode, 'session', v_session.id,
             v_display_index, v_original_index, v_was_correct,
             v_answer IS NOT NULL AND COALESCE(v_display_index, -1) < 0)
        ON CONFLICT (source_type, source_id, user_id, question_id) DO NOTHING
        RETURNING id INTO v_event_id;
        IF v_event_id IS NULL THEN
            CONTINUE;
        END IF;

        INSERT INTO public.trivia_user_question_history AS h
            (user_id, question_id, seen_at, was_correct, mode)
        VALUES
            (v_session.user_id, v_question_id, COALESCE(v_session.created_at, now()),
             v_was_correct, v_session.mode)
        ON CONFLICT (user_id, question_id) DO UPDATE
            SET was_correct = EXCLUDED.was_correct,
                mode = EXCLUDED.mode;

        IF v_answer IS NOT NULL AND COALESCE(v_display_index, -1) < 0 THEN
            UPDATE public.trivia_questions
               SET skipped_count = COALESCE(skipped_count, 0) + 1
             WHERE id = v_question_id;
            v_skipped := v_skipped + 1;
        END IF;

        IF v_original_index IS NOT NULL THEN
            v_answered := v_answered + 1;
            IF v_was_correct IS TRUE THEN
                v_correct := v_correct + 1;
                UPDATE public.trivia_questions
                   SET times_correct = COALESCE(times_correct, 0) + 1
                 WHERE id = v_question_id;
            END IF;

            INSERT INTO public.trivia_category_mastery AS m
                (user_id, category, total_answered, correct_count, mastery_level, updated_at)
            VALUES
                (v_session.user_id, COALESCE(v_category, 'general'), 1,
                 CASE WHEN v_was_correct IS TRUE THEN 1 ELSE 0 END,
                 CASE WHEN v_was_correct IS TRUE THEN 10 ELSE 1 END, now())
            ON CONFLICT (user_id, category) DO UPDATE SET
                total_answered = m.total_answered + 1,
                correct_count = m.correct_count + EXCLUDED.correct_count,
                mastery_level = LEAST(10, GREATEST(1,
                    floor(((m.correct_count + EXCLUDED.correct_count)::numeric
                        / NULLIF(m.total_answered + 1, 0)) * 10)::integer + 1)),
                updated_at = now();
        END IF;
    END LOOP;

    IF v_session.mode = 'daily' THEN
        v_play_date := (COALESCE(v_session.submitted_at, now())
            AT TIME ZONE 'America/Chicago')::date;
        SELECT COALESCE(current_streak, 0) INTO v_streak
          FROM public.trivia_streaks
         WHERE user_id = v_session.user_id;

        INSERT INTO public.daily_trivia_plays AS d
            (user_id, played_date, was_correct, streak_at_time, created_at)
        VALUES
            (v_session.user_id, v_play_date, v_correct > 0, v_streak, now())
        ON CONFLICT (user_id, played_date) DO UPDATE SET
            was_correct = d.was_correct OR EXCLUDED.was_correct,
            streak_at_time = GREATEST(COALESCE(d.streak_at_time, 0), EXCLUDED.streak_at_time);
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'deduped', false,
        'answered', v_answered,
        'correct', v_correct,
        'skipped', v_skipped
    );
END;
$_$;


ALTER FUNCTION public.finalize_trivia_session_stats_v3(p_session_id uuid) OWNER TO postgres;

--
-- Name: finalize_vip_subscription_admission(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finalize_vip_subscription_admission(p_user_id uuid, p_stripe_subscription_id text, p_request_id text, p_intent_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_claim public.vip_subscription_checkout_claims%ROWTYPE;
  v_subscription public.vip_subscriptions%ROWTYPE;
BEGIN
  IF p_user_id IS NULL
     OR p_stripe_subscription_id IS NULL
     OR btrim(p_stripe_subscription_id) = ''
     OR length(p_stripe_subscription_id) > 255
     OR p_request_id IS NULL
     OR btrim(p_request_id) = ''
     OR length(p_request_id) > 200
     OR p_intent_hash IS NULL
     OR p_intent_hash !~ '^[a-f0-9]{64}$' THEN
    RETURN jsonb_build_object(
      'success', false,
      'finalized', false,
      'state', 'invalid'
    );
  END IF;

  PERFORM 1
    FROM public.profiles
   WHERE id = p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'finalized', false,
      'state', 'profile_not_found'
    );
  END IF;

  SELECT * INTO v_claim
    FROM public.vip_subscription_checkout_claims
   WHERE user_id = p_user_id
   FOR UPDATE;

  SELECT * INTO v_subscription
    FROM public.vip_subscriptions
   WHERE stripe_subscription_id = p_stripe_subscription_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'finalized', false,
      'state', 'subscription_missing'
    );
  END IF;
  IF v_subscription.user_id IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object(
      'success', false,
      'finalized', false,
      'state', 'subscription_conflict'
    );
  END IF;

  IF v_claim.user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'finalized', false,
      'state', 'replay',
      'stripe_subscription_id', p_stripe_subscription_id
    );
  END IF;
  IF v_claim.request_id <> p_request_id
     OR v_claim.intent_hash <> p_intent_hash THEN
    RETURN jsonb_build_object(
      'success', false,
      'finalized', false,
      'state', 'claim_conflict'
    );
  END IF;
  IF v_claim.state <> 'admitting' THEN
    RETURN jsonb_build_object(
      'success', false,
      'finalized', false,
      'state', 'claim_state_conflict'
    );
  END IF;

  DELETE FROM public.vip_subscription_checkout_claims
   WHERE user_id = p_user_id
     AND request_id = p_request_id
     AND intent_hash = p_intent_hash
     AND state = 'admitting';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'VIP subscription admission barrier disappeared while locked';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'finalized', true,
    'state', 'finalized',
    'stripe_subscription_id', p_stripe_subscription_id
  );
END;
$_$;


ALTER FUNCTION public.finalize_vip_subscription_admission(p_user_id uuid, p_stripe_subscription_id text, p_request_id text, p_intent_hash text) OWNER TO postgres;

--
-- Name: FUNCTION finalize_vip_subscription_admission(p_user_id uuid, p_stripe_subscription_id text, p_request_id text, p_intent_hash text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.finalize_vip_subscription_admission(p_user_id uuid, p_stripe_subscription_id text, p_request_id text, p_intent_hash text) IS 'marketplace_phase7_vip_acquisition_mutex:v1';


--
-- Name: find_live_games_nearby(double precision, double precision, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_live_games_nearby(p_lat double precision, p_lng double precision, p_radius_miles numeric DEFAULT 50, p_game_type text DEFAULT NULL::text, p_stakes text DEFAULT NULL::text) RETURNS TABLE(id uuid, venue_id integer, venue_name text, venue_city text, venue_state text, distance_miles numeric, game_type text, stakes text, seats_open integer, waitlist_size integer, table_count integer, wait_time integer, notes text, game_quality text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_radius numeric;
BEGIN
  IF p_lat IS NULL OR p_lng IS NULL THEN
    RETURN;
  END IF;

  -- Clamp radius: 1mi floor, 250mi ceiling.
  v_radius := GREATEST(1, LEAST(250, COALESCE(p_radius_miles, 50)));

  RETURN QUERY
  SELECT
    lg.id,
    lg.venue_id,
    pv.name AS venue_name,
    pv.city AS venue_city,
    pv.state AS venue_state,
    -- Haversine in miles. 3958.8 = Earth radius in miles.
    ROUND((3958.8 * 2 * asin(
      sqrt(
        sin(radians((COALESCE(pv.lat, pv.latitude) - p_lat) / 2)) ^ 2
        + cos(radians(p_lat)) * cos(radians(COALESCE(pv.lat, pv.latitude)))
        * sin(radians((COALESCE(pv.lng, pv.longitude) - p_lng) / 2)) ^ 2
      )
    ))::numeric, 2) AS distance_miles,
    lg.game_type,
    lg.stakes,
    NULL::integer AS seats_open,        -- not stored on live_games
    NULL::integer AS waitlist_size,     -- not stored on live_games
    lg.table_count,
    lg.wait_time,
    lg.notes,
    lg.game_quality,
    lg.created_at
  FROM public.live_games lg
  JOIN public.poker_venues pv ON pv.id = lg.venue_id
  WHERE lg.is_active = true
    AND lg.expires_at > now()
    AND COALESCE(pv.lat, pv.latitude) IS NOT NULL
    AND COALESCE(pv.lng, pv.longitude) IS NOT NULL
    AND (p_game_type IS NULL OR lg.game_type = p_game_type)
    AND (p_stakes IS NULL OR lg.stakes = p_stakes)
    AND (3958.8 * 2 * asin(
      sqrt(
        sin(radians((COALESCE(pv.lat, pv.latitude) - p_lat) / 2)) ^ 2
        + cos(radians(p_lat)) * cos(radians(COALESCE(pv.lat, pv.latitude)))
        * sin(radians((COALESCE(pv.lng, pv.longitude) - p_lng) / 2)) ^ 2
      )
    )) <= v_radius
  ORDER BY distance_miles ASC
  LIMIT 200;
END;
$$;


ALTER FUNCTION public.find_live_games_nearby(p_lat double precision, p_lng double precision, p_radius_miles numeric, p_game_type text, p_stakes text) OWNER TO postgres;

--
-- Name: find_similar_questions(text, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_similar_questions(search_query text, similarity_threshold numeric DEFAULT 0.3, max_results integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer;
  v_query text;
  v_result jsonb;
BEGIN
  IF search_query IS NULL OR length(search_query) < 3 THEN
    RETURN '[]'::jsonb;
  END IF;
  v_limit := GREATEST(1, LEAST(50, COALESCE(max_results, 5)));
  v_query := '%' || lower(search_query) || '%';

  SELECT COALESCE(jsonb_agg(row_to_json(q)::jsonb), '[]'::jsonb) INTO v_result
  FROM (
    SELECT
      tq.id,
      tq.scenario_text,
      tq.gto_action,
      tq.gto_explanation,
      tq.game_type,
      tq.difficulty,
      tq.created_at
    FROM public.training_questions tq
    WHERE lower(tq.scenario_text) LIKE v_query
       OR lower(COALESCE(tq.gto_explanation, '')) LIKE v_query
    ORDER BY tq.created_at DESC
    LIMIT v_limit
  ) q;

  RETURN COALESCE(v_result, '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'find_similar_questions failed (q=%): % %', search_query, SQLERRM, SQLSTATE;
  RETURN '[]'::jsonb;
END;
$$;


ALTER FUNCTION public.find_similar_questions(search_query text, similarity_threshold numeric, max_results integer) OWNER TO postgres;

--
-- Name: flag_venue_review(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.flag_venue_review(p_review_id uuid, p_caller_user_id uuid, p_reason text, p_detail text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_review RECORD; v_id uuid; v_recent int; v_is_own boolean;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    IF p_reason NOT IN ('spam','harassment','fake','off_topic','hate_speech','inaccurate','other')
    THEN RAISE EXCEPTION 'INVALID_REASON'; END IF;

    SELECT id, reviewer_id INTO v_review FROM commander_venue_reviews WHERE id = p_review_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'REVIEW_NOT_FOUND'; END IF;
    IF v_review.reviewer_id = p_caller_user_id THEN RAISE EXCEPTION 'CANNOT_FLAG_OWN_REVIEW'; END IF;

    -- Rate limit: 10 flags per 24h per user
    SELECT COUNT(*) INTO v_recent FROM commander_venue_review_flags 
     WHERE flagger_id = p_caller_user_id AND created_at > NOW() - INTERVAL '24 hours';
    IF v_recent >= 10 THEN RAISE EXCEPTION 'RATE_LIMITED'; END IF;

    INSERT INTO commander_venue_review_flags (review_id, flagger_id, reason, detail)
    VALUES (p_review_id, p_caller_user_id, p_reason, p_detail)
    ON CONFLICT (review_id, flagger_id) DO UPDATE SET reason = EXCLUDED.reason, detail = EXCLUDED.detail
    RETURNING id INTO v_id;

    -- Auto-flag review for moderator attention if it hits 3+ distinct flaggers
    IF (SELECT COUNT(*) FROM commander_venue_review_flags 
         WHERE review_id = p_review_id AND status = 'pending') >= 3 THEN
        UPDATE commander_venue_reviews SET is_published = false WHERE id = p_review_id;
    END IF;

    RETURN jsonb_build_object('success', true, 'flag_id', v_id);
END; $$;


ALTER FUNCTION public.flag_venue_review(p_review_id uuid, p_caller_user_id uuid, p_reason text, p_detail text) OWNER TO postgres;

--
-- Name: FUNCTION flag_venue_review(p_review_id uuid, p_caller_user_id uuid, p_reason text, p_detail text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.flag_venue_review(p_review_id uuid, p_caller_user_id uuid, p_reason text, p_detail text) IS 'Phase 27/C: Flag a review for moderation. Auto-unpublishes review at 3+ pending flags.';


--
-- Name: fn_a_benched_horse_stays_benched(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_a_benched_horse_stays_benched() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.horse_status = 'disabled'
     AND NEW.horse_status IS DISTINCT FROM 'disabled'
     AND COALESCE(current_setting('app.horse_release', true), '') <> 'on'
  THEN
    NEW.horse_status := 'disabled';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_a_benched_horse_stays_benched() OWNER TO postgres;

--
-- Name: fn_accept_friend_request(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_accept_friend_request(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_sender UUID;
    v_recipient UUID;
BEGIN
    SELECT sender_id, recipient_id INTO v_sender, v_recipient
    FROM friend_requests WHERE id = p_request_id;
    
    UPDATE friend_requests SET status = 'accepted', updated_at = NOW() WHERE id = p_request_id;
    
    INSERT INTO friendships (user_id, friend_id) VALUES (v_sender, v_recipient);
    INSERT INTO friendships (user_id, friend_id) VALUES (v_recipient, v_sender);
END;
$$;


ALTER FUNCTION public.fn_accept_friend_request(p_request_id uuid) OWNER TO postgres;

--
-- Name: fn_achievement_record_progress(uuid, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_achievement_record_progress(p_user_id uuid, p_achievement_id text, p_progress numeric, p_target numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller       uuid := auth.uid();
  v_target       numeric := GREATEST(COALESCE(p_target, 1), 1);
  v_was_unlocked boolean;
  v_now_unlocked boolean;
BEGIN
  IF p_user_id IS NULL OR p_achievement_id IS NULL THEN
    RETURN false;
  END IF;

  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'fn_achievement_record_progress: a caller without a session cannot write achievements';
  END IF;

  IF v_caller <> p_user_id THEN
    RAISE EXCEPTION 'fn_achievement_record_progress: refusing to write achievements for another user';
  END IF;

  SELECT (unlocked_at IS NOT NULL) INTO v_was_unlocked
    FROM public.training_user_achievements
   WHERE user_id = p_user_id AND achievement_id = p_achievement_id;

  INSERT INTO public.training_user_achievements
              (user_id, achievement_id, progress, target, unlocked_at, unlocked)
       VALUES (p_user_id, p_achievement_id,
               LEAST(GREATEST(COALESCE(p_progress, 0), 0), v_target),
               v_target,
               CASE WHEN COALESCE(p_progress, 0) >= v_target THEN now() ELSE NULL END,
               COALESCE(p_progress, 0) >= v_target)
  ON CONFLICT (user_id, achievement_id) DO UPDATE
     SET progress    = LEAST(GREATEST(public.training_user_achievements.progress,
                                      COALESCE(EXCLUDED.progress, 0)), v_target),
         target      = v_target,
         unlocked_at = COALESCE(
                         public.training_user_achievements.unlocked_at,
                         CASE WHEN LEAST(GREATEST(public.training_user_achievements.progress,
                                                  COALESCE(EXCLUDED.progress, 0)), v_target) >= v_target
                              THEN now() END),
         unlocked    = COALESCE(
                         public.training_user_achievements.unlocked_at,
                         CASE WHEN LEAST(GREATEST(public.training_user_achievements.progress,
                                                  COALESCE(EXCLUDED.progress, 0)), v_target) >= v_target
                              THEN now() END) IS NOT NULL
  RETURNING unlocked INTO v_now_unlocked;

  RETURN COALESCE(v_now_unlocked, false) AND NOT COALESCE(v_was_unlocked, false);
END $$;


ALTER FUNCTION public.fn_achievement_record_progress(p_user_id uuid, p_achievement_id text, p_progress numeric, p_target numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_achievement_record_progress(p_user_id uuid, p_achievement_id text, p_progress numeric, p_target numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_achievement_record_progress(p_user_id uuid, p_achievement_id text, p_progress numeric, p_target numeric) IS 'Records achievement progress for the CALLING user. Requires a session: a NULL auth.uid() is refused, not exempted (the pre-2026-08-30 guard skipped itself for anon, so a logged-out caller could write any user''s achievements). anon has no EXECUTE. Called from src/services/AchievementService.ts.';


