--
-- Name: fn_ack_tournament_capacity_tables(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ack_tournament_capacity_tables(p_tournament_id uuid, p_table_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ids uuid[];
  v_found integer;
  v_changed integer;
BEGIN
  SELECT array_agg(DISTINCT requested.table_id ORDER BY requested.table_id)
    INTO v_ids
    FROM unnest(p_table_ids) AS requested(table_id)
   WHERE requested.table_id IS NOT NULL;
  IF p_tournament_id IS NULL OR p_table_ids IS NULL OR v_ids IS NULL
     OR cardinality(v_ids)<>cardinality(p_table_ids)
     OR cardinality(v_ids)>20 THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_exact_table_set');
  END IF;

  PERFORM 1
    FROM public.tournament_capacity_table_receipts r
   WHERE r.table_id=ANY(v_ids)
   ORDER BY r.table_id
   FOR UPDATE;
  SELECT count(*)::integer INTO v_found
    FROM public.tournament_capacity_table_receipts r
   WHERE r.table_id=ANY(v_ids) AND r.tournament_id=p_tournament_id;
  IF v_found<>cardinality(v_ids) THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','table_receipt_or_tournament_mismatch');
  END IF;

  UPDATE public.tournament_capacity_table_receipts r
     SET manager_admitted_at=COALESCE(r.manager_admitted_at,clock_timestamp()),
         updated_at=clock_timestamp()
   WHERE r.table_id=ANY(v_ids) AND r.tournament_id=p_tournament_id
     AND r.manager_admitted_at IS NULL;
  GET DIAGNOSTICS v_changed=ROW_COUNT;
  RETURN jsonb_build_object(
    'ok',true,'requested',cardinality(v_ids),'newly_admitted',v_changed);
END;
$$;


ALTER FUNCTION public.fn_ack_tournament_capacity_tables(p_tournament_id uuid, p_table_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_ack_tournament_manager_wakes(uuid, bigint[], bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ack_tournament_manager_wakes(p_tournament_id uuid, p_wake_ids bigint[], p_wake_generations bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ids bigint[];
  v_found integer;
  v_changed integer;
  v_current_receipts jsonb;
BEGIN
  SELECT array_agg(DISTINCT id ORDER BY id)
    INTO v_ids
    FROM unnest(p_wake_ids) id
   WHERE id>0;
  IF p_tournament_id IS NULL OR v_ids IS NULL
     OR cardinality(v_ids)<>cardinality(p_wake_ids)
     OR p_wake_generations IS NULL
     OR cardinality(p_wake_generations)<>cardinality(p_wake_ids)
     OR EXISTS (
       SELECT 1 FROM unnest(p_wake_generations) generation
        WHERE generation IS NULL OR generation<=0
     )
     OR cardinality(v_ids)>200 THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_exact_wake_set');
  END IF;

  -- Lock and verify every exact id before acknowledging any. A global
  -- identity value says nothing about commit order, so no range predicate is
  -- permitted at this boundary.
  PERFORM 1
    FROM public.tournament_manager_wakes w
   WHERE w.id=ANY(v_ids)
   ORDER BY w.id
   FOR UPDATE;
  SELECT count(*) INTO v_found
    FROM public.tournament_manager_wakes w
   WHERE w.id=ANY(v_ids) AND w.tournament_id=p_tournament_id;
  IF v_found<>cardinality(v_ids) THEN
    RETURN jsonb_build_object('ok',false,'reason','wake_identity_or_tournament_mismatch');
  END IF;

  UPDATE public.tournament_manager_wakes w
     SET consumed_at=coalesce(w.consumed_at,clock_timestamp())
    FROM unnest(p_wake_ids,p_wake_generations) requested(id,generation)
   WHERE w.id=requested.id AND w.tournament_id=p_tournament_id
     AND w.generation=requested.generation AND w.consumed_at IS NULL;
  GET DIAGNOSTICS v_changed=ROW_COUNT;

  -- Return the post-lock generation of every exact identity. A signal that
  -- arrived while the manager's sweep was in flight increments generation and
  -- remains unconsumed; the manager must run that newer generation before it
  -- may delete the local receipt.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id',w.id,
           'generation',w.generation,
           'consumed',w.consumed_at IS NOT NULL
         ) ORDER BY w.id),'[]'::jsonb)
    INTO v_current_receipts
    FROM public.tournament_manager_wakes w
   WHERE w.id=ANY(v_ids) AND w.tournament_id=p_tournament_id;
  RETURN jsonb_build_object(
    'ok',true,
    'requested',cardinality(v_ids),
    'newly_acknowledged',v_changed,
    'current_receipts',v_current_receipts);
END;
$$;


ALTER FUNCTION public.fn_ack_tournament_manager_wakes(p_tournament_id uuid, p_wake_ids bigint[], p_wake_generations bigint[]) OWNER TO postgres;

--
-- Name: fn_action_player_report(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_action_player_report(p_report_id uuid, p_status text, p_admin_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reported uuid;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication required'); END IF;
  IF p_status NOT IN ('actioned','dismissed','reviewed','pending') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid status'); END IF;

  SELECT reported_user_id INTO v_reported FROM user_reports WHERE id = p_report_id;
  IF v_reported IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'report not found'); END IF;

  IF NOT public.fn_caller_can_moderate_user(v_reported) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authorized to review this report'); END IF;

  UPDATE user_reports SET
    status = p_status,
    admin_notes = p_admin_notes,
    reviewed_by = (SELECT auth.uid()),
    reviewed_at = now()
  WHERE id = p_report_id;

  RETURN jsonb_build_object('success', true, 'report_id', p_report_id, 'status', p_status);
END;
$$;


ALTER FUNCTION public.fn_action_player_report(p_report_id uuid, p_status text, p_admin_notes text) OWNER TO postgres;

--
-- Name: fn_active_maintenance_release_boundary(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_active_maintenance_release_boundary() RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  c_required_steps CONSTANT text[] := ARRAY[
    'sit_out_at','hold_expires_at','addon_period_ends_at','reversible_until',
    'reveal_deadline_at','rebuy_prompt_until','bomb_pot_next_due_at',
    'cash_stay_last_tick_at','cash_rejoin_expires_at','level_started_at',
    'cluster_break_eligible_since','cluster_move_expires_at',
    'reconnect_presence','reconnect_snapshots'
  ];
  v_request_role text := NULLIF(btrim(COALESCE(auth.role(), '')), '');
  v_trusted_database_actor boolean;
  v_release_target timestamptz;
BEGIN
  SELECT session_user IN ('postgres', 'supabase_admin', 'service_role')
         OR COALESCE(r.rolsuper, false)
    INTO v_trusted_database_actor
    FROM (SELECT session_user AS role_name) s
    LEFT JOIN pg_catalog.pg_roles r ON r.rolname = s.role_name;

  IF v_request_role IS NOT NULL
     AND v_request_role NOT IN ('anon', 'authenticated', 'service_role') THEN
    RAISE EXCEPTION 'MAINTENANCE_RELEASE_CERTIFICATE_CALLER_REFUSED'
      USING ERRCODE = '42501';
  END IF;
  IF v_request_role IS NULL AND NOT COALESCE(v_trusted_database_actor, false) THEN
    RAISE EXCEPTION 'MAINTENANCE_RELEASE_CERTIFICATE_CALLER_REQUIRED'
      USING ERRCODE = '42501';
  END IF;

  SELECT max(t.release_target_at) INTO v_release_target
    FROM public.engine_maintenance_thaws t
   WHERE t.contract_version = 3
     AND t.release_target_at > clock_timestamp()
     AND COALESCE((t.shifted->>'complete')::boolean, false)
     AND t.shifted ?& c_required_steps;
  RETURN v_release_target;
END;
$$;


ALTER FUNCTION public.fn_active_maintenance_release_boundary() OWNER TO postgres;

--
-- Name: fn_actor_can_manage_club_treasury(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_actor_can_manage_club_treasury(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    -- Backend / service-role context (no end-user JWT): trusted, allow.
    auth.uid() IS NULL
    OR EXISTS (SELECT 1 FROM public.clubs c
               WHERE c.id = p_club_id AND c.owner_id = auth.uid())
    OR EXISTS (SELECT 1 FROM public.club_members cm
               WHERE cm.club_id = p_club_id
                 AND cm.user_id = auth.uid()
                 AND cm.role IN ('owner','co_owner','admin','manager','super_agent','treasurer'))
    OR EXISTS (SELECT 1 FROM public.agents a
               WHERE a.club_id = p_club_id
                 AND a.user_id = auth.uid()
                 AND a.role IN ('owner','co_owner','admin','manager','super_agent'));
$$;


ALTER FUNCTION public.fn_actor_can_manage_club_treasury(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_ad_campaign_list(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ad_campaign_list(p_club_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, club_id uuid, club_name text, name text, slot text, status text, display_status text, scope text, starts_at timestamp with time zone, ends_at timestamp with time zone, days integer, image_url text, target_url text, headline text, diamonds_charged integer, diamonds_refunded integer, submitted_by uuid, reviewed_at timestamp with time zone, review_note text, created_at timestamp with time zone, impressions bigint, viewable bigint, clicks bigint, viewers bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT c.id, c.club_id, cl.name AS club_name, c.name, c.slot, c.status,
         CASE
           WHEN c.status <> 'approved' THEN c.status
           WHEN now() < c.starts_at THEN 'scheduled'
           WHEN now() >= c.ends_at  THEN 'finished'
           ELSE 'live'
         END AS display_status,
         c.scope, c.starts_at, c.ends_at, c.days,
         c.image_url, c.target_url, c.headline,
         c.diamonds_charged, c.diamonds_refunded,
         c.submitted_by, c.reviewed_at, c.review_note, c.created_at,
         COALESCE(s.impressions, 0), COALESCE(s.viewable, 0), COALESCE(s.clicks, 0), COALESCE(s.viewers, 0)
    FROM public.ad_campaign c
    JOIN public.clubs cl ON cl.id = c.club_id
    LEFT JOIN LATERAL (
      SELECT count(*) FILTER (WHERE e.event_type = 'impression') AS impressions,
             count(*) FILTER (WHERE e.event_type = 'viewable')   AS viewable,
             count(*) FILTER (WHERE e.event_type = 'click')      AS clicks,
             count(DISTINCT e.user_id) FILTER (WHERE e.event_type = 'impression') AS viewers
        FROM public.ad_event e
       WHERE e.ad_id = c.ad_id
    ) s ON true
   WHERE (
           (p_club_id IS NOT NULL AND c.club_id = p_club_id AND public.fn_club_is_staff(p_club_id, auth.uid()))
        OR (p_club_id IS NULL AND (COALESCE(auth.role(), '') = 'service_role' OR public.fn_is_platform_admin()))
         )
   ORDER BY c.created_at DESC
   LIMIT 200;
$$;


ALTER FUNCTION public.fn_ad_campaign_list(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_ad_campaign_review(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ad_campaign_review(p_campaign_id uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_c    public.ad_campaign%rowtype;
  v_ad   uuid;
  v_ref  jsonb;
BEGIN
  IF NOT (COALESCE(auth.role(), '') = 'service_role' OR public.fn_is_platform_admin()) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_platform_admin');
  END IF;
  IF p_decision NOT IN ('approve', 'reject') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bad_decision');
  END IF;
  SELECT * INTO v_c FROM public.ad_campaign WHERE id = p_campaign_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;
  IF v_c.status <> 'submitted' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_reviewed', 'status', v_c.status);
  END IF;
  IF p_decision = 'reject' THEN
    v_ref := public.add_diamonds_to_balance(
      v_c.submitted_by, v_c.diamonds_charged, 'refund',
      'Club advert not approved: ' || v_c.name,
      'adcamp-refund:' || v_c.id::text
    );
    IF COALESCE((v_ref->>'success')::boolean, false) IS NOT TRUE
       AND COALESCE((v_ref->>'duplicate')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'refund failed: %', v_ref->>'error';
    END IF;
    UPDATE public.ad_campaign
       SET status = 'rejected', diamonds_refunded = diamonds_charged,
           reviewed_by = v_user, reviewed_at = now(), review_note = p_note, updated_at = now()
     WHERE id = p_campaign_id;
    RETURN jsonb_build_object('ok', true, 'status', 'rejected', 'diamonds_refunded', v_c.diamonds_charged);
  END IF;
  INSERT INTO public.ad_catalog
    (ad_key, category, headline, body, glyph, target_url, cta_label, is_active,
     starts_at, ends_at, weight, created_by, image_url, advertiser_id, campaign_id, priority)
  VALUES
    ('camp_' || replace(v_c.id::text, '-', ''), 'club', v_c.headline, NULL, NULL,
     v_c.target_url, NULL, true,
     v_c.starts_at, v_c.ends_at, 100, v_user, v_c.image_url, v_c.advertiser_id, v_c.id, v_c.priority)
  RETURNING id INTO v_ad;
  INSERT INTO public.ad_placement (ad_id, slot, club_id, audience, daily_cap, is_active, image_url)
  VALUES (v_ad, v_c.slot,
          CASE WHEN v_c.scope = 'own_club' THEN v_c.club_id ELSE NULL END,
          'all', NULL, true, v_c.image_url);
  UPDATE public.ad_campaign
     SET status = 'approved', ad_id = v_ad,
         reviewed_by = v_user, reviewed_at = now(), review_note = p_note, updated_at = now()
   WHERE id = p_campaign_id;
  RETURN jsonb_build_object('ok', true, 'status', 'approved', 'ad_id', v_ad);
END;
$$;


ALTER FUNCTION public.fn_ad_campaign_review(p_campaign_id uuid, p_decision text, p_note text) OWNER TO postgres;

--
-- Name: fn_ad_conversions(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ad_conversions(p_window_hours integer DEFAULT 24) RETURNS TABLE(ad_id uuid, ad_key text, slot text, clicks bigint, clicks_followed_by bigint, conversion_rule text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH w AS (
    SELECT make_interval(hours => GREATEST(1, LEAST(COALESCE(p_window_hours, 24), 720))) AS span
  ),
  clicks AS (
    SELECT e.id, e.ad_id, e.slot, e.user_id, e.created_at, c.ad_key
      FROM public.ad_event e
      JOIN public.ad_catalog c ON c.id = e.ad_id
     WHERE e.event_type = 'click'
       AND e.user_id IS NOT NULL
  ),
  followed AS (
    SELECT k.id FROM clicks k, w
     WHERE k.ad_key = 'vip_upsell'
       AND EXISTS (SELECT 1 FROM public.vip_subscriptions v
                    WHERE v.user_id = k.user_id
                      AND v.created_at >= k.created_at
                      AND v.created_at <  k.created_at + w.span)
    UNION
    SELECT k.id FROM clicks k, w
     WHERE k.ad_key = 'diamonds_store'
       AND EXISTS (SELECT 1 FROM public.diamond_purchases d
                    WHERE d.user_id = k.user_id
                      AND d.completed_at IS NOT NULL
                      AND d.completed_at >= k.created_at
                      AND d.completed_at <  k.created_at + w.span)
    UNION
    SELECT k.id FROM clicks k, w
     WHERE k.ad_key = 'referral_invite'
       AND EXISTS (SELECT 1 FROM public.referrals r
                    WHERE r.referrer_id = k.user_id
                      AND r.created_at >= k.created_at
                      AND r.created_at <  k.created_at + w.span)
    UNION
    SELECT k.id FROM clicks k, w
     WHERE k.ad_key = 'tournaments_daily'
       AND EXISTS (SELECT 1 FROM public.tournament_registrations tr
                    JOIN public.tournaments t ON t.id = tr.tournament_id
                   WHERE tr.user_id = k.user_id
                     AND t.tournament_type = 'MTT'
                     AND tr.registered_at >= k.created_at
                     AND tr.registered_at <  k.created_at + w.span)
    UNION
    SELECT k.id FROM clicks k, w
     WHERE k.ad_key = 'spins_jackpot'
       AND EXISTS (SELECT 1 FROM public.tournament_registrations tr
                    JOIN public.tournaments t ON t.id = tr.tournament_id
                   WHERE tr.user_id = k.user_id
                     AND t.tournament_type = 'SPIN'
                     AND tr.registered_at >= k.created_at
                     AND tr.registered_at <  k.created_at + w.span)
  )
  SELECT k.ad_id,
         k.ad_key,
         k.slot,
         count(*) AS clicks,
         CASE WHEN k.ad_key IN ('vip_upsell','diamonds_store','referral_invite',
                                'tournaments_daily','spins_jackpot')
              THEN count(*) FILTER (WHERE k.id IN (SELECT f.id FROM followed f))
              ELSE NULL END AS clicks_followed_by,
         CASE k.ad_key
           WHEN 'vip_upsell'        THEN 'A VIP subscription started'
           WHEN 'diamonds_store'    THEN 'A diamond purchase completed'
           WHEN 'referral_invite'   THEN 'Somebody used their referral code'
           WHEN 'tournaments_daily' THEN 'They registered for an MTT'
           WHEN 'spins_jackpot'     THEN 'They registered for a Spin'
           ELSE NULL
         END AS conversion_rule
    FROM clicks k
   GROUP BY k.ad_id, k.ad_key, k.slot;
$$;


ALTER FUNCTION public.fn_ad_conversions(p_window_hours integer) OWNER TO postgres;

--
-- Name: fn_ad_daily(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ad_daily(p_days integer DEFAULT 30) RETURNS TABLE(ad_id uuid, slot text, day date, impressions bigint, clicks bigint, viewers bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT e.ad_id,
         e.slot,
         (e.created_at AT TIME ZONE 'UTC')::date AS day,
         count(*) FILTER (WHERE e.event_type = 'impression') AS impressions,
         count(*) FILTER (WHERE e.event_type = 'click')      AS clicks,
         count(DISTINCT e.user_id) FILTER (WHERE e.event_type = 'impression') AS viewers
    FROM public.ad_event e
   WHERE e.created_at >= now() - make_interval(days => GREATEST(1, LEAST(COALESCE(p_days, 30), 365)))
   GROUP BY e.ad_id, e.slot, (e.created_at AT TIME ZONE 'UTC')::date;
$$;


ALTER FUNCTION public.fn_ad_daily(p_days integer) OWNER TO postgres;

--
-- Name: fn_ad_retention_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ad_retention_status() RETURNS TABLE(retention_days integer, cutoff timestamp with time zone, total_events bigint, prunable_events bigint, oldest_event timestamp with time zone, newest_event timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select
    p.event_retention_days,
    now() - make_interval(days => p.event_retention_days),
    count(e.id),
    count(e.id) filter (
      where e.created_at < now() - make_interval(days => p.event_retention_days)
    ),
    min(e.created_at),
    max(e.created_at)
  from public.ad_event_retention_policy p
  left join public.ad_event e on true
  group by p.event_retention_days;
$$;


ALTER FUNCTION public.fn_ad_retention_status() OWNER TO postgres;

--
-- Name: FUNCTION fn_ad_retention_status(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ad_retention_status() IS 'Read-only preview for the house-ads retention card: what the policy is, where the cutoff falls, and exactly how many ad_event rows fn_prune_ad_events() would delete. Counts server-side because the reason a retention screen exists is that the table is too large to fetch.';


--
-- Name: fn_ad_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ad_stats() RETURNS TABLE(ad_id uuid, slot text, impressions bigint, clicks bigint, dismisses bigint, viewers bigint, clickers bigint, last_event_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT e.ad_id,
         e.slot,
         count(*) FILTER (WHERE e.event_type = 'impression') AS impressions,
         count(*) FILTER (WHERE e.event_type = 'click')      AS clicks,
         count(*) FILTER (WHERE e.event_type = 'dismiss')    AS dismisses,
         count(DISTINCT e.user_id) FILTER (WHERE e.event_type = 'impression') AS viewers,
         count(DISTINCT e.user_id) FILTER (WHERE e.event_type = 'click')      AS clickers,
         max(e.created_at)                                   AS last_event_at
    FROM public.ad_event e
   GROUP BY e.ad_id, e.slot;
$$;


ALTER FUNCTION public.fn_ad_stats() OWNER TO postgres;

--
-- Name: fn_ad_suppression(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ad_suppression() RETURNS TABLE(ad_id uuid, slot text, daily_cap integer, served_users_24h bigint, capped_users_24h bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH per_user AS (
    SELECT e.ad_id, e.slot, e.user_id, count(*) AS impressions
      FROM public.ad_event e
     WHERE e.event_type = 'impression'
       AND e.created_at > now() - interval '24 hours'
       AND e.user_id IS NOT NULL
     GROUP BY e.ad_id, e.slot, e.user_id
  )
  SELECT pl.ad_id,
         pl.slot,
         pl.daily_cap,
         COALESCE(count(pu.user_id), 0) AS served_users_24h,
         COALESCE(count(pu.user_id) FILTER (
           WHERE pl.daily_cap IS NOT NULL AND pu.impressions >= pl.daily_cap
         ), 0) AS capped_users_24h
    FROM public.ad_placement pl
    LEFT JOIN per_user pu
           ON pu.ad_id = pl.ad_id AND pu.slot = pl.slot
   WHERE pl.is_active
   GROUP BY pl.ad_id, pl.slot, pl.daily_cap;
$$;


ALTER FUNCTION public.fn_ad_suppression() OWNER TO postgres;

