-- Name: fn_add_chips(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_add_chips(p_user_id uuid, p_club_id uuid, p_amount numeric) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    UPDATE club_members 
    SET chip_balance = chip_balance + p_amount
    WHERE club_id = p_club_id 
      AND user_id = p_user_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Club member not found';
    END IF;
END;
$$;


