--
-- Name: fn_admin_close_table(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_admin_close_table(p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid       uuid := auth.uid();
  v_club      uuid;
  v_seat      record;
  v_refunded  integer := 0;
  v_total     numeric := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_admin_close_table requires an authenticated caller'
      USING ERRCODE = '28000';
  END IF;

  SELECT club_id INTO v_club FROM public.tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;

  IF NOT public.is_club_admin(v_club) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  FOR v_seat IN
    SELECT id, user_id, stack
    FROM public.table_seats
    WHERE table_id = p_table_id AND left_at IS NULL AND COALESCE(stack, 0) > 0
    ORDER BY seat_number
    FOR UPDATE
  LOOP
    IF NOT public.atomic_credit_wallet_and_log(
         v_seat.user_id,
         v_seat.stack,
         'cashout',
         'Table closed: ' || v_seat.stack::text || ' chips returned',
         p_table_id,
         NULL,
         NULL,
         'cashout:' || v_seat.id::text
       ) THEN
      RAISE EXCEPTION 'fn_admin_close_table: credit failed for seat %', v_seat.id
        USING ERRCODE = '25000';
    END IF;

    v_refunded := v_refunded + 1;
    v_total := v_total + v_seat.stack;
  END LOOP;

  UPDATE public.table_seats
     SET left_at = now()
   WHERE table_id = p_table_id AND left_at IS NULL;

  UPDATE public.tables
     SET status = 'closed', current_players = 0, updated_at = now()
   WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'ok', true, 'players_refunded', v_refunded, 'chips_refunded', v_total);
END;
$$;


ALTER FUNCTION public.fn_admin_close_table(p_table_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_admin_close_table(p_table_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_admin_close_table(p_table_id uuid) IS 'AUDIT M17: club-admin table close. Refunds every seated player their actual stack and closes the table in one transaction.';


--
-- Name: fn_admin_holds_no_player_wallet(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_admin_holds_no_player_wallet() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_is_union boolean;
BEGIN
  IF COALESCE(NEW.role, 'player') <> 'admin' THEN RETURN NEW; END IF;

  SELECT COALESCE(c.is_union, false) INTO v_is_union FROM public.clubs c WHERE c.id = NEW.club_id;
  IF COALESCE(v_is_union, false) THEN RETURN NEW; END IF;

  IF TG_OP = 'UPDATE' AND OLD.role IS DISTINCT FROM NEW.role
     AND (COALESCE(NEW.chip_balance, 0) <> 0
          OR COALESCE(NEW.locked_chips, 0) <> 0
          OR COALESCE(NEW.held_chips, 0) <> 0
          OR COALESCE(NEW.promo_balance, 0) <> 0) THEN
    RAISE EXCEPTION 'Cash Out The Player Wallet Before Making This Member An Admin'
      USING ERRCODE = 'check_violation',
            DETAIL = format('chip_balance %s, locked %s, held %s, promo %s',
                            COALESCE(NEW.chip_balance, 0), COALESCE(NEW.locked_chips, 0),
                            COALESCE(NEW.held_chips, 0), COALESCE(NEW.promo_balance, 0));
  END IF;

  IF COALESCE(NEW.chip_balance, 0) > 0
     AND (TG_OP = 'INSERT' OR COALESCE(NEW.chip_balance, 0) > COALESCE(OLD.chip_balance, 0)) THEN
    RAISE EXCEPTION 'An Admin Does Not Hold A Player Wallet'
      USING ERRCODE = 'check_violation',
            HINT = 'Send To The Agent Wallet Or The Club Bank Instead.';
  END IF;

  RETURN NEW;
END;
$$;


