--
-- Name: fn_admin_platform_aggregates(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_admin_platform_aggregates(p_since timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(total_hands bigint, active_players bigint, total_rake numeric, vip_diamonds bigint, live_players bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.fn_is_platform_admin() THEN
    RAISE EXCEPTION 'not_authorized: platform admin required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    COALESCE((
      SELECT sum(pps.hands_played)
      FROM public.player_position_stats pps
      WHERE p_since IS NULL OR pps.updated_at >= p_since
    ), 0)::bigint,

    COALESCE((
      SELECT count(DISTINCT pps.user_id)
      FROM public.player_position_stats pps
      WHERE p_since IS NULL OR pps.updated_at >= p_since
    ), 0)::bigint,

    COALESCE((
      SELECT sum(rr.rake_amount)
      FROM public.rake_records rr
      WHERE p_since IS NULL OR rr.created_at >= p_since
    ), 0)::numeric,

    COALESCE((
      SELECT sum(dt.amount)
      FROM public.diamond_transactions dt
      WHERE dt.amount > 0
        AND (p_since IS NULL OR dt.created_at >= p_since)
    ), 0)::bigint,

    COALESCE((
      SELECT count(*)
      FROM public.table_seats ts
      WHERE ts.status = 'active' AND ts.left_at IS NULL
    ), 0)::bigint;
END $$;


ALTER FUNCTION public.fn_admin_platform_aggregates(p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_admin_platform_aggregates(p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_admin_platform_aggregates(p_since timestamp with time zone) IS 'Platform-wide admin metrics in one round trip. Replaces four browser-side reductions over unordered .limit(5000) slices, one of which (rake) was 0.05 * hands rather than rake, and one of which (diamonds) read the permanently empty diamond_ledger. Admin-gated; counts horses as players per CLAUDE.md 10.5.';


--
-- Name: fn_admin_remove_player_chips(uuid, uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_admin_remove_player_chips(p_club_id uuid, p_player_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor      uuid := auth.uid();
  v_op_id      uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior      record;
  v_actor_role text;
  v_before     numeric;
  v_after      numeric;
  v_bank_after numeric;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;

  -- The same rounding trap the send functions carry: club_members.chip_balance
  -- is numeric(20,2) and clubs.chip_treasury is not, so an amount finer than a
  -- hundredth is debited and credited at different scales.
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false, 'error', 'Chips Move In Hundredths At Most');
  end if;

  select id, amount, metadata into v_prior
    from chip_transactions
   where transaction_type = 'admin_removal'
     and club_id = p_club_id
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object('success', true, 'replayed', true,
      'removed', v_prior.amount,
      'balance_after', (v_prior.metadata ->> 'holder_balance_after')::numeric,
      'bank_after', (v_prior.metadata ->> 'bank_after')::numeric);
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null or v_actor_role not in ('owner', 'co_owner', 'admin') then
    return jsonb_build_object('success', false,
      'error', 'Only An Owner, Co Owner Or Admin May Pull Chips From A Member. '
               || 'An Agent Must Wait For A Cash Out Request');
  end if;

  select chip_balance into v_before
    from club_members
   where club_id = p_club_id and user_id = p_player_id
   for update;
  if v_before is null then
    return jsonb_build_object('success', false,
      'error', 'That Person Is Not A Member Of This Club');
  end if;
  if v_before < p_amount then
    return jsonb_build_object('success', false,
      'error', 'That Wallet Only Holds ' || trim(to_char(v_before, 'FM999,999,999,990.00')) || ' Chips',
      'balance', v_before, 'requested', p_amount);
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): ONE `club_bank_claim` row from the
  -- member's wallet to the club bank, keyed and correlated on the op. The
  -- clubs trigger is skipped; the club_members trigger writes the row with
  -- the bank as its counterparty (it used to invent `table_stack`).
  perform public.fn_ca_declare_ledger('club_bank_claim', 'club_treasury', p_club_id, null,
    'admin_removal:' || v_op_id::text, array['clubs']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  update club_members
     set chip_balance = coalesce(chip_balance, 0) - p_amount,
         updated_at = now()
   where club_id = p_club_id and user_id = p_player_id
   returning chip_balance into v_after;

  update clubs
     set chip_treasury = coalesce(chip_treasury, 0) + p_amount,
         updated_at = now()
   where id = p_club_id
   returning chip_treasury into v_bank_after;
  perform set_config('app.ledger_autoskip_clubs', '', true);

  begin
    insert into chip_transactions
      (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
    values
      (p_club_id, p_player_id, v_actor, p_amount, 'admin_removal',
       coalesce(nullif(btrim(p_reason), ''), 'Chips Pulled By Club Staff'),
       jsonb_build_object(
         'op_id', v_op_id,
         'source', 'player_wallet',
         'direction', 'into_bank',
         'actor_role', v_actor_role,
         'holder_balance_after', v_after,
         'bank_after', v_bank_after),
       v_bank_after);
  exception when unique_violation then
    select id, amount, metadata into v_prior
      from chip_transactions
     where transaction_type = 'admin_removal'
       and club_id = p_club_id
       and metadata ->> 'op_id' = v_op_id::text
     limit 1;
    return jsonb_build_object('success', true, 'replayed', true,
      'removed', v_prior.amount,
      'balance_after', (v_prior.metadata ->> 'holder_balance_after')::numeric,
      'bank_after', (v_prior.metadata ->> 'bank_after')::numeric);
  end;

  -- The member is told. Staff pulling chips is the one movement that happens
  -- to a player without them asking for it.
  insert into notifications (user_id, type, title, message, metadata, actor_id)
  values (p_player_id, 'settlement', 'Chips Removed By Club Staff',
          trim(to_char(p_amount, 'FM999,999,999,990')) || ' Chips Were Removed From Your Wallet',
          jsonb_build_object('clubId', p_club_id, 'amount', p_amount,
                             'balanceAfter', v_after),
          v_actor);

  return jsonb_build_object('success', true, 'replayed', false, 'removed', p_amount,
    'balance_before', v_before, 'balance_after', v_after, 'bank_after', v_bank_after);
end
$$;


ALTER FUNCTION public.fn_admin_remove_player_chips(p_club_id uuid, p_player_id uuid, p_amount numeric, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_admin_remove_tournament_player(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_admin_remove_tournament_player(p_tournament_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid:=auth.uid();
  v_club_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_admin_remove_tournament_player requires an authenticated caller'
      USING ERRCODE='28000';
  END IF;
  SELECT t.club_id INTO v_club_id FROM public.tournaments t
   WHERE t.id=p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  IF NOT public.fn_can_create_games(v_club_id,v_uid) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized');
  END IF;
  RETURN public.fn_ca_unregister_tournament_player_exact(
    p_tournament_id,p_user_id,NULL,'Administrator tournament removal refund');
END;
$$;


ALTER FUNCTION public.fn_admin_remove_tournament_player(p_tournament_id uuid, p_user_id uuid) OWNER TO postgres;

