--
-- Name: fn_admin_update_agent(uuid, text, text, numeric, numeric, numeric, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_admin_update_agent(p_agent_id uuid, p_status text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_credit_limit numeric DEFAULT NULL::numeric, p_commission_rate numeric DEFAULT NULL::numeric, p_player_rakeback_rate numeric DEFAULT NULL::numeric, p_assigned_by uuid DEFAULT NULL::uuid, p_credit_reason text DEFAULT NULL::text, p_is_prepaid boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_caller uuid := (SELECT auth.uid());
  v_club_id uuid; v_user_id uuid; v_parent uuid; v_old_limit numeric; v_parent_limit numeric;
  v_member_role text; v_role_res jsonb;
  v_prepaid_now boolean; v_limit_now numeric; v_used_now numeric;
  v_prepaid_after boolean; v_limit_after numeric;
  v_touches_funding boolean;
BEGIN
  IF p_agent_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'agent id required'); END IF;
  IF v_caller IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'authentication required'); END IF;
  SELECT club_id, user_id, parent_agent_id, credit_limit INTO v_club_id, v_user_id, v_parent, v_old_limit
  FROM agents WHERE id = p_agent_id;
  IF v_club_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'agent not found'); END IF;
  IF NOT EXISTS (
    SELECT 1 FROM clubs c WHERE c.id = v_club_id AND (
      c.owner_id = v_caller
      OR EXISTS (SELECT 1 FROM club_members cm WHERE cm.club_id = v_club_id AND cm.user_id = v_caller
                 AND cm.role IN ('owner','co_owner','admin')))
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authorized to manage this club''s agents');
  END IF;
  IF p_status IS NOT NULL AND p_status NOT IN ('active','suspended','frozen') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid status'); END IF;
  IF p_role IS NOT NULL AND p_role NOT IN ('super_agent','agent','sub_agent') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid role'); END IF;
  IF p_credit_limit IS NOT NULL AND p_credit_limit < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'credit_limit must be >= 0'); END IF;
  -- The table CHECK is 0..0.70 and 0..0.50. Validating against 0..100 let a
  -- caller who meant "25%" past this line and into a raw 23514 from Postgres.
  IF p_commission_rate IS NOT NULL AND (p_commission_rate < 0 OR p_commission_rate > 0.70) THEN
    RETURN jsonb_build_object('success', false, 'error', 'commission_rate must be between 0 and 0.70'); END IF;
  IF p_player_rakeback_rate IS NOT NULL AND (p_player_rakeback_rate < 0 OR p_player_rakeback_rate > 0.50) THEN
    RETURN jsonb_build_object('success', false, 'error', 'player_rakeback_rate must be between 0 and 0.50'); END IF;

  -- ---------------------------------------------------------------------------
  -- THE FUNDING PAIR
  -- ---------------------------------------------------------------------------
  SELECT COALESCE(is_prepaid, false), COALESCE(credit_limit, 0), COALESCE(credit_used, 0)
    INTO v_prepaid_now, v_limit_now, v_used_now
    FROM agents WHERE id = p_agent_id;

  v_touches_funding := (p_is_prepaid IS NOT NULL OR p_credit_limit IS NOT NULL);
  v_prepaid_after   := COALESCE(p_is_prepaid, v_prepaid_now);
  v_limit_after     := COALESCE(p_credit_limit, v_limit_now);

  IF v_touches_funding THEN
    -- Granting a line IS the choice of credit. Refusing here instead would
    -- dead-end every "raise this agent's limit" call against a prepaid agent,
    -- and no screen moves them to credit first.
    IF p_is_prepaid IS NULL AND COALESCE(p_credit_limit, 0) > 0 THEN
      v_prepaid_after := false;
    END IF;

    -- And moving somebody TO prepaid closes the line, for the same reason in
    -- reverse: prepaid and a line cannot both be true.
    IF COALESCE(p_is_prepaid, false) AND p_credit_limit IS NULL THEN
      v_limit_after := 0;
    END IF;

    -- Saying both, and contradicting yourself, is still a mistake worth naming.
    IF v_prepaid_after AND COALESCE(v_limit_after, 0) <> 0 THEN
      RETURN jsonb_build_object('success', false,
        'error', 'a prepaid agent carries no credit line. Send prepaid on its own, or a credit limit on its own.');
    END IF;

    -- The pair that can send nothing at all.
    IF NOT v_prepaid_after AND COALESCE(v_limit_after, 0) <= 0 THEN
      RETURN jsonb_build_object('success', false, 'needs_funding', true,
        'error', 'an agent on credit needs a limit greater than 0. Set them prepaid instead, or give a limit.');
    END IF;

    -- A debt outlives the line it was drawn against, so the line cannot simply
    -- be taken away while it is still owed.
    IF v_prepaid_after AND v_used_now > 0 THEN
      RETURN jsonb_build_object('success', false,
        'error', 'this agent still owes ' || trim(to_char(v_used_now, 'FM999,999,999,990.00'))
                 || ' chips on their credit line. Settle the invoice before moving them to prepaid.',
        'credit_used', v_used_now);
    END IF;

    -- Lowering a limit below what has already been drawn violates check_credit
    -- and used to reach the client as a raw 23514 with no explanation.
    IF NOT v_prepaid_after AND v_limit_after < v_used_now THEN
      RETURN jsonb_build_object('success', false,
        'error', 'that limit is below the ' || trim(to_char(v_used_now, 'FM999,999,999,990.00'))
                 || ' chips already drawn. Take a payment first, or set a limit of at least that much.',
        'credit_used', v_used_now, 'requested_limit', v_limit_after);
    END IF;
  END IF;

  IF v_touches_funding AND v_parent IS NOT NULL THEN
    SELECT credit_limit INTO v_parent_limit FROM agents WHERE id = v_parent;
    IF v_parent_limit IS NOT NULL AND v_limit_after > v_parent_limit THEN
      RETURN jsonb_build_object('success', false, 'error', 'credit limit cannot exceed parent agent limit');
    END IF;
  END IF;

  SELECT role INTO v_member_role FROM club_members
   WHERE club_id = v_club_id AND user_id = v_user_id;

  -- Dan, B-02, 2026-08-31: OWNERS KEEP EARNING. This list used to include
  -- 'owner', which no rule anywhere else does: trg_agents_staff_earn_no_rakeback
  -- covers co_owner and admin only, and one live owner already holds an active
  -- agents row at 0.30 / 0.20 that this branch would have refused to edit.
  IF v_member_role IN ('co_owner','admin')
     AND (COALESCE(p_commission_rate, 0) <> 0 OR COALESCE(p_player_rakeback_rate, 0) <> 0)
     AND p_role IS NULL THEN
    RETURN jsonb_build_object('success', false,
      'error', 'this member is club staff and earns no rakeback. Change their role first.');
  END IF;

  -- The role change goes through the one door, so the grant matrix, the
  -- downline guard, the funding choice and the audit row apply here too. The
  -- RESOLVED funding pair is forwarded, not the raw arguments: the callee
  -- applies the same prepaid-or-a-line rule, and sending it a bare NULL where
  -- this call has already decided would make the two disagree.
  IF p_role IS NOT NULL AND v_member_role IS NOT NULL AND v_member_role <> p_role THEN
    v_role_res := public.fn_club_set_member_role(
      v_club_id, v_user_id, p_role, v_caller,
      p_commission_rate, p_player_rakeback_rate,
      CASE WHEN v_touches_funding THEN v_prepaid_after ELSE NULL END,
      CASE WHEN v_touches_funding THEN v_limit_after   ELSE NULL END);
    IF NOT COALESCE((v_role_res ->> 'success')::boolean, false) THEN
      RETURN v_role_res;
    END IF;
  END IF;

  UPDATE agents SET
    status = COALESCE(p_status, status),
    role = COALESCE(p_role, role),
    credit_limit = CASE WHEN v_touches_funding THEN v_limit_after ELSE credit_limit END,
    commission_rate = COALESCE(p_commission_rate, commission_rate),
    player_rakeback_rate = COALESCE(p_player_rakeback_rate, player_rakeback_rate),
    is_prepaid = CASE WHEN v_touches_funding THEN v_prepaid_after ELSE is_prepaid END,
    updated_at = now()
  WHERE id = p_agent_id;

  IF v_touches_funding AND v_limit_after <> COALESCE(v_old_limit, -1) THEN
    INSERT INTO credit_assignments (agent_id, assigned_by, old_limit, new_limit, reason)
    VALUES (p_agent_id, v_caller, v_old_limit, v_limit_after, p_credit_reason);
  END IF;

  RETURN jsonb_build_object('success', true, 'agent_id', p_agent_id, 'club_id', v_club_id,
    'is_prepaid', CASE WHEN v_touches_funding THEN v_prepaid_after ELSE v_prepaid_now END,
    'credit_limit', CASE WHEN v_touches_funding THEN v_limit_after ELSE v_limit_now END);
END;
$$;


ALTER FUNCTION public.fn_admin_update_agent(p_agent_id uuid, p_status text, p_role text, p_credit_limit numeric, p_commission_rate numeric, p_player_rakeback_rate numeric, p_assigned_by uuid, p_credit_reason text, p_is_prepaid boolean) OWNER TO postgres;

--
-- Name: fn_after_tournament_rebuy(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_after_tournament_rebuy(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_candidate uuid;
  v_candidates uuid[];
  v_count integer;
BEGIN
  IF p_rebuy_type NOT IN ('rebuy','reentry') THEN RETURN; END IF;
  PERFORM 1 FROM public.tournaments t WHERE t.id=p_tournament_id FOR UPDATE;
  SELECT array_agg(locked.id ORDER BY locked.hand_number)
    INTO v_candidates
    FROM (
      SELECT c.id,c.hand_number
        FROM public.tournament_knockout_candidates c
       WHERE c.tournament_id=p_tournament_id
         AND c.eliminated_user_id=p_user_id
         AND c.state='pending'
       ORDER BY c.hand_number
       FOR UPDATE
    ) locked;
  v_count := coalesce(cardinality(v_candidates),0);
  v_candidate := v_candidates[1];
  IF v_count>1 THEN
    RAISE EXCEPTION 'rebuy has % unresolved knockout generations for tournament %, user %',
      v_count,p_tournament_id,p_user_id USING ERRCODE='integrity_constraint_violation';
  END IF;
  IF v_count=1 THEN
    UPDATE public.tournament_knockout_candidates
       SET state='rebought',resolved_at=clock_timestamp()
     WHERE id=v_candidate;
  END IF;
  UPDATE public.tournament_players
     SET rebuy_prompt_until=NULL
   WHERE tournament_id=p_tournament_id AND user_id=p_user_id;
END;
$$;


ALTER FUNCTION public.fn_after_tournament_rebuy(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text) OWNER TO postgres;

--
-- Name: fn_agent_approve_cashout(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_approve_cashout(p_cashout_id uuid, p_agent_user_id uuid, p_agent_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_cashout RECORD; v_agent RECORD;
BEGIN
  SELECT * INTO v_cashout FROM cashout_requests WHERE id = p_cashout_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Not found'); END IF;
  IF v_cashout.status != 'pending' THEN RETURN jsonb_build_object('success', false, 'error', 'Already ' || v_cashout.status); END IF;
  SELECT * INTO v_agent FROM agents WHERE club_id = v_cashout.club_id AND user_id = COALESCE(v_cashout.agent_id, p_agent_user_id);
  UPDATE cashout_requests SET status = 'approved', agent_id = COALESCE(agent_id, p_agent_user_id), agent_note = p_agent_note, acknowledged_at = NOW(), updated_at = NOW() WHERE id = p_cashout_id;
  IF v_agent.id IS NOT NULL AND v_agent.is_prepaid = true THEN
    UPDATE agents SET player_balance = COALESCE(player_balance, 0) - v_cashout.amount, updated_at = NOW() WHERE id = v_agent.id;
  END IF;
  IF v_agent.id IS NOT NULL AND COALESCE(v_agent.is_prepaid, false) = false THEN
    UPDATE agents SET credit_used = COALESCE(credit_used, 0) + v_cashout.amount, updated_at = NOW() WHERE id = v_agent.id;
  END IF;
  RETURN jsonb_build_object('success', true, 'cashout_id', p_cashout_id, 'status', 'approved', 'amount', v_cashout.amount);
END;
$$;


ALTER FUNCTION public.fn_agent_approve_cashout(p_cashout_id uuid, p_agent_user_id uuid, p_agent_note text) OWNER TO postgres;

--
-- Name: fn_agent_attach_player(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_attach_player(p_club_id uuid, p_agent_user_id uuid, p_player_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_caller     uuid := auth.uid();
  v_is_staff   boolean := false;
  v_agent      record;
  v_member     record;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'not_authenticated',
                              'error', 'Please sign in again.');
  END IF;

  IF p_agent_user_id = p_player_id THEN
    RETURN jsonb_build_object('success', false, 'code', 'self_attach',
                              'error', 'An agent cannot be their own downline.');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM clubs c WHERE c.id = p_club_id AND c.owner_id = v_caller
    UNION ALL
    SELECT 1 FROM club_members cm
     WHERE cm.club_id = p_club_id AND cm.user_id = v_caller
       AND cm.role IN ('owner', 'co_owner', 'admin')
       AND cm.status IN ('active', 'approved')
  ) INTO v_is_staff;

  IF NOT v_is_staff AND v_caller <> p_agent_user_id THEN
    RETURN jsonb_build_object('success', false, 'code', 'not_authorized',
                              'error', 'You can only add players to your own downline.');
  END IF;

  SELECT * INTO v_agent FROM agents
   WHERE club_id = p_club_id AND user_id = p_agent_user_id AND status = 'active';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'not_an_active_agent',
                              'error', 'That agent is not active in this club.');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = p_player_id) THEN
    RETURN jsonb_build_object('success', false, 'code', 'unknown_player',
                              'error', 'That player does not exist.');
  END IF;

  SELECT * INTO v_member FROM club_members
   WHERE club_id = p_club_id AND user_id = p_player_id;

  IF NOT FOUND THEN
    INSERT INTO club_members (club_id, user_id, role, status, tier, rank_level,
                              orange_ball_status, agent_id, invited_by)
    VALUES (p_club_id, p_player_id, 'player', 'active', 'bronze', 0, 'cold',
            p_agent_user_id, p_agent_user_id)
    RETURNING * INTO v_member;
  ELSE
    IF v_member.status NOT IN ('active', 'approved', 'pending') THEN
      RETURN jsonb_build_object('success', false, 'code', 'membership_blocked',
                                'error', 'That membership cannot be changed.');
    END IF;

    IF v_member.agent_id IS NOT NULL
       AND v_member.agent_id <> p_agent_user_id
       AND NOT v_is_staff THEN
      RETURN jsonb_build_object('success', false, 'code', 'already_in_a_downline',
                                'error', 'That player is already in another downline.');
    END IF;

    UPDATE club_members
       SET agent_id   = p_agent_user_id,
           invited_by = COALESCE(invited_by, p_agent_user_id),
           status     = CASE WHEN status = 'pending' THEN 'active' ELSE status END,
           updated_at = now()
     WHERE club_id = p_club_id AND user_id = p_player_id
    RETURNING * INTO v_member;
  END IF;

  UPDATE agents
     SET total_players = (SELECT count(*) FROM club_members
                           WHERE agent_id = p_agent_user_id AND club_id = p_club_id),
         active_player_count = (SELECT count(*) FROM club_members
                                 WHERE agent_id = p_agent_user_id AND club_id = p_club_id
                                   AND status IN ('active', 'approved')),
         updated_at = now()
   WHERE club_id = p_club_id AND user_id = p_agent_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'status', v_member.status,
    'agent_id', v_member.agent_id,
    'chip_balance', v_member.chip_balance
  );
END;
$$;


ALTER FUNCTION public.fn_agent_attach_player(p_club_id uuid, p_agent_user_id uuid, p_player_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_agent_attach_player(p_club_id uuid, p_agent_user_id uuid, p_player_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_agent_attach_player(p_club_id uuid, p_agent_user_id uuid, p_player_id uuid) IS 'Attaches a player to an agent downline in one permission-checked call, creating the membership at zero chips if it does not exist. Replaces PlayerInviteModal direct insert, which wrote a referrer_id column that does not exist and therefore never once succeeded.';


--
-- Name: fn_agent_claim_commission(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_claim_commission(p_club_id uuid, p_op_id uuid DEFAULT NULL::uuid, p_max_rows integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor      uuid;
  v_op_id      uuid := COALESCE(p_op_id, gen_random_uuid());
  v_role       text;
  v_amount     numeric;
  v_rows       bigint;
  v_bank_before numeric;
  v_bank_after  numeric;
  v_to_after    numeric;
  v_prior      jsonb;
  v_club_name  text;
  v_batch      integer;
  v_more       boolean;
  v_ids        uuid[];
  v_cutoff     timestamptz;
  v_safe       timestamptz := now() - interval '5 minutes';
  v_settled    uuid;
BEGIN
  /* ZERO-DRIFT phase 6: commission claims journal as commission. */
  PERFORM set_config('app.ledger_category', 'commission', true);
  PERFORM set_config('app.ledger_counterparty', 'agent_wallet', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  -- IDENTITY. auth.uid() is the only identity a browser can establish, and this
  -- RPC pays the caller. There is deliberately no p_user_id: a parameter naming
  -- somebody else would make this a way to move another person's earnings, and
  -- Dan's rule is that agents handle their own payouts.
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sign In To Claim Your Commission');
  END IF;

  -- REPLAY. Same op_id, same answer, no second payment. The client sends one
  -- id per intent, so a double tap or a retried request settles once.
  SELECT metadata INTO v_prior
    FROM chip_transactions
   WHERE club_id = p_club_id
     AND to_user_id = v_actor
     AND transaction_type = 'commission_claim'
     AND metadata ->> 'op_id' = v_op_id::text
   LIMIT 1;
  IF v_prior IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'replayed', true,
      'amount', (v_prior ->> 'amount')::numeric,
      'rows_settled', (v_prior ->> 'rows_settled')::bigint,
      'more', EXISTS (SELECT 1 FROM public.agent_commissions ac WHERE ac.club_id = p_club_id AND ac.user_id = v_actor AND ac.settled_at IS NULL AND NOT EXISTS (SELECT 1 FROM public.agent_commission_settlements s WHERE s.club_id = ac.club_id AND s.user_id = ac.user_id AND ac.created_at >= s.period_start AND ac.created_at < s.period_end)),
      'op_id', v_op_id);
  END IF;

  /* ONE CLAIM PER PAIR AT A TIME (Phase 7, 20260908). The batch used to be
     held with FOR UPDATE, which is what stopped two concurrent claims paying
     the same rows. Nothing is stamped now, so the pair is serialised here
     instead; every statement after this takes a fresh snapshot, so the
     second claim sees the first one's settlement row. */
  PERFORM pg_advisory_xact_lock(hashtextextended('agent_claim:' || p_club_id::text || ':' || v_actor::text, 42));

  -- MEMBERSHIP, NOT ROLE. A demoted agent keeps what they earned - Phase 4 let
  -- the demotion through precisely because "the agents row survives with the
  -- figure intact". If claiming required an agent role, the demotion would have
  -- quietly confiscated the money instead of deferring it.
  SELECT cm.role INTO v_role
    FROM club_members cm
   WHERE cm.club_id = p_club_id
     AND cm.user_id = v_actor
     AND COALESCE(cm.status, 'active') IN ('active', 'approved')
     -- FOR UPDATE, added 2026-09-02. Without it this row can be deleted
     -- between here and the credit ninety lines below, and the credit
     -- silently matches nothing while the bank has already been debited.
     FOR UPDATE;
  IF v_role IS NULL THEN
    RETURN jsonb_build_object('success', false,
      'error', 'You Are Not An Active Member Of This Club');
  END IF;

  -- WHAT IS OWED, LOCKED, AND BOUNDED.
  --
  -- MEASURED ON PRODUCTION, 2026-08-31: the largest agent has 192,135 unsettled
  -- rows, and settling all of them in one statement took 64.6 SECONDS. The
  -- authenticated role's statement_timeout is 8s, so the three biggest agents
  -- (192k, 114k, 113k rows) could never have been paid at all.
  --
  -- The timeout is the smaller half of the problem. That statement also holds
  -- FOR UPDATE on the clubs row for its whole life, so a single claim would
  -- have frozen every chip movement in that club for a minute.
  --
  -- So a claim settles a BATCH and reports whether more is left. Measured on
  -- production against the largest agent: 2,000 rows took 2.95s, so the default
  -- is 1,000 - roughly 1.5s, a comfortable margin under 8s on a database that
  -- is also serving everybody else. The caller repeats while `more` is true -
  -- WITH A FRESH op_id EACH TIME, because op_id identifies one batch. Reusing
  -- one is what makes a retry safe; reusing one for the NEXT batch would
  -- replay the previous answer instead of settling anything.
  v_batch := LEAST(GREATEST(COALESCE(p_max_rows, 1000), 1), 5000);

  -- LOCK AND TOTAL THE BATCH. NOTHING IS WRITTEN YET.
  --
  -- ORDER MATTERS HERE AND IT IS THE WHOLE POINT. A refusal below returns
  -- JSON, and a plain RETURN does not roll anything back - PostgREST commits
  -- the transaction. So every write in this function happens AFTER the last
  -- thing that can refuse. An earlier draft folded the lock, the settle and
  -- the sum into one CTE for speed, which stamped settled_at before the club
  -- bank had been checked: a short bank would then have returned "cannot pay"
  -- while leaving the rows marked paid. That is the worst bug this function
  -- could have had, and it is why the settle is the last write, below.
  /* Phase 7 (20260908): the batch is the pair's OPEN rows - unstamped, and
     not covered by a settlement row - so a claim can never re-pay a row a
     period already covers. The anti-join rides agent_commissions_open_idx
     and stops at the LIMIT; the ORDER BY note below is history. */
  /* THE CUTOFF: the created_at of the batch-th oldest open row, clamped to
     five minutes ago. Oldest-first is agent_commissions_open_idx's own
     order, so the ORDER BY below is an index walk, not a sort. */
  SELECT ac.created_at INTO v_cutoff
    FROM public.agent_commissions ac
   WHERE ac.club_id = p_club_id AND ac.user_id = v_actor
     AND ac.settled_at IS NULL
     AND ac.created_at < v_safe
     AND NOT EXISTS (SELECT 1 FROM public.agent_commission_settlements s
                      WHERE s.club_id = ac.club_id AND s.user_id = ac.user_id
                        AND ac.created_at >= s.period_start AND ac.created_at < s.period_end)
   ORDER BY ac.created_at
  OFFSET v_batch LIMIT 1;
  v_cutoff := LEAST(COALESCE(v_cutoff, v_safe), v_safe);
  SELECT COALESCE(SUM(ac.amount), 0), COUNT(*)
    INTO v_amount, v_rows
    FROM (
      SELECT ac.amount
        FROM public.agent_commissions ac
       WHERE ac.club_id = p_club_id AND ac.user_id = v_actor
         AND ac.settled_at IS NULL
         AND ac.created_at < v_cutoff
         AND NOT EXISTS (SELECT 1 FROM public.agent_commission_settlements s
                          WHERE s.club_id = ac.club_id AND s.user_id = ac.user_id
                            AND ac.created_at >= s.period_start AND ac.created_at < s.period_end)
       /* No LIMIT and no FOR UPDATE: the cutoff already bounds the set, and
          nothing here is stamped, so there is no row to hold. The pair's
          advisory lock above is what serialises two claims. */
    ) ac;

  IF COALESCE(v_amount, 0) <= 0 THEN
    RETURN jsonb_build_object('success', false, 'nothing_owed', true,
      'error', 'You Have No Commission To Claim Yet');
  END IF;

  v_amount := round(v_amount, 2);

  -- THE CLUB BANK PAYS, AND IT PAYS ONLY WHAT IT HAS. Midway Union owes 568.18
  -- against a treasury of 0.00, so this refusal is not hypothetical. Naming the
  -- shortfall is the difference between "try later" and "somebody has to fund
  -- the bank" - and it is the same refusal fn_club_bank_send already gives.
  SELECT COALESCE(c.chip_treasury, 0), c.name
    INTO v_bank_before, v_club_name
    FROM clubs c WHERE c.id = p_club_id FOR UPDATE;
  IF v_bank_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Club Not Found');
  END IF;
  IF v_bank_before < v_amount THEN
    RETURN jsonb_build_object('success', false, 'bank_short', true,
      'error', 'The Club Bank Holds '
               || trim(to_char(v_bank_before, 'FM999,999,999,990.00'))
               || ' Chips And Owes You '
               || trim(to_char(v_amount, 'FM999,999,999,990.00'))
               || '. Ask An Owner To Fund The Bank, Then Claim Again.',
      'balance', v_bank_before, 'requested', v_amount);
  END IF;

  UPDATE clubs
     SET chip_treasury = COALESCE(chip_treasury, 0) - v_amount,
         updated_at = now()
   WHERE id = p_club_id
   RETURNING chip_treasury INTO v_bank_after;

  -- INTO THEIR OWN MONEY, not the agent wallet. See the header.
  UPDATE club_members
     SET chip_balance = COALESCE(chip_balance, 0) + v_amount,
         updated_at = now()
   WHERE club_id = p_club_id AND user_id = v_actor
   RETURNING chip_balance INTO v_to_after;

  -- THE CREDIT MUST HAVE LANDED. The bank is already debited at this
  -- point, so a credit that matched no row would leave the chips nowhere
  -- and stamp the rows paid. The role read above holds FOR UPDATE, so
  -- this should be unreachable; RAISE rather than RETURN because a
  -- refusal here has to take the debit back with it, and only an
  -- exception rolls back what PostgREST would otherwise commit.
  IF v_to_after IS NULL THEN
    RAISE EXCEPTION 'commission claim could not credit the member wallet'
      USING ERRCODE = '25000';
  END IF;

  -- SETTLED, LAST. This is the line execute_commission_payout never had, and
  -- its absence is what let that function pay the same row forever. It runs
  -- after the bank has been debited and the agent credited, so no row is ever
  -- marked paid by a claim that did not pay.
  INSERT INTO public.agent_commission_settlements
    (club_id, user_id, union_id, period_start, period_end, amount, rows_count, paid_at, settlement_ref)
  VALUES (p_club_id, v_actor, NULL, '-infinity'::timestamptz, v_cutoff,
          round(v_amount, 2), v_rows, now(), 'claim:' || v_op_id::text)
  ON CONFLICT (club_id, user_id, period_start, period_end) DO NOTHING
  RETURNING id INTO v_settled;
  IF v_settled IS NULL THEN
    /* A concurrent claim recorded the same cutoff. The bank is already
       debited in this transaction, so the only safe answer is to take it
       all back: RAISE rolls the claim back and the caller retries. */
    RAISE EXCEPTION 'another claim recorded this window; retry'
      USING ERRCODE = '40001';
  END IF;

  /* CONTROL (phase 8): the claim is two balanced legs on the journal, the
       same movement chip_transactions records one-sidedly below. */
    INSERT INTO public.chip_ledger
      (performed_by, from_type, from_entity_id, to_type, to_entity_id,
       amount, category, club_id, description, idempotency_key, metadata)
    VALUES
      (v_actor, 'club_treasury', p_club_id, 'player_wallet', v_actor,
       round(v_amount, 2), 'commission', p_club_id,
       'Agent claimed commission from the club bank',
       'agent_claim:' || v_op_id::text,
       jsonb_build_object('op_id', v_op_id, 'rows_settled', v_rows,
                          'bank_after', v_bank_after,
                          'agent_balance_after', v_to_after))
    ON CONFLICT DO NOTHING;

    INSERT INTO chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  VALUES
    (p_club_id, NULL, v_actor, v_amount, 'commission_claim',
     'Commission Claimed By Agent',
     jsonb_build_object(
       'op_id', v_op_id,
       'amount', v_amount,
       'rows_settled', v_rows,
       'role_at_claim', v_role,
       'bank_before', v_bank_before,
       'bank_after', v_bank_after),
     v_to_after);

  BEGIN
    PERFORM public.fn_raise_notification(
      v_actor, 'commission_claimed',
      'You Claimed ' || trim(to_char(v_amount, 'FM999,999,999,990.00')) || ' Chips',
      'Your Commission From ' || COALESCE(v_club_name, 'Your Club')
        || ' Is Now In Your Chip Balance.',
      '/clubs/' || p_club_id::text,
      jsonb_build_object('club_id', p_club_id, 'amount', v_amount, 'rows_settled', v_rows));
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- the money has moved and is recorded; the notice is a courtesy
  END;

  -- IS THERE MORE? An EXISTS, not a COUNT and a SUM.
  --
  -- Reporting the exact remaining figure here cost 1,474ms on production,
  -- because it re-scans every one of the agent's remaining rows - on a call
  -- whose entire budget is 8 seconds. EXISTS answers the only question the
  -- caller needs in order to loop (0.25ms), and the exact figure is available
  -- from fn_agent_unsettled_commission on a screen that can afford it.
  SELECT EXISTS (
    SELECT 1 FROM public.agent_commissions ac
     WHERE ac.club_id = p_club_id AND ac.user_id = v_actor AND ac.settled_at IS NULL
       AND NOT EXISTS (SELECT 1 FROM public.agent_commission_settlements s
                        WHERE s.club_id = ac.club_id AND s.user_id = ac.user_id
                          AND ac.created_at >= s.period_start AND ac.created_at < s.period_end)
  ) INTO v_more;

  RETURN jsonb_build_object('success', true, 'amount', v_amount,
    'rows_settled', v_rows, 'chip_balance', v_to_after,
    'bank_after', v_bank_after, 'op_id', v_op_id,
    'more', v_more);
END;
$$;


ALTER FUNCTION public.fn_agent_claim_commission(p_club_id uuid, p_op_id uuid, p_max_rows integer) OWNER TO postgres;

--
-- Name: fn_agent_commission_paid_by_period(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_commission_paid_by_period(p_club_id uuid, p_user_id uuid, p_created_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.agent_commission_settlements s
                  WHERE s.club_id = p_club_id AND s.user_id = p_user_id
                    AND p_created_at >= s.period_start AND p_created_at < s.period_end);
$$;


ALTER FUNCTION public.fn_agent_commission_paid_by_period(p_club_id uuid, p_user_id uuid, p_created_at timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_agent_commission_rollup_recompute(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_commission_rollup_recompute(p_pairs jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  WITH pairs AS (
    SELECT DISTINCT (p->>'club_id')::uuid AS club_id, (p->>'user_id')::uuid AS user_id
      FROM jsonb_array_elements(p_pairs) p
     WHERE p->>'club_id' IS NOT NULL AND p->>'user_id' IS NOT NULL
  ),
  fresh AS (
    SELECT pr.club_id, pr.user_id,
           coalesce(sum(ac.amount), 0)  AS owed,
           count(ac.id)                 AS rows_behind,
           min(ac.created_at)           AS oldest
      FROM pairs pr
      LEFT JOIN public.agent_commissions ac
        ON ac.club_id = pr.club_id AND ac.user_id = pr.user_id
       AND ac.settled_at IS NULL
       AND NOT EXISTS (SELECT 1 FROM public.agent_commission_settlements s
                        WHERE s.club_id = ac.club_id AND s.user_id = ac.user_id
                          AND ac.created_at >= s.period_start AND ac.created_at < s.period_end)
     GROUP BY pr.club_id, pr.user_id
  )
  INSERT INTO public.agent_commission_unsettled_rollup AS r
         (club_id, user_id, owed, rows_behind, oldest_unsettled, updated_at)
  SELECT f.club_id, f.user_id, f.owed, f.rows_behind, f.oldest, now() FROM fresh f
  ON CONFLICT (club_id, user_id) DO UPDATE
     SET owed = EXCLUDED.owed,
         rows_behind = EXCLUDED.rows_behind,
         oldest_unsettled = EXCLUDED.oldest_unsettled,
         updated_at = now();
END;
$$;


ALTER FUNCTION public.fn_agent_commission_rollup_recompute(p_pairs jsonb) OWNER TO postgres;

--
-- Name: fn_agent_downline_commission(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_downline_commission(p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'agent_id',  d.id,
           'user_id',   d.user_id,
           'club_id',   d.club_id,
           'unclaimed', COALESCE(t.unclaimed, 0))), '[]'::jsonb)
    INTO v_result
    FROM public.agents me
    JOIN public.agents d ON d.parent_agent_id = me.id
    LEFT JOIN LATERAL (
           SELECT SUM(ac.amount) AS unclaimed
             FROM public.agent_commissions ac
            WHERE ac.club_id = d.club_id
              AND ac.user_id = d.user_id
              AND ac.settled_at IS NULL AND NOT public.fn_agent_commission_paid_by_period(ac.club_id, ac.user_id, ac.created_at)
         ) t ON TRUE
   WHERE me.user_id = v_uid
     AND (p_club_id IS NULL OR me.club_id = p_club_id);

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_agent_downline_commission(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_agent_downline_rake(uuid, uuid, timestamp with time zone, timestamp with time zone, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_downline_rake(p_agent_user_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS TABLE(player_id uuid, username text, club_id uuid, club_name text, role text, depth integer, upline_user_id uuid, upline_name text, rake_generated numeric, hands bigint, last_hand_at timestamp with time zone, downline_players integer, downline_rake numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_root uuid := COALESCE(p_agent_user_id, auth.uid());
  v_from timestamptz := COALESCE(p_since, public.fn_union_week_start(now()));
  v_to   timestamptz := COALESCE(p_until, now());
  v_caller uuid := auth.uid();
  v_today  timestamptz := date_trunc('day', now());
  v_day_lo date;
  v_day_hi date;
  v_head_end   timestamptz;
  v_tail_start timestamptz;
BEGIN
  IF v_root IS NULL THEN RAISE EXCEPTION 'no_agent'; END IF;

  IF NOT EXISTS (SELECT 1 FROM agents a
                  WHERE a.user_id = v_root AND a.status='active'
                    AND a.role IN ('super_agent','agent','sub_agent')
                    AND (p_club_id IS NULL OR a.club_id = p_club_id)) THEN
    RAISE EXCEPTION 'not_an_agent';
  END IF;

  IF v_caller IS NOT NULL
     AND v_caller <> v_root
     AND NOT public.fn_is_agent_ancestor(v_caller, v_root, p_club_id)
     AND NOT EXISTS (
       SELECT 1 FROM union_clubs uc
        WHERE (p_club_id IS NULL OR uc.club_id = p_club_id)
          AND public.fn_is_union_overseer(uc.union_id, v_caller))
     AND NOT (p_club_id IS NOT NULL AND public.fn_is_club_admin_uid(p_club_id))
  THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  v_day_lo := date_trunc('day', v_from)::date;
  IF date_trunc('day', v_from) < v_from THEN v_day_lo := v_day_lo + 1; END IF;
  v_day_hi := LEAST(date_trunc('day', v_to), v_today)::date;
  IF v_day_hi < v_day_lo THEN v_day_hi := v_day_lo; END IF;

  v_head_end   := LEAST(v_day_lo::timestamptz, v_to);
  v_tail_start := GREATEST(v_day_hi::timestamptz, v_from);

  RETURN QUERY
  WITH RECURSIVE chain AS (
    SELECT a.id, a.user_id, a.club_id, a.role, a.parent_agent_id, 0 AS depth
      FROM agents a
     WHERE a.user_id = v_root AND a.status = 'active'
       AND (p_club_id IS NULL OR a.club_id = p_club_id)
    UNION ALL
    SELECT c.id, c.user_id, c.club_id, c.role, c.parent_agent_id, ch.depth + 1
      FROM agents c JOIN chain ch ON c.parent_agent_id = ch.id
     WHERE c.status = 'active'
  ),
  roster AS (
    SELECT DISTINCT cm.user_id AS player_id, cm.club_id, cm.agent_id AS upline_user_id,
           ch.depth + 1 AS depth
      FROM club_members cm
      JOIN chain ch ON ch.user_id = cm.agent_id AND ch.club_id = cm.club_id
     WHERE cm.agent_id IS NOT NULL
  ),
  everyone AS MATERIALIZED (
    SELECT player_id, club_id, upline_user_id, depth FROM roster
    UNION
    SELECT ch.user_id, ch.club_id,
           (SELECT p.user_id FROM agents p WHERE p.id = ch.parent_agent_id),
           ch.depth
      FROM chain ch WHERE ch.depth > 0
  ),
  in_scope_clubs AS MATERIALIZED (SELECT DISTINCT club_id FROM everyone),
  ok_days AS MATERIALIZED (
    SELECT rc.club_id, rc.day
      FROM club_rake_rollup_complete rc
      JOIN in_scope_clubs c ON c.club_id = rc.club_id
     WHERE rc.day >= v_day_lo AND rc.day < v_day_hi
  ),
  gap_days AS MATERIALIZED (
    SELECT c.club_id, g::date AS day
      FROM in_scope_clubs c
      CROSS JOIN generate_series(v_day_lo, v_day_hi - 1, interval '1 day') g
     WHERE v_day_hi > v_day_lo
       AND NOT EXISTS (SELECT 1 FROM ok_days o
                        WHERE o.club_id = c.club_id AND o.day = g::date)
  ),
  from_rollup AS (
    SELECT rd.user_id, rd.club_id,
           SUM(rd.rake_amount) AS rake,
           SUM(rd.hands)::bigint AS hands,
           MAX((rd.day + 1)::timestamptz) AS last_at
      FROM club_rake_daily_user rd
      JOIN ok_days o  ON o.club_id = rd.club_id AND o.day = rd.day
      JOIN everyone e ON e.player_id = rd.user_id AND e.club_id = rd.club_id
     GROUP BY rd.user_id, rd.club_id
  ),
  edge_hands AS MATERIALIZED (
    SELECT r.id, r.hand_id, r.club_id, r.created_at, r.rake_amount, r.player_contributions, r.rake_method
      FROM rake_records r
     WHERE r.created_at >= v_from AND r.created_at < v_head_end
       AND r.rake_amount > 0 AND r.player_contributions IS NOT NULL
       AND (p_club_id IS NULL OR r.club_id = p_club_id)
    UNION ALL
    SELECT r.id, r.hand_id, r.club_id, r.created_at, r.rake_amount, r.player_contributions, r.rake_method
      FROM rake_records r
     WHERE r.created_at >= v_tail_start AND r.created_at < v_to
       AND r.rake_amount > 0 AND r.player_contributions IS NOT NULL
       AND (p_club_id IS NULL OR r.club_id = p_club_id)
    UNION ALL
    SELECT r.id, r.hand_id, r.club_id, r.created_at, r.rake_amount, r.player_contributions, r.rake_method
      FROM gap_days gd
      JOIN rake_records r
        ON r.club_id = gd.club_id
       AND r.created_at >= gd.day::timestamptz
       AND r.created_at <  (gd.day + 1)::timestamptz
     WHERE r.rake_amount > 0 AND r.player_contributions IS NOT NULL
  ),
  -- LEDGER-READ (2026-08-29): stored per-player credits when present, the
  -- canonical allocator when not.
  edge_split AS MATERIALIZED (
    SELECT s.user_id, eh.club_id, eh.created_at,
           round(s.credit * 100)::bigint AS cents
      FROM edge_hands eh
      CROSS JOIN LATERAL public.fn_rake_shares_for_record(
        eh.hand_id, eh.rake_amount, eh.player_contributions, COALESCE(eh.rake_method, 'DEALT_EQUAL')
      ) s
  ),
  from_live AS (
    SELECT s.user_id, s.club_id,
           SUM(s.cents)::numeric / 100 AS rake,
           count(*)::bigint AS hands,
           max(s.created_at) AS last_at
      FROM edge_split s
      JOIN everyone e ON e.player_id = s.user_id AND e.club_id = s.club_id
     GROUP BY s.user_id, s.club_id
  ),
  earned AS MATERIALIZED (
    SELECT COALESCE(a.user_id, b.user_id) AS user_id,
           COALESCE(a.club_id, b.club_id) AS club_id,
           COALESCE(a.rake,0) + COALESCE(b.rake,0)   AS rake,
           COALESCE(a.hands,0) + COALESCE(b.hands,0) AS hands,
           GREATEST(COALESCE(a.last_at,'-infinity'::timestamptz),
                    COALESCE(b.last_at,'-infinity'::timestamptz)) AS last_at
      FROM from_rollup a
      FULL OUTER JOIN from_live b ON b.user_id = a.user_id AND b.club_id = a.club_id
  ),
  downline_agg AS MATERIALIZED (
    SELECT cm.agent_id AS upline, cm.club_id, SUM(ea.rake) AS rake
      FROM earned ea
      JOIN club_members cm ON cm.user_id = ea.user_id AND cm.club_id = ea.club_id
     WHERE cm.agent_id IS NOT NULL
     GROUP BY cm.agent_id, cm.club_id
  ),
  downline_cnt AS MATERIALIZED (
    SELECT cm.agent_id AS upline, cm.club_id, count(*)::int AS players
      FROM club_members cm
     WHERE cm.agent_id IN (SELECT player_id FROM everyone)
     GROUP BY cm.agent_id, cm.club_id
  )
  SELECT e.player_id,
         COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), pr.username, left(e.player_id::text, 8)),
         e.club_id, cl.name,
         COALESCE(ag.role, 'player'),
         e.depth, e.upline_user_id,
         COALESCE(public.fn_arena_name(up.alias, up.username, up.display_name, up.first_name, up.last_name, up.full_name), up.username),
         COALESCE(ea.rake, 0), COALESCE(ea.hands, 0),
         NULLIF(ea.last_at, '-infinity'::timestamptz),
         COALESCE(dc.players, 0), COALESCE(da.rake, 0)
    FROM everyone e
    LEFT JOIN earned ea       ON ea.user_id = e.player_id AND ea.club_id = e.club_id
    LEFT JOIN downline_agg da ON da.upline  = e.player_id AND da.club_id = e.club_id
    LEFT JOIN downline_cnt dc ON dc.upline  = e.player_id AND dc.club_id = e.club_id
    LEFT JOIN profiles pr ON pr.id = e.player_id
    LEFT JOIN profiles up ON up.id = e.upline_user_id
    LEFT JOIN clubs cl    ON cl.id = e.club_id
    LEFT JOIN agents ag   ON ag.user_id = e.player_id AND ag.club_id = e.club_id
                         AND ag.status = 'active'
   WHERE (p_search IS NULL OR p_search = ''
          OR COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), pr.username, '') ILIKE '%' || p_search || '%')
   ORDER BY COALESCE(ea.rake, 0) DESC
   LIMIT GREATEST(COALESCE(p_limit, 500), 1);
END $$;


ALTER FUNCTION public.fn_agent_downline_rake(p_agent_user_id uuid, p_club_id uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_search text, p_limit integer) OWNER TO postgres;

--
-- Name: fn_agent_downline_rake_summary(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_downline_rake_summary(p_agent_user_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_root uuid := COALESCE(p_agent_user_id, auth.uid());
  v_from timestamptz := COALESCE(p_since, public.fn_union_week_start(now()));
  v_to   timestamptz := COALESCE(p_until, now());
  v_rate numeric;
  v_members int := 0; v_active int := 0; v_direct int := 0; v_subs int := 0;
  v_hands bigint := 0; v_rake numeric := 0; v_last timestamptz;
  v_top_name text; v_top_rake numeric;
BEGIN
  SELECT a.commission_rate INTO v_rate
    FROM agents a
   WHERE a.user_id = v_root AND a.status='active'
     AND (p_club_id IS NULL OR a.club_id = p_club_id)
   ORDER BY a.commission_rate DESC NULLS LAST
   LIMIT 1;

  -- One execution, one pass.
  SELECT count(*),
         count(*) FILTER (WHERE d.hands > 0),
         count(*) FILTER (WHERE d.depth = 1),
         count(*) FILTER (WHERE d.role IN ('agent','sub_agent','super_agent')),
         COALESCE(SUM(d.hands), 0),
         COALESCE(ROUND(SUM(d.rake_generated), 2), 0),
         MAX(d.last_hand_at),
         (array_agg(d.username     ORDER BY d.rake_generated DESC))[1],
         (array_agg(d.rake_generated ORDER BY d.rake_generated DESC))[1]
    INTO v_members, v_active, v_direct, v_subs, v_hands, v_rake, v_last,
         v_top_name, v_top_rake
    FROM public.fn_agent_downline_rake(v_root, p_club_id, v_from, v_to, NULL, 100000) d;

  RETURN jsonb_build_object(
    'period_start', v_from,
    'period_end',   v_to,
    'members',      v_members,
    'active',       v_active,
    'direct',       v_direct,
    'sub_agents',   v_subs,
    'hands',        v_hands,
    'rake_generated', v_rake,
    'commission_rate', COALESCE(v_rate, 0),
    'estimated_commission', ROUND(v_rake * COALESCE(v_rate, 0), 2),
    'last_hand_at', v_last,
    'top_earner', CASE WHEN v_top_name IS NULL THEN NULL
                       ELSE jsonb_build_object('username', v_top_name, 'rake', v_top_rake) END
  );
END $$;


ALTER FUNCTION public.fn_agent_downline_rake_summary(p_agent_user_id uuid, p_club_id uuid, p_since timestamp with time zone, p_until timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_agent_may_read_commission(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_may_read_commission(p_club_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  -- The engine and the API routes.
  IF public.fn_is_service_context() THEN
    RETURN true;
  END IF;

  -- A logged-out caller reads nothing.
  IF v_uid IS NULL THEN
    RETURN false;
  END IF;

  -- Yourself.
  IF v_uid = p_user_id THEN
    RETURN true;
  END IF;

  IF p_club_id IS NULL THEN
    RETURN false;
  END IF;

  -- An officer of that club. fn_role_rank: owner 7, co_owner 6, admin 5.
  IF public.fn_has_club_role(v_uid, p_club_id, 'admin') THEN
    RETURN true;
  END IF;

  -- Your own downline, at any depth - the same relationship
  -- fn_agent_downline_commission already reports on, so it grants nothing new.
  RETURN public.fn_is_agent_ancestor(v_uid, p_user_id, p_club_id);
END
$$;


ALTER FUNCTION public.fn_agent_may_read_commission(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_agent_may_read_commission(p_club_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_agent_may_read_commission(p_club_id uuid, p_user_id uuid) IS 'Who may see what a club owes a member. One definition, reused - do not write a second one next to a new commission surface.';


--
-- Name: fn_agent_player_breakdown(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_player_breakdown(p_agent_user_id uuid DEFAULT NULL::uuid, p_period_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(player_id uuid, username text, club_id uuid, rake_generated numeric, player_net numeric, rakeback_rate numeric, rakeback_due numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent uuid := COALESCE(p_agent_user_id, auth.uid());
  v_from  timestamptz := COALESCE(p_period_start, fn_union_week_start());
  v_to    timestamptz := COALESCE(p_period_end, now());
BEGIN
  IF v_agent IS NULL THEN
    RAISE EXCEPTION 'no_agent_context' USING ERRCODE = '42704';
  END IF;

  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( auth.uid() <> v_agent
     AND NOT public.fn_is_any_union_overseer(auth.uid()))) THEN
    RAISE EXCEPTION 'not_authorised' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH roster AS (
    -- club_members.agent_id stores the agent's USER id, not agents.id
    SELECT DISTINCT cm.user_id AS player_id, cm.club_id
      FROM club_members cm
     WHERE cm.agent_id = v_agent
  ),
  deal AS (
    SELECT r.club_id, MAX(COALESCE(a.player_rakeback_rate, 0)) AS rb
      FROM roster r
      LEFT JOIN agents a ON a.user_id = v_agent AND a.club_id = r.club_id
     GROUP BY r.club_id
  ),
  ut AS (
    SELECT t.id FROM tables t
     WHERE t.union_id IS NOT NULL AND t.tournament_id IS NULL
  ),
  rake AS (
    SELECT u.user_id, round(SUM(u.rake_amount), 2) AS amt
      FROM union_rake_paid_daily_user u
      JOIN roster r ON r.player_id = u.user_id
     WHERE u.day >= (v_from AT TIME ZONE 'UTC')::date
       AND u.day <= (v_to   AT TIME ZONE 'UTC')::date
     GROUP BY u.user_id
  ),
  flows AS (
    SELECT wt.user_id,
           round(SUM(CASE WHEN wt.type = 'credit' THEN wt.amount ELSE -wt.amount END), 2) AS pnl
      FROM wallet_transactions wt
      JOIN roster r ON r.player_id = wt.user_id
     WHERE wt.created_at >= v_from AND wt.created_at < v_to
       AND wt.category IN ('buyin','cashout')
       AND wt.table_id IN (SELECT id FROM ut)
     GROUP BY wt.user_id
  )
  SELECT r.player_id,
         COALESCE(p.username, p.display_name, left(r.player_id::text, 8))::text,
         r.club_id,
         COALESCE(rake.amt, 0),
         COALESCE(flows.pnl, 0),
         COALESCE(d.rb, 0),
         round(COALESCE(rake.amt, 0) * COALESCE(d.rb, 0), 2)
    FROM roster r
    LEFT JOIN profiles p ON p.id = r.player_id
    LEFT JOIN deal d     ON d.club_id = r.club_id
    LEFT JOIN rake       ON rake.user_id = r.player_id
    LEFT JOIN flows      ON flows.user_id = r.player_id
   ORDER BY COALESCE(rake.amt, 0) DESC;
END;
$$;


ALTER FUNCTION public.fn_agent_player_breakdown(p_agent_user_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_agent_roster_report(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_roster_report(p_agent_user_id uuid DEFAULT NULL::uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(player_id uuid, username text, club_id uuid, club_name text, buyins numeric, cashouts numeric, net_result numeric, rake_generated numeric, agent_commission numeric, chip_balance numeric, credit_used numeric, currently_seated boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent uuid := COALESCE(p_agent_user_id, auth.uid());
  v_from  timestamptz := COALESCE(p_since, public.fn_union_week_start(now()));
  v_to    timestamptz := COALESCE(p_until, now());
BEGIN
  IF v_agent IS NULL THEN RAISE EXCEPTION 'no_agent_context'; END IF;
  -- A caller may only pull their OWN roster unless they oversee the union.
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( auth.uid() <> v_agent
     AND NOT public.fn_is_any_union_overseer(auth.uid()))) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  RETURN QUERY
  WITH roster AS (
    SELECT DISTINCT m.user_id, m.club_id, m.chip_balance, m.credit_used
      FROM club_members m
     WHERE m.agent_id = v_agent
        OR EXISTS (SELECT 1 FROM agents child
                    JOIN agents parent ON parent.id = child.parent_agent_id
                   WHERE child.user_id = m.agent_id AND parent.user_id = v_agent)
  ),
  flows AS (
    SELECT wt.user_id,
           SUM(CASE WHEN wt.type='debit'  AND wt.category IN ('buyin','rebuy','addon') THEN wt.amount ELSE 0 END) AS buyins,
           SUM(CASE WHEN wt.type='credit' AND wt.category='cashout' THEN wt.amount ELSE 0 END) AS cashouts
      FROM wallet_transactions wt
      JOIN roster r ON r.user_id = wt.user_id
     WHERE wt.created_at >= v_from AND wt.created_at < v_to
     GROUP BY wt.user_id
  ),
  rake AS (
    SELECT (e.key)::uuid AS user_id,
           SUM(rr.rake_amount * (e.value::numeric) / NULLIF(c.total,0)) AS rake_generated
      FROM rake_records rr
      CROSS JOIN LATERAL (SELECT SUM(t.value::numeric) AS total
                            FROM jsonb_each_text(rr.player_contributions) t(key,value)) c
      CROSS JOIN LATERAL jsonb_each_text(rr.player_contributions) e(key,value)
     WHERE rr.created_at >= v_from AND rr.created_at < v_to
       AND rr.player_contributions IS NOT NULL AND c.total > 0
       AND EXISTS (SELECT 1 FROM roster r WHERE r.user_id = (e.key)::uuid)
     GROUP BY 1
  ),
  comm AS (
    SELECT ac.club_id, SUM(ac.amount) AS amt
      FROM agent_commissions ac
     WHERE ac.user_id = v_agent AND ac.created_at >= v_from AND ac.created_at < v_to
     GROUP BY ac.club_id
  )
  SELECT r.user_id, pr.username, r.club_id, cl.name,
         COALESCE(f.buyins,0), COALESCE(f.cashouts,0),
         COALESCE(f.cashouts,0) - COALESCE(f.buyins,0),
         ROUND(COALESCE(rk.rake_generated,0),2),
         ROUND(COALESCE(cm2.amt,0),2),
         COALESCE(r.chip_balance,0), COALESCE(r.credit_used,0),
         EXISTS (SELECT 1 FROM table_seats ts WHERE ts.user_id = r.user_id AND ts.left_at IS NULL)
    FROM roster r
    LEFT JOIN profiles pr ON pr.id = r.user_id
    LEFT JOIN clubs cl ON cl.id = r.club_id
    LEFT JOIN flows f ON f.user_id = r.user_id
    LEFT JOIN rake rk ON rk.user_id = r.user_id
    LEFT JOIN comm cm2 ON cm2.club_id = r.club_id
   ORDER BY 8 DESC NULLS LAST;
END $$;


ALTER FUNCTION public.fn_agent_roster_report(p_agent_user_id uuid, p_since timestamp with time zone, p_until timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_agent_unsettled_commission(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_unsettled_commission(p_club_id uuid, p_user_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_club_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'fn_agent_unsettled_commission needs a club and a user'
      USING ERRCODE = '22023';
  END IF;

  IF NOT public.fn_agent_may_read_commission(p_club_id, p_user_id) THEN
    -- Not a zero. A zero is indistinguishable from "owes nothing", and this
    -- caller is not entitled to know which of the two it is.
    RAISE EXCEPTION 'not authorized to read that member''s commission'
      USING ERRCODE = '42501';
  END IF;

  RETURN (
    SELECT COALESCE(SUM(ac.amount), 0)::numeric
      FROM public.agent_commissions ac
     WHERE ac.club_id = p_club_id
       AND ac.user_id = p_user_id
       AND ac.settled_at IS NULL
       AND NOT EXISTS (SELECT 1 FROM public.agent_commission_settlements s
                        WHERE s.club_id = ac.club_id AND s.user_id = ac.user_id
                          AND ac.created_at >= s.period_start AND ac.created_at < s.period_end));
END
$$;


ALTER FUNCTION public.fn_agent_unsettled_commission(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_agent_unsettled_commission(p_club_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_agent_unsettled_commission(p_club_id uuid, p_user_id uuid) IS 'What a club still owes one member, from agent_commissions. Guarded by fn_agent_may_read_commission: self, club admin+, agent ancestor, or service role. Raises 42501 otherwise - never a zero, which would be a lie.';


--
-- Name: fn_agent_wallet_claim_back(uuid, uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_wallet_claim_back(p_club_id uuid, p_transaction_id uuid, p_amount numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    return jsonb_build_object('success',false,'error','Not Authenticated');
  end if;
  if p_op_id is null then
    return jsonb_build_object('success',false,'error','A Retry Key Is Required For Every Claim Back');
  end if;
  return public.fn_agent_wallet_claim_back_phase2_core_20260831(
    p_club_id,p_transaction_id,p_amount,p_reason,p_op_id
  );
end
$$;


ALTER FUNCTION public.fn_agent_wallet_claim_back(p_club_id uuid, p_transaction_id uuid, p_amount numeric, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_agent_wallet_claim_back_phase2_core_20260831(uuid, uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_wallet_claim_back_phase2_core_20260831(p_club_id uuid, p_transaction_id uuid, p_amount numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_context jsonb;
  v_setting text;
  v_actor            uuid := auth.uid();
  v_op_id            uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior            record;
  v_src              record;
  v_claimed          numeric;
  v_claimed_after    numeric;
  v_remaining_exact  numeric;
  v_remaining        numeric;
  v_take             numeric;
  v_complete         boolean;
  v_dest             text;
  v_held             numeric;
  v_agent_id         uuid;
  v_float_after      numeric;
  v_holder_after     numeric;
  v_tx_id            uuid;
  v_drawn            numeric;
  v_repaid           numeric;
  v_repay            numeric := 0;
  v_my_agent_id      uuid;
  v_my_used          numeric;
  v_credit_after     numeric;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;
  if p_club_id is null or p_transaction_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose A Recent Agent Wallet Send');
  end if;
  if p_amount is not null and
     (p_amount <= 0 or p_amount > 1e9 or p_amount <> round(p_amount, 2)) then
    return jsonb_build_object(
      'success', false,
      'error', 'Claim Back Amounts Must Be Positive Whole Cents');
  end if;

  -- One caller/op pair is serialized, so two simultaneous retries cannot both
  -- pass the replay read and enter the money section.
  perform pg_advisory_xact_lock(hashtextextended(
    'agent-wallet-claim:' || p_club_id::text || ':' || v_actor::text || ':' || v_op_id::text,
    0
  ));

  select id, amount, metadata into v_prior
    from public.chip_transactions
   where club_id = p_club_id
     and transaction_type = 'agent_wallet_claim_back'
     and to_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    if coalesce(v_prior.metadata ->> 'original_transaction_id', '')
         is distinct from p_transaction_id::text
       or (p_amount is not null and v_prior.amount is distinct from p_amount) then
      return jsonb_build_object(
        'success', false,
        'error', 'That Retry Key Belongs To A Different Claim Back');
    end if;
    return jsonb_build_object(
      'success', true,
      'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'agent_wallet_after', (v_prior.metadata ->> 'agent_wallet_after')::numeric,
      'credit_repaid', coalesce((v_prior.metadata ->> 'credit_repaid')::numeric, 0),
      'credit_used_after', (v_prior.metadata ->> 'credit_used_after')::numeric);
  end if;

  select * into v_src
    from public.chip_transactions
   where id = p_transaction_id
     and club_id = p_club_id
   for update;
  if v_src is null then
    return jsonb_build_object('success', false, 'error', 'That Send Could Not Be Found');
  end if;
  if v_src.transaction_type <> 'agent_wallet_send' then
    return jsonb_build_object(
      'success', false,
      'error', 'Only An Agent Wallet Send Can Be Claimed Back This Way');
  end if;
  if v_src.from_user_id is distinct from v_actor then
    return jsonb_build_object(
      'success', false,
      'error', 'You Can Only Claim Back Chips You Sent Yourself');
  end if;
  if coalesce(v_src.is_reversed, false) then
    return jsonb_build_object('success', false, 'error', 'That Send Has Already Been Claimed Back');
  end if;
  if v_src.reversible_until is null or now() > v_src.reversible_until then
    return jsonb_build_object(
      'success', false,
      'error', 'The Ten Minute Window To Claim These Chips Back Has Closed. '
               || 'The Player Must Request A Cash Out Instead');
  end if;

  v_claimed := coalesce((v_src.metadata ->> 'claimed_back')::numeric, 0);
  v_remaining_exact := greatest(v_src.amount - v_claimed, 0);

  -- Round DOWN, never to nearest. A historical 9.9951 remainder can safely
  -- return 9.99; rounding it to 10.00 would create another 0.0049 chips.
  v_remaining := trunc(v_remaining_exact, 2);
  if v_remaining < 0.01 then
    return jsonb_build_object('success', false, 'error', 'That Send Has Already Been Claimed Back');
  end if;

  -- Null means all safely claimable whole cents. This is what the cashier uses
  -- so contaminated historical rows can be closed without echoing sub-cents.
  v_take := coalesce(p_amount, v_remaining);
  if v_take > v_remaining then
    return jsonb_build_object(
      'success', false,
      'error', 'Only ' || trim(to_char(v_remaining, 'FM999,999,999,990.00'))
               || ' Chips Of That Send Are Left To Claim Back',
      'remaining', v_remaining,
      'requested', v_take);
  end if;

  v_claimed_after := v_claimed + v_take;
  v_complete := (v_src.amount - v_claimed_after) < 0.01;

  v_dest := coalesce(v_src.metadata ->> 'destination', 'player_wallet');
  if v_dest = 'player_wallet' then
    select coalesce(chip_balance, 0) into v_held
      from public.club_members
     where club_id = p_club_id and user_id = v_src.to_user_id
     for update;
  else
    select a.id, coalesce(a.agent_wallet_balance, 0) into v_agent_id, v_held
      from public.agents a
     where a.club_id = p_club_id and a.user_id = v_src.to_user_id
     for update;
  end if;

  if v_held is null then
    return jsonb_build_object(
      'success', false,
      'error', 'That Wallet Could Not Be Read, So Nothing Was Moved');
  end if;
  if v_held < v_take then
    return jsonb_build_object(
      'success', false,
      'error', 'Those Chips Have Already Been Spent. That Wallet Only Holds '
               || trim(to_char(v_held, 'FM999,999,999,990.00')) || ' Chips',
      'held', v_held,
      'requested', v_take);
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): a claim back is ONE `agent_claim` row from
  -- the wallet that held the send back to the agent's float, keyed and
  -- correlated on the op. The agents trigger is skipped for both float
  -- writes: a player holder's club_members trigger writes the row with the
  -- agent's float as counterparty; an agent holder (both sides in `agents`)
  -- gets the row posted explicitly below. The share that repays the credit
  -- line never reaches the float, so it is its own `credit_repayment
  -- agent_wallet -> credit_facility` row. Never a refusal.
  select jsonb_object_agg(k,coalesce(current_setting(k,true),'')) into v_context
   from unnest(array['app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_tournament','app.ledger_settlement','app.ledger_idempotency_key','app.ledger_correlation','app.ledger_autoskip_agents']) settings(k);
  perform set_config('app.ledger_tournament','',true);
  perform set_config('app.ledger_settlement','',true);
  perform public.fn_ca_declare_ledger('agent_claim', 'agent_wallet', v_actor, null,
    'agent_claim:' || v_op_id::text, array['agents']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  if v_dest = 'player_wallet' then
    update public.club_members
       set chip_balance = coalesce(chip_balance, 0) - v_take,
           updated_at = now()
     where club_id = p_club_id and user_id = v_src.to_user_id
     returning chip_balance into v_holder_after;
  else
    update public.agents
       set agent_wallet_balance = coalesce(agent_wallet_balance, 0) - v_take,
           updated_at = now()
     where id = v_agent_id
     returning agent_wallet_balance into v_holder_after;
    perform set_config('app.ledger_idempotency_key', '', true);
    perform public.fn_ca_post_leg('agent_claim', 'agent_wallet', v_src.to_user_id, 'agent_wallet', v_actor,
      v_take, p_club_id, 'agent_claim:' || v_op_id::text,
      'Agent wallet claim back from a downline agent wallet (fn_agent_wallet_claim_back_phase2_core_20260831)');
  end if;

  -- HOW MUCH OF THIS CLAIM IS A REPAYMENT.
  --
  -- credit_drawn is what this send borrowed; credit_repaid is how much of that
  -- borrowing earlier partial claims have already handed back. The share of a
  -- partial claim is proportional, truncated down so repeated partials can
  -- never repay more than was drawn. The final claim settles the exact
  -- remainder, so truncation cannot strand a cent of debt on a send that has
  -- been returned in full.
  v_drawn  := coalesce((v_src.metadata ->> 'credit_drawn')::numeric, 0);
  v_repaid := coalesce((v_src.metadata ->> 'credit_repaid')::numeric, 0);

  select a.id, coalesce(a.credit_used, 0) into v_my_agent_id, v_my_used
    from public.agents a
   where a.club_id = p_club_id and a.user_id = v_actor
   for update;
  if v_my_agent_id is null then
    raise exception 'agent wallet row vanished for % in club %', v_actor, p_club_id;
  end if;

  if v_drawn > 0 then
    if v_complete then
      v_repay := greatest(v_drawn - v_repaid, 0);
    else
      v_repay := least(trunc(v_drawn * v_take / v_src.amount, 2),
                       greatest(v_drawn - v_repaid, 0));
    end if;
    -- The debt may already have been settled another way: an invoice paid
    -- inside the ten minute window pays credit_used down (phase 1), and paying
    -- twice for the same borrowing would hand the agent free chips.
    v_repay := greatest(least(v_repay, v_my_used), 0);
  end if;

  if v_repay > 0 then
    perform public.fn_ca_post_leg('credit_repayment', 'agent_wallet', v_actor, 'credit_facility', v_actor,
      v_repay, p_club_id, 'agent_claim:credit:' || v_op_id::text,
      'Claimed back chips repay the credit line drawn for the send (fn_agent_wallet_claim_back_phase2_core_20260831)');
  end if;

  -- Every chip returns: what is not repaying a debt becomes float.
  update public.agents
     set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + (v_take - v_repay),
         credit_used          = greatest(coalesce(credit_used, 0) - v_repay, 0),
         updated_at = now()
   where id = v_my_agent_id
   returning agent_wallet_balance, credit_used into v_float_after, v_credit_after;
  for v_setting in select jsonb_object_keys(v_context) loop
    perform set_config(v_setting,v_context->>v_setting,true);
  end loop;

  update public.chip_transactions
     set metadata = coalesce(metadata, '{}'::jsonb)
                    || jsonb_build_object('claimed_back', v_claimed_after,
                                          'credit_repaid', v_repaid + v_repay),
         is_reversed = v_complete,
         clawed_back = v_complete
   where id = v_src.id;

  insert into public.chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (p_club_id, v_src.to_user_id, v_actor, v_take, 'agent_wallet_claim_back',
     coalesce(nullif(btrim(p_reason), ''), 'Agent Wallet Claim Back Inside The Ten Minute Window'),
     jsonb_build_object(
       'op_id', v_op_id,
       'source', v_dest,
       'original_transaction_id', v_src.id,
       'holder_balance_after', v_holder_after,
       'agent_wallet_after', v_float_after,
       'credit_repaid', v_repay,
       'credit_used_after', v_credit_after),
     v_float_after)
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true,
    'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', v_take,
    'source', v_dest,
    'holder_balance_after', v_holder_after,
    'agent_wallet_after', v_float_after,
    'credit_repaid', v_repay,
    'credit_used_after', v_credit_after);
exception
  when unique_violation then
    select id, amount, metadata into v_prior
      from public.chip_transactions
     where club_id = p_club_id
       and transaction_type = 'agent_wallet_claim_back'
       and to_user_id = v_actor
       and metadata ->> 'op_id' = v_op_id::text
     limit 1;
    if v_prior.id is null then
      raise;
    end if;
    if coalesce(v_prior.metadata ->> 'original_transaction_id', '')
         is distinct from p_transaction_id::text
       or (p_amount is not null and v_prior.amount is distinct from p_amount) then
      return jsonb_build_object(
        'success', false,
        'error', 'That Retry Key Belongs To A Different Claim Back');
    end if;
    return jsonb_build_object(
      'success', true,
      'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'agent_wallet_after', (v_prior.metadata ->> 'agent_wallet_after')::numeric,
      'credit_repaid', coalesce((v_prior.metadata ->> 'credit_repaid')::numeric, 0),
      'credit_used_after', (v_prior.metadata ->> 'credit_used_after')::numeric);
end
$$;


ALTER FUNCTION public.fn_agent_wallet_claim_back_phase2_core_20260831(p_club_id uuid, p_transaction_id uuid, p_amount numeric, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_agent_wallet_claim_back_phase2_core_20260831(p_club_id uuid, p_transaction_id uuid, p_amount numeric, p_reason text, p_op_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_agent_wallet_claim_back_phase2_core_20260831(p_club_id uuid, p_transaction_id uuid, p_amount numeric, p_reason text, p_op_id uuid) IS 'Cent-conserving ten-minute reversal of one caller-owned agent wallet send. Null amount means all safely claimable whole cents; replay keys are bound to source and amount.';


--
-- Name: fn_agent_wallet_reversible(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_wallet_reversible(p_club_id uuid) RETURNS TABLE(transaction_id uuid, to_user_id uuid, to_name text, amount numeric, claimed_back numeric, remaining numeric, destination text, created_at timestamp with time zone, reversible_until timestamp with time zone, seconds_left integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select t.id,
         t.to_user_id,
         coalesce(
           nullif(btrim(pr.display_name), ''),
           nullif(btrim(pr.alias), ''),
           nullif(btrim(pr.username), ''),
           'Member'
         )::text,
         t.amount,
         coalesce((t.metadata ->> 'claimed_back')::numeric, 0),
         t.amount - coalesce((t.metadata ->> 'claimed_back')::numeric, 0),
         coalesce(t.metadata ->> 'destination', 'player_wallet'),
         t.created_at,
         t.reversible_until,
         greatest(0, ceil(extract(epoch from (t.reversible_until - now()))))::int
    from chip_transactions t
    left join profiles pr on pr.id = t.to_user_id
   where t.club_id = p_club_id
     and t.transaction_type = 'agent_wallet_send'
     and t.from_user_id = auth.uid()
     and coalesce(t.is_reversed, false) = false
     and t.reversible_until is not null
     and t.reversible_until > now()
     and t.amount - coalesce((t.metadata ->> 'claimed_back')::numeric, 0) > 0
   order by t.created_at desc
   limit 50;
$$;


ALTER FUNCTION public.fn_agent_wallet_reversible(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_agent_wallet_reversible(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_agent_wallet_reversible(p_club_id uuid) IS 'The callers own agent wallet sends still inside their ten minute clawback window.';


--
-- Name: fn_agent_wallet_self_stake(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_wallet_self_stake(p_club_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_prior record;
  v_role text;
  v_wallet_after numeric;
  v_player_after numeric;
  v_tx uuid;
  v_context jsonb;
  v_setting text;
begin
  if v_actor is null then
    return jsonb_build_object('success',false,'error','Not Authenticated');
  end if;
  if p_op_id is null then
    return jsonb_build_object('success',false,'error','A Retry Key Is Required For Every Send');
  end if;
  if p_club_id is null then
    return jsonb_build_object('success',false,'error','That Club Could Not Be Found');
  end if;
  if p_amount is null or p_amount <= 0 or p_amount > 1e9 or p_amount <> round(p_amount,2) then
    return jsonb_build_object('success',false,'error','Enter A Valid Send Amount');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'agent-wallet-send:'||p_club_id::text||':'||v_actor::text||':'||p_op_id::text,0));
  perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||p_club_id::text,0));

  select ct.* into v_prior from public.chip_transactions ct
   where ct.club_id=p_club_id and ct.transaction_type='agent_wallet_self_stake'
     and ct.from_user_id=v_actor and ct.metadata->>'op_id'=p_op_id::text limit 1;
  if found then
    if v_prior.amount is distinct from p_amount then
      return jsonb_build_object('success',false,
        'error','That Retry Key Belongs To A Different Agent Wallet Send');
    end if;
    return jsonb_build_object('success',true,'replayed',true,
      'transaction_id',v_prior.id,'amount',v_prior.amount,
      'agent_wallet_after',(v_prior.metadata->>'agent_wallet_after')::numeric,
      'player_wallet_after',(v_prior.metadata->>'player_wallet_after')::numeric);
  end if;

  perform 1 from public.clubs where id=p_club_id for update;
  if not found then
    return jsonb_build_object('success',false,'error','That Club Could Not Be Found');
  end if;
  perform 1 from public.club_members where club_id=p_club_id and user_id=v_actor for update;

  v_role := public.fn_club_bank_role(p_club_id, v_actor);
  -- Dan 2026-09-02: owners and co-owners hold a player wallet again, and they
  -- have always held an agent wallet, so the rung exists for them too. An
  -- admin holds no player wallet, so there is nowhere for the chips to land.
  if v_role is null or v_role not in ('owner','co_owner','super_agent','agent','sub_agent') then
    return jsonb_build_object('success',false,'error','Only An Agent Wallet Holder With A Player Wallet Can Stake Their Own Seat');
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): ONE `agent_send` row from the agent's own
  -- float to their own player wallet, keyed and correlated on the op (32
  -- stakes / 320,000.00 in 30d journaled as two suspense legs). The agents
  -- trigger is skipped; the club_members trigger writes the row.
  SELECT jsonb_object_agg(k,coalesce(current_setting(k,true),'')) INTO v_context
   FROM unnest(array['app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_tournament','app.ledger_settlement','app.ledger_idempotency_key','app.ledger_correlation','app.ledger_autoskip_agents']) settings(k);
  PERFORM set_config('app.ledger_tournament','',true);
  PERFORM set_config('app.ledger_settlement','',true);
  perform public.fn_ca_declare_ledger('agent_send', 'agent_wallet', v_actor, null,
    'agent_self_stake:' || p_op_id::text, array['agents']);
  perform set_config('app.ledger_correlation', p_op_id::text, true);

  update public.agents
     set agent_wallet_balance = agent_wallet_balance - p_amount
   where club_id=p_club_id and user_id=v_actor
     and coalesce(status,'active')='active'
     and agent_wallet_balance >= p_amount
   returning agent_wallet_balance into v_wallet_after;
  if v_wallet_after is null then
  FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
    PERFORM set_config(v_setting,v_context->>v_setting,true);
  END LOOP;
    return jsonb_build_object('success',false,'error','Your Agent Wallet Cannot Cover That Amount');
  end if;

  update public.club_members
     set chip_balance = coalesce(chip_balance,0) + p_amount
   where club_id=p_club_id and user_id=v_actor
   returning chip_balance into v_player_after;
  FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
    PERFORM set_config(v_setting,v_context->>v_setting,true);
  END LOOP;
  if v_player_after is null then
    raise exception 'membership row vanished for % in % after wallet debit', v_actor, p_club_id;
  end if;

  insert into public.chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (p_club_id, v_actor, v_actor, p_amount, 'agent_wallet_self_stake',
     coalesce(p_reason,'Agent Wallet To Own Player Wallet'),
     jsonb_build_object('op_id',p_op_id::text,'destination','player_wallet',
       'actor_role',v_role,
       'agent_wallet_after',v_wallet_after,'player_wallet_after',v_player_after),
     v_player_after)
  returning id into v_tx;

  return jsonb_build_object('success',true,'transaction_id',v_tx,'amount',p_amount,
    'agent_wallet_after',v_wallet_after,'player_wallet_after',v_player_after);
end
$$;


ALTER FUNCTION public.fn_agent_wallet_self_stake(p_club_id uuid, p_amount numeric, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_agent_wallet_send(uuid, uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_wallet_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text DEFAULT 'player_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    return jsonb_build_object('success',false,'error','Not Authenticated');
  end if;
  if p_op_id is null then
    return jsonb_build_object('success',false,'error','A Retry Key Is Required For Every Send');
  end if;
  return public.fn_agent_wallet_send_phase2_core_20260831(
    p_club_id,p_to_user_id,p_amount,p_destination,p_reason,p_op_id
  );
end
$$;


ALTER FUNCTION public.fn_agent_wallet_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_agent_wallet_send_core_20260830(uuid, uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_wallet_send_core_20260830(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text DEFAULT 'player_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_context jsonb;
  v_setting text;
  v_actor        uuid := auth.uid();
  v_actor_role   text;
  v_dest         text := lower(coalesce(p_destination, 'player_wallet'));
  v_op_id        uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior        record;
  v_agent_id     uuid;
  v_float_before numeric;
  v_float_after  numeric;
  v_is_prepaid   boolean;
  v_credit_limit numeric;
  v_credit_used  numeric;
  v_credit_after numeric;
  v_shortfall    numeric := 0;
  v_headroom     numeric;
  v_to_role      text;
  v_to_agent_id  uuid;
  v_to_after     numeric;
  v_tx_id        uuid;
  v_until        timestamptz;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  select id, amount, metadata into v_prior
    from chip_transactions
   where club_id = p_club_id
     and transaction_type = 'agent_wallet_send'
     and from_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'agent_wallet_after', (v_prior.metadata ->> 'agent_wallet_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric,
      'credit_drawn', coalesce((v_prior.metadata ->> 'credit_drawn')::numeric, 0),
      'credit_used_after', (v_prior.metadata ->> 'credit_used_after')::numeric,
      'credit_limit', (v_prior.metadata ->> 'credit_limit')::numeric);
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null
     or v_actor_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only Staff Or Agents Hold An Agent Wallet');
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false,
      'error', 'Chips Move In Hundredths At Most');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Send Limit');
  end if;
  if v_dest not in ('player_wallet', 'agent_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Destination Wallet');
  end if;
  if p_to_user_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose A Recipient');
  end if;
  if p_to_user_id = v_actor then
    return jsonb_build_object('success', false,
      'error', 'You Cannot Send Chips To Yourself');
  end if;

  if not public.fn_club_cashier_can_transact(p_club_id, v_actor, p_to_user_id) then
    return jsonb_build_object('success', false,
      'error', 'That Member Is Not In Your Downline');
  end if;

  select cm.role into v_to_role
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = p_to_user_id
     and coalesce(cm.status, 'active') in ('active', 'approved')
   for update;
  if v_to_role is null then
    return jsonb_build_object('success', false,
      'error', 'Recipient Is Not An Active Member Of This Club');
  end if;
  if v_dest = 'agent_wallet'
     and v_to_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only Staff Or Agents Hold An Agent Wallet');
  end if;

  if v_to_role in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    v_dest := 'agent_wallet';
  end if;

  select a.id, coalesce(a.agent_wallet_balance, 0),
         coalesce(a.is_prepaid, true),
         coalesce(a.credit_limit, 0), coalesce(a.credit_used, 0)
    into v_agent_id, v_float_before, v_is_prepaid, v_credit_limit, v_credit_used
    from agents a
   where a.club_id = p_club_id and a.user_id = v_actor
   for update;
  if v_agent_id is null then
    return jsonb_build_object('success', false,
      'error', 'Your Agent Wallet Has Not Been Funded Yet');
  end if;

  -- THE CREDIT LINE. Dan, 2026-08-31: "IF THEY GO BELOW THE CREDIT LIMIT, THEY
  -- MUST 'SQUARE UP' OR PRE PAY FOR CHIPS FOR THE REST OF THE WEEK." So the
  -- limit caps the debt outstanding, not the amount ever borrowed: an agent
  -- draws credit_limit - credit_used, and paying an invoice frees it again
  -- (fn_apply_credit_payment pays credit_used down, phase 1).
  if v_float_before < p_amount then
    v_shortfall := round(p_amount - v_float_before, 2);

    -- A prepaid agent, and an agent with no line at all, get the plain answer
    -- about their wallet. Talking about a credit line to somebody who has none
    -- is the sort of message that sends a person looking for a setting.
    if v_is_prepaid or v_credit_limit <= 0 then
      return jsonb_build_object('success', false,
        'error', 'Your Agent Wallet Only Holds '
                 || trim(to_char(v_float_before, 'FM999,999,999,990.00')) || ' Chips',
        'balance', v_float_before, 'requested', p_amount,
        'prepaid', v_is_prepaid);
    end if;

    v_headroom := v_credit_limit - v_credit_used;
    if v_shortfall > v_headroom then
      return jsonb_build_object('success', false,
        'error', 'Your Wallet Holds '
                 || trim(to_char(v_float_before, 'FM999,999,999,990.00'))
                 || ' Chips And Your Credit Line Has '
                 || trim(to_char(greatest(v_headroom, 0), 'FM999,999,999,990.00'))
                 || ' Left. Square Up Your Invoice Or Add Chips To Send This Much.',
        'balance', v_float_before, 'requested', p_amount,
        'credit_limit', v_credit_limit, 'credit_used', v_credit_used,
        'credit_available', greatest(v_headroom, 0),
        'shortfall', v_shortfall);
    end if;
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): an agent wallet send is ONE `agent_send`
  -- row from the sender's float to the wallet that receives it, keyed and
  -- correlated on the op. Verified on 2026-09-01 14:23:18 (10,000.00 to a
  -- player) the undeclared journal was `adjustment agent_wallet ->
  -- settlement_suspense` plus `adjustment table_stack -> player_wallet`. The
  -- agents trigger is skipped for both float writes: a player recipient's
  -- club_members trigger writes the row with the sender's float as its
  -- counterparty; an agent recipient (both sides in `agents`) gets the row
  -- posted explicitly below. When the credit line covers a shortfall the
  -- float only pays p_amount - v_shortfall, so the draw is its own
  -- `credit_draw credit_facility -> agent_wallet` row for the difference and
  -- the send row still carries the whole amount. Never a refusal.
  select jsonb_object_agg(k,coalesce(current_setting(k,true),'')) into v_context
   from unnest(array['app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_tournament','app.ledger_settlement','app.ledger_idempotency_key','app.ledger_correlation','app.ledger_autoskip_agents']) settings(k);
  perform set_config('app.ledger_tournament','',true);
  perform set_config('app.ledger_settlement','',true);
  perform public.fn_ca_declare_ledger('agent_send', 'agent_wallet', v_actor, null,
    'agent_send:' || v_op_id::text, array['agents']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);
  if v_shortfall > 0 then
    perform public.fn_ca_post_leg('credit_draw', 'credit_facility', v_actor, 'agent_wallet', v_actor,
      v_shortfall, p_club_id, 'agent_send:credit:' || v_op_id::text,
      'Agent credit line covers the shortfall of an agent wallet send (fn_agent_wallet_send_core_20260830)');
  end if;

  -- The wallet pays what it can and the line covers the rest, so the balance
  -- lands on exactly zero rather than going negative.
  update agents
     set agent_wallet_balance = coalesce(agent_wallet_balance, 0) - (p_amount - v_shortfall),
         credit_used          = coalesce(credit_used, 0) + v_shortfall,
         updated_at = now()
   where id = v_agent_id
   returning agent_wallet_balance, credit_used into v_float_after, v_credit_after;

  if v_dest = 'player_wallet' then
    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount,
           updated_at = now()
     where club_id = p_club_id and user_id = p_to_user_id
     returning chip_balance into v_to_after;
  else
    v_to_agent_id := public.fn_ensure_agent_row(p_club_id, p_to_user_id, v_to_role);
    if v_to_agent_id is null then
      raise exception 'could not ensure agents row for % in club %', p_to_user_id, p_club_id;
    end if;
    update agents
       set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + p_amount,
           updated_at = now()
     where id = v_to_agent_id
     returning agent_wallet_balance into v_to_after;
    perform set_config('app.ledger_idempotency_key', '', true);
    perform public.fn_ca_post_leg('agent_send', 'agent_wallet', v_actor, 'agent_wallet', p_to_user_id,
      p_amount, p_club_id, 'agent_send:' || v_op_id::text,
      'Agent wallet send to a downline agent wallet (fn_agent_wallet_send_core_20260830)');
  end if;

  for v_setting in select jsonb_object_keys(v_context) loop
    perform set_config(v_setting,v_context->>v_setting,true);
  end loop;

  v_until := now() + interval '10 minutes';

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata,
     balance_after, reversible_until)
  values
    (p_club_id, v_actor, p_to_user_id, p_amount, 'agent_wallet_send',
     coalesce(nullif(btrim(p_reason), ''), 'Agent Wallet Send'),
     jsonb_build_object(
       'op_id', v_op_id,
       'destination', v_dest,
       'actor_role', v_actor_role,
       'recipient_role', v_to_role,
       'agent_wallet_before', v_float_before,
       'agent_wallet_after', v_float_after,
       'recipient_balance_after', v_to_after,
       'claimed_back', 0,
       -- What was borrowed to make this send, and how much of that borrowing
       -- has since been handed back. The claim back reads both.
       'credit_drawn', v_shortfall,
       'credit_repaid', 0,
       'credit_used_after', v_credit_after,
       'credit_limit', v_credit_limit,
       'clawback_window_minutes', 10),
     v_float_after, v_until)
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true, 'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', p_amount,
    'destination', v_dest,
    'agent_wallet_before', v_float_before,
    'agent_wallet_after', v_float_after,
    'recipient_balance_after', v_to_after,
    'credit_drawn', v_shortfall,
    'credit_used_after', v_credit_after,
    'credit_limit', v_credit_limit,
    'reversible_until', v_until);
exception
  when unique_violation then
    select id, amount, metadata into v_prior
      from chip_transactions
     where club_id = p_club_id
       and transaction_type = 'agent_wallet_send'
       and from_user_id = v_actor
       and metadata ->> 'op_id' = v_op_id::text
     limit 1;
    if v_prior.id is null then
      raise;
    end if;
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'agent_wallet_after', (v_prior.metadata ->> 'agent_wallet_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric,
      'credit_drawn', coalesce((v_prior.metadata ->> 'credit_drawn')::numeric, 0),
      'credit_used_after', (v_prior.metadata ->> 'credit_used_after')::numeric,
      'credit_limit', (v_prior.metadata ->> 'credit_limit')::numeric);
end
$$;


ALTER FUNCTION public.fn_agent_wallet_send_core_20260830(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_agent_wallet_send_core_20260830(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_agent_wallet_send_core_20260830(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid) IS 'Agent wallet send: debits agents.agent_wallet_balance, credits the downline recipient, writes the ledger row, ten minute clawback window.';


--
-- Name: fn_agent_wallet_send_phase2_core_20260831(uuid, uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_wallet_send_phase2_core_20260831(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text DEFAULT 'player_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_op_id uuid := coalesce(p_op_id,gen_random_uuid());
  v_destination text := lower(coalesce(p_destination,'player_wallet'));
  v_prior record;
  v_replay_destination text;
  v_actor_role text;
  v_target_role text;
  v_first uuid;
  v_second uuid;
begin
  if v_actor is null then return jsonb_build_object('success',false,'error','Not Authenticated'); end if;
  if p_club_id is null or p_to_user_id is null or p_to_user_id=v_actor then
    return jsonb_build_object('success',false,'error','Choose Another Active Member');
  end if;
  if p_amount is null or p_amount <= 0 or p_amount > 1e9 or p_amount<>round(p_amount,2) then
    return jsonb_build_object('success',false,'error','Enter A Valid Send Amount');
  end if;
  if v_destination not in ('player_wallet','agent_wallet') then
    return jsonb_build_object('success',false,'error','Unknown Destination Wallet');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'agent-wallet-send:'||p_club_id::text||':'||v_actor::text||':'||v_op_id::text,0));
  perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||p_club_id::text,0));

  select ct.* into v_prior from public.chip_transactions ct
   where ct.club_id=p_club_id and ct.transaction_type='agent_wallet_send'
     and ct.from_user_id=v_actor and ct.metadata->>'op_id'=v_op_id::text limit 1;
  if found then
    v_replay_destination := case
      when coalesce(v_prior.metadata->>'recipient_role','') in
        ('owner','co_owner','admin','super_agent','agent','sub_agent')
      then 'agent_wallet' else v_destination end;
    if v_prior.to_user_id is distinct from p_to_user_id
       or v_prior.amount is distinct from p_amount
       or coalesce(v_prior.metadata->>'destination','') is distinct from v_replay_destination then
      return jsonb_build_object('success',false,
        'error','That Retry Key Belongs To A Different Agent Wallet Send');
    end if;
    return jsonb_build_object(
      'success',true,'replayed',true,'transaction_id',v_prior.id,'amount',v_prior.amount,
      'destination',v_prior.metadata->>'destination',
      'agent_wallet_after',(v_prior.metadata->>'agent_wallet_after')::numeric,
      'recipient_balance_after',(v_prior.metadata->>'recipient_balance_after')::numeric,
      'credit_drawn',coalesce((v_prior.metadata->>'credit_drawn')::numeric,0),
      'credit_used_after',(v_prior.metadata->>'credit_used_after')::numeric,
      'credit_limit',(v_prior.metadata->>'credit_limit')::numeric);
  end if;

  -- Ownership and both membership rows stay locked through the core operation.
  -- A concurrent role revocation, downline reassignment, or member deletion
  -- must complete before or after this send, never between its checks and debit.
  perform 1 from public.clubs where id=p_club_id for update;
  if not found then return jsonb_build_object('success',false,'error','That Club Could Not Be Found'); end if;
  if v_actor<p_to_user_id then v_first:=v_actor; v_second:=p_to_user_id;
  else v_first:=p_to_user_id; v_second:=v_actor; end if;
  perform 1 from public.club_members where club_id=p_club_id and user_id=v_first for update;
  perform 1 from public.club_members where club_id=p_club_id and user_id=v_second for update;

  v_actor_role:=public.fn_club_bank_role(p_club_id,v_actor);
  select role into v_target_role from public.club_members
   where club_id=p_club_id and user_id=p_to_user_id
     and coalesce(status,'active') in ('active','approved');
  if v_actor_role is null
     or v_actor_role not in ('owner','co_owner','admin','super_agent','agent','sub_agent') then
    return jsonb_build_object('success',false,'error','Your Cashier Authority Is No Longer Active');
  end if;
  if v_target_role is null then
    return jsonb_build_object('success',false,'error','Recipient Is Not An Active Member Of This Club');
  end if;
  if not public.fn_club_cashier_can_transact(p_club_id,v_actor,p_to_user_id) then
    return jsonb_build_object('success',false,'error','That Member Is Not In Your Downline');
  end if;

  -- Agent recipients always receive agent float; bind the replay fingerprint
  -- to the effective destination, not a caller-controlled label.
  if v_target_role in ('owner','co_owner','admin','super_agent','agent','sub_agent') then
    v_destination:='agent_wallet';
  end if;

  return public.fn_agent_wallet_send_core_20260830(
    p_club_id,p_to_user_id,p_amount,v_destination,p_reason,v_op_id);
end
$$;


ALTER FUNCTION public.fn_agent_wallet_send_phase2_core_20260831(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_agent_weekly_statement(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_weekly_statement(p_agent_user_id uuid DEFAULT NULL::uuid, p_period_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_agent uuid := COALESCE(p_agent_user_id, auth.uid());
  v_from timestamptz := COALESCE(p_period_start, public.fn_union_week_start(now()));
  v_to   timestamptz := COALESCE(p_period_end, now());
  v_players int := 0; v_rake numeric := 0; v_commission numeric := 0;
  v_player_net numeric := 0; v_credit numeric := 0;
  v_chips_out numeric := 0; v_chips_in numeric := 0; v_rb_passed numeric := 0;
BEGIN
  IF v_agent IS NULL THEN RAISE EXCEPTION 'no_agent_context'; END IF;
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( auth.uid() <> v_agent
     AND NOT public.fn_is_any_union_overseer(auth.uid()))) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  WITH roster AS (
    SELECT DISTINCT m.user_id AS player_id, m.club_id
      FROM club_members m
     WHERE m.agent_id = v_agent
        OR EXISTS (SELECT 1 FROM agents child
                    JOIN agents parent ON parent.id = child.parent_agent_id
                   WHERE child.user_id = m.agent_id AND parent.user_id = v_agent)
  ),
  rk AS (
    SELECT SUM(rr.rake_amount * (e.value::numeric) / NULLIF(c.total,0)) AS rake
      FROM rake_records rr
      CROSS JOIN LATERAL (SELECT SUM(t.value::numeric) AS total
                            FROM jsonb_each_text(rr.player_contributions) t(key,value)) c
      CROSS JOIN LATERAL jsonb_each_text(rr.player_contributions) e(key,value)
     WHERE rr.created_at >= v_from AND rr.created_at < v_to
       AND rr.player_contributions IS NOT NULL AND c.total > 0
       AND EXISTS (SELECT 1 FROM roster r WHERE r.player_id = (e.key)::uuid)
  ),
  fl AS (
    SELECT SUM(CASE WHEN wt.type='credit' AND wt.category='cashout' THEN wt.amount ELSE 0 END)
         - SUM(CASE WHEN wt.type='debit'  AND wt.category IN ('buyin','rebuy','addon') THEN wt.amount ELSE 0 END) AS net
      FROM wallet_transactions wt
      JOIN roster r ON r.player_id = wt.user_id
     WHERE wt.created_at >= v_from AND wt.created_at < v_to
  ),
  cm AS (
    SELECT COALESCE(SUM(amount),0) AS commission
      FROM agent_commissions
     WHERE user_id = v_agent AND created_at >= v_from AND created_at < v_to
  ),
  rb AS (
    -- rakeback this agent's own players received: funded from this agent
    SELECT COALESCE(SUM(rp.rakeback_amount),0) AS passed
      FROM rakeback_periods rp
      JOIN club_members m ON m.user_id = rp.user_id AND m.club_id = rp.club_id
     WHERE m.agent_id = v_agent
       AND rp.period_start >= v_from::date AND rp.period_start < v_to::date + 1
  ),
  ct AS (
    SELECT COALESCE(SUM(CASE WHEN from_user_id = v_agent THEN amount ELSE 0 END),0) AS out_chips,
           COALESCE(SUM(CASE WHEN to_user_id   = v_agent THEN amount ELSE 0 END),0) AS in_chips
      FROM chip_transactions
     WHERE created_at >= v_from AND created_at < v_to
       AND (from_user_id = v_agent OR to_user_id = v_agent)
  )
  SELECT (SELECT count(*) FROM roster),
         COALESCE((SELECT rake FROM rk),0),
         COALESCE((SELECT commission FROM cm),0),
         COALESCE((SELECT net FROM fl),0),
         COALESCE((SELECT out_chips FROM ct),0),
         COALESCE((SELECT in_chips FROM ct),0),
         COALESCE((SELECT passed FROM rb),0)
    INTO v_players, v_rake, v_commission, v_player_net, v_chips_out, v_chips_in, v_rb_passed;

  SELECT COALESCE(SUM(credit_used),0) INTO v_credit
    FROM agents WHERE user_id = v_agent AND status = 'active';

  RETURN jsonb_build_object(
    'agent_user_id', v_agent,
    'period_start', v_from, 'period_end', v_to,
    'players', v_players,
    'rake_generated', round(v_rake, 2),
    'commission_earned', round(v_commission, 2),
    'rakeback_passed_to_players', round(v_rb_passed, 2),
    'commission_net_of_rakeback', round(v_commission - v_rb_passed, 2),
    'player_net_result', round(v_player_net, 2),
    'chips_issued_to_players', round(v_chips_out, 2),
    'chips_returned_from_players', round(v_chips_in, 2),
    'credit_outstanding', round(v_credit, 2),
    -- positive = owed TO the agent; negative = the agent owes up the chain
    'net_settlement_position',
      round(v_commission - v_rb_passed - v_player_net - v_credit, 2),
    'settles', 'weekly'
  );
END $$;


ALTER FUNCTION public.fn_agent_weekly_statement(p_agent_user_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_agents_staff_earn_no_rakeback(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agents_staff_earn_no_rakeback() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.club_id = NEW.club_id AND cm.user_id = NEW.user_id
       AND cm.role IN ('co_owner', 'admin')
  ) THEN
    -- The row survives: it is also the agent wallet. Only the rate goes to zero.
    NEW.commission_rate      := 0;
    NEW.player_rakeback_rate := 0;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_agents_staff_earn_no_rakeback() OWNER TO postgres;

--
-- Name: fn_aggregate_gto_flop(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_aggregate_gto_flop(p_game_type text) RETURNS TABLE(cells integer, rows_read integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_family text;
  v_cells integer; v_rows integer;
begin
  v_family := case
    when p_game_type like '%cash%' then 'cash'
    when p_game_type like '%icm%' then 'tourney_icm'
    when p_game_type like 'spin%' then 'spin'
    else 'tourney_ev' end;

  create temp table if not exists tmp_agg (like public.gto_postflop_compact including all) on commit drop;
  delete from tmp_agg where true;

  with src as (
    select
      substring(s.scenario_hash from '_(UTG|MP|CO|BTN|SB|BB)_') as pos,
      case
        when s.stack_depth <= 12 then 10
        when s.stack_depth <= 30 then 20
        when s.stack_depth <= 60 then 40
        when s.stack_depth <= 110 then 80
        else 150 end as depth_bucket,
      public.fn_gto_texture_class(substring(s.scenario_hash from 'bb_(.*)$')) as tex,
      case when s.strategy_matrix->'actions' @> '["f"]'::jsonb then 'facing' else 'open' end as facing,
      s.strategy_matrix->'frequencies' as freqs,
      s.strategy_matrix->'actions' as actions
    from public.solved_spots_gold s
    where s.street = 'flop'
      and s.game_type = p_game_type
      and s.strategy_matrix ? 'frequencies'
      and s.strategy_matrix ? 'actions'
  ),
  labeled as (
    select pos, depth_bucket, tex, facing, freqs,
      (select jsonb_object_agg(a.act,
        case
          when a.act = 'c' and facing = 'open' then 'check'
          when a.act = 'c' then 'call'
          when a.act = 'f' then 'fold'
          when a.act like 'b%' then
            case when (nullif(substr(a.act, 2), ''))::numeric >= (
              select max((nullif(substr(b.act2, 2), ''))::numeric)
              from jsonb_array_elements_text(actions) b(act2) where b.act2 like 'b%'
            ) then case when facing = 'open' then 'bet_big' else 'raise_big' end
            else case when facing = 'open' then 'bet_small' else 'raise_small' end
          end
          else null end)
       from jsonb_array_elements_text(actions) a(act)) as bucket_of
    from src
    where pos is not null and tex is not null
  ),
  rowcounts as (
    select pos, depth_bucket, tex, facing, count(*) as nrows
    from labeled group by 1,2,3,4
  ),
  expanded as (
    select l.pos, l.depth_bucket, l.tex, l.facing,
           h.key as hand, l.bucket_of->>am.key as bucket, (h.value)::numeric as freq
    from labeled l,
         jsonb_each(l.freqs) am,
         jsonb_each_text(am.value) h
    where l.bucket_of->>am.key is not null
      and h.value ~ '^-?[0-9.eE+]+$'
  ),
  cellhand as (
    select pos, depth_bucket, tex, facing, hand, bucket, avg(freq) as f
    from expanded group by 1,2,3,4,5,6
  ),
  cells as (
    select c.pos, c.depth_bucket, c.tex, c.facing,
           jsonb_object_agg(c.hand, c.per_hand) as matrix,
           max(r.nrows)::integer as source_rows
    from (
      select pos, depth_bucket, tex, facing, hand,
             jsonb_object_agg(bucket, round(f, 4)) as per_hand
      from cellhand group by 1,2,3,4,5
    ) c
    join rowcounts r using (pos, depth_bucket, tex, facing)
    group by 1,2,3,4
  )
  insert into tmp_agg (street, game_family, position, depth_bucket, texture_class, facing,
                       hand_matrix, source_rows)
  select 'flop', v_family, pos, depth_bucket, tex, facing, matrix, source_rows from cells;

  get diagnostics v_cells = row_count;
  select count(*) into v_rows from public.solved_spots_gold
   where street = 'flop' and game_type = p_game_type;

  insert into public.gto_postflop_compact as g
    (street, game_family, position, depth_bucket, texture_class, facing, hand_matrix, source_rows)
  select street, game_family, position, depth_bucket, texture_class, facing, hand_matrix, source_rows
  from tmp_agg
  on conflict (street, game_family, position, depth_bucket, texture_class, facing) do update
     set hand_matrix = (
           select jsonb_object_agg(hand, merged) from (
             select coalesce(a.key, b.key) as hand,
               case
                 when a.value is null then b.value
                 when b.value is null then a.value
                 else (
                   select jsonb_object_agg(bk, round(
                     (coalesce((a.value->>bk)::numeric, 0) * g.source_rows
                      + coalesce((b.value->>bk)::numeric, 0) * excluded.source_rows)
                     / nullif(g.source_rows + excluded.source_rows, 0), 4))
                   from (
                     select distinct k as bk from (
                       select jsonb_object_keys(a.value) k
                       union select jsonb_object_keys(b.value) k
                     ) kk
                   ) bks
                 )
               end as merged
             from jsonb_each(g.hand_matrix) a
             full outer join jsonb_each(excluded.hand_matrix) b on a.key = b.key
           ) m
         ),
         source_rows = g.source_rows + excluded.source_rows,
         built_at = now();

  return query select v_cells, v_rows;
end;
$_$;


ALTER FUNCTION public.fn_aggregate_gto_flop(p_game_type text) OWNER TO postgres;

--
-- Name: FUNCTION fn_aggregate_gto_flop(p_game_type text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_aggregate_gto_flop(p_game_type text) IS 'V29 batch aggregator: fold ONE game_type''s flop rows (<=6k, index-driven) from solved_spots_gold into gto_postflop_compact. Idempotence contract: rebuilding requires truncating the target first (the merge is additive by design so sibling game_types in one family combine). Run once per game_type, off-peak.';


--
-- Name: fn_aggregate_gto_street_next(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_aggregate_gto_street_next(p_street text, p_batch integer DEFAULT 1500) RETURNS TABLE(processed integer, new_last_id uuid, street_done boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $_$
declare
  v_cur record;
  v_batch integer := greatest(25, least(5000, coalesce(p_batch, 1500)));
  v_max_id uuid;
  v_processed integer := 0;
begin
  if p_street not in ('turn', 'river') then
    raise exception 'fn_aggregate_gto_street_next handles turn/river only (got %)', p_street;
  end if;

  select * into v_cur from public.gto_agg_progress where street = p_street for update;
  if not found then
    raise exception 'no gto_agg_progress row for %', p_street;
  end if;
  if v_cur.done then
    return query select 0, v_cur.last_id, true;
    return;
  end if;

  create temp table if not exists tmp_agg30 (like public.gto_postflop_compact including all) on commit drop;
  -- TRUNCATE, not DELETE: PostgREST roles run with the safe-update guard,
  -- which refuses an unqualified DELETE (error 21000).
  truncate table tmp_agg30;

  with batch as (
    select s.id, s.game_type, s.stack_depth, s.scenario_hash, s.strategy_matrix
    from public.solved_spots_gold s
    where s.street = p_street
      and (v_cur.last_id is null or s.id > v_cur.last_id)
    order by s.id
    limit v_batch
  ),
  marked as (
    select (select b2.id from batch b2 order by b2.id desc limit 1) as max_id,
           (select count(*) from batch) as n
  ),
  src as (
    select
      b.id,
      case
        when b.game_type like '%cash%' then 'cash'
        when b.game_type like '%icm%' then 'tourney_icm'
        when b.game_type like 'spin%' then 'spin'
        else 'tourney_ev' end as fam,
      substring(b.scenario_hash from '_(UTG|MP|CO|BTN|SB|BB)_') as pos,
      case
        when b.stack_depth <= 12 then 10
        when b.stack_depth <= 30 then 20
        when b.stack_depth <= 60 then 40
        when b.stack_depth <= 110 then 80
        else 150 end as depth_bucket,
      public.fn_gto_texture_class_any(substring(b.scenario_hash from 'bb_(.*)$')) as tex,
      b.strategy_matrix->'frequencies' as freqs,
      b.strategy_matrix->'tree_lines' as tree_lines
    from batch b
    where b.strategy_matrix ? 'frequencies'
      and b.strategy_matrix ? 'tree_lines'
  ),
  roots as (
    select s.id, replace(l.line, 'r:0:', '') as act
    from src s, jsonb_array_elements_text(s.tree_lines) l(line)
    where l.line ~ '^r:0:[^:]+$'
    group by 1, 2
  ),
  rootbets as (
    select id,
           count(*) as nb,
           max((nullif(substr(act, 2), ''))::numeric) as mx
    from roots where act like 'b%' and substr(act, 2) ~ '^[0-9]+$'
    group by id
  ),
  handvals as (
    select s.id, s.fam, s.pos, s.depth_bucket, s.tex, r.act,
           h.key as hand, (h.value)::numeric as v
    from src s
    join roots r on r.id = s.id
    cross join lateral jsonb_each_text(s.freqs -> r.act) h
    where s.pos is not null and s.tex is not null
      and h.value ~ '^-?[0-9.eE+]+$'
  ),
  validated as (
    select id, hand, sum(v) as tot
    from handvals
    group by 1, 2
    having bool_and(v >= 0 and v <= 1.001)
       and sum(v) between 0.95 and 1.05
  ),
  normed as (
    select hv.id, hv.fam, hv.pos, hv.depth_bucket, hv.tex, hv.hand,
      case
        when hv.act = 'c' then 'check'
        when coalesce(rb.nb, 0) = 1 then
          case when (nullif(substr(hv.act, 2), ''))::numeric >= 100
            then 'bet_big' else 'bet_small' end
        when (nullif(substr(hv.act, 2), ''))::numeric >= rb.mx then 'bet_big'
        else 'bet_small'
      end as bucket,
      hv.v / va.tot as freq
    from handvals hv
    join validated va on va.id = hv.id and va.hand = hv.hand
    left join rootbets rb on rb.id = hv.id
  ),
  perhand as (
    select id, fam, pos, depth_bucket, tex, hand, bucket, sum(freq) as f
    from normed group by 1, 2, 3, 4, 5, 6, 7
  ),
  rowcounts as (
    select fam, pos, depth_bucket, tex, count(distinct id) as nrows
    from perhand group by 1, 2, 3, 4
  ),
  cellhand as (
    select fam, pos, depth_bucket, tex, hand, bucket, avg(f) as f
    from perhand group by 1, 2, 3, 4, 5, 6
  ),
  cells as (
    select c.fam, c.pos, c.depth_bucket, c.tex,
           jsonb_object_agg(c.hand, c.per_hand) as matrix,
           max(r.nrows)::integer as source_rows
    from (
      select fam, pos, depth_bucket, tex, hand,
             jsonb_object_agg(bucket, round(f, 4)) as per_hand
      from cellhand group by 1, 2, 3, 4, 5
    ) c
    join rowcounts r using (fam, pos, depth_bucket, tex)
    group by 1, 2, 3, 4
  ),
  ins as (
    insert into tmp_agg30 (street, game_family, position, depth_bucket, texture_class, facing,
                           hand_matrix, source_rows)
    select p_street, fam, pos, depth_bucket, tex, 'open', matrix, source_rows from cells
    returning 1
  )
  select coalesce((select max_id from marked), v_cur.last_id),
         coalesce((select n from marked), 0)
    into v_max_id, v_processed;

  insert into public.gto_postflop_compact as g
    (street, game_family, position, depth_bucket, texture_class, facing, hand_matrix, source_rows)
  select street, game_family, position, depth_bucket, texture_class, facing, hand_matrix, source_rows
  from tmp_agg30
  on conflict (street, game_family, position, depth_bucket, texture_class, facing) do update
     set hand_matrix = (
           select jsonb_object_agg(hand, merged) from (
             select coalesce(a.key, b.key) as hand,
               case
                 when a.value is null then b.value
                 when b.value is null then a.value
                 else (
                   select jsonb_object_agg(bk, round(
                     (coalesce((a.value->>bk)::numeric, 0) * g.source_rows
                      + coalesce((b.value->>bk)::numeric, 0) * excluded.source_rows)
                     / nullif(g.source_rows + excluded.source_rows, 0), 4))
                   from (
                     select distinct k as bk from (
                       select jsonb_object_keys(a.value) k
                       union select jsonb_object_keys(b.value) k
                     ) kk
                   ) bks
                 )
               end as merged
             from jsonb_each(g.hand_matrix) a
             full outer join jsonb_each(excluded.hand_matrix) b on a.key = b.key
           ) m
         ),
         source_rows = g.source_rows + excluded.source_rows,
         built_at = now();

  update public.gto_agg_progress
     set last_id = v_max_id,
         rows_done = rows_done + v_processed,
         done = (v_processed < v_batch),
         updated_at = now()
   where street = p_street;

  return query select v_processed, v_max_id, (v_processed < v_batch);
end;
$_$;


ALTER FUNCTION public.fn_aggregate_gto_street_next(p_street text, p_batch integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_aggregate_gto_street_next(p_street text, p_batch integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_aggregate_gto_street_next(p_street text, p_batch integer) IS 'V30 cursor-driven batch aggregator for turn/river OPEN cells. Root-node actions only (tree_lines r:0:X); per-hand validated and renormalized; TRUNCATE not DELETE (PostgREST roles refuse an unqualified DELETE, 21000).
BATCH FLOOR IS 25 AND WAS MEASURED, NOT GUESSED (20260830040000): cost is super-linear in batch size because a populated gto_postflop_compact sends nearly every batch down the ON CONFLICT merge path - 100 rows ~0.9s (111 rows/s), 200 rows ~8s and one call in three cancelled. The engine driver passes 100.
DO NOT CREATE OR REPLACE THIS FUNCTION FROM A COPY YOU FETCHED EARLIER. On 2026-08-30 a full-body replace silently reverted that floor to 200 and put the aggregation back on the timeout cliff; the cursor froze for ~4 minutes until it was patched back. Read prosrc first and patch surgically, or re-derive from the newest migration on main.';


--
-- Name: fn_aggregate_gto_v31_next(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_aggregate_gto_v31_next(p_batch integer DEFAULT 25) RETURNS TABLE(processed integer, last_at timestamp with time zone, last_id uuid, is_done boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cur       record;
  v_batch     integer := greatest(5, least(500, coalesce(p_batch, 25)));
  v_max_at    timestamptz;
  v_max_id    uuid;
  v_processed integer := 0;
begin
  select * into v_cur from public.gto_agg_progress_v31 where only_row for update;
  if not found then
    raise exception 'no gto_agg_progress_v31 cursor row';
  end if;
  if v_cur.done then
    return query select 0, v_cur.last_at, v_cur.last_id, true;
    return;
  end if;

  create temp table if not exists tmp_agg31 (like public.gto_postflop_v31 including all)
    on commit delete rows;
  delete from tmp_agg31 where true;

  with batch as materialized (
    select s.id, s.solved_v2_at, s.street, s.game_type, s.strategy_matrix_v2 as m
    from public.solved_spots_gold s
    where s.solved_v2_at is not null
      /* A SEEK, NOT A SCAN (2026-09-08). The OR-form of this keyset was not
         sargable: Postgres started at the beginning of
         idx_solved_spots_gold_solved_v2_at and filtered out every row already
         processed, so a 25-row batch removed 655,130 rows by filter, touched
         611,591 buffers (~4.8 GB) and took 761 ms - and got worse with every
         batch, because the discarded prefix is the work already done. The
         row-comparison below is a single index seek on
         idx_ssg_v2_cursor (solved_v2_at, id): same rows, same order, same
         cursor semantics, measured 0.082 ms and 12 buffers. */
      and (v_cur.last_at is null
           or (s.solved_v2_at, s.id) > (v_cur.last_at, v_cur.last_id))
    order by s.solved_v2_at, s.id
    limit v_batch
  ),
  marked as (
    select (select b2.solved_v2_at from batch b2
             order by b2.solved_v2_at desc, b2.id desc limit 1) as max_at,
           (select b2.id from batch b2
             order by b2.solved_v2_at desc, b2.id desc limit 1) as max_id,
           (select count(*) from batch) as n
  ),
  src as materialized (
    select b.id, b.street,
      case
        when b.game_type like '%cash%' then 'cash'
        when b.game_type like '%icm%'  then 'tourney_icm'
        when b.game_type like 'spin%'  then 'spin'
        else 'tourney_ev' end as fam,
      case upper(b.m->>'position')
        when 'UTG' then 'UTG' when 'UTG1' then 'UTG' when 'UTG2' then 'UTG'
        when 'MP'  then 'MP'  when 'MP1'  then 'MP'  when 'MP2'  then 'MP'
        when 'HJ'  then 'MP'
        when 'CO'  then 'CO'  when 'BTN'  then 'BTN'
        when 'SB'  then 'SB'  when 'BB'   then 'BB'
        else null end as pos,
      case
        when (b.m->>'eff_stack_bb')::numeric <= 12  then 10
        when (b.m->>'eff_stack_bb')::numeric <= 30  then 20
        when (b.m->>'eff_stack_bb')::numeric <= 60  then 40
        when (b.m->>'eff_stack_bb')::numeric <= 110 then 80
        else 150 end as depth_bucket,
      public.fn_gto_texture_class_any(b.m->>'board') as tex,
      public.fn_gto_board_flush_suit(b.m->>'board')  as fs,
      b.m->'actions'     as acts,
      b.m->'frequencies' as freqs
    from batch b
    where b.m ? 'actions' and b.m ? 'frequencies'
      and (b.m->>'eff_stack_bb') is not null
  ),
  acted as materialized (
    select s.id, s.street, s.fam, s.pos, s.depth_bucket, s.tex, s.fs,
      (a->>'code') as code,
      (a->>'size_pct')::numeric as size_pct,
      case
        when (a->>'size_pct')::numeric = 0   then 'check'
        when (a->>'size_pct')::numeric < 60  then 'bet_small'
        when (a->>'size_pct')::numeric < 110 then 'bet_mid'
        else 'bet_big' end as bucket,
      s.freqs
    from src s, jsonb_array_elements(s.acts) a
    where s.pos is not null and s.tex is not null and s.fs is not null
      and (a->>'size_pct') is not null
      and jsonb_typeof(s.freqs -> (a->>'code')) = 'array'
      and translate((s.freqs -> (a->>'code'))::text,
                    '0123456789.,+-eE[] ' || chr(9) || chr(10) || chr(13) || 'nul', '') = ''
  ),
  raw as materialized (
    select a.id, a.street, a.fam, a.pos, a.depth_bucket, a.tex, a.fs,
           (e.ord - 1)::int as combo_idx, a.bucket, e.f
    from acted a
    cross join lateral unnest(
      translate((a.freqs -> a.code)::text, '[]', '{}')::numeric[]
    ) with ordinality e(f, ord)
    where e.f is not null
  ),
  agg as materialized (
    select id, street, fam, pos, depth_bucket, tex, fs, combo_idx,
      sum(f) filter (where bucket = 'check')     as f_check,
      sum(f) filter (where bucket = 'bet_small') as f_small,
      sum(f) filter (where bucket = 'bet_mid')   as f_mid,
      sum(f) filter (where bucket = 'bet_big')   as f_big
    from raw
    group by 1, 2, 3, 4, 5, 6, 7, 8
    having sum(f) between 0.95 and 1.05
       and min(f) >= -0.001 and max(f) <= 1.001
  ),
  keyed as (
    select g.id, g.street, g.fam, g.pos, g.depth_bucket, g.tex,
           m.hand_class || ':' ||
             ((case when m.suit_a = g.fs then 1 else 0 end)
            + (case when m.suit_b = g.fs then 1 else 0 end))::text as handkey,
           v.bucket, v.f
    from agg g
    join public.gto_combo_map m on m.combo_idx = g.combo_idx
    cross join lateral (values
      ('check', g.f_check), ('bet_small', g.f_small),
      ('bet_mid', g.f_mid), ('bet_big', g.f_big)
    ) v(bucket, f)
    where v.f is not null
  ),
  perrow as materialized (
    select id, street, fam, pos, depth_bucket, tex, handkey, bucket, avg(f) as f
    from keyed
    group by 1, 2, 3, 4, 5, 6, 7, 8
  ),
  rowcounts as (
    select street, fam, pos, depth_bucket, tex, count(distinct id) as nrows
    from perrow group by 1, 2, 3, 4, 5
  ),
  cellhand as (
    select street, fam, pos, depth_bucket, tex, handkey, bucket, avg(f) as f
    from perrow group by 1, 2, 3, 4, 5, 6, 7
  ),
  sizecells as (
    select street, fam, pos, depth_bucket, tex,
           jsonb_object_agg(bucket, sz) as size_map
    from (
      select street, fam, pos, depth_bucket, tex, bucket, round(avg(size_pct), 1) as sz
      from acted where bucket <> 'check'
      group by 1, 2, 3, 4, 5, 6
    ) q
    group by 1, 2, 3, 4, 5
  ),
  cells as (
    select c.street, c.fam, c.pos, c.depth_bucket, c.tex,
           jsonb_object_agg(c.handkey, c.per_hand) as matrix,
           max(r.nrows)::integer as source_rows,
           coalesce(z.size_map, '{}'::jsonb) as size_map
    from (
      select street, fam, pos, depth_bucket, tex, handkey,
             jsonb_object_agg(bucket, round(f, 4)) as per_hand
      from cellhand group by 1, 2, 3, 4, 5, 6
    ) c
    join rowcounts r using (street, fam, pos, depth_bucket, tex)
    left join sizecells z using (street, fam, pos, depth_bucket, tex)
    -- size_map is one value per cell key, so grouping by it is identical to
    -- grouping by the key alone; Postgres just cannot infer that across a join
    group by 1, 2, 3, 4, 5, z.size_map
  ),
  ins as (
    insert into tmp_agg31
      (street, game_family, position, depth_bucket, texture_class, hand_matrix, source_rows, size_pct)
    select street, fam, pos, depth_bucket, tex, matrix, source_rows, size_map from cells
    returning 1
  )
  select coalesce((select max_at from marked), v_cur.last_at),
         coalesce((select max_id from marked), v_cur.last_id),
         coalesce((select n from marked), 0)
    into v_max_at, v_max_id, v_processed;

  insert into public.gto_postflop_v31 as g
    (street, game_family, position, depth_bucket, texture_class, hand_matrix, source_rows, size_pct)
  select street, game_family, position, depth_bucket, texture_class, hand_matrix, source_rows, size_pct
  from tmp_agg31
  on conflict (street, game_family, position, depth_bucket, texture_class) do update
     set hand_matrix = (
           select jsonb_object_agg(hand, merged) from (
             select coalesce(a.key, b.key) as hand,
               case
                 when a.value is null then b.value
                 when b.value is null then a.value
                 else (
                   select jsonb_object_agg(bk, round(
                     (coalesce((a.value->>bk)::numeric, 0) * g.source_rows
                      + coalesce((b.value->>bk)::numeric, 0) * excluded.source_rows)
                     / nullif(g.source_rows + excluded.source_rows, 0), 4))
                   from (
                     select distinct k as bk from (
                       select jsonb_object_keys(a.value) k
                       union select jsonb_object_keys(b.value) k
                     ) kk
                   ) bks
                 )
               end as merged
             from jsonb_each(g.hand_matrix) a
             full outer join jsonb_each(excluded.hand_matrix) b on a.key = b.key
           ) m
         ),
         size_pct = coalesce((
           select jsonb_object_agg(bk, round(
             (coalesce((g.size_pct->>bk)::numeric, (excluded.size_pct->>bk)::numeric) * g.source_rows
              + coalesce((excluded.size_pct->>bk)::numeric, (g.size_pct->>bk)::numeric) * excluded.source_rows)
             / nullif(g.source_rows + excluded.source_rows, 0), 1))
           from (
             select distinct k as bk from (
               select jsonb_object_keys(g.size_pct) k
               union select jsonb_object_keys(excluded.size_pct) k
             ) kk
           ) bks
         ), g.size_pct),
         source_rows = g.source_rows + excluded.source_rows,
         built_at = now();

  update public.gto_agg_progress_v31
     set last_at    = v_max_at,
         last_id    = v_max_id,
         rows_done  = rows_done + v_processed,
         done       = (v_processed < v_batch),
         updated_at = now()
   where only_row;

  return query select v_processed, v_max_at, v_max_id, (v_processed < v_batch);
end;
$$;


ALTER FUNCTION public.fn_aggregate_gto_v31_next(p_batch integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_aggregate_gto_v31_next(p_batch integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_aggregate_gto_v31_next(p_batch integer) IS 'Folds the next batch of solved_spots_gold.strategy_matrix_v2 into gto_postflop_v31. The keyset is a row-comparison so it seeks on idx_ssg_v2_cursor (solved_v2_at, id) rather than re-reading every already-processed row (761 ms -> 0.082 ms per batch, 2026-09-08).';


--
-- Name: fn_allocate_rake_credits(numeric, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_allocate_rake_credits(p_amount numeric, p_contributions jsonb, p_method text DEFAULT 'WEIGHTED_CONTRIBUTED'::text) RETURNS TABLE(user_id uuid, credit numeric, weight numeric)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  WITH c AS (
    SELECT (k.key)::uuid AS uid,
           round((k.value)::numeric * 100)::bigint AS cc
      FROM jsonb_each(COALESCE(p_contributions, '{}'::jsonb)) k
     WHERE jsonb_typeof(k.value) = 'number'
       AND (k.value)::numeric > 0
       AND k.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  ),
  t AS (
    SELECT COALESCE(SUM(cc), 0)::bigint AS total,
           round(GREATEST(COALESCE(p_amount, 0), 0) * 100)::bigint AS amt,
           COUNT(*)::bigint AS n
      FROM c
  ),
  weighted AS (
    SELECT c.uid, c.cc,
           (t.amt * c.cc) / t.total AS fl,
           (t.amt * c.cc) % t.total AS rem,
           t.amt, t.total
      FROM c CROSS JOIN t
     WHERE t.total > 0
  ),
  weighted_ranked AS (
    SELECT w.*,
           row_number() OVER (ORDER BY w.rem DESC, w.uid ASC) AS rn,
           SUM(w.fl) OVER () AS fl_sum
      FROM weighted w
  ),
  equal_ranked AS (
    SELECT c.uid, c.cc, t.amt, t.total, t.n,
           row_number() OVER (ORDER BY c.uid ASC) AS rn
      FROM c CROSS JOIN t
     WHERE t.n > 0
  )
  SELECT uid,
         ((fl + CASE WHEN rn <= (amt - fl_sum) THEN 1 ELSE 0 END)::numeric / 100),
         round(cc::numeric / total, 8)
    FROM weighted_ranked
   WHERE COALESCE(p_method, 'WEIGHTED_CONTRIBUTED') = 'WEIGHTED_CONTRIBUTED'
  UNION ALL
  SELECT uid,
         (((amt / n) + CASE WHEN rn <= (amt % n) THEN 1 ELSE 0 END)::numeric / 100),
         round(cc::numeric / total, 8)
    FROM equal_ranked
   WHERE COALESCE(p_method, 'WEIGHTED_CONTRIBUTED') = 'DEALT_EQUAL';
$_$;


ALTER FUNCTION public.fn_allocate_rake_credits(p_amount numeric, p_contributions jsonb, p_method text) OWNER TO postgres;

--
-- Name: fn_anon_exposure_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_anon_exposure_check() RETURNS TABLE(invariant text, severity text, offenders bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 'money_fn_exposed_to_anon', 'critical', count(*),
         'Financial functions callable by anon (no login). Postgres grants '
         || 'EXECUTE to PUBLIC by default and Supabase publishes every public '
         || 'function, so each of these is one REVOKE away from safe: '
         || COALESCE(string_agg(x.proname, ', ' ORDER BY x.proname), '')
    FROM (
      SELECT p.proname
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public'
       WHERE has_function_privilege('anon', p.oid, 'EXECUTE')
         AND (p.proname LIKE 'fn_union_%'
              OR p.proname LIKE '%settle%'
              OR p.proname LIKE '%treasury%'
              OR p.proname LIKE '%rakeback%'
              OR p.proname LIKE '%agent_commission%'
              OR p.proname LIKE 'fn_union_rake%')
         AND p.proname NOT IN (
           -- see header for why each of these is intentionally reachable
           'fn_union_oversees_club',
           'fn_tournament_entry_split',
           'fn_union_week_start')
    ) x
  HAVING count(*) > 0;
$$;


ALTER FUNCTION public.fn_anon_exposure_check() OWNER TO postgres;

--
-- Name: fn_anonymize_hg_user_content(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_anonymize_hg_user_content(p_user_id uuid, p_requested_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_counts jsonb := '{}'::jsonb;
  v_n int;
BEGIN
  IF p_user_id IS NULL OR p_requested_by IS NULL THEN
    RAISE EXCEPTION 'user_id and requested_by required'
          USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- ★ NEW: caller-identity check - prevents impersonation where Bob
  -- claims p_requested_by = Alice (admin)'s uuid to scrub anyone.
  -- service_role bypasses (server-side tooling).
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_requested_by THEN
      RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Authz: self OR platform admin (of the authenticated caller)
  SELECT role INTO v_role FROM public.profiles WHERE id = p_requested_by;
  IF p_user_id <> p_requested_by AND v_role NOT IN ('admin','superadmin','god') THEN
    RAISE EXCEPTION 'only the user or a platform admin may scrub HG content'
          USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- ── Anonymization sweeps ──
  UPDATE public.commander_home_posts
     SET content = '[content removed]',
         image_urls = NULL, video_url = NULL,
         is_hidden = true,
         hidden_at = COALESCE(hidden_at, now()),
         hidden_reason = 'gdpr_user_erasure'
   WHERE author_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('posts', v_n);

  UPDATE public.commander_home_post_comments
     SET content = '[comment removed]',
         is_hidden = true,
         hidden_at = COALESCE(hidden_at, now()),
         hidden_reason = 'gdpr_user_erasure'
   WHERE author_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('comments', v_n);

  UPDATE public.commander_home_rsvps
     SET message = NULL
   WHERE user_id = p_user_id AND message IS NOT NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('rsvp_messages', v_n);

  UPDATE public.commander_home_game_reviews
     SET review_text = '[review removed]',
         is_hidden = true,
         hidden_at = COALESCE(hidden_at, now()),
         hidden_reason = 'gdpr_user_erasure'
   WHERE reviewer_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('reviews', v_n);

  UPDATE public.commander_home_game_photos
     SET caption = NULL, photo_url = '[photo removed]', is_hidden = true
   WHERE uploader_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('photos', v_n);

  UPDATE public.commander_home_members
     SET host_private_note = NULL
   WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('member_notes_cleared_as_subject', v_n);

  UPDATE public.commander_home_ban_appeals
     SET appeal_text = '[removed]'
   WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('ban_appeals', v_n);

  UPDATE public.commander_home_group_promotion_requests
     SET reason = NULL
   WHERE requested_by = p_user_id AND reason IS NOT NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('promotion_reasons', v_n);

  -- Audit each affected group
  INSERT INTO public.commander_home_audit_log
    (group_id, actor_id, target_type, target_id, action, metadata)
  SELECT DISTINCT
    g.id, p_requested_by, 'user', p_user_id,
    'gdpr.hg_content_anonymized', v_counts
  FROM public.commander_home_groups g
  WHERE g.id IN (
    SELECT DISTINCT group_id FROM public.commander_home_members WHERE user_id = p_user_id
    UNION
    SELECT DISTINCT group_id FROM public.commander_home_posts   WHERE author_id = p_user_id
  );

  -- ★ Also log user-scope audit row (useful when user has no group memberships)
  INSERT INTO public.commander_home_audit_log
    (group_id, actor_id, target_type, target_id, action, metadata)
  VALUES (NULL, p_requested_by, 'user', p_user_id,
          'gdpr.hg_content_anonymized.summary', v_counts);

  RETURN jsonb_build_object(
    'success', true, 'user_id', p_user_id,
    'requested_by', p_requested_by, 'counts', v_counts
  );
END;
$$;


ALTER FUNCTION public.fn_anonymize_hg_user_content(p_user_id uuid, p_requested_by uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_anonymize_hg_user_content(p_user_id uuid, p_requested_by uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_anonymize_hg_user_content(p_user_id uuid, p_requested_by uuid) IS 'GDPR right-to-erasure for HG user content. Scrubs post/comment/review/photo/RSVP bodies. Idempotent. Preserves row structure for thread coherence.';


--
-- Name: fn_apply_club_ladder(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_apply_club_ladder(p_club_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_members integer;
  v_level   smallint;
  v_admins integer; v_supers integer; v_agents integer;
  v_units numeric; v_units_up integer; v_hlevel integer; v_cursor integer;
BEGIN
  IF p_club_id IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.clubs WHERE id = p_club_id) THEN RETURN; END IF;

  SELECT public.fn_get_club_realtime_member_count(p_club_id) INTO v_members;
  v_level := public.fn_club_level_for_members(v_members::integer);

  SELECT count(*) FILTER (WHERE role IN ('admin','manager')),
         count(*) FILTER (WHERE role = 'super_agent'),
         count(*) FILTER (WHERE role IN ('agent','sub_agent'))
    INTO v_admins, v_supers, v_agents
    FROM public.club_members
   WHERE club_id = p_club_id
     AND (status IS NULL OR status IN ('active','approved'));
  v_units := (v_admins * 1.00) + (v_supers * 1.00) + (v_agents * 0.25);
  v_units_up := CEIL(v_units);
  v_hlevel := 1;
  FOR v_cursor IN 1..50 LOOP
    IF v_units_up >= ROUND(2 * POWER(1.086, v_cursor - 1)) THEN v_hlevel := v_cursor; ELSE EXIT; END IF;
  END LOOP;

  UPDATE public.clubs SET
    member_count               = v_members,
    level                      = v_level,
    player_level               = v_level,
    player_threshold_current   = public.fn_club_level_min_members(v_level),
    player_threshold_next      = public.fn_club_level_min_members(v_level + 1),
    admin_count                = v_admins,
    super_agent_count          = v_supers,
    agent_count                = v_agents,
    hierarchy_units            = v_units,
    hierarchy_units_rounded_up = v_units_up,
    hierarchy_level            = v_hlevel,
    hierarchy_threshold_current = ROUND(2 * POWER(1.086, v_hlevel - 1)),
    hierarchy_threshold_next    = ROUND(2 * POWER(1.086, LEAST(v_hlevel, 49))),
    updated_at                 = now()
  WHERE id = p_club_id
    AND (member_count IS DISTINCT FROM v_members
      OR level IS DISTINCT FROM v_level
      OR player_level IS DISTINCT FROM v_level
      OR admin_count IS DISTINCT FROM v_admins
      OR super_agent_count IS DISTINCT FROM v_supers
      OR agent_count IS DISTINCT FROM v_agents
      OR player_threshold_current IS DISTINCT FROM public.fn_club_level_min_members(v_level)
      OR player_threshold_next IS DISTINCT FROM public.fn_club_level_min_members(v_level + 1));
END;
$$;


ALTER FUNCTION public.fn_apply_club_ladder(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_apply_credit_payment(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_apply_credit_payment(p_invoice_id uuid, p_amount numeric, p_method text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_inv public.credit_invoices;
  v_new_paid numeric;
  v_new_remaining numeric;
  v_status text;
  v_paid_at timestamptz;
  v_pay public.credit_payments;
  v_applied numeric;
  v_used_after numeric;
BEGIN
  IF p_invoice_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invoice and positive amount required');
  END IF;
  IF p_method NOT IN ('wallet','diamonds','external') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid payment method');
  END IF;

  SELECT * INTO v_inv FROM public.credit_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF v_inv.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invoice not found');
  END IF;

  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( auth.uid() <> v_inv.agent_id
     AND NOT public.is_admin()
     AND NOT EXISTS (
       SELECT 1 FROM public.club_members me
        WHERE me.user_id = auth.uid()
          AND me.role IN ('owner','co_owner','admin','manager')
          AND me.club_id IN (SELECT club_id FROM public.club_members
                              WHERE user_id = v_inv.agent_id)))) THEN
    RAISE EXCEPTION 'Not authorised to apply a payment to this invoice';
  END IF;

  IF v_inv.status = 'void' THEN
    RETURN jsonb_build_object('success', false, 'error', 'that invoice was voided and is not payable',
      'void_reason', v_inv.void_reason);
  END IF;
  IF v_inv.status = 'paid' THEN
    RETURN jsonb_build_object('success', false, 'error', 'that invoice is already settled');
  END IF;

  v_applied := LEAST(p_amount, GREATEST(v_inv.debt_owed - v_inv.amount_paid, 0));
  IF v_applied <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'that invoice has nothing left to pay');
  END IF;

  v_new_paid      := v_inv.amount_paid + v_applied;
  v_new_remaining := GREATEST(v_inv.debt_owed - v_new_paid, 0);
  IF v_new_remaining <= 0 THEN
    v_status  := 'paid';
    v_paid_at := NOW();
  ELSE
    v_status  := 'partial';
    v_paid_at := v_inv.paid_at;
  END IF;

  UPDATE public.credit_invoices
  SET amount_paid = v_new_paid,
      amount_remaining = v_new_remaining,
      status = v_status,
      paid_at = v_paid_at
  WHERE id = p_invoice_id;

  -- THE DEBT ITSELF. Without this the invoice went to 'paid' and
  -- agents.credit_used never moved, so the agent paid and still owed.
  UPDATE public.agents
     SET credit_used = GREATEST(COALESCE(credit_used, 0) - v_applied, 0),
         updated_at = now()
   WHERE id = v_inv.agent_id
  RETURNING credit_used INTO v_used_after;

  INSERT INTO public.credit_payments (invoice_id, amount, payment_method)
  VALUES (p_invoice_id, v_applied, p_method)
  RETURNING * INTO v_pay;

  RETURN jsonb_build_object(
    'success', true, 'invoice_id', p_invoice_id, 'status', v_status,
    'applied', v_applied, 'amount_remaining', v_new_remaining,
    'credit_used_after', v_used_after, 'payment', to_jsonb(v_pay));
END;
$$;


ALTER FUNCTION public.fn_apply_credit_payment(p_invoice_id uuid, p_amount numeric, p_method text) OWNER TO postgres;

--
-- Name: fn_apply_mystery_bounty_config(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_apply_mystery_bounty_config(p_tournament_id uuid, p_config jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_club uuid; v_stage text; v_is_mb boolean;
  v_activation text; v_profile text;
  v_value numeric; v_top numeric; v_mystery numeric; v_regular numeric;
BEGIN
  SELECT club_id, mystery_bounty_stage, is_mystery_bounty
    INTO v_club, v_stage, v_is_mb
    FROM public.tournaments WHERE id = p_tournament_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found'); END IF;

  -- Only the people who could have created the event can configure it, and
  -- only before the chests exist: after activation these columns describe an
  -- inventory already built from them, and changing one would make the record
  -- of how the money was split a lie.
  IF v_uid IS NOT NULL AND NOT public.fn_can_create_games(v_club, v_uid)
     AND NOT public.is_club_admin(v_club, v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;
  IF NOT COALESCE(v_is_mb, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_mystery_bounty');
  END IF;
  IF v_stage IS DISTINCT FROM 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_activated');
  END IF;

  v_activation := COALESCE(p_config->>'activation', 'at_the_money');
  IF v_activation NOT IN ('at_the_money','percent_field','player_count') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bad_activation_mode');
  END IF;
  v_profile := COALESCE(p_config->>'profile', 'classic');
  IF v_profile NOT IN ('balanced','classic','jackpot') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bad_profile');
  END IF;

  v_value := (p_config->>'activationValue')::numeric;
  IF v_activation = 'percent_field' AND (COALESCE(v_value,0) <= 0 OR v_value > 100) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'activation_percent_out_of_range');
  END IF;
  IF v_activation = 'player_count' AND COALESCE(v_value,0) < 2 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'activation_count_too_small');
  END IF;

  v_top := COALESCE((p_config->>'topPercent')::numeric, 20);
  IF v_top <= 0 OR v_top > 100 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'top_percent_out_of_range');
  END IF;

  v_mystery := COALESCE((p_config->>'poolPercent')::numeric, 50);
  v_regular := COALESCE((p_config->>'regularPoolPercent')::numeric, 100 - v_mystery);
  IF v_mystery < 0 OR v_regular < 0 OR v_mystery + v_regular <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'pool_split_invalid');
  END IF;

  UPDATE public.tournaments
     SET mystery_bounty_activation = v_activation,
         mystery_bounty_activation_value = v_value,
         mystery_bounty_profile = v_profile,
         mystery_bounty_top_percent = v_top,
         mystery_bounty_pool_percent = v_mystery,
         mystery_bounty_regular_pool_percent = v_regular
   WHERE id = p_tournament_id;

  RETURN jsonb_build_object('ok', true, 'activation', v_activation, 'profile', v_profile,
    'activation_value', v_value, 'top_percent', v_top,
    'pool_percent', v_mystery, 'regular_pool_percent', v_regular);
END;
$$;


ALTER FUNCTION public.fn_apply_mystery_bounty_config(p_tournament_id uuid, p_config jsonb) OWNER TO postgres;

--
-- Name: fn_apply_prize_guarantee(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_apply_prize_guarantee(p_tournament_id uuid, p_source text DEFAULT 'engine'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_overlay numeric;
  v_ledger_count integer;
  v_escrow public.tournament_escrow%ROWTYPE;
BEGIN
  v_result:=public.fn_ca_apply_prize_guarantee_core(
    p_tournament_id,p_source);
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_result;
  END IF;
  v_overlay:=COALESCE((v_result->>'overlay')::numeric,0);
  IF v_overlay::text IN ('NaN','Infinity','-Infinity')
     OR v_overlay<0 OR v_overlay IS DISTINCT FROM round(v_overlay,2) THEN
    RAISE EXCEPTION 'guarantee core returned invalid overlay %',v_overlay
      USING ERRCODE='P0404';
  END IF;
  IF v_overlay>0 THEN
    SELECT count(*) INTO v_ledger_count
      FROM public.chip_ledger l
     WHERE l.idempotency_key=
             'tourney:'||p_tournament_id::text||':guarantee_overlay'
       AND l.tournament_id=p_tournament_id
       AND l.to_type='prize_liability'
       AND l.to_entity_id=p_tournament_id
       AND l.category='overlay'
       AND l.amount=v_overlay
       AND l.from_entity_id=(v_result->>'bank_entity_id')::uuid
       AND l.from_type=CASE WHEN v_result->>'bank_type'='union'
                            THEN 'union_bank' ELSE 'club_treasury' END;
    SELECT * INTO v_escrow
      FROM public.tournament_escrow e
     WHERE e.tournament_id=p_tournament_id
     FOR UPDATE;
    IF v_ledger_count<>1 OR NOT FOUND
       OR COALESCE(v_escrow.enforced,false) IS NOT TRUE
       OR v_result->>'escrow_after' IS NULL
       OR v_escrow.prize_balance IS DISTINCT FROM
            (v_result->>'escrow_after')::numeric THEN
      RAISE EXCEPTION
        'guarantee overlay is not one exact journaled escrow credit'
        USING ERRCODE='P0404';
    END IF;
  END IF;
  RETURN v_result||jsonb_build_object('overlay_journaled',true);
END;
$$;


ALTER FUNCTION public.fn_apply_prize_guarantee(p_tournament_id uuid, p_source text) OWNER TO postgres;

--
-- Name: fn_apply_prize_guarantee_before_atomic_proof(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_apply_prize_guarantee_before_atomic_proof(p_tournament_id uuid, p_source text DEFAULT 'engine'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_t record; v_overlay numeric; v_final numeric; v_claimed integer;
  v_union uuid; v_bank_type text; v_bank_entity uuid;
  v_balance_after numeric; v_bank_name text; v_updated integer;
  v_note text := 'Guarantees are funded daily; union rake returns at the '
              || 'weekly rakeback close, so a mid-week dip is usually timing. '
              || 'Escalate if it survives a close.';
begin
  select t.id, t.club_id, t.name, t.union_id, coalesce(t.is_private, false) as is_private,
         coalesce(t.prize_pool, 0) as pool,
         coalesce(t.guaranteed_prize, 0) as gtd, coalesce(t.prize_pool_finalized, false) as finalized
    into v_t from public.tournaments t where t.id = p_tournament_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  if v_t.finalized then
    return jsonb_build_object('ok', true, 'already_finalized', true, 'prize_pool', v_t.pool);
  end if;

  v_final := greatest(v_t.pool, v_t.gtd);
  v_overlay := round(v_final - v_t.pool, 2);

  if v_overlay > 0 then
    -- ZERO-DRIFT phase 2: overlay funding = 'overlay' vs the tournament.
    perform set_config('app.ledger_category', 'overlay', true);
    perform set_config('app.ledger_counterparty', 'prize_liability', true);
    perform set_config('app.ledger_counterparty_entity', p_tournament_id::text, true);

    -- The event owns its funding scope, as in fn_ca_fund_overlay_on_lock.
    -- A club joining another union must not redirect this event's guarantee.
    v_union := CASE WHEN v_t.is_private THEN NULL ELSE v_t.union_id END;
    if v_union is not null then
      v_bank_type := 'union'; v_bank_entity := v_union;
    else
      v_bank_type := 'club'; v_bank_entity := v_t.club_id;
    end if;

    insert into public.tournament_guarantee_overlays
      (tournament_id, club_id, amount, pool_before, pool_after, source,
       bank_type, bank_entity_id, union_id)
    values (p_tournament_id, v_t.club_id, v_overlay, v_t.pool, v_final,
            coalesce(p_source, 'engine'), v_bank_type, v_bank_entity, v_union)
    on conflict (tournament_id) do nothing;
    get diagnostics v_claimed = row_count;

    if v_claimed = 0 then
      update public.tournaments set prize_pool_finalized = true where id = p_tournament_id;
      return jsonb_build_object('ok', true, 'already_funded', true, 'prize_pool', v_t.pool);
    end if;

    if v_bank_type = 'union' then
      update public.union_wallets
         set chip_balance = coalesce(chip_balance, 0) - v_overlay,
             updated_at = now()
       where union_id = v_union
       returning chip_balance into v_balance_after;

      if v_balance_after is null then
        update public.tournament_guarantee_overlays
           set bank_type = 'club', bank_entity_id = v_t.club_id
         where tournament_id = p_tournament_id;
        update public.clubs
           set chip_treasury = coalesce(chip_treasury, 0) - v_overlay, updated_at = now()
         where id = v_t.club_id
         returning chip_treasury into v_balance_after;
        v_bank_type := 'club'; v_bank_entity := v_t.club_id;
      else
        insert into public.union_wallet_transactions
          (union_id, wallet, direction, amount, balance_after, tx_type, club_id, notes)
        values
          (v_union, 'chip_balance', 'debit', v_overlay, v_balance_after,
           'guarantee_overlay', v_t.club_id,
           'Overlay for tournament ' || coalesce(v_t.name, p_tournament_id::text)
             || ' (' || p_tournament_id || '), pool ' || v_t.pool || ' -> ' || v_final);
      end if;
    else
      update public.clubs
         set chip_treasury = coalesce(chip_treasury, 0) - v_overlay, updated_at = now()
       where id = v_t.club_id
       returning chip_treasury into v_balance_after;
    end if;

    -- A missing bank must not manufacture an overlay or finalize the pool.
    -- RETURNING yields a non-null numeric balance after any actual debit,
    -- including the existing union-to-club fallback.
    if v_balance_after is null then
      raise exception 'guarantee_funding_bank_missing: tournament %, bank %/%',
        p_tournament_id, v_bank_type, v_bank_entity;
    end if;

    update public.tournament_guarantee_overlays
       set treasury_after = v_balance_after
     where tournament_id = p_tournament_id;

    select case when v_bank_type = 'union'
                then (select u.name from public.unions u where u.id = v_union)
                else (select c.name from public.clubs c where c.id = v_t.club_id) end
      into v_bank_name;

    if v_balance_after is not null and v_balance_after < 0 then
      update public.financial_alerts
         set severity = 'critical',
             message = 'Bank is negative from funding advertised guarantees: '
                       || coalesce(v_bank_name, v_bank_entity::text),
             context = jsonb_build_object(
                         'bank_type', v_bank_type,
                         'bank_entity_id', v_bank_entity,
                         'club_id', v_t.club_id,
                         'balance_after', v_balance_after,
                         'shortfall', round(-v_balance_after, 2),
                         'latest_tournament_id', p_tournament_id,
                         'latest_overlay', v_overlay,
                         'note', v_note),
             created_at = now()
       where source = 'fn_apply_prize_guarantee'
         and resolved is not true
         and context->>'bank_entity_id' = v_bank_entity::text;
      get diagnostics v_updated = row_count;

      if v_updated = 0 then
        insert into public.financial_alerts (severity, source, message, context)
        values ('critical', 'fn_apply_prize_guarantee',
                'Bank is negative from funding advertised guarantees: '
                  || coalesce(v_bank_name, v_bank_entity::text),
                jsonb_build_object(
                  'bank_type', v_bank_type,
                  'bank_entity_id', v_bank_entity,
                  'club_id', v_t.club_id,
                  'balance_after', v_balance_after,
                  'shortfall', round(-v_balance_after, 2),
                  'latest_tournament_id', p_tournament_id,
                  'latest_overlay', v_overlay,
                  'note', v_note));
      end if;
    end if;
  end if;

  update public.tournaments
     set prize_pool = v_final, prize_pool_finalized = true
   where id = p_tournament_id;

  return jsonb_build_object('ok', true, 'prize_pool', v_final,
    'overlay', coalesce(v_overlay, 0),
    'bank_type', v_bank_type, 'bank_entity_id', v_bank_entity,
    'treasury_after', v_balance_after);
end;
$$;


ALTER FUNCTION public.fn_apply_prize_guarantee_before_atomic_proof(p_tournament_id uuid, p_source text) OWNER TO postgres;

--
-- Name: FUNCTION fn_apply_prize_guarantee_before_atomic_proof(p_tournament_id uuid, p_source text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_apply_prize_guarantee_before_atomic_proof(p_tournament_id uuid, p_source text) IS 'Fund a tournament overlay from the bank that owns the club: the UNION bank (union_wallets.chip_balance) for a union-affiliated club, the club''s own chip_treasury for a standalone club. Idempotent via the PK claim on tournament_guarantee_overlays; every union debit writes union_wallet_transactions; a negative bank raises one deduped critical alert per bank.';


--
-- Name: fn_apply_rakeback_player_stats_batch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_apply_rakeback_player_stats_batch(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  it jsonb;
  v_ok integer := 0;
  v_failed integer := 0;
  v_first_error text := NULL;
BEGIN
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RETURN jsonb_build_object('ok', 0, 'failed', 0, 'error', 'p_items must be a jsonb array');
  END IF;

  -- ---------------------------------------------------------------- fast path
  BEGIN
    WITH src AS (
      SELECT DISTINCT ON (rake_record_id, user_id)
             rake_record_id, user_id, club_id, hands, rake
        FROM (
          SELECT (e->>'rake_record_id')::uuid        AS rake_record_id,
                 (e->>'user_id')::uuid               AS user_id,
                 (e->>'club_id')::uuid               AS club_id,
                 COALESCE((e->>'hands')::integer, 1) AS hands,
                 COALESCE((e->>'rake')::numeric, 0)  AS rake
            FROM jsonb_array_elements(p_items) AS e
        ) parsed
       WHERE rake_record_id IS NOT NULL
         AND user_id        IS NOT NULL
         AND club_id        IS NOT NULL
    ),
    ins AS (
      INSERT INTO public.rakeback_stats_applied (rake_record_id, user_id, hands, rake)
      SELECT rake_record_id, user_id, hands, rake FROM src
      ON CONFLICT (rake_record_id, user_id) DO NOTHING
      RETURNING rake_record_id, user_id, hands, rake
    ),
    agg AS (
      SELECT i.user_id,
             s.club_id,
             SUM(COALESCE(i.hands, 0))::integer AS hands,
             SUM(COALESCE(i.rake, 0))::numeric  AS rake
        FROM ins i
        JOIN src s
          ON s.rake_record_id = i.rake_record_id
         AND s.user_id        = i.user_id
       GROUP BY i.user_id, s.club_id
    ),
    upserted AS (
      INSERT INTO public.player_stats (
        user_id, club_id, hands_played, total_rake,
        total_winnings, total_losses, vpip, pfr, tournaments_played, tournaments_won
      )
      SELECT user_id, club_id, hands, rake, 0, 0, 0, 0, 0, 0 FROM agg
      ON CONFLICT (user_id, club_id) DO UPDATE SET
        hands_played = public.player_stats.hands_played + EXCLUDED.hands_played,
        total_rake   = ROUND((public.player_stats.total_rake + EXCLUDED.total_rake) * 100) / 100,
        updated_at   = NOW()
      RETURNING 1
    )
    SELECT count(*)::integer INTO v_ok FROM ins;

    RETURN jsonb_build_object('ok', v_ok, 'failed', 0, 'first_error', NULL);

  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_apply_rakeback_player_stats_batch: set-based path failed (%), falling back to per-item', SQLERRM;
    v_ok := 0; v_failed := 0; v_first_error := NULL;
  END;

  -- ------------------------------------------------- fallback: original loop
  FOR it IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    BEGIN
      PERFORM public.apply_rakeback_player_stats(
        (it->>'rake_record_id')::uuid,
        (it->>'user_id')::uuid,
        (it->>'club_id')::uuid,
        COALESCE((it->>'hands')::integer, 1),
        COALESCE((it->>'rake')::numeric, 0)
      );
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      IF v_first_error IS NULL THEN v_first_error := SQLERRM; END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('ok', v_ok, 'failed', v_failed, 'first_error', v_first_error);
END;
$$;


ALTER FUNCTION public.fn_apply_rakeback_player_stats_batch(p_items jsonb) OWNER TO postgres;

--
-- Name: fn_apply_union_ladder(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_apply_union_ladder(p_union_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_members bigint;
  v_level   smallint;
  v_clubs integer; v_admins integer; v_supers integer; v_agents integer;
  v_units numeric; v_units_up integer; v_hlevel integer; v_cursor integer;
BEGIN
  IF p_union_id IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.unions WHERE id = p_union_id) THEN RETURN; END IF;

  SELECT member_count INTO v_members
    FROM public.fn_batch_union_realtime_member_counts(ARRAY[p_union_id]);
  v_members := COALESCE(v_members, 0);
  v_level := public.fn_club_level_for_members(v_members::integer);

  SELECT count(DISTINCT uc.club_id),
         COALESCE(sum(c.admin_count), 0),
         COALESCE(sum(c.super_agent_count), 0),
         COALESCE(sum(c.agent_count), 0)
    INTO v_clubs, v_admins, v_supers, v_agents
    FROM public.union_clubs uc
    JOIN public.clubs c ON c.id = uc.club_id
   WHERE uc.union_id = p_union_id;
  v_units := (v_admins * 1.00) + (v_supers * 1.00) + (v_agents * 0.25);
  v_units_up := CEIL(v_units);
  v_hlevel := 1;
  FOR v_cursor IN 1..50 LOOP
    IF v_units_up >= ROUND(2 * POWER(1.086, v_cursor - 1)) THEN v_hlevel := v_cursor; ELSE EXIT; END IF;
  END LOOP;

  UPDATE public.unions SET
    member_count               = v_members,
    total_players              = v_members,
    club_count                 = v_clubs,
    level                      = v_level,
    player_level               = v_level,
    player_threshold_current   = public.fn_club_level_min_members(v_level),
    player_threshold_next      = public.fn_club_level_min_members(v_level + 1),
    total_admins               = v_admins,
    total_super_agents         = v_supers,
    total_agents               = v_agents,
    hierarchy_units            = v_units,
    hierarchy_units_rounded_up = v_units_up,
    hierarchy_level            = v_hlevel,
    hierarchy_threshold_current = ROUND(2 * POWER(1.086, v_hlevel - 1)),
    hierarchy_threshold_next    = ROUND(2 * POWER(1.086, LEAST(v_hlevel, 49))),
    updated_at                 = now()
  WHERE id = p_union_id;
END;
$$;


ALTER FUNCTION public.fn_apply_union_ladder(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_approve_cashout_atomic(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_approve_cashout_atomic(p_cashout_id uuid, p_agent_id uuid, p_agent_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_cashout record;
  v_escrow  record;
  v_role    text;
  v_agent_row uuid;
  v_after   numeric;
BEGIN
  SELECT * INTO v_cashout FROM cashout_requests WHERE id = p_cashout_id FOR UPDATE;
  IF v_cashout IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'cashout not found');
  END IF;

  IF v_cashout.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'cashout not in pending status',
                              'current_status', v_cashout.status);
  END IF;

  SELECT role INTO v_role
    FROM club_members
   WHERE club_id = v_cashout.club_id
     AND user_id = p_agent_id
     AND role IN ('agent','sub_agent','super_agent','owner','co_owner','admin');
  IF v_role IS NULL AND EXISTS (
       SELECT 1 FROM clubs WHERE id = v_cashout.club_id AND owner_id = p_agent_id) THEN
    v_role := 'owner';
  END IF;
  IF v_role IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authorized to approve for this club');
  END IF;

  -- Release the hold if there is one. A request created before 2026-08-25 has
  -- no chip_escrow row (see fn_request_cashout above) but its chips were still
  -- debited, so a missing hold is legacy rather than fraud; an ALREADY RELEASED
  -- hold is neither, and must stop here.
  SELECT * INTO v_escrow FROM chip_escrow WHERE cashout_request_id = p_cashout_id FOR UPDATE;
  IF v_escrow.id IS NOT NULL AND v_escrow.released_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'those chips have already been released');
  END IF;

  -- THE AGENT WALLET, not the approver's playing balance. This used to credit
  -- club_members.chip_balance, which is the approver's PLAYER wallet: an agent
  -- who accepted a cash out found the chips in the account they buy in from.
  SELECT id INTO v_agent_row
    FROM agents WHERE club_id = v_cashout.club_id AND user_id = p_agent_id FOR UPDATE;
  IF v_agent_row IS NULL THEN
    INSERT INTO agents (user_id, club_id, role, status, agent_wallet_balance, promo_wallet_balance)
    VALUES (p_agent_id, v_cashout.club_id, v_role, 'active', 0, 0)
    RETURNING id INTO v_agent_row;
  END IF;

  UPDATE agents
     SET agent_wallet_balance = COALESCE(agent_wallet_balance, 0) + v_cashout.amount,
         updated_at = NOW()
   WHERE id = v_agent_row
  RETURNING agent_wallet_balance INTO v_after;

  IF v_escrow.id IS NOT NULL THEN
    UPDATE chip_escrow SET released_at = NOW(), release_type = 'completed' WHERE id = v_escrow.id;
  END IF;

  UPDATE cashout_requests
     SET status = 'approved',
         agent_note = COALESCE(p_agent_note, agent_note),
         updated_at = NOW(),
         acknowledged_at = NOW(),
         completed_at = NOW()
   WHERE id = p_cashout_id;

  INSERT INTO chip_transactions (
    id, club_id, from_user_id, to_user_id, amount,
    transaction_type, notes, related_cashout_id, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), v_cashout.club_id, v_cashout.player_id, p_agent_id, v_cashout.amount,
    'cashout_approved',
    COALESCE(p_agent_note, 'Cash Out Approved. Escrow Released Into The Agent Wallet'),
    p_cashout_id, v_after, NOW()
  );

  INSERT INTO notifications (user_id, type, title, message, metadata, actor_id)
  VALUES (v_cashout.player_id, 'settlement', 'Cash Out Approved',
          'Your Cash Out Of ' || trim(to_char(v_cashout.amount, 'FM999,999,999,990'))
            || ' Chips Was Approved',
          jsonb_build_object('clubId', v_cashout.club_id, 'cashoutId', p_cashout_id,
                             'amount', v_cashout.amount),
          p_agent_id);

  RETURN jsonb_build_object('success', true, 'cashout_id', p_cashout_id,
                            'amount', v_cashout.amount, 'agent_wallet_after', v_after);
END;
$$;


