-- Name: FUNCTION fn_arena_name(p_alias text, p_username text, p_display_name text, p_first_name text, p_last_name text, p_full_name text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_arena_name(p_alias text, p_username text, p_display_name text, p_first_name text, p_last_name text, p_full_name text) IS 'The Club Arena name: alias -> username -> display_name (never when it is the real name) -> Player. Mirrors src/utils/playerDisplayName.ts arena branch. Dan 2026-09-02: the arena is always the poker alias; the real name lives in the World Hub.';


--
-- Name: fn_arena_withdraw(integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_arena_withdraw(p_amount integer, p_op_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_club uuid; v_arena numeric; v_after integer; v_ref text;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'authentication_required');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive');
  END IF;
  IF p_op_id IS NULL OR btrim(p_op_id) = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'op_id_required');
  END IF;
  v_ref := 'arena-withdraw:' || p_op_id;

  IF EXISTS (SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope = 'arena_withdrawals' AND f.cleared_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'arena_withdrawals_frozen');
  END IF;

  SELECT s.club_id INTO v_club FROM public.ca_arena_settings s WHERE s.id = 1;
  IF v_club IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'the_arena_club_does_not_exist_yet');
  END IF;

  IF EXISTS (SELECT 1 FROM public.diamond_transactions WHERE reference_id = v_ref) THEN
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'withdrawn', p_amount,
                              'arena_balance', public.fn_ca_arena_diamonds());
  END IF;

  UPDATE public.club_members
     SET chip_balance = chip_balance - p_amount
   WHERE club_id = v_club AND user_id = v_user AND chip_balance >= p_amount
  RETURNING chip_balance INTO v_arena;
  IF v_arena IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'insufficient_arena_balance');
  END IF;

  UPDATE public.profiles
     SET diamonds = diamonds + p_amount, updated_at = now()
   WHERE id = v_user
  RETURNING diamonds INTO v_after;
  IF v_after IS NULL THEN
    -- The player's profile is gone underneath the withdrawal. Raising undoes the arena debit in
    -- the same transaction; there is nothing to compensate afterwards (CLAUDE.md 10.12).
    RAISE EXCEPTION 'arena withdrawal found no profile for %', v_user USING ERRCODE = 'P0431';
  END IF;

  INSERT INTO public.diamond_transactions
    (user_id, amount, transaction_type, type, source, description, balance_after, reference_id,
     counterparty, issuance_class, metadata)
  VALUES
    (v_user, p_amount, 'arena_withdraw', 'arena_withdraw', 'fn_arena_withdraw',
     'Withdrawn from the Diamond Arena', v_after, v_ref,
     'arena:' || v_club::text, 'arena',
     jsonb_build_object('club_id', v_club, 'op_id', p_op_id));

  RETURN jsonb_build_object('ok', true, 'replayed', false, 'withdrawn', p_amount,
                            'wallet_balance', v_after, 'arena_balance', v_arena);
END $$;


ALTER FUNCTION public.fn_arena_withdraw(p_amount integer, p_op_id text) OWNER TO postgres;

--
-- Name: fn_assert_bounty_award_has_recipients(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assert_bounty_award_has_recipients() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_recipients int;
  v_sum        bigint;
BEGIN
  SELECT count(*), COALESCE(sum(amount_cents), 0)
    INTO v_recipients, v_sum
    FROM public.tournament_bounty_award_recipients
   WHERE award_id = NEW.id;

  IF v_recipients = 0 THEN
    RAISE EXCEPTION
      'bounty award % consumed chest % on tournament % with NO recipients - refusing to commit a chest nobody can be paid from',
      NEW.id, NEW.chest_id, NEW.tournament_id;
  END IF;

  -- The split must also hand out the whole chest. The function has its own
  -- check for this, but it only covers its own arithmetic; this covers the
  -- row as committed, whoever wrote it.
  IF v_sum <> NEW.amount_cents THEN
    RAISE EXCEPTION
      'bounty award % splits % cents across its recipients but the chest holds % - refusing to commit a split that loses or invents money',
      NEW.id, v_sum, NEW.amount_cents;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_assert_bounty_award_has_recipients() OWNER TO postgres;

--
-- Name: fn_assert_cash_chip_purchase_table(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assert_cash_chip_purchase_table(p_table_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_is_template boolean;
BEGIN
  SELECT t.tournament_id, COALESCE(t.is_template, false)
    INTO v_tournament_id, v_is_template
    FROM public.tables t
   WHERE t.id = p_table_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: cash chip purchase target does not exist'
      USING ERRCODE = 'P0002';
  END IF;
  IF v_tournament_id IS NOT NULL THEN
    RAISE EXCEPTION
      'CASH_PURCHASE_ONLY: cash buy-in, rebuy and add-on RPCs cannot fund a tournament table'
      USING ERRCODE = '55000';
  END IF;
  IF v_is_template THEN
    RAISE EXCEPTION 'IS_TEMPLATE: this is a saved table template, not a live game'
      USING ERRCODE = '55000';
  END IF;
END;
$$;


ALTER FUNCTION public.fn_assert_cash_chip_purchase_table(p_table_id uuid) OWNER TO postgres;

--
-- Name: fn_assert_tournament_manager_write_scope(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assert_tournament_manager_write_scope(p_tournament_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_lease_generation uuid;
BEGIN
  IF current_setting('app.smarter_data_actor', true)
       IS DISTINCT FROM 'tournament-manager' THEN
    RAISE EXCEPTION 'TOURNAMENT_MANAGER_SCOPE_REQUIRED: manager actor is absent'
      USING ERRCODE = '42501';
  END IF;

  IF current_setting('app.smarter_manager_request_fenced', true)
       IS DISTINCT FROM 'protocol-2' THEN
    RAISE EXCEPTION
      'TOURNAMENT_MANAGER_SCOPE_REQUIRED: request lease proof is absent'
      USING ERRCODE = '42501';
  END IF;

  BEGIN
    v_tournament_id :=
      NULLIF(current_setting('app.smarter_tournament_id', true), '')::uuid;
    v_lease_generation :=
      NULLIF(
        current_setting('app.smarter_tournament_lease_generation', true),
        ''
      )::uuid;
  EXCEPTION WHEN invalid_text_representation OR null_value_not_allowed THEN
    RAISE EXCEPTION 'TOURNAMENT_MANAGER_SCOPE_INVALID: malformed authority context'
      USING ERRCODE = '22023';
  END;

  IF p_tournament_id IS NULL
     OR v_tournament_id IS NULL
     OR v_lease_generation IS NULL
     OR p_tournament_id IS DISTINCT FROM v_tournament_id THEN
    RAISE EXCEPTION
      'TOURNAMENT_MANAGER_SCOPE_VIOLATION: row belongs to another tournament'
      USING ERRCODE = '42501';
  END IF;

END;
$$;


ALTER FUNCTION public.fn_assert_tournament_manager_write_scope(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_assert_tournament_manager_write_scope(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_assert_tournament_manager_write_scope(p_tournament_id uuid) IS 'Private Stage-B row-scope proof. A manager write must consume the transaction marker set only after the request hook locks its exact fresh protocol-2 lease, then name that same tournament and generation.';


--
-- Name: fn_assign_agent_to_super_agent(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assign_agent_to_super_agent(p_agent_user_id uuid, p_super_agent_user_id uuid, p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_agent uuid; v_super uuid;
BEGIN
  IF NOT public.fn_is_any_union_overseer(auth.uid()) AND NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  SELECT id INTO v_agent FROM agents WHERE user_id = p_agent_user_id AND club_id = p_club_id;
  SELECT id INTO v_super FROM agents WHERE user_id = p_super_agent_user_id AND club_id = p_club_id;
  IF v_agent IS NULL OR v_super IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'agent_or_super_agent_not_found');
  END IF;
  IF v_agent = v_super THEN
    RETURN jsonb_build_object('success', false, 'error', 'agent_cannot_report_to_itself');
  END IF;
  -- No cycles: the proposed parent must not already sit beneath this agent.
  IF EXISTS (
    WITH RECURSIVE up AS (
      SELECT id, parent_agent_id FROM agents WHERE id = v_super
      UNION ALL
      SELECT a.id, a.parent_agent_id FROM agents a JOIN up ON up.parent_agent_id = a.id
    ) SELECT 1 FROM up WHERE id = v_agent
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'would_create_cycle');
  END IF;

  UPDATE agents SET parent_agent_id = v_super, updated_at = now() WHERE id = v_agent;
  UPDATE agents SET role = 'super_agent', updated_at = now()
   WHERE id = v_super AND COALESCE(role,'agent') <> 'super_agent';

  RETURN jsonb_build_object('success', true, 'agent_id', v_agent, 'super_agent_id', v_super);
END $$;


ALTER FUNCTION public.fn_assign_agent_to_super_agent(p_agent_user_id uuid, p_super_agent_user_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_assign_current_challenge_period(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assign_current_challenge_period(p_user_id uuid, p_tier text, p_period_key text, p_count integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.fn_lock_daily_mission_user(p_user_id);
  PERFORM public.fn_assign_current_challenge_period_serialized_body(
    p_user_id,
    p_tier,
    p_period_key,
    p_count
  );
END;
$$;


ALTER FUNCTION public.fn_assign_current_challenge_period(p_user_id uuid, p_tier text, p_period_key text, p_count integer) OWNER TO postgres;

--
-- Name: fn_assign_current_challenge_period_serialized_body(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assign_current_challenge_period_serialized_body(p_user_id uuid, p_tier text, p_period_key text, p_count integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_day_index integer;
  v_existing integer;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'A player is required';
  END IF;
  IF p_tier IS NULL OR p_period_key IS NULL OR p_count IS NULL
     OR (p_tier = 'daily' AND (p_count <> 5 OR p_period_key !~ '^\d{4}-\d{2}-\d{2}$'))
     OR (p_tier = 'weekly' AND (p_count <> 3 OR p_period_key !~ '^W\d{4}-\d{2}-\d{2}$'))
     OR (p_tier = 'monthly' AND (p_count <> 2 OR p_period_key !~ '^M\d{4}-\d{2}$'))
     OR p_tier NOT IN ('daily', 'weekly', 'monthly') THEN
    RAISE EXCEPTION 'Invalid canonical Daily Missions period contract';
  END IF;

  SELECT count(*) INTO v_existing
  FROM public.user_daily_challenges
  WHERE user_id = p_user_id AND assigned_date = p_period_key;

  IF v_existing > p_count OR EXISTS (
    SELECT 1
    FROM public.user_daily_challenges
    WHERE user_id = p_user_id
      AND assigned_date = p_period_key
      AND tier_snapshot IS DISTINCT FROM p_tier
  ) THEN
    RAISE EXCEPTION 'Existing % period is not a canonical Daily Missions contract set', p_tier;
  END IF;
  IF v_existing = p_count THEN
    RETURN;
  END IF;

  IF p_tier = 'daily' THEN
    v_day_index := abs(p_period_key::date - date '1970-01-01');

    -- Five distinct challenge types move through a circular type wheel. Each
    -- selected type advances through its own complete catalog list. This
    -- guarantees bounded exposure for every active Daily contract without
    -- coupling selection eligibility to its reward amount.
    INSERT INTO public.user_daily_challenges (
      user_id, challenge_id, assigned_date, progress, completed
    )
    WITH challenge_types AS (
      SELECT challenge_type,
             row_number() OVER (ORDER BY challenge_type) - 1 AS type_ordinal,
             count(*) OVER () AS type_count
      FROM (
        SELECT DISTINCT challenge_type
        FROM public.daily_challenge_catalog
        WHERE tier = 'daily' AND is_active
      ) types
    ), ranked AS (
      SELECT c.id,
             row_number() OVER (PARTITION BY c.challenge_type ORDER BY c.id) - 1 AS item_ordinal,
             count(*) OVER (PARTITION BY c.challenge_type) AS item_count,
             t.type_ordinal,
             t.type_count,
             mod(
               t.type_ordinal - mod(v_day_index::bigint, t.type_count) + t.type_count,
               t.type_count
             ) AS type_distance
      FROM public.daily_challenge_catalog c
      JOIN challenge_types t USING (challenge_type)
      WHERE c.tier = 'daily' AND c.is_active
    ), selected AS (
      SELECT id, type_ordinal, type_distance
      FROM ranked
      WHERE type_distance < p_count
        AND item_ordinal = mod(
          (v_day_index::bigint / type_count) + type_distance,
          item_count
        )
    )
    SELECT p_user_id, selected.id, p_period_key, 0, false
    FROM selected
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.user_daily_challenges existing
      WHERE existing.user_id = p_user_id
        AND existing.assigned_date = p_period_key
        AND existing.challenge_id = selected.id
    )
    ORDER BY selected.type_distance, selected.type_ordinal, selected.id
    LIMIT (p_count - v_existing)
    ON CONFLICT (user_id, challenge_id, assigned_date) DO NOTHING;
  ELSE
    INSERT INTO public.user_daily_challenges (
      user_id, challenge_id, assigned_date, progress, completed
    )
    WITH one_per_type AS (
      SELECT DISTINCT ON (c.challenge_type)
             c.id,
             c.challenge_type,
             md5(p_period_key || '|' || c.id) AS draw
      FROM public.daily_challenge_catalog c
      WHERE c.tier = p_tier AND c.is_active
      ORDER BY c.challenge_type, md5(p_period_key || '|' || c.id), c.id
    )
    SELECT p_user_id, one_per_type.id, p_period_key, 0, false
    FROM one_per_type
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.user_daily_challenges existing
      WHERE existing.user_id = p_user_id
        AND existing.assigned_date = p_period_key
        AND existing.challenge_id = one_per_type.id
    )
    ORDER BY draw, id
    LIMIT (p_count - v_existing)
    ON CONFLICT (user_id, challenge_id, assigned_date) DO NOTHING;
  END IF;

  IF (
    SELECT count(*)
    FROM public.user_daily_challenges
    WHERE user_id = p_user_id AND assigned_date = p_period_key
  ) <> p_count THEN
    RAISE EXCEPTION 'Catalog cannot supply the canonical % % contracts', p_count, p_tier;
  END IF;
END;
$_$;


ALTER FUNCTION public.fn_assign_current_challenge_period_serialized_body(p_user_id uuid, p_tier text, p_period_key text, p_count integer) OWNER TO postgres;

--
-- Name: fn_assign_horse_lanes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assign_horse_lanes() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_events int; v_cash int; v_total int; v_res jsonb;
begin
  select count(*) into v_total from profiles where is_horse;
  if v_total = 0 then return jsonb_build_object('assigned', 0); end if;

  v_events := floor(v_total * 0.33);
  v_cash := floor(v_total * 0.33);

  with ordered as (
    select id, row_number() over (order by md5(id::text)) rn
    from profiles where is_horse
  ), lanes as (
    select id,
           case when rn <= v_events then 'events'
                when rn <= v_events + v_cash then 'cash'
                else 'both' end as lane
    from ordered
  )
  update profiles p
     set horse_profile = coalesce(p.horse_profile, '{}'::jsonb) || jsonb_build_object('lane', l.lane)
    from lanes l
   where p.id = l.id
     and coalesce(p.horse_profile->>'lane', '') is distinct from l.lane;

  select jsonb_object_agg(lane, n) into v_res from (
    select horse_profile->>'lane' lane, count(*) n
    from profiles where is_horse group by 1
  ) s;
  return jsonb_build_object('total', v_total, 'distribution', v_res);
end $$;


ALTER FUNCTION public.fn_assign_horse_lanes() OWNER TO postgres;

--
-- Name: fn_assign_horse_lanes_for_club(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assign_horse_lanes_for_club(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_events int; v_cash int; v_total int; v_res jsonb;
begin
  if not fn_caller_is_engine() then
    raise exception 'fn_assign_horse_lanes_for_club is engine-only';
  end if;

  create temp table _lane_pool on commit drop as
    select p.id
      from profiles p
      join club_members cm on cm.user_id = p.id
     where cm.club_id = p_club_id
       and cm.is_bot
       and p.is_horse;

  select count(*) into v_total from _lane_pool;
  if v_total = 0 then
    return jsonb_build_object('club_id', p_club_id, 'total', 0, 'distribution', '{}'::jsonb);
  end if;

  v_events := floor(v_total * 0.33);
  v_cash   := floor(v_total * 0.33);

  with ordered as (
    select id, row_number() over (order by md5(id::text)) rn from _lane_pool
  ), lanes as (
    select id,
           case when rn <= v_events then 'events'
                when rn <= v_events + v_cash then 'cash'
                else 'both' end as lane
      from ordered
  )
  update profiles p
     set horse_profile = coalesce(p.horse_profile, '{}'::jsonb) || jsonb_build_object('lane', l.lane)
    from lanes l
   where p.id = l.id
     and coalesce(p.horse_profile->>'lane', '') is distinct from l.lane;

  select jsonb_object_agg(lane, n) into v_res from (
    select p.horse_profile->>'lane' lane, count(*) n
      from profiles p join _lane_pool lp on lp.id = p.id
     group by 1
  ) s;

  return jsonb_build_object('club_id', p_club_id, 'total', v_total, 'distribution', v_res);
end
$$;


ALTER FUNCTION public.fn_assign_horse_lanes_for_club(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_assign_horse_stake_bands(integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assign_horse_stake_bands(p_min_hands integer DEFAULT 1000, p_hysteresis_pct numeric DEFAULT 5) RETURNS TABLE(band text, horses integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_available text[];
begin
  v_available := public.fn_available_stake_bands();

  -- FAIL OPEN. No enabled game anywhere is not evidence that every band is
  -- empty, it is evidence that we cannot see the floor. Change nothing and
  -- leave every horse exactly where it is.
  if coalesce(array_length(v_available, 1), 0) = 0 then
    return;
  end if;

  return query
  with perf as (
    select ps.user_id,
           sum(ps.hands_played)                     as hands,
           sum(ps.total_winnings - ps.total_losses) as net,
           sum(ps.sum_big_blind)                    as sum_bb
      from public.player_stats ps
      join public.profiles p on p.id = ps.user_id
     where p.is_horse is true
     group by ps.user_id
  ),
  ranked as (
    select p.id,
           coalesce(perf.hands, 0) as hands,
           case when coalesce(perf.sum_bb, 0) > 0
                then (perf.net / perf.sum_bb) * 100
                else null end as bb100,
           p.horse_profile->>'stakeBand' as current_band
      from public.profiles p
      left join perf on perf.user_id = p.id
     where p.is_horse is true
  ),
  scored as (
    select id, current_band,
           hands >= p_min_hands and bb100 is not null as ranked_ok,
           case when hands >= p_min_hands and bb100 is not null
                then 100.0 * (percent_rank() over (
                       partition by (hands >= p_min_hands and bb100 is not null)
                       order by bb100, id))
                else null end as merit_pct
      from ranked
  ),
  -- THE MERIT LADDER, UNCHANGED. Same metric, same hands floor, same cut
  -- points. This is what the horse has EARNED, before the floor is consulted.
  target as (
    select id, current_band, ranked_ok, merit_pct,
           case
             when not ranked_ok   then 'micro'
             when merit_pct <  22 then 'micro'
             when merit_pct <  74 then 'low'
             when merit_pct <  89 then 'mid'
             else                      'high'
           end as merit_band
      from scored
  ),
  -- THE LADDER PROJECTED ONTO THE GAMES THAT EXIST. The order is preserved
  -- because the projection is monotone: two horses never swap places, a
  -- whole rung is folded into the one below it.
  projected as (
    select id, current_band, ranked_ok, merit_pct, merit_band,
           public.fn_project_stake_band(merit_band, v_available) as want
      from target
  ),
  settled as (
    select id, want, current_band, merit_pct, ranked_ok,
           case
             when current_band is null or current_band not in ('micro','low','mid','high')
               then want
             when current_band = want then want
             when not ranked_ok then current_band
             when merit_pct is null then current_band
             when abs(merit_pct - case merit_band
                                    when 'micro' then 22.0
                                    when 'low'   then 74.0
                                    when 'mid'   then 89.0
                                    else 89.0
                                  end) >= p_hysteresis_pct
               then want
             else current_band
           end as settled_band
      from projected
  ),
  -- THE CLAMP. Hysteresis holds a horse near a boundary in the band it
  -- already has, and that band may be one the operator has since closed - it
  -- is exactly how the 100 'high' horses would otherwise survive this run.
  -- Whatever path a horse took above, it lands on a band that has a game.
  clamped as (
    select id, public.fn_project_stake_band(settled_band, v_available) as final_band
      from settled
  ),
  written as (
    update public.profiles p
       set horse_profile = coalesce(p.horse_profile, '{}'::jsonb)
                           || jsonb_build_object('stakeBand', c.final_band)
      from clamped c
     where p.id = c.id
       and p.is_horse is true
       and coalesce(p.horse_profile->>'stakeBand', '') is distinct from c.final_band
    returning c.final_band as band
  )
  select w.band, count(*)::integer from written w group by w.band;
end;
$$;


ALTER FUNCTION public.fn_assign_horse_stake_bands(p_min_hands integer, p_hysteresis_pct numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_assign_horse_stake_bands(p_min_hands integer, p_hysteresis_pct numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_assign_horse_stake_bands(p_min_hands integer, p_hysteresis_pct numeric) IS 'Assign every horse a merit stake band from bb/100 over player_stats, then PROJECT that band onto the bands that have an enabled cash game (fn_available_stake_bands + fn_project_stake_band). Merit decides the order, the floor decides which rungs exist. Downward only, never promotes, and changes nothing at all when no cash game is enabled. 2026-09-06: before this, 100 horses held ''high'' with zero enabled games above bb 6 and could sit nowhere.';


--
-- Name: fn_assign_player_to_agent(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assign_player_to_agent(p_player_user_id uuid, p_agent_user_id uuid, p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_agent record; v_is_member boolean;
BEGIN
  IF NOT public.fn_is_any_union_overseer(auth.uid())
     AND NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT EXISTS (SELECT 1 FROM agents a
                      WHERE a.user_id = auth.uid() AND a.club_id = p_club_id
                        AND a.status = 'active'))) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  SELECT a.id, a.user_id, a.club_id INTO v_agent
    FROM agents a
   WHERE a.user_id = p_agent_user_id AND a.club_id = p_club_id AND a.status = 'active';
  IF v_agent.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'agent_not_active_in_club');
  END IF;

  IF p_player_user_id = p_agent_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'agent_cannot_be_own_player');
  END IF;

  SELECT EXISTS (SELECT 1 FROM club_members
                  WHERE user_id = p_player_user_id AND club_id = p_club_id)
    INTO v_is_member;
  IF NOT v_is_member THEN
    RETURN jsonb_build_object('success', false, 'error', 'player_not_member_of_club');
  END IF;

  UPDATE club_members
     SET agent_id = p_agent_user_id, updated_at = now()
   WHERE user_id = p_player_user_id AND club_id = p_club_id;

  UPDATE agents
     SET total_players = (SELECT count(*) FROM club_members
                           WHERE agent_id = p_agent_user_id AND club_id = p_club_id),
         updated_at = now()
   WHERE id = v_agent.id;

  INSERT INTO audit_trail (actor_id, actor_role, action, target_type, target_id, reason)
  VALUES (COALESCE(auth.uid(), p_agent_user_id), 'agent', 'assign_player_to_agent',
          'club_member', p_player_user_id,
          'agent ' || p_agent_user_id::text || ' in club ' || p_club_id::text);

  RETURN jsonb_build_object('success', true, 'player_id', p_player_user_id,
                            'agent_id', p_agent_user_id, 'club_id', p_club_id);
END $$;


ALTER FUNCTION public.fn_assign_player_to_agent(p_player_user_id uuid, p_agent_user_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_assign_tournament_player_seat_atomic(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assign_tournament_player_seat_atomic(p_tournament_id uuid, p_user_id uuid, p_table_id uuid, p_seat_number integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_gate jsonb;
  v_t public.tournaments%ROWTYPE;
  v_tp public.tournament_players%ROWTYPE;
  v_table public.tables%ROWTYPE;
  v_live public.table_seats%ROWTYPE;
  v_destination public.table_seats%ROWTYPE;
  v_live_count integer;
  v_stack numeric;
  v_seat_id uuid;
  v_current_players integer;
  v_rows integer;
  v_assigned_at timestamptz;
  v_previous_money_path text:=current_setting('app.money_path',true);
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'fn_assign_tournament_player_seat_atomic requires service authority'
      USING ERRCODE='28000';
  END IF;
  IF p_tournament_id IS NULL OR p_user_id IS NULL OR p_table_id IS NULL
     OR p_seat_number IS NULL OR p_seat_number NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION 'tournament, player, table and legal seat are required'
      USING ERRCODE='22023';
  END IF;

  v_gate:=public.fn_ca_lock_tournament_seat_acquisition(
    p_tournament_id,p_table_id,p_user_id);
  IF COALESCE((v_gate->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_gate;
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id;
  IF upper(COALESCE(v_t.status::text,'')) NOT IN ('REGISTERING','RUNNING') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_not_assignable',
      'status',upper(COALESCE(v_t.status::text,'')));
  END IF;

  -- Lock the beneficiary and every roster row claiming the requested
  -- coordinate before any table/seat row. This matches terminal settlement's
  -- tournament -> roster -> tables -> seats child order.
  PERFORM tp.id
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND (tp.user_id=p_user_id
       OR (tp.table_id=p_table_id AND tp.seat_number=p_seat_number))
   ORDER BY tp.id
   FOR UPDATE;

  SELECT * INTO v_tp FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','player_not_registered');
  END IF;
  IF v_tp.status::text NOT IN ('registered','playing') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','player_not_assignable','status',v_tp.status::text);
  END IF;

  IF v_tp.status::text='registered' THEN
    v_stack:=COALESCE(v_t.starting_chips,0)
             +GREATEST(COALESCE(v_tp.chips,0),0);
  ELSE
    v_stack:=COALESCE(v_tp.chips,0);
  END IF;
  IF v_stack::text IN ('NaN','Infinity','-Infinity')
     OR v_stack<=0 OR v_stack<>trunc(v_stack)
     OR v_stack>2147483647 THEN
    RETURN jsonb_build_object('ok',false,'reason','player_stack_invalid');
  END IF;

  SELECT * INTO v_table FROM public.tables tb
   WHERE tb.id=p_table_id
   FOR UPDATE;
  IF NOT FOUND OR v_table.tournament_id IS DISTINCT FROM p_tournament_id THEN
    RETURN jsonb_build_object('ok',false,'reason','table_tournament_mismatch');
  END IF;
  IF lower(COALESCE(v_table.status::text,'')) NOT IN
       ('waiting','running','active')
     OR COALESCE(v_table.is_deleted,false)
     OR p_seat_number>COALESCE(NULLIF(v_table.max_players,0),9) THEN
    RETURN jsonb_build_object('ok',false,'reason','table_not_assignable');
  END IF;

  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_user_id AND s.left_at IS NULL
   ORDER BY s.id
   FOR UPDATE OF s;
  SELECT count(*)::integer INTO v_live_count
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_user_id AND s.left_at IS NULL;
  IF v_live_count>1 THEN
    RAISE EXCEPTION 'tournament player already owns multiple live seats'
      USING ERRCODE='P0404';
  END IF;
  IF v_live_count=1 THEN
    SELECT s.* INTO v_live
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND s.user_id=p_user_id AND s.left_at IS NULL
     FOR UPDATE OF s;
    IF v_live.table_id IS DISTINCT FROM p_table_id
       OR v_live.seat_number IS DISTINCT FROM p_seat_number THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','player_already_seated_elsewhere',
        'table_id',v_live.table_id,'seat_number',v_live.seat_number);
    END IF;
    SELECT count(*)::integer INTO v_current_players
      FROM public.table_seats s
     WHERE s.table_id=p_table_id AND s.left_at IS NULL;
    IF v_live.stack IS DISTINCT FROM v_stack
       OR v_tp.status::text<>'playing'
       OR v_tp.chips IS DISTINCT FROM v_stack::integer
       OR v_tp.table_id IS DISTINCT FROM p_table_id
       OR v_tp.seat_number IS DISTINCT FROM p_seat_number
       OR v_table.current_players IS DISTINCT FROM v_current_players
       OR v_live.joined_at IS NULL THEN
      RAISE EXCEPTION 'existing tournament assignment is not an exact receipt'
        USING ERRCODE='P0404';
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'replayed',true,'tournament_id',p_tournament_id,
      'user_id',p_user_id,'table_id',p_table_id,
      'seat_id',v_live.id,'seat_number',p_seat_number,'stack',v_stack,
      'current_players',v_current_players,'assigned_at',v_live.joined_at);
  END IF;

  SELECT * INTO v_destination FROM public.table_seats s
   WHERE s.table_id=p_table_id AND s.seat_number=p_seat_number
   FOR UPDATE;
  IF FOUND AND v_destination.left_at IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','seat_taken');
  END IF;

  -- A departed occupant can still carry a stale roster coordinate. Correct
  -- that link inside this assignment transaction; never overwrite a live
  -- seat or leave two active roster rows claiming one chair.
  UPDATE public.tournament_players tp
     SET table_id=NULL,seat_number=NULL
   WHERE tp.tournament_id=p_tournament_id
     AND tp.user_id<>p_user_id
     AND tp.table_id=p_table_id AND tp.seat_number=p_seat_number;

  v_assigned_at:=clock_timestamp();
  PERFORM set_config(
    'app.money_path','fn_assign_tournament_player_seat_atomic',true);
  BEGIN
    IF v_destination.id IS NULL THEN
      INSERT INTO public.table_seats(
        table_id,user_id,seat_number,stack,status,joined_at,left_at,
        is_sitting_out,is_away,leave_pending,scheduled_leave_hands)
      VALUES(
        p_table_id,p_user_id,p_seat_number,v_stack,'active',v_assigned_at,NULL,
        false,false,false,NULL)
      RETURNING id INTO v_seat_id;
    ELSE
      UPDATE public.table_seats s
         SET user_id=p_user_id,member_id=NULL,stack=v_stack,
             status='active',joined_at=v_assigned_at,left_at=NULL,
             is_sitting_out=false,is_away=false,leave_pending=false,
             sit_out_at=NULL,scheduled_leave_hands=NULL,
             entry_hold=NULL,entry_post_agreed=false,auto_rebuy=false
       WHERE s.id=v_destination.id AND s.left_at IS NOT NULL
       RETURNING id INTO v_seat_id;
      IF v_seat_id IS NULL THEN
        RAISE EXCEPTION 'vacated tournament seat changed during assignment'
          USING ERRCODE='40001';
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'app.money_path',COALESCE(v_previous_money_path,''),true);
    RAISE;
  END;
  PERFORM set_config(
    'app.money_path',COALESCE(v_previous_money_path,''),true);

  UPDATE public.tournament_players tp
     SET status='playing',chips=v_stack::integer,
         table_id=p_table_id,seat_number=p_seat_number
   WHERE tp.id=v_tp.id AND tp.status::text IN ('registered','playing');
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament roster changed during seat assignment'
      USING ERRCODE='40001';
  END IF;

  SELECT count(*)::integer INTO v_current_players
    FROM public.table_seats s
   WHERE s.table_id=p_table_id AND s.left_at IS NULL;
  UPDATE public.tables tb
     SET current_players=v_current_players,updated_at=now()
   WHERE tb.id=p_table_id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament table vanished during seat assignment'
      USING ERRCODE='40001';
  END IF;

  IF (SELECT count(*) FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND s.user_id=p_user_id AND s.left_at IS NULL)<>1
     OR NOT EXISTS(
       SELECT 1 FROM public.table_seats s
        WHERE s.id=v_seat_id AND s.table_id=p_table_id
          AND s.user_id=p_user_id AND s.seat_number=p_seat_number
          AND s.left_at IS NULL AND s.stack=v_stack)
     OR NOT EXISTS(
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.id=v_tp.id AND tp.status::text='playing'
          AND tp.chips=v_stack::integer AND tp.table_id=p_table_id
          AND tp.seat_number=p_seat_number)
     OR NOT EXISTS(
       SELECT 1 FROM public.tables tb
        WHERE tb.id=p_table_id AND tb.tournament_id=p_tournament_id
          AND tb.current_players=v_current_players) THEN
    RAISE EXCEPTION 'atomic tournament seat assignment final proof is not exact'
      USING ERRCODE='P0404';
  END IF;

  RETURN jsonb_build_object(
    'ok',true,'replayed',false,'tournament_id',p_tournament_id,
    'user_id',p_user_id,'table_id',p_table_id,'seat_id',v_seat_id,
    'seat_number',p_seat_number,'stack',v_stack,
    'current_players',v_current_players,'assigned_at',v_assigned_at);
END;
$$;


ALTER FUNCTION public.fn_assign_tournament_player_seat_atomic(p_tournament_id uuid, p_user_id uuid, p_table_id uuid, p_seat_number integer) OWNER TO postgres;

--
-- Name: fn_atomic_buyin(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_atomic_buyin(p_user_id uuid, p_club_id uuid, p_chip_amount integer, p_diamond_cost integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_diamonds INTEGER;
  v_chips NUMERIC;
  v_new_diamonds INTEGER;
  v_new_chips NUMERIC;
BEGIN
  -- ZERO-DRIFT phase 5: reject nonsense before touching balances.
  IF COALESCE(p_chip_amount, 0) <= 0 OR COALESCE(p_diamond_cost, 0) <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid amounts');
  END IF;

  SELECT diamonds INTO v_diamonds FROM profiles WHERE id = p_user_id FOR UPDATE;
  IF v_diamonds IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Profile not found');
  END IF;

  IF v_diamonds < p_diamond_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient diamonds',
                              'needed', p_diamond_cost, 'available', v_diamonds);
  END IF;

  SELECT chip_balance INTO v_chips FROM club_members
   WHERE club_id = p_club_id AND user_id = p_user_id FOR UPDATE;
  IF v_chips IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not a club member');
  END IF;

  -- Atomic debit diamonds
  v_new_diamonds := v_diamonds - p_diamond_cost;
  UPDATE profiles
     SET diamonds = v_new_diamonds,
         diamond_balance = v_new_diamonds
   WHERE id = p_user_id;

  -- ZERO-DRIFT: the diamond leg is a real movement of supply and belongs in
  -- diamond_transactions, or the hourly snapshot reports it as a bypass.
  INSERT INTO diamond_transactions (user_id, amount, type, balance_after, description, source)
  VALUES (p_user_id, -p_diamond_cost, 'chip_purchase', v_new_diamonds,
          'Buy-In: ' || p_chip_amount || ' Chips For ' || p_diamond_cost || ' Diamonds',
          'fn_atomic_buyin');

  -- ZERO-DRIFT phase 5: a diamond->chip conversion is chip issuance. Journal
  -- it as a mint against the issuance reserve, never as an anonymous
  -- adjustment vs table_stack.
  PERFORM set_config('app.ledger_category', 'mint', true);
  PERFORM set_config('app.ledger_counterparty', 'issuance_reserve', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);

  v_new_chips := v_chips + p_chip_amount;
  UPDATE club_members SET chip_balance = v_new_chips
    WHERE club_id = p_club_id AND user_id = p_user_id;

  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);

  INSERT INTO chip_transactions (from_user_id, to_user_id, club_id, transaction_type, amount, notes)
    VALUES (p_user_id, p_user_id, p_club_id, 'buyin', p_chip_amount,
      'Buy-In: ' || p_chip_amount || ' Chips For ' || p_diamond_cost || ' Diamonds');

  RETURN jsonb_build_object('success', true, 'chipAmount', p_chip_amount,
    'diamondCost', p_diamond_cost, 'newChipBalance', v_new_chips,
    'newDiamondBalance', v_new_diamonds);
END;
$$;


ALTER FUNCTION public.fn_atomic_buyin(p_user_id uuid, p_club_id uuid, p_chip_amount integer, p_diamond_cost integer) OWNER TO postgres;

--
-- Name: fn_atomic_increment_field(text, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_atomic_increment_field(p_table_name text DEFAULT ''::text, p_id uuid DEFAULT NULL::uuid, p_field text DEFAULT ''::text, p_amount integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF p_id IS NULL OR p_table_name = '' OR p_field = '' THEN RETURN; END IF;

  -- Allowlist of (table, field) pairs we accept. Adding to this list is the
  -- only way to expand allowed atomic increments.
  IF NOT EXISTS (
    SELECT 1 FROM (VALUES
      ('clubs','member_count'),
      ('clubs','table_count'),
      ('clubs','active_players'),
      ('clubs','active_tables'),
      ('clubs','hands_played'),
      ('clubs','total_rake'),
      ('agents','total_players'),
      ('agents','active_player_count'),
      ('agents','sub_agent_count'),
      ('agents','credit_used'),
      ('agents','credit_limit'),
      ('tables','hands_played'),
      ('tournaments','registered_count'),
      ('tournaments','current_players'),
      ('tournaments','total_rake')
    ) v(t,f) WHERE t = p_table_name AND f = p_field
  ) THEN
    RAISE EXCEPTION 'fn_atomic_increment_field: (%, %) not in allowlist', p_table_name, p_field;
  END IF;

  EXECUTE format('UPDATE public.%I SET %I = COALESCE(%I, 0) + $1, updated_at = NOW() WHERE id = $2',
                 p_table_name, p_field, p_field)
  USING p_amount, p_id;
END $_$;


ALTER FUNCTION public.fn_atomic_increment_field(p_table_name text, p_id uuid, p_field text, p_amount integer) OWNER TO postgres;

--
-- Name: fn_attach_bounty_award_obligation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_attach_bounty_award_obligation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_context text := current_setting('app.bounty_obligation_id',true);
  v_obligation_id uuid;
  v_activation_generation bigint;
BEGIN
  IF NEW.bounty_obligation_id IS NULL THEN
    IF COALESCE(v_context,'')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
      v_obligation_id := v_context::uuid;
      SELECT o.id,o.activation_generation
        INTO NEW.bounty_obligation_id,v_activation_generation
        FROM public.tournament_bounty_obligations o
       WHERE o.id=v_obligation_id AND o.tournament_id=NEW.tournament_id
         AND o.eliminated_user_id=NEW.eliminated_user_id
         AND o.mode='mystery_chest' AND o.hand_id::text=NEW.hand_id;
      IF NEW.bounty_obligation_id IS NULL THEN
        RAISE EXCEPTION 'mystery award context does not match its exact generation'
          USING ERRCODE='check_violation';
      END IF;
      NEW.activation_generation := v_activation_generation;
    ELSIF EXISTS (
      SELECT 1 FROM public.tournament_bounty_obligations o
       WHERE o.tournament_id=NEW.tournament_id
         AND o.eliminated_user_id=NEW.eliminated_user_id
         AND o.mode='mystery_chest' AND o.hand_id::text=NEW.hand_id
    ) THEN
      RAISE EXCEPTION 'generation-bound mystery award has no exact obligation context'
        USING ERRCODE='check_violation';
    END IF;
  ELSE
    SELECT o.activation_generation INTO v_activation_generation
      FROM public.tournament_bounty_obligations o
     WHERE o.id=NEW.bounty_obligation_id AND o.tournament_id=NEW.tournament_id
       AND o.eliminated_user_id=NEW.eliminated_user_id
       AND o.mode='mystery_chest' AND o.hand_id::text=NEW.hand_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'mystery award names a mismatched obligation generation'
        USING ERRCODE='check_violation';
    END IF;
    NEW.activation_generation := v_activation_generation;
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_attach_bounty_award_obligation() OWNER TO postgres;

--
-- Name: fn_attach_bounty_ledger_obligation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_attach_bounty_ledger_obligation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_context text := current_setting('app.bounty_obligation_id',true);
  v_obligation_id uuid;
BEGIN
  IF NEW.bounty_obligation_id IS NULL THEN
    IF COALESCE(v_context,'')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
      v_obligation_id := v_context::uuid;
      SELECT o.id INTO NEW.bounty_obligation_id
        FROM public.tournament_bounty_obligations o
       WHERE o.id=v_obligation_id AND o.tournament_id=NEW.tournament_id
         AND o.eliminated_user_id=NEW.eliminated_player_id
         AND o.mode<>'mystery_chest';
      IF NEW.bounty_obligation_id IS NULL THEN
        RAISE EXCEPTION 'bounty ledger context does not match its exact generation'
          USING ERRCODE='check_violation';
      END IF;
    ELSIF EXISTS (
      SELECT 1 FROM public.tournament_bounty_obligations o
       WHERE o.tournament_id=NEW.tournament_id
         AND o.eliminated_user_id=NEW.eliminated_player_id
         AND o.mode<>'mystery_chest' AND o.state='pending'
    ) THEN
      RAISE EXCEPTION 'generation-bound bounty ledger insert has no exact obligation context'
        USING ERRCODE='check_violation';
    END IF;
  ELSIF NOT EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations o
     WHERE o.id=NEW.bounty_obligation_id AND o.tournament_id=NEW.tournament_id
       AND o.eliminated_user_id=NEW.eliminated_player_id
       AND o.mode<>'mystery_chest'
  ) THEN
    RAISE EXCEPTION 'bounty ledger names a mismatched obligation generation'
      USING ERRCODE='check_violation';
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_attach_bounty_ledger_obligation() OWNER TO postgres;

--
-- Name: fn_attribute_tournament_rake(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_attribute_tournament_rake(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_club uuid; v_att record; v_users integer := 0; v_chips numeric := 0;
  v_members integer := 0;
BEGIN
  SELECT t.club_id INTO v_club FROM public.tournaments t WHERE t.id = p_tournament_id;
  IF v_club IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_club');
  END IF;

  /* The denominator the userless spread divides by, surfaced so a caller can
     tell "credited nobody" from "there was nobody to credit". Without it a
     settlement that FAILED and one that had nothing to do look identical, and
     the repair queue cannot decide whether retrying is worth anything. */
  SELECT count(*) INTO v_members
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id AND tp.user_id IS NOT NULL;

  FOR v_att IN
    WITH per_user AS (
      SELECT (r.metadata->>'user_id')::uuid AS uid,
             sum(r.rake_amount) AS amt, min(r.id::text)::uuid AS row_id
        FROM public.rake_records r
       WHERE r.tournament_id = p_tournament_id AND r.is_tournament
         AND r.metadata->>'user_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       GROUP BY 1
    ),
    userless AS (
      SELECT sum(r.rake_amount) AS amt, min(r.id::text)::uuid AS row_id
        FROM public.rake_records r
       WHERE r.tournament_id = p_tournament_id AND r.is_tournament
         AND (r.metadata->>'user_id') IS NULL
      HAVING sum(r.rake_amount) > 0
    ),
    members AS (
      SELECT tp.user_id FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id AND tp.user_id IS NOT NULL
    ),
    spread AS (
      SELECT m.user_id AS uid,
             round(u.amt / NULLIF((SELECT count(*) FROM members), 0), 2) AS amt,
             u.row_id
        FROM userless u CROSS JOIN members m
    )
    SELECT x.uid, round(sum(x.amt), 2) AS amt, min(x.row_id::text)::uuid AS row_id
      FROM (SELECT * FROM per_user UNION ALL SELECT * FROM spread) x
     WHERE x.uid IS NOT NULL
     GROUP BY x.uid
    HAVING round(sum(x.amt), 2) > 0
     /* FIXED LOCK ORDER. Every row written in this loop is keyed on the user,
        so two settlements that share a player contend. Walking them in a
        deterministic order turns a deadlock into a wait. Do not remove. */
     ORDER BY x.uid
  LOOP
    v_users := v_users + 1;
    v_chips := v_chips + v_att.amt;

    PERFORM public.fn_award_vip_credit(
      v_att.uid, v_att.amt, 'tournament_rake', p_tournament_id, 'Tournament rake generated');

    PERFORM public.credit_agent_commission_from_rake(
      v_att.uid, v_club, v_att.amt,
      'tournament_rake_settlement',
      md5('trs:' || p_tournament_id::text || ':' || v_att.uid::text)::uuid,
      'tournament rake settlement');

    PERFORM public.apply_rakeback_player_stats(
      v_att.row_id, v_att.uid, v_club, 0, v_att.amt);
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'attributed_users', v_users,
                            'members', v_members,
                            'attributed_chips', round(v_chips, 2));
END;
$_$;


ALTER FUNCTION public.fn_attribute_tournament_rake(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_audit_actor_role(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_actor_role(p_club_id uuid, p_actor uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM public.clubs c
                 WHERE c.id = p_club_id AND c.owner_id = p_actor) THEN 'owner'
    ELSE COALESCE(
      (SELECT CASE cm.role
                WHEN 'owner'       THEN 'owner'
                WHEN 'co_owner'    THEN 'co_owner'
                WHEN 'admin'       THEN 'admin'
                WHEN 'super_agent' THEN 'super_agent'
                WHEN 'agent'       THEN 'agent'
                WHEN 'sub_agent'   THEN 'sub_agent'
                WHEN 'player'      THEN 'player'
                ELSE 'system'
              END
         FROM public.club_members cm
        WHERE cm.club_id = p_club_id AND cm.user_id = p_actor
        LIMIT 1),
      'system')
  END;
$$;


ALTER FUNCTION public.fn_audit_actor_role(p_club_id uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: fn_audit_analysis_watchdog(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_analysis_watchdog(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb := '[]'::jsonb; a record; claimed boolean;
begin
  select day, agent_analyzed_at into a from horse_daily_audit where day = p_day;
  if not found then return v; end if;
  select exists(select 1 from horse_job_runs where job = 'claude_daily_analysis' and run_date = p_day)
    into claimed;

  if now() < (p_day + 2)::timestamptz then return v; end if;

  if a.agent_analyzed_at is null then
    v := v || jsonb_build_object(
      'severity', 'critical', 'category', 'schema',
      'code', case when claimed then 'analysis_claimed_but_never_written' else 'analysis_never_ran' end,
      'title', case when claimed
                 then 'The daily analysis CLAIMED ' || p_day || ' and never wrote a verdict'
                 else 'No daily analysis ran for ' || p_day end,
      'evidence', jsonb_build_object('day', p_day, 'claimed', claimed, 'agent_analyzed_at', null),
      'recommendation', case when claimed
        then 'A runner took the claim and died mid-run. Check that account''s Claude app was open and the run completed; the claim row is what lets a backup runner take over after 14:00 UTC.'
        else 'No Claude account executed the schedule for this day - the app was closed on every machine carrying it, or the task is disabled. The machine findings above still stand on their own.' end
    );
  end if;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_analysis_watchdog(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_behaviour_has_a_stage(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_behaviour_has_a_stage(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  r record;
begin
  for r in
    with live as (
      select
        count(*)                                                      as tables_live,
        count(*) filter (where coalesce(straddle_enabled, false))     as straddle,
        count(*) filter (where coalesce(nit_game, false))             as nit,
        count(*) filter (where game_variant = 'short_deck')           as short_deck,
        count(*) filter (where game_variant like 'plo%')              as omaha,
        count(*) filter (where coalesce(run_it_twice_enabled, false)) as rit
      from tables where status in ('active', 'waiting')
    ),
    checks(behaviour, stage_name, stage_count) as (
      select 'The voluntary straddle (V48)', 'live table with straddle_enabled', (select straddle from live)
      union all
      select 'The VPIP floor read (Dan 2026-09-04)', 'live table with nit_game', (select nit from live)
      union all
      select 'The short-deck hand classes (V46)', 'live short_deck table', (select short_deck from live)
      union all
      select 'The Omaha hand classes (V46)', 'live PLO table', (select omaha from live)
      union all
      select 'Declining run it twice', 'live table with run_it_twice_enabled', (select rit from live)
    )
    select c.behaviour, c.stage_name, c.stage_count, (select tables_live from live) as tables_live
      from checks c
     where c.stage_count = 0
  loop
    v := v || jsonb_build_object('severity','warn','category','schema','code','behaviour_has_no_stage',
      'title', r.behaviour || ' cannot happen: not one of ' || r.tables_live || ' live tables is a ' || r.stage_name,
      'evidence', jsonb_build_object('behaviour', r.behaviour, 'stage', r.stage_name,
                                     'stage_count', 0, 'tables_live', r.tables_live),
      'recommendation','The horse code is not the problem and must not be re-read for this. The FLEET is not opening a table this behaviour can happen at, so its receipt will read zero every night and every night it will look like a dead layer. Fix the table factory or the lobby mix and it starts firing on its own. Whether a behaviour that HAS a stage actually fires is fn_audit_data_receipts'' question, not this one.');
  end loop;

  return v;
end $$;


ALTER FUNCTION public.fn_audit_behaviour_has_a_stage(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_breather_returns(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_breather_returns(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  v_out bigint; v_in bigint; v_gap bigint; v_share numeric;
begin
  select coalesce(sum(fires) filter (where feature = 'v48_sit_out_after_loss'), 0),
         coalesce(sum(fires) filter (where feature = 'v48_sit_back_in'), 0)
    into v_out, v_in
    from horse_brain_telemetry where day = p_day;

  if v_out = 0 then
    -- Not a finding on its own: most horses are grinders by persona, and the
    -- fleet default is 0. fn_audit_data_receipts already reports a receipt
    -- that never fires against its declared expectation.
    return v;
  end if;

  v_gap := v_out - v_in;
  v_share := round(v_gap::numeric / v_out, 3);

  if v_share > 0.10 then
    v := v || jsonb_build_object(
      'severity', case when v_share > 0.25 then 'critical' else 'warn' end,
      'category', 'logic', 'code', 'breather_never_returned',
      'title', v_gap || ' of ' || v_out || ' horse breathers did not book the seat back in',
      'evidence', jsonb_build_object('day', p_day, 'sat_out', v_out, 'came_back', v_in,
                                     'gap', v_gap, 'share', v_share),
      'recommendation', 'The return is a 75-second setTimeout in ServerTableEngineSettlement.horsesTakeABreather, and a timeout does not survive a container replacement. A horse whose breather started just before a deploy holds its seat sitting out forever. Check the day''s engine deploys against the gap; if they line up, the return needs to be driven by the table loop rather than by a timer. A seat held by a horse that will never act is worse than a seat it never took.');
  else
    v := v || jsonb_build_object('severity','info','category','logic','code','breather_returns',
      'title', v_in || ' of ' || v_out || ' horse breathers ended and the seat came back',
      'evidence', jsonb_build_object('day', p_day, 'sat_out', v_out, 'came_back', v_in, 'gap', v_gap),
      'recommendation','A horse that loses a buy-in in one hand takes an orbit off, like a person. The pair must track; a gap is a stranded seat.');
  end if;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_breather_returns(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_club_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_club_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RETURN OLD;
  END IF;
  BEGIN
    INSERT INTO public.audit_trail
      (actor_id, actor_role, action, target_type, target_id, club_id, before_state)
    VALUES
      (v_actor,
       CASE WHEN v_actor = OLD.owner_id THEN 'owner' ELSE 'system' END,
       'delete_club', 'club', OLD.id,
       NULL,
       jsonb_build_object('name', OLD.name, 'member_count', OLD.member_count));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'audit_trail insert failed for club delete %: %', OLD.id, SQLERRM;
  END;
  RETURN OLD;
END;
$$;


ALTER FUNCTION public.fn_audit_club_delete() OWNER TO postgres;

--
-- Name: fn_audit_club_entry_mutation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_club_entry_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_action text; v_club uuid; v_target uuid; v_actor uuid; v_details jsonb;
BEGIN
  IF TG_TABLE_NAME='clubs' THEN
    v_action:='club_created'; v_club:=NEW.id; v_target:=NEW.id;
    v_actor:=COALESCE(auth.uid(),NEW.owner_id);
    v_details:=jsonb_build_object('club_code',NEW.club_id,'requires_approval',NEW.requires_approval);
  ELSIF TG_TABLE_NAME='club_members' THEN
    v_club:=NEW.club_id; v_target:=NEW.user_id;
    v_actor:=COALESCE(auth.uid(),NEW.user_id);
    v_action:=CASE WHEN TG_OP='INSERT' THEN 'club_join_'||NEW.status ELSE 'club_join_status_changed' END;
    v_details:=jsonb_build_object('status',NEW.status,'previous_status',CASE WHEN TG_OP='UPDATE' THEN OLD.status ELSE NULL END);
  ELSE
    v_action:='player_search_privacy_changed'; v_target:=NEW.user_id;
    v_actor:=COALESCE(auth.uid(),NEW.user_id);
    v_details:=jsonb_build_object('discoverable',NEW.discoverable,'show_presence',NEW.show_presence,'show_current_table',NEW.show_current_table);
  END IF;
  INSERT INTO public.audit_trail(
    club_id,actor_id,actor_role,action,target_type,target_id,after_state
  ) VALUES(
    v_club,v_actor,'system',v_action,TG_TABLE_NAME,v_target,jsonb_strip_nulls(v_details)
  );
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_audit_club_entry_mutation() OWNER TO postgres;

--
-- Name: fn_audit_club_member_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_club_member_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor  uuid := auth.uid();
  v_action text;
  v_before jsonb;
  v_after  jsonb;
  v_club   uuid;
  v_target uuid;
BEGIN
  IF v_actor IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP = 'DELETE' THEN
    v_club   := OLD.club_id;
    v_target := OLD.user_id;
    v_action := CASE WHEN v_actor = OLD.user_id THEN 'member_left'
                     ELSE 'kick_member' END;
    v_before := jsonb_build_object('role', OLD.role, 'status', OLD.status);
    v_after  := NULL;
  ELSE
    v_club   := NEW.club_id;
    v_target := NEW.user_id;
    IF NEW.role IS DISTINCT FROM OLD.role THEN
      v_action := 'role_change';
      v_before := jsonb_build_object('role', OLD.role);
      v_after  := jsonb_build_object('role', NEW.role);
    ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
      v_action := CASE
        WHEN NEW.status = 'banned' THEN 'banned'
        WHEN OLD.status = 'banned' THEN 'unban_member'
        ELSE 'member_status_change' END;
      v_before := jsonb_build_object('status', OLD.status);
      v_after  := jsonb_build_object('status', NEW.status);
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.audit_trail
      (actor_id, actor_role, action, target_type, target_id, club_id,
       before_state, after_state)
    VALUES
      (v_actor, public.fn_audit_actor_role(v_club, v_actor),
       v_action, 'member', v_target, v_club, v_before, v_after);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'audit_trail insert failed for club % member %: %',
      v_club, v_target, SQLERRM;
  END;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.fn_audit_club_member_change() OWNER TO postgres;

--
-- Name: fn_audit_club_settings_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_club_settings_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor   uuid := auth.uid();
  v_before  jsonb := '{}'::jsonb;
  v_after   jsonb := '{}'::jsonb;
  v_old     jsonb;
  v_new     jsonb;
  v_key     text;
  -- `settings`, `tagline` and `lobby_message` are new here. The rules a member
  -- is held to live inside `settings`, and a rewrite used to leave no trace at
  -- all: no row, no actor, no before.
  v_watched text[] := ARRAY[
    'name','description','is_public','requires_approval',
    'default_rake_percent','rake_cap',
    'allow_straddle','allow_run_it_twice','allow_rabbit_hunt',
    'min_buyin_bb','max_buyin_bb','logo_url',
    'bbj_rake_enabled','spins_enabled','spins_preseed_amount','spins_wallet_funding',
    'settings','tagline','lobby_message'];
BEGIN
  IF v_actor IS NULL THEN
    RETURN NEW;
  END IF;

  v_old := to_jsonb(OLD);
  v_new := to_jsonb(NEW);
  FOREACH v_key IN ARRAY v_watched LOOP
    IF (v_old -> v_key) IS DISTINCT FROM (v_new -> v_key) THEN
      v_before := v_before || jsonb_build_object(v_key, v_old -> v_key);
      v_after  := v_after  || jsonb_build_object(v_key, v_new -> v_key);
    END IF;
  END LOOP;

  IF v_after = '{}'::jsonb THEN
    RETURN NEW;
  END IF;

  -- The same target and the same swallow the original used. An audit row must
  -- never be the reason a club cannot be saved, and this migration is here to
  -- widen what is watched, not to change where it is written.
  BEGIN
    INSERT INTO public.audit_trail
      (actor_id, actor_role, action, target_type, target_id, club_id,
       before_state, after_state)
    VALUES
      (v_actor, public.fn_audit_actor_role(NEW.id, v_actor), 'update_club_settings',
       'club', NEW.id, NEW.id, v_before, v_after);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_audit_club_settings_change() OWNER TO postgres;

--
-- Name: fn_audit_data_receipts(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_data_receipts(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_findings jsonb := '[]'::jsonb;
  r record;
  v_fires bigint;
  v_denom bigint;
  v_ratio numeric;
  v_ledger_rows bigint;
  v_ledger_age interval;
  v_fresh boolean;
  v_table_exists boolean;
  v_prior_days bigint;
  v_first_later_day date;
begin
  select count(*), now() - max(updated_at) into v_ledger_rows, v_ledger_age
    from horse_data_ledger;

  -- The ledger itself is a datum. No rows = the engine never synced it;
  -- an old sync = the running brain is not the one the ledger describes.
  if v_ledger_rows = 0 then
    v_findings := v_findings || jsonb_build_object(
      'severity', 'critical', 'category', 'schema', 'code', 'data_ledger_missing',
      'title', 'horse_data_ledger is empty - the engine has not synced its contract',
      'evidence', jsonb_build_object('rows', 0),
      'recommendation', 'HorseDataLedgerSync runs at engine boot. Either the engine has not restarted since the ledger shipped or the sync is failing (horse_error_log / container logs, context HorseDataLedgerSync).');
    return v_findings;
  end if;

  -- ── receipts: did each layer fire its expected share? ────────────────
  for r in
    select l.key, split_part(l.key, ':', 2) as feature, l.consumer, l.ratio_of, l.min_ratio, l.note, l.since
      from horse_data_ledger l
     where l.kind = 'receipt'
     order by l.key
  loop
    v_fires := fn_ledger_fires(p_day, r.feature);
    if r.ratio_of is null then
      -- table-mix dependent: only a zero against a big day is worth a line
      continue;
    end if;
    v_denom := fn_ledger_fires(p_day, r.ratio_of);
    if v_denom < 1000 then
      continue; -- the denominator itself is too small to judge anything
    end if;
    v_ratio := v_fires::numeric / v_denom;
    -- ── A LAYER'S FIRST DAY IS A PARTIAL DAY (2026-09-05) ──
    -- V40 merged at 17:51 UTC on 2026-09-04 and this check reported
    -- v40_made_* at 4.982% of decide_omaha against a 5% floor: six hours of
    -- numerator over twenty-four hours of denominator. A receipt that has
    -- fired today and has NO telemetry row on any earlier day is on its first
    -- (partial) day and cannot be judged by a whole-day ratio; it is reported
    -- as info and judged tomorrow. Zero fires with no history is NOT excused:
    -- that is a layer that has never executed, and stays critical.
    if r.min_ratio is not null and v_ratio < r.min_ratio and v_fires > 0 then
      select count(distinct t.day) into v_prior_days
        from horse_brain_telemetry t
       where t.day < p_day and t.fires > 0
         and case when right(r.feature, 1) = '*'
                  then t.feature like replace(left(r.feature, length(r.feature) - 1), '_', '\_') || '%'
                  else t.feature = r.feature end;
      if v_prior_days = 0 then
        v_findings := v_findings || jsonb_build_object(
          'severity', 'info', 'category', 'logic', 'code', 'receipt_first_day',
          'title', r.feature || ' fired ' || v_fires || ' times on its first (partial) day - ratio not judged',
          'evidence', jsonb_build_object(
            'feature', r.feature, 'fires', v_fires, 'ratio_of', r.ratio_of, 'denominator', v_denom,
            'ratio', round(v_ratio, 6), 'min_ratio', r.min_ratio, 'consumer', r.consumer, 'since', r.since),
          'recommendation', 'The layer deployed during this day, so its fires cover part of the day and the denominator covers all of it. The ratio is judged from its first full day.');
        continue;
      end if;
    end if;
    -- ── A LAYER DEPLOYED AFTER THE AUDITED DAY IS NOT DARK (2026-09-06) ──
    -- Zero fires on p_day, no fires before it, but fires on a LATER day: the
    -- ledger row belongs to a build that cut over after this day closed (the
    -- audit reads the ledger the current engine synced, not the one that ran
    -- on p_day). v44_second_look, 2026-09-05: 0 fires, deployed 23:55:30 UTC
    -- into the freeze, 39,132 fires the next day. Info, and judged from its
    -- first full day. No telemetry on ANY day stays critical below.
    if r.min_ratio is not null and v_fires = 0 then
      select min(t.day) into v_first_later_day
        from horse_brain_telemetry t
       where t.day > p_day and t.fires > 0
         and case when right(r.feature, 1) = '*'
                  then t.feature like replace(left(r.feature, length(r.feature) - 1), '_', '\_') || '%'
                  else t.feature = r.feature end;
      if v_first_later_day is not null and not exists (
        select 1 from horse_brain_telemetry t
         where t.day <= p_day and t.fires > 0
           and case when right(r.feature, 1) = '*'
                    then t.feature like replace(left(r.feature, length(r.feature) - 1), '_', '\_') || '%'
                    else t.feature = r.feature end
      ) then
        v_findings := v_findings || jsonb_build_object(
          'severity', 'info', 'category', 'logic', 'code', 'receipt_deployed_after_day',
          'title', r.feature || ' fired 0 times on ' || p_day || ' - its first fire is ' || v_first_later_day || ', so it deployed after this day',
          'evidence', jsonb_build_object(
            'feature', r.feature, 'fires', 0, 'ratio_of', r.ratio_of, 'denominator', v_denom,
            'min_ratio', r.min_ratio, 'consumer', r.consumer, 'since', r.since,
            'first_fire_day', v_first_later_day),
          'recommendation', 'The ledger the audit read was synced by an engine that booted after this day ended. Nothing was dark on ' || p_day || '; the layer did not exist yet. It is judged from its first full day (' || v_first_later_day || ' is its partial first day).');
        continue;
      end if;
    end if;
    if r.min_ratio is not null and v_ratio < r.min_ratio then
      v_findings := v_findings || jsonb_build_object(
        'severity', case when v_fires = 0 then 'critical' else 'warn' end,
        'category', 'logic',
        'code', 'data_unread',
        'title', r.feature || ' fired ' || v_fires || ' times against ' || v_denom || ' ' || r.ratio_of ||
                 ' (' || round(v_ratio * 100, 3) || '%, ledger expects >= ' || round(r.min_ratio * 100, 3) || '%)',
        'evidence', jsonb_build_object(
          'feature', r.feature, 'fires', v_fires, 'ratio_of', r.ratio_of, 'denominator', v_denom,
          'ratio', round(v_ratio, 6), 'min_ratio', r.min_ratio, 'consumer', r.consumer, 'since', r.since),
        'recommendation', case when v_fires = 0
          then 'A registered consumer produced no receipt all day: the gate in front of ' || r.consumer || ' is closed (flag default, upstream condition, or the layer was removed without retiring its ledger row). Trace the gate in the source before touching the ratio.'
          else 'The consumer runs but far below the share the ledger expects. Either the fleet mix changed (then lower min_ratio in HorseDataLedger.ts with the evidence) or an upstream condition narrowed. ' || r.note end);
    end if;
  end loop;

  -- ── tables: is each nightly/boot source fresh? ───────────────────────
  for r in
    select l.key, split_part(l.key, ':', 2) as tbl, l.cadence, l.consumer, l.day_column, l.freshness_days
      from horse_data_ledger l
     where l.kind = 'table' and l.day_column is not null and l.freshness_days is not null
     order by l.key
  loop
    select exists (
      select 1 from information_schema.tables
       where table_schema = 'public' and table_name = r.tbl
    ) into v_table_exists;
    if not v_table_exists then
      v_findings := v_findings || jsonb_build_object(
        'severity', 'critical', 'category', 'schema', 'code', 'data_stale',
        'title', 'Ledger table ' || r.tbl || ' does not exist',
        'evidence', jsonb_build_object('table', r.tbl),
        'recommendation', 'The ledger names a table the schema does not have. Either the migration was never applied or the ledger row is wrong.');
      continue;
    end if;
    -- freshness: any row whose day column is within freshness_days of p_day
    -- (timestamps and dates both cast to date).
    execute format(
      'select exists (select 1 from public.%I where (%I)::date >= %L::date - %s)',
      r.tbl, r.day_column, p_day, r.freshness_days
    ) into v_fresh;
    if not v_fresh then
      v_findings := v_findings || jsonb_build_object(
        'severity', 'critical', 'category', 'schema', 'code', 'data_stale',
        'title', r.tbl || ' has no row within ' || r.freshness_days || ' day(s) of ' || p_day,
        'evidence', jsonb_build_object('table', r.tbl, 'day_column', r.day_column,
                                       'freshness_days', r.freshness_days, 'consumer', r.consumer, 'cadence', r.cadence),
        'recommendation', 'A source the brain or its compilers depend on stopped being written. ' || r.consumer || ' is reading stale memory. Find the writer (the ledger names the cadence) and its error log.');
    end if;
  end loop;

  return v_findings;
end
$$;


ALTER FUNCTION public.fn_audit_data_receipts(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_empty_freerolls(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_empty_freerolls(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb := '[]'::jsonb; r record;
begin
  for r in
    select t.name, coalesce(t.current_players,0) cur, coalesce(t.max_players,0) maxp
    from tournaments t
    where coalesce(t.buy_in_amount,0) = 0
      and t.started_at >= p_day and t.started_at < p_day + 1
      and coalesce(t.max_players,0) > 0
      and coalesce(t.current_players,0) < greatest(6, coalesce(t.max_players,0) * 0.15)
    order by coalesce(t.current_players,0) asc limit 8
  loop
    v := v || jsonb_build_object(
      'severity','warn','category','logic','code','freeroll_started_empty',
      'title', r.name || ' started with ' || r.cur || ' of ' || r.maxp || ' players',
      'evidence', jsonb_build_object('entries', r.cur, 'capacity', r.maxp),
      'recommendation','Every playing horse should register for a freeroll. Check HorseOverlayGuard freeroll lines for that window - it may have been outside the fill band, or every candidate was outside its activity window or at the four-table cap.'
    );
  end loop;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_empty_freerolls(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_fleet_drop_identity(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_fleet_drop_identity(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  v_net numeric; v_rake numeric; v_bbj numeric; v_hands bigint;
  v_residual numeric; v_resid_bb100 numeric; v_raw_bb100 numeric;
begin
  select coalesce(sum(net_bb),0), coalesce(sum(rake_bb),0), coalesce(sum(bbj_bb),0), coalesce(sum(hands),0)
    into v_net, v_rake, v_bbj, v_hands
    from horse_daily_nets where day = p_day and format in ('cash','hu_cash');
  if v_hands < 10000 then
    -- Too little play for the identity to mean anything; say so rather than
    -- report a number nobody should act on.
    return v;
  end if;

  v_residual := v_net + v_rake + v_bbj;
  v_resid_bb100 := round(v_residual / v_hands * 100, 2);
  v_raw_bb100 := round(v_net / v_hands * 100, 2);

  -- THE FREE DIAGNOSIS. rake_bb landed on 2026-09-05 and bbj_bb on
  -- 2026-09-06; a day where one is flowing and the other is flat zero names
  -- the missing half without reading a second table.
  if v_rake <> 0 and v_bbj = 0 then
    v := v || jsonb_build_object('severity','warn','category','schema','code','drop_half_missing',
      'title','The rake is attributed and the jackpot drop is not - ' || v_resid_bb100 || ' bb/100 unexplained',
      'evidence', jsonb_build_object('day', p_day, 'hands', v_hands, 'rake_bb', round(v_rake,0),
                                     'bbj_bb', round(v_bbj,0), 'residual_bb100', v_resid_bb100),
      'recommendation','horse_daily_nets.bbj_bb is written by HorseHandReview.accumulateHorseNets from ServerTableEngineSettlement''s bbjAmount, allocated by allocateWeightedShareCents exactly as rake_bb is. A zero here means the engine is serving a build from before that shipped, or bbjAmount is not reaching logHandHistory. Until it flows, the regression rule is judging the jackpot drop as a leak.');
  end if;

  if abs(v_resid_bb100) > 5 then
    v := v || jsonb_build_object('severity','warn','category','logic','code','fleet_residual_unexplained',
      'title','The fleet is ' || v_resid_bb100 || ' bb/100 after the whole drop, and it plays itself',
      'evidence', jsonb_build_object('day', p_day, 'hands', v_hands, 'net_bb', round(v_net,0),
                                     'rake_bb', round(v_rake,0), 'bbj_bb', round(v_bbj,0),
                                     'raw_bb100', v_raw_bb100, 'residual_bb100', v_resid_bb100),
      'recommendation','A closed system nets to zero minus the drop, so a residual this size is a drop nobody attributed, chips leaving to human players (hand_history.has_human - there were 29 human hands in 143,795 on 2026-09-05), or a settlement path that does not balance. Find it before letting the regression rule judge anyone: it reads the whole residual as a leak.');
  else
    v := v || jsonb_build_object('severity','info','category','logic','code','fleet_drop_identity_holds',
      'title','The fleet nets to ' || v_resid_bb100 || ' bb/100 once the rake and the jackpot are counted',
      'evidence', jsonb_build_object('day', p_day, 'hands', v_hands, 'net_bb', round(v_net,0),
                                     'rake_bb', round(v_rake,0), 'bbj_bb', round(v_bbj,0),
                                     'raw_bb100', v_raw_bb100, 'residual_bb100', v_resid_bb100),
      'recommendation','This is the fleet''s true result, and the raw ' || v_raw_bb100 || ' bb/100 on the same day is the house take rather than a leak. Nothing may tune on the raw number.');
  end if;

  return v;
end $$;


ALTER FUNCTION public.fn_audit_fleet_drop_identity(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_fleet_health(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_fleet_health(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  v_fleet int;
  v_played int;
  v_idle int;
  v_over int;
  v_over_max int;
  v_ghosts int;
  v_ghost_max_min numeric;
  v_decided_unfinished int;
  v_decided_max_min numeric;
  v_open_seats int;
  v_seat_total int;
  v_seat_filled int;
  v_avail_horses int;
begin
  select count(*) into v_fleet from profiles
    where is_horse = true
      and coalesce(horse_status, 'available') <> 'disabled';
  select count(distinct horse_user_id) into v_played
    from horse_daily_nets where day = p_day;
  v_idle := greatest(0, v_fleet - v_played);

  if v_fleet > 0 and v_idle::numeric / v_fleet > 0.20 then
    v := v || jsonb_build_object(
      'severity', case when v_idle::numeric / v_fleet > 0.40 then 'critical' else 'warn' end,
      'category','logic','code','fleet_idle_share',
      'title', v_idle || ' of ' || v_fleet || ' horses dealt no hands',
      'evidence', jsonb_build_object('fleet', v_fleet, 'played', v_played, 'idle', v_idle),
      'recommendation','Activity windows legitimately idle ~40% at any instant, but across a WHOLE day nearly every horse should deal. Check HorseFleetManager seeding cycles and the overlay guard candidate pools.');
  end if;

  select count(*), coalesce(max(l), 0) into v_over, v_over_max
    from (select fn_concurrent_game_load(id) l from profiles where is_horse = true) q
   where l > 4;
  if v_over > 5 then
    v := v || jsonb_build_object(
      'severity', case when v_over > 25 then 'critical' else 'warn' end,
      'category','logic','code','fleet_over_cap',
      'title', v_over || ' horses are above the four-game cap (max ' || v_over_max || ')',
      'evidence', jsonb_build_object('over_cap', v_over, 'max_load', v_over_max),
      'recommendation','trg_enforce_four_table_limit and trg_enforce_booking_game_cap hold this at write time with an advisory lock, so a few are expected from tournament STATUS transitions that retroactively count a booking. Many means a write path is bypassing the triggers - find it.');
  end if;

  select count(*), coalesce(max(extract(epoch from (now() - ts.joined_at))/60), 0)
    into v_ghosts, v_ghost_max_min
    from table_seats ts
    join tables t on t.id = ts.table_id
    join tournaments tr on tr.id = t.tournament_id
    join tournament_players tp
      on tp.tournament_id = t.tournament_id and tp.user_id = ts.user_id
   where ts.left_at is null
     and tr.status = 'RUNNING'
     and tp.status = 'playing'
     and coalesce(ts.stack, 0) <= 0
     and ts.joined_at < now() - interval '10 minutes';

  select count(*), coalesce(max(extract(epoch from (now() - tr.started_at))/60), 0)
    into v_decided_unfinished, v_decided_max_min
    from tournaments tr
   where tr.status = 'RUNNING'
     and tr.started_at < now() - interval '5 minutes'
     and (select count(*) from tournament_players tp
           where tp.tournament_id = tr.id
             and tp.status = 'playing'
             and coalesce(tp.chips, 0) > 0) <= 1;

  if v_ghosts > 0 or v_decided_unfinished > 0 then
    v := v || jsonb_build_object(
      'severity', case when v_decided_unfinished > 5 or v_ghosts > 10 then 'critical' else 'warn' end,
      'category','logic','code','bust_sweep_lag',
      'title', v_ghosts || ' busted entrants still hold seats, and ' ||
               v_decided_unfinished || ' running tournament(s) are already decided but unpaid',
      'evidence', jsonb_build_object(
        'ghost_seats', v_ghosts,
        'oldest_seat_tenure_minutes', round(v_ghost_max_min),
        'decided_unfinished', v_decided_unfinished,
        'oldest_decided_minutes', round(v_decided_max_min),
        'measured_at', now(),
        'metric_note', 'oldest_seat_tenure_minutes is how long the player has been SEATED, not how long the bust has gone unswept - there is no bust timestamp in the schema. Escalation uses decided_unfinished, which is unambiguous.'),
      'recommendation','The 5s elimination sweep is lagging. Measured 2026-09-02: the engine carries 1,300+ table engines in ONE Node process at 60-98% CPU, with 2,621 elimination_sweep_overrunning events in 5.5 hours of logs, so the sweep cannot be SCHEDULED - it is not a predicate mismatch and not the bustingArmedAt hold. Relieving it is a capacity change (one process-wide scheduler with bounded concurrency instead of a 5s interval per tournament, and then sharding the engine across cores). Do not change the bust predicate, the zero-chip guard or the lock thresholds; each of those is guarding a documented money incident.');
  end if;

  select count(*) into v_avail_horses from profiles
    where is_horse = true
      and coalesce(horse_status, 'available') <> 'disabled';
  select coalesce(sum(t.max_players), 0), coalesce(sum(coalesce(s.n, 0)), 0),
         coalesce(sum(t.max_players) - sum(coalesce(s.n, 0)), 0)
    into v_seat_total, v_seat_filled, v_open_seats
    from tables t
    left join (select table_id, count(*) n from table_seats where left_at is null group by 1) s
      on s.table_id = t.id
   where t.tournament_id is null and t.status in ('running','waiting');
  if v_seat_total > 0 and v_open_seats::numeric / v_seat_total > 0.45 then
    v := v || jsonb_build_object(
      'severity','warn','category','logic','code','fleet_seat_starvation',
      'title', v_open_seats || ' of ' || v_seat_total || ' cash seats are empty (' ||
        round(100.0 * v_seat_filled / nullif(v_seat_total, 0), 1) || '% full)',
      'evidence', jsonb_build_object('open_seats', v_open_seats, 'seats', v_seat_total,
        'filled', v_seat_filled,
        'pct_full', round(100.0 * v_seat_filled / nullif(v_seat_total, 0), 1),
        'available_horses', v_avail_horses),
      'recommendation','Some open seats are deliberate (V14 table occupancy keeps the lobby lopsided and human-looking). This many means the seeder is not keeping up - check HorseFleetManager seeding cycles and the horse candidate pool.');
  end if;

  return v;
end
$$;


ALTER FUNCTION public.fn_audit_fleet_health(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_frequency_leaks(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_frequency_leaks(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  r record;
  v_studied int;
  v_play_days int;
  v_hands bigint;
  v_floored bigint;
  v_share numeric;
begin
  select count(distinct day) into v_play_days
    from horse_daily_play where day > p_day - 7 and day <= p_day;
  if v_play_days = 0 then
    return v;
  end if;

  -- How much of the window the bands are structurally blind to.
  select coalesce(sum(hands), 0),
         coalesce(sum(hands) filter (where floored), 0)
    into v_hands, v_floored
    from horse_daily_play
   where day > p_day - 7 and day <= p_day and format in ('cash', 'hu_cash');
  v_share := case when v_hands > 0 then round(v_floored::numeric / v_hands, 3) else 0 end;
  if v_floored > 0 then
    v := v || jsonb_build_object(
      'severity', case when v_share >= 0.40 then 'warn' else 'info' end,
      'category', 'logic', 'code', 'frequency_floored_share',
      'title', (v_share * 100)::int || '% of cash hands were played at a VPIP-floored table',
      'evidence', jsonb_build_object('hands', v_hands, 'floored_hands', v_floored, 'share', v_share),
      'recommendation', case when v_share >= 0.40
        then 'The winning-player bands now judge a minority of the fleet''s cash play, and horses may stop reaching the 1,000-hand gate. A floored table REQUIRES loose play (10.5, HorseLogic.vpipFloorMul), so its frequencies cannot be scored against the bands - the answer is fewer floored tables or a floored-table band of its own, not scoring them together.'
        else 'Floored tables require loose play and are excluded from the bands and from the self-tuner by design (see the_floor_is_not_a_leak). This line exists so the exclusion stays visible.' end);
  end if;

  select count(*) into v_studied from fn_horse_frequency_leaks(p_day - 7);
  if v_studied = 0 then
    v := v || jsonb_build_object('severity','info','category','logic','code','frequency_sample_thin',
      'title','No horse has 1,000 unfloored cash hands in the frequency window yet',
      'evidence', jsonb_build_object('play_days', v_play_days, 'floored_share', v_share),
      'recommendation','horse_daily_play is young, or too much of the play is floored. The frequency detectors report from the day a horse crosses 1,000 hands at tables where it was free to fold.');
    return v;
  end if;

  for r in
    select leak, count(*) as horses
      from fn_horse_frequency_leaks(p_day - 7), lateral unnest(leaks) leak
     group by leak
     order by 2 desc
  loop
    if r.horses::numeric / v_studied >= 0.33 then
      v := v || jsonb_build_object('severity','critical','category','gto','code','frequency_leak_fleetwide',
        'title', r.leak || ': ' || r.horses || ' of ' || v_studied || ' studied horses',
        'evidence', jsonb_build_object('leak', r.leak, 'horses', r.horses, 'studied', v_studied,
                                       'share', round(r.horses::numeric / v_studied, 3)),
        'recommendation','A third of the fleet shares this frequency, so it is a threshold in the brain rather than a personality. Find the bar: VPIP and PFR are HorsePreflop open/defend bars, fold-to-3-bet is the facing-raise bar, WWSF and AF are the postflop bluff and value gates. Do not tune dials against it - the dials are already trying and losing.');
    else
      v := v || jsonb_build_object('severity','info','category','gto','code','frequency_leak',
        'title', r.leak || ': ' || r.horses || ' of ' || v_studied || ' studied horses',
        'evidence', jsonb_build_object('leak', r.leak, 'horses', r.horses, 'studied', v_studied,
                                       'share', round(r.horses::numeric / v_studied, 3)),
        'recommendation','Individual horses outside a winning band. The self-tuner moves these dials nightly on the same bands; this line is how to see whether it is working.');
    end if;
  end loop;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_frequency_leaks(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_layer_drift(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_layer_drift(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_findings jsonb := '[]'::jsonb;
  v_decides bigint;
  v_already text[];
  r record;
  /*
   * ── FALLBACK COUNTERS: SILENCE IS THE GOAL (2026-09-05) ──
   * Some counters name the DEGRADED path, not a layer: icm_legacy is the flat
   * heuristic used only when TournamentBrainContext arrives without stacks or
   * payouts (icm_real takes over the moment it has them), icm_warming is a
   * context that has not arrived yet, gto_depth_fallback and gto_miss_* are
   * the solver store having no cell for the spot. For these, zero fires on a
   * big day means the primary path covered everything - the six-day
   * icm_legacy migration to icm_real reached exactly zero on 2026-09-04 and
   * this function reported it as a layer that "was executing and is not any
   * more". Their silence is reported as info, with the reason, so the panel
   * can still see the step without a warning that says the opposite of what
   * happened. A fallback that starts firing AGAIN is caught by the ratio
   * checks in fn_audit_data_receipts, not here.
   */
  v_fallback_exact constant text[] := array['icm_legacy', 'icm_warming', 'gto_depth_fallback'];
  v_fallback_prefix constant text[] := array['gto_miss_'];
  v_is_fallback boolean;
begin
  select coalesce(sum(fires), 0) into v_decides
    from horse_brain_telemetry where day = p_day and feature = 'decide';

  if v_decides < 1000 then
    return v_findings;
  end if;

  select coalesce(array_agg(f->'evidence'->>'feature'), '{}')
    into v_already
    from jsonb_array_elements(fn_audit_layer_silence(p_day)) f
   where f->>'code' = 'layer_silent';

  -- 1. A layer that was firing and stopped.
  for r in
    with hist as (
      select feature,
             count(*) filter (where day < p_day and fires > 0) as prior_days,
             coalesce(max(fires) filter (where day = p_day), 0) as today,
             coalesce(sum(fires) filter (where day < p_day), 0) as prior_fires,
             max(day) filter (where day < p_day and fires > 0) as last_fired
        from horse_brain_telemetry
       where day between p_day - 7 and p_day and feature <> 'decide'
       group by feature
    )
    select * from hist
     where prior_days >= 2 and today = 0 and not (feature = any(v_already))
     order by prior_fires desc
  loop
    v_is_fallback := r.feature = any(v_fallback_exact)
      or exists (select 1 from unnest(v_fallback_prefix) p where left(r.feature, length(p)) = p);
    if v_is_fallback then
      v_findings := v_findings || jsonb_build_object(
        'severity', 'info',
        'category', 'logic',
        'code', 'fallback_went_quiet',
        'title', 'Fallback ' || r.feature || ' fired ' || r.prior_fires ||
                 ' times in the previous week and ZERO on ' || p_day || ' - the primary path covered every spot',
        'evidence', jsonb_build_object(
          'feature', r.feature,
          'prior_days_active', r.prior_days,
          'prior_fires', r.prior_fires,
          'last_fired', r.last_fired,
          'decide_fires', v_decides
        ),
        'recommendation',
          'This counter names a degraded path (the legacy ICM heuristic, a warming ' ||
          'context, a solver-store miss), so zero is the intended direction: the ' ||
          'primary path answered every spot the fallback used to answer. Nothing to ' ||
          'trace. If it starts firing again the receipts audit will say so.'
      );
      continue;
    end if;
    v_findings := v_findings || jsonb_build_object(
      'severity', 'warn',
      'category', 'logic',
      'code', 'layer_went_silent',
      'title', 'Layer ' || r.feature || ' fired ' || r.prior_fires ||
               ' times in the previous week and ZERO on ' || p_day,
      'evidence', jsonb_build_object(
        'feature', r.feature,
        'prior_days_active', r.prior_days,
        'prior_fires', r.prior_fires,
        'last_fired', r.last_fired,
        'decide_fires', v_decides
      ),
      'recommendation',
        'This layer was executing and is not any more. Trace the gate: a flag ' ||
        'default, an upstream condition that can no longer be true, or a newer ' ||
        'layer returning before it. A retired layer is a valid answer - if the ' ||
        'feature name no longer exists in the source it is not a regression, ' ||
        'and this finding should be answered by deleting the counter.'
    );
  end loop;

  -- 2. A layer that collapsed without going silent - REPORTED ON THE DAY OF
  --    THE STEP ONLY (2026-09-04).
  for r in
    with dec as (
      select day, sum(fires) filter (where feature = 'decide') as d
        from horse_brain_telemetry
       where day between p_day - 7 and p_day
       group by day
      having sum(fires) filter (where feature = 'decide') > 1000
    ),
    rate as (
      select t.feature, t.day, (t.fires::numeric * 1000) / dec.d as rate, t.fires
        from horse_brain_telemetry t
        join dec on dec.day = t.day
       where t.feature <> 'decide'
    ),
    cur  as (select feature, rate as cur_rate,  fires as cur_fires  from rate where day = p_day),
    prev as (select feature, rate as prev_rate, fires as prev_fires from rate where day = p_day - 1),
    base as (
      select feature,
             (percentile_cont(0.5) within group (order by rate))::numeric as med_rate,
             count(*) as n_days,
             sum(fires) as prior_fires
        from rate where day < p_day group by feature
    )
    select c.feature, c.cur_rate, c.cur_fires, b.med_rate, b.n_days, b.prior_fires,
           p.prev_rate, p.prev_fires
      from cur c
      join base b using (feature)
      left join prev p using (feature)
     where b.n_days >= 3
       and b.prior_fires >= 5000
       and b.med_rate > 0
       and c.cur_rate < b.med_rate * 0.40
       -- THE STEP MUST BE NEW. If yesterday was already below the line, this
       -- is the same step reported again - the median simply has not rolled
       -- past it yet. Reporting it daily for a week is what buried three real
       -- criticals under three false ones on 2026-09-01.
       and (p.prev_rate is null or p.prev_rate >= b.med_rate * 0.40)
       -- AND IT MUST ACTUALLY HAVE FALLEN. icm_legacy went 441 -> 641 fires
       -- and v16_unblocker 2,428 -> 2,512 on the day they were both reported
       -- as collapsing. A layer whose raw count rose is not collapsing today,
       -- whatever a median that straddles a deploy says.
       and (p.prev_fires is null or c.cur_fires < p.prev_fires)
     order by (1 - c.cur_rate / b.med_rate) desc
  loop
    v_findings := v_findings || jsonb_build_object(
      'severity', 'warn',
      'category', 'logic',
      'code', 'layer_fire_collapse',
      'title', 'Layer ' || r.feature || ' fell to ' ||
               round(100 * (1 - r.cur_rate / r.med_rate)) || '% below its usual rate',
      'evidence', jsonb_build_object(
        'feature', r.feature,
        'rate_per_1k_today', round(r.cur_rate, 2),
        'rate_per_1k_yesterday', round(coalesce(r.prev_rate, 0), 2),
        'rate_per_1k_median', round(r.med_rate, 2),
        'pct_drop', round(100 * (1 - r.cur_rate / r.med_rate)),
        'fires_today', r.cur_fires,
        'fires_yesterday', coalesce(r.prev_fires, 0),
        'prior_fires', r.prior_fires,
        'baseline_days', r.n_days,
        'step_day', p_day
      ),
      'recommendation',
        'Reported ONLY on the day the step happened: yesterday was still near ' ||
        'the median and the raw count fell today, so this is new rather than a ' ||
        'week-old change the median has not caught up with. Measured per 1,000 ' ||
        'decisions, so fleet volume is already divided out. Two innocent ' ||
        'explanations remain and both are worth confirming rather than ' ||
        'assuming: a SUPERSEDED layer legitimately declining (icm_legacy as ' ||
        'icm_real took over), and a newer layer that RETURNS EARLY displacing ' ||
        'the ones below it (V32 did exactly that to v16_reads_tell and ' ||
        'v16_unblocker on 2026-08-31). The third explanation is a broken gate.'
    );
  end loop;

  return v_findings;
end
$$;


ALTER FUNCTION public.fn_audit_layer_drift(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_layer_silence(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_layer_silence(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_findings jsonb := '[]'::jsonb;
  v_decides bigint;
  f jsonb;
  feat record;
begin
  select coalesce(sum(fires), 0) into v_decides
  from horse_brain_telemetry where day = p_day and feature = 'decide';

  if v_decides < 1000 then
    return jsonb_build_array(jsonb_build_object(
      'severity','critical','category','schema','code','telemetry_dark',
      'title','Brain telemetry recorded ' || v_decides || ' decisions for ' || p_day,
      'evidence', jsonb_build_object('decide_fires', v_decides),
      'recommendation','Either BrainTelemetryFlush is not running, the deploy predates telemetry, or the fleet was down. Nothing about layer health can be known for this day.'
    ));
  end if;

  for feat in
    select * from (values
      ('preflop_v7',          'critical','the V7 preflop engine - every preflop decision should route through it'),
      ('v15_nut_status',      'critical','V15 Omaha nut awareness - fires on every made flush/straight in PLO'),
      ('banded_mc_omaha',     'critical','Omaha banded equity (the reservoir sampler feeds this path)'),
      ('banded_mc_nlh',       'critical','NLH banded equity'),
      ('icm_real',            'warn','V16 real ICM - tournament decisions with stacks+payouts in context'),
      ('v16_hu_overlay',      'warn','V16 heads-up overlay - any two-handed postflop pot'),
      ('v15_eq_capped',       'warn','V15 equity cap - dominated hands facing aggression'),
      ('v16_reads_cbet',      'warn','deep-read c-bet scaling - needs 10+ observed c-bet opportunities'),
      ('v16_sizecond_bigbet', 'warn','size-conditioned sampling - a 20bb+ bet on the newest street'),
      ('v16_reads_f3b',       'warn','deep-read fold-to-3-bet scaling of the bluff 3-bet mix'),
      ('v16_reads_tell',      'warn','big-river-bet sizing tell - WAS DEAD until the 2026-08-27 scale fix; zero here means the repair did not take'),
      ('v17_pos_behind',      'warn','V17 positional pressure - 0 or 2+ live players behind in a bluff-band spot'),
      ('v17_river_probe',     'warn','V17 river delayed probe - checked-through turn into a short-handed river'),
      ('v17_catch_block',     'warn','V17 call-side blocker - WAS DEAD until the 2026-08-27 scale fix; zero here means the repair did not take'),
      ('v17_short_deck',      'warn','V17 short-deck overlay - every short-deck postflop decision'),
      ('v18_straddle',        'warn','V18 straddle fix - straddled pots re-read as unopened (straddle tables only)'),
      ('v18_self_image',      'warn','V18 self-image - a horse''s own recent line moving its bluff volume'),
      ('v18_exploit_size',    'warn','V18 exploit-sized river value raises'),
      ('v19_overbet_polarity','warn','overbet polarity respect - unreachable before the scale fix'),
      ('v19_river_bigbet_cap','warn','V15 river big-bet equity cap - unreachable before the scale fix')
    ) as t(feature, severity, why)
  loop
    if not exists (
      select 1 from horse_brain_telemetry
      where day = p_day and feature = feat.feature and fires > 0
    ) then
      v_findings := v_findings || jsonb_build_object(
        'severity', feat.severity,'category','logic','code','layer_silent',
        'title','Deployed layer ' || feat.feature || ' fired ZERO times',
        'evidence', jsonb_build_object('feature', feat.feature,'decide_fires', v_decides,'expectation', feat.why),
        'recommendation','The code is deployed but never executes at live tables. Find the gate that turned it off - flag defaults, wiring, an upstream condition that can no longer be true, or a threshold on the wrong scale.'
      );
    end if;
  end loop;

  return v_findings;
end $$;


