--
-- Name: fn_audit_league_coverage(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_league_coverage(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_findings jsonb := '[]'::jsonb;
  v_recent int;
  v_stale text[];
begin
  select count(distinct matchup) into v_recent
  from horse_league_results where run_date > p_day - 7;

  select coalesce(array_agg(m order by m), '{}')
    into v_stale
  from (
    select distinct matchup m from horse_league_results where run_date > p_day - 45
    except
    select distinct matchup from horse_league_results where run_date > p_day - 7
  ) s;

  if array_length(v_stale, 1) > 0 then
    v_findings := v_findings || jsonb_build_object(
      'severity', 'warn',
      'category', 'gto',
      'code', 'league_card_starved',
      'title', array_length(v_stale, 1) || ' league matchup(s) unmeasured for 7+ days',
      'evidence', jsonb_build_object('stale_matchups', to_jsonb(v_stale), 'measured_last_7d', v_recent),
      'recommendation', 'The nightly budget is not reaching these matchups even with daily rotation. Their layers are unmeasured - reduce PAIRS_PER_MATCHUP, raise MAX_RUN_MS, or trim the card. A layer nobody measures is a layer nobody can defend.'
    );
  end if;

  if exists (
    select 1 from horse_league_results
    where run_date = (select max(run_date) from horse_league_results where run_date <= p_day + 1)
    group by run_date having count(*) < 6
  ) then
    v_findings := v_findings || jsonb_build_object(
      'severity', 'info',
      'category', 'gto',
      'code', 'league_run_partial',
      'title', 'The latest league run completed fewer than 6 matchups',
      'evidence', jsonb_build_object(
        'run_date', (select max(run_date) from horse_league_results where run_date <= p_day + 1),
        'matchups', (select count(*) from horse_league_results
                     where run_date = (select max(run_date) from horse_league_results where run_date <= p_day + 1))
      ),
      'recommendation', 'Expected with a large card and a fixed budget - the rotation covers the rest over following nights. Only a concern if the same matchups keep leading every night.'
    );
  end if;

  return v_findings;
end $$;


ALTER FUNCTION public.fn_audit_league_coverage(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_league_pooled_findings(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_league_pooled_findings(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb := '[]'::jsonb; r record;
begin
  for r in select * from fn_league_pooled(p_day, 7) loop
    if r.verdict = 'SIGNIFICANT' and r.bb100 < 0 then
      v := v || jsonb_build_object(
        'severity', 'critical', 'category', 'gto', 'code', 'league_layer_negative_pooled',
        'title', 'Pooled over ' || r.runs || ' run(s): ' || r.matchup || ' resolves NEGATIVE at ' || r.bb100 || ' bb/100',
        'evidence', jsonb_build_object('matchup', r.matchup, 'bb100', r.bb100, 'stderr', r.stderr,
                                       'runs', r.runs, 'hands', r.hands, 'newest_run', r.newest_run),
        'recommendation', 'This layer is measurably losing money across every night it was measured. Ablate it properly before tuning anything else - and check whether a recent change to it caused the flip.'
      );
    end if;
    if r.verdict = 'SIGNIFICANT' and r.bb100 > 0 and r.matchup = 'v16_ratio_rescale' then
      v := v || jsonb_build_object(
        'severity', 'info', 'category', 'gto', 'code', 'flagged_experiment_earned_its_keep',
        'title', 'v16_ratio_rescale is pooled-SIGNIFICANT positive (' || r.bb100 || ' bb/100 over ' || r.runs || ' runs)',
        'evidence', jsonb_build_object('bb100', r.bb100, 'stderr', r.stderr, 'runs', r.runs),
        'recommendation', 'The default-OFF experiment has earned its default. Ship a PR flipping v16Ratio to default ON, citing these runs.'
      );
    end if;
  end loop;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_league_pooled_findings(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_nightly_job_health(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_nightly_job_health(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_findings jsonb := '[]'::jsonb;
  r record;
  v_rows bigint;
  v_last_league date;
  v_gap int;
  v_matchups bigint;
begin
  for r in
    select j.job, j.claimed_at, j.claimed_by
      from horse_job_runs j
     where j.run_date = p_day
       and j.job in ('league', 'league_pm', 'self_tuner')
     order by j.job
  loop
    if r.job in ('league', 'league_pm') then
      select count(*) into v_rows from horse_league_results where run_date = p_day;
    else
      select count(*) into v_rows from horse_self_tune_log where run_date = p_day;
    end if;

    if v_rows = 0 then
      v_findings := v_findings || jsonb_build_object(
        'severity', 'critical',
        'category', 'schema',
        'code', 'nightly_job_lost',
        'title', r.job || ' claimed ' || p_day || ' and produced nothing',
        'evidence', jsonb_build_object(
          'job', r.job,
          'run_date', p_day,
          'claimed_at', r.claimed_at,
          'claimed_by', r.claimed_by,
          'evidence_rows', 0
        ),
        'recommendation',
          'The job took the lock and died before writing a row - an engine ' ||
          'restart inside the run is the usual cause, and server/** merges ' ||
          'deploy automatically. Check the container logs for that window. ' ||
          'Any conclusion drawn from this job for this date is unsupported: ' ||
          'do not quote it.'
      );
    end if;
  end loop;

  select max(run_date) into v_last_league from horse_league_results;
  if v_last_league is null then
    v_findings := v_findings || jsonb_build_object(
      'severity', 'critical',
      'category', 'schema',
      'code', 'league_card_empty',
      'title', 'horse_league_results has no rows at all',
      'evidence', jsonb_build_object('as_of', p_day),
      'recommendation',
        'No layer has ever been measured. Every strategy verdict is opinion ' ||
        'until the league runs.'
    );
  else
    v_gap := p_day - v_last_league;
    if v_gap >= 1 then
      select count(*) into v_matchups from horse_league_results where run_date = v_last_league;
      v_findings := v_findings || jsonb_build_object(
        'severity', case when v_gap >= 2 then 'critical' else 'warn' end,
        'category', 'schema',
        'code', 'league_card_stale',
        'title', 'The newest league measurement is ' || v_gap || ' day(s) before ' || p_day,
        'evidence', jsonb_build_object(
          'last_run_date', v_last_league,
          'days_stale', v_gap,
          'matchups_in_last_run', v_matchups
        ),
        'recommendation',
          'Layer verdicts are being read off a card this many days old. ' ||
          'Significance rules assume independent runs, so a single surviving ' ||
          'run cannot satisfy any three-run gate (v16_ratio_rescale in ' ||
          'particular). Fix the runner before tuning anything on this card.'
      );
    end if;
  end if;

  for r in
    select matchup, hands
      from horse_league_results
     where run_date = p_day and bb100 = 0 and stderr = 0 and hands > 0
     order by matchup
  loop
    v_findings := v_findings || jsonb_build_object(
      'severity', 'warn',
      'category', 'logic',
      'code', 'league_matchup_inert',
      'title', r.matchup || ' returned exactly zero over ' || r.hands || ' hands',
      'evidence', jsonb_build_object('matchup', r.matchup, 'hands', r.hands),
      'recommendation',
        'Both arms played identically. Confirm the b-side flag still gates ' ||
        'live code; if it does not, the layer is unreachable or the flag is ' ||
        'dead and the matchup should be retired or repointed.'
    );
  end loop;

  return v_findings;
end
$$;


ALTER FUNCTION public.fn_audit_nightly_job_health(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_overlays(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_overlays(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb := '[]'::jsonb; r record; total numeric := 0; n int := 0;
begin
  for r in
    select t.name, t.guaranteed_prize gtd, t.buy_in_amount bi,
           coalesce(t.current_players,0) cur,
           (t.guaranteed_prize - coalesce(t.current_players,0) * t.buy_in_amount) short
    from tournaments t
    where t.guaranteed_prize > 0 and t.buy_in_amount > 0
      and t.started_at >= p_day and t.started_at < p_day + 1
      and (t.guaranteed_prize - coalesce(t.current_players,0) * t.buy_in_amount) > 0
    order by 5 desc limit 10
  loop
    total := total + r.short; n := n + 1;
    v := v || jsonb_build_object(
      'severity', case when r.short >= 200 then 'critical' else 'warn' end,
      'category', 'logic', 'code', 'tournament_overlay',
      'title', r.name || ' started with a ' || round(r.short, 2) || ' overlay',
      'evidence', jsonb_build_object('guarantee', r.gtd, 'buy_in', r.bi,
                                     'entries', r.cur, 'shortfall', r.short),
      'recommendation', 'The overlay guard did not fill this event before it started. Check HorseOverlayGuard logs for that window: it may have been starved of eligible horses (events/both lane, under the four-table cap) or the event may have started sooner than the guard cycle.'
    );
  end loop;
  if n > 0 then
    v := v || jsonb_build_object(
      'severity', 'info', 'category', 'logic', 'code', 'overlay_total',
      'title', 'Club covered ' || round(total, 2) || ' in overlays across ' || n || ' event(s)',
      'evidence', jsonb_build_object('events', n, 'total_overlay', round(total, 2)),
      'recommendation', 'Total is the money the guarantee cost beyond what entries funded.'
    );
  end if;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_overlays(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_privileged_grants(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_privileged_grants() RETURNS TABLE(severity text, function_name text, arguments text, security_definer boolean, remedy text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    CASE
      WHEN pg_get_function_result(p.oid) = 'trigger' THEN 'LOW'
      WHEN p.prosecdef THEN 'CRITICAL'
      ELSE 'MEDIUM'
    END::text AS severity,
    p.proname::text,
    pg_get_function_identity_arguments(p.oid)::text,
    p.prosecdef,
    CASE
      WHEN pg_get_function_result(p.oid) = 'trigger'
        THEN 'Trigger function; anon cannot meaningfully invoke it. Tidy up when convenient.'
      WHEN p.prosecdef
        THEN 'SECURITY DEFINER bypasses RLS and anon can call it. REVOKE EXECUTE ... FROM PUBLIC, anon NOW.'
      ELSE 'anon can call it; RLS on the underlying tables is the only thing stopping a write. REVOKE for defence in depth.'
    END::text
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND p.prokind = 'f'
    AND has_function_privilege('anon', p.oid, 'EXECUTE')
    AND p.proname !~ '^st_'
    AND p.proname <> 'fn_audit_privileged_grants'
    AND (
         p.proname ~* '(mint_|_mint|chip|wallet|promo|cashout|diamond|rake|bounty|settle|payout|clawback|purchase|treasury|jackpot|bbj)'
      OR p.proname ~* '^(credit|debit|transfer|distribute|deduct|atomic|admin)_'
      OR p.proname ~* '(promote_member|transfer_club_ownership|remove_player)'
    )
  ORDER BY
    CASE WHEN pg_get_function_result(p.oid)='trigger' THEN 3
         WHEN p.prosecdef THEN 1 ELSE 2 END,
    p.proname;
$$;


ALTER FUNCTION public.fn_audit_privileged_grants() OWNER TO postgres;

--
-- Name: FUNCTION fn_audit_privileged_grants(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_audit_privileged_grants() IS 'INVARIANT: money/privileged functions must not be anon-executable. CRITICAL (SECURITY DEFINER + anon) must always be 0 -- gate CI on it. MEDIUM = anon but RLS-protected. LOW = trigger functions. New functions inherit EXECUTE for PUBLIC, so every privileged CREATE FUNCTION needs a paired REVOKE ... FROM PUBLIC, anon in the SAME migration.';


--
-- Name: fn_audit_river_aggression_ev(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_river_aggression_ev(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  r record;
  v_ranked int := 0;
begin
  for r in
    select * from fn_horse_tag_ev(p_day - 6)
     where mirrored and hands >= 200
     order by bb_per_hand asc
  loop
    v_ranked := v_ranked + 1;
    if r.bb_per_hand < 0 then
      v := v || jsonb_build_object('severity', case when r.net_bb < -20000 then 'warn' else 'info' end,
        'category','gto','code','tag_ev_negative',
        'title', r.situation || ' is losing ' || r.bb_per_hand || 'bb per hand over ' || r.hands || ' hands',
        'evidence', jsonb_build_object('situation', r.situation, 'hands', r.hands,
                                       'won_hands', r.won_hands, 'net_bb', r.net_bb,
                                       'bb_per_hand', r.bb_per_hand, 'win_rate', r.win_rate),
        'recommendation','Both outcomes of this situation are counted, so this is EV and not a damage total. A negative number here is a real leak and a cap is worth testing: flag it, add a league matchup, and do not claim an improvement without significance.');
    end if;
  end loop;

  if v_ranked = 0 then
    v := v || jsonb_build_object('severity','info','category','schema','code','tag_ev_unavailable',
      'title','No mirrored situation has 200 hands in the seven-day window',
      'evidence', jsonb_build_object('day', p_day),
      'recommendation','horse_review_rollup.leak_net_bb is written by fn_hhr_rollup_add on every review insert. If counts exist and nets do not, the rollup is running a build from before 2026-09-06.');
  else
    v := v || jsonb_build_object('severity','info','category','gto','code','tag_ev_ranked',
      'title', v_ranked || ' mirrored situations ranked by EV over seven days',
      'evidence', jsonb_build_object('situations', v_ranked, 'since', p_day - 6),
      'recommendation','Ranked by bb per hand across BOTH outcomes, which is the only honest ranking: a loss-only total ranks situations by how often they occur in big pots. The fold family has no winning mirror and is deliberately excluded - a folded hand never wins, so its total is the fold, not a leak.');
  end if;

  return v;
end $$;


ALTER FUNCTION public.fn_audit_river_aggression_ev(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_seat_clock(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_seat_clock(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  v_seated int;
  v_touched int;
  v_decides bigint;
begin
  select count(*) filter (where state = 'seated'),
         count(*) filter (where state = 'seated' and last_action_at >= now() - interval '2 hours')
    into v_seated, v_touched
    from ca_horse_fleet_state;
  select coalesce(sum(fires), 0) into v_decides
    from horse_brain_telemetry where day = p_day and feature = 'decide';
  if v_seated >= 50 and v_decides >= 100000 and v_touched = 0 then
    v := v || jsonb_build_object('severity','critical','category','schema','code','seat_clock_dead',
      'title', v_seated || ' seated horses and none has a last_action_at in the last two hours, against ' || v_decides || ' decisions on ' || p_day,
      'evidence', jsonb_build_object('seated', v_seated, 'touched_2h', v_touched, 'decides', v_decides),
      'recommendation','fn_ca_fleet_seat_touch is not being called (HorseHandReview.touchHorseSeats, HORSE_SEAT_TOUCH_ENABLED) or the fleet upsert is overwriting it again (fn_ca_fleet_state_upsert must coalesce last_action_at). The panel cannot tell a playing horse from a stuck one without it.');
  end if;

  -- 2026-09-06: a breather that never ends holds a seat the horse will never
  -- act from, which is the same question this step exists to ask.
  v := v || fn_audit_breather_returns(p_day);
  return v;
end $$;


ALTER FUNCTION public.fn_audit_seat_clock(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_solver_agreement(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_solver_agreement(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  r record;
  prev numeric;
begin
  for r in
    select * from horse_solver_agreement
     where run_date > p_day - 3 and run_date <= p_day + 1
     order by run_date desc limit 1
  loop
    select agreement into prev from horse_solver_agreement
     where reference = r.reference and run_date < r.run_date
     order by run_date desc limit 1;
    if r.spots < 50 then
      v := v || jsonb_build_object('severity','warn','category','gto','code','solver_agreement_thin',
        'title','Solver agreement probed only ' || r.spots || ' spots on ' || r.run_date,
        'evidence', jsonb_build_object('spots', r.spots, 'reference', r.reference),
        'recommendation','The push/fold chart store is nearly empty in this process (GtoChartsLoader). The probe reports what it could reach; a thin sample is a loader problem, not a brain one.');
    elsif prev is not null and r.agreement < prev - 0.03 then
      v := v || jsonb_build_object('severity','critical','category','gto','code','solver_agreement_dropped',
        'title','Solver agreement fell to ' || round(r.agreement, 3) || ' from ' || round(prev, 3),
        'evidence', jsonb_build_object('agreement', r.agreement, 'previous', prev, 'spots', r.spots,
                                       'pure_misses', r.pure_misses, 'reference', r.reference),
        'recommendation','The brain moved AWAY from the solver on spots it used to agree with. This is the one measurement the league cannot make, and a drop after a deploy is a regression in a preflop layer. Diff the day''s engine deploys against HorsePreflop and the GTO consult.');
    else
      v := v || jsonb_build_object('severity','info','category','gto','code','solver_agreement',
        'title','Solver agreement ' || round(r.agreement, 3) || ' over ' || r.spots || ' spots (' || r.pure_misses || ' pure misses)',
        'evidence', jsonb_build_object('agreement', r.agreement, 'previous', prev, 'spots', r.spots,
                                       'pure_misses', r.pure_misses, 'reference', r.reference),
        'recommendation','The absolute score: the mean solver frequency of the action the horse chose, hold em push/fold only. A pure miss is a spot where the solver is 90%+ one way and the horse went the other.');
    end if;
  end loop;
  if v = '[]'::jsonb then
    v := v || jsonb_build_object('severity','info','category','gto','code','solver_agreement_missing',
      'title','No solver agreement row in the last three days',
      'evidence', jsonb_build_object('day', p_day),
      'recommendation','HorseLeague writes it after the nightly matchups. If the league ran and this is absent, the probe threw - check horse_error_log for HorseLeague.agreement.');
  end if;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_solver_agreement(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_supply_breaches(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_supply_breaches(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_findings jsonb := '[]'::jsonb;
  v_n int;
  v_sum numeric;
  v_oldest timestamptz;
  v_newest timestamptz;
  v_worst numeric;
begin
  select count(*), coalesce(sum(unexplained), 0), min(taken_at), max(taken_at),
         coalesce(max(abs(unexplained)), 0)
    into v_n, v_sum, v_oldest, v_newest, v_worst
    from fn_ca_unacknowledged_supply_breaches();

  if v_n = 0 then
    return v_findings;
  end if;

  v_findings := v_findings || jsonb_build_object(
    'severity', 'critical',
    'category', 'schema',
    'code', 'supply_breach_unacknowledged',
    'title', v_n || ' chip-supply breach(es) have never been explained, netting '
             || round(v_sum, 2) || ' chips',
    'evidence', jsonb_build_object(
      'breaches', v_n,
      'net_unexplained', round(v_sum, 2),
      'largest_single', round(v_worst, 2),
      'oldest', v_oldest,
      'newest', v_newest,
      'rows', (select coalesce(jsonb_agg(jsonb_build_object(
                        'taken_at', b.taken_at,
                        'unexplained', b.unexplained,
                        'age_hours', b.age_hours) order by b.taken_at desc), '[]'::jsonb)
                 from fn_ca_unacknowledged_supply_breaches() b)
    ),
    'recommendation',
      'The deploy gate only sums a TRAILING FOUR HOURS, so each of these went '
      || 'green on its own within four hours of happening and has been invisible '
      || 'since. This finding does not expire. Either explain each one with an '
      || 'INSERT into ca_supply_breach_ack (snapshot_id, acknowledged_by, reason), '
      || 'which is a deliberate written act and the audit trail for chips that '
      || 'could not be accounted for, or treat it as a live money-integrity '
      || 'incident. If these are the gap already baselined by '
      || 'baseline_the_unledgered_gap on 2026-08-27, say so in the reason - do '
      || 'not assume it, because nothing in the data says it.'
  );

  return v_findings;
end
$$;


ALTER FUNCTION public.fn_audit_supply_breaches(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_tag_consumers(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_tag_consumers(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  r record;
  v_registry int;
begin
  select count(*) into v_registry from horse_data_ledger where kind = 'tag';
  if v_registry = 0 then
    v := v || jsonb_build_object('severity','warn','category','schema','code','tag_registry_missing',
      'title','horse_data_ledger has no tag rows - the engine has not synced TAG_CONSUMERS',
      'evidence', jsonb_build_object('rows', 0),
      'recommendation','HorseDataLedgerSync writes the tag registry at boot. Until the engine restarts on a build that carries TAG_CONSUMERS, tag_unread cannot be judged.');
    return v;
  end if;
  for r in
    with week as (
      select k as tag, sum((leak_counts->>k)::bigint) as n
        from horse_review_rollup, lateral jsonb_object_keys(leak_counts) k
       where day > p_day - 7 and day <= p_day
       group by k
    )
    select w.tag, w.n,
           l.consumer,
           case when w.tag like '%\_won' escape '\' then substr(w.tag, 1, length(w.tag) - 4) end as base
      from week w
      left join horse_data_ledger l on l.kind = 'tag' and l.key = 'tag:' || w.tag
     where w.n >= 100
     order by w.n desc
  loop
    if r.consumer is null and r.base is not null then
      continue;
    end if;
    if r.consumer is null then
      v := v || jsonb_build_object('severity','warn','category','logic','code','tag_unread',
        'title','Leak tag ' || r.tag || ' (' || r.n || ' rows this week) has no ledger row',
        'evidence', jsonb_build_object('tag', r.tag, 'rows_7d', r.n),
        'recommendation','A detector emits this tag and HorseDataLedger.TAG_CONSUMERS does not know it. EveryTagHasAConsumer.law.test.ts should have failed; if the engine is older than the tag, redeploy. Register it with the code that reads it, or as measurement with the reason.');
    elsif r.consumer = 'measurement' and r.n >= 1000 then
      v := v || jsonb_build_object('severity','info','category','logic','code','tag_measurement_only',
        'title','Leak tag ' || r.tag || ' (' || r.n || ' rows this week) is measurement only',
        'evidence', jsonb_build_object('tag', r.tag, 'rows_7d', r.n, 'reason', (select note from horse_data_ledger where kind = 'tag' and key = 'tag:' || r.tag)),
        'recommendation','Registered as read by nobody, with a reason. Volume this high is worth a decision: wire a consumer with a receipt, or keep the reason current.');
    end if;
  end loop;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_tag_consumers(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_tournament_results(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_tournament_results(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  r record;
  v_completed int;
  v_rows int;
begin
  select count(*) into v_completed from tournaments
   where status = 'COMPLETED' and ended_at >= p_day and ended_at < p_day + 1;
  select count(*) into v_rows from horse_tournament_daily where day = p_day;
  if v_completed >= 20 and v_rows = 0 then
    v := v || jsonb_build_object('severity','critical','category','schema','code','tournament_results_missing',
      'title', v_completed || ' tournaments completed on ' || p_day || ' and the horse scoreboard has no rows',
      'evidence', jsonb_build_object('completed', v_completed, 'scoreboard_rows', v_rows),
      'recommendation','fn_horse_tournament_daily_compile did not run or found no horse entries. It is called from fn_run_horse_daily_audit; check the audit ran and tournament_players.position is being written at completion.');
    return v;
  end if;
  for r in
    select tournament_type,
           sum(entries) as entries,
           sum(invested) as invested,
           sum(won) as won,
           case when sum(invested) > 0 then round(100 * (sum(won) - sum(invested)) / sum(invested), 1) end as roi_pct,
           case when sum(entries) > 0 then round(100.0 * sum(itm_entries) / sum(entries), 1) end as itm_pct
      from horse_tournament_daily
     where day > p_day - 7 and day <= p_day
     group by 1
  loop
    if r.entries >= 2000 and r.roi_pct is not null and r.roi_pct < -15 then
      v := v || jsonb_build_object('severity','warn','category','gto','code','tournament_roi_negative',
        'title', r.tournament_type || ' ROI ' || r.roi_pct || '% over ' || r.entries || ' entries (7 days)',
        'evidence', jsonb_build_object('tournament_type', r.tournament_type, 'entries', r.entries, 'invested', round(r.invested), 'won', round(r.won), 'roi_pct', r.roi_pct, 'itm_pct', r.itm_pct),
        'recommendation','The fleet plays itself, so a type''s pooled ROI is minus the fee and any overlay; compare against -fee%. A type far below that is a format the brain plays badly: read the tournament-format tags for it (fn_horse_tournament_leaks) before touching the ICM dials.');
    else
      v := v || jsonb_build_object('severity','info','category','gto','code','tournament_results',
        'title', r.tournament_type || ' ROI ' || coalesce(r.roi_pct::text, 'n/a') || '%, ITM ' || coalesce(r.itm_pct::text, 'n/a') || '% over ' || r.entries || ' entries (7 days)',
        'evidence', jsonb_build_object('tournament_type', r.tournament_type, 'entries', r.entries, 'invested', round(r.invested), 'won', round(r.won), 'roi_pct', r.roi_pct, 'itm_pct', r.itm_pct),
        'recommendation','The tournament lane scoreboard. Not a finding; the number Dan asked for.');
    end if;
  end loop;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_tournament_results(p_day date) OWNER TO postgres;

--
-- Name: fn_audit_tuner_health(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_tuner_health(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  v_rows int;
  v_regress int;
  v_tight int;
  v_play int;
  v_play_age int;
  v_run date := p_day + 1;
begin
  -- The accounting the rule depends on, first: a verdict below is only
  -- meaningful once the drop is fully attributed.
  v := v || fn_audit_fleet_drop_identity(p_day);

  select count(*),
         count(*) filter (where array_to_string(reasons, ' ') like '%regress dials halfway%'),
         count(*) filter (where array_to_string(reasons, ' ') like '%too loose%'),
         count(*) filter (where (stats->>'study_source')::int = 1)
    into v_rows, v_regress, v_tight, v_play
    from horse_self_tune_log where run_date = v_run;
  if v_rows = 0 then
    v := v || jsonb_build_object('severity','warn','category','logic','code','tuner_no_rows',
      'title','No self-tune rows for ' || v_run || ' - the leak profiles did not move',
      'evidence', jsonb_build_object('run_date', v_run),
      'recommendation','HorseSelfTuner is the only writer of profiles.horse_profile.leaks*; every night it does not run, the brain reads stale verdicts. See the nightly_job_health finding for the claim.');
    return v;
  end if;
  if v_regress::numeric / v_rows > 0.4 then
    v := v || jsonb_build_object('severity','critical','category','logic','code','tuner_regressed_the_fleet',
      'title', v_regress || ' of ' || v_rows || ' tuned horses regressed to neutral on ' || v_run,
      'evidence', jsonb_build_object('run_date', v_run, 'tuned', v_rows, 'regressed', v_regress, 'share', round(v_regress::numeric / v_rows, 3)),
      'recommendation','The regression rule is reading the DROP as a leak again (2026-09-04: 221 of 383). It must judge net_bb + rake_bb + bbj_bb and only a horse under the fleet p25 - see RegressionContext in HorseSelfTuner.ts, TheTunerDoesNotFightTheRake.law.test.ts and TheDropIsTheRakeAndTheJackpot.law.test.ts. Read the drop-identity finding above this one first: if the attribution is short, this number is the shortfall, not 221 broken horses.');
  end if;

  -- A MASS TIGHTENING IS THE SAME CLASS OF BUG (2026-09-06). It ran three
  -- nights running - 104/429, 180/386, 216/383 - because floored tables were
  -- measured against the winning-player band. Whenever half the fleet is
  -- moved the same way, the input is wrong before the dials are.
  if v_tight::numeric / v_rows > 0.40 then
    v := v || jsonb_build_object('severity','critical','category','logic','code','tuner_tightened_the_fleet',
      'title', v_tight || ' of ' || v_rows || ' tuned horses were tightened for "too loose" on ' || v_run,
      'evidence', jsonb_build_object('run_date', v_run, 'tuned', v_rows, 'tightened', v_tight, 'share', round(v_tight::numeric / v_rows, 3)),
      'recommendation','Half the fleet is not individually too loose - the measurement is. Check that horse_daily_play.floored is being written (a floored table REQUIRES loose play) and that loadPlayRows still filters floored = false. `tightness` is a GLOBAL dial, so a horse tightened for its floored table plays nittier at every ordinary table it sits at.');
  end if;

  select count(distinct day) into v_play_age from horse_daily_play where day > p_day - 7 and day <= p_day;
  if v_play_age >= 6 and v_play::numeric / v_rows < 0.6 then
    v := v || jsonb_build_object('severity','warn','category','schema','code','tuner_studied_from_stream',
      'title', (v_rows - v_play) || ' of ' || v_rows || ' tuned horses came from the hand_history stream, not horse_daily_play',
      'evidence', jsonb_build_object('run_date', v_run, 'tuned', v_rows, 'from_play_rows', v_play, 'play_days_in_window', v_play_age),
      'recommendation','horse_daily_play has a week of rows, so the tuner should study nearly every horse from it. Either the settlement compiler (HorseHandReview.accumulateHorsePlay) is off (HORSE_PLAY_ROLLUP_ENABLED) or loadPlayRows is failing (horse_error_log context HorseSelfTuner.playRows).');
  end if;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_tuner_health(p_day date) OWNER TO postgres;

--
-- Name: fn_auto_create_story_from_post(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_auto_create_story_from_post() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Wrap in exception handler so a failed story insert never blocks the post
    BEGIN
        INSERT INTO social_stories (
            author_id,
            content,
            media_url,
            media_type,
            created_at,
            expires_at,
            is_active
        )
        VALUES (
            NEW.author_id,
            LEFT(NEW.content, 200),
            CASE WHEN NEW.media_urls IS NOT NULL AND jsonb_array_length(NEW.media_urls) > 0
                 THEN NEW.media_urls->>0
                 ELSE NULL
            END,
            CASE
                WHEN NEW.media_urls IS NOT NULL AND jsonb_array_length(NEW.media_urls) > 0 THEN
                    CASE WHEN NEW.media_urls->>0 ILIKE '%.mp4' OR NEW.media_urls->>0 ILIKE '%video%'
                         THEN 'video'
                         ELSE 'image'
                    END
                ELSE NULL
            END,
            NOW(),
            NOW() + INTERVAL '24 hours',
            true
        );
    EXCEPTION WHEN OTHERS THEN
        -- Silently swallow - story creation is optional, never block the post
        RAISE WARNING '[fn_auto_create_story_from_post] Failed: %', SQLERRM;
    END;

    RETURN NEW;  -- CRITICAL: Always return NEW so the INSERT proceeds
END;
$$;


ALTER FUNCTION public.fn_auto_create_story_from_post() OWNER TO postgres;

--
-- Name: fn_auto_end_stale_streams(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_auto_end_stale_streams(p_timeout_seconds integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ended_count integer := 0;
  v_stale_threshold timestamptz := now() - (p_timeout_seconds || ' seconds')::interval;
BEGIN
  WITH stale AS (
    SELECT id 
    FROM live_streams
    WHERE status = 'live'
      AND started_at < v_stale_threshold
      AND (preview_updated_at IS NULL OR preview_updated_at < v_stale_threshold)
  )
  UPDATE live_streams ls
     SET status   = 'ended',
         ended_at = now()
   WHERE ls.id IN (SELECT id FROM stale);

  GET DIAGNOSTICS v_ended_count = ROW_COUNT;
  
  RETURN jsonb_build_object(
    'success', true,
    'ended_count', v_ended_count,
    'timeout_seconds', p_timeout_seconds
  );
END;
$$;


ALTER FUNCTION public.fn_auto_end_stale_streams(p_timeout_seconds integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_auto_end_stale_streams(p_timeout_seconds integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_auto_end_stale_streams(p_timeout_seconds integer) IS 'Bug 8b: Transitions live streams that haven''t had preview_updated_at activity in p_timeout_seconds (default 60) to status=ended. Called from a periodic cron / admin script.';


--
-- Name: fn_auto_promote_waitlist(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_auto_promote_waitlist() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_target_game_id uuid;
    v_game_exists    boolean;
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.response = 'yes' AND NEW.response <> 'yes' THEN
        v_target_game_id := NEW.game_id;
    ELSIF TG_OP = 'DELETE' AND OLD.response = 'yes' THEN
        v_target_game_id := OLD.game_id;
    ELSE
        RETURN COALESCE(NEW, OLD);
    END IF;

    SELECT EXISTS(SELECT 1 FROM commander_home_games WHERE id = v_target_game_id)
      INTO v_game_exists;
    IF NOT v_game_exists THEN
      RETURN COALESCE(NEW, OLD);
    END IF;

    -- Mark this tx as a legitimate auto-promote context so the RPC's
    -- hardened auth gate permits the NULL p_caller_user_id call path.
    -- LOCAL scope: rolls back at tx end, cannot leak to other sessions.
    PERFORM set_config('app.hg_waitlist_auto_promote', '1', true);

    BEGIN
      PERFORM public.promote_home_game_waitlist(v_target_game_id, NULL);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'fn_auto_promote_waitlist swallowed promote error for game %: % (%)',
        v_target_game_id, SQLERRM, SQLSTATE;
    END;

    -- Clear the GUC before returning so subsequent work in the same tx
    -- (e.g. other triggers firing on cascading mutations) can't reuse it.
    PERFORM set_config('app.hg_waitlist_auto_promote', '', true);

    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.fn_auto_promote_waitlist() OWNER TO postgres;

--
-- Name: FUNCTION fn_auto_promote_waitlist(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_auto_promote_waitlist() IS 'Phase 40: fires on RSVP delete/update-from-yes to promote waitlist. Tolerates parent-game-already-deleted (cascade) and swallows any downstream promotion errors so the underlying RSVP mutation always succeeds. Waitlist promotion is opportunistic.';


--
-- Name: fn_autorevoke_privileged_anon(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_autorevoke_privileged_anon() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  obj          record;
  lk           record;
  v_name       text;
  v_sig        text;
  v_secdef     boolean;
  v_src        text;
  v_behaves    boolean;
  v_named      boolean;
  v_saw_grant  boolean := false;
BEGIN
  IF COALESCE(current_setting('app.allow_privileged_anon_grant', true), 'off') = 'on' THEN
    RETURN;
  END IF;

  FOR obj IN SELECT * FROM pg_event_trigger_ddl_commands() LOOP

    -- GRANT rows carry no objid/object_identity at all (probe-verified):
    --   [tag=GRANT | object_type=FUNCTION | objid=NULL | ident=NULL]
    -- so the granted function cannot be identified here. Flag a lock sweep.
    IF obj.command_tag = 'GRANT' THEN
      IF upper(COALESCE(obj.object_type, '')) = 'FUNCTION' THEN
        v_saw_grant := true;
      END IF;
      CONTINUE;
    END IF;

    IF lower(COALESCE(obj.object_type, '')) <> 'function' THEN
      CONTINUE;
    END IF;

    SELECT p.proname,
           format('public.%I(%s)', p.proname,
                  COALESCE((SELECT string_agg(format_type(t.typ, NULL), ', ' ORDER BY t.ord)
                              FROM unnest(p.proargtypes) WITH ORDINALITY AS t(typ, ord)), '')),
           p.prosecdef,
           p.prosrc
      INTO v_name, v_sig, v_secdef, v_src
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE p.oid = obj.objid
       AND n.nspname = 'public';

    IF v_name IS NULL
       OR v_name IN ('fn_autorevoke_privileged_anon', 'fn_audit_privileged_grants') THEN
      CONTINUE;
    END IF;

    -- ARM 1 - NAME. Unchanged except the prefix arm now tolerates an `fn_`
    -- prefix: `fn_credit_stalled_seat_first_stacks` defeated the anchored
    -- version on 2026-08-23 despite crediting stacks.
    v_named := v_name !~ '^st_' AND (
         v_name ~* '(mint_|_mint|chip|wallet|promo|cashout|diamond|rake|bounty|settle|payout|clawback|purchase|treasury|jackpot|bbj)'
      OR v_name ~* '^(fn_)?(credit|debit|transfer|distribute|deduct|atomic|admin)_'
      OR v_name ~* '(promote_member|transfer_club_ownership|remove_player)'
    );

    -- ARM 2 - BEHAVIOUR. The rule economy_invariants() actually asserts:
    -- SECURITY DEFINER (so RLS does not apply) + writes + never consults
    -- auth.uid() (so it cannot tell who is asking). Such a function must not
    -- be reachable without a session, whatever it is called. This is the arm
    -- that would have caught all six of today's.
    v_behaves := COALESCE(v_secdef, false)
             AND v_src ~* '\m(insert|update|delete)\M'
             AND v_src !~* 'auth\.uid\(\)';

    IF v_named OR v_behaves THEN
      BEGIN
        EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC', obj.object_identity);
        EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM anon',   obj.object_identity);

        INSERT INTO public.privileged_function_lock (function_signature, security_definer, reason)
        VALUES (v_sig,
                COALESCE(v_secdef, false),
                'Auto-locked by trg_autorevoke_privileged_anon on ' || obj.command_tag
                 || CASE WHEN v_behaves AND NOT v_named
                         THEN ' (behavioural: definer + writes + no auth.uid())'
                         WHEN v_behaves THEN ' (name + behavioural)'
                         ELSE ' (name)' END || '.')
        ON CONFLICT (function_signature) DO NOTHING;

        RAISE NOTICE '[autorevoke] stripped PUBLIC/anon EXECUTE from % (tag %, named=%, behaviour=%)',
          obj.object_identity, obj.command_tag, v_named, v_behaves;
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING '[autorevoke] could not revoke on %: %', obj.object_identity, SQLERRM;
      END;
    END IF;
  END LOOP;

  IF v_saw_grant THEN
    FOR lk IN
      SELECT l.function_signature, to_regprocedure(l.function_signature) AS rp
        FROM public.privileged_function_lock l
       WHERE to_regprocedure(l.function_signature) IS NOT NULL
         AND ( has_function_privilege('anon',   to_regprocedure(l.function_signature)::oid, 'EXECUTE')
            OR has_function_privilege('public', to_regprocedure(l.function_signature)::oid, 'EXECUTE') )
    LOOP
      BEGIN
        EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC', lk.function_signature);
        EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM anon',   lk.function_signature);
        RAISE NOTICE '[autorevoke] GRANT sweep re-revoked anon/PUBLIC on %', lk.function_signature;
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING '[autorevoke] GRANT sweep could not revoke on %: %', lk.function_signature, SQLERRM;
      END;
    END LOOP;
  END IF;
END;
$$;


ALTER FUNCTION public.fn_autorevoke_privileged_anon() OWNER TO postgres;

--
-- Name: FUNCTION fn_autorevoke_privileged_anon(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_autorevoke_privileged_anon() IS 'Event-trigger body: strips PUBLIC/anon EXECUTE from money/privileged functions on CREATE, ALTER and GRANT. Bypass for one transaction with SET app.allow_privileged_anon_grant=''on''. Verified by probe 2026-08-15.';


--
-- Name: fn_available_stake_bands(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_available_stake_bands() RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(array_agg(s.band ORDER BY s.ord), '{}'::text[])
    FROM (
      SELECT DISTINCT
             public.fn_cash_stake_band(cg.bb) AS band,
             CASE public.fn_cash_stake_band(cg.bb)
               WHEN 'micro' THEN 1
               WHEN 'low'   THEN 2
               WHEN 'mid'   THEN 3
               WHEN 'high'  THEN 4
             END AS ord
        FROM public.cash_games cg
       WHERE cg.enabled IS TRUE
         AND cg.bb IS NOT NULL
    ) s
   WHERE s.band IS NOT NULL;
$$;


ALTER FUNCTION public.fn_available_stake_bands() OWNER TO postgres;

--
-- Name: FUNCTION fn_available_stake_bands(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_available_stake_bands() IS 'The stake bands that have at least one ENABLED cash game, low to high. The SQL half of the engine''s bandSupply set (HorseBehavior.applyStakeBandSupply). Empty array means no enabled game at all, which every caller must treat as "change nothing" rather than "every band is empty".';


--
-- Name: fn_award_daily_mission_milestones(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_award_daily_mission_milestones(p_user_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_streak_receipt jsonb;
  v_streak integer;
  v_run_id uuid;
  v_started date;
  v_ended date;
  v_reward numeric := 0;
  v_max integer;
  v_max_reward numeric;
  v_reference text;
  v_credit jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'A Daily Missions milestone player is required';
  END IF;

  PERFORM public.fn_lock_daily_mission_user(p_user_id);
  v_streak_receipt := public.get_challenge_streak(p_user_id);
  v_streak := COALESCE((v_streak_receipt ->> 'streak')::integer, 0);
  v_run_id := NULLIF(v_streak_receipt ->> 'streakRunId', '')::uuid;
  v_started := NULLIF(v_streak_receipt ->> 'streakStartedOn', '')::date;
  v_ended := NULLIF(v_streak_receipt ->> 'streakEndedOn', '')::date;

  IF v_streak <= 0 OR v_run_id IS NULL OR v_started IS NULL OR v_ended IS NULL THEN
    RETURN 0;
  END IF;

  SELECT max(days) INTO v_max
  FROM public.daily_challenge_milestones;

  SELECT reward_diamonds INTO v_max_reward
  FROM public.daily_challenge_milestones
  WHERE days = v_max;

  WITH due AS (
    SELECT days, reward_diamonds
    FROM public.daily_challenge_milestones
    WHERE days <= v_streak
    UNION ALL
    SELECT day, v_max_reward
    FROM generate_series(
      v_max + 30,
      v_max + ((v_streak - v_max) / 30) * 30,
      30
    ) day
  ), inserted AS (
    INSERT INTO public.daily_challenge_milestone_claims (
      user_id,
      streak_run_id,
      streak_started_on,
      milestone_days,
      reward_diamonds
    )
    SELECT p_user_id, v_run_id, v_started, days, reward_diamonds
    FROM due
    ON CONFLICT DO NOTHING
    RETURNING reward_diamonds, milestone_days
  )
  SELECT COALESCE(sum(reward_diamonds), 0),
         'daily_mission_milestones:' || p_user_id::text || ':'
           || v_run_id::text || ':' || max(milestone_days)
  INTO v_reward, v_reference
  FROM inserted;

  IF v_reward > 0 THEN
    IF v_reward <> trunc(v_reward) OR v_reward > 2147483647 THEN
      RAISE EXCEPTION 'Daily Missions milestone aggregate is outside the whole-Diamond wallet range';
    END IF;

    v_credit := public.add_diamonds_to_balance(
      p_user_id,
      v_reward::integer,
      'daily_mission_milestone',
      'Daily Missions streak circuit',
      v_reference
    );

    IF COALESCE((v_credit ->> 'success')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Daily Missions streak milestone could not be credited: %',
        COALESCE(v_credit ->> 'error', 'unknown');
    END IF;
  END IF;

  RETURN v_reward;
END;
$$;


ALTER FUNCTION public.fn_award_daily_mission_milestones(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_award_daily_mission_milestones(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_award_daily_mission_milestones(p_user_id uuid) IS 'Awards streak circuits in DIAMONDS (Dan 2026-09-05: nothing ever earns chips, only diamonds). Returns the diamonds awarded - the return value changed currency, not shape, and no caller had ever received a non-zero one.';


--
-- Name: fn_award_satellite_seat(uuid, uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_award_satellite_seat(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_username text DEFAULT NULL::text, p_position integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_t        record;
  v_name     text;
  v_seat_id  uuid;
  v_cap      integer;
  v_existing uuid;
  v_existing_q boolean;
  v_seated   boolean;
  v_sat      record;
  v_field    integer;
  v_value    numeric;
  v_split record;
  -- Lane G (2026-09-02): the seat is paid from the satellite's own pool.
  v_sat_pool numeric;
  v_moved    numeric := 0;
  v_short    numeric := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  SELECT id, name, club_id, status, buy_in_amount, buy_in_fee,
         bounty_amount, is_bounty, is_pko, is_mystery_bounty,
         max_players, current_players, current_level,
         late_reg_levels, rebuy_levels, prize_pool_finalized
    INTO v_t
    FROM public.tournaments
   WHERE id = p_target_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'target_not_found');
  END IF;

  -- A previously committed award is a replay even if admission later closed.
    SELECT source_satellite_id, COALESCE(is_satellite_qualifier, false)
      INTO v_existing, v_existing_q
      FROM public.tournament_players
     WHERE tournament_id = p_target_id AND user_id = p_user_id
     LIMIT 1;

  IF FOUND THEN

    /* CHIP STANDARD (2026-09-05): A CASH ENTRANT IS NOT AN UNKNOWN. A seat
       with is_satellite_qualifier false was bought with the player's own
       chips (its wallet debit is on the ledger); no satellite seated them, so
       this one certainly did not, and the ticket value is theirs in cash.
       NULL origin is unknown only on a seat a satellite awarded before
       2026-08-30. Sunday Deep Stack Satellite $25 (956383d2), 19:22 UTC: the
       second place had bought the target seat for 200.00 at 10:08 and was
       paid nothing while first and third were paid 200.00 each. */
    v_seated := CASE WHEN NOT v_existing_q THEN false
                     WHEN v_existing IS NULL THEN NULL
                     ELSE (v_existing = p_satellite_id) END;

    RETURN jsonb_build_object(
      'ok', true, 'awarded', false, 'reason', 'already_registered',
      'held_from_this_satellite', v_seated,
      'origin_unknown', (v_existing_q AND v_existing IS NULL));
  END IF;

  -- One database predicate owns level-based and minutes-only late entry.
  -- ANNOUNCED/REGISTERING targets are open until their pool is finalized;
  -- RUNNING targets must pass the same locked gate as a paid registrant.
  IF v_t.status IN ('ANNOUNCED','REGISTERING') THEN
    IF COALESCE(v_t.prize_pool_finalized,false) THEN
      RETURN jsonb_build_object('ok',false,'reason','target_pool_finalized');
    END IF;
  ELSIF v_t.status='RUNNING' THEN
    IF NOT public.fn_tournament_late_registration_open(p_target_id) THEN
      RETURN jsonb_build_object('ok',false,'reason','target_closed');
    END IF;
  ELSE
    RETURN jsonb_build_object('ok',false,'reason','target_closed');
  END IF;

  SELECT count(*) INTO v_field
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_target_id;
  IF v_t.max_players IS NOT NULL AND v_field>=v_t.max_players THEN
    RETURN jsonb_build_object('ok',false,'reason','target_full');
  END IF;

  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_t.buy_in_amount, v_t.buy_in_fee, v_t.bounty_amount,
    COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false) OR COALESCE(v_t.is_mystery_bounty,false));
  IF v_split.prize < 0 OR v_split.bounty < 0 OR v_split.rake < 0
     OR v_split.charge <> v_split.prize + v_split.bounty + v_split.rake THEN
    RAISE EXCEPTION 'Invalid satellite target entry split' USING ERRCODE='23514';
  END IF;
  -- Open both escrows before journal triggers observe this award's writes.
  PERFORM public.fn_ca_escrow_apply(p_target_id, 'before satellite seat');
  PERFORM public.fn_ca_escrow_apply(p_satellite_id, 'before satellite seat');

  SELECT COALESCE(NULLIF(p_username, ''),
                  NULLIF(display_name, ''), NULLIF(username, ''), 'Player')
    INTO v_name
    FROM public.profiles WHERE id = p_user_id;
  v_name := COALESCE(v_name, COALESCE(NULLIF(p_username, ''), 'Player'));

  BEGIN
    INSERT INTO public.tournament_players
      (tournament_id, user_id, username, chips, status,
       is_satellite_qualifier, source_satellite_id, current_bounty)
    VALUES (p_target_id, p_user_id, v_name, 0, 'registered', true, p_satellite_id, v_split.bounty)
    RETURNING id INTO v_seat_id;
  EXCEPTION WHEN unique_violation THEN
    -- Already seated. Move nothing - the pool was credited when the seat was
    -- first taken. But SAY WHO SEATED THEM: a re-drive of THIS satellite must
    -- stay silent, while a win in a DIFFERENT satellite deserves the ticket
    -- value in cash, and only the caller can pay it.
    --
    -- AND SAY WHEN YOU DO NOT KNOW. source_satellite_id has only been written
    -- since 2026-08-30; every seat awarded before that has it NULL. Collapsing
    -- NULL to FALSE answers "a different satellite seated them" and sends the
    -- caller down the branch that pays cash, on top of a seat this satellite
    -- may well have awarded. NULL means unknown, and the caller pays nothing.
    SELECT source_satellite_id, COALESCE(is_satellite_qualifier, false)
      INTO v_existing, v_existing_q
      FROM public.tournament_players
     WHERE tournament_id = p_target_id AND user_id = p_user_id
     LIMIT 1;

    /* CHIP STANDARD (2026-09-05): A CASH ENTRANT IS NOT AN UNKNOWN. A seat
       with is_satellite_qualifier false was bought with the player's own
       chips (its wallet debit is on the ledger); no satellite seated them, so
       this one certainly did not, and the ticket value is theirs in cash.
       NULL origin is unknown only on a seat a satellite awarded before
       2026-08-30. Sunday Deep Stack Satellite $25 (956383d2), 19:22 UTC: the
       second place had bought the target seat for 200.00 at 10:08 and was
       paid nothing while first and third were paid 200.00 each. */
    v_seated := CASE WHEN NOT v_existing_q THEN false
                     WHEN v_existing IS NULL THEN NULL
                     ELSE (v_existing = p_satellite_id) END;

    RETURN jsonb_build_object(
      'ok', true, 'awarded', false, 'reason', 'already_registered',
      'held_from_this_satellite', v_seated,
      'origin_unknown', (v_existing_q AND v_existing IS NULL));
  END;

  UPDATE public.tournaments
     SET current_players = COALESCE(current_players, 0) + 1,
         prize_pool      = COALESCE(prize_pool, 0) + v_split.prize,
         bounty_pool     = COALESCE(bounty_pool, 0) + v_split.bounty,
         total_rake      = COALESCE(total_rake, 0) + COALESCE(v_t.buy_in_fee, 0)
   WHERE id = p_target_id;

  IF COALESCE(v_t.buy_in_fee, 0) > 0 AND v_t.club_id IS NOT NULL THEN
    INSERT INTO public.rake_records
      (hand_id, table_id, club_id, rake_amount, pot_size, num_players,
       bbj_contribution, is_tournament, tournament_id, source, metadata)
    VALUES (NULL, NULL, v_t.club_id, v_t.buy_in_fee,
            COALESCE(v_t.buy_in_amount, 0) + COALESCE(v_t.buy_in_fee, 0), 1, 0,
            true, p_target_id, 'fn_award_satellite_seat',
            jsonb_build_object('kind', 'satellite_seat_entry_fee', 'entry_split_version', 2,
                               'user_id', p_user_id,
                               'satellite_id', p_satellite_id,
                               'registration_id', v_seat_id));
  END IF;

  v_value := round(COALESCE(v_t.buy_in_amount, 0) + COALESCE(v_t.buy_in_fee, 0), 2);

  /* THE SEAT IS PAID FROM THE SATELLITE'S OWN POOL (Lane G, 2026-09-02).
     The target was just credited buy_in + fee. Until now nobody was debited,
     so the target owed prize money it never received and the satellite kept
     a pool it had already spent. Move the seat value out of the satellite's
     prize_pool, and write the one ledger row that says where it went.

     Every newly awarded seat must have a fully funded transfer and payout
     receipt in this transaction. Existing awards still replay above. */
  BEGIN
    SELECT prize_pool INTO v_sat_pool
      FROM public.tournaments
     WHERE id = p_satellite_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Satellite source tournament does not exist' USING ERRCODE = '23503';
    END IF;
    v_sat_pool := round(COALESCE(v_sat_pool, 0), 2);
    v_moved := LEAST(GREATEST(v_sat_pool, 0), v_value);
    v_short := round(v_value - v_moved, 2);

    IF v_moved > 0 THEN
      UPDATE public.tournaments
         SET prize_pool = round(COALESCE(prize_pool, 0) - v_moved, 2)
       WHERE id = p_satellite_id;

      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, tournament_id, idempotency_key,
         description, metadata,
         pre_from_balance, post_from_balance)
      VALUES
        (COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
         'prize_liability', p_satellite_id, 'tournaments.prize_pool',
         'prize_liability', p_target_id, 'tournaments.prize_pool+total_rake',
         v_moved, 'tournament_buyin', v_t.club_id, p_satellite_id,
         'tourney:' || p_satellite_id::text || ':seat:' || p_user_id::text || ':pool_transfer',
         format('Satellite seat: %s paid from the satellite pool into %s (buy-in %s + fee %s) for the seat of %s',
                v_moved, COALESCE(v_t.name, p_target_id::text),
                COALESCE(v_t.buy_in_amount, 0), COALESCE(v_t.buy_in_fee, 0), p_user_id),
         jsonb_build_object('kind', 'satellite_seat_pool_transfer',
                            'entry_split_version', 2, 'entry_prize', v_split.prize,
                            'entry_bounty', v_split.bounty, 'entry_fee', v_split.rake,
                            'satellite_id', p_satellite_id,
                            'satellite_target_id', p_target_id,
                            'user_id', p_user_id,
                            'registration_id', v_seat_id,
                            'seat_value', v_value,
                            'moved', v_moved,
                            'unbacked', v_short),
         v_sat_pool, round(v_sat_pool - v_moved, 2))
      ;
    END IF;

    IF v_short > 0 THEN
      RAISE EXCEPTION 'Satellite pool cannot fund the entire seat: required %, available %',
        v_value, v_sat_pool USING ERRCODE = '23514';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- The seat, target counters, source debit and journal are indivisible.
    RAISE;
  END;

  /* The payout receipt commits with the new seat and its funded transfer. */
  BEGIN
    SELECT tournament_type, prize_pool INTO v_sat
      FROM public.tournaments WHERE id = p_satellite_id;
    SELECT count(*) INTO v_field
      FROM public.tournament_players WHERE tournament_id = p_satellite_id;
    v_value := COALESCE(v_t.buy_in_amount, 0) + COALESCE(v_t.buy_in_fee, 0);

    INSERT INTO public.tournament_payouts
      (tournament_id, user_id, "position", amount, source, idempotency_key,
       paid_at, tournament_type, field_size, prize_pool, recorded_by, metadata)
    VALUES
      (p_satellite_id, p_user_id, p_position, v_value, 'satellite_seat',
       'tourney:' || p_satellite_id::text || ':seat:' || p_user_id::text,
       now(), v_sat.tournament_type, v_field,
       -- The COLLECTED pool, as every earlier row recorded it: read before
       -- this seat's transfer reduced it.
       COALESCE(v_sat_pool, v_sat.prize_pool),
       'award_satellite_seat',
       jsonb_build_object('satellite_target_id', p_target_id,
                          'target_name', v_t.name,
                          'registration_id', v_seat_id,
                          'target_buy_in', COALESCE(v_t.buy_in_amount, 0),
                          'target_fee', COALESCE(v_t.buy_in_fee, 0),
                          'entry_split_version', 2, 'entry_prize', v_split.prize,
                          'entry_bounty', v_split.bounty,
                          'pool_transfer', v_moved,
                          'unbacked', v_short))
    ;
  EXCEPTION WHEN OTHERS THEN
    -- An award without its payout receipt must roll back in full.
    RAISE;
  END;

  RETURN jsonb_build_object(
    'ok', true, 'awarded', true, 'registration_id', v_seat_id,
    'prize_contribution', v_split.prize,
    'bounty_contribution', v_split.bounty,
    'rake', COALESCE(v_t.buy_in_fee, 0),
    'pool_transfer', v_moved,
    'unbacked', v_short);
END;
$_$;


ALTER FUNCTION public.fn_award_satellite_seat(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_username text, p_position integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_award_satellite_seat(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_username text, p_position integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_award_satellite_seat(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_username text, p_position integer) IS 'Seats a satellite winner in the target and moves the seat value (target buy_in + fee) from the satellite prize_pool to the target prize_pool/total_rake with one chip_ledger row (prize_liability -> prize_liability, tournament_buyin, keyed tourney:<sat>:seat:<user>:pool_transfer). Never refuses a seat: a pool that cannot cover it moves what it holds and files warning satellite_seat_unbacked. Idempotent: a second call for a seated player moves nothing and reports held_from_this_satellite.';


--
-- Name: fn_award_share_streak_diamonds(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_award_share_streak_diamonds(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_today           date    := (now() AT TIME ZONE 'America/Chicago')::date;
    v_yesterday       date    := v_today - 1;
    v_streak_days     integer := 0;
    v_reward_diamonds integer := 0;
    v_reward_tier     text    := 'none';
    v_ref_id          text;
    v_award_result    jsonb;
BEGIN
    WITH daily_shares AS (
        SELECT date_trunc('day', created_at AT TIME ZONE 'America/Chicago')::DATE AS share_day
        FROM public.share_events
        WHERE user_id = p_user_id
          AND created_at >= (now() - INTERVAL '90 days')
        GROUP BY share_day
    ),
    numbered AS (
        SELECT
            share_day,
            share_day - ROW_NUMBER() OVER (ORDER BY share_day ASC)::integer AS grp
        FROM daily_shares
        WHERE share_day <= v_today
    ),
    active_grp AS (
        SELECT grp FROM numbered
        WHERE share_day >= v_yesterday
        ORDER BY share_day DESC
        LIMIT 1
    ),
    current_streak AS (
        SELECT COUNT(*) AS streak_days
        FROM numbered
        WHERE grp = (SELECT grp FROM active_grp)
    )
    SELECT COALESCE(streak_days, 0) INTO v_streak_days FROM current_streak;

    IF v_streak_days = 30 THEN
        v_reward_tier := 'legend';    v_reward_diamonds := 500;
    ELSIF v_streak_days = 14 THEN
        v_reward_tier := 'master';    v_reward_diamonds := 200;
    ELSIF v_streak_days = 7 THEN
        v_reward_tier := 'expert';    v_reward_diamonds := 100;
    ELSIF v_streak_days = 3 THEN
        v_reward_tier := 'streak';    v_reward_diamonds := 50;
    ELSE
        RETURN jsonb_build_object(
            'awarded', false,
            'streak_days', v_streak_days,
            'reason', 'no_milestone'
        );
    END IF;

    v_ref_id := format('streak_milestone_%s_%s_%s', p_user_id, v_reward_tier, v_today);

    SELECT public.add_diamonds_to_balance(
        p_user_id      := p_user_id,
        p_amount       := v_reward_diamonds,
        p_type         := 'streak_reward',
        p_description  := format('%s-day share streak milestone bonus', v_streak_days),
        p_reference_id := v_ref_id
    ) INTO v_award_result;

    INSERT INTO public.share_streak_rewards (user_id, reward_day, streak_length, diamonds_awarded)
    VALUES (p_user_id, v_today, v_streak_days, v_reward_diamonds)
    ON CONFLICT (user_id, reward_day) DO NOTHING;

    PERFORM public.fn_sync_share_streak_multiplier(p_user_id);

    RETURN jsonb_build_object(
        'awarded',      true,
        'streak_days',  v_streak_days,
        'tier',         v_reward_tier,
        'diamonds',     v_reward_diamonds,
        'award_result', v_award_result
    );
END;
$$;


ALTER FUNCTION public.fn_award_share_streak_diamonds(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_award_vip_credit(uuid, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_award_vip_credit(p_user_id uuid, p_credit numeric, p_source_type text, p_source_id uuid, p_reason text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ledger_id uuid;
  v_carry numeric(14,4);
  v_total numeric(14,4);
  v_pts bigint;
BEGIN
  -- SERVER ONLY. A browser calling this would be minting its own points.
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'fn_award_vip_credit is a server-side path' USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL OR COALESCE(p_credit, 0) <= 0 THEN
    RETURN 0;
  END IF;

  /* The carry row first, locked for this transaction: it serialises awards
     per user, and it is what the points depend on. Before phase 8 the leg
     was inserted with points = 0 and rewritten after this step. */
  INSERT INTO public.vip_points_carry (user_id, carry)
  VALUES (p_user_id, 0)
  ON CONFLICT (user_id) DO UPDATE SET carry = public.vip_points_carry.carry
  RETURNING carry INTO v_carry;

  v_total := v_carry + round(p_credit, 4);
  v_pts   := floor(v_total)::bigint;

  /* The leg, once, final. The unique (user, source_type, source_id) key is
     the idempotency: a second award for the same source writes nothing and
     changes nothing - the carry above was only locked, not moved. */
  INSERT INTO public.vip_points_ledger (user_id, points, reason, source_type, source_id, credit)
  VALUES (p_user_id, v_pts, p_reason, p_source_type, p_source_id, round(p_credit, 4))
  ON CONFLICT (user_id, source_type, source_id) DO NOTHING
  RETURNING id INTO v_ledger_id;
  IF v_ledger_id IS NULL THEN
    RETURN 0;
  END IF;

  UPDATE public.vip_points_carry SET carry = v_total - v_pts, updated_at = now() WHERE user_id = p_user_id;

  IF v_pts > 0 THEN
    PERFORM set_config('app.vip_points_writer', 'fn_award_vip_credit', true);
    INSERT INTO public.vip_points (user_id, current_points, lifetime_points)
    VALUES (p_user_id, v_pts, v_pts)
    ON CONFLICT (user_id) DO UPDATE
      SET current_points = public.vip_points.current_points + v_pts,
          lifetime_points = public.vip_points.lifetime_points + v_pts,
          updated_at = now();
    PERFORM set_config('app.vip_points_writer', '', true);
  END IF;
  RETURN v_pts;
END;
$$;


ALTER FUNCTION public.fn_award_vip_credit(p_user_id uuid, p_credit numeric, p_source_type text, p_source_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: fn_award_vip_points_from_rake(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_award_vip_points_from_rake() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  rec record;
BEGIN
  /* Tournament rake (entry fees, rebuys, satellite seats, spin books) is
     attributed ONCE, at settlement: fn_settle_tournament_rake ->
     fn_attribute_tournament_rake, by metadata.user_id or spread across the
     field. Awarding here as well credited every spin twice (2026-09-07). */
  IF COALESCE(NEW.is_tournament, false) OR NEW.tournament_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.player_contributions IS NULL OR jsonb_typeof(NEW.player_contributions) <> 'object'
     OR COALESCE(NEW.rake_amount, 0) <= 0 THEN
    RETURN NEW;
  END IF;

  /* RAKE PAID IS RAKE EARNED (20260831100610): the credit is the player's
     share of NEW.rake_amount under the hand's own method, from the one
     allocator. Never the raw contribution - that is a pot figure, not rake. */
  FOR rec IN
    SELECT a.user_id, a.credit
      FROM public.fn_allocate_rake_credits(
             NEW.rake_amount, NEW.player_contributions,
             COALESCE(NEW.rake_method, 'DEALT_EQUAL')) a
  LOOP
    BEGIN
      PERFORM public.fn_award_vip_credit(rec.user_id, rec.credit, 'rake', NEW.id, 'Rake generated');
    EXCEPTION WHEN others THEN
      -- The rake is banked whether or not the points land; the ledger row
      -- is the audit and a warning is the trace.
      RAISE WARNING 'fn_award_vip_points_from_rake: % for user % on %', SQLERRM, rec.user_id, NEW.id;
    END;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_award_vip_points_from_rake() OWNER TO postgres;

--
-- Name: fn_backfill_bomb_multi_winner_units(integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_backfill_bomb_multi_winner_units(p_limit integer DEFAULT 500, p_dry_run boolean DEFAULT true) RETURNS TABLE(hands_considered bigint, hands_written bigint, units_written bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_hands bigint := 0;
  v_units bigint := 0;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS zz_bomb_multi (
    hand_history_id uuid, table_id uuid, hand_number bigint,
    pot_index integer, board smallint, side text,
    user_id uuid, amount numeric, hand_name text
  ) ON COMMIT DROP;
  DELETE FROM zz_bomb_multi;

  WITH candidates AS (
    SELECT h.id, h.table_id, h.hand_number, h.winners,
           round(COALESCE(h.pot_size,0) - COALESCE(h.rake_amount,0) - COALESCE(h.bbj_amount,0), 2) AS net_winnings
    FROM public.hand_history h
    WHERE h.bomb_pot IS NOT NULL
      AND jsonb_array_length(COALESCE(h.winners,'[]'::jsonb)) > 1
      AND COALESCE(h.pot_size,0) > 0
      AND NOT EXISTS (SELECT 1 FROM public.bomb_pot_award_units a WHERE a.hand_history_id = h.id)
    ORDER BY h.created_at
    LIMIT GREATEST(p_limit, 0)
  ),
  exploded AS (
    SELECT c.id, c.table_id, c.hand_number, c.net_winnings,
           (w.value ->> 'userId')::uuid                       AS user_id,
           COALESCE((w.value ->> 'potIndex')::int, 0)         AS pot_index,
           (w.value ->> 'amount')::numeric                    AS amount,
           w.value -> 'hand' ->> 'name'                       AS hand_name,
           row_number() OVER (PARTITION BY c.id, COALESCE((w.value ->> 'potIndex')::int,0)
                              ORDER BY w.ordinality)          AS board_no
    FROM candidates c
    CROSS JOIN LATERAL jsonb_array_elements(c.winners) WITH ORDINALITY AS w(value, ordinality)
    WHERE (w.value ->> 'userId') IS NOT NULL
      AND (w.value ->> 'amount') IS NOT NULL
  ),
  -- Only repair hands whose winner amounts reconstruct the net pot exactly.
  -- A hand that does not add up is a DIFFERENT defect and must stay visible.
  exact AS (
    SELECT e.*
    FROM exploded e
    JOIN (
      SELECT id, net_winnings, round(SUM(amount),2) AS winners_sum
      FROM exploded GROUP BY id, net_winnings
    ) s ON s.id = e.id AND s.winners_sum = e.net_winnings
  )
  INSERT INTO zz_bomb_multi
  SELECT e.id, e.table_id, e.hand_number, e.pot_index, e.board_no::smallint,
         'high', e.user_id, e.amount, e.hand_name
  FROM exact e
  WHERE e.amount > 0;

  SELECT count(DISTINCT hand_history_id), count(*) INTO v_hands, v_units FROM zz_bomb_multi;

  IF NOT p_dry_run THEN
    INSERT INTO public.bomb_pot_award_units
      (hand_history_id, table_id, hand_number, pot_index, board, side, user_id, amount, hand_name)
    SELECT hand_history_id, table_id, hand_number, pot_index, board, side, user_id, amount, hand_name
    FROM zz_bomb_multi
    ON CONFLICT (hand_history_id, pot_index, board, side, user_id) DO NOTHING;
  END IF;

  hands_considered := v_hands;
  hands_written    := v_hands;
  units_written    := v_units;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_backfill_bomb_multi_winner_units(p_limit integer, p_dry_run boolean) OWNER TO postgres;

--
-- Name: FUNCTION fn_backfill_bomb_multi_winner_units(p_limit integer, p_dry_run boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_backfill_bomb_multi_winner_units(p_limit integer, p_dry_run boolean) IS 'Repairs bomb_pot_award_units for MULTI-winner bomb pots, which fn_backfill_bomb_pot_award_units excludes via its jsonb_array_length(winners)=1 filter. Uses the per-winner amounts already recorded in hand_history.winners, and only repairs hands whose winner amounts sum exactly to the net pot.';


--
-- Name: fn_backfill_bomb_pot_award_units(integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_backfill_bomb_pot_award_units(p_limit integer DEFAULT 1000, p_dry_run boolean DEFAULT true) RETURNS TABLE(hands_considered bigint, hands_written bigint, units_written bigint, hands_skipped bigint, skip_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_considered bigint := 0;
  v_written    bigint := 0;
  v_units      bigint := 0;
  v_skipped    bigint := 0;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS zz_backfill_units (
    hand_history_id uuid,
    table_id        uuid,
    hand_number     bigint,
    pot_index       integer,
    board           smallint,
    side            text,
    user_id         uuid,
    amount          numeric,
    hand_name       text
  ) ON COMMIT DROP;
  delete from zz_backfill_units where true;

  WITH candidates AS (
    SELECT
      h.id, h.table_id, h.hand_number,
      h.winners -> 0 ->> 'userId' AS winner_id,
      h.winners -> 0 -> 'hand' ->> 'name' AS hand_name,
      1
        + (CASE WHEN COALESCE(array_length(h.community_cards2, 1), 0) = 5 THEN 1 ELSE 0 END)
        + (CASE WHEN COALESCE(array_length(h.community_cards3, 1), 0) = 5 THEN 1 ELSE 0 END)
        AS boards,
      COALESCE(
        NULLIF(h.pots, 'null'::jsonb),
        jsonb_build_array(jsonb_build_object('index', 0, 'amount', h.pot_size))
      ) AS pots,
      round(COALESCE(h.pot_size, 0) - COALESCE(h.rake_amount, 0) - COALESCE(h.bbj_amount, 0), 2)
        AS net_winnings,
      COALESCE(h.pot_size, 0) AS gross_pot
    FROM public.hand_history h
    WHERE h.bomb_pot IS NOT NULL
      AND jsonb_array_length(COALESCE(h.winners, '[]'::jsonb)) = 1
      AND h.winners -> 0 ->> 'userId' IS NOT NULL
      AND COALESCE(h.pot_size, 0) > 0
      AND NOT EXISTS (
        SELECT 1 FROM public.bomb_pot_award_units a WHERE a.hand_history_id = h.id
      )
    ORDER BY h.created_at
    LIMIT GREATEST(p_limit, 0)
  ),
  shares AS (
    SELECT
      c.*,
      (p.value ->> 'index')::int AS pot_index,
      b.board_no,
      (
        (round((p.value ->> 'amount')::numeric * 100)::bigint / c.boards)
        + CASE
            WHEN b.board_no <= (round((p.value ->> 'amount')::numeric * 100)::bigint % c.boards)
            THEN 1 ELSE 0
          END
      ) AS share_cents
    FROM candidates c
    CROSS JOIN LATERAL jsonb_array_elements(c.pots) p
    CROSS JOIN LATERAL generate_series(1, c.boards) AS b(board_no)
  ),
  scaled AS (
    SELECT
      s.*,
      round(s.share_cents * (s.net_winnings / NULLIF(s.gross_pot, 0))) AS scaled_cents
    FROM shares s
  ),
  repaired AS (
    SELECT
      sc.*,
      row_number() OVER (
        PARTITION BY sc.id ORDER BY sc.scaled_cents DESC, sc.pot_index, sc.board_no
      ) AS rn,
      round(sc.net_winnings * 100) - SUM(sc.scaled_cents) OVER (PARTITION BY sc.id) AS diff
    FROM scaled sc
  )
  INSERT INTO zz_backfill_units
  SELECT
    r.id, r.table_id, r.hand_number, r.pot_index, r.board_no::smallint,
    'high', r.winner_id::uuid,
    (r.scaled_cents + CASE WHEN r.rn = 1 THEN r.diff ELSE 0 END) / 100.0,
    r.hand_name
  FROM repaired r;

  SELECT count(DISTINCT hand_history_id), count(*)
    INTO v_written, v_units
  FROM zz_backfill_units;
  v_considered := v_written;

  DELETE FROM zz_backfill_units u
  WHERE EXISTS (
    SELECT 1 FROM zz_backfill_units z
    WHERE z.hand_history_id = u.hand_history_id AND z.amount <= 0
  );

  SELECT count(DISTINCT hand_history_id), count(*)
    INTO v_written, v_units
  FROM zz_backfill_units;
  v_skipped := v_considered - v_written;

  IF NOT p_dry_run THEN
    INSERT INTO public.bomb_pot_award_units
      (hand_history_id, table_id, hand_number, pot_index, board, side, user_id, amount, hand_name)
    SELECT hand_history_id, table_id, hand_number, pot_index, board, side, user_id, amount, hand_name
    FROM zz_backfill_units
    ON CONFLICT (hand_history_id, pot_index, board, side, user_id) DO NOTHING;
  END IF;

  hands_considered := v_considered;
  hands_written    := v_written;
  units_written    := v_units;
  hands_skipped    := v_skipped;
  skip_reason      := 'non-positive share after rake scaling';
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_backfill_bomb_pot_award_units(p_limit integer, p_dry_run boolean) OWNER TO postgres;

--
-- Name: FUNCTION fn_backfill_bomb_pot_award_units(p_limit integer, p_dry_run boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_backfill_bomb_pot_award_units(p_limit integer, p_dry_run boolean) IS 'Reconstructs bomb_pot_award_units for SINGLE-WINNER bomb hands only, from stored pots/boards/rake - arithmetic, never card evaluation. Multi-winner hands are deliberately left missing and visible in fn_bomb_pot_ledger_gaps.';


--
-- Name: fn_backfill_position_stats(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_backfill_position_stats(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; v_count int := 0;
BEGIN
  FOR v_id IN SELECT id FROM hand_history
              WHERE created_at >= p_from AND created_at < p_to
              ORDER BY created_at LOOP
    BEGIN
      PERFORM fn_process_hand_position_stats(v_id);
      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.fn_backfill_position_stats(p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_backfill_rake_attributions(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_backfill_rake_attributions(p_since timestamp with time zone DEFAULT (now() - '7 days'::interval)) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows integer := 0;
BEGIN
  INSERT INTO public.rake_attributions (
    hand_id, player_id, rake_amount, rake_record_id, table_id, club_id,
    gross_contribution, returned_uncalled, eligible_contribution,
    contribution_weight, weighted_rake_credit, bbj_attributed_contribution,
    rake_method
  )
  SELECT r.hand_id, a.user_id, a.credit, r.id, r.table_id, r.club_id,
         (r.player_contributions ->> a.user_id::text)::numeric
           + COALESCE((r.returned_uncalled ->> a.user_id::text)::numeric, 0),
         COALESCE((r.returned_uncalled ->> a.user_id::text)::numeric, 0),
         (r.player_contributions ->> a.user_id::text)::numeric,
         a.weight, a.credit, COALESCE(b.credit, 0),
         COALESCE(r.rake_method, 'DEALT_EQUAL')
    FROM public.rake_records r
    CROSS JOIN LATERAL public.fn_allocate_rake_credits(
      r.rake_amount, r.player_contributions, COALESCE(r.rake_method, 'DEALT_EQUAL')) a
    LEFT JOIN LATERAL public.fn_allocate_rake_credits(
      COALESCE(r.bbj_contribution, 0), r.player_contributions, COALESCE(r.rake_method, 'DEALT_EQUAL')) b
      ON b.user_id = a.user_id
   WHERE r.hand_id IS NOT NULL
     AND r.rake_amount > 0
     AND r.player_contributions IS NOT NULL
     AND jsonb_typeof(r.player_contributions) = 'object'
     AND r.created_at >= p_since
     AND EXISTS (SELECT 1 FROM public.hand_history hh WHERE hh.id = r.hand_id)
     AND NOT EXISTS (SELECT 1 FROM public.rake_attributions ra WHERE ra.hand_id = r.hand_id)
  ON CONFLICT (hand_id, player_id) DO NOTHING;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END $$;


ALTER FUNCTION public.fn_backfill_rake_attributions(p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_backfill_unranked_survivors(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_backfill_unranked_survivors(p_apply boolean DEFAULT false, p_limit integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r record; v_events integer := 0; v_ranked integer := 0;
  v_before integer; v_after integer;
BEGIN
  SELECT count(*) INTO v_before
    FROM public.tournaments t JOIN public.tournament_players tp ON tp.tournament_id = t.id
   WHERE t.status = 'COMPLETED' AND tp.position IS NULL;

  FOR r IN
    SELECT DISTINCT t.id
      FROM public.tournaments t JOIN public.tournament_players tp ON tp.tournament_id = t.id
     WHERE t.status = 'COMPLETED' AND tp.position IS NULL
     LIMIT GREATEST(p_limit, 1)
  LOOP
    v_events := v_events + 1;
    IF p_apply THEN
      -- Record who is about to be ranked, before they are, so the previous
      -- state is reconstructable from the row itself.
      INSERT INTO public.tournament_survivor_rank_backfill
        (tournament_id, user_id, new_position, new_status, chips_at_rank)
      SELECT r.id, tp.user_id, 0, 'pending', tp.chips
        FROM public.tournament_players tp
       WHERE tp.tournament_id = r.id AND tp.position IS NULL
      ON CONFLICT (tournament_id, user_id) DO NOTHING;

      v_ranked := v_ranked + COALESCE(public.fn_rank_survivors(r.id), 0);

      UPDATE public.tournament_survivor_rank_backfill b
         SET new_position = tp.position, new_status = tp.status
        FROM public.tournament_players tp
       WHERE tp.tournament_id = b.tournament_id AND tp.user_id = b.user_id
         AND b.tournament_id = r.id AND b.new_position = 0
         AND tp.position IS NOT NULL;
    END IF;
  END LOOP;

  SELECT count(*) INTO v_after
    FROM public.tournaments t JOIN public.tournament_players tp ON tp.tournament_id = t.id
   WHERE t.status = 'COMPLETED' AND tp.position IS NULL;

  -- Second measurement: the backlog must actually be smaller, not merely
  -- "processed". A pass that reports events touched and leaves the count
  -- unchanged is the failure mode this estate keeps rediscovering.
  RETURN jsonb_build_object('ok', true, 'applied', p_apply,
    'events', v_events, 'rows_ranked', v_ranked,
    'unranked_before', v_before, 'unranked_after', v_after);
END;
$$;


ALTER FUNCTION public.fn_backfill_unranked_survivors(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: fn_backfill_venue_slugs(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_backfill_venue_slugs() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_venue RECORD; v_base text; v_candidate text; v_n int; v_updated int := 0;
    v_reused int := 0;
BEGIN
    FOR v_venue IN 
        SELECT id, name, city, state FROM poker_venues
         WHERE slug IS NULL 
           AND COALESCE(is_active,true) AND NOT COALESCE(is_suppressed,false)
         ORDER BY id
    LOOP
        v_base := public.fn_generate_venue_slug(v_venue.name, v_venue.city, v_venue.state);
        v_candidate := v_base;
        v_n := 0;
        -- Collision resolve: try name, then name-city, then name-2, name-3, etc.
        WHILE EXISTS(SELECT 1 FROM poker_venues WHERE slug = v_candidate AND id <> v_venue.id) LOOP
            v_n := v_n + 1;
            IF v_n = 1 AND v_venue.city IS NOT NULL THEN
                v_candidate := v_base || '-' || lower(regexp_replace(v_venue.city, '[^a-z0-9]+', '-', 'g'));
                v_candidate := regexp_replace(v_candidate, '-{2,}', '-', 'g');
            ELSIF v_n = 2 AND v_venue.state IS NOT NULL THEN
                v_candidate := v_base || '-' || lower(v_venue.state);
            ELSE
                v_candidate := v_base || '-' || v_n::text;
            END IF;
            v_reused := v_reused + 1;
        END LOOP;
        UPDATE poker_venues SET slug = v_candidate WHERE id = v_venue.id;
        v_updated := v_updated + 1;
    END LOOP;
    RETURN jsonb_build_object('success', true, 'updated', v_updated, 'collision_resolutions', v_reused);
END;
$$;


ALTER FUNCTION public.fn_backfill_venue_slugs() OWNER TO postgres;

--
-- Name: FUNCTION fn_backfill_venue_slugs(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_backfill_venue_slugs() IS 'Phase 28/A: One-time backfill for venues missing slugs. Collision-safe.';


--
-- Name: fn_backpay_spin_unpaid_winners(boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_backpay_spin_unpaid_winners(p_apply boolean DEFAULT false, p_limit integer DEFAULT 200, p_since_hours integer DEFAULT 6) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r record; v_ok boolean;
  v_settle jsonb; v_settle_paid numeric; v_paid_so_far numeric;
  v_paid integer := 0; v_chips numeric := 0; v_skipped integer := 0;
  v_refused integer := 0;
  v_owed_before numeric; v_owed_after numeric;
  v_event record; v_ladder jsonb; v_recorded jsonb;
  v_drawn numeric; v_entitlement numeric; v_prior_owed numeric;
  v_contract_refused integer := 0; v_winner_complete integer := 0;
BEGIN
  create temp table if not exists _spin_unpaid_snapshot (
    tournament_id uuid,
    chips_short numeric,
    verdict text,
    seats_at_first bigint,
    ended_at timestamptz
  ) on commit drop;
  /* TRUNCATE, not DELETE: the safeupdate library preloaded on the
     authenticator role rejects a DELETE with no WHERE clause outright. */
  truncate _spin_unpaid_snapshot;

  insert into _spin_unpaid_snapshot
  select s.tournament_id, s.chips_short, s.verdict, s.seats_at_first, s.ended_at
    from public.fn_spin_unpaid_settlements(p_since_hours) s
   where s.chips_short > 0.01;

  select coalesce(sum(chips_short), 0) into v_owed_before
    from _spin_unpaid_snapshot;

  FOR r IN
    SELECT s.tournament_id, s.chips_short, s.verdict,
           (SELECT tp.user_id FROM public.tournament_players tp
             WHERE tp.tournament_id = s.tournament_id AND tp.position = 1
             LIMIT 1) AS winner
      FROM _spin_unpaid_snapshot s
     WHERE NOT EXISTS (SELECT 1 FROM public.spin_unpaid_backpay_log l
                        WHERE l.tournament_id = s.tournament_id)
     ORDER BY s.ended_at ASC NULLS LAST
     LIMIT GREATEST(p_limit, 1)
  LOOP
    IF r.winner IS NULL THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    -- A tournament-wide shortfall is not necessarily owed to first place.
    -- Use the recorded drawn ladder and reserve draw before naming a debt.
    -- The tournament lock is the same lock held by the settlement function.
    SELECT t.status, t.spin_multiplier, t.payout_structure
      INTO v_event FROM public.tournaments t
     WHERE t.id = r.tournament_id FOR UPDATE;
    v_ladder := NULL; v_recorded := NULL; v_entitlement := NULL;
    IF FOUND AND v_event.status = 'COMPLETED' THEN
      SELECT l.structure INTO v_ladder FROM public.spin_payout_ladder l
       WHERE l.multiplier = v_event.spin_multiplier;
      BEGIN
        v_recorded := v_event.payout_structure::jsonb;
      EXCEPTION WHEN invalid_text_representation THEN v_recorded := NULL;
      END;
      IF v_ladder IS NOT NULL AND v_recorded IS NOT DISTINCT FROM v_ladder THEN
        SELECT round(sum(-l.amount), 2) INTO v_drawn
          FROM public.spin_reserve_ledger l
         WHERE l.tournament_id = r.tournament_id AND l.kind = 'jackpot_draw';
        SELECT round(v_drawn * (e->>'percentage')::numeric / 100, 2)
          INTO v_entitlement FROM jsonb_array_elements(v_ladder) e
         WHERE (e->>'place')::integer = 1;
      END IF;
    END IF;
    SELECT o.amount_owed INTO v_prior_owed FROM public.tournament_obligations o
     WHERE o.tournament_id = r.tournament_id AND o.kind = 'place' AND o.place = 1;
    IF v_entitlement IS NULL OR v_entitlement <= 0
       OR v_entitlement::text IN ('NaN','Infinity','-Infinity')
       OR COALESCE(v_prior_owed, 0) > v_entitlement THEN
      v_contract_refused := v_contract_refused + 1;
      IF p_apply THEN
        PERFORM public.fn_raise_server_financial_alert(
          'critical', 'fn_backpay_spin_unpaid_winners',
          'Spin winner top-up requires reconciliation of the recorded payout contract',
          jsonb_build_object('kind','spin_winner_entitlement_unverified',
            'tournament_id',r.tournament_id,'winner_entitlement',v_entitlement,
            'recorded_owed',v_prior_owed,'tournament_shortfall',r.chips_short),
          r.tournament_id::text);
      END IF;
      CONTINUE;
    END IF;
    v_paid_so_far := public.fn_tournament_obligation_paid_so_far(r.tournament_id, 'place', 1, r.winner);
    IF v_paid_so_far >= v_entitlement THEN
      v_winner_complete := v_winner_complete + 1;
      CONTINUE;
    END IF;

    IF p_apply THEN
      /* ONE SETTLE PATH (Lane A3, 2026-09-02). The winner's place-1 obligation
         is capped at its share of the recorded reserve draw. A whole-event
         shortfall must not increase first place beyond that share. It pays
         that difference once, and a replay pays 0. A refusal (escrow_short,
         place paid to another user, payout frozen) is reported and NOT paid
         through any other path. */
      v_settle := public.fn_settle_tournament_obligation(
        r.tournament_id, 'place', 1, r.winner,
        LEAST(v_entitlement, round(v_paid_so_far + r.chips_short, 2)), 'spin_backpay',
        'Spin winner back-pay (prize drawn from the reserve but never credited)');
      v_ok := COALESCE((v_settle->>'ok')::boolean, false);
      v_settle_paid := round(COALESCE((v_settle->>'paid')::numeric, 0), 2);

      IF v_ok AND v_settle_paid > 0 THEN
        UPDATE public.tournament_players
           SET prize = round(COALESCE(prize, 0) + v_settle_paid, 2)
         WHERE tournament_id = r.tournament_id AND user_id = r.winner;

        INSERT INTO public.spin_unpaid_backpay_log
          (tournament_id, user_id, amount, verdict)
        VALUES (r.tournament_id, r.winner, v_settle_paid, r.verdict)
        ON CONFLICT (tournament_id) DO NOTHING;

        v_paid := v_paid + 1;
        v_chips := v_chips + v_settle_paid;
      ELSIF NOT v_ok THEN
        v_refused := v_refused + 1;
      END IF;
    ELSE
      v_paid := v_paid + 1;
      v_chips := v_chips + LEAST(r.chips_short, v_entitlement - v_paid_so_far);
    END IF;
  END LOOP;

  /* Second measurement, over the SAME window and genuinely re-read. The
     backlog itself must shrink; a count of rows processed proves nothing. */
  SELECT COALESCE(sum(chips_short), 0) INTO v_owed_after
    FROM public.fn_spin_unpaid_settlements(p_since_hours)
   WHERE chips_short > 0.01;

  RETURN jsonb_build_object('ok', true, 'applied', p_apply,
    'window_hours', p_since_hours,
    'winners_paid', v_paid, 'chips', round(v_chips, 2),
    'skipped_no_winner', v_skipped,
    'refused_by_obligation', v_refused,
    'refused_unverified_winner_contract', v_contract_refused,
    'skipped_winner_already_paid', v_winner_complete,
    'owed_before', round(v_owed_before, 2), 'owed_after', round(v_owed_after, 2),
    'money_path', 'fn_settle_tournament_obligation');
END;
$$;


ALTER FUNCTION public.fn_backpay_spin_unpaid_winners(p_apply boolean, p_limit integer, p_since_hours integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_backpay_spin_unpaid_winners(p_apply boolean, p_limit integer, p_since_hours integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_backpay_spin_unpaid_winners(p_apply boolean, p_limit integer, p_since_hours integer) IS 'Credits Spin winners whose prize left the reserve pool and reached no wallet. p_since_hours bounds the sweep: the recurring 10-minute repair uses a short window it can finish inside the 8s statement timeout, and an audit passes a large one. It read the unbounded view three times and timed out every call before 2026-08-31.';


--
-- Name: fn_backpay_tournament_rake_attribution(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_backpay_tournament_rake_attribution(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row record; v_att jsonb; v_msg text;
  v_users integer; v_members integer;
  v_paid integer := 0; v_chips numeric := 0; v_seen integer := 0;
  v_requeued integer := 0; v_errors integer := 0; v_left integer;
  v_retried integer := 0; v_stuck integer := 0;
BEGIN
  FOR v_row IN
    SELECT tournament_id, (attributed_users = -1) AS is_retry
      FROM public.tournament_rake_settlements
     WHERE amount > 0
       AND settled_at IS NOT NULL
       AND (
         attributed_users IS NULL
         OR (
           attributed_users = -1
           AND attribution_error ~* '(deadlock|serializ|lock timeout|statement timeout|canceling statement|could not obtain lock)'
         )
       )
     ORDER BY settled_at ASC
     LIMIT GREATEST(p_limit, 1)
  LOOP
    v_seen := v_seen + 1;
    IF v_row.is_retry THEN v_retried := v_retried + 1; END IF;
    BEGIN
      v_att := public.fn_attribute_tournament_rake(v_row.tournament_id);
      v_users   := COALESCE((v_att->>'attributed_users')::int, 0);
      v_members := COALESCE((v_att->>'members')::int, 0);

      UPDATE public.tournament_rake_settlements
         SET attributed_users = v_users,
             attributed_at = CASE WHEN v_users = 0 AND v_members > 0
                                  THEN NULL ELSE COALESCE(attributed_at, now()) END,
             attribution_error = CASE WHEN v_users = 0 AND v_members > 0
                                      THEN 'attributed_nobody' ELSE NULL END
       WHERE tournament_id = v_row.tournament_id;

      IF v_users > 0 THEN
        v_paid  := v_paid + 1;
        v_chips := v_chips + COALESCE((v_att->>'attributed_chips')::numeric, 0);
      ELSIF v_members > 0 THEN
        v_requeued := v_requeued + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT;
      UPDATE public.tournament_rake_settlements
         SET attributed_users = -1, attribution_error = v_msg
       WHERE tournament_id = v_row.tournament_id;
      v_errors := v_errors + 1;
    END;
  END LOOP;

  SELECT count(*) INTO v_left
    FROM public.tournament_rake_settlements
   WHERE attributed_users IS NULL AND amount > 0 AND settled_at IS NOT NULL;

  SELECT count(*) INTO v_stuck
    FROM public.tournament_rake_settlements
   WHERE attributed_users = -1 AND amount > 0 AND settled_at IS NOT NULL
     AND (attribution_error IS NULL
          OR attribution_error !~* '(deadlock|serializ|lock timeout|statement timeout|canceling statement|could not obtain lock)');

  RETURN jsonb_build_object('ok', true, 'scanned', v_seen, 'paid', v_paid,
    'chips', round(v_chips, 2), 'requeued', v_requeued, 'errors', v_errors,
    'retried', v_retried, 'remaining', v_left, 'needs_a_human', v_stuck);
END;
$$;


ALTER FUNCTION public.fn_backpay_tournament_rake_attribution(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_backpay_tournament_rake_attribution(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_backpay_tournament_rake_attribution(p_limit integer) IS 'Drains never-measured rake attribution, and re-attempts rows a transient lock failure stamped -1. A non-retryable -1 keeps its stamp and is reported as needs_a_human.';


--
-- Name: fn_backpay_unfinalised_bounty_pools(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_backpay_unfinalised_bounty_pools(p_apply boolean DEFAULT false, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r record; v_res jsonb;
  v_events integer := 0; v_paid numeric := 0;
  v_orphan integer := 0; v_orphan_chips numeric := 0; v_alerts integer := 0;
  v_refused integer := 0; v_refused_chips numeric := 0;
  v_state text; v_msg text;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  FOR r IN
    WITH scanned AS (
      SELECT t.id, t.name, t.club_id, t.ended_at,
             round(COALESCE(t.bounty_pool, 0), 2) AS pool,
             COALESCE((SELECT round(sum(w.amount), 2)
                         FROM public.wallet_transactions w
                        WHERE w.related_entity_id = t.id
                          AND w.type = 'credit'
                          AND w.category = 'bounty'), 0) AS wallet_bounty,
             (SELECT tp.user_id FROM public.tournament_players tp
               WHERE tp.tournament_id = t.id AND tp.status = 'winner'
               LIMIT 1) AS champion
        FROM public.tournaments t
       WHERE t.status = 'COMPLETED'
         AND COALESCE(t.bounty_pool, 0) > 0
    )
    SELECT * FROM scanned
     -- the unpaid test is part of the SCAN now, so the limit below caps how
     -- much work one run does instead of how far back it can look
     WHERE wallet_bounty + 0.01 < pool
     -- oldest debt first: a pool that has been owed longest is settled first,
     -- and can never be pushed out of reach by newer events completing
     ORDER BY ended_at ASC NULLS LAST
     LIMIT GREATEST(p_limit, 1)
  LOOP
    IF r.champion IS NULL THEN
      v_orphan := v_orphan + 1;
      v_orphan_chips := v_orphan_chips + (r.pool - r.wallet_bounty);
      PERFORM public.fn_raise_server_financial_alert(
        'warning', 'fn_backpay_unfinalised_bounty_pools',
        format('%s holds %s chips of unpaid bounty pool and has no champion recorded, so there is nobody to settle it to',
               COALESCE(r.name, r.id::text), round(r.pool - r.wallet_bounty, 2)),
        jsonb_build_object('kind','no_champion','tournament_id',r.id,
          'club_id',r.club_id,'bounty_pool',r.pool,'paid',r.wallet_bounty,
          'retained',round(r.pool - r.wallet_bounty, 2),
          'detail','no money was moved; a residual with no recipient is a question, not a payment'),
        r.id::text);
      v_alerts := v_alerts + 1;
      CONTINUE;
    END IF;

    IF p_apply THEN
      -- ONE POOL AT A TIME (2026-09-07). fn_finalize_bounty_pool RAISES when
      -- the one payer refuses (escrow_short and friends). That refusal is
      -- right and the payer has already raised its own critical alert; what
      -- must not happen is the refusal aborting THIS run and leaving every
      -- pool behind it unpaid. The block below is a savepoint: the refused
      -- pool's partial work rolls back, the rest of the run continues.
      BEGIN
        v_res := public.fn_finalize_bounty_pool(r.id, r.champion);
        IF COALESCE((v_res->>'ok')::boolean, false) THEN
          v_paid := v_paid + COALESCE((v_res->>'residual')::numeric, 0);
        END IF;
        v_events := v_events + 1;
      EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
        v_refused := v_refused + 1;
        v_refused_chips := v_refused_chips + (r.pool - r.wallet_bounty);
        PERFORM public.fn_raise_server_financial_alert(
          'critical', 'fn_backpay_unfinalised_bounty_pools',
          format('%s: bounty residual of %s chips could not be settled to the champion (%s); the sweep moved on to the next pool',
                 COALESCE(r.name, r.id::text), round(r.pool - r.wallet_bounty, 2), left(v_msg, 300)),
          jsonb_build_object('kind','refused','tournament_id',r.id,'club_id',r.club_id,
            'bounty_pool',r.pool,'paid',r.wallet_bounty,
            'residual',round(r.pool - r.wallet_bounty, 2),
            'sqlstate',v_state,'error',left(v_msg, 500),
            'detail','no money was moved for this pool; every pool behind it was still attempted'),
          'refused:' || r.id::text);
        v_alerts := v_alerts + 1;
      END;
    ELSE
      v_paid := v_paid + (r.pool - r.wallet_bounty);
      v_events := v_events + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'applied', p_apply,
    'events_settled', v_events, 'chips_settled', round(v_paid, 2),
    'events_refused', v_refused, 'chips_refused', round(v_refused_chips, 2),
    'events_without_a_champion', v_orphan,
    'chips_without_a_champion', round(v_orphan_chips, 2),
    'alerts_raised', v_alerts);
END;
$$;


ALTER FUNCTION public.fn_backpay_unfinalised_bounty_pools(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_backpay_unfinalised_bounty_pools(p_apply boolean, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_backpay_unfinalised_bounty_pools(p_apply boolean, p_limit integer) IS 'Hourly sweep (ca-bounty-backpay-hourly): settles every completed tournament whose bounty pool is still owed to its champion, oldest first, through fn_finalize_bounty_pool. A pool the one payer refuses is reported (once per tournament) and skipped so the pools behind it are still paid.';


--
-- Name: fn_batch_active_player_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_active_player_counts(p_club_ids uuid[]) RETURNS TABLE(club_id uuid, active_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with live as (
    select
      ts.user_id,
      -- ONE club per seated player. This is the whole fix.
      coalesce(ts.club_id, t.club_id) as at_club,
      t.union_id                      as at_union
    from table_seats ts
    join tables t
      on t.id = ts.table_id
     and lower(coalesce(t.status, '')) not in ('closed', 'completed', 'cancelled', 'finished')
    where ts.left_at is null
      and coalesce(ts.is_away, false) = false
  )
  select
    c.id as club_id,
    count(distinct l.user_id) as active_count
  from clubs c
  join live l
    on case
         when coalesce(c.is_union, false)
           -- Union: its own tables, plus every member club's tables.
           then l.at_union = c.id
                or l.at_club = c.id
                or l.at_club in (select mc.id from clubs mc where mc.union_id = c.id)
           -- Club: only the players actually representing it right now.
           else l.at_club = c.id
       end
  where c.id = any(p_club_ids)
  group by c.id;
$$;


ALTER FUNCTION public.fn_batch_active_player_counts(p_club_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_batch_club_member_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_club_member_counts(p_club_ids uuid[]) RETURNS TABLE(club_id uuid, member_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT cm.club_id, COUNT(*) AS member_count
  FROM club_members cm
  WHERE cm.club_id = ANY(p_club_ids)
    AND (cm.status IS NULL OR cm.status IN ('active', 'approved'))
  GROUP BY cm.club_id;
$$;


ALTER FUNCTION public.fn_batch_club_member_counts(p_club_ids uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION fn_batch_club_member_counts(p_club_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_batch_club_member_counts(p_club_ids uuid[]) IS 'Live member counts for club cards. SECURITY DEFINER on purpose: under RLS a plain player could only count their own row and saw "1" on every club (2026-08-23). The same counts are already public via clubs.member_count.';


--
-- Name: fn_batch_club_realtime_active_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_club_realtime_active_counts(p_club_ids uuid[]) RETURNS TABLE(club_id uuid, active_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT requested.club_id,
         count(DISTINCT ts.user_id) FILTER (WHERE t.id IS NOT NULL)::bigint
    FROM unnest(p_club_ids) requested(club_id)
    -- The club's own row, for the union it belongs to (if any).
    LEFT JOIN public.clubs cl ON cl.id = requested.club_id
    LEFT JOIN public.club_members cm ON cm.club_id = requested.club_id
      AND (cm.status IS NULL OR cm.status IN ('active', 'approved'))
    LEFT JOIN public.table_seats ts ON ts.user_id = cm.user_id
      AND ts.left_at IS NULL AND COALESCE(ts.is_away, false) = false
    LEFT JOIN public.tables t ON t.id = ts.table_id
      -- THE CLUB'S FLOOR, not just the club's own tables. A member club of a
      -- union plays on tables stamped with the UNION's id; requiring
      -- t.club_id = requested.club_id reported 0 active players at Shark Club
      -- and Club JAQK while 475 and 471 of their members were seated.
      AND (
        t.club_id = requested.club_id
        OR (cl.union_id IS NOT NULL AND t.union_id = cl.union_id)
      )
      AND lower(COALESCE(t.status, '')) NOT IN ('closed','completed','cancelled','finished')
   GROUP BY requested.club_id;
$$;


ALTER FUNCTION public.fn_batch_club_realtime_active_counts(p_club_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_batch_club_realtime_member_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_club_realtime_member_counts(p_club_ids uuid[]) RETURNS TABLE(club_id uuid, member_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT requested.club_id, count(cm.user_id)::bigint
    FROM unnest(p_club_ids) requested(club_id)
    LEFT JOIN public.club_members cm ON cm.club_id = requested.club_id
      AND (cm.status IS NULL OR cm.status IN ('active', 'approved'))
   GROUP BY requested.club_id;
$$;


ALTER FUNCTION public.fn_batch_club_realtime_member_counts(p_club_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_batch_union_realtime_active_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_union_realtime_active_counts(p_union_ids uuid[]) RETURNS TABLE(union_id uuid, active_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH member_clubs AS (
    SELECT uc.union_id, uc.club_id
      FROM public.union_clubs uc
     WHERE uc.union_id = ANY(p_union_ids)
  ),
  per_club AS (
    SELECT a.club_id, a.active_count
      FROM public.fn_batch_club_realtime_active_counts(
             (SELECT coalesce(array_agg(DISTINCT mc.club_id), '{}'::uuid[]) FROM member_clubs mc)
           ) a
  )
  SELECT requested.union_id,
         coalesce(sum(pc.active_count), 0)::bigint AS active_count
    FROM unnest(p_union_ids) requested(union_id)
    LEFT JOIN member_clubs mc ON mc.union_id = requested.union_id
    LEFT JOIN per_club pc ON pc.club_id = mc.club_id
   GROUP BY requested.union_id;
$$;


ALTER FUNCTION public.fn_batch_union_realtime_active_counts(p_union_ids uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION fn_batch_union_realtime_active_counts(p_union_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_batch_union_realtime_active_counts(p_union_ids uuid[]) IS 'Sum of each member club''s active-player count (fn_batch_club_realtime_active_counts) over union_clubs. Matches the union member count basis: a player in two clubs is two active players. Returns a row per requested union, zero included.';


--
-- Name: fn_batch_union_realtime_member_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_union_realtime_member_counts(p_union_ids uuid[]) RETURNS TABLE(union_id uuid, member_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT requested.union_id, count(cm.user_id)::bigint
    FROM unnest(p_union_ids) requested(union_id)
    LEFT JOIN public.union_clubs uc ON uc.union_id = requested.union_id
    LEFT JOIN public.club_members cm ON cm.club_id = uc.club_id
      AND (cm.status IS NULL OR cm.status IN ('active', 'approved'))
   GROUP BY requested.union_id;
$$;


