--
-- Name: fn_bbj_allocate(numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_allocate(p_amount numeric, p_main_balance numeric) RETURNS TABLE(main_portion numeric, backup_portion numeric, promo_portion numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pol public.ca_bbj_policy%ROWTYPE;
  v_rm numeric; v_rb numeric; v_amt numeric := round(COALESCE(p_amount, 0), 2);
BEGIN
  SELECT * INTO v_pol FROM public.ca_bbj_policy WHERE id = 1;
  IF COALESCE(p_main_balance, 0) >= v_pol.pivot_threshold THEN
    v_rm := v_pol.pivot_main; v_rb := v_pol.pivot_backup;
  ELSE
    v_rm := v_pol.standard_main; v_rb := v_pol.standard_backup;
  END IF;
  main_portion   := round(v_amt * v_rm, 2);
  backup_portion := round(v_amt * v_rb, 2);
  -- Promo takes the remainder, so the three always re-sum to the drop.
  promo_portion  := round(v_amt - main_portion - backup_portion, 2);
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_bbj_allocate(p_amount numeric, p_main_balance numeric) OWNER TO postgres;

--
-- Name: fn_bbj_allocate(numeric, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_allocate(p_amount numeric, p_main_balance numeric, p_pool_id uuid) RETURNS TABLE(main_portion numeric, backup_portion numeric, promo_portion numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pol public.ca_bbj_policy%ROWTYPE;
  v_rm numeric; v_rb numeric; v_amt numeric := round(COALESCE(p_amount, 0), 2);
  v_state public.ca_bbj_alloc_state%ROWTYPE;
  v_exact_m numeric; v_exact_b numeric;
BEGIN
  SELECT * INTO v_pol FROM public.ca_bbj_policy WHERE id = 1;
  IF COALESCE(p_main_balance, 0) >= v_pol.pivot_threshold THEN
    v_rm := v_pol.pivot_main; v_rb := v_pol.pivot_backup;
  ELSE
    v_rm := v_pol.standard_main; v_rb := v_pol.standard_backup;
  END IF;

  IF p_pool_id IS NULL THEN
    main_portion   := round(v_amt * v_rm, 2);
    backup_portion := round(v_amt * v_rb, 2);
    promo_portion  := round(v_amt - main_portion - backup_portion, 2);
    RETURN NEXT;
    RETURN;
  END IF;

  INSERT INTO public.ca_bbj_alloc_state (pool_id) VALUES (p_pool_id) ON CONFLICT (pool_id) DO NOTHING;
  SELECT * INTO v_state FROM public.ca_bbj_alloc_state WHERE pool_id = p_pool_id FOR UPDATE;

  v_exact_m := v_amt * v_rm + v_state.main_residue;
  v_exact_b := v_amt * v_rb + v_state.backup_residue;
  main_portion   := round(v_exact_m, 2);
  backup_portion := round(v_exact_b, 2);
  -- A bank cannot be asked for more than the drop, nor less than nothing.
  main_portion   := LEAST(GREATEST(main_portion, 0), v_amt);
  backup_portion := LEAST(GREATEST(backup_portion, 0), v_amt - main_portion);
  promo_portion  := round(v_amt - main_portion - backup_portion, 2);

  UPDATE public.ca_bbj_alloc_state
     SET main_residue   = round(v_exact_m - main_portion, 6),
         backup_residue = round(v_exact_b - backup_portion, 6),
         updated_at     = now()
   WHERE pool_id = p_pool_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_bbj_allocate(p_amount numeric, p_main_balance numeric, p_pool_id uuid) OWNER TO postgres;

--
-- Name: fn_bbj_analytics(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_analytics(p_pool_id uuid) RETURNS TABLE(main_balance numeric, backup_balance numeric, promo_balance numeric, contributions_24h numeric, contributions_7d numeric, contributions_30d numeric, hands_24h bigint, hands_7d bigint, total_contributed_all_time numeric, hit_count bigint, total_paid_all_time numeric, biggest_hit numeric, last_hit_at timestamp with time zone, avg_days_between_hits numeric, days_since_last_hit numeric, net_pool_position numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club_id uuid;
  v_union_id uuid;
  v_allowed boolean := false;
BEGIN
  SELECT bp.club_id, bp.union_id INTO v_club_id, v_union_id
  FROM public.bbj_pools bp WHERE bp.id = p_pool_id;

  IF v_club_id IS NULL AND v_union_id IS NULL THEN
    RAISE EXCEPTION 'BBJ pool not found';
  END IF;

  -- Admin of the owning club, or of ANY club in the owning union.
  IF v_club_id IS NOT NULL THEN
    v_allowed := public.fn_is_club_admin_uid(v_club_id);
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public.clubs c
      WHERE c.union_id = v_union_id
        AND public.fn_is_club_admin_uid(c.id)
    ) INTO v_allowed;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Not authorized: club admin role required for this jackpot pool';
  END IF;

  RETURN QUERY
  WITH pool AS (
    SELECT bp.main_balance, bp.backup_balance, bp.promo_balance
    FROM public.bbj_pools bp WHERE bp.id = p_pool_id
  ),
  contrib AS (
    SELECT
      COALESCE(SUM(amount) FILTER (WHERE created_at > now() - interval '24 hours'), 0) AS c24,
      COALESCE(SUM(amount) FILTER (WHERE created_at > now() - interval '7 days'), 0) AS c7,
      COALESCE(SUM(amount) FILTER (WHERE created_at > now() - interval '30 days'), 0) AS c30,
      COUNT(*) FILTER (WHERE created_at > now() - interval '24 hours') AS h24,
      COUNT(*) FILTER (WHERE created_at > now() - interval '7 days') AS h7,
      COALESCE(SUM(amount), 0) AS call_time
    FROM public.bbj_contributions WHERE pool_id = p_pool_id
  ),
  hits AS (
    SELECT
      COUNT(*) AS n,
      COALESCE(SUM(total_payout), 0) AS paid,
      COALESCE(MAX(total_payout), 0) AS biggest,
      MAX(awarded_at) AS last_at,
      MIN(awarded_at) AS first_at
    FROM public.bbj_winners WHERE pool_id = p_pool_id
  )
  SELECT
    p.main_balance,
    p.backup_balance,
    p.promo_balance,
    c.c24,
    c.c7,
    c.c30,
    c.h24,
    c.h7,
    c.call_time,
    h.n,
    h.paid,
    h.biggest,
    h.last_at,
    -- Average interval between hits (needs 2+ hits to mean anything).
    CASE WHEN h.n > 1
      THEN ROUND(EXTRACT(EPOCH FROM (h.last_at - h.first_at)) / 86400.0 / (h.n - 1), 2)
      ELSE NULL END,
    CASE WHEN h.last_at IS NOT NULL
      THEN ROUND(EXTRACT(EPOCH FROM (now() - h.last_at)) / 86400.0, 2)
      ELSE NULL END,
    -- Net position: everything ever collected minus everything ever paid.
    ROUND(c.call_time - h.paid, 2)
  FROM pool p, contrib c, hits h;
END;
$$;


