COMMENT ON FUNCTION public.fn_bbj_claim_drill(p_table_id uuid, p_hand_number bigint) IS 'Consume a single armed Bad Beat Jackpot drill for one hand. Engine only (service_role). Atomic, so an arm fires exactly once. BBJ phase 4.1.';


--
-- Name: fn_bbj_conservation_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_conservation_check() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_in numeric; v_out numeric; v_bal numeric; v_gap numeric; v_base record;
  v_epoch_at timestamptz; v_epoch_unexp numeric; v_epoch_runs int;
  v_counters_paid numeric; v_payout_rows numeric; v_pre_table numeric;
  v_unrecorded_since numeric; v_seeds_live numeric;
  v_seeds numeric; v_drift numeric; v_unexplained numeric; v_tol numeric;
BEGIN
  v_in := fn_bbj_contributions_total();
  v_in := v_in + (SELECT COALESCE(SUM(amount),0) FROM union_wallet_transactions WHERE tx_type='bbj_fund');

  v_out := (SELECT COALESCE(SUM(total_amount),0) FROM bbj_payouts)
         + (SELECT COALESCE(SUM(amount),0) FROM union_wallet_transactions WHERE tx_type='bbj_promo_sweep')
         + (SELECT COALESCE(SUM(amount),0) FROM chip_transactions WHERE transaction_type='bbj_promo_sweep')
         + (SELECT COALESCE(SUM(amount),0) FROM wallet_transactions
             WHERE category='promotion' AND description='BBJ promo pool payout');

  SELECT COALESCE(SUM(main_balance+backup_balance+promo_balance),0) INTO v_bal FROM bbj_pools;

  v_gap := round(v_in - v_out - v_bal, 2);
  SELECT * INTO v_base FROM bbj_conservation_baseline WHERE id = 1;
  v_tol := COALESCE(v_base.tolerance, 1.00);
  v_drift := round(v_gap - COALESCE(v_base.baseline_gap, 0), 2);

  -- THE EPOCH (Phase 4.2): since the opening balances, the journal identity per
  -- pool per bank. This is what `healthy` means; the lifetime figures stay.
  SELECT min(taken_at) INTO v_epoch_at FROM public.ca_bbj_pool_snapshots WHERE is_baseline;
  SELECT COALESCE(sum(unexplained_main + unexplained_backup + unexplained_promo), 0), count(*)
    INTO v_epoch_unexp, v_epoch_runs
    FROM public.ca_bbj_pool_snapshots WHERE NOT is_baseline;

  /* THE LIFETIME DECOMPOSITION (phase 5.3). Two ledgers with different start
     dates, named rather than reported as a deficit.

     ROOT pools only: a merge folds the retired pool's counters into its
     destination, so summing every pool would count the club pool's 74,301.10
     twice. */
  SELECT COALESCE(sum(total_paid_out),0) INTO v_counters_paid
    FROM bbj_pools WHERE merged_into_pool_id IS NULL;
  SELECT COALESCE(sum(total_amount),0) INTO v_payout_rows FROM bbj_payouts;
  v_pre_table := round(v_counters_paid - v_payout_rows, 2);

  /* The historical figure is CLOSED at 71,749.31. Anything beyond it is a
     payout made since bbj_payouts existed that wrote no row - a live blind
     spot wearing a historical explanation's clothes. */
  v_unrecorded_since := round(v_pre_table - COALESCE(v_base.pre_ledger_payouts, 0), 2);

  /* Opening seeds pull the OTHER way: bank balance with no inflow row behind
     it. REMEMBERED, not read from bbj_pools.pool_amount - four functions can
     write that column, so deriving from it would let any of them move a money
     verdict, and would silently absorb a new seed the way the pre-ledger
     bucket would have absorbed a new unrecorded payout. The live column is
     reported beside it so a divergence is visible rather than load-bearing. */
  v_seeds := COALESCE(v_base.opening_seeds, 0);
  SELECT COALESCE(sum(pool_amount),0) INTO v_seeds_live FROM bbj_pools;

  v_unexplained := round(v_drift - v_pre_table + v_seeds, 2);

  RETURN jsonb_build_object(
    'inflow', round(v_in,2), 'outflow', round(v_out,2), 'balances', round(v_bal,2),
    'gap', v_gap,
    'baseline_gap', COALESCE(v_base.baseline_gap, 0),
    'drift_from_baseline', v_drift,
    'tolerance', v_tol,
    'lifetime', jsonb_build_object(
      'drift_from_baseline', v_drift,
      'paid_before_the_payout_table', v_pre_table,
      'pre_ledger_payouts_known', COALESCE(v_base.pre_ledger_payouts, 0),
      'paid_without_a_payout_row_since', v_unrecorded_since,
      'opening_seeds_known', v_seeds,
      'legacy_pool_amount_live', round(v_seeds_live,2),
      'unexplained', v_unexplained,
      'known_residue', COALESCE(v_base.lifetime_residue, 0),
      'moved_since_resolution', round(v_unexplained - COALESCE(v_base.lifetime_residue,0), 2),
      'note', 'The gap is two ledgers with different start dates, not missing chips. bbj_contributions begins 2026-03-03; bbj_payouts begins 2026-07-22. The union pool paid forty jackpots in between (71,749.31), and bbj_pools.total_paid_out is the witness that was there. Against it, 1,000.00 of opening seed sits in a bank with no contribution row. Both are CLOSED historical figures. `paid_without_a_payout_row_since` and `moved_since_resolution` are the live signals; everything else here is memory.'),
    'lifetime_healthy',
          abs(v_unexplained - COALESCE(v_base.lifetime_residue, 0)) <= v_tol
      AND abs(v_unrecorded_since) <= 0.01,
    'epoch', jsonb_build_object(
      'opened_at', v_epoch_at,
      'snapshots', v_epoch_runs,
      'unexplained_since_opening', round(v_epoch_unexp, 2)),
    'healthy', v_epoch_at IS NOT NULL AND abs(v_epoch_unexp) <= v_tol);
END;
$$;


ALTER FUNCTION public.fn_bbj_conservation_check() OWNER TO postgres;

--
-- Name: fn_bbj_contributions_by_day(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_contributions_by_day(p_union_id uuid, p_days integer DEFAULT 30) RETURNS TABLE(day date, bbj numeric, main numeric, backup numeric, promo numeric, players bigint, player_hands bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT b.day,
         SUM(b.bbj_amount)::numeric,
         SUM(b.main_amount)::numeric,
         SUM(b.backup_amount)::numeric,
         SUM(b.promo_amount)::numeric,
         COUNT(DISTINCT b.user_id)::bigint,
         SUM(b.hands)::bigint
    FROM bbj_daily_user b
    JOIN fn_union_club_scope(p_union_id) s ON s.club_id = b.club_id
   WHERE public.fn_union_report_caller_ok(p_union_id)
     AND b.day >= (CURRENT_DATE - GREATEST(COALESCE(p_days, 30), 1))
   GROUP BY b.day
   ORDER BY b.day DESC;
$$;


ALTER FUNCTION public.fn_bbj_contributions_by_day(p_union_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: fn_bbj_contributions_total(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_contributions_total() RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_as_of timestamptz;
  v_total numeric;
  v_tail  numeric;
BEGIN
  SELECT c.as_of, c.total INTO v_as_of, v_total
    FROM money_flow_checkpoint c WHERE c.metric_key = 'bbj_contributions_inflow';
  IF NOT FOUND THEN
    v_as_of := '-infinity'::timestamptz; v_total := 0;
  END IF;

  SELECT COALESCE(SUM(b.amount), 0) INTO v_tail
    FROM bbj_contributions b WHERE b.created_at >= v_as_of;

  RETURN v_total + v_tail;
END;
$$;


ALTER FUNCTION public.fn_bbj_contributions_total() OWNER TO postgres;

--
-- Name: fn_bbj_contributions_total_advance(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_contributions_total_advance() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key    text := 'bbj_contributions_inflow';
  v_as_of  timestamptz;
  v_total  numeric;
  v_rows   bigint;
  v_target timestamptz := now() - interval '1 hour';
  d_total  numeric;
  d_rows   bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('money_flow_cp:' || v_key, 42));

  SELECT c.as_of, c.total, c.rows_seen INTO v_as_of, v_total, v_rows
    FROM money_flow_checkpoint c WHERE c.metric_key = v_key;
  IF NOT FOUND THEN
    v_as_of := '-infinity'::timestamptz; v_total := 0; v_rows := 0;
  END IF;

  IF v_target <= v_as_of THEN
    RETURN;
  END IF;

  SELECT COALESCE(SUM(b.amount), 0), COUNT(*)
    INTO d_total, d_rows
    FROM bbj_contributions b
   WHERE b.created_at >= v_as_of AND b.created_at < v_target;

  INSERT INTO money_flow_checkpoint
        (metric_key, as_of, total, rows_seen, last_verified_at, updated_at)
  VALUES (v_key, v_target, v_total + d_total, v_rows + d_rows, now(), now())
  ON CONFLICT (metric_key) DO UPDATE
    SET as_of      = EXCLUDED.as_of,
        total      = EXCLUDED.total,
        rows_seen  = EXCLUDED.rows_seen,
        updated_at = now();
END;
$$;


ALTER FUNCTION public.fn_bbj_contributions_total_advance() OWNER TO postgres;

--
-- Name: fn_bbj_contributions_total_verify(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_contributions_total_verify() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key      text := 'bbj_contributions_inflow';
  v_target   timestamptz := now() - interval '1 hour';
  v_total    numeric; v_rows bigint;
  v_old      numeric; v_old_as_of timestamptz;
  v_tail     numeric; v_believed numeric; v_drift numeric;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('money_flow_cp:' || v_key, 42));

  SELECT c.total, c.as_of INTO v_old, v_old_as_of
    FROM money_flow_checkpoint c WHERE c.metric_key = v_key;

  SELECT COALESCE(SUM(b.amount), 0), COUNT(*) INTO v_total, v_rows
    FROM bbj_contributions b WHERE b.created_at < v_target;

  IF v_old_as_of IS NOT NULL THEN
    SELECT COALESCE(SUM(b.amount), 0) INTO v_tail
      FROM bbj_contributions b
     WHERE b.created_at >= v_old_as_of AND b.created_at < v_target;
    v_believed := v_old + v_tail;
    v_drift    := round(v_believed - v_total, 2);
  END IF;

  INSERT INTO money_flow_checkpoint
        (metric_key, as_of, total, rows_seen, last_verified_at, updated_at)
  VALUES (v_key, v_target, v_total, v_rows, now(), now())
  ON CONFLICT (metric_key) DO UPDATE
    SET as_of            = EXCLUDED.as_of,
        total            = EXCLUDED.total,
        rows_seen        = EXCLUDED.rows_seen,
        last_verified_at = now(),
        updated_at       = now();

  IF COALESCE(v_drift, 0) <> 0 THEN
    INSERT INTO financial_alerts (severity, source, message, context)
    SELECT 'critical', 'fn_bbj_contributions_total_verify',
           'BBJ contributions checkpoint drifted from recomputed truth',
           jsonb_build_object('metric_key', v_key, 'drift', v_drift,
                              'believed', v_believed, 'truth', v_total)
     WHERE NOT EXISTS (
       SELECT 1 FROM financial_alerts
        WHERE source = 'fn_bbj_contributions_total_verify'
          AND resolved IS NOT TRUE);
  END IF;

  RETURN jsonb_build_object('metric_key', v_key, 'as_of', v_target,
                            'total', v_total, 'rows_seen', v_rows,
                            'drift', COALESCE(v_drift, 0));
END;
$$;


ALTER FUNCTION public.fn_bbj_contributions_total_verify() OWNER TO postgres;

--
-- Name: fn_bbj_credited_report(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_credited_report(p_union_id uuid, p_days integer DEFAULT 7, p_limit integer DEFAULT 100) RETURNS TABLE(user_id uuid, username text, club_id uuid, club_name text, agent_id uuid, agent_name text, bbj_amount numeric, main_amount numeric, backup_amount numeric, promo_amount numeric, hands bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NOT public.fn_union_report_caller_ok(p_union_id) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH scope AS (
    SELECT uc.club_id AS cid FROM union_clubs uc WHERE uc.union_id = p_union_id
    UNION SELECT p_union_id
  ), agg AS (
    SELECT d.user_id, d.club_id,
           SUM(d.bbj_amount)    AS bbj,
           SUM(d.main_amount)   AS m,
           SUM(d.backup_amount) AS bk,
           SUM(d.promo_amount)  AS pr,
           SUM(d.hands)         AS h
      FROM bbj_daily_user d
      JOIN scope s ON s.cid = d.club_id
     WHERE d.day >= (now()::date - GREATEST(COALESCE(p_days, 7), 1))
     GROUP BY d.user_id, d.club_id
  )
  SELECT a.user_id,
         COALESCE(p.username, 'Player')::text,
         a.club_id,
         COALESCE(c.name, 'Club')::text,
         cm.agent_id,
         COALESCE(ap.username, NULL)::text,
         round(a.bbj, 2), round(a.m, 2), round(a.bk, 2), round(a.pr, 2),
         a.h::bigint
    FROM agg a
    LEFT JOIN profiles p  ON p.id = a.user_id
    LEFT JOIN clubs    c  ON c.id = a.club_id
    LEFT JOIN club_members cm ON cm.club_id = a.club_id AND cm.user_id = a.user_id
    LEFT JOIN profiles ap ON ap.id = cm.agent_id
   ORDER BY a.bbj DESC
   LIMIT GREATEST(COALESCE(p_limit, 100), 1);
END;
$$;


ALTER FUNCTION public.fn_bbj_credited_report(p_union_id uuid, p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: fn_bbj_drill_arms(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_drill_arms() RETURNS TABLE(id uuid, table_id uuid, club_id uuid, pool_id uuid, pool_balance_at_arm numeric, note text, armed_by uuid, armed_at timestamp with time zone, fired_at timestamp with time zone, fired_hand_number bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT a.id, a.table_id, a.club_id, a.pool_id, a.pool_balance_at_arm, a.note,
         a.armed_by, a.armed_at, a.fired_at, a.fired_hand_number
    FROM public.bbj_drill_arms a
   ORDER BY a.armed_at DESC
   LIMIT 100;
$$;


ALTER FUNCTION public.fn_bbj_drill_arms() OWNER TO postgres;

--
-- Name: FUNCTION fn_bbj_drill_arms(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_drill_arms() IS 'Every Bad Beat Jackpot drill armed, and whether it fired. Operator surface: service_role only. BBJ phase 4.1.';


--
-- Name: fn_bbj_gap_decomposition(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_gap_decomposition() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_check      jsonb;
    v_orphan     numeric := 0;
    v_orphan_pre numeric := 0;
    v_restored   numeric := 0;
BEGIN
    v_check := public.fn_bbj_conservation_check();

    SELECT COALESCE(sum(
             COALESCE(c.contributed,0)
           - COALESCE(p.paid,0)
           - COALESCE(s.swept,0)
           - COALESCE(b.main_balance,0)
           - COALESCE(b.backup_balance,0)
           - COALESCE(b.promo_balance,0)), 0)
      INTO v_orphan
      FROM bbj_pools b
      LEFT JOIN (SELECT pool_id, sum(amount) contributed FROM bbj_contributions GROUP BY 1) c
             ON c.pool_id = b.id
      LEFT JOIN (SELECT pool_id, sum(total_amount) paid FROM bbj_payouts GROUP BY 1) p
             ON p.pool_id = b.id
      LEFT JOIN (SELECT (SELECT COALESCE(sum(amount),0) FROM chip_transactions
                          WHERE transaction_type='bbj_promo_sweep') AS swept) s ON true
     WHERE b.merged_into_pool_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.bbj_pool_restorations r
                        WHERE r.source_pool_id = b.id);

    SELECT COALESCE(sum(bc.amount),0) INTO v_orphan_pre
      FROM bbj_contributions bc
     WHERE bc.main_portion IS NULL AND bc.backup_portion IS NULL AND bc.promo_portion IS NULL
       AND NOT EXISTS (SELECT 1 FROM public.bbj_pool_restorations r
                        WHERE r.source_pool_id = bc.pool_id);

    SELECT COALESCE(sum(amount),0) INTO v_restored FROM public.bbj_pool_restorations;

    RETURN jsonb_build_object(
        'measured_gap',        v_check -> 'gap',
        'baseline_gap',        v_check -> 'baseline_gap',
        'drift_from_baseline', v_check -> 'drift_from_baseline',
        'healthy',             v_check -> 'healthy',
        'restored_to_pools',   round(v_restored, 2),
        'explained', jsonb_build_object(
            'merged_pool_residual_erased', round(v_orphan, 2),
            'of_which_pre_triple_bank',    round(v_orphan_pre, 2),
            'note', 'Retired pools whose merged_into_pool_id is set were zeroed without the destination being credited. Pools listed in bbj_pool_restorations have had that residual paid back and are excluded.'),
        'remainder_unexplained',
            round(((v_check ->> 'gap')::numeric) - v_orphan, 2)
    );
END $$;


ALTER FUNCTION public.fn_bbj_gap_decomposition() OWNER TO postgres;

--
-- Name: fn_bbj_hand_detail(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_hand_detail(p_payout_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  WITH pay AS (SELECT * FROM public.bbj_payouts WHERE id = p_payout_id),
  hh AS (
    SELECT h.* FROM public.hand_history h
    JOIN pay ON h.table_id = pay.table_id AND h.hand_number = pay.hand_number
    ORDER BY h.created_at DESC LIMIT 1
  ),
  win AS (
    SELECT w.* FROM public.bbj_winners w
    JOIN pay ON w.table_id = pay.table_id AND w.hand_number = pay.hand_number
    LIMIT 1
  ),
  seats AS (
    SELECT e.value AS p FROM hh, LATERAL jsonb_array_elements(COALESCE(hh.players, '[]'::jsonb)) e
  ),
  players_out AS (
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'userId',       s.p->>'userId',
          'username',     COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), pr.username, s.p->>'username', 'Player'),
          'playerNumber', pr.player_number::text,
          -- The CLUB avatar. profiles.avatar_url is the social media photo and
          -- is not Club Arena's to display.
          'avatarUrl',    NULLIF(pr.arena_avatar_url, ''),
          'seat',         NULLIF(s.p->>'seat', '')::int,
          'stack',        NULLIF(s.p->>'stack', '')::numeric,
          'cards',        COALESCE((SELECT hh.hole_cards -> (s.p->>'userId') FROM hh), 'null'::jsonb)
        ) ORDER BY NULLIF(s.p->>'seat', '')::int), '[]'::jsonb) AS v
    FROM seats s LEFT JOIN public.profiles pr ON pr.id::text = s.p->>'userId'
  ),
  board_out AS (
    SELECT CASE
      WHEN (SELECT community_cards FROM hh) IS NULL THEN '[]'::jsonb
      ELSE COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
                 'rank', regexp_replace(c, '(hearts|diamonds|clubs|spades)$', ''),
                 'suit', substring(c from '(hearts|diamonds|clubs|spades)$')) ORDER BY ord)
        FROM unnest((SELECT community_cards FROM hh)) WITH ORDINALITY AS t(c, ord)
        WHERE substring(c from '(hearts|diamonds|clubs|spades)$') IS NOT NULL
      ), '[]'::jsonb)
    END AS v
  ),
  extra_boards AS (
    SELECT COALESCE(jsonb_agg(b ORDER BY ord), '[]'::jsonb) AS v
    FROM (
      SELECT e.value AS b, e.ordinality AS ord
      FROM hh, LATERAL jsonb_array_elements(COALESCE(hh.rit_boards, '[]'::jsonb))
                       WITH ORDINALITY e(value, ordinality)
      UNION ALL
      SELECT to_jsonb(hh.community_cards2), 1000
      FROM hh WHERE hh.community_cards2 IS NOT NULL
                AND array_length(hh.community_cards2, 1) > 0
    ) t
  ),
  recips AS (
    SELECT COALESCE(jsonb_agg(
             jsonb_build_object(
               'userId', r.user_id,
               'name',   COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), pr.username, 'Player'),
               -- The summary card has no seat roster to look a number up in,
               -- so it travels with the recipient.
               'playerNumber', pr.player_number::text,
               'amount', r.amount,
               'role',   CASE
                           WHEN r.user_id = (SELECT winner_user_id FROM pay) THEN 'bad_beat'
                           WHEN r.user_id = (SELECT loser_user_id  FROM pay) THEN 'hand_winner'
                           ELSE 'table'
                         END) ORDER BY r.amount DESC), '[]'::jsonb) AS v
    FROM public.bbj_payout_recipients r
    LEFT JOIN public.profiles pr ON pr.id = r.user_id
    WHERE r.payout_id = p_payout_id
  ),
  jackpot AS (
    SELECT jsonb_build_object(
             'payoutId',         p_payout_id,
             'total',            (SELECT total_amount FROM pay),
             'badBeatUserId',    (SELECT winner_user_id FROM pay),
             'handWinnerUserId', (SELECT loser_user_id FROM pay),
             'recipients',       (SELECT v FROM recips)) AS v
  )
  SELECT CASE
    -- No such payout. A genuine nothing, and still a NULL.
    WHEN (SELECT count(*) FROM pay) = 0 THEN NULL

    -- THE HAND IS GONE. Everything the payout ledger knows, and an honest flag
    -- saying the street-by-street part is not coming.
    WHEN (SELECT count(*) FROM hh) = 0 THEN jsonb_build_object(
      'handAvailable', false,
      'handNumber',    (SELECT hand_number FROM pay),
      'playedAt',      (SELECT created_at FROM pay),
      'gameVariant',   NULL,
      'tablePlayerCount', (SELECT table_player_count FROM pay),
      -- bbj_winners names the two hands. Note the deliberate inversion the
      -- rest of this feature lives with: in bbj_winners, "winner" is the
      -- winner OF THE JACKPOT (the bad-beat holder, who LOST the hand).
      'badBeatName',   (SELECT COALESCE(NULLIF(winner_display_name,''), 'Player') FROM win),
      'badBeatHand',   (SELECT NULLIF(winner_hand, 'Unknown') FROM win),
      'handWinnerName',(SELECT COALESCE(NULLIF(loser_display_name,''), 'Player') FROM win),
      'handWinnerHand',(SELECT NULLIF(loser_hand, 'Unknown') FROM win),
      'poolAtHit',     (SELECT pool_amount_at_hit FROM win),
      'jackpot',       (SELECT v FROM jackpot)
    )

    ELSE jsonb_build_object(
      'handAvailable', true,
      'handNumber',  (SELECT hand_number FROM hh),
      'playedAt',    COALESCE((SELECT started_at FROM hh), (SELECT created_at FROM hh)),
      'gameVariant', (SELECT game_variant FROM hh),
      'smallBlind',  (SELECT small_blind FROM hh),
      'bigBlind',    (SELECT big_blind FROM hh),
      'potSize',     (SELECT pot_size FROM hh),
      'rakeAmount',  (SELECT rake_amount FROM hh),
      'bbjAmount',   (SELECT bbj_amount FROM hh),
      'buttonSeat',  (SELECT button_seat FROM hh),
      'board',       (SELECT v FROM board_out),
      'extraBoards', (SELECT v FROM extra_boards),
      'players',     (SELECT v FROM players_out),
      'actions',     COALESCE((SELECT jsonb_agg(a ORDER BY ord)
                        FROM jsonb_array_elements((SELECT COALESCE(actions, '[]'::jsonb) FROM hh))
                             WITH ORDINALITY AS t(a, ord)
                        WHERE COALESCE(a->>'userId', '') <> 'system'), '[]'::jsonb),
      'winners',     (SELECT COALESCE(winners, '[]'::jsonb) FROM hh),
      'showdown',    (SELECT COALESCE(showdown, '[]'::jsonb) FROM hh),
      'pots',        (SELECT COALESCE(pots, '[]'::jsonb) FROM hh),
      'jackpot',     (SELECT v FROM jackpot)
    )
  END;
$_$;


ALTER FUNCTION public.fn_bbj_hand_detail(p_payout_id uuid) OWNER TO postgres;

--
-- Name: fn_bbj_ledger_delete_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_ledger_delete_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.bbj_ledger_deletions (source_table, row_data)
  VALUES (TG_TABLE_NAME, to_jsonb(OLD));
  -- One alert per statement would flood on a cascade; dedupe to one per table per hour.
  IF NOT EXISTS (
    SELECT 1 FROM public.financial_alerts
     WHERE source = 'bbj_ledger_delete_guard'
       AND context->>'table' = TG_TABLE_NAME
       AND created_at > now() - interval '1 hour') THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    VALUES ('critical', 'bbj_ledger_delete_guard',
      'A BBJ ledger row was deleted. The 2026-08 drift incident was exactly this. Review bbj_ledger_deletions.',
      jsonb_build_object('table', TG_TABLE_NAME, 'role', current_user,
                         'app', current_setting('application_name', true)));
  END IF;
  RETURN OLD;
END $$;


ALTER FUNCTION public.fn_bbj_ledger_delete_guard() OWNER TO postgres;

--
-- Name: fn_bbj_mini_payout(uuid, uuid, bigint, text, uuid, uuid, uuid[], uuid[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_mini_payout(p_pool_id uuid, p_table_id uuid, p_hand_number bigint, p_tier_id text, p_loser_user_id uuid, p_winner_user_id uuid, p_dealt_in_ids uuid[], p_seated_ids uuid[], p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(applied boolean, already_paid boolean, refused text, payout_id uuid, total_payout numeric, loser_share numeric, winner_share numeric, table_share numeric, per_player_share numeric, backup_after numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_backup numeric; v_floor numeric; v_amount numeric; v_enabled boolean;
  v_total numeric; v_loser numeric; v_winner numeric; v_table numeric; v_per numeric;
  v_payout_id uuid; v_existing uuid; v_table_ids uuid[]; v_n_table integer;
  v_club_id uuid; v_uid uuid; v_remainder numeric; v_hand_id uuid;
  v_loser_name text; v_winner_name text; v_pending record;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'fn_bbj_mini_payout is service only' USING ERRCODE = '42501';
  END IF;

  /* The same kill switch the main jackpot honours, and the same error class,
     so the engine's queue retries a mini frozen mid-flight exactly as it
     retries a main one. */
  IF EXISTS (SELECT 1 FROM public.ca_payout_freeze f
              WHERE f.scope = 'bbj_payouts' AND f.cleared_at IS NULL) THEN
    RAISE EXCEPTION 'payout_frozen: jackpot payouts are frozen by the kill switch (ca_payout_freeze scope bbj_payouts); the engine retries when it is cleared'
      USING ERRCODE = 'P0404';
  END IF;

  IF p_pool_id IS NULL OR p_table_id IS NULL OR p_hand_number IS NULL
     OR p_loser_user_id IS NULL OR p_winner_user_id IS NULL
     OR p_loser_user_id = p_winner_user_id THEN
    RAISE EXCEPTION 'mini jackpot requires a hand and two distinct recipients'
      USING ERRCODE = '22023';
  END IF;

  -- Serialize the decision before inspecting its idempotency record. A
  -- concurrent second caller must see the first caller's committed payout.
  SELECT COALESCE(backup_balance,0), COALESCE(mini_reserve_floor, 0), club_id
    INTO v_backup, v_floor, v_club_id
    FROM public.bbj_pools WHERE id = p_pool_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, false, 'pool_not_found'::text, NULL::uuid,
      0::numeric,0::numeric,0::numeric,0::numeric,0::numeric, 0::numeric;
    RETURN;
  END IF;

  /* IDEMPOTENT ON THE HAND, and it shares the key with the main jackpot on
     purpose: bbj_payouts_pool_table_hand_uidx means one hand can produce one
     payout of either kind and never both. A mini only ever runs when
     detectBBJHit refused the main, so the two cannot race for the same hand -
     and if that ever stops being true, this is where it stops, not a second
     row nobody reconciles. */
  SELECT id INTO v_existing FROM public.bbj_payouts
   WHERE pool_id = p_pool_id AND table_id = p_table_id AND hand_number = p_hand_number LIMIT 1;
  IF v_existing IS NOT NULL THEN
    SELECT bp.total_amount, bp.loser_share, bp.winner_share, bp.table_share, bp.table_player_count
      INTO v_total, v_loser, v_winner, v_table, v_n_table
      FROM public.bbj_payouts bp WHERE bp.id = v_existing;
    FOR v_pending IN SELECT u.user_id,u.amount FROM public.bbj_unclaimed_shares u
      WHERE u.payout_id=v_existing AND u.paid_at IS NULL ORDER BY u.user_id
    LOOP
      PERFORM public.bbj_credit_one_recipient(v_existing,p_table_id,v_pending.user_id,v_pending.amount,
        EXISTS(SELECT 1 FROM public.table_seats s WHERE s.table_id=p_table_id
          AND s.user_id=v_pending.user_id AND s.left_at IS NULL));
    END LOOP;
    SELECT COALESCE(backup_balance,0) INTO v_backup FROM public.bbj_pools WHERE id = p_pool_id;
    RETURN QUERY SELECT false, true, NULL::text, v_existing, v_total, v_loser, v_winner,
      v_table, CASE WHEN v_n_table > 0 THEN v_table / v_n_table ELSE 0::numeric END, v_backup;
    RETURN;
  END IF;

  SELECT amount, enabled INTO v_amount, v_enabled
    FROM public.bbj_mini_tiers WHERE tier_id = p_tier_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, false, 'no_mini_amount_for_tier'::text, NULL::uuid,
      0::numeric,0::numeric,0::numeric,0::numeric,0::numeric, 0::numeric;
    RETURN;
  END IF;
  IF NOT v_enabled THEN
    RETURN QUERY SELECT false, false, 'mini_disabled_for_tier'::text, NULL::uuid,
      0::numeric,0::numeric,0::numeric,0::numeric,0::numeric, 0::numeric;
    RETURN;
  END IF;

  /* THE FLOOR IS NOT NEGOTIABLE AND THE MINI IS NOT SHRUNK TO FIT.
     Paying a partial mini would publish one number to the player and pay
     another; a mini that cannot be paid in full is simply not owed. */
  IF v_backup - public.fn_bbj_parked_reserve(p_pool_id,'backup') - v_amount < v_floor THEN
    RETURN QUERY SELECT false, false, 'reserve_at_floor'::text, NULL::uuid,
      0::numeric,0::numeric,0::numeric,0::numeric,0::numeric, v_backup;
    RETURN;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_table_ids
    FROM unnest(COALESCE(p_dealt_in_ids, ARRAY[]::uuid[])) AS x
   WHERE x IS NOT NULL AND x <> p_loser_user_id AND x <> p_winner_user_id;
  v_n_table := COALESCE(array_length(v_table_ids, 1), 0);

  v_total  := round(v_amount, 2);
  v_loser  := round(v_total * 0.50, 2);
  v_winner := round(v_total * 0.25, 2);
  v_table  := round(v_total - v_loser - v_winner, 2);
  IF v_n_table > 0 THEN
    v_per := round(v_table / v_n_table, 2);
    -- Preserve the main jackpot's signed residual rule, BEFORE the loser is
    -- credited. A second credit is deduplicated; ignoring a negative residual
    -- creates chips. Persist the actual table allocation shown to clients.
    v_remainder := v_table - v_per * v_n_table;
    v_loser := v_loser + v_remainder;
    v_table := v_per * v_n_table;
  ELSE
    /* Nobody else was dealt in: the table quarter goes to the player who took
       the beat rather than staying in a bank nobody can see. */
    v_per := 0;
    v_loser := round(v_loser + v_table, 2);
    v_table := 0;
  END IF;

  IF v_loser < 0 OR v_winner < 0 OR v_table < 0
     OR v_loser + v_winner + v_table <> v_total THEN
    RAISE EXCEPTION 'mini jackpot allocation does not conserve its funded total';
  END IF;

  SELECT id INTO v_hand_id FROM public.hand_history
   WHERE table_id = p_table_id AND hand_number = p_hand_number
   ORDER BY created_at DESC LIMIT 1;

  PERFORM public.fn_ca_declare_ledger('bbj_payout', 'bbj_pool', p_pool_id, NULL,
            'bbj_mini:' || p_pool_id::text || ':' || p_table_id::text || ':' || p_hand_number::text, NULL);
  UPDATE public.bbj_pools
     SET backup_balance = GREATEST(0, COALESCE(backup_balance,0) - v_total),
         /* The pool's own paid-out counter moves with every payout of either
            kind. fn_bbj_conservation_check compares that counter against the
            bbj_payouts rows (phase 5.3); a mini that wrote a row and left the
            counter behind would take `paid_without_a_payout_row_since`
            negative and the lifetime verdict false. */
         total_paid_out = COALESCE(total_paid_out, 0) + v_total,
         updated_at = now()
   WHERE id = p_pool_id
   RETURNING COALESCE(backup_balance,0) INTO v_backup;
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_idempotency_key', '', true);

  INSERT INTO public.bbj_payouts
    (pool_id, hand_id, table_id, hand_number, winner_user_id, loser_user_id,
     total_amount, winner_share, loser_share, table_share, table_player_count, kind, metadata)
  VALUES (p_pool_id, v_hand_id, p_table_id, p_hand_number, p_winner_user_id, p_loser_user_id,
          v_total, v_winner, v_loser, v_table, v_n_table, 'mini',
          COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('tier_id', p_tier_id, 'funded_from', 'backup_reserve'))
  RETURNING id INTO v_payout_id;

  PERFORM public.bbj_credit_one_recipient(v_payout_id, p_table_id, p_loser_user_id, v_loser,
            p_loser_user_id = ANY(COALESCE(p_seated_ids, ARRAY[]::uuid[])));
  PERFORM public.bbj_credit_one_recipient(v_payout_id, p_table_id, p_winner_user_id, v_winner,
            p_winner_user_id = ANY(COALESCE(p_seated_ids, ARRAY[]::uuid[])));
  IF v_n_table > 0 AND v_per > 0 THEN
    FOREACH v_uid IN ARRAY v_table_ids LOOP
      PERFORM public.bbj_credit_one_recipient(v_payout_id, p_table_id, v_uid, v_per,
                v_uid = ANY(COALESCE(p_seated_ids, ARRAY[]::uuid[])));
    END LOOP;

  END IF;

  /* THE ARENA NAME, through the platform's own helper. The first cut of this
     function read `profiles.arena_name`, a column that does not exist, and a
     rolled-back probe (CLAUDE.md 11.5) found it before a single real hand
     could. fn_arena_name is what fn_bbj_recent_hits and the rest of the arena
     already use, and reusing it is why the mini ticker will show the same name
     the main one does. */
  SELECT COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                                       pr.first_name, pr.last_name, pr.full_name),
                  pr.username, 'Player')
    INTO v_loser_name FROM public.profiles pr WHERE pr.id = p_loser_user_id;
  SELECT COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                                       pr.first_name, pr.last_name, pr.full_name),
                  pr.username, 'Player')
    INTO v_winner_name FROM public.profiles pr WHERE pr.id = p_winner_user_id;

  INSERT INTO public.bbj_winners
    (club_id, pool_id, loser_id, winner_id, loser_payout, winner_payout,
     table_share_payout, total_payout, pool_amount_at_hit, stakes_tier,
     table_id, hand_number, awarded_at, winner_display_name, loser_display_name, kind)
  VALUES (v_club_id, p_pool_id, p_loser_user_id, p_winner_user_id, v_loser, v_winner,
          v_table, v_total, v_backup + v_total, p_tier_id,
          p_table_id, p_hand_number, now(), v_winner_name, v_loser_name, 'mini')
  ON CONFLICT (pool_id, table_id, hand_number) DO NOTHING;

  RETURN QUERY SELECT true, false, NULL::text, v_payout_id, v_total, v_loser, v_winner,
    v_table, v_per, v_backup;
END;
 $$;


ALTER FUNCTION public.fn_bbj_mini_payout(p_pool_id uuid, p_table_id uuid, p_hand_number bigint, p_tier_id text, p_loser_user_id uuid, p_winner_user_id uuid, p_dealt_in_ids uuid[], p_seated_ids uuid[], p_metadata jsonb) OWNER TO postgres;

--
-- Name: fn_bbj_move_between_banks(uuid, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_move_between_banks(p_pool_id uuid, p_from_bank text, p_to_bank text, p_amount numeric, p_reason text, p_op_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_amt numeric := round(COALESCE(p_amount, 0), 2);
  v_pool public.bbj_pools%ROWTYPE; v_have numeric; v_prior public.ca_bbj_bucket_moves%ROWTYPE;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'fn_bbj_move_between_banks is service only' USING ERRCODE = '42501';
  END IF;
  IF p_from_bank NOT IN ('main', 'backup', 'promo') OR p_to_bank NOT IN ('main', 'backup', 'promo') OR p_from_bank = p_to_bank THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'banks_must_be_two_of_main_backup_promo');
  END IF;
  IF v_amt <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive');
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 10 OR COALESCE(btrim(p_op_id), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'a_bank_move_needs_a_reason_and_an_op_id');
  END IF;
  SELECT * INTO v_pool FROM public.bbj_pools WHERE id = p_pool_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'pool_not_found');
  END IF;
  SELECT * INTO v_prior FROM public.ca_bbj_bucket_moves WHERE op_id = p_op_id;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'move_id', v_prior.id, 'amount', v_prior.amount);
  END IF;
  v_have := CASE p_from_bank WHEN 'main' THEN v_pool.main_balance WHEN 'backup' THEN v_pool.backup_balance ELSE v_pool.promo_balance END;
  v_have := v_have-public.fn_bbj_parked_reserve(p_pool_id,p_from_bank);
  IF COALESCE(v_have, 0) < v_amt THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'source_bank_cannot_cover_it', 'available', COALESCE(v_have, 0), 'requested', v_amt);
  END IF;
  -- Declared as bbj_pool -> bbj_pool: the chips change bank, not account. The
  -- autoledger writes one leg per bucket column with its label, which is what
  -- the per-bank reconcile reads.
  PERFORM public.fn_ca_declare_ledger('adjustment', 'bbj_pool', p_pool_id, NULL, NULL, NULL);
  UPDATE public.bbj_pools
     SET main_balance   = main_balance   + CASE WHEN p_to_bank = 'main'   THEN v_amt ELSE 0 END - CASE WHEN p_from_bank = 'main'   THEN v_amt ELSE 0 END,
         backup_balance = backup_balance + CASE WHEN p_to_bank = 'backup' THEN v_amt ELSE 0 END - CASE WHEN p_from_bank = 'backup' THEN v_amt ELSE 0 END,
         promo_balance  = promo_balance  + CASE WHEN p_to_bank = 'promo'  THEN v_amt ELSE 0 END - CASE WHEN p_from_bank = 'promo'  THEN v_amt ELSE 0 END,
         updated_at = now()
   WHERE id = p_pool_id;
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  INSERT INTO public.ca_bbj_bucket_moves (pool_id, from_bank, to_bank, amount, reason, op_id, performed_by)
  VALUES (p_pool_id, p_from_bank, p_to_bank, v_amt, btrim(p_reason), p_op_id, auth.uid())
  RETURNING * INTO v_prior;
  RETURN jsonb_build_object('ok', true, 'replayed', false, 'move_id', v_prior.id, 'amount', v_amt,
                            'from_bank', p_from_bank, 'to_bank', p_to_bank);
END;
$$;


ALTER FUNCTION public.fn_bbj_move_between_banks(p_pool_id uuid, p_from_bank text, p_to_bank text, p_amount numeric, p_reason text, p_op_id text) OWNER TO postgres;

--
-- Name: fn_bbj_my_contribution(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_my_contribution(p_pool_id uuid, p_days integer DEFAULT 90) RETURNS TABLE(attributed_chips numeric, hands_contributed bigint, days_covered integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_club_ids uuid[];
BEGIN
  IF v_uid IS NULL THEN
    RETURN QUERY SELECT 0::numeric, 0::bigint, p_days;
    RETURN;
  END IF;

  SELECT ARRAY(
    SELECT c.id FROM public.clubs c
    WHERE c.union_id = (SELECT bp.union_id FROM public.bbj_pools bp WHERE bp.id = p_pool_id)
       OR c.id = (SELECT bp.club_id FROM public.bbj_pools bp WHERE bp.id = p_pool_id)
  ) INTO v_club_ids;

  IF v_club_ids IS NULL OR array_length(v_club_ids, 1) IS NULL THEN
    RETURN QUERY SELECT 0::numeric, 0::bigint, p_days;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    ROUND(COALESCE(SUM(
      COALESCE(
        ra.bbj_attributed_contribution,
        rr.bbj_contribution
          * ((rr.player_contributions->>v_uid::text)::numeric)
          / NULLIF(rr.pot_size, 0)
      )
    ), 0), 2),
    COUNT(*)::bigint,
    p_days
  FROM public.rake_records rr
  LEFT JOIN public.rake_attributions ra
    ON ra.hand_id = rr.hand_id AND ra.player_id = v_uid
  WHERE rr.player_contributions ? v_uid::text
    AND rr.club_id = ANY(v_club_ids)
    AND COALESCE(rr.bbj_contribution, 0) > 0
    AND rr.created_at > now() - make_interval(days => p_days)
    AND COALESCE((rr.player_contributions->>v_uid::text)::numeric, 0) > 0;
END;
$$;


ALTER FUNCTION public.fn_bbj_my_contribution(p_pool_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_bbj_my_contribution(p_pool_id uuid, p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_my_contribution(p_pool_id uuid, p_days integer) IS 'A player''s honest attributed share of jackpot fees (fee * their pot share), for auth.uid() only. Replaces the dead player_id-based card that always read 0.';


--
-- Name: fn_bbj_notify_thresholds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_notify_thresholds() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_t              record;
  v_pool_id        uuid;
  v_balance        numeric;
  v_members        integer;
  v_crossings      integer := 0;
  v_notified       integer := 0;
  v_failed         integer := 0;
  v_crossing_id    uuid;
BEGIN
  FOR v_t IN
    SELECT th.id, th.club_id, th.amount, th.label
      FROM public.bbj_notify_thresholds th
     WHERE th.enabled
     ORDER BY th.club_id, th.amount
  LOOP
    v_pool_id := NULL;
    v_balance := NULL;
    SELECT p.pool_id, p.main_balance INTO v_pool_id, v_balance
      FROM public.fn_bbj_pool_for_club(v_t.club_id) p
     LIMIT 1;

    CONTINUE WHEN v_pool_id IS NULL;
    CONTINUE WHEN COALESCE(v_balance, 0) < v_t.amount;

    IF EXISTS (
      SELECT 1
        FROM public.bbj_threshold_crossings c
        LEFT JOIN public.bbj_pools bp ON bp.id = v_pool_id
       WHERE c.threshold_id = v_t.id
         AND c.crossed_at > COALESCE(bp.last_hit_at, '-infinity'::timestamptz)
    ) THEN
      CONTINUE;
    END IF;

    BEGIN
      INSERT INTO public.bbj_threshold_crossings
        (threshold_id, club_id, pool_id, threshold_amount, balance_at_cross)
      VALUES (v_t.id, v_t.club_id, v_pool_id, v_t.amount, v_balance)
      RETURNING id INTO v_crossing_id;

      /* EVERY ACTIVE MEMBER, HORSES INCLUDED (CLAUDE.md 10.5), IN USER_ID
         ORDER. The order is not cosmetic: each row takes a FOR KEY SHARE lock
         on its profile through the notifications FK, and an arbitrary order
         deadlocked against live traffic on the first probe. */
      WITH ordered AS (
        SELECT cm.user_id, c.name AS club_name
          FROM public.club_members cm
          JOIN public.clubs c ON c.id = cm.club_id
         WHERE cm.club_id = v_t.club_id
           AND cm.status = 'active'
         ORDER BY cm.user_id
      ), told AS (
        INSERT INTO public.notifications (user_id, type, title, message, metadata, read)
        SELECT o.user_id,
               'bonus',
               'The Bad Beat Jackpot Just Passed $' || trim(to_char(v_t.amount, 'FM999,999,999.00')),
               'The jackpot at ' || COALESCE(o.club_name, 'your club') || ' is now $' ||
                 trim(to_char(v_balance, 'FM999,999,999.00')) ||
                 '. Every raked hand adds to it, and it pays the table when it hits.',
               jsonb_build_object(
                 'clubId', v_t.club_id,
                 'poolId', v_pool_id,
                 'threshold', v_t.amount,
                 'balance', v_balance,
                 'crossingId', v_crossing_id,
                 'label', v_t.label
               ),
               false
          FROM ordered o
        RETURNING 1
      )
      SELECT count(*) INTO v_members FROM told;

      UPDATE public.bbj_threshold_crossings
         SET notified_count = COALESCE(v_members, 0)
       WHERE id = v_crossing_id;

      v_crossings := v_crossings + 1;
      v_notified  := v_notified + COALESCE(v_members, 0);
    EXCEPTION WHEN OTHERS THEN
      /* The crossing row rolls back with the fan-out, so the threshold stays
         ARMED and the next run tries again. Recording a crossing that told
         nobody would silence this club's jackpot for good. */
      v_failed := v_failed + 1;
      RAISE WARNING '[bbj-threshold] club % threshold % could not be announced: % (%). It stays armed.',
        v_t.club_id, v_t.amount, SQLERRM, SQLSTATE;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'crossings', v_crossings,
    'notified', v_notified,
    'failed', v_failed
  );
END $_$;


ALTER FUNCTION public.fn_bbj_notify_thresholds() OWNER TO postgres;

--
-- Name: FUNCTION fn_bbj_notify_thresholds(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_notify_thresholds() IS 'Tells every active member of a club when its Bad Beat Jackpot crosses a threshold the club set, once per crossing, re-arming when the jackpot is next hit. Fans out in user_id order because the notifications FK takes a per-profile lock and an arbitrary order deadlocked against live traffic. One club failing never costs the others theirs. Never runs on the money path. Operator surface: service_role only. BBJ phase 3.4.';


--
-- Name: ca_bbj_pool_snapshots; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_bbj_pool_snapshots (
    id bigint NOT NULL,
    pool_id uuid NOT NULL,
    taken_at timestamp with time zone DEFAULT now() NOT NULL,
    is_baseline boolean DEFAULT false NOT NULL,
    prev_id bigint,
    main numeric NOT NULL,
    backup numeric NOT NULL,
    promo numeric NOT NULL,
    journal_main numeric DEFAULT 0 NOT NULL,
    journal_backup numeric DEFAULT 0 NOT NULL,
    journal_promo numeric DEFAULT 0 NOT NULL,
    drops_since numeric DEFAULT 0 NOT NULL,
    payouts_since numeric DEFAULT 0 NOT NULL,
    sweeps_since numeric DEFAULT 0 NOT NULL,
    funding_since numeric DEFAULT 0 NOT NULL,
    moves_since numeric DEFAULT 0 NOT NULL,
    write_failures integer DEFAULT 0 NOT NULL,
    unexplained_main numeric DEFAULT 0 NOT NULL,
    unexplained_backup numeric DEFAULT 0 NOT NULL,
    unexplained_promo numeric DEFAULT 0 NOT NULL,
    note text
);


ALTER TABLE public.ca_bbj_pool_snapshots OWNER TO postgres;

--
-- Name: TABLE ca_bbj_pool_snapshots; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_bbj_pool_snapshots IS 'The BBJ meter (chip standard Phase 4.2): one row per pool per run. main/backup/promo are the banks as read; journal_* the chip_ledger legs labelled bbj_pools.<bank> since prev; unexplained_* the difference. The is_baseline row is the opening balance - not a movement.';


--
-- Name: fn_bbj_open_pool_baseline(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_open_pool_baseline(p_pool_id uuid) RETURNS public.ca_bbj_pool_snapshots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_epoch timestamptz; v_created timestamptz; v_at timestamptz;
  v_m numeric; v_b numeric; v_p numeric; jm numeric; jb numeric; jp numeric;
  v_row public.ca_bbj_pool_snapshots%ROWTYPE;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'fn_bbj_open_pool_baseline is service only' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.ca_bbj_pool_snapshots WHERE pool_id = p_pool_id) THEN
    SELECT * INTO v_row FROM public.ca_bbj_pool_snapshots WHERE pool_id = p_pool_id AND is_baseline ORDER BY taken_at LIMIT 1;
    RETURN v_row;
  END IF;
  SELECT min(taken_at) INTO v_epoch FROM public.ca_bbj_pool_snapshots WHERE is_baseline;
  SELECT created_at INTO v_created FROM public.bbj_pools WHERE id = p_pool_id;
  IF v_created IS NULL THEN
    RAISE EXCEPTION 'fn_bbj_open_pool_baseline: pool % not found', p_pool_id;
  END IF;
  v_at := GREATEST(v_created, COALESCE(v_epoch, v_created));

  -- One statement, one snapshot: the banks now and every labelled leg since v_at.
  WITH legs AS (
    SELECT CASE WHEN l.to_label LIKE 'bbj_pools.%' THEN l.amount
                WHEN l.from_label LIKE 'bbj_pools.%' THEN -l.amount ELSE 0 END AS signed,
           CASE WHEN l.to_label LIKE 'bbj_pools.%' THEN l.to_label
                WHEN l.from_label LIKE 'bbj_pools.%' THEN l.from_label END AS lbl
      FROM public.chip_ledger l
     WHERE ((l.to_entity_id = p_pool_id AND l.to_type = 'bbj_pool') OR (l.from_entity_id = p_pool_id AND l.from_type = 'bbj_pool'))
       AND l.created_at > v_at
       AND (l.to_label LIKE 'bbj_pools.%' OR l.from_label LIKE 'bbj_pools.%')
  ), banks AS (
    SELECT COALESCE(main_balance, 0) AS m, COALESCE(backup_balance, 0) AS b, COALESCE(promo_balance, 0) AS p
      FROM public.bbj_pools WHERE id = p_pool_id
  )
  SELECT banks.m, banks.b, banks.p,
         COALESCE(sum(signed) FILTER (WHERE lbl = 'bbj_pools.main_balance'), 0),
         COALESCE(sum(signed) FILTER (WHERE lbl = 'bbj_pools.backup_balance'), 0),
         COALESCE(sum(signed) FILTER (WHERE lbl = 'bbj_pools.promo_balance'), 0)
    INTO v_m, v_b, v_p, jm, jb, jp
    FROM banks LEFT JOIN legs ON true GROUP BY banks.m, banks.b, banks.p;

  INSERT INTO public.ca_bbj_pool_snapshots (pool_id, taken_at, is_baseline, main, backup, promo, note)
  VALUES (p_pool_id, v_at, true, round(v_m - jm, 2), round(v_b - jb, 2), round(v_p - jp, 2),
          format('auto-opened by the meter on first sight (%s): opening balance reconstructed as the banks at first sight minus the journal since %s (the later of the pool''s creation and the epoch); not a movement',
                 to_char(clock_timestamp(), 'YYYY-MM-DD HH24:MI:SS UTC'), v_at))
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


ALTER FUNCTION public.fn_bbj_open_pool_baseline(p_pool_id uuid) OWNER TO postgres;

--
-- Name: fn_bbj_orphaned_payouts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_orphaned_payouts() RETURNS TABLE(payout_id uuid, awarded_at timestamp with time zone, table_id uuid, hand_number bigint, total_amount numeric, recipients integer, hand_exists boolean, hand_id_set boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id, p.created_at, p.table_id, p.hand_number, p.total_amount,
         (SELECT count(*)::int FROM public.bbj_payout_recipients r WHERE r.payout_id = p.id),
         EXISTS (SELECT 1 FROM public.hand_history h
                  WHERE h.table_id = p.table_id AND h.hand_number = p.hand_number),
         p.hand_id IS NOT NULL
    FROM public.bbj_payouts p
   WHERE p.hand_id IS NULL
      OR NOT EXISTS (SELECT 1 FROM public.hand_history h
                      WHERE h.table_id = p.table_id AND h.hand_number = p.hand_number)
   ORDER BY p.created_at DESC;
$$;


ALTER FUNCTION public.fn_bbj_orphaned_payouts() OWNER TO postgres;

--
-- Name: fn_bbj_parked_reserve(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_parked_reserve(p_pool_id uuid, p_bank text) RETURNS numeric
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  -- A parked refund remains in this bank but is already owed, not spendable.
  -- Financial callers must hold bbj_pools FOR UPDATE before reading it.
  SELECT COALESCE(sum(u.amount),0) FROM public.bbj_unclaimed_shares u
  JOIN public.bbj_payouts p ON p.id=u.payout_id
  WHERE u.pool_id=p_pool_id AND u.paid_at IS NULL
    AND (CASE WHEN p.kind='mini' THEN 'backup' ELSE 'main' END)=p_bank;
$$;


ALTER FUNCTION public.fn_bbj_parked_reserve(p_pool_id uuid, p_bank text) OWNER TO postgres;

--
-- Name: fn_bbj_payout(uuid, uuid, uuid, uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_payout(p_pool_id uuid, p_hand_id uuid, p_table_id uuid, p_winner_user_id uuid, p_loser_user_id uuid, p_table_player_ids uuid[]) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  -- RETIRED 2026-08-18 (BBJ audit §40): bbj_atomic_payout_v2 is the sole
  -- payer. This one drained the dead pool_amount column, had no idempotency,
  -- credited wallets instead of table stacks, and split 50% to the wrong
  -- player. Refuses permanently.
  SELECT jsonb_build_object('success', false, 'error', 'retired_path_use_bbj_atomic_payout_v2');
$$;


