-- Name: FUNCTION fn_bbj_pool_facts(p_pool_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_pool_facts(p_pool_id uuid) IS 'Hand count + chips contributed for a BBJ pool, counted from bbj_contributions (the ledger) because the bbj_pools counters have drifted.';


--
-- Name: fn_bbj_pool_for_club(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_pool_for_club(p_club_id uuid) RETURNS TABLE(pool_id uuid, main_balance numeric, backup_balance numeric, promo_balance numeric, is_union_pool boolean, union_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH club AS (
    SELECT c.id, c.union_id FROM public.clubs c WHERE c.id = p_club_id
  )
  SELECT bp.id,
         bp.main_balance,
         bp.backup_balance,
         bp.promo_balance,
         bp.union_id IS NOT NULL,
         bp.union_id
  FROM public.bbj_pools bp, club
  WHERE bp.status = 'active'
    AND (
      (club.union_id IS NOT NULL AND bp.union_id = club.union_id)
      OR (club.union_id IS NULL AND bp.club_id = club.id)
    )
  -- Union pool wins if a stale club-level row also exists (matches the server).
  ORDER BY (bp.union_id IS NOT NULL) DESC
  LIMIT 1;
$$;


ALTER FUNCTION public.fn_bbj_pool_for_club(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_bbj_pool_for_club(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_pool_for_club(p_club_id uuid) IS 'The BBJ pool a club plays for: union pool when the club is in a union, else its own. Single source of the union rule that four client surfaces each re-implemented (three incorrectly), and one round trip instead of two or three.';


--
-- Name: fn_bbj_promo_bank_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_promo_bank_check() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH t AS (
    SELECT
      (SELECT COALESCE(sum(promo_portion),0) FROM bbj_contributions)                             AS contributed,
      (SELECT COALESCE(sum(amount),0) FROM union_wallet_transactions WHERE tx_type='bbj_promo_sweep') AS swept_to_union,
      (SELECT COALESCE(sum(amount),0) FROM chip_transactions WHERE transaction_type='bbj_promo_sweep') AS swept_to_club,
      (SELECT COALESCE(sum(promo_balance),0) FROM bbj_pools)                                     AS still_held,
      (SELECT COALESCE(sum(amount),0) FROM bbj_contributions
        WHERE main_portion IS NULL AND backup_portion IS NULL AND promo_portion IS NULL)         AS pre_triple_bank,
      /* The promo rate the rows that DO record their split actually show. Not
         a constant from config: the rate has varied by stakes tier and over
         time, and what matters here is what this pool really banked. */
      (SELECT CASE WHEN COALESCE(sum(amount),0) > 0
                   THEN COALESCE(sum(promo_portion),0) / sum(amount) ELSE 0 END
         FROM bbj_contributions WHERE promo_portion IS NOT NULL)                                 AS observed_rate
  ), g AS (
    SELECT t.*,
           round(swept_to_union + swept_to_club + still_held - contributed, 2) AS gap,
           round(pre_triple_bank * observed_rate, 2)                           AS era_promo
      FROM t
  )
  SELECT jsonb_build_object(
    'promo_contributed', round(contributed,2),
    'swept_to_union',    round(swept_to_union,2),
    'swept_to_club',     round(swept_to_club,2),
    'still_held',        round(still_held,2),
    'over_swept',        gap,
    'pre_triple_bank_contributions', round(pre_triple_bank,2),
    'pre_triple_bank_promo_at_observed_rate', era_promo,
    'observed_promo_rate', round(observed_rate * 100, 4),
    'explained_by_pre_triple_bank', (gap > 0.01 AND gap <= era_promo),
    'unexplained',       GREATEST(round(gap - era_promo, 2), 0),
    'reconciles',        (GREATEST(round(gap - era_promo, 2), 0) <= 0.01),
    'note', 'The promo bank balances once the pre-triple-bank era is accounted for. 49,714 contribution rows from 2026-03-03..07 carry NULL portions - the columns did not exist yet - so their promo money is real but counts as zero on the "entered" side. `unexplained` is the number that matters: chips that left the promo bank and cannot be traced to any contribution, counted or uncounted. Only that should ever raise an alarm. The portions are deliberately NOT backfilled: inventing a split nobody recorded would be editing history.'
  ) FROM g;
$$;


ALTER FUNCTION public.fn_bbj_promo_bank_check() OWNER TO postgres;

--
-- Name: fn_bbj_promo_payout_atomic(uuid, numeric, uuid[], text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_promo_payout_atomic(p_pool_id uuid, p_amount numeric, p_recipient_user_ids uuid[], p_reason text DEFAULT NULL::text, p_event_type text DEFAULT 'custom'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pool record; v_count int; v_total_cents bigint; v_base_cents bigint;
  v_remainder_cents bigint; v_uid uuid; v_idx int := 0; v_amt numeric;
  v_club uuid; v_paid numeric := 0; v_skipped int := 0;
  v_op_key text;
  v_claimed integer;
  v_union uuid;
  v_float numeric;
  v_after numeric;
BEGIN
  /* The GRANT is the gate: anon and authenticated hold no EXECUTE here, so the
     only callers are service_role and the definers that have already
     established who is asking (fn_bbj_promo_rain checks the pool's owner or a
     god/admin profile). The old auth.role() test blocked those definers too,
     because SECURITY DEFINER changes the database role and not the JWT. */
  IF p_amount IS NULL OR p_amount <= 0 THEN RETURN jsonb_build_object('success', true, 'skipped', 'zero_amount'); END IF;
  IF p_recipient_user_ids IS NULL OR array_length(p_recipient_user_ids,1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'no_recipients'); END IF;
  v_count := array_length(p_recipient_user_ids, 1);

  /* ZERO-DRIFT (2026-08-31): idempotency. One payout per
     (pool, event, reason, recipient set, amount) - a retried call returns
     without draining the float twice. */
  v_op_key := 'bbjpromo:' || p_pool_id::text || ':' || p_event_type || ':'
           || COALESCE(p_reason,'') || ':' || p_amount::text || ':'
           || md5(array_to_string(p_recipient_user_ids, ','));
  INSERT INTO public.wallet_credit_idempotency (key, user_id, amount)
  VALUES (left(v_op_key, 255), p_recipient_user_ids[1], p_amount)
  ON CONFLICT (key) DO NOTHING;
  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 0 THEN
    RETURN jsonb_build_object('success', true, 'already_paid', true);
  END IF;

  SELECT * INTO v_pool FROM bbj_pools WHERE id = p_pool_id FOR UPDATE;
  IF v_pool.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'pool_not_found'); END IF;

  /* THE PURSE (2026-09-03, Dan's ruling 3): the promo float, which is where the
     hourly sweep puts this money - the union's promo_wallet when the pool
     belongs to a union, otherwise the standalone club's promo_balance. The pool
     is the occasion, not the purse. */
  v_union := v_pool.union_id;

  IF v_union IS NOT NULL THEN
    SELECT COALESCE(promo_wallet, 0) INTO v_float
      FROM union_wallets WHERE union_id = v_union FOR UPDATE;
  ELSIF v_pool.club_id IS NOT NULL THEN
    SELECT COALESCE(promo_balance, 0) INTO v_float
      FROM clubs WHERE id = v_pool.club_id FOR UPDATE;
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'pool_has_no_owner');
  END IF;

  IF COALESCE(v_float, 0) < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient_promo_balance',
                              'available', COALESCE(v_float, 0), 'requested', p_amount);
  END IF;

  /* One declaration for the whole rain: the float is the counterparty and its
     own table is skipped, so each player's credit writes the single row that
     names both sides. */
  IF v_union IS NOT NULL THEN
    PERFORM public.fn_ca_declare_ledger('promo', 'union_wallet', v_union, NULL,
                                        'promo_rain:' || left(v_op_key, 180), ARRAY['union_wallets']);
    UPDATE union_wallets
       SET promo_wallet = promo_wallet - p_amount, updated_at = now()
     WHERE union_id = v_union
     RETURNING round(promo_wallet, 2) INTO v_after;
  ELSE
    PERFORM public.fn_ca_declare_ledger('promo', 'promo_wallet', v_pool.club_id, NULL,
                                        'promo_rain:' || left(v_op_key, 180), ARRAY['clubs']);
    UPDATE clubs
       SET promo_balance = promo_balance - p_amount, updated_at = now()
     WHERE id = v_pool.club_id
     RETURNING round(promo_balance, 2) INTO v_after;
  END IF;

  v_total_cents := round(p_amount * 100); v_base_cents := v_total_cents / v_count;
  v_remainder_cents := v_total_cents - v_base_cents * v_count;

  FOREACH v_uid IN ARRAY p_recipient_user_ids LOOP
    v_amt := (v_base_cents + (CASE WHEN v_idx = 0 THEN v_remainder_cents ELSE 0 END))::numeric / 100;

    /* ORDINARY CHIPS (Dan, 2026-09-03, ruling 4B). The old body credited
       club_members.promo_balance, a locked bucket; before that it paid
       wallets(PROMO), a pool nothing reads. Promo chips are the same chips. */
    v_club := COALESCE(v_pool.club_id, public.fn_player_home_club(v_uid, NULL));
    IF v_club IS NOT NULL AND EXISTS (
         SELECT 1 FROM club_members m WHERE m.user_id = v_uid AND m.club_id = v_club) THEN
      UPDATE club_members
         SET chip_balance = COALESCE(chip_balance, 0) + v_amt,
             updated_at = NOW()
       WHERE user_id = v_uid AND club_id = v_club;
      INSERT INTO chip_transactions (club_id, to_user_id, amount, transaction_type, notes)
      VALUES (v_club, v_uid, v_amt, 'bbj_promo_payout',
              COALESCE(p_reason, 'BBJ promo pool payout') || ' (' || p_event_type || ')');
      v_paid := v_paid + v_amt;
    ELSE
      v_skipped := v_skipped + 1;
      INSERT INTO financial_alerts (severity, source, message, context)
      VALUES ('critical', 'fn_bbj_promo_payout_atomic',
              'BBJ promo payout recipient has no club wallet - share NOT paid, returned to the float',
              jsonb_build_object('pool_id', p_pool_id, 'user_id', v_uid, 'amount', v_amt));
      IF v_union IS NOT NULL THEN
        UPDATE union_wallets SET promo_wallet = promo_wallet + v_amt, updated_at = now()
         WHERE union_id = v_union RETURNING round(promo_wallet, 2) INTO v_after;
      ELSE
        UPDATE clubs SET promo_balance = promo_balance + v_amt, updated_at = now()
         WHERE id = v_pool.club_id RETURNING round(promo_balance, 2) INTO v_after;
      END IF;
    END IF;
    v_idx := v_idx + 1;
  END LOOP;

  PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);
  PERFORM set_config('app.ledger_autoskip_clubs', '', true);

  RETURN jsonb_build_object('success', true, 'amount', v_paid, 'recipient_count', v_count - v_skipped,
                            'skipped', v_skipped, 'event_type', p_event_type, 'reason', p_reason,
                            'float_after', v_after, 'lands_as', 'ordinary_chips');
END;
$$;


ALTER FUNCTION public.fn_bbj_promo_payout_atomic(p_pool_id uuid, p_amount numeric, p_recipient_user_ids uuid[], p_reason text, p_event_type text) OWNER TO postgres;

--
-- Name: fn_bbj_promo_rain(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_promo_rain(p_pool_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  /* Dan, 2026-09-03: the splash pot has never been built or specified and is
     to be added later, once the accounting work is finished. Until its rules
     exist - eligibility, size, frequency, and what stops a single click
     emptying a union's promo float - this moves no chips.

     The disbursement path that IS ruled on and built is fn_promo_disburse:
     a union owner sends promo to a member club or to a player in one, and an
     unaffiliated club owner sends it to a player in that club. Leaderboards
     remain the one automatic promo payout. */
  RETURN jsonb_build_object(
    'success', false,
    'error', 'not_built_yet',
    'detail', 'The splash pot has not been designed. Promo is disbursed by owners through '
              || 'fn_promo_disburse, and leaderboards are the only automatic promo payout.',
    'pool_id', p_pool_id,
    'requested', p_amount,
    'reason', p_reason);
END;
$$;


ALTER FUNCTION public.fn_bbj_promo_rain(p_pool_id uuid, p_amount numeric, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION fn_bbj_promo_rain(p_pool_id uuid, p_amount numeric, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_promo_rain(p_pool_id uuid, p_amount numeric, p_reason text) IS 'CLOSED 2026-09-03 by Dan''s ruling: the splash pot has never been designed and is to be added later. Refuses every call. The accounting beneath it (fn_bbj_promo_payout_atomic) is correct and ready for when the rules are written.';


--
-- Name: fn_bbj_recent_hits(uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_recent_hits(p_pool_id uuid, p_limit integer DEFAULT 5, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(payout_id uuid, awarded_at timestamp with time zone, hand_number bigint, total_payout numeric, bad_beat_user_id uuid, bad_beat_player_number text, bad_beat_avatar_url text, bad_beat_name text, bad_beat_hand text, bad_beat_amount numeric, bad_beat_cards jsonb, hand_winner_name text, hand_winner_hand text, hand_winner_amount numeric, hand_winner_cards jsonb, board jsonb, game_variant text, small_blind numeric, big_blind numeric, table_player_count integer, recipients jsonb, total_hits integer, kind text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  WITH pool_total AS (
    SELECT count(*)::int AS n FROM public.bbj_payouts p WHERE p.pool_id = p_pool_id
  ),
  top_payouts AS (
    SELECT p.* FROM public.bbj_payouts p
    WHERE p.pool_id = p_pool_id
      AND (
        p_before IS NULL
        OR (p_before_id IS NULL AND p.created_at < p_before)
        OR (p_before_id IS NOT NULL AND (p.created_at, p.id) < (p_before, p_before_id))
      )
    ORDER BY p.created_at DESC, p.id DESC
    LIMIT GREATEST(1, LEAST(p_limit, 25))
  ),
  hits AS (
    SELECT p.*, w.winner_hand, w.loser_hand, w.winner_display_name, w.loser_display_name,
           h.board AS raw_board, h.hole_cards, h.game_variant, h.small_blind, h.big_blind
    FROM top_payouts p
    LEFT JOIN public.bbj_winners w ON w.table_id = p.table_id AND w.hand_number = p.hand_number
    LEFT JOIN public.hand_history h ON h.table_id = p.table_id AND h.hand_number = p.hand_number
  )
  SELECT
    x.id,
    x.created_at,
    x.hand_number,
    x.total_amount,
    x.winner_user_id,
    bb.player_number::text,
    -- THE CLUB AVATAR. profiles.arena_avatar_url is Club Arena's own column
    -- (library art); profiles.avatar_url is the social media photo and is not
    -- ours to display. No fallback to it, exactly as the felt does it - an
    -- unset arena avatar draws the generated monogram client-side instead.
    NULLIF(bb.arena_avatar_url, ''),
    COALESCE(public.fn_arena_name(bb.alias, bb.username, bb.display_name, bb.first_name, bb.last_name, bb.full_name), x.winner_display_name, 'Player'),
    x.winner_hand,
    (SELECT r.amount FROM public.bbj_payout_recipients r
      WHERE r.payout_id = x.id AND r.user_id = x.winner_user_id),
    x.hole_cards -> (x.winner_user_id::text),
    COALESCE(public.fn_arena_name(hw.alias, hw.username, hw.display_name, hw.first_name, hw.last_name, hw.full_name), x.loser_display_name, 'Player'),
    x.loser_hand,
    (SELECT r.amount FROM public.bbj_payout_recipients r
      WHERE r.payout_id = x.id AND r.user_id = x.loser_user_id),
    x.hole_cards -> (x.loser_user_id::text),
    CASE
      WHEN jsonb_typeof(x.raw_board) = 'array' THEN (
        SELECT COALESCE(jsonb_agg(
                 jsonb_build_object(
                   'rank', regexp_replace(card, '(hearts|diamonds|clubs|spades)$', ''),
                   'suit', substring(card from '(hearts|diamonds|clubs|spades)$')
                 ) ORDER BY ord), '[]'::jsonb)
        FROM jsonb_array_elements_text(x.raw_board) WITH ORDINALITY AS arr(card, ord)
        WHERE substring(card from '(hearts|diamonds|clubs|spades)$') IS NOT NULL
      )
      ELSE '[]'::jsonb
    END,
    x.game_variant,
    x.small_blind,
    x.big_blind,
    x.table_player_count,
    COALESCE((
      SELECT jsonb_agg(
               jsonb_build_object(
                 'name', COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), pr.username, 'Player'),
                 'amount', r.amount,
                 'role', CASE
                           WHEN r.user_id = x.winner_user_id THEN 'bad_beat'
                           WHEN r.user_id = x.loser_user_id  THEN 'hand_winner'
                           ELSE 'table'
                         END
               ) ORDER BY r.amount DESC)
      FROM public.bbj_payout_recipients r
      LEFT JOIN public.profiles pr ON pr.id = r.user_id
      WHERE r.payout_id = x.id
    ), '[]'::jsonb),
    (SELECT n FROM pool_total),
    COALESCE(x.kind, 'main')
  FROM hits x
  LEFT JOIN public.profiles bb ON bb.id = x.winner_user_id
  LEFT JOIN public.profiles hw ON hw.id = x.loser_user_id
  ORDER BY x.created_at DESC, x.id DESC;
$_$;


ALTER FUNCTION public.fn_bbj_recent_hits(p_pool_id uuid, p_limit integer, p_before timestamp with time zone, p_before_id uuid) OWNER TO postgres;

--
-- Name: fn_bbj_reconcile(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_reconcile(p_pool_id uuid) RETURNS public.ca_bbj_pool_snapshots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prev public.ca_bbj_pool_snapshots%ROWTYPE;
  v_now timestamptz := clock_timestamp();  -- not now(): two runs in one transaction must not collide
  v_main numeric; v_backup numeric; v_promo numeric;
  jm numeric := 0; jb numeric := 0; jp numeric := 0;
  v_drops numeric := 0; v_pay numeric := 0; v_sweep numeric := 0; v_fund numeric := 0; v_moves numeric := 0;
  v_fail integer := 0;
  v_row public.ca_bbj_pool_snapshots%ROWTYPE;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'fn_bbj_reconcile is service only' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_prev FROM public.ca_bbj_pool_snapshots WHERE pool_id = p_pool_id ORDER BY taken_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'fn_bbj_reconcile: pool % has no opening balance; write the baseline first', p_pool_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.bbj_pools WHERE id = p_pool_id) THEN
    RAISE EXCEPTION 'fn_bbj_reconcile: pool % not found', p_pool_id;
  END IF;

  -- ONE STATEMENT, ONE SNAPSHOT: the banks and the legs are read together so
  -- a write that commits between two reads cannot show in one and not the
  -- other. Every leg the autoledger wrote for this pool's own columns since the
  -- previous snapshot: the labelled side is the pool's bank, its sign is the
  -- side the label sits on (a bank move is two self-legs, one label each).
  -- A leg where the pool is only somebody else's counterparty carries no
  -- bbj_pools label and moves no bank, so it is not counted.
  WITH legs AS (
    SELECT l.category,
           CASE WHEN l.to_label LIKE 'bbj_pools.%' THEN l.amount
                WHEN l.from_label LIKE 'bbj_pools.%' THEN -l.amount ELSE 0 END AS signed,
           CASE WHEN l.to_label LIKE 'bbj_pools.%' THEN l.to_label
                WHEN l.from_label LIKE 'bbj_pools.%' THEN l.from_label END AS lbl,
           l.amount, l.from_type, l.to_type
      FROM public.chip_ledger l
     WHERE ((l.to_entity_id = p_pool_id AND l.to_type = 'bbj_pool') OR (l.from_entity_id = p_pool_id AND l.from_type = 'bbj_pool'))
       AND l.created_at > v_prev.taken_at AND l.created_at <= v_now
       AND (l.to_label LIKE 'bbj_pools.%' OR l.from_label LIKE 'bbj_pools.%')
  )
  , banks AS (
    SELECT COALESCE(main_balance, 0) AS m, COALESCE(backup_balance, 0) AS b, COALESCE(promo_balance, 0) AS p
      FROM public.bbj_pools WHERE id = p_pool_id
  )
  SELECT banks.m, banks.b, banks.p,
         COALESCE(sum(signed) FILTER (WHERE lbl = 'bbj_pools.main_balance'), 0),
         COALESCE(sum(signed) FILTER (WHERE lbl = 'bbj_pools.backup_balance'), 0),
         COALESCE(sum(signed) FILTER (WHERE lbl = 'bbj_pools.promo_balance'), 0),
         COALESCE(sum(amount) FILTER (WHERE category = 'bbj_contribution' AND to_type = 'bbj_pool' AND from_type <> 'bbj_pool'), 0),
         COALESCE(sum(amount) FILTER (WHERE category = 'bbj_payout' AND from_type = 'bbj_pool'), 0),
         COALESCE(sum(amount) FILTER (WHERE category = 'promo' AND from_type = 'bbj_pool'), 0),
         COALESCE(sum(amount) FILTER (WHERE category = 'transfer' AND to_type = 'bbj_pool'), 0),
         COALESCE(sum(amount) FILTER (WHERE from_type = 'bbj_pool' AND to_type = 'bbj_pool'), 0) / 2
    INTO v_main, v_backup, v_promo, jm, jb, jp, v_drops, v_pay, v_sweep, v_fund, v_moves
    FROM banks LEFT JOIN legs ON true
   GROUP BY banks.m, banks.b, banks.p;

  SELECT count(*) INTO v_fail FROM public.ca_ledger_write_failures f
   WHERE f.occurred_at > v_prev.taken_at AND f.occurred_at <= v_now AND f.message ILIKE '%bbj_pools.%';

  INSERT INTO public.ca_bbj_pool_snapshots
    (pool_id, taken_at, is_baseline, prev_id, main, backup, promo,
     journal_main, journal_backup, journal_promo,
     drops_since, payouts_since, sweeps_since, funding_since, moves_since, write_failures,
     unexplained_main, unexplained_backup, unexplained_promo)
  VALUES
    (p_pool_id, v_now, false, v_prev.id, v_main, v_backup, v_promo,
     round(jm, 2), round(jb, 2), round(jp, 2),
     round(v_drops, 2), round(v_pay, 2), round(v_sweep, 2), round(v_fund, 2), round(v_moves, 2), v_fail,
     round((v_main - v_prev.main) - jm, 2),
     round((v_backup - v_prev.backup) - jb, 2),
     round((v_promo - v_prev.promo) - jp, 2))
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


ALTER FUNCTION public.fn_bbj_reconcile(p_pool_id uuid) OWNER TO postgres;

--
-- Name: fn_bbj_reconcile_all(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_reconcile_all() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  p record; s public.ca_bbj_pool_snapshots%ROWTYPE; prev public.ca_bbj_pool_snapshots%ROWTYPE;
  v_out jsonb := '[]'::jsonb; v_two numeric; v_alerts int := 0; v_opened int := 0;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'fn_bbj_reconcile_all is service only' USING ERRCODE = '42501';
  END IF;
  FOR p IN SELECT b.id, b.union_id, b.club_id FROM public.bbj_pools b WHERE b.status = 'active' ORDER BY b.created_at LOOP
    -- A pool the meter has never seen opens its own balance (second cut).
    IF NOT EXISTS (SELECT 1 FROM public.ca_bbj_pool_snapshots x WHERE x.pool_id = p.id) THEN
      PERFORM public.fn_bbj_open_pool_baseline(p.id);
      v_opened := v_opened + 1;
    END IF;
    s := public.fn_bbj_reconcile(p.id);
    SELECT * INTO prev FROM public.ca_bbj_pool_snapshots WHERE id = s.prev_id;
    -- Two consecutive snapshots: a leg that commits after a read straddles one
    -- boundary and reverses at the next, so a single-interval swing is noise
    -- and a two-interval sum is a finding.
    v_two := (s.unexplained_main + s.unexplained_backup + s.unexplained_promo)
           + COALESCE(CASE WHEN prev.is_baseline THEN 0 ELSE prev.unexplained_main + prev.unexplained_backup + prev.unexplained_promo END, 0);
    IF abs(v_two) > 0.01 OR s.write_failures > 0 THEN
      v_alerts := v_alerts + 1;
      -- PHASE 6.2 (2026-09-05): the kill switch reads every pool's two-snapshot figure.
      PERFORM public.fn_ca_kill_switch_trip('fn_bbj_reconcile', v_two,
        format('BBJ pool %s moved %s beyond the journal over two snapshots', p.id, round(v_two, 2)));
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_bbj_reconcile', 'bbj_error', CASE WHEN abs(v_two) >= 100 OR s.write_failures > 0 THEN 'critical' ELSE 'warning' END,
        'bbj-meter:' || p.id::text || ':' || to_char(s.taken_at, 'YYYY-MM-DD-HH24'),
        round(v_two, 2), 0, round(v_two, 2), 'ledger', 'bbj_pools', p.id, p.club_id, p.union_id,
        NULL, NULL, NULL, NULL, NULL, NULL,
        format('BBJ pool banks moved by %s beyond the journal over the last two snapshots (main %s, backup %s, promo %s this interval; %s ledger write failure(s)): a bbj_pools write without a leg, or a leg without a write',
               round(v_two, 2), s.unexplained_main, s.unexplained_backup, s.unexplained_promo, s.write_failures),
        false,
        jsonb_build_object('snapshot_id', s.id, 'pool_id', p.id, 'unexplained_main', s.unexplained_main,
                           'unexplained_backup', s.unexplained_backup, 'unexplained_promo', s.unexplained_promo,
                           'write_failures', s.write_failures));
    END IF;
    v_out := v_out || jsonb_build_object('pool_id', p.id, 'snapshot_id', s.id,
                'main', s.main, 'backup', s.backup, 'promo', s.promo,
                'unexplained', round(s.unexplained_main + s.unexplained_backup + s.unexplained_promo, 2),
                'drops', s.drops_since, 'payouts', s.payouts_since, 'sweeps', s.sweeps_since);
  END LOOP;
  RETURN jsonb_build_object('pools', v_out, 'alerts', v_alerts, 'opened', v_opened);
END;
$$;


ALTER FUNCTION public.fn_bbj_reconcile_all() OWNER TO postgres;

--
-- Name: fn_bbj_relink_payouts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_relink_payouts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_linked integer;
BEGIN
  UPDATE public.bbj_payouts bp
     SET hand_id = h.id
    FROM public.hand_history h
   WHERE bp.hand_id IS NULL
     AND h.table_id = bp.table_id
     AND h.hand_number = bp.hand_number;
  GET DIAGNOSTICS v_linked = ROW_COUNT;
  RETURN v_linked;
END;
$$;


ALTER FUNCTION public.fn_bbj_relink_payouts() OWNER TO postgres;

--
-- Name: fn_bbj_repair_unbanked(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_repair_unbanked(p_since_hours integer DEFAULT 48, p_limit integer DEFAULT 200) RETURNS TABLE(hand_id uuid, table_id uuid, club_id uuid, pool_id uuid, amount numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record; v_pool_id uuid; v_main numeric; v_backup numeric; v_promo numeric;
  v_current_main numeric; v_inserted uuid;
BEGIN
  -- CHIP STANDARD (2026-09-05): a sweep that moves money checks the freeze
  -- (CLAUDE.md section 13 rule 5). fn_ca_auto_reconcile_tick runs this every
  -- minute from pg_cron, which does not stop for the break, and bbj_pools is
  -- not under the freeze guard; the drops it re-banked at :55 and :00 were
  -- the ones whose legs the freeze refused. It returns empty during the break
  -- and re-banks them at the next tick after play resumes.
  IF public.fn_platform_frozen() THEN
    RETURN;
  END IF;
  FOR r IN
    SELECT rr.hand_id AS h_id, rr.table_id AS t_id, rr.club_id AS c_id,
           SUM(rr.bbj_contribution) AS amt,
           MAX(COALESCE((rr.metadata->>'big_blind')::numeric, 0)) AS bb,
           MIN(rr.created_at) AS hand_at
    FROM public.rake_records rr
    WHERE rr.hand_id IS NOT NULL
      AND COALESCE(rr.bbj_contribution, 0) > 0
      AND rr.created_at > now() - make_interval(hours => p_since_hours)
      AND rr.created_at < now() - interval '5 minutes'
      AND NOT EXISTS (SELECT 1 FROM public.bbj_contributions bc WHERE bc.hand_id = rr.hand_id)
    GROUP BY rr.hand_id, rr.table_id, rr.club_id
    ORDER BY MIN(rr.created_at)
    LIMIT p_limit
  LOOP
    SELECT bp.id, bp.main_balance INTO v_pool_id, v_current_main
    FROM public.bbj_pools bp
    WHERE bp.status = 'active'
      AND ((bp.union_id = (SELECT c.union_id FROM public.clubs c WHERE c.id = r.c_id))
        OR (bp.club_id = r.c_id AND (SELECT c.union_id FROM public.clubs c WHERE c.id = r.c_id) IS NULL))
    ORDER BY (bp.union_id IS NOT NULL) DESC
    LIMIT 1
    FOR UPDATE OF bp;

    CONTINUE WHEN v_pool_id IS NULL;

    -- ONE ALLOCATOR (Phase 4.3): the same split the drop uses, residue carried.
    SELECT a.main_portion, a.backup_portion, a.promo_portion INTO v_main, v_backup, v_promo
      FROM public.fn_bbj_allocate(r.amt, v_current_main, v_pool_id) a;

    -- ZERO-DRIFT phase 2: repaired drops = bbj_contribution vs table_stack.
    PERFORM set_config('app.ledger_category', 'bbj_contribution', true);
    PERFORM set_config('app.ledger_counterparty', 'table_stack', true);
    PERFORM set_config('app.ledger_counterparty_entity', COALESCE(r.t_id::text, ''), true);

    WITH ins AS (
      INSERT INTO public.bbj_contributions (
        pool_id, hand_id, table_id, club_id, amount,
        main_portion, backup_portion, promo_portion, big_blind, hand_number, created_at
      )
      SELECT v_pool_id, r.h_id, r.t_id, r.c_id, r.amt,
             v_main, v_backup, v_promo, NULLIF(r.bb, 0), NULL, r.hand_at
      WHERE NOT EXISTS (SELECT 1 FROM public.bbj_contributions bc WHERE bc.hand_id = r.h_id)
      RETURNING id
    ),
    upd AS (
      UPDATE public.bbj_pools bp
      SET main_balance      = bp.main_balance + v_main,
          backup_balance    = bp.backup_balance + v_backup,
          promo_balance     = bp.promo_balance + v_promo,
          total_contributed = COALESCE(bp.total_contributed, 0) + r.amt,
          hands_contributed = COALESCE(bp.hands_contributed, 0) + 1,
          updated_at        = now()
      FROM ins WHERE bp.id = v_pool_id RETURNING bp.id
    )
    SELECT ins.id INTO v_inserted FROM ins;

    IF v_inserted IS NOT NULL THEN
      hand_id := r.h_id; table_id := r.t_id; club_id := r.c_id;
      pool_id := v_pool_id; amount := r.amt;
      RETURN NEXT;
    END IF;
  END LOOP;
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
END;
$$;


ALTER FUNCTION public.fn_bbj_repair_unbanked(p_since_hours integer, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_bbj_repair_unbanked(p_since_hours integer, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_repair_unbanked(p_since_hours integer, p_limit integer) IS 'Self-heal: banks BBJ fees that rake_records shows were withheld from pots but that never reached a pool (engine crash between the rake txn and the banking call). Idempotent by construction; skips the last 5 minutes to avoid racing the live path. Service-role only.';


--
-- Name: fn_bbj_reseed_main_from_backup(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_reseed_main_from_backup(p_pool_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_main numeric; v_backup numeric; v_res jsonb; v_union uuid; v_club uuid;
BEGIN
  SELECT COALESCE(main_balance, 0), COALESCE(backup_balance, 0), union_id, club_id
    INTO v_main, v_backup, v_union, v_club
    FROM public.bbj_pools WHERE id = p_pool_id FOR UPDATE;
  IF NOT FOUND OR v_main > public.fn_bbj_parked_reserve(p_pool_id,'main') THEN
    RETURN COALESCE(v_main, 0);
  END IF;
  v_backup := v_backup-public.fn_bbj_parked_reserve(p_pool_id,'backup');
  IF v_backup <= 0 THEN
    -- The reserve is empty: the jackpot restarts at zero. Not refused (the
    -- hit has been paid and the pool is what it is), but never silent.
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_bbj_reseed_main_from_backup', 'bbj_error', 'warning',
      'bbj-reserve-empty:' || p_pool_id::text || ':' || to_char(now(), 'YYYY-MM-DD-HH24'),
      0, NULL, 0, 'ledger', 'bbj_pools', p_pool_id, v_club, v_union, NULL, NULL, NULL, NULL, NULL, NULL,
      'a 100% hit drained the main jackpot and the backup reserve was empty, so the jackpot restarts at 0; fund the reserve (fn_union_fund_bbj_pool) or accept the restart',
      true, jsonb_build_object('pool_id', p_pool_id));
    RETURN COALESCE(v_main,0);
  END IF;
  v_res := public.fn_bbj_move_between_banks(p_pool_id, 'backup', 'main', v_backup,
             'reseed: a hit took 100% of main; the reserve becomes the new main jackpot',
             'reseed:' || p_pool_id::text || ':' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSUS'));
  IF (v_res->>'ok')::boolean IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'reseed failed: %', v_res;
  END IF;
  RETURN v_main+v_backup;
END;
$$;


ALTER FUNCTION public.fn_bbj_reseed_main_from_backup(p_pool_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_bbj_reseed_main_from_backup(p_pool_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_reseed_main_from_backup(p_pool_id uuid) IS 'After a hit drains main to zero, TRANSFERS the back-up jackpot into main so the jackpot does not restart at zero. A transfer, never a payout source: backup is debited exactly what main is credited.';


--
-- Name: fn_bbj_rollup_catchup(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_rollup_catchup(p_days integer DEFAULT 3) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  r record;
  v_done integer := 0;
BEGIN
  FOR r IN
    SELECT DISTINCT b.club_id, b.created_at::date AS day
      FROM bbj_contributions b
     WHERE b.created_at >= (now()::date - GREATEST(COALESCE(p_days, 3), 1))
       AND b.created_at <  date_trunc('day', now())
       AND NOT EXISTS (SELECT 1 FROM bbj_daily_user d
                        WHERE d.club_id = b.club_id AND d.day = b.created_at::date)
  LOOP
    BEGIN
      PERFORM fn_bbj_rollup_day(r.club_id, r.day);
      v_done := v_done + 1;
    EXCEPTION WHEN OTHERS THEN
      -- One bad club-day must not stop the sweep, but it must be visible.
      RAISE WARNING '[bbj-rollup] % % failed: %', r.club_id, r.day, SQLERRM;
    END;
  END LOOP;
  RETURN v_done;
END;
$$;


ALTER FUNCTION public.fn_bbj_rollup_catchup(p_days integer) OWNER TO postgres;

--
-- Name: fn_bbj_rollup_day(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_rollup_day(p_club_id uuid, p_day date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_start timestamptz := p_day::timestamptz;
  v_end   timestamptz := (p_day + 1)::timestamptz;
  v_rows  integer := 0;
BEGIN
  IF v_end > date_trunc('day', now()) THEN
    RAISE EXCEPTION 'bbj rollup: day % is not complete', p_day;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('bbj_rollup:' || p_club_id::text || ':' || p_day::text, 42));

  DELETE FROM bbj_daily_user WHERE club_id = p_club_id AND day = p_day;

  WITH src AS (
    SELECT b.id,
           b.main_portion   AS m,
           b.backup_portion AS bk,
           b.promo_portion  AS pr,
           r.player_contributions AS contribs,
           COALESCE(r.rake_method, 'DEALT_EQUAL') AS method
      FROM bbj_contributions b
      JOIN rake_records r ON r.hand_id = b.hand_id
     WHERE b.club_id = p_club_id
       AND b.created_at >= v_start AND b.created_at < v_end
       AND b.amount > 0
       AND r.player_contributions IS NOT NULL
  ), split AS (
    SELECT am.user_id,
           round(am.credit * 100)::bigint AS m_cents,
           COALESCE(round(ab.credit * 100)::bigint, 0) AS bk_cents,
           COALESCE(round(ap.credit * 100)::bigint, 0) AS pr_cents
      FROM src s
      CROSS JOIN LATERAL public.fn_allocate_rake_credits(COALESCE(s.m, 0),  s.contribs, s.method) am
      LEFT JOIN LATERAL public.fn_allocate_rake_credits(COALESCE(s.bk, 0), s.contribs, s.method) ab
        ON ab.user_id = am.user_id
      LEFT JOIN LATERAL public.fn_allocate_rake_credits(COALESCE(s.pr, 0), s.contribs, s.method) ap
        ON ap.user_id = am.user_id
  ), ins AS (
    INSERT INTO bbj_daily_user
      (club_id, day, user_id, bbj_amount, main_amount, backup_amount, promo_amount, hands)
    SELECT p_club_id, p_day, sp.user_id,
           SUM(sp.m_cents + sp.bk_cents + sp.pr_cents)::numeric / 100,
           SUM(sp.m_cents)::numeric  / 100,
           SUM(sp.bk_cents)::numeric / 100,
           SUM(sp.pr_cents)::numeric / 100,
           count(*)
      FROM split sp GROUP BY sp.user_id
    RETURNING 1
  )
  SELECT count(*) INTO v_rows FROM ins;

  RETURN v_rows;
END;
$$;


ALTER FUNCTION public.fn_bbj_rollup_day(p_club_id uuid, p_day date) OWNER TO postgres;

--
-- Name: fn_bbj_selftest_payout_conservation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_selftest_payout_conservation() RETURNS TABLE(ok boolean, detail text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pool uuid; err text := ''; r record;
  m_full numeric; b_full numeric; paid_full numeric;
  m_part numeric; b_part numeric; paid_part numeric;
  v_u1 uuid; v_u2 uuid;
BEGIN
  SELECT id INTO v_pool FROM bbj_pools WHERE status='active' ORDER BY main_balance DESC LIMIT 1;
  IF v_pool IS NULL THEN
    RETURN QUERY SELECT true, 'skipped: no active pool'; RETURN;
  END IF;
  SELECT id INTO v_u1 FROM profiles LIMIT 1;
  SELECT id INTO v_u2 FROM profiles OFFSET 1 LIMIT 1;

  BEGIN
    -- FULL hit: 100% of main, reserve funded and must reseed.
    UPDATE bbj_pools SET main_balance = 800, backup_balance = 5000 WHERE id = v_pool;
    SELECT * INTO r FROM bbj_atomic_payout_v2(v_pool, gen_random_uuid(), 999999881::bigint,
      100::numeric, v_u1, v_u2, ARRAY[]::uuid[], ARRAY[]::uuid[], '{"selftest":true}'::jsonb);
    paid_full := COALESCE(r.total_payout,0);
    SELECT main_balance, COALESCE(backup_balance,0) INTO m_full, b_full FROM bbj_pools WHERE id=v_pool;

    -- PARTIAL hit: 85% of main, reserve must not move.
    UPDATE bbj_pools SET main_balance = 1000, backup_balance = 5000 WHERE id = v_pool;
    SELECT * INTO r FROM bbj_atomic_payout_v2(v_pool, gen_random_uuid(), 999999882::bigint,
      85::numeric, v_u1, v_u2, ARRAY[]::uuid[], ARRAY[]::uuid[], '{"selftest":true}'::jsonb);
    paid_part := COALESCE(r.total_payout,0);
    SELECT main_balance, COALESCE(backup_balance,0) INTO m_part, b_part FROM bbj_pools WHERE id=v_pool;

    RAISE EXCEPTION 'SELFTEST-ROLLBACK';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'SELFTEST-ROLLBACK' THEN GET STACKED DIAGNOSTICS err = MESSAGE_TEXT; END IF;
  END;

  IF err <> '' THEN
    RETURN QUERY SELECT false, 'selftest errored: ' || err;
  ELSIF paid_full > 800.005 THEN
    RETURN QUERY SELECT false, format('RESERVE FUNDED A PAYOUT: paid %s from a main of 800', paid_full);
  ELSIF ABS((m_full + b_full) - (5800 - paid_full)) > 0.005 THEN
    RETURN QUERY SELECT false, format('NOT CONSERVED on full hit: pool is %s, expected %s',
                                      m_full + b_full, 5800 - paid_full);
  ELSIF ABS(m_full - 5000) > 0.005 OR ABS(b_full) > 0.005 THEN
    RETURN QUERY SELECT false, format('RESEED FAILED: after a 100%% hit main=%s backup=%s, expected main=5000 backup=0',
                                      m_full, b_full);
  ELSIF ABS(b_part - 5000) > 0.005 THEN
    RETURN QUERY SELECT false, format('RESERVE MOVED ON A PARTIAL HIT: backup=%s, expected 5000', b_part);
  ELSIF ABS(m_part - 150) > 0.005 THEN
    RETURN QUERY SELECT false, format('MAIN WRONG after partial hit: main=%s, expected 150', m_part);
  ELSE
    RETURN QUERY SELECT true, format(
      'full hit: paid %s, reserve reseeded main to %s; partial hit: paid %s, reserve untouched',
      paid_full, m_full, paid_part);
  END IF;
END;
$$;


ALTER FUNCTION public.fn_bbj_selftest_payout_conservation() OWNER TO postgres;

--
-- Name: FUNCTION fn_bbj_selftest_payout_conservation(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_selftest_payout_conservation() IS 'Runs the real BBJ payer at 100% of main in a rolled-back subtransaction and asserts: the backup reserve is untouched, main falls by exactly the amount paid, and the payout never exceeds main.';


--
-- Name: fn_bbj_table_share_farming(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_table_share_farming(p_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(days => GREATEST(COALESCE(p_days, 90), 1));
  v_payouts int; v_recipients int; v_with_ip int; v_with_agent int; v_findings jsonb;
BEGIN
  SELECT count(DISTINCT p.id), count(DISTINCT r.user_id)
    INTO v_payouts, v_recipients
    FROM bbj_payouts p JOIN bbj_payout_recipients r ON r.payout_id = p.id
   WHERE p.created_at >= v_since;

  /* COVERAGE FIRST, because an empty result over an empty population reads
     exactly like an empty result over a clean one. */
  SELECT count(DISTINCT r.user_id) FILTER (WHERE EXISTS (
           SELECT 1 FROM action_audit_logs a
            WHERE a.user_id = r.user_id AND a.ip_address IS NOT NULL)),
         count(DISTINCT r.user_id) FILTER (WHERE EXISTS (
           SELECT 1 FROM club_members cm
            WHERE cm.user_id = r.user_id
              AND COALESCE(cm.agent_id, cm.parent_agent_id) IS NOT NULL))
    INTO v_with_ip, v_with_agent
    FROM bbj_payouts p JOIN bbj_payout_recipients r ON r.payout_id = p.id
   WHERE p.created_at >= v_since;

  /* THE ONLY BOND THAT MEANS ANYTHING HERE IS THE DEVICE.
     The agent graph was tried and REJECTED, and the rejection is the finding:
     asking it on 2026-09-07 flagged 20 of 29 payouts, because two recipients
     sharing an agent is the ordinary shape of every club on this platform, not
     evidence of anything. A check that fires on two thirds of all jackpots is
     an alarm that gets muted (CLAUDE.md 10.84), so the agent count is reported
     as COVERAGE and never as a finding. Making it usable needs a baseline -
     what fraction of a table an agent's players normally occupy - measured
     rather than guessed, and that is not done here. */
  WITH rec AS (
    SELECT p.id AS payout_id, p.hand_number, r.user_id
      FROM bbj_payouts p JOIN bbj_payout_recipients r ON r.payout_id = p.id
     WHERE p.created_at >= v_since
  ), link AS (
    SELECT rc.payout_id, rc.hand_number, rc.user_id, a.ip_address AS bond
      FROM rec rc JOIN action_audit_logs a ON a.user_id = rc.user_id
     WHERE a.ip_address IS NOT NULL
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'hand_number', hand_number, 'ip', bond,
           'linked_recipients', n, 'users', users)), '[]'::jsonb)
    INTO v_findings
    FROM (SELECT hand_number, bond, count(DISTINCT user_id) AS n,
                 jsonb_agg(DISTINCT user_id) AS users
            FROM link GROUP BY 1, 2 HAVING count(DISTINCT user_id) > 1
           ORDER BY 3 DESC LIMIT 20) x;

  RETURN jsonb_build_object(
    'window_days', p_days,
    'payouts_examined', v_payouts,
    'recipients_examined', v_recipients,
    'recipients_with_a_device_signal', v_with_ip,
    'recipients_with_an_agent_above_them', v_with_agent,
    'findings', v_findings,
    'finding_count', jsonb_array_length(v_findings),
    /* THREE OUTCOMES, NOT TWO (CLAUDE.md 10.86 rule 1). */
    'verdict', CASE
      WHEN v_recipients = 0 THEN 'no_payouts_in_window'
      WHEN v_with_ip = 0 THEN 'cannot_tell'
      WHEN jsonb_array_length(v_findings) > 0 THEN 'shared_device_found'
      ELSE 'clean' END,
    'clean', (v_recipients > 0 AND v_with_ip > 0 AND jsonb_array_length(v_findings) = 0),
    'note', 'Table-share farming is seating several accounts you control at one table so that a jackpot pays you several dealt-in shares of a fixed 25%. It does not enlarge the pot; it enlarges your fraction of it at the honest players'' expense. MEASURED 2026-09-07 over all 29 payouts and 131 distinct recipients in the platform''s history: every recipient is a horse, not one has ever had an IP, and so this check''s only real signal has zero coverage. `cannot_tell` is the true answer and it is what this returns - it has never yet been able to see farming, and until a human collects a table share it never will. HORSES ARE PLAYERS (10.5): the fix is not to exclude them, it is that a horse has no browser and therefore no device bond, so the day a human is paid a share is the day this check starts working. What would make it work for everyone: a per-agent table-occupancy baseline, measured, so that "several of one agent''s players at one table" can be told from the ordinary shape of a club.');
END;
$$;


ALTER FUNCTION public.fn_bbj_table_share_farming(p_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_bbj_table_share_farming(p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_table_share_farming(p_days integer) IS 'BBJ phase 5.4. Answers whether two recipients of one jackpot share a device. Returns `cannot_tell` rather than `clean` when no recipient in the window carries a device signal - which is every window so far, because every jackpot recipient to date is a horse.';


--
-- Name: fn_bbj_unclaimed_shares(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_unclaimed_shares() RETURNS TABLE(id uuid, created_at timestamp with time zone, user_id uuid, player text, amount numeric, payout_id uuid, table_id uuid, hand_number bigint, reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT u.id, u.created_at, u.user_id,
         COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                                       pr.first_name, pr.last_name, pr.full_name), 'Player'),
         u.amount, u.payout_id, u.table_id, p.hand_number, u.reason
    FROM public.bbj_unclaimed_shares u
    LEFT JOIN public.bbj_payouts p ON p.id = u.payout_id
    LEFT JOIN public.profiles pr ON pr.id = u.user_id
   WHERE u.paid_at IS NULL
   ORDER BY u.created_at DESC;
$$;


