--
-- Name: fn_block_home_member_ban_evasion(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_block_home_member_ban_evasion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_staff boolean;
BEGIN
  -- Internal / cron / trigger-chain contexts have no JWT. Allow.
  IF v_caller IS NULL THEN
    RETURN OLD;
  END IF;

  -- service_role (server-side admin code) bypass
  IF COALESCE(auth.role(), '') = 'service_role' THEN
    RETURN OLD;
  END IF;

  -- If the row being deleted isn't banned, nothing special to check here
  IF OLD.status <> 'banned' THEN
    RETURN OLD;
  END IF;

  -- Banned row being deleted. Only staff of this group may do so (to
  -- permanently remove the person from the group, e.g. after an appeal).
  v_is_staff := fn_home_is_group_staff(v_caller, OLD.group_id);

  IF NOT v_is_staff THEN
    RAISE EXCEPTION
      'Cannot delete your own banned member row. Banned members cannot leave a group to evade their ban.'
      USING ERRCODE = '42501',
            HINT = 'Contact a group admin if you believe this ban is in error.';
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION public.fn_block_home_member_ban_evasion() OWNER TO postgres;

--
-- Name: fn_block_message_field_reassignment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_block_message_field_reassignment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Service role is the maintenance path and bypasses field locks.
  IF auth.role() = 'service_role' THEN
    RETURN NEW;
  END IF;

  IF NEW.sender_id IS DISTINCT FROM OLD.sender_id THEN
    RAISE EXCEPTION 'sender_id cannot be changed on an existing message'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.conversation_id IS DISTINCT FROM OLD.conversation_id THEN
    RAISE EXCEPTION 'conversation_id cannot be changed on an existing message'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'created_at cannot be changed on an existing message'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_block_message_field_reassignment() OWNER TO postgres;

--
-- Name: fn_bomb_pot_ledger_gaps(interval, interval, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bomb_pot_ledger_gaps(p_since interval DEFAULT '1 day'::interval, p_grace interval DEFAULT '00:10:00'::interval, p_epoch timestamp with time zone DEFAULT '2026-08-28 17:38:00-05'::timestamp with time zone) RETURNS TABLE(hand_history_id uuid, table_id uuid, hand_number bigint, occurred_at timestamp with time zone, board_count integer, trigger_reason text, net_winnings numeric, ledger_total numeric, award_units bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    h.id,
    h.table_id,
    h.hand_number::bigint,
    h.created_at,
    (h.bomb_pot ->> 'board_count')::int,
    h.bomb_pot ->> 'trigger_reason',
    round(COALESCE(h.pot_size, 0) - COALESCE(h.rake_amount, 0) - COALESCE(h.bbj_amount, 0), 2),
    round(COALESCE(u.total, 0), 2),
    COALESCE(u.units, 0)
  FROM public.hand_history h
  LEFT JOIN LATERAL (
    SELECT SUM(a.amount) AS total, COUNT(*) AS units
    FROM public.bomb_pot_award_units a
    WHERE a.hand_history_id = h.id
  ) u ON true
  WHERE h.bomb_pot IS NOT NULL
    AND h.created_at >  now() - p_since
    AND h.created_at <  now() - p_grace
    AND h.created_at >= p_epoch
    AND round(COALESCE(h.pot_size, 0) - COALESCE(h.rake_amount, 0) - COALESCE(h.bbj_amount, 0), 2)
        IS DISTINCT FROM round(COALESCE(u.total, 0), 2)
  ORDER BY h.created_at DESC
$$;


ALTER FUNCTION public.fn_bomb_pot_ledger_gaps(p_since interval, p_grace interval, p_epoch timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_bomb_pot_ledger_gaps(p_since interval, p_grace interval, p_epoch timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bomb_pot_ledger_gaps(p_since interval, p_grace interval, p_epoch timestamp with time zone) IS 'Settled bomb hands whose bomb_pot_award_units do not sum to net winnings. Read by reconcile_ledger_nightly, which files each row as critical.';


--
-- Name: fn_bot_flag_disagreement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bot_flag_disagreement() RETURNS TABLE(memberships bigint, chips_held numeric, horses_mislabelled_human bigint, humans_mislabelled_bot bigint, note text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT count(*) FILTER (WHERE coalesce(p.is_horse,false) <> coalesce(cm.is_bot,false)),
         round(coalesce(sum(cm.chip_balance) FILTER (
           WHERE coalesce(p.is_horse,false) <> coalesce(cm.is_bot,false)), 0)::numeric, 2),
         count(*) FILTER (WHERE coalesce(p.is_horse,false) AND NOT coalesce(cm.is_bot,false)),
         count(*) FILTER (WHERE NOT coalesce(p.is_horse,false) AND coalesce(cm.is_bot,false)),
         'profiles.is_horse is authoritative. Any segmentation using club_members.is_bot '
         || 'miscounts by this many memberships.'
  FROM public.club_members cm
  JOIN public.profiles p ON p.id = cm.user_id;
$$;


ALTER FUNCTION public.fn_bot_flag_disagreement() OWNER TO postgres;

--
-- Name: FUNCTION fn_bot_flag_disagreement(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bot_flag_disagreement() IS 'How far club_members.is_bot has drifted from profiles.is_horse. Added 2026-08-27 after finding 985 horses (74.5M chips) flagged as human, which makes every is_bot-keyed report wrong. The flag is NOT auto-corrected: mass_fund_horses reads it and flipping rows could trigger a funding run.';


--
-- Name: fn_bounty_obligation_has_complete_marker(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bounty_obligation_has_complete_marker(p_obligation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE((
    SELECT CASE WHEN o.mode='mystery_chest' THEN
      EXISTS (
        SELECT 1 FROM public.tournament_bounty_awards a
         WHERE a.bounty_obligation_id=o.id AND a.status='completed'
           AND (SELECT COALESCE(sum(r.amount_cents),0)
                  FROM public.tournament_bounty_award_recipients r
                 WHERE r.award_id=a.id AND r.paid_at IS NOT NULL)=a.amount_cents
           AND NOT EXISTS (
             SELECT 1
               FROM (
                 SELECT claimant_id,ordinal,claimant_count,
                        floor(a.amount_cents / claimant_count)
                          + CASE WHEN ordinal <= mod(a.amount_cents,claimant_count)
                                 THEN 1 ELSE 0 END AS expected_cents
                   FROM (
                     SELECT (c->>'user_id')::uuid AS claimant_id,
                            row_number() OVER (ORDER BY c->>'user_id') AS ordinal,
                            count(*) OVER () AS claimant_count
                       FROM jsonb_array_elements(o.claimants) c
                   ) ordered_claimants
               ) expected
              WHERE NOT EXISTS (
                SELECT 1 FROM public.tournament_bounty_award_recipients r
                 WHERE r.award_id=a.id AND r.user_id=expected.claimant_id
                   AND r.amount_cents=expected.expected_cents
                   AND r.paid_at IS NOT NULL
              )
           )
           AND NOT EXISTS (
             SELECT 1 FROM public.tournament_bounty_award_recipients r
              WHERE r.award_id=a.id
                AND (r.paid_at IS NULL OR NOT EXISTS (
                  SELECT 1 FROM jsonb_array_elements(o.claimants) c
                   WHERE (c->>'user_id')::uuid=r.user_id
                ))
           )
      )
    ELSE
      NOT EXISTS (
        SELECT 1
          FROM (
            SELECT claimant_id, ordinal, claimant_count,
                   CASE WHEN ordinal < claimant_count
                        THEN floor(head_cents / claimant_count)
                        ELSE head_cents
                             - floor(head_cents / claimant_count) * (claimant_count - 1)
                   END AS expected_cents
              FROM (
                SELECT (c->>'user_id')::uuid AS claimant_id,
                       row_number() OVER (ORDER BY c->>'user_id') AS ordinal,
                       count(*) OVER () AS claimant_count,
                       round(o.head_amount * 100)::bigint AS head_cents
                  FROM jsonb_array_elements(o.claimants) c
              ) ordered_claimants
          ) expected
         WHERE expected.expected_cents > 0
           AND NOT EXISTS (
           SELECT 1 FROM public.tournament_bounties b
            WHERE b.bounty_obligation_id=o.id
              AND b.collector_player_id=expected.claimant_id
              AND round(b.bounty_amount * 100)::bigint=expected.expected_cents
              AND round(COALESCE(b.added_to_collector_bounty,0) * 100)::bigint=
                    CASE WHEN o.mode='pko'
                         THEN expected.expected_cents-floor(expected.expected_cents/2.0)::bigint
                         ELSE 0 END
              AND round((b.bounty_amount-COALESCE(b.added_to_collector_bounty,0))*100)::bigint=
                    CASE WHEN o.mode='pko'
                         THEN floor(expected.expected_cents/2.0)::bigint
                         ELSE expected.expected_cents END
         )
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.tournament_bounties b
         WHERE b.bounty_obligation_id=o.id
           AND NOT EXISTS (
             SELECT 1 FROM jsonb_array_elements(o.claimants) c
              WHERE (c->>'user_id')::uuid=b.collector_player_id
           )
      )
      AND round(COALESCE((
        SELECT sum(b.bounty_amount) FROM public.tournament_bounties b
         WHERE b.bounty_obligation_id=o.id
      ),0),2)=round(o.head_amount,2)
    END
      FROM public.tournament_bounty_obligations o
     WHERE o.id=p_obligation_id
  ),false);
$$;


ALTER FUNCTION public.fn_bounty_obligation_has_complete_marker(p_obligation_id uuid) OWNER TO postgres;

--
-- Name: fn_brain_telemetry_add(date, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_brain_telemetry_add(p_day date, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r jsonb; n int := 0;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then return 0; end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    continue when r->>'feature' is null or length(r->>'feature') = 0 or length(r->>'feature') > 64;
    insert into horse_brain_telemetry as t (day, feature, fires)
    values (p_day, r->>'feature', coalesce((r->>'fires')::bigint, 0))
    on conflict (day, feature) do update set
      fires = t.fires + excluded.fires,
      updated_at = now();
    n := n + 1;
  end loop;
  return n;
end $$;


ALTER FUNCTION public.fn_brain_telemetry_add(p_day date, p_rows jsonb) OWNER TO postgres;

--
-- Name: fn_bump_friend_challenge_progress(text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bump_friend_challenge_progress(p_challenge_type text, p_amount numeric DEFAULT 1) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR p_amount IS NULL OR p_amount = 0 THEN RETURN; END IF;
  UPDATE friend_challenges
     SET challenger_progress = COALESCE(challenger_progress,0) + p_amount
   WHERE challenge_type = p_challenge_type AND status = 'active'
     AND challenger_id = v_uid AND expires_at > now();
  UPDATE friend_challenges
     SET challengee_progress = COALESCE(challengee_progress,0) + p_amount
   WHERE challenge_type = p_challenge_type AND status = 'active'
     AND challengee_id = v_uid AND expires_at > now();
END; $$;


ALTER FUNCTION public.fn_bump_friend_challenge_progress(p_challenge_type text, p_amount numeric) OWNER TO postgres;

--
-- Name: fn_bump_group_activity_on_reservation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bump_group_activity_on_reservation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_group_id uuid;
BEGIN
  SELECT g.group_id INTO v_group_id
    FROM public.commander_home_game_tables t
    JOIN public.commander_home_games g ON g.id = t.game_id
   WHERE t.id = COALESCE(NEW.table_id, OLD.table_id);

  IF v_group_id IS NOT NULL THEN
    UPDATE public.commander_home_groups
       SET last_activity_at = now()
     WHERE id = v_group_id;
  END IF;

  RETURN COALESCE(NEW, OLD);
END $$;


