--
-- Name: fn_ca_account_balance(text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_account_balance(p_type text, p_entity uuid, p_club uuid, p_col text) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v numeric; v_rows int;
BEGIN
  /* A BALANCE THAT DOES NOT EXIST IS NOT ZERO: an owner with no row is
     unreadable, and the replay skips what it cannot read rather than judging
     it against a fabricated zero. */
  CASE p_col
    WHEN 'club_members.chip_balance' THEN
      SELECT count(*), COALESCE(sum(chip_balance), 0) INTO v_rows, v FROM public.club_members WHERE user_id = p_entity;
    WHEN 'table_seats.stack' THEN
      -- the whole cash felt, exactly as fn_ca_supply_snapshot defines it
      SELECT count(*), COALESCE(sum(ts.stack), 0) INTO v_rows, v
        FROM public.table_seats ts
       WHERE ts.left_at IS NULL
         AND NOT EXISTS (SELECT 1 FROM public.tables t WHERE t.id = ts.table_id AND t.tournament_id IS NOT NULL);
      v_rows := 1;  -- the felt always exists, even when every seat is empty
    WHEN 'clubs.chip_treasury' THEN
      SELECT count(*), COALESCE(sum(chip_treasury), 0) INTO v_rows, v FROM public.clubs WHERE id = p_entity;
    WHEN 'clubs.promo_balance' THEN
      SELECT count(*), COALESCE(sum(promo_balance), 0) INTO v_rows, v FROM public.clubs WHERE id = p_entity;
    WHEN 'clubs.insurance_balance' THEN
      SELECT count(*), COALESCE(sum(insurance_balance), 0) INTO v_rows, v FROM public.clubs WHERE id = p_entity;
    WHEN 'union_wallets.chip_balance' THEN
      SELECT count(*), COALESCE(sum(chip_balance), 0) INTO v_rows, v FROM public.union_wallets WHERE union_id = p_entity;
    WHEN 'union_wallets.rake_wallet' THEN
      SELECT count(*), COALESCE(sum(rake_wallet), 0) INTO v_rows, v FROM public.union_wallets WHERE union_id = p_entity;
    WHEN 'union_wallets.bbj_wallet' THEN
      SELECT count(*), COALESCE(sum(bbj_wallet), 0) INTO v_rows, v FROM public.union_wallets WHERE union_id = p_entity;
    WHEN 'union_wallets.promo_wallet' THEN
      SELECT count(*), COALESCE(sum(promo_wallet), 0) INTO v_rows, v FROM public.union_wallets WHERE union_id = p_entity;
    WHEN 'union_wallets.insurance_wallet' THEN
      SELECT count(*), COALESCE(sum(insurance_wallet), 0) INTO v_rows, v FROM public.union_wallets WHERE union_id = p_entity;
    WHEN 'union_wallets.spin_reserve_wallet' THEN
      SELECT count(*), COALESCE(sum(spin_reserve_wallet), 0) INTO v_rows, v FROM public.union_wallets WHERE union_id = p_entity;
    WHEN 'bbj_pools.main_balance' THEN
      SELECT count(*), COALESCE(sum(main_balance), 0) INTO v_rows, v FROM public.bbj_pools WHERE id = p_entity;
    WHEN 'bbj_pools.backup_balance' THEN
      SELECT count(*), COALESCE(sum(backup_balance), 0) INTO v_rows, v FROM public.bbj_pools WHERE id = p_entity;
    WHEN 'bbj_pools.promo_balance' THEN
      SELECT count(*), COALESCE(sum(promo_balance), 0) INTO v_rows, v FROM public.bbj_pools WHERE id = p_entity;
    WHEN 'spin_bonus_pools.balance' THEN
      SELECT count(*), COALESCE(sum(balance), 0) INTO v_rows, v FROM public.spin_bonus_pools WHERE club_id = p_entity OR id = p_entity;
    WHEN 'agents.promo_wallet_balance' THEN
      SELECT count(*), COALESCE(sum(promo_wallet_balance), 0) INTO v_rows, v FROM public.agents WHERE id = p_entity OR user_id = p_entity;
    WHEN 'agents.agent_wallet_balance' THEN
      SELECT count(*), COALESCE(sum(agent_wallet_balance), 0) INTO v_rows, v FROM public.agents WHERE id = p_entity OR user_id = p_entity;
    ELSE
      v_rows := 0; v := NULL;
  END CASE;
  IF COALESCE(v_rows, 0) = 0 THEN RETURN NULL; END IF;
  RETURN v;
END;
$$;


ALTER FUNCTION public.fn_ca_account_balance(p_type text, p_entity uuid, p_club uuid, p_col text) OWNER TO postgres;

--
-- Name: fn_ca_adjustment_under_10_9(uuid, uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_adjustment_under_10_9(p_tournament_id uuid, p_user_id uuid, p_amount numeric, p_reason text, p_migration text, p_actor_label text DEFAULT 'chip standard (Claude)'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_id uuid;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'fn_ca_adjustment_under_10_9 is service only' USING ERRCODE = '42501';
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 200 THEN
    RAISE EXCEPTION 'a 10.9 adjustment carries the paragraph: at least 200 characters naming every affected player and why (got %)', length(btrim(COALESCE(p_reason, '')));
  END IF;
  IF COALESCE(p_migration, '') !~ '^\d{14}_[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'a 10.9 adjustment names the migration that carries it (got %)', p_migration;
  END IF;
  IF p_reason NOT LIKE '%' || p_migration || '%' THEN
    RAISE EXCEPTION 'the reason must name the migration %', p_migration;
  END IF;
  INSERT INTO public.ca_manual_adjustments
    (actor, actor_label, approver, approver_label, reason, amount, target_kind, target_id, tournament_id, status, approved_at, decision_note, asset)
  VALUES
    ('00000000-0000-0000-0000-00000000c1a9', p_actor_label,
     '2d1cd6c3-5700-4af9-a271-d4863fdab20d', 'Dan, standing written approval under CLAUDE.md 10.9 (2026-09-02): agents settle real chips without asking when the five conditions hold',
     btrim(p_reason), round(p_amount, 2), 'player_wallet', p_user_id, p_tournament_id, 'approved', now(),
     'migration ' || p_migration, 'chips')
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$_$;


ALTER FUNCTION public.fn_ca_adjustment_under_10_9(p_tournament_id uuid, p_user_id uuid, p_amount numeric, p_reason text, p_migration text, p_actor_label text) OWNER TO postgres;

--
-- Name: fn_ca_adjustments_report(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_adjustments_report(p_since timestamp with time zone DEFAULT (now() - '1 day'::interval)) RETURNS TABLE(source text, moved_at timestamp with time zone, actor uuid, action text, from_account text, from_entity uuid, to_account text, to_entity uuid, amount numeric, club_id uuid, union_id uuid, reference text, single_actor boolean, row_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  v_uid  uuid := auth.uid();
  v_mgmt boolean := false;
BEGIN
  /* The management gate fn_ca_post_correction uses. A server-side caller
     (service_role, or no JWT at all: pg_cron, the MCP as postgres) passes;
     a JWT caller must be an active incident recipient or an admin/god. */
  IF v_uid IS NOT NULL AND COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ca_incident_recipients r WHERE r.user_id = v_uid AND r.active
      UNION ALL
      SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.role IN ('admin','god')
    ) INTO v_mgmt;
    IF NOT v_mgmt THEN
      RAISE EXCEPTION 'management_only' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH m AS (
    SELECT 'chip_transactions'::text AS source,
           ct.created_at AS moved_at,
           COALESCE(
             CASE WHEN length(ct.metadata->>'performed_by') = 36 AND ct.metadata->>'performed_by' ~ '^[0-9a-fA-F-]+$'
                  THEN (ct.metadata->>'performed_by')::uuid END,
             CASE WHEN length(ct.metadata->>'actor_id') = 36 AND ct.metadata->>'actor_id' ~ '^[0-9a-fA-F-]+$'
                  THEN (ct.metadata->>'actor_id')::uuid END,
             CASE WHEN length(ct.metadata->>'minted_by') = 36 AND ct.metadata->>'minted_by' ~ '^[0-9a-fA-F-]+$'
                  THEN (ct.metadata->>'minted_by')::uuid END,
             CASE WHEN ct.transaction_type ~ '(claim|clawback|reversal|collect|removal|debit)'
                  THEN ct.to_user_id ELSE ct.from_user_id END,
             CASE WHEN length(ct.metadata->>'club_owner_id') = 36 AND ct.metadata->>'club_owner_id' ~ '^[0-9a-fA-F-]+$'
                  THEN (ct.metadata->>'club_owner_id')::uuid END
           ) AS actor,
           ct.transaction_type AS action,
           COALESCE(ct.metadata->>'source_wallet',
                    CASE WHEN ct.transaction_type IN ('club_bank_send','treasury_debit') THEN 'club_bank'
                         WHEN ct.transaction_type IN ('agent_wallet_send','agent_wallet_self_stake') THEN 'agent_wallet'
                         WHEN ct.transaction_type IN ('union_transfer','treasury_credit','union_pnl_payout') THEN 'union_bank'
                         WHEN ct.transaction_type IN ('treasury_mint','mint','club_opening_grant','chip_purchase','bonus','chip_credit','admin_adjustment') THEN 'issuance'
                         WHEN ct.from_user_id IS NOT NULL THEN 'member_wallet'
                         ELSE 'club_treasury' END) AS from_account,
           ct.from_user_id AS from_entity,
           COALESCE(ct.metadata->>'destination', ct.metadata->>'target_wallet',
                    CASE WHEN ct.transaction_type IN ('club_bank_claim','club_bank_reversal','treasury_mint','mint','club_opening_grant','union_transfer','treasury_credit') THEN 'club_bank'
                         WHEN ct.transaction_type IN ('agent_claim','agent_wallet_claim','agent_wallet_claim_back') THEN 'agent_wallet'
                         WHEN ct.transaction_type = 'union_pnl_collect' THEN 'union_bank'
                         WHEN ct.to_user_id IS NOT NULL THEN 'member_wallet'
                         ELSE 'club_treasury' END) AS to_account,
           ct.to_user_id AS to_entity,
           ct.amount,
           ct.club_id,
           COALESCE(CASE WHEN length(ct.metadata->>'union_id') = 36 AND ct.metadata->>'union_id' ~ '^[0-9a-fA-F-]+$'
                         THEN (ct.metadata->>'union_id')::uuid END, c.union_id) AS union_id,
           COALESCE(ct.metadata->>'op_id', ct.metadata->>'idempotency_key', ct.metadata->>'settlement_id', ct.id::text) AS reference,
           COALESCE(ct.metadata, '{}'::jsonb) AS metadata,
           ct.id AS row_id
      FROM public.chip_transactions ct
      LEFT JOIN public.clubs c ON c.id = ct.club_id
     WHERE ct.created_at >= p_since
       AND ct.amount > 0
       AND ct.transaction_type IN (
         'club_bank_send','club_bank_claim','club_bank_reversal',
         'agent_wallet_send','agent_wallet_claim','agent_wallet_claim_back','agent_claim','agent_send',
         'promo_send','promo_claim','agent_wallet_self_stake',
         'club_opening_grant','treasury_mint','mint','treasury_credit','treasury_debit',
         'admin_adjustment','admin_removal','chip_credit','chip_debit',
         'union_transfer','union_pnl_collect','union_pnl_payout',
         'default_mint_correction','clawback','union_clawback','promo_closed_on_union_join',
         'peer_transfer','chip_purchase','bonus','correction','reversal','adjustment')
    UNION ALL
    SELECT 'union_wallet_transactions',
           u.created_at,
           u.created_by,
           u.tx_type || '/' || u.direction,
           CASE WHEN u.direction = 'debit' THEN 'union_' || u.wallet ELSE COALESCE(u.tx_type, 'external') END,
           CASE WHEN u.direction = 'debit' THEN u.union_id ELSE u.club_id END,
           CASE WHEN u.direction = 'credit' THEN 'union_' || u.wallet ELSE COALESCE(u.tx_type, 'external') END,
           CASE WHEN u.direction = 'credit' THEN u.union_id ELSE u.club_id END,
           u.amount,
           u.club_id,
           u.union_id,
           COALESCE(u.period_id::text, u.id::text),
           '{}'::jsonb,
           u.id
      FROM public.union_wallet_transactions u
     WHERE u.created_at >= p_since
       AND u.amount > 0
       AND u.tx_type IN (
         'manual_transfer','send_to_club','owner_deposit','adjustment','clawback','union_clawback',
         'settlement','statement_paid','rakeback','spin_reserve_seed','player_pnl_pay','player_pnl_collect',
         'correction','reversal','mint','burn')
    UNION ALL
    SELECT 'ca_mint_ledger',
           ml.created_at,
           ml.performed_by,
           ml.action || '/' || ml.asset,
           CASE WHEN ml.action = 'mint' THEN 'issuance_reserve' ELSE ml.holder_type END,
           CASE WHEN ml.action = 'mint' THEN NULL ELSE ml.holder_id END,
           CASE WHEN ml.action = 'mint' THEN ml.holder_type ELSE 'issuance_reserve' END,
           CASE WHEN ml.action = 'mint' THEN ml.holder_id ELSE NULL END,
           ml.amount,
           NULL::uuid,
           NULL::uuid,
           COALESCE(ml.op_id, ml.id::text),
           '{}'::jsonb,
           ml.id
      FROM public.ca_mint_ledger ml
     WHERE ml.created_at >= p_since
       AND ml.amount > 0
    UNION ALL
    SELECT 'chip_ledger',
           l.created_at,
           l.performed_by,
           l.category,
           l.from_type,
           l.from_entity_id,
           l.to_type,
           l.to_entity_id,
           l.amount,
           l.club_id,
           l.union_id,
           COALESCE(l.idempotency_key, l.correlation_id::text, l.id::text),
           COALESCE(l.metadata, '{}'::jsonb),
           l.id
      FROM public.chip_ledger l
     WHERE l.created_at >= p_since
       AND l.amount > 0
       AND (
         l.category IN ('mint','club_bank_send','club_bank_claim','agent_send','agent_claim',
                        'union_settlement','union_send','correction','reversal')
         OR (l.category = 'adjustment' AND COALESCE(l.description, '') NOT LIKE 'auto-%')
       )
  )
  SELECT m.source,
         m.moved_at,
         m.actor,
         m.action,
         m.from_account,
         m.from_entity,
         m.to_account,
         m.to_entity,
         m.amount,
         m.club_id,
         m.union_id,
         m.reference,
         NOT EXISTS (
           SELECT 1
             FROM public.ca_manual_adjustments a
            WHERE a.status = 'approved'
              AND a.approver IS NOT NULL
              AND a.approver IS DISTINCT FROM m.actor
              AND (
                a.id::text = m.reference
                OR a.id::text = m.metadata->>'adjustment_id'
                OR (a.target_id IN (m.from_entity, m.to_entity, m.club_id, m.union_id)
                    AND a.amount = m.amount
                    AND a.approved_at BETWEEN m.moved_at - interval '7 days' AND m.moved_at + interval '1 hour')
              )
         ) AS single_actor,
         m.row_id
    FROM m
   ORDER BY m.amount DESC, m.moved_at DESC;
END
$_$;


ALTER FUNCTION public.fn_ca_adjustments_report(p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_adjustments_report(p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_adjustments_report(p_since timestamp with time zone) IS 'Chip-std phase 2 lane 2.5 (F10, advisory): every actor-initiated hierarchy movement, mint, clawback and correction since p_since, with a single_actor flag. Read side only - no threshold is enforced until Dan sets one (roadmap decision 6). service_role only, plus the fn_ca_post_correction management gate for a JWT caller.';


--
-- Name: fn_ca_agent_payables(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_agent_payables(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows      jsonb;
  v_owed      numeric;
  v_count     bigint;
  v_agents    integer;
  v_oldest    timestamptz;
  v_checked   timestamptz;
  -- 500, up from 200: the read comes off the rollup now and costs the same
  -- at any size. Only 32 agents exist at this club today.
  v_cap constant integer := 500;
BEGIN
  IF NOT fn_ca_can_manage_agents(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  WITH ranked AS (
    SELECT a.id,
           a.user_id,
           a.role,
           coalesce(a.status, 'active') AS status,
           coalesce(a.is_prepaid, false) AS is_prepaid,
           coalesce(a.credit_limit, 0)   AS credit_limit,
           coalesce(a.credit_used, 0)    AS credit_used,
           coalesce(a.commission_rate, 0) AS commission_rate,
           coalesce(a.player_rakeback_rate, 0) AS player_rakeback_rate,
           coalesce(a.total_players, 0)  AS total_players,
           coalesce(o.owed, 0)           AS owed,
           coalesce(o.rows_behind, 0)    AS rows_behind,
           o.oldest_unsettled            AS oldest,
           o.updated_at                  AS checked,
           coalesce(
             nullif(btrim(pr.display_name), ''),
             nullif(btrim(pr.alias), ''),
             nullif(btrim(pr.username), ''),
             'Member') AS name,
           row_number() OVER (ORDER BY coalesce(o.owed, 0) DESC, a.created_at) AS rn
      FROM agents a
      LEFT JOIN agent_commission_unsettled_rollup o
             ON o.club_id = p_club_id AND o.user_id = a.user_id
      LEFT JOIN profiles pr ON pr.id = a.user_id
     WHERE a.club_id = p_club_id
  )
  SELECT
    coalesce(jsonb_agg(
      jsonb_build_object(
        'agent_id', r.id,
        'user_id', r.user_id,
        'name', r.name,
        'role', r.role,
        'status', r.status,
        'is_prepaid', r.is_prepaid,
        'credit_limit', r.credit_limit,
        'credit_used', r.credit_used,
        'credit_available', greatest(r.credit_limit - r.credit_used, 0),
        'utilization', CASE WHEN r.credit_limit > 0
                            THEN round(r.credit_used / r.credit_limit, 4)
                            ELSE 0 END,
        'commission_rate', r.commission_rate,
        'player_rakeback_rate', r.player_rakeback_rate,
        'total_players', r.total_players,
        'owed', round(r.owed, 2),
        'rows_behind', r.rows_behind,
        'oldest_unsettled', r.oldest)
      ORDER BY r.rn) FILTER (WHERE r.rn <= v_cap), '[]'::jsonb),
    count(*)::integer,
    round(sum(r.owed), 2),
    sum(r.rows_behind),
    min(r.oldest),
    max(r.checked)
    INTO v_rows, v_agents, v_owed, v_count, v_oldest, v_checked
  FROM ranked r;

  RETURN jsonb_build_object(
    'agents', coalesce(v_agents, 0),
    'cap', v_cap,
    'total_owed', coalesce(v_owed, 0),
    'total_rows', coalesce(v_count, 0),
    'oldest_unsettled', v_oldest,
    'rollup_checked_at', v_checked,
    'rows', v_rows,
    'generated_at', now());
END;
$$;


ALTER FUNCTION public.fn_ca_agent_payables(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_agent_payables(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_agent_payables(p_club_id uuid) IS 'What a club owes each of its agents, from agent_commission_unsettled_rollup. Capped at 500 rows with totals over all. The superseded estimate came down 2026-09-04. Gated by fn_ca_can_manage_agents.';


--
-- Name: fn_ca_alarm_drill(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_alarm_drill() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_results jsonb := '[]'::jsonb;
  v_failing text[] := '{}';
  v_ok boolean; v_note text; v_n int; v_sev text;
  c_midway_club constant uuid := 'a41434bb-8d0c-400a-8f0d-e8b3d65afed4';
  c_cert_user  constant uuid := '00000000-0000-0000-0000-000000000017';
  c_other_club constant uuid := 'd08cf7f1-d50b-4e44-851c-8369ebbb706f';
BEGIN
  SET LOCAL statement_timeout = '110s';
  SET LOCAL lock_timeout = '4s';

  -- 1. negative balance fires
  v_ok := false; v_note := '';
  BEGIN
    PERFORM set_config('app.ledger_autoskip_club_members','1',true);
    UPDATE club_members SET chip_balance = -3
     WHERE club_id = c_midway_club AND user_id = c_cert_user;
    PERFORM public.fn_ca_negative_balance_watch();
    SELECT count(*) INTO v_n FROM ca_drift_incidents
     WHERE dedupe_key LIKE 'negative-balance:club_members:%' AND status <> 'resolved';
    v_ok := v_n > 0;
    RAISE EXCEPTION 'CA_DRILL_UNWIND';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'CA_DRILL_UNWIND' THEN v_ok := false; v_note := left(SQLERRM, 120); END IF;
  END;
  v_results := v_results || jsonb_build_object('check','negative_balance','pass',v_ok,'note',v_note);
  IF NOT v_ok THEN v_failing := array_append(v_failing, 'negative_balance'); END IF;

  -- 2. suspense regression fires
  v_ok := false; v_note := '';
  BEGIN
    INSERT INTO chip_ledger (performed_by, from_type, to_type, amount, category, description)
    VALUES ('2d1cd6c3-5700-4af9-a271-d4863fdab20d','settlement_suspense','club_treasury',
            60.00,'adjustment','alarm drill synthetic suspense');
    PERFORM public.fn_ca_suspense_regression_check();
    SELECT count(*) INTO v_n FROM ca_drift_incidents
     WHERE dedupe_key LIKE 'suspense-regression:%' AND status <> 'resolved';
    v_ok := v_n > 0;
    RAISE EXCEPTION 'CA_DRILL_UNWIND';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'CA_DRILL_UNWIND' THEN v_ok := false; v_note := left(SQLERRM, 120); END IF;
  END;
  v_results := v_results || jsonb_build_object('check','suspense_regression','pass',v_ok,'note',v_note);
  IF NOT v_ok THEN v_failing := array_append(v_failing, 'suspense_regression'); END IF;

  -- 3. mint velocity fires
  v_ok := false; v_note := '';
  BEGIN
    PERFORM set_config('app.ledger_category','mint',true);
    INSERT INTO chip_ledger (performed_by, from_type, to_type, to_entity_id, amount, category, description)
    VALUES ('2d1cd6c3-5700-4af9-a271-d4863fdab20d','issuance_reserve','club_treasury',
            c_other_club, 300000.00, 'mint', 'alarm drill synthetic mint');
    PERFORM public.fn_ca_mint_velocity_watch();
    SELECT count(*) INTO v_n FROM ca_drift_incidents
     WHERE dedupe_key LIKE 'mint-velocity:%' AND status <> 'resolved';
    v_ok := v_n > 0;
    RAISE EXCEPTION 'CA_DRILL_UNWIND';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'CA_DRILL_UNWIND' THEN v_ok := false; v_note := left(SQLERRM, 120); END IF;
  END;
  v_results := v_results || jsonb_build_object('check','mint_velocity','pass',v_ok,'note',v_note);
  IF NOT v_ok THEN v_failing := array_append(v_failing, 'mint_velocity'); END IF;

  -- 4. a raise in Midway scope files critical AND notifies; out of scope stays out
  v_ok := false; v_note := '';
  BEGIN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_alarm_drill','unknown','critical','alarm-drill-raise-probe', 1.00,
      NULL, NULL, 'ledger', 'drill', NULL, c_midway_club);
    SELECT count(*) INTO v_n FROM ca_drift_incidents
     WHERE dedupe_key = 'alarm-drill-raise-probe' AND severity = 'critical' AND status <> 'resolved';
    IF v_n = 1 THEN
      SELECT count(*) INTO v_n FROM notifications
       WHERE type='financial_incident' AND created_at > now() - interval '5 seconds';
      IF v_n > 0 THEN
        PERFORM public.fn_ca_raise_drift_incident(
          'fn_ca_alarm_drill','unknown','critical','alarm-drill-scope-probe', 1.00,
          NULL, NULL, 'ledger', 'drill', NULL, c_other_club);
        SELECT count(*) INTO v_n FROM ca_drift_incidents
         WHERE dedupe_key = 'alarm-drill-scope-probe';
        v_ok := v_n = 0;  -- the other-club raise must be filtered
        IF NOT v_ok THEN v_note := 'scope filter did not filter'; END IF;
      ELSE v_note := 'raise did not notify'; END IF;
    ELSE v_note := 'raise did not file critical'; END IF;
    RAISE EXCEPTION 'CA_DRILL_UNWIND';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'CA_DRILL_UNWIND' THEN v_ok := false; v_note := left(SQLERRM, 120); END IF;
  END;
  v_results := v_results || jsonb_build_object('check','raise_scope_and_notify','pass',v_ok,'note',v_note);
  IF NOT v_ok THEN v_failing := array_append(v_failing, 'raise_scope_and_notify'); END IF;

  -- 5. conservation alerts map to info (quarantine intact)
  v_ok := false; v_note := '';
  BEGIN
    INSERT INTO financial_alerts (source, severity, message, context)
    VALUES ('fn_spin_chip_conservation_check','critical',
            'alarm drill conservation probe ' || clock_timestamp()::text, '{"minted_games":1}'::jsonb);
    SELECT severity INTO v_sev FROM ca_drift_incidents
     WHERE source = 'financial_alerts:fn_spin_chip_conservation_check'
     ORDER BY detected_at DESC LIMIT 1;
    v_ok := v_sev = 'info';
    IF NOT v_ok THEN v_note := 'mapped severity=' || COALESCE(v_sev,'NONE'); END IF;
    RAISE EXCEPTION 'CA_DRILL_UNWIND';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'CA_DRILL_UNWIND' THEN v_ok := false; v_note := left(SQLERRM, 120); END IF;
  END;
  v_results := v_results || jsonb_build_object('check','conservation_quarantine','pass',v_ok,'note',v_note);
  IF NOT v_ok THEN v_failing := array_append(v_failing, 'conservation_quarantine'); END IF;

  -- 6. journals are append-only (chip + diamond)
  v_ok := false; v_note := '';
  BEGIN
    UPDATE chip_ledger SET amount = amount + 1
     WHERE id = (SELECT id FROM chip_ledger ORDER BY created_at DESC LIMIT 1);
    v_note := 'chip_ledger accepted a rewrite';
    RAISE EXCEPTION 'CA_DRILL_UNWIND';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM ILIKE '%append-only%' THEN
      BEGIN
        DELETE FROM diamond_transactions
         WHERE id = (SELECT id FROM diamond_transactions LIMIT 1);
        v_note := 'diamond_transactions accepted a delete';
        RAISE EXCEPTION 'CA_DRILL_UNWIND';
      EXCEPTION WHEN OTHERS THEN
        IF SQLERRM ILIKE '%append-only%' THEN v_ok := true;
        ELSIF SQLERRM <> 'CA_DRILL_UNWIND' THEN v_note := left(SQLERRM, 120); END IF;
      END;
    ELSIF SQLERRM <> 'CA_DRILL_UNWIND' THEN v_note := left(SQLERRM, 120); END IF;
  END;
  v_results := v_results || jsonb_build_object('check','journals_append_only','pass',v_ok,'note',v_note);
  IF NOT v_ok THEN v_failing := array_append(v_failing, 'journals_append_only'); END IF;

  -- 7. deleting a balance-holding row journals its burn
  v_ok := false; v_note := '';
  BEGIN
    DELETE FROM club_members WHERE club_id = c_midway_club AND user_id = c_cert_user;
    SELECT count(*) INTO v_n FROM chip_ledger
     WHERE created_at > now() - interval '5 seconds'
       AND to_type = 'chip_retirement' AND category = 'burn' AND from_type = 'player_wallet';
    v_ok := v_n > 0;
    IF NOT v_ok THEN v_note := 'delete journaled no burn'; END IF;
    RAISE EXCEPTION 'CA_DRILL_UNWIND';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'CA_DRILL_UNWIND' THEN v_ok := false; v_note := left(SQLERRM, 120); END IF;
  END;
  v_results := v_results || jsonb_build_object('check','delete_journals_burn','pass',v_ok,'note',v_note);
  IF NOT v_ok THEN v_failing := array_append(v_failing, 'delete_journals_burn'); END IF;

  -- 8. settlement state machine refuses an illegal jump
  v_ok := false; v_note := '';
  BEGIN
    INSERT INTO ca_settlements (id, settlement_type, external_ref, state, totals)
    VALUES (gen_random_uuid(), 'union_rakeback_close',
            'alarm-drill:' || clock_timestamp()::text, 'open', '{}'::jsonb);
    UPDATE ca_settlements SET state = 'final'
     WHERE external_ref LIKE 'alarm-drill:%' AND state = 'open';
    v_note := 'an illegal open to final jump was accepted';
    RAISE EXCEPTION 'CA_DRILL_UNWIND';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM ILIKE '%invalid settlement transition%' THEN v_ok := true;
    ELSIF SQLERRM <> 'CA_DRILL_UNWIND' THEN v_note := left(SQLERRM, 120); END IF;
  END;
  v_results := v_results || jsonb_build_object('check','settlement_guard','pass',v_ok,'note',v_note);
  IF NOT v_ok THEN v_failing := array_append(v_failing, 'settlement_guard'); END IF;

  -- 9. corrections refuse to post without linkage
  v_ok := false; v_note := '';
  BEGIN
    PERFORM set_config('request.jwt.claims', '{"role":"service_role"}', true);
    v_ok := (public.fn_ca_post_correction('club_treasury', NULL, 'player_wallet', NULL,
             1.00, 'alarm drill probing the linkage requirement') ->> 'reason')
            = 'linkage_required_incident_or_write_failure';
    RAISE EXCEPTION 'CA_DRILL_UNWIND';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'CA_DRILL_UNWIND' THEN v_ok := false; v_note := left(SQLERRM, 120); END IF;
  END;
  v_results := v_results || jsonb_build_object('check','correction_linkage','pass',v_ok,'note',v_note);
  IF NOT v_ok THEN v_failing := array_append(v_failing, 'correction_linkage'); END IF;

  -- record; page ONLY if an alarm stayed silent
  INSERT INTO public.ca_alarm_drills (pass, failing, results)
  VALUES (cardinality(v_failing) = 0, NULLIF(v_failing, '{}'), v_results);

  IF cardinality(v_failing) > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_alarm_drill', 'unknown', 'critical',
      'alarm-drill-failed:' || to_char(now(), 'YYYY-MM-DD'),
      cardinality(v_failing), NULL, NULL, 'reporting', 'ca_alarm_drills',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'THE ALARM DRILL FAILED: ' || array_to_string(v_failing, ', ')
        || ' stayed silent when their drift condition was created. The detectors need repair before anything else.',
      true, jsonb_build_object('failing', v_failing));
  END IF;

  RETURN jsonb_build_object('pass', cardinality(v_failing) = 0,
                            'failing', v_failing, 'results', v_results);
END $$;


ALTER FUNCTION public.fn_ca_alarm_drill() OWNER TO postgres;

--
-- Name: fn_ca_alert_resolution_reaches_the_incident(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_alert_resolution_reaches_the_incident() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_state text; v_msg text;
BEGIN
  IF NOT COALESCE(NEW.resolved,false) OR COALESCE(OLD.resolved,false) THEN
    RETURN NEW;
  END IF;
  UPDATE public.ca_drift_incidents i
     SET status      = 'resolved',
         resolved_at = COALESCE(NEW.resolved_at, now()),
         correction_ref = COALESCE(NULLIF(i.correction_ref,''),
                                   'verified: closed with financial alert ' || NEW.id::text),
         root_cause  = COALESCE(NULLIF(i.root_cause,''),
                        'This incident is a mirror of financial alert ' || NEW.id::text
                        || ', raised by ' || COALESCE(NEW.source,'an unnamed source')
                        || '. The condition it describes was diagnosed and closed on that '
                        || 'alert; this row exists only because the alert was copied onto '
                        || 'the drift board when it was raised.'),
         resolution  = COALESCE(NULLIF(i.resolution,'') || ' | ', '')
                       || 'Closed with the financial alert it mirrors ('
                       || NEW.id::text || '): '
                       || COALESCE(NULLIF(NEW.resolution,''), 'no note given on the alert')
   WHERE i.status <> 'resolved'
     AND i.metadata->>'alert_id' ~ '^[0-9a-fA-F-]{36}$'
     AND (i.metadata->>'alert_id')::uuid = NEW.id;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  /* Never roll back the resolve that triggered us - but never disappear
     either. RAISE WARNING alone is how this defect hid from its own author. */
  GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
  BEGIN
    INSERT INTO public.ca_incident_file_failures
      (source, dedupe_key, classification, severity, discrepancy, sqlstate, message)
    VALUES ('fn_ca_alert_resolution_reaches_the_incident',
            'propagate:alert->incident:' || NEW.id::text,
            'unknown', 'warning', 0, v_state,
            'a resolved alert did not close the incident mirroring it: ' || v_msg);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RAISE WARNING 'fn_ca_alert_resolution_reaches_the_incident failed: %', v_msg;
  RETURN NEW;
END $_$;


ALTER FUNCTION public.fn_ca_alert_resolution_reaches_the_incident() OWNER TO postgres;

--
-- Name: fn_ca_applied_migrations(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_applied_migrations(p_since text DEFAULT NULL::text) RETURNS TABLE(version text, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  -- version and name ONLY. `statements` is deliberately not returned: it is the
  -- full DDL of every migration ever applied and this function exists to be
  -- called by CI, not to hand the schema's history to whoever asks.
  select m.version, m.name
    from supabase_migrations.schema_migrations m
   where m.version ~ '^[0-9]+$'
     and (p_since is null or m.version >= p_since)
   order by m.version;
$_$;


ALTER FUNCTION public.fn_ca_applied_migrations(p_since text) OWNER TO postgres;

--
-- Name: fn_ca_apply_prize_guarantee_core(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_apply_prize_guarantee_core(p_tournament_id uuid, p_source text DEFAULT 'engine'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t                    record;
  v_after                record;
  v_overlay_row          public.tournament_guarantee_overlays%ROWTYPE;
  v_result               jsonb;
  v_pool_before          numeric := 0;
  v_guarantee            numeric := 0;
  v_final                numeric := 0;
  v_overlay              numeric := 0;
  v_escrow_before        numeric := 0;
  v_escrow_after         numeric := 0;
  v_escrow_before_found  boolean := false;
  v_escrow_after_found   boolean := false;
  v_escrow_enforced      boolean := false;
  v_union                uuid;
  v_expected_bank_type   text;
  v_expected_bank_entity uuid;
  v_club_bank_before     numeric := 0;
  v_bank_before          numeric := 0;
  v_bank_after           numeric := 0;
  v_bank_row_found       boolean := false;
  v_ledger_inserted      integer := 0;
  v_old_category         text;
  v_old_counterparty     text;
  v_old_entity           text;
  v_old_tournament       text;
  v_failure              text;
  v_failure_state        text;
BEGIN
  IF p_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_id_required',
                              'retryable', false);
  END IF;

  SELECT t.id, t.club_id, t.name, t.status, t.union_id,
         COALESCE(t.is_private, false) AS is_private,
         round(COALESCE(t.prize_pool, 0), 2) AS pool,
         round(COALESCE(t.guaranteed_prize, 0), 2) AS guarantee,
         COALESCE(t.prize_pool_finalized, false) AS finalized
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found',
                              'retryable', false);
  END IF;

  v_pool_before := v_t.pool;
  v_guarantee := v_t.guarantee;
  v_final := GREATEST(v_pool_before, v_guarantee);
  v_overlay := round(v_final - v_pool_before, 2);

  /* Finalized is irreversible. A published pool that was finalized below its
     guarantee is evidence requiring an explicit, reviewed correction; the
     runtime must never reopen and silently reprice it. */
  IF v_t.finalized AND v_pool_before + 0.005 < v_guarantee THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'finalized_guarantee_is_below_published_floor',
      'prize_pool', v_pool_before, 'guaranteed_prize', v_guarantee,
      'retryable', false);
  END IF;

  SELECT round(COALESCE(e.prize_balance, 0), 2)
    INTO v_escrow_before
    FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id
   FOR UPDATE;
  v_escrow_before_found := FOUND;

  BEGIN
    IF v_overlay > 0 THEN
      /* Lock and snapshot the real bank before calling the legacy debit core.
         Its overlay row describes the movement; only the live before/after
         balance proves that movement happened exactly once. */
      SELECT round(COALESCE(c.chip_treasury, 0), 2)
        INTO v_club_bank_before
        FROM public.clubs c
       WHERE c.id = v_t.club_id
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = 'guarantee host club does not exist',
                              ERRCODE = '23503';
      END IF;

      /* Funding ownership was captured on the event. A later club union move
         cannot redirect this liability, and a private event always belongs to
         its host club even when that club is currently union-affiliated. */
      v_union := CASE WHEN v_t.is_private THEN NULL ELSE v_t.union_id END;
      IF v_union IS NOT NULL THEN
        SELECT round(COALESCE(uw.chip_balance, 0), 2)
          INTO v_bank_before
          FROM public.union_wallets uw
         WHERE uw.union_id = v_union
         FOR UPDATE;
        v_bank_row_found := FOUND;
      END IF;
      IF v_bank_row_found THEN
        v_expected_bank_type := 'union';
        v_expected_bank_entity := v_union;
      ELSE
        v_expected_bank_type := 'club';
        v_expected_bank_entity := v_t.club_id;
        v_bank_before := v_club_bank_before;
      END IF;
      IF v_bank_before + 0.005 < v_overlay THEN
        RAISE EXCEPTION USING
          MESSAGE = format(
            'guarantee bank holds %s but the advertised overlay requires %s',
            v_bank_before, v_overlay),
          ERRCODE = '23514';
      END IF;
    END IF;

    v_old_category := current_setting('app.ledger_category', true);
    v_old_counterparty := current_setting('app.ledger_counterparty', true);
    v_old_entity := current_setting('app.ledger_counterparty_entity', true);
    v_old_tournament := current_setting('app.ledger_tournament', true);
    PERFORM set_config('app.ledger_tournament', p_tournament_id::text, true);

    v_result := public.fn_apply_prize_guarantee_before_atomic_proof(
      p_tournament_id, COALESCE(NULLIF(btrim(p_source), ''), 'engine'));
    IF NOT COALESCE((v_result->>'ok')::boolean, false) THEN
      RAISE EXCEPTION USING MESSAGE = COALESCE(v_result->>'reason', 'guarantee core refused'),
                            ERRCODE = '23514';
    END IF;
    IF v_overlay > 0 AND COALESCE((v_result->>'already_funded')::boolean, false) THEN
      RAISE EXCEPTION USING
        MESSAGE = 'an existing overlay claim did not prove this short pool was funded',
        ERRCODE = '23514';
    END IF;

    IF v_overlay > 0 THEN
      SELECT * INTO v_overlay_row
        FROM public.tournament_guarantee_overlays o
       WHERE o.tournament_id = p_tournament_id
       FOR UPDATE;
      IF NOT FOUND
         OR v_overlay_row.club_id IS DISTINCT FROM v_t.club_id
         OR abs(round(v_overlay_row.amount, 2) - v_overlay) > 0.005
         OR abs(round(v_overlay_row.pool_before, 2) - v_pool_before) > 0.005
         OR abs(round(v_overlay_row.pool_after, 2) - v_final) > 0.005
         OR v_overlay_row.bank_type IS DISTINCT FROM v_expected_bank_type
         OR v_overlay_row.bank_entity_id IS DISTINCT FROM v_expected_bank_entity
         OR v_overlay_row.treasury_after IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'guarantee overlay claim does not match its bank debit and pool',
                              ERRCODE = '23514';
      END IF;

      IF v_expected_bank_type = 'union' THEN
        SELECT round(COALESCE(uw.chip_balance, 0), 2)
          INTO v_bank_after
          FROM public.union_wallets uw
         WHERE uw.union_id = v_expected_bank_entity
         FOR UPDATE;
      ELSE
        SELECT round(COALESCE(c.chip_treasury, 0), 2)
          INTO v_bank_after
          FROM public.clubs c
         WHERE c.id = v_expected_bank_entity
         FOR UPDATE;
      END IF;
      IF NOT FOUND
         OR abs(v_bank_after - (v_bank_before - v_overlay)) > 0.005
         OR abs(round(v_overlay_row.treasury_after, 2) - v_bank_after) > 0.005 THEN
        RAISE EXCEPTION USING MESSAGE = 'guarantee bank did not debit the exact overlay',
                              ERRCODE = '23514';
      END IF;

      /* The legacy core's balance UPDATE produces an auto-ledger twin. Live
         escrow deliberately ignores auto-ledger overlay rows, so publish the
         one explicit, deterministic bank -> prize-liability leg it requires.
         This insert is in the same subtransaction as the bank debit. */
      INSERT INTO public.chip_ledger (
        performed_by, from_type, from_entity_id, to_type, to_entity_id,
        amount, category, club_id, tournament_id, idempotency_key, description)
      VALUES (
        COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
        CASE WHEN v_expected_bank_type = 'union' THEN 'union_bank' ELSE 'club_treasury' END,
        v_expected_bank_entity, 'prize_liability', p_tournament_id,
        v_overlay, 'overlay', v_t.club_id, p_tournament_id,
        'tourney:' || p_tournament_id::text || ':guarantee_overlay',
        'Guarantee Overlay Funded For ' || COALESCE(v_t.name, p_tournament_id::text))
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
      GET DIAGNOSTICS v_ledger_inserted = ROW_COUNT;
      IF v_ledger_inserted <> 1 THEN
        RAISE EXCEPTION USING MESSAGE = 'guarantee overlay journal key already exists unexpectedly',
                              ERRCODE = '23505';
      END IF;
    END IF;

    SELECT t.status, round(COALESCE(t.prize_pool, 0), 2) AS pool,
           round(COALESCE(t.guaranteed_prize, 0), 2) AS guarantee,
           COALESCE(t.prize_pool_finalized, false) AS finalized
      INTO v_after
      FROM public.tournaments t
     WHERE t.id = p_tournament_id
     FOR UPDATE;
    IF NOT FOUND OR NOT v_after.finalized
       OR abs(v_after.pool - v_final) > 0.005
       OR v_after.pool + 0.005 < v_after.guarantee THEN
      RAISE EXCEPTION USING MESSAGE = 'guarantee core did not publish the exact funded final pool',
                            ERRCODE = '23514';
    END IF;

    SELECT COALESCE(e.enforced, false), round(COALESCE(e.prize_balance, 0), 2)
      INTO v_escrow_enforced, v_escrow_after
      FROM public.tournament_escrow e
     WHERE e.tournament_id = p_tournament_id
     FOR UPDATE;
    v_escrow_after_found := FOUND;
    IF v_overlay > 0 AND (
         NOT v_escrow_after_found OR NOT v_escrow_enforced
         OR abs((v_escrow_after - CASE WHEN v_escrow_before_found
                                      THEN v_escrow_before ELSE 0 END) - v_overlay) > 0.005
       ) THEN
      RAISE EXCEPTION USING MESSAGE = 'guarantee bank debit did not credit live escrow exactly',
                            ERRCODE = '23514';
    END IF;

    PERFORM set_config('app.ledger_category', COALESCE(v_old_category, ''), true);
    PERFORM set_config('app.ledger_counterparty', COALESCE(v_old_counterparty, ''), true);
    PERFORM set_config('app.ledger_counterparty_entity', COALESCE(v_old_entity, ''), true);
    PERFORM set_config('app.ledger_tournament', COALESCE(v_old_tournament, ''), true);
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_failure = MESSAGE_TEXT,
                            v_failure_state = RETURNED_SQLSTATE;
  END;

  IF v_failure IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'atomic_guarantee_funding_aborted',
      'detail', v_failure, 'sqlstate', v_failure_state,
      'prize_pool', v_pool_before, 'guaranteed_prize', v_guarantee,
      'retryable', v_failure_state IN ('40001', '40P01', '55P03'));
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'prize_pool', v_after.pool,
    'overlay', v_overlay, 'bank_type', v_expected_bank_type,
    'bank_entity_id', v_expected_bank_entity,
    'bank_before', CASE WHEN v_overlay > 0 THEN v_bank_before ELSE NULL END,
    'bank_after', CASE WHEN v_overlay > 0 THEN v_bank_after ELSE NULL END,
    'treasury_after', CASE WHEN v_overlay > 0 THEN v_bank_after ELSE NULL END,
    'escrow_before', CASE WHEN v_escrow_before_found THEN v_escrow_before ELSE NULL END,
    'escrow_after', CASE WHEN v_escrow_after_found THEN v_escrow_after ELSE NULL END,
    'overlay_journaled', v_overlay = 0 OR
      (v_ledger_inserted = 1 AND v_escrow_after_found AND v_escrow_enforced),
    'already_finalized', v_t.finalized AND v_overlay = 0,
    'retryable', false);
END;
$$;


ALTER FUNCTION public.fn_ca_apply_prize_guarantee_core(p_tournament_id uuid, p_source text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_apply_prize_guarantee_core(p_tournament_id uuid, p_source text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_apply_prize_guarantee_core(p_tournament_id uuid, p_source text) IS 'Atomic guarantee proof gate: the bank debit, exact overlay claim, explicit journal leg, live escrow credit and finalized published pool all commit together or none do.';


--
-- Name: fn_ca_approve_manual_adjustment(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_approve_manual_adjustment(p_id uuid, p_approver uuid DEFAULT NULL::uuid, p_approver_label text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_approver uuid := COALESCE(p_approver, auth.uid());
  v_label    text := COALESCE(NULLIF(btrim(p_approver_label), ''),
                              NULLIF(current_setting('application_name', true), ''),
                              session_user::text);
  v_row      public.ca_manual_adjustments%ROWTYPE;
BEGIN
  IF NOT public.fn_ca_caller_is_management() THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'not_management');
  END IF;
  IF v_approver IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'approver_required');
  END IF;

  SELECT * INTO v_row FROM public.ca_manual_adjustments WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'not_found', 'adjustment_id', p_id);
  END IF;
  IF v_row.status <> 'proposed' THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'not_proposed',
      'adjustment_id', p_id, 'status', v_row.status);
  END IF;

  -- Four eyes. The CHECK would refuse this too; saying why is the point.
  IF v_approver = v_row.actor THEN
    PERFORM public.fn_raise_server_financial_alert(
      'warning', 'ca_manual_adjustments',
      format('Self-approval REFUSED: %s proposed adjustment %s and tried to approve it', v_label, p_id),
      jsonb_build_object('adjustment_id', p_id, 'actor', v_row.actor, 'approver', v_approver,
                         'approver_label', v_label),
      'adj-self-approval:' || p_id::text);
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'four_eyes_violated',
      'adjustment_id', p_id, 'actor', v_row.actor);
  END IF;

  UPDATE public.ca_manual_adjustments
     SET status = 'approved', approver = v_approver, approver_label = v_label,
         approved_at = now(), decision_note = NULLIF(btrim(p_note), '')
   WHERE id = p_id
   RETURNING * INTO v_row;

  PERFORM public.fn_raise_server_financial_alert(
    'info', 'ca_manual_adjustments',
    format('Manual adjustment APPROVED by %s (proposed by %s): %s to %s',
           v_label, COALESCE(v_row.actor_label, v_row.actor::text), v_row.amount, v_row.target_kind),
    jsonb_build_object('adjustment_id', p_id, 'actor', v_row.actor, 'approver', v_approver,
                       'approver_label', v_label, 'amount', v_row.amount,
                       'target_kind', v_row.target_kind, 'target_id', v_row.target_id),
    'adj-approved:' || p_id::text);

  RETURN jsonb_build_object('ok', true, 'adjustment_id', p_id, 'status', v_row.status,
    'actor', v_row.actor, 'approver', v_approver, 'approved_at', v_row.approved_at);
END $$;


ALTER FUNCTION public.fn_ca_approve_manual_adjustment(p_id uuid, p_approver uuid, p_approver_label text, p_note text) OWNER TO postgres;

--
-- Name: fn_ca_arena_diamonds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_arena_diamonds() RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE((
    SELECT sum(m.chip_balance)
      FROM public.club_members m
      JOIN public.ca_arena_settings s ON s.id = 1 AND s.club_id = m.club_id
  ), 0)::numeric;
$$;


ALTER FUNCTION public.fn_ca_arena_diamonds() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_arena_diamonds(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_arena_diamonds() IS 'Diamonds held inside the Diamond Arena (the platform club''s member wallets). The trial balance names them apart from player wallets so a deposit does not read as a disappearance.';


--
-- Name: fn_ca_arena_seat_is_same_asset(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_arena_seat_is_same_asset() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_club_asset text; v_arena uuid;
BEGIN
  BEGIN
    SELECT s.club_id INTO v_arena FROM public.ca_arena_settings s WHERE s.id = 1;
    IF v_arena IS NULL THEN RETURN NULL; END IF;   -- no arena yet: nothing to be inconsistent with
    SELECT c.asset INTO v_club_asset
      FROM public.tables t JOIN public.clubs c ON c.id = t.club_id
     WHERE t.id = NEW.table_id;
    IF v_club_asset IS NULL THEN RETURN NULL; END IF;
    -- The only asymmetry that can exist today: a seat at an arena (diamond) table funded from a
    -- chip club wallet, or the reverse. Both are a reporting error before they are a money one.
    IF (v_club_asset = 'diamonds') <> ((SELECT t.club_id FROM public.tables t WHERE t.id = NEW.table_id) = v_arena) THEN
      -- Flipping DR15 escalates what this files; it never refuses the seat, because a guard
      -- that can refuse a seat can strand a player mid-hand. The mode is READ here so the rule
      -- has a consumer and a flip means something (CLAUDE.md 10.86).
      PERFORM public.fn_ca_diamond_incident('DR15:cross_asset_seat',
        CASE WHEN public.fn_ca_diamond_rule_mode('DR15:cross_asset_seat') = 'refuse'
             THEN 'critical' ELSE 'warning' END, NEW.user_id, NEW.stack,
        'fn_ca_arena_seat_is_same_asset',
        jsonb_build_object('table_id', NEW.table_id, 'club_asset', v_club_asset, 'arena_club', v_arena));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- a seat is never refused by a reporting guard
  END;
  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_ca_arena_seat_is_same_asset() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_arena_seat_is_same_asset(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_arena_seat_is_same_asset() IS 'Reports a seat whose funding asset disagrees with its club (DR15). It NEVER refuses a seat; flipping DR15 to refuse escalates the incident to critical instead.';


--
-- Name: fn_ca_attested_day_is_restated(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_attested_day_is_restated() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  v_reason text := NULLIF(current_setting('app.ledger_maintenance', true), '');
  r record;
  v_res jsonb;
BEGIN
  IF v_reason IS NULL THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'DELETE' THEN
    FOR r IN
      SELECT DISTINCT o.created_at::date AS day
        FROM old_rows o
        JOIN public.ca_ledger_day_manifests m ON m.day = o.created_at::date
       ORDER BY 1
    LOOP
      v_res := public.fn_ca_ledger_day_manifest(r.day, 'maintenance:' || v_reason);
      IF COALESCE((v_res->>'tampered')::boolean, false) THEN
        RAISE EXCEPTION 'the manifest for % could not be restated after maintenance "%": %', r.day, v_reason, v_res
          USING ERRCODE = 'P0403';
      END IF;
    END LOOP;
  ELSE
    FOR r IN
      SELECT DISTINCT d.day
        FROM (SELECT created_at::date AS day FROM old_rows
              UNION
              SELECT created_at::date FROM new_rows) d
        JOIN public.ca_ledger_day_manifests m ON m.day = d.day
       ORDER BY 1
    LOOP
      v_res := public.fn_ca_ledger_day_manifest(r.day, 'maintenance:' || v_reason);
      IF COALESCE((v_res->>'tampered')::boolean, false) THEN
        RAISE EXCEPTION 'the manifest for % could not be restated after maintenance "%": %', r.day, v_reason, v_res
          USING ERRCODE = 'P0403';
      END IF;
    END LOOP;
  END IF;

  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_ca_attested_day_is_restated() OWNER TO postgres;

--
-- Name: fn_ca_attribute_union_rake(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_attribute_union_rake(p_hours integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(hours => GREATEST(1, LEAST(COALESCE(p_hours, 3), 168)));
  v_rows int := 0; v_attributed int := 0; v_unattributed int := 0;
  v_records int := 0;
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role only' USING ERRCODE = '42501';
  END IF;

  /* the hands: rake at a table owned by a union's house club (tables.club_id
     = the union's id), in the window, either never attributed or still
     carrying an unattributed player under six hours old */
  CREATE TEMP TABLE _ura_hands ON COMMIT DROP AS
  SELECT r.id AS rake_record_id, r.hand_id, r.table_id, r.club_id AS union_id,
         r.created_at AS played_at, r.rake_amount, r.player_contributions
    FROM public.rake_records r
   WHERE r.is_tournament IS NOT TRUE
     AND r.rake_amount > 0
     AND r.created_at >= v_since
     AND r.player_contributions IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.unions u WHERE u.id = r.club_id)
     AND (NOT EXISTS (SELECT 1 FROM public.ca_union_rake_attribution a WHERE a.rake_record_id = r.id)
          OR EXISTS (SELECT 1 FROM public.ca_union_rake_attribution a
                      WHERE a.rake_record_id = r.id AND a.club_id IS NULL
                        AND a.attempts < 6 AND r.created_at >= now() - interval '6 hours'));
  SELECT count(*) INTO v_records FROM _ura_hands;

  CREATE TEMP TABLE _ura_contrib ON COMMIT DROP AS
  SELECT h.rake_record_id, h.hand_id, h.table_id, h.union_id, h.played_at, h.rake_amount,
         (x.key)::uuid AS user_id, (x.value)::numeric AS contrib,
         sum((x.value)::numeric) OVER (PARTITION BY h.rake_record_id) AS total
    FROM _ura_hands h, jsonb_each_text(h.player_contributions) x
   WHERE (x.value)::numeric > 0;

  /* the seat covering the hand's instant: same table first, else the
     player's latest seat that covers it */
  CREATE TEMP TABLE _ura_attr ON COMMIT DROP AS
  SELECT c.rake_record_id, c.user_id, c.union_id, c.table_id, c.hand_id, c.played_at,
         COALESCE(
           (SELECT s.club_id FROM public.table_seats s
             WHERE s.table_id = c.table_id AND s.user_id = c.user_id
               AND s.joined_at <= c.played_at
               AND COALESCE(s.left_at, 'infinity'::timestamptz) >= c.played_at - interval '2 minutes'
               AND s.club_id IS NOT NULL
             ORDER BY s.joined_at DESC LIMIT 1),
           (SELECT s.club_id FROM public.table_seats s
             WHERE s.user_id = c.user_id
               AND s.joined_at <= c.played_at
               AND COALESCE(s.left_at, 'infinity'::timestamptz) >= c.played_at - interval '2 minutes'
               AND s.club_id IS NOT NULL
             ORDER BY s.joined_at DESC LIMIT 1),
           /* the seat row itself may be gone (a table torn down deletes its
              seats): the club the player last sat through in the past week
              is the club they play through */
           (SELECT s.club_id FROM public.table_seats s
             WHERE s.user_id = c.user_id
               AND s.joined_at <= c.played_at
               AND s.joined_at >= c.played_at - interval '7 days'
               AND s.club_id IS NOT NULL
             ORDER BY s.joined_at DESC LIMIT 1)
         ) AS club_id,
         round(c.rake_amount * c.contrib / NULLIF(c.total, 0), 4) AS rake_share
    FROM _ura_contrib c;

  INSERT INTO public.ca_union_rake_attribution AS a
        (rake_record_id, user_id, union_id, table_id, hand_id, played_at, club_id, rake_share, attempts, attributed_at)
  SELECT rake_record_id, user_id, union_id, table_id, hand_id, played_at, club_id, COALESCE(rake_share, 0), 1, now()
    FROM _ura_attr
  ON CONFLICT (rake_record_id, user_id) DO UPDATE
     SET club_id       = COALESCE(EXCLUDED.club_id, a.club_id),
         rake_share    = EXCLUDED.rake_share,
         attempts      = a.attempts + 1,
         attributed_at = now();
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  SELECT count(*) FILTER (WHERE club_id IS NOT NULL), count(*) FILTER (WHERE club_id IS NULL)
    INTO v_attributed, v_unattributed
    FROM _ura_attr;

  RETURN jsonb_build_object('since', v_since, 'records', v_records, 'rows', v_rows,
                            'attributed', v_attributed, 'unattributed', v_unattributed);
END $$;


ALTER FUNCTION public.fn_ca_attribute_union_rake(p_hours integer) OWNER TO postgres;

--
-- Name: fn_ca_audit_diamond_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_audit_diamond_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old integer; v_new integer := COALESCE(NEW.diamonds, 0); v_delta integer;
  v_stack text; v_writer text; v_path text; v_journaled boolean := false;
  v_cert boolean; v_fixture boolean; v_sanctioned boolean; v_refuse boolean := false;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.diamonds IS NOT DISTINCT FROM OLD.diamonds THEN RETURN NEW; END IF;
    v_old := COALESCE(OLD.diamonds, 0);
  ELSE
    IF v_new = 0 THEN RETURN NEW; END IF;
    v_old := 0;
  END IF;
  v_delta := v_new - v_old;

  BEGIN
    GET DIAGNOSTICS v_stack = PG_CONTEXT;
    SELECT (regexp_match(t.ln, 'function (?:public\.)?([A-Za-z0-9_]+)\('))[1] INTO v_writer
      FROM regexp_split_to_table(COALESCE(v_stack, ''), E'\n') WITH ORDINALITY AS t(ln, ord)
     WHERE t.ln ~ 'function (?:public\.)?[A-Za-z0-9_]+\('
       AND (regexp_match(t.ln, 'function (?:public\.)?([A-Za-z0-9_]+)\('))[1] <> 'fn_ca_audit_diamond_change'
     ORDER BY t.ord LIMIT 1;

    v_path := NULLIF(btrim(COALESCE(current_setting('app.money_path', true), '')), '');
    v_journaled := EXISTS (SELECT 1 FROM public.diamond_transactions dt
                            WHERE dt.user_id = NEW.id AND dt.created_at >= now() - interval '2 seconds');
    v_cert    := public.fn_ca_is_cert_account(NEW.id);
    v_fixture := public.fn_ca_is_fixture_account(NEW.id);

    -- DR6. Every writer here journals in the same transaction; most of them AFTER the balance
    -- write, which is why v_journaled is false at trigger time for a correct credit (2026-09-07
    -- review D4-D6). Gate by name, and by prefix for the daily-challenge family whose body name
    -- has drifted twice.
    v_sanctioned :=
         COALESCE(v_writer, '') IN ('add_diamonds_to_balance', 'deduct_diamonds', 'fn_ca_mint', 'fn_ca_burn',
                                    'send_wallet_diamond_transfer', 'send_stream_gift', 'handle_new_user',
                                    'fn_ca_diamond_born_with_balance', 'award_diamonds_v2',
                                    'fn_purchase_time_banks_v2', 'reconcile_diamond_purchase_refund',
                                    'fn_diamond_purchase_refund', 'fn_ca_journal_profile_deletion')
      OR COALESCE(v_writer, '') LIKE 'claim_daily_challenge%'
      OR COALESCE(v_path, '') IN ('add_diamonds_to_balance', 'deduct_diamonds', 'fn_ca_mint', 'fn_ca_burn',
                                  'send_wallet_diamond_transfer', 'send_stream_gift',
                                  'claim_daily_challenge', 'claim_daily_challenges');

    INSERT INTO public.ca_diamond_balance_audit
      (user_id, old_diamonds, new_diamonds, delta, is_cert, db_role, app_name, journaled, writer, money_path)
    VALUES (NEW.id, v_old, v_new, v_delta, v_cert, current_user,
            COALESCE(current_setting('application_name', true), ''), v_journaled, v_writer, v_path);

    IF v_delta <> 0 AND NOT v_journaled AND NOT v_sanctioned THEN
      -- DR6 (DIAMOND-RULINGS 17): once flipped, an unsanctioned balance write on a player
      -- account is refused; fixtures are never refused, only filed at info.
      v_refuse := NOT v_fixture
                  AND public.fn_ca_diamond_rule_mode('DR6:balance_changed_without_journal') = 'refuse';
      PERFORM public.fn_ca_diamond_incident(
        CASE WHEN v_fixture THEN 'DR6:fixture_harness_unjournaled' ELSE 'DR6:balance_changed_without_journal' END,
        CASE WHEN v_fixture THEN 'info' ELSE 'warning' END,
        NEW.id, v_delta, COALESCE(v_writer, v_path, '(no function frame)'),
        jsonb_build_object('money_path', v_path, 'is_cert', v_cert, 'is_fixture', v_fixture, 'tg_op', TG_OP,
                           'writer', v_writer, 'old_diamonds', v_old, 'new_diamonds', v_new,
                           'db_role', current_user,
                           'app_name', COALESCE(current_setting('application_name', true), ''),
                           'journaled_at_trigger_time', v_journaled, 'sanctioned_money_path', v_sanctioned));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      INSERT INTO public.ca_ledger_write_failures (user_id, delta, sqlstate, message)
      VALUES (NEW.id, v_delta, SQLSTATE, 'diamond audit insert failed: ' || SQLERRM);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END;
  IF v_refuse THEN
    RAISE EXCEPTION 'DR6: profiles.diamonds may only change through a sanctioned money path (writer %, delta %)',
      COALESCE(v_writer, v_path, '(no function frame)'), v_delta
      USING ERRCODE = 'P0406', HINT = 'Use add_diamonds_to_balance, deduct_diamonds, fn_ca_mint or fn_ca_burn.';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_audit_diamond_change() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_audit_diamond_change(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_audit_diamond_change() IS 'DR6 log-only. Appends to ca_diamond_balance_audit on every INSERT or change of profiles.diamonds, naming the writer from PG_CONTEXT and the declared app.money_path, and files DR6:balance_changed_without_journal when a non-zero delta comes from a writer that is not one of the eight sanctioned money paths. It refuses nothing and it cannot fail a diamond movement: every failure lands in ca_ledger_write_failures.';


--
-- Name: fn_ca_auto_reconcile_tick(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_auto_reconcile_tick() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  inc RECORD; repaired int := 0; v_clean boolean; v_res text; v_uid uuid; v_n int;
BEGIN
  FOR inc IN
    SELECT * FROM public.ca_drift_incidents
     WHERE status IN ('open','acknowledged','reconciling')
       AND auto_repair_status IN ('pending','running')
     ORDER BY detected_at
     LIMIT 25
  LOOP
    v_clean := false; v_res := NULL;

    BEGIN
      IF inc.classification IN ('incorrect_rake','bbj_error') THEN
        -- the rake/BBJ audit covers both invariants; both redrives are
        -- idempotent, so run both regardless of which word won the classifier
        PERFORM public.fn_redrive_unbanked_rake(100);
        PERFORM public.fn_bbj_repair_unbanked(24, 200);
        v_res := 'ran fn_redrive_unbanked_rake(100) + fn_bbj_repair_unbanked(24,200)';
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_res := 'redrive failed: ' || SQLERRM;
    END;

    IF inc.source LIKE '%winner_prize_credit%' AND (inc.metadata ? 'user_id') THEN
      BEGIN
        v_uid := (inc.metadata->>'user_id')::uuid;
        SELECT EXISTS (
          SELECT 1 FROM wallet_transactions wt
           WHERE wt.user_id = v_uid AND wt.type = 'credit'
             AND wt.description LIKE 'Tournament payout reconciliation%'
             AND wt.created_at > inc.detected_at) INTO v_clean;
        IF v_clean THEN
          v_res := COALESCE(v_res || '; ', '') ||
            'payout reconciler credit verified in wallet_transactions after detection';
        END IF;
      EXCEPTION WHEN OTHERS THEN v_clean := false;
      END;
    ELSIF inc.source = 'financial_alerts:fn_rake_bbj_audit' THEN
      -- clean when no unbanked BBJ drops and no unbanked raked hands remain
      -- in the audit's 2-hour window
      SELECT count(*) INTO v_n
        FROM rake_records rr
       WHERE rr.hand_id IS NOT NULL
         AND rr.created_at > now() - interval '2 hours'
         AND rr.created_at < now() - interval '5 minutes'
         AND ((COALESCE(rr.bbj_contribution,0) > 0 AND NOT EXISTS
                (SELECT 1 FROM bbj_contributions bc WHERE bc.hand_id = rr.hand_id))
           OR (rr.rake_amount > 0 AND NOT EXISTS
                (SELECT 1 FROM rake_distribution_legs l WHERE l.leg_key = rr.hand_id)));
      v_clean := (v_n = 0);
      IF v_clean THEN
        v_res := COALESCE(v_res || '; ', '') || 'zero unbanked fees remain in the 2h audit window';
      END IF;
    ELSIF inc.entity_type = 'seat_stack_exit' AND (inc.metadata ? 'exit_id') THEN
      SELECT NOT EXISTS (
        SELECT 1 FROM public.fn_unaccounted_seat_exits('7 days'::interval) u
         WHERE u.id = (inc.metadata->>'exit_id')::bigint) INTO v_clean;
    ELSIF inc.entity_type = 'settlement_idempotency_keys' AND inc.table_id IS NOT NULL THEN
      SELECT NOT EXISTS (
        SELECT 1 FROM settlement_idempotency_keys k
         WHERE k.table_id = inc.table_id AND k.hand_id = inc.hand_id
           AND k.status = 'in_flight') INTO v_clean;
    ELSIF inc.entity_type = 'union_pnl_settlements' AND inc.entity_id IS NOT NULL THEN
      SELECT NOT EXISTS (
        SELECT 1 FROM union_pnl_settlements s
         WHERE s.id = inc.entity_id AND s.status = 'in_progress') INTO v_clean;
    ELSIF inc.entity_type = 'frozen_wallets_pool' THEN
      SELECT (SELECT COALESCE(SUM(balance),0) FROM public.wallets)
             = (SELECT frozen_total FROM public.ca_frozen_pool_baseline
                 WHERE pool = 'public.wallets') INTO v_clean;
    ELSIF inc.source = 'fn_ca_quick_reconcile:negative_balance' THEN
      v_clean := NOT EXISTS (
        SELECT 1 WHERE
          (inc.entity_type='club_treasury' AND EXISTS
            (SELECT 1 FROM clubs WHERE id = inc.entity_id AND COALESCE(chip_treasury,0) < 0))
          OR (inc.entity_type='player_wallet' AND EXISTS
            (SELECT 1 FROM club_members WHERE user_id = inc.entity_id
              AND club_id = inc.club_id
              AND COALESCE(chip_balance,0) < -COALESCE(credit_limit,0))));
    END IF;

    IF v_clean THEN
      UPDATE public.ca_drift_incidents
         SET status = 'resolved', resolved_at = now(),
             auto_repair_status = 'repaired',
             resolution = COALESCE(v_res || '; ', '') || 'source measurement re-verified clean',
             root_cause = COALESCE(root_cause,
               'Transient drift: the source measurement re-verified clean after an idempotent re-drive; no persistent code defect observed in this occurrence.'),
             -- THE LAW, SATISFIED ON ITS OWN TERMS (2026-09-01): the evidence
             -- the reconciler actually gathered IS the correction reference.
             correction_ref = COALESCE(correction_ref,
               'verified: ' || COALESCE(v_res, 'source measurement re-verified clean'))
       WHERE id = inc.id;
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (inc.id, 'repair_action',
              jsonb_build_object('action', COALESCE(v_res,'reverify'), 'result', 'clean -> resolved'));
      PERFORM public.fn_ca_incident_notify(inc.id, 'notified',
        '✅ Auto-reconciled: ' || inc.classification, false);
      repaired := repaired + 1;
    ELSIF v_res IS NOT NULL THEN
      UPDATE public.ca_drift_incidents SET auto_repair_status = 'running' WHERE id = inc.id;
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (inc.id, 'repair_action', jsonb_build_object('action', v_res, 'result', 'pending re-check'));
    ELSIF inc.auto_repair_status = 'pending'
          AND now() - inc.detected_at > interval '10 minutes' THEN
      UPDATE public.ca_drift_incidents SET auto_repair_status = 'manual_needed' WHERE id = inc.id;
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (inc.id, 'repair_action',
              jsonb_build_object('action', 'none applicable', 'result', 'manual_needed'));
    END IF;
  END LOOP;
  RETURN repaired;
END $$;


ALTER FUNCTION public.fn_ca_auto_reconcile_tick() OWNER TO postgres;

--
-- Name: fn_ca_autoledger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_autoledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  spec text; col text; acct text;
  o jsonb; nn jsonb;
  d numeric; oldv numeric; newv numeric;
  cat text; cp text; cpid uuid;
  v_club uuid; v_union uuid; v_entity uuid;
  actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN NEW;
  END IF;

  o  := CASE WHEN TG_OP = 'INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
  nn := to_jsonb(NEW);

  cat := COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'adjustment');
  cp  := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), 'settlement_suspense');
  BEGIN
    cpid := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN cpid := NULL;
  END;
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (nn->>'id')::uuid
    WHEN nn ? 'club_id' THEN NULLIF(nn->>'club_id','')::uuid
    ELSE NULL END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (nn->>'id')::uuid
    WHEN nn ? 'union_id' THEN NULLIF(nn->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME = 'agents' THEN NULLIF(nn->>'user_id','')::uuid
    WHEN TG_TABLE_NAME = 'club_members' THEN NULLIF(nn->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(nn->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := COALESCE(NULLIF(o->>col,'')::numeric, 0);
    newv := COALESCE(NULLIF(nn->>col,'')::numeric, 0);
    d := round(newv - oldv, 2);
    CONTINUE WHEN d = 0;

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance, pre_to_balance, post_to_balance)
      VALUES (actor,
        CASE WHEN d > 0 THEN cp   ELSE acct END,
        CASE WHEN d > 0 THEN cpid ELSE v_entity END,
        CASE WHEN d > 0 THEN NULL ELSE TG_TABLE_NAME || '.' || col END,
        CASE WHEN d > 0 THEN acct ELSE cp END,
        CASE WHEN d > 0 THEN v_entity ELSE cpid END,
        CASE WHEN d > 0 THEN TG_TABLE_NAME || '.' || col ELSE NULL END,
        abs(d), cat, v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' delta ' || d::text,
        CASE WHEN d < 0 THEN oldv END, CASE WHEN d < 0 THEN newv END,
        CASE WHEN d > 0 THEN oldv END, CASE WHEN d > 0 THEN newv END);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_autoledger() OWNER TO postgres;

--
-- Name: fn_ca_autoledger_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_autoledger_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  spec text; col text; acct text;
  o jsonb; oldv numeric;
  v_club uuid; v_union uuid; v_entity uuid; actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN OLD;
  END IF;

  o := to_jsonb(OLD);
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);
  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (o->>'id')::uuid
    WHEN o ? 'club_id' THEN NULLIF(o->>'club_id','')::uuid
    ELSE NULL END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (o->>'id')::uuid
    WHEN o ? 'union_id' THEN NULLIF(o->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME IN ('agents','club_members') THEN NULLIF(o->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(o->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := round(COALESCE(NULLIF(o->>col,'')::numeric, 0), 2);
    CONTINUE WHEN oldv = 0;

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance)
      VALUES (actor,
        acct, v_entity, TG_TABLE_NAME || '.' || col,
        'chip_retirement', NULL, NULL,
        abs(oldv), CASE WHEN oldv > 0 THEN 'burn' ELSE 'correction' END,
        v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' balance ' || oldv::text
          || ' retired on row delete',
        oldv, 0);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN OLD;
END $$;


ALTER FUNCTION public.fn_ca_autoledger_delete() OWNER TO postgres;

--
-- Name: fn_ca_balance_asof(text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_balance_asof(p_type text, p_entity uuid, p_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record;
BEGIN
  SELECT * INTO r FROM (
    SELECT l.id, l.created_at, l.post_from_balance AS balance, 'from' AS side
      FROM public.chip_ledger l
     WHERE l.from_type = p_type AND l.from_entity_id = p_entity
       AND l.created_at <= p_at AND l.post_from_balance IS NOT NULL
     ORDER BY l.created_at DESC LIMIT 1
  ) f
  UNION ALL
  SELECT * FROM (
    SELECT l.id, l.created_at, l.post_to_balance AS balance, 'to' AS side
      FROM public.chip_ledger l
     WHERE l.to_type = p_type AND l.to_entity_id = p_entity
       AND l.created_at <= p_at AND l.post_to_balance IS NOT NULL
     ORDER BY l.created_at DESC LIMIT 1
  ) t
  ORDER BY created_at DESC LIMIT 1;

  IF r.id IS NULL THEN
    RETURN jsonb_build_object('found', false, 'account_type', p_type, 'entity_id', p_entity,
      'as_of', p_at, 'note', 'no ledger row with a recorded balance at or before this time');
  END IF;
  RETURN jsonb_build_object('found', true, 'account_type', p_type, 'entity_id', p_entity,
    'as_of', p_at, 'balance', r.balance, 'recorded_at', r.created_at,
    'ledger_row', r.id, 'side', r.side);
END $$;


ALTER FUNCTION public.fn_ca_balance_asof(p_type text, p_entity uuid, p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_ca_balance_asof_admin(text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_balance_asof_admin(p_entity_type text, p_entity_id uuid, p_asof timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mgmt boolean;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.ca_incident_recipients r WHERE r.user_id = v_uid AND r.active
    UNION ALL
    SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.role IN ('admin','god')
  ) INTO v_mgmt;
  IF NOT v_mgmt THEN RETURN NULL; END IF;
  RETURN public.fn_ca_balance_asof(p_entity_type, p_entity_id, p_asof);
END $$;


ALTER FUNCTION public.fn_ca_balance_asof_admin(p_entity_type text, p_entity_id uuid, p_asof timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_ca_ban_club_player(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ban_club_player(p_club_id uuid, p_user_id uuid, p_reason text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller    uuid := auth.uid();
  v_role      text;
  v_agent     uuid;
  v_chips     numeric;
  v_credit    numeric;
  v_seats     integer;
  v_blacklist uuid;
  v_re_ban    boolean := false;
BEGIN
  IF NOT fn_ca_can_manage_agents(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_player');
  END IF;

  -- Banning the person who holds the club is how a club loses its owner.
  IF EXISTS (SELECT 1 FROM clubs c WHERE c.id = p_club_id AND c.owner_id = p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'cannot_ban_the_owner');
  END IF;

  SELECT cm.role,
         cm.agent_id,
         coalesce(cm.chip_balance, 0) + coalesce(cm.held_chips, 0)
           + coalesce(cm.locked_chips, 0) + coalesce(cm.promo_balance, 0),
         coalesce(cm.credit_used, 0)
    INTO v_role, v_agent, v_chips, v_credit
    FROM club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = p_user_id;

  IF v_role IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_member_of_this_club');
  END IF;

  IF v_role IN ('owner', 'co_owner', 'admin') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'cannot_ban_club_staff');
  END IF;

  -- An existing exclusion for this pair is replaced rather than duplicated.
  -- Written as a lookup and a branch rather than ON CONFLICT because the
  -- unique index here is partial (permanent rows only), so a timed ban does
  -- not match the arbiter and the two cases are clearer spelled out. A re-ban
  -- is the same ban and files no second audit event.
  SELECT b.id INTO v_blacklist
    FROM blacklists b
   WHERE b.club_id = p_club_id AND b.user_id = p_user_id
   LIMIT 1;

  v_re_ban := v_blacklist IS NOT NULL;

  IF v_re_ban THEN
    UPDATE blacklists b
       SET reason = coalesce(nullif(btrim(coalesce(p_reason, '')), ''), b.reason),
           banned_by = v_caller,
           banned_at = now(),
           expires_at = p_expires_at
     WHERE b.id = v_blacklist;
  ELSE
    INSERT INTO blacklists (club_id, user_id, reason, banned_by, banned_at, expires_at)
    VALUES (p_club_id, p_user_id,
            nullif(btrim(coalesce(p_reason, '')), ''),
            v_caller, now(), p_expires_at)
    RETURNING id INTO v_blacklist;
  END IF;

  -- What the operator now has to deal with, said plainly rather than left for
  -- them to discover: an excluded player who is still sitting, and whatever
  -- the membership row is still holding.
  SELECT count(*)::integer INTO v_seats
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
   WHERE t.club_id = p_club_id
     AND ts.user_id = p_user_id
     AND ts.left_at IS NULL;

  RETURN jsonb_build_object(
    'ok', true,
    'blacklist_id', v_blacklist,
    'was_already_excluded', v_re_ban,
    'expires_at', p_expires_at,
    'was_role', v_role,
    'had_agent', v_agent,
    'chips_held', v_chips,
    'credit_used', v_credit,
    'live_seats', coalesce(v_seats, 0));
END;
$$;


ALTER FUNCTION public.fn_ca_ban_club_player(p_club_id uuid, p_user_id uuid, p_reason text, p_expires_at timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_ca_banned_copy_characters(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_banned_copy_characters() RETURNS TABLE(kind text, object_name text, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH lines AS (
    SELECT p.proname, p.oid::regprocedure::text AS sig, l
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    CROSS JOIN LATERAL unnest(string_to_array(p.prosrc, E'\n')) AS l
    WHERE n.nspname = 'public'
      AND p.prokind = 'f'
      -- The checker is allowed to hold the characters it checks for. Same
      -- exemption check-ui-text.mjs keeps for titleCase.ts and popupStyle.ts:
      -- without this the function reports ITSELF forever and never passes.
      AND p.proname <> 'fn_ca_banned_copy_characters'
  )
  SELECT 'dash'::text, sig, left(trim(l), 200)
  FROM lines
  WHERE l ~ '[‒–—―]'
  UNION ALL
  SELECT 'emoji'::text, sig, left(trim(l), 200)
  FROM lines
  -- The pictograph planes, plus the four BMP characters this product actually
  -- uses AS emoji. Arrows and check/cross glyphs are deliberately NOT here:
  -- the first version of this gate matched them and reported '->' inside a
  -- HINT and '* NEW:' in a comment, which is how a gate earns its own deletion.
  WHERE l ~ '[\U0001F000-\U0001FAFF✨⭐✅❌]'
    -- Operator dashboards and admin alerts, exempted in the open: glyphs as
    -- status columns and severity flags for staff, not copy on a page. A NAME
    -- LIST rather than a pattern, because a pattern quietly grows to cover
    -- whatever somebody names next.
    AND proname NOT IN (
      'fn_ca_incident_action',
      'fn_ca_incident_escalation_tick',
      'fn_ca_incident_notify',
      'fn_ca_raise_drift_incident',
      'fn_ca_auto_reconcile_tick',
      'fn_ca_burnin_gate_tick',
      'fn_ca_daily_attestation',
      'fn_submit_bug_report_to_admin',
      'verify_home_games_health_core',
      'verify_home_games_health_addendum'
    )
  ORDER BY 1, 2, 3;
$$;


ALTER FUNCTION public.fn_ca_banned_copy_characters() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_banned_copy_characters(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_banned_copy_characters() IS 'Every line of every public function that breaks one of Dan''s two character bans: a dash character (banned 2026-08-20) or an emoji in player-facing copy (design-guidelines.md rule 1). Empty is the only passing result. Read by scripts/ci/check-db-copy.mjs. Operator dashboards are exempted by name, in the function body.';


--
-- Name: fn_ca_block_browser_money_table(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_block_browser_money_table() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    RAISE EXCEPTION
      'Direct % on %.% from the browser is forbidden. Chips move only through the money RPCs.',
      TG_OP, TG_TABLE_SCHEMA, TG_TABLE_NAME
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;


