--
-- Name: fn_ca_bomb_hand_keeps_its_award_units(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_bomb_hand_keeps_its_award_units() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_distributable numeric;
  v_units numeric;
  v_n int;
BEGIN
  IF NEW.bomb_pot IS NULL THEN RETURN NULL; END IF;

  v_distributable := round(COALESCE(NEW.pot_size,0)
                           - COALESCE(NEW.rake_amount,0)
                           - COALESCE(NEW.bbj_amount,0), 2);
  /* Nothing to distribute means nothing to attribute: a folded-around bomb, or
     a hand voided before showdown. Not every bomb row owes a breakdown. */
  IF v_distributable <= 0 THEN RETURN NULL; END IF;

  SELECT COALESCE(round(sum(amount),2),0), count(*)
    INTO v_units, v_n
    FROM public.bomb_pot_award_units
   WHERE hand_history_id = NEW.id;

  IF v_n = 0 THEN
    RAISE EXCEPTION
      'bomb pot hand #% (%) would commit with % chips distributed and no award units. '
      'Write the hand and its units together through fn_ca_insert_hand_with_awards - '
      'two separate writes is how 18 bomb pots lost their record in the week to '
      '2026-09-06.',
      NEW.hand_number, NEW.id, v_distributable
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF v_units <> v_distributable THEN
    RAISE EXCEPTION
      'bomb pot hand #% (%) distributes % chips but its % award unit(s) sum to %.',
      NEW.hand_number, NEW.id, v_distributable, v_n, v_units
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_ca_bomb_hand_keeps_its_award_units() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_bomb_hand_keeps_its_award_units(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_bomb_hand_keeps_its_award_units() IS 'ATTACHED as constraint trigger zz_ca_bomb_hand_keeps_its_award_units on hand_history (20260906143315). A bomb-pot hand that distributes chips cannot commit without award units summing to the distributable pot. The engine satisfies it through fn_ca_insert_hand_with_awards (PR #3272). Detached history: 20260906100735 defined, 20260906101230 detached.';


--
-- Name: fn_ca_bomb_pot_catchup(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_bomb_pot_catchup(p_club_id uuid, p_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_day  date;
  v_done integer := 0;
BEGIN
  IF p_club_id IS NULL THEN
    RETURN 0;
  END IF;

  -- Only days the hands can still answer for. Reaching further back would
  -- write ZEROES over history that pruning removed, which is worse than the
  -- gap it would be papering over: the rollup exists to be believed.
  FOR v_day IN
    SELECT g::date
      FROM generate_series(
             GREATEST(
               (now() - make_interval(days => LEAST(GREATEST(COALESCE(p_days, 30), 1), 365)))::date,
               (SELECT MIN(h.created_at)::date FROM public.hand_history h
                 WHERE h.bomb_pot IS NOT NULL)
             ),
             (now() - interval '15 minutes')::date - 1,
             interval '1 day') g
     WHERE NOT EXISTS (
       SELECT 1 FROM public.ca_club_bomb_pot_complete c
        WHERE c.club_id = p_club_id AND c.day = g::date)
     ORDER BY g DESC
     LIMIT 40
  LOOP
    PERFORM public.fn_ca_bomb_pot_rollup_day(p_club_id, v_day);
    v_done := v_done + 1;
  END LOOP;

  RETURN v_done;
END;
$$;


ALTER FUNCTION public.fn_ca_bomb_pot_catchup(p_club_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_bomb_pot_catchup(p_club_id uuid, p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_bomb_pot_catchup(p_club_id uuid, p_days integer) IS 'Seals any finished day in the window that has no marker yet, newest first, at most forty per call. Called by fn_club_bomb_pot_report so the rollup needs no scheduler.';


--
-- Name: fn_ca_bomb_pot_rollup_day(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_bomb_pot_rollup_day(p_club_id uuid, p_day date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows  integer := 0;
  v_hands bigint  := 0;
BEGIN
  IF p_club_id IS NULL OR p_day IS NULL THEN
    RETURN 0;
  END IF;

  -- A day is finished fifteen minutes after it ends, never before. See the
  -- header: bomb_pot_award_units can land a moment late and a sealed day is
  -- not recomputed.
  IF (p_day + 1)::timestamptz > now() - interval '15 minutes' THEN
    RETURN 0;
  END IF;

  DELETE FROM public.ca_club_bomb_pot_daily d
   WHERE d.club_id = p_club_id AND d.day = p_day;

  WITH bomb_hands AS (
    SELECT h.id,
           h.table_id,
           h.bomb_pot ->> 'trigger_reason'                       AS trigger_reason,
           (h.bomb_pot ->> 'board_count')::int                   AS board_count,
           h.bomb_pot ->> 'variant'                              AS variant,
           COALESCE((h.bomb_pot ->> 'ante_amount')::numeric, 0)  AS ante_amount,
           COALESCE(h.pot_size, 0)                               AS pot_size,
           COALESCE(h.rake_amount, 0)                            AS rake_amount,
           COALESCE(jsonb_array_length(h.players), 0)            AS seats
      FROM public.hand_history h
      JOIN public.tables t ON t.id = h.table_id
     WHERE t.club_id = p_club_id
       AND h.bomb_pot IS NOT NULL
       AND h.created_at >= p_day::timestamptz
       AND h.created_at <  (p_day + 1)::timestamptz
  ), per_hand_units AS (
    SELECT a.hand_history_id,
           count(DISTINCT a.user_id) AS distinct_winners
      FROM public.bomb_pot_award_units a
      JOIN bomb_hands b ON b.id = a.hand_history_id
     GROUP BY a.hand_history_id
  ), grouped AS (
    SELECT b.table_id, b.trigger_reason, b.board_count, b.variant,
           count(*)::bigint                                              AS hands,
           SUM(b.seats)::numeric                                         AS seats_sum,
           SUM(b.pot_size)                                               AS pot_sum,
           SUM(b.rake_amount)                                            AS rake_sum,
           SUM(b.ante_amount * b.seats)                                  AS ante_sum,
           count(*) FILTER (WHERE u.distinct_winners = 1)::bigint        AS scoops,
           count(*) FILTER (WHERE u.distinct_winners > 1)::bigint        AS splits,
           count(*) FILTER (WHERE u.hand_history_id IS NULL)::bigint     AS unrecorded
      FROM bomb_hands b
      LEFT JOIN per_hand_units u ON u.hand_history_id = b.id
     GROUP BY b.table_id, b.trigger_reason, b.board_count, b.variant
  )
  INSERT INTO public.ca_club_bomb_pot_daily
    (club_id, day, table_id, trigger_reason, board_count, variant,
     hands, seats_sum, pot_sum, rake_sum, ante_sum, scoops, splits, unrecorded)
  SELECT p_club_id, p_day, g.table_id, g.trigger_reason, g.board_count, g.variant,
         g.hands, g.seats_sum, g.pot_sum, g.rake_sum, g.ante_sum,
         g.scoops, g.splits, g.unrecorded
    FROM grouped g;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  SELECT COALESCE(SUM(d.hands), 0) INTO v_hands
    FROM public.ca_club_bomb_pot_daily d
   WHERE d.club_id = p_club_id AND d.day = p_day;

  -- The marker is written even when the day held no bomb pots. A day with
  -- none is a FACT, and without the marker it would be re-scanned live for
  -- ever and read as "not yet known" rather than "none".
  INSERT INTO public.ca_club_bomb_pot_complete (club_id, day, rows_written, hands_read, computed_at)
  VALUES (p_club_id, p_day, v_rows, v_hands, now())
  ON CONFLICT (club_id, day) DO UPDATE
    SET rows_written = EXCLUDED.rows_written,
        hands_read   = EXCLUDED.hands_read,
        computed_at  = EXCLUDED.computed_at;

  RETURN v_rows;
END;
$$;


ALTER FUNCTION public.fn_ca_bomb_pot_rollup_day(p_club_id uuid, p_day date) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_bomb_pot_rollup_day(p_club_id uuid, p_day date); Type: COMMENT; Schema: public; Owner: postgres
--

