    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.ca_bridge_rate_history (diamonds_per_chip, previous, changed_by, note)
  VALUES (NEW.diamonds_per_chip,
