--
-- Name: fn_ca_browser_reachable_telemetry(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_browser_reachable_telemetry() RETURNS TABLE(proname text, args text, reached_by text, volatility text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  select p.proname::text,
         pg_get_function_identity_arguments(p.oid)::text,
         concat_ws(' + ',
           case when has_function_privilege('anon', p.oid, 'EXECUTE') then 'anon' end,
           case when has_function_privilege('authenticated', p.oid, 'EXECUTE') then 'authenticated' end
         )::text,
         case p.provolatile when 'v' then 'volatile' when 's' then 'stable' else 'immutable' end::text
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.prosecdef
     -- reachable from a browser
     and (has_function_privilege('anon', p.oid, 'EXECUTE')
       or has_function_privilege('authenticated', p.oid, 'EXECUTE'))
     -- a trigger function cannot be invoked through PostgREST at all
     and p.prorettype <> 'pg_catalog.trigger'::regtype
     -- and asks nothing about who is calling
     and p.prosrc not ilike '%auth.uid()%'
     and p.prosrc not ilike '%auth.role()%'
     and p.prosrc not ilike '%auth.jwt()%'
     and p.prosrc not ilike '%current_setting%request%'
     -- and takes no identity argument, so it can only be answering about
     -- everything. This is the line between an operator console and an RPC.
     and coalesce(pg_get_function_identity_arguments(p.oid), '') !~*
         '(club|user|union|table|pool|tournament|group|member|owner|horse|author|sender|recipient|agent|payout|promotion|profile|seat|hand)'
     -- PostGIS ships its own definer helpers; they are not ours to re-grant.
     and p.proname !~ '^(st_|_st_|postgis_)'
     -- and it has not been decided, with a reason, that it belongs open.
     and not exists (select 1 from public.ca_browser_definer_allowlist a where a.proname = p.proname)
   order by p.proname;
$$;


ALTER FUNCTION public.fn_ca_browser_reachable_telemetry() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_browser_reachable_telemetry(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_browser_reachable_telemetry() IS 'Unscoped SECURITY DEFINER routines a browser can execute that never consult the caller and are not on ca_browser_definer_allowlist. Zero rows is the healthy state. Read by scripts/ci/check-telemetry-exposure.mjs.';


--
-- Name: fn_ca_burn(text, text, uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_burn(p_asset text, p_source text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text DEFAULT 'admin'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_house constant uuid := '00000000-0000-0000-0000-00000000d1a0';
  v_actor uuid := auth.uid();
  v_admin boolean := false;
  v_asset text := lower(btrim(COALESCE(p_asset, '')));
  v_src   text := lower(btrim(COALESCE(p_source, '')));
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_class text := lower(btrim(COALESCE(p_class, 'admin')));
  v_holder uuid;
  v_prior jsonb; v_before numeric; v_after numeric; v_label text;
  v_supply numeric; v_chip_id uuid; v_dia_id uuid; v_actorlb text; v_result jsonb;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT EXISTS (SELECT 1 FROM public.profiles p
                    WHERE p.id = v_actor AND p.role IN ('admin', 'god')) INTO v_admin;
    IF NOT v_admin THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'the_mint_is_admin_only');
    END IF;
  END IF;

  IF v_asset NOT IN ('chips', 'diamonds') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'asset_must_be_chips_or_diamonds');
  END IF;
  IF v_asset = 'chips' AND v_src NOT IN ('club', 'union') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'chips_are_retired_from_a_club_or_union_wallet_only');
  END IF;
  IF v_asset = 'diamonds' AND v_src NOT IN ('player', 'house') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamonds_are_retired_from_a_player_or_from_the_house_only');
  END IF;
  IF v_class NOT IN ('purchased', 'promotional', 'earned', 'transferred', 'seeded',
                     'refund', 'spend', 'bridge', 'deletion', 'admin', 'arena',
                     'house', 'unknown') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unknown_issuance_class', 'class', v_class);
  END IF;
  IF v_asset = 'diamonds' AND v_src = 'house' THEN
    IF p_target_id IS NOT NULL AND p_target_id <> c_house THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'the_house_target_is_the_house_sentinel_or_null');
    END IF;
  ELSIF p_target_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'target_required');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive_to_two_decimals');
  END IF;
  IF v_asset = 'diamonds' AND p_amount <> round(p_amount, 0) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamonds_are_whole_numbers');
  END IF;
  IF length(v_reason) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'retirement_needs_a_real_reason');
  END IF;
  IF COALESCE(btrim(p_op_id), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'idempotency_key_required');
  END IF;

  SELECT result INTO v_prior FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_ca_burn';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims WHERE op_id = p_op_id AND fn_name = 'fn_ca_burn';
  END IF;
  INSERT INTO public.ca_op_claims (op_id, fn_name, claimed_by)
  VALUES (p_op_id, 'fn_ca_burn', v_actor);

  PERFORM pg_advisory_xact_lock(hashtext('ca_mint_ledger:' || v_asset));

  IF v_asset = 'diamonds' THEN
    IF v_src = 'house' THEN
      INSERT INTO public.ca_diamond_house (id, balance)
      VALUES (1, 0) ON CONFLICT (id) DO NOTHING;
      SELECT COALESCE(balance, 0) INTO v_before
        FROM public.ca_diamond_house WHERE id = 1 FOR UPDATE;
      IF v_before < p_amount THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'that_would_take_the_house_below_zero',
                                  'balance', v_before, 'requested', p_amount);
      END IF;
      UPDATE public.ca_diamond_house
         SET balance = COALESCE(balance, 0) - p_amount, updated_at = now()
       WHERE id = 1 RETURNING balance INTO v_after;
      v_label  := 'the house';
      v_holder := c_house;
    ELSE
      SELECT COALESCE(diamonds, 0), COALESCE(NULLIF(btrim(username), ''), full_name, id::text)
        INTO v_before, v_label FROM public.profiles WHERE id = p_target_id FOR UPDATE;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'player_not_found');
      END IF;
      IF v_before < p_amount THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'that_would_take_the_balance_below_zero',
                                  'balance', v_before, 'requested', p_amount);
      END IF;
      UPDATE public.profiles SET diamonds = COALESCE(diamonds, 0) - p_amount
       WHERE id = p_target_id RETURNING diamonds INTO v_after;
      -- The op id is the journal reference (DR4), the same way fn_ca_mint records it.
      INSERT INTO public.diamond_transactions
        (user_id, type, transaction_type, amount, balance_after, description, source,
         metadata, counterparty, issuance_class, reference_id)
      VALUES (p_target_id, 'spend', 'burn', -p_amount, v_after,
              'The Mint (retired): ' || v_reason, 'the_mint',
              jsonb_build_object('burned_by', v_actor, 'op_id', p_op_id),
              'retired', v_class, p_op_id)
      RETURNING id INTO v_dia_id;
      v_holder := p_target_id;
    END IF;
  ELSE
    -- The leg is declared WITH A KEY and found by that key: never by shape.
    PERFORM public.fn_ca_declare_ledger('burn', 'chip_retirement', NULL, NULL, 'burn:' || p_op_id, NULL);
    IF v_src = 'club' THEN
      SELECT COALESCE(chip_treasury, 0), name INTO v_before, v_label
        FROM public.clubs WHERE id = p_target_id FOR UPDATE;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'club_not_found');
      END IF;
      IF v_before < p_amount THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'that_would_take_the_treasury_below_zero',
                                  'balance', v_before, 'requested', p_amount);
      END IF;
      UPDATE public.clubs SET chip_treasury = COALESCE(chip_treasury, 0) - p_amount
       WHERE id = p_target_id RETURNING chip_treasury INTO v_after;
      INSERT INTO public.chip_transactions
        (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after)
      VALUES (p_target_id, v_actor, NULL, p_amount, 'treasury_burn',
              'The Mint (retired): ' || v_reason, v_after);
    ELSE
      SELECT COALESCE(w.chip_balance, 0), u.name INTO v_before, v_label
        FROM public.union_wallets w JOIN public.unions u ON u.id = w.union_id
       WHERE w.union_id = p_target_id FOR UPDATE OF w;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'union_wallet_not_found');
      END IF;
      IF v_before < p_amount THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'that_would_take_the_union_bank_below_zero',
                                  'balance', v_before, 'requested', p_amount);
      END IF;
      UPDATE public.union_wallets
         SET chip_balance = COALESCE(chip_balance, 0) - p_amount, updated_at = now()
       WHERE union_id = p_target_id RETURNING chip_balance INTO v_after;
    END IF;
    SELECT id INTO v_chip_id FROM public.chip_ledger WHERE idempotency_key = 'burn:' || p_op_id;
    PERFORM set_config('app.ledger_category', '', true);
    PERFORM set_config('app.ledger_counterparty', '', true);
    PERFORM set_config('app.ledger_counterparty_entity', '', true);
    PERFORM set_config('app.ledger_idempotency_key', '', true);
    IF v_chip_id IS NULL THEN
      RAISE EXCEPTION 'fn_ca_burn: the balance moved but no journal leg was written for key burn:% - refusing to register a retirement the journal does not carry', p_op_id;
    END IF;
    v_holder := p_target_id;
  END IF;

  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) - p_amount
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = v_asset;
  SELECT COALESCE(NULLIF(btrim(username), ''), full_name, id::text)
    INTO v_actorlb FROM public.profiles WHERE id = v_actor;

  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason,
     performed_by, performed_by_label, chip_ledger_id, diamond_tx_id)
  VALUES
    (p_op_id, 'burn', v_asset, v_src, v_holder, v_label, p_amount,
     v_before, v_after, v_supply, v_reason, v_actor, v_actorlb, v_chip_id, v_dia_id);

  v_result := jsonb_build_object(
    'ok', true, 'replayed', false, 'action', 'burn',
    'asset', v_asset, 'source', v_src, 'issuance_class', v_class,
    'target_id', v_holder, 'target_label', v_label, 'amount', p_amount,
    'balance_before', v_before, 'balance_after', v_after, 'supply_after', v_supply,
    'ledger_id', v_chip_id,
    'burned_by', v_actor, 'reason', v_reason, 'op_id', p_op_id);

  UPDATE public.ca_op_claims SET result = v_result, finalized_at = now()
   WHERE op_id = p_op_id AND fn_name = 'fn_ca_burn';

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_ca_burn(p_asset text, p_source text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_burn(p_asset text, p_source text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_burn(p_asset text, p_source text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text) IS 'Retirement, the mirror of fn_ca_mint. Chips from a club treasury or union bank; diamonds from a player wallet or from ca_diamond_house. Refuses below zero on every account. p_class is stamped on the diamond journal row beside counterparty = ''retired''. service_role, or admin / god, only.';


--
-- Name: fn_ca_burnin_gate_tick(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_burnin_gate_tick() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_gate jsonb; v_pass boolean; v_prev boolean; v_failing text[];
  v_tracker record; v_uid uuid;
BEGIN
  v_gate := public.fn_ca_midway_burnin_gate(24);
  v_pass := COALESCE((v_gate->>'pass')::boolean, false);
  SELECT COALESCE(array_agg(k), '{}') INTO v_failing
    FROM jsonb_each(v_gate->'checks') e(k, v) WHERE (v->'pass')::boolean = false;
  SELECT pass INTO v_prev FROM public.ca_gate_runs ORDER BY run_at DESC LIMIT 1;
  INSERT INTO public.ca_gate_runs (pass, window_hours, failing, result)
  VALUES (v_pass, 24, v_failing, v_gate);

  -- red -> green: the one push worth sending
  IF v_pass AND (v_prev IS DISTINCT FROM true) THEN
    FOR v_uid IN SELECT user_id FROM public.ca_incident_recipients WHERE active AND scope='platform' LOOP
      PERFORM public.fn_raise_notification(v_uid, 'financial_attestation',
        '🟢 Midway burn-in gate is GREEN',
        'All 12 acceptance checks passed over the last 24 hours. Per the zero-drift directive, Midway/Shark/JAQK may reopen normal tables.',
        '/hub/club-arena/financial-incidents',
        jsonb_build_object('gate', 'green'));
    END LOOP;
  END IF;

  -- blocked-mint tracker auto-verify: a full day of zero attempts after the
  -- engine fix = verified. Resolve the tracker and say so, once.
  FOR v_tracker IN
    SELECT i.id FROM public.ca_drift_incidents i
    WHERE i.dedupe_key LIKE 'tourney-cashout-blocked:%' AND i.status <> 'resolved'
      AND i.detected_at < now() - interval '24 hours'
      AND NOT EXISTS (SELECT 1 FROM public.ca_incident_events e
                       WHERE e.incident_id = i.id AND e.at > now() - interval '24 hours'
                         AND e.kind IN ('created','notified'))
  LOOP
    PERFORM public.fn_ca_incident_action(v_tracker.id, 'resolve',
      'Auto-verified: 24 hours with zero blocked tournament-cashout attempts - the engine exit path is confirmed fixed.',
      NULL, 'engine exit path fix verified by 24h of silence at the guard',
      'verified: 24h with zero blocked tournament-cashout attempts at the guard');
    FOR v_uid IN SELECT user_id FROM public.ca_incident_recipients WHERE active AND scope='platform' LOOP
      PERFORM public.fn_raise_notification(v_uid, 'financial_attestation',
        '✅ Engine tournament-exit fix verified',
        'The mint guard has seen zero blocked cashout attempts for a full day. The engine-side bug behind the tournament-cashout mint is confirmed fixed.',
        '/hub/club-arena/financial-incidents', '{}'::jsonb);
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('pass', v_pass, 'failing', v_failing);
END $$;


ALTER FUNCTION public.fn_ca_burnin_gate_tick() OWNER TO postgres;

--
-- Name: fn_ca_caller_is_management(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_caller_is_management() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_ok  boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN true;
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.ca_incident_recipients r WHERE r.user_id = v_uid AND r.active
    UNION ALL
    SELECT 1 FROM public.club_members cm WHERE cm.user_id = v_uid AND cm.role = 'owner'
    UNION ALL
    SELECT 1 FROM public.unions u WHERE u.owner_id = v_uid
    UNION ALL
    SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.role IN ('admin','god')
  ) INTO v_ok;
  RETURN COALESCE(v_ok, false);
END $$;


ALTER FUNCTION public.fn_ca_caller_is_management() OWNER TO postgres;

--
-- Name: fn_ca_can_manage_agents(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_can_manage_agents(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT auth.uid() IS NOT NULL
     AND (
       EXISTS (SELECT 1 FROM clubs c
                WHERE c.id = p_club_id AND c.owner_id = auth.uid())
       OR EXISTS (SELECT 1 FROM club_members cm
                   WHERE cm.club_id = p_club_id
                     AND cm.user_id = auth.uid()
                     AND cm.role IN ('owner', 'co_owner', 'admin'))
     );
$$;


