--
-- Name: fn_ca_can_review_integrity(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_can_review_integrity(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_club_id IS NOT NULL
     AND auth.uid() IS NOT NULL
     AND (
       coalesce(fn_is_platform_admin(), false)
       OR EXISTS (SELECT 1 FROM clubs c WHERE c.id = p_club_id AND c.owner_id = auth.uid())
       OR EXISTS (
         SELECT 1 FROM club_members cm
          WHERE cm.club_id = p_club_id
            AND cm.user_id = auth.uid()
            AND cm.role IN ('owner', 'co_owner', 'admin')
            AND coalesce(cm.status, 'active') NOT IN ('banned', 'suspended')
       )
     );
$$;


ALTER FUNCTION public.fn_ca_can_review_integrity(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_can_review_integrity(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_can_review_integrity(p_club_id uuid) IS 'The one gate for club integrity surfaces: club owner (by owner_id or by role), co-owner, admin, or platform admin. Shared by the flag list, the flag review, the club stats, the collusion detector and both dispute transitions so they cannot drift about who may look.';


--
-- Name: fn_ca_capture_closing_position(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_closing_position(p_note text DEFAULT NULL::text, p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ref    uuid := gen_random_uuid();
  v_epoch  record;
  v_rows   integer := 0;
  v_total  numeric := 0;
  v_by     jsonb;
BEGIN
  IF COALESCE(NULLIF(auth.role(), ''), session_user) NOT IN ('service_role', 'postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'closing-position capture is operator-only';
  END IF;

  SELECT id, name INTO v_epoch
    FROM public.ca_financial_epochs WHERE is_current LIMIT 1;
  IF v_epoch.id IS NULL THEN
    RAISE EXCEPTION 'no current epoch - ca_financial_epochs has no is_current row';
  END IF;

  IF NOT p_dry_run AND NOT public.fn_platform_frozen() THEN
    RAISE EXCEPTION
      'closing-position capture refused: the platform is not frozen. Capture inside the :55 maintenance break, or pass p_dry_run => true to rehearse.'
      USING ERRCODE = '55006';
  END IF;

  CREATE TEMP TABLE _closing (
    account_type text, column_name text, entity_id uuid, club_id uuid, balance numeric
  ) ON COMMIT DROP;

  INSERT INTO _closing
  SELECT 'player_wallet', 'club_members.chip_balance', cm.user_id, cm.club_id, round(COALESCE(cm.chip_balance,0),2)
    FROM public.club_members cm WHERE COALESCE(cm.chip_balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'member_promo', 'club_members.promo_balance', cm.user_id, cm.club_id, round(COALESCE(cm.promo_balance,0),2)
    FROM public.club_members cm WHERE COALESCE(cm.promo_balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'table_stack', 'table_seats.stack', ts.user_id, ts.club_id, round(COALESCE(ts.stack,0),2)
    FROM public.table_seats ts
   WHERE ts.left_at IS NULL AND COALESCE(ts.stack,0) <> 0
     AND NOT EXISTS (SELECT 1 FROM public.tables t WHERE t.id = ts.table_id AND t.tournament_id IS NOT NULL);

  INSERT INTO _closing
  SELECT 'club_treasury', 'clubs.chip_treasury', NULL, c.id, round(COALESCE(c.chip_treasury,0),2)
    FROM public.clubs c WHERE COALESCE(c.chip_treasury,0) <> 0;
  INSERT INTO _closing
  SELECT 'club_pool', 'clubs.chip_pool', NULL, c.id, round(COALESCE(c.chip_pool,0),2)
    FROM public.clubs c WHERE COALESCE(c.chip_pool,0) <> 0;
  INSERT INTO _closing
  SELECT 'club_promo', 'clubs.promo_balance', NULL, c.id, round(COALESCE(c.promo_balance,0),2)
    FROM public.clubs c WHERE COALESCE(c.promo_balance,0) <> 0;
  INSERT INTO _closing
  SELECT 'club_insurance', 'clubs.insurance_balance', NULL, c.id, round(COALESCE(c.insurance_balance,0),2)
    FROM public.clubs c WHERE COALESCE(c.insurance_balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'club_wallet', 'club_wallets.chip_balance', NULL, cw.club_id, round(COALESCE(cw.chip_balance,0),2)
    FROM public.club_wallets cw WHERE COALESCE(cw.chip_balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'union_wallet', 'union_wallets.' || col, NULL, uw.union_id, round(bal,2)
    FROM public.union_wallets uw,
         LATERAL (VALUES
           ('chip_balance', COALESCE(uw.chip_balance,0)),
           ('rake_wallet', COALESCE(uw.rake_wallet,0)),
           ('bbj_wallet', COALESCE(uw.bbj_wallet,0)),
           ('promo_wallet', COALESCE(uw.promo_wallet,0)),
           ('insurance_wallet', COALESCE(uw.insurance_wallet,0)),
           ('spin_reserve_wallet', COALESCE(uw.spin_reserve_wallet,0))
         ) AS v(col, bal)
   WHERE bal <> 0;

  INSERT INTO _closing
  SELECT 'agent_wallet', 'agents.agent_wallet_balance', a.user_id, a.club_id, round(COALESCE(a.agent_wallet_balance,0),2)
    FROM public.agents a WHERE COALESCE(a.agent_wallet_balance,0) <> 0;
  INSERT INTO _closing
  SELECT 'agent_promo', 'agents.promo_wallet_balance', a.user_id, a.club_id, round(COALESCE(a.promo_wallet_balance,0),2)
    FROM public.agents a WHERE COALESCE(a.promo_wallet_balance,0) <> 0;
  INSERT INTO _closing
  SELECT 'agent_player_wallet', 'agents.player_wallet_balance', a.user_id, a.club_id, round(COALESCE(a.player_wallet_balance,0),2)
    FROM public.agents a WHERE COALESCE(a.player_wallet_balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'bbj_pool', 'bbj_pools.' || col, b.union_id, b.club_id, round(bal,2)
    FROM public.bbj_pools b,
         LATERAL (VALUES
           ('main_balance', COALESCE(b.main_balance,0)),
           ('backup_balance', COALESCE(b.backup_balance,0)),
           ('promo_balance', COALESCE(b.promo_balance,0))
         ) AS v(col, bal)
   WHERE bal <> 0;

  INSERT INTO _closing
  SELECT 'spin_reserve', 'spin_bonus_pools.balance', NULL, s.club_id, round(COALESCE(s.balance,0),2)
    FROM public.spin_bonus_pools s WHERE COALESCE(s.balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'frozen_wallet_pool', 'wallets.balance', w.user_id, NULL, round(COALESCE(w.balance,0),2)
    FROM public.wallets w WHERE COALESCE(w.balance,0) <> 0;

  SELECT count(*), COALESCE(round(sum(balance),2),0) INTO v_rows, v_total FROM _closing;
  SELECT jsonb_object_agg(account_type, totals) INTO v_by
    FROM (SELECT account_type,
                 jsonb_build_object('accounts', count(*), 'total', round(sum(balance),2)) AS totals
            FROM _closing GROUP BY account_type) x;

  IF v_rows = 0 THEN
    RAISE EXCEPTION 'closing-position capture found no accounts at all - refusing to record an empty position';
  END IF;

  IF p_dry_run THEN
    RETURN jsonb_build_object('dry_run', true, 'written', false,
      'epoch', v_epoch.name, 'accounts', v_rows, 'total', v_total, 'by_class', v_by,
      'frozen_now', public.fn_platform_frozen(),
      'note', 'run with p_dry_run => false inside the :55 freeze to record it');
  END IF;

  INSERT INTO public.ca_epoch_closing_positions
    (capture_ref, epoch_id, epoch_name, account_type, column_name, entity_id, club_id, balance, note)
  SELECT v_ref, v_epoch.id, v_epoch.name, c.account_type, c.column_name, c.entity_id, c.club_id, c.balance, p_note
    FROM _closing c;

  RETURN jsonb_build_object('written', true, 'capture_ref', v_ref,
    'epoch', v_epoch.name, 'accounts', v_rows, 'total', v_total, 'by_class', v_by,
    'next', 'compare against fn_ca_supply_snapshot() before the reset, then keep it forever');
END;
$$;


ALTER FUNCTION public.fn_ca_capture_closing_position(p_note text, p_dry_run boolean) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_capture_closing_position(p_note text, p_dry_run boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_capture_closing_position(p_note text, p_dry_run boolean) IS 'Records what every account held the moment before an epoch reset - roadmap 9.8 step 1. Covers exactly the classes fn_ca_supply_snapshot reads, so the two agree by construction. A real capture refuses unless the platform is frozen; p_dry_run reads and returns the same totals without writing.';


--
-- Name: fn_ca_capture_freeze_mark(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_freeze_mark(p_kind text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_win TIMESTAMPTZ; m NUMERIC; f NUMERIC; t NUMERIC; i INTEGER := 0;
BEGIN
  IF p_kind NOT IN ('pre','post') THEN
    RAISE EXCEPTION 'p_kind must be pre or post, got %', p_kind;
  END IF;
  v_win := CASE WHEN p_kind = 'pre'
                THEN date_trunc('hour', now()) + interval '1 hour'
                ELSE date_trunc('hour', now() + interval '2 minutes') END;
  -- A pre mark taken before the freeze engages measures three seconds of live
  -- play, not the freeze. Wait for the platform to actually be frozen.
  IF p_kind = 'pre' THEN
    WHILE NOT public.fn_platform_frozen() AND i < 25 LOOP
      PERFORM pg_sleep(1); i := i + 1;
    END LOOP;
  END IF;
  SELECT member_wallets, on_the_felt, total INTO m, f, t FROM public.fn_ca_circulation_total();
  INSERT INTO public.ca_freeze_circulation_marks (window_hour, kind, member_wallets, on_the_felt, total)
  VALUES (v_win, p_kind, m, f, t)
  ON CONFLICT (window_hour, kind) DO UPDATE
     SET member_wallets = EXCLUDED.member_wallets,
         on_the_felt    = EXCLUDED.on_the_felt,
         total          = EXCLUDED.total,
         mark_at        = now();
  RETURN v_win;
END $$;


ALTER FUNCTION public.fn_ca_capture_freeze_mark(p_kind text) OWNER TO postgres;

--
-- Name: fn_ca_capture_hand_facts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_hand_facts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(OLD.rake_amount, 0) > 0 OR COALESCE(OLD.bbj_amount, 0) > 0
     OR OLD.reported IS TRUE THEN
    INSERT INTO public.ca_hand_financial_facts
      (hand_id, table_id, tournament_id, hand_number, big_blind, pot_size,
       rake_amount, bbj_amount, winners, hand_created_at)
    VALUES (OLD.id, OLD.table_id, OLD.tournament_id, OLD.hand_number, OLD.big_blind,
            OLD.pot_size, OLD.rake_amount, OLD.bbj_amount, OLD.winners, OLD.created_at)
    ON CONFLICT (hand_id) DO NOTHING;
  END IF;
  RETURN OLD;
EXCEPTION WHEN OTHERS THEN
  -- never block a prune; count the miss
  BEGIN
    INSERT INTO public.ca_ledger_write_failures (source_table, message, sqlstate)
    VALUES ('ca_hand_financial_facts', left(SQLERRM, 500), SQLSTATE);
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN OLD;
END $$;


ALTER FUNCTION public.fn_ca_capture_hand_facts() OWNER TO postgres;

--
-- Name: fn_ca_capture_satellite_seat_entitlement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_satellite_seat_entitlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_h public.tournament_satellite_settlements%ROWTYPE;
  v_l public.chip_ledger%ROWTYPE;
  v_rows integer;
BEGIN
  IF NEW.delivery_kind IS DISTINCT FROM 'seat' THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v_h FROM public.tournament_satellite_settlements h
   WHERE h.tournament_id=NEW.tournament_id;
  SELECT * INTO v_l FROM public.chip_ledger l
   WHERE l.idempotency_key=NEW.idempotency_key||':pool_transfer'
     AND l.from_type='prize_liability'
     AND l.from_entity_id=NEW.tournament_id
     AND l.to_type='prize_liability'
     AND l.to_entity_id=v_h.target_id
     AND l.amount=NEW.amount;
  IF v_h.tournament_id IS NULL OR v_l.id IS NULL OR v_l.club_id IS NULL
     OR NEW.registration_id IS NULL
     OR v_h.ticket_cost IS DISTINCT FROM NEW.amount
     OR v_h.ticket_cost IS DISTINCT FROM
          round(v_h.target_buy_in+v_h.target_fee,2) THEN
    RAISE EXCEPTION
      'satellite seat award has no exact target contract and pool-transfer source'
      USING ERRCODE = 'P0404';
  END IF;
  INSERT INTO public.tournament_refund_entitlements(
    tournament_id,user_id,entitlement_kind,charge_category,
    refund_wallet_club_id,gross,refund_prize,refund_bounty,refund_fee,
    source_ledger_id,registration_id,source_satellite_id,source_award_place,
    escrow_bucket,evidence_kind,created_at)
  VALUES(
    v_h.target_id,NEW.user_id,'satellite_seat','satellite_seat',
    v_l.club_id,NEW.amount,v_h.target_buy_in,0,v_h.target_fee,
    v_l.id,NEW.registration_id,NEW.tournament_id,NEW.place,
    'satellite_in','atomic_satellite_seat',transaction_timestamp())
  ON CONFLICT(source_ledger_id) DO NOTHING;
  SELECT count(*) INTO v_rows
    FROM public.tournament_refund_entitlements e
   WHERE e.source_ledger_id=v_l.id
     AND e.tournament_id=v_h.target_id AND e.user_id=NEW.user_id
     AND e.entitlement_kind='satellite_seat'
     AND e.charge_category='satellite_seat'
     AND e.refund_wallet_club_id=v_l.club_id
     AND e.gross=NEW.amount
     AND e.refund_prize=v_h.target_buy_in
     AND e.refund_bounty=0 AND e.refund_fee=v_h.target_fee
     AND e.registration_id=NEW.registration_id
     AND e.source_satellite_id=NEW.tournament_id
     AND e.source_award_place=NEW.place;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'satellite seat entitlement identity conflicts with its source'
      USING ERRCODE = 'P0404';
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_capture_satellite_seat_entitlement() OWNER TO postgres;

--
-- Name: fn_ca_capture_tournament_charge_entitlement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_tournament_charge_entitlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_split record;
BEGIN
  IF NEW.tournament_id IS NULL
     OR NEW.from_type IS DISTINCT FROM 'player_wallet'
     OR NEW.to_type IS DISTINCT FROM 'prize_liability'
     OR NEW.to_entity_id IS DISTINCT FROM NEW.tournament_id
     OR lower(COALESCE(NEW.category,'')) NOT IN (
          'tournament_buyin','rebuy','addon') THEN
    RETURN NULL;
  END IF;
  IF NEW.from_entity_id IS NULL OR NEW.club_id IS NULL THEN
    RAISE EXCEPTION 'tournament charge ledger omitted player or source club'
      USING ERRCODE = 'P0404';
  END IF;
  SELECT * INTO v_split FROM public.fn_ca_tournament_charge_split(
    NEW.tournament_id,NEW.category,NEW.amount);
  INSERT INTO public.tournament_refund_entitlements(
    tournament_id,user_id,entitlement_kind,charge_category,
    refund_wallet_club_id,gross,refund_prize,refund_bounty,refund_fee,
    source_ledger_id,registration_id,source_satellite_id,source_award_place,
    escrow_bucket,evidence_kind,created_at)
  VALUES(
    NEW.tournament_id,NEW.from_entity_id,'wallet_charge',lower(NEW.category),
    NEW.club_id,round(NEW.amount,2),v_split.refund_prize,
    v_split.refund_bounty,v_split.refund_fee,NEW.id,NULL,NULL,NULL,
    'wallet_gross','atomic_wallet_charge',transaction_timestamp());
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_capture_tournament_charge_entitlement() OWNER TO postgres;

--
-- Name: fn_ca_chip_ledger_enrich(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_chip_ledger_enrich() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_prev text;
BEGIN
  NEW.amount := round(NEW.amount, 2);
  NEW.created_at := COALESCE(NEW.created_at, now());

  NEW.epoch_id      := COALESCE(NEW.epoch_id, public.fn_ca_current_epoch());
  NEW.actor_service := COALESCE(NEW.actor_service,
                                current_setting('application_name', true));
  NEW.db_role       := COALESCE(NEW.db_role, current_user);
  NEW.correlation_id := COALESCE(NEW.correlation_id,
      NULLIF(current_setting('app.ledger_correlation', true), '')::uuid);
  NEW.settlement_id  := COALESCE(NEW.settlement_id,
      NULLIF(current_setting('app.ledger_settlement', true), ''));
  IF NEW.idempotency_key IS NULL THEN
    NEW.idempotency_key := NULLIF(current_setting('app.ledger_idempotency_key', true), '');
    IF NEW.idempotency_key IS NOT NULL THEN
      -- consume-once: the next row in this transaction must not inherit it
      PERFORM set_config('app.ledger_idempotency_key', '', true);
    END IF;
  END IF;

  /* PHASE 6.4 (2026-09-05): EVERY LEG NAMES ITS HAND OR ITS EVENT. The doors
     that know the hand say so on app.ledger_hand_id (the rake door and the
     BBJ drop, since today) or on a 'bbj:<hand>' settlement; the rake
     settlement is not read for it because it carries a random key when the
     hand is unknown, and a guessed hand is worse than none; a spin's reserve legs
     carry the spin on their prize_liability side. Read them here, once, so
     the hand and the event are columns a per-hand audit can index on rather
     than strings it has to parse. 231,211 legs a day; 29,617 named a hand
     and 50,359 an event before this. */
  IF NEW.hand_id IS NULL THEN
    NEW.hand_id := NULLIF(current_setting('app.ledger_hand_id', true), '')::uuid;
    IF NEW.hand_id IS NULL AND NEW.settlement_id ~ '^bbj:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      NEW.hand_id := split_part(NEW.settlement_id, ':', 2)::uuid;
    END IF;
  END IF;
  IF NEW.tournament_id IS NULL THEN
    NEW.tournament_id := NULLIF(current_setting('app.ledger_tournament_id', true), '')::uuid;
    /* PHASE 6 GATE (2026-09-05): a prize_liability side IS the event, on every
       category, not only the two spin ones. This is what the 6.4 measurement
       missed: 777 tournament rake settlements in three hours (the fee leaving
       an event to a union rake wallet or a club treasury) and every tournament
       add-on named nothing. Read against the rows first: all 777 from_entity_id
       values are real tournaments. The FROM side wins when both sides are
       prize_liability (a satellite seat's pool transfer, which already stamps
       the satellite itself). */
    IF NEW.tournament_id IS NULL THEN
      IF NEW.from_type = 'prize_liability' THEN NEW.tournament_id := NEW.from_entity_id;
      ELSIF NEW.to_type = 'prize_liability' THEN NEW.tournament_id := NEW.to_entity_id;
      END IF;
    END IF;
  END IF;
  /* PHASE 6 GATE: and a table_stack side IS the table. Every cash buy-in,
     add-on and cash-out carries the table on its felt side (231, 53 and 222
     of each measured in the same window, every one a real table row) and
     none of them carried table_id. A cash buy-in is not a hand; the table is
     the name it has. */
  IF NEW.table_id IS NULL THEN
    IF NEW.to_type = 'table_stack' THEN NEW.table_id := NEW.to_entity_id;
    ELSIF NEW.from_type = 'table_stack' THEN NEW.table_id := NEW.from_entity_id;
    END IF;
  END IF;

  -- Tamper evidence: monotone sequence + per-row content checksum. NOT chained
  -- through the previous row's hash at insert time - that would put a global
  -- serialization point (and deadlock surface) inside every money transaction,
  -- which the availability policy forbids. prev_hash is best-effort forensics.
  NEW.chain_seq := nextval('public.chip_ledger_chain_seq');
  SELECT row_hash INTO v_prev
    FROM public.chip_ledger
   WHERE chain_seq = NEW.chain_seq - 1;
  NEW.prev_hash := v_prev;
  NEW.row_hash := encode(extensions.digest(
      'v1'
      || '|' || NEW.chain_seq::text
      || '|' || COALESCE(NEW.epoch_id::text,'')
      || '|' || NEW.amount::text
      || '|' || NEW.from_type || ':' || COALESCE(NEW.from_entity_id::text,'')
      || '|' || NEW.to_type   || ':' || COALESCE(NEW.to_entity_id::text,'')
      || '|' || NEW.category
      || '|' || COALESCE(NEW.idempotency_key,'')
      || '|' || COALESCE(NEW.correlation_id::text,'')
      || '|' || NEW.created_at::text,
      'sha256'), 'hex');
  RETURN NEW;
END $_$;


ALTER FUNCTION public.fn_ca_chip_ledger_enrich() OWNER TO postgres;

--
-- Name: fn_ca_chip_statement(text, uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_chip_statement(p_scope text DEFAULT 'player'::text, p_club_id uuid DEFAULT NULL::uuid, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller     uuid := auth.uid();
  v_entity     uuid;
  v_type       text;
  v_col        text;
  v_key        text;
  v_limit      int := GREATEST(LEAST(COALESCE(p_limit, 50), 200), 1);
  v_balance    numeric;
  v_clubs      jsonb := '[]'::jsonb;
  v_legs       jsonb;
  v_has_more   boolean;
  v_next       timestamptz;
  v_snap_bal   numeric;
  v_snap_at    timestamptz;
  v_snap_cum   numeric;
  v_snap_base  boolean;
  v_in         numeric;
  v_out        numeric;
  v_since_legs bigint;
  v_expected   numeric;
  v_audit      jsonb;
  v_t0         timestamptz := clock_timestamp();
BEGIN
  IF v_caller IS NULL AND COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF p_scope = 'player' THEN
    IF v_caller IS NULL THEN
      RAISE EXCEPTION 'a player statement is the caller''s own; there is no other player to ask for' USING ERRCODE = '42501';
    END IF;
    v_entity := v_caller;              -- never a parameter: the statement is always your own
    v_type   := 'player_wallet';
    v_col    := 'club_members.chip_balance';
  ELSIF p_scope = 'club_treasury' THEN
    IF p_club_id IS NULL THEN
      RAISE EXCEPTION 'club_treasury needs p_club_id';
    END IF;
    IF NOT public.ca_can_view_club_finances(p_club_id) THEN
      RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
    END IF;
    v_entity := p_club_id;
    v_type   := 'club_treasury';
    v_col    := 'clubs.chip_treasury';
  ELSE
    RAISE EXCEPTION 'scope must be player or club_treasury';
  END IF;
  v_key := v_type || ':' || v_entity::text || ':' || v_col;

  /* THE BALANCE NOW, through the same reader the nightly replay uses. */
  v_balance := public.fn_ca_account_balance(v_type, v_entity, NULL, v_col);

  IF p_scope = 'player' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'club_id', m.club_id, 'club_name', c.name, 'balance', round(COALESCE(m.chip_balance, 0), 2))
             ORDER BY c.name), '[]'::jsonb)
      INTO v_clubs
      FROM public.club_members m
      JOIN public.clubs c ON c.id = m.club_id
     WHERE m.user_id = v_entity;
  END IF;

  /* THE PAGE. Both sides, newest first, from this account's point of view. */
  WITH mine AS (
    /* One index range per side - (to_entity_id, created_at DESC) and
       (from_entity_id, created_at DESC) both exist - each already limited,
       then merged. An OR across the two sides would be a bitmap of every leg
       the account ever had, which for a horse is tens of thousands. */
    (SELECT l.id, l.created_at, l.amount, l.category, l.description, l.club_id,
            l.table_id, l.tournament_id, l.hand_id, l.settlement_id,
            'in'::text AS direction, l.from_type AS counterparty_type,
            l.from_label AS counterparty_label, l.from_entity_id AS counterparty_id
       FROM public.chip_ledger l
      WHERE l.to_entity_id = v_entity AND l.to_type = v_type
        AND (p_club_id IS NULL OR l.club_id = p_club_id)
        AND (p_before IS NULL OR l.created_at < p_before)
      ORDER BY l.created_at DESC, l.id DESC
      LIMIT v_limit + 1)
    UNION ALL
    (SELECT l.id, l.created_at, l.amount, l.category, l.description, l.club_id,
            l.table_id, l.tournament_id, l.hand_id, l.settlement_id,
            'out'::text, l.to_type, l.to_label, l.to_entity_id
       FROM public.chip_ledger l
      WHERE l.from_entity_id = v_entity AND l.from_type = v_type
        AND (p_club_id IS NULL OR l.club_id = p_club_id)
        AND (p_before IS NULL OR l.created_at < p_before)
      ORDER BY l.created_at DESC, l.id DESC
      LIMIT v_limit + 1)
  ), page AS (
    SELECT * FROM mine ORDER BY created_at DESC, id DESC LIMIT v_limit
  )
  SELECT COALESCE((SELECT jsonb_agg(jsonb_build_object(
             'id', p.id, 'at', p.created_at, 'direction', p.direction, 'amount', round(p.amount, 2),
             'category', p.category, 'description', p.description,
             'counterparty_type', p.counterparty_type, 'counterparty_label', p.counterparty_label,
             'counterparty_id', p.counterparty_id,
             'club_id', p.club_id, 'table_id', p.table_id, 'tournament_id', p.tournament_id,
             'hand_id', p.hand_id, 'settlement_id', p.settlement_id)
             ORDER BY p.created_at DESC, p.id DESC) FROM page p), '[]'::jsonb),
         (SELECT count(*) FROM mine) > v_limit,   -- more than a page on either side, or both together
         (SELECT min(p.created_at) FROM page p)
    INTO v_legs, v_has_more, v_next;

  /* THE AUDIT. The last nightly reading of this account, and the journal
     since it. Balance-at-reading plus net-since equals balance-now, or it
     does not, and either way the player sees the same three numbers the
     platform's own control sees. */
  SELECT s.balance, s.taken_at, s.cum_unexplained, s.is_baseline
    INTO v_snap_bal, v_snap_at, v_snap_cum, v_snap_base
    FROM public.ca_account_snapshots s
   WHERE s.account_key = v_key
   ORDER BY s.taken_at DESC
   LIMIT 1;

  IF v_snap_at IS NULL THEN
    v_audit := jsonb_build_object(
      'status', 'no_reading_yet',
      'detail', 'this account has not yet been read by the nightly ledger replay (fn_ca_ledger_replay reads every account that moved in the last 26 hours, at 06:40 UTC). The legs above are complete; there is no reading to compare the balance against yet.',
      'balance_now', round(COALESCE(v_balance, 0), 2));
  ELSE
    SELECT COALESCE(sum(l.amount) FILTER (WHERE l.to_entity_id = v_entity AND l.to_type = v_type), 0),
           COALESCE(sum(l.amount) FILTER (WHERE l.from_entity_id = v_entity AND l.from_type = v_type), 0),
           count(*)
      INTO v_in, v_out, v_since_legs
      FROM public.chip_ledger l
     WHERE ((l.to_entity_id = v_entity AND l.to_type = v_type) OR (l.from_entity_id = v_entity AND l.from_type = v_type))
       AND l.created_at > v_snap_at;
    v_expected := round(v_snap_bal + v_in - v_out, 2);
    v_audit := jsonb_build_object(
      'status', CASE WHEN v_balance IS NULL THEN 'no_balance'
                     WHEN abs(round(v_balance, 2) - v_expected) < 0.005 THEN 'reconciles'
                     ELSE 'does_not_reconcile' END,
      'read_at', v_snap_at,
      'balance_at_reading', round(v_snap_bal, 2),
      'reading_is_baseline', COALESCE(v_snap_base, false),
      'cumulative_unexplained_at_reading', round(COALESCE(v_snap_cum, 0), 2),
      'in_since', round(v_in, 2),
      'out_since', round(v_out, 2),
      'legs_since', v_since_legs,
      'expected_now', v_expected,
      'balance_now', round(COALESCE(v_balance, 0), 2),
      'unexplained', CASE WHEN v_balance IS NULL THEN NULL ELSE round(round(v_balance, 2) - v_expected, 2) END,
      'detail', 'balance_at_reading + in_since - out_since = expected_now. The nightly replay (fn_ca_ledger_replay) makes this same comparison for every account and files an incident when it fails; a difference here that persists past the next 06:40 UTC reading is one the platform has also seen.');
  END IF;

  RETURN jsonb_build_object(
    'scope', p_scope,
    'entity_id', v_entity,
    'account', v_key,
    'club_filter', p_club_id,
    'balance_now', round(COALESCE(v_balance, 0), 2),
    'balance_exists', v_balance IS NOT NULL,
    'clubs', v_clubs,
    'legs', v_legs,
    'has_more', v_has_more,
    'next_before', v_next,
    'audit', v_audit,
    'generated_at', now(),
    'ms', round(extract(epoch from (clock_timestamp() - v_t0)) * 1000));
END $$;


ALTER FUNCTION public.fn_ca_chip_statement(p_scope text, p_club_id uuid, p_before timestamp with time zone, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_chip_statement(p_scope text, p_club_id uuid, p_before timestamp with time zone, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_chip_statement(p_scope text, p_club_id uuid, p_before timestamp with time zone, p_limit integer) IS 'Phase 7 (roadmap 9.5). A chip statement a player - horse or human, identically - or a club operator can audit: balance now, a page of legs with direction and counterparty, and the comparison against the last nightly reading in ca_account_snapshots (balance_at_reading + in_since - out_since vs balance_now). scope=player is always the caller''s own wallet; scope=club_treasury is gated by ca_can_view_club_finances.';


--
-- Name: fn_ca_circulation_total(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_circulation_total() RETURNS TABLE(member_wallets numeric, on_the_felt numeric, total numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    COALESCE((SELECT sum(chip_balance) FROM public.club_members), 0)::numeric,
    COALESCE((SELECT sum(stack) FROM public.table_seats WHERE left_at IS NULL), 0)::numeric,
    COALESCE((SELECT sum(chip_balance) FROM public.club_members), 0)::numeric
      + COALESCE((SELECT sum(stack) FROM public.table_seats WHERE left_at IS NULL), 0)::numeric;
$$;


ALTER FUNCTION public.fn_ca_circulation_total() OWNER TO postgres;

--
-- Name: fn_ca_clear_payout_freeze(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_clear_payout_freeze(p_id uuid, p_actor_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_label text := COALESCE(NULLIF(btrim(p_actor_label), ''),
                           NULLIF(current_setting('application_name', true), ''),
                           session_user::text);
  v_row   public.ca_payout_freeze%ROWTYPE;
BEGIN
  IF NOT public.fn_ca_caller_is_management() THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'not_management');
  END IF;
  IF p_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'id_required');
  END IF;

  UPDATE public.ca_payout_freeze
     SET cleared_at = now(), cleared_by = v_uid, cleared_by_label = v_label
   WHERE id = p_id AND cleared_at IS NULL
   RETURNING * INTO v_row;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'not_open', 'freeze_id', p_id);
  END IF;

  UPDATE public.financial_alerts
     SET resolved = true, resolved_at = now(), resolved_by = v_uid
   WHERE source = 'ca_payout_freeze'
     AND resolved IS NOT TRUE
     AND context ->> 'dedupe_key' = 'freeze:' || p_id::text;

  PERFORM public.fn_raise_server_financial_alert(
    'info', 'ca_payout_freeze',
    format('Tournament payouts UNFROZEN by %s after %s (opened by %s: %s)',
           v_label, (now() - v_row.opened_at)::text, COALESCE(v_row.opened_by_label, '?'), v_row.reason),
    jsonb_build_object('freeze_id', v_row.id, 'scope', v_row.scope, 'cleared_by', v_uid,
                       'cleared_by_label', v_label, 'opened_at', v_row.opened_at,
                       'cleared_at', v_row.cleared_at),
    'freeze-cleared:' || v_row.id::text);

  RETURN jsonb_build_object('ok', true, 'freeze_id', v_row.id, 'scope', v_row.scope,
    'opened_at', v_row.opened_at, 'cleared_at', v_row.cleared_at, 'cleared_by', v_uid,
    'cleared_by_label', v_label);
END $$;


ALTER FUNCTION public.fn_ca_clear_payout_freeze(p_id uuid, p_actor_label text) OWNER TO postgres;

--
-- Name: fn_ca_close_tournament_seat_exit_authority(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_close_tournament_seat_exit_authority(p_token uuid, p_require_consumed boolean DEFAULT true) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_remaining integer;
BEGIN
  SELECT count(*) INTO v_remaining
    FROM public.tournament_seat_exit_authorizations a
   WHERE a.token=p_token;
  DELETE FROM public.tournament_seat_exit_authorizations a
   WHERE a.token=p_token;
  PERFORM set_config('app.tournament_seat_exit_token','',true);
  PERFORM set_config('app.tournament_seat_exit_operation','',true);
  IF COALESCE(p_require_consumed,true) AND v_remaining<>0 THEN
    RAISE EXCEPTION
      'tournament seat-exit authority left % live seat(s) unconsumed',v_remaining
      USING ERRCODE='P0404';
  END IF;
  RETURN v_remaining;
END;
$$;


ALTER FUNCTION public.fn_ca_close_tournament_seat_exit_authority(p_token uuid, p_require_consumed boolean) OWNER TO postgres;

--
-- Name: fn_ca_closing_position_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_closing_position_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION
    '% on ca_epoch_closing_positions is forbidden: a closing position is the only evidence of what every account held before an epoch reset, and it is kept seven years under docs/CHIP-JOURNAL-RETENTION-POLICY.md. Correct it forward with a new capture; never edit it.',
    TG_OP
    USING ERRCODE = 'P0403',
          HINT = 'CLAUDE.md 10.9: correct it forward, with a row that says what changed. Never edit history quiet.';
END;
$$;


ALTER FUNCTION public.fn_ca_closing_position_is_immutable() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_closing_position_is_immutable(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_closing_position_is_immutable() IS 'Refuses every UPDATE, DELETE and TRUNCATE on ca_epoch_closing_positions. Closing evidence is corrected forward by a new capture and is never edited or erased.';


--
-- Name: fn_ca_closing_position_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_closing_position_summary(p_capture_ref uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ref uuid := p_capture_ref;
  v_out jsonb;
BEGIN
  IF COALESCE(NULLIF(auth.role(), ''), session_user) NOT IN ('service_role', 'postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'closing-position summary is operator-only';
  END IF;

  IF v_ref IS NULL THEN
    SELECT capture_ref INTO v_ref FROM public.ca_epoch_closing_positions
     ORDER BY captured_at DESC LIMIT 1;
  END IF;
  IF v_ref IS NULL THEN
    RETURN jsonb_build_object('found', false,
      'error', 'no closing position has ever been captured');
  END IF;

  SELECT jsonb_build_object(
      'found', true,
      'capture_ref', v_ref,
      'epoch', max(epoch_name),
      'captured_at', max(captured_at),
      'accounts', count(*),
      'total', round(sum(balance), 2),
      'by_class', (SELECT jsonb_object_agg(account_type,
                       jsonb_build_object('accounts', n, 'total', t))
                     FROM (SELECT account_type, count(*) AS n, round(sum(balance),2) AS t
                             FROM public.ca_epoch_closing_positions
                            WHERE capture_ref = v_ref GROUP BY account_type) g))
    INTO v_out
    FROM public.ca_epoch_closing_positions WHERE capture_ref = v_ref;

  RETURN v_out;
END;
$$;


ALTER FUNCTION public.fn_ca_closing_position_summary(p_capture_ref uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_closing_position_summary(p_capture_ref uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_closing_position_summary(p_capture_ref uuid) IS 'Reads a captured closing position back, per class and in total. What the restore migration of the epoch reset contract step 3 is written from, and what the capture is compared against fn_ca_supply_snapshot() with before anybody trusts it.';


--
-- Name: fn_ca_club_actor_role(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_actor_role(p_club_id uuid, p_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT m.role FROM public.club_members m
      WHERE m.club_id = p_club_id AND m.user_id = p_user_id
        AND m.role IN ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent')
      ORDER BY CASE m.role
        WHEN 'owner' THEN 0 WHEN 'co_owner' THEN 1 WHEN 'admin' THEN 2
        WHEN 'super_agent' THEN 3 WHEN 'agent' THEN 4 ELSE 5 END
      LIMIT 1),
    (SELECT 'owner' FROM public.clubs c WHERE c.id = p_club_id AND c.owner_id = p_user_id),
    'player'
  );
$$;


ALTER FUNCTION public.fn_ca_club_actor_role(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_club_game_rows(uuid, date, date, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_game_rows(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_out jsonb;
BEGIN
  IF UPPER(COALESCE(NULLIF(p_game,''),'ALL')) <> 'ALL'
     OR UPPER(COALESCE(NULLIF(p_stakes,''),'ALL')) <> 'ALL'
     OR NULLIF(btrim(COALESCE(p_search,'')),'') IS NOT NULL THEN
    RETURN public.fn_ca_club_game_rows_filtered(
      p_club_id,p_start,p_end,p_game,p_stakes,p_search,p_limit
    );
  END IF;

  EXECUTE $query$
    WITH recent_cash_ids AS MATERIALIZED (
      SELECT tb.id
        FROM public.tables tb
       WHERE EXISTS (
         SELECT 1 FROM public.club_table_daily d
          WHERE d.club_id=$1 AND d.table_id=tb.id
            AND d.stat_date BETWEEN $2 AND $3
       )
       ORDER BY tb.created_at DESC NULLS LAST,tb.id DESC
       LIMIT $4
    ), cash AS MATERIALIZED (
      SELECT tb.id,COALESCE(tb.name,'Unnamed') name,
             UPPER(COALESCE(tb.game_variant,'nlh')) variant,
             CASE WHEN COALESCE(tb.game_variant,'') ILIKE '%plo%'
                        OR COALESCE(tb.game_variant,'') ILIKE '%omaha%' THEN 'OMAHA'
                  WHEN COALESCE(tb.game_variant,'') ILIKE '%mixed%'
                        OR COALESCE(tb.game_mode,'') ILIKE '%mixed%' THEN 'MIXED'
                  ELSE 'HOLDEM' END game_class,
             CASE WHEN COALESCE(tb.big_blind,0)<1 THEN 'MICRO'
                  WHEN COALESCE(tb.big_blind,0)<5 THEN 'SMALL'
                  WHEN COALESCE(tb.big_blind,0)<25 THEN 'MID' ELSE 'HIGH' END stakes_tier,
             COALESCE(tb.small_blind,0) small_blind,
             COALESCE(tb.big_blind,0) big_blind,
             CASE WHEN COALESCE(tb.rake_percent,-1)>=0 THEN tb.rake_percent END rake_percent,
             tb.created_at started_at,tb.created_by,tb.status,
             round(sum(d.rake),2) fee,round(sum(d.net),2) winnings,
             sum(d.hands)::bigint hands,max(d.players)::integer players
        FROM recent_cash_ids r
        JOIN public.tables tb ON tb.id=r.id
        JOIN public.club_table_daily d ON d.club_id=$1 AND d.table_id=r.id
          AND d.stat_date BETWEEN $2 AND $3
       GROUP BY tb.id,tb.name,tb.game_variant,tb.game_mode,tb.big_blind,
                tb.small_blind,tb.rake_percent,tb.created_at,tb.created_by,tb.status
    ), recent_tournament_ids AS MATERIALIZED (
      SELECT tr.id
        FROM public.tournaments tr
       WHERE EXISTS (
         SELECT 1 FROM public.ca_club_tournament_daily d
          WHERE d.club_id=$1 AND d.tournament_id=tr.id
            AND d.stat_date BETWEEN $2 AND $3
       )
       ORDER BY tr.start_time DESC NULLS LAST,tr.id DESC
       LIMIT $4
    ), tournament_facts AS MATERIALIZED (
      SELECT r.id,round(sum(d.fee),2) fee,round(sum(d.winnings),2) winnings
        FROM recent_tournament_ids r
        JOIN public.ca_club_tournament_daily d
          ON d.club_id=$1 AND d.tournament_id=r.id
         AND d.stat_date BETWEEN $2 AND $3
       GROUP BY r.id
    ), tournament_players AS MATERIALIZED (
      SELECT r.id,count(DISTINCT p.user_id)::integer players
        FROM recent_tournament_ids r
        LEFT JOIN public.ca_club_tournament_player_daily p
          ON p.club_id=$1 AND p.tournament_id=r.id
         AND p.stat_date BETWEEN $2 AND $3
       GROUP BY r.id
    ), all_rows AS (
      SELECT 'CASH'::text kind,c.id::text id,c.name,c.variant,c.game_class,
             c.stakes_tier,c.small_blind,c.big_blind,c.rake_percent,c.started_at,
             c.created_by,c.status,c.fee,c.winnings,c.hands,c.players,
             COALESCE(pr.username,'') creator_name,pr.avatar_url creator_avatar
        FROM cash c LEFT JOIN public.profiles pr ON pr.id=c.created_by
      UNION ALL
      SELECT CASE WHEN tr.tournament_type='SPIN' THEN 'SPIN'
                  WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,
             tr.id::text,COALESCE(tr.name,'Tournament'),
             UPPER(COALESCE(tr.variant,tr.game_type,'nlh')),
             CASE WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,
             'NA',0::numeric,0::numeric,NULL::numeric,tr.start_time,NULL::uuid,
             tr.status,f.fee,f.winnings,0::bigint,COALESCE(tp.players,0),
             ''::text,NULL::text
        FROM tournament_facts f
        JOIN public.tournaments tr ON tr.id=f.id
        LEFT JOIN tournament_players tp ON tp.id=f.id
    ), bounded AS MATERIALIZED (
      SELECT * FROM all_rows r
       ORDER BY r.started_at DESC NULLS LAST,r.kind DESC,r.id DESC
       LIMIT $4
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'kind',q.kind,'id',q.id,'name',q.name,'variant',q.variant,
      'game_class',q.game_class,'stakes_tier',q.stakes_tier,
      'blinds',CASE WHEN q.big_blind>0 THEN
        trim(trailing '.' from trim(trailing '0' from q.small_blind::text))||'/'||
        trim(trailing '.' from trim(trailing '0' from q.big_blind::text)) END,
      'rake_percent',q.rake_percent,'started_at',q.started_at,'status',q.status,
      'creator_id',q.created_by,'creator_name',NULLIF(q.creator_name,''),
      'creator_avatar',q.creator_avatar,'fee',q.fee,'winnings',q.winnings,
      'hands',q.hands,'players',q.players)
      ORDER BY q.started_at DESC NULLS LAST,q.kind DESC,q.id DESC),'[]'::jsonb)
      FROM bounded q
  $query$ INTO v_out USING p_club_id,p_start,p_end,p_limit;
  RETURN v_out;
END;
$_$;


ALTER FUNCTION public.fn_ca_club_game_rows(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text, p_limit integer) OWNER TO postgres;

--
-- Name: fn_ca_club_game_rows_filtered(uuid, date, date, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_game_rows_filtered(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_out jsonb;
BEGIN
  EXECUTE $query$
    WITH cash AS (
      SELECT c.table_id,SUM(c.rake) fee,SUM(c.net) winnings,SUM(c.hands) hands,
             MAX(c.players)::integer players FROM public.club_table_daily c
       WHERE c.club_id=$1 AND c.stat_date BETWEEN $2 AND $3 GROUP BY c.table_id
    ), tournament_facts AS (
      SELECT d.tournament_id,SUM(d.fee) fee,SUM(d.winnings) winnings
        FROM public.ca_club_tournament_daily d WHERE d.club_id=$1
         AND d.stat_date BETWEEN $2 AND $3 GROUP BY d.tournament_id
    ), all_rows AS (
      SELECT 'CASH'::text kind,t.id::text id,COALESCE(t.name,'Unnamed') name,
        UPPER(COALESCE(t.game_variant,'nlh')) variant,
        CASE WHEN COALESCE(t.game_variant,'') ILIKE '%plo%' OR COALESCE(t.game_variant,'') ILIKE '%omaha%' THEN 'OMAHA'
             WHEN COALESCE(t.game_variant,'') ILIKE '%mixed%' OR COALESCE(t.game_mode,'') ILIKE '%mixed%' THEN 'MIXED'
             ELSE 'HOLDEM' END game_class,
        CASE WHEN COALESCE(t.big_blind,0)<1 THEN 'MICRO'
             WHEN COALESCE(t.big_blind,0)<5 THEN 'SMALL'
             WHEN COALESCE(t.big_blind,0)<25 THEN 'MID' ELSE 'HIGH' END stakes_tier,
        COALESCE(t.small_blind,0) small_blind,COALESCE(t.big_blind,0) big_blind,
        CASE WHEN COALESCE(t.rake_percent,-1)>=0 THEN t.rake_percent END rake_percent,
        t.created_at started_at,t.created_by,t.status,round(c.fee,2) fee,
        round(c.winnings,2) winnings,c.hands::bigint,c.players,
        COALESCE(pr.username,'') creator_name,pr.avatar_url creator_avatar
        FROM cash c JOIN public.tables t ON t.id=c.table_id
        LEFT JOIN public.profiles pr ON pr.id=t.created_by
      UNION ALL
      SELECT CASE WHEN tr.tournament_type='SPIN' THEN 'SPIN'
                  WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,
        tr.id::text,COALESCE(tr.name,'Tournament'),UPPER(COALESCE(tr.variant,tr.game_type,'nlh')),
        CASE WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,'NA',
        0::numeric,0::numeric,NULL::numeric,tr.start_time,NULL::uuid,tr.status,
        round(COALESCE(f.fee,0),2),round(COALESCE(f.winnings,0),2),0::bigint,0::integer,
        ''::text,NULL::text
        FROM tournament_facts f JOIN public.tournaments tr ON tr.id=f.tournament_id
    ), bounded AS MATERIALIZED (
      SELECT * FROM all_rows r
       WHERE (UPPER(COALESCE(NULLIF($4,''),'ALL'))='ALL' OR r.game_class=UPPER($4))
         AND (UPPER(COALESCE(NULLIF($5,''),'ALL'))='ALL' OR r.stakes_tier=UPPER($5))
         AND (NULLIF(btrim(COALESCE($6,'')),'') IS NULL
           OR r.name ILIKE '%'||btrim($6)||'%' OR r.id ILIKE '%'||btrim($6)||'%'
           OR r.creator_name ILIKE '%'||btrim($6)||'%')
       ORDER BY r.started_at DESC NULLS LAST,r.kind DESC,r.id DESC LIMIT $7
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'kind',q.kind,'id',q.id,'name',q.name,'variant',q.variant,
      'game_class',q.game_class,'stakes_tier',q.stakes_tier,
      'blinds',CASE WHEN q.big_blind>0 THEN
        trim(trailing '.' from trim(trailing '0' from q.small_blind::text))||'/'||
        trim(trailing '.' from trim(trailing '0' from q.big_blind::text)) END,
      'rake_percent',q.rake_percent,'started_at',q.started_at,'status',q.status,
      'creator_id',q.created_by,'creator_name',NULLIF(q.creator_name,''),
      'creator_avatar',q.creator_avatar,'fee',q.fee,'winnings',q.winnings,
      'hands',q.hands,'players',CASE WHEN q.kind='CASH' THEN q.players ELSE COALESCE((
        SELECT count(DISTINCT p.user_id)::integer FROM public.ca_club_tournament_player_daily p
         WHERE p.club_id=$1 AND p.tournament_id=q.id::uuid
           AND p.stat_date BETWEEN $2 AND $3),0) END)
      ORDER BY q.started_at DESC NULLS LAST,q.kind DESC,q.id DESC),'[]'::jsonb)
      FROM bounded q
  $query$ INTO v_out USING p_club_id,p_start,p_end,p_game,p_stakes,p_search,p_limit;
  RETURN v_out;
END;
$_$;


ALTER FUNCTION public.fn_ca_club_game_rows_filtered(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text, p_limit integer) OWNER TO postgres;

--
-- Name: fn_ca_club_game_summary(uuid, date, date, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_game_summary(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_out jsonb;
BEGIN
  IF UPPER(COALESCE(NULLIF(p_game,''),'ALL')) <> 'ALL'
     OR UPPER(COALESCE(NULLIF(p_stakes,''),'ALL')) <> 'ALL'
     OR NULLIF(btrim(COALESCE(p_search,'')),'') IS NOT NULL THEN
    RETURN public.fn_ca_club_game_summary_filtered(
      p_club_id,p_start,p_end,p_game,p_stakes,p_search
    );
  END IF;

  SELECT jsonb_build_object(
    'games',COALESCE(c.games,0)+COALESCE(t.games,0),
    'total_winnings',round(COALESCE(c.winnings,0)+COALESCE(t.winnings,0),2),
    'mtt_winnings',round(COALESCE(t.winnings,0),2),
    'cash_winnings',round(COALESCE(c.winnings,0),2),
    'fee',round(COALESCE(c.fee,0)+COALESCE(t.fee,0),2),
    'cash_fee',round(COALESCE(c.fee,0),2),
    'mtt_fee',round(COALESCE(t.fee,0),2),
    'hands',COALESCE(c.hands,0))
    INTO v_out
    FROM (
      SELECT count(DISTINCT d.table_id)::bigint games,
             COALESCE(sum(d.rake),0) fee,COALESCE(sum(d.net),0) winnings,
             COALESCE(sum(d.hands),0)::bigint hands
        FROM public.club_table_daily d
       WHERE d.club_id=p_club_id AND d.stat_date BETWEEN p_start AND p_end
    ) c
    CROSS JOIN (
      SELECT count(DISTINCT d.tournament_id)::bigint games,
             COALESCE(sum(d.fee),0) fee,COALESCE(sum(d.winnings),0) winnings
        FROM public.ca_club_tournament_daily d
       WHERE d.club_id=p_club_id AND d.stat_date BETWEEN p_start AND p_end
    ) t;
  RETURN v_out;
END;
$$;


ALTER FUNCTION public.fn_ca_club_game_summary(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text) OWNER TO postgres;

--
-- Name: fn_ca_club_game_summary_filtered(uuid, date, date, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_game_summary_filtered(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_out jsonb;
BEGIN
  EXECUTE $query$
    WITH cash AS (
      SELECT c.table_id,SUM(c.rake) fee,SUM(c.net) winnings,SUM(c.hands) hands
        FROM public.club_table_daily c WHERE c.club_id=$1
         AND c.stat_date BETWEEN $2 AND $3 GROUP BY c.table_id
    ), tournament_facts AS (
      SELECT d.tournament_id,SUM(d.fee) fee,SUM(d.winnings) winnings
        FROM public.ca_club_tournament_daily d WHERE d.club_id=$1
         AND d.stat_date BETWEEN $2 AND $3 GROUP BY d.tournament_id
    ), all_rows AS (
      SELECT CASE WHEN COALESCE(t.game_variant,'') ILIKE '%plo%'
                    OR COALESCE(t.game_variant,'') ILIKE '%omaha%' THEN 'OMAHA'
                  WHEN COALESCE(t.game_variant,'') ILIKE '%mixed%'
                    OR COALESCE(t.game_mode,'') ILIKE '%mixed%' THEN 'MIXED'
                  ELSE 'HOLDEM' END game_class,
             CASE WHEN COALESCE(t.big_blind,0)<1 THEN 'MICRO'
                  WHEN COALESCE(t.big_blind,0)<5 THEN 'SMALL'
                  WHEN COALESCE(t.big_blind,0)<25 THEN 'MID' ELSE 'HIGH' END stakes_tier,
             t.id::text id,COALESCE(t.name,'Unnamed') name,
             COALESCE(pr.username,'') creator_name,c.fee,c.winnings,c.hands::bigint
        FROM cash c JOIN public.tables t ON t.id=c.table_id
        LEFT JOIN public.profiles pr ON pr.id=t.created_by
      UNION ALL
      SELECT CASE WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,'NA',
             tr.id::text,COALESCE(tr.name,'Tournament'),'',f.fee,f.winnings,0::bigint
        FROM tournament_facts f JOIN public.tournaments tr ON tr.id=f.tournament_id
    ), filtered AS (
      SELECT * FROM all_rows r
       WHERE (UPPER(COALESCE(NULLIF($4,''),'ALL'))='ALL' OR r.game_class=UPPER($4))
         AND (UPPER(COALESCE(NULLIF($5,''),'ALL'))='ALL' OR r.stakes_tier=UPPER($5))
         AND (NULLIF(btrim(COALESCE($6,'')),'') IS NULL
           OR r.name ILIKE '%'||btrim($6)||'%' OR r.id ILIKE '%'||btrim($6)||'%'
           OR r.creator_name ILIKE '%'||btrim($6)||'%')
    )
    SELECT jsonb_build_object(
      'games',count(*),
      'total_winnings',round(COALESCE(SUM(winnings),0),2),
      'mtt_winnings',round(COALESCE(SUM(winnings) FILTER(WHERE game_class IN('MTT','SNG')),0),2),
      'cash_winnings',round(COALESCE(SUM(winnings) FILTER(WHERE game_class NOT IN('MTT','SNG')),0),2),
      'fee',round(COALESCE(SUM(fee),0),2),
      'cash_fee',round(COALESCE(SUM(fee) FILTER(WHERE game_class NOT IN('MTT','SNG')),0),2),
      'mtt_fee',round(COALESCE(SUM(fee) FILTER(WHERE game_class IN('MTT','SNG')),0),2),
      'hands',COALESCE(SUM(hands),0)) FROM filtered
  $query$ INTO v_out USING p_club_id,p_start,p_end,p_game,p_stakes,p_search;
  RETURN v_out;
END;
$_$;


ALTER FUNCTION public.fn_ca_club_game_summary_filtered(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text) OWNER TO postgres;

--
-- Name: fn_ca_club_games(uuid, date, date, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_games(p_club_id uuid, p_start date, p_end date, p_game text DEFAULT 'ALL'::text, p_stakes text DEFAULT 'ALL'::text, p_search text DEFAULT NULL::text) RETURNS TABLE(kind text, id text, name text, variant text, game_class text, stakes_tier text, small_blind numeric, big_blind numeric, rake_percent numeric, started_at timestamp with time zone, created_by uuid, status text, fee numeric, winnings numeric, hands bigint, players integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NULLIF(btrim(COALESCE(p_search,'')),'') IS NULL THEN
    RETURN QUERY SELECT * FROM public.fn_ca_club_games_unsearched(
      p_club_id,p_start,p_end,p_game,p_stakes
    );
  ELSE
    RETURN QUERY SELECT * FROM public.fn_ca_club_games_searched(
      p_club_id,p_start,p_end,p_game,p_stakes,p_search
    );
  END IF;
END;
$$;


ALTER FUNCTION public.fn_ca_club_games(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text) OWNER TO postgres;

--
-- Name: fn_ca_club_games_searched(uuid, date, date, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_games_searched(p_club_id uuid, p_start date, p_end date, p_game text DEFAULT 'ALL'::text, p_stakes text DEFAULT 'ALL'::text, p_search text DEFAULT NULL::text) RETURNS TABLE(kind text, id text, name text, variant text, game_class text, stakes_tier text, small_blind numeric, big_blind numeric, rake_percent numeric, started_at timestamp with time zone, created_by uuid, status text, fee numeric, winnings numeric, hands bigint, players integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH cash AS (
    SELECT c.table_id,SUM(c.rake) fee,SUM(c.net) winnings,SUM(c.hands) hands,
           MAX(c.players) players FROM public.club_table_daily c
     WHERE c.club_id=p_club_id AND c.stat_date BETWEEN p_start AND p_end GROUP BY c.table_id
  ), tournament_facts AS MATERIALIZED (
    SELECT d.tournament_id,SUM(d.fee) fee,SUM(d.winnings) winnings
      FROM public.ca_club_tournament_daily d WHERE d.club_id=p_club_id
       AND d.stat_date BETWEEN p_start AND p_end GROUP BY d.tournament_id
  ), tournament_players AS MATERIALIZED (
    SELECT p.tournament_id,count(DISTINCT p.user_id)::integer players
      FROM public.ca_club_tournament_player_daily p WHERE p.club_id=p_club_id
       AND p.stat_date BETWEEN p_start AND p_end GROUP BY p.tournament_id
  ), all_rows AS (
    SELECT 'CASH'::text kind,t.id::text id,COALESCE(t.name,'Unnamed') name,
      UPPER(COALESCE(t.game_variant,'nlh')) variant,
      CASE WHEN COALESCE(t.game_variant,'') ILIKE '%plo%' OR COALESCE(t.game_variant,'') ILIKE '%omaha%' THEN 'OMAHA'
           WHEN COALESCE(t.game_variant,'') ILIKE '%mixed%' OR COALESCE(t.game_mode,'') ILIKE '%mixed%' THEN 'MIXED'
           ELSE 'HOLDEM' END game_class,COALESCE(t.small_blind,0) small_blind,
      COALESCE(t.big_blind,0) big_blind,
      CASE WHEN COALESCE(t.rake_percent,-1)>=0 THEN t.rake_percent END rake_percent,
      t.created_at started_at,t.created_by,t.status,round(c.fee,2) fee,
      round(c.winnings,2) winnings,c.hands::bigint,c.players::integer,
      COALESCE(pr.username,'') creator_username
      FROM cash c JOIN public.tables t ON t.id=c.table_id
      LEFT JOIN public.profiles pr ON pr.id=t.created_by
    UNION ALL
    SELECT CASE WHEN tr.tournament_type='SPIN' THEN 'SPIN'
                WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,
      tr.id::text,COALESCE(tr.name,'Tournament'),UPPER(COALESCE(tr.variant,tr.game_type,'nlh')),
      CASE WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,
      0::numeric,0::numeric,NULL::numeric,tr.start_time,NULL::uuid,tr.status,
      round(COALESCE(f.fee,0),2),round(COALESCE(f.winnings,0),2),0::bigint,
      COALESCE(tp.players,0)::integer,''::text
      FROM tournament_facts f JOIN public.tournaments tr ON tr.id=f.tournament_id
      LEFT JOIN tournament_players tp ON tp.tournament_id=f.tournament_id
  ), tagged AS (
    SELECT r.*,CASE WHEN r.game_class IN('MTT','SNG') THEN 'NA'
      WHEN r.big_blind<1 THEN 'MICRO' WHEN r.big_blind<5 THEN 'SMALL'
      WHEN r.big_blind<25 THEN 'MID' ELSE 'HIGH' END stakes_tier FROM all_rows r
  )
  SELECT t.kind,t.id,t.name,t.variant,t.game_class,t.stakes_tier,t.small_blind,
    t.big_blind,t.rake_percent,t.started_at,t.created_by,t.status,t.fee,t.winnings,
    t.hands,t.players FROM tagged t
   WHERE (UPPER(COALESCE(NULLIF(p_game,''),'ALL'))='ALL' OR t.game_class=UPPER(p_game))
     AND (UPPER(COALESCE(NULLIF(p_stakes,''),'ALL'))='ALL' OR t.stakes_tier=UPPER(p_stakes))
     AND (NULLIF(btrim(COALESCE(p_search,'')),'') IS NULL
       OR t.name ILIKE '%'||btrim(p_search)||'%'
       OR t.id ILIKE '%'||btrim(p_search)||'%'
       OR t.creator_username ILIKE '%'||btrim(p_search)||'%');
$$;


ALTER FUNCTION public.fn_ca_club_games_searched(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text) OWNER TO postgres;

--
-- Name: fn_ca_club_games_unsearched(uuid, date, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_games_unsearched(p_club_id uuid, p_start date, p_end date, p_game text DEFAULT 'ALL'::text, p_stakes text DEFAULT 'ALL'::text) RETURNS TABLE(kind text, id text, name text, variant text, game_class text, stakes_tier text, small_blind numeric, big_blind numeric, rake_percent numeric, started_at timestamp with time zone, created_by uuid, status text, fee numeric, winnings numeric, hands bigint, players integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  RETURN QUERY EXECUTE $query$
    WITH cash AS (
      SELECT c.table_id,SUM(c.rake) fee,SUM(c.net) winnings,SUM(c.hands) hands,
             MAX(c.players) players FROM public.club_table_daily c
       WHERE c.club_id=$1 AND c.stat_date BETWEEN $2 AND $3 GROUP BY c.table_id
    ), tournament_facts AS MATERIALIZED (
      SELECT d.tournament_id,SUM(d.fee) fee,SUM(d.winnings) winnings
        FROM public.ca_club_tournament_daily d WHERE d.club_id=$1
         AND d.stat_date BETWEEN $2 AND $3 GROUP BY d.tournament_id
    ), tournament_players AS MATERIALIZED (
      SELECT p.tournament_id,count(DISTINCT p.user_id)::integer players
        FROM public.ca_club_tournament_player_daily p WHERE p.club_id=$1
         AND p.stat_date BETWEEN $2 AND $3 GROUP BY p.tournament_id
    ), all_rows AS (
      SELECT 'CASH'::text kind,t.id::text id,COALESCE(t.name,'Unnamed') name,
        UPPER(COALESCE(t.game_variant,'nlh')) variant,
        CASE WHEN COALESCE(t.game_variant,'') ILIKE '%plo%' OR COALESCE(t.game_variant,'') ILIKE '%omaha%' THEN 'OMAHA'
             WHEN COALESCE(t.game_variant,'') ILIKE '%mixed%' OR COALESCE(t.game_mode,'') ILIKE '%mixed%' THEN 'MIXED'
             ELSE 'HOLDEM' END game_class,COALESCE(t.small_blind,0) small_blind,
        COALESCE(t.big_blind,0) big_blind,
        CASE WHEN COALESCE(t.rake_percent,-1)>=0 THEN t.rake_percent END rake_percent,
        t.created_at started_at,t.created_by,t.status,round(c.fee,2) fee,
        round(c.winnings,2) winnings,c.hands::bigint,c.players::integer
        FROM cash c JOIN public.tables t ON t.id=c.table_id
      UNION ALL
      SELECT CASE WHEN tr.tournament_type='SPIN' THEN 'SPIN'
                  WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,
        tr.id::text,COALESCE(tr.name,'Tournament'),UPPER(COALESCE(tr.variant,tr.game_type,'nlh')),
        CASE WHEN tr.tournament_type='SNG' THEN 'SNG' ELSE 'MTT' END,
        0::numeric,0::numeric,NULL::numeric,tr.start_time,NULL::uuid,tr.status,
        round(COALESCE(f.fee,0),2),round(COALESCE(f.winnings,0),2),0::bigint,
        COALESCE(tp.players,0)::integer
        FROM tournament_facts f JOIN public.tournaments tr ON tr.id=f.tournament_id
        LEFT JOIN tournament_players tp ON tp.tournament_id=f.tournament_id
    ), tagged AS (
      SELECT r.*,CASE WHEN r.game_class IN('MTT','SNG') THEN 'NA'
        WHEN r.big_blind<1 THEN 'MICRO' WHEN r.big_blind<5 THEN 'SMALL'
        WHEN r.big_blind<25 THEN 'MID' ELSE 'HIGH' END stakes_tier FROM all_rows r
    )
    SELECT t.kind,t.id,t.name,t.variant,t.game_class,t.stakes_tier,t.small_blind,
      t.big_blind,t.rake_percent,t.started_at,t.created_by,t.status,t.fee,t.winnings,
      t.hands,t.players FROM tagged t
     WHERE (UPPER(COALESCE(NULLIF($4,''),'ALL'))='ALL' OR t.game_class=UPPER($4))
       AND (UPPER(COALESCE(NULLIF($5,''),'ALL'))='ALL' OR t.stakes_tier=UPPER($5))
  $query$ USING p_club_id,p_start,p_end,p_game,p_stakes;
END;
$_$;


ALTER FUNCTION public.fn_ca_club_games_unsearched(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text) OWNER TO postgres;

--
-- Name: fn_ca_club_gets_a_baseline(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_gets_a_baseline() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    BEGIN
      /* A club created after the baseline cutover had no opening row, and
         reconcile_ledger_nightly read that absence as an opening of zero -
         9,981,739.70 of fabricated critical drift against Deep Stack Society,
         every night, from the day it was created. A new club opens at whatever
         it is created holding, which is normally nothing; recording it here
         means the reconciler is never guessing. */
      INSERT INTO public.ca_treasury_baseline
        (club_id, opening_balance, ledger_at_baseline, unledgered_gap, taken_at)
      VALUES (NEW.id, round(COALESCE(NEW.chip_treasury, 0), 2), 0,
              round(COALESCE(NEW.chip_treasury, 0), 2), now())
      ON CONFLICT DO NOTHING;
      RETURN NEW;
    END;
    $$;


ALTER FUNCTION public.fn_ca_club_gets_a_baseline() OWNER TO postgres;

--
-- Name: fn_ca_club_hand_flags(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_hand_flags(p_club_id uuid, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, hand_id uuid, hand_number bigint, table_id uuid, table_name text, flagged_by uuid, note text, status text, operator_note text, reviewed_by uuid, reviewed_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF NOT public.fn_ca_is_club_staff(p_club_id, v_uid) THEN
    RAISE EXCEPTION 'not an operator of this club' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT f.id, f.hand_id, f.hand_number, f.table_id,
         t.name AS table_name,
         f.flagged_by,
         f.note, f.status, f.operator_note, f.reviewed_by, f.reviewed_at,
         f.created_at, f.updated_at
    FROM public.ca_hand_flags f
    LEFT JOIN public.tables t ON t.id = f.table_id
   WHERE f.club_id = p_club_id
     AND (p_status IS NULL OR p_status = 'all' OR f.status = p_status)
   ORDER BY
     CASE WHEN f.status IN ('open', 'under_review') THEN 0 ELSE 1 END,
     CASE WHEN f.status IN ('open', 'under_review') THEN f.created_at END ASC,
     f.updated_at DESC
   LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 100), 500));
END;
$$;


ALTER FUNCTION public.fn_ca_club_hand_flags(p_club_id uuid, p_status text, p_limit integer) OWNER TO postgres;

--
-- Name: fn_ca_club_rake_daily_apply(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_apply(p_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n integer := 0;
BEGIN
  IF p_ids IS NULL OR cardinality(p_ids) = 0 THEN RETURN 0; END IF;
  INSERT INTO public.ca_club_rake_daily AS d
         (club_id, stat_date, hands, rake, bbj, pot, source_rows, updated_at)
  SELECT c.club_id, c.stat_date, c.hands, c.rake, c.bbj, c.pot, c.source_rows, now()
    FROM public.fn_ca_club_rake_daily_compute(now(), now(), p_ids) c
  ON CONFLICT (club_id, stat_date) DO UPDATE
     SET hands = d.hands + EXCLUDED.hands,
         rake = d.rake + EXCLUDED.rake,
         bbj = d.bbj + EXCLUDED.bbj,
         pot = d.pot + EXCLUDED.pot,
         source_rows = d.source_rows + EXCLUDED.source_rows,
         updated_at = now();
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_apply(p_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_ca_club_rake_daily_compute(timestamp with time zone, timestamp with time zone, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_compute(p_from timestamp with time zone, p_to timestamp with time zone, p_ids uuid[]) RETURNS TABLE(club_id uuid, stat_date date, hands bigint, rake numeric, bbj numeric, pot numeric, source_rows bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  WITH src AS (
    SELECT r.id, r.table_id, r.club_id, r.created_at,
           coalesce(r.rake_amount, 0) AS rake, coalesce(r.bbj_contribution, 0) AS bbj,
           coalesce(r.pot_size, 0) AS pot, r.player_contributions
      FROM rake_records r
     WHERE p_ids IS NOT NULL AND r.id = ANY (p_ids)
       AND r.club_id IS NOT NULL AND NOT coalesce(r.is_tournament, false)
    UNION ALL
    SELECT r.id, r.table_id, r.club_id, r.created_at,
           coalesce(r.rake_amount, 0), coalesce(r.bbj_contribution, 0),
           coalesce(r.pot_size, 0), r.player_contributions
      FROM rake_records r
     WHERE p_ids IS NULL AND r.created_at >= p_from AND r.created_at < p_to
       AND r.club_id IS NOT NULL AND NOT coalesce(r.is_tournament, false)
  ),
  tbl AS (
    SELECT s.id, s.club_id AS table_club, (s.created_at AT TIME ZONE 'UTC')::date AS day,
           s.rake, s.bbj, s.pot, s.player_contributions, t.union_id
      FROM src s
      LEFT JOIN tables t ON t.id = s.table_id
     WHERE t.id IS NULL OR t.tournament_id IS NULL
  ),
  -- Only a union table needs its contributions read: a standalone table's
  -- rake has exactly one place to go. A key that is not a uuid or a value
  -- that is not a number is ignored, never raised: a reporting rollup must
  -- not fail a ledger write. A contribution of zero still counts the hand
  -- for that player's club, as club_table_daily counts it.
  contrib AS (
    SELECT b.id, b.union_id,
           CASE WHEN e.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                THEN e.key::uuid END AS uid,
           CASE WHEN e.value ~ '^-?[0-9]+(\.[0-9]+)?$' THEN e.value::numeric END AS contrib
      FROM tbl b
      CROSS JOIN LATERAL jsonb_each_text(
        CASE WHEN jsonb_typeof(b.player_contributions) = 'object'
             THEN b.player_contributions ELSE '{}'::jsonb END) e
     WHERE b.union_id IS NOT NULL
  ),
  attributed AS (
    SELECT c.id, c.contrib,
           coalesce((SELECT cm.club_id
                       FROM club_members cm
                       JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = c.union_id
                      WHERE cm.user_id = c.uid
                      ORDER BY cm.joined_at ASC NULLS LAST, cm.club_id
                      LIMIT 1),
                    b.table_club) AS club_id
      FROM contrib c JOIN tbl b ON b.id = c.id
     WHERE c.uid IS NOT NULL AND c.contrib IS NOT NULL AND c.contrib >= 0
  ),
  split AS (
    SELECT a.id, a.club_id, sum(a.contrib) AS contrib, count(*) AS src_rows
      FROM attributed a GROUP BY a.id, a.club_id
  ),
  split_total AS (
    SELECT s.id, sum(s.contrib) AS tot FROM split s GROUP BY s.id
  ),
  hand_rows AS (
    SELECT b.*, EXISTS (SELECT 1 FROM split_total st WHERE st.id = b.id AND st.tot > 0) AS has_split
      FROM tbl b
  ),
  parts AS (
    -- A union hand with a usable split: rake by contribution share, and one
    -- hand for every club that contributed.
    SELECT h.day, s.club_id, 1::bigint AS hands, h.rake * s.contrib / st.tot AS rake,
           0::numeric AS bbj, 0::numeric AS pot, s.src_rows
      FROM split s
      JOIN split_total st ON st.id = s.id AND st.tot > 0
      JOIN hand_rows h ON h.id = s.id
    UNION ALL
    -- The table's club: the drop and the pot volume of every hand it hosted,
    -- plus the whole hand when nothing could be attributed.
    SELECT h.day, h.table_club,
           CASE WHEN h.has_split THEN 0 ELSE 1 END,
           CASE WHEN h.has_split THEN 0 ELSE h.rake END,
           h.bbj, h.pot,
           CASE WHEN h.has_split THEN 0 ELSE 1 END
      FROM hand_rows h
  )
  SELECT p.club_id, p.day, sum(p.hands)::bigint, sum(p.rake), sum(p.bbj), sum(p.pot),
         sum(p.src_rows)::bigint
    FROM parts p
   GROUP BY p.club_id, p.day;
$_$;


ALTER FUNCTION public.fn_ca_club_rake_daily_compute(p_from timestamp with time zone, p_to timestamp with time zone, p_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_ca_club_rake_daily_ledger_total(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_ledger_total(p_day date) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(SUM(r.rake_amount), 0)
    FROM rake_records r
   WHERE r.created_at >= (p_day::timestamp AT TIME ZONE 'UTC')
     AND r.created_at <  ((p_day + 1)::timestamp AT TIME ZONE 'UTC')
     AND r.club_id IS NOT NULL
     AND NOT COALESCE(r.is_tournament, false)
     AND EXISTS (SELECT 1 FROM tables t WHERE t.id = r.table_id AND t.tournament_id IS NULL);
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_ledger_total(p_day date) OWNER TO postgres;

--
-- Name: fn_ca_club_rake_daily_rebuild(date, date, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_rebuild(p_start date, p_end date, p_include_today boolean DEFAULT false) RETURNS TABLE(stat_date date, clubs bigint, hands bigint, rake numeric, ledger_rake numeric, difference numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n integer;
BEGIN
  IF NOT (session_user IN ('postgres', 'supabase_admin')
          OR coalesce(auth.role(), '') = 'service_role'
          OR coalesce(fn_is_platform_admin(), false)) THEN
    RAISE EXCEPTION 'rebuild is an operator action' USING ERRCODE = '42501';
  END IF;
  v_n := public.fn_ca_club_rake_daily_rebuild_range(p_start, p_end, p_include_today);
  RETURN QUERY
  SELECT r.stat_date, count(*)::bigint, coalesce(sum(r.hands), 0)::bigint,
         round(coalesce(sum(r.rake), 0), 4),
         round(public.fn_ca_club_rake_daily_ledger_total(r.stat_date), 4),
         round(public.fn_ca_club_rake_daily_ledger_total(r.stat_date)
               - coalesce(sum(r.rake), 0), 4)
    FROM public.ca_club_rake_daily r
   WHERE r.stat_date BETWEEN LEAST(p_start, p_end) AND GREATEST(p_start, p_end)
   GROUP BY r.stat_date ORDER BY r.stat_date;
END;
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_rebuild(p_start date, p_end date, p_include_today boolean) OWNER TO postgres;

--
-- Name: fn_ca_club_rake_daily_rebuild_range(date, date, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_rebuild_range(p_start date, p_end date, p_include_today boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_last date := CASE WHEN coalesce(p_include_today, false) THEN v_today ELSE v_today - 1 END;
  v_s date := LEAST(coalesce(p_start, v_today), coalesce(p_end, v_today));
  v_e date := LEAST(GREATEST(coalesce(p_start, v_today), coalesce(p_end, v_today)), v_last);
  d date;
  v_days integer := 0;
BEGIN
  IF v_s > v_e THEN RETURN 0; END IF;
  FOR d IN SELECT gs::date FROM generate_series(v_s, v_e, interval '1 day') gs LOOP
    -- One pass. A complete day has no writer to race, so the recount is
    -- exact; the caller checks the result against the ledger and says so.
    -- Retrying was measured on a live day and never closed the gap: see the
    -- header.
    PERFORM pg_advisory_xact_lock(hashtextextended('ca_club_rake_daily:' || d::text, 42));
    DELETE FROM public.ca_club_rake_daily r WHERE r.stat_date = d;
    INSERT INTO public.ca_club_rake_daily AS x
           (club_id, stat_date, hands, rake, bbj, pot, source_rows, updated_at)
    SELECT c.club_id, c.stat_date, c.hands, c.rake, c.bbj, c.pot, c.source_rows, now()
      FROM public.fn_ca_club_rake_daily_compute(
             (d::timestamp AT TIME ZONE 'UTC'), ((d + 1)::timestamp AT TIME ZONE 'UTC'), NULL) c
    ON CONFLICT (club_id, stat_date) DO UPDATE
       SET hands = x.hands + EXCLUDED.hands,
           rake = x.rake + EXCLUDED.rake,
           bbj = x.bbj + EXCLUDED.bbj,
           pot = x.pot + EXCLUDED.pot,
           source_rows = x.source_rows + EXCLUDED.source_rows,
           updated_at = now();
    v_days := v_days + 1;
  END LOOP;
  RETURN v_days;
END;
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_rebuild_range(p_start date, p_end date, p_include_today boolean) OWNER TO postgres;

--
-- Name: fn_ca_club_rake_daily_user_apply(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_user_apply(p_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.ca_club_rake_daily_user (club_id, day, user_id, rake_cents, hands, updated_at)
  SELECT ra.club_id,
         (ra.created_at AT TIME ZONE 'UTC')::date,
         ra.player_id,
         SUM(round(ra.rake_amount * 100))::bigint,
         count(*)::bigint,
         now()
    FROM public.rake_attributions ra
   WHERE ra.id = ANY (p_ids)
     AND ra.club_id IS NOT NULL
     AND ra.player_id IS NOT NULL
     AND ra.rake_amount > 0
   GROUP BY 1, 2, 3
  ON CONFLICT (club_id, day, user_id) DO UPDATE
     SET rake_cents = public.ca_club_rake_daily_user.rake_cents + EXCLUDED.rake_cents,
         hands      = public.ca_club_rake_daily_user.hands + EXCLUDED.hands,
         updated_at = now();
END;
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_user_apply(p_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_ca_club_rake_daily_user_rebuild_day(uuid, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_user_rebuild_day(p_club_id uuid, p_day date, p_user_id uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_rows bigint := 0;
BEGIN
  IF p_club_id IS NULL OR p_day IS NULL THEN
    RETURN 0;
  END IF;

  DELETE FROM public.ca_club_rake_daily_user d
   WHERE d.club_id = p_club_id AND d.day = p_day
     AND (p_user_id IS NULL OR d.user_id = p_user_id);

  INSERT INTO public.ca_club_rake_daily_user (club_id, day, user_id, rake_cents, hands, updated_at)
  SELECT ra.club_id,
         p_day,
         ra.player_id,
         SUM(round(ra.rake_amount * 100))::bigint,
         count(*)::bigint,
         now()
    FROM public.rake_attributions ra
   WHERE ra.club_id = p_club_id
     AND ra.created_at >= p_day::timestamptz
     AND ra.created_at <  (p_day + 1)::timestamptz
     AND ra.player_id IS NOT NULL
     AND ra.rake_amount > 0
     AND (p_user_id IS NULL OR ra.player_id = p_user_id)
   GROUP BY 1, 3;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END;
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_user_rebuild_day(p_club_id uuid, p_day date, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_collusion_detector_health(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_collusion_detector_health(p_cadence_minutes integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cadence     int := greatest(coalesce(p_cadence_minutes, 30), 1);
  v_stale_after int := v_cadence * 3 * 60;
  s public.ca_collusion_scan_state;
  v_newest_finding timestamptz;
  v_since_success  numeric;
  v_behind         numeric;
  v_has_gap        boolean;
  v_process_stale  boolean;
  v_coverage_stale boolean;
  v_status         text;
begin
  select * into s from public.ca_collusion_scan_state limit 1;

  -- Indexed now (see section 5): this used to seq-scan 169,530 rows on
  -- every render of every integrity panel.
  select max(created_at) into v_newest_finding from public.collusion_tracking;

  if not found or s.last_success_at is null then
    -- NEVER RUN is its own answer. Collapsing it into stale tells an
    -- operator a brand-new detector is broken; collapsing it into live
    -- tells them a broken one is new. Every key the live branch returns
    -- is returned here too, as NULL, so a console cannot read a missing
    -- field as a zero.
    return jsonb_build_object(
      'ok', true, 'status', 'never_run', 'stale', true,
      'stale_after_seconds', v_stale_after,
      'cadence_minutes', v_cadence,
      'last_success_at', null,
      'seconds_since_success', null,
      'seconds_behind', null,
      'last_scanned_hands', null,
      'last_findings', null,
      'catching_up', null,
      'unscanned_from', s.unscanned_from,
      'unscanned_to', s.unscanned_to,
      'unscanned_note', s.unscanned_note,
      'has_unscanned_gap', s.unscanned_from is not null,
      'newest_finding_at', v_newest_finding);
  end if;

  v_since_success := extract(epoch from now() - s.last_success_at);
  v_behind        := extract(epoch from now() - s.last_window_end);
  v_has_gap       := s.unscanned_from is not null;

  -- TWO INDEPENDENT QUESTIONS. The process running is not the same as
  -- the coverage keeping up, and the old health only asked the first.
  v_process_stale  := v_since_success > v_stale_after;
  v_coverage_stale := v_behind > v_stale_after;

  v_status := case
                when v_process_stale  then 'stale'    -- it stopped running
                when v_coverage_stale then 'behind'   -- it runs, and loses ground
                else 'live'
              end;

  return jsonb_build_object(
    'ok', true,
    'status', v_status,
    -- A HOLE IN THE RECORD IS NOT HEALTH. While an unscanned gap is
    -- recorded, this never answers false, whatever the process is doing.
    'stale', v_process_stale or v_coverage_stale or v_has_gap,
    'stale_after_seconds', v_stale_after,
    'cadence_minutes', v_cadence,
    'last_success_at', s.last_success_at,
    'seconds_since_success', round(v_since_success),
    'seconds_behind', round(v_behind),
    'last_scanned_hands', s.last_scanned_hands,
    'last_findings', s.last_findings,
    'catching_up', s.last_budget_hit,
    'unscanned_from', s.unscanned_from,
    'unscanned_to', s.unscanned_to,
    'unscanned_note', s.unscanned_note,
    'has_unscanned_gap', v_has_gap,
    'newest_finding_at', v_newest_finding);
end;
$$;


ALTER FUNCTION public.fn_ca_collusion_detector_health(p_cadence_minutes integer) OWNER TO postgres;

--
-- Name: fn_ca_collusion_scan(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_collusion_scan(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(days => GREATEST(p_days,1));
  r RECORD; v_flagged int := 0; v_scanned int := 0;
BEGIN
  FOR r IN
    WITH pairflow AS (
      SELECT LEAST(t.winner_id, t.loser_id)    AS ua,
             GREATEST(t.winner_id, t.loser_id) AS ub,
             count(*)                          AS hands_together,
             sum(t.amount)                     AS gross_flow,
             sum(CASE WHEN t.winner_id < t.loser_id THEN t.amount ELSE -t.amount END) AS net_to_ua
        FROM public.ca_hand_transfers t
       WHERE t.played_at > v_since
         AND t.winner_id IS NOT NULL AND t.loser_id IS NOT NULL
         AND t.amount > 0
       GROUP BY 1, 2
    )
    SELECT CASE WHEN net_to_ua >= 0 THEN ua ELSE ub END AS receiver,
           CASE WHEN net_to_ua >= 0 THEN ub ELSE ua END AS sender,
           hands_together, gross_flow, abs(net_to_ua) AS net_flow,
           round(abs(net_to_ua) / NULLIF(gross_flow, 0), 3) AS direction_ratio
      FROM pairflow
     WHERE hands_together >= 20
       AND abs(net_to_ua) >= 5000
       AND abs(net_to_ua) / NULLIF(gross_flow, 0) > 0.8
  LOOP
    v_scanned := v_scanned + 1;
    INSERT INTO public.ca_collusion_signals
      (window_days, user_a, user_b, hands_together, gross_flow, net_flow,
       direction_ratio, both_cert, detail)
    VALUES
      (p_days, r.receiver, r.sender, r.hands_together, r.gross_flow, r.net_flow,
       r.direction_ratio,
       public.fn_ca_is_cert_account(r.receiver) AND public.fn_ca_is_cert_account(r.sender),
       jsonb_build_object('since', v_since));
    v_flagged := v_flagged + 1;

    -- signal, never a page: info for cert pairs and moderate flows; warning
    -- (one push, per policy) only for a large real-account flow
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_collusion_scan', 'unknown',
      CASE WHEN r.net_flow >= 50000
              AND NOT (public.fn_ca_is_cert_account(r.receiver)
                       AND public.fn_ca_is_cert_account(r.sender))
           THEN 'warning' ELSE 'info' END,
      'collusion:' || r.receiver::text || ':' || r.sender::text || ':' || to_char(now(), 'IYYY-IW'),
      r.net_flow, NULL, NULL,
      'reporting', 'user', r.receiver, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'one-directional chip flow: ' || r.net_flow || ' chips over ' || r.hands_together
        || ' shared hands in ' || p_days || 'd (direction ratio ' || r.direction_ratio
        || ') - review the pair; no automatic action taken',
      true,
      jsonb_build_object('receiver', r.receiver, 'sender', r.sender,
                         'hands_together', r.hands_together,
                         'gross_flow', r.gross_flow, 'net_flow', r.net_flow,
                         'direction_ratio', r.direction_ratio));
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'window_days', p_days,
                            'pairs_flagged', v_flagged);
END $$;


ALTER FUNCTION public.fn_ca_collusion_scan(p_days integer) OWNER TO postgres;

--
-- Name: fn_ca_collusion_scan_advance(timestamp with time zone, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_collusion_scan_advance(p_window_end timestamp with time zone, p_scanned_hands integer, p_findings integer, p_duration_ms integer, p_budget_hit boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id     boolean;
  v_before timestamptz;
  v_after  timestamptz;
  v_rows   int;
begin
  -- The id comes back with the mark so the UPDATE can be keyed on it.
  -- FOR UPDATE serialises overlapping runs on this one row; the
  -- dispatcher's client timeout does not cancel the worker, so a slow run
  -- and the next cron fire overlap by design.
  select s.id, s.last_window_end into v_id, v_before
    from public.ca_collusion_scan_state s
   limit 1
     for update;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_state_row');
  end if;

  v_after := least(greatest(coalesce(p_window_end, v_before), v_before), now());

  update public.ca_collusion_scan_state
     set last_window_end    = greatest(last_window_end, v_after),
         last_success_at    = now(),
         last_duration_ms   = p_duration_ms,
         last_scanned_hands = p_scanned_hands,
         last_findings      = p_findings,
         last_budget_hit    = coalesce(p_budget_hit, false),
         updated_at         = now()
   -- THE WHOLE FIX. The table is a singleton and this predicate selects
   -- exactly the row the SELECT above locked, so it changes nothing about
   -- what the statement does - and it is the difference between the
   -- function running and PostgREST refusing it with 21000 before a single
   -- row is touched. Never remove it as redundant. It is not redundant to
   -- safeupdate, which reads the statement, not the table.
   where id = v_id;
  get diagnostics v_rows = row_count;

  if v_rows = 0 then
    return jsonb_build_object('ok', false, 'reason', 'no_rows_updated');
  end if;

  return jsonb_build_object('ok', true, 'from', v_before, 'to', v_after,
                            'advanced_seconds',
                            round(extract(epoch from v_after - v_before)));
end;
$$;


ALTER FUNCTION public.fn_ca_collusion_scan_advance(p_window_end timestamp with time zone, p_scanned_hands integer, p_findings integer, p_duration_ms integer, p_budget_hit boolean) OWNER TO postgres;

--
-- Name: fn_ca_collusion_scan_state(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_collusion_scan_state() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
           'ok', true,
           'last_window_end', s.last_window_end,
           'last_success_at', s.last_success_at,
           'last_duration_ms', s.last_duration_ms,
           'last_scanned_hands', s.last_scanned_hands,
           'last_findings', s.last_findings,
           'last_budget_hit', s.last_budget_hit,
           'unscanned_from', s.unscanned_from,
           'unscanned_to', s.unscanned_to,
           'seconds_since_success',
             case when s.last_success_at is null then null
                  else round(extract(epoch from now() - s.last_success_at)) end,
           'seconds_behind', round(extract(epoch from now() - s.last_window_end)))
    from public.ca_collusion_scan_state s
   limit 1;
$$;


ALTER FUNCTION public.fn_ca_collusion_scan_state() OWNER TO postgres;

--
-- Name: fn_ca_commit_hand_settlement(uuid, bigint, jsonb, numeric, numeric, text, numeric, jsonb, jsonb, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commit_hand_settlement(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric, p_hand_row jsonb, p_units jsonb, p_instance_id text, p_lease_generation uuid, p_post_commit_obligations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_result jsonb;
  v_hand_id uuid;
  v_request_hash text;
  v_hash text;
  v_existing_request_hash text;
  v_existing_hash text;
  v_payload jsonb;
  v_club_id uuid;
  v_tournament_id uuid;
  v_item jsonb;
  v_expected integer;
  v_updated integer;
  v_row_count integer;
  v_exact_seat_generation boolean := false;
BEGIN
  -- This public 12-argument door is the outermost accepted-hand authority.
  -- Take the lifecycle root before its preserved exact-generation core can
  -- lock a lease, tournament or table. The owner-only nine-argument core
  -- re-enters this shared transaction lock defensively; that acquisition is
  -- harmless and keeps the private core safe from future owner-only callers.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));

  IF jsonb_typeof(p_post_commit_obligations) IS DISTINCT FROM 'object'
     OR p_post_commit_obligations->>'version' <> '1'
     OR jsonb_typeof(p_post_commit_obligations->'time_banks') IS DISTINCT FROM 'array'
     OR jsonb_typeof(p_post_commit_obligations->'promo_playthrough') IS DISTINCT FROM 'array'
     OR jsonb_typeof(p_post_commit_obligations->'insurance') IS DISTINCT FROM 'array'
     OR NOT (p_post_commit_obligations ? 'pending_addons')
     OR NOT (p_post_commit_obligations ? 'rake')
     OR NOT (p_post_commit_obligations ? 'bbj_contribution')
     OR p_post_commit_obligations ? 'accepted_hand_facts'
     OR jsonb_typeof(p_post_commit_obligations->'rake') NOT IN ('object', 'null')
     OR jsonb_typeof(p_post_commit_obligations->'bbj_contribution') NOT IN ('object', 'null')
     OR jsonb_typeof(p_post_commit_obligations->'pending_addons') NOT IN ('object', 'null') THEN
    RAISE EXCEPTION
      'atomic hand commit refused (invalid_post_commit_obligations)';
  END IF;

  -- Database-first expansion. The previous engine may send an entirely legacy
  -- roster while it drains, but exact and legacy identities never mix.
  IF jsonb_typeof(p_stacks) = 'array' AND jsonb_array_length(p_stacks) > 0 THEN
    IF EXISTS (
      SELECT 1
        FROM jsonb_array_elements(p_stacks) x
       WHERE (x ? 'seat_id') IS DISTINCT FROM (x ? 'seat_joined_at')
          OR CASE WHEN x ? 'seat_id'
                  THEN jsonb_typeof(x->'seat_id') IS DISTINCT FROM 'string'
                    OR jsonb_typeof(x->'seat_joined_at') IS DISTINCT FROM 'string'
                  ELSE false END
          OR CASE WHEN jsonb_typeof(x->'seat_id') = 'string'
                  THEN (x->>'seat_id') !~*
                    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  ELSE false END
          OR CASE WHEN jsonb_typeof(x->'seat_joined_at') = 'string'
                  THEN NOT pg_input_is_valid(
                    x->>'seat_joined_at', 'timestamp with time zone'
                  )
                  ELSE false END
    ) THEN
      RAISE EXCEPTION
        'atomic hand commit refused (invalid_stack_seat_generation)';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x WHERE x ? 'seat_id')
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x WHERE NOT (x ? 'seat_id')) THEN
      RAISE EXCEPTION
        'atomic hand commit refused (mixed_stack_seat_generation_protocol)';
    END IF;
    SELECT COALESCE(bool_and(x ? 'seat_id' AND x ? 'seat_joined_at'), false)
      INTO v_exact_seat_generation
      FROM jsonb_array_elements(p_stacks) x;

    IF EXISTS (
      SELECT 1
        FROM jsonb_array_elements(p_post_commit_obligations->'time_banks') x
       WHERE (x ? 'seat_id') IS DISTINCT FROM (x ? 'seat_joined_at')
          OR CASE WHEN x ? 'seat_id'
                  THEN jsonb_typeof(x->'seat_id') IS DISTINCT FROM 'string'
                    OR jsonb_typeof(x->'seat_joined_at') IS DISTINCT FROM 'string'
                  ELSE false END
          OR CASE WHEN jsonb_typeof(x->'seat_id') = 'string'
                  THEN (x->>'seat_id') !~*
                    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  ELSE false END
          OR CASE WHEN jsonb_typeof(x->'seat_joined_at') = 'string'
                  THEN NOT pg_input_is_valid(
                    x->>'seat_joined_at', 'timestamp with time zone'
                  )
                  ELSE false END
          OR (x ? 'seat_id') IS DISTINCT FROM v_exact_seat_generation
    ) THEN
      RAISE EXCEPTION
        'atomic hand commit refused (invalid_time_bank_seat_generation)';
    END IF;

    IF v_exact_seat_generation AND EXISTS (
      SELECT 1
        FROM jsonb_array_elements(p_post_commit_obligations->'time_banks') x
       WHERE NOT EXISTS (
         SELECT 1
           FROM jsonb_array_elements(p_stacks) s
          WHERE s->>'user_id' = x->>'user_id'
            AND s->>'seat_id' = x->>'seat_id'
            AND (s->>'seat_joined_at')::timestamptz =
                (x->>'seat_joined_at')::timestamptz
       )
    ) THEN
      RAISE EXCEPTION
        'atomic hand commit refused (time_bank_seat_generation_mismatch)';
    END IF;
  END IF;

  IF jsonb_typeof(p_hand_row->'_accepted_post_commit_facts') IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_hand_row->'pot_size') IS DISTINCT FROM 'number'
     OR jsonb_typeof(p_hand_row->'big_blind') IS DISTINCT FROM 'number'
     OR COALESCE(p_rake, 0) < 0
     OR COALESCE(p_bbj, 0) < 0
     OR jsonb_typeof(p_hand_row->'_accepted_post_commit_facts'->'contributions')
          IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_hand_row->'_accepted_post_commit_facts'->'returned_uncalled')
          IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_hand_row->'_accepted_post_commit_facts'->'insurance')
          IS DISTINCT FROM 'array'
     OR EXISTS (
       SELECT 1
         FROM jsonb_each(p_hand_row->'_accepted_post_commit_facts'->'contributions') e
        WHERE e.key !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR jsonb_typeof(e.value) IS DISTINCT FROM 'number'
           OR CASE WHEN jsonb_typeof(e.value) = 'number'
                   THEN (e.value::text)::numeric < 0 ELSE false END
     )
     OR EXISTS (
       SELECT 1
         FROM jsonb_each(p_hand_row->'_accepted_post_commit_facts'->'returned_uncalled') e
        WHERE e.key !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR jsonb_typeof(e.value) IS DISTINCT FROM 'number'
           OR CASE WHEN jsonb_typeof(e.value) = 'number'
                   THEN (e.value::text)::numeric < 0 ELSE false END
     ) THEN
    RAISE EXCEPTION
      'atomic hand commit refused (invalid_accepted_post_commit_facts)';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_post_commit_obligations->'time_banks') x
     WHERE (x->>'user_id') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR jsonb_typeof(x->'uses_remaining') IS DISTINCT FROM 'number'
        OR jsonb_typeof(x->'seconds_remaining') IS DISTINCT FROM 'number'
        OR (x->>'uses_remaining') !~ '^[0-9]+$'
        OR (x->>'seconds_remaining') !~ '^[0-9]+$'
        OR CASE WHEN (x->>'uses_remaining') ~ '^[0-9]+$'
                THEN (x->>'uses_remaining')::numeric > 2147483647 ELSE false END
        OR CASE WHEN (x->>'seconds_remaining') ~ '^[0-9]+$'
                THEN (x->>'seconds_remaining')::numeric > 2147483647 ELSE false END
  ) OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_post_commit_obligations->'promo_playthrough') x
     WHERE (x->>'club_id') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR (x->>'user_id') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR jsonb_typeof(x->'wagered') IS DISTINCT FROM 'number'
        OR CASE WHEN jsonb_typeof(x->'wagered') = 'number'
                THEN (x->>'wagered')::numeric <= 0 ELSE false END
  ) OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_post_commit_obligations->'insurance') x
     WHERE (x->>'club_id') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR (x->>'player_id') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR jsonb_typeof(x->'equity_percent') IS DISTINCT FROM 'number'
        OR jsonb_typeof(x->'premium') IS DISTINCT FROM 'number'
        OR jsonb_typeof(x->'insured_amount') IS DISTINCT FROM 'number'
        OR jsonb_typeof(x->'payout') IS DISTINCT FROM 'number'
        OR jsonb_typeof(x->'player_won') IS DISTINCT FROM 'boolean'
        OR COALESCE(x->>'kind', '') NOT IN ('insurance', 'ev_cashout')
        OR CASE WHEN jsonb_typeof(x->'equity_percent') = 'number'
                THEN (x->>'equity_percent')::numeric NOT BETWEEN 0 AND 100 ELSE false END
        OR CASE WHEN jsonb_typeof(x->'premium') = 'number'
                THEN (x->>'premium')::numeric < 0 ELSE false END
        OR CASE WHEN jsonb_typeof(x->'insured_amount') = 'number'
                THEN (x->>'insured_amount')::numeric < 0 ELSE false END
        OR CASE WHEN jsonb_typeof(x->'payout') = 'number'
                THEN (x->>'payout')::numeric < 0 ELSE false END
  ) THEN
    RAISE EXCEPTION
      'atomic hand commit refused (invalid_post_commit_item)';
  END IF;

  IF jsonb_typeof(p_post_commit_obligations->'rake') = 'object'
     AND (
       jsonb_typeof(p_post_commit_obligations->'rake'->'amount') IS DISTINCT FROM 'number'
       OR jsonb_typeof(p_post_commit_obligations->'rake'->'bbj') IS DISTINCT FROM 'number'
       OR jsonb_typeof(p_post_commit_obligations->'rake'->'pot') IS DISTINCT FROM 'number'
       OR jsonb_typeof(p_post_commit_obligations->'rake'->'num_players') IS DISTINCT FROM 'number'
       OR jsonb_typeof(p_post_commit_obligations->'rake'->'contributions') IS DISTINCT FROM 'object'
       OR jsonb_typeof(p_post_commit_obligations->'rake'->'returned_uncalled') IS DISTINCT FROM 'object'
       OR (p_post_commit_obligations->'rake'->>'num_players') !~ '^[0-9]+$'
       OR COALESCE((p_post_commit_obligations->'rake'->>'amount')::numeric, 0) <= 0
       OR COALESCE((p_post_commit_obligations->'rake'->>'bbj')::numeric, 0) < 0
       OR COALESCE((p_post_commit_obligations->'rake'->>'pot')::numeric, -1) < 0
       OR COALESCE((p_post_commit_obligations->'rake'->>'num_players')::numeric, 0) <= 0
       OR COALESCE((p_post_commit_obligations->'rake'->>'num_players')::numeric, 0)
            > 2147483647
       OR (p_post_commit_obligations->'rake'->>'club_id') !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(p_post_commit_obligations->'rake'->>'method', '')
            <> 'WEIGHTED_CONTRIBUTED'
     ) THEN
    RAISE EXCEPTION
      'atomic hand commit refused (invalid_post_commit_rake)';
  END IF;
  IF jsonb_typeof(p_post_commit_obligations->'bbj_contribution') = 'object'
     AND (
       jsonb_typeof(p_post_commit_obligations->'bbj_contribution'->'amount')
         IS DISTINCT FROM 'number'
       OR jsonb_typeof(p_post_commit_obligations->'bbj_contribution'->'big_blind')
         IS DISTINCT FROM 'number'
       OR COALESCE((p_post_commit_obligations->'bbj_contribution'->>'amount')::numeric, 0)
            <= 0
       OR COALESCE((p_post_commit_obligations->'bbj_contribution'->>'big_blind')::numeric, 0)
            <= 0
       OR (p_post_commit_obligations->'bbj_contribution'->>'club_id') !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     ) THEN
    RAISE EXCEPTION
      'atomic hand commit refused (invalid_post_commit_bbj)';
  END IF;

  IF jsonb_typeof(p_post_commit_obligations->'pending_addons') = 'object'
     AND (
       jsonb_typeof(p_post_commit_obligations->'pending_addons'->'enabled')
         IS DISTINCT FROM 'boolean'
       OR CASE
            WHEN jsonb_typeof(p_post_commit_obligations->'pending_addons'->'enabled') = 'boolean'
            THEN COALESCE(
              (p_post_commit_obligations->'pending_addons'->>'enabled')::boolean,
              false
            ) IS NOT TRUE
            ELSE false
          END
       OR jsonb_typeof(p_post_commit_obligations->'pending_addons'->'max_buy_in')
            IS DISTINCT FROM 'number'
       OR COALESCE(
            (p_post_commit_obligations->'pending_addons'->>'max_buy_in')::numeric,
            0
          ) <= 0
       OR p_post_commit_obligations->'pending_addons' ? 'ids'
     ) THEN
    RAISE EXCEPTION
      'atomic hand commit refused (invalid_post_commit_addons)';
  END IF;

  IF p_hand_number > 2147483647
     AND (
       jsonb_typeof(p_post_commit_obligations->'rake') = 'object'
       OR jsonb_typeof(p_post_commit_obligations->'bbj_contribution') = 'object'
       OR jsonb_array_length(p_post_commit_obligations->'insurance') > 0
     ) THEN
    RAISE EXCEPTION
      'atomic hand commit refused (post_commit_hand_number_out_of_range)';
  END IF;

  v_request_hash := encode(
    extensions.digest(convert_to(p_post_commit_obligations::text, 'UTF8'), 'sha256'),
    'hex'
  );

  /* The owner-only exact-generation core locks and proves the cash-table or
     tournament generation, then runs the unchanged accepted-hand core. Its
     lease/table locks remain held until this outer transaction commits. */
  v_result := public.fn_ca_commit_hand_settlement_exact_before_obligations(
    p_table_id,
    p_hand_number,
    p_stacks,
    p_rake,
    p_bbj,
    p_ref,
    p_inflow,
    p_hand_row,
    p_units,
    p_instance_id,
    p_lease_generation
  );

  IF COALESCE((v_result->>'success')::boolean, false) IS NOT TRUE
     OR COALESCE((v_result->>'atomic_hand_commit')::boolean, false) IS NOT TRUE THEN
    RETURN v_result;
  END IF;

  BEGIN
    v_hand_id := (v_result->>'history_id')::uuid;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION
      'atomic hand commit refused (invalid_post_commit_history_receipt)';
  END;
  IF v_hand_id IS NULL THEN
    RAISE EXCEPTION
      'atomic hand commit refused (missing_post_commit_history_receipt)';
  END IF;

  SELECT t.club_id, t.tournament_id
    INTO v_club_id, v_tournament_id
    FROM public.tables t
   WHERE t.id = p_table_id;
  IF NOT FOUND OR v_club_id IS NULL THEN
    RAISE EXCEPTION 'atomic hand commit refused (post_commit_table_scope_missing)';
  END IF;

  /* The envelope cannot contradict the accepted hand. Amounts bind to the
     settlement arguments; every per-player item binds to its authoritative
     stack roster; every money item binds to the table's club. */
  IF (COALESCE(p_rake, 0) > 0) IS DISTINCT FROM
       (jsonb_typeof(p_post_commit_obligations->'rake') = 'object')
     OR (
       COALESCE(p_rake, 0) > 0
       AND (p_post_commit_obligations->'rake'->>'amount')::numeric
             IS DISTINCT FROM p_rake
     )
     OR (
       COALESCE(p_rake, 0) > 0
       AND (p_post_commit_obligations->'rake'->>'bbj')::numeric
             IS DISTINCT FROM COALESCE(p_bbj, 0)
     )
     OR (
       COALESCE(p_rake, 0) > 0
       AND (p_post_commit_obligations->'rake'->>'pot')::numeric
             IS DISTINCT FROM (p_hand_row->>'pot_size')::numeric
     )
     OR (
       COALESCE(p_rake, 0) > 0
       AND (p_post_commit_obligations->'rake'->>'num_players')::integer
             IS DISTINCT FROM (
               SELECT count(*)::integer
                 FROM jsonb_object_keys(
                   p_hand_row->'_accepted_post_commit_facts'->'contributions'
                 )
             )
     )
     OR (
       COALESCE(p_rake, 0) > 0
       AND p_post_commit_obligations->'rake'->'contributions'
             IS DISTINCT FROM
             p_hand_row->'_accepted_post_commit_facts'->'contributions'
     )
     OR (
       COALESCE(p_rake, 0) > 0
       AND p_post_commit_obligations->'rake'->'returned_uncalled'
             IS DISTINCT FROM
             p_hand_row->'_accepted_post_commit_facts'->'returned_uncalled'
     )
     OR (COALESCE(p_bbj, 0) > 0) IS DISTINCT FROM
       (jsonb_typeof(p_post_commit_obligations->'bbj_contribution') = 'object')
     OR (
       COALESCE(p_bbj, 0) > 0
       AND (p_post_commit_obligations->'bbj_contribution'->>'amount')::numeric
             IS DISTINCT FROM p_bbj
     )
     OR (
       COALESCE(p_bbj, 0) > 0
       AND (p_post_commit_obligations->'bbj_contribution'->>'big_blind')::numeric
             IS DISTINCT FROM (p_hand_row->>'big_blind')::numeric
     ) THEN
    RAISE EXCEPTION
      'atomic hand commit refused (post_commit_fee_mismatch)';
  END IF;

  IF p_post_commit_obligations->'insurance' IS DISTINCT FROM
       p_hand_row->'_accepted_post_commit_facts'->'insurance' THEN
    RAISE EXCEPTION
      'atomic hand commit refused (post_commit_insurance_fact_mismatch)';
  END IF;

  IF (
       v_tournament_id IS NULL
       AND (
         jsonb_array_length(p_post_commit_obligations->'promo_playthrough')
           IS DISTINCT FROM (
             SELECT count(*)::integer
               FROM jsonb_each(
                 p_hand_row->'_accepted_post_commit_facts'->'contributions'
               ) e
              WHERE (e.value::text)::numeric > 0
           )
         OR EXISTS (
           SELECT 1
             FROM jsonb_array_elements(p_post_commit_obligations->'promo_playthrough') x
            WHERE (x->>'wagered')::numeric IS DISTINCT FROM
                  (
                    p_hand_row->'_accepted_post_commit_facts'->'contributions'->>
                    (x->>'user_id')
                  )::numeric
         )
       )
     ) OR (
       v_tournament_id IS NOT NULL
       AND jsonb_array_length(p_post_commit_obligations->'promo_playthrough') <> 0
     ) THEN
    RAISE EXCEPTION
      'atomic hand commit refused (post_commit_promo_fact_mismatch)';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_post_commit_obligations->'time_banks') x
     WHERE NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(COALESCE(p_stacks, '[]'::jsonb)) s
        WHERE s->>'user_id' = x->>'user_id'
     )
  ) OR EXISTS (
    SELECT 1
      FROM jsonb_object_keys(
        p_hand_row->'_accepted_post_commit_facts'->'contributions'
      ) uid
     WHERE NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(p_stacks) s
        WHERE s->>'user_id' = uid
     )
  ) OR EXISTS (
    SELECT 1
      FROM jsonb_object_keys(
        p_hand_row->'_accepted_post_commit_facts'->'returned_uncalled'
      ) uid
     WHERE NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(p_stacks) s
        WHERE s->>'user_id' = uid
     )
  ) OR EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_post_commit_obligations->'promo_playthrough') x
     WHERE x->>'club_id' IS DISTINCT FROM v_club_id::text
        OR NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(COALESCE(p_stacks, '[]'::jsonb)) s
           WHERE s->>'user_id' = x->>'user_id'
        )
  ) OR EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_post_commit_obligations->'insurance') x
     WHERE x->>'club_id' IS DISTINCT FROM v_club_id::text
        OR NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(COALESCE(p_stacks, '[]'::jsonb)) s
           WHERE s->>'user_id' = x->>'player_id'
        )
  ) THEN
    RAISE EXCEPTION
      'atomic hand commit refused (post_commit_player_or_club_mismatch)';
  END IF;

  /* Repeated recipients would turn one accepted-hand fact into two additive
     mutations. Time-bank rows are exhaustive because omitting one would make
     the accepted seat state depend on whichever process ran before this one. */
  IF jsonb_array_length(p_post_commit_obligations->'time_banks')
       IS DISTINCT FROM jsonb_array_length(p_stacks)
     OR (
       SELECT count(DISTINCT x->>'user_id')
         FROM jsonb_array_elements(p_post_commit_obligations->'time_banks') x
     ) IS DISTINCT FROM jsonb_array_length(p_stacks)
     OR (
       SELECT count(DISTINCT x->>'user_id')
         FROM jsonb_array_elements(p_post_commit_obligations->'promo_playthrough') x
     ) IS DISTINCT FROM jsonb_array_length(p_post_commit_obligations->'promo_playthrough')
     OR (
       /* The durable insurance writer is unique per table/hand/player. Two
          different kinds for one player would look like two obligations here
          but collapse to one receipt downstream. Refuse that ambiguity. */
       SELECT count(DISTINCT x->>'player_id')
         FROM jsonb_array_elements(p_post_commit_obligations->'insurance') x
     ) IS DISTINCT FROM jsonb_array_length(p_post_commit_obligations->'insurance') THEN
    RAISE EXCEPTION
      'atomic hand commit refused (post_commit_duplicate_or_missing_recipient)';
  END IF;

  IF jsonb_typeof(p_post_commit_obligations->'rake') = 'object'
     AND (
       EXISTS (
         SELECT 1
           FROM jsonb_object_keys(
             COALESCE(p_post_commit_obligations->'rake'->'contributions', '{}'::jsonb)
           ) uid
          WHERE NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(p_stacks) s
             WHERE s->>'user_id' = uid
          )
       )
       OR EXISTS (
         SELECT 1
           FROM jsonb_object_keys(
             COALESCE(p_post_commit_obligations->'rake'->'returned_uncalled', '{}'::jsonb)
           ) uid
          WHERE NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(p_stacks) s
             WHERE s->>'user_id' = uid
          )
       )
     ) THEN
    RAISE EXCEPTION
      'atomic hand commit refused (post_commit_rake_recipient_mismatch)';
  END IF;
  IF jsonb_typeof(p_post_commit_obligations->'rake') = 'object'
     AND p_post_commit_obligations->'rake'->>'club_id' IS DISTINCT FROM v_club_id::text THEN
    RAISE EXCEPTION 'atomic hand commit refused (post_commit_rake_club_mismatch)';
  END IF;
  IF jsonb_typeof(p_post_commit_obligations->'bbj_contribution') = 'object'
     AND p_post_commit_obligations->'bbj_contribution'->>'club_id'
           IS DISTINCT FROM v_club_id::text THEN
    RAISE EXCEPTION 'atomic hand commit refused (post_commit_bbj_club_mismatch)';
  END IF;
  IF jsonb_typeof(p_post_commit_obligations->'rake') = 'object'
     AND (
       COALESCE(p_post_commit_obligations->'rake'->>'tournament_id', '')
         IS DISTINCT FROM COALESCE(v_tournament_id::text, '')
       OR COALESCE(p_post_commit_obligations->'rake'->>'method', '')
            <> 'WEIGHTED_CONTRIBUTED'
     ) THEN
    RAISE EXCEPTION 'atomic hand commit refused (post_commit_rake_scope_mismatch)';
  END IF;
  IF (v_tournament_id IS NULL) IS DISTINCT FROM
       (jsonb_typeof(p_post_commit_obligations->'pending_addons') = 'object') THEN
    RAISE EXCEPTION 'atomic hand commit refused (post_commit_addon_scope_mismatch)';
  END IF;

  SELECT c.post_commit_request_hash, c.post_commit_payload_hash
    INTO v_existing_request_hash, v_existing_hash
    FROM public.hand_atomic_commits c
   WHERE c.table_id = p_table_id
     AND c.hand_number = p_hand_number
     AND c.hand_id = v_hand_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION
      'atomic hand commit refused (missing_post_commit_atomic_receipt)';
  END IF;
  IF v_existing_request_hash IS NOT NULL
     AND v_existing_request_hash IS DISTINCT FROM v_request_hash THEN
    RAISE EXCEPTION
      'atomic hand commit refused (post_commit_payload_conflict)';
  END IF;

  IF v_existing_request_hash IS NULL THEN
    /* A rolling 11-argument engine may already have committed this hand and
       run its legacy post-commit steps. Never attach a new additive envelope
       to that receipt. A response-loss replay from this 12-argument door
       always finds the request hash written by its first transaction. */
    IF COALESCE((v_result->>'replay')::boolean, false) IS TRUE THEN
      RAISE EXCEPTION
        'atomic hand commit refused (legacy_receipt_has_no_post_commit_envelope)';
    END IF;

    /* Copy the independently accepted facts into the immutable stored envelope.
       The caller is forbidden from supplying this key itself. Besides the core
       hand hash, the durable processor/audit row can therefore show exactly
       which first-narrative facts every derived obligation was checked against. */
    v_payload := jsonb_set(
      p_post_commit_obligations,
      '{accepted_hand_facts}',
      p_hand_row->'_accepted_post_commit_facts',
      true
    );
    IF jsonb_typeof(v_payload->'pending_addons') = 'object' THEN
      /* Own the exact eligible rows through commit. A legacy/manual resolver
         cannot consume one after it was frozen but before the obligation
         transaction gets its causal wake. */
      PERFORM 1
        FROM public.table_pending_addons a
       WHERE a.table_id = p_table_id
         AND a.resolved_at IS NULL
         AND a.created_at <= transaction_timestamp()
       ORDER BY a.created_at, a.id
       FOR UPDATE;
      v_payload := jsonb_set(
        v_payload,
        '{pending_addons,ids}',
        COALESCE((
          SELECT jsonb_agg(a.id ORDER BY a.created_at, a.id)
            FROM public.table_pending_addons a
           WHERE a.table_id = p_table_id
             AND a.resolved_at IS NULL
             AND a.created_at <= transaction_timestamp()
        ), '[]'::jsonb),
        true
      );
    END IF;
    v_hash := encode(
      extensions.digest(convert_to(v_payload::text, 'UTF8'), 'sha256'),
      'hex'
    );

    /* Time-bank state belongs to the accepted-hand boundary itself. Apply it
       while the exact lease/table/seat locks inherited from the owner-only
       exact-generation core are still held, never later from a stale envelope. */
    v_expected := jsonb_array_length(v_payload->'time_banks');
    v_updated := 0;
    FOR v_item IN
      SELECT value FROM jsonb_array_elements(v_payload->'time_banks')
       ORDER BY value->>'user_id'
    LOOP
      IF (v_item->>'user_id') !~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         OR (v_item->>'uses_remaining') !~ '^[0-9]+$'
         OR (v_item->>'seconds_remaining') !~ '^[0-9]+$' THEN
        RAISE EXCEPTION
          'atomic hand commit refused (invalid_time_bank_obligation)';
      END IF;
      UPDATE public.table_seats s
         SET time_bank_uses_remaining = (v_item->>'uses_remaining')::integer,
             time_bank_remaining = (v_item->>'seconds_remaining')::integer
       WHERE s.table_id = p_table_id
         AND s.user_id = (v_item->>'user_id')::uuid
         AND (
           (v_exact_seat_generation
             AND s.id = (v_item->>'seat_id')::uuid
             AND s.joined_at = (v_item->>'seat_joined_at')::timestamptz)
           OR (NOT v_exact_seat_generation AND (
           s.left_at IS NULL
           OR (
             v_tournament_id IS NOT NULL
             AND s.stack = 0
             AND lower(COALESCE(s.status, '')) = 'left'
             AND s.left_at =
                   (v_result->>'tournament_zero_stack_vacated_at')::timestamptz
             AND EXISTS (
               SELECT 1
                 FROM jsonb_array_elements(
                        v_result->'tournament_zero_stack_seat_generations'
                      ) generation(value)
                WHERE (generation.value->>'seat_id')::uuid = s.id
                  AND (generation.value->>'user_id')::uuid = s.user_id
                  AND (generation.value->>'seat_number')::integer = s.seat_number
                  AND (generation.value->>'joined_at')::timestamptz = s.joined_at
             )
           )
         ))
         );
      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      /* Preserve the stack writer's lawful-noop rule. If a redundant-update
         suppressor is installed, ROW_COUNT may be zero even though the exact
         row already stores the requested state. Prove that exact state before
         counting it; a missing or replaced generation still refuses whole. */
      IF v_row_count = 0 AND EXISTS (
        SELECT 1
          FROM public.table_seats s
         WHERE s.table_id = p_table_id
           AND s.user_id = (v_item->>'user_id')::uuid
           AND s.time_bank_uses_remaining = (v_item->>'uses_remaining')::integer
           AND s.time_bank_remaining = (v_item->>'seconds_remaining')::integer
           AND (
             (v_exact_seat_generation
               AND s.id = (v_item->>'seat_id')::uuid
               AND s.joined_at = (v_item->>'seat_joined_at')::timestamptz)
             OR (NOT v_exact_seat_generation AND (
           s.left_at IS NULL
           OR (
             v_tournament_id IS NOT NULL
             AND s.stack = 0
             AND lower(COALESCE(s.status, '')) = 'left'
             AND s.left_at =
                   (v_result->>'tournament_zero_stack_vacated_at')::timestamptz
             AND EXISTS (
               SELECT 1
                 FROM jsonb_array_elements(
                        v_result->'tournament_zero_stack_seat_generations'
                      ) generation(value)
                WHERE (generation.value->>'seat_id')::uuid = s.id
                  AND (generation.value->>'user_id')::uuid = s.user_id
                  AND (generation.value->>'seat_number')::integer = s.seat_number
                  AND (generation.value->>'joined_at')::timestamptz = s.joined_at
             )
           )
         ))
           )
      ) THEN
        v_row_count := 1;
      END IF;
      v_updated := v_updated + v_row_count;
    END LOOP;
    IF v_updated IS DISTINCT FROM v_expected THEN
      RAISE EXCEPTION
        'atomic hand commit refused (time_bank_seat_mismatch)';
    END IF;

    UPDATE public.hand_atomic_commits c
       SET post_commit_payload = v_payload,
           post_commit_request_hash = v_request_hash,
           post_commit_payload_hash = v_hash
     WHERE c.table_id = p_table_id
       AND c.hand_number = p_hand_number
       AND c.hand_id = v_hand_id
       AND c.post_commit_request_hash IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION
        'atomic hand commit refused (post_commit_receipt_raced)';
    END IF;
  ELSE
    v_hash := v_existing_hash;
    IF v_hash IS NULL THEN
      RAISE EXCEPTION
        'atomic hand commit refused (post_commit_payload_hash_missing)';
    END IF;
  END IF;

  RETURN v_result || jsonb_build_object(
    'post_commit_obligations', true,
    'post_commit_payload_hash', v_hash
  );
END;
$_$;


ALTER FUNCTION public.fn_ca_commit_hand_settlement(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric, p_hand_row jsonb, p_units jsonb, p_instance_id text, p_lease_generation uuid, p_post_commit_obligations jsonb) OWNER TO postgres;

--
-- Name: fn_ca_commit_hand_settlement_before_lease_generation(uuid, bigint, jsonb, numeric, numeric, text, numeric, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commit_hand_settlement_before_lease_generation(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric, p_hand_row jsonb, p_units jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_tournament_id uuid;
  v_stack_result jsonb;
  v_hand_id uuid;
  v_existing public.hand_history%ROWTYPE;
  v_prior public.hand_atomic_commits%ROWTYPE;
  v_commit_hash text;
  v_normalized_stacks jsonb;
  v_normalized_units jsonb;
  v_stack jsonb;
  v_uid uuid;
  v_written numeric;
  v_before numeric;
  v_seat record;
  v_zero_generation jsonb;
  v_zero_generation_count integer;
  v_prompt_until timestamptz;
  v_rebuy_cap integer;
  v_rebuy_offer_available boolean;
  v_n integer;
  v_distinct integer;
  v_changed integer;
  v_candidate_id uuid;
BEGIN
  -- External authority is the EXECUTE ACL on the lease-fenced public wrapper.
  -- This nested SECURITY DEFINER core is owner-only and must remain callable
  -- when its preserved production owner is neither postgres nor service_role.
  IF p_table_id IS NULL OR p_hand_number IS NULL OR p_hand_number<1000000
     OR jsonb_typeof(p_stacks)<>'array' OR jsonb_array_length(p_stacks)=0
     OR jsonb_typeof(p_hand_row)<>'object'
     OR jsonb_typeof(coalesce(p_units,'[]'::jsonb))<>'array'
     OR coalesce(p_hand_row->>'table_id','')<>p_table_id::text
     OR coalesce(p_hand_row->>'hand_number','')<>p_hand_number::text THEN
    RETURN jsonb_build_object('success',false,'reason','invalid_atomic_hand_payload');
  END IF;

  SELECT count(*), count(DISTINCT x->>'user_id')
    INTO v_n, v_distinct
    FROM jsonb_array_elements(p_stacks) x
   WHERE jsonb_typeof(x)='object'
     AND coalesce(x->>'user_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND jsonb_typeof(x->'stack')='number'
     AND jsonb_typeof(x->'stack_before')='number'
     AND (x->>'stack')::numeric>=0
     AND (x->>'stack_before')::numeric>=0;
  IF v_n<>jsonb_array_length(p_stacks) OR v_distinct<>v_n THEN
    RETURN jsonb_build_object('success',false,'reason','invalid_or_duplicate_stack_rows');
  END IF;

  SELECT jsonb_agg(x ORDER BY x->>'user_id') INTO v_normalized_stacks
    FROM jsonb_array_elements(p_stacks) x;
  SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]'::jsonb) INTO v_normalized_units
    FROM jsonb_array_elements(coalesce(p_units,'[]'::jsonb)) x;
  v_commit_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'table_id',p_table_id,'hand_number',p_hand_number,
    'stacks',v_normalized_stacks,'rake',p_rake,'bbj',p_bbj,
    'ref',p_ref,'inflow',p_inflow,'hand_row',p_hand_row,
    'units',v_normalized_units)::text,'UTF8'),'sha256'),'hex');

  PERFORM pg_advisory_xact_lock(
    hashtextextended('atomic-table:'||p_table_id::text,0));
  PERFORM pg_advisory_xact_lock(
    hashtextextended('atomic-hand:'||p_hand_number::text,0));

  SELECT * INTO v_prior
    FROM public.hand_atomic_commits c
   WHERE c.hand_number=p_hand_number
   FOR UPDATE;
  IF FOUND THEN
    IF v_prior.table_id IS DISTINCT FROM p_table_id
       OR v_prior.payload_hash IS DISTINCT FROM v_commit_hash THEN
      RETURN jsonb_build_object(
        'success',false,'reason','atomic_hand_payload_conflict',
        'hand_number',p_hand_number,'existing_table_id',v_prior.table_id);
    END IF;
    RETURN v_prior.stack_result || jsonb_build_object(
      'success',true,'atomic_hand_commit',true,'replay',true,
      'history_id',v_prior.hand_id,'commit_hash',v_prior.payload_hash);
  END IF;

  SELECT t.tournament_id INTO v_tournament_id
    FROM public.tables t WHERE t.id=p_table_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success',false,'reason','table_not_found');
  END IF;

  IF (p_hand_row->>'tournament_id') IS DISTINCT FROM v_tournament_id::text THEN
    RETURN jsonb_build_object(
      'success',false,'reason','hand_tournament_mismatch',
      'table_tournament_id',v_tournament_id,
      'row_tournament_id',p_hand_row->>'tournament_id');
  END IF;

  BEGIN
    IF v_tournament_id IS NOT NULL THEN
      PERFORM 1 FROM public.tournaments t WHERE t.id=v_tournament_id FOR SHARE;
      PERFORM 1
        FROM public.tournament_players tp
       WHERE tp.tournament_id=v_tournament_id
         AND tp.user_id IN (
           SELECT (x->>'user_id')::uuid FROM jsonb_array_elements(p_stacks) x)
       ORDER BY tp.user_id
       FOR UPDATE;
    END IF;

    v_stack_result := public.fn_ca_settle_hand_stacks_absolute(
      p_table_id,p_hand_number,v_normalized_stacks,p_rake,p_bbj,p_ref,p_inflow);
    IF coalesce((v_stack_result->>'success')::boolean,false) IS NOT TRUE THEN
      RETURN v_stack_result || jsonb_build_object('atomic_hand_commit',false);
    END IF;
    IF coalesce((v_stack_result->>'replay')::boolean,false) IS TRUE THEN
      RAISE EXCEPTION 'legacy stack settlement exists for hand % without an atomic receipt',
        p_hand_number USING ERRCODE='integrity_constraint_violation';
    END IF;

    SELECT * INTO v_existing
      FROM public.hand_history h WHERE h.hand_number=p_hand_number;
    IF FOUND THEN
      RAISE EXCEPTION 'hand % already exists without an atomic commit receipt',p_hand_number
        USING ERRCODE='integrity_constraint_violation';
    ELSE
      PERFORM set_config('app.atomic_hand_commit','on',true);
      v_hand_id := public.fn_ca_insert_hand_with_awards(p_hand_row,p_units);
    END IF;

    IF v_tournament_id IS NOT NULL THEN
      IF jsonb_typeof(
           v_stack_result->'tournament_zero_stack_seat_generations')
             IS DISTINCT FROM 'array'
         OR jsonb_array_length(
              v_stack_result->'tournament_zero_stack_seat_generations')
              IS DISTINCT FROM
              COALESCE(
                (v_stack_result->>'tournament_zero_stack_seat_count')::integer,-1)
         OR (
              COALESCE(
                (v_stack_result->>'tournament_zero_stack_seat_count')::integer,-1) > 0
              AND (v_stack_result->>'tournament_zero_stack_vacated_at') IS NULL
            ) THEN
        RAISE EXCEPTION
          'accepted tournament hand omitted exact zero-seat generation evidence';
      END IF;

      FOR v_stack IN SELECT value FROM jsonb_array_elements(p_stacks)
      LOOP
        v_uid := (v_stack->>'user_id')::uuid;
        v_before := round((v_stack->>'stack_before')::numeric,2);
        v_written := round((v_stack_result->'written'->>v_uid::text)::numeric,2);
        IF v_written IS NULL THEN
          RAISE EXCEPTION 'accepted tournament hand omitted written stack for %',v_uid;
        END IF;
        IF v_written<>trunc(v_written) THEN
          RAISE EXCEPTION 'accepted tournament hand produced fractional stack % for %',v_written,v_uid;
        END IF;

        IF v_written=0 THEN
          SELECT count(*) INTO v_zero_generation_count
            FROM jsonb_array_elements(
                   v_stack_result->'tournament_zero_stack_seat_generations') g(value)
           WHERE g.value->>'user_id'=v_uid::text;
          IF v_zero_generation_count<>1 THEN
            RAISE EXCEPTION
              'accepted tournament hand has % zero-seat generations for %',
              v_zero_generation_count,v_uid USING ERRCODE='P0404';
          END IF;
          SELECT g.value INTO v_zero_generation
            FROM jsonb_array_elements(
                   v_stack_result->'tournament_zero_stack_seat_generations') g(value)
           WHERE g.value->>'user_id'=v_uid::text;
          SELECT s.id,s.joined_at,s.seat_number
            INTO v_seat
            FROM public.table_seats s
           WHERE s.id=(v_zero_generation->>'seat_id')::uuid
             AND s.table_id=p_table_id
             AND s.user_id=v_uid
             AND s.seat_number=(v_zero_generation->>'seat_number')::integer
             AND s.joined_at=(v_zero_generation->>'joined_at')::timestamptz
             AND s.stack=0
             AND s.left_at=
                   (v_stack_result->>'tournament_zero_stack_vacated_at')::timestamptz
             AND lower(COALESCE(s.status,''))='left'
           FOR UPDATE;
          IF NOT FOUND THEN
            RAISE EXCEPTION
              'accepted tournament hand lost exact closed seat generation for %',v_uid
              USING ERRCODE='P0404';
          END IF;
        ELSE
          SELECT s.id,s.joined_at,s.seat_number
            INTO v_seat
            FROM public.table_seats s
           WHERE s.table_id=p_table_id AND s.user_id=v_uid AND s.left_at IS NULL
           FOR UPDATE;
          IF NOT FOUND THEN
            RAISE EXCEPTION
              'accepted tournament hand lost active seat for % before generation capture',v_uid;
          END IF;
        END IF;

        UPDATE public.tournament_players tp
           SET chips=greatest(v_written,0)::integer,
               table_id=p_table_id,
               seat_number=v_seat.seat_number
         WHERE tp.tournament_id=v_tournament_id AND tp.user_id=v_uid
           AND tp.status='playing';
        GET DIAGNOSTICS v_changed=ROW_COUNT;
        IF v_changed<>1 AND NOT EXISTS (
          SELECT 1 FROM public.tournament_players tp
           WHERE tp.tournament_id=v_tournament_id AND tp.user_id=v_uid
             AND tp.status='playing'
             AND tp.chips=greatest(v_written,0)::integer
             AND tp.table_id=p_table_id
             AND tp.seat_number=v_seat.seat_number) THEN
          RAISE EXCEPTION
            'accepted tournament hand could not mirror playing roster row for %',v_uid;
        END IF;

        IF v_before>0 AND v_written=0 THEN
          SELECT
            (coalesce(t.is_rebuy,false)
               AND (t.max_rebuys IS NULL OR coalesce(tp.rebuys,0)<t.max_rebuys))
            OR
            (coalesce(t.is_reentry,false)
               AND (t.max_reentries IS NULL OR coalesce(tp.rebuys,0)<t.max_reentries)),
            coalesce(nullif(t.rebuy_levels,0),nullif(t.late_reg_levels,0),0)
              + CASE WHEN coalesce(t.add_on_available,false)
                     THEN coalesce(nullif(t.addon_levels,0),1) ELSE 0 END
            INTO v_rebuy_offer_available,v_rebuy_cap
            FROM public.tournaments t
            JOIN public.tournament_players tp
              ON tp.tournament_id=t.id AND tp.user_id=v_uid
           WHERE t.id=v_tournament_id;
          SELECT CASE
            WHEN v_rebuy_offer_available
             AND v_rebuy_cap>0
             AND (SELECT coalesce(current_level,0)
                    FROM public.tournaments WHERE id=v_tournament_id)<v_rebuy_cap
             AND NOT (SELECT coalesce(prize_pool_finalized,false)
                        FROM public.tournaments WHERE id=v_tournament_id)
            THEN clock_timestamp()+interval '30 seconds'
            ELSE NULL END
            INTO v_prompt_until;

          v_candidate_id := NULL;
          INSERT INTO public.tournament_knockout_candidates(
            tournament_id,eliminated_user_id,table_id,seat_id,seat_joined_at,
            hand_id,hand_number,stack_before,stack_after,rebuy_prompt_until)
          VALUES (
            v_tournament_id,v_uid,p_table_id,v_seat.id,v_seat.joined_at,
            v_hand_id,p_hand_number,v_before,0,v_prompt_until)
          -- More than one uniqueness rule can describe the same physical bust.
          -- In particular, a rebuy can bust twice from the same chair generation.
          -- Let the identity checks below distinguish an accepted replay from a
          -- genuinely conflicting candidate instead of aborting the whole hand on
          -- whichever relevant unique constraint PostgreSQL encounters first.
          ON CONFLICT DO NOTHING
          RETURNING id INTO v_candidate_id;
          IF v_candidate_id IS NULL AND NOT EXISTS (
            SELECT 1 FROM public.tournament_knockout_candidates c
             WHERE c.tournament_id=v_tournament_id
               AND c.hand_number=p_hand_number
               AND c.eliminated_user_id=v_uid
               AND c.table_id=p_table_id
               AND c.seat_id=v_seat.id
               AND c.seat_joined_at=v_seat.joined_at
               AND c.hand_id=v_hand_id
               AND c.stack_before=v_before
               AND c.stack_after=0)
             AND NOT EXISTS (
              SELECT 1 FROM public.tournament_knockout_candidates c2
               WHERE c2.tournament_id=v_tournament_id
                 AND c2.eliminated_user_id=v_uid
                 AND c2.seat_joined_at=v_seat.joined_at) THEN
            RAISE EXCEPTION
              'knockout candidate identity conflict for tournament %, hand %, user %',
              v_tournament_id,p_hand_number,v_uid;
          END IF;

          UPDATE public.tournament_players tp
             SET rebuy_prompt_until=v_prompt_until
           WHERE tp.tournament_id=v_tournament_id AND tp.user_id=v_uid
             AND tp.status='playing';
        END IF;
      END LOOP;
    END IF;

    INSERT INTO public.hand_projection_outbox(hand_id,table_id,hand_number)
    VALUES (v_hand_id,p_table_id,p_hand_number);

    INSERT INTO public.hand_atomic_commits(
      table_id,hand_number,hand_id,payload_hash,stack_result)
    VALUES (p_table_id,p_hand_number,v_hand_id,v_commit_hash,v_stack_result);

    RETURN v_stack_result || jsonb_build_object(
      'success',true,
      'atomic_hand_commit',true,
      'history_id',v_hand_id,
      'tournament_id',v_tournament_id,
      'commit_hash',v_commit_hash);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success',false,'atomic_hand_commit',false,'reason','atomic_hand_rolled_back',
      'error',SQLERRM,'sqlstate',SQLSTATE,'table_id',p_table_id,
      'hand_number',p_hand_number,'commit_hash',v_commit_hash);
  END;
END;
$_$;


ALTER FUNCTION public.fn_ca_commit_hand_settlement_before_lease_generation(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric, p_hand_row jsonb, p_units jsonb) OWNER TO postgres;

--
-- Name: fn_ca_commit_hand_settlement_exact_before_obligations(uuid, bigint, jsonb, numeric, numeric, text, numeric, jsonb, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commit_hand_settlement_exact_before_obligations(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric, p_hand_row jsonb, p_units jsonb, p_instance_id text, p_lease_generation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_locked_tournament_id uuid;
  v_holder text;
  v_generation uuid;
  v_protocol_version integer;
  v_heartbeat_at timestamptz;
  v_lease_found boolean;
  v_scope text;
BEGIN
  IF length(btrim(COALESCE(p_instance_id, ''))) = 0
     OR p_lease_generation IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'atomic_hand_commit', false,
      'reason', 'invalid_hand_lease_authority'
    );
  END IF;

  /* This read is deliberately unlocked and is used only to choose one lease
     relation.  No mutation follows until the chosen lease is locked and the
     tables row is itself locked/re-read below. */
  SELECT t.tournament_id INTO v_tournament_id
    FROM public.tables t
   WHERE t.id = p_table_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'table_not_found');
  END IF;

  IF v_tournament_id IS NULL THEN
    v_scope := 'table';
    SELECT l.instance_id, l.lease_generation, l.protocol_version, l.heartbeat_at
      INTO v_holder, v_generation, v_protocol_version, v_heartbeat_at
      FROM public.engine_table_leases l
     WHERE l.table_id = p_table_id
     FOR SHARE;
    v_lease_found := FOUND;
  ELSE
    v_scope := 'tournament';
    SELECT l.instance_id, l.lease_generation, l.protocol_version, l.heartbeat_at
      INTO v_holder, v_generation, v_protocol_version, v_heartbeat_at
      FROM public.engine_tournament_leases l
     WHERE l.tournament_id = v_tournament_id
     FOR SHARE;
    v_lease_found := FOUND;
  END IF;

  IF NOT v_lease_found
     OR v_protocol_version IS DISTINCT FROM 2
     OR v_holder IS DISTINCT FROM p_instance_id
     OR v_generation IS DISTINCT FROM p_lease_generation THEN
    RETURN jsonb_build_object(
      'success', false,
      'atomic_hand_commit', false,
      'reason', 'hand_lease_lost',
      'lease_scope', v_scope,
      'lease_generation', v_generation
    );
  END IF;

  IF v_heartbeat_at < clock_timestamp() - make_interval(
       secs => public.fn_engine_lease_stale_seconds()
     ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'atomic_hand_commit', false,
      'reason', 'hand_lease_stale',
      'lease_scope', v_scope,
      'lease_generation', v_generation
    );
  END IF;

  /* Match the unchanged core and manager lock order before taking the mutable
     table row.  FOR SHARE excludes tournament lifecycle updates without
     serializing hands at distinct tables in the same event. */
  IF v_tournament_id IS NOT NULL THEN
    PERFORM 1
      FROM public.tournaments t
     WHERE t.id = v_tournament_id
     FOR SHARE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'reason', 'tournament_not_found');
    END IF;
  END IF;

  /* Cash uses lease -> table. Tournament settlement uses
     lease -> tournament parent -> table. Holding the exact lease now prevents
     takeover until the unchanged core has committed or rolled back. */
  SELECT t.tournament_id INTO v_locked_tournament_id
    FROM public.tables t
   WHERE t.id = p_table_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'table_not_found');
  END IF;
  IF v_locked_tournament_id IS DISTINCT FROM v_tournament_id THEN
    RETURN jsonb_build_object(
      'success', false,
      'atomic_hand_commit', false,
      'reason', 'hand_lease_scope_changed'
    );
  END IF;

  RETURN public.fn_ca_commit_hand_settlement_before_lease_generation(
    p_table_id,
    p_hand_number,
    p_stacks,
    p_rake,
    p_bbj,
    p_ref,
    p_inflow,
    p_hand_row,
    p_units
  );
END;
$$;


ALTER FUNCTION public.fn_ca_commit_hand_settlement_exact_before_obligations(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric, p_hand_row jsonb, p_units jsonb, p_instance_id text, p_lease_generation uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_commit_hand_settlement_exact_before_obligations(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric, p_hand_row jsonb, p_units jsonb, p_instance_id text, p_lease_generation uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_commit_hand_settlement_exact_before_obligations(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric, p_hand_row jsonb, p_units jsonb, p_instance_id text, p_lease_generation uuid) IS 'Commits one hand only while holding the exact protocol-2 table generation for cash or tournament generation for a tournament table, then delegates to the unchanged atomic core.';


--
-- Name: fn_ca_completed_without_a_champion(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_completed_without_a_champion() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT count(*)::int
    FROM public.tournaments t
   WHERE t.status = 'COMPLETED'
     AND EXISTS (SELECT 1 FROM public.tournament_players tp
                  WHERE tp.tournament_id = t.id)
     AND NOT EXISTS (SELECT 1 FROM public.tournament_players tp
                      WHERE tp.tournament_id = t.id AND tp.status = 'winner');
$$;


ALTER FUNCTION public.fn_ca_completed_without_a_champion() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_completed_without_a_champion(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_completed_without_a_champion() IS 'Completed tournaments that have players but nobody marked winner. Every one is a settlement that cannot complete: bounty pools, prizes and stats all read status=winner. 52 on 2026-09-01, all from the 2026-08-21..27 window, all with the champion still in status=playing.';


--
-- Name: fn_ca_conservation_sweep(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_conservation_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  c record; v_n bigint; v_rows jsonb; v_verdict jsonb;
  v_found int := 0; v_failed int := 0; v_ran int := 0;
BEGIN
  FOR c IN
    SELECT * FROM (VALUES
      ('fn_chip_integrity_report',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_chip_integrity_report() where severity <> ''ok'' limit 20) t',
       'warning'),
      ('fn_settlement_conservation_check',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_settlement_conservation_check() limit 20) t',
       'critical'),
      ('fn_union_chip_integrity_check',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_union_chip_integrity_check() limit 20) t',
       'critical'),
      ('fn_union_money_path_check',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_union_money_path_check() limit 20) t',
       'warning'),
      ('fn_club_arena_global_wallet_check',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_club_arena_global_wallet_check() limit 20) t',
       'warning'),
      ('fn_tournament_chip_conservation_check',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_tournament_chip_conservation_check(0.01) limit 20) t',
       'warning'),
      ('fn_satellite_conservation_audit',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_satellite_conservation_audit(24) limit 20) t',
       'warning'),
      ('fn_tournament_prize_disbursement_audit',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_tournament_prize_disbursement_audit(24) limit 20) t',
       'warning'),
      ('fn_union_credit_risk_check',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_union_credit_risk_check() limit 20) t',
       'warning'),
      ('fn_union_governance_check',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_union_governance_check() limit 20) t',
       'warning'),
      ('fn_union_house_club_stamp_check',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_union_house_club_stamp_check() limit 20) t',
       'warning'),
      ('fn_union_law_integrity_breaches',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_union_law_integrity_breaches() limit 20) t',
       'critical'),
      ('fn_union_overload_check',
       'select count(*), jsonb_agg(to_jsonb(t)) from (select * from public.fn_union_overload_check() limit 20) t',
       'warning')
    ) v(check_name, q, sev)
  LOOP
    BEGIN
      v_ran := v_ran + 1;
      EXECUTE c.q INTO v_n, v_rows;
      IF COALESCE(v_n,0) > 0 THEN
        v_found := v_found + 1;
        PERFORM public.fn_ca_raise_drift_incident(
          'fn_ca_conservation_sweep:' || c.check_name, 'ledger_imbalance', c.sev,
          'sweep:' || c.check_name || ':' || CURRENT_DATE::text,
          0, NULL, NULL, 'ledger', c.check_name,
          NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
          c.check_name || ' returned ' || v_n || ' finding(s) - an invariant does not hold',
          false, jsonb_build_object('rows', v_rows, 'row_count', v_n));
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_conservation_sweep:' || c.check_name, 'unknown', 'warning',
        'sweepfail:' || c.check_name || ':' || CURRENT_DATE::text,
        0, NULL, NULL, 'ledger', c.check_name,
        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
        'check could not run: ' || SQLERRM
          || ' - a check that errors is as silent as one that never runs',
        false, jsonb_build_object('sqlstate', SQLSTATE));
    END;
  END LOOP;

  FOR c IN
    SELECT * FROM (VALUES
      ('fn_bbj_conservation_check',   'select public.fn_bbj_conservation_check()',   'healthy'),
      ('fn_bbj_promo_bank_check',     'select public.fn_bbj_promo_bank_check()',     'reconciles'),
      ('fn_settler_lag_check',        'select public.fn_settler_lag_check()',        'healthy'),
      ('fn_tournament_guarantee_check','select public.fn_tournament_guarantee_check(24)','__guarantee')
    ) v(check_name, q, health_key)
  LOOP
    BEGIN
      v_ran := v_ran + 1;
      EXECUTE c.q INTO v_verdict;

      IF (c.health_key = '__guarantee'
            AND (COALESCE((v_verdict->>'short_of_guarantee')::numeric,0) > 0
              OR COALESCE((v_verdict->>'paid_nothing')::numeric,0) > 0))
         OR (c.health_key <> '__guarantee'
            AND COALESCE((v_verdict->>c.health_key)::boolean, true) IS NOT TRUE)
      THEN
        v_found := v_found + 1;
        PERFORM public.fn_ca_raise_drift_incident(
          'fn_ca_conservation_sweep:' || c.check_name, 'ledger_imbalance', 'warning',
          'sweep:' || c.check_name || ':' || CURRENT_DATE::text,
          COALESCE((v_verdict->>'drift_from_baseline')::numeric,
                   (v_verdict->>'over_swept')::numeric,
                   (v_verdict->>'chips_short')::numeric, 0),
          NULL, NULL, 'ledger', c.check_name,
          NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
          c.check_name || ' reports a conservation failure',
          false, v_verdict);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_conservation_sweep:' || c.check_name, 'unknown', 'warning',
        'sweepfail:' || c.check_name || ':' || CURRENT_DATE::text,
        0, NULL, NULL, 'ledger', c.check_name,
        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
        'check could not run: ' || SQLERRM,
        false, jsonb_build_object('sqlstate', SQLSTATE));
    END;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'checks_run', v_ran,
                            'with_findings', v_found, 'errored', v_failed);
END;
$$;


ALTER FUNCTION public.fn_ca_conservation_sweep() OWNER TO postgres;

--
-- Name: fn_ca_consume_purchase_lots(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_consume_purchase_lots(p_user_id uuid, p_amount bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_left bigint := COALESCE(p_amount, 0); v_lot record; v_take bigint; v_consumed bigint := 0;
BEGIN
  IF v_left <= 0 THEN RETURN 0; END IF;
  BEGIN
    FOR v_lot IN
      SELECT l.id, (l.issued - l.consumed - l.refunded) AS avail
        FROM public.diamond_purchase_lots l
       WHERE l.user_id = p_user_id AND l.frozen_at IS NULL
         AND (l.issued - l.consumed - l.refunded) > 0
       ORDER BY l.created_at, l.id
       FOR UPDATE
    LOOP
      EXIT WHEN v_left <= 0;
      v_take := LEAST(v_lot.avail, v_left);
      UPDATE public.diamond_purchase_lots SET consumed = consumed + v_take WHERE id = v_lot.id;
      v_left := v_left - v_take;
      v_consumed := v_consumed + v_take;
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      PERFORM public.fn_ca_diamond_incident('DR9:purchase_lot_write_failed', 'critical', p_user_id, p_amount,
        'fn_ca_consume_purchase_lots', jsonb_build_object('sqlstate', SQLSTATE, 'message', SQLERRM));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END;
  RETURN v_consumed;
END $$;


ALTER FUNCTION public.fn_ca_consume_purchase_lots(p_user_id uuid, p_amount bigint) OWNER TO postgres;

--
-- Name: fn_ca_cron_failure_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cron_failure_watch() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; n integer := 0; v_is_guard boolean;
BEGIN
  FOR r IN
    SELECT j.jobname,
           count(*) FILTER (WHERE d.status = 'failed')    AS fails,
           count(*) FILTER (WHERE d.status = 'succeeded') AS successes,
           max(d.start_time) FILTER (WHERE d.status = 'succeeded') AS last_success,
           max(left(d.return_message, 200)) FILTER (WHERE d.status = 'failed') AS sample_error
    FROM cron.job j
    JOIN cron.job_run_details d ON d.jobid = j.jobid
    WHERE j.active AND d.start_time > now() - interval '2 hours'
    GROUP BY j.jobname
    HAVING count(*) FILTER (WHERE d.status = 'failed') >= 5
       AND count(*) FILTER (WHERE d.status = 'succeeded') = 0
    LIMIT 20
  LOOP
    SELECT EXISTS (SELECT 1 FROM public.ca_guard_inventory g
                    WHERE g.kind = 'cron' AND g.object_a = r.jobname AND g.active)
      INTO v_is_guard;
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_cron_failure_watch', 'unknown',
      CASE WHEN v_is_guard THEN 'critical' ELSE 'warning' END,
      'cron-failing:' || r.jobname || ':' || CURRENT_DATE::text,
      0, NULL, NULL, 'reporting', 'cron.job_run_details',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'scheduled job ' || r.jobname || ' has failed ' || r.fails
        || ' times in 2h with zero successes. Last error: ' || COALESCE(r.sample_error, '?'),
      NULL, jsonb_build_object('jobname', r.jobname, 'fails_2h', r.fails,
                               'last_success', r.last_success));
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;


ALTER FUNCTION public.fn_ca_cron_failure_watch() OWNER TO postgres;

--
-- Name: fn_ca_cron_health(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cron_health(p_window interval DEFAULT '24:00:00'::interval) RETURNS TABLE(jobname text, schedule text, verdict text, runs bigint, failures bigint, successes bigint, last_run_at timestamp with time zone, last_error text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with runs as (
    select j.jobname,
           j.schedule,
           count(r.*)                                     as runs,
           count(*) filter (where r.status = 'failed')    as failures,
           count(*) filter (where r.status = 'succeeded') as successes,
           max(r.start_time)                              as last_run_at,
           left(max(r.return_message) filter (where r.status = 'failed'), 200) as last_error
      from cron.job j
      left join cron.job_run_details r
        on r.jobid = j.jobid
       and r.start_time > now() - p_window
     where j.active
     group by j.jobname, j.schedule
  )
  select x.jobname, x.schedule,
         case
           -- Only FINISHED runs are evidence. pg_cron logs a row at START, so
           -- a job mid-flight has status 'running' and counts as neither.
           when x.failures + x.successes = 0 then 'idle'
           when x.successes = 0              then 'critical'
           when x.failures  > 0              then 'warn'
           else 'ok'
         end as verdict,
         x.runs, x.failures, x.successes, x.last_run_at, x.last_error
    from runs x
   order by
     case
       when x.failures + x.successes = 0 then 3
       when x.successes = 0              then 0
       when x.failures  > 0              then 1
       else 2
     end,
     x.failures desc,
     x.jobname;
$$;


ALTER FUNCTION public.fn_ca_cron_health(p_window interval) OWNER TO postgres;

--
-- Name: fn_ca_currency_meter(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_currency_meter() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_t0 timestamptz := clock_timestamp();
  v_out numeric; v_journal numeric; v_accounts int; v_drifted int; v_worst numeric; v_detail jsonb;
  v_res jsonb := '{}'::jsonb;
  v_rb_periods_paid numeric; v_rb_payout_rows numeric; v_rb_legs numeric; v_rb_pending numeric;
  v_rb_orphans int; v_rb_deletes int; v_rb_first_leg timestamptz;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'fn_ca_currency_meter is service only' USING ERRCODE = '42501';
  END IF;

  /* VIP POINTS: every balance against the sum of its legs. Enforced. */
  WITH j AS (SELECT user_id, sum(points) AS journal, sum(points) FILTER (WHERE points > 0) AS earned FROM public.vip_points_ledger GROUP BY 1)
  SELECT COALESCE(sum(v.current_points), 0), COALESCE(sum(j.journal), 0), count(*),
         count(*) FILTER (WHERE COALESCE(j.journal, 0) <> COALESCE(v.current_points, 0) OR COALESCE(j.earned, 0) <> COALESCE(v.lifetime_points, 0)),
         COALESCE(max(abs(COALESCE(j.journal, 0) - COALESCE(v.current_points, 0))), 0),
         jsonb_build_object(
           'balance_without_journal', count(*) FILTER (WHERE j.user_id IS NULL),
           'journal_without_balance', count(*) FILTER (WHERE v.user_id IS NULL),
           'sample', COALESCE((SELECT jsonb_agg(jsonb_build_object('user_id', x.uid, 'balance', x.bal, 'journal', x.jr)) FROM (
              SELECT COALESCE(v2.user_id, j2.user_id) AS uid, v2.current_points AS bal, j2.journal AS jr
                FROM public.vip_points v2 FULL JOIN j j2 ON j2.user_id = v2.user_id
               WHERE COALESCE(j2.journal, 0) <> COALESCE(v2.current_points, 0) LIMIT 10) x), '[]'::jsonb))
    INTO v_out, v_journal, v_accounts, v_drifted, v_worst, v_detail
    FROM public.vip_points v FULL JOIN j ON j.user_id = v.user_id;
  INSERT INTO public.ca_currency_meter (currency, outstanding, journal_total, accounts, drifted, worst, enforced, detail)
  VALUES ('vip_points', v_out, v_journal, v_accounts, v_drifted, v_worst, true, v_detail);
  IF v_drifted > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_currency_meter', 'ledger_imbalance', 'critical', 'currency-drift:vip_points',
      v_out - v_journal, v_journal, v_out, 'ledger', 'vip_points',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      v_drifted || ' VIP balance(s) disagree with their own ledger (worst ' || v_worst || ' points). '
        || 'zz_vip_points_move_only_with_a_leg and the append-only guard on vip_points_ledger make this '
        || 'impossible through the doors; seeing it means a guard was bypassed or dropped.',
      false, v_detail);
  END IF;
  v_res := v_res || jsonb_build_object('vip_points', jsonb_build_object('outstanding', v_out, 'journal', v_journal, 'accounts', v_accounts, 'drifted', v_drifted, 'worst', v_worst));

  /* AGENT COMMISSIONS: every rollup against the sum of its unsettled rows. Enforced. */
  WITH u AS (SELECT club_id, user_id, sum(amount) AS owed FROM public.agent_commissions_unsettled GROUP BY 1, 2)
  SELECT COALESCE(sum(r.owed), 0), COALESCE(sum(u.owed), 0), count(*),
         count(*) FILTER (WHERE round(COALESCE(u.owed, 0), 2) <> round(COALESCE(r.owed, 0), 2)),
         COALESCE(max(abs(COALESCE(u.owed, 0) - COALESCE(r.owed, 0))), 0),
         jsonb_build_object(
           'journal_without_rollup', count(*) FILTER (WHERE r.club_id IS NULL),
           'rollup_without_journal', count(*) FILTER (WHERE u.club_id IS NULL))
    INTO v_out, v_journal, v_accounts, v_drifted, v_worst, v_detail
    FROM u FULL JOIN public.agent_commission_unsettled_rollup r ON r.club_id = u.club_id AND r.user_id = u.user_id;
  INSERT INTO public.ca_currency_meter (currency, outstanding, journal_total, accounts, drifted, worst, enforced, detail)
  VALUES ('agent_commissions', v_out, v_journal, v_accounts, v_drifted, v_worst, true, v_detail);
  IF v_drifted > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_currency_meter', 'ledger_imbalance', 'critical', 'currency-drift:agent_commissions',
      v_out - v_journal, v_journal, v_out, 'ledger', 'agent_commissions',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      v_drifted || ' agent(s) whose unsettled rollup disagrees with their commission rows (worst ' || round(v_worst, 2) || '). '
        || 'The rollup is kept by statement triggers and the rows are append-only; seeing it means one of those was bypassed.',
      false, v_detail);
  END IF;
  v_res := v_res || jsonb_build_object('agent_commissions', jsonb_build_object('outstanding', v_out, 'journal', v_journal, 'accounts', v_accounts, 'drifted', v_drifted, 'worst', v_worst));

  /* RAKEBACK: three sources side by side. NOT enforced - the period row is a
     counter that accrues by design, and the payout path is another lane's. */
  SELECT COALESCE(sum(rakeback_amount) FILTER (WHERE status = 'paid'), 0),
         COALESCE(sum(rakeback_amount) FILTER (WHERE status <> 'paid'), 0)
    INTO v_rb_periods_paid, v_rb_pending FROM public.rakeback_periods;
  SELECT COALESCE(sum(payout_amount), 0) INTO v_rb_payout_rows FROM public.rakeback_period_payouts WHERE status = 'paid';
  SELECT COALESCE(sum(amount), 0), min(created_at) INTO v_rb_legs, v_rb_first_leg
    FROM public.chip_ledger WHERE category = 'rakeback' AND to_type = 'player_wallet';
  SELECT count(*) INTO v_rb_orphans FROM public.rakeback_periods p
   WHERE p.status = 'paid' AND p.rakeback_amount > 0
     AND NOT EXISTS (SELECT 1 FROM public.rakeback_period_payouts pp WHERE pp.rakeback_period_id = p.id);
  SELECT count(*) INTO v_rb_deletes FROM public.ca_ledger_mutation_log
   WHERE source_table = 'rakeback_period_payouts' AND at > now() - interval '1 day';
  v_detail := jsonb_build_object(
    'periods_paid_total', v_rb_periods_paid, 'payout_rows_total', v_rb_payout_rows,
    'chip_legs_to_players_total', v_rb_legs, 'chip_journal_since', v_rb_first_leg,
    'paid_periods_without_payout_row', v_rb_orphans, 'payout_rows_deleted_24h', v_rb_deletes,
    'not_enforced_because', 'rakeback_periods accrues during the period by design and the payout path (fn_close_settlement_period) is another lane''s live rebuild as of 2026-09-07; the meter reads the three sources and names the gap');
  INSERT INTO public.ca_currency_meter (currency, outstanding, journal_total, accounts, drifted, worst, enforced, detail)
  VALUES ('rakeback', v_rb_pending, v_rb_payout_rows, 0,
          CASE WHEN round(v_rb_periods_paid, 2) <> round(v_rb_payout_rows, 2) THEN 1 ELSE 0 END,
          abs(v_rb_periods_paid - v_rb_payout_rows), false, v_detail);
  IF round(v_rb_periods_paid, 2) <> round(v_rb_payout_rows, 2) OR v_rb_orphans > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_currency_meter', 'ledger_imbalance', 'warning', 'currency-drift:rakeback',
      v_rb_periods_paid - v_rb_payout_rows, v_rb_payout_rows, v_rb_periods_paid, 'ledger', 'rakeback_periods',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'rakeback_periods says ' || v_rb_periods_paid || ' paid; rakeback_period_payouts says ' || v_rb_payout_rows
        || '; chip_ledger legs to players say ' || v_rb_legs || ' since ' || COALESCE(v_rb_first_leg::text, 'never')
        || '. ' || v_rb_orphans || ' paid period(s) have no payout row. Not enforced by this meter; see detail.',
      false, v_detail);
  END IF;
  v_res := v_res || jsonb_build_object('rakeback', v_detail || jsonb_build_object('pending', v_rb_pending));

  RETURN v_res || jsonb_build_object('at', now(), 'ms', round(extract(epoch from (clock_timestamp() - v_t0)) * 1000));
END $$;


ALTER FUNCTION public.fn_ca_currency_meter() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_currency_meter(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_currency_meter() IS 'Nightly conservation meter for the currencies that are not chips. ENFORCED: vip_points against vip_points_ledger, and agent_commission_unsettled_rollup against unsettled agent_commissions - both hold by construction because the journals are append-only and the balance moves only with a leg, so a drift is a CRITICAL incident meaning a guard was bypassed or dropped. NOT ENFORCED, and deliberately: rakeback (three sources disagree by design while fn_close_settlement_period is another lane''s live rebuild; the row carries not_enforced_because and raises a WARNING with the numbers). NOT COVERED AT ALL: vip_points_carry, the fractional remainder between awards, which no guard watches; and the commission rollup is COMPARED here rather than guarded, its correctness resting on the statement triggers that maintain it. Cost is O(journal) - 10.2s at 5.75M VIP legs, growing ~306k/day against job 286''s 600s budget.';


