--
-- Name: fn_ca_daily_attestation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_attestation() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_open integer; v_critical integer; v_resolved integer; v_suspense numeric;
  v_failures integer; v_chain record; v_rows bigint; v_green boolean;
  v_title text; v_body text; v_uid uuid; v_sent integer := 0;
BEGIN
  SELECT count(*) FILTER (WHERE status <> 'resolved'),
         count(*) FILTER (WHERE status <> 'resolved' AND severity = 'critical'),
         count(*) FILTER (WHERE status = 'resolved' AND resolved_at > now() - interval '24 hours')
    INTO v_open, v_critical, v_resolved
    FROM public.ca_drift_incidents;
  SELECT COALESCE(sum(amount), 0) INTO v_suspense FROM public.chip_ledger
   WHERE (from_type='settlement_suspense' OR to_type='settlement_suspense')
     AND created_at > now() - interval '24 hours';
  SELECT count(*) INTO v_failures FROM public.ca_ledger_write_failures
   WHERE occurred_at > now() - interval '24 hours';
  SELECT * INTO v_chain FROM public.fn_ca_verify_ledger_chain(20000);
  SELECT count(*) INTO v_rows FROM public.chip_ledger WHERE created_at > now() - interval '24 hours';

  v_green := v_open = 0 AND v_failures = 0 AND COALESCE(v_chain.breaks, 0) = 0
             AND v_suspense < 50;
  v_title := CASE WHEN v_green THEN '✅ Chip integrity: all green'
                  ELSE '📋 Chip integrity: attention needed' END;
  v_body := v_rows || ' ledger rows / 24h. Open incidents: ' || v_open
    || ' (' || v_critical || ' critical). Resolved / 24h: ' || v_resolved
    || '. Unclassified flow: ' || round(v_suspense, 2)
    || '. Ledger write failures: ' || v_failures
    || '. Checksum verify: ' || COALESCE(v_chain.checked, 0) || ' rows, '
    || COALESCE(v_chain.breaks, 0) || ' breaks.';

  FOR v_uid IN
    SELECT DISTINCT user_id FROM public.ca_incident_recipients
     WHERE active AND scope = 'platform'
  LOOP
    PERFORM public.fn_raise_notification(v_uid, 'financial_attestation', v_title, v_body,
      '/hub/club-arena/financial-incidents',
      jsonb_build_object('green', v_green, 'open', v_open, 'critical', v_critical,
                         'suspense', round(v_suspense,2), 'chain_breaks', COALESCE(v_chain.breaks,0)));
    v_sent := v_sent + 1;
  END LOOP;

  RETURN jsonb_build_object('green', v_green, 'recipients', v_sent, 'open', v_open,
    'critical', v_critical, 'resolved_24h', v_resolved, 'suspense_24h', round(v_suspense,2),
    'write_failures_24h', v_failures, 'chain_checked', COALESCE(v_chain.checked,0),
    'chain_breaks', COALESCE(v_chain.breaks,0), 'ledger_rows_24h', v_rows);
END $$;


ALTER FUNCTION public.fn_ca_daily_attestation() OWNER TO postgres;

--
-- Name: fn_ca_daily_bonus_calendar_history(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_bonus_calendar_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.ca_daily_bonus_calendar_history (op, old_row, new_row)
  VALUES (TG_OP,
          CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) END,
          CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) END);
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


