--
-- Name: ca_daily_bonus_days; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_daily_bonus_days (
    user_id uuid NOT NULL,
    bonus_date date NOT NULL,
    streak integer NOT NULL,
    cycle_day integer NOT NULL,
    streak_day integer,
    tiles jsonb NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    first_claimed_at timestamp with time zone,
    CONSTRAINT ca_daily_bonus_days_cycle_day_check CHECK (((cycle_day >= 1) AND (cycle_day <= 7))),
    CONSTRAINT ca_daily_bonus_days_streak_check CHECK ((streak >= 1))
);


ALTER TABLE public.ca_daily_bonus_days OWNER TO postgres;

--
-- Name: TABLE ca_daily_bonus_days; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_daily_bonus_days IS 'One row per player per Chicago date, written the first time the sheet is opened: the streak that day, and the tiles offered as a snapshot of the calendar (with the mystery roll already decided). first_claimed_at is what makes the day count toward the streak. Read through fn_ca_daily_bonus_status.';


--
-- Name: fn_ca_daily_bonus_open_day(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_bonus_open_day(p_user_id uuid, p_today date) RETURNS public.ca_daily_bonus_days
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row        public.ca_daily_bonus_days;
  v_yesterday  public.ca_daily_bonus_days;
  v_streak     integer;
  v_cycle_day  integer;
  v_streak_day integer;
  v_tiles      jsonb;
  v_roll       numeric;
  v_mystery    jsonb;
BEGIN
  SELECT * INTO v_row FROM public.ca_daily_bonus_days
   WHERE user_id = p_user_id AND bonus_date = p_today;
  IF FOUND THEN RETURN v_row; END IF;

  -- The streak advances only across consecutive CLAIMED days. An opened but
  -- unclaimed yesterday is a gap, exactly like a day never opened.
  SELECT * INTO v_yesterday FROM public.ca_daily_bonus_days
   WHERE user_id = p_user_id AND bonus_date = p_today - 1;
  IF FOUND AND v_yesterday.first_claimed_at IS NOT NULL THEN
    v_streak := v_yesterday.streak + 1;
  ELSE
    v_streak := 1;
  END IF;

  v_cycle_day := ((v_streak - 1) % 7) + 1;
  SELECT c.streak_day INTO v_streak_day
    FROM public.ca_daily_bonus_calendar c
   WHERE c.streak_day = v_streak AND c.active
   LIMIT 1;

  -- The mystery roll is decided when the day opens and stored with the
  -- snapshot, so a claim reveals it rather than rolling it. Weights, in
  -- cents of expected value: 10 (40%), 25 (25%), 5 throwables (15%),
  -- 3 rabbit hunts (10%), 50 (7%), 100 (3%) = 22.9 cents expected.
  v_roll := random();
  v_mystery := CASE
    WHEN v_roll < 0.40 THEN jsonb_build_object('kind', 'diamonds',     'diamonds', 10,  'quantity', 0)
    WHEN v_roll < 0.65 THEN jsonb_build_object('kind', 'diamonds',     'diamonds', 25,  'quantity', 0)
    WHEN v_roll < 0.80 THEN jsonb_build_object('kind', 'throwables',   'diamonds', 0,   'quantity', 5)
    WHEN v_roll < 0.90 THEN jsonb_build_object('kind', 'rabbit_hunts', 'diamonds', 0,   'quantity', 3)
    WHEN v_roll < 0.97 THEN jsonb_build_object('kind', 'diamonds',     'diamonds', 50,  'quantity', 0)
    ELSE                    jsonb_build_object('kind', 'diamonds',     'diamonds', 100, 'quantity', 0)
  END;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'slot', c.slot,
           'kind', c.kind,
           'label', c.label,
           'vip_only', c.vip_only,
           'quantity', c.quantity,
           'base_diamonds', c.diamonds,
           -- The diamond tile scales with the platform streak ladder. Clamped
           -- to award_diamonds_v2's 125-per-call ceiling so the sheet never
           -- shows a number the ledger would trim.
           'diamonds', CASE WHEN c.kind = 'diamonds'
                            THEN LEAST(125, round(c.diamonds * public.fn_get_streak_multiplier(v_streak))::integer)
                            ELSE 0 END,
           'mystery', CASE WHEN c.kind = 'mystery' THEN v_mystery ELSE NULL END
         ) ORDER BY c.slot), '[]'::jsonb)
    INTO v_tiles
    FROM public.ca_daily_bonus_calendar c
   WHERE c.active
     AND ((v_streak_day IS NOT NULL AND c.streak_day = v_streak_day)
       OR (v_streak_day IS NULL AND c.cycle_day = v_cycle_day));

  IF v_tiles = '[]'::jsonb THEN
    RAISE EXCEPTION 'fn_ca_daily_bonus_open_day: no calendar rows for streak % (cycle day %)', v_streak, v_cycle_day
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.ca_daily_bonus_days (user_id, bonus_date, streak, cycle_day, streak_day, tiles)
  VALUES (p_user_id, p_today, v_streak, v_cycle_day, v_streak_day, v_tiles)
  ON CONFLICT (user_id, bonus_date) DO NOTHING;

  SELECT * INTO v_row FROM public.ca_daily_bonus_days
   WHERE user_id = p_user_id AND bonus_date = p_today;
  RETURN v_row;
END;
$$;


ALTER FUNCTION public.fn_ca_daily_bonus_open_day(p_user_id uuid, p_today date) OWNER TO postgres;

--
-- Name: fn_ca_daily_bonus_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_bonus_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_elig       text;
  v_today      date := (now() AT TIME ZONE 'America/Chicago')::date;
  v_reset_at   timestamptz := ((now() AT TIME ZONE 'America/Chicago')::date + 1)::timestamp AT TIME ZONE 'America/Chicago';
  v_day        public.ca_daily_bonus_days;
  v_is_vip     boolean := false;
  v_caps       jsonb;
  v_tiles      jsonb;
  v_week       jsonb;
  v_next       jsonb;
  v_next_streak integer;
  v_next_cycle  integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_ca_daily_bonus_status requires an authenticated caller' USING ERRCODE = '28000';
  END IF;

  v_elig := public.fn_ca_daily_bonus_eligibility(v_uid);
  IF v_elig <> 'ok' THEN
    RETURN jsonb_build_object('eligible', false, 'reason', v_elig, 'today', v_today,
                              'reset_at', v_reset_at, 'tiles', '[]'::jsonb);
  END IF;

  SELECT COALESCE(p.is_vip, false)
         AND (p.vip_tier = 'lifetime' OR p.vip_expires_at IS NULL OR p.vip_expires_at > now())
    INTO v_is_vip
    FROM public.profiles p WHERE p.id = v_uid;

  v_day  := public.fn_ca_daily_bonus_open_day(v_uid, v_today);
  v_caps := public.fn_ca_daily_bonus_caps(v_uid, v_is_vip);

  -- Today's tiles with their claim state. The mystery result stays hidden
  -- until it is claimed; the claim reveals it. A diamond tile the daily cap
  -- would trim is flagged so the sheet can say so before the tap.
  SELECT COALESCE(jsonb_agg(
           (t - 'mystery') || jsonb_build_object(
             'claimed', cl.id IS NOT NULL,
             'claimed_at', cl.created_at,
             'granted', cl.granted,
             'locked', (t->>'vip_only')::boolean AND NOT v_is_vip,
             'capped', cl.id IS NULL AND t->>'kind' = 'diamonds'
                       AND (t->>'diamonds')::int > (v_caps->>'daily_remaining')::int
           ) ORDER BY (t->>'slot')::int), '[]'::jsonb)
    INTO v_tiles
    FROM jsonb_array_elements(v_day.tiles) t
    LEFT JOIN public.ca_daily_bonus_claims cl
      ON cl.user_id = v_uid AND cl.bonus_date = v_today AND cl.slot = (t->>'slot')::int;

  SELECT jsonb_agg(jsonb_build_object(
           'day', d,
           'streak', v_day.streak - v_day.cycle_day + d,
           'diamonds', (SELECT LEAST(125, round(c.diamonds * public.fn_get_streak_multiplier(GREATEST(1, v_day.streak - v_day.cycle_day + d)))::integer)
                          FROM public.ca_daily_bonus_calendar c
                         WHERE c.active AND c.cycle_day = d AND c.kind = 'diamonds' AND NOT c.vip_only
                         ORDER BY c.slot LIMIT 1),
           'extras', (SELECT string_agg(c.label, ', ' ORDER BY c.slot)
                        FROM public.ca_daily_bonus_calendar c
                       WHERE c.active AND c.cycle_day = d AND c.kind <> 'diamonds'),
           'state', CASE WHEN d < v_day.cycle_day THEN 'done'
                         WHEN d = v_day.cycle_day THEN 'today'
                         ELSE 'upcoming' END
         ) ORDER BY d)
    INTO v_week
    FROM generate_series(1, 7) d;

  v_next_streak := v_day.streak + 1;
  v_next_cycle  := ((v_next_streak - 1) % 7) + 1;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'kind', c.kind, 'label', c.label, 'vip_only', c.vip_only, 'quantity', c.quantity,
           'diamonds', CASE WHEN c.kind = 'diamonds'
                            THEN LEAST(125, round(c.diamonds * public.fn_get_streak_multiplier(v_next_streak))::integer)
                            ELSE 0 END
         ) ORDER BY c.slot), '[]'::jsonb)
    INTO v_next
    FROM public.ca_daily_bonus_calendar c
   WHERE c.active
     AND ((EXISTS (SELECT 1 FROM public.ca_daily_bonus_calendar s WHERE s.active AND s.streak_day = v_next_streak)
             AND c.streak_day = v_next_streak)
       OR (NOT EXISTS (SELECT 1 FROM public.ca_daily_bonus_calendar s WHERE s.active AND s.streak_day = v_next_streak)
             AND c.cycle_day = v_next_cycle));

  RETURN jsonb_build_object(
    'eligible', true,
    'today', v_today,
    'reset_at', v_reset_at,
    'seconds_to_reset', GREATEST(0, floor(extract(epoch FROM (v_reset_at - now())))::integer),
    'streak', v_day.streak,
    'cycle_day', v_day.cycle_day,
    'streak_day', v_day.streak_day,
    'multiplier', public.fn_get_streak_multiplier(v_day.streak),
    'is_vip', v_is_vip,
    'claimed_today', v_day.first_claimed_at IS NOT NULL,
    'unclaimed', (SELECT count(*) FROM jsonb_array_elements(v_tiles) x
                   WHERE NOT (x->>'claimed')::boolean AND NOT (x->>'locked')::boolean),
    'tiles', v_tiles,
    'week', v_week,
    'tomorrow', v_next,
    'caps', v_caps,
    'cents_per_diamond', 1
  );
END;
$$;


ALTER FUNCTION public.fn_ca_daily_bonus_status() OWNER TO postgres;

--
-- Name: fn_ca_declare_ledger(text, text, uuid, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_declare_ledger(p_category text, p_counterparty text, p_counterparty_entity uuid DEFAULT NULL::uuid, p_settlement_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_autoskip_tables text[] DEFAULT NULL::text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_t text;
BEGIN
  -- validate against the LIVE vocabulary so this can never lag a CHECK change
  IF p_category IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_category_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_category || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: category % is not in the ledger vocabulary - add it to chip_ledger_category_check FIRST, then declare it', p_category;
  END IF;
  IF p_counterparty IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_from_type_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_counterparty || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: counterparty % is not in the ledger vocabulary - add it to the from/to type CHECKs FIRST, then declare it', p_counterparty;
  END IF;

  PERFORM set_config('app.ledger_category', p_category, true);
  PERFORM set_config('app.ledger_counterparty', p_counterparty, true);
  PERFORM set_config('app.ledger_counterparty_entity',
                     COALESCE(p_counterparty_entity::text, ''), true);
  IF p_settlement_id IS NOT NULL THEN
    PERFORM set_config('app.ledger_settlement', p_settlement_id::text, true);
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM set_config('app.ledger_idempotency_key', p_idempotency_key, true);
  END IF;
  IF p_autoskip_tables IS NOT NULL THEN
    FOREACH v_t IN ARRAY p_autoskip_tables LOOP
      IF v_t !~ '^[a-z_]+$' THEN
        RAISE EXCEPTION 'fn_ca_declare_ledger: bad autoskip table name %', v_t;
      END IF;
      PERFORM set_config('app.ledger_autoskip_' || v_t, '1', true);
    END LOOP;
  END IF;
END $_$;


ALTER FUNCTION public.fn_ca_declare_ledger(p_category text, p_counterparty text, p_counterparty_entity uuid, p_settlement_id uuid, p_idempotency_key text, p_autoskip_tables text[]) OWNER TO postgres;

--
-- Name: fn_ca_deploy_dispatch_tick(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_deploy_dispatch_tick(p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'vault'
    AS $$
DECLARE
  cfg public.ca_deploy_dispatch_config;
  v_win TIMESTAMPTZ := date_trunc('hour', now()) + interval '1 hour';
  v_token text; v_url text; v_action text; v_req bigint;
BEGIN
  SELECT * INTO cfg FROM public.ca_deploy_dispatch_config WHERE id;

  IF public.fn_ca_deploy_run_exists_this_hour() THEN
    v_action := 'skipped_existing_run';
  ELSIF NOT cfg.enabled THEN
    v_action := 'disarmed';
  ELSIF NOT EXISTS (SELECT 1 FROM public.ca_engine_deploy_runs_started) THEN
    -- The only way this dispatcher knows a run is in flight is the marker the
    -- workflow writes at start. Until one has ever been written, that step is
    -- not live and firing would duplicate GitHub's cron every hour.
    v_action := 'no_marker_writer_yet';
  ELSE
    SELECT decrypted_secret INTO v_token FROM vault.decrypted_secrets WHERE name = cfg.vault_secret;
    IF v_token IS NULL OR v_token = '' THEN
      v_action := 'no_token';
    ELSIF p_dry_run THEN
      v_action := 'dry_run';
    ELSE
      v_url := 'https://api.github.com/repos/' || cfg.repo
             || '/actions/workflows/' || cfg.workflow_file || '/dispatches';
      SELECT net.http_post(
        url := v_url,
        body := jsonb_build_object('ref', cfg.ref, 'inputs', '{}'::jsonb),
        headers := jsonb_build_object(
          'Authorization', 'Bearer ' || v_token,
          'Accept', 'application/vnd.github+json',
          'User-Agent', 'ca-db-dispatcher',
          'Content-Type', 'application/json')
      ) INTO v_req;
      v_action := 'dispatched';
    END IF;
  END IF;

  INSERT INTO public.ca_deploy_dispatch_log (window_hour, action, net_request_id, detail)
  VALUES (v_win, v_action, v_req,
          jsonb_build_object('enabled', cfg.enabled, 'dry_run', p_dry_run));
  RETURN jsonb_build_object('window_hour', v_win, 'action', v_action, 'net_request_id', v_req);
END $$;


ALTER FUNCTION public.fn_ca_deploy_dispatch_tick(p_dry_run boolean) OWNER TO postgres;

--
-- Name: fn_ca_deploy_run_exists_this_hour(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_deploy_run_exists_this_hour() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.ca_engine_deploy_runs_started
                  WHERE started_at >= now() - interval '25 minutes');
$$;


ALTER FUNCTION public.fn_ca_deploy_run_exists_this_hour() OWNER TO postgres;

--
-- Name: fn_ca_diamond_born_with_balance(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_born_with_balance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_fixture boolean := false;
BEGIN
  BEGIN
    v_fixture := public.fn_ca_is_fixture_account(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    v_fixture := false;
  END;
  -- DR2 (DIAMOND-RULINGS 17): once flipped, a player profile may not be born holding
  -- diamonds; every seeder inserts 0 and the Mint grants under signup:<id>. Fixtures are
  -- filed at info and never refused. The raise is outside the handlers below on purpose.
  IF NOT v_fixture AND public.fn_ca_diamond_rule_mode('DR2:balance_born_outside_the_mint') = 'refuse' THEN
    RAISE EXCEPTION 'DR2: a profile may not be born holding % diamonds; insert 0 and let fn_ca_mint grant under signup:<id>', NEW.diamonds
      USING ERRCODE = 'P0402';
  END IF;
  BEGIN
    PERFORM public.fn_ca_diamond_incident(
      'DR2:balance_born_outside_the_mint',
      CASE WHEN v_fixture THEN 'info' ELSE 'warning' END,
      NEW.id, NEW.diamonds, 'profiles INSERT',
      jsonb_build_object('is_horse', NEW.is_horse, 'is_fixture', v_fixture,
                         'app_name', COALESCE(current_setting('application_name', true), ''),
                         'db_role', CURRENT_USER, 'username', NEW.username, 'diamonds', NEW.diamonds));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_ca_diamond_born_with_balance could not record the incident for %: %', NEW.id, SQLERRM;
  END;
  BEGIN
    INSERT INTO public.ca_mint_ledger
      (op_id, action, asset, holder_type, holder_id, holder_label, amount, balance_before, balance_after,
       supply_after, reason, performed_by, performed_by_label)
    VALUES
      ('seed:' || NEW.id::text, 'mint', 'diamonds', 'player', NEW.id,
       COALESCE(NULLIF(BTRIM(NEW.username), ''), NEW.id::text), NEW.diamonds, 0, NEW.diamonds,
       public.fn_ca_mint_supply('diamonds') + NEW.diamonds,
       CASE WHEN v_fixture THEN 'balance present at fixture profile INSERT' ELSE 'balance present at profile INSERT' END,
       NULL, 'zz_ca_diamond_born_with_balance')
    ON CONFLICT (op_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_ca_diamond_born_with_balance could not register the seed for %: %', NEW.id, SQLERRM;
  END;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_diamond_born_with_balance() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_born_with_balance(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_born_with_balance() IS 'DR2, log-only. A profiles INSERT carrying a non-zero diamonds balance did not pass through the Mint: record it in ca_diamond_incidents and put the amount in ca_mint_ledger under op_id seed:<profile id> so the supply register still matches SUM(profiles.diamonds). Writes no diamond_transactions row - the seeder inserts the profile before the auth.users row exists and that journal is FK-bound to it; handle_new_user writes it a moment later. Never raises.';


--
-- Name: fn_ca_diamond_breakage_aging(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_breakage_aging() RETURNS TABLE(bucket text, lots bigint, issued numeric, consumed numeric, refunded numeric, outstanding numeric, note text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH aged AS (
    SELECT CASE
             WHEN l.settled_at IS NULL THEN 'unsettled'
             WHEN l.settled_at > now() - interval '14 days'  THEN 'age_0_14d'
             WHEN l.settled_at > now() - interval '90 days'  THEN 'age_15_90d'
             WHEN l.settled_at > now() - interval '365 days' THEN 'age_91_365d'
             ELSE 'age_over_365d'
           END AS bucket,
           l.issued, l.consumed, l.refunded,
           (l.issued - l.consumed - l.refunded) AS outstanding
      FROM public.diamond_purchase_lots l
  )
  SELECT a.bucket,
         count(*)::bigint,
         COALESCE(sum(a.issued), 0)::numeric,
         COALESCE(sum(a.consumed), 0)::numeric,
         COALESCE(sum(a.refunded), 0)::numeric,
         COALESCE(sum(a.outstanding), 0)::numeric,
         CASE a.bucket
           WHEN 'unsettled'     THEN 'settled_at is null: a lot the settle path never stamped. Should be zero.'
           WHEN 'age_0_14d'     THEN 'inside the arena settlement window (ruling 14) and inside most card dispute windows: this is the money a chargeback can still take back.'
           WHEN 'age_15_90d'    THEN 'past the arena window, still inside the usual 120-day card dispute reach.'
           WHEN 'age_91_365d'   THEN 'past most dispute windows; outstanding here is ageing toward breakage.'
           ELSE                      'over a year old and never spent: breakage in all but name. A candidate for a revenue recognition decision, which is Dan''s.'
         END::text
    FROM aged a
   GROUP BY a.bucket
   ORDER BY CASE a.bucket
              WHEN 'unsettled' THEN 0 WHEN 'age_0_14d' THEN 1 WHEN 'age_15_90d' THEN 2
              WHEN 'age_91_365d' THEN 3 ELSE 4 END;
$$;


ALTER FUNCTION public.fn_ca_diamond_breakage_aging() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_breakage_aging(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_breakage_aging() IS 'Purchased diamond lots by age: what is still refundable, what is ageing, what is breakage in all but name.';


--
-- Name: fn_ca_diamond_budget_reality(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_budget_reality(p_period text DEFAULT NULL::text) RETURNS TABLE(period text, engine text, budgeted bigint, actual numeric, ratio numeric, verdict text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_now text := to_char((now() AT TIME ZONE 'America/Chicago'), 'YYYY-MM');
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  RETURN QUERY
  WITH ref AS (
    -- What each engine ACTUALLY issued in the most recent complete-enough month we have, which is
    -- the only honest thing to judge a plan against.
    SELECT b.period AS per, b.engine AS eng,
           public.fn_ca_diamond_engine_spent(b.period, b.engine)::numeric AS act,
           b.budget_diamonds AS bud
      FROM public.diamond_reward_budgets b
     WHERE p_period IS NULL OR b.period = p_period)
  SELECT r.per, r.eng, r.bud, r.act,
         CASE WHEN r.bud IS NULL OR r.bud = 0 THEN NULL
              ELSE round(r.act / r.bud, 2) END,
         CASE
           WHEN r.bud IS NULL THEN
             'NO PLAN SET. Refuses nobody either way (ruling 21); this is simply unstated.'
           WHEN r.act = 0 AND r.bud = 0 THEN 'Nothing budgeted, nothing issued.'
           WHEN r.bud = 0 AND r.act > 0 THEN
             'BUDGETED ZERO, ISSUED ' || r.act || '. The plan says this engine does not exist.'
           WHEN r.act > r.bud THEN
             'ALREADY OVER: issued ' || r.act || ' against a plan of ' || r.bud || ' ('
             || round(r.act / NULLIF(r.bud, 0), 1) || 'x). The plan is fiction.'
           WHEN r.per > v_now AND r.bud > 0 AND EXISTS (
                  SELECT 1 FROM public.diamond_reward_budgets q
                   WHERE q.engine = r.eng AND q.period < r.per
                     AND public.fn_ca_diamond_engine_spent(q.period, q.engine) > r.bud * 2)
             THEN 'FUTURE PLAN BELOW PAST ACTUAL. A previous month issued more than twice this '
                  || 'plan, so it will read as over on the day it starts.'
           ELSE 'Plausible: issued ' || r.act || ' against a plan of ' || r.bud || '.'
         END
    FROM ref r
   ORDER BY r.per DESC, (CASE WHEN r.bud IS NULL THEN 0 ELSE r.act / NULLIF(r.bud, 0) END) DESC NULLS LAST;
END $$;


ALTER FUNCTION public.fn_ca_diamond_budget_reality(p_period text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_budget_reality(p_period text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_budget_reality(p_period text) IS 'Every reward budget against what that engine actually issued, with a verdict in words. Exists because the budgets refuse nobody (ruling 21) yet read as controls, and three of them were fiction - a bigint-max sentinel, an October plan 18x under September actual, and a September plan already exceeded 2.5x with nothing saying so.';


--
-- Name: fn_ca_diamond_cap_headroom(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_cap_headroom(p_days integer DEFAULT 14) RETURNS TABLE(engine text, cap_now integer, cap_vip integer, binding_cap integer, design_ceiling bigint, observed_max bigint, observed_p99 bigint, user_days bigint, would_refuse bigint, verdict text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_from date := current_date - GREATEST(COALESCE(p_days, 14), 1);
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  RETURN QUERY
  WITH awarded AS (
    SELECT a.engine AS eng, a.awarded AS amt,
           -- The cap that applies to THIS player. fn_ca_diamond_earn_ledger substitutes the VIP
           -- column outright when the player is VIP, so reading only the standard column certifies
           -- a limit that will never be used. That is how a 2,000 VIP cap read as "1.61x healthy"
           -- under a 4,000 standard cap on 2026-09-08.
           (COALESCE(p.is_vip, false)
            AND (COALESCE(p.vip_tier, '') = 'lifetime'
                 OR (p.vip_expires_at IS NOT NULL AND p.vip_expires_at > now()))) AS vip
      FROM public.diamond_user_daily_awards a
      JOIN public.profiles p ON p.id = a.user_id
     WHERE a.day >= v_from AND a.awarded > 0),
  ceiling AS (
    SELECT 'daily_challenges'::text AS eng, max(possible)::bigint AS ceil
      FROM (SELECT sum(u.diamond_reward_snapshot) AS possible
              FROM public.user_daily_challenges u
             WHERE u.created_at >= now() - make_interval(days => GREATEST(COALESCE(p_days, 14), 1))
             GROUP BY u.user_id, (u.created_at AT TIME ZONE 'America/Chicago')::date) s),
  rolled AS (
    SELECT c.engine AS eng,
           c.max_per_user_per_day AS cap_std,
           c.max_per_user_per_day_vip AS cap_v,
           LEAST(COALESCE(c.max_per_user_per_day, 2147483647),
                 COALESCE(c.max_per_user_per_day_vip, 2147483647)) AS cap_bind,
           cl.ceil AS ceil,
           COALESCE(max(w.amt), 0)::bigint AS obs_max,
           COALESCE(percentile_disc(0.99) WITHIN GROUP (ORDER BY w.amt), 0)::bigint AS obs_p99,
           count(w.amt) AS days,
           count(*) FILTER (
             WHERE w.amt > CASE WHEN w.vip
                                THEN COALESCE(c.max_per_user_per_day_vip, c.max_per_user_per_day)
                                ELSE c.max_per_user_per_day END) AS refused
      FROM public.diamond_engine_daily_caps c
      LEFT JOIN awarded w ON w.eng = c.engine
      LEFT JOIN ceiling cl ON cl.eng = c.engine
     GROUP BY c.engine, c.max_per_user_per_day, c.max_per_user_per_day_vip, cl.ceil)
  SELECT r.eng, r.cap_std, r.cap_v, r.cap_bind, r.ceil, r.obs_max, r.obs_p99, r.days, r.refused,
         CASE
           WHEN r.cap_std IS NULL AND r.cap_v IS NULL THEN
             'NO CAP. Nothing limits one account on this engine.'
           WHEN r.cap_v IS NOT NULL AND r.cap_std IS NOT NULL AND r.cap_v < r.cap_std THEN
             'VIP CAP IS LOWER (' || r.cap_v || ' vs ' || r.cap_std || '). The VIP column is what '
             || 'applies to a VIP, so that is the real limit and paying for VIP is a downgrade.'
           WHEN r.ceil IS NOT NULL AND r.cap_bind <= r.ceil THEN
             'BELOW THE DESIGN CEILING (' || r.ceil || '). This refuses a player who completed '
             || 'everything the game assigned them.'
           WHEN r.refused > 0 THEN
             'REFUSES REAL DAYS: ' || r.refused || ' of ' || r.days || ' user-days in the window are '
             || 'over the cap that applies to that player.'
           WHEN r.days = 0 THEN 'NO ACTIVITY in the window; nothing to judge it against.'
           ELSE 'HEALTHY. ' || r.days || ' user-days, highest ' || r.obs_max || ', binding cap '
                || r.cap_bind || ' - ' || round(r.cap_bind::numeric / NULLIF(r.obs_max, 0), 2)
                || 'x headroom.'
         END
    FROM rolled r
   ORDER BY r.refused DESC, r.eng;
END $$;


ALTER FUNCTION public.fn_ca_diamond_cap_headroom(p_days integer) OWNER TO postgres;

--
-- Name: fn_ca_diamond_catalog_history(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_catalog_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_sql text;
BEGIN
    BEGIN
        v_sql := format(
            'INSERT INTO public.%I (op, old_row, new_row) VALUES ($1, $2, $3)',
            TG_TABLE_NAME || '_history');
        IF TG_OP = 'INSERT' THEN
            EXECUTE v_sql USING TG_OP, NULL::jsonb, to_jsonb(NEW);
        ELSIF TG_OP = 'DELETE' THEN
            EXECUTE v_sql USING TG_OP, to_jsonb(OLD), NULL::jsonb;
        ELSE
            EXECUTE v_sql USING TG_OP, to_jsonb(OLD), to_jsonb(NEW);
        END IF;
    EXCEPTION WHEN OTHERS THEN
        PERFORM public.fn_ca_diamond_incident(
            'D21:catalog_history_write_failed', 'warning', NULL, NULL,
            'fn_ca_diamond_catalog_history',
            jsonb_build_object('table', TG_TABLE_NAME, 'op', TG_OP,
                               'sqlstate', SQLSTATE, 'sqlerrm', SQLERRM));
    END;
    RETURN NULL;
END;
$_$;


ALTER FUNCTION public.fn_ca_diamond_catalog_history() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_catalog_history(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_catalog_history() IS 'D21. AFTER INSERT OR UPDATE OR DELETE on a diamond pricing catalog: appends the old and new row to <table>_history. Never raises.';


--
-- Name: fn_ca_diamond_earn_ledger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_earn_ledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_engine text; v_period text; v_day date; v_budget bigint; v_spent bigint; v_awarded bigint;
    v_cap integer; v_cap_vip integer; v_is_vip boolean := false; v_at timestamptz;
    v_refuse text; v_refuse_detail text; v_armed boolean;
BEGIN
    BEGIN
        IF COALESCE(NEW.issuance_class, '') IN ('purchased', 'transferred', 'refund', 'admin', 'arena', 'spend', 'deletion', 'bridge') THEN
            RETURN NULL;
        END IF;
        IF COALESCE(NEW.type, '') = 'purchase' OR COALESCE(NEW.transaction_type, '') = 'purchase' THEN
            RETURN NULL;
        END IF;
        -- Fixture accounts are not players (2026-09-07 review DEF-03): their issuance is not
        -- promotional spend. Horses ARE players and are counted.
        IF public.fn_ca_is_fixture_account(NEW.user_id) THEN
            RETURN NULL;
        END IF;

        v_at     := COALESCE(NEW.created_at, now());
        v_engine := CASE WHEN NEW.issuance_class IS NULL THEN 'unclassified'
                         ELSE public.fn_ca_diamond_engine_of(NEW.type, NEW.transaction_type, NEW.source,
                                                             NEW.description, NEW.reference_id) END;
        v_period := to_char((v_at AT TIME ZONE 'America/Chicago'), 'YYYY-MM');
        v_day    := (v_at AT TIME ZONE 'America/Chicago')::date;

        -- THE PER-USER ROW FIRST. It is keyed (user_id, engine, day), so it contends only with the
        -- same player's own concurrent awards - which is to say, essentially never. It used to sit
        -- after the budget write and was therefore lost every time the budget write timed out,
        -- taking the per-user cap figure down with it.
        INSERT INTO public.diamond_user_daily_awards (user_id, engine, day, awarded, updated_at)
        VALUES (NEW.user_id, v_engine, v_day, NEW.amount, now())
        ON CONFLICT (user_id, engine, day) DO UPDATE
           SET awarded = diamond_user_daily_awards.awarded + EXCLUDED.awarded, updated_at = now()
        RETURNING awarded INTO v_awarded;

        -- THE BUDGET LINE EXISTS, BUT ITS TOTAL IS NO LONGER MAINTAINED HERE. This upsert touches
        -- the row only when the line is missing for a new period, so it is a once-a-month write,
        -- not a once-an-award one.
        INSERT INTO public.diamond_reward_budgets (period, engine, budget_diamonds, spent_diamonds, updated_at)
        VALUES (v_period, v_engine,
                COALESCE((SELECT b.budget_diamonds FROM public.diamond_reward_budgets b
                           WHERE b.engine = v_engine AND b.period < v_period
                           ORDER BY b.period DESC LIMIT 1), 2500000),
                0, now())
        ON CONFLICT (period, engine) DO NOTHING;

        -- ONE INSERT, NO CONTENTION. Two awards never touch the same row, so there is nothing to
        -- wait behind. This is the whole fix.
        INSERT INTO public.ca_diamond_engine_spend (period, engine, user_id, amount, journal_id, at)
        VALUES (v_period, v_engine, NEW.user_id, NEW.amount, NEW.id, v_at)
        ON CONFLICT (journal_id) DO NOTHING;

        -- RULING 21: THE ENGINE'S MONTHLY TOTAL IS A FORECAST, NOT A GATE. It is a pot shared
        -- between players, so refusing on it punishes whoever arrives last for what everybody
        -- else earned. The spend row appended above is the measurement, and the economy report
        -- reads it; nothing here refuses, and no incident is filed per award - daily_missions is
        -- 4.2x its line today, so one would fire on every single award and be muted inside a day
        -- (10.84). The only cap that refuses is the per-user one below.

        SELECT c.max_per_user_per_day, c.max_per_user_per_day_vip INTO v_cap, v_cap_vip
          FROM public.diamond_engine_daily_caps c WHERE c.engine = v_engine;
        IF v_cap_vip IS NOT NULL THEN
            SELECT COALESCE(p.is_vip, false) AND (COALESCE(p.vip_tier, '') = 'lifetime'
                     OR (p.vip_expires_at IS NOT NULL AND p.vip_expires_at > now()))
              INTO v_is_vip FROM public.profiles p WHERE p.id = NEW.user_id;
            IF COALESCE(v_is_vip, false) THEN v_cap := v_cap_vip; END IF;
        END IF;

        IF v_cap IS NOT NULL AND v_awarded > v_cap THEN
            IF public.fn_ca_diamond_rule_mode('DR7:user_over_daily_cap') = 'refuse' THEN
                v_refuse := COALESCE(v_refuse, 'DR7:user_over_daily_cap');
                v_refuse_detail := COALESCE(v_refuse_detail, format('engine %s day %s cap %s awarded %s', v_engine, v_day, v_cap, v_awarded));
            END IF;
            PERFORM public.fn_ca_diamond_incident('DR7:user_over_daily_cap', 'warning', NEW.user_id, NEW.amount,
                'fn_ca_diamond_earn_ledger',
                jsonb_build_object('engine', v_engine, 'day', v_day, 'is_vip', v_is_vip,
                                   'max_per_user_per_day', v_cap, 'awarded_today', v_awarded,
                                   'journal_id', NEW.id, 'reference_id', NEW.reference_id));
        END IF;
    EXCEPTION WHEN OTHERS THEN
        -- A FAILURE HERE MEANS A GUARD DID NOT RUN, and that is a different thing from a counter
        -- being late. While both rules are in `log` it is a warning; the moment either is armed to
        -- refuse, a write that could not complete is the guard failing OPEN, so it is CRITICAL and
        -- says so. The award is still paid: a player never loses an earned reward because our
        -- bookkeeping stumbled (10.9 rule 3), and "I could not tell" gets its own severity rather
        -- than being folded into silence (10.86).
        -- Only the per-user cap can refuse now (ruling 21), so it alone decides whether a
        -- write that could not complete means a guard failed open. The engine pot is a forecast
        -- and its rule row is deleted below; consulting a rule that no longer exists would read
        -- as armed while being nothing at all.
        v_armed := public.fn_ca_diamond_rule_mode('DR7:user_over_daily_cap') = 'refuse';
        PERFORM public.fn_ca_diamond_incident('DR7:ledger_write_failed',
            CASE WHEN v_armed THEN 'critical' ELSE 'warning' END, NEW.user_id, NEW.amount,
            'fn_ca_diamond_earn_ledger',
            jsonb_build_object('sqlstate', SQLSTATE, 'sqlerrm', SQLERRM, 'journal_id', NEW.id,
                               'reference_id', NEW.reference_id, 'rules_armed', v_armed,
                               'note', CASE WHEN v_armed
                                            THEN 'A rule is armed to refuse and this write did not complete, so neither cap was evaluated for this award. The guard failed OPEN.'
                                            ELSE 'Both rules are in log mode; nothing was refused either way.' END));
    END;
    -- DIAMOND-RULINGS 17/18: a flipped DR7 refuses the credit. Raising here aborts the writer's
    -- whole transaction (balance, journal, ledger rows), so nothing is issued and nothing is
    -- half-written. The incident above rolls back with it; the writer's error carries the reason.
    IF v_refuse IS NOT NULL THEN
        RAISE EXCEPTION '%: promotional issuance refused (%)', v_refuse, v_refuse_detail
            USING ERRCODE = 'P0407';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_diamond_earn_ledger() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_earn_ledger(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_earn_ledger() IS 'DR7 LOG-ONLY. AFTER INSERT on diamond_transactions for positive amounts: charges the engine budget line, adds to the per-user per-day total, and files DR7:engine_over_budget / DR7:user_over_daily_cap incidents. Never refuses; any failure becomes DR7:ledger_write_failed.';


--
-- Name: fn_ca_diamond_economy(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_economy(p_days integer DEFAULT 30) RETURNS TABLE(section text, metric text, value numeric, comparison numeric, note text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_from timestamptz := now() - make_interval(days => GREATEST(COALESCE(p_days, 30), 1));
  v_supply numeric; v_horses numeric; v_humans numeric; v_top numeric; v_holders bigint;
  v_faucet numeric; v_sink numeric; v_arena numeric;
BEGIN
  SELECT COALESCE(sum(p.diamonds), 0),
         COALESCE(sum(p.diamonds) FILTER (WHERE p.is_horse), 0),
         COALESCE(sum(p.diamonds) FILTER (WHERE NOT p.is_horse), 0),
         count(*) FILTER (WHERE p.diamonds > 0)
    INTO v_supply, v_horses, v_humans, v_holders
    FROM public.profiles p;
  SELECT COALESCE(max(p.diamonds), 0) INTO v_top FROM public.profiles p WHERE NOT p.is_horse;

  -- ── supply and who holds it ──────────────────────────────────────────────
  RETURN QUERY SELECT 'supply'::text, 'total_diamonds'::text, v_supply,
    (SELECT public.fn_ca_mint_supply('diamonds'))::numeric,
    'value is sum(profiles.diamonds); comparison is the Mint register. They must be equal.'::text;
  RETURN QUERY SELECT 'supply'::text, 'holders'::text, v_holders::numeric, NULL::numeric,
    'accounts holding more than zero.'::text;
  RETURN QUERY SELECT 'holders'::text, 'horses'::text, v_horses,
    CASE WHEN v_supply > 0 THEN round(100 * v_horses / v_supply, 1) ELSE NULL END,
    'comparison is percent of all diamonds. Horses are players (CLAUDE.md 10.5); this is not a deduction, it is a fact about who is playing.'::text;
  RETURN QUERY SELECT 'holders'::text, 'humans'::text, v_humans,
    CASE WHEN v_supply > 0 THEN round(100 * v_humans / v_supply, 1) ELSE NULL END,
    'comparison is percent of all diamonds.'::text;
  RETURN QUERY SELECT 'concentration'::text, 'largest_human_holder'::text, v_top,
    CASE WHEN v_humans > 0 THEN round(100 * v_top / v_humans, 1) ELSE NULL END,
    'comparison is percent of all HUMAN diamonds held by one account. Above about 50 means the currency is one person''s.'::text;
  RETURN QUERY SELECT 'concentration'::text, 'humans_excluding_largest'::text,
    GREATEST(v_humans - v_top, 0),
    (SELECT count(*)::numeric FROM public.profiles p WHERE NOT p.is_horse AND p.diamonds > 0) - 1,
    'value is what every other human holds together; comparison is how many of them there are.'::text;

  -- ── faucets ──────────────────────────────────────────────────────────────
  RETURN QUERY
  SELECT 'faucet'::text,
         public.fn_ca_diamond_engine_of(dt.type, dt.transaction_type, dt.source, dt.description, dt.reference_id),
         COALESCE(sum(dt.amount), 0)::numeric, count(*)::numeric,
         'diamonds issued over the window by engine; comparison is the number of credits.'::text
    FROM public.diamond_transactions dt
   WHERE dt.amount > 0 AND dt.created_at >= v_from
     AND NOT public.fn_ca_is_fixture_account(dt.user_id)
   GROUP BY 2
   ORDER BY 3 DESC;

  -- ── sinks ────────────────────────────────────────────────────────────────
  RETURN QUERY
  SELECT 'sink'::text,
         COALESCE(NULLIF(btrim(dt.transaction_type), ''), NULLIF(btrim(dt.type), ''), 'unknown'),
         COALESCE(sum(-dt.amount), 0)::numeric, count(*)::numeric,
         'diamonds spent over the window by kind; comparison is the number of debits.'::text
    FROM public.diamond_transactions dt
   WHERE dt.amount < 0 AND dt.created_at >= v_from
     AND NOT public.fn_ca_is_fixture_account(dt.user_id)
   GROUP BY 2
   ORDER BY 3 DESC;

  SELECT COALESCE(sum(dt.amount) FILTER (WHERE dt.amount > 0), 0),
         COALESCE(sum(-dt.amount) FILTER (WHERE dt.amount < 0), 0)
    INTO v_faucet, v_sink
    FROM public.diamond_transactions dt
   WHERE dt.created_at >= v_from AND NOT public.fn_ca_is_fixture_account(dt.user_id);

  RETURN QUERY SELECT 'flow'::text, 'faucet_total'::text, v_faucet, NULL::numeric,
    'everything issued to players over the window.'::text;
  RETURN QUERY SELECT 'flow'::text, 'sink_total'::text, v_sink, NULL::numeric,
    'everything spent by players over the window.'::text;
  RETURN QUERY SELECT 'flow'::text, 'sink_player_total'::text,
    public.fn_ca_diamond_player_spend(v_from), v_sink - public.fn_ca_diamond_player_spend(v_from),
    'what players spent PLAYING; comparison is what the raw sink counted that this does not - admin adjustments and refunds, which are the house moving its own money.'::text;
  RETURN QUERY SELECT 'flow'::text, 'faucet_over_sink'::text,
    CASE WHEN public.fn_ca_diamond_player_spend(v_from) > 0
         THEN round(v_faucet / public.fn_ca_diamond_player_spend(v_from), 2) ELSE NULL END,
    v_faucet - public.fn_ca_diamond_player_spend(v_from),
    'THE HEALTH NUMBER: issuance divided by what players spent PLAYING, not by every debit. Measured against the raw sink it read 1.15 on 2026-09-08 while the true ratio was about 53, because five admin adjustments were 83 percent of the raw figure. Above 1 the currency inflates; comparison is the net added to supply.'::text;

  -- ── liabilities ──────────────────────────────────────────────────────────
  RETURN QUERY SELECT 'liability'::text, 'unclaimed_challenges'::text,
    (SELECT COALESCE(sum(u.diamond_reward_snapshot), 0)::numeric FROM public.user_daily_challenges u
      WHERE u.completed AND NOT u.claimed AND u.expired_at IS NULL),
    (SELECT count(*)::numeric FROM public.user_daily_challenges u
      WHERE u.completed AND NOT u.claimed AND u.expired_at IS NULL),
    'promised and not yet paid; expires seven days after completion (ruling 3). Comparison is the row count.'::text;
  RETURN QUERY SELECT 'liability'::text, 'purchased_outstanding'::text,
    (SELECT COALESCE(sum(l.issued - l.consumed - l.refunded), 0)::numeric FROM public.diamond_purchase_lots l
      WHERE (l.issued - l.consumed - l.refunded) > 0),
    (SELECT COALESCE(sum(d.amount), 0)::numeric FROM public.diamond_debts d WHERE d.settled_at IS NULL),
    'real customer money still in wallets; comparison is open receivables from reversed purchases (ruling 2).'::text;

  RETURN QUERY
  SELECT 'breakage'::text, b.bucket, b.outstanding, b.lots::numeric, b.note
    FROM public.fn_ca_diamond_breakage_aging() b;

  -- ── revenue ──────────────────────────────────────────────────────────────
  RETURN QUERY SELECT 'revenue'::text, 'lifetime_usd'::text,
    (SELECT COALESCE(sum(dp.price_usd), 0)::numeric FROM public.diamond_purchases dp WHERE dp.status = 'completed'),
    (SELECT count(*)::numeric FROM public.diamond_purchases dp WHERE dp.status = 'completed'),
    'every completed diamond purchase, ever; comparison is how many. This is the number the whole economy is meant to serve.'::text;
  RETURN QUERY SELECT 'revenue'::text, 'window_usd'::text,
    (SELECT COALESCE(sum(dp.price_usd), 0)::numeric FROM public.diamond_purchases dp
      WHERE dp.status = 'completed' AND dp.completed_at >= v_from),
    (SELECT count(*)::numeric FROM public.diamond_purchases dp
      WHERE dp.status = 'completed' AND dp.completed_at >= v_from),
    'purchases inside the window.'::text;

  -- ── the arena ────────────────────────────────────────────────────────────
  v_arena := public.fn_ca_diamond_offledger_float();
  RETURN QUERY SELECT 'arena'::text, 'diamonds_inside'::text, v_arena,
    CASE WHEN v_supply > 0 THEN round(100 * v_arena / v_supply, 1) ELSE NULL END,
    'held in the platform club''s member wallets; comparison is percent of supply. Zero until the arena club exists.'::text;
END $$;


ALTER FUNCTION public.fn_ca_diamond_economy(p_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_economy(p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_economy(p_days integer) IS 'The whole diamond economy in one read: supply, who holds it, faucets by engine, sinks by kind, the faucet-over-sink health number, liabilities, breakage by age, revenue, and the arena.';


--
-- Name: fn_ca_diamond_economy_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_economy_watch() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_conc numeric; v_ratio numeric; v_faucet numeric; v_sink_raw numeric; v_player numeric;
  v_top numeric; v_humans numeric; v_filed integer := 0;
  v_mode text := public.fn_ca_diamond_rule_mode('DR13:concentration_or_velocity');
  v_sev  text;
  -- CONCENTRATION, measured 2026-09-08: one human account (kingfish, role admin) held 494,445 of
  -- 566,246 human-held diamonds - 87.3 percent - with the next largest at 11,571. Fixtures are
  -- excluded here as they are from every flow metric. A band of 60 says "one account owns the
  -- currency" without firing on the ordinary case of a few large holders.
  c_concentration_pct constant numeric := 60;
  -- VELOCITY, re-derived 2026-09-08 against the definition that actually shipped. The comment
  -- this replaces cited player spending of 370 and a ratio near 50; both came from a definition
  -- superseded 162 seconds later and neither survived it. What the shipped definition returns
  -- over the same window is player spend 2,873 against a faucet of 20,283 - a ratio of 7.06. A
  -- band of 25 sits well above that and below anything that would count as the faucet running
  -- away. It is EXPECTED to fire once as the seven-day claim backlog settles, which is a real
  -- event and should be seen.
  c_ratio_max constant numeric := 25;
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;
  -- The mode is USED, not merely reported: flipping DR13 escalates what it files. There is
  -- nothing here to refuse - only somebody to tell, louder (D3).
  v_sev := CASE WHEN v_mode = 'refuse' THEN 'critical' ELSE 'warning' END;

  SELECT COALESCE(max(p.diamonds), 0), COALESCE(sum(p.diamonds), 0)
    INTO v_top, v_humans
    FROM public.profiles p
   WHERE NOT p.is_horse AND NOT public.fn_ca_is_fixture_account(p.id);
  v_conc := CASE WHEN v_humans > 0 THEN round(100 * v_top / v_humans, 1) ELSE 0 END;

  SELECT COALESCE(sum(dt.amount) FILTER (WHERE dt.amount > 0), 0),
         COALESCE(sum(-dt.amount) FILTER (WHERE dt.amount < 0), 0)
    INTO v_faucet, v_sink_raw
    FROM public.diamond_transactions dt
   WHERE dt.created_at >= now() - interval '30 days'
     AND NOT public.fn_ca_is_fixture_account(dt.user_id);
  v_player := public.fn_ca_diamond_player_spend(now() - interval '30 days');
  v_ratio := CASE WHEN v_player > 0 THEN round(v_faucet / v_player, 2) ELSE NULL END;

  -- At most one open incident per kind per day: both conditions are structural and would
  -- otherwise file on every call for ever, into the one table whose retention only removes
  -- RESOLVED rows (D4).
  IF v_conc > c_concentration_pct
     AND NOT EXISTS (SELECT 1 FROM public.ca_diamond_incidents i
                      WHERE i.rule = 'DR13:concentration_or_velocity'
                        AND i.detail ->> 'kind' = 'concentration'
                        AND i.resolved_at IS NULL
                        AND i.occurred_at > now() - interval '24 hours') THEN
    PERFORM public.fn_ca_diamond_incident('DR13:concentration_or_velocity', v_sev, NULL, v_top,
      'fn_ca_diamond_economy_watch',
      jsonb_build_object('kind', 'concentration', 'largest_human_pct', v_conc,
                         'threshold_pct', c_concentration_pct, 'largest_holder_diamonds', v_top,
                         'all_human_diamonds', v_humans,
                         'note', 'One account holds most of the human-held currency. Not a defect: a fact about the economy that should be seen. Filed at most once a day.'));
    v_filed := v_filed + 1;
  END IF;

  IF v_ratio IS NOT NULL AND v_ratio > c_ratio_max
     AND NOT EXISTS (SELECT 1 FROM public.ca_diamond_incidents i
                      WHERE i.rule = 'DR13:concentration_or_velocity'
                        AND i.detail ->> 'kind' = 'velocity'
                        AND i.resolved_at IS NULL
                        AND i.occurred_at > now() - interval '24 hours') THEN
    PERFORM public.fn_ca_diamond_incident('DR13:concentration_or_velocity', v_sev, NULL, v_faucet - v_player,
      'fn_ca_diamond_economy_watch',
      jsonb_build_object('kind', 'velocity', 'faucet_over_player_spend', v_ratio, 'threshold', c_ratio_max,
                         'faucet_30d', v_faucet, 'player_spend_30d', v_player, 'sink_total_30d', v_sink_raw,
                         'note', 'Issuance is outrunning what players spend playing. The levers are the per-user daily caps and what diamonds can be spent on; both are Dan''s.'));
    v_filed := v_filed + 1;
  END IF;

  -- Each figure under its own name (D6): sink_30d used to carry player spend.
  RETURN jsonb_build_object('ok', true, 'concentration_pct', v_conc, 'faucet_over_sink', v_ratio,
                            'faucet_30d', v_faucet, 'player_spend_30d', v_player,
                            'sink_total_30d', v_sink_raw, 'incidents_filed', v_filed, 'mode', v_mode,
                            'severity_when_filed', v_sev);
END $$;


ALTER FUNCTION public.fn_ca_diamond_economy_watch() OWNER TO postgres;

--
-- Name: fn_ca_diamond_engine_of(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_engine_of(p_type text, p_transaction_type text, p_source text, p_description text, p_reference_id text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT CASE
        WHEN starts_with(p_reference_id, 'ca_daily_bonus:')   THEN 'club_arena_daily'
        WHEN starts_with(p_reference_id, 'wheel:')            THEN 'wheel'
        WHEN starts_with(p_reference_id, 'trivia_tourn_')     THEN 'trivia_tournaments'
        WHEN starts_with(p_reference_id, 'trivia_session_')   THEN 'trivia'
        WHEN starts_with(p_reference_id, 'trivia_wheel_')     THEN 'trivia'
        WHEN starts_with(p_reference_id, 'challenge_claim')   THEN 'daily_challenges'
        WHEN starts_with(p_reference_id, 'daily_mission_milestones:') THEN 'daily_missions'
        WHEN starts_with(p_reference_id, 'daily-missions-historical-multiplier:') THEN 'daily_missions'
        WHEN starts_with(p_reference_id, 'daily_mission_')    THEN 'daily_missions'
        WHEN starts_with(p_reference_id, 'streak_milestone_') THEN 'share_streak'
        WHEN starts_with(p_reference_id, 'streak_')           THEN 'catalog_v2'
        WHEN starts_with(p_reference_id, 'signup:')           THEN 'signup'
        WHEN starts_with(p_reference_id, 'easter_egg_')       THEN 'catalog_v2'
        WHEN starts_with(p_reference_id, 'video_favorite_')   THEN 'catalog_v2'
        WHEN starts_with(p_reference_id, 'vip_stipend_')      THEN 'catalog_v2'
        WHEN starts_with(p_reference_id, 'hotd_')             THEN 'catalog_v2'
        WHEN starts_with(p_reference_id, 'progress_')         THEN 'catalog_v2'
        WHEN starts_with(p_reference_id, 'customization-cert-fund') THEN 'cert_fixture'
        WHEN p_source = 'complete_daily_challenge' THEN 'memory_game'
        WHEN p_source = 'handle_new_user'          THEN 'signup'
        WHEN p_source = 'union'                    THEN 'union_grant'
        WHEN p_source = 'the_mint'                 THEN 'mint'
        WHEN COALESCE(p_transaction_type, p_type) IN ('wheel_prize', 'wheel_spin') THEN 'wheel'
        WHEN COALESCE(p_transaction_type, p_type) IN (
                'referral_bonus', 'referral_bonus_reversal', 'referral_qualified',
                'referral_referee', 'referral_vip_conversion',
                'referral_milestone', 'referral_reward')                    THEN 'referrals'
        WHEN COALESCE(p_transaction_type, p_type) = 'signup_bonus'         THEN 'signup'
        WHEN COALESCE(p_transaction_type, p_type) = 'union_grant'          THEN 'union_grant'
        WHEN COALESCE(p_transaction_type, p_type) IN (
                'pvp_refund', 'pvp_win', 'pvp_tie_refund', 'trivia_run',
                'trivia_daily_bonus', 'daily_trivia', 'trivia_reward',
                'trivia_prize_wheel', 'endless_reward', 'survival_reward',
                'mixed_reward', 'time_attack_reward', 'trivia_double_win')  THEN 'trivia'
        WHEN COALESCE(p_transaction_type, p_type) IN (
                'tournament_prize', 'tournament_entry_refund',
                'tournament_cancel_refund')                                THEN 'trivia_tournaments'
        WHEN COALESCE(p_transaction_type, p_type) IN ('daily_challenge_claim') THEN 'daily_challenges'
        WHEN COALESCE(p_transaction_type, p_type) IN ('daily_mission_milestone', 'daily_mission_reward') THEN 'daily_missions'
        WHEN COALESCE(p_transaction_type, p_type) = 'streak_reward'        THEN 'share_streak'
        WHEN COALESCE(p_transaction_type, p_type) IN (
                'daily_login', 'easter_egg', 'training_reward',
                'video_favorite', 'vip_stipend')                           THEN 'catalog_v2'
        WHEN COALESCE(p_transaction_type, p_type) IN ('credit', 'earn', 'bonus') THEN 'legacy_credit'
        WHEN p_description LIKE 'Diamond Rewards v2:%'                      THEN 'catalog_v2'
        ELSE 'other'
    END;
$$;


ALTER FUNCTION public.fn_ca_diamond_engine_of(p_type text, p_transaction_type text, p_source text, p_description text, p_reference_id text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_engine_of(p_type text, p_transaction_type text, p_source text, p_description text, p_reference_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_engine_of(p_type text, p_transaction_type text, p_source text, p_description text, p_reference_id text) IS 'Classifies a diamond journal row into its earning engine for the budget ledger. Prefix branches come first; keep every one of them when redefining (the ca_daily_bonus: prefix files the Daily Club Arena Bonus under club_arena_daily).';


--
-- Name: fn_ca_diamond_engine_spent(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_engine_spent(p_period text, p_engine text) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The frozen baseline plus everything appended since. One number, one definition, read by the
  -- rule and by the report alike.
  SELECT COALESCE((SELECT b.spent_diamonds FROM public.diamond_reward_budgets b
                    WHERE b.period = p_period AND b.engine = p_engine), 0)
       + COALESCE((SELECT SUM(s.amount) FROM public.ca_diamond_engine_spend s
                    WHERE s.period = p_period AND s.engine = p_engine), 0);
$$;


ALTER FUNCTION public.fn_ca_diamond_engine_spent(p_period text, p_engine text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_engine_spent(p_period text, p_engine text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_engine_spent(p_period text, p_engine text) IS 'What an engine has spent in a period: the frozen diamond_reward_budgets.spent_diamonds baseline plus the append-only rows in ca_diamond_engine_spend.';


--
-- Name: fn_ca_diamond_flip_forecast(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_flip_forecast(p_hours integer DEFAULT 24) RETURNS TABLE(rule text, mode text, arms_on date, would_refuse bigint, since_config bigint, players_hit bigint, diamonds numeric, last_seen timestamp with time zone, config_at timestamp with time zone, verdict text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_since timestamptz := now() - make_interval(hours => GREATEST(COALESCE(p_hours, 24), 1));
        v_blind bigint; v_blind_new timestamptz; v_caps timestamptz;
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  -- DR7:user_over_daily_cap is the one rule whose behaviour is set by a SECOND table: change a row
  -- in diamond_engine_daily_caps and the rule refuses differently without its own row moving. Every
  -- other rule's configuration is its own row.
  SELECT max(updated_at) INTO v_caps FROM public.diamond_engine_daily_caps;

  RETURN QUERY
  WITH cfg AS (
    SELECT m.rule AS r, m.mode AS md, m.flip_after AS fa,
           GREATEST(m.updated_at,
                    CASE WHEN m.rule = 'DR7:user_over_daily_cap' THEN v_caps ELSE m.updated_at END)
             AS epoch
      FROM public.ca_diamond_rule_modes m)
  SELECT c.r, c.md, c.fa::date,
         count(i.id),
         count(i.id) FILTER (WHERE i.occurred_at >= c.epoch),
         count(DISTINCT i.user_id),
         COALESCE(sum(abs(i.amount)), 0)::numeric,
         max(i.occurred_at),
         c.epoch,
         CASE
           WHEN c.md = 'refuse' THEN
             'ALREADY ARMED. It is refusing now; the count is what it has refused.'
           WHEN count(i.id) = 0 THEN
             'SAFE TO ARM. Nothing in the window would have been refused.'
           -- The configuration moved inside the window, so the older incidents describe a rule that
           -- no longer exists in that form. Say so rather than reporting a total that mixes both.
           WHEN c.epoch > v_since AND count(i.id) FILTER (WHERE i.occurred_at >= c.epoch) = 0 THEN
             'SAFE TO ARM SINCE THE CONFIGURATION CHANGED at ' || to_char(c.epoch, 'YYYY-MM-DD HH24:MI')
             || '. The ' || count(i.id) || ' in the window all predate it and describe the old setting.'
           WHEN c.epoch > v_since THEN
             'WOULD REFUSE ' || count(i.id) FILTER (WHERE i.occurred_at >= c.epoch)
             || ' SINCE THE CONFIGURATION CHANGED at ' || to_char(c.epoch, 'YYYY-MM-DD HH24:MI')
             || ' (' || count(i.id) || ' in the whole window). Read the first number.'
           WHEN c.fa IS NOT NULL AND c.fa <= now() THEN 'OVERDUE AND LOUD. Its date has passed, it is still logging, and it would refuse ' || count(i.id) || ' movement(s) affecting ' || count(DISTINCT i.user_id) || ' player(s).' WHEN max(i.occurred_at) < now() - interval '3 hours' THEN
             'PROBABLY FIXED ALREADY. ' || count(i.id) || ' in the window, but the most recent was '
             || to_char(now() - max(i.occurred_at), 'HH24:MI') || ' ago and nothing since. Re-read '
             || 'over a shorter window before acting.'
           WHEN c.fa IS NULL THEN
             'WOULD REFUSE ' || count(i.id) || ' - no arming date set, so this is advisory only.'
           WHEN c.fa <= now() THEN
             'OVERDUE AND LOUD. Its date has passed, it is still logging, and it would refuse '
             || count(i.id) || ' movement(s) affecting ' || count(DISTINCT i.user_id) || ' player(s).'
           ELSE
             'WOULD REFUSE ' || count(i.id) || ' movement(s) worth ' || COALESCE(sum(abs(i.amount)), 0)
             || ' diamonds across ' || count(DISTINCT i.user_id) || ' player(s), most recent '
             || to_char(now() - max(i.occurred_at), 'HH24:MI') || ' ago, starting in '
             || (c.fa::date - now()::date) || ' day(s). Read this before that date.'
         END
    FROM cfg c
    LEFT JOIN public.ca_diamond_incidents i ON i.rule = c.r AND i.occurred_at >= v_since
   GROUP BY c.r, c.md, c.fa, c.epoch;

  RETURN QUERY
  SELECT x.rule, 'retired'::text, NULL::date,
         count(*), count(*), count(DISTINCT x.user_id), COALESCE(sum(abs(x.amount)), 0)::numeric,
         max(x.occurred_at), NULL::timestamptz,
         'RETIRED RULE, ' || count(*) || ' incident(s) still in the window. It refuses nothing and '
         || 'arms on no date. The rows are history and stay; nothing acts on them.'
    FROM public.ca_diamond_incidents x
   WHERE x.occurred_at >= v_since
     AND x.rule NOT LIKE 'DR0:%'
     AND NOT EXISTS (SELECT 1 FROM public.ca_diamond_rule_modes m WHERE m.rule = x.rule)
   GROUP BY x.rule;

  SELECT count(*), max(x.occurred_at) INTO v_blind, v_blind_new
    FROM public.ca_diamond_incidents x
   WHERE x.rule = 'DR7:ledger_write_failed' AND x.occurred_at >= v_since;
  RETURN QUERY SELECT
    '(forecast confidence)'::text,
    CASE WHEN v_blind = 0 THEN 'complete' ELSE 'incomplete' END::text,
    NULL::date, v_blind, v_blind, 0::bigint, 0::numeric, v_blind_new, NULL::timestamptz,
    CASE WHEN v_blind = 0
         THEN 'Every award in the window was evaluated, so the counts above are totals.'
         ELSE v_blind || ' award(s) could not be evaluated at all because the ledger write failed, '
              || 'most recent ' || to_char(now() - v_blind_new, 'HH24:MI') || ' ago. Every count '
              || 'above is a FLOOR, not a total.'
    END;
END $$;


ALTER FUNCTION public.fn_ca_diamond_flip_forecast(p_hours integer) OWNER TO postgres;

--
-- Name: fn_ca_diamond_health(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_health() RETURNS TABLE(area text, status text, detail text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_n bigint; v_h bigint; v_m numeric; v_t text; v_e text;
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  -- EVERY AREA IS WRAPPED. The previous version called eight external functions with no handler,
  -- so one raise anywhere returned ZERO ROWS rather than twelve answers and one unknown - a report
  -- that vanishes rather than admitting what it could not read (CLAUDE.md 10.86 rule 1).

  -- A JOB IS NOT ALIVE BECAUSE IT IS SCHEDULED. This read cron.job.active alone, so a job failing
  -- on every run for a week reported ok. Same shape as 10.84's "a rule is not live because it
  -- merged". It reads job_run_details now.
  BEGIN
    SELECT count(*) FILTER (WHERE d.status = 'succeeded' AND d.end_time >= now() - interval '25 hours')
      INTO v_n
      FROM cron.job j LEFT JOIN cron.job_run_details d ON d.jobid = j.jobid
     WHERE j.jobname = 'ca-diamond-rule-flip-daily' AND j.active;
    RETURN QUERY SELECT 'rule arming'::text,
      CASE WHEN NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'ca-diamond-rule-flip-daily' AND active)
             THEN 'critical'
           WHEN v_n > 0 THEN 'ok' ELSE 'attention' END,
      CASE WHEN NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'ca-diamond-rule-flip-daily' AND active)
             THEN 'NOTHING ARMS THE RULES. Every flip_after date will pass unremarked.'
           WHEN v_n > 0 THEN 'ca-diamond-rule-flip-daily is scheduled and has succeeded in the last 25 hours.'
           ELSE 'ca-diamond-rule-flip-daily is scheduled but has not succeeded in 25 hours. '
                || 'Scheduled is not running.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'rule arming'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  BEGIN
    SELECT count(*) FILTER (WHERE d.status = 'succeeded' AND d.end_time >= now() - interval '10 minutes')
      INTO v_n
      FROM cron.job j LEFT JOIN cron.job_run_details d ON d.jobid = j.jobid
     WHERE j.jobname = 'ca-horse-claim-due-minute' AND j.active;
    RETURN QUERY SELECT 'horse claim button'::text,
      CASE WHEN NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'ca-horse-claim-due-minute' AND active)
             THEN 'critical'
           WHEN v_n > 0 THEN 'ok' ELSE 'critical' END,
      CASE WHEN NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'ca-horse-claim-due-minute' AND active)
             THEN 'NOTHING PRESSES A HORSE''S CLAIM BUTTON. Every horse reward will expire unclaimed.'
           WHEN v_n > 0 THEN 'ca-horse-claim-due-minute has succeeded ' || v_n || ' time(s) in ten minutes.'
           ELSE 'ca-horse-claim-due-minute is scheduled but has not succeeded in ten minutes, and it '
                || 'runs every minute. Horse rewards are accumulating toward expiry.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'horse claim button'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  -- THE NUMBER THAT MUST NEVER BE NON-ZERO, and nothing was watching it. A reward that expires
  -- unclaimed leaves the `horse claims` count, so that area would have gone GREEN at the exact
  -- moment the diamonds were lost.
  --
  -- IT EXCLUDES RULING 3's BACKLOG BY REFERENCE, NOT BY A DATE. 4,703 rows (4,674 horse + 29 human,
  -- 159,275 diamonds) expired at 2026-09-08 03:11 under Dan's ruling - "no retroactive mint into
  -- idle wallets, humans and horses treated alike" - and they are NOT owed. A plain 36-hour window
  -- flagged them as a critical defect the moment this area was written, which is how a new alarm
  -- teaches people to ignore it on day one. The bound reads the recorded write-off's own timestamp,
  -- so it needs no magic date and retires itself once the window moves past it.
  BEGIN
    SELECT count(*) FILTER (WHERE p.is_horse), COALESCE(sum(u.diamond_reward_snapshot) FILTER (WHERE p.is_horse), 0)
      INTO v_h, v_m
      FROM public.user_daily_challenges u JOIN public.profiles p ON p.id = u.user_id
     WHERE u.expired_at IS NOT NULL AND NOT u.claimed
       AND u.expired_at >= now() - interval '36 hours'
       AND u.expired_at > COALESCE((SELECT max(i.occurred_at) FROM public.ca_diamond_incidents i
                                     WHERE i.rule = 'DR0:ruling_3_backlog_expired'), '-infinity'::timestamptz);
    RETURN QUERY SELECT 'rewards lost to expiry'::text,
      CASE WHEN v_h = 0 THEN 'ok' ELSE 'critical' END,
      CASE WHEN v_h = 0 THEN 'No horse reward expired unclaimed in the last 36 hours.'
           ELSE v_h || ' horse reward(s) worth ' || v_m || ' diamonds expired UNCLAIMED in the last '
                || '36 hours. Something was owed and nothing paid it before the clock ran out.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'rewards lost to expiry'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  BEGIN
    SELECT count(*) FILTER (WHERE p.is_horse), count(*) FILTER (WHERE NOT COALESCE(p.is_horse, false))
      INTO v_h, v_n
      FROM public.user_daily_challenges u JOIN public.profiles p ON p.id = u.user_id
     WHERE u.completed AND NOT u.claimed AND u.expired_at IS NULL
       AND u.completed_at >= now() - interval '7 days'
       AND u.completed_at < now() - interval '5 minutes';
    RETURN QUERY SELECT 'horse claims'::text,
      CASE WHEN v_h = 0 THEN 'ok' WHEN v_h < 50 THEN 'attention' ELSE 'critical' END,
      CASE WHEN v_h = 0
           THEN 'No horse is owed a reward it cannot claim. ' || v_n || ' human reward(s) are '
                || 'unclaimed, which is a person choosing not to press a button, not a defect.'
           ELSE v_h || ' horse reward(s) are owed past the sweep interval; nothing but '
                || 'fn_ca_horse_claim_due presses a horse''s button.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'horse claims'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  BEGIN
    SELECT count(*) INTO v_n FROM public.fn_ca_diamond_rule_flip_due(true) x
      JOIN public.ca_diamond_rule_modes m ON m.rule = x.rule
     WHERE x.action IN ('blocked', 'unknown') AND m.flip_after IS NOT NULL AND m.flip_after <= now();
    RETURN QUERY SELECT 'rules overdue'::text,
      CASE WHEN v_n = 0 THEN 'ok' ELSE 'attention' END,
      CASE WHEN v_n = 0 THEN 'No rule is past its arming date and still stuck.'
           ELSE v_n || ' rule(s) are past their arming date and cannot arm; read '
                || 'fn_ca_diamond_rule_flip_due(true) for each reason.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'rules overdue'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  BEGIN
    v_m := (SELECT public.fn_ca_mint_supply('diamonds'))
           - ((SELECT COALESCE(sum(diamonds), 0) FROM public.profiles) + public.fn_ca_diamond_offledger_float());
    RETURN QUERY SELECT 'money identity'::text,
      CASE WHEN v_m = 0 THEN 'ok' ELSE 'critical' END,
      CASE WHEN v_m = 0 THEN 'players + float = register, exactly.'
           ELSE 'players + float differs from the register by ' || v_m || '.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'money identity'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  -- READS THE STORED SNAPSHOT; NEVER TAKES ONE. fn_ca_diamond_snapshot() is VOLATILE and INSERTs,
  -- so the previous version advanced the baseline it was reporting against - 25 snapshots in eight
  -- hours where 8 belonged to the hourly cron, one timestamp repeated seven times. The instrument
  -- destroyed the series it existed to read, and STABLE was a lie.
  BEGIN
    SELECT s.unexplained, s.taken_at::text INTO v_m, v_t
      FROM public.ca_diamond_snapshots s ORDER BY s.taken_at DESC LIMIT 1;
    RETURN QUERY SELECT 'deploy gate'::text,
      CASE WHEN v_t IS NULL THEN 'unknown'
           WHEN v_t::timestamptz < now() - interval '3 hours' THEN 'attention'
           WHEN COALESCE(v_m, -1) = 0 THEN 'ok' ELSE 'critical' END,
      CASE WHEN v_t IS NULL THEN 'no snapshot has ever been taken; ca-diamond-snapshot-hourly may not be running'
           WHEN v_t::timestamptz < now() - interval '3 hours'
             THEN 'the newest snapshot is from ' || v_t || ', over three hours old - the hourly job is not running'
           WHEN COALESCE(v_m, -1) = 0 THEN 'The snapshot at ' || v_t || ' explains every movement.'
           ELSE COALESCE(v_m::text, 'NULL') || ' unexplained at the snapshot taken ' || v_t || '.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'deploy gate'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  BEGIN
    SELECT count(*) INTO v_n FROM public.fn_ca_diamond_trial_balance() x
     WHERE x.difference IS NOT NULL AND x.difference <> 0;
    RETURN QUERY SELECT 'trial balance'::text,
      CASE WHEN v_n = 0 THEN 'ok' ELSE 'critical' END,
      CASE WHEN v_n = 0 THEN 'Every reconciling account balances against the journal.'
           ELSE v_n || ' account(s) do not reconcile.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'trial balance'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  BEGIN
    SELECT COALESCE(sum(x.would_refuse), 0) INTO v_n FROM public.fn_ca_diamond_cap_headroom(14) x;
    RETURN QUERY SELECT 'per-user caps'::text,
      CASE WHEN v_n = 0 THEN 'ok' ELSE 'attention' END,
      CASE WHEN v_n = 0 THEN 'No real user-day in fourteen days exceeds the cap that applies to it.'
           ELSE v_n || ' user-day(s) exceed the cap that applies to them.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'per-user caps'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  BEGIN
    SELECT count(*) INTO v_n FROM public.diamond_engine_daily_caps
     WHERE max_per_user_per_day_vip IS NOT NULL AND max_per_user_per_day IS NOT NULL
       AND max_per_user_per_day_vip < max_per_user_per_day;
    RETURN QUERY SELECT 'VIP caps'::text,
      CASE WHEN v_n = 0 THEN 'ok' ELSE 'attention' END,
      CASE WHEN v_n = 0 THEN 'No cap gives a VIP less than a standard player receives.'
           ELSE v_n || ' cap(s) make VIP a downgrade.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'VIP caps'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  BEGIN
    SELECT count(*) INTO v_n FROM public.profiles p
     WHERE p.is_horse AND (public.fn_ca_is_cert_account(p.id) OR public.fn_ca_is_fixture_account(p.id));
    RETURN QUERY SELECT 'horses are players'::text,
      CASE WHEN v_n = 0 THEN 'ok' ELSE 'critical' END,
      CASE WHEN v_n = 0 THEN 'No horse is classified as test equipment.'
           ELSE v_n || ' horse(s) read as harness equipment.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'horses are players'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  BEGIN
    SELECT count(*) INTO v_n FROM public.fn_ca_diamond_budget_reality() x
     WHERE x.verdict LIKE 'ALREADY OVER%' OR x.verdict LIKE 'FUTURE PLAN BELOW%' OR x.verdict LIKE 'BUDGETED ZERO%';
    RETURN QUERY SELECT 'budget plans'::text,
      CASE WHEN v_n = 0 THEN 'ok' ELSE 'attention' END,
      CASE WHEN v_n = 0 THEN 'Every reward budget is plausible against actual issuance.'
           ELSE v_n || ' budget line(s) are fiction. They refuse nobody (ruling 21); setting them is Dan''s.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'budget plans'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  BEGIN
    SELECT count(*) INTO v_n FROM public.fn_ca_diamond_unreachable_money();
    RETURN QUERY SELECT 'unreachable money'::text,
      CASE WHEN v_n = 0 THEN 'ok' ELSE 'attention' END,
      CASE WHEN v_n = 0 THEN 'No diamonds are stranded where nothing can reach them.'
           ELSE v_n || ' finding(s); read fn_ca_diamond_unreachable_money().' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'unreachable money'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;

  BEGIN
    SELECT count(*), max(i.occurred_at)::text INTO v_n, v_t
      FROM public.ca_diamond_incidents i
     WHERE i.rule = 'DR7:ledger_write_failed' AND i.occurred_at >= now() - interval '24 hours';
    RETURN QUERY SELECT 'evaluation coverage'::text,
      CASE WHEN COALESCE(v_n, 0) = 0 THEN 'ok'
           WHEN v_t::timestamptz >= now() - interval '1 hour' THEN 'critical'
           ELSE 'attention' END,
      CASE WHEN COALESCE(v_n, 0) = 0
           THEN 'Every award in the last 24 hours was evaluated by the rules.'
           WHEN v_t::timestamptz >= now() - interval '1 hour'
           THEN v_n || ' award(s) could not be evaluated and it is STILL HAPPENING (most recent '
                || to_char(now() - v_t::timestamptz, 'HH24:MI') || ' ago).'
           ELSE v_n || ' award(s) could not be evaluated in 24 hours, but none for '
                || to_char(now() - v_t::timestamptz, 'HH24:MI') || '; the cause appears fixed.' END;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_e = MESSAGE_TEXT;
    RETURN QUERY SELECT 'evaluation coverage'::text, 'unknown'::text, 'could not be read: ' || v_e;
  END;
END $$;


ALTER FUNCTION public.fn_ca_diamond_health() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_health(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_health() IS 'One call over the diamond economy: eleven areas, each with ok/attention/critical and a sentence. Exists because there are 28 fn_ca_diamond_*/fn_ca_mint_* reporting functions and a person has to know which to read - which is how "nothing arms the rules" survived a week of daily review. Its first row is whether the flip has a hand.';


--
-- Name: fn_ca_diamond_health_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_health_watch() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_bad integer; v_detail jsonb;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND current_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'fn_ca_diamond_health_watch: service_role required';
  END IF;

  -- `unknown` counts as bad. An area that could not be read is not an area that is fine, and the
  -- whole point of giving health an `unknown` status was that somebody would act on it.
  SELECT count(*), COALESCE(jsonb_agg(jsonb_build_object('area', h.area, 'status', h.status, 'detail', h.detail)), '[]'::jsonb)
    INTO v_bad, v_detail
    FROM public.fn_ca_diamond_health() h
   WHERE h.status IN ('critical', 'unknown');

  IF v_bad > 0 THEN
    PERFORM public.fn_ca_diamond_incident(
      'DR0:health_critical', 'critical', NULL, NULL, 'fn_ca_diamond_health_watch',
      jsonb_build_object('areas', v_bad, 'detail', v_detail));
  END IF;

  RETURN v_bad;
END $$;


ALTER FUNCTION public.fn_ca_diamond_health_watch() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_health_watch(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_health_watch() IS 'Reads fn_ca_diamond_health and files a CRITICAL incident naming every area that is critical or unknown. Exists because the health report had NO reader - 0 cron callers, no application caller - which is the same defect as nine rules whose arming function nothing called. Files only on critical/unknown, never on attention, so it does not become an always-on alarm on the two areas that are amber by decision.';


--
-- Name: fn_ca_diamond_incident(text, text, uuid, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_incident(p_rule text, p_severity text, p_user_id uuid, p_amount numeric, p_writer text, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_sev text := COALESCE(p_severity, 'info');
BEGIN
  -- Fixture accounts are not players (docs/DIAMOND-RULINGS.md): a rule filed against one is info
  -- unless it is critical. Horses are players and are never fixtures.
  IF v_sev <> 'critical' AND p_user_id IS NOT NULL AND public.fn_ca_is_fixture_account(p_user_id) THEN
    v_sev := 'info';
  END IF;
  INSERT INTO public.ca_diamond_incidents (rule, severity, user_id, amount, writer, detail)
  VALUES (p_rule, v_sev, p_user_id, p_amount, p_writer,
          COALESCE(p_detail, '{}'::jsonb) || CASE WHEN v_sev <> COALESCE(p_severity, 'info')
                                                  THEN jsonb_build_object('severity_requested', p_severity, 'fixture_account', true)
                                                  ELSE '{}'::jsonb END);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_ca_diamond_incident could not record % (%): %', p_rule, p_writer, SQLERRM;
END;
$$;


ALTER FUNCTION public.fn_ca_diamond_incident(p_rule text, p_severity text, p_user_id uuid, p_amount numeric, p_writer text, p_detail jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_incident(p_rule text, p_severity text, p_user_id uuid, p_amount numeric, p_writer text, p_detail jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_incident(p_rule text, p_severity text, p_user_id uuid, p_amount numeric, p_writer text, p_detail jsonb) IS 'Records a diamond standard incident. Never raises, never blocks. Called by log-only rules.';


--
-- Name: fn_ca_diamond_journal_classifier(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_journal_classifier() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_type text := COALESCE(NEW.transaction_type, NEW.type, 'unknown');
  v_stack text; v_writer text; v_filled boolean := false;
BEGIN
  IF NEW.issuance_class IS NULL THEN
    v_filled := true;
    NEW.issuance_class := CASE
      WHEN v_type = 'purchase' THEN 'purchased'
      WHEN v_type = 'refund' OR right(v_type, 7) = '_refund' THEN 'refund'
      WHEN v_type IN ('transfer', 'diamond_gift_received', 'live_gift_received', 'diamond_received',
                      'diamond_gift_sent', 'live_gift_sent', 'spend_transfer') THEN 'transferred'
      WHEN v_type = 'adjustment' THEN 'admin'
      WHEN v_type = 'mint' THEN 'admin'
      WHEN v_type = 'burn' THEN 'deletion'
      WHEN v_type IN ('union_grant', 'signup_bonus') THEN 'promotional'
      WHEN COALESCE(NEW.amount, 0) < 0 THEN 'spend'
      WHEN EXISTS (SELECT 1 FROM public.diamond_reward_catalog c WHERE c.action_key = v_type)
           OR COALESCE(NEW.description, '') LIKE 'Diamond Rewards v2:%' THEN 'promotional'
      ELSE 'earned'
    END;
  END IF;
  IF NEW.counterparty IS NULL THEN
    v_filled := true;
    NEW.counterparty := CASE NEW.issuance_class
      WHEN 'purchased' THEN 'purchase_clearing'
      WHEN 'refund' THEN CASE WHEN v_type IN ('refund', 'stripe') THEN 'purchase_clearing' ELSE 'revenue:' || v_type END
      WHEN 'transferred' THEN 'player:' || COALESCE(NEW.metadata->>'recipient_id', NEW.metadata->>'sender_id', 'unknown')
      WHEN 'admin' THEN 'adjustment'
      WHEN 'deletion' THEN 'retired'
      WHEN 'spend' THEN 'revenue:' || v_type
      ELSE 'promo_budget:' || public.fn_ca_diamond_engine_of(NEW.type, NEW.transaction_type, NEW.source, NEW.description, NEW.reference_id)
    END;
  END IF;
  IF v_filled THEN
    BEGIN
      GET DIAGNOSTICS v_stack = PG_CONTEXT;
      SELECT (regexp_match(t.ln, 'function (?:public\.)?([A-Za-z0-9_]+)\('))[1] INTO v_writer
        FROM regexp_split_to_table(COALESCE(v_stack, ''), E'\n') WITH ORDINALITY AS t(ln, ord)
       WHERE t.ln ~ 'function (?:public\.)?[A-Za-z0-9_]+\('
         AND (regexp_match(t.ln, 'function (?:public\.)?([A-Za-z0-9_]+)\('))[1] <> 'fn_ca_diamond_journal_classifier'
       ORDER BY t.ord LIMIT 1;
      PERFORM public.fn_ca_diamond_incident(
        'DR12:journal_row_unclassified_by_writer', 'info', NEW.user_id, NEW.amount,
        COALESCE(v_writer, '(no function frame)'),
        jsonb_build_object('type', NEW.type, 'transaction_type', NEW.transaction_type,
                           'description', left(NEW.description, 120), 'reference_id', NEW.reference_id,
                           'classified_as', NEW.issuance_class, 'counterparty', NEW.counterparty,
                           'note', 'the writer left issuance_class or counterparty NULL; the classifier filled them. Fix the writer.'));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_diamond_journal_classifier() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_journal_classifier(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_journal_classifier() IS 'DR3 safety net: fills issuance_class and counterparty when a writer leaves them NULL and files DR12 naming the writer. Standard 3.3.';


--
-- Name: fn_ca_diamond_journal_origin(text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_journal_origin(p_type text, p_transaction_type text, p_source text, p_issuance_class text, p_amount numeric) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_kind  text := lower(COALESCE(NULLIF(btrim(p_transaction_type), ''), NULLIF(btrim(p_type), ''), ''));
  v_class text := lower(COALESCE(NULLIF(btrim(p_issuance_class), ''), ''));
  v_src   text := lower(COALESCE(NULLIF(btrim(p_source), ''), ''));
BEGIN
  IF p_amount IS NULL OR p_amount = 0 THEN RETURN NULL; END IF;
  -- The Mint's own doors register their own rows.
  IF v_src = 'the_mint' THEN RETURN NULL; END IF;
  -- SO DOES THE SEED DOOR. fn_ca_diamond_born_with_balance writes the
  -- 'seed:<id>' register row for the signup grant and then the journal row.
  -- Registering it here as well counts one movement twice (2026-09-05: 18
  -- duplicate pairs, 9,000 diamonds). Named writer, not a class: every OTHER
  -- promotional credit still registers here.
  IF v_kind = 'signup_bonus' OR v_src = 'handle_new_user' THEN RETURN NULL; END IF;
  -- Player to player: supply moves, none is created or retired.
  IF v_class = 'transferred'
     OR v_kind IN ('transfer', 'diamond_gift_sent', 'diamond_gift_received', 'diamond_received',
                   'live_gift_sent', 'live_gift_received', 'wallet_transfer',
                   'wallet_diamond_transfer', 'stream_gift', 'union_grant_transfer')
     OR v_kind LIKE '%gift%' OR v_kind LIKE '%transfer%' THEN
    RETURN NULL;
  END IF;
  -- THE ARENA DOORS MOVE MONEY, THEY DO NOT ISSUE IT. A deposit takes diamonds out of
  -- profiles.diamonds and puts them in the platform club's member wallet; a withdrawal is the
  -- mirror. The player still owns them and the supply is unchanged, so the register must not
  -- follow either leg - the same treatment, for the same reason, as a player-to-player transfer
  -- above. Classified as 'spend' (deposit) and 'arena' (withdrawal), the register would have
  -- burned the float on the way in and minted it on the way out (2026-09-08).
  IF v_kind IN ('arena_deposit', 'arena_withdraw') THEN RETURN NULL; END IF;
  -- The deletion door writes its own register row.
  IF v_class = 'deletion' THEN RETURN NULL; END IF;
  -- A test fixture row is not supply the Mint issued.
  IF v_kind LIKE 'test%' THEN RETURN NULL; END IF;

  IF p_amount > 0 THEN
    IF v_class = 'purchased' OR v_kind IN ('purchase', 'stripe_purchase', 'diamond_purchase') THEN
      RETURN 'purchase';
    ELSIF v_class = 'refund' OR v_kind LIKE '%refund%' OR v_kind = 'diamond_refund' THEN
      RETURN 'refund';
    ELSIF v_class = 'promotional' OR v_kind IN ('union_grant', 'bonus', 'promo',
                                                 'promo_purchased', 'easter_egg', 'vip_daily',
                                                 'vip_stipend', 'vip_monthly') THEN
      RETURN 'promotion';
    ELSIF v_class = 'admin' OR v_kind IN ('adjustment', 'reconciliation', 'admin', 'admin_grant') THEN
      RETURN 'adjustment';
    -- 'arcade%' only. The 'arena' CLASS now belongs to the arena doors, which are handled
    -- as transfers above; leaving it here would have made a withdrawal mint.
    ELSIF v_kind LIKE 'arcade%' THEN
      RETURN 'arena';
    ELSE
      RETURN 'reward';
    END IF;
  ELSE
    IF v_kind IN ('chip_mint', 'chip_purchase', 'mint_chips', 'diamonds_to_chips') OR v_class = 'bridge' THEN
      RETURN 'bridge';
    ELSIF v_class = 'admin' OR v_kind IN ('adjustment', 'reconciliation', 'admin', 'chargeback', 'clawback') THEN
      RETURN 'adjustment';
    ELSE
      RETURN 'spend';
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION public.fn_ca_diamond_journal_origin(p_type text, p_transaction_type text, p_source text, p_issuance_class text, p_amount numeric) OWNER TO postgres;

--
-- Name: fn_ca_diamond_offledger_float(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_offledger_float() RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v numeric;
BEGIN
  -- No arena at all: nothing is parked outside the player wallet, and 0 is the true answer.
  IF to_regprocedure('public.fn_ca_arena_diamonds()') IS NULL THEN
    RETURN 0;
  END IF;

  -- An arena exists, so its float is part of the supply and the books need the real number.
  -- If it cannot be read, RAISE. Returning 0 here would report a balanced set of books that had
  -- simply stopped counting one of the accounts (CLAUDE.md 10.86).
  EXECUTE 'SELECT public.fn_ca_arena_diamonds()' INTO v;
  IF v IS NULL THEN
    RAISE EXCEPTION 'the arena float is unreadable: fn_ca_arena_diamonds() exists and returned NULL. The books will not publish a balance they could not compute.';
  END IF;
  RETURN v;
END $$;


ALTER FUNCTION public.fn_ca_diamond_offledger_float() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_offledger_float(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_offledger_float() IS 'Diamonds a player owns that are not in profiles.diamonds - today the arena float. Returns 0 when no arena exists (the true answer) and RAISES when one exists but cannot be read (never 0, which would be a wrong balance that looks right). THE CONTRACT: whatever parks diamonds outside the player wallet provides public.fn_ca_arena_diamonds(); the books need no other change.';


--
-- Name: fn_ca_diamond_player_spend(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_player_spend(p_from timestamp with time zone) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- What players spent PLAYING, decided by the register's own authority on what a movement is:
  --   'spend'  - a debit for something in the game (entries, stakes, features, time banks)
  --   'bridge' - diamonds converted into chips, which is a player spending them
  -- and NOT 'adjustment' (the house correcting its books), NOT 'refund' (money going back to a
  -- card), NOT NULL (transfers, the Mint's own doors, seeds and test rows, which move no value
  -- out of the player economy). Fixtures are not players.
  SELECT COALESCE(sum(-dt.amount), 0)::numeric
    FROM public.diamond_transactions dt
   WHERE dt.amount < 0
     AND dt.created_at >= p_from
     AND public.fn_ca_diamond_journal_origin(dt.type, dt.transaction_type, dt.source,
                                             dt.issuance_class, dt.amount) IN ('spend', 'bridge')
     AND NOT public.fn_ca_is_fixture_account(dt.user_id);
$$;


ALTER FUNCTION public.fn_ca_diamond_player_spend(p_from timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_player_spend(p_from timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_player_spend(p_from timestamp with time zone) IS 'What players spent playing since p_from, by the register''s own origin rule: spend and bridge only, fixtures excluded. The denominator of the health number. Classifying by issuance_class instead returned the raw sink, because historical rows carry NULL there.';


--
-- Name: fn_ca_diamond_prune_history(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_prune_history(p_incident_days integer DEFAULT 30, p_challenge_days integer DEFAULT 400, p_abandoned_days integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_incidents integer := 0; v_challenges integer := 0; v_abandoned integer := 0;
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;
  -- The challenge floor is 400 days and not 60, because this table is also the streak ledger:
  -- get_challenge_streak reads every completed row with no lower bound and walks back to the
  -- first gap, so deleting completed rows inside any plausible streak horizon would make a long
  -- streak uncomputable (D2). 400 days is beyond a year-long streak.
  IF p_incident_days < 7 OR p_challenge_days < 400 OR p_abandoned_days < 45 THEN
    RAISE EXCEPTION 'retention below the floor: incidents 7 days, challenges 400 days, abandoned 45 days';
  END IF;

  DELETE FROM public.ca_diamond_incidents
   WHERE resolved_at IS NOT NULL
     AND severity IN ('info', 'warning')
     AND occurred_at < now() - make_interval(days => p_incident_days);
  GET DIAGNOSTICS v_incidents = ROW_COUNT;

  DELETE FROM public.user_daily_challenges
   WHERE (claimed OR expired_at IS NOT NULL)
     AND created_at < now() - make_interval(days => p_challenge_days);
  GET DIAGNOSTICS v_challenges = ROW_COUNT;

  -- Assigned and never completed: no expiry reaches it and no claim will ever come, so it was the
  -- one class the first version could not remove even though it grows fastest (D8). Not part of
  -- any streak, because a streak counts completions.
  DELETE FROM public.user_daily_challenges
   WHERE NOT completed
     AND created_at < now() - make_interval(days => p_abandoned_days);
  GET DIAGNOSTICS v_abandoned = ROW_COUNT;

  RETURN jsonb_build_object('ok', true, 'incidents_pruned', v_incidents,
                            'challenges_pruned', v_challenges, 'abandoned_pruned', v_abandoned,
                            'incident_days', p_incident_days, 'challenge_days', p_challenge_days,
                            'abandoned_days', p_abandoned_days);
END $$;


ALTER FUNCTION public.fn_ca_diamond_prune_history(p_incident_days integer, p_challenge_days integer, p_abandoned_days integer) OWNER TO postgres;

--
-- Name: fn_ca_diamond_register_follows_journal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_register_follows_journal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  BEGIN
    PERFORM public.fn_ca_register_diamond_journal_row(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    -- The diamonds already moved and the journal row stands. A register that
    -- could not be written is an incident, not a refused purchase.
    BEGIN
      PERFORM public.fn_ca_diamond_incident(
        'MINT:register_follow_failed', 'critical', NEW.user_id, NEW.amount,
        'fn_ca_diamond_register_follows_journal',
        jsonb_build_object('sqlstate', SQLSTATE, 'sqlerrm', SQLERRM,
                           'journal_id', NEW.id, 'reference_id', NEW.reference_id));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_diamond_register_follows_journal() OWNER TO postgres;

--
-- Name: fn_ca_diamond_register_vs_supply(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_register_vs_supply() RETURNS TABLE(register_net numeric, meter_total numeric, player_diamonds numeric, house_diamonds numeric, difference numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH r AS (SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) AS net
               FROM public.ca_mint_ledger WHERE asset = 'diamonds'),
       p AS (SELECT COALESCE(SUM(COALESCE(diamonds, 0)), 0)::numeric AS held FROM public.profiles),
       h AS (SELECT COALESCE(SUM(COALESCE(balance, 0)), 0)::numeric AS held FROM public.ca_diamond_house)
  SELECT round(r.net, 2), round(p.held + h.held, 2), round(p.held, 2), round(h.held, 2),
         round(p.held + h.held - r.net, 2)
    FROM r, p, h;
$$;


ALTER FUNCTION public.fn_ca_diamond_register_vs_supply() OWNER TO postgres;

--
-- Name: fn_ca_diamond_rule_flip(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_rule_flip(p_rule text, p_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_row public.ca_diamond_rule_modes%ROWTYPE; v_dirty integer;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND current_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'fn_ca_diamond_rule_flip: service_role required';
  END IF;
  SELECT * INTO v_row FROM public.ca_diamond_rule_modes WHERE rule = p_rule FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'fn_ca_diamond_rule_flip: unknown rule %', p_rule;
  END IF;
  IF v_row.mode = 'refuse' THEN
    RETURN jsonb_build_object('ok', true, 'rule', p_rule, 'mode', 'refuse', 'already', true);
  END IF;
  -- A rule with no reader cannot become a refusal (CLAUDE.md 10.86): the flip would report
  -- mode 'refuse' and change nothing, which is worse than never having flipped it. Found by the
  -- verification pass on 2026-09-08, when DR15 was exactly that.
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public'
       AND p.prosrc LIKE '%fn_ca_diamond_rule_mode%'
       AND p.prosrc LIKE '%' || p_rule || '%'
  ) THEN
    RAISE EXCEPTION 'fn_ca_diamond_rule_flip: no function consults %; flipping it would change nothing', p_rule;
  END IF;
  IF now() < v_row.flip_after THEN
    RAISE EXCEPTION 'fn_ca_diamond_rule_flip: % may not flip before %', p_rule, v_row.flip_after;
  END IF;
  SELECT count(*) INTO v_dirty
    FROM public.ca_diamond_incidents i
   WHERE i.rule = p_rule AND i.severity <> 'info'
     AND i.occurred_at >= now() - make_interval(days => v_row.clean_days_required);
  IF v_dirty > 0 THEN
    RAISE EXCEPTION 'fn_ca_diamond_rule_flip: % has % non-info incidents in the last % days; not clean',
      p_rule, v_dirty, v_row.clean_days_required;
  END IF;
  UPDATE public.ca_diamond_rule_modes
     SET mode = 'refuse', flipped_at = now(), flipped_by = p_by, updated_at = now()
   WHERE rule = p_rule;
  RETURN jsonb_build_object('ok', true, 'rule', p_rule, 'mode', 'refuse', 'flipped_by', p_by);
END $$;


ALTER FUNCTION public.fn_ca_diamond_rule_flip(p_rule text, p_by text) OWNER TO postgres;

--
-- Name: fn_ca_diamond_rule_flip_due(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_rule_flip_due(p_dry_run boolean DEFAULT false) RETURNS TABLE(rule text, action text, detail text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r record; v_msg text; v_fc record; v_armed int := 0; v_blocked int := 0; v_n bigint;
        v_window integer;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND current_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'fn_ca_diamond_rule_flip_due: service_role required';
  END IF;

  FOR r IN SELECT m.rule AS rl, m.flip_after, m.clean_days_required
             FROM public.ca_diamond_rule_modes m
            WHERE m.mode = 'log' ORDER BY m.flip_after, m.rule
  LOOP
    v_window := GREATEST(24, r.clean_days_required * 24);
    SELECT * INTO v_fc FROM public.fn_ca_diamond_flip_forecast(v_window) f WHERE f.rule = r.rl;

    IF v_fc IS NULL THEN
      v_blocked := v_blocked + 1;
      RETURN QUERY SELECT r.rl, 'unknown'::text,
        'the forecast does not cover this rule, so nothing can say what arming it would do'::text;
      CONTINUE;
    END IF;

    -- GATE ON would_refuse, NOT ON since_config.
    --
    -- since_config was the gate and it was inert. zz_touch_updated_at fires on ANY column, so
    -- editing a note resets the epoch; and for DR7 the epoch is the newest of all fourteen cap
    -- rows, so touching the `wheel` cap erased DR7's evidence. Measured 2026-09-08: DR7 showed
    -- would_refuse 4,553 over seven days and since_config 0 on a 43-minute window, and the gate
    -- passed. A window younger than the evidence period is UNKNOWN, never clean.
    IF v_fc.config_at IS NOT NULL
       AND v_fc.config_at > now() - make_interval(days => r.clean_days_required) THEN
      v_blocked := v_blocked + 1;
      RETURN QUERY SELECT r.rl, 'unknown'::text,
        format('its configuration changed %s ago, less than the %s clean days required, so the '
               || 'evidence window is too short to judge (%s refusals in the last %s hours)',
               to_char(now() - v_fc.config_at, 'DD"d" HH24"h"'), r.clean_days_required,
               v_fc.would_refuse, v_window);
      CONTINUE;
    END IF;

    IF v_fc.would_refuse > 0 THEN
      v_blocked := v_blocked + 1;
      RETURN QUERY SELECT r.rl, 'blocked'::text,
        format('would refuse %s movement(s) affecting %s player(s) in the last %s hours',
               v_fc.would_refuse, v_fc.players_hit, v_window);
      CONTINUE;
    END IF;

    IF now() < r.flip_after THEN
      v_blocked := v_blocked + 1;
      RETURN QUERY SELECT r.rl, 'blocked'::text,
        format('may not arm before %s', to_char(r.flip_after, 'YYYY-MM-DD'));
      CONTINUE;
    END IF;
    SELECT count(*) INTO v_n FROM public.ca_diamond_incidents i
     WHERE i.rule = r.rl AND i.severity <> 'info'
       AND i.occurred_at >= now() - make_interval(days => r.clean_days_required);
    IF v_n > 0 THEN
      v_blocked := v_blocked + 1;
      RETURN QUERY SELECT r.rl, 'blocked'::text,
        format('%s non-info incident(s) in the last %s days; not clean', v_n, r.clean_days_required);
      CONTINUE;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = 'public' AND p.prosrc LIKE '%fn_ca_diamond_rule_mode%'
         AND p.prosrc LIKE '%' || r.rl || '%') THEN
      v_blocked := v_blocked + 1;
      RETURN QUERY SELECT r.rl, 'blocked'::text,
        'no function consults this rule; arming it would change nothing'::text;
      CONTINUE;
    END IF;

    IF p_dry_run THEN
      RETURN QUERY SELECT r.rl, 'would-arm'::text,
        format('every gate passes; arming date %s', COALESCE(r.flip_after::date::text, 'unset'));
      CONTINUE;
    END IF;

    BEGIN
      PERFORM public.fn_ca_diamond_rule_flip(r.rl, 'auto:flip_due');
      v_armed := v_armed + 1;
      RETURN QUERY SELECT r.rl, 'armed'::text, 'now refusing'::text;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT;
      v_blocked := v_blocked + 1;
      RETURN QUERY SELECT r.rl, 'blocked'::text, v_msg;
    END;
  END LOOP;

  -- THE BEACON ONLY ON A REAL RUN. It was filed on every call, and fn_ca_diamond_health calls this
  -- as a dry run - so reading the report wrote 19 beacon rows against 1 scheduled run, and the
  -- signal that a scheduler is alive became a signal that somebody opened a report.
  IF NOT p_dry_run THEN
    BEGIN
      PERFORM public.fn_ca_diamond_incident(
        'DR0:rule_flip_sweep', 'info', NULL, NULL, 'fn_ca_diamond_rule_flip_due',
        jsonb_build_object('armed', v_armed, 'blocked', v_blocked));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;
END $$;


ALTER FUNCTION public.fn_ca_diamond_rule_flip_due(p_dry_run boolean) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_rule_flip_due(p_dry_run boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_rule_flip_due(p_dry_run boolean) IS 'Arms every diamond rule whose flip_after date has passed and whose gates all pass, and REPORTS every rule it could not arm. Exists because nine rules carried arming dates and nothing anywhere called fn_ca_diamond_rule_flip - the dates would have passed unremarked for ever. It decides nothing: arming was decided when each rule was written (rulings 13-20). Scheduled daily as ca-diamond-rule-flip-daily.';


--
-- Name: fn_ca_diamond_rule_mode(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_rule_mode(p_rule text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE((SELECT m.mode FROM public.ca_diamond_rule_modes m WHERE m.rule = p_rule), 'log');
$$;


ALTER FUNCTION public.fn_ca_diamond_rule_mode(p_rule text) OWNER TO postgres;

--
-- Name: fn_ca_diamond_snapshot(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_snapshot() RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prof numeric; v_wal numeric; v_cert numeric; v_total numeric; v_house numeric; v_arena_now numeric;
  v_reg numeric; v_fix numeric; v_reg_fix numeric;
  prev RECORD; v_journal numeric; v_journal_noncert numeric; v_unexplained numeric; v_fix_unexplained numeric;
  v_basis_changed boolean := false;
  v_prev_basis numeric;
  v_mirror_bad bigint := 0;
BEGIN
  -- ONE statement, ONE snapshot (2026-09-07 review fix 4): the meter, the mirror, the fixture share,
  -- the house and the register are read together, so a signup committing between two reads cannot
  -- show as a 500 drift for one run.
  SELECT (SELECT COALESCE(sum(diamonds),0) FROM public.profiles),
         (SELECT COALESCE(sum(balance),0) FROM public.diamond_wallets),
         (SELECT COALESCE(sum(p.diamonds),0) FROM public.profiles p WHERE public.fn_ca_is_cert_account(p.id)),
         (SELECT COALESCE(sum(p.diamonds),0) FROM public.profiles p WHERE public.fn_ca_is_fixture_account(p.id)),
         (SELECT COALESCE(balance, 0) FROM public.ca_diamond_house WHERE id = 1),
         (SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
            FROM public.ca_mint_ledger WHERE asset = 'diamonds' AND holder_type = 'player'),
         (SELECT COALESCE(SUM(CASE WHEN m.action = 'mint' THEN m.amount ELSE -m.amount END), 0)
            FROM public.ca_mint_ledger m
           WHERE m.asset = 'diamonds' AND m.holder_type = 'player' AND public.fn_ca_is_fixture_account(m.holder_id))
    INTO v_prof, v_wal, v_cert, v_fix, v_house, v_reg, v_reg_fix;
  v_house := COALESCE(v_house, 0);

  -- The basis is what players hold PLUS what they have parked on the arena felt. Both sides of
  -- the comparison below use the same basis, so a deposit nets to zero and the deploy gate keeps
  -- meaning "diamonds appeared or vanished" rather than "diamonds moved" (2026-09-08).
  v_arena_now := public.fn_ca_diamond_offledger_float();
  v_total := v_prof + v_arena_now;

  SELECT count(*) INTO v_mirror_bad
    FROM profiles p
    LEFT JOIN user_diamonds        ud  ON ud.user_id  = p.id
    LEFT JOIN user_diamond_balance udb ON udb.user_id = p.id
    LEFT JOIN diamond_wallets      dw  ON dw.user_id  = p.id
   WHERE ud.user_id IS NULL OR udb.user_id IS NULL OR dw.user_id IS NULL
      OR ud.balance  IS DISTINCT FROM GREATEST(COALESCE(p.diamonds,0),0)
      OR udb.balance IS DISTINCT FROM GREATEST(COALESCE(p.diamonds,0),0)::int
      OR dw.balance  IS DISTINCT FROM GREATEST(COALESCE(p.diamonds,0),0)::int;

  SELECT * INTO prev FROM public.ca_diamond_snapshots ORDER BY taken_at DESC LIMIT 1;
  IF prev.id IS NOT NULL THEN
    SELECT COALESCE(sum(amount),0) INTO v_journal FROM diamond_transactions WHERE created_at > prev.taken_at;
    SELECT COALESCE(sum(amount),0) INTO v_journal_noncert
      FROM diamond_transactions t WHERE t.created_at > prev.taken_at AND NOT public.fn_ca_is_cert_account(t.user_id);
    SELECT EXISTS (SELECT 1 FROM public.ca_cert_accounts c WHERE c.tagged_at > prev.taken_at) INTO v_basis_changed;
    v_prev_basis := prev.profile_diamonds + COALESCE(prev.arena_diamonds, 0);
  END IF;

  -- The player identity, on stored figures, fixtures apart (2026-09-07 review fix 2):
  --   unexplained = (players - fixtures) moved - (player register - fixture register) moved.
  -- The fixture share is measured the same way and reported as its own drift class, because the
  -- certification harness writes fixture balances directly (a harness defect, DR6 at info), and a
  -- harness defect must never arm the deploy gate that protects players.
  IF prev.id IS NOT NULL AND prev.register_supply IS NOT NULL AND prev.fixture_diamonds IS NOT NULL THEN
    v_unexplained     := ((v_total - v_fix) - (v_prev_basis - prev.fixture_diamonds))
                       - ((v_reg - v_reg_fix) - (prev.register_supply - COALESCE(prev.register_fixture, 0)));
    v_fix_unexplained := (v_fix - prev.fixture_diamonds) - (v_reg_fix - COALESCE(prev.register_fixture, 0));
  ELSIF prev.id IS NOT NULL AND prev.register_supply IS NOT NULL THEN
    -- One transitional row: the previous snapshot stored the register but not the fixture split.
    v_unexplained := NULL; v_fix_unexplained := NULL;
  ELSIF prev.id IS NOT NULL AND NOT v_basis_changed THEN
    v_unexplained := (v_total - v_cert) - (v_prev_basis - COALESCE(prev.cert_diamonds, 0)) - COALESCE(v_journal_noncert, 0);
    v_fix_unexplained := NULL;
  ELSE
    v_unexplained := NULL; v_fix_unexplained := NULL;
  END IF;

  INSERT INTO public.ca_diamond_snapshots
    (arena_diamonds, profile_diamonds, wallet_diamonds, cert_diamonds, total, journaled_delta, delta_vs_prev, unexplained,
     register_supply, house_balance, fixture_diamonds, register_fixture)
  VALUES
    (v_arena_now, v_prof, v_wal, v_cert, v_total, v_journal,
     CASE WHEN prev.id IS NULL THEN NULL ELSE v_total - v_prev_basis END,
     v_unexplained, v_reg, v_house, v_fix, v_reg_fix);

  IF v_mirror_bad > 0 THEN
    PERFORM public.fn_ca_diamond_incident('DR10:mirror_mismatch', 'warning', NULL, v_mirror_bad::numeric,
      'fn_ca_diamond_snapshot',
      jsonb_build_object('profiles_disagreeing', v_mirror_bad, 'profile_diamonds', v_prof, 'wallet_diamonds', v_wal,
        'note', 'the three mirrors are upserted on INSERT and UPDATE since 2026-09-07; a disagreeing or missing row means a writer bypassed the mirror trigger'));
  END IF;

  IF v_unexplained IS NOT NULL AND abs(v_unexplained) > 50 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_diamond_snapshot', 'ledger_imbalance',
      CASE WHEN abs(v_unexplained) > 5000 THEN 'critical' ELSE 'warning' END,
      'diamond-unexplained:' || to_char(now(), 'YYYY-MM-DD-HH24'),
      v_unexplained, v_prev_basis + COALESCE(v_journal,0), v_total,
      'ledger', 'ca_diamond_snapshots', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'player diamond supply (fixtures excluded) moved by ' || round(v_unexplained,2)
        || ' more than the Mint register explains - a diamond writer is bypassing the register',
      false, jsonb_build_object('profile_diamonds', v_prof, 'fixture_diamonds', v_fix, 'register_supply', v_reg,
                                 'register_fixture', v_reg_fix, 'house_balance', v_house));
  END IF;

  IF v_fix_unexplained IS NOT NULL AND v_fix_unexplained <> 0 THEN
    PERFORM public.fn_ca_diamond_incident('DR6:fixture_harness_unregistered_movement', 'info', NULL, v_fix_unexplained,
      'fn_ca_diamond_snapshot',
      jsonb_build_object('fixture_diamonds', v_fix, 'prev_fixture_diamonds', prev.fixture_diamonds,
        'register_fixture', v_reg_fix, 'prev_register_fixture', prev.register_fixture,
        'note', 'certification fixture balances moved outside the journal and the register (the harness writes profiles.diamonds directly). Not a player movement. The root fix is the harness funding through fn_ca_mint and spending through deduct_diamonds.'));
  END IF;

  RETURN v_unexplained;
END $$;


ALTER FUNCTION public.fn_ca_diamond_snapshot() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_snapshot(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_snapshot() IS 'DR10. Hourly diamond supply snapshot (cron job 201). total = SUM(profiles.diamonds), the canonical store, read once. user_diamonds, user_diamond_balance and diamond_wallets are mirrors: recorded and compared for equality, never added. Drift is measured against prev.profile_diamonds so the basis is continuous across the 2026-09-03 identity change. service_role only: it writes the rows the engine deploy money gate reads, so no browser role may call it.';


--
-- Name: fn_ca_diamond_trial_balance(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_trial_balance(p_since timestamp with time zone DEFAULT (now() - '01:15:00'::interval)) RETURNS TABLE(account text, balance_now numeric, balance_delta numeric, journal_net numeric, mint_net numeric, difference numeric, note text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_foundation constant timestamptz := timestamptz '2026-09-03 00:07:00+00';
  v_since   timestamptz := COALESCE(p_since, now() - interval '75 minutes');
  s0        public.ca_diamond_snapshots%ROWTYPE;
  w0        timestamptz;
  v_players numeric; v_house numeric; v_reg numeric; v_reg_players numeric; v_reg_house numeric;
  v_fix numeric; v_reg_fix numeric; v_fix_n bigint;
  v_delta   numeric; v_jrn numeric; v_jrn_live numeric; v_jrn_archive numeric; v_mint numeric;
  v_diff    numeric; v_note text; v_n bigint; v_sub numeric; v_tmp numeric;
  v_house_ledger numeric;
  v_arena numeric;
  v_tot_now numeric := 0; v_tot_delta numeric := 0; v_tot_jrn numeric := 0; v_tot_mint numeric := 0;
  r record;
BEGIN
  SELECT * INTO s0 FROM public.ca_diamond_snapshots WHERE taken_at >= v_since ORDER BY taken_at ASC LIMIT 1;
  w0 := COALESCE(s0.taken_at, v_since);

  -- ONE statement, ONE snapshot (2026-09-07 review fix 4), so a signup committing between two reads
  -- cannot show as a 500 break for one run.
  SELECT (SELECT COALESCE(SUM(COALESCE(p.diamonds, 0)), 0)::numeric FROM public.profiles p),
         (SELECT COALESCE(SUM(p.diamonds), 0) FROM public.profiles p WHERE public.fn_ca_is_fixture_account(p.id)),
         (SELECT count(*) FROM public.profiles p WHERE public.fn_ca_is_fixture_account(p.id)),
         (SELECT COALESCE(balance, 0) FROM public.ca_diamond_house WHERE id = 1),
         (SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
            FROM public.ca_mint_ledger WHERE asset = 'diamonds' AND holder_type = 'player'),
         (SELECT COALESCE(SUM(CASE WHEN m.action = 'mint' THEN m.amount ELSE -m.amount END), 0)
            FROM public.ca_mint_ledger m WHERE m.asset = 'diamonds' AND m.holder_type = 'player' AND public.fn_ca_is_fixture_account(m.holder_id)),
         (SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
            FROM public.ca_mint_ledger WHERE asset = 'diamonds' AND holder_type = 'house'),
         public.fn_ca_mint_supply('diamonds')
    INTO v_players, v_fix, v_fix_n, v_house, v_reg_players, v_reg_fix, v_reg_house, v_reg;
  v_house := COALESCE(v_house, 0);

  SELECT COALESCE(SUM(dt.amount), 0) INTO v_jrn_live FROM public.diamond_transactions dt WHERE dt.created_at >= w0 AND dt.created_at < now();
  SELECT COALESCE(SUM(a.amount), 0) INTO v_jrn_archive FROM public.ca_diamond_journal_archive a WHERE a.created_at >= w0 AND a.created_at < now();
  v_jrn := v_jrn_live + v_jrn_archive;

  -- player_diamonds: players without the fixture harness, on stored figures.
  IF s0.id IS NULL THEN
    v_delta := NULL; v_mint := NULL; v_diff := NULL;
    v_note := 'no diamond snapshot at or after the window start, so the delta is unknown';
  ELSIF s0.register_supply IS NOT NULL AND s0.fixture_diamonds IS NOT NULL THEN
    v_delta := (v_players - v_fix) - (s0.profile_diamonds - s0.fixture_diamonds);
    v_mint  := (v_reg_players - v_reg_fix) - (s0.register_supply - COALESCE(s0.register_fixture, 0));
    v_diff  := v_delta - v_mint;
    v_note  := 'player balances (fixtures excluded) moved ' || v_delta || ' since the ' || to_char(s0.taken_at AT TIME ZONE 'UTC', 'HH24:MI')
            || ' UTC snapshot; the player register moved ' || v_mint || ' on the same stored figures (no window skew).'
            || ' journal_net over the window is ' || v_jrn || ' (live ' || v_jrn_live || ' + archived ' || v_jrn_archive
            || '), informative: the seed trigger and the Mint house branch write no journal row.';
  ELSIF s0.register_supply IS NOT NULL THEN
    v_delta := v_players - s0.profile_diamonds;
    v_mint  := v_reg_players - s0.register_supply;
    v_diff  := v_delta - v_mint;
    v_note  := 'transitional: the window snapshot stored the register but not the fixture split, so this row includes the certification harness. journal_net ' || v_jrn || ' informative.';
  ELSE
    v_delta := v_players - s0.profile_diamonds;
    SELECT COALESCE(SUM(CASE WHEN ml.action = 'mint' THEN ml.amount ELSE -ml.amount END), 0) INTO v_mint
      FROM public.ca_mint_ledger ml WHERE ml.asset = 'diamonds' AND ml.holder_type = 'player' AND ml.created_at >= w0 AND ml.created_at < now();
    v_diff := v_delta - v_mint;
    v_note := 'the window snapshot predates register_supply, so the register is windowed by created_at (boundary skew possible). journal_net ' || v_jrn || ' informative.';
  END IF;
  -- balance_now must be the SAME population balance_delta is measured on, or adding this row
  -- to fixture_accounts double counts the harness (found by the verification pass, 2026-09-08).
  DECLARE v_players_shown numeric := CASE
    WHEN s0.id IS NOT NULL AND s0.register_supply IS NOT NULL AND s0.fixture_diamonds IS NOT NULL
    THEN v_players - v_fix ELSE v_players END;
  BEGIN
    v_tot_now := v_tot_now + v_players_shown; v_tot_delta := v_tot_delta + COALESCE(v_delta, 0);
    v_tot_jrn := v_tot_jrn + v_jrn; v_tot_mint := v_tot_mint + COALESCE(v_mint, 0);
    RETURN QUERY SELECT 'player_diamonds'::text, v_players_shown, v_delta, v_jrn, v_mint, v_diff,
      (v_note || CASE WHEN v_players_shown <> v_players
                      THEN ' balance_now is players WITHOUT the harness (' || v_fix || ' shown on the fixture_accounts row), so the two rows add up.'
                      ELSE '' END)::text;
  END;

  -- fixture_accounts: the certification harness, measured the same way, reported apart.
  IF s0.id IS NOT NULL AND s0.fixture_diamonds IS NOT NULL THEN
    v_delta := v_fix - s0.fixture_diamonds;
    v_mint  := v_reg_fix - COALESCE(s0.register_fixture, 0);
    v_diff  := v_delta - v_mint;
    v_note  := format('%s fixture profiles hold %s. Their balances moved %s and their register moved %s; a non-zero difference is the harness writing profiles.diamonds directly (DR6 at info). Never a player, never a horse.', v_fix_n, v_fix, v_delta, v_mint);
  ELSE
    v_delta := NULL; v_mint := NULL; v_diff := NULL;
    v_note := format('%s fixture profiles hold %s diamonds (inside player_diamonds). No stored fixture figure at the window start yet.', v_fix_n, v_fix);
  END IF;
  RETURN QUERY SELECT 'fixture_accounts'::text, v_fix, v_delta, NULL::numeric, v_mint, v_diff, v_note;

  -- diamond_house
  SELECT COALESCE(SUM(delta), 0) INTO v_house_ledger FROM public.ca_diamond_house_ledger WHERE at >= w0 AND at < now();
  SELECT COALESCE(SUM(CASE WHEN ml.action = 'mint' THEN ml.amount ELSE -ml.amount END), 0) INTO v_mint
    FROM public.ca_mint_ledger ml WHERE ml.asset = 'diamonds' AND ml.holder_type = 'house' AND ml.created_at >= w0 AND ml.created_at < now();
  IF s0.id IS NOT NULL AND s0.house_balance IS NOT NULL THEN
    v_delta := v_house - s0.house_balance; v_diff := v_delta - v_house_ledger - v_mint;
    v_note := 'house moved ' || v_delta || '; the house ledger (rake, cuts, forfeits) explains ' || v_house_ledger || ' and the Mint explains ' || v_mint || '. DR14: what leaves a player and reaches no player lands here.';
  ELSE
    v_delta := NULL; v_diff := NULL;
    v_note := 'no stored house balance at the window start; ledger ' || v_house_ledger || ', mint ' || v_mint || ' shown.';
  END IF;
  v_tot_now := v_tot_now + v_house; v_tot_delta := v_tot_delta + COALESCE(v_delta, 0); v_tot_mint := v_tot_mint + COALESCE(v_mint, 0);
  RETURN QUERY SELECT 'diamond_house'::text, v_house, v_delta, v_house_ledger, v_mint, v_diff, v_note;

  -- arena_wallets: diamonds a player has deposited onto the platform club's felt. Still theirs,
  -- still in the supply, and in neither profiles nor the house - so the identity below has to
  -- count them or a deposit reads as a break (2026-09-08).
  v_arena := public.fn_ca_diamond_offledger_float();
  IF s0.id IS NOT NULL AND s0.arena_diamonds IS NOT NULL THEN
    v_delta := v_arena - s0.arena_diamonds;
  ELSE
    v_delta := NULL;
  END IF;
  v_tot_now := v_tot_now + v_arena; v_tot_delta := v_tot_delta + COALESCE(v_delta, 0);
  RETURN QUERY SELECT 'arena_wallets'::text, v_arena, v_delta, NULL::numeric, NULL::numeric, NULL::numeric,
    ('diamonds on the Diamond Arena felt (platform club member wallets). A deposit moves them out of '
     || 'profiles.diamonds without changing the supply, so they are counted here and in the register '
     || 'identity below. The Mint issues nothing for a deposit and retires nothing for a withdrawal.')::text;

  -- register: the identity over every holder (D9), read in the same snapshot as the balances.
  RETURN QUERY SELECT 'register'::text, v_reg, NULL::numeric, NULL::numeric, NULL::numeric, (v_players + v_house + v_arena) - v_reg,
    ('fn_ca_mint_supply(diamonds) over every holder is ' || v_reg || '; players + house + arena is ' || (v_players + v_house + v_arena)
     || '. Player holders net ' || v_reg_players || ' (fixtures ' || v_reg_fix || '), house holders net ' || v_reg_house
     || ', the rest is the acknowledged pre-standard baseline and its corrections (holder circulation). difference must be 0.')::text;

  -- diamond_debts
  EXECUTE 'SELECT COALESCE(SUM(amount), 0)::numeric FROM public.diamond_debts WHERE settled_at IS NULL' INTO v_sub;
  v_tot_now := v_tot_now + v_sub;
  RETURN QUERY SELECT 'diamond_debts'::text, v_sub, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric,
    'unsettled chargeback receivable (DR1). A balance is never negative; the remainder lands here.'::text;

  -- promo_budgets_spent
  SELECT COALESCE(SUM(public.fn_ca_diamond_engine_spent(b.period, b.engine)), 0)::numeric, COALESCE(SUM(b.budget_diamonds), 0)::numeric, count(*) INTO v_sub, v_tmp, v_n
    FROM public.diamond_reward_budgets b;
  RETURN QUERY SELECT 'promo_budgets_spent'::text, v_sub, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric,
    format('%s budget lines, %s budgeted, %s spent by players (fixture issuance excluded since 2026-09-07). A counter, not a balance.', v_n, v_tmp, v_sub);

  -- mirror_mismatch
  SELECT count(*) INTO v_n FROM public.profiles p
    LEFT JOIN public.user_diamonds ud ON ud.user_id = p.id
    LEFT JOIN public.user_diamond_balance udb ON udb.user_id = p.id
    LEFT JOIN public.diamond_wallets dw ON dw.user_id = p.id
   WHERE ud.user_id IS NULL OR udb.user_id IS NULL OR dw.user_id IS NULL
      OR ud.balance IS DISTINCT FROM GREATEST(COALESCE(p.diamonds,0),0)
      OR udb.balance IS DISTINCT FROM GREATEST(COALESCE(p.diamonds,0),0)::int
      OR dw.balance IS DISTINCT FROM GREATEST(COALESCE(p.diamonds,0),0)::int;
  RETURN QUERY SELECT 'mirror_mismatch'::text, v_n::numeric, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric,
    'COUNT of profiles whose three mirrors disagree or are missing. The mirror trigger upserts all three legs on INSERT and UPDATE (2026-09-07); non-zero means a writer bypassed it.'::text;

  -- dead_stores
  v_sub := 0; v_note := '';
  FOR r IN SELECT * FROM (VALUES ('user_progress', 'diamonds'), ('bot_profiles', 'diamonds'), ('club_members', 'diamonds'),
                                 ('club_memberships', 'diamonds'), ('club_diamond_wallets', 'balance')) AS m(rel, col) LOOP
    BEGIN
      IF to_regclass('public.' || r.rel) IS NULL THEN v_note := v_note || r.rel || ': absent. ';
      ELSIF NOT EXISTS (SELECT 1 FROM information_schema.columns c
                         WHERE c.table_schema = 'public' AND c.table_name = r.rel AND c.column_name = r.col) THEN
        -- Dropped on purpose (20260908033824), which is not the same thing as a query that
        -- broke. This line exists to tell those two apart, so it has to say which one it is.
        v_note := v_note || format('%s.%s: dropped. ', r.rel, r.col);
      ELSE
        EXECUTE format('SELECT COALESCE(SUM(COALESCE(%I, 0)), 0)::numeric FROM public.%I', r.col, r.rel) INTO v_tmp;
        v_sub := v_sub + v_tmp; v_note := v_note || format('%s.%s = %s. ', r.rel, r.col, v_tmp);
      END IF;
    EXCEPTION WHEN OTHERS THEN v_note := v_note || r.rel || ': unreadable. ';
    END;
  END LOOP;
  RETURN QUERY SELECT 'dead_stores'::text, v_sub, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric,
    (v_note || 'Outside the supply; the delete list, gated on seven days of zero writes (ca_diamond_dead_store_writes).')::text;

  -- suspense (DR12)
  SELECT COALESCE(SUM(dt.amount), 0), count(*) INTO v_sub, v_n FROM public.diamond_transactions dt
   WHERE dt.created_at >= GREATEST(w0, c_foundation) AND (dt.counterparty IS NULL OR dt.counterparty = 'unknown' OR dt.issuance_class IS NULL);
  RETURN QUERY SELECT 'suspense'::text, v_sub, NULL::numeric, v_sub, NULL::numeric, NULL::numeric,
    format('%s journal rows in the window name no counterparty or class. The journal classifier fills both on INSERT since 2026-09-07 and files DR12 naming the writer, so this must read zero.', v_n);

  -- total
  RETURN QUERY SELECT 'total'::text, v_tot_now, CASE WHEN s0.id IS NULL THEN NULL ELSE v_tot_delta END, v_tot_jrn, v_tot_mint,
    CASE WHEN s0.id IS NULL THEN NULL ELSE v_tot_delta - v_tot_mint END,
    'players + house + unsettled debts. difference is player-and-house movement minus register movement (fixtures apart).'::text;
END $$;


ALTER FUNCTION public.fn_ca_diamond_trial_balance(p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_trial_balance(p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_trial_balance(p_since timestamp with time zone) IS 'DR11: one row per diamond account with balance, delta, journal net, mint net and the difference. Reports; refuses nothing. Every account is guarded so a table another lane has not landed yields a row noted "table absent" rather than an error.';


--
-- Name: fn_ca_diamond_trial_balance_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_trial_balance_watch() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record; v_since timestamptz := now() - interval '1 hour';
  v_filed integer := 0; v_rows integer := 0; v_broken text := '';
BEGIN
  FOR r IN SELECT * FROM public.fn_ca_diamond_trial_balance(v_since) LOOP
    v_rows := v_rows + 1;
    IF r.account IN ('player_diamonds', 'diamond_house', 'register') AND r.difference IS NOT NULL AND abs(r.difference) > 0 THEN
      -- Ruling 13 (docs/DIAMOND-RULINGS.md): a break over 1,000 diamonds in one hour is critical and
      -- pages; opening the diamond_issuance freeze stays a human act.
      PERFORM public.fn_ca_diamond_incident('DR11:trial_balance_break',
        CASE WHEN abs(r.difference) > 1000 THEN 'critical' ELSE 'warning' END, NULL, r.difference, r.account,
        jsonb_build_object('account', r.account, 'balance_now', r.balance_now, 'balance_delta', r.balance_delta,
                           'journal_net', r.journal_net, 'mint_net', r.mint_net, 'difference', r.difference,
                           'window_start', v_since, 'note', r.note));
      v_filed := v_filed + 1; v_broken := v_broken || r.account || ' ';
    END IF;
    IF r.account = 'fixture_accounts' AND r.difference IS NOT NULL AND abs(r.difference) > 0 THEN
      PERFORM public.fn_ca_diamond_incident('DR6:fixture_harness_unregistered_movement', 'info', NULL, r.difference,
        'fn_ca_diamond_trial_balance_watch',
        jsonb_build_object('balance_delta', r.balance_delta, 'mint_net', r.mint_net, 'window_start', v_since, 'note', r.note));
    END IF;
    IF r.account = 'suspense' AND COALESCE(r.balance_now, 0) <> 0 THEN
      PERFORM public.fn_ca_diamond_incident('DR12:suspense_nonzero', 'info', NULL, r.balance_now, 'fn_ca_diamond_trial_balance_watch',
        jsonb_build_object('suspense', r.balance_now, 'window_start', v_since, 'note', r.note));
      v_filed := v_filed + 1;
    END IF;
  END LOOP;

  PERFORM public.fn_ca_diamond_incident('DR11:trial_balance_summary', 'info', NULL, NULL, 'fn_ca_diamond_trial_balance_watch',
    jsonb_build_object('accounts_reported', v_rows, 'incidents_filed', v_filed, 'accounts_broken', NULLIF(btrim(v_broken), ''),
                       'window_start', v_since, 'window_end', now()));

  UPDATE public.ca_diamond_incidents SET resolved_at = now()
   WHERE resolved_at IS NULL AND severity = 'info' AND occurred_at < now() - interval '7 days';
  DELETE FROM public.ca_diamond_incidents
   WHERE severity = 'info' AND resolved_at IS NOT NULL AND occurred_at < now() - interval '30 days';
  RETURN v_filed;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_ca_diamond_trial_balance_watch failed: %', SQLERRM;
  RETURN -1;
END $$;


ALTER FUNCTION public.fn_ca_diamond_trial_balance_watch() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_trial_balance_watch(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_trial_balance_watch() IS 'Hourly at minute 20. Files DR11:trial_balance_break (warning) per account with a non-zero difference, DR12:suspense_nonzero (info) when suspense is non-zero, and one DR11:trial_balance_summary (info) per run. Writes nothing but incidents and NEVER opens ca_payout_freeze: the threshold is Dan (standard 6.13) and an automatic opener is the mechanism that refuses a legitimate movement on a false alarm.';


--
-- Name: fn_ca_diamond_unreachable_money(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_unreachable_money() RETURNS TABLE(finding text, object text, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- A money function nothing calls, and nothing grants to a client either: it can only ever run
  -- if a human types its name. That is how send_stream_gift sat unreachable for months.
  SELECT 'no_caller_and_no_client_grant'::text,
         p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')',
         'writes profiles.diamonds but no other function calls it and neither anon nor authenticated may execute it'::text
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.prokind = 'f'
     AND p.prosrc ~* 'update\s+(public\.)?profiles[^;]*diamonds\s*='
     AND NOT EXISTS (
       SELECT 1 FROM pg_proc q JOIN pg_namespace m ON m.oid = q.pronamespace
        WHERE m.nspname = 'public' AND q.oid <> p.oid AND q.prosrc LIKE '%' || p.proname || '%')
     AND NOT EXISTS (
       SELECT 1 FROM aclexplode(p.proacl) a
        WHERE a.grantee IN ('anon'::regrole, 'authenticated'::regrole))

  UNION ALL

  -- A money function a browser CAN call, that the privileged-column guard would refuse. That is
  -- exactly what made send_stream_gift answer 42501 to every real player.
  SELECT 'client_reachable_but_guard_refuses'::text,
         p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')',
         'granted to authenticated and writes profiles.diamonds, but fn_guard_profile_privileged_columns does not name it'::text
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.prokind = 'f'
     AND p.prosrc ~* 'update\s+(public\.)?profiles[^;]*diamonds\s*='
     AND EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 'authenticated'::regrole)
     AND NOT EXISTS (
       SELECT 1 FROM pg_proc g JOIN pg_namespace gn ON gn.oid = g.pronamespace
        WHERE gn.nspname = 'public' AND g.proname = 'fn_guard_profile_privileged_columns'
          AND g.prosrc LIKE '%' || p.proname || '[(]%')

  UNION ALL

  -- A rule row that reads as armed while nothing consults it (the DR15 shape).
  SELECT 'rule_with_no_consumer'::text, r.rule,
         'ca_diamond_rule_modes carries it, but no function calls fn_ca_diamond_rule_mode with this name'::text
    FROM public.ca_diamond_rule_modes r
   WHERE NOT EXISTS (
     SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'public'
        -- THE LITERAL CALL, not a body that merely mentions the two strings somewhere. The first
        -- version passed the rule its own migration had just inserted (D3, 2026-09-08).
        AND p.prosrc LIKE '%fn_ca_diamond_rule_mode(''' || r.rule || ''')%');
$$;


ALTER FUNCTION public.fn_ca_diamond_unreachable_money() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_diamond_unreachable_money(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_unreachable_money() IS 'Money paths that read as working while being unreachable: no caller, refused by the privileged-column guard, or a rule nothing consults. Four defects on 2026-09-08 were one of these three.';


--
-- Name: fn_ca_dismiss_collusion_pair(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_dismiss_collusion_pair(p_club_id uuid, p_player_a uuid, p_player_b uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated integer;
BEGIN
  IF NOT fn_ca_can_review_integrity(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM table_seats ts JOIN tables t ON t.id = ts.table_id
     WHERE t.club_id = p_club_id AND ts.user_id = p_player_a
  ) OR NOT EXISTS (
    SELECT 1 FROM table_seats ts JOIN tables t ON t.id = ts.table_id
     WHERE t.club_id = p_club_id AND ts.user_id = p_player_b
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'pair_did_not_play_here', 'updated', 0);
  END IF;

  -- 'cleared', not 'dismissed'. The check constraint on this table allows
  -- open | reviewed | cleared | actioned, and the word this function used to
  -- write is in none of them.
  UPDATE collusion_tracking ct
     SET status = 'cleared',
         reviewed_by = auth.uid(),
         reviewed_at = now(),
         notes = nullif(btrim(coalesce(p_note, '')), ''),
         updated_at = now()
   WHERE ct.scan_date > current_date - 30
     AND coalesce(ct.status, 'open') = 'open'
     AND ((ct.player_a = p_player_a AND ct.player_b = p_player_b)
       OR (ct.player_a = p_player_b AND ct.player_b = p_player_a));

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN jsonb_build_object('ok', v_updated > 0, 'updated', v_updated);
END;
$$;


ALTER FUNCTION public.fn_ca_dismiss_collusion_pair(p_club_id uuid, p_player_a uuid, p_player_b uuid, p_note text) OWNER TO postgres;

--
-- Name: fn_ca_drift_metrics(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_drift_metrics() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mgmt boolean := true;
  v jsonb;
BEGIN
  IF v_uid IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ca_incident_recipients r WHERE r.user_id = v_uid AND r.active
      UNION ALL
      SELECT 1 FROM public.club_members cm WHERE cm.user_id = v_uid AND cm.role = 'owner'
      UNION ALL
      SELECT 1 FROM public.unions u WHERE u.owner_id = v_uid
      UNION ALL
      SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.role IN ('admin','god')
    ) INTO v_mgmt;
    IF NOT v_mgmt THEN RETURN '{}'::jsonb; END IF;
  END IF;

  SELECT jsonb_build_object(
    'open_total',        count(*) FILTER (WHERE status <> 'resolved'),
    'open_critical',     count(*) FILTER (WHERE status <> 'resolved' AND severity = 'critical'),
    'past_target',       count(*) FILTER (WHERE status <> 'resolved' AND past_target),
    'auto_repairing',    count(*) FILTER (WHERE status <> 'resolved' AND auto_repair_status = 'running'),
    'resolved_today',    count(*) FILTER (WHERE status = 'resolved' AND resolved_at > CURRENT_DATE),
    'median_resolve_min', (SELECT round(percentile_cont(0.5) WITHIN GROUP (
                             ORDER BY extract(epoch FROM (resolved_at - detected_at))/60)::numeric, 1)
                            FROM public.ca_drift_incidents
                           WHERE status = 'resolved' AND resolved_at > now() - interval '7 days'),
    'worst_open_drift',  COALESCE(max(abs(discrepancy_amount))
                           FILTER (WHERE status <> 'resolved'), 0)
  ) INTO v
  FROM public.ca_drift_incidents;

  v := v || jsonb_build_object(
    'suspense_today', (SELECT COALESCE(sum(amount),0) FROM public.chip_ledger
                        WHERE (from_type='settlement_suspense' OR to_type='settlement_suspense')
                          AND created_at > CURRENT_DATE),
    'ledger_write_failures_24h', (SELECT count(*) FROM public.ca_ledger_write_failures
                                   WHERE occurred_at > now() - interval '24 hours'),
    'supply_unexplained_last', (SELECT unexplained FROM public.ca_supply_snapshots
                                 ORDER BY taken_at DESC LIMIT 1),
    'ledger_rows_today', (SELECT count(*) FROM public.chip_ledger WHERE created_at > CURRENT_DATE));
  RETURN v;
END $$;


ALTER FUNCTION public.fn_ca_drift_metrics() OWNER TO postgres;

--
-- Name: fn_ca_duel_pairing_scan(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_duel_pairing_scan(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(days => GREATEST(p_days, 1));
  -- Calibrated on the live board 2026-09-01: of 10,134 duels in 7 days the
  -- most any pair met is 5 (6,454 met once, 1,106 twice, 222 three times,
  -- 40 four times, 7 five times). Eight is 60% above that maximum, and the
  -- win share must hold too - win share alone is worthless down there,
  -- because every pair that met once has a "100% win rate".
  v_min_meetings   constant int     := 8;
  v_min_win_share  constant numeric := 0.8;
  r RECORD; v_flagged int := 0;
BEGIN
  FOR r IN
    WITH duels AS (
      SELECT t.id, COALESCE(t.buy_in_amount, 0) AS buy_in
        FROM public.tournaments t
       WHERE t.max_players = 2
         AND t.status = 'COMPLETED'
         AND t.started_at > v_since
    ),
    met AS (
      SELECT LEAST(a.user_id, b.user_id)    AS ua,
             GREATEST(a.user_id, b.user_id) AS ub,
             CASE WHEN a.position = 1 THEN a.user_id ELSE b.user_id END AS winner,
             d.buy_in
        FROM duels d
        JOIN public.tournament_players a ON a.tournament_id = d.id
        JOIN public.tournament_players b ON b.tournament_id = d.id
                                        AND b.user_id > a.user_id
    ),
    pairflow AS (
      SELECT ua, ub,
             count(*)                            AS meetings,
             count(*) FILTER (WHERE winner = ua) AS wins_a,
             sum(buy_in)                         AS gross_flow,
             sum(CASE WHEN winner = ua THEN buy_in ELSE -buy_in END) AS net_to_ua
        FROM met
       GROUP BY 1, 2
    )
    SELECT CASE WHEN wins_a * 2 >= meetings THEN ua ELSE ub END AS receiver,
           CASE WHEN wins_a * 2 >= meetings THEN ub ELSE ua END AS sender,
           meetings,
           gross_flow,
           abs(net_to_ua) AS net_flow,
           round(GREATEST(wins_a, meetings - wins_a)::numeric / meetings, 3) AS win_share
      FROM pairflow
     WHERE meetings >= v_min_meetings
       AND GREATEST(wins_a, meetings - wins_a)::numeric / meetings >= v_min_win_share
  LOOP
    v_flagged := v_flagged + 1;

    INSERT INTO public.ca_collusion_signals
      (window_days, user_a, user_b, hands_together, gross_flow, net_flow,
       direction_ratio, both_cert, detail)
    VALUES
      (p_days, r.receiver, r.sender, r.meetings, r.gross_flow, r.net_flow,
       r.win_share,
       public.fn_ca_is_cert_account(r.receiver) AND public.fn_ca_is_cert_account(r.sender),
       jsonb_build_object(
         'signal', 'duel_repeat_pairing',
         'since', v_since,
         'note', 'hands_together is DUELS together for this detector, not hands; '
                 || 'direction_ratio is the winner share of those duels',
         'min_meetings', v_min_meetings,
         'min_win_share', v_min_win_share));

    PERFORM public.fn_ca_raise_drift_incident(
      p_source          => 'fn_ca_duel_pairing_scan',
      p_classification  => 'unknown',
      p_severity        => CASE
                             WHEN r.win_share >= 0.9
                              AND NOT (public.fn_ca_is_cert_account(r.receiver)
                                   AND public.fn_ca_is_cert_account(r.sender))
                             THEN 'warning' ELSE 'info' END,
      p_dedupe_key      => 'duelpair:' || r.receiver::text || ':' || r.sender::text
                           || ':' || to_char(now(), 'IYYY-IW'),
      p_discrepancy     => r.net_flow,
      p_expected        => NULL,
      p_actual          => NULL,
      p_layer           => 'reporting',
      p_entity_type     => 'user',
      p_entity_id       => r.receiver,
      p_club_id         => NULL,
      p_union_id        => NULL,
      p_table_id        => NULL,
      p_tournament_id   => NULL,
      p_hand_id         => NULL,
      p_settlement_id   => NULL,
      p_wallet_ids      => NULL,
      p_transaction_ids => NULL,
      p_suspected_cause => 'the same two accounts met heads-up ' || r.meetings
                           || ' times in ' || p_days || 'd and one side won '
                           || round(r.win_share * 100) || '% of them ('
                           || r.net_flow || ' chips net) - review the pair; '
                           || 'no automatic action taken',
      p_ledger_balanced => true,
      p_metadata        => jsonb_build_object(
                             'receiver', r.receiver, 'sender', r.sender,
                             'meetings', r.meetings, 'gross_flow', r.gross_flow,
                             'net_flow', r.net_flow, 'win_share', r.win_share));
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'window_days', p_days,
                            'min_meetings', v_min_meetings,
                            'min_win_share', v_min_win_share,
                            'pairs_flagged', v_flagged);
END $$;


ALTER FUNCTION public.fn_ca_duel_pairing_scan(p_days integer) OWNER TO postgres;

--
-- Name: fn_ca_duplicate_structure_payout_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_duplicate_structure_payout_check(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_players int := 0;
  v_events  int := 0;
  v_excess  numeric := 0;
  v_sample  jsonb;
  v_since   timestamptz := now() - make_interval(hours => GREATEST(p_hours, 1));
BEGIN
  WITH dup AS (
    SELECT tpo.tournament_id,
           tpo.user_id,
           count(*)            AS rows_,
           sum(tpo.amount)     AS paid,
           max(tpo.amount)     AS largest,
           max(tpo.created_at) AS last_at
      FROM public.tournament_payouts tpo
     WHERE tpo.source = 'structure'
       AND tpo.amount > 0
       AND tpo.created_at > v_since
     GROUP BY 1, 2
    HAVING count(*) > 1
  )
  SELECT count(*),
         count(DISTINCT tournament_id),
         COALESCE(sum(paid - largest), 0),
         COALESCE(jsonb_agg(jsonb_build_object(
           'tournament_id', tournament_id, 'user_id', user_id,
           'rows', rows_, 'paid', round(paid, 2),
           'excess', round(paid - largest, 2), 'last_at', last_at)
           ORDER BY paid - largest DESC), '[]'::jsonb)
    INTO v_players, v_events, v_excess, v_sample
    FROM dup;

  IF v_players > 0 THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical',
           'fn_ca_duplicate_structure_payout_check',
           format('%s finisher(s) across %s tournament(s) hold more than one '
                  'structure payout row for the same place; %s paid beyond the '
                  'ladder in the last %s hour(s). A place pays once.',
                  v_players, v_events, round(v_excess, 2), GREATEST(p_hours, 1)),
           jsonb_build_object('players', v_players, 'tournaments', v_events,
                              'excess', round(v_excess, 2),
                              'hours', GREATEST(p_hours, 1),
                              'sample', v_sample)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'fn_ca_duplicate_structure_payout_check'
          AND fa.resolved IS NOT TRUE);
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'hours', GREATEST(p_hours, 1),
    'players_double_paid', v_players,
    'tournaments', v_events,
    'excess', round(v_excess, 2),
    'sample', v_sample);
END;
$$;


ALTER FUNCTION public.fn_ca_duplicate_structure_payout_check(p_hours integer) OWNER TO postgres;

--
-- Name: fn_ca_engine_deploy_truth_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_engine_deploy_truth_watch() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_behind_after     constant interval := interval '8 hours';
  c_silent_after     constant interval := interval '6 hours';
  c_heartbeat_dead   constant interval := interval '180 seconds';
  c_split_brain_live constant interval := interval '60 seconds';

  v_running                 text;
  v_leader_version          text;
  v_table_version           text;
  v_versions_live           int;
  v_leader_rows             int;
  v_leases                  int;
  v_leader_heartbeat        timestamptz;
  v_table_heartbeat         timestamptz;
  v_last_heartbeat          timestamptz;
  v_engine_signal_live      boolean;
  v_engine_missing_since    timestamptz;
  v_target                  text;
  v_target_since            timestamptz;
  v_last_attempt            timestamptz;
  v_ever_reported           boolean;
  v_findings                jsonb := '[]'::jsonb;
BEGIN
  SELECT count(*), max(l.heartbeat_at),
         (array_agg(l.engine_version ORDER BY l.heartbeat_at DESC))[1]
    INTO v_leader_rows, v_leader_heartbeat, v_leader_version
    FROM public.engine_leader l;

  SELECT count(*), max(l.heartbeat_at),
         (array_agg(l.engine_version ORDER BY l.heartbeat_at DESC))[1]
    INTO v_leases, v_table_heartbeat, v_table_version
    FROM public.engine_table_leases l;

  v_last_heartbeat := greatest(v_leader_heartbeat, v_table_heartbeat);
  v_running := coalesce(v_leader_version, v_table_version);
  v_engine_signal_live := v_last_heartbeat IS NOT NULL
                          AND v_last_heartbeat > now() - c_heartbeat_dead;

  -- Persist the first missing observation. A normal rolling restart that
  -- releases its rows and reclaims them inside three minutes never raises.
  -- A stale row uses its own heartbeat as the start, so an already-dead engine
  -- does not get a fresh grace period merely because this migration landed.
  INSERT INTO public.ca_engine_deploy_watch_state (
    singleton, engine_missing_since, last_engine_heartbeat, checked_at
  )
  VALUES (
    true,
    CASE
      WHEN v_engine_signal_live THEN NULL
      WHEN v_last_heartbeat IS NOT NULL THEN v_last_heartbeat
      ELSE now()
    END,
    v_last_heartbeat,
    now()
  )
  ON CONFLICT (singleton) DO UPDATE
     SET engine_missing_since = CASE
           WHEN v_engine_signal_live THEN NULL
           WHEN public.ca_engine_deploy_watch_state.engine_missing_since IS NOT NULL
             THEN public.ca_engine_deploy_watch_state.engine_missing_since
           WHEN v_last_heartbeat IS NOT NULL THEN v_last_heartbeat
           ELSE now()
         END,
         last_engine_heartbeat = coalesce(
           v_last_heartbeat,
           public.ca_engine_deploy_watch_state.last_engine_heartbeat
         ),
         checked_at = now()
  RETURNING engine_missing_since INTO v_engine_missing_since;

  SELECT count(DISTINCT live.engine_version)
    INTO v_versions_live
    FROM (
      SELECT l.engine_version
        FROM public.engine_leader l
       WHERE l.heartbeat_at > now() - c_split_brain_live
      UNION ALL
      SELECT l.engine_version
        FROM public.engine_table_leases l
       WHERE l.heartbeat_at > now() - c_split_brain_live
    ) live;

  SELECT EXISTS (SELECT 1 FROM public.ca_engine_deploy_attempts)
    INTO v_ever_reported;
  SELECT max(at) INTO v_last_attempt FROM public.ca_engine_deploy_attempts;

  SELECT a.target_sha INTO v_target
    FROM public.ca_engine_deploy_attempts a
   ORDER BY a.at DESC
   LIMIT 1;

  IF v_target IS NOT NULL AND v_running IS NOT NULL THEN
    /* How long has the ENGINE been behind - not how old is the newest sha.
       Keyed on the newest sha, every fresh commit reset the clock and a
       permanently stuck engine could never age past the threshold. */
    SELECT min(a.at) INTO v_target_since
      FROM public.ca_engine_deploy_attempts a
     WHERE left(a.target_sha, 8) <> left(v_running, 8)
       AND a.at > coalesce(
             (SELECT max(b.at)
                FROM public.ca_engine_deploy_attempts b
               WHERE left(b.target_sha, 8) = left(v_running, 8)),
             '-infinity'::timestamptz
           );
  END IF;

  -- 1. No live process heartbeat and no live table heartbeat for the full
  -- grace period. This includes the zero-row state the first version missed.
  IF v_engine_missing_since IS NOT NULL
     AND v_engine_missing_since < now() - c_heartbeat_dead THEN
    v_findings := v_findings || jsonb_build_object(
      'kind', 'engine_heartbeat_stopped',
      'missing_since', v_engine_missing_since,
      'last_heartbeat', v_last_heartbeat,
      'leader_rows', v_leader_rows,
      'leases_held', v_leases);
    IF NOT EXISTS (
      SELECT 1 FROM public.financial_alerts a
       WHERE a.source = 'deploy_truth.engine_heartbeat_stopped' AND NOT a.resolved
    ) THEN
      PERFORM public.fn_raise_server_financial_alert(
        'critical',
        'deploy_truth.engine_heartbeat_stopped',
        'No live engine heartbeat has been observed since ' || v_engine_missing_since
          || '. Leader rows: ' || v_leader_rows || '; table leases: ' || v_leases || '.',
        jsonb_build_object(
          'missing_since', v_engine_missing_since,
          'last_heartbeat', v_last_heartbeat,
          'leader_rows', v_leader_rows,
          'leases_held', v_leases,
          'engine_version', v_running
        )
      );
    END IF;
  ELSE
    UPDATE public.financial_alerts
       SET resolved = true, resolved_at = now()
     WHERE source = 'deploy_truth.engine_heartbeat_stopped' AND NOT resolved;
  END IF;

  -- 2. Two build versions are live at once.
  IF v_versions_live > 1 THEN
    v_findings := v_findings || jsonb_build_object(
      'kind', 'engine_split_brain', 'versions', v_versions_live);
    IF NOT EXISTS (
      SELECT 1 FROM public.financial_alerts a
       WHERE a.source = 'deploy_truth.engine_split_brain' AND NOT a.resolved
    ) THEN
      PERFORM public.fn_raise_server_financial_alert(
        'critical',
        'deploy_truth.engine_split_brain',
        v_versions_live || ' distinct engine builds are heartbeating at once',
        jsonb_build_object(
          'versions', (
            SELECT jsonb_agg(DISTINCT live.engine_version)
              FROM (
                SELECT l.engine_version
                  FROM public.engine_leader l
                 WHERE l.heartbeat_at > now() - c_split_brain_live
                UNION ALL
                SELECT l.engine_version
                  FROM public.engine_table_leases l
                 WHERE l.heartbeat_at > now() - c_split_brain_live
              ) live
          )
        )
      );
    END IF;
  ELSE
    UPDATE public.financial_alerts
       SET resolved = true, resolved_at = now()
     WHERE source = 'deploy_truth.engine_split_brain' AND NOT resolved;
  END IF;

  -- 3. The shipper itself has gone quiet.
  IF v_ever_reported AND v_last_attempt < now() - c_silent_after THEN
    v_findings := v_findings || jsonb_build_object(
      'kind', 'deploy_pipeline_silent', 'last_attempt', v_last_attempt);
    IF NOT EXISTS (
      SELECT 1 FROM public.financial_alerts a
       WHERE a.source = 'deploy_truth.pipeline_silent' AND NOT a.resolved
    ) THEN
      PERFORM public.fn_raise_server_financial_alert(
        'critical',
        'deploy_truth.pipeline_silent',
        'No engine deploy attempt has been recorded since ' || v_last_attempt
          || '. The deploy workflow is not running.',
        jsonb_build_object('last_attempt', v_last_attempt, 'engine_version', v_running)
      );
    END IF;
  ELSE
    UPDATE public.financial_alerts
       SET resolved = true, resolved_at = now()
     WHERE source = 'deploy_truth.pipeline_silent' AND NOT resolved;
  END IF;

  -- 4. The running build differs from the build the pipeline keeps offering.
  IF v_target IS NOT NULL AND v_running IS NOT NULL
     AND left(v_target, 8) <> left(v_running, 8)
     AND v_target_since < now() - c_behind_after THEN
    v_findings := v_findings || jsonb_build_object(
      'kind', 'engine_behind_target',
      'running', v_running,
      'target', left(v_target, 8),
      'since', v_target_since);
    IF NOT EXISTS (
      SELECT 1 FROM public.financial_alerts a
       WHERE a.source = 'deploy_truth.engine_behind_target' AND NOT a.resolved
    ) THEN
      PERFORM public.fn_raise_server_financial_alert(
        'critical',
        'deploy_truth.engine_behind_target',
        'The engine is running ' || v_running || ' but the deploy pipeline has been offering '
          || left(v_target, 8) || ' since ' || v_target_since || '. Restart windows have passed.',
        jsonb_build_object(
          'running', v_running,
          'target', left(v_target, 8),
          'target_first_offered', v_target_since
        )
      );
    END IF;
  ELSE
    UPDATE public.financial_alerts
       SET resolved = true, resolved_at = now()
     WHERE source = 'deploy_truth.engine_behind_target' AND NOT resolved;
  END IF;

  RETURN jsonb_build_object(
    'checked_at', now(),
    'engine_version', v_running,
    'leader_rows', v_leader_rows,
    'leases_held', v_leases,
    'last_heartbeat', v_last_heartbeat,
    'engine_missing_since', v_engine_missing_since,
    'last_attempt', v_last_attempt,
    'target_sha', left(coalesce(v_target, ''), 8),
    'findings', v_findings
  );
END;
$$;


ALTER FUNCTION public.fn_ca_engine_deploy_truth_watch() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_engine_deploy_truth_watch(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_engine_deploy_truth_watch() IS 'Phase 4 deploy truth. Detects engine absence, split builds, pipeline silence, and continuous lag across changing target SHAs.';


