-- Name: fn_ca_engine_spend_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_engine_spend_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION
    'ca_diamond_engine_spend is append-only: % on id % refused. It is the register of engine spend, and it replaced a running total whose mutability cost 5,861 awards. Correct it forward with a new row.',
    TG_OP, COALESCE(OLD.id, -1);
END $$;


ALTER FUNCTION public.fn_ca_engine_spend_append_only() OWNER TO postgres;

--
-- Name: fn_ca_entry_scope_ok(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_entry_scope_ok(p_user_id uuid, p_tournament_club uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_union boolean; v_club_union uuid;
BEGIN
  IF p_user_id IS NULL OR p_tournament_club IS NULL THEN
    RETURN false;
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.unions u WHERE u.id = p_tournament_club) INTO v_is_union;
  IF v_is_union THEN
    -- Union-scoped tournament: member of any club in that union.
    RETURN EXISTS (
      SELECT 1 FROM public.club_members cm JOIN public.clubs c ON c.id = cm.club_id
       WHERE cm.user_id = p_user_id
         AND (c.union_id = p_tournament_club
              OR EXISTS (SELECT 1 FROM public.union_clubs uc
                          WHERE uc.club_id = c.id AND uc.union_id = p_tournament_club)));
  END IF;
  SELECT c.union_id INTO v_club_union FROM public.clubs c WHERE c.id = p_tournament_club;
  IF v_club_union IS NOT NULL THEN
    -- Club in a union: member of the club itself or any sibling club in the union.
    RETURN EXISTS (
      SELECT 1 FROM public.club_members cm JOIN public.clubs c ON c.id = cm.club_id
       WHERE cm.user_id = p_user_id
         AND (c.id = p_tournament_club
              OR c.union_id = v_club_union
              OR EXISTS (SELECT 1 FROM public.union_clubs uc
                          WHERE uc.club_id = c.id AND uc.union_id = v_club_union)));
  END IF;
  -- Standalone club: members only.
  RETURN EXISTS (SELECT 1 FROM public.club_members cm
                  WHERE cm.user_id = p_user_id AND cm.club_id = p_tournament_club);
END $$;


ALTER FUNCTION public.fn_ca_entry_scope_ok(p_user_id uuid, p_tournament_club uuid) OWNER TO postgres;

--
-- Name: fn_ca_epoch3_cert_fleet_reset(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_epoch3_cert_fleet_reset(p_confirm text DEFAULT NULL::text, p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_accounts int; v_rows int; v_chips numeric; v_promo numeric;
  v_pre jsonb; v_zeroed int;
BEGIN
  SELECT count(DISTINCT cm.user_id), count(*),
         COALESCE(sum(cm.chip_balance), 0), COALESCE(sum(cm.promo_balance), 0)
    INTO v_accounts, v_rows, v_chips, v_promo
    FROM club_members cm
   WHERE public.fn_ca_is_cert_account(cm.user_id)
     AND (cm.chip_balance > 0 OR cm.promo_balance > 0);

  IF p_dry_run THEN
    RETURN jsonb_build_object('dry_run', true,
      'cert_accounts_holding_value', v_accounts,
      'membership_rows', v_rows,
      'chips_to_retire', round(v_chips, 2),
      'promo_to_retire', round(v_promo, 2),
      'note', 'execution requires the epoch-3 confirmation literal and a passing preflight');
  END IF;

  IF p_confirm IS DISTINCT FROM 'MIDWAY-EPOCH-3-RESET' THEN
    RAISE EXCEPTION 'cert-fleet reset refused: confirmation literal missing';
  END IF;
  v_pre := public.fn_ca_epoch3_preflight();
  IF NOT COALESCE((v_pre->>'pass')::boolean, false) THEN
    RAISE EXCEPTION 'cert-fleet reset refused: preflight failing - %', v_pre::text;
  END IF;

  PERFORM public.fn_ca_declare_ledger('burn', 'chip_retirement');
  UPDATE club_members cm
     SET chip_balance = 0, promo_balance = 0, updated_at = now()
   WHERE public.fn_ca_is_cert_account(cm.user_id)
     AND (cm.chip_balance > 0 OR cm.promo_balance > 0);
  GET DIAGNOSTICS v_zeroed = ROW_COUNT;

  RETURN jsonb_build_object('dry_run', false,
    'rows_zeroed', v_zeroed,
    'chips_retired', round(v_chips, 2),
    'promo_retired', round(v_promo, 2));
END $$;


ALTER FUNCTION public.fn_ca_epoch3_cert_fleet_reset(p_confirm text, p_dry_run boolean) OWNER TO postgres;

--
-- Name: fn_ca_epoch3_preflight(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_epoch3_preflight() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_open integer; c_susp integer; c_wf integer; v_chain record;
  c_drift integer; v_snap record; v_checks jsonb; v_pass boolean; v_guard_inc integer;
BEGIN
  SELECT count(*) INTO c_open FROM public.ca_drift_incidents
   WHERE status <> 'resolved' AND severity <> 'info';
  SELECT count(*) INTO c_susp FROM public.chip_ledger
   WHERE (from_type='settlement_suspense' OR to_type='settlement_suspense')
     AND created_at > GREATEST('2026-09-01 00:17:00+00'::timestamptz,
                               now() - interval '24 hours');
  SELECT count(*) INTO c_wf FROM public.ca_ledger_write_failures
   WHERE occurred_at > now() - interval '24 hours';
  SELECT * INTO v_chain FROM public.fn_ca_verify_ledger_chain(50000);
  SELECT count(*) INTO v_guard_inc FROM (
    SELECT 1 FROM public.ca_drift_incidents
     WHERE dedupe_key LIKE 'guard-missing:%' AND status <> 'resolved') g;
  SELECT count(*) INTO c_drift FROM public.fn_ca_money_rpc_drift();
  SELECT s.unexplained, s.taken_at INTO v_snap
    FROM public.ca_supply_snapshots s ORDER BY s.taken_at DESC LIMIT 1;

  v_checks := jsonb_build_object(
    'no_open_incidents',        jsonb_build_object('pass', c_open = 0, 'open', c_open),
    'zero_suspense_flow',       jsonb_build_object('pass', c_susp = 0, 'rows', c_susp),
    'zero_write_failures_24h',  jsonb_build_object('pass', c_wf = 0, 'value', c_wf),
    'ledger_chain_clean',       jsonb_build_object('pass', COALESCE(v_chain.breaks,0) = 0,
                                                   'checked', COALESCE(v_chain.checked,0)),
    'guards_all_present',       jsonb_build_object('pass', v_guard_inc = 0, 'open_guard_incidents', v_guard_inc),
    'no_unregistered_rpcs',     jsonb_build_object('pass', c_drift = 0, 'value', c_drift),
    'fresh_supply_snapshot',    jsonb_build_object('pass', v_snap.taken_at > now() - interval '2 hours',
                                                   'taken_at', v_snap.taken_at,
                                                   'unexplained', round(COALESCE(v_snap.unexplained,0),2))
  );
  SELECT bool_and((v->'pass')::boolean) INTO v_pass FROM jsonb_each(v_checks) e(k, v);
  RETURN jsonb_build_object('pass', v_pass, 'checked_at', now(), 'checks', v_checks);
END $$;


ALTER FUNCTION public.fn_ca_epoch3_preflight() OWNER TO postgres;

--
-- Name: fn_ca_escalate_reconcile_criticals(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escalate_reconcile_criticals(p_lookback interval DEFAULT '36:00:00'::interval) RETURNS TABLE(considered integer, filed integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r        record;
  v_seen   integer := 0;
  v_filed  integer := 0;
  v_id     uuid;
  v_class  text;
BEGIN
  FOR r IN
    -- Newest row per entity. An entity critical for a week must not raise
    -- seven incidents; fn_ca_raise_drift_incident counts the recurrence.
    /* THE NEWEST ROW DECIDES, NOT THE NEWEST CRITICAL ROW (2026-09-08).
       The severity filter used to sit in this WHERE, so DISTINCT ON picked
       the newest CRITICAL row per entity rather than the newest row - and
       an entity whose latest reading is ok kept re-escalating its last
       critical for the whole lookback. Deep Stack Society read ok at
       13:01:35 and was escalated again at 13:52 from a 2026-09-07 row.
       Every fix in this repo was being undone on the board for 36 hours. */
    SELECT * FROM (
      SELECT DISTINCT ON (l.entity_type, l.entity_id)
             l.entity_type, l.entity_id, l.drift, l.ledger_balance,
             l.stored_balance, l.run_date, l.metadata, l.severity
        FROM public.ledger_reconcile_log l
       WHERE l.created_at >= now() - p_lookback
       ORDER BY l.entity_type, l.entity_id, l.created_at DESC
    ) newest WHERE newest.severity = 'critical'
  LOOP
    v_seen := v_seen + 1;

    -- Map onto the classifications the estate already routes on rather than
    -- inventing one; an unknown value silently becomes 'unknown' upstream.
    v_class := CASE r.entity_type
      WHEN 'club_treasury'       THEN 'treasury_error'
      WHEN 'frozen_wallets_pool' THEN 'unauthorized_adjustment'
      ELSE 'ledger_imbalance'
    END;

    v_id := public.fn_ca_raise_drift_incident(
      'ledger_reconcile_log:' || r.entity_type,
      v_class,
      'critical',
      'reconcile:' || r.entity_type || ':' || COALESCE(r.entity_id::text, 'global'),
      COALESCE(r.drift, 0),
      r.ledger_balance,
      r.stored_balance,
      -- MUST be one of ledger/projection/cache/reporting/settlement/unknown.
      -- 'database' is not, and passing it is what made 901 calls vanish.
      'ledger',
      r.entity_type,
      r.entity_id,
      CASE WHEN r.entity_type = 'club_treasury' THEN r.entity_id END,
      NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'reconcile_ledger_nightly reported a critical drift for this '
        || r.entity_type || ': the stored balance and the journal disagree.',
      false,
      COALESCE(r.metadata, '{}'::jsonb)
        || jsonb_build_object('run_date', r.run_date,
                              'escalated_by', 'fn_ca_escalate_reconcile_criticals')
    );

    -- NULL means the incident was not filed. Today that is almost always
    -- fn_ca_is_midway_scope declining an entity outside the piloted union,
    -- which is deliberate; anything else now leaves a row in
    -- ca_incident_file_failures instead of disappearing.
    IF v_id IS NOT NULL THEN
      v_filed := v_filed + 1;
    END IF;
  END LOOP;

  considered := v_seen;
  filed := v_filed;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_ca_escalate_reconcile_criticals(p_lookback interval) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_escalate_reconcile_criticals(p_lookback interval); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_escalate_reconcile_criticals(p_lookback interval) IS 'Raises a deduped ca_drift_incidents row for each critical in ledger_reconcile_log. The reconciler writes findings; this is what makes a human hear them. Returns considered/filed so a run that files nothing is visible rather than silent.';


--
-- Name: fn_ca_escrow_apply(uuid, text, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_apply(p_tournament_id uuid, p_what text, p_gross_in numeric DEFAULT 0, p_fee_entries_in numeric DEFAULT 0, p_satellite_fee_in numeric DEFAULT 0, p_bounty_in numeric DEFAULT 0, p_overlay_in numeric DEFAULT 0, p_satellite_in numeric DEFAULT 0, p_prize_out numeric DEFAULT 0, p_bounty_out numeric DEFAULT 0, p_fee_out numeric DEFAULT 0, p_refund numeric DEFAULT 0, p_reserve_out numeric DEFAULT 0, p_reserve_in numeric DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v public.tournament_escrow%ROWTYPE;
  v_spin boolean; e record; v_sat_fee numeric;
  v_prize_in numeric; v_tot numeric; r_p numeric := 0; r_b numeric := 0; r_f numeric := 0;
  v_outflow boolean := COALESCE(p_prize_out, 0) > 0 OR COALESCE(p_bounty_out, 0) > 0 OR COALESCE(p_fee_out, 0) > 0 OR COALESCE(p_refund, 0) > 0;
  r_out numeric := 0; r_in numeric := 0;
  v_sp_prize numeric; v_sp_bounty numeric;
BEGIN
  SELECT * INTO v FROM public.tournament_escrow WHERE tournament_id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    SELECT (COALESCE(t.variant, '') = 'spin' OR COALESCE(t.is_premium_spin, false)) INTO v_spin
      FROM public.tournaments t WHERE t.id = p_tournament_id;
    IF NOT FOUND THEN
      RETURN;
    END IF;
    SELECT * INTO e FROM public.fn_ca_tournament_escrow(p_tournament_id);
    SELECT COALESCE(sum(rr.rake_amount), 0) INTO v_sat_fee FROM public.rake_records rr
     WHERE rr.tournament_id = p_tournament_id AND rr.is_tournament AND rr.source = 'fn_award_satellite_seat';
    v_prize_in := e.prize_in; v_tot := e.prize_in + e.satellite_in + e.bounty_in + e.fee_in;
    IF v_tot > 0 THEN
      r_p := round(e.refund_out * (e.prize_in + e.satellite_in) / v_tot, 2);
      r_b := round(e.refund_out * e.bounty_in / v_tot, 2);
    ELSE
      r_p := e.refund_out;
    END IF;
    r_f := round(e.refund_out - r_p - r_b, 2);
    /* PHASE 5.2: a spin's prize bank also moves through the reserve.
       2026-09-07: read from spin_reserve_ledger, not from the chip_ledger
       spin_entry / spin_prize legs it used to read. Those legs are the DERIVED
       record and one pair of them went missing: on 2026-09-06 at 12:50:38 both
       legs of tournament afa045db landed as `adjustment` rows into
       settlement_suspense with a NULL entity, their intended category
       surviving only inside the description text. The escrow therefore never
       learned that 60.00 had been drawn for a 60.00 prize, and
       fn_settle_tournament_obligation refused the winner's last 4.80 as
       escrow_short - for a day, with an open critical alert nobody could act
       on. spin_reserve_ledger is the record the pool balance itself moved by;
       it cannot be missing while the money has moved. Verified across 18,318
       escrow rows: 0 disagree with it, 1 was missing the legs entirely. */
    SELECT COALESCE(sum(l.amount) FILTER (WHERE l.kind = 'contribution'), 0),
           COALESCE(-sum(l.amount) FILTER (WHERE l.kind = 'jackpot_draw'), 0)
      INTO r_out, r_in
      FROM public.spin_reserve_ledger l
     WHERE l.tournament_id = p_tournament_id
       AND l.kind IN ('contribution', 'jackpot_draw');
    INSERT INTO public.tournament_escrow
      (tournament_id, enforced, gross_in, fee_entries_in, satellite_fee_in, bounty_in, overlay_in, satellite_in,
       prize_out, bounty_out, fee_out, refund_prize, refund_bounty, refund_fee, reserve_out, reserve_in,
       prize_balance, bounty_balance, fee_balance, opened_from)
    VALUES
      (p_tournament_id, true,
       round(e.prize_in + e.bounty_in + (e.fee_in - v_sat_fee), 2), round(e.fee_in - v_sat_fee, 2), round(v_sat_fee, 2),
       e.bounty_in, e.overlay_in, e.satellite_in, e.prize_out, e.bounty_out, e.fee_out, r_p, r_b, r_f, round(r_out, 2), round(r_in, 2),
       round(e.prize_balance - r_out + r_in, 2), e.bounty_balance, e.fee_balance,
       'shadow at first sight (' || p_what || ')')
    ON CONFLICT (tournament_id) DO NOTHING;
    RETURN;
  END IF;

  IF COALESCE(p_refund, 0) > 0 THEN
    v_prize_in := v.gross_in - v.fee_entries_in - v.bounty_in + v.satellite_in;
    v_tot := v.gross_in + v.satellite_in + v.satellite_fee_in;
    IF v_tot > 0 THEN
      r_p := round(p_refund * v_prize_in / v_tot, 2);
      r_b := round(p_refund * v.bounty_in / v_tot, 2);
    ELSE
      SELECT s.prize, s.bounty INTO v_sp_prize, v_sp_bounty
        FROM public.tournaments t2
        CROSS JOIN LATERAL public.fn_tournament_entry_split(t2.buy_in_amount, t2.buy_in_fee, t2.bounty_amount,
               COALESCE(t2.is_bounty, false) OR COALESCE(t2.is_pko, false) OR COALESCE(t2.is_mystery_bounty, false)) s
       WHERE t2.id = p_tournament_id;
      IF COALESCE(v_sp_prize, 0) + COALESCE(v_sp_bounty, 0) > 0 THEN
        r_p := round(p_refund * v_sp_prize / (v_sp_prize + v_sp_bounty + (SELECT COALESCE(t3.buy_in_fee, 0) FROM public.tournaments t3 WHERE t3.id = p_tournament_id)), 2);
        r_b := round(p_refund * v_sp_bounty / (v_sp_prize + v_sp_bounty + (SELECT COALESCE(t3.buy_in_fee, 0) FROM public.tournaments t3 WHERE t3.id = p_tournament_id)), 2);
      ELSE
        r_p := p_refund;
      END IF;
    END IF;
    r_f := round(p_refund - r_p - r_b, 2);
  END IF;

  UPDATE public.tournament_escrow
     SET gross_in = gross_in + COALESCE(p_gross_in, 0),
         fee_entries_in = fee_entries_in + COALESCE(p_fee_entries_in, 0),
         satellite_fee_in = satellite_fee_in + COALESCE(p_satellite_fee_in, 0),
         bounty_in = bounty_in + COALESCE(p_bounty_in, 0),
         overlay_in = overlay_in + COALESCE(p_overlay_in, 0),
         satellite_in = satellite_in + COALESCE(p_satellite_in, 0),
         prize_out = prize_out + COALESCE(p_prize_out, 0),
         bounty_out = bounty_out + COALESCE(p_bounty_out, 0),
         fee_out = fee_out + COALESCE(p_fee_out, 0),
         refund_prize = refund_prize + r_p, refund_bounty = refund_bounty + r_b, refund_fee = refund_fee + r_f,
         reserve_out = reserve_out + COALESCE(p_reserve_out, 0), reserve_in = reserve_in + COALESCE(p_reserve_in, 0),
         updated_at = now()
   WHERE tournament_id = p_tournament_id;
  UPDATE public.tournament_escrow
     SET prize_balance  = round((gross_in - fee_entries_in - bounty_in) + overlay_in + satellite_in - reserve_out + reserve_in - prize_out - refund_prize, 2),
         bounty_balance = round(bounty_in - bounty_out - refund_bounty, 2),
         fee_balance    = round(fee_entries_in + satellite_fee_in - fee_out - refund_fee, 2)
   WHERE tournament_id = p_tournament_id
   RETURNING * INTO v;

  IF v.enforced AND v_outflow
     AND (v.prize_balance < -0.005 OR v.bounty_balance < -0.005 OR v.fee_balance < -0.005) THEN
    RAISE EXCEPTION 'escrow_short: tournament % cannot pay this % - it would leave prize %, bounty %, fee % (chip standard Phase 5.1: an event pays only what it holds)',
      p_tournament_id, p_what, v.prize_balance, v.bounty_balance, v.fee_balance
      USING ERRCODE = 'P0403';
  END IF;
END;
$$;


ALTER FUNCTION public.fn_ca_escrow_apply(p_tournament_id uuid, p_what text, p_gross_in numeric, p_fee_entries_in numeric, p_satellite_fee_in numeric, p_bounty_in numeric, p_overlay_in numeric, p_satellite_in numeric, p_prize_out numeric, p_bounty_out numeric, p_fee_out numeric, p_refund numeric, p_reserve_out numeric, p_reserve_in numeric) OWNER TO postgres;

--
-- Name: fn_ca_escrow_apply_exact_refund(uuid, text, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_apply_exact_refund(p_tournament_id uuid, p_what text, p_refund_prize numeric, p_refund_bounty numeric, p_refund_fee numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v public.tournament_escrow%ROWTYPE;
  v_prize numeric := round(COALESCE(p_refund_prize,0),2);
  v_bounty numeric := round(COALESCE(p_refund_bounty,0),2);
  v_fee numeric := round(COALESCE(p_refund_fee,0),2);
BEGIN
  IF p_tournament_id IS NULL
     OR p_refund_prize IS NULL OR p_refund_bounty IS NULL OR p_refund_fee IS NULL
     OR p_refund_prize::text IN ('NaN','Infinity','-Infinity')
     OR p_refund_bounty::text IN ('NaN','Infinity','-Infinity')
     OR p_refund_fee::text IN ('NaN','Infinity','-Infinity')
     OR p_refund_prize < 0 OR p_refund_bounty < 0 OR p_refund_fee < 0
     OR p_refund_prize IS DISTINCT FROM v_prize
     OR p_refund_bounty IS DISTINCT FROM v_bounty
     OR p_refund_fee IS DISTINCT FROM v_fee
     OR v_prize + v_bounty + v_fee <= 0 THEN
    RAISE EXCEPTION 'exact refund requires finite nonnegative whole-cent rails'
      USING ERRCODE = '22003';
  END IF;

  UPDATE public.tournament_escrow
     SET refund_prize = refund_prize + v_prize,
         refund_bounty = refund_bounty + v_bounty,
         refund_fee = refund_fee + v_fee,
         prize_balance = round(
           (gross_in - fee_entries_in - bounty_in) + overlay_in + satellite_in
           - reserve_out + reserve_in - prize_out - refund_prize - v_prize,2),
         bounty_balance = round(
           bounty_in - bounty_out - refund_bounty - v_bounty,2),
         fee_balance = round(
           fee_entries_in + satellite_fee_in - fee_out - refund_fee - v_fee,2),
         updated_at = now()
   WHERE tournament_id = p_tournament_id
   RETURNING * INTO v;
  IF v.tournament_id IS NULL OR v.enforced IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'exact refund escrow for tournament % is absent or unenforced',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF v.prize_balance IS NULL OR v.bounty_balance IS NULL OR v.fee_balance IS NULL
     OR v.refund_prize IS NULL OR v.refund_bounty IS NULL OR v.refund_fee IS NULL
     OR v.prize_balance::text IN ('NaN','Infinity','-Infinity')
     OR v.bounty_balance::text IN ('NaN','Infinity','-Infinity')
     OR v.fee_balance::text IN ('NaN','Infinity','-Infinity')
     OR v.refund_prize::text IN ('NaN','Infinity','-Infinity')
     OR v.refund_bounty::text IN ('NaN','Infinity','-Infinity')
     OR v.refund_fee::text IN ('NaN','Infinity','-Infinity')
     OR v.prize_balance IS DISTINCT FROM round(v.prize_balance,2)
     OR v.bounty_balance IS DISTINCT FROM round(v.bounty_balance,2)
     OR v.fee_balance IS DISTINCT FROM round(v.fee_balance,2)
     OR v.refund_prize IS DISTINCT FROM round(v.refund_prize,2)
     OR v.refund_bounty IS DISTINCT FROM round(v.refund_bounty,2)
     OR v.refund_fee IS DISTINCT FROM round(v.refund_fee,2)
     OR v.prize_balance < -0.005
     OR v.bounty_balance < -0.005
     OR v.fee_balance < -0.005 THEN
    RAISE EXCEPTION
      'escrow_short: tournament % cannot pay exact % rails %, %, %; balances would be %, %, %',
      p_tournament_id,p_what,v_prize,v_bounty,v_fee,
      v.prize_balance,v.bounty_balance,v.fee_balance USING ERRCODE = 'P0403';
  END IF;
END;
$$;


ALTER FUNCTION public.fn_ca_escrow_apply_exact_refund(p_tournament_id uuid, p_what text, p_refund_prize numeric, p_refund_bounty numeric, p_refund_fee numeric) OWNER TO postgres;

--
-- Name: fn_ca_escrow_balance_drift(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_balance_drift(p_hours integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; e record; v_n int := 0; v_bad int := 0; v_list jsonb := '[]'::jsonb; v_gap numeric := 0;
BEGIN
  FOR r IN SELECT x.* FROM public.tournament_escrow x
            WHERE x.updated_at > now() - make_interval(hours => GREATEST(COALESCE(p_hours, 3), 1))
              AND x.updated_at < now() - interval '2 minutes'   -- a row mid-flight is not a finding
            ORDER BY x.updated_at DESC LIMIT 5000
  LOOP
    v_n := v_n + 1;
    /* Same instant (2026-09-05): the cursor read this row when the loop began,
       and the loop takes tens of seconds over thousands of rows; a payout that
       lands in between moves the shadow and not the row in hand. Re-read the
       balance right before the shadow so both reads are milliseconds apart. */
    SELECT * INTO r FROM public.tournament_escrow x WHERE x.tournament_id = r.tournament_id;
    SELECT * INTO e FROM public.fn_ca_tournament_escrow(r.tournament_id);
    IF abs(r.prize_balance - (e.prize_balance - r.reserve_out + r.reserve_in)) > 0.01 OR abs(r.bounty_balance - e.bounty_balance) > 0.01 OR abs(r.fee_balance - e.fee_balance) > 0.01 THEN
      v_bad := v_bad + 1;
      v_gap := v_gap + abs((r.prize_balance + r.bounty_balance + r.fee_balance) - (e.prize_balance - r.reserve_out + r.reserve_in + e.bounty_balance + e.fee_balance));
      IF v_bad <= 20 THEN
        v_list := v_list || jsonb_build_object('tournament_id', r.tournament_id,
                    'balance', jsonb_build_object('prize', r.prize_balance, 'bounty', r.bounty_balance, 'fee', r.fee_balance),
                    'shadow', jsonb_build_object('prize', e.prize_balance - r.reserve_out + r.reserve_in, 'bounty', e.bounty_balance, 'fee', e.fee_balance));
      END IF;
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_escrow_balance_drift', 'settlement_error', 'warning',
        'escrow-balance-drift:' || r.tournament_id::text,
        round((r.prize_balance + r.bounty_balance + r.fee_balance) - (e.prize_balance - r.reserve_out + r.reserve_in + e.bounty_balance + e.fee_balance), 2),
        round(e.prize_balance - r.reserve_out + r.reserve_in + e.bounty_balance + e.fee_balance, 2), round(r.prize_balance + r.bounty_balance + r.fee_balance, 2),
        'ledger', 'tournament', r.tournament_id, NULL, NULL, NULL, r.tournament_id, NULL, NULL, NULL, NULL,
        format('the maintained escrow balance (prize %s, bounty %s, fee %s) disagrees with the shadow (prize %s, bounty %s, fee %s): a path wrote an operational row the escrow triggers do not read, or the other way round',
               r.prize_balance, r.bounty_balance, r.fee_balance, e.prize_balance, e.bounty_balance, e.fee_balance),
        false, jsonb_build_object('tournament_id', r.tournament_id));
    END IF;
  END LOOP;
  -- PHASE 6.2 (2026-09-05): the kill switch reads the run's total disagreement.
  PERFORM public.fn_ca_kill_switch_trip('fn_ca_escrow_balance_drift', v_gap,
    format('%s escrow rows disagree with the shadow by %s in total', v_bad, round(v_gap, 2)));
  RETURN jsonb_build_object('checked', v_n, 'disagree', v_bad, 'sample', v_list, 'gap', round(v_gap, 2));
END;
$$;


ALTER FUNCTION public.fn_ca_escrow_balance_drift(p_hours integer) OWNER TO postgres;

--
-- Name: fn_ca_escrow_can_pay(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_can_pay(p_tournament_id uuid, p_kind text, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v public.tournament_escrow%ROWTYPE; v_have numeric;
BEGIN
  SELECT * INTO v FROM public.tournament_escrow WHERE tournament_id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('known', false);
  END IF;
  v_have := CASE WHEN p_kind IN ('bounty', 'mystery_bounty', 'bounty_residual') THEN v.bounty_balance
                 WHEN p_kind = 'refund' THEN v.prize_balance + v.bounty_balance + v.fee_balance
                 ELSE v.prize_balance END;
  RETURN jsonb_build_object('known', true, 'enforced', v.enforced, 'available', v_have,
                            'ok', (NOT v.enforced) OR p_amount <= v_have + 0.005,
                            'prize_balance', v.prize_balance, 'bounty_balance', v.bounty_balance, 'fee_balance', v.fee_balance);
END;
$$;


ALTER FUNCTION public.fn_ca_escrow_can_pay(p_tournament_id uuid, p_kind text, p_amount numeric) OWNER TO postgres;

--
-- Name: fn_ca_escrow_incident_closes_when_the_leg_lands(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_incident_closes_when_the_leg_lands(p_incident_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  inc          public.ca_drift_incidents;
  e            record;
  v_ended      timestamptz;
  v_name       text;
  v_fee_at     timestamptz;
  v_fee_src    text;
  v_prize_at   timestamptz;
  v_prize_src  text;
  v_leg        text;
  v_leg_at     timestamptz;
  v_leg_src    text;
  v_cause      text;
BEGIN
  SELECT * INTO inc FROM public.ca_drift_incidents WHERE id = p_incident_id;
  IF NOT FOUND OR inc.status = 'resolved'
     OR inc.source <> 'fn_ca_escrow_vs_counter_check'
     OR inc.entity_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT * INTO e FROM public.fn_ca_tournament_escrow(inc.entity_id);
  IF NOT FOUND THEN RETURN false; END IF;
  IF abs(e.prize_balance) > 0.005 OR abs(e.bounty_balance) > 0.005
     OR abs(e.fee_balance) > 0.005 THEN
    RETURN false;                       -- still owed or still over; stays open
  END IF;

  SELECT t.ended_at, t.name INTO v_ended, v_name
    FROM public.tournaments t WHERE t.id = inc.entity_id;

  SELECT s.settled_at, s.source INTO v_fee_at, v_fee_src
    FROM public.tournament_rake_settlements s
   WHERE s.tournament_id = inc.entity_id AND s.settled_at IS NOT NULL
   ORDER BY s.settled_at DESC LIMIT 1;

  SELECT p.paid_at, p.source INTO v_prize_at, v_prize_src
    FROM public.tournament_payouts p
   WHERE p.tournament_id = inc.entity_id AND p.paid_at IS NOT NULL
   ORDER BY p.paid_at DESC LIMIT 1;

  IF COALESCE(v_fee_at, '-infinity') >= COALESCE(v_prize_at, '-infinity') THEN
    v_leg := 'fee';   v_leg_at := v_fee_at;   v_leg_src := v_fee_src;
  ELSE
    v_leg := 'prize'; v_leg_at := v_prize_at; v_leg_src := v_prize_src;
  END IF;

  v_cause := format(
    'The escrow shadow looked before the %s leg had landed. %s closed %s; the detector filed at %s; the last %s leg landed at %s (source %s), %s minutes after close. Re-read at %s: prize 0.00, bounty 0.00, fee 0.00. No chips moved to close this.',
    v_leg,
    COALESCE(v_name, inc.entity_id::text),
    to_char(v_ended, 'YYYY-MM-DD HH24:MI:SS "UTC"'),
    to_char(inc.detected_at, 'YYYY-MM-DD HH24:MI:SS "UTC"'),
    v_leg,
    COALESCE(to_char(v_leg_at, 'YYYY-MM-DD HH24:MI:SS "UTC"'), '?'),
    COALESCE(v_leg_src, '?'),
    CASE WHEN v_leg_at IS NULL OR v_ended IS NULL THEN '?'
         ELSE round(extract(epoch FROM (v_leg_at - v_ended)) / 60, 1)::text END,
    to_char(now(), 'YYYY-MM-DD HH24:MI:SS "UTC"'));

  UPDATE public.ca_drift_incidents
     SET status = 'resolved',
         resolved_at = now(),
         root_cause = v_cause,
         correction_ref = 'verified: fn_ca_tournament_escrow balances 0.00/0.00/0.00 at '
                          || to_char(now(), 'YYYY-MM-DD HH24:MI:SS "UTC"'),
         resolution = 'Closed by the detector on re-read: the leg it could not see has landed and the event balances. Migration 20260906145058.'
   WHERE id = inc.id AND status <> 'resolved';

  INSERT INTO public.ca_incident_events (incident_id, kind, detail)
  VALUES (inc.id, 'resolved',
          jsonb_build_object('by', 'fn_ca_escrow_incident_closes_when_the_leg_lands',
                             'leg', v_leg, 'leg_landed_at', v_leg_at, 'leg_source', v_leg_src,
                             'ended_at', v_ended,
                             'lag_seconds', CASE WHEN v_leg_at IS NULL OR v_ended IS NULL THEN NULL
                                                 ELSE round(extract(epoch FROM (v_leg_at - v_ended))) END));
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  -- Part 7.3 of the programme record: a handler that writes only to the
  -- Postgres log hides the failure where nobody reads. File it where a person
  -- looks, then let the caller continue.
  INSERT INTO public.ca_incident_file_failures
    (source, dedupe_key, classification, severity, discrepancy, sqlstate, message, db_role, app_name)
  VALUES ('fn_ca_escrow_incident_closes_when_the_leg_lands',
          'close:' || p_incident_id::text, 'settlement_error', 'info', 0,
          SQLSTATE, SQLERRM, current_user, current_setting('application_name', true));
  RETURN false;
END
$$;


ALTER FUNCTION public.fn_ca_escrow_incident_closes_when_the_leg_lands(p_incident_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_escrow_incident_closes_when_the_leg_lands(p_incident_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_escrow_incident_closes_when_the_leg_lands(p_incident_id uuid) IS 'Re-reads one open fn_ca_escrow_vs_counter_check incident against fn_ca_tournament_escrow and resolves it, naming the leg that landed late, when the event balances. Detector bookkeeping; moves no chips. 20260906145058.';


--
-- Name: fn_ca_escrow_on_close(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_on_close() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v public.tournament_escrow%ROWTYPE;
BEGIN
  IF NEW.status <> 'COMPLETED' OR OLD.status = 'COMPLETED' THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v FROM public.tournament_escrow
   WHERE tournament_id = NEW.id FOR UPDATE;
  IF NOT FOUND OR NOT v.enforced THEN
    RETURN NULL;
  END IF;
  IF v.closed_at IS NOT NULL THEN
    IF v.prize_balance = 0 AND v.bounty_balance = 0 AND v.fee_balance = 0
       AND v.close_note = 'atomic satellite terminal receipt: exact zero' THEN
      RETURN NULL;
    END IF;
    RAISE EXCEPTION
      'tournament % reached COMPLETED with contradictory preclosed escrow',
      NEW.id USING ERRCODE = '55000';
  END IF;
  UPDATE public.tournament_escrow
     SET closed_at = now(),
         close_note = CASE
           WHEN abs(v.prize_balance) <= 0.05
            AND abs(v.bounty_balance) <= 0.05
             THEN 'closed at zero'
           ELSE format(
             'closed with prize %s, bounty %s, fee %s still to settle; '
             || 'fn_ca_escrow_vs_counter_check judges this after settlement',
             v.prize_balance, v.bounty_balance, v.fee_balance)
         END
   WHERE tournament_id = NEW.id;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_escrow_on_close() OWNER TO postgres;

--
-- Name: fn_ca_escrow_on_overlay_leg(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_on_overlay_leg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Explicit rows only: the autoledger twin (description 'auto-ledgered ...')
  -- of the same debit is not a second overlay. None has been written since
  -- the lock trigger was fixed on 09-03; the shadow still skips them.
  IF COALESCE(NEW.description, '') LIKE 'auto-ledgered%' THEN RETURN NULL; END IF;
  PERFORM public.fn_ca_escrow_apply(NEW.to_entity_id, 'overlay', p_overlay_in => round(NEW.amount, 2));
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_escrow_on_overlay_leg() OWNER TO postgres;

--
-- Name: fn_ca_escrow_on_rake_record(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_on_rake_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_fee numeric := round(COALESCE(NEW.rake_amount,0),2);
BEGIN
  IF NOT COALESCE(NEW.is_tournament,false) OR NEW.tournament_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF v_fee < 0 AND NEW.source IN (
       'atomic_cancel_tournament',
       'fn_unregister_from_tournament') THEN
    RETURN NULL;
  END IF;
  IF NEW.source = 'fn_award_satellite_seat' THEN
    PERFORM public.fn_ca_escrow_apply(
      NEW.tournament_id,'satellite seat fee',
      p_satellite_fee_in => v_fee,p_satellite_in => -v_fee);
  ELSE
    PERFORM public.fn_ca_escrow_apply(
      NEW.tournament_id,'entry fee',p_fee_entries_in => v_fee);
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_escrow_on_rake_record() OWNER TO postgres;

--
-- Name: fn_ca_escrow_on_rake_settlement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_on_rake_settlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.settled_at IS NULL THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND OLD.settled_at IS NOT NULL THEN RETURN NULL; END IF;
  PERFORM public.fn_ca_escrow_apply(NEW.tournament_id, 'fee settlement', p_fee_out => round(COALESCE(NEW.amount, 0), 2));
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_escrow_on_rake_settlement() OWNER TO postgres;

--
-- Name: fn_ca_escrow_on_reserve_leg(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_on_reserve_leg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.category = 'spin_entry' THEN
    PERFORM public.fn_ca_escrow_apply(NEW.from_entity_id, 'spin pool to reserve', p_reserve_out => round(NEW.amount, 2));
  ELSIF NEW.category = 'spin_prize' THEN
    PERFORM public.fn_ca_escrow_apply(NEW.to_entity_id, 'spin prize from reserve', p_reserve_in => round(NEW.amount, 2));
  END IF;
  RETURN NULL;
END;
$$;


