END;
$$;


ALTER FUNCTION public.fn_ca_escrow_on_seat_payout() OWNER TO postgres;

--
-- Name: fn_ca_escrow_on_seat_transfer_leg(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_on_seat_transfer_leg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.metadata->>'entry_split_version' = '2' THEN
    IF round(NEW.amount,2) IS DISTINCT FROM round((NEW.metadata->>'entry_prize')::numeric
        + (NEW.metadata->>'entry_bounty')::numeric + (NEW.metadata->>'entry_fee')::numeric,2)
       OR (NEW.metadata->>'entry_prize')::numeric < 0
       OR (NEW.metadata->>'entry_bounty')::numeric < 0
       OR (NEW.metadata->>'entry_fee')::numeric < 0 THEN
      RAISE EXCEPTION 'Satellite transfer does not match its funded split' USING ERRCODE='23514';
    END IF;
    PERFORM public.fn_ca_escrow_apply(NEW.to_entity_id, 'satellite split entry',
      p_gross_in => round(NEW.amount - (NEW.metadata->>'entry_fee')::numeric,2),
      p_bounty_in => (NEW.metadata->>'entry_bounty')::numeric);
    RETURN NULL;
  END IF;
  PERFORM public.fn_ca_escrow_apply(NEW.to_entity_id, 'satellite seat in', p_satellite_in => round(NEW.amount, 2));
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_escrow_on_seat_transfer_leg() OWNER TO postgres;

--
-- Name: fn_ca_escrow_on_wallet_tx(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_on_wallet_tx() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cat text := lower(COALESCE(NEW.category,''));
  v_amt numeric := round(COALESCE(NEW.amount,0),2);
  v_bounty numeric;
  v_split record;
  v_ent_count bigint;
  v_ent_amount numeric;
  v_wallet_count bigint;
  v_wallet_amount numeric;
  v_exact_token uuid := NULLIF(
    current_setting('app.ca_exact_refund_token',true),'')::uuid;
  v_authorization public.tournament_refund_authorizations%ROWTYPE;
  v_rows integer;
  v_credit_ledger_id uuid;
BEGIN
  IF NEW.related_entity_id IS NULL OR v_amt = 0 THEN RETURN NULL; END IF;
  IF NEW.type = 'debit' AND v_cat IN ('tournament_buyin','rebuy','addon') THEN
    SELECT * INTO v_split FROM public.fn_ca_tournament_charge_split(
      NEW.related_entity_id,v_cat,v_amt);
    SELECT count(*),round(COALESCE(sum(e.gross),0),2)
      INTO v_ent_count,v_ent_amount
      FROM public.tournament_refund_entitlements e
     WHERE e.tournament_id=NEW.related_entity_id AND e.user_id=NEW.user_id
       AND e.entitlement_kind='wallet_charge'
       AND e.charge_category=v_cat;
    SELECT count(*),round(COALESCE(sum(w.amount),0),2)
      INTO v_wallet_count,v_wallet_amount
      FROM public.wallet_transactions w
     WHERE w.related_entity_id=NEW.related_entity_id AND w.user_id=NEW.user_id
       AND w.type='debit' AND lower(w.category)=v_cat;
    IF v_ent_count IS DISTINCT FROM v_wallet_count
       OR v_ent_amount IS DISTINCT FROM v_wallet_amount THEN
      RAISE EXCEPTION
        'tournament wallet debit has no exact immutable charge entitlement'
        USING ERRCODE = 'P0404';
    END IF;
    v_bounty := v_split.refund_bounty;
    PERFORM public.fn_ca_escrow_apply(
      NEW.related_entity_id,v_cat,p_gross_in => v_amt,p_bounty_in => v_bounty);
  ELSIF NEW.type = 'credit' AND v_cat = 'prize' THEN
    PERFORM public.fn_ca_escrow_apply(
      NEW.related_entity_id,'prize',p_prize_out => v_amt);
  ELSIF NEW.type = 'debit' AND v_cat IN ('prize','prize_reversal') THEN
    PERFORM public.fn_ca_escrow_apply(
      NEW.related_entity_id,'prize reversal',p_prize_out => -v_amt);
  ELSIF NEW.type = 'credit' AND v_cat = 'bounty' THEN
    PERFORM public.fn_ca_escrow_apply(
      NEW.related_entity_id,'bounty',p_bounty_out => v_amt);
  ELSIF NEW.type = 'credit' AND v_cat IN ('refund','tournament_refund') THEN
    IF v_exact_token IS NULL THEN
      RAISE EXCEPTION
        'tournament refund credits require the one-use exact refund authority'
        USING ERRCODE = '42501';
    ELSE
      SELECT * INTO v_authorization
        FROM public.tournament_refund_authorizations a
       WHERE a.token = v_exact_token FOR UPDATE;
      IF v_authorization.token IS NULL
         OR v_authorization.tournament_id IS DISTINCT FROM NEW.related_entity_id
         OR v_authorization.user_id IS DISTINCT FROM NEW.user_id
         OR v_authorization.amount_paid_now IS DISTINCT FROM v_amt
         OR v_authorization.description IS DISTINCT FROM NEW.description
         OR NOT EXISTS (
           SELECT 1 FROM public.tournament_refund_entitlements e
            WHERE e.id=v_authorization.entitlement_id
              AND e.tournament_id=NEW.related_entity_id
              AND e.user_id=NEW.user_id
              AND e.refund_wallet_club_id=
                    v_authorization.source_wallet_club_id
              AND e.gross=v_authorization.amount_paid_now
              AND e.refund_prize=v_authorization.refund_prize
              AND e.refund_bounty=v_authorization.refund_bounty
              AND e.refund_fee=v_authorization.refund_fee)
         OR NOT EXISTS (
           SELECT 1 FROM public.tournament_obligations o
            WHERE o.id = v_authorization.obligation_id
              AND o.tournament_id = NEW.related_entity_id
              AND o.kind = 'refund' AND o.place IS NULL
              AND o.user_id = NEW.user_id
              AND o.amount_paid IS NOT DISTINCT FROM
                    v_authorization.amount_paid_before)
         OR NOT EXISTS (
           SELECT 1 FROM public.wallet_credit_idempotency k
            WHERE k.key = v_authorization.idempotency_key
              AND k.user_id = NEW.user_id AND k.amount = v_amt) THEN
        RAISE EXCEPTION 'wallet refund has no exact authorized component tranche'
          USING ERRCODE = 'P0404';
      END IF;
      DELETE FROM public.tournament_refund_authorizations a
       WHERE a.token = v_exact_token;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 THEN
        RAISE EXCEPTION 'exact refund authorization was not consumed once'
          USING ERRCODE = '40001';
      END IF;
      SELECT count(*),min(l.id::text)::uuid
        INTO v_rows,v_credit_ledger_id
        FROM public.chip_ledger l
       WHERE l.idempotency_key = v_authorization.idempotency_key
         AND l.tournament_id = NEW.related_entity_id
         AND l.club_id = v_authorization.source_wallet_club_id
         AND l.category = 'refund'
         AND l.from_type = 'prize_liability'
         AND l.from_entity_id = NEW.related_entity_id
         AND l.to_type = 'player_wallet'
         AND l.to_entity_id = NEW.user_id
         AND l.amount = v_amt;
      IF v_rows <> 1 OR v_credit_ledger_id IS NULL THEN
        RAISE EXCEPTION
          'wallet refund has no single exact source-club journal credit'
          USING ERRCODE = 'P0404';
      END IF;
      INSERT INTO public.tournament_refund_tranches(
        wallet_transaction_id,idempotency_key,tournament_id,obligation_id,user_id,
        source_wallet_club_id,entitlement_id,credit_ledger_id,
        amount_paid_before,amount_paid_now,refund_prize,refund_bounty,refund_fee,
        source,description,created_at)
      VALUES(
        NEW.id,v_authorization.idempotency_key,NEW.related_entity_id,
        v_authorization.obligation_id,NEW.user_id,
        v_authorization.source_wallet_club_id,
        v_authorization.entitlement_id,v_credit_ledger_id,
        v_authorization.amount_paid_before,v_amt,
        v_authorization.refund_prize,v_authorization.refund_bounty,
        v_authorization.refund_fee,v_authorization.source,
        NEW.description,transaction_timestamp());
      PERFORM public.fn_ca_escrow_apply_exact_refund(
        NEW.related_entity_id,'authorized exact refund',
        v_authorization.refund_prize,v_authorization.refund_bounty,
        v_authorization.refund_fee);
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_escrow_on_wallet_tx() OWNER TO postgres;

--
-- Name: fn_ca_escrow_ttl_sweep(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_ttl_sweep() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r RECORD; n int := 0;
BEGIN
  FOR r IN
    SELECT * FROM chip_escrow_holds
     WHERE status = 'active' AND expires_at IS NOT NULL
       AND expires_at < now() - interval '10 minutes'
     LIMIT 25
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_escrow_ttl_sweep', 'settlement_error', 'warning',
      'escrow-expired:' || r.id::text,
      r.amount, r.amount, 0, 'settlement', 'chip_escrow_holds', r.user_id,
      r.club_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'escrow hold (' || r.hold_type || ') expired ' ||
        floor(extract(epoch FROM now() - r.expires_at)/60) || ' min ago but was never released',
      NULL, jsonb_build_object('hold_id', r.id, 'hold_type', r.hold_type,
                               'related_id', r.related_id, 'expires_at', r.expires_at));
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;


ALTER FUNCTION public.fn_ca_escrow_ttl_sweep() OWNER TO postgres;

--
-- Name: fn_ca_escrow_vs_counter_check(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_escrow_vs_counter_check(p_hours integer DEFAULT 3, p_warning_cap integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_started      timestamptz := clock_timestamp();
  v_run_now      timestamptz := now();
  v_cutoff       timestamptz := now() - make_interval(hours => GREATEST(COALESCE(p_hours, 3), 1));
  r              record;
  e              record;
  v_terminal     boolean;
  v_asserted     boolean;
  v_verdict      text;
  v_sev          text;
  v_inc          uuid;
  v_total        numeric;
  v_candidates   integer := 0;
  v_asserted_n   integer := 0;
  v_balanced     integer := 0;
  v_overpaid     integer := 0;
  v_underpaid    integer := 0;
  v_over_total   numeric := 0;
  v_under_total  numeric := 0;
  v_spins        integer := 0;
  v_open         integer := 0;
  v_gap_events   integer := 0;
  v_info         integer := 0;
  v_warn         integer := 0;
  v_warn_capped  integer := 0;
  v_reread       integer := 0;
  v_self_closed  integer := 0;
  v_by_variant   jsonb;
  v_summary      jsonb;
  v_state        text;
  v_msg          text;
BEGIN
  /* 2026-09-06 (H2): what this detector filed and still holds open is re-read
     first. A settlement leg that landed after the detector looked - a fee
     settled by the sweep, a place paid by the reconciler - leaves an incident
     that the board shows as owed money for days. The detector closes its own
     false alarm, naming the leg and the lag, and moves no chips. */
  FOR r IN
    SELECT i.id
      FROM public.ca_drift_incidents i
     WHERE i.source = 'fn_ca_escrow_vs_counter_check'
       AND i.status <> 'resolved'
       AND i.entity_id IS NOT NULL
     ORDER BY i.detected_at
     LIMIT 500
  LOOP
    v_reread := v_reread + 1;
    IF public.fn_ca_escrow_incident_closes_when_the_leg_lands(r.id) THEN
      v_self_closed := v_self_closed + 1;
    END IF;
  END LOOP;

  FOR r IN
    SELECT t.id, t.name, t.variant, t.status, t.club_id, t.union_id, t.ended_at,
           round(COALESCE(t.prize_pool, 0), 2)                                    AS counter_prize_pool,
           round(COALESCE(t.bounty_pool, 0) - COALESCE(t.bounty_pool_paid, 0), 2) AS counter_bounty_open,
           round(COALESCE(t.total_rake, 0), 2)                                    AS counter_total_rake
      FROM public.tournaments t
     WHERE (t.status = 'COMPLETED' AND t.ended_at > v_cutoff)
        OR (t.status IN ('RUNNING','COMPLETING','CANCELLED','CANCELED')
            AND t.start_time > v_cutoff - interval '3 days'
            AND COALESCE(t.updated_at, t.ended_at, t.started_at, t.created_at) > v_cutoff)
     ORDER BY t.ended_at DESC NULLS LAST
     LIMIT 20000
  LOOP
    v_candidates := v_candidates + 1;

    SELECT * INTO e FROM public.fn_ca_tournament_escrow(r.id);
    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    v_terminal := r.status IN ('COMPLETED','CANCELLED','CANCELED');
    v_asserted := v_terminal AND COALESCE(r.variant, '') <> 'spin';
    v_total    := round(e.prize_balance + e.bounty_balance + e.fee_balance, 2);

    IF NOT v_terminal THEN
      v_open := v_open + 1;
    ELSIF NOT v_asserted THEN
      v_spins := v_spins + 1;
    END IF;

    IF abs(r.counter_prize_pool - (e.prize_in + e.overlay_in + e.satellite_in)) > 0.005 THEN
      v_gap_events := v_gap_events + 1;
    END IF;

    v_verdict := 'not_asserted';
    v_inc := NULL;

    IF v_asserted THEN
      v_asserted_n := v_asserted_n + 1;
      IF abs(e.prize_balance) <= 0.005 AND abs(e.bounty_balance) <= 0.005
         AND abs(e.fee_balance) <= 0.005 THEN
        v_verdict := 'balanced';
        v_balanced := v_balanced + 1;
      ELSE
        IF v_total < 0 THEN
          v_verdict := 'overpaid';
          v_overpaid := v_overpaid + 1;
          v_over_total := v_over_total + v_total;
        ELSE
          v_verdict := 'underpaid';
          v_underpaid := v_underpaid + 1;
          v_under_total := v_under_total + v_total;
        END IF;

        -- ONE incident per tournament. Info by default (dashboard only, never
        -- paged). Warning only when the event paid more than it held by over
        -- one chip, and at most p_warning_cap warnings per run so a backlog
        -- can never become a push storm; the rest are filed as info with the
        -- cap noted.
        v_sev := 'info';
        IF e.prize_balance < -1.00 THEN
          IF v_warn < GREATEST(COALESCE(p_warning_cap, 5), 0) THEN
            v_sev := 'warning';
          ELSE
            v_warn_capped := v_warn_capped + 1;
          END IF;
        END IF;

        BEGIN
          v_inc := public.fn_ca_raise_drift_incident(
            p_source          => 'fn_ca_escrow_vs_counter_check',
            p_classification  => 'settlement_error',
            p_severity        => v_sev,
            p_dedupe_key      => 'escrow:' || r.id::text,
            p_discrepancy     => abs(v_total),
            p_expected        => round(e.prize_in + e.bounty_in + e.fee_in + e.overlay_in + e.satellite_in, 2),
            p_actual          => round(e.prize_out + e.bounty_out + e.fee_out + e.refund_out, 2),
            p_layer           => 'ledger',
            p_entity_type     => 'tournament',
            p_entity_id       => r.id,
            p_club_id         => r.club_id,
            p_union_id        => r.union_id,
            p_table_id        => NULL,
            p_tournament_id   => r.id,
            p_hand_id         => NULL,
            p_settlement_id   => NULL,
            p_wallet_ids      => NULL,
            p_transaction_ids => NULL,
            p_suspected_cause => left(format(
              'Escrow shadow (R5): %s (%s) closed with prize %s, bounty %s, fee %s left in escrow (negative = paid more than it held). Held %s, paid %s.',
              COALESCE(r.name, r.id::text), COALESCE(r.variant, '?'),
              e.prize_balance, e.bounty_balance, e.fee_balance,
              round(e.prize_in + e.bounty_in + e.fee_in + e.overlay_in + e.satellite_in, 2),
              round(e.prize_out + e.bounty_out + e.fee_out + e.refund_out, 2)), 300),
            p_ledger_balanced => false,
            p_metadata        => jsonb_build_object(
              'shadow', true, 'never_refuses', true,
              'variant', r.variant, 'status', r.status, 'ended_at', r.ended_at,
              'prize_residual', e.prize_balance, 'bounty_residual', e.bounty_balance,
              'fee_residual', e.fee_balance, 'total_residual', v_total,
              'prize_in', e.prize_in, 'bounty_in', e.bounty_in, 'fee_in', e.fee_in,
              'overlay_in', e.overlay_in, 'satellite_in', e.satellite_in,
              'prize_out', e.prize_out, 'bounty_out', e.bounty_out,
              'fee_out', e.fee_out, 'refund_out', e.refund_out,
              'counter_prize_pool', r.counter_prize_pool,
              'counter_bounty_open', r.counter_bounty_open,
              'counter_total_rake', r.counter_total_rake,
              'warning_capped', (v_sev = 'info' AND e.prize_balance < -1.00)));
        EXCEPTION WHEN OTHERS THEN
          -- A reporter must never be the thing that fails. Keep going.
          GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
          RAISE WARNING 'fn_ca_escrow_vs_counter_check: incident for % not filed (%: %)', r.id, v_state, v_msg;
          v_inc := NULL;
        END;

        IF v_sev = 'warning' THEN
          v_warn := v_warn + 1;
        ELSE
          v_info := v_info + 1;
        END IF;
      END IF;
    END IF;

    INSERT INTO public.ca_escrow_shadow_results AS s (
      tournament_id, club_id, union_id, name, variant, status, ended_at, checked_at,
      prize_in, bounty_in, fee_in, overlay_in, satellite_in,
      prize_out, bounty_out, fee_out, refund_out,
      prize_balance, bounty_balance, fee_balance,
      counter_prize_pool, counter_bounty_open, counter_total_rake,
      counter_prize_gap, counter_bounty_gap, counter_fee_gap,
      asserted, verdict, incident_id)
    VALUES (
      r.id, r.club_id, r.union_id, r.name, r.variant, r.status, r.ended_at, now(),
      e.prize_in, e.bounty_in, e.fee_in, e.overlay_in, e.satellite_in,
      e.prize_out, e.bounty_out, e.fee_out, e.refund_out,
      e.prize_balance, e.bounty_balance, e.fee_balance,
      r.counter_prize_pool, r.counter_bounty_open, r.counter_total_rake,
      round(r.counter_prize_pool - (e.prize_in + e.overlay_in + e.satellite_in), 2),
      round(r.counter_bounty_open - e.bounty_balance, 2),
      round(r.counter_total_rake - e.fee_in, 2),
      v_asserted, v_verdict, v_inc)
    ON CONFLICT (tournament_id) DO UPDATE SET
      club_id = EXCLUDED.club_id, union_id = EXCLUDED.union_id, name = EXCLUDED.name,
      variant = EXCLUDED.variant, status = EXCLUDED.status, ended_at = EXCLUDED.ended_at,
      checked_at = EXCLUDED.checked_at,
      prize_in = EXCLUDED.prize_in, bounty_in = EXCLUDED.bounty_in, fee_in = EXCLUDED.fee_in,
      overlay_in = EXCLUDED.overlay_in, satellite_in = EXCLUDED.satellite_in,
      prize_out = EXCLUDED.prize_out, bounty_out = EXCLUDED.bounty_out,
      fee_out = EXCLUDED.fee_out, refund_out = EXCLUDED.refund_out,
      prize_balance = EXCLUDED.prize_balance, bounty_balance = EXCLUDED.bounty_balance,
      fee_balance = EXCLUDED.fee_balance,
      counter_prize_pool = EXCLUDED.counter_prize_pool,
      counter_bounty_open = EXCLUDED.counter_bounty_open,
      counter_total_rake = EXCLUDED.counter_total_rake,
      counter_prize_gap = EXCLUDED.counter_prize_gap,
      counter_bounty_gap = EXCLUDED.counter_bounty_gap,
      counter_fee_gap = EXCLUDED.counter_fee_gap,
      asserted = EXCLUDED.asserted, verdict = EXCLUDED.verdict,
      incident_id = COALESCE(EXCLUDED.incident_id, s.incident_id);
  END LOOP;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'variant', v.variant, 'events', v.events, 'balanced', v.balanced,
           'overpaid', v.overpaid, 'underpaid', v.underpaid,
           'overpaid_total', v.overpaid_total, 'underpaid_total', v.underpaid_total)
           ORDER BY v.events DESC), '[]'::jsonb)
    INTO v_by_variant
    FROM (
      SELECT COALESCE(variant, '?') AS variant,
             count(*) AS events,
             count(*) FILTER (WHERE verdict = 'balanced')  AS balanced,
             count(*) FILTER (WHERE verdict = 'overpaid')  AS overpaid,
             count(*) FILTER (WHERE verdict = 'underpaid') AS underpaid,
             round(COALESCE(sum(prize_balance + bounty_balance + fee_balance)
                     FILTER (WHERE verdict = 'overpaid'), 0), 2)  AS overpaid_total,
             round(COALESCE(sum(prize_balance + bounty_balance + fee_balance)
                     FILTER (WHERE verdict = 'underpaid'), 0), 2) AS underpaid_total
        FROM public.ca_escrow_shadow_results
       WHERE asserted AND checked_at >= v_run_now
       GROUP BY 1) v;

  v_summary := jsonb_build_object(
    'hours', p_hours,
    'candidates', v_candidates,
    'asserted', v_asserted_n,
    'balanced', v_balanced,
    'overpaid', v_overpaid,
    'overpaid_total', round(v_over_total, 2),
    'underpaid', v_underpaid,
    'underpaid_total', round(v_under_total, 2),
    'net_residual', round(v_over_total + v_under_total, 2),
    'spins_not_asserted', v_spins,
    'open_not_asserted', v_open,
    'counter_prize_gap_events', v_gap_events,
    'incidents_info', v_info,
    'incidents_warning', v_warn,
    'warnings_capped_to_info', v_warn_capped,
    'open_incidents_reread', v_reread,
    'open_incidents_self_closed', v_self_closed,
    'by_variant', v_by_variant,
    'elapsed_ms', (extract(epoch FROM (clock_timestamp() - v_started)) * 1000)::integer);

  INSERT INTO public.ca_escrow_shadow_runs (hours, elapsed_ms, summary)
  VALUES (p_hours, (v_summary->>'elapsed_ms')::integer, v_summary);

  RETURN v_summary;
END;
$$;


ALTER FUNCTION public.fn_ca_escrow_vs_counter_check(p_hours integer, p_warning_cap integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_escrow_vs_counter_check(p_hours integer, p_warning_cap integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_escrow_vs_counter_check(p_hours integer, p_warning_cap integer) IS 'Hourly shadow escrow check (Chip Accounting Standard R5, shadow). For every tournament that changed in the window: computes fn_ca_tournament_escrow, records it beside the counters in ca_escrow_shadow_results, and for COMPLETED / CANCELLED non-spin events files ONE info incident per event (dedupe escrow:<id>) when any residual is non-zero, warning only when prize residual < -1.00 and only up to p_warning_cap per run. Report-only: never refuses, never raises, never writes tournaments.';


--
-- Name: fn_ca_execute_epoch3_reset(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_execute_epoch3_reset(p_confirm text DEFAULT NULL::text, p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pre jsonb; v_corr uuid := gen_random_uuid();
  v_mint_users integer; v_mint_total numeric;
  v_frozen_rows integer; v_frozen_total numeric;
  r record; v_take numeric; v_retired_mint numeric := 0; v_retired_frozen numeric := 0;
  v_epoch integer;
BEGIN
  IF NOT (current_user IN ('postgres', 'service_role')) THEN
    RAISE EXCEPTION 'epoch-3 reset is operator-only';
  END IF;

  /* THE CONTRACT'S REFUSALS (roadmap 9.8, added 2026-09-08). This function
     destroys balances; before 2026-09-08 nothing recorded them first, nothing
     checked that play had stopped, and there was no restore path. */
  IF NOT p_dry_run THEN
    IF NOT public.fn_platform_frozen() THEN
      RAISE EXCEPTION 'epoch reset refused: the platform is not frozen. It runs inside the :55 maintenance break.'
        USING ERRCODE = '55006';
    END IF;
    IF EXISTS (SELECT 1 FROM public.table_seats WHERE left_at IS NULL) THEN
      RAISE EXCEPTION 'epoch reset refused: % seat(s) are still occupied. Parked is not the same as empty - a stack zeroed under a seated player is a balance that no longer matches what they can see.',
        (SELECT count(*) FROM public.table_seats WHERE left_at IS NULL);
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.ca_epoch_closing_positions cp
       JOIN public.ca_financial_epochs e ON e.id = cp.epoch_id AND e.is_current
       WHERE cp.captured_at > now() - interval '15 minutes'
    ) THEN
      RAISE EXCEPTION 'epoch reset refused: no closing position captured for the current epoch in the last 15 minutes. Run fn_ca_capture_closing_position(p_dry_run => false) first - it is the only evidence of what anybody held, and the only thing a restore can be written from.';
    END IF;
  END IF;

  -- measure the horse mint per user (credits from tournament-attached tables)
  CREATE TEMP TABLE IF NOT EXISTS _mint (user_id uuid, minted numeric) ON COMMIT DROP;
  DELETE FROM _mint;
  INSERT INTO _mint
  SELECT wt.user_id, round(sum(wt.amount), 2)
  FROM public.wallet_transactions wt
  JOIN public.profiles p ON p.id = wt.user_id AND p.is_horse
  WHERE wt.amount > 0 AND wt.category IN ('cashout','table_cashout')
    AND wt.table_id IN (SELECT id FROM public.tables WHERE tournament_id IS NOT NULL)
  GROUP BY wt.user_id;
  SELECT count(*), COALESCE(round(sum(minted),2),0) INTO v_mint_users, v_mint_total FROM _mint;

  SELECT count(*), COALESCE(round(sum(balance),2),0) INTO v_frozen_rows, v_frozen_total
    FROM public.wallets WHERE COALESCE(balance,0) <> 0 AND created_at < '2026-08-22';

  v_pre := public.fn_ca_epoch3_preflight();

  IF p_dry_run THEN
    RETURN jsonb_build_object('dry_run', true, 'would_execute', false,
      'preflight', v_pre,
      'horse_mint_to_retire', jsonb_build_object('users', v_mint_users, 'total', v_mint_total),
      'frozen_pool_to_retire', jsonb_build_object('wallets', v_frozen_rows, 'total', v_frozen_total),
      'correlation_id_preview', v_corr,
      'note', 'run with p_confirm => ''MIDWAY-EPOCH-3-RESET'', p_dry_run => false to execute; preflight must pass');
  END IF;

  IF p_confirm IS DISTINCT FROM 'MIDWAY-EPOCH-3-RESET' THEN
    RAISE EXCEPTION 'epoch-3 reset refused: confirmation literal missing';
  END IF;
  IF NOT COALESCE((v_pre->>'pass')::boolean, false) THEN
    RAISE EXCEPTION 'epoch-3 reset refused: preflight failing - %', v_pre->'checks';
  END IF;

  -- ── 1. retire the horse tournament-cashout mint, ledgered per wallet ──
  PERFORM set_config('app.ledger_category', 'burn', true);
  PERFORM set_config('app.ledger_counterparty', 'chip_retirement', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_correlation', v_corr::text, true);
  FOR r IN SELECT m.user_id, m.minted FROM _mint m WHERE m.minted > 0 LOOP
    DECLARE
      v_left numeric := r.minted; v_club uuid; v_bal numeric;
    BEGIN
      -- drain the user's club balances largest-first until the measured
      -- mint is retired or the balances run out; each debit is ledgered
      LOOP
        EXIT WHEN v_left <= 0;
        SELECT cm.club_id, cm.chip_balance INTO v_club, v_bal
          FROM public.club_members cm
         WHERE cm.user_id = r.user_id AND cm.chip_balance > 0
         ORDER BY cm.chip_balance DESC LIMIT 1
         FOR UPDATE;
        EXIT WHEN v_club IS NULL;
        v_take := LEAST(v_bal, v_left);
        UPDATE public.club_members
           SET chip_balance = round(chip_balance - v_take, 2), updated_at = now()
         WHERE user_id = r.user_id AND club_id = v_club;
        v_retired_mint := v_retired_mint + v_take;
        v_left := round(v_left - v_take, 2);
        v_club := NULL;
      END LOOP;
    END;
  END LOOP;

  -- ── 2. retire the frozen public.wallets pool under the audited escape ──
  PERFORM set_config('app.ledger_maintenance',
    'epoch-3 reset ' || v_corr::text || ' - formal retirement of the frozen 2026-08-21 wallets pool (doc 05 §3)', true);
  INSERT INTO public.chip_ledger
    (performed_by, from_type, from_entity_id, to_type, to_entity_id, amount, category,
     correlation_id, description)
  SELECT '2d1cd6c3-5700-4af9-a271-d4863fdab20d', 'player_wallet', w.user_id,
         'chip_retirement', NULL, round(w.balance, 2), 'burn', v_corr,
         'epoch-3: retirement of frozen legacy wallet balance'
  FROM public.wallets w WHERE COALESCE(w.balance, 0) > 0 AND w.created_at < '2026-08-22';
  UPDATE public.wallets SET balance = 0, updated_at = now() WHERE COALESCE(balance,0) <> 0 AND created_at < '2026-08-22';
  v_retired_frozen := v_frozen_total;

  -- ── 3. close epoch 2, open epoch 3, re-baseline, snapshot ──
  UPDATE public.ca_financial_epochs SET is_current = false, ended_at = now() WHERE is_current;
  INSERT INTO public.ca_financial_epochs (name, description, started_at, is_current)
  VALUES ('epoch-3-midway-reset',
          'Midway master reset on the hardened ledger: horse tournament-mint retired ('
            || round(v_retired_mint,2) || '), frozen 2026-08-21 pool retired ('
            || round(v_retired_frozen,2) || '), correlation ' || v_corr,
          now(), true)
  RETURNING id INTO v_epoch;

  DELETE FROM public.ca_treasury_baseline;
  INSERT INTO public.ca_treasury_baseline (club_id, opening_balance, ledger_at_baseline, unledgered_gap, taken_at)
  SELECT c.id, COALESCE(c.chip_treasury,0), COALESCE(c.chip_treasury,0), 0, now() FROM public.clubs c;
  INSERT INTO public.ca_frozen_pool_baseline (pool, frozen_total, frozen_at, note)
  VALUES ('public.wallets', 0, now(), 'epoch-3: pool formally retired, correlation ' || v_corr);
  PERFORM public.fn_ca_supply_snapshot();

  RETURN jsonb_build_object('executed', true, 'epoch', v_epoch, 'correlation_id', v_corr,
    'horse_mint_retired', round(v_retired_mint, 2),
    'frozen_pool_retired', round(v_retired_frozen, 2),
    'next', 'fn_ca_midway_burnin_gate(24) must pass over horse-only play before Midway/Shark/JAQK reopen');
END $$;


ALTER FUNCTION public.fn_ca_execute_epoch3_reset(p_confirm text, p_dry_run boolean) OWNER TO postgres;

--
-- Name: fn_ca_financial_alert_to_incident(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_financial_alert_to_incident() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dedupe text;
  v_echo_id uuid;
  v_severity text;
BEGIN
  IF NEW.severity <> 'critical' THEN RETURN NEW; END IF;
  IF NEW.source LIKE 'drift_incident:%' THEN RETURN NEW; END IF;

  v_dedupe := CASE
      WHEN NEW.source ~* 'prize_credit_failed' AND NULLIF(NEW.context->>'tournament_id','') IS NOT NULL
        THEN 'fa:prize_credit_failed:' || (NEW.context->>'tournament_id')
      ELSE 'fa:' || NEW.source || ':' || md5(left(NEW.message, 200)) END;

  -- Echo of a recently resolved incident: identical dedupe key AND identical
  -- suspected cause, resolved within 48h. Fold, do not re-page.
  SELECT i.id INTO v_echo_id FROM public.ca_drift_incidents i
   WHERE i.dedupe_key = v_dedupe AND i.status = 'resolved'
     AND i.resolved_at > now() - interval '48 hours'
     AND i.suspected_cause = left(NEW.message, 300)
   ORDER BY i.resolved_at DESC LIMIT 1;
  IF v_echo_id IS NOT NULL THEN
    UPDATE public.ca_drift_incidents
       SET occurrences = occurrences + 1
     WHERE id = v_echo_id;
    INSERT INTO public.ca_incident_events (incident_id, at, kind, actor_label, detail)
    VALUES (v_echo_id, now(), 'comment', 'system',
            jsonb_build_object('note', 'Byte-identical echo of this resolved incident re-reported by '
              || NEW.source || '; folded without re-paging (alert ' || NEW.id || ').'));
    RETURN NEW;
  END IF;

  v_severity := CASE
      /* Play-chip conservation: contained as info, never paged. Ruled
         2026-08-31 (alert audit round 3). */
      WHEN NEW.source ~* 'conservation' THEN 'info'
      /* A prize credit that failed for a cert/horse payee is a known,
         root-caused condition (club-less fleet in a union freeroll) that
         deprives no real player: tracked, tallied, never paged. A real
         player's failed prize stays critical. */
      WHEN NEW.source ~* 'prize_credit_failed'
           AND NULLIF(NEW.context->>'user_id','') IS NOT NULL
           AND public.fn_ca_is_cert_account((NEW.context->>'user_id')::uuid) THEN 'info'
      ELSE 'critical' END;

  PERFORM public.fn_ca_raise_drift_incident(
    p_source         => 'financial_alerts:' || NEW.source,
    p_classification => CASE
        WHEN NEW.source ~* 'rake'                   THEN 'incorrect_rake'
        WHEN NEW.source ~* 'bbj'                    THEN 'bbj_error'
        WHEN NEW.source ~* 'rakeback'               THEN 'incorrect_rakeback'
        WHEN NEW.source ~* 'treasury|guarantee'     THEN 'treasury_error'
        WHEN NEW.source ~* 'payout|prize|bounty'    THEN 'settlement_error'
        WHEN NEW.source ~* 'insurance'              THEN 'settlement_error'
        WHEN NEW.source ~* 'conservation'           THEN 'ledger_imbalance'
        ELSE 'unknown' END,
    p_severity       => v_severity,
    /* One root cause = one incident = one push (per-tournament key for
       prize-credit failures; message-hash key otherwise). */
    p_dedupe_key     => v_dedupe,
    p_discrepancy    => COALESCE(NULLIF(NEW.context->>'discrepancy','')::numeric,
                                 NULLIF(NEW.context->>'amount','')::numeric, 0),
    p_layer          => 'ledger',
    p_club_id        => NULLIF(NEW.context->>'club_id','')::uuid,
    p_tournament_id  => NULLIF(NEW.context->>'tournament_id','')::uuid,
    p_table_id       => NULLIF(NEW.context->>'table_id','')::uuid,
    p_suspected_cause => left(NEW.message, 300),
    p_metadata       => COALESCE(NEW.context,'{}'::jsonb) ||
                        jsonb_build_object('alert_id', NEW.id));
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_ca_financial_alert_to_incident failed: %', SQLERRM;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_financial_alert_to_incident() OWNER TO postgres;

--
-- Name: fn_ca_find_erased_seat_credits(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_find_erased_seat_credits(p_since timestamp with time zone, p_until timestamp with time zone DEFAULT now()) RETURNS TABLE(restore_key text, source text, source_id uuid, table_id uuid, user_id uuid, club_id uuid, amount numeric, credited_at timestamp with time zone, prev_hand bigint, next_hand bigint, is_horse boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (current_user IN ('postgres', 'service_role')) THEN
    RAISE EXCEPTION 'fn_ca_find_erased_seat_credits is operator/service only';
  END IF;
  RETURN QUERY
  WITH h AS (
    SELECT hh.id, hh.table_id, hh.hand_number, hh.created_at, hh.rake_amount, COALESCE(hh.bbj_amount, 0) AS bbj,
           (SELECT sum((q->>'stack')::numeric) FROM jsonb_array_elements(hh.players) q) AS felt,
           (SELECT array_agg((q->>'userId')::uuid ORDER BY q->>'userId') FROM jsonb_array_elements(hh.players) q) AS ids
      FROM public.hand_history hh
     WHERE hh.tournament_id IS NULL
       AND hh.created_at > p_since - interval '30 minutes' AND hh.created_at <= p_until + interval '30 minutes'
  ), pairs AS (
    SELECT h.*, lag(h.felt) OVER w AS prev_felt, lag(h.created_at) OVER w AS prev_at,
           lag(h.hand_number) OVER w AS prev_hand_number, (h.ids = lag(h.ids) OVER w) AS same_players
      FROM h WINDOW w AS (PARTITION BY h.table_id ORDER BY h.hand_number)
  ), quiet AS (
    -- a boundary whose felt moved by exactly -(rake+bbj): nothing arrived IN MEMORY.
    -- Only an absolute-mode write turns that into a loss: a delta-mode write
    -- preserves what memory missed (ca_seat_stack_rebases), so a boundary whose
    -- hand was settled in delta mode is excluded here, whatever memory shows.
    SELECT p.table_id, p.prev_at, p.created_at, p.prev_hand_number, p.hand_number, p.ids
      FROM pairs p
     WHERE p.same_players AND p.prev_felt IS NOT NULL
       AND round(p.felt - p.prev_felt + p.rake_amount + p.bbj, 2) = 0
       AND NOT EXISTS (SELECT 1 FROM public.ca_settlements s
                        WHERE s.settlement_type = 'hand_stacks' AND s.table_id = p.table_id
                          AND s.hand_id = md5('ca-hand:' || p.table_id::text || ':' || p.hand_number::text)::uuid
                          AND s.totals->>'mode' = 'delta')
  ), credits AS (
    SELECT 'pending_addon'::text AS source, pa.id AS source_id, pa.table_id, pa.user_id,
           round(pa.applied_to_stack, 2) AS amount, pa.resolved_at AS credited_at,
           (SELECT l.club_id FROM public.chip_ledger l
             WHERE l.category = 'addon' AND l.from_entity_id = pa.user_id AND l.to_entity_id = pa.table_id
               AND round(l.amount, 2) = round(pa.amount, 2)
               AND l.created_at BETWEEN pa.created_at - interval '5 seconds' AND pa.created_at + interval '5 seconds'
             ORDER BY abs(extract(epoch FROM (l.created_at - pa.created_at))) LIMIT 1) AS debited_club
      FROM public.table_pending_addons pa
     WHERE pa.resolved_at > p_since AND pa.resolved_at <= p_until AND pa.applied_to_stack > 0
    UNION ALL
    SELECT 'addon_leg', l.id, l.to_entity_id, l.from_entity_id, round(l.amount, 2), l.created_at, l.club_id
      FROM public.chip_ledger l
     WHERE l.category = 'addon' AND l.to_type = 'table_stack' AND l.from_type = 'player_wallet'
       AND l.created_at > p_since AND l.created_at <= p_until
       AND NOT EXISTS (SELECT 1 FROM public.table_pending_addons q
                        WHERE q.user_id = l.from_entity_id AND q.table_id = l.to_entity_id
                          AND round(q.amount, 2) = round(l.amount, 2)
                          AND q.created_at BETWEEN l.created_at - interval '5 seconds' AND l.created_at + interval '5 seconds')
  )
  SELECT ('seat_credit_erased:' || c.source || ':' || c.source_id::text) AS restore_key,
         c.source, c.source_id, c.table_id, c.user_id,
         COALESCE(c.debited_club,
                  (SELECT ts.club_id FROM public.table_seats ts
                    WHERE ts.table_id = c.table_id AND ts.user_id = c.user_id
                    ORDER BY ts.joined_at DESC LIMIT 1),
                  (SELECT t.club_id FROM public.tables t WHERE t.id = c.table_id)) AS club_id,
         c.amount, c.credited_at, q.prev_hand_number::bigint, q.hand_number::bigint,
         COALESCE((SELECT pr.is_horse FROM public.profiles pr WHERE pr.id = c.user_id), false) AS is_horse
    FROM credits c
    JOIN quiet q ON q.table_id = c.table_id AND c.user_id = ANY(q.ids)
                AND c.credited_at > q.prev_at AND c.credited_at <= q.created_at
   WHERE NOT EXISTS (   -- exactly one credit in the window, so the identity attributes it
           SELECT 1 FROM credits c2
            WHERE c2.table_id = c.table_id AND c2.source_id <> c.source_id
              AND c2.credited_at > q.prev_at AND c2.credited_at <= q.created_at)
     AND NOT EXISTS (   -- and no other seat movement on the table between the hands
           SELECT 1 FROM public.chip_ledger l
            WHERE l.created_at > q.prev_at AND l.created_at <= q.created_at
              AND l.category IN ('buyin', 'rebuy', 'horse_funding', 'table_cashout')
              AND (l.to_entity_id = c.table_id OR l.from_entity_id = c.table_id OR l.table_id = c.table_id))
     AND NOT EXISTS (SELECT 1 FROM public.wallet_credit_idempotency k
                      WHERE k.key = 'seat_credit_erased:' || c.source || ':' || c.source_id::text)
   ORDER BY c.credited_at;
END;
$$;


ALTER FUNCTION public.fn_ca_find_erased_seat_credits(p_since timestamp with time zone, p_until timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_find_erased_seat_credits(p_since timestamp with time zone, p_until timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_find_erased_seat_credits(p_since timestamp with time zone, p_until timestamp with time zone) IS 'Lists seat credits erased by an ABSOLUTE-mode hand-stack write (same players, felt in memory moved by exactly -(rake+bbj), one credit in the window, no other seat movement). A boundary settled in delta mode is never reported: the delta write preserves what memory missed (20260904 detector correction).';


--
-- Name: fn_ca_find_tournament_entry_ticket_for(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_find_tournament_entry_ticket_for(p_tournament_id uuid, p_beneficiary_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid:=p_beneficiary_id;
  v_t public.tournaments%ROWTYPE;
  v_split record;
  v_ticket public.tournament_tickets%ROWTYPE;
  v_is_bounty boolean;
  v_candidate_count integer:=0;
BEGIN
  IF p_tournament_id IS NULL OR v_uid IS NULL THEN
    RAISE EXCEPTION 'tournament and beneficiary ids are required'
      USING ERRCODE='22004';
  END IF;
  SELECT * INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id;
  IF v_t.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_not_found','ticket_id',NULL);
  END IF;
  v_is_bounty:=COALESCE(v_t.is_bounty,false)
            OR COALESCE(v_t.is_pko,false)
            OR COALESCE(v_t.is_mystery_bounty,false);
  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_t.buy_in_amount,v_t.buy_in_fee,v_t.bounty_amount,v_is_bounty);
  IF v_split.charge IS NULL OR v_split.prize IS NULL
     OR v_split.bounty IS NULL OR v_split.rake IS NULL
     OR v_split.charge::text IN ('NaN','Infinity','-Infinity')
     OR v_split.prize::text IN ('NaN','Infinity','-Infinity')
     OR v_split.bounty::text IN ('NaN','Infinity','-Infinity')
     OR v_split.rake::text IN ('NaN','Infinity','-Infinity')
     OR v_split.charge<0 OR v_split.prize<0
     OR v_split.bounty<0 OR v_split.rake<0
     OR v_split.charge IS DISTINCT FROM
          round(v_split.prize+v_split.bounty+v_split.rake,2) THEN
    RAISE EXCEPTION 'tournament % has no finite ticket contract',p_tournament_id
      USING ERRCODE='P0404';
  END IF;
  IF v_split.charge=0 THEN
    RETURN jsonb_build_object('ok',true,'ticket_id',NULL);
  END IF;

  -- Presence and validity are separate facts. If an exact-price ticket exists
  -- but its issue proof or scope is unreadable, do not erase it through an
  -- inner join and silently charge the wallet instead.
  SELECT count(*) INTO v_candidate_count
    FROM public.tournament_tickets tk
   WHERE tk.holder_id=v_uid
     AND tk.status='issued'
     AND tk.redemption_mode='tournament_entry_only'
     AND tk.value=v_split.charge
     AND tk.entry_prize=v_split.prize
     AND tk.entry_bounty=v_split.bounty
     AND tk.entry_fee=v_split.rake
     AND EXISTS(
       SELECT 1 FROM public.club_members m
        WHERE m.club_id=tk.club_id AND m.user_id=v_uid
          AND COALESCE(m.status,'active') IN ('active','approved'))
     AND (v_t.club_id IS NULL OR tk.club_id=v_t.club_id)
     AND (v_t.union_id IS NULL OR EXISTS(
       SELECT 1 FROM public.union_clubs uc
        WHERE uc.union_id=v_t.union_id AND uc.club_id=tk.club_id))
     AND public.fn_tournament_club_for_user(
           v_uid,p_tournament_id,tk.club_id) IS NOT DISTINCT FROM tk.club_id;

  SELECT tk.* INTO v_ticket
    FROM public.tournament_tickets tk
    JOIN public.tournament_refund_entitlements source_e
      ON source_e.id=tk.source_refund_entitlement_id
    JOIN public.chip_ledger issue_l
      ON issue_l.idempotency_key='tourney:'
           ||source_e.tournament_id::text
           ||':satellite-ticket-return:'||source_e.id::text
     AND issue_l.from_type='prize_liability'
     AND issue_l.from_entity_id=source_e.tournament_id
     AND issue_l.to_type='escrow' AND issue_l.to_entity_id=tk.id
     AND issue_l.club_id=tk.club_id AND issue_l.amount=tk.value
     AND issue_l.category='ticket_issue'
   WHERE tk.holder_id=v_uid
     AND tk.status='issued'
     AND tk.redemption_mode='tournament_entry_only'
     AND tk.value=v_split.charge
     AND tk.entry_prize=v_split.prize
     AND tk.entry_bounty=v_split.bounty
     AND tk.entry_fee=v_split.rake
     AND source_e.user_id=v_uid
     AND source_e.entitlement_kind IN ('satellite_seat','tournament_ticket')
     AND source_e.gross=tk.value
     AND source_e.refund_prize=tk.entry_prize
     AND source_e.refund_bounty=tk.entry_bounty
     AND source_e.refund_fee=tk.entry_fee
     AND source_e.source_satellite_id=tk.source_satellite_id
     AND source_e.tournament_id=tk.source_tournament_id
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=source_e.id)
     AND EXISTS(
       SELECT 1 FROM public.club_members m
        WHERE m.club_id=tk.club_id AND m.user_id=v_uid
          AND COALESCE(m.status,'active') IN ('active','approved'))
     AND (v_t.club_id IS NULL OR tk.club_id=v_t.club_id)
     AND (v_t.union_id IS NULL OR EXISTS(
       SELECT 1 FROM public.union_clubs uc
        WHERE uc.union_id=v_t.union_id AND uc.club_id=tk.club_id))
     AND public.fn_tournament_club_for_user(
           v_uid,p_tournament_id,tk.club_id) IS NOT DISTINCT FROM tk.club_id
     AND (SELECT count(*) FROM public.chip_transactions issue_tx
           WHERE issue_tx.transaction_type='tournament_ticket_issue'
             AND issue_tx.club_id=tk.club_id
             AND issue_tx.from_user_id IS NULL
             AND issue_tx.to_user_id=v_uid
             AND issue_tx.amount=tk.value
             AND issue_tx.metadata->>'ticket_id'=tk.id::text
             AND issue_tx.metadata->>'entitlement_id'=source_e.id::text
             AND issue_tx.metadata->>'ledger_id'=issue_l.id::text)=1
   ORDER BY tk.created_at,tk.id
   LIMIT 1;

  IF v_ticket.id IS NULL THEN
    IF v_candidate_count>0 THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','matching_tournament_ticket_unavailable',
        'ticket_id',NULL);
    END IF;
    RETURN jsonb_build_object('ok',true,'ticket_id',NULL);
  END IF;
  RETURN jsonb_build_object(
    'ok',true,'ticket_id',v_ticket.id,'ticket_value',v_ticket.value,
    'entry_prize',v_ticket.entry_prize,
    'entry_bounty',v_ticket.entry_bounty,'entry_fee',v_ticket.entry_fee,
    'source_satellite_id',v_ticket.source_satellite_id);
END;
$$;


ALTER FUNCTION public.fn_ca_find_tournament_entry_ticket_for(p_tournament_id uuid, p_beneficiary_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_finding_key(text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_finding_key(p_dedupe_key text, p_classification text, p_layer text, p_club_id uuid, p_union_id uuid) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  k text := COALESCE(p_dedupe_key, '');
  before text;
BEGIN
  FOR i IN 1..4 LOOP
    before := k;
    k := regexp_replace(k, ':[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$', '');
    k := regexp_replace(k, ':[0-9a-fA-F]{32}$', '');
    k := regexp_replace(k, ':[0-9]{4}-[0-9]{2}-[0-9]{2}(-[0-9]{2})?$', '');
    EXIT WHEN k = before;
  END LOOP;

  IF k = '' THEN
    k := COALESCE(p_classification, 'unknown');
  END IF;

  RETURN k
      || '|' || COALESCE(p_layer, 'unknown')
      || '|' || COALESCE(p_club_id::text, '-')
      || '|' || COALESCE(p_union_id::text, '-');
END $_$;


ALTER FUNCTION public.fn_ca_finding_key(p_dedupe_key text, p_classification text, p_layer text, p_club_id uuid, p_union_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_finding_key(p_dedupe_key text, p_classification text, p_layer text, p_club_id uuid, p_union_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_finding_key(p_dedupe_key text, p_classification text, p_layer text, p_club_id uuid, p_union_id uuid) IS 'The identity of a drift FINDING, independent of how many incident rows happen to describe it and of what time it is. Never put a clock or a row id in a notification key again - that is what caused the 2026-08-31 storm and the 2026-09-01 doubles.';


--
-- Name: fn_ca_fk_index_gaps(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_fk_index_gaps(p_parent text DEFAULT 'public.clubs'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'parent', p_parent,
    'checked_at', now(),
    'gaps', COALESCE(jsonb_agg(jsonb_build_object(
              'child_table', g.child_table,
              'child_column', g.child_col,
              'constraint', g.conname,
              'est_rows', g.est_rows
            ) ORDER BY g.est_rows DESC NULLS LAST), '[]'::jsonb))
    FROM (
      SELECT f.child_table, f.child_col, f.conname,
             (SELECT c2.reltuples::bigint FROM pg_class c2 WHERE c2.oid = f.conrelid) AS est_rows
        FROM (
          SELECT c.conrelid,
                 c.conrelid::regclass::text AS child_table,
                 a.attname                  AS child_col,
                 c.conname::text            AS conname,
                 a.attnum
            FROM pg_constraint c
            JOIN unnest(c.conkey) WITH ORDINALITY AS k(attnum, ord) ON true
            JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum
           WHERE c.contype = 'f'
             AND c.confrelid = p_parent::regclass
             AND array_length(c.conkey, 1) = 1
        ) f
       WHERE NOT EXISTS (
         SELECT 1 FROM pg_index i
          WHERE i.indrelid = f.conrelid
            AND i.indisvalid
            AND i.indpred IS NULL
            AND i.indkey[0] = f.attnum
       )
    ) g;
$$;


ALTER FUNCTION public.fn_ca_fk_index_gaps(p_parent text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_fk_index_gaps(p_parent text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_fk_index_gaps(p_parent text) IS 'Every single-column foreign key into p_parent that no valid, non-partial, leading-column index can answer - so the parent cannot be deleted without a sequential scan of that child. Read-only. Asked by scripts/ci/check-club-fk-indexes.mjs on every pull request; nothing schedules it.';


--
-- Name: fn_ca_flag_hand(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_flag_hand(p_hand_id uuid, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_hand   record;
  v_club   uuid;
  v_note   text := btrim(COALESCE(p_note, ''));
  v_row    public.ca_hand_flags%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not signed in' USING ERRCODE = '28000';
  END IF;
  IF char_length(v_note) < 4 THEN
    RAISE EXCEPTION 'say what is wrong with the hand' USING ERRCODE = '22023';
  END IF;

  SELECT h.id, h.table_id, h.hand_number, h.players
    INTO v_hand
    FROM public.hand_history h
   WHERE h.id = p_hand_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such hand' USING ERRCODE = 'P0002';
  END IF;

  IF NOT (v_hand.players @> jsonb_build_array(jsonb_build_object('userId', v_uid::text))) THEN
    RAISE EXCEPTION 'that hand is not yours to flag' USING ERRCODE = '42501';
  END IF;

  SELECT t.club_id INTO v_club FROM public.tables t WHERE t.id = v_hand.table_id;
  IF v_club IS NULL THEN
    RAISE EXCEPTION 'that hand has no club on record, so it cannot reach an operator'
      USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.ca_hand_flags (hand_id, club_id, table_id, hand_number, flagged_by, note)
  VALUES (v_hand.id, v_club, v_hand.table_id, v_hand.hand_number, v_uid, v_note)
  ON CONFLICT (hand_id, flagged_by) DO UPDATE
    SET note = EXCLUDED.note,
        updated_at = now(),
        status = CASE WHEN public.ca_hand_flags.status IN ('resolved', 'dismissed')
                      THEN 'open' ELSE public.ca_hand_flags.status END
  RETURNING * INTO v_row;

  RETURN to_jsonb(v_row);
END;
$$;


ALTER FUNCTION public.fn_ca_flag_hand(p_hand_id uuid, p_note text) OWNER TO postgres;

--
-- Name: fn_ca_fleet_isolation_report(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_fleet_isolation_report(p_limit integer, p_offset integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_limit  int := least(greatest(coalesce(p_limit, 50), 1), 500);
  v_offset int := greatest(coalesce(p_offset, 0), 0);
  v_have_seats  boolean := to_regclass('public.table_seats') is not null;
  v_have_tables boolean := to_regclass('public.tables') is not null;
  v_have_uc     boolean := to_regclass('public.union_clubs') is not null;
  v_have_is_horse boolean := false;
  v_fleet_filter text;
  v_union_join   text;
  v_union_expr   text;
  v_sql   text;
  v_rows  jsonb := '[]'::jsonb;
  v_total int := 0;
  v_notes jsonb := '[]'::jsonb;
begin
  if to_regclass('public.profiles') is not null then
    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = 'profiles' and column_name = 'is_horse'
    ) into v_have_is_horse;
  end if;

  if not v_have_seats or not v_have_tables then
    -- Empty rather than failing, and the envelope says which source was
    -- missing so a zero is never mistaken for a clean bill of health.
    if not v_have_seats then
      v_notes := v_notes || to_jsonb('public.table_seats is not present'::text);
    end if;
    if not v_have_tables then
      v_notes := v_notes || to_jsonb('public.tables is not present'::text);
    end if;
    return jsonb_build_object(
      'ok', true, 'generated_at', now(), 'total', 0, 'limit', v_limit, 'offset', v_offset,
      'rows', '[]'::jsonb, 'complete', false,
      'sources', jsonb_build_object('table_seats', v_have_seats, 'tables', v_have_tables,
                                    'union_clubs', v_have_uc, 'profiles_is_horse', v_have_is_horse),
      'notes', v_notes
    );
  end if;

  -- WHO IS A HORSE. profiles.is_horse is authoritative. Where it cannot
  -- be read, the register this migration creates is the fallback, and a
  -- register that has never been synced yields an empty report with a
  -- note rather than a report full of humans.
  if v_have_is_horse then
    v_fleet_filter := 'exists (select 1 from public.profiles p where p.id = ts.user_id and coalesce(p.is_horse, false))';
  else
    v_fleet_filter := 'exists (select 1 from public.ca_horse_fleet_register r where r.horse_id = ts.user_id and r.retired_at is null)';
    v_notes := v_notes || to_jsonb('profiles.is_horse is unavailable, so the fleet was taken from ca_horse_fleet_register'::text);
  end if;

  if v_have_uc then
    v_union_join := 'left join public.union_clubs uc on uc.club_id = t.club_id ';
    v_union_expr := 'uc.union_id';
  else
    v_union_join := '';
    v_union_expr := 'null::uuid';
    v_notes := v_notes || to_jsonb('public.union_clubs is not present, so every club is its own scope'::text);
  end if;

  v_sql :=
    'with seats as ( '
    || '  select ts.user_id as horse_id, t.club_id, ' || v_union_expr || ' as union_id, ts.table_id '
    || '  from public.table_seats ts '
    || '  join public.tables t on t.id = ts.table_id '
    || v_union_join
    || '  where ts.left_at is null and t.club_id is not null and ts.user_id is not null and ' || v_fleet_filter
    || '), scoped as ( '
    || '  select horse_id, '
    || '         coalesce(union_id, club_id) as scope_id, '
    || '         case when union_id is not null then ''union'' else ''club'' end as scope_kind, '
    || '         club_id, table_id '
    || '  from seats '
    || '), per_scope as ( '
    || '  select horse_id, scope_id, min(scope_kind) as scope_kind, '
    || '         count(*)::int as seats, '
    || '         jsonb_agg(distinct club_id) as club_ids, '
    || '         jsonb_agg(distinct table_id) as table_ids '
    || '  from scoped group by horse_id, scope_id '
    || '), offenders as ( '
    || '  select horse_id, count(*)::int as scope_count '
    || '  from per_scope group by horse_id having count(*) > 1 '
    || ') '
    || 'select (select count(*)::int from offenders), '
    || '       coalesce((select jsonb_agg(r order by r ->> ''horse_id'') from ( '
    || '         select jsonb_build_object( '
    || '           ''horse_id'', o.horse_id, '
    || '           ''scope_count'', o.scope_count, '
    || '           ''scopes'', (select jsonb_agg(jsonb_build_object( '
    || '                          ''scope_kind'', ps.scope_kind, ''scope_id'', ps.scope_id, '
    || '                          ''seats'', ps.seats, ''club_ids'', ps.club_ids, ''table_ids'', ps.table_ids) '
    || '                        order by ps.scope_id) '
    || '                       from per_scope ps where ps.horse_id = o.horse_id) '
    || '         ) as r '
    || '         from offenders o order by o.horse_id limit $1 offset $2 '
    || '       ) x), ''[]''::jsonb)';

  begin
    execute v_sql into v_total, v_rows using v_limit, v_offset;
  exception when others then
    v_notes := v_notes || to_jsonb(('the isolation query could not run: ' || sqlerrm)::text);
    return jsonb_build_object(
      'ok', true, 'generated_at', now(), 'total', 0, 'limit', v_limit, 'offset', v_offset,
      'rows', '[]'::jsonb, 'complete', false,
      'sources', jsonb_build_object('table_seats', v_have_seats, 'tables', v_have_tables,
                                    'union_clubs', v_have_uc, 'profiles_is_horse', v_have_is_horse),
      'notes', v_notes
    );
  end;

  return jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'total', coalesce(v_total, 0),
    'limit', v_limit,
    'offset', v_offset,
    'rows', coalesce(v_rows, '[]'::jsonb),
    'complete', true,
    'sources', jsonb_build_object('table_seats', v_have_seats, 'tables', v_have_tables,
                                  'union_clubs', v_have_uc, 'profiles_is_horse', v_have_is_horse),
    'ruling', 'A horse plays inside its own club or union only. An empty report is the correct answer.',
    'notes', v_notes
  );
end
$_$;


ALTER FUNCTION public.fn_ca_fleet_isolation_report(p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_ca_fleet_overview(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_fleet_overview(p_window_minutes integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_window int := greatest(coalesce(p_window_minutes, 15), 1);
  v_states jsonb;
  v_total  int;
  v_stuck  int;
  v_stuck_ids jsonb;
  v_beat   public.ca_horse_fleet_heartbeat%rowtype;
  v_beat_json jsonb;
  v_tables_live int;
  v_seats_total int;
  v_seats_filled int;
  v_have_tables boolean := to_regclass('public.tables') is not null;
  v_have_seats  boolean := to_regclass('public.table_seats') is not null;
  v_capacity jsonb;
  v_clubs jsonb;
  v_notes jsonb := '[]'::jsonb;
begin
  -- Counts by state, every state present even at zero. A tab that hides
  -- 'busted' because it happens to be zero teaches the operator that
  -- busted is not a thing.
  select coalesce(jsonb_object_agg(s.state, s.n), '{}'::jsonb), coalesce(sum(s.n), 0)
    into v_states, v_total
  from (
    select k.state, coalesce(c.n, 0) as n
    from unnest(array['idle','seated','playing','sitting_out','busted','suspended','retired','unknown']) as k(state)
    left join (
      select state, count(*)::int as n from public.ca_horse_fleet_state group by state
    ) c on c.state = k.state
  ) s;

  -- Stuck: holding a seat and quiet for longer than the window.
  --
  -- MEASURED FROM THE BEST TIMESTAMP AVAILABLE (review M-9). A horse that
  -- has never acted since it sat down IS the case this number exists to
  -- surface - but only once the window has passed. A null last_action_at
  -- used to count as stuck on its own, so the cycle that seats forty
  -- horses published forty state rows with no action to report yet and the
  -- next Health load called a healthy fleet forty stuck seats. The row
  -- carries session_started_at and last_seen_at, so how long the horse has
  -- actually been sitting there is knowable and is what is measured.
  select count(*)::int into v_stuck
  from public.ca_horse_fleet_state
  where state in ('seated','playing')
    and coalesce(last_action_at, session_started_at, last_seen_at)
        < now() - make_interval(mins => v_window);

  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_stuck_ids
  from (
    select jsonb_build_object(
             'horse_id', horse_id, 'club_id', club_id, 'table_id', table_id,
             'state', state, 'last_action_at', last_action_at,
             -- Which timestamp the count actually used, so a row with no
             -- last_action_at does not read as an unexplained finding.
             'stuck_since', coalesce(last_action_at, session_started_at, last_seen_at)
           ) as x
    from public.ca_horse_fleet_state
    where state in ('seated','playing')
      and coalesce(last_action_at, session_started_at, last_seen_at)
          < now() - make_interval(mins => v_window)
    order by coalesce(last_action_at, session_started_at, last_seen_at) asc
    limit 50
  ) t;

  select * into v_beat
  from public.ca_horse_fleet_heartbeat
  order by beat_at desc
  limit 1;

  if v_beat.id is null then
    v_beat_json := null;
    v_notes := v_notes || to_jsonb('no heartbeat has ever been recorded'::text);
  else
    v_beat_json := jsonb_build_object(
      'id', v_beat.id,
      'beat_at', v_beat.beat_at,
      'age_seconds', floor(extract(epoch from (now() - v_beat.beat_at)))::bigint,
      -- Stale once the last beat is older than the window the caller is
      -- asking about. The console states a stale heartbeat loudly.
      'stale', (now() - v_beat.beat_at) > make_interval(mins => v_window),
      'cycle_ms', v_beat.cycle_ms,
      'degraded', v_beat.degraded,
      'horses_total', v_beat.horses_total,
      'horses_seated', v_beat.horses_seated,
      'horses_idle', v_beat.horses_idle,
      'horses_stuck', v_beat.horses_stuck,
      'tables_seen', v_beat.tables_seen,
      'tables_seeded', v_beat.tables_seeded,
      'seats_filled', v_beat.seats_filled,
      'seats_released', v_beat.seats_released,
      'policy_version', v_beat.policy_version,
      'detail', v_beat.detail
    );
  end if;

  -- Capacity. Live tables and their seat count against seats actually
  -- occupied by anybody, horse or human. Contract section 0: a horse
  -- counts everywhere a human counts, so this is a total, not a fleet
  -- total.
  if v_have_tables then
    begin
      execute 'select count(*)::int, coalesce(sum(coalesce(t.max_players, 0)), 0)::int '
           || 'from public.tables t where coalesce(t.status, '''') in (''running'', ''active'', ''waiting'')'
        into v_tables_live, v_seats_total;
    exception when others then
      v_have_tables := false;
      v_notes := v_notes || to_jsonb(('tables could not be read: ' || sqlerrm)::text);
    end;
  else
    v_notes := v_notes || to_jsonb('public.tables is not present, so capacity is unavailable'::text);
  end if;

  if v_have_seats then
    begin
      execute 'select count(*)::int from public.table_seats where left_at is null'
        into v_seats_filled;
    exception when others then
      v_have_seats := false;
      v_notes := v_notes || to_jsonb(('table_seats could not be read: ' || sqlerrm)::text);
    end;
  else
    v_notes := v_notes || to_jsonb('public.table_seats is not present, so occupancy is unavailable'::text);
  end if;

  v_capacity := jsonb_build_object(
    'tables_live', case when v_have_tables then v_tables_live else null end,
    'seats_total', case when v_have_tables then v_seats_total else null end,
    'seats_filled', case when v_have_seats then v_seats_filled else null end,
    'seats_free', case when v_have_tables and v_have_seats
                       then greatest(coalesce(v_seats_total, 0) - coalesce(v_seats_filled, 0), 0)
                       else null end,
    'sources', jsonb_build_object('tables', v_have_tables, 'table_seats', v_have_seats)
  );

  -- Per club allocation: how many horses this club is actually carrying
  -- against the cap its effective policy sets. quota null means no cap,
  -- which is today's answer for every club.
  -- One policy resolution per club, through a LATERAL, rather than one
  -- per field. The Health tab renders every club at once and the engine
  -- is already asking this question on its own cycle.
  select coalesce(jsonb_agg(x order by x ->> 'club_id'), '[]'::jsonb) into v_clubs
  from (
    select jsonb_build_object(
             'club_id', a.club_id,
             'actual', a.n,
             'seated', a.seated,
             'quota', (pol.p ->> 'max_horses')::int,
             'enabled', (pol.p ->> 'enabled')::boolean,
             'paused', (pol.p ->> 'pause_new_seatings')::boolean,
             'headroom', case when pol.p ->> 'max_horses' is null then null
                              else (pol.p ->> 'max_horses')::int - a.n end
           ) as x
    from (
      select club_id,
             count(*)::int as n,
             count(*) filter (where state in ('seated','playing'))::int as seated
      from public.ca_horse_fleet_state
      where club_id is not null
      group by club_id
    ) a
    cross join lateral (select public.fn_ca_fleet_policy_effective(a.club_id) as p) pol
  ) t;

  return jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'window_minutes', v_window,
    'states', v_states,
    'total', coalesce(v_total, 0),
    'stuck', coalesce(v_stuck, 0),
    'stuck_sample', v_stuck_ids,
    'heartbeat', v_beat_json,
    'capacity', v_capacity,
    'clubs', v_clubs,
    'notes', v_notes
  );
end
$$;


ALTER FUNCTION public.fn_ca_fleet_overview(p_window_minutes integer) OWNER TO postgres;

--
-- Name: fn_ca_fleet_pnl(date, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_fleet_pnl(p_from date, p_to date, p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_from date := coalesce(p_from, current_date - 29);
  v_to   date := coalesce(p_to, current_date);
  v_cols text[];

  -- horse_daily_nets
  v_hdn boolean := to_regclass('public.horse_daily_nets') is not null;
  v_hdn_day text; v_hdn_horse text; v_hdn_club text; v_hdn_net text;
  v_hdn_won text; v_hdn_lost text; v_hdn_hands text; v_hdn_stake text;
  v_hdn_expr text;
  v_hdn_used boolean := false;

  -- club_rake_daily_user
  v_crd boolean := to_regclass('public.club_rake_daily_user') is not null;
  v_crd_day text; v_crd_user text; v_crd_club text; v_crd_rake text;
  v_crd_used boolean := false;

  -- ca_club_player_daily
  v_cpd boolean := to_regclass('public.ca_club_player_daily') is not null;
  v_cpd_day text; v_cpd_user text; v_cpd_club text; v_cpd_net text; v_cpd_rake text; v_cpd_hands text;
  v_cpd_used boolean := false;

  v_have_is_horse boolean := false;
  v_fleet_filter text := 'true';

  v_sql text;
  v_by_club jsonb := '[]'::jsonb;
  v_by_stake jsonb := '[]'::jsonb;
  v_by_day jsonb := '[]'::jsonb;
  v_net numeric := 0;
  v_hands numeric := 0;
  v_rake numeric := 0;
  v_notes jsonb := '[]'::jsonb;
begin
  if v_to < v_from then
    return jsonb_build_object('ok', false, 'error', 'range_inverted',
      'message', 'p_to is earlier than p_from', 'from', v_from, 'to', v_to);
  end if;

  if to_regclass('public.profiles') is not null then
    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = 'profiles' and column_name = 'is_horse'
    ) into v_have_is_horse;
  end if;

  -- ---- horse_daily_nets: the fleet's own chip ledger ----------------
  if v_hdn then
    select coalesce(array_agg(column_name::text), '{}') into v_cols
    from information_schema.columns
    where table_schema = 'public' and table_name = 'horse_daily_nets';

    v_hdn_day   := (select x from unnest(array['day','net_date','stat_date','date','as_of_date','as_of','play_date']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_hdn_horse := (select x from unnest(array['horse_id','user_id','profile_id','player_id']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_hdn_club  := (select x from unnest(array['club_id']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_hdn_net   := (select x from unnest(array['net','net_chips','net_amount','chips_net','net_result','profit','result']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_hdn_won   := (select x from unnest(array['won','chips_won','total_winnings','winnings']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_hdn_lost  := (select x from unnest(array['lost','chips_lost','total_losses','losses']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_hdn_hands := (select x from unnest(array['hands','hands_played','hand_count']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_hdn_stake := (select x from unnest(array['stake_band','stakes','big_blind','bb','stake']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);

    -- The ONE derivation this function is allowed: where the table
    -- keeps won and lost but no net, net is won minus lost. Both halves
    -- are still READ, never recomputed from hands.
    if v_hdn_net is not null then
      v_hdn_expr := 'coalesce(h.' || quote_ident(v_hdn_net) || ', 0)';
    elsif v_hdn_won is not null and v_hdn_lost is not null then
      v_hdn_expr := 'coalesce(h.' || quote_ident(v_hdn_won) || ', 0) - coalesce(h.' || quote_ident(v_hdn_lost) || ', 0)';
    else
      v_hdn_expr := null;
    end if;

    if v_hdn_day is null or v_hdn_expr is null then
      v_notes := v_notes || to_jsonb('horse_daily_nets exists but carries no recognised day or net column, so it was not read'::text);
    else
      v_hdn_used := true;
    end if;
  else
    v_notes := v_notes || to_jsonb('public.horse_daily_nets is not present'::text);
  end if;

  if v_hdn_used then
    v_sql :=
      'with src as (select '
      || 'h.' || quote_ident(v_hdn_day) || '::date as d, '
      || coalesce('h.' || quote_ident(v_hdn_club), 'null::uuid') || ' as club_id, '
      || coalesce('h.' || quote_ident(v_hdn_stake) || '::text', 'null::text') || ' as stake_band, '
      || v_hdn_expr || '::numeric as net, '
      || coalesce('coalesce(h.' || quote_ident(v_hdn_hands) || ', 0)', '0') || '::numeric as hands '
      || 'from public.horse_daily_nets h '
      || 'where h.' || quote_ident(v_hdn_day) || '::date between $1 and $2 '
      || case when v_hdn_club is not null
              then 'and ($3::uuid is null or h.' || quote_ident(v_hdn_club) || ' = $3::uuid) '
              else 'and $3::uuid is null ' end
      || ') '
      || 'select coalesce(sum(net), 0), coalesce(sum(hands), 0), '
      || '  coalesce((select jsonb_agg(jsonb_build_object(''club_id'', club_id, ''net'', net, ''hands'', hands) order by club_id) '
      || '            from (select club_id, sum(net) as net, sum(hands) as hands from src group by club_id) a), ''[]''::jsonb), '
      || '  coalesce((select jsonb_agg(jsonb_build_object(''stake_band'', stake_band, ''net'', net, ''hands'', hands) order by stake_band) '
      || '            from (select stake_band, sum(net) as net, sum(hands) as hands from src group by stake_band) b), ''[]''::jsonb), '
      || '  coalesce((select jsonb_agg(jsonb_build_object(''day'', d, ''net'', net, ''hands'', hands) order by d) '
      || '            from (select d, sum(net) as net, sum(hands) as hands from src group by d) c), ''[]''::jsonb) '
      || 'from src';
    begin
      execute v_sql into v_net, v_hands, v_by_club, v_by_stake, v_by_day using v_from, v_to, p_club_id;
      if v_hdn_stake is null then
        v_notes := v_notes || to_jsonb('horse_daily_nets carries no stake column, so the by stake breakdown is a single null band'::text);
      end if;
      if v_hdn_club is null and p_club_id is not null then
        v_notes := v_notes || to_jsonb('horse_daily_nets carries no club_id, so a club filter returns nothing from it'::text);
      end if;
    exception when others then
      v_hdn_used := false;
      v_net := 0; v_hands := 0;
      v_by_club := '[]'::jsonb; v_by_stake := '[]'::jsonb; v_by_day := '[]'::jsonb;
      v_notes := v_notes || to_jsonb(('horse_daily_nets could not be read: ' || sqlerrm)::text);
    end;
  end if;

  -- ---- ca_club_player_daily: the fallback chip source and a rake ----
  if v_cpd then
    select coalesce(array_agg(column_name::text), '{}') into v_cols
    from information_schema.columns
    where table_schema = 'public' and table_name = 'ca_club_player_daily';

    v_cpd_day   := (select x from unnest(array['day','stat_date','date','as_of_date','play_date']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_cpd_user  := (select x from unnest(array['user_id','player_id','profile_id','horse_id']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_cpd_club  := (select x from unnest(array['club_id']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_cpd_net   := (select x from unnest(array['net','net_chips','net_amount','profit','result']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_cpd_rake  := (select x from unnest(array['rake','rake_amount','total_rake','rake_paid','rake_contributed']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_cpd_hands := (select x from unnest(array['hands','hands_played','hand_count']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);

    if v_cpd_day is null or v_cpd_user is null then
      v_notes := v_notes || to_jsonb('ca_club_player_daily exists but carries no recognised day or user column, so it was not read'::text);
    else
      v_cpd_used := true;
    end if;
  else
    v_notes := v_notes || to_jsonb('public.ca_club_player_daily is not present'::text);
  end if;

  -- ---- club_rake_daily_user: rake, kept separate --------------------
  if v_crd then
    select coalesce(array_agg(column_name::text), '{}') into v_cols
    from information_schema.columns
    where table_schema = 'public' and table_name = 'club_rake_daily_user';

    v_crd_day  := (select x from unnest(array['day','stat_date','date','as_of_date','play_date']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_crd_user := (select x from unnest(array['user_id','player_id','profile_id','horse_id']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_crd_club := (select x from unnest(array['club_id']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);
    v_crd_rake := (select x from unnest(array['rake','rake_amount','total_rake','rake_paid','rake_contributed']) with ordinality t(x, o) where x = any (v_cols) order by o limit 1);

    if v_crd_day is null or v_crd_user is null or v_crd_rake is null then
      v_notes := v_notes || to_jsonb('club_rake_daily_user exists but carries no recognised day, user or rake column, so it was not read'::text);
    else
      v_crd_used := true;
    end if;
  else
    v_notes := v_notes || to_jsonb('public.club_rake_daily_user is not present'::text);
  end if;

  -- Both per user tables carry HUMANS as well, so the fleet filter is
  -- not optional. Without it these are club totals, not fleet totals,
  -- and a P and L that quietly counts human money is worse than none.
  -- %s, not %I: the caller substitutes an ALREADY qualified and quoted
  -- column reference such as c."user_id", and %I would quote the whole
  -- thing again into a single identifier that does not exist.
  if v_have_is_horse then
    v_fleet_filter := 'exists (select 1 from public.profiles p where p.id = %s and coalesce(p.is_horse, false))';
  else
    v_fleet_filter := 'exists (select 1 from public.ca_horse_fleet_register r where r.horse_id = %s and r.retired_at is null)';
    v_notes := v_notes || to_jsonb('profiles.is_horse is unavailable, so the fleet was taken from ca_horse_fleet_register'::text);
  end if;

  if v_crd_used then
    begin
      execute
        'select coalesce(sum(coalesce(c.' || quote_ident(v_crd_rake) || ', 0)), 0) '
        || 'from public.club_rake_daily_user c '
        || 'where c.' || quote_ident(v_crd_day) || '::date between $1 and $2 '
        || case when v_crd_club is not null
                then 'and ($3::uuid is null or c.' || quote_ident(v_crd_club) || ' = $3::uuid) '
                else 'and $3::uuid is null ' end
        || 'and ' || format(v_fleet_filter, 'c.' || quote_ident(v_crd_user))
        into v_rake using v_from, v_to, p_club_id;
    exception when others then
      v_crd_used := false;
      v_rake := 0;
      v_notes := v_notes || to_jsonb(('club_rake_daily_user could not be read: ' || sqlerrm)::text);
    end;
  end if;

  -- ca_club_player_daily only fills the CHIP columns when
  -- horse_daily_nets could not be read. Two sources summed into one
  -- total would double count the same hands.
  if v_cpd_used and not v_hdn_used and v_cpd_net is not null then
    begin
      execute
        'with src as (select d.' || quote_ident(v_cpd_day) || '::date as d, '
        || coalesce('d.' || quote_ident(v_cpd_club), 'null::uuid') || ' as club_id, '
        || 'coalesce(d.' || quote_ident(v_cpd_net) || ', 0)::numeric as net, '
        || coalesce('coalesce(d.' || quote_ident(v_cpd_hands) || ', 0)', '0') || '::numeric as hands '
        || 'from public.ca_club_player_daily d '
        || 'where d.' || quote_ident(v_cpd_day) || '::date between $1 and $2 '
        || case when v_cpd_club is not null
                then 'and ($3::uuid is null or d.' || quote_ident(v_cpd_club) || ' = $3::uuid) '
                else 'and $3::uuid is null ' end
        || 'and ' || format(v_fleet_filter, 'd.' || quote_ident(v_cpd_user)) || ') '
        || 'select coalesce(sum(net), 0), coalesce(sum(hands), 0), '
        || '  coalesce((select jsonb_agg(jsonb_build_object(''club_id'', club_id, ''net'', net, ''hands'', hands) order by club_id) '
        || '            from (select club_id, sum(net) as net, sum(hands) as hands from src group by club_id) a), ''[]''::jsonb), '
        || '  coalesce((select jsonb_agg(jsonb_build_object(''day'', d, ''net'', net, ''hands'', hands) order by d) '
        || '            from (select d, sum(net) as net, sum(hands) as hands from src group by d) c), ''[]''::jsonb) '
        || 'from src'
        into v_net, v_hands, v_by_club, v_by_day using v_from, v_to, p_club_id;
      v_notes := v_notes || to_jsonb('chips came from ca_club_player_daily because horse_daily_nets could not be read'::text);
    exception when others then
      v_net := 0; v_hands := 0;
      v_by_club := '[]'::jsonb; v_by_day := '[]'::jsonb;
      v_notes := v_notes || to_jsonb(('ca_club_player_daily could not be read: ' || sqlerrm)::text);
    end;
  end if;

  -- Rake from ca_club_player_daily only where the dedicated rake table
  -- gave nothing, for the same double counting reason.
  if not v_crd_used and v_cpd_used and v_cpd_rake is not null then
    begin
      execute
        'select coalesce(sum(coalesce(d.' || quote_ident(v_cpd_rake) || ', 0)), 0) '
        || 'from public.ca_club_player_daily d '
        || 'where d.' || quote_ident(v_cpd_day) || '::date between $1 and $2 '
        || case when v_cpd_club is not null
                then 'and ($3::uuid is null or d.' || quote_ident(v_cpd_club) || ' = $3::uuid) '
                else 'and $3::uuid is null ' end
        || 'and ' || format(v_fleet_filter, 'd.' || quote_ident(v_cpd_user))
        into v_rake using v_from, v_to, p_club_id;
      v_notes := v_notes || to_jsonb('rake came from ca_club_player_daily because club_rake_daily_user could not be read'::text);
    exception when others then
      v_rake := 0;
      v_notes := v_notes || to_jsonb(('ca_club_player_daily rake could not be read: ' || sqlerrm)::text);
    end;
  end if;

  if not v_hdn_used and not v_cpd_used then
    v_notes := v_notes || to_jsonb('no chip source could be read, so every chip figure is a reported zero and not a measurement'::text);
  end if;

  return jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'from', v_from,
    'to', v_to,
    'club_id', p_club_id,
    'read_only', true,
    'totals', jsonb_build_object(
      'net', v_net,
      'hands', v_hands,
      -- Rake is the platform's revenue, not the fleet's swing. It is
      -- reported beside the chips and never added to them.
      'rake', v_rake
    ),
    'by_club', v_by_club,
    'by_stake', v_by_stake,
    'by_day', v_by_day,
    'sources', jsonb_build_object(
      'horse_daily_nets', jsonb_build_object('present', v_hdn, 'used', v_hdn_used,
        'columns', jsonb_build_object('day', v_hdn_day, 'club', v_hdn_club, 'net', v_hdn_net,
                                      'won', v_hdn_won, 'lost', v_hdn_lost,
                                      'hands', v_hdn_hands, 'stake', v_hdn_stake)),
      'club_rake_daily_user', jsonb_build_object('present', v_crd, 'used', v_crd_used,
        'columns', jsonb_build_object('day', v_crd_day, 'club', v_crd_club, 'user', v_crd_user, 'rake', v_crd_rake)),
      'ca_club_player_daily', jsonb_build_object('present', v_cpd, 'used', v_cpd_used,
        'columns', jsonb_build_object('day', v_cpd_day, 'club', v_cpd_club, 'user', v_cpd_user,
                                      'net', v_cpd_net, 'rake', v_cpd_rake, 'hands', v_cpd_hands)),
      'profiles_is_horse', v_have_is_horse
    ),
    'note', 'Every figure is a sum of rows the platform already keeps. Nothing here recomputes money and nothing here moves a chip.',
    'notes', v_notes
  );
end
$_$;


ALTER FUNCTION public.fn_ca_fleet_pnl(p_from date, p_to date, p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_fleet_policy_effective(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_fleet_policy_effective(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_global   public.ca_horse_fleet_policy%rowtype;
  v_union    public.ca_horse_fleet_policy%rowtype;
  v_club     public.ca_horse_fleet_policy%rowtype;
  v_union_id uuid;
  v_has_union_rows boolean := false;

  v_enabled  boolean;
  v_pause    boolean;
  v_max_h    int;
  v_max_pt   int;
  v_bias     numeric;
  v_min_hum  int;
  v_bands    text[];
  v_variants text[];
  v_schedule jsonb;
begin
  select * into v_global
  from public.ca_horse_fleet_policy
  where scope = 'global'
  limit 1;

  if p_club_id is not null then
    select * into v_club
    from public.ca_horse_fleet_policy
    where scope = 'club' and scope_id = p_club_id
    limit 1;

    -- Fast path: no union scope row anywhere means the club to union
    -- lookup cannot change the answer, so it is not issued.
    select exists (select 1 from public.ca_horse_fleet_policy where scope = 'union')
      into v_has_union_rows;

    if v_has_union_rows then
      -- union_clubs is the mapping settlement reads; clubs.union_id is
      -- the mirror rake routing reads. Either answers this question, and
      -- both are guarded because neither is created by this file.
      if to_regclass('public.union_clubs') is not null then
        begin
          execute 'select uc.union_id from public.union_clubs uc where uc.club_id = $1 limit 1'
            into v_union_id using p_club_id;
        exception when others then
          v_union_id := null;
        end;
      end if;
      if v_union_id is null and to_regclass('public.clubs') is not null then
        begin
          execute 'select c.union_id from public.clubs c where c.id = $1 limit 1'
            into v_union_id using p_club_id;
        exception when others then
          v_union_id := null;
        end;
      end if;
      if v_union_id is not null then
        select * into v_union
        from public.ca_horse_fleet_policy
        where scope = 'union' and scope_id = v_union_id
        limit 1;
      end if;
    end if;
  end if;

  -- THE MERGE. Narrowest scope that expressed an opinion wins. The
  -- final coalesce argument is the hardcoded default, which is today's
  -- behaviour, which is why an empty table is safe.
  v_enabled  := coalesce(v_club.enabled,            v_union.enabled,            v_global.enabled,            true);
  v_pause    := coalesce(v_club.pause_new_seatings, v_union.pause_new_seatings, v_global.pause_new_seatings, false);
  v_max_h    := coalesce(v_club.max_horses,         v_union.max_horses,         v_global.max_horses);
  v_max_pt   := coalesce(v_club.max_per_table,      v_union.max_per_table,      v_global.max_per_table);
  v_bias     := coalesce(v_club.occupancy_bias,     v_union.occupancy_bias,     v_global.occupancy_bias,     1.0);
  v_min_hum  := coalesce(v_club.min_humans_to_seat, v_union.min_humans_to_seat, v_global.min_humans_to_seat, 0);
  v_bands    := coalesce(v_club.stake_bands,        v_union.stake_bands,        v_global.stake_bands);
  v_variants := coalesce(v_club.variants,           v_union.variants,           v_global.variants);
  v_schedule := coalesce(v_club.schedule,           v_union.schedule,           v_global.schedule);

  return jsonb_build_object(
    'ok', true,
    'club_id', p_club_id,
    'union_id', v_union_id,
    'enabled', v_enabled,
    'pause_new_seatings', v_pause,
    'max_horses', v_max_h,
    'max_per_table', v_max_pt,
    'occupancy_bias', v_bias,
    'min_humans_to_seat', v_min_hum,
    'stake_bands', case when v_bands is null then null else to_jsonb(v_bands) end,
    'variants', case when v_variants is null then null else to_jsonb(v_variants) end,
    'schedule', v_schedule,
    'notes', coalesce(v_club.notes, v_union.notes, v_global.notes),
    -- Which row supplied each value. The Policy tab renders this so an
    -- operator can see that a club is capped by ITS row and enabled by
    -- the global one, rather than guessing.
    'source', jsonb_build_object(
      'enabled', case when v_club.enabled is not null then 'club'
                      when v_union.enabled is not null then 'union'
                      when v_global.enabled is not null then 'global'
                      else 'default' end,
      'pause_new_seatings', case when v_club.pause_new_seatings is not null then 'club'
                                 when v_union.pause_new_seatings is not null then 'union'
                                 when v_global.pause_new_seatings is not null then 'global'
                                 else 'default' end,
      'max_horses', case when v_club.max_horses is not null then 'club'
                         when v_union.max_horses is not null then 'union'
                         when v_global.max_horses is not null then 'global'
                         else 'default' end,
      'max_per_table', case when v_club.max_per_table is not null then 'club'
                            when v_union.max_per_table is not null then 'union'
                            when v_global.max_per_table is not null then 'global'
                            else 'default' end,
      'occupancy_bias', case when v_club.occupancy_bias is not null then 'club'
                             when v_union.occupancy_bias is not null then 'union'
                             when v_global.occupancy_bias is not null then 'global'
                             else 'default' end,
      'min_humans_to_seat', case when v_club.min_humans_to_seat is not null then 'club'
                                 when v_union.min_humans_to_seat is not null then 'union'
                                 when v_global.min_humans_to_seat is not null then 'global'
                                 else 'default' end,
      'stake_bands', case when v_club.stake_bands is not null then 'club'
                          when v_union.stake_bands is not null then 'union'
                          when v_global.stake_bands is not null then 'global'
                          else 'default' end,
      'variants', case when v_club.variants is not null then 'club'
                       when v_union.variants is not null then 'union'
                       when v_global.variants is not null then 'global'
                       else 'default' end,
      'schedule', case when v_club.schedule is not null then 'club'
                       when v_union.schedule is not null then 'union'
                       when v_global.schedule is not null then 'global'
                       else 'default' end
    ),
    'rows', jsonb_build_object(
      'global', v_global.scope is not null,
      'union', v_union.scope is not null,
      'club', v_club.scope is not null
    ),
    -- The engine stamps this on its heartbeat, so the console can say
    -- which version of the policy a cycle actually ran under.
    -- Null, not -infinity, when no row exists at all: the heartbeat
    -- stores this verbatim and a sentinel date on the Health tab would
    -- read as a policy written in the far past rather than as none.
    'policy_version', nullif(greatest(
      coalesce(v_club.updated_at,  '-infinity'::timestamptz),
      coalesce(v_union.updated_at, '-infinity'::timestamptz),
      coalesce(v_global.updated_at,'-infinity'::timestamptz)
    ), '-infinity'::timestamptz),
    'defaults_used', (v_global.scope is null and v_union.scope is null and v_club.scope is null)
  );
end
$_$;


ALTER FUNCTION public.fn_ca_fleet_policy_effective(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_fleet_register_sync(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_fleet_register_sync(p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_have_profiles boolean := to_regclass('public.profiles') is not null;
  v_have_is_horse boolean := false;
  v_have_created  boolean := false;
  v_inserted int := 0;
  v_retired  int := 0;
  v_unretired int := 0;
  v_unflagged int := 0;
  v_total    int := 0;
  v_active   int := 0;
  v_audited  boolean := false;
  v_notes    jsonb := '[]'::jsonb;
begin
  if v_have_profiles then
    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = 'profiles' and column_name = 'is_horse'
    ) into v_have_is_horse;
    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = 'profiles' and column_name = 'created_at'
    ) into v_have_created;
  end if;

  if not v_have_profiles or not v_have_is_horse then
    -- Empty rather than failing. Nothing is inserted and nothing is
    -- retired, because with no way to ask who is a horse, retiring the
    -- whole register is the one outcome that must not happen.
    v_notes := v_notes || to_jsonb('profiles.is_horse is unavailable, so nothing was inserted and nothing was retired'::text);
    select count(*)::int, count(*) filter (where retired_at is null)::int
      into v_total, v_active from public.ca_horse_fleet_register;
    return jsonb_build_object(
      'ok', true, 'inserted', 0, 'retired', 0, 'unretired', 0, 'unflagged', 0,
      'total', v_total, 'active', v_active, 'audited', false,
      'sources', jsonb_build_object('profiles', v_have_profiles, 'profiles_is_horse', v_have_is_horse),
      'notes', v_notes
    );
  end if;

  -- INSERT the missing ones. Dynamic because profiles is not this
  -- file's table and created_at may or may not be there.
  execute
    'insert into public.ca_horse_fleet_register (horse_id, disclosed, owner_entity, funding_source, created_at, note) '
    || 'select p.id, true, ''Smarter Poker'', ''club treasury'', '
    || case when v_have_created then 'p.created_at' else 'null::timestamptz' end || ', '
    || '''backfilled from profiles.is_horse'' '
    || 'from public.profiles p '
    || 'where coalesce(p.is_horse, false) '
    || 'on conflict (horse_id) do nothing';
  get diagnostics v_inserted = row_count;

  -- RETIRE the rows whose profile is gone. "No longer exists" is
  -- literal: the profiles row is absent. A profile that merely lost its
  -- is_horse flag is counted and reported, not retired, because that
  -- flag is data an operator can flip by hand and the register is a
  -- legal record.
  update public.ca_horse_fleet_register r
     set retired_at = now(),
         note = coalesce(r.note, '') || ' | retired: profile no longer exists'
   where r.retired_at is null
     and not exists (select 1 from public.profiles p where p.id = r.horse_id);
  get diagnostics v_retired = row_count;

  -- UN-RETIRE anyone who is a horse again. An update, never a delete,
  -- so registered_at keeps saying when the account was first disclosed.
  update public.ca_horse_fleet_register r
     set retired_at = null,
         note = coalesce(r.note, '') || ' | un-retired: profile is is_horse again'
   where r.retired_at is not null
     and exists (select 1 from public.profiles p where p.id = r.horse_id and coalesce(p.is_horse, false));
  get diagnostics v_unretired = row_count;

  select count(*)::int into v_unflagged
  from public.ca_horse_fleet_register r
  join public.profiles p on p.id = r.horse_id
  where r.retired_at is null and not coalesce(p.is_horse, false);

  select count(*)::int, count(*) filter (where retired_at is null)::int
    into v_total, v_active from public.ca_horse_fleet_register;

  if p_actor is not null then
    begin
      perform public.fn_log_admin_action(
        p_admin_user_id := p_actor,
        p_action        := 'fleet.register_sync',
        p_target_type   := 'fleet_register',
        p_target_id     := 'all',
        p_details       := jsonb_build_object(
                             'inserted', v_inserted, 'retired', v_retired,
                             'unretired', v_unretired, 'unflagged', v_unflagged,
                             'total', v_total, 'active', v_active
                           ),
        p_before_state  := null,
        p_after_state   := jsonb_build_object('total', v_total, 'active', v_active),
        p_ip_address    := null,
        p_user_agent    := null,
        p_request_id    := null
      );
      v_audited := true;
    exception when others then
      raise notice 'fn_ca_fleet_register_sync audit failed: %', sqlerrm;
    end;
  else
    v_notes := v_notes || to_jsonb('no actor was supplied, so no audit row was written. fn_log_admin_action refuses a null actor.'::text);
  end if;

  return jsonb_build_object(
    'ok', true,
    'inserted', v_inserted,
    'retired', v_retired,
    'unretired', v_unretired,
    'unflagged', v_unflagged,
    'total', v_total,
    'active', v_active,
    'audited', v_audited,
    'sources', jsonb_build_object('profiles', v_have_profiles, 'profiles_is_horse', v_have_is_horse),
    'disclosure', 'Every row here is a simulated account operated by the platform and disclosed under GLI-19.',
    'notes', v_notes
  );
end
$$;


ALTER FUNCTION public.fn_ca_fleet_register_sync(p_actor uuid) OWNER TO postgres;

--
-- Name: fn_ca_fleet_seat_touch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_fleet_seat_touch(p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare n int := 0; r jsonb;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then return 0; end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    update public.ca_horse_fleet_state s
       set last_action_at = greatest(coalesce(s.last_action_at, 'epoch'::timestamptz),
                                     coalesce(nullif(r->>'at','')::timestamptz, now())),
           hands_this_session = case
             when s.table_id is not null and nullif(r->>'table_id','')::uuid is not null
                  and s.table_id <> nullif(r->>'table_id','')::uuid
             then coalesce((r->>'hands')::int, 0)
             else coalesce(s.hands_this_session, 0) + coalesce((r->>'hands')::int, 0) end,
           session_started_at = case
             when s.table_id is not null and nullif(r->>'table_id','')::uuid is not null
                  and s.table_id <> nullif(r->>'table_id','')::uuid
             then coalesce(nullif(r->>'at','')::timestamptz, now())
             else coalesce(s.session_started_at, nullif(r->>'at','')::timestamptz, now()) end,
           updated_at = now()
     where s.horse_id = nullif(r->>'horse_id','')::uuid;
    if found then n := n + 1; end if;
  end loop;
  return n;
end $$;


ALTER FUNCTION public.fn_ca_fleet_seat_touch(p_rows jsonb) OWNER TO postgres;

--
-- Name: fn_ca_fleet_set_policy(text, uuid, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_fleet_set_policy(p_scope text, p_scope_id uuid, p_patch jsonb, p_updated_by uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  c_fields constant text[] := array[
    'enabled','pause_new_seatings','max_horses','max_per_table','occupancy_bias',
    'min_humans_to_seat','stake_bands','variants','schedule','notes'
  ];
  v_key      text;
  v_type     text;
  v_num      numeric;
  v_elem     jsonb;
  v_before   public.ca_horse_fleet_policy%rowtype;
  v_after    public.ca_horse_fleet_policy%rowtype;
  v_created  boolean := false;
  v_material boolean := false;
  v_reasons  jsonb := '[]'::jsonb;
  v_old_cap  numeric;
  v_new_cap  numeric;
  v_old_bias numeric;
  v_new_bias numeric;
  v_had_list boolean;
  v_old_len  int;
  v_new_len  int;
begin
  -- Scope, first, because everything else depends on which row this is.
  if p_scope is null or p_scope not in ('global','club','union') then
    return jsonb_build_object('ok', false, 'error', 'unknown_scope',
      'message', 'scope must be one of global, club, union',
      'scope', p_scope);
  end if;
  if p_scope = 'global' and p_scope_id is not null then
    return jsonb_build_object('ok', false, 'error', 'scope_id_not_allowed',
      'message', 'the global row has no scope_id');
  end if;
  if p_scope <> 'global' and p_scope_id is null then
    return jsonb_build_object('ok', false, 'error', 'scope_id_required',
      'message', 'a club or union row needs a scope_id');
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    return jsonb_build_object('ok', false, 'error', 'invalid_patch',
      'message', 'p_patch must be a json object');
  end if;
  -- An unattributable policy change is not written down as somebody
  -- else's, and fn_log_admin_action refuses a null actor anyway.
  if p_updated_by is null then
    return jsonb_build_object('ok', false, 'error', 'actor_required',
      'message', 'p_updated_by is required so the change can be audited');
  end if;

  -- Every key must be one this table carries. A typo that silently did
  -- nothing would read on the Policy tab as a change that was applied.
  for v_key in select jsonb_object_keys(p_patch) loop
    if not (v_key = any (c_fields)) then
      return jsonb_build_object('ok', false, 'error', 'unknown_field',
        'message', 'not a policy field', 'field', v_key,
        'known', to_jsonb(c_fields));
    end if;
  end loop;

  -- Type and range, field by field. A json null CLEARS an override and
  -- hands the field back to the wider scope, so null is legal everywhere.
  foreach v_key in array array['enabled','pause_new_seatings'] loop
    if p_patch ? v_key then
      v_type := jsonb_typeof(p_patch -> v_key);
      if v_type not in ('boolean','null') then
        return jsonb_build_object('ok', false, 'error', 'invalid_type',
          'field', v_key, 'expected', 'boolean', 'got', v_type);
      end if;
    end if;
  end loop;

  foreach v_key in array array['max_horses','max_per_table','min_humans_to_seat'] loop
    if p_patch ? v_key then
      v_type := jsonb_typeof(p_patch -> v_key);
      if v_type not in ('number','null') then
        return jsonb_build_object('ok', false, 'error', 'invalid_type',
          'field', v_key, 'expected', 'integer', 'got', v_type);
      end if;
      if v_type = 'number' then
        v_num := (p_patch ->> v_key)::numeric;
        if v_num <> trunc(v_num) then
          return jsonb_build_object('ok', false, 'error', 'not_an_integer',
            'field', v_key, 'value', v_num);
        end if;
        if v_num < 0 then
          return jsonb_build_object('ok', false, 'error', 'negative_cap',
            'message', 'a cap is a count of seats and cannot be negative',
            'field', v_key, 'value', v_num);
        end if;
        if v_key = 'min_humans_to_seat' and v_num > 10 then
          return jsonb_build_object('ok', false, 'error', 'min_humans_out_of_range',
            'message', 'no table seats more than ten players, so this rule could never be met',
            'field', v_key, 'value', v_num);
        end if;
      end if;
    end if;
  end loop;

  if p_patch ? 'occupancy_bias' then
    v_type := jsonb_typeof(p_patch -> 'occupancy_bias');
    if v_type not in ('number','null') then
      return jsonb_build_object('ok', false, 'error', 'invalid_type',
        'field', 'occupancy_bias', 'expected', 'number', 'got', v_type);
    end if;
    if v_type = 'number' then
      v_num := (p_patch ->> 'occupancy_bias')::numeric;
      -- Zero or negative is an eviction dressed as arithmetic: it would
      -- take every table target to zero. Above ten is a fat finger.
      if v_num <= 0 or v_num > 10 then
        return jsonb_build_object('ok', false, 'error', 'bias_out_of_range',
          'message', 'occupancy_bias must be greater than 0 and at most 10',
          'field', 'occupancy_bias', 'value', v_num);
      end if;
    end if;
  end if;

  foreach v_key in array array['stake_bands','variants'] loop
    if p_patch ? v_key then
      v_type := jsonb_typeof(p_patch -> v_key);
      if v_type not in ('array','null') then
        return jsonb_build_object('ok', false, 'error', 'invalid_type',
          'field', v_key, 'expected', 'array of strings', 'got', v_type);
      end if;
      if v_type = 'array' then
        for v_elem in select value from jsonb_array_elements(p_patch -> v_key) loop
          if jsonb_typeof(v_elem) <> 'string' then
            return jsonb_build_object('ok', false, 'error', 'invalid_array',
              'field', v_key, 'message', 'every element must be a string',
              'element', v_elem);
          end if;
        end loop;
      end if;
    end if;
  end loop;

  if p_patch ? 'schedule' then
    v_type := jsonb_typeof(p_patch -> 'schedule');
    if v_type not in ('array','null') then
      return jsonb_build_object('ok', false, 'error', 'invalid_type',
        'field', 'schedule', 'expected', 'array of hour ranges', 'got', v_type);
    end if;
    if v_type = 'array' then
      for v_elem in select value from jsonb_array_elements(p_patch -> 'schedule') loop
        if jsonb_typeof(v_elem) <> 'object'
           or not (v_elem ? 'start_hour') or not (v_elem ? 'end_hour')
           or jsonb_typeof(v_elem -> 'start_hour') <> 'number'
           or jsonb_typeof(v_elem -> 'end_hour') <> 'number' then
          return jsonb_build_object('ok', false, 'error', 'invalid_schedule',
            'message', 'each entry needs numeric start_hour and end_hour',
            'entry', v_elem);
        end if;
        if (v_elem ->> 'start_hour')::numeric < 0 or (v_elem ->> 'start_hour')::numeric > 23
           or (v_elem ->> 'end_hour')::numeric < 0 or (v_elem ->> 'end_hour')::numeric > 23 then
          return jsonb_build_object('ok', false, 'error', 'invalid_schedule',
            'message', 'hours are UTC and run 0 to 23. start greater than end wraps midnight',
            'entry', v_elem);
        end if;
      end loop;
    end if;
  end if;

  if p_patch ? 'notes' and jsonb_typeof(p_patch -> 'notes') not in ('string','null') then
    return jsonb_build_object('ok', false, 'error', 'invalid_type',
      'field', 'notes', 'expected', 'string', 'got', jsonb_typeof(p_patch -> 'notes'));
  end if;

  -- The row as it stands, for the audit and for the materiality test.
  select * into v_before
  from public.ca_horse_fleet_policy
  where scope = p_scope
    and scope_key = coalesce(p_scope_id, '00000000-0000-0000-0000-000000000000'::uuid);
  v_created := v_before.scope is null;

  -- MATERIALITY, exactly as contract section 0 words it.
  if p_patch ? 'enabled'
     and coalesce((p_patch ->> 'enabled')::boolean, true) is distinct from coalesce(v_before.enabled, true) then
    v_material := true;
    v_reasons := v_reasons || to_jsonb('enabled_changed'::text);
  end if;
  -- Pausing new seatings is disabling the fleet for that scope by
  -- another name, so it is held to the same standard.
  if p_patch ? 'pause_new_seatings'
     and coalesce((p_patch ->> 'pause_new_seatings')::boolean, false) is distinct from coalesce(v_before.pause_new_seatings, false) then
    v_material := true;
    v_reasons := v_reasons || to_jsonb('pause_changed'::text);
  end if;
  foreach v_key in array array['max_horses','max_per_table'] loop
    if p_patch ? v_key then
      v_old_cap := case v_key when 'max_horses' then v_before.max_horses else v_before.max_per_table end;
      v_new_cap := case when jsonb_typeof(p_patch -> v_key) = 'null' then null
                        else (p_patch ->> v_key)::numeric end;
      -- Setting or clearing a cap that did not exist is a change from
      -- unlimited, which has no percentage. It is material.
      if (v_old_cap is null) <> (v_new_cap is null) then
        v_material := true;
        v_reasons := v_reasons || to_jsonb((v_key || '_set_or_cleared')::text);
      elsif v_old_cap is not null and v_new_cap is not null then
        if v_old_cap = 0 then
          if v_new_cap <> 0 then
            v_material := true;
            v_reasons := v_reasons || to_jsonb((v_key || '_changed_from_zero')::text);
          end if;
        -- AN ABSOLUTE FLOOR UNDER THE PERCENTAGE (review M-7). Each patch is
        -- compared against the row as it stands, so a run of sub-25-percent
        -- cuts is a run of non-material changes and takes a club from 100
        -- horses to 3 with no approval. A cap this low is a stand-down
        -- whatever the step size that reached it. The complete fix also
        -- measures the WALK - the greatest cap this scope carried inside the
        -- approval TTL, from admin_audit_log's before_state - and that half is
        -- deliberately not in this phase; the floor closes the proved case.
        elsif v_new_cap <= 5 and v_new_cap < v_old_cap then
          v_material := true;
          v_reasons := v_reasons || to_jsonb((v_key || '_cut_to_a_floor')::text);
        elsif abs(v_new_cap - v_old_cap) / v_old_cap > 0.25 then
          v_material := true;
          v_reasons := v_reasons || to_jsonb((v_key || '_moved_more_than_25_percent')::text);
        end if;
      end if;
    end if;
  end loop;

  -- FIVE MORE FIELDS THAT CAN STOP THE FLEET SEATING (review H-1), in the
  -- same order and under the same reason strings as fleetPolicyMateriality in
  -- src/lib/horses/fleetPolicy.js. Each of these was below the line while
  -- being able to stop every table on the platform taking a horse: a global
  -- bias of 0.1 scales every seat target to a tenth, a min_humans_to_seat of
  -- 10 can never be met because ten seats is the widest table, and a band,
  -- variant or schedule restriction narrows eligibility to nothing. That is
  -- disabling the fleet for that scope by another name, so it is held to the
  -- same standard.
  if p_patch ? 'occupancy_bias' then
    v_old_bias := coalesce(v_before.occupancy_bias, 1.0);
    v_new_bias := coalesce(case when jsonb_typeof(p_patch -> 'occupancy_bias') = 'null' then null
                                else (p_patch ->> 'occupancy_bias')::numeric end, 1.0);
    if v_new_bias <= 0.5 and v_new_bias < v_old_bias then
      v_material := true;
      v_reasons := v_reasons || to_jsonb('occupancy_bias_cut_below_half'::text);
    elsif v_old_bias > 0 and abs(v_new_bias - v_old_bias) / v_old_bias > 0.25 then
      v_material := true;
      v_reasons := v_reasons || to_jsonb('occupancy_bias_moved_more_than_25_percent'::text);
    end if;
  end if;

  -- Raising the human minimum withholds seating from tables that qualified a
  -- moment ago. Lowering it gives seats back, which needs no second operator.
  if p_patch ? 'min_humans_to_seat'
     and coalesce(case when jsonb_typeof(p_patch -> 'min_humans_to_seat') = 'null' then null
                       else (p_patch ->> 'min_humans_to_seat')::numeric end, 0)
         > coalesce(v_before.min_humans_to_seat, 0) then
    v_material := true;
    v_reasons := v_reasons || to_jsonb('min_humans_to_seat_raised'::text);
  end if;

  -- A restriction is measured against NO restriction: null is "this scope
  -- withholds nothing", so adding a list where there was none is a narrowing
  -- however long the list is, and a shorter list is a narrowing too. Widening
  -- or clearing gives the fleet back seats it could not take.
  foreach v_key in array array['stake_bands','variants','schedule'] loop
    if p_patch ? v_key then
      v_had_list := case v_key
                      when 'stake_bands' then v_before.stake_bands is not null
                      when 'variants'    then v_before.variants is not null
                      else v_before.schedule is not null
                           and jsonb_typeof(v_before.schedule) = 'array'
                    end;
      v_old_len := case when not v_had_list then null
                        when v_key = 'stake_bands' then coalesce(array_length(v_before.stake_bands, 1), 0)
                        when v_key = 'variants'    then coalesce(array_length(v_before.variants, 1), 0)
                        else jsonb_array_length(v_before.schedule) end;
      v_new_len := case when jsonb_typeof(p_patch -> v_key) <> 'array' then null
                        else jsonb_array_length(p_patch -> v_key) end;
      if v_new_len is not null and (v_old_len is null or v_new_len < v_old_len) then
        v_material := true;
        v_reasons := v_reasons || to_jsonb((v_key || '_narrowed')::text);
      end if;
    end if;
  end loop;

  -- The upsert. Every column is named, so a NEW club row leaves the
  -- fields the patch did not mention as NULL and inherits them from the
  -- wider scope. On an existing row only the named keys move.
  insert into public.ca_horse_fleet_policy as t (
    scope, scope_id, enabled, pause_new_seatings, max_horses, max_per_table,
    occupancy_bias, min_humans_to_seat, stake_bands, variants, schedule,
    notes, updated_by, updated_at
  ) values (
    p_scope,
    p_scope_id,
    case when p_patch ? 'enabled' then (p_patch ->> 'enabled')::boolean else null end,
    case when p_patch ? 'pause_new_seatings' then (p_patch ->> 'pause_new_seatings')::boolean else null end,
    case when p_patch ? 'max_horses' then (p_patch ->> 'max_horses')::int else null end,
    case when p_patch ? 'max_per_table' then (p_patch ->> 'max_per_table')::int else null end,
    case when p_patch ? 'occupancy_bias' then (p_patch ->> 'occupancy_bias')::numeric else null end,
    case when p_patch ? 'min_humans_to_seat' then (p_patch ->> 'min_humans_to_seat')::int else null end,
    case when p_patch ? 'stake_bands' and jsonb_typeof(p_patch -> 'stake_bands') = 'array'
         then (select array_agg(value #>> '{}') from jsonb_array_elements(p_patch -> 'stake_bands'))
         else null end,
    case when p_patch ? 'variants' and jsonb_typeof(p_patch -> 'variants') = 'array'
         then (select array_agg(value #>> '{}') from jsonb_array_elements(p_patch -> 'variants'))
         else null end,
    case when p_patch ? 'schedule' and jsonb_typeof(p_patch -> 'schedule') = 'array'
         then p_patch -> 'schedule' else null end,
    case when p_patch ? 'notes' then p_patch ->> 'notes' else null end,
    p_updated_by,
    now()
  )
  on conflict (scope, scope_key) do update set
    enabled            = case when p_patch ? 'enabled' then (p_patch ->> 'enabled')::boolean else t.enabled end,
    pause_new_seatings = case when p_patch ? 'pause_new_seatings' then (p_patch ->> 'pause_new_seatings')::boolean else t.pause_new_seatings end,
    max_horses         = case when p_patch ? 'max_horses' then (p_patch ->> 'max_horses')::int else t.max_horses end,
    max_per_table      = case when p_patch ? 'max_per_table' then (p_patch ->> 'max_per_table')::int else t.max_per_table end,
    occupancy_bias     = case when p_patch ? 'occupancy_bias' then (p_patch ->> 'occupancy_bias')::numeric else t.occupancy_bias end,
    min_humans_to_seat = case when p_patch ? 'min_humans_to_seat' then (p_patch ->> 'min_humans_to_seat')::int else t.min_humans_to_seat end,
    stake_bands        = case when p_patch ? 'stake_bands'
                              then case when jsonb_typeof(p_patch -> 'stake_bands') = 'array'
                                        then (select array_agg(value #>> '{}') from jsonb_array_elements(p_patch -> 'stake_bands'))
                                        else null end
                              else t.stake_bands end,
    variants           = case when p_patch ? 'variants'
                              then case when jsonb_typeof(p_patch -> 'variants') = 'array'
                                        then (select array_agg(value #>> '{}') from jsonb_array_elements(p_patch -> 'variants'))
                                        else null end
                              else t.variants end,
    schedule           = case when p_patch ? 'schedule'
                              then case when jsonb_typeof(p_patch -> 'schedule') = 'array'
                                        then p_patch -> 'schedule' else null end
                              else t.schedule end,
    notes              = case when p_patch ? 'notes' then p_patch ->> 'notes' else t.notes end,
    updated_by         = p_updated_by,
    updated_at         = now()
  returning * into v_after;

  begin
    perform public.fn_log_admin_action(
      p_admin_user_id := p_updated_by,
      p_action        := 'fleet.set_policy',
      p_target_type   := 'fleet_policy',
      -- THE SAME TARGET ID THE ROUTE USES (review M-2). fleet-admin.js files
      -- its own fleet.set_policy row under policyTargetId(), which is 'global'
      -- for the global row and '<scope>:<uuid>' otherwise. This function used
      -- to write 'global:global' for the global row, so a trail lookup on
      -- fn_ca_operator_audit_trail - which filters on an exact target_id -
      -- found one of the two rows and silently omitted the other, and the one
      -- it omitted carried the before and after snapshots.
      p_target_id     := case when p_scope = 'global' then 'global'
                              else p_scope || ':' || p_scope_id::text end,
      p_details       := jsonb_build_object(
                           'patch', p_patch,
                           'reason', p_reason,
                           'created', v_created,
                           'material', v_material,
                           'material_reasons', v_reasons
                         ),
      p_before_state  := case when v_created then null else to_jsonb(v_before) end,
      p_after_state   := to_jsonb(v_after),
      p_ip_address    := null,
      p_user_agent    := null,
      p_request_id    := null
    );
  exception when others then
    raise notice 'fn_ca_fleet_set_policy audit failed: %', sqlerrm;
  end;

  return jsonb_build_object(
    'ok', true,
    'scope', p_scope,
    'scope_id', p_scope_id,
    'created', v_created,
    'material', v_material,
    'material_reasons', v_reasons,
    'before', case when v_created then null else to_jsonb(v_before) end,
    'after', to_jsonb(v_after),
    -- What the ENGINE will now read. fn_ca_fleet_policy_effective is
    -- keyed by club, so a club write echoes that club's merged policy
    -- and a global or union write echoes the global view. effective_for
    -- says which, so the console never renders a global answer under a
    -- union heading.
    'effective_for', case when p_scope = 'club' then 'club:' || p_scope_id::text else 'global' end,
    'effective', case when p_scope = 'club' then public.fn_ca_fleet_policy_effective(p_scope_id)
                      else public.fn_ca_fleet_policy_effective(null) end
  );
end
$$;


ALTER FUNCTION public.fn_ca_fleet_set_policy(p_scope text, p_scope_id uuid, p_patch jsonb, p_updated_by uuid, p_reason text) OWNER TO postgres;

--
-- Name: fn_ca_fleet_state_upsert(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_fleet_state_upsert(p_rows jsonb, p_beat jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_written int := 0;
  v_skipped int := 0;
  v_beat_id bigint;
  v_beat_at timestamptz;
begin
  if p_rows is not null and jsonb_typeof(p_rows) = 'array' then
    with incoming as (
      select
        nullif(r ->> 'horse_id', '')::uuid as horse_id,
        case when coalesce(r ->> 'state', 'unknown') in
               ('idle','seated','playing','sitting_out','busted','suspended','retired','unknown')
             then r ->> 'state' else 'unknown' end as state,
        nullif(r ->> 'club_id', '')::uuid       as club_id,
        nullif(r ->> 'table_id', '')::uuid      as table_id,
        nullif(r ->> 'seat_index', '')::int     as seat_index,
        nullif(r ->> 'stack', '')::numeric      as stack,
        nullif(r ->> 'last_action_at', '')::timestamptz     as last_action_at,
        coalesce(nullif(r ->> 'last_seen_at', '')::timestamptz, now()) as last_seen_at,
        nullif(r ->> 'session_started_at', '')::timestamptz as session_started_at,
        coalesce(nullif(r ->> 'hands_this_session', '')::int, 0) as hands_this_session,
        nullif(r ->> 'lane', '')                as lane,
        nullif(r ->> 'stake_band', '')          as stake_band,
        nullif(r ->> 'bankroll', '')::numeric   as bankroll,
        nullif(r ->> 'note', '')                as note
      from jsonb_array_elements(p_rows) as r
      where jsonb_typeof(r) = 'object'
    ),
    valid as (
      select * from incoming where horse_id is not null
    ),
    -- One row per horse per call. A cycle that named the same horse
    -- twice must not trip the primary key: the last mention wins.
    deduped as (
      select distinct on (horse_id) * from valid order by horse_id, last_seen_at desc
    ),
    upserted as (
      insert into public.ca_horse_fleet_state as s (
        horse_id, state, club_id, table_id, seat_index, stack, last_action_at,
        last_seen_at, session_started_at, hands_this_session, lane, stake_band,
        bankroll, note, updated_at
      )
      select horse_id, state, club_id, table_id, seat_index, stack, last_action_at,
             last_seen_at, session_started_at, hands_this_session, lane, stake_band,
             bankroll, note, now()
      from deduped
      on conflict (horse_id) do update set
        state              = excluded.state,
        club_id            = excluded.club_id,
        table_id           = excluded.table_id,
        seat_index         = excluded.seat_index,
        stack              = excluded.stack,
        last_action_at     = coalesce(excluded.last_action_at, s.last_action_at),
        last_seen_at       = excluded.last_seen_at,
        session_started_at = case when excluded.table_id is distinct from s.table_id then excluded.session_started_at else coalesce(excluded.session_started_at, s.session_started_at) end,
        hands_this_session = case when excluded.table_id is distinct from s.table_id then excluded.hands_this_session when excluded.hands_this_session > 0 then excluded.hands_this_session else s.hands_this_session end,
        lane               = excluded.lane,
        stake_band         = excluded.stake_band,
        bankroll           = excluded.bankroll,
        note               = excluded.note,
        updated_at         = now()
      returning 1
    )
    select
      (select count(*) from upserted),
      (select count(*) from incoming) - (select count(*) from deduped)
    into v_written, v_skipped;
  end if;

  if p_beat is not null and jsonb_typeof(p_beat) = 'object' then
    insert into public.ca_horse_fleet_heartbeat (
      beat_at, cycle_ms, horses_total, horses_seated, horses_idle, horses_stuck,
      tables_seen, tables_seeded, seats_filled, seats_released, policy_version,
      degraded, detail
    ) values (
      coalesce(nullif(p_beat ->> 'beat_at', '')::timestamptz, now()),
      nullif(p_beat ->> 'cycle_ms', '')::int,
      nullif(p_beat ->> 'horses_total', '')::int,
      nullif(p_beat ->> 'horses_seated', '')::int,
      nullif(p_beat ->> 'horses_idle', '')::int,
      nullif(p_beat ->> 'horses_stuck', '')::int,
      nullif(p_beat ->> 'tables_seen', '')::int,
      nullif(p_beat ->> 'tables_seeded', '')::int,
      nullif(p_beat ->> 'seats_filled', '')::int,
      nullif(p_beat ->> 'seats_released', '')::int,
      nullif(p_beat ->> 'policy_version', '')::timestamptz,
      coalesce((p_beat ->> 'degraded')::boolean, false),
      case when jsonb_typeof(p_beat -> 'detail') = 'object' then p_beat -> 'detail' else null end
    )
    returning id, beat_at into v_beat_id, v_beat_at;
  end if;

  return jsonb_build_object(
    'ok', true,
    'rows_written', coalesce(v_written, 0),
    'rows_skipped', coalesce(v_skipped, 0),
    'heartbeat_id', v_beat_id,
    'beat_at', v_beat_at,
    'audited', false,
    'audit_note', 'machine telemetry, one call per engine cycle, deliberately not audited'
  );
end
$$;


ALTER FUNCTION public.fn_ca_fleet_state_upsert(p_rows jsonb, p_beat jsonb) OWNER TO postgres;

--
-- Name: fn_ca_frozen_baseline_needs_a_reason(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_frozen_baseline_needs_a_reason() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'the frozen pool baseline for % is not deleted; move it with a recorded reason', OLD.pool
      USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.frozen_total IS DISTINCT FROM OLD.frozen_total THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.ca_frozen_pool_baseline_changes c
       WHERE c.pool = NEW.pool
         AND c.total_before = OLD.frozen_total
         AND c.total_after  = NEW.frozen_total
         AND c.recorded_at > now() - interval '1 minute')
    THEN
      RAISE EXCEPTION 'the frozen pool baseline for % may not move from % to % without a row in ca_frozen_pool_baseline_changes written in the same transaction',
        NEW.pool, OLD.frozen_total, NEW.frozen_total USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_frozen_baseline_needs_a_reason() OWNER TO postgres;

--
-- Name: fn_ca_fund_club(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_fund_club(p_club_id uuid, p_amount numeric, p_reason text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club record; v_key text; v_after numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'fund_club refused: amount must be positive';
  END IF;
  IF COALESCE(length(trim(p_reason)),0) < 10 THEN
    RAISE EXCEPTION 'fund_club refused: a reason of at least 10 characters is required';
  END IF;
  SELECT * INTO v_club FROM public.clubs WHERE id = p_club_id;
  IF v_club.id IS NULL THEN
    RAISE EXCEPTION 'fund_club refused: unknown club %', p_club_id;
  END IF;
  v_key := COALESCE(p_idempotency_key,
                    'club-funding:' || p_club_id::text || ':' ||
                    extract(epoch from clock_timestamp())::bigint::text);
  -- Replay safety: an identical key that already journaled is a no-op.
  IF EXISTS (SELECT 1 FROM public.chip_ledger WHERE idempotency_key = v_key) THEN
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'idempotency_key', v_key);
  END IF;
  PERFORM public.fn_ca_declare_ledger('mint', 'system_mint', NULL, NULL, v_key);
  UPDATE public.clubs
     SET chip_treasury = COALESCE(chip_treasury,0) + p_amount
   WHERE id = p_club_id
   RETURNING chip_treasury INTO v_after;
  RETURN jsonb_build_object('ok', true, 'replayed', false, 'club_id', p_club_id,
                            'amount', p_amount, 'treasury_after', v_after,
                            'idempotency_key', v_key, 'reason', p_reason);
END $$;


ALTER FUNCTION public.fn_ca_fund_club(p_club_id uuid, p_amount numeric, p_reason text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: fn_ca_fund_overlay_on_lock(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_fund_overlay_on_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_short numeric; v_union uuid; v_bank numeric; v_from text; v_store text;
  v_pool_before numeric;
  v_entrants int; v_places int; v_existing jsonb;
  v_guarantee numeric; v_seat_guarantee numeric; v_target uuid;
  v_attempt int; v_fallback numeric;
BEGIN
  IF NOT (COALESCE(OLD.status,'') IN ('ANNOUNCED','REGISTERING')
          AND NEW.status IN ('RUNNING','COMPLETING','COMPLETED')) THEN
    RETURN NEW;
  END IF;

  /* ── 1. payout table, from the field that actually entered ─────────────
     Only when nobody has registered yet. With registrations present,
     fn_guard_managed_game_lifecycle protects payout_structure and this
     trigger currently runs BEFORE it, so writing here refuses the whole
     start. Re-enabled once the trigger is renamed to sort after the guard.

     NOT FOR A SPIN (2026-09-02). A Spin's ladder comes from the tier the
     wheel drew - 10x is 80/20 - and this rule is "pay the top N% of the
     field", which on three seats rounds to one place and silently replaced
     every high multiplier with winner-take-all. 32 games, 1,592 chips. */
  SELECT count(*) INTO v_entrants
    FROM public.tournament_players tp WHERE tp.tournament_id = NEW.id;

  IF NEW.variant IS DISTINCT FROM 'spin' THEN
    IF v_entrants > 0 AND NOT EXISTS (
         SELECT 1 FROM pg_trigger tg
          WHERE tg.tgrelid = 'public.tournaments'::regclass
            AND tg.tgname = 'zz_ca_fund_overlay_on_lock')
    THEN
      NULL;  -- stand down: the guard would refuse the start
    ELSIF v_entrants > 0 THEN
      v_places := GREATEST(1, LEAST(v_entrants,
                    ceil(v_entrants * COALESCE(NEW.payout_percent,10) / 100.0)::int));
      BEGIN
        v_existing := NULLIF(btrim(COALESCE(NEW.payout_structure,'')), '')::jsonb;
      EXCEPTION WHEN OTHERS THEN v_existing := NULL; END;

      IF v_existing IS NULL
         OR jsonb_typeof(v_existing) <> 'array'
         OR jsonb_array_length(v_existing) = 0
         OR v_existing = '[{"place":1,"percentage":100}]'::jsonb
         OR jsonb_array_length(v_existing) <> v_places
      THEN
        NEW.payout_structure := public.fn_ca_payout_structure(
                                  v_entrants, COALESCE(NEW.payout_percent,10))::text;
      END IF;
    END IF;
  END IF;

  /* ── 2. the guarantee overlay, from the main bank ─────────────────────── */
  v_pool_before := round(COALESCE(NEW.prize_pool,0),2);
  v_guarantee   := round(COALESCE(NEW.guaranteed_prize,0),2);

  /* A GUARANTEED SEAT IS A GUARANTEE (2026-09-02). A satellite's advertised
     seats are worth target buy-in + fee each; the engine awards every one of
     them, so the bank funds the shortfall here, like any other guarantee. */
  IF COALESCE(NEW.satellite_seats, 0) > 0
     AND (NEW.variant = 'satellite'
          OR UPPER(COALESCE(NEW.tournament_type, '')) = 'SATELLITE'
          OR NEW.satellite_target_id IS NOT NULL) THEN
    v_target := COALESCE(NEW.satellite_target_id, NEW.satellite_target);
    IF v_target IS NOT NULL THEN
      SELECT round((COALESCE(t2.buy_in_amount,0) + COALESCE(t2.buy_in_fee,0)) * NEW.satellite_seats, 2)
        INTO v_seat_guarantee
        FROM public.tournaments t2 WHERE t2.id = v_target;
      v_guarantee := GREATEST(v_guarantee, COALESCE(v_seat_guarantee, 0));
    END IF;
  END IF;

  v_short := GREATEST(0, v_guarantee - v_pool_before);
  IF v_short <= 0 THEN RETURN NEW; END IF;

  PERFORM set_config('app.ledger_category', 'overlay', true);
  PERFORM set_config('app.ledger_counterparty', 'prize_liability', true);
  PERFORM set_config('app.ledger_counterparty_entity', NEW.id::text, true);

  v_union := CASE WHEN COALESCE(NEW.is_private,false) THEN NULL ELSE NEW.union_id END;

  IF v_union IS NOT NULL THEN
    SELECT chip_balance INTO v_bank FROM public.union_wallets
     WHERE union_id = v_union FOR UPDATE;
    v_from := 'union_bank';
    v_store := 'union_wallets.chip_balance';
    IF COALESCE(v_bank,0) < v_short THEN
      /* THE MAIN BANK IS SHORT - FALL BACK TO THE CLUB TREASURY.
         Dan 2026-09-04. Refusing here meant advertising a guarantee and then
         not paying it. */
      SELECT chip_treasury INTO v_fallback
        FROM public.clubs WHERE id = NEW.club_id FOR UPDATE;

      IF COALESCE(v_fallback,0) >= v_short THEN
        v_from  := 'club_treasury';
        v_store := 'clubs.chip_treasury';
        PERFORM set_config('app.ledger_autoskip_clubs', '1', true);
        UPDATE public.clubs
           SET chip_treasury = COALESCE(chip_treasury,0) - v_short, updated_at = now()
         WHERE id = NEW.club_id;
        PERFORM set_config('app.ledger_autoskip_clubs', '0', true);
        PERFORM public.fn_raise_server_financial_alert(
          'warning', 'fn_ca_fund_overlay_on_lock',
          format('%s took its %s chip overlay from the club treasury: the union bank held only %s. The guarantee WAS met. Refill the union bank.',
                 COALESCE(NEW.name, NEW.id::text), v_short, COALESCE(v_bank,0)),
          jsonb_build_object('kind','overlay_funded_from_fallback','tournament_id',NEW.id,
            'shortfall',v_short,'union_bank',COALESCE(v_bank,0),
            'club_treasury',COALESCE(v_fallback,0)), NEW.id::text);
        v_union := NULL;  -- the ledger row names the account that actually moved
      ELSE
        PERFORM public.fn_raise_server_financial_alert(
          'critical', 'fn_ca_fund_overlay_on_lock',
          format('%s needs %s chips of overlay to meet its %s guarantee. The union bank holds %s and the club treasury holds %s. BOTH are short and the pool was NOT topped up.',
                 COALESCE(NEW.name, NEW.id::text), v_short, v_guarantee,
                 COALESCE(v_bank,0), COALESCE(v_fallback,0)),
          jsonb_build_object('kind','overlay_unfunded','tournament_id',NEW.id,
            'shortfall',v_short,'bank',COALESCE(v_bank,0),
            'club_treasury',COALESCE(v_fallback,0)), NEW.id::text);
        RETURN NEW;
      END IF;
    ELSE
      PERFORM set_config('app.ledger_autoskip_union_wallets', '1', true);
      UPDATE public.union_wallets
         SET chip_balance = chip_balance - v_short, updated_at = now()
       WHERE union_id = v_union;
      PERFORM set_config('app.ledger_autoskip_union_wallets', '0', true);
    END IF;
  ELSE
    SELECT chip_treasury INTO v_bank FROM public.clubs
     WHERE id = NEW.club_id FOR UPDATE;
    v_from := 'club_treasury';
    v_store := 'clubs.chip_treasury';
    IF COALESCE(v_bank,0) < v_short THEN
      PERFORM public.fn_raise_server_financial_alert(
        'critical', 'fn_ca_fund_overlay_on_lock',
        format('%s needs %s chips of overlay to meet its %s guarantee and the club treasury holds %s. The pool was NOT topped up.',
               COALESCE(NEW.name, NEW.id::text), v_short,
               v_guarantee, COALESCE(v_bank,0)),
        jsonb_build_object('kind','overlay_unfunded','tournament_id',NEW.id,
          'shortfall',v_short,'bank',COALESCE(v_bank,0)), NEW.id::text);
      RETURN NEW;
    END IF;
    PERFORM set_config('app.ledger_autoskip_clubs', '1', true);
    UPDATE public.clubs
       SET chip_treasury = COALESCE(chip_treasury,0) - v_short, updated_at = now()
     WHERE id = NEW.club_id;
    PERFORM set_config('app.ledger_autoskip_clubs', '0', true);
  END IF;

  NEW.prize_pool := round(v_pool_before + v_short, 2);

  -- Funding and its escrow/journal leg are one transaction. A failed
  -- journal insert must undo the bank debit and the advertised pool change.
  -- Retry only transient deadlocks; every final error propagates to the
  -- original status update, whose existing lifecycle can retry safely.
  FOR v_attempt IN 1..3 LOOP
    BEGIN
      INSERT INTO public.chip_ledger (
        performed_by, from_type, from_entity_id, to_type, to_entity_id,
        amount, category, club_id, tournament_id, description)
      VALUES (
        COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
        v_from, COALESCE(v_union, NEW.club_id), 'prize_liability', NEW.id,
        v_short, 'overlay', NEW.club_id, NEW.id,
        format('Guarantee overlay from the main bank: %s (%s) was %s short of its %s guarantee - field made %s, bank paid %s',
               COALESCE(NEW.name, 'tournament'), NEW.id::text,
               v_short, v_guarantee,
               v_pool_before, v_short));
      EXIT;
    EXCEPTION WHEN deadlock_detected THEN
      IF v_attempt = 3 THEN RAISE; END IF;
    END;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_fund_overlay_on_lock() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_fund_overlay_on_lock(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_fund_overlay_on_lock() IS 'Fires in the same write that closes registration and settles three things that must agree: the payout table is rebuilt for the field that actually entered (top payout_percent of them), the prize pool is topped to the guarantee out of the main bank, and the draw is journalled once, naming the tournament and the shortfall. Idempotent; all-or-nothing on the bank draw.';


--
-- Name: fn_ca_gate_panel(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_gate_panel() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mgmt boolean;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.ca_incident_recipients r WHERE r.user_id = v_uid AND r.active
    UNION ALL
    SELECT 1 FROM public.club_members cm WHERE cm.user_id = v_uid AND cm.role = 'owner'
    UNION ALL
    SELECT 1 FROM public.unions u WHERE u.owner_id = v_uid
    UNION ALL
    SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.role IN ('admin','god')
  ) INTO v_mgmt;
  IF NOT v_mgmt THEN RETURN NULL; END IF;

  RETURN jsonb_build_object(
    'gate', (SELECT to_jsonb(g) FROM (
               SELECT run_at, pass, window_hours, failing, result
                 FROM public.ca_gate_runs ORDER BY run_at DESC LIMIT 1) g),
    'supply_series', (SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.taken_at), '[]'::jsonb) FROM (
               SELECT taken_at, round(unexplained,2) AS unexplained, round(total,2) AS total,
                      round(cert_wallets,2) AS cert_wallets,
                      round(leaderboard_liability,2) AS leaderboard_liability
                 FROM public.ca_supply_snapshots
                WHERE taken_at > now() - interval '24 hours'
                ORDER BY taken_at DESC LIMIT 48) s),
    'diamond_series', (SELECT COALESCE(jsonb_agg(to_jsonb(d) ORDER BY d.taken_at), '[]'::jsonb) FROM (
               SELECT taken_at, round(unexplained,2) AS unexplained, round(total,2) AS total
                 FROM public.ca_diamond_snapshots
                WHERE taken_at > now() - interval '24 hours'
                ORDER BY taken_at DESC LIMIT 48) d),
    'open_counts', (SELECT jsonb_object_agg(severity, n) FROM (
               SELECT severity, count(*) AS n FROM public.ca_drift_incidents
                WHERE status <> 'resolved' GROUP BY severity) c),
    'generated_at', now());
END $$;


ALTER FUNCTION public.fn_ca_gate_panel() OWNER TO postgres;

--
-- Name: fn_ca_gdpr_financial_precheck(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_gdpr_financial_precheck(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('clear', false, 'blockers', jsonb_build_array('missing user id'));
  END IF;

  SELECT COALESCE(jsonb_agg(b), '[]'::jsonb) INTO v_blockers FROM (
    SELECT 'club ' || cm.club_id || ': chip balance ' || cm.chip_balance AS b
      FROM public.club_members cm
     WHERE cm.user_id = p_user_id AND round(COALESCE(cm.chip_balance,0),2) <> 0
    UNION ALL
    SELECT 'club ' || cm.club_id || ': promo balance ' || cm.promo_balance
      FROM public.club_members cm
     WHERE cm.user_id = p_user_id AND round(COALESCE(cm.promo_balance,0),2) <> 0
    UNION ALL
    SELECT 'seated at table ' || ts.table_id || ' with stack ' || ts.stack
      FROM public.table_seats ts
     WHERE ts.user_id = p_user_id AND COALESCE(ts.stack,0) > 0
    UNION ALL
    SELECT 'pending rakeback payout ' || p.id
      FROM public.rakeback_period_payouts p
     WHERE p.user_id = p_user_id AND p.status NOT IN ('paid','cancelled','failed')
    UNION ALL
    SELECT 'outstanding tournament ticket ' || t.id || ' (value ' || t.value || ')'
      FROM public.tournament_tickets t
     WHERE t.holder_id = p_user_id AND t.status NOT IN ('redeemed','cancelled')
    UNION ALL
    SELECT 'agent record in club ' || a.club_id || ' holds balances or credit (credit_used ' || COALESCE(a.credit_used,0) || ')'
      FROM public.agents a
     WHERE a.user_id = p_user_id
       AND (round(COALESCE(a.agent_wallet_balance,0) + COALESCE(a.player_wallet_balance,0)
                + COALESCE(a.promo_wallet_balance,0),2) <> 0
            OR round(COALESCE(a.credit_used,0),2) <> 0)
    UNION ALL
    SELECT 'club ' || ac.club_id || ': unclaimed commission '
           || trim(to_char(SUM(ac.amount), 'FM999,999,999,990.00'))
           || ' chips, claimable but not yet claimed'
      FROM public.agent_commissions ac
     WHERE ac.user_id = p_user_id AND ac.settled_at IS NULL AND NOT public.fn_agent_commission_paid_by_period(ac.club_id, ac.user_id, ac.created_at)
     GROUP BY ac.club_id
    HAVING round(SUM(ac.amount), 2) <> 0
  ) s;

  RETURN jsonb_build_object('clear', jsonb_array_length(v_blockers) = 0,
                            'blockers', v_blockers, 'checked_at', now());
END;
$$;


ALTER FUNCTION public.fn_ca_gdpr_financial_precheck(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_giftable_balance(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_giftable_balance(p_user_id uuid) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- DIAMOND-RULINGS 4 ("promotional balance first") read against ruling 1: purchased diamonds
  -- are the collateral of the refund and chargeback sub-ledger, so they do not leave the wallet
  -- as a gift. What a player may gift is the balance minus every unconsumed purchased lot.
  SELECT GREATEST(
    COALESCE((SELECT p.diamonds FROM public.profiles p WHERE p.id = p_user_id), 0)
      - COALESCE((SELECT sum(l.issued - l.consumed - l.refunded)
                    FROM public.diamond_purchase_lots l
                   WHERE l.user_id = p_user_id AND (l.issued - l.consumed - l.refunded) > 0), 0),
    0)::bigint;
$$;


ALTER FUNCTION public.fn_ca_giftable_balance(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_guard_defs_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_guard_defs_watch() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_name text; v_hash text; v_stored text; v_changes int := 0;
  v_def text; v_old_id bigint; v_new_id bigint;
BEGIN
  FOREACH v_name IN ARRAY public.fn_ca_guard_watchlist()
  LOOP
    SELECT md5(string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)),
           string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)
      INTO v_hash, v_def
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public' AND p.proname = v_name;

    IF v_hash IS NULL THEN
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_guard_defs_watch', 'unknown', 'warning',
        'guard-def-missing:' || v_name,
        0, NULL, NULL, 'reporting', 'pg_proc',
        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
        'guard function ' || v_name || ' no longer exists - an alarm was deleted',
        true, jsonb_build_object('guard', v_name));
      v_changes := v_changes + 1;
      CONTINUE;
    END IF;

    -- Keep the text, always, so a later notice has something to diff against.
    INSERT INTO public.ca_guard_def_history (proname, def_hash, def_text)
    VALUES (v_name, v_hash, v_def)
    ON CONFLICT (proname, def_hash) DO NOTHING;

    SELECT def_hash INTO v_stored FROM public.ca_guard_defs WHERE proname = v_name;
    IF v_stored IS NULL THEN
      INSERT INTO public.ca_guard_defs (proname, def_hash) VALUES (v_name, v_hash)
      ON CONFLICT (proname) DO NOTHING;
    ELSIF v_stored <> v_hash THEN
      v_changes := v_changes + 1;

      SELECT id INTO v_old_id FROM public.ca_guard_def_history
       WHERE proname = v_name AND def_hash = v_stored;
      SELECT id INTO v_new_id FROM public.ca_guard_def_history
       WHERE proname = v_name AND def_hash = v_hash;

      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_guard_defs_watch', 'unknown', 'info',
        'guard-def-drift:' || v_name || ':' || left(v_hash, 12),
        0, NULL, NULL, 'reporting', 'pg_proc',
        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
        'guard function ' || v_name || ' was redefined since its last baseline. '
          || CASE WHEN v_old_id IS NULL
                  THEN 'The previous text was never captured (it changed before this watcher kept history), so review the current definition on its own.'
                  ELSE 'Diff it: select def_text from ca_guard_def_history where id in ('
                       || v_old_id || ',' || v_new_id || ')'
             END
          || ' Then resolve this notice - it does not close itself.',
        true, jsonb_build_object('guard', v_name, 'old_hash', v_stored, 'new_hash', v_hash,
                                 'old_history_id', v_old_id, 'new_history_id', v_new_id));
      UPDATE public.ca_guard_defs
         SET def_hash = v_hash, updated_at = now() WHERE proname = v_name;
    END IF;
  END LOOP;
  RETURN v_changes;
END $$;


ALTER FUNCTION public.fn_ca_guard_defs_watch() OWNER TO postgres;

--
-- Name: fn_ca_guard_integrity_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_guard_integrity_check() RETURNS TABLE(kind text, object_a text, object_b text, ok boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  g RECORD; v_ok boolean; v_missing int := 0; v_detail jsonb := '[]'::jsonb;
BEGIN
  FOR g IN SELECT * FROM public.ca_guard_inventory WHERE active LOOP
    v_ok := CASE g.kind
      WHEN 'trigger' THEN EXISTS (
        SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
         WHERE t.tgname = g.object_a AND c.relname = g.object_b
           AND NOT t.tgisinternal AND t.tgenabled <> 'D')
      WHEN 'cron' THEN EXISTS (
        SELECT 1 FROM cron.job j WHERE j.jobname = g.object_a AND j.active)
      WHEN 'constraint' THEN EXISTS (
        SELECT 1 FROM pg_constraint x JOIN pg_class c ON c.oid = x.conrelid
         WHERE x.conname = g.object_a AND c.relname = g.object_b)
      WHEN 'index' THEN EXISTS (
        SELECT 1 FROM pg_indexes i
         WHERE i.indexname = g.object_a AND i.schemaname = 'public')
        OR EXISTS (SELECT 1 FROM pg_constraint x WHERE x.conname = g.object_a)
      WHEN 'function' THEN EXISTS (
        SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
         WHERE n.nspname = 'public' AND p.proname = g.object_a)
      WHEN 'revoked_dml' THEN NOT EXISTS (
        SELECT 1 FROM information_schema.role_table_grants r
         WHERE r.table_schema = 'public' AND r.table_name = g.object_a
           AND r.grantee IN ('anon','authenticated')
           AND r.privilege_type IN ('INSERT','UPDATE','DELETE'))
      ELSE false END;

    IF NOT v_ok THEN
      v_missing := v_missing + 1;
      v_detail := v_detail || jsonb_build_object('kind', g.kind, 'a', g.object_a, 'b', g.object_b);
    END IF;
    kind := g.kind; object_a := g.object_a; object_b := g.object_b; ok := v_ok;
    RETURN NEXT;
  END LOOP;

  IF v_missing > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_guard_integrity_check', 'unauthorized_adjustment', 'critical',
      'guard-missing:' || CURRENT_DATE::text,
      0, NULL, NULL, 'ledger', 'ca_guard_inventory', NULL, NULL, NULL, NULL, NULL,
      NULL, NULL, NULL, NULL,
      v_missing || ' zero-drift guard(s) are MISSING or disabled - a protection was dropped',
      false, jsonb_build_object('missing', v_detail));
  END IF;
END $$;


ALTER FUNCTION public.fn_ca_guard_integrity_check() OWNER TO postgres;

--
-- Name: fn_ca_guard_seat_creation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_guard_seat_creation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_path text;
  v_creating boolean;
  v_tournament_id uuid;
  v_variant text;
  v_max_players integer;
  v_starting_chips numeric;
BEGIN
  v_creating := (TG_OP = 'INSERT' AND NEW.left_at IS NULL)
             OR (TG_OP = 'UPDATE' AND OLD.left_at IS NOT NULL AND NEW.left_at IS NULL);
  IF NOT v_creating THEN
    RETURN NEW;
  END IF;

  SELECT tb.tournament_id, t.variant, t.max_players, t.starting_chips
    INTO v_tournament_id, v_variant, v_max_players, v_starting_chips
    FROM public.tables tb
    LEFT JOIN public.tournaments t ON t.id = tb.tournament_id
   WHERE tb.id = NEW.table_id;

  IF v_tournament_id IS NOT NULL THEN
    IF NEW.stack IS NULL
       OR NEW.stack::text IN ('NaN','Infinity','-Infinity')
       OR NEW.stack <= 0 THEN
      RAISE EXCEPTION
        'TOURNAMENT_SEAT_REQUIRES_POSITIVE_STACK: tournament %, table %, seat %, stack %',
        v_tournament_id, NEW.table_id, NEW.seat_number, NEW.stack
        USING ERRCODE = 'check_violation',
              HINT = 'Create or revive the seat with its paid positive stack in the same database transaction.';
    END IF;

    IF lower(COALESCE(v_variant,'')) = 'spin'
       OR COALESCE(v_max_players,0) <= 2 THEN
      IF v_starting_chips IS NULL
         OR v_starting_chips::text IN ('NaN','Infinity','-Infinity')
         OR v_starting_chips <= 0 THEN
        RAISE EXCEPTION
          'SEAT_FIRST_STARTING_CHIPS_INVALID: tournament %, starting_chips %',
          v_tournament_id, v_starting_chips
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.stack IS DISTINCT FROM v_starting_chips THEN
        RAISE EXCEPTION
          'SEAT_FIRST_STACK_MUST_EQUAL_STARTING_CHIPS: tournament %, table %, seat %, stack %, expected %',
          v_tournament_id, NEW.table_id, NEW.seat_number, NEW.stack, v_starting_chips
          USING ERRCODE = 'check_violation',
                HINT = 'The paid seat transaction is the only starting-stack authority; no later top-up exists.';
      END IF;
    END IF;
  END IF;

  -- Cash seats with no funded stack preserve their existing reservation path.
  IF COALESCE(NEW.stack,0) <= 0 THEN
    RETURN NEW;
  END IF;

  IF public.fn_caller_is_engine() THEN
    RETURN NEW;
  END IF;

  v_path := current_setting('app.money_path', true);
  IF v_path IN ('atomic_table_buyin', 'fn_take_seat_and_buy_in',
                'fn_seat_horse_in_seat_first_game', 'fn_seat_late_registrant',
                'fn_assign_tournament_player_seat_atomic',
                'fn_horse_seat_from_treasury') THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'SEAT_NOT_FUNDED: chips may only reach a seat through the engine or a declared money path (path=%, jwt_role=%, app=%, table=%, seat=%, stack=%)',
    COALESCE(NULLIF(v_path, ''), 'none'),
    COALESCE(auth.role(), 'none'),
    COALESCE(NULLIF(current_setting('application_name', true), ''), 'none'),
    NEW.table_id, NEW.seat_number, NEW.stack
    USING ERRCODE = 'check_violation',
          HINT = 'The caller must debit a wallet or treasury and declare app.money_path, or be the engine.';
END;
$$;


ALTER FUNCTION public.fn_ca_guard_seat_creation() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_guard_seat_creation(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_guard_seat_creation() IS 'BEFORE-seat authority. Every live tournament seat is positive; every canonical seat-first seat exactly equals tournaments.starting_chips before any caller authorization is considered.';


