--
-- Name: fn_ca_hierarchy_payables(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_hierarchy_payables(p_club_id uuid DEFAULT NULL::uuid) RETURNS TABLE(club_id uuid, club_name text, treasury numeric, commission_payable numeric, commission_rows bigint, commission_accrued_since_2_2 numeric, rakeback_payable_row_rate numeric, rakeback_payable_contract_rate numeric, rakeback_rows bigint, rakeback_last_paid timestamp with time zone, treasury_after_payables numeric, covered boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mgmt boolean := false;
BEGIN
  -- management or the service role, exactly the gate fn_ca_post_correction uses
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ca_incident_recipients r WHERE r.user_id = v_uid AND r.active
      UNION ALL
      SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.role IN ('admin','god')
    ) INTO v_mgmt;
    IF NOT v_mgmt THEN
      RAISE EXCEPTION 'management_only' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH c AS (
    SELECT cl.id, cl.name, round(COALESCE(cl.chip_treasury, 0), 2) AS treasury
      FROM public.clubs cl
     WHERE p_club_id IS NULL OR cl.id = p_club_id
  ), com AS (
    SELECT a.club_id,
           round(COALESCE(sum(a.amount), 0), 2)                                              AS payable,
           count(*)                                                                          AS n,
           round(COALESCE(sum(a.amount) FILTER (WHERE a.created_at >= '2026-09-03 16:34+00'), 0), 2) AS since_fix
      FROM public.agent_commissions a
     WHERE a.settled_at IS NULL AND NOT EXISTS (SELECT 1 FROM public.agent_commission_settlements s2 WHERE s2.club_id = a.club_id AND s2.user_id = a.user_id AND a.created_at >= s2.period_start AND a.created_at < s2.period_end)
       AND (p_club_id IS NULL OR a.club_id = p_club_id)
     GROUP BY a.club_id
  ), rb AS (
    SELECT r.club_id,
           round(COALESCE(sum(r.rakeback_amount), 0), 2)                                           AS at_row_rate,
           round(COALESCE(sum(r.rake_generated * public.fn_player_rakeback_rate(r.user_id, r.club_id, r.rake_generated)), 0), 2) AS at_contract_rate,
           count(*)                                                                                AS n
      FROM public.rakeback_periods r
     WHERE r.status = 'pending'
       AND (p_club_id IS NULL OR r.club_id = p_club_id)
     GROUP BY r.club_id
  ), lp AS (
    SELECT r.club_id, max(r.paid_at) AS last_paid
      FROM public.rakeback_periods r
     WHERE r.paid_at IS NOT NULL
       AND (p_club_id IS NULL OR r.club_id = p_club_id)
     GROUP BY r.club_id
  )
  SELECT c.id, c.name, c.treasury,
         COALESCE(com.payable, 0), COALESCE(com.n, 0), COALESCE(com.since_fix, 0),
         COALESCE(rb.at_row_rate, 0), COALESCE(rb.at_contract_rate, 0), COALESCE(rb.n, 0),
         lp.last_paid,
         round(c.treasury - COALESCE(com.payable, 0) - COALESCE(rb.at_contract_rate, 0), 2),
         (c.treasury >= COALESCE(com.payable, 0) + COALESCE(rb.at_contract_rate, 0))
    FROM c
    LEFT JOIN com ON com.club_id = c.id
    LEFT JOIN rb  ON rb.club_id  = c.id
    LEFT JOIN lp  ON lp.club_id  = c.id
   WHERE COALESCE(com.payable, 0) > 0 OR COALESCE(rb.at_row_rate, 0) > 0 OR p_club_id IS NOT NULL
   ORDER BY COALESCE(com.payable, 0) + COALESCE(rb.at_contract_rate, 0) DESC;
END $$;


ALTER FUNCTION public.fn_ca_hierarchy_payables(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_horse_claim_due(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_horse_claim_due(p_limit integer DEFAULT 500) RETURNS TABLE(claimed integer, capped integer, failed integer, ran boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r record; v_claimed integer := 0; v_capped integer := 0; v_failed integer := 0; v_msg text;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND current_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'fn_ca_horse_claim_due: service_role required';
  END IF;

  -- THE PLATFORM FREEZE (CLAUDE.md 13 rule 5). This moves money every minute, and profiles and
  -- diamond_transactions are NOT among the tables zz_freeze_guard protects - so nothing else would
  -- have stopped it crediting inside a :55-:00 break.
  IF public.fn_platform_frozen() THEN
    RETURN QUERY SELECT 0, 0, 0, false;
    RETURN;
  END IF;

  -- xact-scoped: released at commit or rollback, with no unlock path to miss. The session-scoped
  -- form skipped its unlock on a statement timeout, because EXCEPTION WHEN OTHERS does not trap
  -- query_canceled - harmless under pg_cron (the backend exits) and a permanent leak from a pooled
  -- service_role backend, which also holds EXECUTE on this.
  IF NOT pg_try_advisory_xact_lock(hashtext('ca_horse_claim_due')) THEN
    -- `ran = false` and not a zero count: "another run holds the lock" and "nothing was owed" are
    -- different answers and must not share a representation (CLAUDE.md 10.86 rule 1).
    RETURN QUERY SELECT 0, 0, 0, false;
    RETURN;
  END IF;

  FOR r IN
    SELECT u.id, u.user_id
      FROM public.user_daily_challenges u
      JOIN public.profiles p ON p.id = u.user_id AND p.is_horse
     WHERE u.completed AND NOT u.claimed AND u.expired_at IS NULL
       AND u.completed_at >= now() - interval '7 days'
     ORDER BY u.completed_at, u.id
     LIMIT GREATEST(COALESCE(p_limit, 500), 1)
  LOOP
    BEGIN
      PERFORM public.claim_daily_challenge_serialized_body(r.user_id, r.id, NULL);
      v_claimed := v_claimed + 1;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT;
      IF v_msg LIKE '%DR7:user_over_daily_cap%' THEN
        -- COUNTED, NOT FILED. A thousand horses meet the cap daily so an incident would be an
        -- always-on alarm, but returning it means the caller can see a run that paid nothing
        -- because everything was capped - which after DR7 arms is the difference between a
        -- backlog draining and a backlog dying.
        v_capped := v_capped + 1;
      ELSE
        v_failed := v_failed + 1;
        BEGIN
          PERFORM public.fn_ca_diamond_incident(
            'CH3:horse_claim_failed', 'warning', r.user_id, NULL, 'fn_ca_horse_claim_due',
            jsonb_build_object('challenge_row_id', r.id, 'sqlerrm', v_msg));
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
      END IF;
    END;
  END LOOP;

  RETURN QUERY SELECT v_claimed, v_capped, v_failed, true;
END $$;


ALTER FUNCTION public.fn_ca_horse_claim_due(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_horse_claim_due(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_horse_claim_due(p_limit integer) IS 'A horse has no browser, so this presses its claim button - keyed to who is OWED, not to who just acted. Not a repair job (CLAUDE.md 10.12): it IS the button, the same legitimate horse branch as scheduleHorseAction. Returns (claimed, capped, failed, ran): ran=false means the freeze is on or another run holds the lock, which is not the same answer as nothing being owed.';


--
-- Name: fn_ca_house_board_allows_automation(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_house_board_allows_automation(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- DERIVED FIRST: the platform club is the house board, and always will be, without anybody
  -- remembering to add it to a list. This is the half that cannot rot.
  SELECT COALESCE((SELECT c.is_platform FROM public.clubs c WHERE c.id = p_club_id), false)
     -- LEGACY, AND IT IS DEBT: four chip house boards that predate clubs.is_platform and carry no
     -- flag of their own. Give them one and these four lines delete themselves.
     OR p_club_id = ANY (ARRAY[
          'a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid,   -- Club JAQK
          'a0000000-0000-0000-0000-000000000001'::uuid,   -- SHARK CLUB
          'fade0000-0000-0000-0000-000000000001'::uuid,   -- Midway Union
          '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid    -- Deep Stack Society
        ]);
$$;


ALTER FUNCTION public.fn_ca_house_board_allows_automation(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_house_board_allows_automation(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_house_board_allows_automation(p_club_id uuid) IS 'True for a club where automated players may sit: the platform club (derived from clubs.is_platform) or one of four legacy chip house boards. Was a bare list of four uuids, which locked the Diamond Arena out of its own category on the day it was created (2026-09-08).';


--
-- Name: fn_ca_incident_action(uuid, text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_incident_action(p_incident_id uuid, p_action text, p_note text DEFAULT NULL::text, p_assignee uuid DEFAULT NULL::uuid, p_root_cause text DEFAULT NULL::text, p_correction_ref text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  inc public.ca_drift_incidents;
  v_allowed boolean;
BEGIN
  SELECT * INTO inc FROM public.ca_drift_incidents WHERE id = p_incident_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;

  v_allowed := v_uid IS NULL OR v_uid = ANY (public.fn_ca_incident_recipient_ids(inc, false));
  IF NOT v_allowed THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  IF p_action = 'acknowledge' THEN
    UPDATE public.ca_drift_incidents
       SET status = CASE WHEN status = 'open' THEN 'acknowledged' ELSE status END,
           acknowledged_by = COALESCE(acknowledged_by, v_uid),
           acknowledged_at = COALESCE(acknowledged_at, now())
     WHERE id = p_incident_id;
    INSERT INTO public.ca_incident_events (incident_id, kind, actor, detail)
    VALUES (p_incident_id, 'acknowledged', v_uid, jsonb_build_object('note', p_note));

  ELSIF p_action = 'assign' THEN
    UPDATE public.ca_drift_incidents SET assigned_to = p_assignee WHERE id = p_incident_id;
    INSERT INTO public.ca_incident_events (incident_id, kind, actor, detail)
    VALUES (p_incident_id, 'assigned', v_uid,
            jsonb_build_object('assignee', p_assignee, 'note', p_note));

  ELSIF p_action = 'comment' THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, actor, detail)
    VALUES (p_incident_id, 'comment', v_uid, jsonb_build_object('note', p_note));

  ELSIF p_action = 'reconciling' THEN
    UPDATE public.ca_drift_incidents SET status = 'reconciling' WHERE id = p_incident_id;
    INSERT INTO public.ca_incident_events (incident_id, kind, actor, detail)
    VALUES (p_incident_id, 'status_change', v_uid,
            jsonb_build_object('to', 'reconciling', 'note', p_note));

  ELSIF p_action = 'resolve' THEN
    IF inc.classification = 'unknown'
       AND COALESCE(p_root_cause, inc.root_cause) IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'root_cause_required_for_unknown');
    END IF;
    UPDATE public.ca_drift_incidents
       SET status = 'resolved', resolved_by = v_uid, resolved_at = now(),
           resolution = COALESCE(p_note, resolution),
           root_cause = COALESCE(p_root_cause, root_cause),
           correction_ref = COALESCE(p_correction_ref, correction_ref)
     WHERE id = p_incident_id;
    INSERT INTO public.ca_incident_events (incident_id, kind, actor, detail)
    VALUES (p_incident_id, 'resolved', v_uid,
            jsonb_build_object('note', p_note, 'root_cause', p_root_cause,
                               'correction_ref', p_correction_ref));
    -- SIGNAL-NOT-NOISE (2026-08-31): only a critical's resolution pushes.
    IF inc.severity = 'critical' THEN
      PERFORM public.fn_ca_incident_notify(p_incident_id, 'notified',
        '✅ Resolved: ' || inc.classification || ' drift', false);
    END IF;

  ELSIF p_action = 'reopen' THEN
    UPDATE public.ca_drift_incidents
       SET status = 'open', resolved_at = NULL, resolved_by = NULL,
           past_target = false, escalation_level = 0,
           detected_at = now(), deadline_at = now() + interval '20 minutes'
     WHERE id = p_incident_id;
    INSERT INTO public.ca_incident_events (incident_id, kind, actor, detail)
    VALUES (p_incident_id, 'reopened', v_uid, jsonb_build_object('note', p_note));
  ELSE
    RETURN jsonb_build_object('ok', false, 'reason', 'unknown_action');
  END IF;

  RETURN jsonb_build_object('ok', true);
END $$;


ALTER FUNCTION public.fn_ca_incident_action(p_incident_id uuid, p_action text, p_note text, p_assignee uuid, p_root_cause text, p_correction_ref text) OWNER TO postgres;

--
-- Name: fn_ca_incident_dashboard(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_incident_dashboard(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mgmt boolean;
BEGIN
  IF v_uid IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ca_incident_recipients r WHERE r.user_id = v_uid AND r.active
      UNION ALL
      SELECT 1 FROM public.club_members cm WHERE cm.user_id = v_uid AND cm.role = 'owner'
      UNION ALL
      SELECT 1 FROM public.unions u WHERE u.owner_id = v_uid
      UNION ALL
      SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.role IN ('admin','god')
    ) INTO v_mgmt;
    IF NOT v_mgmt THEN RETURN; END IF;
  END IF;
  RETURN QUERY
  SELECT to_jsonb(i) ||
         jsonb_build_object(
           'club_name',  (SELECT name FROM public.clubs  c WHERE c.id = i.club_id),
           'union_name', (SELECT name FROM public.unions u WHERE u.id = i.union_id),
           'age_minutes', floor(extract(epoch FROM now() - i.detected_at)/60),
           'events', (SELECT COALESCE(jsonb_agg(to_jsonb(e)), '[]'::jsonb)
                        FROM (SELECT at, kind, actor, detail
                                FROM public.ca_incident_events e2
                               WHERE e2.incident_id = i.id
                               ORDER BY at DESC LIMIT 30) e))
  FROM public.ca_drift_incidents i
  WHERE p_status IS NULL OR i.status = p_status
  ORDER BY (i.status = 'resolved'), i.detected_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit,100),1), 500);
END $$;


ALTER FUNCTION public.fn_ca_incident_dashboard(p_status text, p_limit integer) OWNER TO postgres;

--
-- Name: fn_ca_incident_escalation_tick(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_incident_escalation_tick() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  inc RECORD;
  age_min numeric;
  v_sla numeric;
  v_auto int := 0;
BEGIN
  /* PHASE 6.3 (2026-09-05): AUTO-RESOLVE ON CLEAR. A detector registered with
     auto_resolve_hours names a transient finding (an hour's drift, a refused
     leg, a shadow disagreement): if the same dedupe_key has not been seen
     again for that long, the finding cleared itself and the row says so. A
     finding that keeps recurring keeps its last_seen_at fresh and stays open. */
  UPDATE public.ca_drift_incidents i
     SET status = 'resolved', resolved_at = now(),
         resolution = format('auto-resolved on clear: not seen again for %s hours (ca_detector_registry.auto_resolve_hours); the detector kept running', r.auto_resolve_hours),
         root_cause = COALESCE(i.root_cause, 'transient finding that did not recur within the detector''s clear window'),
         correction_ref = COALESCE(i.correction_ref, format('verified: not seen again for %s hours by the detector that filed it (ca_detector_registry.auto_resolve_hours, Phase 6.3)', r.auto_resolve_hours))
    FROM public.ca_detector_registry r
   WHERE r.source = i.source AND r.status = 'active' AND r.auto_resolve_hours IS NOT NULL
     AND i.status IN ('open','acknowledged','reconciling')
     AND COALESCE(i.last_seen_at, i.detected_at) < now() - make_interval(hours => r.auto_resolve_hours);
  GET DIAGNOSTICS v_auto = ROW_COUNT;
  FOR inc IN
    SELECT * FROM public.ca_drift_incidents
     WHERE status IN ('open','acknowledged','reconciling')
       AND severity IN ('critical','warning')
     ORDER BY detected_at
     LIMIT 200
  LOOP
    age_min := extract(epoch FROM now() - inc.detected_at) / 60;
    -- ONE PUSH PER DRIFT (Dan, 2026-09-01): the raise already pushed; this
    -- tick now only keeps the dashboard's clock honest. escalation_level
    -- advances silently so the age is visible at a glance.
    -- PHASE 6.3 (2026-09-05): past_target is the detector's own SLA
    -- (ca_detector_registry.sla_hours, default 24h), not a flat 20 minutes.
    SELECT COALESCE(r.sla_hours, 24) INTO v_sla FROM public.ca_detector_registry r WHERE r.source = inc.source;
    v_sla := COALESCE(v_sla, 24);
    IF age_min >= v_sla * 60 AND inc.past_target IS NOT TRUE THEN
      UPDATE public.ca_drift_incidents
         SET escalation_level = GREATEST(escalation_level, 4), past_target = true
       WHERE id = inc.id;
    ELSIF age_min >= 15 AND inc.escalation_level < 3 THEN
      UPDATE public.ca_drift_incidents SET escalation_level = 3 WHERE id = inc.id;
    ELSIF age_min >= 10 AND inc.escalation_level < 2 THEN
      UPDATE public.ca_drift_incidents SET escalation_level = 2 WHERE id = inc.id;
    ELSIF age_min >= 5 AND inc.escalation_level < 1 THEN
      UPDATE public.ca_drift_incidents SET escalation_level = 1 WHERE id = inc.id;
    END IF;
  END LOOP;
  RETURN v_auto;
END $$;


ALTER FUNCTION public.fn_ca_incident_escalation_tick() OWNER TO postgres;

