--
-- Name: fn_ca_incident_notify(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_incident_notify(p_incident_id uuid, p_kind text, p_headline text, p_senior_only boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  inc  public.ca_drift_incidents;
  rec  uuid;
  n    int := 0;
  club_name  text;
  union_name text;
  body text;
  age_min int;
  v_finding text;
  v_state   text;
  v_kind    text;
  v_fresh   boolean;
  v_withheld text := NULL;
BEGIN
  SELECT * INTO inc FROM public.ca_drift_incidents WHERE id = p_incident_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  v_kind := CASE
              WHEN p_kind = 'escalated'    THEN 'escalated'
              WHEN inc.status = 'resolved' THEN 'resolved'
              ELSE 'raised'
            END;

  /* DAN'S RULE, 2026-09-06. Three gates, on the PUSH only. The incident is
     still filed, the event row is still written, the board still shows
     everything - what changes is whose night it interrupts.

     Order matters: 'resolved' is checked first because a fix is the case he
     named explicitly, and it would otherwise slip through on a critical. */
  IF v_kind = 'resolved' THEN
    v_withheld := 'a fix is not a page';
  ELSIF lower(COALESCE(inc.severity,'')) <> 'critical' THEN
    v_withheld := 'severity ' || COALESCE(inc.severity,'null') || ' is not critical';
  ELSIF COALESCE(inc.discrepancy_amount, 0) = 0 THEN
    v_withheld := 'nothing is unaccounted for (0.00)';
  END IF;

  IF v_withheld IS NOT NULL THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (inc.id, 'notify_withheld',
            jsonb_build_object('reason', v_withheld, 'kind', v_kind,
                               'severity', inc.severity,
                               'discrepancy', inc.discrepancy_amount,
                               'headline', left(p_headline, 110),
                               'rule', 'Dan 2026-09-06: only critical errors that need my attention'));
    RETURN 0;
  END IF;

  SELECT name INTO club_name  FROM public.clubs  WHERE id = inc.club_id;
  SELECT name INTO union_name FROM public.unions WHERE id = inc.union_id;
  age_min := GREATEST(0, floor(extract(epoch FROM now() - inc.detected_at) / 60))::int;

  body := format(
    '%s | %s drift %s chips (%s layer). Expected %s, actual %s. %s%sAge %smin, reconcile target %s. Auto-repair: %s.',
    upper(inc.severity), inc.classification,
    to_char(COALESCE(inc.discrepancy_amount,0), 'FM999999999990.00'),
    inc.layer,
    COALESCE(to_char(inc.expected_amount,'FM999999999990.00'),'?'),
    COALESCE(to_char(inc.actual_amount,'FM999999999990.00'),'?'),
    COALESCE('Club ' || club_name || '. ', ''),
    COALESCE('Union ' || union_name || '. ', ''),
    age_min, to_char(inc.deadline_at, 'HH24:MI UTC'), inc.auto_repair_status);

  v_finding := public.fn_ca_finding_key(inc.dedupe_key, inc.classification, inc.layer,
                                        inc.club_id, inc.union_id);
  v_state := md5(
      v_kind
      || '|' || COALESCE(inc.severity,'?')
      || '|' || COALESCE(inc.classification,'?')
      || '|' || COALESCE(inc.layer,'?')
      || '|' || COALESCE(inc.club_id::text,'-')
      || '|' || COALESCE(inc.union_id::text,'-')
      || '|' || CASE WHEN v_kind = 'escalated'
                     THEN COALESCE(inc.escalation_level, 0)::text ELSE '' END);

  FOR rec IN SELECT unnest(public.fn_ca_incident_recipient_ids(inc, p_senior_only))
  LOOP
    BEGIN
      v_fresh := NULL;
      INSERT INTO public.ca_incident_notify_ledger AS l
        (recipient_id, finding_key, state_hash, last_kind, last_incident_id)
      VALUES (rec, v_finding, v_state, v_kind, inc.id)
      ON CONFLICT (recipient_id, finding_key) DO UPDATE
        SET state_hash = EXCLUDED.state_hash, last_kind = EXCLUDED.last_kind,
            last_incident_id = EXCLUDED.last_incident_id, last_sent_at = now(),
            send_count = l.send_count + 1
        WHERE l.state_hash IS DISTINCT FROM EXCLUDED.state_hash
      RETURNING true INTO v_fresh;

      IF NOT COALESCE(v_fresh, false) THEN
        INSERT INTO public.ca_incident_events (incident_id, kind, detail)
        VALUES (inc.id, 'notified',
                jsonb_build_object('already_reported', true, 'finding_key', v_finding,
                                   'state', v_kind, 'recipient', rec));
        CONTINUE;
      END IF;

      PERFORM public.fn_raise_notification(
        rec, 'financial_incident', left(p_headline, 110), left(body, 480),
        '/hub/club-arena/financial-incidents?id=' || inc.id::text,
        jsonb_build_object('incident_id', inc.id, 'finding_key', v_finding,
                           'classification', inc.classification, 'severity', inc.severity,
                           'discrepancy', inc.discrepancy_amount, 'club_id', inc.club_id,
                           'union_id', inc.union_id, 'deadline_at', inc.deadline_at));
      n := n + 1;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (inc.id, 'notify_failed',
              jsonb_build_object('recipient', rec, 'error', SQLERRM));
    END;
  END LOOP;

  INSERT INTO public.ca_incident_events (incident_id, kind, detail)
  VALUES (inc.id, p_kind,
          jsonb_build_object('headline', p_headline, 'recipients', n,
                             'senior_only', p_senior_only, 'age_min', age_min,
                             'finding_key', v_finding, 'state', v_kind));
  RETURN n;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_ca_incident_notify failed for %: %', p_incident_id, SQLERRM;
  RETURN 0;
END $$;


ALTER FUNCTION public.fn_ca_incident_notify(p_incident_id uuid, p_kind text, p_headline text, p_senior_only boolean) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_incident_notify(p_incident_id uuid, p_kind text, p_headline text, p_senior_only boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_incident_notify(p_incident_id uuid, p_kind text, p_headline text, p_senior_only boolean) IS 'The only path from a drift incident to a human. Sends once per (recipient, finding, state) via ca_incident_notify_ledger. Do not add a time window here - two have been tried (10-in-2-minutes, 3-in-5-minutes) and both let every double through by construction.';


--
-- Name: ca_drift_incidents; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_drift_incidents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    detected_at timestamp with time zone DEFAULT now() NOT NULL,
    deadline_at timestamp with time zone DEFAULT (now() + '00:20:00'::interval) NOT NULL,
    classification text DEFAULT 'unknown'::text NOT NULL,
    severity text DEFAULT 'critical'::text NOT NULL,
    layer text DEFAULT 'unknown'::text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    source text NOT NULL,
    dedupe_key text NOT NULL,
    union_id uuid,
    club_id uuid,
    entity_type text,
    entity_id uuid,
    table_id uuid,
    tournament_id uuid,
    hand_id uuid,
    settlement_id text,
    wallet_ids uuid[],
    transaction_ids uuid[],
    currency text DEFAULT 'club_chips'::text NOT NULL,
    expected_amount numeric,
    actual_amount numeric,
    discrepancy_amount numeric DEFAULT 0 NOT NULL,
    ledger_balanced boolean,
    suspected_cause text,
    auto_repair_status text DEFAULT 'pending'::text NOT NULL,
    escalation_level integer DEFAULT 0 NOT NULL,
    past_target boolean DEFAULT false NOT NULL,
    occurrences integer DEFAULT 1 NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    acknowledged_by uuid,
    acknowledged_at timestamp with time zone,
    assigned_to uuid,
    root_cause text,
    correction_ref text,
    resolution text,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ca_drift_incidents_auto_repair_status_check CHECK ((auto_repair_status = ANY (ARRAY['pending'::text, 'running'::text, 'repaired'::text, 'manual_needed'::text, 'not_applicable'::text]))),
    CONSTRAINT ca_drift_incidents_classification_check CHECK ((classification = ANY (ARRAY['ledger_imbalance'::text, 'settlement_error'::text, 'duplicate_payment'::text, 'missing_payment'::text, 'projection_delay'::text, 'cache_mismatch'::text, 'reporting_mismatch'::text, 'delayed_event'::text, 'duplicate_event'::text, 'rounding_error'::text, 'incorrect_rake'::text, 'incorrect_weighted_rake'::text, 'incorrect_rakeback'::text, 'bbj_error'::text, 'treasury_error'::text, 'credit_line_error'::text, 'cross_club_posting'::text, 'cross_union_posting'::text, 'unauthorized_adjustment'::text, 'historical_migration'::text, 'unknown'::text]))),
    CONSTRAINT ca_drift_incidents_layer_check CHECK ((layer = ANY (ARRAY['ledger'::text, 'projection'::text, 'cache'::text, 'reporting'::text, 'settlement'::text, 'unknown'::text]))),
    CONSTRAINT ca_drift_incidents_severity_check CHECK ((severity = ANY (ARRAY['critical'::text, 'warning'::text, 'info'::text]))),
    CONSTRAINT ca_drift_incidents_status_check CHECK ((status = ANY (ARRAY['open'::text, 'acknowledged'::text, 'reconciling'::text, 'resolved'::text])))
);


ALTER TABLE public.ca_drift_incidents OWNER TO postgres;

--
-- Name: fn_ca_incident_recipient_ids(public.ca_drift_incidents, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_incident_recipient_ids(p_incident public.ca_drift_incidents, p_senior_only boolean DEFAULT false) RETURNS uuid[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- REGISTRY-ONLY (2026-08-31, Dan's directive): financial incident pushes
  -- go to the active rows of ca_incident_recipients and to nobody else.
  -- The old dynamic fan-out to affected club/union owners is deliberately
  -- gone - an incident about a club must never page that club's owner.
  SELECT COALESCE(array_agg(DISTINCT r.user_id), '{}')
  FROM public.ca_incident_recipients r
  WHERE r.active
    AND (NOT p_senior_only OR r.senior)
    AND (r.scope IN ('platform','financial_ops','technical')
         OR (r.scope = 'union' AND r.scope_id = p_incident.union_id)
         OR (r.scope = 'club'  AND r.scope_id = p_incident.club_id))
$$;


ALTER FUNCTION public.fn_ca_incident_recipient_ids(p_incident public.ca_drift_incidents, p_senior_only boolean) OWNER TO postgres;

--
-- Name: fn_ca_incident_resolution_reaches_the_alerts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_incident_resolution_reaches_the_alerts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_note text; v_state text; v_msg text;
BEGIN
  IF NEW.status <> 'resolved' OR COALESCE(OLD.status,'') = 'resolved' THEN
    RETURN NEW;
  END IF;
  v_note := 'Closed with drift incident ' || NEW.id::text || ': '
            || COALESCE(NULLIF(NEW.resolution,''), 'no note given on the incident');

  UPDATE public.financial_alerts f
     SET resolved = true, resolved_at = now(),
         resolution = COALESCE(NULLIF(f.resolution,'') || ' | ','') || v_note
   WHERE NOT COALESCE(f.resolved,false)
     AND f.context->>'incident_id' ~ '^[0-9a-fA-F-]{36}$'
     AND (f.context->>'incident_id')::uuid = NEW.id;

  IF NEW.metadata->>'alert_id' ~ '^[0-9a-fA-F-]{36}$' THEN
    UPDATE public.financial_alerts f
       SET resolved = true, resolved_at = now(),
           resolution = COALESCE(NULLIF(f.resolution,'') || ' | ','') || v_note
     WHERE NOT COALESCE(f.resolved,false)
       AND f.id = (NEW.metadata->>'alert_id')::uuid;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
  BEGIN
    INSERT INTO public.ca_incident_file_failures
      (source, dedupe_key, classification, severity, discrepancy, sqlstate, message)
    VALUES ('fn_ca_incident_resolution_reaches_the_alerts',
            'propagate:incident->alert:' || NEW.id::text,
            'unknown', 'warning', 0, v_state,
            'a resolved incident did not close the alerts echoing it: ' || v_msg);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RAISE WARNING 'fn_ca_incident_resolution_reaches_the_alerts failed: %', v_msg;
  RETURN NEW;
END $_$;


ALTER FUNCTION public.fn_ca_incident_resolution_reaches_the_alerts() OWNER TO postgres;

--
-- Name: fn_ca_incidents_stay_in_midway(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_incidents_stay_in_midway() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.fn_ca_is_midway_scope(
    NEW.union_id, NEW.club_id, NEW.table_id, NEW.tournament_id, NEW.metadata
  ) THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_incidents_stay_in_midway() OWNER TO postgres;

--
-- Name: fn_ca_insert_hand_with_awards(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_insert_hand_with_awards(p_row jsonb, p_units jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_id   uuid;
  v_cols text;
BEGIN
  /* Only the columns the caller named. Anything absent keeps its DEFAULT,
     which is the entire point - see the header. */
  SELECT string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position)
    INTO v_cols
    FROM information_schema.columns c
   WHERE c.table_schema = 'public'
     AND c.table_name   = 'hand_history'
     AND p_row ? c.column_name;

  IF v_cols IS NULL THEN
    RAISE EXCEPTION
      'fn_ca_insert_hand_with_awards: p_row names no hand_history column - refusing to insert a row of pure defaults';
  END IF;

  EXECUTE format(
    'INSERT INTO public.hand_history (%1$s) '
    'SELECT %1$s FROM jsonb_populate_record(null::public.hand_history, $1) '
    'RETURNING id', v_cols)
    USING p_row
     INTO v_id;

  IF jsonb_array_length(COALESCE(p_units, '[]'::jsonb)) > 0 THEN
    INSERT INTO public.bomb_pot_award_units
      (hand_history_id, table_id, hand_number, pot_index, board, side, user_id, amount, hand_name)
    SELECT v_id,
           (u->>'table_id')::uuid,
           (u->>'hand_number')::bigint,
           (u->>'pot_index')::int,
           COALESCE((u->>'board')::int, 1),
           COALESCE(u->>'side', 'high'),
           (u->>'user_id')::uuid,
           (u->>'amount')::numeric,
           NULLIF(u->>'hand_name', '')
      FROM jsonb_array_elements(p_units) u
    ON CONFLICT (hand_history_id, pot_index, board, side, user_id) DO NOTHING;
  END IF;

  RETURN v_id;
END $_$;


ALTER FUNCTION public.fn_ca_insert_hand_with_awards(p_row jsonb, p_units jsonb) OWNER TO postgres;

--
-- Name: fn_ca_integrity_action_time(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_action_time(p_action jsonb) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v text;
  n numeric;
BEGIN
  v := coalesce(p_action ->> 'timestamp', p_action ->> 'ts',
                p_action ->> 'time', p_action ->> 'created_at');
  IF v IS NULL OR btrim(v) = '' THEN RETURN NULL; END IF;
  IF v ~ '^[0-9]+([.][0-9]+)?$' THEN
    n := v::numeric;
    RETURN to_timestamp(CASE WHEN n > 100000000000 THEN n / 1000 ELSE n END);
  END IF;
  RETURN v::timestamptz;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$_$;


ALTER FUNCTION public.fn_ca_integrity_action_time(p_action jsonb) OWNER TO postgres;

--
-- Name: fn_ca_integrity_action_user(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_action_user(p_action jsonb) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v text;
BEGIN
  v := coalesce(p_action ->> 'user_id', p_action ->> 'userId',
                p_action ->> 'player_id', p_action ->> 'playerId');
  IF v ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN v::uuid;
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$_$;


ALTER FUNCTION public.fn_ca_integrity_action_user(p_action jsonb) OWNER TO postgres;

--
-- Name: fn_ca_integrity_audit(uuid, text, text, text, jsonb, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_audit(p_actor uuid, p_action text, p_target_type text, p_target_id text, p_details jsonb, p_before jsonb, p_after jsonb, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.fn_log_admin_action(
    p_admin_user_id := p_actor,
    p_action        := p_action,
    p_target_type   := p_target_type,
    p_target_id     := p_target_id,
    p_details       := coalesce(p_details, '{}'::jsonb),
    p_before_state  := p_before,
    p_after_state   := p_after,
    p_ip_address    := p_ip_address,
    p_user_agent    := p_user_agent,
    p_request_id    := p_request_id
  );
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_audit(p_actor uuid, p_action text, p_target_type text, p_target_id text, p_details jsonb, p_before jsonb, p_after jsonb, p_ip_address text, p_user_agent text, p_request_id text) OWNER TO postgres;

--
-- Name: fn_ca_integrity_case(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_case(p_case_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_case      jsonb;
  v_items     jsonb;
  v_sanctions jsonb;
BEGIN
  IF p_case_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_ID_REQUIRED',
                              'message', 'A case id is required');
  END IF;

  SELECT to_jsonb(c) INTO v_case
    FROM public.ca_integrity_cases c
   WHERE c.id = p_case_id;

  IF v_case IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND',
                              'message', 'Integrity case not found',
                              'state', 'not_found', 'case_id', p_case_id);
  END IF;

  SELECT coalesce(jsonb_agg(
           to_jsonb(i) || jsonb_build_object(
             'retracted', EXISTS (
               SELECT 1 FROM public.ca_integrity_case_items r
                WHERE r.retracts_item_id = i.id),
             'retraction', (
               SELECT to_jsonb(r) FROM public.ca_integrity_case_items r
                WHERE r.retracts_item_id = i.id LIMIT 1))
           ORDER BY i.added_at, i.id), '[]'::jsonb)
    INTO v_items
    FROM public.ca_integrity_case_items i
   WHERE i.case_id = p_case_id;

  SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.proposed_at, s.id), '[]'::jsonb)
    INTO v_sanctions
    FROM public.ca_integrity_sanctions s
   WHERE s.case_id = p_case_id;

  RETURN jsonb_build_object(
    'ok', true,
    'state', 'found',
    'case', v_case,
    'items', v_items,
    'sanctions', v_sanctions,
    'measured_at', clock_timestamp());
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_case(p_case_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_integrity_case_add_item(uuid, text, text, jsonb, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_case_add_item(p_case_id uuid, p_item_type text, p_item_ref text, p_detail jsonb, p_actor uuid, p_op_id text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_case       public.ca_integrity_cases;
  v_item       public.ca_integrity_case_items;
  v_existing   public.ca_integrity_case_items;
  v_annotation jsonb := coalesce(p_detail, '{}'::jsonb);
  v_snapshot   jsonb;
  v_stored     jsonb;
  v_hash       text;
  v_payload    text;
BEGIN
  IF p_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACTOR_REQUIRED', 'message', 'Operator identity is required');
  END IF;
  IF p_op_id IS NULL OR length(btrim(p_op_id)) NOT BETWEEN 8 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'OP_ID_REQUIRED', 'message', 'A bounded operation id is required');
  END IF;
  IF p_item_type NOT IN (
    'collusion_row', 'collusion_signal', 'flag', 'hand',
    'restriction', 'note', 'observation') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_ITEM_TYPE', 'message', 'Unknown evidence item type');
  END IF;
  IF octet_length(v_annotation::text) > 65536 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'DETAIL_TOO_LARGE', 'message', 'Evidence annotation is too large');
  END IF;

  SELECT * INTO v_case FROM public.ca_integrity_cases c WHERE c.id = p_case_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND', 'message', 'Integrity case not found');
  END IF;
  IF v_case.status = 'closed' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_CLOSED', 'message', 'Closed cases cannot receive evidence');
  END IF;

  v_payload := concat_ws('|', p_case_id::text, p_item_type, coalesce(p_item_ref, ''), v_annotation::text);
  v_hash := md5(v_payload);
  SELECT * INTO v_existing FROM public.ca_integrity_case_items i WHERE i.op_id = p_op_id;
  IF FOUND THEN
    IF v_existing.case_id <> p_case_id OR v_existing.payload_hash <> v_hash THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT',
                                'message', 'This operation id was used for different evidence');
    END IF;
    RETURN jsonb_build_object('ok', true, 'item', to_jsonb(v_existing), 'idempotent', true);
  END IF;

  IF p_item_type = 'note' THEN
    IF p_item_ref IS NOT NULL OR length(btrim(coalesce(v_annotation ->> 'note', ''))) NOT BETWEEN 1 AND 4000 THEN
      RETURN jsonb_build_object('ok', false, 'code', 'INVALID_NOTE', 'message', 'A bounded note and no source reference are required');
    END IF;
    v_snapshot := jsonb_build_object('note', btrim(v_annotation ->> 'note'));
  ELSE
    IF p_item_ref IS NULL OR length(p_item_ref) > 200 THEN
      RETURN jsonb_build_object('ok', false, 'code', 'ITEM_REF_REQUIRED', 'message', 'A bounded source reference is required');
    END IF;

    SELECT * INTO v_existing FROM public.ca_integrity_case_items i
     WHERE i.case_id = p_case_id AND i.item_type = p_item_type AND i.item_ref = p_item_ref
     LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object('ok', false, 'code', 'EVIDENCE_ALREADY_ATTACHED',
                                'message', 'This evidence is already attached', 'item_id', v_existing.id);
    END IF;

    IF p_item_type IN ('collusion_row', 'flag', 'hand', 'restriction')
       AND p_item_ref !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'INVALID_ITEM_REF', 'message', 'Source reference is invalid');
    END IF;
    IF p_item_type IN ('collusion_signal', 'observation') AND p_item_ref !~ '^[0-9]+$' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'INVALID_ITEM_REF', 'message', 'Source reference is invalid');
    END IF;

    CASE p_item_type
      WHEN 'collusion_row' THEN
        SELECT to_jsonb(c) INTO v_snapshot FROM public.collusion_tracking c
         WHERE c.id = p_item_ref::uuid;
      WHEN 'collusion_signal' THEN
        SELECT to_jsonb(s) INTO v_snapshot FROM public.ca_collusion_signals s
         WHERE s.id = p_item_ref::bigint;
      WHEN 'flag' THEN
        SELECT to_jsonb(f) INTO v_snapshot FROM public.anti_cheat_flags f
         WHERE f.id = p_item_ref::uuid;
      WHEN 'hand' THEN
        SELECT jsonb_build_object(
          'id', h.id, 'table_id', h.table_id, 'tournament_id', h.tournament_id,
          'hand_number', h.hand_number, 'game_variant', h.game_variant,
          'pot_size', h.pot_size, 'big_blind', h.big_blind, 'small_blind', h.small_blind,
          'players', h.players, 'winners', h.winners, 'actions', h.actions,
          'created_at', h.created_at)
          INTO v_snapshot FROM public.hand_history h WHERE h.id = p_item_ref::uuid;
      WHEN 'restriction' THEN
        SELECT to_jsonb(r) INTO v_snapshot FROM public.ca_player_restrictions r
         WHERE r.id = p_item_ref::uuid;
      WHEN 'observation' THEN
        SELECT to_jsonb(o) INTO v_snapshot FROM public.ca_restriction_observations o
         WHERE o.id = p_item_ref::bigint;
    END CASE;

    IF v_snapshot IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'code', 'EVIDENCE_NOT_FOUND', 'message', 'Evidence source not found');
    END IF;
  END IF;

  v_stored := CASE WHEN p_item_type = 'note' THEN v_snapshot
    ELSE jsonb_build_object('source_snapshot', v_snapshot, 'annotation', v_annotation) END;
  IF octet_length(v_stored::text) > 524288 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'EVIDENCE_TOO_LARGE', 'message', 'Evidence snapshot exceeds the attachment limit');
  END IF;

  INSERT INTO public.ca_integrity_case_items (
    case_id, item_type, item_ref, detail, snapshot_hash, added_by, op_id, payload_hash)
  VALUES (
    p_case_id, p_item_type, CASE WHEN p_item_type = 'note' THEN NULL ELSE p_item_ref END,
    v_stored, md5(v_stored::text), p_actor, p_op_id, v_hash)
  RETURNING * INTO v_item;

  PERFORM public.fn_ca_integrity_audit(
    p_actor, 'integrity.case_add_item', 'integrity_case', p_case_id::text,
    jsonb_build_object('item_id', v_item.id, 'item_type', p_item_type, 'item_ref', p_item_ref),
    NULL, to_jsonb(v_item), p_ip_address, p_user_agent, p_request_id);

  RETURN jsonb_build_object('ok', true, 'item', to_jsonb(v_item), 'idempotent', false);
END;
$_$;


ALTER FUNCTION public.fn_ca_integrity_case_add_item(p_case_id uuid, p_item_type text, p_item_ref text, p_detail jsonb, p_actor uuid, p_op_id text, p_ip_address text, p_user_agent text, p_request_id text) OWNER TO postgres;

--
-- Name: fn_ca_integrity_case_assign(uuid, uuid, uuid, text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_case_assign(p_case_id uuid, p_assigned_to uuid, p_actor uuid, p_op_id text, p_expected_version integer DEFAULT NULL::integer, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_case public.ca_integrity_cases;
  v_before jsonb;
  v_payload jsonb;
  v_hash text;
  v_event public.ca_integrity_case_items;
BEGIN
  IF p_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACTOR_REQUIRED', 'message', 'Operator identity is required');
  END IF;
  IF p_op_id IS NULL OR length(btrim(p_op_id)) NOT BETWEEN 8 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'OP_ID_REQUIRED', 'message', 'A bounded operation id is required');
  END IF;
  v_payload := jsonb_build_object('case_id', p_case_id, 'assigned_to', p_assigned_to);
  v_hash := md5(v_payload::text);

  SELECT * INTO v_event FROM public.ca_integrity_case_items i WHERE i.op_id = p_op_id;
  IF FOUND THEN
    IF v_event.case_id <> p_case_id OR v_event.item_type <> 'assignment' OR v_event.payload_hash <> v_hash THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT', 'message', 'This operation id was used for a different assignment');
    END IF;
    SELECT * INTO v_case FROM public.ca_integrity_cases c WHERE c.id = p_case_id;
    RETURN jsonb_build_object('ok', true, 'case', to_jsonb(v_case), 'event', to_jsonb(v_event), 'idempotent', true);
  END IF;

  SELECT * INTO v_case FROM public.ca_integrity_cases c WHERE c.id = p_case_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND', 'message', 'Integrity case not found');
  END IF;
  IF v_case.status = 'closed' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_CLOSED', 'message', 'A closed case cannot be assigned');
  END IF;
  IF p_expected_version IS NOT NULL AND v_case.version <> p_expected_version THEN
    RETURN jsonb_build_object('ok', false, 'code', 'VERSION_CONFLICT', 'message', 'The case changed. Reload it before assigning');
  END IF;
  IF p_assigned_to IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.profiles p WHERE p.id = p_assigned_to
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ASSIGNEE_NOT_FOUND', 'message', 'The assigned operator was not found');
  END IF;

  v_before := to_jsonb(v_case);
  UPDATE public.ca_integrity_cases c
     SET assigned_to = p_assigned_to,
         status = CASE WHEN c.status = 'open' AND p_assigned_to IS NOT NULL THEN 'investigating' ELSE c.status END,
         version = c.version + 1,
         updated_at = now()
   WHERE c.id = p_case_id
   RETURNING * INTO v_case;

  INSERT INTO public.ca_integrity_case_items (
    case_id, item_type, detail, snapshot_hash, added_by, op_id, payload_hash)
  VALUES (p_case_id, 'assignment', v_payload, v_hash, p_actor, p_op_id, v_hash)
  RETURNING * INTO v_event;

  PERFORM public.fn_ca_integrity_audit(
    p_actor, 'integrity.case_assign', 'integrity_case', p_case_id::text,
    jsonb_build_object('op_id', p_op_id), v_before, to_jsonb(v_case),
    p_ip_address, p_user_agent, p_request_id);
  RETURN jsonb_build_object('ok', true, 'case', to_jsonb(v_case), 'event', to_jsonb(v_event), 'idempotent', false);
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_case_assign(p_case_id uuid, p_assigned_to uuid, p_actor uuid, p_op_id text, p_expected_version integer, p_ip_address text, p_user_agent text, p_request_id text) OWNER TO postgres;

--
-- Name: fn_ca_integrity_case_close(uuid, text, uuid, text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_case_close(p_case_id uuid, p_close_note text, p_actor uuid, p_op_id text, p_expected_version integer DEFAULT NULL::integer, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_case public.ca_integrity_cases;
  v_before jsonb;
  v_payload jsonb;
  v_hash text;
  v_event public.ca_integrity_case_items;
BEGIN
  IF p_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACTOR_REQUIRED', 'message', 'Operator identity is required');
  END IF;
  IF p_op_id IS NULL OR length(btrim(p_op_id)) NOT BETWEEN 8 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'OP_ID_REQUIRED', 'message', 'A bounded operation id is required');
  END IF;
  IF length(btrim(coalesce(p_close_note, ''))) NOT BETWEEN 10 AND 4000 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CLOSE_NOTE', 'message', 'A closing note of at least ten characters is required');
  END IF;
  v_payload := jsonb_build_object('case_id', p_case_id, 'close_note', btrim(p_close_note));
  v_hash := md5(v_payload::text);

  SELECT * INTO v_event FROM public.ca_integrity_case_items i WHERE i.op_id = p_op_id;
  IF FOUND THEN
    IF v_event.case_id <> p_case_id OR v_event.item_type <> 'closure' OR v_event.payload_hash <> v_hash THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT', 'message', 'This operation id was used for a different closure');
    END IF;
    SELECT * INTO v_case FROM public.ca_integrity_cases c WHERE c.id = p_case_id;
    RETURN jsonb_build_object('ok', true, 'case', to_jsonb(v_case), 'event', to_jsonb(v_event), 'idempotent', true);
  END IF;

  SELECT * INTO v_case FROM public.ca_integrity_cases c WHERE c.id = p_case_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND', 'message', 'Integrity case not found');
  END IF;
  IF v_case.status = 'closed' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_ALREADY_CLOSED', 'message', 'This case is already closed');
  END IF;
  IF v_case.status <> 'decided' OR v_case.decision IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'DECISION_REQUIRED', 'message', 'Decide the case before closing it');
  END IF;
  IF p_expected_version IS NOT NULL AND v_case.version <> p_expected_version THEN
    RETURN jsonb_build_object('ok', false, 'code', 'VERSION_CONFLICT', 'message', 'The case changed. Reload it before closing');
  END IF;

  v_before := to_jsonb(v_case);
  UPDATE public.ca_integrity_cases c
     SET status = 'closed', closed_by = p_actor, closed_at = now(), close_note = btrim(p_close_note),
         version = c.version + 1, updated_at = now()
   WHERE c.id = p_case_id
   RETURNING * INTO v_case;
  INSERT INTO public.ca_integrity_case_items (
    case_id, item_type, detail, snapshot_hash, added_by, op_id, payload_hash)
  VALUES (p_case_id, 'closure', v_payload, v_hash, p_actor, p_op_id, v_hash)
  RETURNING * INTO v_event;

  PERFORM public.fn_ca_integrity_audit(
    p_actor, 'integrity.case_close', 'integrity_case', p_case_id::text,
    jsonb_build_object('op_id', p_op_id), v_before, to_jsonb(v_case),
    p_ip_address, p_user_agent, p_request_id);
  RETURN jsonb_build_object('ok', true, 'case', to_jsonb(v_case), 'event', to_jsonb(v_event), 'idempotent', false);
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_case_close(p_case_id uuid, p_close_note text, p_actor uuid, p_op_id text, p_expected_version integer, p_ip_address text, p_user_agent text, p_request_id text) OWNER TO postgres;

--
-- Name: fn_ca_integrity_case_decide(uuid, text, text, uuid, text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_case_decide(p_case_id uuid, p_decision text, p_decision_note text, p_actor uuid, p_op_id text, p_expected_version integer DEFAULT NULL::integer, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_case public.ca_integrity_cases;
  v_before jsonb;
  v_payload jsonb;
  v_hash text;
  v_event public.ca_integrity_case_items;
BEGIN
  IF p_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACTOR_REQUIRED', 'message', 'Operator identity is required');
  END IF;
  IF p_op_id IS NULL OR length(btrim(p_op_id)) NOT BETWEEN 8 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'OP_ID_REQUIRED', 'message', 'A bounded operation id is required');
  END IF;
  IF p_decision IS NULL OR p_decision NOT IN ('no_action', 'warned', 'restricted', 'confiscated') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_DECISION', 'message', 'Unknown case decision');
  END IF;
  IF length(btrim(coalesce(p_decision_note, ''))) NOT BETWEEN 10 AND 4000 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_DECISION_NOTE', 'message', 'A decision note of at least ten characters is required');
  END IF;
  v_payload := jsonb_build_object('case_id', p_case_id, 'decision', p_decision, 'decision_note', btrim(p_decision_note));
  v_hash := md5(v_payload::text);

  SELECT * INTO v_event FROM public.ca_integrity_case_items i WHERE i.op_id = p_op_id;
  IF FOUND THEN
    IF v_event.case_id <> p_case_id OR v_event.item_type <> 'decision' OR v_event.payload_hash <> v_hash THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT', 'message', 'This operation id was used for a different decision');
    END IF;
    SELECT * INTO v_case FROM public.ca_integrity_cases c WHERE c.id = p_case_id;
    RETURN jsonb_build_object('ok', true, 'case', to_jsonb(v_case), 'event', to_jsonb(v_event), 'idempotent', true);
  END IF;

  SELECT * INTO v_case FROM public.ca_integrity_cases c WHERE c.id = p_case_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND', 'message', 'Integrity case not found');
  END IF;
  IF v_case.status IN ('decided', 'closed') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_ALREADY_DECIDED', 'message', 'This case already has a decision');
  END IF;
  IF p_expected_version IS NOT NULL AND v_case.version <> p_expected_version THEN
    RETURN jsonb_build_object('ok', false, 'code', 'VERSION_CONFLICT', 'message', 'The case changed. Reload it before deciding');
  END IF;

  v_before := to_jsonb(v_case);
  UPDATE public.ca_integrity_cases c
     SET status = 'decided', decision = p_decision, decision_note = btrim(p_decision_note),
         decided_by = p_actor, decided_at = now(), version = c.version + 1, updated_at = now()
   WHERE c.id = p_case_id
   RETURNING * INTO v_case;
  INSERT INTO public.ca_integrity_case_items (
    case_id, item_type, detail, snapshot_hash, added_by, op_id, payload_hash)
  VALUES (p_case_id, 'decision', v_payload, v_hash, p_actor, p_op_id, v_hash)
  RETURNING * INTO v_event;

  PERFORM public.fn_ca_integrity_audit(
    p_actor, 'integrity.case_decide', 'integrity_case', p_case_id::text,
    jsonb_build_object('op_id', p_op_id), v_before, to_jsonb(v_case),
    p_ip_address, p_user_agent, p_request_id);
  RETURN jsonb_build_object('ok', true, 'case', to_jsonb(v_case), 'event', to_jsonb(v_event), 'idempotent', false);
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_case_decide(p_case_id uuid, p_decision text, p_decision_note text, p_actor uuid, p_op_id text, p_expected_version integer, p_ip_address text, p_user_agent text, p_request_id text) OWNER TO postgres;

--
-- Name: fn_ca_integrity_case_item_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_case_item_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION USING
    ERRCODE = '55000',
    MESSAGE = 'INTEGRITY_EVIDENCE_IMMUTABLE: append a retraction row instead';
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_case_item_immutable() OWNER TO postgres;

--
-- Name: fn_ca_integrity_case_open(uuid[], text, text, text, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_case_open(p_subject_ids uuid[], p_kind text, p_severity text, p_note text, p_actor uuid, p_op_id text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_subjects uuid[];
  v_payload  jsonb;
  v_hash     text;
  v_case     public.ca_integrity_cases;
  v_count    integer;
BEGIN
  IF p_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACTOR_REQUIRED', 'message', 'Operator identity is required');
  END IF;
  IF p_op_id IS NULL OR length(btrim(p_op_id)) NOT BETWEEN 8 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'OP_ID_REQUIRED', 'message', 'A bounded operation id is required');
  END IF;

  v_subjects := public.fn_ca_integrity_normalize_subjects(p_subject_ids);
  IF coalesce(cardinality(v_subjects), 0) NOT BETWEEN 1 AND 32 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_SUBJECTS', 'message', 'Cases require between 1 and 32 players');
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN (
    'collusion', 'chip_dumping', 'multi_accounting', 'bot_or_rta', 'abuse', 'other') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_KIND', 'message', 'Unknown integrity case kind');
  END IF;
  IF p_severity IS NULL OR p_severity NOT IN ('low', 'medium', 'high') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_SEVERITY', 'message', 'Unknown integrity case severity');
  END IF;
  IF p_note IS NOT NULL AND length(btrim(p_note)) NOT BETWEEN 1 AND 4000 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_NOTE', 'message', 'Case note is too long');
  END IF;

  SELECT count(*)::integer INTO v_count
    FROM public.profiles p WHERE p.id = ANY(v_subjects);
  IF v_count <> cardinality(v_subjects) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'PLAYER_NOT_FOUND', 'message', 'One or more players do not exist');
  END IF;

  v_payload := jsonb_build_object(
    'subject_ids', to_jsonb(v_subjects), 'kind', p_kind,
    'severity', p_severity, 'note', nullif(btrim(coalesce(p_note, '')), ''));
  v_hash := md5(v_payload::text);

  SELECT * INTO v_case FROM public.ca_integrity_cases c WHERE c.open_op_id = p_op_id;
  IF FOUND THEN
    IF v_case.open_payload_hash <> v_hash THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT',
                                'message', 'This operation id was used for a different case');
    END IF;
    RETURN jsonb_build_object('ok', true, 'case', to_jsonb(v_case), 'idempotent', true);
  END IF;

  INSERT INTO public.ca_integrity_cases (
    subject_ids, kind, severity, opened_by, open_op_id, open_payload_hash)
  VALUES (v_subjects, p_kind, p_severity, p_actor, p_op_id, v_hash)
  RETURNING * INTO v_case;

  IF nullif(btrim(coalesce(p_note, '')), '') IS NOT NULL THEN
    INSERT INTO public.ca_integrity_case_items (
      case_id, item_type, detail, snapshot_hash, added_by, op_id, payload_hash)
    VALUES (
      v_case.id, 'note', jsonb_build_object('note', btrim(p_note)),
      md5(jsonb_build_object('note', btrim(p_note))::text), p_actor,
      md5('integrity-open-note:' || p_op_id),
      md5(jsonb_build_object('note', btrim(p_note))::text));
  END IF;

  PERFORM public.fn_ca_integrity_audit(
    p_actor, 'integrity.case_open', 'integrity_case', v_case.id::text,
    jsonb_build_object('op_id', p_op_id), NULL, to_jsonb(v_case),
    p_ip_address, p_user_agent, p_request_id);

  RETURN jsonb_build_object('ok', true, 'case', to_jsonb(v_case), 'idempotent', false);
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_case_open(p_subject_ids uuid[], p_kind text, p_severity text, p_note text, p_actor uuid, p_op_id text, p_ip_address text, p_user_agent text, p_request_id text) OWNER TO postgres;

--
-- Name: fn_ca_integrity_case_retract_item(uuid, uuid, text, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_case_retract_item(p_case_id uuid, p_item_id uuid, p_reason text, p_actor uuid, p_op_id text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_case     public.ca_integrity_cases;
  v_target   public.ca_integrity_case_items;
  v_existing public.ca_integrity_case_items;
  v_item     public.ca_integrity_case_items;
  v_detail   jsonb;
  v_hash     text;
BEGIN
  IF p_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACTOR_REQUIRED', 'message', 'Operator identity is required');
  END IF;
  IF p_op_id IS NULL OR length(btrim(p_op_id)) NOT BETWEEN 8 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'OP_ID_REQUIRED', 'message', 'A bounded operation id is required');
  END IF;
  IF length(btrim(coalesce(p_reason, ''))) NOT BETWEEN 1 AND 2000 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_REASON', 'message', 'A bounded retraction reason is required');
  END IF;

  SELECT * INTO v_case FROM public.ca_integrity_cases c WHERE c.id = p_case_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND', 'message', 'Integrity case not found');
  END IF;
  IF v_case.status = 'closed' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_CLOSED', 'message', 'Closed cases cannot change evidence history');
  END IF;

  SELECT * INTO v_target FROM public.ca_integrity_case_items i
   WHERE i.id = p_item_id AND i.case_id = p_case_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ITEM_NOT_FOUND', 'message', 'Case item not found');
  END IF;
  IF v_target.item_type IN ('retraction', 'assignment', 'decision', 'closure', 'sanction') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ITEM_NOT_RETRACTABLE', 'message', 'This history event cannot be retracted');
  END IF;

  v_detail := jsonb_build_object(
    'retracts_item_id', p_item_id,
    'reason', btrim(p_reason),
    'original_snapshot_hash', v_target.snapshot_hash);
  v_hash := md5(concat_ws('|', p_case_id::text, p_item_id::text, btrim(p_reason)));

  SELECT * INTO v_existing FROM public.ca_integrity_case_items i WHERE i.op_id = p_op_id;
  IF FOUND THEN
    IF v_existing.case_id <> p_case_id OR v_existing.payload_hash <> v_hash THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT',
                                'message', 'This operation id was used for another retraction');
    END IF;
    RETURN jsonb_build_object('ok', true, 'item', to_jsonb(v_existing), 'idempotent', true);
  END IF;
  IF EXISTS (SELECT 1 FROM public.ca_integrity_case_items i WHERE i.retracts_item_id = p_item_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ALREADY_RETRACTED', 'message', 'This evidence is already retracted');
  END IF;

  INSERT INTO public.ca_integrity_case_items (
    case_id, item_type, item_ref, detail, snapshot_hash, added_by, op_id,
    payload_hash, retracts_item_id, retraction_reason)
  VALUES (
    p_case_id, 'retraction', p_item_id::text, v_detail, md5(v_detail::text),
    p_actor, p_op_id, v_hash, p_item_id, btrim(p_reason))
  RETURNING * INTO v_item;

  PERFORM public.fn_ca_integrity_audit(
    p_actor, 'integrity.case_retract_item', 'integrity_case', p_case_id::text,
    jsonb_build_object('item_id', p_item_id, 'retraction_id', v_item.id),
    to_jsonb(v_target), to_jsonb(v_item), p_ip_address, p_user_agent, p_request_id);

  RETURN jsonb_build_object('ok', true, 'item', to_jsonb(v_item), 'idempotent', false);
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_case_retract_item(p_case_id uuid, p_item_id uuid, p_reason text, p_actor uuid, p_op_id text, p_ip_address text, p_user_agent text, p_request_id text) OWNER TO postgres;

--
-- Name: fn_ca_integrity_detector_health(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_detector_health(p_stale_after_minutes integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_cadence       integer := least(greatest(coalesce(p_stale_after_minutes, 30), 1), 1440);
  v_measured      timestamptz := clock_timestamp();
  v_worker        jsonb;
  v_latest_cron   jsonb;
  v_daily         jsonb := '{}'::jsonb;
  v_tracking      jsonb;
  v_signals       jsonb;
  v_errors        jsonb := '[]'::jsonb;
  v_state         text;
BEGIN
  BEGIN
    v_worker := public.fn_ca_collusion_detector_health(v_cadence);
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'integrity worker health unavailable: %', SQLERRM;
    v_errors := v_errors || jsonb_build_array(
      jsonb_build_object('source', 'collusion_worker_health', 'code', 'SOURCE_UNAVAILABLE'));
  END;

  BEGIN
    SELECT to_jsonb(e)
      INTO v_latest_cron
      FROM public.cron_execution_log e
     WHERE regexp_replace(replace(lower(e.job_name), '_', '-'), '^.*/', '') = 'collusion-scan'
     ORDER BY e.started_at DESC, e.id DESC
     LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'integrity cron execution health unavailable: %', SQLERRM;
    v_errors := v_errors || jsonb_build_array(
      jsonb_build_object('source', 'cron_execution_log', 'code', 'SOURCE_UNAVAILABLE'));
  END;

  BEGIN
    EXECUTE $sql$
      SELECT coalesce(jsonb_object_agg(q.source_key, q.payload), '{}'::jsonb)
        FROM (
          SELECT CASE j.jobname
                   WHEN 'ca-collusion-daily' THEN 'chip_flow'
                   WHEN 'ca-duel-pairing-daily' THEN 'duel_pairing'
                 END AS source_key,
                 jsonb_build_object(
                   'job_name', j.jobname,
                   'active', j.active,
                   'status', d.status,
                   'started_at', d.start_time,
                   'finished_at', d.end_time,
                   'return_message', d.return_message
                 ) AS payload
            FROM cron.job j
            LEFT JOIN LATERAL (
              SELECT r.status, r.start_time, r.end_time, r.return_message
                FROM cron.job_run_details r
               WHERE r.jobid = j.jobid
               ORDER BY r.runid DESC
               LIMIT 1
            ) d ON true
           WHERE j.jobname IN ('ca-collusion-daily', 'ca-duel-pairing-daily')
        ) q
       WHERE q.source_key IS NOT NULL
    $sql$ INTO v_daily;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'integrity pg_cron health unavailable: %', SQLERRM;
    v_errors := v_errors || jsonb_build_array(
      jsonb_build_object('source', 'pg_cron_daily_scans', 'code', 'SOURCE_UNAVAILABLE'));
  END;

  IF v_worker IS NOT NULL
     AND jsonb_typeof(v_latest_cron -> 'result') = 'object'
     AND (v_latest_cron -> 'result') ? 'detection_span_minutes'
     AND (v_latest_cron -> 'result') ? 'detection_thresholds' THEN
    v_worker := v_worker || jsonb_build_object(
      'detection_span_minutes', v_latest_cron #> '{result,detection_span_minutes}',
      'detection_thresholds', v_latest_cron #> '{result,detection_thresholds}');
  END IF;

  BEGIN
    SELECT jsonb_build_object(
             'newest_at', max(c.created_at),
             'total', count(*)::bigint,
             'total_open', count(*) FILTER (WHERE coalesce(c.status, 'open') = 'open')::bigint
           )
      INTO v_tracking
      FROM public.collusion_tracking c;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'integrity collusion_tracking health unavailable: %', SQLERRM;
    v_errors := v_errors || jsonb_build_array(
      jsonb_build_object('source', 'collusion_tracking', 'code', 'SOURCE_UNAVAILABLE'));
  END;

  BEGIN
    SELECT jsonb_build_object(
             'newest_at', max(s.detected_at),
             'total', count(*)::bigint,
             'chip_flow_rows', count(*) FILTER (WHERE s.detail ->> 'signal' IS NULL)::bigint,
             'duel_pairing_rows', count(*) FILTER (
               WHERE s.detail ->> 'signal' = 'duel_repeat_pairing')::bigint
           )
      INTO v_signals
      FROM public.ca_collusion_signals s;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'integrity ca_collusion_signals health unavailable: %', SQLERRM;
    v_errors := v_errors || jsonb_build_array(
      jsonb_build_object('source', 'ca_collusion_signals', 'code', 'SOURCE_UNAVAILABLE'));
  END;

  v_state := CASE
    WHEN v_worker IS NULL THEN 'unknown'
    WHEN coalesce(v_worker ->> 'status', 'unknown') <> 'live' THEN 'degraded'
    WHEN coalesce((v_worker ->> 'stale')::boolean, true) THEN 'degraded'
    WHEN jsonb_array_length(v_errors) > 0 THEN 'degraded'
    WHEN NOT (v_daily ? 'chip_flow') OR NOT (v_daily ? 'duel_pairing') THEN 'degraded'
    ELSE 'live'
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'state', v_state,
    'measured_at', v_measured,
    'worker', v_worker,
    'latest_cron', v_latest_cron,
    'daily_scans', coalesce(v_daily, '{}'::jsonb),
    'sources', jsonb_build_object(
      'collusion_tracking', v_tracking,
      'ca_collusion_signals', v_signals),
    'source_errors', v_errors);
END;
$_$;


ALTER FUNCTION public.fn_ca_integrity_detector_health(p_stale_after_minutes integer) OWNER TO postgres;

--
-- Name: fn_ca_integrity_flags(timestamp with time zone, integer, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_flags(p_as_of timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 50, p_cursor jsonb DEFAULT NULL::jsonb, p_include_horses boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_as_of   timestamptz := least(coalesce(p_as_of, now()), now());
  v_limit   integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_include boolean := coalesce(p_include_horses, true);
  v_rows    jsonb;
  v_total   bigint;
  v_next    jsonb;
BEGIN
  IF p_cursor IS NOT NULL AND NOT (p_cursor ?& array['flagged_at', 'id']) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CURSOR',
                              'message', 'The flag cursor is incomplete');
  END IF;

  WITH scoped AS MATERIALIZED (
    SELECT
      f.*,
      coalesce((to_jsonb(p) ->> 'is_horse')::boolean, false) AS player_is_horse,
      coalesce(to_jsonb(p) ->> 'display_name', to_jsonb(p) ->> 'username', f.player_id::text) AS player_name,
      (SELECT count(*)::integer FROM public.anti_cheat_events e
        WHERE e.player_id = f.player_id
          AND e.created_at <= v_as_of
          AND e.created_at >= v_as_of - interval '30 days') AS event_count_30d,
      (SELECT to_jsonb(e) FROM public.anti_cheat_events e
        WHERE e.player_id = f.player_id AND e.created_at <= v_as_of
        ORDER BY e.created_at DESC, e.id DESC LIMIT 1) AS latest_event
    FROM public.anti_cheat_flags f
    LEFT JOIN public.profiles p ON p.id = f.player_id
    WHERE coalesce(f.status, 'open') = 'open'
      AND f.flagged_at <= v_as_of
  ), selected AS MATERIALIZED (
    SELECT s.*
    FROM scoped s
    WHERE (v_include OR NOT s.player_is_horse)
      AND (p_cursor IS NULL OR ROW(s.flagged_at, s.id) < ROW(
        (p_cursor ->> 'flagged_at')::timestamptz,
        (p_cursor ->> 'id')::uuid))
  ), page AS MATERIALIZED (
    SELECT s.*, row_number() OVER (ORDER BY s.flagged_at DESC, s.id DESC) AS rn
    FROM selected s
    ORDER BY s.flagged_at DESC, s.id DESC
    LIMIT v_limit + 1
  )
  SELECT
    coalesce(jsonb_agg(
      (to_jsonb(p) - 'rn') ORDER BY p.rn) FILTER (WHERE p.rn <= v_limit), '[]'::jsonb),
    (SELECT count(*)::bigint FROM scoped),
    CASE WHEN count(*) > v_limit THEN (
      SELECT jsonb_build_object('flagged_at', z.flagged_at, 'id', z.id)
      FROM page z WHERE z.rn = v_limit) END
    INTO v_rows, v_total, v_next
    FROM page p;

  RETURN jsonb_build_object(
    'ok', true,
    'state', CASE WHEN v_total > 0 THEN 'review_available' ELSE 'nothing_to_review' END,
    'flags', v_rows,
    'rows', v_rows,
    'total', v_total,
    'as_of', v_as_of,
    'measured_at', clock_timestamp(),
    'next_cursor', v_next);
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
  RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CURSOR',
                            'message', 'The flag cursor is invalid', 'state', 'unknown');
WHEN OTHERS THEN
  RAISE NOTICE 'fn_ca_integrity_flags source error: %', SQLERRM;
  RETURN jsonb_build_object('ok', false, 'code', 'FLAGS_SOURCE_ERROR',
                            'message', 'The anti-cheat source could not be read', 'state', 'unknown');
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_flags(p_as_of timestamp with time zone, p_limit integer, p_cursor jsonb, p_include_horses boolean) OWNER TO postgres;

--
-- Name: fn_ca_integrity_hands(uuid, uuid, timestamp with time zone, integer, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_hands(p_player_id uuid DEFAULT NULL::uuid, p_pair_player_id uuid DEFAULT NULL::uuid, p_as_of timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 25, p_cursor jsonb DEFAULT NULL::jsonb, p_include_horses boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_as_of      timestamptz := least(coalesce(p_as_of, now()), now());
  v_limit      integer := least(greatest(coalesce(p_limit, 25), 1), 50);
  v_candidate  integer := 500;
  v_rows       jsonb;
  v_next       jsonb;
  v_match      bigint;
BEGIN
  IF p_pair_player_id IS NOT NULL AND p_player_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'PLAYER_ID_REQUIRED',
                              'message', 'A primary player is required for pair search');
  END IF;
  IF p_cursor IS NOT NULL AND NOT (p_cursor ?& array['created_at', 'id']) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CURSOR',
                              'message', 'The hand cursor is incomplete');
  END IF;

  WITH candidates AS MATERIALIZED (
    SELECT h.id, h.table_id, h.tournament_id, h.hand_number, h.game_variant,
           h.pot_size, h.big_blind, h.small_blind, h.players, h.winners,
           h.actions, h.created_at
    FROM public.hand_history h
    WHERE h.created_at <= v_as_of
      AND (p_cursor IS NULL OR ROW(h.created_at, h.id) < ROW(
        (p_cursor ->> 'created_at')::timestamptz,
        (p_cursor ->> 'id')::uuid))
    ORDER BY h.created_at DESC, h.id DESC
    LIMIT v_candidate
  ), matched AS MATERIALIZED (
    SELECT c.*
    FROM candidates c
    WHERE (p_player_id IS NULL OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(coalesce(c.players, '[]'::jsonb)) x
       WHERE coalesce(x ->> 'user_id', x ->> 'userId', x ->> 'id') = p_player_id::text))
      AND (p_pair_player_id IS NULL OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(coalesce(c.players, '[]'::jsonb)) x
       WHERE coalesce(x ->> 'user_id', x ->> 'userId', x ->> 'id') = p_pair_player_id::text))
  ), page AS MATERIALIZED (
    SELECT m.*, row_number() OVER (ORDER BY m.created_at DESC, m.id DESC) AS rn
    FROM matched m
    ORDER BY m.created_at DESC, m.id DESC
    LIMIT v_limit + 1
  )
  SELECT
    coalesce(jsonb_agg((to_jsonb(p) - 'rn') ORDER BY p.rn)
      FILTER (WHERE p.rn <= v_limit), '[]'::jsonb),
    (SELECT count(*)::bigint FROM matched),
    CASE WHEN count(*) > v_limit THEN (
      SELECT jsonb_build_object('created_at', z.created_at, 'id', z.id)
      FROM page z WHERE z.rn = v_limit) END
    INTO v_rows, v_match, v_next
    FROM page p;

  RETURN jsonb_build_object(
    'ok', true,
    'state', CASE WHEN v_match > 0 THEN 'hands_available' ELSE 'nothing_to_review' END,
    'hands', v_rows,
    'rows', v_rows,
    'matched_in_sample', v_match,
    'candidate_cap', v_candidate,
    'truncated', true,
    'include_horses', coalesce(p_include_horses, true),
    'as_of', v_as_of,
    'measured_at', clock_timestamp(),
    'next_cursor', v_next,
    'coverage_note', 'Search examines the newest 500 candidate hands per page before player filters.');
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
  RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CURSOR',
                            'message', 'The hand cursor is invalid', 'state', 'unknown');
WHEN OTHERS THEN
  RAISE NOTICE 'fn_ca_integrity_hands source error: %', SQLERRM;
  RETURN jsonb_build_object('ok', false, 'code', 'HANDS_SOURCE_ERROR',
                            'message', 'The hand-history source could not be read', 'state', 'unknown');
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_hands(p_player_id uuid, p_pair_player_id uuid, p_as_of timestamp with time zone, p_limit integer, p_cursor jsonb, p_include_horses boolean) OWNER TO postgres;

--
-- Name: fn_ca_integrity_json_numeric(jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_json_numeric(p_value jsonb, p_key text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  SELECT CASE
    WHEN p_value ->> p_key ~ '^-?[0-9]+([.][0-9]+)?$'
      THEN (p_value ->> p_key)::numeric
    ELSE NULL
  END
$_$;


ALTER FUNCTION public.fn_ca_integrity_json_numeric(p_value jsonb, p_key text) OWNER TO postgres;

--
-- Name: fn_ca_integrity_normalize_subjects(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_normalize_subjects(p_subject_ids uuid[]) RETURNS uuid[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT array_agg(DISTINCT x ORDER BY x)
    FROM unnest(p_subject_ids) AS u(x)
   WHERE x IS NOT NULL;
$$;


ALTER FUNCTION public.fn_ca_integrity_normalize_subjects(p_subject_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_ca_integrity_pairs(boolean, text, timestamp with time zone, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_pairs(p_include_horses boolean DEFAULT true, p_composition text DEFAULT 'all'::text, p_as_of timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 50, p_cursor jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_queue jsonb;
BEGIN
  v_queue := public.fn_ca_integrity_queue(
    p_include_horses => coalesce(p_include_horses, true),
    p_composition => p_composition,
    p_tier => 'money_flow',
    p_pattern => NULL,
    p_as_of => p_as_of,
    p_limit => p_limit,
    p_cursor => p_cursor);

  IF coalesce((v_queue ->> 'ok')::boolean, false) IS NOT TRUE THEN
    RETURN v_queue;
  END IF;
  RETURN v_queue || jsonb_build_object(
    'pairs', v_queue -> 'groups',
    'matrix', v_queue -> 'groups',
    'view', 'money_flow');
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_pairs(p_include_horses boolean, p_composition text, p_as_of timestamp with time zone, p_limit integer, p_cursor jsonb) OWNER TO postgres;

--
-- Name: fn_ca_integrity_queue(boolean, text, text, text, timestamp with time zone, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_queue(p_include_horses boolean DEFAULT true, p_composition text DEFAULT 'all'::text, p_tier text DEFAULT NULL::text, p_pattern text DEFAULT NULL::text, p_as_of timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 50, p_cursor jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_include     boolean := coalesce(p_include_horses, true);
  v_composition text := lower(coalesce(nullif(btrim(p_composition), ''), 'all'));
  v_tier        text := lower(nullif(btrim(coalesce(p_tier, '')), ''));
  v_pattern     text := upper(nullif(btrim(coalesce(p_pattern, '')), ''));
  v_as_of       timestamptz := least(coalesce(p_as_of, now()), now());
  v_limit       integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_health      jsonb;
  v_result      jsonb;
BEGIN
  IF v_composition NOT IN ('all', 'horse_horse', 'horse_human', 'human_human') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_COMPOSITION',
                              'message', 'Unknown participant composition');
  END IF;
  IF v_tier IS NOT NULL AND v_tier NOT IN (
    'active_case', 'multiple_signals', 'seven_day_money_flow',
    'chip_dump', 'other_non_timing', 'timing_only', 'money_flow'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_TIER',
                              'message', 'Unknown integrity queue tier');
  END IF;
  IF v_pattern IS NOT NULL AND v_pattern NOT IN (
    'TIMING_CORRELATION', 'CHIP_DUMP', 'SOFT_PLAY', 'WIN_RATE_ANOMALY',
    'CHIP_FLOW_7D', 'DUEL_REPEAT_PAIRING'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_PATTERN',
                              'message', 'Unknown detector pattern');
  END IF;

  IF p_cursor IS NOT NULL AND NOT (
    p_cursor ?& array[
      'tier_rank', 'distinct_window_count', 'absolute_net_flow',
      'gross_flow', 'sample_size', 'last_seen',
      'player_a_id', 'player_b_id'
    ]
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CURSOR',
                              'message', 'The queue cursor is incomplete');
  END IF;

  v_health := public.fn_ca_integrity_detector_health(30);

  WITH source_rows AS MATERIALIZED (
    SELECT
      least(c.player_a, c.player_b) AS player_a_id,
      greatest(c.player_a, c.player_b) AS player_b_id,
      'collusion_tracking'::text AS detector_source,
      c.id::text AS source_id,
      upper(c.pattern_type) AS pattern,
      c.created_at AS observed_at,
      c.suspicion_score::numeric AS source_score,
      greatest(
        coalesce(public.fn_ca_integrity_json_numeric(c.evidence, 'hands'), 0),
        coalesce(public.fn_ca_integrity_json_numeric(c.evidence, 'hands_together'), 0),
        coalesce(public.fn_ca_integrity_json_numeric(c.evidence, 'head_to_head_pots'), 0),
        coalesce(public.fn_ca_integrity_json_numeric(c.evidence, 'total_adjacent_actions'), 0),
        coalesce(public.fn_ca_integrity_json_numeric(c.evidence, 'mutual_checkdowns'), 0)
      ) AS sample_size,
      CASE WHEN upper(c.pattern_type) = 'CHIP_DUMP'
        THEN public.fn_ca_integrity_json_numeric(c.evidence, 'pot_volume') END AS gross_flow,
      NULL::numeric AS net_flow,
      coalesce(to_jsonb(c) ->> 'window_start', c.created_at::text)
        || '/' || coalesce(to_jsonb(c) ->> 'window_end', c.created_at::text) AS window_key,
      jsonb_build_object(
        'reported_player_a', c.player_a,
        'reported_player_b', c.player_b,
        'meaning', CASE WHEN upper(c.pattern_type) = 'CHIP_DUMP'
          THEN 'player_a is the dominant loser and player_b is the dominant winner'
          ELSE 'detector-reported order; canonical pair order is separate' END
      ) AS direction,
      coalesce(c.evidence, '{}'::jsonb) AS evidence
    FROM public.collusion_tracking c
    WHERE c.status = 'open'
      AND c.player_b IS NOT NULL
      AND c.created_at <= v_as_of

    UNION ALL

    SELECT
      least(s.user_a, s.user_b) AS player_a_id,
      greatest(s.user_a, s.user_b) AS player_b_id,
      'ca_collusion_signals'::text AS detector_source,
      s.id::text AS source_id,
      CASE WHEN s.detail ->> 'signal' = 'duel_repeat_pairing'
        THEN 'DUEL_REPEAT_PAIRING' ELSE 'CHIP_FLOW_7D' END AS pattern,
      s.detected_at AS observed_at,
      round(s.direction_ratio * 100, 2) AS source_score,
      s.hands_together::numeric AS sample_size,
      s.gross_flow,
      abs(s.net_flow) AS net_flow,
      coalesce(s.detail ->> 'since', s.detected_at::text)
        || '/' || s.detected_at::text AS window_key,
      jsonb_build_object(
        'receiver_id', s.user_a,
        'sender_id', s.user_b,
        'meaning', CASE WHEN s.detail ->> 'signal' = 'duel_repeat_pairing'
          THEN 'user_a is the dominant winner; hands_together means heads-up duels and direction_ratio means win share'
          ELSE 'user_a is the net receiver; hands_together means hands and direction_ratio means net-flow concentration' END
      ) AS direction,
      coalesce(s.detail, '{}'::jsonb) || jsonb_build_object(
        'hands_together', s.hands_together,
        'gross_flow', s.gross_flow,
        'net_flow', s.net_flow,
        'direction_ratio', s.direction_ratio,
        'both_cert', s.both_cert) AS evidence
    FROM public.ca_collusion_signals s
    WHERE s.detected_at <= v_as_of
      AND s.detected_at >= v_as_of - make_interval(
        days => least(greatest(coalesce(s.window_days, 7), 1), 30) + 1)
  ), grouped AS MATERIALIZED (
    SELECT
      r.player_a_id,
      r.player_b_id,
      count(*)::integer AS observation_count,
      count(DISTINCT r.detector_source || ':' || r.window_key)::integer AS distinct_window_count,
      count(DISTINCT r.detector_source)::integer AS source_count,
      count(DISTINCT r.pattern)::integer AS pattern_count,
      array_agg(DISTINCT r.detector_source ORDER BY r.detector_source) AS detector_sources,
      array_agg(DISTINCT r.pattern ORDER BY r.pattern) AS patterns,
      min(r.observed_at) AS first_seen,
      max(r.observed_at) AS last_seen,
      max(r.source_score) AS max_score,
      max(r.sample_size) AS sample_size,
      max(r.gross_flow) AS gross_flow,
      max(abs(r.net_flow)) AS absolute_net_flow,
      bool_or(r.pattern IN ('CHIP_DUMP', 'CHIP_FLOW_7D', 'DUEL_REPEAT_PAIRING')) AS has_money,
      bool_or(r.detector_source = 'ca_collusion_signals') AS has_seven_day,
      bool_or(r.pattern = 'CHIP_DUMP') AS has_chip_dump,
      bool_or(r.pattern NOT IN (
        'TIMING_CORRELATION', 'CHIP_DUMP', 'CHIP_FLOW_7D', 'DUEL_REPEAT_PAIRING')) AS has_non_timing,
      jsonb_agg(jsonb_build_object(
        'source', r.detector_source,
        'source_id', r.source_id,
        'pattern', r.pattern,
        'observed_at', r.observed_at,
        'score', r.source_score,
        'gross_flow', r.gross_flow,
        'net_flow', r.net_flow,
        'window_key', r.window_key,
        'direction', r.direction,
        'evidence', r.evidence
      ) ORDER BY r.observed_at DESC, r.detector_source, r.source_id) AS evidence
    FROM source_rows r
    GROUP BY r.player_a_id, r.player_b_id
  ), decorated AS MATERIALIZED (
    SELECT
      g.*,
      coalesce(pa.is_horse, false) AS a_horse,
      coalesce(pb.is_horse, false) AS b_horse,
      coalesce(pa.display_name, pa.username, g.player_a_id::text) AS player_a_name,
      coalesce(pb.display_name, pb.username, g.player_b_id::text) AS player_b_name,
      CASE
        WHEN coalesce(pa.is_horse, false)
         AND coalesce(pb.is_horse, false) THEN 'horse_horse'
        WHEN coalesce(pa.is_horse, false)
          OR coalesce(pb.is_horse, false) THEN 'horse_human'
        ELSE 'human_human'
      END AS composition,
      (SELECT count(*)::integer
         FROM public.anti_cheat_flags f
        WHERE f.player_id IN (g.player_a_id, g.player_b_id)
          AND coalesce(f.status, 'open') = 'open') AS open_flag_count
    FROM grouped g
    LEFT JOIN public.profiles pa ON pa.id = g.player_a_id
    LEFT JOIN public.profiles pb ON pb.id = g.player_b_id
  ), ranked AS MATERIALIZED (
    SELECT d.*,
      linked.case_summary,
      CASE
        WHEN linked.case_summary IS NOT NULL THEN 1
        WHEN d.source_count > 1 OR d.pattern_count > 1 THEN 2
        WHEN d.has_seven_day THEN 3
        WHEN d.has_chip_dump THEN 4
        WHEN d.has_non_timing OR d.open_flag_count > 0 THEN 5
        ELSE 6
      END AS tier_rank,
      CASE
        WHEN linked.case_summary IS NOT NULL THEN 'active_case'
        WHEN d.source_count > 1 OR d.pattern_count > 1 THEN 'multiple_signals'
        WHEN d.has_seven_day THEN 'seven_day_money_flow'
        WHEN d.has_chip_dump THEN 'chip_dump'
        WHEN d.has_non_timing OR d.open_flag_count > 0 THEN 'other_non_timing'
        ELSE 'timing_only'
      END AS tier,
      CASE
        WHEN linked.case_summary IS NOT NULL THEN 'This pair is attached to an active operator case.'
        WHEN d.source_count > 1 THEN 'More than one independent detector source reported this pair.'
        WHEN d.pattern_count > 1 THEN 'More than one independent detector pattern reported this pair.'
        WHEN d.has_seven_day THEN 'A seven-day chip-flow or duel-repeat detector reported this pair.'
        WHEN d.has_chip_dump THEN 'The incremental detector reported a chip-dump pattern.'
        WHEN d.has_non_timing THEN 'A non-timing behavioral signal reported this pair.'
        WHEN d.open_flag_count > 0 THEN 'One or both participants has an unresolved anti-cheat flag.'
        ELSE 'Timing correlation only. Horses share deterministic HorseLogic, so correlation is expected to be elevated.'
      END AS tier_reason
    FROM decorated d
    LEFT JOIN LATERAL (
      SELECT jsonb_build_object(
        'id', c.id,
        'status', c.status,
        'severity', c.severity,
        'assigned_to', c.assigned_to,
        'opened_at', c.opened_at,
        'version', c.version) AS case_summary
      FROM public.ca_integrity_cases c
      WHERE c.status IN ('open', 'investigating')
        AND c.subject_ids @> ARRAY[d.player_a_id, d.player_b_id]::uuid[]
      ORDER BY c.opened_at DESC, c.id
      LIMIT 1
    ) linked ON true
  ), selected AS MATERIALIZED (
    SELECT r.*
    FROM ranked r
    WHERE (v_include OR (NOT r.a_horse AND NOT r.b_horse))
      AND (v_composition = 'all' OR r.composition = v_composition)
      AND (v_tier IS NULL OR r.tier = v_tier OR (v_tier = 'money_flow' AND r.has_money))
      AND (v_pattern IS NULL OR v_pattern = ANY(r.patterns))
      AND (
        p_cursor IS NULL OR
        ROW(
          r.tier_rank,
          -r.distinct_window_count,
          -coalesce(r.absolute_net_flow, -1),
          -coalesce(r.gross_flow, -1),
          -coalesce(r.sample_size, 0),
          -extract(epoch FROM r.last_seen),
          r.player_a_id,
          r.player_b_id
        ) > ROW(
          (p_cursor ->> 'tier_rank')::integer,
          -(p_cursor ->> 'distinct_window_count')::integer,
          -coalesce((p_cursor ->> 'absolute_net_flow')::numeric, -1),
          -coalesce((p_cursor ->> 'gross_flow')::numeric, -1),
          -coalesce((p_cursor ->> 'sample_size')::numeric, 0),
          -extract(epoch FROM (p_cursor ->> 'last_seen')::timestamptz),
          (p_cursor ->> 'player_a_id')::uuid,
          (p_cursor ->> 'player_b_id')::uuid
        )
      )
  ), page AS MATERIALIZED (
    SELECT s.*, row_number() OVER (
      ORDER BY s.tier_rank, s.distinct_window_count DESC,
        s.absolute_net_flow DESC NULLS LAST, s.gross_flow DESC NULLS LAST,
        s.sample_size DESC NULLS LAST,
        s.last_seen DESC, s.player_a_id, s.player_b_id
    ) AS rn
    FROM selected s
    ORDER BY s.tier_rank, s.distinct_window_count DESC,
      s.absolute_net_flow DESC NULLS LAST, s.gross_flow DESC NULLS LAST,
      s.sample_size DESC NULLS LAST,
      s.last_seen DESC, s.player_a_id, s.player_b_id
    LIMIT v_limit + 1
  ), payload AS (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'queue_key', p.player_a_id::text || ':' || p.player_b_id::text,
      'player_a_id', p.player_a_id,
      'player_b_id', p.player_b_id,
      'player_a_name', p.player_a_name,
      'player_b_name', p.player_b_name,
      'player_a_is_horse', p.a_horse,
      'player_b_is_horse', p.b_horse,
      'composition', p.composition,
      'tier', p.tier,
      'tier_rank', p.tier_rank,
      'tier_reason', p.tier_reason,
      'observation_count', p.observation_count,
      'distinct_window_count', p.distinct_window_count,
      'source_count', p.source_count,
      'pattern_count', p.pattern_count,
      'detector_sources', p.detector_sources,
      'patterns', p.patterns,
      'first_seen', p.first_seen,
      'last_seen', p.last_seen,
      'max_score', p.max_score,
      'sample_size', p.sample_size,
      'gross_flow', p.gross_flow,
      'absolute_net_flow', p.absolute_net_flow,
      'open_flag_count', p.open_flag_count,
      'case', p.case_summary,
      'evidence', p.evidence,
      'disclosure', 'Queue priority is review order, not a verdict.'
    ) ORDER BY p.rn) FILTER (WHERE p.rn <= v_limit), '[]'::jsonb) AS rows,
    CASE WHEN count(*) > v_limit THEN (
      SELECT jsonb_build_object(
        'tier_rank', z.tier_rank,
        'distinct_window_count', z.distinct_window_count,
        'absolute_net_flow', z.absolute_net_flow,
        'gross_flow', z.gross_flow,
        'sample_size', z.sample_size,
        'last_seen', z.last_seen,
        'player_a_id', z.player_a_id,
        'player_b_id', z.player_b_id)
      FROM page z WHERE z.rn = v_limit
    ) END AS next_cursor
    FROM page p
  ), totals AS (
    SELECT jsonb_build_object(
      'groups', (SELECT count(*)::bigint FROM ranked),
      'observations', (SELECT count(*)::bigint FROM source_rows),
      'filtered_groups', (SELECT count(*)::bigint FROM selected),
      'by_tier', coalesce((SELECT jsonb_object_agg(x.tier, x.n)
        FROM (SELECT tier, count(*)::bigint AS n FROM ranked GROUP BY tier) x), '{}'::jsonb),
      'by_pattern', coalesce((SELECT jsonb_object_agg(x.pattern, x.n)
        FROM (SELECT pattern, count(*)::bigint AS n
          FROM ranked r CROSS JOIN LATERAL unnest(r.patterns) pattern GROUP BY pattern) x), '{}'::jsonb),
      'by_composition', coalesce((SELECT jsonb_object_agg(x.composition, x.n)
        FROM (SELECT composition, count(*)::bigint AS n FROM ranked GROUP BY composition) x), '{}'::jsonb),
      'by_source', coalesce((SELECT jsonb_object_agg(x.detector_source, x.n)
        FROM (SELECT detector_source, count(*)::bigint AS n
          FROM source_rows GROUP BY detector_source) x), '{}'::jsonb)
    ) AS value
  )
  SELECT jsonb_build_object(
    'ok', true,
    'state', CASE
      WHEN coalesce(v_health ->> 'state', 'unknown') = 'unknown' THEN 'unknown'
      WHEN (SELECT count(*) FROM selected) > 0 THEN 'review_available'
      WHEN coalesce(v_health #>> '{worker,newest_finding_at}', '') = ''
       AND coalesce((v_health #>> '{sources,ca_collusion_signals,total}')::bigint, 0) = 0
        THEN 'nothing_produced'
      ELSE 'nothing_to_review' END,
    'queue_state', CASE
      WHEN coalesce(v_health ->> 'state', 'unknown') = 'unknown' THEN 'unknown'
      WHEN (SELECT count(*) FROM selected) > 0 THEN 'review_available'
      WHEN coalesce(v_health #>> '{worker,newest_finding_at}', '') = ''
       AND coalesce((v_health #>> '{sources,ca_collusion_signals,total}')::bigint, 0) = 0
        THEN 'nothing_produced'
      ELSE 'nothing_to_review' END,
    'rows', payload.rows,
    'groups', payload.rows,
    'totals', totals.value,
    'as_of', v_as_of,
    'measured_at', clock_timestamp(),
    'next_cursor', payload.next_cursor,
    'health', v_health,
    'ranking', jsonb_build_object(
      'tiers', jsonb_build_array(
        'active_case', 'multiple_signals', 'seven_day_money_flow',
        'chip_dump', 'other_non_timing', 'timing_only'),
      'rule', 'Lexicographic review priority; unlike detector scores are never blended.'),
    'disclosure', jsonb_build_array(
      'Horses are players and are included by default.',
      'Queue priority is review order, not a verdict.',
      'Horse timing correlation is elevated by shared deterministic HorseLogic.',
      'Repeated raw observations are grouped by canonical unordered pair.'
    )
  ) INTO v_result
  FROM payload CROSS JOIN totals;

  RETURN v_result;
EXCEPTION
  WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CURSOR',
                              'message', 'The queue cursor is invalid',
                              'state', 'unknown', 'queue_state', 'unknown',
                              'health', v_health, 'as_of', v_as_of,
                              'measured_at', clock_timestamp());
  WHEN OTHERS THEN
    RAISE NOTICE 'fn_ca_integrity_queue source error: %', SQLERRM;
    RETURN jsonb_build_object('ok', false, 'code', 'QUEUE_SOURCE_ERROR',
                              'message', 'One or more integrity queue sources could not be read',
                              'state', 'unknown', 'queue_state', 'unknown',
                              'health', v_health, 'as_of', v_as_of,
                              'measured_at', clock_timestamp());
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_queue(p_include_horses boolean, p_composition text, p_tier text, p_pattern text, p_as_of timestamp with time zone, p_limit integer, p_cursor jsonb) OWNER TO postgres;

--
-- Name: fn_ca_integrity_sanction(uuid, uuid, text, numeric, uuid, uuid, text, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_sanction(p_case_id uuid, p_subject_id uuid, p_kind text, p_amount numeric, p_restriction_id uuid, p_approval_id uuid, p_note text, p_actor uuid, p_op_id text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_case public.ca_integrity_cases;
  v_sanction public.ca_integrity_sanctions;
  v_payload jsonb;
  v_hash text;
  v_state text;
  v_expected_decision text;
BEGIN
  IF p_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACTOR_REQUIRED', 'message', 'Operator identity is required');
  END IF;
  IF p_op_id IS NULL OR length(btrim(p_op_id)) NOT BETWEEN 8 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'OP_ID_REQUIRED', 'message', 'A bounded operation id is required');
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('warning', 'restriction', 'confiscation') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_SANCTION', 'message', 'Unknown sanction kind');
  END IF;
  IF length(btrim(coalesce(p_note, ''))) NOT BETWEEN 10 AND 4000 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_NOTE', 'message', 'A sanction note of at least ten characters is required');
  END IF;
  IF p_kind = 'confiscation' AND (p_amount IS NULL OR p_amount <= 0 OR p_approval_id IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'APPROVAL_REQUIRED', 'message', 'A positive amount and approval are required for confiscation');
  END IF;
  IF p_kind <> 'confiscation' AND (p_amount IS NOT NULL OR p_approval_id IS NOT NULL) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_MONEY_FIELDS', 'message', 'Only confiscation may carry money approval fields');
  END IF;
  IF p_kind = 'restriction' AND p_restriction_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'RESTRICTION_REQUIRED', 'message', 'A restriction record is required');
  END IF;
  IF p_kind <> 'restriction' AND p_restriction_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_RESTRICTION', 'message', 'Only a restriction sanction may name a restriction');
  END IF;

  v_payload := jsonb_build_object(
    'case_id', p_case_id, 'subject_id', p_subject_id, 'kind', p_kind,
    'amount', p_amount, 'asset', CASE WHEN p_kind = 'confiscation' THEN 'chips' ELSE NULL END,
    'restriction_id', p_restriction_id, 'approval_id', p_approval_id, 'note', btrim(p_note));
  v_hash := md5(v_payload::text);
  SELECT * INTO v_sanction FROM public.ca_integrity_sanctions s WHERE s.op_id = p_op_id;
  IF FOUND THEN
    IF v_sanction.payload_hash <> v_hash THEN
      RETURN jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT', 'message', 'This operation id was used for a different sanction');
    END IF;
    RETURN jsonb_build_object('ok', true, 'sanction', to_jsonb(v_sanction), 'idempotent', true);
  END IF;

  SELECT * INTO v_case FROM public.ca_integrity_cases c WHERE c.id = p_case_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND', 'message', 'Integrity case not found');
  END IF;
  IF v_case.status = 'closed' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CASE_CLOSED', 'message', 'A closed case cannot receive a sanction');
  END IF;
  IF v_case.status <> 'decided' OR v_case.decision IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'DECISION_REQUIRED', 'message', 'A human decision is required before a sanction');
  END IF;

  v_expected_decision := CASE p_kind
    WHEN 'warning' THEN 'warned'
    WHEN 'restriction' THEN 'restricted'
    WHEN 'confiscation' THEN 'confiscated'
  END;
  IF v_case.decision <> v_expected_decision THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'SANCTION_DECISION_MISMATCH',
      'message', 'The sanction must match the human decision recorded on the case');
  END IF;
  IF NOT (p_subject_id = ANY(v_case.subject_ids)) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'SUBJECT_NOT_IN_CASE', 'message', 'That player is not a subject of this case');
  END IF;
  IF p_kind = 'restriction' AND NOT EXISTS (
    SELECT 1 FROM public.ca_player_restrictions r
     WHERE r.id = p_restriction_id AND r.user_id = p_subject_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'RESTRICTION_NOT_FOUND', 'message', 'That restriction does not belong to this case subject');
  END IF;
  IF p_kind = 'confiscation' AND NOT EXISTS (
    SELECT 1 FROM public.ca_operator_approvals a
     WHERE a.id = p_approval_id AND a.kind = 'sanction' AND a.status = 'approved'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'APPROVAL_NOT_APPROVED', 'message', 'The confiscation approval is not approved');
  END IF;

  -- Warnings and existing restrictions have already happened elsewhere. A
  -- confiscation is only an approved decision record: this function never
  -- debits chips and deliberately cannot mark it applied.
  v_state := CASE WHEN p_kind = 'confiscation' THEN 'approved' ELSE 'applied' END;
  INSERT INTO public.ca_integrity_sanctions (
    case_id, subject_id, kind, state, amount, asset, restriction_id, approval_id,
    payload, payload_hash, proposed_by, applied_by, applied_at, note, op_id)
  VALUES (
    p_case_id, p_subject_id, p_kind, v_state, p_amount,
    CASE WHEN p_kind = 'confiscation' THEN 'chips' ELSE NULL END,
    p_restriction_id, p_approval_id, v_payload, v_hash, p_actor,
    CASE WHEN v_state = 'applied' THEN p_actor ELSE NULL END,
    CASE WHEN v_state = 'applied' THEN now() ELSE NULL END,
    btrim(p_note), p_op_id)
  RETURNING * INTO v_sanction;

  INSERT INTO public.ca_integrity_case_items (
    case_id, item_type, detail, snapshot_hash, added_by, op_id, payload_hash)
  VALUES (
    p_case_id, 'sanction', jsonb_build_object('sanction_id', v_sanction.id, 'kind', p_kind, 'state', v_state),
    md5(jsonb_build_object('sanction_id', v_sanction.id, 'kind', p_kind, 'state', v_state)::text),
    p_actor, md5('integrity-sanction-event:' || p_op_id), v_hash);

  PERFORM public.fn_ca_integrity_audit(
    p_actor, 'integrity.sanction_propose', 'integrity_case', p_case_id::text,
    jsonb_build_object('op_id', p_op_id, 'kind', p_kind, 'no_chips_moved', p_kind = 'confiscation'),
    NULL, to_jsonb(v_sanction), p_ip_address, p_user_agent, p_request_id);
  RETURN jsonb_build_object(
    'ok', true, 'sanction', to_jsonb(v_sanction), 'idempotent', false,
    'no_chips_moved', p_kind = 'confiscation');
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_sanction(p_case_id uuid, p_subject_id uuid, p_kind text, p_amount numeric, p_restriction_id uuid, p_approval_id uuid, p_note text, p_actor uuid, p_op_id text, p_ip_address text, p_user_agent text, p_request_id text) OWNER TO postgres;

--
-- Name: fn_ca_integrity_timing(boolean, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_integrity_timing(p_include_horses boolean DEFAULT true, p_as_of timestamp with time zone DEFAULT now(), p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_hand_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_as_of      timestamptz := least(coalesce(p_as_of, now()), now());
  v_since      timestamptz;
  v_hand_limit integer := least(greatest(coalesce(p_hand_limit, 200), 10), 500);
  v_histogram  jsonb;
  v_pairs      bigint;
  v_hands      bigint;
  v_actions    bigint;
BEGIN
  v_since := greatest(coalesce(p_since, v_as_of - interval '24 hours'),
                      v_as_of - interval '7 days');
  IF v_since >= v_as_of THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_WINDOW',
                              'message', 'Timing window must begin before as_of');
  END IF;

  WITH sampled_hands AS MATERIALIZED (
    SELECT h.id, h.created_at, h.actions
    FROM public.hand_history h
    WHERE h.created_at >= v_since AND h.created_at <= v_as_of
    ORDER BY h.created_at DESC, h.id DESC
    LIMIT v_hand_limit
  ), action_rows AS MATERIALIZED (
    SELECT h.id AS hand_id,
      a.ordinality,
      public.fn_ca_integrity_action_user(a.value) AS user_id,
      public.fn_ca_integrity_action_time(a.value) AS action_at
    FROM sampled_hands h
    CROSS JOIN LATERAL jsonb_array_elements(coalesce(h.actions, '[]'::jsonb))
      WITH ORDINALITY AS a(value, ordinality)
  ), adjacent AS MATERIALIZED (
    SELECT hand_id, user_id,
      lead(user_id) OVER (PARTITION BY hand_id ORDER BY action_at, ordinality) AS next_user_id,
      action_at,
      lead(action_at) OVER (PARTITION BY hand_id ORDER BY action_at, ordinality) AS next_action_at
    FROM action_rows
    WHERE user_id IS NOT NULL AND action_at IS NOT NULL
  ), intervals AS MATERIALIZED (
    SELECT a.hand_id, a.user_id, a.next_user_id,
      greatest(0, extract(epoch FROM a.next_action_at - a.action_at) * 1000)::numeric AS interval_ms,
      coalesce((to_jsonb(p1) ->> 'is_horse')::boolean, false) AS first_horse,
      coalesce((to_jsonb(p2) ->> 'is_horse')::boolean, false) AS second_horse
    FROM adjacent a
    LEFT JOIN public.profiles p1 ON p1.id = a.user_id
    LEFT JOIN public.profiles p2 ON p2.id = a.next_user_id
    WHERE a.next_user_id IS NOT NULL
      AND a.next_action_at IS NOT NULL
      AND a.user_id <> a.next_user_id
      AND a.next_action_at >= a.action_at
      AND a.next_action_at - a.action_at <= interval '60 seconds'
  ), classified AS MATERIALIZED (
    SELECT i.*,
      CASE WHEN i.first_horse AND i.second_horse THEN 'horse_horse'
           WHEN i.first_horse OR i.second_horse THEN 'horse_human'
           ELSE 'human_human' END AS composition,
      CASE WHEN i.interval_ms < 250 THEN 'under_250ms'
           WHEN i.interval_ms < 500 THEN '250_to_499ms'
           WHEN i.interval_ms < 1000 THEN '500_to_999ms'
           WHEN i.interval_ms < 2000 THEN '1000_to_1999ms'
           ELSE '2000ms_plus' END AS bucket
    FROM intervals i
    WHERE coalesce(p_include_horses, true)
       OR (NOT i.first_horse AND NOT i.second_horse)
  )
  SELECT
    coalesce((
      SELECT jsonb_object_agg(c.composition, c.payload)
      FROM (
        SELECT composition, jsonb_build_object(
          'adjacent_pairs', count(*)::bigint,
          'distinct_hands', count(DISTINCT hand_id)::bigint,
          'median_ms', round(percentile_cont(0.5) WITHIN GROUP (ORDER BY interval_ms)::numeric, 1),
          'under_500ms', count(*) FILTER (WHERE interval_ms < 500)::bigint,
          'buckets', (
            SELECT jsonb_object_agg(b.bucket, b.n)
            FROM (SELECT c2.bucket, count(*)::bigint AS n
              FROM classified c2 WHERE c2.composition = classified.composition
              GROUP BY c2.bucket) b)
        ) AS payload
        FROM classified
        GROUP BY composition
      ) c), '{}'::jsonb),
    (SELECT count(*)::bigint FROM classified),
    (SELECT count(*)::bigint FROM sampled_hands),
    (SELECT count(*)::bigint FROM action_rows)
    INTO v_histogram, v_pairs, v_hands, v_actions;

  RETURN jsonb_build_object(
    'ok', true,
    'state', CASE WHEN v_pairs > 0 THEN 'sample_available' ELSE 'nothing_produced' END,
    'distribution', v_histogram,
    'histogram', v_histogram,
    'coverage', jsonb_build_object(
      'since', v_since,
      'as_of', v_as_of,
      'hand_cap', v_hand_limit,
      'hands_sampled', v_hands,
      'actions_sampled', v_actions,
      'adjacent_pairs', v_pairs,
      'truncated', v_hands >= v_hand_limit),
    'measured_at', clock_timestamp(),
    'disclosure', jsonb_build_array(
      'This is adjacent-action interval evidence, not an RTA verdict.',
      'Horse rows are shown beside human rows because horses share deterministic HorseLogic.',
      'There is no complete human decision-latency table; this view uses a bounded hand-history sample.'
    ));
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'fn_ca_integrity_timing source error: %', SQLERRM;
  RETURN jsonb_build_object('ok', false, 'code', 'TIMING_SOURCE_ERROR',
                            'message', 'The timing sample could not be read', 'state', 'unknown',
                            'as_of', v_as_of, 'measured_at', clock_timestamp());
END;
$$;


ALTER FUNCTION public.fn_ca_integrity_timing(p_include_horses boolean, p_as_of timestamp with time zone, p_since timestamp with time zone, p_hand_limit integer) OWNER TO postgres;

--
-- Name: fn_ca_is_cert_account(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_is_cert_account(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- DEFINER, like fn_ca_is_fixture_account. It reads auth.users, which `authenticated` cannot
  -- select from, so as INVOKER it answered one thing for service_role and another for everyone
  -- else - a predicate whose result depended on the caller rather than the account.
  --
  -- A HORSE IS A PLAYER (CLAUDE.md 10.5), so it is never certification equipment, whatever its
  -- address looks like. The fleet shares an email domain, which classified 468 of them as test
  -- equipment until 2026-09-08.
  SELECT p_user_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = p_user_id AND COALESCE(p.is_horse, false))
    AND (
      EXISTS (SELECT 1 FROM public.ca_cert_accounts c WHERE c.user_id = p_user_id AND c.active)
      OR p_user_id::text LIKE '00000000-0000-0000-0000-%'
      OR EXISTS (SELECT 1 FROM auth.users u
                  WHERE u.id = p_user_id
                    AND (u.email LIKE '%@horses.smarter.poker'
                         OR u.email LIKE '%.invalid'))
    );
$$;


ALTER FUNCTION public.fn_ca_is_cert_account(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_is_cert_account(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_is_cert_account(p_user_id uuid) IS 'True for a certification account. NEVER true for a horse: a horse is a player (CLAUDE.md 10.5) and the fleet shares an email domain, which used to classify 468 of them as test equipment - refusing them the daily bonus, the wheel and the games, leaving them out of the collusion scan, and reporting 1,324,300 of their diamonds as harness money. Cert accounts are what ca_cert_accounts says they are.';


--
-- Name: fn_ca_is_club_control(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_is_club_control(p_club_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_user_id IS NOT NULL AND (
    EXISTS (
      SELECT 1 FROM public.club_members m
      WHERE m.club_id = p_club_id
        AND m.user_id = p_user_id
        AND COALESCE(m.is_active, true)
        AND COALESCE(m.status, 'active') IN ('active', 'approved')
        AND m.role IN ('owner', 'co_owner', 'admin')
    )
    OR EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = p_club_id AND c.owner_id = p_user_id)
  );
$$;


ALTER FUNCTION public.fn_ca_is_club_control(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_is_club_control(p_club_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_is_club_control(p_club_id uuid, p_user_id uuid) IS 'Club control: the only set that may read every seat''s hole cards, and only through fn_ca_operator_read_hand, which logs it.';


--
-- Name: fn_ca_is_club_staff(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_is_club_staff(p_club_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_user_id IS NOT NULL AND (
    EXISTS (
      SELECT 1 FROM public.club_members m
      WHERE m.club_id = p_club_id
        AND m.user_id = p_user_id
        AND COALESCE(m.is_active, true)
        AND COALESCE(m.status, 'active') IN ('active', 'approved')
        AND m.role IN ('owner', 'co_owner', 'admin', 'manager', 'super_agent', 'agent')
    )
    OR EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = p_club_id AND c.owner_id = p_user_id)
  );
$$;


ALTER FUNCTION public.fn_ca_is_club_staff(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_is_club_staff(p_club_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_is_club_staff(p_club_id uuid, p_user_id uuid) IS 'Club staff: may triage a flagged hand. NOT the set that may read hole cards - see fn_ca_is_club_control.';


--
-- Name: fn_ca_is_fixture_account(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_is_fixture_account(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_user_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = p_user_id AND COALESCE(p.is_horse, false))
    AND (
      p_user_id::text LIKE '00000000-0000-0000-0000-%'
      OR EXISTS (SELECT 1 FROM public.ca_cert_accounts c WHERE c.user_id = p_user_id AND c.active)
      OR EXISTS (SELECT 1 FROM auth.users u WHERE u.id = p_user_id AND u.email LIKE '%.invalid')
    );
$$;


ALTER FUNCTION public.fn_ca_is_fixture_account(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_is_fixture_account(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_is_fixture_account(p_user_id uuid) IS 'A certification or test fixture account: sentinel uuid, active ca_cert_accounts row, or a .invalid email. NEVER a horse. Used to scope diamond incident severity and the promotional budget; never to deny anything.';


--
-- Name: fn_ca_is_midway_scope(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_is_midway_scope(p_union_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((
    -- THE FOUR ESTATES (Dan, 2026-09-03): Midway Union with Club JAQK and
    -- SHARK CLUB inside it, and Deep Stack Society standing alone. Until
    -- chip standard Phase 4.3 (2026-09-04) this scope was Midway only, so an
    -- incident about Deep Stack Society's money - its jackpot reserve running
    -- dry, a payout that could not reconcile - was dropped before it was
    -- filed. Deep Stack is an estate; its incidents file.
    -- platform-substrate incidents: no entity dimension anywhere = global
    -- checks (supply, suspense, guards, crons, diamonds) that protect every
    -- union including Midway. These always file.
    (p_union_id IS NULL AND p_club_id IS NULL AND p_table_id IS NULL
     AND p_tournament_id IS NULL
     AND COALESCE(p_metadata->>'union_id','') = ''
     AND COALESCE(p_metadata->>'club_id','') = '')
    OR p_union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
    OR p_club_id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
    OR EXISTS (
      SELECT 1 FROM public.clubs c
       WHERE c.id = p_club_id
         AND c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
    )
    OR EXISTS (
      SELECT 1 FROM public.union_clubs uc
       WHERE uc.club_id = p_club_id
         AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
    )
    OR EXISTS (
      SELECT 1 FROM public.tables t
      JOIN public.clubs c ON c.id = t.club_id
       WHERE t.id = p_table_id
         AND (
           c.id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
           OR c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           OR EXISTS (
             SELECT 1 FROM public.union_clubs uc
              WHERE uc.club_id = c.id
                AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           )
         )
    )
    OR EXISTS (
      SELECT 1 FROM public.tournaments t
      JOIN public.clubs c ON c.id = t.club_id
       WHERE t.id = p_tournament_id
         AND (
           c.id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
           OR c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           OR EXISTS (
             SELECT 1 FROM public.union_clubs uc
              WHERE uc.club_id = c.id
                AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           )
         )
    )
    OR COALESCE(p_metadata->>'union_id', '') = 'fade0000-0000-0000-0000-000000000001'
    OR EXISTS (
      SELECT 1 FROM public.clubs c
       WHERE c.id::text = COALESCE(p_metadata->>'club_id', '')
         AND (
           c.id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
           OR c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           OR EXISTS (
             SELECT 1 FROM public.union_clubs uc
              WHERE uc.club_id = c.id
                AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           )
         )
    )), false);
$$;


ALTER FUNCTION public.fn_ca_is_midway_scope(p_union_id uuid, p_club_id uuid, p_table_id uuid, p_tournament_id uuid, p_metadata jsonb) OWNER TO postgres;

--
-- Name: fn_ca_issuance_leg_is_registered(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_issuance_leg_is_registered() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_outside text[] := public.fn_ca_noncirculating_chip_stores();
  v_pol public.ca_mint_policy%ROWTYPE;
  v_24h numeric;
BEGIN
  IF NEW.from_type = ANY (v_outside) AND NOT (NEW.to_type = ANY (v_outside))
     AND NEW.category <> 'correction' THEN
    SELECT * INTO v_pol FROM public.ca_mint_policy WHERE id = 1;
    IF NEW.amount > v_pol.per_operation_cap_chips THEN
      RAISE EXCEPTION 'issuance refused: % chips in one leg is over the per-operation ceiling of % (ca_mint_policy; raise it with a reason through fn_ca_mint_policy_set before a deliberate batch)',
        NEW.amount, v_pol.per_operation_cap_chips USING ERRCODE = 'P0403';
    END IF;
    v_24h := public.fn_ca_mint_issued_24h('chips', NEW.id) + NEW.amount;
    IF v_24h > v_pol.rolling_24h_cap_chips THEN
      RAISE EXCEPTION 'issuance refused: this leg would bring the last 24 hours to % chips, over the rolling ceiling of % (ca_mint_policy; raise it with a reason through fn_ca_mint_policy_set before a deliberate batch)',
        v_24h, v_pol.rolling_24h_cap_chips USING ERRCODE = 'P0403';
    END IF;
  END IF;
  PERFORM public.fn_ca_register_issuance_leg(NEW.id);
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_issuance_leg_is_registered() OWNER TO postgres;

--
-- Name: fn_ca_journal_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_journal_append_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reason text := NULLIF(current_setting('app.ledger_maintenance', true), '');
  v_allowed_update boolean := false;
  v_kind text;
  v_j jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF TG_TABLE_NAME = 'chip_transactions' THEN
      v_allowed_update :=
        NEW.amount IS NOT DISTINCT FROM OLD.amount
        AND NEW.transaction_type IS NOT DISTINCT FROM OLD.transaction_type
        AND NEW.from_user_id IS NOT DISTINCT FROM OLD.from_user_id
        AND NEW.to_user_id IS NOT DISTINCT FROM OLD.to_user_id
        AND NEW.club_id IS NOT DISTINCT FROM OLD.club_id
        AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at;
    ELSIF TG_TABLE_NAME = 'chip_ledger' THEN
      v_allowed_update :=
        NEW.amount IS NOT DISTINCT FROM OLD.amount
        AND NEW.from_type IS NOT DISTINCT FROM OLD.from_type
        AND NEW.from_entity_id IS NOT DISTINCT FROM OLD.from_entity_id
        AND NEW.to_type IS NOT DISTINCT FROM OLD.to_type
        AND NEW.to_entity_id IS NOT DISTINCT FROM OLD.to_entity_id
        AND NEW.category IS NOT DISTINCT FROM OLD.category
        AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at
        AND NEW.chain_seq IS NOT DISTINCT FROM OLD.chain_seq
        AND NEW.prev_hash IS NOT DISTINCT FROM OLD.prev_hash
        AND NEW.row_hash IS NOT DISTINCT FROM OLD.row_hash
        AND NEW.idempotency_key IS NOT DISTINCT FROM OLD.idempotency_key
        AND NEW.correlation_id IS NOT DISTINCT FROM OLD.correlation_id
        AND NEW.settlement_id IS NOT DISTINCT FROM OLD.settlement_id
        AND NEW.epoch_id IS NOT DISTINCT FROM OLD.epoch_id;
    ELSIF TG_TABLE_NAME = 'vip_points_ledger' THEN
      /* Phase 8 (2026-09-08). A VIP leg is written once, final: the award
         writer no longer inserts 0 and updates it afterwards. Nothing on this
         table may change. */
      v_allowed_update := false;
    ELSIF TG_TABLE_NAME = 'agent_commissions' THEN
      /* Phase 8. A commission row is what was earned on one hand. The only
         thing that happens to it afterwards is being settled, once. */
      v_allowed_update :=
        NEW.amount IS NOT DISTINCT FROM OLD.amount
        AND NEW.club_id IS NOT DISTINCT FROM OLD.club_id
        AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
        AND NEW.source_type IS NOT DISTINCT FROM OLD.source_type
        AND NEW.source_id IS NOT DISTINCT FROM OLD.source_id
        AND NEW.commission_rate IS NOT DISTINCT FROM OLD.commission_rate
        AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at
        AND (OLD.settled_at IS NULL OR NEW.settled_at IS NOT DISTINCT FROM OLD.settled_at);
    ELSIF TG_TABLE_NAME = 'rakeback_period_payouts' THEN
      /* Phase 8. What was paid, to whom, for which period, never changes;
         status, paid_at, wallet_transaction_id and failure_reason are the
         payout's own bookkeeping. */
      v_allowed_update :=
        NEW.payout_amount IS NOT DISTINCT FROM OLD.payout_amount
        AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
        AND NEW.club_id IS NOT DISTINCT FROM OLD.club_id
        AND NEW.rakeback_period_id IS NOT DISTINCT FROM OLD.rakeback_period_id
        AND NEW.currency IS NOT DISTINCT FROM OLD.currency
        AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at;
    ELSE
      v_allowed_update :=
        NEW.amount IS NOT DISTINCT FROM OLD.amount
        AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND v_allowed_update THEN
    RETURN NEW;
  END IF;

  /* Phase 8. fn_close_settlement_period inserts a payout row as its
     idempotency claim BEFORE debiting the treasury and deletes it again on a
     shortfall, inside the same transaction. That is a compensation, not a
     mutation of history, so this table's DELETE is allowed - and RECORDED,
     every time, so a person can tell a compensation from a hand on the
     table. The meter counts these. */
  IF TG_OP = 'DELETE' AND TG_TABLE_NAME = 'rakeback_period_payouts' THEN
    INSERT INTO public.ca_ledger_mutation_log
      (source_table, operation, db_role, application, reason, old_row, new_row)
    VALUES (TG_TABLE_NAME, TG_OP, current_user,
            current_setting('application_name', true),
            COALESCE(v_reason, 'rakeback-payout-delete: compensation on a treasury shortfall, or maintenance without app.ledger_maintenance'),
            to_jsonb(OLD), NULL);
    RETURN OLD;
  END IF;

  IF v_reason IS NOT NULL THEN
    INSERT INTO public.ca_ledger_mutation_log
      (source_table, operation, db_role, application, reason, old_row, new_row)
    VALUES (TG_TABLE_NAME, TG_OP, current_user,
            current_setting('application_name', true), v_reason,
            to_jsonb(OLD), CASE WHEN TG_OP='UPDATE' THEN to_jsonb(NEW) END);

    BEGIN
      v_kind := split_part(v_reason, ':', 1);
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_journal_append_only', 'unauthorized_adjustment', 'warning',
        'journal-bypass:' || TG_TABLE_NAME || ':' || TG_OP || ':' || v_kind,
        0, NULL, NULL, 'ledger', TG_TABLE_NAME,
        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
        'append-only bypass used on ' || TG_TABLE_NAME || ': ' || TG_OP
          || ' permitted because app.ledger_maintenance was set to "' || v_reason
          || '". The rows are preserved whole in ca_ledger_mutation_log - this incident'
          || ' counts them (occurrences) rather than the chips; query that table by'
          || ' reason for the full inventory. Confirm the maintenance was intended,'
          || ' then resolve.',
        true,
        jsonb_build_object('table', TG_TABLE_NAME, 'operation', TG_OP,
                           'reason', v_reason, 'reason_kind', v_kind,
                           'db_role', current_user,
                           'application', current_setting('application_name', true)));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    -- DR5. The diamond journal is deleted from on an hourly cadence by the
    -- certification fleet. Keep the row and say who took it. Nothing here can
    -- refuse the DELETE the branch above has already permitted.
    IF TG_TABLE_NAME = 'diamond_transactions' AND TG_OP = 'DELETE' THEN
      BEGIN
        v_j := to_jsonb(OLD);
        INSERT INTO public.ca_diamond_journal_archive
          (id, user_id, type, amount, balance_after, description, reference_id, created_at,
           transaction_type, source, metadata, counterparty, issuance_class,
           deleted_profile_id, deletion_reason)
        VALUES
          ((v_j->>'id')::uuid, (v_j->>'user_id')::uuid, v_j->>'type',
           (v_j->>'amount')::integer, (v_j->>'balance_after')::integer,
           v_j->>'description', v_j->>'reference_id', (v_j->>'created_at')::timestamptz,
           v_j->>'transaction_type', v_j->>'source',
           COALESCE(v_j->'metadata', '{}'::jsonb),
           v_j->>'counterparty', v_j->>'issuance_class',
           (v_j->>'user_id')::uuid, v_reason)
        ON CONFLICT (id) DO NOTHING;

        PERFORM public.fn_ca_diamond_incident(
          'DR5:journal_row_deleted_under_maintenance', 'info',
          (v_j->>'user_id')::uuid, (v_j->>'amount')::numeric,
          'fn_ca_journal_append_only',
          jsonb_build_object('reason', v_reason,
                             'reference_id', v_j->>'reference_id',
                             'type', v_j->>'type',
                             'db_role', current_user));
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'ca_diamond_journal_archive could not preserve a journal row deleted under maintenance (%): %',
          v_reason, SQLERRM;
      END;
    END IF;

    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  RAISE EXCEPTION
    '% on % is forbidden: financial journals are append-only. Corrections are new linked rows (category=correction). Set app.ledger_maintenance with an incident reference for authorized maintenance.',
    TG_OP, TG_TABLE_NAME
    USING ERRCODE = 'P0403';
END $$;


ALTER FUNCTION public.fn_ca_journal_append_only() OWNER TO postgres;

--
-- Name: fn_ca_journal_profile_deletion(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_journal_profile_deletion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reason text := NULLIF(current_setting('app.ledger_maintenance', true), '');
  v_archived integer := 0;
  v_baseline timestamptz;
  v_attributed numeric := 0;
  v_burn numeric;
BEGIN
  BEGIN
    INSERT INTO public.ca_profile_deletions
      (profile_id, username, is_horse, diamonds, diamond_balance, profile_created_at)
    VALUES
      (OLD.id, OLD.username, OLD.is_horse, OLD.diamonds, OLD.diamond_balance, OLD.created_at);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'ca_profile_deletions could not record deletion of % (%): %',
      OLD.id, OLD.username, SQLERRM;
  END;

  BEGIN
    INSERT INTO public.ca_diamond_journal_archive
      (id, user_id, type, amount, balance_after, description, reference_id, created_at,
       transaction_type, source, metadata, counterparty, issuance_class,
       deleted_profile_id, deletion_reason)
    SELECT t.id, t.user_id, t.type, t.amount, t.balance_after, t.description,
           t.reference_id, t.created_at, t.transaction_type, t.source, t.metadata,
           t.counterparty, t.issuance_class, OLD.id, v_reason
      FROM public.diamond_transactions t
     WHERE t.user_id = OLD.id
    ON CONFLICT (id) DO NOTHING;
    GET DIAGNOSTICS v_archived = ROW_COUNT;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'ca_diamond_journal_archive could not preserve the journal of % (%): %',
      OLD.id, OLD.username, SQLERRM;
  END;

  -- A balance that leaves with the account has left supply, and so has
  -- anything the register still attributes to the holder. GREATEST is never
  -- less than the balance this trigger burned before 2026-09-05, so the
  -- healthy case is unchanged; it also retires a seed the harness zeroed
  -- outside the journal (18 certification accounts stranded 500 each).
  BEGIN
    SELECT min(created_at) INTO v_baseline
      FROM public.ca_mint_ledger WHERE asset = 'diamonds' AND origin = 'baseline';
    SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
      INTO v_attributed
      FROM public.ca_mint_ledger
     WHERE asset = 'diamonds' AND holder_type = 'player' AND holder_id = OLD.id
       AND (v_baseline IS NULL OR created_at >= v_baseline);
  EXCEPTION WHEN OTHERS THEN
    v_attributed := 0;
  END;

  v_burn := GREATEST(COALESCE(OLD.diamonds, 0), COALESCE(v_attributed, 0));

  IF v_burn > 0 THEN
    BEGIN
      INSERT INTO public.ca_mint_ledger
        (op_id, action, asset, holder_type, holder_id, holder_label, amount,
         balance_before, balance_after, supply_after, reason, performed_by)
      VALUES
        ('deletion:' || OLD.id::text, 'burn', 'diamonds', 'player', OLD.id, OLD.username,
         v_burn, COALESCE(OLD.diamonds, 0), 0,
         COALESCE(public.fn_ca_mint_supply('diamonds'), 0) - v_burn,
         'profile deleted (retirement recorded by trigger, docs/DIAMOND-ACCOUNTING-STANDARD.md DR5): '
           || 'balance ' || COALESCE(OLD.diamonds, 0)::text
           || ', registered attribution ' || COALESCE(v_attributed, 0)::text
           || ', retired ' || v_burn::text,
         NULL)
      ON CONFLICT (op_id) DO NOTHING;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'ca_mint_ledger could not record the retirement burn of % (% diamonds): %',
        OLD.id, v_burn, SQLERRM;
    END;
  END IF;

  IF COALESCE(OLD.diamonds, 0) > 0 THEN
    BEGIN
      PERFORM public.fn_ca_diamond_incident(
        'DR5:deleted_with_balance',
        CASE WHEN COALESCE(v_reason, '') LIKE 'certification-cleanup:%'
               OR public.fn_ca_is_fixture_account(OLD.id) THEN 'info' ELSE 'warning' END,
        OLD.id, OLD.diamonds, 'profiles DELETE',
        jsonb_build_object('is_horse', OLD.is_horse, 'username', OLD.username,
                           'journal_rows_archived', v_archived,
                           'registered_attribution', v_attributed,
                           'retired', v_burn,
                           'ledger_maintenance', v_reason));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION public.fn_ca_journal_profile_deletion() OWNER TO postgres;

--
-- Name: fn_ca_kill_switch_trip(text, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_kill_switch_trip(p_detector text, p_amount numeric, p_detail text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  pol public.ca_kill_switch_policy%ROWTYPE;
  v_inc uuid;
  v_hour text := to_char(now(), 'YYYY-MM-DD-HH24');
  v_prev numeric;
  v_prev_at timestamptz;
  v_corr text;
  v_redef text;
  v_explained text;
  v_persists boolean := false;
  v_head text;
BEGIN
  SELECT * INTO pol FROM public.ca_kill_switch_policy WHERE detector = p_detector;
  IF NOT FOUND OR NOT pol.armed OR p_amount IS NULL OR abs(p_amount) < pol.threshold_chips THEN
    RETURN false;
  END IF;

  /* THE SWITCH ESCALATES; A PERSON FREEZES (ruling 2026-09-05, on the
     evidence in this migration's header). This function must never write
     ca_payout_freeze: tests/law/PayoutFreezeIsHumanOnly.law.test.ts pins that
     the only insert into that table is inside the human opener. */

  -- The second opinion, taken now rather than an hour from now.
  IF p_detector = 'fn_ca_supply_snapshot' THEN
    SELECT s.unexplained, s.taken_at INTO v_prev, v_prev_at
      FROM public.ca_supply_snapshots s
     WHERE s.unexplained IS NOT NULL
     ORDER BY s.taken_at DESC OFFSET 1 LIMIT 1;
    v_persists := v_prev IS NOT NULL AND abs(v_prev) > pol.threshold_chips / 4 AND sign(v_prev) = sign(p_amount);
  END IF;

  SELECT string_agg(m.op_id, ', ') INTO v_corr
    FROM public.ca_mint_ledger m
   WHERE m.op_id LIKE 'register-opening-baseline-correction:%'
     AND m.created_at > COALESCE(v_prev_at, now() - interval '2 hours');

  /* A migration that re-created the meter itself, named exactly. The guard
     watch is the backstop for a change no migration explains: it captures a
     new hash within the hour, so it errs toward "explained" for at most one
     hour after a real redefinition - which is exactly the hour the false
     alarms live in. Neither suppresses the incident; both name it. */
  SELECT string_agg(m.version || ' ' || m.name, ', ') INTO v_redef
    FROM supabase_migrations.schema_migrations m
   WHERE m.version >= to_char(COALESCE(v_prev_at, now() - interval '2 hours') AT TIME ZONE 'UTC', 'YYYYMMDDHH24MISS')
     AND m.statements[1] LIKE '%' || p_detector || '%';
  IF v_redef IS NULL THEN
    SELECT string_agg(DISTINCT 'the guard watch saw ' || h.proname || ' change', ', ') INTO v_redef
      FROM public.ca_guard_def_history h
     WHERE h.captured_at > COALESCE(v_prev_at, now() - interval '2 hours')
       AND h.proname = p_detector;
  END IF;

  v_explained := NULLIF(concat_ws('; ',
    CASE WHEN v_corr IS NOT NULL THEN 'a labelled register correction in the window (' || v_corr || ')' END,
    CASE WHEN v_redef IS NOT NULL THEN 'the meter''s own definition changed in the window (' || v_redef || ')' END), '');

  v_head := CASE
    WHEN v_explained IS NOT NULL THEN 'EXPLAINED: ' || v_explained || '. Read it before you freeze anything: a meter that has just changed definition reads like a leak and is not one.'
    WHEN v_persists THEN 'CONFIRMED: the previous reading agreed in sign (' || round(COALESCE(v_prev, 0), 2) || ' at ' || COALESCE(v_prev_at::text, 'n/a') || ') and nothing in the window explains it. A leak persists; an oscillation flips.'
    ELSE 'UNCONFIRMED: one reading over the threshold, nothing in the window explains it, and the previous reading did not agree. Take the next reading before you freeze.'
  END;

  v_inc := public.fn_ca_raise_drift_incident(
    'fn_ca_kill_switch_trip', 'ledger_imbalance',
    CASE WHEN v_explained IS NOT NULL THEN 'warning' ELSE 'critical' END,
    'kill-switch:' || p_detector || ':' || v_hour,
    round(p_amount, 2), NULL, NULL, 'ledger', 'ca_kill_switch_policy', NULL,
    'fade0000-0000-0000-0000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL,
    format('KILL SWITCH THRESHOLD CROSSED by %s: %s (threshold %s). %s Payouts are NOT frozen: open the freeze yourself with fn_ca_open_payout_freeze if this is real.',
           p_detector, p_detail, pol.threshold_chips, v_head),
    false,
    jsonb_build_object('detector', p_detector, 'amount', round(p_amount, 2), 'threshold', pol.threshold_chips,
                       'freeze', 'human only', 'verdict', split_part(v_head, ':', 1),
                       'previous_reading', v_prev, 'previous_at', v_prev_at,
                       'explained_by', v_explained, 'persists', v_persists));

  IF v_inc IS NOT NULL AND v_explained IS NULL THEN
    PERFORM public.fn_ca_incident_notify(v_inc, 'escalated',
      format('KILL SWITCH: %s read %s. %s', p_detector, round(p_amount, 2), split_part(v_head, '.', 1)), true);
  END IF;

  PERFORM public.fn_raise_server_financial_alert(
    CASE WHEN v_explained IS NOT NULL THEN 'warning' ELSE 'critical' END, 'ca_kill_switch',
    format('KILL SWITCH THRESHOLD CROSSED by %s: %s. %s', p_detector, p_detail, v_head),
    jsonb_build_object('detector', p_detector, 'amount', round(p_amount, 2), 'threshold', pol.threshold_chips,
                       'verdict', split_part(v_head, ':', 1), 'explained_by', v_explained),
    'kill-switch:' || p_detector || ':' || v_hour);
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  BEGIN
    PERFORM public.fn_raise_server_financial_alert('critical', 'ca_kill_switch',
      format('KILL SWITCH by %s could not complete its paging: %s', p_detector, SQLERRM),
      jsonb_build_object('detector', p_detector), 'kill-switch-error:' || v_hour);
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN true;
END;
$$;


ALTER FUNCTION public.fn_ca_kill_switch_trip(p_detector text, p_amount numeric, p_detail text) OWNER TO postgres;

--
-- Name: fn_ca_largest_remainder_cents(numeric, numeric[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_largest_remainder_cents(p_total_cents numeric, p_weights numeric[]) RETURNS numeric[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  WITH w AS (
    SELECT ord, GREATEST(COALESCE(weight, 0), 0) AS weight
      FROM unnest(p_weights) WITH ORDINALITY AS t(weight, ord)
  ), tot AS (
    SELECT NULLIF(sum(weight), 0) AS s FROM w
  ), base AS (
    SELECT w.ord,
           floor(p_total_cents * w.weight / tot.s)                                  AS c,
           (p_total_cents * w.weight / tot.s)
             - floor(p_total_cents * w.weight / tot.s)                              AS frac
      FROM w CROSS JOIN tot
     WHERE tot.s IS NOT NULL
  ), leftover AS (
    SELECT GREATEST(p_total_cents - COALESCE(sum(c), 0), 0) AS n FROM base
  ), ranked AS (
    SELECT ord, c, row_number() OVER (ORDER BY frac DESC, ord ASC) AS rk FROM base
  )
  SELECT COALESCE(
           array_agg(c + CASE WHEN rk <= (SELECT n FROM leftover) THEN 1 ELSE 0 END
                     ORDER BY ord),
           ARRAY[]::numeric[])
    FROM ranked;
$$;


ALTER FUNCTION public.fn_ca_largest_remainder_cents(p_total_cents numeric, p_weights numeric[]) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_largest_remainder_cents(p_total_cents numeric, p_weights numeric[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_largest_remainder_cents(p_total_cents numeric, p_weights numeric[]) IS 'Split p_total_cents across p_weights by largest remainder. Sum is exact. Ties favour the earlier position, which callers pass in finishing order.';


--
-- Name: fn_ca_ledger_day_manifest(date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_day_manifest(p_day date DEFAULT (CURRENT_DATE - 1), p_restate_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE v_count bigint; v_net numeric; v_first bigint; v_last bigint; v_sha text; v_prior text; v_prior_rows bigint;
BEGIN
  /* One index range over idx_chip_ledger_created_at: the cost is this day's
     legs, not the journal's. A day is a UTC day (SET timezone above). */
  SELECT count(*), COALESCE(sum(amount), 0), min(chain_seq), max(chain_seq),
         encode(extensions.digest(
           COALESCE(string_agg(
             id::text || '|' || amount::text || '|' || from_type || ':' || COALESCE(from_entity_id::text,'') ||
             '>' || to_type || ':' || COALESCE(to_entity_id::text,'') || '|' || category || '|' ||
             extract(epoch from created_at)::text || '|' || COALESCE(row_hash,''),
             E'\n' ORDER BY created_at, id), ''), 'sha256'), 'hex')
    INTO v_count, v_net, v_first, v_last, v_sha
    FROM public.chip_ledger
   WHERE created_at >= p_day AND created_at < p_day + 1;

  SELECT sha256, row_count INTO v_prior, v_prior_rows
    FROM public.ca_ledger_day_manifests WHERE day = p_day;

  IF v_prior IS NULL THEN
    IF v_count = 0 THEN
      /* Nothing to attest and nothing attested: not a manifest, not an error. */
      RETURN jsonb_build_object('day', p_day, 'rows', 0, 'attested', false, 'tampered', false);
    END IF;
    INSERT INTO public.ca_ledger_day_manifests
      (day, row_count, first_seq, last_seq, net_amount, sha256, last_checked_at)
    VALUES (p_day, v_count, v_first, v_last, v_net, v_sha, now())
    ON CONFLICT (day) DO NOTHING;
    RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
      'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false, 'restated', false);
  END IF;

  IF v_prior = v_sha THEN
    /* Read and agreed: that is a verification, so say when it happened. */
    UPDATE public.ca_ledger_day_manifests SET last_checked_at = now() WHERE day = p_day;
    RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
      'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false, 'restated', false);
  END IF;

  /* The stored attestation and the journal disagree. */
  IF p_restate_reason IS NULL THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_ledger_day_manifest', 'unauthorized_adjustment', 'critical',
      'manifest-mismatch:' || p_day::text,
      0, NULL, NULL, 'ledger', 'ca_ledger_day_manifests',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'the recomputed ledger manifest for ' || p_day || ' no longer matches the stored one - historical rows changed',
      false, jsonb_build_object('day', p_day, 'stored', v_prior, 'recomputed', v_sha,
                                'stored_rows', v_prior_rows, 'actual_rows', v_count));
    RETURN jsonb_build_object('day', p_day, 'tampered', true, 'stored', v_prior, 'recomputed', v_sha,
                              'stored_rows', v_prior_rows, 'actual_rows', v_count);
  END IF;

  IF v_count = 0 THEN
    /* A day that was attested cannot become a day that never happened. The
       statement that would empty it is refused whole. */
    RAISE EXCEPTION
      'refusing to restate % to zero rows (it attested % rows): an attested day cannot be emptied. Reason offered: %',
      p_day, v_prior_rows, p_restate_reason
      USING ERRCODE = 'P0403';
  END IF;

  /* Open the guard for exactly this update, in this transaction only. The
     guard writes the restatement row itself, old value kept. */
  PERFORM set_config('app.manifest_restatement', p_restate_reason, true);
  UPDATE public.ca_ledger_day_manifests
     SET row_count = v_count, first_seq = v_first, last_seq = v_last,
         net_amount = v_net, sha256 = v_sha, last_checked_at = now()
   WHERE day = p_day;
  PERFORM set_config('app.manifest_restatement', '', true);

  RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
    'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false,
    'restated', true, 'old_sha256', v_prior, 'old_rows', v_prior_rows, 'reason', p_restate_reason);
END $$;


ALTER FUNCTION public.fn_ca_ledger_day_manifest(p_day date, p_restate_reason text) OWNER TO postgres;

--
-- Name: fn_ca_ledger_day_manifest_backfill(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_day_manifest_backfill(p_since date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  r      record;
  v_done int   := 0;
  v_days jsonb := '[]'::jsonb;
  v_res  jsonb;
BEGIN
  FOR r IN
    SELECT d.day
      FROM public.fn_ca_ledger_finished_days() d(day)
     WHERE (p_since IS NULL OR d.day >= p_since)
       AND NOT EXISTS (SELECT 1 FROM public.ca_ledger_day_manifests m WHERE m.day = d.day)
     ORDER BY d.day
  LOOP
    v_res  := public.fn_ca_ledger_day_manifest(r.day);
    v_done := v_done + 1;
    v_days := v_days || jsonb_build_object('day', r.day, 'rows', v_res->'rows');
  END LOOP;

  RETURN jsonb_build_object('attested', v_done, 'days', v_days,
                            'since', COALESCE(p_since::text, 'the whole journal'));
END $$;


ALTER FUNCTION public.fn_ca_ledger_day_manifest_backfill(p_since date) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_ledger_day_manifest_backfill(p_since date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_ledger_day_manifest_backfill(p_since date) IS 'Attests every finished day the journal has that carries no manifest, by calling fn_ca_ledger_day_manifest for each. Exists because that writer only ever examines CURRENT_DATE - 1, so 27 days of real money movement (2026-03-19..2026-08-29) were outside every guard until 2026-09-07. Composes no manifest of its own: there are exactly two places that know how to hash a day, and this is not one of them.';


--
-- Name: fn_ca_ledger_day_manifest_verify_all(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_day_manifest_verify_all(p_budget_ms integer DEFAULT 60000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  r            record;
  v_checked    int   := 0;
  v_drifted    int   := 0;
  v_unattested int   := 0;
  v_deferred   int   := 0;
  v_days       jsonb := '[]'::jsonb;
  v_missing    jsonb := '[]'::jsonb;
  v_t0         timestamptz := clock_timestamp();
  v_sha        text;
  v_count      bigint;
  v_oldest_age numeric;
  v_never      int;
BEGIN
  /* COVERAGE, every run. Which finished days have legs, and which of those
     carry no manifest. Loose index scan: proportional to days, not legs. */
  FOR r IN
    SELECT d.day
      FROM public.fn_ca_ledger_finished_days() d(day)
     WHERE NOT EXISTS (SELECT 1 FROM public.ca_ledger_day_manifests m WHERE m.day = d.day)
     ORDER BY d.day
  LOOP
    v_unattested := v_unattested + 1;
    v_missing := v_missing || jsonb_build_object('day', r.day);
  END LOOP;

  /* THE ROTATION. Least recently re-read first (never re-read first of all),
     until the budget is spent. Every manifest is a candidate, including one
     whose day has lost every row - that recomputes to the empty digest and is
     reported as drift with rows_present=false, the same failure #3463 named. */
  FOR r IN
    SELECT m.day, m.row_count AS stored_rows, m.sha256 AS stored_sha
      FROM public.ca_ledger_day_manifests m
     ORDER BY m.last_checked_at ASC NULLS FIRST, m.day ASC
  LOOP
    IF extract(epoch from (clock_timestamp() - v_t0)) * 1000 > p_budget_ms THEN
      v_deferred := v_deferred + 1;
      CONTINUE;
    END IF;

    /* The same expression fn_ca_ledger_day_manifest uses. If that one changes,
       this must change with it, or the pair will disagree about a journal
       neither has touched. */
    SELECT count(*),
           encode(extensions.digest(
             COALESCE(string_agg(
               id::text || '|' || amount::text || '|' || from_type || ':' || COALESCE(from_entity_id::text,'') ||
               '>' || to_type || ':' || COALESCE(to_entity_id::text,'') || '|' || category || '|' ||
               extract(epoch from created_at)::text || '|' || COALESCE(row_hash,''),
               E'\n' ORDER BY created_at, id), ''), 'sha256'), 'hex')
      INTO v_count, v_sha
      FROM public.chip_ledger
     WHERE created_at >= r.day AND created_at < r.day + 1;

    v_checked := v_checked + 1;
    UPDATE public.ca_ledger_day_manifests SET last_checked_at = now() WHERE day = r.day;

    IF v_sha IS DISTINCT FROM r.stored_sha THEN
      v_drifted := v_drifted + 1;
      v_days := v_days || jsonb_build_object(
        'day', r.day, 'stored_rows', r.stored_rows, 'actual_rows', v_count,
        'stored_sha', r.stored_sha, 'recomputed_sha', v_sha,
        'rows_present', v_count > 0);

      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_ledger_day_manifest_verify_all', 'unauthorized_adjustment', 'critical',
        'manifest-mismatch:' || r.day::text,
        0, NULL, NULL, 'ledger', 'ca_ledger_day_manifests',
        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
        'the ledger manifest for ' || r.day || ' no longer matches the journal: '
          || r.stored_rows || ' rows attested, ' || v_count || ' present. Sanctioned maintenance '
          || 'restates a manifest in its own transaction (zz_ca_attested_day_is_restated), so a mismatch '
          || 'here means the day changed some other way. Read ca_ledger_mutation_log for it first.',
        false,
        jsonb_build_object('day', r.day, 'stored_rows', r.stored_rows, 'actual_rows', v_count,
                           'stored', r.stored_sha, 'recomputed', v_sha));
    END IF;
  END LOOP;

  IF v_unattested > 0 THEN
    /* Not folded into `drifted`. They are different facts and a reader has to
       be able to tell them apart: drifted means a day changed, unattested
       means a day was never looked at. */
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_ledger_day_manifest_verify_all', 'unauthorized_adjustment', 'critical',
      'manifest-unattested-days',
      0, NULL, NULL, 'ledger', 'ca_ledger_day_manifests',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      v_unattested || ' day(s) of chip_ledger carry no manifest at all, so nothing is '
        || 'verifying them. fn_ca_ledger_day_manifest_backfill() attests every finished day '
        || 'the journal has, and the daily job calls it, so seeing this means that call did not '
        || 'run or could not write.',
      false, jsonb_build_object('unattested', v_unattested, 'days', v_missing));
  END IF;

  /* HOW WIDE THE MESH IS. The oldest re-read, in days, over every manifest -
     a manifest never re-read counts from the moment it was written. */
  SELECT max(extract(epoch from (now() - COALESCE(m.last_checked_at, m.created_at))) / 86400.0),
         count(*) FILTER (WHERE m.last_checked_at IS NULL)
    INTO v_oldest_age, v_never
    FROM public.ca_ledger_day_manifests m;

  IF COALESCE(v_oldest_age, 0) > 30 THEN
    /* Measured basis, 2026-09-07: the whole journal (35 days, 2.18M legs)
       re-reads inside the 60 s budget in about two nights. Thirty days is
       fifteen-fold headroom. When this fires the rotation can no longer cover
       the journal in a month, and the decision - a bigger budget or a longer
       rotation - is Dan's, made on this number. Warning, not critical: nothing
       has drifted, something has merely not been re-read lately. */
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_ledger_day_manifest_verify_all', 'unauthorized_adjustment', 'warning',
      'manifest-rotation-stale',
      0, NULL, NULL, 'ledger', 'ca_ledger_day_manifests',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'the oldest ledger-day manifest was last re-read ' || round(v_oldest_age, 1)
        || ' days ago: the nightly budget of ' || p_budget_ms || ' ms no longer re-reads the whole '
        || 'journal inside 30 days. Raise the budget (cron.job ca-ledger-day-manifest) or accept a '
        || 'longer rotation; either is a decision, not a repair.',
      true, jsonb_build_object('oldest_check_age_days', round(v_oldest_age, 2),
                               'never_checked', v_never, 'budget_ms', p_budget_ms));
  END IF;

  RETURN jsonb_build_object(
    'checked', v_checked, 'drifted', v_drifted, 'days', v_days,
    /* The coverage travels WITH the answer. "0 drifted" on its own was the
       defect #3463 was written for; "checked N" on its own is the one this
       migration was written for. */
    'unattested', v_unattested, 'unattested_days', v_missing,
    'deferred', v_deferred,
    'oldest_check_age_days', round(COALESCE(v_oldest_age, 0), 2),
    'never_checked', v_never,
    'budget_ms', p_budget_ms,
    'ms', round(extract(epoch from (clock_timestamp() - v_t0)) * 1000));
END $$;


ALTER FUNCTION public.fn_ca_ledger_day_manifest_verify_all(p_budget_ms integer) OWNER TO postgres;

--
-- Name: fn_ca_ledger_finished_days(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_finished_days() RETURNS SETOF date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
  WITH RECURSIVE d AS (
    SELECT (SELECT min(created_at) FROM public.chip_ledger)::date AS day
    UNION ALL
    SELECT (SELECT min(created_at) FROM public.chip_ledger
             WHERE created_at >= (d.day + 1)::timestamptz)::date
      FROM d WHERE d.day IS NOT NULL
  )
  SELECT day FROM d WHERE day IS NOT NULL AND day < CURRENT_DATE ORDER BY day
$$;


ALTER FUNCTION public.fn_ca_ledger_finished_days() OWNER TO postgres;

--
-- Name: fn_ca_ledger_replay(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_replay(p_limit integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  r record; v_at timestamptz;
  v_checked int := 0; v_baselines int := 0; v_bad int := 0; v_unkeyable bigint := 0;
  v_this numeric; v_two numeric; v_cum numeric;
  v_worst numeric := 0; v_worst_key text; v_sample jsonb := '[]'::jsonb;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'fn_ca_ledger_replay is service only' USING ERRCODE = '42501';
  END IF;

  /* ONE SCAN PER INSTANT, NOT ONE PER ACCOUNT. Every account read in a run
     shares this run's end instant, and in the ordinary case they share the
     previous run's instant too, so the journal is read once per distinct
     previous reading (one, most nights) rather than once per wallet. The
     first shape of this function called the reader inside the loop: 200
     accounts meant 200 scans of a day of journal, and it did not finish. */
  /* Two runs in one transaction (the probe, and the assertion below) must not
     collide on the scratch names. */
  DROP TABLE IF EXISTS zz_replay_window;
  DROP TABLE IF EXISTS zz_replay_touched;
  DROP TABLE IF EXISTS zz_replay_prev;
  DROP TABLE IF EXISTS zz_replay_net;

  /* One read of the window for both answers: what moved, and what could not
     be keyed. The journal is the biggest table on the platform; it is scanned
     once here and once per distinct previous reading below, and nowhere else. */
  CREATE TEMP TABLE zz_replay_window ON COMMIT DROP AS
    SELECT a.* FROM public.fn_ca_leg_accounts(v_now - interval '26 hours', v_now) a;

  SELECT COALESCE(sum(w.unkeyable), 0) INTO v_unkeyable FROM zz_replay_window w WHERE w.account_type = 'unkeyable';

  CREATE TEMP TABLE zz_replay_touched ON COMMIT DROP AS
    SELECT w.* FROM zz_replay_window w
     WHERE w.account_type <> 'unkeyable'
     ORDER BY abs(w.net) DESC
     LIMIT GREATEST(COALESCE(p_limit, 5000), 1);

  CREATE TEMP TABLE zz_replay_prev ON COMMIT DROP AS
    SELECT t.account_key, s.balance AS prev_balance, s.taken_at AS prev_at, s.unexplained AS prev_unexplained, s.cum_unexplained AS prev_cum
      FROM zz_replay_touched t
      LEFT JOIN LATERAL (
        SELECT x.balance, x.taken_at, x.unexplained, x.cum_unexplained FROM public.ca_account_snapshots x
         WHERE x.account_key = t.account_key ORDER BY x.taken_at DESC LIMIT 1
      ) s ON true;

  CREATE TEMP TABLE zz_replay_net (account_key text, prev_at timestamptz, net numeric) ON COMMIT DROP;
  FOR v_at IN SELECT DISTINCT prev_at FROM zz_replay_prev WHERE prev_at IS NOT NULL LOOP
    INSERT INTO zz_replay_net (account_key, prev_at, net)
    SELECT a.account_key, v_at, a.net FROM public.fn_ca_leg_accounts(v_at, v_now) a WHERE a.account_key IS NOT NULL;
  END LOOP;

  FOR r IN
    SELECT t.*, p.prev_balance, p.prev_at, p.prev_unexplained, p.prev_cum,
           COALESCE((SELECT n.net FROM zz_replay_net n WHERE n.account_key = t.account_key AND n.prev_at = p.prev_at), 0) AS expected,
           public.fn_ca_account_balance(t.account_type, t.entity_id, t.club_id, t.column_name) AS now_bal
      FROM zz_replay_touched t JOIN zz_replay_prev p ON p.account_key = t.account_key
  LOOP
    IF r.now_bal IS NULL THEN CONTINUE; END IF;

    IF r.prev_at IS NULL THEN
      INSERT INTO public.ca_account_snapshots (account_key, account_type, entity_id, club_id, column_name, balance, taken_at, is_baseline, note)
      VALUES (r.account_key, r.account_type, r.entity_id, r.club_id, r.column_name, r.now_bal, v_now, true,
              'baseline: first reading of this account, not judged');
      v_baselines := v_baselines + 1;
      CONTINUE;
    END IF;

    v_checked := v_checked + 1;
    v_this := round((r.now_bal - r.prev_balance) - r.expected, 2);

    /* TWO INTERVALS, ONE FINDING. A leg that commits between the balance read
       and the window's end lands in one interval and reverses in the next, so
       a single interval's residue is noise and the two-interval sum is the
       finding - the same rule the BBJ meter uses, and for the same reason.
       Measured while building this: two passes microseconds apart reported
       three player wallets as 3.00 unexplained; every one was a buy-in that
       committed between the two reads, and every one cancelled next pass. */
    /* A RESIDUE THAT ALREADY CANCELLED IS NOT A FINDING (2026-09-06). Summing
       this interval with the previous one double-counts along the chain: a
       +100 at run N cancelled by -100 at run N+1 reappears as -100 at run N+2,
       where this interval is 0.00. Four such findings were filed at the Phase
       8 gate, every one reading "0.00 unexplained this interval". What is
       carried instead is the CUMULATIVE residue since the account's baseline,
       which oscillates around zero for a boundary and grows for a leak, and
       a finding needs BOTH a non-zero cumulative AND two consecutive
       intervals moving it the same way - the supply meter's own rule, that a
       leak persists while an oscillation flips. A single interval of 100 or
       more is always shown, whatever its sign. */
    v_cum := round(v_this + COALESCE(r.prev_cum, 0), 2);
    v_two := CASE
               WHEN abs(v_this) >= 100 THEN v_this
               WHEN v_this <> 0 AND COALESCE(r.prev_unexplained, 0) <> 0
                    AND sign(v_this) = sign(r.prev_unexplained) THEN v_cum
               ELSE 0
             END;

    INSERT INTO public.ca_account_snapshots (account_key, account_type, entity_id, club_id, column_name, balance, taken_at, is_baseline, unexplained, cum_unexplained, note)
    VALUES (r.account_key, r.account_type, r.entity_id, r.club_id, r.column_name, r.now_bal, v_now, false, v_this, v_cum,
            format('moved %s, journal %s, unexplained %s this interval (cumulative %s, judged %s) since %s', round(r.now_bal - r.prev_balance, 2), r.expected,
                   v_this, v_cum, v_two, r.prev_at));

    IF abs(v_two) > 0.005 THEN
      v_bad := v_bad + 1;
      IF abs(v_two) > abs(v_worst) THEN v_worst := v_two; v_worst_key := r.account_key; END IF;
      IF v_bad <= 20 THEN
        v_sample := v_sample || jsonb_build_object('account', r.account_key, 'moved', round(r.now_bal - r.prev_balance, 2),
                                                   'journal', r.expected, 'unexplained', v_this, 'cumulative', v_cum,
                                                   'since', r.prev_at);
      END IF;
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_ledger_replay', 'ledger_imbalance',
        CASE WHEN abs(v_two) >= 100 THEN 'critical' ELSE 'warning' END,
        'ledger-replay:' || r.account_key || ':' || to_char(v_now, 'YYYY-MM-DD'),
        v_two, r.expected, round(r.now_bal - r.prev_balance, 2),
        'ledger', r.account_type, r.entity_id, r.club_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
        format('%s moved %s between %s and now while the journal accounts for %s: %s unexplained this interval, %s over the last two. The journal names every chip that entered or left an account; this one disagrees with its own balance.',
               r.column_name, round(r.now_bal - r.prev_balance, 2), r.prev_at, r.expected, v_this, v_cum),
        false,
        jsonb_build_object('account_key', r.account_key, 'column', r.column_name,
                           'moved', round(r.now_bal - r.prev_balance, 2), 'journal', r.expected,
                           'unexplained', v_this, 'cumulative', v_cum, 'judged', v_two, 'previous_at', r.prev_at));
    END IF;
  END LOOP;

  PERFORM public.fn_ca_kill_switch_trip('fn_ca_ledger_replay', v_worst,
    format('one account disagrees with the journal by %s (%s)', round(COALESCE(v_worst, 0), 2), COALESCE(v_worst_key, 'n/a')));

  RETURN jsonb_build_object('checked', v_checked, 'baselines', v_baselines, 'disagree', v_bad,
                            'worst', round(COALESCE(v_worst, 0), 2), 'worst_account', v_worst_key,
                            'unkeyable_legs', v_unkeyable, 'sample', v_sample, 'at', v_now);
END;
$$;


ALTER FUNCTION public.fn_ca_ledger_replay(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_ledger_replay(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_ledger_replay(p_limit integer) IS 'Chip standard Phase 7.1: checks that each account''s change between its own two most recent readings equals the journal''s net over the same interval. CALL IT IN A REPEATABLE READ TRANSACTION (the nightly job does): under READ COMMITTED a leg that commits between the window end and the balance read shows as a residue, which the two-interval rule then cancels on the next run.';


--
-- Name: fn_ca_leg_accounts(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_leg_accounts(p_since timestamp with time zone, p_until timestamp with time zone) RETURNS TABLE(account_key text, account_type text, entity_id uuid, club_id uuid, column_name text, net numeric, legs bigint, unkeyable bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH sides AS (
    /* Each side carries the OTHER side's label, because that is what names
       the column when this side has none. */
    SELECT l.to_type AS t, l.to_entity_id AS id, l.to_label AS lbl, l.from_label AS other_lbl, l.amount AS amt
      FROM public.chip_ledger l
     WHERE l.created_at > p_since AND l.created_at <= p_until AND l.to_entity_id IS NOT NULL
    UNION ALL
    SELECT l.from_type, l.from_entity_id, l.from_label, l.to_label, -l.amount
      FROM public.chip_ledger l
     WHERE l.created_at > p_since AND l.created_at <= p_until AND l.from_entity_id IS NOT NULL
  ), resolved AS (
    SELECT s.*,
      CASE s.t
        WHEN 'player_wallet'  THEN 'club_members.chip_balance'
        WHEN 'table_stack'    THEN 'table_seats.stack'
        WHEN 'club_treasury'  THEN 'clubs.chip_treasury'
        WHEN 'union_bank'     THEN 'union_wallets.chip_balance'
        WHEN 'spin_reserve'   THEN 'spin_bonus_pools.balance'
        WHEN 'union_wallet'   THEN COALESCE(s.lbl,
               /* THE OTHER SIDE NAMES WHAT MOVED: out of a promo bank, into a
                  promo bank. The entity decides which promo column. */
               CASE WHEN s.other_lbl LIKE '%promo%'
                         AND EXISTS (SELECT 1 FROM public.unions u WHERE u.id = s.id)
                    THEN 'union_wallets.promo_wallet' END)
        WHEN 'bbj_pool'       THEN s.lbl
        WHEN 'promo_wallet'   THEN COALESCE(s.lbl,
               CASE WHEN s.other_lbl LIKE '%promo%' AND EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = s.id)
                    THEN 'clubs.promo_balance'
                    WHEN s.other_lbl LIKE '%promo%' AND EXISTS (SELECT 1 FROM public.agents a WHERE a.id = s.id OR a.user_id = s.id)
                    THEN 'agents.promo_wallet_balance'
                    WHEN s.other_lbl LIKE '%promo%' AND EXISTS (SELECT 1 FROM public.unions u WHERE u.id = s.id)
                    THEN 'union_wallets.promo_wallet' END)
        WHEN 'agent_wallet'   THEN COALESCE(s.lbl, 'agents.agent_wallet_balance')
        ELSE NULL
      END AS col,
      CASE WHEN s.t = 'table_stack' THEN '00000000-0000-0000-0000-0000000fe17e'::uuid ELSE s.id END AS owner
      FROM sides s
     WHERE s.t <> 'prize_liability'
  )
  SELECT k.t || ':' || k.owner::text || ':' || k.col AS account_key,
         k.t, k.owner, NULL::uuid, k.col,
         round(sum(k.amt), 2), count(*), 0::bigint
    FROM resolved k
   WHERE k.col IS NOT NULL
   GROUP BY 1, 2, 3, 4, 5
  UNION ALL
  SELECT NULL, 'unkeyable', NULL, NULL, NULL, round(sum(k.amt), 2), count(*), count(*)
    FROM resolved k
   WHERE k.col IS NULL
  HAVING count(*) > 0;
$$;


ALTER FUNCTION public.fn_ca_leg_accounts(p_since timestamp with time zone, p_until timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_ca_lock_tournament_contract_from_entitlement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_lock_tournament_contract_from_entitlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.tournaments t
     SET entry_contract_locked=true
   WHERE t.id=NEW.tournament_id AND NOT t.entry_contract_locked;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_lock_tournament_contract_from_entitlement() OWNER TO postgres;

--
-- Name: fn_ca_lock_tournament_seat_acquisition(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_lock_tournament_seat_acquisition(p_tournament_id uuid, p_table_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id uuid:=p_tournament_id;
  v_table_tournament_id uuid;
  v_status text;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  PERFORM pg_advisory_xact_lock_shared(530090,1);

  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok',false,'reason','platform_frozen');
  END IF;

  IF p_user_id IS NOT NULL THEN
    PERFORM public.fn_lock_daily_mission_user(p_user_id);
  END IF;

  IF p_table_id IS NOT NULL THEN
    SELECT tb.tournament_id INTO v_table_tournament_id
      FROM public.tables tb
     WHERE tb.id=p_table_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok',false,'reason','table_not_found');
    END IF;
    IF v_table_tournament_id IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','not_a_tournament_table');
    END IF;
    IF v_tournament_id IS NOT NULL
       AND v_tournament_id IS DISTINCT FROM v_table_tournament_id THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','table_tournament_mismatch');
    END IF;
    v_tournament_id:=v_table_tournament_id;
  END IF;

  IF v_tournament_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_or_table_required');
  END IF;

  -- Launch completion already owns receipt -> tournament. Re-entering these
  -- locks from every seat root makes the historical aa_ launch-proof trigger
  -- a no-op lock acquisition rather than a late inversion.
  PERFORM r.tournament_id
    FROM public.tournament_launch_receipts r
   WHERE r.tournament_id=v_tournament_id
   ORDER BY r.tournament_id
   FOR UPDATE;

  SELECT upper(COALESCE(t.status::text,'')) INTO v_status
    FROM public.tournaments t
   WHERE t.id=v_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  IF v_status NOT IN ('ANNOUNCED','REGISTERING','RUNNING') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_not_seatable','status',v_status);
  END IF;

  RETURN jsonb_build_object(
    'ok',true,'tournament_id',v_tournament_id,
    'table_id',p_table_id,'status',v_status);
END;
$$;


ALTER FUNCTION public.fn_ca_lock_tournament_seat_acquisition(p_tournament_id uuid, p_table_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_lock_tournament_seat_acquisition(p_tournament_id uuid, p_table_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_lock_tournament_seat_acquisition(p_tournament_id uuid, p_table_id uuid, p_user_id uuid) IS 'Owner-only root lock for every tournament seat create/revive path. Global terminal lock, maintenance boundary, Daily Missions player lock, launch receipt and tournament parent are acquired before child rows.';


--
-- Name: fn_ca_manifest_is_restated_not_edited(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_manifest_is_restated_not_edited() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  v_reason text := NULLIF(current_setting('app.manifest_restatement', true), '');
  v_changed boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION
      'DELETE on ca_ledger_day_manifests is forbidden: an attested day stays attested. If its rows legitimately changed, restate it through fn_ca_ledger_day_manifest(day, reason).'
      USING ERRCODE = 'P0403';
  END IF;

  v_changed :=
       NEW.sha256     IS DISTINCT FROM OLD.sha256
    OR NEW.row_count  IS DISTINCT FROM OLD.row_count
    OR NEW.first_seq  IS DISTINCT FROM OLD.first_seq
    OR NEW.last_seq   IS DISTINCT FROM OLD.last_seq
    OR NEW.net_amount IS DISTINCT FROM OLD.net_amount
    OR NEW.day        IS DISTINCT FROM OLD.day;

  IF NOT v_changed THEN
    RETURN NEW;                       -- bookkeeping only (last_checked_at)
  END IF;

  IF NEW.day IS DISTINCT FROM OLD.day THEN
    RAISE EXCEPTION 'a manifest cannot be moved to another day' USING ERRCODE = 'P0403';
  END IF;

  IF v_reason IS NULL THEN
    RAISE EXCEPTION
      'UPDATE of an attested field on ca_ledger_day_manifests (%) is forbidden: a manifest is restated, never edited. Call fn_ca_ledger_day_manifest(day, reason), which keeps the old value.',
      OLD.day
      USING ERRCODE = 'P0403';
  END IF;

  /* The restatement exists by construction. Nobody has to remember. */
  INSERT INTO public.ca_ledger_day_manifest_restatements
    (day, old_row_count, new_row_count, old_sha256, new_sha256, reason, restated_by, application)
  VALUES
    (OLD.day, OLD.row_count, NEW.row_count, OLD.sha256, NEW.sha256, v_reason,
     current_user, current_setting('application_name', true));

  NEW.restated_at := now();
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_manifest_is_restated_not_edited() OWNER TO postgres;

--
-- Name: fn_ca_midway_burnin_gate(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_midway_burnin_gate(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(hours => GREATEST(p_hours, 1));
  c_open_criticals integer; c_new_criticals integer; c_unresolved_unknown integer;
  c_suspense_rows integer; c_suspense_chips numeric;
  c_write_failures integer; c_mint_incidents integer;
  c_failed_settlements integer; c_stuck_settlements integer;
  v_chain record; c_guards_missing integer; c_rpc_drift integer;
  v_supply record; v_checks jsonb; v_pass boolean;
BEGIN
  SELECT count(*) FILTER (WHERE status <> 'resolved' AND severity = 'critical'),
         count(*) FILTER (WHERE severity = 'critical' AND detected_at > v_since),
         count(*) FILTER (WHERE status <> 'resolved' AND classification = 'unknown' AND severity <> 'info')
    INTO c_open_criticals, c_new_criticals, c_unresolved_unknown
    FROM public.ca_drift_incidents;

  SELECT count(*), COALESCE(sum(amount),0) INTO c_suspense_rows, c_suspense_chips
    FROM public.chip_ledger
   WHERE (from_type='settlement_suspense' OR to_type='settlement_suspense')
     AND created_at > GREATEST(v_since, '2026-08-31 19:01:00+00'::timestamptz);

  SELECT count(*) INTO c_write_failures FROM public.ca_ledger_write_failures WHERE occurred_at > v_since;

  SELECT count(*) INTO c_mint_incidents FROM public.ca_drift_incidents
   WHERE dedupe_key LIKE 'tourney-cashout-blocked:%' AND detected_at > v_since AND status <> 'resolved';

  SELECT count(*) FILTER (WHERE state = 'failed'),
         count(*) FILTER (WHERE state NOT IN ('final','failed') AND updated_at < now() - interval '10 minutes')
    INTO c_failed_settlements, c_stuck_settlements
    FROM public.ca_settlements WHERE updated_at > v_since;

  SELECT * INTO v_chain FROM public.fn_ca_verify_ledger_chain(50000);

  SELECT count(*) INTO c_guards_missing FROM (
    SELECT g.id FROM public.ca_guard_inventory g WHERE g.active
    EXCEPT SELECT g2.id FROM public.ca_guard_inventory g2 WHERE g2.active AND (
      (g2.kind='trigger'     AND EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgname=g2.object_a AND NOT t.tgisinternal)) OR
      (g2.kind='cron'        AND EXISTS (SELECT 1 FROM cron.job j WHERE j.jobname=g2.object_a AND j.active)) OR
      (g2.kind='function'    AND EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=g2.object_a)) OR
      (g2.kind NOT IN ('trigger','cron','function'))
    )) miss;

  SELECT count(*) INTO c_rpc_drift FROM public.fn_ca_money_rpc_drift();

  SELECT s.unexplained, s.taken_at INTO v_supply
    FROM public.ca_supply_snapshots s ORDER BY s.taken_at DESC LIMIT 1;

  v_checks := jsonb_build_object(
    'no_open_critical_incidents',        jsonb_build_object('pass', c_open_criticals = 0, 'value', c_open_criticals),
    'no_new_criticals_in_window',        jsonb_build_object('pass', c_new_criticals = 0, 'value', c_new_criticals),
    'no_unresolved_unknowns',            jsonb_build_object('pass', c_unresolved_unknown = 0, 'value', c_unresolved_unknown),
    'zero_suspense_flow',                jsonb_build_object('pass', c_suspense_rows = 0, 'rows', c_suspense_rows, 'chips', round(c_suspense_chips,2)),
    'zero_ledger_write_failures',        jsonb_build_object('pass', c_write_failures = 0, 'value', c_write_failures),
    'zero_blocked_tournament_mints',     jsonb_build_object('pass', c_mint_incidents = 0, 'value', c_mint_incidents),
    'no_failed_or_stuck_settlements',    jsonb_build_object('pass', c_failed_settlements = 0 AND c_stuck_settlements = 0, 'failed', c_failed_settlements, 'stuck', c_stuck_settlements),
    'ledger_chain_clean',                jsonb_build_object('pass', COALESCE(v_chain.breaks,0) = 0, 'checked', COALESCE(v_chain.checked,0), 'breaks', COALESCE(v_chain.breaks,0)),
    'all_structural_guards_present',     jsonb_build_object('pass', c_guards_missing = 0, 'missing', c_guards_missing),
    'no_unregistered_money_rpcs',        jsonb_build_object('pass', c_rpc_drift = 0, 'value', c_rpc_drift),
    'last_supply_snapshot_explained',    jsonb_build_object('pass', abs(COALESCE(v_supply.unexplained, 0)) <= 100, 'unexplained', round(COALESCE(v_supply.unexplained,0),2), 'taken_at', v_supply.taken_at),
    'play_chip_conservation_clean',      (SELECT jsonb_build_object(
         'pass', COALESCE(bool_and(COALESCE((fa.context->>'minted_games')::int,0) = 0
                              AND COALESCE((fa.context->>'destroyed_games')::int,0) = 0), true),
         'alerts_in_window', count(*))
       FROM public.financial_alerts fa
      WHERE fa.source IN ('fn_tournament_chip_conservation_check', 'fn_spin_chip_conservation_check')
        AND fa.created_at > v_since)
  );

  SELECT bool_and((v->'pass')::boolean) INTO v_pass FROM jsonb_each(v_checks) AS e(k, v);

  RETURN jsonb_build_object(
    'gate', CASE WHEN v_pass THEN 'PASS - hardened accounting proven for this window' ELSE 'FAIL - do not restart Midway/Shark/JAQK yet' END,
    'pass', v_pass, 'window_hours', p_hours, 'since', v_since, 'checked_at', now(),
    'checks', v_checks);
END $$;


ALTER FUNCTION public.fn_ca_midway_burnin_gate(p_hours integer) OWNER TO postgres;

--
-- Name: fn_ca_migration_text(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_migration_text(p_version text) RETURNS TABLE(version text, name text, body text, md5 text, byte_len integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT
    m.version,
    m.name,
    array_to_string(m.statements, E';\n'),
    md5(array_to_string(m.statements, E';\n')),
    octet_length(array_to_string(m.statements, E';\n'))
  FROM supabase_migrations.schema_migrations m
  WHERE m.version = p_version;
$$;


ALTER FUNCTION public.fn_ca_migration_text(p_version text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_migration_text(p_version text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_migration_text(p_version text) IS 'The exact statements a migration executed, with an md5, so a committed file can be PROVEN identical to what production ran instead of reconstructed by hand. Read-only, service_role only. See the 428-uncommitted-migrations finding of 2026-08-31.';


--
-- Name: fn_ca_mint(text, text, uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint(p_asset text, p_destination text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text DEFAULT 'admin'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_house constant uuid := '00000000-0000-0000-0000-00000000d1a0';
  v_actor uuid := auth.uid();
  v_admin boolean := false;
  v_asset text := lower(btrim(COALESCE(p_asset, '')));
  v_dest  text := lower(btrim(COALESCE(p_destination, '')));
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_class text := lower(btrim(COALESCE(p_class, 'admin')));
  v_holder uuid;
  v_prior jsonb; v_before numeric; v_after numeric; v_label text;
  v_supply numeric; v_chip_id uuid; v_dia_id uuid; v_actorlb text; v_result jsonb;
  v_pol public.ca_mint_policy%ROWTYPE;
  v_cap numeric; v_roll numeric; v_24h numeric;
BEGIN
  -- The trigger door (2026-09-08, DIAMOND-RULINGS 17 / roadmap 1.3): handle_new_user and the
  -- other seeders fire inside a trigger owned by the database itself, where auth.role() is
  -- NULL. The database's own code may mint; a browser never reaches this branch because a
  -- SECURITY DEFINER trigger runs as the owner and a client session is never at depth > 0.
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND NOT (pg_trigger_depth() > 0
              AND current_user IN ('postgres', 'supabase_admin', 'supabase_auth_admin')) THEN
    SELECT EXISTS (SELECT 1 FROM public.profiles p
                    WHERE p.id = v_actor AND p.role IN ('admin', 'god')) INTO v_admin;
    IF NOT v_admin THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'the_mint_is_admin_only');
    END IF;
  END IF;

  IF v_asset NOT IN ('chips', 'diamonds') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'asset_must_be_chips_or_diamonds');
  END IF;
  IF v_asset = 'chips' AND v_dest NOT IN ('club', 'union') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'chips_are_issued_to_a_club_or_union_wallet_only');
  END IF;
  IF v_asset = 'diamonds' AND v_dest NOT IN ('player', 'house') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamonds_are_issued_to_a_player_or_to_the_house_only');
  END IF;
  -- The foundation's issuance_class list (diamond_transactions_issuance_class_chk).
  -- Recorded on the diamond journal row; carried but unused for chips, which have
  -- their own ledger.
  IF v_class NOT IN ('purchased', 'promotional', 'earned', 'transferred', 'seeded',
                     'refund', 'spend', 'bridge', 'deletion', 'admin', 'arena',
                     'house', 'unknown') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unknown_issuance_class', 'class', v_class);
  END IF;
  IF v_asset = 'diamonds' AND v_dest = 'house' THEN
    IF p_target_id IS NOT NULL AND p_target_id <> c_house THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'the_house_target_is_the_house_sentinel_or_null');
    END IF;
  ELSIF p_target_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'target_required');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive_to_two_decimals');
  END IF;
  IF v_asset = 'diamonds' AND p_amount <> round(p_amount, 0) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamonds_are_whole_numbers');
  END IF;
  -- Kill switch (standard 3.4 layer 6, review D11): a human-opened diamond_issuance freeze
  -- refuses diamond minting until it is cleared. Burns and chips are untouched.
  IF v_asset = 'diamonds' AND EXISTS (SELECT 1 FROM public.ca_payout_freeze f
                                        WHERE f.scope = 'diamond_issuance' AND f.cleared_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'diamond_issuance_frozen');
  END IF;
  -- THE POLICY (ca_mint_policy): a per-operation cap and a rolling 24-hour
  -- ceiling, both refused here with a reason the operator can read, and
  -- refused again at commit by the constraint trigger for chips whatever the
  -- door. 24h issuance is read from the register with the advisory lock held
  -- below, so two operators cannot both fit under the ceiling at once.
  SELECT * INTO v_pol FROM public.ca_mint_policy WHERE id = 1;
  v_cap  := CASE WHEN v_asset = 'chips' THEN v_pol.per_operation_cap_chips ELSE v_pol.per_operation_cap_diamonds END;
  v_roll := CASE WHEN v_asset = 'chips' THEN v_pol.rolling_24h_cap_chips ELSE v_pol.rolling_24h_cap_diamonds END;
  IF p_amount > v_cap THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_over_the_single_mint_cap',
                              'cap', v_cap, 'requested', p_amount);
  END IF;
  IF length(v_reason) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'issuance_needs_a_real_reason');
  END IF;
  IF COALESCE(btrim(p_op_id), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'idempotency_key_required');
  END IF;

  SELECT result INTO v_prior FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_ca_mint';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims WHERE op_id = p_op_id AND fn_name = 'fn_ca_mint';
  END IF;
  INSERT INTO public.ca_op_claims (op_id, fn_name, claimed_by)
  VALUES (p_op_id, 'fn_ca_mint', v_actor);

  PERFORM pg_advisory_xact_lock(hashtext('ca_mint_ledger:' || v_asset));

  v_24h := public.fn_ca_mint_issued_24h(v_asset) + p_amount;
  IF v_24h > v_roll THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'over_the_rolling_24h_issuance_ceiling',
                              'ceiling', v_roll, 'issued_24h', v_24h - p_amount, 'requested', p_amount);
  END IF;

  IF v_asset = 'diamonds' THEN
    IF v_dest = 'house' THEN
      INSERT INTO public.ca_diamond_house (id, balance)
      VALUES (1, 0) ON CONFLICT (id) DO NOTHING;
      SELECT COALESCE(balance, 0) INTO v_before
        FROM public.ca_diamond_house WHERE id = 1 FOR UPDATE;
      UPDATE public.ca_diamond_house
         SET balance = COALESCE(balance, 0) + p_amount, updated_at = now()
       WHERE id = 1 RETURNING balance INTO v_after;
      v_label  := 'the house';
      v_holder := c_house;
      -- No diamond_transactions row: that journal is keyed by a user (two FKs to
      -- auth.users and profiles) and the house is not one. ca_mint_ledger is the
      -- record of a house-side issuance.
    ELSE
      SELECT COALESCE(diamonds, 0), COALESCE(NULLIF(btrim(username), ''), full_name, id::text)
        INTO v_before, v_label FROM public.profiles WHERE id = p_target_id FOR UPDATE;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'player_not_found');
      END IF;
      UPDATE public.profiles SET diamonds = COALESCE(diamonds, 0) + p_amount
       WHERE id = p_target_id RETURNING diamonds INTO v_after;
      -- The op id is the journal reference (DR4: a credit carries its reference), so the earn
      -- ledger files a promotional mint under its engine by prefix (signup: -> signup).
      INSERT INTO public.diamond_transactions
        (user_id, type, transaction_type, amount, balance_after, description, source,
         metadata, counterparty, issuance_class, reference_id)
      VALUES (p_target_id, 'earn', 'mint', p_amount, v_after,
              'The Mint: ' || v_reason, 'the_mint',
              jsonb_build_object('minted_by', v_actor, 'op_id', p_op_id),
              'issuance', v_class, p_op_id)
      RETURNING id INTO v_dia_id;
      v_holder := p_target_id;
    END IF;
  ELSE
    -- The leg is declared WITH A KEY and found by that key: never by shape.
    PERFORM public.fn_ca_declare_ledger('mint', 'issuance_reserve', NULL, NULL, 'mint:' || p_op_id, NULL);
    IF v_dest = 'club' THEN
      SELECT COALESCE(chip_treasury, 0), name INTO v_before, v_label
        FROM public.clubs WHERE id = p_target_id FOR UPDATE;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'club_not_found');
      END IF;
      UPDATE public.clubs SET chip_treasury = COALESCE(chip_treasury, 0) + p_amount
       WHERE id = p_target_id RETURNING chip_treasury INTO v_after;
      INSERT INTO public.chip_transactions
        (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after)
      VALUES (p_target_id, v_actor, NULL, p_amount, 'treasury_mint',
              'The Mint: ' || v_reason, v_after);
    ELSE
      SELECT name INTO v_label FROM public.unions WHERE id = p_target_id;
      IF v_label IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'union_not_found');
      END IF;
      INSERT INTO public.union_wallets (union_id, created_at, updated_at)
      VALUES (p_target_id, now(), now()) ON CONFLICT (union_id) DO NOTHING;
      SELECT COALESCE(chip_balance, 0) INTO v_before
        FROM public.union_wallets WHERE union_id = p_target_id FOR UPDATE;
      UPDATE public.union_wallets
         SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = now()
       WHERE union_id = p_target_id RETURNING chip_balance INTO v_after;
    END IF;
    SELECT id INTO v_chip_id FROM public.chip_ledger WHERE idempotency_key = 'mint:' || p_op_id;
    PERFORM set_config('app.ledger_category', '', true);
    PERFORM set_config('app.ledger_counterparty', '', true);
    PERFORM set_config('app.ledger_counterparty_entity', '', true);
    PERFORM set_config('app.ledger_idempotency_key', '', true);
    IF v_chip_id IS NULL THEN
      RAISE EXCEPTION 'fn_ca_mint: the balance moved but no journal leg was written for key mint:% - refusing to register an issuance the journal does not carry', p_op_id;
    END IF;
    v_holder := p_target_id;
  END IF;

  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) + p_amount
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = v_asset;
  SELECT COALESCE(NULLIF(btrim(username), ''), full_name, id::text)
    INTO v_actorlb FROM public.profiles WHERE id = v_actor;

  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason,
     performed_by, performed_by_label, chip_ledger_id, diamond_tx_id)
  VALUES
    (p_op_id, 'mint', v_asset, v_dest, v_holder, v_label, p_amount,
     v_before, v_after, v_supply, v_reason, v_actor, v_actorlb, v_chip_id, v_dia_id);

  v_result := jsonb_build_object(
    'ok', true, 'replayed', false, 'action', 'mint',
    'asset', v_asset, 'destination', v_dest, 'issuance_class', v_class,
    'target_id', v_holder, 'target_label', v_label, 'amount', p_amount,
    'balance_before', v_before, 'balance_after', v_after, 'supply_after', v_supply,
    'ledger_id', v_chip_id, 'issued_24h_after', v_24h, 'rolling_24h_cap', v_roll,
    'minted_by', v_actor, 'reason', v_reason, 'op_id', p_op_id);

  UPDATE public.ca_op_claims SET result = v_result, finalized_at = now()
   WHERE op_id = p_op_id AND fn_name = 'fn_ca_mint';

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_ca_mint(p_asset text, p_destination text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_mint(p_asset text, p_destination text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_mint(p_asset text, p_destination text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text) IS 'The Mint. Chips are issued to a club treasury or a union bank; diamonds to a player wallet or to ca_diamond_house (DR14, and the Diamond Arena treasury of DIAMOND-ACCOUNTING-STANDARD 3.2). p_class is the issuance class stamped on the diamond journal row beside counterparty = ''issuance'' (DR3). service_role, or a profiles.role of admin / god, only.';


--
-- Name: fn_ca_mint_issued_24h(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint_issued_24h(p_asset text, p_except_leg uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(sum(m.amount), 0)
    FROM public.ca_mint_ledger m
   WHERE m.asset = p_asset AND m.action = 'mint'
     AND m.origin <> 'baseline'
     AND m.created_at > now() - interval '24 hours'
     AND (p_except_leg IS NULL OR m.chip_ledger_id IS DISTINCT FROM p_except_leg);
$$;


ALTER FUNCTION public.fn_ca_mint_issued_24h(p_asset text, p_except_leg uuid) OWNER TO postgres;

--
-- Name: fn_ca_mint_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_rec record; v_pol public.ca_mint_policy%ROWTYPE; v_base timestamptz;
  v_issued_24h numeric; v_retired_24h numeric; v_issued_base numeric; v_retired_base numeric;
  v_drec record; v_dbase timestamptz;
  v_dissued_24h numeric; v_dretired_24h numeric; v_dissued_base numeric; v_dretired_base numeric;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND NOT EXISTS (SELECT 1 FROM public.profiles p
                      WHERE p.id = v_actor AND p.role IN ('admin', 'god')) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'the_mint_is_admin_only');
  END IF;
  SELECT * INTO v_rec FROM public.fn_ca_mint_register_vs_supply();
  SELECT * INTO v_pol FROM public.ca_mint_policy WHERE id = 1;
  SELECT min(created_at) INTO v_base FROM public.ca_mint_ledger WHERE op_id LIKE 'register-opening-baseline:%';
  SELECT COALESCE(sum(amount) FILTER (WHERE action = 'mint' AND created_at > now() - interval '24 hours'), 0),
         COALESCE(sum(amount) FILTER (WHERE action = 'burn' AND created_at > now() - interval '24 hours'), 0),
         COALESCE(sum(amount) FILTER (WHERE action = 'mint' AND created_at > v_base), 0),
         COALESCE(sum(amount) FILTER (WHERE action = 'burn' AND created_at > v_base), 0)
    INTO v_issued_24h, v_retired_24h, v_issued_base, v_retired_base
    FROM public.ca_mint_ledger WHERE asset = 'chips' AND origin <> 'baseline';

  -- Diamonds: the register against the live meter (player balances + house).
  SELECT * INTO v_drec FROM public.fn_ca_diamond_register_vs_supply();
  SELECT min(created_at) INTO v_dbase FROM public.ca_mint_ledger WHERE asset = 'diamonds' AND origin = 'baseline';
  SELECT COALESCE(sum(amount) FILTER (WHERE action = 'mint' AND created_at > now() - interval '24 hours'), 0),
         COALESCE(sum(amount) FILTER (WHERE action = 'burn' AND created_at > now() - interval '24 hours'), 0),
         COALESCE(sum(amount) FILTER (WHERE action = 'mint' AND created_at > v_dbase), 0),
         COALESCE(sum(amount) FILTER (WHERE action = 'burn' AND created_at > v_dbase), 0)
    INTO v_dissued_24h, v_dretired_24h, v_dissued_base, v_dretired_base
    FROM public.ca_mint_ledger WHERE asset = 'diamonds' AND origin <> 'baseline';

  RETURN jsonb_build_object(
    'ok', true,
    'chips_issued',      public.fn_ca_mint_supply('chips'),
    'diamonds_issued',   public.fn_ca_mint_supply('diamonds'),
    'mint_operations',   (SELECT count(*) FROM public.ca_mint_ledger),
    'club_treasuries',   (SELECT COALESCE(SUM(COALESCE(chip_treasury, 0)), 0) FROM public.clubs),
    'union_banks',       (SELECT COALESCE(SUM(COALESCE(chip_balance, 0)), 0) FROM public.union_wallets),
    'member_wallets',    (SELECT COALESCE(SUM(COALESCE(chip_balance, 0)), 0) FROM public.club_members),
    'chips_on_the_felt', (SELECT COALESCE(SUM(COALESCE(stack, 0)), 0) FROM public.table_seats WHERE left_at IS NULL),
    'diamonds_held',     (SELECT COALESCE(SUM(COALESCE(diamonds, 0)), 0) FROM public.profiles),
    'diamond_holders',   (SELECT count(*) FROM public.profiles WHERE COALESCE(diamonds, 0) > 0),
    'reconciliation', jsonb_build_object(
      'register_net',               v_rec.register_net,
      'register_net_at_meter',      v_rec.register_net_at_meter,
      'meter_total',                v_rec.meter_total,
      'meter_taken_at',             v_rec.meter_taken_at,
      'meter_age_seconds',          extract(epoch FROM (now() - v_rec.meter_taken_at))::int,
      'difference',                 v_rec.difference,
      'unexplained_since_baseline', v_rec.unexplained_since_baseline,
      'baseline_at',                v_base,
      'balanced',                   (v_rec.difference = v_rec.unexplained_since_baseline)),
    'issuance', jsonb_build_object(
      'issued_since_baseline',  v_issued_base,
      'retired_since_baseline', v_retired_base,
      'issued_24h',             v_issued_24h,
      'retired_24h',            v_retired_24h),
    'diamonds', jsonb_build_object(
      'register_net',     v_drec.register_net,
      'meter_total',      v_drec.meter_total,
      'player_diamonds',  v_drec.player_diamonds,
      'house_diamonds',   v_drec.house_diamonds,
      'difference',       v_drec.difference,
      'balanced',         (v_drec.difference = 0),
      'baseline_at',      v_dbase,
      'issued_24h',       v_dissued_24h,
      'retired_24h',      v_dretired_24h,
      'issued_since_baseline',  v_dissued_base,
      'retired_since_baseline', v_dretired_base,
      'headroom_24h',     v_pol.rolling_24h_cap_diamonds - public.fn_ca_mint_issued_24h('diamonds'),
      'by_origin_24h', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                          'origin', o.origin, 'action', o.action, 'operations', o.n, 'amount', o.total)
                          ORDER BY o.action, o.total DESC), '[]'::jsonb)
                         FROM (SELECT origin, action, count(*) n, sum(amount) total
                                 FROM public.ca_mint_ledger
                                WHERE asset = 'diamonds' AND created_at > now() - interval '24 hours'
                                GROUP BY 1, 2) o),
      'by_origin', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                      'origin', o.origin, 'action', o.action, 'operations', o.n, 'amount', o.total)
                      ORDER BY o.action, o.total DESC), '[]'::jsonb)
                     FROM (SELECT origin, action, count(*) n, sum(amount) total
                             FROM public.ca_mint_ledger
                            WHERE asset = 'diamonds' AND origin <> 'baseline'
                            GROUP BY 1, 2) o)),
    'policy', jsonb_build_object(
      'per_operation_cap_chips',    v_pol.per_operation_cap_chips,
      'rolling_24h_cap_chips',      v_pol.rolling_24h_cap_chips,
      'per_operation_cap_diamonds', v_pol.per_operation_cap_diamonds,
      'rolling_24h_cap_diamonds',   v_pol.rolling_24h_cap_diamonds,
      'headroom_24h_chips',         v_pol.rolling_24h_cap_chips - v_issued_24h,
      'note',                       v_pol.note,
      'updated_at',                 v_pol.updated_at),
    'by_origin', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                     'origin', o.origin, 'asset', o.asset, 'action', o.action,
                     'operations', o.n, 'amount', o.total) ORDER BY o.asset, o.origin, o.action), '[]'::jsonb)
                    FROM (SELECT origin, asset, action, count(*) n, sum(amount) total
                            FROM public.ca_mint_ledger GROUP BY 1, 2, 3) o)
  );
END;
$$;


ALTER FUNCTION public.fn_ca_mint_overview() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_mint_overview(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_mint_overview() IS 'Supply and circulation figures for The Mint panel. Issued totals come from the Mint journal; circulating totals from the live balances, so a divergence is visible.';


--
-- Name: fn_ca_mint_policy_set(numeric, numeric, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint_policy_set(p_per_operation_cap_chips numeric DEFAULT NULL::numeric, p_rolling_24h_cap_chips numeric DEFAULT NULL::numeric, p_per_operation_cap_diamonds numeric DEFAULT NULL::numeric, p_rolling_24h_cap_diamonds numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_admin boolean := false;
  v_before jsonb; v_after jsonb;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND current_user NOT IN ('postgres', 'supabase_admin') THEN
    SELECT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = v_actor AND p.role IN ('admin', 'god')) INTO v_admin;
    IF NOT v_admin THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'the_mint_is_admin_only');
    END IF;
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'a_policy_change_needs_a_real_reason');
  END IF;
  IF p_per_operation_cap_chips IS NULL AND p_rolling_24h_cap_chips IS NULL
     AND p_per_operation_cap_diamonds IS NULL AND p_rolling_24h_cap_diamonds IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'nothing_to_change');
  END IF;
  SELECT to_jsonb(p) INTO v_before FROM public.ca_mint_policy p WHERE p.id = 1 FOR UPDATE;
  UPDATE public.ca_mint_policy
     SET per_operation_cap_chips    = COALESCE(p_per_operation_cap_chips, per_operation_cap_chips),
         rolling_24h_cap_chips      = COALESCE(p_rolling_24h_cap_chips, rolling_24h_cap_chips),
         per_operation_cap_diamonds = COALESCE(p_per_operation_cap_diamonds, per_operation_cap_diamonds),
         rolling_24h_cap_diamonds   = COALESCE(p_rolling_24h_cap_diamonds, rolling_24h_cap_diamonds),
         note = btrim(p_reason), updated_at = now(), updated_by = v_actor
   WHERE id = 1;
  SELECT to_jsonb(p) INTO v_after FROM public.ca_mint_policy p WHERE p.id = 1;
  INSERT INTO public.ca_mint_policy_changes (changed_by, reason, before, after)
  VALUES (v_actor, btrim(p_reason), v_before, v_after);
  RETURN jsonb_build_object('ok', true, 'before', v_before, 'after', v_after);
END;
$$;


ALTER FUNCTION public.fn_ca_mint_policy_set(p_per_operation_cap_chips numeric, p_rolling_24h_cap_chips numeric, p_per_operation_cap_diamonds numeric, p_rolling_24h_cap_diamonds numeric, p_reason text) OWNER TO postgres;

--
-- Name: fn_ca_mint_register_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint_register_append_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reason text := NULLIF(current_setting('app.ledger_maintenance', true), '');
BEGIN
  -- The one permitted update: linking a row to its journal leg.
  IF TG_OP = 'UPDATE'
     AND OLD.chip_ledger_id IS NULL AND NEW.chip_ledger_id IS NOT NULL
     AND NEW.op_id IS NOT DISTINCT FROM OLD.op_id
     AND NEW.action IS NOT DISTINCT FROM OLD.action
     AND NEW.asset IS NOT DISTINCT FROM OLD.asset
     AND NEW.holder_type IS NOT DISTINCT FROM OLD.holder_type
     AND NEW.holder_id IS NOT DISTINCT FROM OLD.holder_id
     AND NEW.amount IS NOT DISTINCT FROM OLD.amount
     AND NEW.balance_before IS NOT DISTINCT FROM OLD.balance_before
     AND NEW.balance_after IS NOT DISTINCT FROM OLD.balance_after
     AND NEW.supply_after IS NOT DISTINCT FROM OLD.supply_after
     AND NEW.reason IS NOT DISTINCT FROM OLD.reason
     AND NEW.performed_by IS NOT DISTINCT FROM OLD.performed_by
     AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at
     AND NEW.diamond_tx_id IS NOT DISTINCT FROM OLD.diamond_tx_id THEN
    RETURN NEW;
  END IF;

  IF v_reason IS NOT NULL THEN
    INSERT INTO public.ca_ledger_mutation_log
      (source_table, operation, db_role, application, reason, old_row, new_row)
    VALUES (TG_TABLE_NAME, TG_OP, current_user,
            current_setting('application_name', true), v_reason,
            to_jsonb(OLD), CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(NEW) END);
    BEGIN
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_mint_register_append_only', 'unauthorized_adjustment', 'warning',
        'register-bypass:' || TG_OP || ':' || split_part(v_reason, ':', 1),
        0, NULL, NULL, 'ledger', 'ca_mint_ledger',
        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
        'append-only bypass used on the mint register: ' || TG_OP
          || ' permitted because app.ledger_maintenance was set to "' || v_reason
          || '". The rows are preserved whole in ca_ledger_mutation_log. Confirm the maintenance was intended, then resolve.',
        true,
        jsonb_build_object('operation', TG_OP, 'reason', v_reason, 'db_role', current_user,
                           'application', current_setting('application_name', true)));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  RAISE EXCEPTION
    '% on ca_mint_ledger is forbidden: the mint register is append-only. A retirement offsets an issuance; neither is ever edited or removed. Set app.ledger_maintenance with an incident reference for authorized maintenance.',
    TG_OP USING ERRCODE = 'P0403';
END;
$$;


ALTER FUNCTION public.fn_ca_mint_register_append_only() OWNER TO postgres;

--
-- Name: fn_ca_mint_register_vs_supply(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint_register_vs_supply() RETURNS TABLE(register_net numeric, register_net_at_meter numeric, meter_total numeric, meter_taken_at timestamp with time zone, difference numeric, unexplained_since_baseline numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH s AS (SELECT total, taken_at FROM public.ca_supply_snapshots ORDER BY taken_at DESC LIMIT 1),
       r AS (SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) AS net FROM public.ca_mint_ledger WHERE asset = 'chips'),
       ra AS (SELECT COALESCE(SUM(CASE WHEN m.action = 'mint' THEN m.amount ELSE -m.amount END), 0) AS net
                FROM public.ca_mint_ledger m, s WHERE m.asset = 'chips' AND m.created_at <= s.taken_at),
       b AS (SELECT min(created_at) AS at FROM public.ca_mint_ledger WHERE op_id LIKE 'register-opening-baseline:%'),
       u AS (SELECT COALESCE(sum(unexplained), 0) AS drift FROM public.ca_supply_snapshots, b WHERE taken_at > b.at),
       -- A baseline correction re-sizes the register to a meter whose definition
       -- changed; it is neither issuance nor drift, so it is added back here.
       c AS (SELECT COALESCE(SUM(CASE WHEN m.action = 'mint' THEN -m.amount ELSE m.amount END), 0) AS corr
               FROM public.ca_mint_ledger m, s WHERE m.asset = 'chips' AND m.op_id LIKE 'register-opening-baseline-correction:%' AND m.created_at <= s.taken_at)
  SELECT round(r.net, 2), round(ra.net, 2), round(s.total, 2), s.taken_at, round(s.total - ra.net, 2), round(u.drift + c.corr, 2) FROM r, ra, s, u, c;
$$;


ALTER FUNCTION public.fn_ca_mint_register_vs_supply() OWNER TO postgres;

--
-- Name: fn_ca_mint_supply(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint_supply(p_asset text) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
    FROM public.ca_mint_ledger WHERE asset = p_asset;
$$;


ALTER FUNCTION public.fn_ca_mint_supply(p_asset text) OWNER TO postgres;

