COMMENT ON FUNCTION public.fn_ca_mint_supply(p_asset text) IS 'Net authorized supply of an asset: total minted less total burned, from the Mint journal.';


--
-- Name: fn_ca_mint_velocity_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint_velocity_watch() RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_mint numeric; v_burn numeric;
BEGIN
  SELECT COALESCE(sum(amount) FILTER (WHERE from_type IN ('system_mint','issuance_reserve')), 0),
         COALESCE(sum(amount) FILTER (WHERE to_type   IN ('system_burn','chip_retirement')), 0)
    INTO v_mint, v_burn
    FROM public.chip_ledger
   WHERE created_at > now() - interval '10 minutes';

  IF v_mint > 250000 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_mint_velocity_watch', 'ledger_imbalance',
      CASE WHEN v_mint > 1000000 THEN 'critical' ELSE 'warning' END,
      'mint-velocity:' || to_char(now(), 'YYYY-MM-DD-HH24'),
      v_mint, 250000, v_mint, 'ledger', 'chip_ledger',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      round(v_mint, 2) || ' chips minted in 10 minutes - far above the expected trickle; if this is not a deliberate batch (mass club creation, epoch reset), a mint loop is running',
      true, jsonb_build_object('mint_10m', round(v_mint,2), 'burn_10m', round(v_burn,2)));
  END IF;

  IF v_burn > 1000000 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_mint_velocity_watch', 'ledger_imbalance', 'warning',
      'burn-velocity:' || to_char(now(), 'YYYY-MM-DD-HH24'),
      v_burn, 1000000, v_burn, 'ledger', 'chip_ledger',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      round(v_burn, 2) || ' chips burned in 10 minutes - expected only during an epoch reset or a mass cleanup; verify the operation is deliberate',
      true, jsonb_build_object('mint_10m', round(v_mint,2), 'burn_10m', round(v_burn,2)));
  END IF;

  RETURN v_mint;
END $$;


ALTER FUNCTION public.fn_ca_mint_velocity_watch() OWNER TO postgres;

--
-- Name: fn_ca_money_path_log(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_money_path_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_path text;
  v_cat  text;
  v_mode text;
BEGIN
  v_path := COALESCE(current_setting('app.money_path', true), '');
  IF v_path = 'fn_settle_tournament_obligation' THEN
    RETURN NEW;
  END IF;

  v_cat := lower(COALESCE(NEW.category, ''));

  -- The mode is data, so the way back is an UPDATE and not a deploy. A missing
  -- row means log: this guard never becomes stricter by accident.
  SELECT e.mode INTO v_mode FROM public.ca_money_path_enforcement e WHERE e.only_row;
  v_mode := COALESCE(v_mode, 'log');

  IF v_mode = 'refuse' THEN
    -- Nothing survives this raise, so the message carries the evidence: who
    -- wrote, from where, for how much, against which entity.
    RAISE EXCEPTION
      'R3: a % credit of % was written outside fn_settle_tournament_obligation (money_path=%, app=%, role=%, wallet_transactions.related_entity_id=%). Route it through fn_settle_tournament_obligation. To reopen the door: UPDATE public.ca_money_path_enforcement SET mode = ''log'';',
      COALESCE(NULLIF(v_cat, ''), '<none>'), NEW.amount, COALESCE(NULLIF(v_path, ''), '<none>'),
      COALESCE(NULLIF(current_setting('application_name', true), ''), '<none>'),
      session_user::text, NEW.related_entity_id
      USING ERRCODE = 'raise_exception';
  END IF;

  BEGIN
    INSERT INTO public.ca_money_path_violations
      (table_name, user_id, amount, category, description, related_entity_id,
       money_path, app_name, db_role)
    VALUES
      (TG_TABLE_NAME, NEW.user_id, NEW.amount, NEW.category, NEW.description,
       NEW.related_entity_id, NULLIF(v_path, ''),
       NULLIF(current_setting('application_name', true), ''),
       session_user::text);
  EXCEPTION WHEN OTHERS THEN
    -- The logger must never be the reason a credit fails.
    NULL;
  END;

  BEGIN
    -- Global scope (no entity dimension) so it files for every union; the
    -- tournament id travels in metadata only. INFO never pages.
    PERFORM public.fn_ca_raise_drift_incident(
      p_source         => 'r3_money_path_log',
      p_classification => 'unauthorized_adjustment',
      p_severity       => 'info',
      p_dedupe_key     => 'r3:' || v_cat || ':' || to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24'),
      p_discrepancy    => NEW.amount,
      p_layer          => 'settlement',
      p_entity_type    => 'wallet_transactions',
      p_entity_id      => NEW.id,
      p_suspected_cause => 'a tournament-category credit was written outside fn_settle_tournament_obligation (R3, log-only)',
      p_metadata       => jsonb_build_object('category', NEW.category, 'money_path', NULLIF(v_path, ''),
                            'related_entity_id', NEW.related_entity_id,
                            'app_name', NULLIF(current_setting('application_name', true), ''),
                            'session_user', session_user::text));
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_ca_money_path_log() OWNER TO postgres;

--
-- Name: fn_ca_money_rpc_drift(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_money_rpc_drift() RETURNS TABLE(proname text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r RECORD;
  v_cols text[];
  v_col_re text;
BEGIN
  /* The balance columns, read from the triggers that watch them. */
  SELECT array_agg(DISTINCT c) INTO v_cols
    FROM (
      SELECT (regexp_matches(pg_get_triggerdef(t.oid), '''([a-z_]+)=([a-z_]+)''', 'g'))[1] AS c
        FROM pg_trigger t
        JOIN pg_proc p ON p.oid = t.tgfoid
       WHERE NOT t.tgisinternal AND p.proname IN ('fn_ca_autoledger','fn_ca_autoledger_delete')
      UNION
      SELECT unnest(ARRAY['chip_balance','held_chips','locked_chips','credit_used',
                          'stack','balance','chips','prize','bounty_winnings'])
    ) s;

  v_col_re := '\y(' || array_to_string(v_cols, '|') || ')\y';

  FOR r IN
    SELECT DISTINCT p.proname AS pn
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.prokind = 'f'
      AND (
        p.prosrc ~* 'UPDATE\s+(public\.)?(club_members|club_wallets|union_wallets|unions|table_seats|bbj_pools|clubs|agents|wallets|spin_bonus_pools|tournament_players)\y'
        OR p.prosrc ~* 'INSERT\s+INTO\s+(public\.)?(club_members|club_wallets|union_wallets|unions|bbj_pools|clubs|agents|wallets|spin_bonus_pools)\y'
      )
      /* ...and it has to actually name a balance column. */
      AND p.prosrc ~* v_col_re
      AND NOT EXISTS (SELECT 1 FROM public.ca_money_rpc_registry g WHERE g.proname = p.proname)
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_money_rpc_drift', 'unauthorized_adjustment', 'warning',
      'rpc-drift:' || r.pn,
      0, NULL, NULL, 'ledger', 'pg_proc', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'NEW unregistered function writes balance columns: ' || r.pn
        || ' - audit it, then register it in ca_money_rpc_registry',
      NULL, jsonb_build_object('proname', r.pn));
    proname := r.pn; RETURN NEXT;
  END LOOP;

  /* Phase 2 lane 2.5 (F9): a door the registry says is CLOSED must stay
     closed. If any client role - or service_role - can execute it again,
     that is drift of the authorization surface, not of a balance. */
  FOR r IN
    SELECT g.proname AS pn
      FROM public.ca_money_rpc_registry g
      JOIN pg_proc p ON p.proname = g.proname
      JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public'
     WHERE g.status = 'closed'
       AND (has_function_privilege('anon', p.oid, 'EXECUTE')
         OR has_function_privilege('authenticated', p.oid, 'EXECUTE')
         OR has_function_privilege('service_role', p.oid, 'EXECUTE'))
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_money_rpc_drift', 'unauthorized_adjustment', 'warning',
      'rpc-closed-door-open:' || r.pn,
      0, NULL, NULL, 'ledger', 'pg_proc', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'CLOSED money door is executable again: ' || r.pn
        || ' - it was revoked from every client role; revoke it again or change its registry status',
      NULL, jsonb_build_object('proname', r.pn));
    proname := r.pn; RETURN NEXT;
  END LOOP;
END $$;


ALTER FUNCTION public.fn_ca_money_rpc_drift() OWNER TO postgres;

--
-- Name: fn_ca_mystery_bounty_completion_evidence(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mystery_bounty_completion_evidence(p_tournament_id uuid, p_winner_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $_$
DECLARE
  v_t record;
  v_inventory_cents bigint;
  v_completed_award_cents bigint;
  v_void_chest_cents bigint;
  v_legacy_award_cents bigint;
  v_legacy_residual_cents bigint;
  v_legacy_residual_amount numeric;
  v_legacy_credit_cents bigint;
  v_obligation_cents bigint;
  v_evidence_mode text;
BEGIN
  IF p_tournament_id IS NULL OR p_winner_user_id IS NULL THEN
    RAISE EXCEPTION 'mystery completion evidence requires tournament and winner ids'
      USING ERRCODE = '22004';
  END IF;

  SELECT t.id,t.is_mystery_bounty,t.mystery_bounty_stage,
         t.mystery_bounty_pool_cents
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF NOT FOUND
     OR COALESCE(v_t.is_mystery_bounty,false) IS NOT TRUE
     OR v_t.mystery_bounty_stage IS DISTINCT FROM 'complete'
     OR COALESCE(v_t.mystery_bounty_pool_cents,0) <= 0 THEN
    RAISE EXCEPTION 'tournament % has no complete funded mystery inventory',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.user_id = p_winner_user_id
  ) THEN
    RAISE EXCEPTION 'mystery completion winner % is not in tournament %',
      p_winner_user_id,p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT COALESCE(sum(c.amount_cents),0),
         COALESCE(sum(c.amount_cents) FILTER (WHERE c.status = 'void'),0)
    INTO v_inventory_cents,v_void_chest_cents
    FROM public.tournament_bounty_chests c
   WHERE c.tournament_id = p_tournament_id;
  SELECT COALESCE(sum(a.amount_cents) FILTER (
           WHERE a.status = 'completed'),0)
    INTO v_completed_award_cents
    FROM public.tournament_bounty_awards a
   WHERE a.tournament_id = p_tournament_id;

  IF v_inventory_cents IS DISTINCT FROM v_t.mystery_bounty_pool_cents
     OR v_completed_award_cents + v_void_chest_cents
          IS DISTINCT FROM v_t.mystery_bounty_pool_cents
     OR EXISTS (
       SELECT 1 FROM public.tournament_bounty_chests c
        WHERE c.tournament_id = p_tournament_id
          AND (c.amount_cents <= 0 OR c.status NOT IN ('paid','void')
            OR (c.status = 'paid' AND (c.award_id IS NULL OR NOT EXISTS (
              SELECT 1 FROM public.tournament_bounty_awards a
               WHERE a.id = c.award_id
                 AND a.tournament_id = p_tournament_id
                 AND a.chest_id = c.id
                 AND a.amount_cents = c.amount_cents
                 AND a.status = 'completed')))
            OR (c.status = 'void' AND c.award_id IS NOT NULL AND NOT EXISTS (
              SELECT 1 FROM public.tournament_bounty_awards a
               WHERE a.id = c.award_id
                 AND a.tournament_id = p_tournament_id
                 AND a.chest_id = c.id
                 AND a.amount_cents = c.amount_cents
                 AND a.status = 'void'))))
     OR EXISTS (
       SELECT 1 FROM public.tournament_bounty_awards a
        JOIN public.tournament_bounty_chests c ON c.id = a.chest_id
       WHERE a.tournament_id = p_tournament_id
         AND (c.tournament_id IS DISTINCT FROM p_tournament_id
           OR c.award_id IS DISTINCT FROM a.id
           OR c.amount_cents IS DISTINCT FROM a.amount_cents
           OR a.status NOT IN ('completed','void')
           OR (a.status = 'completed' AND (
             c.status <> 'paid' OR a.paid_at IS NULL
             OR (SELECT count(*)
                   FROM public.tournament_bounty_award_recipients r
                  WHERE r.award_id = a.id AND r.amount_cents > 0) < 1
             OR (SELECT COALESCE(sum(r.amount_cents),0)
                   FROM public.tournament_bounty_award_recipients r
                  WHERE r.award_id = a.id) <> a.amount_cents
             OR EXISTS (
               SELECT 1 FROM public.tournament_bounty_award_recipients r
                WHERE r.award_id = a.id
                  AND (r.amount_cents <= 0 OR r.paid_at IS NULL))))
           OR (a.status = 'void' AND (
             c.status <> 'void' OR a.paid_at IS NOT NULL OR EXISTS (
               SELECT 1 FROM public.tournament_bounty_award_recipients r
                WHERE r.award_id = a.id AND r.paid_at IS NOT NULL)))))
     OR EXISTS (
       SELECT 1 FROM public.tournament_bounty_chests c
        WHERE c.tournament_id = p_tournament_id
          AND c.status = 'paid'
          AND (SELECT count(*) FROM public.tournament_bounty_awards a
                WHERE a.id = c.award_id AND a.chest_id = c.id
                  AND a.tournament_id = p_tournament_id
                  AND a.status = 'completed') <> 1)
  THEN
    RAISE EXCEPTION 'tournament % has malformed or open mystery inventory',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- Every legacy award key must name one exact completed recipient. A key with
  -- an award prefix but the wrong user or amount is contradictory evidence,
  -- not a reason to classify the recipient as obligation-era.
  IF EXISTS (
    SELECT 1
      FROM public.tournament_bounty_awards a
      JOIN public.wallet_credit_idempotency k
        ON k.key LIKE 'mb:' || a.id::text || ':%'
     WHERE a.tournament_id = p_tournament_id
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_bounty_award_recipients r
          WHERE r.award_id = a.id
            AND k.key = 'mb:' || a.id::text || ':' || r.user_id::text
            AND k.user_id = r.user_id
            AND k.amount IS NOT NULL
            AND k.amount::text NOT IN ('NaN','Infinity','-Infinity')
            AND k.amount = round(r.amount_cents / 100.0,2)))
     OR EXISTS (
       SELECT 1 FROM public.wallet_credit_idempotency k
        WHERE k.key LIKE 'mb-residual:' || p_tournament_id::text || '%'
          AND k.key <> 'mb-residual:' || p_tournament_id::text)
  THEN
    RAISE EXCEPTION 'tournament % has malformed legacy mystery credit keys',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT COALESCE(sum(r.amount_cents),0)
    INTO v_legacy_award_cents
    FROM public.tournament_bounty_awards a
    JOIN public.tournament_bounty_award_recipients r ON r.award_id = a.id
    JOIN public.wallet_credit_idempotency k
      ON k.key = 'mb:' || a.id::text || ':' || r.user_id::text
     AND k.user_id = r.user_id
     AND k.amount = round(r.amount_cents / 100.0,2)
   WHERE a.tournament_id = p_tournament_id
     AND a.status = 'completed' AND r.paid_at IS NOT NULL;

  SELECT k.amount
    INTO v_legacy_residual_amount
    FROM public.wallet_credit_idempotency k
   WHERE k.key = 'mb-residual:' || p_tournament_id::text;
  IF FOUND AND (
       v_legacy_residual_amount IS NULL
       OR v_legacy_residual_amount::text IN ('NaN','Infinity','-Infinity')
       OR v_legacy_residual_amount <= 0
       OR v_legacy_residual_amount <> round(v_legacy_residual_amount,2)
  ) THEN
    RAISE EXCEPTION 'tournament % has a malformed legacy mystery residual',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  v_legacy_residual_cents := CASE
    WHEN v_legacy_residual_amount IS NULL THEN 0
    ELSE round(v_legacy_residual_amount * 100)::bigint END;
  IF v_legacy_residual_cents > 0 AND NOT EXISTS (
    SELECT 1 FROM public.wallet_credit_idempotency k
     WHERE k.key = 'mb-residual:' || p_tournament_id::text
       AND k.user_id = p_winner_user_id
       AND k.amount::text NOT IN ('NaN','Infinity','-Infinity')
       AND k.amount > 0 AND k.amount = round(k.amount,2)
       AND round(k.amount * 100)::bigint = v_void_chest_cents
  ) THEN
    RAISE EXCEPTION 'tournament % legacy mystery residual is not its exact void inventory',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  v_legacy_credit_cents := v_legacy_award_cents + v_legacy_residual_cents;

  -- Obligation credits use one immutable key per cumulative increment. The
  -- suffix is the prior paid cents. Ordered intervals must cover [0,paid)
  -- exactly, which proves no missing, overlapping or invented increment.
  IF EXISTS (
    SELECT 1 FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'mystery_bounty'
       AND (o.place IS NOT NULL OR o.user_id IS NULL
         OR o.amount_owed IS NULL OR o.amount_paid IS NULL
         OR o.amount_owed::text IN ('NaN','Infinity','-Infinity')
         OR o.amount_paid::text IN ('NaN','Infinity','-Infinity')
         OR o.amount_paid <= 0 OR o.amount_paid <> round(o.amount_paid,2)
         OR o.amount_owed IS DISTINCT FROM o.amount_paid
         OR o.settled_at IS NULL))
     OR EXISTS (
       SELECT 1
         FROM public.tournament_obligations o
         JOIN public.wallet_credit_idempotency k
           ON k.key LIKE 'tourney:' || p_tournament_id::text ||
                         ':obl:' || o.id::text || ':%'
        WHERE o.tournament_id = p_tournament_id
          AND o.kind = 'mystery_bounty'
          AND (k.user_id IS DISTINCT FROM o.user_id
            OR k.amount IS NULL
            OR k.amount::text IN ('NaN','Infinity','-Infinity')
            OR k.amount <= 0 OR k.amount <> round(k.amount,2)
            OR split_part(k.key,':',5) !~ '^[0-9]+$'))
     OR EXISTS (
       WITH key_intervals AS (
         SELECT o.id,o.amount_paid,
                CASE WHEN split_part(k.key,':',5) ~ '^[0-9]+$'
                     THEN split_part(k.key,':',5)::bigint END
                  AS starts_at_cents,
                CASE WHEN k.amount IS NOT NULL
                           AND k.amount::text NOT IN
                               ('NaN','Infinity','-Infinity')
                           AND k.amount > 0 AND k.amount = round(k.amount,2)
                     THEN round(k.amount * 100)::bigint END
                  AS paid_cents
           FROM public.tournament_obligations o
           JOIN public.wallet_credit_idempotency k
             ON k.key LIKE 'tourney:' || p_tournament_id::text ||
                           ':obl:' || o.id::text || ':%'
          WHERE o.tournament_id = p_tournament_id
            AND o.kind = 'mystery_bounty'
       ), exact_intervals AS (
         SELECT i.*,
                COALESCE(sum(i.paid_cents) OVER (
                  PARTITION BY i.id ORDER BY i.starts_at_cents
                  ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0)
                  AS expected_start_cents,
                sum(i.paid_cents) OVER (PARTITION BY i.id) AS total_key_cents
           FROM key_intervals i
       )
       SELECT 1
         FROM public.tournament_obligations o
         LEFT JOIN exact_intervals i ON i.id = o.id
        WHERE o.tournament_id = p_tournament_id
          AND o.kind = 'mystery_bounty'
        GROUP BY o.id,o.amount_paid
       HAVING count(i.id) = 0
           OR bool_or(i.starts_at_cents <> i.expected_start_cents)
           OR max(i.total_key_cents) <>
                round(o.amount_paid * 100)::bigint)
  THEN
    RAISE EXCEPTION 'tournament % has incomplete mystery obligation credit keys',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT round(COALESCE(sum(o.amount_paid),0) * 100)::bigint
    INTO v_obligation_cents
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND o.kind = 'mystery_bounty';

  -- Allocate every uncovered paid recipient to that recipient's obligation,
  -- and every uncovered void chest to the champion's obligation. This is an
  -- exact per-user partition, stronger than a pool-only total.
  IF EXISTS (
    WITH uncovered AS (
      SELECT r.user_id,sum(r.amount_cents)::bigint AS cents
        FROM public.tournament_bounty_awards a
        JOIN public.tournament_bounty_award_recipients r ON r.award_id = a.id
        LEFT JOIN public.wallet_credit_idempotency k
          ON k.key = 'mb:' || a.id::text || ':' || r.user_id::text
         AND k.user_id = r.user_id
         AND k.amount = round(r.amount_cents / 100.0,2)
       WHERE a.tournament_id = p_tournament_id
         AND a.status = 'completed' AND r.paid_at IS NOT NULL
         AND k.key IS NULL
       GROUP BY r.user_id
      UNION ALL
      SELECT p_winner_user_id,v_void_chest_cents
       WHERE v_void_chest_cents > 0
         AND v_legacy_residual_cents = 0
    ), expected AS (
      SELECT u.user_id,sum(u.cents)::bigint AS cents
        FROM uncovered u GROUP BY u.user_id
    ), obligated AS (
      SELECT o.user_id,round(sum(o.amount_paid) * 100)::bigint AS cents
        FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'mystery_bounty'
       GROUP BY o.user_id
    )
    SELECT 1 FROM expected e
    FULL JOIN obligated o USING (user_id)
     WHERE COALESCE(e.cents,0) IS DISTINCT FROM COALESCE(o.cents,0)
  ) OR v_legacy_credit_cents + v_obligation_cents
         IS DISTINCT FROM v_t.mystery_bounty_pool_cents THEN
    RAISE EXCEPTION
      'tournament % mystery credit eras do not exactly cover its pool (% legacy + % obligation <> %)',
      p_tournament_id,v_legacy_credit_cents,v_obligation_cents,
      v_t.mystery_bounty_pool_cents USING ERRCODE = 'P0404';
  END IF;

  v_evidence_mode := CASE
    WHEN v_legacy_credit_cents > 0 AND v_obligation_cents > 0 THEN 'mixed'
    WHEN v_legacy_credit_cents > 0 THEN 'legacy_wallet_keys'
    ELSE 'obligations'
  END;
  RETURN jsonb_build_object(
    'evidence_version',1,
    'evidence_mode',v_evidence_mode,
    'pool_cents',v_t.mystery_bounty_pool_cents,
    'inventory_cents',v_inventory_cents,
    'completed_award_cents',v_completed_award_cents,
    'void_chest_cents',v_void_chest_cents,
    'legacy_award_credit_cents',v_legacy_award_cents,
    'legacy_residual_credit_cents',v_legacy_residual_cents,
    'legacy_credit_cents',v_legacy_credit_cents,
    'obligation_cents',v_obligation_cents);
END;
$_$;


ALTER FUNCTION public.fn_ca_mystery_bounty_completion_evidence(p_tournament_id uuid, p_winner_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_mystery_bounty_completion_evidence(p_tournament_id uuid, p_winner_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_mystery_bounty_completion_evidence(p_tournament_id uuid, p_winner_user_id uuid) IS 'Owner-only STABLE proof that a complete mystery inventory is partitioned exactly between legacy mb wallet keys and cumulative obligation credit-key intervals. It never moves or repairs money.';


--
-- Name: fn_ca_negative_balance_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_negative_balance_watch() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_hits int := 0; r record; v_stale int;
BEGIN
  FOR r IN
    SELECT 'club_members' AS store, user_id::text AS who, club_id, chip_balance AS bal
      FROM club_members WHERE chip_balance < 0
    UNION ALL
    SELECT 'clubs', id::text, id, chip_treasury FROM clubs WHERE chip_treasury < 0
    UNION ALL
    SELECT 'union_wallets', union_id::text, NULL,
           LEAST(chip_balance, rake_wallet, bbj_wallet, promo_wallet, insurance_wallet,
                 COALESCE(spin_reserve_wallet,0))
      FROM union_wallets
     WHERE LEAST(chip_balance, rake_wallet, bbj_wallet, promo_wallet, insurance_wallet,
                 COALESCE(spin_reserve_wallet,0)) < 0
    UNION ALL
    SELECT 'agents', user_id::text, club_id,
           LEAST(COALESCE(agent_wallet_balance,0), COALESCE(promo_wallet_balance,0))
      FROM agents
     WHERE COALESCE(agent_wallet_balance,0) < 0 OR COALESCE(promo_wallet_balance,0) < 0
    LIMIT 20
  LOOP
    v_hits := v_hits + 1;
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_negative_balance_watch', 'ledger_imbalance', 'critical',
      'negative-balance:' || r.store || ':' || r.who,
      r.bal, 0, r.bal, 'ledger', r.store, NULL, r.club_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'a balance store went below zero - a debit path is missing its floor check; nothing was blocked, review the store''s recent ledger rows',
      false, jsonb_build_object('store', r.store, 'entity', r.who, 'balance', r.bal));
  END LOOP;

  -- the siren's own power light
  SELECT count(*) INTO v_stale FROM ca_incident_recipients rec
   WHERE rec.active
     AND NOT EXISTS (
       SELECT 1 FROM push_subscriptions s
        WHERE s.user_id = rec.user_id AND s.is_active
          AND COALESCE(s.last_receipt_at, s.created_at) > now() - interval '48 hours');
  IF v_stale > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_negative_balance_watch', 'unknown', 'warning',
      'push-deliverability:' || to_char(now(), 'YYYY-MM-DD'),
      v_stale, NULL, NULL, 'reporting', 'push_subscriptions',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'a registered incident recipient has no push subscription with a delivery receipt in 48h - alerts may not be reaching a phone; check the device''s notification permissions',
      true, jsonb_build_object('recipients_without_fresh_receipts', v_stale));
  END IF;

  RETURN v_hits;
END $$;


ALTER FUNCTION public.fn_ca_negative_balance_watch() OWNER TO postgres;

--
-- Name: fn_ca_noncirculating_chip_stores(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_noncirculating_chip_stores() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT ARRAY['system_mint', 'system_burn', 'issuance_reserve', 'chip_retirement']::text[];
$$;


ALTER FUNCTION public.fn_ca_noncirculating_chip_stores() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_noncirculating_chip_stores(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_noncirculating_chip_stores() IS 'The chip_ledger from_type/to_type values that sit outside circulating supply. Used symmetrically by fn_ca_supply_snapshot: out of one = issuance, into one = retirement.';


--
-- Name: fn_ca_open_payout_freeze(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_open_payout_freeze(p_scope text, p_reason text, p_actor_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_scope text := lower(btrim(COALESCE(p_scope, '')));
  v_uid   uuid := auth.uid();
  v_label text := COALESCE(NULLIF(btrim(p_actor_label), ''),
                           NULLIF(current_setting('application_name', true), ''),
                           session_user::text);
  v_row   public.ca_payout_freeze%ROWTYPE;
BEGIN
  IF NOT public.fn_ca_caller_is_management() THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'not_management');
  END IF;
  IF v_scope NOT IN ('tournament_payouts', 'bbj_payouts', 'diamond_issuance',
                     'diamond_tournament_payouts', 'arena_withdrawals') THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'unknown_scope');
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'reason_too_short');
  END IF;

  SELECT * INTO v_row FROM public.ca_payout_freeze
   WHERE scope = v_scope AND cleared_at IS NULL
   FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', true, 'already_open', true, 'freeze_id', v_row.id,
      'scope', v_row.scope, 'opened_at', v_row.opened_at, 'opened_by', v_row.opened_by,
      'opened_by_label', v_row.opened_by_label, 'reason', v_row.reason);
  END IF;

  INSERT INTO public.ca_payout_freeze (scope, reason, opened_by, opened_by_label)
  VALUES (v_scope, btrim(p_reason), v_uid, v_label)
  RETURNING * INTO v_row;

  PERFORM public.fn_raise_server_financial_alert(
    'warning', 'ca_payout_freeze',
    format('Payouts FROZEN on scope %s by %s: %s', v_scope, v_label, btrim(p_reason)),
    jsonb_build_object('freeze_id', v_row.id, 'scope', v_scope, 'opened_by', v_uid,
                       'opened_by_label', v_label, 'opened_at', v_row.opened_at),
    'freeze:' || v_row.id::text);

  RETURN jsonb_build_object('ok', true, 'already_open', false, 'freeze_id', v_row.id,
    'scope', v_row.scope, 'opened_at', v_row.opened_at, 'opened_by', v_uid,
    'opened_by_label', v_label, 'reason', v_row.reason);
END $$;


ALTER FUNCTION public.fn_ca_open_payout_freeze(p_scope text, p_reason text, p_actor_label text) OWNER TO postgres;

--
-- Name: fn_ca_open_tournament_hand_seat_exit_authority(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_open_tournament_hand_seat_exit_authority(p_tournament_id uuid, p_table_id uuid, p_user_ids uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_token uuid:=gen_random_uuid();
  v_expected integer;
  v_inserted integer;
BEGIN
  v_expected:=COALESCE(cardinality(p_user_ids),0);
  IF p_tournament_id IS NULL OR p_table_id IS NULL OR v_expected=0
     OR array_position(p_user_ids,NULL) IS NOT NULL
     OR (SELECT count(DISTINCT u) FROM unnest(p_user_ids) u)<>v_expected
     OR NOT EXISTS (
       SELECT 1 FROM public.tables tb
        WHERE tb.id=p_table_id AND tb.tournament_id=p_tournament_id) THEN
    RAISE EXCEPTION 'invalid accepted-hand seat-exit authority scope'
      USING ERRCODE='22023';
  END IF;

  INSERT INTO public.tournament_seat_exit_authorizations(
    token,seat_id,tournament_id,user_id,operation)
  SELECT v_token,s.id,p_tournament_id,s.user_id,'hand_settlement'
    FROM public.table_seats s
   WHERE s.table_id=p_table_id
     AND s.left_at IS NULL
     AND s.user_id=ANY(p_user_ids)
   ORDER BY s.id;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  IF v_inserted<>v_expected THEN
    RAISE EXCEPTION
      'accepted-hand seat-exit authority expected % live seat(s), found %',
      v_expected,v_inserted USING ERRCODE='P0404';
  END IF;

  PERFORM set_config('app.tournament_seat_exit_token',v_token::text,true);
  PERFORM set_config('app.tournament_seat_exit_operation','hand_settlement',true);
  RETURN v_token;
END;
$$;


ALTER FUNCTION public.fn_ca_open_tournament_hand_seat_exit_authority(p_tournament_id uuid, p_table_id uuid, p_user_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_ca_open_tournament_seat_exit_authority(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_open_tournament_seat_exit_authority(p_tournament_id uuid, p_operation text, p_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_token uuid:=gen_random_uuid();
BEGIN
  IF p_tournament_id IS NULL
     OR p_operation NOT IN (
       'unregister','cancel','satellite_finish','terminal_finish','move',
       'elimination') THEN
    RAISE EXCEPTION 'invalid tournament seat-exit authority scope'
      USING ERRCODE='22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  PERFORM 1 FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist',p_tournament_id
      USING ERRCODE='P0002';
  END IF;

  -- Deterministic seat order matches hand settlement and terminal close.
  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.left_at IS NULL
     AND (p_user_id IS NULL OR s.user_id=p_user_id)
   ORDER BY s.id
   FOR UPDATE OF s;

  INSERT INTO public.tournament_seat_exit_authorizations(
    token,seat_id,tournament_id,user_id,operation)
  SELECT v_token,s.id,p_tournament_id,s.user_id,p_operation
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.left_at IS NULL
     AND s.user_id IS NOT NULL
     AND (p_user_id IS NULL OR s.user_id=p_user_id)
   ORDER BY s.id;

  PERFORM set_config('app.tournament_seat_exit_token',v_token::text,true);
  PERFORM set_config('app.tournament_seat_exit_operation',p_operation,true);
  RETURN v_token;
END;
$$;


ALTER FUNCTION public.fn_ca_open_tournament_seat_exit_authority(p_tournament_id uuid, p_operation text, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_operator_audit_trail(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_audit_trail(p_target_type text, p_target_id text, p_limit integer, p_offset integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_limit  int := least(greatest(coalesce(p_limit, 50), 1), 500);
  v_offset int := greatest(coalesce(p_offset, 0), 0);
  v_total  bigint := 0;
  v_rows   jsonb := '[]'::jsonb;
begin
  select count(*) into v_total
  from public.admin_audit_log a
  where a.target_type = p_target_type
    and a.target_id = p_target_id;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb)
    into v_rows
  from (
    select a.id, a.admin_user_id, a.actor_role, a.action, a.target_type, a.target_id,
           a.details, a.before_state, a.after_state, a.ip_address, a.user_agent,
           a.request_id, a.created_at
    from public.admin_audit_log a
    where a.target_type = p_target_type
      and a.target_id = p_target_id
    order by a.created_at desc
    limit v_limit offset v_offset
  ) t;

  -- This function files NO audit row. It is a read with no actor in its
  -- signature, so the write it used to attempt passed a null actor and
  -- was refused every time. See the header. The route's write actions
  -- audit with the real actor through operatorAudit.js.

  return jsonb_build_object(
    'rows', v_rows,
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset
  );
end
$$;


ALTER FUNCTION public.fn_ca_operator_audit_trail(p_target_type text, p_target_id text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_ca_operator_decide_approval(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_decide_approval(p_approval_id uuid, p_decision text, p_decided_by uuid, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row        public.ca_operator_approvals%rowtype;
  v_policy     public.ca_operator_policy%rowtype;
  v_permission text;
  v_decision   text;
  v_alone      boolean := false;
  v_self       boolean := false;
  v_withdraw   boolean := false;
  v_holds      boolean := false;
begin
  v_decision := lower(coalesce(p_decision, ''));
  if v_decision in ('approve', 'approved') then
    v_decision := 'approved';
  elsif v_decision in ('reject', 'rejected') then
    v_decision := 'rejected';
  else
    raise exception 'fn_ca_operator_decide_approval: decision must be approve or reject, got %', p_decision;
  end if;

  select * into v_row from public.ca_operator_approvals where id = p_approval_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'approval_not_found', 'reason', 'approval_not_found', 'approval_id', p_approval_id);
  end if;

  if v_row.status <> 'pending' then
    return jsonb_build_object('ok', false, 'error', 'already_decided', 'reason', 'already_decided', 'status', v_row.status, 'approval_id', p_approval_id);
  end if;

  -- An expired request is closed here rather than left to a sweeper, so
  -- the refusal and the state change cannot disagree.
  if v_row.expires_at is not null and v_row.expires_at <= now() then
    update public.ca_operator_approvals set status = 'expired' where id = p_approval_id;
    return jsonb_build_object('ok', false, 'error', 'expired', 'reason', 'expired', 'status', 'expired', 'approval_id', p_approval_id);
  end if;

  v_permission := case v_row.kind
                    when 'cashout' then 'cashier.write'
                    when 'fleet_policy' then 'fleet.write'
                    when 'sanction' then 'moderation.write'
                    else 'money.write'
                  end;

  -- THE PERMISSION CHECK (20260903140000, review finding M-2). It sits
  -- AFTER the not-found, already-decided and expired branches on purpose:
  -- a decision on a dead row should say the row is dead, not hide that
  -- behind an authorisation error the operator cannot act on. A
  -- withdrawal needs it too: the requester held it to raise the row.
  v_holds := coalesce(public.fn_ca_operator_permissions(p_decided_by) -> 'permissions', '[]'::jsonb)
             ? v_permission;

  if not coalesce(v_holds, false) then
    return jsonb_build_object(
      'ok', false,
      'error', 'permission_denied',
      'reason', 'permission_denied',
      'required_permission', v_permission,
      'status', v_row.status,
      'approval_id', p_approval_id
    );
  end if;

  select * into v_policy from public.ca_operator_policy where id limit 1;

  v_self := p_decided_by is not null and v_row.requested_by is not null and p_decided_by = v_row.requested_by;

  -- A WITHDRAWAL IS NOT A SELF APPROVAL (review finding L-12). The four
  -- eyes rule exists so nobody approves their own money move; it has
  -- nothing to say about the requester cancelling one. A reject by the
  -- requester of their own pending row goes through, ends `rejected`
  -- exactly as a second operator's refusal would, and is filed under its
  -- own action name so the trail can tell the two apart.
  v_withdraw := v_self and v_decision = 'rejected';

  if v_self and not v_withdraw then
    v_alone := not public.fn_ca_operator_has_second_approver(v_row.requested_by, v_permission);
    if not (v_alone and coalesce(v_policy.allow_self_approve_when_alone, true)) then
      return jsonb_build_object(
        'ok', false,
        'error', 'self_approval_refused',
        'reason', 'self_approval_refused',
        'status', v_row.status,
        'approval_id', p_approval_id
      );
    end if;
  end if;

  update public.ca_operator_approvals
    set status = v_decision,
        decided_by = p_decided_by,
        decided_at = now(),
        blocked_reason = case when v_self and v_alone then 'no_second_approver' else blocked_reason end,
        result = coalesce(result, '{}'::jsonb)
                 || jsonb_build_object(
                      'decision_note', p_note,
                      'self_approved_alone', v_self and v_alone,
                      'withdrawn', v_withdraw
                    )
  where id = p_approval_id
  returning * into v_row;

  begin
    perform public.fn_log_admin_action(
      p_admin_user_id := p_decided_by,
      p_action        := case when v_withdraw then 'operator.withdraw_approval' else 'operator.decide_approval' end,
      p_target_type   := coalesce(v_row.target_type, 'operator_approval'),
      p_target_id     := coalesce(v_row.target_id, p_approval_id::text),
      p_details       := jsonb_build_object(
                           'approval_id', p_approval_id,
                           'kind', v_row.kind,
                           'decision', v_decision,
                           'note', p_note,
                           'permission', v_permission,
                           'self_approved_alone', v_self and v_alone,
                           'alone_rule_applied', v_self and v_alone,
                           'withdrawn', v_withdraw
                         ),
      p_before_state  := jsonb_build_object('status', 'pending'),
      p_after_state   := jsonb_build_object('status', v_decision, 'decided_by', p_decided_by),
      p_ip_address    := null,
      p_user_agent    := null,
      p_request_id    := v_row.request_id
    );
  exception when others then
    raise notice 'fn_ca_operator_decide_approval audit failed: %', sqlerrm;
  end;

  return jsonb_build_object(
    'ok', true,
    'approval_id', p_approval_id,
    'status', v_decision,
    'self_approved_alone', v_self and v_alone,
    'withdrawn', v_withdraw
  );
end
$$;


ALTER FUNCTION public.fn_ca_operator_decide_approval(p_approval_id uuid, p_decision text, p_decided_by uuid, p_note text) OWNER TO postgres;

--
-- Name: fn_ca_operator_grant(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_grant(p_user_id uuid, p_role_key text, p_granted_by uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_exists      boolean;
  v_has_profile boolean;
  v_is_legacy   boolean;
  v_grant_id    uuid;
  v_already     boolean := false;
begin
  if p_user_id is null then
    raise exception 'fn_ca_operator_grant: p_user_id is required';
  end if;

  -- THE OPERATOR MUST EXIST (review finding L-3). fn_ca_operator_staff is
  -- driven by profiles, so a grant to a uuid with no profiles row was
  -- stored, never shown, and could not be revoked from the console.
  -- SQLSTATE 23503 is a reference to a row that does not exist, which the
  -- route's mapDbError reads as bad input (400) rather than an outage.
  select true into v_has_profile from public.profiles where id = p_user_id limit 1;
  if not coalesce(v_has_profile, false) then
    raise exception 'fn_ca_operator_grant: operator_not_found, no profiles row for %', p_user_id
      using errcode = '23503';
  end if;

  select true, r.is_legacy into v_exists, v_is_legacy
  from public.ca_operator_roles r
  where r.key = p_role_key;
  if not coalesce(v_exists, false) then
    raise exception 'fn_ca_operator_grant: unknown role_key %', p_role_key;
  end if;

  -- THE LEGACY KEYS ARE NOT GRANTS (review finding L-3). god, superadmin
  -- and admin are what profiles.role says; a grant of one produces an
  -- account that counts as an operator with every permission and that the
  -- Staff tab cannot explain. SQLSTATE 23514, a value that breaks a rule.
  if coalesce(v_is_legacy, false) then
    raise exception 'fn_ca_operator_grant: legacy_role_not_grantable, % lives on profiles.role', p_role_key
      using errcode = '23514';
  end if;

  -- Idempotent, and atomically so (20260903140000, review finding M-4):
  -- the conflict is resolved by the partial unique index itself and the
  -- loser of a race re-reads the winner's row.
  insert into public.ca_operator_grants (user_id, role_key, granted_by, reason)
  values (p_user_id, p_role_key, p_granted_by, p_reason)
  on conflict (user_id, role_key) where revoked_at is null do nothing
  returning id into v_grant_id;

  if v_grant_id is null then
    v_already := true;
    select id into v_grant_id
    from public.ca_operator_grants
    where user_id = p_user_id
      and role_key = p_role_key
      and revoked_at is null
    limit 1;
  end if;

  begin
    perform public.fn_log_admin_action(
      p_admin_user_id := p_granted_by,
      p_action        := 'operator.grant_role',
      p_target_type   := 'operator',
      p_target_id     := p_user_id::text,
      p_details       := jsonb_build_object(
                           'grant_id', v_grant_id,
                           'role_key', p_role_key,
                           'reason', p_reason,
                           'already_held', v_already
                         ),
      p_before_state  := null,
      p_after_state   := jsonb_build_object('role_key', p_role_key, 'revoked_at', null),
      p_ip_address    := null,
      p_user_agent    := null,
      p_request_id    := null
    );
  exception when others then
    raise notice 'fn_ca_operator_grant audit failed: %', sqlerrm;
  end;

  return jsonb_build_object(
    'ok', true,
    'grant_id', v_grant_id,
    'user_id', p_user_id,
    'role_key', p_role_key,
    'already', v_already,
    'permissions', (select public.fn_ca_operator_permissions(p_user_id) -> 'permissions')
  );
end
$$;


ALTER FUNCTION public.fn_ca_operator_grant(p_user_id uuid, p_role_key text, p_granted_by uuid, p_reason text) OWNER TO postgres;

--
-- Name: fn_ca_operator_has_second_approver(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_has_second_approver(p_requested_by uuid, p_permission text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_enforce boolean := false;
  v_count   int := 0;
begin
  select coalesce(enforce_named_roles, false) into v_enforce
  from public.ca_operator_policy where id limit 1;

  -- A named grant always makes somebody a nominated approver. A legacy
  -- role holder counts while enforcement is off, which is why the alone
  -- rule never fires in production today: there are three legacy
  -- operators and any two of them are four eyes. Under enforcement a
  -- legacy account is described by its grants when it has any, and keeps
  -- the legacy set when it has none - the exact rule
  -- fn_ca_operator_permissions applies (review finding M-2) - and it
  -- always holds admin.manage, the recovery floor 20260903140000 gave it.
  select count(*) into v_count
  from (
    select g.user_id
    from public.ca_operator_grants g
    join public.ca_operator_role_permissions rp on rp.role_key = g.role_key
    where g.revoked_at is null
      and rp.permission = p_permission
      and (p_requested_by is null or g.user_id <> p_requested_by)
    union
    select p.id
    from public.profiles p
    join public.ca_operator_roles r on r.key = p.role and r.is_legacy
    join public.ca_operator_role_permissions rp on rp.role_key = r.key
    where rp.permission = p_permission
      and (p_requested_by is null or p.id <> p_requested_by)
      and (
        not v_enforce
        or p_permission = 'admin.manage'
        or not exists (
          select 1
          from public.ca_operator_grants g
          where g.user_id = p.id
            and g.revoked_at is null
        )
      )
  ) candidates;

  return v_count > 0;
end
$$;


ALTER FUNCTION public.fn_ca_operator_has_second_approver(p_requested_by uuid, p_permission text) OWNER TO postgres;

--
-- Name: fn_ca_operator_mark_executed(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_mark_executed(p_approval_id uuid, p_result jsonb, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row    public.ca_operator_approvals%rowtype;
  v_status text := coalesce(nullif(lower(p_status), ''), 'executed');
begin
  if v_status not in ('executed', 'failed') then
    raise exception 'fn_ca_operator_mark_executed: status must be executed or failed, got %', p_status;
  end if;

  select * into v_row from public.ca_operator_approvals where id = p_approval_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'approval_not_found', 'reason', 'approval_not_found', 'approval_id', p_approval_id);
  end if;

  if v_row.status = 'executed' then
    return jsonb_build_object('ok', true, 'already', true, 'status', 'executed', 'approval_id', p_approval_id);
  end if;

  if v_row.status not in ('approved', 'auto_approved', 'failed') then
    return jsonb_build_object('ok', false, 'error', 'not_approved', 'reason', 'not_approved', 'status', v_row.status, 'approval_id', p_approval_id);
  end if;

  update public.ca_operator_approvals
    set status = v_status,
        executed_at = case when v_status = 'executed' then now() else executed_at end,
        result = coalesce(result, '{}'::jsonb) || coalesce(p_result, '{}'::jsonb)
  where id = p_approval_id
  returning * into v_row;

  begin
    perform public.fn_log_admin_action(
      p_admin_user_id := coalesce(v_row.decided_by, v_row.requested_by),
      p_action        := 'operator.execute_approval',
      p_target_type   := coalesce(v_row.target_type, 'operator_approval'),
      p_target_id     := coalesce(v_row.target_id, p_approval_id::text),
      p_details       := jsonb_build_object(
                           'approval_id', p_approval_id,
                           'kind', v_row.kind,
                           'status', v_status,
                           'op_id', v_row.op_id
                         ),
      p_before_state  := null,
      p_after_state   := jsonb_build_object('status', v_status, 'executed_at', v_row.executed_at),
      p_ip_address    := null,
      p_user_agent    := null,
      p_request_id    := v_row.request_id
    );
  exception when others then
    raise notice 'fn_ca_operator_mark_executed audit failed: %', sqlerrm;
  end;

  return jsonb_build_object('ok', true, 'already', false, 'status', v_status, 'approval_id', p_approval_id);
end
$$;


ALTER FUNCTION public.fn_ca_operator_mark_executed(p_approval_id uuid, p_result jsonb, p_status text) OWNER TO postgres;

--
-- Name: fn_ca_operator_permissions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_permissions(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_profile_role  text;
  v_is_legacy     boolean := false;
  v_enforce       boolean := false;
  v_legacy        text[]  := '{}';
  v_granted       text[]  := '{}';
  v_granted_roles text[]  := '{}';
  v_permissions   text[]  := '{}';
  v_roles         text[]  := '{}';
  v_source        text;
  v_floor         boolean := false;
begin
  if p_user_id is null then
    return jsonb_build_object(
      'role', null, 'roles', '[]'::jsonb, 'permissions', '[]'::jsonb,
      'source', 'none', 'admin_manage_floor', false
    );
  end if;

  select coalesce(pol.enforce_named_roles, false)
    into v_enforce
  from public.ca_operator_policy pol
  where pol.id
  limit 1;

  select p.role into v_profile_role
  from public.profiles as p
  where p.id = p_user_id
  limit 1;

  -- Only a role that exists in the table and is flagged legacy gets the
  -- automatic set. An unknown profiles.role contributes nothing.
  if v_profile_role is not null then
    select exists (
      select 1 from public.ca_operator_roles r
      where r.key = v_profile_role and r.is_legacy
    ) into v_is_legacy;

    select coalesce(array_agg(rp.permission order by rp.permission), '{}')
      into v_legacy
    from public.ca_operator_role_permissions rp
    join public.ca_operator_roles r on r.key = rp.role_key
    where r.key = v_profile_role
      and r.is_legacy;
  end if;

  select coalesce(array_agg(distinct rp.permission), '{}'),
         coalesce(array_agg(distinct g.role_key), '{}')
    into v_granted, v_granted_roles
  from public.ca_operator_grants g
  join public.ca_operator_role_permissions rp on rp.role_key = g.role_key
  where g.user_id = p_user_id
    and g.revoked_at is null;

  if v_enforce and array_length(v_granted_roles, 1) is not null then
    v_permissions := v_granted;
    v_roles       := v_granted_roles;
    v_source      := 'granted';
  else
    select coalesce(array_agg(distinct u.perm), '{}'::text[])
      into v_permissions
    from (
      select l.perm from unnest(v_legacy) as l(perm)
      union
      select g.perm from unnest(v_granted) as g(perm)
    ) u
    where u.perm is not null;

    select coalesce(array_agg(distinct y.role_key), '{}'::text[])
      into v_roles
    from (
      select v_profile_role as role_key
      where array_length(v_legacy, 1) is not null
      union
      select g.role_key from unnest(v_granted_roles) as g(role_key)
    ) y
    where y.role_key is not null;

    if array_length(v_legacy, 1) is not null and array_length(v_granted_roles, 1) is not null then
      v_source := 'both';
    elsif array_length(v_legacy, 1) is not null then
      v_source := 'legacy';
    elsif array_length(v_granted_roles, 1) is not null then
      v_source := 'granted';
    else
      v_source := 'none';
    end if;
  end if;

  -- THE RECOVERY HATCH (review finding H-4). An account whose
  -- profiles.role is a LEGACY role ALWAYS keeps admin.manage, whatever
  -- enforce_named_roles says and whatever grants it holds. Without this,
  -- granting a god `read_only` and flipping enforcement drops that god
  -- from 21 permissions to 6, admin.manage among the 15 lost, and
  -- admin.manage is the only permission that can flip enforcement back:
  -- the platform would be locked out of its own policy panel with direct
  -- SQL as the only way back in. This is purely ADDITIVE. It can widen a
  -- permission set and can never narrow one, so it cannot breach
  -- contract section 0, and it leaves `roles` and `source` describing
  -- exactly what was granted so the Staff tab still tells the truth.
  if v_is_legacy and not (coalesce(v_permissions, '{}'::text[]) @> array['admin.manage']) then
    v_permissions := coalesce(v_permissions, '{}'::text[]) || 'admin.manage'::text;
    v_floor := true;
  end if;

  -- NO AUDIT ROW IS WRITTEN HERE, DELIBERATELY. This is a READ, it runs
  -- on every console request behind a 30 second cache, and the route that
  -- called it already files one audit row for the request itself. See
  -- WHY PERMISSION RESOLUTION DOES NOT AUDIT ITSELF in 20260903120000.
  return jsonb_build_object(
    'role', v_profile_role,
    'roles', to_jsonb(coalesce(v_roles, '{}'::text[])),
    'permissions', to_jsonb(coalesce(v_permissions, '{}'::text[])),
    'source', v_source,
    -- Additive key. True when the line above put admin.manage back for a
    -- legacy account that enforcement would otherwise have stripped it
    -- from, so the console can say why it is there.
    'admin_manage_floor', v_floor
  );
end
$$;


ALTER FUNCTION public.fn_ca_operator_permissions(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_operator_read_hand(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_read_hand(p_club_id uuid, p_hand_number bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_reason text := btrim(COALESCE(p_reason, ''));
  v_hand   public.hand_history%ROWTYPE;
  v_club   uuid;
  v_cards  jsonb := '{}'::jsonb;
  v_fresh  jsonb;
  v_dealt  int;
  v_have   int;
BEGIN
  IF NOT public.fn_ca_is_club_control(p_club_id, v_uid) THEN
    RAISE EXCEPTION 'only a club owner or admin may open a hand'
      USING ERRCODE = '42501';
  END IF;

  IF char_length(v_reason) < 8 THEN
    RAISE EXCEPTION 'say why this hand is being opened' USING ERRCODE = '22023';
  END IF;

  SELECT h.* INTO v_hand
    FROM public.hand_history h
   WHERE h.hand_number = p_hand_number
   ORDER BY h.created_at DESC
   LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no hand numbered %', p_hand_number USING ERRCODE = 'P0002';
  END IF;

  SELECT t.club_id INTO v_club FROM public.tables t WHERE t.id = v_hand.table_id;
  IF v_club IS DISTINCT FROM p_club_id THEN
    RAISE EXCEPTION 'hand % was not dealt at this club', p_hand_number
      USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(jsonb_object_agg(f.user_id::text, f.hole_cards), '{}'::jsonb)
    INTO v_cards
    FROM public.ca_hand_facts f
   WHERE f.hand_id = v_hand.id
     AND f.hole_cards IS NOT NULL
     AND f.hole_cards::text NOT IN ('null', '[]', '{}');

  SELECT jsonb_object_agg(c.user_id::text, c.cards)
    INTO v_fresh
    FROM public.table_hole_cards c
   WHERE c.table_id = v_hand.table_id
     AND c.hand_number = v_hand.hand_number
     AND c.cards IS NOT NULL;

  v_cards := COALESCE(v_fresh, '{}'::jsonb) || v_cards;

  v_dealt := COALESCE(jsonb_array_length(v_hand.players), 0);
  v_have  := (SELECT count(*) FROM jsonb_object_keys(v_cards));

  INSERT INTO public.audit_trail
    (actor_id, actor_role, action, target_type, target_id, club_id, reason, after_state)
  VALUES (
    v_uid,
    public.fn_ca_club_actor_role(p_club_id, v_uid),
    'hand_godmode_read',
    'hand',
    v_hand.id,
    p_club_id,
    v_reason,
    jsonb_build_object(
      'hand_number', v_hand.hand_number,
      'table_id', v_hand.table_id,
      'seats_dealt', v_dealt,
      'seats_revealed', v_have,
      'played_at', COALESCE(v_hand.started_at, v_hand.created_at)
    )
  );

  RETURN to_jsonb(v_hand) || jsonb_build_object(
    'all_hole_cards', v_cards,
    'club_id', p_club_id,
    'seats_dealt', v_dealt,
    'seats_with_cards', v_have,
    'cards_complete', (v_dealt > 0 AND v_have >= v_dealt)
  );
END;
$$;


ALTER FUNCTION public.fn_ca_operator_read_hand(p_club_id uuid, p_hand_number bigint, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_operator_read_hand(p_club_id uuid, p_hand_number bigint, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_operator_read_hand(p_club_id uuid, p_hand_number bigint, p_reason text) IS 'The audited godmode read: every seat''s holding for one hand at the caller''s own club, from ca_hand_facts (durable) and table_hole_cards (fresh). Writes the audit_trail row in the same transaction that returns the cards, so a read cannot happen unlogged.';


--
-- Name: fn_ca_operator_request_approval(text, jsonb, uuid, numeric, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_request_approval(p_kind text, p_payload jsonb, p_requested_by uuid, p_amount numeric, p_asset text, p_target_type text, p_target_id text, p_reason text, p_op_id text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_policy         public.ca_operator_policy%rowtype;
  v_threshold      numeric;
  v_permission     text;
  v_required       boolean := false;
  v_alone          boolean := false;
  v_blocked        text;
  v_status         text;
  v_expires        timestamptz;
  v_id             uuid;
  v_existing       public.ca_operator_approvals%rowtype;
  v_replay         boolean := false;
  v_retry_failed   boolean := false;
  v_mismatch       text[]  := '{}';
begin
  if p_kind is null or p_kind not in ('mint','burn','fund_club','cashout','fleet_policy','sanction') then
    raise exception 'fn_ca_operator_request_approval: unknown kind %', p_kind;
  end if;

  -- Exactly once starts here, not at execution: a retried request with
  -- the same op_id must return the row it already made, never a second
  -- queue entry that a second operator could approve independently.
  if p_op_id is not null then
    select * into v_existing from public.ca_operator_approvals where op_id = p_op_id;
    if found then
      v_replay := true;
    end if;
  end if;

  if v_replay then
    -- ---------------------------------------------------------------
    -- IS THIS EVEN THE SAME OPERATION? (review finding B-3)
    -- ---------------------------------------------------------------
    -- The old body returned the stored row without ever looking at the
    -- parameters, so an approved 500-chip request for one club could be
    -- replayed as 999999 to another club and come back required:false.
    -- IS DISTINCT FROM, so a null matches a null and 500 matches 500.0.
    -- This runs BEFORE the status branch: a laundered replay must not be
    -- able to reach the "cleared to proceed" answer at all.
    if v_existing.kind is distinct from p_kind then
      v_mismatch := v_mismatch || 'kind'::text;
    end if;
    if v_existing.amount is distinct from p_amount then
      v_mismatch := v_mismatch || 'amount'::text;
    end if;
    if v_existing.asset is distinct from p_asset then
      v_mismatch := v_mismatch || 'asset'::text;
    end if;
    if v_existing.target_type is distinct from p_target_type then
      v_mismatch := v_mismatch || 'target_type'::text;
    end if;
    if v_existing.target_id is distinct from p_target_id then
      v_mismatch := v_mismatch || 'target_id'::text;
    end if;

    if array_length(v_mismatch, 1) is not null then
      return jsonb_build_object(
        'ok', false,
        'refused', true,
        -- required stays TRUE on every refusal. approvals.js ANDs this
        -- with its own cached decision, so a refusal that said false
        -- would read as "go" to a caller not yet taught to read `ok`.
        'required', true,
        'error', 'payload_mismatch',
        'reason', 'payload_mismatch',
        'mismatch', to_jsonb(v_mismatch),
        'approval_id', v_existing.id,
        'status', v_existing.status,
        'blocked_reason', v_existing.blocked_reason,
        'idempotent', true
      );
    end if;

    -- A pending row that has aged out is closed HERE rather than left to
    -- answer required:true forever, and rather than waiting for somebody
    -- to attempt a decision on it (review finding M-5). The row and the
    -- answer can then never disagree.
    if v_existing.status = 'pending'
       and v_existing.expires_at is not null
       and v_existing.expires_at <= now() then
      update public.ca_operator_approvals
        set status = 'expired'
      where id = v_existing.id
      returning * into v_existing;
    end if;

    -- ---------------------------------------------------------------
    -- WHAT EACH STORED STATUS MEANS (review finding B-2)
    -- ---------------------------------------------------------------
    -- The old body answered required := (status = 'pending'), so
    -- 'rejected' and 'expired' both came back required:false and the
    -- caller moved the money against a refused request.
    if v_existing.status in ('approved', 'auto_approved') then
      -- Cleared to proceed and not yet executed. The only two statuses
      -- that may answer false.
      return jsonb_build_object(
        'ok', true,
        'required', false,
        'approval_id', v_existing.id,
        'status', v_existing.status,
        'blocked_reason', v_existing.blocked_reason,
        'idempotent', true,
        'already_executed', false
      );
    elsif v_existing.status = 'executed' then
      -- Already done. required:false with already_executed:true, on
      -- purpose and not a refusal: the money RPC's own op_id claim is
      -- what replays from here (fn_ca_mint returns the original result
      -- rather than minting again), so the caller's idempotency does the
      -- work. Refusing would turn a dropped response on a completed mint
      -- into an operator error and invite a manual retry.
      return jsonb_build_object(
        'ok', true,
        'required', false,
        'approval_id', v_existing.id,
        'status', v_existing.status,
        'blocked_reason', v_existing.blocked_reason,
        'idempotent', true,
        'already_executed', true
      );
    elsif v_existing.status = 'pending' then
      return jsonb_build_object(
        'ok', true,
        'required', true,
        'approval_id', v_existing.id,
        'status', v_existing.status,
        'blocked_reason', v_existing.blocked_reason,
        'idempotent', true,
        'already_executed', false
      );
    elsif v_existing.status in ('rejected', 'expired') then
      -- A human said no, or the request timed out. Either way this
      -- operation does not proceed under this key. The route maps
      -- refused:true onto a 403 or 409; a caller that only reads
      -- `required` sees true and returns the 202 pending body, which
      -- moves no money either.
      return jsonb_build_object(
        'ok', false,
        'refused', true,
        'required', true,
        'error', case when v_existing.status = 'rejected'
                      then 'approval_rejected' else 'approval_expired' end,
        'reason', case when v_existing.status = 'rejected'
                       then 'approval_rejected' else 'approval_expired' end,
        'approval_id', v_existing.id,
        'status', v_existing.status,
        'blocked_reason', v_existing.blocked_reason,
        'idempotent', true
      );
    else
      -- 'failed'. The previous attempt moved no money, so the operator
      -- is entitled to try again, and this is a FRESH request: the
      -- policy is read again and the threshold applied again. op_id is
      -- unique, so the existing row is re-opened in place below rather
      -- than duplicated.
      v_retry_failed := true;
    end if;
  end if;

  select * into v_policy from public.ca_operator_policy where id limit 1;
  if not found then
    -- No policy row means no configured control, and the safety rule
    -- says an absent control never blocks a move that works today.
    v_policy.approvals_enabled := false;
    v_policy.allow_self_approve_when_alone := true;
    v_policy.approval_ttl_minutes := 1440;
  end if;

  v_permission := case p_kind
                    when 'cashout' then 'cashier.write'
                    when 'fleet_policy' then 'fleet.write'
                    when 'sanction' then 'moderation.write'
                    else 'money.write'
                  end;

  v_threshold := case p_kind
                   when 'cashout' then coalesce(v_policy.cashout_threshold, 0)
                   when 'fund_club' then coalesce(v_policy.fund_threshold, 0)
                   when 'mint' then coalesce(v_policy.mint_threshold, 0)
                   when 'burn' then coalesce(v_policy.mint_threshold, 0)
                   else 0
                 end;

  if not coalesce(v_policy.approvals_enabled, false) then
    v_required := false;
  elsif p_amount is null then
    -- A kind with no amount (fleet_policy, sanction) has nothing to
    -- compare against a threshold, so with approvals on it always asks.
    v_required := true;
  else
    -- >= AND NOT > (review finding H-2). src/lib/horses/approvals.js
    -- gates at `amt < threshold` (so >= asks), the module comment says
    -- so, the console copy an operator reads says so and the test
    -- asserts it. requireApproval ANDs the two answers, so the looser
    -- one won: a threshold of exactly 1000 let 1000 through unwatched.
    v_required := p_amount >= v_threshold;
  end if;

  if v_required then
    v_alone := not public.fn_ca_operator_has_second_approver(p_requested_by, v_permission);
    if v_alone then
      -- Always recorded, whichever way the rule falls, so the trail
      -- shows the platform was short handed at this moment.
      v_blocked := 'no_second_approver';
      if coalesce(v_policy.allow_self_approve_when_alone, true) then
        v_required := false;
      end if;
    end if;
  end if;

  if v_required then
    v_status  := 'pending';
    v_expires := now() + make_interval(mins => coalesce(v_policy.approval_ttl_minutes, 1440));
  else
    v_status  := 'auto_approved';
    v_expires := null;
  end if;

  if v_retry_failed then
    -- Re-open the failed row under its own key rather than insert a
    -- second row the unique index would reject.
    update public.ca_operator_approvals
      set status         = v_status,
          requested_by   = p_requested_by,
          requested_at   = now(),
          amount         = p_amount,
          asset          = p_asset,
          target_type    = p_target_type,
          target_id      = p_target_id,
          reason         = p_reason,
          payload        = coalesce(p_payload, '{}'::jsonb),
          blocked_reason = v_blocked,
          request_id     = p_request_id,
          expires_at     = v_expires,
          executed_at    = null,
          decided_by     = case when v_status = 'auto_approved' and v_alone then p_requested_by end,
          decided_at     = case when v_status = 'auto_approved' and v_alone then now() end
    where id = v_existing.id
    returning id into v_id;
  else
    insert into public.ca_operator_approvals (
      kind, status, requested_by, amount, asset, target_type, target_id,
      reason, payload, op_id, blocked_reason, request_id, expires_at,
      decided_by, decided_at
    ) values (
      p_kind, v_status, p_requested_by, p_amount, p_asset, p_target_type, p_target_id,
      p_reason, coalesce(p_payload, '{}'::jsonb), p_op_id, v_blocked, p_request_id, v_expires,
      -- decided_by is the requester ONLY when the alone rule let them
      -- stand in for a second operator. A plain auto_approved row (the
      -- normal case today, approvals off) has no decider, and saying it
      -- had one would put a self approval in the trail that never
      -- happened.
      case when v_status = 'auto_approved' and v_alone then p_requested_by end,
      -- AND NEITHER DOES IT HAVE A DECISION TIME (review finding L-4).
      -- The old body stamped decided_at = now() on every auto_approved
      -- row, decider or not, which reads to anyone querying the table
      -- later as a decision that happened and whose decider was lost.
      case when v_status = 'auto_approved' and v_alone then now() end
    )
    -- The check above and this insert used to be two statements with
    -- nothing between them but hope (review finding M-3): two requests
    -- with the same op_id both missed the SELECT, both inserted, and the
    -- second raised 23505, which approvals.js reads as "the approval
    -- could not be recorded" and turns into a 503 on what should be a
    -- 202. The partial unique index resolves it now, and the loser
    -- re-reads the winner's row below.
    on conflict (op_id) where op_id is not null do nothing
    returning id into v_id;

    if v_id is null then
      select * into v_existing from public.ca_operator_approvals where op_id = p_op_id;
      if not found then
        raise exception 'fn_ca_operator_request_approval: op_id % conflicted but no row can be read', p_op_id;
      end if;
      -- The winner's row, answered by the same rules as any other
      -- replay. Only the two cleared statuses may say required:false.
      return jsonb_build_object(
        'ok', v_existing.status not in ('rejected', 'expired'),
        'refused', v_existing.status in ('rejected', 'expired'),
        'required', v_existing.status not in ('approved', 'auto_approved', 'executed'),
        'approval_id', v_existing.id,
        'status', v_existing.status,
        'blocked_reason', v_existing.blocked_reason,
        'idempotent', true,
        'already_executed', v_existing.status = 'executed',
        'raced', true
      );
    end if;
  end if;

  begin
    perform public.fn_log_admin_action(
      p_admin_user_id := p_requested_by,
      p_action        := 'operator.request_approval',
      p_target_type   := coalesce(p_target_type, 'operator_approval'),
      p_target_id     := coalesce(p_target_id, v_id::text),
      p_details       := jsonb_build_object(
                           'approval_id', v_id,
                           'kind', p_kind,
                           'amount', p_amount,
                           'asset', p_asset,
                           'threshold', v_threshold,
                           'required', v_required,
                           'status', v_status,
                           'blocked_reason', v_blocked,
                           'alone_rule_applied', v_alone and not v_required,
                           'approvals_enabled', coalesce(v_policy.approvals_enabled, false),
                           'retried_after_failure', v_retry_failed,
                           'op_id', p_op_id
                         ),
      p_before_state  := null,
      p_after_state   := jsonb_build_object('status', v_status, 'expires_at', v_expires),
      p_ip_address    := null,
      p_user_agent    := null,
      p_request_id    := p_request_id
    );
  exception when others then
    raise notice 'fn_ca_operator_request_approval audit failed: %', sqlerrm;
  end;

  return jsonb_build_object(
    'ok', true,
    'required', v_required,
    'approval_id', v_id,
    'status', v_status,
    'blocked_reason', v_blocked,
    'idempotent', false,
    'already_executed', false,
    'retried_after_failure', v_retry_failed
  );
end
$$;


ALTER FUNCTION public.fn_ca_operator_request_approval(p_kind text, p_payload jsonb, p_requested_by uuid, p_amount numeric, p_asset text, p_target_type text, p_target_id text, p_reason text, p_op_id text, p_request_id text) OWNER TO postgres;

--
-- Name: fn_ca_operator_revoke(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_revoke(p_grant_id uuid, p_revoked_by uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row       public.ca_operator_grants%rowtype;
  v_already   boolean := false;
begin
  select * into v_row from public.ca_operator_grants where id = p_grant_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'grant_not_found', 'reason', 'grant_not_found', 'grant_id', p_grant_id);
  end if;

  if v_row.revoked_at is not null then
    v_already := true;
  else
    update public.ca_operator_grants
      set revoked_at = now(),
          revoked_by = p_revoked_by,
          note = p_reason
    where id = p_grant_id
    returning * into v_row;
  end if;

  begin
    perform public.fn_log_admin_action(
      p_admin_user_id := p_revoked_by,
      p_action        := 'operator.revoke_role',
      p_target_type   := 'operator',
      p_target_id     := v_row.user_id::text,
      p_details       := jsonb_build_object(
                           'grant_id', p_grant_id,
                           'role_key', v_row.role_key,
                           'reason', p_reason,
                           'already_revoked', v_already
                         ),
      p_before_state  := jsonb_build_object('role_key', v_row.role_key, 'revoked_at', null),
      p_after_state   := jsonb_build_object('role_key', v_row.role_key, 'revoked_at', v_row.revoked_at),
      p_ip_address    := null,
      p_user_agent    := null,
      p_request_id    := null
    );
  exception when others then
    raise notice 'fn_ca_operator_revoke audit failed: %', sqlerrm;
  end;

  return jsonb_build_object(
    'ok', true,
    'grant_id', p_grant_id,
    'user_id', v_row.user_id,
    'role_key', v_row.role_key,
    'already_revoked', v_already,
    'permissions', (select public.fn_ca_operator_permissions(v_row.user_id) -> 'permissions')
  );
end
$$;


ALTER FUNCTION public.fn_ca_operator_revoke(p_grant_id uuid, p_revoked_by uuid, p_reason text) OWNER TO postgres;

--
-- Name: fn_ca_operator_set_policy(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_set_policy(p_patch jsonb, p_updated_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_before  public.ca_operator_policy%rowtype;
  v_after   public.ca_operator_policy%rowtype;
  v_holders int := 0;
begin
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception 'fn_ca_operator_set_policy: p_patch must be a json object';
  end if;

  select * into v_before from public.ca_operator_policy where id for update;
  if not found then
    insert into public.ca_operator_policy (id) values (true) returning * into v_before;
  end if;

  -- THE LOCKOUT GUARD (review finding H-4). admin.manage is the only
  -- permission that can set this policy, so turning enforcement on when
  -- nobody would still hold it is a one-way door: the panel that could
  -- turn it back off becomes unreachable and direct SQL is the only
  -- recovery. Refuse with a reason instead, and say how many holders
  -- were counted so the operator can see what to fix first (grant
  -- somebody `owner`, then flip the flag).
  --
  -- The count mirrors what fn_ca_operator_permissions resolves once
  -- enforcement is on: every legacy-role account, which keeps
  -- admin.manage through the recovery hatch in section 1 above, plus
  -- every account holding an active grant on a role that carries
  -- admin.manage.
  if coalesce((p_patch ->> 'enforce_named_roles')::boolean, false) then
    select count(*) into v_holders
    from (
      select p.id as user_id
      from public.profiles p
      join public.ca_operator_roles r on r.key = p.role and r.is_legacy
      union
      select g.user_id
      from public.ca_operator_grants g
      join public.ca_operator_role_permissions rp on rp.role_key = g.role_key
      where g.revoked_at is null
        and rp.permission = 'admin.manage'
    ) holders;

    if v_holders = 0 then
      return jsonb_build_object(
        'ok', false,
        'error', 'enforce_named_roles_would_lock_out',
        'reason', 'enforce_named_roles_would_lock_out',
        'admin_manage_holders', v_holders,
        'policy', to_jsonb(v_before)
      );
    end if;
  end if;

  update public.ca_operator_policy
    set approvals_enabled             = coalesce((p_patch ->> 'approvals_enabled')::boolean, v_before.approvals_enabled),
        allow_self_approve_when_alone = coalesce((p_patch ->> 'allow_self_approve_when_alone')::boolean, v_before.allow_self_approve_when_alone),
        enforce_named_roles           = coalesce((p_patch ->> 'enforce_named_roles')::boolean, v_before.enforce_named_roles),
        mint_threshold                = coalesce((p_patch ->> 'mint_threshold')::numeric, v_before.mint_threshold),
        fund_threshold                = coalesce((p_patch ->> 'fund_threshold')::numeric, v_before.fund_threshold),
        cashout_threshold             = coalesce((p_patch ->> 'cashout_threshold')::numeric, v_before.cashout_threshold),
        approval_ttl_minutes          = coalesce((p_patch ->> 'approval_ttl_minutes')::int, v_before.approval_ttl_minutes),
        updated_by                    = p_updated_by,
        updated_at                    = now()
  where id
  returning * into v_after;

  begin
    perform public.fn_log_admin_action(
      p_admin_user_id := p_updated_by,
      p_action        := 'operator.set_policy',
      p_target_type   := 'operator_policy',
      p_target_id     := 'singleton',
      p_details       := jsonb_build_object('patch', p_patch, 'admin_manage_holders', v_holders),
      p_before_state  := to_jsonb(v_before),
      p_after_state   := to_jsonb(v_after),
      p_ip_address    := null,
      p_user_agent    := null,
      p_request_id    := null
    );
  exception when others then
    raise notice 'fn_ca_operator_set_policy audit failed: %', sqlerrm;
  end;

  return jsonb_build_object('ok', true, 'policy', to_jsonb(v_after));
end
$$;


ALTER FUNCTION public.fn_ca_operator_set_policy(p_patch jsonb, p_updated_by uuid) OWNER TO postgres;

--
-- Name: fn_ca_operator_staff(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_staff() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_mfa       jsonb   := '{}'::jsonb;
  v_mfa_known boolean := false;
  v_rows      jsonb   := '[]'::jsonb;
begin
  -- auth.mfa_factors is not present on every project and the definer may
  -- not be able to read it. UNREADABLE MFA state is reported as null,
  -- never as "no MFA", and never as a failed staff page. A read that
  -- SUCCEEDED and found nobody is "no MFA" (review finding N-4): before
  -- this the Staff tab could not say "No" until one operator enrolled.
  begin
    if to_regclass('auth.mfa_factors') is not null then
      execute $q$
        select coalesce(jsonb_object_agg(user_id::text, cnt), '{}'::jsonb)
        from (
          select user_id, count(*) as cnt
          from auth.mfa_factors
          where status = 'verified'
          group by user_id
        ) m
      $q$ into v_mfa;
      v_mfa_known := true;
    end if;
  exception when others then
    raise notice 'fn_ca_operator_staff mfa read failed: %', sqlerrm;
    v_mfa := '{}'::jsonb;
    v_mfa_known := false;
  end;

  -- Widest role first, which is rank descending: ROLE_META gives god 100
  -- and read_only 10.
  select coalesce(jsonb_agg(to_jsonb(s) order by s.rank desc, s.email), '[]'::jsonb)
    into v_rows
  from (
    select
      p.id                                   as user_id,
      p.email,
      p.username,
      p.display_name,
      p.role                                 as profile_role,
      coalesce(r.rank, 0)                    as rank,
      coalesce(
        (select jsonb_agg(g.role_key order by g.role_key)
         from public.ca_operator_grants g
         where g.user_id = p.id and g.revoked_at is null),
        '[]'::jsonb
      )                                      as granted_roles,
      -- The same active grants again, WITH THEIR IDS. granted_roles is
      -- kept beside this and unchanged, because it is what the first
      -- build of the console reads; this array is additive.
      -- fn_ca_operator_revoke takes a grant id and a revoked grant is
      -- kept rather than deleted, so the id IS the record: without it
      -- the Staff tab can list the roles an operator holds and offer no
      -- way to take one back, which is a console that can only ever
      -- widen. granted_by and reason travel with it so the row can say
      -- who gave it and why without a second request.
      coalesce(
        (select jsonb_agg(
                  jsonb_build_object(
                    'id', g.id,
                    'role_key', g.role_key,
                    'granted_at', g.granted_at,
                    'granted_by', g.granted_by,
                    'reason', g.reason
                  ) order by g.granted_at desc
                )
         from public.ca_operator_grants g
         where g.user_id = p.id and g.revoked_at is null),
        '[]'::jsonb
      )                                      as grants,
      (select count(*) from public.ca_operator_grants g where g.user_id = p.id) as grant_history_count,
      u.last_sign_in_at,
      case
        when not v_mfa_known then null
        else coalesce((v_mfa ->> p.id::text)::int, 0) > 0
      end                                    as mfa_enabled
    from public.profiles p
    left join public.ca_operator_roles r on r.key = p.role
    left join auth.users u on u.id = p.id
    where exists (
            select 1 from public.ca_operator_roles lr
            where lr.key = p.role and lr.is_legacy
          )
       or exists (
            select 1 from public.ca_operator_grants g where g.user_id = p.id
          )
  ) s;

  -- This function files NO audit row. Same reason as
  -- fn_ca_operator_audit_trail: a read with no actor in its signature
  -- cannot write a row the audit helper will accept.

  return jsonb_build_object('staff', v_rows, 'total', jsonb_array_length(v_rows));
end
$_$;


ALTER FUNCTION public.fn_ca_operator_staff() OWNER TO postgres;

--
-- Name: fn_ca_orphaned_checks(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_orphaned_checks() RETURNS TABLE(proname text, args text, why text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  WITH sweep AS (
    SELECT COALESCE(
      (SELECT pg_get_functiondef(p.oid)
         FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname='public' AND p.proname='fn_ca_conservation_sweep'
        LIMIT 1), '') AS body
  ),
  candidates AS (
    SELECT p.proname::text AS pn,
           pg_get_function_identity_arguments(p.oid) AS ar
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public'
       AND p.prokind = 'f'
       AND p.prorettype <> 'trigger'::regtype
       AND p.proname ~ '(conservation|_check$|_audit$|_watch$|integrity)'
       AND p.proname NOT LIKE '%selftest%'
  )
  SELECT c.pn, c.ar,
         'exists but nothing runs it: no cron entry, not called by fn_ca_conservation_sweep, and no exemption reason'
    FROM candidates c, sweep s
   WHERE NOT EXISTS (SELECT 1 FROM cron.job j WHERE j.command LIKE '%' || c.pn || '%')
     AND position(c.pn IN s.body) = 0
     AND NOT EXISTS (SELECT 1 FROM public.ca_check_sweep_exemptions e WHERE e.proname = c.pn)
   ORDER BY 1;
$_$;


ALTER FUNCTION public.fn_ca_orphaned_checks() OWNER TO postgres;

--
-- Name: fn_ca_orphaned_checks_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_orphaned_checks_watch() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_n int; v_rows jsonb;
BEGIN
  SELECT count(*), jsonb_agg(jsonb_build_object('fn', o.proname, 'args', o.args))
    INTO v_n, v_rows
    FROM public.fn_ca_orphaned_checks() o;

  IF COALESCE(v_n,0) > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_orphaned_checks_watch', 'unknown', 'warning',
      'orphaned-checks:' || CURRENT_DATE::text,
      0, NULL, NULL, 'ledger', 'pg_proc',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      v_n || ' integrity check function(s) exist that nothing ever runs. '
        || 'Schedule them, add them to fn_ca_conservation_sweep, or exempt them '
        || 'with a reason in ca_check_sweep_exemptions. A check nobody runs '
        || 'reads as a check finding nothing.',
      false, jsonb_build_object('orphans', v_rows));
  END IF;
  RETURN COALESCE(v_n,0);
END;
$$;


ALTER FUNCTION public.fn_ca_orphaned_checks_watch() OWNER TO postgres;

--
-- Name: fn_ca_overlay_shortfall(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_overlay_shortfall(p_tournament_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT GREATEST(0, round(COALESCE(t.guaranteed_prize,0),2) - round(COALESCE(t.prize_pool,0),2))
    FROM public.tournaments t WHERE t.id = p_tournament_id;
$$;


ALTER FUNCTION public.fn_ca_overlay_shortfall(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_overlay_shortfall(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_overlay_shortfall(p_tournament_id uuid) IS 'What the main bank still owes this tournament to meet its guarantee. Zero once the pool has been topped up, which is why the funding is idempotent without a flag.';


--
-- Name: fn_ca_payout_structure(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_payout_structure(p_entrants integer, p_percent integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_places int;
  v_pct    numeric;
  v_out    jsonb;
BEGIN
  v_pct := CASE WHEN p_percent IN (10,15,20) THEN p_percent ELSE 10 END;

  -- at least one place, never more places than players
  v_places := GREATEST(1, LEAST(COALESCE(p_entrants,0),
                                ceil(COALESCE(p_entrants,0) * v_pct / 100.0)::int));
  IF COALESCE(p_entrants,0) <= 0 THEN
    RETURN '[]'::jsonb;
  END IF;

  WITH w AS (
    SELECT i AS place, 1.0 / power(i, 0.8) AS weight
      FROM generate_series(1, v_places) i
  ), n AS (
    SELECT place, weight, 100.0 * weight / SUM(weight) OVER () AS exact
      FROM w
  ), f AS (
    SELECT place, exact,
           floor(exact * 100) / 100 AS floored,
           (exact * 100) - floor(exact * 100) AS frac
      FROM n
  ), r AS (
    -- largest remainder: hand the leftover cents to the biggest fractions, so
    -- the structure sums to exactly 100.00 for any field size
    SELECT place, floored,
           row_number() OVER (ORDER BY frac DESC, place ASC) AS rk,
           round((100.0 - SUM(floored) OVER ()) * 100)::int AS cents_left
      FROM f
  )
  SELECT jsonb_agg(
           jsonb_build_object('place', place,
                              'percentage', floored + CASE WHEN rk <= cents_left THEN 0.01 ELSE 0 END)
           ORDER BY place)
    INTO v_out
    FROM r;

  RETURN COALESCE(v_out, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.fn_ca_payout_structure(p_entrants integer, p_percent integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_payout_structure(p_entrants integer, p_percent integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_payout_structure(p_entrants integer, p_percent integer) IS 'Payout table for a field of p_entrants paying the top p_percent (10/15/20). Places = ceil(entrants * percent / 100), min 1, never more than the field. Weight 1/place^0.8 normalised to 100, with largest-remainder rounding so the percentages sum to EXACTLY 100.00 at every field size.';


--
-- Name: fn_ca_pgrst_reload_if_stale(interval, interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_pgrst_reload_if_stale(p_ddl_window interval DEFAULT '00:15:00'::interval, p_cooldown interval DEFAULT '00:05:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ddl      integer;
  v_last     timestamptz;
BEGIN
  SELECT count(*) INTO v_ddl
    FROM public.ca_ddl_events
   WHERE occurred_at > now() - p_ddl_window
     AND triggers_pgrst_reload;

  IF v_ddl = 0 THEN
    -- No DDL, so the cache cannot have gone stale. Reloading here would be the
    -- unconditional timer this deliberately is not.
    RETURN jsonb_build_object('sent', false, 'reason', 'no reload-triggering ddl in window', 'ddl_events', 0);
  END IF;

  SELECT max(sent_at) INTO v_last FROM public.ca_pgrst_reload_log;

  IF v_last IS NOT NULL AND v_last > now() - p_cooldown THEN
    RETURN jsonb_build_object('sent', false, 'reason', 'cooldown', 'ddl_events', v_ddl,
                              'last_sent_at', v_last);
  END IF;

  NOTIFY pgrst, 'reload schema';

  INSERT INTO public.ca_pgrst_reload_log (ddl_events, reason)
  VALUES (v_ddl, format('%s reload-triggering ddl event(s) in %s', v_ddl, p_ddl_window));

  RETURN jsonb_build_object('sent', true, 'ddl_events', v_ddl);
END;
$$;


ALTER FUNCTION public.fn_ca_pgrst_reload_if_stale(p_ddl_window interval, p_cooldown interval) OWNER TO postgres;

--
-- Name: fn_ca_player_360(uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_player_360(p_user_id uuid, p_money_visible boolean DEFAULT false, p_reveal_email boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_p       public.profiles;
  v_money   boolean := coalesce(p_money_visible, false);
  v_profile jsonb;
  v_rg      jsonb;
begin
  select * into v_p from public.profiles where id = p_user_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'player_not_found');
  end if;

  v_profile := jsonb_build_object(
    'id', v_p.id,
    'displayName', v_p.display_name,
    'username', v_p.username,
    'playerNumber', v_p.player_number,
    'avatarUrl', v_p.avatar_url,
    'country', v_p.country,
    'createdAt', v_p.created_at,
    'lastSeen', v_p.last_seen,
    'lastLogin', v_p.last_login,
    'emailVerified', v_p.email_verified,
    'phoneVerified', v_p.phone_verified,
    'isHorse', coalesce(v_p.is_horse, false),
    'role', v_p.role,
    'status', v_p.status,
    'totalHandsPlayed', v_p.total_hands_played);

  if p_reveal_email then
    v_profile := v_profile || jsonb_build_object('email', v_p.email);
  end if;
  if v_money then
    v_profile := v_profile || jsonb_build_object('diamonds', v_p.diamond_balance);
  end if;

  -- The four deposit and loss limits are CURRENCY. The exclusion
  -- timestamps and the reality-check interval are protection state, not
  -- money, and stay visible to anybody who can open the tab: an
  -- operator answering a self-exclusion question needs to see it.
  select jsonb_build_object(
           'user_id', rg.user_id,
           'session_time_limit_minutes', rg.session_time_limit_minutes,
           'reality_check_interval_minutes', rg.reality_check_interval_minutes,
           'self_excluded_until', rg.self_excluded_until,
           'cooling_off_until', rg.cooling_off_until,
           'limit_increase_available_at', rg.limit_increase_available_at,
           'updated_at', rg.updated_at,
           'daily_deposit_limit', case when v_money then rg.daily_deposit_limit end,
           'weekly_deposit_limit', case when v_money then rg.weekly_deposit_limit end,
           'monthly_deposit_limit', case when v_money then rg.monthly_deposit_limit end,
           'daily_loss_limit', case when v_money then rg.daily_loss_limit end)
    into v_rg
    from public.responsible_gaming_limits rg
   where rg.user_id = p_user_id;

  return jsonb_build_object(
    'ok', true,
    'moneyVisible', v_money,
    'emailRevealed', coalesce(p_reveal_email, false),
    'profile', v_profile,

    'restrictions', coalesce((
      select jsonb_agg(to_jsonb(r) order by r.applied_at desc, r.id)
        from public.ca_player_restrictions r where r.user_id = p_user_id), '[]'::jsonb),

    'notes', coalesce((
      select jsonb_agg(to_jsonb(n) order by n.pinned desc, n.created_at desc, n.id)
        from public.ca_operator_player_notes n
       where n.user_id = p_user_id and n.deleted_at is null), '[]'::jsonb),

    'tags', coalesce((
      select jsonb_agg(t.tag order by t.tag)
        from public.ca_operator_player_tags t where t.user_id = p_user_id), '[]'::jsonb),

    'clubs', coalesce((
      select jsonb_agg(jsonb_build_object(
               'clubId', cm.club_id,
               'clubName', c.name,
               'role', cm.role,
               'status', cm.status,
               'joinedAt', cm.joined_at,
               'lastActiveAt', cm.last_active_at,
               'handsPlayed', cm.hands_played,
               'chipBalance', case when v_money then cm.chip_balance else null end)
             order by cm.joined_at desc)
        from public.club_members cm
        left join public.clubs c on c.id = cm.club_id
       where cm.user_id = p_user_id), '[]'::jsonb),

    'playRecord', coalesce((
      select jsonb_agg(jsonb_build_object(
               'clubId', ps.club_id,
               'handsPlayed', ps.hands_played,
               'vpip', ps.vpip,
               'pfr', ps.pfr,
               'tournamentsPlayed', ps.tournaments_played,
               'tournamentsWon', ps.tournaments_won,
               'totalWinnings', case when v_money then ps.total_winnings else null end,
               'totalLosses', case when v_money then ps.total_losses else null end,
               'totalRake', case when v_money then ps.total_rake else null end))
        from public.player_stats ps where ps.user_id = p_user_id), '[]'::jsonb),

    'seats', coalesce((
      select jsonb_agg(jsonb_build_object(
               'tableId', ts.table_id, 'seatNumber', ts.seat_number,
               'joinedAt', ts.joined_at, 'clubId', ts.club_id,
               'stack', case when v_money then ts.stack else null end)
             order by ts.joined_at desc)
        from public.table_seats ts
       where ts.user_id = p_user_id and ts.left_at is null), '[]'::jsonb),

    'kycEvents', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', k.id, 'eventType', k.event_type, 'provider', k.provider,
               'previousStatus', k.previous_status, 'newStatus', k.new_status,
               'source', k.source, 'createdAt', k.created_at)
             order by k.created_at desc)
        from (select * from public.kyc_events
               where user_id = p_user_id order by created_at desc, id limit 50) k),
      '[]'::jsonb),

    'responsibleGaming', v_rg,

    'tickets', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', t.id, 'subject', t.subject, 'status', t.status,
               'priority', t.priority, 'assignedTo', t.assigned_to,
               'createdAt', t.created_at, 'resolvedAt', t.resolved_at)
             order by t.created_at desc)
        from (select * from public.live_help_tickets
               where user_id = p_user_id order by created_at desc, id limit 50) t),
      '[]'::jsonb),

    'reportsAgainst', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', ur.id, 'reason', ur.reason, 'status', ur.status,
               'createdAt', ur.created_at)
             order by ur.created_at desc)
        from (select * from public.user_reports
               where reported_user_id = p_user_id order by created_at desc, id limit 50) ur),
      '[]'::jsonb),

    'flags', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', f.id, 'flagType', f.flag_type, 'severity', f.severity,
               'status', f.status, 'flaggedAt', f.flagged_at)
             order by f.flagged_at desc)
        from (select * from public.anti_cheat_flags
               where player_id = p_user_id order by flagged_at desc, id limit 50) f),
      '[]'::jsonb),

    'auditRowCount', (
      select count(*) from public.admin_audit_log
       where target_id = p_user_id::text),

    'observationCount', (
      select count(*) from public.ca_restriction_observations
       where user_id = p_user_id)
  );
end;
$$;


ALTER FUNCTION public.fn_ca_player_360(p_user_id uuid, p_money_visible boolean, p_reveal_email boolean) OWNER TO postgres;

--
-- Name: fn_ca_player_lift_restriction(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_player_lift_restriction(p_id uuid, p_actor uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_before public.ca_player_restrictions;
  v_after  public.ca_player_restrictions;
begin
  if p_actor is null then
    return jsonb_build_object('ok', false, 'reason', 'actor_required');
  end if;

  select * into v_before from public.ca_player_restrictions where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if v_before.status <> 'active' then
    return jsonb_build_object('ok', false, 'reason', 'not_active',
                              'status', v_before.status);
  end if;

  update public.ca_player_restrictions
     set status    = 'lifted',
         lifted_by = p_actor,
         lifted_at = now(),
         lift_note = nullif(btrim(coalesce(p_note, '')), '')
   where id = p_id
  returning * into v_after;

  return jsonb_build_object('ok', true, 'restriction', to_jsonb(v_after),
                            'before', to_jsonb(v_before));
end;
$$;


ALTER FUNCTION public.fn_ca_player_lift_restriction(p_id uuid, p_actor uuid, p_note text) OWNER TO postgres;

--
-- Name: fn_ca_player_note_add(uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_player_note_add(p_user_id uuid, p_body text, p_actor uuid, p_pinned boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.ca_operator_player_notes;
begin
  if p_actor is null then
    return jsonb_build_object('ok', false, 'reason', 'actor_required');
  end if;
  if coalesce(btrim(p_body), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'body_required');
  end if;

  insert into public.ca_operator_player_notes (user_id, body, author_id, pinned)
  values (p_user_id, btrim(p_body), p_actor, coalesce(p_pinned, false))
  returning * into v_row;

  return jsonb_build_object('ok', true, 'note', to_jsonb(v_row));
end;
$$;


ALTER FUNCTION public.fn_ca_player_note_add(p_user_id uuid, p_body text, p_actor uuid, p_pinned boolean) OWNER TO postgres;

--
-- Name: fn_ca_player_note_delete(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_player_note_delete(p_note_id uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_before public.ca_operator_player_notes;
  v_after  public.ca_operator_player_notes;
begin
  if p_actor is null then
    return jsonb_build_object('ok', false, 'reason', 'actor_required');
  end if;

  select * into v_before from public.ca_operator_player_notes where id = p_note_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if v_before.deleted_at is not null then
    return jsonb_build_object('ok', false, 'reason', 'already_deleted');
  end if;

  update public.ca_operator_player_notes
     set deleted_at = now(), deleted_by = p_actor, updated_at = now()
   where id = p_note_id
  returning * into v_after;

  -- `before` travels back so the ROUTE can file the real prior state
  -- rather than a synthetic { deleted: false }.
  return jsonb_build_object('ok', true, 'note', to_jsonb(v_after),
                            'before', to_jsonb(v_before));
end;
$$;


ALTER FUNCTION public.fn_ca_player_note_delete(p_note_id uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: fn_ca_player_restrict(uuid, text, text, text, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_player_restrict(p_user_id uuid, p_scope text, p_reason_code text, p_note text, p_expires_at timestamp with time zone, p_actor uuid, p_approval_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row      public.ca_player_restrictions;
  v_existing public.ca_player_restrictions;
  v_is_horse boolean;
begin
  if p_actor is null then
    return jsonb_build_object('ok', false, 'reason', 'actor_required');
  end if;
  if p_user_id is null then
    return jsonb_build_object('ok', false, 'reason', 'user_required');
  end if;

  select is_horse into v_is_horse from public.profiles where id = p_user_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'player_not_found');
  end if;

  -- expires_at is the clock, status is only the intent. A row that has
  -- run out does not bind, so it must not block either - the console
  -- renders it Expired and told the operator to lift an active one.
  select * into v_existing
    from public.ca_player_restrictions
   where user_id = p_user_id and scope = p_scope and status = 'active'
     and (expires_at is null or expires_at > now())
   limit 1;

  if found then
    return jsonb_build_object(
      'ok', false, 'reason', 'already_restricted',
      'restriction_id', v_existing.id,
      'applied_at', v_existing.applied_at);
  end if;

  -- The partial unique index has the same blind spot by construction: it
  -- keys on status alone. So a run-out row that the sweep has not
  -- reached yet is retired HERE, in the same transaction, rather than
  -- raising a unique violation the operator cannot act on.
  update public.ca_player_restrictions
     set status = 'expired'
   where user_id = p_user_id and scope = p_scope and status = 'active'
     and expires_at is not null and expires_at <= now();

  insert into public.ca_player_restrictions
    (user_id, scope, reason_code, reason_note, expires_at, applied_by, approval_id)
  values
    (p_user_id, p_scope, p_reason_code, nullif(btrim(coalesce(p_note, '')), ''),
     p_expires_at, p_actor, p_approval_id)
  returning * into v_row;

  -- NO fn_log_admin_action HERE. The route audits, and it is the only
  -- half that knows the ip, the user agent and the request id that
  -- Phase 1's audit contract requires on every row. Two writers meant
  -- two rows per event and two different answers to "what changed".
  return jsonb_build_object('ok', true, 'restriction', to_jsonb(v_row),
                            'is_horse', coalesce(v_is_horse, false));
end;
$$;


ALTER FUNCTION public.fn_ca_player_restrict(p_user_id uuid, p_scope text, p_reason_code text, p_note text, p_expires_at timestamp with time zone, p_actor uuid, p_approval_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_player_restricted(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_player_restricted(p_user_id uuid, p_scope text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_user_id is null or p_scope is null then
    return false;
  end if;

  return exists (
    select 1
      from public.ca_player_restrictions r
     where r.user_id = p_user_id
       and r.status = 'active'
       and (r.expires_at is null or r.expires_at > now())
       and (r.scope = p_scope or r.scope = 'account')
  );
exception
  when others then
    -- SECTION 0 RULE 3, FAIL OPEN. A player refused a seat because a
    -- lookup broke is a support ticket about something nobody chose.
    return false;
end;
$$;


ALTER FUNCTION public.fn_ca_player_restricted(p_user_id uuid, p_scope text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_player_restricted(p_user_id uuid, p_scope text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_player_restricted(p_user_id uuid, p_scope text) IS 'True when an active, unexpired restriction covers this player for this scope or for the whole account. Fails OPEN: any error answers false.';


--
-- Name: ca_player_restrictions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_player_restrictions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    scope text NOT NULL,
    reason_code text NOT NULL,
    reason_note text,
    status text DEFAULT 'active'::text NOT NULL,
    applied_by uuid,
    applied_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    approval_id uuid,
    lifted_by uuid,
    lifted_at timestamp with time zone,
    lift_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ca_player_restrictions_expiry_after_start CHECK (((expires_at IS NULL) OR (expires_at > applied_at))),
    CONSTRAINT ca_player_restrictions_lift_is_attributed CHECK (((status <> 'lifted'::text) OR ((lifted_at IS NOT NULL) AND (lifted_by IS NOT NULL)))),
    CONSTRAINT ca_player_restrictions_other_needs_a_note CHECK (((reason_code <> 'other'::text) OR (COALESCE(btrim(reason_note), ''::text) <> ''::text))),
    CONSTRAINT ca_player_restrictions_reason_known CHECK ((reason_code = ANY (ARRAY['collusion_suspected'::text, 'chip_dumping_suspected'::text, 'multi_accounting'::text, 'bot_or_rta_suspected'::text, 'abuse_or_harassment'::text, 'payment_dispute'::text, 'kyc_incomplete'::text, 'responsible_gaming'::text, 'self_requested'::text, 'security_compromise'::text, 'terms_violation'::text, 'other'::text]))),
    CONSTRAINT ca_player_restrictions_scope_known CHECK ((scope = ANY (ARRAY['account'::text, 'cash'::text, 'tournaments'::text, 'transfers'::text, 'social'::text]))),
    CONSTRAINT ca_player_restrictions_status_known CHECK ((status = ANY (ARRAY['active'::text, 'lifted'::text, 'expired'::text])))
);


ALTER TABLE public.ca_player_restrictions OWNER TO postgres;

--
-- Name: TABLE ca_player_restrictions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_player_restrictions IS 'Operator restrictions on a player account. One active row per scope per player. Horses and humans alike. Nothing here refuses anything until ca_operator_policy.restrictions_enforced is true.';


--
-- Name: fn_ca_player_restriction_for(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_player_restriction_for(p_user_id uuid, p_scope text) RETURNS public.ca_player_restrictions
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select r.*
    from public.ca_player_restrictions r
   where r.user_id = p_user_id
     and r.status = 'active'
     and (r.expires_at is null or r.expires_at > now())
     and (r.scope = p_scope or r.scope = 'account')
   order by (r.scope = 'account') desc, r.applied_at asc
   limit 1;
$$;


ALTER FUNCTION public.fn_ca_player_restriction_for(p_user_id uuid, p_scope text) OWNER TO postgres;

--
-- Name: fn_ca_player_rg_set(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_player_rg_set(p_user_id uuid, p_patch jsonb, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_before  public.responsible_gaming_limits;
  v_after   public.responsible_gaming_limits;
  v_created boolean := false;
  v_loosens text[] := '{}';
  v_changed text[] := '{}';
  v_key     text;
  v_num     numeric;
  v_ts      timestamptz;
  v_old     text;
  v_new     text;
  -- The column's own default, mirrored here and asserted below. NOT 60:
  -- a longer interval is fewer reminders, which this function itself
  -- classifies as a loosening.
  c_default_interval constant int := 30;
begin
  if p_actor is null then
    return jsonb_build_object('ok', false, 'reason', 'actor_required');
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    return jsonb_build_object('ok', false, 'reason', 'patch_required');
  end if;

  select * into v_before
    from public.responsible_gaming_limits where user_id = p_user_id;
  if not found then
    v_created := true;
  end if;

  if p_patch ? 'reality_check_interval_minutes'
     and nullif(p_patch ->> 'reality_check_interval_minutes', '') is null then
    return jsonb_build_object('ok', false, 'reason', 'reality_check_not_nullable');
  end if;

  foreach v_key in array array[
    'daily_deposit_limit', 'weekly_deposit_limit', 'monthly_deposit_limit',
    'daily_loss_limit', 'session_time_limit_minutes',
    'reality_check_interval_minutes', 'self_excluded_until', 'cooling_off_until'
  ] loop
    if not (p_patch ? v_key) then
      continue;
    end if;
    v_new := nullif(p_patch ->> v_key, '');
    v_old := case when v_created then null else to_jsonb(v_before) ->> v_key end;

    if v_key in ('self_excluded_until', 'cooling_off_until') then
      if v_new is distinct from v_old
         and (v_new is null or v_old is null
              or v_new::timestamptz is distinct from v_old::timestamptz) then
        v_changed := array_append(v_changed, v_key);
      end if;
    elsif v_new is distinct from v_old
          and (v_new is null or v_old is null
               or v_new::numeric is distinct from v_old::numeric) then
      v_changed := array_append(v_changed, v_key);
    end if;
  end loop;

  if array_length(v_changed, 1) is null then
    return jsonb_build_object('ok', false, 'reason', 'patch_changes_nothing');
  end if;

  foreach v_key in array array[
    'daily_deposit_limit', 'weekly_deposit_limit', 'monthly_deposit_limit',
    'daily_loss_limit', 'session_time_limit_minutes'
  ] loop
    if p_patch ? v_key and not v_created then
      v_num := nullif(p_patch ->> v_key, '')::numeric;
      v_old := to_jsonb(v_before) ->> v_key;
      if v_num is null and v_old is not null then
        v_loosens := array_append(v_loosens, v_key || ':cleared');
      elsif v_num is not null and v_old is not null and v_num > v_old::numeric then
        v_loosens := array_append(v_loosens, v_key || ':raised');
      end if;
    end if;
  end loop;

  if p_patch ? 'reality_check_interval_minutes' and not v_created then
    v_num := nullif(p_patch ->> 'reality_check_interval_minutes', '')::numeric;
    if v_num is not null and v_num > v_before.reality_check_interval_minutes then
      v_loosens := array_append(v_loosens, 'reality_check_interval_minutes:lengthened');
    end if;
  end if;

  foreach v_key in array array['self_excluded_until', 'cooling_off_until'] loop
    if p_patch ? v_key and not v_created then
      v_ts := nullif(p_patch ->> v_key, '')::timestamptz;
      v_old := to_jsonb(v_before) ->> v_key;
      if v_ts is null and v_old is not null then
        v_loosens := array_append(v_loosens, v_key || ':cleared');
      elsif v_ts is not null and v_old is not null and v_ts < v_old::timestamptz then
        v_loosens := array_append(v_loosens, v_key || ':shortened');
      end if;
    end if;
  end loop;

  if array_length(v_loosens, 1) is not null
     and not v_created
     and now() < v_before.limit_increase_available_at then
    return jsonb_build_object(
      'ok', false,
      'reason', 'loosening_is_held',
      'held_until', v_before.limit_increase_available_at,
      'loosens', to_jsonb(v_loosens));
  end if;

  insert into public.responsible_gaming_limits as t (
    user_id, daily_deposit_limit, weekly_deposit_limit, monthly_deposit_limit,
    daily_loss_limit, session_time_limit_minutes, reality_check_interval_minutes,
    self_excluded_until, cooling_off_until, limit_increase_available_at, updated_at
  ) values (
    p_user_id,
    nullif(p_patch ->> 'daily_deposit_limit', '')::numeric,
    nullif(p_patch ->> 'weekly_deposit_limit', '')::numeric,
    nullif(p_patch ->> 'monthly_deposit_limit', '')::numeric,
    nullif(p_patch ->> 'daily_loss_limit', '')::numeric,
    nullif(p_patch ->> 'session_time_limit_minutes', '')::int,
    -- THE FIX. The column's default, not a number somebody liked.
    coalesce(nullif(p_patch ->> 'reality_check_interval_minutes', '')::int,
             c_default_interval),
    nullif(p_patch ->> 'self_excluded_until', '')::timestamptz,
    nullif(p_patch ->> 'cooling_off_until', '')::timestamptz,
    now() + interval '24 hours',
    now()
  )
  on conflict (user_id) do update set
    daily_deposit_limit = case when p_patch ? 'daily_deposit_limit'
      then nullif(p_patch ->> 'daily_deposit_limit', '')::numeric
      else t.daily_deposit_limit end,
    weekly_deposit_limit = case when p_patch ? 'weekly_deposit_limit'
      then nullif(p_patch ->> 'weekly_deposit_limit', '')::numeric
      else t.weekly_deposit_limit end,
    monthly_deposit_limit = case when p_patch ? 'monthly_deposit_limit'
      then nullif(p_patch ->> 'monthly_deposit_limit', '')::numeric
      else t.monthly_deposit_limit end,
    daily_loss_limit = case when p_patch ? 'daily_loss_limit'
      then nullif(p_patch ->> 'daily_loss_limit', '')::numeric
      else t.daily_loss_limit end,
    session_time_limit_minutes = case when p_patch ? 'session_time_limit_minutes'
      then nullif(p_patch ->> 'session_time_limit_minutes', '')::int
      else t.session_time_limit_minutes end,
    reality_check_interval_minutes = case when p_patch ? 'reality_check_interval_minutes'
      then nullif(p_patch ->> 'reality_check_interval_minutes', '')::int
      else t.reality_check_interval_minutes end,
    self_excluded_until = case when p_patch ? 'self_excluded_until'
      then nullif(p_patch ->> 'self_excluded_until', '')::timestamptz
      else t.self_excluded_until end,
    cooling_off_until = case when p_patch ? 'cooling_off_until'
      then nullif(p_patch ->> 'cooling_off_until', '')::timestamptz
      else t.cooling_off_until end,
    limit_increase_available_at = now() + interval '24 hours',
    updated_at = now()
  returning * into v_after;

  return jsonb_build_object('ok', true, 'limits', to_jsonb(v_after),
                            'before', case when v_created then null else to_jsonb(v_before) end,
                            'changed', to_jsonb(v_changed),
                            'created', v_created);
end;
$$;


ALTER FUNCTION public.fn_ca_player_rg_set(p_user_id uuid, p_patch jsonb, p_actor uuid) OWNER TO postgres;

--
-- Name: fn_ca_player_search(text, boolean, boolean, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_player_search(p_q text, p_include_horses boolean DEFAULT true, p_restricted boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_reveal_email boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_q     text := nullif(btrim(coalesce(p_q, '')), '');
  v_lim   int  := least(greatest(coalesce(p_limit, 25), 1), 200);
  v_off   int  := greatest(coalesce(p_offset, 0), 0);
  v_rows  jsonb;
  v_total bigint;
begin
  with matched as (
    select p.id, p.display_name, p.username, p.email, p.player_number,
           p.is_horse, p.created_at, p.last_seen, p.avatar_url,
           exists (
             select 1 from public.ca_player_restrictions r
              where r.user_id = p.id and r.status = 'active'
                and (r.expires_at is null or r.expires_at > now())
           ) as restricted
      from public.profiles p
     where
       (coalesce(p_include_horses, true) or not coalesce(p.is_horse, false))
       and (
         v_q is null
         or p.display_name ilike '%' || v_q || '%'
         or p.username     ilike '%' || v_q || '%'
         or p.email        ilike '%' || v_q || '%'
         or p.player_number ilike '%' || v_q || '%'
         or (length(v_q) >= 8 and p.id::text ilike v_q || '%')
       )
  ), filtered as (
    select * from matched
     where p_restricted is null or restricted = p_restricted
  )
  select
    coalesce(jsonb_agg(to_jsonb(x) - case when p_reveal_email then '' else 'email' end
                       order by x.restricted desc, x.display_name asc, x.id), '[]'::jsonb),
    (select count(*) from filtered)
    into v_rows, v_total
  from (select * from filtered
         order by restricted desc, display_name asc, id
         limit v_lim offset v_off) x;

  return jsonb_build_object(
    'ok', true,
    'rows', v_rows,
    'total', v_total,
    'limit', v_lim,
    'offset', v_off,
    'includeHorses', coalesce(p_include_horses, true),
    'emailRevealed', coalesce(p_reveal_email, false));
end;
$$;


ALTER FUNCTION public.fn_ca_player_search(p_q text, p_include_horses boolean, p_restricted boolean, p_limit integer, p_offset integer, p_reveal_email boolean) OWNER TO postgres;

--
-- Name: fn_ca_player_tag_set(uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_player_tag_set(p_user_id uuid, p_tag text, p_actor uuid, p_remove boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_tag text := lower(btrim(coalesce(p_tag, '')));
  v_had boolean;
begin
  if p_actor is null then
    return jsonb_build_object('ok', false, 'reason', 'actor_required');
  end if;
  if v_tag !~ '^[a-z0-9][a-z0-9-]{1,31}$' then
    return jsonb_build_object('ok', false, 'reason', 'bad_tag');
  end if;

  select exists (select 1 from public.ca_operator_player_tags
                  where user_id = p_user_id and tag = v_tag) into v_had;

  if coalesce(p_remove, false) then
    delete from public.ca_operator_player_tags
     where user_id = p_user_id and tag = v_tag;
  else
    insert into public.ca_operator_player_tags (user_id, tag, added_by)
    values (p_user_id, v_tag, p_actor)
    on conflict (user_id, tag) do nothing;
  end if;

  return jsonb_build_object('ok', true, 'tag', v_tag,
                            'removed', coalesce(p_remove, false),
                            'was_present', v_had);
end;
$_$;


ALTER FUNCTION public.fn_ca_player_tag_set(p_user_id uuid, p_tag text, p_actor uuid, p_remove boolean) OWNER TO postgres;

--
-- Name: fn_ca_post_correction(text, uuid, text, uuid, numeric, text, uuid, bigint, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_post_correction(p_from_type text, p_from_entity uuid, p_to_type text, p_to_entity uuid, p_amount numeric, p_reason text, p_incident_id uuid DEFAULT NULL::uuid, p_write_failure_id bigint DEFAULT NULL::bigint, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mgmt boolean := false;
  v_key text;
  v_id uuid;
  v_existing uuid;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ca_incident_recipients r WHERE r.user_id = v_uid AND r.active
      UNION ALL
      SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.role IN ('admin','god')
    ) INTO v_mgmt;
    IF NOT v_mgmt THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'management_only');
    END IF;
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive_cents');
  END IF;
  IF COALESCE(btrim(p_reason), '') = '' OR length(p_reason) < 20 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'a_correction_needs_a_real_reason');
  END IF;

  -- THE LINKAGE RULE: no correction without a live reference to what it fixes.
  IF p_incident_id IS NULL AND p_write_failure_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'linkage_required_incident_or_write_failure');
  END IF;
  IF p_incident_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.ca_drift_incidents WHERE id = p_incident_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'incident_not_found');
  END IF;
  IF p_write_failure_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.ca_ledger_write_failures WHERE id = p_write_failure_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'write_failure_not_found');
  END IF;

  v_key := 'correction:' || COALESCE('lwf:' || p_write_failure_id::text,
                                     'inc:' || p_incident_id::text);

  -- replay-safe: the same linkage posts at most one correction
  SELECT id INTO v_existing FROM public.chip_ledger WHERE idempotency_key = v_key;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'ledger_id', v_existing);
  END IF;

  INSERT INTO public.chip_ledger
    (performed_by, from_type, from_entity_id, to_type, to_entity_id,
     amount, category, club_id, union_id, description, idempotency_key, metadata)
  VALUES
    (COALESCE(v_uid, '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
     p_from_type, p_from_entity, p_to_type, p_to_entity,
     p_amount, 'correction', p_club_id, p_union_id,
     left(p_reason, 900), v_key,
     COALESCE(p_metadata, '{}'::jsonb)
       || jsonb_build_object('incident_id', p_incident_id,
                             'write_failure_id', p_write_failure_id,
                             'posted_via', 'fn_ca_post_correction'))
  RETURNING id INTO v_id;

  IF p_incident_id IS NOT NULL THEN
    UPDATE public.ca_drift_incidents
       SET correction_ref = COALESCE(correction_ref, 'chip_ledger ' || v_id::text)
     WHERE id = p_incident_id;
    INSERT INTO public.ca_incident_events (incident_id, kind, actor, detail)
    VALUES (p_incident_id, 'repair_action', v_uid,
            jsonb_build_object('correction_posted', v_id, 'amount', p_amount,
                               'from', p_from_type, 'to', p_to_type));
  END IF;

  RETURN jsonb_build_object('ok', true, 'replayed', false, 'ledger_id', v_id);
END $$;


ALTER FUNCTION public.fn_ca_post_correction(p_from_type text, p_from_entity uuid, p_to_type text, p_to_entity uuid, p_amount numeric, p_reason text, p_incident_id uuid, p_write_failure_id bigint, p_club_id uuid, p_union_id uuid, p_metadata jsonb) OWNER TO postgres;

--
-- Name: fn_ca_post_leg(text, text, uuid, text, uuid, numeric, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_post_leg(p_category text, p_from_type text, p_from_entity uuid, p_to_type text, p_to_entity uuid, p_amount numeric, p_club_id uuid, p_idempotency_key text, p_description text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_st text; v_msg text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN false;
  END IF;
  BEGIN
    INSERT INTO public.chip_ledger
      (performed_by, from_type, from_entity_id, to_type, to_entity_id,
       amount, category, club_id, description, idempotency_key)
    VALUES (COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
            p_from_type, p_from_entity, p_to_type, p_to_entity,
            round(p_amount, 2), p_category, p_club_id, p_description, p_idempotency_key);
    RETURN true;
  EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;

END $$;


ALTER FUNCTION public.fn_ca_post_leg(p_category text, p_from_type text, p_from_entity uuid, p_to_type text, p_to_entity uuid, p_amount numeric, p_club_id uuid, p_idempotency_key text, p_description text) OWNER TO postgres;

--
-- Name: fn_ca_prize_overpay_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_prize_overpay_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT count(*)::int FROM public.fn_ca_prize_overpay_unexplained('48 hours'::interval);
$$;


ALTER FUNCTION public.fn_ca_prize_overpay_count() OWNER TO postgres;

--
-- Name: fn_ca_prize_overpay_unexplained(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_prize_overpay_unexplained(p_window interval DEFAULT '10 days'::interval) RETURNS TABLE(tournament_id uuid, name text, ended_at timestamp with time zone, prize_pool numeric, guaranteed_prize numeric, paid numeric, excess numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH p AS (
    SELECT t.id, t.name, t.ended_at, t.tournament_type,
           round(COALESCE(t.prize_pool, 0), 2)       AS pool,
           round(COALESCE(t.guaranteed_prize, 0), 2) AS guar,
           COALESCE(t.satellite_seats, 0)            AS seats,
           COALESCE((SELECT round(sum(w.amount), 2)
                       FROM public.wallet_transactions w
                      WHERE w.related_entity_id = t.id
                        AND w.type = 'credit'
                        -- bounty money is funded by the bounty pool, not the
                        -- prize pool, and is reconciled by its own check
                        AND COALESCE(w.category, '') <> 'bounty'), 0) AS paid
      FROM public.tournaments t
     WHERE t.status = 'COMPLETED'
       AND COALESCE(t.prize_pool, 0) > 0
       AND t.ended_at > now() - p_window
  )
  SELECT id, name, ended_at, pool, guar, paid, round(paid - GREATEST(pool, guar), 2)
    FROM p
   WHERE paid > GREATEST(pool, guar) + 0.01
     AND seats = 0                       -- a seat is not a share of the pool
     AND tournament_type <> 'SPIN'       -- a Spin pays a club-funded multiple
   ORDER BY paid - GREATEST(pool, guar) DESC;
$$;


ALTER FUNCTION public.fn_ca_prize_overpay_unexplained(p_window interval) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_prize_overpay_unexplained(p_window interval); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_prize_overpay_unexplained(p_window interval) IS 'Tournaments that paid out more than the pool AND more than any guarantee, excluding satellites (fixed seat value) and Spins (club-funded multiplier). These are the overpayments nothing accounts for. Do NOT filter Spins on spin_type: it is the string standard on every row in the table, MTTs included, and using it hides real discrepancies.';


--
-- Name: fn_ca_process_hand_post_commit_obligations(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_process_hand_post_commit_obligations(p_hand_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_table_id uuid;
  v_commit public.hand_atomic_commits%ROWTYPE;
  v_payload jsonb;
  v_hash text;
  v_rake jsonb;
  v_bbj jsonb;
  v_pending jsonb;
  v_item jsonb;
  v_rake_result record;
  v_promo_result jsonb;
  v_pool_id uuid;
  v_union_id uuid;
  v_contribution_id uuid;
  v_insurance_id uuid;
  v_addon_result record;
  v_time_bank_count integer := 0;
  v_promo_count integer := 0;
  v_insurance_count integer := 0;
  v_addon_count integer := 0;
  v_result jsonb;
BEGIN
  /* Read only the scope, then take the per-table mutex before the row lock.
     This gives every hand at one table the same lock order. */
  SELECT c.table_id INTO v_table_id
    FROM public.hand_atomic_commits c
   WHERE c.hand_id = p_hand_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found', 'hand_id', p_hand_id);
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('hand-post-commit:' || v_table_id::text, 0)
  );

  SELECT c.* INTO v_commit
    FROM public.hand_atomic_commits c
   WHERE c.hand_id = p_hand_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found', 'hand_id', p_hand_id);
  END IF;
  IF v_commit.post_commit_payload IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'legacy_no_obligations',
      'hand_id', p_hand_id
    );
  END IF;
  IF v_commit.post_commit_completed_at IS NOT NULL THEN
    RETURN COALESCE(v_commit.post_commit_result, '{}'::jsonb) || jsonb_build_object(
      'ok', true,
      'already_completed', true,
      'hand_id', p_hand_id,
      'completed_at', v_commit.post_commit_completed_at
    );
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.hand_atomic_commits earlier
     WHERE earlier.table_id = v_commit.table_id
       AND earlier.hand_number < v_commit.hand_number
       AND earlier.post_commit_payload IS NOT NULL
       AND earlier.post_commit_completed_at IS NULL
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'predecessor_pending',
      'hand_id', p_hand_id
    );
  END IF;

  v_payload := v_commit.post_commit_payload;
  v_hash := encode(
    extensions.digest(convert_to(v_payload::text, 'UTF8'), 'sha256'),
    'hex'
  );
  IF v_commit.post_commit_payload_hash IS DISTINCT FROM v_hash THEN
    RAISE EXCEPTION 'post-commit obligation payload hash mismatch for hand %', p_hand_id;
  END IF;

  /* Time banks were stamped inside the accepted-hand transaction while the
     exact lease and seat locks were held. A delayed consumer must never apply
     those older values again after hand N+1, a table break, or a seat move. */
  IF jsonb_typeof(v_payload->'time_banks') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'invalid time-bank audit payload for hand %', p_hand_id;
  END IF;
  v_time_bank_count := jsonb_array_length(v_payload->'time_banks');

  v_rake := v_payload->'rake';
  IF v_rake IS NOT NULL AND jsonb_typeof(v_rake) <> 'null' THEN
    IF jsonb_typeof(v_rake) <> 'object'
       OR COALESCE((v_rake->>'amount')::numeric, 0) <= 0
       OR (v_rake->>'club_id') !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'invalid rake obligation for hand %', p_hand_id;
    END IF;
    IF v_commit.hand_number > 2147483647 THEN
      RAISE EXCEPTION 'rake hand number exceeds downstream integer contract: %',
        v_commit.hand_number;
    END IF;

    SELECT * INTO v_rake_result
      FROM public.atomic_distribute_rake(
        v_commit.table_id,
        (v_rake->>'club_id')::uuid,
        v_commit.hand_id,
        v_commit.hand_number::integer,
        (v_rake->>'amount')::numeric,
        COALESCE((v_rake->>'bbj')::numeric, 0),
        NULLIF(v_rake->>'pot', '')::numeric,
        NULLIF(v_rake->>'num_players', '')::integer,
        COALESCE(v_rake->'contributions', '{}'::jsonb),
        NULLIF(v_rake->>'tournament_id', '')::uuid,
        COALESCE(v_rake->'returned_uncalled', '{}'::jsonb),
        COALESCE(NULLIF(v_rake->>'method', ''), 'WEIGHTED_CONTRIBUTED')
      );
    IF NOT FOUND OR NOT (
      COALESCE(v_rake_result.applied, false)
      OR COALESCE(v_rake_result.already_processed, false)
      OR v_rake_result.rake_record_id IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'rake obligation did not produce a receipt for hand %', p_hand_id;
    END IF;
  END IF;

  v_bbj := v_payload->'bbj_contribution';
  IF v_bbj IS NOT NULL AND jsonb_typeof(v_bbj) <> 'null' THEN
    IF jsonb_typeof(v_bbj) <> 'object'
       OR COALESCE((v_bbj->>'amount')::numeric, 0) <= 0
       OR (v_bbj->>'club_id') !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'invalid BBJ contribution obligation for hand %', p_hand_id;
    END IF;

    SELECT c.union_id INTO v_union_id
      FROM public.clubs c
     WHERE c.id = (v_bbj->>'club_id')::uuid;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'BBJ obligation club not found for hand %', p_hand_id;
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(
      'bbj-pool:' || COALESCE(v_union_id::text, 'club:' || (v_bbj->>'club_id')),
      0
    ));
    IF v_union_id IS NULL THEN
      SELECT p.id INTO v_pool_id
        FROM public.bbj_pools p
       WHERE p.club_id = (v_bbj->>'club_id')::uuid
         AND p.status = 'active'
       ORDER BY p.created_at, p.id
       LIMIT 1
       FOR UPDATE;
    ELSE
      SELECT p.id INTO v_pool_id
        FROM public.bbj_pools p
       WHERE p.union_id = v_union_id
         AND p.status = 'active'
       ORDER BY p.created_at, p.id
       LIMIT 1
       FOR UPDATE;
    END IF;

    IF v_pool_id IS NULL THEN
      IF v_union_id IS NULL THEN
        INSERT INTO public.bbj_pools(
          club_id, main_balance, backup_balance, promo_balance, status
        ) VALUES (
          (v_bbj->>'club_id')::uuid, 0, 0, 0, 'active'
        ) RETURNING id INTO v_pool_id;
      ELSE
        INSERT INTO public.bbj_pools(
          union_id, main_balance, backup_balance, promo_balance, status
        ) VALUES (
          v_union_id, 0, 0, 0, 'active'
        ) RETURNING id INTO v_pool_id;
      END IF;
    END IF;

    SELECT r.id INTO v_contribution_id
      FROM public.bbj_record_contribution(
        v_pool_id,
        v_commit.hand_id,
        v_commit.table_id,
        (v_bbj->>'amount')::numeric,
        0, 0, 0,
        COALESCE((v_bbj->>'big_blind')::numeric, 2),
        v_commit.hand_number::integer,
        (v_bbj->>'club_id')::uuid
      ) r;
    IF v_contribution_id IS NULL THEN
      RAISE EXCEPTION 'BBJ contribution produced no receipt for hand %', p_hand_id;
    END IF;
  END IF;

  FOR v_item IN
    SELECT value
      FROM jsonb_array_elements(v_payload->'promo_playthrough')
     ORDER BY value->>'user_id'
  LOOP
    IF (v_item->>'club_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR (v_item->>'user_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE((v_item->>'wagered')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION 'invalid promo obligation for hand %', p_hand_id;
    END IF;
    v_promo_result := public.promo_apply_playthrough(
      (v_item->>'club_id')::uuid,
      (v_item->>'user_id')::uuid,
      (v_item->>'wagered')::numeric
    );
    IF v_promo_result->>'reason' IN ('engine_only', 'no_wager') THEN
      RAISE EXCEPTION 'promo obligation refused for hand %: %',
        p_hand_id, v_promo_result;
    END IF;
    v_promo_count := v_promo_count + 1;
  END LOOP;

  FOR v_item IN
    SELECT value
      FROM jsonb_array_elements(v_payload->'insurance')
     ORDER BY value->>'player_id', value->>'kind'
  LOOP
    IF (v_item->>'club_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR (v_item->>'player_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'invalid insurance obligation for hand %', p_hand_id;
    END IF;
    SELECT r.id INTO v_insurance_id
      FROM public.record_insurance_transaction(
        v_commit.table_id,
        (v_item->>'club_id')::uuid,
        v_commit.hand_number::integer,
        (v_item->>'player_id')::uuid,
        COALESCE((v_item->>'equity_percent')::numeric, 0),
        COALESCE((v_item->>'premium')::numeric, 0),
        COALESCE((v_item->>'insured_amount')::numeric, 0),
        COALESCE((v_item->>'payout')::numeric, 0),
        COALESCE((v_item->>'player_won')::boolean, false),
        COALESCE(NULLIF(v_item->>'kind', ''), 'insurance')::varchar
      ) r;
    IF v_insurance_id IS NULL THEN
      RAISE EXCEPTION 'insurance obligation produced no receipt for hand %', p_hand_id;
    END IF;
    v_insurance_count := v_insurance_count + 1;
  END LOOP;

  v_pending := v_payload->'pending_addons';
  IF v_pending IS NOT NULL AND jsonb_typeof(v_pending) <> 'null' THEN
    IF jsonb_typeof(v_pending) <> 'object'
       OR COALESCE((v_pending->>'enabled')::boolean, false) IS NOT TRUE
       OR jsonb_typeof(v_pending->'ids') IS DISTINCT FROM 'array'
       OR NULLIF(v_pending->>'max_buy_in', '') IS NULL
       OR (v_pending->>'max_buy_in')::numeric <= 0 THEN
      RAISE EXCEPTION 'invalid pending-add-on obligation for hand %', p_hand_id;
    END IF;
    FOR v_item IN
      SELECT value
        FROM jsonb_array_elements(v_pending->'ids')
       ORDER BY value #>> '{}'
    LOOP
      IF (v_item #>> '{}') !~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN
        RAISE EXCEPTION 'pending add-on % is not frozen for table % (hand %)',
          v_item, v_commit.table_id, p_hand_id;
      END IF;
      PERFORM 1
        FROM public.table_pending_addons a
       WHERE a.id = (v_item #>> '{}')::uuid
         AND a.table_id = v_commit.table_id
         AND a.resolved_at IS NULL
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'pending add-on % is not unresolved for table % (hand %)',
          v_item, v_commit.table_id, p_hand_id;
      END IF;
      SELECT * INTO v_addon_result
        FROM public.resolve_pending_addon(
          (v_item #>> '{}')::uuid,
          NULLIF(v_pending->>'max_buy_in', '')::numeric
        );
      IF NOT FOUND THEN
        RAISE EXCEPTION 'pending add-on % produced no receipt for hand %',
          v_item, p_hand_id;
      END IF;
      v_addon_count := v_addon_count + 1;
    END LOOP;
  END IF;

  v_result := jsonb_build_object(
    'ok', true,
    'already_completed', false,
    'hand_id', p_hand_id,
    'hand_number', v_commit.hand_number,
    'time_banks', v_time_bank_count,
    'rake', v_rake IS NOT NULL AND jsonb_typeof(v_rake) <> 'null',
    'bbj_contribution', v_bbj IS NOT NULL AND jsonb_typeof(v_bbj) <> 'null',
    'promo_playthrough', v_promo_count,
    'insurance', v_insurance_count,
    'pending_addons', v_addon_count
  );

  UPDATE public.hand_atomic_commits c
     SET post_commit_completed_at = clock_timestamp(),
         post_commit_result = v_result
   WHERE c.hand_id = p_hand_id
     AND c.post_commit_completed_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'post-commit completion receipt was lost for hand %', p_hand_id;
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION public.fn_ca_process_hand_post_commit_obligations(p_hand_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_propose_manual_adjustment(text, numeric, text, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_propose_manual_adjustment(p_reason text, p_amount numeric, p_target_kind text, p_target_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_actor uuid DEFAULT NULL::uuid, p_actor_label text DEFAULT NULL::text, p_asset text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := COALESCE(p_actor, auth.uid());
  v_label text := COALESCE(NULLIF(btrim(p_actor_label), ''),
                           NULLIF(current_setting('application_name', true), ''),
                           session_user::text);
  v_kind  text := lower(btrim(COALESCE(p_target_kind, '')));
  v_asset text;
  v_row   public.ca_manual_adjustments%ROWTYPE;
BEGIN
  IF NOT public.fn_ca_caller_is_management() THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'not_management');
  END IF;
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'actor_required');
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 20 THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'reason_too_short');
  END IF;
  IF p_amount IS NULL OR round(p_amount, 2) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'amount_required');
  END IF;
  IF v_kind NOT IN
     ('player_wallet','promo_wallet','club_treasury','union_bank','union_wallet','agent_wallet',
      'club_wallet','bbj_pool','spin_reserve','prize_liability','bounty_liability',
      'diamond_wallet','diamond_house') THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'unknown_target_kind');
  END IF;

  -- The target kind decides the asset. p_asset is accepted so a caller can say
  -- it out loud, and it is compared, never trusted.
  v_asset := CASE WHEN v_kind IN ('diamond_wallet','diamond_house') THEN 'diamonds' ELSE 'chips' END;
  IF NULLIF(btrim(COALESCE(p_asset, '')), '') IS NOT NULL
     AND lower(btrim(p_asset)) <> v_asset THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'asset_does_not_match_target_kind',
      'asset_for_target_kind', v_asset, 'asset_supplied', lower(btrim(p_asset)));
  END IF;
  IF v_asset = 'diamonds' AND round(p_amount, 2) <> round(p_amount, 0) THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'diamonds_are_whole_numbers');
  END IF;

  INSERT INTO public.ca_manual_adjustments
    (actor, actor_label, reason, amount, target_kind, target_id, tournament_id, asset)
  VALUES (v_actor, v_label, btrim(p_reason), round(p_amount, 2), v_kind, p_target_id,
          p_tournament_id, v_asset)
  RETURNING * INTO v_row;

  PERFORM public.fn_raise_server_financial_alert(
    'info', 'ca_manual_adjustments',
    format('Manual adjustment PROPOSED by %s: %s %s to %s (%s)',
           v_label, v_row.amount, v_asset, v_kind, btrim(p_reason)),
    jsonb_build_object('adjustment_id', v_row.id, 'actor', v_actor, 'actor_label', v_label,
                       'amount', v_row.amount, 'asset', v_asset, 'target_kind', v_kind,
                       'target_id', p_target_id, 'tournament_id', p_tournament_id),
    'adj:' || v_row.id::text);

  RETURN jsonb_build_object('ok', true, 'adjustment_id', v_row.id, 'status', v_row.status,
    'actor', v_actor, 'amount', v_row.amount, 'asset', v_asset, 'target_kind', v_kind);
END $$;


ALTER FUNCTION public.fn_ca_propose_manual_adjustment(p_reason text, p_amount numeric, p_target_kind text, p_target_id uuid, p_tournament_id uuid, p_actor uuid, p_actor_label text, p_asset text) OWNER TO postgres;

--
-- Name: fn_ca_prune_deploy_run_markers(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_prune_deploy_run_markers() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH d AS (DELETE FROM public.ca_engine_deploy_runs_started WHERE started_at < now() - interval '14 days' RETURNING 1)
  SELECT count(*)::int FROM d;
$$;


ALTER FUNCTION public.fn_ca_prune_deploy_run_markers() OWNER TO postgres;

--
-- Name: fn_ca_quick_reconcile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_quick_reconcile() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r RECORD; n int := 0; v_frozen numeric; v_now numeric; v_left numeric;
BEGIN
  -- 3a. Negative balances (credit-line members are checked against their BOUND)
  FOR r IN
    SELECT 'player_wallet' AS pool, m.user_id AS entity_id, m.club_id, m.chip_balance AS amt,
           false AS ok
      FROM club_members m
     WHERE COALESCE(m.chip_balance,0) < 0
       AND COALESCE(m.chip_balance,0) < -COALESCE(m.credit_limit,0)
    UNION ALL
    SELECT 'club_treasury', c.id, c.id, c.chip_treasury, false FROM clubs c
     WHERE COALESCE(c.chip_treasury,0) < 0
    UNION ALL
    SELECT 'union_wallet', w.union_id, NULL, LEAST(w.chip_balance, w.rake_wallet, w.bbj_wallet,
           w.promo_wallet, w.insurance_wallet, COALESCE(w.spin_reserve_wallet,0)), false
      FROM union_wallets w
     WHERE LEAST(w.chip_balance, w.rake_wallet, w.bbj_wallet, w.promo_wallet,
                 w.insurance_wallet, COALESCE(w.spin_reserve_wallet,0)) < 0
    UNION ALL
    SELECT 'agent_wallet', a.user_id, a.club_id,
           LEAST(COALESCE(a.agent_wallet_balance,0), COALESCE(a.promo_wallet_balance,0)), false
      FROM agents a
     WHERE LEAST(COALESCE(a.agent_wallet_balance,0), COALESCE(a.promo_wallet_balance,0)) < 0
    UNION ALL
    SELECT 'bbj_pool', b.id, b.club_id,
           LEAST(b.main_balance, b.backup_balance, b.promo_balance), false
      FROM bbj_pools b
     WHERE LEAST(b.main_balance, b.backup_balance, b.promo_balance) < 0
    LIMIT 50
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_quick_reconcile:negative_balance',
      CASE WHEN r.pool = 'club_treasury' THEN 'treasury_error'
           WHEN r.pool = 'player_wallet' THEN 'credit_line_error'
           ELSE 'ledger_imbalance' END,
      CASE WHEN r.pool = 'club_treasury' THEN 'warning' ELSE 'critical' END,
      'qr:neg:' || r.pool || ':' || COALESCE(r.entity_id::text,'-') || ':' || CURRENT_DATE::text,
      abs(r.amt), 0, r.amt, 'ledger', r.pool, r.entity_id, r.club_id,
      NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      CASE WHEN r.pool = 'player_wallet'
           THEN 'player balance below the authorized credit-line bound'
           ELSE 'unauthorized negative balance in ' || r.pool END,
      NULL, '{}'::jsonb);
    n := n + 1;
  END LOOP;

  -- 3b. Frozen pool must not move
  SELECT frozen_total INTO v_frozen
    FROM public.ca_frozen_pool_baseline WHERE pool = 'public.wallets';
  -- The frozen pool is the PRE-FREEZE rows (verified: the 690 rows created
  -- before 2026-08-22 sum to the baseline exactly). Post-freeze rows belong
  -- to certification/test accounts whose harness chips cycle through the
  -- no-club fallback and are deleted by the certification cleanup - they are
  -- not the stranded pool and must not page anyone.
  SELECT COALESCE(SUM(balance), 0) INTO v_now FROM public.wallets
   WHERE created_at < '2026-08-22';
  -- 2026-09-02: a pre-freeze row can also LEAVE, because public.wallets
  -- cascades from profiles and auth.users and 188 pre-freeze rows belong to
  -- certification accounts that are torn down routinely. A deleted row is not
  -- a write, so add recorded departures back before comparing: an
  -- attributable teardown nets to zero, an unrecorded change still pages.
  SELECT COALESCE(SUM(deleted_balance), 0) INTO v_left
    FROM public.ca_frozen_pool_deletions WHERE pool = 'public.wallets';
  v_now := v_now + COALESCE(v_left, 0);
  IF v_frozen IS NOT NULL AND v_now <> v_frozen THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_quick_reconcile:frozen_pool', 'unauthorized_adjustment', 'critical',
      'qr:frozen_wallets:' || CURRENT_DATE::text,
      v_now - v_frozen, v_frozen, v_now, 'ledger', 'frozen_wallets_pool',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'the dead public.wallets pool changed by an amount no recorded deletion explains - either a money path wrote to it, or a row left without the recording trigger firing',
      NULL, '{}'::jsonb);
    n := n + 1;
  END IF;

  -- 3c. Settlements stuck in flight (> 5 minutes)
  FOR r IN
    SELECT table_id, hand_id, first_attempt_at
      FROM settlement_idempotency_keys
     WHERE status = 'in_flight' AND last_attempt_at < now() - interval '5 minutes'
     LIMIT 20
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_quick_reconcile:settlement_stuck', 'settlement_error', 'critical',
      'qr:stuck:' || r.table_id::text || ':' || COALESCE(r.hand_id::text,'-'),
      0, NULL, NULL, 'settlement', 'settlement_idempotency_keys', r.hand_id,
      NULL, NULL, r.table_id, NULL, r.hand_id,
      'hand:' || r.table_id::text, NULL, NULL,
      'settlement in_flight for more than 5 minutes (crashed mid-settlement?)',
      NULL, jsonb_build_object('first_attempt_at', r.first_attempt_at));
    n := n + 1;
  END LOOP;

  -- 3d. Union PnL settlements stuck in_progress (> 10 minutes) - the
  -- half-collected/half-paid trap the audit flagged.
  FOR r IN
    SELECT id, union_id, period_start
      FROM union_pnl_settlements
     WHERE status = 'in_progress'
       AND COALESCE(settled_at, period_end, now() - interval '1 day') < now() - interval '10 minutes'
     LIMIT 10
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_quick_reconcile:union_pnl_stuck', 'settlement_error', 'critical',
      'qr:pnl:' || r.id::text,
      0, NULL, NULL, 'settlement', 'union_pnl_settlements', r.id,
      NULL, r.union_id, NULL, NULL, NULL,
      'union_pnl:' || r.id::text, NULL, NULL,
      'union PnL settlement stuck in_progress - money may be half-collected/half-paid; resume or reconcile manually',
      NULL, jsonb_build_object('period_start', r.period_start));
    n := n + 1;
  END LOOP;

  -- 3e. Fresh unaccounted cash seat exits
  FOR r IN
    SELECT * FROM public.fn_unaccounted_seat_exits('30 minutes'::interval, '10 minutes'::interval)
    LIMIT 20
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_quick_reconcile:seat_exit', 'missing_payment', 'critical',
      'qr:seatexit:' || r.exit_id::text,
      -r.stack, r.stack, 0, 'ledger', 'seat_stack_exit', r.user_id,
      r.club_id, NULL, r.table_id, NULL, NULL, NULL, NULL, NULL,
      'seat exited with ' || r.stack || ' chips and no matching wallet credit',
      false, jsonb_build_object('exit_id', r.exit_id, 'exit_kind', r.exit_kind));
    n := n + 1;
  END LOOP;

  -- 3f. Ledger write failures
  FOR r IN
    SELECT * FROM public.ca_ledger_write_failures f
     WHERE f.occurred_at > now() - interval '10 minutes'
        AND public.fn_ca_is_midway_scope(NULL, f.club_id, NULL, NULL, '{}'::jsonb)
        AND NOT (
          f.sqlstate = '23505'
          AND f.message LIKE '%ux_chip_ledger_idempotency_key%'
          AND EXISTS (
            SELECT 1 FROM public.chip_ledger l
             WHERE l.club_id = f.club_id
               AND l.idempotency_key = 'club-opening-grant:' || f.club_id::text
               AND l.category = 'mint' AND l.from_type = 'system_mint'
               AND l.to_type = 'club_treasury' AND l.to_entity_id = f.club_id
               AND l.amount = 100000 AND l.status = 'posted'
          )
        )
     LIMIT 20
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_quick_reconcile:ledger_write_failure', 'ledger_imbalance', 'critical',
      'qr:lwf:' || r.id::text,
      COALESCE(r.delta,0), NULL, NULL, 'ledger', 'ca_ledger_write_failures', r.user_id,
      r.club_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'a balance moved but its ledger row could not be written: ' || COALESCE(r.message,''),
      false, jsonb_build_object('sqlstate', r.sqlstate));
    n := n + 1;
  END LOOP;

  -- 3g. Unclassified (suspense) flow - info-severity daily rollup: it is a
  -- category-migration metric, not a discrepancy; the dashboard shows it.
  PERFORM 1 FROM public.chip_ledger
   WHERE (from_type = 'settlement_suspense' OR to_type = 'settlement_suspense')
     AND created_at > GREATEST(CURRENT_DATE::timestamptz, '2026-09-01 00:17:00+00'::timestamptz) LIMIT 1;
  IF FOUND THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_quick_reconcile:suspense_flow', 'unknown', 'info',
      'qr:suspense:' || CURRENT_DATE::text,
      (SELECT COALESCE(sum(amount),0) FROM public.chip_ledger
        WHERE (from_type='settlement_suspense' OR to_type='settlement_suspense')
          AND created_at > GREATEST(CURRENT_DATE::timestamptz, '2026-09-01 00:17:00+00'::timestamptz)),
      NULL, NULL, 'ledger', 'settlement_suspense', NULL, NULL, NULL, NULL, NULL,
      NULL, NULL, NULL, NULL,
      'balance movements posted without a declared counterparty today (category-migration phase)',
      true, '{}'::jsonb);
  END IF;

  RETURN n;
END $$;


ALTER FUNCTION public.fn_ca_quick_reconcile() OWNER TO postgres;

--
-- Name: fn_ca_raise_drift_incident(text, text, text, text, numeric, numeric, numeric, text, text, uuid, uuid, uuid, uuid, uuid, uuid, text, uuid[], uuid[], text, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_raise_drift_incident(p_source text, p_classification text, p_severity text, p_dedupe_key text, p_discrepancy numeric DEFAULT NULL::numeric, p_expected numeric DEFAULT NULL::numeric, p_actual numeric DEFAULT NULL::numeric, p_layer text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_settlement_id text DEFAULT NULL::text, p_wallet_ids uuid[] DEFAULT NULL::uuid[], p_transaction_ids uuid[] DEFAULT NULL::uuid[], p_suspected_cause text DEFAULT NULL::text, p_ledger_balanced boolean DEFAULT NULL::boolean, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_class text := p_classification;
  v_sev   text := lower(COALESCE(p_severity,'critical'));
  v_stable text;
BEGIN
  IF NOT public.fn_ca_is_midway_scope(
    p_union_id, p_club_id, p_table_id, p_tournament_id, p_metadata
  ) THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.ca_detector_registry r WHERE r.source = p_source AND r.status = 'retired') THEN
    RETURN NULL;
  END IF;
  INSERT INTO public.ca_detector_registry (source, owner, sla_hours, note)
  VALUES (p_source, 'unassigned', 24, 'auto-registered on first sight (Phase 6 gate); give it an owner')
  ON CONFLICT (source) DO NOTHING;

  IF v_class IS NULL OR v_class NOT IN (
      'ledger_imbalance','settlement_error','duplicate_payment','missing_payment',
      'projection_delay','cache_mismatch','reporting_mismatch','delayed_event',
      'duplicate_event','rounding_error','incorrect_rake','incorrect_weighted_rake',
      'incorrect_rakeback','bbj_error','treasury_error','credit_line_error',
      'cross_club_posting','cross_union_posting','unauthorized_adjustment',
      'historical_migration','unknown') THEN
    v_class := 'unknown';
  END IF;
  IF v_sev NOT IN ('critical','warning','info') THEN v_sev := 'critical'; END IF;

  UPDATE public.ca_drift_incidents
     SET occurrences  = occurrences + 1,
         last_seen_at = now(),
         discrepancy_amount = COALESCE(p_discrepancy, discrepancy_amount),
         actual_amount      = COALESCE(p_actual, actual_amount),
         expected_amount    = COALESCE(p_expected, expected_amount)
   WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'
   RETURNING id INTO v_id;

  IF v_id IS NOT NULL THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (v_id, 'recurred', jsonb_build_object('source', p_source,
            'discrepancy', p_discrepancy));
    RETURN v_id;
  END IF;

  /* ONE STANDING CONDITION IS ONE INCIDENT (2026-09-06).
     A sweep that puts the date in its key defeats the exact-match fold above
     and files a fresh critical every run: sweep:fn_bbj_promo_bank_check:
     2026-09-02 .. -09-06, five rows, all 6705.21, one condition.

     The amount is what makes this safe. `diamond-unexplained:2026-09-02-18`
     is an hourly bucket where each bucket is a DIFFERENT event, so folding on
     the key alone would hide real ones. A standing condition re-reports the
     same number; a new event reports a new one. Same detector, same key
     without its period label, same discrepancy - then and only then is it the
     same finding said twice. */
  v_stable := public.fn_ca_stable_dedupe_key(p_dedupe_key);
  IF v_stable <> p_dedupe_key THEN
    UPDATE public.ca_drift_incidents
       SET occurrences  = occurrences + 1,
           last_seen_at = now()
     WHERE status <> 'resolved'
       AND source = p_source
       AND public.fn_ca_stable_dedupe_key(dedupe_key) = v_stable
       AND COALESCE(discrepancy_amount,0) = COALESCE(p_discrepancy,0)
     RETURNING id INTO v_id;
    IF v_id IS NOT NULL THEN
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (v_id, 'recurred', jsonb_build_object(
        'source', p_source, 'rotated_key', p_dedupe_key,
        'note', 'same condition under a new period label; folded rather than re-filed'));
      RETURN v_id;
    END IF;
  END IF;

  INSERT INTO public.ca_drift_incidents (
    classification, severity, layer, source, dedupe_key,
    union_id, club_id, entity_type, entity_id, table_id, tournament_id,
    hand_id, settlement_id, wallet_ids, transaction_ids,
    expected_amount, actual_amount, discrepancy_amount,
    ledger_balanced, suspected_cause, metadata)
  VALUES (
    v_class, v_sev, COALESCE(p_layer,'unknown'), p_source, p_dedupe_key,
    p_union_id, p_club_id, p_entity_type, p_entity_id, p_table_id, p_tournament_id,
    p_hand_id, p_settlement_id, p_wallet_ids, p_transaction_ids,
    p_expected, p_actual, COALESCE(p_discrepancy, 0),
    p_ledger_balanced, p_suspected_cause, COALESCE(p_metadata,'{}'::jsonb))
  ON CONFLICT (dedupe_key) WHERE status <> 'resolved' DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    UPDATE public.ca_drift_incidents
       SET occurrences = occurrences + 1, last_seen_at = now()
     WHERE dedupe_key = p_dedupe_key AND status <> 'resolved'
     RETURNING id INTO v_id;
    RETURN v_id;
  END IF;

  INSERT INTO public.ca_incident_events (incident_id, kind, detail)
  VALUES (v_id, 'created', jsonb_build_object('source', p_source));

  BEGIN
    PERFORM public.fn_raise_server_financial_alert(
      v_sev, 'drift_incident:' || p_source,
      v_class || ' drift ' || COALESCE(p_discrepancy,0)::text || ' chips',
      jsonb_build_object('incident_id', v_id) || COALESCE(p_metadata,'{}'::jsonb));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  IF p_severity = 'info' THEN
    NULL;
  ELSIF (SELECT count(*) FROM public.ca_drift_incidents
       WHERE created_at > now() - interval '2 minutes') >= 10 THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (v_id, 'notified', jsonb_build_object('storm_suppressed', true));
  ELSE
    PERFORM public.fn_ca_incident_notify(
      v_id, 'notified',
      to_char(COALESCE(p_discrepancy,0),'FM999999999990.00') || ' chip drift: ' || v_class,
      false);
  END IF;

  RETURN v_id;
EXCEPTION WHEN OTHERS THEN
  DECLARE v_state text; v_msg text;
  BEGIN
    GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
    RAISE WARNING 'fn_ca_raise_drift_incident(%) failed: %', p_source, v_msg;
    BEGIN
      INSERT INTO public.ca_incident_file_failures
        (source, dedupe_key, classification, severity, discrepancy, sqlstate, message)
      VALUES (p_source, p_dedupe_key, v_class, v_sev, p_discrepancy, v_state, v_msg);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RETURN NULL;
  END;
END $$;


ALTER FUNCTION public.fn_ca_raise_drift_incident(p_source text, p_classification text, p_severity text, p_dedupe_key text, p_discrepancy numeric, p_expected numeric, p_actual numeric, p_layer text, p_entity_type text, p_entity_id uuid, p_club_id uuid, p_union_id uuid, p_table_id uuid, p_tournament_id uuid, p_hand_id uuid, p_settlement_id text, p_wallet_ids uuid[], p_transaction_ids uuid[], p_suspected_cause text, p_ledger_balanced boolean, p_metadata jsonb) OWNER TO postgres;

--
-- Name: fn_ca_rake_by_agent(uuid, date, date, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_rake_by_agent(p_club_id uuid, p_start date, p_end date, p_limit integer, p_offset integer DEFAULT 0, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'rake'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now  timestamptz := now();
  v_from timestamptz := p_start::timestamptz;
  v_to   timestamptz := LEAST((p_end + 1)::timestamptz, v_now);
  v_uid  uuid    := auth.uid();
  v_cost boolean := public.fn_is_club_admin_uid(p_club_id);
  v_over boolean := EXISTS (SELECT 1 FROM public.union_clubs uc
                             WHERE uc.club_id = p_club_id
                               AND public.fn_is_union_overseer(uc.union_id, v_uid));
  v_q    text := NULLIF(btrim(COALESCE(p_search,'')),'');
  v_sort text := lower(COALESCE(NULLIF(btrim(p_sort),''),'rake'));
  v_out  jsonb;
BEGIN
  IF v_to <= v_from THEN
    RETURN jsonb_build_object('rows','[]'::jsonb,'total',0,'total_direct',0,'total_commission',NULL);
  END IF;

  WITH RECURSIVE ok_days AS MATERIALIZED (
    SELECT rc.day FROM public.club_rake_rollup_complete rc
     WHERE rc.club_id = p_club_id
       AND rc.day >= date_trunc('day', v_from)::date
       AND rc.day <  date_trunc('day', v_to)::date
  ), from_rollup AS (
    SELECT rd.user_id, SUM(rd.rake_amount) AS rake, SUM(rd.hands)::bigint AS hands
      FROM public.club_rake_daily_user rd
      JOIN ok_days o ON o.day = rd.day
     WHERE rd.club_id = p_club_id
     GROUP BY rd.user_id
  ), from_live AS (
    -- THE DAYS NOT YET SEALED, read from the incremental rollup the triggers
    -- on rake_attributions keep exact. This used to scan the attributions
    -- themselves, which is fine at 04:00 and a third of a million rows by
    -- midnight - the panel healed every morning and failed every evening.
    -- Same cents, same rounding, same source table as the sealed days.
    SELECT du.user_id,
           du.rake_cents::numeric / 100 AS rake,
           du.hands
      FROM public.ca_club_rake_daily_user du
     WHERE du.club_id = p_club_id
       AND du.day >= date_trunc('day', v_from)::date
       -- A DAY IS IN RANGE WHEN ITS OWN MIDNIGHT IS BEFORE THE EXCLUSIVE END,
       -- never `<= date_trunc('day', v_to)`. v_to is either a midnight (ask
       -- for a range ending yesterday and it is TODAY's midnight) or now()
       -- itself (ask for a range ending today). The inclusive form got the
       -- second case right and the first case wrong, and put TODAY's rake into
       -- a report for YESTERDAY. Caught by comparing old against new under one
       -- snapshot before this shipped; four ranges agreed and that one did not.
       AND du.day::timestamptz < v_to
       AND NOT EXISTS (SELECT 1 FROM ok_days o WHERE o.day = du.day)
  ), earned AS MATERIALIZED (
    SELECT COALESCE(a.user_id,b.user_id) AS user_id,
           COALESCE(a.rake,0)+COALESCE(b.rake,0)   AS rake,
           COALESCE(a.hands,0)+COALESCE(b.hands,0) AS hands
      FROM from_rollup a FULL OUTER JOIN from_live b ON b.user_id = a.user_id
  ), commission AS (
    SELECT ac.user_id,
           SUM(ac.amount)                                          AS earned,
           SUM(ac.amount) FILTER (WHERE ac.settled_at IS NULL AND NOT public.fn_agent_commission_paid_by_period(ac.club_id, ac.user_id, ac.created_at)) AS outstanding,
           SUM(ac.amount) FILTER (WHERE ac.settled_at IS NOT NULL OR public.fn_agent_commission_paid_by_period(ac.club_id, ac.user_id, ac.created_at)) AS settled
      FROM public.agent_commissions ac
     WHERE ac.club_id = p_club_id
       AND ac.created_at >= v_from AND ac.created_at < v_to
     GROUP BY ac.user_id
  ), club_agents AS (
    SELECT a.id, a.user_id, a.parent_agent_id, a.role, a.commission_rate
      FROM public.agents a WHERE a.club_id = p_club_id AND a.status='active'
  ), direct AS (
    SELECT cm.agent_id, COUNT(*) AS players,
           COUNT(*) FILTER (WHERE COALESCE(e.rake,0) <> 0) AS active,
           COALESCE(SUM(e.rake),0) AS rake, COALESCE(SUM(e.hands),0)::bigint AS hands
      FROM public.club_members cm
      LEFT JOIN earned e ON e.user_id = cm.user_id
     WHERE cm.club_id = p_club_id
     GROUP BY cm.agent_id
  ), tree AS (
    SELECT ca.id AS root_id, ca.id AS node_id, 0 AS depth FROM club_agents ca
    UNION ALL
    SELECT t.root_id, c.id, t.depth+1
      FROM tree t JOIN club_agents c ON c.parent_agent_id = t.node_id
     WHERE t.depth < 12
  ), network AS (
    SELECT t.root_id, COALESCE(SUM(d.rake),0) AS rake,
           COALESCE(SUM(d.players),0) AS players,
           COUNT(*) FILTER (WHERE t.node_id <> t.root_id) AS sub_agents
      FROM (SELECT DISTINCT root_id, node_id FROM tree) t
      JOIN club_agents n ON n.id = t.node_id
      LEFT JOIN direct d ON d.agent_id = n.user_id
     GROUP BY t.root_id
  ), unlisted AS (
    SELECT SUM(cs.earned) AS earned, SUM(cs.outstanding) AS outstanding,
           SUM(cs.settled) AS settled, count(*)::int AS recipients
      FROM commission cs
     WHERE NOT EXISTS (SELECT 1 FROM club_agents ca WHERE ca.user_id = cs.user_id)
  ), listed AS (
    SELECT ca.user_id AS agent_user_id,
           COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                                         pr.first_name, pr.last_name, pr.full_name),
                    pr.username, 'Agent') AS name,
           pr.avatar_url, ca.role, ca.commission_rate,
           COALESCE(dr.players,0) AS direct_players,
           COALESCE(dr.active,0)  AS direct_active,
           round(COALESCE(dr.rake,0),2) AS direct_rake,
           COALESCE(dr.hands,0) AS direct_hands,
           COALESCE(nw.players,0) AS network_players,
           round(COALESCE(nw.rake,0),2) AS network_rake,
           COALESCE(nw.sub_agents,0) AS sub_agents,
           CASE WHEN v_cost THEN round(COALESCE(cs.earned,0),2)      END AS commission_earned,
           CASE WHEN v_cost THEN round(COALESCE(cs.outstanding,0),2) END AS commission_outstanding,
           CASE WHEN v_cost THEN round(COALESCE(cs.settled,0),2)     END AS commission_settled,
           -- The same three conditions the downline walker enforces.
           (v_cost OR v_over OR ca.user_id = v_uid
            OR public.fn_is_agent_ancestor(v_uid, ca.user_id, p_club_id)) AS can_drill,
           false AS is_unassigned, false AS is_residual
      FROM club_agents ca
      LEFT JOIN direct dr ON dr.agent_id = ca.user_id
      LEFT JOIN network nw ON nw.root_id = ca.id
      LEFT JOIN commission cs ON cs.user_id = ca.user_id
      LEFT JOIN public.profiles pr ON pr.id = ca.user_id
    UNION ALL
    SELECT NULL,'Unassigned',NULL,'none',NULL,
           d.players,d.active,round(d.rake,2),d.hands,
           d.players,round(d.rake,2),0,
           CASE WHEN v_cost THEN 0::numeric END,
           CASE WHEN v_cost THEN 0::numeric END,
           CASE WHEN v_cost THEN 0::numeric END,
           false, true, false
      FROM direct d WHERE d.agent_id IS NULL AND d.players > 0
    UNION ALL
    SELECT NULL,'Unlisted Recipients',NULL,'none',NULL,
           0,0,0::numeric,0::bigint,
           u.recipients,0::numeric,0,
           round(u.earned,2), round(u.outstanding,2), round(u.settled,2),
           false, true, true
      FROM unlisted u
     WHERE v_cost AND COALESCE(u.earned,0) <> 0
  ), totals AS (
    -- Before the filter. The denominator is the club, not the search result.
    SELECT COALESCE(SUM(l.direct_rake),0) AS total_direct,
           SUM(l.commission_earned)       AS total_commission
      FROM listed l
  ), filtered AS (
    SELECT l.* FROM listed l
     WHERE v_q IS NULL OR l.name ILIKE '%' || public.fn_like_escape(v_q) || '%' ESCAPE '\'
  ), ranked AS (
    SELECT f.*, row_number() OVER (
             ORDER BY f.is_unassigned,
               CASE WHEN v_sort = 'name'    THEN f.name END ASC,
               CASE WHEN v_sort = 'cost'    THEN f.commission_earned END DESC NULLS LAST,
               CASE WHEN v_sort = 'players' THEN f.network_players END DESC,
               CASE WHEN v_sort NOT IN ('name','cost','players')
                    THEN f.network_rake END DESC NULLS LAST,
               f.name ASC) AS rn
      FROM filtered f
  ), sliced AS (
    SELECT r.* FROM ranked r ORDER BY r.rn
     OFFSET GREATEST(COALESCE(p_offset,0),0)
      LIMIT GREATEST(LEAST(COALESCE(p_limit,50),200),1)
  )
  SELECT jsonb_build_object(
    'rows', COALESCE((SELECT jsonb_agg((to_jsonb(s) - 'rn') ORDER BY s.rn) FROM sliced s), '[]'::jsonb),
    -- Counted, not taken from a window over the page: ask for an offset past
    -- the end and a windowed count would answer "nothing matches".
    'total', (SELECT count(*) FROM filtered),
    'total_direct', (SELECT t.total_direct FROM totals t),
    'total_commission', (SELECT t.total_commission FROM totals t))
    INTO v_out;

  RETURN COALESCE(v_out,
    jsonb_build_object('rows','[]'::jsonb,'total',0,'total_direct',0,'total_commission',NULL));
END;
$$;


ALTER FUNCTION public.fn_ca_rake_by_agent(p_club_id uuid, p_start date, p_end date, p_limit integer, p_offset integer, p_search text, p_sort text) OWNER TO postgres;

--
-- Name: fn_ca_rake_by_club(uuid[], date, date, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_rake_by_club(p_club_ids uuid[], p_start date, p_end date, p_limit integer, p_offset integer DEFAULT 0, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'rake'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH rows_in AS (
    SELECT c.club_id, c.rake AS fee, c.net AS winnings,
           COALESCE(c.hands,0)::bigint AS hands,
           'c:' || c.table_id::text AS gid, false AS is_mtt
      FROM public.club_table_daily c
     WHERE c.club_id = ANY (p_club_ids) AND c.stat_date BETWEEN p_start AND p_end
    UNION ALL
    SELECT t.club_id, t.fee, t.winnings, 0::bigint,
           't:' || t.tournament_id::text, true
      FROM public.ca_club_tournament_daily t
     WHERE t.club_id = ANY (p_club_ids) AND t.stat_date BETWEEN p_start AND p_end
  ), agg AS (
    SELECT r.club_id,
           round(SUM(r.fee),2) AS fee,
           round(SUM(r.fee) FILTER (WHERE r.is_mtt),2) AS mtt_fee,
           round(SUM(r.fee) FILTER (WHERE NOT r.is_mtt),2) AS cash_fee,
           round(SUM(r.winnings),2) AS winnings,
           SUM(r.hands) AS hands,
           COUNT(DISTINCT r.gid) AS games
      FROM rows_in r GROUP BY r.club_id
  ), listed AS (
    SELECT a.club_id, COALESCE(cl.name,'Club') AS name, cl.code,
           COALESCE(cl.avatar_url, cl.logo_url) AS avatar_url,
           COALESCE(a.fee,0) AS fee, COALESCE(a.cash_fee,0) AS cash_fee,
           COALESCE(a.mtt_fee,0) AS mtt_fee, COALESCE(a.winnings,0) AS winnings,
           COALESCE(a.hands,0) AS hands, a.games,
           -- The same gate the club scope enforces.
           public.ca_can_read_club_production(a.club_id) AS can_drill
      FROM agg a JOIN public.clubs cl ON cl.id = a.club_id
  ), totals AS (
    -- Before the filter, deliberately: the denominator is the whole set.
    SELECT COALESCE(SUM(l.fee),0) AS total_direct FROM listed l
  ), filtered AS (
    SELECT l.* FROM listed l
     WHERE NULLIF(btrim(COALESCE(p_search,'')),'') IS NULL
        OR l.name ILIKE '%' || public.fn_like_escape(btrim(p_search)) || '%' ESCAPE '\'
        OR COALESCE(l.code,'') ILIKE '%' || public.fn_like_escape(btrim(p_search)) || '%' ESCAPE '\'
  ), page AS (
    SELECT f.* FROM filtered f
     ORDER BY
       CASE WHEN lower(COALESCE(p_sort,'rake')) = 'name'  THEN f.name END ASC,
       CASE WHEN lower(COALESCE(p_sort,'rake')) = 'hands' THEN f.hands END DESC,
       CASE WHEN lower(COALESCE(p_sort,'rake')) NOT IN ('name','hands') THEN f.fee END DESC,
       f.name ASC
     OFFSET GREATEST(COALESCE(p_offset,0),0)
      LIMIT GREATEST(LEAST(COALESCE(p_limit,50),200),1)
  )
  SELECT jsonb_build_object(
    'rows', COALESCE((SELECT jsonb_agg(to_jsonb(p)) FROM page p), '[]'::jsonb),
    'total', (SELECT count(*) FROM filtered),
    'total_direct', (SELECT t.total_direct FROM totals t),
    'total_commission', NULL);
$$;


ALTER FUNCTION public.fn_ca_rake_by_club(p_club_ids uuid[], p_start date, p_end date, p_limit integer, p_offset integer, p_search text, p_sort text) OWNER TO postgres;

--
-- Name: fn_ca_rake_by_downline(uuid, uuid, timestamp with time zone, timestamp with time zone, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_rake_by_downline(p_agent_user_id uuid, p_club_id uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_limit integer, p_offset integer DEFAULT 0, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'rake'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH listed AS (
    SELECT d.* FROM public.fn_agent_downline_rake(
      p_agent_user_id, p_club_id, p_since, p_until, NULL, 5000) d
  ), totals AS (
    SELECT COALESCE(SUM(l.rake_generated),0) AS total_direct FROM listed l
  ), filtered AS (
    SELECT l.* FROM listed l
     WHERE NULLIF(btrim(COALESCE(p_search,'')),'') IS NULL
        OR COALESCE(l.username,'') ILIKE '%' || public.fn_like_escape(btrim(p_search)) || '%' ESCAPE '\'
  ), page AS (
    SELECT f.* FROM filtered f
     ORDER BY
       CASE WHEN lower(COALESCE(p_sort,'rake')) = 'name'  THEN f.username END ASC,
       CASE WHEN lower(COALESCE(p_sort,'rake')) = 'hands' THEN f.hands END DESC,
       CASE WHEN lower(COALESCE(p_sort,'rake')) NOT IN ('name','hands')
            THEN f.rake_generated END DESC,
       f.username ASC
     OFFSET GREATEST(COALESCE(p_offset,0),0)
      LIMIT GREATEST(LEAST(COALESCE(p_limit,100),500),1)
  )
  SELECT jsonb_build_object(
    'rows', COALESCE((SELECT jsonb_agg(jsonb_build_object(
              'player_id', p.player_id,
              'name', COALESCE(p.username,'Player'),
              'role', p.role,
              'depth', p.depth,
              'upline_user_id', p.upline_user_id,
              'upline_name', p.upline_name,
              'rake', round(COALESCE(p.rake_generated,0),2),
              'hands', COALESCE(p.hands,0),
              'last_hand_at', p.last_hand_at,
              'downline_players', COALESCE(p.downline_players,0),
              'downline_rake', round(COALESCE(p.downline_rake,0),2))) FROM page p), '[]'::jsonb),
    'total', (SELECT count(*) FROM filtered),
    'total_direct', (SELECT t.total_direct FROM totals t),
    'total_commission', NULL);
$$;


ALTER FUNCTION public.fn_ca_rake_by_downline(p_agent_user_id uuid, p_club_id uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_limit integer, p_offset integer, p_search text, p_sort text) OWNER TO postgres;

--
-- Name: fn_ca_rake_distribution_mismatch(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_rake_distribution_mismatch(p_window interval DEFAULT '01:00:00'::interval) RETURNS TABLE(hand_id uuid, rake numeric, distributed numeric, excess numeric, legs bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT rr.hand_id,
         round(rr.rake_amount, 2),
         COALESCE(l.total, 0),
         round(COALESCE(l.total, 0) - rr.rake_amount, 2),
         COALESCE(l.n, 0)
    FROM public.rake_records rr
    LEFT JOIN LATERAL (
      SELECT round(sum(amount), 2) AS total, count(*) AS n
        FROM public.rake_distribution_legs dl
       WHERE dl.leg_key = rr.hand_id
         -- club_accumulator accrues the club's weekly share; it moves no chips
         AND dl.leg <> 'club_accumulator'
    ) l ON true
   WHERE rr.created_at > now() - p_window
     AND rr.hand_id IS NOT NULL
     AND rr.rake_amount > 0
     AND COALESCE(l.total, 0) > rr.rake_amount + 0.01
   ORDER BY COALESCE(l.total, 0) - rr.rake_amount DESC;
$$;


ALTER FUNCTION public.fn_ca_rake_distribution_mismatch(p_window interval) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_rake_distribution_mismatch(p_window interval); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_rake_distribution_mismatch(p_window interval) IS 'Hands where the CHIP-MOVING rake legs sum to more than the rake taken from the pot. club_accumulator is excluded: since the 2026-09-02 ruling it records the club share accruing toward the weekly settlement and moves no chips. Whatever the split, the legs that move money must sum to the rake.';


--
-- Name: fn_ca_rake_distribution_mismatch_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_rake_distribution_mismatch_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    round(100.0 * count(*) FILTER (
            WHERE COALESCE(l.total, 0) > rr.rake_amount + 0.01)
          / NULLIF(count(*), 0))::int, 0)
    FROM public.rake_records rr
    LEFT JOIN LATERAL (
      SELECT round(sum(amount), 2) AS total
        FROM public.rake_distribution_legs dl
       WHERE dl.leg_key = rr.hand_id
         AND dl.leg <> 'club_accumulator'
    ) l ON true
   WHERE rr.created_at > now() - interval '10 minutes'
     AND rr.hand_id IS NOT NULL
     AND rr.rake_amount > 0;
$$;


ALTER FUNCTION public.fn_ca_rake_distribution_mismatch_count() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_rake_distribution_mismatch_count(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_rake_distribution_mismatch_count() IS 'Percent of raked hands in the last TEN MINUTES whose distribution legs sum to more than the rake collected. A rate, not a headcount, sampled over a window big enough to be stable (~190 hands) and small enough to run hourly. Use fn_ca_rake_distribution_mismatch(interval) to read the hands themselves.';


--
-- Name: fn_ca_rake_series(uuid[], date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_rake_series(p_club_ids uuid[], p_start date, p_end date, p_bucket text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH b AS (
    SELECT CASE WHEN lower(COALESCE(p_bucket, 'day')) IN ('day', 'week', 'month')
                THEN lower(p_bucket) ELSE 'day' END AS unit
  ), rows AS (
    SELECT c.stat_date AS d, c.rake AS fee, c.net AS winnings
      FROM public.club_table_daily c
     WHERE c.club_id = ANY (p_club_ids) AND c.stat_date BETWEEN p_start AND p_end
    UNION ALL
    SELECT t.stat_date, t.fee, t.winnings
      FROM public.ca_club_tournament_daily t
     WHERE t.club_id = ANY (p_club_ids) AND t.stat_date BETWEEN p_start AND p_end
  ), grouped AS (
    SELECT date_trunc((SELECT unit FROM b), rows.d::timestamp)::date AS bucket,
           round(SUM(rows.fee), 2)      AS fee,
           round(SUM(rows.winnings), 2) AS winnings
      FROM rows GROUP BY 1
  )
  SELECT COALESCE(
    jsonb_agg(jsonb_build_object('bucket', bucket, 'fee', fee, 'winnings', winnings)
              ORDER BY bucket),
    '[]'::jsonb)
  FROM grouped;
$$;


ALTER FUNCTION public.fn_ca_rake_series(p_club_ids uuid[], p_start date, p_end date, p_bucket text) OWNER TO postgres;

--
-- Name: fn_ca_rake_window(uuid[], date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_rake_window(p_club_ids uuid[], p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH cash AS (
    SELECT COALESCE(SUM(c.rake), 0)          AS fee,
           COALESCE(SUM(c.net), 0)           AS winnings,
           COALESCE(SUM(c.hands), 0)::bigint AS hands,
           COUNT(DISTINCT c.table_id)        AS games
      FROM public.club_table_daily c
     WHERE c.club_id = ANY (p_club_ids)
       AND c.stat_date BETWEEN p_start AND p_end
  ), mtt AS (
    SELECT COALESCE(SUM(d.fee), 0)        AS fee,
           COALESCE(SUM(d.winnings), 0)   AS winnings,
           COUNT(DISTINCT d.tournament_id) AS games
      FROM public.ca_club_tournament_daily d
     WHERE d.club_id = ANY (p_club_ids)
       AND d.stat_date BETWEEN p_start AND p_end
  )
  SELECT jsonb_build_object(
    'games',          cash.games + mtt.games,
    'cash_games',     cash.games,
    'mtt_games',      mtt.games,
    'hands',          cash.hands,
    'fee',            round(cash.fee + mtt.fee, 2),
    'cash_fee',       round(cash.fee, 2),
    'mtt_fee',        round(mtt.fee, 2),
    'total_winnings', round(cash.winnings + mtt.winnings, 2),
    'cash_winnings',  round(cash.winnings, 2),
    'mtt_winnings',   round(mtt.winnings, 2)
  )
  FROM cash, mtt;
$$;


ALTER FUNCTION public.fn_ca_rake_window(p_club_ids uuid[], p_start date, p_end date) OWNER TO postgres;

--
-- Name: fn_ca_ratchet_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ratchet_watch() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_row record; v_current integer; v_out jsonb := '[]'::jsonb; v_crit boolean;
BEGIN
  FOR v_row IN SELECT * FROM public.ca_ratchet_baselines ORDER BY ratchet LOOP
    IF v_row.ratchet = 'unledgered_insert_paths' THEN
      SELECT count(*)::int INTO v_current FROM public.fn_ca_unledgered_insert_paths();
    ELSIF v_row.ratchet = 'undeclared_money_paths' THEN
      SELECT count(*)::int INTO v_current FROM public.fn_ca_undeclared_money_paths();
    ELSIF v_row.ratchet = 'rake_law_violations_24h' THEN
      SELECT count(*)::int INTO v_current
        FROM public.fn_rake_law_violations('2 hours'::interval)
       WHERE kind IN ('no_flop_no_drop','over_cap','over_percent');
    ELSIF v_row.ratchet = 'reconciler_delete_unscoped' THEN
      SELECT public.fn_ca_reconciler_delete_unscoped() INTO v_current;
    ELSIF v_row.ratchet = 'completed_without_a_champion' THEN
      SELECT public.fn_ca_completed_without_a_champion() INTO v_current;
    ELSIF v_row.ratchet = 'prize_overpay_unexplained_10d' THEN
      SELECT public.fn_ca_prize_overpay_count() INTO v_current;
    ELSIF v_row.ratchet = 'rake_distributed_exceeds_collected_1h' THEN
      SELECT public.fn_ca_rake_distribution_mismatch_count() INTO v_current;
    ELSIF v_row.ratchet = 'tournament_underpaid_48h' THEN
      SELECT public.fn_ca_tournament_underpaid_count() INTO v_current;
    ELSE
      CONTINUE;
    END IF;

    v_crit := v_row.ratchet IN ('rake_law_violations_24h','reconciler_delete_unscoped',
                                'completed_without_a_champion','prize_overpay_unexplained_10d',
                                'rake_distributed_exceeds_collected_1h','tournament_underpaid_48h');

    IF v_current > v_row.baseline THEN
      PERFORM public.fn_ca_raise_drift_incident(
        p_source          => 'fn_ca_ratchet_watch',
        p_classification  => CASE v_row.ratchet
                               WHEN 'rake_law_violations_24h' THEN 'incorrect_rake'
                               WHEN 'rake_distributed_exceeds_collected_1h' THEN 'incorrect_rake'
                               WHEN 'reconciler_delete_unscoped' THEN 'reporting_mismatch'
                               WHEN 'tournament_underpaid_48h' THEN 'missing_payment'
                               WHEN 'completed_without_a_champion' THEN 'settlement_error'
                               WHEN 'prize_overpay_unexplained_10d' THEN 'settlement_error'
                               ELSE 'unauthorized_adjustment' END,
        p_severity        => CASE WHEN v_crit THEN 'critical' ELSE 'warning' END,
        p_dedupe_key      => 'ratchet:' || v_row.ratchet || ':above:' || v_row.baseline
                             || ':' || to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD'),
        p_discrepancy     => (v_current - v_row.baseline)::numeric,
        p_expected        => v_row.baseline::numeric,
        p_actual          => v_current::numeric,
        p_layer           => CASE v_row.ratchet
                               WHEN 'reconciler_delete_unscoped' THEN 'reporting'
                               WHEN 'undeclared_money_paths' THEN 'ledger'
                               WHEN 'unledgered_insert_paths' THEN 'ledger'
                               ELSE 'settlement' END,
        p_suspected_cause => CASE v_row.ratchet
          WHEN 'rake_law_violations_24h' THEN
            'Chips were raked that the rules did not owe the house, in the last 2 hours.'
          WHEN 'rake_distributed_exceeds_collected_1h' THEN
            'A larger share of raked hands is banking more rake than was taken from the pot.'
          WHEN 'reconciler_delete_unscoped' THEN
            'reconcile_ledger_nightly has lost its scoped DELETE and is again clearing '
            || 'ledger_reconcile_log rows it never wrote.'
          WHEN 'tournament_underpaid_48h' THEN
            'A tournament paid players LESS than it owed - GREATEST(prize_pool, '
            || 'guaranteed_prize). Every case found so far was a guarantee that was never '
            || 'topped up, so the advertised prize pool and the paid one differ. Read them '
            || 'with SELECT * FROM fn_ca_tournament_settlement_mismatch() WHERE kind=''underpaid''.'
          WHEN 'completed_without_a_champion' THEN
            'A tournament finished without anybody marked winner, so every settlement '
            || 'that reads status=winner is stuck.'
          WHEN 'prize_overpay_unexplained_10d' THEN
            'A tournament paid out more than its prize pool AND more than its guarantee, '
            || 'and it is neither a satellite nor a Spin.'
          ELSE
            'A new money path was added that does not declare its ledger counterparty.' END,
        p_ledger_balanced => true,
        p_metadata        => jsonb_build_object('ratchet', v_row.ratchet,
                                                'baseline', v_row.baseline,
                                                'current',  v_current));
    ELSIF v_current < v_row.baseline THEN
      UPDATE public.ca_ratchet_baselines
         SET baseline = v_current, tightened_at = now()
       WHERE ratchet = v_row.ratchet;
    END IF;

    v_out := v_out || jsonb_build_object('ratchet', v_row.ratchet,
                                         'baseline', v_row.baseline, 'current', v_current);
  END LOOP;

  RETURN jsonb_build_object('checked_at', now(), 'ratchets', v_out);
END;
$$;


ALTER FUNCTION public.fn_ca_ratchet_watch() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_ratchet_watch(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_ratchet_watch() IS 'Hourly. Raises a warning incident when a structural money-path ratchet regresses above its baseline, and tightens the baseline when it improves. Never blocks or disables anything.';


--
-- Name: fn_ca_reconcile_log_to_incident(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_reconcile_log_to_incident() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_class text; v_layer text; v_club uuid; v_kind text; v_illegal boolean;
BEGIN
  IF NEW.severity NOT IN ('warn','critical') THEN RETURN NEW; END IF;

  v_kind := NEW.metadata->>'kind';
  -- An over-rake takes chips off a player that the rules never owed the
  -- house. board_not_recorded and impossible_showdown really are evidence
  -- gaps; these three are money.
  v_illegal := NEW.entity_type = 'rake_law'
               AND v_kind IN ('no_flop_no_drop','over_cap','over_percent');

  v_class := CASE
    WHEN v_illegal THEN 'incorrect_rake'
    ELSE CASE NEW.entity_type
      WHEN 'club_treasury' THEN 'treasury_error'
      WHEN 'frozen_wallets_pool' THEN 'unauthorized_adjustment'
      WHEN 'seat_stack_exit' THEN 'missing_payment'
      WHEN 'negative_balance' THEN 'ledger_imbalance'
      WHEN 'insurance_bank' THEN 'settlement_error'
      WHEN 'insurance_offer_unresolved' THEN 'settlement_error'
      WHEN 'cashout_escrow_stuck' THEN 'settlement_error'
      WHEN 'over_claimed_send' THEN 'duplicate_payment'
      WHEN 'bomb_award_ledger_gap' THEN 'reporting_mismatch'
      WHEN 'rake_law' THEN 'reporting_mismatch'
      ELSE 'unknown' END
  END;

  v_layer := CASE
    WHEN v_illegal THEN 'settlement'
    WHEN NEW.entity_type IN ('bomb_award_ledger_gap','rake_law') THEN 'reporting'
    ELSE 'ledger' END;

  BEGIN v_club := NULLIF(NEW.metadata->>'club_id','')::uuid;
  EXCEPTION WHEN OTHERS THEN v_club := NULL; END;
  IF v_club IS NULL AND NEW.entity_type = 'club_treasury' THEN v_club := NEW.entity_id; END IF;

  PERFORM public.fn_ca_raise_drift_incident(
    p_source => 'ledger_reconcile_log:' || COALESCE(NEW.metadata->>'source', v_kind, '?'),
    p_classification => v_class,
    p_severity => CASE WHEN v_illegal THEN 'critical'
                       WHEN NEW.severity = 'critical' THEN 'critical'
                       ELSE 'warning' END,
    p_dedupe_key => 'lrl:' || NEW.entity_type || ':' || COALESCE(NEW.entity_id::text,'-') || ':' ||
      COALESCE(NEW.metadata->>'exit_id', NEW.metadata->>'hand_history_id',
               NEW.metadata->>'hand_id', NEW.metadata->>'escrow_id', ''),
    p_discrepancy => COALESCE(NEW.stored_balance,0) - COALESCE(NEW.ledger_balance,0),
    p_expected => NEW.ledger_balance,
    p_actual => NEW.stored_balance,
    p_layer => v_layer,
    p_entity_type => NEW.entity_type,
    p_entity_id => NEW.entity_id,
    p_club_id => v_club,
    p_suspected_cause => COALESCE(NEW.metadata->>'rule', v_kind),
    p_metadata => COALESCE(NEW.metadata,'{}'::jsonb));
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_ca_reconcile_log_to_incident failed: %', SQLERRM;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_reconcile_log_to_incident() OWNER TO postgres;

--
-- Name: fn_ca_reconcile_owned_entity_types(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_reconcile_owned_entity_types() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT ARRAY['player_wallet','seat_stack_exit','club_treasury','chip_circulation',
               'bomb_award_ledger_gap','frozen_wallets_pool','insurance_bank',
               'negative_balance']::text[];
$$;


ALTER FUNCTION public.fn_ca_reconcile_owned_entity_types() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_reconcile_owned_entity_types(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_reconcile_owned_entity_types() IS 'The entity types reconcile_ledger_nightly writes, and therefore the only ones it may clear. Any other writer of ledger_reconcile_log (fn_rake_law_check writes rake_law) must NOT appear here.';


--
-- Name: fn_ca_reconciler_delete_unscoped(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_reconciler_delete_unscoped() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  -- 1 when reconcile_ledger_nightly clears rows it does not own, 0 when the
  -- DELETE is scoped to its own entity types.
  SELECT CASE
           WHEN NOT EXISTS (
             SELECT 1 FROM pg_proc p
              JOIN pg_namespace n ON n.oid = p.pronamespace
             WHERE n.nspname = 'public' AND p.proname = 'reconcile_ledger_nightly'
           ) THEN 1                      -- missing entirely is also not healthy
           WHEN (SELECT pg_get_functiondef(p.oid)
                   FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
                  WHERE n.nspname = 'public' AND p.proname = 'reconcile_ledger_nightly'
                  LIMIT 1)
                ILIKE '%fn_ca_reconcile_owned_entity_types()%' THEN 0
           ELSE 1
         END;
$$;


ALTER FUNCTION public.fn_ca_reconciler_delete_unscoped() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_reconciler_delete_unscoped(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_reconciler_delete_unscoped() IS 'Returns 1 if reconcile_ledger_nightly has lost its scoped DELETE and is again clearing ledger_reconcile_log rows written by other jobs (rake_law). Watched hourly by fn_ca_ratchet_watch at baseline 0.';


--
-- Name: fn_ca_record_break_scorecard(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_record_break_scorecard(p_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.ca_break_scorecards
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_end   TIMESTAMPTZ := COALESCE(p_end, date_trunc('hour', now()));
  v_start TIMESTAMPTZ := v_end - interval '5 minutes';
  v_meas_start TIMESTAMPTZ;
  v_meas_end   TIMESTAMPTZ;
  v_brk   RECORD;
  v_hands INTEGER; v_wtabs INTEGER;
  v_thaw  RECORD; v_kill INTEGER; v_base INTEGER; v_rec INTEGER;
  v_ship  RECORD; v_pre NUMERIC; v_post NUMERIC; v_conserved BOOLEAN; v_delta NUMERIC;
  v_verdict TEXT; v_row public.ca_break_scorecards; m INTEGER;
  v_early_s NUMERIC; v_late_start_s NUMERIC; v_covered BOOLEAN; v_reasons TEXT[] := '{}';
  c_max_hands CONSTANT INTEGER := 50;
  c_edge_tolerance_s CONSTANT NUMERIC := 30;
BEGIN
  SELECT break_started_at, break_ended_at, unparked_at_countdown, peak_unparked,
         ready_for_restart_at
    INTO v_brk
    FROM public.engine_maintenance_break_log
   WHERE break_started_at BETWEEN v_start - interval '3 min' AND v_start + interval '3 min'
   ORDER BY recorded_at DESC LIMIT 1;

  IF v_brk.break_started_at IS NOT NULL AND v_brk.break_ended_at IS NOT NULL THEN
    v_meas_start := v_brk.break_started_at;
    v_meas_end   := v_brk.break_ended_at;
    v_early_s := GREATEST(0, EXTRACT(EPOCH FROM (v_end - v_brk.break_ended_at)));
    v_late_start_s := GREATEST(0, EXTRACT(EPOCH FROM (v_brk.break_started_at - v_start)));
    v_covered := (v_early_s <= c_edge_tolerance_s AND v_late_start_s <= c_edge_tolerance_s);
  ELSE
    v_meas_start := v_start;
    v_meas_end   := v_end;
    v_covered := NULL;
  END IF;

  SELECT count(*), count(DISTINCT table_id) INTO v_hands, v_wtabs
    FROM public.hand_history
   WHERE created_at >= v_meas_start AND created_at < v_meas_end;

  SELECT frozen_seconds, thawed_at INTO v_thaw
    FROM public.engine_maintenance_thaws
   WHERE freeze_started_at BETWEEN v_start - interval '3 min' AND v_start + interval '3 min'
   ORDER BY thawed_at DESC LIMIT 1;

  SELECT count(*) INTO v_kill FROM public.engine_recovery_events
   WHERE event = 'watchdog_kill_rebuild'
     AND event_class = 'automatic_recovery'
     AND created_at >= v_end AND created_at < v_end + interval '5 min';

  SELECT count(DISTINCT table_id) INTO v_base FROM public.hand_history
   WHERE created_at >= v_end - interval '12 min' AND created_at < v_end - interval '7 min';
  v_rec := NULL;
  IF v_base > 0 THEN
    FOR m IN 1..10 LOOP
      IF (SELECT count(DISTINCT table_id) FROM public.hand_history
            WHERE created_at >= v_end + make_interval(mins => m - 1)
              AND created_at <  v_end + make_interval(mins => m + 1)) >= ceil(v_base * 0.8) THEN
        v_rec := m * 60; EXIT;
      END IF;
    END LOOP;
  END IF;

  SELECT target_sha, shipped INTO v_ship FROM public.ca_engine_deploy_attempts
   WHERE at >= v_start AND at < v_end + interval '6 min' ORDER BY at DESC LIMIT 1;

  SELECT total INTO v_pre  FROM public.ca_freeze_circulation_marks WHERE window_hour = v_end AND kind='pre';
  SELECT total INTO v_post FROM public.ca_freeze_circulation_marks WHERE window_hour = v_end AND kind='post';
  IF v_pre IS NOT NULL AND v_post IS NOT NULL THEN
    v_delta := v_post - v_pre;
    v_conserved := (abs(v_delta) <= GREATEST(1.0, COALESCE(v_pre, 0) * 1e-7));
  ELSE v_delta := NULL; v_conserved := NULL; END IF;

  IF v_hands IS NOT NULL THEN
    IF v_hands > c_max_hands THEN
      v_reasons := array_append(v_reasons, 'dealt_inside_break');
    END IF;
    IF COALESCE(v_thaw.frozen_seconds, 0) <= 0 THEN
      v_reasons := array_append(v_reasons, 'thaw_did_not_run');
    END IF;
    IF v_covered IS FALSE THEN
      v_reasons := array_append(v_reasons, 'break_missed_its_window');
    END IF;
  END IF;

  v_verdict := CASE
    WHEN v_hands IS NULL THEN 'unknown'
    WHEN v_hands <= c_max_hands
     AND COALESCE(v_thaw.frozen_seconds, 0) > 0
     AND v_covered IS NOT FALSE
    THEN 'pass'
    ELSE 'fail' END;

  INSERT INTO public.ca_break_scorecards AS s (
    break_ended_at, break_started_at, hands_in_window, tables_dealing_in_window,
    thaw_ran, thaw_frozen_seconds, kill_rebuilds_after, recovery_seconds,
    pre_break_tables, shipped_sha, shipped, freeze_conserved, freeze_delta, verdict, detail,
    unparked_at_countdown, peak_unparked, ready_for_restart_at, gate_opened)
  VALUES (
    v_end, v_start, v_hands, v_wtabs,
    (v_thaw.frozen_seconds IS NOT NULL), v_thaw.frozen_seconds, v_kill, v_rec,
    v_base, v_ship.target_sha, COALESCE(v_ship.shipped, FALSE), v_conserved, v_delta, v_verdict,
    jsonb_build_object(
      'pre_total', v_pre,
      'post_total', v_post,
      'measured_from', v_meas_start,
      'measured_to', v_meas_end,
      'measured_actual_break', (v_brk.break_started_at IS NOT NULL),
      'covered_the_hour', v_covered,
      'resumed_early_seconds', v_early_s,
      'started_late_seconds', v_late_start_s,
      'reasons', to_jsonb(v_reasons)),
    v_brk.unparked_at_countdown, v_brk.peak_unparked, v_brk.ready_for_restart_at,
    CASE WHEN v_brk.unparked_at_countdown IS NULL THEN NULL
         ELSE (v_brk.ready_for_restart_at IS NOT NULL) END)
  ON CONFLICT (break_ended_at) DO UPDATE SET
    hands_in_window = EXCLUDED.hands_in_window,
    tables_dealing_in_window = EXCLUDED.tables_dealing_in_window,
    thaw_ran = EXCLUDED.thaw_ran, thaw_frozen_seconds = EXCLUDED.thaw_frozen_seconds,
    kill_rebuilds_after = EXCLUDED.kill_rebuilds_after, recovery_seconds = EXCLUDED.recovery_seconds,
    pre_break_tables = EXCLUDED.pre_break_tables, shipped_sha = EXCLUDED.shipped_sha,
    shipped = EXCLUDED.shipped, freeze_conserved = EXCLUDED.freeze_conserved,
    freeze_delta = EXCLUDED.freeze_delta, verdict = EXCLUDED.verdict, detail = EXCLUDED.detail,
    unparked_at_countdown = EXCLUDED.unparked_at_countdown, peak_unparked = EXCLUDED.peak_unparked,
    ready_for_restart_at = EXCLUDED.ready_for_restart_at, gate_opened = EXCLUDED.gate_opened,
    recorded_at = now()
  RETURNING * INTO v_row;

  IF v_verdict = 'fail' THEN
    PERFORM public.fn_ca_break_scorecard_push(v_row);
  END IF;
  RETURN v_row;
END $$;


ALTER FUNCTION public.fn_ca_record_break_scorecard(p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_ca_record_engine_deploy_attempt(text, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_record_engine_deploy_attempt(p_target_sha text, p_shipped boolean, p_reason text DEFAULT NULL::text, p_run_id text DEFAULT NULL::text, p_actor text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id bigint;
BEGIN
  IF p_target_sha IS NULL OR length(btrim(p_target_sha)) = 0 THEN
    RAISE EXCEPTION 'fn_ca_record_engine_deploy_attempt: p_target_sha is required';
  END IF;

  INSERT INTO public.ca_engine_deploy_attempts (run_id, target_sha, shipped, reason, actor)
  VALUES (p_run_id, left(btrim(p_target_sha), 40), COALESCE(p_shipped, false),
          left(COALESCE(p_reason, ''), 500), left(COALESCE(p_actor, ''), 120))
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.fn_ca_record_engine_deploy_attempt(p_target_sha text, p_shipped boolean, p_reason text, p_run_id text, p_actor text) OWNER TO postgres;

--
-- Name: fn_ca_record_engine_deploy_start(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_record_engine_deploy_start(p_run_id text, p_target_sha text, p_actor text DEFAULT NULL::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v TIMESTAMPTZ;
BEGIN
  INSERT INTO public.ca_engine_deploy_runs_started (run_id, target_sha, actor)
  VALUES (p_run_id, p_target_sha, p_actor)
  ON CONFLICT (run_id) DO UPDATE SET target_sha = EXCLUDED.target_sha
  RETURNING started_at INTO v;
  RETURN v;
END $$;


