--
-- Name: fn_ca_refund_entitlement_commit_valid(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_refund_entitlement_commit_valid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ent_count bigint;
  v_ent_amount numeric;
  v_wallet_count bigint;
  v_wallet_amount numeric;
  v_rows integer;
BEGIN
  IF NEW.entitlement_kind='wallet_charge' THEN
    SELECT count(*) INTO v_rows FROM public.chip_ledger l
     WHERE l.id=NEW.source_ledger_id
       AND l.tournament_id=NEW.tournament_id
       AND l.club_id=NEW.refund_wallet_club_id
       AND l.from_type='player_wallet' AND l.from_entity_id=NEW.user_id
       AND l.to_type='prize_liability'
       AND l.to_entity_id=NEW.tournament_id
       AND lower(l.category)=NEW.charge_category
       AND l.amount=NEW.gross;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'wallet charge entitlement lost its exact source ledger'
        USING ERRCODE = 'P0404';
    END IF;
    SELECT count(*),round(COALESCE(sum(e.gross),0),2)
      INTO v_ent_count,v_ent_amount
      FROM public.tournament_refund_entitlements e
     WHERE e.tournament_id=NEW.tournament_id AND e.user_id=NEW.user_id
       AND e.entitlement_kind='wallet_charge'
       AND e.charge_category=NEW.charge_category;
    SELECT count(*),round(COALESCE(sum(w.amount),0),2)
      INTO v_wallet_count,v_wallet_amount
      FROM public.wallet_transactions w
     WHERE w.related_entity_id=NEW.tournament_id AND w.user_id=NEW.user_id
       AND w.type='debit' AND lower(w.category)=NEW.charge_category;
    IF v_ent_count IS DISTINCT FROM v_wallet_count
       OR v_ent_amount IS DISTINCT FROM v_wallet_amount THEN
      RAISE EXCEPTION
        'wallet charge entitlement and reporting debit do not commit together'
        USING ERRCODE = 'P0404';
    END IF;
  ELSIF NEW.entitlement_kind='satellite_seat' THEN
    SELECT count(*) INTO v_rows FROM public.chip_ledger l
     WHERE l.id=NEW.source_ledger_id
       AND l.club_id=NEW.refund_wallet_club_id
       AND l.from_type='prize_liability'
       AND l.from_entity_id=NEW.source_satellite_id
       AND l.to_type='prize_liability'
       AND l.to_entity_id=NEW.tournament_id
       AND l.amount=NEW.gross
       AND l.metadata->>'user_id'=NEW.user_id::text
       AND l.metadata->>'registration_id'=NEW.registration_id::text;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'satellite seat entitlement lost its exact pool transfer'
        USING ERRCODE = 'P0404';
    END IF;
  ELSE
    SELECT count(*) INTO v_rows
      FROM public.chip_ledger l
      JOIN public.tournament_tickets tk ON tk.id=NEW.source_ticket_id
     WHERE l.id=NEW.source_ledger_id
       AND l.tournament_id=NEW.tournament_id
       AND l.club_id=NEW.refund_wallet_club_id
       AND l.from_type='escrow' AND l.from_entity_id=NEW.source_ticket_id
       AND l.to_type='prize_liability'
       AND l.to_entity_id=NEW.tournament_id
       AND l.category='ticket_redeem' AND l.amount=NEW.gross
       AND l.metadata->>'user_id'=NEW.user_id::text
       AND l.metadata->>'registration_id'=NEW.registration_id::text
       AND tk.holder_id=NEW.user_id
       AND tk.status='redeemed'
       AND tk.redemption_mode='tournament_entry_only'
       AND tk.value=NEW.gross
       AND tk.entry_prize=NEW.refund_prize
       AND tk.entry_bounty=NEW.refund_bounty
       AND tk.entry_fee=NEW.refund_fee
       AND tk.source_satellite_id=NEW.source_satellite_id;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION
        'tournament-ticket entitlement lost its exact admission transfer'
        USING ERRCODE = 'P0404';
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_refund_entitlement_commit_valid() OWNER TO postgres;

--
-- Name: fn_ca_refuse_restricted_entry(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_refuse_restricted_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_scope    text := coalesce(tg_argv[0], 'account');
  v_user     uuid;
  v_enforced boolean := false;
  v_tourney  uuid;
  v_row      public.ca_player_restrictions;
begin
  begin
    v_user := new.user_id;
    if v_user is null then
      return new;
    end if;

    -- THE HOT PATH, and the only thing that runs for a player nobody has
    -- restricted: one probe of the partial index
    -- ca_player_restrictions_active_by_user, which on a platform with no
    -- restrictions is a handful of pages. Everything below it - the
    -- table lookup, the policy read, the observation write - happens
    -- only for a player who genuinely carries a live restriction.
    if not exists (
      select 1 from public.ca_player_restrictions r
       where r.user_id = v_user
         and r.status = 'active'
         and (r.expires_at is null or r.expires_at > now())
    ) then
      return new;
    end if;

    -- THE SCOPE THIS WRITE ACTUALLY BELONGS TO. table_seats carries both
    -- cash and tournament seats and 97.8% of its rows are tournament
    -- ones, so the trigger argument is a DEFAULT, not an answer.
    if tg_table_name = 'table_seats' then
      select t.tournament_id into v_tourney
        from public.tables t where t.id = new.table_id;
      v_scope := case when v_tourney is not null then 'tournaments' else 'cash' end;
    end if;

    if not public.fn_ca_player_restricted(v_user, v_scope) then
      return new;
    end if;

    select restrictions_enforced into v_enforced
      from public.ca_operator_policy limit 1;
    v_enforced := coalesce(v_enforced, false);

    v_row := public.fn_ca_player_restriction_for(v_user, v_scope);

    if not v_enforced then
      insert into public.ca_restriction_observations
        (user_id, scope, restriction_id, table_name, op, would_refuse, detail)
      values (
        v_user, v_scope, v_row.id, tg_table_name, tg_op, true,
        jsonb_build_object(
          'reason_code', v_row.reason_code,
          'restriction_scope', v_row.scope,
          'applied_at', v_row.applied_at,
          'expires_at', v_row.expires_at,
          -- Which of the two ways in this was, so the evidence says
          -- whether the revive path is being used at all.
          'seating_op', tg_op,
          'tournament_id', v_tourney));
      return new;
    end if;

    raise exception
      'PLAYER_RESTRICTED: this account is restricted (%) and cannot % on %.',
      v_row.reason_code, tg_op, tg_table_name
      using errcode = '42501',
            hint = 'An operator applied this restriction. It can be lifted from the Players tab in the operator console.';

  exception
    when insufficient_privilege then
      raise;
    when others then
      return new;
  end;
end;
$$;


ALTER FUNCTION public.fn_ca_refuse_restricted_entry() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_refuse_restricted_entry(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_refuse_restricted_entry() IS 'BEFORE INSERT and BEFORE seat-revive UPDATE guard for table_seats, and BEFORE INSERT for tournament_players. Resolves cash vs tournaments from the seat''s table. Observes while ca_operator_policy.restrictions_enforced is false. Fails OPEN on any internal error.';


--
-- Name: fn_ca_register_diamond_journal_row(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_register_diamond_journal_row(p_tx_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  t record; v_origin text; v_action text; v_label text; v_actorlb text;
  v_before numeric; v_after numeric; v_supply numeric; v_reason text; v_op text;
  v_actor uuid := auth.uid();
BEGIN
  SELECT * INTO t FROM public.diamond_transactions WHERE id = p_tx_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF EXISTS (SELECT 1 FROM public.ca_mint_ledger m WHERE m.diamond_tx_id = t.id) THEN
    RETURN false;
  END IF;
  v_origin := public.fn_ca_diamond_journal_origin(t.type, t.transaction_type, t.source, t.issuance_class, t.amount);
  IF v_origin IS NULL THEN RETURN false; END IF;

  v_action := CASE WHEN t.amount > 0 THEN 'mint' ELSE 'burn' END;
  v_after  := COALESCE(t.balance_after, 0);
  v_before := v_after - t.amount;
  SELECT COALESCE(NULLIF(btrim(p.username), ''), p.full_name, p.id::text)
    INTO v_label FROM public.profiles p WHERE p.id = t.user_id;
  v_label := COALESCE(v_label, t.user_id::text);
  SELECT COALESCE(NULLIF(btrim(p.username), ''), p.full_name, p.id::text)
    INTO v_actorlb FROM public.profiles p WHERE p.id = v_actor;
  v_op := 'diamond-journal:' || v_origin || ':' || t.id::text;
  v_reason := CASE v_action
                WHEN 'mint' THEN 'The Mint issued ' || abs(t.amount)::text || ' diamonds (' || v_origin || '): '
                ELSE 'The Mint retired ' || abs(t.amount)::text || ' diamonds (' || v_origin || '): '
              END
              || COALESCE(NULLIF(btrim(t.description), ''), COALESCE(t.transaction_type, t.type, 'diamond movement'));

  -- NO GLOBAL LOCK ON THIS PATH. It used to hold pg_advisory_xact_lock('ca_mint_ledger:diamonds')
  -- to make supply_after an exact running total. An xact-scoped lock is held until the CALLER
  -- commits, so every diamond movement serialised the whole economy behind whatever transaction
  -- happened to be moving diamonds - and on 2026-09-08, once one transaction could claim several
  -- challenges at once, twenty-four movements died on lock_timeout and went unrecorded.
  --
  -- supply_after is therefore the supply OBSERVED as this row was written, not a serialised
  -- running total: two simultaneous movements may each omit the other. Nothing reads it. The
  -- authority on supply is fn_ca_mint_supply(), which sums the movements, and the identity that
  -- matters - that sum equals what players hold - does not depend on this column at all.
  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = 'diamonds';
  v_supply := v_supply + CASE WHEN v_action = 'mint' THEN abs(t.amount) ELSE -abs(t.amount) END;

  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason,
     performed_by, performed_by_label, chip_ledger_id, diamond_tx_id, created_at)
  VALUES
    (v_op, v_action, 'diamonds', 'player', t.user_id, v_label, abs(t.amount),
     v_before, v_after, v_supply, v_reason,
     v_actor, v_actorlb, NULL, t.id, COALESCE(t.created_at, now()))
  ON CONFLICT (op_id) DO NOTHING;
  RETURN true;
END $$;


ALTER FUNCTION public.fn_ca_register_diamond_journal_row(p_tx_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_register_for_tournament_with_ticket_for(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_register_for_tournament_with_ticket_for(p_tournament_id uuid, p_ticket_id uuid, p_beneficiary_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid:=p_beneficiary_id;
  v_t public.tournaments%ROWTYPE;
  v_ticket public.tournament_tickets%ROWTYPE;
  v_split record;
  v_username text;
  v_registration_id uuid;
  v_ledger_id uuid;
  v_tx_id uuid;
  v_entitlement_id uuid;
  v_resolved_club uuid;
  v_is_bounty boolean;
  v_late_open boolean:=false;
  v_start_chips integer:=0;
  v_seat jsonb;
  v_seat_reason text;
  v_players_before integer;
  v_wallet_rows_before bigint;
  v_wallet_rows_after bigint;
  v_rows integer;
  v_key text;
  v_ticket_use_token uuid:=gen_random_uuid();
  v_previous_ticket_use_token text:=
    current_setting('app.ca_satellite_ticket_use_token',true);
  v_escrow_before public.tournament_escrow%ROWTYPE;
  v_escrow_after public.tournament_escrow%ROWTYPE;
BEGIN
  IF p_tournament_id IS NULL OR p_ticket_id IS NULL OR v_uid IS NULL THEN
    RAISE EXCEPTION 'tournament, ticket and beneficiary ids are required'
      USING ERRCODE='22004';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  PERFORM pg_advisory_xact_lock_shared(530090,1);
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok',false,'reason','platform_frozen');
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF v_t.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  SELECT * INTO v_ticket FROM public.tournament_tickets tk
   WHERE tk.id=p_ticket_id FOR UPDATE;
  IF v_ticket.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_found');
  END IF;
  IF v_ticket.holder_id IS DISTINCT FROM v_uid THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_owned');
  END IF;
  IF v_ticket.redemption_mode IS DISTINCT FROM 'tournament_entry_only' THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_is_wallet_only');
  END IF;

  SELECT count(*) INTO v_rows
    FROM public.tournament_refund_entitlements source_e
    JOIN public.chip_ledger issue_l
      ON issue_l.idempotency_key='tourney:'
           ||source_e.tournament_id::text
           ||':satellite-ticket-return:'||source_e.id::text
     AND issue_l.from_type='prize_liability'
     AND issue_l.from_entity_id=source_e.tournament_id
     AND issue_l.to_type='escrow' AND issue_l.to_entity_id=v_ticket.id
     AND issue_l.club_id=v_ticket.club_id AND issue_l.amount=v_ticket.value
     AND issue_l.category='ticket_issue'
   WHERE source_e.id=v_ticket.source_refund_entitlement_id
     AND source_e.user_id=v_uid
     AND source_e.entitlement_kind IN ('satellite_seat','tournament_ticket')
     AND source_e.gross=v_ticket.value
     AND source_e.refund_prize=v_ticket.entry_prize
     AND source_e.refund_bounty=v_ticket.entry_bounty
     AND source_e.refund_fee=v_ticket.entry_fee
     AND source_e.source_satellite_id=v_ticket.source_satellite_id
     AND source_e.tournament_id=v_ticket.source_tournament_id
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=source_e.id)
     AND (SELECT count(*) FROM public.chip_transactions issue_tx
           WHERE issue_tx.transaction_type='tournament_ticket_issue'
             AND issue_tx.club_id=v_ticket.club_id
             AND issue_tx.from_user_id IS NULL AND issue_tx.to_user_id=v_uid
             AND issue_tx.amount=v_ticket.value
             AND issue_tx.metadata->>'ticket_id'=v_ticket.id::text
             AND issue_tx.metadata->>'entitlement_id'=source_e.id::text
             AND issue_tx.metadata->>'ledger_id'=issue_l.id::text)=1;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament-entry ticket has no exact noncash issue evidence'
      USING ERRCODE='P0404';
  END IF;

  IF v_ticket.status='redeemed' THEN
    SELECT count(*),min(e.id::text)::uuid,min(e.registration_id::text)::uuid
      INTO v_rows,v_entitlement_id,v_registration_id
      FROM public.tournament_refund_entitlements e
      JOIN public.tournament_players tp ON tp.id=e.registration_id
     WHERE e.source_ticket_id=v_ticket.id
       AND e.entitlement_kind='tournament_ticket'
       AND e.tournament_id=p_tournament_id
       AND e.user_id=v_uid
       AND tp.tournament_id=e.tournament_id AND tp.user_id=e.user_id;
    IF v_rows=1 AND v_entitlement_id IS NOT NULL
       AND v_registration_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok',true,'replayed',true,'ticket_id',v_ticket.id,
        'registration_id',v_registration_id,
        'entitlement_id',v_entitlement_id,'wallet_chips_credited',0);
    END IF;
    RETURN jsonb_build_object('ok',false,'reason','ticket_already_used');
  END IF;
  IF v_ticket.status<>'issued' THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_available');
  END IF;

  IF lower(COALESCE(v_t.variant,''))='spin'
     OR (v_t.max_players IS NOT NULL
       AND v_t.max_players>0 AND v_t.max_players<=2) THEN
    RETURN jsonb_build_object('ok',false,'reason','seat_first_variant');
  END IF;
  IF v_t.status='RUNNING' THEN
    v_late_open:=public.fn_tournament_late_registration_open(p_tournament_id)
                 AND NOT COALESCE(v_t.prize_pool_finalized,false);
  END IF;
  IF v_t.status NOT IN ('ANNOUNCED','REGISTERING') AND NOT v_late_open THEN
    RETURN jsonb_build_object('ok',false,'reason','registration_closed');
  END IF;
  IF COALESCE(v_t.prize_pool_finalized,false) THEN
    RETURN jsonb_build_object('ok',false,'reason','target_pool_finalized');
  END IF;
  IF public.fn_tournament_entry_cap_reached(p_tournament_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_full');
  END IF;
  IF EXISTS(SELECT 1 FROM public.tournament_players tp
             WHERE tp.tournament_id=p_tournament_id AND tp.user_id=v_uid) THEN
    RETURN jsonb_build_object('ok',false,'reason','already_registered');
  END IF;

  IF NOT EXISTS(
    SELECT 1 FROM public.club_members m
     WHERE m.club_id=v_ticket.club_id AND m.user_id=v_uid
       AND COALESCE(m.status,'active') IN ('active','approved')) THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_club_membership_inactive');
  END IF;
  IF v_t.club_id IS NOT NULL
     AND v_ticket.club_id IS DISTINCT FROM v_t.club_id THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_club_mismatch');
  END IF;
  IF v_t.union_id IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.union_clubs uc
     WHERE uc.union_id=v_t.union_id AND uc.club_id=v_ticket.club_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_union_mismatch');
  END IF;
  v_resolved_club:=public.fn_tournament_club_for_user(
    v_uid,p_tournament_id,v_ticket.club_id);
  IF v_resolved_club IS DISTINCT FROM v_ticket.club_id THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_source_club_unavailable');
  END IF;

  IF COALESCE(v_t.authorized_to_register,false)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_registration_approvals a
        WHERE a.tournament_id=p_tournament_id AND a.user_id=v_uid)
     AND NOT public.is_club_admin(v_ticket.club_id,v_uid) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized_to_register');
  END IF;
  IF COALESCE(v_t.is_vip_only,false)
     AND NOT EXISTS(
       SELECT 1 FROM public.profiles pr
        WHERE pr.id=v_uid AND COALESCE(pr.is_vip,false)
          AND (pr.vip_expires_at IS NULL OR pr.vip_expires_at>now()))
     AND NOT EXISTS(
       SELECT 1 FROM public.club_members m
        WHERE m.club_id=v_ticket.club_id AND m.user_id=v_uid
          AND m.role IN ('owner','co_owner','admin','agent')) THEN
    RETURN jsonb_build_object('ok',false,'reason','vip_only');
  END IF;

  v_is_bounty:=COALESCE(v_t.is_bounty,false)
            OR COALESCE(v_t.is_pko,false)
            OR COALESCE(v_t.is_mystery_bounty,false);
  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_t.buy_in_amount,v_t.buy_in_fee,v_t.bounty_amount,v_is_bounty);
  IF v_split.charge IS NULL OR v_split.prize IS NULL
     OR v_split.bounty IS NULL OR v_split.rake IS NULL
     OR v_split.charge::text IN ('NaN','Infinity','-Infinity')
     OR v_split.prize::text IN ('NaN','Infinity','-Infinity')
     OR v_split.bounty::text IN ('NaN','Infinity','-Infinity')
     OR v_split.rake::text IN ('NaN','Infinity','-Infinity')
     OR v_split.charge<=0 OR v_split.prize<0
     OR v_split.bounty<0 OR v_split.rake<0
     OR v_split.charge IS DISTINCT FROM
          round(v_split.prize+v_split.bounty+v_split.rake,2)
     OR v_ticket.value IS DISTINCT FROM v_split.charge
     OR v_ticket.entry_prize IS DISTINCT FROM v_split.prize
     OR v_ticket.entry_bounty IS DISTINCT FROM v_split.bounty
     OR v_ticket.entry_fee IS DISTINCT FROM v_split.rake THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_entry_contract_mismatch');
  END IF;

  IF COALESCE(v_t.early_bird_enabled,false)
     AND now()<v_t.start_time AND COALESCE(v_t.early_bird_chips,0)>0 THEN
    v_start_chips:=v_t.early_bird_chips;
  END IF;
  SELECT COALESCE(NULLIF(p.display_name,''),NULLIF(p.username,''),'Player')
    INTO v_username FROM public.profiles p WHERE p.id=v_uid;
  v_username:=COALESCE(v_username,'Player');

  PERFORM public.fn_ca_escrow_apply(p_tournament_id,'ticket admission prelock');
  SELECT * INTO v_escrow_before FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id FOR UPDATE;
  SELECT count(*) INTO v_players_before FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.status::text IN ('registered','playing');
  SELECT count(*) INTO v_wallet_rows_before
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=v_uid;
  IF v_escrow_before.tournament_id IS NULL
     OR v_escrow_before.enforced IS DISTINCT FROM true
     OR v_t.current_players IS DISTINCT FROM v_players_before
     OR v_t.prize_pool IS DISTINCT FROM v_escrow_before.prize_balance
     OR v_t.bounty_pool IS DISTINCT FROM v_escrow_before.bounty_balance
     OR v_t.total_rake IS DISTINCT FROM v_escrow_before.fee_balance THEN
    RAISE EXCEPTION 'ticket admission found divergent tournament escrow'
      USING ERRCODE='P0404';
  END IF;

  INSERT INTO public.tournament_players(
    tournament_id,user_id,username,chips,status,current_bounty,
    mystery_bounty_value,bounties_collected,bounty_winnings,
    club_id,is_satellite_qualifier,source_satellite_id)
  VALUES(
    p_tournament_id,v_uid,v_username,v_start_chips,'registered',
    v_split.bounty,0,0,0,v_ticket.club_id,true,v_ticket.source_satellite_id)
  RETURNING id INTO v_registration_id;

  v_key:='ticket:'||v_ticket.id::text||':tournament:'
         ||p_tournament_id::text||':entry';
  INSERT INTO public.chip_ledger(
    performed_by,from_type,from_entity_id,from_label,
    to_type,to_entity_id,to_label,amount,category,club_id,tournament_id,
    idempotency_key,settlement_id,actor_service,description,metadata,
    pre_from_balance,post_from_balance,pre_to_balance,post_to_balance)
  VALUES(
    v_uid,'escrow',v_ticket.id,'tournament entry ticket',
    'prize_liability',p_tournament_id,'tournaments escrow',
    v_ticket.value,'ticket_redeem',v_ticket.club_id,p_tournament_id,
    v_key,'ticket-entry:'||v_ticket.id::text,
    'fn_register_for_tournament_with_ticket',
    'Tournament-entry ticket committed to tournament admission',
    jsonb_build_object(
      'kind','tournament_entry_ticket_admission','ticket_id',v_ticket.id,
      'user_id',v_uid,'registration_id',v_registration_id,
      'source_tournament_id',v_ticket.source_tournament_id,
      'source_satellite_id',v_ticket.source_satellite_id,
      'entry_prize',v_ticket.entry_prize,
      'entry_bounty',v_ticket.entry_bounty,'entry_fee',v_ticket.entry_fee),
    v_ticket.value,0,
    round(v_escrow_before.prize_balance+v_escrow_before.bounty_balance
          +v_escrow_before.fee_balance,2),
    round(v_escrow_before.prize_balance+v_escrow_before.bounty_balance
          +v_escrow_before.fee_balance+v_ticket.value,2))
  RETURNING id INTO v_ledger_id;

  PERFORM public.fn_ca_escrow_apply(
    p_tournament_id,'tournament-entry ticket admission',
    p_gross_in=>v_ticket.value,p_bounty_in=>v_ticket.entry_bounty);
  IF v_ticket.entry_fee>0 THEN
    INSERT INTO public.rake_records(
      hand_id,table_id,club_id,rake_amount,pot_size,num_players,
      bbj_contribution,is_tournament,tournament_id,source,metadata)
    VALUES(
      NULL,NULL,v_ticket.club_id,v_ticket.entry_fee,v_ticket.value,1,
      0,true,p_tournament_id,'fn_register_for_tournament_with_ticket',
      jsonb_build_object(
        'kind','tournament_ticket_entry_fee','user_id',v_uid,
        'registration_id',v_registration_id,'ticket_id',v_ticket.id));
  END IF;

  UPDATE public.tournaments
     SET current_players=v_players_before+1,
         prize_pool=round(v_t.prize_pool+v_ticket.entry_prize,2),
         bounty_pool=round(v_t.bounty_pool+v_ticket.entry_bounty,2),
         total_rake=round(v_t.total_rake+v_ticket.entry_fee,2),
         updated_at=now()
   WHERE id=p_tournament_id
     -- The canonical roster trigger has already counted the row inserted
     -- above. Require that exact post-insert count instead of expecting the
     -- stale pre-insert cache and then reporting a false registration race.
     AND current_players IS NOT DISTINCT FROM v_players_before+1
     AND prize_pool IS NOT DISTINCT FROM v_t.prize_pool
     AND bounty_pool IS NOT DISTINCT FROM v_t.bounty_pool
     AND total_rake IS NOT DISTINCT FROM v_t.total_rake;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'ticket admission tournament cache changed'
      USING ERRCODE='40001';
  END IF;

  INSERT INTO public.tournament_ticket_admission_authorizations(
    token,ticket_id,tournament_id,user_id,registration_id)
  VALUES(
    v_ticket_use_token,v_ticket.id,p_tournament_id,v_uid,v_registration_id);

  PERFORM set_config(
    'app.ca_satellite_ticket_use_token',v_ticket_use_token::text,true);
  UPDATE public.tournament_tickets
     SET status='redeemed',redeemed_at=transaction_timestamp()
   WHERE id=v_ticket.id AND status='issued';
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  PERFORM set_config(
    'app.ca_satellite_ticket_use_token',
    COALESCE(v_previous_ticket_use_token,''),true);
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament-entry ticket changed during admission'
      USING ERRCODE='40001';
  END IF;
  IF EXISTS(
    SELECT 1 FROM public.tournament_ticket_admission_authorizations a
     WHERE a.token=v_ticket_use_token) THEN
    RAISE EXCEPTION
      'tournament-entry ticket authorization was not consumed by admission'
      USING ERRCODE='P0404';
  END IF;

  INSERT INTO public.tournament_refund_entitlements(
    tournament_id,user_id,entitlement_kind,charge_category,
    refund_wallet_club_id,gross,refund_prize,refund_bounty,refund_fee,
    source_ledger_id,registration_id,source_satellite_id,source_award_place,
    source_ticket_id,escrow_bucket,evidence_kind,created_at)
  VALUES(
    p_tournament_id,v_uid,'tournament_ticket','tournament_ticket',
    v_ticket.club_id,v_ticket.value,v_ticket.entry_prize,
    v_ticket.entry_bounty,v_ticket.entry_fee,v_ledger_id,
    v_registration_id,v_ticket.source_satellite_id,NULL,v_ticket.id,
    'ticket_gross','atomic_tournament_ticket',transaction_timestamp())
  RETURNING id INTO v_entitlement_id;

  INSERT INTO public.chip_transactions(
    club_id,from_user_id,to_user_id,amount,transaction_type,notes,
    balance_after,metadata)
  VALUES(
    v_ticket.club_id,v_uid,NULL,v_ticket.value,
    'tournament_ticket_entry','Tournament-Entry Ticket Used',NULL,
    jsonb_build_object(
      'ticket_id',v_ticket.id,'holder_id',v_uid,
      'target_tournament_id',p_tournament_id,
      'registration_id',v_registration_id,
      'entitlement_id',v_entitlement_id,'ledger_id',v_ledger_id,
      'idempotency_key',v_key,'wallet_chips_credited',0))
  RETURNING id INTO v_tx_id;

  IF v_late_open THEN
    BEGIN
      v_seat:=public.fn_seat_late_registrant(p_tournament_id,v_uid);
    EXCEPTION WHEN SQLSTATE '55000' THEN
      PERFORM public.fn_create_late_registration_capacity(p_tournament_id);
      v_seat:=public.fn_seat_late_registrant(p_tournament_id,v_uid);
    END;
    v_seat_reason:=v_seat->>'reason';
    IF NOT COALESCE((v_seat->>'ok')::boolean,false)
       AND COALESCE(v_seat_reason,'')<>'already_seated_or_missing' THEN
      PERFORM public.fn_create_late_registration_capacity(p_tournament_id);
      v_seat:=public.fn_seat_late_registrant(p_tournament_id,v_uid);
      v_seat_reason:=v_seat->>'reason';
      IF NOT COALESCE((v_seat->>'ok')::boolean,false)
         AND COALESCE(v_seat_reason,'')<>'already_seated_or_missing' THEN
        RAISE EXCEPTION
          'Late ticket admission could not seat the player (%)',
          COALESCE(v_seat_reason,'unknown') USING ERRCODE='55000';
      END IF;
    END IF;
    PERFORM public.fn_emit_tournament_manager_wake(
      p_tournament_id,'late_ticket_registration');
  END IF;

  SELECT * INTO v_escrow_after FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id;
  SELECT count(*) INTO v_wallet_rows_after
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=v_uid;
  IF v_escrow_after.prize_balance IS DISTINCT FROM
       round(v_escrow_before.prize_balance+v_ticket.entry_prize,2)
     OR v_escrow_after.bounty_balance IS DISTINCT FROM
       round(v_escrow_before.bounty_balance+v_ticket.entry_bounty,2)
     OR v_escrow_after.fee_balance IS DISTINCT FROM
       round(v_escrow_before.fee_balance+v_ticket.entry_fee,2)
     OR v_wallet_rows_after IS DISTINCT FROM v_wallet_rows_before THEN
    RAISE EXCEPTION 'ticket admission did not preserve exact noncash rails'
      USING ERRCODE='P0404';
  END IF;

  RETURN jsonb_build_object(
    'ok',true,'replayed',false,'ticket_id',v_ticket.id,
    'registration_id',v_registration_id,'entitlement_id',v_entitlement_id,
    'ledger_id',v_ledger_id,'transaction_id',v_tx_id,
    'ticket_value',v_ticket.value,'wallet_chips_credited',0,
    'prize_contribution',v_ticket.entry_prize,
    'bounty_contribution',v_ticket.entry_bounty,
    'fee_contribution',v_ticket.entry_fee,'late_registration',v_late_open,
    'seat',v_seat);
END;
$$;


ALTER FUNCTION public.fn_ca_register_for_tournament_with_ticket_for(p_tournament_id uuid, p_ticket_id uuid, p_beneficiary_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_register_issuance_leg(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_register_issuance_leg(p_ledger_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  l record; v_action text; v_holder_type text; v_holder uuid; v_label text;
  v_before numeric; v_after numeric; v_supply numeric; v_reason text; v_op text;
  v_outside text[] := public.fn_ca_noncirculating_chip_stores();
BEGIN
  SELECT * INTO l FROM public.chip_ledger WHERE id = p_ledger_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF EXISTS (SELECT 1 FROM public.ca_mint_ledger m WHERE m.chip_ledger_id = l.id) THEN
    RETURN false;
  END IF;
  IF l.category = 'correction' AND l.metadata->>'posted_via' = 'fn_ca_post_correction' THEN
    RETURN false;  -- a correction moves no balance (a_correction_is_not_a_mint)
  END IF;
  IF l.from_type = ANY (v_outside) AND NOT (l.to_type = ANY (v_outside)) THEN
    v_action := 'mint'; v_holder := l.to_entity_id;
    v_holder_type := CASE l.to_type
      WHEN 'club_treasury' THEN 'club' WHEN 'club_wallet' THEN 'club'
      WHEN 'union_bank' THEN 'union' WHEN 'union_wallet' THEN 'union'
      WHEN 'player_wallet' THEN 'player' WHEN 'promo_wallet' THEN 'player'
      ELSE 'circulation' END;
  ELSIF l.to_type = ANY (v_outside) AND NOT (l.from_type = ANY (v_outside)) THEN
    v_action := 'burn'; v_holder := l.from_entity_id;
    v_holder_type := CASE l.from_type
      WHEN 'club_treasury' THEN 'club' WHEN 'club_wallet' THEN 'club'
      WHEN 'union_bank' THEN 'union' WHEN 'union_wallet' THEN 'union'
      WHEN 'player_wallet' THEN 'player' WHEN 'promo_wallet' THEN 'player'
      ELSE 'circulation' END;
  ELSE
    RETURN false;  -- store to store, or circulating to circulating
  END IF;
  -- The autoledger stamps a union wallet's row with the union id; a union is
  -- also a row in clubs (is_union), so resolve by what the id actually is.
  IF v_holder_type = 'club' AND EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = v_holder AND COALESCE(c.is_union, false)) THEN
    v_holder_type := 'union';
  END IF;
  IF v_holder IS NULL THEN
    v_holder_type := 'circulation';
  END IF;
  IF v_holder_type = 'circulation' THEN
    v_holder := '00000000-0000-0000-0000-00000000c1c0';  -- the circulation sentinel (the house is ...d1a0)
  END IF;
  v_label := CASE v_holder_type
    WHEN 'club'   THEN (SELECT c.name FROM public.clubs c WHERE c.id = v_holder)
    WHEN 'union'  THEN COALESCE((SELECT u.name FROM public.unions u WHERE u.id = v_holder), (SELECT c.name FROM public.clubs c WHERE c.id = v_holder))
    WHEN 'player' THEN (SELECT COALESCE(NULLIF(btrim(p.username), ''), p.full_name, p.id::text) FROM public.profiles p WHERE p.id = v_holder)
    ELSE 'circulation' END;
  -- A leg written by hand (a linked compensating entry) carries no balances;
  -- the register still wants a pair, so the pair is the amount itself.
  /* A door that wrote its own register row but did not link the leg
     (fn_ca_burn looks the leg up by a shape it does not always match):
     adopt that row rather than write a second one. Same action, holder,
     amount, asset, within five seconds of the leg, not yet linked. */
  UPDATE public.ca_mint_ledger m
     SET chip_ledger_id = l.id
   WHERE m.id = (SELECT m2.id FROM public.ca_mint_ledger m2
                  WHERE m2.chip_ledger_id IS NULL AND m2.asset = 'chips' AND m2.action = v_action
                    AND m2.amount = l.amount AND m2.holder_id = v_holder
                    AND m2.created_at BETWEEN l.created_at - interval '5 seconds' AND l.created_at + interval '5 seconds'
                  ORDER BY m2.created_at LIMIT 1);
  IF FOUND THEN RETURN false; END IF;
  v_before := COALESCE(CASE WHEN v_action = 'mint' THEN l.pre_to_balance ELSE l.pre_from_balance END, 0);
  v_after  := COALESCE(CASE WHEN v_action = 'mint' THEN l.post_to_balance ELSE l.post_from_balance END,
                       v_before + CASE WHEN v_action = 'mint' THEN l.amount ELSE -l.amount END);
  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
       + CASE WHEN v_action = 'mint' THEN l.amount ELSE -l.amount END
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = 'chips';
  v_op := 'ledger:' || l.id::text;
  v_reason := left(COALESCE(NULLIF(btrim(l.description), ''), l.category) || ' (' || l.category
              || CASE WHEN l.idempotency_key IS NOT NULL THEN ', key ' || l.idempotency_key ELSE '' END
              || '; registered from the journal leg)', 500);
  IF length(btrim(v_reason)) < 10 THEN v_reason := v_reason || ' - registered from the journal'; END IF;
  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason, performed_by, performed_by_label, db_role, chip_ledger_id, created_at)
  VALUES (v_op, v_action, 'chips', v_holder_type, v_holder, v_label, l.amount,
          v_before, v_after, v_supply, v_reason, l.performed_by, COALESCE(l.actor_service, l.db_role), l.db_role, l.id, l.created_at)
  ON CONFLICT (op_id) DO NOTHING;
  RETURN true;
END;
$$;


ALTER FUNCTION public.fn_ca_register_issuance_leg(p_ledger_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_reject_automated_user_club_row(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_reject_automated_user_club_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_club_id uuid;
  v_user_id uuid;
  v_automated boolean := false;
BEGIN
  IF TG_TABLE_NAME = 'club_members' THEN
    v_club_id := NEW.club_id;
    v_user_id := NEW.user_id;
    v_automated := COALESCE(NEW.is_bot, false);
  ELSIF TG_TABLE_NAME = 'agents' THEN
    v_club_id := NEW.club_id;
    v_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'table_seats' THEN
    -- A historical/departed seat remains immutable evidence. Only a live seat
    -- can put an automated player back onto a user-created club table.
    IF NEW.left_at IS NOT NULL THEN RETURN NEW; END IF;
    SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = NEW.table_id;
    v_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'tournament_players' THEN
    SELECT t.club_id INTO v_club_id
      FROM public.tournaments t WHERE t.id = NEW.tournament_id;
    v_user_id := NEW.user_id;
  ELSE
    RAISE EXCEPTION 'Unsupported Automated-Club Guard Table: %', TG_TABLE_NAME;
  END IF;

  v_automated := v_automated OR COALESCE(
    (SELECT p.is_horse FROM public.profiles p WHERE p.id = v_user_id), false
  );

  IF v_automated AND NOT public.fn_ca_house_board_allows_automation(v_club_id) THEN
    RAISE EXCEPTION 'AUTOMATED_PLAYER_HOUSE_BOARD_ONLY: Automated Players Cannot Enter A User-Created Club'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_reject_automated_user_club_row() OWNER TO postgres;

--
-- Name: fn_ca_reject_manual_adjustment(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_reject_manual_adjustment(p_id uuid, p_note text, p_rejecter uuid DEFAULT NULL::uuid, p_rejecter_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rejecter uuid := COALESCE(p_rejecter, auth.uid());
  v_label    text := COALESCE(NULLIF(btrim(p_rejecter_label), ''),
                              NULLIF(current_setting('application_name', true), ''),
                              session_user::text);
  v_row      public.ca_manual_adjustments%ROWTYPE;
BEGIN
  IF NOT public.fn_ca_caller_is_management() THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'not_management');
  END IF;
  IF v_rejecter IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'rejecter_required');
  END IF;

  UPDATE public.ca_manual_adjustments
     SET status = 'rejected', rejected_by = v_rejecter, rejected_at = now(),
         decision_note = NULLIF(btrim(p_note), '')
   WHERE id = p_id AND status = 'proposed'
   RETURNING * INTO v_row;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'not_proposed', 'adjustment_id', p_id);
  END IF;

  -- resolved_by references auth.users; a named service actor is not one.
  UPDATE public.financial_alerts
     SET resolved = true, resolved_at = now(), resolved_by = auth.uid()
   WHERE source = 'ca_manual_adjustments'
     AND resolved IS NOT TRUE
     AND context ->> 'dedupe_key' = 'adj:' || p_id::text;

  RETURN jsonb_build_object('ok', true, 'adjustment_id', p_id, 'status', v_row.status,
    'rejected_by', v_rejecter, 'rejected_by_label', v_label, 'rejected_at', v_row.rejected_at);
END $$;


ALTER FUNCTION public.fn_ca_reject_manual_adjustment(p_id uuid, p_note text, p_rejecter uuid, p_rejecter_label text) OWNER TO postgres;

--
-- Name: fn_ca_repair_write_failure(bigint, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_repair_write_failure(p_write_failure_id bigint, p_counterparty_type text DEFAULT 'settlement_suspense'::text, p_counterparty_entity uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  f RECORD;
  v_store text;
  v_res jsonb;
  v_inc uuid;
BEGIN
  SELECT * INTO f FROM public.ca_ledger_write_failures WHERE id = p_write_failure_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'write_failure_not_found');
  END IF;

  -- map the failed writer's table.column (kept in the message prefix) to the
  -- ledger account vocabulary; unknown shapes fall back to player/club stores
  v_store := CASE
    WHEN f.message LIKE '%clubs.chip_treasury%'            THEN 'club_treasury'
    WHEN f.message LIKE '%clubs.chip_pool%'                THEN 'club_treasury'
    WHEN f.message LIKE '%clubs.promo_balance%'            THEN 'promo_wallet'
    WHEN f.message LIKE '%club_members.chip_balance%'      THEN 'player_wallet'
    WHEN f.message LIKE '%club_members.promo_balance%'     THEN 'promo_wallet'
    WHEN f.message LIKE '%club_wallets.chip_balance%'      THEN 'club_wallet'
    WHEN f.message LIKE '%union_wallets.chip_balance%'     THEN 'union_bank'
    WHEN f.message LIKE '%union_wallets.%'                 THEN 'union_wallet'
    WHEN f.message LIKE '%agents.agent_wallet_balance%'    THEN 'agent_wallet'
    WHEN f.message LIKE '%agents.promo_wallet_balance%'    THEN 'promo_wallet'
    WHEN f.message LIKE '%bbj_pools.%'                     THEN 'bbj_pool'
    WHEN f.message LIKE '%spin_bonus_pools.%'              THEN 'spin_reserve'
    WHEN f.user_id IS NOT NULL                             THEN 'player_wallet'
    ELSE 'club_treasury' END;

  SELECT id INTO v_inc FROM public.ca_drift_incidents
   WHERE dedupe_key = 'qr:lwf:' || p_write_failure_id::text
   ORDER BY detected_at DESC LIMIT 1;

  v_res := public.fn_ca_post_correction(
    CASE WHEN f.delta >= 0 THEN p_counterparty_type ELSE v_store END,
    CASE WHEN f.delta >= 0 THEN p_counterparty_entity ELSE COALESCE(f.user_id, f.club_id) END,
    CASE WHEN f.delta >= 0 THEN v_store ELSE p_counterparty_type END,
    CASE WHEN f.delta >= 0 THEN COALESCE(f.user_id, f.club_id) ELSE p_counterparty_entity END,
    abs(round(f.delta, 2)),
    COALESCE(p_reason,
      'Compensating entry for swallowed journal row (ca_ledger_write_failures '
      || p_write_failure_id::text || '): ' || left(f.message, 300)),
    v_inc, p_write_failure_id, f.club_id, NULL,
    jsonb_build_object('repaired_via', 'fn_ca_repair_write_failure',
                       'store', v_store, 'original_delta', f.delta));

  IF (v_res->>'ok')::boolean AND v_inc IS NOT NULL THEN
    PERFORM public.fn_ca_incident_action(v_inc, 'resolve',
      'Compensating entry posted via fn_ca_repair_write_failure (chip_ledger '
        || (v_res->>'ledger_id') || ').',
      NULL,
      'Swallowed journal row restored; ledger completeness re-established.',
      'chip_ledger ' || (v_res->>'ledger_id'));
  END IF;

  RETURN v_res || jsonb_build_object('incident_id', v_inc, 'store', v_store);
END $$;


ALTER FUNCTION public.fn_ca_repair_write_failure(p_write_failure_id bigint, p_counterparty_type text, p_counterparty_entity uuid, p_reason text) OWNER TO postgres;

--
-- Name: fn_ca_resolution_needs_a_cause(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_resolution_needs_a_cause() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cause text := btrim(coalesce(NEW.root_cause, ''));
  v_ref   text := btrim(coalesce(NEW.correction_ref, ''));
  v_ok    boolean;
BEGIN
  IF NEW.status <> 'resolved' OR OLD.status = 'resolved' THEN
    RETURN NEW;
  END IF;

  IF length(v_cause) < 40 THEN
    RAISE EXCEPTION
      'An incident is not resolved until the cause is written down. Supply root_cause: what was actually wrong, in a sentence (at least 40 characters). Got %.',
      CASE WHEN v_cause = '' THEN 'nothing' ELSE '"' || v_cause || '"' END
      USING ERRCODE = 'P0404';
  END IF;

  -- 2026-09-01: the auto_repair_status='repaired' bypass is GONE. Any writer
  -- could set that flag in the same UPDATE that resolved, which made the law
  -- optional for exactly the actor it was written to govern (the same shape
  -- as the [allow-revert] token incident of 2026-08-31). The automated
  -- reconciler now writes 'verified: <evidence>' like every other resolver.
  v_ok := v_ref ~* '^(migration\s+\S|PR\s*#\d|chip_ledger\s+\S|correction:\S)'
       OR v_ref ~* '^(ruling:|verified:|no-change-needed:)\s*\S';

  IF NOT v_ok THEN
    RAISE EXCEPTION
      'An incident is not resolved until something stops it happening again. Supply correction_ref as one of: "migration <name>", "PR #<n>", "chip_ledger <id>", "correction:<key>", "ruling: <decision>", "verified: <evidence>", or "no-change-needed: <why>". Got %.',
      CASE WHEN v_ref = '' THEN 'nothing' ELSE '"' || v_ref || '"' END
      USING ERRCODE = 'P0404';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_resolution_needs_a_cause() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_resolution_needs_a_cause(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_resolution_needs_a_cause() IS 'HARD LAW: an incident cannot enter resolved without a root cause of substance and a correction reference naming what prevents recurrence. On the table rather than in fn_ca_incident_action, because fn_ca_auto_reconcile_tick and raw SQL both bypass that function. Added 2026-09-01 at Dan''s instruction.';


--
-- Name: fn_ca_resolve_hand_flag(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_resolve_hand_flag(p_flag_id uuid, p_status text, p_operator_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_flag public.ca_hand_flags%ROWTYPE;
  v_note text := NULLIF(btrim(COALESCE(p_operator_note, '')), '');
BEGIN
  IF p_status NOT IN ('open', 'under_review', 'resolved', 'dismissed') THEN
    RAISE EXCEPTION 'unknown status %', p_status USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_flag FROM public.ca_hand_flags WHERE id = p_flag_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such flag' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.fn_ca_is_club_staff(v_flag.club_id, v_uid) THEN
    RAISE EXCEPTION 'not an operator of this club' USING ERRCODE = '42501';
  END IF;

  IF p_status IN ('resolved', 'dismissed') AND v_note IS NULL THEN
    RAISE EXCEPTION 'closing a flag needs a note the player can read'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.ca_hand_flags
     SET status = p_status,
         operator_note = COALESCE(v_note, operator_note),
         reviewed_by = v_uid,
         reviewed_at = now(),
         updated_at = now()
   WHERE id = p_flag_id
   RETURNING * INTO v_flag;

  INSERT INTO public.audit_trail
    (actor_id, actor_role, action, target_type, target_id, club_id, reason, after_state)
  VALUES (
    v_uid,
    public.fn_ca_club_actor_role(v_flag.club_id, v_uid),
    'hand_flag_' || p_status,
    'hand_flag',
    p_flag_id,
    v_flag.club_id,
    v_note,
    jsonb_build_object(
      'hand_id', v_flag.hand_id,
      'hand_number', v_flag.hand_number,
      'status', v_flag.status
    )
  );

  RETURN to_jsonb(v_flag);
END;
$$;


ALTER FUNCTION public.fn_ca_resolve_hand_flag(p_flag_id uuid, p_status text, p_operator_note text) OWNER TO postgres;

--
-- Name: fn_ca_resolve_unbound_pending_addons(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_resolve_unbound_pending_addons(p_table_id uuid, p_max_buy_in numeric, p_instance_id text, p_lease_generation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_holder text;
  v_generation uuid;
  v_protocol integer;
  v_heartbeat timestamptz;
  v_tournament_id uuid;
  v_addon public.table_pending_addons%ROWTYPE;
  v_resolution record;
  v_rows jsonb := '[]'::jsonb;
BEGIN
  IF p_table_id IS NULL
     OR p_max_buy_in IS NULL
     OR p_max_buy_in <= 0
     OR length(btrim(COALESCE(p_instance_id, ''))) = 0
     OR p_lease_generation IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request');
  END IF;

  /* One lock vocabulary with the durable hand processor. Take it first on
     both paths so two pending-row consumers cannot form a reverse lock order
     through resolve_pending_addon's seat lock. */
  PERFORM pg_advisory_xact_lock(
    hashtextextended('hand-post-commit:' || p_table_id::text, 0)
  );

  SELECT l.instance_id, l.lease_generation, l.protocol_version, l.heartbeat_at
    INTO v_holder, v_generation, v_protocol, v_heartbeat
    FROM public.engine_table_leases l
   WHERE l.table_id = p_table_id
   FOR SHARE;
  IF NOT FOUND
     OR v_protocol IS DISTINCT FROM 2
     OR v_holder IS DISTINCT FROM p_instance_id
     OR v_generation IS DISTINCT FROM p_lease_generation
     OR v_heartbeat < clock_timestamp() - make_interval(
          secs => public.fn_engine_lease_stale_seconds()
        ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'lease_lost',
      'lease_generation', v_generation
    );
  END IF;

  /* Exact hand settlement takes lease -> table as well. Holding this row
     through selection and delivery makes "not frozen" a stable statement. */
  SELECT t.tournament_id INTO v_tournament_id
    FROM public.tables t
   WHERE t.id = p_table_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;
  IF v_tournament_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'cash_table_required');
  END IF;

  FOR v_addon IN
    SELECT a.*
      FROM public.table_pending_addons a
     WHERE a.table_id = p_table_id
       AND a.resolved_at IS NULL
       AND NOT EXISTS (
         SELECT 1
           FROM public.hand_atomic_commits c
          WHERE c.table_id = p_table_id
            AND jsonb_typeof(
                  c.post_commit_payload #> '{pending_addons,ids}'
                ) = 'array'
            AND (c.post_commit_payload #> '{pending_addons,ids}') ? a.id::text
       )
     ORDER BY a.created_at, a.id
     FOR UPDATE
  LOOP
    SELECT * INTO STRICT v_resolution
      FROM public.resolve_pending_addon(v_addon.id, p_max_buy_in);
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'id', v_addon.id,
      'user_id', v_addon.user_id,
      'kind', COALESCE(v_addon.kind, 'addon'),
      'applied', COALESCE(v_resolution.applied, 0),
      'refunded', COALESCE(v_resolution.refunded, 0)
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'table_id', p_table_id,
    'lease_generation', p_lease_generation,
    'resolved', jsonb_array_length(v_rows),
    'rows', v_rows
  );
END;
$$;


ALTER FUNCTION public.fn_ca_resolve_unbound_pending_addons(p_table_id uuid, p_max_buy_in numeric, p_instance_id text, p_lease_generation uuid) OWNER TO postgres;

