--
-- Name: fn_ca_restore_erased_seat_credit(text, uuid, uuid, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_restore_erased_seat_credit(p_key text, p_user_id uuid, p_club_id uuid, p_amount numeric, p_table_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inserted integer; v_after numeric; v_ledger uuid; v_supply numeric; v_label text;
BEGIN
  IF NOT (current_user IN ('postgres', 'service_role')) THEN
    RAISE EXCEPTION 'fn_ca_restore_erased_seat_credit is operator/service only';
  END IF;
  IF p_key IS NULL OR p_user_id IS NULL OR p_club_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'key, user, club and a positive amount are required';
  END IF;

  -- One restoration per erased credit, ever.
  INSERT INTO public.wallet_credit_idempotency (key, user_id, amount)
  VALUES (p_key, p_user_id, p_amount)
  ON CONFLICT (key) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 0 THEN
    RETURN jsonb_build_object('restored', false, 'reason', 'already_restored', 'key', p_key);
  END IF;

  PERFORM public.fn_ensure_club_wallet(p_user_id, p_club_id);

  /* The chips were destroyed by an un-journalled overwrite of the felt (the
     meter recorded that hour as unexplained negative drift). Giving them back
     is issuance, labelled as such: issuance_reserve -> player_wallet, so the
     meter reads a mint with a reason, not a second unexplained move. */
  PERFORM public.fn_ca_declare_ledger('refund', 'issuance_reserve', NULL, NULL, p_key, NULL);
  UPDATE public.club_members
     SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = now()
   WHERE user_id = p_user_id AND club_id = p_club_id
   RETURNING chip_balance INTO v_after;
  IF v_after IS NULL THEN
    RAISE EXCEPTION 'no club wallet for player % in club %', p_user_id, p_club_id;
  END IF;

  INSERT INTO public.chip_transactions (club_id, to_user_id, amount, transaction_type, notes, table_id, balance_after, metadata)
  VALUES (p_club_id, p_user_id, p_amount, 'seat_credit_restored', p_reason, p_table_id, v_after,
          jsonb_build_object('restore_key', p_key, 'source', 'issuance_reserve'));

  SELECT id INTO v_ledger FROM public.chip_ledger
   WHERE idempotency_key = p_key ORDER BY created_at DESC LIMIT 1;
  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) + p_amount
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = 'chips';
  SELECT COALESCE(NULLIF(btrim(p.username), ''), p.full_name, p.id::text)
    INTO v_label FROM public.profiles p WHERE p.id = p_user_id;
  BEGIN
    INSERT INTO public.ca_mint_ledger
      (op_id, action, asset, holder_type, holder_id, holder_label, amount,
       balance_before, balance_after, supply_after, reason, performed_by, performed_by_label, chip_ledger_id)
    VALUES (p_key, 'mint', 'chips', 'player', p_user_id, v_label, p_amount,
            v_after - p_amount, v_after, v_supply, p_reason, NULL, current_user, v_ledger);
  EXCEPTION WHEN unique_violation THEN
    NULL;
  END;

  RETURN jsonb_build_object('restored', true, 'key', p_key, 'user_id', p_user_id,
                            'club_id', p_club_id, 'amount', p_amount, 'balance_after', v_after,
                            'chip_ledger_id', v_ledger);
END;
$$;


ALTER FUNCTION public.fn_ca_restore_erased_seat_credit(p_key text, p_user_id uuid, p_club_id uuid, p_amount numeric, p_table_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: fn_ca_restore_erased_seat_credits(timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_restore_erased_seat_credits(p_since timestamp with time zone, p_until timestamp with time zone DEFAULT now(), p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record; v_n integer := 0; v_sum numeric := 0; v_horses integer := 0; v_rows jsonb := '[]'::jsonb; v_res jsonb;
BEGIN
  IF NOT (current_user IN ('postgres', 'service_role')) THEN
    RAISE EXCEPTION 'fn_ca_restore_erased_seat_credits is operator/service only';
  END IF;
  FOR r IN SELECT * FROM public.fn_ca_find_erased_seat_credits(p_since, p_until) LOOP
    IF r.club_id IS NULL THEN
      CONTINUE;
    END IF;
    IF NOT p_dry_run THEN
      v_res := public.fn_ca_restore_erased_seat_credit(
        r.restore_key, r.user_id, r.club_id, r.amount, r.table_id,
        format('Add-on restored to your club wallet: %s chips applied to your seat at %s were erased by the next hand''s stack write (platform defect 2026-08-31 to 2026-09-04, hand %s to %s)',
               r.amount, r.credited_at, r.prev_hand, r.next_hand));
      IF NOT COALESCE((v_res->>'restored')::boolean, false) THEN
        CONTINUE;
      END IF;
    END IF;
    v_n := v_n + 1; v_sum := v_sum + r.amount;
    IF r.is_horse THEN v_horses := v_horses + 1; END IF;
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'key', r.restore_key, 'user_id', r.user_id, 'club_id', r.club_id, 'amount', r.amount,
      'table_id', r.table_id, 'credited_at', r.credited_at, 'is_horse', r.is_horse));
  END LOOP;
  RETURN jsonb_build_object('dry_run', p_dry_run, 'since', p_since, 'until', p_until,
                            'count', v_n, 'horses', v_horses, 'total', round(v_sum, 2), 'rows', v_rows);
END;
$$;


ALTER FUNCTION public.fn_ca_restore_erased_seat_credits(p_since timestamp with time zone, p_until timestamp with time zone, p_dry_run boolean) OWNER TO postgres;

--
-- Name: fn_ca_restriction_expire_sweep(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_restriction_expire_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_count int;
begin
  update public.ca_player_restrictions
     set status = 'expired'
   where status = 'active'
     and expires_at is not null
     and expires_at <= now();
  get diagnostics v_count = row_count;
  return jsonb_build_object('ok', true, 'expired', v_count);
end;
$$;


ALTER FUNCTION public.fn_ca_restriction_expire_sweep() OWNER TO postgres;

--
-- Name: fn_ca_restriction_list(text, text, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_restriction_list(p_scope text DEFAULT NULL::text, p_status text DEFAULT 'active'::text, p_include_horses boolean DEFAULT true, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_lim   int := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_off   int := greatest(coalesce(p_offset, 0), 0);
  v_rows  jsonb;
  v_total bigint;
begin
  with base as (
    select r.*, p.display_name, p.username,
           coalesce(p.is_horse, false) as is_horse
      from public.ca_player_restrictions r
      left join public.profiles p on p.id = r.user_id
     where (p_scope is null or r.scope = p_scope)
       and (p_status is null or r.status = p_status)
       and (coalesce(p_include_horses, true) or not coalesce(p.is_horse, false))
  )
  select coalesce(jsonb_agg(to_jsonb(x) order by x.applied_at desc, x.id), '[]'::jsonb),
         (select count(*) from base)
    into v_rows, v_total
  from (select * from base order by applied_at desc, id limit v_lim offset v_off) x;

  return jsonb_build_object('ok', true, 'rows', v_rows, 'total', v_total,
                            'limit', v_lim, 'offset', v_off,
                            'includeHorses', coalesce(p_include_horses, true));
end;
$$;


ALTER FUNCTION public.fn_ca_restriction_list(p_scope text, p_status text, p_include_horses boolean, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_ca_restriction_observation_prune(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_restriction_observation_prune(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_days int := least(greatest(coalesce(p_days, 30), 1), 3650);
  v_n    int;
begin
  delete from public.ca_restriction_observations
   where observed_at < now() - make_interval(days => v_days);
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'deleted', v_n, 'days', v_days);
end;
$$;


ALTER FUNCTION public.fn_ca_restriction_observation_prune(p_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_restriction_observation_prune(p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_restriction_observation_prune(p_days integer) IS 'Prunes the restriction observation log by AGE. Schedule through Open Claw (World Hub CLAUDE.md 11.2), NEVER the Claude scheduler (10.9): a task installed from one Claude account is unreachable from the next and reports enabled true while never firing again.';


--
-- Name: fn_ca_restriction_observations(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_restriction_observations(p_hours integer DEFAULT 24, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_h     int := least(greatest(coalesce(p_hours, 24), 1), 720);
  v_lim   int := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_off   int := greatest(coalesce(p_offset, 0), 0);
  v_rows  jsonb;
  v_total bigint;
  v_enf   boolean;
  v_found boolean := false;
begin
  select restrictions_enforced, true into v_enf, v_found
    from public.ca_operator_policy limit 1;

  with base as (
    select o.*, p.display_name, coalesce(p.is_horse, false) as is_horse
      from public.ca_restriction_observations o
      left join public.profiles p on p.id = o.user_id
     where o.observed_at > now() - make_interval(hours => v_h)
  )
  select coalesce(jsonb_agg(to_jsonb(x) order by x.observed_at desc, x.id), '[]'::jsonb),
         (select count(*) from base)
    into v_rows, v_total
  from (select * from base order by observed_at desc, id limit v_lim offset v_off) x;

  return jsonb_build_object('ok', true, 'rows', v_rows, 'total', v_total,
                            'limit', v_lim, 'offset', v_off, 'hours', v_h,
                            -- NULL when there is no policy row to read, never
                            -- false. An unknown switch is not an off switch,
                            -- and this function used to coalesce it to false
                            -- while every other answer on the route reported
                            -- null.
                            'enforced', case when v_found then v_enf else null end);
end;
$$;


ALTER FUNCTION public.fn_ca_restriction_observations(p_hours integer, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_ca_retire_certification_club(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_retire_certification_club(p_club_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club     public.clubs%ROWTYPE;
  v_reason   text := COALESCE(NULLIF(btrim(p_reason), ''), 'cert-cleanup');
  v_retired  numeric := 0;
  v_members  integer := 0;
  v_bad      integer := 0;
  v_tx       integer := 0;
  v_ev       integer := 0;
  v_protected uuid[] := ARRAY[
    'a0000000-0000-0000-0000-000000000001'::uuid,  -- Club JAQK
    'a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid,  -- SHARK CLUB
    '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid,  -- Deep Stack Society
    'fade0000-0000-0000-0000-000000000001'::uuid   -- Midway Union
  ];
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND current_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'service_role_only' USING ERRCODE = '42501';
  END IF;

  IF p_club_id = ANY (v_protected) THEN
    RETURN jsonb_build_object('success', false, 'error', 'that is a real Club Arena estate, not a fixture');
  END IF;

  SELECT * INTO v_club FROM public.clubs WHERE id = p_club_id FOR UPDATE;
  IF v_club.id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'already_gone', true, 'club_id', p_club_id);
  END IF;

  IF v_club.name NOT LIKE 'Crest Cert %' AND v_club.name NOT LIKE 'Preset Crest Cert %' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not a certification fixture by name',
                              'name', v_club.name);
  END IF;
  IF v_club.union_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'a fixture never belongs to a union');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tables t WHERE t.club_id = p_club_id)
     OR EXISTS (SELECT 1 FROM public.tournaments t WHERE t.club_id = p_club_id)
     OR EXISTS (SELECT 1 FROM public.agents a WHERE a.club_id = p_club_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'this club has played: it is not a fixture');
  END IF;

  SELECT count(*) INTO v_members FROM public.club_members m WHERE m.club_id = p_club_id;
  SELECT count(*) INTO v_bad
    FROM public.club_members m
    LEFT JOIN auth.users u ON u.id = m.user_id
   WHERE m.club_id = p_club_id
     AND COALESCE(u.email, '') NOT LIKE '%@smarter-poker.invalid';
  IF v_bad > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'a real member holds this club',
                              'non_cert_members', v_bad);
  END IF;
  IF EXISTS (SELECT 1 FROM public.club_members m
              WHERE m.club_id = p_club_id
                AND (COALESCE(m.chip_balance, 0) <> 0 OR COALESCE(m.promo_balance, 0) <> 0)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'a fixture member still holds chips');
  END IF;

  /* RETIRE THE CHIPS FIRST. chip_retirement is a non-circulating store, so the
     supply meter reads this as a burn and not as chips vanishing. */
  v_retired := round(COALESCE(v_club.chip_treasury, 0)
                   + COALESCE(v_club.chip_pool, 0)
                   + COALESCE(v_club.promo_balance, 0)
                   + COALESCE(v_club.insurance_balance, 0), 2);

  IF v_retired <> 0 THEN
    PERFORM public.fn_ca_declare_ledger('burn', 'chip_retirement', NULL, NULL,
                                        'cert-retire:' || p_club_id::text, NULL);
    UPDATE public.clubs
       SET chip_treasury     = 0,
           chip_pool         = 0,
           promo_balance     = 0,
           insurance_balance = 0,
           updated_at        = now()
     WHERE id = p_club_id;
    PERFORM set_config('app.ledger_category', '', true);
    PERFORM set_config('app.ledger_counterparty', '', true);
  END IF;

  /* Both append-only doors, opened by name and closed again below. */
  PERFORM set_config('app.ledger_maintenance', v_reason || ':' || p_club_id::text, true);
  PERFORM set_config('app.game_management_retention', 'on', true);

  /* Order matters. The journal rows go first (their club still exists, so the
     archive records a complete row). The members go next, while the club is
     still there for the event their removal emits. Then that event, and only
     then the club itself. */
  DELETE FROM public.chip_transactions WHERE club_id = p_club_id;
  GET DIAGNOSTICS v_tx = ROW_COUNT;

  DELETE FROM public.club_members WHERE club_id = p_club_id;

  DELETE FROM public.game_management_events WHERE club_id = p_club_id;
  GET DIAGNOSTICS v_ev = ROW_COUNT;

  DELETE FROM public.clubs WHERE id = p_club_id;

  PERFORM set_config('app.ledger_maintenance', '', true);
  PERFORM set_config('app.game_management_retention', '', true);

  RETURN jsonb_build_object('success', true, 'club_id', p_club_id, 'name', v_club.name,
                            'chips_retired', v_retired, 'members_removed', v_members,
                            'journal_rows_archived', v_tx, 'events_removed', v_ev);
END
$$;


ALTER FUNCTION public.fn_ca_retire_certification_club(p_club_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_retire_certification_club(p_club_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_retire_certification_club(p_club_id uuid, p_reason text) IS 'Retires one Club Create Certification fixture: proves it is a fixture, retires its chips to chip_retirement with a declared journal row, then removes it through the append-only maintenance doors. Refuses the four real estates by id and anything that has played.';


--
-- Name: fn_ca_retry_promo_accruals(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_retry_promo_accruals(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_res jsonb; v_ok int := 0; v_failed int := 0;
BEGIN
  FOR r IN SELECT * FROM public.ca_pending_promo_accruals
           WHERE resolved_at IS NULL ORDER BY created_at
           LIMIT GREATEST(COALESCE(p_limit,200),1)
  LOOP
    BEGIN
      v_res := public.promo_apply_playthrough(r.club_id, r.user_id, r.wagered);
      UPDATE public.ca_pending_promo_accruals
         SET resolved_at = now(), attempts = attempts + 1, last_attempt_at = now(),
             last_error = NULL
       WHERE id = r.id;
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.ca_pending_promo_accruals
         SET attempts = attempts + 1, last_attempt_at = now(), last_error = left(SQLERRM, 500)
       WHERE id = r.id;
      v_failed := v_failed + 1;
    END;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'redriven', v_ok, 'failed', v_failed);
END $$;


ALTER FUNCTION public.fn_ca_retry_promo_accruals(p_limit integer) OWNER TO postgres;

--
-- Name: fn_ca_return_satellite_entitlement_as_ticket(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_return_satellite_entitlement_as_ticket(p_entitlement_id uuid, p_source text, p_description text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_e public.tournament_refund_entitlements%ROWTYPE;
  v_t public.tournaments%ROWTYPE;
  v_tournament_id uuid;
  v_ticket public.tournament_tickets%ROWTYPE;
  v_key text;
  v_before numeric;
  v_rows integer;
  v_ledger_id uuid;
  v_tx_id uuid;
BEGIN
  IF p_entitlement_id IS NULL OR p_source IS NULL
     OR length(btrim(p_source))=0 OR p_description IS NULL
     OR length(btrim(p_description))=0 THEN
    RAISE EXCEPTION 'satellite ticket return received an invalid contract'
      USING ERRCODE = '22003';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.ca_settle_sources s
     WHERE s.source=lower(btrim(p_source))) THEN
    RAISE EXCEPTION 'satellite ticket return source % is not an authority',p_source
      USING ERRCODE = '42501';
  END IF;
  SELECT e.tournament_id INTO v_tournament_id
    FROM public.tournament_refund_entitlements e
   WHERE e.id=p_entitlement_id;
  IF v_tournament_id IS NULL THEN
    RAISE EXCEPTION 'satellite refund entitlement % does not exist',p_entitlement_id
      USING ERRCODE = 'P0002';
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=v_tournament_id FOR UPDATE;
  SELECT * INTO v_e FROM public.tournament_refund_entitlements e
   WHERE e.id=p_entitlement_id FOR UPDATE;
  IF v_e.id IS NULL
     OR v_e.entitlement_kind NOT IN ('satellite_seat','tournament_ticket')
     OR v_e.tournament_id IS DISTINCT FROM v_t.id THEN
    RAISE EXCEPTION
      'entitlement % is not a satellite-funded tournament entry',p_entitlement_id
      USING ERRCODE = 'P0404';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_refund_tranches tr
     WHERE tr.entitlement_id=v_e.id) THEN
    RAISE EXCEPTION 'satellite seat entitlement was incorrectly converted to chips'
      USING ERRCODE = 'P0404';
  END IF;
  SELECT * INTO v_ticket FROM public.tournament_tickets tk
   WHERE tk.source_refund_entitlement_id=v_e.id FOR UPDATE;
  IF FOUND THEN
    SELECT count(*),min(l.id::text)::uuid
      INTO v_rows,v_ledger_id FROM public.chip_ledger l
     WHERE l.idempotency_key='tourney:'||v_e.tournament_id::text
             ||':satellite-ticket-return:'||v_e.id::text
       AND l.from_type='prize_liability'
       AND l.from_entity_id=v_e.tournament_id
       AND l.to_type='escrow' AND l.to_entity_id=v_ticket.id
       AND l.club_id=v_e.refund_wallet_club_id AND l.amount=v_e.gross;
    IF v_rows<>1 OR v_ledger_id IS NULL
       OR (SELECT count(*) FROM public.chip_transactions ct
            WHERE ct.transaction_type='tournament_ticket_issue'
              AND ct.club_id=v_e.refund_wallet_club_id
              AND ct.from_user_id IS NULL AND ct.to_user_id=v_e.user_id
              AND ct.amount=v_e.gross
              AND ct.metadata->>'ticket_id'=v_ticket.id::text
              AND ct.metadata->>'entitlement_id'=v_e.id::text
              AND ct.metadata->>'ledger_id'=v_ledger_id::text) <> 1
       OR v_ticket.status NOT IN ('issued','redeemed')
       OR v_ticket.holder_id IS DISTINCT FROM v_e.user_id
       OR v_ticket.value IS DISTINCT FROM v_e.gross
       OR v_ticket.redemption_mode<>'tournament_entry_only'
       OR v_ticket.source_tournament_id IS DISTINCT FROM v_e.tournament_id
       OR v_ticket.source_satellite_id IS DISTINCT FROM v_e.source_satellite_id
       OR v_ticket.source_refund_entitlement_id IS DISTINCT FROM v_e.id
       OR v_ticket.entry_prize IS DISTINCT FROM v_e.refund_prize
       OR v_ticket.entry_bounty IS DISTINCT FROM v_e.refund_bounty
       OR v_ticket.entry_fee IS DISTINCT FROM v_e.refund_fee THEN
      RAISE EXCEPTION 'satellite ticket replay evidence is incomplete'
        USING ERRCODE = 'P0404';
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'replayed',true,'ticket_id',v_ticket.id,
      'entitlement_id',v_e.id,'value',v_e.gross,
      'refund_prize',v_e.refund_prize,
      'refund_bounty',v_e.refund_bounty,'refund_fee',v_e.refund_fee,
      'refund_wallet_club_id',v_e.refund_wallet_club_id);
  END IF;

  PERFORM public.fn_ca_escrow_apply(
    v_e.tournament_id,'satellite ticket return escrow prelock');
  SELECT round(e.prize_balance+e.bounty_balance+e.fee_balance,2)
    INTO v_before FROM public.tournament_escrow e
   WHERE e.tournament_id=v_e.tournament_id FOR UPDATE;
  IF v_before IS NULL THEN
    RAISE EXCEPTION 'satellite ticket return has no enforced target escrow'
      USING ERRCODE = 'P0404';
  END IF;
  v_ticket.id:=gen_random_uuid();
  INSERT INTO public.tournament_tickets(
    id,club_id,issued_by,holder_id,value,status,note,
    redemption_mode,source_tournament_id,source_satellite_id,
    source_refund_entitlement_id,entry_prize,entry_bounty,entry_fee,created_at)
  VALUES(
    v_ticket.id,v_e.refund_wallet_club_id,
    '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid,
    v_e.user_id,v_e.gross,'issued',
    p_description,'tournament_entry_only',v_e.tournament_id,
    v_e.source_satellite_id,v_e.id,v_e.refund_prize,v_e.refund_bounty,
    v_e.refund_fee,transaction_timestamp())
  RETURNING * INTO v_ticket;
  v_key:='tourney:'||v_e.tournament_id::text
         ||':satellite-ticket-return:'||v_e.id::text;
  INSERT INTO public.chip_ledger(
    performed_by,from_type,from_entity_id,from_label,
    to_type,to_entity_id,to_label,amount,category,club_id,tournament_id,
    idempotency_key,settlement_id,actor_service,description,metadata,
    pre_from_balance,post_from_balance,pre_to_balance,post_to_balance)
  VALUES(
    COALESCE(auth.uid(),'2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
    'prize_liability',v_e.tournament_id,'tournaments escrow',
    'escrow',v_ticket.id,'satellite tournament entry ticket',
    v_e.gross,'ticket_issue',v_e.refund_wallet_club_id,v_e.tournament_id,
    v_key,'satellite-ticket:'||v_ticket.id::text,lower(btrim(p_source)),
    p_description,jsonb_build_object(
      'kind','tournament_entry_ticket_return','ticket_id',v_ticket.id,
      'entitlement_id',v_e.id,'user_id',v_e.user_id,
      'entitlement_kind',v_e.entitlement_kind,
      'source_satellite_id',v_e.source_satellite_id,
      'refund_prize',v_e.refund_prize,'refund_bounty',v_e.refund_bounty,
      'refund_fee',v_e.refund_fee),
    v_before,round(v_before-v_e.gross,2),0,v_e.gross)
  RETURNING id INTO v_ledger_id;
  INSERT INTO public.chip_transactions(
    club_id,from_user_id,to_user_id,amount,transaction_type,notes,
    balance_after,metadata)
  VALUES(
    v_e.refund_wallet_club_id,NULL,v_e.user_id,v_e.gross,
    'tournament_ticket_issue',p_description,NULL,jsonb_build_object(
      'ticket_id',v_ticket.id,'escrow_entity_id',v_ticket.id,
      'holder_id',v_e.user_id,'value',v_e.gross,
      'redemption_mode','tournament_entry_only',
      'source_tournament_id',v_e.tournament_id,
      'source_satellite_id',v_e.source_satellite_id,
      'entitlement_id',v_e.id,'entitlement_kind',v_e.entitlement_kind,
      'ledger_id',v_ledger_id,
      'idempotency_key',v_key))
  RETURNING id INTO v_tx_id;
  PERFORM public.fn_ca_escrow_apply_exact_refund(
    v_e.tournament_id,'satellite seat returned as tournament ticket',
    v_e.refund_prize,v_e.refund_bounty,v_e.refund_fee);
  RETURN jsonb_build_object(
    'ok',true,'replayed',false,'ticket_id',v_ticket.id,
    'entitlement_id',v_e.id,'value',v_e.gross,
    'refund_prize',v_e.refund_prize,
    'refund_bounty',v_e.refund_bounty,'refund_fee',v_e.refund_fee,
    'refund_wallet_club_id',v_e.refund_wallet_club_id,
    'ledger_id',v_ledger_id,'transaction_id',v_tx_id);
END;
$$;


ALTER FUNCTION public.fn_ca_return_satellite_entitlement_as_ticket(p_entitlement_id uuid, p_source text, p_description text) OWNER TO postgres;

--
-- Name: fn_ca_return_unawarded_spin_draws(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_return_unawarded_spin_draws(p_apply boolean DEFAULT false, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r record; v_n int := 0; v_chips numeric := 0; v_bal numeric;
BEGIN
  FOR r IN
    SELECT l.tournament_id, l.club_id,
           round(sum(CASE WHEN l.kind = 'jackpot_draw' THEN -l.amount ELSE 0 END), 2) AS drawn,
           round(sum(CASE WHEN l.kind = 'surplus_return' THEN l.amount ELSE 0 END), 2) AS returned
      FROM public.spin_reserve_ledger l
      JOIN public.tournaments t ON t.id = l.tournament_id
     WHERE t.status IN ('CANCELLED','CANCELED')
       AND l.tournament_id IS NOT NULL
     GROUP BY l.tournament_id, l.club_id
    HAVING round(sum(CASE WHEN l.kind = 'jackpot_draw' THEN -l.amount ELSE 0 END), 2)
         > round(sum(CASE WHEN l.kind = 'surplus_return' THEN l.amount ELSE 0 END), 2)
       AND NOT EXISTS (SELECT 1 FROM public.wallet_transactions w
                        WHERE w.related_entity_id = l.tournament_id
                          AND w.type = 'credit' AND w.category = 'prize')
     ORDER BY 3 DESC
     LIMIT GREATEST(p_limit, 1)
  LOOP
    v_n := v_n + 1;
    v_chips := v_chips + (r.drawn - r.returned);

    IF p_apply THEN
      PERFORM set_config('app.ledger_category', 'refund', true);
      PERFORM set_config('app.ledger_counterparty', 'prize_liability', true);
      PERFORM set_config('app.ledger_counterparty_entity', r.tournament_id::text, true);

      UPDATE public.spin_bonus_pools
         SET balance = balance + (r.drawn - r.returned)
       WHERE club_id = r.club_id
      RETURNING balance INTO v_bal;

      PERFORM set_config('app.ledger_category', '', true);
      PERFORM set_config('app.ledger_counterparty', '', true);
      PERFORM set_config('app.ledger_counterparty_entity', '', true);

      IF FOUND THEN
        INSERT INTO public.spin_reserve_ledger
          (club_id, tournament_id, kind, amount, balance_after, note)
        VALUES (r.club_id, r.tournament_id, 'surplus_return',
                (r.drawn - r.returned), v_bal,
                'spin cancelled without awarding a prize; jackpot draw returned to the reserve');
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'applied', p_apply,
                            'spins', v_n, 'chips_returned', round(v_chips,2));
END;
$$;


ALTER FUNCTION public.fn_ca_return_unawarded_spin_draws(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_return_unawarded_spin_draws(p_apply boolean, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_return_unawarded_spin_draws(p_apply boolean, p_limit integer) IS 'Returns the jackpot draw to the spin reserve for any CANCELLED spin that never credited a prize. Idempotent: acts only where draws exceed draw_returned.';


--
-- Name: fn_ca_satellite_entry_ticket_is_guarded(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_satellite_entry_ticket_is_guarded() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_token uuid := NULLIF(
    current_setting('app.ca_satellite_ticket_use_token',true),'')::uuid;
  v_authorization public.tournament_ticket_admission_authorizations%ROWTYPE;
  v_rows integer;
BEGIN
  IF TG_OP='DELETE' AND OLD.redemption_mode='tournament_entry_only' THEN
    RAISE EXCEPTION 'tournament-entry tickets are durable financial evidence'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP='UPDATE' AND OLD.redemption_mode='tournament_entry_only' THEN
    IF ROW(NEW.id,NEW.club_id,NEW.issued_by,NEW.holder_id,NEW.value,NEW.note,
           NEW.redemption_mode,NEW.source_tournament_id,
           NEW.source_satellite_id,NEW.source_refund_entitlement_id,
           NEW.entry_prize,NEW.entry_bounty,NEW.entry_fee,NEW.created_at,
           NEW.cancelled_at)
       IS DISTINCT FROM
       ROW(OLD.id,OLD.club_id,OLD.issued_by,OLD.holder_id,OLD.value,OLD.note,
           OLD.redemption_mode,OLD.source_tournament_id,
           OLD.source_satellite_id,OLD.source_refund_entitlement_id,
           OLD.entry_prize,OLD.entry_bounty,OLD.entry_fee,OLD.created_at,
           OLD.cancelled_at) THEN
      RAISE EXCEPTION 'tournament-entry ticket identity and rails are immutable'
        USING ERRCODE = '55000';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      IF NOT (OLD.status='issued' AND NEW.status='redeemed'
              AND v_token IS NOT NULL
              AND OLD.redeemed_at IS NULL
              AND NEW.redeemed_at IS NOT NULL
              AND NEW.redeemed_at=transaction_timestamp()) THEN
        RAISE EXCEPTION
          'tournament-entry tickets can only be consumed by tournament admission'
          USING ERRCODE = '42501';
      END IF;
      SELECT * INTO v_authorization
        FROM public.tournament_ticket_admission_authorizations a
       WHERE a.token=v_token AND a.ticket_id=OLD.id
       FOR UPDATE;
      IF v_authorization.token IS NULL
         OR v_authorization.user_id IS DISTINCT FROM OLD.holder_id
         OR NOT EXISTS(
           SELECT 1 FROM public.tournament_players tp
            WHERE tp.id=v_authorization.registration_id
              AND tp.tournament_id=v_authorization.tournament_id
              AND tp.user_id=v_authorization.user_id
              AND tp.status::text IN ('registered','playing')) THEN
        RAISE EXCEPTION
          'tournament-entry ticket has no exact admission authorization'
          USING ERRCODE = '42501';
      END IF;
      DELETE FROM public.tournament_ticket_admission_authorizations a
       WHERE a.token=v_token AND a.ticket_id=OLD.id;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN
        RAISE EXCEPTION
          'tournament-entry ticket admission authorization was not consumed once'
          USING ERRCODE = 'P0404';
      END IF;
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status
       AND NEW.redeemed_at IS DISTINCT FROM OLD.redeemed_at THEN
      RAISE EXCEPTION
        'tournament-entry ticket redemption time is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.fn_ca_satellite_entry_ticket_is_guarded() OWNER TO postgres;

--
-- Name: fn_ca_satellite_settlement_receipt(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_satellite_settlement_receipt(p_tournament_id uuid, p_observed_winner_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_h public.tournament_satellite_settlements%ROWTYPE;
  v_source record;
  v_target record;
  v_source_escrow public.tournament_escrow%ROWTYPE;
  v_rake_settlement record;
  v_field_size integer;
  v_position_count integer;
  v_rows integer;
  v_expected_rows integer;
  v_amount numeric;
  v_rake numeric;
  v_awards jsonb := '[]'::jsonb;
  v_seats jsonb := '[]'::jsonb;
  v_remainder jsonb := NULL;
  v_winner_amount numeric := 0;
  v_source_table_ids uuid[];
  v_source_seat_ids uuid[];
  v_durable_released_ids uuid[];
  v_durable_released_count integer;
BEGIN
  IF p_tournament_id IS NULL OR p_observed_winner_id IS NULL THEN
    RAISE EXCEPTION 'satellite receipt requires tournament and observed winner ids'
      USING ERRCODE = '22004';
  END IF;

  SELECT * INTO v_h
    FROM public.tournament_satellite_settlements s
   WHERE s.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'satellite % has no immutable settlement header',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF v_h.winner_id IS DISTINCT FROM p_observed_winner_id THEN
    RAISE EXCEPTION
      'satellite % receipt winner % differs from observed winner %',
      p_tournament_id, v_h.winner_id, p_observed_winner_id
      USING ERRCODE = '40001';
  END IF;
  IF v_h.receipt_version IS DISTINCT FROM 2 THEN
    RAISE EXCEPTION 'satellite % has unsupported receipt version %',
      p_tournament_id, v_h.receipt_version USING ERRCODE = 'P0404';
  END IF;

  -- Target lifecycle state is intentionally absent from replay. A target may
  -- close after commit without changing what was already delivered.
  PERFORM 1 FROM public.tournaments t
   WHERE t.id IN (p_tournament_id, v_h.target_id)
   ORDER BY CASE WHEN t.id = v_h.target_id THEN 0 ELSE 1 END, t.id
   FOR UPDATE;
  SELECT t.id, t.status, t.variant, t.tournament_type,
         t.satellite_target_id, t.satellite_target, t.satellite_seats,
         t.prize_pool, t.prize_pool_finalized, t.ended_at,
         t.current_players, t.on_break, t.break_started_at, t.break_ends_at
    INTO v_source FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF v_source.id IS NULL THEN
    RAISE EXCEPTION 'satellite % source row is missing',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF upper(COALESCE(v_source.status, '')) <> 'COMPLETED'
     OR COALESCE(v_source.prize_pool_finalized, false) IS NOT TRUE
     OR v_source.ended_at IS NULL
     OR v_source.ended_at IS DISTINCT FROM v_h.source_closed_at
     OR v_source.current_players IS DISTINCT FROM 0
     OR v_source.on_break IS DISTINCT FROM false
     OR v_source.break_started_at IS NOT NULL
     OR v_source.break_ends_at IS NOT NULL THEN
    RAISE EXCEPTION 'satellite % receipt is not attached to one completed close',
      p_tournament_id USING ERRCODE = '55000';
  END IF;
  IF lower(COALESCE(v_source.variant, '')) <> 'satellite'
     AND upper(COALESCE(v_source.tournament_type, '')) <> 'SATELLITE'
     AND v_source.satellite_target_id IS NULL
     AND v_source.satellite_target IS NULL THEN
    RAISE EXCEPTION 'tournament % no longer identifies as a satellite',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF v_source.satellite_target_id IS NOT NULL
     AND v_source.satellite_target IS NOT NULL
     AND v_source.satellite_target_id IS DISTINCT FROM v_source.satellite_target THEN
    RAISE EXCEPTION 'satellite % has conflicting target columns',
      p_tournament_id USING ERRCODE = '23514';
  END IF;
  IF COALESCE(v_source.satellite_target_id, v_source.satellite_target)
       IS DISTINCT FROM v_h.target_id
     OR v_source.prize_pool IS NULL
     OR v_source.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR round(v_source.prize_pool, 2) IS DISTINCT FROM v_h.pool
     OR COALESCE(v_source.satellite_seats, 0) IS DISTINCT FROM v_h.advertised_seats
     OR v_h.pool < v_h.advertised_seats * v_h.ticket_cost
     OR floor(v_h.pool / v_h.ticket_cost)::integer IS DISTINCT FROM v_h.ticket_award_count
     OR round(v_h.pool - v_h.ticket_award_count * v_h.ticket_cost, 2)
          IS DISTINCT FROM v_h.remainder THEN
    RAISE EXCEPTION 'satellite % immutable receipt disagrees with its locked contract',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT t.id,t.buy_in_amount,t.buy_in_fee,t.bounty_amount,t.is_bounty,
         t.is_pko,t.is_mystery_bounty,t.is_premium_spin,t.variant,
         t.tournament_type,t.club_id
    INTO v_target FROM public.tournaments t
   WHERE t.id = v_h.target_id
   FOR SHARE;
  IF v_target.id IS NULL
     OR v_h.target_was_missing IS DISTINCT FROM false
     OR v_h.target_contract_version IS NOT NULL
     OR (v_h.seat_count > 0 AND (
          v_target.buy_in_amount IS DISTINCT FROM v_h.target_buy_in
       OR COALESCE(v_target.buy_in_fee,0) IS DISTINCT FROM v_h.target_fee
       OR COALESCE(v_target.bounty_amount,0) <> 0
       OR COALESCE(v_target.is_bounty,false)
       OR COALESCE(v_target.is_pko,false)
       OR COALESCE(v_target.is_mystery_bounty,false)
       OR COALESCE(v_target.is_premium_spin,false)
       OR lower(COALESCE(v_target.variant,'')) = 'spin'
       OR upper(COALESCE(v_target.tournament_type,'')) = 'SPIN')) THEN
    RAISE EXCEPTION 'satellite % immutable receipt lost its locked target row',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  -- The header is the immutable settlement-time contract. Replay proves that
  -- exact value through its award, transfer and fee evidence. The terminal
  -- hardening migration also freezes the target's economic columns after its
  -- first actual seat, so cancellation and unregister use the same split.

  PERFORM 1 FROM public.tournament_players tp
   WHERE tp.tournament_id IN (p_tournament_id, v_h.target_id)
   ORDER BY tp.tournament_id, tp.id FOR SHARE;
  SELECT count(*), count(DISTINCT tp.position)
    INTO v_field_size, v_position_count
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  IF v_field_size <> v_h.field_size
     OR v_position_count <> v_h.field_size
     OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND (tp.position IS NULL OR tp.position < 1 OR tp.position > v_h.field_size)
    ) OR NOT EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.user_id = v_h.winner_id
          AND tp.position = 1 AND tp.status::text = 'winner'
          AND tp.eliminated_at IS NULL
          AND tp.elimination_sequence IS NULL
     ) OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.position > 1
          AND tp.status::text IS DISTINCT FROM 'eliminated'
     ) THEN
    RAISE EXCEPTION 'satellite % receipt has no exact final standings',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- A satellite is not terminal while its felt still owns live seats. The
  -- header freezes every source table and seat identity, plus the subset that
  -- this settlement itself released. Replay requires the exact same durable
  -- rows, every table closed at zero and no live seat left behind.
  PERFORM 1 FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY tb.id FOR UPDATE;
  PERFORM 1
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY ts.table_id, ts.id FOR UPDATE OF ts;
  SELECT COALESCE(array_agg(tb.id ORDER BY tb.id), ARRAY[]::uuid[])
    INTO v_source_table_ids
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id;
  SELECT COALESCE(array_agg(ts.id ORDER BY ts.table_id, ts.id), ARRAY[]::uuid[])
    INTO v_source_seat_ids
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id;
  SELECT COALESCE(array_agg(ts.id ORDER BY ts.table_id, ts.id), ARRAY[]::uuid[])
    INTO v_durable_released_ids
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id
     AND ts.left_at IS NOT DISTINCT FROM v_h.settled_at
     AND ts.status IS NOT DISTINCT FROM 'left'
     AND ts.leave_pending IS FALSE
     AND ts.is_sitting_out IS FALSE
     AND ts.is_away IS FALSE
     AND ts.sit_out_at IS NULL
     AND ts.scheduled_leave_hands IS NULL;
  v_durable_released_count := cardinality(v_durable_released_ids);
  IF v_source_table_ids IS DISTINCT FROM v_h.source_table_ids
     OR cardinality(v_source_table_ids) IS DISTINCT FROM v_h.source_table_count
     OR v_source_seat_ids IS DISTINCT FROM v_h.source_seat_ids
     OR cardinality(v_source_seat_ids) IS DISTINCT FROM v_h.source_seat_count
     OR v_durable_released_ids IS DISTINCT FROM v_h.released_seat_ids
     OR v_durable_released_count IS DISTINCT FROM v_h.released_seat_count
     OR EXISTS (
       SELECT 1 FROM public.tables tb
        WHERE tb.tournament_id = p_tournament_id
          AND (lower(COALESCE(tb.status::text, '')) <> 'closed'
            OR lower(COALESCE(tb.lifecycle, '')) <> 'closed'
            OR tb.current_players IS DISTINCT FROM 0
            OR tb.terminal_closed_at IS DISTINCT FROM v_h.source_closed_at)
     ) OR EXISTS (
       SELECT 1
        FROM public.table_seats ts
         JOIN public.tables tb ON tb.id = ts.table_id
        WHERE tb.tournament_id = p_tournament_id
          AND (ts.left_at IS NULL
            OR ts.status IS DISTINCT FROM 'left'
            OR ts.leave_pending IS DISTINCT FROM false
            OR ts.is_sitting_out IS DISTINCT FROM false
            OR ts.is_away IS DISTINCT FROM false
            OR ts.sit_out_at IS NOT NULL
            OR ts.scheduled_leave_hands IS NOT NULL)
     ) THEN
    RAISE EXCEPTION
      'satellite % source table or seat closeout differs from its immutable receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_rows
    FROM public.tournament_satellite_awards a
   WHERE a.tournament_id = p_tournament_id;
  IF v_rows <> v_h.ticket_award_count
     OR (SELECT count(*) FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id AND a.delivery_kind = 'seat')
          <> v_h.seat_count
     OR (SELECT count(*) FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id AND a.delivery_kind = 'cash')
          <> v_h.cash_ticket_count
     OR EXISTS (
       SELECT 1
         FROM public.tournament_satellite_awards a
         JOIN public.tournament_players tp
           ON tp.tournament_id = p_tournament_id AND tp.position = a.place
        WHERE a.tournament_id = p_tournament_id
          AND (a.place > v_h.ticket_award_count
            OR a.user_id IS DISTINCT FROM tp.user_id
            OR a.amount IS DISTINCT FROM v_h.ticket_cost)
     ) OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.position BETWEEN 1 AND v_h.ticket_award_count
          AND NOT EXISTS (
            SELECT 1 FROM public.tournament_satellite_awards a
             WHERE a.tournament_id = p_tournament_id
               AND a.place = tp.position AND a.user_id = tp.user_id)
     ) THEN
    RAISE EXCEPTION 'satellite % has incomplete or non-contiguous award lines',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- Every line has one exact payout row. Cash lines additionally prove the
  -- wallet credit and closed obligation; seats prove the registration and
  -- source-to-target funding leg below.
  IF EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_payouts p ON p.id = a.payout_id
     WHERE a.tournament_id = p_tournament_id
       AND (p.id IS NULL
         OR p.tournament_id IS DISTINCT FROM p_tournament_id
         OR p.user_id IS DISTINCT FROM a.user_id
         OR p."position" IS DISTINCT FROM a.place
         OR p.amount IS DISTINCT FROM a.amount
         OR p.source IS DISTINCT FROM a.payout_source
         OR p.idempotency_key IS DISTINCT FROM a.idempotency_key)
  ) THEN
    RAISE EXCEPTION 'satellite % award line has no exact payout evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_obligations o ON o.id = a.obligation_id
      LEFT JOIN public.wallet_credit_idempotency k ON k.key = a.idempotency_key
     WHERE a.tournament_id = p_tournament_id
       AND a.delivery_kind = 'cash'
       AND (o.id IS NULL
         OR o.tournament_id IS DISTINCT FROM p_tournament_id
         OR o.kind IS DISTINCT FROM a.obligation_kind
         OR o.place IS DISTINCT FROM a.place
         OR o.user_id IS DISTINCT FROM a.user_id
         OR o.amount_owed IS DISTINCT FROM a.amount
         OR o.amount_paid IS DISTINCT FROM a.amount
         OR o.settled_at IS NULL
         OR k.key IS NULL
         OR k.user_id IS DISTINCT FROM a.user_id
         OR k.amount IS DISTINCT FROM a.amount)
  ) THEN
    RAISE EXCEPTION 'satellite % cash ticket has no exact wallet/debt evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_h.seat_count > 0 AND v_target.id IS NULL THEN
    RAISE EXCEPTION 'satellite % delivered seats into a missing target',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_players target_player
        ON target_player.id = a.registration_id
      LEFT JOIN public.chip_ledger l
        ON l.idempotency_key = 'tourney:' || p_tournament_id::text
                               || ':seat:' || a.user_id::text || ':pool_transfer'
     WHERE a.tournament_id = p_tournament_id
       AND a.delivery_kind = 'seat'
       AND (target_player.id IS NULL
         OR target_player.tournament_id IS DISTINCT FROM v_h.target_id
           OR target_player.user_id IS DISTINCT FROM a.user_id
           OR COALESCE(target_player.is_satellite_qualifier, false) IS NOT TRUE
           OR target_player.source_satellite_id IS DISTINCT FROM p_tournament_id
         OR l.id IS NULL
         OR l.amount IS DISTINCT FROM v_h.ticket_cost
         OR l.from_type IS DISTINCT FROM 'prize_liability'
         OR l.from_entity_id IS DISTINCT FROM p_tournament_id
         OR l.to_type IS DISTINCT FROM 'prize_liability'
         OR l.to_entity_id IS DISTINCT FROM v_h.target_id
         OR l.category IS DISTINCT FROM 'tournament_buyin'
         OR l.metadata->>'registration_id' IS DISTINCT FROM a.registration_id::text)
  ) OR EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = v_h.target_id
       AND tp.source_satellite_id = p_tournament_id
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id
            AND a.delivery_kind = 'seat' AND a.registration_id = tp.id)
  ) OR (SELECT count(*) FROM public.chip_ledger l
         WHERE l.from_type = 'prize_liability'
           AND l.from_entity_id = p_tournament_id
           AND l.idempotency_key LIKE 'tourney:' || p_tournament_id::text
                                          || ':seat:%:pool_transfer')
       <> v_h.seat_count THEN
    RAISE EXCEPTION 'satellite % has malformed or extra actual-seat evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*), round(COALESCE(sum(r.rake_amount), 0), 2)
    INTO v_rows, v_rake
    FROM public.rake_records r
   WHERE r.tournament_id = v_h.target_id
     AND r.is_tournament
     AND r.source = 'fn_award_satellite_seat'
     AND r.metadata->>'satellite_id' = p_tournament_id::text;
  IF v_rows <> (CASE WHEN v_h.target_fee > 0 THEN v_h.seat_count ELSE 0 END)
     OR v_rake IS DISTINCT FROM round(v_h.seat_count * v_h.target_fee, 2)
     OR (SELECT count(DISTINCT r.metadata->>'registration_id')
           FROM public.rake_records r
          WHERE r.tournament_id = v_h.target_id
            AND r.is_tournament
            AND r.source = 'fn_award_satellite_seat'
            AND r.metadata->>'satellite_id' = p_tournament_id::text)
          <> (CASE WHEN v_h.target_fee > 0 THEN v_h.seat_count ELSE 0 END)
     OR EXISTS (
       SELECT 1 FROM public.rake_records r
        WHERE r.tournament_id = v_h.target_id
          AND r.is_tournament
          AND r.source = 'fn_award_satellite_seat'
          AND r.metadata->>'satellite_id' = p_tournament_id::text
          AND (r.rake_amount IS DISTINCT FROM v_h.target_fee
            OR r.pot_size IS DISTINCT FROM v_h.ticket_cost
            OR r.metadata->>'kind' IS DISTINCT FROM 'satellite_seat_entry_fee'
            OR NOT EXISTS (
              SELECT 1 FROM public.tournament_satellite_awards a
               WHERE a.tournament_id = p_tournament_id
                 AND a.delivery_kind = 'seat'
                 AND a.user_id::text = r.metadata->>'user_id'
                 AND a.registration_id::text = r.metadata->>'registration_id'))
     ) OR EXISTS (
       SELECT 1
         FROM public.tournament_satellite_awards a
        WHERE a.tournament_id = p_tournament_id
          AND a.delivery_kind = 'seat'
          AND v_h.target_fee > 0
          AND (SELECT count(*)
                 FROM public.rake_records r
                WHERE r.tournament_id = v_h.target_id
                  AND r.is_tournament
                  AND r.source = 'fn_award_satellite_seat'
                  AND r.metadata->>'kind' = 'satellite_seat_entry_fee'
                  AND r.metadata->>'satellite_id' = p_tournament_id::text
                  AND r.metadata->>'user_id' = a.user_id::text
                  AND r.metadata->>'registration_id' = a.registration_id::text
                  AND r.rake_amount = v_h.target_fee
                  AND r.pot_size = v_h.ticket_cost) <> 1
     ) THEN
    RAISE EXCEPTION 'satellite % has malformed target-entry evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_rows
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id;
  IF v_rows <> (v_h.cash_ticket_count
                + CASE WHEN v_h.remainder > 0 THEN 1 ELSE 0 END) THEN
    RAISE EXCEPTION 'satellite % has missing or extra obligation evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_h.remainder > 0 THEN
    IF (SELECT count(*) FROM public.tournament_satellite_remainders r
         WHERE r.tournament_id = p_tournament_id) <> 1
       OR NOT EXISTS (
      SELECT 1
        FROM public.tournament_players bubble
        JOIN public.tournament_satellite_remainders r
          ON r.tournament_id = p_tournament_id
         AND r.user_id = bubble.user_id
         AND r.place = v_h.bubble_position
         AND r.amount = v_h.remainder
        JOIN public.tournament_payouts p
          ON p.id = r.payout_id
         AND p.tournament_id = p_tournament_id
         AND p.user_id = bubble.user_id
         AND p."position" IS NOT DISTINCT FROM r.payout_position
         AND p.amount = v_h.remainder
         AND p.source = r.payout_source
         AND p.idempotency_key = r.idempotency_key
        JOIN public.tournament_obligations o
          ON o.id = r.obligation_id
         AND o.tournament_id = p_tournament_id
         AND o.kind = r.obligation_kind
         AND o.place IS NOT DISTINCT FROM r.obligation_place
         AND o.user_id = bubble.user_id
         AND o.amount_owed = v_h.remainder
         AND o.amount_paid = v_h.remainder
         AND o.settled_at IS NOT NULL
        JOIN public.wallet_credit_idempotency k
          ON k.key = r.idempotency_key
         AND k.user_id = bubble.user_id
         AND k.amount = v_h.remainder
       WHERE bubble.tournament_id = p_tournament_id
         AND bubble.user_id = v_h.bubble_user_id
         AND bubble.position = v_h.bubble_position
         AND (
           (r.evidence_kind = 'atomic'
             AND r.payout_position IS NOT DISTINCT FROM r.place
             AND r.obligation_place IS NOT DISTINCT FROM r.place
             AND r.idempotency_key = 'tourney:' || p_tournament_id::text
                 || ':satellite_remainder:place:' || r.place::text)
           OR r.evidence_kind = 'legacy_20260908_682')
    ) THEN
      RAISE EXCEPTION 'satellite % has no exact single-bubble remainder payment',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    v_remainder := jsonb_build_object(
      'user_id', v_h.bubble_user_id,
      'position', v_h.bubble_position,
      'amount', v_h.remainder);
  ELSIF EXISTS (SELECT 1 FROM public.tournament_satellite_remainders r
                 WHERE r.tournament_id = p_tournament_id)
     OR EXISTS (
       SELECT 1 FROM public.tournament_payouts p
        WHERE p.tournament_id = p_tournament_id
          AND p.source = 'satellite_remainder'
     ) THEN
    RAISE EXCEPTION 'satellite % has remainder evidence when remainder is zero',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  v_expected_rows := v_h.ticket_award_count
                     + CASE WHEN v_h.remainder > 0 THEN 1 ELSE 0 END;
  SELECT count(*), round(COALESCE(sum(p.amount), 0), 2)
    INTO v_rows, v_amount
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id;
  IF v_rows <> v_expected_rows OR v_amount IS DISTINCT FROM v_h.pool THEN
    RAISE EXCEPTION
      'satellite % payout evidence has % rows / % chips, expected % / %',
      p_tournament_id, v_rows, v_amount, v_expected_rows, v_h.pool
      USING ERRCODE = 'P0404';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.prize IS DISTINCT FROM CASE
         WHEN tp.position BETWEEN 1 AND v_h.ticket_award_count THEN v_h.ticket_cost
         WHEN v_h.remainder > 0 AND tp.position = v_h.bubble_position
           THEN v_h.remainder
         ELSE 0::numeric
       END
  ) THEN
    RAISE EXCEPTION 'satellite % prize cache disagrees with its receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT * INTO v_source_escrow
    FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id
   FOR UPDATE;
  IF v_source_escrow.tournament_id IS NULL
     OR COALESCE(v_source_escrow.enforced, false) IS NOT TRUE
     OR v_source_escrow.prize_out IS DISTINCT FROM v_h.pool
     OR v_source_escrow.bounty_in IS DISTINCT FROM 0::numeric
     OR v_source_escrow.bounty_out IS DISTINCT FROM 0::numeric
     OR v_source_escrow.refund_bounty IS DISTINCT FROM 0::numeric
     OR v_source_escrow.reserve_out IS DISTINCT FROM 0::numeric
     OR v_source_escrow.reserve_in IS DISTINCT FROM 0::numeric
     OR v_source_escrow.prize_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.bounty_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.fee_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.closed_at IS DISTINCT FROM v_h.source_escrow_closed_at
     OR v_source_escrow.close_note IS DISTINCT FROM v_h.source_escrow_close_note
     OR EXISTS (
       SELECT 1
         FROM unnest(ARRAY[
           'gross_in','fee_entries_in','satellite_fee_in','bounty_in',
           'overlay_in','satellite_in','prize_out','bounty_out','fee_out',
           'refund_prize','refund_bounty','refund_fee',
           'prize_balance','bounty_balance','fee_balance',
           'reserve_out','reserve_in'
         ]::text[]) AS component(name)
         CROSS JOIN LATERAL (
           SELECT (to_jsonb(v_source_escrow)->>component.name)::numeric AS amount
         ) AS persisted
        WHERE persisted.amount IS NULL
           OR CASE
                WHEN persisted.amount::text IN ('NaN','Infinity','-Infinity')
                  THEN true
                ELSE persisted.amount < 0
                  OR persisted.amount IS DISTINCT FROM round(persisted.amount,2)
              END
     ) THEN
    RAISE EXCEPTION 'satellite % did not close every escrow bank at zero',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT * INTO v_rake_settlement
    FROM public.tournament_rake_settlements s
   WHERE s.tournament_id = p_tournament_id;
  SELECT round(COALESCE(sum(r.rake_amount), 0), 2) INTO v_rake
    FROM public.rake_records r
   WHERE r.tournament_id = p_tournament_id AND r.is_tournament;
  IF v_rake_settlement.tournament_id IS NULL
     OR v_rake_settlement.settled_at IS NULL
     OR v_rake_settlement.amount IS DISTINCT FROM v_rake
     OR (v_rake > 0 AND v_rake_settlement.attributed_at IS NULL) THEN
    RAISE EXCEPTION 'satellite % rake has no exact terminal settlement',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', a.user_id,
           'position', a.place,
           'amount', a.amount,
           'delivery_kind', a.delivery_kind,
           'payout_id', a.payout_id,
           'registration_id', a.registration_id)
         ORDER BY a.place), '[]'::jsonb)
    INTO v_awards
    FROM public.tournament_satellite_awards a
   WHERE a.tournament_id = p_tournament_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', a.user_id,
           'position', a.place,
           'amount', a.amount,
           'registration_id', a.registration_id)
         ORDER BY a.place), '[]'::jsonb)
    INTO v_seats
    FROM public.tournament_satellite_awards a
   WHERE a.tournament_id = p_tournament_id
     AND a.delivery_kind = 'seat';

  v_winner_amount := CASE WHEN v_h.ticket_award_count > 0
                          THEN v_h.ticket_cost ELSE v_h.remainder END;
  RETURN jsonb_build_object(
    'ok', true,
    'fully_settled', true,
    'status', 'COMPLETED',
    'tournament_id', p_tournament_id,
    'target_id', v_h.target_id,
    'winner_id', v_h.winner_id,
    'field_size', v_h.field_size,
    'pool', v_h.pool,
    'ticket_cost', v_h.ticket_cost,
    'ticket_award_count', v_h.ticket_award_count,
    'seat_count', v_h.seat_count,
    'cash_ticket_count', v_h.cash_ticket_count,
    'awards', v_awards,
    'seats', v_seats,
    'remainder', v_remainder,
    'winner_amount', v_winner_amount,
    'source_table_count', v_h.source_table_count,
    'source_seat_count', v_h.source_seat_count,
    'released_seat_count', v_h.released_seat_count,
    'source_closeout', jsonb_build_object(
      'source_table_count', v_h.source_table_count,
      'source_table_ids', to_jsonb(v_h.source_table_ids),
      'source_seat_count', v_h.source_seat_count,
      'source_seat_ids', to_jsonb(v_h.source_seat_ids),
      'released_seat_count', v_h.released_seat_count,
      'released_seat_ids', to_jsonb(v_h.released_seat_ids),
      'closed_at', v_h.source_closed_at,
      'escrow_closed_at', v_h.source_escrow_closed_at,
      'escrow_close_note', v_h.source_escrow_close_note),
    'settled_at', v_h.settled_at,
    'receipt_version', v_h.receipt_version);
END;
$$;


ALTER FUNCTION public.fn_ca_satellite_settlement_receipt(p_tournament_id uuid, p_observed_winner_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_second_writer_check(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_second_writer_check(p_calls jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  c            jsonb;
  v_fn         text;
  v_keys       text[];
  v_findings   jsonb := '[]'::jsonb;
  v_checked    int := 0;
  v_unchecked  int := 0;
  v_calls      int := 0;
  v_overloads  int;
  v_status     text;
  v_sr         boolean;
  v_sig_ok     boolean;
  v_live       text;
  v_writes     boolean;
  v_money      boolean;
  v_sev        text;
  v_kinds      jsonb := '{}'::jsonb;
BEGIN
  IF p_calls IS NULL OR jsonb_typeof(p_calls) <> 'array' THEN
    RAISE EXCEPTION 'fn_ca_second_writer_check wants a JSON array of {file, line, fn, keys}';
  END IF;

  FOR c IN SELECT * FROM jsonb_array_elements(p_calls) LOOP
    v_calls := v_calls + 1;
    v_fn := c->>'fn';
    IF v_fn IS NULL OR v_fn !~ '^[a-z_][a-z0-9_]*$' THEN
      v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
        'kind', 'unreadable_call', 'severity', 'error', 'money', true,
        'detail', 'the function name is not a plain identifier');
      CONTINUE;
    END IF;

    /* keys: null = the payload was not a literal object; the script could not
       read it, so this call is counted as UNCHECKED, never as fine. */
    IF c->'keys' IS NULL OR jsonb_typeof(c->'keys') <> 'array' THEN
      v_keys := NULL;
    ELSE
      SELECT array_agg(x) INTO v_keys FROM jsonb_array_elements_text(c->'keys') x;
      v_keys := COALESCE(v_keys, '{}'::text[]);
    END IF;
    /* Coverage is counted here, before any verdict, so a missing function is
       still a call that was checked and the totals always sum to `calls`. */
    IF v_keys IS NULL THEN v_unchecked := v_unchecked + 1; ELSE v_checked := v_checked + 1; END IF;

    SELECT count(*), bool_or(has_function_privilege('service_role', p.oid, 'EXECUTE')),
           string_agg('(' || COALESCE(array_to_string(p.proargnames[1:p.pronargs], ', '), '') || ')', ' | '),
           bool_or(
             (p.prosrc ~* 'UPDATE\s+(public\.)?(club_members|club_wallets|union_wallets|unions|table_seats|bbj_pools|clubs|agents|wallets|spin_bonus_pools|tournament_players)\y'
              OR p.prosrc ~* 'INSERT\s+INTO\s+(public\.)?(club_members|club_wallets|union_wallets|unions|bbj_pools|clubs|agents|wallets|spin_bonus_pools)\y'
              OR p.prosrc ~* 'EXECUTE\s+format\s*\(\s*''UPDATE')
             AND p.prosrc ~* '\y(chip_balance|held_chips|locked_chips|credit_used|credit_limit|stack|balance|chips|prize|bounty_winnings|promo_balance)\y')
      INTO v_overloads, v_sr, v_live, v_writes
      FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = v_fn;

    SELECT status INTO v_status FROM public.ca_money_rpc_registry WHERE proname = v_fn;

    /* A MONEY DOOR is one the register knows (any status) or one that writes
       balance columns. A function the register has never seen and that has
       no function body to read (missing) is judged by the register alone. */
    v_money := (v_status IS NOT NULL) OR COALESCE(v_writes, false);
    v_sev   := CASE WHEN v_money THEN 'error' ELSE 'warning' END;

    IF v_overloads = 0 THEN
      v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
        'kind', 'missing_function', 'severity', v_sev, 'money', v_money,
        'detail', 'no function of this name exists in public; the route gets PGRST202 on every call');
      CONTINUE;
    END IF;

    IF v_status = 'closed' THEN
      v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
        'kind', 'closed_door', 'severity', 'error', 'money', true,
        'detail', 'the register closed this door; the route still calls it. Refuse before writing, or remove the branch.');
    ELSIF NOT COALESCE(v_sr, false) THEN
      v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
        'kind', 'not_executable_by_service_role', 'severity', v_sev, 'money', v_money,
        'detail', 'service_role cannot execute it; the route gets "permission denied" on every call');
    END IF;

    IF v_keys IS NOT NULL THEN
      /* PostgREST picks the overload whose NAMED parameters are exactly the
         keys sent, with every other parameter carrying a default. */
      SELECT bool_or(
               v_keys <@ COALESCE(p.proargnames[1:p.pronargs], '{}'::text[])
               AND NOT EXISTS (
                 SELECT 1 FROM unnest(COALESCE(p.proargnames[1:p.pronargs], '{}'::text[])) WITH ORDINALITY a(n, i)
                  WHERE NOT (a.n = ANY (v_keys))
                    AND a.i <= p.pronargs - p.pronargdefaults))
        INTO v_sig_ok
        FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = v_fn;
      IF NOT COALESCE(v_sig_ok, false) THEN
        v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
          'kind', 'signature_mismatch', 'severity', v_sev, 'money', v_money,
          'sent', to_jsonb(v_keys), 'live', v_live,
          'detail', 'no overload accepts exactly these parameter names; PostgREST answers PGRST202 and whatever the route does next is the only thing that runs');
      END IF;
    END IF;

    IF v_status IS NULL AND COALESCE(v_writes, false) THEN
      v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
        'kind', 'unregistered_writer', 'severity', 'warning', 'money', true,
        'detail', 'this function writes balance columns and is not in ca_money_rpc_registry: audit it, then register it');
    END IF;
  END LOOP;

  SELECT COALESCE(jsonb_object_agg(k, n), '{}'::jsonb) INTO v_kinds
    FROM (SELECT f->>'kind' AS k, count(*) AS n FROM jsonb_array_elements(v_findings) f GROUP BY 1) s;

  RETURN jsonb_build_object(
    'calls', v_calls,
    'checked', v_checked,
    'unchecked', v_unchecked,
    'errors', (SELECT count(*) FROM jsonb_array_elements(v_findings) f WHERE f->>'severity' = 'error'),
    'warnings', (SELECT count(*) FROM jsonb_array_elements(v_findings) f WHERE f->>'severity' = 'warning'),
    'kinds', v_kinds,
    'findings', v_findings,
    'registry', (SELECT jsonb_build_object('approved', count(*) FILTER (WHERE status = 'approved'),
                                           'closed', count(*) FILTER (WHERE status = 'closed'))
                   FROM public.ca_money_rpc_registry),
    'as_of', now());
END $_$;


ALTER FUNCTION public.fn_ca_second_writer_check(p_calls jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_second_writer_check(p_calls jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_second_writer_check(p_calls jsonb) IS 'Phase 7 (roadmap 9.6). Takes [{file,line,fn,keys}] as scanned from the World Hub''s pages/api/club-arena routes and answers whether each call agrees with pg_proc and ca_money_rpc_registry: missing, closed, not executable by service_role, parameter names no overload accepts, or an unregistered balance writer. The answer carries `unchecked` for calls whose payload could not be read.';


--
-- Name: fn_ca_settle_final_table_deal_share_raw(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settle_final_table_deal_share_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL
     OR p_amount IS NULL
     OR p_amount::text IN ('NaN','Infinity','-Infinity')
     OR p_amount <= 0
     OR p_amount IS DISTINCT FROM round(p_amount, 2) THEN
    RAISE EXCEPTION 'raw final-table-deal settlement received invalid derived inputs'
      USING ERRCODE = '22023';
  END IF;

  v_result := public.fn_settle_tournament_obligation_before_atomic_batch_gate(
    p_tournament_id,
    'final_table_deal',
    NULL,
    p_user_id,
    p_amount,
    'final_table_deal',
    'Final Table Deal (Exact-Cent Chip Chop)',
    NULL
  );

  IF COALESCE((v_result->>'ok')::boolean, false) IS NOT TRUE
     OR COALESCE((v_result->>'fully_settled')::boolean, false) IS NOT TRUE
     OR (v_result->>'amount_owed')::numeric IS DISTINCT FROM p_amount
     OR (v_result->>'amount_paid')::numeric IS DISTINCT FROM p_amount
     OR COALESCE((v_result->>'remaining')::numeric, p_amount) <> 0 THEN
    RAISE EXCEPTION 'tournament % deal share for % did not settle in full: %',
      p_tournament_id, p_user_id, v_result USING ERRCODE = 'P0404';
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_ca_settle_final_table_deal_share_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_settle_final_table_deal_share_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_settle_final_table_deal_share_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric) IS 'Owner-only final-table-deal obligation payer. The atomic deal door derives its inputs and any partial result raises.';


--
-- Name: fn_ca_settle_hand_stacks(uuid, uuid, bigint, jsonb, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settle_hand_stacks(p_table_id uuid, p_hand_id uuid, p_hand_number bigint DEFAULT NULL::bigint, p_deltas jsonb DEFAULT '[]'::jsonb, p_rake numeric DEFAULT 0, p_bbj numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claimed integer; v_prior record; v_sum numeric := 0; v_n integer := 0;
  e jsonb; v_uid uuid; v_delta numeric; v_updated integer;
  v_ca_id uuid; v_err text; v_result jsonb;
BEGIN
  IF NOT (current_user IN ('postgres', 'service_role')) THEN
    RAISE EXCEPTION 'fn_ca_settle_hand_stacks is engine/service only';
  END IF;
  IF p_table_id IS NULL OR p_hand_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'missing_ids');
  END IF;
  IF jsonb_typeof(p_deltas) IS DISTINCT FROM 'array' OR jsonb_array_length(p_deltas) = 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_deltas');
  END IF;

  -- claim (idempotent replay)
  INSERT INTO public.settlement_idempotency_keys
    (table_id, hand_id, status, attempt_count, first_attempt_at, last_attempt_at)
  VALUES (p_table_id, p_hand_id, 'in_flight', 1, now(), now())
  ON CONFLICT (table_id, hand_id) DO NOTHING;
  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 0 THEN
    SELECT status, result, last_attempt_at INTO v_prior
      FROM public.settlement_idempotency_keys
     WHERE table_id = p_table_id AND hand_id = p_hand_id FOR UPDATE;
    IF v_prior.status = 'succeeded' THEN
      RETURN COALESCE(v_prior.result, '{}'::jsonb) || jsonb_build_object('replay', true);
    ELSIF v_prior.status = 'in_flight' AND v_prior.last_attempt_at > now() - interval '5 minutes' THEN
      RETURN jsonb_build_object('success', false, 'reason', 'in_flight');
    ELSE
      UPDATE public.settlement_idempotency_keys
         SET status = 'in_flight', attempt_count = attempt_count + 1, last_attempt_at = now(), error = NULL
       WHERE table_id = p_table_id AND hand_id = p_hand_id;
    END IF;
  END IF;

  -- state machine
  INSERT INTO public.ca_settlements (settlement_type, external_ref, state, table_id, hand_id,
                                     idempotency_key)
  VALUES ('hand_stacks', p_table_id::text || ':' || p_hand_id::text, 'open', p_table_id, p_hand_id,
          'hand:' || p_table_id::text || ':' || p_hand_id::text)
  ON CONFLICT (settlement_type, external_ref) DO UPDATE
    SET state = CASE WHEN public.ca_settlements.state = 'failed' THEN 'open'
                     ELSE public.ca_settlements.state END,
        error_detail = NULL
  RETURNING id INTO v_ca_id;

  BEGIN
    UPDATE public.ca_settlements SET state='locked_for_calculation' WHERE id = v_ca_id AND state='open';

    -- validation: exact scale + conservation
    FOR e IN SELECT * FROM jsonb_array_elements(p_deltas) LOOP
      v_delta := round((e->>'delta')::numeric, 2);
      IF v_delta IS DISTINCT FROM (e->>'delta')::numeric THEN
        RAISE EXCEPTION 'delta for % is not exact 2dp: %', e->>'user_id', e->>'delta';
      END IF;
      v_sum := v_sum + v_delta;
      v_n := v_n + 1;
    END LOOP;
    IF round(v_sum + COALESCE(p_rake,0) + COALESCE(p_bbj,0), 2) <> 0 THEN
      RAISE EXCEPTION 'conservation violation: deltas %.2f + rake %.2f + bbj %.2f != 0',
        v_sum, COALESCE(p_rake,0), COALESCE(p_bbj,0);
    END IF;
    UPDATE public.ca_settlements SET state='calculated',
      totals = jsonb_build_object('players', v_n, 'net_deltas', v_sum,
                                  'rake', COALESCE(p_rake,0), 'bbj', COALESCE(p_bbj,0))
      WHERE id = v_ca_id AND state='locked_for_calculation';
    UPDATE public.ca_settlements SET state='validated' WHERE id = v_ca_id AND state='calculated';

    -- apply: all seats or none, no stack below zero, seats never deleted
    FOR e IN SELECT * FROM jsonb_array_elements(p_deltas) LOOP
      v_uid := (e->>'user_id')::uuid;
      v_delta := round((e->>'delta')::numeric, 2);
      CONTINUE WHEN v_delta = 0;
      UPDATE public.table_seats ts
         SET stack = round(ts.stack + v_delta, 2)
       WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL
         AND round(ts.stack + v_delta, 2) >= 0;
      GET DIAGNOSTICS v_updated = ROW_COUNT;
      IF v_updated <> 1 THEN
        RAISE EXCEPTION 'seat write failed for % (delta %): seat missing, left, or stack would go negative',
          v_uid, v_delta;
      END IF;
    END LOOP;
    UPDATE public.ca_settlements SET state='ledger_posted' WHERE id = v_ca_id AND state='validated';
    UPDATE public.ca_settlements SET state='post_commit_verified' WHERE id = v_ca_id AND state='ledger_posted';

    v_result := jsonb_build_object('success', true, 'players', v_n,
      'table_id', p_table_id, 'hand_id', p_hand_id, 'hand_number', p_hand_number,
      'rake', COALESCE(p_rake,0), 'bbj', COALESCE(p_bbj,0));

    UPDATE public.settlement_idempotency_keys
       SET status='succeeded', result=v_result, completed_at=now(), last_attempt_at=now()
     WHERE table_id = p_table_id AND hand_id = p_hand_id;
    UPDATE public.ca_settlements SET state='final' WHERE id = v_ca_id AND state='post_commit_verified';

    RETURN v_result;

  EXCEPTION WHEN OTHERS THEN
    v_err := SQLERRM;  -- every stack write above is rolled back here
    UPDATE public.settlement_idempotency_keys
       SET status='failed', error=left(v_err, 500), last_attempt_at=now()
     WHERE table_id = p_table_id AND hand_id = p_hand_id;
    UPDATE public.ca_settlements SET state='failed', error_detail=left(v_err, 2000)
     WHERE id = v_ca_id;
    IF v_err LIKE 'conservation violation%' THEN
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_settle_hand_stacks', 'ledger_imbalance', 'warning',
        'hand-conservation:' || p_table_id::text,
        round(v_sum + COALESCE(p_rake,0) + COALESCE(p_bbj,0), 2), 0,
        round(v_sum + COALESCE(p_rake,0) + COALESCE(p_bbj,0), 2),
        'settlement', 'table_seats', p_hand_id, NULL, NULL, p_table_id, NULL, p_hand_id,
        v_ca_id::text, NULL, NULL,
        'engine submitted a hand whose stack deltas do not conserve: ' || left(v_err, 200),
        false, jsonb_build_object('hand_id', p_hand_id, 'hand_number', p_hand_number));
    END IF;
    RETURN jsonb_build_object('success', false, 'reason', 'rolled_back', 'error', v_err,
                              'table_id', p_table_id, 'hand_id', p_hand_id);
  END;
END $$;


ALTER FUNCTION public.fn_ca_settle_hand_stacks(p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_deltas jsonb, p_rake numeric, p_bbj numeric) OWNER TO postgres;

--
-- Name: fn_ca_settle_hand_stacks_absolute(uuid, bigint, jsonb, numeric, numeric, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settle_hand_stacks_absolute(p_table_id uuid, p_hand_number bigint, p_stacks jsonb DEFAULT '[]'::jsonb, p_rake numeric DEFAULT NULL::numeric, p_bbj numeric DEFAULT NULL::numeric, p_ref text DEFAULT NULL::text, p_inflow numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_tournament_id uuid;
  v_zero_user_ids uuid[]:=ARRAY[]::uuid[];
  v_token uuid;
  v_opened integer:=0;
  v_remaining integer:=0;
  v_consumed integer:=0;
  v_result jsonb;
  v_expected_vacated integer;
  v_hand uuid;
  v_succeeded_receipt boolean:=false;
BEGIN
  -- Parse only an entirely well-shaped roster. Malformed input is passed to
  -- the preserved core unchanged so its canonical refusal remains the one
  -- semantic result and no capability is opened for a partial interpretation.
  IF jsonb_typeof(p_stacks)='array'
     AND jsonb_array_length(p_stacks)>0
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(p_stacks) x
        WHERE jsonb_typeof(x)<>'object'
           OR jsonb_typeof(x->'user_id')<>'string'
           OR COALESCE(x->>'user_id','') !~*
             '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR jsonb_typeof(x->'stack')<>'number')
     AND (SELECT count(DISTINCT x->>'user_id')
            FROM jsonb_array_elements(p_stacks) x)
           = jsonb_array_length(p_stacks) THEN
    SELECT tb.tournament_id INTO v_tournament_id
      FROM public.tables tb WHERE tb.id=p_table_id;
    IF v_tournament_id IS NOT NULL THEN
      SELECT COALESCE(
               array_agg(DISTINCT (x->>'user_id')::uuid
                         ORDER BY (x->>'user_id')::uuid),
               ARRAY[]::uuid[])
        INTO v_zero_user_ids
        FROM jsonb_array_elements(p_stacks) x
       WHERE (x->>'stack')::numeric=0;
    END IF;
  END IF;

  IF p_table_id IS NOT NULL AND p_hand_number IS NOT NULL THEN
    v_hand:=md5(
      'ca-hand:'||p_table_id::text||':'||p_hand_number::text||
      CASE WHEN p_ref IS NULL OR p_ref='' THEN '' ELSE ':'||p_ref END
    )::uuid;
    SELECT EXISTS (
      SELECT 1 FROM public.settlement_idempotency_keys k
       WHERE k.table_id=p_table_id AND k.hand_id=v_hand
         AND k.status='succeeded')
      INTO v_succeeded_receipt;
  END IF;

  -- A successful replay has already consumed and closed every zero seat. Do
  -- not weaken the fresh path to accommodate it: skip opening, then let the
  -- preserved core validate the complete request identity and return replay.
  IF cardinality(v_zero_user_ids)>0 AND NOT v_succeeded_receipt THEN
    v_token:=public.fn_ca_open_tournament_hand_seat_exit_authority(
      v_tournament_id,p_table_id,v_zero_user_ids);
    SELECT count(*) INTO v_opened
      FROM public.tournament_seat_exit_authorizations a
     WHERE a.token=v_token AND a.operation='hand_settlement';
  END IF;

  BEGIN
    v_result:=public.fn_ca_settle_hand_stacks_absolute_pre_seat_exit_authority(
      p_table_id,p_hand_number,p_stacks,p_rake,p_bbj,p_ref,p_inflow);

    IF v_token IS NOT NULL THEN
      v_remaining:=public.fn_ca_close_tournament_seat_exit_authority(
        v_token,false);
      v_consumed:=v_opened-v_remaining;
      IF COALESCE((v_result->>'success')::boolean,false)
         AND NOT COALESCE((v_result->>'replay')::boolean,false) THEN
        BEGIN
          v_expected_vacated:=
            (v_result->>'tournament_zero_stack_seat_count')::integer;
        EXCEPTION WHEN OTHERS THEN
          RAISE EXCEPTION
            'accepted-hand stack result omitted its seat-exit receipt'
            USING ERRCODE='P0404';
        END;
        IF v_expected_vacated IS NULL
           OR v_expected_vacated<>v_consumed THEN
          RAISE EXCEPTION
            'accepted-hand consumed % seat capability row(s), receipt named %',
            v_consumed,v_expected_vacated USING ERRCODE='P0404';
        END IF;
        IF v_expected_vacated>0 THEN
          PERFORM public.fn_emit_tournament_manager_wake(
            v_tournament_id,'accepted_hand_bust');
        END IF;
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    IF v_token IS NOT NULL THEN
      PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
    END IF;
    RAISE;
  END;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION public.fn_ca_settle_hand_stacks_absolute(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric) OWNER TO postgres;

--
-- Name: fn_ca_settle_hand_stacks_absolute_pre_seat_exit_authority(uuid, bigint, jsonb, numeric, numeric, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settle_hand_stacks_absolute_pre_seat_exit_authority(p_table_id uuid, p_hand_number bigint, p_stacks jsonb DEFAULT '[]'::jsonb, p_rake numeric DEFAULT NULL::numeric, p_bbj numeric DEFAULT NULL::numeric, p_ref text DEFAULT NULL::text, p_inflow numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_request jsonb;
  v_canonical jsonb;
  v_hand uuid; v_claimed integer; v_prior record; v_ca_id uuid;
  e jsonb; v_uid uuid; v_new numeric; v_old numeric; v_before numeric; v_target numeric;
  v_delta_sum numeric := 0; v_expected numeric;
  v_n integer := 0; v_updated integer; v_err text; v_result jsonb;
  v_delta_mode boolean;
  -- Exact seat identity is the row id plus the join instant. A vacated row can
  -- be reused in place, so neither user_id, chair number, nor row id is enough.
  v_exact_seat_generation boolean;
  v_exact_seat_id uuid;
  v_exact_seat_joined_at timestamptz;
  v_exact_seat_left_at timestamptz;
  v_exact_seat_club uuid;
  v_exact_seat_found boolean;
  v_targets jsonb := '{}'::jsonb;      -- user_id -> stack to write
  v_rebased jsonb := '{}'::jsonb;      -- user_id -> db_before - engine_before (delta mode only)
  v_rebase_rows jsonb := '[]'::jsonb;  -- rows for ca_seat_stack_rebases
  v_rebase_count integer := 0;
  -- 2026-09-04 (verification sweep): a seat that LEFT during the hand
  v_departed jsonb := '[]'::jsonb;   -- [{user_id, delta, club_id}]
  v_dep record; v_dep_club uuid; v_dep_after numeric; v_dep_key text; v_dep_claimed integer;
  -- chip-std Lane F (2026-09-02): tournament conservation (absolute mode)
  v_tournament_id uuid;
  -- The hand result is also the durable final-stack boundary for a tournament.
  v_tournament_status text;
  v_payload_stack_count integer := 0;
  v_target_user_count integer := 0;
  v_tournament_player_count integer := 0;
  v_tournament_player_user_ids uuid[] := ARRAY[]::uuid[];
  v_tournament_player_chips jsonb := '[]'::jsonb;
  v_zero_stack_seat_count integer := 0;
  v_zero_stack_seat_ids uuid[] := ARRAY[]::uuid[];
  v_zero_stack_user_ids uuid[] := ARRAY[]::uuid[];
  v_zero_stack_seat_generations jsonb := '[]'::jsonb;
  v_zero_stack_vacated_at timestamptz;
  v_table_live_seat_count integer := 0;
BEGIN
  -- This implementation primitive is owner-only by ACL below. Do not inspect
  -- current_user inside a SECURITY DEFINER core: CREATE OR REPLACE preserves
  -- the production owner, so a valid call through the sole service wrapper
  -- may execute here as that owner rather than as postgres/service_role.
  IF p_table_id IS NULL OR p_hand_number IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'missing_ids');
  END IF;
  IF jsonb_typeof(p_stacks) IS DISTINCT FROM 'array' OR jsonb_array_length(p_stacks) = 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_stacks');
  END IF;


  -- One participant, one delta. Duplicates previously passed the sum check
  -- twice but wrote a single target, allowing a non-conserving final balance.
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x
              WHERE jsonb_typeof(x) IS DISTINCT FROM 'object'
                 OR jsonb_typeof(x->'user_id') IS DISTINCT FROM 'string'
                 OR jsonb_typeof(x->'stack') IS DISTINCT FROM 'number'
                 OR (x ? 'stack_before' AND jsonb_typeof(x->'stack_before') IS DISTINCT FROM 'number')) THEN
    RAISE EXCEPTION 'Invalid hand settlement participant' USING ERRCODE = '22023';
  END IF;

  -- Rolling expansion accepts either a wholly legacy roster or a wholly exact
  -- roster. One-sided and mixed generations can otherwise create a request
  -- whose hash says one thing while individual rows are selected another way.
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_stacks) x
     WHERE (x ? 'seat_id') IS DISTINCT FROM (x ? 'seat_joined_at')
        OR CASE WHEN x ? 'seat_id'
                THEN jsonb_typeof(x->'seat_id') IS DISTINCT FROM 'string'
                  OR jsonb_typeof(x->'seat_joined_at') IS DISTINCT FROM 'string'
                ELSE false END
        OR CASE WHEN jsonb_typeof(x->'seat_id') = 'string'
                THEN (x->>'seat_id') !~*
                  '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ELSE false END
        OR CASE WHEN jsonb_typeof(x->'seat_joined_at') = 'string'
                THEN NOT pg_input_is_valid(
                  x->>'seat_joined_at', 'timestamp with time zone'
                )
                ELSE false END
  ) THEN
    RAISE EXCEPTION 'Invalid hand settlement seat generation'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x WHERE x ? 'seat_id')
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x WHERE NOT (x ? 'seat_id')) THEN
    RAISE EXCEPTION 'Mixed legacy and exact hand settlement seat generations'
      USING ERRCODE = '22023';
  END IF;
  SELECT COALESCE(bool_and(x ? 'seat_id' AND x ? 'seat_joined_at'), false)
    INTO v_exact_seat_generation
    FROM jsonb_array_elements(p_stacks) x;

  IF (SELECT count(*) <> count(DISTINCT (x->>'user_id')::uuid) FROM jsonb_array_elements(p_stacks) x) THEN
    RAISE EXCEPTION 'Duplicate hand settlement participant' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x WHERE x ? 'stack_before')
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x WHERE NOT (x ? 'stack_before')) THEN
    RAISE EXCEPTION 'Mixed absolute and delta hand settlement' USING ERRCODE = '22023';
  END IF;
  SELECT jsonb_agg(jsonb_build_object('user_id', (x->>'user_id')::uuid,
      'stack', (x->>'stack')::numeric)
      || CASE WHEN x ? 'stack_before' THEN jsonb_build_object('stack_before', (x->>'stack_before')::numeric)
              ELSE '{}'::jsonb END
      || CASE WHEN v_exact_seat_generation THEN jsonb_build_object(
              'seat_id', (x->>'seat_id')::uuid,
              'seat_joined_at', x->>'seat_joined_at')
              ELSE '{}'::jsonb END
      ORDER BY (x->>'user_id')::uuid) INTO v_canonical
    FROM jsonb_array_elements(p_stacks) x;
  v_request := jsonb_build_object('stacks', v_canonical, 'rake', p_rake,
    'bbj', p_bbj, 'inflow', p_inflow);

  /* DELTA MODE (chip standard 2026-09-04): the engine says what each stack
     WAS when it dealt and what it IS now; the database applies the difference
     to whatever the row holds. Every element must carry stack_before, or the
     whole call is absolute - a mixed payload would silently erase on the
     seats that lacked it. */
  SELECT bool_and(x ? 'stack_before' AND jsonb_typeof(x -> 'stack_before') = 'number')
    INTO v_delta_mode
    FROM jsonb_array_elements(p_stacks) x;
  v_delta_mode := COALESCE(v_delta_mode, false);

  -- stable hand id from (table, hand number[, ref])
  v_hand := md5('ca-hand:' || p_table_id::text || ':' || p_hand_number::text
                || CASE WHEN p_ref IS NULL OR p_ref = '' THEN '' ELSE ':' || p_ref END)::uuid;

  INSERT INTO public.settlement_idempotency_keys
    (table_id, hand_id, status, attempt_count, first_attempt_at, last_attempt_at)
  VALUES (p_table_id, v_hand, 'in_flight', 1, now(), now())
  ON CONFLICT (table_id, hand_id) DO NOTHING;
  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 0 THEN
    SELECT status, result, last_attempt_at INTO v_prior
      FROM public.settlement_idempotency_keys
     WHERE table_id = p_table_id AND hand_id = v_hand FOR UPDATE;
    IF v_prior.status = 'succeeded' THEN
      -- Old receipts predate payload storage. New receipts bind the full request.
      IF v_prior.result ? 'request' AND v_prior.result->'request' IS DISTINCT FROM v_request THEN
        RAISE EXCEPTION 'Hand settlement identity belongs to a different payload' USING ERRCODE = '22023';
      END IF;
      RETURN COALESCE(v_prior.result, '{}'::jsonb) || jsonb_build_object('replay', true);
    ELSIF v_prior.status = 'in_flight' AND v_prior.last_attempt_at > now() - interval '5 minutes' THEN
      RETURN jsonb_build_object('success', false, 'reason', 'in_flight');
    ELSE
      UPDATE public.settlement_idempotency_keys
         SET status = 'in_flight', attempt_count = attempt_count + 1, last_attempt_at = now(), error = NULL
       WHERE table_id = p_table_id AND hand_id = v_hand;
    END IF;
  END IF;

  INSERT INTO public.ca_settlements (settlement_type, external_ref, state, table_id, hand_id, idempotency_key)
  VALUES ('hand_stacks', p_table_id::text || ':' || v_hand::text, 'open', p_table_id, v_hand,
          'hand:' || p_table_id::text || ':' || v_hand::text)
  ON CONFLICT (settlement_type, external_ref) DO UPDATE
    SET state = CASE WHEN public.ca_settlements.state = 'failed' THEN 'open'
                     ELSE public.ca_settlements.state END,
        error_detail = NULL
  RETURNING id INTO v_ca_id;

  BEGIN
    UPDATE public.ca_settlements SET state='locked_for_calculation' WHERE id = v_ca_id AND state='open';

    -- ONE LOCK ORDER WITH TERMINAL CLOSE (20260908): tournament,
    -- target tournament players by user_id/id, then target seats by id. The
    -- terminal authority takes the same order. A hand that waited behind a
    -- terminal commit sees COMPLETED and is refused before touching a seat.
    SELECT tb.tournament_id INTO v_tournament_id
      FROM public.tables tb WHERE tb.id = p_table_id;
    IF v_tournament_id IS NOT NULL THEN
      SELECT upper(COALESCE(t.status::text,'')) INTO v_tournament_status
        FROM public.tournaments t
       WHERE t.id = v_tournament_id
       FOR SHARE;
      IF NOT FOUND OR v_tournament_status <> 'RUNNING' THEN
        RAISE EXCEPTION
          'tournament % is not RUNNING at the durable hand boundary',
          v_tournament_id USING ERRCODE = '55000';
      END IF;
      SELECT count(*),count(DISTINCT (x.value->>'user_id')::uuid)
        INTO v_payload_stack_count,v_target_user_count
        FROM jsonb_array_elements(v_canonical) AS x(value);
      IF v_target_user_count <> v_payload_stack_count THEN
        RAISE EXCEPTION 'tournament hand % contains duplicate player stacks',
          p_hand_number USING ERRCODE = '22023';
      END IF;
      PERFORM 1
        FROM public.tournament_players tp
       WHERE tp.tournament_id = v_tournament_id
         AND tp.status::text = 'playing'
         AND tp.user_id IN (
           SELECT (x.value->>'user_id')::uuid
             FROM jsonb_array_elements(v_canonical) AS x(value))
       ORDER BY tp.user_id,tp.id
       FOR UPDATE;
      SELECT count(*) INTO v_tournament_player_count
        FROM public.tournament_players tp
       WHERE tp.tournament_id = v_tournament_id
         AND tp.status::text = 'playing'
         AND tp.user_id IN (
           SELECT (x.value->>'user_id')::uuid
             FROM jsonb_array_elements(v_canonical) AS x(value));
      IF v_tournament_player_count <> v_target_user_count THEN
        RAISE EXCEPTION
          'tournament % hand % does not map every stack to one playing player',
          v_tournament_id,p_hand_number USING ERRCODE = 'P0404';
      END IF;
      -- A zero-seat vacate fires the seat-first table count trigger. Own the
      -- table before the seats, matching terminal close, so that trigger only
      -- reacquires a row this transaction already holds.
      PERFORM 1 FROM public.tables tb
       WHERE tb.id = p_table_id AND tb.tournament_id = v_tournament_id
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'tournament table % changed while hand % was locking',
          p_table_id,p_hand_number USING ERRCODE = '40001';
      END IF;
    END IF;

    -- Acquire every live target seat once in durable row-id order before the
    -- original loop. The loop's individual SELECT FOR UPDATE calls then
    -- reacquire locks that this transaction already owns. v_canonical is also
    -- the immutable replay identity, so lock, write and receipt use one roster.
    PERFORM 1
      FROM public.table_seats ts
      JOIN (
        SELECT DISTINCT (x.value->>'user_id')::uuid AS user_id
          FROM jsonb_array_elements(v_canonical) AS x(value)
      ) target ON target.user_id = ts.user_id
     WHERE ts.table_id = p_table_id
       AND ts.left_at IS NULL
     ORDER BY ts.id
     FOR UPDATE OF ts;

    -- lock seats, compute deltas / targets
    FOR e IN SELECT * FROM jsonb_array_elements(v_canonical) LOOP
      v_uid := (e->>'user_id')::uuid;
      v_new := round((e->>'stack')::numeric, 2);
      IF v_new IS NULL OR v_new < 0 THEN
        RAISE EXCEPTION 'invalid stack for %: %', e->>'user_id', e->>'stack';
      END IF;
      v_exact_seat_id := NULL;
      v_exact_seat_joined_at := NULL;
      v_exact_seat_left_at := NULL;
      v_exact_seat_club := NULL;
      IF v_exact_seat_generation THEN
        v_exact_seat_id := (e->>'seat_id')::uuid;
        v_exact_seat_joined_at := (e->>'seat_joined_at')::timestamptz;
        SELECT ts.stack, ts.left_at, ts.club_id
          INTO v_old, v_exact_seat_left_at, v_exact_seat_club
          FROM public.table_seats ts
         WHERE ts.id = v_exact_seat_id
           AND ts.joined_at = v_exact_seat_joined_at
           AND ts.table_id = p_table_id
           AND ts.user_id = v_uid
         FOR UPDATE;
      ELSE
        SELECT ts.stack INTO v_old FROM public.table_seats ts
         WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL
         FOR UPDATE;
      END IF;
      v_exact_seat_found := FOUND;
      IF NOT v_exact_seat_found
         OR (v_exact_seat_generation AND v_exact_seat_left_at IS NOT NULL) THEN
        -- If the exact row id was reused in place, joined_at no longer matches.
        -- There is no historical row left to settle, so fail the hand whole.
        IF v_exact_seat_generation AND NOT v_exact_seat_found THEN
          RAISE EXCEPTION
            'exact seat generation missing or replaced for % - hand write rejected whole',
            v_uid;
        END IF;
        /* A SEAT THAT LEFT DURING THE HAND (2026-09-04, verification sweep).
           In delta mode the player's own delta is settled against the club
           wallet the seat cashed out to, keyed on hand + user, and the players
           still seated get their deltas as usual. Refusing the whole hand here
           left the winner unpaid in the database and the leaver refunded the
           bet they had put in the pot (the exit cashes out the seat's stack
           as it stood BEFORE the hand). Measured before this: 3 cash hands in
           the first 40 minutes of delta mode, each a mid-hand leave_pending
           cash-out raced by a stale settlement step. Absolute mode still
           refuses: with no stack_before there is no delta to settle. */
        /* CASH TABLES ONLY. Tournament chips are play chips: a seat that a
           table balance moved or an elimination removed mid-hand has no
           wallet to settle against, and settling it debited 230 real chips
           from a player on 2026-09-04 13:04 (reversed in 20260904131500).
           The tournament conservation gate in the engine and the tournament
           branch below own that case; here it is refused whole, as before. */
        IF v_delta_mode AND NOT EXISTS (SELECT 1 FROM public.tables tb WHERE tb.id = p_table_id AND tb.tournament_id IS NOT NULL) THEN
          v_before := round((e->>'stack_before')::numeric, 2);
          IF v_before IS NULL OR v_before < 0 THEN
            RAISE EXCEPTION 'invalid stack_before for %: %', e->>'user_id', e->>'stack_before';
          END IF;
          IF v_exact_seat_generation THEN
            -- Use the club captured on the exact departed generation. Looking
            -- up the latest departed row can cross a later rejoin or club move.
            v_dep_club := v_exact_seat_club;
          ELSE
            SELECT ts.club_id INTO v_dep_club FROM public.table_seats ts
             WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NOT NULL
             ORDER BY ts.left_at DESC LIMIT 1;
          END IF;
          IF v_dep_club IS NULL AND NOT v_exact_seat_generation THEN
            SELECT t.club_id INTO v_dep_club FROM public.tables t WHERE t.id = p_table_id;
          END IF;
          /* SETTLING NOTHING NEEDS NO WALLET (2026-09-08). A seat that left
             having moved no chips has nothing to settle against a wallet, and
             the departed loop below already skips a zero delta. Demanding the
             wallet first refused whole hands over seats that owed nothing -
             hand 7903456, which nets to zero between two seated players, was
             refused because a third seat with a delta of 0.00 had gone. */
          IF round(v_new - v_before, 2) = 0 THEN
            v_n := v_n + 1;
            CONTINUE;
          END IF;
          IF v_dep_club IS NULL OR NOT EXISTS (SELECT 1 FROM public.club_members m WHERE m.user_id = v_uid AND m.club_id = v_dep_club) THEN
            RAISE EXCEPTION 'seat missing or left for % and no club wallet resolves for it - hand write rejected whole', v_uid;
          END IF;
          v_delta_sum := v_delta_sum + (v_new - v_before);
          v_departed := v_departed || jsonb_build_array(
            jsonb_build_object(
              'user_id', v_uid,
              'delta', round(v_new - v_before, 2),
              'club_id', v_dep_club
            ) || CASE WHEN v_exact_seat_generation THEN jsonb_build_object(
              'seat_id', v_exact_seat_id,
              'seat_joined_at', e->>'seat_joined_at'
            ) ELSE '{}'::jsonb END
          );
          v_n := v_n + 1;
          CONTINUE;
        END IF;
        RAISE EXCEPTION 'seat missing or left for % - hand write rejected whole', v_uid;
      END IF;
      v_old := COALESCE(v_old, 0);

      IF v_delta_mode THEN
        v_before := round((e->>'stack_before')::numeric, 2);
        IF v_before IS NULL OR v_before < 0 THEN
          RAISE EXCEPTION 'invalid stack_before for %: %', e->>'user_id', e->>'stack_before';
        END IF;
        v_target := round(v_old + (v_new - v_before), 2);
        IF v_target < 0 THEN
          RAISE EXCEPTION 'negative stack for % after applying delta % to the seat''s % (engine dealt from %) - hand write rejected whole',
            v_uid, round(v_new - v_before, 2), v_old, v_before;
        END IF;
        v_delta_sum := v_delta_sum + (v_new - v_before);
        IF round(v_old - v_before, 2) <> 0 THEN
          v_rebased := v_rebased || jsonb_build_object(v_uid::text, round(v_old - v_before, 2));
          v_rebase_rows := v_rebase_rows || jsonb_build_array(jsonb_build_object(
            'user_id', v_uid, 'engine_before', v_before, 'db_before', v_old,
            'engine_after', v_new, 'written', v_target));
          v_rebase_count := v_rebase_count + 1;
        END IF;
      ELSE
        v_target := v_new;
        v_delta_sum := v_delta_sum + (v_new - v_old);
      END IF;
      v_targets := v_targets || jsonb_build_object(v_uid::text, v_target);
      v_n := v_n + 1;
    END LOOP;

    UPDATE public.ca_settlements SET state='calculated',
      totals = jsonb_build_object('players', v_n, 'net_deltas', round(v_delta_sum,2),
                                  'rake', p_rake, 'bbj', p_bbj, 'inflow', p_inflow,
                                  'mode', CASE WHEN v_delta_mode THEN 'delta' ELSE 'absolute' END,
                                  'rebased', v_rebased, 'ref', p_ref, 'departed', v_departed)
      WHERE id = v_ca_id AND state='locked_for_calculation';

    SELECT tb.tournament_id INTO v_tournament_id FROM public.tables tb WHERE tb.id = p_table_id;

    IF v_delta_mode THEN
      /* THE IDENTITY, ON THE ENGINE'S OWN ARITHMETIC: what the seats gained
         is what arrived from a declared pool, less what left as rake and
         jackpot drop. Checked on every table, cash or tournament, on every
         write. A credit that landed on the row is outside the identity by
         construction - it is in v_old, not in the delta - so it is preserved
         rather than "explained". */
      v_expected := COALESCE(p_inflow, 0) - COALESCE(p_rake, 0) - COALESCE(p_bbj, 0);
      IF round(v_delta_sum - v_expected, 2) <> 0 THEN
        RAISE EXCEPTION 'conservation violation: stack deltas % != inflow % - rake % - bbj % (table % hand %) - write refused whole',
          round(v_delta_sum, 2), COALESCE(p_inflow, 0), COALESCE(p_rake, 0), COALESCE(p_bbj, 0),
          p_table_id, p_hand_number::text || COALESCE(':' || p_ref, '');
      END IF;
    ELSE
      -- ═══ TOURNAMENT CHIPS ARE CONSERVED HAND BY HAND (chip-std Lane F, 2026-09-02) ═══
      -- Absolute mode only. A tournament table has no rake and no BBJ drop,
      -- so the named seats must sum, after this write, to exactly what they
      -- summed to before it. A paid rebuy/re-entry/add-on commits its seat and
      -- roster under the accepted-hand table lock. The dealing loop reloads
      -- those authoritative rows before admitting the next hand. Therefore a
      -- non-zero delta is stale hand input, never permission to scan payment
      -- history and reconstruct chips. Refuse the whole hand at the boundary.
      IF v_tournament_id IS NOT NULL AND round(v_delta_sum, 2) <> 0 THEN
        RAISE EXCEPTION 'conservation violation (tournament %): stale accepted-hand stacks changed the table total by % across % seat(s) of table % hand % - paid seat/roster generations must be reloaded before dealing; write refused whole',
          v_tournament_id,round(v_delta_sum,2),v_n,p_table_id,p_hand_number;
      END IF;

      -- strict conservation only when rake is declared
      IF p_rake IS NOT NULL
         AND round(v_delta_sum + p_rake + COALESCE(p_bbj, 0), 2) <> 0 THEN
        RAISE EXCEPTION 'conservation violation: stack deltas %.2f + rake %.2f + bbj %.2f != 0',
          v_delta_sum, p_rake, COALESCE(p_bbj, 0);
      END IF;
    END IF;
    UPDATE public.ca_settlements SET state='validated' WHERE id = v_ca_id AND state='calculated';

    FOR e IN SELECT * FROM jsonb_array_elements(v_canonical) LOOP
      v_uid := (e->>'user_id')::uuid;
      IF NOT (v_targets ? v_uid::text) THEN
        CONTINUE;  -- a departed seat: settled against the wallet below
      END IF;
      v_target := (v_targets->>(v_uid::text))::numeric;
      IF v_exact_seat_generation THEN
        UPDATE public.table_seats ts SET stack = v_target
         WHERE ts.id = (e->>'seat_id')::uuid
           AND ts.joined_at = (e->>'seat_joined_at')::timestamptz
           AND ts.table_id = p_table_id
           AND ts.user_id = v_uid
           AND ts.left_at IS NULL;
      ELSE
        UPDATE public.table_seats ts SET stack = v_target
         WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL;
      END IF;
      GET DIAGNOSTICS v_updated = ROW_COUNT;
      IF v_updated <> 1 THEN
        /* aaa_skip_noop_update returns NULL for a row that would not change,
           and ROW_COUNT then reads 0. The seat was locked and found above, so
           a zero-row update whose seat already holds the target is the trigger
           doing its job, not a failed write. Before 2026-09-04 this rejected
           8,645 hands an hour - every hand in which one player's stack did not
           move - and each of those was persisted by the engine's unchecked
           per-seat fallback instead. */
        IF NOT EXISTS (
          SELECT 1
            FROM public.table_seats ts
           WHERE ts.table_id = p_table_id
             AND ts.user_id = v_uid
             AND ts.stack = v_target
             AND (
               (v_exact_seat_generation
                 AND ts.id = (e->>'seat_id')::uuid
                 AND ts.joined_at = (e->>'seat_joined_at')::timestamptz
                 AND ts.left_at IS NULL)
               OR (NOT v_exact_seat_generation AND ts.left_at IS NULL)
             )
        ) THEN
          RAISE EXCEPTION 'seat write failed for % - hand write rejected whole', v_uid;
        END IF;
      END IF;
    END LOOP;

    -- A successful tournament hand has one durable stack source. Mirror the
    -- exact resulting/rebased live seat targets into the matching playing
    -- tournament_players rows while both sets are still locked. Any missing,
    -- duplicate or divergent row rejects the whole hand subtransaction.
    IF v_tournament_id IS NOT NULL THEN
      UPDATE public.tournament_players tp
         SET chips = target.stack
        FROM (
          SELECT x.key::uuid AS user_id,x.value::numeric AS stack
            FROM jsonb_each_text(v_targets) AS x(key,value)
        ) target
       WHERE tp.tournament_id = v_tournament_id
         AND tp.user_id = target.user_id
         AND tp.status::text = 'playing';

      SELECT count(*),
             COALESCE(array_agg(tp.user_id ORDER BY tp.user_id),ARRAY[]::uuid[]),
             COALESCE(jsonb_agg(jsonb_build_object(
               'user_id',tp.user_id,'chips',tp.chips)
               ORDER BY tp.user_id),'[]'::jsonb)
        INTO v_tournament_player_count,v_tournament_player_user_ids,
             v_tournament_player_chips
        FROM public.tournament_players tp
        JOIN jsonb_each_text(v_targets) target
          ON target.key::uuid = tp.user_id
       WHERE tp.tournament_id = v_tournament_id
         AND tp.status::text = 'playing';
      IF v_tournament_player_count <>
           (SELECT count(*) FROM jsonb_each(v_targets))
         OR EXISTS (
           SELECT 1
             FROM jsonb_each_text(v_targets) target
            WHERE NOT EXISTS (
              SELECT 1
                FROM public.tournament_players tp
                JOIN public.table_seats ts
                  ON ts.table_id = p_table_id
                 AND ts.user_id = tp.user_id
                 AND ts.left_at IS NULL
               WHERE tp.tournament_id = v_tournament_id
                 AND tp.status::text = 'playing'
                 AND tp.user_id = target.key::uuid
                 AND tp.chips IS NOT DISTINCT FROM target.value::numeric
                 AND ts.stack IS NOT DISTINCT FROM target.value::numeric)) THEN
        RAISE EXCEPTION
          'tournament % hand % did not durably sync every final seat stack',
          v_tournament_id,p_hand_number USING ERRCODE = 'P0404';
      END IF;

      -- A named zero-stack tournament seat is finished on the felt at this
      -- same durable hand boundary. Keep tournament_players playing with
      -- chips=0 so the rebuy/elimination state machine can decide its life,
      -- but release the physical seat now. This replaces the former
      -- PostgREST vacate followed by a compensating chips-zero write.
      SELECT count(*),
             COALESCE(array_agg(ts.id ORDER BY ts.id),ARRAY[]::uuid[]),
             COALESCE(array_agg(ts.user_id ORDER BY ts.user_id),ARRAY[]::uuid[]),
             COALESCE(jsonb_agg(jsonb_build_object(
               'seat_id',ts.id,
               'user_id',ts.user_id,
               'seat_number',ts.seat_number,
               'joined_at',ts.joined_at)
               ORDER BY ts.id),'[]'::jsonb)
        INTO v_zero_stack_seat_count,v_zero_stack_seat_ids,
             v_zero_stack_user_ids,v_zero_stack_seat_generations
        FROM public.table_seats ts
        JOIN jsonb_each_text(v_targets) target
          ON target.key::uuid = ts.user_id
       WHERE ts.table_id = p_table_id
         AND ts.left_at IS NULL
         AND ts.stack = 0
         AND ts.user_id IS NOT NULL
         AND ts.joined_at IS NOT NULL
         AND target.value::numeric = 0;
      IF v_zero_stack_seat_count <>
           (SELECT count(*) FROM jsonb_each_text(v_targets) target
             WHERE target.value::numeric = 0) THEN
        RAISE EXCEPTION
          'tournament % hand % cannot identify every named zero-stack seat',
          v_tournament_id,p_hand_number USING ERRCODE = 'P0404';
      END IF;

      IF v_zero_stack_seat_count > 0 THEN
        v_zero_stack_vacated_at := clock_timestamp();
        UPDATE public.table_seats ts
           SET left_at = v_zero_stack_vacated_at,
               status = 'left',
               leave_pending = false,
               is_sitting_out = false,
               is_away = false,
               sit_out_at = NULL,
               scheduled_leave_hands = NULL
         WHERE ts.id = ANY(v_zero_stack_seat_ids)
           AND ts.table_id = p_table_id
           AND ts.left_at IS NULL
           AND ts.stack = 0;
        GET DIAGNOSTICS v_updated = ROW_COUNT;
        IF v_updated <> v_zero_stack_seat_count
           OR EXISTS (
             SELECT 1
               FROM unnest(v_zero_stack_seat_ids) expected(id)
              WHERE NOT EXISTS (
                SELECT 1 FROM public.table_seats ts
                 WHERE ts.id = expected.id
                   AND ts.table_id = p_table_id
                   AND ts.stack = 0
                   AND ts.left_at = v_zero_stack_vacated_at
                   AND ts.status = 'left'
                   AND COALESCE(ts.leave_pending,false) IS FALSE
                   AND COALESCE(ts.is_sitting_out,false) IS FALSE
                   AND COALESCE(ts.is_away,false) IS FALSE
                   AND ts.sit_out_at IS NULL
                   AND ts.scheduled_leave_hands IS NULL))
           OR EXISTS (
             SELECT 1
               FROM public.table_seats ts
               JOIN jsonb_each_text(v_targets) target
                 ON target.key::uuid = ts.user_id
              WHERE ts.table_id = p_table_id
                AND ts.left_at IS NULL
                AND target.value::numeric = 0) THEN
          RAISE EXCEPTION
            'tournament % hand % did not atomically vacate every zero-stack seat',
            v_tournament_id,p_hand_number USING ERRCODE = 'P0404';
        END IF;
      END IF;

      SELECT count(*) INTO v_table_live_seat_count
        FROM public.table_seats ts
       WHERE ts.table_id = p_table_id AND ts.left_at IS NULL;
      UPDATE public.tables tb
         SET current_players = v_table_live_seat_count,
             updated_at = now()
       WHERE tb.id = p_table_id
         AND tb.current_players IS DISTINCT FROM v_table_live_seat_count;
      IF NOT EXISTS (
        SELECT 1 FROM public.tables tb
         WHERE tb.id = p_table_id
           AND tb.tournament_id = v_tournament_id
           AND tb.current_players = v_table_live_seat_count) THEN
        RAISE EXCEPTION
          'tournament % hand % did not persist its exact live-seat count',
          v_tournament_id,p_hand_number USING ERRCODE = 'P0404';
      END IF;
    END IF;

    /* THE LEAVER STILL OWES WHAT THEY BET, AND IS STILL OWED WHAT THEY WON.
       The exit credited the seat's pre-hand stack to the club wallet, so a
       negative delta is chips the wallet holds that the pot (and now the
       winner's seat) also holds: debit the wallet, counterparty the felt.
       A positive delta is a pot they won after leaving: credit it. Keyed on
       hand + user in wallet_credit_idempotency, so a retry of this hand
       settles nothing twice. A wallet that cannot cover the debit refuses
       the whole hand, with the numbers, rather than going negative. */
    FOR v_dep IN SELECT (d->>'user_id')::uuid AS user_id, (d->>'delta')::numeric AS delta, (d->>'club_id')::uuid AS club_id
                   FROM jsonb_array_elements(v_departed) d LOOP
      IF v_dep.delta = 0 THEN CONTINUE; END IF;
      v_dep_key := 'late_seat_settle:' || v_hand::text || ':' || v_dep.user_id::text;
      INSERT INTO public.wallet_credit_idempotency (key, user_id, amount)
      VALUES (v_dep_key, v_dep.user_id, v_dep.delta)
      ON CONFLICT (key) DO NOTHING;
      GET DIAGNOSTICS v_dep_claimed = ROW_COUNT;
      IF v_dep_claimed = 0 THEN CONTINUE; END IF;  -- already settled by an earlier attempt
      PERFORM public.fn_ca_declare_ledger('settlement', 'table_stack', p_table_id, v_ca_id, v_dep_key, NULL);
      UPDATE public.club_members m
         SET chip_balance = COALESCE(m.chip_balance, 0) + v_dep.delta, updated_at = now()
       WHERE m.user_id = v_dep.user_id AND m.club_id = v_dep.club_id
         AND COALESCE(m.chip_balance, 0) + v_dep.delta >= 0
       RETURNING m.chip_balance INTO v_dep_after;
      PERFORM set_config('app.ledger_category', '', true);
      PERFORM set_config('app.ledger_counterparty', '', true);
      PERFORM set_config('app.ledger_counterparty_entity', '', true);
      PERFORM set_config('app.ledger_idempotency_key', '', true);
      IF v_dep_after IS NULL THEN
        RAISE EXCEPTION 'seat missing or left for % and its club wallet cannot cover its delta of % - hand write rejected whole', v_dep.user_id, v_dep.delta;
      END IF;
      INSERT INTO public.chip_transactions (club_id, to_user_id, amount, transaction_type, notes, table_id, balance_after, metadata)
      VALUES (v_dep.club_id, v_dep.user_id, abs(v_dep.delta),
              CASE WHEN v_dep.delta < 0 THEN 'late_seat_debit' ELSE 'late_seat_credit' END,
              CASE WHEN v_dep.delta < 0
                   THEN format('Hand #%s settled after you left the table: %s chips you had bet are taken from the club wallet the seat cashed out to', p_hand_number, abs(v_dep.delta))
                   ELSE format('Hand #%s settled after you left the table: %s chips you won are credited to your club wallet', p_hand_number, v_dep.delta) END,
              p_table_id, v_dep_after, jsonb_build_object('hand_id', v_hand, 'key', v_dep_key, 'delta', v_dep.delta));
    END LOOP;
    UPDATE public.ca_settlements SET state='ledger_posted' WHERE id = v_ca_id AND state='validated';

    IF v_rebase_count > 0 THEN
      INSERT INTO public.ca_seat_stack_rebases
        (settlement_id, table_id, hand_id, hand_number, user_id, engine_before, db_before, engine_after, written)
      SELECT v_ca_id, p_table_id, v_hand, p_hand_number,
             (r->>'user_id')::uuid, (r->>'engine_before')::numeric, (r->>'db_before')::numeric,
             (r->>'engine_after')::numeric, (r->>'written')::numeric
        FROM jsonb_array_elements(v_rebase_rows) r;
    END IF;
    UPDATE public.ca_settlements SET state='post_commit_verified' WHERE id = v_ca_id AND state='ledger_posted';

    v_result := jsonb_build_object('success', true, 'players', v_n,
      'table_id', p_table_id, 'hand_id', v_hand, 'hand_number', p_hand_number,
      'net_deltas', round(v_delta_sum, 2), 'rake', p_rake, 'bbj', p_bbj, 'inflow', p_inflow,
      'mode', CASE WHEN v_delta_mode THEN 'delta' ELSE 'absolute' END,
      'rebased', v_rebased, 'written', v_targets, 'departed', v_departed,
      'conservation_checked', v_delta_mode OR p_rake IS NOT NULL,
      'tournament_id', v_tournament_id,
      'tournament_players_synced', v_tournament_id IS NOT NULL,
      'tournament_player_count', v_tournament_player_count,
      'tournament_player_user_ids', to_jsonb(v_tournament_player_user_ids),
      'tournament_player_chips', v_tournament_player_chips,
      'tournament_zero_stack_seats_vacated', v_tournament_id IS NOT NULL,
      'tournament_zero_stack_seat_count', v_zero_stack_seat_count,
      'tournament_zero_stack_seat_ids', to_jsonb(v_zero_stack_seat_ids),
      'tournament_zero_stack_user_ids', to_jsonb(v_zero_stack_user_ids),
      'tournament_zero_stack_seat_generations', v_zero_stack_seat_generations,
      'tournament_zero_stack_vacated_at', v_zero_stack_vacated_at,
      'tournament_table_live_seat_count', v_table_live_seat_count,
      'request', v_request);

    UPDATE public.settlement_idempotency_keys
       SET status='succeeded', result=v_result, completed_at=now(), last_attempt_at=now()
     WHERE table_id = p_table_id AND hand_id = v_hand;
    UPDATE public.ca_settlements SET state='final' WHERE id = v_ca_id AND state='post_commit_verified';
    RETURN v_result;

  EXCEPTION WHEN OTHERS THEN
    v_err := SQLERRM;
    UPDATE public.settlement_idempotency_keys
       SET status='failed', error=left(v_err, 500), last_attempt_at=now()
     WHERE table_id = p_table_id AND hand_id = v_hand;
    UPDATE public.ca_settlements SET state='failed', error_detail=left(v_err, 2000) WHERE id = v_ca_id;
    IF v_err LIKE 'conservation violation%' OR v_err LIKE 'negative stack%' THEN
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_settle_hand_stacks_absolute', 'ledger_imbalance', 'warning',
        'hand-conservation:' || p_table_id::text,
        round(v_delta_sum + COALESCE(p_rake,0) + COALESCE(p_bbj,0) - COALESCE(p_inflow,0), 2), 0,
        round(v_delta_sum + COALESCE(p_rake,0) + COALESCE(p_bbj,0) - COALESCE(p_inflow,0), 2),
        'settlement', 'table_seats', v_hand, NULL, NULL, p_table_id, NULL, v_hand,
        v_ca_id::text, NULL, NULL,
        'engine submitted a hand whose stack deltas do not conserve: ' || left(v_err, 200),
        false, jsonb_build_object('hand_number', p_hand_number, 'ref', p_ref,
                                  'mode', CASE WHEN v_delta_mode THEN 'delta' ELSE 'absolute' END));
    END IF;
    RETURN jsonb_build_object('success', false, 'reason', 'rolled_back', 'error', v_err,
                              'table_id', p_table_id, 'hand_number', p_hand_number, 'ref', p_ref);
  END;
END $_$;


ALTER FUNCTION public.fn_ca_settle_hand_stacks_absolute_pre_seat_exit_authority(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_settle_hand_stacks_absolute_pre_seat_exit_authority(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_settle_hand_stacks_absolute_pre_seat_exit_authority(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric) IS 'Owner-only accepted-hand stack core. The sole service door is the 12-argument lease-fenced fn_ca_commit_hand_settlement transaction; direct stack-only commits are forbidden.';


--
-- Name: fn_ca_settle_tournament_bubble_raw(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settle_tournament_bubble_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_ob public.tournament_obligations%ROWTYPE;
  v_payout_count integer;
  v_paid numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL
     OR p_amount IS NULL
     OR p_amount::text IN ('NaN','Infinity','-Infinity')
     OR p_amount <= 0
     OR p_amount IS DISTINCT FROM round(p_amount, 2) THEN
    RAISE EXCEPTION 'raw bubble settlement received invalid derived inputs'
      USING ERRCODE = '22023';
  END IF;

  v_result := public.fn_settle_tournament_obligation_before_atomic_batch_gate(
    p_tournament_id,
    'bubble_protection',
    NULL,
    p_user_id,
    p_amount,
    'engine.fn_settle_tournament_bubble_protection',
    'Bubble Protection: Base Buy-In Returned',
    NULL
  );

  IF COALESCE((v_result->>'ok')::boolean, false) IS NOT TRUE
     OR COALESCE((v_result->>'fully_settled')::boolean, false) IS NOT TRUE
     OR (v_result->>'amount_owed')::numeric IS DISTINCT FROM p_amount
     OR (v_result->>'amount_paid')::numeric IS DISTINCT FROM p_amount
     OR COALESCE((v_result->>'remaining')::numeric, p_amount) <> 0 THEN
    RAISE EXCEPTION 'tournament % bubble obligation for % did not settle in full: %',
      p_tournament_id, p_user_id, v_result USING ERRCODE = 'P0404';
  END IF;

  SELECT * INTO v_ob
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND o.kind = 'bubble_protection';
  IF NOT FOUND OR v_ob.place IS NOT NULL
     OR v_ob.user_id IS DISTINCT FROM p_user_id
     OR v_ob.amount_owed IS DISTINCT FROM p_amount
     OR v_ob.amount_paid IS DISTINCT FROM p_amount
     OR v_ob.settled_at IS NULL
     OR (SELECT count(*) FROM public.tournament_obligations o
          WHERE o.tournament_id = p_tournament_id
            AND o.kind = 'bubble_protection') <> 1 THEN
    RAISE EXCEPTION 'tournament % has no exact settled bubble obligation',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*), COALESCE(sum(p.amount), 0)
    INTO v_payout_count, v_paid
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id
     AND p.source = 'bubble_protection';
  IF v_payout_count < 1 OR v_paid IS DISTINCT FROM p_amount
     OR EXISTS (
       SELECT 1 FROM public.tournament_payouts p
        WHERE p.tournament_id = p_tournament_id
          AND p.source = 'bubble_protection'
          AND (p.user_id IS DISTINCT FROM p_user_id
            OR p."position" IS NOT NULL
            OR p.amount IS NULL
            OR p.amount::text IN ('NaN','Infinity','-Infinity')
            OR p.amount <= 0
            OR p.amount IS DISTINCT FROM round(p.amount, 2)
            OR p.idempotency_key IS NULL
            OR NOT EXISTS (
              SELECT 1 FROM public.wallet_credit_idempotency k
               WHERE k.key = p.idempotency_key
                 AND k.user_id = p.user_id
                 AND k.amount = p.amount))) THEN
    RAISE EXCEPTION 'tournament % has malformed or incomplete bubble payout evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_ca_settle_tournament_bubble_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_settle_tournament_bubble_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_settle_tournament_bubble_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric) IS 'Owner-only raw payer for a database-derived, pool-funded stone-bubble buy-in. Partial settlement raises and rolls its outer transaction back.';


--
-- Name: fn_ca_settle_tournament_place_raw(uuid, integer, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settle_tournament_place_raw(p_tournament_id uuid, p_place integer, p_user_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL OR p_place IS NULL OR p_place < 1
     OR p_amount IS NULL OR p_amount::text IN ('NaN','Infinity','-Infinity')
     OR p_amount <= 0 OR p_amount IS DISTINCT FROM round(p_amount,2) THEN
    RAISE EXCEPTION 'raw place settlement received invalid derived inputs'
      USING ERRCODE = '22023';
  END IF;
  v_result := public.fn_settle_tournament_obligation_before_atomic_batch_gate(
    p_tournament_id, 'place', p_place, p_user_id, p_amount,
    'engine.fn_settle_tournament_places',
    format('Tournament prize: position %s',p_place), NULL);
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_result->>'fully_settled')::boolean,false) IS NOT TRUE
     OR (v_result->>'amount_owed')::numeric IS DISTINCT FROM p_amount
     OR (v_result->>'amount_paid')::numeric IS DISTINCT FROM p_amount
     OR COALESCE((v_result->>'remaining')::numeric,p_amount) <> 0 THEN
    RAISE EXCEPTION 'tournament %, place % did not settle in full: %',
      p_tournament_id, p_place, v_result USING ERRCODE = 'P0404';
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_ca_settle_tournament_place_raw(p_tournament_id uuid, p_place integer, p_user_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_settle_tournament_place_raw(p_tournament_id uuid, p_place integer, p_user_id uuid, p_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_settle_tournament_place_raw(p_tournament_id uuid, p_place integer, p_user_id uuid, p_amount numeric) IS 'Owner-only raw place payer used by the atomic service door. A partial result raises and rolls the outer ladder back.';


--
-- Name: fn_ca_settlement_correctness_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settlement_correctness_check() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; n integer := 0;
BEGIN
  -- B. Cross-club direct postings (last 60 min)
  FOR r IN
    SELECT l.id, l.from_type, l.from_entity_id, l.to_type, l.to_entity_id, l.amount, l.category
    FROM public.chip_ledger l
    WHERE l.created_at > now() - interval '60 minutes'
      AND l.from_type IN ('club_treasury','club_wallet')
      AND l.to_type   IN ('club_treasury','club_wallet')
      AND l.from_entity_id IS DISTINCT FROM l.to_entity_id
      AND l.category NOT IN ('treasury_transfer','pnl_settlement','horse_funding','correction')
    LIMIT 20
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_settlement_correctness_check:cross_club', 'cross_club_posting', 'warning',
      'cross-club:' || COALESCE(r.from_entity_id::text,'?') || ':' || COALESCE(r.to_entity_id::text,'?'),
      r.amount, NULL, NULL, 'ledger', 'chip_ledger', NULL,
      r.from_entity_id, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY[r.id],
      'chips moved directly between two different clubs (' || r.category || ', '
        || r.from_type || '→' || r.to_type || ') outside the allowed cross-club categories',
      NULL, jsonb_build_object('ledger_row', r.id, 'category', r.category));
    n := n + 1;
  END LOOP;

  -- C1. Rakeback over-attribution (last 24 h)
  FOR r IN
    SELECT rr.id AS record_id, rr.club_id, rr.rake_amount, round(sum(ra.rake_amount),2) AS attributed
    FROM public.rake_records rr
    JOIN public.rake_attributions ra ON ra.rake_record_id = rr.id
    WHERE rr.created_at > now() - interval '24 hours'
    GROUP BY rr.id, rr.club_id, rr.rake_amount
    HAVING round(sum(ra.rake_amount),2) > round(rr.rake_amount,2) + 0.01
    LIMIT 20
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_settlement_correctness_check:rakeback_chain', 'incorrect_rakeback', 'warning',
      'rakeback-overattr:' || r.record_id::text,
      round(r.attributed - r.rake_amount, 2), r.rake_amount, r.attributed,
      'reporting', 'rake_attributions', r.record_id, r.club_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'rake attributions exceed the rake actually collected for this record - the rakeback chain would over-accrue',
      NULL, jsonb_build_object('rake_record_id', r.record_id));
    n := n + 1;
  END LOOP;

  -- C2. Rakeback over-payout (paid more than the player contributed, last 7 d)
  FOR r IN
    SELECT p.id, p.club_id, p.user_id, p.payout_amount, p.user_rake_contribution
    FROM public.rakeback_period_payouts p
    WHERE p.status = 'paid' AND p.paid_at > now() - interval '7 days'
      AND p.payout_amount > COALESCE(p.user_rake_contribution, 0) + 0.01
    LIMIT 20
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_settlement_correctness_check:rakeback_chain', 'incorrect_rakeback', 'critical',
      'rakeback-overpay:' || r.id::text,
      round(r.payout_amount - COALESCE(r.user_rake_contribution,0), 2),
      r.user_rake_contribution, r.payout_amount,
      'settlement', 'rakeback_period_payouts', r.id, r.club_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'a rakeback payout exceeds the player''s ENTIRE rake contribution - impossible under any percentage',
      NULL, jsonb_build_object('payout_id', r.id, 'user_id', r.user_id));
    n := n + 1;
  END LOOP;

  -- C3. Rakeback dual-write evidence gaps (last 7 d)
  FOR r IN
    SELECT 'period_payout' AS src, p.id, p.club_id FROM public.rakeback_period_payouts p
     WHERE p.status = 'paid' AND p.paid_at > now() - interval '7 days' AND p.wallet_transaction_id IS NULL
    UNION ALL
    SELECT 'distribution', d.id, d.club_id FROM public.rakeback_distributions d
     WHERE d.status IN ('transferred','paid') AND d.transferred_at > now() - interval '7 days'
       AND d.chip_transfer_id IS NULL
    LIMIT 20
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_settlement_correctness_check:rakeback_chain', 'reporting_mismatch', 'warning',
      'rakeback-evidence:' || r.src || ':' || r.id::text,
      0, NULL, NULL, 'reporting', 'rakeback_' || r.src, r.id, r.club_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'rakeback marked paid/transferred with no linked wallet/chip transaction - the money side has no evidence pointer',
      NULL, jsonb_build_object('kind', r.src, 'row_id', r.id));
    n := n + 1;
  END LOOP;

  -- D. Ticket conservation
  FOR r IN
    SELECT t.id, t.club_id, t.status, t.value,
           CASE WHEN t.status='redeemed' AND t.redeemed_at IS NULL THEN 'redeemed_without_timestamp'
                WHEN t.status='cancelled' AND t.cancelled_at IS NULL THEN 'cancelled_without_timestamp'
                WHEN t.status NOT IN ('redeemed','cancelled') AND COALESCE(t.value,0) <= 0 THEN 'active_nonpositive_value'
           END AS why
    FROM public.tournament_tickets t
    WHERE (t.status='redeemed' AND t.redeemed_at IS NULL)
       OR (t.status='cancelled' AND t.cancelled_at IS NULL)
       OR (t.status NOT IN ('redeemed','cancelled') AND COALESCE(t.value,0) <= 0)
    LIMIT 20
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_settlement_correctness_check:tickets', 'reporting_mismatch', 'warning',
      'ticket:' || r.id::text,
      COALESCE(r.value,0), NULL, NULL, 'reporting', 'tournament_tickets', r.id, r.club_id,
      NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'ticket conservation violation: ' || r.why,
      NULL, jsonb_build_object('ticket_id', r.id, 'status', r.status, 'why', r.why));
    n := n + 1;
  END LOOP;

  -- E. Insurance pair-match (net must equal payout − premium; last 24 h)
  FOR r IN
    SELECT i.id, i.club_id, i.union_id, i.premium, i.payout, i.net_result
    FROM public.insurance_transactions i
    WHERE i.created_at > now() - interval '24 hours'
      AND round(COALESCE(i.payout,0) - COALESCE(i.premium,0), 2) <> round(COALESCE(i.net_result,0), 2)
    LIMIT 20
  LOOP
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_settlement_correctness_check:insurance', 'reporting_mismatch', 'warning',
      'insurance-pair:' || r.id::text,
      round((COALESCE(r.payout,0) - COALESCE(r.premium,0)) - COALESCE(r.net_result,0), 2),
      round(COALESCE(r.payout,0) - COALESCE(r.premium,0), 2), r.net_result,
      'reporting', 'insurance_transactions', r.id, r.club_id, r.union_id,
      NULL, NULL, NULL, NULL, NULL, NULL,
      'insurance row does not pair: net_result must equal payout minus premium exactly',
      NULL, jsonb_build_object('insurance_id', r.id));
    n := n + 1;
  END LOOP;

  -- F. Ticket VALUE conservation (phase 2b): every redeemed/cancelled
  -- ticket must have exactly one credit receipt of exactly its value.
  FOR r IN
    SELECT t.id, t.club_id, t.value, t.status,
           (SELECT count(*) FROM public.chip_transactions ct
             WHERE ct.transaction_type = CASE t.status WHEN 'redeemed'
                     THEN 'tournament_ticket_redeem' ELSE 'tournament_ticket_cancel' END
               AND ct.metadata->>'ticket_id' = t.id::text) AS receipts,
           (SELECT COALESCE(sum(ct.amount),0) FROM public.chip_transactions ct
             WHERE ct.transaction_type = CASE t.status WHEN 'redeemed'
                     THEN 'tournament_ticket_redeem' ELSE 'tournament_ticket_cancel' END
               AND ct.metadata->>'ticket_id' = t.id::text) AS receipt_value
    FROM public.tournament_tickets t
    WHERE t.status IN ('redeemed','cancelled')
      AND COALESCE(t.redeemed_at, t.cancelled_at) > now() - interval '24 hours'
    LIMIT 50
  LOOP
    IF r.receipts <> 1 OR round(r.receipt_value,2) <> round(r.value,2) THEN
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_settlement_correctness_check:ticket_value', 'reporting_mismatch', 'warning',
        'ticket-value:' || r.id::text,
        round(r.receipt_value - r.value, 2), r.value, r.receipt_value,
        'settlement', 'tournament_tickets', r.id, r.club_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
        'ticket value conservation broken: ' || r.status || ' ticket worth ' || r.value
          || ' has ' || r.receipts || ' receipt(s) totalling ' || r.receipt_value,
        NULL, jsonb_build_object('ticket_id', r.id));
      n := n + 1;
    END IF;
  END LOOP;

  -- G. Legacy-fallback alarm (phase 2b): once the engine settles ≥50% of
  -- hands through the atomic claim RPC (24h view), any last-hour coverage
  -- below 90% means a regression re-opened the unsafe per-seat path.
  DECLARE
    v_hands_24h bigint; v_claims_24h bigint; v_hands_1h bigint; v_claims_1h bigint;
  BEGIN
    SELECT count(*) INTO v_hands_24h FROM public.hand_history
     WHERE created_at > now() - interval '24 hours' AND has_human;
    SELECT count(*) INTO v_claims_24h FROM public.settlement_idempotency_keys
     WHERE first_attempt_at > now() - interval '24 hours';
    IF v_hands_24h > 100 AND v_claims_24h >= v_hands_24h / 2 THEN
      SELECT count(*) INTO v_hands_1h FROM public.hand_history
       WHERE created_at > now() - interval '60 minutes' AND has_human;
      SELECT count(*) INTO v_claims_1h FROM public.settlement_idempotency_keys
       WHERE first_attempt_at > now() - interval '60 minutes';
      IF v_hands_1h >= 20 AND v_claims_1h < (v_hands_1h * 9) / 10 THEN
        PERFORM public.fn_ca_raise_drift_incident(
          'fn_ca_settlement_correctness_check:fallback_regression', 'settlement_error', 'warning',
          'fallback-regression:' || to_char(now(), 'YYYY-MM-DD-HH24'),
          0, v_hands_1h, v_claims_1h, 'settlement', 'settlement_idempotency_keys',
          NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
          'atomic hand settlement coverage fell to ' || v_claims_1h || '/' || v_hands_1h
            || ' hands in the last hour after adoption - the engine has regressed to the legacy per-seat write path',
          NULL, jsonb_build_object('claims_1h', v_claims_1h, 'hands_1h', v_hands_1h));
        n := n + 1;
      END IF;
    END IF;
  END;

  RETURN n;
END $$;


ALTER FUNCTION public.fn_ca_settlement_correctness_check() OWNER TO postgres;

--
-- Name: fn_ca_settlement_transition_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settlement_transition_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  ord_old int; ord_new int;
BEGIN
  IF NEW.state = OLD.state THEN RETURN NEW; END IF;
  ord_old := array_position(ARRAY['open','locked_for_calculation','calculated',
              'validated','ledger_posted','post_commit_verified','final'], OLD.state);
  ord_new := array_position(ARRAY['open','locked_for_calculation','calculated',
              'validated','ledger_posted','post_commit_verified','final'], NEW.state);
  IF OLD.state = 'final' THEN
    RAISE EXCEPTION 'settlement % is final and cannot change state', OLD.id;
  END IF;
  IF NEW.state = 'failed' THEN
    NEW.updated_at := now(); RETURN NEW;
  END IF;
  IF OLD.state = 'failed' THEN  -- resume: re-enter anywhere at or before ledger_posted
    IF ord_new IS NULL OR ord_new > 5 THEN
      RAISE EXCEPTION 'failed settlement % may only resume at or before ledger_posted', OLD.id;
    END IF;
    NEW.updated_at := now(); RETURN NEW;
  END IF;
  IF ord_old IS NULL OR ord_new IS NULL OR ord_new <> ord_old + 1 THEN
    RAISE EXCEPTION 'invalid settlement transition % -> % for %', OLD.state, NEW.state, OLD.id;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_settlement_transition_guard() OWNER TO postgres;

--
-- Name: fn_ca_stable_dedupe_key(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_stable_dedupe_key(p_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  /* Strips a trailing period label: :2026-09-06, :2026-09-06-18, :2026-36.
     Used ONLY together with an equal discrepancy, so an hourly bucket that
     reports a different number is never folded into another one. */
  SELECT regexp_replace($1, ':([0-9]{4}-[0-9]{2}-[0-9]{2}(-[0-9]{2})?|[0-9]{4}-[0-9]{1,2})$', '')
$_$;


ALTER FUNCTION public.fn_ca_stable_dedupe_key(p_key text) OWNER TO postgres;

--
-- Name: fn_ca_supply_snapshot(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_supply_snapshot() RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s RECORD; prev RECORD; v_mint numeric; v_burn numeric; v_unexplained numeric;
  v_total numeric; v_trailing numeric; v_prev_unexplained numeric; v_critical boolean;
  v_outside text[] := public.fn_ca_noncirculating_chip_stores();
BEGIN
  SELECT
    -- EVERY aggregate here excludes the platform club: its wallets and treasuries are
    -- denominated in diamonds and sit in the same columns, so counting them would add the whole
    -- arena float to the chip supply (2026-09-08).
    (SELECT COALESCE(sum(cm.chip_balance),0) FROM club_members cm
       JOIN clubs c ON c.id = cm.club_id WHERE NOT COALESCE(c.is_platform, false)) AS member_wallets,
    (SELECT COALESCE(sum(cm.promo_balance),0) FROM club_members cm
       JOIN clubs c ON c.id = cm.club_id WHERE NOT COALESCE(c.is_platform, false)) AS member_promo,
    (SELECT COALESCE(sum(stack),0) FROM table_seats
      WHERE left_at IS NULL
        AND NOT EXISTS (SELECT 1 FROM tables t
                         WHERE t.id = table_seats.table_id
                           AND t.tournament_id IS NOT NULL))            AS felt,
    (SELECT COALESCE(sum(chip_treasury),0) FROM clubs WHERE NOT COALESCE(is_platform, false)) AS treasuries,
    (SELECT COALESCE(sum(chip_pool),0) FROM clubs WHERE NOT COALESCE(is_platform, false)) AS chip_pools,
    /* CHIP STANDARD (2026-09-03): the club-held promo and insurance floats are
       chips like any other. They were outside the total, so every BBJ promo
       sweep into a standalone club read as chips leaving the world. */
    (SELECT COALESCE(sum(promo_balance),0) FROM clubs WHERE NOT COALESCE(is_platform, false)) AS club_promo,
    (SELECT COALESCE(sum(insurance_balance),0) FROM clubs WHERE NOT COALESCE(is_platform, false)) AS club_insurance,
    (SELECT COALESCE(sum(chip_balance),0) FROM club_wallets)            AS club_wallets,
    (SELECT COALESCE(sum(chip_balance+rake_wallet+bbj_wallet+promo_wallet
             +insurance_wallet+COALESCE(spin_reserve_wallet,0)),0)
       FROM union_wallets)                                              AS union_wallets,
    (SELECT COALESCE(sum(COALESCE(agent_wallet_balance,0)
             +COALESCE(promo_wallet_balance,0)),0) FROM agents)         AS agent_wallets,
    (SELECT COALESCE(sum(COALESCE(promo_wallet_balance,0)),0) FROM agents) AS agent_promo,
    (SELECT COALESCE(sum(main_balance+backup_balance+promo_balance),0)
       FROM bbj_pools)                                                  AS bbj,
    (SELECT COALESCE(sum(balance),0) FROM spin_bonus_pools)             AS spin,
    /* CHIP STANDARD PHASE 5.1 (2026-09-05): a tournament's liability is its
       ESCROW BALANCE where the balance enforces the event (every non-spin
       event with a row since part two), and the old counters where it does
       not: an event with no row yet, and every SPIN, whose money sits in
       spin_reserve until the draw funds its prize and whose escrow row is
       tracked, not enforced (part four: reading spins from the escrow
       double-counted their entries against the reserve). */
    /* PHASE 5.2 (2026-09-05): the spin escrow now carries the reserve legs
       (reserve_out at pool completion, reserve_in at the draw), so its banks
       are exact and journal-consistent; the meter reads the escrow for EVERY
       event with a row, and the counters only for an event with no row yet. */
    (SELECT COALESCE(sum(COALESCE(e.prize_balance + e.bounty_balance + e.fee_balance,
                                  COALESCE(t.prize_pool,0) + COALESCE(t.bounty_pool,0)
                                  - COALESCE(t.bounty_pool_paid,0) + COALESCE(t.total_rake,0))),0)
       FROM tournaments t
       LEFT JOIN public.tournament_escrow e ON e.tournament_id = t.id
      WHERE t.status NOT IN ('COMPLETED','CANCELLED'))                  AS tourn_liab,
    (SELECT COALESCE(sum(leaderboard_seed_remaining),0)
       FROM club_opening_setups)                                        AS lb_liab,
    /* phase 4: cert-held chips, reported not excluded */
    (SELECT COALESCE(sum(cm.chip_balance),0)
       FROM club_members cm
      WHERE public.fn_ca_is_cert_account(cm.user_id))                   AS cert_w
  INTO s;

  v_total := s.member_wallets + s.member_promo + s.felt + s.treasuries + s.chip_pools
           + s.club_promo + s.club_insurance
           + s.club_wallets + s.union_wallets + s.agent_wallets + s.bbj + s.spin + s.tourn_liab + s.lb_liab;

  SELECT * INTO prev FROM public.ca_supply_snapshots ORDER BY taken_at DESC LIMIT 1;
  v_prev_unexplained := CASE WHEN prev.id IS NULL THEN NULL ELSE prev.unexplained END;

  IF prev.id IS NOT NULL THEN
    -- Symmetric: out of a non-circulating store is issuance, into one is
    -- retirement. A store-to-store row appears in each sum once and nets to
    -- zero, which is correct -- it never touched circulation.
    SELECT COALESCE(sum(amount) FILTER (WHERE from_type = ANY(v_outside)),0),
           COALESCE(sum(amount) FILTER (WHERE to_type   = ANY(v_outside)),0)
      INTO v_mint, v_burn
      FROM public.chip_ledger
     WHERE created_at > prev.taken_at
       /* A correction moves no balance (see a_correction_is_not_a_mint):
          counting it as issuance invents drift equal to itself. */
       AND NOT (category = 'correction'
                AND metadata->>'posted_via' = 'fn_ca_post_correction');
  END IF;

  INSERT INTO public.ca_supply_snapshots
    (member_wallets, member_promo, felt, treasuries, chip_pools, club_wallets,
     union_wallets, agent_wallets, bbj_pools, spin_pools, tournament_liability,
     leaderboard_liability, cert_wallets, club_promo, club_insurance, agent_promo, total,
     mint_since_prev, burn_since_prev, delta_vs_prev, unexplained)
  VALUES
    (s.member_wallets, s.member_promo, s.felt, s.treasuries, s.chip_pools,
     s.club_wallets, s.union_wallets, s.agent_wallets, s.bbj, s.spin, s.tourn_liab,
     s.lb_liab, s.cert_w, s.club_promo, s.club_insurance, s.agent_promo, v_total,
     v_mint, v_burn,
     CASE WHEN prev.id IS NULL THEN NULL ELSE v_total - prev.total END,
     CASE WHEN prev.id IS NULL OR prev.tournament_liability IS NULL
            OR prev.leaderboard_liability IS NULL THEN NULL
          ELSE v_total - prev.total - COALESCE(v_mint,0) + COALESCE(v_burn,0) END)
  RETURNING unexplained INTO v_unexplained;

  SELECT COALESCE(sum(unexplained), 0) INTO v_trailing
    FROM public.ca_supply_snapshots
   WHERE taken_at > now() - interval '4 hours' AND unexplained IS NOT NULL;

  IF v_unexplained IS NOT NULL AND abs(v_unexplained) > 100 AND abs(v_trailing) > 300 THEN
    v_critical := abs(v_unexplained) > 25000
               OR (abs(v_trailing) > 2000
                   AND v_prev_unexplained IS NOT NULL
                   AND abs(v_prev_unexplained) > 100
                   AND sign(v_prev_unexplained) = sign(v_unexplained));
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_supply_snapshot', 'ledger_imbalance',
      CASE WHEN v_critical THEN 'critical' ELSE 'warning' END,
      'supply-unexplained:' || to_char(now(), 'YYYY-MM-DD-HH24'),
      v_unexplained, prev.total + COALESCE(v_mint,0) - COALESCE(v_burn,0), v_total,
      'ledger', 'ca_supply_snapshots', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'total chip supply changed by ' || round(v_unexplained,2)
        || ' beyond ledgered issuance/retirement this interval; trailing 4h net '
        || round(v_trailing,2)
        || CASE WHEN v_critical THEN ' - SAME-SIGN across consecutive intervals (a leak persists, oscillation flips)'
                ELSE ' (single-interval swing; previous interval did not agree in sign)' END,
      false, jsonb_build_object('trailing_4h', round(v_trailing,2),
                                 'prev_unexplained', round(COALESCE(v_prev_unexplained,0),2)));
  END IF;

  -- PHASE 6.2 (2026-09-05): the kill switch reads every hour's figure.
  PERFORM public.fn_ca_kill_switch_trip('fn_ca_supply_snapshot', v_unexplained,
    format('the supply meter read %s unexplained in one hour (trailing 4h %s)', round(COALESCE(v_unexplained, 0), 2), round(COALESCE(v_trailing, 0), 2)));

  RETURN v_unexplained;
END
$$;


ALTER FUNCTION public.fn_ca_supply_snapshot() OWNER TO postgres;

--
-- Name: fn_ca_suspense_regression_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_suspense_regression_check() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_rows integer; v_chips numeric;
BEGIN
  SELECT count(*), COALESCE(sum(amount), 0) INTO v_rows, v_chips
  FROM public.chip_ledger
  WHERE (from_type = 'settlement_suspense' OR to_type = 'settlement_suspense')
    AND created_at > now() - interval '60 minutes'
    AND created_at > '2026-09-01 00:17:00+00';

  IF v_rows > 10 OR v_chips > 50 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_suspense_regression_check', 'unauthorized_adjustment', 'warning',
      'suspense-regression',
      round(v_chips, 2), NULL, NULL, 'ledger', 'settlement_suspense',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'unclassified (suspense) flow returned after the phase-2 drain: '
        || v_rows || ' rows / ' || round(v_chips, 2) || ' chips in the last hour'
        || ' - a money path lost (or never had) its category declaration',
      false, jsonb_build_object('rows_last_hour', v_rows, 'chips_last_hour', round(v_chips, 2)));
    RETURN 1;
  END IF;
  RETURN 0;
END $$;


ALTER FUNCTION public.fn_ca_suspense_regression_check() OWNER TO postgres;

--
-- Name: fn_ca_terminal_marker_transition_is_exact(jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_terminal_marker_transition_is_exact(p_old jsonb, p_new jsonb, p_tournament_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    p_old ? 'terminal_closed_at'
    AND p_new ? 'terminal_closed_at'
    AND NULLIF(p_old->>'terminal_closed_at','') IS NULL
    AND NULLIF(p_new->>'terminal_closed_at','') IS NOT NULL
    AND (p_new - 'terminal_closed_at') IS NOT DISTINCT FROM
        (p_old - 'terminal_closed_at')
    AND EXISTS (
      SELECT 1
        FROM public.tournaments t
       WHERE t.id = p_tournament_id
         AND upper(COALESCE(t.status::text,'')) IN
             ('COMPLETED','CANCELLED','CANCELED')
         AND t.ended_at IS NOT NULL
         AND isfinite(t.ended_at)
         AND NULLIF(p_new->>'terminal_closed_at','')::timestamptz
               IS NOT DISTINCT FROM t.ended_at
    ),false)
$$;


ALTER FUNCTION public.fn_ca_terminal_marker_transition_is_exact(p_old jsonb, p_new jsonb, p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_touch_updated_at() OWNER TO postgres;

--
-- Name: fn_ca_tournament_cancellation_receipt(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_cancellation_receipt(p_tournament_id uuid, p_observed_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_h public.tournament_cancellation_receipts%ROWTYPE;
  v_t public.tournaments%ROWTYPE;
  v_e public.tournament_escrow%ROWTYPE;
  v_ids uuid[];
BEGIN
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'cancellation receipt requires a tournament id'
      USING ERRCODE='22004';
  END IF;
  SELECT * INTO v_h FROM public.tournament_cancellation_receipts h
   WHERE h.tournament_id=p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % has no immutable cancellation receipt',
      p_tournament_id USING ERRCODE='P0404';
  END IF;
  IF p_observed_actor_id IS NOT NULL
     AND v_h.actor_id IS DISTINCT FROM p_observed_actor_id THEN
    RAISE EXCEPTION 'cancellation actor disagrees with stored receipt'
      USING ERRCODE='40001';
  END IF;
  SELECT * INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id;
  SELECT * INTO v_e FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id;
  IF v_t.id IS NULL
     OR upper(COALESCE(v_t.status::text,'')) NOT IN ('CANCELLED','CANCELED')
     OR v_t.ended_at IS DISTINCT FROM v_h.settled_at
     OR v_t.current_players IS DISTINCT FROM 0
     OR v_t.prize_pool IS DISTINCT FROM 0::numeric
     OR v_t.bounty_pool IS DISTINCT FROM 0::numeric
     OR v_t.total_rake IS DISTINCT FROM v_h.total_rake_after
     OR v_t.on_break IS DISTINCT FROM false
     OR v_t.break_started_at IS NOT NULL OR v_t.break_ends_at IS NOT NULL
     OR v_e.tournament_id IS NULL OR v_e.enforced IS DISTINCT FROM true
     OR v_e.prize_balance IS DISTINCT FROM 0::numeric
     OR v_e.bounty_balance IS DISTINCT FROM 0::numeric
     OR v_e.fee_balance IS DISTINCT FROM 0::numeric
     OR v_e.closed_at IS DISTINCT FROM v_h.escrow_closed_at
     OR v_e.close_note IS DISTINCT FROM v_h.escrow_close_note THEN
    RAISE EXCEPTION 'cancellation receipt lost its terminal parent or escrow state'
      USING ERRCODE='P0404';
  END IF;

  SELECT COALESCE(array_agg(tp.id ORDER BY tp.id),ARRAY[]::uuid[])
    INTO v_ids FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id;
  IF v_ids IS DISTINCT FROM v_h.source_player_ids OR EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id
       AND (tp.status::text IS DISTINCT FROM 'eliminated'
         OR tp.eliminated_at IS DISTINCT FROM v_h.settled_at
         OR COALESCE(tp.chips,0)<>0 OR COALESCE(tp.current_bounty,0)<>0)) THEN
    RAISE EXCEPTION 'cancellation receipt lost its frozen roster'
      USING ERRCODE='P0404';
  END IF;
  SELECT COALESCE(array_agg(tb.id ORDER BY tb.id),ARRAY[]::uuid[])
    INTO v_ids FROM public.tables tb WHERE tb.tournament_id=p_tournament_id;
  IF v_ids IS DISTINCT FROM v_h.closed_table_ids OR EXISTS (
    SELECT 1 FROM public.tables tb WHERE tb.tournament_id=p_tournament_id
      AND (lower(COALESCE(tb.status::text,''))<>'closed'
        OR lower(COALESCE(tb.lifecycle,''))<>'closed'
        OR tb.current_players IS DISTINCT FROM 0
        OR tb.terminal_closed_at IS DISTINCT FROM v_h.settled_at)) THEN
    RAISE EXCEPTION 'cancellation receipt lost its frozen tables'
      USING ERRCODE='P0404';
  END IF;
  SELECT COALESCE(array_agg(s.id ORDER BY s.table_id,s.id),ARRAY[]::uuid[])
    INTO v_ids FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id;
  IF v_ids IS DISTINCT FROM v_h.source_seat_ids OR EXISTS (
    SELECT 1 FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND (s.left_at IS NULL OR s.status IS DISTINCT FROM 'left'
         OR s.leave_pending IS DISTINCT FROM false
         OR s.is_sitting_out IS DISTINCT FROM false
         OR s.is_away IS DISTINCT FROM false OR s.sit_out_at IS NOT NULL
         OR s.scheduled_leave_hands IS NOT NULL)) THEN
    RAISE EXCEPTION 'cancellation receipt lost its frozen seats'
      USING ERRCODE='P0404';
  END IF;
  SELECT COALESCE(array_agg(s.id ORDER BY s.id),ARRAY[]::uuid[])
    INTO v_ids FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.left_at IS NOT DISTINCT FROM v_h.settled_at;
  IF v_ids IS DISTINCT FROM v_h.released_seat_ids THEN
    RAISE EXCEPTION 'cancellation receipt lost its released-seat identity'
      USING ERRCODE='P0404';
  END IF;

  SELECT COALESCE(array_agg(x.registration_id ORDER BY x.registration_id),
                  ARRAY[]::uuid[])
    INTO v_ids
    FROM (
      SELECT DISTINCT (line->>'registration_id')::uuid AS registration_id
        FROM jsonb_array_elements(v_h.receipt->'refunds') line
      UNION
      SELECT DISTINCT (line->>'registration_id')::uuid AS registration_id
        FROM jsonb_array_elements(v_h.receipt->'ticket_returns') line
    ) x;
  IF v_ids IS DISTINCT FROM v_h.refunded_registration_ids THEN
    RAISE EXCEPTION 'cancellation receipt lost its disposition roster'
      USING ERRCODE='P0404';
  END IF;
  SELECT COALESCE(array_agg(x.id ORDER BY x.id),ARRAY[]::uuid[])
    INTO v_ids
    FROM (
      SELECT unnest(v_h.source_player_ids) AS id
      EXCEPT SELECT unnest(v_h.refunded_registration_ids)
    ) x;
  IF v_ids IS DISTINCT FROM v_h.zero_refund_registration_ids THEN
    RAISE EXCEPTION 'cancellation receipt lost its zero-disposition roster'
      USING ERRCODE='P0404';
  END IF;

  IF (SELECT count(*) FROM public.tournament_refund_tranches tr
       WHERE tr.tournament_id=p_tournament_id
         AND tr.source='atomic_cancel_tournament')
       IS DISTINCT FROM v_h.refund_line_count
     OR (SELECT round(COALESCE(sum(tr.amount_paid_now),0),2)
           FROM public.tournament_refund_tranches tr
          WHERE tr.tournament_id=p_tournament_id
            AND tr.source='atomic_cancel_tournament')
       IS DISTINCT FROM v_h.total_refunded
     OR EXISTS (
       SELECT 1
         FROM jsonb_to_recordset(v_h.receipt->'refunds') AS line(
           registration_id uuid,user_id uuid,entitlement_id uuid,
           entitlement_kind text,source_wallet_club_id uuid,
           gross_paid numeric,amount_paid_before numeric,amount_paid_now numeric,
           refund_prize numeric,refund_bounty numeric,refund_fee numeric,
           obligation_id uuid,idempotency_key text,credit_ledger_id uuid,
           wallet_transaction_id uuid)
         LEFT JOIN public.tournament_players tp ON tp.id=line.registration_id
         LEFT JOIN public.tournament_refund_entitlements e
           ON e.id=line.entitlement_id
         LEFT JOIN public.tournament_refund_tranches tr
           ON tr.wallet_transaction_id=line.wallet_transaction_id
         LEFT JOIN public.tournament_obligations o ON o.id=line.obligation_id
         LEFT JOIN public.wallet_transactions w ON w.id=line.wallet_transaction_id
         LEFT JOIN public.wallet_credit_idempotency k ON k.key=line.idempotency_key
         LEFT JOIN public.chip_ledger l ON l.id=line.credit_ledger_id
        WHERE tp.id IS NULL OR tp.tournament_id IS DISTINCT FROM p_tournament_id
           OR tp.user_id IS DISTINCT FROM line.user_id
           OR e.id IS NULL OR e.tournament_id IS DISTINCT FROM p_tournament_id
           OR e.user_id IS DISTINCT FROM line.user_id
           OR e.entitlement_kind IS DISTINCT FROM 'wallet_charge'
           OR e.entitlement_kind IS DISTINCT FROM line.entitlement_kind
           OR e.refund_wallet_club_id IS DISTINCT FROM line.source_wallet_club_id
           OR e.gross IS DISTINCT FROM line.amount_paid_now
           OR e.refund_prize IS DISTINCT FROM line.refund_prize
           OR e.refund_bounty IS DISTINCT FROM line.refund_bounty
           OR e.refund_fee IS DISTINCT FROM line.refund_fee
           OR (e.entitlement_kind IN ('satellite_seat','tournament_ticket')
               AND e.registration_id IS DISTINCT FROM line.registration_id)
           OR line.gross_paid IS DISTINCT FROM line.amount_paid_now
           OR line.amount_paid_now IS DISTINCT FROM
                round(line.refund_prize+line.refund_bounty+line.refund_fee,2)
           OR tr.wallet_transaction_id IS NULL
           OR tr.idempotency_key IS DISTINCT FROM line.idempotency_key
           OR tr.tournament_id IS DISTINCT FROM p_tournament_id
           OR tr.obligation_id IS DISTINCT FROM line.obligation_id
           OR tr.user_id IS DISTINCT FROM line.user_id
           OR tr.source_wallet_club_id IS DISTINCT FROM line.source_wallet_club_id
           OR tr.entitlement_id IS DISTINCT FROM line.entitlement_id
           OR tr.credit_ledger_id IS DISTINCT FROM line.credit_ledger_id
           OR tr.amount_paid_before IS DISTINCT FROM line.amount_paid_before
           OR tr.amount_paid_now IS DISTINCT FROM line.amount_paid_now
           OR tr.refund_prize IS DISTINCT FROM line.refund_prize
           OR tr.refund_bounty IS DISTINCT FROM line.refund_bounty
           OR tr.refund_fee IS DISTINCT FROM line.refund_fee
           OR tr.source IS DISTINCT FROM 'atomic_cancel_tournament'
           OR o.id IS NULL OR o.tournament_id IS DISTINCT FROM p_tournament_id
           OR o.kind IS DISTINCT FROM 'refund' OR o.place IS NOT NULL
           OR o.user_id IS DISTINCT FROM line.user_id OR o.settled_at IS NULL
           OR o.amount_paid IS DISTINCT FROM o.amount_owed
           OR o.amount_paid IS DISTINCT FROM (
             SELECT round(COALESCE(sum(all_tr.amount_paid_now),0),2)
               FROM public.tournament_refund_tranches all_tr
              WHERE all_tr.obligation_id=o.id)
           OR w.id IS NULL OR w.user_id IS DISTINCT FROM line.user_id
           OR w.related_entity_id IS DISTINCT FROM p_tournament_id
           OR w.type IS DISTINCT FROM 'credit' OR lower(w.category)<>'refund'
           OR w.amount IS DISTINCT FROM line.amount_paid_now
           OR k.key IS NULL OR k.user_id IS DISTINCT FROM line.user_id
           OR k.amount IS DISTINCT FROM line.amount_paid_now
           OR l.id IS NULL OR l.club_id IS DISTINCT FROM line.source_wallet_club_id
           OR l.from_type IS DISTINCT FROM 'prize_liability'
           OR l.from_entity_id IS DISTINCT FROM p_tournament_id
           OR l.to_type IS DISTINCT FROM 'player_wallet'
           OR l.to_entity_id IS DISTINCT FROM line.user_id
           OR l.amount IS DISTINCT FROM line.amount_paid_now)
     OR EXISTS (
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.tournament_id=p_tournament_id
          AND tr.source='atomic_cancel_tournament'
          AND NOT EXISTS (
            SELECT 1 FROM jsonb_to_recordset(v_h.receipt->'refunds') AS line(
              wallet_transaction_id uuid)
             WHERE line.wallet_transaction_id=tr.wallet_transaction_id)) THEN
    RAISE EXCEPTION 'cancellation receipt lost exact refund evidence'
      USING ERRCODE='P0404';
  END IF;

  IF (SELECT count(*) FROM public.tournament_tickets tk
       WHERE tk.id=ANY(v_h.ticket_return_ids))
       IS DISTINCT FROM v_h.ticket_return_count
     OR (SELECT round(COALESCE(sum(tk.value),0),2)
           FROM public.tournament_tickets tk
          WHERE tk.id=ANY(v_h.ticket_return_ids))
       IS DISTINCT FROM v_h.total_ticket_returned
     OR EXISTS (
       SELECT 1
         FROM jsonb_to_recordset(v_h.receipt->'ticket_returns') AS line(
           registration_id uuid,user_id uuid,entitlement_id uuid,
           entitlement_kind text,ticket_id uuid,
           value numeric,source_wallet_club_id uuid,source_satellite_id uuid,
           refund_prize numeric,refund_bounty numeric,refund_fee numeric,
           ledger_id uuid,transaction_id uuid)
         LEFT JOIN public.tournament_players tp ON tp.id=line.registration_id
         LEFT JOIN public.tournament_refund_entitlements e
           ON e.id=line.entitlement_id
         LEFT JOIN public.tournament_tickets tk ON tk.id=line.ticket_id
         LEFT JOIN public.chip_ledger l ON l.id=line.ledger_id
         LEFT JOIN public.chip_transactions ct ON ct.id=line.transaction_id
        WHERE tp.id IS NULL OR tp.tournament_id IS DISTINCT FROM p_tournament_id
           OR tp.user_id IS DISTINCT FROM line.user_id
           OR e.id IS NULL OR e.tournament_id IS DISTINCT FROM p_tournament_id
           OR e.user_id IS DISTINCT FROM line.user_id
           OR e.entitlement_kind NOT IN ('satellite_seat','tournament_ticket')
           OR e.entitlement_kind IS DISTINCT FROM line.entitlement_kind
           OR e.registration_id IS DISTINCT FROM line.registration_id
           OR e.source_satellite_id IS DISTINCT FROM line.source_satellite_id
           OR e.refund_wallet_club_id IS DISTINCT FROM line.source_wallet_club_id
           OR e.gross IS DISTINCT FROM line.value
           OR e.refund_prize IS DISTINCT FROM line.refund_prize
           OR e.refund_bounty IS DISTINCT FROM line.refund_bounty
           OR e.refund_fee IS DISTINCT FROM line.refund_fee
           OR EXISTS (SELECT 1 FROM public.tournament_refund_tranches tr
                       WHERE tr.entitlement_id=line.entitlement_id)
           OR tk.id IS NULL OR tk.id<>ALL(v_h.ticket_return_ids)
           OR tk.source_refund_entitlement_id IS DISTINCT FROM line.entitlement_id
           OR tk.source_tournament_id IS DISTINCT FROM p_tournament_id
           OR tk.source_satellite_id IS DISTINCT FROM line.source_satellite_id
           OR tk.holder_id IS DISTINCT FROM line.user_id
           OR tk.club_id IS DISTINCT FROM line.source_wallet_club_id
           OR tk.value IS DISTINCT FROM line.value
           OR tk.status NOT IN ('issued','redeemed')
           OR tk.redemption_mode IS DISTINCT FROM 'tournament_entry_only'
           OR tk.entry_prize IS DISTINCT FROM line.refund_prize
           OR tk.entry_bounty IS DISTINCT FROM line.refund_bounty
           OR tk.entry_fee IS DISTINCT FROM line.refund_fee
           OR l.id IS NULL
           OR l.idempotency_key IS DISTINCT FROM
                'tourney:'||p_tournament_id::text
                  ||':satellite-ticket-return:'||line.entitlement_id::text
           OR l.tournament_id IS DISTINCT FROM p_tournament_id
           OR l.club_id IS DISTINCT FROM line.source_wallet_club_id
           OR l.from_type IS DISTINCT FROM 'prize_liability'
           OR l.from_entity_id IS DISTINCT FROM p_tournament_id
           OR l.to_type IS DISTINCT FROM 'escrow'
           OR l.to_entity_id IS DISTINCT FROM line.ticket_id
           OR l.category IS DISTINCT FROM 'ticket_issue'
           OR l.amount IS DISTINCT FROM line.value
           OR l.metadata->>'entitlement_kind'
                IS DISTINCT FROM line.entitlement_kind
           OR ct.id IS NULL OR ct.club_id IS DISTINCT FROM line.source_wallet_club_id
           OR ct.to_user_id IS DISTINCT FROM line.user_id
           OR ct.amount IS DISTINCT FROM line.value
           OR ct.transaction_type IS DISTINCT FROM 'tournament_ticket_issue'
           OR ct.metadata->>'ticket_id' IS DISTINCT FROM line.ticket_id::text
           OR ct.metadata->>'entitlement_id' IS DISTINCT FROM line.entitlement_id::text
           OR ct.metadata->>'entitlement_kind'
                IS DISTINCT FROM line.entitlement_kind
           OR ct.metadata->>'ledger_id' IS DISTINCT FROM line.ledger_id::text)
     OR EXISTS (
       SELECT 1 FROM public.tournament_tickets tk
        WHERE tk.id=ANY(v_h.ticket_return_ids)
          AND NOT EXISTS (
            SELECT 1 FROM jsonb_to_recordset(
              v_h.receipt->'ticket_returns') AS line(ticket_id uuid)
             WHERE line.ticket_id=tk.id)) THEN
    RAISE EXCEPTION 'cancellation receipt lost satellite entry-ticket evidence'
      USING ERRCODE='P0404';
  END IF;

  SELECT COALESCE(array_agg(r.id ORDER BY r.id),ARRAY[]::uuid[])
    INTO v_ids FROM public.rake_records r
   WHERE r.tournament_id=p_tournament_id
     AND r.source='atomic_cancel_tournament';
  IF v_ids IS DISTINCT FROM v_h.fee_reversal_ids
     OR (SELECT round(COALESCE(sum(r.rake_amount),0),2)
           FROM public.rake_records r
          WHERE r.tournament_id=p_tournament_id AND r.is_tournament)
        IS DISTINCT FROM v_h.total_rake_after
     OR (SELECT round(COALESCE(-sum(r.rake_amount),0),2)
           FROM public.rake_records r WHERE r.id=ANY(v_h.fee_reversal_ids))
        IS DISTINCT FROM v_h.fees_reversed
     OR EXISTS (
       SELECT 1 FROM public.rake_records reversal
        WHERE reversal.id=ANY(v_h.fee_reversal_ids)
          AND (reversal.rake_amount>=0
            OR reversal.club_id IS NULL
            OR reversal.source IS DISTINCT FROM 'atomic_cancel_tournament'
            OR reversal.metadata->>'kind' NOT IN (
                 'tournament_fee_refund','spin_rake_refund')
            OR (reversal.metadata->>'kind'='tournament_fee_refund' AND (
              jsonb_typeof(reversal.metadata->'original_rake_record_ids')
                IS DISTINCT FROM 'array'
              OR jsonb_array_length(
                   reversal.metadata->'original_rake_record_ids')
                 IS DISTINCT FROM (
                   SELECT count(*)::integer
                     FROM jsonb_array_elements_text(
                       reversal.metadata->'original_rake_record_ids') source(id)
                     JOIN public.rake_records original
                       ON original.id=source.id::uuid
                    WHERE original.tournament_id=p_tournament_id
                      AND original.club_id=reversal.club_id
                      AND original.metadata->>'user_id'=
                          reversal.metadata->>'user_id')
              OR (SELECT round(COALESCE(sum(original.rake_amount),0),2)
                    FROM jsonb_array_elements_text(
                      reversal.metadata->'original_rake_record_ids') source(id)
                    JOIN public.rake_records original ON original.id=source.id::uuid
                   WHERE original.tournament_id=p_tournament_id
                     AND original.club_id=reversal.club_id
                     AND original.metadata->>'user_id'=
                         reversal.metadata->>'user_id')
                 IS DISTINCT FROM -reversal.rake_amount))
            OR (reversal.metadata->>'kind'='spin_rake_refund' AND NOT EXISTS (
              SELECT 1 FROM public.rake_records original
               WHERE original.id::text=
                       reversal.metadata->>'original_rake_record_id'
                 AND original.tournament_id=p_tournament_id
                 AND original.club_id=reversal.club_id
                 AND original.source IN (
                       'fn_spin_book_entry','fn_spin_settle_game')
                 AND original.rake_amount=-reversal.rake_amount)))) THEN
    RAISE EXCEPTION 'cancellation receipt lost exact fee evidence'
      USING ERRCODE='P0404';
  END IF;

  IF v_h.spin_unwind_tournament_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.tournament_spin_cancellation_unwinds u
    JOIN public.spin_reserve_ledger c ON c.id=u.original_contribution_id
    JOIN public.spin_reserve_ledger cr ON cr.id=u.contribution_reversal_id
    JOIN public.chip_ledger cj ON cj.id=u.original_entry_journal_id
    JOIN public.chip_ledger crj ON crj.id=u.contribution_reversal_journal_id
     WHERE u.tournament_id=p_tournament_id AND c.kind='contribution'
       AND cr.kind='contribution_reversal' AND cr.amount=-c.amount
       AND cj.category='spin_entry' AND cj.amount=c.amount
       AND crj.category='reversal' AND crj.amount=c.amount
       AND crj.idempotency_key='spin:'||p_tournament_id::text||':cancel:entry'
       AND ((u.draw_amount=0 AND u.original_draw_id IS NULL
             AND u.draw_reversal_id IS NULL)
         OR (u.draw_amount>0 AND EXISTS (
           SELECT 1 FROM public.spin_reserve_ledger d
           JOIN public.spin_reserve_ledger dr ON dr.id=u.draw_reversal_id
           JOIN public.chip_ledger dj ON dj.id=u.original_draw_journal_id
           JOIN public.chip_ledger drj ON drj.id=u.draw_reversal_journal_id
            WHERE d.id=u.original_draw_id AND d.kind='jackpot_draw'
              AND dr.kind='draw_reversal' AND dr.amount=-d.amount
              AND dj.category='spin_prize' AND dj.amount=-d.amount
              AND drj.category='reversal' AND drj.amount=-d.amount
              AND drj.idempotency_key=
                  'spin:'||p_tournament_id::text||':cancel:draw')))) THEN
    RAISE EXCEPTION 'cancellation receipt lost exact Spin unwind evidence'
      USING ERRCODE='P0404';
  END IF;
  IF v_h.spin_unwind_tournament_id IS NULL AND EXISTS (
    SELECT 1 FROM public.spin_reserve_ledger r
     WHERE r.tournament_id=p_tournament_id AND r.kind='contribution') THEN
    RAISE EXCEPTION 'cancellation receipt omitted the Spin contribution unwind'
      USING ERRCODE='P0404';
  END IF;
  RETURN v_h.receipt;
END;
$$;


ALTER FUNCTION public.fn_ca_tournament_cancellation_receipt(p_tournament_id uuid, p_observed_actor_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_tournament_charge_split(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_charge_split(p_tournament_id uuid, p_charge_category text, p_gross numeric) RETURNS TABLE(refund_prize numeric, refund_bounty numeric, refund_fee numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_t record;
  v_entry record;
  v_kind text := lower(btrim(COALESCE(p_charge_category,'')));
  v_gross numeric := round(COALESCE(p_gross,0),2);
  v_is_bounty boolean;
  v_ratio numeric;
  v_fee numeric;
  v_bounty numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_gross IS NULL
     OR p_gross::text IN ('NaN','Infinity','-Infinity')
     OR p_gross IS DISTINCT FROM v_gross OR v_gross <= 0
     OR v_kind NOT IN ('tournament_buyin','rebuy','addon') THEN
    RAISE EXCEPTION 'tournament charge split received an invalid contract'
      USING ERRCODE = '22003';
  END IF;
  SELECT t.buy_in_amount,t.buy_in_fee,t.bounty_amount,
         t.is_bounty,t.is_pko,t.is_mystery_bounty
    INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament charge split has no tournament %',p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  v_is_bounty := COALESCE(v_t.is_bounty,false)
              OR COALESCE(v_t.is_pko,false)
              OR COALESCE(v_t.is_mystery_bounty,false);
  IF v_kind='tournament_buyin' THEN
    SELECT * INTO v_entry FROM public.fn_tournament_entry_split(
      v_t.buy_in_amount,v_t.buy_in_fee,v_t.bounty_amount,v_is_bounty);
    IF v_entry.charge IS DISTINCT FROM v_gross THEN
      RAISE EXCEPTION
        'tournament buy-in ledger amount % does not match its funded split %',
        v_gross,v_entry.charge USING ERRCODE = '23514';
    END IF;
    refund_prize := v_entry.prize;
    refund_bounty := v_entry.bounty;
    refund_fee := v_entry.rake;
  ELSIF v_kind='addon' THEN
    IF v_gross IS DISTINCT FROM round(v_gross) THEN
      RAISE EXCEPTION 'add-on charge must be a positive whole chip amount'
        USING ERRCODE = '23514';
    END IF;
    refund_prize := v_gross;
    refund_bounty := 0;
    refund_fee := 0;
  ELSE
    IF v_gross IS DISTINCT FROM round(v_gross) THEN
      RAISE EXCEPTION 'rebuy charge must be a positive whole chip amount'
        USING ERRCODE = '23514';
    END IF;
    v_ratio := CASE
      WHEN COALESCE(v_t.buy_in_amount,0)+COALESCE(v_t.buy_in_fee,0)>0
           AND COALESCE(v_t.buy_in_fee,0)>0
        THEN v_t.buy_in_fee/(v_t.buy_in_amount+v_t.buy_in_fee)
      ELSE 0.1 END;
    v_fee := LEAST(
      trunc(v_gross*v_ratio*100+0.000001)/100,
      trunc(v_gross*0.1*100+0.000001)/100);
    v_bounty := CASE WHEN v_is_bounty THEN LEAST(
      GREATEST(0,round(COALESCE(v_t.bounty_amount,0))),v_gross-v_fee)
      ELSE 0 END;
    refund_fee := v_fee;
    refund_bounty := v_bounty;
    refund_prize := round(v_gross-v_fee-v_bounty,2);
  END IF;
  IF refund_prize IS NULL OR refund_bounty IS NULL OR refund_fee IS NULL
     OR refund_prize::text IN ('NaN','Infinity','-Infinity')
     OR refund_bounty::text IN ('NaN','Infinity','-Infinity')
     OR refund_fee::text IN ('NaN','Infinity','-Infinity')
     OR refund_prize < 0 OR refund_bounty < 0 OR refund_fee < 0
     OR v_gross IS DISTINCT FROM
          round(refund_prize+refund_bounty+refund_fee,2) THEN
    RAISE EXCEPTION 'tournament charge split produced invalid component rails'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_ca_tournament_charge_split(p_tournament_id uuid, p_charge_category text, p_gross numeric) OWNER TO postgres;

--
-- Name: fn_ca_tournament_conservation_confirm(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_conservation_confirm() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row     record;
  v_prev    record;
  v_hands   bigint;
  v_raised  int := 0;
  v_sampled int := 0;
BEGIN
  FOR v_row IN SELECT * FROM public.fn_tournament_chip_conservation_check() LOOP
    SELECT COALESCE(sum(tb.hands_dealt), 0) INTO v_hands
      FROM public.tables tb WHERE tb.tournament_id = v_row.tournament_id;

    SELECT * INTO v_prev
      FROM public.ca_tournament_conservation_samples s
     WHERE s.tournament_id = v_row.tournament_id
     ORDER BY s.taken_at DESC LIMIT 1;

    INSERT INTO public.ca_tournament_conservation_samples
      (tournament_id, drift, hands_dealt, players)
    VALUES (v_row.tournament_id, v_row.drift, v_hands, v_row.players);
    v_sampled := v_sampled + 1;

    -- Confirmed only when the drift is unchanged AND the tournament dealt
    -- hands since the previous look. Identical drift across completed hands
    -- cannot be a pot: pots pay out.
    IF v_prev.tournament_id IS NOT NULL
       AND v_prev.drift = v_row.drift
       AND v_hands > v_prev.hands_dealt
    THEN
      PERFORM public.fn_ca_raise_drift_incident(
        p_source          => 'fn_ca_tournament_conservation_confirm',
        p_classification  => 'ledger_imbalance',
        p_severity        => 'critical',
        p_dedupe_key      => 'tourn-conservation:' || v_row.tournament_id::text
                             || ':' || v_row.drift::text,
        p_discrepancy     => v_row.drift,
        p_expected        => v_row.expected_chips,
        p_actual          => v_row.actual_chips,
        p_layer           => 'settlement',
        p_entity_type     => 'tournament',
        p_tournament_id   => v_row.tournament_id,
        p_suspected_cause => 'Tournament chip conservation drift of ' || v_row.drift::text
          || ' held steady across ' || (v_hands - v_prev.hands_dealt)::text
          || ' completed hands, so it is not chips sitting in a pot. Stacks do not '
          || 'add up to buy-ins plus rebuys plus add-ons on "' || v_row.name || '".',
        p_ledger_balanced => false,
        p_metadata        => jsonb_build_object(
          'tournament', v_row.name, 'players', v_row.players,
          'drift_per_player', v_row.drift_per_player,
          'hands_between_samples', v_hands - v_prev.hands_dealt,
          'first_seen_at', v_prev.taken_at));
      v_raised := v_raised + 1;
    END IF;
  END LOOP;

  DELETE FROM public.ca_tournament_conservation_samples
   WHERE taken_at < now() - interval '7 days';

  RETURN jsonb_build_object('checked_at', now(), 'sampled', v_sampled, 'confirmed', v_raised);
END;
$$;


ALTER FUNCTION public.fn_ca_tournament_conservation_confirm() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_tournament_conservation_confirm(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_tournament_conservation_confirm() IS 'Every 10 minutes. Samples tournament chip conservation and raises an incident only for drift that survives a second reading with completed hands in between. Never blocks or pauses a tournament.';


--
-- Name: fn_ca_tournament_entry_gate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_entry_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tclub uuid;
BEGIN
  -- Maintenance escape for deliberate service operations.
  IF current_setting('app.ca_entry_gate_skip', true) = '1' THEN
    RETURN NEW;
  END IF;
  SELECT t.club_id INTO v_tclub FROM public.tournaments t WHERE t.id = NEW.tournament_id;
  IF v_tclub IS NULL THEN
    RETURN NEW; -- clubless tournament: nothing to scope against
  END IF;
  IF NOT public.fn_ca_entry_scope_ok(NEW.user_id, v_tclub) THEN
    RAISE EXCEPTION 'tournament entry refused: player % has no club membership in the scope of tournament % (club/union %). Join a club in this union first.',
      NEW.user_id, NEW.tournament_id, v_tclub
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_tournament_entry_gate() OWNER TO postgres;

--
-- Name: fn_ca_tournament_escrow(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_escrow(p_tournament_id uuid) RETURNS TABLE(prize_in numeric, bounty_in numeric, fee_in numeric, overlay_in numeric, satellite_in numeric, prize_out numeric, bounty_out numeric, fee_out numeric, refund_out numeric, prize_balance numeric, bounty_balance numeric, fee_balance numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH t AS (
  SELECT id,COALESCE(buy_in_amount,0) AS buy_in_amount,
         COALESCE(buy_in_fee,0) AS buy_in_fee,
         COALESCE(bounty_amount,0) AS bounty_amount,
         (COALESCE(is_bounty,false) OR COALESCE(is_pko,false)
          OR COALESCE(is_mystery_bounty,false)) AS is_b
    FROM public.tournaments WHERE id=p_tournament_id
), w AS (
  SELECT
    COALESCE(sum(amount) FILTER (WHERE type='debit'
      AND category IN ('tournament_buyin','rebuy','addon')),0) AS gross_in,
    COALESCE(sum(amount) FILTER (WHERE type='credit' AND category='prize'),0)
      - COALESCE(sum(amount) FILTER (WHERE type='debit'
          AND category IN ('prize','prize_reversal')),0) AS prize_out,
    COALESCE(sum(amount) FILTER (WHERE type='credit' AND category='bounty'),0)
      AS bounty_out,
    COALESCE(sum(amount) FILTER (WHERE type='credit'
      AND category IN ('refund','tournament_refund')),0) AS refund_out
  FROM public.wallet_transactions WHERE related_entity_id=p_tournament_id
), direct_bounty AS (
  SELECT round(COALESCE(sum(CASE
    WHEN NOT t.is_b OR lower(l.category)='addon' THEN 0
    WHEN lower(l.category)='tournament_buyin' THEN round(t.bounty_amount,2)
    ELSE LEAST(
      GREATEST(0,round(t.bounty_amount)),
      round(l.amount,2)-LEAST(
        trunc(round(l.amount,2)*(CASE
          WHEN t.buy_in_amount+t.buy_in_fee>0 AND t.buy_in_fee>0
            THEN t.buy_in_fee/(t.buy_in_amount+t.buy_in_fee)
          ELSE 0.1 END)*100+0.000001)/100,
        trunc(round(l.amount,2)*0.1*100+0.000001)/100))
    END),0),2) AS amount
  FROM t LEFT JOIN public.chip_ledger l
    ON l.tournament_id=p_tournament_id
   AND l.from_type='player_wallet' AND l.to_type='prize_liability'
   AND l.to_entity_id=p_tournament_id
   AND lower(l.category) IN ('tournament_buyin','rebuy','addon')
), rr AS (
  SELECT
    COALESCE(sum(rake_amount),0) AS fee_in,
    COALESCE(sum(rake_amount) FILTER (
      WHERE source='fn_award_satellite_seat'),0) AS fee_sat,
    COALESCE(sum(rake_amount) FILTER (
      WHERE source='fn_award_satellite_seat'
        AND metadata->>'entry_split_version'='2'),0) AS fee_sat_split,
    COALESCE(sum(COALESCE(pot_size,0)-rake_amount) FILTER (
      WHERE source='fn_award_satellite_seat'),0) AS satellite_in
  FROM public.rake_records
  WHERE tournament_id=p_tournament_id AND is_tournament
    AND NOT (rake_amount<0 AND source IN (
      'atomic_cancel_tournament','fn_unregister_from_tournament'))
), ov AS (
  SELECT COALESCE(sum(a.amount),0) AS ledger_overlay
    FROM public.chip_ledger a
   WHERE a.to_entity_id=p_tournament_id
     AND a.to_type='prize_liability'
     AND (a.category='overlay' OR
       (a.category='correction' AND a.from_type IN ('union_bank','club_treasury')))
     AND NOT (COALESCE(a.description,'') LIKE 'auto-ledgered%'
       AND EXISTS (
         SELECT 1 FROM public.chip_ledger b
          WHERE b.to_entity_id=a.to_entity_id AND b.category='overlay'
            AND b.to_type='prize_liability' AND b.id<>a.id
            AND b.amount=a.amount
            AND COALESCE(b.description,'') NOT LIKE 'auto-ledgered%'
            AND abs(extract(epoch FROM (b.created_at-a.created_at)))<5))
), stl AS (
  SELECT COALESCE(sum(amount),0) AS moved,
    COALESCE(sum(amount) FILTER (
      WHERE metadata->>'entry_split_version'='2'),0) AS split_moved,
    COALESCE(sum((metadata->>'entry_fee')::numeric) FILTER (
      WHERE metadata->>'entry_split_version'='2'),0) AS split_fee,
    COALESCE(sum((metadata->>'entry_bounty')::numeric) FILTER (
      WHERE metadata->>'entry_split_version'='2'),0) AS split_bounty
  FROM public.chip_ledger
  WHERE to_entity_id=p_tournament_id AND to_type='prize_liability'
    AND idempotency_key LIKE 'tourney:%:seat:%:pool_transfer'
), tgo AS (
  SELECT COALESCE(sum(amount),0) AS tgo_amount
    FROM public.tournament_guarantee_overlays
   WHERE tournament_id=p_tournament_id
), sat AS (
  SELECT COALESCE(sum(amount),0) AS seats_out
    FROM public.tournament_payouts
   WHERE tournament_id=p_tournament_id AND source='satellite_seat'
), fo AS (
  SELECT COALESCE(sum(amount),0) AS fee_out
    FROM public.tournament_rake_settlements
   WHERE tournament_id=p_tournament_id AND settled_at IS NOT NULL
), exact_refunds AS (
  SELECT COALESCE(sum(amount_paid_now),0) AS total,
         COALESCE(sum(refund_prize),0) AS prize,
         COALESCE(sum(refund_bounty),0) AS bounty,
         COALESCE(sum(refund_fee),0) AS fee
    FROM public.tournament_refund_tranches
   WHERE tournament_id=p_tournament_id
), calc AS (
  SELECT
    round(w.gross_in+stl.split_moved-stl.split_fee,2) AS gross_in,
    round(rr.fee_in,2) AS fee_in,
    round(rr.fee_in-rr.fee_sat,2) AS fee_entries,
    round(direct_bounty.amount+stl.split_bounty,2) AS bounty_in,
    round(CASE WHEN ov.ledger_overlay>0 THEN ov.ledger_overlay
      ELSE tgo.tgo_amount END,2) AS overlay_in,
    round(stl.moved-stl.split_moved-rr.fee_sat+rr.fee_sat_split,2)
      AS satellite_in,
    round(w.prize_out+sat.seats_out,2) AS prize_out,
    round(w.bounty_out,2) AS bounty_out,
    round(fo.fee_out,2) AS fee_out,
    round(w.refund_out,2) AS refund_out,
    round(exact_refunds.total,2) AS exact_total,
    round(exact_refunds.prize,2) AS exact_prize,
    round(exact_refunds.bounty,2) AS exact_bounty,
    round(exact_refunds.fee,2) AS exact_fee
  FROM t,w,direct_bounty,rr,stl,ov,tgo,sat,fo,exact_refunds
), split AS (
  SELECT c.*,round(c.gross_in-c.fee_entries-c.bounty_in,2) AS prize_in,
         round(c.refund_out-c.exact_total,2) AS legacy_refund
    FROM calc c
), apportioned AS (
  SELECT s.*,
    CASE WHEN (s.prize_in+s.satellite_in+s.bounty_in+s.fee_in)>0
      THEN round(s.legacy_refund*(s.prize_in+s.satellite_in)
        /(s.prize_in+s.satellite_in+s.bounty_in+s.fee_in),2)
      ELSE s.legacy_refund END AS legacy_prize,
    CASE WHEN (s.prize_in+s.satellite_in+s.bounty_in+s.fee_in)>0
      THEN round(s.legacy_refund*s.bounty_in
        /(s.prize_in+s.satellite_in+s.bounty_in+s.fee_in),2)
      ELSE 0 END AS legacy_bounty
  FROM split s
)
SELECT a.prize_in,a.bounty_in,a.fee_in,a.overlay_in,a.satellite_in,
       a.prize_out,a.bounty_out,a.fee_out,a.refund_out,
       round(a.prize_in+a.overlay_in+a.satellite_in-a.prize_out
         -a.legacy_prize-a.exact_prize,2) AS prize_balance,
       round(a.bounty_in-a.bounty_out-a.legacy_bounty-a.exact_bounty,2)
         AS bounty_balance,
       round(a.fee_in-a.fee_out
         -(a.legacy_refund-a.legacy_prize-a.legacy_bounty)-a.exact_fee,2)
         AS fee_balance
  FROM apportioned a;
$$;


ALTER FUNCTION public.fn_ca_tournament_escrow(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_tournament_escrow(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_tournament_escrow(p_tournament_id uuid) IS 'Shadow of one tournament''s prize / bounty / fee banks, derived from wallet rows, rake records and ledger legs. A Spin''s reserve movement is NOT here: it lives in tournament_escrow.reserve_out / reserve_in, because fn_ca_escrow_apply derives gross_in from prize_in at first sight and would double count a draw folded into it.';


--
-- Name: fn_ca_tournament_finished_but_not_completed(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_finished_but_not_completed(p_minutes integer DEFAULT 15) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
DECLARE
  v_count   int := 0;
  v_sample  jsonb := '[]'::jsonb;
  v_open    boolean;
  v_cutoff  interval := make_interval(mins => GREATEST(COALESCE(p_minutes, 15), 1));
BEGIN
  WITH stuck AS (
    SELECT t.id AS tournament_id,
           t.name,
           t.started_at,
           (SELECT count(*) FROM public.tournament_players tp
             WHERE tp.tournament_id = t.id
               AND tp.status IN ('playing', 'active', 'registered')) AS alive,
           (SELECT max(tp.eliminated_at) FROM public.tournament_players tp
             WHERE tp.tournament_id = t.id AND tp.eliminated_at IS NOT NULL) AS last_elimination,
           (SELECT count(*) FROM public.tournament_players tp
             WHERE tp.tournament_id = t.id) AS entrants
      FROM public.tournaments t
     WHERE t.status = 'RUNNING'
       AND COALESCE(t.variant, '') <> 'satellite'
       AND upper(COALESCE(t.tournament_type, '')) <> 'SATELLITE'
  )
  SELECT count(*),
         COALESCE(jsonb_agg(jsonb_build_object(
           'tournament_id', tournament_id,
           'name', left(COALESCE(name, ''), 60),
           'entrants', entrants,
           'alive', alive,
           'last_elimination', last_elimination,
           'stuck_for_minutes', round(extract(epoch FROM (now() - last_elimination)) / 60.0, 1))
           ORDER BY last_elimination), '[]'::jsonb)
    INTO v_count, v_sample
    FROM stuck
   WHERE alive <= 1
     AND last_elimination IS NOT NULL
     AND last_elimination < now() - v_cutoff;

  IF v_count > 0 THEN
    SELECT EXISTS (
      SELECT 1 FROM public.financial_alerts fa
       WHERE fa.source = 'fn_ca_tournament_finished_but_not_completed'
         AND COALESCE(fa.resolved, false) = false
    ) INTO v_open;

    IF NOT v_open THEN
      INSERT INTO public.financial_alerts (severity, source, message, context)
      VALUES (
        'critical',
        'fn_ca_tournament_finished_but_not_completed',
        format(
          '%s tournament(s) have one player or fewer left and have not completed '
          || 'for over %s minute(s). Their winners are unpaid, and every other payout '
          || 'check on this database only judges COMPLETED tournaments, so nothing '
          || 'else can see them. Healthy tournaments settle within 20s of the final '
          || 'elimination (p99 over 4,242 events).',
          v_count, GREATEST(COALESCE(p_minutes, 15), 1)),
        jsonb_build_object(
          'checked_at', now(),
          'threshold_minutes', GREATEST(COALESCE(p_minutes, 15), 1),
          'tournaments', v_sample,
          'cause', 'elimination sweep overruns on a saturated engine thread - '
                || 'see docs/HANDOFF_CURRENT_STATE.md section 16 (P0/P1) and '
                || 'docs/changelog/2026-09-07-the-collapse-was-not-the-reload-storm.md')
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'checked_at', now(),
    'threshold_minutes', GREATEST(COALESCE(p_minutes, 15), 1),
    'stuck', v_count,
    'tournaments', v_sample
  );
END;
$$;


ALTER FUNCTION public.fn_ca_tournament_finished_but_not_completed(p_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_tournament_finished_but_not_completed(p_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_tournament_finished_but_not_completed(p_minutes integer) IS 'Tournaments still RUNNING with one player or fewer left, past the threshold. Every other payout check on this database judges COMPLETED tournaments only, so this class was invisible until 2026-09-07. Detector only - settles nothing.';


--
-- Name: fn_ca_tournament_id_from_credit_key(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_id_from_credit_key(p_key text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_id_text text;
  v_id uuid;
BEGIN
  IF p_key LIKE 'tourney:%' OR p_key LIKE 'mb-residual:%' THEN
    v_id_text := split_part(p_key,':',2);
    IF v_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RETURN v_id_text::uuid;
    END IF;
  ELSIF p_key LIKE 'mb:%' THEN
    v_id_text := split_part(p_key,':',2);
    IF v_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      SELECT a.tournament_id INTO v_id
        FROM public.tournament_bounty_awards a WHERE a.id = v_id_text::uuid;
      RETURN v_id;
    END IF;
  END IF;
  RETURN NULL;
END;
$_$;


ALTER FUNCTION public.fn_ca_tournament_id_from_credit_key(p_key text) OWNER TO postgres;

--
-- Name: fn_ca_tournament_place_amounts(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_place_amounts(p_tournament_id uuid) RETURNS TABLE(place integer, amount numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_t record;
  v_pool numeric;
  v_ladder_pool numeric;
  v_bubble_amount numeric := 0;
  v_expected_pool numeric;
  v_pool_cents bigint;
  v_remaining bigint;
  v_share bigint;
  v_total_bp bigint := 0;
  v_bp bigint;
  v_field integer;
  v_struct jsonb;
  v_work jsonb := '[]'::jsonb;
  v_trimmed jsonb := '[]'::jsonb;
  v_entry jsonb;
  v_place_numeric numeric;
  v_pct numeric;
  v_place integer;
  v_valid boolean := true;
  v_is_spin boolean;
  v_known_spin boolean := false;
  v_count integer;
  v_max_place integer;
  v_index integer := 0;
BEGIN
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'place amount derivation requires a tournament id'
      USING ERRCODE = '22004';
  END IF;

  SELECT t.id, t.prize_pool, t.payout_structure, t.variant,
         t.tournament_type, t.is_premium_spin, t.spin_multiplier,
         t.buy_in_amount, t.satellite_target_id, t.satellite_target,
         t.bubble_protection
    INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  IF lower(COALESCE(v_t.variant, '')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type, '')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL
     OR v_t.satellite_target IS NOT NULL THEN
    RAISE EXCEPTION 'tournament % is a satellite, not a cash ladder',
      p_tournament_id USING ERRCODE = '22023';
  END IF;

  v_pool := v_t.prize_pool;
  IF v_pool IS NULL
     OR v_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_pool < 0
     OR v_pool IS DISTINCT FROM round(v_pool, 2) THEN
    RAISE EXCEPTION 'tournament % has invalid whole-cent prize pool %',
      p_tournament_id, v_pool USING ERRCODE = '22003';
  END IF;
  SELECT count(*) INTO v_field FROM public.tournament_players
   WHERE tournament_id = p_tournament_id;
  IF v_field < 1 THEN
    RAISE EXCEPTION 'tournament % has no roster', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;

  v_is_spin := lower(COALESCE(v_t.variant, '')) = 'spin'
               OR COALESCE(v_t.is_premium_spin, false)
               OR upper(COALESCE(v_t.tournament_type, '')) = 'SPIN';
  IF v_is_spin THEN
    IF v_t.spin_multiplier IS NULL
       OR v_t.spin_multiplier::text IN ('NaN','Infinity','-Infinity')
       OR v_t.spin_multiplier <= 0
       OR v_t.buy_in_amount IS NULL
       OR v_t.buy_in_amount::text IN ('NaN','Infinity','-Infinity')
       OR v_t.buy_in_amount < 0
       OR v_t.buy_in_amount IS DISTINCT FROM round(v_t.buy_in_amount, 2) THEN
      RAISE EXCEPTION 'Spin % has invalid locked buy-in/multiplier evidence',
        p_tournament_id USING ERRCODE = '22003';
    END IF;
    v_expected_pool := round(v_t.buy_in_amount * v_t.spin_multiplier, 2);
    IF v_expected_pool::text IN ('NaN','Infinity','-Infinity')
       OR v_pool IS DISTINCT FROM v_expected_pool THEN
      RAISE EXCEPTION
        'Spin % pool % does not equal buy-in % x multiplier % (= %)',
        p_tournament_id, v_pool, v_t.buy_in_amount, v_t.spin_multiplier,
        v_expected_pool USING ERRCODE = '23514';
    END IF;

    IF v_t.spin_multiplier IN (2,3,4,5) THEN
      v_struct := '[{"place":1,"percentage":100}]'::jsonb;
      v_known_spin := true;
    ELSIF v_t.spin_multiplier = 10 THEN
      v_struct := '[{"place":1,"percentage":80},{"place":2,"percentage":20}]'::jsonb;
      v_known_spin := true;
    ELSIF v_t.spin_multiplier IN (25,50,100) THEN
      v_struct := '[{"place":1,"percentage":80},{"place":2,"percentage":12},{"place":3,"percentage":8}]'::jsonb;
      v_known_spin := true;
    END IF;
  END IF;

  -- Unknown/retired Spin multipliers and non-Spins read the stored structure.
  IF NOT v_known_spin THEN
    BEGIN
      v_struct := NULLIF(btrim(COALESCE(v_t.payout_structure::text, '')), '')::jsonb;
    EXCEPTION WHEN invalid_text_representation THEN
      v_struct := NULL;
    END;
  END IF;
  IF v_struct IS NULL OR jsonb_typeof(v_struct) <> 'array'
     OR jsonb_array_length(v_struct) = 0 THEN
    v_valid := false;
  END IF;

  -- Fractional places and non-finite/non-positive shares fail this candidate.
  -- As in computePlacePrize, the first entry for a duplicate place wins.
  IF v_valid THEN
    FOR v_entry IN SELECT value FROM jsonb_array_elements(v_struct) LOOP
      IF jsonb_typeof(v_entry) <> 'object'
         OR v_entry->>'place' IS NULL
         OR v_entry->>'percentage' IS NULL THEN
        v_valid := false; EXIT;
      END IF;
      BEGIN
        v_place_numeric := (v_entry->>'place')::numeric;
        v_pct := (v_entry->>'percentage')::numeric;
      EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        v_valid := false; EXIT;
      END;
      IF v_place_numeric::text IN ('NaN','Infinity','-Infinity')
         OR v_pct::text IN ('NaN','Infinity','-Infinity')
         OR v_place_numeric < 1 OR v_place_numeric <> trunc(v_place_numeric)
         OR v_place_numeric > 2147483647 OR v_pct <= 0 THEN
        v_valid := false; EXIT;
      END IF;
      v_place := v_place_numeric::integer;
      IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_work) e
                  WHERE (e->>'place')::integer = v_place) THEN
        CONTINUE;
      END IF;
      BEGIN
        v_bp := round(v_pct * 100)::bigint;
      EXCEPTION WHEN numeric_value_out_of_range THEN
        v_valid := false; EXIT;
      END;
      IF v_bp <= 0 THEN
        v_valid := false; EXIT;
      END IF;
      v_work := v_work || jsonb_build_object('place',v_place,'bp',v_bp);
    END LOOP;
  END IF;
  IF v_valid AND NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_work) e
     WHERE (e->>'place')::integer = 1
  ) THEN
    v_valid := false;
  END IF;

  IF NOT v_valid THEN
    RAISE EXCEPTION
      'tournament % has no usable canonical payout ladder',
      p_tournament_id USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(jsonb_agg(e ORDER BY (e->>'place')::integer),'[]'::jsonb)
    INTO v_trimmed FROM jsonb_array_elements(v_work) e
   WHERE (e->>'place')::integer <= v_field;
  IF jsonb_array_length(v_trimmed) = 0 THEN
    RAISE EXCEPTION 'tournament % ladder has no place in final field %',
      p_tournament_id, v_field USING ERRCODE = '22023';
  END IF;
  SELECT count(*), COALESCE(sum((e->>'bp')::bigint),0)
    INTO v_count, v_total_bp FROM jsonb_array_elements(v_trimmed) e;
  IF v_total_bp <= 0 THEN
    RAISE EXCEPTION 'tournament % ladder has no positive percentage',
      p_tournament_id USING ERRCODE = '22023';
  END IF;

  SELECT max((e->>'place')::integer)
    INTO v_max_place
    FROM jsonb_array_elements(v_trimmed) e;

  -- Bubble protection is part of the tournament pool, not a house overlay.
  -- When the final field contains a stone bubble, reserve exactly one base
  -- buy-in before pricing the percentage ladder. The bubble and all places
  -- therefore spend the locked prize_pool exactly once between them.
  IF COALESCE(v_t.bubble_protection, false) AND v_field > v_max_place THEN
    IF v_t.buy_in_amount IS NULL
       OR v_t.buy_in_amount::text IN ('NaN','Infinity','-Infinity')
       OR v_t.buy_in_amount <= 0
       OR v_t.buy_in_amount IS DISTINCT FROM round(v_t.buy_in_amount, 2) THEN
      RAISE EXCEPTION
        'tournament % has bubble protection but invalid whole-cent buy-in %',
        p_tournament_id, v_t.buy_in_amount USING ERRCODE = '22003';
    END IF;
    v_bubble_amount := round(v_t.buy_in_amount, 2);
    IF v_bubble_amount > v_pool THEN
      RAISE EXCEPTION
        'tournament % bubble amount % exceeds locked prize pool %',
        p_tournament_id, v_bubble_amount, v_pool USING ERRCODE = '23514';
    END IF;
  END IF;

  v_ladder_pool := round(v_pool - v_bubble_amount, 2);
  v_pool_cents := round(v_ladder_pool * 100)::bigint;

  -- Mirror computePlacePrize: normalize to surviving basis points, spend down
  -- in place order, and give the exact remaining cents to the last place.
  v_remaining := v_pool_cents;
  FOR v_entry IN
    SELECT e FROM jsonb_array_elements(v_trimmed) e
     ORDER BY (e->>'place')::integer
  LOOP
    v_index := v_index + 1;
    v_place := (v_entry->>'place')::integer;
    v_bp := (v_entry->>'bp')::bigint;
    IF v_index = v_count THEN
      v_share := v_remaining;
    ELSE
      v_share := LEAST(v_remaining,
        round((v_pool_cents::numeric * v_bp::numeric) / v_total_bp::numeric)::bigint);
    END IF;
    v_share := GREATEST(v_share,0);
    v_remaining := v_remaining - v_share;
    place := v_place;
    amount := (v_share::numeric / 100)::numeric(15,2);
    IF amount::text IN ('NaN','Infinity','-Infinity')
       OR amount < 0 OR amount IS DISTINCT FROM round(amount,2) THEN
      RAISE EXCEPTION 'derived invalid amount % for tournament %, place %',
        amount, p_tournament_id, place USING ERRCODE = '22003';
    END IF;
    RETURN NEXT;
  END LOOP;
  IF v_remaining <> 0 THEN
    RAISE EXCEPTION 'tournament % ladder left % cents undistributed',
      p_tournament_id, v_remaining USING ERRCODE = '23514';
  END IF;
END;
$$;


ALTER FUNCTION public.fn_ca_tournament_place_amounts(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_tournament_place_amounts(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_tournament_place_amounts(p_tournament_id uuid) IS 'Owner-only exact-cent cash ladder derived from the locked tournament row and final field; a due bubble buy-in is reserved from the pool before percentages, and known Spins use the canonical drawn tier.';


--
-- Name: fn_ca_tournament_refund_plan(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_refund_plan(p_tournament_id uuid, p_user_id uuid) RETURNS TABLE(source_wallet_club_id uuid, gross_remaining numeric, prize_remaining numeric, bounty_remaining numeric, fee_remaining numeric, debit_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_escrow public.tournament_escrow%ROWTYPE;
  v_wallet_count bigint;
  v_wallet_total numeric;
  v_charge_count bigint;
  v_charge_total numeric;
  v_refund_count bigint;
  v_refund_total numeric;
  v_tranche_count bigint;
  v_tranche_total numeric;
  v_wallet_gross numeric;
  v_direct_fee numeric;
  v_satellite_fee numeric;
  v_bounty numeric;
  v_satellite_in numeric;
  v_invalid bigint;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'refund plan requires tournament and player ids'
      USING ERRCODE = '22004';
  END IF;
  PERFORM 1 FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'refund plan tournament % does not exist',p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  PERFORM 1 FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id
   ORDER BY e.user_id,e.entitlement_kind,e.id FOR SHARE;
  PERFORM 1 FROM public.tournament_refund_tranches tr
   WHERE tr.tournament_id=p_tournament_id
   ORDER BY tr.user_id,tr.entitlement_id FOR SHARE;

  SELECT count(*),round(COALESCE(sum(w.amount),0),2)
    INTO v_wallet_count,v_wallet_total
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.type='debit'
     AND lower(w.category) IN ('tournament_buyin','rebuy','addon');
  SELECT count(*),round(COALESCE(sum(e.gross),0),2)
    INTO v_charge_count,v_charge_total
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id
     AND e.entitlement_kind='wallet_charge';
  IF v_wallet_count IS DISTINCT FROM v_charge_count
     OR v_wallet_total IS DISTINCT FROM v_charge_total THEN
    RAISE EXCEPTION
      'tournament % wallet charges and immutable entitlements disagree',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_invalid
    FROM public.tournament_refund_entitlements e
    LEFT JOIN public.chip_ledger l ON l.id=e.source_ledger_id
   WHERE e.tournament_id=p_tournament_id
     AND (
       l.id IS NULL OR l.club_id IS DISTINCT FROM e.refund_wallet_club_id
       OR l.amount IS DISTINCT FROM e.gross
       OR (e.entitlement_kind='wallet_charge' AND (
         l.tournament_id IS DISTINCT FROM e.tournament_id
         OR l.from_type IS DISTINCT FROM 'player_wallet'
         OR l.from_entity_id IS DISTINCT FROM e.user_id
         OR l.to_type IS DISTINCT FROM 'prize_liability'
         OR l.to_entity_id IS DISTINCT FROM e.tournament_id
         OR lower(l.category) IS DISTINCT FROM e.charge_category))
       OR (e.entitlement_kind='satellite_seat' AND (
         l.from_type IS DISTINCT FROM 'prize_liability'
         OR l.from_entity_id IS DISTINCT FROM e.source_satellite_id
         OR l.to_type IS DISTINCT FROM 'prize_liability'
         OR l.to_entity_id IS DISTINCT FROM e.tournament_id
         OR l.metadata->>'user_id' IS DISTINCT FROM e.user_id::text
         OR l.metadata->>'registration_id' IS DISTINCT FROM
              e.registration_id::text))
       OR (e.entitlement_kind='tournament_ticket' AND (
         l.tournament_id IS DISTINCT FROM e.tournament_id
         OR l.from_type IS DISTINCT FROM 'escrow'
         OR l.from_entity_id IS DISTINCT FROM e.source_ticket_id
         OR l.to_type IS DISTINCT FROM 'prize_liability'
         OR l.to_entity_id IS DISTINCT FROM e.tournament_id
         OR l.category IS DISTINCT FROM 'ticket_redeem'
         OR l.metadata->>'user_id' IS DISTINCT FROM e.user_id::text
         OR l.metadata->>'registration_id' IS DISTINCT FROM
              e.registration_id::text))
     );
  IF v_invalid <> 0 THEN
    RAISE EXCEPTION 'tournament % has % invalid refund entitlement sources',
      p_tournament_id,v_invalid USING ERRCODE = 'P0404';
  END IF;

  SELECT round(COALESCE(sum(CASE
           WHEN e.escrow_bucket IN ('wallet_gross','ticket_gross')
             THEN e.gross
           WHEN e.escrow_bucket='satellite_gross'
             THEN e.refund_prize+e.refund_bounty ELSE 0 END),0),2),
         round(COALESCE(sum(CASE
           WHEN e.entitlement_kind IN ('wallet_charge','tournament_ticket')
             THEN e.refund_fee
           ELSE 0 END),0),2),
         round(COALESCE(sum(CASE
           WHEN e.entitlement_kind='satellite_seat' THEN e.refund_fee
           ELSE 0 END),0),2),
         round(COALESCE(sum(CASE
           WHEN e.escrow_bucket IN (
             'wallet_gross','satellite_gross','ticket_gross')
             THEN e.refund_bounty ELSE 0 END),0),2),
         round(COALESCE(sum(CASE
           WHEN e.escrow_bucket='satellite_in'
             THEN e.refund_prize+e.refund_bounty ELSE 0 END),0),2)
    INTO v_wallet_gross,v_direct_fee,v_satellite_fee,v_bounty,v_satellite_in
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id;
  SELECT * INTO v_escrow FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id FOR SHARE;
  IF v_escrow.tournament_id IS NULL
     OR v_escrow.enforced IS DISTINCT FROM true
     OR v_escrow.gross_in IS DISTINCT FROM v_wallet_gross
     OR v_escrow.fee_entries_in IS DISTINCT FROM v_direct_fee
     OR v_escrow.satellite_fee_in IS DISTINCT FROM v_satellite_fee
     OR v_escrow.bounty_in IS DISTINCT FROM v_bounty
     OR v_escrow.satellite_in IS DISTINCT FROM v_satellite_in THEN
    RAISE EXCEPTION
      'tournament % escrow does not equal its immutable entitlement rails',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*),round(COALESCE(sum(w.amount),0),2)
    INTO v_refund_count,v_refund_total
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=p_user_id
     AND w.type='credit'
     AND lower(w.category) IN ('refund','tournament_refund');
  SELECT count(*),round(COALESCE(sum(tr.amount_paid_now),0),2)
    INTO v_tranche_count,v_tranche_total
    FROM public.tournament_refund_tranches tr
   WHERE tr.tournament_id=p_tournament_id AND tr.user_id=p_user_id;
  IF v_refund_count IS DISTINCT FROM v_tranche_count
     OR v_refund_total IS DISTINCT FROM v_tranche_total THEN
    RAISE EXCEPTION
      'player % tournament % has refund money without exact entitlement tranches',
      p_user_id,p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.tournament_refund_tranches tr
    JOIN public.tournament_refund_entitlements e ON e.id=tr.entitlement_id
    WHERE tr.tournament_id=p_tournament_id AND (
      e.tournament_id IS DISTINCT FROM tr.tournament_id
      OR e.user_id IS DISTINCT FROM tr.user_id
      OR e.refund_wallet_club_id IS DISTINCT FROM tr.source_wallet_club_id
      OR e.gross IS DISTINCT FROM tr.amount_paid_now
      OR e.refund_prize IS DISTINCT FROM tr.refund_prize
      OR e.refund_bounty IS DISTINCT FROM tr.refund_bounty
      OR e.refund_fee IS DISTINCT FROM tr.refund_fee)
  ) THEN
    RAISE EXCEPTION 'tournament % has a tranche detached from its entitlement',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  RETURN QUERY
  SELECT e.refund_wallet_club_id,e.gross,e.refund_prize,e.refund_bounty,
         e.refund_fee,1::bigint
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND e.entitlement_kind='wallet_charge'
     AND NOT EXISTS (
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=e.id)
     AND NOT EXISTS (
       SELECT 1 FROM public.tournament_tickets tk
        WHERE tk.source_refund_entitlement_id=e.id)
   ORDER BY e.entitlement_kind,e.id;
END;
$$;


ALTER FUNCTION public.fn_ca_tournament_refund_plan(p_tournament_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_tournament_seat_move_receipt(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_seat_move_receipt(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'ok',true,
    'request_id',r.request_id,
    'tournament_id',r.tournament_id,
    'user_id',r.user_id,
    'source_table_id',r.source_table_id,
    'destination_table_id',r.destination_table_id,
    'source_seat_id',r.source_seat_id,
    'destination_seat_id',r.destination_seat_id,
    'source_seat_number',r.source_seat_number,
    'destination_seat_number',r.destination_seat_number,
    'stack',r.stack,
    'moved_at',r.moved_at)
  FROM public.tournament_seat_move_receipts r
  WHERE r.request_id=p_request_id;
$$;


ALTER FUNCTION public.fn_ca_tournament_seat_move_receipt(p_request_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_tournament_settlement_mismatch(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_settlement_mismatch(p_window interval DEFAULT '48:00:00'::interval) RETURNS TABLE(kind text, tournament_id uuid, name text, ended_at timestamp with time zone, prize_pool numeric, guaranteed_prize numeric, paid numeric, delta numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH p AS (
    SELECT t.id, t.name, t.ended_at, t.tournament_type,
           round(COALESCE(t.prize_pool, 0), 2)       AS pool,
           round(COALESCE(t.guaranteed_prize, 0), 2) AS guar,
           COALESCE(t.satellite_seats, 0)            AS seats,
           COALESCE((SELECT round(sum(w.amount), 2)
                       FROM public.wallet_transactions w
                      WHERE w.related_entity_id = t.id
                        AND w.type = 'credit'
                        AND COALESCE(w.category, '') <> 'bounty'), 0) AS paid
      FROM public.tournaments t
     WHERE t.status = 'COMPLETED'
       AND COALESCE(t.prize_pool, 0) > 0
       AND t.ended_at > now() - p_window
       -- a satellite pays in SEATS and a Spin pays a club-funded multiple;
       -- neither is measurable against the pool. Do NOT use spin_type here:
       -- it is the string 'standard' on every row in the table, MTTs included.
       AND COALESCE(t.satellite_seats, 0) = 0
       AND t.tournament_type <> 'SPIN'
  )
  SELECT 'underpaid', id, name, ended_at, pool, guar, paid,
         round(GREATEST(pool, guar) - paid, 2)
    FROM p WHERE paid + 0.01 < GREATEST(pool, guar)
  UNION ALL
  SELECT 'overpaid', id, name, ended_at, pool, guar, paid,
         round(paid - GREATEST(pool, guar), 2)
    FROM p WHERE paid > GREATEST(pool, guar) + 0.01
   ORDER BY 8 DESC;
$$;


ALTER FUNCTION public.fn_ca_tournament_settlement_mismatch(p_window interval) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_tournament_settlement_mismatch(p_window interval); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_tournament_settlement_mismatch(p_window interval) IS 'Completed tournaments where the credits do not match what the event owed: GREATEST(prize_pool, guaranteed_prize). Reports BOTH directions - underpaid is a player who did not get what was promised, overpaid is chips created. Excludes satellites (paid in seats) and Spins (club-funded multiplier).';


--
-- Name: fn_ca_tournament_terminal_receipt(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_terminal_receipt(p_tournament_id uuid, p_observed_winner_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_h public.tournament_terminal_settlements%ROWTYPE;
  v_t record;
  v_e public.tournament_escrow%ROWTYPE;
  v_r record;
  v_cash_count integer;
  v_cash_total numeric(15,2);
  v_cash_obligation_total numeric(15,2);
  v_bounty_total numeric(15,2);
  v_rake_total numeric(15,2);
  v_roster_count integer;
  v_winner_count integer;
  v_raw_winner_id uuid;
  v_raw_winner_amount numeric(15,2);
  v_bubble jsonb;
  v_durable_payouts jsonb;
  v_durable_deal_shares jsonb;
  v_durable_bubble jsonb;
  v_durable_table_ids uuid[];
  v_durable_table_count integer;
  v_durable_seat_ids uuid[];
  v_durable_seat_count integer;
  v_durable_released_count integer;
  v_mystery_evidence jsonb;
BEGIN
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'terminal receipt requires a tournament id'
      USING ERRCODE = '22004';
  END IF;

  SELECT * INTO v_h
    FROM public.tournament_terminal_settlements h
   WHERE h.tournament_id = p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % has no immutable terminal receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF p_observed_winner_id IS NOT NULL
     AND v_h.winner_id IS DISTINCT FROM p_observed_winner_id THEN
    RAISE EXCEPTION 'tournament % receipt winner % differs from observed winner %',
      p_tournament_id, v_h.winner_id, p_observed_winner_id
      USING ERRCODE = '40001';
  END IF;

  SELECT t.id,t.status,t.variant,t.tournament_type,t.satellite_target_id,
         t.satellite_target,t.prize_pool,t.bounty_pool,t.bounty_pool_paid,
         t.is_bounty,t.is_pko,t.is_mystery_bounty,t.mystery_bounty_stage,
         t.mystery_bounty_pool_cents,t.club_id,t.ended_at,t.on_break,
         t.break_started_at,t.break_ends_at
    INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF v_t.id IS NULL THEN
    RAISE EXCEPTION 'terminal receipt lost tournament %', p_tournament_id
      USING ERRCODE = 'P0404';
  END IF;
  IF lower(COALESCE(v_t.variant::text, '')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type::text, '')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL
     OR v_t.satellite_target IS NOT NULL THEN
    RAISE EXCEPTION 'terminal receipt % belongs to a satellite', p_tournament_id
      USING ERRCODE = 'P0404';
  END IF;
  IF upper(COALESCE(v_t.status::text, '')) <> 'COMPLETED'
     OR v_t.ended_at IS DISTINCT FROM v_h.completed_at
     OR COALESCE(v_t.on_break, false)
     OR v_t.break_started_at IS NOT NULL
     OR v_t.break_ends_at IS NOT NULL THEN
    RAISE EXCEPTION 'tournament % is not durably closed by its receipt',
      p_tournament_id USING ERRCODE = '55000';
  END IF;

  -- Every mutable child carries the same tuple-owned close fact. This makes a
  -- replay prove the synchronous marker transition itself, while queued
  -- writers can reject from OLD after a row-lock wait without relying on a
  -- pre-wait statement snapshot of the parent or receipt.
  IF EXISTS (SELECT 1 FROM public.tournament_players x
              WHERE x.tournament_id=p_tournament_id
                AND x.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (SELECT 1 FROM public.tournament_obligations x
                 WHERE x.tournament_id=p_tournament_id
                   AND x.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (SELECT 1 FROM public.tournament_payouts x
                 WHERE x.tournament_id=p_tournament_id
                   AND x.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (SELECT 1 FROM public.tournament_rake_settlements x
                 WHERE x.tournament_id=p_tournament_id
                   AND x.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (SELECT 1 FROM public.rake_records x
                 WHERE x.tournament_id=p_tournament_id
                   AND x.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (SELECT 1 FROM public.tournament_bounty_chests x
                 WHERE x.tournament_id=p_tournament_id
                   AND x.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (SELECT 1 FROM public.tournament_bounty_awards x
                 WHERE x.tournament_id=p_tournament_id
                   AND x.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (SELECT 1 FROM public.tournament_guarantee_overlays x
                 WHERE x.tournament_id=p_tournament_id
                   AND x.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (
       SELECT 1 FROM public.table_seats s
       JOIN public.tables tb ON tb.id=s.table_id
        WHERE tb.tournament_id=p_tournament_id
          AND s.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (SELECT 1 FROM public.wallet_transactions x
                 WHERE x.related_entity_id=p_tournament_id
                   AND x.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (
       SELECT 1 FROM public.tournament_bounty_award_recipients r
       JOIN public.tournament_bounty_awards a ON a.id=r.award_id
        WHERE a.tournament_id=p_tournament_id
          AND r.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (SELECT 1 FROM public.tournament_escrow x
                 WHERE x.tournament_id=p_tournament_id
                   AND x.terminal_closed_at IS DISTINCT FROM v_h.completed_at)
     OR EXISTS (SELECT 1 FROM public.spin_reserve_ledger x
                 WHERE x.tournament_id=p_tournament_id
                   AND x.kind NOT IN ('contribution','jackpot_draw')
                   AND x.terminal_closed_at IS DISTINCT FROM v_h.completed_at) THEN
    RAISE EXCEPTION 'tournament % mutable evidence lacks its exact terminal marker',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- Table closure is money-adjacent terminal state, not an asynchronous UI
  -- cleanup. The immutable identities prove that no tournament table vanished,
  -- appeared or reopened after this receipt and that every seat released by
  -- the terminal transaction still has its exact terminal state.
  SELECT COALESCE(array_agg(tb.id ORDER BY tb.id),ARRAY[]::uuid[]),count(*)
    INTO v_durable_table_ids,v_durable_table_count
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id;
  SELECT COALESCE(array_agg(s.id ORDER BY s.id),ARRAY[]::uuid[]),count(*)
    INTO v_durable_seat_ids,v_durable_seat_count
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id;
  SELECT count(*) INTO v_durable_released_count
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id
     AND s.id = ANY(v_h.released_seat_ids)
     AND s.left_at IS NOT DISTINCT FROM v_h.completed_at
     AND COALESCE(s.status,'') = 'left'
     AND COALESCE(s.leave_pending,false) IS FALSE
     AND COALESCE(s.is_sitting_out,false) IS FALSE;
  IF v_durable_table_ids IS DISTINCT FROM v_h.closed_table_ids
     OR v_durable_table_count IS DISTINCT FROM v_h.closed_table_count
     OR v_durable_seat_ids IS DISTINCT FROM v_h.source_seat_ids
     OR v_durable_seat_count IS DISTINCT FROM v_h.source_seat_count
     OR v_durable_released_count IS DISTINCT FROM v_h.released_seat_count
     OR EXISTS (
       SELECT 1 FROM public.tables tb
        WHERE tb.tournament_id = p_tournament_id
          AND (lower(COALESCE(tb.status::text,'')) <> 'closed'
            OR lower(COALESCE(tb.lifecycle,'')) <> 'closed'
            OR tb.current_players IS DISTINCT FROM 0
            OR tb.terminal_closed_at IS DISTINCT FROM v_h.completed_at))
     OR EXISTS (
       SELECT 1
         FROM public.table_seats s
         JOIN public.tables tb ON tb.id = s.table_id
        WHERE tb.tournament_id = p_tournament_id
          AND (s.left_at IS NULL
            OR s.status IS DISTINCT FROM 'left'
            OR s.terminal_closed_at IS DISTINCT FROM v_h.completed_at
            OR s.leave_pending IS DISTINCT FROM false
            OR s.is_sitting_out IS DISTINCT FROM false
            OR s.is_away IS DISTINCT FROM false
            OR s.sit_out_at IS NOT NULL
            OR s.scheduled_leave_hands IS NOT NULL)) THEN
    RAISE EXCEPTION 'tournament % table or seat closure differs from its immutable receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF v_t.prize_pool IS NULL
     OR v_t.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR round(v_t.prize_pool,2) IS DISTINCT FROM v_h.prize_pool
     OR v_t.bounty_pool IS NULL
     OR v_t.bounty_pool::text IN ('NaN','Infinity','-Infinity')
     OR round(v_t.bounty_pool,2) IS DISTINCT FROM v_h.bounty_pool THEN
    RAISE EXCEPTION 'tournament % pools differ from its immutable receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*),
         count(*) FILTER (WHERE tp.status::text = 'winner'
                            AND tp.position = 1)
    INTO v_roster_count,v_winner_count
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  IF v_roster_count < 1 OR v_winner_count <> 1
     OR NOT EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.user_id = v_h.winner_id
          AND tp.status::text = 'winner' AND tp.position = 1
          AND tp.eliminated_at IS NULL
          AND tp.elimination_sequence IS NULL)
     OR (SELECT count(tp.position) FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id) <> v_roster_count
     OR (SELECT count(DISTINCT tp.position) FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id) <> v_roster_count
     OR (SELECT min(tp.position) FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id) <> 1
     OR (SELECT max(tp.position) FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id) <> v_roster_count
     OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.status::text NOT IN ('winner','eliminated')) THEN
    RAISE EXCEPTION 'tournament % has ambiguous or incomplete final standings',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF jsonb_typeof(v_h.cash_receipt->'payouts') <> 'array'
     OR COALESCE((v_h.cash_receipt->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_h.cash_receipt->>'fully_settled')::boolean,false) IS NOT TRUE
     OR upper(COALESCE(v_h.cash_receipt->>'status','')) <> 'COMPLETING'
     OR v_h.cash_receipt->>'winner_amount' IS NULL
     OR (v_h.cash_receipt->>'winner_amount')::numeric < 0
     OR (v_h.cash_receipt->>'winner_amount')::numeric IS DISTINCT FROM
          round((v_h.cash_receipt->>'winner_amount')::numeric,2)
     OR (v_h.settlement_mode = 'final_table_deal'
         AND v_h.cash_receipt->>'money_path'
               IS DISTINCT FROM 'fn_settle_tournament_final_table_deal') THEN
    RAISE EXCEPTION 'tournament % stored a malformed cash authority receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT (p->>'user_id')::uuid,(p->>'amount')::numeric
    INTO v_raw_winner_id,v_raw_winner_amount
    FROM jsonb_array_elements(v_h.cash_receipt->'payouts') p
   WHERE (p->>'place')::integer = 1;
  IF v_raw_winner_id IS DISTINCT FROM v_h.winner_id
     OR v_raw_winner_amount IS DISTINCT FROM
          (v_h.cash_receipt->>'winner_amount')::numeric
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_h.cash_receipt->'payouts') p
        WHERE p->>'place' IS NULL OR p->>'user_id' IS NULL
           OR p->>'amount' IS NULL
           OR (p->>'place')::integer < 1
           OR (p->>'amount')::numeric < 0
           OR (p->>'amount')::numeric IS DISTINCT FROM
                round((p->>'amount')::numeric,2)
           OR NOT EXISTS (
             SELECT 1 FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.position = (p->>'place')::integer
                AND tp.user_id = (p->>'user_id')::uuid))
     OR (SELECT count(*) FROM jsonb_array_elements(v_h.cash_receipt->'payouts')) < 1
     OR (SELECT count(DISTINCT (p->>'place')::integer)
           FROM jsonb_array_elements(v_h.cash_receipt->'payouts') p)
          <> (SELECT count(*) FROM jsonb_array_elements(v_h.cash_receipt->'payouts')) THEN
    RAISE EXCEPTION 'tournament % cash receipt does not name exact finishers',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- Satellite and bounty records never consume the ordinary prize pool.
  IF EXISTS (
    SELECT 1 FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.source IN ('satellite_seat','satellite_ticket','satellite_remainder')
  ) THEN
    RAISE EXCEPTION 'non-satellite tournament % carries satellite payout evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  SELECT count(*),round(COALESCE(sum(p.amount),0),2)
    INTO v_cash_count,v_cash_total
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id
     AND p.source NOT IN (
       'bounty','bounty_residual','own_bounty','mystery_bounty',
       'mystery_bounty_residual','satellite_seat','satellite_ticket',
       'satellite_remainder');
  IF v_cash_count IS DISTINCT FROM v_h.cash_payout_count
     OR v_cash_total IS DISTINCT FROM v_h.cash_payout_total
     OR v_cash_total IS DISTINCT FROM v_h.prize_pool
     OR EXISTS (
       SELECT 1 FROM public.tournament_payouts p
        WHERE p.tournament_id = p_tournament_id
          AND p.source NOT IN (
            'bounty','bounty_residual','own_bounty','mystery_bounty',
            'mystery_bounty_residual','satellite_seat','satellite_ticket',
            'satellite_remainder')
          AND (p.amount IS NULL
            OR p.amount::text IN ('NaN','Infinity','-Infinity')
            OR p.amount <= 0 OR p.amount IS DISTINCT FROM round(p.amount,2)
            OR p.idempotency_key IS NULL OR NOT EXISTS (
              SELECT 1 FROM public.wallet_credit_idempotency k
               WHERE k.key = p.idempotency_key
                 AND k.user_id = p.user_id AND k.amount = p.amount))) THEN
    RAISE EXCEPTION 'tournament % cash payout evidence is incomplete or malformed',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'place',q.place,'user_id',q.user_id,'amount',q.amount)
           ORDER BY q.place,q.user_id),'[]'::jsonb)
    INTO v_durable_payouts
    FROM (
      SELECT tp.position AS place,p.user_id,round(sum(p.amount),2) AS amount
        FROM public.tournament_payouts p
        JOIN public.tournament_players tp
          ON tp.tournament_id = p_tournament_id AND tp.user_id = p.user_id
       WHERE p.tournament_id = p_tournament_id
         AND p.source <> 'bubble_protection'
         AND p.source NOT IN (
           'bounty','bounty_residual','own_bounty','mystery_bounty',
           'mystery_bounty_residual','satellite_seat','satellite_ticket',
           'satellite_remainder')
       GROUP BY tp.position,p.user_id
    ) q;
  IF v_h.prize_pool = 0 AND v_durable_payouts = '[]'::jsonb THEN
    -- A zero-cash event has a real winner and no wallet/payout mutation. Keep
    -- that explicit standings line in the receipt without inventing durable
    -- payment evidence.
    v_durable_payouts := jsonb_build_array(jsonb_build_object(
      'place',1,'user_id',v_h.winner_id,'amount',0));
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'place',q.place,'user_id',q.user_id,'amount',q.amount)
           ORDER BY q.place,q.user_id),'[]'::jsonb)
    INTO v_durable_deal_shares
    FROM (
      SELECT tp.position AS place,p.user_id,round(sum(p.amount),2) AS amount
        FROM public.tournament_payouts p
        JOIN public.tournament_players tp
          ON tp.tournament_id = p_tournament_id AND tp.user_id = p.user_id
       WHERE p.tournament_id = p_tournament_id
         AND p.source = 'final_table_deal'
       GROUP BY tp.position,p.user_id
    ) q;
  IF (SELECT count(*) FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.source = 'bubble_protection') > 1 THEN
    RAISE EXCEPTION 'tournament % has multiple durable bubble payout lines',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  SELECT jsonb_build_object(
           'user_id',p.user_id,'position',tp.position,'amount',p.amount)
    INTO v_durable_bubble
    FROM public.tournament_payouts p
    JOIN public.tournament_players tp
      ON tp.tournament_id = p_tournament_id AND tp.user_id = p.user_id
   WHERE p.tournament_id = p_tournament_id
     AND p.source = 'bubble_protection';
  v_durable_bubble := COALESCE(v_durable_bubble,'null'::jsonb);
  IF v_h.cash_receipt->'payouts' IS DISTINCT FROM v_durable_payouts
     OR jsonb_typeof(v_h.cash_receipt->'deal_shares') <> 'array'
     OR v_h.cash_receipt->'deal_shares' IS DISTINCT FROM
          (CASE WHEN v_h.settlement_mode = 'final_table_deal'
                THEN v_durable_deal_shares ELSE '[]'::jsonb END)
     OR COALESCE(v_h.cash_receipt->'bubble_protection','null'::jsonb)
          IS DISTINCT FROM v_durable_bubble
     OR ((SELECT round(COALESCE(sum((p->>'amount')::numeric),0),2)
            FROM jsonb_array_elements(v_durable_payouts) p)
         + (CASE WHEN v_durable_bubble = 'null'::jsonb THEN 0
                 ELSE (v_durable_bubble->>'amount')::numeric END))
          IS DISTINCT FROM v_h.cash_payout_total THEN
    RAISE EXCEPTION
      'tournament % stored cash lines differ from complete durable payout evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT round(COALESCE(sum(o.amount_paid),0),2)
    INTO v_cash_obligation_total
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND o.kind IN ('place','bubble_protection','final_table_deal');
  IF v_cash_obligation_total IS DISTINCT FROM v_h.prize_pool
     OR EXISTS (
       SELECT 1 FROM public.tournament_obligations o
        WHERE o.tournament_id = p_tournament_id
          AND (o.amount_owed IS NULL OR o.amount_paid IS NULL
            OR o.amount_owed::text IN ('NaN','Infinity','-Infinity')
            OR o.amount_paid::text IN ('NaN','Infinity','-Infinity')
            OR o.amount_owed < 0 OR o.amount_paid < 0
            OR o.amount_owed IS DISTINCT FROM round(o.amount_owed,2)
            OR o.amount_paid IS DISTINCT FROM round(o.amount_paid,2)
            OR o.amount_paid IS DISTINCT FROM o.amount_owed
            OR o.settled_at IS NULL)) THEN
    RAISE EXCEPTION 'tournament % has incomplete or malformed obligations',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT round(COALESCE(sum(w.amount),0),2)
    INTO v_bounty_total
    FROM public.wallet_transactions w
   WHERE w.related_entity_id = p_tournament_id AND lower(w.category) = 'bounty';
  IF v_bounty_total IS DISTINCT FROM v_h.bounty_payout_total
     OR v_bounty_total IS DISTINCT FROM v_h.bounty_pool
     OR EXISTS (
       SELECT 1 FROM public.wallet_transactions w
        WHERE w.related_entity_id = p_tournament_id
          AND lower(w.category) = 'bounty'
          AND (lower(w.type) <> 'credit' OR w.amount <= 0
            OR w.amount::text IN ('NaN','Infinity','-Infinity')
            OR w.amount IS DISTINCT FROM round(w.amount,2)))
     OR COALESCE(v_t.bounty_pool_paid,0) IS DISTINCT FROM v_h.bounty_pool
     OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND COALESCE(tp.current_bounty,0) <> 0) THEN
    RAISE EXCEPTION 'tournament % bounty pool is underfunded, overfunded or still open',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_h.bounty_pool > 0 THEN
    IF NOT (COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
            OR COALESCE(v_t.is_mystery_bounty,false))
       OR COALESCE((v_h.bounty_receipt->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_h.bounty_receipt->>'funded')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'tournament % bounty receipt is not a funded close',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  ELSIF COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
        OR COALESCE(v_t.is_mystery_bounty,false)
        OR EXISTS (SELECT 1 FROM public.tournament_obligations o
                    WHERE o.tournament_id = p_tournament_id
                      AND o.kind IN ('bounty','bounty_residual','mystery_bounty'))
        OR EXISTS (SELECT 1 FROM public.tournament_bounty_chests c
                    WHERE c.tournament_id = p_tournament_id)
        OR EXISTS (SELECT 1 FROM public.tournament_bounty_awards a
                    WHERE a.tournament_id = p_tournament_id) THEN
    RAISE EXCEPTION 'ordinary tournament % carries unfunded bounty state',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_h.mystery_was_active THEN
    v_mystery_evidence :=
      public.fn_ca_mystery_bounty_completion_evidence(
        p_tournament_id,v_h.winner_id);
    IF COALESCE(v_t.is_mystery_bounty,false) IS NOT TRUE
       OR v_t.mystery_bounty_stage IS DISTINCT FROM 'complete'
       OR COALESCE(v_t.mystery_bounty_pool_cents,0)
            IS DISTINCT FROM v_h.mystery_pool_cents
       OR COALESCE((v_h.mystery_receipt->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_h.mystery_receipt->>'balanced')::boolean,false) IS NOT TRUE
       OR COALESCE((v_h.mystery_receipt->>'pool_cents')::bigint,-1)
            IS DISTINCT FROM v_h.mystery_pool_cents
       OR COALESCE((v_h.mystery_receipt->>'settled_cents')::bigint,-1)
            IS DISTINCT FROM v_h.mystery_pool_cents
       OR (SELECT COALESCE(sum(c.amount_cents),0)
             FROM public.tournament_bounty_chests c
            WHERE c.tournament_id = p_tournament_id)
            IS DISTINCT FROM v_h.mystery_pool_cents
       OR v_h.mystery_receipt->'payment_evidence'
            IS DISTINCT FROM v_mystery_evidence
       OR COALESCE((v_h.mystery_receipt->>'residual_paid_cents')::bigint,-1)
            IS DISTINCT FROM
              COALESCE((v_mystery_evidence->>'void_chest_cents')::bigint,0)
       OR EXISTS (SELECT 1 FROM public.tournament_bounty_chests c
                   WHERE c.tournament_id = p_tournament_id
                     AND c.status NOT IN ('paid','void'))
       OR EXISTS (SELECT 1 FROM public.tournament_bounty_awards a
                   WHERE a.tournament_id = p_tournament_id
                     AND a.status NOT IN ('completed','void'))
       OR EXISTS (
         SELECT 1 FROM public.tournament_bounty_awards a
          WHERE a.tournament_id = p_tournament_id
            AND ((a.status = 'completed' AND (
                  a.paid_at IS NULL OR
                  (SELECT COALESCE(sum(r.amount_cents),0)
                     FROM public.tournament_bounty_award_recipients r
                    WHERE r.award_id = a.id) <> a.amount_cents OR
                  EXISTS (SELECT 1
                            FROM public.tournament_bounty_award_recipients r
                           WHERE r.award_id = a.id
                             AND r.amount_cents > 0 AND r.paid_at IS NULL)))
              OR (a.status = 'void' AND EXISTS (
                  SELECT 1 FROM public.tournament_bounty_award_recipients r
                   WHERE r.award_id = a.id AND r.paid_at IS NOT NULL)))) THEN
      RAISE EXCEPTION 'tournament % has open or inconsistent mystery bounty evidence',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  ELSE
    IF v_h.mystery_pool_cents <> 0
       OR COALESCE(v_h.mystery_receipt->>'reason','')
            NOT IN ('never_activated','not_a_mystery_tournament')
       OR EXISTS (SELECT 1 FROM public.tournament_bounty_chests c
                   WHERE c.tournament_id = p_tournament_id)
       OR EXISTS (SELECT 1 FROM public.tournament_bounty_awards a
                   WHERE a.tournament_id = p_tournament_id) THEN
      RAISE EXCEPTION 'tournament % stored an invalid non-active mystery close',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  END IF;

  SELECT * INTO v_e FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id;
  IF v_e.tournament_id IS NULL
     OR v_e.prize_balance IS DISTINCT FROM 0::numeric
     OR v_e.bounty_balance IS DISTINCT FROM 0::numeric
     OR v_e.fee_balance IS DISTINCT FROM 0::numeric
     OR v_e.closed_at IS DISTINCT FROM v_h.escrow_closed_at
     OR v_e.close_note IS DISTINCT FROM v_h.escrow_close_note THEN
    RAISE EXCEPTION 'tournament % escrow is not an exact durable zero close',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT round(COALESCE(sum(rr.rake_amount),0),2) INTO v_rake_total
    FROM public.rake_records rr
   WHERE rr.tournament_id = p_tournament_id AND rr.is_tournament;
  SELECT rs.* INTO v_r FROM public.tournament_rake_settlements rs
   WHERE rs.tournament_id = p_tournament_id;
  IF v_r.tournament_id IS NULL
     OR v_r.amount IS DISTINCT FROM v_rake_total
     OR v_r.amount IS DISTINCT FROM v_h.rake_amount
     OR v_r.destination IS DISTINCT FROM v_h.rake_destination
     OR v_r.settled_at IS DISTINCT FROM v_h.rake_settled_at
     OR v_r.attributed_at IS DISTINCT FROM v_h.rake_attributed_at
     OR v_r.attributed_users IS DISTINCT FROM v_h.rake_attributed_users
     OR v_r.attributed_users IS NULL OR v_r.attributed_users < 0
     OR v_r.attribution_error IS NOT NULL
     OR lower(v_r.destination) IN ('pending','')
     OR (v_r.amount > 0 AND v_t.club_id IS NOT NULL
         AND (v_r.attributed_users < 1
           OR v_r.destination NOT LIKE 'union:%'
              AND v_r.destination NOT LIKE 'club_treasury:%')) THEN
    RAISE EXCEPTION 'tournament % rake is not durably and successfully attributed',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  v_bubble := CASE WHEN v_h.cash_receipt ? 'bubble_protection'
                    THEN v_h.cash_receipt->'bubble_protection'
                   ELSE 'null'::jsonb END;

  RETURN jsonb_build_object(
    'ok',true,
    'fully_settled',true,
    'status','COMPLETED',
    'tournament_id',v_h.tournament_id,
    'winner_id',v_h.winner_id,
    'mode',v_h.settlement_mode,
    'settlement_mode',v_h.settlement_mode,
    'payouts',v_h.cash_receipt->'payouts',
    'deal_shares',v_h.cash_receipt->'deal_shares',
    'winner_amount',(v_h.cash_receipt->>'winner_amount')::numeric,
    'bubble_protection',v_bubble,
    'cash',v_h.cash_receipt,
    'mystery_bounty',v_h.mystery_receipt,
    'bounty',v_h.bounty_receipt,
    'closed_table_count',v_h.closed_table_count,
    'source_seat_count',v_h.source_seat_count,
    'released_seat_count',v_h.released_seat_count,
    'table_closure',jsonb_build_object(
      'closed_table_count',v_h.closed_table_count,
      'closed_table_ids',to_jsonb(v_h.closed_table_ids),
      'source_seat_count',v_h.source_seat_count,
      'source_seat_ids',to_jsonb(v_h.source_seat_ids),
      'released_seat_count',v_h.released_seat_count,
      'released_seat_ids',to_jsonb(v_h.released_seat_ids)),
    'rake',jsonb_build_object(
      'amount',v_h.rake_amount,
      'destination',v_h.rake_destination,
      'attributed',true,
      'attributed_users',v_h.rake_attributed_users,
      'settled_at',v_h.rake_settled_at,
      'attributed_at',v_h.rake_attributed_at),
    'escrow',jsonb_build_object(
      'prize_balance',v_e.prize_balance,
      'bounty_balance',v_e.bounty_balance,
      'fee_balance',v_e.fee_balance,
      'closed_at',v_h.escrow_closed_at,
      'close_note',v_h.escrow_close_note),
    'cash_payout_total',v_h.cash_payout_total,
    'bounty_payout_total',v_h.bounty_payout_total,
    'receipt_version',v_h.receipt_version,
    'settled_at',v_h.settled_at);
END;
$$;


ALTER FUNCTION public.fn_ca_tournament_terminal_receipt(p_tournament_id uuid, p_observed_winner_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_tournament_terminal_receipt(p_tournament_id uuid, p_observed_winner_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_tournament_terminal_receipt(p_tournament_id uuid, p_observed_winner_id uuid) IS 'Owner-only STABLE verifier for an immutable terminal receipt. It reads exact cash, bounty, escrow, rake, table, seat and lifecycle evidence and moves no money.';


--
-- Name: fn_ca_tournament_underpaid_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_underpaid_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT count(*)::int
    FROM public.fn_ca_tournament_settlement_mismatch('48 hours'::interval)
   WHERE kind = 'underpaid';
$$;


ALTER FUNCTION public.fn_ca_tournament_underpaid_count() OWNER TO postgres;

--
-- Name: fn_ca_tournament_unregistration_receipt(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_unregistration_receipt(p_tournament_id uuid, p_user_id uuid, p_source_table_id uuid DEFAULT NULL::uuid, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_r public.tournament_unregistration_receipts%ROWTYPE;
  v_entitlement_count integer;
  v_entitlement_total numeric;
  v_source_count integer;
  v_wallet_count integer;
  v_wallet_total numeric;
  v_ticket_count integer;
  v_ticket_total numeric;
  v_ticket_ledger_count integer;
  v_ticket_transaction_count integer;
BEGIN
  SELECT * INTO v_r
    FROM public.tournament_unregistration_receipts r
   WHERE r.tournament_id=p_tournament_id AND r.user_id=p_user_id
     AND r.source_table_id IS NOT DISTINCT FROM p_source_table_id
     AND (p_request_id IS NULL OR r.request_id=p_request_id)
   ORDER BY r.settled_at DESC,r.registration_id DESC
   LIMIT 1;
  IF v_r.registration_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- A later registration, including an eliminated one, makes an unkeyed
  -- "latest receipt" unsafe. The exact request-key path is also refused while
  -- any later registration row exists: a replay is an outcome read, never an
  -- operation against a new lifecycle.
  IF EXISTS(
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id=v_r.tournament_id AND tp.user_id=v_r.user_id) THEN
    RETURN NULL;
  END IF;

  SELECT count(*),round(COALESCE(sum(e.gross),0),2)
    INTO v_entitlement_count,v_entitlement_total
    FROM public.tournament_refund_entitlements e
   WHERE e.id=ANY(v_r.entitlement_ids)
     AND e.tournament_id=v_r.tournament_id AND e.user_id=v_r.user_id;
  SELECT count(*) INTO v_source_count
    FROM unnest(v_r.entitlement_ids) WITH ORDINALITY entitlement(id,n)
    JOIN unnest(v_r.source_wallet_club_ids) WITH ORDINALITY source(club_id,n)
      USING(n)
    JOIN public.tournament_refund_entitlements e
      ON e.id=entitlement.id AND e.refund_wallet_club_id=source.club_id
     AND e.tournament_id=v_r.tournament_id AND e.user_id=v_r.user_id;
  SELECT count(*),round(COALESCE(sum(tr.amount_paid_now),0),2)
    INTO v_wallet_count,v_wallet_total
    FROM public.tournament_refund_tranches tr
    JOIN public.tournament_refund_entitlements e ON e.id=tr.entitlement_id
   WHERE e.id=ANY(v_r.entitlement_ids)
     AND e.entitlement_kind='wallet_charge'
     AND tr.wallet_transaction_id=ANY(v_r.wallet_transaction_ids)
     AND tr.credit_ledger_id=ANY(v_r.credit_ledger_ids)
     AND tr.tournament_id=v_r.tournament_id AND tr.user_id=v_r.user_id;
  SELECT count(*),round(COALESCE(sum(tk.value),0),2)
    INTO v_ticket_count,v_ticket_total
    FROM public.tournament_tickets tk
    JOIN public.tournament_refund_entitlements e
      ON e.id=tk.source_refund_entitlement_id
   WHERE tk.id=ANY(v_r.ticket_ids)
     AND tk.redemption_mode='tournament_entry_only'
     AND e.id=ANY(v_r.entitlement_ids)
     AND e.entitlement_kind IN ('satellite_seat','tournament_ticket')
     AND e.tournament_id=v_r.tournament_id AND e.user_id=v_r.user_id
     AND tk.value=e.gross;
  SELECT count(*) INTO v_ticket_ledger_count
    FROM public.chip_ledger l
    JOIN public.tournament_tickets tk ON tk.id=l.to_entity_id
    JOIN public.tournament_refund_entitlements e
      ON e.id=tk.source_refund_entitlement_id
   WHERE tk.id=ANY(v_r.ticket_ids)
     AND e.id=ANY(v_r.entitlement_ids)
     AND l.idempotency_key='tourney:'||e.tournament_id::text
          ||':satellite-ticket-return:'||e.id::text
     AND l.from_type='prize_liability'
     AND l.from_entity_id=e.tournament_id
     AND l.to_type='escrow' AND l.to_entity_id=tk.id
     AND l.club_id=e.refund_wallet_club_id AND l.amount=e.gross;
  SELECT count(*) INTO v_ticket_transaction_count
    FROM public.chip_transactions ct
    JOIN public.tournament_tickets tk
      ON tk.id::text=ct.metadata->>'ticket_id'
    JOIN public.tournament_refund_entitlements e
      ON e.id=tk.source_refund_entitlement_id
    JOIN public.chip_ledger l
      ON l.id::text=ct.metadata->>'ledger_id'
   WHERE tk.id=ANY(v_r.ticket_ids)
     AND e.id=ANY(v_r.entitlement_ids)
     AND ct.transaction_type='tournament_ticket_issue'
     AND ct.club_id=e.refund_wallet_club_id
     AND ct.from_user_id IS NULL AND ct.to_user_id=e.user_id
     AND ct.amount=e.gross
     AND ct.metadata->>'entitlement_id'=e.id::text
     AND l.to_entity_id=tk.id
     AND l.idempotency_key='tourney:'||e.tournament_id::text
          ||':satellite-ticket-return:'||e.id::text;

  IF v_r.settled_at>=v_r.scheduled_start_at
     OR v_entitlement_count<>cardinality(v_r.entitlement_ids)
     OR v_source_count<>cardinality(v_r.entitlement_ids)
     OR v_entitlement_total IS DISTINCT FROM
          round(v_r.refunded_chips+v_r.returned_ticket_value,2)
     OR v_wallet_count<>cardinality(v_r.wallet_transaction_ids)
     OR v_wallet_total IS DISTINCT FROM v_r.refunded_chips
     OR v_ticket_count<>cardinality(v_r.ticket_ids)
     OR v_ticket_total IS DISTINCT FROM v_r.returned_ticket_value
     OR v_ticket_ledger_count<>cardinality(v_r.ticket_ids)
     OR v_ticket_transaction_count<>cardinality(v_r.ticket_ids)
     OR (v_r.source_table_id IS NOT NULL AND NOT EXISTS(
       SELECT 1 FROM public.tables tb
        WHERE tb.id=v_r.source_table_id
          AND tb.tournament_id=v_r.tournament_id)) THEN
    RAISE EXCEPTION 'tournament unregistration receipt % is not exact',
      v_r.registration_id USING ERRCODE='P0404';
  END IF;

  RETURN jsonb_build_object(
    'ok',true,'request_id',v_r.request_id,
    'registration_id',v_r.registration_id,
    'refunded_chips',v_r.refunded_chips,
    'returned_ticket_value',v_r.returned_ticket_value,
    'wallet_chips_from_satellite_entitlements',0,
    'entitlement_ids',to_jsonb(v_r.entitlement_ids),
    'ticket_ids',to_jsonb(v_r.ticket_ids),
    'source_wallet_club_ids',to_jsonb(v_r.source_wallet_club_ids),
    'credit_ledger_ids',to_jsonb(v_r.credit_ledger_ids),
    'wallet_transaction_ids',to_jsonb(v_r.wallet_transaction_ids),
    'seat_number',v_r.seat_number,'seats_taken',v_r.seats_taken,
    'scheduled_start_at',v_r.scheduled_start_at,
    'settled_at',v_r.settled_at);
END;
$$;


ALTER FUNCTION public.fn_ca_tournament_unregistration_receipt(p_tournament_id uuid, p_user_id uuid, p_source_table_id uuid, p_request_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_trial_balance(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_trial_balance(p_since timestamp with time zone DEFAULT (now() - '01:15:00'::interval)) RETURNS TABLE(account text, balance_delta numeric, ledger_net numeric, difference numeric, writers text, window_start timestamp with time zone, window_end timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s0 public.ca_supply_snapshots%ROWTYPE;
  s1 public.ca_supply_snapshots%ROWTYPE;
  v_outside text[] := public.fn_ca_noncirculating_chip_stores();
BEGIN
  SELECT * INTO s0 FROM public.ca_supply_snapshots
   WHERE taken_at >= COALESCE(p_since, now() - interval '75 minutes')
   ORDER BY taken_at ASC LIMIT 1;
  SELECT * INTO s1 FROM public.ca_supply_snapshots ORDER BY taken_at DESC LIMIT 1;

  -- No window (no snapshot at/after p_since, or it IS the latest): report the
  -- chart with NULL deltas rather than a zero that reads as "reconciled".
  IF s0.id IS NULL OR s1.id IS NULL OR s0.id = s1.id THEN
    RETURN QUERY
      SELECT a.account, NULL::numeric, NULL::numeric, NULL::numeric, NULL::text,
             s0.taken_at, s1.taken_at
        FROM (VALUES ('player_wallets'), ('promo_wallets'), ('table_stack'),
                     ('tournament_liability'), ('bbj_pools'), ('spin_reserve'),
                     ('club_treasuries'), ('club_chip_pools'), ('union_banks'),
                     ('agent_wallets'), ('club_wallets'), ('leaderboard_liability'),
                     ('settlement_suspense'), ('total_supply')) AS a(account);
    RETURN;
  END IF;

  RETURN QUERY
  WITH acct(account, ledger_types, bal_delta) AS (
    VALUES
      ('player_wallets',        ARRAY['player_wallet'],                                  s1.member_wallets        - s0.member_wallets),
      /* CHIP STANDARD (2026-09-03): the promo_wallet ledger account is written
         from THREE balances - club_members.promo_balance, clubs.promo_balance
         and agents.promo_wallet_balance (see trg_ca_autoledger). Measuring it
         as member promo alone reported a -5,955.77 phantom over seven days.
         Snapshots taken before this change carry NULL in the two new columns;
         COALESCE keeps the old basis for those windows rather than inventing a
         delta out of a NULL. */
      ('promo_wallets',         ARRAY['promo_wallet'],
                                (s1.member_promo + COALESCE(s1.club_promo, 0) + COALESCE(s1.agent_promo, 0))
                              - (s0.member_promo + COALESCE(s0.club_promo, 0) + COALESCE(s0.agent_promo, 0))),
      ('table_stack',           ARRAY['table_stack'],                                    s1.felt                  - s0.felt),
      ('tournament_liability',  ARRAY['prize_liability','bounty_liability','refund_payable'],
                                                                                         s1.tournament_liability  - s0.tournament_liability),
      ('bbj_pools',             ARRAY['bbj_pool'],                                       s1.bbj_pools             - s0.bbj_pools),
      ('spin_reserve',          ARRAY['spin_reserve'],                                   s1.spin_pools            - s0.spin_pools),
      ('club_treasuries',       ARRAY['club_treasury'],                                  s1.treasuries            - s0.treasuries),
      ('club_chip_pools',       ARRAY[]::text[],                                         s1.chip_pools            - s0.chip_pools),
      /* insurance_bank is written from clubs.insurance_balance as well as the
         union's insurance_wallet, so both back this account. */
      ('union_banks',           ARRAY['union_bank','union_wallet','insurance_bank'],
                                (s1.union_wallets + COALESCE(s1.club_insurance, 0))
                              - (s0.union_wallets + COALESCE(s0.club_insurance, 0))),
      /* agent promo is journalled as promo_wallet, so it belongs to the promo
         account above and not to this one. */
      ('agent_wallets',         ARRAY['agent_wallet'],
                                (s1.agent_wallets - COALESCE(s1.agent_promo, 0))
                              - (s0.agent_wallets - COALESCE(s0.agent_promo, 0))),
      ('club_wallets',          ARRAY['club_wallet'],                                    s1.club_wallets          - s0.club_wallets),
      ('leaderboard_liability', ARRAY['opening_setup','leaderboard_round'],              s1.leaderboard_liability - s0.leaderboard_liability),
      ('settlement_suspense',   ARRAY['settlement_suspense'],                            0::numeric)
  ),
  led AS (
    SELECT l.from_type, l.to_type, l.amount,
           COALESCE(l.actor_service, '?') || '/' || COALESCE(l.db_role, '?') AS writer
      FROM public.chip_ledger l
     WHERE l.created_at >  s0.taken_at
       AND l.created_at <= s1.taken_at
       AND NOT (l.category = 'correction'
                AND l.metadata ->> 'posted_via' = 'fn_ca_post_correction')
  ),
  per_acct AS (
    SELECT a.account, a.bal_delta,
           COALESCE((SELECT sum(led.amount) FROM led WHERE led.to_type   = ANY (a.ledger_types)), 0)
         - COALESCE((SELECT sum(led.amount) FROM led WHERE led.from_type = ANY (a.ledger_types)), 0) AS net,
           (SELECT string_agg(w.writer || ':' || w.n::text, ', ' ORDER BY w.n DESC)
              FROM (SELECT led.writer, count(*) AS n
                      FROM led
                     WHERE led.to_type = ANY (a.ledger_types) OR led.from_type = ANY (a.ledger_types)
                     GROUP BY led.writer
                     ORDER BY count(*) DESC
                     LIMIT 5) w) AS writers
      FROM acct a
  ),
  issuance AS (
    SELECT COALESCE(sum(led.amount) FILTER (WHERE led.from_type = ANY (v_outside)), 0)
         - COALESCE(sum(led.amount) FILTER (WHERE led.to_type   = ANY (v_outside)), 0) AS net,
           (SELECT string_agg(w.writer || ':' || w.n::text, ', ' ORDER BY w.n DESC)
              FROM (SELECT l2.writer, count(*) AS n FROM led l2
                     WHERE l2.from_type = ANY (v_outside) OR l2.to_type = ANY (v_outside)
                     GROUP BY l2.writer ORDER BY count(*) DESC LIMIT 5) w) AS writers
      FROM led
  ),
  total_bal AS (
    -- ISSUED is the sum of the accounts (standard 1.2), never a stored column.
    SELECT sum(a.bal_delta) AS d FROM acct a
  )
  SELECT p.account,
         round(p.bal_delta, 2),
         round(p.net, 2),
         round(p.bal_delta - p.net, 2),
         p.writers,
         s0.taken_at, s1.taken_at
    FROM per_acct p
  UNION ALL
  SELECT 'total_supply',
         round(t.d, 2),
         round(i.net, 2),
         round(t.d - i.net, 2),
         i.writers,
         s0.taken_at, s1.taken_at
    FROM issuance i, total_bal t
  ORDER BY 1;
END
$$;


ALTER FUNCTION public.fn_ca_trial_balance(p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_ca_trial_balance_watch(timestamp with time zone, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_trial_balance_watch(p_since timestamp with time zone DEFAULT (now() - '01:15:00'::interval), p_threshold numeric DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r       record;
  v_filed integer := 0;
  v_id    uuid;
BEGIN
  FOR r IN
    SELECT * FROM public.fn_ca_trial_balance(p_since)
     WHERE account <> 'total_supply'
       AND difference IS NOT NULL
       AND abs(difference) > COALESCE(p_threshold, 100)
  LOOP
    v_id := public.fn_ca_raise_drift_incident(
      'fn_ca_trial_balance_watch', 'ledger_imbalance', 'info',
      'tb:' || r.account || ':' || to_char(r.window_end AT TIME ZONE 'UTC', 'YYYY-MM-DD'),
      r.difference, r.ledger_net, r.balance_delta,
      'ledger', 'account', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      format('trial balance: %s moved %s in its balance column but %s in the ledger between %s and %s; writers %s',
             r.account, r.balance_delta, r.ledger_net,
             to_char(r.window_start AT TIME ZONE 'UTC', 'HH24:MI'),
             to_char(r.window_end   AT TIME ZONE 'UTC', 'HH24:MI'),
             COALESCE(r.writers, '(no ledger rows)')),
      false,
      jsonb_build_object('account', r.account, 'balance_delta', r.balance_delta,
                         'ledger_net', r.ledger_net, 'difference', r.difference,
                         'writers', r.writers, 'window_start', r.window_start,
                         'window_end', r.window_end));
    IF v_id IS NOT NULL THEN
      v_filed := v_filed + 1;
    END IF;
  END LOOP;
  RETURN v_filed;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_ca_trial_balance_watch failed: %', SQLERRM;
  RETURN -1;
END $$;


ALTER FUNCTION public.fn_ca_trial_balance_watch(p_since timestamp with time zone, p_threshold numeric) OWNER TO postgres;

--
-- Name: fn_ca_unacknowledged_supply_breaches(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_unacknowledged_supply_breaches(p_threshold numeric DEFAULT 5000) RETURNS TABLE(snapshot_id bigint, taken_at timestamp with time zone, unexplained numeric, total numeric, age_hours numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select s.id,
         s.taken_at,
         round(s.unexplained, 2),
         round(s.total, 2),
         round(extract(epoch from (now() - s.taken_at)) / 3600.0, 1)
    from ca_supply_snapshots s
    left join ca_supply_breach_ack a on a.snapshot_id = s.id
   where s.unexplained is not null
     and abs(s.unexplained) > p_threshold
     and a.snapshot_id is null
   order by s.taken_at desc;
$$;


ALTER FUNCTION public.fn_ca_unacknowledged_supply_breaches(p_threshold numeric) OWNER TO postgres;

--
-- Name: fn_ca_undeclared_money_paths(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_undeclared_money_paths() RETURNS TABLE(proname text, tbl text, col text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH watched AS (
    SELECT c.relname::text AS tbl,
           (regexp_matches(pg_get_triggerdef(t.oid), '''([a-z_]+)=([a-z_]+)''', 'g'))[1] AS col
      FROM pg_trigger t
      JOIN pg_class c ON c.oid = t.tgrelid
      JOIN pg_proc  p ON p.oid = t.tgfoid
     WHERE NOT t.tgisinternal AND p.proname = 'fn_ca_autoledger'
  ), fns AS (
    SELECT p.proname::text AS proname, p.prosrc,
           (p.prosrc ILIKE '%fn_ca_declare_ledger%'
            OR p.prosrc ILIKE '%app.ledger_counterparty%') AS declares
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public' AND p.prokind = 'f'
  )
  SELECT DISTINCT f.proname, w.tbl, w.col
    FROM fns f
    JOIN watched w
      ON f.prosrc ~* ('UPDATE\s+(public\.)?' || w.tbl || '\y')
     AND f.prosrc ~* ('\y' || w.col || '\y')
   WHERE NOT f.declares
     AND f.proname NOT IN ('fn_ca_autoledger', 'fn_ca_autoledger_delete',
                           'fn_ca_declare_ledger', 'fn_ca_undeclared_money_paths')
   ORDER BY 1, 2, 3
$$;


ALTER FUNCTION public.fn_ca_undeclared_money_paths() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_undeclared_money_paths(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_undeclared_money_paths() IS 'Functions that move a balance fn_ca_autoledger watches without declaring the other side, so their movements land on settlement_suspense. This is the unclassified-flow backlog. 172 function-column pairs across 81 functions when first measured on 2026-09-01; the number must only ever go down.';


--
-- Name: fn_ca_union_wallet_ledger_shape(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_union_wallet_ledger_shape(p_tx_type text) RETURNS TABLE(category text, counterparty text)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT m.cat, m.cp FROM (VALUES
    ('rake',                  'rake',     'table_stack'),
    ('bbj_promo_sweep',       'promo',    'bbj_pool'),
    ('guarantee_overlay',     'overlay',  'prize_liability'),
    ('tournament_fee_refund', 'reversal', 'prize_liability')
  ) AS m(tx, cat, cp)
  WHERE m.tx = lower(coalesce(p_tx_type,''))
$$;


ALTER FUNCTION public.fn_ca_union_wallet_ledger_shape(p_tx_type text) OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_union_wallet_ledger_shape(p_tx_type text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_union_wallet_ledger_shape(p_tx_type text) IS 'Maps a union_wallet_transactions.tx_type to the ledger category and counterparty the movement should be booked against. Returns no row for an unrecognised type, which leaves fn_ca_autoledger on its settlement_suspense default - unclassified on purpose rather than guessed.';


--
-- Name: fn_ca_unledgered_insert_paths(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_unledgered_insert_paths() RETURNS TABLE(table_name text, ledgers_delete boolean, ledgers_insert boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.relname::text,
         bool_or(p.proname = 'fn_ca_autoledger_delete'),
         bool_or(p.proname IN ('fn_ca_autoledger', 'fn_club_members_ledger_writer')
                 AND (t.tgtype & 4) = 4)
    FROM pg_trigger t
    JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_proc  p ON p.oid = t.tgfoid
    JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE NOT t.tgisinternal
     AND n.nspname = 'public'
     AND p.proname IN ('fn_ca_autoledger', 'fn_ca_autoledger_delete',
                       'fn_club_members_ledger_writer')
   GROUP BY c.relname
  HAVING bool_or(p.proname = 'fn_ca_autoledger_delete')
     AND NOT bool_or(p.proname IN ('fn_ca_autoledger', 'fn_club_members_ledger_writer')
                     AND (t.tgtype & 4) = 4);
$$;


ALTER FUNCTION public.fn_ca_unledgered_insert_paths() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_unledgered_insert_paths(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_unledgered_insert_paths() IS 'Balance-bearing tables that ledger a DELETE but not an INSERT - i.e. rows that can be born holding chips with nothing recorded. Must return zero rows. Added 2026-09-01 after the Deep Stack quarantine restore minted 4,159,644.00 chips through club_members INSERT with no ledger entry.';


--
-- Name: fn_ca_unregister_tournament_player_exact(uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_unregister_tournament_player_exact(p_tournament_id uuid, p_user_id uuid, p_expected_table_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_token uuid;
  v_result jsonb;
  v_live_seats integer;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  SELECT count(*) INTO v_live_seats
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_user_id AND s.left_at IS NULL;
  IF v_live_seats>1 THEN
    RAISE EXCEPTION
      'tournament player % has % live seats; exact unregistration refuses ambiguous chips',
      p_user_id,v_live_seats USING ERRCODE='P0404';
  END IF;
  v_token:=public.fn_ca_open_tournament_seat_exit_authority(
    p_tournament_id,'unregister',p_user_id);
  BEGIN
    v_result:=public.fn_ca_unregister_tournament_player_exact_pre_seat_guard(
      p_tournament_id,p_user_id,p_expected_table_id,p_description,p_request_id);
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(
      v_token,COALESCE((v_result->>'ok')::boolean,false));
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
    RAISE;
  END;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_ca_unregister_tournament_player_exact(p_tournament_id uuid, p_user_id uuid, p_expected_table_id uuid, p_description text, p_request_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_unregister_tournament_player_exact_pre_seat_guard(uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_unregister_tournament_player_exact_pre_seat_guard(p_tournament_id uuid, p_user_id uuid, p_expected_table_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_reg public.tournament_players%ROWTYPE;
  v_ent record;
  v_fee_group record;
  v_settle jsonb;
  v_ticket jsonb;
  v_receipt jsonb;
  v_escrow_before public.tournament_escrow%ROWTYPE;
  v_escrow_after public.tournament_escrow%ROWTYPE;
  v_players_before integer;
  v_rows integer;
  v_seat_number integer;
  v_seats_taken integer;
  v_non_cash_count integer;
  v_wallet_debits numeric:=0;
  v_wallet_refunds_before numeric:=0;
  v_wallet_refunds_after numeric:=0;
  v_entitled_wallet_total numeric:=0;
  v_tranche_total numeric:=0;
  v_refund_prize numeric:=0;
  v_refund_bounty numeric:=0;
  v_refund_fee numeric:=0;
  v_refund_total numeric:=0;
  v_wallet_amount numeric:=0;
  v_ticket_amount numeric:=0;
  v_running_owed numeric:=0;
  v_rake_before numeric:=0;
  v_rake_after numeric:=0;
  v_entitlement_ids uuid[]:='{}'::uuid[];
  v_ticket_ids uuid[]:='{}'::uuid[];
  v_credit_ledger_ids uuid[]:='{}'::uuid[];
  v_wallet_transaction_ids uuid[]:='{}'::uuid[];
  v_source_wallet_club_ids uuid[]:='{}'::uuid[];
  v_request_id uuid:=COALESCE(p_request_id,gen_random_uuid());
  v_unregistered_at timestamptz;
  v_description text:=COALESCE(
    NULLIF(btrim(p_description),''),'Tournament unregistration refund');
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'tournament and player ids are required'
      USING ERRCODE='22004';
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF v_t.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;

  -- A caller-supplied request id is a durable operation identity. It may only
  -- name this exact player/event/endpoint scope. If its pre-start outcome is
  -- already committed, replay that immutable outcome even when the wall clock
  -- is now past the start; this branch performs no new unregistration writes.
  IF p_request_id IS NOT NULL THEN
    IF EXISTS(
      SELECT 1 FROM public.tournament_unregistration_receipts r
       WHERE r.request_id=p_request_id
         AND (r.tournament_id IS DISTINCT FROM p_tournament_id
           OR r.user_id IS DISTINCT FROM p_user_id
           OR r.source_table_id IS DISTINCT FROM p_expected_table_id)) THEN
      RAISE EXCEPTION 'unregistration request id belongs to another intent'
        USING ERRCODE='22023';
    END IF;
    IF EXISTS(
      SELECT 1 FROM public.tournament_unregistration_receipts r
       WHERE r.request_id=p_request_id) THEN
      v_receipt:=public.fn_ca_tournament_unregistration_receipt(
        p_tournament_id,p_user_id,p_expected_table_id,p_request_id);
      IF v_receipt IS NOT NULL THEN
        RETURN v_receipt||jsonb_build_object('replayed',true);
      END IF;
      RAISE EXCEPTION
        'unregistration request id belongs to a prior registration lifecycle'
        USING ERRCODE='P0404';
    END IF;
  END IF;

  SELECT * INTO v_reg FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
     AND tp.status::text IN ('registered','playing')
   ORDER BY tp.id LIMIT 1 FOR UPDATE;
  IF upper(COALESCE(v_t.status::text,'')) NOT IN ('ANNOUNCED','REGISTERING') THEN
    RETURN jsonb_build_object('ok',false,'reason','registration_closed');
  END IF;
  IF v_t.start_time IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','registration_schedule_unset');
  END IF;
  IF clock_timestamp()>=v_t.start_time THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_started');
  END IF;
  IF v_reg.id IS NULL THEN
    -- Rolling clients without a request id may recover a just-lost response
    -- only while registration remains open. They can never turn an old receipt
    -- into a successful post-start response.
    IF p_request_id IS NULL THEN
      v_receipt:=public.fn_ca_tournament_unregistration_receipt(
        p_tournament_id,p_user_id,p_expected_table_id,NULL);
      IF v_receipt IS NOT NULL THEN
        RETURN v_receipt||jsonb_build_object('replayed',true);
      END IF;
    END IF;
    RETURN jsonb_build_object('ok',false,'reason','not_registered');
  END IF;
  IF p_expected_table_id IS NOT NULL THEN
    SELECT s.seat_number INTO v_seat_number
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE s.table_id=p_expected_table_id AND s.user_id=p_user_id
       AND s.left_at IS NULL AND tb.tournament_id=p_tournament_id
     ORDER BY s.id LIMIT 1 FOR UPDATE OF s;
    IF v_seat_number IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','not_seated');
    END IF;
  END IF;
  IF EXISTS(
    SELECT 1 FROM public.spin_reserve_ledger r
     WHERE r.tournament_id=p_tournament_id
       AND r.kind IN ('contribution','jackpot_draw')) THEN
    RETURN jsonb_build_object('ok',false,'reason','spin_entry_already_booked');
  END IF;

  PERFORM 1 FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
   ORDER BY e.entitlement_kind,e.id FOR UPDATE;
  SELECT count(*) INTO v_non_cash_count
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND e.registration_id=v_reg.id
     AND e.entitlement_kind IN ('satellite_seat','tournament_ticket')
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_tickets tk
        WHERE tk.source_refund_entitlement_id=e.id)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=e.id);
  IF COALESCE(v_reg.is_satellite_qualifier,false)
     AND v_non_cash_count<>1 THEN
    RAISE EXCEPTION
      'satellite-funded registration % requires one unspent ticket entitlement',
      v_reg.id USING ERRCODE='P0404';
  END IF;
  IF NOT COALESCE(v_reg.is_satellite_qualifier,false)
     AND v_non_cash_count<>0 THEN
    RAISE EXCEPTION
      'cash registration % cannot own a satellite ticket entitlement',v_reg.id
      USING ERRCODE='P0404';
  END IF;

  SELECT round(COALESCE(sum(e.refund_prize),0),2),
         round(COALESCE(sum(e.refund_bounty),0),2),
         round(COALESCE(sum(e.refund_fee),0),2),
         round(COALESCE(sum(e.gross),0),2),
         round(COALESCE(sum(e.gross) FILTER(
           WHERE e.entitlement_kind='wallet_charge'),0),2),
         round(COALESCE(sum(e.gross) FILTER(
           WHERE e.entitlement_kind IN ('satellite_seat','tournament_ticket')),0),2)
    INTO v_refund_prize,v_refund_bounty,v_refund_fee,v_refund_total,
         v_wallet_amount,v_ticket_amount
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND (e.entitlement_kind='wallet_charge' OR e.registration_id=v_reg.id)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=e.id)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_tickets tk
        WHERE tk.source_refund_entitlement_id=e.id);
  IF v_refund_total IS DISTINCT FROM
       round(v_refund_prize+v_refund_bounty+v_refund_fee,2)
     OR v_refund_total IS DISTINCT FROM
       round(v_wallet_amount+v_ticket_amount,2) THEN
    RAISE EXCEPTION 'registration % has invalid entitlement totals',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  -- A satellite seat, including a returned ticket that was used for a later
  -- target entry, is a noncash entry for its entire registration lifecycle.
  -- Any wallet-charge entitlement attached to that registration is corrupt;
  -- refuse the whole transaction instead of ever returning chips.
  IF COALESCE(v_reg.is_satellite_qualifier,false)
     AND (v_wallet_amount<>0 OR v_ticket_amount<=0
       OR v_refund_total IS DISTINCT FROM v_ticket_amount) THEN
    RAISE EXCEPTION
      'satellite-funded registration % can return only a tournament ticket',
      v_reg.id USING ERRCODE='P0404';
  END IF;

  SELECT round(COALESCE(sum(w.amount),0),2) INTO v_wallet_debits
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=p_user_id
     AND w.type='debit'
     AND lower(w.category) IN ('tournament_buyin','rebuy','addon');
  SELECT round(COALESCE(sum(e.gross),0),2) INTO v_entitled_wallet_total
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND e.entitlement_kind='wallet_charge';
  SELECT round(COALESCE(sum(w.amount),0),2) INTO v_wallet_refunds_before
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=p_user_id
     AND w.type='credit'
     AND lower(w.category) IN ('refund','tournament_refund');
  SELECT round(COALESCE(sum(tr.amount_paid_now),0),2) INTO v_tranche_total
    FROM public.tournament_refund_tranches tr
   WHERE tr.tournament_id=p_tournament_id AND tr.user_id=p_user_id;
  IF v_wallet_debits IS DISTINCT FROM v_entitled_wallet_total
     OR v_wallet_refunds_before IS DISTINCT FROM v_tranche_total
     OR v_wallet_refunds_before>v_wallet_debits THEN
    RAISE EXCEPTION 'registration % wallet and entitlement journals disagree',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  v_running_owed:=v_tranche_total;

  SELECT round(COALESCE(sum(r.rake_amount),0),2) INTO v_rake_before
    FROM public.rake_records r
   WHERE r.tournament_id=p_tournament_id AND r.is_tournament;
  IF round(COALESCE((SELECT sum(r.rake_amount)
       FROM public.rake_records r
      WHERE r.tournament_id=p_tournament_id AND r.is_tournament
        AND r.metadata->>'user_id'=p_user_id::text),0),2)
       IS DISTINCT FROM v_refund_fee THEN
    RAISE EXCEPTION 'registration % has no exact unmatched fee evidence',v_reg.id
      USING ERRCODE='P0404';
  END IF;

  PERFORM public.fn_ca_escrow_apply(
    p_tournament_id,'unregister entitlement escrow prelock');
  SELECT * INTO v_escrow_before FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id FOR UPDATE;
  SELECT count(*) INTO v_players_before FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.status::text IN ('registered','playing');
  IF v_escrow_before.tournament_id IS NULL
     OR v_escrow_before.enforced IS DISTINCT FROM true
     OR v_players_before<=0
     OR v_t.current_players IS DISTINCT FROM v_players_before
     OR v_t.prize_pool IS DISTINCT FROM v_escrow_before.prize_balance
     OR v_t.bounty_pool IS DISTINCT FROM v_escrow_before.bounty_balance
     OR v_t.total_rake IS DISTINCT FROM v_escrow_before.fee_balance
     OR v_t.total_rake IS DISTINCT FROM v_rake_before
     OR v_t.prize_pool<v_refund_prize
     OR v_t.bounty_pool<v_refund_bounty
     OR v_t.total_rake<v_refund_fee THEN
    RAISE EXCEPTION 'registration % cannot leave divergent tournament state',v_reg.id
      USING ERRCODE='P0404';
  END IF;

  FOR v_ent IN
    SELECT e.* FROM public.tournament_refund_entitlements e
     WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
       AND e.entitlement_kind='wallet_charge'
       AND NOT EXISTS(
         SELECT 1 FROM public.tournament_refund_tranches tr
          WHERE tr.entitlement_id=e.id)
       AND NOT EXISTS(
         SELECT 1 FROM public.tournament_tickets tk
          WHERE tk.source_refund_entitlement_id=e.id)
     ORDER BY e.id
  LOOP
    v_running_owed:=round(v_running_owed+v_ent.gross,2);
    v_settle:=public.fn_settle_tournament_refund_exact(
      p_tournament_id,p_user_id,v_ent.refund_wallet_club_id,v_running_owed,
      v_ent.refund_prize,v_ent.refund_bounty,v_ent.refund_fee,
      'fn_unregister_from_tournament',v_description);
    IF COALESCE((v_settle->>'ok')::boolean,false) IS NOT TRUE
       OR (v_settle->>'entitlement_id')::uuid IS DISTINCT FROM v_ent.id
       OR (v_settle->>'paid')::numeric IS DISTINCT FROM v_ent.gross
       OR (v_settle->>'amount_paid')::numeric IS DISTINCT FROM v_running_owed
       OR (v_settle->>'source_wallet_club_id')::uuid
            IS DISTINCT FROM v_ent.refund_wallet_club_id THEN
      RAISE EXCEPTION 'registration % exact wallet refund failed',v_reg.id
        USING ERRCODE='P0404';
    END IF;
    v_entitlement_ids:=array_append(v_entitlement_ids,v_ent.id);
    v_source_wallet_club_ids:=array_append(
      v_source_wallet_club_ids,v_ent.refund_wallet_club_id);
    v_credit_ledger_ids:=array_append(
      v_credit_ledger_ids,(v_settle->>'credit_ledger_id')::uuid);
    v_wallet_transaction_ids:=array_append(
      v_wallet_transaction_ids,(v_settle->>'wallet_transaction_id')::uuid);
  END LOOP;

  FOR v_ent IN
    SELECT e.* FROM public.tournament_refund_entitlements e
     WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
       AND e.registration_id=v_reg.id
       AND e.entitlement_kind IN ('satellite_seat','tournament_ticket')
       AND NOT EXISTS(
         SELECT 1 FROM public.tournament_refund_tranches tr
          WHERE tr.entitlement_id=e.id)
       AND NOT EXISTS(
         SELECT 1 FROM public.tournament_tickets tk
          WHERE tk.source_refund_entitlement_id=e.id)
     ORDER BY e.id
  LOOP
    v_ticket:=public.fn_ca_return_satellite_entitlement_as_ticket(
      v_ent.id,'fn_unregister_from_tournament',v_description);
    IF COALESCE((v_ticket->>'ok')::boolean,false) IS NOT TRUE
       OR (v_ticket->>'entitlement_id')::uuid IS DISTINCT FROM v_ent.id
       OR (v_ticket->>'value')::numeric IS DISTINCT FROM v_ent.gross
       OR (v_ticket->>'refund_wallet_club_id')::uuid
            IS DISTINCT FROM v_ent.refund_wallet_club_id
       OR (v_ticket->>'ticket_id') IS NULL THEN
      RAISE EXCEPTION 'registration % tournament-ticket return failed',v_reg.id
        USING ERRCODE='P0404';
    END IF;
    v_entitlement_ids:=array_append(v_entitlement_ids,v_ent.id);
    v_source_wallet_club_ids:=array_append(
      v_source_wallet_club_ids,v_ent.refund_wallet_club_id);
    v_ticket_ids:=array_append(v_ticket_ids,(v_ticket->>'ticket_id')::uuid);
  END LOOP;

  FOR v_fee_group IN
    SELECT e.refund_wallet_club_id AS club_id,
           round(sum(e.refund_fee),2) AS fee,
           array_agg(e.id ORDER BY e.id) AS entitlement_ids
      FROM public.tournament_refund_entitlements e
     WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
       AND (e.entitlement_kind='wallet_charge' OR e.registration_id=v_reg.id)
       AND e.id=ANY(v_entitlement_ids)
     GROUP BY e.refund_wallet_club_id
     ORDER BY e.refund_wallet_club_id
  LOOP
    IF v_fee_group.fee>0 THEN
      INSERT INTO public.rake_records(
        hand_id,table_id,club_id,rake_amount,pot_size,num_players,
        bbj_contribution,is_tournament,tournament_id,source,metadata)
      VALUES(
        NULL,NULL,v_fee_group.club_id,-v_fee_group.fee,v_fee_group.fee,1,
        0,true,p_tournament_id,'fn_unregister_from_tournament',
        jsonb_build_object(
          'kind','tournament_fee_refund','user_id',p_user_id,
          'registration_id',v_reg.id,
          'source_wallet_club_id',v_fee_group.club_id,
          'entitlement_ids',to_jsonb(v_fee_group.entitlement_ids)));
    END IF;
  END LOOP;

  UPDATE public.tournaments
     SET current_players=v_players_before-1,
         prize_pool=round(v_t.prize_pool-v_refund_prize,2),
         bounty_pool=round(v_t.bounty_pool-v_refund_bounty,2),
         total_rake=round(v_t.total_rake-v_refund_fee,2),updated_at=now()
   WHERE id=p_tournament_id
     AND current_players IS NOT DISTINCT FROM v_players_before
     AND prize_pool IS NOT DISTINCT FROM v_t.prize_pool
     AND bounty_pool IS NOT DISTINCT FROM v_t.bounty_pool
     AND total_rake IS NOT DISTINCT FROM v_t.total_rake;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'registration % tournament cache changed',v_reg.id
      USING ERRCODE='40001';
  END IF;

  UPDATE public.table_seats s
     SET left_at=transaction_timestamp(),status='left',leave_pending=false,
         is_sitting_out=false,is_away=false,sit_out_at=NULL,
         scheduled_leave_hands=NULL
   WHERE s.user_id=p_user_id AND s.left_at IS NULL
     AND EXISTS(SELECT 1 FROM public.tables tb
                 WHERE tb.id=s.table_id AND tb.tournament_id=p_tournament_id);
  UPDATE public.tables tb
     SET current_players=(SELECT count(*) FROM public.table_seats s
                           WHERE s.table_id=tb.id AND s.left_at IS NULL),
         updated_at=now()
   WHERE tb.tournament_id=p_tournament_id;
  DELETE FROM public.tournament_players tp WHERE tp.id=v_reg.id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'registration % was not deleted after settlement',v_reg.id
      USING ERRCODE='40001';
  END IF;

  SELECT * INTO v_escrow_after FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id;
  SELECT round(COALESCE(sum(r.rake_amount),0),2) INTO v_rake_after
    FROM public.rake_records r
   WHERE r.tournament_id=p_tournament_id AND r.is_tournament;
  SELECT round(COALESCE(sum(w.amount),0),2) INTO v_wallet_refunds_after
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=p_user_id
     AND w.type='credit'
     AND lower(w.category) IN ('refund','tournament_refund');
  IF (SELECT count(*) FROM public.tournament_players tp
       WHERE tp.tournament_id=p_tournament_id
         AND tp.status::text IN ('registered','playing'))<>v_players_before-1
     OR v_wallet_refunds_after IS DISTINCT FROM
          round(v_wallet_refunds_before+v_wallet_amount,2)
     OR v_escrow_after.prize_balance IS DISTINCT FROM
          round(v_escrow_before.prize_balance-v_refund_prize,2)
     OR v_escrow_after.bounty_balance IS DISTINCT FROM
          round(v_escrow_before.bounty_balance-v_refund_bounty,2)
     OR v_escrow_after.fee_balance IS DISTINCT FROM
          round(v_escrow_before.fee_balance-v_refund_fee,2)
     OR v_rake_after IS DISTINCT FROM round(v_rake_before-v_refund_fee,2)
     OR NOT EXISTS(
       SELECT 1 FROM public.tournaments t
        WHERE t.id=p_tournament_id
          AND t.current_players=v_players_before-1
          AND t.prize_pool=v_escrow_after.prize_balance
          AND t.bounty_pool=v_escrow_after.bounty_balance
          AND t.total_rake=v_rake_after) THEN
    RAISE EXCEPTION 'registration % did not leave exact final state',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  IF p_expected_table_id IS NOT NULL THEN
    SELECT count(*) INTO v_seats_taken FROM public.table_seats s
     WHERE s.table_id=p_expected_table_id AND s.left_at IS NULL;
  END IF;

  -- The entire transaction is refused if its final verified outcome was not
  -- established before the locked schedule cutoff. All preceding writes then
  -- roll back atomically; no wall-clock grace period exists.
  v_unregistered_at:=clock_timestamp();
  IF v_unregistered_at>=v_t.start_time THEN
    RAISE EXCEPTION 'tournament started before unregistration could commit'
      USING ERRCODE='55000';
  END IF;

  INSERT INTO public.tournament_unregistration_receipts(
    registration_id,request_id,tournament_id,user_id,source_table_id,
    refunded_chips,returned_ticket_value,entitlement_ids,ticket_ids,
    source_wallet_club_ids,credit_ledger_ids,wallet_transaction_ids,
    seat_number,seats_taken,scheduled_start_at,settled_at)
  VALUES(
    v_reg.id,v_request_id,p_tournament_id,p_user_id,p_expected_table_id,
    v_wallet_amount,v_ticket_amount,v_entitlement_ids,v_ticket_ids,
    v_source_wallet_club_ids,v_credit_ledger_ids,v_wallet_transaction_ids,
    v_seat_number,v_seats_taken,v_t.start_time,v_unregistered_at);
  v_receipt:=public.fn_ca_tournament_unregistration_receipt(
    p_tournament_id,p_user_id,p_expected_table_id,v_request_id);
  IF v_receipt IS NULL
     OR (v_receipt->>'registration_id')::uuid IS DISTINCT FROM v_reg.id THEN
    RAISE EXCEPTION 'registration % has no exact unregistration receipt',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  RETURN v_receipt||jsonb_build_object('replayed',false);
END;
$$;


ALTER FUNCTION public.fn_ca_unregister_tournament_player_exact_pre_seat_guard(p_tournament_id uuid, p_user_id uuid, p_expected_table_id uuid, p_description text, p_request_id uuid) OWNER TO postgres;

--
-- Name: fn_ca_unresolved_write_failures(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_unresolved_write_failures() RETURNS TABLE(id bigint, occurred_at timestamp with time zone, club_id uuid, user_id uuid, delta numeric, sql_state text, message text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT f.id, f.occurred_at, f.club_id, f.user_id, f.delta, f.sqlstate, f.message
    FROM public.ca_ledger_write_failures f
   WHERE NOT EXISTS (
           SELECT 1
             FROM public.chip_ledger l
            WHERE l.idempotency_key = 'correction:lwf:' || f.id
         )
   ORDER BY f.occurred_at DESC;
$$;


ALTER FUNCTION public.fn_ca_unresolved_write_failures() OWNER TO postgres;

--
-- Name: FUNCTION fn_ca_unresolved_write_failures(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_unresolved_write_failures() IS 'Swallowed ledger writes with no compensating correction:lwf:<id> entry. The number that can return to zero.';


--
-- Name: fn_ca_verify_ledger_chain(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_verify_ledger_chain(p_last_n bigint DEFAULT 50000) RETURNS TABLE(checked bigint, breaks bigint, first_break_seq bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r RECORD;
  v_checked bigint := 0;
  v_breaks  bigint := 0;
  v_first   bigint := NULL;
  v_calc text;
BEGIN
  FOR r IN
    SELECT * FROM (
      SELECT * FROM public.chip_ledger
       WHERE chain_seq IS NOT NULL
       ORDER BY chain_seq DESC
       LIMIT p_last_n) t
    ORDER BY chain_seq ASC
  LOOP
    v_checked := v_checked + 1;
    v_calc := encode(extensions.digest(
      'v1'
      || '|' || r.chain_seq::text
      || '|' || COALESCE(r.epoch_id::text,'')
      || '|' || r.amount::text
      || '|' || r.from_type || ':' || COALESCE(r.from_entity_id::text,'')
      || '|' || r.to_type   || ':' || COALESCE(r.to_entity_id::text,'')
      || '|' || r.category
      || '|' || COALESCE(r.idempotency_key,'')
      || '|' || COALESCE(r.correlation_id::text,'')
      || '|' || r.created_at::text,
      'sha256'), 'hex');
    IF v_calc IS DISTINCT FROM r.row_hash THEN
      v_breaks := v_breaks + 1;
      v_first := COALESCE(v_first, r.chain_seq);
    END IF;
  END LOOP;

  IF v_breaks > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_verify_ledger_chain', 'unauthorized_adjustment', 'critical',
      'ledger-chain-break:' || COALESCE(v_first, 0)::text,
      0, NULL, NULL, 'ledger', 'chip_ledger', NULL, NULL, NULL, NULL, NULL,
      NULL, NULL, NULL, NULL,
      'checksum verification found ' || v_breaks || ' altered row(s) starting at seq ' || v_first,
      false, jsonb_build_object('breaks', v_breaks, 'first_break_seq', v_first));
  END IF;

  checked := v_checked; breaks := v_breaks; first_break_seq := v_first;
  RETURN NEXT;
END $$;


ALTER FUNCTION public.fn_ca_verify_ledger_chain(p_last_n bigint) OWNER TO postgres;

--
-- Name: fn_ca_weekly_revenue_digest(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_weekly_revenue_digest(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(days => GREATEST(p_days,1));
  v jsonb; v_msg text; r uuid;
BEGIN
  SELECT jsonb_build_object(
    'window_days', p_days,
    'since', v_since,
    'cash_rake', (SELECT round(COALESCE(sum(amount),0),2) FROM chip_ledger
                   WHERE created_at > v_since AND category='rake'
                     AND from_type='table_stack'),
    'tournament_and_spin_rake', (SELECT round(COALESCE(sum(amount),0),2) FROM chip_ledger
                   WHERE created_at > v_since AND category='rake'
                     AND from_type='prize_liability'),
    'rakeback_paid_to_clubs', (SELECT round(COALESCE(sum(amount),0),2) FROM chip_ledger
                   WHERE created_at > v_since AND category='rakeback'),
    'minted', (SELECT round(COALESCE(sum(amount),0),2) FROM chip_ledger
                   WHERE created_at > v_since AND from_type IN ('system_mint','issuance_reserve')),
    'burned', (SELECT round(COALESCE(sum(amount),0),2) FROM chip_ledger
                   WHERE created_at > v_since AND to_type IN ('system_burn','chip_retirement')),
    'promo_and_leaderboard_spend', (SELECT round(COALESCE(sum(amount),0),2) FROM chip_ledger
                   WHERE created_at > v_since
                     AND category IN ('promo_send','promo','leaderboard_payout','club_opening_allocation')),
    'bbj_contributions', (SELECT round(COALESCE(sum(amount),0),2) FROM chip_ledger
                   WHERE created_at > v_since AND category='bbj_contribution'),
    'suspense_flow', (SELECT round(COALESCE(sum(amount),0),2) FROM chip_ledger
                   WHERE created_at > v_since
                     AND (from_type='settlement_suspense' OR to_type='settlement_suspense')),
    'cert_player_flow', (SELECT round(COALESCE(sum(amount),0),2) FROM chip_ledger
                   WHERE created_at > v_since
                     AND ((from_type='player_wallet' AND public.fn_ca_is_cert_account(from_entity_id))
                       OR (to_type='player_wallet' AND public.fn_ca_is_cert_account(to_entity_id)))),
    'diamond_net', (SELECT round(COALESCE(sum(amount),0),2) FROM diamond_transactions
                   WHERE created_at > v_since),
    'supply_unexplained_net', (SELECT round(COALESCE(sum(unexplained),0),2) FROM ca_supply_snapshots
                   WHERE taken_at > v_since AND unexplained IS NOT NULL),
    'generated_at', now()
  ) INTO v;

  v_msg := 'Cash Rake ' || (v->>'cash_rake')
    || ' | Tournament And Spin Rake ' || (v->>'tournament_and_spin_rake')
    || ' | Rakeback Paid ' || (v->>'rakeback_paid_to_clubs')
    || ' | Minted ' || (v->>'minted') || ' | Burned ' || (v->>'burned')
    || ' | Promo And Leaderboard Spend ' || (v->>'promo_and_leaderboard_spend')
    || ' | BBJ Contributions ' || (v->>'bbj_contributions')
    || ' | Suspense Flow ' || (v->>'suspense_flow')
    || ' | Cert Player Flow (Excluded) ' || (v->>'cert_player_flow')
    || ' | Unexplained Supply Net ' || (v->>'supply_unexplained_net');

  FOR r IN SELECT user_id FROM ca_incident_recipients WHERE active
  LOOP
    INSERT INTO notifications (user_id, type, title, message, data)
    VALUES (r, 'financial_digest',
            'Weekly Revenue Digest (' || p_days || 'd)',
            left(v_msg, 500),
            jsonb_build_object('digest', v));
  END LOOP;

  RETURN v;
END $$;


ALTER FUNCTION public.fn_ca_weekly_revenue_digest(p_days integer) OWNER TO postgres;

