--
-- Name: fn_caller_can_moderate_user(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_caller_can_moderate_user(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM club_members target_cm
    JOIN clubs c ON c.id = target_cm.club_id
    WHERE target_cm.user_id = p_user_id
      AND (
        c.owner_id = (SELECT auth.uid())
        OR EXISTS (
          SELECT 1 FROM club_members admin_cm
          WHERE admin_cm.club_id = c.id
            AND admin_cm.user_id = (SELECT auth.uid())
            AND admin_cm.role = ANY (ARRAY['owner','co_owner','admin'])
        )
      )
  );
$$;


ALTER FUNCTION public.fn_caller_can_moderate_user(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_caller_is_engine(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_caller_is_engine() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
  -- The engine and every server-side job authenticate as service_role. A NULL
  -- means there is no PostgREST request context at all - psql, pg_cron, a
  -- migration - which is equally trusted. A browser can never produce NULL:
  -- reaching `authenticated` requires a verified JWT and PostgREST always sets
  -- request.jwt.claims from it.
  --
  -- NOT current_user. Inside a SECURITY DEFINER body current_user is the
  -- function OWNER for the browser and the engine alike, which is what made an
  -- earlier guard on club_members a silent no-op.
  SELECT COALESCE(auth.role(), 'service_role') = 'service_role';
$$;


ALTER FUNCTION public.fn_caller_is_engine() OWNER TO postgres;

--
-- Name: FUNCTION fn_caller_is_engine(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_caller_is_engine() IS 'True when the caller is the engine or another server-side job: service_role, or no request context at all. The single definition of that question, so no two guards can disagree about it.';


--
-- Name: fn_caller_session_is_live(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_caller_session_is_live() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_claims jsonb;
  v_sid    uuid;
BEGIN
  IF public.fn_caller_is_engine() THEN
    RETURN true;
  END IF;

  -- Malformed or absent claims are not a crash, they are a refusal.
  BEGIN
    v_claims := current_setting('request.jwt.claims', true)::jsonb;
  EXCEPTION WHEN others THEN
    RETURN false;
  END;

  IF v_claims IS NULL THEN
    RETURN false;
  END IF;

  BEGIN
    v_sid := (v_claims ->> 'session_id')::uuid;
  EXCEPTION WHEN others THEN
    RETURN false;
  END;

  IF v_sid IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
      FROM auth.sessions s
     WHERE s.id = v_sid
       AND (s.not_after IS NULL OR s.not_after > now())
  );
END;
$$;


ALTER FUNCTION public.fn_caller_session_is_live() OWNER TO postgres;

--
-- Name: fn_can_agent_remove_chips(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_can_agent_remove_chips(p_agent_id uuid, p_player_id uuid, p_club_id uuid, p_amount numeric) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_available_to_remove DECIMAL;
BEGIN
    -- Sum chips sent by this agent to this player in the last 10 minutes that haven't been reversed
    SELECT COALESCE(SUM(amount), 0) INTO v_available_to_remove
    FROM chip_transactions
    WHERE from_user_id = p_agent_id
      AND to_user_id = p_player_id
      AND club_id = p_club_id
      AND transaction_type = 'send'
      AND reversible_until > NOW()
      AND is_reversed = FALSE;

    RETURN v_available_to_remove >= p_amount;
END;
$$;


ALTER FUNCTION public.fn_can_agent_remove_chips(p_agent_id uuid, p_player_id uuid, p_club_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: fn_can_create_games(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_can_create_games(p_club_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_own    uuid;
  v_member uuid;
BEGIN
  IF EXISTS (SELECT 1 FROM public.clubs WHERE id=p_club_id AND asset='diamonds') THEN RETURN false; END IF;
  IF p_club_id IS NULL OR p_user_id IS NULL THEN
    RETURN false;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM clubs c WHERE c.id = p_club_id) THEN
    RETURN false;
  END IF;

  SELECT own_union_id, member_union_id INTO v_own, v_member
    FROM fn_club_union_context(p_club_id);

  IF v_own IS NOT NULL THEN
    RETURN EXISTS (SELECT 1 FROM unions u
                    WHERE u.id = v_own AND u.owner_id = p_user_id)
        OR EXISTS (SELECT 1 FROM union_admins a
                    WHERE a.union_id = v_own AND a.user_id = p_user_id)
        OR EXISTS (SELECT 1 FROM clubs c
                    WHERE c.id = p_club_id AND c.owner_id = p_user_id)
        OR EXISTS (SELECT 1 FROM club_members m
                    WHERE m.club_id = p_club_id AND m.user_id = p_user_id
                      AND m.role IN ('owner', 'co_owner', 'admin')
                      AND m.status IN ('active', 'approved'));
  END IF;

  IF v_member IS NOT NULL THEN
    RETURN EXISTS (SELECT 1 FROM unions u
                    WHERE u.id = v_member AND u.owner_id = p_user_id)
        OR EXISTS (SELECT 1 FROM union_admins a
                    WHERE a.union_id = v_member AND a.user_id = p_user_id);
  END IF;

  RETURN EXISTS (SELECT 1 FROM clubs c
                  WHERE c.id = p_club_id AND c.owner_id = p_user_id)
      OR EXISTS (SELECT 1 FROM club_members m
                  WHERE m.club_id = p_club_id
                    AND m.user_id = p_user_id
                    AND m.role IN ('owner', 'co_owner', 'admin')
                    AND m.status IN ('active', 'approved'));
END;
$$;


ALTER FUNCTION public.fn_can_create_games(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

