--
-- Name: fn_can_view_post(uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_can_view_post(p_author_id uuid, p_audience_mode text, p_audience_list text[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_viewer uuid;
  v_mode text;
BEGIN
  v_viewer := auth.uid();
  v_mode := COALESCE(p_audience_mode, 'public');

  -- Author always sees their own posts.
  IF v_viewer IS NOT NULL AND v_viewer = p_author_id THEN
    RETURN TRUE;
  END IF;

  IF v_mode = 'public' THEN
    RETURN TRUE;
  END IF;

  -- All non-public modes require the viewer to be authenticated.
  IF v_viewer IS NULL THEN
    RETURN FALSE;
  END IF;

  IF v_mode = 'only_me' THEN
    RETURN FALSE; -- author already returned above
  END IF;

  IF v_mode = 'friends' THEN
    RETURN public.fn_are_friends(v_viewer, p_author_id);
  END IF;

  IF v_mode = 'friends_except' THEN
    -- audience_list holds excluded user ids
    RETURN public.fn_are_friends(v_viewer, p_author_id)
       AND NOT (v_viewer::text = ANY(COALESCE(p_audience_list, '{}'::text[])));
  END IF;

  IF v_mode IN ('specific', 'custom') THEN
    RETURN v_viewer::text = ANY(COALESCE(p_audience_list, '{}'::text[]));
  END IF;

  -- Unknown mode: fail closed.
  RETURN FALSE;
END;
$$;


ALTER FUNCTION public.fn_can_view_post(p_author_id uuid, p_audience_mode text, p_audience_list text[]) OWNER TO postgres;

--
-- Name: fn_cancel_cashout(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cancel_cashout(p_cashout_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_cashout RECORD;
BEGIN
  -- Atomically claim the cashout (only if still pending)
  UPDATE cashout_requests SET status = 'cancelled', cancelled_at = NOW(), updated_at = NOW()
  WHERE id = p_cashout_id AND player_id = p_user_id AND status = 'pending'
  RETURNING * INTO v_cashout;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cashout Not Found Or Already Processed');
  END IF;
  -- Return chips to player wallet
  UPDATE wallets SET balance = balance + v_cashout.amount, updated_at = NOW()
  WHERE user_id = p_user_id AND wallet_type = 'PLAYER';
  INSERT INTO wallet_transactions (user_id, wallet_type, type, amount, category, description)
  VALUES (p_user_id, 'PLAYER', 'credit', v_cashout.amount, 'cashout_cancel', 'Cashout Cancelled - Chips Returned');
  RETURN jsonb_build_object('success', true, 'amount', v_cashout.amount);
END; $$;


ALTER FUNCTION public.fn_cancel_cashout(p_cashout_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_cancel_cashout_atomic(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cancel_cashout_atomic(p_cashout_id uuid, p_user_id uuid, p_is_agent boolean DEFAULT false, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_cashout record;
  v_escrow  record;
  v_new_balance numeric;
BEGIN
  SELECT * INTO v_cashout FROM cashout_requests WHERE id = p_cashout_id FOR UPDATE;

  IF v_cashout IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'cashout not found');
  END IF;

  IF v_cashout.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'cashout not in pending status',
                              'current_status', v_cashout.status);
  END IF;

  IF p_is_agent THEN
    IF NOT EXISTS (
      SELECT 1 FROM club_members
      WHERE club_id = v_cashout.club_id
        AND user_id = p_user_id
        AND role IN ('agent', 'sub_agent', 'super_agent', 'owner', 'co_owner', 'admin')
    ) AND NOT EXISTS (
      SELECT 1 FROM clubs WHERE id = v_cashout.club_id AND owner_id = p_user_id
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'not authorized to cancel for this club');
    END IF;
  ELSE
    IF v_cashout.player_id <> p_user_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'only the requester can self-cancel');
    END IF;
  END IF;

  SELECT * INTO v_escrow FROM chip_escrow WHERE cashout_request_id = p_cashout_id FOR UPDATE;
  IF v_escrow.id IS NOT NULL AND v_escrow.released_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'those chips have already been released');
  END IF;

  UPDATE club_members
  SET chip_balance = COALESCE(chip_balance, 0) + v_cashout.amount,
      updated_at = NOW()
  WHERE club_id = v_cashout.club_id AND user_id = v_cashout.player_id
  RETURNING chip_balance INTO v_new_balance;

  IF v_new_balance IS NULL THEN
    INSERT INTO club_members (club_id, user_id, role, chip_balance, joined_at, created_at, updated_at, status, is_active)
    VALUES (v_cashout.club_id, v_cashout.player_id, 'player', v_cashout.amount, NOW(), NOW(), NOW(), 'active', true)
    ON CONFLICT (club_id, user_id) DO UPDATE
      SET chip_balance = COALESCE(club_members.chip_balance, 0) + EXCLUDED.chip_balance,
          updated_at = NOW()
    RETURNING chip_balance INTO v_new_balance;
  END IF;

  IF v_escrow.id IS NOT NULL THEN
    UPDATE chip_escrow
       SET released_at = NOW(),
           release_type = CASE WHEN p_is_agent THEN 'rejected' ELSE 'cancelled' END
     WHERE id = v_escrow.id;
  END IF;

  UPDATE cashout_requests
  SET status = CASE WHEN p_is_agent THEN 'rejected' ELSE 'cancelled' END,
      agent_note = CASE WHEN p_is_agent THEN COALESCE(p_note, agent_note) ELSE agent_note END,
      player_note = CASE WHEN NOT p_is_agent THEN COALESCE(p_note, player_note) ELSE player_note END,
      cancelled_at = NOW(),
      updated_at = NOW()
  WHERE id = p_cashout_id;

  INSERT INTO chip_transactions (
    id, club_id, from_user_id, to_user_id, amount,
    transaction_type, notes, related_cashout_id, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), v_cashout.club_id, p_user_id, v_cashout.player_id, v_cashout.amount,
    CASE WHEN p_is_agent THEN 'cashout_denied' ELSE 'cashout_cancelled' END,
    COALESCE(p_note, 'Cash Out Closed. Chips Returned From Escrow'),
    p_cashout_id, v_new_balance, NOW()
  );

  IF p_is_agent THEN
    INSERT INTO notifications (user_id, type, title, message, metadata, actor_id)
    VALUES (v_cashout.player_id, 'settlement', 'Cash Out Declined',
            'Your Cash Out Of ' || trim(to_char(v_cashout.amount, 'FM999,999,999,990'))
              || ' Chips Was Declined And The Chips Are Back In Your Wallet',
            jsonb_build_object('clubId', v_cashout.club_id, 'cashoutId', p_cashout_id,
                               'amount', v_cashout.amount),
            p_user_id);
  END IF;

  RETURN jsonb_build_object('success', true, 'cashout_id', p_cashout_id,
                            'amount', v_cashout.amount, 'new_balance', v_new_balance);
END;
$$;


ALTER FUNCTION public.fn_cancel_cashout_atomic(p_cashout_id uuid, p_user_id uuid, p_is_agent boolean, p_note text) OWNER TO postgres;

--
-- Name: FUNCTION fn_cancel_cashout_atomic(p_cashout_id uuid, p_user_id uuid, p_is_agent boolean, p_note text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cancel_cashout_atomic(p_cashout_id uuid, p_user_id uuid, p_is_agent boolean, p_note text) IS 'BUG 025: real impl. Validates pending + authorization (self or agent), refunds player chip_balance from escrow, transitions cashout to cancelled, writes audit.';


--
-- Name: fn_cancel_club_join_request(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cancel_club_join_request(p_club_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_deleted integer := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  DELETE FROM public.club_members
   WHERE club_id = p_club_id
     AND user_id = v_uid
     AND status = 'pending';
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted > 0;
END;
$$;


ALTER FUNCTION public.fn_cancel_club_join_request(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_cancel_managed_game_schedule(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cancel_managed_game_schedule(p_schedule_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_schedule public.managed_game_schedules%ROWTYPE;
  v_club uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000'; END IF;
  SELECT * INTO v_schedule FROM public.managed_game_schedules
   WHERE schedule_id=p_schedule_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','schedule_not_found'); END IF;
  IF v_schedule.game_kind='table' THEN
    SELECT club_id INTO v_club FROM public.tables WHERE id=v_schedule.game_id;
  ELSE
    SELECT club_id INTO v_club FROM public.tournaments WHERE id=v_schedule.game_id;
  END IF;
  IF NOT public.fn_can_create_games(v_club,v_uid) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized');
  END IF;
  IF v_schedule.status<>'scheduled' THEN
    RETURN jsonb_build_object('ok',false,'reason','schedule_not_pending');
  END IF;
  UPDATE public.managed_game_schedules SET status='cancelled',completed_at=now(),
    result=jsonb_build_object('ok',true,'cancelled_by',v_uid)
  WHERE schedule_id=p_schedule_id RETURNING * INTO v_schedule;
  PERFORM public.fn_emit_game_management_event(
    'game_changed',v_club,NULL,NULL,v_schedule.game_kind,v_schedule.game_id,NULL,
    jsonb_build_object('operation','close_schedule_cancelled','schedule_id',p_schedule_id)
  );
  RETURN jsonb_build_object('ok',true,'schedule',to_jsonb(v_schedule));
END;
$$;


ALTER FUNCTION public.fn_cancel_managed_game_schedule(p_schedule_id uuid) OWNER TO postgres;

--
-- Name: fn_cancel_revoked_youtube_transcode_jobs(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cancel_revoked_youtube_transcode_jobs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  UPDATE public.video_transcode_jobs job
  SET status = 'cancelled',
      completed_at = now(),
      error_message = 'native_processing_authorization_revoked',
      worker_id = NULL,
      claim_token = NULL,
      locked_at = NULL,
      heartbeat_at = now()
  WHERE job.reel_id = NEW.id
    AND job.source_type = 'youtube'
    AND job.status IN ('queued', 'processing', 'running')
    AND (
      NEW.native_processing_requested IS DISTINCT FROM true
      OR NEW.rights_status NOT IN ('owned', 'licensed')
      OR COALESCE(NEW.is_deleted, false)
      OR NEW.source_type IS DISTINCT FROM 'youtube'
      OR NEW.origin_type = 'video_library'
      OR NEW.source_post_id IS NULL
      OR NEW.youtube_video_id IS NULL
      OR job.user_id IS DISTINCT FROM NEW.author_id
      OR job.rights_status IS DISTINCT FROM NEW.rights_status
      OR job.origin_type IS DISTINCT FROM NEW.origin_type
      OR job.source_asset_id IS DISTINCT FROM NEW.source_asset_id
      OR job.canonical_asset_key IS DISTINCT FROM NEW.canonical_asset_key
      OR public.fn_extract_youtube_video_id(job.youtube_url) IS DISTINCT FROM NEW.youtube_video_id
      OR public.fn_extract_youtube_video_id(job.source_url) IS DISTINCT FROM NEW.youtube_video_id
      OR public.fn_extract_youtube_video_id(NEW.video_url) IS DISTINCT FROM NEW.youtube_video_id
      OR public.fn_extract_youtube_video_id(NEW.original_youtube_url) IS DISTINCT FROM NEW.youtube_video_id
    );
  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_cancel_revoked_youtube_transcode_jobs() OWNER TO postgres;

--
-- Name: fn_cancel_tournament_ticket(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cancel_tournament_ticket(p_ticket_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me uuid:=auth.uid();
  v_t public.tournament_tickets%ROWTYPE;
  v_after numeric;
  v_context jsonb;
  v_setting text;
  v_receipt public.chip_transactions%ROWTYPE;
  v_issue public.chip_transactions%ROWTYPE;
  v_escrow_entity uuid;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','Not Authenticated');
  END IF;
  IF p_ticket_id IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','Choose A Ticket');
  END IF;

  SELECT * INTO v_t FROM public.tournament_tickets
   WHERE id=p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success',false,'error','Ticket Not Found');
  END IF;
  IF v_t.redemption_mode='tournament_entry_only' THEN
    RETURN jsonb_build_object(
      'success',false,
      'error','Returned Tournament-Entry Tickets Cannot Be Cancelled For Chips');
  END IF;
  IF v_t.issued_by IS DISTINCT FROM v_me THEN
    RETURN jsonb_build_object(
      'success',false,'error','Only The Issuer May Cancel A Ticket');
  END IF;
  IF v_t.status='cancelled' THEN
    SELECT * INTO v_receipt FROM public.chip_transactions
     WHERE transaction_type='tournament_ticket_cancel'
       AND metadata->>'ticket_id'=p_ticket_id::text LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'success',true,'replayed',true,'refunded',v_t.value,
        'your_balance',(v_receipt.metadata->>'issuer_balance_after')::numeric,
        'transaction_id',v_receipt.id);
    END IF;
  END IF;
  IF v_t.status<>'issued' THEN
    RETURN jsonb_build_object(
      'success',false,'error','Ticket Already '||initcap(v_t.status));
  END IF;

  SELECT * INTO v_issue FROM public.chip_transactions
   WHERE transaction_type='tournament_ticket_issue'
     AND metadata->>'ticket_id'=p_ticket_id::text LIMIT 1;
  IF FOUND AND v_issue.metadata ? 'escrow_entity_id' THEN
    IF v_issue.club_id IS DISTINCT FROM v_t.club_id
       OR v_issue.from_user_id IS DISTINCT FROM v_t.issued_by
       OR v_issue.to_user_id IS DISTINCT FROM v_t.holder_id
       OR v_issue.amount IS DISTINCT FROM v_t.value
       OR v_issue.metadata->>'escrow_entity_id'
            IS DISTINCT FROM p_ticket_id::text THEN
      RAISE EXCEPTION 'Ticket escrow receipt does not match its entitlement'
        USING ERRCODE='22023';
    END IF;
    v_escrow_entity:=p_ticket_id;
  END IF;
  SELECT jsonb_object_agg(k,COALESCE(current_setting(k,true),''))
    INTO v_context
    FROM unnest(ARRAY[
      'app.ledger_category','app.ledger_counterparty',
      'app.ledger_counterparty_entity','app.ledger_tournament']) settings(k);
  PERFORM set_config('app.ledger_tournament','',true);
  PERFORM set_config('app.ledger_category','escrow_release',true);
  PERFORM set_config('app.ledger_counterparty','escrow',true);
  PERFORM set_config(
    'app.ledger_counterparty_entity',COALESCE(v_escrow_entity::text,''),true);
  UPDATE public.club_members
     SET chip_balance=COALESCE(chip_balance,0)+v_t.value,updated_at=now()
   WHERE club_id=v_t.club_id AND user_id=v_me
     AND COALESCE(status,'active') IN ('active','approved')
   RETURNING chip_balance INTO v_after;
  FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
    PERFORM set_config(v_setting,v_context->>v_setting,true);
  END LOOP;
  IF v_after IS NULL THEN
    RETURN jsonb_build_object(
      'success',false,
      'error','You Are No Longer A Member Of That Club, So The Escrow Has Nowhere To Land');
  END IF;

  UPDATE public.tournament_tickets
     SET status='cancelled',cancelled_at=now()
   WHERE id=p_ticket_id;
  INSERT INTO public.chip_transactions(
    club_id,from_user_id,to_user_id,amount,transaction_type,notes,
    balance_after,metadata)
  VALUES(
    v_t.club_id,NULL,v_me,v_t.value,'tournament_ticket_cancel',
    'Tournament Ticket Cancelled: Escrow Refunded',v_after,
    jsonb_build_object(
      'ticket_id',p_ticket_id,'issuer_id',v_t.issued_by,
      'holder_id',v_t.holder_id,'escrow_action','refund_to_issuer',
      'issuer_balance_after',v_after))
  RETURNING * INTO v_receipt;

  RETURN jsonb_build_object(
    'success',true,'replayed',false,'refunded',v_t.value,
    'your_balance',v_after,'transaction_id',v_receipt.id);
END;
$$;


ALTER FUNCTION public.fn_cancel_tournament_ticket(p_ticket_id uuid) OWNER TO postgres;

--
-- Name: fn_cancelled_tournament_evidence_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cancelled_tournament_evidence_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_tournament_id uuid;
BEGIN
  IF TG_OP<>'INSERT' THEN
    v_old_tournament_id:=NULLIF(to_jsonb(OLD)->>'tournament_id','')::uuid;
  END IF;
  IF TG_OP<>'DELETE' THEN
    v_new_tournament_id:=NULLIF(to_jsonb(NEW)->>'tournament_id','')::uuid;
  END IF;
  IF TG_OP='UPDATE' AND v_new_tournament_id IS DISTINCT FROM v_old_tournament_id THEN
    RAISE EXCEPTION '% rows cannot move between tournaments',TG_TABLE_NAME
      USING ERRCODE='55000';
  END IF;
  v_tournament_id:=COALESCE(v_new_tournament_id,v_old_tournament_id);
  IF v_tournament_id IS NULL THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  IF TG_TABLE_NAME='chip_ledger' AND TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'tournament chip ledger evidence is append-only'
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='INSERT' THEN
    PERFORM 1 FROM public.tournaments t
     WHERE t.id=v_tournament_id FOR KEY SHARE;
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h
              WHERE h.tournament_id=v_tournament_id) THEN
    RAISE EXCEPTION 'cancelled tournament % has immutable % evidence',
      v_tournament_id,TG_TABLE_NAME USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


ALTER FUNCTION public.fn_cancelled_tournament_evidence_is_immutable() OWNER TO postgres;

--
-- Name: fn_cancelled_tournament_parent_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cancelled_tournament_parent_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h
              WHERE h.tournament_id=OLD.id) THEN
    RAISE EXCEPTION 'receipted cancellation % is immutable',OLD.id
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


ALTER FUNCTION public.fn_cancelled_tournament_parent_is_immutable() OWNER TO postgres;

--
-- Name: fn_cancelled_tournament_seat_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cancelled_tournament_seat_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
BEGIN
  IF TG_OP<>'INSERT' THEN
    SELECT tb.tournament_id INTO v_old_tournament_id
      FROM public.tables tb WHERE tb.id=OLD.table_id;
  END IF;
  IF TG_OP<>'DELETE' THEN
    SELECT tb.tournament_id INTO v_new_tournament_id
      FROM public.tables tb WHERE tb.id=NEW.table_id;
  END IF;
  IF TG_OP='UPDATE' AND v_new_tournament_id IS DISTINCT FROM v_old_tournament_id THEN
    RAISE EXCEPTION 'seat % cannot move between tournament owners',OLD.id
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='INSERT' AND v_new_tournament_id IS NOT NULL THEN
    PERFORM 1 FROM public.tournaments t
     WHERE t.id=v_new_tournament_id FOR KEY SHARE;
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h
              WHERE h.tournament_id=COALESCE(v_new_tournament_id,v_old_tournament_id)) THEN
    RAISE EXCEPTION 'cancelled tournament seat evidence is immutable'
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


ALTER FUNCTION public.fn_cancelled_tournament_seat_is_immutable() OWNER TO postgres;

--
-- Name: fn_cancelled_tournament_wallet_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cancelled_tournament_wallet_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
BEGIN
  IF TG_OP<>'INSERT' THEN v_old_tournament_id:=OLD.related_entity_id; END IF;
  IF TG_OP<>'DELETE' THEN v_new_tournament_id:=NEW.related_entity_id; END IF;
  IF TG_OP='INSERT' AND v_new_tournament_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.tournaments t
                  WHERE t.id=v_new_tournament_id) THEN
    PERFORM 1 FROM public.tournaments t
     WHERE t.id=v_new_tournament_id FOR KEY SHARE;
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h
              WHERE h.tournament_id=v_old_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h
                 WHERE h.tournament_id=v_new_tournament_id) THEN
    RAISE EXCEPTION 'cancelled tournament wallet evidence is immutable'
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


ALTER FUNCTION public.fn_cancelled_tournament_wallet_is_immutable() OWNER TO postgres;

--
-- Name: fn_capture_home_weekly_snapshots(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_capture_home_weekly_snapshots() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_week_start date;
    v_captured   int := 0;
    v_group      RECORD;
    v_prev_snapshot RECORD;
BEGIN
    -- Monday of the current week
    v_week_start := date_trunc('week', CURRENT_DATE)::date;

    FOR v_group IN 
        SELECT * FROM commander_home_groups WHERE is_active = true
    LOOP
        SELECT * INTO v_prev_snapshot 
          FROM commander_home_group_weekly_snapshots
         WHERE group_id = v_group.id 
         ORDER BY week_start DESC LIMIT 1;

        INSERT INTO commander_home_group_weekly_snapshots (
            group_id, week_start,
            member_count, new_members,
            games_scheduled, games_completed, games_cancelled,
            total_rsvp_yes, total_checked_in, flake_count,
            post_count, view_count_delta, share_count_delta
        ) VALUES (
            v_group.id, v_week_start,
            COALESCE(v_group.member_count, 0),
            (SELECT COUNT(*) FROM commander_home_members 
              WHERE group_id = v_group.id AND created_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_games 
              WHERE group_id = v_group.id AND created_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_games 
              WHERE group_id = v_group.id AND status = 'completed' 
                AND updated_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_games 
              WHERE group_id = v_group.id AND status = 'cancelled' 
                AND cancelled_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_rsvps r 
              JOIN commander_home_games g ON g.id = r.game_id
              WHERE g.group_id = v_group.id AND r.response = 'yes'
                AND r.responded_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_rsvps r 
              JOIN commander_home_games g ON g.id = r.game_id
              WHERE g.group_id = v_group.id AND r.checked_in_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_rsvps r 
              JOIN commander_home_games g ON g.id = r.game_id
              WHERE g.group_id = v_group.id AND r.flaked = true
                AND r.updated_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_posts 
              WHERE group_id = v_group.id AND created_at >= v_week_start - INTERVAL '7 days'),
            -- Deltas vs last snapshot
            GREATEST(0, COALESCE(v_group.view_count, 0) - COALESCE(v_prev_snapshot.view_count_delta, 0)),
            GREATEST(0, COALESCE(v_group.share_click_count, 0) - COALESCE(v_prev_snapshot.share_count_delta, 0))
        )
        ON CONFLICT (group_id, week_start) DO UPDATE SET
            member_count       = EXCLUDED.member_count,
            new_members        = EXCLUDED.new_members,
            games_scheduled    = EXCLUDED.games_scheduled,
            games_completed    = EXCLUDED.games_completed,
            games_cancelled    = EXCLUDED.games_cancelled,
            total_rsvp_yes     = EXCLUDED.total_rsvp_yes,
            total_checked_in   = EXCLUDED.total_checked_in,
            flake_count        = EXCLUDED.flake_count,
            post_count         = EXCLUDED.post_count,
            captured_at        = NOW();

        v_captured := v_captured + 1;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'week_start', v_week_start, 'snapshots_captured', v_captured);
END;
$$;


ALTER FUNCTION public.fn_capture_home_weekly_snapshots() OWNER TO postgres;

--
-- Name: fn_capture_managed_game_contract(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_capture_managed_game_contract() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_kind text := CASE TG_TABLE_NAME WHEN 'tables' THEN 'table' ELSE 'tournament' END;
  v_contract jsonb;
  v_hash text;
  v_last_hash text;
  v_version integer;
  v_sqlstate text;
  v_message text;
  v_dedupe text;
BEGIN
  IF v_kind = 'table' AND to_jsonb(NEW) -> 'tournament_id' <> 'null'::jsonb THEN
    RETURN NEW;
  END IF;

  v_contract := public.fn_managed_game_contract_document(v_kind, to_jsonb(NEW));

  -- ── NOTHING IN THE CONTRACT MOVED (2026-09-06) ───────────────────────────
  -- The engine and the cluster controller write `current_players`, `status`,
  -- `lifecycle`, `last_activity_at` and the lease columns thousands of times
  -- an hour, and every one of those is in the document's denylist. Comparing
  -- the documents is the same test the hash comparison below performs, minus
  -- the advisory lock and the indexed read - and it is derived from the
  -- document rather than from a second copy of the denylist, so it cannot
  -- drift the day a contract column is added.
  IF TG_OP = 'UPDATE'
     AND v_contract IS NOT DISTINCT FROM
         public.fn_managed_game_contract_document(v_kind, to_jsonb(OLD)) THEN
    RETURN NEW;
  END IF;

  -- ── THE CAPTURE CANNOT REFUSE THE WRITE IT DESCRIBES ─────────────────────
  BEGIN
    v_hash := public.fn_managed_game_contract_hash(v_contract);

    -- Updates of one physical row normally serialize already. This lock also
    -- protects repair/import paths that can publish the same logical game from
    -- separate statements before either has allocated its next version.
    PERFORM pg_advisory_xact_lock(hashtextextended(v_kind || ':' || NEW.id::text, 0));

    SELECT contract_hash, version
      INTO v_last_hash, v_version
      FROM public.managed_game_contract_versions
     WHERE game_kind = v_kind AND game_id = NEW.id
     ORDER BY version DESC
     LIMIT 1;

    IF v_last_hash IS NOT DISTINCT FROM v_hash THEN
      RETURN NEW;
    END IF;

    INSERT INTO public.managed_game_contract_versions (
      game_kind, game_id, club_id, union_id, version, contract,
      contract_hash, published_by, change_reason
    ) VALUES (
      v_kind, NEW.id, NEW.club_id, NEW.union_id, COALESCE(v_version, 0) + 1,
      v_contract, v_hash, auth.uid(),
      CASE
        WHEN TG_OP = 'INSERT' THEN 'created'
        WHEN auth.uid() IS NULL THEN 'system_revision'
        ELSE 'operator_revision'
      END
    );

    RETURN NEW;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
    v_dedupe := 'contract_capture:' || v_kind || ':' || coalesce(v_sqlstate, 'unknown');

    -- The handler must not be able to fail either. A detector that raises is
    -- the defect it was written to catch, one level up.
    BEGIN
      UPDATE public.ca_drift_incidents
         SET occurrences  = occurrences + 1,
             last_seen_at = now(),
             metadata     = metadata
                            || jsonb_build_object('last_game_id', NEW.id,
                                                  'message', v_message)
       WHERE source = 'managed_game_contract_capture'
         AND dedupe_key = v_dedupe
         AND status IN ('open', 'acknowledged', 'reconciling');
      IF NOT FOUND THEN
        -- `classification` and `layer` are CHECK-constrained enums, read off
        -- the live catalogue rather than guessed: 'contract_capture_failed'
        -- and 'schema' are in neither list, and writing them would have made
        -- this handler raise - the exact defect one level up.
        INSERT INTO public.ca_drift_incidents (
          source, dedupe_key, classification, severity, layer,
          club_id, union_id, entity_type, entity_id, suspected_cause, metadata
        ) VALUES (
          'managed_game_contract_capture', v_dedupe, 'unknown',
          'critical', 'projection',
          NEW.club_id, NEW.union_id, v_kind, NEW.id,
          'fn_capture_managed_game_contract raised ' || coalesce(v_sqlstate, '?') ||
            '. The game write SUCCEEDED; the contract version row is missing.',
          jsonb_build_object('sqlstate', v_sqlstate, 'message', v_message,
                             'game_kind', v_kind, 'first_game_id', NEW.id,
                             'tg_op', TG_OP)
        );
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL; -- the incident could not be filed; the WARNING below still speaks
    END;

    RAISE WARNING
      'managed game contract capture failed for % % (%): % - the % write was NOT refused; incident filed under source managed_game_contract_capture',
      v_kind, NEW.id, v_sqlstate, v_message, TG_TABLE_NAME;

    RETURN NEW;
  END;
END;
$$;


ALTER FUNCTION public.fn_capture_managed_game_contract() OWNER TO postgres;

--
-- Name: FUNCTION fn_capture_managed_game_contract(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_capture_managed_game_contract() IS 'Captures a managed-game contract version. NEVER raises: a failed capture files a ca_drift_incidents row under source managed_game_contract_capture and returns NEW, because an audit record must not be able to refuse the game write it describes (2026-09-06, after 683 refused cluster ticks in 65 minutes). Exits early when the contract document is unchanged, so the engine''s current_players/status churn costs no advisory lock.';


--
-- Name: fn_card_slide_adoption(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_card_slide_adoption(p_days integer DEFAULT 7) RETURNS TABLE(days integer, users_with_setting_on bigint, users_with_setting_off bigint, active_users bigint, peels_started bigint, peels_committed bigint, peels_abandoned bigint, keyboard_opens bigint, commit_rate numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_days integer := LEAST(GREATEST(COALESCE(p_days, 7), 1), 90);
  v_caller uuid := auth.uid();
BEGIN
  -- Two statements, and both are load-bearing. There is no session -> there is
  -- no answer; and a session that is not a platform admin gets an empty result
  -- rather than an error, because an authenticated non-admin opening an admin
  -- panel is a UI state, not an incident.
  IF v_caller IS NULL THEN
    RETURN;
  END IF;
  IF NOT public.fn_is_platform_admin() THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH usage AS (
    SELECT
      COUNT(DISTINCT u.user_id) AS active_users,
      COALESCE(SUM(u.peels_started), 0) AS started,
      COALESCE(SUM(u.peels_committed), 0) AS committed,
      COALESCE(SUM(u.peels_abandoned), 0) AS abandoned,
      COALESCE(SUM(u.keyboard_opens), 0) AS keyboard
    FROM public.card_slide_usage u
    WHERE u.day >= (now() AT TIME ZONE 'utc')::date - v_days
  ),
  setting AS (
    SELECT
      COUNT(*) FILTER (WHERE s.card_slide) AS on_count,
      COUNT(*) FILTER (WHERE NOT s.card_slide) AS off_count
    FROM public.user_table_settings s
  )
  SELECT
    v_days,
    setting.on_count,
    setting.off_count,
    usage.active_users,
    usage.started,
    usage.committed,
    usage.abandoned,
    usage.keyboard,
    CASE WHEN usage.started > 0
      THEN ROUND((usage.committed::numeric / usage.started) * 100, 1)
      ELSE NULL
    END
  FROM usage, setting;
END $$;


ALTER FUNCTION public.fn_card_slide_adoption(p_days integer) OWNER TO postgres;

--
-- Name: fn_cash_apply_ruleset(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_apply_ruleset(p_game_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g record; s jsonb; v_opts jsonb;
  v_ante text; v_ante_chips numeric; v_vpip integer; v_vpip_window integer;
  v_bomb_on boolean; v_bomb_trigger text; v_bomb_ante integer; v_bomb_boards integer;
  v_min_bb integer; v_max_bb integer;
  v_trigger_mode text; v_interval integer; v_action_secs integer;
  v_n integer := 0;
BEGIN
  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id;
  IF NOT FOUND THEN RETURN 0; END IF;
  s := g.ruleset_snapshot;
  IF s IS NULL THEN RETURN 0; END IF;

  -- The same mapping fn_cash_cluster_open_table applies at open. Kept in
  -- one place by construction: the opener's INSERT and this UPDATE must read
  -- the snapshot identically or a fresh table and a reconciled one disagree.
  v_opts := coalesce(s->'options', '{}'::jsonb);
  v_ante := coalesce(s->>'regular_ante', 'none');
  v_ante_chips := CASE v_ante WHEN 'sb' THEN g.sb WHEN 'bb' THEN g.bb ELSE 0 END;
  v_vpip := coalesce((s->>'vpip_floor')::integer, 0);
  v_vpip_window := coalesce((s->>'vpip_window')::integer, 40);
  v_bomb_on := coalesce((s->'bombs'->>'enabled')::boolean, false);
  v_bomb_trigger := s->'bombs'->>'trigger';
  v_bomb_ante := (s->'bombs'->>'ante_bb')::integer;
  v_bomb_boards := (s->'bombs'->>'boards')::integer;
  v_min_bb := coalesce((s->>'min_buyin_bb')::integer, 40);
  v_max_bb := coalesce((s->>'max_buyin_bb')::integer, 200);
  v_trigger_mode := CASE WHEN v_bomb_on AND v_bomb_trigger = 'timed_15m' THEN 'timed'
                         WHEN v_bomb_on AND v_bomb_trigger = 'every_orbit' THEN 'once_per_orbit'
                         ELSE 'every_n_hands' END;
  v_interval := CASE WHEN v_bomb_on AND v_bomb_trigger = 'timed_15m' THEN 900 ELSE NULL END;
  v_action_secs := LEAST(120, GREATEST(10, coalesce((v_opts->>'action_time_seconds')::integer, 15)));

  UPDATE public.tables t
     SET ante_enabled = v_ante_chips > 0,
         ante = v_ante_chips,
         ante_bb = CASE WHEN v_ante_chips > 0 THEN round(v_ante_chips / g.bb, 4) ELSE 0 END,
         big_blind_ante_enabled = (v_ante = 'bb'),
         nit_game = v_vpip > 0,
         career_percent_min = 0,
         maintain_percent_min = v_vpip,
         maintain_hands = v_vpip_window,
         bomb_pot_enabled = v_bomb_on,
         bomb_pot_trigger_mode = v_trigger_mode,
         bomb_pot_interval_seconds = v_interval,
         bomb_pot_frequency = 0,
         bomb_pot_ante_multiplier = coalesce(v_bomb_ante, 2),
         bomb_pot_board_count = coalesce(v_bomb_boards, 1),
         bomb_pot_double_board = coalesce(v_bomb_boards, 1) >= 2,
         bomb_pot_min_players = 2,
         min_buy_in = round(g.bb * v_min_bb, 2),
         max_buy_in = round(g.bb * v_max_bb, 2),
         straddle_enabled = false, auto_utg_straddle = false, voluntary_straddle = false,
         is_private = coalesce((v_opts->>'is_private')::boolean, false),
         is_vip_only = coalesce((v_opts->>'is_vip_only')::boolean, false),
         is_anonymous = coalesce((v_opts->>'is_anonymous')::boolean, false),
         ban_chat = coalesce((v_opts->>'ban_chat')::boolean, false),
         insurance_enabled = coalesce((v_opts->>'insurance_enabled')::boolean, false),
         seven_deuce_enabled = coalesce((v_opts->>'seven_deuce_enabled')::boolean, false),
         seven_deuce_amount = CASE WHEN coalesce((v_opts->>'seven_deuce_enabled')::boolean, false) THEN 2 ELSE 0 END,
         action_time_seconds = v_action_secs,
         updated_at = now()
   WHERE t.cluster_id = g.id
     AND t.lifecycle <> 'closed'
     AND coalesce(t.is_deleted, false) = false
     AND (
          t.ante_enabled IS DISTINCT FROM (v_ante_chips > 0)
       OR t.ante IS DISTINCT FROM v_ante_chips
       OR t.big_blind_ante_enabled IS DISTINCT FROM (v_ante = 'bb')
       OR t.nit_game IS DISTINCT FROM (v_vpip > 0)
       OR t.maintain_percent_min IS DISTINCT FROM v_vpip
       OR t.maintain_hands IS DISTINCT FROM v_vpip_window
       OR t.bomb_pot_enabled IS DISTINCT FROM v_bomb_on
       OR t.bomb_pot_trigger_mode IS DISTINCT FROM v_trigger_mode
       OR t.bomb_pot_interval_seconds IS DISTINCT FROM v_interval
       OR t.bomb_pot_ante_multiplier IS DISTINCT FROM coalesce(v_bomb_ante, 2)
       OR t.bomb_pot_board_count IS DISTINCT FROM coalesce(v_bomb_boards, 1)
       OR t.bomb_pot_double_board IS DISTINCT FROM (coalesce(v_bomb_boards, 1) >= 2)
       OR t.min_buy_in IS DISTINCT FROM round(g.bb * v_min_bb, 2)
       OR t.max_buy_in IS DISTINCT FROM round(g.bb * v_max_bb, 2)
       OR coalesce(t.straddle_enabled, false) OR coalesce(t.auto_utg_straddle, false) OR coalesce(t.voluntary_straddle, false)
       OR t.is_private IS DISTINCT FROM coalesce((v_opts->>'is_private')::boolean, false)
       OR t.is_vip_only IS DISTINCT FROM coalesce((v_opts->>'is_vip_only')::boolean, false)
       OR t.is_anonymous IS DISTINCT FROM coalesce((v_opts->>'is_anonymous')::boolean, false)
       OR t.ban_chat IS DISTINCT FROM coalesce((v_opts->>'ban_chat')::boolean, false)
       OR t.insurance_enabled IS DISTINCT FROM coalesce((v_opts->>'insurance_enabled')::boolean, false)
       OR t.seven_deuce_enabled IS DISTINCT FROM coalesce((v_opts->>'seven_deuce_enabled')::boolean, false)
       OR t.action_time_seconds IS DISTINCT FROM v_action_secs
     );
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    INSERT INTO public.cash_cluster_events (game_id, kind, payload)
    VALUES (g.id, 'ruleset_applied',
            jsonb_build_object('tables', v_n, 'vpip_floor', v_vpip, 'vpip_window', v_vpip_window,
                               'ante', v_ante, 'bombs', v_bomb_on, 'bomb_trigger', v_trigger_mode));
  END IF;
  RETURN v_n;
END;
$$;


ALTER FUNCTION public.fn_cash_apply_ruleset(p_game_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_cluster_balance(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_balance(p_game_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_census public.cash_cluster_census_row[];
  v_planned integer := 0;
  v_from uuid;
  v_to uuid;
  v_player uuid;
BEGIN
  v_census := public.fn_cash_cluster_census(p_game_id, p_now);

  WITH pool AS (
    SELECT c.id,
           c.main_index,
           c.created_at,
           c.seated
             - (SELECT count(*) FROM public.cash_seat_moves m
                 WHERE m.from_table_id = c.id AND m.state = 'pending')
             + (SELECT count(*) FROM public.cash_seat_moves m
                 WHERE m.to_table_id = c.id AND m.state = 'pending') AS n,
           c.open_unreserved
             - (SELECT count(*) FROM public.cash_seat_moves m
                 WHERE m.to_table_id = c.id AND m.state = 'pending' AND m.swap_move_id IS NULL) AS room
      FROM unnest(v_census) c
     WHERE c.lifecycle = 'live'
       AND NOT c.breaking
       AND NOT (c.role = 'main' AND c.main_index = 1)
  ),
  hi AS (
    SELECT * FROM pool ORDER BY n DESC, main_index DESC NULLS FIRST, created_at DESC LIMIT 1
  ),
  lo AS (
    SELECT * FROM pool WHERE room > 0
     ORDER BY n ASC, main_index ASC NULLS LAST, created_at ASC LIMIT 1
  ),
  pair AS (
    SELECT hi.id AS from_id, lo.id AS to_id
      FROM hi, lo
     WHERE hi.id <> lo.id
       AND hi.n - lo.n >= 2
       AND hi.n >= 3
       AND lo.n >= 1
  ),
  mover AS (
    SELECT p.from_id, p.to_id, ts.user_id
      FROM pair p
      JOIN public.table_seats ts ON ts.table_id = p.from_id AND ts.left_at IS NULL
     WHERE ts.user_id IS NOT NULL
       AND coalesce(ts.stack, 0) > 0
       AND coalesce(ts.leave_pending, false) = false
       AND NOT EXISTS (SELECT 1 FROM public.table_seats d
                        WHERE d.table_id = p.to_id AND d.user_id = ts.user_id AND d.left_at IS NULL)
       AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m
                        WHERE m.player_id = ts.user_id AND m.state = 'pending')
       AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m
                        WHERE m.player_id = ts.user_id AND m.state = 'cancelled'
                          AND m.created_at > p_now - interval '60 seconds')
     ORDER BY coalesce((SELECT r.joined_at FROM public.cash_game_roster r
                         WHERE r.game_id = p_game_id AND r.user_id = ts.user_id AND r.left_at IS NULL),
                       ts.joined_at) DESC,
              ts.joined_at DESC
     LIMIT 1
  ),
  ins AS (
    INSERT INTO public.cash_seat_moves (game_id, player_id, from_table_id, to_table_id, reason)
    SELECT p_game_id, m.user_id, m.from_id, m.to_id, 'balance' FROM mover m
    RETURNING player_id, from_table_id, to_table_id
  )
  SELECT count(*)::integer,
         (array_agg(i.from_table_id))[1],
         (array_agg(i.to_table_id))[1],
         (array_agg(i.player_id))[1]
    INTO v_planned, v_from, v_to, v_player
    FROM ins i;

  IF coalesce(v_planned, 0) > 0 THEN
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
    VALUES (p_game_id, v_to, 'move_planned',
            jsonb_build_object('player_id', v_player, 'from_table_id', v_from, 'reason', 'balance'));
  END IF;

  RETURN coalesce(v_planned, 0);
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_balance(p_game_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_cash_cluster_balance(p_game_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_balance(p_game_id uuid, p_now timestamp with time zone) IS 'Plans at most one balancing move between the must-move tables of one cash cluster, keeping them within one player of each other (Dan 2026-09-05). Main 1 is fed and never balanced. Called once per game per pass from fn_cash_clusters_tick_all, after the tick.';


--
-- Name: fn_cash_cluster_census(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_census(p_game_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS public.cash_cluster_census_row[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(array_agg(
           (q.id, q.role, q.main_index, q.lifecycle, q.status, q.created_at, q.max_players,
            q.seated, q.reserved, GREATEST(0, q.max_players - q.seated - q.reserved),
            q.lifecycle = 'breaking')::public.cash_cluster_census_row
           ORDER BY q.created_at), '{}'::public.cash_cluster_census_row[])
    FROM (
      SELECT tb.id, tb.role, tb.main_index, tb.lifecycle, tb.status, tb.created_at,
             coalesce(tb.max_players, 9) AS max_players,
             (SELECT count(*) FROM public.table_seats ts WHERE ts.table_id = tb.id AND ts.left_at IS NULL)::integer AS seated,
             (SELECT count(*) FROM public.table_waitlist w
               WHERE w.table_id = tb.id AND w.status = 'notified' AND w.hold_expires_at > p_now)::integer AS reserved
        FROM public.tables tb
       WHERE tb.cluster_id = p_game_id AND coalesce(tb.is_deleted, false) = false
         AND tb.status IN ('waiting', 'running', 'active') AND tb.lifecycle <> 'closed'
    ) q;
$$;


ALTER FUNCTION public.fn_cash_cluster_census(p_game_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_cash_cluster_open_table(uuid, text, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_open_table(p_game_id uuid, p_role text, p_main_index integer, p_lifecycle text DEFAULT 'opening'::text, p_created_by uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g record; s jsonb; v_opts jsonb;
  v_ante text; v_ante_chips numeric; v_vpip integer; v_vpip_window integer;
  v_bomb_on boolean; v_bomb_trigger text; v_bomb_ante integer; v_bomb_boards integer;
  v_min_bb integer; v_max_bb integer; v_name text; v_table_id uuid; v_n integer;
BEGIN
  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND: %', p_game_id; END IF;
  IF p_role NOT IN ('main', 'feeder') THEN RAISE EXCEPTION 'ROLE_INVALID: %', p_role; END IF;
  IF p_role = 'main' AND (p_main_index IS NULL OR p_main_index < 1) THEN
    RAISE EXCEPTION 'MAIN_INDEX_INVALID: %', p_main_index;
  END IF;
  IF p_lifecycle NOT IN ('opening', 'live') THEN RAISE EXCEPTION 'LIFECYCLE_INVALID: %', p_lifecycle; END IF;

  s := g.ruleset_snapshot;
  v_opts := coalesce(s->'options', '{}'::jsonb);
  v_ante := coalesce(s->>'regular_ante', 'none');
  v_ante_chips := CASE v_ante WHEN 'sb' THEN g.sb WHEN 'bb' THEN g.bb ELSE 0 END;
  v_vpip := coalesce((s->>'vpip_floor')::integer, 0);
  v_vpip_window := coalesce((s->>'vpip_window')::integer, 40);
  v_bomb_on := coalesce((s->'bombs'->>'enabled')::boolean, false);
  v_bomb_trigger := s->'bombs'->>'trigger';
  v_bomb_ante := (s->'bombs'->>'ante_bb')::integer;
  v_bomb_boards := (s->'bombs'->>'boards')::integer;
  v_min_bb := coalesce((s->>'min_buyin_bb')::integer, 40);
  v_max_bb := coalesce((s->>'max_buyin_bb')::integer, 200);

  -- "NLH 1/2 Classic" for Main 1, "NLH 1/2 Classic Main 2", "... Feeder".
  SELECT count(*) INTO v_n FROM public.tables WHERE cluster_id = p_game_id;
  v_name := CASE
    WHEN p_role = 'main' AND p_main_index = 1 THEN g.name
    WHEN p_role = 'main' THEN left(g.name, 50) || ' Main ' || p_main_index
    ELSE left(g.name, 50) || ' Feeder' END;

  INSERT INTO public.tables (
    club_id, union_id, name, game_type, game_variant, game_mode,
    small_blind, big_blind, stakes,
    max_players, min_buy_in, max_buy_in,
    ante_enabled, ante, ante_bb, big_blind_ante_enabled,
    nit_game, career_percent_min, maintain_percent_min, maintain_hands,
    bomb_pot_enabled, bomb_pot_trigger_mode, bomb_pot_interval_seconds, bomb_pot_frequency,
    bomb_pot_ante_multiplier, bomb_pot_board_count, bomb_pot_double_board, bomb_pot_min_players,
    straddle_enabled, auto_utg_straddle, voluntary_straddle,
    run_it_mode, run_it_twice, allow_run_it_twice, run_it_twice_enabled,
    rake_percent, rake_cap_bb,
    is_private, is_vip_only, is_anonymous, ban_chat, insurance_enabled,
    seven_deuce_enabled, seven_deuce_amount,
    action_time_seconds, auto_start_players,
    auto_extension, auto_restart, auto_create_table,
    status, current_players, created_by,
    cluster_id, role, main_index, lifecycle, opened_at, live_at
  ) VALUES (
    g.club_id, g.union_id, v_name, 'cash', g.variant, 'regular',
    g.sb, g.bb, public.fn_cash_stakes_label(g.sb, g.bb, g.variant),
    g.handedness, round(g.bb * v_min_bb, 2), round(g.bb * v_max_bb, 2),
    -- BIG BLIND ANTE (2026-09-05): 'bb' is the format, not just the size -
    -- the big blind posts one ante for the table. 'sb' is the classic ante,
    -- a small blind from every seat.
    v_ante_chips > 0, v_ante_chips, CASE WHEN v_ante_chips > 0 THEN round(v_ante_chips / g.bb, 4) ELSE 0 END,
    (v_ante = 'bb'),
    v_vpip > 0, 0, v_vpip, v_vpip_window,
    v_bomb_on,
    CASE WHEN v_bomb_on AND v_bomb_trigger = 'timed_15m' THEN 'timed'
         WHEN v_bomb_on AND v_bomb_trigger = 'every_orbit' THEN 'once_per_orbit'
         ELSE 'every_n_hands' END,
    CASE WHEN v_bomb_on AND v_bomb_trigger = 'timed_15m' THEN 900 ELSE NULL END,
    0,
    coalesce(v_bomb_ante, 2), coalesce(v_bomb_boards, 1), coalesce(v_bomb_boards, 1) >= 2, 2,
    false, false, false,
    'player_choice', true, true, true,
    -1, -1,
    coalesce((v_opts->>'is_private')::boolean, false), coalesce((v_opts->>'is_vip_only')::boolean, false),
    coalesce((v_opts->>'is_anonymous')::boolean, false), coalesce((v_opts->>'ban_chat')::boolean, false),
    coalesce((v_opts->>'insurance_enabled')::boolean, false),
    coalesce((v_opts->>'seven_deuce_enabled')::boolean, false),
    CASE WHEN coalesce((v_opts->>'seven_deuce_enabled')::boolean, false) THEN 2 ELSE 0 END,
    LEAST(120, GREATEST(10, coalesce((v_opts->>'action_time_seconds')::integer, 15))), 2,
    -- A cluster table's life is the controller's (Slice 6). A manual (R9)
    -- table's life is the host's. Neither uses the lifecycle-pass flags.
    false, false, false,
    'waiting', 0, coalesce(p_created_by, g.created_by),
    p_game_id, p_role, CASE WHEN p_role = 'main' THEN p_main_index END, p_lifecycle,
    clock_timestamp(), CASE WHEN p_lifecycle = 'live' THEN clock_timestamp() END
  ) RETURNING id INTO v_table_id;

  INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
  VALUES (p_game_id, v_table_id, CASE WHEN p_role = 'feeder' THEN 'feeder_opened' ELSE 'main_opened' END,
          jsonb_build_object('role', p_role, 'main_index', p_main_index, 'lifecycle', p_lifecycle, 'name', v_name));
  RETURN v_table_id;
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_open_table(p_game_id uuid, p_role text, p_main_index integer, p_lifecycle text, p_created_by uuid) OWNER TO postgres;

--
-- Name: fn_cash_cluster_tick(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_tick(p_game_id uuid, p_eligible_horses integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g record; t record; r record;
  v_census public.cash_cluster_census_row[];
  v_actions jsonb := '[]'::jsonb;
  v_now timestamptz := clock_timestamp();
  v_seated_total integer := 0;
  v_live_tables integer := 0;
  v_open_unreserved integer := 0;
  v_buyers integer;
  v_waiting integer;
  v_prev_feeder record;
  v_candidate record;
  v_floor integer;
  v_remaining_capacity integer;
  v_remaining_tables integer;
  v_main1 record;
  v_new_state text;
  v_moves integer := 0;
  v_n integer;
  v_idx integer;
  v_shortest uuid;
  v_table_cap integer;
  v_res jsonb;
  v_hands integer;
  v_orbit integer;
  v_window interval;
BEGIN
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'skipped', 'frozen');
  END IF;

  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;
  IF NOT g.must_move THEN RETURN jsonb_build_object('ok', false, 'reason', 'manual_game'); END IF;

  -- ── 1. RECONCILE ─────────────────────────────────────────────────────────
  -- AN EXPIRED MOVE SAYS WHAT IT WAS WAITING FOR (2026-09-07). Three
  -- different failures land here and the row could not tell them apart.
  UPDATE public.cash_seat_moves m SET state = 'expired',
         note = CASE
                  WHEN NOT EXISTS (SELECT 1 FROM public.table_seats ts
                                    WHERE ts.table_id = m.from_table_id
                                      AND ts.user_id = m.player_id AND ts.left_at IS NULL)
                    THEN 'player_left_before_boundary'
                  WHEN EXISTS (SELECT 1 FROM public.table_seats ts
                                WHERE ts.table_id = m.from_table_id
                                  AND ts.user_id = m.player_id AND ts.left_at IS NULL
                                  AND coalesce(ts.stack, 0) = 0)
                    THEN 'player_busted_before_boundary'
                  ELSE 'engine_did_not_execute_before_expiry'
                END
   WHERE m.game_id = g.id AND m.state = 'pending' AND m.expires_at <= v_now;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_actions := v_actions || jsonb_build_object('moves_expired', v_n); END IF;

  -- THE SNAPSHOT IS THE RULE (Gate 5, 2026-09-05). Every open table of the
  -- game carries exactly the rules its snapshot says; a table that drifted
  -- (54 did, on the VPIP floor alone) is corrected here, every tick.
  v_n := public.fn_cash_apply_ruleset(g.id);
  IF v_n > 0 THEN v_actions := v_actions || jsonb_build_object('ruleset_applied', v_n); END IF;

  -- THE ROSTER AND THE SEAT-CHANGE LIST (Dan 2026-09-05). A roster row whose
  -- player holds no chair in the game and has no move planned is closed (the
  -- seat trigger closes most of them; this catches a chair that emptied
  -- while a move was pending and the move then died). A seat change whose
  -- move was cancelled or expired goes back on the list, at its old place;
  -- the back-off in the planner gives the refusal its minute.
  UPDATE public.cash_game_roster ro SET left_at = v_now
   WHERE ro.game_id = g.id AND ro.left_at IS NULL
     AND NOT EXISTS (SELECT 1 FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
                      WHERE ts.user_id = ro.user_id AND ts.left_at IS NULL AND tb.cluster_id = g.id AND tb.lifecycle <> 'closed')
     AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves mv WHERE mv.player_id = ro.user_id AND mv.game_id = g.id AND mv.state = 'pending');
  UPDATE public.cash_seat_change_requests rq SET status = 'cancelled', resolved_at = v_now, note = 'left_game'
   WHERE rq.game_id = g.id AND rq.status = 'requested'
     AND NOT EXISTS (SELECT 1 FROM public.cash_game_roster ro WHERE ro.game_id = g.id AND ro.user_id = rq.user_id AND ro.left_at IS NULL);
  UPDATE public.cash_seat_change_requests rq SET status = 'requested', resolved_at = NULL, move_id = NULL, note = 'move_' || mv.state
    FROM public.cash_seat_moves mv
   WHERE rq.game_id = g.id AND rq.status = 'moved' AND rq.move_id = mv.id AND mv.state IN ('cancelled', 'expired')
     AND EXISTS (SELECT 1 FROM public.table_seats ts WHERE ts.table_id = rq.from_table_id AND ts.user_id = rq.user_id AND ts.left_at IS NULL);

  -- THE GAME WAITLIST (Gate 4, 2026-09-05). A row whose player now holds a
  -- seat in the game is `seated`; a `notified` row (the join door told them
  -- a seat was open) that has not turned into a seat in three minutes is
  -- `expired` - their browser asks again if they are still there, and the
  -- OPEN rule stops counting a buyer who left.
  UPDATE public.cash_game_waitlist w SET status = 'seated', updated_at = v_now
   WHERE w.game_id = g.id AND w.status IN ('waiting', 'notified')
     AND EXISTS (SELECT 1 FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
                  WHERE ts.user_id = w.user_id AND ts.left_at IS NULL AND tb.cluster_id = g.id AND tb.lifecycle <> 'closed');
  UPDATE public.cash_game_waitlist w SET status = 'expired', updated_at = v_now
   WHERE w.game_id = g.id AND w.status = 'notified' AND w.updated_at < v_now - interval '3 minutes';

  -- A CLOSED TABLE WITH SOMEONE ON IT (2026-09-05). The census excludes
  -- closed tables, so a player who reached one (the seat guard below now
  -- refuses; this covers what got through before it, and any future hole)
  -- would never be planned out. It goes back to `breaking`, which the
  -- census sees and step 5 walks empty, then closes again.
  FOR t IN SELECT tb.id FROM public.tables tb
            WHERE tb.cluster_id = g.id AND tb.lifecycle = 'closed'
              AND coalesce(tb.is_deleted, false) = false
              AND EXISTS (SELECT 1 FROM public.table_seats ts WHERE ts.table_id = tb.id AND ts.left_at IS NULL)
  LOOP
    UPDATE public.tables SET lifecycle = 'breaking', status = 'running', break_started_at = v_now, updated_at = now()
     WHERE id = t.id;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, t.id, 'closed_table_reopened_to_break');
    v_actions := v_actions || jsonb_build_object('reopened_to_break', t.id);
  END LOOP;

  -- ONE CHAIR PER PLAYER PER GAME, EVERY TICK (2026-09-05). The door
  -- refuses a second chair now; before it did, the fleet seated the same
  -- horse at two tables of one game, and the tick only settled that on a
  -- BREAKING table (below). Found live: one horse on Main 1 since 17:01 and
  -- on the feeder since 19:17 the day before, both chairs idle. The roster
  -- is per player, so every such pair also read as one row of drift. The
  -- oldest chair is the player's; each newer one goes home through the
  -- same door as a Leave: between hands (table waiting) it is cashed out
  -- now, exactly as the breaking branch does; mid-game it is flagged
  -- leave_pending and the engine cashes it out at the hand boundary.
  FOR r IN
    SELECT ts.user_id, ts.table_id, ts.seat_number, ts.stack, tb.status,
           coalesce(ts.club_id, public.fn_player_home_club(ts.user_id, NULL)) AS club_id
      FROM public.table_seats ts
      JOIN public.tables tb ON tb.id = ts.table_id
     WHERE tb.cluster_id = g.id AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
       AND tb.lifecycle <> 'closed' AND coalesce(tb.is_deleted, false) = false
       AND coalesce(ts.leave_pending, false) = false
       AND EXISTS (SELECT 1 FROM public.table_seats o JOIN public.tables ot ON ot.id = o.table_id
                    WHERE o.user_id = ts.user_id AND o.left_at IS NULL AND o.table_id <> ts.table_id
                      AND ot.cluster_id = g.id AND ot.lifecycle <> 'closed'
                      AND (o.joined_at < ts.joined_at OR (o.joined_at = ts.joined_at AND o.id < ts.id)))
  LOOP
    IF r.status = 'waiting' AND coalesce(r.stack, 0) > 0 AND r.club_id IS NOT NULL THEN
      PERFORM public.fn_ensure_club_wallet(r.user_id, r.club_id);
      PERFORM public.fn_ca_declare_ledger('table_cashout', 'table_stack', r.table_id);
      v_res := public.atomic_seat_cashout_locked(r.user_id, r.table_id, r.seat_number, 'forced');
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (g.id, r.table_id, 'second_chair_cashed_out',
              jsonb_build_object('player_id', r.user_id, 'seat', r.seat_number, 'stack', r.stack, 'club_id', r.club_id,
                                 'credited', v_res->'credited', 'key', v_res->'idempotency_key', 'where', 'reconcile'));
      v_actions := v_actions || jsonb_build_object('second_chair_cashed_out', r.user_id);
    ELSE
      UPDATE public.table_seats SET leave_pending = true
       WHERE table_id = r.table_id AND user_id = r.user_id AND left_at IS NULL;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (g.id, r.table_id, 'second_chair_leave_pending',
              jsonb_build_object('player_id', r.user_id, 'seat', r.seat_number, 'stack', r.stack, 'table_status', r.status));
      v_actions := v_actions || jsonb_build_object('second_chair_leave_pending', r.user_id);
    END IF;
  END LOOP;

  -- AN OPENING FEEDER NOBODY CAME TO (2026-09-05, window raised the same
  -- night). It was opened for two buyers; SIX minutes with nobody on it
  -- means they went elsewhere. It closes, the live feeder it was going to
  -- promote stays the feeder, and OPEN below waits two minutes before
  -- trying again.
  --
  -- WHY SIX AND NOT THREE. The buyers are horses, and the fleet that seats
  -- them reads the open-table list ONCE at the top of a cycle that takes 57
  -- to 118 seconds (HorseFleetManager: "Seeding cycle took 118s and 3 30s
  -- tick(s) were dropped while it ran"), on a 30-second tick. Three minutes
  -- is shorter than one worst-case cycle plus a full tick interval, so a
  -- feeder could be closed before the fleet's next cycle ever reached it -
  -- and the fleet then bought into the closed row and was refused
  -- TABLE_CLOSING. Measured 2026-09-05 20:45 CDT: 22 feeder_opened, 4
  -- feeder_live, 20 feeder_abandoned in one hour; NLH 0.05/0.10 Classic
  -- abandoned 11 in 90 minutes. 118s + 30s is 148s, so six minutes is that
  -- with a full cycle of margin on top. The two-minute rest after an abandon
  -- and the 60-second opening hold are unchanged.
  FOR t IN SELECT tb.id FROM public.tables tb
            WHERE tb.cluster_id = g.id AND tb.lifecycle = 'opening'
              AND coalesce(tb.is_deleted, false) = false
              AND coalesce(tb.opened_at, tb.created_at) < v_now - interval '6 minutes'
              AND NOT EXISTS (SELECT 1 FROM public.table_seats ts WHERE ts.table_id = tb.id AND ts.left_at IS NULL)
  LOOP
    UPDATE public.tables SET status = 'closed', lifecycle = 'closed', current_players = 0, updated_at = now()
     WHERE id = t.id;
    UPDATE public.tables SET promote_pending = false
     WHERE cluster_id = g.id AND role = 'feeder' AND promote_pending;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, t.id, 'feeder_abandoned');
    v_actions := v_actions || jsonb_build_object('feeder_abandoned', t.id);
  END LOOP;

  -- A TABLE CLOSED BY STATUS BUT NOT BY LIFECYCLE (2026-09-05). Fifteen
  -- cluster tables carried status = 'closed' with lifecycle still 'live'
  -- (an operator's close-game action and the pre-controller close path
  -- write status only). The census reads status and drops them, the roles
  -- step reads lifecycle and still counts them, so a game could hold a
  -- Main 1 nobody could see and a feeder with nobody to feed. With no seat
  -- on it, the lifecycle follows the status; with a seat on it, the closed
  -- table sweep above has already put it back to breaking.
  UPDATE public.tables SET lifecycle = 'closed', current_players = 0, updated_at = now()
   WHERE cluster_id = g.id AND status = 'closed' AND lifecycle <> 'closed'
     AND coalesce(is_deleted, false) = false
     -- An enabled game's Main 1 is not followed down: R3 below repairs it in
     -- place (same id, same lobby links) instead of opening a replacement.
     AND NOT (g.enabled AND role = 'main' AND main_index = 1)
     AND NOT EXISTS (SELECT 1 FROM public.table_seats ts WHERE ts.table_id = public.tables.id AND ts.left_at IS NULL);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    INSERT INTO public.cash_cluster_events (game_id, kind, payload) VALUES (g.id, 'lifecycle_followed_status', jsonb_build_object('tables', v_n));
    v_actions := v_actions || jsonb_build_object('lifecycle_followed_status', v_n);
  END IF;

  -- THE HEADCOUNT COLUMN IS THE SEATS (2026-09-05, 15:05). tables.current_players
  -- is what every per-table surface paints and the engine writes it only
  -- when it loads seats to deal; a table with one seated player and no
  -- engine said 0 (22 of them live). The seats are the truth; the column
  -- follows them here, every tick, for this game's open tables.
  UPDATE public.tables tb SET current_players = s.n
    FROM (SELECT tx.id, (SELECT count(*) FROM public.table_seats ts WHERE ts.table_id = tx.id AND ts.left_at IS NULL)::integer AS n
            FROM public.tables tx WHERE tx.cluster_id = g.id AND tx.lifecycle <> 'closed' AND coalesce(tx.is_deleted, false) = false) s
   WHERE tb.id = s.id AND tb.current_players IS DISTINCT FROM s.n;

  v_census := public.fn_cash_cluster_census(g.id, v_now);
  SELECT coalesce(sum(c.seated), 0), count(*) INTO v_seated_total, v_live_tables FROM unnest(v_census) c;

  -- R3: an enabled game always has Main 1 open. Anything that closed it
  -- (a stray close, the pre-controller lifecycle pass, a restart) is undone
  -- here rather than by a row flag.
  --
  -- THE LOOKUP READS THE LIVE BOARD, NOT THE OLDEST ROW (2026-09-05, 14:45).
  -- This used to select the oldest table ever numbered Main 1, closed or not.
  -- On NLH 0.05/0.10 Classic the original Main 1 was closed for good, so
  -- every tick found a closed row, took the "open a new one" branch, and
  -- opened a fresh Main 1: 3,000 tables in 148 minutes (08:01 to 10:29),
  -- every one of them then broken and renumbered by the steps below, 10,989
  -- moves planned to shuffle 43 players through them. Now: a Main 1 that is
  -- live or opening on a waiting/running table is the game's; a game with
  -- ANY live table but no such Main 1 leaves it to the ROLES step, which
  -- promotes the oldest live table (that is what Main 1 means, 1.3 s9.2);
  -- only a game with no live table at all opens one. The status-only repair
  -- (a live-lifecycle Main 1 whose status got set to closed) stays.
  SELECT * INTO v_main1 FROM public.tables
   WHERE cluster_id = g.id AND role = 'main' AND main_index = 1 AND coalesce(is_deleted, false) = false
     AND lifecycle IN ('live', 'opening')
   ORDER BY created_at LIMIT 1;
  IF g.enabled AND v_main1.id IS NOT NULL AND v_main1.status NOT IN ('waiting', 'running', 'active') THEN
    UPDATE public.tables SET status = 'waiting', lifecycle = 'live', current_players = 0, updated_at = now()
     WHERE id = v_main1.id;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, v_main1.id, 'main1_reopened');
    v_actions := v_actions || jsonb_build_object('main1', 'reopened');
    v_census := public.fn_cash_cluster_census(g.id, v_now);
    SELECT coalesce(sum(c.seated), 0), count(*) INTO v_seated_total, v_live_tables FROM unnest(v_census) c;
  ELSIF g.enabled AND v_main1.id IS NULL
        AND NOT EXISTS (SELECT 1 FROM public.tables
                         WHERE cluster_id = g.id AND coalesce(is_deleted, false) = false
                           AND lifecycle IN ('live', 'opening', 'breaking') AND status IN ('waiting', 'running', 'active')) THEN
    PERFORM public.fn_cash_cluster_open_table(g.id, 'main', 1, 'live', NULL);
    v_actions := v_actions || jsonb_build_object('main1', 'opened');
    -- Recount after the repair; the rest of the tick sees the real board.
    v_census := public.fn_cash_cluster_census(g.id, v_now);
    SELECT coalesce(sum(c.seated), 0), count(*) INTO v_seated_total, v_live_tables FROM unnest(v_census) c;
  END IF;

  -- ── 2. MUST-MOVE (1.3 s9.5) ──────────────────────────────────────────────
  -- For every Main with an unreserved open seat, the longest-seated player on
  -- the feeder (or on a breaking table) is planned onto it, one per seat,
  -- one per player. The engine executes at the player's next hand boundary.
  FOR t IN SELECT * FROM unnest(v_census) c
            WHERE c.role = 'main' AND c.lifecycle = 'live' AND c.open_unreserved > 0
            ORDER BY c.main_index
  LOOP
    v_n := t.open_unreserved
         - (SELECT count(*) FROM public.cash_seat_moves m WHERE m.to_table_id = t.id AND m.state = 'pending' AND m.swap_move_id IS NULL);
    FOR r IN
      SELECT ts.user_id, ts.table_id
        FROM public.table_seats ts
        JOIN unnest(v_census) c ON c.id = ts.table_id
       WHERE ts.left_at IS NULL AND ts.user_id IS NOT NULL
         -- A Main 1 seat draws from the WHOLE list (every table but Main 1);
         -- a Main N seat draws from the feeder and any breaking table.
         AND (c.role = 'feeder' OR c.breaking OR (t.main_index = 1 AND c.id <> t.id))
         AND c.id <> t.id
         -- NOT WITH NOTHING, NOT WHILE LEAVING (2026-09-05): a busted seat is
         -- in its rebuy window, a leave_pending seat is on its way out.
         AND coalesce(ts.stack, 0) > 0
         AND coalesce(ts.leave_pending, false) = false
         -- Never onto a table they are already sitting at.
         AND NOT EXISTS (SELECT 1 FROM public.table_seats d WHERE d.table_id = t.id AND d.user_id = ts.user_id AND d.left_at IS NULL)
         AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m WHERE m.player_id = ts.user_id AND m.state = 'pending')
         -- BACK-OFF (2026-09-05): a move the engine just refused (cancelled
         -- with a note) is not re-planned every 5 s; the refusal gets a minute.
         AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m WHERE m.player_id = ts.user_id AND m.state = 'cancelled' AND m.created_at > v_now - interval '60 seconds')
       -- THE ORDER YOU JOINED THE GAME (Dan 2026-09-05): the roster's
       -- joined_at, which survives every move; the chair's own joined_at
       -- only for a chair that predates the roster.
       ORDER BY c.breaking DESC,
                coalesce((SELECT r2.joined_at FROM public.cash_game_roster r2
                           WHERE r2.game_id = g.id AND r2.user_id = ts.user_id AND r2.left_at IS NULL), ts.joined_at) ASC,
                ts.joined_at ASC
       LIMIT GREATEST(v_n, 0)
    LOOP
      INSERT INTO public.cash_seat_moves (game_id, player_id, from_table_id, to_table_id, reason)
      VALUES (g.id, r.user_id, r.table_id, t.id, 'must_move');
      v_moves := v_moves + 1;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (g.id, t.id, 'move_planned', jsonb_build_object('player_id', r.user_id, 'from_table_id', r.table_id, 'reason', 'must_move'));
    END LOOP;
  END LOOP;
  IF v_moves > 0 THEN v_actions := v_actions || jsonb_build_object('moves_planned', v_moves); END IF;

  -- ── 2b. SEAT CHANGES (Dan 2026-09-05) ────────────────────────────────────
  -- After Main seats are filled in must-move order and before a feeder is
  -- opened: a requested table change takes the next unreserved chair on a
  -- table that is not Main 1, oldest request first; two requests that would
  -- take each other's table are swapped.
  v_n := public.fn_cash_seat_change_plan(g.id, v_now);
  IF v_n > 0 THEN v_actions := v_actions || jsonb_build_object('seat_changes_planned', v_n); END IF;

  -- ── 3. OPEN (18.3) ───────────────────────────────────────────────────────
  SELECT coalesce(sum(c.open_unreserved), 0) INTO v_open_unreserved
    FROM unnest(v_census) c WHERE c.lifecycle IN ('live', 'opening') AND NOT c.breaking;
  SELECT count(*) INTO v_waiting FROM public.cash_game_waitlist w
   WHERE w.game_id = g.id AND w.status IN ('waiting', 'notified');
  v_buyers := v_waiting + GREATEST(coalesce(p_eligible_horses, 0), 0);
  -- (a CASE ... THEN inside an IF condition ends the condition early in
  --  PL/pgSQL, so the cap is computed first)
  v_table_cap := g.cap_mains + 1;
  IF g.allow_second_feeder THEN v_table_cap := v_table_cap + 1; END IF;

  IF g.enabled AND v_open_unreserved = 0 AND v_live_tables > 0
     AND NOT EXISTS (SELECT 1 FROM unnest(v_census) c WHERE c.lifecycle = 'opening')
     AND v_live_tables < v_table_cap
     -- Two minutes after a feeder was abandoned, not before.
     AND NOT EXISTS (SELECT 1 FROM public.cash_cluster_events e
                      WHERE e.game_id = g.id AND e.kind = 'feeder_abandoned' AND e.at > v_now - interval '2 minutes') THEN
    IF v_buyers >= 2 THEN
      UPDATE public.tables SET promote_pending = true
       WHERE cluster_id = g.id AND role = 'feeder' AND lifecycle = 'live';
      PERFORM public.fn_cash_cluster_open_table(g.id, 'feeder', NULL, 'opening', NULL);
      UPDATE public.cash_games SET opening_hold_since = NULL WHERE id = g.id;
      v_actions := v_actions || jsonb_build_object('feeder', 'opened', 'buyers', v_buyers);
    ELSIF v_buyers = 1 THEN
      -- One buyer holds for 60 s; the fleet's next cycle usually brings a
      -- partner. No ghost table.
      -- AN EXPIRED HOLD RESTS (2026-09-05): five minutes before the next.
      IF g.opening_hold_since IS NULL
         AND (g.opening_hold_rested_until IS NULL OR g.opening_hold_rested_until <= v_now) THEN
        UPDATE public.cash_games SET opening_hold_since = v_now WHERE id = g.id;
        INSERT INTO public.cash_cluster_events (game_id, kind) VALUES (g.id, 'table_opening_hold');
        v_actions := v_actions || jsonb_build_object('opening_hold', 'started');
      ELSIF g.opening_hold_since IS NOT NULL AND g.opening_hold_since < v_now - interval '60 seconds' THEN
        UPDATE public.cash_games SET opening_hold_since = NULL, opening_hold_rested_until = v_now + interval '5 minutes' WHERE id = g.id;
        INSERT INTO public.cash_cluster_events (game_id, kind) VALUES (g.id, 'table_opening_hold_expired');
        v_actions := v_actions || jsonb_build_object('opening_hold', 'expired');
      END IF;
    END IF;
  ELSIF g.opening_hold_since IS NOT NULL THEN
    UPDATE public.cash_games SET opening_hold_since = NULL WHERE id = g.id;
  END IF;

  -- ── 4. PROMOTE (18.3) ────────────────────────────────────────────────────
  -- An opening feeder with two seated is live. The feeder before it, marked
  -- promote_pending, becomes Main N+1.
  FOR t IN SELECT * FROM unnest(v_census) c WHERE c.lifecycle = 'opening' AND c.seated >= 2 LOOP
    UPDATE public.tables SET lifecycle = 'live', live_at = v_now WHERE id = t.id;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, t.id, 'feeder_live');
    SELECT coalesce(max(main_index), 0) + 1 INTO v_idx FROM public.tables
     WHERE cluster_id = g.id AND role = 'main' AND lifecycle <> 'closed' AND coalesce(is_deleted, false) = false;
    FOR v_prev_feeder IN SELECT id, name FROM public.tables
                          WHERE cluster_id = g.id AND role = 'feeder' AND promote_pending AND id <> t.id
                            AND lifecycle = 'live' ORDER BY created_at
    LOOP
      UPDATE public.tables SET role = 'main', main_index = v_idx, promote_pending = false,
             name = left(g.name, 50) || ' Main ' || v_idx
       WHERE id = v_prev_feeder.id;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (g.id, v_prev_feeder.id, 'feeder_promoted_to_main', jsonb_build_object('main_index', v_idx));
      v_idx := v_idx + 1;
    END LOOP;
    v_actions := v_actions || jsonb_build_object('feeder_live', t.id);
  END LOOP;

  -- Refresh the census for the steps that read roles (the counts are the
  -- tick's own snapshot and stay).
  SELECT coalesce(array_agg(
           (tb.id, tb.role, tb.main_index, tb.lifecycle, c.status, c.created_at, c.max_players,
            c.seated, c.reserved, c.open_unreserved, c.breaking)::public.cash_cluster_census_row
           ORDER BY c.created_at), '{}'::public.cash_cluster_census_row[])
    INTO v_census
    FROM unnest(v_census) c JOIN public.tables tb ON tb.id = c.id;

  -- ── 5. BREAK (18.3) ──────────────────────────────────────────────────────
  -- Candidate: newest table first (feeder, then the highest main), never
  -- Main 1, never a table still opening. Condition: everyone fits in the
  -- rest at or above the floor. It breaks when that has held for the
  -- SHORTER of two completed orbits on the candidate or five minutes
  -- (OPORD 1.4 18.3). An orbit is one hand per seated player; a table
  -- with fewer than two seated deals no hands, so only the clock runs
  -- for it. Until 2026-09-05 only the clock ran for everyone, and a
  -- six-handed feeder that dealt twenty hands in four minutes with the
  -- whole game fitting elsewhere still sat there for the fifth.
  v_floor := CASE WHEN g.handedness <= 6 THEN 3 ELSE 4 END;
  -- EMPTY FIRST (2026-09-05, 14:50). An empty table has nobody to move and
  -- nothing to interrupt; it is the cheapest table to close and the one the
  -- lobby least wants to see. Then the newest.
  SELECT * INTO v_candidate FROM unnest(v_census) c
   WHERE NOT (c.role = 'main' AND c.main_index = 1) AND c.lifecycle = 'live'
   ORDER BY (c.seated = 0) DESC, (c.role = 'feeder') DESC, c.main_index DESC NULLS FIRST, c.created_at DESC LIMIT 1;

  IF NOT EXISTS (SELECT 1 FROM unnest(v_census) c WHERE c.breaking) AND v_candidate.id IS NOT NULL THEN
    SELECT coalesce(sum(c.max_players - c.reserved), 0), count(*) INTO v_remaining_capacity, v_remaining_tables
      FROM unnest(v_census) c WHERE c.id <> v_candidate.id AND c.lifecycle = 'live';
    -- THE FLOOR CLAUSE IS GONE (2026-09-05, 14:50). It read
    -- `seated_total >= floor x remaining_tables`: break only if the
    -- rest would average at or above the maintain floor afterwards. Breaking
    -- a table never makes the rest SHORTER, so the clause could only ever
    -- refuse the breaks that matter most: a game of 1 player on 4 tables
    -- (1 >= 3 x 3, never) kept all four for ever, and a game of 42 on 16
    -- (42 >= 4 x 15, never) never armed. Read live at 14:45: eligible_since
    -- NULL on every table of both. Dan's rule is "fewer tables, more players
    -- at each"; the floor is a target for the fleet to fill to, not a bar
    -- to consolidation. The STRICT fit stays (everyone fits AND the rest
    -- keeps a seat open, so the OPEN rule does not fire on the same board).
    IF v_remaining_tables >= 1
       AND v_seated_total < v_remaining_capacity THEN
      SELECT break_eligible_since INTO r FROM public.tables WHERE id = v_candidate.id;
      IF r.break_eligible_since IS NULL THEN
        UPDATE public.tables SET break_eligible_since = v_now WHERE id = v_candidate.id;
        v_actions := v_actions || jsonb_build_object('break_eligible', v_candidate.id);
      ELSE
        v_orbit := v_candidate.seated;
        v_hands := 0;
        IF v_orbit >= 2 THEN
          SELECT count(*) INTO v_hands FROM public.hand_history h
           WHERE h.table_id = v_candidate.id AND h.created_at >= r.break_eligible_since;
        END IF;
        -- A TABLE WITH NOBODY, OR ONE PLAYER, HAS NOTHING TO INTERRUPT
        -- (2026-09-05): no hand can be dealt there, so the five-minute
        -- window protects nobody. Sixty seconds is enough to let someone who
        -- is sitting down finish sitting down.
        -- (computed first: a CASE ... THEN inside an IF condition ends the
        --  condition early in PL/pgSQL, see the OPEN rule's cap above)
        v_window := CASE WHEN v_orbit <= 1 THEN interval '60 seconds' ELSE interval '5 minutes' END;
        IF r.break_eligible_since <= v_now - v_window
           OR (v_orbit >= 2 AND v_hands >= 2 * v_orbit) THEN
          UPDATE public.tables SET lifecycle = 'breaking', break_started_at = v_now, break_eligible_since = NULL
           WHERE id = v_candidate.id;
          SELECT coalesce(array_agg(
                   (c.id, c.role, c.main_index,
                    CASE WHEN c.id = v_candidate.id THEN 'breaking' ELSE c.lifecycle END,
                    c.status, c.created_at, c.max_players, c.seated, c.reserved, c.open_unreserved,
                    c.breaking OR c.id = v_candidate.id)::public.cash_cluster_census_row
                   ORDER BY c.created_at), '{}'::public.cash_cluster_census_row[])
            INTO v_census FROM unnest(v_census) c;
          INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
          VALUES (g.id, v_candidate.id, 'table_break_started',
                  jsonb_build_object('seated_total', v_seated_total, 'remaining_capacity', v_remaining_capacity,
                                     'eligible_since', r.break_eligible_since, 'hands_since_eligible', v_hands, 'orbit', v_orbit));
          v_actions := v_actions || jsonb_build_object('break_started', v_candidate.id,
                                                       'hands_since_eligible', v_hands, 'orbit', v_orbit);
        END IF;
      END IF;
    ELSE
      UPDATE public.tables SET break_eligible_since = NULL
       WHERE cluster_id = g.id AND break_eligible_since IS NOT NULL;
    END IF;
  ELSE
    UPDATE public.tables SET break_eligible_since = NULL
     WHERE cluster_id = g.id AND break_eligible_since IS NOT NULL;
  END IF;

  -- A breaking table: every seated player is planned onto the shortest live
  -- table with room (must-move already took the mains' open seats above;
  -- this covers what is left, feeder included). When the last chair is
  -- empty it closes.
  FOR t IN SELECT * FROM unnest(v_census) c WHERE c.breaking LOOP
    IF t.seated = 0 THEN
      UPDATE public.tables SET status = 'closed', lifecycle = 'closed', current_players = 0, updated_at = now()
       WHERE id = t.id;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, t.id, 'table_break_completed');
      SELECT coalesce(array_agg(c ORDER BY c.created_at), '{}'::public.cash_cluster_census_row[])
        INTO v_census FROM unnest(v_census) c WHERE c.id <> t.id;
      v_actions := v_actions || jsonb_build_object('closed', t.id);
      CONTINUE;
    END IF;
    -- A SECOND CHAIR IN ONE GAME (2026-09-05). Before the door refused it, the
    -- fleet could seat the same horse at two tables of one game; found live
    -- with one of the two chairs on this breaking table. There is nowhere to
    -- move that chair to (they are already at the other table), so it goes
    -- home: the stack returns to the wallet through the forced cash-out the
    -- table-close path uses. Nothing is lost; the other chair is untouched.
    FOR r IN SELECT ts.user_id, ts.seat_number, ts.stack,
                    coalesce(ts.club_id, public.fn_player_home_club(ts.user_id, NULL)) AS club_id
               FROM public.table_seats ts
              WHERE ts.table_id = t.id AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
                AND coalesce(ts.stack, 0) > 0
                AND EXISTS (SELECT 1 FROM public.table_seats o JOIN public.tables ot ON ot.id = o.table_id
                             WHERE o.user_id = ts.user_id AND o.left_at IS NULL AND o.table_id <> t.id
                               AND ot.cluster_id = g.id AND ot.lifecycle IN ('live', 'opening'))
    LOOP
      CONTINUE WHEN r.club_id IS NULL;
      -- The same three calls fn_cashout_seats_for_closing_table makes, per seat.
      PERFORM public.fn_ensure_club_wallet(r.user_id, r.club_id);
      PERFORM public.fn_ca_declare_ledger('table_cashout', 'table_stack', t.id);
      v_res := public.atomic_seat_cashout_locked(r.user_id, t.id, r.seat_number, 'forced');
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (g.id, t.id, 'second_chair_cashed_out',
              jsonb_build_object('player_id', r.user_id, 'seat', r.seat_number, 'stack', r.stack,
                                 'club_id', r.club_id, 'credited', v_res->'credited', 'key', v_res->'idempotency_key'));
      v_actions := v_actions || jsonb_build_object('second_chair_cashed_out', r.user_id);
    END LOOP;
    FOR r IN SELECT ts.user_id FROM public.table_seats ts
              WHERE ts.table_id = t.id AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
                AND coalesce(ts.stack, 0) > 0
                AND coalesce(ts.leave_pending, false) = false
                AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m WHERE m.player_id = ts.user_id AND m.state = 'pending')
                AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m WHERE m.player_id = ts.user_id AND m.state = 'cancelled' AND m.created_at > v_now - interval '60 seconds')
              ORDER BY coalesce((SELECT r2.joined_at FROM public.cash_game_roster r2
                                  WHERE r2.game_id = g.id AND r2.user_id = ts.user_id AND r2.left_at IS NULL), ts.joined_at),
                       ts.joined_at
    LOOP
      SELECT c.id INTO v_shortest FROM unnest(v_census) c
       WHERE c.id <> t.id AND NOT c.breaking AND c.lifecycle IN ('live', 'opening')
         AND c.open_unreserved - (SELECT count(*) FROM public.cash_seat_moves m WHERE m.to_table_id = c.id AND m.state = 'pending' AND m.swap_move_id IS NULL) > 0
         AND NOT EXISTS (SELECT 1 FROM public.table_seats d WHERE d.table_id = c.id AND d.user_id = r.user_id AND d.left_at IS NULL)
       ORDER BY c.seated ASC, c.main_index ASC NULLS LAST LIMIT 1;
      EXIT WHEN v_shortest IS NULL;
      INSERT INTO public.cash_seat_moves (game_id, player_id, from_table_id, to_table_id, reason)
      VALUES (g.id, r.user_id, t.id, v_shortest, 'break');
      v_moves := v_moves + 1;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (g.id, v_shortest, 'move_planned', jsonb_build_object('player_id', r.user_id, 'from_table_id', t.id, 'reason', 'break'));
    END LOOP;
  END LOOP;

  -- ── 6. ROLES (1.3 s9.2) ──────────────────────────────────────────────────
  -- Oldest live table is Main 1; mains renumber by age; with no feeder left
  -- and two or more tables, the newest becomes the feeder.
  -- A GAME WITH A FEEDER AND NO MAIN (2026-09-05). Found live: Main 1 closed
  -- by status under a disabled game, five players still on its feeder, and
  -- nothing below promoted the feeder because this step only renumbers
  -- mains. Oldest live table is Main 1 (1.3 s9.2); if no main is live, the
  -- oldest live feeder becomes it, so the players on it have a Main to be
  -- on and the R3 repair does not open a second table beside them.
  IF NOT EXISTS (SELECT 1 FROM unnest(v_census) c WHERE c.lifecycle IN ('live', 'opening') AND c.role = 'main')
     AND EXISTS (SELECT 1 FROM unnest(v_census) c WHERE c.lifecycle = 'live' AND c.role = 'feeder') THEN
    SELECT * INTO t FROM unnest(v_census) c WHERE c.lifecycle = 'live' AND c.role = 'feeder' ORDER BY c.created_at LIMIT 1;
    UPDATE public.tables SET role = 'main', main_index = 1, promote_pending = false, name = g.name WHERE id = t.id;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
    VALUES (g.id, t.id, 'feeder_promoted_to_main', jsonb_build_object('main_index', 1, 'reason', 'no_live_main'));
    SELECT coalesce(array_agg(
             (c.id, CASE WHEN c.id = t.id THEN 'main' ELSE c.role END, CASE WHEN c.id = t.id THEN 1 ELSE c.main_index END,
              c.lifecycle, c.status, c.created_at, c.max_players, c.seated, c.reserved, c.open_unreserved, c.breaking)::public.cash_cluster_census_row
             ORDER BY c.created_at), '{}'::public.cash_cluster_census_row[])
      INTO v_census FROM unnest(v_census) c;
    v_actions := v_actions || jsonb_build_object('feeder_became_main1', t.id);
  END IF;
  v_idx := 0;
  FOR t IN SELECT * FROM unnest(v_census) c WHERE c.lifecycle IN ('live', 'opening') AND c.role = 'main' ORDER BY c.created_at LOOP
    v_idx := v_idx + 1;
    IF t.main_index IS DISTINCT FROM v_idx THEN
      UPDATE public.tables SET main_index = v_idx,
             name = CASE WHEN v_idx = 1 THEN g.name ELSE left(g.name, 50) || ' Main ' || v_idx END
       WHERE id = t.id;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (g.id, t.id, 'main_renumbered', jsonb_build_object('from', t.main_index, 'to', v_idx));
    END IF;
  END LOOP;
  IF v_idx >= 2 AND NOT EXISTS (SELECT 1 FROM unnest(v_census) c WHERE c.role = 'feeder' AND c.lifecycle IN ('live', 'opening')) THEN
    SELECT * INTO t FROM unnest(v_census) c WHERE c.role = 'main' AND c.lifecycle = 'live' ORDER BY c.created_at DESC LIMIT 1;
    UPDATE public.tables SET role = 'feeder', main_index = NULL, promote_pending = false,
           name = left(g.name, 50) || ' Feeder'
     WHERE id = t.id;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, t.id, 'main_demoted_to_feeder');
    v_actions := v_actions || jsonb_build_object('demoted', t.id);
  END IF;

  -- ── enabled = false (18.4): no seeding, no opening; empties close ─────────
  IF NOT g.enabled THEN
    FOR t IN SELECT * FROM unnest(v_census) c WHERE c.seated = 0 LOOP
      UPDATE public.tables SET status = 'closed', lifecycle = 'closed', current_players = 0, updated_at = now() WHERE id = t.id;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, t.id, 'table_closed_disabled');
      v_actions := v_actions || jsonb_build_object('closed_disabled', t.id);
    END LOOP;
  END IF;

  -- ── 7. WAKE / SLEEP (18.4) ───────────────────────────────────────────────
  v_new_state := CASE WHEN v_seated_total = 0 AND coalesce(p_eligible_horses, 0) = 0 THEN 'dormant' ELSE 'live' END;
  -- NOT gated on g.enabled (2026-09-07). `enabled` says whether this game
  -- may OPEN tables; it has nothing to do with whether `state` is true. Three
  -- games sat at 'live' with no tables and nobody in them for 38 hours
  -- because a disabled game could never be corrected, and once its last table
  -- closed fn_cash_clusters_to_tick stopped admitting it at all.
  IF g.state IS DISTINCT FROM v_new_state THEN
    UPDATE public.cash_games SET state = v_new_state, updated_at = now() WHERE id = g.id;
    INSERT INTO public.cash_cluster_events (game_id, kind, payload)
    VALUES (g.id, CASE WHEN v_new_state = 'live' THEN 'game_woken' ELSE 'game_dormant' END,
            jsonb_build_object('seated_total', v_seated_total, 'eligible_horses', p_eligible_horses));
    v_actions := v_actions || jsonb_build_object('state', v_new_state);
  END IF;

  UPDATE public.cash_games SET last_tick_at = v_now, last_tick_actions = v_actions WHERE id = g.id;

  RETURN jsonb_build_object('ok', true, 'game_id', g.id, 'seated_total', v_seated_total,
                            'tables', v_live_tables, 'buyers', v_buyers, 'actions', v_actions);
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_tick(p_game_id uuid, p_eligible_horses integer) OWNER TO postgres;

--
-- Name: fn_cash_clusters_tick_all(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_clusters_tick_all(p_eligible jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  w record;
  v_now timestamptz := clock_timestamp();
  v_games integer := 0;
  v_ticked integer := 0;
  v_errors integer := 0;
  v_rested integer := 0;
  v_balanced integer := 0;
  v_bal integer;
  v_eligible integer;
  v_res jsonb;
  v_results jsonb := '[]'::jsonb;
  v_rested_games jsonb := '[]'::jsonb;
  v_sqlstate text;
  v_message text;
  -- A PASS COMMITS WHAT IT DID (2026-09-06). See the header of migration
  -- 20260906150956. The engine's role has an 8-second statement_timeout, and
  -- a pass that crosses it is rolled back WHOLE: every game it ticked is
  -- un-ticked and the 8 seconds are gone. Measured 2026-09-06: mean 1,187 ms,
  -- max 7,993 ms, 9 whole-pass timeouts in three hours, while a pass over all
  -- 108 games in isolation is ~3.3 s (avg 25 ms a game, worst 675 ms) - the
  -- overrun is waiting, not work. So: the pass stops STARTING games at
  -- v_budget and hands the rest to the next pass (they are ordered oldest-
  -- ticked first, so nothing starves), and a single lock wait is bounded by
  -- v_lock_wait so one held row costs one game its tick, not the pass.
  v_budget interval := interval '5500 milliseconds';
  v_lock_wait text := '2000ms';
  v_deferred integer := 0;
  v_deferred_games jsonb := '[]'::jsonb;
BEGIN
  -- Transaction-local, so it dies with the RPC. lock_timeout is checked at
  -- every lock acquisition, so unlike statement_timeout it can be set from
  -- inside the statement it governs. A game whose tick waits longer than this
  -- raises 55P03 inside its own sub-block below and becomes an error row.
  PERFORM set_config('lock_timeout', v_lock_wait, true);

  -- THE FREEZE (CLAUDE.md 13): the same short-circuit the per-game tick has,
  -- taken once for the pass so a frozen platform costs one row read.
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'skipped', 'frozen',
                              'games', 0, 'ticked', 0, 'errors', 0, 'rested', 0,
                              'balanced', 0,
                              'results', '[]'::jsonb, 'rested_games', '[]'::jsonb);
  END IF;

  FOR w IN
    SELECT l.game_id, l.club_id, l.main1_table_id, l.state, l.enabled,
           g.last_tick_at,
           coalesce((p_eligible ->> (l.main1_table_id::text))::integer, 0) AS eligible,
           EXISTS (
             SELECT 1
               FROM public.tables t
               JOIN public.table_seats ts ON ts.table_id = t.id AND ts.left_at IS NULL
              WHERE t.cluster_id = l.game_id
                AND t.lifecycle <> 'closed'
           ) AS anyone_seated
      FROM public.fn_cash_clusters_to_tick() l
      JOIN public.cash_games g ON g.id = l.game_id
     -- Oldest-ticked first (2026-09-06; it was created_at). With a budget
     -- that can defer the tail of the list, creation order would defer the
     -- SAME games every pass. A game deferred now is the oldest next pass.
     ORDER BY g.last_tick_at NULLS FIRST, g.created_at
  LOOP
    v_games := v_games + 1;


    -- DUE? Live, disabled, occupied or wanted: every pass. Otherwise every 30 s.
    IF NOT (
         w.state = 'live'
      OR NOT w.enabled
      OR w.anyone_seated
      OR w.eligible > 0
      OR w.last_tick_at IS NULL
      OR w.last_tick_at < v_now - interval '30 seconds'
    ) THEN
      v_rested := v_rested + 1;
      -- A RESTED GAME STILL ANSWERS "WHO ARE YOU" (2026-09-05). The controller
      -- builds its per-game row map from what this pass returns, and a wake on
      -- a game absent from that map cannot read `enabled` or find Main 1 - so
      -- the 18.4 dealer wake was skipped for precisely the dormant game a wake
      -- is for. Identity only; no result, because it was not ticked.
      v_rested_games := v_rested_games || jsonb_build_object(
        'game_id', w.game_id,
        'main1_table_id', w.main1_table_id,
        'enabled', w.enabled,
        'state', w.state
      );
      CONTINUE;
    END IF;

    -- THE BUDGET. Checked after the rest test and before a game STARTS, so
    -- a resting game is still counted as rested and `deferred` means DUE but
    -- not started; a game already ticking finishes. Deferred games answer
    -- "who are you" exactly as rested games do, so the controller's row map
    -- still knows them and a wake finds Main 1. Their last_tick_at is
    -- untouched, which is what puts them first next pass.
    IF clock_timestamp() - v_now > v_budget THEN
      v_deferred := v_deferred + 1;
      v_deferred_games := v_deferred_games || jsonb_build_object(
        'game_id', w.game_id,
        'main1_table_id', w.main1_table_id,
        'enabled', w.enabled,
        'state', w.state
      );
      CONTINUE;
    END IF;

    v_eligible := w.eligible;
    BEGIN
      v_res := public.fn_cash_cluster_tick(w.game_id, v_eligible);
      v_ticked := v_ticked + 1;
      -- THE TABLES STAY WITHIN ONE PLAYER (Dan 2026-09-05). After the tick,
      -- never before it: the must-move step has just filled the main game's
      -- open seats from the list, and balancing against the board as it was
      -- BEFORE that would move players the tick was about to move anyway.
      v_bal := public.fn_cash_cluster_balance(w.game_id, v_now);
      v_balanced := v_balanced + coalesce(v_bal, 0);
      v_results := v_results || jsonb_build_object(
        'game_id', w.game_id,
        'main1_table_id', w.main1_table_id,
        'enabled', w.enabled,
        'state', w.state,
        'balanced', coalesce(v_bal, 0),
        'result', coalesce(v_res, '{}'::jsonb)
      );
    EXCEPTION WHEN OTHERS THEN
      -- The sub-block rolled this game's tick back; the pass goes on. The
      -- error is a row, not a log line, so the next agent can find it.
      GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      v_errors := v_errors + 1;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (w.game_id, w.main1_table_id, 'controller_tick_error',
              jsonb_build_object('sqlstate', v_sqlstate, 'message', v_message,
                                 'eligible_horses', v_eligible));
      v_results := v_results || jsonb_build_object(
        'game_id', w.game_id,
        'main1_table_id', w.main1_table_id,
        'enabled', w.enabled,
        'state', w.state,
        'error', jsonb_build_object('sqlstate', v_sqlstate, 'message', v_message)
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'games', v_games,
    'ticked', v_ticked,
    'errors', v_errors,
    'rested', v_rested,
    'deferred', v_deferred,
    'balanced', v_balanced,
    'elapsed_ms', round(extract(epoch from (clock_timestamp() - v_now)) * 1000),
    'results', v_results,
    -- Deferred games ride with the rested ones: identity rows, so the
    -- controller's map is complete without a new shape to parse.
    'rested_games', v_rested_games || v_deferred_games
  );
END;
$$;


ALTER FUNCTION public.fn_cash_clusters_tick_all(p_eligible jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_cash_clusters_tick_all(p_eligible jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_clusters_tick_all(p_eligible jsonb) IS 'One cluster-controller pass in one call (OPORD 1.4 s18.2). p_eligible is {main1_table_id: eligible_horses}. Live, disabled, occupied or horse-wanted games tick every pass; a dormant empty game every 30 s. Per-game errors are caught and written to cash_cluster_events as controller_tick_error.';


--
-- Name: fn_cash_clusters_to_tick(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_clusters_to_tick() RETURNS TABLE(game_id uuid, club_id uuid, main1_table_id uuid, state text, enabled boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT g.id, g.club_id,
         (SELECT t.id FROM public.tables t WHERE t.cluster_id = g.id AND t.role = 'main' AND t.main_index = 1
            AND t.lifecycle <> 'closed' AND coalesce(t.is_deleted, false) = false ORDER BY t.created_at LIMIT 1),
         g.state, g.enabled
    FROM public.cash_games g
   WHERE g.must_move
     -- A DISABLED GAME IS ADMITTED ON LIFECYCLE ALONE (2026-09-05). This used
     -- to require status IN ('waiting','running','active') as well, and a
     -- table stranded at lifecycle='live' with status='closed' satisfies the
     -- lifecycle test and fails the status one - which is the exact shape
     -- `lifecycle_followed_status` was written to repair. Fourteen games sat
     -- that way, never ticked once.
     AND (g.enabled OR EXISTS (SELECT 1 FROM public.tables t
                                WHERE t.cluster_id = g.id
                                  AND t.lifecycle <> 'closed'
                                  AND coalesce(t.is_deleted, false) = false))
   ORDER BY g.created_at;
$$;


ALTER FUNCTION public.fn_cash_clusters_to_tick() OWNER TO postgres;

--
-- Name: fn_cash_effective_buyin(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_effective_buyin(p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_min numeric; v_max numeric; v_bb numeric; v_floor numeric; v_eff numeric;
  v_barred_secs integer;
BEGIN
  SELECT t.min_buy_in, t.max_buy_in, t.big_blind INTO v_min, v_max, v_bb
    FROM public.tables t WHERE t.id = p_table_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;
  IF COALESCE(v_min, 0) <= 0 THEN v_min := COALESCE(v_bb, 0) * 40; END IF;
  IF COALESCE(v_max, 0) <= 0 THEN v_max := COALESCE(v_bb, 0) * 200; END IF;
  v_eff := v_min;
  IF v_uid IS NOT NULL THEN
    BEGIN
      v_floor := public.fn_cash_rejoin_floor(v_uid, p_table_id);
    EXCEPTION WHEN check_violation THEN
      IF SQLERRM LIKE 'VPIP_BARRED:%' THEN
        v_barred_secs := nullif(regexp_replace(SQLERRM, '^VPIP_BARRED:', ''), '')::integer;
      ELSE
        RAISE;
      END IF;
    END;
    IF v_floor IS NOT NULL THEN
      v_eff := GREATEST(v_min, v_floor);
      IF v_max > 0 THEN v_eff := LEAST(v_eff, v_max); END IF;
    END IF;
  END IF;
  RETURN jsonb_build_object('ok', true, 'min', v_eff, 'max', v_max,
                            'table_min', v_min, 'floor_applied', v_floor IS NOT NULL AND v_eff > v_min,
                            'barred_seconds', v_barred_secs);
END;
$$;


ALTER FUNCTION public.fn_cash_effective_buyin(p_table_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_game_barred_seconds(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_barred_seconds(p_game_id uuid, p_user_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT ceil(extract(epoch FROM (max(c.barred_until) - now())))::integer
    FROM public.cash_games g
    JOIN public.cash_rejoin_constraints c
      ON c.player_id = p_user_id AND c.club_id = g.club_id AND c.variant = g.variant
     AND c.sb = g.sb AND c.bb = g.bb AND c.barred_until > now()
   WHERE g.id = p_game_id
  HAVING max(c.barred_until) IS NOT NULL;
$$;


ALTER FUNCTION public.fn_cash_game_barred_seconds(p_game_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_game_create(uuid, text, text, numeric, numeric, integer, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_create(p_club_id uuid, p_template text, p_variant text, p_sb numeric, p_bb numeric, p_handedness integer DEFAULT NULL::integer, p_overrides jsonb DEFAULT '{}'::jsonb, p_name text DEFAULT NULL::text, p_must_move boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_cash_game_create requires an authenticated caller'
      USING ERRCODE = '28000';
  END IF;
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'SESSION_REVOKED: this session is signed out - sign in again'
      USING ERRCODE = '28000';
  END IF;
  IF p_club_id IS NULL THEN
    RAISE EXCEPTION 'CLUB_REQUIRED';
  END IF;
  IF NOT public.fn_can_create_games(p_club_id, v_uid) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: this club is managed by its union';
  END IF;

  RETURN public.fn_cash_game_create_impl_20260905(
    p_club_id, p_template, p_variant, p_sb, p_bb, p_handedness,
    p_overrides, p_name, p_must_move
  );
END;
$$;


ALTER FUNCTION public.fn_cash_game_create(p_club_id uuid, p_template text, p_variant text, p_sb numeric, p_bb numeric, p_handedness integer, p_overrides jsonb, p_name text, p_must_move boolean) OWNER TO postgres;

--
-- Name: FUNCTION fn_cash_game_create(p_club_id uuid, p_template text, p_variant text, p_sb numeric, p_bb numeric, p_handedness integer, p_overrides jsonb, p_name text, p_must_move boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_game_create(p_club_id uuid, p_template text, p_variant text, p_sb numeric, p_bb numeric, p_handedness integer, p_overrides jsonb, p_name text, p_must_move boolean) IS 'Union-aware cash-game creation door. Affiliated club staff cannot bypass fn_can_create_games.';


--
-- Name: fn_cash_game_create_impl_20260905(uuid, text, text, numeric, numeric, integer, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_create_impl_20260905(p_club_id uuid, p_template text, p_variant text, p_sb numeric, p_bb numeric, p_handedness integer DEFAULT NULL::integer, p_overrides jsonb DEFAULT '{}'::jsonb, p_name text DEFAULT NULL::text, p_must_move boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_t text := lower(coalesce(p_template, ''));
  v_v text := lower(coalesce(p_variant, ''));
  v_def jsonb; v_snap jsonb; v_o jsonb := coalesce(p_overrides, '{}'::jsonb);
  v_must_move boolean := coalesce(p_must_move, true);
  v_union uuid;
  v_seats integer; v_choices integer[];
  v_stay integer; v_rejoin integer;
  v_min_bb integer; v_max_bb integer;
  v_ante text; v_vpip integer; v_vpip_window integer;
  v_bombs jsonb; v_bomb_on boolean; v_bomb_trigger text; v_bomb_ante integer; v_bomb_boards integer;
  v_opts jsonb; v_oo jsonb;
  v_name text; v_label text;
  v_game_id uuid; v_table_id uuid;
  v_variant_label text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_cash_game_create requires an authenticated caller' USING ERRCODE = '28000';
  END IF;
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'SESSION_REVOKED: this session is signed out - sign in again' USING ERRCODE = '28000';
  END IF;
  IF p_club_id IS NULL THEN
    RAISE EXCEPTION 'CLUB_REQUIRED';
  END IF;
  IF NOT (public.fn_can_create_games(p_club_id, v_uid) OR public.is_club_admin(p_club_id, v_uid)) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: you cannot create games in this club';
  END IF;

  IF v_t NOT IN ('classic', 'action', 'madness') THEN
    RAISE EXCEPTION 'TEMPLATE_UNKNOWN: %', p_template;
  END IF;
  IF v_v NOT IN ('nlh','plo4','plo5','plo6','plo8','flo8','flh','short_deck','pineapple') THEN
    RAISE EXCEPTION 'VARIANT_UNAVAILABLE: % is not available yet', p_variant;
  END IF;
  IF p_sb IS NULL OR p_bb IS NULL OR p_sb = 'NaN'::numeric OR p_bb = 'NaN'::numeric
     OR p_sb <= 0 OR p_bb <= p_sb
     OR round(p_sb, 2) <> p_sb OR round(p_bb, 2) <> p_bb
     OR p_bb > 100000 THEN
    RAISE EXCEPTION 'STAKES_INVALID: sb=% bb=%', p_sb, p_bb;
  END IF;
  IF jsonb_typeof(v_o) <> 'object' THEN
    RAISE EXCEPTION 'OVERRIDE_INVALID: overrides must be an object';
  END IF;

  v_def := public.fn_cash_template_defaults(v_t, v_v);

  SELECT array_agg(x::integer) INTO v_choices FROM jsonb_array_elements_text(v_def->'seat_choices') x;
  IF (v_def->>'seats_locked')::boolean THEN
    v_seats := (v_def->>'seats')::integer;
  ELSE
    v_seats := coalesce(p_handedness, (v_def->>'seats')::integer);
    IF NOT (v_seats = ANY (v_choices)) THEN
      RAISE EXCEPTION 'HANDEDNESS_INVALID: % is not offered for % %', v_seats, v_t, v_v;
    END IF;
  END IF;

  v_min_bb := public.fn_cash_override_int(v_o, 'min_buyin_bb', (v_def->>'min_buyin_bb')::integer);
  v_max_bb := public.fn_cash_override_int(v_o, 'max_buyin_bb', (v_def->>'max_buyin_bb')::integer);
  IF v_min_bb < 1 OR v_max_bb < v_min_bb OR v_max_bb > 1000 THEN
    RAISE EXCEPTION 'BUYIN_BAND_INVALID: % - % bb', v_min_bb, v_max_bb;
  END IF;
  v_ante := coalesce(v_o->>'regular_ante', v_def->>'regular_ante');
  IF v_ante NOT IN ('none', 'sb', 'bb') THEN
    RAISE EXCEPTION 'ANTE_INVALID: %', v_ante;
  END IF;
  v_vpip := public.fn_cash_override_int(v_o, 'vpip_floor', (v_def->>'vpip_floor')::integer);
  IF v_vpip < 0 OR v_vpip > 100 THEN RAISE EXCEPTION 'VPIP_INVALID: %', v_vpip; END IF;
  v_vpip_window := public.fn_cash_override_int(v_o, 'vpip_window', (v_def->>'vpip_window')::integer);
  IF v_vpip_window < 10 OR v_vpip_window > 200 THEN RAISE EXCEPTION 'VPIP_WINDOW_INVALID: %', v_vpip_window; END IF;

  IF v_o ? 'bombs' AND jsonb_typeof(v_o->'bombs') <> 'object' THEN
    RAISE EXCEPTION 'OVERRIDE_INVALID: bombs must be an object';
  END IF;
  v_bombs := coalesce(v_def->'bombs', '{}'::jsonb) || coalesce(v_o->'bombs', '{}'::jsonb);
  v_bomb_on := public.fn_cash_override_bool(v_bombs, 'enabled', false);
  v_bomb_trigger := v_bombs->>'trigger';
  v_bomb_ante := public.fn_cash_override_int(v_bombs, 'ante_bb', NULL);
  v_bomb_boards := public.fn_cash_override_int(v_bombs, 'boards', NULL);
  IF v_bomb_on THEN
    IF v_bomb_trigger IS NULL OR v_bomb_trigger NOT IN ('timed_15m', 'every_orbit') THEN
      RAISE EXCEPTION 'BOMB_TRIGGER_INVALID: %', v_bomb_trigger;
    END IF;
    IF v_bomb_ante IS NULL OR v_bomb_ante < 1 OR v_bomb_ante > 20 THEN
      RAISE EXCEPTION 'BOMB_ANTE_INVALID: %', v_bomb_ante;
    END IF;
    IF v_bomb_boards IS NULL OR v_bomb_boards < 2 OR v_bomb_boards > 3 THEN
      RAISE EXCEPTION 'BOMB_BOARDS_INVALID: %', v_bomb_boards;
    END IF;
  END IF;

  v_stay := public.fn_cash_override_int(v_o, 'stay_clock_min', (v_def->>'stay_clock_min')::integer);
  v_rejoin := public.fn_cash_override_int(v_o, 'rejoin_window_min', (v_def->>'rejoin_window_min')::integer);
  IF v_stay < (v_def->>'stay_clock_min')::integer THEN
    RAISE EXCEPTION 'STAY_CLOCK_BELOW_FLOOR: % minutes; the minimum is %', v_stay, v_def->>'stay_clock_min';
  END IF;
  IF v_rejoin < (v_def->>'rejoin_window_min')::integer THEN
    RAISE EXCEPTION 'REJOIN_WINDOW_BELOW_FLOOR: % minutes; the minimum is %', v_rejoin, v_def->>'rejoin_window_min';
  END IF;
  IF v_stay > 1440 OR v_rejoin > 10080 THEN
    RAISE EXCEPTION 'CLOCK_TOO_LONG';
  END IF;

  IF v_o ? 'options' AND jsonb_typeof(v_o->'options') <> 'object' THEN
    RAISE EXCEPTION 'OVERRIDE_INVALID: options must be an object';
  END IF;
  v_oo := coalesce(v_o->'options', '{}'::jsonb);
  v_opts := jsonb_build_object(
    'is_private',          public.fn_cash_override_bool(v_oo, 'is_private', false),
    'is_vip_only',         public.fn_cash_override_bool(v_oo, 'is_vip_only', false),
    'is_anonymous',        public.fn_cash_override_bool(v_oo, 'is_anonymous', false),
    'ban_chat',            public.fn_cash_override_bool(v_oo, 'ban_chat', false),
    'insurance_enabled',   public.fn_cash_override_bool(v_oo, 'insurance_enabled', false),
    'seven_deuce_enabled', public.fn_cash_override_bool(v_oo, 'seven_deuce_enabled', false) AND v_v = 'nlh',
    'action_time_seconds', LEAST(120, GREATEST(10, public.fn_cash_override_int(v_oo, 'action_time_seconds', 15)))
  );

  v_snap := v_def || jsonb_build_object(
    'seats', v_seats,
    'min_buyin_bb', v_min_bb,
    'max_buyin_bb', v_max_bb,
    'regular_ante', v_ante,
    'vpip_floor', v_vpip,
    'vpip_window', v_vpip_window,
    'bombs', jsonb_build_object('enabled', v_bomb_on, 'trigger', v_bomb_trigger, 'ante_bb', v_bomb_ante, 'boards', v_bomb_boards),
    'straddle', false,
    'stay_clock_min', v_stay,
    'rejoin_window_min', v_rejoin,
    'run_it_n_times', 'opt_in',
    'rake', 'existing',
    'options', v_opts,
    'table_mode', CASE WHEN v_must_move THEN 'must_move' ELSE 'manual' END,
    'sb', p_sb, 'bb', p_bb,
    'resolved_at', to_jsonb(clock_timestamp())
  );

  v_variant_label := CASE v_v
    WHEN 'nlh' THEN 'NLH' WHEN 'plo4' THEN 'PLO4' WHEN 'plo5' THEN 'PLO5' WHEN 'plo6' THEN 'PLO6'
    WHEN 'plo8' THEN 'PLO8' WHEN 'flo8' THEN 'FLO8' WHEN 'flh' THEN 'FLH'
    WHEN 'short_deck' THEN 'Short Deck' WHEN 'pineapple' THEN 'Pineapple' END;
  v_label := public.fn_cash_stakes_label(p_sb, p_bb, v_v);
  v_name := btrim(coalesce(p_name, ''));
  IF v_name = '' THEN
    v_name := v_variant_label || ' ' || v_label || ' ' || initcap(v_t);
  END IF;
  v_name := left(replace(replace(v_name, '<', ''), '>', ''), 60);

  SELECT u.id INTO v_union
    FROM public.fn_club_union_context(p_club_id) ctx
    JOIN public.unions u ON u.id = COALESCE(ctx.own_union_id, ctx.member_union_id);

  BEGIN
    INSERT INTO public.cash_games
      (club_id, union_id, name, template_name, variant, sb, bb, handedness, ruleset_snapshot, created_by, must_move)
    VALUES
      (p_club_id, v_union, v_name, v_t, v_v, p_sb, p_bb, v_seats, v_snap, v_uid, v_must_move)
    RETURNING id INTO v_game_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'GAME_EXISTS: this club already runs % % %', initcap(v_t), v_variant_label, v_label;
  END;

  -- Main 1 through the one cluster writer. A must-move game's Main 1 is kept
  -- open by the controller (R3); a manual table lives and dies with its host.
  v_table_id := public.fn_cash_cluster_open_table(v_game_id, 'main', 1, 'live', v_uid);

  RETURN jsonb_build_object('ok', true, 'game_id', v_game_id, 'table_id', v_table_id,
                            'name', v_name, 'must_move', v_must_move, 'snapshot', v_snap);
END;
$$;


ALTER FUNCTION public.fn_cash_game_create_impl_20260905(p_club_id uuid, p_template text, p_variant text, p_sb numeric, p_bb numeric, p_handedness integer, p_overrides jsonb, p_name text, p_must_move boolean) OWNER TO postgres;

--
-- Name: fn_cash_game_ensure(uuid, text, numeric, numeric, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_ensure(p_club_id uuid, p_variant text, p_sb numeric, p_bb numeric, p_template text DEFAULT 'classic'::text, p_handedness integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g record; v_def jsonb; v_snap jsonb; v_id uuid; v_union uuid;
  v_t text := lower(coalesce(p_template, 'classic'));
  v_v text := lower(p_variant);
  v_label text; v_variant_label text; v_name text; v_seats integer;
BEGIN
  IF v_t NOT IN ('classic', 'action', 'madness') THEN v_t := 'classic'; END IF;
  SELECT * INTO g FROM public.cash_games
   WHERE club_id = p_club_id AND variant = v_v AND sb = p_sb AND bb = p_bb
   ORDER BY enabled DESC, created_at LIMIT 1;
  IF FOUND THEN
    IF NOT g.enabled THEN
      UPDATE public.cash_games SET enabled = true, closed_at = NULL, closed_by = NULL, updated_at = now()
       WHERE id = g.id;
      INSERT INTO public.cash_cluster_events (game_id, kind, payload)
      VALUES (g.id, 'game_woken', jsonb_build_object('by', 'fn_cash_game_ensure'));
    END IF;
    -- A game with no open table at all: Main 1 is opened, as at creation.
    IF NOT EXISTS (SELECT 1 FROM public.tables t WHERE t.cluster_id = g.id AND t.lifecycle <> 'closed'
                    AND coalesce(t.is_deleted, false) = false) THEN
      PERFORM public.fn_cash_cluster_open_table(g.id, 'main', 1, 'live', NULL);
    END IF;
    RETURN g.id;
  END IF;

  v_def := public.fn_cash_template_defaults(v_t, v_v);
  v_seats := coalesce(p_handedness, (v_def->>'seats')::integer, 6);
  v_snap := v_def || jsonb_build_object('seats', v_seats, 'sb', p_sb, 'bb', p_bb,
                                        'resolved_at', to_jsonb(clock_timestamp()),
                                        'created_by', 'fn_cash_game_ensure');
  v_variant_label := CASE v_v
    WHEN 'nlh' THEN 'NLH' WHEN 'plo4' THEN 'PLO4' WHEN 'plo5' THEN 'PLO5' WHEN 'plo6' THEN 'PLO6'
    WHEN 'plo8' THEN 'PLO8' WHEN 'flo8' THEN 'FLO8' WHEN 'flh' THEN 'FLH'
    WHEN 'short_deck' THEN 'Short Deck' WHEN 'pineapple' THEN 'Pineapple' ELSE upper(v_v) END;
  v_label := public.fn_cash_stakes_label(p_sb, p_bb, v_v);
  v_name := left(v_variant_label || ' ' || v_label || ' ' || initcap(v_t), 60);
  SELECT u.id INTO v_union
    FROM public.fn_club_union_context(p_club_id) ctx
    JOIN public.unions u ON u.id = COALESCE(ctx.own_union_id, ctx.member_union_id);

  INSERT INTO public.cash_games
    (club_id, union_id, name, template_name, variant, sb, bb, handedness, ruleset_snapshot, created_by, must_move)
  VALUES
    (p_club_id, v_union, v_name, v_t, v_v, p_sb, p_bb, v_seats, v_snap, NULL, true)
  RETURNING id INTO v_id;
  PERFORM public.fn_cash_cluster_open_table(v_id, 'main', 1, 'live', NULL);
  INSERT INTO public.cash_cluster_events (game_id, kind, payload)
  VALUES (v_id, 'game_created', jsonb_build_object('name', v_name, 'must_move', true, 'by', 'fn_cash_game_ensure'));
  RETURN v_id;
END;
$$;


ALTER FUNCTION public.fn_cash_game_ensure(p_club_id uuid, p_variant text, p_sb numeric, p_bb numeric, p_template text, p_handedness integer) OWNER TO postgres;

--
-- Name: fn_cash_game_floor_from_template(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_floor_from_template() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_def jsonb;
BEGIN
  IF NEW.ruleset_snapshot IS NULL THEN
    RETURN NEW;
  END IF;

  v_def := public.fn_cash_template_defaults(NEW.template_name, NEW.variant);

  NEW.ruleset_snapshot := jsonb_set(
    jsonb_set(NEW.ruleset_snapshot, '{vpip_floor}',  v_def->'vpip_floor'),
    '{vpip_window}', v_def->'vpip_window');

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_cash_game_floor_from_template() OWNER TO postgres;

--
-- Name: FUNCTION fn_cash_game_floor_from_template(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_game_floor_from_template() IS 'The VPIP floor and window are template constants (Dan 2026-09-07: action 30, madness 50, classic none). Normalises them on every write to cash_games so no writer can store a third answer.';


--
-- Name: fn_cash_game_join(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_join(p_game_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  g record; s record; t record;
  v_position integer; v_count integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED: sign in to join a game' USING ERRCODE = '28000';
  END IF;
  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND: %', p_game_id; END IF;
  IF NOT g.enabled THEN
    RAISE EXCEPTION 'GAME_CLOSED: this game is not taking players' USING ERRCODE = 'check_violation';
  END IF;
  -- Booted for low VPIP: no seat in this game until the bar lifts (Dan 2026-09-05).
  IF public.fn_cash_game_barred_seconds(g.id, v_uid) IS NOT NULL THEN
    RAISE EXCEPTION 'GAME_BARRED:%', public.fn_cash_game_barred_seconds(g.id, v_uid) USING ERRCODE = 'check_violation';
  END IF;

  -- Already in the game: say where.
  SELECT ts.table_id, ts.seat_number, tb.name, tb.role, tb.main_index
    INTO s
    FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
   WHERE ts.user_id = v_uid AND ts.left_at IS NULL AND tb.cluster_id = g.id AND tb.lifecycle <> 'closed'
   LIMIT 1;
  IF FOUND THEN
    UPDATE public.cash_game_waitlist SET status = 'seated', updated_at = now()
     WHERE game_id = g.id AND user_id = v_uid AND status IN ('waiting', 'notified');
    RETURN jsonb_build_object('ok', true, 'action', 'seated', 'table_id', s.table_id,
                              'seat_number', s.seat_number, 'table_name', s.name,
                              'role', s.role, 'main_index', s.main_index);
  END IF;

  -- The shortest live Main with an unreserved open chair, then the feeder
  -- (opening or live). Never a breaking or closed table.
  SELECT tb.id, tb.name, tb.role, tb.main_index, public.fn_cash_game_open_seats(tb.id) AS open_seats,
         (SELECT count(*) FROM public.table_seats ts WHERE ts.table_id = tb.id AND ts.left_at IS NULL) AS seated
    INTO t
    FROM public.tables tb
   WHERE tb.cluster_id = g.id AND coalesce(tb.is_deleted, false) = false
     AND tb.status IN ('waiting', 'running', 'active') AND tb.lifecycle IN ('live', 'opening')
     AND public.fn_cash_game_open_seats(tb.id) > 0
   ORDER BY (tb.role = 'feeder') ASC, seated ASC, tb.main_index ASC NULLS LAST, tb.created_at ASC
   LIMIT 1;
  IF FOUND THEN
    UPDATE public.cash_game_waitlist SET status = 'notified', updated_at = now()
     WHERE game_id = g.id AND user_id = v_uid AND status IN ('waiting', 'notified');
    RETURN jsonb_build_object('ok', true, 'action', 'seat', 'table_id', t.id, 'table_name', t.name,
                              'role', t.role, 'main_index', t.main_index, 'open_seats', t.open_seats);
  END IF;

  -- Nothing open anywhere: hold the place. One live row per game per player.
  INSERT INTO public.cash_game_waitlist (game_id, user_id, status)
  VALUES (g.id, v_uid, 'waiting')
  ON CONFLICT DO NOTHING;
  SELECT count(*) + 1 INTO v_position FROM public.cash_game_waitlist w
   WHERE w.game_id = g.id AND w.status IN ('waiting', 'notified')
     AND w.created_at < (SELECT created_at FROM public.cash_game_waitlist x
                          WHERE x.game_id = g.id AND x.user_id = v_uid AND x.status IN ('waiting', 'notified') LIMIT 1);
  SELECT count(*) INTO v_count FROM public.cash_game_waitlist w
   WHERE w.game_id = g.id AND w.status IN ('waiting', 'notified');
  RETURN jsonb_build_object('ok', true, 'action', 'waitlisted', 'position', v_position, 'waiting', v_count,
                            'opening_hold_since', g.opening_hold_since,
                            'tables', (SELECT count(*) FROM public.tables tb WHERE tb.cluster_id = g.id AND tb.lifecycle <> 'closed'
                                          AND coalesce(tb.is_deleted, false) = false));
END;
$$;


ALTER FUNCTION public.fn_cash_game_join(p_game_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_game_leave_waitlist(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_leave_waitlist(p_game_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_n integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED: sign in first' USING ERRCODE = '28000';
  END IF;
  UPDATE public.cash_game_waitlist SET status = 'cancelled', updated_at = now()
   WHERE game_id = p_game_id AND user_id = v_uid AND status IN ('waiting', 'notified');
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'cancelled', v_n);
END;
$$;


ALTER FUNCTION public.fn_cash_game_leave_waitlist(p_game_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_game_lobby(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_lobby(p_game_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  g record;
  me record;
  v_tables jsonb;
  v_list jsonb;
  v_me jsonb := 'null'::jsonb;
  v_req record;
  v_move record;
  v_roster record;
  v_position integer;
BEGIN
  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND: %', p_game_id; END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'name', t.name, 'role', t.role, 'main_index', t.main_index,
           'lifecycle', t.lifecycle, 'status', t.status, 'max_players', coalesce(t.max_players, 9),
           'seated', (SELECT count(*) FROM public.table_seats ts WHERE ts.table_id = t.id AND ts.left_at IS NULL),
           'open_seats', public.fn_cash_game_open_seats(t.id),
           'seat_change_queue', (SELECT count(*) FROM public.cash_seat_change_requests q
                                  WHERE q.game_id = g.id AND q.status = 'requested' AND q.to_table_id = t.id),
           'seats', (SELECT coalesce(jsonb_agg(jsonb_build_object(
                        'seat_number', ts.seat_number, 'user_id', ts.user_id,
                        'alias', public.fn_player_display_name(ts.user_id),
                        'stack', ts.stack, 'is_sitting_out', ts.is_sitting_out,
                        'joined_game_at', (SELECT r.joined_at FROM public.cash_game_roster r
                                            WHERE r.game_id = g.id AND r.user_id = ts.user_id AND r.left_at IS NULL))
                        ORDER BY ts.seat_number), '[]'::jsonb)
                       FROM public.table_seats ts WHERE ts.table_id = t.id AND ts.left_at IS NULL)
         ) ORDER BY (t.role = 'feeder'), t.main_index NULLS LAST, t.created_at), '[]'::jsonb)
    INTO v_tables
    FROM public.tables t
   WHERE t.cluster_id = g.id AND coalesce(t.is_deleted, false) = false
     -- ONE DEFINITION (20260906163151): the same predicate as
     -- fn_cash_cluster_census and get_club_home. Without the status test this
     -- listed a table the controller does not consider part of the game.
     AND t.status IN ('waiting', 'running', 'active')
     AND t.lifecycle <> 'closed';

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'position', l.pos, 'user_id', l.user_id, 'alias', l.alias,
           'table_id', l.table_id, 'table_name', l.table_name, 'role', l.role,
           'main_index', l.main_index, 'joined_at', l.joined_at) ORDER BY l.pos), '[]'::jsonb)
    INTO v_list
    FROM public.fn_cash_game_must_move_list(g.id) l;

  IF v_uid IS NOT NULL THEN
    SELECT ts.table_id, ts.seat_number, ts.stack, t.role, t.main_index, t.lifecycle
      INTO me
      FROM public.table_seats ts JOIN public.tables t ON t.id = ts.table_id
     WHERE ts.user_id = v_uid AND ts.left_at IS NULL AND t.cluster_id = g.id AND t.lifecycle <> 'closed'
     LIMIT 1;
    SELECT * INTO v_roster FROM public.cash_game_roster r
     WHERE r.game_id = g.id AND r.user_id = v_uid AND r.left_at IS NULL;
    SELECT l.pos INTO v_position FROM public.fn_cash_game_must_move_list(g.id) l WHERE l.user_id = v_uid;
    SELECT * INTO v_req FROM public.cash_seat_change_requests q
     WHERE q.game_id = g.id AND q.user_id = v_uid AND q.status = 'requested';
    SELECT m.id, m.to_table_id, m.reason, m.announced_at, m.ready_at, m.swap_move_id, t.name AS to_table_name,
           t.role AS to_role, t.main_index AS to_main_index
      INTO v_move
      FROM public.cash_seat_moves m JOIN public.tables t ON t.id = m.to_table_id
     WHERE m.game_id = g.id AND m.player_id = v_uid AND m.state = 'pending' AND m.expires_at > clock_timestamp()
     ORDER BY m.created_at DESC LIMIT 1;

    v_me := jsonb_build_object(
      'user_id', v_uid,
      'seated', me.table_id IS NOT NULL,
      'table_id', me.table_id, 'seat_number', me.seat_number, 'stack', me.stack,
      'role', me.role, 'main_index', me.main_index, 'lifecycle', me.lifecycle,
      'on_main_one', (me.role = 'main' AND me.main_index = 1),
      'joined_game_at', v_roster.joined_at,
      'must_move_position', v_position,
      'seat_change', jsonb_build_object(
         -- The button: seated somewhere other than Main 1, not used, nothing
         -- pending, and the table is not already closing under them.
         'available', (me.table_id IS NOT NULL AND NOT (me.role = 'main' AND me.main_index = 1)
                       AND v_roster.seat_change_used_at IS NULL AND v_req.id IS NULL AND v_move.id IS NULL
                       AND me.lifecycle NOT IN ('breaking', 'closed')),
         'used_at', v_roster.seat_change_used_at,
         'request', CASE WHEN v_req.id IS NULL THEN NULL ELSE jsonb_build_object(
            'id', v_req.id, 'to_table_id', v_req.to_table_id, 'created_at', v_req.created_at,
            'position', (SELECT count(*) + 1 FROM public.cash_seat_change_requests q
                          WHERE q.game_id = g.id AND q.status = 'requested' AND q.created_at < v_req.created_at
                            AND (v_req.to_table_id IS NULL OR q.to_table_id IS NULL OR q.to_table_id = v_req.to_table_id))) END),
      -- Not seated: their place on the game's waitlist, if any (Gate 4).
      'waitlist', CASE WHEN me.table_id IS NULL THEN public.fn_cash_game_waitlist_position(g.id) ELSE NULL END,
      'pending_move', CASE WHEN v_move.id IS NULL THEN NULL ELSE jsonb_build_object(
         'id', v_move.id, 'to_table_id', v_move.to_table_id, 'to_table_name', v_move.to_table_name,
         'to_role', v_move.to_role, 'to_main_index', v_move.to_main_index, 'reason', v_move.reason,
         'announced', v_move.announced_at IS NOT NULL, 'swap', v_move.swap_move_id IS NOT NULL,
         'held', v_move.ready_at IS NOT NULL) END);
  END IF;

  RETURN jsonb_build_object(
    'game', jsonb_build_object('id', g.id, 'name', g.name, 'template_name', g.template_name,
                               'variant', g.variant, 'sb', g.sb, 'bb', g.bb, 'handedness', g.handedness,
                               'state', g.state, 'must_move', g.must_move, 'enabled', g.enabled,
                               'last_tick_at', g.last_tick_at),
    'tables', v_tables,
    'must_move_list', v_list,
    'waitlist', jsonb_build_object('waiting', (SELECT count(*) FROM public.cash_game_waitlist w
                                                WHERE w.game_id = g.id AND w.status IN ('waiting', 'notified'))),
    'seat_changes_requested', (SELECT count(*) FROM public.cash_seat_change_requests q
                                WHERE q.game_id = g.id AND q.status = 'requested'),
    'me', v_me,
    'as_of', clock_timestamp());
END;
$$;


ALTER FUNCTION public.fn_cash_game_lobby(p_game_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_game_must_move_list(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_must_move_list(p_game_id uuid) RETURNS TABLE(pos integer, user_id uuid, alias text, table_id uuid, table_name text, role text, main_index integer, joined_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Posted for the game's players and the engine; nobody else. A caller with
  -- no account reads nothing (the empty list), the definer never raises.
  SELECT (row_number() OVER (ORDER BY r.joined_at, r.id))::integer AS pos,
         r.user_id, public.fn_player_display_name(r.user_id) AS alias,
         t.id, t.name, t.role, t.main_index, r.joined_at
    FROM public.cash_game_roster r
    JOIN public.table_seats ts ON ts.user_id = r.user_id AND ts.left_at IS NULL
    JOIN public.tables t ON t.id = ts.table_id AND t.cluster_id = r.game_id AND t.lifecycle <> 'closed'
   WHERE r.game_id = p_game_id AND r.left_at IS NULL
     AND NOT (t.role = 'main' AND t.main_index = 1)
     AND (auth.uid() IS NOT NULL OR public.fn_caller_is_engine())
   ORDER BY r.joined_at, r.id;
$$;


ALTER FUNCTION public.fn_cash_game_must_move_list(p_game_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_game_open_seats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_open_seats(p_table_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT GREATEST(0,
           coalesce(t.max_players, 9)
           - (SELECT count(*) FROM public.table_seats ts WHERE ts.table_id = t.id AND ts.left_at IS NULL)
           - (SELECT count(*) FROM public.table_waitlist w
               WHERE w.table_id = t.id AND w.status = 'notified' AND w.hold_expires_at > clock_timestamp())
           - (SELECT count(*) FROM public.cash_seat_moves m
               WHERE m.to_table_id = t.id AND m.state = 'pending' AND m.swap_move_id IS NULL))::integer
    FROM public.tables t WHERE t.id = p_table_id;
$$;


ALTER FUNCTION public.fn_cash_game_open_seats(p_table_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_game_roster_track(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_roster_track() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_game uuid;
BEGIN
  IF NEW.user_id IS NULL THEN RETURN NEW; END IF;
  SELECT cluster_id INTO v_game FROM public.tables WHERE id = NEW.table_id;
  IF v_game IS NULL THEN RETURN NEW; END IF;

  BEGIN
    IF NEW.left_at IS NULL THEN
      -- A live chair in the game. On the roster once, at the time of the
      -- first chair; a second chair (a move, mid-transaction) changes nothing.
      INSERT INTO public.cash_game_roster (game_id, user_id, joined_at)
      VALUES (v_game, NEW.user_id, coalesce(NEW.joined_at, now()))
      ON CONFLICT (game_id, user_id) WHERE left_at IS NULL DO NOTHING;
    ELSIF TG_OP = 'UPDATE' AND OLD.left_at IS NULL THEN
      -- The chair emptied. A move declares itself and is not a leave; a
      -- player with another live chair in the game, or a move still planned
      -- for them, is still in the game.
      IF current_setting('app.cash_seat_move', true) IS DISTINCT FROM 'on'
         AND NOT EXISTS (SELECT 1 FROM public.table_seats ts
                           JOIN public.tables t ON t.id = ts.table_id
                          WHERE ts.user_id = NEW.user_id AND ts.left_at IS NULL AND ts.id <> NEW.id
                            AND t.cluster_id = v_game AND t.lifecycle <> 'closed')
         AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m
                          WHERE m.player_id = NEW.user_id AND m.game_id = v_game AND m.state = 'pending') THEN
        UPDATE public.cash_game_roster SET left_at = now()
         WHERE game_id = v_game AND user_id = NEW.user_id AND left_at IS NULL;
        UPDATE public.cash_seat_change_requests
           SET status = 'cancelled', resolved_at = now(), note = 'left_game'
         WHERE game_id = v_game AND user_id = NEW.user_id AND status = 'requested';
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_cash_game_roster_track: % (seat %, user %)', SQLERRM, NEW.id, NEW.user_id;
  END;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_cash_game_roster_track() OWNER TO postgres;

--
-- Name: fn_cash_game_waitlist_position(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_waitlist_position(p_game_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'waiting', (SELECT count(*) FROM public.cash_game_waitlist w WHERE w.game_id = p_game_id AND w.status IN ('waiting', 'notified')),
    'position', (SELECT count(*) + 1 FROM public.cash_game_waitlist w
                  WHERE w.game_id = p_game_id AND w.status IN ('waiting', 'notified')
                    AND w.created_at < (SELECT created_at FROM public.cash_game_waitlist x
                                         WHERE x.game_id = p_game_id AND x.user_id = auth.uid() AND x.status IN ('waiting', 'notified') LIMIT 1)),
    'on_list', EXISTS (SELECT 1 FROM public.cash_game_waitlist x
                        WHERE x.game_id = p_game_id AND x.user_id = auth.uid() AND x.status IN ('waiting', 'notified')));
$$;


ALTER FUNCTION public.fn_cash_game_waitlist_position(p_game_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_leave_check(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_leave_check(p_user_id uuid, p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_s record; v_stack numeric; v_rem integer; v_locked boolean;
BEGIN
  SELECT * INTO v_s FROM public.cash_player_session
   WHERE player_id = p_user_id AND scope_type = 'table' AND scope_id = p_table_id AND closed_at IS NULL;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', true, 'stay_remaining_ms', 0);
  END IF;
  SELECT ts.stack INTO v_stack FROM public.table_seats ts
   WHERE ts.table_id = p_table_id AND ts.user_id = p_user_id AND ts.left_at IS NULL LIMIT 1;
  v_rem := public.fn_cash_stay_remaining_ms(v_s.stay_remaining_ms, v_s.stay_running, v_s.stay_last_tick_at);
  v_locked := COALESCE(v_stack, 0) > v_s.baseline AND v_rem > 0;
  RETURN jsonb_build_object(
    'allowed', NOT v_locked,
    'code', CASE WHEN v_locked THEN 'LEAVE_LOCKED' ELSE NULL END,
    'stay_remaining_ms', CASE WHEN v_locked THEN v_rem ELSE 0 END,
    'baseline', v_s.baseline, 'stack', COALESCE(v_stack, 0));
END;
$$;


ALTER FUNCTION public.fn_cash_leave_check(p_user_id uuid, p_table_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_money_text(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_money_text(p numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN p = trunc(p) THEN trunc(p)::bigint::text
              ELSE to_char(p, 'FM999999990.00') END;
$$;


ALTER FUNCTION public.fn_cash_money_text(p numeric) OWNER TO postgres;

--
-- Name: fn_cash_override_bool(jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_override_bool(p_o jsonb, p_key text, p_default boolean) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v text := p_o->>p_key;
BEGIN
  IF v IS NULL THEN RETURN p_default; END IF;
  IF lower(v) IN ('true', 't', '1') THEN RETURN true; END IF;
  IF lower(v) IN ('false', 'f', '0') THEN RETURN false; END IF;
  RAISE EXCEPTION 'OVERRIDE_INVALID: % must be true or false, got %', p_key, v;
END;
$$;


ALTER FUNCTION public.fn_cash_override_bool(p_o jsonb, p_key text, p_default boolean) OWNER TO postgres;

--
-- Name: fn_cash_override_int(jsonb, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_override_int(p_o jsonb, p_key text, p_default integer) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v text := p_o->>p_key;
BEGIN
  IF v IS NULL THEN RETURN p_default; END IF;
  IF v !~ '^-?[0-9]{1,9}$' THEN
    RAISE EXCEPTION 'OVERRIDE_INVALID: % must be a whole number, got %', p_key, v;
  END IF;
  RETURN v::integer;
END;
$_$;


ALTER FUNCTION public.fn_cash_override_int(p_o jsonb, p_key text, p_default integer) OWNER TO postgres;

--
-- Name: fn_cash_pot_conservation_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_pot_conservation_check(p_since_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  /* BOUNDED AT 48 HOURS, MEASURED (2026-09-01, and the ceiling was 720 for
     about an hour before this).

     Cash hands arrive at roughly 59,000 a day and the per-row cost is a
     jsonb_array_elements sum over `winners`. A 24-hour window reads 58,932
     rows and returns comfortably. A 168-hour window read 463,506 rows and
     returned once, then hit the statement timeout on the very next call an
     hour later when the database was busier - which is the shape of every
     check on this platform that quietly stopped working. fn_spin_unpaid_check
     learned the same lesson the same way ("it read the unbounded view three
     times and timed out every call before 2026-08-31").

     48 hours is double what the engine asks for and still half of what has
     been seen to fail. An operator who wants a week walks it two days at a
     time; a check that cannot finish tells nobody anything. */
  v_hours   integer := LEAST(GREATEST(COALESCE(p_since_hours, 24), 1), 48);
  v_since   timestamptz;
  v_hands   bigint := 0;
  v_bad     bigint := 0;
  v_chips   numeric := 0;
  v_nowin   bigint := 0;
  v_nowin_chips numeric := 0;
  v_alerts  integer := 0;
BEGIN
  v_since := now() - make_interval(hours => v_hours);

  WITH h AS (
    SELECT hh.id, hh.table_id, hh.created_at,
           COALESCE(hh.pot_size, 0)    AS pot,
           COALESCE(hh.rake_amount, 0) AS rake,
           COALESCE(hh.bbj_amount, 0)  AS bbj,
           COALESCE((SELECT sum((e->>'amount')::numeric)
                       FROM jsonb_array_elements(
                         CASE WHEN jsonb_typeof(hh.winners) = 'array'
                              THEN hh.winners ELSE '[]'::jsonb END) e
                      WHERE e ? 'amount'), 0) AS awarded,
           COALESCE(jsonb_array_length(
             CASE WHEN jsonb_typeof(hh.winners) = 'array'
                  THEN hh.winners ELSE '[]'::jsonb END), 0) AS winner_count
      FROM public.hand_history hh
     WHERE hh.tournament_id IS NULL
       AND hh.created_at >= v_since
       AND COALESCE(hh.pot_size, 0) > 0
  )
  SELECT count(*),
         count(*) FILTER (WHERE winner_count > 0 AND abs(pot - rake - bbj - awarded) > 0.01),
         COALESCE(round(sum(abs(pot - rake - bbj - awarded))
                        FILTER (WHERE winner_count > 0
                                  AND abs(pot - rake - bbj - awarded) > 0.01), 2), 0),
         /* A HAND WITH NO WINNER IS NOT AUTOMATICALLY A HAND WITH A PROBLEM
            (2026-09-01, corrected on the first live run). Both hands this
            found - 86ff9441 and 139babb2, 2026-08-30 - had their whole pot
            after rake go to the Bad Beat Jackpot: pot 0.30, rake 0.03, bbj
            0.27, undistributed 0.00. Nobody was owed anything and there was
            nothing wrong. Only a no-winner hand that still HOLDS chips is
            worth an alert. */
         count(*) FILTER (WHERE winner_count = 0 AND pot - rake - bbj > 0.01),
         COALESCE(round(sum(pot - rake - bbj)
                        FILTER (WHERE winner_count = 0 AND pot - rake - bbj > 0.01), 2), 0)
    INTO v_hands, v_bad, v_chips, v_nowin, v_nowin_chips
    FROM h;

  /* One OPEN alert per condition, refreshed by resolving it. A per-hand alert
     would file thousands of rows on a bad day and bury itself, which is the
     failure 20260901170000 exists to stop. */
  IF v_bad > 0 THEN
    PERFORM public.fn_raise_server_financial_alert(
      'critical', 'fn_cash_pot_conservation_check',
      format('%s cash hand(s) in the last %sh did not distribute their pot: %s chips entered pots and did not come out to a player or the rake',
             v_bad, v_hours, v_chips),
      jsonb_build_object('kind','pot_not_distributed','hands',v_bad,
        'chips',v_chips,'since_hours',v_hours,'hands_checked',v_hands,
        'detail','no money was moved by this check'),
      'pot_not_distributed');
    v_alerts := v_alerts + 1;
  END IF;

  IF v_nowin > 0 THEN
    PERFORM public.fn_raise_server_financial_alert(
      'warning', 'fn_cash_pot_conservation_check',
      format('%s cash hand(s) in the last %sh recorded no winner at all while still holding %s chips after rake and jackpot',
             v_nowin, v_hours, v_nowin_chips),
      jsonb_build_object('kind','no_winner_recorded','hands',v_nowin,
        'chips',v_nowin_chips,'since_hours',v_hours,
        'detail','a hand whose whole pot goes to the jackpot has no winner and owes nobody; this counts only the ones still holding chips'),
      'no_winner_recorded');
    v_alerts := v_alerts + 1;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'since_hours', v_hours,
    'hands_checked', v_hands,
    'pot_not_distributed', v_bad,
    'pot_not_distributed_chips', v_chips,
    'no_winner_recorded', v_nowin,
    'no_winner_recorded_chips', v_nowin_chips,
    -- NOT "alerts_raised": the dedupe path returns an existing row's id, so a
    -- standing condition reports itself on every pass without a new row being
    -- written. This counts CONDITIONS that are open, which is what it means.
    'conditions_alerted', v_alerts);
END;
$$;


ALTER FUNCTION public.fn_cash_pot_conservation_check(p_since_hours integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_cash_pot_conservation_check(p_since_hours integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_pot_conservation_check(p_since_hours integer) IS 'Asks of every completed cash hand whether pot_size equals rake + bbj + what the winners were awarded. The one money surface on the platform that nothing was watching. Reports through the deduped alert path and moves no money.';


--
-- Name: fn_cash_rejoin_floor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_rejoin_floor(p_user_id uuid, p_table_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_barred timestamptz;
  v_floor numeric;
BEGIN
  SELECT max(c.barred_until), max(c.required_stack)
    INTO v_barred, v_floor
    FROM public.tables t
    JOIN public.cash_rejoin_constraints c
      ON c.player_id = p_user_id
     AND c.club_id  = t.club_id
     AND c.variant  = t.game_variant
     AND c.sb       = t.small_blind
     AND c.bb       = t.big_blind
     AND c.expires_at > now()
   WHERE t.id = p_table_id
     AND t.tournament_id IS NULL;
  IF v_barred IS NOT NULL AND v_barred > now() THEN
    RAISE EXCEPTION 'VPIP_BARRED:%', ceil(extract(epoch FROM (v_barred - now())))::integer
      USING ERRCODE = 'check_violation',
            HINT = 'Removed for low VPIP: no seat in this game until the bar lifts.';
  END IF;
  RETURN v_floor;
END;
$$;


ALTER FUNCTION public.fn_cash_rejoin_floor(p_user_id uuid, p_table_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_seat_change_cancel(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_change_cancel(p_game_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_n integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED: sign in first' USING ERRCODE = '28000';
  END IF;
  PERFORM 1 FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  -- Only a request still on the list can be taken back; a planned move is
  -- already the engine's.
  UPDATE public.cash_seat_change_requests
     SET status = 'cancelled', resolved_at = now(), note = 'cancelled_by_player'
   WHERE game_id = p_game_id AND user_id = v_uid AND status = 'requested';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    -- The button comes back.
    UPDATE public.cash_game_roster SET seat_change_used_at = NULL
     WHERE game_id = p_game_id AND user_id = v_uid AND left_at IS NULL;
    INSERT INTO public.cash_cluster_events (game_id, kind, payload)
    VALUES (p_game_id, 'seat_change_cancelled', jsonb_build_object('player_id', v_uid));
  END IF;
  RETURN jsonb_build_object('ok', true, 'cancelled', v_n);
END;
$$;


ALTER FUNCTION public.fn_cash_seat_change_cancel(p_game_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_seat_change_plan(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_change_plan(p_game_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r record; p record;
  v_census public.cash_cluster_census_row[];
  v_target uuid;
  v_moves integer := 0;
  v_move_a uuid; v_move_b uuid;
  v_seat_a integer; v_seat_b integer;
BEGIN
  v_census := public.fn_cash_cluster_census(p_game_id, p_now);

  FOR r IN SELECT q.* FROM public.cash_seat_change_requests q
            WHERE q.game_id = p_game_id AND q.status = 'requested'
            ORDER BY q.created_at, q.id
  LOOP
    -- Still in that chair, with chips, not on the way out?
    IF NOT EXISTS (SELECT 1 FROM public.table_seats ts
                    WHERE ts.table_id = r.from_table_id AND ts.user_id = r.user_id AND ts.left_at IS NULL) THEN
      UPDATE public.cash_seat_change_requests
         SET status = 'cancelled', resolved_at = p_now, note = 'left_table'
       WHERE id = r.id;
      -- AND THE BUTTON COMES BACK. This request is being cancelled for a
      -- reason that is not the player's doing and did not move them where they
      -- asked, so it must not spend the one change they get for this game.
      -- fn_cash_seat_change_cancel has done exactly this for the player's own
      -- cancel since day one; this is the same event arriving from the planner.
      UPDATE public.cash_game_roster
         SET seat_change_used_at = NULL
       WHERE game_id = p_game_id AND user_id = r.user_id AND left_at IS NULL;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (p_game_id, r.from_table_id, 'seat_change_returned',
              jsonb_build_object('player_id', r.user_id, 'reason', 'left_table'));
      CONTINUE;
    END IF;
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM public.table_seats ts
                               WHERE ts.table_id = r.from_table_id AND ts.user_id = r.user_id AND ts.left_at IS NULL
                                 AND coalesce(ts.stack, 0) > 0 AND coalesce(ts.leave_pending, false) = false);
    CONTINUE WHEN EXISTS (SELECT 1 FROM public.cash_seat_moves m WHERE m.player_id = r.user_id AND m.state = 'pending');
    CONTINUE WHEN EXISTS (SELECT 1 FROM public.cash_seat_moves m
                           WHERE m.player_id = r.user_id AND m.state = 'cancelled' AND m.created_at > p_now - interval '60 seconds');

    -- A chair: the table they asked for, or (any) the shortest other table
    -- that is not Main 1 and not closing.
    SELECT c.id INTO v_target FROM unnest(v_census) c
     WHERE c.id <> r.from_table_id AND NOT c.breaking AND c.lifecycle IN ('live', 'opening')
       AND NOT (c.role = 'main' AND c.main_index = 1)
       AND (r.to_table_id IS NULL OR c.id = r.to_table_id)
       AND c.open_unreserved
           - (SELECT count(*) FROM public.cash_seat_moves m
               WHERE m.to_table_id = c.id AND m.state = 'pending' AND m.swap_move_id IS NULL) > 0
     ORDER BY c.seated ASC, c.created_at ASC LIMIT 1;
    IF v_target IS NOT NULL THEN
      INSERT INTO public.cash_seat_moves (game_id, player_id, from_table_id, to_table_id, reason)
      VALUES (p_game_id, r.user_id, r.from_table_id, v_target, 'seat_change')
      RETURNING id INTO v_move_a;
      UPDATE public.cash_seat_change_requests
         SET status = 'moved', resolved_at = p_now, move_id = v_move_a, note = 'seat_open'
       WHERE id = r.id;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (p_game_id, v_target, 'move_planned',
              jsonb_build_object('player_id', r.user_id, 'from_table_id', r.from_table_id, 'reason', 'seat_change'));
      v_moves := v_moves + 1;
      CONTINUE;
    END IF;

    -- A swap: the oldest other request whose table I would take and who
    -- would take mine. Both chairs are occupied, so both moves are linked
    -- and land together (fn_cash_seat_swap_execute).
    SELECT q.*, ts.seat_number AS their_seat INTO p
      FROM public.cash_seat_change_requests q
      JOIN unnest(v_census) c ON c.id = q.from_table_id
      JOIN public.table_seats ts ON ts.table_id = q.from_table_id AND ts.user_id = q.user_id AND ts.left_at IS NULL
     WHERE q.game_id = p_game_id AND q.status = 'requested' AND q.id <> r.id
       AND q.from_table_id <> r.from_table_id
       AND (r.to_table_id IS NULL OR q.from_table_id = r.to_table_id)
       AND (q.to_table_id IS NULL OR q.to_table_id = r.from_table_id)
       AND NOT c.breaking AND c.lifecycle = 'live'
       AND NOT (c.role = 'main' AND c.main_index = 1)
       AND coalesce(ts.stack, 0) > 0 AND coalesce(ts.leave_pending, false) = false
       AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m WHERE m.player_id = q.user_id AND m.state = 'pending')
       AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m
                        WHERE m.player_id = q.user_id AND m.state = 'cancelled' AND m.created_at > p_now - interval '60 seconds')
     ORDER BY q.created_at, q.id LIMIT 1;
    IF FOUND THEN
      SELECT ts.seat_number INTO v_seat_a FROM public.table_seats ts
       WHERE ts.table_id = r.from_table_id AND ts.user_id = r.user_id AND ts.left_at IS NULL;
      v_seat_b := p.their_seat;
      INSERT INTO public.cash_seat_moves (game_id, player_id, from_table_id, to_table_id, reason, to_seat_number)
      VALUES (p_game_id, r.user_id, r.from_table_id, p.from_table_id, 'seat_change', v_seat_b)
      RETURNING id INTO v_move_a;
      INSERT INTO public.cash_seat_moves (game_id, player_id, from_table_id, to_table_id, reason, to_seat_number, swap_move_id)
      VALUES (p_game_id, p.user_id, p.from_table_id, r.from_table_id, 'seat_change', v_seat_a, v_move_a)
      RETURNING id INTO v_move_b;
      UPDATE public.cash_seat_moves SET swap_move_id = v_move_b WHERE id = v_move_a;
      UPDATE public.cash_seat_change_requests
         SET status = 'moved', resolved_at = p_now, move_id = v_move_a, note = 'swap'
       WHERE id = r.id;
      UPDATE public.cash_seat_change_requests
         SET status = 'moved', resolved_at = p_now, move_id = v_move_b, note = 'swap'
       WHERE id = p.id;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (p_game_id, p.from_table_id, 'swap_planned',
              jsonb_build_object('player_id', r.user_id, 'with_player_id', p.user_id,
                                 'from_table_id', r.from_table_id, 'to_table_id', p.from_table_id));
      v_moves := v_moves + 2;
    END IF;
  END LOOP;
  RETURN v_moves;
END;
$$;


ALTER FUNCTION public.fn_cash_seat_change_plan(p_game_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_cash_seat_change_request(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_change_request(p_game_id uuid, p_to_table_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  -- THE ONLY LINE THAT DIFFERS FROM THE HUMAN DOOR. A browser is its own
  -- auth.uid() and nothing else; the engine, and only the engine, may name the
  -- player it is acting for. Everything below this line is unchanged.
  v_uid uuid := CASE WHEN public.fn_caller_is_engine() THEN coalesce(p_user_id, auth.uid())
                     ELSE auth.uid() END;
  g record; me record; dst record; ro record; q record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED: sign in first' USING ERRCODE = '28000';
  END IF;
  IF public.fn_platform_frozen() THEN
    RAISE EXCEPTION 'PLATFORM_FROZEN: the platform is on its maintenance break' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND: %', p_game_id; END IF;
  IF NOT g.must_move THEN
    RAISE EXCEPTION 'SEAT_CHANGE_MANUAL_GAME: a manual table has no seat change' USING ERRCODE = 'check_violation';
  END IF;

  SELECT ts.table_id, ts.seat_number, ts.stack, ts.leave_pending, t.role, t.main_index, t.lifecycle, t.name
    INTO me
    FROM public.table_seats ts JOIN public.tables t ON t.id = ts.table_id
   WHERE ts.user_id = v_uid AND ts.left_at IS NULL AND t.cluster_id = g.id AND t.lifecycle <> 'closed'
   LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_IN_GAME: you are not seated in this game' USING ERRCODE = 'check_violation';
  END IF;
  IF me.role = 'main' AND me.main_index = 1 THEN
    RAISE EXCEPTION 'SEAT_CHANGE_NOT_FROM_MAIN: the main game has no seat change' USING ERRCODE = 'check_violation';
  END IF;
  IF me.lifecycle = 'breaking' THEN
    RAISE EXCEPTION 'SEAT_CHANGE_TABLE_CLOSING: this table is closing and the game is already moving you' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM public.cash_seat_moves m WHERE m.player_id = v_uid AND m.state = 'pending') THEN
    RAISE EXCEPTION 'MOVE_PENDING: you are already being moved' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO q FROM public.cash_seat_change_requests
   WHERE game_id = g.id AND user_id = v_uid AND status = 'requested';
  IF FOUND THEN
    RETURN public.fn_cash_seat_change_status(g.id, v_uid);
  END IF;

  SELECT * INTO ro FROM public.cash_game_roster WHERE game_id = g.id AND user_id = v_uid AND left_at IS NULL;
  IF NOT FOUND THEN
    INSERT INTO public.cash_game_roster (game_id, user_id, joined_at)
    SELECT g.id, v_uid, coalesce(min(ts.joined_at), now()) FROM public.table_seats ts
     WHERE ts.user_id = v_uid AND ts.table_id = me.table_id AND ts.left_at IS NULL
    RETURNING * INTO ro;
  END IF;
  IF ro.seat_change_used_at IS NOT NULL THEN
    RAISE EXCEPTION 'SEAT_CHANGE_USED: you have used your seat change for this game' USING ERRCODE = 'check_violation';
  END IF;

  IF p_to_table_id IS NOT NULL THEN
    SELECT * INTO dst FROM public.tables WHERE id = p_to_table_id;
    IF NOT FOUND OR dst.cluster_id IS DISTINCT FROM g.id OR coalesce(dst.is_deleted, false)
       OR dst.lifecycle NOT IN ('live', 'opening') THEN
      RAISE EXCEPTION 'SEAT_CHANGE_TABLE_UNAVAILABLE: that table is not open in this game' USING ERRCODE = 'check_violation';
    END IF;
    IF dst.role = 'main' AND dst.main_index = 1 THEN
      RAISE EXCEPTION 'SEAT_CHANGE_NEVER_TO_MAIN: the main game fills in must-move order only' USING ERRCODE = 'check_violation';
    END IF;
    IF dst.id = me.table_id THEN
      RAISE EXCEPTION 'SEAT_CHANGE_SAME_TABLE: you are already at that table' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.tables t
                    WHERE t.cluster_id = g.id AND t.id <> me.table_id AND coalesce(t.is_deleted, false) = false
                      AND t.lifecycle IN ('live', 'opening') AND NOT (t.role = 'main' AND t.main_index = 1)) THEN
      RAISE EXCEPTION 'SEAT_CHANGE_NO_OTHER_TABLE: there is no other table to change to yet' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  INSERT INTO public.cash_seat_change_requests (game_id, user_id, from_table_id, to_table_id)
  VALUES (g.id, v_uid, me.table_id, p_to_table_id);
  UPDATE public.cash_game_roster SET seat_change_used_at = now() WHERE id = ro.id;
  INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
  VALUES (g.id, me.table_id, 'seat_change_requested',
          jsonb_build_object('player_id', v_uid, 'to_table_id', p_to_table_id));

  PERFORM public.fn_cash_seat_change_plan(g.id, clock_timestamp());
  RETURN public.fn_cash_seat_change_status(g.id, v_uid);
END;
$$;


ALTER FUNCTION public.fn_cash_seat_change_request(p_game_id uuid, p_to_table_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_cash_seat_change_request(p_game_id uuid, p_to_table_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_seat_change_request(p_game_id uuid, p_to_table_id uuid, p_user_id uuid) IS 'The once-per-stay seat change on a must-move game. p_user_id is honoured ONLY when fn_caller_is_engine() - the engine asking on behalf of a horse (CLAUDE.md 10.5); a browser is always its own auth.uid().';


--
-- Name: fn_cash_seat_change_status(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_change_status(p_game_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH q AS (
    SELECT * FROM public.cash_seat_change_requests
     WHERE game_id = p_game_id AND user_id = p_user_id
     ORDER BY (status = 'requested') DESC, created_at DESC, resolved_at DESC NULLS FIRST LIMIT 1),
  m AS (
    SELECT mv.*, t.name AS to_table_name, t.role AS to_role, t.main_index AS to_main_index
      FROM public.cash_seat_moves mv JOIN public.tables t ON t.id = mv.to_table_id
     WHERE mv.game_id = p_game_id AND mv.player_id = p_user_id AND mv.state = 'pending'
       AND mv.reason = 'seat_change'
     ORDER BY mv.created_at DESC LIMIT 1)
  SELECT jsonb_build_object(
    'ok', true,
    'action', CASE WHEN (SELECT id FROM m) IS NOT NULL AND (SELECT swap_move_id FROM m) IS NOT NULL THEN 'swapping'
                   WHEN (SELECT id FROM m) IS NOT NULL THEN 'moving'
                   WHEN (SELECT status FROM q) = 'requested' THEN 'listed'
                   WHEN (SELECT status FROM q) = 'moved' THEN 'moved'
                   ELSE coalesce((SELECT status FROM q), 'none') END,
    'request_id', (SELECT id FROM q),
    'to_table_id', coalesce((SELECT to_table_id FROM m), (SELECT to_table_id FROM q)),
    'to_table_name', (SELECT to_table_name FROM m),
    'to_role', (SELECT to_role FROM m),
    'to_main_index', (SELECT to_main_index FROM m),
    'position', CASE WHEN (SELECT status FROM q) = 'requested' THEN
                  (SELECT count(*) + 1 FROM public.cash_seat_change_requests x, q
                    WHERE x.game_id = p_game_id AND x.status = 'requested' AND x.created_at < q.created_at
                      AND (q.to_table_id IS NULL OR x.to_table_id IS NULL OR x.to_table_id = q.to_table_id)) END,
    'used_at', (SELECT seat_change_used_at FROM public.cash_game_roster
                 WHERE game_id = p_game_id AND user_id = p_user_id AND left_at IS NULL));
$$;


ALTER FUNCTION public.fn_cash_seat_change_status(p_game_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_seat_move_announce(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_move_announce(p_move_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_n integer;
BEGIN
  -- The engine has just promised "Moving After This Hand". The promise has
  -- to outlive the hand: five minutes covers any hand the engine's own
  -- watchdog would let run.
  UPDATE public.cash_seat_moves
     SET announced_at = coalesce(announced_at, clock_timestamp()),
         expires_at   = GREATEST(expires_at, clock_timestamp() + interval '5 minutes')
   WHERE id = ANY(p_move_ids) AND state = 'pending';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


ALTER FUNCTION public.fn_cash_seat_move_announce(p_move_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_cash_seat_move_execute(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_move_execute(p_move_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'platform_frozen');
  END IF;
  RETURN public.fn_cash_seat_move_execute_before_maintenance_gate(p_move_id);
END;
$$;


ALTER FUNCTION public.fn_cash_seat_move_execute(p_move_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_seat_move_execute_before_maintenance_gate(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_move_execute_before_maintenance_gate(p_move_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  m record; src record; dst record; v_seat integer; v_new_id uuid; v_stack numeric;
  v_hold text; v_agreed boolean;
BEGIN
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'frozen');
  END IF;
  SELECT * INTO m FROM public.cash_seat_moves WHERE id = p_move_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;
  IF m.state <> 'pending' THEN RETURN jsonb_build_object('ok', false, 'reason', m.state); END IF;
  IF m.expires_at <= clock_timestamp() THEN
    UPDATE public.cash_seat_moves SET state = 'expired' WHERE id = m.id;
    RETURN jsonb_build_object('ok', false, 'reason', 'expired');
  END IF;
  IF m.swap_move_id IS NOT NULL THEN
    RETURN public.fn_cash_seat_swap_execute(m.id);
  END IF;

  SELECT * INTO src FROM public.table_seats
   WHERE table_id = m.from_table_id AND user_id = m.player_id AND left_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    UPDATE public.cash_seat_moves SET state = 'cancelled', note = 'player_not_seated' WHERE id = m.id;
    RETURN jsonb_build_object('ok', false, 'reason', 'player_not_seated');
  END IF;

  IF coalesce(src.stack, 0) <= 0 THEN
    UPDATE public.cash_seat_moves SET state = 'cancelled', note = 'busted' WHERE id = m.id;
    RETURN jsonb_build_object('ok', false, 'reason', 'busted');
  END IF;

  SELECT * INTO dst FROM public.tables WHERE id = m.to_table_id FOR UPDATE;
  IF NOT FOUND OR dst.status NOT IN ('waiting', 'running', 'active') OR dst.lifecycle IN ('breaking', 'closed') THEN
    UPDATE public.cash_seat_moves SET state = 'cancelled', note = 'destination_unavailable' WHERE id = m.id;
    RETURN jsonb_build_object('ok', false, 'reason', 'destination_unavailable');
  END IF;

  SELECT gs INTO v_seat FROM generate_series(1, coalesce(dst.max_players, 9)) gs
   WHERE NOT EXISTS (SELECT 1 FROM public.table_seats ts
                      WHERE ts.table_id = dst.id AND ts.seat_number = gs AND ts.left_at IS NULL)
   ORDER BY gs LIMIT 1;
  IF v_seat IS NULL THEN
    UPDATE public.cash_seat_moves SET state = 'cancelled', note = 'destination_full' WHERE id = m.id;
    RETURN jsonb_build_object('ok', false, 'reason', 'destination_full');
  END IF;

  v_stack := src.stack;

  v_hold := CASE WHEN m.reason = 'seat_change' THEN 'waiting' ELSE 'moved' END;
  v_agreed := (m.reason = 'seat_change');

  PERFORM set_config('app.cash_seat_move', 'on', true);

  -- PRESENCE FOLLOWS THE PLAYER (2026-09-05). is_sitting_out / sit_out_at used
  -- to be written false/NULL here, so a player sitting out at the feeder was
  -- dealt into the first hand at the new table. Carried now, with the ORIGINAL
  -- sit_out_at, so the 5-minute eviction clock is the same clock.
  BEGIN
    UPDATE public.table_seats
       SET user_id = src.user_id, member_id = src.member_id, stack = v_stack,
           is_sitting_out = coalesce(src.is_sitting_out, false), sit_out_at = src.sit_out_at,
           is_away = coalesce(src.is_away, false),
           joined_at = src.joined_at,
           horse_id = src.horse_id, status = 'active', leave_pending = false,
           auto_rebuy = src.auto_rebuy, time_bank_remaining = src.time_bank_remaining,
           time_bank_uses_remaining = src.time_bank_uses_remaining, club_id = src.club_id,
           entry_hold = v_hold, entry_post_agreed = v_agreed, left_at = NULL
     WHERE table_id = dst.id AND seat_number = v_seat AND left_at IS NOT NULL
     RETURNING id INTO v_new_id;
    IF v_new_id IS NULL THEN
      INSERT INTO public.table_seats
        (table_id, seat_number, user_id, member_id, stack, is_sitting_out, is_away, sit_out_at, joined_at,
         horse_id, status, leave_pending, auto_rebuy, time_bank_remaining, time_bank_uses_remaining,
         club_id, entry_hold, entry_post_agreed)
      VALUES
        (dst.id, v_seat, src.user_id, src.member_id, v_stack,
         coalesce(src.is_sitting_out, false), coalesce(src.is_away, false), src.sit_out_at, src.joined_at,
         src.horse_id, 'active', false, src.auto_rebuy, src.time_bank_remaining, src.time_bank_uses_remaining,
         src.club_id, v_hold, v_agreed)
      RETURNING id INTO v_new_id;
    END IF;
    UPDATE public.table_seats SET stack = 0 WHERE id = src.id;
    UPDATE public.table_seats SET left_at = clock_timestamp(), leave_pending = false, status = 'left'
     WHERE id = src.id;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.cash_seat_move', '', true);
    -- A TRANSIENT FAILURE IS NOT A REFUSAL (2026-09-07). 40P01 deadlock,
    -- 55P03 lock timeout and 40001 serialization all mean "try again", and
    -- cancelling for them also puts the player under the planner's 60 second
    -- back-off. The move stays pending; the next hand boundary retries it,
    -- bounded by its own expires_at.
    IF SQLSTATE IN ('40P01', '55P03', '40001') THEN
      UPDATE public.cash_seat_moves
         SET note = left('retry after ' || SQLSTATE || ': ' || SQLERRM, 200)
       WHERE id = m.id;
      RETURN jsonb_build_object('ok', false, 'reason', 'transient',
                                'retry', true, 'detail', left(SQLERRM, 200));
    END IF;
    UPDATE public.cash_seat_moves SET state = 'cancelled', note = left(SQLERRM, 200) WHERE id = m.id;
    RETURN jsonb_build_object('ok', false, 'reason', 'destination_refused', 'detail', left(SQLERRM, 200));
  END;
  PERFORM set_config('app.cash_seat_move', '', true);

  UPDATE public.cash_player_session
     SET scope_id = dst.id, table_id = dst.id
   WHERE player_id = m.player_id AND scope_type = 'table' AND scope_id = m.from_table_id AND closed_at IS NULL;

  UPDATE public.tables t SET current_players =
    (SELECT count(*) FROM public.table_seats ts WHERE ts.table_id = t.id AND ts.left_at IS NULL)
   WHERE t.id IN (m.from_table_id, m.to_table_id);
  UPDATE public.cash_seat_moves
     SET state = 'done', executed_at = clock_timestamp(), to_seat_number = v_seat
   WHERE id = m.id;
  INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
  VALUES (m.game_id, m.to_table_id, 'seat_moved',
          jsonb_build_object('player_id', m.player_id, 'from_table_id', m.from_table_id,
                             'to_seat', v_seat, 'stack', v_stack, 'reason', m.reason));

  RETURN jsonb_build_object('ok', true, 'to_table_id', m.to_table_id, 'to_seat_number', v_seat, 'stack', v_stack,
                            'reason', m.reason);
END;
$$;


ALTER FUNCTION public.fn_cash_seat_move_execute_before_maintenance_gate(p_move_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_seat_move_set_window(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_move_set_window() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- ONE AUTHORITY. The column default is gone; every insert gets its deadline
  -- from the table it is leaving.
  NEW.expires_at := coalesce(NEW.created_at, now())
                  + public.fn_cash_seat_move_window(NEW.from_table_id);
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_cash_seat_move_set_window() OWNER TO postgres;

--
-- Name: fn_cash_seat_move_window(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_move_window(p_table_id uuid) RETURNS interval
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The last four hands give three intervals. Index: (table_id, created_at, id).
  SELECT greatest(
           interval '3 minutes',
           least(
             interval '15 minutes',
             coalesce(
               (SELECT (max(created_at) - min(created_at)) * 4 / 3
                  FROM (SELECT created_at
                          FROM public.hand_history
                         WHERE table_id = p_table_id
                         ORDER BY created_at DESC
                         LIMIT 4) s
                 HAVING count(*) >= 2),
               interval '3 minutes'
             )
           )
         );
$$;


ALTER FUNCTION public.fn_cash_seat_move_window(p_table_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_seat_moves_pending(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_moves_pending(p_table_id uuid) RETURNS TABLE(move_id uuid, player_id uuid, to_table_id uuid, to_table_name text, to_role text, to_main_index integer, reason text, announced_at timestamp with time zone, swap_move_id uuid, ready_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT m.id, m.player_id, m.to_table_id, t.name, t.role, t.main_index, m.reason, m.announced_at,
         m.swap_move_id, m.ready_at
    FROM public.cash_seat_moves m
    JOIN public.tables t ON t.id = m.to_table_id
   WHERE m.from_table_id = p_table_id AND m.state = 'pending' AND m.expires_at > clock_timestamp()
   ORDER BY m.created_at;
$$;


ALTER FUNCTION public.fn_cash_seat_moves_pending(p_table_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_seat_swap_execute(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_swap_execute(p_move_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'platform_frozen');
  END IF;
  RETURN public.fn_cash_seat_swap_execute_before_maintenance_gate(p_move_id);
END;
$$;


ALTER FUNCTION public.fn_cash_seat_swap_execute(p_move_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_seat_swap_execute_before_maintenance_gate(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_seat_swap_execute_before_maintenance_gate(p_move_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  m record; pm record; a record; b record; ta record; tb record;
  v_stack_a numeric; v_stack_b numeric; v_now timestamptz := clock_timestamp();
BEGIN
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'frozen');
  END IF;
  PERFORM 1 FROM public.cash_seat_moves
   WHERE id IN (p_move_id, (SELECT swap_move_id FROM public.cash_seat_moves WHERE id = p_move_id))
   ORDER BY id FOR UPDATE;
  SELECT * INTO m FROM public.cash_seat_moves WHERE id = p_move_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;
  IF m.state <> 'pending' THEN RETURN jsonb_build_object('ok', false, 'reason', m.state); END IF;
  SELECT * INTO pm FROM public.cash_seat_moves WHERE id = m.swap_move_id;
  IF NOT FOUND OR pm.state <> 'pending' OR pm.expires_at <= v_now OR m.expires_at <= v_now THEN
    UPDATE public.cash_seat_moves SET state = CASE WHEN m.expires_at <= v_now THEN 'expired' ELSE 'cancelled' END,
           note = 'swap_partner_gone'
     WHERE id = m.id;
    IF pm.id IS NOT NULL AND pm.state = 'pending' THEN
      UPDATE public.cash_seat_moves SET state = 'expired', note = 'swap_partner_gone' WHERE id = pm.id;
    END IF;
    RETURN jsonb_build_object('ok', false, 'reason', 'swap_partner_gone');
  END IF;

  SELECT * INTO a FROM public.table_seats
   WHERE table_id = m.from_table_id AND user_id = m.player_id AND left_at IS NULL FOR UPDATE;
  SELECT * INTO b FROM public.table_seats
   WHERE table_id = pm.from_table_id AND user_id = pm.player_id AND left_at IS NULL FOR UPDATE;
  IF a.id IS NULL OR b.id IS NULL OR coalesce(a.stack, 0) <= 0 OR coalesce(b.stack, 0) <= 0 THEN
    UPDATE public.cash_seat_moves SET state = 'cancelled',
           note = CASE WHEN a.id IS NULL THEN 'player_not_seated' WHEN coalesce(a.stack, 0) <= 0 THEN 'busted' ELSE 'swap_partner_gone' END
     WHERE id = m.id;
    UPDATE public.cash_seat_moves SET state = 'cancelled',
           note = CASE WHEN b.id IS NULL THEN 'player_not_seated' WHEN coalesce(b.stack, 0) <= 0 THEN 'busted' ELSE 'swap_partner_gone' END
     WHERE id = pm.id;
    RETURN jsonb_build_object('ok', false, 'reason', 'swap_cancelled');
  END IF;
  SELECT * INTO ta FROM public.tables WHERE id = m.to_table_id;
  SELECT * INTO tb FROM public.tables WHERE id = pm.to_table_id;
  IF ta.lifecycle IN ('breaking', 'closed') OR tb.lifecycle IN ('breaking', 'closed') THEN
    UPDATE public.cash_seat_moves SET state = 'cancelled', note = 'destination_unavailable' WHERE id IN (m.id, pm.id);
    RETURN jsonb_build_object('ok', false, 'reason', 'destination_unavailable');
  END IF;

  IF m.ready_at IS NULL THEN
    UPDATE public.cash_seat_moves SET ready_at = v_now WHERE id = m.id;
  END IF;
  IF pm.ready_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'waiting_partner', 'held', true,
                              'to_table_id', m.to_table_id, 'partner_id', pm.player_id);
  END IF;

  -- Each side carries its OWN sit-out across, for the reason written on
  -- fn_cash_seat_move_execute: neither player asked to be dealt into a hand
  -- they had sat out of.
  v_stack_a := a.stack; v_stack_b := b.stack;
  PERFORM set_config('app.cash_seat_move', 'on', true);
  BEGIN
    UPDATE public.table_seats SET stack = 0 WHERE id IN (a.id, b.id);
    UPDATE public.table_seats SET left_at = v_now, leave_pending = false, status = 'left' WHERE id IN (a.id, b.id);
    UPDATE public.table_seats
       SET user_id = a.user_id, member_id = a.member_id, stack = v_stack_a,
           is_sitting_out = coalesce(a.is_sitting_out, false), sit_out_at = a.sit_out_at,
           is_away = coalesce(a.is_away, false),
           joined_at = a.joined_at, horse_id = a.horse_id, status = 'active', leave_pending = false,
           auto_rebuy = a.auto_rebuy, time_bank_remaining = a.time_bank_remaining,
           time_bank_uses_remaining = a.time_bank_uses_remaining, club_id = a.club_id,
           entry_hold = 'waiting', entry_post_agreed = true, left_at = NULL
     WHERE id = b.id;
    UPDATE public.table_seats
       SET user_id = b.user_id, member_id = b.member_id, stack = v_stack_b,
           is_sitting_out = coalesce(b.is_sitting_out, false), sit_out_at = b.sit_out_at,
           is_away = coalesce(b.is_away, false),
           joined_at = b.joined_at, horse_id = b.horse_id, status = 'active', leave_pending = false,
           auto_rebuy = b.auto_rebuy, time_bank_remaining = b.time_bank_remaining,
           time_bank_uses_remaining = b.time_bank_uses_remaining, club_id = b.club_id,
           entry_hold = 'waiting', entry_post_agreed = true, left_at = NULL
     WHERE id = a.id;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.cash_seat_move', '', true);
    UPDATE public.cash_seat_moves SET state = 'cancelled', note = left(SQLERRM, 200) WHERE id IN (m.id, pm.id);
    RETURN jsonb_build_object('ok', false, 'reason', 'destination_refused', 'detail', left(SQLERRM, 200));
  END;
  PERFORM set_config('app.cash_seat_move', '', true);

  UPDATE public.cash_player_session SET scope_id = m.to_table_id, table_id = m.to_table_id
   WHERE player_id = m.player_id AND scope_type = 'table' AND scope_id = m.from_table_id AND closed_at IS NULL;
  UPDATE public.cash_player_session SET scope_id = pm.to_table_id, table_id = pm.to_table_id
   WHERE player_id = pm.player_id AND scope_type = 'table' AND scope_id = pm.from_table_id AND closed_at IS NULL;

  UPDATE public.cash_seat_moves SET state = 'done', executed_at = v_now, to_seat_number = b.seat_number WHERE id = m.id;
  UPDATE public.cash_seat_moves SET state = 'done', executed_at = v_now, to_seat_number = a.seat_number WHERE id = pm.id;
  INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
  VALUES (m.game_id, m.to_table_id, 'seat_moved',
          jsonb_build_object('player_id', m.player_id, 'from_table_id', m.from_table_id, 'to_seat', b.seat_number,
                             'stack', v_stack_a, 'reason', 'seat_change', 'swap', true)),
         (pm.game_id, pm.to_table_id, 'seat_moved',
          jsonb_build_object('player_id', pm.player_id, 'from_table_id', pm.from_table_id, 'to_seat', a.seat_number,
                             'stack', v_stack_b, 'reason', 'seat_change', 'swap', true));
  RETURN jsonb_build_object('ok', true, 'swap', true, 'to_table_id', m.to_table_id, 'to_seat_number', b.seat_number,
                            'stack', v_stack_a,
                            'partner', jsonb_build_object('player_id', pm.player_id, 'from_table_id', pm.from_table_id,
                                                          'to_table_id', pm.to_table_id, 'to_seat_number', a.seat_number,
                                                          'stack', v_stack_b));
END;
$$;


ALTER FUNCTION public.fn_cash_seat_swap_execute_before_maintenance_gate(p_move_id uuid) OWNER TO postgres;

--
-- Name: fn_cash_session_add_baseline(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_session_add_baseline(p_user_id uuid, p_table_id uuid, p_amount numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_s record; v_stack numeric; v_rem integer;
BEGIN
  IF COALESCE(p_amount, 0) <= 0 THEN RETURN; END IF;
  SELECT * INTO v_s FROM public.cash_player_session
   WHERE player_id = p_user_id AND scope_type = 'table' AND scope_id = p_table_id
     AND closed_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT ts.stack INTO v_stack FROM public.table_seats ts
   WHERE ts.table_id = p_table_id AND ts.user_id = p_user_id AND ts.left_at IS NULL
   LIMIT 1;

  v_rem := public.fn_cash_stay_remaining_ms(v_s.stay_remaining_ms, v_s.stay_running, v_s.stay_last_tick_at);
  UPDATE public.cash_player_session
     SET baseline          = baseline + p_amount,
         stay_remaining_ms = v_rem,
         stay_last_tick_at = clock_timestamp(),
         stay_running      = (v_s.stay_running AND COALESCE(v_stack, 0) > (v_s.baseline + p_amount) AND v_rem > 0)
   WHERE id = v_s.id;
END;
$$;


ALTER FUNCTION public.fn_cash_session_add_baseline(p_user_id uuid, p_table_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: fn_cash_session_close(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_session_close(p_user_id uuid, p_table_id uuid, p_stack numeric, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t record; v_s record; v_window integer := 7200000; v_exp timestamptz; v_c record; v_now timestamptz := clock_timestamp();
BEGIN
  SELECT t.club_id, t.game_variant, t.small_blind, t.big_blind, t.tournament_id
    INTO v_t FROM public.tables t WHERE t.id = p_table_id;
  IF NOT FOUND OR v_t.tournament_id IS NOT NULL THEN RETURN; END IF;

  UPDATE public.cash_player_session
     SET closed_at = v_now, closed_reason = COALESCE(p_reason, 'leave')
   WHERE player_id = p_user_id AND scope_type = 'table' AND scope_id = p_table_id AND closed_at IS NULL
   RETURNING * INTO v_s;
  IF FOUND THEN v_window := COALESCE(v_s.rejoin_window_ms, 7200000); END IF;

  -- BOOTED FOR LOW VPIP = BARRED FROM THIS GAME FOR THE WINDOW (Dan
  -- 2026-09-05): "IF A PLAYER GETS BOOTED BECAUSE THERE VPIP IS TO LOW,
  -- RATHOLE RULES APPLY, THEY CAN'T JOIN THAT GAME AGAIN FOR 2 HOURS." The
  -- bar is written whatever the stack (a bust included); the floor, if they
  -- were ahead, is written by the same row as usual below.
  IF p_reason = 'vpip_evicted' AND v_t.club_id IS NOT NULL AND v_t.game_variant IS NOT NULL
     AND v_t.small_blind IS NOT NULL AND v_t.big_blind IS NOT NULL THEN
    v_exp := v_now + make_interval(secs => v_window / 1000.0);
    SELECT * INTO v_c FROM public.cash_rejoin_constraints c
     WHERE c.player_id = p_user_id AND c.club_id = v_t.club_id AND c.variant = v_t.game_variant
       AND c.sb = v_t.small_blind AND c.bb = v_t.big_blind AND c.expires_at > v_now
     ORDER BY c.expires_at DESC LIMIT 1
     FOR UPDATE;
    IF FOUND THEN
      UPDATE public.cash_rejoin_constraints
         SET barred_until = GREATEST(COALESCE(barred_until, v_exp), v_exp),
             expires_at   = GREATEST(expires_at, v_exp),
             left_at      = v_now,
             source_table_id = p_table_id
       WHERE id = v_c.id;
    ELSE
      INSERT INTO public.cash_rejoin_constraints
        (player_id, club_id, variant, sb, bb, required_stack, left_at, expires_at, source_table_id, barred_until)
      -- required_stack must be > 0 (CHECK); a bar-only row carries a cent,
      -- which GREATEST(table minimum, floor) never raises anything to.
      VALUES (p_user_id, v_t.club_id, v_t.game_variant, v_t.small_blind, v_t.big_blind,
              0.01, v_now, v_exp, p_table_id, v_exp);
    END IF;
  END IF;

  IF COALESCE(p_stack, 0) <= 0 THEN RETURN; END IF;             -- bust-to-zero: no floor (A0.11)
  -- RATHOLE ONLY APPLIES TO WINNING PLAYERS (Dan 2026-09-05). The floor is
  -- written only when the departing stack is above the session baseline (the
  -- buy-in plus every add-on and rebuy). A player who is down leaves and
  -- comes back at the table minimum like anyone else. No session, no
  -- baseline, no floor: a chair the platform never opened a session for
  -- cannot be judged a winner.
  IF v_s.id IS NULL OR p_stack <= COALESCE(v_s.baseline, 0) THEN RETURN; END IF;
  IF v_t.club_id IS NULL OR v_t.game_variant IS NULL
     OR v_t.small_blind IS NULL OR v_t.big_blind IS NULL THEN RETURN; END IF;

  v_exp := v_now + make_interval(secs => v_window / 1000.0);

  SELECT * INTO v_c FROM public.cash_rejoin_constraints c
   WHERE c.player_id = p_user_id AND c.club_id = v_t.club_id AND c.variant = v_t.game_variant
     AND c.sb = v_t.small_blind AND c.bb = v_t.big_blind AND c.expires_at > v_now
   ORDER BY c.expires_at DESC LIMIT 1
   FOR UPDATE;
  IF FOUND THEN
    UPDATE public.cash_rejoin_constraints
       SET required_stack = GREATEST(required_stack, p_stack),
           expires_at     = GREATEST(expires_at, v_exp),
           left_at        = v_now,
           source_table_id = p_table_id
     WHERE id = v_c.id;
  ELSE
    INSERT INTO public.cash_rejoin_constraints
      (player_id, club_id, variant, sb, bb, required_stack, left_at, expires_at, source_table_id)
    VALUES (p_user_id, v_t.club_id, v_t.game_variant, v_t.small_blind, v_t.big_blind,
            p_stack, v_now, v_exp, p_table_id);
  END IF;
END;
$$;


ALTER FUNCTION public.fn_cash_session_close(p_user_id uuid, p_table_id uuid, p_stack numeric, p_reason text) OWNER TO postgres;

--
-- Name: fn_cash_session_evaluate(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_session_evaluate(p_table_id uuid, p_entries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t record; v_e jsonb; v_uid uuid; v_active boolean; v_stack numeric;
  v_s record; v_rem integer; v_running boolean; v_out jsonb := '[]'::jsonb; v_now timestamptz;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'fn_cash_session_evaluate is engine-only';
  END IF;
  SELECT t.id, t.tournament_id INTO v_t FROM public.tables t WHERE t.id = p_table_id;
  IF NOT FOUND OR v_t.tournament_id IS NOT NULL THEN RETURN v_out; END IF;

  FOR v_e IN SELECT * FROM jsonb_array_elements(COALESCE(p_entries, '[]'::jsonb)) LOOP
    BEGIN
      v_uid := (v_e->>'user_id')::uuid;
    EXCEPTION WHEN others THEN CONTINUE;
    END;
    v_active := COALESCE((v_e->>'active')::boolean, false);
    v_stack := NULLIF(v_e->>'stack', '')::numeric;

    IF v_stack IS NULL THEN
      SELECT ts.stack INTO v_stack FROM public.table_seats ts
       WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL LIMIT 1;
      IF v_stack IS NULL THEN CONTINUE; END IF;
    ELSIF NOT EXISTS (SELECT 1 FROM public.table_seats ts
                       WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL) THEN
      CONTINUE;
    END IF;

    SELECT * INTO v_s FROM public.cash_player_session
     WHERE player_id = v_uid AND scope_type = 'table' AND scope_id = p_table_id AND closed_at IS NULL
     FOR UPDATE;
    IF NOT FOUND THEN
      -- Seated before the session table existed: baseline = what they hold now.
      PERFORM public.fn_cash_session_open(v_uid, p_table_id, v_stack);
      SELECT * INTO v_s FROM public.cash_player_session
       WHERE player_id = v_uid AND scope_type = 'table' AND scope_id = p_table_id AND closed_at IS NULL
       FOR UPDATE;
      IF NOT FOUND THEN CONTINUE; END IF;
    END IF;

    v_now := clock_timestamp();
    v_rem := public.fn_cash_stay_remaining_ms(v_s.stay_remaining_ms, v_s.stay_running, v_s.stay_last_tick_at);
    v_running := v_active AND v_stack > v_s.baseline AND v_rem > 0;

    UPDATE public.cash_player_session
       SET stay_remaining_ms = v_rem,
           stay_last_tick_at = v_now,
           stay_running      = v_running
     WHERE id = v_s.id;

    v_out := v_out || jsonb_build_object(
      'user_id', v_uid, 'baseline', v_s.baseline, 'stack', v_stack,
      'stay_remaining_ms', v_rem, 'stay_running', v_running,
      'stay_last_tick_at', v_now, 'stay_clock_ms', v_s.stay_clock_ms,
      'leave_locked', (v_stack > v_s.baseline AND v_rem > 0));
  END LOOP;
  RETURN v_out;
END;
$$;


ALTER FUNCTION public.fn_cash_session_evaluate(p_table_id uuid, p_entries jsonb) OWNER TO postgres;

--
-- Name: fn_cash_session_open(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_session_open(p_user_id uuid, p_table_id uuid, p_buy_in numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t record; v_id uuid; v_stay integer := 600000; v_rejoin integer := 7200000; v_snap jsonb;
BEGIN
  SELECT t.id, t.club_id, t.game_variant, t.small_blind, t.big_blind, t.tournament_id, t.cluster_id
    INTO v_t FROM public.tables t WHERE t.id = p_table_id;
  IF NOT FOUND OR v_t.tournament_id IS NOT NULL THEN RETURN NULL; END IF;

  -- A game's snapshot may RAISE the two clocks (never lower: CHECK floors on
  -- the session row and the create function both refuse it).
  IF v_t.cluster_id IS NOT NULL THEN
    SELECT g.ruleset_snapshot INTO v_snap FROM public.cash_games g WHERE g.id = v_t.cluster_id;
    IF v_snap IS NOT NULL THEN
      v_stay   := GREATEST(600000,  coalesce((v_snap->>'stay_clock_min')::integer, 10) * 60000);
      v_rejoin := GREATEST(7200000, coalesce((v_snap->>'rejoin_window_min')::integer, 120) * 60000);
    END IF;
  END IF;

  IF p_buy_in IS NOT NULL THEN
    UPDATE public.cash_player_session
       SET closed_at = clock_timestamp(), closed_reason = 'stale_on_reopen'
     WHERE player_id = p_user_id AND scope_type = 'table' AND scope_id = p_table_id
       AND closed_at IS NULL;
  END IF;

  INSERT INTO public.cash_player_session
    (player_id, club_id, scope_type, scope_id, table_id, variant, sb, bb, baseline,
     stay_clock_ms, rejoin_window_ms, stay_remaining_ms, stay_running, stay_last_tick_at, opened_at)
  VALUES
    (p_user_id, v_t.club_id, 'table', p_table_id, p_table_id, v_t.game_variant,
     v_t.small_blind, v_t.big_blind, GREATEST(COALESCE(p_buy_in, 0), 0),
     v_stay, v_rejoin, v_stay, false, clock_timestamp(), clock_timestamp())
  ON CONFLICT (player_id, scope_type, scope_id) WHERE closed_at IS NULL DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM public.cash_player_session
     WHERE player_id = p_user_id AND scope_type = 'table' AND scope_id = p_table_id
       AND closed_at IS NULL;
  END IF;
  RETURN v_id;
END;
$$;


ALTER FUNCTION public.fn_cash_session_open(p_user_id uuid, p_table_id uuid, p_buy_in numeric) OWNER TO postgres;

--
-- Name: fn_cash_stake_band(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_stake_band(p_bb numeric) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
           WHEN p_bb IS NULL THEN NULL
           WHEN p_bb <= 0.5 THEN 'micro'
           WHEN p_bb <= 2   THEN 'low'
           WHEN p_bb <= 6   THEN 'mid'
           ELSE                  'high'
         END;
$$;


ALTER FUNCTION public.fn_cash_stake_band(p_bb numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_cash_stake_band(p_bb numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_stake_band(p_bb numeric) IS 'The blind category of a big blind: micro <= 0.5, low <= 2, mid <= 6, high above. The SQL twin of stakeBandForBigBlind in server/src/services/HorseBehavior.ts. Dan calls low "small".';


--
-- Name: fn_cash_stakes_label(numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_stakes_label(p_sb numeric, p_bb numeric, p_variant text DEFAULT 'nlh'::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN lower(coalesce(p_variant, 'nlh')) IN ('flh', 'flo8')
              THEN public.fn_cash_money_text(p_bb) || '/' || public.fn_cash_money_text(p_bb * 2)
              ELSE public.fn_cash_money_text(p_sb) || '/' || public.fn_cash_money_text(p_bb) END;
$$;


ALTER FUNCTION public.fn_cash_stakes_label(p_sb numeric, p_bb numeric, p_variant text) OWNER TO postgres;

--
-- Name: fn_cash_stay_remaining_ms(integer, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_stay_remaining_ms(p_remaining integer, p_running boolean, p_last_tick timestamp with time zone) RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN COALESCE(p_running, false)
      THEN LEAST(2147483647::bigint, GREATEST(0::bigint,
             COALESCE(p_remaining, 0)::bigint
             - FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - COALESCE(p_last_tick, clock_timestamp()))) * 1000)::bigint
           ))::integer
    ELSE GREATEST(0, COALESCE(p_remaining, 0))
  END;
$$;


ALTER FUNCTION public.fn_cash_stay_remaining_ms(p_remaining integer, p_running boolean, p_last_tick timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_cash_template_defaults(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_template_defaults(p_template text, p_variant text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t text := lower(coalesce(p_template, 'classic'));
  v_v text := lower(coalesce(p_variant, 'nlh'));
  v_family text;
  v_seats integer; v_seats_locked boolean; v_seat_choices integer[];
  v_vpip integer; v_vpip_window integer;
BEGIN
  IF v_t NOT IN ('classic', 'action', 'madness') THEN
    RAISE EXCEPTION 'TEMPLATE_UNKNOWN: %', p_template;
  END IF;

  v_family := CASE
    WHEN v_v IN ('plo4','plo5','plo6','plo8','flo8') THEN 'plo'
    WHEN v_v = 'short_deck' THEN 'shortdeck'
    WHEN v_v = 'pineapple' THEN 'pineapple'
    ELSE 'holdem' END;

  IF v_family = 'plo' THEN
    v_seats := 6; v_seats_locked := true; v_seat_choices := ARRAY[6];
  ELSIF v_family = 'holdem' THEN
    IF v_t = 'classic' THEN v_seats := 9; v_seat_choices := ARRAY[9, 6];
    ELSE v_seats := 6; v_seat_choices := ARRAY[2,3,4,5,6,7,8,9]; END IF;
    v_seats_locked := false;
  ELSE
    v_seats := 6; v_seats_locked := false; v_seat_choices := ARRAY[2,3,4,5,6,7,8];
  END IF;

  -- VPIP floor per template (percent), FLAT ACROSS FAMILIES (Dan 2026-09-05).
  v_vpip := CASE v_t
    WHEN 'classic' THEN 0
    WHEN 'action'  THEN 30
    ELSE                50 END;
  v_vpip_window := 10;

  RETURN jsonb_build_object(
    'template', v_t,
    'variant', v_v,
    'family', v_family,
    'seats', v_seats,
    'seats_locked', v_seats_locked,
    'seat_choices', to_jsonb(v_seat_choices),
    'min_buyin_bb', CASE v_t WHEN 'classic' THEN 40 WHEN 'action' THEN 50 ELSE 100 END,
    'max_buyin_bb', 200,
    'regular_ante', CASE v_t WHEN 'classic' THEN 'none' WHEN 'action' THEN 'sb' ELSE 'bb' END,
    'vpip_floor', v_vpip,
    'vpip_window', v_vpip_window,
    'bombs', jsonb_build_object(
      'enabled', v_t <> 'classic',
      'trigger', CASE v_t WHEN 'action' THEN 'timed_15m' WHEN 'madness' THEN 'every_orbit' ELSE NULL END,
      'ante_bb', CASE v_t WHEN 'action' THEN 2 WHEN 'madness' THEN 3 ELSE NULL END,
      'boards', CASE WHEN v_t = 'classic' THEN NULL ELSE 2 END),
    'straddle', false,
    'stay_clock_min', 10,
    'rejoin_window_min', 120,
    'run_it_n_times', 'opt_in',
    'rake', 'existing'
  );
END;
$$;


ALTER FUNCTION public.fn_cash_template_defaults(p_template text, p_variant text) OWNER TO postgres;

--
-- Name: fn_cash_vpip_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_vpip_status(p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_on     boolean;
  v_min    integer;
  v_n      integer;
  v_joined timestamptz;
  v_hands  integer;
  v_vpip   numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_signed_in');
  END IF;

  SELECT COALESCE(t.nit_game, false),
         GREATEST(COALESCE(t.maintain_percent_min, 0), 0),
         GREATEST(COALESCE(t.maintain_hands, 10), 1)
    INTO v_on, v_min, v_n
    FROM public.tables t WHERE t.id = p_table_id LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;

  SELECT ts.joined_at INTO v_joined
    FROM public.table_seats ts
   WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL
   ORDER BY ts.joined_at DESC NULLS LAST
   LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', true, 'seated', false,
      'nit_game', v_on, 'required', CASE WHEN v_on THEN v_min ELSE 0 END, 'window', v_n);
  END IF;

  SELECT count(*)::int,
         CASE WHEN count(*) = 0 THEN NULL
              ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
    INTO v_hands, v_vpip
    FROM public.ca_hand_facts f
   WHERE f.table_id = p_table_id
     AND f.user_id = v_uid
     AND (v_joined IS NULL OR f.played_at >= v_joined);

  RETURN jsonb_build_object(
    'ok', true, 'seated', true,
    'nit_game', v_on,
    'required', CASE WHEN v_on THEN v_min ELSE 0 END,
    'window', v_n,
    'hands', v_hands,
    'vpip', v_vpip,
    'since', v_joined);
END;
$$;


ALTER FUNCTION public.fn_cash_vpip_status(p_table_id uuid) OWNER TO postgres;

--
-- Name: fn_cashier_batch_transfer(uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_batch_transfer(p_club_id uuid, p_kind text, p_items jsonb, p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := auth.uid();
  v_item jsonb;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
  v_user_id uuid;
  v_amount numeric;
  v_destination text;
  v_reason text;
  v_op_id uuid;
  v_ticket_key text;
  v_seen uuid[] := '{}'::uuid[];
begin
  if v_me is null then
    return jsonb_build_object('success',false,'error','Not Authenticated');
  end if;
  if p_club_id is null or p_batch_id is null then
    return jsonb_build_object('success',false,'error','Club And Batch Retry Key Are Required');
  end if;
  if p_kind not in ('send','ticket') then
    return jsonb_build_object('success',false,'error','Choose Send Or Ticket');
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) < 1
     or jsonb_array_length(p_items) > 25 then
    return jsonb_build_object('success',false,'error','A Batch Must Contain Between 1 And 25 Recipients');
  end if;

  -- Validate the complete envelope before the first item can move money.
  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if jsonb_typeof(v_item) <> 'object'
       or coalesce(v_item->>'user_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(v_item->>'amount','') !~ '^[0-9]+([.][0-9]+)?$' then
      return jsonb_build_object('success',false,'error','Every Batch Item Needs A Valid Recipient And Amount');
    end if;
    v_user_id := (v_item->>'user_id')::uuid;
    v_amount := (v_item->>'amount')::numeric;
    if v_user_id = any(v_seen) then
      return jsonb_build_object('success',false,'error','A Recipient May Appear Only Once Per Batch');
    end if;
    v_seen := array_append(v_seen, v_user_id);
    if v_amount <= 0 or v_amount > 1e9 or v_amount <> round(v_amount,2) then
      return jsonb_build_object('success',false,'error','Every Amount Must Be Positive And Use Hundredths At Most');
    end if;
    if p_kind='send' and coalesce(v_item->>'op_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      return jsonb_build_object('success',false,'error','Every Send Needs Its Own Retry Key');
    end if;
    if p_kind='ticket' and nullif(btrim(coalesce(v_item->>'idempotency_key','')),'') is null then
      return jsonb_build_object('success',false,'error','Every Ticket Needs Its Own Retry Key');
    end if;
  end loop;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_user_id := (v_item->>'user_id')::uuid;
    v_amount := (v_item->>'amount')::numeric;
    begin
      if p_kind='send' then
        v_destination := coalesce(nullif(v_item->>'destination',''),'player_wallet');
        v_reason := nullif(v_item->>'reason','');
        v_op_id := (v_item->>'op_id')::uuid;
        v_result := public.fn_agent_wallet_send(
          p_club_id,v_user_id,v_amount,v_destination,v_reason,v_op_id
        );
      else
        v_ticket_key := v_item->>'idempotency_key';
        v_result := public.fn_issue_tournament_ticket(
          p_club_id,v_user_id,v_amount,nullif(v_item->>'note',''),v_ticket_key
        );
      end if;
    exception when others then
      v_result := jsonb_build_object(
        'success',false,'error','Transfer Failed','error_code',sqlstate
      );
    end;
    v_results := v_results || jsonb_build_array(
      jsonb_build_object('user_id',v_user_id) || coalesce(v_result,'{}'::jsonb)
    );
  end loop;

  return jsonb_build_object(
    'success',true,
    'batch_id',p_batch_id,
    'results',v_results,
    'processed',jsonb_array_length(v_results)
  );
end
$_$;


ALTER FUNCTION public.fn_cashier_batch_transfer(p_club_id uuid, p_kind text, p_items jsonb, p_batch_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_cashier_batch_transfer(p_club_id uuid, p_kind text, p_items jsonb, p_batch_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cashier_batch_transfer(p_club_id uuid, p_kind text, p_items jsonb, p_batch_id uuid) IS 'Processes at most 25 idempotent cashier sends or tickets in one round trip and returns one explicit result per recipient.';


--
-- Name: fn_cashier_claim_back(uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_claim_back(p_club_id uuid, p_from_user_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_actor_role text;
  v_player_agent uuid;
  v_player_before numeric;
  v_player_after numeric;
  v_actor_after numeric;
  v_first uuid;
  v_second uuid;
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_prior jsonb;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'not authenticated');
  end if;
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'amount must be > 0');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'amount exceeds limit');
  end if;
  if p_from_user_id is null or p_from_user_id = v_actor then
    return jsonb_build_object('success', false, 'error', 'invalid player');
  end if;

  -- IDEMPOTENCY (2026-08-24). This moved money with no replay protection, so a
  -- request that COMMITTED and then failed on the way back - a dropped
  -- connection, a proxy timeout - looked identical to a request that never ran.
  -- The caller's only option was to retry, and the retry charged the player a
  -- second time. Every other money path here already carries a key.
  --
  -- The pre-check below is the fast path; it is NOT the guarantee. Two
  -- concurrent identical submissions both pass it, and the partial unique index
  -- ux_chip_transactions_idempotency_key is what actually settles the race -
  -- see the exception handler around the writes.
  if v_key is not null then
    select ct.metadata into v_prior
      from chip_transactions ct
     where ct.metadata->>'idempotency_key' = v_key
     limit 1;
    if v_prior is not null then
      return jsonb_build_object(
        'success', true,
        'player_balance', (v_prior->>'player_balance_after')::numeric,
        'your_balance',   (v_prior->>'actor_balance_after')::numeric,
        'replayed', true);
    end if;
  end if;

  if v_actor < p_from_user_id then
    v_first := v_actor; v_second := p_from_user_id;
  else
    v_first := p_from_user_id; v_second := v_actor;
  end if;
  perform 1 from club_members
    where club_id = p_club_id and user_id = v_first for update;
  perform 1 from club_members
    where club_id = p_club_id and user_id = v_second for update;

  select role into v_actor_role
    from club_members
   where club_id = p_club_id and user_id = v_actor and status in ('active', 'approved');
  if v_actor_role is null then
    return jsonb_build_object('success', false, 'error', 'you are not an active member of this club');
  end if;
  -- co_owner was missing from this list, so a co-owner - who fn_club_bank_role
  -- and fn_wallet_claim_back both treat as club leadership - could not claim
  -- back at all. Added rather than silently left out.
  if v_actor_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false, 'error', 'your role cannot claim back chips');
  end if;

  select agent_id, coalesce(chip_balance, 0)
    into v_player_agent, v_player_before
    from club_members
   where club_id = p_club_id and user_id = p_from_user_id and status in ('active', 'approved');
  if v_player_before is null then
    return jsonb_build_object('success', false, 'error', 'player is not an active member of this club');
  end if;
  if v_actor_role in ('super_agent', 'agent', 'sub_agent')
     and v_player_agent is distinct from v_actor then
    return jsonb_build_object('success', false, 'error', 'player is not in your downline');
  end if;

  if v_player_before < p_amount then
    return jsonb_build_object('success', false, 'error', 'insufficient chips',
                              'balance', v_player_before);
  end if;

  begin
    update club_members
       set chip_balance = chip_balance - p_amount, updated_at = now()
     where club_id = p_club_id and user_id = p_from_user_id
     returning chip_balance into v_player_after;

    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount, updated_at = now()
     where club_id = p_club_id and user_id = v_actor
     returning chip_balance into v_actor_after;

    insert into chip_transactions
      (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after, metadata)
    values
      (p_club_id, p_from_user_id, v_actor, p_amount, 'peer_transfer',
       coalesce(p_reason, 'Cashier claim back'), v_actor_after,
       case when v_key is null then '{}'::jsonb
            else jsonb_build_object(
                   'idempotency_key', v_key,
                   'player_balance_after', v_player_after,
                   'actor_balance_after', v_actor_after) end);

    insert into wallet_transactions
      (user_id, wallet_type, type, amount, category, description, balance_after)
    values
      (p_from_user_id, 'PLAYER', 'debit', p_amount, 'transfer',
       coalesce(p_reason, 'Cashier claim back'), v_player_after),
      (v_actor, 'PLAYER', 'credit', p_amount, 'transfer',
       coalesce(p_reason, 'Cashier claim back'), v_actor_after);
  exception when unique_violation then
    -- A concurrent identical submission won the race and committed first.
    -- Everything this block did is rolled back with it, so no chips moved
    -- twice; report the winner's outcome rather than an error the caller
    -- would answer with yet another retry.
    select ct.metadata into v_prior
      from chip_transactions ct
     where ct.metadata->>'idempotency_key' = v_key
     limit 1;
    if v_prior is null then raise; END IF;
    return jsonb_build_object(
      'success', true,
      'player_balance', (v_prior->>'player_balance_after')::numeric,
      'your_balance',   (v_prior->>'actor_balance_after')::numeric,
      'replayed', true);
  end;

  return jsonb_build_object(
    'success', true,
    'player_balance', v_player_after,
    'your_balance', v_actor_after
  );
end
$$;


ALTER FUNCTION public.fn_cashier_claim_back(p_club_id uuid, p_from_user_id uuid, p_amount numeric, p_reason text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: fn_cashier_send_chips(uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_send_chips(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_sender uuid := auth.uid();
  v_sender_role text;
  v_recipient_agent uuid;
  v_from_before numeric;
  v_from_after numeric;
  v_to_after numeric;
  v_first uuid;
  v_second uuid;
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_prior jsonb;
begin
  if v_sender is null then
    return jsonb_build_object('success', false, 'error', 'not authenticated');
  end if;
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'amount must be > 0');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'amount exceeds limit');
  end if;
  if p_to_user_id is null or p_to_user_id = v_sender then
    return jsonb_build_object('success', false, 'error', 'invalid recipient');
  end if;

  if v_key is not null then
    select ct.metadata into v_prior
      from chip_transactions ct
     where ct.metadata->>'idempotency_key' = v_key
     limit 1;
    if v_prior is not null then
      return jsonb_build_object(
        'success', true,
        'from_balance', (v_prior->>'from_balance_after')::numeric,
        'to_balance',   (v_prior->>'to_balance_after')::numeric,
        'replayed', true);
    end if;
  end if;

  if v_sender < p_to_user_id then
    v_first := v_sender; v_second := p_to_user_id;
  else
    v_first := p_to_user_id; v_second := v_sender;
  end if;
  perform 1 from club_members
    where club_id = p_club_id and user_id = v_first for update;
  perform 1 from club_members
    where club_id = p_club_id and user_id = v_second for update;

  select role, coalesce(chip_balance, 0)
    into v_sender_role, v_from_before
    from club_members
   where club_id = p_club_id and user_id = v_sender and status in ('active', 'approved');
  if v_sender_role is null then
    return jsonb_build_object('success', false, 'error', 'sender is not an active member of this club');
  end if;
  if v_sender_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false, 'error', 'your role cannot send chips');
  end if;

  select agent_id into v_recipient_agent
    from club_members
   where club_id = p_club_id and user_id = p_to_user_id and status in ('active', 'approved');
  if not found then
    return jsonb_build_object('success', false, 'error', 'recipient is not an active member of this club');
  end if;
  if v_sender_role in ('super_agent', 'agent', 'sub_agent')
     and v_recipient_agent is distinct from v_sender then
    return jsonb_build_object('success', false, 'error', 'recipient is not in your downline');
  end if;

  if v_from_before < p_amount then
    return jsonb_build_object('success', false, 'error', 'insufficient chips', 'balance', v_from_before);
  end if;

  begin
    update club_members
       set chip_balance = chip_balance - p_amount, updated_at = now()
     where club_id = p_club_id and user_id = v_sender
     returning chip_balance into v_from_after;

    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount, updated_at = now()
     where club_id = p_club_id and user_id = p_to_user_id
     returning chip_balance into v_to_after;

    insert into chip_transactions
      (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after, metadata)
    values
      (p_club_id, v_sender, p_to_user_id, p_amount, 'peer_transfer',
       coalesce(p_reason, 'Cashier send out'), v_to_after,
       case when v_key is null then '{}'::jsonb
            else jsonb_build_object(
                   'idempotency_key', v_key,
                   'from_balance_after', v_from_after,
                   'to_balance_after', v_to_after) end);

    insert into wallet_transactions
      (user_id, wallet_type, type, amount, category, description, balance_after)
    values
      (v_sender, 'PLAYER', 'debit', p_amount, 'transfer',
       coalesce(p_reason, 'Cashier send out'), v_from_after),
      (p_to_user_id, 'PLAYER', 'credit', p_amount, 'transfer',
       coalesce(p_reason, 'Cashier send out'), v_to_after);
  exception when unique_violation then
    select ct.metadata into v_prior
      from chip_transactions ct
     where ct.metadata->>'idempotency_key' = v_key
     limit 1;
    if v_prior is null then raise; end if;
    return jsonb_build_object(
      'success', true,
      'from_balance', (v_prior->>'from_balance_after')::numeric,
      'to_balance',   (v_prior->>'to_balance_after')::numeric,
      'replayed', true);
  end;

  return jsonb_build_object(
    'success', true,
    'from_balance', v_from_after,
    'to_balance', v_to_after
  );
end
$$;


ALTER FUNCTION public.fn_cashier_send_chips(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_reason text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: fn_cashout_approve(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashout_approve(p_cashout_id uuid, p_note text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor    uuid := auth.uid();
  v_op_id    uuid := coalesce(p_op_id, gen_random_uuid());
  v_old_category text := current_setting('app.ledger_category', true);
  v_old_counterparty text := current_setting('app.ledger_counterparty', true);
  v_old_entity text := current_setting('app.ledger_counterparty_entity', true);
  v_old_key text := current_setting('app.ledger_idempotency_key', true);
  v_prior    record;
  v_req      record;
  v_escrow   record;
  v_role     text;
  v_agent_id uuid;
  v_after    numeric;
  v_name     text;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  -- Serialize a caller's retries before consulting the committed receipt.
  perform pg_advisory_xact_lock(hashtextextended('cashout-op:' || v_actor::text || ':' || v_op_id::text, 0));

  select id, amount, related_cashout_id, metadata into v_prior
    from chip_transactions
   where transaction_type = 'cashout_approved'
     and to_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    if v_prior.related_cashout_id is distinct from p_cashout_id then
      raise exception 'Operation ID belongs to a different cashout' using errcode = '22023';
    end if;
    return jsonb_build_object('success', true, 'replayed', true,
      'cashout_id', v_prior.related_cashout_id, 'amount', v_prior.amount);
  end if;

  select * into v_req from cashout_requests where id = p_cashout_id for update;
  if v_req is null then
    return jsonb_build_object('success', false, 'error', 'That Cash Out Could Not Be Found');
  end if;
  if v_req.status <> 'pending' then
    return jsonb_build_object('success', false,
      'error', 'That Cash Out Has Already Been Dealt With',
      'current_status', v_req.status);
  end if;

  v_role := public.fn_club_bank_role(v_req.club_id);
  if v_role is null then
    return jsonb_build_object('success', false,
      'error', 'You Are Not A Member Of That Club');
  end if;
  if v_req.agent_id <> v_actor
     and not public.fn_club_cashier_can_transact(v_req.club_id, v_actor, v_req.player_id) then
    return jsonb_build_object('success', false,
      'error', 'That Cash Out Belongs To A Different Agent');
  end if;

  select * into v_escrow
    from chip_escrow
   where cashout_request_id = p_cashout_id
   for update;
  if v_escrow is null or v_escrow.released_at is not null then
    return jsonb_build_object('success', false,
      'error', 'Those Chips Are Not Held In Escrow, So Nothing Can Be Released');
  end if;
  if v_escrow.amount <> v_req.amount then
    return jsonb_build_object('success', false,
      'error', 'The Escrowed Amount Does Not Match The Request');
  end if;

  v_agent_id := public.fn_ensure_agent_row(v_req.club_id, v_actor, v_role);
  if v_agent_id is null then
    raise exception 'could not ensure agents row for % in club %', v_actor, v_req.club_id;
  end if;

  perform public.fn_ca_declare_ledger('escrow_release', 'escrow', v_escrow.id, null,
    'cashout:' || p_cashout_id::text || ':release', null);

  update agents
     set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + v_req.amount,
         updated_at = now()
   where id = v_agent_id
   returning agent_wallet_balance into v_after;
  if not found then
    raise exception 'Cashout destination wallet is missing' using errcode = '23503';
  end if;

  perform set_config('app.ledger_category', coalesce(v_old_category, ''), true);
  perform set_config('app.ledger_counterparty', coalesce(v_old_counterparty, ''), true);
  perform set_config('app.ledger_counterparty_entity', coalesce(v_old_entity, ''), true);
  perform set_config('app.ledger_idempotency_key', coalesce(v_old_key, ''), true);

  update chip_escrow
     set released_at = now(), release_type = 'completed'
   where id = v_escrow.id;

  update cashout_requests
     set status = 'approved',
         agent_note = coalesce(nullif(btrim(p_note), ''), agent_note),
         acknowledged_at = now(),
         completed_at = now(),
         updated_at = now()
   where id = p_cashout_id;

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes,
     related_cashout_id, metadata, balance_after)
  values
    (v_req.club_id, v_req.player_id, v_actor, v_req.amount, 'cashout_approved',
     coalesce(nullif(btrim(p_note), ''), 'Cash Out Approved. Escrow Released Into The Agent Wallet'),
     p_cashout_id,
     jsonb_build_object('op_id', v_op_id, 'assigned_agent_id', v_req.agent_id,
                        'approved_by', v_actor, 'approver_role', v_role,
                        'agent_wallet_after', v_after),
     v_after);

  select coalesce(nullif(btrim(pr.display_name), ''),
                  nullif(btrim(pr.alias), ''),
                  nullif(btrim(pr.username), ''), 'Your Agent')
    into v_name
    from profiles pr where pr.id = v_actor;

  insert into notifications (user_id, type, title, message, metadata, actor_id)
  values (v_req.player_id, 'settlement', 'Cash Out Approved',
          coalesce(v_name, 'Your Agent') || ' Approved Your Cash Out Of '
            || trim(to_char(v_req.amount, 'FM999,999,999,990')) || ' Chips',
          jsonb_build_object('clubId', v_req.club_id, 'cashoutId', p_cashout_id,
                             'amount', v_req.amount),
          v_actor);

  return jsonb_build_object('success', true, 'replayed', false,
    'cashout_id', p_cashout_id, 'amount', v_req.amount,
    'club_id', v_req.club_id,
    'player_id', v_req.player_id, 'agent_wallet_after', v_after);
end
$$;


ALTER FUNCTION public.fn_cashout_approve(p_cashout_id uuid, p_note text, p_op_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_cashout_approve(p_cashout_id uuid, p_note text, p_op_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cashout_approve(p_cashout_id uuid, p_note text, p_op_id uuid) IS 'Agent accepts a cash out: releases escrow into the approvers agent wallet, writes the ledger row, notifies the player.';


--
-- Name: fn_cashout_queue(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashout_queue(p_club_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'pending'::text) RETURNS TABLE(id uuid, club_id uuid, player_id uuid, player_name text, player_avatar text, agent_id uuid, amount numeric, status text, player_note text, agent_note text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select cr.id, cr.club_id, cr.player_id,
         public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                              pr.first_name, pr.last_name, pr.full_name)::text,
         coalesce(nullif(btrim(pr.arena_avatar_url), ''), nullif(btrim(pr.avatar_url), ''), '')::text,
         cr.agent_id, cr.amount, cr.status, cr.player_note, cr.agent_note, cr.created_at
    from cashout_requests cr
    left join profiles pr on pr.id = cr.player_id
   where auth.uid() is not null
     and (p_club_id is null or cr.club_id = p_club_id)
     and (p_status is null or cr.status = p_status)
     and (
       cr.agent_id = auth.uid()
       or public.fn_club_bank_role(cr.club_id) in ('owner', 'co_owner', 'admin')
       or public.fn_club_is_in_downline(cr.club_id, auth.uid(), cr.player_id)
     )
   order by cr.created_at desc
   limit 200;
$$;


