-- Name: FUNCTION fn_cashout_queue(p_club_id uuid, p_status text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cashout_queue(p_club_id uuid, p_status text) IS 'Cash out requests the caller may act on: their own downline, or every request in a club they run.';


--
-- Name: fn_cashout_release(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashout_release(p_cashout_id uuid, p_note text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor     uuid := auth.uid();
  v_op_id     uuid := coalesce(p_op_id, gen_random_uuid());
  v_old_category text := current_setting('app.ledger_category', true);
  v_old_counterparty text := current_setting('app.ledger_counterparty', true);
  v_old_entity text := current_setting('app.ledger_counterparty_entity', true);
  v_old_key text := current_setting('app.ledger_idempotency_key', true);
  v_prior     record;
  v_req       record;
  v_escrow    record;
  v_is_player boolean;
  v_type      text;
  v_status    text;
  v_after     numeric;
  v_name      text;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  -- Serialize a caller's retries before consulting the committed receipt.
  perform pg_advisory_xact_lock(hashtextextended('cashout-op:' || v_actor::text || ':' || v_op_id::text, 0));

  select id, amount, related_cashout_id into v_prior
    from chip_transactions
   where transaction_type in ('cashout_denied', 'cashout_cancelled')
     and from_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    if v_prior.related_cashout_id is distinct from p_cashout_id then
      raise exception 'Operation ID belongs to a different cashout' using errcode = '22023';
    end if;
    return jsonb_build_object('success', true, 'replayed', true,
      'cashout_id', v_prior.related_cashout_id, 'amount', v_prior.amount);
  end if;

  select * into v_req from cashout_requests where id = p_cashout_id for update;
  if not found then
    return jsonb_build_object('success', false, 'error', 'That Cash Out Could Not Be Found');
  end if;
  if v_req.status <> 'pending' then
    return jsonb_build_object('success', false,
      'error', 'That Cash Out Has Already Been Dealt With',
      'current_status', v_req.status);
  end if;

  v_is_player := (v_req.player_id = v_actor);
  if not v_is_player
     and v_req.agent_id <> v_actor
     and not public.fn_club_cashier_can_transact(v_req.club_id, v_actor, v_req.player_id) then
    return jsonb_build_object('success', false,
      'error', 'That Cash Out Belongs To A Different Agent');
  end if;

  select * into v_escrow from chip_escrow where cashout_request_id = p_cashout_id for update;
  if not found or v_escrow.released_at is not null then
    return jsonb_build_object('success', false,
      'error', 'Those Chips Are Not Held In Escrow, So Nothing Can Be Returned');
  end if;

  if v_escrow.amount is distinct from v_req.amount then
    return jsonb_build_object('success', false,
      'error', 'That Cash Out Does Not Match The Chips Held For It');
  end if;

  v_type   := case when v_is_player then 'cashout_cancelled' else 'cashout_denied' end;
  v_status := case when v_is_player then 'cancelled' else 'rejected' end;

  perform public.fn_ca_declare_ledger('escrow_release', 'escrow', v_escrow.id, null,
    'cashout:' || p_cashout_id::text || ':release', null);

  update club_members
     set chip_balance = coalesce(chip_balance, 0) + v_escrow.amount,
         updated_at = now()
   where club_id = v_req.club_id and user_id = v_req.player_id
   returning chip_balance into v_after;
  if v_after is null then
    insert into club_members (club_id, user_id, role, chip_balance, status, is_active)
    values (v_req.club_id, v_req.player_id, 'player', v_escrow.amount, 'active', true)
    on conflict (club_id, user_id) do update
      set chip_balance = coalesce(club_members.chip_balance, 0) + excluded.chip_balance,
          updated_at = now()
    returning chip_balance into v_after;
  end if;

  perform set_config('app.ledger_category', coalesce(v_old_category, ''), true);
  perform set_config('app.ledger_counterparty', coalesce(v_old_counterparty, ''), true);
  perform set_config('app.ledger_counterparty_entity', coalesce(v_old_entity, ''), true);
  perform set_config('app.ledger_idempotency_key', coalesce(v_old_key, ''), true);

  update chip_escrow
     set released_at = now(),
         release_type = case when v_is_player then 'cancelled' else 'rejected' end
   where id = v_escrow.id;

  update cashout_requests
     set status = v_status,
         agent_note  = case when v_is_player then agent_note
                            else coalesce(nullif(btrim(p_note), ''), agent_note) end,
         player_note = case when v_is_player
                            then coalesce(nullif(btrim(p_note), ''), player_note)
                            else player_note end,
         cancelled_at = now(),
         updated_at = now()
   where id = p_cashout_id;

  insert into chip_transactions
      (club_id, from_user_id, to_user_id, amount, transaction_type, notes,
       related_cashout_id, metadata, balance_after)
    values
      (v_req.club_id, v_actor, v_req.player_id, v_escrow.amount, v_type,
       coalesce(nullif(btrim(p_note), ''), 'Cash Out Closed. Chips Returned From Escrow'),
       p_cashout_id,
       jsonb_build_object('op_id', v_op_id, 'closed_by', v_actor,
                          'player_balance_after', v_after),
       v_after);


  if not v_is_player then
    select coalesce(nullif(btrim(pr.display_name), ''),
                    nullif(btrim(pr.alias), ''),
                    nullif(btrim(pr.username), ''), 'Your Agent')
      into v_name
      from profiles pr where pr.id = v_actor;

    insert into notifications (user_id, type, title, message, metadata, actor_id)
    values (v_req.player_id, 'settlement', 'Cash Out Declined',
            coalesce(v_name, 'Your Agent') || ' Declined Your Cash Out. '
              || trim(to_char(v_escrow.amount, 'FM999,999,999,990')) || ' Chips Are Back In Your Wallet',
            jsonb_build_object('clubId', v_req.club_id, 'cashoutId', p_cashout_id,
                               'amount', v_escrow.amount),
            v_actor);

  elsif v_req.agent_id is not null then
    select coalesce(nullif(btrim(pr.display_name), ''),
                    nullif(btrim(pr.alias), ''),
                    nullif(btrim(pr.username), ''), 'A Player')
      into v_name
      from profiles pr where pr.id = v_req.player_id;

    insert into notifications (user_id, type, title, message, metadata, actor_id)
    values (v_req.agent_id, 'settlement', 'Cash Out Withdrawn',
            coalesce(v_name, 'A Player') || ' Withdrew A Cash Out Request For '
              || trim(to_char(v_escrow.amount, 'FM999,999,999,990')) || ' Chips',
            jsonb_build_object('clubId', v_req.club_id, 'cashoutId', p_cashout_id,
                               'amount', v_escrow.amount),
            v_req.player_id);
  end if;

  return jsonb_build_object('success', true, 'replayed', false,
    'cashout_id', p_cashout_id, 'amount', v_escrow.amount,
    'club_id', v_req.club_id,
    'player_id', v_req.player_id,
    'agent_id', v_req.agent_id,
    'cancelled_by_player', v_is_player,
    'player_balance_after', v_after);
end
$$;


ALTER FUNCTION public.fn_cashout_release(p_cashout_id uuid, p_note text, p_op_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_cashout_release(p_cashout_id uuid, p_note text, p_op_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cashout_release(p_cashout_id uuid, p_note text, p_op_id uuid) IS 'Deny (agent or staff) or cancel (the player): escrow returns to the player wallet and the ledger says which it was.';


--
-- Name: fn_cashout_request(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashout_request(p_club_id uuid, p_amount numeric, p_note text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor   uuid := auth.uid();
  v_op_id   uuid := coalesce(p_op_id, gen_random_uuid());
  v_old_category text := current_setting('app.ledger_category', true);
  v_old_counterparty text := current_setting('app.ledger_counterparty', true);
  v_old_entity text := current_setting('app.ledger_counterparty_entity', true);
  v_old_key text := current_setting('app.ledger_idempotency_key', true);
  v_prior   record;
  v_agent   uuid;
  v_before  numeric;
  v_after   numeric;
  v_cashout uuid := gen_random_uuid();
  v_escrow_id uuid := gen_random_uuid();
  v_name    text;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  -- Serialize a caller's retries before consulting the committed receipt.
  perform pg_advisory_xact_lock(hashtextextended('cashout-op:' || v_actor::text || ':' || v_op_id::text, 0));

  select id, amount, related_cashout_id, metadata into v_prior
    from chip_transactions
   where club_id = p_club_id
     and transaction_type = 'cashout_request_escrow'
     and from_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    if v_prior.amount is distinct from p_amount then
      raise exception 'Operation ID belongs to a different cashout amount' using errcode = '22023';
    end if;
    return jsonb_build_object('success', true, 'replayed', true,
      'cashout_id', v_prior.related_cashout_id,
      'amount', v_prior.amount,
      'agent_id', v_prior.metadata ->> 'agent_id');
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false, 'error', 'Chips Move In Hundredths At Most');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Request Limit');
  end if;

  select coalesce(cm.chip_balance, 0), cm.agent_id
    into v_before, v_agent
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = v_actor
     and coalesce(cm.status, 'active') in ('active', 'approved')
   for update;
  if v_before is null then
    return jsonb_build_object('success', false,
      'error', 'You Are Not An Active Member Of This Club');
  end if;
  if v_before < p_amount then
    return jsonb_build_object('success', false,
      'error', 'You Only Hold ' || trim(to_char(v_before, 'FM999,999,999,990.00')) || ' Chips',
      'balance', v_before, 'requested', p_amount);
  end if;

  if v_agent is null then
    select c.owner_id into v_agent from clubs c where c.id = p_club_id;
  end if;
  if v_agent is null then
    select cm.user_id into v_agent
      from club_members cm
     where cm.club_id = p_club_id
       and cm.role in ('owner', 'co_owner', 'admin', 'super_agent', 'agent')
     order by case cm.role
                when 'owner' then 1 when 'co_owner' then 2 when 'admin' then 3
                when 'super_agent' then 4 else 5 end
     limit 1;
  end if;
  if v_agent is null then
    return jsonb_build_object('success', false,
      'error', 'This Club Has Nobody Who Can Approve A Cash Out');
  end if;
  if v_agent = v_actor then
    return jsonb_build_object('success', false,
      'error', 'You Cannot Request A Cash Out From Yourself');
  end if;

  if exists (select 1 from cashout_requests
              where club_id = p_club_id and player_id = v_actor and status = 'pending') then
    return jsonb_build_object('success', false,
      'error', 'You Already Have A Cash Out Waiting. Wait For It Or Cancel It First');
  end if;

  perform public.fn_ca_declare_ledger('escrow_hold', 'escrow', v_escrow_id, null,
    'cashout:' || v_cashout::text || ':hold', null);

  update club_members
     set chip_balance = coalesce(chip_balance, 0) - p_amount,
         updated_at = now()
   where club_id = p_club_id and user_id = v_actor
   returning chip_balance into v_after;

  perform set_config('app.ledger_category', coalesce(v_old_category, ''), true);
  perform set_config('app.ledger_counterparty', coalesce(v_old_counterparty, ''), true);
  perform set_config('app.ledger_counterparty_entity', coalesce(v_old_entity, ''), true);
  perform set_config('app.ledger_idempotency_key', coalesce(v_old_key, ''), true);

  insert into cashout_requests (id, club_id, player_id, agent_id, amount, status, player_note)
  values (v_cashout, p_club_id, v_actor, v_agent, p_amount, 'pending', nullif(btrim(p_note), ''))
  returning id into v_cashout;

  insert into chip_escrow (id, cashout_request_id, player_id, amount, club_id, locked_at)
  values (v_escrow_id, v_cashout, v_actor, p_amount, p_club_id, now());

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes,
     related_cashout_id, metadata, balance_after)
  values
    (p_club_id, v_actor, v_agent, p_amount, 'cashout_request_escrow',
     coalesce(nullif(btrim(p_note), ''), 'Cash Out Requested. Chips Held In Escrow'),
     v_cashout,
     jsonb_build_object('op_id', v_op_id, 'agent_id', v_agent,
                        'player_balance_after', v_after),
     v_after);

  select coalesce(nullif(btrim(pr.display_name), ''),
                  nullif(btrim(pr.alias), ''),
                  nullif(btrim(pr.username), ''), 'A Player')
    into v_name
    from profiles pr where pr.id = v_actor;

  insert into notifications (user_id, type, title, message, metadata, actor_id)
  values (v_agent, 'settlement', 'Cash Out Requested',
          coalesce(v_name, 'A Player') || ' Requested To Cash Out '
            || trim(to_char(p_amount, 'FM999,999,999,990')) || ' Chips',
          jsonb_build_object('clubId', p_club_id, 'cashoutId', v_cashout,
                             'amount', p_amount, 'playerName', v_name),
          v_actor);

  return jsonb_build_object('success', true, 'replayed', false,
    'cashout_id', v_cashout, 'agent_id', v_agent, 'amount', p_amount,
    'player_name', v_name,
    'player_balance_after', v_after);
end
$$;


ALTER FUNCTION public.fn_cashout_request(p_club_id uuid, p_amount numeric, p_note text, p_op_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_cashout_request(p_club_id uuid, p_amount numeric, p_note text, p_op_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cashout_request(p_club_id uuid, p_amount numeric, p_note text, p_op_id uuid) IS 'Player asks to cash out: debits their balance into escrow, opens the request, notifies the agent.';


--
-- Name: fn_cashout_seats_for_closing_table(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashout_seats_for_closing_table(p_table_id uuid, p_reason text DEFAULT 'table closed'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_tournament boolean;
  v_seat          record;
  v_club          uuid;
  v_res           jsonb;
  v_count         int := 0;
  v_total         numeric := 0;
BEGIN
  IF p_table_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'p_table_id required');
  END IF;

  SELECT (t.tournament_id IS NOT NULL) INTO v_is_tournament
    FROM public.tables t WHERE t.id = p_table_id;

  IF v_is_tournament IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;

  IF v_is_tournament THEN
    RETURN jsonb_build_object('ok', true, 'skipped', 'tournament_table');
  END IF;

  FOR v_seat IN
    SELECT id, user_id, seat_number, stack, club_id
      FROM public.table_seats
     WHERE table_id = p_table_id
       AND left_at IS NULL
       AND user_id IS NOT NULL
       AND COALESCE(stack, 0) > 0
     FOR UPDATE
  LOOP
    v_club := v_seat.club_id;
    IF v_club IS NULL THEN
      v_club := public.fn_player_home_club(v_seat.user_id, NULL);
    END IF;

    IF v_club IS NULL THEN
      CONTINUE;
    END IF;

    PERFORM public.fn_ensure_club_wallet(v_seat.user_id, v_club);

    PERFORM public.fn_ca_declare_ledger('table_cashout', 'table_stack', p_table_id);

    -- CHIP CONTINUITY: a table close is a system exit, never the player's choice.
    v_res := public.atomic_seat_cashout_locked(v_seat.user_id, p_table_id, v_seat.seat_number, 'forced');

    IF COALESCE((v_res->>'credited')::boolean, false) THEN
      v_count := v_count + 1;
      v_total := v_total + COALESCE((v_res->>'stack')::numeric, 0);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'players_paid', v_count, 'chips_returned', v_total,
                            'reason_text', COALESCE(p_reason, 'table closed'));
END;
$$;


ALTER FUNCTION public.fn_cashout_seats_for_closing_table(p_table_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: fn_cast_tournament_deal_vote(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cast_tournament_deal_vote(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_inserted integer;
  v_wake_id bigint;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE='42501';
  END IF;
  PERFORM 1
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
     AND t.status='RUNNING'
     AND coalesce(t.final_table_deal_enabled,false)
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','deal_vote_not_open');
  END IF;
  PERFORM 1
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.user_id=v_user_id
     AND tp.status IN ('registered','playing')
     AND tp.eliminated_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','voter_not_alive');
  END IF;

  INSERT INTO public.tournament_deal_votes(tournament_id,user_id)
  VALUES (p_tournament_id,v_user_id)
  ON CONFLICT (tournament_id,user_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  -- Emit on exact replay too. This closes the rolling-deploy case where an old
  -- client inserted the vote directly but no durable wake accompanied it.
  v_wake_id := public.fn_emit_tournament_manager_wake(p_tournament_id,'deal_vote');
  RETURN jsonb_build_object(
    'ok',true,'voted',true,'already',v_inserted=0,'wake_id',v_wake_id);
END;
$$;


ALTER FUNCTION public.fn_cast_tournament_deal_vote(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_certify_tournament_finish(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_certify_tournament_finish(p_tournament_id uuid, p_winner_user_id uuid, p_source text DEFAULT 'engine'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_finish public.tournament_finish_receipts%ROWTYPE;
  v_ready jsonb;
BEGIN
  IF p_tournament_id IS NULL OR p_winner_user_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'certified',false,'reason','missing_ids');
  END IF;
  SELECT * INTO v_t FROM public.tournaments
   WHERE id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'certified',false,'reason','tournament_not_found');
  END IF;
  SELECT * INTO v_finish FROM public.tournament_finish_receipts
   WHERE tournament_id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'certified',false,
      'reason','finish_certificate_missing','status',v_t.status,'rows_updated',0);
  END IF;
  IF v_finish.winner_user_id IS DISTINCT FROM p_winner_user_id THEN
    RETURN jsonb_build_object('ok',false,'certified',false,
      'reason','canonical_winner_conflict','winner_user_id',v_finish.winner_user_id,
      'finish_kind',v_finish.finish_kind,'status',v_t.status,'rows_updated',0);
  END IF;
  IF v_t.status <> 'COMPLETED' THEN
    RETURN jsonb_build_object('ok',false,'certified',false,
      'reason','domain_settlement_required','winner_user_id',v_finish.winner_user_id,
      'finish_kind',v_finish.finish_kind,'status',v_t.status,'rows_updated',0,
      'already_completed',false);
  END IF;
  IF v_finish.certified_at IS NULL OR v_finish.completed_at IS NULL
     OR v_finish.evidence IS NULL THEN
    RETURN jsonb_build_object('ok',false,'certified',false,
      'reason','completed_without_certificate','winner_user_id',v_finish.winner_user_id,
      'finish_kind',v_finish.finish_kind,'status',v_t.status,'rows_updated',0,
      'already_completed',true);
  END IF;

  -- Re-read the proof as a defence against privileged post-completion drift.
  -- The atomic domain migrations freeze their plan, results and obligation
  -- ledger, so this is a pure verification pass and can never repair money.
  v_ready := public.fn_tournament_finish_readiness(p_tournament_id,p_winner_user_id);
  IF COALESCE((v_ready->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN jsonb_build_object('ok',false,'certified',false,
      'reason','certificate_evidence_no_longer_valid','winner_user_id',v_finish.winner_user_id,
      'finish_kind',v_finish.finish_kind,'status',v_t.status,'rows_updated',0,
      'already_completed',true,'evidence',v_ready);
  END IF;

  RETURN jsonb_build_object('ok',true,'certified',true,'reason',NULL,
    'status','COMPLETED','rows_updated',0,'already_completed',true,
    'winner_user_id',p_winner_user_id,'finish_kind',v_finish.finish_kind,
    'evidence',v_finish.evidence,
    'requested_by',COALESCE(NULLIF(btrim(p_source),''),'engine'));
END;
$$;


ALTER FUNCTION public.fn_certify_tournament_finish(p_tournament_id uuid, p_winner_user_id uuid, p_source text) OWNER TO postgres;

--
-- Name: fn_charge_place_overpays(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_charge_place_overpays(p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_club record; v_res jsonb;
  v_charged numeric := 0; v_clubs integer := 0;
  v_blocked numeric := 0; v_blocked_clubs integer := 0;
  v_owed_before numeric; v_owed_after numeric;
BEGIN
  INSERT INTO public.tournament_place_overpay_charges
    (tournament_id, club_id, user_id, old_position, new_position,
     prize_paid, entitled, overpaid)
  SELECT r.tournament_id, t.club_id, r.user_id, r.old_position, r.new_position,
         r.prize_paid,
         public.fn_place_entitlement(t.prize_pool, t.payout_structure, r.new_position),
         round(GREATEST(r.prize_paid - public.fn_place_entitlement(
           t.prize_pool, t.payout_structure, r.new_position), 0), 2)
    FROM public.tournament_place_renumbers r
    JOIN public.tournaments t ON t.id = r.tournament_id
  ON CONFLICT (tournament_id, user_id) DO NOTHING;

  SELECT COALESCE(sum(overpaid), 0) INTO v_owed_before
    FROM public.tournament_place_overpay_charges
   WHERE charged_at IS NULL AND overpaid > 0.005;

  FOR v_club IN
    SELECT club_id, round(sum(overpaid), 2) AS owed
      FROM public.tournament_place_overpay_charges
     WHERE charged_at IS NULL AND overpaid > 0.005 AND club_id IS NOT NULL
     GROUP BY club_id
     ORDER BY 2 DESC
     LIMIT GREATEST(p_limit, 1)
  LOOP
    v_res := public.fn_debit_treasury(
      v_club.club_id, v_club.owed,
      'Duplicate finishing place paid twice; overpay absorbed by club treasury',
      jsonb_build_object('source', 'fn_charge_place_overpays'));

    IF COALESCE((v_res->>'success')::boolean, false) THEN
      UPDATE public.tournament_place_overpay_charges
         SET charged_at = now()
       WHERE club_id = v_club.club_id AND charged_at IS NULL AND overpaid > 0.005;
      v_charged := v_charged + v_club.owed;
      v_clubs := v_clubs + 1;
    ELSE
      v_blocked := v_blocked + v_club.owed;
      v_blocked_clubs := v_blocked_clubs + 1;
    END IF;
  END LOOP;

  -- Second measurement. A pass that says it charged something must also be
  -- able to show the queue got smaller.
  SELECT COALESCE(sum(overpaid), 0) INTO v_owed_after
    FROM public.tournament_place_overpay_charges
   WHERE charged_at IS NULL AND overpaid > 0.005;

  RETURN jsonb_build_object('ok', true,
    'owed_before', round(v_owed_before, 2), 'owed_after', round(v_owed_after, 2),
    'charged', round(v_charged, 2), 'clubs_charged', v_clubs,
    'blocked_insufficient_treasury', round(v_blocked, 2),
    'clubs_blocked', v_blocked_clubs);
END;
$$;


ALTER FUNCTION public.fn_charge_place_overpays(p_limit integer) OWNER TO postgres;

--
-- Name: fn_check_anti_farming_gift_cap(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_check_anti_farming_gift_cap(p_sender_id uuid, p_recipient_id uuid, p_amount integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 DECLARE
   v_pair_24h              bigint;
   v_total_24h             bigint;
   v_burst_60s             bigint;
   v_fresh_paid_24h        bigint;
   v_active_ban            boolean;
   v_is_flagged            boolean;
   v_created_at            timestamptz;
   v_first_purchase_at     timestamptz;
   v_account_age_days      numeric;
   v_days_since_purchase   numeric;
   v_lift_via_age          timestamptz;
   v_lift_via_purchase     timestamptz;
   v_lift_at               timestamptz;
   v_lift_date_str         text;
   v_lift_msg              text;
   CAP_PER_PAIR_24H        constant integer := 5000;
   CAP_PER_USER_24H        constant integer := 50000;
   CAP_BURST_60S           constant integer := 2000;
   CAP_FRESH_PAID_24H      constant integer := 500;
   TRUST_AGE_DAYS          constant integer := 120;
   NEW_USER_DAYS           constant integer := 30;
   PURCHASE_COOLDOWN_DAYS  constant integer := 7;
 BEGIN
   -- ── Argument validation ─────────────────────────────────────────────────
   IF p_sender_id IS NULL OR p_recipient_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
     RETURN jsonb_build_object(
       'allowed', false,
       'reason', 'Invalid Arguments',
       'code', 'invalid_args',
       'title', 'Invalid Request',
       'popup_message', 'The Request Is Missing Required Information',
       'popup_explanation', 'Please Refresh The Page And Try Again'
     );
   END IF;
   IF p_sender_id = p_recipient_id THEN
     RETURN jsonb_build_object(
       'allowed', false,
       'reason', 'Cannot Send To Self',
       'code', 'self_transfer',
       'title', 'Cannot Send To Yourself',
       'popup_message', 'You Cannot Send Diamonds To Your Own Account',
       'popup_explanation', 'Please Choose A Different Recipient'
     );
   END IF;

   -- DIAMOND-RULINGS 12: the hard-coded exempt account is gone. An account that is to be
   -- exempt from this ladder is a row in a table Dan owns, with a reason, never a literal
   -- in a function body that nothing outside it can see.

   -- ── Banned-by-recipient ─────────────────────────────────────────────────
   SELECT EXISTS (
     SELECT 1 FROM live_bans lb
       JOIN live_streams ls ON ls.id = lb.stream_id
      WHERE lb.banned_user_id = p_sender_id
        AND ls.broadcaster_id = p_recipient_id
   ) INTO v_active_ban;
   IF v_active_ban THEN
     RETURN jsonb_build_object(
       'allowed', false,
       'reason', 'You Are Banned From This Broadcaster',
       'code', 'banned_by_recipient',
       'title', 'You Are Banned',
       'popup_message', 'This Broadcaster Has Banned You From Sending Gifts',
       'popup_explanation', 'You Will Need To Contact The Broadcaster Directly To Request An Unban'
     );
   END IF;

   -- ── Load sender state ───────────────────────────────────────────────────
   SELECT COALESCE(is_farming_flagged, false), created_at
     INTO v_is_flagged, v_created_at
     FROM profiles WHERE id = p_sender_id;

   -- ── Compute lift timestamps (used by any blocked path below) ────────────
   IF v_is_flagged IS NOT TRUE THEN
     SELECT MIN(completed_at) INTO v_first_purchase_at
       FROM diamond_purchases
       WHERE user_id = p_sender_id
         AND status = 'completed'
         AND refunded_at IS NULL;

     v_account_age_days := CASE
       WHEN v_created_at IS NULL THEN 0
       ELSE EXTRACT(epoch FROM (now() - v_created_at)) / 86400
     END;
     v_days_since_purchase := CASE
       WHEN v_first_purchase_at IS NULL THEN NULL
       ELSE EXTRACT(epoch FROM (now() - v_first_purchase_at)) / 86400
     END;

     v_lift_via_age := CASE
       WHEN v_created_at IS NULL THEN NULL
       ELSE v_created_at + make_interval(days => TRUST_AGE_DAYS)
     END;
     v_lift_via_purchase := CASE
       WHEN v_first_purchase_at IS NULL THEN NULL
       ELSE v_first_purchase_at + make_interval(days => PURCHASE_COOLDOWN_DAYS)
     END;
     v_lift_at := CASE
       WHEN v_lift_via_age IS NOT NULL AND v_lift_via_purchase IS NOT NULL THEN LEAST(v_lift_via_age, v_lift_via_purchase)
       WHEN v_lift_via_purchase IS NOT NULL THEN v_lift_via_purchase
       WHEN v_lift_via_age IS NOT NULL THEN v_lift_via_age
       ELSE NULL
     END;
   ELSE
     v_lift_at := NULL;  -- flagged: requires admin action
   END IF;

   -- DIAMOND-RULINGS 4, with CLAUDE.md 10.86: there is no lift any more, so this stops
   -- answering with a date. A field that names a day nothing will happen on is worse than an
   -- empty one - it is the shape of a signal that answers when it does not know.
   v_lift_at := NULL;

   -- Title-Cased lift date string ("Your Limits Are Fully Lifted On May 19, 2026")
   v_lift_msg := CASE
     WHEN v_is_flagged THEN 'Your Account Has Restrictions That Require Admin Review To Lift'
     WHEN false THEN ''
     ELSE
       'Your Sending Limits Are Per Recipient, Per Day And Per Minute, And They Apply To Every Account'
   END;

   -- ── Trust ladder (only for unflagged senders) ───────────────────────────
   IF v_is_flagged IS NOT TRUE THEN
     -- DIAMOND-RULINGS 4: the two waivers are removed. Tier 4 lifted every cap seven days
     -- after the cheapest purchase a farmer can make, and tier 5 lifted them for any account
     -- that had simply existed for 120 days. Age is not trust and a receipt is not trust; the
     -- pair, user and burst caps below are what this ladder is for, and they cost a real
     -- player nothing.

     -- Tier 6: <30d + paid + <7d since purchase → 500/24h cap (with popup)
     IF v_account_age_days < NEW_USER_DAYS
        AND v_first_purchase_at IS NOT NULL THEN
       SELECT COALESCE(SUM(ABS(amount)), 0) INTO v_fresh_paid_24h
         FROM diamond_transactions
        WHERE user_id = p_sender_id
          AND amount  < 0
          AND created_at > now() - interval '24 hours'
          AND (transaction_type IN ('live_gift_sent','diamond_gift_sent')
            OR source IN ('stream_gift','wallet_transfer','wallet_diamond_transfer'));

       IF v_fresh_paid_24h + p_amount > CAP_FRESH_PAID_24H THEN
         RETURN jsonb_build_object(
           'allowed', false,
           'reason',  format('Fresh-Paid Users Are Capped At %s Diamonds / 24h For The First 7 Days After Purchase', CAP_FRESH_PAID_24H),
           'code',    'fresh_paid_24h_cap',
           'title',   'Daily Limit Reached',
           'popup_message', format('You Have Reached Your Daily %s Diamond Sending Limit', CAP_FRESH_PAID_24H),
           'popup_explanation', format('New Paid Accounts Are Limited To %s Diamonds Per Day During The First 7 Days After Your First Purchase To Protect Against Fraud', CAP_FRESH_PAID_24H),
           'next_send_message', 'You Can Send More Diamonds Tomorrow',
           'limits_lift_at', v_lift_at,
           'limits_lift_message', v_lift_msg,
           'amount_sent_24h', v_fresh_paid_24h,
           'amount_cap_24h', CAP_FRESH_PAID_24H
         );
       END IF;

       RETURN jsonb_build_object(
         'allowed', true,
         'reason',  'fresh_paid_within_500_per_day',
         'code',    'ok'
       );
     END IF;
   END IF;

   -- ── Tier 7: standard pair/user/burst caps (with popups) ─────────────────

   SELECT COALESCE(SUM(ABS(amount)), 0) INTO v_pair_24h
     FROM diamond_transactions
    WHERE user_id = p_sender_id
      AND amount  < 0
      AND created_at > now() - interval '24 hours'
      AND metadata->>'recipient_id' = p_recipient_id::text
      AND (transaction_type IN ('live_gift_sent','diamond_gift_sent')
        OR source IN ('stream_gift','wallet_transfer','wallet_diamond_transfer'));
   IF v_pair_24h + p_amount > CAP_PER_PAIR_24H THEN
     RETURN jsonb_build_object(
       'allowed', false,
       'reason', format('Pair Limit Hit (%s Diamonds / 24h To This User)', CAP_PER_PAIR_24H),
       'code', 'pair_24h_cap',
       'title', 'Pair Limit Reached',
       'popup_message', format('You Have Sent %s Diamonds To This User In The Last 24 Hours', CAP_PER_PAIR_24H),
       'popup_explanation', format('You Can Send Up To %s Diamonds Per User Per Day While Your Account Is Not Yet Fully Trusted', CAP_PER_PAIR_24H),
       'next_send_message', 'You Can Send More Diamonds To This User Tomorrow',
       'limits_lift_at', v_lift_at,
       'limits_lift_message', v_lift_msg,
       'amount_sent_24h', v_pair_24h,
       'amount_cap_24h', CAP_PER_PAIR_24H
     );
   END IF;

   SELECT COALESCE(SUM(ABS(amount)), 0) INTO v_total_24h
     FROM diamond_transactions
    WHERE user_id = p_sender_id
      AND amount  < 0
      AND created_at > now() - interval '24 hours'
      AND (transaction_type IN ('live_gift_sent','diamond_gift_sent')
        OR source IN ('stream_gift','wallet_transfer','wallet_diamond_transfer'));
   IF v_total_24h + p_amount > CAP_PER_USER_24H THEN
     RETURN jsonb_build_object(
       'allowed', false,
       'reason', format('Daily Limit Hit (%s Diamonds / 24h)', CAP_PER_USER_24H),
       'code', 'user_24h_cap',
       'title', 'Daily Limit Reached',
       'popup_message', format('You Have Sent %s Diamonds Total In The Last 24 Hours', CAP_PER_USER_24H),
       'popup_explanation', format('Your Account Can Send Up To %s Diamonds Per Day Until It Is Fully Trusted', CAP_PER_USER_24H),
       'next_send_message', 'You Can Send More Diamonds Tomorrow',
       'limits_lift_at', v_lift_at,
       'limits_lift_message', v_lift_msg,
       'amount_sent_24h', v_total_24h,
       'amount_cap_24h', CAP_PER_USER_24H
     );
   END IF;

   SELECT COALESCE(SUM(ABS(amount)), 0) INTO v_burst_60s
     FROM diamond_transactions
    WHERE user_id = p_sender_id
      AND amount  < 0
      AND created_at > now() - interval '60 seconds'
      AND (transaction_type IN ('live_gift_sent','diamond_gift_sent')
        OR source IN ('stream_gift','wallet_transfer','wallet_diamond_transfer'));
   IF v_burst_60s + p_amount > CAP_BURST_60S THEN
     RETURN jsonb_build_object(
       'allowed', false,
       'reason', format('Slow Down - %s Diamonds In 60s Is Too Fast', CAP_BURST_60S),
       'code', 'burst_cap',
       'title', 'Sending Too Fast',
       'popup_message', format('You Have Sent %s Diamonds In The Last 60 Seconds', CAP_BURST_60S),
       'popup_explanation', format('Please Wait A Few Seconds Between Gifts To Avoid Hitting The %s Diamond Burst Limit', CAP_BURST_60S),
       'next_send_message', 'You Can Send More In About A Minute',
       'limits_lift_at', v_lift_at,
       'limits_lift_message', v_lift_msg,
       'amount_sent_60s', v_burst_60s,
       'amount_cap_60s', CAP_BURST_60S
     );
   END IF;

   RETURN jsonb_build_object('allowed', true, 'reason', 'within_caps', 'code', 'ok');
 END;
 $$;


ALTER FUNCTION public.fn_check_anti_farming_gift_cap(p_sender_id uuid, p_recipient_id uuid, p_amount integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_check_anti_farming_gift_cap(p_sender_id uuid, p_recipient_id uuid, p_amount integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_check_anti_farming_gift_cap(p_sender_id uuid, p_recipient_id uuid, p_amount integer) IS 'Anti-farming limits with rich popups';


--
-- Name: fn_check_atomic_final_table_deal(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_check_atomic_final_table_deal(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_t                         record;
  v_batch                     public.tournament_final_table_deal_batches%ROWTYPE;
  v_line_count                integer := 0;
  v_place_lines               integer := 0;
  v_deal_lines                integer := 0;
  v_distinct_places           integer := 0;
  v_distinct_deal_users       integer := 0;
  v_distinct_deal_ranks       integer := 0;
  v_min_deal_rank             integer := 0;
  v_max_deal_rank             integer := 0;
  v_place_cents               bigint := 0;
  v_deal_cents                bigint := 0;
  v_obligation_mismatches     integer := 0;
  v_extra_obligations         integer := 0;
  v_evidence_mismatches       integer := 0;
  v_unexpected_place_evidence integer := 0;
  v_unexpected_deal_evidence  integer := 0;
  v_prize_mismatches          integer := 0;
  v_standing_mismatches       integer := 0;
  v_prior_count               integer := 0;
  v_prior_missing_bust_time   integer := 0;
  v_prior_canonical_mismatches integer := 0;
  v_prior_standings_fingerprint text;
  v_player_count              integer := 0;
  v_unranked                  integer := 0;
  v_distinct_positions        integer := 0;
  v_min_position              integer := 0;
  v_max_position              integer := 0;
  v_winners                   integer := 0;
  v_winner_at_one             integer := 0;
  v_nonterminal               integer := 0;
  v_missing_bust_time         integer := 0;
  v_snapshot_count            integer := 0;
  v_snapshot_distinct_players integer := 0;
  v_snapshot_distinct_users   integer := 0;
  v_snapshot_distinct_seats   integer := 0;
  v_snapshot_wrong_tables     integer := 0;
  v_snapshot_input_mismatches integer := 0;
  v_snapshot_share_mismatches integer := 0;
  v_bubble_user               uuid;
  v_bubble_holders            integer := 0;
  v_bubble_obligations        integer := 0;
  v_bubble_matching           integer := 0;
  v_bubble_owed               numeric := 0;
  v_bubble_paid               numeric := 0;
  v_bubble_evidence           numeric := 0;
  v_bubble_conflicts          integer := 0;
  v_bubble_obligation_id      uuid;
  v_bubble_source             text;
  v_bubble_settled_at         timestamptz;
  v_bubble_obligation_present boolean := false;
  v_bubble_payout_present     boolean := false;
  v_bubble_required           boolean := false;
  v_bubble_shape_valid        boolean := false;
  v_escrow                    public.tournament_escrow%ROWTYPE;
BEGIN
  IF p_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_id_required');
  END IF;

  SELECT t.id, t.status, round(COALESCE(t.prize_pool, 0), 2) AS prize_pool,
         round(COALESCE(t.guaranteed_prize, 0), 2) AS guaranteed_prize,
         COALESCE(t.prize_pool_finalized, false) AS prize_pool_finalized,
         COALESCE(t.bubble_protection, false) AS bubble_protection,
         round(COALESCE(t.buy_in_amount, 0), 2) AS buy_in_amount
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
  END IF;

  SELECT * INTO v_batch
    FROM public.tournament_final_table_deal_batches b
   WHERE b.tournament_id = p_tournament_id;
  IF NOT FOUND OR v_batch.settled_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_batch_is_not_settled');
  END IF;
  IF md5(v_batch.live_input_snapshot::text)
       <> v_batch.live_input_fingerprint THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'atomic_deal_live_input_fingerprint_changed');
  END IF;
  IF md5(jsonb_build_object(
                            'bubble_contract_required', v_batch.bubble_contract_required,
                            'bubble_obligation_id', v_batch.bubble_obligation_id,
                            'bubble_user_id', v_batch.bubble_user_id,
                            'bubble_source', v_batch.bubble_source,
                            'bubble_amount_owed',
                              round(COALESCE(v_batch.bubble_amount_owed, 0) * 100)::bigint,
                            'bubble_amount_paid_before',
                              round(COALESCE(v_batch.bubble_amount_paid_before, 0) * 100)::bigint,
                            'deal_table_id', v_batch.deal_table_id,
                            'live_input_fingerprint', v_batch.live_input_fingerprint,
                            'prior_standings_fingerprint',
                              v_batch.prior_standings_fingerprint,
                            'plan', v_batch.plan)::text)
       <> v_batch.plan_fingerprint THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_plan_fingerprint_changed');
  END IF;
  IF NOT v_t.prize_pool_finalized
     OR v_t.prize_pool + 0.005 < v_t.guaranteed_prize THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'prize_pool_is_not_funded_and_finalized');
  END IF;

  SELECT * INTO v_escrow
    FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id;
  IF NOT FOUND OR NOT v_escrow.enforced
     OR v_batch.escrow_prize_after IS NULL
     OR abs(v_batch.escrow_prize_before - v_batch.amount_moved
            - v_batch.escrow_prize_after) > 0.005
     OR abs(round(v_escrow.prize_balance, 2)
            - v_batch.escrow_prize_after) > 0.005 THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'atomic_deal_escrow_proof_is_invalid');
  END IF;

  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(v_batch.plan) e
     WHERE jsonb_typeof(e) <> 'object'
        OR COALESCE(e->>'kind', '') NOT IN ('place', 'final_table_deal')
        OR COALESCE(e->>'user_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR COALESCE(e->>'cents', '') !~ '^[0-9]+$'
        OR ((e->>'kind') = 'place'
            AND (COALESCE(e->>'place', '') !~ '^[1-9][0-9]*$'
                 OR e->>'rank' IS NOT NULL))
        OR ((e->>'kind') = 'final_table_deal'
            AND (e->>'place' IS NOT NULL
                 OR COALESCE(e->>'rank', '') !~ '^[1-9][0-9]*$'))
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_plan_is_malformed');
  END IF;

  SELECT count(*),
         count(*) FILTER (WHERE x.kind = 'place'),
         count(*) FILTER (WHERE x.kind = 'final_table_deal'),
         count(DISTINCT x.place) FILTER (WHERE x.kind = 'place'),
         count(DISTINCT x.user_id) FILTER (WHERE x.kind = 'final_table_deal'),
         count(DISTINCT x.rank) FILTER (WHERE x.kind = 'final_table_deal'),
         COALESCE(min(x.rank) FILTER (WHERE x.kind = 'final_table_deal'), 0),
         COALESCE(max(x.rank) FILTER (WHERE x.kind = 'final_table_deal'), 0),
         COALESCE(sum(x.cents) FILTER (WHERE x.kind = 'place'), 0),
         COALESCE(sum(x.cents) FILTER (WHERE x.kind = 'final_table_deal'), 0)
    INTO v_line_count, v_place_lines, v_deal_lines, v_distinct_places,
         v_distinct_deal_users, v_distinct_deal_ranks,
         v_min_deal_rank, v_max_deal_rank, v_place_cents, v_deal_cents
    FROM jsonb_to_recordset(v_batch.plan)
      AS x(kind text, place integer, user_id uuid, cents bigint, rank integer);

  IF v_line_count <> v_batch.place_line_count + v_batch.deal_line_count
     OR v_place_lines <> v_batch.place_line_count
     OR v_deal_lines <> v_batch.deal_line_count
     OR v_distinct_places <> v_place_lines
     OR v_distinct_deal_users <> v_deal_lines
     OR v_distinct_deal_ranks <> v_deal_lines
     OR v_min_deal_rank <> 1 OR v_max_deal_rank <> v_deal_lines
     OR v_deal_lines <> v_batch.live_count
     OR v_place_cents <> round(v_batch.place_amount * 100)::bigint
     OR v_deal_cents <> round(v_batch.deal_amount * 100)::bigint
     OR v_place_cents + v_deal_cents <> round(v_batch.amount_owed * 100)::bigint
     OR round(v_batch.amount_owed * 100)::bigint <> round(v_t.prize_pool * 100)::bigint
     OR NOT EXISTS (
       SELECT 1
         FROM jsonb_to_recordset(v_batch.plan)
           AS leader(kind text, place integer, user_id uuid, cents bigint, rank integer)
        WHERE leader.kind = 'final_table_deal' AND leader.rank = 1
          AND leader.user_id = v_batch.chip_leader
     ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_header_disagrees_with_plan');
  END IF;

  /* Re-derive every deal share from the frozen pre-deal inputs. The live
     players are terminal by the time this verifier runs, and their physical
     seats may be torn down after completion, so the immutable snapshot is the
     allocation source while the frozen player columns prove that the snapshot
     still names the same chips and tie-break inputs. */
  IF jsonb_array_length(v_batch.live_input_snapshot) <> v_batch.live_count
     OR EXISTS (
       SELECT 1
         FROM jsonb_array_elements(v_batch.live_input_snapshot) e
        WHERE jsonb_typeof(e) <> 'object'
           OR COALESCE(e->>'player_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR COALESCE(e->>'user_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR COALESCE(e->>'seat_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR COALESCE(e->>'table_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR COALESCE(e->>'chips', '') !~ '^[0-9]+([.][0-9]+)?$'
           OR (e->>'chips')::numeric <= 0
           OR COALESCE(e->>'seat_stack', '') !~ '^[0-9]+([.][0-9]+)?$'
           OR (e->>'seat_stack')::numeric IS DISTINCT FROM (e->>'chips')::numeric
           OR COALESCE(e->>'registered_at_utc', '') !~
              '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}$'
           OR COALESCE(e->>'rebuys', '') !~ '^[0-9]+$'
           OR jsonb_typeof(e->'add_on') IS DISTINCT FROM 'boolean'
     ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_live_input_is_malformed');
  END IF;

  SELECT count(*), count(DISTINCT s.player_id), count(DISTINCT s.user_id),
         count(DISTINCT s.seat_id),
         count(*) FILTER (WHERE s.table_id IS DISTINCT FROM v_batch.deal_table_id)
    INTO v_snapshot_count, v_snapshot_distinct_players,
         v_snapshot_distinct_users, v_snapshot_distinct_seats,
         v_snapshot_wrong_tables
    FROM jsonb_to_recordset(v_batch.live_input_snapshot)
      AS s(player_id uuid, user_id uuid, chips numeric,
           registered_at_utc text, rebuys integer, add_on boolean,
           seat_id uuid, table_id uuid, seat_stack numeric);

  SELECT count(*) INTO v_snapshot_input_mismatches
    FROM jsonb_to_recordset(v_batch.live_input_snapshot)
      AS s(player_id uuid, user_id uuid, chips numeric,
           registered_at_utc text, rebuys integer, add_on boolean,
           seat_id uuid, table_id uuid, seat_stack numeric)
    LEFT JOIN public.tournament_players tp
      ON tp.id = s.player_id AND tp.tournament_id = p_tournament_id
     AND tp.user_id = s.user_id
   WHERE tp.id IS NULL
      OR tp.chips IS DISTINCT FROM s.chips
      OR to_char(tp.registered_at AT TIME ZONE 'UTC',
                 'YYYY-MM-DD"T"HH24:MI:SS.US') IS DISTINCT FROM s.registered_at_utc
      OR COALESCE(tp.rebuys, 0) IS DISTINCT FROM s.rebuys
      OR COALESCE(tp.add_on, false) IS DISTINCT FROM s.add_on;

  WITH input AS (
    SELECT s.user_id, s.chips, s.registered_at_utc,
           row_number() OVER (
             ORDER BY s.chips DESC, s.registered_at_utc ASC, s.user_id ASC
           )::integer AS rank,
           floor(s.chips / sum(s.chips) OVER ()
                 * round(v_batch.deal_amount * 100)::bigint)::bigint AS floor_cents
      FROM jsonb_to_recordset(v_batch.live_input_snapshot)
        AS s(player_id uuid, user_id uuid, chips numeric,
             registered_at_utc text, rebuys integer, add_on boolean,
             seat_id uuid, table_id uuid, seat_stack numeric)
  ), expected AS (
    SELECT i.user_id, i.rank,
           i.floor_cents + CASE WHEN i.rank = 1 THEN
             round(v_batch.deal_amount * 100)::bigint
               - sum(i.floor_cents) OVER ()
             ELSE 0 END AS cents
      FROM input i
  ), actual AS (
    SELECT x.user_id, x.rank, x.cents
      FROM jsonb_to_recordset(v_batch.plan)
        AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
     WHERE x.kind = 'final_table_deal'
  )
  SELECT count(*) INTO v_snapshot_share_mismatches
    FROM expected e
    FULL JOIN actual a USING (user_id)
   WHERE e.user_id IS NULL OR a.user_id IS NULL
      OR e.rank IS DISTINCT FROM a.rank
      OR e.cents IS DISTINCT FROM a.cents;

  SELECT count(*) INTO v_obligation_mismatches
    FROM jsonb_to_recordset(v_batch.plan)
      AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
    LEFT JOIN public.tournament_obligations o
      ON o.tournament_id = p_tournament_id
     AND o.kind = x.kind
     AND o.user_id = x.user_id
     AND ((x.kind = 'place' AND o.place = x.place)
          OR (x.kind = 'final_table_deal' AND o.place IS NULL))
   WHERE o.id IS NULL
      OR round(o.amount_owed * 100)::bigint <> x.cents
      OR round(o.amount_paid * 100)::bigint <> x.cents
      OR o.settled_at IS NULL;

  SELECT count(*) INTO v_extra_obligations
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND o.kind IN ('place', 'final_table_deal')
     AND NOT EXISTS (
       SELECT 1
         FROM jsonb_to_recordset(v_batch.plan)
           AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
        WHERE x.kind = o.kind AND x.user_id = o.user_id
          AND ((x.kind = 'place' AND x.place = o.place)
               OR (x.kind = 'final_table_deal' AND o.place IS NULL))
     );

  SELECT count(*) INTO v_evidence_mismatches
    FROM jsonb_to_recordset(v_batch.plan)
      AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
    CROSS JOIN LATERAL (
      SELECT round(COALESCE(sum(p.amount), 0) * 100)::bigint AS cents
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.user_id = x.user_id
         AND ((x.kind = 'place'
               AND p.position = x.place
               AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                                 'late_reg_adjustment', 'clawback', 'spin_backpay',
                                 'overlay_backpay')
                    OR EXISTS (
                      SELECT 1 FROM public.tournament_obligations eo
                       WHERE eo.tournament_id = p_tournament_id
                         AND eo.kind = 'place' AND eo.place = x.place
                         AND eo.user_id = x.user_id
                         AND p.idempotency_key LIKE
                           'tourney:' || p_tournament_id::text || ':obl:' ||
                           eo.id::text || ':%'
                    )))
              OR (x.kind = 'final_table_deal'
                  AND p.position IS NULL
                  AND p.source = 'final_table_deal'))
    ) evidence
   WHERE evidence.cents <> x.cents;

  SELECT count(*) INTO v_unexpected_place_evidence
    FROM (
      SELECT p.position, p.user_id
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.position IS NOT NULL
         AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                           'late_reg_adjustment', 'clawback', 'spin_backpay',
                           'overlay_backpay')
              OR EXISTS (
                SELECT 1 FROM public.tournament_obligations eo
                 WHERE eo.tournament_id = p_tournament_id
                   AND eo.kind = 'place' AND eo.place = p.position
                   AND eo.user_id = p.user_id
                   AND p.idempotency_key LIKE
                     'tourney:' || p_tournament_id::text || ':obl:' ||
                     eo.id::text || ':%'
              ))
       GROUP BY p.position, p.user_id
      HAVING abs(round(sum(p.amount), 2)) > 0.005
    ) evidence
   WHERE NOT EXISTS (
     SELECT 1
       FROM jsonb_to_recordset(v_batch.plan)
         AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
      WHERE x.kind = 'place' AND x.place = evidence.position
        AND x.user_id = evidence.user_id
   );

  SELECT count(*) INTO v_unexpected_deal_evidence
    FROM (
      SELECT p.position, p.user_id
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.source = 'final_table_deal'
       GROUP BY p.position, p.user_id
      HAVING abs(round(sum(p.amount), 2)) > 0.005
    ) evidence
   WHERE evidence.position IS NOT NULL
      OR NOT EXISTS (
        SELECT 1
          FROM jsonb_to_recordset(v_batch.plan)
            AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
         WHERE x.kind = 'final_table_deal' AND x.user_id = evidence.user_id
      );

  SELECT count(*) INTO v_prize_mismatches
    FROM public.tournament_players tp
    CROSS JOIN LATERAL (
      SELECT COALESCE(sum(x.cents), 0) AS cents
        FROM jsonb_to_recordset(v_batch.plan)
          AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
       WHERE x.user_id = tp.user_id
    ) expected
   WHERE tp.tournament_id = p_tournament_id
     AND round(COALESCE(tp.prize, 0) * 100)::bigint <> expected.cents;

  SELECT count(*) INTO v_standing_mismatches
    FROM jsonb_to_recordset(v_batch.plan)
      AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
    LEFT JOIN public.tournament_players tp
      ON tp.tournament_id = p_tournament_id AND tp.user_id = x.user_id
   WHERE tp.id IS NULL
      OR (x.kind = 'place'
          AND (tp.position IS DISTINCT FROM x.place OR tp.status <> 'eliminated'
               OR tp.eliminated_at IS NULL))
      OR (x.kind = 'final_table_deal'
          AND (tp.position IS DISTINCT FROM x.rank
               OR tp.status <> CASE WHEN x.rank = 1 THEN 'winner' ELSE 'eliminated' END
               OR (x.rank = 1 AND tp.eliminated_at IS NOT NULL)
               OR (x.rank > 1 AND tp.eliminated_at IS NULL)));

  SELECT count(*), count(*) FILTER (WHERE tp.position IS NULL),
         count(DISTINCT tp.position), COALESCE(min(tp.position), 0),
         COALESCE(max(tp.position), 0),
         count(*) FILTER (WHERE tp.status = 'winner'),
         count(*) FILTER (WHERE tp.status = 'winner' AND tp.position = 1),
         count(*) FILTER (WHERE tp.status NOT IN ('winner', 'eliminated')),
         count(*) FILTER (WHERE tp.status = 'eliminated' AND tp.eliminated_at IS NULL)
    INTO v_player_count, v_unranked, v_distinct_positions,
         v_min_position, v_max_position, v_winners, v_winner_at_one,
         v_nonterminal, v_missing_bust_time
   FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;

  /* Ranks below the live chop belong to players who busted before the deal.
     Their exact suffix is determined by bust time, then immutable row id for
     equal timestamps: earliest bust finishes last. Recompute both the mapping
     and the stable UTC fingerprint on every verifier call. */
  WITH prior AS (
    SELECT tp.id, tp.user_id, tp.position, tp.eliminated_at,
           v_batch.field_count - (row_number() OVER (
             ORDER BY tp.eliminated_at ASC, tp.id ASC
           ))::integer + 1 AS canonical_position
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position > v_batch.live_count
  )
  SELECT count(*),
         count(*) FILTER (WHERE p.eliminated_at IS NULL),
         count(*) FILTER (WHERE p.position IS DISTINCT FROM p.canonical_position),
         md5(COALESCE(jsonb_agg(jsonb_build_object(
           'id', p.id, 'user_id', p.user_id, 'position', p.position,
           'eliminated_at_utc', to_char(
             p.eliminated_at AT TIME ZONE 'UTC',
             'YYYY-MM-DD"T"HH24:MI:SS.US'))
           ORDER BY p.position, p.id), '[]'::jsonb)::text)
    INTO v_prior_count, v_prior_missing_bust_time,
         v_prior_canonical_mismatches, v_prior_standings_fingerprint
    FROM prior p;

  SELECT EXISTS (
           SELECT 1 FROM public.tournament_obligations o
            WHERE o.tournament_id = p_tournament_id
              AND o.kind = 'bubble_protection'
         ), EXISTS (
           SELECT 1 FROM public.tournament_payouts p
            WHERE p.tournament_id = p_tournament_id
              AND p.source = 'bubble_protection'
         )
    INTO v_bubble_obligation_present, v_bubble_payout_present;
  v_bubble_shape_valid := v_t.buy_in_amount > 0
    AND v_batch.structure_place_count > 0
    AND v_player_count > v_batch.structure_place_count;
  v_bubble_required := (v_t.bubble_protection AND v_bubble_shape_valid)
    OR v_bubble_obligation_present OR v_bubble_payout_present;

  IF v_bubble_required AND v_bubble_shape_valid THEN
    SELECT count(*), (array_agg(tp.user_id ORDER BY tp.id))[1]
      INTO v_bubble_holders, v_bubble_user
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position = v_batch.structure_place_count + 1;

    SELECT count(*),
           count(*) FILTER (WHERE o.user_id = v_bubble_user AND o.place IS NULL),
           COALESCE(max(o.amount_owed) FILTER (
             WHERE o.user_id = v_bubble_user AND o.place IS NULL), 0),
           COALESCE(max(o.amount_paid) FILTER (
             WHERE o.user_id = v_bubble_user AND o.place IS NULL), 0)
      INTO v_bubble_obligations, v_bubble_matching, v_bubble_owed, v_bubble_paid
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'bubble_protection';

    SELECT round(COALESCE(sum(p.amount), 0), 2)
      INTO v_bubble_evidence
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.user_id = v_bubble_user AND p.position IS NULL
       AND p.source = 'bubble_protection';

    SELECT count(*) INTO v_bubble_conflicts
      FROM (
        SELECT p.position, p.user_id
          FROM public.tournament_payouts p
         WHERE p.tournament_id = p_tournament_id
           AND p.source = 'bubble_protection'
           AND (p.position IS NOT NULL OR p.user_id IS DISTINCT FROM v_bubble_user)
         GROUP BY p.position, p.user_id
        HAVING abs(round(sum(p.amount), 2)) > 0.005
      ) unexpected_bubble;

    IF v_bubble_obligations = 1 AND v_bubble_matching = 1 THEN
      SELECT o.id, o.source, o.amount_owed, o.amount_paid, o.settled_at
        INTO v_bubble_obligation_id, v_bubble_source, v_bubble_owed,
             v_bubble_paid, v_bubble_settled_at
        FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'bubble_protection'
         AND o.place IS NULL AND o.user_id = v_bubble_user;
    END IF;
  END IF;

  IF v_obligation_mismatches > 0 OR v_extra_obligations > 0
     OR v_evidence_mismatches > 0 OR v_unexpected_place_evidence > 0
     OR v_unexpected_deal_evidence > 0 OR v_prize_mismatches > 0
     OR v_standing_mismatches > 0
     OR v_prior_count <> v_batch.field_count - v_batch.live_count
     OR v_prior_missing_bust_time > 0
     OR v_prior_canonical_mismatches > 0
     OR v_prior_standings_fingerprint IS DISTINCT FROM
          v_batch.prior_standings_fingerprint
     OR v_player_count <> v_batch.field_count OR v_unranked > 0
     OR v_distinct_positions <> v_player_count
     OR v_min_position <> 1 OR v_max_position <> v_player_count
     OR v_winners <> 1 OR v_winner_at_one <> 1 OR v_nonterminal > 0
     OR v_missing_bust_time > 0
     OR v_snapshot_count <> v_batch.live_count
     OR v_snapshot_distinct_players <> v_batch.live_count
     OR v_snapshot_distinct_users <> v_batch.live_count
     OR v_snapshot_distinct_seats <> v_batch.live_count
     OR v_snapshot_wrong_tables > 0
     OR v_snapshot_input_mismatches > 0
     OR v_snapshot_share_mismatches > 0
     OR v_batch.bubble_contract_required IS DISTINCT FROM v_bubble_required
     OR (v_bubble_required
         AND (NOT v_bubble_shape_valid
              OR v_bubble_holders <> 1 OR v_bubble_user IS NULL
              OR v_bubble_obligations <> 1 OR v_bubble_matching <> 1
              OR v_bubble_obligation_id IS DISTINCT FROM v_batch.bubble_obligation_id
              OR v_bubble_user IS DISTINCT FROM v_batch.bubble_user_id
              OR v_bubble_source IS DISTINCT FROM v_batch.bubble_source
              OR COALESCE(v_bubble_source, '') NOT IN ('engine.eliminatePlayer', 'engine.atomicFinalTableDeal')
              OR abs(v_bubble_owed - v_t.buy_in_amount) > 0.005
              OR abs(v_bubble_owed - v_batch.bubble_amount_owed) > 0.005
              OR v_bubble_paid + 0.005 < v_batch.bubble_amount_paid_before
              OR v_bubble_paid + 0.005 < v_bubble_owed
              OR abs(v_bubble_paid - v_bubble_evidence) > 0.005
              OR v_bubble_settled_at IS NULL
              OR v_bubble_conflicts > 0))
     OR (NOT v_bubble_required
         AND (v_batch.bubble_obligation_id IS NOT NULL
              OR v_batch.bubble_user_id IS NOT NULL
              OR v_batch.bubble_source IS NOT NULL
              OR abs(v_batch.bubble_amount_owed) > 0.005
              OR abs(v_batch.bubble_amount_paid_before) > 0.005)) THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'atomic_deal_evidence_is_incomplete',
      'obligation_mismatches', v_obligation_mismatches,
      'extra_obligations', v_extra_obligations,
      'evidence_mismatches', v_evidence_mismatches,
      'unexpected_place_evidence', v_unexpected_place_evidence,
      'unexpected_deal_evidence', v_unexpected_deal_evidence,
      'prize_mismatches', v_prize_mismatches,
      'standing_mismatches', v_standing_mismatches,
      'prior_players', v_prior_count,
      'prior_eliminated_without_time', v_prior_missing_bust_time,
      'prior_canonical_mismatches', v_prior_canonical_mismatches,
      'prior_standings_fingerprint_matches',
        v_prior_standings_fingerprint IS NOT DISTINCT FROM
          v_batch.prior_standings_fingerprint,
      'players', v_player_count, 'unranked', v_unranked,
      'distinct_positions', v_distinct_positions,
      'rank_range', jsonb_build_array(v_min_position, v_max_position),
      'winners', v_winners, 'winner_at_one', v_winner_at_one,
      'nonterminal', v_nonterminal,
      'eliminated_without_time', v_missing_bust_time,
      'live_input_rows', v_snapshot_count,
      'live_input_mismatches', v_snapshot_input_mismatches,
      'share_rederivation_mismatches', v_snapshot_share_mismatches,
      'bubble_obligations', v_bubble_obligations,
      'bubble_required', v_bubble_required,
      'bubble_shape_valid', v_bubble_shape_valid,
      'bubble_obligation_present', v_bubble_obligation_present,
      'bubble_payout_present', v_bubble_payout_present,
      'bubble_conflicts', v_bubble_conflicts);
  END IF;

  RETURN jsonb_build_object('ok', true, 'reason', NULL,
                            'tournament_id', p_tournament_id,
                            'deal_table_id', v_batch.deal_table_id,
                            'bubble_contract_required', v_batch.bubble_contract_required,
                            'chip_leader', v_batch.chip_leader,
                            'players', v_batch.live_count,
                            'amount_owed', v_batch.amount_owed,
                            'completed', true);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'reason', 'atomic_deal_verification_failed',
                            'detail', SQLERRM, 'sqlstate', SQLSTATE);
END;
$_$;


ALTER FUNCTION public.fn_check_atomic_final_table_deal(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_check_atomic_satellite_finish(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_check_atomic_satellite_finish(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_batch public.tournament_satellite_settlement_batches%ROWTYPE;
  v_count integer;
  v_depth integer;
  v_amount numeric;
  v_fingerprint text;
  v_bad integer;
  v_winner uuid;
  v_t public.tournaments%ROWTYPE;
  v_escrow public.tournament_escrow%ROWTYPE;
  v_rake_expected numeric;
  v_rake_rows integer;
  v_rake_amount numeric;
  v_rake_destination text;
  v_rake_settled_at timestamptz;
  v_rake_attributed_at timestamptz;
  v_bounty public.tournament_bounty_completion_receipts%ROWTYPE;
BEGIN
  SELECT * INTO v_t FROM public.tournaments WHERE id=p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  SELECT * INTO v_batch FROM public.tournament_satellite_settlement_batches
   WHERE tournament_id=p_tournament_id;
  IF NOT FOUND OR v_batch.settled_at IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_batch_not_settled');
  END IF;
  SELECT count(*)::integer,COALESCE(max(e.position),0),
         round(COALESCE(sum(e.ticket_value+e.remainder_value),0),2),
         md5(COALESCE(string_agg(
           concat_ws(':',e.position,e.award_kind,
             COALESCE(e.target_tournament_id::text,''),e.ticket_value,e.remainder_value,
             e.source_pool,e.entry_closed_at::text),'|' ORDER BY e.position),''))
    INTO v_count,v_depth,v_amount,v_fingerprint
    FROM public.tournament_satellite_entitlements e
   WHERE e.tournament_id=p_tournament_id;
  IF ROW(v_batch.entitlement_count,v_batch.award_depth,v_batch.amount_owed,
         v_batch.plan_fingerprint)
     IS DISTINCT FROM ROW(v_count,v_depth,v_amount,v_fingerprint) THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_batch_plan_conflict');
  END IF;
  SELECT (array_agg(tp.user_id ORDER BY tp.user_id))[1] INTO v_winner
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.status='winner' AND tp.position=1;
  IF v_winner IS DISTINCT FROM v_batch.winner_user_id THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_winner_conflict');
  END IF;
  SELECT count(*)::integer INTO v_bad
    FROM public.tournament_satellite_entitlements e
   WHERE e.tournament_id=p_tournament_id
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_batch.outcomes) o
        WHERE COALESCE(o->>'position','')~'^[0-9]+$'
          AND (o->>'position')::integer=e.position
          AND COALESCE(o->>'user_id','')=(SELECT tp.user_id::text
            FROM public.tournament_players tp
            WHERE tp.tournament_id=p_tournament_id AND tp.position=e.position)
          AND CASE WHEN COALESCE(o->>'ticket_value','')~'^[0-9]+([.][0-9]+)?$'
                   THEN round((o->>'ticket_value')::numeric,2) ELSE -1 END
              =e.ticket_value
          AND CASE WHEN COALESCE(o->>'remainder_value','')~'^[0-9]+([.][0-9]+)?$'
                   THEN round((o->>'remainder_value')::numeric,2) ELSE -1 END
              =e.remainder_value
     );
  IF v_bad>0 OR jsonb_array_length(v_batch.outcomes)<>v_count OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_batch.outcomes) o
     GROUP BY o->>'position' HAVING count(*)<>1
  ) THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_outcome_set_incomplete');
  END IF;

  -- Prove each promised ticket is exactly one in-kind seat or one paid place,
  -- never both; prove residual cash through its distinct obligation key.
  SELECT count(*)::integer INTO v_bad
    FROM public.tournament_satellite_entitlements e
    JOIN public.tournament_players finisher
      ON finisher.tournament_id=e.tournament_id AND finisher.position=e.position
    CROSS JOIN LATERAL (
      SELECT o FROM jsonb_array_elements(v_batch.outcomes) o
       WHERE (o->>'position')::integer=e.position LIMIT 1
    ) outcome
   WHERE e.tournament_id=p_tournament_id AND (
     finisher.status NOT IN ('winner','eliminated')
     OR round(COALESCE(finisher.prize,0),2)<>
          round(e.ticket_value+e.remainder_value,2)
     OR (e.ticket_value>0 AND (
       (outcome.o->>'ticket_delivery') NOT IN ('seat','cash')
       OR ((outcome.o->>'ticket_delivery')='seat')<>((
         SELECT count(*)=1 FROM public.tournament_payouts po
          JOIN public.tournament_players target_seat
            ON target_seat.id::text=po.metadata->>'registration_id'
         WHERE po.tournament_id=p_tournament_id AND po.user_id=finisher.user_id
           AND po.position=e.position AND po.source='satellite_seat'
           AND round(po.amount,2)=e.ticket_value
           AND CASE WHEN COALESCE(po.metadata->>'pool_transfer','')~'^[0-9]+([.][0-9]+)?$'
                    THEN round((po.metadata->>'pool_transfer')::numeric,2) ELSE -1 END
               =e.ticket_value
           AND CASE WHEN COALESCE(po.metadata->>'unbacked','')~'^[0-9]+([.][0-9]+)?$'
                    THEN round((po.metadata->>'unbacked')::numeric,2) ELSE -1 END=0
           AND round(
             CASE WHEN COALESCE(po.metadata->>'target_buy_in','')~'^[0-9]+([.][0-9]+)?$'
                  THEN (po.metadata->>'target_buy_in')::numeric ELSE -1 END
             +CASE WHEN COALESCE(po.metadata->>'target_fee','')~'^[0-9]+([.][0-9]+)?$'
                   THEN (po.metadata->>'target_fee')::numeric ELSE -1 END,2)
               =e.ticket_value
           AND target_seat.user_id=finisher.user_id
           AND target_seat.source_satellite_id=p_tournament_id
           AND (SELECT count(*) FROM public.chip_ledger l
                 WHERE l.idempotency_key='tourney:'||p_tournament_id::text
                       ||':seat:'||finisher.user_id::text||':pool_transfer'
                   AND l.from_type='prize_liability'
                   AND l.from_entity_id=p_tournament_id
                   AND l.to_type='prize_liability'
                   AND l.to_entity_id=e.target_tournament_id
                   AND round(l.amount,2)=e.ticket_value
                   AND l.metadata->>'registration_id'=target_seat.id::text
                   AND CASE WHEN COALESCE(l.metadata->>'moved','')~'^[0-9]+([.][0-9]+)?$'
                            THEN round((l.metadata->>'moved')::numeric,2) ELSE -1 END
                       =e.ticket_value
                   AND CASE WHEN COALESCE(l.metadata->>'unbacked','')~'^[0-9]+([.][0-9]+)?$'
                            THEN round((l.metadata->>'unbacked')::numeric,2) ELSE -1 END=0)=1
           AND (SELECT count(*) FROM public.rake_records rr
                 WHERE rr.tournament_id=e.target_tournament_id
                   AND rr.source='fn_award_satellite_seat'
                   AND rr.metadata->>'satellite_id'=p_tournament_id::text
                   AND rr.metadata->>'user_id'=finisher.user_id::text
                   AND rr.metadata->>'registration_id'=target_seat.id::text
                   AND round(rr.rake_amount,2)=round(
                     CASE WHEN COALESCE(po.metadata->>'target_fee','')~'^[0-9]+([.][0-9]+)?$'
                          THEN (po.metadata->>'target_fee')::numeric ELSE -1 END,2)
                   AND round(COALESCE(rr.pot_size,0),2)=e.ticket_value)
               =CASE WHEN CASE
                   WHEN COALESCE(po.metadata->>'target_fee','')~'^[0-9]+([.][0-9]+)?$'
                     THEN (po.metadata->>'target_fee')::numeric ELSE -1 END>0
                 THEN 1 ELSE 0 END
       ))
       OR ((outcome.o->>'ticket_delivery')='cash')<>((
         SELECT count(*)=1 FROM public.tournament_obligations obl
          WHERE obl.tournament_id=p_tournament_id AND obl.kind='place'
            AND obl.place=e.position AND obl.user_id=finisher.user_id
            AND round(obl.amount_owed,2)=e.ticket_value
            AND round(obl.amount_paid,2)=e.ticket_value
            AND obl.settled_at IS NOT NULL))
     ))
     OR (e.award_kind='cash' AND (
       SELECT count(*) FROM public.tournament_obligations obl
        WHERE obl.tournament_id=p_tournament_id AND obl.kind='place'
          AND obl.place=e.position AND obl.user_id=finisher.user_id
          AND round(obl.amount_owed,2)=e.remainder_value
          AND round(obl.amount_paid,2)=e.remainder_value
          AND obl.settled_at IS NOT NULL)<>1)
     OR (e.ticket_value>0 AND e.remainder_value>0 AND (
       SELECT count(*) FROM public.tournament_obligations obl
        WHERE obl.tournament_id=p_tournament_id
          AND obl.kind='satellite_remainder' AND obl.place IS NULL
          AND obl.user_id=finisher.user_id
          AND round(obl.amount_owed,2)=e.remainder_value
          AND round(obl.amount_paid,2)=e.remainder_value
          AND obl.settled_at IS NOT NULL)<>1)
   );
  IF v_bad>0 THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_money_evidence_incomplete',
                              'invalid_entitlements',v_bad);
  END IF;

  -- COMPLETED cannot outrun the common money prerequisites. The caller runs
  -- rake/bounty settlement first, while this checker independently proves the
  -- durable receipts inside the same transaction as the terminal status flip.
  SELECT GREATEST(round(COALESCE(sum(rr.rake_amount),0),2),0)
    INTO v_rake_expected
    FROM public.rake_records rr
   WHERE rr.tournament_id=p_tournament_id AND rr.is_tournament;
  SELECT count(*)::integer,(array_agg(rs.amount ORDER BY rs.tournament_id))[1],
         (array_agg(rs.destination ORDER BY rs.tournament_id))[1],
         (array_agg(rs.settled_at ORDER BY rs.tournament_id))[1],
         (array_agg(rs.attributed_at ORDER BY rs.tournament_id))[1]
    INTO v_rake_rows,v_rake_amount,v_rake_destination,
         v_rake_settled_at,v_rake_attributed_at
    FROM public.tournament_rake_settlements rs
   WHERE rs.tournament_id=p_tournament_id;
  IF v_rake_rows<>1 OR v_rake_settled_at IS NULL
     OR v_rake_attributed_at IS NULL OR v_rake_destination='pending'
     OR abs(round(COALESCE(v_rake_amount,0),2)-v_rake_expected)>0.005 THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_rake_not_settled',
      'expected',v_rake_expected,'recorded',v_rake_amount,
      'destination',v_rake_destination,'attributed_at',v_rake_attributed_at);
  END IF;

  IF COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
     OR COALESCE(v_t.is_mystery_bounty,false) THEN
    IF public.fn_tournament_has_unsettled_bounties(p_tournament_id) THEN
      RETURN jsonb_build_object('ok',false,
                                'reason','satellite_bounty_obligations_pending');
    END IF;
    SELECT * INTO v_bounty
      FROM public.tournament_bounty_completion_receipts b
     WHERE b.tournament_id=p_tournament_id;
    IF NOT FOUND OR v_bounty.winner_user_id IS DISTINCT FROM v_winner
       OR v_bounty.pool_finalized_at IS NULL
       OR COALESCE((v_bounty.pool_result->>'ok')::boolean,false) IS NOT TRUE
       OR (COALESCE(v_t.is_mystery_bounty,false)
           AND COALESCE(v_t.mystery_bounty_stage,'pending')<>'pending'
           AND (v_bounty.mystery_settled_at IS NULL
                OR COALESCE((v_bounty.mystery_result->>'ok')::boolean,false) IS NOT TRUE
                OR COALESCE((v_bounty.mystery_result->>'balanced')::boolean,false) IS NOT TRUE)) THEN
      RETURN jsonb_build_object('ok',false,
                                'reason','satellite_bounty_not_certified');
    END IF;
  END IF;

  SELECT * INTO v_escrow FROM public.tournament_escrow
   WHERE tournament_id=p_tournament_id;
  IF NOT FOUND THEN
    IF COALESCE(v_t.prize_pool,0)<>0 OR COALESCE(v_t.bounty_pool,0)<>0
       OR COALESCE(v_t.total_rake,0)<>0
       OR EXISTS (SELECT 1 FROM public.tournament_payouts po
                   WHERE po.tournament_id=p_tournament_id) THEN
      RETURN jsonb_build_object('ok',false,'reason','satellite_escrow_evidence_missing');
    END IF;
  ELSIF abs(round(v_escrow.prize_balance,2))>0.005
     OR abs(round(v_escrow.bounty_balance,2))>0.005
     OR abs(round(v_escrow.fee_balance,2))>0.005 THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_escrow_not_zero',
      'prize_balance',v_escrow.prize_balance,
      'bounty_balance',v_escrow.bounty_balance,
      'fee_balance',v_escrow.fee_balance);
  END IF;
  RETURN jsonb_build_object('ok',true,'reason',NULL,
    'tournament_id',p_tournament_id,'winner_user_id',v_batch.winner_user_id,
    'entitlement_count',v_count,'award_depth',v_depth,'amount_settled',v_amount,
    'plan_fingerprint',v_fingerprint);
END;
$_$;


ALTER FUNCTION public.fn_check_atomic_satellite_finish(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_check_club_message_permission(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_check_club_message_permission() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    conv_category TEXT;
    conv_club_id UUID;
BEGIN
    -- Get conversation details
    SELECT category, club_id INTO conv_category, conv_club_id
    FROM conversations
    WHERE id = NEW.conversation_id;

    -- If not a club conversation, allow (personal messages have different rules)
    IF conv_category != 'club' OR conv_club_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Check permission
    IF NOT fn_can_message_in_club(NEW.sender_id, NEW.receiver_id, conv_club_id) THEN
        RAISE EXCEPTION 'Not authorized to message this user in this club';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_check_club_message_permission() OWNER TO postgres;

--
-- Name: fn_check_distribution_rate_limit(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_check_distribution_rate_limit(p_agent_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$ DECLARE v_recent_count INTEGER; BEGIN SELECT COUNT(*) INTO v_recent_count FROM chip_transactions WHERE from_user_id = (SELECT user_id FROM agents WHERE id = p_agent_id) AND transaction_type IN ('agent_to_player', 'promo_agent_to_player') AND created_at > NOW() - INTERVAL '1 minute'; RETURN v_recent_count < 10; END; $$;


ALTER FUNCTION public.fn_check_distribution_rate_limit(p_agent_id uuid) OWNER TO postgres;

--
-- Name: fn_check_home_rate_limit(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_check_home_rate_limit(p_caller_user_id uuid, p_action text, p_window_minutes integer DEFAULT 60) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int := 0;
  v_limit int;
  v_since timestamptz := NOW() - (p_window_minutes || ' minutes')::interval;
BEGIN
  CASE p_action
    WHEN 'join' THEN
      v_limit := 20;
      SELECT COUNT(*) INTO v_count FROM commander_home_members
        WHERE user_id = p_caller_user_id AND created_at > v_since;
    WHEN 'post' THEN
      v_limit := 30;
      SELECT COUNT(*) INTO v_count FROM commander_home_posts
        WHERE author_id = p_caller_user_id AND created_at > v_since;
    WHEN 'comment' THEN
      v_limit := 60;
      SELECT COUNT(*) INTO v_count FROM commander_home_post_comments
        WHERE author_id = p_caller_user_id AND created_at > v_since;
    WHEN 'invite_token' THEN
      v_limit := 15;
      SELECT COUNT(*) INTO v_count FROM commander_home_invite_tokens
        WHERE created_by = p_caller_user_id AND created_at > v_since;
    WHEN 'rsvp' THEN
      v_limit := 40;
      SELECT COUNT(*) INTO v_count FROM commander_home_rsvps
        WHERE user_id = p_caller_user_id AND responded_at > v_since;
    ELSE
      RETURN true;
  END CASE;
  RETURN (v_count < v_limit);
END;
$$;


ALTER FUNCTION public.fn_check_home_rate_limit(p_caller_user_id uuid, p_action text, p_window_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_check_home_rate_limit(p_caller_user_id uuid, p_action text, p_window_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_check_home_rate_limit(p_caller_user_id uuid, p_action text, p_window_minutes integer) IS 'Pass 46: Extended with broadcast_group (5/hr) and broadcast_game (10/hr) actions. Counts via notifications.actor_id + type patterns — no schema change. Original post/comment/rsvp/invite_token/join actions preserved.';


--
-- Name: fn_check_level_advancement(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_check_level_advancement(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND (auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_user_id) THEN
    RAISE EXCEPTION 'Cannot maintain sessions for another user';
  END IF;
  UPDATE public.arena_sessions
     SET status = 'abandoned', completed_at = now()
   WHERE user_id = p_user_id AND status = 'active'
     AND created_at < now() - interval '24 hours';
END;
$$;


ALTER FUNCTION public.fn_check_level_advancement(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_check_ungated_money_rpcs(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_check_ungated_money_rpcs() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_n int; v_list text;
BEGIN
  SELECT count(*), string_agg(fn || '(' || args || ')', ', ')
    INTO v_n, v_list
    FROM public.fn_ungated_money_rpcs();

  IF v_n > 0 THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical', 'fn_check_ungated_money_rpcs',
           v_n || ' money-mutating SECURITY DEFINER function(s) are callable by '
             || 'authenticated with no authorization gate',
           jsonb_build_object('count', v_n, 'functions', v_list)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts
        WHERE source = 'fn_check_ungated_money_rpcs' AND resolved IS NOT TRUE);
  ELSE
    -- Self-resolving: a guard that can raise must be able to stand down.
    UPDATE public.financial_alerts
       SET resolved = true, resolved_at = now()
     WHERE source = 'fn_check_ungated_money_rpcs' AND resolved IS NOT TRUE;
  END IF;

  RETURN jsonb_build_object('ok', true, 'ungated', v_n, 'functions', v_list);
END;
$$;


ALTER FUNCTION public.fn_check_ungated_money_rpcs() OWNER TO postgres;

--
-- Name: fn_chip_drift_since_baseline(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_chip_drift_since_baseline() RETURNS TABLE(club_id uuid, user_id uuid, opening_balance numeric, movements_since numeric, expected numeric, actual numeric, drift numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH span AS (SELECT MIN(taken_at) AS t0 FROM public.ca_chip_baseline),
  moves AS (
    SELECT cl.club_id AS c_id,
           /* The player is whichever side is typed player_wallet. Never a
              coalesce: both sides are populated now. */
           CASE WHEN cl.to_type = 'player_wallet' THEN cl.to_entity_id
                ELSE cl.from_entity_id END AS u_id,
           SUM(CASE WHEN cl.to_type   = 'player_wallet' THEN cl.amount ELSE 0 END)
         - SUM(CASE WHEN cl.from_type = 'player_wallet' THEN cl.amount ELSE 0 END) AS net
    FROM public.chip_ledger cl, span
    WHERE cl.club_id IS NOT NULL
      AND cl.created_at >= span.t0
      AND (cl.to_type = 'player_wallet' OR cl.from_type = 'player_wallet')
    GROUP BY 1, 2
  )
  SELECT b.club_id, b.user_id, b.opening_balance,
         COALESCE(m.net, 0)                              AS movements_since,
         b.opening_balance + COALESCE(m.net, 0)          AS expected,
         COALESCE(cm.chip_balance, 0)                    AS actual,
         COALESCE(cm.chip_balance, 0) - (b.opening_balance + COALESCE(m.net, 0)) AS drift
  FROM public.ca_chip_baseline b
  JOIN public.club_members cm
    ON cm.club_id = b.club_id AND cm.user_id = b.user_id
  LEFT JOIN moves m
    ON m.c_id = b.club_id AND m.u_id = b.user_id;
$$;


ALTER FUNCTION public.fn_chip_drift_since_baseline() OWNER TO postgres;

--
-- Name: FUNCTION fn_chip_drift_since_baseline(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_chip_drift_since_baseline() IS 'Drift that happened AFTER auditing was restored on 2026-08-26. Non-zero means chips moved without a ledger row, on our watch. Identifies the player by which SIDE is typed player_wallet - a coalesce over the two entity ids silently drops every debit. The pre-baseline gap is excluded: it is unknowable, not zero.';


--
-- Name: fn_chip_integrity_report(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_chip_integrity_report() RETURNS TABLE(check_name text, severity text, detail text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_sev text; v_finding text; v_days integer;
  v_drift_rows bigint; v_worst numeric;
  v_fail bigint; v_exits bigint;
  v_frozen numeric; v_last_write timestamptz;
  v_free bigint; v_lost numeric;
  v_flag bigint; v_flag_chips numeric;
  v_base numeric; v_left numeric;
BEGIN
  SELECT l.severity, l.finding, l.silent_for_days INTO v_sev, v_finding, v_days
    FROM public.fn_ledger_liveness() l;
  check_name := 'ledger_liveness'; severity := v_sev; detail := v_finding;
  RETURN NEXT;

  SELECT count(*) FILTER (WHERE abs(d.drift) > 0.01), COALESCE(max(abs(d.drift)), 0)
    INTO v_drift_rows, v_worst FROM public.fn_chip_drift_since_baseline() d;
  check_name := 'drift_since_baseline';
  severity   := CASE WHEN v_drift_rows = 0 THEN 'ok' WHEN v_worst <= 1 THEN 'warn' ELSE 'critical' END;
  detail     := format('%s member(s) drifting, worst %s. Baseline 2026-08-26.', v_drift_rows, round(v_worst,2));
  RETURN NEXT;

  -- Excludes the idempotency refusal, matching fn_ca_quick_reconcile 3f.
  SELECT count(*) INTO v_fail
    FROM public.ca_ledger_write_failures f
   WHERE NOT (
     f.sqlstate = '23505'
     AND f.message LIKE '%ux_chip_ledger_idempotency_key%'
     AND EXISTS (
       SELECT 1 FROM public.chip_ledger l
        WHERE l.club_id = f.club_id
          AND l.idempotency_key = 'club-opening-grant:' || f.club_id::text
          AND l.category = 'mint' AND l.from_type = 'system_mint'
          AND l.to_type = 'club_treasury' AND l.to_entity_id = f.club_id
          AND l.amount = 100000 AND l.status = 'posted'));
  check_name := 'ledger_write_failures';
  severity   := CASE WHEN v_fail = 0 THEN 'ok' ELSE 'critical' END;
  detail     := format('%s swallowed ledger write(s) (idempotency refusals of an already-posted grant excluded).', v_fail);
  RETURN NEXT;

  SELECT count(*) INTO v_exits FROM public.fn_unaccounted_seat_exits();
  check_name := 'unaccounted_seat_exits';
  severity   := CASE WHEN v_exits = 0 THEN 'ok' ELSE 'critical' END;
  detail     := format('%s seat exit(s) with a non-zero stack and no wallet credit.', v_exits);
  RETURN NEXT;

  SELECT count(*), COALESCE(sum(u.uncollected),0) INTO v_free, v_lost
    FROM public.fn_unpriced_tournaments('7 days') u;
  check_name := 'unpriced_tournaments';
  severity   := CASE WHEN v_free = 0 THEN 'ok' ELSE 'warn' END;
  detail     := format('%s COMPLETED tournament(s) in 7 days took a buy-in and earned no rake, ~%s uncollected.',
                       v_free, round(v_lost,2));
  RETURN NEXT;

  SELECT b.memberships, b.chips_held INTO v_flag, v_flag_chips
    FROM public.fn_bot_flag_disagreement() b;
  check_name := 'bot_flag_disagreement';
  severity   := CASE WHEN v_flag = 0 THEN 'ok' ELSE 'warn' END;
  detail     := format('%s membership(s) holding %s chips have club_members.is_bot disagreeing '
                       || 'with profiles.is_horse. Every is_bot-keyed report is wrong by this much.',
                       v_flag, round(v_flag_chips,2));
  RETURN NEXT;

  SELECT COALESCE(sum(balance),0), max(updated_at) FILTER (WHERE balance <> 0)
    INTO v_frozen, v_last_write FROM public.wallets;
  SELECT COALESCE(frozen_total, 732591994.33) INTO v_base
    FROM public.ca_frozen_pool_baseline WHERE pool = 'public.wallets';
  SELECT COALESCE(sum(deleted_balance),0) INTO v_left
    FROM public.ca_frozen_pool_deletions WHERE pool = 'public.wallets';
  check_name := 'legacy_wallets_frozen';
  severity   := CASE WHEN round(v_frozen + COALESCE(v_left,0), 2) <> round(COALESCE(v_base,0),2) THEN 'critical'
                     WHEN v_last_write > now() - interval '2 days' THEN 'critical'
                     ELSE 'ok' END;
  detail     := format('public.wallets holds %s chips plus %s recorded as having left, against a frozen baseline of %s. Last MONEY write %s. A zero-balance row created at signup is not a movement; a changed total is, and so is a row that cascaded away.',
                       round(v_frozen,2), round(COALESCE(v_left,0),2), round(COALESCE(v_base,0),2),
                       COALESCE(v_last_write::text,'never'));
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_chip_integrity_report() OWNER TO postgres;

--
-- Name: FUNCTION fn_chip_integrity_report(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_chip_integrity_report() IS 'The five chip-integrity questions worth paging on, added 2026-08-26. Replaces reading 575 nightly criticals about a frozen table, which is what hid a 115-day ledger outage. Page on any critical row.';


--
-- Name: fn_chip_ledger_split_report(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_chip_ledger_split_report() RETURNS TABLE(metric text, value numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH per_user AS (
    SELECT cm.user_id,
           SUM(cm.chip_balance)::numeric        AS club_chips,
           COALESCE(MAX(w.balance), 0)::numeric AS global_chips
      FROM club_members cm
      JOIN clubs c ON c.id = cm.club_id AND c.is_union = false
      LEFT JOIN wallets w
        ON w.user_id = cm.user_id AND w.wallet_type = 'PLAYER'
     WHERE cm.status IN ('approved','active')
     GROUP BY cm.user_id
  )
  SELECT 'users_total',            count(*)::numeric                                              FROM per_user
  UNION ALL
  SELECT 'bought_but_cannot_play', count(*) FILTER (WHERE club_chips > 0 AND global_chips = 0)::numeric FROM per_user
  UNION ALL
  SELECT 'won_but_cannot_cashout', count(*) FILTER (WHERE global_chips > 0 AND club_chips = 0)::numeric FROM per_user
  UNION ALL
  SELECT 'total_club_chips',       COALESCE(round(sum(club_chips)), 0)                            FROM per_user
  UNION ALL
  SELECT 'total_global_chips',     COALESCE(round(sum(global_chips)), 0)                          FROM per_user
  UNION ALL
  SELECT 'ledger_gap',             COALESCE(round(sum(global_chips) - sum(club_chips)), 0)        FROM per_user;
$$;


ALTER FUNCTION public.fn_chip_ledger_split_report() OWNER TO postgres;

--
-- Name: fn_claim_bounty_legacy_candidate_20260907(uuid, uuid, integer, numeric, uuid, uuid, bigint, timestamp with time zone, uuid, jsonb, numeric, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_bounty_legacy_candidate_20260907(p_tournament_id uuid, p_eliminated_user_id uuid, p_position integer, p_prize numeric, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_knocker_user_id uuid, p_claimants jsonb, p_bubble_refund numeric DEFAULT 0, p_allow_existing_eliminated boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_player public.tournament_players%ROWTYPE;
  v_settlement_at timestamptz;
  v_mode text;
  v_claimants jsonb;
  v_input_claimants jsonb;
  v_knocker uuid;
  v_head numeric;
  v_hand_created_at timestamptz;
  v_latest_joined_at timestamptz;
  v_position integer;
  v_prize numeric;
  v_claimed boolean := false;
  v_existing public.tournament_bounty_obligations%ROWTYPE;
  v_activation_generation bigint := 0;
  v_pko_watermark bigint;
BEGIN
  IF p_tournament_id IS NULL OR p_eliminated_user_id IS NULL OR p_table_id IS NULL
     OR p_hand_id IS NULL OR p_hand_number IS NULL OR p_hand_number < 1000000
     OR p_seat_joined_at IS NULL OR p_bubble_refund IS NULL OR p_bubble_refund<0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'missing_identity');
  END IF;
  IF p_bubble_refund <> 0 THEN
    RETURN jsonb_build_object('ok',false,'reason','bubble_refund_requires_finalized_batch');
  END IF;

  IF p_claimants IS NOT NULL THEN
    IF jsonb_typeof(p_claimants) <> 'array' OR jsonb_array_length(p_claimants)=0
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(p_claimants) e
          WHERE COALESCE(e->>'user_id','')
                  !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
             OR COALESCE(e->>'weight','') !~ '^[0-9]+([.][0-9]+)?$'
             OR (e->>'weight')::numeric <= 0
       ) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'invalid_claimants');
    END IF;
    SELECT jsonb_agg(jsonb_build_object('user_id', user_id, 'weight', 1)
                     ORDER BY user_id::text)
      INTO v_input_claimants
      FROM (SELECT DISTINCT (e->>'user_id')::uuid AS user_id
              FROM jsonb_array_elements(p_claimants) e) q;
  END IF;

  SELECT * INTO v_t FROM public.tournaments
   WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found'); END IF;

  -- The obligation is the accepted claim receipt.  Check it before today's
  -- player status, latest seat or mystery phase: those mutable facts can all
  -- change after a successful call whose response was lost.
  SELECT * INTO v_existing FROM public.tournament_bounty_obligations
   WHERE tournament_id=p_tournament_id
     AND eliminated_user_id=p_eliminated_user_id
     AND seat_joined_at=p_seat_joined_at
   FOR UPDATE;
  IF FOUND THEN
    IF v_existing.table_id<>p_table_id OR v_existing.hand_id<>p_hand_id
       OR v_existing.hand_number<>p_hand_number
       OR v_existing.bubble_refund<>round(p_bubble_refund,2)
       OR v_existing.position IS DISTINCT FROM p_position
       OR v_existing.prize IS DISTINCT FROM round(p_prize,2)
       OR (p_knocker_user_id IS NOT NULL AND NOT EXISTS (
             SELECT 1 FROM jsonb_array_elements(v_existing.claimants) c
              WHERE c->>'user_id'=p_knocker_user_id::text))
       OR (v_input_claimants IS NOT NULL
           AND v_existing.claimants IS DISTINCT FROM v_input_claimants) THEN
      RETURN jsonb_build_object('ok',false,'reason','obligation_identity_conflict');
    END IF;
    IF v_existing.state='settled'
       AND NOT public.fn_bounty_obligation_has_complete_marker(v_existing.id) THEN
      RETURN jsonb_build_object('ok',false,'reason','settled_marker_incomplete',
                                'obligation_id',v_existing.id);
    END IF;
    RETURN jsonb_build_object('ok',true,'already',true,'claimed',false,
      'mode',v_existing.mode,'state',v_existing.state,
      'activation_generation',v_existing.activation_generation,
      'obligation_id',v_existing.id);
  END IF;

  IF NOT (COALESCE(v_t.is_bounty, false) OR COALESCE(v_t.is_pko, false)
          OR COALESCE(v_t.is_mystery_bounty, false)) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_bounty_tournament');
  END IF;

  -- The finalisation owner may finish an already-observed live knockout while
  -- COMPLETING. The compatibility argument does not authorize reconstruction
  -- of an eliminated row or mutation of an already-COMPLETED tournament.
  IF upper(COALESCE(v_t.status,'')) <> 'RUNNING'
     AND NOT (p_allow_existing_eliminated
              AND upper(COALESCE(v_t.status,'')) = 'COMPLETING') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_lifecycle_not_claimable',
                              'status', v_t.status);
  END IF;

  SELECT * INTO v_player FROM public.tournament_players
   WHERE tournament_id = p_tournament_id AND user_id = p_eliminated_user_id
   FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'player_not_found'); END IF;
  IF COALESCE(v_player.chips, 0) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'player_has_chips');
  END IF;
  IF v_player.status <> 'playing' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'status_not_claimable', 'status', v_player.status);
  END IF;
  IF p_position IS NULL OR p_position < 2 OR p_prize IS NULL OR p_prize < 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_place_or_prize');
  END IF;
  v_position := p_position;
  v_prize := p_prize;
  -- The seat generation closes the rebuy/re-bust ambiguity. An old zero hand
  -- from the same physical table cannot authorize a newer seat.
  IF NOT EXISTS (
    SELECT 1 FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
    WHERE s.user_id = p_eliminated_user_id
      AND s.table_id = p_table_id
      AND tb.tournament_id = p_tournament_id
      AND s.joined_at = p_seat_joined_at
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seat_generation_not_found');
  END IF;

  SELECT max(s.joined_at) INTO v_latest_joined_at
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_eliminated_user_id;
  IF v_latest_joined_at IS DISTINCT FROM p_seat_joined_at THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seat_generation_not_current');
  END IF;

  SELECT k.completed_at INTO v_settlement_at
    FROM public.settlement_idempotency_keys k
   WHERE k.table_id = p_table_id
     AND k.status = 'succeeded'
     AND k.completed_at >= p_seat_joined_at
     AND COALESCE(k.result->>'hand_number', '') ~ '^[0-9]+$'
     AND (k.result->>'hand_number')::bigint = p_hand_number
     AND k.result->>'table_id' = p_table_id::text
     AND k.result->'written' ? p_eliminated_user_id::text
     AND COALESCE(k.result->'written'->>p_eliminated_user_id::text, '') ~ '^-?[0-9]+([.][0-9]+)?$'
     AND (k.result->'written'->>p_eliminated_user_id::text)::numeric <= 0
   ORDER BY k.completed_at DESC
   LIMIT 1;
  IF v_settlement_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'accepted_zero_settlement_not_found');
  END IF;

  SELECT h.created_at INTO v_hand_created_at
    FROM public.hand_history h
   WHERE h.id = p_hand_id
     AND h.table_id = p_table_id
     AND h.hand_number = p_hand_number
     AND h.hand_number >= 1000000
     AND h.created_at >= v_settlement_at
     AND h.created_at >= p_seat_joined_at
     AND EXISTS (
       SELECT 1 FROM jsonb_array_elements(COALESCE(h.players, '[]'::jsonb)) player
        WHERE COALESCE(player->>'userId', player->>'user_id') = p_eliminated_user_id::text
          AND COALESCE(player->>'stack', '') ~ '^-?[0-9]+([.][0-9]+)?$'
          AND (player->>'stack')::numeric <= 0
     );
  IF v_hand_created_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'exact_knockout_history_not_found');
  END IF;

  v_claimants := public.fn_exact_tournament_knockout_claimants(
    p_tournament_id, p_hand_id, p_eliminated_user_id);
  IF v_claimants IS NULL OR jsonb_array_length(v_claimants)=0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'exact_pot_claimants_not_found');
  END IF;

  SELECT (e->>'user_id')::uuid
  INTO v_knocker
  FROM jsonb_array_elements(v_claimants) e
  ORDER BY e->>'user_id'
  LIMIT 1;
  IF p_knocker_user_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_claimants) e
                      WHERE e->>'user_id'=p_knocker_user_id::text) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_knocker');
  END IF;

  IF p_claimants IS NOT NULL THEN
    IF v_input_claimants IS DISTINCT FROM v_claimants THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'claimants_do_not_match_exact_pot');
    END IF;
  END IF;

  -- The locked live tournament phase is the authority for a new obligation.
  -- No prior award or mutable post-hoc row can be adopted into the outbox.
  v_mode := CASE
    WHEN COALESCE(v_t.is_mystery_bounty, false)
      AND v_t.mystery_bounty_stage = 'active' THEN 'mystery_chest'
    WHEN COALESCE(v_t.is_pko, false) THEN 'pko'
    WHEN COALESCE(v_t.is_mystery_bounty, false) THEN 'mystery_pre'
    ELSE 'regular'
  END;
  v_activation_generation := CASE WHEN v_mode='mystery_chest'
    THEN v_t.mystery_bounty_activation_generation ELSE 0 END;
  IF v_mode='mystery_chest' AND (v_activation_generation<=0 OR NOT EXISTS (
    SELECT 1 FROM public.tournament_mystery_activation_receipts ar
     WHERE ar.tournament_id=p_tournament_id
       AND ar.activation_generation=v_activation_generation
  )) THEN
    RETURN jsonb_build_object('ok',false,'reason','mystery_activation_evidence_missing');
  END IF;

  IF v_mode='pko' THEN
    SELECT w.last_settled_hand_number INTO v_pko_watermark
      FROM public.tournament_pko_settlement_watermarks w
     WHERE w.tournament_id=p_tournament_id
     FOR UPDATE;
    IF v_pko_watermark IS NOT NULL AND p_hand_number<v_pko_watermark THEN
      RETURN jsonb_build_object('ok',false,'reason','pko_order_already_advanced',
                                'last_settled_hand_number',v_pko_watermark);
    END IF;
  END IF;

  -- A pending earlier PKO can still add half its head to this player. Claiming
  -- the player's later bust first would snapshot/zero the smaller head and
  -- strand the predecessor credit. Strict hand order makes that impossible.
  IF v_mode='pko' AND EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations prior
     WHERE prior.tournament_id=p_tournament_id AND prior.mode='pko' AND prior.state='pending'
       AND (prior.hand_number < p_hand_number
            OR (prior.hand_number=p_hand_number
                AND prior.eliminated_user_id::text < p_eliminated_user_id::text))
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(prior.claimants) c
                    WHERE c->>'user_id'=p_eliminated_user_id::text)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'pending_pko_predecessor');
  END IF;

  -- Same-hand chain: if another zero-stack player in this exact hand awards
  -- head value to the player being claimed, that predecessor must be fully
  -- settled first even when no outbox for it has been created yet. This is a
  -- causal/topological dependency, not an arbitrary UUID ordering.
  IF v_mode='pko' AND EXISTS (
    SELECT 1
      FROM public.hand_history h
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(h.players,'[]'::jsonb)) hp
     WHERE h.id=p_hand_id
       AND COALESCE(hp->>'userId',hp->>'user_id','')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       AND COALESCE(hp->>'userId',hp->>'user_id') <> p_eliminated_user_id::text
       AND COALESCE(hp->>'stack','') ~ '^-?[0-9]+([.][0-9]+)?$'
       AND (hp->>'stack')::numeric <= 0
       AND public.fn_exact_tournament_knockout_claimants(
             p_tournament_id,h.id,COALESCE(hp->>'userId',hp->>'user_id')::uuid)
             @> jsonb_build_array(jsonb_build_object(
                   'user_id',p_eliminated_user_id,'weight',1))
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_bounty_obligations predecessor
          WHERE predecessor.tournament_id=p_tournament_id
            AND predecessor.hand_number=p_hand_number
            AND predecessor.eliminated_user_id=
                COALESCE(hp->>'userId',hp->>'user_id')::uuid
            AND predecessor.state='settled'
       )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'same_hand_pko_predecessor');
  END IF;

  v_head := COALESCE(NULLIF(v_player.current_bounty,0),
                     NULLIF(v_t.bounty_amount,0));
  IF COALESCE(v_head,0) <= 0 THEN
    RETURN jsonb_build_object('ok',false,'reason','exact_head_value_not_found');
  END IF;

  UPDATE public.tournament_players
     SET status = 'eliminated', position = p_position, prize = p_prize,
         eliminated_at = now()
   WHERE tournament_id = p_tournament_id
     AND user_id = p_eliminated_user_id
     AND status = 'playing' AND chips <= 0;
  IF NOT FOUND THEN
    -- The status, exact knockout outbox and seat release are one transaction.
    -- A CAS miss must undo the outbox rather than leave a payable bounty claim
    -- beside a still-playing row. Place and Bubble money are not moved here.
    RAISE EXCEPTION 'bounty elimination CAS missed after locked claim'
      USING ERRCODE='serialization_failure';
  END IF;
  v_claimed := true;

  INSERT INTO public.tournament_bounty_obligations
    (tournament_id, eliminated_user_id, table_id, hand_id, hand_number,
     settlement_completed_at, seat_joined_at, position, prize, bubble_refund,
     mode, activation_generation, head_amount, knocker_user_id, claimants,
     next_attempt_at)
  VALUES
    (p_tournament_id, p_eliminated_user_id, p_table_id, p_hand_id, p_hand_number,
     v_settlement_at, p_seat_joined_at, v_position, round(v_prize,2),round(p_bubble_refund,2),
     v_mode,v_activation_generation,round(v_head,2),v_knocker,v_claimants,
     CASE WHEN v_mode = 'mystery_chest' THEN now() + interval '30 seconds' ELSE now() END);

  -- Seat ownership is part of the same commit. A committed claim whose HTTP
  -- response is lost cannot leave a ghost at the felt after process death.
  UPDATE public.table_seats
     SET left_at=COALESCE(left_at,now())
   WHERE table_id=p_table_id AND user_id=p_eliminated_user_id
     AND joined_at=p_seat_joined_at AND left_at IS NULL;
  UPDATE public.tables
     SET current_players=(SELECT count(*) FROM public.table_seats s
                           WHERE s.table_id=p_table_id AND s.left_at IS NULL)
   WHERE id=p_table_id;
  PERFORM public.fn_sync_seat_first_player_count(p_tournament_id);

  UPDATE public.tournament_bounty_obligations o
     SET state='settled', settled_at=now()
   WHERE o.tournament_id=p_tournament_id AND o.eliminated_user_id=p_eliminated_user_id
     AND o.seat_joined_at=p_seat_joined_at
     AND public.fn_bounty_obligation_has_complete_marker(o.id);

  RETURN jsonb_build_object('ok', true, 'already', false, 'claimed', v_claimed,
    'mode', v_mode, 'state',(SELECT state FROM public.tournament_bounty_obligations o
      WHERE o.tournament_id=p_tournament_id AND o.eliminated_user_id=p_eliminated_user_id
        AND o.seat_joined_at=p_seat_joined_at),
    'activation_generation',v_activation_generation,
    'bubble_refund',0,
    'obligation_id',(SELECT id FROM public.tournament_bounty_obligations o
      WHERE o.tournament_id=p_tournament_id AND o.eliminated_user_id=p_eliminated_user_id
        AND o.seat_joined_at=p_seat_joined_at));
END;
$_$;


