--
-- Name: fn_claim_engine_maintenance_break(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_engine_maintenance_break(p_expected_ownership_token uuid, p_new_ownership_token uuid, p_declared_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '45s'
    SET lock_timeout TO '40s'
    AS $$
DECLARE
  v_row public.engine_maintenance_break%ROWTYPE;
BEGIN
  IF p_expected_ownership_token IS NULL OR p_new_ownership_token IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'ownership_token_required');
  END IF;
  PERFORM pg_advisory_xact_lock(530090, 1);
  SELECT * INTO v_row
    FROM public.engine_maintenance_break b
   WHERE b.id = true
   FOR UPDATE;
  IF NOT FOUND OR v_row.ownership_token <> p_expected_ownership_token THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'ownership_changed');
  END IF;
  UPDATE public.engine_maintenance_break
     SET ownership_token = p_new_ownership_token,
         declared_by = p_declared_by,
         updated_at = clock_timestamp()
   WHERE id = true
     AND ownership_token = p_expected_ownership_token
  RETURNING * INTO v_row;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'ownership_changed');
  END IF;
  RETURN jsonb_build_object(
    'ok', true,
    'phase', v_row.phase,
    'announced_at', v_row.announced_at,
    'break_started_at', v_row.break_started_at,
    'break_ends_at', v_row.break_ends_at,
    'reason', v_row.reason,
    'ownership_token', v_row.ownership_token
  );
END;
$$;


ALTER FUNCTION public.fn_claim_engine_maintenance_break(p_expected_ownership_token uuid, p_new_ownership_token uuid, p_declared_by text) OWNER TO postgres;

--
-- Name: fn_claim_entry_purchase_receipt(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_entry_purchase_receipt(p_key_domain text, p_idempotency_key text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request jsonb;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 THEN
    RETURN jsonb_build_object('claimed', true);
  END IF;

  INSERT INTO public.entry_purchase_idempotency_receipts
    (key_domain, idempotency_key, request)
  VALUES (p_key_domain, p_idempotency_key, p_request)
  ON CONFLICT (key_domain, idempotency_key) DO NOTHING
  RETURNING request, response INTO v_request, v_response;
  IF FOUND THEN
    RETURN jsonb_build_object('claimed', true);
  END IF;

  /* The unique-index wait above cannot observe an uncommitted placeholder.
     A committed placeholder without a response means some code violated the
     same-transaction contract, so it is corruption-not permission to rerun
     a money core. */
  SELECT r.request, r.response
    INTO STRICT v_request, v_response
    FROM public.entry_purchase_idempotency_receipts r
   WHERE r.key_domain = p_key_domain
     AND r.idempotency_key = p_idempotency_key;
  IF v_request IS DISTINCT FROM p_request THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_KEY_REUSED: % key is already bound to a different entry purchase',
      p_key_domain
      USING ERRCODE = '22023';
  END IF;
  IF v_response IS NULL THEN
    RAISE EXCEPTION
      'INCOMPLETE_IDEMPOTENCY_RECEIPT: % key was committed without its response',
      p_key_domain
      USING ERRCODE = '55000';
  END IF;
  RETURN jsonb_build_object('claimed', false, 'response', v_response);
END;
$$;


ALTER FUNCTION public.fn_claim_entry_purchase_receipt(p_key_domain text, p_idempotency_key text, p_request jsonb) OWNER TO postgres;

--
-- Name: fn_claim_rakeback(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_rakeback(p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user    uuid := (SELECT auth.uid());
  v_period  record;
  v_res     jsonb;
  v_count   int := 0;
  v_total   numeric := 0;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication required');
  END IF;

  FOR v_period IN
    SELECT id FROM public.rakeback_periods
     WHERE user_id = v_user
       AND status = 'pending'
       AND (p_club_id IS NULL OR club_id = p_club_id)
     ORDER BY period_start
     FOR UPDATE
  LOOP
    v_res := public.fn_close_settlement_period(v_period.id);
    IF COALESCE((v_res->>'success')::boolean, false) THEN
      v_total := v_total + COALESCE((v_res->>'payout')::numeric, 0);
      IF COALESCE((v_res->>'payout')::numeric, 0) > 0 THEN
        v_count := v_count + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'periods_claimed', v_count, 'total_payout', v_total);
END;
$$;


ALTER FUNCTION public.fn_claim_rakeback(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_claim_referral_milestone(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_referral_milestone(p_milestone integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller    uuid := (SELECT auth.uid());
  v_reward    integer;
  v_referrals integer;
  v_credit    jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication required');
  END IF;

  -- THE PRICING LINE. Diamonds, not chips. These four numbers are Dan's to
  -- set; everything around them is the mechanism.
  v_reward := CASE p_milestone
    WHEN 5  THEN 250
    WHEN 10 THEN 500
    WHEN 25 THEN 1500
    WHEN 50 THEN 5000
    ELSE NULL END;

  IF v_reward IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown milestone');
  END IF;

  SELECT count(*) INTO v_referrals
    FROM public.referral_redemptions
   WHERE referrer_id = v_caller;

  IF v_referrals < p_milestone THEN
    RETURN jsonb_build_object('success', false, 'error', 'milestone not reached',
                              'referrals', v_referrals);
  END IF;

  BEGIN
    INSERT INTO public.referral_milestone_claims (user_id, milestone, diamonds_awarded)
    VALUES (v_caller, p_milestone, v_reward);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('success', false, 'error', 'milestone already claimed');
  END;

  v_credit := public.add_diamonds_to_balance(
    v_caller,
    v_reward,
    'referral_milestone',
    'Referral milestone: ' || p_milestone || ' referrals',
    'referral_milestone:' || v_caller::text || ':' || p_milestone::text
  );

  IF COALESCE((v_credit->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'referral milestone % could not be credited: %',
      p_milestone, COALESCE(v_credit->>'error', 'unknown');
  END IF;

  RETURN jsonb_build_object('success', true, 'awarded', v_reward, 'currency', 'diamonds');
END;
$$;


ALTER FUNCTION public.fn_claim_referral_milestone(p_milestone integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_claim_referral_milestone(p_milestone integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_claim_referral_milestone(p_milestone integer) IS 'Claims a referral milestone and pays DIAMONDS (never chips - Dan 2026-09-05). Deduped by referral_milestone_claims, and again by add_diamonds_to_balance reference_id. Rolls the claim back if the credit fails.';


--
-- Name: fn_claim_settlement_period(text, text, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_settlement_period(p_idempotency_key text, p_period_kind text, p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row settlement_journal%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM settlement_journal WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'already_claimed',
      'existing_status', v_row.status,
      'id', v_row.id
    );
  END IF;

  INSERT INTO settlement_journal (
    idempotency_key, period_kind, period_start, period_end, union_id, status
  ) VALUES (
    p_idempotency_key, p_period_kind, p_period_start, p_period_end,
    p_union_id, 'pending'
  )
  RETURNING * INTO v_row;

  RETURN jsonb_build_object('ok', true, 'id', v_row.id);
END; $$;


ALTER FUNCTION public.fn_claim_settlement_period(p_idempotency_key text, p_period_kind text, p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_claim_shop_purchase(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_shop_purchase(p_club_id uuid, p_user_id uuid, p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_avail jsonb;
  v_item  club_shop_items;
  v_found boolean := false;
BEGIN
  -- Serialise this (user, item) for the rest of the caller's transaction.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('shop_buy:' || p_user_id::text || ':' || p_item_id::text, 0)
  );

  v_avail := fn_shop_item_availability(p_club_id, p_user_id, p_item_id);
  IF NOT COALESCE((v_avail->>'ok')::boolean, false) THEN
    RETURN v_avail;
  END IF;

  SELECT * INTO v_item FROM club_shop_items
   WHERE id = p_item_id AND club_id = p_club_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;

  IF v_item.stock IS NOT NULL THEN
    UPDATE club_shop_items
       SET stock = stock - 1
     WHERE id = p_item_id AND club_id = p_club_id AND stock > 0
    RETURNING true INTO v_found;

    IF NOT COALESCE(v_found, false) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'sold_out');
    END IF;
  END IF;

  RETURN v_avail || jsonb_build_object('stock_claimed', v_item.stock IS NOT NULL);
END;
$$;


ALTER FUNCTION public.fn_claim_shop_purchase(p_club_id uuid, p_user_id uuid, p_item_id uuid) OWNER TO postgres;

--
-- Name: fn_claim_shop_stock(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_shop_stock(p_club_id uuid, p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stock integer;
  v_found boolean := false;
BEGIN
  -- Unlimited items: nothing to claim.
  SELECT stock INTO v_stock
    FROM club_shop_items
   WHERE id = p_item_id AND club_id = p_club_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('claimed', false, 'error', 'item_not_found');
  END IF;

  IF v_stock IS NULL THEN
    RETURN jsonb_build_object('claimed', true, 'unlimited', true);
  END IF;

  UPDATE club_shop_items
     SET stock = stock - 1
   WHERE id = p_item_id
     AND club_id = p_club_id
     AND stock IS NOT NULL
     AND stock > 0
  RETURNING true INTO v_found;

  IF NOT COALESCE(v_found, false) THEN
    RETURN jsonb_build_object('claimed', false, 'error', 'sold_out');
  END IF;

  RETURN jsonb_build_object('claimed', true, 'unlimited', false);
END;
$$;


ALTER FUNCTION public.fn_claim_shop_stock(p_club_id uuid, p_item_id uuid) OWNER TO postgres;

--
-- Name: fn_claim_tournament_bounty_elimination(uuid, uuid, integer, numeric, uuid, uuid, bigint, timestamp with time zone, uuid, jsonb, numeric, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_tournament_bounty_elimination(p_tournament_id uuid, p_eliminated_user_id uuid, p_position integer, p_prize numeric, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_knocker_user_id uuid, p_claimants jsonb, p_bubble_refund numeric DEFAULT 0, p_allow_existing_eliminated boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_token uuid;
  v_result jsonb;
  v_live_seats integer;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'tournament bounty elimination requires service authority'
      USING ERRCODE='28000';
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  PERFORM 1 FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN public.fn_claim_tournament_bounty_elimination_pre_seat_guard(
      p_tournament_id,p_eliminated_user_id,p_position,p_prize,p_table_id,
      p_hand_id,p_hand_number,p_seat_joined_at,p_knocker_user_id,p_claimants,
      p_bubble_refund,p_allow_existing_eliminated);
  END IF;
  PERFORM 1 FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.user_id=p_eliminated_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN public.fn_claim_tournament_bounty_elimination_pre_seat_guard(
      p_tournament_id,p_eliminated_user_id,p_position,p_prize,p_table_id,
      p_hand_id,p_hand_number,p_seat_joined_at,p_knocker_user_id,p_claimants,
      p_bubble_refund,p_allow_existing_eliminated);
  END IF;
  SELECT count(*) INTO v_live_seats
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_eliminated_user_id AND s.left_at IS NULL;
  IF v_live_seats>1 THEN
    RAISE EXCEPTION
      'tournament bounty elimination refuses % live seats for one player',
      v_live_seats USING ERRCODE='P0404';
  END IF;
  v_token:=public.fn_ca_open_tournament_seat_exit_authority(
    p_tournament_id,'elimination',p_eliminated_user_id);
  BEGIN
    v_result:=public.fn_claim_tournament_bounty_elimination_pre_seat_guard(
      p_tournament_id,p_eliminated_user_id,p_position,p_prize,p_table_id,
      p_hand_id,p_hand_number,p_seat_joined_at,p_knocker_user_id,p_claimants,
      p_bubble_refund,p_allow_existing_eliminated);
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(
      v_token,COALESCE((v_result->>'ok')::boolean,false));
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
    RAISE;
  END;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_claim_tournament_bounty_elimination(p_tournament_id uuid, p_eliminated_user_id uuid, p_position integer, p_prize numeric, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_knocker_user_id uuid, p_claimants jsonb, p_bubble_refund numeric, p_allow_existing_eliminated boolean) OWNER TO postgres;

--
-- Name: fn_claim_tournament_bounty_elimination_pre_seat_guard(uuid, uuid, integer, numeric, uuid, uuid, bigint, timestamp with time zone, uuid, jsonb, numeric, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_tournament_bounty_elimination_pre_seat_guard(p_tournament_id uuid, p_eliminated_user_id uuid, p_position integer, p_prize numeric, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_knocker_user_id uuid, p_claimants jsonb, p_bubble_refund numeric DEFAULT 0, p_allow_existing_eliminated boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_candidate public.tournament_knockout_candidates%ROWTYPE;
  v_result jsonb;
BEGIN
  -- The predecessor takes the same tournament/player locks. Taking them first
  -- here makes the candidate check and the eventual result/status mutation one
  -- serial transaction, including exact replays after a lost HTTP response.
  PERFORM 1 FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  PERFORM 1 FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_eliminated_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','player_not_found');
  END IF;

  SELECT * INTO v_candidate
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_eliminated_user_id
     AND c.table_id=p_table_id
     AND c.hand_id=p_hand_id
     AND c.hand_number=p_hand_number
     AND c.seat_joined_at=p_seat_joined_at
   FOR UPDATE;

  IF v_candidate.id IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.hand_atomic_commits c
       WHERE c.table_id=p_table_id
         AND c.hand_id=p_hand_id
         AND c.hand_number=p_hand_number
    ) THEN
      RETURN jsonb_build_object('ok',false,'reason','atomic_knockout_candidate_missing');
    END IF;
    -- No atomic receipt means this can only be an old-pod hand. The predecessor
    -- still requires its exact settlement, history, seat and canonical-pot
    -- proof; no timestamp or caller attribution is accepted as authority.
  ELSIF v_candidate.state NOT IN ('pending','eliminated') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','knockout_generation_already_closed','state',v_candidate.state);
  ELSIF v_candidate.state='pending'
        AND v_candidate.rebuy_prompt_until IS NOT NULL
        AND v_candidate.rebuy_prompt_until>clock_timestamp() THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','rebuy_decision_open',
      'rebuy_prompt_until',v_candidate.rebuy_prompt_until);
  END IF;

  v_result := public.fn_claim_bounty_legacy_candidate_20260907(
    p_tournament_id,p_eliminated_user_id,p_position,p_prize,p_table_id,p_hand_id,
    p_hand_number,p_seat_joined_at,p_knocker_user_id,p_claimants,
    p_bubble_refund,p_allow_existing_eliminated);
  IF coalesce((v_result->>'ok')::boolean,false) AND v_candidate.id IS NOT NULL THEN
    UPDATE public.tournament_knockout_candidates c
       SET state='eliminated',resolved_at=coalesce(c.resolved_at,clock_timestamp())
     WHERE c.id=v_candidate.id AND c.state IN ('pending','eliminated');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'bounty knockout generation changed while claim committed'
        USING ERRCODE='serialization_failure';
    END IF;
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_claim_tournament_bounty_elimination_pre_seat_guard(p_tournament_id uuid, p_eliminated_user_id uuid, p_position integer, p_prize numeric, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_knocker_user_id uuid, p_claimants jsonb, p_bubble_refund numeric, p_allow_existing_eliminated boolean) OWNER TO postgres;

--
-- Name: fn_claim_tournament_finish(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_tournament_finish(p_tournament_id uuid, p_winner_user_id uuid, p_source text DEFAULT 'engine'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_receipt public.tournament_finish_receipts%ROWTYPE;
  v_kind text;
  v_rows integer := 0;
  v_live_count integer := 0;
  v_live_winner uuid;
  v_position_one uuid;
BEGIN
  IF p_tournament_id IS NULL OR p_winner_user_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','missing_ids');
  END IF;

  SELECT * INTO v_t FROM public.tournaments
   WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;

  v_kind := public.fn_tournament_finish_kind(p_tournament_id);

  SELECT * INTO v_receipt FROM public.tournament_finish_receipts
   WHERE tournament_id = p_tournament_id;
  IF FOUND THEN
    IF v_receipt.finish_kind IS DISTINCT FROM v_kind THEN
      RETURN jsonb_build_object('ok',false,'reason','finish_kind_conflict',
        'finish_kind',v_receipt.finish_kind,'observed_kind',v_kind,'status',v_t.status);
    END IF;
    IF v_t.status = 'COMPLETED' THEN
      RETURN jsonb_build_object('ok',v_receipt.certified_at IS NOT NULL,
        'reason',CASE WHEN v_receipt.certified_at IS NULL
                      THEN 'completed_without_certificate' ELSE NULL END,
        'winner_user_id',v_receipt.winner_user_id,'finish_kind',v_kind,
        'status',v_t.status,'already_completed',true);
    END IF;
    IF v_t.status = 'COMPLETING' THEN
      /* The immutable receipt outranks a stale process-local candidate after
         restart. Returning its winner is not a new claim and moves no state;
         it is the only safe way to resume an interrupted atomic settlement. */
      RETURN jsonb_build_object('ok',true,'reason',NULL,
        'winner_user_id',v_receipt.winner_user_id,'finish_kind',v_kind,
        'status',v_t.status,'claimed',false,'resumed',true,
        'candidate_mismatch',v_receipt.winner_user_id IS DISTINCT FROM p_winner_user_id);
    END IF;
    RETURN jsonb_build_object('ok',false,'reason','finish_receipt_status_conflict',
      'winner_user_id',v_receipt.winner_user_id,'status',v_t.status);
  END IF;

  IF upper(COALESCE(v_t.status,'')) NOT IN ('RUNNING','COMPLETING') THEN
    RETURN jsonb_build_object('ok',false,'reason','finish_status_not_claimable',
      'status',v_t.status);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.user_id = p_winner_user_id
  ) THEN
    RETURN jsonb_build_object('ok',false,'reason','winner_not_in_tournament');
  END IF;

  SELECT count(*), (array_agg(tp.user_id ORDER BY tp.user_id))[1]
    INTO v_live_count, v_live_winner
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status IN ('registered','playing');
  IF v_live_count = 1 AND v_live_winner IS DISTINCT FROM p_winner_user_id THEN
    RETURN jsonb_build_object('ok',false,'reason','winner_is_not_sole_survivor',
      'survivor_user_id',v_live_winner);
  END IF;
  IF v_live_count > 1 AND v_kind <> 'final_table_deal' THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_decided',
      'live_players',v_live_count);
  END IF;

  SELECT (array_agg(tp.user_id ORDER BY tp.user_id))[1]
    INTO v_position_one
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id AND tp.position = 1;
  IF v_position_one IS NOT NULL AND v_position_one IS DISTINCT FROM p_winner_user_id THEN
    RETURN jsonb_build_object('ok',false,'reason','position_one_conflict',
      'position_one_user_id',v_position_one);
  END IF;

  IF v_kind = 'final_table_deal' AND NOT EXISTS (
    SELECT 1 FROM public.tournament_final_table_deal_batches d
     WHERE d.tournament_id = p_tournament_id
       AND d.chip_leader = p_winner_user_id
  ) THEN
    RETURN jsonb_build_object('ok',false,'reason','deal_winner_conflict');
  END IF;

  INSERT INTO public.tournament_finish_receipts
    (tournament_id,winner_user_id,finish_kind,claim_source)
  VALUES
    (p_tournament_id,p_winner_user_id,v_kind,
     COALESCE(NULLIF(btrim(p_source),''),'engine'))
  ON CONFLICT (tournament_id) DO NOTHING;

  SELECT * INTO v_receipt FROM public.tournament_finish_receipts
   WHERE tournament_id = p_tournament_id;
  IF v_receipt.winner_user_id IS DISTINCT FROM p_winner_user_id
     OR v_receipt.finish_kind IS DISTINCT FROM v_kind THEN
    RETURN jsonb_build_object('ok',false,'reason','finish_claim_conflict');
  END IF;

  IF v_t.status = 'RUNNING' THEN
    PERFORM set_config('app.tournament_finish_claim', p_tournament_id::text, true);
    UPDATE public.tournaments SET status = 'COMPLETING'
     WHERE id = p_tournament_id AND status = 'RUNNING';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    PERFORM set_config('app.tournament_finish_claim', '', true);
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'finish claim CAS changed % rows for tournament %',
        v_rows, p_tournament_id USING ERRCODE = '40001';
    END IF;
  END IF;

  RETURN jsonb_build_object('ok',true,'reason',NULL,
    'winner_user_id',p_winner_user_id,'finish_kind',v_kind,
    'status','COMPLETING','claimed',true,'resumed',(v_t.status = 'COMPLETING'));
END;
$$;


ALTER FUNCTION public.fn_claim_tournament_finish(p_tournament_id uuid, p_winner_user_id uuid, p_source text) OWNER TO postgres;

--
-- Name: fn_claim_training_streak_milestone_v2(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_training_streak_milestone_v2(p_user_id uuid, p_milestone_days integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  streak_row public.training_streaks%ROWTYPE;
  claim_row public.training_streak_milestone_claims%ROWTYPE;
  milestone_diamonds integer;
  milestone_name text;
  award_result jsonb := '{}'::jsonb;
  award_amount integer := 0;
  award_requested integer := 0;
  award_total integer := 0;
  award_entitlement integer := 0;
  award_response_entitlement integer := 0;
  award_remaining integer := 0;
  award_multiplier numeric(12,6) := 1.00;
  milestone_completed boolean := false;
  claim_row_exists boolean := false;
  claim_reference text;
BEGIN
  IF p_user_id IS NULL OR p_milestone_days IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'status', 400,
      'code', 'TRAINING_STREAK_MILESTONE_INPUT_INVALID',
      'error', 'A valid user and streak milestone are required.'
    );
  END IF;

  SELECT milestone.diamonds, milestone.name
  INTO milestone_diamonds, milestone_name
  FROM (VALUES
    (3, 25, '3-Day Streak'::text),
    (7, 75, 'Week Warrior'::text),
    (14, 150, 'Two Week Champion'::text),
    (30, 400, 'Monthly Master'::text),
    (60, 800, 'Double Month Legend'::text),
    (100, 2000, 'Century Grinder'::text),
    (365, 10000, 'Year of Dedication'::text)
  ) AS milestone(days, diamonds, name)
  WHERE milestone.days = p_milestone_days;

  IF milestone_diamonds IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'status', 400,
      'code', 'TRAINING_STREAK_MILESTONE_INVALID',
      'error', 'This Training streak milestone does not exist.'
    );
  END IF;

  -- Use the same cross-RPC lock order as award_diamonds_v2 before touching
  -- training_streaks. Without this boundary a milestone claim can hold the
  -- streak row while completion holds the award lock, leaving each RPC
  -- waiting for the other for the same user.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    1799876946,
    pg_catalog.hashtext(p_user_id::text)
  );

  SELECT * INTO streak_row
  FROM public.training_streaks
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'status', 404,
      'code', 'TRAINING_STREAK_NOT_FOUND',
      'error', 'No verified Training streak exists for this user.'
    );
  END IF;

  IF greatest(
      streak_row.authority_current_streak,
      streak_row.authority_longest_streak
    ) < p_milestone_days THEN
    RETURN jsonb_build_object(
      'success', false,
      'status', 409,
      'code', 'TRAINING_STREAK_MILESTONE_NOT_REACHED',
      'error', 'This Training streak milestone has not been reached.',
      'currentStreak', streak_row.authority_current_streak,
      'milestoneDays', p_milestone_days
    );
  END IF;

  -- Read the payout ledger while the same per-user lock and streak row lock
  -- are held. A completed ledger is the source of the exact credited total;
  -- the legacy milestone JSON alone can only fall back to the base amount.
  SELECT * INTO claim_row
  FROM public.training_streak_milestone_claims
  WHERE user_id = p_user_id AND milestone_days = p_milestone_days
  FOR UPDATE;
  claim_row_exists := FOUND;

  IF streak_row.authority_milestones_claimed
      @> jsonb_build_array(p_milestone_days) THEN
    award_total := CASE
      WHEN claim_row_exists THEN claim_row.diamonds_awarded
      ELSE milestone_diamonds
    END;
    award_multiplier := CASE
      WHEN claim_row_exists THEN coalesce(claim_row.reward_multiplier, 1.00)
      ELSE 1.00
    END;
    RETURN jsonb_build_object(
      'success', true,
      'newClaim', false,
      'awardApplied', false,
      'milestoneCompleted', true,
      'milestoneDays', p_milestone_days,
      'diamondsAwarded', 0,
      'diamondsAwardedTotal', award_total,
      'diamondsRemaining', 0,
      'entitlementDiamonds', award_total,
      'rewardMultiplier', award_multiplier
    );
  END IF;

  IF NOT claim_row_exists THEN
    INSERT INTO public.training_streak_milestone_claims(
      user_id, milestone_days, diamonds_awarded, claim_count
    ) VALUES (p_user_id, p_milestone_days, 0, 0)
    ON CONFLICT (user_id, milestone_days) DO NOTHING;

    SELECT * INTO claim_row
    FROM public.training_streak_milestone_claims
    WHERE user_id = p_user_id AND milestone_days = p_milestone_days
    FOR UPDATE;
  END IF;

  IF claim_row.completed_at IS NOT NULL
     OR (
       claim_row.entitlement_diamonds IS NOT NULL
       AND claim_row.diamonds_awarded >= claim_row.entitlement_diamonds
     ) THEN
    UPDATE public.training_streaks
    SET authority_milestones_claimed = CASE
          WHEN authority_milestones_claimed
              @> jsonb_build_array(p_milestone_days)
            THEN authority_milestones_claimed
          ELSE authority_milestones_claimed
            || jsonb_build_array(p_milestone_days)
        END,
        milestones_claimed = CASE
          WHEN authority_milestones_claimed
              @> jsonb_build_array(p_milestone_days)
            THEN authority_milestones_claimed
          ELSE authority_milestones_claimed
            || jsonb_build_array(p_milestone_days)
        END,
        updated_at = now()
    WHERE user_id = p_user_id;
    RETURN jsonb_build_object(
      'success', true,
      'newClaim', false,
      'awardApplied', false,
      'milestoneCompleted', true,
      'milestoneDays', p_milestone_days,
      'diamondsAwarded', 0,
      'diamondsAwardedTotal', claim_row.diamonds_awarded,
      'diamondsRemaining', 0,
      'entitlementDiamonds', coalesce(
        claim_row.entitlement_diamonds,
        claim_row.diamonds_awarded
      ),
      'rewardMultiplier', coalesce(claim_row.reward_multiplier, 1.00)
    );
  END IF;

  award_entitlement := coalesce(claim_row.entitlement_diamonds, 0);
  award_remaining := CASE
    WHEN award_entitlement > 0
      THEN award_entitlement - claim_row.diamonds_awarded
    ELSE milestone_diamonds
  END;
  claim_reference := 'streak_' || p_user_id::text || '_'
    || p_milestone_days::text || '_part_' || (claim_row.claim_count + 1)::text;
  award_result := public.award_diamonds_v2(
    p_user_id,
    'streak_reward',
    claim_reference,
    claim_reference,
    jsonb_build_object(
      'streak_diamonds', award_remaining,
      'milestone_name', milestone_name,
      'milestone_days', p_milestone_days,
      'post_multiplier_entitlement', award_entitlement > 0,
      '_source', 'fn_claim_training_streak_milestone_v2'
    )
  );

  BEGIN
    award_amount := greatest(0, coalesce(nullif(award_result ->> 'awarded', '')::integer, 0));
    award_requested := greatest(0, coalesce(nullif(award_result ->> 'requested', '')::integer, 0));
    award_response_entitlement := greatest(0, coalesce(
      nullif(award_result ->> 'entitlement', '')::integer,
      claim_row.diamonds_awarded + award_requested
    ));
    award_multiplier := coalesce(nullif(award_result ->> 'multiplier', '')::numeric, 1.00);
    IF award_multiplier <= 0 OR award_multiplier > 10 THEN
      award_multiplier := 1.00;
    END IF;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RETURN jsonb_build_object(
      'success', false,
      'status', 502,
      'code', 'TRAINING_STREAK_AWARD_INVALID_RESPONSE',
      'error', 'The streak reward response was invalid.'
    );
  END;

  IF award_response_entitlement < claim_row.diamonds_awarded
     OR award_response_entitlement > milestone_diamonds * 10 THEN
    RAISE EXCEPTION USING
      ERRCODE = '22003',
      MESSAGE = 'TRAINING_STREAK_ENTITLEMENT_OUT_OF_RANGE';
  END IF;

  IF NOT (award_result @> '{"success": true}'::jsonb) THEN
    -- Even a cap/budget deferral is an authoritative multiplier snapshot.
    -- Persist it without advancing claim_count so the same exact part can be
    -- retried in a later allowance window without repricing the milestone.
    IF award_entitlement <= 0 AND award_response_entitlement > 0 THEN
      UPDATE public.training_streak_milestone_claims
      SET entitlement_diamonds = award_response_entitlement,
          reward_multiplier = award_multiplier,
          updated_at = now()
      WHERE user_id = p_user_id AND milestone_days = p_milestone_days;
    END IF;
    RETURN jsonb_build_object(
      'success', false,
      'status', 409,
      'code', 'TRAINING_STREAK_AWARD_NOT_APPLIED',
      'error', 'The streak reward could not be applied yet.',
      'rewardVerdict', award_result
    );
  END IF;

  IF award_amount > milestone_diamonds * 10 THEN
    RAISE EXCEPTION USING
      ERRCODE = '22003',
      MESSAGE = 'TRAINING_STREAK_AWARD_OUT_OF_RANGE';
  END IF;

  IF award_entitlement <= 0 THEN
    -- The award RPC returns its final post-multiplier request before family
    -- and platform caps. Snapshot it once so later cap-window installments do
    -- not reapply a changed profile multiplier.
    award_entitlement := award_response_entitlement;
  ELSE
    award_multiplier := coalesce(claim_row.reward_multiplier, award_multiplier);
  END IF;
  IF award_entitlement <= 0
     OR award_entitlement < claim_row.diamonds_awarded + award_amount THEN
    RAISE EXCEPTION USING
      ERRCODE = '22003',
      MESSAGE = 'TRAINING_STREAK_ENTITLEMENT_OUT_OF_RANGE';
  END IF;

  award_total := claim_row.diamonds_awarded + award_amount;
  milestone_completed := award_total >= award_entitlement;

  UPDATE public.training_streak_milestone_claims
  SET diamonds_awarded = award_total,
      entitlement_diamonds = award_entitlement,
      reward_multiplier = award_multiplier,
      claim_count = claim_count + 1,
      completed_at = CASE WHEN milestone_completed THEN now() ELSE completed_at END,
      updated_at = now()
  WHERE user_id = p_user_id AND milestone_days = p_milestone_days;

  IF milestone_completed THEN
    UPDATE public.training_streaks
    SET authority_milestones_claimed = authority_milestones_claimed
          || jsonb_build_array(p_milestone_days),
        milestones_claimed = authority_milestones_claimed
          || jsonb_build_array(p_milestone_days),
        updated_at = now()
    WHERE user_id = p_user_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'newClaim', milestone_completed,
    'awardApplied', true,
    'milestoneCompleted', milestone_completed,
    'milestoneDays', p_milestone_days,
    'diamondsAwarded', award_amount,
    'diamondsAwardedTotal', award_total,
    'diamondsRemaining', greatest(award_entitlement - award_total, 0),
    'entitlementDiamonds', award_entitlement,
    'rewardMultiplier', award_multiplier,
    'rewardVerdict', award_result
  );
END;
$$;


ALTER FUNCTION public.fn_claim_training_streak_milestone_v2(p_user_id uuid, p_milestone_days integer) OWNER TO postgres;

--
-- Name: fn_classify_engine_recovery_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_classify_engine_recovery_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.event_class = 'fault_injection' THEN
    RETURN NEW;
  END IF;

  IF NEW.detail IN ('drill', 'fault_injection_drill') THEN
    NEW.event_class := 'fault_injection';
    RETURN NEW;
  END IF;

  IF NEW.table_id IN (
       'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'::uuid,
       '50505050-5050-4050-8050-505050505050'::uuid,
       'eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee'::uuid
     )
     AND NOT EXISTS (SELECT 1 FROM public.tables t WHERE t.id = NEW.table_id) THEN
    NEW.event_class := 'fault_injection';
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_classify_engine_recovery_event() OWNER TO postgres;

--
-- Name: FUNCTION fn_classify_engine_recovery_event(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_classify_engine_recovery_event() IS 'Compatibility classifier for recovery events written by pre-event_class engines and known test fixtures. New engines write event_class explicitly; exact legacy drills are forced to fault_injection while every other row retains automatic_recovery.';


--
-- Name: fn_clawback_chips_atomic(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_clawback_chips_atomic(p_transaction_id uuid, p_club_id uuid, p_agent_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tx RECORD;
  v_to_user_balance NUMERIC;
  v_agent_balance NUMERIC;
BEGIN
  SELECT id, from_user_id, to_user_id, amount, is_reversed, clawed_back,
         reversible_until, transaction_type, club_id
    INTO v_tx
    FROM chip_transactions WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'transaction_not_found'); END IF;
  IF v_tx.is_reversed OR v_tx.clawed_back THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_reversed'); END IF;
  IF v_tx.club_id IS NOT NULL AND v_tx.club_id <> p_club_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'club_mismatch'); END IF;
  IF v_tx.reversible_until IS NOT NULL AND v_tx.reversible_until < NOW() THEN
    RETURN jsonb_build_object('success', false, 'error', 'clawback_window_expired', 'expired_at', v_tx.reversible_until); END IF;
  IF v_tx.amount <> p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount_mismatch', 'expected', v_tx.amount, 'got', p_amount); END IF;
  UPDATE agents SET player_balance = COALESCE(player_balance, 0) - p_amount, updated_at = NOW()
    WHERE user_id = v_tx.to_user_id AND club_id = p_club_id
    RETURNING player_balance INTO v_to_user_balance;
  IF v_to_user_balance IS NULL THEN
    UPDATE wallets SET balance = COALESCE(balance, 0) - p_amount, updated_at = NOW()
      WHERE user_id = v_tx.to_user_id AND wallet_type = 'PLAYER'
      RETURNING balance INTO v_to_user_balance;
  END IF;
  IF v_to_user_balance IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'recipient_wallet_not_found'); END IF;
  IF v_to_user_balance < 0 THEN
    RAISE EXCEPTION 'Recipient has spent the distributed chips - clawback would create negative balance'; END IF;
  UPDATE agents SET business_balance = COALESCE(business_balance, 0) + p_amount, updated_at = NOW()
    WHERE id = p_agent_id RETURNING business_balance INTO v_agent_balance;
  IF v_agent_balance IS NULL THEN RAISE EXCEPTION 'Agent not found: %', p_agent_id; END IF;
  UPDATE chip_transactions SET is_reversed = true, clawed_back = true WHERE id = p_transaction_id;
  INSERT INTO chip_transactions (
    club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after, metadata
  ) VALUES (
    p_club_id, v_tx.to_user_id,
    (SELECT user_id FROM agents WHERE id = p_agent_id),
    p_amount, 'CLAWBACK',
    format('Clawback of transaction %s', p_transaction_id),
    v_agent_balance,
    jsonb_build_object('reversed_transaction_id', p_transaction_id, 'clawback_by_agent_id', p_agent_id)
  );
  RETURN jsonb_build_object('success', true, 'clawed_back', p_amount,
    'reversed_transaction_id', p_transaction_id,
    'new_recipient_balance', v_to_user_balance,
    'new_agent_balance', v_agent_balance);
END;
$$;


ALTER FUNCTION public.fn_clawback_chips_atomic(p_transaction_id uuid, p_club_id uuid, p_agent_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_clawback_chips_atomic(p_transaction_id uuid, p_club_id uuid, p_agent_id uuid, p_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_clawback_chips_atomic(p_transaction_id uuid, p_club_id uuid, p_agent_id uuid, p_amount numeric) IS 'BUG 010 FIX 2026-04-15 — real atomic clawback replacing stub that wrote to non-existent clawback_audit_log';


--
-- Name: fn_cleanup_expired_stories(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cleanup_expired_stories(p_grace_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted int;
  v_grace int;
BEGIN
  -- Defensive clamp: never run with grace=0 (would delete stories at
  -- the exact moment they expire - too aggressive). Min 1h, max 7d.
  v_grace := GREATEST(1, LEAST(168, COALESCE(p_grace_hours, 24)));

  DELETE FROM social_stories
  WHERE expires_at < (now() - make_interval(hours => v_grace));

  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted,
    'grace_hours', v_grace,
    'cutoff', (now() - make_interval(hours => v_grace))::text
  );
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_cleanup_expired_stories failed: % %', SQLERRM, SQLSTATE;
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION public.fn_cleanup_expired_stories(p_grace_hours integer) OWNER TO postgres;

--
-- Name: fn_cleanup_home_group_polymorphic_refs(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cleanup_home_group_polymorphic_refs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- 1) Clean up the linked social_page
  BEGIN
    DELETE FROM public.social_pages
    WHERE linked_entity_type = 'home_group'
      AND linked_entity_id = OLD.id::text;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_cleanup_home_group_polymorphic_refs: social_pages cleanup failed for group=%: % (%)',
      OLD.id, SQLERRM, SQLSTATE;
  END;

  -- 2) Clean up the linked conversation
  BEGIN
    IF OLD.messenger_conversation_id IS NOT NULL THEN
      DELETE FROM public.conversations
      WHERE id = OLD.messenger_conversation_id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_cleanup_home_group_polymorphic_refs: conversations cleanup failed for group=%: % (%)',
      OLD.id, SQLERRM, SQLSTATE;
  END;

  RETURN OLD;
END;
$$;


ALTER FUNCTION public.fn_cleanup_home_group_polymorphic_refs() OWNER TO postgres;

--
-- Name: fn_cleanup_home_join_attempts(); Type: FUNCTION; Schema: public; Owner: postgres
