--
-- Name: fn_cleanup_stale_scheduled_home_games(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cleanup_stale_scheduled_home_games(p_grace_days integer DEFAULT 1) RETURNS TABLE(rows_updated integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_updated int;
BEGIN
    IF p_grace_days < 0 THEN
        RAISE EXCEPTION 'p_grace_days must be non-negative' USING ERRCODE = '22023';
    END IF;

    UPDATE commander_home_games
       SET status     = 'completed',
           updated_at = NOW()
     WHERE status = 'scheduled'
       AND scheduled_date < CURRENT_DATE - (p_grace_days || ' days')::interval;

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    RETURN QUERY SELECT v_updated;
END;
$$;


ALTER FUNCTION public.fn_cleanup_stale_scheduled_home_games(p_grace_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_cleanup_stale_scheduled_home_games(p_grace_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cleanup_stale_scheduled_home_games(p_grace_days integer) IS 'Phase 22 janitor. Flips past-dated status=scheduled home games to status=completed. Call from cron; default 1-day grace window. Returns count of rows updated.';


--
-- Name: fn_cleanup_stale_scheduled_lives(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cleanup_stale_scheduled_lives() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted_count integer := 0;
BEGIN
  -- Anything 24h past its scheduled_at that never converted to a live row is
  -- garbage. The broadcaster either never went live, or the system already
  -- forgot about it. Keeping it bloats GET /api/live/schedule for everyone.
  WITH stale AS (
    DELETE FROM public.scheduled_lives
     WHERE scheduled_at < now() - interval '24 hours'
    RETURNING id
  )
  SELECT count(*) INTO v_deleted_count FROM stale;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted_count
  );
END;
$$;


ALTER FUNCTION public.fn_cleanup_stale_scheduled_lives() OWNER TO postgres;

--
-- Name: FUNCTION fn_cleanup_stale_scheduled_lives(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cleanup_stale_scheduled_lives() IS 'Deletes scheduled_lives rows whose scheduled_at is more than 24h in the past. Invoked from /api/cron/live-reminders. service_role only.';


--
-- Name: fn_cleanup_stale_viewers(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cleanup_stale_viewers(p_timeout_minutes integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted_count integer := 0;
BEGIN
  -- Delete viewer rows older than p_timeout_minutes since last heartbeat.
  -- The broadcaster's StreamPreviewCapture refreshes preview_updated_at
  -- every ~25s while alive; named viewers heartbeat every ~30s from the
  -- LiveStreamService viewer loop. 5 minutes is a comfortable margin: a
  -- viewer with a 30s cellular dropout doesn't get pruned, but a tab
  -- crash 5+ minutes ago does.
  WITH stale AS (
    DELETE FROM public.live_viewers
     WHERE last_seen_at < now() - (p_timeout_minutes || ' minutes')::interval
    RETURNING id
  )
  SELECT count(*) INTO v_deleted_count FROM stale;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted_count,
    'timeout_minutes', p_timeout_minutes
  );
END;
$$;


ALTER FUNCTION public.fn_cleanup_stale_viewers(p_timeout_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_cleanup_stale_viewers(p_timeout_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cleanup_stale_viewers(p_timeout_minutes integer) IS 'Deletes live_viewers rows older than p_timeout_minutes since last_seen_at. Invoked from /api/cron/cleanup-stale-streams. service_role only. Defends against ghost viewers from force-quit / signal drop / tab crash.';


--
-- Name: fn_clear_engine_maintenance_break(text, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_clear_engine_maintenance_break(p_phase text, p_announced_at timestamp with time zone, p_break_started_at timestamp with time zone, p_break_ends_at timestamp with time zone, p_reason text, p_ownership_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '45s'
    SET lock_timeout TO '40s'
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  IF p_ownership_token IS NULL THEN
    RAISE EXCEPTION 'MAINTENANCE_OWNERSHIP_REQUIRED: a break may only clear its own generation'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(530090, 1);
  DELETE FROM public.engine_maintenance_break b
   WHERE b.id = true
     AND b.phase IS NOT DISTINCT FROM p_phase
     AND b.announced_at IS NOT DISTINCT FROM p_announced_at
     AND b.break_started_at IS NOT DISTINCT FROM p_break_started_at
     AND b.break_ends_at IS NOT DISTINCT FROM p_break_ends_at
     AND b.reason IS NOT DISTINCT FROM p_reason
     AND b.ownership_token = p_ownership_token;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted = 1;
END;
$$;


ALTER FUNCTION public.fn_clear_engine_maintenance_break(p_phase text, p_announced_at timestamp with time zone, p_break_started_at timestamp with time zone, p_break_ends_at timestamp with time zone, p_reason text, p_ownership_token uuid) OWNER TO postgres;

--
-- Name: fn_clear_sitout_on_turnover(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_clear_sitout_on_turnover() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.left_at IS NOT NULL AND OLD.left_at IS NULL THEN
    NEW.is_sitting_out := false;
    NEW.sit_out_at := NULL;
  ELSIF NEW.left_at IS NULL AND OLD.left_at IS NOT NULL
        AND NEW.is_sitting_out IS NOT DISTINCT FROM OLD.is_sitting_out THEN
    NEW.is_sitting_out := false;
    NEW.sit_out_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_clear_sitout_on_turnover() OWNER TO postgres;

--
-- Name: fn_clear_table_seats(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_clear_table_seats(p_table_id uuid, p_reopen boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_cleared integer:=0;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'fn_clear_table_seats requires service authority'
      USING ERRCODE='28000';
  END IF;
  SELECT tb.tournament_id INTO v_tournament_id
    FROM public.tables tb WHERE tb.id=p_table_id FOR UPDATE;
  IF NOT FOUND THEN RETURN 0; END IF;
  IF v_tournament_id IS NOT NULL THEN
    RAISE EXCEPTION 'TOURNAMENT_SEAT_EXIT_REQUIRES_TOURNAMENT_AUTHORITY'
      USING ERRCODE='55000';
  END IF;
  PERFORM public.fn_cashout_seats_for_closing_table(p_table_id,'seats cleared');
  UPDATE public.table_seats
     SET left_at=now(),is_sitting_out=false
   WHERE table_id=p_table_id AND left_at IS NULL;
  GET DIAGNOSTICS v_cleared=ROW_COUNT;
  UPDATE public.tables
     SET current_players=0,
         status=CASE WHEN p_reopen AND status<>'closed' THEN 'waiting' ELSE status END
   WHERE id=p_table_id;
  RETURN v_cleared;
END;
$$;


ALTER FUNCTION public.fn_clear_table_seats(p_table_id uuid, p_reopen boolean) OWNER TO postgres;

--
-- Name: fn_clone_table_row(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_clone_table_row(p_source_id uuid, p_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_row jsonb;
  v_new uuid := gen_random_uuid();
  v_cols text;
BEGIN
  SELECT to_jsonb(t) INTO v_row FROM public.tables t WHERE t.id = p_source_id LIMIT 1;
  IF v_row IS NULL THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: %', p_source_id;
  END IF;

  -- Identity and live state do not carry over.
  v_row := v_row || jsonb_build_object(
    'id',              v_new,
    'is_template',     false,
    'status',          'waiting',
    'current_players', 0,
    'hands_dealt',     0,
    'avg_pot',         0,
    'live_state',      NULL,
    'is_deleted',      false,
    'created_at',      now(),
    'updated_at',      now(),
    -- BOMB POT LIVE STATE (2026-08-28). Engine-written, per-table, and NOT
    -- part of the template: a clone that inherited these would deal a bomb
    -- pot it never earned. The bomb CONFIG columns are untouched on purpose.
    'bomb_pot_sched_state',    NULL,
    'bomb_pot_next_due_at',    NULL,
    'bomb_pot_manual_pending', false
  );

  -- ── NOR DOES ITS PLACE IN THE GAME (2026-09-06) ──────────────────────────
  -- `cluster_id` stays (tables_cash_needs_a_game refuses an open cash table
  -- without one), but role / main_index / lifecycle and their timestamps are
  -- the answer to "which table of this game are you", and the clone is a NEW
  -- one. Copying them made a clone of Main 1 a second Main 1. It joins as an
  -- opening feeder, the shape the controller's OPEN rule creates and already
  -- knows how to promote, break or abandon.
  IF (v_row -> 'cluster_id') IS NOT NULL AND jsonb_typeof(v_row -> 'cluster_id') <> 'null' THEN
    v_row := v_row || jsonb_build_object(
      'role',                 'feeder',
      'main_index',           NULL,
      'lifecycle',            'opening',
      'opened_at',            now(),
      'live_at',              NULL,
      'break_started_at',     NULL,
      'break_eligible_since', NULL,
      'promote_pending',      false
    );
  END IF;

  IF p_name IS NOT NULL THEN
    v_row := v_row || jsonb_build_object('name', p_name);
  END IF;

  -- ── AND IT COULD NOT INSERT AT ALL (2026-09-06) ──────────────────────────
  -- This was `INSERT INTO public.tables SELECT * FROM jsonb_populate_record(
  -- NULL::public.tables, v_row)`, and `public.tables` has FOUR GENERATED
  -- columns - `min_buyin`, `max_buyin`, `min_buy_in_bb`, `max_buy_in_bb`, all
  -- derived from min/max_buy_in and big_blind. `SELECT *` names them, and
  -- Postgres refuses a non-DEFAULT value for a generated column:
  --
  --   428C9 cannot insert a non-DEFAULT value into column "min_buy_in_bb"
  --
  -- So every call has raised since those columns were added, and BOTH callers
  -- were broken: `fn_launch_table_from_template` (a live operator feature) and
  -- `fn_table_lifecycle_pass`'s AUTO CREATE arm - whose only handler is
  -- `EXCEPTION WHEN unique_violation`, which does not catch 428C9, so the
  -- whole pass aborted. Found by the rolled-back probe for this migration; the
  -- clone path has no test and no caller that reports, so nothing said so.
  --
  -- The column list is read from the catalogue rather than written down, so a
  -- FIFTH generated column cannot break it again the way the first four did.
  SELECT string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position)
    INTO v_cols
    FROM information_schema.columns c
   WHERE c.table_schema = 'public'
     AND c.table_name = 'tables'
     AND c.is_generated = 'NEVER'
     AND c.is_identity <> 'YES';

  EXECUTE format(
    'INSERT INTO public.tables (%s) SELECT %s FROM jsonb_populate_record(NULL::public.tables, $1)',
    v_cols, v_cols
  ) USING v_row;

  RETURN v_new;
END;
$_$;


ALTER FUNCTION public.fn_clone_table_row(p_source_id uuid, p_name text) OWNER TO postgres;

--
-- Name: FUNCTION fn_clone_table_row(p_source_id uuid, p_name text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_clone_table_row(p_source_id uuid, p_name text) IS 'Clones a table row. Identity, live state, bomb-pot live state AND the table''s place in its game (role/main_index/lifecycle) are reset: a clustered clone joins as an opening feeder, never as a second Main 1. Inserts by explicit column list read from the catalogue, because public.tables has generated columns that SELECT * cannot write (2026-09-06).';


--
-- Name: fn_close_club_wallets_on_union_join(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_close_club_wallets_on_union_join(p_club_id uuid, p_union_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_spin jsonb;
  v_bbj_main numeric := 0; v_bbj_backup numeric := 0; v_bbj_promo numeric := 0;
  v_bbj_total numeric := 0; v_club_promo numeric := 0;
  v_keep_main numeric; v_keep_backup numeric; v_pool_id uuid; v_union_pool uuid; v_after numeric; v_treasury numeric;
BEGIN
  IF p_club_id IS NULL OR p_union_id IS NULL OR p_club_id = p_union_id THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'nothing_to_close');
  END IF;

  v_spin := public.fn_spin_absorb_club_pool_into_union(p_club_id, p_union_id);

  SELECT id, COALESCE(main_balance,0), COALESCE(backup_balance,0), COALESCE(promo_balance,0)
    INTO v_pool_id, v_bbj_main, v_bbj_backup, v_bbj_promo
    FROM public.bbj_pools
   WHERE club_id = p_club_id AND union_id IS NULL
   FOR UPDATE;

  IF v_pool_id IS NOT NULL THEN
    v_keep_main := public.fn_bbj_parked_reserve(v_pool_id,'main');
    v_keep_backup := public.fn_bbj_parked_reserve(v_pool_id,'backup');
    v_bbj_main := v_bbj_main-v_keep_main;
    v_bbj_backup := v_bbj_backup-v_keep_backup;
    IF v_bbj_main<0 OR v_bbj_backup<0 THEN
      RAISE EXCEPTION 'club jackpot bank cannot cover its parked obligations';
    END IF;
    v_bbj_total := v_bbj_main + v_bbj_backup + v_bbj_promo;
    SELECT id INTO v_union_pool FROM public.bbj_pools WHERE union_id = p_union_id LIMIT 1;

    IF v_bbj_total > 0 THEN
      v_after := public.fn_spin_move_owner_wallet(p_club_id, 'club', 'chip_treasury', v_bbj_total);
      IF v_after IS NULL THEN
        RAISE EXCEPTION 'cannot pay the % BBJ balance of club % into its treasury', v_bbj_total, p_club_id;
      END IF;

      -- bbj_promo_sweep so fn_bbj_conservation_check counts this as OUTFLOW.
      -- Without this row the gap moves by exactly v_bbj_total and a correct
      -- transfer reads as a money leak.
      INSERT INTO public.chip_transactions
        (id, club_id, amount, transaction_type, notes, balance_after, metadata)
      VALUES (gen_random_uuid(), p_club_id, v_bbj_total, 'bbj_promo_sweep',
              format('BBJ, backup and promo closed into the club main bank on joining union %s - the club keeps these funds. Play moves to the union pool; this money does not.', p_union_id),
              v_after,
              jsonb_build_object('reason','union_join','union_id',p_union_id,
                                 'bbj_main',v_bbj_main,'bbj_backup',v_bbj_backup,
                                 'bbj_promo',v_bbj_promo,'club_pool_id',v_pool_id));
    END IF;

    UPDATE public.bbj_pools
       SET main_balance = v_keep_main, backup_balance = v_keep_backup, promo_balance = 0,
           status = 'retired',
           merged_into_pool_id = COALESCE(merged_into_pool_id, v_union_pool),
           updated_at = now()
     WHERE id = v_pool_id;
  END IF;

  SELECT COALESCE(promo_balance,0) INTO v_club_promo
    FROM public.clubs WHERE id = p_club_id FOR UPDATE;

  IF v_club_promo > 0 THEN
    UPDATE public.clubs
       SET chip_treasury = COALESCE(chip_treasury,0) + v_club_promo,
           promo_balance = 0
     WHERE id = p_club_id
     RETURNING chip_treasury INTO v_treasury;

    INSERT INTO public.chip_transactions
      (id, club_id, amount, transaction_type, notes, balance_after, metadata)
    VALUES (gen_random_uuid(), p_club_id, v_club_promo, 'promo_closed_on_union_join',
            format('Club promo float closed into the main bank on joining union %s - the club keeps these funds to disburse at its own discretion', p_union_id),
            v_treasury,
            jsonb_build_object('reason','union_join','union_id',p_union_id));
  END IF;

  RETURN jsonb_build_object('ok', true, 'club_id', p_club_id, 'union_id', p_union_id,
    'spins', v_spin, 'bbj_swept', v_bbj_total, 'club_promo_swept', v_club_promo,
    'club_treasury_after', COALESCE(v_treasury, v_after));
END;
$$;


ALTER FUNCTION public.fn_close_club_wallets_on_union_join(p_club_id uuid, p_union_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_close_club_wallets_on_union_join(p_club_id uuid, p_union_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_close_club_wallets_on_union_join(p_club_id uuid, p_union_id uuid) IS 'On union join: Spins, BBJ, backup BBJ and both promo floats close into clubs.chip_treasury. BBJ movements book as bbj_promo_sweep so fn_bbj_conservation_check sees them as outflow and the gap does not move.';


--
-- Name: fn_close_due_settlement_periods(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_close_due_settlement_periods(p_grace_days integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_closed int := 0;
  v_ids uuid[];
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_platform_admin())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  WITH due AS (
    UPDATE settlement_periods sp
       SET status = 'closed', updated_at = now()
     WHERE sp.status = 'settled'
       AND sp.end_at + make_interval(days => p_grace_days) < now()
     RETURNING sp.id
  )
  SELECT array_agg(id), count(*) INTO v_ids, v_closed FROM due;

  RETURN jsonb_build_object('periods_closed', COALESCE(v_closed, 0),
                            'grace_days', p_grace_days,
                            'closed_ids', COALESCE(to_jsonb(v_ids), '[]'::jsonb),
                            'ran_at', now());
END $$;


ALTER FUNCTION public.fn_close_due_settlement_periods(p_grace_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_close_due_settlement_periods(p_grace_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_close_due_settlement_periods(p_grace_days integer) IS 'Moves a settled settlement period to closed once it is past end_at plus the grace period. Never touches a disputed period. Runs hourly from fn_union_integrity_sweep_all.';


--
-- Name: fn_close_empty_tournament_table(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_close_empty_tournament_table(p_tournament_id uuid, p_table_id uuid, p_lease_generation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor text;
  v_actor_tournament_id uuid;
  v_actor_generation uuid;
  v_parent_status text;
  v_table_status text;
  v_current_players integer;
BEGIN
  IF p_tournament_id IS NULL OR p_table_id IS NULL OR p_lease_generation IS NULL THEN
    RAISE EXCEPTION 'fn_close_empty_tournament_table requires three UUIDs'
      USING ERRCODE = '22023';
  END IF;

  v_actor := current_setting('app.smarter_data_actor', true);
  BEGIN
    v_actor_tournament_id :=
      NULLIF(current_setting('app.smarter_tournament_id', true), '')::uuid;
    v_actor_generation :=
      NULLIF(current_setting('app.smarter_tournament_lease_generation', true), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'TOURNAMENT_MANAGER_FENCED: malformed request authority'
      USING ERRCODE = '42501';
  END;

  IF v_actor IS DISTINCT FROM 'tournament-manager'
     OR v_actor_tournament_id IS DISTINCT FROM p_tournament_id
     OR v_actor_generation IS DISTINCT FROM p_lease_generation THEN
    RAISE EXCEPTION 'TOURNAMENT_MANAGER_FENCED: table close authority does not match request'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1
    FROM public.engine_tournament_leases l
   WHERE l.tournament_id = p_tournament_id
     AND l.protocol_version = 2
     AND l.lease_generation = p_lease_generation
     AND l.heartbeat_at >= clock_timestamp() - interval '30 seconds'
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TOURNAMENT_MANAGER_FENCED: table close lease is stale'
      USING ERRCODE = '42501';
  END IF;

  SELECT upper(t.status::text)
    INTO v_parent_status
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND OR v_parent_status <> 'RUNNING' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'tournament_not_running',
      'status', v_parent_status
    );
  END IF;

  SELECT lower(t.status::text), COALESCE(t.current_players, 0)
    INTO v_table_status, v_current_players
    FROM public.tables t
   WHERE t.id = p_table_id
     AND t.tournament_id = p_tournament_id
     AND NOT COALESCE(t.is_deleted, false)
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;

  PERFORM 1
    FROM public.table_seats s
   WHERE s.table_id = p_table_id
     AND s.left_at IS NULL
   ORDER BY s.id
   FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'live_seats_remain');
  END IF;

  IF v_table_status <> 'closed' OR v_current_players <> 0 THEN
    UPDATE public.tables
       SET status = 'closed',
           current_players = 0,
           updated_at = clock_timestamp()
     WHERE id = p_table_id
       AND tournament_id = p_tournament_id;
  END IF;

  SELECT lower(t.status::text), COALESCE(t.current_players, 0)
    INTO v_table_status, v_current_players
    FROM public.tables t
   WHERE t.id = p_table_id
     AND t.tournament_id = p_tournament_id;

  RETURN jsonb_build_object(
    'ok', v_table_status = 'closed' AND v_current_players = 0,
    'reason', CASE
      WHEN v_table_status = 'closed' AND v_current_players = 0 THEN 'closed'
      ELSE 'close_not_durable'
    END,
    'table_id', p_table_id,
    'tournament_id', p_tournament_id,
    'status', v_table_status,
    'current_players', v_current_players
  );
END;
$$;


ALTER FUNCTION public.fn_close_empty_tournament_table(p_tournament_id uuid, p_table_id uuid, p_lease_generation uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_close_empty_tournament_table(p_tournament_id uuid, p_table_id uuid, p_lease_generation uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_close_empty_tournament_table(p_tournament_id uuid, p_table_id uuid, p_lease_generation uuid) IS 'Exact protocol-2 tournament-manager table-break close. Locks the live generation, parent, table, and seats; refuses a non-empty table and returns a durable terminal receipt.';


--
-- Name: fn_close_managed_game(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_close_managed_game(p_kind text, p_game_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_club uuid;
  v_status text;
  v_cluster uuid;
  v_role text;
  v_cancel jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_kind = 'table' THEN
    SELECT club_id, status, cluster_id, role
      INTO v_club, v_status, v_cluster, v_role
      FROM public.tables
     WHERE id = p_game_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'game_not_found');
    END IF;
    IF NOT public.fn_can_create_games(v_club, v_uid) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
    END IF;
    IF lower(COALESCE(v_status, '')) IN ('closed', 'completed', 'cancelled', 'finished') THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'already_closed');
    END IF;

    PERFORM 1
      FROM public.table_seats ts
     WHERE ts.table_id = p_game_id
       AND ts.left_at IS NULL
     FOR UPDATE;
    IF FOUND THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'players_seated');
    END IF;

    UPDATE public.tables
       SET status = 'closed', current_players = 0, updated_at = now()
     WHERE id = p_game_id;

    IF v_cluster IS NOT NULL AND v_role = 'main' THEN
      UPDATE public.cash_games
         SET enabled = false,
             state = 'dormant',
             closed_at = now(),
             closed_by = v_uid,
             updated_at = now()
       WHERE id = v_cluster
         AND enabled;
    END IF;
    RETURN jsonb_build_object('ok', true);
  ELSIF p_kind = 'tournament' THEN
    -- This must precede the first tournament row lock. Every terminal owner
    -- takes the same lock, so managed cancellation cannot deadlock or race a
    -- finish, satellite closeout, unregister, or another cancellation.
    PERFORM pg_advisory_xact_lock(
      hashtextextended('ca:tournament-terminal-settlement:v1',0));

    SELECT club_id, status
      INTO v_club, v_status
      FROM public.tournaments
     WHERE id = p_game_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'game_not_found');
    END IF;
    IF NOT public.fn_can_create_games(v_club, v_uid) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
    END IF;
    IF upper(COALESCE(v_status, '')) IN ('COMPLETED', 'CANCELLED', 'CANCELED', 'COMPLETING') THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'already_closed');
    END IF;

    PERFORM 1
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_game_id
     FOR UPDATE;
    IF FOUND THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'players_registered');
    END IF;

    PERFORM set_config('app.managed_game_lifecycle', 'on', true);
    v_cancel := public.atomic_cancel_tournament(p_game_id, v_uid);
    PERFORM set_config('app.managed_game_lifecycle', '', true);
    IF v_cancel->>'ok' IS DISTINCT FROM 'true'
       OR v_cancel->>'fully_settled' IS DISTINCT FROM 'true'
       OR v_cancel->>'status' IS DISTINCT FROM 'CANCELLED'
       OR v_cancel->>'tournament_id' IS DISTINCT FROM p_game_id::text
       OR (v_cancel->>'source_player_count')::integer IS DISTINCT FROM 0 THEN
      RAISE EXCEPTION
        'managed tournament close did not return its exact atomic cancellation receipt'
        USING ERRCODE = 'P0404';
    END IF;
    RETURN jsonb_build_object('ok', true);
  END IF;

  RETURN jsonb_build_object('ok', false, 'reason', 'invalid_game_kind');
END;
$$;


ALTER FUNCTION public.fn_close_managed_game(p_kind text, p_game_id uuid) OWNER TO postgres;

--
-- Name: fn_close_settlement_period(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_close_settlement_period(p_period_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_period         record;
  v_rake_total     numeric;
  v_rate           numeric;
  v_payout         numeric;
  v_payout_id      uuid;
  v_days_needed    int;
  v_days_have      int;
  v_from_rollup    boolean := true;
  v_is_member      boolean;
  v_balance        numeric;
  v_debit          jsonb;
  v_treasury       numeric;
BEGIN
  SELECT * INTO v_period FROM public.rakeback_periods WHERE id = p_period_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'period not found');
  END IF;

  IF v_period.status IN ('paid', 'expired') THEN
    RETURN jsonb_build_object('success', true, 'skipped', v_period.status, 'period_id', p_period_id);
  END IF;

  -- WHO IS ASKING. A grant is not an authorization check: it lives outside
  -- the function and CREATE OR REPLACE carries it forward unexamined. This
  -- function debits a treasury and credits a wallet, so it asks.
  IF NOT public.fn_caller_is_engine()
     AND (auth.uid() IS NULL
          OR (auth.uid() <> v_period.user_id
              AND NOT public.fn_is_platform_admin()
              AND NOT EXISTS (SELECT 1 FROM public.clubs c
                               WHERE c.id = v_period.club_id
                                 AND c.owner_id = auth.uid()))) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorised');
  END IF;

  -- ---- EVERY CHEAP REFUSAL FIRST -------------------------------------------
  -- Each of these is one indexed lookup. The basis below is a rollup sum at
  -- best and a full rake_records scan at worst, and there is no reason to pay
  -- for it on a period that cannot be paid out either way.

  -- CLAUDE.md 13 rule 5: a sweep that moves money checks the freeze first.
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('success', false, 'deferred', 'platform_frozen',
                              'period_id', p_period_id);
  END IF;

  -- Rakeback is earned at a club and belongs in that club's wallet. A player
  -- with no membership there is not quietly paid somewhere else, and is not
  -- worth a rake scan to discover that.
  SELECT EXISTS (SELECT 1 FROM public.club_members cm
                  WHERE cm.user_id = v_period.user_id
                    AND cm.club_id = v_period.club_id
                    AND cm.status IN ('active','approved'))
    INTO v_is_member;

  IF NOT v_is_member THEN
    UPDATE public.rakeback_periods
       SET deferred_reason = 'no_membership_at_earning_club',
           deferred_at = NOW(), defer_count = defer_count + 1
     WHERE id = p_period_id;
    RETURN jsonb_build_object('success', false, 'deferred', 'no_membership_at_earning_club',
      'period_id', p_period_id, 'club_id', v_period.club_id, 'user_id', v_period.user_id);
  END IF;

  -- Can this club fund what this period is already believed to be worth? The
  -- estimate is the writer's own last computation, it is used ONLY to refuse,
  -- and refusing here costs one indexed row where continuing costs a full rake
  -- scan for a payment fn_debit_treasury would decline at the end of it.
  IF COALESCE(v_period.rakeback_amount, v_period.rakeback_earned, 0) > 0 THEN
    SELECT COALESCE(c.chip_treasury, 0) INTO v_treasury
      FROM public.clubs c WHERE c.id = v_period.club_id;
    IF v_treasury < COALESCE(v_period.rakeback_amount, v_period.rakeback_earned, 0) THEN
      UPDATE public.rakeback_periods
         SET deferred_reason = 'insufficient_club_treasury',
             deferred_at = NOW(), defer_count = defer_count + 1
       WHERE id = p_period_id;
      RETURN jsonb_build_object('success', false, 'deferred', 'insufficient_club_treasury',
        'period_id', p_period_id, 'club_id', v_period.club_id,
        'estimated_payout', COALESCE(v_period.rakeback_amount, v_period.rakeback_earned, 0),
        'treasury', round(v_treasury, 2), 'checked', 'before_basis');
    END IF;
  END IF;

  -- ---- NOW THE WORK ---------------------------------------------------------
  -- rakeback_daily_user is the same allocation the writer used, computed once
  -- per club-day for every player. Where it does not cover the period - it
  -- began 2026-08-31 and the backlog reaches to 2026-07-20 - fall back to the
  -- original scan rather than pay somebody zero because a cache is cold.
  v_days_needed := (v_period.period_end - v_period.period_start) + 1;
  SELECT count(*) INTO v_days_have FROM public.rakeback_daily_state s
   WHERE s.club_id = v_period.club_id
     AND s.day BETWEEN v_period.period_start AND v_period.period_end;

  IF v_days_have >= v_days_needed THEN
    SELECT ROUND(COALESCE(SUM(d.cents), 0)::numeric / 100, 2)
      INTO v_rake_total
      FROM public.rakeback_daily_user d
     WHERE d.club_id = v_period.club_id
       AND d.user_id = v_period.user_id
       AND d.day BETWEEN v_period.period_start AND v_period.period_end;
  ELSE
    v_from_rollup := false;
    SELECT ROUND(COALESCE(SUM(s.credit), 0), 2)
      INTO v_rake_total
      FROM public.rake_records r
      CROSS JOIN LATERAL public.fn_rake_shares_for_record(
        r.hand_id, r.rake_amount, r.player_contributions, COALESCE(r.rake_method, 'DEALT_EQUAL')
      ) s
     WHERE r.club_id = v_period.club_id
       AND r.created_at >= v_period.period_start::timestamptz
       AND r.created_at <  (v_period.period_end + 1)::timestamptz
       AND r.rake_amount > 0
       AND r.player_contributions IS NOT NULL
       AND (r.player_contributions ? v_period.user_id::text)
       AND NOT public.fn_rake_record_is_ghost_twin(r.hand_id, r.table_id, r.metadata)
       AND s.user_id = v_period.user_id;
  END IF;

  -- One source of truth for the rate: the player's own deal, else their agent's
  -- standing offer, else the legacy volume ladder, never more than the upline
  -- earns less ten points.
  v_rate   := public.fn_player_rakeback_rate(v_period.user_id, v_period.club_id, v_rake_total);
  v_payout := ROUND(v_rake_total * v_rate, 2);

  UPDATE public.rakeback_periods
     SET rake_generated  = v_rake_total,
         total_rake_paid = v_rake_total,
         rakeback_rate   = v_rate,
         rakeback_amount = v_payout,
         rakeback_earned = v_payout
   WHERE id = p_period_id;

  IF v_payout <= 0 THEN
    UPDATE public.rakeback_periods
       SET status = 'paid', paid_at = NOW(), deferred_reason = NULL, deferred_at = NULL
     WHERE id = p_period_id;
    RETURN jsonb_build_object('success', true, 'period_id', p_period_id, 'payout', 0,
                              'rake_total', v_rake_total, 'rakeback_rate', v_rate,
                              'from_rollup', v_from_rollup);
  END IF;

  INSERT INTO public.rakeback_period_payouts
    (rakeback_period_id, club_id, user_id, user_rake_contribution,
     rakeback_pct, payout_amount, status, paid_at)
  VALUES
    (p_period_id, v_period.club_id, v_period.user_id, v_rake_total,
     ROUND(v_rate * 100, 2), round(v_payout, 2), 'paid', NOW())
  ON CONFLICT (rakeback_period_id, user_id) DO NOTHING
  RETURNING id INTO v_payout_id;

  IF v_payout_id IS NULL THEN
    UPDATE public.rakeback_periods
       SET status = 'paid', paid_at = NOW(), deferred_reason = NULL, deferred_at = NULL
     WHERE id = p_period_id;
    RETURN jsonb_build_object('success', true, 'skipped', 'payout_exists', 'period_id', p_period_id);
  END IF;

  v_debit := public.fn_debit_treasury(
    v_period.club_id, v_payout,
    'Player rakeback ' || v_period.period_start::text || ' to ' || v_period.period_end::text,
    jsonb_build_object('period_id', p_period_id, 'user_id', v_period.user_id,
                       'rake_basis', v_rake_total, 'rate', v_rate));

  IF COALESCE((v_debit->>'success')::boolean, false) IS NOT TRUE THEN
    DELETE FROM public.rakeback_period_payouts WHERE id = v_payout_id;
    UPDATE public.rakeback_periods
       SET deferred_reason = 'insufficient_club_treasury',
           deferred_at = NOW(), defer_count = defer_count + 1
     WHERE id = p_period_id;
    RETURN jsonb_build_object('success', false, 'deferred', 'insufficient_club_treasury',
      'period_id', p_period_id, 'club_id', v_period.club_id, 'payout', v_payout,
      'treasury', v_debit->'balance');
  END IF;

  PERFORM set_config('app.ledger_club_id', v_period.club_id::text, true);

  PERFORM public.atomic_credit_wallet_and_log(
    v_period.user_id, v_payout, 'rakeback',
    'Rakeback payout ' || v_period.period_start::text || ' to ' || v_period.period_end::text,
    NULL, NULL, v_payout_id, 'rakeback:' || p_period_id::text
  );
  /* THE POINTER IS WRITTEN WHERE THE MONEY MOVED (2026-09-08). The credit
     above already stamps related_entity_id = this payout, so the link has
     always existed in ONE direction. rakeback_period_payouts.wallet_
     transaction_id was never written back, on any of 2,704 rows since the
     table was created, and fn_ca_settlement_correctness_check reads that
     direction - so every paid rakeback looked like money with no evidence.
     PERFORM discards what the credit returns and the function returns only
     a boolean, so the id is read back from the row it just stamped. */
  PERFORM set_config('app.ledger_maintenance',
                     'rakeback payout evidence pointer', true);
  UPDATE public.rakeback_period_payouts p
     SET wallet_transaction_id = w.id
    FROM public.wallet_transactions w
   WHERE p.id = v_payout_id AND w.related_entity_id = v_payout_id
     AND p.wallet_transaction_id IS NULL;
  PERFORM set_config('app.ledger_maintenance', '', true);

  PERFORM set_config('app.ledger_club_id', '', true);

  SELECT cm.chip_balance INTO v_balance
    FROM public.club_members cm
   WHERE cm.user_id = v_period.user_id AND cm.club_id = v_period.club_id;

  INSERT INTO public.wallet_transactions
    (user_id, wallet_type, amount, type, category, description, related_entity_id, balance_after)
  VALUES
    (v_period.user_id, 'PLAYER', v_payout, 'credit', 'rakeback',
     'Rakeback payout ' || v_period.period_start::text || ' to ' || v_period.period_end::text,
     v_payout_id, v_balance);

  UPDATE public.rakeback_periods
     SET status = 'paid', paid_at = NOW(), deferred_reason = NULL, deferred_at = NULL
   WHERE id = p_period_id;

  RETURN jsonb_build_object('success', true, 'period_id', p_period_id,
    'rake_total', v_rake_total, 'rakeback_rate', v_rate,
    'payout', v_payout, 'payout_id', v_payout_id, 'club_id', v_period.club_id,
    'from_rollup', v_from_rollup, 'funded_from', 'club_chip_treasury');
END;
$$;


ALTER FUNCTION public.fn_close_settlement_period(p_period_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_close_settlement_period(p_period_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_close_settlement_period(p_period_id uuid) IS 'Pays one rakeback period. Basis from the rakeback_daily_user rollup, falling back to a direct rake_records scan when the rollup does not cover the period. Rate from fn_player_rakeback_rate - the same policy the writer used, including the upline cap - never a hardcoded ladder. Credits the club the rake was earned at, refuses to pay a player who is not a member there, refuses to move money during a maintenance freeze, and records why on the period when it defers.';


--
-- Name: fn_close_tournament_addon_period(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_close_tournament_addon_period(p_tournament_id uuid, p_source text DEFAULT 'engine.addon_period_end'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_result jsonb;
BEGIN
  SELECT * INTO v_t
    FROM public.tournaments
   WHERE id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','not_found'); END IF;
  IF v_t.addon_period_started_at IS NULL OR v_t.addon_period_ends_at IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','addon_period_not_started');
  END IF;
  IF clock_timestamp()<v_t.addon_period_ends_at
     AND NOT COALESCE(v_t.prize_pool_finalized,false) THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','addon_period_open','ends_at',v_t.addon_period_ends_at);
  END IF;

  v_result := public.fn_finalize_tournament_entry_pool_locked(
    p_tournament_id,p_source,'addon');
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Add-on close could not fund/finalize its prize pool: %',
      COALESCE(v_result->>'reason','unknown') USING ERRCODE='55000';
  END IF;
  RETURN v_result || jsonb_build_object(
    'closed',true,'ends_at',v_t.addon_period_ends_at);
END;
$$;


ALTER FUNCTION public.fn_close_tournament_addon_period(p_tournament_id uuid, p_source text) OWNER TO postgres;

--
-- Name: fn_close_tournament_entry_window(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_close_tournament_entry_window(p_tournament_id uuid, p_source text DEFAULT 'engine.entry_window_close'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_deadline timestamptz;
  v_retry_ms bigint;
  v_mode text;
BEGIN
  SELECT * INTO v_t
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','not_found'); END IF;
  IF v_t.status<>'RUNNING' THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_not_running','status',v_t.status);
  END IF;

  IF COALESCE(v_t.late_reg_levels,v_t.rebuy_levels,0)>0 THEN
    v_mode := 'levels';
    IF COALESCE(v_t.current_level,0)<COALESCE(v_t.late_reg_levels,v_t.rebuy_levels,0)
       AND NOT COALESCE(v_t.prize_pool_finalized,false) THEN
      RETURN jsonb_build_object(
        'ok',true,'entry_closed',false,'window_mode',v_mode,
        'retry_after_ms',NULL);
    END IF;
  ELSIF COALESCE(v_t.late_reg_mins,0)>0 THEN
    v_mode := 'minutes';
    IF v_t.started_at IS NULL THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','started_at_required_for_minutes_window',
        'window_mode',v_mode);
    END IF;
    v_deadline := v_t.started_at+make_interval(mins=>v_t.late_reg_mins);
    IF clock_timestamp()<v_deadline
       AND NOT COALESCE(v_t.prize_pool_finalized,false) THEN
      v_retry_ms := GREATEST(
        ceil(extract(epoch FROM (v_deadline-clock_timestamp()))*1000),0)::bigint;
      RETURN jsonb_build_object(
        'ok',true,'entry_closed',false,'window_mode',v_mode,
        'retry_after_ms',v_retry_ms);
    END IF;
  ELSE
    v_mode := 'immediate';
  END IF;

  -- Add-on chips can still change the final pool. Close entry now, but let the
  -- persisted add-on deadline own finalization and its receipt.
  IF COALESCE(v_t.add_on_available,false)
     AND NOT COALESCE(v_t.prize_pool_finalized,false) THEN
    RETURN jsonb_build_object(
      'ok',true,'entry_closed',true,'window_mode',v_mode,
      'finalized',false,'finalization_deferred',true,
      'reason','addon_required','retry_after_ms',NULL);
  END IF;

  RETURN public.fn_finalize_tournament_entry_pool_locked(
    p_tournament_id,p_source,v_mode);
END;
$$;


ALTER FUNCTION public.fn_close_tournament_entry_window(p_tournament_id uuid, p_source text) OWNER TO postgres;

--
-- Name: fn_closed_cluster_main_releases_index(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_closed_cluster_main_releases_index() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.cluster_id IS NOT NULL
     AND NEW.main_index IS NOT NULL
     AND (NEW.lifecycle = 'closed' OR coalesce(NEW.is_deleted, false) = true)
  THEN
    NEW.main_index := NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_closed_cluster_main_releases_index() OWNER TO postgres;

--
-- Name: fn_club_ad_cancel(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_ad_cancel(p_campaign_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_c    public.ad_campaign%rowtype;
  v_ref  jsonb;
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_signed_in'); END IF;
  SELECT * INTO v_c FROM public.ad_campaign WHERE id = p_campaign_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;
  IF NOT public.fn_club_is_staff(v_c.club_id, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_club_staff');
  END IF;
  IF v_c.status <> 'submitted' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_cancellable', 'status', v_c.status);
  END IF;
  v_ref := public.add_diamonds_to_balance(
    v_c.submitted_by, v_c.diamonds_charged, 'refund',
    'Club advert cancelled: ' || v_c.name,
    'adcamp-refund:' || v_c.id::text
  );
  IF COALESCE((v_ref->>'success')::boolean, false) IS NOT TRUE
     AND COALESCE((v_ref->>'duplicate')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'refund failed: %', v_ref->>'error';
  END IF;
  UPDATE public.ad_campaign
     SET status = 'cancelled', diamonds_refunded = diamonds_charged,
         reviewed_at = now(), updated_at = now()
   WHERE id = p_campaign_id;
  RETURN jsonb_build_object('ok', true, 'diamonds_refunded', v_c.diamonds_charged);
END;
$$;


ALTER FUNCTION public.fn_club_ad_cancel(p_campaign_id uuid) OWNER TO postgres;

--
-- Name: fn_club_ad_submit(uuid, text, text, text, text, timestamp with time zone, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_ad_submit(p_club_id uuid, p_slot text, p_headline text, p_image_url text, p_target_url text, p_starts_at timestamp with time zone, p_days integer, p_scope text DEFAULT 'platform'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user   uuid := auth.uid();
  v_rate   public.ad_rate_card%rowtype;
  v_club   record;
  v_adv    uuid;
  v_id     uuid := gen_random_uuid();
  v_cost   integer;
  v_start  timestamptz;
  v_end    timestamptz;
  v_debit  jsonb;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_signed_in');
  END IF;
  IF NOT public.fn_club_is_staff(p_club_id, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_club_staff');
  END IF;
  SELECT * INTO v_rate FROM public.ad_rate_card WHERE slot = p_slot;
  IF NOT FOUND OR NOT v_rate.is_open THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'surface_not_open');
  END IF;
  IF p_days IS NULL OR p_days < v_rate.min_days OR p_days > v_rate.max_days THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'days_out_of_range',
                              'min_days', v_rate.min_days, 'max_days', v_rate.max_days);
  END IF;
  IF p_scope NOT IN ('platform', 'own_club') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bad_scope');
  END IF;
  IF p_image_url IS NULL
     OR p_image_url NOT LIKE ('/ad-creatives/club/' || p_club_id::text || '/%') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'creative_not_in_club_folder');
  END IF;
  IF p_target_url IS NULL OR p_target_url NOT LIKE '/%'
     OR p_target_url LIKE '//%' OR position('\' in p_target_url) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bad_destination');
  END IF;
  IF p_headline IS NULL OR length(btrim(p_headline)) NOT BETWEEN 1 AND 120 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bad_headline');
  END IF;
  v_start := GREATEST(COALESCE(p_starts_at, now()), now() - interval '10 minutes');
  v_end   := v_start + make_interval(days => p_days);
  v_cost  := v_rate.diamonds_per_day * p_days;
  SELECT id, name INTO v_club FROM public.clubs WHERE id = p_club_id;
  INSERT INTO public.ad_advertiser (kind, name, club_id, owner_user_id)
  VALUES ('club', left(v_club.name, 80), p_club_id, v_user)
  ON CONFLICT (club_id) WHERE club_id IS NOT NULL
  DO UPDATE SET name = excluded.name, updated_at = now()
  RETURNING id INTO v_adv;
  INSERT INTO public.ad_campaign
    (id, advertiser_id, club_id, name, slot, status, scope, priority,
     starts_at, ends_at, days, image_url, target_url, headline,
     diamonds_charged, submitted_by)
  VALUES
    (v_id, v_adv, p_club_id, left(btrim(p_headline), 80), p_slot, 'submitted', p_scope, 75,
     v_start, v_end, p_days, p_image_url, p_target_url, btrim(p_headline),
     v_cost, v_user);
  v_debit := public.deduct_diamonds(
    v_user, v_cost,
    'Club advert: ' || v_rate.label || ' x ' || p_days || ' day(s)',
    'ad_purchase', 'club_ads',
    jsonb_build_object('campaign_id', v_id, 'club_id', p_club_id, 'slot', p_slot, 'days', p_days),
    'adcamp:' || v_id::text,
    0
  );
  IF COALESCE((v_debit->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'AD_DEBIT_FAILED:%', COALESCE(v_debit->>'error', 'unknown')
      USING ERRCODE = 'P0001';
  END IF;
  RETURN jsonb_build_object(
    'ok', true, 'campaign_id', v_id, 'diamonds_charged', v_cost,
    'balance', v_debit->'balance', 'starts_at', v_start, 'ends_at', v_end
  );
EXCEPTION
  WHEN OTHERS THEN
    IF SQLERRM LIKE 'AD_DEBIT_FAILED:%' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'debit_failed',
                                'detail', substr(SQLERRM, 17));
    END IF;
    RAISE;
END;
$$;


ALTER FUNCTION public.fn_club_ad_submit(p_club_id uuid, p_slot text, p_headline text, p_image_url text, p_target_url text, p_starts_at timestamp with time zone, p_days integer, p_scope text) OWNER TO postgres;

--
-- Name: fn_club_anti_cheat_flags(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_anti_cheat_flags(p_club_id uuid, p_status text DEFAULT 'open'::text, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, player_id uuid, club_id uuid, table_id uuid, flag_type text, reason text, severity text, status text, reviewed_by uuid, reviewed_at timestamp with time zone, review_notes text, flagged_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT fn_ca_can_review_integrity(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT f.id, f.player_id, f.club_id, f.table_id, f.flag_type, f.reason, f.severity,
         f.status, f.reviewed_by, f.reviewed_at, f.review_notes, f.flagged_at, f.created_at
    FROM anti_cheat_flags f
   WHERE (
           f.club_id = p_club_id
           OR (f.club_id IS NULL AND EXISTS (
                 SELECT 1 FROM club_members cm
                  WHERE cm.club_id = p_club_id AND cm.user_id = f.player_id))
         )
     AND (p_status IS NULL OR p_status = 'all' OR coalesce(f.status, 'open') = p_status)
   ORDER BY coalesce(f.flagged_at, f.created_at) DESC
   LIMIT greatest(1, least(coalesce(p_limit, 50), 200));
END;
$$;


ALTER FUNCTION public.fn_club_anti_cheat_flags(p_club_id uuid, p_status text, p_limit integer) OWNER TO postgres;

--
-- Name: fn_club_arena_global_wallet_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_arena_global_wallet_check() RETURNS TABLE(fn text, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.proname::text,
         'Club Arena money path references the global wallets table - every club '
         || 'must be its own standalone wallet, never joined or pooled'
    FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname='public'
     AND p.proname IN (
       'atomic_table_buyin','atomic_table_cashout','atomic_table_rebuy','atomic_table_addon',
       'atomic_tournament_register','process_tournament_rebuy',
       'atomic_cancel_tournament','fn_pay_player_chips',
       'atomic_pay_player_rakeback','credit_player_rakeback')
       -- atomic_pay_agent_settlement was here until phase 7 dropped it.
     AND p.prosrc ~* '(update|insert into|from)\s+(public\.)?wallets\M';
$$;


ALTER FUNCTION public.fn_club_arena_global_wallet_check() OWNER TO postgres;

--
-- Name: fn_club_bank_claim_back(uuid, uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_bank_claim_back(p_club_id uuid, p_from_user_id uuid, p_amount numeric, p_source text DEFAULT 'agent_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor        uuid := auth.uid();
  v_actor_role   text;
  v_source       text := lower(coalesce(p_source, 'agent_wallet'));
  v_op_id        uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior        record;
  v_holder_role  text;
  v_held         numeric;
  v_agent_id     uuid;
  v_holder_after numeric;
  v_bank_after   numeric;
  v_tx_id        uuid;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null or v_actor_role not in ('owner', 'co_owner', 'admin', 'super_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only An Owner, Co Owner, Admin Or Super Agent May Claim Chips Back Into The Club Bank');
  end if;

  select id, amount, metadata into v_prior
    from chip_transactions
   where club_id = p_club_id
     and transaction_type = 'club_bank_claim'
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'source', v_prior.metadata ->> 'source',
      'bank_after', (v_prior.metadata ->> 'bank_after')::numeric,
      'holder_balance_after', (v_prior.metadata ->> 'holder_balance_after')::numeric);
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Claim Limit');
  end if;
  if v_source not in ('agent_wallet', 'promo_wallet', 'player_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Source Wallet');
  end if;
  if p_from_user_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose Whose Wallet To Claim From');
  end if;

  if p_from_user_id <> v_actor
     and not public.fn_club_cashier_can_transact(p_club_id, v_actor, p_from_user_id) then
    return jsonb_build_object('success', false,
      'error', 'That Member Is Not In Your Downline');
  end if;

  select cm.role into v_holder_role
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = p_from_user_id
     and coalesce(cm.status, 'active') in ('active', 'approved')
   for update;
  if v_holder_role is null then
    return jsonb_build_object('success', false, 'error', 'That Person Is Not An Active Member Of This Club');
  end if;

  if v_source = 'player_wallet' then
    select coalesce(chip_balance, 0) into v_held
      from club_members
     where club_id = p_club_id and user_id = p_from_user_id
     for update;
  else
    if v_holder_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
      return jsonb_build_object('success', false,
        'error', 'Only Staff Or Agents Hold An Agent Wallet');
    end if;
    select a.id, coalesce(case when v_source = 'promo_wallet'
                               then a.promo_wallet_balance
                               else a.agent_wallet_balance end, 0)
      into v_agent_id, v_held
      from agents a
     where a.club_id = p_club_id and a.user_id = p_from_user_id
     for update;
    if v_agent_id is null then
      return jsonb_build_object('success', false,
        'error', 'That Member Has Never Been Funded, So There Is Nothing To Claim');
    end if;
  end if;

  if v_held < p_amount then
    return jsonb_build_object('success', false,
      'error', 'That Wallet Only Holds ' || trim(to_char(v_held, 'FM999,999,999,990.00')) || ' Chips',
      'held', v_held, 'requested', p_amount);
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): ONE row from the wallet claimed to the
  -- club bank, keyed and correlated on the op. The clubs trigger is skipped;
  -- the holder's wallet trigger writes the row with the bank as counterparty.
  perform public.fn_ca_declare_ledger('club_bank_claim', 'club_treasury', p_club_id, null,
    'club_bank_claim:' || v_op_id::text, array['clubs']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  if v_source = 'player_wallet' then
    update club_members
       set chip_balance = coalesce(chip_balance, 0) - p_amount,
           updated_at = now()
     where club_id = p_club_id and user_id = p_from_user_id
     returning chip_balance into v_holder_after;
  elsif v_source = 'promo_wallet' then
    update agents
       set promo_wallet_balance = coalesce(promo_wallet_balance, 0) - p_amount,
           updated_at = now()
     where id = v_agent_id
     returning promo_wallet_balance into v_holder_after;
  else
    update agents
       set agent_wallet_balance = coalesce(agent_wallet_balance, 0) - p_amount,
           updated_at = now()
     where id = v_agent_id
     returning agent_wallet_balance into v_holder_after;
  end if;

  update clubs
     set chip_treasury = coalesce(chip_treasury, 0) + p_amount,
         updated_at = now()
   where id = p_club_id
   returning chip_treasury into v_bank_after;
  if v_bank_after is null then
    raise exception 'club % not found while crediting the bank', p_club_id;
  end if;
  perform set_config('app.ledger_autoskip_clubs', '', true);

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (p_club_id, p_from_user_id, v_actor, p_amount, 'club_bank_claim',
     coalesce(nullif(btrim(p_reason), ''), 'Club Bank Claim Back'),
     jsonb_build_object(
       'op_id', v_op_id,
       'source', v_source,
       'direction', 'into_bank',
       'actor_role', v_actor_role,
       'holder_role', v_holder_role,
       'bank_after', v_bank_after,
       'holder_balance_after', v_holder_after),
     v_bank_after)
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true, 'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', p_amount,
    'source', v_source,
    'bank_after', v_bank_after,
    'holder_balance_after', v_holder_after);
exception
  when unique_violation then
    select id, amount, metadata into v_prior
      from chip_transactions
     where club_id = p_club_id
       and transaction_type = 'club_bank_claim'
       and metadata ->> 'op_id' = v_op_id::text
     limit 1;
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'source', v_prior.metadata ->> 'source',
      'bank_after', (v_prior.metadata ->> 'bank_after')::numeric,
      'holder_balance_after', (v_prior.metadata ->> 'holder_balance_after')::numeric);
end
$$;


ALTER FUNCTION public.fn_club_bank_claim_back(p_club_id uuid, p_from_user_id uuid, p_amount numeric, p_source text, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_club_bank_ledger(uuid, integer, integer, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_bank_ledger(p_club_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_types text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_offset int := greatest(coalesce(p_offset, 0), 0);
  v_total bigint;
  v_rows jsonb;
  v_types jsonb;
  v_in numeric;
  v_out numeric;
begin
  if not public.fn_can_use_club_bank(p_club_id) then
    return jsonb_build_object('authorized', false,
      'error', 'The Club Bank Ledger Is Restricted To Owners, Co Owners, Admins And Super Agents');
  end if;

  select count(*) into v_total
    from chip_transactions t
   where t.club_id = p_club_id
     and (p_types is null or t.transaction_type = any (p_types));

  -- Every type this club has ever recorded, so the filter offers real options
  -- rather than a hard-coded list that goes stale.
  select coalesce(jsonb_agg(x.transaction_type order by x.transaction_type), '[]'::jsonb)
    into v_types
    from (select distinct transaction_type from chip_transactions where club_id = p_club_id) x;

  -- What went INTO the bank and what came OUT of it. Scoped to the movements
  -- the bank itself makes; a peer transfer between two members never touches
  -- clubs.chip_treasury and would make this figure a lie.
  select
    coalesce(sum(t.amount) filter (
      where t.transaction_type in ('mint', 'club_bank_reversal', 'treasury_credit', 'club_bank_claim')), 0),
    coalesce(sum(t.amount) filter (
      where t.transaction_type in ('club_bank_send', 'treasury_debit')
        and coalesce(t.is_reversed, false) = false), 0)
    into v_in, v_out
    from chip_transactions t
   where t.club_id = p_club_id;

  select coalesce(jsonb_agg(r order by r->>'created_at' desc), '[]'::jsonb) into v_rows
  from (
    select jsonb_build_object(
             'id', t.id,
             'created_at', t.created_at,
             'amount', round(coalesce(t.amount, 0), 2),
             'transaction_type', t.transaction_type,
             'notes', t.notes,
             'balance_after', t.balance_after,
             'metadata', coalesce(t.metadata, '{}'::jsonb),
             'is_reversed', coalesce(t.is_reversed, false),
             'reversible',
               t.transaction_type = 'club_bank_send'
               and coalesce(t.is_reversed, false) = false
               and (t.reversible_until is null or now() <= t.reversible_until),
             'from_user_id', t.from_user_id,
             'to_user_id', t.to_user_id,
             'from_name', coalesce(public.fn_arena_name(pf.alias, pf.username, pf.display_name, pf.first_name, pf.last_name, pf.full_name), pf.username, pf.full_name),
             'to_name', coalesce(public.fn_arena_name(pt.alias, pt.username, pt.display_name, pt.first_name, pt.last_name, pt.full_name), pt.username, pt.full_name)
           ) as r
      from chip_transactions t
      left join profiles pf on pf.id = t.from_user_id
      left join profiles pt on pt.id = t.to_user_id
     where t.club_id = p_club_id
       and (p_types is null or t.transaction_type = any (p_types))
     order by t.created_at desc
     limit v_limit offset v_offset
  ) s;

  return jsonb_build_object(
    'authorized', true,
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'types', v_types,
    'totals', jsonb_build_object('into_bank', round(v_in, 2), 'out_of_bank', round(v_out, 2),
                                 'net', round(v_in - v_out, 2)),
    'rows', v_rows);
end
$$;


ALTER FUNCTION public.fn_club_bank_ledger(p_club_id uuid, p_limit integer, p_offset integer, p_types text[]) OWNER TO postgres;

--
-- Name: fn_club_bank_reverse(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_bank_reverse(p_transaction_id uuid, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor      uuid := auth.uid();
  v_actor_role text;
  v_op_id      uuid := coalesce(p_op_id, gen_random_uuid());
  v_tx         record;
  v_dest       text;
  v_held       numeric;
  v_agent_id   uuid;
  v_bank_after numeric;
  v_to_after   numeric;
  v_new_id     uuid;
  v_prior      record;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  select id, club_id, from_user_id, to_user_id, amount, transaction_type,
         coalesce(metadata, '{}'::jsonb) as metadata,
         coalesce(is_reversed, false) as is_reversed, reversible_until
    into v_tx
    from chip_transactions
   where id = p_transaction_id
   for update;
  if v_tx.id is null then
    return jsonb_build_object('success', false, 'error', 'That Ledger Entry Was Not Found');
  end if;

  v_actor_role := public.fn_club_bank_role(v_tx.club_id);
  if v_actor_role is null or v_actor_role not in ('owner', 'co_owner', 'admin', 'super_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only An Owner, Co Owner, Admin Or Super Agent May Reverse A Club Bank Send');
  end if;

  select id into v_prior from chip_transactions
   where club_id = v_tx.club_id
     and transaction_type = 'club_bank_reversal'
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object('success', true, 'replayed', true, 'transaction_id', v_prior.id);
  end if;

  if v_tx.transaction_type <> 'club_bank_send' then
    return jsonb_build_object('success', false,
      'error', 'Only A Club Bank Send Can Be Reversed Here');
  end if;
  if v_tx.is_reversed then
    return jsonb_build_object('success', false, 'error', 'That Send Has Already Been Reversed');
  end if;
  if v_tx.reversible_until is not null and now() > v_tx.reversible_until then
    return jsonb_build_object('success', false,
      'error', 'That Send Is Outside Its Seven Day Reversal Window');
  end if;

  v_dest := coalesce(v_tx.metadata ->> 'destination', 'agent_wallet');

  -- Take the chips back only if they are still there.
  if v_dest = 'player_wallet' then
    select coalesce(chip_balance, 0) into v_held
      from club_members
     where club_id = v_tx.club_id and user_id = v_tx.to_user_id
     for update;
  else
    select a.id, coalesce(case when v_dest = 'promo_wallet'
                               then a.promo_wallet_balance
                               else a.agent_wallet_balance end, 0)
      into v_agent_id, v_held
      from agents a
     where a.club_id = v_tx.club_id and a.user_id = v_tx.to_user_id
     for update;
  end if;

  if v_held is null then
    return jsonb_build_object('success', false, 'error', 'That Wallet No Longer Exists');
  end if;
  if v_held < v_tx.amount then
    return jsonb_build_object('success', false,
      'error', 'Those Chips Have Already Been Spent, So The Send Cannot Be Reversed',
      'held', v_held, 'required', v_tx.amount);
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): ONE `reversal` row from the wallet that
  -- received the send back to the club bank, keyed and correlated on the op.
  -- The clubs trigger is skipped; the recipient's wallet trigger writes it.
  perform public.fn_ca_declare_ledger('reversal', 'club_treasury', v_tx.club_id, null,
    'club_bank_reversal:' || v_op_id::text, array['clubs']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  if v_dest = 'player_wallet' then
    update club_members set chip_balance = chip_balance - v_tx.amount, updated_at = now()
     where club_id = v_tx.club_id and user_id = v_tx.to_user_id
     returning chip_balance into v_to_after;
  elsif v_dest = 'promo_wallet' then
    update agents set promo_wallet_balance = promo_wallet_balance - v_tx.amount, updated_at = now()
     where id = v_agent_id returning promo_wallet_balance into v_to_after;
  else
    update agents set agent_wallet_balance = agent_wallet_balance - v_tx.amount, updated_at = now()
     where id = v_agent_id returning agent_wallet_balance into v_to_after;
  end if;

  update clubs set chip_treasury = coalesce(chip_treasury, 0) + v_tx.amount, updated_at = now()
   where id = v_tx.club_id returning chip_treasury into v_bank_after;
  perform set_config('app.ledger_autoskip_clubs', '', true);

  update chip_transactions
     set is_reversed = true, clawed_back = true
   where id = v_tx.id;

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (v_tx.club_id, v_tx.to_user_id, v_tx.from_user_id, v_tx.amount, 'club_bank_reversal',
     coalesce(nullif(btrim(p_reason), ''), 'Club Bank Send Reversed'),
     jsonb_build_object(
       'op_id', v_op_id,
       'reverses', v_tx.id,
       'destination', v_dest,
       'actor_role', v_actor_role,
       'bank_after', v_bank_after,
       'recipient_balance_after', v_to_after),
     v_bank_after)
  returning id into v_new_id;

  return jsonb_build_object(
    'success', true, 'replayed', false,
    'transaction_id', v_new_id, 'reversed', v_tx.id,
    'amount', v_tx.amount, 'bank_after', v_bank_after,
    'recipient_balance_after', v_to_after);
end
$$;


ALTER FUNCTION public.fn_club_bank_reverse(p_transaction_id uuid, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_club_bank_role(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_bank_role(p_club_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_club_id is null then null
    when exists (select 1 from public.clubs c
                  where c.id = p_club_id
                    and c.owner_id = coalesce(p_user_id, auth.uid())) then 'owner'
    else (select cm.role from public.club_members cm
           where cm.club_id = p_club_id
             and cm.user_id = coalesce(p_user_id, auth.uid())
             and coalesce(cm.status, 'active') in ('active', 'approved')
           limit 1)
  end;
$$;


ALTER FUNCTION public.fn_club_bank_role(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_club_bank_send(uuid, uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_bank_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text DEFAULT 'agent_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor        uuid := auth.uid();
  v_actor_role   text;
  v_dest         text := lower(coalesce(p_destination, 'agent_wallet'));
  v_op_id        uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior        record;
  v_bank_before  numeric;
  v_bank_after   numeric;
  v_to_role      text;
  v_to_after     numeric;
  v_agent_id     uuid;
  v_tx_id        uuid;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null or v_actor_role not in ('owner', 'co_owner', 'admin', 'super_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only An Owner, Co Owner, Admin Or Super Agent May Send From The Club Bank');
  end if;

  select id, amount, metadata into v_prior
    from chip_transactions
   where club_id = p_club_id
     and transaction_type = 'club_bank_send'
     and from_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'bank_after', (v_prior.metadata ->> 'bank_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric);
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false,
      'error', 'Chips Move In Hundredths At Most');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Send Limit');
  end if;
  if v_dest not in ('agent_wallet', 'promo_wallet', 'player_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Destination Wallet');
  end if;
  if p_to_user_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose A Recipient');
  end if;

  select cm.role into v_to_role
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = p_to_user_id
     and coalesce(cm.status, 'active') in ('active', 'approved')
   for update;
  if v_to_role is null then
    return jsonb_build_object('success', false, 'error', 'Recipient Is Not An Active Member Of This Club');
  end if;
  if v_dest in ('agent_wallet', 'promo_wallet')
     and v_to_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only Staff Or Agents Hold An Agent Wallet');
  end if;
  -- Dan 2026-09-02: "ALL CLUB OWNERS AND CO-OWNERS SHOULD HAVE A PLAYER
  -- WALLET (ADMIN'S SHOULD NOT)". A player-wallet credit to an admin lands in
  -- a balance no surface shows them, so it is refused here rather than
  -- stranded.
  if v_dest = 'player_wallet' and v_to_role = 'admin' then
    return jsonb_build_object('success', false,
      'error', 'An Admin Does Not Hold A Player Wallet');
  end if;

  if p_to_user_id <> v_actor
     and not public.fn_club_cashier_can_transact(p_club_id, v_actor, p_to_user_id) then
    return jsonb_build_object('success', false,
      'error', 'That Member Is Not In Your Downline');
  end if;

  select coalesce(c.chip_treasury, 0) into v_bank_before
    from clubs c where c.id = p_club_id for update;
  if v_bank_before is null then
    return jsonb_build_object('success', false, 'error', 'Club Not Found');
  end if;
  if v_bank_before < p_amount then
    return jsonb_build_object('success', false, 'error', 'Insufficient Club Bank Balance',
      'balance', v_bank_before, 'requested', p_amount);
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): a club bank send is ONE journal row from
  -- the bank to the wallet that receives it. Undeclared, the two balance
  -- writes landed as `adjustment club_treasury -> settlement_suspense` plus
  -- `adjustment settlement_suspense -> agent_wallet` (or `table_stack ->
  -- player_wallet`), unkeyed and uncorrelated (3,750,000.00 on 2026-09-01
  -- 14:02:19 journaled exactly so). The clubs trigger is skipped for this
  -- write; the receiving wallet's trigger writes the row with the bank as its
  -- counterparty, keyed and correlated on the op. Never a refusal: a journal
  -- miss falls back inside the trigger, the money moves as before.
  perform public.fn_ca_declare_ledger('club_bank_send', 'club_treasury', p_club_id, null,
    'club_bank_send:' || v_op_id::text, array['clubs']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  update clubs
     set chip_treasury = coalesce(chip_treasury, 0) - p_amount,
         updated_at = now()
   where id = p_club_id
   returning chip_treasury into v_bank_after;

  if v_dest = 'player_wallet' then
    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount,
           updated_at = now()
     where club_id = p_club_id and user_id = p_to_user_id
     returning chip_balance into v_to_after;
  else
    v_agent_id := public.fn_ensure_agent_row(p_club_id, p_to_user_id, v_to_role);
    if v_agent_id is null then
      raise exception 'could not ensure agents row for % in club %', p_to_user_id, p_club_id;
    end if;

    if v_dest = 'agent_wallet' then
      update agents
         set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + p_amount,
             updated_at = now()
       where id = v_agent_id
       returning agent_wallet_balance into v_to_after;
    else
      update agents
         set promo_wallet_balance = coalesce(promo_wallet_balance, 0) + p_amount,
             updated_at = now()
       where id = v_agent_id
       returning promo_wallet_balance into v_to_after;
    end if;
  end if;
  perform set_config('app.ledger_autoskip_clubs', '', true);

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata,
     balance_after, reversible_until)
  values
    (p_club_id, v_actor, p_to_user_id, p_amount, 'club_bank_send',
     coalesce(nullif(btrim(p_reason), ''), 'Club Bank Send'),
     jsonb_build_object(
       'op_id', v_op_id,
       'destination', v_dest,
       'actor_role', v_actor_role,
       'recipient_role', v_to_role,
       'bank_before', v_bank_before,
       'bank_after', v_bank_after,
       'recipient_balance_after', v_to_after),
     v_bank_after, now() + interval '7 days')
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true,
    'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', p_amount,
    'destination', v_dest,
    'bank_before', v_bank_before,
    'bank_after', v_bank_after,
    'recipient_balance_after', v_to_after);
exception
  when unique_violation then
    select id, amount, metadata into v_prior
      from chip_transactions
     where club_id = p_club_id
       and transaction_type = 'club_bank_send'
       and from_user_id = v_actor
       and metadata ->> 'op_id' = v_op_id::text
     limit 1;
    if v_prior.id is null then
      raise;
    end if;
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'bank_after', (v_prior.metadata ->> 'bank_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric);
end
$$;


ALTER FUNCTION public.fn_club_bank_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_club_bomb_pot_report(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_bomb_pot_report(p_club_id uuid, p_days integer DEFAULT 30) RETURNS TABLE(table_id uuid, table_name text, trigger_reason text, board_count integer, variant text, hands bigint, avg_players numeric, avg_pot numeric, total_pot numeric, total_rake numeric, total_antes numeric, scoops bigint, splits bigint, unrecorded_hands bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid        uuid    := auth.uid();
  v_authorized boolean := false;
  v_days       integer := LEAST(GREATEST(COALESCE(p_days, 30), 1), 365);
  v_from       date;
  v_live_from  date;
  v_oldest     date;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT
    EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = p_club_id AND c.owner_id = v_uid)
    OR EXISTS (
      SELECT 1 FROM public.club_members cm
      WHERE cm.club_id = p_club_id AND cm.user_id = v_uid
        AND lower(cm.role) IN ('owner', 'co_owner', 'admin')
    )
  INTO v_authorized;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM public.fn_ca_bomb_pot_catchup(p_club_id, v_days);

  v_from := (now() - make_interval(days => v_days))::date;

  SELECT MIN(g)::date INTO v_live_from
    FROM generate_series(v_from, (now() AT TIME ZONE 'UTC')::date, interval '1 day') g
   WHERE NOT EXISTS (SELECT 1 FROM public.ca_club_bomb_pot_complete c
                      WHERE c.club_id = p_club_id AND c.day = g::date);
  v_live_from := COALESCE(v_live_from, (now() AT TIME ZONE 'UTC')::date);

  -- THE FLOOR THIS MIGRATION ADDS. An unsealed day older than the oldest
  -- surviving bomb pot hand holds nothing to find, and the catchup will never
  -- seal it because sealing a pruned day would write zeroes over real history.
  -- Without this, a thirty-day window scanned a month of hand_history to
  -- discover that twenty-three of those days were empty.
  SELECT MIN(h.created_at)::date INTO v_oldest
    FROM public.hand_history h
   WHERE h.bomb_pot IS NOT NULL;
  IF v_oldest IS NULL THEN
    v_live_from := (now() AT TIME ZONE 'UTC')::date;
  ELSIF v_oldest > v_live_from THEN
    v_live_from := v_oldest;
  END IF;

  RETURN QUERY
  WITH ok_days AS MATERIALIZED (
    SELECT c.day FROM public.ca_club_bomb_pot_complete c
     WHERE c.club_id = p_club_id AND c.day >= v_from
  ), from_rollup AS (
    SELECT d.table_id, d.trigger_reason, d.board_count, d.variant,
           d.hands, d.seats_sum, d.pot_sum, d.rake_sum, d.ante_sum,
           d.scoops, d.splits, d.unrecorded
      FROM public.ca_club_bomb_pot_daily d
      JOIN ok_days o ON o.day = d.day
     WHERE d.club_id = p_club_id
  ), from_live AS (
    SELECT b.table_id, b.trigger_reason, b.board_count, b.variant,
           count(*)::bigint                                          AS hands,
           SUM(b.seats)::numeric                                     AS seats_sum,
           SUM(b.pot_size)                                           AS pot_sum,
           SUM(b.rake_amount)                                        AS rake_sum,
           SUM(b.ante_amount * b.seats)                              AS ante_sum,
           count(*) FILTER (WHERE u.distinct_winners = 1)::bigint    AS scoops,
           count(*) FILTER (WHERE u.distinct_winners > 1)::bigint    AS splits,
           count(*) FILTER (WHERE u.hand_history_id IS NULL)::bigint AS unrecorded
      FROM (
        SELECT h.id, h.table_id,
               h.bomb_pot ->> 'trigger_reason'                      AS trigger_reason,
               (h.bomb_pot ->> 'board_count')::int                  AS board_count,
               h.bomb_pot ->> 'variant'                             AS variant,
               COALESCE((h.bomb_pot ->> 'ante_amount')::numeric, 0) AS ante_amount,
               COALESCE(h.pot_size, 0)                              AS pot_size,
               COALESCE(h.rake_amount, 0)                           AS rake_amount,
               COALESCE(jsonb_array_length(h.players), 0)           AS seats
          FROM public.hand_history h
          JOIN public.tables t ON t.id = h.table_id
         WHERE t.club_id = p_club_id
           AND h.bomb_pot IS NOT NULL
           AND h.created_at >= v_live_from::timestamptz
           AND NOT EXISTS (SELECT 1 FROM ok_days o2
                            WHERE o2.day = (h.created_at AT TIME ZONE 'UTC')::date)
      ) b
      LEFT JOIN (
        SELECT a.hand_history_id, count(DISTINCT a.user_id) AS distinct_winners
          FROM public.bomb_pot_award_units a
         WHERE a.created_at >= v_live_from::timestamptz
         GROUP BY a.hand_history_id
      ) u ON u.hand_history_id = b.id
     GROUP BY b.table_id, b.trigger_reason, b.board_count, b.variant
  ), merged AS (
    SELECT * FROM from_rollup
    UNION ALL
    SELECT * FROM from_live
  ), totalled AS (
    SELECT m.table_id, m.trigger_reason, m.board_count, m.variant,
           SUM(m.hands)::bigint      AS hands,
           SUM(m.seats_sum)          AS seats_sum,
           SUM(m.pot_sum)            AS pot_sum,
           SUM(m.rake_sum)           AS rake_sum,
           SUM(m.ante_sum)           AS ante_sum,
           SUM(m.scoops)::bigint     AS scoops,
           SUM(m.splits)::bigint     AS splits,
           SUM(m.unrecorded)::bigint AS unrecorded
      FROM merged m
     GROUP BY m.table_id, m.trigger_reason, m.board_count, m.variant
  )
  SELECT tt.table_id,
         t.name,
         tt.trigger_reason,
         tt.board_count,
         tt.variant,
         tt.hands,
         round(tt.seats_sum / NULLIF(tt.hands, 0), 2),
         round(tt.pot_sum   / NULLIF(tt.hands, 0), 2),
         round(tt.pot_sum,  2),
         round(tt.rake_sum, 2),
         round(tt.ante_sum, 2),
         tt.scoops,
         tt.splits,
         tt.unrecorded
    FROM totalled tt
    LEFT JOIN public.tables t ON t.id = tt.table_id
   ORDER BY tt.hands DESC;
END;
$$;


ALTER FUNCTION public.fn_club_bomb_pot_report(p_club_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_bomb_pot_report(p_club_id uuid, p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_bomb_pot_report(p_club_id uuid, p_days integer) IS 'Bomb pot summary for a club. Finished days come from ca_club_bomb_pot_daily, which outlives hand_history pruning; the hands are read only from the earliest unsealed day forward, which is normally today.';


--
-- Name: fn_club_cashier_can_transact(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_cashier_can_transact(p_club_id uuid, p_actor uuid, p_target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_club_id IS NULL OR p_actor IS NULL OR p_target IS NULL THEN false
    ELSE (
      SELECT CASE s.scope
        WHEN 'all'      THEN true
        WHEN 'downline' THEN public.fn_club_is_in_downline(p_club_id, p_actor, p_target)
        ELSE false
      END
      FROM (SELECT public.fn_club_cashier_scope(p_club_id, p_actor) AS scope) s
    )
  END;
$$;


ALTER FUNCTION public.fn_club_cashier_can_transact(p_club_id uuid, p_actor uuid, p_target uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_cashier_can_transact(p_club_id uuid, p_actor uuid, p_target uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_cashier_can_transact(p_club_id uuid, p_actor uuid, p_target uuid) IS 'True when the actor may send to, or claim from, the target in this club.';


--
-- Name: fn_club_cashier_members(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_cashier_members(p_club_id uuid) RETURNS TABLE(user_id uuid, role text, role_rank integer, depth integer, chip_balance numeric, name text, username text, player_number text, avatar_url text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_scope text;
begin
  if v_actor is null or p_club_id is null then
    return;
  end if;

  v_scope := public.fn_club_cashier_scope(p_club_id, v_actor);
  if v_scope = 'none' then
    return;
  end if;

  return query
  with recursive
  edges as (
    select cm.user_id as child, cm.agent_id as parent
      from club_members cm
     where cm.club_id = p_club_id
       and coalesce(cm.status, 'active') in ('active', 'approved')
       and cm.agent_id is not null
       and cm.agent_id <> cm.user_id
  ),
  tree as (
    select e.child, array[e.child] as path, 1 as depth
      from edges e
     where e.parent = v_actor
    union all
    select e.child, t.path || e.child, t.depth + 1
      from tree t
      join edges e on e.parent = t.child
     where not (e.child = any (t.path))
       and t.depth < 20
  ),
  flat as (
    select t.child as uid, min(t.depth)::int as d
      from tree t
     group by t.child
  ),
  scoped as (
    select cm.user_id as uid,
           coalesce(cm.role, 'player') as r,
           coalesce(cm.chip_balance, 0)::numeric as bal,
           coalesce(f.d, 0) as d
      from club_members cm
      left join flat f on f.uid = cm.user_id
     where cm.club_id = p_club_id
       and coalesce(cm.status, 'active') in ('active', 'approved')
       and (v_scope = 'all' or f.uid is not null)
  )
  select s.uid,
         s.r,
         (case s.r
            when 'owner' then 100 when 'co_owner' then 90 when 'admin' then 80
            when 'super_agent' then 60 when 'agent' then 40 when 'sub_agent' then 20
            else 0 end)::int,
         s.d,
         s.bal,
         public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                              pr.first_name, pr.last_name, pr.full_name)::text,
         coalesce(pr.username, '')::text,
         coalesce(pr.player_number, '')::text,
         coalesce(nullif(btrim(pr.avatar_url), ''), nullif(btrim(pr.arena_avatar_url), ''), '')::text
    from scoped s
    left join profiles pr on pr.id = s.uid
   order by s.d asc,
            (case s.r
               when 'owner' then 100 when 'co_owner' then 90 when 'admin' then 80
               when 'super_agent' then 60 when 'agent' then 40 when 'sub_agent' then 20
               else 0 end) desc,
            lower(public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                                       pr.first_name, pr.last_name, pr.full_name));
end
$$;


ALTER FUNCTION public.fn_club_cashier_members(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_cashier_members(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_cashier_members(p_club_id uuid) IS 'Members the caller may transact with in this club: everyone for staff, the recursive downline for an agent, nobody for a player.';


--
-- Name: fn_club_cashier_members_page_v3(uuid, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_cashier_members_page_v3(p_club_id uuid, p_after_role_rank integer DEFAULT NULL::integer, p_after_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500) RETURNS TABLE(user_id uuid, role text, role_rank integer, depth integer, chip_balance numeric, name text, username text, player_number text, avatar_url text, is_horse boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select m.user_id, m.role, m.role_rank, m.depth, m.chip_balance,
         m.name, m.username, m.player_number, m.avatar_url, (public.fn_can_see_horse_flag(p_club_id) AND COALESCE(m.is_horse,false))
    from public.fn_club_cashier_members_v2(p_club_id) m
   where p_after_role_rank is null
      or m.role_rank < p_after_role_rank
      or (m.role_rank = p_after_role_rank and m.user_id > p_after_user_id)
   order by m.role_rank desc, m.user_id
   limit greatest(1, least(coalesce(p_limit, 500), 500))
$$;


ALTER FUNCTION public.fn_club_cashier_members_page_v3(p_club_id uuid, p_after_role_rank integer, p_after_user_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_cashier_members_page_v3(p_club_id uuid, p_after_role_rank integer, p_after_user_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_cashier_members_page_v3(p_club_id uuid, p_after_role_rank integer, p_after_user_id uuid, p_limit integer) IS 'Stable keyset page of the caller-authorized cashier roster. Cursor is the previous page final role_rank/user_id.';


--
-- Name: fn_club_cashier_members_v2(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_cashier_members_v2(p_club_id uuid) RETURNS TABLE(user_id uuid, role text, role_rank integer, depth integer, chip_balance numeric, name text, username text, player_number text, avatar_url text, is_horse boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select m.user_id, m.role, m.role_rank, m.depth, m.chip_balance,
         m.name, m.username, m.player_number, m.avatar_url,
         -- MASKED: staff get the truth, everyone else gets a uniform false.
         (public.fn_can_see_horse_flag(p_club_id) and coalesce(p.is_horse, false))
    from public.fn_club_cashier_members(p_club_id) m
    left join public.profiles p on p.id=m.user_id
   order by m.role_rank desc, m.user_id
$$;


ALTER FUNCTION public.fn_club_cashier_members_v2(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_club_cashier_scope(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_cashier_scope(p_club_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case public.fn_club_bank_role(p_club_id, coalesce(p_user_id, auth.uid()))
    when 'owner'       then 'all'
    when 'co_owner'    then 'all'
    when 'admin'       then 'all'
    when 'super_agent' then 'downline'
    when 'agent'       then 'downline'
    when 'sub_agent'   then 'downline'
    else 'none'
  end;
$$;


ALTER FUNCTION public.fn_club_cashier_scope(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_cashier_scope(p_club_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_cashier_scope(p_club_id uuid, p_user_id uuid) IS 'Cashier visibility scope for a member of a club: all, downline or none.';


--
-- Name: fn_club_chat_is_silenced(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_chat_is_silenced(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE((
    SELECT true
      FROM public.blacklists b
     WHERE b.club_id = p_club_id
       AND b.user_id = auth.uid()
       AND (b.expires_at IS NULL OR b.expires_at > now())
     LIMIT 1
  ), false);
$$;


ALTER FUNCTION public.fn_club_chat_is_silenced(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_chat_is_silenced(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_chat_is_silenced(p_club_id uuid) IS 'True when the caller holds an unexpired blacklists row for this club. SECURITY DEFINER because blacklists_select is restricted to owners, admins and agents, so a banned member cannot see their own ban and an inline RLS subquery would never fire. Answers about the caller only.';


--
-- Name: fn_club_chip_circulation(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_chip_circulation(p_club_id uuid DEFAULT NULL::uuid) RETURNS TABLE(club_id uuid, club_name text, member_wallets numeric, on_the_felt numeric, treasury numeric, total numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT c.id, c.name,
         COALESCE((SELECT SUM(cm.chip_balance) FROM public.club_members cm
                    WHERE cm.club_id = c.id), 0),
         COALESCE((SELECT SUM(ts.stack) FROM public.table_seats ts
                    WHERE ts.club_id = c.id AND ts.left_at IS NULL), 0),
         COALESCE(c.chip_pool, 0),
         COALESCE((SELECT SUM(cm.chip_balance) FROM public.club_members cm
                    WHERE cm.club_id = c.id), 0)
         + COALESCE((SELECT SUM(ts.stack) FROM public.table_seats ts
                      WHERE ts.club_id = c.id AND ts.left_at IS NULL), 0)
         + COALESCE(c.chip_pool, 0)
  FROM public.clubs c
  WHERE p_club_id IS NULL OR c.id = p_club_id
  ORDER BY 6 DESC;
$$;


ALTER FUNCTION public.fn_club_chip_circulation(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_club_commission_accrued(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_commission_accrued(p_club_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_total numeric;
BEGIN
  IF p_club_id IS NULL THEN
    RETURN 0;
  END IF;

  -- Staff of THIS club, or a service caller. Anybody else gets zero rather than
  -- an error: this feeds a summary card, and a card is not the place to leak
  -- whether a club exists.
  IF NOT (public.fn_is_club_admin_uid(p_club_id)
          OR (auth.uid() IS NULL AND COALESCE(auth.role(), 'service_role') = 'service_role')) THEN
    RETURN 0;
  END IF;

  SELECT COALESCE(SUM(ac.amount), 0) INTO v_total
    FROM public.agent_commissions ac
   WHERE ac.club_id = p_club_id
     AND (p_since IS NULL OR ac.created_at >= p_since)
     AND (p_until IS NULL OR ac.created_at <  p_until);

  RETURN COALESCE(v_total, 0);
END;
$$;


ALTER FUNCTION public.fn_club_commission_accrued(p_club_id uuid, p_since timestamp with time zone, p_until timestamp with time zone) OWNER TO postgres;

