--
-- Name: fn_club_grantable_roles(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_grantable_roles(p_club_id uuid, p_actor_user_id uuid, p_target_user_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_role  text;
  v_target_role text;
  v_platform_admin boolean := false;
BEGIN
  IF p_actor_user_id IS NULL OR p_target_user_id IS NULL THEN RETURN '{}'; END IF;

  -- Nobody edits their own title. An owner demoting themselves would leave a
  -- club with no owner; anyone else would simply be promoting themselves.
  IF p_actor_user_id = p_target_user_id THEN RETURN '{}'; END IF;

  SELECT role INTO v_actor_role FROM club_members
   WHERE club_id = p_club_id AND user_id = p_actor_user_id
     AND status IN ('active','approved');

  SELECT role INTO v_target_role FROM club_members
   WHERE club_id = p_club_id AND user_id = p_target_user_id
     AND status IN ('active','approved');

  IF v_target_role IS NULL THEN RETURN '{}'; END IF;

  SELECT COALESCE(is_admin, false) INTO v_platform_admin
    FROM profiles WHERE id = p_actor_user_id;

  IF v_actor_role IS NULL AND NOT v_platform_admin THEN RETURN '{}'; END IF;

  -- The club owner is not demotable through this path. Handing over a club is
  -- a deliberate act of its own, not a dropdown on the members list.
  IF v_target_role = 'owner' THEN RETURN '{}'; END IF;

  IF v_platform_admin OR v_actor_role = 'owner' THEN
    RETURN ARRAY['co_owner','admin','super_agent','agent','sub_agent','player'];
  END IF;

  IF v_actor_role IN ('co_owner','admin') THEN
    -- "as high as admin". A co-owner outranks an admin but may not appoint or
    -- remove another co-owner; only the owner does that.
    IF fn_club_role_rank(v_target_role) >= fn_club_role_rank(v_actor_role) THEN
      RETURN '{}';
    END IF;
    RETURN ARRAY['admin','super_agent','agent','sub_agent','player'];
  END IF;

  -- A super agent manages the whole ladder beneath it, inside its own
  -- downline: agent, sub agent, player -- in either direction. It may not
  -- mint another super agent; that is owner / co-owner / admin work.
  IF v_actor_role = 'super_agent' THEN
    IF v_target_role IN ('player','agent','sub_agent')
       AND fn_club_is_in_downline(p_club_id, p_actor_user_id, p_target_user_id) THEN
      RETURN ARRAY['agent','sub_agent','player'];
    END IF;
    RETURN '{}';
  END IF;

  -- An agent may raise a player of theirs to sub agent, and put them back.
  IF v_actor_role = 'agent' THEN
    IF v_target_role IN ('player','sub_agent')
       AND fn_club_is_in_downline(p_club_id, p_actor_user_id, p_target_user_id) THEN
      RETURN ARRAY['sub_agent','player'];
    END IF;
    RETURN '{}';
  END IF;

  -- sub agents and players promote nobody
  RETURN '{}';
END;
$$;


ALTER FUNCTION public.fn_club_grantable_roles(p_club_id uuid, p_actor_user_id uuid, p_target_user_id uuid) OWNER TO postgres;

--
-- Name: fn_club_home_in_scope(uuid, boolean, uuid, uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_home_in_scope(p_club_id uuid, p_is_private boolean, p_union_id uuid, p_viewer_union_id uuid, p_viewer_club_id uuid, p_viewer_union_club_ids uuid[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE COST 1 PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_viewer_union_id IS NOT NULL THEN
      (p_union_id = p_viewer_union_id
       OR (p_club_id = p_viewer_club_id AND COALESCE(p_is_private, false)))
    ELSE p_club_id = ANY (p_viewer_union_club_ids)
  END;
$$;


ALTER FUNCTION public.fn_club_home_in_scope(p_club_id uuid, p_is_private boolean, p_union_id uuid, p_viewer_union_id uuid, p_viewer_club_id uuid, p_viewer_union_club_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_club_home_scope_parity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_home_scope_parity() RETURNS TABLE(club_id uuid, club_name text, union_id uuid, rpc_tournaments integer, union_tournaments integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT c.id, c.name, c.union_id,
         jsonb_array_length(COALESCE(public.get_club_home(c.id::text)->'tournaments','[]'::jsonb)),
         (SELECT count(*)::int FROM public.tournaments t
           WHERE t.union_id = c.union_id
             AND t.status IN ('REGISTERING','RUNNING'))
    FROM public.clubs c
   WHERE c.union_id IS NOT NULL AND c.union_id <> c.id
     -- Only a club that SHOULD see something. A union with no games is not a
     -- parity failure.
     AND EXISTS (SELECT 1 FROM public.tournaments t
                  WHERE t.union_id = c.union_id AND t.status IN ('REGISTERING','RUNNING'))
     AND jsonb_array_length(COALESCE(public.get_club_home(c.id::text)->'tournaments','[]'::jsonb)) = 0;
END;
$$;


ALTER FUNCTION public.fn_club_home_scope_parity() OWNER TO postgres;

--
-- Name: FUNCTION fn_club_home_scope_parity(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_home_scope_parity() IS 'Lists any union club whose club-home RPC returns ZERO tournaments while its union is running some. Empty result is the healthy state. Added after the tournament scope clause was found missing its union branch for the second time.';


--
-- Name: fn_club_is_in_downline(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_is_in_downline(p_club_id uuid, p_upline_user_id uuid, p_member_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH RECURSIVE dl AS (
    SELECT cm.user_id, 1 AS depth
      FROM public.club_members cm
     WHERE cm.club_id = p_club_id
       AND cm.agent_id = p_upline_user_id
       AND p_upline_user_id IS NOT NULL
       AND p_member_user_id IS NOT NULL
       AND p_upline_user_id <> p_member_user_id
    UNION
    SELECT cm.user_id, dl.depth + 1
      FROM public.club_members cm
      JOIN dl ON cm.agent_id = dl.user_id
     WHERE cm.club_id = p_club_id
       AND dl.depth < 20
  )
  SELECT EXISTS (SELECT 1 FROM dl WHERE dl.user_id = p_member_user_id);
$$;


ALTER FUNCTION public.fn_club_is_in_downline(p_club_id uuid, p_upline_user_id uuid, p_member_user_id uuid) OWNER TO postgres;

--
-- Name: fn_club_is_staff(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_is_staff(p_club_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.clubs c
     WHERE c.id = p_club_id
       AND c.owner_id = COALESCE(p_user_id, auth.uid())
  ) OR EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.club_id = p_club_id
       AND cm.user_id = COALESCE(p_user_id, auth.uid())
       AND cm.role IN ('owner', 'co_owner', 'admin')
       AND COALESCE(cm.status, 'active') IN ('active', 'approved')
  );
$$;


ALTER FUNCTION public.fn_club_is_staff(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_is_staff(p_club_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_is_staff(p_club_id uuid, p_user_id uuid) IS 'Owner, co-owner or admin of this club. The mirror of isClubStaff() in src/types/clubRoles.ts. Ask this instead of spelling out a role list: co_owner was missed by twenty-four hand-rolled lists precisely because they were hand-rolled.';


--
-- Name: fn_club_leaderboard_by_dates(uuid, text, date, date, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_leaderboard_by_dates(p_club_id uuid, p_metric text DEFAULT 'profit'::text, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_limit integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid, hands_played numeric, total_winnings numeric, total_losses numeric, tournaments_won numeric, total_rake numeric, sum_big_blind numeric, rank_change integer, qualified boolean, rank integer, total_ranked integer, baseline_date date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_today date := (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')::date;
  v_start date := COALESCE(p_start_date, v_today - 7);
  v_end date := COALESCE(p_end_date, v_today);
  v_span integer;
  v_baseline date;
  v_end_snap date;
  v_prev_start date;
  v_use_live boolean;
  v_min_hands integer := 20;
BEGIN
  IF v_end < v_start THEN
    RAISE EXCEPTION 'end date % precedes start date %', v_end, v_start
      USING ERRCODE = '22023';
  END IF;
  v_span := GREATEST(v_end - v_start, 1);

  SELECT max(snapshot_date) INTO v_baseline
    FROM public.player_stats_snapshots
   WHERE club_id = p_club_id AND snapshot_date <= v_start;

  -- end_date is exclusive. A window ending today closed at 00:00 UTC and must
  -- not consume today's mutable totals.
  v_use_live := (v_end > v_today);
  IF NOT v_use_live THEN
    SELECT max(snapshot_date) INTO v_end_snap
      FROM public.player_stats_snapshots
     WHERE club_id = p_club_id AND snapshot_date <= v_end;
    IF v_end_snap IS NULL OR (v_baseline IS NOT NULL AND v_end_snap <= v_baseline) THEN
      RETURN;
    END IF;
  END IF;

  SELECT max(snapshot_date) INTO v_prev_start
    FROM public.player_stats_snapshots
   WHERE club_id = p_club_id AND snapshot_date <= v_start - v_span;

  RETURN QUERY
  WITH end_s AS (
    SELECT ps.user_id AS uid, ps.hands_dealt::numeric AS h,
           ps.total_winnings AS w, ps.total_losses AS l,
           ps.tournaments_won::numeric AS t, ps.total_rake AS rk,
           ps.sum_big_blind AS bb
      FROM public.player_stats ps
     WHERE v_use_live AND ps.club_id = p_club_id
    UNION ALL
    SELECT s.user_id, s.hands_dealt::numeric, s.total_winnings, s.total_losses,
           s.tournaments_won::numeric, s.total_rake, s.sum_big_blind
      FROM public.player_stats_snapshots s
     WHERE NOT v_use_live AND s.club_id = p_club_id AND s.snapshot_date = v_end_snap
  ),
  base_s AS (
    SELECT s.user_id AS uid, s.hands_dealt::numeric AS h,
           s.total_winnings AS w, s.total_losses AS l,
           s.tournaments_won::numeric AS t, s.total_rake AS rk,
           s.sum_big_blind AS bb
      FROM public.player_stats_snapshots s
     WHERE s.club_id = p_club_id
       AND v_baseline IS NOT NULL
       AND s.snapshot_date = v_baseline
  ),
  prev_s AS (
    SELECT s.user_id AS uid, s.hands_dealt::numeric AS h,
           s.total_winnings AS w, s.total_losses AS l,
           s.tournaments_won::numeric AS t, s.sum_big_blind AS bb
      FROM public.player_stats_snapshots s
     WHERE s.club_id = p_club_id
       AND v_prev_start IS NOT NULL
       AND s.snapshot_date = v_prev_start
  ),
  cur AS (
    SELECT e.uid,
           GREATEST(e.h - COALESCE(b.h, 0), 0) AS d_hands,
           e.w - COALESCE(b.w, 0) AS d_win,
           e.l - COALESCE(b.l, 0) AS d_loss,
           GREATEST(e.t - COALESCE(b.t, 0), 0) AS d_twon,
           GREATEST(e.rk - COALESCE(b.rk, 0), 0) AS d_rake,
           GREATEST(e.bb - COALESCE(b.bb, 0), 0) AS d_bb,
           CASE WHEN b.uid IS NULL THEN NULL ELSE GREATEST(b.h - COALESCE(p.h, 0), 0) END AS p_hands,
           CASE WHEN b.uid IS NULL THEN NULL ELSE b.w - COALESCE(p.w, 0) END AS p_win,
           CASE WHEN b.uid IS NULL THEN NULL ELSE b.l - COALESCE(p.l, 0) END AS p_loss,
           CASE WHEN b.uid IS NULL THEN NULL ELSE GREATEST(b.t - COALESCE(p.t, 0), 0) END AS p_twon,
           CASE WHEN b.uid IS NULL THEN NULL ELSE GREATEST(b.bb - COALESCE(p.bb, 0), 0) END AS p_bb
      FROM end_s e
      LEFT JOIN base_s b ON b.uid = e.uid
      LEFT JOIN prev_s p ON p.uid = e.uid
  ),
  scored AS (
    SELECT c.*,
           CASE p_metric
             WHEN 'hands_played' THEN c.d_hands
             WHEN 'tournaments_won' THEN c.d_twon
             WHEN 'roi' THEN CASE WHEN c.d_loss > 0 AND c.d_hands >= v_min_hands
                                  THEN (c.d_win-c.d_loss)/c.d_loss END
             WHEN 'bb100' THEN CASE WHEN c.d_bb > 0 AND c.d_hands >= v_min_hands
                                    THEN 100*(c.d_win-c.d_loss)/c.d_bb END
             ELSE c.d_win-c.d_loss
           END AS score,
           CASE p_metric
             WHEN 'hands_played' THEN c.p_hands
             WHEN 'tournaments_won' THEN c.p_twon
             WHEN 'roi' THEN CASE WHEN c.p_loss > 0 AND c.p_hands >= v_min_hands
                                  THEN (c.p_win-c.p_loss)/c.p_loss END
             WHEN 'bb100' THEN CASE WHEN c.p_bb > 0 AND c.p_hands >= v_min_hands
                                    THEN 100*(c.p_win-c.p_loss)/c.p_bb END
             ELSE c.p_win-c.p_loss
           END AS prev_score
      FROM cur c
  ),
  ranked AS (
    SELECT s.*,
           row_number() OVER (ORDER BY s.score DESC NULLS LAST, s.uid) AS rn_now,
           rank() OVER (ORDER BY s.score DESC NULLS LAST) AS rk_now,
           count(*) OVER () AS total_active,
           CASE WHEN s.prev_score IS NULL THEN NULL
                ELSE rank() OVER (ORDER BY s.prev_score DESC NULLS LAST) END AS rk_old
      FROM scored s
     WHERE (s.d_hands > 0 OR s.d_twon > 0 OR s.d_win <> 0 OR s.d_loss <> 0)
  )
  SELECT r.uid, r.d_hands, r.d_win, r.d_loss, r.d_twon, r.d_rake, r.d_bb,
         COALESCE((r.rk_old - r.rk_now)::integer, 0),
         (p_metric NOT IN ('roi','bb100') OR
          (r.d_hands >= v_min_hands AND
           (CASE WHEN p_metric='roi' THEN r.d_loss ELSE r.d_bb END) > 0)),
         r.rk_now::integer, r.total_active::integer, v_baseline
    FROM ranked r
   ORDER BY r.rn_now
   LIMIT p_limit OFFSET GREATEST(COALESCE(p_offset,0),0);
END;
$$;


ALTER FUNCTION public.fn_club_leaderboard_by_dates(p_club_id uuid, p_metric text, p_start_date date, p_end_date date, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_club_leaderboard_period(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_leaderboard_period(p_club_id uuid, p_metric text DEFAULT 'profit'::text, p_period text DEFAULT 'weekly'::text, p_limit integer DEFAULT 10) RETURNS TABLE(user_id uuid, hands_played numeric, total_winnings numeric, total_losses numeric, tournaments_won numeric, total_rake numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_days integer; v_target date; v_baseline date;
BEGIN
  v_days := CASE p_period WHEN 'daily' THEN 1 WHEN 'weekly' THEN 7 WHEN 'monthly' THEN 30 ELSE 0 END;
  IF v_days = 0 THEN
    RETURN QUERY
      SELECT ps.user_id, ps.hands_played::numeric, ps.total_winnings::numeric,
             ps.total_losses::numeric, ps.tournaments_won::numeric, ps.total_rake::numeric
      FROM player_stats ps WHERE ps.club_id = p_club_id
      ORDER BY (CASE p_metric WHEN 'hands_played' THEN ps.hands_played::numeric
                              WHEN 'tournaments_won' THEN ps.tournaments_won::numeric
                              ELSE (ps.total_winnings - ps.total_losses) END) DESC
      LIMIT p_limit;
    RETURN;
  END IF;

  v_target := CURRENT_DATE - v_days;
  SELECT max(snapshot_date) INTO v_baseline FROM player_stats_snapshots
   WHERE club_id = p_club_id AND snapshot_date <= v_target;
  IF v_baseline IS NULL THEN
    SELECT min(snapshot_date) INTO v_baseline FROM player_stats_snapshots WHERE club_id = p_club_id;
  END IF;

  RETURN QUERY
    SELECT ps.user_id,
           GREATEST(ps.hands_played - COALESCE(s.hands_played,0),0)::numeric,
           (ps.total_winnings - COALESCE(s.total_winnings,0))::numeric,
           (ps.total_losses - COALESCE(s.total_losses,0))::numeric,
           GREATEST(ps.tournaments_won - COALESCE(s.tournaments_won,0),0)::numeric,
           GREATEST(ps.total_rake - COALESCE(s.total_rake,0),0)::numeric
    FROM player_stats ps
    LEFT JOIN player_stats_snapshots s
      ON s.user_id = ps.user_id AND s.club_id = ps.club_id AND s.snapshot_date = v_baseline
    WHERE ps.club_id = p_club_id
    ORDER BY (CASE p_metric
      WHEN 'hands_played' THEN GREATEST(ps.hands_played - COALESCE(s.hands_played,0),0)
      WHEN 'tournaments_won' THEN GREATEST(ps.tournaments_won - COALESCE(s.tournaments_won,0),0)
      ELSE ((ps.total_winnings - COALESCE(s.total_winnings,0)) - (ps.total_losses - COALESCE(s.total_losses,0)))
    END) DESC
    LIMIT p_limit;
END; $$;


ALTER FUNCTION public.fn_club_leaderboard_period(p_club_id uuid, p_metric text, p_period text, p_limit integer) OWNER TO postgres;

--
-- Name: fn_club_leaderboard_period_v2(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_leaderboard_period_v2(p_club_id uuid, p_metric text DEFAULT 'profit'::text, p_period text DEFAULT 'weekly'::text, p_limit integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid, hands_played numeric, total_winnings numeric, total_losses numeric, tournaments_won numeric, total_rake numeric, sum_big_blind numeric, rank_change integer, qualified boolean, rank integer, total_ranked integer, baseline_date date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_period_start date;
  v_baseline date;
  v_prev_end date;
  v_min_hands integer := 20;
  v_is_all_time boolean := p_period = 'all_time';
BEGIN
  SELECT bounds.start_date INTO v_period_start
    FROM public.fn_leaderboard_period_window(p_period, 0) bounds;

  IF NOT v_is_all_time THEN
    SELECT max(snapshot_date) INTO v_baseline
      FROM public.player_stats_snapshots
     WHERE club_id = p_club_id AND snapshot_date <= v_period_start;
    IF v_baseline IS NULL THEN
      SELECT min(snapshot_date) INTO v_baseline
        FROM public.player_stats_snapshots WHERE club_id = p_club_id;
    END IF;
  END IF;

  SELECT max(snapshot_date) INTO v_prev_end
    FROM public.player_stats_snapshots
   WHERE club_id = p_club_id AND snapshot_date <= (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')::date - 1;

  RETURN QUERY
  WITH cur AS (
    SELECT ps.user_id AS uid,
           (CASE WHEN v_is_all_time THEN ps.hands_dealt::numeric ELSE GREATEST(ps.hands_dealt-COALESCE(b.hands_dealt,0),0)::numeric END) AS d_hands,
           (CASE WHEN v_is_all_time THEN ps.total_winnings ELSE (ps.total_winnings-COALESCE(b.total_winnings,0)) END) AS d_win,
           (CASE WHEN v_is_all_time THEN ps.total_losses ELSE (ps.total_losses-COALESCE(b.total_losses,0)) END) AS d_loss,
           (CASE WHEN v_is_all_time THEN ps.tournaments_won::numeric ELSE GREATEST(ps.tournaments_won-COALESCE(b.tournaments_won,0),0)::numeric END) AS d_twon,
           (CASE WHEN v_is_all_time THEN ps.total_rake ELSE GREATEST(ps.total_rake-COALESCE(b.total_rake,0),0) END) AS d_rake,
           (CASE WHEN v_is_all_time THEN ps.sum_big_blind ELSE GREATEST(ps.sum_big_blind-COALESCE(b.sum_big_blind,0),0) END) AS d_bb,
           (CASE WHEN pe.user_id IS NULL OR (NOT v_is_all_time AND v_prev_end <= v_baseline) THEN NULL ELSE GREATEST(pe.hands_dealt-COALESCE(pv.hands_dealt,0),0)::numeric END) AS p_hands,
           (CASE WHEN pe.user_id IS NULL OR (NOT v_is_all_time AND v_prev_end <= v_baseline) THEN NULL ELSE (pe.total_winnings-COALESCE(pv.total_winnings,0)) END) AS p_win,
           (CASE WHEN pe.user_id IS NULL OR (NOT v_is_all_time AND v_prev_end <= v_baseline) THEN NULL ELSE (pe.total_losses-COALESCE(pv.total_losses,0)) END) AS p_loss,
           (CASE WHEN pe.user_id IS NULL OR (NOT v_is_all_time AND v_prev_end <= v_baseline) THEN NULL ELSE GREATEST(pe.tournaments_won-COALESCE(pv.tournaments_won,0),0)::numeric END) AS p_twon,
           (CASE WHEN pe.user_id IS NULL OR (NOT v_is_all_time AND v_prev_end <= v_baseline) THEN NULL ELSE GREATEST(pe.sum_big_blind-COALESCE(pv.sum_big_blind,0),0) END) AS p_bb
      FROM public.player_stats ps
      LEFT JOIN public.player_stats_snapshots b
        ON NOT v_is_all_time AND b.user_id=ps.user_id AND b.club_id=ps.club_id AND b.snapshot_date=v_baseline
      LEFT JOIN public.player_stats_snapshots pe
        ON pe.user_id=ps.user_id AND pe.club_id=ps.club_id AND pe.snapshot_date=v_prev_end
      LEFT JOIN public.player_stats_snapshots pv
        ON NOT v_is_all_time AND pv.user_id=ps.user_id AND pv.club_id=ps.club_id AND pv.snapshot_date=v_baseline
     WHERE ps.club_id = p_club_id
  ),
  scored AS (
    SELECT c.*,
           (CASE p_metric
              WHEN 'hands_played' THEN c.d_hands
              WHEN 'tournaments_won' THEN c.d_twon
              WHEN 'roi' THEN CASE WHEN c.d_loss>0 AND c.d_hands>=v_min_hands THEN (c.d_win-c.d_loss)/c.d_loss END
              WHEN 'bb100' THEN CASE WHEN c.d_bb>0 AND c.d_hands>=v_min_hands THEN 100*(c.d_win-c.d_loss)/c.d_bb END
              ELSE (c.d_win-c.d_loss) END) AS score,
           (CASE p_metric
              WHEN 'hands_played' THEN c.p_hands
              WHEN 'tournaments_won' THEN c.p_twon
              WHEN 'roi' THEN CASE WHEN c.p_loss>0 AND c.p_hands>=v_min_hands THEN (c.p_win-c.p_loss)/c.p_loss END
              WHEN 'bb100' THEN CASE WHEN c.p_bb>0 AND c.p_hands>=v_min_hands THEN 100*(c.p_win-c.p_loss)/c.p_bb END
              ELSE (c.p_win-c.p_loss) END) AS prev_score
      FROM cur c
  ),
  ranked AS (
    SELECT s.*,
           row_number() OVER (ORDER BY s.score DESC NULLS LAST, s.uid) AS rn_now,
           rank() OVER (ORDER BY s.score DESC NULLS LAST) AS rk_now,
           count(*) OVER () AS total_active,
           CASE WHEN s.prev_score IS NULL THEN NULL
                ELSE rank() OVER (ORDER BY s.prev_score DESC NULLS LAST) END AS rk_old
      FROM scored s
     WHERE (s.d_hands > 0 OR s.d_twon > 0 OR s.d_win <> 0 OR s.d_loss <> 0)
  )
  SELECT r.uid, r.d_hands, r.d_win, r.d_loss, r.d_twon, r.d_rake, r.d_bb,
         COALESCE((r.rk_old-r.rk_now)::integer,0),
         (p_metric NOT IN ('roi','bb100') OR
          (r.d_hands>=v_min_hands AND (CASE WHEN p_metric='roi' THEN r.d_loss ELSE r.d_bb END)>0)),
         r.rk_now::integer, r.total_active::integer, v_baseline
    FROM ranked r
   ORDER BY r.rn_now
   LIMIT p_limit OFFSET GREATEST(COALESCE(p_offset,0),0);
END;
$$;


ALTER FUNCTION public.fn_club_leaderboard_period_v2(p_club_id uuid, p_metric text, p_period text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_club_level_for_members(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_level_for_members(p_members integer) RETURNS smallint
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT MAX(level) FROM public.club_level_thresholds
      WHERE min_members <= GREATEST(COALESCE(p_members, 0), 0)),
    1::smallint);
$$;


ALTER FUNCTION public.fn_club_level_for_members(p_members integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_level_for_members(p_members integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_level_for_members(p_members integer) IS 'Club level 1-55 from member count. Mirrors getClubLevelFromMembers() in the Club Arena client exactly.';


--
-- Name: fn_club_level_min_members(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_level_min_members(p_level integer) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT min_members FROM public.club_level_thresholds
      WHERE level = LEAST(GREATEST(COALESCE(p_level, 1), 1),
                          (SELECT MAX(level) FROM public.club_level_thresholds))),
    0);
$$;


ALTER FUNCTION public.fn_club_level_min_members(p_level integer) OWNER TO postgres;

--
-- Name: fn_club_member_count(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_member_count(p_club_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT count(*)::int
  FROM public.club_members cm
  WHERE cm.club_id = p_club_id
    AND cm.status IN ('active', 'approved');
$$;


ALTER FUNCTION public.fn_club_member_count(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_member_count(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_member_count(p_club_id uuid) IS 'Active/approved member COUNT of one club, as an integer and nothing else. SECURITY DEFINER on purpose: the count is public (every club card shows it) and under club_members RLS the same COUNT evaluated four policy functions per row - 2,026 ms for a 417-member club, called ~70x/min by get_club_home (2026-09-02).';


--
-- Name: fn_club_member_counts(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_member_counts(p_club_id uuid) RETURNS TABLE(total bigint, active bigint, pending bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT
    count(*)                                                                   AS total,
    count(*) FILTER (WHERE status IS NULL OR status IN ('active','approved'))  AS active,
    count(*) FILTER (WHERE status = 'pending')                                 AS pending
  FROM club_members
  WHERE club_id = p_club_id;
$$;


ALTER FUNCTION public.fn_club_member_counts(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_member_counts(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_member_counts(p_club_id uuid) IS 'Total / active / pending member counts for one club, from a single scan. SECURITY DEFINER because a club''s member count is a property of the club, not of who is asking - a direct count is RLS-filtered and returns 0 to non-members.';


--
-- Name: fn_club_member_daily_profit_exact(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_member_daily_profit_exact(p_club_id uuid, p_date date) RETURNS TABLE(user_id uuid, exact_profit numeric, basis text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT b.user_id,
         (a.total_winnings - b.total_winnings) - (a.total_losses - b.total_losses),
         CASE WHEN p_date >= DATE '2026-08-20' THEN 'exact'
              ELSE 'partial_raked_hands_only' END
    FROM player_stats_snapshots b
    JOIN player_stats_snapshots a
      ON a.user_id = b.user_id AND a.club_id = b.club_id AND a.snapshot_date = p_date + 1
   WHERE b.snapshot_date = p_date AND b.club_id = p_club_id;
$$;


ALTER FUNCTION public.fn_club_member_daily_profit_exact(p_club_id uuid, p_date date) OWNER TO postgres;

--
-- Name: fn_club_member_notes_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_member_notes_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.nickname IS NOT DISTINCT FROM OLD.nickname
     AND NEW.notes IS NOT DISTINCT FROM OLD.notes THEN
    RETURN NEW;
  END IF;

  IF coalesce(auth.role(), 'service_role') = 'service_role'
     OR current_setting('app.club_notes_update', true) = 'on' THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION USING ERRCODE = '42501',
    MESSAGE = 'Member Notes Must Be Updated Through ca_club_member_notes_update';
END;
$$;


ALTER FUNCTION public.fn_club_member_notes_guard() OWNER TO postgres;

