-- Name: fn_club_members_bot_follows_horse(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_members_bot_follows_horse() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.is_bot := coalesce(
