COMMENT ON FUNCTION public.fn_club_members_bot_follows_horse() IS 'Keeps club_members.is_bot equal to profiles.is_horse. Added 2026-08-27 after 985 horses (74.5M chips) sat flagged as human because HorseOnboarding inserted the row without the column.';


--
-- Name: fn_club_members_ledger_writer(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_members_ledger_writer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  d     numeric;
  actor uuid;
  cat   text;
  tid   uuid;
  st    text;
  msg   text;
  cp    text;
  cpid  uuid;
BEGIN
  d := COALESCE(NEW.chip_balance, 0) - COALESCE(OLD.chip_balance, 0);

  IF d = 0 THEN
    RETURN NEW;
  END IF;

  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

  cat := COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'adjustment');

  BEGIN
    tid := NULLIF(current_setting('app.ledger_tournament', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    tid := NULL;
  END;

  /* THE COUNTERPARTY IS DECLARED, NEVER INFERRED (2026-08-31). */
  cp := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), 'settlement_suspense');
  BEGIN
    cpid := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    cpid := NULL;
  END;

  BEGIN
    INSERT INTO public.chip_ledger
      (performed_by, from_type, from_entity_id, to_type, to_entity_id,
       amount, category, club_id, tournament_id, description)
    VALUES (
      actor,
      CASE WHEN d > 0 THEN cp              ELSE 'player_wallet' END,
      CASE WHEN d > 0 THEN cpid            ELSE NEW.user_id     END,
      CASE WHEN d > 0 THEN 'player_wallet' ELSE cp              END,
      CASE WHEN d > 0 THEN NEW.user_id     ELSE cpid            END,
      abs(d), cat, NEW.club_id, tid,
      'auto-audited club_members.chip_balance delta ' || d::text);

  EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_club_members_ledger_writer() OWNER TO postgres;

--
-- Name: FUNCTION fn_club_members_ledger_writer(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_members_ledger_writer() IS 'chip_ledger writer for club_members.chip_balance deltas. The counterparty is DECLARED by the caller via app.ledger_counterparty / app.ledger_counterparty_entity and defaults to table_stack; it is never inferred. Never raises, never blocks a chip movement: three-step retry, then ca_ledger_write_failures.';


--
-- Name: fn_club_members_no_agent_cycle(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_members_no_agent_cycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cursor uuid;
  v_hops   int := 0;
begin
  if new.agent_id is null then
    return new;
  end if;

  if new.agent_id = new.user_id then
    raise exception
      'club_members.agent_id: a member cannot be their own upline (club %, member %)',
      new.club_id, new.user_id
      using errcode = '23514';
  end if;

  v_cursor := new.agent_id;
  while v_cursor is not null and v_hops < 64 loop
    if v_cursor = new.user_id then
      raise exception
        'club_members.agent_id: % cannot sit under % - that would close a cycle in club %',
        new.user_id, new.agent_id, new.club_id
        using errcode = '23514';
    end if;
    select cm.agent_id
      into v_cursor
      from public.club_members cm
     where cm.club_id = new.club_id
       and cm.user_id = v_cursor;
    if not found then
      exit;
    end if;
    v_hops := v_hops + 1;
  end loop;

  if v_hops >= 64 then
    raise exception
      'club_members.agent_id: the upline chain above % is deeper than 64 levels or already loops',
      new.agent_id
      using errcode = '23514';
  end if;

  return new;
end
$$;


ALTER FUNCTION public.fn_club_members_no_agent_cycle() OWNER TO postgres;

--
-- Name: FUNCTION fn_club_members_no_agent_cycle(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_members_no_agent_cycle() IS 'Refuses a club_members.agent_id write that would make a member their own upline or close a cycle. Walks up from the proposed parent, club scoped, capped at 64 hops.';


--
-- Name: fn_club_members_role_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_members_role_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role THEN
    -- fn_club_set_member_role sets this for the duration of its own UPDATE.
    IF COALESCE(current_setting('app.club_role_change', true), '') <> 'on'
       -- migrations, seeds and server-side jobs run as these and are trusted
       AND current_user NOT IN ('postgres', 'supabase_admin', 'service_role') THEN
      RAISE EXCEPTION
        'club_members.role must be changed through fn_club_set_member_role (attempted % -> %, as %)',
        OLD.role, NEW.role, current_user
        USING ERRCODE = '42501',
              HINT = 'The grant matrix lives in fn_club_grantable_roles. A direct '
                     'update would bypass it, which is what this trigger exists to stop.';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_club_members_role_guard() OWNER TO postgres;

--
-- Name: fn_club_members_staff_earn_no_rakeback(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_members_staff_earn_no_rakeback() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Dan 2026-08-31: "CO-OWNERS AND ADMINS GET NO RAKE BACK."
  -- player_rakeback_pct is the first branch of fn_player_rakeback_rate, so a
  -- non-zero value here is money. owner is deliberately not covered.
  NEW.player_rakeback_pct := 0;
  NEW.rakeback_rate       := 0;
  NEW.commission_rate     := 0;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_club_members_staff_earn_no_rakeback() OWNER TO postgres;

--
-- Name: fn_club_money_panel(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_money_panel(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_union_id uuid; v_club record;
  v_is_member boolean := false; v_is_club_staff boolean := false; v_is_union_staff boolean := false;
  v_scope text; v_pool record; v_w record;
  v_week_start timestamptz := date_trunc('week', now());
  v_club_rake numeric := 0; v_rate numeric := 0.90;
  v_clubs_wallet numeric; v_union_week numeric; v_out jsonb;
  v_spin_idle numeric := 0; v_spin_deployed numeric := 0;
  v_bbj jsonb;
BEGIN
  IF v_uid IS NULL OR p_club_id IS NULL THEN
    RETURN jsonb_build_object('authorized', false, 'reason', 'no_auth');
  END IF;

  SELECT id, name, union_id, COALESCE(chip_treasury,0) AS chip_treasury,
         COALESCE(chip_pool,0) AS chip_pool, COALESCE(promo_balance,0) AS promo_balance,
         owner_id
    INTO v_club FROM clubs WHERE id = p_club_id;
  IF v_club.id IS NULL THEN
    RETURN jsonb_build_object('authorized', false, 'reason', 'club_not_found');
  END IF;
  v_union_id := v_club.union_id;

  -- The jackpot, resolved BEFORE the membership gate. Union-first, exactly as
  -- the engine banks it: a club inside a union contributes to the UNION pool.
  SELECT bp.id, COALESCE(bp.main_balance,0) main_balance,
         COALESCE(bp.backup_balance,0) backup_balance,
         COALESCE(bp.promo_balance,0) promo_balance,
         bp.union_id IS NOT NULL AS is_union_pool
    INTO v_pool FROM bbj_pools bp
   WHERE bp.status = 'active'
     AND ((v_union_id IS NOT NULL AND bp.union_id = v_union_id)
       OR (v_union_id IS NULL  AND bp.club_id = p_club_id))
   ORDER BY (bp.union_id IS NOT NULL) DESC LIMIT 1;

  v_bbj := jsonb_build_object(
    'pool_id', v_pool.id, 'is_union_pool', COALESCE(v_pool.is_union_pool, false),
    'main', round(COALESCE(v_pool.main_balance,0), 2),
    'backup', round(COALESCE(v_pool.backup_balance,0), 2),
    'promo_in_pool', round(COALESCE(v_pool.promo_balance,0), 2));

  SELECT EXISTS (SELECT 1 FROM club_members cm WHERE cm.club_id = p_club_id AND cm.user_id = v_uid)
    INTO v_is_member;
  v_is_club_staff := (v_club.owner_id = v_uid)
    OR EXISTS (SELECT 1 FROM club_members cm WHERE cm.club_id = p_club_id AND cm.user_id = v_uid
                 AND lower(COALESCE(cm.role,'')) IN ('owner','co_owner','admin','manager'));

  IF v_union_id IS NOT NULL THEN
    v_is_union_staff := EXISTS (SELECT 1 FROM unions u WHERE u.id = v_union_id AND u.owner_id = v_uid)
      OR EXISTS (SELECT 1 FROM union_admins ua WHERE ua.union_id = v_union_id AND ua.user_id = v_uid);
  END IF;

  IF NOT (v_is_member OR v_is_club_staff OR v_is_union_staff) THEN
    -- Still a refusal in every respect the caller relies on: `scope` is absent,
    -- so club money renders "-" and never 0.00. Only the public jackpot rides
    -- along.
    RETURN jsonb_build_object('authorized', false, 'reason', 'not_a_member',
                              'bbj', v_bbj);
  END IF;

  v_scope := CASE WHEN v_is_union_staff THEN 'union'
                  WHEN v_is_club_staff  THEN 'club' ELSE 'member' END;

  v_out := jsonb_build_object(
    'authorized', true, 'scope', v_scope, 'club_id', p_club_id, 'club_name', v_club.name,
    'in_union', v_union_id IS NOT NULL, 'union_id', v_union_id,
    'club_treasury', round(v_club.chip_treasury, 2), 'club_pool', round(v_club.chip_pool, 2),
    /* THE CLUB'S PROMO WALLET (Dan, 2026-09-02): "NONE OF THE CHIPS FROM THE
       BBJ RAKE ARE GOING INTO THE PROMO WALLET." They were. Every hand's BBJ
       drop splits 50/25/25 main/backup/promo (bbj_record_contribution), and
       fn_sweep_bbj_promo moves the promo slice out of the pool into
       clubs.promo_balance for a standalone club - 1,220.19 of it in Deep
       Stack Society alone. This panel never returned that column, so no
       surface could show it and the club's Promo Wallet row fell back to the
       VIEWER'S OWN agents.promo_wallet_balance, which reads 0.00 for an owner
       who is not an agent. Club money, at exactly the sensitivity of
       club_treasury beside it, and club-scoped: a club inside a union banks
       its promo slice in the UNION wallet, so this is honestly 0 there and
       'union_promo' below carries the union's figure for union staff. */
    'club_promo_wallet', round(COALESCE(v_club.promo_balance, 0), 2),
    'bbj', v_bbj,
    'week_start', v_week_start, 'next_close_at', v_week_start + interval '7 days');

  IF v_union_id IS NULL THEN
    IF v_is_club_staff THEN
      SELECT round(COALESCE(w.period_rake_collected, 0), 2) INTO v_club_rake
        FROM club_wallets w WHERE w.club_id = p_club_id;
      IF FOUND THEN
        v_out := v_out || jsonb_build_object('club_rake_treasury', v_club_rake);
      END IF;
    END IF;
    RETURN v_out;
  END IF;

  IF v_is_club_staff OR v_is_union_staff THEN
    SELECT COALESCE(
             (SELECT w.rake_total FROM union_rake_weekly w
               WHERE w.union_id = v_union_id AND w.club_id = p_club_id
                 AND w.week_start = v_week_start::date),
             (SELECT COALESCE(SUM(t.amount), 0) FROM union_wallet_transactions t
               WHERE t.union_id = v_union_id AND t.club_id = p_club_id
                 AND t.wallet = 'rake_wallet' AND t.direction = 'credit' AND t.tx_type = 'rake'
                 AND t.created_at >= v_week_start),
             0) INTO v_club_rake;
    SELECT COALESCE(uc.club_commission_rate, 0.90) INTO v_rate
      FROM union_clubs uc WHERE uc.union_id = v_union_id AND uc.club_id = p_club_id;
    v_out := v_out || jsonb_build_object(
      'club_rake_this_week', round(v_club_rake, 2),
      'club_rakeback_rate', COALESCE(v_rate, 0.90),
      'club_projected_rakeback', trunc(v_club_rake * COALESCE(v_rate, 0.90) * 100) / 100);
  END IF;

  IF v_is_union_staff THEN
    SELECT round(COALESCE(chip_balance,0),2) chip_balance,
           round(COALESCE(rake_wallet,0),2) rake_wallet,
           round(COALESCE(promo_wallet,0),2) promo_wallet,
           round(COALESCE(spin_reserve_wallet,0),2) spin_reserve_wallet
      INTO v_w FROM union_wallets WHERE union_id = v_union_id;

    SELECT COALESCE(SUM(COALESCE(c.chip_treasury,0)), 0) INTO v_clubs_wallet
      FROM clubs c WHERE c.union_id = v_union_id AND c.id <> v_union_id;

    SELECT COALESCE(
             (SELECT SUM(w.rake_total) FROM union_rake_weekly w
               WHERE w.union_id = v_union_id AND w.week_start = v_week_start::date),
             (SELECT COALESCE(SUM(t.amount), 0) FROM union_wallet_transactions t
               WHERE t.union_id = v_union_id AND t.wallet = 'rake_wallet'
                 AND t.direction = 'credit' AND t.tx_type = 'rake' AND t.created_at >= v_week_start),
             0) INTO v_union_week;

    v_spin_idle := COALESCE(v_w.spin_reserve_wallet, 0);
    SELECT COALESCE(SUM(COALESCE(sp.balance, 0)), 0) INTO v_spin_deployed
      FROM spin_bonus_pools sp
     WHERE sp.is_active
       AND (sp.club_id = v_union_id
            OR sp.club_id IN (SELECT uc.club_id FROM union_clubs uc WHERE uc.union_id = v_union_id));

    v_out := v_out || jsonb_build_object(
      'union_bank', COALESCE(v_w.chip_balance, 0),
      'rake_treasury', COALESCE(v_w.rake_wallet, 0),
      'union_promo', COALESCE(v_w.promo_wallet, 0),
      'union_spin_treasury', round(v_spin_idle + v_spin_deployed, 2),
      'union_spin_idle', round(v_spin_idle, 2),
      'union_spin_deployed', round(v_spin_deployed, 2),
      'clubs_wallet', round(v_clubs_wallet, 2),
      'union_rake_this_week', round(v_union_week, 2),
      'projected_clubs_share', trunc(v_union_week * 0.90 * 100) / 100,
      'projected_union_share', round(v_union_week - trunc(v_union_week * 0.90 * 100) / 100, 2));
  END IF;

  RETURN v_out;
END
$$;


ALTER FUNCTION public.fn_club_money_panel(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_club_name_available(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_name_available(p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT length(btrim(COALESCE(p_name, ''))) BETWEEN 3 AND 30
     AND NOT EXISTS (
       SELECT 1 FROM public.clubs WHERE lower(name) = lower(btrim(p_name))
     );
$$;


ALTER FUNCTION public.fn_club_name_available(p_name text) OWNER TO postgres;

--
-- Name: fn_club_owner_has_a_player_wallet(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_owner_has_a_player_wallet() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_previous text := COALESCE(current_setting('app.club_membership_source', true), '');
BEGIN
  IF NEW.owner_id IS NULL OR COALESCE(NEW.is_union, false) THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND OLD.owner_id IS NOT DISTINCT FROM NEW.owner_id THEN
    RETURN NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM public.club_members cm
              WHERE cm.club_id = NEW.id AND cm.user_id = NEW.owner_id) THEN
    UPDATE public.club_members
       SET status = CASE WHEN COALESCE(status, 'active') IN ('active', 'approved') THEN status ELSE 'active' END,
           role   = CASE WHEN role IN ('owner', 'co_owner') THEN role ELSE 'owner' END,
           updated_at = now()
     WHERE club_id = NEW.id AND user_id = NEW.owner_id
       AND (COALESCE(status, 'active') NOT IN ('active', 'approved') OR role NOT IN ('owner', 'co_owner'));
    RETURN NULL;
  END IF;

  PERFORM set_config('app.club_membership_source', 'club_owner_create', true);
  PERFORM set_config('app.club_role_change', 'on', true);
  BEGIN
    INSERT INTO public.club_members (club_id, user_id, role, status, chip_balance)
    VALUES (NEW.id, NEW.owner_id, 'owner', 'active', 0)
    ON CONFLICT (club_id, user_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.club_membership_source', v_previous, true);
    RAISE;
  END;
  PERFORM set_config('app.club_membership_source', v_previous, true);
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_club_owner_has_a_player_wallet() OWNER TO postgres;

--
-- Name: fn_club_profit_conservation(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_profit_conservation(p_club_id uuid, p_date date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH exact AS (
    SELECT COALESCE(SUM((a.total_winnings - b.total_winnings)
                      - (a.total_losses  - b.total_losses)), 0) AS profit_sum,
           count(*) AS users
      FROM player_stats_snapshots b
      JOIN player_stats_snapshots a
        ON a.user_id = b.user_id AND a.club_id = b.club_id
       AND a.snapshot_date = p_date + 1
     WHERE b.snapshot_date = p_date AND b.club_id = p_club_id
  ),
  house AS (
    SELECT COALESCE(SUM(rake + bbj), 0) AS cut, count(*) AS days
      FROM club_hand_daily
     WHERE club_id = p_club_id AND stat_date = p_date
  ),
  dash AS (
    SELECT COALESCE(SUM(profit), 0) AS profit_sum
      FROM club_member_daily_stats
     WHERE club_id = p_club_id AND stat_date = p_date
  )
  SELECT jsonb_build_object(
    'club_id',                p_club_id,
    'stat_date',              p_date,
    'users',                  exact.users,
    'exact_profit_sum',       round(exact.profit_sum, 2),
    'dashboard_profit_sum',   round(dash.profit_sum, 2),
    'house_cut',              round(house.cut, 2),
    'exact_drift',            round(exact.profit_sum + house.cut, 2),
    'dashboard_drift',        round(dash.profit_sum  + house.cut, 2),
    'loss_to_win_ratio',      CASE WHEN house.cut <> 0
                                   THEN round(-exact.profit_sum / house.cut, 3) END,
    'tolerance',              round(GREATEST(abs(house.cut) * 0.02, 100), 2),
    'has_house_row',          (house.days > 0),
    'conserves',              house.days > 0
                              AND abs(exact.profit_sum + house.cut)
                                  <= GREATEST(abs(house.cut) * 0.02, 100)
  )
  FROM exact, house, dash;
$$;


ALTER FUNCTION public.fn_club_profit_conservation(p_club_id uuid, p_date date) OWNER TO postgres;

--
-- Name: fn_club_profit_drift(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_profit_drift(p_club_id uuid, p_date date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH dash AS (
    SELECT COALESCE(round(SUM(profit)::numeric, 2), 0) AS s
      FROM club_member_daily_stats WHERE club_id = p_club_id AND stat_date = p_date
  ), house AS (
    SELECT COALESCE(round((rake + bbj)::numeric, 2), 0) AS s
      FROM club_hand_daily WHERE club_id = p_club_id AND stat_date = p_date
  ), exact AS (
    SELECT COALESCE(round(SUM(exact_profit)::numeric, 2), 0) AS s
      FROM fn_club_member_daily_profit_exact(p_club_id, p_date)
  )
  SELECT jsonb_build_object(
    'club_id', p_club_id,
    'stat_date', p_date,
    'dashboard_player_profit', (SELECT s FROM dash),
    'exact_player_profit',     (SELECT s FROM exact),
    'house_cut',               (SELECT s FROM house),
    -- Both must satisfy: player profit + house cut = 0.
    'dashboard_drift', (SELECT s FROM dash)  + (SELECT s FROM house),
    'exact_drift',     (SELECT s FROM exact) + (SELECT s FROM house)
  );
$$;


ALTER FUNCTION public.fn_club_profit_drift(p_club_id uuid, p_date date) OWNER TO postgres;

--
-- Name: fn_club_promo_wallet_send(uuid, uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_promo_wallet_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text DEFAULT 'player_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor        uuid := auth.uid();
  v_actor_role   text;
  v_dest         text := lower(coalesce(p_destination, 'player_wallet'));
  v_op_id        uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior        record;
  v_pot_before   numeric;
  v_pot_after    numeric;
  v_to_role      text;
  v_to_after     numeric;
  v_agent_id     uuid;
  v_tx_id        uuid;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null or v_actor_role not in ('owner', 'co_owner', 'admin', 'super_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only An Owner, Co Owner, Admin Or Super Agent May Send From The Club Promo Wallet');
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false, 'error', 'Chips Move In Hundredths At Most');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Send Limit');
  end if;
  if v_dest not in ('player_wallet', 'agent_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Destination Wallet');
  end if;
  if p_to_user_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose A Recipient');
  end if;

  select coalesce(c.promo_balance, 0) into v_pot_before
    from clubs c where c.id = p_club_id for update;
  if v_pot_before is null then
    return jsonb_build_object('success', false, 'error', 'Club Not Found');
  end if;

  select id, amount, metadata into v_prior
    from chip_transactions
   where club_id = p_club_id
     and transaction_type = 'club_promo_send'
     and from_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'pot_after', (v_prior.metadata ->> 'pot_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric);
  end if;

  if v_pot_before < p_amount then
    return jsonb_build_object('success', false, 'error', 'Insufficient Club Promo Wallet Balance',
      'balance', v_pot_before, 'requested', p_amount);
  end if;

  select cm.role into v_to_role
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = p_to_user_id
     and coalesce(cm.status, 'active') in ('active', 'approved')
   for update;
  if v_to_role is null then
    return jsonb_build_object('success', false, 'error', 'Recipient Is Not An Active Member Of This Club');
  end if;
  if v_dest = 'agent_wallet'
     and v_to_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false, 'error', 'Only Staff Or Agents Hold A Promo Wallet');
  end if;
  if v_dest = 'player_wallet' and v_to_role = 'admin' then
    return jsonb_build_object('success', false, 'error', 'An Admin Does Not Hold A Player Wallet');
  end if;
  if p_to_user_id <> v_actor
     and not public.fn_club_cashier_can_transact(p_club_id, v_actor, p_to_user_id) then
    return jsonb_build_object('success', false, 'error', 'That Member Is Not In Your Downline');
  end if;

  perform public.fn_ca_declare_ledger('promo_send', 'promo_wallet', p_club_id, null,
    'club_promo_send:' || v_op_id::text, array['clubs']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  update clubs
     set promo_balance = coalesce(promo_balance, 0) - p_amount,
         updated_at = now()
   where id = p_club_id
   returning promo_balance into v_pot_after;

  if v_dest = 'player_wallet' then
    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount,
           updated_at = now()
     where club_id = p_club_id and user_id = p_to_user_id
     returning chip_balance into v_to_after;
  else
    v_agent_id := public.fn_ensure_agent_row(p_club_id, p_to_user_id, v_to_role);
    if v_agent_id is null then
      raise exception 'could not ensure agents row for % in club %', p_to_user_id, p_club_id;
    end if;
    update agents
       set promo_wallet_balance = coalesce(promo_wallet_balance, 0) + p_amount,
           updated_at = now()
     where id = v_agent_id
     returning promo_wallet_balance into v_to_after;
  end if;
  if v_to_after is null then
    raise exception 'club promo credit landed nowhere for % in %', p_to_user_id, p_club_id;
  end if;
  perform set_config('app.ledger_autoskip_clubs', '', true);

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (p_club_id, v_actor, p_to_user_id, p_amount, 'club_promo_send',
     coalesce(nullif(btrim(p_reason), ''), 'Club Promo Wallet Send'),
     jsonb_build_object(
       'op_id', v_op_id,
       'destination', v_dest,
       'source', 'club_promo_wallet',
       'actor_role', v_actor_role,
       'recipient_role', v_to_role,
       'pot_before', v_pot_before,
       'pot_after', v_pot_after,
       'recipient_balance_after', v_to_after),
     v_pot_after)
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true, 'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', p_amount,
    'destination', v_dest,
    'pot_before', v_pot_before,
    'pot_after', v_pot_after,
    'recipient_balance_after', v_to_after);
end
$$;


ALTER FUNCTION public.fn_club_promo_wallet_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_promo_wallet_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_promo_wallet_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid) IS 'Spends clubs.promo_balance (the club Promo Wallet) into a member player wallet (as cash) or an agent promo float. Club Bank roles only. fn_promo_wallet_send is the AGENT''S own float; this is the CLUB''S pot.';


--
-- Name: fn_club_rake_rollup_catchup(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_rake_rollup_catchup(p_days integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '600s'
    AS $$
DECLARE
  rec record; d date;
  v_days int := 0; v_rows int := 0; v_fail int := 0; v_gaps int := 0;
  v_ctd jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_platform_admin())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  FOR rec IN
    SELECT DISTINCT club_id FROM union_clubs
    UNION
    SELECT DISTINCT r.club_id FROM rake_records r
     WHERE r.club_id IS NOT NULL
       AND r.created_at >= current_date - GREATEST(p_days,1) - 1
  LOOP
    FOR d IN
      SELECT gs::date FROM generate_series(
               current_date - GREATEST(p_days,1), current_date - 1, interval '1 day') gs
    LOOP
      IF EXISTS (SELECT 1 FROM club_rake_rollup_complete
                  WHERE club_id = rec.club_id AND day = d) THEN
        CONTINUE;
      END IF;
      BEGIN
        v_rows := v_rows + public.fn_club_rake_rollup_day(rec.club_id, d);
        v_days := v_days + 1;
      EXCEPTION WHEN OTHERS THEN
        v_fail := v_fail + 1;
      END;
    END LOOP;
  END LOOP;

  SELECT count(*) INTO v_gaps
    FROM (SELECT DISTINCT club_id AS cid FROM rake_records
           WHERE created_at >= current_date - GREATEST(p_days,1) - 1
             AND club_id IS NOT NULL) src
    CROSS JOIN generate_series(current_date - GREATEST(p_days,1),
                               current_date - 1, interval '1 day') g
   WHERE NOT EXISTS (SELECT 1 FROM club_rake_rollup_complete rc
                      WHERE rc.club_id = src.cid AND rc.day = g::date);

  IF v_gaps > 0 THEN
    INSERT INTO financial_alerts (severity, source, message, context)
    VALUES ('warning', 'fn_club_rake_rollup_catchup',
            'Club rake rollup has uncovered days - the live downline view is falling back to full scans',
            jsonb_build_object('gap_club_days', v_gaps, 'lookback_days', p_days,
                               'failures', v_fail, 'ran_at', now()));
  END IF;

  -- Club Data screen rollup. Additive; never allowed to break the above.
  BEGIN
    v_ctd := public.fn_club_table_daily_catchup(2);
  EXCEPTION WHEN OTHERS THEN
    v_ctd := jsonb_build_object('success', false, 'error', SQLERRM);
  END;

  RETURN jsonb_build_object('days_built', v_days, 'rows', v_rows,
                            'failures', v_fail, 'remaining_gaps', v_gaps,
                            'club_table_daily', v_ctd,
                            'ran_at', now());
END $$;


ALTER FUNCTION public.fn_club_rake_rollup_catchup(p_days integer) OWNER TO postgres;

--
-- Name: fn_club_rake_rollup_day(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_rake_rollup_day(p_club_id uuid, p_day date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start timestamptz := p_day::timestamptz;
  v_end   timestamptz := (p_day + 1)::timestamptz;
  v_rows  integer := 0;
BEGIN
  IF v_end > date_trunc('day', now()) THEN
    RAISE EXCEPTION 'club rake rollup: day % is not complete', p_day;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('club_rake_rollup:' || p_club_id::text || ':' || p_day::text, 42));

  DELETE FROM club_rake_daily_user WHERE club_id = p_club_id AND day = p_day;

  WITH split AS (
    SELECT a.player_id AS user_id, round(a.rake_amount * 100)::bigint AS cents
      FROM rake_attributions a
     WHERE a.club_id = p_club_id
       AND a.created_at >= v_start AND a.created_at < v_end
       AND a.rake_amount > 0
  ), ins AS (
    INSERT INTO club_rake_daily_user (club_id, day, user_id, rake_amount, hands)
    SELECT p_club_id, p_day, s.user_id, SUM(s.cents)::numeric / 100, count(*)
      FROM split s GROUP BY s.user_id
    RETURNING 1
  )
  SELECT count(*) INTO v_rows FROM ins;

  INSERT INTO club_rake_rollup_complete (club_id, day, rows_written, computed_at)
  VALUES (p_club_id, p_day, v_rows, now())
  ON CONFLICT (club_id, day) DO UPDATE
    SET rows_written = EXCLUDED.rows_written, computed_at = EXCLUDED.computed_at;

  RETURN v_rows;
END $$;


ALTER FUNCTION public.fn_club_rake_rollup_day(p_club_id uuid, p_day date) OWNER TO postgres;

--
-- Name: fn_club_rakeback_margin_violations(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_rakeback_margin_violations(p_club_id uuid) RETURNS TABLE(rule text, upline_user_id uuid, upline_role text, upline_rate numeric, downline_user_id uuid, downline_role text, downline_rate numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- manager -> manager edges (agents table is what commissions read)
  SELECT 'manager_margin_under_10'::text,
         p.user_id, p.role, p.commission_rate,
         c.user_id, c.role, c.commission_rate
    FROM agents c JOIN agents p ON p.id = c.parent_agent_id
   WHERE c.club_id = p_club_id AND p.club_id = p_club_id
     AND (p.commission_rate - c.commission_rate) < 0.10

  UNION ALL
  -- manager -> player edges
  SELECT 'player_margin_under_10',
         a.user_id, a.role, a.commission_rate,
         cm.user_id, cm.role, cm.rakeback_rate
    FROM club_members cm
    JOIN agents a ON a.user_id = cm.agent_id AND a.club_id = cm.club_id
   WHERE cm.club_id = p_club_id AND cm.role = 'player'
     AND (a.commission_rate - cm.rakeback_rate) < 0.10

  UNION ALL
  -- nobody below the 10% floor
  SELECT 'player_below_10_percent',
         a.user_id, a.role, a.commission_rate,
         cm.user_id, cm.role, cm.rakeback_rate
    FROM club_members cm
    LEFT JOIN agents a ON a.user_id = cm.agent_id AND a.club_id = cm.club_id
   WHERE cm.club_id = p_club_id AND cm.role = 'player'
     AND cm.rakeback_rate < 0.10

  UNION ALL
  -- super agent direct players capped at 50%
  SELECT 'sa_direct_player_over_50',
         a.user_id, a.role, a.commission_rate,
         cm.user_id, cm.role, cm.rakeback_rate
    FROM club_members cm
    JOIN agents a ON a.user_id = cm.agent_id AND a.club_id = cm.club_id
   WHERE cm.club_id = p_club_id AND cm.role = 'player'
     AND a.role = 'super_agent' AND cm.rakeback_rate > 0.50

  UNION ALL
  -- a player with no resolvable upline is outside the ladder entirely
  SELECT 'player_without_upline',
         NULL::uuid, NULL::text, NULL::numeric,
         cm.user_id, cm.role, cm.rakeback_rate
    FROM club_members cm
   WHERE cm.club_id = p_club_id AND cm.role = 'player'
     AND (cm.agent_id IS NULL OR NOT EXISTS (
           SELECT 1 FROM agents a
            WHERE a.user_id = cm.agent_id AND a.club_id = cm.club_id))
$$;


ALTER FUNCTION public.fn_club_rakeback_margin_violations(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_rakeback_margin_violations(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_rakeback_margin_violations(p_club_id uuid) IS 'Rakeback ladder violations for one club. SERVICE ROLE ONLY - it returns every agent commission_rate and every player rakeback_rate in the club, which is the club''s whole rate card. Do not grant this to authenticated without writing a guard first.';


--
-- Name: fn_club_retirement_impact(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_retirement_impact(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_members bigint := 0;
  v_running bigint := 0;
  v_tournaments bigint := 0;
  v_wallet numeric := 0;
  v_diamonds numeric := 0;
  v_inventory bigint := 0;
  v_open bigint := 0;
  v_union boolean := false;
  v_retired boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT c.owner_id, c.lifecycle_status = 'retired'
    INTO v_owner, v_retired
    FROM public.clubs c WHERE c.id = p_club_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Club not found'; END IF;
  IF v_owner IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'Only the club owner can inspect retirement impact';
  END IF;

  SELECT count(*) INTO v_members FROM public.club_members WHERE club_id = p_club_id;
  SELECT count(*) INTO v_running
    FROM public.tables t
   WHERE t.club_id = p_club_id
     AND coalesce(t.is_deleted, false) = false
     AND lower(coalesce(t.status::text, '')) NOT IN ('closed', 'deleted');

  SELECT count(*) INTO v_tournaments
    FROM public.tournaments t
   WHERE t.club_id = p_club_id
     AND lower(coalesce(t.status::text, '')) NOT IN ('completed', 'cancelled', 'canceled');

  SELECT
    EXISTS (SELECT 1 FROM public.unions u WHERE u.id = p_club_id)
    OR EXISTS (SELECT 1 FROM public.union_clubs uc WHERE uc.club_id = p_club_id)
    OR EXISTS (SELECT 1 FROM public.clubs c
                WHERE c.id = p_club_id
                  AND (c.union_id IS NOT NULL
                    OR coalesce((to_jsonb(c) ->> 'is_union')::boolean, false)))
    INTO v_union;

  SELECT coalesce(abs(c.chip_treasury), 0) + coalesce(abs(c.chip_pool), 0)
       + coalesce(abs(c.promo_balance), 0) + coalesce(abs(c.insurance_balance), 0)
    INTO v_wallet FROM public.clubs c WHERE c.id = p_club_id;

  SELECT v_wallet + coalesce(sum(
           abs(coalesce(cm.chip_balance, 0)) + abs(coalesce(cm.held_chips, 0))
         + abs(coalesce(cm.locked_chips, 0)) + abs(coalesce(cm.promo_balance, 0))
         + abs(coalesce(cm.credit_used, 0))), 0)
    INTO v_wallet FROM public.club_members cm WHERE cm.club_id = p_club_id;

  SELECT v_wallet + coalesce(sum(
           abs(coalesce(a.agent_wallet_balance, 0))
         + abs(coalesce(a.promo_wallet_balance, 0))
         + abs(coalesce(a.credit_used, 0))), 0)
    INTO v_wallet FROM public.agents a WHERE a.club_id = p_club_id;

  SELECT v_wallet + coalesce(sum(
           abs(coalesce(w.chip_balance, 0))), 0)
    INTO v_wallet FROM public.club_wallets w WHERE w.club_id = p_club_id;
  SELECT v_wallet + coalesce(sum(
           abs(coalesce(b.main_balance, 0)) + abs(coalesce(b.backup_balance, 0))
         + abs(coalesce(b.promo_balance, 0))), 0)
    INTO v_wallet FROM public.bbj_pools b WHERE b.club_id = p_club_id;
  SELECT v_wallet + coalesce(sum(abs(coalesce(s.balance, 0))), 0)
    INTO v_wallet FROM public.spin_bonus_pools s WHERE s.club_id = p_club_id;
  SELECT v_wallet + coalesce(sum(abs(coalesce(ts.stack, 0))), 0)
    INTO v_wallet
    FROM public.table_seats ts JOIN public.tables t ON t.id = ts.table_id
   WHERE t.club_id = p_club_id
     AND t.tournament_id IS NULL
     AND ts.left_at IS NULL;
  SELECT v_wallet + coalesce(sum(abs(coalesce(h.amount, 0))), 0)
    INTO v_wallet FROM public.chip_escrow_holds h
   WHERE h.club_id = p_club_id AND h.status = 'held';
  SELECT v_wallet + coalesce(sum(abs(coalesce(ce.amount, 0))), 0)
    INTO v_wallet
    FROM public.chip_escrow ce
    JOIN public.cashout_requests cr ON cr.id = ce.cashout_request_id
   WHERE cr.club_id = p_club_id AND ce.released_at IS NULL;
  SELECT v_wallet + coalesce(sum(abs(coalesce(tt.value, 0))), 0)
    INTO v_wallet FROM public.tournament_tickets tt
   WHERE tt.club_id = p_club_id AND tt.status = 'issued';

  -- Tournament chip stacks are game units, not a second cash balance. The
  -- canonical liability is the enforced escrow balance, falling back to the
  -- legacy counters only where no escrow row exists yet.
  SELECT v_wallet + coalesce(sum(abs(coalesce(
           te.prize_balance + te.bounty_balance + te.fee_balance,
           coalesce(tr.prize_pool, 0) + coalesce(tr.bounty_pool, 0)
             - coalesce(tr.bounty_pool_paid, 0) + coalesce(tr.total_rake, 0)
         ))), 0)
    INTO v_wallet
    FROM public.tournaments tr
    LEFT JOIN public.tournament_escrow te ON te.tournament_id = tr.id
   WHERE tr.club_id = p_club_id
     AND lower(coalesce(tr.status::text, '')) NOT IN ('completed', 'cancelled', 'canceled');

  SELECT v_wallet + coalesce(sum(abs(coalesce(s.leaderboard_seed_remaining, 0))), 0)
    INTO v_wallet FROM public.club_opening_setups s WHERE s.club_id = p_club_id;

  SELECT coalesce(sum(abs(coalesce(w.balance, 0))), 0)
    INTO v_diamonds FROM public.club_diamond_wallets w WHERE w.club_id = p_club_id;
  SELECT v_diamonds + coalesce(sum(abs(coalesce(cm.diamonds, 0))), 0)
    INTO v_diamonds FROM public.club_members cm WHERE cm.club_id = p_club_id;
  SELECT coalesce(sum(coalesce(i.quantity, 0)), 0)
    INTO v_inventory FROM public.promo_vault_inventory i WHERE i.club_id = p_club_id;

  SELECT
      (SELECT count(*) FROM public.cashout_requests cr
        WHERE cr.club_id = p_club_id AND cr.status IN ('pending', 'approved'))
    + (SELECT count(*) FROM public.chip_requests r
        WHERE r.club_id = p_club_id AND r.status = 'pending')
    + (SELECT count(*) FROM public.chip_escrow_holds h
        WHERE h.club_id = p_club_id AND h.status = 'held')
    + (SELECT count(*)
         FROM public.chip_escrow ce
         JOIN public.cashout_requests cr ON cr.id = ce.cashout_request_id
        WHERE cr.club_id = p_club_id AND ce.released_at IS NULL)
    + (SELECT count(*) FROM public.tournament_tickets tt
        WHERE tt.club_id = p_club_id AND tt.status = 'issued')
    + (SELECT count(*) FROM public.settlement_periods sp
        WHERE sp.club_id = p_club_id
          AND lower(coalesce(sp.status::text, '')) IN ('open', 'processing', 'disputed'))
    + (SELECT count(*)
         FROM public.credit_invoices ci JOIN public.agents a ON a.id = ci.agent_id
        WHERE a.club_id = p_club_id
          AND lower(coalesce(ci.status::text, '')) IN ('pending', 'partial', 'overdue', 'disputed'))
    + (SELECT count(*)
         FROM public.table_seats ts JOIN public.tables t ON t.id = ts.table_id
        WHERE t.club_id = p_club_id AND ts.left_at IS NULL)
    + (SELECT count(*)
         FROM public.tournament_players tp
         JOIN public.tournaments tr ON tr.id = tp.tournament_id
        WHERE tr.club_id = p_club_id
          AND lower(coalesce(tp.status::text, '')) IN ('registered', 'playing'))
    + v_tournaments
    INTO v_open;

  RETURN jsonb_build_object(
    'members', v_members,
    'running_tables', v_running,
    'active_tournaments', v_tournaments,
    'wallet_chips', coalesce(v_wallet, 0),
    'diamonds', coalesce(v_diamonds, 0),
    'inventory_items', coalesce(v_inventory, 0),
    'open_obligations', v_open,
    'union_affiliated', v_union,
    'already_retired', v_retired
  );
END
$$;


ALTER FUNCTION public.fn_club_retirement_impact(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_club_role(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_role(p_user_id uuid, p_club_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
           WHEN EXISTS (SELECT 1 FROM clubs c
                         WHERE c.id = p_club_id AND c.owner_id = p_user_id) THEN 'owner'
           ELSE (SELECT m.role FROM club_members m
                  WHERE m.user_id = p_user_id AND m.club_id = p_club_id
                  LIMIT 1)
         END;
$$;


ALTER FUNCTION public.fn_club_role(p_user_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_club_role_rank(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_role_rank(p_role text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT CASE p_role
    WHEN 'owner'       THEN 100
    WHEN 'co_owner'    THEN 90
    WHEN 'admin'       THEN 80
    WHEN 'super_agent' THEN 60
    WHEN 'agent'       THEN 40
    WHEN 'sub_agent'   THEN 20
    WHEN 'player'      THEN 0
    ELSE -1
  END;
$$;


ALTER FUNCTION public.fn_club_role_rank(p_role text) OWNER TO postgres;

--
-- Name: fn_club_scope_ids(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_scope_ids(p_club_id uuid) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN coalesce((SELECT is_union FROM public.clubs WHERE id = p_club_id), false)
      THEN (
        SELECT array_agg(DISTINCT x)
        FROM (
          SELECT p_club_id AS x
          UNION SELECT id      FROM public.clubs       WHERE union_id = p_club_id
          UNION SELECT club_id FROM public.union_clubs WHERE union_id = p_club_id
        ) s
        WHERE x IS NOT NULL
      )
    ELSE ARRAY[p_club_id]
  END;
$$;


ALTER FUNCTION public.fn_club_scope_ids(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_scope_ids(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_scope_ids(p_club_id uuid) IS 'Clubs a roster covers: a union covers itself plus every club under it; a club covers only itself.';


--
-- Name: fn_club_scoped_chips_enabled(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_scoped_chips_enabled() RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  -- Retired switch: Club Arena is always club-scoped. Kept so existing guards
  -- and self-tests continue to compile and read true.
  SELECT true;
$$;


ALTER FUNCTION public.fn_club_scoped_chips_enabled() OWNER TO postgres;

--
-- Name: fn_club_set_member_role(uuid, uuid, text, uuid, numeric, numeric, boolean, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_set_member_role(p_club_id uuid, p_user_id uuid, p_role text, p_actor_user_id uuid DEFAULT NULL::uuid, p_commission_rate numeric DEFAULT NULL::numeric, p_player_rakeback_rate numeric DEFAULT NULL::numeric, p_is_prepaid boolean DEFAULT NULL::boolean, p_credit_limit numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor      uuid;
  v_old_role   text;
  v_actor_role text;
  v_allowed    text[];
  v_downline   int;
  v_agent_id   uuid;
  v_parent     uuid;
  v_set_upline boolean := false;
  v_is_agent   boolean;
  v_is_staff   boolean;
  v_comm       numeric;
  v_rake       numeric;
  v_prepaid    boolean;
  v_limit      numeric;
  v_have_row   boolean := false;
  v_fresh      boolean;
  v_cap_comm   numeric;
  v_cap_rake   numeric;
  v_cap_limit  numeric;
  v_float      numeric;
  v_owed       numeric;
  v_commission numeric;
  v_keeps_wallet boolean;
  v_club_name  text;
  v_label      text;
BEGIN
  -- IDENTITY. auth.uid() is the ONLY identity a browser can establish; it is
  -- NULL for anon, and a NULL here used to mean "believe p_actor_user_id".
  -- A caller-supplied actor is now accepted from a trusted backend only.
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    IF COALESCE(auth.role(), 'service_role') = 'service_role'
       AND p_actor_user_id IS NOT NULL THEN
      v_actor := p_actor_user_id;
    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'actor identity required');
    END IF;
  END IF;

  IF p_role IS NULL OR p_role NOT IN
     ('co_owner','admin','super_agent','agent','sub_agent','player') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid role: ' || COALESCE(p_role,'null'));
  END IF;

  v_is_agent := p_role IN ('super_agent','agent','sub_agent');
  v_is_staff := p_role IN ('co_owner','admin');

  IF NOT v_is_agent
     AND (COALESCE(p_commission_rate, 0) <> 0 OR COALESCE(p_player_rakeback_rate, 0) <> 0) THEN
    RETURN jsonb_build_object('success', false,
      'error', CASE WHEN v_is_staff
                    THEN 'co owners and admins receive no rakeback, so no rate may be set for one'
                    ELSE 'only an agent role carries a commission or rakeback rate' END);
  END IF;

  -- Funding belongs to an agent role. Sending it with a demotion to player, or
  -- with a promotion to staff, is a caller mistake worth naming rather than
  -- quietly ignoring: it usually means the wrong role reached this call.
  IF NOT v_is_agent AND (p_is_prepaid IS NOT NULL OR p_credit_limit IS NOT NULL) THEN
    RETURN jsonb_build_object('success', false,
      'error', 'only an agent role is funded prepaid or on a credit line');
  END IF;

  SELECT role INTO v_old_role FROM club_members
   WHERE club_id = p_club_id AND user_id = p_user_id
     AND status IN ('active','approved')
   FOR UPDATE;

  IF v_old_role IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'target is not a member of this club');
  END IF;

  IF v_old_role = p_role THEN
    RETURN jsonb_build_object('success', true, 'unchanged', true, 'role', p_role);
  END IF;

  v_allowed := fn_club_grantable_roles(p_club_id, v_actor, p_user_id);
  IF NOT (p_role = ANY (v_allowed)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not permitted to set this role',
      'allowed', COALESCE(to_jsonb(v_allowed), '[]'::jsonb));
  END IF;

  SELECT role INTO v_actor_role FROM club_members
   WHERE club_id = p_club_id AND user_id = v_actor AND status IN ('active','approved');

  IF fn_club_role_rank(v_old_role) > fn_club_role_rank(p_role)
     AND v_old_role IN ('super_agent','agent','sub_agent') THEN
    SELECT count(*) INTO v_downline FROM club_members
     WHERE club_id = p_club_id AND agent_id = p_user_id;
    IF v_downline > 0 THEN
      RETURN jsonb_build_object('success', false,
        'error', 'this member still has ' || v_downline || ' player'
                 || CASE WHEN v_downline = 1 THEN '' ELSE 's' END
                 || ' reporting to them. Move them to another agent first.',
        'downline_count', v_downline);
    END IF;
  END IF;

  v_set_upline := v_actor_role IN ('super_agent','agent')
                  AND p_role IN ('agent','sub_agent');

  -- ---------------------------------------------------------------------------
  -- A DEMOTION MUST NOT STRAND MONEY
  -- ---------------------------------------------------------------------------
  -- Every role except 'player' may hold an agent wallet - Dan, 2026-08-31:
  -- "OWNERS AND CO OWNERS CAN AND SHOULD HAVE AGENT WALLETS." So moving an
  -- agent up to co-owner, or sideways to another agent tier, strands nothing:
  -- the wallet goes with them and they can still spend it.
  --
  -- Becoming a PLAYER is the one move that takes the wallet away.
  -- fn_club_bank_role then returns 'player', fn_agent_wallet_send refuses them
  -- outright, and fn_agent_wallet_claim_back with it - so whatever the row still
  -- holds becomes chips nobody can move and nobody is watching. 67 of the 111
  -- active agents hold float today, 6,726,000 chips between them.
  --
  -- The remedy already exists and is named in the refusal:
  -- fn_club_bank_claim_back pulls the float back into the club bank, keyed on an
  -- op_id and written to the ledger, and any owner, co-owner, admin or super
  -- agent may run it. A debt is not sweepable and must be settled instead -
  -- fn_apply_credit_payment pays credit_used down when the invoice is paid.
  v_keeps_wallet := p_role <> 'player';

  -- PHASE 7. What the club still owes this person, from the ledger the claim
  -- path settles - rather than from the agents column that migration drops,
  -- which nothing ever wrote. It said 26,859.87 across 5 agents on a day the
  -- ledger held 408,809.59 across 114, so 109 of those 114 were reported to the
  -- person changing their role as owed nothing at all. One partial-index lookup
  -- (agent_commissions_unsettled_idx).
  -- reads the ledger directly: this function has already authorized its
  -- actor through fn_club_grantable_roles above, and it is SECURITY DEFINER,
  -- so it does not need the guarded caller-facing RPC's door. That RPC now
  -- admits only self, club admin and above, an agent ancestor, or the
  -- service role, and THIS report must not be able to fail on it. Same
  -- SELECT, same partial index (agent_commissions_unsettled_idx).
  SELECT COALESCE(SUM(ac.amount), 0)::numeric INTO v_commission
    FROM public.agent_commissions ac
   WHERE ac.club_id = p_club_id
     AND ac.user_id = p_user_id
     AND ac.settled_at IS NULL AND NOT public.fn_agent_commission_paid_by_period(ac.club_id, ac.user_id, ac.created_at);

  -- v_old_role was checked against the three AGENT tiers here, which missed the
  -- people phase 2 deliberately gave wallets to. A co-owner or an admin holds an
  -- agent wallet by design - Dan: "OWNERS AND CO OWNERS CAN AND SHOULD HAVE
  -- AGENT WALLETS" - so demoting one straight to player took the wallet away
  -- with the float still in it, which is the exact defect this phase exists to
  -- stop. Any role that is not already 'player' can be holding one.
  IF NOT v_keeps_wallet AND v_old_role <> 'player' THEN
    SELECT COALESCE(a.agent_wallet_balance, 0), COALESCE(a.credit_used, 0)
      INTO v_float, v_owed
      FROM agents a
     WHERE a.club_id = p_club_id AND a.user_id = p_user_id;

    IF COALESCE(v_float, 0) > 0 OR COALESCE(v_owed, 0) > 0 THEN
      -- Name only what is actually outstanding. "holds 5,000 chips and owes
      -- 0.00" invites somebody to go looking for a debt that is not there.
      RETURN jsonb_build_object('success', false, 'needs_settlement', true,
        'error', 'this member cannot become a player yet: '
                 || CASE WHEN COALESCE(v_float, 0) > 0 AND COALESCE(v_owed, 0) > 0
                         THEN 'their agent wallet still holds '
                              || trim(to_char(v_float, 'FM999,999,999,990.00'))
                              || ' chips, and they still owe '
                              || trim(to_char(v_owed, 'FM999,999,999,990.00'))
                              || '. Claim the chips back into the club bank and settle the debt first.'
                         WHEN COALESCE(v_float, 0) > 0
                         THEN 'their agent wallet still holds '
                              || trim(to_char(v_float, 'FM999,999,999,990.00'))
                              || ' chips. Claim them back into the club bank first, '
                              || 'because a player cannot spend an agent wallet.'
                         ELSE 'they still owe '
                              || trim(to_char(v_owed, 'FM999,999,999,990.00'))
                              || ' on their credit line. Settle the invoice first.'
                    END,
        'agent_wallet_balance', COALESCE(v_float, 0),
        'credit_used', COALESCE(v_owed, 0),
        'unclaimed_commission', COALESCE(v_commission, 0));
    END IF;
  END IF;

  IF v_is_agent THEN
    SELECT a.commission_rate, a.player_rakeback_rate, a.is_prepaid, a.credit_limit
      INTO v_comm, v_rake, v_prepaid, v_limit
      FROM agents a
     WHERE a.club_id = p_club_id AND a.user_id = p_user_id;
    v_have_row := FOUND;

    -- B-01, Dan 2026-08-31: FORCE A FRESH CHOICE.
    --
    -- A member whose current club role is not an agent tier is being PROMOTED.
    -- Their agents row may still hold the commission, rakeback and credit line
    -- they carried before they were demoted, and a commercial term nobody has
    -- re-agreed does not come back by default - "getting this wrong costs
    -- money" was the whole of the question put to Dan. So on a promotion every
    -- term is taken from this call and from nowhere else.
    --
    -- Re-GRADING an existing agent (agent to super agent) is a different act:
    -- their terms are live, not stale, and carrying them forward when the
    -- caller sends nothing is what every existing caller already relies on.
    v_fresh := v_old_role NOT IN ('super_agent','agent','sub_agent');

    IF v_fresh THEN
      v_comm    := p_commission_rate;
      v_rake    := p_player_rakeback_rate;
      v_prepaid := p_is_prepaid;
      v_limit   := p_credit_limit;
    ELSE
      v_comm    := COALESCE(p_commission_rate, v_comm);
      v_rake    := COALESCE(p_player_rakeback_rate, v_rake);
      v_prepaid := COALESCE(p_is_prepaid, v_prepaid);
      v_limit   := COALESCE(p_credit_limit, v_limit);
    END IF;

    IF v_comm IS NULL OR v_rake IS NULL THEN
      RETURN jsonb_build_object('success', false, 'needs_rates', true,
        'error', 'a commission rate and a player rakeback rate must be chosen when granting an agent role');
    END IF;
    IF v_comm < 0 OR v_comm > 0.70 THEN
      RETURN jsonb_build_object('success', false, 'error', 'the commission rate must be between 0 and 0.70');
    END IF;
    IF v_rake < 0 OR v_rake > 0.50 THEN
      RETURN jsonb_build_object('success', false, 'error', 'the player rakeback rate must be between 0 and 0.50');
    END IF;
    IF v_rake > v_comm THEN
      RETURN jsonb_build_object('success', false,
        'error', 'the player rakeback rate cannot exceed the commission rate it is paid out of');
    END IF;

    -- Dan, 2026-08-31: "WHEN A AGENT IS PROMOTED ... THEY ALSO NEED TO BE
    -- ASSIGNED 'PRE PAID' OR CREDIT LINE, (AND IF SO, THEN HOW MUCH)".
    -- Before this, every promotion hardcoded credit_limit 0 and left is_prepaid
    -- at its column default of false, which is the one combination that can
    -- send nothing at all: not prepaid, and no line to draw on. Three agents
    -- are in exactly that state on production today.
    IF v_prepaid IS NULL THEN
      RETURN jsonb_build_object('success', false, 'needs_funding', true,
        'error', 'choose prepaid or a credit line when granting an agent role');
    END IF;
    IF v_prepaid THEN
      IF COALESCE(v_limit, 0) <> 0 THEN
        RETURN jsonb_build_object('success', false,
          'error', 'a prepaid agent carries no credit line, so the limit must be 0');
      END IF;
      v_limit := 0;
    ELSE
      IF v_limit IS NULL THEN
        RETURN jsonb_build_object('success', false, 'needs_funding', true,
          'error', 'a credit agent needs a credit limit');
      END IF;
      IF v_limit <= 0 THEN
        RETURN jsonb_build_object('success', false,
          'error', 'a credit line must be greater than 0, or the agent should be prepaid');
      END IF;
    END IF;

    IF v_set_upline THEN
      SELECT id, commission_rate, player_rakeback_rate, credit_limit
        INTO v_parent, v_cap_comm, v_cap_rake, v_cap_limit
        FROM agents WHERE club_id = p_club_id AND user_id = v_actor;
    ELSIF v_have_row THEN
      SELECT p.commission_rate, p.player_rakeback_rate, p.credit_limit
        INTO v_cap_comm, v_cap_rake, v_cap_limit
        FROM agents a JOIN agents p ON p.id = a.parent_agent_id
       WHERE a.club_id = p_club_id AND a.user_id = p_user_id;
    END IF;

    IF v_cap_comm IS NOT NULL AND v_comm > v_cap_comm THEN
      RETURN jsonb_build_object('success', false,
        'error', 'the commission rate cannot exceed the upline rate of ' || v_cap_comm);
    END IF;
    IF v_cap_rake IS NOT NULL AND v_rake > v_cap_rake THEN
      RETURN jsonb_build_object('success', false,
        'error', 'the player rakeback rate cannot exceed the upline rate of ' || v_cap_rake);
    END IF;
    -- An upline cannot lend downward what it does not itself hold.
    IF v_cap_limit IS NOT NULL AND v_limit > v_cap_limit THEN
      RETURN jsonb_build_object('success', false,
        'error', 'the credit limit cannot exceed the upline limit of ' || v_cap_limit);
    END IF;
  END IF;

  PERFORM set_config('app.club_role_change', 'on', true);

  UPDATE club_members
     SET role                = p_role,
         agent_id            = CASE WHEN v_set_upline THEN v_actor ELSE agent_id END,
         player_rakeback_pct = CASE WHEN v_is_staff THEN 0 ELSE player_rakeback_pct END,
         rakeback_rate       = CASE WHEN v_is_staff THEN 0 ELSE rakeback_rate END,
         commission_rate     = CASE WHEN v_is_staff THEN 0 ELSE commission_rate END,
         updated_at          = now()
   WHERE club_id = p_club_id AND user_id = p_user_id;

  PERFORM set_config('app.club_role_change', '', true);

  IF v_is_agent THEN
    SELECT id INTO v_agent_id FROM agents
     WHERE club_id = p_club_id AND user_id = p_user_id;

    IF v_agent_id IS NOT NULL THEN
      UPDATE agents
         SET role = p_role, status = 'active',
             parent_agent_id = COALESCE(v_parent, parent_agent_id),
             commission_rate = v_comm, player_rakeback_rate = v_rake,
             is_prepaid = v_prepaid, credit_limit = v_limit,
             updated_at = now()
       WHERE id = v_agent_id;
    ELSE
      INSERT INTO agents (club_id, user_id, role, status, parent_agent_id,
                          commission_rate, player_rakeback_rate,
                          is_prepaid, credit_limit, credit_used)
      VALUES (p_club_id, p_user_id, p_role, 'active', v_parent, v_comm, v_rake,
              v_prepaid, v_limit, 0)
      RETURNING id INTO v_agent_id;
    END IF;
  ELSE
    -- Suspend the row only when the member can no longer hold a wallet. A
    -- promotion to co-owner or admin used to suspend it too, which contradicted
    -- the rule that staff hold agent wallets and left the club bank funding a
    -- row marked inactive.
    -- Active while they can hold a wallet, suspended when they cannot. Keyed on
    -- the role they are BECOMING, for the same reason the guard above is: a
    -- co-owner demoted to player left an ACTIVE agents row behind, so a player
    -- still read as an agent - fn_player_rakeback_rate joins that row on
    -- status = 'active'.
    UPDATE agents
       SET status = CASE WHEN p_role = 'player' AND v_old_role <> 'player'
                         THEN 'suspended' ELSE status END,
           commission_rate      = CASE WHEN v_is_staff THEN 0 ELSE commission_rate END,
           player_rakeback_rate = CASE WHEN v_is_staff THEN 0 ELSE player_rakeback_rate END,
           updated_at = now()
     WHERE club_id = p_club_id AND user_id = p_user_id;
  END IF;

  INSERT INTO audit_trail (actor_id, actor_role, action, target_type, target_id,
                           club_id, before_state, after_state, reason)
  VALUES (v_actor, COALESCE(v_actor_role, 'platform_admin'), 'set_member_role',
          'club_member', p_user_id, p_club_id,
          jsonb_build_object('role', v_old_role),
          jsonb_build_object('role', p_role, 'upline_set', v_set_upline,
                             'commission_rate', v_comm, 'player_rakeback_rate', v_rake,
                             'is_prepaid', v_prepaid, 'credit_limit', v_limit,
                             'funding_rechosen', COALESCE(v_fresh, false)),
          'Role changed via fn_club_set_member_role');

  -- ---------------------------------------------------------------------------
  -- TELL THE PERSON IT HAPPENED
  -- ---------------------------------------------------------------------------
  -- Until now the only announcement was masterBus.emit('MEMBER_ROLE_CHANGED'),
  -- a browser-local event. It reaches the tabs of whoever performed the change
  -- and nobody else, so the person whose role actually changed found out when a
  -- button appeared or vanished. notifications is the estate's real channel:
  -- 11,362 rows, four RLS policies, rendered by NotificationDropdown, the
  -- header store and NotificationsPage.
  --
  -- Failing to notify must never fail the role change. The role is the fact;
  -- the notice is a courtesy, and a courtesy that can roll back a promotion is
  -- worse than no courtesy at all.
  SELECT name INTO v_club_name FROM clubs WHERE id = p_club_id;
  v_label := CASE p_role
               WHEN 'co_owner' THEN 'Co Owner'
               WHEN 'admin' THEN 'Admin'
               WHEN 'super_agent' THEN 'Super Agent'
               WHEN 'agent' THEN 'Agent'
               WHEN 'sub_agent' THEN 'Sub Agent'
               ELSE 'Player'
             END;
  BEGIN
    PERFORM public.fn_raise_notification(
      p_user_id,
      'club_role_changed',
      'Your Role Changed In ' || COALESCE(v_club_name, 'Your Club'),
      'You Are Now ' || v_label || '.'
        || CASE WHEN v_is_agent
                THEN ' Your Commission Is ' || trim(to_char(v_comm * 100, 'FM990.00'))
                     || ' Percent And Your Player Rakeback Is '
                     || trim(to_char(v_rake * 100, 'FM990.00')) || ' Percent.'
                     || CASE WHEN v_prepaid THEN ' You Are Prepaid.'
                             ELSE ' Your Credit Line Is '
                                  || trim(to_char(v_limit, 'FM999,999,999,990.00')) || ' Chips.'
                        END
                ELSE '' END,
      '/clubs/' || p_club_id::text,
      jsonb_build_object(
        'club_id', p_club_id, 'old_role', v_old_role, 'new_role', p_role,
        'commission_rate', v_comm, 'player_rakeback_rate', v_rake,
        'is_prepaid', v_prepaid, 'credit_limit', v_limit));
  EXCEPTION WHEN OTHERS THEN
    -- Swallowed on purpose, and only here. The role change is already durable.
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'old_role', v_old_role, 'new_role', p_role,
    'commission_rate', v_comm, 'player_rakeback_rate', v_rake,
    'is_prepaid', v_prepaid, 'credit_limit', v_limit,
    -- Commission the CLUB owes THEM. It does not block the demotion: the agents
    -- row survives with the figure intact, so nothing is lost by moving the
    -- role, and there is no payout path to send them to yet (phase 6 builds
    -- one). Blocking here would strand the club, not the money. Reported so the
    -- caller can say it out loud rather than discover it later.
    'unclaimed_commission', COALESCE(v_commission, 0),
    'reports_to', CASE WHEN v_set_upline THEN v_actor ELSE NULL END);
END;
$$;


ALTER FUNCTION public.fn_club_set_member_role(p_club_id uuid, p_user_id uuid, p_role text, p_actor_user_id uuid, p_commission_rate numeric, p_player_rakeback_rate numeric, p_is_prepaid boolean, p_credit_limit numeric) OWNER TO postgres;

--
-- Name: fn_club_settlement_frozen(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_settlement_frozen(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT c.settlement_locked
       AND (c.settlement_lock_until IS NULL OR c.settlement_lock_until > now())
       FROM clubs c WHERE c.id = p_club_id),
    false);
$$;


ALTER FUNCTION public.fn_club_settlement_frozen(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_settlement_frozen(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_settlement_frozen(p_club_id uuid) IS 'True while this club has declared a settlement freeze that has not expired. Read by the operator-movement guard on chip_transactions and by any surface that wants to say why a transfer will be refused.';


--
-- Name: fn_club_table_daily_catchup(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_table_daily_catchup(p_days integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_n int := GREATEST(LEAST(COALESCE(p_days, 3), 30), 1);
  d date;
  v_done jsonb := '[]'::jsonb;
  v_stored bigint;
  v_actual bigint;
  v_ledger numeric;
  v_rollup numeric;
  v_reconciled jsonb := '[]'::jsonb;
  v_today_drift numeric;
BEGIN
  FOR d IN SELECT gs::date FROM generate_series(v_today - (v_n - 1), v_today, interval '1 day') gs LOOP
    SELECT COALESCE(SUM(c.source_rows), 0) INTO v_stored
      FROM club_table_daily c WHERE c.stat_date = d;

    -- The same reading of contributions the refresh uses (uuid-keyed rows,
    -- plus one synthetic row per hand with no usable contribution), so a
    -- stored count matches an actual count exactly when nothing has changed.
    SELECT (
      SELECT COUNT(*)
        FROM rake_records r
        JOIN tables t ON t.id = r.table_id AND t.tournament_id IS NULL
        CROSS JOIN LATERAL jsonb_each_text(r.player_contributions) e(key, value)
       WHERE r.created_at >= (d::timestamp AT TIME ZONE 'UTC')
         AND r.created_at <  ((d + 1)::timestamp AT TIME ZONE 'UTC')
         AND r.player_contributions IS NOT NULL
         AND r.rake_amount > 0
         AND e.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
         AND EXISTS (
           SELECT 1
             FROM jsonb_each_text(CASE WHEN jsonb_typeof(r.player_contributions) = 'object'
                                       THEN r.player_contributions ELSE '{}'::jsonb END) x
            WHERE x.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              AND (CASE WHEN x.value ~ '^-?[0-9]+(\.[0-9]+)?$' THEN x.value::numeric ELSE 0 END) > 0)
    ) + (
      SELECT COUNT(*)
        FROM rake_records r
        JOIN tables t ON t.id = r.table_id AND t.tournament_id IS NULL
       WHERE r.created_at >= (d::timestamp AT TIME ZONE 'UTC')
         AND r.created_at <  ((d + 1)::timestamp AT TIME ZONE 'UTC')
         AND r.rake_amount > 0
         AND NOT EXISTS (
           SELECT 1
             FROM jsonb_each_text(CASE WHEN jsonb_typeof(r.player_contributions) = 'object'
                                       THEN r.player_contributions ELSE '{}'::jsonb END) e
            WHERE e.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              AND (CASE WHEN e.value ~ '^-?[0-9]+(\.[0-9]+)?$' THEN e.value::numeric ELSE 0 END) > 0)
    ) INTO v_actual;

    IF d >= v_today - 1 OR v_stored IS DISTINCT FROM v_actual THEN
      PERFORM fn_club_table_daily_refresh_day(d);
      v_done := v_done || jsonb_build_array(jsonb_build_object('day', d, 'refreshed', true));
    END IF;

    -- Rake is conserved across attribution, so a COMPLETE day's rollup total
    -- must equal the ledger's cash rake for that day. Today is excluded on
    -- purpose: the triggers are exact on a live day and a recount is not.
    IF d < v_today THEN
      v_ledger := public.fn_ca_club_rake_daily_ledger_total(d);
      SELECT COALESCE(SUM(x.rake), 0) INTO v_rollup
        FROM ca_club_rake_daily x WHERE x.stat_date = d;
      IF abs(v_ledger - v_rollup) > 0.005 THEN
        PERFORM fn_ca_club_rake_daily_rebuild_range(d, d, false);
        v_reconciled := v_reconciled || jsonb_build_array(jsonb_build_object(
          'day', d, 'ledger', v_ledger, 'rollup_was', v_rollup));
      END IF;
    END IF;
  END LOOP;

  -- Today is reported, never rewritten. A drift that survives the day is a
  -- trigger that stopped landing, and it will be recounted at midnight.
  v_today_drift := round(public.fn_ca_club_rake_daily_ledger_total(v_today)
                         - COALESCE((SELECT SUM(x.rake) FROM ca_club_rake_daily x
                                      WHERE x.stat_date = v_today), 0), 4);

  RETURN jsonb_build_object('success', true, 'days', v_done,
                            'rake_daily_rebuilt', v_reconciled,
                            'today_drift', v_today_drift);
END;
$_$;


ALTER FUNCTION public.fn_club_table_daily_catchup(p_days integer) OWNER TO postgres;

--
-- Name: fn_club_table_daily_refresh_day(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_table_daily_refresh_day(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_from timestamptz := (p_day::timestamp AT TIME ZONE 'UTC');
  v_to   timestamptz := ((p_day + 1)::timestamp AT TIME ZONE 'UTC');
  v_rows int;
BEGIN
  IF p_day IS NULL OR p_day > (now() AT TIME ZONE 'UTC')::date THEN
    RETURN jsonb_build_object('success', false, 'error', 'day_out_of_range');
  END IF;

  DELETE FROM club_table_daily WHERE stat_date = p_day;

  WITH att AS (
    SELECT DISTINCT ON (cm.user_id, uc.union_id)
           uc.union_id, cm.user_id, cm.club_id
      FROM club_members cm
      JOIN union_clubs uc ON uc.club_id = cm.club_id
     ORDER BY cm.user_id, uc.union_id, cm.joined_at ASC NULLS LAST, cm.club_id
  ),
  rr AS (
    SELECT r.id, r.table_id, r.rake_amount, t.union_id, t.club_id AS table_club,
           e.key AS uid, (e.value)::numeric AS contrib,
           SUM((e.value)::numeric) OVER (PARTITION BY r.id) AS tot
      FROM rake_records r
      JOIN tables t ON t.id = r.table_id AND t.tournament_id IS NULL
      CROSS JOIN LATERAL jsonb_each_text(r.player_contributions) e(key, value)
     WHERE r.created_at >= v_from AND r.created_at < v_to
       AND r.player_contributions IS NOT NULL
       AND r.rake_amount > 0
       AND e.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       AND EXISTS (
         SELECT 1
           FROM jsonb_each_text(CASE WHEN jsonb_typeof(r.player_contributions) = 'object'
                                     THEN r.player_contributions ELSE '{}'::jsonb END) x
          WHERE x.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            AND (CASE WHEN x.value ~ '^-?[0-9]+(\.[0-9]+)?$' THEN x.value::numeric ELSE 0 END) > 0)
    UNION ALL
    -- 2026-09-04: a raked hand with no usable contribution (none recorded,
    -- not an object, no uuid keys, nothing positive) used to vanish from this
    -- rollup: 109 rows and 173.38 chips on the reference club's three days.
    -- It is the table's club's rake and it goes there whole, as one synthetic
    -- row of weight 1 and no player.
    SELECT r.id, r.table_id, r.rake_amount, t.union_id, t.club_id,
           NULL::text, 1::numeric, 1::numeric
      FROM rake_records r
      JOIN tables t ON t.id = r.table_id AND t.tournament_id IS NULL
     WHERE r.created_at >= v_from AND r.created_at < v_to
       AND r.rake_amount > 0
       AND NOT EXISTS (
         SELECT 1
           FROM jsonb_each_text(CASE WHEN jsonb_typeof(r.player_contributions) = 'object'
                                     THEN r.player_contributions ELSE '{}'::jsonb END) e
          WHERE e.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            AND (CASE WHEN e.value ~ '^-?[0-9]+(\.[0-9]+)?$' THEN e.value::numeric ELSE 0 END) > 0)
  ),
  raked AS (
    SELECT COALESCE(a.club_id, rr.table_club) AS club_id,
           rr.table_id,
           rr.union_id,
           SUM(rr.rake_amount * rr.contrib / rr.tot) AS rake,
           COUNT(DISTINCT rr.id)  AS hands,
           COUNT(DISTINCT rr.uid) AS players,
           COUNT(*)               AS src
      FROM rr
      LEFT JOIN att a ON a.user_id::text = rr.uid AND a.union_id IS NOT DISTINCT FROM rr.union_id
     WHERE rr.tot > 0
     GROUP BY 1, 2, 3
  ),
  -- 2026-09-04: a table add-on (a top-up, 'addon'), a rebuy and a refund are
  -- buy-in money too; this read 'buyin' and 'cashout' alone and so put every
  -- top-up (1.76M chips across the platform in 30 days) on the players' side
  -- of the table net. Debits are money onto the table, credits money off it.
  wal AS (
    SELECT COALESCE(a.club_id, t.club_id) AS club_id,
           wt.table_id,
           t.union_id,
           SUM(CASE WHEN wt.type = 'debit'  THEN wt.amount ELSE 0 END) AS buyins,
           SUM(CASE WHEN wt.type = 'credit' THEN wt.amount ELSE 0 END) AS cashouts
      FROM wallet_transactions wt
      JOIN tables t ON t.id = wt.table_id AND t.tournament_id IS NULL
      LEFT JOIN att a ON a.user_id = wt.user_id AND a.union_id IS NOT DISTINCT FROM t.union_id
     WHERE wt.created_at >= v_from AND wt.created_at < v_to
       AND wt.category IN ('buyin', 'cashout', 'addon', 'rebuy', 'refund')
     GROUP BY 1, 2, 3
  ),
  merged AS (
    SELECT COALESCE(k.club_id,  w.club_id)  AS club_id,
           COALESCE(k.table_id, w.table_id) AS table_id,
           COALESCE(k.union_id, w.union_id) AS union_id,
           COALESCE(k.rake, 0)     AS rake,
           COALESCE(k.hands, 0)    AS hands,
           COALESCE(k.players, 0)  AS players,
           COALESCE(k.src, 0)      AS src,
           COALESCE(w.buyins, 0)   AS buyins,
           COALESCE(w.cashouts, 0) AS cashouts
      FROM raked k
      FULL OUTER JOIN wal w
        ON w.club_id = k.club_id AND w.table_id = k.table_id
  )
  INSERT INTO club_table_daily (club_id, table_id, stat_date, union_id,
                                rake, hands, players, buyins, cashouts, net,
                                source_rows, updated_at)
  SELECT m.club_id, m.table_id, p_day, m.union_id,
         round(m.rake, 4), m.hands, m.players,
         round(m.buyins, 2), round(m.cashouts, 2),
         round(m.cashouts - m.buyins, 2),
         m.src, now()
    FROM merged m
   WHERE m.club_id IS NOT NULL AND m.table_id IS NOT NULL;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'day', p_day, 'rows', v_rows);
END;
$_$;


ALTER FUNCTION public.fn_club_table_daily_refresh_day(p_day date) OWNER TO postgres;

--
-- Name: fn_club_tournament_stats(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_tournament_stats(p_club_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE("userId" uuid, username text, avatar text, "tournamentsPlayed" integer, wins integer, "finalTables" integer, "itmFinishes" integer, "totalPrizes" numeric, roi numeric, "biggestWin" numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT
        tp.user_id,
        COALESCE(pr.username, tp.username)::text,
        pr.arena_avatar_url::text,
        COUNT(DISTINCT tp.tournament_id)::int,
        COUNT(*) FILTER (WHERE tp.position = 1)::int,
        COUNT(*) FILTER (WHERE tp.position IS NOT NULL AND tp.position <= 9)::int,
        COUNT(*) FILTER (WHERE COALESCE(tp.prize, 0) > 0)::int,
        COALESCE(SUM(tp.prize), 0)::numeric,
        (CASE
            WHEN SUM(COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0)) > 0
            THEN ((COALESCE(SUM(tp.prize), 0)
                   - SUM(COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0)))
                  / SUM(COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0))) * 100.0
            ELSE 0
        END)::numeric,
        COALESCE(MAX(tp.prize), 0)::numeric
    FROM tournament_players tp
    JOIN tournaments t ON t.id = tp.tournament_id
    LEFT JOIN profiles pr ON pr.id = tp.user_id
    WHERE t.club_id = p_club_id
      AND tp.status IN ('eliminated', 'winner')
    GROUP BY tp.user_id, COALESCE(pr.username, tp.username), pr.arena_avatar_url
    -- user_id breaks ties: without it, two players on equal prizes can swap
    -- between pages and the same row appears twice while another never does.
    ORDER BY 8 DESC, tp.user_id
    LIMIT GREATEST(p_limit, 0)
    OFFSET GREATEST(p_offset, 0);
$$;


ALTER FUNCTION public.fn_club_tournament_stats(p_club_id uuid, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_tournament_stats(p_club_id uuid, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_tournament_stats(p_club_id uuid, p_limit integer, p_offset integer) IS 'Club tournament leaderboard aggregated server-side. Replaces a client-side aggregation that was capped at 10k raw rows, which every club exceeded. SECURITY INVOKER so the tournaments RLS policy still hides private tournaments.';


--
-- Name: fn_club_trade_ledger(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_trade_ledger(p_club_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, created_at timestamp with time zone, transaction_type text, amount numeric, from_user_id uuid, to_user_id uuid, notes text, metadata jsonb, from_name text, to_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
DECLARE
  v_viewer uuid := auth.uid();
  v_role text;
  -- The UI exposes up to 250 rows and asks for one sentinel row to prove that
  -- another page exists. A cap of 200 made the 200 -> 250 control disappear:
  -- p_limit=201 was silently reduced to 200, so the browser concluded there
  -- was no 201st row. Keep the endpoint bounded while honoring that contract.
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 251);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
BEGIN
  IF v_viewer IS NULL OR p_club_id IS NULL THEN
    RETURN;
  END IF;

  SELECT cm.role
    INTO v_role
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id
     AND cm.user_id = v_viewer
     AND coalesce(cm.status::text, 'active') IN ('active', 'approved')
   LIMIT 1;

  IF v_role IS NULL THEN
    RETURN;
  END IF;

  IF v_role IN ('owner', 'co_owner', 'admin', 'super_agent') THEN
    RETURN QUERY
    SELECT ct.id, ct.created_at, ct.transaction_type, ct.amount,
           ct.from_user_id, ct.to_user_id, ct.notes, ct.metadata,
           coalesce(pf.alias, pf.display_name, pf.username),
           coalesce(pt.alias, pt.display_name, pt.username)
      FROM public.chip_transactions ct
      LEFT JOIN public.profiles pf ON pf.id = ct.from_user_id
      LEFT JOIN public.profiles pt ON pt.id = ct.to_user_id
     WHERE ct.club_id = p_club_id
     ORDER BY ct.created_at DESC, ct.id DESC
     LIMIT v_limit OFFSET v_offset;
  ELSIF v_role IN ('agent', 'sub_agent') THEN
    RETURN QUERY
    WITH RECURSIVE downline AS (
      SELECT v_viewer AS user_id
      UNION
      SELECT cm.user_id
        FROM public.club_members cm
        JOIN downline d ON cm.agent_id = d.user_id
       WHERE cm.club_id = p_club_id
         AND coalesce(cm.status::text, 'active') IN ('active', 'approved')
    )
    SELECT ct.id, ct.created_at, ct.transaction_type, ct.amount,
           ct.from_user_id, ct.to_user_id, ct.notes, ct.metadata,
           coalesce(pf.alias, pf.display_name, pf.username),
           coalesce(pt.alias, pt.display_name, pt.username)
      FROM public.chip_transactions ct
      LEFT JOIN public.profiles pf ON pf.id = ct.from_user_id
      LEFT JOIN public.profiles pt ON pt.id = ct.to_user_id
     WHERE ct.club_id = p_club_id
       AND (ct.from_user_id IN (SELECT d.user_id FROM downline d)
         OR ct.to_user_id IN (SELECT d.user_id FROM downline d))
     ORDER BY ct.created_at DESC, ct.id DESC
     LIMIT v_limit OFFSET v_offset;
  ELSE
    RETURN QUERY
    SELECT ct.id, ct.created_at, ct.transaction_type, ct.amount,
           ct.from_user_id, ct.to_user_id, ct.notes, ct.metadata,
           coalesce(pf.alias, pf.display_name, pf.username),
           coalesce(pt.alias, pt.display_name, pt.username)
      FROM public.chip_transactions ct
      LEFT JOIN public.profiles pf ON pf.id = ct.from_user_id
      LEFT JOIN public.profiles pt ON pt.id = ct.to_user_id
     WHERE ct.club_id = p_club_id
       AND (ct.from_user_id = v_viewer OR ct.to_user_id = v_viewer)
     ORDER BY ct.created_at DESC, ct.id DESC
     LIMIT v_limit OFFSET v_offset;
  END IF;
END;
$$;


ALTER FUNCTION public.fn_club_trade_ledger(p_club_id uuid, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_club_unclaimable_commission(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_unclaimable_commission(p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
           'pairs',      COALESCE(count(*), 0),
           'total',      COALESCE(round(sum(t.amt), 2), 0),
           'rows',       COALESCE(sum(t.n), 0),
           'clubs',      COALESCE(count(DISTINCT t.club_id), 0),
           'horses',     COALESCE(count(*) FILTER (WHERE t.is_horse), 0),
           'humans',     COALESCE(count(*) FILTER (WHERE NOT t.is_horse), 0),
           'still_accruing_24h',
                         COALESCE(count(*) FILTER (WHERE t.last_row > now() - interval '24 hours'), 0),
           'measured_at', now()
         )
    FROM (
      SELECT ac.club_id,
             ac.user_id,
             SUM(ac.amount)     AS amt,
             count(*)           AS n,
             max(ac.created_at) AS last_row,
             COALESCE((SELECT pr.is_horse FROM profiles pr WHERE pr.id = ac.user_id), false) AS is_horse
        FROM agent_commissions ac
       WHERE ac.settled_at IS NULL AND NOT EXISTS (SELECT 1 FROM public.agent_commission_settlements s2 WHERE s2.club_id = ac.club_id AND s2.user_id = ac.user_id AND ac.created_at >= s2.period_start AND ac.created_at < s2.period_end)
         AND (p_club_id IS NULL OR ac.club_id = p_club_id)
         AND NOT EXISTS (
               SELECT 1 FROM club_members cm
                WHERE cm.club_id = ac.club_id
                  AND cm.user_id = ac.user_id
                  AND COALESCE(cm.status, 'active') IN ('active', 'approved'))
       GROUP BY ac.club_id, ac.user_id
    ) t;
$$;


ALTER FUNCTION public.fn_club_unclaimable_commission(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_unclaimable_commission(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_unclaimable_commission(p_club_id uuid) IS 'Unsettled commission booked to a club the payee is not an active member of, so the claim path refuses it. SERVICE ROLE ONLY: it reports across clubs and has no per-caller guard. Horses are counted, never filtered (CLAUDE.md 10.5).';


--
-- Name: fn_club_union_context(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_union_context(p_club_id uuid) RETURNS TABLE(own_union_id uuid, member_union_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_union boolean;
  v_union_id uuid;
  v_own      uuid;
BEGIN
  own_union_id := NULL;
  member_union_id := NULL;

  IF p_club_id IS NULL THEN
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT COALESCE(c.is_union, false), c.union_id
    INTO v_is_union, v_union_id
    FROM clubs c
   WHERE c.id = p_club_id;

  IF NOT FOUND THEN
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_is_union OR v_union_id = p_club_id
     OR EXISTS (SELECT 1 FROM unions u WHERE u.id = p_club_id) THEN
    v_own := p_club_id;
    v_union_id := NULL;
  END IF;

  IF v_own IS NULL AND v_union_id IS NULL THEN
    SELECT uc.union_id INTO v_union_id
      FROM union_clubs uc
     WHERE uc.club_id = p_club_id
       AND uc.union_id <> p_club_id
     LIMIT 1;
  END IF;

  own_union_id := v_own;
  member_union_id := v_union_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_club_union_context(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_club_union_join_blockers(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_union_join_blockers(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_treasury    numeric := 0;
  v_club_promo  numeric := 0;
  v_people      numeric := 0;
  v_people_n    int     := 0;
  v_horses      numeric := 0;
  v_horses_n    int     := 0;
  v_agents      numeric := 0;
  v_agents_n    int     := 0;
  v_felt        numeric := 0;
  v_felt_n      int     := 0;
  v_bbj         numeric := 0;
  v_total       numeric := 0;
BEGIN
  SELECT COALESCE(chip_treasury, 0), COALESCE(promo_balance, 0)
    INTO v_treasury, v_club_promo
    FROM clubs WHERE id = p_club_id;

  SELECT COALESCE(SUM(bal), 0), COUNT(*) FILTER (WHERE bal <> 0)
    INTO v_people, v_people_n
    FROM (
      SELECT COALESCE(cm.chip_balance,0) + COALESCE(cm.held_chips,0)
           + COALESCE(cm.locked_chips,0) + COALESCE(cm.promo_balance,0) AS bal
        FROM club_members cm
        LEFT JOIN profiles p ON p.id = cm.user_id
       WHERE cm.club_id = p_club_id
         AND NOT COALESCE(cm.is_bot, false)
         AND NOT COALESCE(p.is_horse, false)
    ) s;

  -- Reported, never blocking. Dan 2026-08-26: "horses keep all there chips."
  SELECT COALESCE(SUM(bal), 0), COUNT(*) FILTER (WHERE bal <> 0)
    INTO v_horses, v_horses_n
    FROM (
      SELECT COALESCE(cm.chip_balance,0) + COALESCE(cm.held_chips,0)
           + COALESCE(cm.locked_chips,0) + COALESCE(cm.promo_balance,0) AS bal
        FROM club_members cm
        LEFT JOIN profiles p ON p.id = cm.user_id
       WHERE cm.club_id = p_club_id
         AND (COALESCE(cm.is_bot, false) OR COALESCE(p.is_horse, false))
    ) s;

  SELECT COALESCE(SUM(bal), 0), COUNT(*) FILTER (WHERE bal <> 0)
    INTO v_agents, v_agents_n
    FROM (
      SELECT COALESCE(a.business_balance,0) + COALESCE(a.player_balance,0)
           + COALESCE(a.promo_balance,0) AS bal
        FROM agents a WHERE a.club_id = p_club_id
    ) s;

  -- Chips on the felt still block: a hand in progress is a player's money.
  -- A horse's seat is excluded along with the rest of its bankroll.
  SELECT COALESCE(SUM(ts.stack), 0), COUNT(*)
    INTO v_felt, v_felt_n
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
    LEFT JOIN profiles p ON p.id = ts.user_id
   WHERE t.club_id = p_club_id
     AND ts.left_at IS NULL
     AND COALESCE(ts.stack, 0) <> 0
     AND NOT COALESCE(p.is_horse, false);

  SELECT COALESCE(SUM(COALESCE(main_balance,0) + COALESCE(backup_balance,0)
                    + COALESCE(promo_balance,0)), 0)
    INTO v_bbj
    FROM bbj_pools WHERE club_id = p_club_id AND union_id IS NULL;

  -- v_horses is deliberately absent from this sum.
  v_total := v_treasury + v_club_promo + v_people + v_agents + v_felt + v_bbj;

  RETURN jsonb_build_object(
    'club_id',         p_club_id,
    'is_empty',        (v_total = 0),
    'total',           v_total,
    'club_treasury',   v_treasury,
    'club_promo',      v_club_promo,
    'member_wallets',  v_people,
    'member_count',    v_people_n,
    'horse_wallets',   v_horses,
    'horse_count',     v_horses_n,
    'horses_block',    false,
    'agent_wallets',   v_agents,
    'agent_count',     v_agents_n,
    'chips_on_felt',   v_felt,
    'open_seats',      v_felt_n,
    'bbj_pool',        v_bbj
  );
END;
$$;


ALTER FUNCTION public.fn_club_union_join_blockers(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_club_union_join_blockers(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_union_join_blockers(p_club_id uuid) IS 'Itemises every chip balance that must be cleared before a club may join a union. Horse bankrolls are reported but never block - Dan 2026-08-26, horses keep all their chips. Read it to show an owner what is left; the BEFORE INSERT trigger on union_clubs enforces it.';


--
-- Name: fn_clubs_lobby_message_keeps_its_own_books(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_clubs_lobby_message_keeps_its_own_books() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Whitespace is not a message. One rule, applied before any writer's own.
  IF NEW.lobby_message IS NOT NULL AND btrim(NEW.lobby_message) = '' THEN
    NEW.lobby_message := NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.lobby_message_updated_at := CASE
      WHEN NEW.lobby_message IS NULL THEN NULL
      ELSE COALESCE(NEW.lobby_message_updated_at, now())
    END;
    RETURN NEW;
  END IF;

  IF NEW.lobby_message IS DISTINCT FROM OLD.lobby_message THEN
    NEW.lobby_message_updated_at := CASE
      WHEN NEW.lobby_message IS NULL THEN NULL
      ELSE now()
    END;
    -- A writer that bumped the revision in this same statement is left alone.
    -- One that forgot is corrected, which is the difference between a message
    -- rewritten from Club Settings reaching a player who dismissed the last
    -- one, and that message never reaching them at all.
    IF NEW.message_revision IS NOT DISTINCT FROM OLD.message_revision THEN
      NEW.message_revision := COALESCE(OLD.message_revision, 0) + 1;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_clubs_lobby_message_keeps_its_own_books() OWNER TO postgres;

--
-- Name: fn_cluster_table_ceiling(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cluster_table_ceiling() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_live integer;
  v_ceiling integer;
BEGIN
  IF NEW.cluster_id IS NULL THEN RETURN NEW; END IF;

  SELECT coalesce(g.cap_mains, 8) + 1 + CASE WHEN g.allow_second_feeder THEN 1 ELSE 0 END + 2
    INTO v_ceiling
    FROM public.cash_games g WHERE g.id = NEW.cluster_id;
  IF v_ceiling IS NULL THEN RETURN NEW; END IF;

  SELECT count(*) INTO v_live FROM public.tables t
   WHERE t.cluster_id = NEW.cluster_id
     AND coalesce(t.is_deleted, false) = false
     AND t.lifecycle <> 'closed';

  IF v_live >= v_ceiling THEN
    INSERT INTO public.cash_cluster_events (game_id, kind, payload)
    VALUES (NEW.cluster_id, 'table_refused_at_ceiling',
            jsonb_build_object('live', v_live, 'ceiling', v_ceiling,
                               'role', NEW.role, 'main_index', NEW.main_index));
    RETURN NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_cluster_table_ceiling() OWNER TO postgres;

--
-- Name: fn_collect_bounty(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_collect_bounty(p_tournament_id uuid, p_eliminated_user_id uuid, p_collector_user_id uuid, p_claimants jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  o public.tournament_bounty_obligations%ROWTYPE;
  v_result jsonb;
  v_shares jsonb;
  v_paid_cash numeric;
  v_added_to_head numeric;
  v_context text := current_setting('app.bounty_obligation_id',true);
  v_prior_context text;
  v_obligation_count integer;
  v_pko_watermark bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  PERFORM 1 FROM public.tournaments t WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','tournament_not_found'); END IF;

  IF COALESCE(v_context,'')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
    SELECT * INTO o FROM public.tournament_bounty_obligations bo
     WHERE bo.id=v_context::uuid AND bo.tournament_id=p_tournament_id
       AND bo.eliminated_user_id=p_eliminated_user_id
       AND bo.mode<>'mystery_chest'
     FOR UPDATE;
  ELSE
    SELECT count(*) INTO v_obligation_count
      FROM public.tournament_bounty_obligations bo
     WHERE bo.tournament_id=p_tournament_id
       AND bo.eliminated_user_id=p_eliminated_user_id
       AND bo.mode<>'mystery_chest';
    IF v_obligation_count>1 THEN
      RETURN jsonb_build_object('ok',false,'reason','bounty_generation_identity_required');
    END IF;
    SELECT * INTO o FROM public.tournament_bounty_obligations bo
     WHERE bo.tournament_id=p_tournament_id
       AND bo.eliminated_user_id=p_eliminated_user_id
       AND bo.mode<>'mystery_chest'
     FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','bounty_obligation_not_ready');
  END IF;
  IF o.mode='pko' THEN
    SELECT w.last_settled_hand_number INTO v_pko_watermark
      FROM public.tournament_pko_settlement_watermarks w
     WHERE w.tournament_id=o.tournament_id FOR UPDATE;
    IF v_pko_watermark IS NOT NULL AND o.hand_number<v_pko_watermark THEN
      RETURN jsonb_build_object('ok',false,'reason','pko_order_already_advanced',
                                'last_settled_hand_number',v_pko_watermark);
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.tournament_bounty_obligations prior
       WHERE prior.tournament_id=o.tournament_id AND prior.mode='pko'
         AND prior.state='pending' AND prior.hand_number<o.hand_number
    ) THEN
      RETURN jsonb_build_object('ok',false,'reason','pending_pko_predecessor');
    END IF;
  END IF;
  IF o.state='settled' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'user_id',b.collector_player_id,
             'cash',GREATEST(0,b.bounty_amount-COALESCE(b.added_to_collector_bounty,0)),
             'to_head',COALESCE(b.added_to_collector_bounty,0))
             ORDER BY b.collector_player_id),'[]'::jsonb),
           COALESCE(sum(GREATEST(0,b.bounty_amount-COALESCE(b.added_to_collector_bounty,0))),0),
           COALESCE(sum(b.added_to_collector_bounty),0)
      INTO v_shares,v_paid_cash,v_added_to_head
      FROM public.tournament_bounties b
     WHERE b.bounty_obligation_id=o.id;
    IF NOT public.fn_bounty_obligation_has_complete_marker(o.id) THEN
      RETURN jsonb_build_object('ok',false,'reason','settled_marker_incomplete',
                                'obligation_id',o.id);
    END IF;
    IF o.mode='pko' THEN
      INSERT INTO public.tournament_pko_settlement_watermarks
        (tournament_id,last_settled_hand_number,last_obligation_id)
      VALUES (o.tournament_id,o.hand_number,o.id)
      ON CONFLICT (tournament_id) DO UPDATE
        SET last_settled_hand_number=GREATEST(
              public.tournament_pko_settlement_watermarks.last_settled_hand_number,
              EXCLUDED.last_settled_hand_number),
            last_obligation_id=CASE
              WHEN EXCLUDED.last_settled_hand_number>=
                   public.tournament_pko_settlement_watermarks.last_settled_hand_number
              THEN EXCLUDED.last_obligation_id
              ELSE public.tournament_pko_settlement_watermarks.last_obligation_id END,
            updated_at=now();
    END IF;
    RETURN jsonb_build_object('ok',true,'already',true,'obligation_id',o.id,
      'marker_verified',true,'mode',o.mode,'head',o.head_amount,
      'paid_cash',v_paid_cash,'added_to_head',v_added_to_head,
      'split',jsonb_array_length(v_shares)>1,'shares',v_shares);
  END IF;

  -- Ignore caller ordering/weights. The exact pot-derived, roster-validated
  -- snapshot stored by the atomic claim is the only payout authority.
  v_prior_context := current_setting('app.bounty_obligation_id',true);
  PERFORM set_config('app.bounty_obligation_id',o.id::text,true);
  v_result := public.fn_collect_bounty_unguarded_20260907(
    p_tournament_id,p_eliminated_user_id,o.knocker_user_id,o.claimants);
  PERFORM set_config('app.bounty_obligation_id',COALESCE(v_prior_context,''),true);

  IF NOT COALESCE((v_result->>'ok')::boolean,false) THEN
    -- A semantic pre-write refusal is safe to commit and stays pending. Any
    -- accepted payer result below must satisfy the exact marker postcondition
    -- or raise so its wallet/head/counter mutations roll back atomically.
    RETURN v_result || jsonb_build_object('obligation_id',o.id);
  END IF;

  UPDATE public.tournament_bounty_obligations bo
     SET state='settled',settled_at=COALESCE(settled_at,now()),last_error=NULL
   WHERE bo.id=o.id AND bo.state='pending'
     AND public.fn_bounty_obligation_has_complete_marker(bo.id);
  IF NOT public.fn_bounty_obligation_has_complete_marker(o.id)
     OR NOT EXISTS (SELECT 1 FROM public.tournament_bounty_obligations bo
                     WHERE bo.id=o.id AND bo.state='settled') THEN
    RAISE EXCEPTION 'accepted bounty payout did not produce the exact settled marker for %',o.id
      USING ERRCODE='check_violation';
  END IF;
  IF o.mode='pko' THEN
    INSERT INTO public.tournament_pko_settlement_watermarks
      (tournament_id,last_settled_hand_number,last_obligation_id)
    VALUES (o.tournament_id,o.hand_number,o.id)
    ON CONFLICT (tournament_id) DO UPDATE
      SET last_settled_hand_number=GREATEST(
            public.tournament_pko_settlement_watermarks.last_settled_hand_number,
            EXCLUDED.last_settled_hand_number),
          last_obligation_id=CASE
            WHEN EXCLUDED.last_settled_hand_number>=
                 public.tournament_pko_settlement_watermarks.last_settled_hand_number
            THEN EXCLUDED.last_obligation_id
            ELSE public.tournament_pko_settlement_watermarks.last_obligation_id END,
          updated_at=now();
  END IF;
  RETURN v_result || jsonb_build_object('obligation_id',o.id,'marker_verified',true);
END;
$_$;


ALTER FUNCTION public.fn_collect_bounty(p_tournament_id uuid, p_eliminated_user_id uuid, p_collector_user_id uuid, p_claimants jsonb) OWNER TO postgres;

--
-- Name: fn_collect_bounty_obligation(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_collect_bounty_obligation(p_obligation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  o public.tournament_bounty_obligations%ROWTYPE;
  v_prior_context text := current_setting('app.bounty_obligation_id',true);
  v_result jsonb;
BEGIN
  SELECT * INTO o FROM public.tournament_bounty_obligations WHERE id=p_obligation_id;
  IF NOT FOUND OR o.mode='mystery_chest' THEN
    RETURN jsonb_build_object('ok',false,'reason','bounty_obligation_not_found');
  END IF;
  PERFORM set_config('app.bounty_obligation_id',o.id::text,true);
  v_result := public.fn_collect_bounty(
    o.tournament_id,o.eliminated_user_id,o.knocker_user_id,o.claimants);
  PERFORM set_config('app.bounty_obligation_id',COALESCE(v_prior_context,''),true);
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_collect_bounty_obligation(p_obligation_id uuid) OWNER TO postgres;

--
-- Name: fn_collect_bounty_unguarded_20260907(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_collect_bounty_unguarded_20260907(p_tournament_id uuid, p_eliminated_user_id uuid, p_collector_user_id uuid, p_claimants jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t record; v_elim record;
  v_head numeric; v_available numeric; v_payable numeric;
  v_cash numeric; v_to_head numeric;
  v_cents integer; v_cash_cents integer;
  v_mode text; v_funded boolean;
  v_claimants jsonb; v_n integer; v_total_weight numeric;
  v_shares jsonb := '[]'::jsonb; v_paid_total numeric := 0; v_head_total numeric := 0;
  c record; v_share_cents integer; v_assigned_cents integer := 0; v_i integer := 0;
  v_prior numeric; v_settle jsonb; v_desc text;
BEGIN
  IF p_collector_user_id IS NULL OR p_eliminated_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'missing_party');
  END IF;

  SELECT id, is_bounty, is_pko, is_mystery_bounty, bounty_amount,
         bounty_pool, bounty_pool_paid, mystery_bounty_stage
    INTO v_t FROM tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found'); END IF;
  IF NOT (COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
          OR COALESCE(v_t.is_mystery_bounty,false)) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_bounty_tournament');
  END IF;

  -- HYBRID TRIPWIRE 2026-08-27. See migration header (a).
  IF COALESCE(v_t.is_pko, false) AND COALESCE(v_t.is_mystery_bounty, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'undefined_pko_mystery_hybrid',
      'detail', 'PKO heads claim against bounty_pool; mystery chests are a sealed '
             || 'inventory. No split satisfies both. This event should not exist.');
  END IF;

  IF COALESCE(v_t.is_mystery_bounty, false) AND v_t.mystery_bounty_stage = 'active' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'mystery_phase_active');
  END IF;

  IF EXISTS (
    SELECT 1 FROM tournament_bounties b
     WHERE b.tournament_id = p_tournament_id
       AND b.eliminated_player_id = p_eliminated_user_id
       AND (
         b.bounty_obligation_id = (SELECT o.id
           FROM tournament_bounty_obligations o
          WHERE o.tournament_id=p_tournament_id
            AND o.eliminated_user_id=p_eliminated_user_id
            AND o.mode <> 'mystery_chest' AND o.state='pending'
          ORDER BY o.hand_number, o.created_at LIMIT 1)
         OR (b.bounty_obligation_id IS NULL AND NOT EXISTS (
           SELECT 1 FROM tournament_bounty_obligations o
            WHERE o.tournament_id=p_tournament_id
              AND o.eliminated_user_id=p_eliminated_user_id
              AND o.mode <> 'mystery_chest' AND o.state='pending'))
       )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_collected');
  END IF;

  SELECT current_bounty INTO v_elim
    FROM tournament_players
   WHERE tournament_id = p_tournament_id AND user_id = p_eliminated_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'eliminated_player_not_in_tournament');
  END IF;

  v_mode := CASE WHEN COALESCE(v_t.is_pko,false) THEN 'pko'
                 WHEN COALESCE(v_t.is_mystery_bounty,false) THEN 'mystery_pre'
                 ELSE 'regular' END;

  v_head := COALESCE(NULLIF(v_elim.current_bounty, 0), v_t.bounty_amount, 0);
  IF v_head <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_head_value');
  END IF;
  IF EXISTS (
    SELECT 1 FROM tournament_bounty_obligations o
     WHERE o.tournament_id=p_tournament_id
       AND o.eliminated_user_id=p_eliminated_user_id
       AND o.mode <> 'mystery_chest' AND o.state='pending'
       AND o.head_amount IS DISTINCT FROM round(v_head,2)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'head_snapshot_changed');
  END IF;

  v_funded  := COALESCE(v_t.bounty_pool, 0) > 0;
  SELECT round(COALESCE(v_t.bounty_pool,0) - COALESCE(SUM(CASE WHEN lower(wt.type) = 'debit' THEN -abs(wt.amount) ELSE wt.amount END), 0), 2) INTO v_available FROM wallet_transactions wt WHERE wt.related_entity_id = p_tournament_id AND wt.category = 'bounty';

  IF v_funded THEN
    IF v_available <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'bounty_pool_exhausted',
                                'head', v_head, 'available', v_available);
    END IF;
    IF v_available < v_head THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'bounty_pool_underfunded',
                                'head', v_head, 'available', v_available);
    END IF;
    v_payable := v_head;
  ELSE
    v_payable := v_head;
  END IF;

  -- SPLIT-POT RULING (2026-08-31): build the validated claimant list.
  -- Claimants must be seated in this tournament with positive weight; a list
  -- that validates to nothing falls back to the single collector.
  SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id', x.uid, 'weight', x.w)), '[]'::jsonb)
    INTO v_claimants
  FROM (
    SELECT (e->>'user_id')::uuid AS uid, (e->>'weight')::numeric AS w
    FROM jsonb_array_elements(COALESCE(p_claimants, '[]'::jsonb)) e
    WHERE (e->>'user_id') IS NOT NULL AND COALESCE((e->>'weight')::numeric, 0) > 0
      AND EXISTS (SELECT 1 FROM tournament_players tp
                  WHERE tp.tournament_id = p_tournament_id
                    AND tp.user_id = (e->>'user_id')::uuid)
  ) x;
  v_n := jsonb_array_length(v_claimants);
  IF v_n <= 1 THEN
    v_claimants := jsonb_build_array(jsonb_build_object('user_id', p_collector_user_id, 'weight', 1));
    v_n := 1;
  END IF;
  SELECT sum((e->>'weight')::numeric) INTO v_total_weight
    FROM jsonb_array_elements(v_claimants) e;

  v_cents := round(v_payable * 100)::integer;

  v_desc := CASE v_mode WHEN 'pko'         THEN 'PKO bounty (cash half) from eliminated player'
                        WHEN 'mystery_pre' THEN 'Bounty collected before the mystery phase opened'
                        ELSE 'Bounty collected from eliminated player' END
            || CASE WHEN v_n > 1 THEN ' (split pot, ' || v_n || ' winners)' ELSE '' END;

  -- pay each claimant their weighted share (largest share absorbs remainder
  -- by paying LAST with whatever cents remain - exact conservation)
  FOR c IN
    SELECT (e->>'user_id')::uuid AS uid, (e->>'weight')::numeric AS w
    FROM jsonb_array_elements(v_claimants) e
    ORDER BY (e->>'weight')::numeric ASC, (e->>'user_id')
  LOOP
    v_i := v_i + 1;
    IF v_i < v_n THEN
      v_share_cents := floor(v_cents * c.w / v_total_weight)::integer;
    ELSE
      v_share_cents := v_cents - v_assigned_cents;  -- remainder to the last (largest) share
    END IF;
    v_assigned_cents := v_assigned_cents + v_share_cents;
    CONTINUE WHEN v_share_cents <= 0;

    IF v_mode = 'pko' THEN
      v_cash_cents := (v_share_cents / 2)::integer;
      v_cash       := v_cash_cents / 100.0;
      v_to_head    := (v_share_cents - v_cash_cents) / 100.0;
    ELSE
      v_cash := v_share_cents / 100.0; v_to_head := 0;
    END IF;

    IF v_cash > 0 THEN
      /* ONE PAYER (Chip Accounting Standard R3, 2026-09-02). The bounty
         obligation for this player is user-keyed and cumulative: what the row
         already paid plus this share is the new total owed, and the settle
         function pays the difference under its own key, stamps
         app.money_path, and writes the 'bounty' ledger row ONLY when chips
         moved. A replay of the same knockout is stopped above by
         tournament_bounties (already_collected) and, below that, by the
         obligation itself (a total that is not higher pays 0). */
      v_prior := COALESCE((SELECT o.amount_paid FROM public.tournament_obligations o
                            WHERE o.tournament_id = p_tournament_id AND o.kind = 'bounty'
                              AND o.place IS NULL AND o.user_id = c.uid), 0);
      v_settle := public.fn_settle_tournament_obligation(
        p_tournament_id, 'bounty', NULL, c.uid, round(v_prior + v_cash, 2),
        'fn_collect_bounty', v_desc);
      IF NOT COALESCE((v_settle->>'ok')::boolean, false) THEN
        RAISE EXCEPTION 'fn_collect_bounty: bounty of % to % in tournament % refused (%); nothing recorded',
          v_cash, c.uid, p_tournament_id, COALESCE(v_settle->>'refused_reason', 'unknown');
      END IF;
      IF round(COALESCE((v_settle->>'paid')::numeric, 0), 2) <> round(v_cash, 2) THEN
        RAISE EXCEPTION 'fn_collect_bounty: obligation paid % but the share is % for % in tournament %; nothing recorded',
          v_settle->>'paid', v_cash, c.uid, p_tournament_id;
      END IF;
    END IF;

    UPDATE tournament_players
       SET bounties_collected = COALESCE(bounties_collected,0) + 1,
           bounty_winnings    = round(COALESCE(bounty_winnings,0) + v_cash, 2),
           current_bounty     = round(COALESCE(current_bounty,0) + v_to_head, 2)
     WHERE tournament_id = p_tournament_id AND user_id = c.uid;

    INSERT INTO tournament_bounties
      (tournament_id, eliminated_player_id, collector_player_id, bounty_amount,
       added_to_collector_bounty, is_mystery_revealed)
    VALUES (p_tournament_id, p_eliminated_user_id, c.uid, round(v_share_cents / 100.0, 2),
            CASE WHEN v_to_head > 0 THEN v_to_head ELSE NULL END,
            false);

    v_paid_total := v_paid_total + v_cash;
    v_head_total := v_head_total + v_to_head;
    v_shares := v_shares || jsonb_build_object('user_id', c.uid, 'cash', v_cash, 'to_head', v_to_head);
  END LOOP;

  UPDATE tournament_players SET current_bounty = 0
   WHERE tournament_id = p_tournament_id AND user_id = p_eliminated_user_id;

  IF v_funded THEN
    UPDATE tournaments
       SET bounty_pool_paid = round(COALESCE(bounty_pool_paid,0) + v_paid_total, 2)
     WHERE id = p_tournament_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'mode', v_mode, 'funded', v_funded,
    'head', v_head, 'paid_cash', round(v_paid_total, 2), 'added_to_head', round(v_head_total, 2),
    'split', v_n > 1, 'shares', v_shares,
    'capped', v_funded AND v_payable < v_head,
    'pool_remaining', CASE WHEN v_funded THEN round(v_available - v_paid_total, 2) END);
END;
$$;


ALTER FUNCTION public.fn_collect_bounty_unguarded_20260907(p_tournament_id uuid, p_eliminated_user_id uuid, p_collector_user_id uuid, p_claimants jsonb) OWNER TO postgres;

--
-- Name: fn_columns_manifest(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_columns_manifest() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(jsonb_object_agg(table_name, cols), '{}'::jsonb)
  FROM (
    SELECT table_name, jsonb_agg(column_name ORDER BY ordinal_position) AS cols
    FROM information_schema.columns
    WHERE table_schema='public'
    GROUP BY table_name
  ) t;
$$;


ALTER FUNCTION public.fn_columns_manifest() OWNER TO postgres;

--
-- Name: fn_commander_staff_hash_pin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_commander_staff_hash_pin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF NEW.pin_code IS NOT NULL THEN
    NEW.pin_hash := extensions.crypt(NEW.pin_code, extensions.gen_salt('bf', 6));
    NEW.pin_code := NULL;   -- never persist plaintext
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_commander_staff_hash_pin() OWNER TO postgres;

--
-- Name: fn_community_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_community_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_union_ok boolean;
  v_out jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  v_union_ok := EXISTS (SELECT 1 FROM public.union_creators uc WHERE uc.user_id = v_uid);

  WITH edges AS MATERIALIZED (
    -- One row per counterparty, whichever side of the pair this account is on.
    -- DISTINCT because a reciprocal pair (a row each way) is one friendship,
    -- not two - the /friends list already dedupes this way.
    SELECT DISTINCT f.friend_id AS other
      FROM public.friendships f
     WHERE f.user_id = v_uid AND f.status = 'accepted'
    UNION
    SELECT DISTINCT f.user_id
      FROM public.friendships f
     WHERE f.friend_id = v_uid AND f.status = 'accepted'
  ), presence AS MATERIALIZED (
    -- Same rule the client uses in utils/socialGraph.ts: the flag alone is not
    -- enough, because a crashed tab never clears it.
    SELECT count(*)::int AS online
      FROM edges e JOIN public.profiles p ON p.id = e.other
     WHERE coalesce(p.is_online, false)
       AND p.last_seen > now() - interval '5 minutes'
  ), requests AS MATERIALIZED (
    SELECT count(*)::int AS pending
      FROM public.friendships f
     WHERE f.friend_id = v_uid AND f.status = 'pending'
  ), challenges AS MATERIALIZED (
    SELECT count(*)::int AS incoming
      FROM public.friend_challenges fc
     WHERE fc.challengee_id = v_uid
       AND lower(coalesce(fc.status, '')) = 'pending'
       AND (fc.expires_at IS NULL OR fc.expires_at > now())
  ), clubs AS MATERIALIZED (
    SELECT count(DISTINCT cm.club_id)::int AS joined
      FROM public.club_members cm
     WHERE cm.user_id = v_uid
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
  ), unions AS MATERIALIZED (
    SELECT count(*)::int AS operated
      FROM public.unions u
     WHERE v_union_ok AND u.owner_id = v_uid
  )
  SELECT jsonb_build_object(
    'friends', (SELECT count(*)::int FROM edges),
    'online', (SELECT online FROM presence),
    'requests', (SELECT pending FROM requests),
    'challenges', (SELECT incoming FROM challenges),
    'clubs', (SELECT joined FROM clubs),
    -- null, not 0, so the client can tell "not allowed to see this" apart from
    -- "allowed, and the answer is none".
    'unions', CASE WHEN v_union_ok THEN (SELECT operated FROM unions) ELSE NULL END,
    'can_operate_union_network', v_union_ok
  ) INTO v_out;

  RETURN v_out;
END;
$$;


ALTER FUNCTION public.fn_community_overview() OWNER TO postgres;

--
-- Name: FUNCTION fn_community_overview(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_community_overview() IS 'Live readings for the Community Center (/community). Scoped to auth.uid(); takes no argument so a browser cannot ask about another account. Unread messages are deliberately absent - /messages leaves Club Arena for the World Hub messenger.';


--
-- Name: fn_community_search(text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_community_search(p_query text, p_scope text DEFAULT 'all'::text, p_limit integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_query text := lower(regexp_replace(btrim(coalesce(p_query, '')), '\s+', ' ', 'g'));
  v_limit integer := least(greatest(coalesce(p_limit, 12), 1), 40);
  v_tokens text[];
  v_fuzzy boolean;
  v_clubs jsonb := '[]'::jsonb;
  v_tables jsonb := '[]'::jsonb;
  v_tournaments jsonb := '[]'::jsonb;
  v_club_total integer := 0;
  v_table_total integer := 0;
  v_tournament_total integer := 0;
  v_health jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_scope IS NULL OR p_scope NOT IN ('all', 'clubs', 'tables', 'tournaments') THEN
    RAISE EXCEPTION 'Invalid search scope' USING ERRCODE = '22023';
  END IF;
  IF length(v_query) > 64 THEN
    RAISE EXCEPTION 'Search must be 64 characters or fewer' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(array_agg(t), '{}'::text[])
    INTO v_tokens
    FROM (
      SELECT t FROM unnest(string_to_array(v_query, ' ')) AS t
       WHERE t <> ''
       LIMIT 6
    ) s;
  v_fuzzy := length(v_query) >= 3;

  -- Index health is measured on every call. It is what "Live Indexes" shows.
  SELECT jsonb_build_object(
    'clubs', (SELECT count(*) FROM public.clubs c WHERE coalesce(c.status, 'active') = 'active'),
    'players', (
      SELECT count(*)
        FROM public.profiles p
        LEFT JOIN public.player_search_preferences sp ON sp.user_id = p.id
       WHERE coalesce(sp.discoverable, true)
    ),
    'tables', (
      SELECT count(*) FROM public.tables t
       WHERE t.is_deleted = false AND t.status <> 'closed' AND t.tournament_id IS NULL
    ),
    'tournaments', (
      SELECT count(*) FROM public.tournaments t
       WHERE t.status IN ('ANNOUNCED', 'REGISTERING', 'RUNNING')
    )
  ) INTO v_health;

  IF cardinality(v_tokens) = 0 THEN
    RETURN jsonb_build_object(
      'query', v_query, 'scope', p_scope, 'fuzzy', false, 'limit', v_limit,
      'clubs', v_clubs, 'tables', v_tables, 'tournaments', v_tournaments,
      'totals', jsonb_build_object('clubs', 0, 'tables', 0, 'tournaments', 0),
      'index_health', v_health
    );
  END IF;

  -- CLUBS (and unions: a union's lobby row lives in clubs with is_union)
  IF p_scope IN ('all', 'clubs') THEN
    WITH matched AS (
      SELECT c.*,
             public.fn_community_search_score(
               concat_ws(' ', c.name, c.slug, c.code, c.club_id::text, c.tagline),
               v_tokens, v_fuzzy
             ) AS score
        FROM public.clubs c
       WHERE coalesce(c.status, 'active') = 'active'
    ),
    ranked AS (
      SELECT m.*,
             row_number() OVER (
               ORDER BY m.score DESC, coalesce(m.is_union, false) DESC,
                        m.member_count DESC NULLS LAST, m.name
             ) AS ord
        FROM matched m
       WHERE m.score IS NOT NULL
    ),
    picked AS (
      SELECT r.*,
             CASE
               WHEN coalesce(r.is_union, false) THEN
                 (SELECT u.member_count FROM public.fn_batch_union_realtime_member_counts(ARRAY[r.id]) u)
               ELSE
                 (SELECT k.member_count FROM public.fn_batch_club_realtime_member_counts(ARRAY[r.id]) k)
             END AS live_member_count,
             (
               SELECT count(*)
                 FROM public.tables t
                WHERE t.is_deleted = false AND t.status <> 'closed' AND t.tournament_id IS NULL
                  AND coalesce(t.is_private, false) = false
                  AND (t.club_id = r.id
                       OR (coalesce(r.is_union, false)
                           AND t.club_id IN (SELECT uc.club_id FROM public.union_clubs uc WHERE uc.union_id = r.id)))
             ) AS live_table_count,
             (
               SELECT coalesce(sum(t.current_players), 0)
                 FROM public.tables t
                WHERE t.is_deleted = false AND t.status <> 'closed' AND t.tournament_id IS NULL
                  AND coalesce(t.is_private, false) = false
                  AND (t.club_id = r.id
                       OR (coalesce(r.is_union, false)
                           AND t.club_id IN (SELECT uc.club_id FROM public.union_clubs uc WHERE uc.union_id = r.id)))
             ) AS live_seated,
             (
               SELECT count(*) FROM public.tournaments tt
                WHERE tt.status IN ('ANNOUNCED', 'REGISTERING', 'RUNNING')
                  AND coalesce(tt.is_private, false) = false
                  AND (tt.club_id = r.id OR tt.union_id = r.id)
             ) AS live_tournament_count,
             (
               SELECT cm.status FROM public.club_members cm
                WHERE cm.club_id = r.id AND cm.user_id = v_uid
                LIMIT 1
             ) AS viewer_status,
             (SELECT pu.name FROM public.clubs pu WHERE pu.id = r.union_id AND pu.id <> r.id) AS union_name
        FROM ranked r
       WHERE r.ord <= v_limit
    )
    SELECT (SELECT count(*) FROM ranked)::integer,
           (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'id', p.id,
              'slug', p.slug,
              'club_number', p.club_id,
              'name', p.name,
              'tagline', p.tagline,
              'description', p.description,
              'image_url', coalesce(nullif(p.logo_url, ''), nullif(p.avatar_url, ''), nullif(p.logo, '')),
              'card_image_url', nullif(p.card_image_url, ''),
              'is_union', coalesce(p.is_union, false),
              'union_id', p.union_id,
              'union_name', p.union_name,
              'member_count', coalesce(p.live_member_count, p.member_count, 0),
              'online_count', coalesce(p.online_count, 0),
              'table_count', p.live_table_count,
              'seated_count', p.live_seated,
              'tournament_count', p.live_tournament_count,
              'level', p.level,
              'is_public', coalesce(p.is_public, true),
              'requires_approval', coalesce(p.requires_approval, false),
              'viewer_status', p.viewer_status,
              'match_score', round(p.score::numeric, 3)
            ) ORDER BY p.ord), '[]'::jsonb) FROM picked p)
      INTO v_club_total, v_clubs;
  END IF;

  -- TABLES (cash / open ring games)
  IF p_scope IN ('all', 'tables') THEN
    WITH visible AS (
      SELECT t.id, t.name, t.game_variant, t.game_type, t.stakes, t.small_blind, t.big_blind,
             t.current_players, t.max_players, t.status, t.club_id, t.is_featured, t.label_as_new,
             t.hide_club_name, t.created_at,
             c.name AS club_name, c.slug AS club_slug, c.is_union AS club_is_union
        FROM public.tables t
        LEFT JOIN public.clubs c ON c.id = t.club_id
       WHERE t.is_deleted = false
         AND t.status <> 'closed'
         AND t.tournament_id IS NULL
         AND coalesce(t.is_template, false) = false
         AND (
           coalesce(t.is_private, false) = false
           OR t.club_id IS NULL
           OR public.is_club_member(t.club_id, v_uid)
           OR c.owner_id = v_uid
           OR public.fn_union_oversees_club(t.club_id, v_uid)
         )
    ),
    matched AS (
      SELECT v.*,
             coalesce(
               public.fn_community_search_score(
                 concat_ws(' ', v.name, v.game_variant, v.game_type, v.stakes), v_tokens, v_fuzzy),
               0.7 * public.fn_community_search_score(
                 concat_ws(' ', v.name, v.game_variant, v.game_type, v.stakes, v.club_name), v_tokens, v_fuzzy)
             ) AS score
        FROM visible v
    ),
    ranked AS (
      SELECT m.*,
             row_number() OVER (
               ORDER BY m.score DESC, m.current_players DESC NULLS LAST,
                        (m.status = 'running') DESC, m.name
             ) AS ord
        FROM matched m
       WHERE m.score IS NOT NULL
    )
    SELECT (SELECT count(*) FROM ranked)::integer,
           (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'id', r.id,
              'name', r.name,
              'game_variant', r.game_variant,
              'game_type', r.game_type,
              'stakes', r.stakes,
              'small_blind', r.small_blind,
              'big_blind', r.big_blind,
              'current_players', coalesce(r.current_players, 0),
              'max_players', coalesce(r.max_players, 9),
              'status', r.status,
              'is_featured', coalesce(r.is_featured, false),
              'is_new', coalesce(r.label_as_new, false),
              'club_id', r.club_id,
              'club_name', CASE WHEN coalesce(r.hide_club_name, false) THEN NULL ELSE r.club_name END,
              'club_slug', r.club_slug,
              'club_is_union', coalesce(r.club_is_union, false),
              'match_score', round(r.score::numeric, 3)
            ) ORDER BY r.ord), '[]'::jsonb) FROM ranked r WHERE r.ord <= v_limit)
      INTO v_table_total, v_tables;
  END IF;

  -- TOURNAMENTS (announced, registering, running)
  IF p_scope IN ('all', 'tournaments') THEN
    WITH visible AS (
      SELECT t.id, t.name, t.status, t.tournament_type, t.variant, t.game_type,
             t.buy_in_amount, t.buy_in_fee, t.guaranteed_prize, t.prize_pool,
             t.current_players, t.max_players, t.start_time, t.club_id, t.union_id,
             t.is_bounty, t.is_pko, t.is_mystery_bounty, t.is_turbo, t.hide_club_name,
             c.name AS club_name, c.slug AS club_slug
        FROM public.tournaments t
        LEFT JOIN public.clubs c ON c.id = t.club_id
       WHERE t.status IN ('ANNOUNCED', 'REGISTERING', 'RUNNING')
         AND (
           coalesce(t.is_private, false) = false
           OR t.club_id IS NULL
           OR public.is_club_member(t.club_id, v_uid)
           OR c.owner_id = v_uid
         )
    ),
    matched AS (
      SELECT v.*,
             coalesce(
               public.fn_community_search_score(
                 concat_ws(' ', v.name, v.variant, v.game_type, v.tournament_type), v_tokens, v_fuzzy),
               0.7 * public.fn_community_search_score(
                 concat_ws(' ', v.name, v.variant, v.game_type, v.tournament_type, v.club_name), v_tokens, v_fuzzy)
             ) AS score
        FROM visible v
    ),
    ranked AS (
      SELECT m.*,
             row_number() OVER (
               ORDER BY m.score DESC,
                        CASE m.status WHEN 'RUNNING' THEN 0 WHEN 'REGISTERING' THEN 1 ELSE 2 END,
                        m.start_time ASC NULLS LAST, m.name
             ) AS ord
        FROM matched m
       WHERE m.score IS NOT NULL
    )
    SELECT (SELECT count(*) FROM ranked)::integer,
           (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'id', r.id,
              'name', r.name,
              'status', r.status,
              'tournament_type', r.tournament_type,
              'variant', r.variant,
              'buy_in_amount', coalesce(r.buy_in_amount, 0),
              'buy_in_fee', coalesce(r.buy_in_fee, 0),
              'guaranteed_prize', coalesce(r.guaranteed_prize, 0),
              'prize_pool', coalesce(r.prize_pool, 0),
              'current_players', coalesce(r.current_players, 0),
              'max_players', r.max_players,
              'start_time', r.start_time,
              'is_bounty', coalesce(r.is_bounty, false) OR coalesce(r.is_pko, false) OR coalesce(r.is_mystery_bounty, false),
              'is_turbo', coalesce(r.is_turbo, false),
              'club_id', r.club_id,
              'club_name', CASE WHEN coalesce(r.hide_club_name, false) THEN NULL ELSE r.club_name END,
              'club_slug', r.club_slug,
              'is_registered', EXISTS (
                SELECT 1 FROM public.tournament_players tp
                 WHERE tp.tournament_id = r.id AND tp.user_id = v_uid
                   AND tp.status IN ('registered', 'playing')
              ),
              'match_score', round(r.score::numeric, 3)
            ) ORDER BY r.ord), '[]'::jsonb) FROM ranked r WHERE r.ord <= v_limit)
      INTO v_tournament_total, v_tournaments;
  END IF;

  RETURN jsonb_build_object(
    'query', v_query,
    'scope', p_scope,
    'fuzzy', v_fuzzy,
    'limit', v_limit,
    'clubs', v_clubs,
    'tables', v_tables,
    'tournaments', v_tournaments,
    'totals', jsonb_build_object(
      'clubs', v_club_total, 'tables', v_table_total, 'tournaments', v_tournament_total
    ),
    'index_health', v_health
  );
END;
$$;


ALTER FUNCTION public.fn_community_search(p_query text, p_scope text, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_community_search(p_query text, p_scope text, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_community_search(p_query text, p_scope text, p_limit integer) IS 'Club Arena /search: ranked trigram-fuzzy search over clubs (union-aware live member counts, resolved logos), open tables and live tournaments, plus per-index live health counts. Players come from fn_search_players.';


--
-- Name: fn_community_search_score(text, text[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_community_search_score(p_hay text, p_tokens text[], p_fuzzy boolean) RETURNS real
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH hay AS (
    SELECT lower(coalesce(p_hay, '')) AS h
  ),
  per AS (
    SELECT
      CASE
        WHEN position(t IN h) > 0 THEN
          CASE
            WHEN h = t THEN 1.0
            WHEN h LIKE t || '%' OR h LIKE '% ' || t || '%' THEN 0.95
            ELSE 0.85
          END
        WHEN p_fuzzy AND length(t) >= 3 AND word_similarity(t, h) >= 0.5 THEN
          0.4 + 0.4 * word_similarity(t, h)
        ELSE NULL
      END AS s
    FROM hay, unnest(coalesce(p_tokens, '{}'::text[])) AS t
  )
  SELECT CASE
           WHEN count(*) = 0 OR bool_or(s IS NULL) THEN NULL
           ELSE avg(s)::real
         END
    FROM per;
$$;


ALTER FUNCTION public.fn_community_search_score(p_hay text, p_tokens text[], p_fuzzy boolean) OWNER TO postgres;

--
-- Name: FUNCTION fn_community_search_score(p_hay text, p_tokens text[], p_fuzzy boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_community_search_score(p_hay text, p_tokens text[], p_fuzzy boolean) IS 'Community search matching rule. NULL = no match; otherwise 0..1 relevance. Every token must match (substring, or trigram word_similarity >= 0.5 when fuzzy).';


--
-- Name: fn_complete_cashout(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_cashout(p_cashout_id uuid, p_completed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_cashout RECORD;
BEGIN
  SELECT * INTO v_cashout FROM cashout_requests WHERE id = p_cashout_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Not found'); END IF;
  IF v_cashout.status NOT IN ('pending', 'approved') THEN RETURN jsonb_build_object('success', false, 'error', 'Already ' || v_cashout.status); END IF;
  UPDATE cashout_requests SET status = 'completed', completed_at = NOW(), updated_at = NOW() WHERE id = p_cashout_id;
  RETURN jsonb_build_object('success', true, 'cashout_id', p_cashout_id, 'amount', v_cashout.amount, 'status', 'completed');
END;
$$;


ALTER FUNCTION public.fn_complete_cashout(p_cashout_id uuid, p_completed_by uuid) OWNER TO postgres;

--
-- Name: fn_complete_club_opening_setup(uuid, uuid, text, numeric, numeric, boolean, numeric, boolean, numeric, numeric, boolean, text, text, text, numeric, boolean, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_club_opening_setup(p_club_id uuid, p_operation_id uuid, p_tagline text, p_rake_percent numeric, p_rake_cap_bb numeric, p_bbj_enabled boolean, p_bbj_seed numeric, p_spins_enabled boolean, p_spin_seed numeric, p_spin_max_stake numeric, p_promo_enabled boolean, p_promo_type text, p_promo_name text, p_promo_description text, p_promo_budget numeric, p_leaderboard_rewards_enabled boolean, p_leaderboard_metric text, p_leaderboard_prize_budget numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_club public.clubs%ROWTYPE;
  v_existing public.club_opening_setups%ROWTYPE;
  v_is_platform_admin boolean := false;
  v_rake numeric := round(COALESCE(p_rake_percent, -1), 2);
  v_cap numeric := round(COALESCE(p_rake_cap_bb, -1), 2);
  v_bbj_seed numeric := round(COALESCE(p_bbj_seed, 0), 2);
  v_spin_seed numeric := round(COALESCE(p_spin_seed, 0), 2);
  v_promo_budget numeric := round(COALESCE(p_promo_budget, 0), 2);
  v_leaderboard_budget numeric := round(COALESCE(p_leaderboard_prize_budget, 0), 2);
  v_spin_required numeric := 0;
  v_other_allocation numeric := 0;
  v_total_allocation numeric := 0;
  v_spin_result jsonb := '{}'::jsonb;
  v_pool_id uuid;
  v_bbj_after numeric := 0;
  v_promo_after numeric := 0;
  v_promotion_id uuid;
  v_leaderboard_result jsonb := '{}'::jsonb;
  v_bank_after numeric := 0;
  v_result jsonb;
  v_tagline text := left(regexp_replace(btrim(COALESCE(p_tagline, '')), '\s+', ' ', 'g'), 72);
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication Required';
  END IF;
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'Operation ID Is Required';
  END IF;

  SELECT * INTO v_club FROM public.clubs WHERE id = p_club_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Club Not Found';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = v_actor AND p.role IN ('admin', 'superadmin', 'god')
  ) INTO v_is_platform_admin;

  IF v_club.owner_id IS DISTINCT FROM v_actor AND NOT v_is_platform_admin THEN
    RAISE EXCEPTION 'Only The Club Owner Can Complete Opening Setup';
  END IF;
  IF COALESCE(v_club.is_union, false) OR v_club.union_id IS NOT NULL THEN
    RAISE EXCEPTION 'Union-Owned Economics Must Be Configured By The Union Lead';
  END IF;

  IF char_length(v_tagline) < 3 THEN
    RAISE EXCEPTION 'Write A Custom Club Tag Line Before Completing Setup';
  END IF;
  IF v_tagline ILIKE '%all fish of all shapes and sizes are welcome%'
     AND v_club.club_id <> 25450 THEN
    RAISE EXCEPTION 'That Tag Line Belongs To Shark Club';
  END IF;

  SELECT * INTO v_existing
  FROM public.club_opening_setups
  WHERE club_id = p_club_id
  FOR UPDATE;

  IF FOUND THEN
    v_result := jsonb_build_object(
      'success', true,
      'already_completed', true,
      'club_id', p_club_id,
      'club_bank_after', v_club.chip_treasury,
      'completed_at', v_existing.completed_at,
      'operation_id', v_existing.last_operation_id
    );
    RETURN v_result;
  END IF;

  IF v_rake <> -1 AND (v_rake < 0 OR v_rake > 10) THEN
    RAISE EXCEPTION 'Rake Must Use The House Schedule Or Be Between 0 And 10 Percent';
  END IF;
  IF v_cap <> -1 AND (v_cap < 0 OR v_cap > 10) THEN
    RAISE EXCEPTION 'Rake Cap Must Use The House Schedule Or Be Between 0 And 10 Big Blinds';
  END IF;

  IF p_bbj_enabled AND v_bbj_seed < 100 THEN
    RAISE EXCEPTION 'BBJ Requires A Minimum 100-Chip Seed';
  END IF;
  IF NOT p_bbj_enabled THEN
    v_bbj_seed := 0;
  END IF;

  IF p_spins_enabled THEN
    IF p_spin_max_stake NOT IN (1, 2, 3, 5, 10, 20, 50, 100) THEN
      RAISE EXCEPTION 'Spin Maximum Stake Is Not A Supported Board Stake';
    END IF;
    v_spin_required := public.fn_spin_required_seed(p_spin_max_stake);
    IF v_spin_seed < GREATEST(100, v_spin_required) THEN
      RAISE EXCEPTION 'Spin Seed Must Be At Least % Chips For The Selected Board',
        GREATEST(100, v_spin_required);
    END IF;
  ELSE
    v_spin_seed := 0;
  END IF;

  IF p_promo_enabled THEN
    IF p_promo_type NOT IN ('leaderboard', 'rake_race', 'milestone', 'mystery', 'high_hand') THEN
      RAISE EXCEPTION 'Promotion Type Is Not Supported';
    END IF;
    IF length(btrim(COALESCE(p_promo_name, ''))) < 3 THEN
      RAISE EXCEPTION 'Promotion Name Must Be At Least 3 Characters';
    END IF;
    IF v_promo_budget < 100 THEN
      RAISE EXCEPTION 'A New Promotion Requires A Minimum 100-Chip Budget';
    END IF;
  ELSE
    v_promo_budget := 0;
  END IF;

  IF p_leaderboard_metric NOT IN ('profit', 'hands_played', 'tournaments_won', 'roi') THEN
    RAISE EXCEPTION 'Leaderboard Metric Is Not Supported';
  END IF;
  IF p_leaderboard_rewards_enabled THEN
    IF v_leaderboard_budget < 100 THEN
      RAISE EXCEPTION 'A Prize Leaderboard Requires A Minimum 100-Chip Budget';
    END IF;
  ELSE
    v_leaderboard_budget := 0;
  END IF;

  v_other_allocation := v_bbj_seed + v_promo_budget + v_leaderboard_budget;
  v_total_allocation := v_other_allocation + v_spin_seed;
  IF COALESCE(v_club.chip_treasury, 0) < v_total_allocation THEN
    RAISE EXCEPTION 'Club Bank Has % Chips But Setup Requires %',
      COALESCE(v_club.chip_treasury, 0), v_total_allocation;
  END IF;

  -- Spin activation owns its wallet debit, reserve credit, repayment metadata,
  -- and reserve ledger. Calling it inside this function keeps all setup steps
  -- in the same database transaction.
  IF p_spins_enabled THEN
    v_spin_result := public.fn_spin_activate(
      p_club_id,
      v_spin_seed,
      p_spin_max_stake,
      'chip_treasury',
      v_actor
    );
    IF NOT COALESCE((v_spin_result ->> 'ok')::boolean, false) THEN
      RAISE EXCEPTION 'Spin Setup Failed: %', COALESCE(v_spin_result ->> 'reason', 'Unknown Reason');
    END IF;

    INSERT INTO public.club_opening_setup_funding
      (club_id, operation_id, destination, amount, balance_after, created_by)
    VALUES (
      p_club_id, p_operation_id, 'spin_reserve', v_spin_seed,
      COALESCE((v_spin_result ->> 'balance')::numeric, v_spin_seed), v_actor
    );
  END IF;

  PERFORM set_config('app.ledger_category', 'club_opening_allocation', true);
  PERFORM set_config('app.ledger_counterparty', 'opening_setup', true);
  PERFORM set_config('app.ledger_counterparty_entity', p_club_id::text, true);

  UPDATE public.clubs
  SET chip_treasury = COALESCE(chip_treasury, 0) - v_other_allocation,
      promo_balance = COALESCE(promo_balance, 0) + v_promo_budget,
      tagline = v_tagline,
      default_rake_percent = v_rake,
      rake_cap = v_cap,
      bbj_enabled = p_bbj_enabled,
      bbj_rake_enabled = p_bbj_enabled,
      spins_enabled = p_spins_enabled,
      spins_preseed_amount = v_spin_seed,
      spins_wallet_funding = 'CHIP_TREASURY',
      updated_at = now()
  WHERE id = p_club_id
  RETURNING chip_treasury, promo_balance INTO v_bank_after, v_promo_after;

  IF p_bbj_enabled THEN
    SELECT pool.id INTO v_pool_id
    FROM public.bbj_pools pool
    WHERE pool.club_id = p_club_id AND pool.union_id IS NULL
    ORDER BY (pool.status = 'active') DESC, pool.created_at
    LIMIT 1
    FOR UPDATE;

    IF v_pool_id IS NULL THEN
      INSERT INTO public.bbj_pools
        (club_id, main_balance, backup_balance, promo_balance, pool_amount, status)
      VALUES (p_club_id, v_bbj_seed, 0, 0, 0, 'active')
      RETURNING id, main_balance INTO v_pool_id, v_bbj_after;
    ELSE
      UPDATE public.bbj_pools
      SET main_balance = main_balance + v_bbj_seed,
          status = 'active',
          updated_at = now()
      WHERE id = v_pool_id
      RETURNING main_balance INTO v_bbj_after;
    END IF;

    INSERT INTO public.club_opening_setup_funding
      (club_id, operation_id, destination, amount, balance_after, created_by)
    VALUES (p_club_id, p_operation_id, 'bbj_main', v_bbj_seed, v_bbj_after, v_actor);
  END IF;

  IF p_promo_enabled THEN
    INSERT INTO public.promotions (
      club_id, name, description, type, start_date, end_date, status,
      prize_pool, requirements, opt_in_required
    ) VALUES (
      p_club_id,
      left(btrim(p_promo_name), 80),
      left(btrim(COALESCE(p_promo_description, '')), 500),
      p_promo_type,
      now(),
      now() + interval '30 days',
      'active',
      v_promo_budget,
      'Created During Club Opening Setup',
      true
    ) RETURNING id INTO v_promotion_id;

    INSERT INTO public.club_opening_setup_funding
      (club_id, operation_id, destination, amount, balance_after, created_by)
    VALUES (p_club_id, p_operation_id, 'promo_wallet', v_promo_budget, v_promo_after, v_actor);
  END IF;

  -- Leaderboards always receive an explicit setup row. Display-only is the
  -- safe launch default; a paid program publishes a balanced weekly top-three
  -- plan and its declared budget has already been placed in the promo wallet.
  v_leaderboard_result := public.fn_publish_leaderboard_reward_program(
    p_club_id,
    p_leaderboard_rewards_enabled,
    p_leaderboard_metric,
    CASE WHEN p_leaderboard_rewards_enabled THEN jsonb_build_array(
      jsonb_build_object('rank', 1, 'amount', round(v_leaderboard_budget * 0.50, 2)),
      jsonb_build_object('rank', 2, 'amount', round(v_leaderboard_budget * 0.30, 2)),
      jsonb_build_object('rank', 3, 'amount', v_leaderboard_budget
        - round(v_leaderboard_budget * 0.50, 2)
        - round(v_leaderboard_budget * 0.30, 2))
    ) ELSE '[]'::jsonb END,
    '[]'::jsonb,
    'balanced',
    0,
    p_operation_id
  );

  IF p_leaderboard_rewards_enabled THEN
    INSERT INTO public.club_opening_setup_funding
      (club_id, operation_id, destination, amount, balance_after, created_by)
    VALUES (
      p_club_id, p_operation_id, 'leaderboard_prizes',
      v_leaderboard_budget, v_leaderboard_budget, v_actor
    );
  END IF;

  INSERT INTO public.club_opening_setups (
    club_id, owner_id, rake_mode, rake_percent, rake_cap_bb,
    bbj_enabled, bbj_seeded_amount,
    spins_enabled, spin_seeded_amount, spin_max_stake,
    promo_enabled, promo_budget, promotion_id,
    leaderboard_rewards_enabled, leaderboard_metric, leaderboard_prize_budget,
    leaderboard_seed_remaining,
    last_operation_id
  ) VALUES (
    p_club_id, v_club.owner_id,
    CASE WHEN v_rake = -1 AND v_cap = -1 THEN 'house_schedule' ELSE 'custom' END,
    v_rake, v_cap,
    p_bbj_enabled, v_bbj_seed,
    p_spins_enabled, v_spin_seed, CASE WHEN p_spins_enabled THEN p_spin_max_stake ELSE 0 END,
    p_promo_enabled, v_promo_budget, v_promotion_id,
    p_leaderboard_rewards_enabled, p_leaderboard_metric, v_leaderboard_budget,
    v_leaderboard_budget,
    p_operation_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'already_completed', false,
    'club_id', p_club_id,
    'club_bank_after', v_bank_after,
    'allocated', v_total_allocation,
    'bbj_seeded', v_bbj_seed,
    'spin_seeded', v_spin_seed,
    'promo_budget', v_promo_budget,
    'promotion_id', v_promotion_id,
    'leaderboard_rewards_enabled', p_leaderboard_rewards_enabled,
    'leaderboard_prize_budget', v_leaderboard_budget,
    'leaderboard', v_leaderboard_result,
    'spin', v_spin_result,
    'operation_id', p_operation_id
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_complete_club_opening_setup(p_club_id uuid, p_operation_id uuid, p_tagline text, p_rake_percent numeric, p_rake_cap_bb numeric, p_bbj_enabled boolean, p_bbj_seed numeric, p_spins_enabled boolean, p_spin_seed numeric, p_spin_max_stake numeric, p_promo_enabled boolean, p_promo_type text, p_promo_name text, p_promo_description text, p_promo_budget numeric, p_leaderboard_rewards_enabled boolean, p_leaderboard_metric text, p_leaderboard_prize_budget numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_complete_club_opening_setup(p_club_id uuid, p_operation_id uuid, p_tagline text, p_rake_percent numeric, p_rake_cap_bb numeric, p_bbj_enabled boolean, p_bbj_seed numeric, p_spins_enabled boolean, p_spin_seed numeric, p_spin_max_stake numeric, p_promo_enabled boolean, p_promo_type text, p_promo_name text, p_promo_description text, p_promo_budget numeric, p_leaderboard_rewards_enabled boolean, p_leaderboard_metric text, p_leaderboard_prize_budget numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_complete_club_opening_setup(p_club_id uuid, p_operation_id uuid, p_tagline text, p_rake_percent numeric, p_rake_cap_bb numeric, p_bbj_enabled boolean, p_bbj_seed numeric, p_spins_enabled boolean, p_spin_seed numeric, p_spin_max_stake numeric, p_promo_enabled boolean, p_promo_type text, p_promo_name text, p_promo_description text, p_promo_budget numeric, p_leaderboard_rewards_enabled boolean, p_leaderboard_metric text, p_leaderboard_prize_budget numeric) IS 'Owner-only, one-time Club Opening Wizard commit. Configures rake, optionally seeds BBJ and Spins, optionally funds the first promotion, explicitly publishes a display-only or prize leaderboard plan, records immutable funding evidence, and rolls every step back on failure.';


--
-- Name: fn_complete_media_upload(uuid, integer, integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_media_upload(p_media_id uuid, p_width integer DEFAULT NULL::integer, p_height integer DEFAULT NULL::integer, p_duration_seconds numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text;
  v_caller_uid uuid;
  v_owner uuid;
  v_rowcount integer := 0;
BEGIN
  IF p_media_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'media_id required');
  END IF;

  v_caller_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '');
  v_caller_uid := auth.uid();

  SELECT uploader_id INTO v_owner FROM public.social_media WHERE id = p_media_id;
  IF v_owner IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'media not found');
  END IF;

  IF v_caller_role = 'authenticated' THEN
    IF v_caller_uid IS NULL OR v_owner <> v_caller_uid THEN
      RAISE WARNING 'fn_complete_media_upload: % is not owner of media %', v_caller_uid, p_media_id;
      RETURN jsonb_build_object('success', false, 'error', 'forbidden');
    END IF;
  ELSIF v_caller_role = 'anon' OR v_caller_role = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'unauthorized');
  END IF;

  UPDATE public.social_media
  SET
    width = COALESCE(p_width, width),
    height = COALESCE(p_height, height),
    duration_seconds = COALESCE(p_duration_seconds, duration_seconds)
  WHERE id = p_media_id;

  GET DIAGNOSTICS v_rowcount = ROW_COUNT;

  RETURN jsonb_build_object('success', v_rowcount > 0, 'media_id', p_media_id);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_complete_media_upload failed for media %: % %', p_media_id, SQLERRM, SQLSTATE;
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION public.fn_complete_media_upload(p_media_id uuid, p_width integer, p_height integer, p_duration_seconds numeric) OWNER TO postgres;

--
-- Name: fn_complete_tournament_entry_reprice(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_tournament_entry_reprice(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_receipt public.tournament_entry_close_receipts%ROWTYPE;
  v_mismatch integer;
BEGIN
  -- Match the lock order used by close/finalize and the satellite entitlement
  -- workflow: tournament first, then its child receipt. Taking these in the
  -- opposite order lets a close replay (tournament -> receipt) deadlock a
  -- completion attempt (receipt -> tournament) exactly when recovery is trying
  -- to prove the durable obligation complete.
  SELECT * INTO v_t
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','not_found'); END IF;

  SELECT * INTO v_receipt
    FROM public.tournament_entry_close_receipts r
   WHERE r.tournament_id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','receipt_missing'); END IF;
  IF v_receipt.reprice_completed_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok',true,'already_completed',true,'mismatches',0);
  END IF;
  IF COALESCE(v_t.prize_pool_finalized,false) IS NOT TRUE
     OR round(COALESCE(v_t.prize_pool,0),2)<>round(v_receipt.final_prize_pool,2)
     OR public.fn_safe_jsonb_array(v_t.payout_structure::text)
        IS DISTINCT FROM v_receipt.payout_structure_snapshot THEN
    RETURN jsonb_build_object('ok',false,'reason','final_pool_or_structure_drifted');
  END IF;

  SELECT count(*)::integer INTO v_mismatch
    FROM public.tournament_players tp
    CROSS JOIN LATERAL (
      SELECT public.fn_tournament_place_prize_exact(
        v_receipt.final_prize_pool,
        v_receipt.payout_structure_snapshot::text,
        tp.position) AS expected
    ) entitlement
   WHERE tp.tournament_id=p_tournament_id
     AND tp.status='eliminated'
     AND (
       -- An eliminated row without its finishing place is unfinished causal
       -- work, not a zero-dollar entitlement. Letting it disappear from this
       -- proof would retire the close receipt before any later process can
       -- know which place must be repriced.
       tp.position IS NULL
       OR round(COALESCE(tp.prize,0),2) IS DISTINCT FROM round(entitlement.expected,2)
       OR (
         entitlement.expected>0
         AND (
           SELECT round(COALESCE(sum(p.amount),0),2)
             FROM public.tournament_payouts p
            WHERE p.tournament_id=p_tournament_id
              AND p.user_id=tp.user_id
              AND p.position=tp.position
              AND COALESCE(p.source,'')<>'satellite_seat'
         ) IS DISTINCT FROM round(entitlement.expected,2)
       )
     );
  IF v_mismatch>0 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','reprice_incomplete','mismatches',v_mismatch);
  END IF;

  UPDATE public.tournament_entry_close_receipts
     SET reprice_completed_at=clock_timestamp(),updated_at=clock_timestamp()
   WHERE tournament_id=p_tournament_id;
  RETURN jsonb_build_object('ok',true,'completed',true,'mismatches',0);
END;
$$;


ALTER FUNCTION public.fn_complete_tournament_entry_reprice(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_complete_tournament_launch_atomic(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_tournament_launch_atomic(p_tournament_id uuid, p_launch_id uuid, p_lease_generation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_current_generation uuid;
  v_protocol_version integer;
  v_heartbeat_at timestamptz;
  v_receipt_generation uuid;
  v_receipt_launch_id uuid;
  v_result jsonb;
BEGIN
  IF p_tournament_id IS NULL OR p_launch_id IS NULL OR p_lease_generation IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_launch_request');
  END IF;

  SELECT l.lease_generation, l.protocol_version, l.heartbeat_at
    INTO v_current_generation, v_protocol_version, v_heartbeat_at
    FROM public.engine_tournament_leases l
   WHERE l.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND
     OR v_protocol_version IS DISTINCT FROM 2
     OR v_current_generation IS DISTINCT FROM p_lease_generation
     OR v_heartbeat_at < clock_timestamp() - interval '30 seconds' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'launch_lease_lost');
  END IF;

  SELECT r.launch_id, r.lease_generation
    INTO v_receipt_launch_id, v_receipt_generation
    FROM public.tournament_launch_receipts r
   WHERE r.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND
     OR v_receipt_launch_id IS DISTINCT FROM p_launch_id
     OR v_receipt_generation IS DISTINCT FROM p_lease_generation THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'launch_receipt_mismatch');
  END IF;

  v_result := public.fn_complete_tournament_launch_before_lease_generation(
    p_tournament_id,
    p_launch_id
  );
  RETURN v_result || jsonb_build_object('lease_generation', p_lease_generation);
END;
$$;


ALTER FUNCTION public.fn_complete_tournament_launch_atomic(p_tournament_id uuid, p_launch_id uuid, p_lease_generation uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_complete_tournament_launch_atomic(p_tournament_id uuid, p_launch_id uuid, p_lease_generation uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_complete_tournament_launch_atomic(p_tournament_id uuid, p_launch_id uuid, p_lease_generation uuid) IS 'Completes a launch only when the current lease and incomplete receipt both match the caller generation; the lease row remains locked through RUNNING commit.';


--
-- Name: fn_complete_tournament_launch_before_lease_generation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_tournament_launch_before_lease_generation(p_tournament_id uuid, p_launch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_receipt public.tournament_launch_receipts%ROWTYPE;
  v_status text;
  v_started_at timestamptz;
  v_completed_at timestamptz := transaction_timestamp();
  v_required_field integer;
  v_active_count bigint;
  v_bad_roster_count bigint;
  v_live_seat_count bigint;
  v_bad_live_seat_count bigint;
  v_distinct_live_users bigint;
  v_distinct_live_coordinates bigint;
  v_matching_roster_seats bigint;
  v_bad_table_count bigint;
  v_is_paid_spin boolean;
  v_spin_multiplier numeric;
  v_spin_ledger_count bigint;
  v_spin_ledger_multiplier numeric;
BEGIN
  SELECT * INTO v_receipt
    FROM public.tournament_launch_receipts r
   WHERE r.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND OR v_receipt.launch_id <> p_launch_id THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'launch_receipt_mismatch');
  END IF;
  IF v_receipt.completed_at IS NOT NULL THEN
    SELECT t.status, t.started_at INTO v_status, v_started_at
      FROM public.tournaments t
     WHERE t.id = p_tournament_id;
    IF NOT FOUND OR v_status <> 'RUNNING'
       OR v_started_at IS DISTINCT FROM v_receipt.started_at THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'launch_receipt_state_mismatch');
    END IF;
    RETURN jsonb_build_object(
      'ok', true,
      'completed', true,
      'replay', true,
      'status', v_status,
      'started_at', v_started_at,
      'completed_at', v_receipt.completed_at
    );
  END IF;

  SELECT t.status,
         t.started_at,
         CASE WHEN COALESCE(t.max_players, 0) > 0
              THEN GREATEST(2, LEAST(3, t.max_players))
              ELSE 3 END,
         ((lower(COALESCE(t.variant, '')) = 'spin'
           OR upper(COALESCE(t.tournament_type, '')) = 'SPIN')
          AND COALESCE(t.buy_in_amount, 0) > 0),
         t.spin_multiplier
    INTO v_status, v_started_at, v_required_field,
         v_is_paid_spin, v_spin_multiplier
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND OR v_status <> 'REGISTERING'
     OR (v_started_at IS NOT NULL AND v_started_at IS DISTINCT FROM v_receipt.started_at) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'launch_receipt_state_mismatch');
  END IF;

  /* Completion is the status transaction, so it owns the final database
     proof too. Every registration/admission path locks this tournament row:
     one that committed first is visible here and makes completion refuse;
     one waiting behind us observes RUNNING and rolls back. This removes the
     proof-to-complete race that no sequence of client reads can close. */
  SELECT count(*),
         count(*) FILTER (
           WHERE p.status <> 'playing'
              OR p.user_id IS NULL
              OR COALESCE(p.chips, 0) < 0
              OR p.table_id IS NULL
              OR p.seat_number IS NULL
              OR p.seat_number <= 0
         )
    INTO v_active_count, v_bad_roster_count
    FROM public.tournament_players p
   WHERE p.tournament_id = p_tournament_id
     AND p.status IN ('registered', 'playing');

  IF (SELECT COALESCE(sum(p2.chips), 0)
         FROM public.tournament_players p2
        WHERE p2.tournament_id = p_tournament_id
          AND p2.status IN ('registered', 'playing'))
      < v_active_count * COALESCE(
          (SELECT t2.starting_chips FROM public.tournaments t2
            WHERE t2.id = p_tournament_id), 0)
     OR (SELECT COALESCE(sum(s2.stack), 0)
           FROM public.table_seats s2
           JOIN public.tables t3 ON t3.id = s2.table_id
          WHERE t3.tournament_id = p_tournament_id
            AND s2.left_at IS NULL)
        < v_active_count * COALESCE(
            (SELECT t2.starting_chips FROM public.tournaments t2
              WHERE t2.id = p_tournament_id), 0) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'launch_stacks_uncredited',
      'active_players', v_active_count
    );
  END IF;

  IF v_is_paid_spin AND v_active_count = 2
     AND COALESCE(
       (public.fn_prove_played_spin_launch_recovery(p_tournament_id)->>'ok')::boolean,
       false
     ) THEN
    v_required_field := 2;
  END IF;

  IF v_active_count < v_required_field OR v_bad_roster_count <> 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'launch_roster_unproven',
      'active_players', v_active_count,
      'required_players', v_required_field,
      'invalid_players', v_bad_roster_count
    );
  END IF;

  SELECT count(*),
         count(*) FILTER (
           WHERE s.user_id IS NULL
              OR COALESCE(s.stack, 0) < 0
              OR s.seat_number IS NULL
              OR s.seat_number <= 0
              OR s.seat_number > COALESCE(t.max_players, 0)
         ),
         count(DISTINCT s.user_id),
         count(DISTINCT (s.table_id, s.seat_number))
    INTO v_live_seat_count, v_bad_live_seat_count,
         v_distinct_live_users, v_distinct_live_coordinates
    FROM public.table_seats s
    JOIN public.tables t ON t.id = s.table_id
   WHERE t.tournament_id = p_tournament_id
     AND s.left_at IS NULL;

  SELECT count(*) INTO v_matching_roster_seats
    FROM public.tournament_players p
    JOIN public.table_seats s
      ON s.user_id = p.user_id
     AND s.table_id = p.table_id
     AND s.seat_number = p.seat_number
     AND s.left_at IS NULL
    JOIN public.tables t
      ON t.id = s.table_id
     AND t.tournament_id = p_tournament_id
   WHERE p.tournament_id = p_tournament_id
     AND p.status IN ('registered', 'playing');

  IF v_live_seat_count <> v_active_count
     OR v_bad_live_seat_count <> 0
     OR v_distinct_live_users <> v_active_count
     OR v_distinct_live_coordinates <> v_active_count
     OR v_matching_roster_seats <> v_active_count THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'launch_seats_unproven',
      'active_players', v_active_count,
      'live_seats', v_live_seat_count,
      'matching_seats', v_matching_roster_seats
    );
  END IF;

  SELECT count(*) INTO v_bad_table_count
    FROM public.tables t
    LEFT JOIN (
      SELECT s.table_id, count(*) AS live_count
        FROM public.table_seats s
       WHERE s.left_at IS NULL
       GROUP BY s.table_id
    ) seats ON seats.table_id = t.id
   WHERE t.tournament_id = p_tournament_id
     AND (seats.table_id IS NULL
          OR t.status NOT IN ('running', 'waiting')
          OR t.current_players IS DISTINCT FROM seats.live_count);

  IF v_bad_table_count <> 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'launch_tables_unproven',
      'invalid_tables', v_bad_table_count
    );
  END IF;

  IF v_is_paid_spin THEN
    SELECT count(*), min(l.multiplier)
      INTO v_spin_ledger_count, v_spin_ledger_multiplier
      FROM public.spin_reserve_ledger l
     WHERE l.tournament_id = p_tournament_id
       AND l.kind = 'jackpot_draw';
    IF v_spin_ledger_count <> 1
       OR COALESCE(v_spin_multiplier, 0) <= 0
       OR v_spin_ledger_multiplier IS DISTINCT FROM v_spin_multiplier THEN
      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'launch_spin_settlement_unproven',
        'draw_rows', v_spin_ledger_count
      );
    END IF;
  END IF;

  PERFORM set_config(
    'app.atomic_tournament_launch',
    p_tournament_id::text || ':' || p_launch_id::text,
    true
  );
  UPDATE public.tournaments
     SET status = 'RUNNING',
         started_at = v_receipt.started_at
   WHERE id = p_tournament_id
     AND status = 'REGISTERING';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament launch status changed inside its completion transaction'
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.tournament_launch_receipts
     SET completed_at = v_completed_at
   WHERE tournament_id = p_tournament_id
     AND launch_id = p_launch_id
     AND completed_at IS NULL;
  RETURN jsonb_build_object(
    'ok', true,
    'completed', true,
    'replay', false,
    'status', 'RUNNING',
    'started_at', v_receipt.started_at,
    'completed_at', v_completed_at
  );
END;
$$;


ALTER FUNCTION public.fn_complete_tournament_launch_before_lease_generation(p_tournament_id uuid, p_launch_id uuid) OWNER TO postgres;

--
-- Name: fn_complete_tournament_terminal(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_tournament_terminal(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '45s'
    AS $$
DECLARE
  v_token uuid;
  v_result jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'terminal settlement requires service authority'
      USING ERRCODE='28000';
  END IF;
  v_token:=public.fn_ca_open_tournament_seat_exit_authority(
    p_tournament_id,'terminal_finish',NULL);
  BEGIN
    v_result:=public.fn_complete_tournament_terminal_pre_seat_guard(
      p_tournament_id,p_observed_winner_id,p_settlement_mode);
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(
      v_token,COALESCE((v_result->>'ok')::boolean,false));
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
    RAISE;
  END;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_complete_tournament_terminal(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text) OWNER TO postgres;

--
-- Name: fn_complete_tournament_terminal_pre_seat_guard(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_tournament_terminal_pre_seat_guard(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
DECLARE
  v_mode text := lower(btrim(COALESCE(p_settlement_mode,'')));
  v_t record;
  v_e public.tournament_escrow%ROWTYPE;
  v_cash jsonb;
  v_mystery jsonb;
  v_mystery_evidence jsonb;
  v_bounty jsonb;
  v_rake_result jsonb;
  v_rake record;
  v_prior_rake record;
  v_winner_id uuid;
  v_winner_count integer;
  v_is_bounty boolean;
  v_mystery_active boolean := false;
  v_mystery_stage text := 'pending';
  v_mystery_pool_cents bigint := 0;
  v_inventory_cents bigint := 0;
  v_cash_count integer;
  v_bubble_line_count integer;
  v_cash_total numeric(15,2);
  v_cash_before numeric(15,2);
  v_bounty_before numeric(15,2);
  v_bounty_total numeric(15,2);
  v_rake_total numeric(15,2);
  v_expected_fee numeric(15,2);
  v_started_status text;
  v_completed_at timestamptz;
  v_rows integer;
  v_closed_table_ids uuid[] := ARRAY[]::uuid[];
  v_source_seat_ids uuid[] := ARRAY[]::uuid[];
  v_released_seat_ids uuid[] := ARRAY[]::uuid[];
  v_closed_table_count integer := 0;
  v_source_seat_count integer := 0;
  v_released_seat_count integer := 0;
  v_event_union_id uuid;
  v_current_union_id uuid;
  v_locked_current_union_id uuid;
  v_deal_shares jsonb := '[]'::jsonb;
  v_full_payouts jsonb := '[]'::jsonb;
  v_cash_bubble jsonb := 'null'::jsonb;
  v_full_winner_amount numeric(15,2);
BEGIN
  -- All satellite and non-satellite terminal money commits use this exact
  -- first lock. It eliminates cross-event cycles on shared club, union and
  -- recipient wallets without weakening any event-local row proof.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));

  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'terminal completion requires a tournament id'
      USING ERRCODE = '22004';
  END IF;
  IF v_mode NOT IN ('places','final_table_deal') THEN
    RAISE EXCEPTION 'unknown terminal settlement mode %', p_settlement_mode
      USING ERRCODE = '22023';
  END IF;
  IF v_mode = 'places' AND p_observed_winner_id IS NULL THEN
    RAISE EXCEPTION 'places completion requires an observed winner id'
      USING ERRCODE = '22004';
  END IF;

  SELECT t.* INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;

  -- Receipt first is the replay boundary. No money authority appears above it.
  IF EXISTS (
    SELECT 1 FROM public.tournament_terminal_settlements h
     WHERE h.tournament_id = p_tournament_id
  ) THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.tournament_terminal_settlements h
       WHERE h.tournament_id = p_tournament_id
         AND h.settlement_mode = v_mode
         AND (p_observed_winner_id IS NULL
              OR h.winner_id = p_observed_winner_id)
    ) THEN
      RAISE EXCEPTION 'terminal replay parameters disagree with stored receipt for %',
        p_tournament_id USING ERRCODE = '40001';
    END IF;
    RETURN public.fn_ca_tournament_terminal_receipt(
      p_tournament_id,p_observed_winner_id);
  END IF;

  IF lower(COALESCE(v_t.variant::text,'')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type::text,'')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL
     OR v_t.satellite_target IS NOT NULL THEN
    RAISE EXCEPTION 'tournament % is a satellite; use its whole-pool authority',
      p_tournament_id USING ERRCODE = '22023';
  END IF;
  v_started_status := upper(COALESCE(v_t.status::text,''));
  IF v_started_status NOT IN ('RUNNING','COMPLETING') THEN
    RAISE EXCEPTION 'tournament % cannot complete from status % without a receipt',
      p_tournament_id,v_t.status USING ERRCODE = '55000';
  END IF;
  IF v_t.prize_pool IS NULL
     OR v_t.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_t.prize_pool < 0
     OR v_t.prize_pool IS DISTINCT FROM round(v_t.prize_pool,2)
     OR v_t.bounty_pool IS NULL
     OR v_t.bounty_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_t.bounty_pool < 0
     OR v_t.bounty_pool IS DISTINCT FROM round(v_t.bounty_pool,2) THEN
    RAISE EXCEPTION 'tournament % has malformed cash or bounty pools',
      p_tournament_id USING ERRCODE = '22003';
  END IF;

  -- Cross-event bank order is tournament -> club_wallets -> union_wallets
  -- (sorted) -> clubs, before a cash authority can apply an overlay. Rake uses
  -- club_wallets before its union/club destination; guarantee funding uses the
  -- union/club destination. Pre-owning both paths prevents two same-scope
  -- finishes from taking those shared banks in opposite order.
  v_event_union_id := CASE WHEN COALESCE(v_t.is_private,false)
                           THEN NULL ELSE v_t.union_id END;
  IF v_t.club_id IS NOT NULL THEN
    SELECT c.union_id INTO v_current_union_id
      FROM public.clubs c WHERE c.id = v_t.club_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'tournament % refers to missing club %',
        p_tournament_id,v_t.club_id USING ERRCODE = 'P0404';
    END IF;
    PERFORM 1 FROM public.club_wallets cw
     WHERE cw.club_id = v_t.club_id
     ORDER BY cw.club_id FOR NO KEY UPDATE;
    PERFORM 1 FROM public.union_wallets uw
     WHERE uw.union_id IN (
       SELECT DISTINCT x.union_id
         FROM unnest(ARRAY[v_event_union_id,v_current_union_id]::uuid[]) x(union_id)
        WHERE x.union_id IS NOT NULL)
     ORDER BY uw.union_id FOR NO KEY UPDATE;
    SELECT c.union_id INTO v_locked_current_union_id
      FROM public.clubs c
     WHERE c.id = v_t.club_id
     FOR NO KEY UPDATE;
    IF v_locked_current_union_id IS DISTINCT FROM v_current_union_id THEN
      RAISE EXCEPTION 'club % changed union while tournament % claimed terminal banks',
        v_t.club_id,p_tournament_id USING ERRCODE = '40001';
    END IF;
  END IF;

  -- Freeze every tournament-owned evidence set before the first payer. The
  -- canonical payers reacquire only rows already owned by this transaction.
  PERFORM 1 FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
   ORDER BY tp.user_id,tp.id FOR UPDATE;
  PERFORM 1 FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
   ORDER BY o.kind,o.place NULLS LAST,o.id FOR UPDATE;
  PERFORM 1 FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id ORDER BY p.id FOR SHARE;
  PERFORM 1 FROM public.tournament_guarantee_overlays g
   WHERE g.tournament_id = p_tournament_id
   ORDER BY g.tournament_id FOR UPDATE;
  -- The final-table deal authority uses this same order after its money sets.
  -- Holding these locks before any bounty or rake row prevents a reversed
  -- terminal lock chain while retaining the tournament row as the root lock.
  PERFORM 1 FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id ORDER BY tb.id FOR UPDATE;
  PERFORM 1
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY s.id FOR UPDATE OF s;
  SELECT COALESCE(array_agg(tb.id ORDER BY tb.id),ARRAY[]::uuid[])
    INTO v_closed_table_ids
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id;
  v_closed_table_count := cardinality(v_closed_table_ids);
  SELECT COALESCE(array_agg(s.id ORDER BY s.id),ARRAY[]::uuid[])
    INTO v_source_seat_ids
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id;
  v_source_seat_count := cardinality(v_source_seat_ids);
  PERFORM 1 FROM public.wallet_transactions w
   WHERE w.related_entity_id = p_tournament_id
   ORDER BY w.id FOR SHARE;
  PERFORM 1 FROM public.tournament_bounty_chests c
   WHERE c.tournament_id = p_tournament_id ORDER BY c.id FOR UPDATE;
  PERFORM 1 FROM public.tournament_bounty_awards a
   WHERE a.tournament_id = p_tournament_id ORDER BY a.id FOR UPDATE;
  PERFORM 1
    FROM public.tournament_bounty_award_recipients r
    JOIN public.tournament_bounty_awards a ON a.id = r.award_id
   WHERE a.tournament_id = p_tournament_id ORDER BY r.id FOR UPDATE OF r;
  PERFORM 1 FROM public.rake_records rr
   WHERE rr.tournament_id = p_tournament_id AND rr.is_tournament
   ORDER BY rr.id FOR SHARE;
  PERFORM 1 FROM public.tournament_rake_settlements rs
   WHERE rs.tournament_id = p_tournament_id FOR UPDATE;

  v_is_bounty := COALESCE(v_t.is_bounty,false)
              OR COALESCE(v_t.is_pko,false)
              OR COALESCE(v_t.is_mystery_bounty,false);

  SELECT round(COALESCE(sum(w.amount),0),2) INTO v_bounty_before
    FROM public.wallet_transactions w
   WHERE w.related_entity_id = p_tournament_id
     AND lower(w.category) = 'bounty';
  IF EXISTS (
    SELECT 1 FROM public.wallet_transactions w
     WHERE w.related_entity_id = p_tournament_id
       AND lower(w.category) = 'bounty'
       AND (lower(w.type) <> 'credit' OR w.amount <= 0
         OR w.amount::text IN ('NaN','Infinity','-Infinity')
         OR w.amount IS DISTINCT FROM round(w.amount,2))
  ) OR v_bounty_before < 0 OR v_bounty_before > v_t.bounty_pool
     OR COALESCE(v_t.bounty_pool_paid,0) IS DISTINCT FROM v_bounty_before THEN
    RAISE EXCEPTION 'tournament % has overpaid or contradictory bounty evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_is_bounty THEN
    IF v_t.bounty_pool <= 0 THEN
      RAISE EXCEPTION 'funded bounty tournament % has no positive bounty pool',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  ELSIF v_t.bounty_pool <> 0 OR v_bounty_before <> 0
     OR EXISTS (SELECT 1 FROM public.tournament_obligations o
                 WHERE o.tournament_id = p_tournament_id
                   AND o.kind IN ('bounty','bounty_residual','mystery_bounty'))
     OR EXISTS (SELECT 1 FROM public.tournament_bounty_chests c
                 WHERE c.tournament_id = p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_bounty_awards a
                 WHERE a.tournament_id = p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_players tp
                 WHERE tp.tournament_id = p_tournament_id
                   AND COALESCE(tp.current_bounty,0) <> 0) THEN
    RAISE EXCEPTION 'ordinary tournament % carries unfunded bounty state',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF COALESCE(v_t.is_mystery_bounty,false) THEN
    v_mystery_stage := COALESCE(v_t.mystery_bounty_stage,'');
    IF v_mystery_stage NOT IN ('pending','active','complete') THEN
      RAISE EXCEPTION 'tournament % has ambiguous mystery stage % without a receipt',
        p_tournament_id,v_t.mystery_bounty_stage USING ERRCODE = '55000';
    END IF;
    -- A rolling cutover may meet an event whose old finish path already
    -- completed the mystery inventory but never completed cash, rake or the
    -- lifecycle. Treat both active and complete as a funded mystery branch.
    -- Active is settled below; complete must already prove the entire mystery
    -- obligation and every inventory row before the wrapper can continue.
    v_mystery_active := v_mystery_stage IN ('active','complete');
    IF v_mystery_active THEN
      v_mystery_pool_cents := COALESCE(v_t.mystery_bounty_pool_cents,0);
      SELECT COALESCE(sum(c.amount_cents),0) INTO v_inventory_cents
        FROM public.tournament_bounty_chests c
       WHERE c.tournament_id = p_tournament_id;
      IF v_mystery_pool_cents <= 0
         OR v_inventory_cents IS DISTINCT FROM v_mystery_pool_cents
         OR v_mystery_pool_cents > round(v_t.bounty_pool * 100)::bigint
         OR EXISTS (
           SELECT 1 FROM public.tournament_bounty_chests c
            WHERE c.tournament_id = p_tournament_id
              AND (c.amount_cents <= 0 OR c.status NOT IN
                   ('available','reserved','revealed','paid','void')))
         OR EXISTS (
           SELECT 1 FROM public.tournament_bounty_awards a
            WHERE a.tournament_id = p_tournament_id
              AND (a.amount_cents <= 0 OR a.status NOT IN
                   ('reserved','revealed','paid','completed','void'))) THEN
        RAISE EXCEPTION 'tournament % mystery bounty inventory is not exactly funded',
          p_tournament_id USING ERRCODE = 'P0404';
      END IF;
    ELSIF COALESCE(v_t.mystery_bounty_pool_cents,0) <> 0
       OR EXISTS (SELECT 1 FROM public.tournament_bounty_chests c
                   WHERE c.tournament_id = p_tournament_id)
       OR EXISTS (SELECT 1 FROM public.tournament_bounty_awards a
                   WHERE a.tournament_id = p_tournament_id) THEN
      RAISE EXCEPTION 'pending mystery tournament % already carries inventory',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  ELSIF COALESCE(v_t.mystery_bounty_stage,'pending') <> 'pending'
     OR COALESCE(v_t.mystery_bounty_pool_cents,0) <> 0
     OR EXISTS (SELECT 1 FROM public.tournament_bounty_chests c
                 WHERE c.tournament_id = p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_bounty_awards a
                 WHERE a.tournament_id = p_tournament_id) THEN
    RAISE EXCEPTION 'non-mystery tournament % carries mystery bounty state',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT round(COALESCE(sum(p.amount),0),2) INTO v_cash_before
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id
     AND p.source NOT IN (
       'bounty','bounty_residual','own_bounty','mystery_bounty',
       'mystery_bounty_residual','satellite_seat','satellite_ticket',
       'satellite_remainder');
  IF v_cash_before < 0 OR v_cash_before > v_t.prize_pool
     OR EXISTS (SELECT 1 FROM public.tournament_payouts p
                 WHERE p.tournament_id = p_tournament_id
                   AND p.source IN
                     ('satellite_seat','satellite_ticket','satellite_remainder')) THEN
    RAISE EXCEPTION 'tournament % has invalid pre-terminal cash evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT round(COALESCE(sum(rr.rake_amount),0),2) INTO v_rake_total
    FROM public.rake_records rr
   WHERE rr.tournament_id = p_tournament_id AND rr.is_tournament;
  IF v_rake_total < 0 OR v_rake_total::text IN ('NaN','Infinity','-Infinity')
     OR v_rake_total IS DISTINCT FROM round(v_rake_total,2) THEN
    RAISE EXCEPTION 'tournament % has malformed rake records',p_tournament_id
      USING ERRCODE = 'P0404';
  END IF;

  SELECT rs.* INTO v_prior_rake FROM public.tournament_rake_settlements rs
   WHERE rs.tournament_id = p_tournament_id;
  IF FOUND THEN
    IF v_prior_rake.amount IS DISTINCT FROM v_rake_total
       OR v_prior_rake.settled_at IS NULL
       OR v_prior_rake.attributed_at IS NULL
       OR v_prior_rake.attributed_users IS NULL
       OR v_prior_rake.attributed_users < 0
       OR v_prior_rake.attribution_error IS NOT NULL
       OR lower(v_prior_rake.destination) IN ('pending','')
       OR (v_prior_rake.amount > 0 AND v_t.club_id IS NOT NULL
           AND (v_prior_rake.attributed_users < 1
             OR (v_prior_rake.destination NOT LIKE 'union:%'
                 AND v_prior_rake.destination NOT LIKE 'club_treasury:%'))) THEN
      RAISE EXCEPTION 'tournament % has a partial or unattributed prior rake row',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    v_expected_fee := 0;
  ELSE
    v_expected_fee := v_rake_total;
  END IF;

  SELECT * INTO v_e FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id FOR UPDATE;
  IF v_e.tournament_id IS NULL
     OR v_e.prize_balance IS DISTINCT FROM round(v_t.prize_pool-v_cash_before,2)
     OR v_e.bounty_balance IS DISTINCT FROM round(v_t.bounty_pool-v_bounty_before,2)
     OR v_e.fee_balance IS DISTINCT FROM v_expected_fee
     OR v_e.prize_balance < 0 OR v_e.bounty_balance < 0
     OR v_e.fee_balance < 0
     OR v_e.closed_at IS NOT NULL
     OR v_e.close_note IS NOT NULL THEN
    RAISE EXCEPTION 'tournament % escrow does not exactly fund its remaining obligations',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- Exactly one branch calls exactly one cash authority.
  IF v_mode = 'places' THEN
    v_cash := public.fn_settle_tournament_places(
      p_tournament_id,p_observed_winner_id);
  ELSE
    v_cash := public.fn_settle_tournament_final_table_deal(p_tournament_id);
  END IF;
  IF COALESCE((v_cash->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_cash->>'fully_settled')::boolean,false) IS NOT TRUE
     OR upper(COALESCE(v_cash->>'status','')) <> 'COMPLETING'
     OR jsonb_typeof(v_cash->'payouts') <> 'array'
     OR jsonb_array_length(v_cash->'payouts') < 1
     OR v_cash->>'winner_amount' IS NULL
     OR (v_cash->>'winner_amount')::numeric < 0
     OR (v_cash->>'winner_amount')::numeric IS DISTINCT FROM
          round((v_cash->>'winner_amount')::numeric,2)
     OR (v_mode = 'final_table_deal'
         AND v_cash->>'money_path'
               IS DISTINCT FROM 'fn_settle_tournament_final_table_deal') THEN
    RAISE EXCEPTION 'tournament % cash authority returned a partial result: %',
      p_tournament_id,v_cash USING ERRCODE = 'P0404';
  END IF;

  SELECT t.* INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id FOR UPDATE;
  IF upper(COALESCE(v_t.status::text,'')) <> 'COMPLETING'
     OR COALESCE(v_t.prize_pool_finalized,false) IS NOT TRUE
     OR v_t.prize_pool IS NULL
     OR v_t.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_t.prize_pool < 0
     OR v_t.prize_pool IS DISTINCT FROM round(v_t.prize_pool,2) THEN
    RAISE EXCEPTION 'tournament % cash authority did not claim one finalized pool',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_winner_count
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status::text = 'winner' AND tp.position = 1;
  SELECT tp.user_id INTO v_winner_id
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status::text = 'winner' AND tp.position = 1;
  IF v_winner_count <> 1 OR v_winner_id IS NULL
     OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.user_id = v_winner_id
          AND (tp.eliminated_at IS NOT NULL
            OR tp.elimination_sequence IS NOT NULL))
     OR (p_observed_winner_id IS NOT NULL
         AND v_winner_id IS DISTINCT FROM p_observed_winner_id)
     OR (SELECT count(*) FROM jsonb_array_elements(v_cash->'payouts') p
          WHERE (p->>'place')::integer = 1
            AND (p->>'user_id')::uuid = v_winner_id
            AND (p->>'amount')::numeric =
                (v_cash->>'winner_amount')::numeric) <> 1 THEN
    RAISE EXCEPTION 'tournament % cash authority left an ambiguous winner',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*),round(COALESCE(sum(p.amount),0),2)
    INTO v_cash_count,v_cash_total
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id
     AND p.source NOT IN (
       'bounty','bounty_residual','own_bounty','mystery_bounty',
       'mystery_bounty_residual','satellite_seat','satellite_ticket',
       'satellite_remainder');
  IF v_cash_total IS DISTINCT FROM v_t.prize_pool
     OR EXISTS (
       SELECT 1 FROM public.tournament_payouts p
        WHERE p.tournament_id = p_tournament_id
          AND p.source NOT IN (
            'bounty','bounty_residual','own_bounty','mystery_bounty',
            'mystery_bounty_residual','satellite_seat','satellite_ticket',
            'satellite_remainder')
          AND (p.amount <= 0 OR p.amount IS DISTINCT FROM round(p.amount,2)
            OR p.idempotency_key IS NULL OR NOT EXISTS (
              SELECT 1 FROM public.wallet_credit_idempotency k
               WHERE k.key = p.idempotency_key
                 AND k.user_id = p.user_id AND k.amount = p.amount))) THEN
    RAISE EXCEPTION 'tournament % cash pool did not settle exactly',p_tournament_id
      USING ERRCODE = 'P0404';
  END IF;

  -- The deal authority returns only the still-live chop shares. That is the
  -- right presentation input for the table animation, but it is not the full
  -- prize-pool receipt when eliminated fixed places were already earned.
  -- Store both contracts explicitly: deal_shares is exactly the live chop;
  -- payouts is every non-bubble cash entitlement reconstructed from durable
  -- payout evidence and final standings. Bubble protection remains a distinct
  -- line, so sum(payouts.amount) + bubble_protection.amount is the full pool.
  IF v_mode = 'final_table_deal' THEN
    v_deal_shares := v_cash->'payouts';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'place',q.place,'user_id',q.user_id,'amount',q.amount)
           ORDER BY q.place,q.user_id),'[]'::jsonb)
    INTO v_full_payouts
    FROM (
      SELECT tp.position AS place,p.user_id,round(sum(p.amount),2) AS amount
        FROM public.tournament_payouts p
        JOIN public.tournament_players tp
          ON tp.tournament_id = p_tournament_id AND tp.user_id = p.user_id
       WHERE p.tournament_id = p_tournament_id
         AND p.source <> 'bubble_protection'
         AND p.source NOT IN (
           'bounty','bounty_residual','own_bounty','mystery_bounty',
           'mystery_bounty_residual','satellite_seat','satellite_ticket',
           'satellite_remainder')
       GROUP BY tp.position,p.user_id
    ) q;
  IF v_t.prize_pool = 0 AND v_full_payouts = '[]'::jsonb THEN
    -- The cash authority returns the derived zero-dollar winner line, but a
    -- zero payment correctly creates no tournament_payouts row.
    v_full_payouts := jsonb_build_array(jsonb_build_object(
      'place',1,'user_id',v_winner_id,'amount',0));
  END IF;
  SELECT count(*) INTO v_bubble_line_count
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id
     AND p.source = 'bubble_protection';
  IF v_bubble_line_count > 1 THEN
    RAISE EXCEPTION 'tournament % has more than one durable bubble payout line',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  SELECT jsonb_build_object(
           'user_id',p.user_id,'position',tp.position,'amount',p.amount)
    INTO v_cash_bubble
    FROM public.tournament_payouts p
    JOIN public.tournament_players tp
      ON tp.tournament_id = p_tournament_id AND tp.user_id = p.user_id
   WHERE p.tournament_id = p_tournament_id
     AND p.source = 'bubble_protection';
  v_cash_bubble := COALESCE(v_cash_bubble,'null'::jsonb);
  SELECT (p->>'amount')::numeric INTO v_full_winner_amount
    FROM jsonb_array_elements(v_full_payouts) p
   WHERE (p->>'place')::integer = 1;
  IF v_full_winner_amount IS NULL THEN
    RAISE EXCEPTION 'tournament % has no durable winner cash line',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  v_cash := v_cash || jsonb_build_object(
    'payouts',v_full_payouts,
    'deal_shares',v_deal_shares,
    'bubble_protection',v_cash_bubble,
    'winner_amount',v_full_winner_amount);

  IF v_mystery_stage = 'active' THEN
    v_mystery := public.fn_mystery_bounty_settle(
      p_tournament_id,v_winner_id);
    IF COALESCE((v_mystery->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_mystery->>'balanced')::boolean,false) IS NOT TRUE
       OR COALESCE((v_mystery->>'pool_cents')::bigint,-1)
            IS DISTINCT FROM v_mystery_pool_cents
       OR COALESCE((v_mystery->>'settled_cents')::bigint,-1)
            IS DISTINCT FROM v_mystery_pool_cents
       OR COALESCE((v_mystery->>'variance_cents')::bigint,1) <> 0 THEN
      RAISE EXCEPTION 'tournament % mystery bounty close was partial: %',
        p_tournament_id,v_mystery USING ERRCODE = 'P0404';
    END IF;
    v_mystery_evidence :=
      public.fn_ca_mystery_bounty_completion_evidence(
        p_tournament_id,v_winner_id);
    v_mystery := v_mystery || jsonb_build_object(
      'payment_evidence',v_mystery_evidence,
      'residual_paid_cents',
        (v_mystery_evidence->>'void_chest_cents')::bigint);
  ELSIF v_mystery_stage = 'complete' THEN
    -- No payer is rerun for an already-complete inventory. The preflight
    -- proved exact terminal chests, awards and mystery obligations plus their
    -- immutable credit-key intervals while all rows were locked. Store that
    -- canonical replay result before the bounty-pool finalizer checks the
    -- mystery completion receipt; this is evidence capture, not a second pay.
    v_mystery_evidence :=
      public.fn_ca_mystery_bounty_completion_evidence(
        p_tournament_id,v_winner_id);
    v_mystery := jsonb_build_object(
      'ok',true,'reason','already_complete',
      'pool_cents',v_mystery_pool_cents,
      'settled_cents',v_mystery_pool_cents,
      'unclaimed_cents',
        (v_mystery_evidence->>'void_chest_cents')::bigint,
      'residual_paid_cents',
        (v_mystery_evidence->>'void_chest_cents')::bigint,
      'balanced',true,'variance_cents',0,
      'payment_evidence',v_mystery_evidence);
    INSERT INTO public.tournament_bounty_completion_receipts
      (tournament_id,winner_user_id,mystery_settled_at,mystery_result,updated_at)
    VALUES (p_tournament_id,v_winner_id,now(),v_mystery,now())
    ON CONFLICT (tournament_id) DO UPDATE
      SET mystery_settled_at=COALESCE(
            public.tournament_bounty_completion_receipts.mystery_settled_at,
            EXCLUDED.mystery_settled_at),
          mystery_result=COALESCE(
            public.tournament_bounty_completion_receipts.mystery_result,
            EXCLUDED.mystery_result),
          winner_user_id=COALESCE(
            public.tournament_bounty_completion_receipts.winner_user_id,
            EXCLUDED.winner_user_id),
          updated_at=now();
    IF NOT EXISTS (
      SELECT 1 FROM public.tournament_bounty_completion_receipts r
       WHERE r.tournament_id=p_tournament_id
         AND r.winner_user_id=v_winner_id
         AND r.mystery_settled_at IS NOT NULL
         AND r.mystery_result IS NOT DISTINCT FROM v_mystery
    ) THEN
      RAISE EXCEPTION
        'tournament % completed mystery evidence receipt conflicts with canonical proof',
        p_tournament_id USING ERRCODE = '40001';
    END IF;
  ELSIF COALESCE(v_t.is_mystery_bounty,false) THEN
    v_mystery := jsonb_build_object(
      'ok',true,'reason','never_activated','pool_cents',0,
      'settled_cents',0,'unclaimed_cents',0,'balanced',true,
      'variance_cents',0,'residual_paid_cents',0);
  ELSE
    v_mystery := jsonb_build_object(
      'ok',true,'reason','not_a_mystery_tournament','pool_cents',0,
      'settled_cents',0,'unclaimed_cents',0,'balanced',true,
      'variance_cents',0,'residual_paid_cents',0);
  END IF;

  IF v_is_bounty THEN
    v_bounty := public.fn_finalize_bounty_pool(p_tournament_id,v_winner_id);
    IF COALESCE((v_bounty->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_bounty->>'funded')::boolean,false) IS NOT TRUE
       OR v_bounty->>'residual' IS NULL
       OR (v_bounty->>'residual')::numeric < 0 THEN
      RAISE EXCEPTION 'tournament % bounty pool close was partial: %',
        p_tournament_id,v_bounty USING ERRCODE = 'P0404';
    END IF;
  ELSE
    v_bounty := jsonb_build_object(
      'ok',true,'funded',true,'residual',0,
      'reason','not_a_bounty_tournament');
  END IF;

  SELECT t.* INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id FOR UPDATE;
  SELECT round(COALESCE(sum(w.amount),0),2) INTO v_bounty_total
    FROM public.wallet_transactions w
   WHERE w.related_entity_id = p_tournament_id
     AND lower(w.category) = 'bounty';
  IF v_bounty_total IS DISTINCT FROM v_t.bounty_pool
     OR COALESCE(v_t.bounty_pool_paid,0) IS DISTINCT FROM v_t.bounty_pool
     OR EXISTS (SELECT 1 FROM public.wallet_transactions w
                 WHERE w.related_entity_id = p_tournament_id
                   AND lower(w.category) = 'bounty'
                   AND (lower(w.type) <> 'credit' OR w.amount <= 0
                     OR w.amount IS DISTINCT FROM round(w.amount,2)))
     OR EXISTS (SELECT 1 FROM public.tournament_obligations o
                 WHERE o.tournament_id = p_tournament_id
                   AND (o.amount_paid IS DISTINCT FROM o.amount_owed
                     OR o.settled_at IS NULL))
     OR EXISTS (SELECT 1 FROM public.tournament_bounty_chests c
                 WHERE c.tournament_id = p_tournament_id
                   AND c.status NOT IN ('paid','void'))
     OR EXISTS (SELECT 1 FROM public.tournament_bounty_awards a
                 WHERE a.tournament_id = p_tournament_id
                   AND a.status NOT IN ('completed','void'))
     OR (v_mystery_active AND (
          v_mystery_evidence IS NULL
          OR COALESCE((v_mystery_evidence->>'pool_cents')::bigint,-1)
               IS DISTINCT FROM v_mystery_pool_cents
          OR COALESCE((v_mystery_evidence->>'legacy_credit_cents')::bigint,-1)
             + COALESCE((v_mystery_evidence->>'obligation_cents')::bigint,-1)
               IS DISTINCT FROM v_mystery_pool_cents))
     OR EXISTS (
       SELECT 1 FROM public.tournament_bounty_awards a
        WHERE a.tournament_id = p_tournament_id
          AND a.status = 'completed'
          AND (a.paid_at IS NULL
            OR (SELECT COALESCE(sum(r.amount_cents),0)
                  FROM public.tournament_bounty_award_recipients r
                 WHERE r.award_id = a.id) <> a.amount_cents
            OR EXISTS (SELECT 1
                         FROM public.tournament_bounty_award_recipients r
                        WHERE r.award_id = a.id
                          AND r.amount_cents > 0 AND r.paid_at IS NULL))) THEN
    RAISE EXCEPTION 'tournament % bounty obligations or chests remain open',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- current_bounty is the live head/cache, not payment evidence. The older
  -- finalizer clears only the champion when it itself pays a positive ordinary
  -- residual; an already-exhausted pool or mystery residual can therefore
  -- leave a stale live head after every chip is durably paid. Once exact pool,
  -- obligation and inventory conservation is proved above, zero every head in
  -- this same terminal commit so no completed player advertises open value.
  IF v_is_bounty THEN
    UPDATE public.tournament_players
       SET current_bounty = 0
     WHERE tournament_id = p_tournament_id
       AND COALESCE(current_bounty,0) <> 0;
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND COALESCE(tp.current_bounty,0) <> 0) THEN
    RAISE EXCEPTION 'tournament % still has a live bounty head after close',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT * INTO v_e FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id FOR UPDATE;
  IF v_e.tournament_id IS NULL
     OR v_e.prize_balance IS DISTINCT FROM 0::numeric
     OR v_e.bounty_balance IS DISTINCT FROM 0::numeric
     OR v_e.fee_balance IS DISTINCT FROM v_expected_fee THEN
    RAISE EXCEPTION 'tournament % cash/bounty close did not preserve fee escrow',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  v_rake_result := public.fn_settle_tournament_rake(
    p_tournament_id,'engine.fn_complete_tournament_terminal');
  IF COALESCE((v_rake_result->>'ok')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'tournament % rake authority refused: %',
      p_tournament_id,v_rake_result USING ERRCODE = 'P0404';
  END IF;
  SELECT rs.* INTO v_rake FROM public.tournament_rake_settlements rs
   WHERE rs.tournament_id = p_tournament_id FOR UPDATE;
  IF v_rake.tournament_id IS NULL
     OR v_rake.amount IS DISTINCT FROM v_rake_total
     OR v_rake.settled_at IS NULL OR v_rake.attributed_at IS NULL
     OR v_rake.attributed_users IS NULL OR v_rake.attributed_users < 0
     OR v_rake.attribution_error IS NOT NULL
     OR lower(v_rake.destination) IN ('pending','')
     OR (v_rake.amount > 0 AND v_t.club_id IS NOT NULL
         AND (v_rake.attributed_users < 1
           OR (v_rake.destination NOT LIKE 'union:%'
               AND v_rake.destination NOT LIKE 'club_treasury:%'))) THEN
    RAISE EXCEPTION 'tournament % rake attribution did not complete: %',
      p_tournament_id,v_rake_result USING ERRCODE = 'P0404';
  END IF;

  SELECT * INTO v_e FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id FOR UPDATE;
  IF v_e.tournament_id IS NULL
     OR v_e.prize_balance IS DISTINCT FROM 0::numeric
     OR v_e.bounty_balance IS DISTINCT FROM 0::numeric
     OR v_e.fee_balance IS DISTINCT FROM 0::numeric THEN
    RAISE EXCEPTION 'tournament % did not close all three escrow banks',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  v_completed_at := COALESCE(v_t.ended_at,transaction_timestamp());
  -- Persist the exact-zero proof before lifecycle. The historical after-status
  -- observer was detached above; this authority is now the only owner of the
  -- terminal escrow marker.
  UPDATE public.tournament_escrow
     SET closed_at = v_completed_at,
         close_note = 'terminal receipt: exact zero',
         updated_at = now()
   WHERE tournament_id = p_tournament_id
     AND prize_balance = 0 AND bounty_balance = 0 AND fee_balance = 0;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'tournament % lost its exact zero escrow close',
      p_tournament_id USING ERRCODE = '40001';
  END IF;

  -- Explicitly release every live seat and close every tournament table in
  -- this transaction. No timer, table manager or lifecycle watcher is part of
  -- the completion contract. IDs and counts are captured for immutable replay.
  WITH released AS (
    UPDATE public.table_seats s
       SET left_at = v_completed_at,
           status = 'left',
           leave_pending = false,
           is_sitting_out = false,
           is_away = false,
           sit_out_at = NULL,
           scheduled_leave_hands = NULL
      FROM public.tables tb
     WHERE tb.id = s.table_id
       AND tb.tournament_id = p_tournament_id
       AND s.left_at IS NULL
    RETURNING s.id
  )
  SELECT COALESCE(array_agg(r.id ORDER BY r.id),ARRAY[]::uuid[])
    INTO v_released_seat_ids
    FROM released r;
  v_released_seat_count := cardinality(v_released_seat_ids);

  -- Preserve an earlier departure time, but canonicalize every other mutable
  -- occupancy flag before the immutable source-seat snapshot is committed.
  UPDATE public.table_seats s
     SET status = 'left',
         leave_pending = false,
         is_sitting_out = false,
         is_away = false,
         sit_out_at = NULL,
         scheduled_leave_hands = NULL
   WHERE s.id = ANY(v_source_seat_ids)
     AND s.left_at IS NOT NULL
     AND (s.status IS DISTINCT FROM 'left'
       OR s.leave_pending IS DISTINCT FROM false
       OR s.is_sitting_out IS DISTINCT FROM false
       OR s.is_away IS DISTINCT FROM false
       OR s.sit_out_at IS NOT NULL
       OR s.scheduled_leave_hands IS NOT NULL);

  -- Publish terminal lifecycle after every seat is released but before table
  -- rows close. The managed table-status observer therefore sees a genuinely
  -- terminal parent and does not emit a false live-tournament incident. The
  -- deferred receipt constraint still requires the receipt later in this same
  -- transaction; any table or receipt failure rolls this update back too.
  UPDATE public.tournaments
     SET status = 'COMPLETED',
         ended_at = v_completed_at,
         on_break = false,
         break_started_at = NULL,
         break_ends_at = NULL,
         updated_at = now()
   WHERE id = p_tournament_id
     AND upper(COALESCE(status::text,'')) = 'COMPLETING';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'tournament % lost its terminal lifecycle claim',
      p_tournament_id USING ERRCODE = '40001';
  END IF;

  UPDATE public.tables
     SET status = 'closed',
         lifecycle = 'closed',
         current_players = 0,
         terminal_closed_at = v_completed_at,
         updated_at = now()
   WHERE tournament_id = p_tournament_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows IS DISTINCT FROM v_closed_table_count
     OR EXISTS (
       SELECT 1 FROM public.tables tb
        WHERE tb.tournament_id = p_tournament_id
          AND (lower(COALESCE(tb.status::text,'')) <> 'closed'
            OR lower(COALESCE(tb.lifecycle,'')) <> 'closed'
            OR tb.current_players IS DISTINCT FROM 0
            OR tb.terminal_closed_at IS DISTINCT FROM v_completed_at))
     OR EXISTS (
       SELECT 1
         FROM public.table_seats s
         JOIN public.tables tb ON tb.id = s.table_id
        WHERE tb.tournament_id = p_tournament_id
          AND (s.left_at IS NULL
            OR s.status IS DISTINCT FROM 'left'
            OR s.leave_pending IS DISTINCT FROM false
            OR s.is_sitting_out IS DISTINCT FROM false
            OR s.is_away IS DISTINCT FROM false
            OR s.sit_out_at IS NOT NULL
            OR s.scheduled_leave_hands IS NOT NULL)) THEN
    RAISE EXCEPTION 'tournament % did not durably release every seat and close every table',
      p_tournament_id USING ERRCODE = '40001';
  END IF;

  INSERT INTO public.tournament_terminal_settlements
    (tournament_id,winner_id,settlement_mode,started_status,
     prize_pool,bounty_pool,cash_payout_count,cash_payout_total,
     bounty_payout_total,mystery_was_active,mystery_pool_cents,
     cash_receipt,mystery_receipt,bounty_receipt,
     closed_table_count,closed_table_ids,source_seat_count,source_seat_ids,
     released_seat_count,released_seat_ids,
     rake_amount,rake_destination,rake_settled_at,rake_attributed_at,
     rake_attributed_users,escrow_closed_at,escrow_close_note,
     completed_at,settled_at,receipt_version)
  VALUES
    (p_tournament_id,v_winner_id,v_mode,v_started_status,
     v_t.prize_pool,v_t.bounty_pool,v_cash_count,v_cash_total,
     v_bounty_total,v_mystery_active,v_mystery_pool_cents,
     v_cash,v_mystery,v_bounty,
     v_closed_table_count,v_closed_table_ids,
     v_source_seat_count,v_source_seat_ids,
     v_released_seat_count,v_released_seat_ids,
     v_rake.amount,v_rake.destination,v_rake.settled_at,v_rake.attributed_at,
     v_rake.attributed_users,v_completed_at,'terminal receipt: exact zero',
     v_completed_at,transaction_timestamp(),1);

  RETURN public.fn_ca_tournament_terminal_receipt(
    p_tournament_id,p_observed_winner_id);
END;
$$;


ALTER FUNCTION public.fn_complete_tournament_terminal_pre_seat_guard(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text) OWNER TO postgres;

--
-- Name: FUNCTION fn_complete_tournament_terminal_pre_seat_guard(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_complete_tournament_terminal_pre_seat_guard(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text) IS 'Service-only non-satellite terminal transaction. Exactly one cash authority, bounty closure, attributed rake, table and seat closure, lifecycle close and immutable receipt commit together; replay only verifies stored durable state.';


--
-- Name: fn_complete_training_attempt_v2(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_training_attempt_v2(p_user_id uuid, p_attempt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
<<complete_attempt>>
DECLARE
  attempt_row public.training_attempts%ROWTYPE;
  answer_row record;
  progress_row public.training_progress%ROWTYPE;
  history_row public.training_level_history%ROWTYPE;
  streak_row public.training_streaks%ROWTYPE;
  daily_row public.training_daily_challenge%ROWTYPE;
  manifest_hands integer := 0;
  scored_hands integer := 0;
  answered integer := 0;
  correct integer := 0;
  current_streak integer := 0;
  best_streak integer := 0;
  accuracy integer := 0;
  required_correct integer := 0;
  reward_request integer := 0;
  reward_awarded integer := 0;
  reward_reason text := NULL;
  reward_reference text;
  reconciled_reward_rows integer := 0;
  reward_multiplier numeric := 1.0;
  award_result jsonb := '{}'::jsonb;
  total_ev_loss numeric := 0;
  has_measured_ev boolean := false;
  passed boolean := false;
  first_answer_at timestamptz := NULL;
  last_answer_at timestamptz := NULL;
  elapsed_seconds integer := 0;
  now_utc timestamp := timezone('UTC', now());
  activity_chicago_date date := timezone('America/Chicago', now())::date;
  daily_key text;
  weekly_key text;
  monthly_key text;
  daily_already_completed boolean := false;
  daily_selected_action text := NULL;
  daily_seal_snapshot_key text;
  daily_hand_snapshot_key text;
BEGIN
  IF p_user_id IS NULL OR p_attempt_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'status', 400,
      'code', 'TRAINING_COMPLETION_INPUT_INVALID',
      'error', 'A valid user and attempt are required.');
  END IF;

  SELECT * INTO attempt_row
  FROM public.training_attempts
  WHERE id = p_attempt_id
  FOR UPDATE;

  IF NOT FOUND OR attempt_row.user_id <> p_user_id THEN
    RETURN jsonb_build_object('success', false, 'status', 404,
      'code', 'TRAINING_ATTEMPT_NOT_FOUND',
      'error', 'The Training attempt was not found.');
  END IF;

  IF attempt_row.session_kind = 'daily' AND attempt_row.status = 'completed' THEN
    IF NOT public.fn_training_daily_attempt_matches_start_v1(
      attempt_row.client_nonce,
      attempt_row.started_at
    ) THEN
      RETURN jsonb_build_object('success', false, 'status', 409,
        'code', 'TRAINING_DAILY_ATTEMPT_EXPIRED',
        'error', 'This Daily Challenge attempt is not bound to its issuance date.');
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.training_daily_question_conflicts conflicts
      WHERE conflicts.daily_id = attempt_row.client_nonce
    ) THEN
      RETURN jsonb_build_object('success', false, 'status', 409,
        'code', 'TRAINING_DAILY_SNAPSHOT_CONFLICT',
        'error', 'This historical Daily Challenge has conflicting sealed evidence.');
    END IF;

    SELECT seals.snapshot_key INTO daily_seal_snapshot_key
    FROM public.training_daily_question_seals seals
    WHERE seals.daily_id = attempt_row.client_nonce;
    SELECT hands.snapshot_key INTO daily_hand_snapshot_key
    FROM public.training_attempt_hands hands
    WHERE hands.attempt_id = attempt_row.id
      AND hands.hand_ordinal = 1;
    IF daily_seal_snapshot_key IS NULL
       OR daily_hand_snapshot_key IS DISTINCT FROM daily_seal_snapshot_key THEN
      RETURN jsonb_build_object('success', false, 'status', 409,
        'code', 'TRAINING_DAILY_SNAPSHOT_BINDING_MISMATCH',
        'error', 'This completed Daily Challenge no longer matches its immutable seal.');
    END IF;
  END IF;

  IF attempt_row.status = 'completed' THEN
    SELECT * INTO history_row FROM public.training_level_history WHERE attempt_id = attempt_row.id;
    SELECT * INTO streak_row FROM public.training_streaks
    WHERE user_id = attempt_row.user_id;
    SELECT * INTO progress_row FROM public.training_progress
    WHERE user_id = attempt_row.user_id AND game_id = attempt_row.game_id;
    IF attempt_row.session_kind = 'daily' THEN
      SELECT * INTO daily_row FROM public.training_daily_challenge
      WHERE user_id = attempt_row.user_id
        AND daily_id = attempt_row.client_nonce;
    END IF;
    RETURN jsonb_build_object(
      'success', true, 'newCompletion', false, 'attemptId', attempt_row.id,
      'practiceOnly', attempt_row.practice_only, 'answered', attempt_row.answered_hands,
      'correct', attempt_row.correct_hands, 'accuracy', attempt_row.accuracy_percentage,
      'passed', attempt_row.passed, 'bestStreak', attempt_row.best_streak,
      'diamondsEarned', attempt_row.reward_diamonds,
      'rewardReference', 'training_attempt:' || attempt_row.id::text,
      'requiredQuestions', attempt_row.expected_hands,
      'requiredCorrect', ceil(attempt_row.expected_hands * CASE WHEN attempt_row.level = 12 THEN 0.90 ELSE 0.85 END)::integer,
      'history', to_jsonb(history_row), 'progress', to_jsonb(progress_row),
      'trainingStreak', to_jsonb(streak_row),
      'dailyChallenge', to_jsonb(daily_row)
    );
  END IF;

  IF attempt_row.status <> 'open' THEN
    RETURN jsonb_build_object('success', false, 'status', 409,
      'code', 'TRAINING_ATTEMPT_NOT_OPEN',
      'error', 'This Training attempt cannot be completed.');
  END IF;
  IF attempt_row.session_kind = 'daily'
     AND NOT public.fn_training_daily_attempt_matches_start_v1(attempt_row.client_nonce, attempt_row.started_at) THEN
    UPDATE public.training_attempts SET status = 'expired', updated_at = now()
    WHERE id = attempt_row.id;
    RETURN jsonb_build_object('success', false, 'status', 409,
      'code', 'TRAINING_DAILY_ATTEMPT_EXPIRED',
      'error', 'This Daily Challenge has expired. Load today''s challenge.');
  END IF;
  IF attempt_row.expires_at <= now() THEN
    UPDATE public.training_attempts SET status = 'expired', updated_at = now()
    WHERE id = attempt_row.id;
    RETURN jsonb_build_object('success', false, 'status', 409,
      'code', 'TRAINING_ATTEMPT_EXPIRED',
      'error', 'This Training attempt expired before completion.');
  END IF;

  IF attempt_row.session_kind = 'daily' THEN
    activity_chicago_date := timezone('America/Chicago', attempt_row.started_at)::date;
    now_utc := activity_chicago_date::timestamp;

    IF EXISTS (
      SELECT 1 FROM public.training_daily_question_conflicts conflicts
      WHERE conflicts.daily_id = attempt_row.client_nonce
    ) THEN
      RETURN jsonb_build_object('success', false, 'status', 409,
        'code', 'TRAINING_DAILY_SNAPSHOT_CONFLICT',
        'error', 'This historical Daily Challenge has conflicting sealed evidence.');
    END IF;

    SELECT seals.snapshot_key INTO daily_seal_snapshot_key
    FROM public.training_daily_question_seals seals
    WHERE seals.daily_id = attempt_row.client_nonce;
    SELECT hands.snapshot_key INTO daily_hand_snapshot_key
    FROM public.training_attempt_hands hands
    WHERE hands.attempt_id = attempt_row.id
      AND hands.hand_ordinal = 1;
    IF daily_seal_snapshot_key IS NULL
       OR daily_hand_snapshot_key IS DISTINCT FROM daily_seal_snapshot_key THEN
      RETURN jsonb_build_object('success', false, 'status', 409,
        'code', 'TRAINING_DAILY_SNAPSHOT_BINDING_MISMATCH',
        'error', 'This Daily Challenge attempt does not match its global seal.');
    END IF;

    SELECT * INTO daily_row
    FROM public.training_daily_challenge
    WHERE user_id = attempt_row.user_id
      AND daily_id = attempt_row.client_nonce
    FOR UPDATE;
    -- A legacy row with no attempt binding still proves today's challenge was
    -- already consumed. It may be bound to this sealed recovery attempt below,
    -- but must never receive a second 25-Diamond payout.
    daily_already_completed := FOUND;
    IF daily_already_completed AND daily_row.attempt_id <> attempt_row.id THEN
      RETURN jsonb_build_object('success', false, 'status', 409,
        'code', 'TRAINING_DAILY_ALREADY_COMPLETED',
        'error', 'This Daily Challenge was already completed by another sealed attempt.');
    END IF;
  END IF;

  SELECT count(*)::integer,
    count(*) FILTER (WHERE status = 'scored' AND result_is_correct IS NOT NULL AND scored_at IS NOT NULL)::integer
  INTO manifest_hands, scored_hands
  FROM public.training_attempt_hands WHERE attempt_id = attempt_row.id;

  IF manifest_hands <> attempt_row.expected_hands OR scored_hands <> attempt_row.expected_hands THEN
    RETURN jsonb_build_object('success', false, 'status', 409,
      'code', 'TRAINING_ATTEMPT_INCOMPLETE',
      'error', format('This attempt has %s of %s scored hands.', scored_hands, attempt_row.expected_hands),
      'answered', scored_hands, 'requiredQuestions', attempt_row.expected_hands);
  END IF;

  FOR answer_row IN
    SELECT hands.hand_ordinal, answers.answer_id, answers.is_correct, answers.answered_at,
      answers.ev_loss, answers.ev_loss_measured
    FROM public.training_attempt_hands hands
    JOIN public.training_answers answers
      ON answers.attempt_id = hands.attempt_id
     AND answers.hand_ordinal = hands.hand_ordinal
     AND answers.decision_ordinal = 1
     AND answers.snapshot_key = hands.snapshot_key
    WHERE hands.attempt_id = attempt_row.id
    ORDER BY hands.hand_ordinal
  LOOP
    answered := answered + 1;
    IF attempt_row.session_kind = 'daily' THEN
      daily_selected_action := answer_row.answer_id;
    END IF;
    first_answer_at := coalesce(first_answer_at, answer_row.answered_at);
    last_answer_at := answer_row.answered_at;
    IF answer_row.is_correct THEN
      correct := correct + 1;
      current_streak := current_streak + 1;
      best_streak := greatest(best_streak, current_streak);
    ELSE
      current_streak := 0;
    END IF;
    IF answer_row.ev_loss_measured THEN
      has_measured_ev := true;
      total_ev_loss := total_ev_loss + coalesce(answer_row.ev_loss, 0);
    END IF;
  END LOOP;

  IF answered <> attempt_row.expected_hands THEN
    RETURN jsonb_build_object('success', false, 'status', 409,
      'code', 'TRAINING_ATTEMPT_DECISIONS_INCOMPLETE',
      'error', 'Every manifested hand requires exactly one persisted first decision.',
      'answered', answered, 'requiredQuestions', attempt_row.expected_hands);
  END IF;

  required_correct := ceil(attempt_row.expected_hands * CASE WHEN attempt_row.level = 12 THEN 0.90 ELSE 0.85 END)::integer;
  accuracy := round((correct::numeric / attempt_row.expected_hands::numeric) * 100)::integer;
  passed := correct >= required_correct;
  elapsed_seconds := greatest(0, least(86400,
    coalesce(extract(epoch FROM (last_answer_at - first_answer_at))::integer, 0)));
  reward_multiplier := CASE attempt_row.level
    WHEN 1 THEN 1.00 WHEN 2 THEN 1.00 WHEN 3 THEN 1.00 WHEN 4 THEN 1.10
    WHEN 5 THEN 1.15 WHEN 6 THEN 1.25 WHEN 7 THEN 1.35 WHEN 8 THEN 1.40
    WHEN 9 THEN 1.50 WHEN 10 THEN 1.60 WHEN 11 THEN 1.75 WHEN 12 THEN 2.00
    ELSE 1.00 END;
  reward_request := CASE
    WHEN attempt_row.session_kind = 'daily' THEN
      CASE WHEN daily_already_completed THEN 0 ELSE 25 END
    WHEN attempt_row.practice_only THEN 0
    ELSE round((
      5 + CASE WHEN accuracy = 100 THEN 10 WHEN accuracy >= 90 THEN 5 WHEN accuracy >= 85 THEN 3 ELSE 0 END
        + CASE WHEN best_streak > 5 THEN 2 ELSE 0 END
      ) * reward_multiplier)::integer
    END;

  reward_reference := 'training_attempt:' || attempt_row.id::text;

  IF NOT attempt_row.practice_only AND reward_request > 0 THEN
    award_result := public.award_diamonds_v2(
      attempt_row.user_id,
      'training_reward',
      reward_reference,
      NULL,
      jsonb_build_object(
        'reward_diamonds', reward_request,
        'game_id', attempt_row.game_id,
        'level', attempt_row.level,
        'attempt_id', attempt_row.id,
        '_source', 'fn_complete_training_attempt_v2'
      )
    );

    -- A malformed economy response is an integrity failure, not a zero-value
    -- completion. Raising here rolls the entire transaction back and leaves
    -- the attempt open for a clean retry.
    IF jsonb_typeof(award_result) IS DISTINCT FROM 'object'
       OR jsonb_typeof(award_result -> 'success') IS DISTINCT FROM 'boolean'
       OR jsonb_typeof(award_result -> 'awarded') IS DISTINCT FROM 'number'
       OR jsonb_typeof(award_result -> 'reason') IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'TRAINING_REWARD_RESPONSE_INVALID';
    END IF;

    BEGIN
      reward_awarded := greatest(0, (award_result ->> 'awarded')::integer);
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'TRAINING_REWARD_RESPONSE_INVALID';
    END;
    reward_reason := lower(award_result ->> 'reason');

    IF award_result @> '{"success": true}'::jsonb AND reward_awarded > 0 THEN
      NULL;
    ELSIF NOT (award_result @> '{"success": true}'::jsonb)
          AND reward_awarded = 0
          AND reward_reason IN ('action_limit', 'daily_cap', 'monthly_cap', 'budget_exhausted') THEN
      -- Explicit economy ceilings are settled zero-award completions. The
      -- verified training result still persists, but no reward is invented.
      NULL;
    ELSIF NOT (award_result @> '{"success": true}'::jsonb)
          AND reward_reason IN ('duplicate', 'already_claimed') THEN
      SELECT count(*)::integer, coalesce(max(transactions.amount), 0)::integer
      INTO reconciled_reward_rows, reward_awarded
      FROM public.diamond_transactions transactions
      WHERE transactions.user_id = attempt_row.user_id
        AND transactions.reference_id = reward_reference
        AND transactions.transaction_type = 'training_reward'
        AND transactions.amount > 0;

      IF reconciled_reward_rows <> 1 OR reward_awarded <= 0 THEN
        RETURN jsonb_build_object(
          'success', false,
          'status', 409,
          'code', 'TRAINING_REWARD_DUPLICATE_UNVERIFIED',
          'error', 'The existing Training reward could not be verified. Retry this completion.',
          'attemptId', attempt_row.id,
          'rewardVerdict', award_result
        );
      END IF;
      award_result := award_result || jsonb_build_object(
        'success', true,
        'awarded', reward_awarded,
        'reconciled', true
      );
    ELSE
      RETURN jsonb_build_object(
        'success', false,
        'status', 503,
        'code', 'TRAINING_REWARD_NOT_SETTLED',
        'error', 'The Training reward could not be settled. Retry this completion.',
        'attemptId', attempt_row.id,
        'rewardVerdict', award_result
      );
    END IF;
  END IF;

  INSERT INTO public.training_level_history (
    user_id, game_id, session_id, attempt_id, practice_only, level,
    questions_answered, questions_correct, accuracy_percentage, passed,
    time_spent_seconds, best_streak, diamonds_earned
  ) VALUES (
    attempt_row.user_id, attempt_row.game_id, attempt_row.client_nonce,
    attempt_row.id, attempt_row.practice_only, attempt_row.level,
    attempt_row.expected_hands, correct, accuracy, passed, elapsed_seconds,
    best_streak, reward_awarded
  ) RETURNING * INTO history_row;

  IF attempt_row.session_kind = 'daily' THEN
    INSERT INTO public.training_daily_challenge (
      user_id, daily_id, score, ev_loss, selected_action, completed_at, attempt_id
    ) VALUES (
      attempt_row.user_id, attempt_row.client_nonce, accuracy,
      CASE WHEN has_measured_ev THEN total_ev_loss ELSE 0 END,
      daily_selected_action, now(), attempt_row.id
    )
    ON CONFLICT (user_id, daily_id) DO UPDATE SET
      score = excluded.score,
      ev_loss = excluded.ev_loss,
      selected_action = excluded.selected_action,
      completed_at = excluded.completed_at,
      attempt_id = excluded.attempt_id
    WHERE public.training_daily_challenge.attempt_id IS NULL
       OR public.training_daily_challenge.attempt_id = excluded.attempt_id;
    SELECT * INTO daily_row
    FROM public.training_daily_challenge
    WHERE user_id = attempt_row.user_id
      AND daily_id = attempt_row.client_nonce;
    IF daily_row.attempt_id IS DISTINCT FROM attempt_row.id THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'TRAINING_DAILY_COMPLETION_BINDING_MISMATCH';
    END IF;
  END IF;

  IF NOT attempt_row.practice_only THEN
    -- A real completed Training attempt is the only source of daily streak
    -- movement. The atomic upsert makes concurrent completions idempotent for
    -- the America/Chicago product day and preserves the original streak start.
    
INSERT INTO public.training_streaks AS streaks (
    user_id, current_streak, longest_streak, last_training_date,
    streak_start_date, milestones_claimed,
    authority_current_streak, authority_longest_streak,
    authority_last_training_date, authority_streak_start_date,
    authority_milestones_claimed, created_at, updated_at
  ) VALUES (
    attempt_row.user_id, 1, 1, activity_chicago_date,
    activity_chicago_date, '[]'::jsonb,
    1, 1, activity_chicago_date, activity_chicago_date, '[]'::jsonb, now(), now()
  )
  ON CONFLICT (user_id) DO NOTHING;

  -- Serialize all days for one player before adding evidence and recomputing
  -- islands. The ledger PK makes same-day concurrent completions idempotent.
  SELECT * INTO streak_row
  FROM public.training_streaks
  WHERE user_id = attempt_row.user_id
  FOR UPDATE;

  INSERT INTO public.training_streak_activity_days (
    user_id, activity_date, first_attempt_id
  ) VALUES (
    attempt_row.user_id, activity_chicago_date, attempt_row.id
  )
  ON CONFLICT (user_id, activity_date) DO NOTHING;

  WITH summary AS MATERIALIZED (
    SELECT public.fn_training_streak_summary_v1(attempt_row.user_id) AS value
  )
  UPDATE public.training_streaks AS streaks
  SET
    authority_current_streak = (summary.value ->> 'current')::integer,
    authority_longest_streak = greatest(
      streaks.authority_longest_streak,
      (summary.value ->> 'longest')::integer
    ),
    authority_last_training_date = (summary.value ->> 'lastDate')::date,
    authority_streak_start_date = (summary.value ->> 'startDate')::date,
    current_streak = (summary.value ->> 'current')::integer,
    longest_streak = greatest(
      streaks.authority_longest_streak,
      (summary.value ->> 'longest')::integer
    ),
    last_training_date = (summary.value ->> 'lastDate')::date,
    streak_start_date = (summary.value ->> 'startDate')::date,
    milestones_claimed = streaks.authority_milestones_claimed,
    updated_at = now()
  FROM summary
  WHERE streaks.user_id = attempt_row.user_id
  RETURNING streaks.* INTO streak_row;


    INSERT INTO public.training_progress AS progress (
      user_id, game_id, level, hands_played, correct_answers, total_answers,
      current_streak, best_streak, last_played_at,
      authority_level, authority_hands_played, authority_correct_answers,
      authority_total_answers, authority_current_streak,
      authority_best_streak, authority_last_played_at
    ) VALUES (
      attempt_row.user_id, attempt_row.game_id,
      CASE WHEN passed THEN least(attempt_row.level + 1, 12) ELSE attempt_row.level END,
      attempt_row.expected_hands, correct, attempt_row.expected_hands,
      current_streak, best_streak, now(),
      CASE WHEN passed THEN least(attempt_row.level + 1, 12) ELSE attempt_row.level END,
      attempt_row.expected_hands, correct, attempt_row.expected_hands,
      current_streak, best_streak, now()
    )
    ON CONFLICT (user_id, game_id) DO UPDATE SET
      authority_level = greatest(progress.authority_level, excluded.authority_level),
      authority_hands_played = progress.authority_hands_played
        + excluded.authority_hands_played,
      authority_correct_answers = progress.authority_correct_answers
        + excluded.authority_correct_answers,
      authority_total_answers = progress.authority_total_answers
        + excluded.authority_total_answers,
      authority_current_streak = excluded.authority_current_streak,
      authority_best_streak = greatest(
        progress.authority_best_streak, excluded.authority_best_streak
      ),
      authority_last_played_at = excluded.authority_last_played_at,
      level = greatest(progress.authority_level, excluded.authority_level),
      hands_played = progress.authority_hands_played + excluded.authority_hands_played,
      correct_answers = progress.authority_correct_answers
        + excluded.authority_correct_answers,
      total_answers = progress.authority_total_answers
        + excluded.authority_total_answers,
      current_streak = excluded.authority_current_streak,
      best_streak = greatest(
        progress.authority_best_streak, excluded.authority_best_streak
      ),
      last_played_at = excluded.authority_last_played_at
    RETURNING * INTO progress_row;

    daily_key := to_char(now_utc, 'YYYY-MM-DD');
    weekly_key := to_char(now_utc, 'IYYY-"W"IW');
    monthly_key := to_char(now_utc, 'YYYY-MM');

    PERFORM public.fn_training_verified_leaderboard_record_v2(
      attempt_row.user_id, attempt_row.game_id, 'daily', daily_key,
      answered, correct, correct = answered, best_streak, NULL,
      CASE WHEN has_measured_ev THEN total_ev_loss ELSE NULL END);
    PERFORM public.fn_training_verified_leaderboard_record_v2(
      attempt_row.user_id, attempt_row.game_id, 'weekly', weekly_key,
      answered, correct, correct = answered, best_streak, NULL,
      CASE WHEN has_measured_ev THEN total_ev_loss ELSE NULL END);
    PERFORM public.fn_training_verified_leaderboard_record_v2(
      attempt_row.user_id, attempt_row.game_id, 'monthly', monthly_key,
      answered, correct, correct = answered, best_streak, NULL,
      CASE WHEN has_measured_ev THEN total_ev_loss ELSE NULL END);
    PERFORM public.fn_training_verified_leaderboard_record_v2(
      attempt_row.user_id, attempt_row.game_id, 'alltime', 'alltime',
      answered, correct, correct = answered, best_streak, NULL,
      CASE WHEN has_measured_ev THEN total_ev_loss ELSE NULL END);
  ELSE
    SELECT * INTO progress_row FROM public.training_progress
    WHERE user_id = attempt_row.user_id AND game_id = attempt_row.game_id;
    SELECT * INTO streak_row FROM public.training_streaks
    WHERE user_id = attempt_row.user_id;
  END IF;

  UPDATE public.training_attempts
  SET status = 'completed', completed_at = now(), answered_hands = answered,
      correct_hands = correct, accuracy_percentage = accuracy,
      passed = complete_attempt.passed,
      best_streak = complete_attempt.best_streak,
      reward_diamonds = complete_attempt.reward_awarded,
      updated_at = now()
  WHERE id = attempt_row.id
  RETURNING * INTO attempt_row;

  RETURN jsonb_build_object(
    'success', true, 'newCompletion', true, 'attemptId', attempt_row.id,
    'practiceOnly', attempt_row.practice_only, 'answered', answered,
    'correct', correct, 'accuracy', accuracy, 'passed', passed,
    'bestStreak', best_streak, 'diamondsEarned', reward_awarded,
    'rewardVerdict', award_result,
    'rewardReference', reward_reference,
    'requiredQuestions', attempt_row.expected_hands,
    'requiredCorrect', required_correct, 'history', to_jsonb(history_row),
    'progress', to_jsonb(progress_row),
    'trainingStreak', to_jsonb(streak_row),
    'dailyChallenge', to_jsonb(daily_row)
  );
END;
$$;


ALTER FUNCTION public.fn_complete_training_attempt_v2(p_user_id uuid, p_attempt_id uuid) OWNER TO postgres;

--
-- Name: fn_concurrent_game_load(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_concurrent_game_load(p_user_id uuid, p_exclude_seat_id uuid DEFAULT NULL::uuid, p_exclude_table_id uuid DEFAULT NULL::uuid, p_exclude_tournament_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT (
    -- (1) A LIVE SEAT IS A GAME. A seat at a closed table is history.
    (
      SELECT count(*)
        FROM public.table_seats ts
        JOIN public.tables t ON t.id = ts.table_id
       WHERE ts.user_id = p_user_id
         AND ts.left_at IS NULL
         AND t.status <> 'closed'
         AND (p_exclude_seat_id IS NULL OR ts.id IS DISTINCT FROM p_exclude_seat_id)
         AND (p_exclude_table_id IS NULL OR ts.table_id IS DISTINCT FROM p_exclude_table_id)
    )
    +
    -- (2) A BOOKING IS A GAME FROM ONE HOUR BEFORE ITS TOURNAMENT STARTS
    -- UNTIL THE TOURNAMENT STARTS (2026-09-06). RUNNING is absent
    -- deliberately: its entrants hold seats, counted by clause (1). A booking
    -- for an event further out than an hour is a plan, not a game - counting
    -- it from registration held 217 horses off the cash floor for events up
    -- to 68 hours away. A NULL start_time is a seat-first game that starts
    -- when it fills, so it always counts.
    (
      SELECT count(*)
        FROM public.tournament_players tp
        JOIN public.tournaments tr ON tr.id = tp.tournament_id
       WHERE tp.user_id = p_user_id
         AND tp.status IN ('registered', 'playing')
         AND tr.status IN ('ANNOUNCED', 'REGISTERING')
         AND (tr.start_time IS NULL OR tr.start_time <= now() + interval '60 minutes')
         AND (p_exclude_tournament_id IS NULL
              OR tp.tournament_id IS DISTINCT FROM p_exclude_tournament_id)
         -- NEVER BOTH. A seat-first game sells the chair before it starts, so
         -- a booking and a seat can describe the same game for a few minutes.
         AND NOT EXISTS (
           SELECT 1
             FROM public.table_seats ts2
             JOIN public.tables t2 ON t2.id = ts2.table_id
            WHERE ts2.user_id = p_user_id
              AND ts2.left_at IS NULL
              AND t2.status <> 'closed'
              AND t2.tournament_id = tp.tournament_id
         )
    )
  )::int;
$$;


ALTER FUNCTION public.fn_concurrent_game_load(p_user_id uuid, p_exclude_seat_id uuid, p_exclude_table_id uuid, p_exclude_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_concurrent_game_load(p_user_id uuid, p_exclude_seat_id uuid, p_exclude_table_id uuid, p_exclude_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_concurrent_game_load(p_user_id uuid, p_exclude_seat_id uuid, p_exclude_table_id uuid, p_exclude_tournament_id uuid) IS 'Games a player is committed to: live seats at open tables, plus bookings for tournaments that start within 60 minutes (or have no start time). Read by fn_enforce_four_table_limit, fn_enforce_booking_game_cap and the fleet (HorseGameLoad.ts). 2026-09-06: a booking counts from one hour before the start, not from registration.';


--
-- Name: fn_consume_feature_use(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_consume_feature_use(p_user_id uuid, p_feature text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND (auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_user_id) THEN
    RAISE EXCEPTION 'Cannot consume a purchase for another user';
  END IF;

  SELECT id INTO v_id
    FROM public.feature_purchases
   WHERE user_id = p_user_id AND feature = p_feature
     AND uses_remaining IS NOT NULL AND uses_remaining > 0
     AND (expires_at IS NULL OR expires_at > now())
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE SKIP LOCKED;

  IF v_id IS NOT NULL THEN
    UPDATE public.feature_purchases SET uses_remaining = uses_remaining - 1 WHERE id = v_id;
  END IF;
END;
$$;


ALTER FUNCTION public.fn_consume_feature_use(p_user_id uuid, p_feature text) OWNER TO postgres;

--
-- Name: fn_consume_mfa_backup_code(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_consume_mfa_backup_code(p_user_id uuid, p_hashed_code text) RETURNS TABLE(consumed boolean, remaining_count integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_codes TEXT[];
    v_new_codes TEXT[];
    v_found BOOLEAN := FALSE;
BEGIN
    -- Lock the row for the duration of this function. Concurrent callers
    -- block on this SELECT until we commit - exactly one of them finds the
    -- code present, the rest see it already consumed.
    SELECT backup_codes
      INTO v_codes
      FROM public.user_mfa_factors
     WHERE user_id = p_user_id
       AND enabled = TRUE
     FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 0;
        RETURN;
    END IF;

    -- Check membership
    IF v_codes IS NULL OR NOT (p_hashed_code = ANY(v_codes)) THEN
        RETURN QUERY SELECT FALSE, COALESCE(array_length(v_codes, 1), 0);
        RETURN;
    END IF;

    v_found := TRUE;
    v_new_codes := array_remove(v_codes, p_hashed_code);

    UPDATE public.user_mfa_factors
       SET backup_codes = v_new_codes,
           updated_at    = NOW()
     WHERE user_id = p_user_id;

    RETURN QUERY SELECT TRUE, COALESCE(array_length(v_new_codes, 1), 0);
END;
$$;


ALTER FUNCTION public.fn_consume_mfa_backup_code(p_user_id uuid, p_hashed_code text) OWNER TO postgres;

--
-- Name: FUNCTION fn_consume_mfa_backup_code(p_user_id uuid, p_hashed_code text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_consume_mfa_backup_code(p_user_id uuid, p_hashed_code text) IS 'Phase 6.1.22: atomically verify + consume an MFA backup code. Returns (consumed boolean, remaining_count integer). Holds a row-level lock for the duration to close the concurrent-use race.';


--
-- Name: fn_consume_rabbit_hunt(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_consume_rabbit_hunt(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'fn_consume_rabbit_hunt is engine-only';
  END IF;

  RETURN public.fn_consume_rabbit_hunt_v2(p_user_id, gen_random_uuid());
END;
$$;


ALTER FUNCTION public.fn_consume_rabbit_hunt(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_consume_rabbit_hunt_v2(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_consume_rabbit_hunt_v2(p_user_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_vip_monthly_cap CONSTANT int := 100;
  v_default_cost    CONSTANT int := 5;
  v_is_vip          boolean;
  v_is_lifetime     boolean;
  v_month           text := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM');
  v_used            int;
  v_cost            int;
  v_row             record;
  v_deduct          jsonb;
  v_balance         integer;
  v_request_payload jsonb := jsonb_build_object(
    'feature', 'rabbit_hunt',
    'user_id', p_user_id
  );
  v_cached_kind     text;
  v_cached_payload  jsonb;
  v_cached_result   jsonb;
  v_result          jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'fn_consume_rabbit_hunt_v2 is engine-only';
  END IF;
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'User Id Required');
  END IF;
  IF p_request_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Secure Request Id Required');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'digital_purchase_request:' || p_user_id::text || ':' || p_request_id::text,
      0
    )
  );

  SELECT r.purchase_kind, r.request_payload, r.result
    INTO v_cached_kind, v_cached_payload, v_cached_result
    FROM public.digital_purchase_receipts r
   WHERE r.user_id = p_user_id
     AND r.request_id = p_request_id;

  IF FOUND THEN
    IF v_cached_kind IS DISTINCT FROM 'rabbit_hunt'
       OR v_cached_payload IS DISTINCT FROM v_request_payload
    THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Request Id Already Used For Another Purchase',
        'code', 'REQUEST_ID_REUSED'
      );
    END IF;

    RETURN v_cached_result || jsonb_build_object(
      'diamonds_spent', 0,
      'original_diamonds_spent',
        COALESCE(
          (v_cached_result->>'original_diamonds_spent')::integer,
          (v_cached_result->>'diamonds_spent')::integer,
          0
        ),
      'idempotent', true,
      'consumed', false
    );
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('rabbit_hunt:' || p_user_id::text, 0));

  SELECT
    COALESCE(p.is_vip, false)
      AND (p.vip_tier = 'lifetime' OR p.vip_expires_at IS NULL OR p.vip_expires_at > now()),
    COALESCE(p.is_vip, false) AND p.vip_tier = 'lifetime'
    INTO v_is_vip, v_is_lifetime
    FROM public.profiles p
   WHERE p.id = p_user_id;

  IF v_is_vip IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown user');
  END IF;

  IF v_is_lifetime THEN
    INSERT INTO public.vip_feature_usage_monthly
      (user_id, feature, month, usage_count, updated_at)
    VALUES
      (p_user_id, 'rabbit_hunt', v_month, 1, now())
    ON CONFLICT (user_id, feature, month) DO UPDATE
       SET usage_count = public.vip_feature_usage_monthly.usage_count + 1,
           updated_at = now();

    v_result := jsonb_build_object(
      'success', true,
      'source', 'lifetime_vip',
      'unlimited', true,
      'vip_remaining', null,
      'diamonds_spent', 0,
      'idempotent', false,
      'consumed', true
    );
    INSERT INTO public.digital_purchase_receipts
      (user_id, request_id, purchase_kind, request_payload, result)
    VALUES
      (p_user_id, p_request_id, 'rabbit_hunt', v_request_payload, v_result);
    RETURN v_result;
  END IF;

  IF v_is_vip THEN
    SELECT COALESCE(SUM(usage_count), 0)::int INTO v_used
      FROM public.vip_feature_usage_monthly
     WHERE user_id = p_user_id
       AND feature = 'rabbit_hunt'
       AND month = v_month;

    IF v_used < v_vip_monthly_cap THEN
      INSERT INTO public.vip_feature_usage_monthly
        (user_id, feature, month, usage_count, updated_at)
      VALUES
        (p_user_id, 'rabbit_hunt', v_month, 1, now())
      ON CONFLICT (user_id, feature, month) DO UPDATE
         SET usage_count = public.vip_feature_usage_monthly.usage_count + 1,
             updated_at = now();

      v_result := jsonb_build_object(
        'success', true,
        'source', 'vip_monthly',
        'vip_used', v_used + 1,
        'vip_remaining', v_vip_monthly_cap - (v_used + 1),
        'diamonds_spent', 0,
        'idempotent', false,
        'consumed', true
      );
      INSERT INTO public.digital_purchase_receipts
        (user_id, request_id, purchase_kind, request_payload, result)
      VALUES
        (p_user_id, p_request_id, 'rabbit_hunt', v_request_payload, v_result);
      RETURN v_result;
    END IF;
  END IF;

  SELECT id, uses_remaining INTO v_row
    FROM public.feature_purchases
   WHERE user_id = p_user_id
     AND feature = 'rabbit_hunt'
     AND COALESCE(uses_remaining, 0) > 0
     AND (expires_at IS NULL OR expires_at > now())
   ORDER BY created_at
   FOR UPDATE
   LIMIT 1;

  IF FOUND THEN
    UPDATE public.feature_purchases
       SET uses_remaining = uses_remaining - 1
     WHERE id = v_row.id;

    v_result := jsonb_build_object(
      'success', true,
      'source', 'purchased',
      'uses_remaining', v_row.uses_remaining - 1,
      'diamonds_spent', 0,
      'idempotent', false,
      'consumed', true
    );
    INSERT INTO public.digital_purchase_receipts
      (user_id, request_id, purchase_kind, request_payload, result)
    VALUES
      (p_user_id, p_request_id, 'rabbit_hunt', v_request_payload, v_result);
    RETURN v_result;
  END IF;

  SELECT COALESCE(diamond_cost, v_default_cost) INTO v_cost
    FROM public.feature_pricing
   WHERE feature = 'rabbit_hunt'
   LIMIT 1;
  v_cost := COALESCE(v_cost, v_default_cost);

  IF v_cost < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rabbit Hunt Pricing Is Invalid');
  END IF;

  IF v_cost > 0 THEN
    v_deduct := public.deduct_diamonds(
      p_user_id          => p_user_id,
      p_amount           => v_cost,
      p_description      => 'Rabbit Hunt',
      p_transaction_type => 'feature_purchase',
      p_source           => 'rabbit_hunt',
      p_reference_id     => 'rabbit_use_' || p_user_id::text || '_' || p_request_id::text
    );

    IF COALESCE((v_deduct->>'success')::boolean, false) IS NOT TRUE THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'insufficient_diamonds',
        'cost', v_cost,
        'diamonds_remaining', (v_deduct->>'balance')::numeric
      );
    END IF;

    IF COALESCE((v_deduct->>'idempotent')::boolean, false) THEN
      v_result := jsonb_build_object(
        'success', true,
        'source', 'diamonds',
        'diamonds_spent', 0,
        'original_diamonds_spent', v_cost,
        'diamonds_remaining', (v_deduct->>'balance')::numeric,
        'idempotent', true,
        'consumed', false
      );
      INSERT INTO public.digital_purchase_receipts
        (user_id, request_id, purchase_kind, request_payload, result)
      VALUES
        (p_user_id, p_request_id, 'rabbit_hunt', v_request_payload, v_result);
      RETURN v_result;
    END IF;
    v_balance := (v_deduct->>'balance')::integer;
  ELSE
    SELECT p.diamonds INTO v_balance
      FROM public.profiles p
     WHERE p.id = p_user_id;
  END IF;

  v_result := jsonb_build_object(
    'success', true,
    'source', 'diamonds',
    'diamonds_spent', v_cost,
    'diamonds_remaining', v_balance,
    'idempotent', false,
    'consumed', true
  );
  INSERT INTO public.digital_purchase_receipts
    (user_id, request_id, purchase_kind, request_payload, result)
  VALUES
    (p_user_id, p_request_id, 'rabbit_hunt', v_request_payload, v_result);
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_consume_rabbit_hunt_v2(p_user_id uuid, p_request_id uuid) OWNER TO postgres;

--
-- Name: fn_consume_time_bank(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_consume_time_bank(p_user_id uuid, p_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_vip      boolean;
  v_is_lifetime boolean;
  v_month       text := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM');
  v_used        int;
  v_from_vip    int := 0;
  v_remaining   int;
  v_uses_needed int;
  v_uses_taken  int := 0;
  v_row         record;
  v_take        int;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'fn_consume_time_bank is engine-only';
  END IF;
  IF p_seconds IS NULL OR p_seconds <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'p_seconds must be positive');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('time_bank:' || p_user_id::text, 0));

  SELECT
    COALESCE(p.is_vip, false)
      AND (p.vip_tier = 'lifetime' OR p.vip_expires_at IS NULL OR p.vip_expires_at > now()),
    COALESCE(p.is_vip, false) AND p.vip_tier = 'lifetime'
    INTO v_is_vip, v_is_lifetime
    FROM public.profiles p
   WHERE p.id = p_user_id;

  IF v_is_vip IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown user');
  END IF;

  IF v_is_lifetime THEN
    INSERT INTO public.vip_feature_usage_monthly
      (user_id, feature, month, usage_count, updated_at)
    VALUES
      (p_user_id, 'time_bank_seconds', v_month, p_seconds, now())
    ON CONFLICT (user_id, feature, month) DO UPDATE
       SET usage_count = public.vip_feature_usage_monthly.usage_count + EXCLUDED.usage_count,
           updated_at = now();

    RETURN jsonb_build_object(
      'success', true,
      'source', 'lifetime_vip',
      'unlimited', true,
      'consumed_vip_seconds', p_seconds,
      'consumed_purchased_uses', 0,
      'shortfall_seconds', 0
    );
  END IF;

  v_remaining := p_seconds;

  IF v_is_vip THEN
    SELECT COALESCE(SUM(usage_count), 0)::int INTO v_used
      FROM public.vip_feature_usage_monthly
     WHERE user_id = p_user_id
       AND feature = 'time_bank_seconds'
       AND month = v_month;

    v_from_vip := LEAST(v_remaining, GREATEST(0, 120 - v_used));
    IF v_from_vip > 0 THEN
      INSERT INTO public.vip_feature_usage_monthly
        (user_id, feature, month, usage_count, updated_at)
      VALUES
        (p_user_id, 'time_bank_seconds', v_month, v_from_vip, now())
      ON CONFLICT (user_id, feature, month) DO UPDATE
         SET usage_count = public.vip_feature_usage_monthly.usage_count + EXCLUDED.usage_count,
             updated_at = now();
      v_remaining := v_remaining - v_from_vip;
    END IF;
  END IF;

  IF v_remaining > 0 THEN
    v_uses_needed := CEIL(v_remaining / 20.0)::int;
    FOR v_row IN
      SELECT id, uses_remaining
        FROM public.feature_purchases
       WHERE user_id = p_user_id
         AND feature = 'time_bank_seconds'
         AND COALESCE(uses_remaining, 0) > 0
         AND (expires_at IS NULL OR expires_at > now())
       ORDER BY created_at
       FOR UPDATE
    LOOP
      EXIT WHEN v_uses_needed <= 0;
      v_take := LEAST(v_row.uses_remaining, v_uses_needed);
      UPDATE public.feature_purchases
         SET uses_remaining = uses_remaining - v_take
       WHERE id = v_row.id;
      v_uses_taken := v_uses_taken + v_take;
      v_uses_needed := v_uses_needed - v_take;
    END LOOP;
    v_remaining := GREATEST(0, v_remaining - v_uses_taken * 20);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'consumed_vip_seconds', v_from_vip,
    'consumed_purchased_uses', v_uses_taken,
    'shortfall_seconds', v_remaining
  );
END;
$$;


ALTER FUNCTION public.fn_consume_time_bank(p_user_id uuid, p_seconds integer) OWNER TO postgres;

--
-- Name: crash_rounds; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.crash_rounds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    host_id uuid NOT NULL,
    host_kind text NOT NULL,
    club_id uuid NOT NULL,
    user_id uuid NOT NULL,
    bet_diamonds integer NOT NULL,
    bet_chips numeric(14,2) NOT NULL,
    diamonds_per_chip integer NOT NULL,
    commit_id uuid NOT NULL,
    server_seed_hash text NOT NULL,
    server_seed text NOT NULL,
    client_seed text NOT NULL,
    nonce bigint NOT NULL,
    roll numeric(20,0) NOT NULL,
    crash_cents bigint NOT NULL,
    cap_cents integer NOT NULL,
    growth_k numeric(6,4) NOT NULL,
    auto_cashout_cents integer,
    reserved_chips numeric(14,2) NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    started_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    settled_at timestamp with time zone,
    settled_by text,
    elapsed_ms integer,
    cashout_cents integer,
    payout_chips numeric(14,2) DEFAULT 0 NOT NULL,
    chips_minted numeric(14,2) NOT NULL,
    pool_chips_minted_after numeric(16,2),
    pool_chips_paid_after numeric(16,2),
    diamonds_after numeric NOT NULL,
    member_chips_after numeric(14,2),
    is_fixture boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT crash_rounds_cap_cents_check CHECK ((cap_cents >= 101)),
    CONSTRAINT crash_rounds_crash_cents_check CHECK ((crash_cents >= 100)),
    CONSTRAINT crash_rounds_status_check CHECK ((status = ANY (ARRAY['open'::text, 'cashed'::text, 'crashed'::text])))
);


ALTER TABLE public.crash_rounds OWNER TO postgres;

--
-- Name: TABLE crash_rounds; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.crash_rounds IS 'Every Diamond Crash round: the seeds, the roll, the crash point (secret until settled), the cap, the auto cash-out, and the settlement. A row is written once at start and settled once; after that it is a fact.';


--
-- Name: fn_crash_decide(public.crash_rounds, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crash_decide(p_round public.crash_rounds, p_cashout boolean, p_by text) RETURNS public.crash_rounds
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  r public.crash_rounds := p_round;
  v_elapsed_ms bigint;
  v_now_cents integer;
  v_result text;          -- 'cashed' | 'crashed' | NULL (still open)
  v_at_cents integer;
  v_payout numeric := 0;
  v_bank_after numeric; v_member_after numeric;
  pool public.diamond_game_pools%ROWTYPE;
  cfg public.diamond_game_configs%ROWTYPE;
BEGIN
  IF r.status <> 'open' THEN
    RETURN r;
  END IF;
  v_elapsed_ms := floor(extract(epoch FROM (clock_timestamp() - r.started_at)) * 1000)::bigint;
  v_now_cents := public.fn_crash_multiplier_cents(r.growth_k, v_elapsed_ms, r.cap_cents);

  -- An auto target below the crash point is honoured the moment the curve
  -- passes it, whatever else happened since.
  IF r.auto_cashout_cents IS NOT NULL AND r.auto_cashout_cents < r.crash_cents AND v_now_cents >= r.auto_cashout_cents THEN
    v_result := 'cashed'; v_at_cents := r.auto_cashout_cents;
  -- The curve reached the cap before the crash point: cashed at the cap.
  ELSIF r.crash_cents >= r.cap_cents AND v_now_cents >= r.cap_cents THEN
    v_result := 'cashed'; v_at_cents := r.cap_cents;
  -- The curve reached the crash point: nothing.
  ELSIF v_now_cents >= r.crash_cents THEN
    v_result := 'crashed'; v_at_cents := NULL;
  ELSIF p_cashout THEN
    v_result := 'cashed'; v_at_cents := v_now_cents;
  ELSE
    RETURN r;
  END IF;

  SELECT * INTO cfg FROM public.diamond_game_configs WHERE host_id = r.host_id AND game = 'crash';
  SELECT * INTO pool FROM public.diamond_game_pools WHERE host_id = r.host_id AND game = 'crash' FOR UPDATE;

  IF v_result = 'cashed' THEN
    v_payout := round(r.bet_chips * v_at_cents / 100, 2);
    IF v_payout > r.reserved_chips THEN
      RAISE EXCEPTION 'fn_crash_decide: payout % exceeds the round''s reservation % (cap %)', v_payout, r.reserved_chips, r.cap_cents;
    END IF;
    SELECT x.bank_after, x.member_after INTO v_bank_after, v_member_after
      FROM public.fn_diamond_game_prize_leg('crash', r.host_id, r.host_kind, r.club_id, r.user_id, v_payout,
             'crash-prize:' || r.id::text,
             format('Diamond Crash: cashed out at %s.%sx', v_at_cents / 100, lpad((v_at_cents % 100)::text, 2, '0')),
             jsonb_build_object('round_id', r.id, 'host_id', r.host_id, 'host_kind', r.host_kind,
                                'cashout_cents', v_at_cents, 'crash_cents', r.crash_cents, 'auto', r.auto_cashout_cents IS NOT NULL AND v_at_cents = r.auto_cashout_cents)) x;
  END IF;

  UPDATE public.diamond_game_pools
     SET chips_paid = chips_paid + v_payout,
         reserved_chips = reserved_chips - r.reserved_chips,
         updated_at = now()
   WHERE host_id = r.host_id AND game = 'crash'
   RETURNING * INTO pool;
  IF pool.chips_paid + pool.reserved_chips > pool.chips_minted + cfg.exposure_allowance_chips + 0.000001 THEN
    RAISE EXCEPTION 'fn_crash_decide: chips_paid % + reserved % would exceed chips_minted % + allowance % - the cap was bypassed',
      pool.chips_paid, pool.reserved_chips, pool.chips_minted, cfg.exposure_allowance_chips;
  END IF;

  UPDATE public.crash_rounds
     SET status = v_result, settled_at = clock_timestamp(), settled_by = p_by,
         elapsed_ms = LEAST(v_elapsed_ms, 2147483647)::integer, cashout_cents = v_at_cents, payout_chips = v_payout,
         pool_chips_minted_after = pool.chips_minted, pool_chips_paid_after = pool.chips_paid,
         member_chips_after = COALESCE(v_member_after, member_chips_after)
   WHERE id = r.id
   RETURNING * INTO r;
  RETURN r;
END $$;


ALTER FUNCTION public.fn_crash_decide(p_round public.crash_rounds, p_cashout boolean, p_by text) OWNER TO postgres;

--
-- Name: fn_crash_multiplier_cents(numeric, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crash_multiplier_cents(p_k numeric, p_elapsed_ms bigint, p_cap_cents integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT LEAST(p_cap_cents::numeric,
               floor(exp(LEAST(p_k * GREATEST(p_elapsed_ms, 0)::numeric / 1000, 12::numeric)) * 100))::integer;
$$;


ALTER FUNCTION public.fn_crash_multiplier_cents(p_k numeric, p_elapsed_ms bigint, p_cap_cents integer) OWNER TO postgres;

--
-- Name: fn_crash_point_cents(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crash_point_cents(p_roll numeric) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT GREATEST(100::bigint, floor(22517998136852480::numeric / (p_roll + 1))::bigint);
$$;


ALTER FUNCTION public.fn_crash_point_cents(p_roll numeric) OWNER TO postgres;

--
-- Name: fn_crash_round_result(public.crash_rounds); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crash_round_result(r public.crash_rounds) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'ok', true, 'game', 'crash', 'round_id', r.id, 'club_id', r.club_id, 'host_id', r.host_id,
    'status', r.status, 'bet_diamonds', r.bet_diamonds, 'bet_chips', r.bet_chips,
    'diamonds_per_chip', r.diamonds_per_chip,
    'cap_cents', r.cap_cents, 'growth_k', r.growth_k, 'auto_cashout_cents', r.auto_cashout_cents,
    'started_at', r.started_at, 'server_now', clock_timestamp(),
    'elapsed_ms', CASE WHEN r.status = 'open'
                       THEN floor(extract(epoch FROM (clock_timestamp() - r.started_at)) * 1000)::bigint
                       ELSE r.elapsed_ms END,
    'multiplier_now_cents', CASE WHEN r.status = 'open'
                       THEN public.fn_crash_multiplier_cents(r.growth_k,
                              floor(extract(epoch FROM (clock_timestamp() - r.started_at)) * 1000)::bigint, r.cap_cents) END,
    'outcome', CASE WHEN r.status = 'open' THEN NULL ELSE jsonb_build_object(
      'status', r.status, 'cashout_cents', r.cashout_cents, 'crash_cents', r.crash_cents,
      'payout_chips', r.payout_chips, 'settled_by', r.settled_by, 'settled_at', r.settled_at) END,
    'fairness', jsonb_build_object('commit_id', r.commit_id, 'server_seed_hash', r.server_seed_hash,
                                   'client_seed', r.client_seed, 'nonce', r.nonce)
                || CASE WHEN r.status = 'open' THEN '{}'::jsonb
                        ELSE jsonb_build_object('server_seed', r.server_seed, 'roll', r.roll, 'crash_cents', r.crash_cents) END,
    'balances', jsonb_build_object('diamonds', r.diamonds_after, 'member_chips', r.member_chips_after),
    'pool', jsonb_build_object('chips_minted', r.pool_chips_minted_after, 'chips_paid', r.pool_chips_paid_after),
    'created_at', r.created_at);
$$;


ALTER FUNCTION public.fn_crash_round_result(r public.crash_rounds) OWNER TO postgres;

--
-- Name: fn_crash_settle(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crash_settle(p_round_id uuid, p_cashout boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  r public.crash_rounds;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In To Play');
  END IF;
  SELECT * INTO r FROM public.crash_rounds WHERE id = p_round_id;
  IF r.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Round Could Not Be Found');
  END IF;
  IF r.user_id <> v_user AND COALESCE(auth.role(), '') <> 'service_role' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Round Belongs To Another Player');
  END IF;
  IF r.status <> 'open' THEN
    RETURN public.fn_crash_round_result(r);
  END IF;
  IF public.fn_platform_frozen() THEN
    -- The clock is frozen with the platform: the round waits, nothing is decided.
    RETURN public.fn_crash_round_result(r) || jsonb_build_object('frozen', true);
  END IF;
  -- The host lock serialises settlement with new rounds on the same pool.
  PERFORM 1 FROM public.diamond_game_configs WHERE host_id = r.host_id AND game = 'crash' FOR UPDATE;
  SELECT * INTO r FROM public.crash_rounds WHERE id = p_round_id FOR UPDATE;
  r := public.fn_crash_decide(r, COALESCE(p_cashout, false), CASE WHEN COALESCE(p_cashout, false) THEN 'player' ELSE 'tick' END);
  RETURN public.fn_crash_round_result(r);
END $$;


ALTER FUNCTION public.fn_crash_settle(p_round_id uuid, p_cashout boolean) OWNER TO postgres;

--
-- Name: fn_crash_settle_decided(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crash_settle_decided(p_host uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE r public.crash_rounds; v_n integer := 0; v_after public.crash_rounds;
BEGIN
  FOR r IN SELECT * FROM public.crash_rounds c
            WHERE c.host_id = p_host AND c.status = 'open'
              AND clock_timestamp() >= c.started_at + make_interval(secs => (ln(c.cap_cents::numeric / 100) / c.growth_k)::double precision + 0.05)
            ORDER BY c.started_at FOR UPDATE LOOP
    v_after := public.fn_crash_decide(r, false, 'time');
    IF v_after.status <> 'open' THEN v_n := v_n + 1; END IF;
  END LOOP;
  RETURN v_n;
END $$;


ALTER FUNCTION public.fn_crash_settle_decided(p_host uuid) OWNER TO postgres;

--
-- Name: fn_crash_start(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crash_start(p_club_id uuid, p_commit_id uuid, p_client_seed text, p_bet_diamonds integer, p_auto_cashout_cents integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  prior public.crash_rounds;
  adm record;
  v_id uuid := gen_random_uuid();
  v_hmac bytea; v_roll numeric; v_crash bigint; v_cap integer;
  v_reserve numeric; v_deduct jsonb; v_dia_after numeric; v_member_chips numeric;
  pool public.diamond_game_pools%ROWTYPE;
  r public.crash_rounds;
BEGIN
  SELECT * INTO prior FROM public.crash_rounds WHERE commit_id = p_commit_id;
  IF prior.id IS NOT NULL THEN
    IF prior.user_id <> v_user THEN
      RETURN jsonb_build_object('ok', false, 'error', 'That Round Belongs To Another Player');
    END IF;
    RETURN public.fn_crash_round_result(prior) || jsonb_build_object('replayed', true);
  END IF;

  SELECT * INTO adm FROM public.fn_diamond_game_admit('crash', p_club_id, p_commit_id, p_client_seed, p_bet_diamonds);
  IF adm.err IS NOT NULL THEN RETURN adm.err; END IF;

  -- One open round per player per host: finish it first (a refresh resumes it).
  SELECT * INTO prior FROM public.crash_rounds c WHERE c.host_id = adm.o_host AND c.user_id = v_user AND c.status = 'open'
   ORDER BY c.started_at DESC LIMIT 1;
  IF prior.id IS NOT NULL THEN
    RETURN public.fn_crash_round_result(prior) || jsonb_build_object('resumed', true);
  END IF;

  v_cap := public.fn_diamond_game_cap_cents(adm.o_cfg, adm.o_pool, adm.o_bank, adm.o_bet_chips, (adm.o_cfg).max_multiplier_cents);
  IF v_cap < 101 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Bank Cannot Cover A Win At That Bet Right Now. Try A Smaller Bet',
                              'cap_cents', v_cap);
  END IF;
  IF p_auto_cashout_cents IS NOT NULL AND (p_auto_cashout_cents < 101 OR p_auto_cashout_cents > v_cap) THEN
    RETURN jsonb_build_object('ok', false, 'error', format('Auto Cash Out Must Be Between 1.01x And %s.%sx', v_cap / 100, lpad((v_cap % 100)::text, 2, '0')),
                              'cap_cents', v_cap);
  END IF;
  v_reserve := round(adm.o_bet_chips * v_cap / 100, 2);

  -- ── the roll: the crash point, sealed in the row ───────────────────────────
  v_hmac := extensions.hmac(convert_to(p_client_seed || ':' || adm.o_nonce::text, 'UTF8'),
                            convert_to((adm.o_commit).server_seed, 'UTF8'), 'sha256');
  v_roll  := (('x' || encode(substring(v_hmac from 1 for 6), 'hex'))::bit(48)::bigint)::numeric;
  v_crash := public.fn_crash_point_cents(v_roll);

  -- ── 1. the bet is paid for ─────────────────────────────────────────────────
  v_deduct := public.fn_diamond_game_take_bet(v_user, p_bet_diamonds, (adm.o_cfg).purchased_only, 'crash_bet',
                format('Diamond Crash Bet (%s Diamonds)', p_bet_diamonds),
                'crash:' || v_id::text,
                jsonb_build_object('round_id', v_id, 'club_id', p_club_id, 'host_id', adm.o_host, 'commit_id', p_commit_id));
  IF COALESCE((v_deduct->>'success')::boolean, false) = false THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not Enough Diamonds For That Bet', 'detail', v_deduct->>'error');
  END IF;

  -- ── 2. the host is paid its chip share, the payout is reserved ─────────────
  PERFORM public.fn_diamond_game_mint_leg(adm.o_host, adm.o_kind, adm.o_mint, 'crash-mint:' || v_id::text);
  UPDATE public.diamond_game_pools
     SET rounds = rounds + 1,
         intake_diamonds = intake_diamonds + p_bet_diamonds,
         chips_minted = chips_minted + adm.o_mint,
         reserved_chips = reserved_chips + v_reserve,
         constrained_rounds = constrained_rounds + CASE WHEN v_cap < (adm.o_cfg).max_multiplier_cents THEN 1 ELSE 0 END,
         updated_at = now()
   WHERE host_id = adm.o_host AND game = 'crash'
   RETURNING * INTO pool;
  IF pool.chips_paid + pool.reserved_chips > pool.chips_minted + (adm.o_cfg).exposure_allowance_chips THEN
    RAISE EXCEPTION 'fn_crash_start: reserved % + paid % would exceed chips_minted % + allowance % - the cap was bypassed',
      pool.reserved_chips, pool.chips_paid, pool.chips_minted, (adm.o_cfg).exposure_allowance_chips;
  END IF;

  SELECT COALESCE(p.diamonds, 0) INTO v_dia_after FROM public.profiles p WHERE p.id = v_user;
  SELECT COALESCE(cm.chip_balance, 0) INTO v_member_chips FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = v_user LIMIT 1;
  UPDATE public.diamond_game_commits SET consumed_by = v_id WHERE id = p_commit_id;

  INSERT INTO public.crash_rounds
    (id, host_id, host_kind, club_id, user_id, bet_diamonds, bet_chips, diamonds_per_chip,
     commit_id, server_seed_hash, server_seed, client_seed, nonce, roll, crash_cents, cap_cents, growth_k,
     auto_cashout_cents, reserved_chips, chips_minted, diamonds_after, member_chips_after, is_fixture, started_at)
  VALUES
    (v_id, adm.o_host, adm.o_kind, p_club_id, v_user, p_bet_diamonds, adm.o_bet_chips, adm.o_rate,
     p_commit_id, (adm.o_commit).server_seed_hash, (adm.o_commit).server_seed, p_client_seed, adm.o_nonce, v_roll, v_crash, v_cap, (adm.o_cfg).growth_k,
     p_auto_cashout_cents, v_reserve, adm.o_mint, v_dia_after, v_member_chips, adm.o_fixture, clock_timestamp())
  RETURNING * INTO r;
  RETURN public.fn_crash_round_result(r);
END $$;


ALTER FUNCTION public.fn_crash_start(p_club_id uuid, p_commit_id uuid, p_client_seed text, p_bet_diamonds integer, p_auto_cashout_cents integer) OWNER TO postgres;

--
-- Name: fn_create_agent(uuid, uuid, text, uuid, numeric, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_agent(p_user_id uuid, p_club_id uuid, p_role text, p_parent_agent_id uuid, p_commission_rate numeric, p_player_rakeback_rate numeric, p_credit_limit numeric, p_is_prepaid boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_caller uuid := (SELECT auth.uid());
  v_membership_user uuid; v_member_role text;
  v_parent_role text; v_parent_comm numeric; v_parent_rake numeric; v_parent_limit numeric;
  v_new_id uuid; v_role_res jsonb;
  v_is_staff boolean; v_comm numeric; v_rake numeric; v_prepaid boolean;
BEGIN
  IF p_user_id IS NULL OR p_club_id IS NULL THEN RETURN jsonb_build_object('success',false,'error','user and club required'); END IF;
  IF v_caller IS NULL THEN RETURN jsonb_build_object('success',false,'error','authentication required'); END IF;
  IF NOT EXISTS (SELECT 1 FROM clubs c WHERE c.id=p_club_id AND (c.owner_id=v_caller
     OR EXISTS (SELECT 1 FROM club_members cm WHERE cm.club_id=p_club_id AND cm.user_id=v_caller AND cm.role IN ('owner','co_owner','admin')))) THEN
    RETURN jsonb_build_object('success',false,'error','not authorized to manage this club''s agents'); END IF;
  IF p_role IS NULL OR p_role NOT IN ('super_agent','agent','sub_agent') THEN RETURN jsonb_build_object('success',false,'error','invalid role'); END IF;
  IF p_commission_rate IS NULL OR p_commission_rate < 0 OR p_commission_rate > 0.7 THEN RETURN jsonb_build_object('success',false,'error','commission rate must be 0-0.7'); END IF;
  IF p_player_rakeback_rate IS NULL OR p_player_rakeback_rate < 0 OR p_player_rakeback_rate > 0.5 THEN RETURN jsonb_build_object('success',false,'error','rakeback rate must be 0-0.5'); END IF;
  IF p_credit_limit IS NULL OR p_credit_limit < 0 THEN RETURN jsonb_build_object('success',false,'error','credit_limit must be >= 0'); END IF;
  IF EXISTS (SELECT 1 FROM agents WHERE user_id=p_user_id AND club_id=p_club_id) THEN RETURN jsonb_build_object('success',false,'error','already an agent in this club'); END IF;

  SELECT user_id, role INTO v_membership_user, v_member_role
    FROM club_members WHERE club_id=p_club_id AND user_id=p_user_id;

  -- Dan, 2026-08-31: "OWNERS AND CO OWNERS CAN AND SHOULD HAVE AGENT WALLETS,
  -- THAT WAS A MISTAKE."
  --
  -- PR #2132 refused outright here, on the reasoning that staff earn no
  -- rakeback so making one an agent is a demotion wearing a create button. That
  -- conflated two separate things. The agents row is BOTH the commission
  -- profile AND the agent wallet, and Dan's chip flow - main bank to agent
  -- wallet to agents and players - requires an owner or a co-owner to hold one.
  -- What they must not get is a rate, and what they must not lose is their
  -- title. Both are handled below instead of refusing the whole operation.
  v_is_staff := v_member_role IN ('owner','co_owner','admin');

  -- Owners keep earning (Dan, B-02, 2026-08-31). A co-owner and an admin do
  -- not, so their wallet is minted at zero rather than at whatever the caller
  -- typed; trg_agents_staff_earn_no_rakeback would zero it anyway, and doing it
  -- here means the row and the request agree instead of silently differing.
  IF v_member_role IN ('co_owner','admin') THEN
    v_comm := 0;
    v_rake := 0;
  ELSE
    v_comm := p_commission_rate;
    v_rake := p_player_rakeback_rate;
  END IF;

  -- Prepaid or a line, and how much. There is no third option, and the pair
  -- that means "can send nothing at all" is refused rather than stored.
  v_prepaid := COALESCE(p_is_prepaid, false);
  IF v_prepaid AND p_credit_limit <> 0 THEN
    RETURN jsonb_build_object('success',false,'error','a prepaid agent carries no credit line, so the limit must be 0');
  END IF;
  IF NOT v_prepaid AND p_credit_limit <= 0 THEN
    RETURN jsonb_build_object('success',false,'needs_funding',true,
      'error','choose prepaid, or give a credit limit greater than 0');
  END IF;

  IF p_parent_agent_id IS NOT NULL THEN
    SELECT role, commission_rate, player_rakeback_rate, credit_limit
      INTO v_parent_role, v_parent_comm, v_parent_rake, v_parent_limit
      FROM agents WHERE id=p_parent_agent_id;
    IF v_parent_role IS NULL THEN RETURN jsonb_build_object('success',false,'error','parent agent not found'); END IF;
    IF v_parent_role = 'sub_agent' THEN RETURN jsonb_build_object('success',false,'error','sub-agents cannot have sub-agents'); END IF;
    IF v_comm > v_parent_comm THEN RETURN jsonb_build_object('success',false,'error','commission rate cannot exceed parent rate'); END IF;
    IF v_rake > v_parent_rake THEN RETURN jsonb_build_object('success',false,'error','rakeback rate cannot exceed parent rate'); END IF;
    IF v_parent_limit IS NOT NULL AND p_credit_limit > v_parent_limit THEN
      RETURN jsonb_build_object('success',false,'error','credit limit cannot exceed parent agent limit'); END IF;
  END IF;

  INSERT INTO agents (user_id, club_id, membership_id, role, parent_agent_id, commission_rate, player_rakeback_rate, credit_limit, credit_used, is_prepaid)
  VALUES (p_user_id, p_club_id, COALESCE(v_membership_user, p_user_id), p_role, p_parent_agent_id, v_comm, v_rake, p_credit_limit, 0, v_prepaid)
  RETURNING id INTO v_new_id;

  -- THE TITLE SURVIVES THE WALLET. Giving an owner an agent wallet must not
  -- write 'agent' over 'owner' in club_members - that is a demotion nobody
  -- asked for, and fn_club_grantable_roles would refuse it anyway (an owner is
  -- never demotable through this door), so the whole create would fail with a
  -- confusing permission error. Only a player being made into an agent has a
  -- club role to change.
  IF NOT v_is_staff AND v_membership_user IS NOT NULL AND v_member_role IS DISTINCT FROM p_role THEN
    v_role_res := public.fn_club_set_member_role(
      p_club_id, p_user_id, p_role, v_caller, v_comm, v_rake, v_prepaid, p_credit_limit);
    IF NOT COALESCE((v_role_res ->> 'success')::boolean, false) THEN
      RETURN v_role_res;
    END IF;
  END IF;

  RETURN jsonb_build_object('success',true,'agent_id',v_new_id,
    'club_role_unchanged', v_is_staff, 'club_role', v_member_role);
END;
$$;


ALTER FUNCTION public.fn_create_agent(p_user_id uuid, p_club_id uuid, p_role text, p_parent_agent_id uuid, p_commission_rate numeric, p_player_rakeback_rate numeric, p_credit_limit numeric, p_is_prepaid boolean) OWNER TO postgres;

--
-- Name: fn_create_club_atomic(uuid, text, text, text, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_club_atomic(p_request_id uuid, p_name text, p_description text DEFAULT NULL::text, p_color_theme text DEFAULT 'royal-blue'::text, p_is_public boolean DEFAULT true, p_requires_approval boolean DEFAULT false, p_logo_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_result jsonb; v_previous text := COALESCE(current_setting('app.club_membership_source', true), '');
BEGIN
  PERFORM set_config('app.club_membership_source', 'club_owner_create', true);
  BEGIN
    v_result := public.fn_create_club_atomic_membership_impl(
      p_request_id, p_name, p_description, p_color_theme,
      p_is_public, p_requires_approval, p_logo_url
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.club_membership_source', v_previous, true);
    RAISE;
  END;
  PERFORM set_config('app.club_membership_source', v_previous, true);
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_create_club_atomic(p_request_id uuid, p_name text, p_description text, p_color_theme text, p_is_public boolean, p_requires_approval boolean, p_logo_url text) OWNER TO postgres;

--
-- Name: FUNCTION fn_create_club_atomic(p_request_id uuid, p_name text, p_description text, p_color_theme text, p_is_public boolean, p_requires_approval boolean, p_logo_url text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_create_club_atomic(p_request_id uuid, p_name text, p_description text, p_color_theme text, p_is_public boolean, p_requires_approval boolean, p_logo_url text) IS 'Creates a club and owner membership atomically while enforcing the universal four-club ceiling.';


--
-- Name: fn_create_club_atomic_membership_impl(uuid, text, text, text, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_club_atomic_membership_impl(p_request_id uuid, p_name text, p_description text DEFAULT NULL::text, p_color_theme text DEFAULT 'royal-blue'::text, p_is_public boolean DEFAULT true, p_requires_approval boolean DEFAULT false, p_logo_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_name text := btrim(COALESCE(p_name, ''));
  v_description text := NULLIF(btrim(COALESCE(p_description, '')), '');
  v_existing uuid;
  v_club public.clubs%ROWTYPE;
  v_code integer;
  v_slug_root text;
  v_memberships integer;
  v_attempt integer := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'A creation request ID is required' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.club_entry_feature_flags f WHERE f.key = 'create_club'
      AND (NOT f.enabled OR ((hashtextextended(v_uid::text || ':' || f.key, 44119)
          & 9223372036854775807) % 100) >= f.rollout_percent)
  ) THEN
    RAISE EXCEPTION 'Club creation is temporarily unavailable.' USING ERRCODE = 'P0001';
  END IF;
  IF length(v_name) < 3 OR length(v_name) > 30 THEN
    RAISE EXCEPTION 'Club name must be between 3 and 30 characters' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_uid::text, 77431));
  PERFORM pg_advisory_xact_lock(77432);

  SELECT club_id INTO v_existing
    FROM public.club_creation_requests
   WHERE user_id = v_uid AND request_id = p_request_id;
  IF FOUND THEN
    SELECT * INTO v_club FROM public.clubs WHERE id = v_existing;
    RETURN to_jsonb(v_club);
  END IF;

  IF EXISTS (SELECT 1 FROM public.clubs WHERE lower(name) = lower(v_name)) THEN
    RAISE EXCEPTION 'A club with this name already exists' USING ERRCODE = '23505';
  END IF;

  SELECT count(*) INTO v_memberships
    FROM public.club_members
   WHERE user_id = v_uid AND status IN ('active', 'approved');
  IF v_memberships >= 10 THEN
    RAISE EXCEPTION 'You can only be a member of up to 10 clubs. Leave a club to create a new one.'
      USING ERRCODE = '23514';
  END IF;

  v_slug_root := trim(both '-' FROM regexp_replace(lower(v_name), '[^a-z0-9]+', '-', 'g'));
  IF v_slug_root = '' THEN v_slug_root := 'club'; END IF;

  LOOP
    v_attempt := v_attempt + 1;
    IF v_attempt > 25 THEN
      RAISE EXCEPTION 'Could not allocate a unique club code. Please try again.';
    END IF;
    v_code := 10000 + floor(random() * 90000)::integer;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.clubs WHERE club_id = v_code);
  END LOOP;

  INSERT INTO public.clubs (
    club_id, name, slug, description, color_theme, is_public,
    requires_approval, owner_id, level, logo_url, avatar_url
  ) VALUES (
    v_code, v_name, left(v_slug_root, 42) || '-' || v_code::text,
    v_description, COALESCE(NULLIF(btrim(p_color_theme), ''), 'royal-blue'),
    COALESCE(p_is_public, true), COALESCE(p_requires_approval, false),
    v_uid, 1, NULLIF(p_logo_url, ''), NULLIF(p_logo_url, '')
  ) RETURNING * INTO v_club;

  INSERT INTO public.club_members (club_id, user_id, role, status, chip_balance)
  VALUES (v_club.id, v_uid, 'owner', 'active', 0);

  INSERT INTO public.club_creation_requests (user_id, request_id, club_id)
  VALUES (v_uid, p_request_id, v_club.id);

  RETURN to_jsonb(v_club);
END;
$$;


ALTER FUNCTION public.fn_create_club_atomic_membership_impl(p_request_id uuid, p_name text, p_description text, p_color_theme text, p_is_public boolean, p_requires_approval boolean, p_logo_url text) OWNER TO postgres;

--
-- Name: fn_create_home_group_conversation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_home_group_conversation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_conv_id uuid;
BEGIN
    INSERT INTO conversations (participant_ids, created_by, category, is_pinned, is_read_only)
    VALUES (ARRAY[NEW.owner_id]::uuid[], NEW.owner_id, 'home_group', false, false)
    RETURNING id INTO v_conv_id;
    UPDATE commander_home_groups SET messenger_conversation_id = v_conv_id WHERE id = NEW.id;
    INSERT INTO messenger_participants (conversation_id, user_id, role, joined_at)
    VALUES (v_conv_id, NEW.owner_id, 'admin', NOW()) ON CONFLICT DO NOTHING;
    RETURN NEW;
END; $$;


ALTER FUNCTION public.fn_create_home_group_conversation() OWNER TO postgres;

--
-- Name: fn_create_media_upload(uuid, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_media_upload(p_user_id uuid, p_file_name text, p_mime_type text, p_file_size integer, p_media_type text) RETURNS TABLE(media_id uuid, bucket_name text, file_path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text;
  v_caller_uid uuid;
  v_media_id uuid;
  v_bucket text;
  v_path text;
  v_safe_name text;
  v_max_size constant integer := 100 * 1024 * 1024; -- 100 MB hard cap
BEGIN
  -- Args validation
  IF p_user_id IS NULL OR p_file_name IS NULL OR length(p_file_name) = 0 THEN
    RAISE EXCEPTION 'fn_create_media_upload: user_id and file_name required';
  END IF;
  IF p_file_size IS NULL OR p_file_size <= 0 OR p_file_size > v_max_size THEN
    RAISE EXCEPTION 'fn_create_media_upload: invalid file_size (%, max %)', p_file_size, v_max_size;
  END IF;

  -- Spoof guard: authenticated callers must own the upload.
  v_caller_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '');
  v_caller_uid := auth.uid();
  IF v_caller_role = 'authenticated' THEN
    IF v_caller_uid IS NULL OR p_user_id <> v_caller_uid THEN
      RAISE EXCEPTION 'fn_create_media_upload: forbidden author spoof';
    END IF;
  ELSIF v_caller_role = 'anon' OR v_caller_role = '' THEN
    RAISE EXCEPTION 'fn_create_media_upload: unauthorized';
  END IF;

  -- Bucket selection - videos to a separate bucket so size-cap and
  -- transcode hooks can differ. Default to social-media-images.
  v_bucket := CASE
    WHEN COALESCE(p_media_type, '') ILIKE 'video%' THEN 'social-media-videos'
    ELSE 'social-media-images'
  END;

  -- Sanitize file name: strip path separators, keep extension.
  v_safe_name := regexp_replace(p_file_name, '[^A-Za-z0-9._-]', '_', 'g');
  v_safe_name := substring(v_safe_name FROM 1 FOR 100);

  -- Pre-generate the media id so we own the storage path.
  v_media_id := gen_random_uuid();
  v_path := p_user_id::text || '/' || to_char(now(), 'YYYY/MM/DD') || '/' || v_media_id::text || '_' || v_safe_name;

  INSERT INTO public.social_media (
    id, uploader_id, file_name, file_size, content_type, storage_path, created_at
  ) VALUES (
    v_media_id, p_user_id, p_file_name, p_file_size, p_mime_type, v_path, now()
  );

  RETURN QUERY SELECT v_media_id, v_bucket, v_path;
END;
$$;


ALTER FUNCTION public.fn_create_media_upload(p_user_id uuid, p_file_name text, p_mime_type text, p_file_size integer, p_media_type text) OWNER TO postgres;

--
-- Name: fn_create_seat_first_game_atomic(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_seat_first_game_atomic(p_tournament_id uuid, p_config jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_existing public.tournaments%ROWTYPE;
  v_existing_table public.tables%ROWTYPE;
  v_existing_table_count integer;
  v_created public.tournaments%ROWTYPE;
  v_table_id uuid;
  v_club_id uuid;
  v_union_id uuid;
  v_name text;
  v_game_type text;
  v_table_variant text;
  v_variant text;
  v_tournament_type text;
  v_buy_in numeric;
  v_buy_in_fee numeric;
  v_guarantee numeric;
  v_starting_chips integer;
  v_max_players integer;
  v_min_players integer;
  v_table_size integer;
  v_blinds jsonb;
  v_payouts jsonb;
  v_start_time timestamptz;
  v_late_reg_levels integer;
  v_late_reg_mins integer;
  v_satellite_target_id uuid;
  v_satellite_seats integer;
  v_short_description text;
  v_requested_current_players integer;
  v_requested_status text;
  v_first_level jsonb;
  v_small_blind numeric;
  v_big_blind numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_config IS NULL OR jsonb_typeof(p_config) <> 'object' THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_INVALID_REQUEST'
      USING ERRCODE = '22023';
  END IF;

  /* Every accepted request key must be represented by the durable pair below.
     Rejecting unknown keys prevents an idempotent replay from appearing exact
     after a caller adds configuration this creator silently ignores. */
  IF EXISTS (
    SELECT 1
      FROM jsonb_object_keys(p_config) AS supplied(key)
     WHERE supplied.key NOT IN (
       'club_id', 'union_id', 'name', 'game_type', 'variant',
       'tournament_type', 'buy_in_amount', 'buy_in_fee', 'guaranteed_prize',
       'starting_chips', 'max_players', 'min_players', 'table_size',
       'current_players', 'status', 'blind_structure', 'payout_structure',
       'start_time', 'late_reg_levels', 'late_reg_mins',
       'satellite_target_id', 'satellite_seats', 'short_description',
       'spin_multiplier', 'spin_locked_tiers'
     )
  ) THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_UNKNOWN_CONFIG_KEY'
      USING ERRCODE = '22023';
  END IF;

  /* This is an entry-producing transaction. It takes the same first lock as
     every purchase path, before the idempotency key or either game row. */
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'platform_frozen');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:seat-first-create:' || p_tournament_id::text, 0)
  );

  v_club_id := NULLIF(p_config->>'club_id', '')::uuid;
  v_union_id := NULLIF(p_config->>'union_id', '')::uuid;
  v_name := NULLIF(btrim(p_config->>'name'), '');
  v_game_type := NULLIF(btrim(p_config->>'game_type'), '');
  v_table_variant := lower(v_game_type);
  v_variant := lower(NULLIF(btrim(p_config->>'variant'), ''));
  v_tournament_type := upper(NULLIF(btrim(p_config->>'tournament_type'), ''));
  v_buy_in := COALESCE(NULLIF(p_config->>'buy_in_amount', '')::numeric, 0);
  v_buy_in_fee := COALESCE(NULLIF(p_config->>'buy_in_fee', '')::numeric, 0);
  v_guarantee := COALESCE(NULLIF(p_config->>'guaranteed_prize', '')::numeric, 0);
  v_starting_chips := NULLIF(p_config->>'starting_chips', '')::integer;
  v_max_players := NULLIF(p_config->>'max_players', '')::integer;
  v_min_players := COALESCE(NULLIF(p_config->>'min_players', '')::integer, v_max_players);
  v_table_size := COALESCE(NULLIF(p_config->>'table_size', '')::integer, v_max_players);
  v_blinds := p_config->'blind_structure';
  v_payouts := COALESCE(p_config->'payout_structure', '[]'::jsonb);
  v_start_time := NULLIF(p_config->>'start_time', '')::timestamptz;
  v_late_reg_levels := COALESCE(NULLIF(p_config->>'late_reg_levels', '')::integer, 0);
  v_late_reg_mins := COALESCE(NULLIF(p_config->>'late_reg_mins', '')::integer, 0);
  v_satellite_target_id := NULLIF(p_config->>'satellite_target_id', '')::uuid;
  v_satellite_seats := NULLIF(p_config->>'satellite_seats', '')::integer;
  v_short_description := NULLIF(btrim(p_config->>'short_description'), '');
  v_requested_current_players :=
    COALESCE(NULLIF(p_config->>'current_players', '')::integer, 0);
  v_requested_status :=
    upper(COALESCE(NULLIF(btrim(p_config->>'status'), ''), 'REGISTERING'));

  IF v_club_id IS NULL
     OR v_name IS NULL
     OR v_game_type IS NULL
     OR v_variant IS NULL
     OR v_tournament_type IS NULL
     OR v_starting_chips IS NULL OR v_starting_chips <= 0
     OR v_max_players IS NULL OR v_max_players < 2 OR v_max_players > 3
     OR v_min_players < 2 OR v_min_players > v_max_players
     OR v_table_size <> v_max_players
     OR v_start_time IS NULL
     OR jsonb_typeof(v_blinds) <> 'array'
     OR jsonb_array_length(v_blinds) = 0
     OR jsonb_typeof(v_payouts) <> 'array'
     OR NOT (v_variant = 'spin' OR v_max_players = 2)
     OR v_tournament_type NOT IN ('SPIN', 'SNG', 'SATELLITE')
     OR v_table_variant NOT IN ('nlh', 'plo4', 'plo5', 'plo6', 'plo8', 'short_deck', 'flh', 'flo8')
     OR v_requested_current_players <> 0
     OR v_requested_status <> 'REGISTERING'
     OR NULLIF(p_config->>'spin_multiplier', '') IS NOT NULL
     OR (
       p_config ? 'spin_locked_tiers'
       AND jsonb_typeof(p_config->'spin_locked_tiers') IS DISTINCT FROM 'null'
     )
     OR (v_tournament_type = 'SPIN' AND (v_variant <> 'spin' OR v_max_players <> 3))
     OR (
       v_tournament_type = 'SATELLITE'
       AND (
         v_satellite_target_id IS NULL
         OR v_satellite_seats IS NULL
         OR v_satellite_seats <= 0
         OR v_satellite_seats > v_max_players
       )
     )
     OR (
       v_tournament_type <> 'SATELLITE'
       AND (v_satellite_target_id IS NOT NULL OR v_satellite_seats IS NOT NULL)
     )
     OR v_buy_in < 0 OR v_buy_in_fee < 0 OR v_guarantee < 0 THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_INVALID_CONFIG'
      USING ERRCODE = '22023';
  END IF;

  v_first_level := v_blinds->0;
  v_small_blind := COALESCE(
    NULLIF(v_first_level->>'smallBlind', '')::numeric,
    NULLIF(v_first_level->>'small_blind', '')::numeric,
    NULLIF(v_first_level->>'sb', '')::numeric
  );
  v_big_blind := COALESCE(
    NULLIF(v_first_level->>'bigBlind', '')::numeric,
    NULLIF(v_first_level->>'big_blind', '')::numeric,
    NULLIF(v_first_level->>'bb', '')::numeric
  );
  IF v_small_blind IS NULL OR v_small_blind <= 0
     OR v_big_blind IS NULL OR v_big_blind < v_small_blind THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_INVALID_BLINDS'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF FOUND THEN
    SELECT count(*) INTO v_existing_table_count
      FROM public.tables tb
     WHERE tb.tournament_id = p_tournament_id
       AND COALESCE(tb.is_deleted, false) = false
       AND tb.status IN ('waiting', 'running');

    IF v_existing_table_count <> 1 THEN
      RAISE EXCEPTION
        'SEAT_FIRST_ATOMIC_PARTIAL_STATE: tournament % has % joinable tables',
        p_tournament_id, v_existing_table_count
        USING ERRCODE = '23514';
    END IF;

    SELECT tb.* INTO v_existing_table
      FROM public.tables tb
     WHERE tb.tournament_id = p_tournament_id
       AND COALESCE(tb.is_deleted, false) = false
       AND tb.status IN ('waiting', 'running')
     ORDER BY tb.created_at, tb.id
     LIMIT 1
     FOR UPDATE;
    v_table_id := v_existing_table.id;

    IF v_existing.club_id IS DISTINCT FROM v_club_id
       OR v_existing.union_id IS DISTINCT FROM v_union_id
       OR v_existing.name IS DISTINCT FROM v_name
       OR lower(v_existing.game_type) IS DISTINCT FROM lower(v_game_type)
       OR lower(v_existing.variant) IS DISTINCT FROM v_variant
       OR upper(v_existing.tournament_type) IS DISTINCT FROM v_tournament_type
       OR v_existing.buy_in_amount IS DISTINCT FROM v_buy_in
       OR v_existing.buy_in_fee IS DISTINCT FROM v_buy_in_fee
       OR v_existing.guaranteed_prize IS DISTINCT FROM v_guarantee
       OR v_existing.starting_chips IS DISTINCT FROM v_starting_chips
       OR v_existing.max_players IS DISTINCT FROM v_max_players
       OR v_existing.min_players IS DISTINCT FROM v_min_players
       OR v_existing.table_size IS DISTINCT FROM v_table_size
       OR (v_existing.blind_structure)::jsonb IS DISTINCT FROM v_blinds
       OR (v_existing.payout_structure)::jsonb IS DISTINCT FROM v_payouts
       OR v_existing.start_time IS DISTINCT FROM v_start_time
       OR v_existing.late_reg_levels IS DISTINCT FROM v_late_reg_levels
       OR v_existing.late_reg_mins IS DISTINCT FROM v_late_reg_mins
       OR v_existing.satellite_target_id IS DISTINCT FROM v_satellite_target_id
       OR v_existing.satellite_seats IS DISTINCT FROM v_satellite_seats
       OR v_existing.short_description IS DISTINCT FROM v_short_description
       OR v_existing_table.club_id IS DISTINCT FROM v_club_id
       OR v_existing_table.tournament_id IS DISTINCT FROM p_tournament_id
       OR v_existing_table.name IS DISTINCT FROM v_name
       OR lower(v_existing_table.game_type) IS DISTINCT FROM 'tournament'
       OR lower(v_existing_table.game_variant) IS DISTINCT FROM v_table_variant
       OR v_existing_table.stakes IS DISTINCT FROM
          (v_small_blind::text || '/' || v_big_blind::text)
       OR v_existing_table.small_blind IS DISTINCT FROM v_small_blind
       OR v_existing_table.big_blind IS DISTINCT FROM v_big_blind
       OR v_existing_table.min_buy_in IS DISTINCT FROM 0::numeric
       OR v_existing_table.max_buy_in IS DISTINCT FROM 0::numeric
       OR v_existing_table.max_players IS DISTINCT FROM v_max_players THEN
      RAISE EXCEPTION 'SEAT_FIRST_CREATE_IDEMPOTENCY_MISMATCH: %', p_tournament_id
        USING ERRCODE = '22023';
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'replayed', true,
      'tournament', to_jsonb(v_existing),
      'table_id', v_table_id
    );
  END IF;

  INSERT INTO public.tournaments (
    id, club_id, union_id, name, game_type, variant, tournament_type,
    buy_in_amount, buy_in_fee, guaranteed_prize, starting_chips,
    max_players, min_players, table_size, current_players, status,
    blind_structure, payout_structure, start_time,
    late_reg_levels, late_reg_mins,
    satellite_target_id, satellite_seats, short_description
  ) VALUES (
    p_tournament_id, v_club_id, v_union_id, v_name, v_game_type, v_variant,
    v_tournament_type, v_buy_in, v_buy_in_fee, v_guarantee, v_starting_chips,
    v_max_players, v_min_players, v_table_size, 0, 'REGISTERING',
    v_blinds::text, v_payouts::text, v_start_time,
    v_late_reg_levels, v_late_reg_mins,
    v_satellite_target_id, v_satellite_seats, v_short_description
  ) RETURNING * INTO v_created;

  INSERT INTO public.tables (
    club_id, tournament_id, name, game_type, game_variant, stakes,
    small_blind, big_blind, min_buy_in, max_buy_in,
    max_players, current_players, status
  ) VALUES (
    v_club_id, p_tournament_id, v_name, 'tournament', v_table_variant,
    v_small_blind::text || '/' || v_big_blind::text,
    v_small_blind, v_big_blind, 0, 0,
    v_max_players, 0, 'waiting'
  ) RETURNING id INTO v_table_id;

  RETURN jsonb_build_object(
    'ok', true,
    'replayed', false,
    'tournament', to_jsonb(v_created),
    'table_id', v_table_id
  );
END;
$$;


ALTER FUNCTION public.fn_create_seat_first_game_atomic(p_tournament_id uuid, p_config jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_create_seat_first_game_atomic(p_tournament_id uuid, p_config jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_create_seat_first_game_atomic(p_tournament_id uuid, p_config jsonb) IS 'Stage-A creator for a Spin, heads-up SNG or heads-up satellite and its joinable table in one service-only transaction. The caller-supplied tournament UUID is the exact replay key.';


--
-- Name: fn_create_settlement_period(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_settlement_period(p_club_id uuid, p_user_id uuid, p_period_start date DEFAULT CURRENT_DATE, p_period_end date DEFAULT (CURRENT_DATE + '7 days'::interval)) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_period_id uuid;
  v_rate numeric;
BEGIN
  SELECT COALESCE(a.player_rakeback_rate, 0.10) INTO v_rate
    FROM public.player_agent_assignments paa
    LEFT JOIN public.agents a ON a.id = paa.agent_id
   WHERE paa.player_id = p_user_id AND paa.club_id = p_club_id
   LIMIT 1;
  v_rate := COALESCE(v_rate, 0.10);

  INSERT INTO public.rakeback_periods
    (user_id, club_id, period_start, period_end, rakeback_rate, status)
  VALUES
    (p_user_id, p_club_id, p_period_start, p_period_end, v_rate, 'pending')
  RETURNING id INTO v_period_id;

  RETURN v_period_id;
END;
$$;


ALTER FUNCTION public.fn_create_settlement_period(p_club_id uuid, p_user_id uuid, p_period_start date, p_period_end date) OWNER TO postgres;

--
-- Name: fn_create_social_post(uuid, text, text, text[], text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_social_post(p_author_id uuid, p_content text DEFAULT ''::text, p_content_type text DEFAULT 'text'::text, p_media_urls text[] DEFAULT '{}'::text[], p_visibility text DEFAULT 'public'::text, p_achievement_data jsonb DEFAULT NULL::jsonb, p_thumbnail_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_post_id uuid;
  v_media_jsonb jsonb := to_jsonb(COALESCE(p_media_urls, '{}'::text[]));
  v_caller_role text := COALESCE(auth.role()::text, '');
  v_caller_uid uuid := auth.uid();
BEGIN
  IF v_caller_role = 'authenticated' THEN
    IF v_caller_uid IS NULL OR p_author_id IS DISTINCT FROM v_caller_uid THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'forbidden: authenticated users may only post as themselves'
      );
    END IF;
  ELSIF v_caller_role <> 'service_role' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'forbidden: anonymous callers cannot create posts'
    );
  END IF;

  INSERT INTO public.social_posts (
    author_id,
    content,
    content_type,
    media_urls,
    visibility,
    achievement_data,
    thumbnail_url,
    created_at,
    updated_at
  ) VALUES (
    p_author_id,
    p_content,
    p_content_type,
    v_media_jsonb,
    p_visibility,
    p_achievement_data,
    p_thumbnail_url,
    now(),
    now()
  )
  RETURNING id INTO v_post_id;

  RETURN jsonb_build_object(
    'success', true,
    'id', v_post_id,
    'author_id', p_author_id,
    'content', p_content,
    'content_type', p_content_type,
    'created_at', now(),
    'media_urls', v_media_jsonb,
    'thumbnail_url', p_thumbnail_url,
    'like_count', 0,
    'comment_count', 0
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END
$$;


ALTER FUNCTION public.fn_create_social_post(p_author_id uuid, p_content text, p_content_type text, p_media_urls text[], p_visibility text, p_achievement_data jsonb, p_thumbnail_url text) OWNER TO postgres;

--
-- Name: fn_create_story(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_story(p_user_id uuid, p_content text, p_media_url text DEFAULT NULL::text, p_media_type text DEFAULT NULL::text, p_background_color text DEFAULT NULL::text, p_link_url text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_story_id uuid;
  v_caller_role text;
  v_caller_uid uuid;
BEGIN
  v_caller_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '');
  v_caller_uid := auth.uid();

  IF v_caller_role = 'authenticated' THEN
    IF v_caller_uid IS NULL OR p_user_id <> v_caller_uid THEN
      RAISE WARNING 'fn_create_story: forbidden author spoof attempt by % targeting %', v_caller_uid, p_user_id;
      RETURN NULL;
    END IF;
  ELSIF v_caller_role = 'anon' OR v_caller_role = '' THEN
    RETURN NULL;
  END IF;
  -- service_role: bypass

  -- STREAM-POLISH-R4 STORY-CREATE-1: length cap. 500 chars is
  -- generous (Instagram caps at 250). Anything beyond is almost
  -- certainly a paste-bomb or DB-row-size attack.
  IF p_content IS NOT NULL AND LENGTH(p_content) > 500 THEN
    RAISE WARNING 'fn_create_story: content too long (% chars, max 500)', LENGTH(p_content);
    RETURN NULL;
  END IF;

  INSERT INTO social_stories (
    author_id, content, media_url, media_type, background_color, link_url,
    expires_at, created_at
  ) VALUES (
    p_user_id, p_content, p_media_url, p_media_type, p_background_color, p_link_url,
    now() + interval '24 hours', now()
  )
  RETURNING id INTO v_story_id;

  RETURN v_story_id;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_create_story failed for user %: % %', p_user_id, SQLERRM, SQLSTATE;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_create_story(p_user_id uuid, p_content text, p_media_url text, p_media_type text, p_background_color text, p_link_url text) OWNER TO postgres;

--
-- Name: fn_create_tournament(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_tournament(p_club_id uuid, p_config jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_res jsonb;
  v_pct smallint;
  v_id  uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','not_authenticated');
  END IF;
  IF NOT public.fn_can_create_games(p_club_id,v_uid) THEN
    RETURN jsonb_build_object('success',false,'error','not_authorised');
  END IF;

  v_res := public.fn_create_tournament_governed_legacy(p_club_id,p_config);

  /* What share of the field finishes in the money (Dan, 2026-09-02). The
     payout TABLE itself is derived at lock from this and the field that
     actually entered, so the places always match the entrants. */
  BEGIN
    v_pct := CASE WHEN (p_config->>'payoutPercent')::int IN (10,15,20)
                  THEN (p_config->>'payoutPercent')::smallint ELSE 10 END;
    v_id := COALESCE(NULLIF(v_res->>'tournamentId',''), NULLIF(v_res->>'id',''))::uuid;
    IF v_id IS NOT NULL AND v_pct IS DISTINCT FROM 10 THEN
      UPDATE public.tournaments SET payout_percent = v_pct WHERE id = v_id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- a bad or absent payoutPercent must never fail a tournament create
  END;

  RETURN v_res;
END $$;


ALTER FUNCTION public.fn_create_tournament(p_club_id uuid, p_config jsonb) OWNER TO postgres;

--
-- Name: fn_create_tournament_governed_legacy(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_tournament_governed_legacy(p_club_id uuid, p_config jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid          uuid := auth.uid();
  v_id           uuid;
  v_total        numeric;
  v_buy_in       numeric;
  v_fee          numeric;
  v_max_players  int;
  v_min_players  int;
  v_type         text;
  v_variant      text;
  v_start        timestamptz;
  v_payouts      jsonb;
  v_blinds       jsonb;
  v_pct_total    numeric;
  v_is_bounty    boolean;
  v_bounty       numeric;
  v_union_id     uuid;
  v_is_private   boolean;
  v_action_time    int;
  v_table_size     int;
  v_addon_break    int;
  v_early_chips    int;
  v_restart_every  int;
  v_sync_breaks    boolean;
  v_max_rebuys     int;
  v_max_reentries  int;
  v_is_multi_day   boolean;
  v_total_days     int;
  v_mb_min_mult    numeric;
  v_mb_max_mult    numeric;
  v_mb_min_money   numeric := 0;
  v_mb_max_money   numeric := 0;
  v_sat_target     uuid;
  v_sat_seats      int;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  v_is_private := COALESCE((p_config->>'isPrivate')::boolean, false);
  IF v_is_private THEN
    IF NOT (is_club_admin(p_club_id, v_uid) OR public.fn_can_create_games(p_club_id, v_uid)) THEN
      RETURN jsonb_build_object('success', false, 'error', 'not_authorised');
    END IF;
  ELSIF NOT public.fn_can_create_games(p_club_id, v_uid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorised');
  END IF;

  v_total := COALESCE((p_config->>'buyIn')::numeric, 0);
  IF v_total < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'buy_in_must_not_be_negative');
  END IF;
  IF v_total <> round(v_total) THEN
    RETURN jsonb_build_object('success', false, 'error', 'buy_in_must_be_whole');
  END IF;

  v_fee    := LEAST(v_total, GREATEST(0, trunc(v_total * (CASE WHEN COALESCE((p_config->>'maxPlayers')::int, 0) BETWEEN 1 AND 2 THEN 0.05 ELSE 0.1 END) * 100 + 0.000001) / 100));
  v_buy_in := v_total - v_fee;

  v_max_players := COALESCE((p_config->>'maxPlayers')::int, 0);
  IF v_max_players <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'max_players_must_be_positive');
  END IF;
  v_min_players := GREATEST(COALESCE((p_config->>'minPlayers')::int, 3), 2);
  IF v_min_players > v_max_players THEN
    v_min_players := v_max_players;
  END IF;

  v_type := COALESCE(p_config->>'type', 'mtt');
  v_variant := CASE v_type
                 WHEN 'sng' THEN 'sng'
                 WHEN 'spin' THEN 'spin'
                 WHEN 'bounty' THEN 'bounty'
                 WHEN 'progressive_bounty' THEN 'progressive_bounty'
                 WHEN 'mystery_bounty' THEN 'mystery_bounty'
                 WHEN 'satellite' THEN 'satellite'
                 ELSE 'freezeout'
               END;

  IF v_type = 'spin' THEN
    v_fee    := 0;
    v_buy_in := v_total;
  END IF;

  v_blinds  := COALESCE(p_config->'blindStructure', '[]'::jsonb);
  v_payouts := COALESCE(p_config->'payoutStructure', '[]'::jsonb);

  IF jsonb_array_length(v_blinds) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'blind_structure_required');
  END IF;
  IF jsonb_array_length(v_payouts) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'payout_structure_required');
  END IF;

  SELECT COALESCE(SUM((e->>'percentage')::numeric), 0) INTO v_pct_total
    FROM jsonb_array_elements(v_payouts) e;
  IF abs(v_pct_total - 100) > 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'payouts_must_total_100',
                              'detail', v_pct_total);
  END IF;

  IF jsonb_array_length(v_payouts) > v_max_players THEN
    RETURN jsonb_build_object('success', false, 'error', 'more_paid_places_than_players');
  END IF;

  v_start := COALESCE((p_config->>'startTime')::timestamptz, now() + interval '1 minute');

  v_is_bounty := v_type IN ('bounty', 'progressive_bounty', 'mystery_bounty');
  v_bounty := COALESCE((p_config->>'bountyAmount')::numeric, 0);
  IF v_is_bounty THEN
    IF v_bounty <= 0 THEN
      RETURN jsonb_build_object('success', false, 'error', 'bounty_amount_required');
    END IF;
    IF v_bounty <> round(v_bounty) THEN
      RETURN jsonb_build_object('success', false, 'error', 'bounty_must_be_whole');
    END IF;
    IF v_buy_in - v_bounty < 0 THEN
      RETURN jsonb_build_object('success', false, 'error', 'bounty_exceeds_buy_in');
    END IF;
  END IF;

  v_action_time := LEAST(60, GREATEST(5,  COALESCE((p_config->>'actionTimeSeconds')::int, 15)));
  v_table_size  := LEAST(10, GREATEST(2,  COALESCE((p_config->>'tableSize')::int, 9)));
  v_addon_break := LEAST(10, GREATEST(1,  COALESCE((p_config->>'addonBreakMinutes')::int, 1)));
  v_sync_breaks := COALESCE((p_config->>'synchronizedBreaks')::boolean, true);

  v_early_chips := COALESCE((p_config->>'earlyBirdChips')::int, 0);
  IF v_early_chips < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'early_bird_chips_must_not_be_negative');
  END IF;

  v_restart_every := NULLIF(p_config->>'restartEveryMinutes', '')::int;
  -- 10080 = one week (Dan 2026-09-03: MTTs repeat weekly, as a Create Event
  -- checkbox). Was 1440; a day was never long enough for a weekly event.
  IF v_restart_every IS NOT NULL AND (v_restart_every < 5 OR v_restart_every > 10080) THEN
    RETURN jsonb_build_object('success', false, 'error', 'restart_every_minutes_out_of_range');
  END IF;

  v_max_rebuys    := NULLIF(p_config->>'maxRebuys', '')::int;
  v_max_reentries := NULLIF(p_config->>'maxReentries', '')::int;

  v_is_multi_day := COALESCE((p_config->>'isMultiDay')::boolean, false);
  v_total_days   := NULLIF(p_config->>'totalDays', '')::int;
  IF v_is_multi_day THEN
    IF v_total_days IS NULL OR v_total_days < 2 OR v_total_days > 7 THEN
      RETURN jsonb_build_object('success', false, 'error', 'total_days_out_of_range');
    END IF;
  ELSE
    v_total_days := 1;
  END IF;

  v_mb_min_mult := NULLIF(p_config->>'mysteryBountyMin', '')::numeric;
  v_mb_max_mult := NULLIF(p_config->>'mysteryBountyMax', '')::numeric;
  IF (v_mb_min_mult IS NOT NULL OR v_mb_max_mult IS NOT NULL)
     AND v_type <> 'mystery_bounty' THEN
    RETURN jsonb_build_object('success', false, 'error', 'mystery_range_requires_mystery_bounty');
  END IF;
  IF v_type = 'mystery_bounty' THEN
    v_mb_min_mult := COALESCE(v_mb_min_mult, 0.5);
    v_mb_max_mult := COALESCE(v_mb_max_mult, 13);
    IF v_mb_min_mult <= 0 OR v_mb_max_mult < v_mb_min_mult THEN
      RETURN jsonb_build_object('success', false, 'error', 'mystery_bounty_range_invalid');
    END IF;
    v_mb_min_money := round(v_bounty * v_mb_min_mult, 2);
    v_mb_max_money := round(v_bounty * v_mb_max_mult, 2);
  END IF;

  v_sat_target := NULLIF(p_config->>'satelliteTargetId', '')::uuid;
  v_sat_seats  := NULLIF(p_config->>'satelliteSeats', '')::int;
  IF v_sat_seats IS NOT NULL THEN
    IF v_sat_seats < 1 THEN
      RETURN jsonb_build_object('success', false, 'error', 'satellite_seats_invalid');
    END IF;
    IF v_sat_target IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'satellite_seats_requires_target');
    END IF;
  END IF;

  SELECT u.id INTO v_union_id FROM unions u
   WHERE u.id = (SELECT COALESCE(c.union_id,
                        (SELECT uc.union_id FROM union_clubs uc WHERE uc.club_id = c.id LIMIT 1))
                   FROM clubs c WHERE c.id = p_club_id);

  INSERT INTO tournaments (
    club_id, name, game_type, variant, tournament_type,
    buy_in_amount, buy_in_fee, starting_chips,
    max_players, min_players, current_players, status,
    blind_structure, payout_structure, guaranteed_prize,
    late_reg_levels, late_reg_mins, rebuy_levels,
    start_time,
    is_rebuy, is_reentry, rebuy_cost, rebuy_chips,
    add_on_available, addon_cost, addon_chips, addon_levels,
    is_bounty, bounty_amount, is_pko, is_mystery_bounty,
    spin_type, satellite_target_id, is_xmtt, union_id, is_private,
    short_description, is_vip_only, ban_chat, all_in_or_fold, label_as_new,
    hide_club_name, action_time_seconds, table_size, accelerated_mtt,
    addon_break_minutes, big_blind_ante, authorized_to_register,
    early_bird_enabled, early_bird_chips, bubble_protection,
    final_table_deal_enabled, restart_every_minutes, synchronized_breaks,
    max_rebuys, max_reentries, is_multi_day, total_days,
    mystery_bounty_min, mystery_bounty_max, is_pinned, satellite_seats
  ) VALUES (
    p_club_id,
    COALESCE(NULLIF(trim(p_config->>'name'), ''), 'Tournament'),
    COALESCE(p_config->>'gameVariant', 'NLH'),
    v_variant,
    CASE WHEN v_type = 'sng' THEN 'SNG' WHEN v_type = 'spin' THEN 'SPIN' ELSE 'MTT' END,
    v_buy_in, v_fee,
    COALESCE((p_config->>'startingStack')::int, 10000),
    v_max_players, v_min_players, 0, 'REGISTERING',
    v_blinds::text, v_payouts::text,
    GREATEST(0, round(COALESCE((p_config->>'guaranteedPrize')::numeric, 0))),
    COALESCE((p_config->>'lateRegistrationLevels')::int, 0),
    COALESCE((p_config->>'lateRegistrationMinutes')::int, 0),
    COALESCE((p_config->>'lateRegistrationLevels')::int, 0),
    v_start,
    COALESCE((p_config->>'isRebuy')::boolean, false),
    COALESCE((p_config->>'isReentry')::boolean, false),
    GREATEST(0, round(COALESCE((p_config->>'rebuyCost')::numeric, 0))),
    COALESCE((p_config->>'rebuyChips')::int, 0),
    COALESCE((p_config->>'addOnAvailable')::boolean, false),
    GREATEST(0, round(COALESCE((p_config->>'addOnCost')::numeric, 0))),
    COALESCE((p_config->>'addOnChips')::int, 0),
    COALESCE((p_config->>'addOnLevels')::int, 1),
    v_is_bounty, v_bounty,
    v_type = 'progressive_bounty',
    v_type = 'mystery_bounty',
    CASE WHEN v_type = 'spin' THEN COALESCE(p_config->>'spinType', 'standard') ELSE NULL END,
    v_sat_target,
    COALESCE((p_config->>'isXmtt')::boolean, false),
    CASE WHEN v_is_private THEN NULL ELSE v_union_id END,
    v_is_private,
    NULLIF(trim(COALESCE(p_config->>'shortDescription', '')), ''),
    COALESCE((p_config->>'isVipOnly')::boolean, false),
    COALESCE((p_config->>'banChat')::boolean, false),
    COALESCE((p_config->>'allInOrFold')::boolean, false),
    COALESCE((p_config->>'labelAsNew')::boolean, false),
    COALESCE((p_config->>'hideClubName')::boolean, false),
    v_action_time, v_table_size,
    COALESCE((p_config->>'acceleratedMtt')::boolean, false),
    v_addon_break,
    COALESCE((p_config->>'bigBlindAnte')::boolean, false),
    COALESCE((p_config->>'authorizedToRegister')::boolean, false),
    COALESCE((p_config->>'earlyBirdEnabled')::boolean, false),
    v_early_chips,
    COALESCE((p_config->>'bubbleProtection')::boolean, false),
    COALESCE((p_config->>'finalTableDealEnabled')::boolean, false),
    v_restart_every, v_sync_breaks,
    v_max_rebuys, v_max_reentries,
    v_is_multi_day, v_total_days,
    v_mb_min_money, v_mb_max_money,
    COALESCE((p_config->>'isFeatured')::boolean, false),
    v_sat_seats
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('success', true, 'tournament_id', v_id,
                            'buy_in', v_total, 'buy_in_fee', v_fee,
                            'status', 'REGISTERING');
END;
$$;


