--
-- Name: FUNCTION fn_create_tournament_governed_legacy(p_club_id uuid, p_config jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_create_tournament_governed_legacy(p_club_id uuid, p_config jsonb) IS 'Dan 2026-08-20: p_config->>''buyIn'' is the whole-number TOTAL the player pays. The 10% fee is rounded whole and cut OUT of it; buy_in_amount is the remainder. A non-integer buyIn is refused with buy_in_must_be_whole rather than rounded. Mirrors splitBuyIn() in src/utils/buyIn.ts and server/src/config/buyIn.ts - change one, change all three. 2026-08-22: PokerBros parity keys added (shortDescription, isVipOnly, banChat, allInOrFold, labelAsNew, hideClubName, actionTimeSeconds, tableSize, acceleratedMtt, addonBreakMinutes, bigBlindAnte, authorizedToRegister, earlyBirdEnabled, earlyBirdChips, bubbleProtection, finalTableDealEnabled, restartEveryMinutes, synchronizedBreaks, maxRebuys, maxReentries, isMultiDay, totalDays, mysteryBountyMin/Max (multipliers, stored as money), isFeatured, satelliteSeats).';


--
-- Name: fn_credit_agent_commissions_batch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_credit_agent_commissions_batch(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '300s'
    AS $$
DECLARE
  it jsonb;
  v_ok integer := 0;
  v_failed integer := 0;
  v_first_error text := NULL;
BEGIN
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RETURN jsonb_build_object('ok', 0, 'failed', 0, 'error', 'p_items must be a jsonb array');
  END IF;

  FOR it IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    BEGIN
      PERFORM public.credit_agent_commission_from_rake(
        (it->>'user_id')::uuid,
        (it->>'club_id')::uuid,
        COALESCE((it->>'rake_credit')::numeric, 0),
        it->>'source_type',
        NULLIF(it->>'source_id', '')::uuid,
        it->>'notes'
      );
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      IF v_first_error IS NULL THEN v_first_error := SQLERRM; END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('ok', v_ok, 'failed', v_failed, 'first_error', v_first_error);
END $$;


ALTER FUNCTION public.fn_credit_agent_commissions_batch(p_items jsonb) OWNER TO postgres;

--
-- Name: fn_credit_and_log(uuid, numeric, text, text, text, uuid, text, uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_credit_and_log(p_user_id uuid, p_amount numeric, p_idempotency_key text, p_category text, p_description text, p_related_entity_id uuid DEFAULT NULL::uuid, p_wallet_type text DEFAULT 'PLAYER'::text, p_table_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_payout_position integer DEFAULT NULL::integer, p_payout_source text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_credited boolean;
  v_ledger_cat text;
  v_t record;
  v_field integer;
  v_shape_source text;
  v_shape_place integer;
  v_payout_source text;
  v_payout_place integer;
  v_payout_id uuid;
  v_existing_key record;
  v_key_existed boolean := false;
  v_evidence_count integer;
  v_prev_cp text;
  v_prev_cp_entity text;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'fn_credit_and_log requires a user id' USING ERRCODE = '22004';
  END IF;
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 THEN
    RAISE EXCEPTION 'fn_credit_and_log requires an idempotency key' USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NULL
     OR p_amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_amount <= 0
     OR p_amount IS DISTINCT FROM round(p_amount, 2) THEN
    RAISE EXCEPTION
      'fn_credit_and_log requires a finite positive whole-cent amount (got %)',
      p_amount USING ERRCODE = '22003';
  END IF;

  SELECT k.user_id, k.amount INTO v_existing_key
    FROM public.wallet_credit_idempotency k
   WHERE k.key = p_idempotency_key;
  v_key_existed := FOUND;
  IF v_key_existed
     AND (v_existing_key.user_id IS DISTINCT FROM p_user_id
       OR v_existing_key.amount IS NULL
       OR v_existing_key.amount::text IN ('NaN', 'Infinity', '-Infinity')
       OR v_existing_key.amount IS DISTINCT FROM p_amount) THEN
    RAISE EXCEPTION 'idempotency key % belongs to a different credit',
      p_idempotency_key USING ERRCODE = '23505';
  END IF;

  v_ledger_cat := CASE lower(COALESCE(p_category, ''))
                    WHEN 'prize' THEN 'tournament_prize'
                    WHEN 'buyin' THEN 'tournament_buyin'
                    WHEN '' THEN 'adjustment'
                    ELSE lower(p_category)
                  END;

  -- Resolve mandatory evidence before the wallet move. Explicit obligation
  -- metadata wins; legacy owner-only callers may still classify their key.
  IF lower(COALESCE(p_category, '')) = 'prize' THEN
    IF p_related_entity_id IS NULL THEN
      RAISE EXCEPTION 'a tournament prize requires a tournament id'
        USING ERRCODE = '23502';
    END IF;
    SELECT t.id, t.tournament_type, t.prize_pool, t.payout_structure
      INTO v_t FROM public.tournaments t
     WHERE t.id = p_related_entity_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'tournament % does not exist for prize evidence',
        p_related_entity_id USING ERRCODE = '23503';
    END IF;
    SELECT s.source, s.place INTO v_shape_source, v_shape_place
      FROM public.fn_tournament_payout_shape(p_idempotency_key) s;
    v_payout_source := COALESCE(NULLIF(btrim(p_payout_source), ''),
                                v_shape_source);
    -- A payment whose kind is unknown is not allowed to move. This check is
    -- deliberately before fn_credit_player_wallet_once: the payout row and
    -- wallet credit are one transaction, but rejecting the unnamed path here
    -- also prevents an older catch-and-alert writer from ever treating a
    -- missing classification as non-fatal.
    IF v_payout_source IS NULL THEN
      RAISE EXCEPTION
        'tournament prize % has no recognized payout source',
        p_idempotency_key USING ERRCODE = '22023';
    END IF;
    IF v_payout_source NOT IN (
      'structure','reconcile','hu_shortfall','bounty','bounty_residual',
      'own_bounty','late_reg_adjustment','clawback','final_table_deal',
      'mystery_bounty','mystery_bounty_residual','spin_backpay',
      'overlay_backpay','bubble_protection','satellite_remainder',
      'satellite_seat','satellite_ticket','finish_position_correction'
    ) THEN
      RAISE EXCEPTION
        'tournament prize % supplied unknown payout source %',
        p_idempotency_key, v_payout_source USING ERRCODE = '22023';
    END IF;
    v_payout_place := COALESCE(p_payout_position, v_shape_place);
    IF v_payout_place IS NOT NULL AND v_payout_place <= 0 THEN
      RAISE EXCEPTION 'prize evidence has invalid finish position %', v_payout_place
        USING ERRCODE = '22023';
    END IF;
    IF v_payout_source = 'structure' AND v_payout_place IS NULL THEN
      RAISE EXCEPTION 'a structure prize requires a finish position'
        USING ERRCODE = '23502';
    END IF;
    SELECT count(*) INTO v_field FROM public.tournament_players
     WHERE tournament_id = v_t.id;
  END IF;

  PERFORM set_config('app.ledger_category', v_ledger_cat, true);
  IF p_related_entity_id IS NOT NULL THEN
    PERFORM set_config('app.ledger_tournament', p_related_entity_id::text, true);
  END IF;
  v_prev_cp := current_setting('app.ledger_counterparty', true);
  v_prev_cp_entity := current_setting('app.ledger_counterparty_entity', true);
  IF p_related_entity_id IS NOT NULL
     AND v_ledger_cat IN ('tournament_prize','bounty','refund','tournament_refund') THEN
    PERFORM set_config('app.ledger_counterparty', 'prize_liability', true);
    PERFORM set_config('app.ledger_counterparty_entity', p_related_entity_id::text, true);
  END IF;

  v_credited := public.fn_credit_player_wallet_once(
    p_user_id, p_amount, p_idempotency_key);

  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_tournament', '', true);
  PERFORM set_config('app.ledger_counterparty', COALESCE(v_prev_cp, ''), true);
  PERFORM set_config('app.ledger_counterparty_entity', COALESCE(v_prev_cp_entity, ''), true);

  IF NOT v_credited THEN
    -- The first snapshot is not authoritative here. Two same-key transactions
    -- can both see no row; the loser then waits on the unique index inside
    -- fn_credit_player_wallet_once and returns FALSE after the winner commits.
    -- Re-read in a new statement snapshot, after that wait, and accept only the
    -- exact committed key. A genuinely orphaned or mismatched claim still
    -- aborts the outer transaction.
    SELECT k.user_id, k.amount INTO v_existing_key
      FROM public.wallet_credit_idempotency k
     WHERE k.key = p_idempotency_key
     FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION
        'wallet credit % claimed its key but did not credit a wallet',
        p_idempotency_key USING ERRCODE = 'P0404';
    END IF;
    IF v_existing_key.user_id IS DISTINCT FROM p_user_id
       OR v_existing_key.amount IS NULL
       OR v_existing_key.amount::text IN ('NaN', 'Infinity', '-Infinity')
       OR v_existing_key.amount IS DISTINCT FROM p_amount THEN
      RAISE EXCEPTION 'idempotency key % belongs to a different credit',
        p_idempotency_key USING ERRCODE = '23505';
    END IF;
    IF lower(COALESCE(p_category, '')) = 'prize' THEN
      SELECT count(*) INTO v_evidence_count
        FROM public.tournament_payouts tp
       WHERE tp.idempotency_key = p_idempotency_key
         AND tp.tournament_id = p_related_entity_id
         AND tp.user_id = p_user_id
         AND tp.amount = p_amount
         AND tp."position" IS NOT DISTINCT FROM v_payout_place
         AND tp.source IS NOT DISTINCT FROM v_payout_source;
      IF v_evidence_count <> 1 THEN
        RAISE EXCEPTION
          'prize replay % has % exact payout rows, expected one',
          p_idempotency_key, v_evidence_count USING ERRCODE = 'P0404';
      END IF;
    END IF;
    RETURN false;
  END IF;

  PERFORM public.log_wallet_transaction(
    p_user_id, p_wallet_type, p_amount, 'credit', p_category, p_description,
    p_table_id, p_hand_id, p_related_entity_id);

  IF lower(COALESCE(p_category, '')) = 'prize' THEN
    INSERT INTO public.tournament_payouts
      (tournament_id, user_id, "position", amount, source, idempotency_key,
       paid_at, tournament_type, field_size, prize_pool, payout_structure,
       recorded_by)
    VALUES
      (v_t.id, p_user_id, v_payout_place, p_amount, v_payout_source,
       p_idempotency_key, now(), v_t.tournament_type, v_field, v_t.prize_pool,
       CASE WHEN v_t.payout_structure IS NULL THEN NULL
            ELSE jsonb_build_object('payout_structure', v_t.payout_structure) END,
       'credit_and_log')
    RETURNING id INTO v_payout_id;

    IF v_payout_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.tournament_payouts tp
       WHERE tp.id = v_payout_id
         AND tp.idempotency_key = p_idempotency_key
         AND tp.tournament_id = p_related_entity_id
         AND tp.user_id = p_user_id
         AND tp.amount = p_amount
         AND tp."position" IS NOT DISTINCT FROM v_payout_place
         AND tp.source IS NOT DISTINCT FROM v_payout_source
    ) THEN
      RAISE EXCEPTION 'prize % could not verify its payout evidence',
        p_idempotency_key USING ERRCODE = 'P0404';
    END IF;
  END IF;
  RETURN true;
END;
$$;


ALTER FUNCTION public.fn_credit_and_log(p_user_id uuid, p_amount numeric, p_idempotency_key text, p_category text, p_description text, p_related_entity_id uuid, p_wallet_type text, p_table_id uuid, p_hand_id uuid, p_payout_position integer, p_payout_source text) OWNER TO postgres;

--
-- Name: fn_credit_chips(uuid, uuid, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_credit_chips(p_club_id uuid, p_user_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_before numeric;
  v_after numeric;
  v_amt numeric := round(p_amount, 2);
BEGIN
  IF v_amt IS NULL OR v_amt <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  PERFORM set_config('app.ledger_category', 'player_funding', true);

  SELECT COALESCE(chip_balance, 0) INTO v_before
  FROM club_members
  WHERE club_id = p_club_id AND user_id = p_user_id FOR UPDATE;

  IF v_before IS NULL THEN
    INSERT INTO club_members (club_id, user_id, role, chip_balance, joined_at, created_at, updated_at, status, is_active)
    VALUES (p_club_id, p_user_id, 'player', v_amt, NOW(), NOW(), NOW(), 'active', true)
    ON CONFLICT (club_id, user_id) DO UPDATE
      SET chip_balance = COALESCE(club_members.chip_balance, 0) + EXCLUDED.chip_balance,
          updated_at = NOW();
    v_before := 0;
    v_after := v_amt;
  ELSE
    /* ZERO-DRIFT (2026-08-31): was + p_amount::integer - the balance moved by
       a truncated amount while the journal recorded the full numeric amount,
       destroying fractions on every fractional call. */
    UPDATE club_members
    SET chip_balance = COALESCE(chip_balance, 0) + v_amt,
        updated_at = NOW()
    WHERE club_id = p_club_id AND user_id = p_user_id;
    v_after := v_before + v_amt;
  END IF;

  INSERT INTO chip_transactions (
    id, club_id, from_user_id, to_user_id, amount,
    transaction_type, notes, metadata, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), p_club_id, NULL, p_user_id, v_amt,
    COALESCE(p_metadata->>'transaction_type', 'chip_credit'),
    COALESCE(p_reason, 'Chip credit'), p_metadata, v_after, NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'amount', v_amt,
    'balance_before', v_before,
    'balance_after', v_after
  );
END;
$$;


ALTER FUNCTION public.fn_credit_chips(p_club_id uuid, p_user_id uuid, p_amount numeric, p_reason text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_credit_chips(p_club_id uuid, p_user_id uuid, p_amount numeric, p_reason text, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_credit_chips(p_club_id uuid, p_user_id uuid, p_amount numeric, p_reason text, p_metadata jsonb) IS 'BUG 025: real impl. Atomic credit to club_memberships.chip_balance (auto-creates membership) + chip_transactions audit.';


--
-- Name: fn_credit_player_wallet_once(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_credit_player_wallet_once(p_user_id uuid, p_amount numeric, p_idempotency_key text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_inserted integer; v_tourn uuid; v_club uuid; v_balance numeric;
  v_is_tournament boolean := false; v_has_any_club boolean;
  v_fallback uuid;
BEGIN
    IF p_idempotency_key IS NOT NULL THEN
        INSERT INTO wallet_credit_idempotency (key, user_id, amount)
        VALUES (p_idempotency_key, p_user_id, p_amount)
        ON CONFLICT (key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT;
        -- FALSE, not void: the caller needs to know it must NOT write a
        -- ledger row for a credit somebody else already made.
        IF v_inserted = 0 THEN RETURN false; END IF;
    END IF;

    IF p_idempotency_key IS NOT NULL AND p_idempotency_key LIKE 'tourney:%' THEN
      v_is_tournament := true;
      BEGIN
        v_tourn := (split_part(p_idempotency_key, ':', 2))::uuid;
      EXCEPTION WHEN OTHERS THEN v_tourn := NULL;
      END;
      IF v_tourn IS NOT NULL THEN
        SELECT tp.club_id INTO v_club FROM tournament_players tp
         WHERE tp.tournament_id = v_tourn AND tp.user_id = p_user_id LIMIT 1;
        IF v_club IS NULL THEN
          SELECT t.club_id INTO v_club FROM tournaments t WHERE t.id = v_tourn;
          v_club := COALESCE(public.fn_player_home_club(p_user_id, NULL), v_club);
        END IF;
      END IF;
    END IF;

    IF v_club IS NULL THEN
      v_club := public.fn_player_home_club(p_user_id, NULL);
    END IF;

    IF v_club IS NOT NULL THEN
      PERFORM public.fn_ensure_club_wallet(p_user_id, v_club);
      UPDATE club_members
         SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = NOW()
       WHERE user_id = p_user_id AND club_id = v_club
       RETURNING chip_balance INTO v_balance;
      IF v_balance IS NOT NULL THEN RETURN true; END IF;
    END IF;

    /* ZERO-DRIFT (2026-08-31): cross-club tournament entry - the stamped club
       holds no wallet for this player. Follow the money home instead of
       refusing a prize the pool already owes. */
    IF v_is_tournament AND v_tourn IS NOT NULL THEN
      SELECT ct.club_id INTO v_fallback
        FROM chip_transactions ct
        JOIN tournaments t ON t.id = v_tourn
       WHERE ct.from_user_id = p_user_id
         AND ct.transaction_type = 'tournament_buyin'
         AND ct.notes = 'Tournament buy-in: ' || t.name
         AND ct.created_at > COALESCE(t.started_at, t.created_at, now()) - interval '7 days'
         AND EXISTS (SELECT 1 FROM club_members m
                      WHERE m.user_id = p_user_id AND m.club_id = ct.club_id)
       ORDER BY ct.created_at DESC LIMIT 1;
      IF v_fallback IS NULL THEN
        v_fallback := public.fn_player_home_club(p_user_id, NULL);
      END IF;
      IF v_fallback IS NULL THEN
        SELECT m.club_id INTO v_fallback
          FROM club_members m
         WHERE m.user_id = p_user_id
           AND COALESCE(m.status, 'active') IN ('active','approved')
         ORDER BY COALESCE(m.chip_balance, 0) DESC, m.club_id LIMIT 1;
      END IF;
      IF v_fallback IS NOT NULL AND v_fallback IS DISTINCT FROM v_club THEN
        PERFORM public.fn_ensure_club_wallet(p_user_id, v_fallback);
        UPDATE club_members
           SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = NOW()
         WHERE user_id = p_user_id AND club_id = v_fallback
         RETURNING chip_balance INTO v_balance;
        IF v_balance IS NOT NULL THEN RETURN true; END IF;
      END IF;
    END IF;

    SELECT EXISTS (SELECT 1 FROM club_members m WHERE m.user_id = p_user_id)
      INTO v_has_any_club;

    IF v_is_tournament OR v_has_any_club THEN
      INSERT INTO financial_alerts (severity, source, message, context)
      VALUES ('critical','credit_player_wallet',
              'Club Arena credit could not resolve a club wallet - payment refused rather than pooled',
              jsonb_build_object('user_id',p_user_id,'amount',p_amount,
                                 'idempotency_key',p_idempotency_key,'tournament_id',v_tourn));
      RAISE EXCEPTION 'No club wallet resolves for Club Arena credit to player %', p_user_id;
    END IF;

    UPDATE wallets SET balance = balance + p_amount, updated_at = NOW()
      WHERE user_id = p_user_id AND wallet_type = 'PLAYER';
    IF NOT FOUND THEN
        INSERT INTO wallets (user_id, wallet_type, balance, locked_balance, created_at, updated_at)
        VALUES (p_user_id, 'PLAYER', p_amount, 0, NOW(), NOW());
    END IF;

    RETURN true;
END;
$$;


ALTER FUNCTION public.fn_credit_player_wallet_once(p_user_id uuid, p_amount numeric, p_idempotency_key text) OWNER TO postgres;

--
-- Name: fn_credit_treasury(uuid, numeric, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_credit_treasury(p_club_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_op_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_prior jsonb;
  v_res jsonb;
BEGIN
  IF p_op_id IS NULL THEN
    RETURN public.fn_credit_treasury_zd4core(p_club_id, p_amount, p_reason, p_metadata);
  END IF;

  SELECT result INTO v_prior
    FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true, 'op_id', p_op_id);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  END IF;

  INSERT INTO public.ca_op_claims (op_id, fn_name, claimed_by)
  VALUES (p_op_id, 'fn_credit_treasury', auth.uid());

  v_res := public.fn_credit_treasury_zd4core(p_club_id, p_amount, p_reason, p_metadata);

  IF COALESCE(v_res->>'success', '') = 'true' THEN
    UPDATE public.ca_op_claims
       SET result = v_res, finalized_at = now()
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  ELSE
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  END IF;

  RETURN v_res;
END;
$$;


ALTER FUNCTION public.fn_credit_treasury(p_club_id uuid, p_amount numeric, p_reason text, p_metadata jsonb, p_op_id text) OWNER TO postgres;

--
-- Name: fn_credit_treasury_zd4core(uuid, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_credit_treasury_zd4core(p_club_id uuid, p_amount numeric, p_reason text, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_before numeric;
  v_after numeric;
BEGIN
  IF p_club_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid parameters');
  END IF;

  SELECT COALESCE(chip_treasury, 0) INTO v_before
  FROM clubs WHERE id = p_club_id FOR UPDATE;

  IF v_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'club not found');
  END IF;

  UPDATE clubs
  SET chip_treasury = COALESCE(chip_treasury, 0) + p_amount,
      updated_at = NOW()
  WHERE id = p_club_id;
  v_after := v_before + p_amount;

  INSERT INTO chip_transactions (
    id, club_id, amount, transaction_type, notes, metadata, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), p_club_id, p_amount,
    'treasury_credit', COALESCE(p_reason, 'Treasury credit'), p_metadata, v_after, NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'amount', p_amount,
    'balance_before', v_before,
    'balance_after', v_after
  );
END;
$$;


ALTER FUNCTION public.fn_credit_treasury_zd4core(p_club_id uuid, p_amount numeric, p_reason text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: fn_cron_field(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cron_field(p_field text, p_max integer) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_part text;
  v_out  int[] := '{}';
  v_step int;
BEGIN
  -- Returns NULL for any form this does not understand, so callers SKIP rather
  -- than guess. Guessing here manufactures false breaches.
  IF p_field IS NULL OR p_field = '' THEN RETURN NULL; END IF;
  IF p_field = '*' THEN RETURN ARRAY(SELECT generate_series(0, p_max)); END IF;

  FOREACH v_part IN ARRAY string_to_array(p_field, ',') LOOP
    IF v_part ~ '^\*/[0-9]+$' THEN
      v_step := substring(v_part from 3)::int;
      IF v_step <= 0 THEN RETURN NULL; END IF;
      v_out := v_out || ARRAY(SELECT g FROM generate_series(0, p_max) g WHERE g % v_step = 0);
    ELSIF v_part ~ '^[0-9]+$' THEN
      IF v_part::int > p_max THEN RETURN NULL; END IF;
      v_out := v_out || ARRAY[v_part::int];
    ELSE
      RETURN NULL;  -- ranges, step-on-range, names
    END IF;
  END LOOP;

  RETURN v_out;
END
$_$;


ALTER FUNCTION public.fn_cron_field(p_field text, p_max integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_cron_field(p_field text, p_max integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cron_field(p_field text, p_max integer) IS 'Expands one cron field (minute 0-59, hour 0-23) to the values it fires on. Returns NULL for forms it does not understand so callers skip rather than guess. Used by fn_db_saturation_selftest CHECK 7.';


--
-- Name: fn_cron_fleet_health(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cron_fleet_health(p_window_minutes integer DEFAULT 60) RETURNS TABLE(pg_cron_jobs bigint, pg_cron_active bigint, pg_cron_runs bigint, pg_cron_failures bigint, openclaw_jobs bigint, openclaw_stale bigint, openclaw_worst_silence_minutes numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'cron', 'pg_temp'
    AS $$
  SELECT
    (SELECT count(*) FROM cron.job),
    (SELECT count(*) FROM cron.job WHERE active),
    (SELECT count(*) FROM cron.job_run_details
      WHERE start_time > now() - make_interval(mins => greatest(p_window_minutes, 1))),
    (SELECT count(*) FROM cron.job_run_details
      WHERE start_time > now() - make_interval(mins => greatest(p_window_minutes, 1))
        AND status <> 'succeeded'),
    (SELECT count(*) FROM public.v_openclaw_job_staleness),
    (SELECT count(*) FROM public.v_openclaw_job_staleness WHERE is_stale),
    (SELECT round(max(silent_minutes), 1) FROM public.v_openclaw_job_staleness)
$$;


ALTER FUNCTION public.fn_cron_fleet_health(p_window_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_cron_fleet_health(p_window_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cron_fleet_health(p_window_minutes integer) IS 'pg_cron and Open Claw fleet health for the engine Prometheus gauges. Measures FAILURES and SILENCE, both unambiguous. Deliberately does not report "never run": cron.job records no creation time, so a NULL last_run cannot be told apart from a job not yet due - which is why fn_uncollected_entry_check could sit in financial_alerts saying its own silence means nothing. On 2026-09-04 four Open Claw jobs were stale, the worst silent for 18.3 days, and v_openclaw_job_staleness had been computing that with nothing reading it.';


--
-- Name: fn_cron_fleet_silence(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cron_fleet_silence(p_threshold_minutes integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_newest    timestamptz;
  v_silence   numeric;
  v_last_hour int;
  v_stale     jsonb;
BEGIN
  SELECT max(started_at) INTO v_newest FROM public.cron_execution_log;

  IF v_newest IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'cron_execution_log is empty',
      'silence_minutes', NULL,
      'threshold_minutes', p_threshold_minutes
    );
  END IF;

  v_silence := round(EXTRACT(epoch FROM (now() - v_newest)) / 60.0, 1);

  SELECT count(*) INTO v_last_hour
    FROM public.cron_execution_log
   WHERE started_at > now() - interval '1 hour';

  -- Jobs late BY THEIR OWN STANDARD. median gap from 14 days of history, so a
  -- weekly job is measured against a week and a per-minute job against a
  -- minute. Late = quiet for > 3x its own median AND at least the fleet
  -- threshold, so a fast job cannot alarm on one skipped tick.
  WITH gaps AS (
    SELECT job_name,
           started_at - lag(started_at) OVER (PARTITION BY job_name ORDER BY started_at) AS gap
      FROM public.cron_execution_log
     WHERE started_at > now() - interval '14 days'
  ),
  cadence AS (
    SELECT job_name,
           count(*) FILTER (WHERE gap IS NOT NULL) AS observations,
           EXTRACT(epoch FROM percentile_cont(0.5) WITHIN GROUP (ORDER BY gap))/60.0 AS median_min
      FROM gaps
     GROUP BY job_name
    HAVING count(*) FILTER (WHERE gap IS NOT NULL) >= 3
  ),
  last_seen AS (
    SELECT job_name, max(started_at) AS last_at
      FROM public.cron_execution_log
     WHERE started_at > now() - interval '14 days'
     GROUP BY job_name
  )
  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'job', c.job_name,
             'quiet_minutes', round(EXTRACT(epoch FROM (now() - l.last_at))/60.0, 1),
             'normal_gap_minutes', round(c.median_min::numeric, 1)
           ) ORDER BY (EXTRACT(epoch FROM (now() - l.last_at))/60.0) / NULLIF(c.median_min, 0) DESC
         ), '[]'::jsonb)
    INTO v_stale
    FROM cadence c
    JOIN last_seen l USING (job_name)
   WHERE c.median_min > 0
     AND EXTRACT(epoch FROM (now() - l.last_at))/60.0 > GREATEST(c.median_min * 3, p_threshold_minutes);

  RETURN jsonb_build_object(
    'ok', v_silence <= p_threshold_minutes,
    'silence_minutes', v_silence,
    'threshold_minutes', p_threshold_minutes,
    'newest_run_at', v_newest,
    'runs_last_hour', v_last_hour,
    'late_jobs', v_stale
  );
END
$$;


ALTER FUNCTION public.fn_cron_fleet_silence(p_threshold_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_cron_fleet_silence(p_threshold_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cron_fleet_silence(p_threshold_minutes integer) IS 'Fleet verdict: how long since ANY Open Claw job recorded a run (silence is the signal - a 401 never reaches the logging layer, so a dead fleet shows as an EMPTY log, not as failures). late_jobs judges each job against its own median gap over 14 days, so weekly jobs and retired ones stay out of the report. Threshold 25m is >2x the worst gap in a normal week (11m). Called by the GitHub-side watchdog, never by an Open Claw cron.';


--
-- Name: fn_daily_missions_claimed_milestone(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_daily_missions_claimed_milestone() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.claimed AND NOT OLD.claimed AND NEW.tier_snapshot = 'daily' THEN
    PERFORM public.fn_award_daily_mission_milestones(NEW.user_id);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_daily_missions_claimed_milestone() OWNER TO postgres;

--
-- Name: fn_daily_missions_friend_accepted(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_daily_missions_friend_accepted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status = 'accepted'
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'accepted') THEN
    IF NEW.user_id = NEW.friend_id THEN
      PERFORM public.fn_lock_daily_mission_user(NEW.user_id);
    ELSIF NEW.user_id < NEW.friend_id THEN
      PERFORM public.fn_lock_daily_mission_user(NEW.user_id);
      PERFORM public.fn_lock_daily_mission_user(NEW.friend_id);
    ELSE
      PERFORM public.fn_lock_daily_mission_user(NEW.friend_id);
      PERFORM public.fn_lock_daily_mission_user(NEW.user_id);
    END IF;

    BEGIN
      PERFORM public.enqueue_daily_challenge_event(
        NEW.user_id,
        'friendship:' || NEW.id::text,
        '{"friends_added":1}'::jsonb,
        '{}'::jsonb,
        now()
      );
      PERFORM public.enqueue_daily_challenge_event(
        NEW.friend_id,
        'friendship:' || NEW.id::text,
        '{"friends_added":1}'::jsonb,
        '{}'::jsonb,
        now()
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Daily Missions friendship event % could not be queued: %',
        NEW.id,
        SQLERRM;
    END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_daily_missions_friend_accepted() OWNER TO postgres;

--
-- Name: fn_daily_missions_tournament_registered(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_daily_missions_tournament_registered() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status NOT IN ('playing', 'eliminated', 'finished', 'winner')
     OR (TG_OP = 'UPDATE' AND OLD.status IN ('playing', 'eliminated', 'finished', 'winner')) THEN
    RETURN NEW;
  END IF;
  BEGIN
    PERFORM public.enqueue_daily_challenge_event(
      NEW.user_id,
      'tournament:' || NEW.tournament_id::text,
      '{"tournaments_played":1}'::jsonb,
      '{}'::jsonb,
      now()
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Daily Missions tournament event % could not be queued: %',
      NEW.tournament_id, SQLERRM;
  END;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_daily_missions_tournament_registered() OWNER TO postgres;

--
-- Name: fn_daily_missions_tournament_registered_inserted(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_daily_missions_tournament_registered_inserted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_event record;
  v_occurred_at timestamptz := transaction_timestamp();
  v_user_id uuid;
BEGIN
  FOR v_user_id IN
    SELECT DISTINCT inserted.user_id
    FROM inserted_rows inserted
    WHERE inserted.status::text IN ('playing', 'eliminated', 'finished', 'winner')
    ORDER BY inserted.user_id
  LOOP
    PERFORM pg_advisory_xact_lock(
      hashtextextended('daily-missions-user:' || v_user_id::text, 0)
    );
  END LOOP;

  FOR v_event IN
    SELECT inserted.id, inserted.user_id, inserted.tournament_id
    FROM inserted_rows inserted
    WHERE inserted.status::text IN ('playing', 'eliminated', 'finished', 'winner')
    ORDER BY inserted.user_id, inserted.tournament_id, inserted.id
  LOOP
    BEGIN
      PERFORM public.enqueue_daily_challenge_event(
        v_event.user_id,
        'tournament:' || v_event.tournament_id::text,
        '{"tournaments_played":1}'::jsonb,
        '{}'::jsonb,
        v_occurred_at
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Daily Missions tournament event % for player % could not be queued: %',
        v_event.tournament_id,
        v_event.user_id,
        SQLERRM;
    END;
  END LOOP;

  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_daily_missions_tournament_registered_inserted() OWNER TO postgres;

--
-- Name: fn_daily_missions_tournament_registered_updated(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_daily_missions_tournament_registered_updated() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_event record;
  v_occurred_at timestamptz := transaction_timestamp();
  v_user_id uuid;
BEGIN
  FOR v_user_id IN
    SELECT DISTINCT updated.user_id
    FROM updated_rows updated
    JOIN previous_rows previous ON previous.id = updated.id
    WHERE updated.status::text IN ('playing', 'eliminated', 'finished', 'winner')
      AND (
        previous.status IS NULL
        OR previous.status::text NOT IN ('playing', 'eliminated', 'finished', 'winner')
      )
    ORDER BY updated.user_id
  LOOP
    PERFORM pg_advisory_xact_lock(
      hashtextextended('daily-missions-user:' || v_user_id::text, 0)
    );
  END LOOP;

  FOR v_event IN
    SELECT updated.id, updated.user_id, updated.tournament_id
    FROM updated_rows updated
    JOIN previous_rows previous ON previous.id = updated.id
    WHERE updated.status::text IN ('playing', 'eliminated', 'finished', 'winner')
      AND (
        previous.status IS NULL
        OR previous.status::text NOT IN ('playing', 'eliminated', 'finished', 'winner')
      )
    ORDER BY updated.user_id, updated.tournament_id, updated.id
  LOOP
    BEGIN
      PERFORM public.enqueue_daily_challenge_event(
        v_event.user_id,
        'tournament:' || v_event.tournament_id::text,
        '{"tournaments_played":1}'::jsonb,
        '{}'::jsonb,
        v_occurred_at
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Daily Missions tournament event % for player % could not be queued: %',
        v_event.tournament_id,
        v_event.user_id,
        SQLERRM;
    END;
  END LOOP;

  RETURN NULL;
END;
$$;


