--
-- Name: FUNCTION fn_db_saturation_selftest(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_db_saturation_selftest() IS 'Detects the conditions that caused the 2026-08-22 "no tables load" outage: unvacuumed/unanalyzed large tables, autovacuum disabled, and cleanup cron jobs without an overlap guard or running long. Run by pg_cron job db-saturation-selftest every 30 minutes.';


--
-- Name: fn_deal_fairness(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_deal_fairness(p_since interval DEFAULT '24:00:00'::interval) RETURNS TABLE(variant text, cards_in_deck integer, flop_slots bigint, degrees_freedom integer, chi_square numeric, verdict text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH h AS (
    SELECT coalesce(hh.game_variant, '(unknown)') AS variant,
           hh.community_cards[1:3] AS flop
    FROM public.hand_history hh
    WHERE hh.community_cards IS NOT NULL
      AND array_length(hh.community_cards, 1) >= 3
      AND hh.created_at > now() - p_since
  ),
  c     AS (SELECT variant, unnest(flop) AS card FROM h),
  tally AS (SELECT variant, card, count(*)::numeric AS n FROM c GROUP BY 1, 2),
  tot   AS (SELECT variant, sum(n) AS total, count(*) AS k FROM tally GROUP BY 1)
  SELECT tot.variant,
         tot.k::integer,
         tot.total::bigint,
         (tot.k - 1)::integer,
         round(sum(power(t.n - tot.total / tot.k, 2) / (tot.total / tot.k))::numeric, 1),
         /* A fair deal puts chi-square near its degrees of freedom. Twice df is
            a deliberately loose gate: it should never fire on noise, and this
            is a claim about integrity, so a false accusation costs more than a
            slow detection. */
         CASE
           WHEN tot.total < 2000 THEN 'too few hands to judge'
           WHEN sum(power(t.n - tot.total / tot.k, 2) / (tot.total / tot.k)) > (tot.k - 1) * 2.0
             THEN 'INVESTIGATE'
           ELSE 'consistent with a fair deal'
         END
  FROM tally t
  JOIN tot ON tot.variant = t.variant
  GROUP BY tot.variant, tot.k, tot.total
  ORDER BY tot.total DESC;
$$;


ALTER FUNCTION public.fn_deal_fairness(p_since interval) OWNER TO postgres;

--
-- Name: FUNCTION fn_deal_fairness(p_since interval); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_deal_fairness(p_since interval) IS 'Chi-square test that every card is dealt equally often, per game variant. Uses the FLOP ONLY and segments by game_variant, both deliberately: filtering to completed boards selects against aces (ace-high flops end hands early) and produced a false chi-square of 169.7 for nlh, and mixing 36-card short_deck with 52-card games manufactures a huge deviation. Added 2026-08-27; the deal measured fair across all 7 variants and 248,412 flop cards.';


--
-- Name: fn_debit_chips(uuid, uuid, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_debit_chips(p_club_id uuid, p_user_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_before numeric;
  v_after  numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  SELECT COALESCE(chip_balance, 0) INTO v_before
  FROM club_members
  WHERE club_id = p_club_id AND user_id = p_user_id FOR UPDATE;

  IF v_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not a member of this club');
  END IF;

  IF v_before < p_amount THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'insufficient chips',
      'balance', v_before, 'requested', p_amount
    );
  END IF;

  -- THE FIX: numeric, not ::integer. The column is numeric(_,2) and every
  -- other line in this function already treats p_amount as numeric.
  UPDATE club_members
  SET chip_balance = chip_balance - p_amount,
      updated_at = NOW()
  WHERE club_id = p_club_id AND user_id = p_user_id;
  v_after := v_before - p_amount;

  INSERT INTO chip_transactions (
    id, club_id, from_user_id, to_user_id, amount,
    transaction_type, notes, metadata, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), p_club_id, p_user_id, NULL, p_amount,
    COALESCE(p_metadata->>'transaction_type', 'chip_debit'),
    COALESCE(p_reason, 'Chip debit'), p_metadata, v_after, NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'amount', p_amount,
    'balance_before', v_before,
    'balance_after', v_after
  );
END;
$$;


