--
-- Name: fn_deep_stack_society_cannot_be_deleted_by_accident(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_deep_stack_society_cannot_be_deleted_by_accident() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_allowed boolean := COALESCE(current_setting('app.deep_stack_teardown', true), '') = 'on';
  v_query   text;
BEGIN
  SELECT a.query INTO v_query
    FROM pg_stat_activity a WHERE a.pid = pg_backend_pid();

  INSERT INTO public.deep_stack_delete_attempts
    (source_table, allowed, db_user, db_role, application, client_addr, backend_pid, running_query, old_row)
  VALUES
    (TG_TABLE_NAME, v_allowed, session_user, current_user,
     current_setting('application_name', true), host(COALESCE(inet_client_addr(), '0.0.0.0'::inet)),
     pg_backend_pid(), left(COALESCE(v_query, ''), 4000), to_jsonb(OLD));

  IF NOT v_allowed THEN
    RAISE EXCEPTION
      'DEEP_STACK_PROTECTED: this row belongs to Deep Stack Society (club 11192) and is not deletable'
      USING ERRCODE = '42501',
            HINT = 'The whole club was deleted once with no audit trail. Set app.deep_stack_teardown = ''on'' for your transaction if you really mean it.';
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION public.fn_deep_stack_society_cannot_be_deleted_by_accident() OWNER TO postgres;

--
-- Name: fn_definer_exposure_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_definer_exposure_audit() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    -- 1. Reachable from a browser, writes, and cannot know who is calling.
    'unauthenticated_writers', COALESCE((
      SELECT jsonb_agg(e ORDER BY e->>'function')
        FROM (
          SELECT jsonb_build_object(
                   'function', p.proname,
                   'args', pg_get_function_identity_arguments(p.oid),
                   'anon', has_function_privilege('anon', p.oid, 'EXECUTE'),
                   'authenticated', has_function_privilege('authenticated', p.oid, 'EXECUTE')
                 ) AS e
            FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
           WHERE n.nspname = 'public'
             AND p.prosecdef
             AND p.prorettype <> 'pg_catalog.trigger'::regtype
             AND (has_function_privilege('authenticated', p.oid, 'EXECUTE')
                  OR has_function_privilege('anon', p.oid, 'EXECUTE'))
             AND pg_get_functiondef(p.oid) ~* '(^|[^a-z_])(insert into|update |delete from)'
             AND pg_get_functiondef(p.oid) !~ 'auth\.uid\(\)|auth\.role\(\)|auth\.jwt\(\)'
        ) s), '[]'::jsonb),

    -- 2. Executable by a LOGGED-OUT caller and writes, whatever it claims to
    --    check. Mentioning auth.uid() is not the same as being bound by it.
    'anon_writers', COALESCE((
      SELECT jsonb_agg(e ORDER BY e->>'function')
        FROM (
          SELECT jsonb_build_object(
                   'function', p.proname,
                   'args', pg_get_function_identity_arguments(p.oid)
                 ) AS e
            FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
           WHERE n.nspname = 'public'
             AND p.prosecdef
             AND p.prorettype <> 'pg_catalog.trigger'::regtype
             AND has_function_privilege('anon', p.oid, 'EXECUTE')
             AND pg_get_functiondef(p.oid) ~* '(^|[^a-z_])(insert into|update |delete from)'
        ) s), '[]'::jsonb),

    -- 3. A table in `public` with RLS off that a browser role can WRITE. There
    --    is no policy to stop it and no function in the way: the grant is the
    --    whole story. A new table created without RLS is the most expensive
    --    single mistake available in this schema, and it is silent.
    'rls_disabled_writable', COALESCE((
      SELECT jsonb_agg(e ORDER BY e->>'table')
        FROM (
          SELECT jsonb_build_object(
                   'table', c.relname,
                   'anon_write', (has_table_privilege('anon', c.oid, 'INSERT')
                               OR has_table_privilege('anon', c.oid, 'UPDATE')
                               OR has_table_privilege('anon', c.oid, 'DELETE')),
                   'authenticated_write', (has_table_privilege('authenticated', c.oid, 'INSERT')
                               OR has_table_privilege('authenticated', c.oid, 'UPDATE')
                               OR has_table_privilege('authenticated', c.oid, 'DELETE')),
                   'owner', pg_get_userbyid(c.relowner)
                 ) AS e
            FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
           WHERE n.nspname = 'public'
             AND c.relkind = 'r'
             AND NOT c.relrowsecurity
             AND (has_table_privilege('anon', c.oid, 'INSERT')
               OR has_table_privilege('anon', c.oid, 'UPDATE')
               OR has_table_privilege('anon', c.oid, 'DELETE')
               OR has_table_privilege('authenticated', c.oid, 'INSERT')
               OR has_table_privilege('authenticated', c.oid, 'UPDATE')
               OR has_table_privilege('authenticated', c.oid, 'DELETE'))
        ) s), '[]'::jsonb),

    -- 4. Executable by a LOGGED-OUT caller, reads, and never asks who is
    --    asking. Added 2026-08-31: questions 1-3 are all about writes, and
    --    three read-only functions walked past all of them in one afternoon.
    --    Extension-owned functions are excluded - PostGIS's st_estimatedextent
    --    overloads are not ours to revoke and would never leave the baseline.
    'anon_readers', COALESCE((
      SELECT jsonb_agg(e ORDER BY e->>'function')
        FROM (
          SELECT jsonb_build_object(
                   'function', p.proname,
                   'args', pg_get_function_identity_arguments(p.oid)
                 ) AS e
            FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
           WHERE n.nspname = 'public'
             AND p.prosecdef
             AND p.prorettype <> 'pg_catalog.trigger'::regtype
             AND has_function_privilege('anon', p.oid, 'EXECUTE')
             AND pg_get_functiondef(p.oid) !~* '(^|[^a-z_])(insert into|update |delete from)'
             AND pg_get_functiondef(p.oid) !~ 'auth\.uid\(\)|auth\.role\(\)|auth\.jwt\(\)'
             AND NOT EXISTS (
               SELECT 1 FROM pg_depend d
                WHERE d.objid = p.oid
                  AND d.classid = 'pg_proc'::regclass
                  AND d.deptype = 'e'
             )
        ) s), '[]'::jsonb)
  );
$$;


ALTER FUNCTION public.fn_definer_exposure_audit() OWNER TO postgres;

--
-- Name: FUNCTION fn_definer_exposure_audit(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_definer_exposure_audit() IS 'Three questions about live exposure: DEFINER writers a browser can reach that never consult the request, ANY writer a logged-out caller can execute, and tables with RLS off that a browser role can write. Read-only. Run daily by scripts/ci/audit-live-definer-exposure.mjs against a committed baseline. service_role only.';


--
-- Name: fn_delete_message(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_delete_message(p_message_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_sender uuid;
BEGIN
    IF p_message_id IS NULL OR p_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing parameters');
    END IF;

    SELECT sender_id INTO v_sender FROM social_messages WHERE id = p_message_id;

    IF v_sender IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'message not found');
    END IF;

    IF v_sender <> p_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'only the sender can delete this message');
    END IF;

    UPDATE social_messages
       SET is_deleted = true,
           content = '[message deleted]',
           updated_at = NOW()
     WHERE id = p_message_id;

    RETURN jsonb_build_object('success', true, 'message_id', p_message_id);
END;
$$;


