--
-- Name: fn_delete_user_gdpr(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_delete_user_gdpr(p_user_id uuid, p_requested_by uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request_id uuid;
  v_req_role text;
  v_summary jsonb := '{}'::jsonb;
  v_counts jsonb := '{}'::jsonb;
  v_n int;
BEGIN
  IF p_user_id IS NULL OR p_requested_by IS NULL THEN
    RAISE EXCEPTION 'user_id and requested_by required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT role INTO v_req_role FROM public.profiles WHERE id = p_requested_by;
  IF p_user_id <> p_requested_by AND v_req_role NOT IN ('admin','superadmin','god') THEN
    RAISE EXCEPTION 'only the user or a platform admin may request GDPR deletion' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- ZERO-DRIFT phase 3: financial closure precheck - refuse to anonymize
  -- an account that still holds or is owed chips (blockers returned).
  IF NOT COALESCE((public.fn_ca_gdpr_financial_precheck(p_user_id)->>'clear')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'financial_precheck_failed',
      'precheck', public.fn_ca_gdpr_financial_precheck(p_user_id));
  END IF;

  INSERT INTO public.gdpr_deletion_requests (user_id, requested_by, reason, status)
  VALUES (p_user_id, p_requested_by, p_reason, 'pending')
  RETURNING id INTO v_request_id;

  UPDATE public.chip_ledger                    SET performed_by = NULL WHERE performed_by = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('chip_ledger', v_n);
  UPDATE public.bus_event_log                  SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('bus_event_log', v_n);
  UPDATE public.admin_audit_log                SET admin_user_id = NULL WHERE admin_user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('admin_audit_log', v_n);
  UPDATE public.club_arena_audit_logs          SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('club_arena_audit_logs', v_n);
  UPDATE public.club_arena_messages            SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('club_arena_messages', v_n);
  UPDATE public.club_chat                      SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('club_chat', v_n);
  UPDATE public.table_chat                     SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('table_chat', v_n);
  UPDATE public.tournament_players             SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('tournament_players', v_n);
  UPDATE public.tournament_registrations       SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('tournament_registrations', v_n);

  UPDATE public.arcade_duels SET player1_id = NULL WHERE player1_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('arcade_duels_player1', v_n);
  UPDATE public.arcade_duels SET player2_id = NULL WHERE player2_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('arcade_duels_player2', v_n);
  UPDATE public.arcade_duels SET winner_id  = NULL WHERE winner_id  = p_user_id;

  UPDATE public.social_post_comments           SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('social_post_comments', v_n);

  UPDATE public.unions                         SET owner_id = NULL WHERE owner_id = p_user_id;
  UPDATE public.union_announcements            SET created_by = NULL WHERE created_by = p_user_id;
  UPDATE public.union_wallet_transactions      SET created_by = NULL WHERE created_by = p_user_id;
  UPDATE public.geeves_analytics               SET user_id = NULL WHERE user_id = p_user_id;
  UPDATE public.live_help_analytics            SET user_id = NULL WHERE user_id = p_user_id;
  UPDATE public.content_schedule               SET author_id = NULL WHERE author_id = p_user_id;
  UPDATE public.commander_buyin_transactions   SET player_id = NULL WHERE player_id = p_user_id;
  UPDATE public.commander_home_seats           SET user_id = NULL WHERE user_id = p_user_id;
  UPDATE public.commander_sessions             SET user_id = NULL WHERE user_id = p_user_id;
  UPDATE public.opponent_profiles              SET opponent_id = NULL WHERE opponent_id = p_user_id;
  UPDATE public.player_notes                   SET target_user_id = NULL WHERE target_user_id = p_user_id;
  UPDATE public.poy_leaderboard                SET player_id = NULL WHERE player_id = p_user_id;
  UPDATE public.arcade_jackpot                 SET last_winner_id = NULL WHERE last_winner_id = p_user_id;

  -- Anonymize the profiles row. BUG-10 fix: drop the bogus `metadata`
  -- column assignment (column does not exist) and also wipe the jsonb
  -- preference columns which can contain personalization data.
  UPDATE public.profiles
    SET
      display_name          = 'Deleted User',
      username              = 'deleted_' || substring(id::text, 1, 8),
      email                 = NULL,
      avatar_url            = NULL,
      bio                   = NULL,
      phone                 = NULL,
      preferences           = '{}'::jsonb,
      hub_preferences       = '{}'::jsonb,
      friend_preferences    = '{}'::jsonb,
      store_preferences     = '{}'::jsonb,
      messenger_preferences = '{}'::jsonb,
      reels_preferences     = '{}'::jsonb
  WHERE id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('profiles_anonymized', v_n);

  v_summary := jsonb_build_object(
    'request_id', v_request_id,
    'user_id', p_user_id,
    'requested_by', p_requested_by,
    'anonymized_columns', v_counts
  );

  UPDATE public.gdpr_deletion_requests
    SET status = 'anonymized',
        anonymized_at = now(),
        summary = v_summary
  WHERE id = v_request_id;

  PERFORM public.fn_log_admin_action(
    p_admin_user_id := p_requested_by,
    p_action := 'user.gdpr_delete_anonymized',
    p_target_type := 'user',
    p_target_id := p_user_id::text,
    p_details := v_summary,
    p_before_state := NULL,
    p_after_state := NULL,
    p_ip_address := NULL,
    p_user_agent := NULL,
    p_request_id := v_request_id::text
  );

  RETURN v_summary;
EXCEPTION WHEN OTHERS THEN
  UPDATE public.gdpr_deletion_requests
    SET status = 'failed', error_detail = SQLERRM
  WHERE id = v_request_id;
  RAISE;
END;
$$;


ALTER FUNCTION public.fn_delete_user_gdpr(p_user_id uuid, p_requested_by uuid, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION fn_delete_user_gdpr(p_user_id uuid, p_requested_by uuid, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_delete_user_gdpr(p_user_id uuid, p_requested_by uuid, p_reason text) IS 'Phase 6.1.10 — GDPR right-to-erasure. Anonymizes audit/financial/public-schema rows that reference the target auth.users id. Caller must then invoke auth.admin.deleteUser(user_id) to cascade-delete remaining personal rows and remove the auth identity.';


--
-- Name: fn_deliver_satellite_ticket_exact(uuid, uuid, uuid, text, integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_deliver_satellite_ticket_exact(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_username text, p_position integer, p_ticket_value numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_target public.tournaments%ROWTYPE;
  v_existing public.tournament_players%ROWTYPE;
  v_before_target_pool numeric;
  v_before_target_bounty numeric;
  v_split record;
  v_before_target_rake numeric;
  v_before_source_pool numeric;
  v_open boolean:=false;
  v_count integer;
  v_result jsonb;
  v_registration uuid;
  v_payout uuid;
  v_payout_meta jsonb;
  v_ledger_count integer;
  v_rake_count integer;
  v_target_buyin numeric;
  v_target_fee numeric;
  v_cash_reason text:='target_not_open';
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  SELECT * INTO v_target FROM public.tournaments
   WHERE id=p_target_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('delivery','cash','reason','target_missing'); END IF;
  SELECT count(*)::integer INTO v_count FROM public.tournament_players
   WHERE tournament_id=p_target_id;
  v_open:=CASE
    WHEN v_target.status IN ('ANNOUNCED','REGISTERING')
      THEN NOT COALESCE(v_target.prize_pool_finalized,false)
    WHEN v_target.status='RUNNING'
      THEN public.fn_tournament_late_registration_open(p_target_id)
    ELSE false END;
  v_open:=v_open AND (v_target.max_players IS NULL OR v_count<v_target.max_players);
  IF round(GREATEST(COALESCE(v_target.buy_in_amount,0),0)
           +GREATEST(COALESCE(v_target.buy_in_fee,0),0),2)
       <>round(p_ticket_value,2) THEN
    -- The winner owns the frozen advertised value. Never call the historical
    -- seat RPC at a later, different target price: it would debit the source by
    -- today's price. Cash the frozen value instead.
    v_open:=false;
    v_cash_reason:='target_economics_changed';
  END IF;

  SELECT * INTO v_existing FROM public.tournament_players
   WHERE tournament_id=p_target_id AND user_id=p_user_id FOR UPDATE;
  IF FOUND THEN
    IF COALESCE(v_existing.is_satellite_qualifier,false)
       AND v_existing.source_satellite_id=p_satellite_id THEN
      SELECT count(*)::integer,(array_agg(po.id ORDER BY po.id))[1],
             (array_agg(po.metadata ORDER BY po.id))[1]
        INTO v_count,v_payout,v_payout_meta
        FROM public.tournament_payouts po
       WHERE po.tournament_id=p_satellite_id AND po.user_id=p_user_id
         AND po.position=p_position AND po.source='satellite_seat'
         AND round(po.amount,2)=round(p_ticket_value,2)
         AND po.metadata->>'registration_id'=v_existing.id::text;
      v_target_buyin:=CASE
        WHEN COALESCE(v_payout_meta->>'target_buy_in','')~'^[0-9]+([.][0-9]+)?$'
          THEN (v_payout_meta->>'target_buy_in')::numeric ELSE -1 END;
      v_target_fee:=CASE
        WHEN COALESCE(v_payout_meta->>'target_fee','')~'^[0-9]+([.][0-9]+)?$'
          THEN (v_payout_meta->>'target_fee')::numeric ELSE -1 END;
      SELECT count(*)::integer INTO v_ledger_count
        FROM public.chip_ledger l
       WHERE l.idempotency_key='tourney:'||p_satellite_id::text||':seat:'
                               ||p_user_id::text||':pool_transfer'
         AND l.from_type='prize_liability' AND l.from_entity_id=p_satellite_id
         AND l.to_type='prize_liability' AND l.to_entity_id=p_target_id
         AND round(l.amount,2)=round(p_ticket_value,2)
         AND l.metadata->>'registration_id'=v_existing.id::text
         AND CASE WHEN COALESCE(l.metadata->>'moved','')~'^[0-9]+([.][0-9]+)?$'
                  THEN round((l.metadata->>'moved')::numeric,2) ELSE -1 END
             =round(p_ticket_value,2)
         AND CASE WHEN COALESCE(l.metadata->>'unbacked','')~'^[0-9]+([.][0-9]+)?$'
                  THEN round((l.metadata->>'unbacked')::numeric,2) ELSE -1 END=0;
      SELECT count(*)::integer INTO v_rake_count
        FROM public.rake_records rr
       WHERE rr.tournament_id=p_target_id AND rr.source='fn_award_satellite_seat'
         AND rr.metadata->>'satellite_id'=p_satellite_id::text
         AND rr.metadata->>'user_id'=p_user_id::text
         AND rr.metadata->>'registration_id'=v_existing.id::text
         AND round(rr.rake_amount,2)=round(v_target_fee,2)
         AND round(COALESCE(rr.pot_size,0),2)=round(p_ticket_value,2);
      IF v_count<>1
         OR (CASE WHEN COALESCE(v_payout_meta->>'pool_transfer','')~'^[0-9]+([.][0-9]+)?$'
                 THEN round((v_payout_meta->>'pool_transfer')::numeric,2) ELSE -1 END)
            <>round(p_ticket_value,2)
         OR (CASE WHEN COALESCE(v_payout_meta->>'unbacked','')~'^[0-9]+([.][0-9]+)?$'
                 THEN round((v_payout_meta->>'unbacked')::numeric,2) ELSE -1 END)<>0
         OR round(v_target_buyin+v_target_fee,2)<>round(p_ticket_value,2)
         OR v_ledger_count<>1
         OR (v_target_fee>0 AND v_rake_count<>1)
         OR (v_target_fee=0 AND v_rake_count<>0) THEN
        RAISE EXCEPTION 'existing target seat has no exact fully-backed payout event'
          USING ERRCODE='check_violation';
      END IF;
      RETURN jsonb_build_object('delivery','seat','already',true,
        'registration_id',v_existing.id,'payout_id',v_payout);
    ELSIF COALESCE(v_existing.is_satellite_qualifier,false)
          AND v_existing.source_satellite_id IS NULL THEN
      RAISE EXCEPTION 'existing target satellite seat has ambiguous origin'
        USING ERRCODE='check_violation';
    ELSE
      RETURN jsonb_build_object('delivery','cash','reason','seat_already_held_elsewhere');
    END IF;
  END IF;
  IF NOT v_open THEN
    RETURN jsonb_build_object('delivery','cash','reason',v_cash_reason);
  END IF;

  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_target.buy_in_amount,v_target.buy_in_fee,v_target.bounty_amount,
    COALESCE(v_target.is_bounty,false) OR COALESCE(v_target.is_pko,false) OR COALESCE(v_target.is_mystery_bounty,false));
  v_before_target_bounty:=round(COALESCE(v_target.bounty_pool,0),2);
  v_before_target_pool:=round(COALESCE(v_target.prize_pool,0),2);
  v_before_target_rake:=round(COALESCE(v_target.total_rake,0),2);
  SELECT round(COALESCE(t.prize_pool,0),2) INTO v_before_source_pool
    FROM public.tournaments t WHERE t.id=p_satellite_id FOR UPDATE;
  IF v_before_source_pool+0.005<round(p_ticket_value,2) THEN
    RAISE EXCEPTION 'satellite guarantee is not funded for its frozen ticket'
      USING ERRCODE='check_violation';
  END IF;

  v_result:=public.fn_award_satellite_seat(
    p_satellite_id,p_target_id,p_user_id,p_username,p_position);
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_result->>'awarded')::boolean,false) IS NOT TRUE
     OR COALESCE((v_result->>'pool_transfer')::numeric,-1)
          <>round(p_ticket_value,2)
     OR COALESCE((v_result->>'unbacked')::numeric,-1)<>0 THEN
    RAISE EXCEPTION 'exact target-seat award refused or wrote incomplete money: %',
      COALESCE(v_result::text,'null') USING ERRCODE='check_violation';
  END IF;
  v_registration:=(v_result->>'registration_id')::uuid;
  IF NOT EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.id=v_registration AND tp.tournament_id=p_target_id
       AND tp.user_id=p_user_id AND tp.source_satellite_id=p_satellite_id
       AND COALESCE(tp.is_satellite_qualifier,false)
  ) THEN
    RAISE EXCEPTION 'seat helper returned without the exact target registration'
      USING ERRCODE='check_violation';
  END IF;
  SELECT count(*)::integer,(array_agg(po.id ORDER BY po.id))[1] INTO v_count,v_payout
    FROM public.tournament_payouts po
   WHERE po.tournament_id=p_satellite_id AND po.user_id=p_user_id
     AND po.position=p_position AND po.source='satellite_seat'
     AND round(po.amount,2)=round(p_ticket_value,2)
     AND po.metadata->>'registration_id'=v_registration::text
     AND round(COALESCE((po.metadata->>'pool_transfer')::numeric,-1),2)
          =round(p_ticket_value,2)
     AND round(COALESCE((po.metadata->>'unbacked')::numeric,-1),2)=0;
  IF v_count<>1
     OR (SELECT round(COALESCE(t.prize_pool,0),2) FROM public.tournaments t
          WHERE t.id=p_target_id)
          <>v_before_target_pool+v_split.prize
     OR (SELECT round(COALESCE(t.bounty_pool,0),2) FROM public.tournaments t
          WHERE t.id=p_target_id) <>v_before_target_bounty+v_split.bounty
     OR (SELECT round(COALESCE(t.total_rake,0),2) FROM public.tournaments t
          WHERE t.id=p_target_id)
          <>v_before_target_rake+round(COALESCE(v_target.buy_in_fee,0),2)
     OR (SELECT round(COALESCE(t.prize_pool,0),2) FROM public.tournaments t
          WHERE t.id=p_satellite_id)
          <>v_before_source_pool-round(p_ticket_value,2) THEN
    RAISE EXCEPTION 'target seat, payout and pool transfer are not one exact event'
      USING ERRCODE='check_violation';
  END IF;
  RETURN jsonb_build_object('delivery','seat','already',false,
    'registration_id',v_registration,'payout_id',v_payout);
END;
$_$;


ALTER FUNCTION public.fn_deliver_satellite_ticket_exact(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_username text, p_position integer, p_ticket_value numeric) OWNER TO postgres;

--
-- Name: fn_deliver_shop_purchase(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_deliver_shop_purchase() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_name text;
  v_cat text;
  v_stackable boolean;
  v_grant jsonb;
BEGIN
  SELECT name, category, COALESCE(stackable, false), grant_spec
    INTO v_name, v_cat, v_stackable, v_grant
    FROM public.club_shop_items
   WHERE id = NEW.item_id;

  INSERT INTO public.club_shop_inventory (
    user_id, club_id, item_id, purchase_id, item_name, category, price_paid,
    stackable_snapshot, grant_snapshot
  ) VALUES (
    NEW.buyer_id, NEW.club_id, NEW.item_id, NEW.id, v_name, v_cat,
    NEW.price_paid, COALESCE(v_stackable, false),
    COALESCE(NEW.grant_snapshot, v_grant)
  )
  ON CONFLICT (purchase_id) DO NOTHING;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_deliver_shop_purchase() OWNER TO postgres;

--
-- Name: fn_deprecated_table_usage(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_deprecated_table_usage() RETURNS TABLE(table_name text, live_rows bigint, note text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_count bigint;
BEGIN
  FOR r IN SELECT d.table_name, d.replacement FROM deprecated_tables d LOOP
    EXECUTE format('SELECT count(*) FROM %I', r.table_name) INTO v_count;
    IF v_count > 0 THEN
      table_name := r.table_name; live_rows := v_count;
      note := 'Deprecated table still holds rows; replacement is ' || COALESCE(r.replacement, 'unknown');
      RETURN NEXT;
    END IF;
  END LOOP;
END $$;


ALTER FUNCTION public.fn_deprecated_table_usage() OWNER TO postgres;

--
-- Name: fn_detect_double_dealing(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_detect_double_dealing(p_lookback_mins integer DEFAULT 30) RETURNS TABLE(table_id uuid, hand_a bigint, hand_b bigint, overlap_seconds numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH recent AS (
    SELECT h.table_id, h.hand_number, h.started_at, h.ended_at
    FROM public.hand_history h
    WHERE h.created_at > now() - make_interval(mins => GREATEST(p_lookback_mins, 1))
      AND h.started_at IS NOT NULL
      AND h.ended_at IS NOT NULL
  )
  SELECT a.table_id,
         a.hand_number AS hand_a,
         b.hand_number AS hand_b,
         round(EXTRACT(EPOCH FROM (LEAST(a.ended_at, b.ended_at) - GREATEST(a.started_at, b.started_at)))::numeric, 1)
  FROM recent a
  JOIN recent b
    ON b.table_id = a.table_id
   AND b.hand_number > a.hand_number
   AND a.started_at < b.ended_at
   AND b.started_at < a.ended_at
  WHERE EXTRACT(EPOCH FROM (LEAST(a.ended_at, b.ended_at) - GREATEST(a.started_at, b.started_at))) > 1
$$;


ALTER FUNCTION public.fn_detect_double_dealing(p_lookback_mins integer) OWNER TO postgres;

--
-- Name: fn_detect_results_without_a_hand(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_detect_results_without_a_hand(p_since_days integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_retention integer;
  v_days      integer;
  v_since     timestamptz;
  v_flagged   integer := 0;
  v_alerts    integer := 0;
  v_chips     numeric := 0;
  v_parked    integer := 0;
  v_ids       uuid[] := ARRAY[]::uuid[];
  v_row       record;
BEGIN
  -- Never scan further back than the hand history is trusted to reach.
  SELECT COALESCE(horse_retention_days, 7) INTO v_retention
    FROM public.hand_history_retention_policy LIMIT 1;
  v_retention := GREATEST(COALESCE(v_retention, 7) - 1, 1);
  v_days := LEAST(GREATEST(COALESCE(p_since_days, v_retention), 1), v_retention);
  v_since := now() - make_interval(days => v_days);

  FOR v_row IN
    SELECT t.id,
           t.name,
           t.club_id,
           t.started_at,
           t.ended_at,
           EXTRACT(epoch FROM (t.ended_at - t.started_at))::integer AS secs,
           (SELECT count(*) FROM public.tournament_players tp
             WHERE tp.tournament_id = t.id)                          AS entrants,
           (SELECT count(*) FROM public.tournament_players tp
             WHERE tp.tournament_id = t.id AND tp.position IS NOT NULL) AS ranked,
           (SELECT COALESCE(sum(p.amount), 0) FROM public.tournament_payouts p
             WHERE p.tournament_id = t.id)                           AS paid
      FROM public.tournaments t
     WHERE t.status = 'COMPLETED'
       AND t.started_at IS NOT NULL
       AND t.started_at >= v_since
       AND NOT EXISTS (SELECT 1 FROM public.hand_history hh
                        WHERE hh.tournament_id = t.id)
       AND EXISTS (SELECT 1 FROM public.tournament_players tp
                    WHERE tp.tournament_id = t.id AND tp.position IS NOT NULL)
  LOOP
    v_flagged := v_flagged + 1;
    v_chips   := v_chips + COALESCE(v_row.paid, 0);
    v_ids     := v_ids || v_row.id;

    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical',
           'fn_detect_results_without_a_hand',
           format(
             'Tournament %s ranked %s of %s entrant(s) and paid %s chips, and not one hand was ever dealt in it',
             COALESCE(v_row.name, v_row.id::text), v_row.ranked, v_row.entrants,
             round(COALESCE(v_row.paid, 0), 2)),
           jsonb_build_object(
             'tournament_id',   v_row.id,
             'club_id',         v_row.club_id,
             'entrants',        v_row.entrants,
             'ranked',          v_row.ranked,
             'chips_paid',      round(COALESCE(v_row.paid, 0), 2),
             'started_at',      v_row.started_at,
             'ended_at',        v_row.ended_at,
             'seconds_to_end',  v_row.secs,
             'detail',          'no money was moved by this check; who is owed what on an event that never dealt is a human decision')
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'fn_detect_results_without_a_hand'
          AND fa.resolved IS NOT TRUE
          AND fa.context->>'tournament_id' = v_row.id::text);
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END LOOP;

  -- Informational, never alerted: events the engine guard is holding back from
  -- exactly this fate. A number climbing here is the guard working, not a leak.
  SELECT count(*) INTO v_parked
    FROM public.tournaments t
   WHERE t.status = 'COMPLETING'
     AND t.started_at IS NOT NULL
     AND t.started_at >= v_since
     AND NOT EXISTS (SELECT 1 FROM public.hand_history hh
                      WHERE hh.tournament_id = t.id);

  RETURN jsonb_build_object(
    'ok',                true,
    'since_days',        v_days,
    'flagged',           v_flagged,
    'alerts_raised',     v_alerts,
    'chips_paid',        round(v_chips, 2),
    'parked_completing', v_parked,
    'tournament_ids',    to_jsonb(v_ids));
END;
$$;


ALTER FUNCTION public.fn_detect_results_without_a_hand(p_since_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_detect_results_without_a_hand(p_since_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_detect_results_without_a_hand(p_since_days integer) IS 'Flags COMPLETED tournaments that carry finishing places while hand_history holds no hand for them: a result that no poker produced. Raises one deduped critical financial_alert per offender and moves no money. Bounded to the horse-only hand retention window, past which an empty history proves nothing.';


