--
-- Name: diamond_game_commits; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.diamond_game_commits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    game text NOT NULL,
    server_seed text NOT NULL,
    server_seed_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '00:15:00'::interval) NOT NULL,
    consumed_by uuid,
    CONSTRAINT diamond_game_commits_game_check CHECK ((game = ANY (ARRAY['plinko'::text, 'crash'::text])))
);


ALTER TABLE public.diamond_game_commits OWNER TO postgres;

--
-- Name: diamond_game_configs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.diamond_game_configs (
    host_id uuid NOT NULL,
    game text NOT NULL,
    host_kind text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    min_bet_diamonds integer DEFAULT 100 NOT NULL,
    max_bet_diamonds integer DEFAULT 1000 NOT NULL,
    bet_options integer[] DEFAULT ARRAY[100, 200, 500, 1000] NOT NULL,
    exposure_allowance_chips numeric(14,2) DEFAULT 1250 NOT NULL,
    cap_fraction numeric(4,3) DEFAULT 0.950 NOT NULL,
    max_multiplier_cents integer DEFAULT 100000 NOT NULL,
    growth_k numeric(6,4) DEFAULT 0.1200 NOT NULL,
    purchased_only boolean DEFAULT true NOT NULL,
    allow_fixture_accounts boolean DEFAULT false NOT NULL,
    max_rounds_per_player_per_day integer DEFAULT 500 NOT NULL,
    min_seconds_between_rounds integer DEFAULT 2 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT diamond_game_configs_cap_fraction_check CHECK (((cap_fraction > (0)::numeric) AND (cap_fraction < (1)::numeric))),
    CONSTRAINT diamond_game_configs_check CHECK ((max_bet_diamonds >= min_bet_diamonds)),
    CONSTRAINT diamond_game_configs_exposure_allowance_chips_check CHECK ((exposure_allowance_chips >= (0)::numeric)),
    CONSTRAINT diamond_game_configs_game_check CHECK ((game = ANY (ARRAY['plinko'::text, 'crash'::text]))),
    CONSTRAINT diamond_game_configs_growth_k_check CHECK ((growth_k > (0)::numeric)),
    CONSTRAINT diamond_game_configs_host_kind_check CHECK ((host_kind = ANY (ARRAY['union'::text, 'club'::text]))),
    CONSTRAINT diamond_game_configs_max_multiplier_cents_check CHECK ((max_multiplier_cents >= 101)),
    CONSTRAINT diamond_game_configs_max_rounds_per_player_per_day_check CHECK ((max_rounds_per_player_per_day > 0)),
    CONSTRAINT diamond_game_configs_min_bet_diamonds_check CHECK ((min_bet_diamonds > 0)),
    CONSTRAINT diamond_game_configs_min_seconds_between_rounds_check CHECK ((min_seconds_between_rounds >= 0))
);


ALTER TABLE public.diamond_game_configs OWNER TO postgres;

--
-- Name: TABLE diamond_game_configs; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.diamond_game_configs IS 'One row per host per game (plinko, crash). exposure_allowance_chips is the working capital the host accepts as its maximum exposure: cumulative chips paid may exceed cumulative chips minted by at most this much. cap_fraction is the share of the pool''s headroom a single round may be promised. max_multiplier_cents is the ceiling (crash; plinko tables carry their own). growth_k is the crash curve e^(k t).';


--
-- Name: diamond_game_pools; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.diamond_game_pools (
    host_id uuid NOT NULL,
    game text NOT NULL,
    rounds bigint DEFAULT 0 NOT NULL,
    intake_diamonds numeric(18,0) DEFAULT 0 NOT NULL,
    chips_minted numeric(16,2) DEFAULT 0 NOT NULL,
    chips_paid numeric(16,2) DEFAULT 0 NOT NULL,
    reserved_chips numeric(16,2) DEFAULT 0 NOT NULL,
    constrained_rounds bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT diamond_game_pools_reserved_chips_check CHECK ((reserved_chips >= (0)::numeric))
);


ALTER TABLE public.diamond_game_pools OWNER TO postgres;

--
-- Name: TABLE diamond_game_pools; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.diamond_game_pools IS 'Plinko and Crash economics per host per game. Invariant, checked on every round and by fn_diamond_game_metrics: chips_paid + reserved_chips <= chips_minted + exposure_allowance_chips. chips_minted is 0.80 of intake; reserved_chips is the largest payout every OPEN crash round could still produce.';


--
-- Name: fn_diamond_game_admit(text, uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_admit(p_game text, p_club_id uuid, p_commit_id uuid, p_client_seed text, p_bet integer, OUT err jsonb, OUT o_host uuid, OUT o_kind text, OUT o_cfg public.diamond_game_configs, OUT o_pool public.diamond_game_pools, OUT o_bank numeric, OUT o_rate integer, OUT o_bet_chips numeric, OUT o_mint numeric, OUT o_nonce bigint, OUT o_commit public.diamond_game_commits, OUT o_diamonds numeric, OUT o_fixture boolean) RETURNS record
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_today integer; v_last timestamptz;
  v_purchased integer; v_spendable integer;
  v_label text := CASE p_game WHEN 'plinko' THEN 'Diamond Plinko' ELSE 'Diamond Crash' END;
BEGIN
  err := NULL;
  IF v_user IS NULL THEN
    err := jsonb_build_object('ok', false, 'error', 'Sign In To Play'); RETURN;
  END IF;
  SELECT h.host_id, h.host_kind INTO o_host, o_kind FROM public.fn_wheel_host(p_club_id) h;
  IF o_host IS NULL THEN
    err := jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found'); RETURN;
  END IF;
  o_rate := public.fn_ca_bridge_rate();
  IF o_rate IS NULL OR o_rate <= 0 THEN
    err := jsonb_build_object('ok', false, 'error', 'The Bridge Rate Is Not Set'); RETURN;
  END IF;
  IF length(COALESCE(p_client_seed, '')) < 1 THEN
    err := jsonb_build_object('ok', false, 'error', 'A Client Seed Is Required'); RETURN;
  END IF;
  IF public.fn_platform_frozen() THEN
    err := jsonb_build_object('ok', false, 'error', 'The Platform Is In Its Maintenance Break. Play Again In A Few Minutes'); RETURN;
  END IF;
  IF EXISTS (SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope = p_game AND f.cleared_at IS NULL) THEN
    err := jsonb_build_object('ok', false, 'error', v_label || ' Is Paused'); RETURN;
  END IF;

  SELECT * INTO o_cfg FROM public.diamond_game_configs c WHERE c.host_id = o_host AND c.game = p_game FOR UPDATE;
  IF o_cfg.host_id IS NULL OR NOT o_cfg.enabled THEN
    err := jsonb_build_object('ok', false, 'error', v_label || ' Is Not Open Here'); RETURN;
  END IF;
  INSERT INTO public.diamond_game_pools (host_id, game) VALUES (o_host, p_game) ON CONFLICT (host_id, game) DO NOTHING;
  IF p_game = 'crash' THEN
    PERFORM public.fn_crash_settle_decided(o_host);
  END IF;
  SELECT * INTO o_pool FROM public.diamond_game_pools p WHERE p.host_id = o_host AND p.game = p_game FOR UPDATE;

  IF p_bet IS NULL OR p_bet < o_cfg.min_bet_diamonds OR p_bet > o_cfg.max_bet_diamonds OR p_bet % o_rate <> 0 THEN
    err := jsonb_build_object('ok', false, 'error',
      format('Bets Are Whole Chips Between %s And %s Diamonds', o_cfg.min_bet_diamonds, o_cfg.max_bet_diamonds)); RETURN;
  END IF;
  o_bet_chips := round(p_bet::numeric / o_rate, 2);
  o_mint := round(o_bet_chips * 0.8, 2);

  IF NOT EXISTS (SELECT 1 FROM public.club_members m
                  WHERE m.club_id = p_club_id AND m.user_id = v_user
                    AND COALESCE(m.status, 'active') IN ('active', 'approved')) THEN
    err := jsonb_build_object('ok', false, 'error', 'Join The Club Before You Play'); RETURN;
  END IF;
  o_fixture := public.fn_ca_is_fixture_account(v_user) OR public.fn_ca_is_cert_account(v_user);
  IF o_fixture AND NOT o_cfg.allow_fixture_accounts THEN
    err := jsonb_build_object('ok', false, 'error', 'Certification Accounts Do Not Play This Game'); RETURN;
  END IF;
  SELECT * INTO o_commit FROM public.diamond_game_commits c
   WHERE c.id = p_commit_id AND c.user_id = v_user AND c.game = p_game AND c.consumed_by IS NULL FOR UPDATE;
  IF o_commit.id IS NULL THEN
    err := jsonb_build_object('ok', false, 'error', 'That Ticket Is Not Yours Or Was Already Used. Open The Game Again'); RETURN;
  END IF;
  IF o_commit.expires_at < now() THEN
    err := jsonb_build_object('ok', false, 'error', 'That Ticket Expired. Open The Game Again'); RETURN;
  END IF;

  IF p_game = 'plinko' THEN
    SELECT count(*)::integer, max(d.created_at) INTO v_today, v_last
      FROM public.plinko_drops d
     WHERE d.user_id = v_user AND d.host_id = o_host
       AND (d.created_at AT TIME ZONE 'America/Chicago')::date = (now() AT TIME ZONE 'America/Chicago')::date;
    SELECT count(*) + 1 INTO o_nonce FROM public.plinko_drops d WHERE d.user_id = v_user;
  ELSE
    SELECT count(*)::integer, max(c.created_at) INTO v_today, v_last
      FROM public.crash_rounds c
     WHERE c.user_id = v_user AND c.host_id = o_host
       AND (c.created_at AT TIME ZONE 'America/Chicago')::date = (now() AT TIME ZONE 'America/Chicago')::date;
    SELECT count(*) + 1 INTO o_nonce FROM public.crash_rounds c WHERE c.user_id = v_user;
  END IF;
  IF v_today >= o_cfg.max_rounds_per_player_per_day THEN
    err := jsonb_build_object('ok', false, 'error', format('You Have Reached Today''s Limit Of %s Rounds', o_cfg.max_rounds_per_player_per_day)); RETURN;
  END IF;
  IF v_last IS NOT NULL AND now() - v_last < make_interval(secs => o_cfg.min_seconds_between_rounds) THEN
    err := jsonb_build_object('ok', false, 'error', 'One Moment Between Rounds'); RETURN;
  END IF;

  SELECT COALESCE(p.diamonds, 0) INTO o_diamonds FROM public.profiles p WHERE p.id = v_user;
  v_purchased := public.fn_wheel_purchased_available(v_user);
  v_spendable := CASE WHEN o_cfg.purchased_only THEN LEAST(o_diamonds, v_purchased)::integer ELSE o_diamonds::integer END;
  IF v_spendable < p_bet THEN
    err := jsonb_build_object('ok', false,
      'error', CASE WHEN o_cfg.purchased_only AND o_diamonds >= p_bet
                    THEN 'This Game Takes Purchased Diamonds Only'
                    ELSE 'Not Enough Diamonds For That Bet' END,
      'diamonds', o_diamonds, 'spendable', v_spendable, 'bet_diamonds', p_bet); RETURN;
  END IF;

  IF o_kind = 'union' THEN
    INSERT INTO public.union_wallets (union_id, created_at, updated_at) VALUES (o_host, now(), now())
    ON CONFLICT (union_id) DO NOTHING;
    SELECT COALESCE(w.chip_balance, 0) INTO o_bank FROM public.union_wallets w WHERE w.union_id = o_host FOR UPDATE;
  ELSE
    SELECT COALESCE(c.chip_treasury, 0) INTO o_bank FROM public.clubs c WHERE c.id = o_host FOR UPDATE;
  END IF;
  o_bank := COALESCE(o_bank, 0);
END $$;


ALTER FUNCTION public.fn_diamond_game_admit(p_game text, p_club_id uuid, p_commit_id uuid, p_client_seed text, p_bet integer, OUT err jsonb, OUT o_host uuid, OUT o_kind text, OUT o_cfg public.diamond_game_configs, OUT o_pool public.diamond_game_pools, OUT o_bank numeric, OUT o_rate integer, OUT o_bet_chips numeric, OUT o_mint numeric, OUT o_nonce bigint, OUT o_commit public.diamond_game_commits, OUT o_diamonds numeric, OUT o_fixture boolean) OWNER TO postgres;

--
-- Name: fn_diamond_game_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NULLIF(current_setting('app.ledger_maintenance', true), '') IS NOT NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF TG_TABLE_NAME = 'crash_rounds' AND TG_OP = 'UPDATE' AND OLD.status = 'open' THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION '% is append-only: a settled round is a fact and is never edited or deleted', TG_TABLE_NAME
    USING ERRCODE = 'integrity_constraint_violation';
END $$;


ALTER FUNCTION public.fn_diamond_game_append_only() OWNER TO postgres;

--
-- Name: fn_diamond_game_cap_cents(public.diamond_game_configs, public.diamond_game_pools, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_cap_cents(p_cfg public.diamond_game_configs, p_pool public.diamond_game_pools, p_bank numeric, p_bet_chips numeric, p_ceiling_cents integer) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mint numeric := round(p_bet_chips * 0.8, 2);
  v_headroom numeric; v_bank_room numeric; v_cap numeric;
BEGIN
  v_headroom  := COALESCE(p_pool.chips_minted, 0) + v_mint + p_cfg.exposure_allowance_chips
               - COALESCE(p_pool.chips_paid, 0) - COALESCE(p_pool.reserved_chips, 0);
  v_bank_room := COALESCE(p_bank, 0) + v_mint - COALESCE(p_pool.reserved_chips, 0);
  v_cap := LEAST(p_ceiling_cents::numeric,
                 floor(p_cfg.cap_fraction * v_headroom / p_bet_chips * 100),
                 floor(v_bank_room / p_bet_chips * 100));
  RETURN GREATEST(0, v_cap)::integer;
END $$;


ALTER FUNCTION public.fn_diamond_game_cap_cents(p_cfg public.diamond_game_configs, p_pool public.diamond_game_pools, p_bank numeric, p_bet_chips numeric, p_ceiling_cents integer) OWNER TO postgres;

--
-- Name: fn_diamond_game_commit(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_commit(p_game text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_seed text; v_hash text; v_id uuid; v_exp timestamptz;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In To Play');
  END IF;
  IF p_game NOT IN ('plinko', 'crash') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Game Does Not Exist');
  END IF;
  DELETE FROM public.diamond_game_commits WHERE user_id = v_user AND game = p_game AND consumed_by IS NULL;
  v_seed := encode(extensions.gen_random_bytes(32), 'hex');
  v_hash := encode(extensions.digest(v_seed, 'sha256'), 'hex');
  INSERT INTO public.diamond_game_commits (user_id, game, server_seed, server_seed_hash)
  VALUES (v_user, p_game, v_seed, v_hash) RETURNING id, expires_at INTO v_id, v_exp;
  RETURN jsonb_build_object('ok', true, 'commit_id', v_id, 'server_seed_hash', v_hash, 'expires_at', v_exp);
END $$;


ALTER FUNCTION public.fn_diamond_game_commit(p_game text) OWNER TO postgres;

--
-- Name: fn_diamond_game_config_history(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_config_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.diamond_game_config_history (host_id, game, changed_by, before, after)
  VALUES (NEW.host_id, NEW.game, COALESCE(NEW.updated_by, auth.uid()),
          CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) END, to_jsonb(NEW));
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_diamond_game_config_history() OWNER TO postgres;

--
-- Name: fn_diamond_game_history(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_history(p_club_id uuid, p_game text, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_host uuid; v_out jsonb;
BEGIN
  SELECT h.host_id INTO v_host FROM public.fn_wheel_host(p_club_id) h;
  IF p_game = 'plinko' THEN
    SELECT COALESCE(jsonb_agg(public.fn_plinko_drop_result(d) ORDER BY d.created_at DESC), '[]'::jsonb) INTO v_out
      FROM (SELECT * FROM public.plinko_drops x WHERE x.user_id = auth.uid() AND x.host_id = v_host
             ORDER BY x.created_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100)) d;
  ELSIF p_game = 'crash' THEN
    SELECT COALESCE(jsonb_agg(public.fn_crash_round_result(c) ORDER BY c.created_at DESC), '[]'::jsonb) INTO v_out
      FROM (SELECT * FROM public.crash_rounds x WHERE x.user_id = auth.uid() AND x.host_id = v_host AND x.status <> 'open'
             ORDER BY x.created_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100)) c;
  ELSE
    v_out := '[]'::jsonb;
  END IF;
  RETURN v_out;
END $$;


ALTER FUNCTION public.fn_diamond_game_history(p_club_id uuid, p_game text, p_limit integer) OWNER TO postgres;

--
-- Name: fn_diamond_game_metrics(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_metrics(p_club_id uuid, p_game text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  cfg public.diamond_game_configs%ROWTYPE;
  pool public.diamond_game_pools%ROWTYPE;
  v_rate integer := public.fn_ca_bridge_rate();
  v_windows jsonb; v_bank numeric; v_open integer := 0;
  v_invariant_ok boolean;
BEGIN
  IF p_game NOT IN ('plinko', 'crash') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Game Does Not Exist');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found'); END IF;
  IF NOT public.fn_wheel_can_operate(v_host, v_kind, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only The Host Owner Or An Admin May Read These Metrics');
  END IF;
  SELECT * INTO cfg FROM public.diamond_game_configs WHERE host_id = v_host AND game = p_game;
  SELECT * INTO pool FROM public.diamond_game_pools WHERE host_id = v_host AND game = p_game;
  IF cfg.host_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'configured', false, 'game', p_game, 'host_id', v_host, 'host_kind', v_kind);
  END IF;
  IF v_kind = 'union' THEN
    SELECT COALESCE(w.chip_balance, 0) INTO v_bank FROM public.union_wallets w WHERE w.union_id = v_host;
  ELSE
    SELECT COALESCE(c.chip_treasury, 0) INTO v_bank FROM public.clubs c WHERE c.id = v_host;
  END IF;

  IF p_game = 'plinko' THEN
    SELECT jsonb_agg(w ORDER BY w->>'window') INTO v_windows
      FROM (
        SELECT jsonb_build_object(
                 'window', lbl, 'rounds', n,
                 'intake_chips', round(intake, 2), 'paid_chips', round(paid, 2),
                 'realized_rtp', CASE WHEN intake > 0 THEN round(paid / intake, 4) END,
                 'z', CASE WHEN n >= 30 AND var > 0 THEN round((paid - 0.80 * intake) / sqrt(var), 2) END,
                 'constrained', constrained,
                 'drift', CASE WHEN n >= 2000 AND var > 0 THEN abs((paid - 0.80 * intake) / sqrt(var)) >= 4 ELSE false END) AS w
          FROM (
            SELECT lbl, count(d.id) AS n,
                   COALESCE(SUM(d.bet_chips), 0) AS intake,
                   COALESCE(SUM(d.payout_chips), 0) AS paid,
                   COALESCE(SUM(power(d.bet_chips * COALESCE(t.sd_chips, 0), 2)), 0) AS var,
                   COALESCE(SUM(CASE WHEN d.capped THEN 1 ELSE 0 END), 0) AS constrained
              FROM (VALUES ('1h', interval '1 hour'), ('24h', interval '24 hours'), ('7d', interval '7 days')) AS win(lbl, span)
              LEFT JOIN public.plinko_drops d ON d.host_id = v_host AND NOT d.is_fixture AND d.created_at >= now() - win.span
              LEFT JOIN public.plinko_tables t ON t.version = d.table_version
             GROUP BY lbl) x) y;
  ELSE
    SELECT count(*) INTO v_open FROM public.crash_rounds c WHERE c.host_id = v_host AND c.status = 'open';
    SELECT jsonb_agg(w ORDER BY w->>'window') INTO v_windows
      FROM (
        SELECT jsonb_build_object(
                 'window', lbl, 'rounds', n,
                 'intake_chips', round(intake, 2), 'paid_chips', round(paid, 2),
                 'realized_rtp', CASE WHEN intake > 0 THEN round(paid / intake, 4) END,
                 'z', CASE WHEN n >= 30 AND var > 0 THEN round((paid - 0.80 * intake) / sqrt(var), 2) END,
                 'constrained', constrained,
                 'instant_crashes', instant,
                 'drift', CASE WHEN n >= 2000 AND var > 0 THEN abs((paid - 0.80 * intake) / sqrt(var)) >= 4 ELSE false END) AS w
          FROM (
            -- Variance per round at the target the player actually took: a
            -- payout of bet*x with probability 0.8/x has variance
            -- bet^2 * (0.8 x - 0.64). A crashed round's target is unknown; it
            -- is scored at its own crash point, the most it could have asked.
            SELECT lbl, count(c.id) AS n,
                   COALESCE(SUM(c.bet_chips), 0) AS intake,
                   COALESCE(SUM(c.payout_chips), 0) AS paid,
                   COALESCE(SUM(power(c.bet_chips, 2) * (0.8 * LEAST(COALESCE(c.cashout_cents, c.crash_cents), c.cap_cents)::numeric / 100 - 0.64)), 0) AS var,
                   COALESCE(SUM(CASE WHEN c.cap_cents < cfg.max_multiplier_cents THEN 1 ELSE 0 END), 0) AS constrained,
                   COALESCE(SUM(CASE WHEN c.crash_cents = 100 THEN 1 ELSE 0 END), 0) AS instant
              FROM (VALUES ('1h', interval '1 hour'), ('24h', interval '24 hours'), ('7d', interval '7 days')) AS win(lbl, span)
              LEFT JOIN public.crash_rounds c ON c.host_id = v_host AND NOT c.is_fixture AND c.status <> 'open' AND c.created_at >= now() - win.span
             GROUP BY lbl) x) y;
  END IF;

  v_invariant_ok := pool.host_id IS NULL
                 OR (pool.chips_paid + pool.reserved_chips <= pool.chips_minted + cfg.exposure_allowance_chips);
  IF NOT v_invariant_ok THEN
    BEGIN
      PERFORM public.fn_ca_raise_drift_incident(
        p_source => p_game || '_invariant', p_classification => 'unauthorized_adjustment', p_severity => 'critical',
        p_dedupe_key => p_game || ':invariant:' || v_host::text,
        p_discrepancy => pool.chips_paid + pool.reserved_chips - pool.chips_minted - cfg.exposure_allowance_chips,
        p_expected => pool.chips_minted + cfg.exposure_allowance_chips, p_actual => pool.chips_paid + pool.reserved_chips,
        p_layer => 'settlement', p_entity_type => 'diamond_game_pool', p_entity_id => v_host,
        p_union_id => CASE WHEN v_kind = 'union' THEN v_host END,
        p_club_id => CASE WHEN v_kind = 'club' THEN v_host END,
        p_suspected_cause => 'Diamond ' || p_game || ' paid or reserved more than it minted plus the allowance; the per-round cap was bypassed',
        p_metadata => to_jsonb(pool));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'configured', true, 'game', p_game, 'host_id', v_host, 'host_kind', v_kind,
    'config', to_jsonb(cfg),
    'pool', to_jsonb(pool),
    'bank_chips', COALESCE(v_bank, 0),
    'open_rounds', v_open,
    'exposure_chips', COALESCE(pool.chips_paid, 0) + COALESCE(pool.reserved_chips, 0) - COALESCE(pool.chips_minted, 0),
    'exposure_headroom_chips', cfg.exposure_allowance_chips - (COALESCE(pool.chips_paid, 0) + COALESCE(pool.reserved_chips, 0) - COALESCE(pool.chips_minted, 0)),
    'realized_rtp_lifetime', CASE WHEN COALESCE(pool.intake_diamonds, 0) > 0
        THEN round(pool.chips_paid / (pool.intake_diamonds::numeric / v_rate), 4) END,
    'house_take_lifetime_chips', CASE WHEN pool.host_id IS NOT NULL
        THEN round(pool.intake_diamonds::numeric / v_rate - pool.chips_minted, 2) END,
    'constrained_rate', CASE WHEN COALESCE(pool.rounds, 0) > 0 THEN round(pool.constrained_rounds::numeric / pool.rounds, 4) END,
    'invariant_ok', v_invariant_ok,
    'windows', COALESCE(v_windows, '[]'::jsonb),
    'tables', CASE WHEN p_game = 'plinko' THEN
        (SELECT jsonb_agg(jsonb_build_object('version', t.version, 'name', t.name, 'spec_rtp', t.spec_rtp,
                                             'sd_chips', t.sd_chips, 'hit_rate', t.hit_rate, 'max_multiplier_cents', t.max_multiplier_cents,
                                             'activated_at', t.activated_at) ORDER BY t.version)
           FROM public.plinko_tables t) END);
END $$;


ALTER FUNCTION public.fn_diamond_game_metrics(p_club_id uuid, p_game text) OWNER TO postgres;

--
-- Name: fn_diamond_game_mint_leg(uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_mint_leg(p_host uuid, p_kind text, p_amount numeric, p_key text) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_after numeric;
BEGIN
  IF p_amount <= 0 THEN
    RETURN NULL;
  END IF;
  PERFORM public.fn_ca_declare_ledger('mint', 'issuance_reserve', NULL, NULL, p_key, NULL);
  IF p_kind = 'union' THEN
    UPDATE public.union_wallets SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = now()
     WHERE union_id = p_host RETURNING chip_balance INTO v_after;
  ELSE
    UPDATE public.clubs SET chip_treasury = COALESCE(chip_treasury, 0) + p_amount, updated_at = now()
     WHERE id = p_host RETURNING chip_treasury INTO v_after;
  END IF;
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_idempotency_key', '', true);
  IF NOT EXISTS (SELECT 1 FROM public.chip_ledger WHERE idempotency_key = p_key) THEN
    RAISE EXCEPTION 'diamond games: the host bank moved but no mint leg was journaled for %', p_key;
  END IF;
  RETURN v_after;
END $$;


ALTER FUNCTION public.fn_diamond_game_mint_leg(p_host uuid, p_kind text, p_amount numeric, p_key text) OWNER TO postgres;

--
-- Name: fn_diamond_game_prize_leg(text, uuid, text, uuid, uuid, numeric, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_prize_leg(p_game text, p_host uuid, p_kind text, p_club uuid, p_user uuid, p_amount numeric, p_key text, p_note text, p_meta jsonb, OUT bank_after numeric, OUT member_after numeric) RETURNS record
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_category text := p_game || '_prize';
BEGIN
  IF p_amount <= 0 THEN
    RETURN;
  END IF;
  PERFORM public.fn_ca_declare_ledger(v_category,
            CASE WHEN p_kind = 'union' THEN 'union_bank' ELSE 'club_treasury' END,
            p_host, NULL, p_key,
            CASE WHEN p_kind = 'union' THEN ARRAY['union_wallets'] ELSE ARRAY['clubs'] END);
  IF p_kind = 'union' THEN
    UPDATE public.union_wallets SET chip_balance = chip_balance - p_amount, updated_at = now()
     WHERE union_id = p_host AND COALESCE(chip_balance, 0) >= p_amount
     RETURNING chip_balance INTO bank_after;
  ELSE
    UPDATE public.clubs SET chip_treasury = chip_treasury - p_amount, updated_at = now()
     WHERE id = p_host AND COALESCE(chip_treasury, 0) >= p_amount
     RETURNING chip_treasury INTO bank_after;
  END IF;
  IF bank_after IS NULL THEN
    RAISE EXCEPTION 'diamond games: the host bank refused the % payout of %', p_game, p_amount;
  END IF;
  UPDATE public.club_members SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = now()
   WHERE club_id = p_club AND user_id = p_user
     AND COALESCE(status, 'active') IN ('active', 'approved')
   RETURNING chip_balance INTO member_after;
  IF member_after IS NULL THEN
    RAISE EXCEPTION 'diamond games: the % payout landed nowhere for % in club %', p_game, p_user, p_club;
  END IF;
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_idempotency_key', '', true);
  PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);
  PERFORM set_config('app.ledger_autoskip_clubs', '', true);
  IF p_kind = 'union' THEN
    INSERT INTO public.union_wallet_transactions
      (union_id, club_id, wallet, direction, amount, balance_after, tx_type, notes, created_by)
    VALUES (p_host, p_club, 'chip_balance', 'debit', p_amount, bank_after, v_category, p_note, p_user);
  END IF;
  INSERT INTO public.chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  VALUES (p_club, NULL, p_user, p_amount, v_category, p_note, p_meta, member_after);
END $$;


ALTER FUNCTION public.fn_diamond_game_prize_leg(p_game text, p_host uuid, p_kind text, p_club uuid, p_user uuid, p_amount numeric, p_key text, p_note text, p_meta jsonb, OUT bank_after numeric, OUT member_after numeric) OWNER TO postgres;

--
-- Name: fn_diamond_game_set_config(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_set_config(p_club_id uuid, p_game text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  cfg public.diamond_game_configs%ROWTYPE;
  v_rate integer := public.fn_ca_bridge_rate();
  v_bad integer;
BEGIN
  IF v_user IS NULL AND COALESCE(auth.role(), '') <> 'service_role' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In First');
  END IF;
  IF p_game NOT IN ('plinko', 'crash') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Game Does Not Exist');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  IF NOT public.fn_wheel_can_operate(v_host, v_kind, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only The Host Owner Or An Admin May Change This Game');
  END IF;

  SELECT * INTO cfg FROM public.diamond_game_configs WHERE host_id = v_host AND game = p_game FOR UPDATE;
  IF cfg.host_id IS NULL THEN
    INSERT INTO public.diamond_game_configs (host_id, game, host_kind, updated_by)
    VALUES (v_host, p_game, v_kind, v_user) RETURNING * INTO cfg;
    INSERT INTO public.diamond_game_pools (host_id, game) VALUES (v_host, p_game) ON CONFLICT (host_id, game) DO NOTHING;
  END IF;

  IF p_patch ? 'min_bet_diamonds' THEN cfg.min_bet_diamonds := (p_patch->>'min_bet_diamonds')::integer; END IF;
  IF p_patch ? 'max_bet_diamonds' THEN cfg.max_bet_diamonds := (p_patch->>'max_bet_diamonds')::integer; END IF;
  IF p_patch ? 'bet_options' THEN
    SELECT array_agg(x::integer ORDER BY x::integer) INTO cfg.bet_options FROM jsonb_array_elements_text(p_patch->'bet_options') x;
  END IF;
  IF p_patch ? 'exposure_allowance_chips' THEN cfg.exposure_allowance_chips := round((p_patch->>'exposure_allowance_chips')::numeric, 2); END IF;
  IF p_patch ? 'cap_fraction' THEN cfg.cap_fraction := round((p_patch->>'cap_fraction')::numeric, 3); END IF;
  IF p_patch ? 'max_multiplier_cents' THEN cfg.max_multiplier_cents := (p_patch->>'max_multiplier_cents')::integer; END IF;
  IF p_patch ? 'growth_k' THEN cfg.growth_k := round((p_patch->>'growth_k')::numeric, 4); END IF;
  IF p_patch ? 'purchased_only' THEN cfg.purchased_only := (p_patch->>'purchased_only')::boolean; END IF;
  IF p_patch ? 'allow_fixture_accounts' THEN cfg.allow_fixture_accounts := (p_patch->>'allow_fixture_accounts')::boolean; END IF;
  IF p_patch ? 'max_rounds_per_player_per_day' THEN cfg.max_rounds_per_player_per_day := (p_patch->>'max_rounds_per_player_per_day')::integer; END IF;
  IF p_patch ? 'min_seconds_between_rounds' THEN cfg.min_seconds_between_rounds := (p_patch->>'min_seconds_between_rounds')::integer; END IF;
  IF p_patch ? 'enabled' THEN cfg.enabled := (p_patch->>'enabled')::boolean; END IF;

  IF cfg.bet_options IS NULL OR array_length(cfg.bet_options, 1) IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'At Least One Bet Size Is Required');
  END IF;
  SELECT count(*) INTO v_bad FROM unnest(cfg.bet_options) b
   WHERE b % v_rate <> 0 OR b < cfg.min_bet_diamonds OR b > cfg.max_bet_diamonds;
  IF v_bad > 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', format('Every Bet Size Must Be A Whole Number Of Chips (%s Diamonds Each) Inside The Limits', v_rate));
  END IF;
  IF cfg.enabled AND p_game = 'plinko' AND NOT EXISTS (
       SELECT 1 FROM public.plinko_tables t, public.fn_plinko_table_audit(t.version) a
        WHERE t.activated_at IS NOT NULL AND a.spec_rtp = 0.800000) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No Plinko Table Audits To 80 Percent. The Game Cannot Be Enabled');
  END IF;

  UPDATE public.diamond_game_configs
     SET enabled = cfg.enabled, min_bet_diamonds = cfg.min_bet_diamonds, max_bet_diamonds = cfg.max_bet_diamonds,
         bet_options = cfg.bet_options, exposure_allowance_chips = cfg.exposure_allowance_chips,
         cap_fraction = cfg.cap_fraction, max_multiplier_cents = cfg.max_multiplier_cents, growth_k = cfg.growth_k,
         purchased_only = cfg.purchased_only, allow_fixture_accounts = cfg.allow_fixture_accounts,
         max_rounds_per_player_per_day = cfg.max_rounds_per_player_per_day,
         min_seconds_between_rounds = cfg.min_seconds_between_rounds,
         updated_at = now(), updated_by = v_user
   WHERE host_id = v_host AND game = p_game
   RETURNING * INTO cfg;
  RETURN jsonb_build_object('ok', true, 'config', to_jsonb(cfg));
END $$;


ALTER FUNCTION public.fn_diamond_game_set_config(p_club_id uuid, p_game text, p_patch jsonb) OWNER TO postgres;

--
-- Name: fn_diamond_game_state(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_state(p_club_id uuid, p_game text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  cfg public.diamond_game_configs%ROWTYPE;
  pool public.diamond_game_pools%ROWTYPE;
  v_rate integer := public.fn_ca_bridge_rate();
  v_bank numeric := 0;
  v_diamonds numeric := 0; v_purchased integer := 0; v_spendable integer := 0;
  v_today integer := 0; v_last timestamptz; v_wait integer := 0;
  v_member boolean := false; v_member_chips numeric;
  v_frozen boolean;
  v_bets jsonb; v_tables jsonb; v_open jsonb;
  r public.crash_rounds;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In To Play');
  END IF;
  IF p_game NOT IN ('plinko', 'crash') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Game Does Not Exist');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  SELECT * INTO cfg FROM public.diamond_game_configs WHERE host_id = v_host AND game = p_game;
  IF cfg.host_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'available', false, 'reason', 'not_configured',
                              'game', p_game, 'host_id', v_host, 'host_kind', v_kind);
  END IF;

  -- Time settles what it has decided before anybody reads the headroom.
  IF p_game = 'crash' THEN
    PERFORM 1 FROM public.diamond_game_configs WHERE host_id = v_host AND game = 'crash' FOR UPDATE;
    PERFORM public.fn_crash_settle_decided(v_host);
    SELECT * INTO r FROM public.crash_rounds c WHERE c.host_id = v_host AND c.user_id = v_user AND c.status = 'open'
     ORDER BY c.started_at DESC LIMIT 1;
    IF r.id IS NOT NULL THEN
      v_open := public.fn_crash_round_result(r);
    END IF;
  END IF;
  SELECT * INTO pool FROM public.diamond_game_pools WHERE host_id = v_host AND game = p_game;

  IF v_kind = 'union' THEN
    SELECT COALESCE(w.chip_balance, 0) INTO v_bank FROM public.union_wallets w WHERE w.union_id = v_host;
  ELSE
    SELECT COALESCE(c.chip_treasury, 0) INTO v_bank FROM public.clubs c WHERE c.id = v_host;
  END IF;
  v_bank := COALESCE(v_bank, 0);

  -- Every bet option with the cap the pool can promise on it right now.
  SELECT jsonb_agg(jsonb_build_object(
           'bet_diamonds', b, 'bet_chips', round(b::numeric / v_rate, 2),
           'cap_cents', public.fn_diamond_game_cap_cents(cfg, pool, v_bank, b::numeric / v_rate, cfg.max_multiplier_cents),
           'playable', public.fn_diamond_game_cap_cents(cfg, pool, v_bank, b::numeric / v_rate, cfg.max_multiplier_cents) >= 101)
         ORDER BY b)
    INTO v_bets
    FROM unnest(cfg.bet_options) b
   WHERE b BETWEEN cfg.min_bet_diamonds AND cfg.max_bet_diamonds AND b % v_rate = 0;

  IF p_game = 'plinko' THEN
    SELECT jsonb_agg(jsonb_build_object(
             'version', t.version, 'name', t.name, 'rows', t.board_rows,
             'multipliers_cents', to_jsonb(t.multipliers_cents),
             'max_multiplier_cents', t.max_multiplier_cents,
             'spec_rtp', t.spec_rtp, 'sd_chips', t.sd_chips, 'hit_rate', t.hit_rate, 'note', t.note)
           ORDER BY t.version)
      INTO v_tables
      FROM public.plinko_tables t WHERE t.activated_at IS NOT NULL;
  END IF;

  SELECT COALESCE(p.diamonds, 0) INTO v_diamonds FROM public.profiles p WHERE p.id = v_user;
  v_purchased := public.fn_wheel_purchased_available(v_user);
  v_spendable := CASE WHEN cfg.purchased_only THEN LEAST(v_diamonds, v_purchased)::integer ELSE v_diamonds::integer END;

  IF p_game = 'plinko' THEN
    SELECT count(*)::integer, max(d.created_at) INTO v_today, v_last
      FROM public.plinko_drops d
     WHERE d.user_id = v_user AND d.host_id = v_host
       AND (d.created_at AT TIME ZONE 'America/Chicago')::date = (now() AT TIME ZONE 'America/Chicago')::date;
  ELSE
    SELECT count(*)::integer, max(c.created_at) INTO v_today, v_last
      FROM public.crash_rounds c
     WHERE c.user_id = v_user AND c.host_id = v_host
       AND (c.created_at AT TIME ZONE 'America/Chicago')::date = (now() AT TIME ZONE 'America/Chicago')::date;
  END IF;
  IF v_last IS NOT NULL THEN
    v_wait := GREATEST(0, cfg.min_seconds_between_rounds - floor(extract(epoch FROM (now() - v_last)))::integer);
  END IF;
  SELECT true, COALESCE(cm.chip_balance, 0) INTO v_member, v_member_chips
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = v_user
     AND COALESCE(cm.status, 'active') IN ('active', 'approved') LIMIT 1;
  v_frozen := public.fn_platform_frozen()
           OR EXISTS (SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope = p_game AND f.cleared_at IS NULL);

  RETURN jsonb_build_object(
    'ok', true, 'available', cfg.enabled, 'game', p_game, 'host_id', v_host, 'host_kind', v_kind, 'club_id', p_club_id,
    'config', jsonb_build_object(
      'diamonds_per_chip', v_rate, 'min_bet_diamonds', cfg.min_bet_diamonds, 'max_bet_diamonds', cfg.max_bet_diamonds,
      'exposure_allowance_chips', cfg.exposure_allowance_chips, 'cap_fraction', cfg.cap_fraction,
      'max_multiplier_cents', cfg.max_multiplier_cents, 'growth_k', cfg.growth_k,
      'purchased_only', cfg.purchased_only, 'max_rounds_per_player_per_day', cfg.max_rounds_per_player_per_day,
      'min_seconds_between_rounds', cfg.min_seconds_between_rounds, 'spec_rtp', 0.800000, 'house_share', 0.200000),
    'bets', COALESCE(v_bets, '[]'::jsonb),
    'tables', COALESCE(v_tables, '[]'::jsonb),
    'open_round', v_open,
    'pool', jsonb_build_object(
      'rounds', COALESCE(pool.rounds, 0), 'intake_diamonds', COALESCE(pool.intake_diamonds, 0),
      'chips_minted', COALESCE(pool.chips_minted, 0), 'chips_paid', COALESCE(pool.chips_paid, 0),
      'reserved_chips', COALESCE(pool.reserved_chips, 0),
      'headroom_chips', COALESCE(pool.chips_minted, 0) + cfg.exposure_allowance_chips - COALESCE(pool.chips_paid, 0) - COALESCE(pool.reserved_chips, 0),
      'realized_rtp', CASE WHEN COALESCE(pool.intake_diamonds, 0) > 0
                           THEN round(COALESCE(pool.chips_paid, 0) / (pool.intake_diamonds::numeric / v_rate), 4) END),
    'player', jsonb_build_object(
      'diamonds', v_diamonds, 'purchased_available', v_purchased, 'spendable', v_spendable,
      'rounds_today', v_today, 'seconds_until_next', v_wait,
      'is_member', COALESCE(v_member, false), 'member_chips', v_member_chips),
    'frozen', v_frozen);
END $$;


ALTER FUNCTION public.fn_diamond_game_state(p_club_id uuid, p_game text) OWNER TO postgres;

--
-- Name: fn_diamond_game_take_bet(uuid, integer, boolean, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_take_bet(p_user uuid, p_bet integer, p_purchased_only boolean, p_type text, p_description text, p_reference text, p_meta jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_deduct jsonb; v_remaining integer; v_take integer; v_lot record;
BEGIN
  v_deduct := public.deduct_diamonds(p_user, p_bet, p_description, p_type, p_type, p_meta, p_reference, 0);
  IF COALESCE((v_deduct->>'success')::boolean, false) = false THEN
    RETURN v_deduct;
  END IF;
  IF p_purchased_only THEN
    v_remaining := p_bet;
    FOR v_lot IN SELECT * FROM public.diamond_purchase_lots l
                  WHERE l.user_id = p_user AND l.frozen_at IS NULL
                    AND (l.issued - l.consumed - l.refunded) > 0
                  ORDER BY l.created_at, l.id FOR UPDATE LOOP
      EXIT WHEN v_remaining <= 0;
      v_take := LEAST(v_remaining, v_lot.issued - v_lot.consumed - v_lot.refunded);
      UPDATE public.diamond_purchase_lots SET consumed = consumed + v_take WHERE id = v_lot.id;
      v_remaining := v_remaining - v_take;
    END LOOP;
    IF v_remaining > 0 THEN
      RAISE EXCEPTION 'diamond games: purchased lots could not cover the bet (% short) after the availability check passed', v_remaining;
    END IF;
  END IF;
  RETURN v_deduct;
END $$;


ALTER FUNCTION public.fn_diamond_game_take_bet(p_user uuid, p_bet integer, p_purchased_only boolean, p_type text, p_description text, p_reference text, p_meta jsonb) OWNER TO postgres;

--
-- Name: fn_diamond_purchase_dispute(uuid, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_purchase_dispute(p_purchase_id uuid, p_dispute_id text, p_event text, p_amount_cents integer, p_evidence_due_by timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_purchase public.diamond_purchases%ROWTYPE;
  v_charge_cents integer; v_claimed integer; v_reversal jsonb; v_frozen integer := 0; v_withdrawn jsonb;
BEGIN
  IF p_purchase_id IS NULL OR COALESCE(p_dispute_id, '') = '' OR COALESCE(p_event, '') = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
  END IF;
  IF p_event NOT IN ('charge.dispute.created', 'charge.dispute.funds_withdrawn',
                     'charge.dispute.closed:won', 'charge.dispute.closed:lost') THEN
    RETURN jsonb_build_object('success', false, 'error', 'unsupported_event', 'event', p_event);
  END IF;
  SELECT * INTO v_purchase FROM public.diamond_purchases WHERE id = p_purchase_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'purchase_not_found'); END IF;

  INSERT INTO public.diamond_purchase_disputes (dispute_id, event, purchase_id, amount_cents)
  VALUES (p_dispute_id, p_event, p_purchase_id, p_amount_cents)
  ON CONFLICT (dispute_id, event) DO NOTHING;
  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 0 THEN
    RETURN jsonb_build_object('success', true, 'duplicate', true, 'event', p_event,
      'purchase_id', p_purchase_id, 'dispute_id', p_dispute_id);
  END IF;

  IF p_event = 'charge.dispute.created' THEN
    UPDATE public.diamond_purchase_lots SET frozen_at = COALESCE(frozen_at, now()) WHERE purchase_id = p_purchase_id;
    GET DIAGNOSTICS v_frozen = ROW_COUNT;
    BEGIN
      PERFORM public.fn_ca_diamond_incident('DR10:dispute_opened', 'critical', v_purchase.user_id,
        COALESCE(v_purchase.diamonds_amount, 0) + COALESCE(v_purchase.bonus_diamonds, 0),
        'fn_diamond_purchase_dispute',
        jsonb_build_object('purchase_id', p_purchase_id, 'dispute_id', p_dispute_id, 'amount_cents', p_amount_cents,
          'lots_frozen', v_frozen, 'evidence_due_by', p_evidence_due_by,
          'note', CASE WHEN p_evidence_due_by IS NULL
                       THEN 'Stripe sent no evidence deadline with this event; check the dispute in the Stripe dashboard. A dispute lost by silence is a money defect (D10).'
                       ELSE 'Submit evidence before evidence_due_by or the dispute is lost by default (D10).' END));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('success', true, 'event', p_event, 'purchase_id', p_purchase_id,
      'lots_frozen', v_frozen, 'evidence_due_by', p_evidence_due_by);

  ELSIF p_event = 'charge.dispute.funds_withdrawn' THEN
    v_charge_cents := round(COALESCE(v_purchase.price_usd, 0) * 100)::integer;
    IF v_charge_cents <= 0 THEN
      BEGIN
        PERFORM public.fn_ca_diamond_incident('DR10:dispute_charge_amount_unknown', 'critical', v_purchase.user_id, NULL,
          'fn_diamond_purchase_dispute',
          jsonb_build_object('purchase_id', p_purchase_id, 'dispute_id', p_dispute_id, 'price_usd', v_purchase.price_usd,
            'note', 'The purchase row carries no usable price, so the pro-rata reversal cannot be computed. Reversed nothing.'));
      EXCEPTION WHEN OTHERS THEN NULL; END;
      RETURN jsonb_build_object('success', false, 'error', 'charge_amount_unknown', 'purchase_id', p_purchase_id);
    END IF;
    v_reversal := public.fn_diamond_purchase_refund(
      p_purchase_id, v_charge_cents, LEAST(COALESCE(p_amount_cents, v_charge_cents), v_charge_cents));
    BEGIN
      PERFORM public.fn_ca_diamond_incident('DR10:dispute_funds_withdrawn', 'critical', v_purchase.user_id,
        COALESCE((v_reversal ->> 'refunded_diamonds')::integer, 0), 'fn_diamond_purchase_dispute',
        jsonb_build_object('purchase_id', p_purchase_id, 'dispute_id', p_dispute_id, 'charge_cents', v_charge_cents,
          'withdrawn_cents', p_amount_cents, 'reversal', v_reversal));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('success', true, 'event', p_event, 'purchase_id', p_purchase_id, 'reversal', v_reversal);

  ELSIF p_event = 'charge.dispute.closed:won' THEN
    UPDATE public.diamond_purchase_lots SET frozen_at = NULL WHERE purchase_id = p_purchase_id;
    GET DIAGNOSTICS v_frozen = ROW_COUNT;
    SELECT to_jsonb(d) INTO v_withdrawn FROM public.diamond_purchase_disputes d
     WHERE d.dispute_id = p_dispute_id AND d.event = 'charge.dispute.funds_withdrawn';
    BEGIN
      -- Review R2-10: a win AFTER funds were withdrawn means the player is short what they paid for.
      -- Money owed to a player is filed critical so the daily sweep sees it (CLAUDE.md 10.9 decides it).
      PERFORM public.fn_ca_diamond_incident('DR10:dispute_closed_won',
        CASE WHEN v_withdrawn IS NULL THEN 'info' ELSE 'critical' END, v_purchase.user_id,
        CASE WHEN v_withdrawn IS NULL THEN NULL ELSE COALESCE(v_purchase.refunded_diamonds, 0) END,
        'fn_diamond_purchase_dispute',
        jsonb_build_object('purchase_id', p_purchase_id, 'dispute_id', p_dispute_id, 'lots_unfrozen', v_frozen,
          'reversal_before_win', v_withdrawn,
          'note', CASE WHEN v_withdrawn IS NULL THEN 'Dispute won; nothing had been reversed. The lot is spendable again.'
                       ELSE 'Dispute won AFTER funds_withdrawn reversed the grant: Stripe returns the funds and the player is owed the reversed diamonds. Re-credit through the Mint (class purchased) under a four-eyes adjustment.' END));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('success', true, 'event', p_event, 'purchase_id', p_purchase_id,
      'lots_unfrozen', v_frozen, 'player_owed', v_withdrawn IS NOT NULL);

  ELSE
    BEGIN
      PERFORM public.fn_ca_diamond_incident('DR10:dispute_closed_lost', 'info', v_purchase.user_id, NULL,
        'fn_diamond_purchase_dispute',
        jsonb_build_object('purchase_id', p_purchase_id, 'dispute_id', p_dispute_id,
          'note', 'Dispute lost. Any reversal booked by funds_withdrawn stands and the lot stays frozen.'));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('success', true, 'event', p_event, 'purchase_id', p_purchase_id, 'reversal_stands', true);
  END IF;
END;
$$;


ALTER FUNCTION public.fn_diamond_purchase_dispute(p_purchase_id uuid, p_dispute_id text, p_event text, p_amount_cents integer, p_evidence_due_by timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_diamond_purchase_refund(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_purchase_refund(p_purchase_id uuid, p_charge_amount_cents integer, p_refunded_amount_cents integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_purchase public.diamond_purchases%ROWTYPE; v_profile public.profiles%ROWTYPE;
  v_total integer; v_cumulative integer; v_target integer; v_delta integer; v_full boolean;
  v_intent jsonb; v_redemption jsonb; v_unwind jsonb; v_wallet jsonb;
  v_unwind_state text := 'not_requested'; v_balance integer; v_daily_cost integer := 150;
  v_available integer; v_applied integer := 0; v_shortfall integer := 0;
BEGIN
  IF p_charge_amount_cents IS NULL OR p_charge_amount_cents <= 0
     OR p_refunded_amount_cents IS NULL OR p_refunded_amount_cents < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_refund_amount');
  END IF;
  SELECT * INTO v_purchase FROM public.diamond_purchases WHERE id = p_purchase_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'purchase_not_found'); END IF;
  v_cumulative := GREATEST(COALESCE(v_purchase.refunded_amount_cents, 0),
    LEAST(p_charge_amount_cents, p_refunded_amount_cents));
  v_full := v_cumulative >= p_charge_amount_cents;

  IF v_purchase.status = 'refunded'
     AND COALESCE((v_purchase.metadata ->> 'refund_before_settlement')::boolean, false) THEN
    UPDATE public.diamond_purchases SET refunded_amount_cents = v_cumulative, updated_at = now()
     WHERE id = v_purchase.id;
    RETURN jsonb_build_object('success', true, 'duplicate', true, 'fully_refunded', true,
      'terminal_refund', true, 'refunded_diamonds', 0,
      'new_balance', (SELECT COALESCE(diamonds, diamond_balance, 0) FROM public.profiles WHERE id = v_purchase.user_id));
  END IF;
  IF v_purchase.status = 'pending' THEN
    IF NOT v_full THEN RETURN jsonb_build_object('success', false, 'error', 'settlement_pending'); END IF;
    UPDATE public.diamond_purchases
       SET status = 'refunded', refunded_amount_cents = v_cumulative, refunded_diamonds = 0,
           refunded_at = COALESCE(refunded_at, now()),
           metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('refund_before_settlement', true),
           updated_at = now()
     WHERE id = v_purchase.id;
    RETURN jsonb_build_object('success', true, 'fully_refunded', true, 'terminal_refund', true,
      'refunded_diamonds', 0,
      'new_balance', (SELECT COALESCE(diamonds, diamond_balance, 0) FROM public.profiles WHERE id = v_purchase.user_id));
  END IF;
  IF v_purchase.status NOT IN ('completed', 'refunded') THEN
    RETURN jsonb_build_object('success', false, 'error', 'purchase_not_settled');
  END IF;

  SELECT * INTO v_profile FROM public.profiles WHERE id = v_purchase.user_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'profile_not_found'); END IF;
  v_total := COALESCE(v_purchase.diamonds_amount, 0) + COALESCE(v_purchase.bonus_diamonds, 0);
  v_target := GREATEST(COALESCE(v_purchase.refunded_diamonds, 0),
    LEAST(v_total, round(v_total::numeric * v_cumulative / p_charge_amount_cents)::integer));
  v_delta := GREATEST(0, v_target - COALESCE(v_purchase.refunded_diamonds, 0));
  v_intent := COALESCE(v_purchase.metadata -> 'redemption_intent', '{}'::jsonb);
  v_redemption := COALESCE(v_purchase.metadata -> 'redemption_result', '{}'::jsonb);
  IF v_full AND COALESCE(v_purchase.metadata ->> 'redemption_status', '') = 'completed'
     AND COALESCE(v_purchase.metadata ->> 'redemption_refund_status', '') NOT IN ('revoked', 'debt_recorded') THEN
    IF v_intent ->> 'kind' = 'club_shop' AND v_redemption ? 'purchase_id' THEN
      v_unwind := public.fn_refund_shop_purchase((v_intent ->> 'club_id')::uuid,
        (v_redemption ->> 'purchase_id')::uuid, v_purchase.user_id,
        'Card-funded Club Shop purchase reversed by Stripe refund');
      v_unwind_state := CASE WHEN COALESCE((v_unwind ->> 'success')::boolean, false) THEN 'revoked' ELSE 'debt_recorded' END;
    ELSIF v_intent ->> 'kind' = 'vip_daily' THEN
      IF v_profile.vip_tier = 'daily' AND v_profile.vip_expires_at IS NOT NULL
         AND v_redemption ? 'expires_at'
         AND abs(extract(epoch FROM (v_profile.vip_expires_at - (v_redemption ->> 'expires_at')::timestamptz))) < 2 THEN
        UPDATE public.profiles SET vip_expires_at = GREATEST(now(), vip_expires_at - interval '1 day'),
          is_vip = (vip_expires_at - interval '1 day') > now(), updated_at = now()
         WHERE id = v_purchase.user_id;
        v_wallet := public.add_diamonds_to_balance(v_purchase.user_id, v_daily_cost, 'refund',
          'Reversed card-funded VIP Daily Pass', 'card-redemption-refund:' || v_purchase.id::text);
        IF COALESCE((v_wallet ->> 'success')::boolean, false) IS NOT TRUE
           AND COALESCE((v_wallet ->> 'duplicate')::boolean, false) IS NOT TRUE THEN
          RAISE EXCEPTION 'daily_redemption_refund_failed:%', COALESCE(v_wallet ->> 'error', 'unknown');
        END IF;
        v_unwind_state := 'revoked';
      ELSE v_unwind_state := 'debt_recorded'; END IF;
    END IF;
  END IF;

  IF v_delta > 0 THEN
    SELECT COALESCE(diamonds, diamond_balance, 0) INTO v_available FROM public.profiles WHERE id = v_purchase.user_id;
    v_available := GREATEST(COALESCE(v_available, 0), 0);
    v_applied := LEAST(v_delta, v_available);
    v_shortfall := v_delta - v_applied;

    IF v_applied > 0 THEN
      UPDATE public.profiles
         SET diamonds = COALESCE(diamonds, diamond_balance, 0) - v_applied,
             diamond_balance = COALESCE(diamonds, diamond_balance, 0) - v_applied, updated_at = now()
       WHERE id = v_purchase.user_id RETURNING diamonds INTO v_balance;
    ELSE
      v_balance := v_available;
    END IF;

    IF v_shortfall > 0 THEN
      INSERT INTO public.diamond_debts (user_id, purchase_id, amount, reason)
      VALUES (v_purchase.user_id, v_purchase.id, v_shortfall, 'chargeback_exceeds_balance');
      BEGIN
        PERFORM public.fn_ca_diamond_incident('DR1:chargeback_exceeds_balance', 'critical', v_purchase.user_id, v_shortfall,
          'fn_diamond_purchase_refund',
          jsonb_build_object('purchase_id', v_purchase.id, 'reversal_owed', v_delta, 'balance_applied', v_applied,
                             'debt_booked', v_shortfall, 'balance_after', v_balance));
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;

    INSERT INTO public.diamond_transactions(user_id,type,amount,balance_after,description,
      reference_id,transaction_type,source,metadata,counterparty,issuance_class)
    VALUES (v_purchase.user_id,'refund',-v_applied,v_balance,'Stripe refund',
      'diamond-refund:' || v_purchase.id::text || ':' || v_target,'refund','stripe',
      jsonb_build_object('purchase_id',v_purchase.id,'chargeback_debt',v_shortfall > 0,
        'reversal_owed',v_delta,'balance_applied',v_applied,'debt_booked',v_shortfall),
      'purchase_clearing','refund');

    -- DR9: the lot carries what was reversed. A failure here is loud (review R2-13), never fatal.
    BEGIN
      UPDATE public.diamond_purchase_lots
         SET refunded = LEAST(issued - consumed, GREATEST(refunded, v_target))
       WHERE purchase_id = v_purchase.id;
    EXCEPTION WHEN OTHERS THEN
      BEGIN
        PERFORM public.fn_ca_diamond_incident('DR9:purchase_lot_write_failed', 'critical', v_purchase.user_id, v_target,
          'fn_diamond_purchase_refund',
          jsonb_build_object('purchase_id', v_purchase.id, 'sqlstate', SQLSTATE, 'sqlerrm', SQLERRM, 'target', v_target));
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END;
  ELSE
    SELECT COALESCE(diamonds, diamond_balance, 0) INTO v_balance FROM public.profiles WHERE id = v_purchase.user_id;
  END IF;
  UPDATE public.diamond_purchases
     SET refunded_amount_cents = v_cumulative, refunded_diamonds = v_target,
         refunded_at = CASE WHEN v_full THEN COALESCE(refunded_at,now()) ELSE refunded_at END,
         status = CASE WHEN v_full THEN 'refunded' ELSE status END,
         metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object(
           'redemption_refund_status',v_unwind_state,'refund_balance_after',v_balance,
           'chargeback_debt',v_shortfall > 0,'chargeback_debt_amount',v_shortfall,
           'refunded_diamonds',v_target), updated_at=now()
   WHERE id=v_purchase.id;
  RETURN jsonb_build_object('success',true,'fully_refunded',v_full,'refunded_diamonds',v_target,
    'new_balance',v_balance,'redemption_refund_status',v_unwind_state,
    'chargeback_debt',v_shortfall > 0,'chargeback_debt_amount',v_shortfall,'balance_applied',v_applied);
END;
$$;


ALTER FUNCTION public.fn_diamond_purchase_refund(p_purchase_id uuid, p_charge_amount_cents integer, p_refunded_amount_cents integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_diamond_purchase_refund(p_purchase_id uuid, p_charge_amount_cents integer, p_refunded_amount_cents integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_diamond_purchase_refund(p_purchase_id uuid, p_charge_amount_cents integer, p_refunded_amount_cents integer) IS 'The live Stripe refund and chargeback handler for a diamond purchase: pro-rata reversal, redemption unwind, clamp at the balance, remainder to diamond_debts (DR1, DR9). Renamed from reconcile_diamond_purchase_refund 2026-09-07.';


--
-- Name: fn_diamond_side_tables_follow_profiles(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_side_tables_follow_profiles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_delta bigint := CASE WHEN TG_OP = 'INSERT'
                         THEN COALESCE(NEW.diamonds, 0)
                         ELSE COALESCE(NEW.diamonds, 0) - COALESCE(OLD.diamonds, 0) END;
BEGIN
  IF TG_OP <> 'INSERT' AND v_delta = 0 THEN RETURN NEW; END IF;
  BEGIN
    INSERT INTO public.user_diamonds (user_id, balance, lifetime_earned, lifetime_spent, created_at, updated_at)
    VALUES (NEW.id, GREATEST(COALESCE(NEW.diamonds, 0), 0), GREATEST(v_delta, 0), GREATEST(-v_delta, 0), now(), now())
    ON CONFLICT (user_id) DO UPDATE
      SET balance = GREATEST(COALESCE(NEW.diamonds, 0), 0),
          lifetime_earned = public.user_diamonds.lifetime_earned + GREATEST(v_delta, 0),
          lifetime_spent  = public.user_diamonds.lifetime_spent  + GREATEST(-v_delta, 0),
          updated_at = now();
    INSERT INTO public.user_diamond_balance (user_id, balance, lifetime_earned, lifetime_spent, created_at, updated_at)
    VALUES (NEW.id, GREATEST(COALESCE(NEW.diamonds, 0), 0)::int, GREATEST(v_delta, 0)::int, GREATEST(-v_delta, 0)::int, now(), now())
    ON CONFLICT (user_id) DO UPDATE
      SET balance = GREATEST(COALESCE(NEW.diamonds, 0), 0)::int,
          lifetime_earned = public.user_diamond_balance.lifetime_earned + GREATEST(v_delta, 0)::int,
          lifetime_spent  = public.user_diamond_balance.lifetime_spent  + GREATEST(-v_delta, 0)::int,
          updated_at = now();
    INSERT INTO public.diamond_wallets (user_id, balance, lifetime_earned, lifetime_spent, updated_at)
    VALUES (NEW.id, GREATEST(COALESCE(NEW.diamonds, 0), 0)::int, GREATEST(v_delta, 0)::int, GREATEST(-v_delta, 0)::int, now())
    ON CONFLICT (user_id) DO UPDATE
      SET balance = GREATEST(COALESCE(NEW.diamonds, 0), 0)::int,
          lifetime_earned = COALESCE(public.diamond_wallets.lifetime_earned, 0) + GREATEST(v_delta, 0)::int,
          lifetime_spent  = COALESCE(public.diamond_wallets.lifetime_spent, 0)  + GREATEST(-v_delta, 0)::int,
          updated_at = now();
  EXCEPTION WHEN OTHERS THEN
    -- A mirror is a mirror: it must never be able to refuse the thing it mirrors (2026-09-07 review
    -- D10: the two side tables carry FKs to auth.users and the seeder inserts the profile first).
    PERFORM public.fn_ca_diamond_incident('DR10:mirror_write_failed', 'warning', NEW.id, NEW.diamonds,
      'fn_diamond_side_tables_follow_profiles',
      jsonb_build_object('sqlstate', SQLSTATE, 'sqlerrm', SQLERRM, 'tg_op', TG_OP));
  END;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_diamond_side_tables_follow_profiles() OWNER TO postgres;

--
-- Name: FUNCTION fn_diamond_side_tables_follow_profiles(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_diamond_side_tables_follow_profiles() IS 'Keeps user_diamonds, user_diamond_balance and diamond_wallets equal to profiles.diamonds. Fires on INSERT as well as UPDATE since 2026-09-07: before that a profile only got its mirror rows the first time its balance changed, so one born with 500 and never touched had none at all and the DR10 mirror check reported it every hour for 94 hours.';


--
-- Name: fn_discover_clubs(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_discover_clubs(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, name text, description text, avatar_url text, member_count integer, online_count integer, game_types text[], is_public boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        c.id,
        c.name,
        c.description,
        c.avatar_url,
        COALESCE(c.member_count, 0)::INTEGER as member_count,
        COALESCE(c.online_count, 0)::INTEGER as online_count,
        c.game_types,
        COALESCE(c.is_public, true) as is_public,
        c.created_at
    FROM clubs c
    WHERE c.is_public = true
    AND (p_search IS NULL OR c.name ILIKE '%' || p_search || '%')
    ORDER BY c.member_count DESC NULLS LAST
    LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.fn_discover_clubs(p_search text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_dismiss_club_message(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_dismiss_club_message(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_revision bigint;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  -- The revision is read from the club, never accepted from the caller. A
  -- client that sent its own number could dismiss a revision that has not
  -- happened yet and silence every future message for that person.
  SELECT c.message_revision INTO v_revision
    FROM public.clubs c WHERE c.id = p_club_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'club_not_found');
  END IF;

  INSERT INTO public.club_message_dismissals AS d (user_id, club_id, dismissed_revision)
  VALUES (v_uid, p_club_id, COALESCE(v_revision, 0))
  ON CONFLICT (user_id, club_id) DO UPDATE
    -- GREATEST, not assignment: two tabs racing must not move a dismissal
    -- BACKWARDS and resurrect a message the person already retired.
    SET dismissed_revision = GREATEST(d.dismissed_revision, EXCLUDED.dismissed_revision),
        dismissed_at       = now();

  RETURN jsonb_build_object('ok', true, 'dismissed_revision', COALESCE(v_revision, 0));
END;
$$;


ALTER FUNCTION public.fn_dismiss_club_message(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_dispute_escalate(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_dispute_escalate(p_dispute_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club   uuid;
  v_status text;
BEGIN
  SELECT d.club_id, coalesce(d.status, 'open') INTO v_club, v_status
    FROM disputes d WHERE d.id = p_dispute_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'dispute not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT fn_ca_can_review_integrity(v_club) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;
  IF v_status IN ('resolved', 'escalated') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_' || v_status, 'status', v_status);
  END IF;

  UPDATE disputes
     SET status = 'escalated',
         assigned_to = coalesce(assigned_to, auth.uid()),
         resolution = coalesce(nullif(btrim(coalesce(p_note, '')), ''), resolution),
         updated_at = now()
   WHERE id = p_dispute_id;

  RETURN jsonb_build_object('ok', true, 'status', 'escalated');
END;
$$;


ALTER FUNCTION public.fn_dispute_escalate(p_dispute_id uuid, p_note text) OWNER TO postgres;

--
-- Name: fn_dispute_start_review(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_dispute_start_review(p_dispute_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club   uuid;
  v_status text;
BEGIN
  SELECT d.club_id, coalesce(d.status, 'open') INTO v_club, v_status
    FROM disputes d WHERE d.id = p_dispute_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'dispute not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT fn_ca_can_review_integrity(v_club) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;
  IF v_status <> 'open' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_open', 'status', v_status);
  END IF;

  UPDATE disputes
     SET status = 'under_review',
         assigned_to = auth.uid(),
         updated_at = now()
   WHERE id = p_dispute_id;

  RETURN jsonb_build_object('ok', true, 'status', 'under_review', 'assigned_to', auth.uid());
END;
$$;


ALTER FUNCTION public.fn_dispute_start_review(p_dispute_id uuid) OWNER TO postgres;

--
-- Name: fn_drain_daily_challenge_event_outbox(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_drain_daily_challenge_event_outbox(p_limit integer DEFAULT 500, p_shard integer DEFAULT 0, p_shards integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  r record;
  v_done integer := 0;
  v_skipped integer := 0;
  -- The cron gives this call the role's statement_timeout; the budget keeps
  -- it well inside that and lets four shards run every minute without ever
  -- overlapping themselves.
  c_budget CONSTANT interval := interval '45 seconds';
  v_deadline timestamptz := clock_timestamp() + c_budget;
BEGIN
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 5000 THEN
    RAISE EXCEPTION 'Invalid outbox batch size';
  END IF;
  -- The shard count is inlined into the query text below so the expression
  -- index can match it, so it may only ever be one of these.
  IF p_shards IS NULL OR p_shards NOT IN (1, 2, 4, 8)
     OR p_shard IS NULL OR p_shard < 0 OR p_shard >= p_shards THEN
    RAISE EXCEPTION 'Invalid outbox shard %/%', p_shard, p_shards;
  END IF;
  -- One worker per shard at a time.
  IF NOT pg_try_advisory_xact_lock(
    hashtextextended('daily-missions-event-outbox-drain', p_shard)
  ) THEN
    RETURN 0;
  END IF;
  -- Never wait long on a player who is being seated right now; the patience
  -- for a row that has already lost races is raised per event below.
  PERFORM set_config('lock_timeout', '250ms', true);

  FOR r IN EXECUTE format(
    $q$
    SELECT *
      FROM public.daily_challenge_event_outbox
     WHERE dead_lettered_at IS NULL
       AND (
         occurred_at < now() - interval '35 days'
         OR next_attempt_at <= now()
       )
       AND (hashtext(user_id::text) & 2147483647) %% %s = %s
     ORDER BY user_id, created_at, event_key
     LIMIT %s
    $q$, p_shards, p_shard, p_limit)
  LOOP
    EXIT WHEN clock_timestamp() >= v_deadline;
    -- Each event in its own subtransaction: a deadlock or a lock timeout on
    -- one user's lock (a hand of theirs settling, or a seat being taken)
    -- skips that event to the next run instead of aborting the shard.
    BEGIN
      -- A row that keeps losing the race waits longer, so it cannot be
      -- starved for ever by a queue of short transactions.
      PERFORM set_config('lock_timeout',
                         CASE WHEN COALESCE(r.attempts, 0) >= 3 THEN '3s' ELSE '250ms' END,
                         true);
      PERFORM public.fn_lock_daily_mission_user(r.user_id);
      IF r.occurred_at < now() - interval '35 days' THEN
        UPDATE public.daily_challenge_event_outbox
        SET dead_lettered_at = now(),
            last_error = left(
              COALESCE(last_error || '; ', '')
                || 'Authoritative event exceeded 35-day replay horizon',
              1000
            )
        WHERE user_id = r.user_id
          AND event_key = r.event_key
          AND dead_lettered_at IS NULL
          AND occurred_at < now() - interval '35 days';
      ELSE
        IF public.enqueue_daily_challenge_event(
          r.user_id,
          r.event_key,
          r.amounts,
          r.magnitudes,
          r.threshold_values,
          r.occurred_at
        ) THEN
          v_done := v_done + 1;
        END IF;
      END IF;
    EXCEPTION
      WHEN deadlock_detected OR lock_not_available OR serialization_failure THEN
        v_skipped := v_skipped + 1;
        -- WRITE THE SKIP DOWN. Without this the row looked untouched and was
        -- retried into the same contention on every run, invisibly.
        UPDATE public.daily_challenge_event_outbox
           SET attempts = attempts + 1,
               last_error = left('Skipped on lock contention at ' || now()::text
                                 || ' (the player was locked by another transaction)', 1000),
               next_attempt_at = now() + LEAST(GREATEST(attempts + 1, 1) * interval '10 seconds',
                                               interval '1 minute')
         WHERE user_id = r.user_id
           AND event_key = r.event_key;
    END;
  END LOOP;

  IF v_skipped > 0 THEN
    RAISE NOTICE 'daily missions outbox shard %/%: booked %, skipped % on lock contention (retried next minute)',
      p_shard, p_shards, v_done, v_skipped;
  END IF;
  RETURN v_done;
END;
$_$;


ALTER FUNCTION public.fn_drain_daily_challenge_event_outbox(p_limit integer, p_shard integer, p_shards integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_drain_daily_challenge_event_outbox(p_limit integer, p_shard integer, p_shards integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_drain_daily_challenge_event_outbox(p_limit integer, p_shard integer, p_shards integer) IS 'Books queued Daily Missions events through enqueue_daily_challenge_event, oldest first per user, for the users whose hash falls in shard p_shard of p_shards (inlined so the expression index matches), until p_limit rows or a 45s budget. Sets a 250ms lock_timeout so a player being seated is skipped to the next run rather than waited on. Four shards run every minute.';


--
-- Name: fn_drain_daily_mission_reset_notifications(date, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_drain_daily_mission_reset_notifications(p_cycle_date date DEFAULT ((now() AT TIME ZONE 'UTC'::text))::date, p_batch_size integer DEFAULT 5000, p_max_batches integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_inserted integer;
  v_total integer := 0;
  v_batch integer := 0;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'service role required';
  END IF;
  IF p_cycle_date IS NULL THEN
    RAISE EXCEPTION 'p_cycle_date is required';
  END IF;
  IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 5000 THEN
    RAISE EXCEPTION 'p_batch_size must be between 1 and 5000';
  END IF;
  IF p_max_batches IS NULL OR p_max_batches NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'p_max_batches must be between 1 and 100';
  END IF;

  IF NOT pg_try_advisory_xact_lock(
    hashtextextended('daily-mission-reset-alerts:' || p_cycle_date::text, 0)
  ) THEN
    RETURN 0;
  END IF;

  LOOP
    EXIT WHEN v_batch >= p_max_batches;
    v_batch := v_batch + 1;
    v_inserted := public.enqueue_daily_mission_reset_notifications(
      p_cycle_date,
      p_batch_size
    );
    v_total := v_total + v_inserted;
    EXIT WHEN v_inserted < p_batch_size;
  END LOOP;

  RETURN v_total;
END;
$$;


ALTER FUNCTION public.fn_drain_daily_mission_reset_notifications(p_cycle_date date, p_batch_size integer, p_max_batches integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_drain_daily_mission_reset_notifications(p_cycle_date date, p_batch_size integer, p_max_batches integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_drain_daily_mission_reset_notifications(p_cycle_date date, p_batch_size integer, p_max_batches integer) IS 'Engine-only bounded reset-alert drain. Up to 100 batches of 5,000 cover more than 5,000 opt-ins without an unbounded transaction loop.';


--
-- Name: fn_effective_bbj_drop(numeric, integer, boolean, uuid, uuid, text, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_effective_bbj_drop(p_bb numeric, p_players_dealt integer, p_saw_flop boolean, p_club_id uuid, p_table_id uuid DEFAULT NULL::uuid, p_variant text DEFAULT 'nlh'::text, p_sb numeric DEFAULT NULL::numeric, p_pot numeric DEFAULT NULL::numeric, p_rake numeric DEFAULT NULL::numeric) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  r        public.ca_rake_rules%ROWTYPE;
  v_fee_bb numeric;
  v_fee    numeric;
  v_tblpct numeric := 100;
  v_over   numeric;
BEGIN
  SELECT * INTO r FROM public.ca_rake_rules WHERE id = 1;

  IF lower(COALESCE(p_variant, 'nlh')) = ANY (r.bbj_ineligible_variants) THEN RETURN 0; END IF;
  IF NOT COALESCE(p_saw_flop, false) THEN RETURN 0; END IF;
  IF COALESCE(p_players_dealt, 0) < r.bbj_min_players_dealt THEN RETURN 0; END IF;

  IF p_table_id IS NOT NULL THEN
    SELECT COALESCE(t.bbj_percent, 100) INTO v_tblpct FROM public.tables t WHERE t.id = p_table_id;
    IF NOT COALESCE(v_tblpct, 100) > 0 THEN RETURN 0; END IF;
  END IF;

  SELECT p.bbj_fee_bb INTO v_fee_bb FROM public.fn_rake_stake_price(p_bb, p_sb) p;
  IF v_fee_bb IS NULL THEN
    SELECT t.bbj_fee_bb INTO v_fee_bb FROM public.fn_rake_tier_price(p_bb) t;
  END IF;
  v_fee := round(p_bb * COALESCE(v_fee_bb, 0), 2);

  IF p_pot IS NOT NULL AND p_rake IS NOT NULL AND p_rake + v_fee > p_pot THEN
    v_over := round(p_rake + v_fee - p_pot, 2);
    v_fee := CASE WHEN v_over <= v_fee THEN round(v_fee - v_over, 2) ELSE 0 END;
  END IF;
  RETURN v_fee;
END;
$$;


ALTER FUNCTION public.fn_effective_bbj_drop(p_bb numeric, p_players_dealt integer, p_saw_flop boolean, p_club_id uuid, p_table_id uuid, p_variant text, p_sb numeric, p_pot numeric, p_rake numeric) OWNER TO postgres;

--
-- Name: fn_effective_rake(numeric, numeric, integer, boolean, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_effective_rake(p_bb numeric, p_pot numeric, p_players_dealt integer, p_saw_flop boolean, p_sb numeric DEFAULT NULL::numeric, p_override_percent numeric DEFAULT NULL::numeric, p_override_cap_bb numeric DEFAULT NULL::numeric) RETURNS TABLE(rake numeric, cap numeric, percent numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  r          public.ca_rake_rules%ROWTYPE;
  v_pct      numeric;
  v_full     numeric;
  v_sched    boolean := false;
  v_cap      numeric;
  v_cap_key  integer;
  v_cap_ovr  boolean := false;
BEGIN
  SELECT * INTO r FROM public.ca_rake_rules WHERE id = 1;

  SELECT p.rake_percent, p.rake_cap, p.scheduled INTO v_pct, v_full, v_sched
    FROM public.fn_rake_stake_price(p_bb, p_sb) p;
  IF v_pct IS NULL THEN
    SELECT t.rake_percent, t.rake_cap INTO v_pct, v_full FROM public.fn_rake_tier_price(p_bb) t;
    v_sched := false;
  END IF;

  IF p_override_percent IS NOT NULL AND p_override_percent >= 0 THEN
    v_pct := LEAST(LEAST(GREATEST(p_override_percent, 0), r.max_rake_percent), v_pct);
  END IF;
  IF p_override_cap_bb IS NOT NULL AND p_override_cap_bb >= 0 THEN
    v_full := LEAST(round(LEAST(GREATEST(p_override_cap_bb, 0), r.max_rake_cap_bb) * p_bb, 2), v_full);
    v_cap_ovr := true;
  END IF;

  IF COALESCE(p_players_dealt, 0) <= 2 THEN
    v_pct := LEAST(v_pct, r.heads_up_percent);
  END IF;

  v_cap := NULL;
  IF v_sched AND NOT v_cap_ovr THEN
    v_cap_key := CASE WHEN COALESCE(p_players_dealt, 0) >= r.short_handed_max_players + 1 THEN 4
                      WHEN p_players_dealt >= r.short_handed_max_players THEN 3
                      WHEN p_players_dealt >= 2 THEN 2
                      ELSE 4 END;
    SELECT c.rake_cap INTO v_cap
      FROM public.ca_rake_schedule_caps c
     WHERE abs(c.bb - p_bb) < 0.001 AND c.players_dealt = v_cap_key AND c.source = 'schedule';
  END IF;
  IF v_cap IS NULL THEN
    v_cap := public.fn_rake_cap_for_dealt(v_full, COALESCE(p_players_dealt, 0));
  END IF;

  IF r.no_flop_no_drop AND NOT COALESCE(p_saw_flop, false) THEN
    RETURN QUERY SELECT 0::numeric, v_cap, v_pct;
  ELSE
    RETURN QUERY SELECT LEAST(round(COALESCE(p_pot, 0) * v_pct, 0) / 100, v_cap), v_cap, v_pct;
  END IF;
END;
$$;


ALTER FUNCTION public.fn_effective_rake(p_bb numeric, p_pot numeric, p_players_dealt integer, p_saw_flop boolean, p_sb numeric, p_override_percent numeric, p_override_cap_bb numeric) OWNER TO postgres;

--
-- Name: fn_effective_rake_cap(numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_effective_rake_cap(p_sb numeric, p_bb numeric) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (SELECT s.rake_cap FROM public.ca_rake_schedule s
      WHERE s.sb = p_sb AND s.bb = p_bb AND s.source = 'engine_mirror'),
    (SELECT LEAST(t.rake_cap, round(p_bb * public.fn_unscheduled_cap_bb(), 2))
       FROM public.ca_rake_tier t
      WHERE t.max_bb IS NULL OR p_bb <= t.max_bb
      ORDER BY t.max_bb ASC NULLS LAST
      LIMIT 1)
  );
$$;


ALTER FUNCTION public.fn_effective_rake_cap(p_sb numeric, p_bb numeric) OWNER TO postgres;

--
-- Name: fn_effective_rake_config(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_effective_rake_config(p_table_id uuid) RETURNS TABLE(table_id uuid, club_name text, source text, effective_percent numeric, effective_cap_bb numeric, note text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT t.id,
         c.name,
         CASE
           WHEN t.rake_percent IS NOT NULL AND t.rake_percent >= 0 THEN 'table override'
           WHEN c.default_rake_percent IS NOT NULL AND c.default_rake_percent >= 0 THEN 'club default'
           ELSE 'engine schedule (RakeConfig.ts)'
         END,
         CASE
           WHEN t.rake_percent IS NOT NULL AND t.rake_percent >= 0 THEN t.rake_percent
           WHEN c.default_rake_percent IS NOT NULL AND c.default_rake_percent >= 0 THEN c.default_rake_percent
           ELSE 10::numeric   -- RAKE_SCHEDULE is 10% at every stake
         END,
         CASE
           WHEN t.rake_cap_bb IS NOT NULL AND t.rake_cap_bb >= 0 THEN t.rake_cap_bb
           WHEN c.rake_cap IS NOT NULL AND c.rake_cap >= 0 THEN c.rake_cap
           ELSE NULL          -- schedule cap is per-stake, in dollars, not BB
         END,
         CASE
           WHEN (t.rake_percent IS NULL OR t.rake_percent < 0)
            AND (c.default_rake_percent IS NULL OR c.default_rake_percent < 0)
           THEN 'Falling through to the hardcoded 10% schedule. clubs.rake_percent='
                || coalesce(c.rake_percent::text,'null')
                || ' is a LEGACY column and is NOT what is being charged.'
           ELSE 'Configured.'
         END
  FROM public.tables t
  LEFT JOIN public.clubs c ON c.id = t.club_id
  WHERE t.id = p_table_id;
$$;


ALTER FUNCTION public.fn_effective_rake_config(p_table_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_effective_rake_config(p_table_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_effective_rake_config(p_table_id uuid) IS 'What rake will ACTUALLY be taken at this table, and where the number came from. Added 2026-08-27 because the clubs table carries two rake column pairs and only one is read.';


--
-- Name: fn_eliminate_player_legacy_candidate_20260907(uuid, uuid, integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_eliminate_player_legacy_candidate_20260907(p_tournament_id uuid, p_user_id uuid, p_position integer, p_prize numeric, p_bubble_refund numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_p public.tournament_players%ROWTYPE;
  v_changed integer;
  v_released_tables uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_position < 2 OR p_prize IS NULL OR p_prize < 0
     OR p_bubble_refund IS NULL OR p_bubble_refund < 0 THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_place_or_prize');
  END IF;
  IF p_bubble_refund <> 0 THEN
    RETURN jsonb_build_object('ok',false,'reason','bubble_refund_requires_finalized_batch');
  END IF;
  SELECT * INTO v_t FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','tournament_not_found'); END IF;
  IF v_t.status <> 'RUNNING' THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_running');
  END IF;
  IF COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
     OR COALESCE(v_t.is_mystery_bounty,false) THEN
    RETURN jsonb_build_object('ok',false,'reason','bounty_requires_outbox_claim');
  END IF;
  SELECT * INTO v_p FROM public.tournament_players
   WHERE tournament_id=p_tournament_id AND user_id=p_user_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','player_not_found'); END IF;
  IF v_p.status = 'winner' THEN
    RETURN jsonb_build_object('ok',false,'reason','player_is_winner');
  END IF;
  IF v_p.status = 'eliminated' THEN
    IF v_p.position IS DISTINCT FROM p_position
       OR round(COALESCE(v_p.prize,0),2) <> round(p_prize,2) THEN
      RETURN jsonb_build_object('ok',false,'reason','elimination_identity_conflict');
    END IF;
    RETURN jsonb_build_object('ok',true,'already',true,'position',v_p.position,'prize',v_p.prize);
  END IF;
  IF v_p.status <> 'playing' OR COALESCE(v_p.chips,0) > 0 THEN
    RETURN jsonb_build_object('ok',false,'reason','not_busted');
  END IF;
  UPDATE public.tournament_players
     SET status='eliminated',position=p_position,prize=round(p_prize,2),eliminated_at=now()
   WHERE tournament_id=p_tournament_id AND user_id=p_user_id
     AND status='playing' AND COALESCE(chips,0)<=0;
  GET DIAGNOSTICS v_changed=ROW_COUNT;
  IF v_changed <> 1 THEN
    RAISE EXCEPTION 'zero-stack elimination CAS changed % rows',v_changed
      USING ERRCODE='serialization_failure';
  END IF;

  WITH released AS (
    UPDATE public.table_seats s SET left_at=now()
      FROM public.tables tb
     WHERE tb.id=s.table_id AND tb.tournament_id=p_tournament_id
       AND s.user_id=p_user_id AND s.left_at IS NULL
    RETURNING s.table_id
  ) SELECT COALESCE(array_agg(DISTINCT table_id),ARRAY[]::uuid[])
      INTO v_released_tables FROM released;
  UPDATE public.tables tb SET current_players=(
    SELECT count(*) FROM public.table_seats s WHERE s.table_id=tb.id AND s.left_at IS NULL)
   WHERE tb.id=ANY(v_released_tables);
  PERFORM public.fn_sync_seat_first_player_count(p_tournament_id);

  RETURN jsonb_build_object('ok',true,'claimed',true,'position',p_position,
                            'prize',round(p_prize,2),'bubble_refund',0);
END;
$$;


ALTER FUNCTION public.fn_eliminate_player_legacy_candidate_20260907(p_tournament_id uuid, p_user_id uuid, p_position integer, p_prize numeric, p_bubble_refund numeric) OWNER TO postgres;

--
-- Name: fn_eliminate_tournament_player_atomic(uuid, uuid, integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_eliminate_tournament_player_atomic(p_tournament_id uuid, p_user_id uuid, p_position integer, p_prize numeric, p_bubble_refund numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_token uuid;
  v_result jsonb;
  v_live_seats integer;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'tournament elimination requires service authority'
      USING ERRCODE='28000';
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  PERFORM 1 FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN public.fn_eliminate_tournament_player_atomic_pre_seat_guard(
      p_tournament_id,p_user_id,p_position,p_prize,p_bubble_refund);
  END IF;
  PERFORM 1 FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN public.fn_eliminate_tournament_player_atomic_pre_seat_guard(
      p_tournament_id,p_user_id,p_position,p_prize,p_bubble_refund);
  END IF;
  SELECT count(*) INTO v_live_seats
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_user_id AND s.left_at IS NULL;
  IF v_live_seats>1 THEN
    RAISE EXCEPTION
      'tournament elimination refuses % live seats for one player',v_live_seats
      USING ERRCODE='P0404';
  END IF;
  v_token:=public.fn_ca_open_tournament_seat_exit_authority(
    p_tournament_id,'elimination',p_user_id);
  BEGIN
    v_result:=public.fn_eliminate_tournament_player_atomic_pre_seat_guard(
      p_tournament_id,p_user_id,p_position,p_prize,p_bubble_refund);
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(
      v_token,COALESCE((v_result->>'ok')::boolean,false));
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
    RAISE;
  END;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_eliminate_tournament_player_atomic(p_tournament_id uuid, p_user_id uuid, p_position integer, p_prize numeric, p_bubble_refund numeric) OWNER TO postgres;

--
-- Name: fn_eliminate_tournament_player_atomic_pre_seat_guard(uuid, uuid, integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_eliminate_tournament_player_atomic_pre_seat_guard(p_tournament_id uuid, p_user_id uuid, p_position integer, p_prize numeric, p_bubble_refund numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_player public.tournament_players%ROWTYPE;
  v_candidate public.tournament_knockout_candidates%ROWTYPE;
  v_pending_count integer;
  v_latest_joined_at timestamptz;
  v_legacy_hand_number bigint;
  v_result jsonb;
BEGIN
  -- Match the canonical tournament -> player -> candidate/seat lock order.
  PERFORM 1 FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  SELECT * INTO v_player
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','player_not_found');
  END IF;

  PERFORM 1
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_user_id
     AND c.state='pending'
   ORDER BY c.hand_number
   FOR UPDATE;
  SELECT count(*) INTO v_pending_count
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_user_id
     AND c.state='pending';
  -- MORE THAN ONE PENDING GENERATION IS A REBUY, NOT AN AMBIGUITY (2026-09-09).
  -- The unique constraint is (tournament_id, eliminated_user_id, seat_joined_at),
  -- so two pending rows for one player are two DIFFERENT seat generations: the
  -- player busted, bought back in, took a new chair and busted again. The older
  -- generation is therefore settled by definition - it is what 'rebought' means -
  -- and only the newest can be the operative knockout. Refusing instead left the
  -- player 'playing' at zero chips for ever, invisible to the seating self-heal
  -- (which skips zero-chip entrants on purpose) and blocking the field count from
  -- ever reaching one. Measured 2026-09-09: 143 rows across 13 live tournaments.
  IF v_pending_count>1 THEN
    UPDATE public.tournament_knockout_candidates c
       SET state='rebought',resolved_at=coalesce(c.resolved_at,clock_timestamp())
     WHERE c.tournament_id=p_tournament_id
       AND c.eliminated_user_id=p_user_id
       AND c.state='pending'
       AND c.seat_joined_at IS DISTINCT FROM (
         SELECT max(c2.seat_joined_at)
           FROM public.tournament_knockout_candidates c2
          WHERE c2.tournament_id=p_tournament_id
            AND c2.eliminated_user_id=p_user_id
            AND c2.state='pending');
  END IF;

  SELECT * INTO v_candidate
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_user_id
     AND c.state IN ('pending','eliminated')
   ORDER BY (c.state='pending') DESC,c.hand_number DESC
   LIMIT 1
   FOR UPDATE;

  SELECT max(s.joined_at) INTO v_latest_joined_at
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id;

  IF v_candidate.id IS NOT NULL THEN
    -- A PLAYER WITH NO SEAT AT ALL IS NOT ON A STALE GENERATION (2026-09-09).
    -- This check exists so an OLD candidate cannot eliminate a player who has
    -- since re-entered and taken a new chair. That hazard needs a current seat
    -- to exist. When the player holds no seat row in this tournament,
    -- v_latest_joined_at is NULL, `seat_joined_at IS DISTINCT FROM NULL` is TRUE,
    -- and the elimination was refused for ever - even though "the chair is gone"
    -- is the ordinary end state of a bust: the seat is released immediately
    -- (Dan 2026-08-30) and is reused in place by the next occupant.
    -- Compare generations only when there IS a generation to compare against.
    IF v_latest_joined_at IS NOT NULL
       AND v_candidate.seat_joined_at IS DISTINCT FROM v_latest_joined_at THEN
      RETURN jsonb_build_object('ok',false,'reason','knockout_generation_is_not_current');
    END IF;
    IF v_candidate.state='pending'
       AND v_candidate.rebuy_prompt_until IS NOT NULL
       AND v_candidate.rebuy_prompt_until>clock_timestamp() THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','rebuy_decision_open',
        'rebuy_prompt_until',v_candidate.rebuy_prompt_until);
    END IF;
  ELSIF v_player.status='playing' THEN
    -- Old pods wrote a successful stack receipt but no atomic receipt. Permit
    -- only that precisely identifiable rolling-upgrade case. A new atomic hand
    -- with no candidate is never silently downgraded to legacy authority.
    SELECT (k.result->>'hand_number')::bigint
      INTO v_legacy_hand_number
      FROM public.settlement_idempotency_keys k
     WHERE k.table_id=v_player.table_id
       AND k.status='succeeded'
       AND k.completed_at>=v_latest_joined_at
       AND coalesce(k.result->>'hand_number','') ~ '^[0-9]+$'
       AND k.result->>'table_id'=v_player.table_id::text
       AND k.result->'written' ? p_user_id::text
       AND coalesce(k.result->'written'->>p_user_id::text,'') ~ '^-?[0-9]+([.][0-9]+)?$'
       AND (k.result->'written'->>p_user_id::text)::numeric<=0
     ORDER BY k.completed_at DESC
     LIMIT 1;
    IF v_legacy_hand_number IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','knockout_evidence_not_found');
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.hand_atomic_commits c
       WHERE c.table_id=v_player.table_id AND c.hand_number=v_legacy_hand_number
    ) THEN
      RETURN jsonb_build_object('ok',false,'reason','atomic_knockout_candidate_missing');
    END IF;
  END IF;

  v_result := public.fn_eliminate_player_legacy_candidate_20260907(
    p_tournament_id,p_user_id,p_position,p_prize,p_bubble_refund);
  IF coalesce((v_result->>'ok')::boolean,false) AND v_candidate.id IS NOT NULL THEN
    UPDATE public.tournament_knockout_candidates c
       SET state='eliminated',resolved_at=coalesce(c.resolved_at,clock_timestamp())
     WHERE c.id=v_candidate.id AND c.state IN ('pending','eliminated');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'knockout generation changed while elimination committed'
        USING ERRCODE='serialization_failure';
    END IF;
  END IF;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION public.fn_eliminate_tournament_player_atomic_pre_seat_guard(p_tournament_id uuid, p_user_id uuid, p_position integer, p_prize numeric, p_bubble_refund numeric) OWNER TO postgres;

