--
-- Name: fn_emit_claim_notification(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_claim_notification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_venue_name text;
BEGIN
    IF NEW.status = OLD.status THEN RETURN NEW; END IF;
    SELECT name INTO v_venue_name FROM poker_venues WHERE id = NEW.venue_id;
    IF v_venue_name IS NULL THEN RETURN NEW; END IF;

    IF NEW.status = 'approved' THEN
        INSERT INTO notifications (user_id, type, title, message, data, actor_id, link)
        VALUES (
            NEW.user_id, 
            'venue_claim_approved',
            'Your venue claim was approved!',
            'You are now the verified manager of ' || v_venue_name || '. Commander access has been enabled.',
            jsonb_build_object('venue_id', NEW.venue_id, 'venue_name', v_venue_name, 
                               'claim_id', NEW.id),
            NEW.verified_by,
            '/poker-near-me/' || 
              (SELECT lower(state) || '/' || 
                      regexp_replace(lower(city), '[^a-z0-9]+', '-', 'g') || '/' || slug
                 FROM poker_venues WHERE id = NEW.venue_id)
        );
    ELSIF NEW.status = 'rejected' THEN
        INSERT INTO notifications (user_id, type, title, message, data, actor_id)
        VALUES (
            NEW.user_id,
            'venue_claim_rejected',
            'Update on your venue claim',
            'Your claim for ' || v_venue_name || ' could not be approved. ' || 
                COALESCE('Reason: ' || NEW.rejection_reason, 'Please contact support for details.'),
            jsonb_build_object('venue_id', NEW.venue_id, 'venue_name', v_venue_name, 
                               'claim_id', NEW.id, 'rejection_reason', NEW.rejection_reason),
            NEW.verified_by
        );
    END IF;
    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'claim notification emit failed: %', SQLERRM;
    RETURN NEW;
END; $$;


ALTER FUNCTION public.fn_emit_claim_notification() OWNER TO postgres;

--
-- Name: FUNCTION fn_emit_claim_notification(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_emit_claim_notification() IS 'Phase 30: Auto-emit notification to claimant on approve/reject status change.';


--
-- Name: fn_emit_club_union_access_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_club_union_access_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_recipient uuid;
  v_union uuid;
  v_side text;
BEGIN
  IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    PERFORM public.fn_emit_game_management_event(
      'management_access_changed', NEW.id, NEW.union_id, OLD.owner_id,
      'club', NEW.id, NULL,
      jsonb_build_object('operation', 'owner_changed', 'side', 'before'));
    PERFORM public.fn_emit_game_management_event(
      'management_access_changed', NEW.id, NEW.union_id, NEW.owner_id,
      'club', NEW.id, NULL,
      jsonb_build_object('operation', 'owner_changed', 'side', 'after'));
  END IF;

  IF NEW.union_id IS DISTINCT FROM OLD.union_id THEN
    FOR v_union, v_side IN
      SELECT OLD.union_id, 'before' WHERE OLD.union_id IS NOT NULL
      UNION ALL
      SELECT NEW.union_id, 'after' WHERE NEW.union_id IS NOT NULL
    LOOP
      FOR v_recipient IN
        SELECT OLD.owner_id
        UNION SELECT NEW.owner_id
        UNION SELECT m.user_id FROM public.club_members m
          WHERE m.club_id = NEW.id
            AND m.role IN ('owner','co_owner','admin')
            AND m.status IN ('active','approved')
            AND COALESCE(m.is_active, true)
        UNION SELECT u.owner_id FROM public.unions u WHERE u.id = v_union
        UNION SELECT a.user_id FROM public.union_admins a WHERE a.union_id = v_union
      LOOP
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', NEW.id, v_union, v_recipient,
          'club', NEW.id, NULL,
          jsonb_build_object('operation', 'union_changed', 'side', v_side));
      END LOOP;
    END LOOP;

    -- Leaving a union has a new standalone scope. Its operators still need an
    -- authoritative refresh even though there is no new union recipient set.
    IF NEW.union_id IS NULL THEN
      FOR v_recipient IN
        SELECT NEW.owner_id
        UNION SELECT m.user_id FROM public.club_members m
          WHERE m.club_id = NEW.id
            AND m.role IN ('owner','co_owner','admin')
            AND m.status IN ('active','approved')
            AND COALESCE(m.is_active, true)
      LOOP
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', NEW.id, NULL, v_recipient,
          'club', NEW.id, NULL,
          jsonb_build_object('operation', 'union_changed', 'side', 'after'));
      END LOOP;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_emit_club_union_access_event() OWNER TO postgres;

--
-- Name: fn_emit_game_management_event(text, uuid, uuid, uuid, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_game_management_event(p_event_type text, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_recipient_id uuid DEFAULT NULL::uuid, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_command_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_scope_kind text; v_scope_id uuid; v_union_id uuid;
BEGIN
  IF p_union_id IS NOT NULL THEN
    v_scope_kind := 'union'; v_scope_id := p_union_id; v_union_id := p_union_id;
  ELSIF p_club_id IS NOT NULL THEN
    SELECT s.scope_kind,s.scope_id,s.union_id
      INTO v_scope_kind,v_scope_id,v_union_id
      FROM public.fn_game_management_scope(p_club_id) s;
  END IF;
  INSERT INTO public.game_management_events(
    event_type,scope_kind,scope_id,club_id,union_id,recipient_id,
    entity_type,entity_id,command_id,actor_id,payload
  ) VALUES (
    p_event_type,v_scope_kind,v_scope_id,p_club_id,v_union_id,p_recipient_id,
    p_entity_type,p_entity_id,p_command_id,auth.uid(),COALESCE(p_payload,'{}'::jsonb)
  );
END;
$$;


ALTER FUNCTION public.fn_emit_game_management_event(p_event_type text, p_club_id uuid, p_union_id uuid, p_recipient_id uuid, p_entity_type text, p_entity_id uuid, p_command_id uuid, p_payload jsonb) OWNER TO postgres;

--
-- Name: fn_emit_home_notification(uuid, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_home_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_link text, p_data jsonb, p_pref_column text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_allowed boolean := true;
    v_pref_val text;
BEGIN
    IF p_user_id IS NULL THEN RETURN; END IF;

    -- Check user pref if column name provided; default allow on any error
    IF p_pref_column IS NOT NULL THEN
      BEGIN
        EXECUTE format('SELECT (%I)::text FROM user_notification_preferences WHERE user_id = $1', p_pref_column)
             INTO v_pref_val
            USING p_user_id;
        IF v_pref_val = 'false' THEN v_allowed := false; END IF;
      EXCEPTION
        WHEN undefined_column THEN
          -- Schema drift: column doesn't exist → treat as opted-in
          RAISE WARNING 'fn_emit_home_notification: preference column % does not exist, defaulting to allow',
            p_pref_column;
          v_allowed := true;
        WHEN OTHERS THEN
          -- Any other failure (permissions, table missing, etc) → default allow
          RAISE WARNING 'fn_emit_home_notification: could not read pref %: % (%), defaulting to allow',
            p_pref_column, SQLERRM, SQLSTATE;
          v_allowed := true;
      END;
    END IF;

    IF v_allowed THEN
      BEGIN
        INSERT INTO notifications (user_id, type, title, message, link, data, read)
        VALUES (p_user_id, p_type, p_title, p_message, p_link, COALESCE(p_data, '{}'::jsonb), false);
      EXCEPTION WHEN OTHERS THEN
        -- Even the insert itself must not block the parent operation.
        -- Notifications are nice-to-have; game creation/RSVP is critical.
        RAISE WARNING 'fn_emit_home_notification: failed to insert notification: % (%)',
          SQLERRM, SQLSTATE;
      END;
    END IF;
END;
$_$;


ALTER FUNCTION public.fn_emit_home_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_link text, p_data jsonb, p_pref_column text) OWNER TO postgres;

--
-- Name: FUNCTION fn_emit_home_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_link text, p_data jsonb, p_pref_column text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_emit_home_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_link text, p_data jsonb, p_pref_column text) IS 'Phase 40: emits a notification to a user, respecting their preference opt-out. Entirely defensive: a missing preference column, missing row, or insert failure will NEVER block the caller. Notifications are opportunistic; parent DB operations must always commit.';


--
-- Name: fn_emit_managed_command_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_managed_command_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_club uuid; v_role text := 'host';
BEGIN
  IF OLD.status='processing' AND NEW.status IN ('succeeded','rejected') THEN
    IF NEW.game_kind='table' THEN
      SELECT club_id INTO v_club FROM public.tables WHERE id=NEW.game_id;
    ELSE
      SELECT club_id INTO v_club FROM public.tournaments WHERE id=NEW.game_id;
    END IF;
    PERFORM public.fn_emit_game_management_event(
      'game_command_'||NEW.status,v_club,NULL,NULL,NEW.game_kind,NEW.game_id,
      NEW.command_id,jsonb_build_object('action',NEW.command_action,'status',NEW.status)
    );
    IF EXISTS (SELECT 1 FROM public.union_clubs WHERE club_id=v_club) THEN
      v_role := 'union_admin';
    ELSE
      SELECT CASE WHEN c.owner_id=NEW.actor_id THEN 'owner'
                  WHEN m.role='co_owner' THEN 'co_owner' ELSE 'host' END
        INTO v_role FROM public.clubs c
        LEFT JOIN public.club_members m ON m.club_id=c.id AND m.user_id=NEW.actor_id
       WHERE c.id=v_club;
    END IF;
    INSERT INTO public.audit_trail(
      actor_id,actor_role,action,target_type,target_id,club_id,
      before_state,after_state,reason,request_id
    ) VALUES (
      NEW.actor_id,COALESCE(v_role,'host'),'managed_game_'||NEW.command_action||'_'||NEW.status,
      NEW.game_kind,NEW.game_id,v_club,
      jsonb_build_object('contract_version',NEW.contract_version_before),
      jsonb_build_object('contract_version',NEW.contract_version_after,'result',NEW.result),
      NEW.result->>'reason',NEW.command_id::text
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_emit_managed_command_event() OWNER TO postgres;

--
-- Name: fn_emit_managed_game_row_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_managed_game_row_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club  uuid := COALESCE(to_jsonb(NEW) ->> 'club_id', to_jsonb(OLD) ->> 'club_id')::uuid;
  v_id    uuid := COALESCE(to_jsonb(NEW) ->> 'id',      to_jsonb(OLD) ->> 'id')::uuid;
  v_watch text[];
BEGIN
  -- Tournament backing tables are represented by the tournament event itself.
  IF TG_TABLE_NAME = 'tables' THEN
    IF COALESCE(to_jsonb(NEW) ->> 'tournament_id',
                to_jsonb(OLD) ->> 'tournament_id') IS NOT NULL THEN
      RETURN NULL;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Exactly the columns fn_list_managed_games projects for this kind. Keep
    -- these two lists in step with that function: a column the board reads and
    -- this does not watch is a row that silently stops refreshing.
    v_watch := CASE TG_TABLE_NAME
      WHEN 'tables' THEN ARRAY[
        'club_id', 'union_id', 'tournament_id', 'is_deleted', 'name', 'status',
        'game_variant', 'current_players', 'max_players', 'small_blind',
        'big_blind', 'min_buy_in', 'max_buy_in', 'created_at']
      ELSE ARRAY[
        'club_id', 'union_id', 'name', 'status', 'game_type', 'variant',
        'current_players', 'max_players', 'start_time', 'created_at',
        'buy_in_amount', 'guaranteed_prize', 'prize_pool']
    END;

    IF (SELECT jsonb_object_agg(k, COALESCE(to_jsonb(OLD) -> k, 'null'::jsonb))
          FROM unnest(v_watch) AS k)
       IS NOT DISTINCT FROM
       (SELECT jsonb_object_agg(k, COALESCE(to_jsonb(NEW) -> k, 'null'::jsonb))
          FROM unnest(v_watch) AS k)
    THEN
      RETURN NULL;
    END IF;
  END IF;

  PERFORM public.fn_emit_game_management_event(
    'game_changed', v_club, NULL, NULL,
    CASE WHEN TG_TABLE_NAME = 'tables' THEN 'table' ELSE 'tournament' END,
    v_id, NULL, jsonb_build_object('operation', lower(TG_OP)));
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_emit_managed_game_row_event() OWNER TO postgres;

--
-- Name: FUNCTION fn_emit_managed_game_row_event(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_emit_managed_game_row_event() IS 'Emits a game_changed event for tables and tournaments. Reads record fields through to_jsonb because this one function is attached to two tables with different columns and fires on DELETE as well: in PL/pgSQL, AND does NOT short-circuit a record field reference - the whole IF condition is planned as one SQL expression - which is why the original TG_TABLE_NAME=''tables'' AND NEW.tournament_id guard raised on every tournament UPDATE and kept reconcile-tournament-denormals from ever completing a run.';


--
-- Name: fn_emit_managed_schedule_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_managed_schedule_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_kind text := COALESCE(NEW.game_kind, OLD.game_kind);
  v_game uuid := COALESCE(NEW.game_id,   OLD.game_id);
  v_was  boolean := (TG_OP <> 'INSERT' AND OLD.status = 'scheduled');
  v_is   boolean := (TG_OP <> 'DELETE' AND NEW.status = 'scheduled');
  v_club uuid;
BEGIN
  -- Nothing the board renders moved.
  IF NOT v_was AND NOT v_is THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND v_was AND v_is
     AND NEW.execute_at IS NOT DISTINCT FROM OLD.execute_at THEN
    RETURN NULL;
  END IF;

  IF v_kind = 'table' THEN
    SELECT t.club_id INTO v_club FROM public.tables t WHERE t.id = v_game;
  ELSE
    SELECT t.club_id INTO v_club FROM public.tournaments t WHERE t.id = v_game;
  END IF;

  -- The game is gone; its own DELETE already told the board.
  IF v_club IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM public.fn_emit_game_management_event(
    'game_changed', v_club, NULL, NULL, v_kind, v_game, NULL,
    jsonb_build_object('operation', lower(TG_OP), 'source', 'schedule'));
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_emit_managed_schedule_event() OWNER TO postgres;

--
-- Name: fn_emit_management_access_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_management_access_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_recipient uuid;
  v_club uuid;
  v_union uuid;
  v_operation text := lower(TG_OP);
BEGIN
  IF TG_TABLE_NAME = 'club_members' THEN
    IF TG_OP = 'UPDATE'
       AND NEW.role IS NOT DISTINCT FROM OLD.role
       AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
       AND NEW.club_id IS NOT DISTINCT FROM OLD.club_id
       AND NEW.status IS NOT DISTINCT FROM OLD.status
       AND NEW.is_active IS NOT DISTINCT FROM OLD.is_active THEN
      RETURN NULL;
    END IF;

    IF TG_OP IN ('UPDATE', 'DELETE') THEN
      PERFORM public.fn_emit_game_management_event(
        'management_access_changed', OLD.club_id, NULL, OLD.user_id,
        'club', OLD.club_id, NULL,
        jsonb_build_object('operation', v_operation, 'side', 'before'));
    END IF;
    IF TG_OP IN ('UPDATE', 'INSERT')
       AND (TG_OP = 'INSERT'
            OR NEW.user_id IS DISTINCT FROM OLD.user_id
            OR NEW.club_id IS DISTINCT FROM OLD.club_id
            OR NEW.role IS DISTINCT FROM OLD.role
            OR NEW.status IS DISTINCT FROM OLD.status
            OR NEW.is_active IS DISTINCT FROM OLD.is_active) THEN
      -- When the row identity did not move, one after-event is sufficient.
      IF TG_OP = 'INSERT'
         OR NEW.user_id IS DISTINCT FROM OLD.user_id
         OR NEW.club_id IS DISTINCT FROM OLD.club_id THEN
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', NEW.club_id, NULL, NEW.user_id,
          'club', NEW.club_id, NULL,
          jsonb_build_object('operation', v_operation, 'side', 'after'));
      END IF;
    END IF;

  ELSIF TG_TABLE_NAME = 'union_admins' THEN
    IF TG_OP = 'UPDATE'
       AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
       AND NEW.union_id IS NOT DISTINCT FROM OLD.union_id
       AND NEW.role IS NOT DISTINCT FROM OLD.role THEN
      RETURN NULL;
    END IF;

    IF TG_OP IN ('UPDATE', 'DELETE') THEN
      PERFORM public.fn_emit_game_management_event(
        'management_access_changed', NULL, OLD.union_id, OLD.user_id,
        'union', OLD.union_id, NULL,
        jsonb_build_object('operation', v_operation, 'side', 'before'));
    END IF;
    IF TG_OP = 'INSERT'
       OR (TG_OP = 'UPDATE' AND (
         NEW.user_id IS DISTINCT FROM OLD.user_id
         OR NEW.union_id IS DISTINCT FROM OLD.union_id)) THEN
      PERFORM public.fn_emit_game_management_event(
        'management_access_changed', NULL, NEW.union_id, NEW.user_id,
        'union', NEW.union_id, NULL,
        jsonb_build_object('operation', v_operation, 'side', 'after'));
    END IF;

  ELSE
    -- union_clubs. UPDATE was omitted from the original trigger entirely.
    -- Each side gets its own recipient set and its own union scope.
    IF TG_OP IN ('UPDATE', 'DELETE') THEN
      v_club := OLD.club_id;
      v_union := OLD.union_id;
      FOR v_recipient IN
        SELECT c.owner_id FROM public.clubs c WHERE c.id = v_club
        UNION SELECT m.user_id FROM public.club_members m
          WHERE m.club_id = v_club
            AND m.role IN ('owner','co_owner','admin')
            AND m.status IN ('active','approved')
            AND COALESCE(m.is_active, true)
        UNION SELECT u.owner_id FROM public.unions u WHERE u.id = v_union
        UNION SELECT a.user_id FROM public.union_admins a WHERE a.union_id = v_union
      LOOP
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', v_club, v_union, v_recipient,
          'club', v_club, NULL,
          jsonb_build_object('operation', v_operation, 'side', 'before'));
      END LOOP;
    END IF;

    IF TG_OP IN ('UPDATE', 'INSERT') THEN
      v_club := NEW.club_id;
      v_union := NEW.union_id;
      FOR v_recipient IN
        SELECT c.owner_id FROM public.clubs c WHERE c.id = v_club
        UNION SELECT m.user_id FROM public.club_members m
          WHERE m.club_id = v_club
            AND m.role IN ('owner','co_owner','admin')
            AND m.status IN ('active','approved')
            AND COALESCE(m.is_active, true)
        UNION SELECT u.owner_id FROM public.unions u WHERE u.id = v_union
        UNION SELECT a.user_id FROM public.union_admins a WHERE a.union_id = v_union
      LOOP
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', v_club, v_union, v_recipient,
          'club', v_club, NULL,
          jsonb_build_object('operation', v_operation, 'side', 'after'));
      END LOOP;
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_emit_management_access_event() OWNER TO postgres;

--
-- Name: fn_emit_management_content_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_emit_management_content_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club uuid; v_union uuid; v_type text; v_id uuid; v_role text := 'host';
  v_before jsonb; v_after jsonb;
BEGIN
  IF TG_TABLE_NAME = 'game_ticker_settings' THEN
    IF TG_OP = 'UPDATE'
       AND (to_jsonb(NEW) - ARRAY['updated_at','revision'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at','revision']) THEN
      RETURN NULL;
    END IF;
    v_club := COALESCE(NEW.club_id, OLD.club_id);
    v_union := COALESCE(NEW.union_id, OLD.union_id);
    v_type := 'ticker_settings_changed'; v_id := COALESCE(NEW.id, OLD.id);
    v_before := CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object('settings',OLD.settings) END;
    v_after := CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('settings',NEW.settings) END;
  ELSIF TG_TABLE_NAME = 'clubs' THEN
    IF NEW.tagline IS NOT DISTINCT FROM OLD.tagline
       AND NEW.lobby_message IS NOT DISTINCT FROM OLD.lobby_message
       AND NEW.description IS NOT DISTINCT FROM OLD.description THEN
      RETURN NULL;
    END IF;
    v_club := NEW.id; v_type := 'club_identity_changed'; v_id := NEW.id;
    v_before := jsonb_build_object('tagline',OLD.tagline,'lobby_message',OLD.lobby_message,'description',OLD.description);
    v_after := jsonb_build_object('tagline',NEW.tagline,'lobby_message',NEW.lobby_message,'description',NEW.description);
  ELSE
    IF TG_OP = 'UPDATE'
       AND (to_jsonb(NEW) - ARRAY['updated_at','management_revision'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['updated_at','management_revision']) THEN
      RETURN NULL;
    END IF;
    v_club := COALESCE(NEW.club_id,OLD.club_id);
    v_type := 'announcement_changed'; v_id := COALESCE(NEW.id,OLD.id);
    v_before := CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object(
      'title',OLD.title,'content',OLD.content,'is_pinned',OLD.is_pinned,'is_active',OLD.is_active) END;
    v_after := CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object(
      'title',NEW.title,'content',NEW.content,'is_pinned',NEW.is_pinned,'is_active',NEW.is_active) END;
  END IF;

  PERFORM public.fn_emit_game_management_event(
    v_type,v_club,v_union,NULL,TG_TABLE_NAME,v_id,NULL,
    jsonb_build_object('operation',lower(TG_OP)));

  IF auth.uid() IS NOT NULL THEN
    IF v_union IS NOT NULL OR EXISTS (
      SELECT 1 FROM public.union_clubs WHERE club_id=v_club) THEN
      v_role := 'union_admin';
    ELSE
      SELECT CASE WHEN c.owner_id=auth.uid() THEN 'owner'
                  WHEN m.role='co_owner' THEN 'co_owner'
                  WHEN m.role='admin' THEN 'admin' ELSE 'host' END
        INTO v_role FROM public.clubs c
        LEFT JOIN public.club_members m
          ON m.club_id=c.id AND m.user_id=auth.uid()
       WHERE c.id=v_club;
    END IF;
    INSERT INTO public.audit_trail(
      actor_id,actor_role,action,target_type,target_id,club_id,before_state,after_state
    ) VALUES (
      auth.uid(),COALESCE(v_role,'host'),v_type,TG_TABLE_NAME,v_id,v_club,v_before,v_after);
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_emit_management_content_event() OWNER TO postgres;

