--
-- Name: fn_enforce_agent_commission_bounds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_agent_commission_bounds() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_union uuid; v_min numeric; v_max numeric; v_rate numeric;
BEGIN
  IF NEW.commission_rate IS NULL THEN RETURN NEW; END IF;

  -- THE RATE IS NOT CHANGING, SO THERE IS NOTHING TO JUDGE.
  -- This trigger is BEFORE UPDATE OF commission_rate, and Postgres fires that
  -- for any UPDATE whose SET list names the column, identical value or not.
  -- Without this, an unrelated write - a status change, a demotion, a parent
  -- reassignment - re-validates a rate nobody touched against a band the row
  -- may never have satisfied, and raises P0001 into a caller that has no idea
  -- why. It is how demoting a co-owner to player failed outright in any club
  -- under a union with a non-zero minimum.
  IF TG_OP = 'UPDATE' AND NEW.commission_rate IS NOT DISTINCT FROM OLD.commission_rate THEN
    RETURN NEW;
  END IF;

  -- A co-owner and an admin earn nothing, by Dan's rule and by
  -- trg_agents_staff_earn_no_rakeback, which sets both of their rates to zero.
  -- The union band says what an EARNING agent may be paid, so it has nothing to
  -- say about a row that is forbidden to earn.
  IF NEW.commission_rate = 0 AND EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.club_id = NEW.club_id
       AND cm.user_id = NEW.user_id
       AND cm.role IN ('co_owner', 'admin')
  ) THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(uc.union_id, c.union_id) INTO v_union
    FROM clubs c LEFT JOIN union_clubs uc ON uc.club_id = c.id
   WHERE c.id = NEW.club_id LIMIT 1;

  IF v_union IS NULL THEN RETURN NEW; END IF;   -- standalone club: no policy

  v_min := public.fn_union_setting(v_union, 'min_agent_commission', 0);
  v_max := public.fn_union_setting(v_union, 'max_agent_commission', 1);

  -- Rates may be expressed as a fraction (0.5) or whole percent (50).
  v_rate := CASE WHEN NEW.commission_rate > 1 THEN NEW.commission_rate / 100.0
                 ELSE NEW.commission_rate END;

  IF v_rate < v_min OR v_rate > v_max THEN
    RAISE EXCEPTION 'agent commission % is outside the union policy band (% .. %)',
      v_rate, v_min, v_max
      USING HINT = 'Change unions.settings.min_agent_commission / max_agent_commission to widen the band.';
  END IF;

  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_enforce_agent_commission_bounds() OWNER TO postgres;

--
-- Name: fn_enforce_anti_farming_caps(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_anti_farming_caps() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$                                                                                 
 DECLARE                                                                                       
   v_recipient uuid;                                                                           
   v_check     jsonb;                                                                          
   v_kingfish  uuid := '47965354-0e56-43ef-931c-ddaab82af765';                                 
 BEGIN                                                                                         
   -- Only enforce on outbound (debit) rows                                                    
   IF NEW.amount IS NULL OR NEW.amount >= 0 THEN                                               
     RETURN NEW;                                                                               
   END IF;                                                                                     
                                                                                               
   -- Only on user→user diamond movement channels.                                             
   -- COALESCE coerces NULL to '' so NULL columns evaluate to FALSE (not NULL)                 
   -- in the IN check. Critical because deduct_diamonds writes source=NULL on                  
   -- every non-gift call (game_cost, course_purchase, etc.) and we need those                 
   -- to fall through to the early RETURN NEW.                                                 
   IF NOT (                                                                                    
        COALESCE(NEW.transaction_type, '') IN ('live_gift_sent','diamond_gift_sent')           
     OR COALESCE(NEW.source, '') IN ('stream_gift','wallet_transfer','wallet_diamond_transfer')
   ) THEN                                                                                      
     RETURN NEW;                                                                               
   END IF;                                                                                     
                                                                                               
   -- KINGFISH sender bypass                                                                   
   IF NEW.user_id = v_kingfish THEN                                                            
     RETURN NEW;                                                                               
   END IF;                                                                                     
                                                                                               
   -- Recipient_id required in metadata for enforced channels                                  
   v_recipient := NULLIF(NEW.metadata->>'recipient_id', '')::uuid;                             
   IF v_recipient IS NULL THEN                                                                 
     RAISE EXCEPTION 'Anti-farming: recipient_id missing from metadata for % transaction',     
       COALESCE(NEW.transaction_type, NEW.source)                                              
       USING ERRCODE = 'check_violation';                                                      
   END IF;                                                                                     
                                                                                               
   -- Delegate to shared cap function                                                          
   v_check := public.fn_check_anti_farming_gift_cap(NEW.user_id, v_recipient, ABS(NEW.amount));
                                                                                               
   IF NOT (v_check->>'allowed')::boolean THEN                                                  
     RAISE EXCEPTION 'Anti-farming: %', v_check->>'reason'                                     
       USING ERRCODE = 'check_violation', DETAIL = v_check::text;                              
   END IF;                                                                                     
                                                                                               
   RETURN NEW;                                                                                 
 END;                                                                                          
 $$;


ALTER FUNCTION public.fn_enforce_anti_farming_caps() OWNER TO postgres;

--
-- Name: FUNCTION fn_enforce_anti_farming_caps(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_enforce_anti_farming_caps() IS 'Anti-farming trigger';


--
-- Name: fn_enforce_booking_game_cap(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_booking_game_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_load    int;
  v_tstatus text;
BEGIN
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.status IS NULL OR NEW.status NOT IN ('registered', 'playing') THEN
    RETURN NEW;
  END IF;

  -- registered -> playing at late registration is not a NEW claim.
  IF TG_OP = 'UPDATE' AND OLD.status IN ('registered', 'playing') THEN
    RETURN NEW;
  END IF;

  SELECT tr.status INTO v_tstatus
    FROM public.tournaments tr
   WHERE tr.id = NEW.tournament_id;

  -- Once under way, entrants are counted by their SEATS and the seat trigger
  -- owns the rule. An unreadable tournament row is checked, not waved through.
  IF v_tstatus IS NOT NULL AND v_tstatus NOT IN ('ANNOUNCED', 'REGISTERING') THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:' || NEW.user_id::text, 0));

  v_load := public.fn_concurrent_game_load(NEW.user_id, NULL, NULL, NEW.tournament_id);

  IF v_load >= 4 THEN
    RAISE EXCEPTION
      'FOUR TABLE LIMIT: user % is already committed to % games and may not enter another',
      NEW.user_id, v_load
      USING ERRCODE = '23514',
            HINT = 'Leave a table or unregister before entering another. A game is a live seat or a booking for a tournament that has not started. This limit applies to players and horses alike.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_booking_game_cap() OWNER TO postgres;

--
-- Name: fn_enforce_club_enters_union_empty(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_club_enters_union_empty() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  b jsonb;
BEGIN
  IF NEW.club_id = NEW.union_id THEN
    RETURN NEW;
  END IF;

  b := public.fn_club_union_join_blockers(NEW.club_id);

  IF (b->>'is_empty')::boolean THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION USING
    ERRCODE = 'check_violation',
    MESSAGE = 'This club still holds chips and cannot join a union yet.',
    DETAIL  = format(
      'treasury %s, club promo %s, member wallets %s across %s members, horse bankrolls %s across %s horses, agent wallets %s across %s agents, %s on the felt in %s open seats, BBJ pool %s. Total %s.',
      b->>'club_treasury', b->>'club_promo',
      b->>'member_wallets', b->>'member_count',
      b->>'horse_wallets', b->>'horse_count',
      b->>'agent_wallets', b->>'agent_count',
      b->>'chips_on_felt', b->>'open_seats',
      b->>'bbj_pool', b->>'total'),
    HINT    = 'Cash your players and agents down to zero, close the tables and empty the treasury first. Once the club is in the union, the union funds it.';
END;
$$;


ALTER FUNCTION public.fn_enforce_club_enters_union_empty() OWNER TO postgres;

--
-- Name: FUNCTION fn_enforce_club_enters_union_empty(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_enforce_club_enters_union_empty() IS 'Dan 2026-08-26, binding: a club joins a union at zero and is funded by the union from then on. Refuses the union_clubs INSERT while the club still holds chips anywhere. It never zeroes anything itself - the club settles its own players and agents first, on purpose.';


--
-- Name: fn_enforce_four_club_limit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_four_club_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int;
BEGIN
  IF NEW.status NOT IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM profiles WHERE id = NEW.user_id AND COALESCE(is_horse, false)
  ) THEN
    RETURN NEW;
  END IF;

  SELECT count(*) INTO v_count
    FROM club_members
   WHERE user_id = NEW.user_id
     AND status IN ('active', 'approved')
     AND club_id <> NEW.club_id;

  IF v_count >= 10 THEN
    RAISE EXCEPTION
      'You can only be a member of up to 10 clubs. Leave a club to join a new one.'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_four_club_limit() OWNER TO postgres;

--
-- Name: fn_enforce_four_table_limit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_four_table_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_live       int;
  v_is_closed  boolean;
  v_tournament uuid;
BEGIN
  IF NEW.left_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- A MOVE WITHIN ONE GAME IS NOT A FIFTH GAME (2026-09-05). Only the cluster
  -- executor sets this, for the one transaction in which a player changes
  -- chairs inside a game they are already in. It replaces the 041000 rule
  -- ("holds another live seat in this cluster"), which also let a player buy
  -- a second seat into a game they were already sitting in.
  IF current_setting('app.cash_seat_move', true) = 'on' THEN
    RETURN NEW;
  END IF;

  SELECT (t.status = 'closed'), t.tournament_id
    INTO v_is_closed, v_tournament
    FROM public.tables t
   WHERE t.id = NEW.table_id;
  IF COALESCE(v_is_closed, false) THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:' || NEW.user_id::text, 0));

  v_live := public.fn_concurrent_game_load(NEW.user_id, NEW.id, NEW.table_id, v_tournament);

  IF v_live >= 4 THEN
    RAISE EXCEPTION
      'FOUR TABLE LIMIT: user % is already committed to % games and may not take another',
      NEW.user_id, v_live
      USING ERRCODE = '23514',
            HINT = 'Leave a table or unregister before joining another. A game is a live seat or a booking for a tournament that has not started. This limit applies to players and horses alike.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_four_table_limit() OWNER TO postgres;

--
-- Name: fn_enforce_game_table_identity_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_game_table_identity_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_role text := current_user;
BEGIN
  IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                'supabase_auth_admin', 'supabase_storage_admin') THEN
    RETURN NEW;
  END IF;

  IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'GAME_TABLE_IMMUTABLE'
          USING HINT = 'created_at is immutable on game tables';
  END IF;

  IF NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'GAME_TABLE_IMMUTABLE'
          USING HINT = 'created_by is immutable on game tables';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_game_table_identity_immutable() OWNER TO postgres;

--
-- Name: fn_enforce_game_table_immutability(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_game_table_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text := current_user;
  v_highest_seat integer;
BEGIN
  IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                'supabase_auth_admin', 'supabase_storage_admin') THEN
    RETURN NEW;
  END IF;

  -- Identity fields: immutable
  IF NEW.game_id IS DISTINCT FROM OLD.game_id THEN
    RAISE EXCEPTION 'GAME_TABLE_IMMUTABLE'
          USING HINT = 'game_id cannot be changed; delete and recreate '
                     || 'the table if it belongs to a different game';
  END IF;
  IF NEW.table_number IS DISTINCT FROM OLD.table_number THEN
    RAISE EXCEPTION 'GAME_TABLE_IMMUTABLE'
          USING HINT = 'table_number is an identity column and cannot be changed';
  END IF;
  IF NEW.is_default IS DISTINCT FROM OLD.is_default THEN
    RAISE EXCEPTION 'GAME_TABLE_IMMUTABLE'
          USING HINT = 'is_default is set at table creation and cannot be toggled; '
                     || 'the default table is guaranteed by the partial unique index';
  END IF;

  -- Status transitions. Allowed edges:
  --   draft            → open_for_rsvp, cancelled
  --   open_for_rsvp    → running, cancelled, draft
  --   running          → ended, cancelled
  --   ended            → (terminal)
  --   cancelled        → (terminal)
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF OLD.status = 'ended' OR OLD.status = 'cancelled' THEN
      RAISE EXCEPTION 'GAME_TABLE_STATUS_TERMINAL'
            USING HINT = 'status ' || OLD.status || ' is terminal and cannot be changed';
    END IF;
    IF OLD.status = 'draft' AND NEW.status NOT IN ('open_for_rsvp','cancelled') THEN
      RAISE EXCEPTION 'INVALID_GAME_TABLE_TRANSITION'
            USING HINT = 'from draft, allowed next statuses are open_for_rsvp or cancelled';
    END IF;
    IF OLD.status = 'open_for_rsvp' AND NEW.status NOT IN ('running','cancelled','draft') THEN
      RAISE EXCEPTION 'INVALID_GAME_TABLE_TRANSITION'
            USING HINT = 'from open_for_rsvp, allowed next statuses are running, cancelled, or draft';
    END IF;
    IF OLD.status = 'running' AND NEW.status NOT IN ('ended','cancelled') THEN
      RAISE EXCEPTION 'INVALID_GAME_TABLE_TRANSITION'
            USING HINT = 'from running, allowed next statuses are ended or cancelled';
    END IF;
  END IF;

  -- max_seats: when reducing, must not orphan active reservations
  IF NEW.max_seats IS DISTINCT FROM OLD.max_seats AND NEW.max_seats < OLD.max_seats THEN
    SELECT COALESCE(MAX(seat_number), 0) INTO v_highest_seat
    FROM public.commander_home_seat_reservations
    WHERE table_id = OLD.id AND status IN ('reserved','seated');
    IF v_highest_seat > NEW.max_seats THEN
      RAISE EXCEPTION 'MAX_SEATS_ORPHANS_RESERVATIONS'
            USING HINT = 'reducing max_seats to ' || NEW.max_seats
                      || ' would orphan existing reservation at seat ' || v_highest_seat;
    END IF;
  END IF;

  -- max_seats: once running, locked (live seating is commander_home_seats)
  IF NEW.max_seats IS DISTINCT FROM OLD.max_seats AND OLD.status = 'running' THEN
    RAISE EXCEPTION 'MAX_SEATS_LOCKED_WHILE_RUNNING'
          USING HINT = 'live seating is managed via Club Commander once the table is running';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_game_table_immutability() OWNER TO postgres;

--
-- Name: fn_enforce_home_club_announcement_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_home_club_announcement_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() = 'service_role' OR auth.uid() IS NULL THEN RETURN NEW; END IF;

  -- Bind author to caller (no forgery)
  NEW.author_id := auth.uid();

  -- System fields: reset on user INSERT
  NEW.push_sent       := false;
  NEW.push_sent_count := 0;
  NEW.sent_at         := NULL;

  -- Force status to a safe initial state
  IF NEW.status IS NULL OR NEW.status NOT IN ('draft', 'scheduled') THEN
    NEW.status := 'draft';
  END IF;

  -- Cannot backdate
  NEW.created_at := NOW();

  -- scheduled_for can't be in the past
  IF NEW.scheduled_for IS NOT NULL AND NEW.scheduled_for < NOW() - INTERVAL '1 minute' THEN
    RAISE EXCEPTION 'SCHEDULED_IN_PAST'
          USING HINT = 'scheduled_for cannot be in the past';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_home_club_announcement_insert() OWNER TO postgres;

--
-- Name: fn_enforce_home_club_announcement_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_home_club_announcement_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_role text := current_user;
BEGIN
  IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                'supabase_auth_admin', 'supabase_storage_admin') THEN
    RETURN NEW;
  END IF;

  IF NEW.author_id IS DISTINCT FROM OLD.author_id THEN
    RAISE EXCEPTION 'IMMUTABLE_FIELD'
          USING HINT = 'author_id is immutable on announcements';
  END IF;
  IF NEW.group_id IS DISTINCT FROM OLD.group_id THEN
    RAISE EXCEPTION 'IMMUTABLE_FIELD'
          USING HINT = 'group_id is immutable on announcements';
  END IF;
  IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'IMMUTABLE_FIELD'
          USING HINT = 'created_at is immutable on announcements';
  END IF;
  IF NEW.push_sent IS DISTINCT FROM OLD.push_sent
     OR NEW.push_sent_count IS DISTINCT FROM OLD.push_sent_count
     OR NEW.sent_at IS DISTINCT FROM OLD.sent_at THEN
    RAISE EXCEPTION 'SYSTEM_ONLY_FIELD'
          USING HINT = 'push_sent, push_sent_count, sent_at are system-managed';
  END IF;

  RETURN NEW;
END;
$$;


