--
-- Name: FUNCTION fn_enforce_home_member_field_permissions(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_enforce_home_member_field_permissions() IS 'Field-permissions trigger on commander_home_members UPDATE. Blocks self-edits of privileged fields (role/status/can_host/is_regular/flake_strikes/host_private_note/probation_until/invited_by/joined_at/group_id/user_id). Pass 37: also blocks games_attended/games_hosted/last_attended/is_roster_only/added_by_user_id/pending_nudge_sent_at (stat + identity-type lockdown). Staff + service-role bypass.';


--
-- Name: fn_enforce_home_members_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_home_members_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_role text := current_user;
  v_active_games int;
BEGIN
  -- Active-host guard fires for EVERYONE unless explicitly skipped
  IF COALESCE(current_setting('app.hg_skip_active_host_check', true), '') <> '1' THEN
    SELECT COUNT(*) INTO v_active_games
      FROM commander_home_games
     WHERE group_id = OLD.group_id
       AND host_id  = OLD.user_id
       AND status IN ('scheduled','confirmed','in_progress');
    IF v_active_games > 0 THEN
      RAISE EXCEPTION 'MEMBER_IS_ACTIVE_GAME_HOST'
            USING HINT = 'member hosts ' || v_active_games
                      || ' active game(s) in this group; cancel or reassign them first';
    END IF;
  END IF;

  -- Service-role / postgres / RPC bypass
  IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                'supabase_auth_admin', 'supabase_storage_admin') THEN
    RETURN OLD;
  END IF;

  -- Self-delete: allowed UNLESS status='banned' (ban-evasion prevention)
  IF OLD.user_id = v_caller THEN
    IF OLD.status = 'banned' THEN
      RAISE EXCEPTION 'BANNED_CANNOT_LEAVE'
            USING HINT = 'banned members cannot leave the group to erase the ban record; '
                      || 'contact a group admin if you believe the ban is a mistake';
    END IF;
    RETURN OLD;
  END IF;

  -- Staff kick via RPC (manage_home_group_member sets this GUC)
  IF COALESCE(current_setting('app.hg_member_remove_allowed', true), '') = '1' THEN
    RETURN OLD;
  END IF;

  -- Otherwise: block. Staff must use manage_home_group_member RPC.
  RAISE EXCEPTION 'DIRECT_MEMBER_DELETE_FORBIDDEN'
        USING HINT = 'use manage_home_group_member RPC with action=remove '
                  || 'so the kick is audit-logged and notifications are sent';
END;
$$;


ALTER FUNCTION public.fn_enforce_home_members_delete() OWNER TO postgres;

--
-- Name: FUNCTION fn_enforce_home_members_delete(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_enforce_home_members_delete() IS 'Pass 34 + 36: Enforces audit trail on commander_home_members DELETE. Blocks direct DELETE unless: self-leave (not banned), staff RPC kick (GUC app.hg_member_remove_allowed=1), or service-role. Active-game-host guard fires for everyone unless GUC app.hg_skip_active_host_check=1. Pass 36: self-leave while status=banned is now blocked to prevent ban evasion.';


--
-- Name: fn_enforce_home_members_self_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_home_members_self_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_private boolean;
  v_is_staff   boolean;
BEGIN
  IF auth.role() = 'service_role' OR auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  -- Token-redeem path carveout: RPC set this flag immediately before
  -- INSERT/UPDATE and clears it immediately after.
  IF COALESCE(current_setting('app.hg_token_redeem_allowed', true), '') = '1' THEN
    RETURN NEW;
  END IF;

  v_is_staff := fn_home_is_group_staff(auth.uid(), NEW.group_id);
  IF v_is_staff THEN RETURN NEW; END IF;

  IF NEW.user_id = auth.uid() THEN
    IF NEW.role IS DISTINCT FROM 'member' THEN
      NEW.role := 'member';
    END IF;

    SELECT is_private INTO v_is_private
      FROM commander_home_groups WHERE id = NEW.group_id;

    IF v_is_private THEN
      NEW.status := 'pending';
    ELSE
      IF COALESCE(NEW.status, '') NOT IN ('pending', 'approved') THEN
        NEW.status := 'pending';
      END IF;
    END IF;

    IF NEW.status = 'approved' AND NEW.joined_at IS NULL THEN
      NEW.joined_at := NOW();
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_home_members_self_insert() OWNER TO postgres;

--
-- Name: fn_enforce_home_poll_field_permissions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_home_poll_field_permissions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
    v_vote_count int;
BEGIN
    IF auth.role() = 'service_role' OR auth.uid() IS NULL THEN RETURN NEW; END IF;
    IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;

    -- Identity fields always immutable
    IF NEW.group_id  IS DISTINCT FROM OLD.group_id
       OR NEW.created_by IS DISTINCT FROM OLD.created_by
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
    THEN
      RAISE EXCEPTION 'IMMUTABLE_FIELD'
            USING HINT = 'group_id, created_by, and created_at are immutable';
    END IF;

    -- Options / question / type: frozen once votes exist
    IF NEW.options   IS DISTINCT FROM OLD.options
       OR NEW.question  IS DISTINCT FROM OLD.question
       OR NEW.poll_type IS DISTINCT FROM OLD.poll_type
    THEN
      SELECT COUNT(*) INTO v_vote_count
        FROM commander_home_poll_votes
       WHERE poll_id = NEW.id;

      IF v_vote_count > 0 THEN
        RAISE EXCEPTION 'POLL_HAS_VOTES'
              USING HINT = 'cannot modify question, options, or poll_type after '
                         || 'votes are cast; close the poll and create a new one';
      END IF;
    END IF;

    RETURN NEW;
END;
$$;


