--
-- Name: FUNCTION fn_enforce_home_poll_field_permissions(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_enforce_home_poll_field_permissions() IS 'Phase 40 Bug 49: freezes question/options/poll_type once a vote exists. is_closed and closes_at remain mutable so hosts can still close polls.';


--
-- Name: fn_enforce_home_poll_vote_integrity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_home_poll_vote_integrity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text := current_user;
  v_poll RECORD;
  v_valid_ids text[];
  v_bad_ids   text[];
BEGIN
  IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                'supabase_auth_admin', 'supabase_storage_admin') THEN
    RETURN NEW;
  END IF;

  SELECT id, is_closed, closes_at, options INTO v_poll
    FROM commander_home_polls WHERE id = NEW.poll_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'POLL_NOT_FOUND' USING HINT = 'poll_id does not exist';
  END IF;

  IF v_poll.is_closed = true THEN
    RAISE EXCEPTION 'POLL_CLOSED' USING HINT = 'cannot vote on a closed poll';
  END IF;
  IF v_poll.closes_at IS NOT NULL AND v_poll.closes_at < now() THEN
    RAISE EXCEPTION 'POLL_EXPIRED' USING HINT = 'voting closed at ' || v_poll.closes_at::text;
  END IF;

  SELECT array_agg(value->>'id') INTO v_valid_ids
    FROM jsonb_array_elements(v_poll.options) AS value;

  IF NEW.option_ids IS NULL OR array_length(NEW.option_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'NO_OPTIONS_SELECTED'
          USING HINT = 'option_ids must contain at least one option id';
  END IF;

  SELECT array_agg(x) INTO v_bad_ids
    FROM unnest(NEW.option_ids) AS x
    WHERE x <> ALL(COALESCE(v_valid_ids, ARRAY[]::text[]));

  IF v_bad_ids IS NOT NULL AND array_length(v_bad_ids, 1) > 0 THEN
    RAISE EXCEPTION 'INVALID_POLL_OPTION'
          USING HINT = 'option_ids not present on poll: ' || array_to_string(v_bad_ids, ',');
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_home_poll_vote_integrity() OWNER TO postgres;

--
-- Name: fn_enforce_home_polls_lifecycle(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_home_polls_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_role text := current_user;
BEGIN
  IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                'supabase_auth_admin', 'supabase_storage_admin') THEN
    RETURN NEW;
  END IF;

  -- updated_at: system-managed
  IF NEW.updated_at IS DISTINCT FROM OLD.updated_at THEN
    RAISE EXCEPTION 'SYSTEM_ONLY_FIELD'
          USING HINT = 'updated_at is managed by triggers; do not include in payload';
  END IF;

  -- is_closed: sticky
  IF OLD.is_closed = true AND COALESCE(NEW.is_closed, false) = false THEN
    RAISE EXCEPTION 'POLL_CLOSED_TERMINAL'
          USING HINT = 'closed polls cannot be reopened; create a new poll instead';
  END IF;

  -- closes_at: cannot move into the past on an active (open) poll
  IF NEW.closes_at IS DISTINCT FROM OLD.closes_at
     AND COALESCE(OLD.is_closed, false) = false
     AND NEW.closes_at IS NOT NULL
     AND NEW.closes_at < now() THEN
    RAISE EXCEPTION 'POLL_CLOSES_AT_PAST'
          USING HINT = 'cannot move closes_at into the past; set is_closed=true to close the poll';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_home_polls_lifecycle() OWNER TO postgres;

--
-- Name: fn_enforce_home_post_comments_integrity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_home_post_comments_integrity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text := current_user;
BEGIN
  -- Service-role / postgres / RPC bypass. Direct PostgREST writes run as
  -- 'authenticated' or 'anon' and are gated.
  IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                'supabase_auth_admin', 'supabase_storage_admin') THEN
    RETURN NEW;
  END IF;

  -- created_at: immutable (identity-adjacent, breaks thread ordering if mutable)
  IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'SYSTEM_ONLY_FIELD'
          USING HINT = 'created_at is immutable on comments; '
                    || 'changing it breaks thread ordering and audit trails';
  END IF;

  -- updated_at: system-managed by trg_touch_updated_at (runs at depth>1).
  -- Reject any user-originated updated_at in the payload.
  IF NEW.updated_at IS DISTINCT FROM OLD.updated_at THEN
    RAISE EXCEPTION 'SYSTEM_ONLY_FIELD'
          USING HINT = 'updated_at is managed by trg_touch_updated_at; '
                    || 'do not include it in UPDATE payloads';
  END IF;

  -- Content edit → auto-flip is_edited to true BEFORE the update commits.
  IF NEW.content IS DISTINCT FROM OLD.content THEN
    NEW.is_edited := true;
  END IF;

  -- is_edited is sticky: cannot go true→false via user UPDATE.
  -- (A user explicitly setting is_edited=true is fine.)
  IF OLD.is_edited = true AND NEW.is_edited = false THEN
    RAISE EXCEPTION 'IS_EDITED_STICKY'
          USING HINT = 'is_edited cannot be reset to false once an edit has been recorded';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_home_post_comments_integrity() OWNER TO postgres;

--
-- Name: fn_enforce_home_post_field_permissions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_home_post_field_permissions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_host boolean;
BEGIN
  -- Service role and non-RLS paths bypass (legitimate server code)
  IF auth.role() = 'service_role' OR v_caller IS NULL THEN RETURN NEW; END IF;
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;

  IF TG_OP = 'INSERT' THEN
    -- BH-1: force server-maintained counters to 0 on insert (don't trust client)
    NEW.likes_count    := COALESCE(0, NEW.likes_count);
    NEW.comments_count := COALESCE(0, NEW.comments_count);
    -- Explicit override (not just COALESCE - client may have sent any value):
    NEW.likes_count    := 0;
    NEW.comments_count := 0;

    -- BH-3: force server-stamped timestamp on insert (prevent backdating
    -- or future-dating). Use transaction timestamp for consistency.
    NEW.created_at := now();

    -- BH-2: is_pinned on insert requires host/owner/admin of the group
    IF COALESCE(NEW.is_pinned, false) = true THEN
      SELECT
        EXISTS (SELECT 1 FROM commander_home_groups gr
                 WHERE gr.id = NEW.group_id AND gr.owner_id = v_caller)
        OR EXISTS (SELECT 1 FROM commander_home_members m
                   WHERE m.group_id = NEW.group_id
                     AND m.user_id = v_caller
                     AND m.role = 'admin'
                     AND m.status = 'approved')
      INTO v_is_host;

      IF NOT v_is_host THEN
        RAISE EXCEPTION 'HOST_ONLY_FIELD'
              USING HINT = 'is_pinned is a moderation flag; only group owner '
                        || 'or admin can create pinned posts';
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  -- ─────── UPDATE path (preserved from original) ───────

  -- Computed/system fields
  IF NEW.likes_count    IS DISTINCT FROM OLD.likes_count
     OR NEW.comments_count IS DISTINCT FROM OLD.comments_count
     OR NEW.created_at  IS DISTINCT FROM OLD.created_at
  THEN
    RAISE EXCEPTION 'IMMUTABLE_OR_COMPUTED_FIELD'
          USING HINT = 'likes_count, comments_count, created_at are '
                     || 'maintained by the system';
  END IF;

  -- is_pinned: host / group owner / admin only
  IF NEW.is_pinned IS DISTINCT FROM OLD.is_pinned THEN
    SELECT
      EXISTS (SELECT 1 FROM commander_home_groups gr
               WHERE gr.id = NEW.group_id AND gr.owner_id = v_caller)
      OR EXISTS (SELECT 1 FROM commander_home_members m
                 WHERE m.group_id = NEW.group_id
                   AND m.user_id = v_caller
                   AND m.role = 'admin'
                   AND m.status = 'approved')
    INTO v_is_host;

    IF NOT v_is_host THEN
      RAISE EXCEPTION 'HOST_ONLY_FIELD'
            USING HINT = 'is_pinned is a moderation flag; only group owner or '
                      || 'admin can pin/unpin posts';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_home_post_field_permissions() OWNER TO postgres;

--
-- Name: FUNCTION fn_enforce_home_post_field_permissions(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_enforce_home_post_field_permissions() IS 'Pass 44: Enforces server-maintained field integrity on home posts for both INSERT and UPDATE. On INSERT: forces likes_count=0, comments_count=0, created_at=now(); requires host/admin for is_pinned=true. On UPDATE: blocks mutation of likes_count/comments_count/created_at; requires host/admin for is_pinned flip. Seals BH-1/BH-2/BH-3.';


--
-- Name: fn_enforce_home_posts_edit_integrity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_home_posts_edit_integrity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_role text := current_user;
BEGIN
  IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                'supabase_auth_admin', 'supabase_storage_admin') THEN
    RETURN NEW;
  END IF;

  -- updated_at: system-managed (touch trigger runs at depth>0 next)
  IF NEW.updated_at IS DISTINCT FROM OLD.updated_at
     AND pg_trigger_depth() = 1 THEN
    RAISE EXCEPTION 'SYSTEM_ONLY_FIELD'
          USING HINT = 'updated_at is managed by trg_home_posts_touch_updated_at';
  END IF;

  -- Auto-flip on content/media change
  IF NEW.content IS DISTINCT FROM OLD.content
     OR NEW.image_urls IS DISTINCT FROM OLD.image_urls
     OR NEW.video_url IS DISTINCT FROM OLD.video_url THEN
    NEW.is_edited := true;
  END IF;

  -- Sticky
  IF OLD.is_edited = true AND NEW.is_edited = false THEN
    RAISE EXCEPTION 'IS_EDITED_STICKY'
          USING HINT = 'is_edited cannot be reset once recorded';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_home_posts_edit_integrity() OWNER TO postgres;

