--
-- Name: fn_enforce_home_rsvp_field_permissions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_home_rsvp_field_permissions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
    v_caller uuid := auth.uid();
    v_is_self boolean;
    v_is_host boolean;
    v_rpc_selfcheckin boolean := false;
BEGIN
    IF auth.role() = 'service_role' OR v_caller IS NULL THEN RETURN NEW; END IF;
    IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;

    v_is_self := (NEW.user_id = v_caller);

    SELECT
      EXISTS (SELECT 1 FROM commander_home_games g
               WHERE g.id = NEW.game_id AND g.host_id = v_caller)
      OR EXISTS (SELECT 1 FROM commander_home_games g
                 JOIN commander_home_groups gr ON gr.id = g.group_id
                 WHERE g.id = NEW.game_id AND gr.owner_id = v_caller)
      OR EXISTS (SELECT 1 FROM commander_home_games g
                 JOIN commander_home_members m ON m.group_id = g.group_id
                 WHERE g.id = NEW.game_id
                   AND m.user_id = v_caller
                   AND m.role = 'admin'
                   AND m.status = 'approved')
    INTO v_is_host;

    -- GUC-gated self-checkin: only valid when the claim_home_game_seat
    -- (or successor) RPC explicitly sets app.hg_self_checkin_allowed='1'.
    -- Direct PostgREST self-check-in is blocked.
    v_rpc_selfcheckin := (
      v_is_self
      AND OLD.checked_in_at IS NULL
      AND NEW.checked_in_at IS NOT NULL
      AND COALESCE(current_setting('app.hg_self_checkin_allowed', true), '') = '1'
    );

    IF NEW.checked_in_at IS DISTINCT FROM OLD.checked_in_at
       OR NEW.checked_in_by IS DISTINCT FROM OLD.checked_in_by
       OR NEW.flaked        IS DISTINCT FROM OLD.flaked
       OR NEW.final_result_note IS DISTINCT FROM OLD.final_result_note
    THEN
      IF NOT v_is_host AND NOT v_rpc_selfcheckin THEN
        RAISE EXCEPTION 'HOST_ONLY_FIELD'
              USING HINT = 'checked_in_at, checked_in_by, flaked, final_result_note '
                         || 'can only be set by game host / group owner / admin';
      END IF;
    END IF;

    IF NEW.seat_number IS DISTINCT FROM OLD.seat_number THEN
      IF NOT v_is_host AND NOT v_is_self THEN
        RAISE EXCEPTION 'HOST_OR_SELF_ONLY_FIELD'
              USING HINT = 'seat_number can only be set by the RSVPing user or host/owner/admin';
      END IF;
    END IF;

    IF NEW.is_confirmed IS DISTINCT FROM OLD.is_confirmed THEN
      IF NOT v_is_host THEN
        IF NOT (v_is_self AND NEW.is_confirmed = false) THEN
          RAISE EXCEPTION 'HOST_ONLY_CONFIRMATION'
                USING HINT = 'only host/owner/admin can set is_confirmed=true';
        END IF;
      END IF;
    END IF;

    IF NEW.reminder_6h_sent_at IS DISTINCT FROM OLD.reminder_6h_sent_at
       OR NEW.reminder_1h_sent_at IS DISTINCT FROM OLD.reminder_1h_sent_at
       OR NEW.review_prompt_sent_at IS DISTINCT FROM OLD.review_prompt_sent_at
    THEN
      RAISE EXCEPTION 'SYSTEM_ONLY_FIELD'
            USING HINT = 'reminder/review timestamps are managed by the system';
    END IF;

    IF NEW.responded_at IS DISTINCT FROM OLD.responded_at THEN
      IF NOT v_is_host AND NOT v_is_self THEN
        RAISE EXCEPTION 'HOST_OR_SELF_ONLY_FIELD'
              USING HINT = 'responded_at can only be set by the RSVPing user or host/owner/admin';
      END IF;
    END IF;

    -- Pass 13 / pass 17 restore: updated_at is system-managed by
    -- trg_touch_updated_at which fires at pg_trigger_depth > 1 (handled
    -- by the early bypass above). User-initiated UPDATE payloads cannot
    -- include updated_at - blocks ordering-based log/digest tampering.
    IF NEW.updated_at IS DISTINCT FROM OLD.updated_at THEN
      RAISE EXCEPTION 'SYSTEM_ONLY_FIELD'
            USING HINT = 'updated_at is managed by trg_touch_updated_at; '
                      || 'do not include it in RSVP UPDATE payloads';
    END IF;

    IF NEW.response IS DISTINCT FROM OLD.response
       OR NEW.bringing_guests IS DISTINCT FROM OLD.bringing_guests
    THEN
      IF NOT v_is_self AND NOT v_is_host THEN
        RAISE EXCEPTION 'RSVP_OWNER_OR_HOST_ONLY_FIELD'
              USING HINT = 'response/bringing_guests can only be changed by the RSVPing user or host/owner/admin';
      END IF;
    END IF;

    IF NEW.message IS DISTINCT FROM OLD.message
       OR NEW.guest_names IS DISTINCT FROM OLD.guest_names
       OR NEW.rsvp_reason IS DISTINCT FROM OLD.rsvp_reason
    THEN
      IF NOT v_is_self THEN
        RAISE EXCEPTION 'RSVP_OWNER_ONLY_FIELD'
              USING HINT = 'only the RSVPing user can change their message, guest names, or rsvp reason';
      END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_home_rsvp_field_permissions() OWNER TO postgres;

--
-- Name: FUNCTION fn_enforce_home_rsvp_field_permissions(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_enforce_home_rsvp_field_permissions() IS 'Phase 40 Bug 47 + regression fix: host-only attendance fields, with a narrow exception for RSVP-owner first-stamping checked_in_at from NULL (preserves claim_home_game_seat semantics). Once stamped, only host/owner/admin can modify.';


--
-- Name: fn_enforce_leaderboard_program_funding(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_leaderboard_program_funding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_balance numeric := 0;
  v_other_commitments numeric := 0;
  v_requested_commitment numeric := 0;
BEGIN
  v_requested_commitment := public.fn_leaderboard_program_commitment(
    NEW.rewards_enabled,
    NEW.weekly_prizes,
    NEW.monthly_prizes
  );

  IF NOT NEW.rewards_enabled THEN
    RETURN NEW;
  END IF;

  IF NEW.funding_owner_type = 'union' THEN
    IF NEW.funding_union_id IS NULL THEN
      RAISE EXCEPTION 'A Union-Funded Leaderboard Requires A Funding Union'
        USING ERRCODE = '23514';
    END IF;
    SELECT COALESCE(wallet.promo_wallet, 0)
      INTO v_balance
      FROM public.union_wallets wallet
     WHERE wallet.union_id = NEW.funding_union_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Leaderboard Funding Union Has No Promo Wallet'
        USING ERRCODE = '55000';
    END IF;
  ELSIF NEW.funding_owner_type = 'club' THEN
    IF NEW.funding_union_id IS NOT NULL THEN
      RAISE EXCEPTION 'A Standalone Club Leaderboard Cannot Name A Funding Union'
        USING ERRCODE = '23514';
    END IF;
    SELECT COALESCE(club.promo_balance, 0)
      INTO v_balance
      FROM public.clubs club
     WHERE club.id = NEW.club_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Club Not Found' USING ERRCODE = 'P0002';
    END IF;
  ELSE
    RAISE EXCEPTION 'Leaderboard Funding Owner Must Be A Union Or Club'
      USING ERRCODE = '23514';
  END IF;

  WITH latest AS MATERIALIZED (
    SELECT DISTINCT ON (program.club_id)
      program.club_id,
      program.rewards_enabled,
      program.weekly_prizes,
      program.monthly_prizes,
      program.funding_owner_type,
      program.funding_union_id
    FROM public.leaderboard_reward_program_versions program
    WHERE program.club_id <> NEW.club_id
    ORDER BY program.club_id, program.version DESC
  )
  SELECT COALESCE(sum(public.fn_leaderboard_program_commitment(
    latest.rewards_enabled,
    latest.weekly_prizes,
    latest.monthly_prizes
  )), 0)
  INTO v_other_commitments
  FROM latest
  WHERE NEW.funding_owner_type = 'union'
    AND latest.funding_owner_type = 'union'
    AND latest.funding_union_id = NEW.funding_union_id;

  IF v_requested_commitment + v_other_commitments > v_balance THEN
    RAISE EXCEPTION
      'Leaderboard Prize Program Requires % Promo Chips But Only % Are Available After Other Published Commitments',
      round(v_requested_commitment, 2),
      round(GREATEST(v_balance - v_other_commitments, 0), 2)
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


