--
-- Name: fn_enforce_rsvp_deadline(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_rsvp_deadline() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_game RECORD;
BEGIN
    IF auth.uid() IS NULL THEN RETURN NEW; END IF;  -- service bypass (cron/trigger)

    SELECT rsvps_closed, rsvp_closes_at, status, scheduled_date, start_time
      INTO v_game
      FROM commander_home_games WHERE id = NEW.game_id;
    IF NOT FOUND THEN RETURN NEW; END IF;

    -- Reject RSVPs on cancelled games (matches rsvp_to_home_game RPC behaviour).
    IF v_game.status = 'cancelled' THEN
        RAISE EXCEPTION 'GAME_CANCELLED'
              USING HINT = 'cannot RSVP to a cancelled game';
    END IF;

    -- Reject RSVPs on non-RSVPable statuses.
    IF v_game.status IS NOT NULL
       AND v_game.status NOT IN ('scheduled','confirmed','in_progress','completed') THEN
        RAISE EXCEPTION 'GAME_NOT_OPEN_FOR_RSVP'
              USING HINT = 'game status is ' || v_game.status;
    END IF;

    IF v_game.rsvps_closed = true THEN
        RAISE EXCEPTION 'RSVPS_CLOSED' USING HINT='host has closed RSVPs for this game';
    END IF;

    IF v_game.rsvp_closes_at IS NOT NULL AND v_game.rsvp_closes_at < NOW() THEN
        RAISE EXCEPTION 'RSVP_DEADLINE_PASSED'
              USING HINT='RSVP deadline was ' || v_game.rsvp_closes_at::text;
    END IF;

    RETURN NEW;
END; $$;


ALTER FUNCTION public.fn_enforce_rsvp_deadline() OWNER TO postgres;

--
-- Name: fn_enforce_seat_reservation_deadline(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_seat_reservation_deadline() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_table  RECORD;
  v_game   RECORD;
  v_cutoff timestamptz;
  v_must_gate boolean := false;
  v_is_materialization boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN RETURN NEW; END IF;

  IF TG_OP = 'INSERT' THEN
    v_must_gate := true;
  ELSIF TG_OP = 'UPDATE' THEN
    -- Detect legitimate start_table materialization shape: reserved→seated
    -- with no other field changes. This is ONLY produced by rpc_hg_start_table.
    v_is_materialization := (
      OLD.status = 'reserved'
      AND NEW.status = 'seated'
      AND OLD.table_id = NEW.table_id
      AND OLD.seat_number = NEW.seat_number
      AND OLD.user_id IS NOT DISTINCT FROM NEW.user_id
      AND OLD.is_guest = NEW.is_guest
      AND OLD.claimed_by_user_id = NEW.claimed_by_user_id
    );

    IF NOT v_is_materialization THEN
      -- Transition into an active state (other than the exempt one) → gate
      IF NEW.status IN ('reserved','seated')
         AND (OLD.status IS DISTINCT FROM NEW.status) THEN
        v_must_gate := true;
      END IF;
      -- Seat-number change while active → gate (Dan's #6)
      IF NEW.status IN ('reserved','seated')
         AND NEW.seat_number IS DISTINCT FROM OLD.seat_number THEN
        v_must_gate := true;
      END IF;
    END IF;
  END IF;

  IF NOT v_must_gate THEN
    RETURN NEW;
  END IF;

  SELECT id, game_id, status, max_seats
    INTO v_table
    FROM public.commander_home_game_tables
   WHERE id = NEW.table_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND' USING HINT = 'table_id does not exist';
  END IF;

  IF v_table.status = 'cancelled' THEN RAISE EXCEPTION 'TABLE_CANCELLED'; END IF;
  IF v_table.status = 'ended'     THEN RAISE EXCEPTION 'TABLE_ENDED';     END IF;
  IF v_table.status = 'running' THEN
    RAISE EXCEPTION 'TABLE_RUNNING'
      USING HINT = 'once a table is running, seating is managed via Club Commander';
  END IF;
  IF v_table.status = 'draft' THEN
    RAISE EXCEPTION 'TABLE_NOT_OPEN_FOR_RSVP'
      USING HINT = 'host has not opened this table for RSVPs yet';
  END IF;

  IF NEW.seat_number > v_table.max_seats THEN
    RAISE EXCEPTION 'SEAT_OUT_OF_BOUNDS'
      USING HINT = format('seat %s exceeds table max_seats %s',
                           NEW.seat_number, v_table.max_seats);
  END IF;

  SELECT id, status, rsvps_closed, rsvp_closes_at,
         scheduled_date, start_time, cancelled_at
    INTO v_game
    FROM public.commander_home_games
   WHERE id = v_table.game_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  IF v_game.cancelled_at IS NOT NULL OR v_game.status = 'cancelled' THEN
    RAISE EXCEPTION 'GAME_CANCELLED';
  END IF;
  IF v_game.rsvps_closed = true THEN
    RAISE EXCEPTION 'RSVPS_CLOSED'
      USING HINT = 'host has closed RSVPs for this game';
  END IF;
  IF v_game.rsvp_closes_at IS NOT NULL AND v_game.rsvp_closes_at < now() THEN
    RAISE EXCEPTION 'RSVP_DEADLINE_PASSED'
      USING HINT = 'RSVP deadline was ' || v_game.rsvp_closes_at::text;
  END IF;

  IF v_game.scheduled_date IS NOT NULL AND v_game.start_time IS NOT NULL THEN
    v_cutoff := (v_game.scheduled_date + v_game.start_time)::timestamptz;
    IF v_cutoff < now() THEN
      RAISE EXCEPTION 'GAME_START_TIME_PASSED'
        USING HINT = 'game started at ' || v_cutoff::text
                  || '; live seating is owned by Club Commander after start';
    END IF;
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_enforce_seat_reservation_deadline() OWNER TO postgres;

--
-- Name: fn_enforce_seat_reservation_immutability(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_seat_reservation_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text := current_user;
  v_is_service boolean;
BEGIN
  v_is_service := v_role IN ('postgres', 'supabase_admin', 'service_role',
                             'supabase_auth_admin', 'supabase_storage_admin');

  IF v_is_service THEN
    RETURN NEW;
  END IF;

  -- Pure identity columns: immutable (unchanged from prior pass 7)
  IF NEW.table_id IS DISTINCT FROM OLD.table_id THEN
    RAISE EXCEPTION 'RESERVATION_IMMUTABLE'
          USING HINT = 'table_id cannot be changed on an existing reservation';
  END IF;
  IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'RESERVATION_IMMUTABLE'
          USING HINT = 'user_id cannot be changed on an existing reservation';
  END IF;
  IF NEW.claimed_by_user_id IS DISTINCT FROM OLD.claimed_by_user_id THEN
    RAISE EXCEPTION 'RESERVATION_IMMUTABLE'
          USING HINT = 'claimed_by_user_id cannot be changed on an existing reservation';
  END IF;
  IF NEW.is_guest IS DISTINCT FROM OLD.is_guest THEN
    RAISE EXCEPTION 'RESERVATION_IMMUTABLE'
          USING HINT = 'is_guest cannot be flipped on an existing reservation';
  END IF;
  IF NEW.member_id IS DISTINCT FROM OLD.member_id THEN
    RAISE EXCEPTION 'RESERVATION_IMMUTABLE'
          USING HINT = 'member_id cannot be changed on an existing reservation';
  END IF;

  -- NEW in pass 33: seat_number cannot be changed via direct UPDATE.
  -- Must go through rpc_hg_change_seat (SECURITY DEFINER → bypass above).
  IF NEW.seat_number IS DISTINCT FROM OLD.seat_number THEN
    RAISE EXCEPTION 'SEAT_CHANGE_REQUIRES_RPC'
          USING HINT = 'seat_number changes must go through rpc_hg_change_seat '
                    || 'to maintain atomicity and shadow-rsvp sync';
  END IF;

  -- Status transitions (layered rule)
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF OLD.status = 'released' THEN
      RAISE EXCEPTION 'RESERVATION_STATUS_TERMINAL'
            USING HINT = 'released reservations cannot be resurrected';
    END IF;
    -- NEW in pass 33: users cannot self-promote reserved → seated.
    -- That transition is ONLY legitimate via rpc_hg_start_table
    -- (SECURITY DEFINER → bypass above).
    IF OLD.status = 'reserved' AND NEW.status = 'seated' THEN
      RAISE EXCEPTION 'SEAT_MATERIALIZATION_REQUIRES_RPC'
            USING HINT = 'reserved → seated transition is owned by '
                      || 'rpc_hg_start_table (host materialization). '
                      || 'Users can release a reservation but not seat '
                      || 'themselves directly.';
    END IF;
    IF OLD.status = 'reserved' AND NEW.status NOT IN ('seated','released') THEN
      RAISE EXCEPTION 'INVALID_RESERVATION_TRANSITION'
            USING HINT = 'from reserved, only seated or released are allowed (got '||NEW.status||')';
    END IF;
    IF OLD.status = 'seated' AND NEW.status <> 'released' THEN
      RAISE EXCEPTION 'INVALID_RESERVATION_TRANSITION'
            USING HINT = 'from seated, only released is allowed (got '||NEW.status||')';
    END IF;
  END IF;

  IF NEW.guest_name IS DISTINCT FROM OLD.guest_name THEN
    IF OLD.is_guest = false OR OLD.status <> 'reserved' THEN
      RAISE EXCEPTION 'GUEST_NAME_LOCKED'
            USING HINT = 'guest_name is only editable on reserved guest seats';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_seat_reservation_immutability() OWNER TO postgres;

--
-- Name: fn_enforce_table_union_ownership_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_table_union_ownership_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_union uuid;
BEGIN
  IF COALESCE(NEW.is_private, false) THEN
    NEW.union_id := NULL;
    RETURN NEW;
  END IF;
  IF NEW.club_id IS NOT NULL THEN
    SELECT uc.union_id INTO v_union FROM union_clubs uc WHERE uc.club_id = NEW.club_id LIMIT 1;
    IF v_union IS NOT NULL AND NEW.union_id IS DISTINCT FROM v_union THEN
      NEW.union_id := v_union;
    END IF;
  END IF;
  IF NEW.union_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM clubs c WHERE c.id = NEW.union_id) THEN
    NEW.club_id := NEW.union_id;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_enforce_table_union_ownership_update() OWNER TO postgres;

--
-- Name: fn_enforce_tournament_capacity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enforce_tournament_capacity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_max int;
  v_have int;
  v_name text;
  v_status text;
  v_variant text;
  v_seat_first boolean;
BEGIN
  /* UNDER THE ROW LOCK (2026-09-06). This read the tournament without one, so
     two entries arriving together could both see room and both be admitted.
     Parent before child - the order every registration door already uses. */
  SELECT max_players, name, status, COALESCE(variant, '')
    INTO v_max, v_name, v_status, v_variant
    FROM public.tournaments WHERE id = NEW.tournament_id
    FOR NO KEY UPDATE;

  -- No declared capacity means no capacity to exceed (open MTTs).
  IF v_max IS NULL OR v_max <= 0 THEN
    RETURN NEW;
  END IF;

  /* 'sng' JOINS 'spin' (2026-09-06). fn_sync_seat_first_player_count has
     always counted ('spin','sng') OR max <= 2 as seat-first; this said
     'spin' OR max <= 2. All 35 overfilled events were sng, and they qualified
     only on the <= 2 half - a six-max sng was outside the rule entirely. */
  v_seat_first := (v_variant IN ('spin', 'sng') OR v_max <= 2);

  -- A seat-first board sells its seats once. After it stops being joinable it
  -- admits nobody, however many of its entrants have since busted.
  IF v_seat_first
     AND upper(COALESCE(v_status, '')) NOT IN ('ANNOUNCED', 'REGISTERING') THEN
    RAISE EXCEPTION
      'tournament_full: % is % and takes no further entrants',
      COALESCE(v_name, NEW.tournament_id::text), lower(v_status)
      USING ERRCODE = '23514';
  END IF;

  IF v_seat_first THEN
    /* AN ENTRY, NOT A SURVIVOR (2026-09-06). This branch used to exclude
       eliminated, winner, left, withdrawn, cancelled, refunded and busted -
       the right rule for a seat and the wrong one for an entry. On a
       two-handed board it meant a bust-out put a sold seat back on sale, and
       35 events took between 3 and 32 paid entries because of it. The board
       sold its seats; what became of the players who bought them is not a
       vacancy. */
    SELECT count(*) INTO v_have
      FROM public.tournament_players
     WHERE tournament_id = NEW.tournament_id;
  ELSE
    -- Multi-table events are unchanged: a busted entrant does not hold a seat
    -- against the next one on a board that is still filling.
    SELECT count(*) INTO v_have
      FROM public.tournament_players
     WHERE tournament_id = NEW.tournament_id
       AND COALESCE(status, 'registered') NOT IN
           ('eliminated', 'winner', 'left', 'withdrawn', 'cancelled', 'refunded', 'busted');
  END IF;

  IF v_have >= v_max THEN
    RAISE EXCEPTION
      'tournament_full: % already has % of % entrants', COALESCE(v_name, NEW.tournament_id::text), v_have, v_max
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enforce_tournament_capacity() OWNER TO postgres;

--
-- Name: FUNCTION fn_enforce_tournament_capacity(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_enforce_tournament_capacity() IS 'Capacity guard on tournament_players. A seat-first board (spin, sng, or max_players <= 2) counts EVERY entry, because a bust-out does not put a sold seat back on sale; a multi-table event counts live entrants as before. Reads the tournament row FOR NO KEY UPDATE so two entries arriving together cannot both find room.';


