--
-- Name: fn_enqueue_hand_daily_missions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_enqueue_hand_daily_missions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_event jsonb;
  v_uid uuid;
BEGIN
  IF jsonb_typeof(NEW.daily_mission_events)<>'array' THEN RETURN NEW; END IF;
  FOR v_event IN
    SELECT value FROM jsonb_array_elements(NEW.daily_mission_events)
     ORDER BY value->>'user_id',value::text
  LOOP
    BEGIN
      v_uid := (v_event->>'user_id')::uuid;
      IF v_uid IS NULL THEN CONTINUE; END IF;
      INSERT INTO public.daily_challenge_event_outbox
        (user_id,event_key,amounts,magnitudes,threshold_values,occurred_at)
      VALUES (
        v_uid,
        'hand:'||NEW.id::text,
        v_event->'amounts',
        coalesce(v_event->'magnitudes','{}'::jsonb),
        coalesce(v_event->'values','{}'::jsonb),
        coalesce(NEW.ended_at,NEW.created_at,now())
      )
      ON CONFLICT (user_id,event_key) DO NOTHING;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Daily Missions hand event % could not be queued: %',NEW.id,SQLERRM;
    END;
  END LOOP;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_enqueue_hand_daily_missions() OWNER TO postgres;

--
-- Name: FUNCTION fn_enqueue_hand_daily_missions(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_enqueue_hand_daily_missions() IS 'AFTER INSERT on hand_history: writes one daily_challenge_event_outbox row per player in the hand and returns. The booking (receipt, challenge bumps) is done by fn_drain_daily_challenge_event_outbox within the minute. Was synchronous until 2026-09-08 and cost ~280 ms of every hand insert.';


--
-- Name: fn_ensure_agent_row(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ensure_agent_row(p_club_id uuid, p_user_id uuid, p_role text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id    uuid;
  v_union uuid;
  v_min   numeric;
  v_role  text;
  v_staff boolean;
begin
  select a.id into v_id
    from agents a
   where a.club_id = p_club_id and a.user_id = p_user_id
   for update;
  if v_id is not null then
    return v_id;
  end if;

  -- agents.role CHECK still admits only the three agent tiers, so a staff
  -- wallet holder is stored as 'super_agent'. The data lies about who holds the
  -- wallet; club_members.role is the truth and every rule reads it. Recorded as
  -- P3 debt for phase 7, not fixed here, because relaxing that CHECK is a table
  -- lock on agents and this migration deliberately takes none.
  v_role := case when p_role in ('super_agent', 'agent', 'sub_agent') then p_role
                 else 'super_agent' end;

  v_staff := exists (
    select 1 from club_members cm
     where cm.club_id = p_club_id and cm.user_id = p_user_id
       and cm.role in ('co_owner', 'admin'));

  select coalesce(uc.union_id, c.union_id) into v_union
    from clubs c
    left join union_clubs uc on uc.club_id = c.id
   where c.id = p_club_id
   limit 1;

  -- A rate nobody chose is the bug phase 0 removed from the promotion path.
  -- Staff earn nothing by law, so minting them at the union minimum invented a
  -- commission AND tripped the band on the way back down to zero.
  v_min := case when v_staff then 0
                when v_union is null then 0
                else public.fn_union_setting(v_union, 'min_agent_commission', 0) end;

  -- Prepaid with no line: a wallet that appears because somebody was sent chips
  -- must not also arrive able to borrow. A credit line is granted deliberately,
  -- through the promotion screen or the agent panel, never as a side effect.
  insert into agents (user_id, club_id, role, status,
                      agent_wallet_balance, promo_wallet_balance,
                      commission_rate, player_rakeback_rate,
                      credit_limit, credit_used, is_prepaid)
  values (p_user_id, p_club_id, v_role, 'active', 0, 0, v_min, 0, 0, 0, true)
  on conflict (user_id, club_id) do nothing;

  select a.id into v_id
    from agents a
   where a.club_id = p_club_id and a.user_id = p_user_id
   for update;
  return v_id;
end
$$;


ALTER FUNCTION public.fn_ensure_agent_row(p_club_id uuid, p_user_id uuid, p_role text) OWNER TO postgres;

