--
-- Name: fn_ensure_upcoming_mtts(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ensure_upcoming_mtts(p_club_id uuid, p_want integer DEFAULT 6, p_spacing_minutes integer DEFAULT 45) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_have integer; v_created integer := 0; v_last timestamptz;
    v_tpl public.tournaments%ROWTYPE; v_tag text; v_name text; i integer;
BEGIN
    SELECT count(*), max(start_time) INTO v_have, v_last
      FROM public.tournaments
     WHERE club_id = p_club_id AND tournament_type = 'MTT'
       AND status IN ('ANNOUNCED','REGISTERING') AND start_time > now();
    IF v_have >= p_want THEN RETURN 0; END IF;

    SELECT * INTO v_tpl FROM public.tournaments
     WHERE tournament_type = 'MTT' AND blind_structure IS NOT NULL AND payout_structure IS NOT NULL
     ORDER BY created_at DESC LIMIT 1;
    IF v_tpl.id IS NULL THEN RETURN 0; END IF;

    -- Names must be unique across live tournaments platform-wide, so scope by club.
    SELECT coalesce(club_id::text, left(id::text, 4)) INTO v_tag FROM public.clubs WHERE id = p_club_id;

    v_last := greatest(coalesce(v_last, now()), now());

    FOR i IN 1..(p_want - v_have) LOOP
        v_last := v_last + (p_spacing_minutes || ' minutes')::interval;
        v_name := 'Rolling Freeroll ' || v_tag || ' ' || to_char(v_last, 'DD HH24:MI');
        CONTINUE WHEN EXISTS (
            SELECT 1 FROM public.tournaments x
             WHERE x.tournament_type = 'MTT' AND x.name = v_name
               AND x.status IN ('ANNOUNCED','REGISTERING')
        );
        INSERT INTO public.tournaments (
            name, description, game_type, variant, buy_in_amount, buy_in_fee, guaranteed_prize,
            start_time, status, current_players, max_players, late_reg_mins, starting_chips,
            blind_structure, payout_structure, club_id, min_players, tournament_type, prize_pool,
            is_rebuy, add_on_available, is_bounty, is_pko, is_turbo, created_at, updated_at
        ) VALUES (
            v_name, 'Freeroll. No buy-in, no fee.',
            v_tpl.game_type, v_tpl.variant, 0, 0, 0,
            v_last, 'REGISTERING', 0,
            v_tpl.max_players, v_tpl.late_reg_mins, v_tpl.starting_chips,
            v_tpl.blind_structure, v_tpl.payout_structure, p_club_id,
            v_tpl.min_players, 'MTT', 0,
            false, false, false, false, false, now(), now()
        );
        v_created := v_created + 1;
    END LOOP;
    RETURN v_created;
END;
$$;


ALTER FUNCTION public.fn_ensure_upcoming_mtts(p_club_id uuid, p_want integer, p_spacing_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_ensure_upcoming_mtts(p_club_id uuid, p_want integer, p_spacing_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ensure_upcoming_mtts(p_club_id uuid, p_want integer, p_spacing_minutes integer) IS 'Tops a club up to N upcoming freeroll MTTs. Idempotent, club-scoped names, safe to call on a cadence — call from Open Claw to keep the starting-soon ticker fed.';


--
-- Name: fn_entry_purchases_frozen(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entry_purchases_frozen() RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
           SELECT 1
             FROM public.engine_maintenance_break b
            WHERE b.enforce_freeze
              AND b.announced_at < clock_timestamp() + INTERVAL '30 seconds'
              AND (
                (
                  b.phase = 'last_hand'
                  AND b.break_started_at IS NULL
                  AND b.break_ends_at IS NULL
                )
                OR (
                  b.phase = 'counting_down'
                  AND b.break_started_at IS NOT NULL
                  AND b.break_ends_at IS NOT NULL
                  AND b.break_started_at >= b.announced_at
                  AND b.break_ends_at > b.break_started_at
                  AND b.break_ends_at < b.announced_at + INTERVAL '15 minutes'
                )
              )
         )
         OR COALESCE(
           public.fn_active_maintenance_release_boundary() > clock_timestamp(),
           false
         );
$$;


ALTER FUNCTION public.fn_entry_purchases_frozen() OWNER TO postgres;

--
-- Name: FUNCTION fn_entry_purchases_frozen(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_entry_purchases_frozen() IS 'True while a bounded last-hand announcement or countdown forbids new seats, registrations, launches, rebuys and add-ons. Unlike fn_platform_frozen, this entry-only predicate includes last_hand while allowing the hand already in flight to settle.';


--
-- Name: fn_evict_sitting_out_cash_players(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_evict_sitting_out_cash_players() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
BEGIN
  IF public.fn_platform_frozen() THEN
    RETURN;
  END IF;

  -- A. Boot players sitting out for more than 5 minutes
  FOR r IN
    SELECT ts.table_id, ts.user_id
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
    WHERE t.game_type = 'cash'
      AND ts.left_at IS NULL
      AND ts.sit_out_at < (now() - interval '5 minutes')
  LOOP
    PERFORM public.player_leave_table(r.table_id, r.user_id);
  END LOOP;

  -- B. Boot players with exactly 0 chips who are sitting out
  FOR r IN
    SELECT ts.table_id, ts.user_id
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
    WHERE t.game_type = 'cash'
      AND ts.left_at IS NULL
      AND ts.stack = 0
      AND ts.is_sitting_out = true
  LOOP
    PERFORM public.player_leave_table(r.table_id, r.user_id);
  END LOOP;

  -- C. Remove 0-chip players in Tournaments who are marked as eliminated
  FOR r IN
    SELECT ts.table_id, ts.user_id
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
    JOIN tournament_players tp ON tp.tournament_id = t.tournament_id AND tp.user_id = ts.user_id
    WHERE ts.left_at IS NULL
      AND tp.status = 'eliminated'
  LOOP
    PERFORM public.player_leave_table(r.table_id, r.user_id);
  END LOOP;
END;
$$;


ALTER FUNCTION public.fn_evict_sitting_out_cash_players() OWNER TO postgres;

--
-- Name: FUNCTION fn_evict_sitting_out_cash_players(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_evict_sitting_out_cash_players() IS 'Evicts cash seats sat out beyond five minutes, zero-chip sit-outs, and eliminated tournament seats. Returns without acting while the platform is frozen: the sit-out clock is shifted forward on thaw so a maintenance break never counts against a player.';


--
-- Name: fn_exact_tournament_knockout_claimants(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_exact_tournament_knockout_claimants(p_tournament_id uuid, p_hand_id uuid, p_eliminated_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_pots jsonb;
  v_winners jsonb;
  v_last_pot integer;
  v_winning_pot integer;
  v_chosen_pot_count integer;
  v_raw_winner_count integer;
  v_valid_winner_count integer;
  v_distinct_winner_count integer;
  v_chosen_eligible jsonb;
  v_claimants jsonb;
BEGIN
  SELECT h.pots, h.winners INTO v_pots, v_winners
    FROM public.hand_history h
   WHERE h.id = p_hand_id;
  IF jsonb_typeof(v_pots) <> 'array' OR jsonb_array_length(v_pots) = 0
     OR jsonb_typeof(v_winners) <> 'array' OR jsonb_array_length(v_winners) = 0 THEN
    RETURN NULL;
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_winners) w
     WHERE COALESCE(w->>'potIndex',w->>'pot_index','') !~ '^[0-9]+$'
  ) THEN
    RETURN NULL;
  END IF;

  WITH pots AS (
    SELECT CASE WHEN COALESCE(p->>'index','') ~ '^[0-9]+$'
                THEN (p->>'index')::integer ELSE ordinality::integer - 1 END AS pot_index,
           COALESCE(p->'eligible', p->'eligiblePlayers', '[]'::jsonb) AS eligible
      FROM jsonb_array_elements(v_pots) WITH ORDINALITY AS q(p, ordinality)
  )
  SELECT max(pot_index) INTO v_last_pot
    FROM pots
   WHERE jsonb_typeof(eligible) = 'array'
     AND EXISTS (SELECT 1 FROM jsonb_array_elements_text(eligible) e(user_id)
                  WHERE e.user_id = p_eliminated_user_id::text);
  IF v_last_pot IS NULL THEN RETURN NULL; END IF;

  -- A modern row that cannot name a valid winner of the exact last pot is
  -- incomplete. Do not walk down to a different pot or largest winner: that
  -- would assign money to somebody who did not own the knockout.
  v_winning_pot := v_last_pot;

  SELECT count(*)
    INTO v_chosen_pot_count
    FROM jsonb_array_elements(v_pots) WITH ORDINALITY AS q(p,ordinality)
   WHERE CASE WHEN COALESCE(p->>'index','') ~ '^[0-9]+$'
              THEN (p->>'index')::integer ELSE ordinality::integer-1 END=v_winning_pot;
  IF v_chosen_pot_count<>1 THEN
    RETURN NULL;
  END IF;
  SELECT COALESCE(p->'eligible',p->'eligiblePlayers','[]'::jsonb)
    INTO v_chosen_eligible
    FROM jsonb_array_elements(v_pots) WITH ORDINALITY AS q(p,ordinality)
   WHERE CASE WHEN COALESCE(p->>'index','') ~ '^[0-9]+$'
              THEN (p->>'index')::integer ELSE ordinality::integer-1 END=v_winning_pot;
  IF jsonb_typeof(v_chosen_eligible)<>'array' THEN RETURN NULL; END IF;

  -- Never canonicalise corruption by filtering it away. Every winner row for
  -- the exact pot must name one distinct tournament participant who is in the
  -- pot's eligible set. A malformed outsider in a tie makes the whole money
  -- authority unavailable; it does not enlarge the valid player's share.
  WITH exact_winners AS (
    SELECT w,COALESCE(w->>'userId',w->>'user_id','') AS user_id_text
      FROM jsonb_array_elements(v_winners) w
     WHERE COALESCE(w->>'potIndex',w->>'pot_index')::integer=v_winning_pot
  ), classified AS (
    SELECT user_id_text,
           user_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
             AND user_id_text<>p_eliminated_user_id::text
             AND EXISTS (SELECT 1 FROM public.tournament_players tp
                          WHERE tp.tournament_id=p_tournament_id
                            AND tp.user_id=CASE
                              WHEN user_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                              THEN user_id_text::uuid ELSE NULL END)
             AND EXISTS (SELECT 1 FROM jsonb_array_elements_text(v_chosen_eligible) e(user_id)
                          WHERE e.user_id=user_id_text) AS valid
      FROM exact_winners
  )
  SELECT count(*),count(*) FILTER (WHERE valid),
         count(DISTINCT user_id_text) FILTER (WHERE valid)
    INTO v_raw_winner_count,v_valid_winner_count,v_distinct_winner_count
    FROM classified;
  -- Hi-lo histories legitimately contain one row for the high half and one
  -- for the low half when the same player scoops. Validate every source row,
  -- then canonicalise to distinct claimant ids below; duplicate winner rows
  -- are not duplicate people and must not invalidate an otherwise exact pot.
  IF v_raw_winner_count=0 OR v_valid_winner_count<>v_raw_winner_count
     OR v_distinct_winner_count=0 THEN
    RETURN NULL;
  END IF;

  WITH participants AS (
    SELECT DISTINCT COALESCE(w->>'userId',w->>'user_id')::uuid AS user_id
      FROM jsonb_array_elements(v_winners) w
     WHERE COALESCE(w->>'potIndex',w->>'pot_index')::integer=v_winning_pot
  )
  SELECT jsonb_agg(jsonb_build_object('user_id', user_id, 'weight', 1)
                   ORDER BY user_id::text)
    INTO v_claimants FROM participants;
  RETURN v_claimants;
END;
$_$;


ALTER FUNCTION public.fn_exact_tournament_knockout_claimants(p_tournament_id uuid, p_hand_id uuid, p_eliminated_user_id uuid) OWNER TO postgres;

--
-- Name: fn_execute_managed_game_command(uuid, text, uuid, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_execute_managed_game_command(p_command_id uuid, p_kind text, p_game_id uuid, p_action text, p_expected_version integer, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_club uuid;
  v_request_hash text;
  v_existing public.managed_game_command_receipts%ROWTYPE;
  v_before integer;
  v_after integer;
  v_action_result jsonb;
  v_result jsonb;
  v_status text;
  v_reason text;
  v_message text;
  v_sqlstate text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_command_id IS NULL
     OR p_game_id IS NULL
     OR p_kind NOT IN ('table', 'tournament')
     OR p_action NOT IN ('update', 'close')
     OR p_expected_version IS NULL
     OR p_expected_version < 1
     OR jsonb_typeof(COALESCE(p_payload, '{}'::jsonb)) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request');
  END IF;

  v_request_hash := public.fn_managed_game_command_hash(
    p_command_id, p_kind, p_game_id, p_action, p_expected_version, p_payload
  );

  PERFORM pg_advisory_xact_lock(
    hashtextextended('managed-game-command:' || p_command_id::text, 0)
  );

  SELECT * INTO v_existing
    FROM public.managed_game_command_receipts
   WHERE command_id = p_command_id;
  IF FOUND THEN
    IF v_existing.actor_id <> v_uid OR v_existing.request_hash <> v_request_hash THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'idempotency_conflict');
    END IF;
    RETURN v_existing.result || jsonb_build_object('replayed', true);
  END IF;

  IF p_kind = 'tournament' AND p_action = 'close' THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('ca:tournament-terminal-settlement:v1',0));
  END IF;

  IF p_kind = 'table' THEN
    SELECT club_id INTO v_club
      FROM public.tables
     WHERE id = p_game_id
     FOR UPDATE;
  ELSE
    SELECT club_id INTO v_club
      FROM public.tournaments
     WHERE id = p_game_id
     FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'game_not_found');
  END IF;
  IF NOT public.fn_can_create_games(v_club, v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  SELECT version INTO v_before
    FROM public.managed_game_contract_versions
   WHERE game_kind = p_kind AND game_id = p_game_id
   ORDER BY version DESC
   LIMIT 1;

  IF v_before IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'contract_not_found');
  END IF;

  INSERT INTO public.managed_game_command_receipts (
    command_id, actor_id, game_kind, game_id, command_action,
    expected_version, request_hash, status, contract_version_before
  ) VALUES (
    p_command_id, v_uid, p_kind, p_game_id, p_action,
    p_expected_version, v_request_hash, 'processing', v_before
  );

  IF p_expected_version <> v_before THEN
    v_result := jsonb_build_object(
      'ok', false,
      'reason', 'stale_contract_version',
      'command_id', p_command_id,
      'command_status', 'rejected',
      'expected_version', p_expected_version,
      'current_version', v_before,
      'version_before', v_before,
      'version_after', v_before,
      'replayed', false
    );
    UPDATE public.managed_game_command_receipts
       SET status = 'rejected', result = v_result,
           contract_version_after = v_before, completed_at = now()
     WHERE command_id = p_command_id;
    RETURN v_result;
  END IF;

  BEGIN
    IF p_action = 'update' THEN
      v_action_result := public.fn_update_managed_game(p_kind, p_game_id, p_payload);
    ELSE
      v_action_result := public.fn_close_managed_game(p_kind, p_game_id);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
    v_reason := CASE
      WHEN v_sqlstate IN ('22P02', '22003', '23514') THEN 'invalid_payload'
      WHEN v_sqlstate = '42501' THEN 'not_authorized'
      WHEN v_sqlstate = '55000' THEN 'contract_rule_blocked'
      ELSE 'command_failed'
    END;
    v_action_result := jsonb_build_object(
      'ok', false,
      'reason', v_reason,
      'message', CASE
        WHEN v_sqlstate = '55000' THEN v_message
        ELSE NULL
      END
    );
  END;

  SELECT version INTO v_after
    FROM public.managed_game_contract_versions
   WHERE game_kind = p_kind AND game_id = p_game_id
   ORDER BY version DESC
   LIMIT 1;
  v_after := COALESCE(v_after, v_before);
  v_status := CASE WHEN COALESCE((v_action_result ->> 'ok')::boolean, false)
    THEN 'succeeded' ELSE 'rejected' END;

  v_result := COALESCE(v_action_result, jsonb_build_object(
    'ok', false, 'reason', 'command_failed'
  )) || jsonb_build_object(
    'command_id', p_command_id,
    'command_status', v_status,
    'expected_version', p_expected_version,
    'current_version', v_after,
    'version_before', v_before,
    'version_after', v_after,
    'replayed', false
  );

  UPDATE public.managed_game_command_receipts
     SET status = v_status, result = v_result,
         contract_version_after = v_after, completed_at = now()
   WHERE command_id = p_command_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_execute_managed_game_command(p_command_id uuid, p_kind text, p_game_id uuid, p_action text, p_expected_version integer, p_payload jsonb) OWNER TO postgres;

--
-- Name: fn_execute_union_rakeback(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_execute_union_rakeback(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_owner  uuid;
BEGIN
  SELECT owner_id INTO v_owner FROM unions WHERE id = p_union_id;
  IF v_owner IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'union_not_found');
  END IF;
  IF v_caller IS NULL OR v_caller <> v_owner THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;
  IF p_period_start IS NULL OR p_period_end IS NULL
     OR p_period_start <> public.fn_union_week_start(p_period_start)
     OR p_period_end   <> public.fn_union_week_start(p_period_end)
     OR p_period_end <= p_period_start THEN
    RETURN jsonb_build_object('success', false, 'error', 'period_must_be_iso_weeks',
      'hint', 'start and end must both be Monday 00:00 UTC');
  END IF;
  RETURN public.fn_union_weekly_rakeback_close(p_union_id, p_period_start, p_period_end);
END $$;


ALTER FUNCTION public.fn_execute_union_rakeback(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_expire_daily_challenge_rewards(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_expire_daily_challenge_rewards() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_n integer;
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;
  UPDATE public.user_daily_challenges
     SET expired_at = now()
   WHERE completed AND NOT claimed AND expired_at IS NULL
     AND completed_at < now() - interval '7 days';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;


