--
-- Name: fn_export_user_data_gdpr(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_export_user_data_gdpr(p_user_id uuid, p_requested_by uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_req_role text;
  v_export   jsonb := '{}'::jsonb;
BEGIN
  IF p_user_id IS NULL OR p_requested_by IS NULL THEN
    RAISE EXCEPTION 'user_id and requested_by required'
          USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- Auth: user-self, or admin
  SELECT role INTO v_req_role FROM public.profiles WHERE id = p_requested_by;
  IF p_user_id <> p_requested_by AND v_req_role NOT IN ('admin','superadmin','god') THEN
    RAISE EXCEPTION 'only the user or a platform admin may request data export'
          USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- profile ------------------------------------------------------------
  v_export := v_export || jsonb_build_object('profile',
    (SELECT to_jsonb(p) FROM public.profiles p WHERE p.id = p_user_id)
  );

  -- groups owned ------------------------------------------------------
  v_export := v_export || jsonb_build_object('groups_owned',
    COALESCE((SELECT jsonb_agg(to_jsonb(g)) FROM public.commander_home_groups g
               WHERE g.owner_id = p_user_id), '[]'::jsonb)
  );

  -- group memberships -------------------------------------------------
  v_export := v_export || jsonb_build_object('group_memberships',
    COALESCE((SELECT jsonb_agg(to_jsonb(m)) FROM public.commander_home_members m
               WHERE m.user_id = p_user_id), '[]'::jsonb)
  );

  -- groups followed ---------------------------------------------------
  v_export := v_export || jsonb_build_object('groups_followed',
    COALESCE((SELECT jsonb_agg(to_jsonb(f)) FROM public.commander_home_group_follows f
               WHERE f.user_id = p_user_id), '[]'::jsonb)
  );

  -- games hosted ------------------------------------------------------
  v_export := v_export || jsonb_build_object('games_hosted',
    COALESCE((SELECT jsonb_agg(to_jsonb(g)) FROM public.commander_home_games g
               WHERE g.host_id = p_user_id), '[]'::jsonb)
  );

  -- rsvps -------------------------------------------------------------
  v_export := v_export || jsonb_build_object('rsvps',
    COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM public.commander_home_rsvps r
               WHERE r.user_id = p_user_id), '[]'::jsonb)
  );

  -- posts authored ----------------------------------------------------
  v_export := v_export || jsonb_build_object('posts',
    COALESCE((SELECT jsonb_agg(to_jsonb(p)) FROM public.commander_home_posts p
               WHERE p.author_id = p_user_id), '[]'::jsonb)
  );

  -- comments authored -------------------------------------------------
  v_export := v_export || jsonb_build_object('post_comments',
    COALESCE((SELECT jsonb_agg(to_jsonb(c)) FROM public.commander_home_post_comments c
               WHERE c.author_id = p_user_id), '[]'::jsonb)
  );

  -- post likes --------------------------------------------------------
  v_export := v_export || jsonb_build_object('post_likes',
    COALESCE((SELECT jsonb_agg(to_jsonb(pl)) FROM public.commander_home_post_likes pl
               WHERE pl.user_id = p_user_id), '[]'::jsonb)
  );

  -- poll votes --------------------------------------------------------
  v_export := v_export || jsonb_build_object('poll_votes',
    COALESCE((SELECT jsonb_agg(to_jsonb(v)) FROM public.commander_home_poll_votes v
               WHERE v.user_id = p_user_id), '[]'::jsonb)
  );

  -- reviews authored --------------------------------------------------
  v_export := v_export || jsonb_build_object('game_reviews',
    COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM public.commander_home_game_reviews r
               WHERE r.reviewer_id = p_user_id), '[]'::jsonb)
  );

  -- game photos uploaded ---------------------------------------------
  v_export := v_export || jsonb_build_object('game_photos',
    COALESCE((SELECT jsonb_agg(to_jsonb(p)) FROM public.commander_home_game_photos p
               WHERE p.uploader_id = p_user_id), '[]'::jsonb)
  );

  -- seats claimed -----------------------------------------------------
  v_export := v_export || jsonb_build_object('seats',
    COALESCE((SELECT jsonb_agg(to_jsonb(s)) FROM public.commander_home_seats s
               WHERE s.user_id = p_user_id), '[]'::jsonb)
  );

  -- seat reservations -------------------------------------------------
  v_export := v_export || jsonb_build_object('seat_reservations',
    COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM public.commander_home_seat_reservations r
               WHERE r.user_id = p_user_id OR r.claimed_by_user_id = p_user_id), '[]'::jsonb)
  );

  -- content reports filed --------------------------------------------
  v_export := v_export || jsonb_build_object('content_reports_filed',
    COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM public.commander_home_content_reports r
               WHERE r.reporter_id = p_user_id), '[]'::jsonb)
  );

  -- moderation actions taken against this user -----------------------
  v_export := v_export || jsonb_build_object('content_reports_about_me',
    COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM public.commander_home_content_reports r
               WHERE r.content_author_id = p_user_id), '[]'::jsonb)
  );

  -- ban appeals ------------------------------------------------------
  v_export := v_export || jsonb_build_object('ban_appeals',
    COALESCE((SELECT jsonb_agg(to_jsonb(a)) FROM public.commander_home_ban_appeals a
               WHERE a.user_id = p_user_id), '[]'::jsonb)
  );

  -- invite tokens created -------------------------------------------
  v_export := v_export || jsonb_build_object('invite_tokens_created',
    COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM public.commander_home_invite_tokens t
               WHERE t.created_by = p_user_id), '[]'::jsonb)
  );

  -- join attempts ---------------------------------------------------
  v_export := v_export || jsonb_build_object('join_attempts',
    COALESCE((SELECT jsonb_agg(to_jsonb(j)) FROM public.commander_home_join_attempts j
               WHERE j.user_id = p_user_id), '[]'::jsonb)
  );

  -- group promotion requests ---------------------------------------
  v_export := v_export || jsonb_build_object('promotion_requests',
    COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM public.commander_home_group_promotion_requests r
               WHERE r.requested_by = p_user_id), '[]'::jsonb)
  );

  -- TOS acceptances ------------------------------------------------
  v_export := v_export || jsonb_build_object('tos_acceptances',
    COALESCE((SELECT jsonb_agg(to_jsonb(a)) FROM public.user_tos_acceptances a
               WHERE a.user_id = p_user_id), '[]'::jsonb)
  );

  -- audit log entries about this user's actions -------------------
  v_export := v_export || jsonb_build_object('audit_log_as_actor',
    COALESCE((SELECT jsonb_agg(to_jsonb(a)) FROM public.commander_home_audit_log a
               WHERE a.actor_id = p_user_id), '[]'::jsonb)
  );

  -- Export envelope
  RETURN jsonb_build_object(
    'success',     true,
    'user_id',     p_user_id,
    'requested_by', p_requested_by,
    'generated_at', now(),
    'scope',       'home_games',
    'data',        v_export
  );
END;
$$;


ALTER FUNCTION public.fn_export_user_data_gdpr(p_user_id uuid, p_requested_by uuid) OWNER TO postgres;

--
-- Name: fn_extract_youtube_video_id(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_extract_youtube_video_id(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'public'
    AS $_$
  WITH normalized AS (
    SELECT btrim(p_value) AS value
  )
  SELECT CASE
    WHEN value ~ '^[A-Za-z0-9_-]{11}$'
      THEN value
    WHEN value ~* '^https?://(?:(?:www|m|music)\.)?youtube\.com/watch\?[^#]*(?:#.*)?$'
      AND split_part(split_part(value, '?', 2), '#', 1)
        ~* '(?:^|&)v=[A-Za-z0-9_-]{11}(?:&|$)'
      THEN substring(
        split_part(split_part(value, '?', 2), '#', 1)
        FROM '(?i)(?:^|&)v=([A-Za-z0-9_-]{11})(?:&|$)'
      )
    WHEN value ~* '^https?://youtu\.be/[A-Za-z0-9_-]{11}(?:[/?#].*)?$'
      THEN substring(
        value FROM '(?i)^https?://youtu\.be/([A-Za-z0-9_-]{11})(?:[/?#]|$)'
      )
    WHEN value ~* '^https?://(?:(?:www|m)\.)?youtube\.com/shorts/[A-Za-z0-9_-]{11}(?:[/?#].*)?$'
      THEN substring(
        value FROM '(?i)/shorts/([A-Za-z0-9_-]{11})(?:[/?#]|$)'
      )
    WHEN value ~* '^https?://(?:(?:www|m)\.)?youtube\.com/embed/[A-Za-z0-9_-]{11}(?:[/?#].*)?$'
      THEN substring(
        value FROM '(?i)/embed/([A-Za-z0-9_-]{11})(?:[/?#]|$)'
      )
    WHEN value ~* '^https?://(?:www\.)?youtube-nocookie\.com/embed/[A-Za-z0-9_-]{11}(?:[/?#].*)?$'
      THEN substring(
        value FROM '(?i)/embed/([A-Za-z0-9_-]{11})(?:[/?#]|$)'
      )
    WHEN value ~* '^https?://(?:(?:www|m)\.)?youtube\.com/live/[A-Za-z0-9_-]{11}(?:[/?#].*)?$'
      THEN substring(
        value FROM '(?i)/live/([A-Za-z0-9_-]{11})(?:[/?#]|$)'
      )
    ELSE NULL
  END
  FROM normalized
$_$;


ALTER FUNCTION public.fn_extract_youtube_video_id(p_value text) OWNER TO postgres;

--
-- Name: FUNCTION fn_extract_youtube_video_id(p_value text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_extract_youtube_video_id(p_value text) IS 'Returns an 11-character YouTube video id from a video id or supported YouTube URL; otherwise NULL.';


--
-- Name: fn_fee_is_accounted_for(text, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fee_is_accounted_for(p_kind text, p_table_id uuid, p_hand_id uuid, p_hand_number bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    -- Cheapest check, and the one that is true most often.
    (p_hand_number > 0 AND EXISTS (
       SELECT 1 FROM public.pending_fee_distributions q
        WHERE q.table_id = p_table_id AND q.hand_number = p_hand_number
          AND q.kind = p_kind))
    OR CASE WHEN p_kind = 'rake' THEN
         (p_hand_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.rake_records r WHERE r.hand_id = p_hand_id))
         OR (p_hand_number > 0 AND EXISTS (
            SELECT 1 FROM public.rake_records r
             WHERE r.table_id = p_table_id AND r.global_hand_id = p_hand_number))
       ELSE
         (p_hand_number > 0 AND EXISTS (
            SELECT 1 FROM public.bbj_contributions b
             WHERE b.table_id = p_table_id AND b.hand_number = p_hand_number))
       END;
$$;


ALTER FUNCTION public.fn_fee_is_accounted_for(p_kind text, p_table_id uuid, p_hand_id uuid, p_hand_number bigint) OWNER TO postgres;

--
-- Name: fn_filter_valid_user_video_storage_urls(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_filter_valid_user_video_storage_urls(p_candidates jsonb) RETURNS TABLE(playback_url text, author_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
  WITH bounded_input AS (
    SELECT CASE
      WHEN jsonb_typeof(COALESCE(p_candidates, '[]'::jsonb)) = 'array'
      THEN CASE
        WHEN jsonb_array_length(COALESCE(p_candidates, '[]'::jsonb)) <= 500
        THEN COALESCE(p_candidates, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
      ELSE '[]'::jsonb
    END AS candidates
  ), parsed AS (
    SELECT candidate ->> 'playback_url' AS playback_url,
           CASE
             WHEN COALESCE(candidate ->> 'author_id', '') ~
               '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
             THEN (candidate ->> 'author_id')::uuid
             ELSE NULL
           END AS author_id
    FROM bounded_input
    CROSS JOIN LATERAL jsonb_array_elements(candidates) AS input(candidate)
    WHERE jsonb_typeof(candidate) = 'object'
  )
  SELECT DISTINCT parsed.playback_url, parsed.author_id
  FROM parsed
  WHERE parsed.playback_url IS NOT NULL
    AND parsed.author_id IS NOT NULL
    AND public.fn_is_user_video_storage_url(
      parsed.playback_url,
      parsed.author_id
    )
$_$;


ALTER FUNCTION public.fn_filter_valid_user_video_storage_urls(p_candidates jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_filter_valid_user_video_storage_urls(p_candidates jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_filter_valid_user_video_storage_urls(p_candidates jsonb) IS 'Service-role batch proof for live, non-archived, non-delete-marker video objects in exact author namespaces; rejects malformed or oversized input fail-closed.';


--
-- Name: fn_filtered_too_long_delete_reel(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_filtered_too_long_delete_reel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.status = 'failed'
     AND COALESCE(NEW.error_message, '') ILIKE 'filtered_too_long_or_large%'
     AND (OLD.status IS DISTINCT FROM NEW.status
          OR COALESCE(OLD.error_message, '') IS DISTINCT FROM COALESCE(NEW.error_message, ''))
     AND NEW.reel_id IS NOT NULL
  THEN
    UPDATE public.social_reels r
    SET video_url = r.original_youtube_url,
        playback_type = 'youtube_embed',
        media_status = 'ready',
        native_processing_requested = false,
        source_type = CASE
          WHEN r.origin_type = 'video_library' THEN 'video_library'
          ELSE 'youtube'
        END
    WHERE r.id = NEW.reel_id
      AND r.original_youtube_url IS NOT NULL
      AND r.youtube_video_id IS NOT NULL;
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_filtered_too_long_delete_reel() OWNER TO postgres;

