--
-- Name: fn_final_table_deal_unguarded_20260907(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_final_table_deal_unguarded_20260907(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_t             record;
  v_remaining     integer;
  v_total_chips   numeric;
  v_awarded       numeric;
  v_undistributed numeric;
  v_paid_out      numeric := 0;
  v_share         numeric;
  v_leader        uuid;
  v_remainder     numeric;
  v_p             record;
  v_payouts       jsonb := '[]'::jsonb;
  v_shares        jsonb := '[]'::jsonb;
  v_rank          integer := 0;
  v_amount        numeric;
  v_settle        jsonb;
  v_settle_paid   numeric;
  v_settled_total numeric := 0;
  v_refusals      jsonb := '[]'::jsonb;
BEGIN
  SELECT id, status, prize_pool, final_table_deal_enabled, COALESCE(table_size, 9) AS table_size
    INTO v_t FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
  END IF;
  IF NOT COALESCE(v_t.final_table_deal_enabled, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'deal_not_enabled');
  END IF;
  IF v_t.status <> 'RUNNING' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_running');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_payouts
              WHERE tournament_id = p_tournament_id AND source = 'final_table_deal')
     OR EXISTS (SELECT 1 FROM public.tournament_obligations
                 WHERE tournament_id = p_tournament_id AND kind = 'final_table_deal') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'deal_already_executed');
  END IF;

  SELECT count(*), COALESCE(sum(GREATEST(chips, 0)), 0)
    INTO v_remaining, v_total_chips
    FROM public.tournament_players
   WHERE tournament_id = p_tournament_id
     AND status IN ('registered', 'playing')
     AND eliminated_at IS NULL;

  IF v_remaining < 2 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_enough_players');
  END IF;
  IF v_remaining > v_t.table_size THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_at_final_table',
                              'detail', v_remaining);
  END IF;
  IF v_total_chips <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_chips_in_play');
  END IF;

  -- tournament_players.prize is a display cache of the same
  -- payments recorded append-only in tournament_payouts. Summing both counts
  -- every settled place twice and underprices the deal. The payout ledger is
  -- the sole authority for prize-pool money already distributed.
  SELECT COALESCE(sum(amount),0) INTO v_awarded
    FROM public.tournament_payouts
   WHERE tournament_id=p_tournament_id
     AND COALESCE(source,'') NOT IN
       ('satellite_seat','bounty','mystery_bounty','bounty_residual',
        'own_bounty','mystery_bounty_residual');

  v_undistributed := GREATEST(COALESCE(v_t.prize_pool, 0) - v_awarded, 0);
  IF v_undistributed <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_undistributed_prize');
  END IF;

  SELECT user_id INTO v_leader
    FROM public.tournament_players
   WHERE tournament_id = p_tournament_id
     AND status IN ('registered', 'playing')
     AND eliminated_at IS NULL
   ORDER BY chips DESC, registered_at ASC, user_id ASC
   LIMIT 1;

  /* PASS 1 - price every seat, write nothing. */
  FOR v_p IN
    SELECT user_id, chips
      FROM public.tournament_players
     WHERE tournament_id = p_tournament_id
       AND status IN ('registered', 'playing')
       AND eliminated_at IS NULL
     ORDER BY chips DESC, registered_at ASC, user_id ASC
  LOOP
    v_rank  := v_rank + 1;
    v_share := floor(GREATEST(v_p.chips, 0) / v_total_chips * v_undistributed);
    v_paid_out := v_paid_out + v_share;
    v_shares := v_shares || jsonb_build_object(
      'user_id', v_p.user_id, 'share', v_share, 'rank', v_rank);
  END LOOP;

  /* The flooring shortfall, settled on the chip leader - as before, but
     decided before the first row is written instead of by an UPDATE after. */
  v_remainder := v_undistributed - v_paid_out;

  /* PASS 2 - ONE SETTLE PATH (Lane A3, 2026-09-02). One user-keyed
     'final_table_deal' obligation per player, settled here. The settle
     function writes tournament_payouts (source 'final_table_deal', position
     NULL) and wallet_transactions, refuses a replay and refuses a share the
     prize pool cannot cover (escrow_short raises its own critical alert). */
  FOR v_p IN SELECT * FROM jsonb_to_recordset(v_shares)
                        AS x(user_id uuid, share numeric, rank integer)
  LOOP
    v_amount := v_p.share
              + CASE WHEN v_remainder > 0 AND v_p.user_id = v_leader
                     THEN v_remainder ELSE 0 END;
    v_settle_paid := 0;

    IF v_amount > 0 THEN
      v_settle := public.fn_settle_tournament_obligation(
        p_tournament_id, 'final_table_deal', NULL, v_p.user_id, v_amount,
        'final_table_deal', 'Final table deal (even chip chop)');
      v_settle_paid := round(COALESCE((v_settle->>'paid')::numeric, 0), 2);
      IF NOT COALESCE((v_settle->>'ok')::boolean, false) THEN
        v_refusals := v_refusals || jsonb_build_object(
          'user_id', v_p.user_id, 'amount', v_amount,
          'refused_reason', v_settle->>'refused_reason',
          'obligation_id', v_settle->>'obligation_id');
      END IF;
    END IF;

    v_settled_total := v_settled_total + v_settle_paid;
    v_payouts := v_payouts || jsonb_build_object('user_id', v_p.user_id, 'amount', v_amount,
                                                 'settled', v_settle_paid,
                                                 'obligation_id', v_settle->>'obligation_id');

    IF v_settle_paid > 0 THEN
      UPDATE public.tournament_players
         SET prize = COALESCE(prize, 0) + v_settle_paid
       WHERE tournament_id = p_tournament_id AND user_id = v_p.user_id;
    END IF;
  END LOOP;

  UPDATE public.tournaments
     SET status = 'COMPLETING', updated_at = now()
   WHERE id = p_tournament_id;

  RETURN jsonb_build_object('ok', true,
    'undistributed', v_undistributed,
    'remainder_to_leader', v_remainder,
    'chip_leader', v_leader,
    'settled', round(v_settled_total, 2),
    'refusals', v_refusals,
    'money_path', 'fn_settle_tournament_obligation',
    'payouts', v_payouts);
END; $$;


ALTER FUNCTION public.fn_final_table_deal_unguarded_20260907(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_finalize_bounty_pool(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_finalize_bounty_pool(p_tournament_id uuid, p_winner_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_t public.tournaments%ROWTYPE;
  v_canonical_winner uuid;
  v_winner_count integer;
  v_receipt public.tournament_bounty_completion_receipts%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  SELECT * INTO v_receipt FROM public.tournament_bounty_completion_receipts
   WHERE tournament_id=p_tournament_id AND pool_finalized_at IS NOT NULL;
  IF FOUND THEN
    IF v_receipt.winner_user_id IS DISTINCT FROM p_winner_user_id
       OR jsonb_typeof(v_receipt.pool_result) IS DISTINCT FROM 'object' THEN
      RETURN jsonb_build_object('ok',false,'reason','completion_receipt_conflict');
    END IF;
    RETURN v_receipt.pool_result;
  END IF;
  SELECT * INTO v_t FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','not_found'); END IF;
  SELECT * INTO v_receipt FROM public.tournament_bounty_completion_receipts
   WHERE tournament_id=p_tournament_id AND pool_finalized_at IS NOT NULL;
  IF FOUND THEN
    IF v_receipt.winner_user_id IS DISTINCT FROM p_winner_user_id
       OR jsonb_typeof(v_receipt.pool_result) IS DISTINCT FROM 'object' THEN
      RETURN jsonb_build_object('ok',false,'reason','completion_receipt_conflict');
    END IF;
    RETURN v_receipt.pool_result;
  END IF;
  SELECT count(DISTINCT tp.user_id),(array_agg(tp.user_id ORDER BY tp.user_id))[1]
    INTO v_winner_count,v_canonical_winner
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.status='winner' AND tp.position=1;
  IF v_winner_count<>1 OR p_winner_user_id IS DISTINCT FROM v_canonical_winner THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_tournament_winner');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_bounty_completion_receipts r
              WHERE r.tournament_id=p_tournament_id
                AND r.winner_user_id IS DISTINCT FROM p_winner_user_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','completion_winner_conflict');
  END IF;
  IF public.fn_tournament_has_unsettled_bounties(p_tournament_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','pending_bounty_obligations');
  END IF;
  IF COALESCE(v_t.is_mystery_bounty,false)
     AND v_t.mystery_bounty_stage IS DISTINCT FROM 'pending'
     AND NOT EXISTS (SELECT 1 FROM public.tournament_bounty_completion_receipts r
                      WHERE r.tournament_id=p_tournament_id
                        AND r.mystery_settled_at IS NOT NULL) THEN
    RETURN jsonb_build_object('ok',false,'reason','mystery_bounty_not_settled');
  END IF;
  v_result := public.fn_finalize_bounty_pool_unguarded_20260907(
    p_tournament_id,p_winner_user_id);
  IF COALESCE((v_result->>'ok')::boolean,false) THEN
    INSERT INTO public.tournament_bounty_completion_receipts
      (tournament_id,winner_user_id,pool_finalized_at,pool_result,updated_at)
    VALUES (p_tournament_id,p_winner_user_id,now(),v_result,now())
    ON CONFLICT (tournament_id) DO UPDATE
      SET pool_finalized_at=COALESCE(public.tournament_bounty_completion_receipts.pool_finalized_at,EXCLUDED.pool_finalized_at),
          pool_result=COALESCE(public.tournament_bounty_completion_receipts.pool_result,EXCLUDED.pool_result),
          winner_user_id=COALESCE(public.tournament_bounty_completion_receipts.winner_user_id,EXCLUDED.winner_user_id),
          updated_at=now();
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_finalize_bounty_pool(p_tournament_id uuid, p_winner_user_id uuid) OWNER TO postgres;

--
-- Name: fn_finalize_bounty_pool_unguarded_20260907(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_finalize_bounty_pool_unguarded_20260907(p_tournament_id uuid, p_winner_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t        record;
  v_residual numeric;
  v_own      numeric;
  v_paid     numeric;
  v_prior    numeric;
  v_settle   jsonb;
BEGIN
  SELECT id, is_bounty, is_pko, is_mystery_bounty, bounty_pool, bounty_pool_paid
    INTO v_t FROM tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;
  IF NOT (COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
          OR COALESCE(v_t.is_mystery_bounty,false)) THEN
    RETURN jsonb_build_object('ok', true, 'residual', 0, 'reason', 'not_a_bounty_tournament');
  END IF;

  IF COALESCE(v_t.bounty_pool, 0) <= 0 THEN
    -- Legacy unfunded event: pay the champion their own remaining head, which
    -- is what the pre-funding-model code did.
    SELECT COALESCE(NULLIF(current_bounty,0), NULLIF(mystery_bounty_value,0), 0)
      INTO v_own FROM tournament_players
     WHERE tournament_id = p_tournament_id AND user_id = p_winner_user_id;
    IF COALESCE(v_own,0) <= 0 OR p_winner_user_id IS NULL THEN
      RETURN jsonb_build_object('ok', true, 'residual', 0, 'funded', false);
    END IF;
    /* ONE PAYER (R3, 2026-09-02): user-keyed cumulative 'bounty_residual'.
       The old key tourney:<t>:ownbounty:<winner> carried no amount, so a
       second run with a larger residual paid nothing (standard 2.6); the
       obligation total rises with it and the difference is what moves. */
    v_prior := COALESCE((SELECT o.amount_paid FROM public.tournament_obligations o
                          WHERE o.tournament_id = p_tournament_id AND o.kind = 'bounty_residual'
                            AND o.place IS NULL AND o.user_id = p_winner_user_id), 0);
    v_settle := public.fn_settle_tournament_obligation(
      p_tournament_id, 'bounty_residual', NULL, p_winner_user_id, round(v_prior + v_own, 2),
      'fn_finalize_bounty_pool', 'Tournament champion: own bounty head collected');
    IF NOT COALESCE((v_settle->>'ok')::boolean, false) THEN
      RAISE EXCEPTION 'fn_finalize_bounty_pool: own bounty head of % to % in tournament % refused (%)',
        v_own, p_winner_user_id, p_tournament_id, COALESCE(v_settle->>'refused_reason', 'unknown');
    END IF;
    UPDATE tournament_players
       SET bounty_winnings = round(COALESCE(bounty_winnings,0) + v_own, 2),
           current_bounty = 0
     WHERE tournament_id = p_tournament_id AND user_id = p_winner_user_id;
    RETURN jsonb_build_object('ok', true, 'residual', v_own, 'funded', false,
                              'paid_to', p_winner_user_id);
  END IF;

  /**
   * MEASURED FROM THE LEDGER (2026-08-29). `bounty_pool_paid` is a counter
   * that fn_collect_bounty increments as knockouts settle, and this function
   * runs while collections are still landing -- so reading it produced an
   * "unclaimed" residual for money that was about to be claimed, and paid it
   * to the champion on top of a pool the knockers went on to exhaust.
   *
   * The ledger cannot be stale relative to the money: it IS the money. Signed
   * off `type`, because a corrective debit is not a payment.
   */
  SELECT round(COALESCE(SUM(
           CASE WHEN lower(wt.type) = 'debit' THEN -abs(wt.amount) ELSE wt.amount END
         ), 0), 2)
    INTO v_paid
    FROM wallet_transactions wt
   WHERE wt.related_entity_id = p_tournament_id
     AND wt.category = 'bounty';

  v_residual := round(COALESCE(v_t.bounty_pool,0) - COALESCE(v_paid,0), 2);

  -- Keep the counter honest even when nothing is owed, so the next reader is
  -- not misled the way this function was.
  IF COALESCE(v_t.bounty_pool_paid,0) IS DISTINCT FROM COALESCE(v_paid,0) THEN
    UPDATE tournaments SET bounty_pool_paid = COALESCE(v_paid,0) WHERE id = p_tournament_id;
  END IF;

  IF v_residual <= 0 OR p_winner_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'residual', GREATEST(v_residual,0),
                              'funded', true, 'ledger_paid', v_paid);
  END IF;

  /* ONE PAYER (R3, 2026-09-02): see the unfunded branch above. The residual
     is measured net of every 'bounty' ledger row, including any earlier
     residual this obligation already paid, so the new total is prior + this. */
  v_prior := COALESCE((SELECT o.amount_paid FROM public.tournament_obligations o
                        WHERE o.tournament_id = p_tournament_id AND o.kind = 'bounty_residual'
                          AND o.place IS NULL AND o.user_id = p_winner_user_id), 0);
  v_settle := public.fn_settle_tournament_obligation(
    p_tournament_id, 'bounty_residual', NULL, p_winner_user_id, round(v_prior + v_residual, 2),
    'fn_finalize_bounty_pool', 'Unclaimed bounty pool awarded to champion');
  IF NOT COALESCE((v_settle->>'ok')::boolean, false) THEN
    RAISE EXCEPTION 'fn_finalize_bounty_pool: residual of % to % in tournament % refused (%)',
      v_residual, p_winner_user_id, p_tournament_id, COALESCE(v_settle->>'refused_reason', 'unknown');
  END IF;

  UPDATE tournaments
     SET bounty_pool_paid = round(COALESCE(v_paid,0) + v_residual, 2)
   WHERE id = p_tournament_id;
  UPDATE tournament_players
     SET bounty_winnings = round(COALESCE(bounty_winnings,0) + v_residual, 2),
         current_bounty = 0
   WHERE tournament_id = p_tournament_id AND user_id = p_winner_user_id;

  RETURN jsonb_build_object('ok', true, 'residual', v_residual, 'funded', true,
                            'ledger_paid', v_paid, 'paid_to', p_winner_user_id);
END;
$$;


ALTER FUNCTION public.fn_finalize_bounty_pool_unguarded_20260907(p_tournament_id uuid, p_winner_user_id uuid) OWNER TO postgres;

--
-- Name: fn_finalize_tournament_entry_pool_locked(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_finalize_tournament_entry_pool_locked(p_tournament_id uuid, p_source text, p_close_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_receipt public.tournament_entry_close_receipts%ROWTYPE;
  v_result jsonb;
  v_field integer;
  v_structure jsonb;
  v_wake_id bigint;
  v_pool numeric;
  v_is_satellite boolean;
BEGIN
  IF p_close_mode NOT IN ('levels','minutes','immediate','addon') THEN
    RAISE EXCEPTION 'Invalid tournament entry close mode' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_t
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','not_found');
  END IF;
  IF v_t.status<>'RUNNING' THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_not_running','status',v_t.status);
  END IF;

  SELECT * INTO v_receipt
    FROM public.tournament_entry_close_receipts r
   WHERE r.tournament_id=p_tournament_id
   FOR UPDATE;
  IF FOUND THEN
    -- A DB-first/old-engine window may have consumed the first wake without
    -- understanding this receipt. Re-emit only when no unconsumed row remains;
    -- never increment the generation a current sweep is already processing.
    IF v_receipt.reprice_completed_at IS NULL
       AND (v_receipt.manager_wake_id IS NULL OR NOT EXISTS (
         SELECT 1 FROM public.tournament_manager_wakes w
          WHERE w.id=v_receipt.manager_wake_id AND w.consumed_at IS NULL
       )) THEN
      v_wake_id := public.fn_emit_tournament_manager_wake(
        p_tournament_id,'late_registration');
      UPDATE public.tournament_entry_close_receipts
         SET manager_wake_id=v_wake_id,updated_at=clock_timestamp()
       WHERE tournament_id=p_tournament_id
       RETURNING * INTO v_receipt;
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'entry_closed',true,'finalized',true,
      'already_finalized',true,'close_mode',v_receipt.close_mode,
      'prize_pool',v_receipt.final_prize_pool,
      'payout_structure',v_receipt.payout_structure_snapshot,
      'reprice_pending',v_receipt.reprice_completed_at IS NULL,
      'retry_after_ms',NULL
    );
  END IF;

  SELECT count(*)::integer INTO v_field
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id;
  IF v_field<1 THEN
    RAISE EXCEPTION 'Entry cannot close without a readable final field'
      USING ERRCODE='55000';
  END IF;

  v_is_satellite := lower(COALESCE(v_t.variant,''))='satellite'
                 OR upper(COALESCE(v_t.tournament_type,''))='SATELLITE'
                 OR v_t.satellite_target_id IS NOT NULL;

  -- Spins own the wheel-derived structure. Every other format uses the
  -- database's canonical payout-percent generator for the final field. This
  -- includes satellites: their finish path awards seats rather than cash, but
  -- hand-for-hand and display readers still require the stored field ladder.
  IF lower(COALESCE(v_t.variant,''))<>'spin'
     AND upper(COALESCE(v_t.tournament_type,''))<>'SPIN' THEN
    v_structure := public.fn_ca_payout_structure(
      v_field,COALESCE(v_t.payout_percent,10));
    IF jsonb_array_length(v_structure)=0 THEN
      RAISE EXCEPTION 'Final payout structure is unreadable' USING ERRCODE='55000';
    END IF;
    UPDATE public.tournaments
       SET payout_structure=v_structure::text
     WHERE id=p_tournament_id;
  ELSE
    v_structure := public.fn_safe_jsonb_array(v_t.payout_structure::text);
    IF jsonb_array_length(v_structure)=0 THEN
      RAISE EXCEPTION 'Spin payout structure is unreadable' USING ERRCODE='55000';
    END IF;
  END IF;

  IF COALESCE(v_t.prize_pool_finalized,false) THEN
    v_result := jsonb_build_object(
      'ok',true,'already_finalized',true,'prize_pool',COALESCE(v_t.prize_pool,0));
  ELSE
    v_result := public.fn_apply_prize_guarantee(
      p_tournament_id,COALESCE(NULLIF(btrim(p_source),''),'engine.entry_window_close'));
  END IF;
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE
     OR v_result->>'prize_pool' IS NULL THEN
    RAISE EXCEPTION 'Entry close could not fund/finalize its prize pool: %',
      COALESCE(v_result->>'reason','unreadable result') USING ERRCODE='55000';
  END IF;
  v_pool := (v_result->>'prize_pool')::numeric;

  SELECT * INTO v_t FROM public.tournaments WHERE id=p_tournament_id;
  IF COALESCE(v_t.prize_pool_finalized,false) IS NOT TRUE
     OR round(COALESCE(v_t.prize_pool,0),2)<>round(v_pool,2) THEN
    RAISE EXCEPTION 'Entry close returned without an exact funded pool marker'
      USING ERRCODE='55000';
  END IF;

  -- Satellites keep the canonical field ladder for readers, but never cash-
  -- reprice eliminated finishers from it. Their immutable seat-or-cash plus
  -- remainder entitlements are materialized by the atomic satellite contract
  -- from this final funded pool; marking generic reprice complete prevents a
  -- manager from paying the display ladder as cash first.
  INSERT INTO public.tournament_entry_close_receipts(
    tournament_id,close_mode,entry_closed_at,final_prize_pool,
    payout_structure_snapshot,reprice_completed_at
  ) VALUES (
    p_tournament_id,p_close_mode,clock_timestamp(),v_pool,
    v_structure,CASE WHEN v_is_satellite THEN clock_timestamp() ELSE NULL END
  )
  RETURNING * INTO v_receipt;
  v_wake_id := public.fn_emit_tournament_manager_wake(
    p_tournament_id,'late_registration');
  UPDATE public.tournament_entry_close_receipts
     SET manager_wake_id=v_wake_id,updated_at=clock_timestamp()
   WHERE tournament_id=p_tournament_id;

  RETURN v_result || jsonb_build_object(
    'ok',true,'entry_closed',true,'finalized',true,
    'close_mode',p_close_mode,'payout_structure',v_structure,
    'reprice_pending',NOT v_is_satellite,'retry_after_ms',NULL
  );
END;
$$;


ALTER FUNCTION public.fn_finalize_tournament_entry_pool_locked(p_tournament_id uuid, p_source text, p_close_mode text) OWNER TO postgres;

--
-- Name: fn_financial_alert_health(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_financial_alert_health(p_stale_hours integer DEFAULT 24) RETURNS TABLE(unresolved_total bigint, unresolved_critical bigint, stale_critical bigint, distinct_conditions bigint, oldest_unresolved_age numeric, meta_alerts bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    count(*),
    count(*) FILTER (WHERE severity = 'critical'),
    count(*) FILTER (WHERE severity = 'critical'
                       AND created_at < now() - make_interval(hours => greatest(p_stale_hours, 1))),
    count(DISTINCT (source || '|' || left(message, 200))),
    CASE WHEN count(*) = 0 THEN NULL
         ELSE round(extract(epoch FROM now() - min(created_at)) / 3600.0, 1)
    END,
    count(*) FILTER (WHERE source LIKE 'drift_incident:financial_alerts:%')
  FROM public.financial_alerts
  WHERE NOT resolved
$$;


