-- Name: FUNCTION fn_flag_garbage_tournaments(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_flag_garbage_tournaments() IS 'Phase 25/D: Scraper cleanup. Suppresses rows with JSON/JS garbage in tournament_name. Runs daily 03:15 UTC.';


--
-- Name: fn_fleet_cadence(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fleet_cadence(p_profile_id uuid) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN (public.fn_fleet_hash(p_profile_id::text, 'cadence') % 100) < 45 THEN 1
    WHEN (public.fn_fleet_hash(p_profile_id::text, 'cadence') % 100) < 75 THEN 2
    WHEN (public.fn_fleet_hash(p_profile_id::text, 'cadence') % 100) < 90 THEN 3
    ELSE 7 END;
$$;


ALTER FUNCTION public.fn_fleet_cadence(p_profile_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_fleet_cadence(p_profile_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_fleet_cadence(p_profile_id uuid) IS 'Posts per week the workers FleetScheduler will actually run for this horse: 1, 2, 3 or 7. Same hash, same buckets.';


--
-- Name: fn_fleet_hash(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fleet_hash(p_profile_id text, p_salt text) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bytes bytea := convert_to(p_salt || ':' || p_profile_id, 'UTF8');
  v_h bigint := 2166136261;
  v_i int;
BEGIN
  FOR v_i IN 0 .. length(v_bytes) - 1 LOOP
    v_h := v_h # get_byte(v_bytes, v_i);
    v_h := (v_h * 16777619) % 4294967296;
  END LOOP;
  RETURN v_h;
END;
$$;


ALTER FUNCTION public.fn_fleet_hash(p_profile_id text, p_salt text) OWNER TO postgres;

--
-- Name: FUNCTION fn_fleet_hash(p_profile_id text, p_salt text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_fleet_hash(p_profile_id text, p_salt text) IS 'FNV-1a 32-bit over salt:profile_id. Byte-identical to workers FleetScheduler.fleetHash(); test vectors asserted in migration 20260905220000.';


--
-- Name: fn_fold_hand_winnings(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fold_hand_winnings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_club uuid; v_bb numeric;
BEGIN
  IF coalesce(current_setting('app.atomic_hand_commit',true),'')='on' THEN RETURN NEW; END IF;
  IF NEW.tournament_id IS NOT NULL OR NEW.players IS NULL
     OR jsonb_typeof(NEW.players)<>'array' OR jsonb_array_length(NEW.players)=0 THEN
    RETURN NEW;
  END IF;
  SELECT t.club_id INTO v_club FROM public.tables t WHERE t.id=NEW.table_id;
  IF v_club IS NULL THEN RETURN NEW; END IF;
  v_bb := greatest(coalesce(NEW.big_blind,0),0);
  WITH seated AS (
    SELECT DISTINCT (pl->>'userId') AS uid
      FROM jsonb_array_elements(NEW.players) pl
     WHERE (pl->>'userId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ), won AS (
    SELECT (w->>'userId') AS uid,sum((w->>'amount')::numeric) AS amt
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(NEW.winners)='array'
        THEN NEW.winners ELSE '[]'::jsonb END) w
     WHERE (w->>'userId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND coalesce((w->>'amount')::numeric,0)>0
     GROUP BY 1
  )
  INSERT INTO public.player_stats
    (id,user_id,club_id,hands_dealt,sum_big_blind,total_winnings,updated_at)
  SELECT gen_random_uuid(),s.uid::uuid,v_club,1,v_bb,coalesce(wo.amt,0),now()
    FROM seated s LEFT JOIN won wo ON wo.uid=s.uid
   WHERE EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=s.uid::uuid)
  ON CONFLICT (user_id,club_id) DO UPDATE SET
    hands_dealt=player_stats.hands_dealt+EXCLUDED.hands_dealt,
    sum_big_blind=player_stats.sum_big_blind+EXCLUDED.sum_big_blind,
    total_winnings=player_stats.total_winnings+EXCLUDED.total_winnings,
    updated_at=now();
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_fold_hand_winnings() OWNER TO postgres;

--
-- Name: fn_freeroll_fill_targets(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_freeroll_fill_targets(p_union uuid DEFAULT NULL::uuid) RETURNS TABLE(tournament_id uuid, name text, status text, current_players integer, max_players integer, minutes_to_start numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select t.id, t.name, t.status,
         coalesce(t.current_players, 0),
         coalesce(t.max_players, 0),
         round(extract(epoch from (t.start_time - now())) / 60.0, 1)
  from tournaments t
  left join clubs c on c.id = t.club_id
  where coalesce(t.buy_in_amount, 0) = 0
    and upper(t.status) in ('SCHEDULED', 'REGISTERING', 'ANNOUNCED', 'RUNNING')
    -- Registration is realistically open in this band: an hour before the
    -- start (the same pre-start ramp window humans browse in) through late
    -- registration shortly after it begins.
    and t.start_time > now() - interval '20 minutes'
    and t.start_time < now() + interval '90 minutes'
    and coalesce(t.max_players, 0) > coalesce(t.current_players, 0)
    and (p_union is null or c.union_id = p_union or c.id = p_union)
  order by t.start_time asc;
$$;


ALTER FUNCTION public.fn_freeroll_fill_targets(p_union uuid) OWNER TO postgres;

--
-- Name: fn_freerolls_are_free_buy(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_freerolls_are_free_buy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_changed jsonb := '{}'::jsonb;
  v_stack   integer;
  v_op      text;
  v_priced  boolean;
BEGIN
  IF NOT public.fn_is_free_buy_event(
       NEW.buy_in_amount, NEW.buy_in_fee, NEW.tournament_type, NEW.variant
     ) THEN
    RETURN NEW;
  END IF;

  -- A live or finished event keeps the contract its players entered under.
  -- Inserts are always pre-start.
  IF TG_OP = 'UPDATE'
     AND upper(COALESCE(NEW.status, '')) NOT IN ('ANNOUNCED', 'REGISTERING') THEN
    RETURN NEW;
  END IF;

  v_stack := COALESCE(NULLIF(NEW.starting_chips, 0), 10000);

  /* A SCHEDULED FREE BUY PRICES ITSELF (Dan 2026-09-04). `free_buy` marks the
     5-a-day board, whose feature event charges 2.00. Every other freeroll -
     anything created with a 0 buy-in anywhere in the product - still gets the
     1.00 default forced on it, which is the 2026-09-02 law unchanged. A NULL
     or non-positive price is never honoured: that is a missing value, not a
     decision, and it falls through to the default. */
  v_priced := COALESCE(NEW.free_buy, false) AND COALESCE(NEW.rebuy_cost, 0) > 0;

  IF NEW.buy_in_fee IS DISTINCT FROM 0 THEN
    v_changed := v_changed || jsonb_build_object('buy_in_fee',
      jsonb_build_object('from', NEW.buy_in_fee, 'to', 0));
    NEW.buy_in_fee := 0;
  END IF;

  IF NOT COALESCE(NEW.is_rebuy, false) THEN
    v_changed := v_changed || jsonb_build_object('is_rebuy',
      jsonb_build_object('from', NEW.is_rebuy, 'to', true));
    NEW.is_rebuy := true;
  END IF;

  IF NOT COALESCE(NEW.add_on_available, false) THEN
    v_changed := v_changed || jsonb_build_object('add_on_available',
      jsonb_build_object('from', NEW.add_on_available, 'to', true));
    NEW.add_on_available := true;
  END IF;

  IF NOT v_priced AND NEW.rebuy_cost IS DISTINCT FROM 1.00 THEN
    v_changed := v_changed || jsonb_build_object('rebuy_cost',
      jsonb_build_object('from', NEW.rebuy_cost, 'to', 1.00));
    NEW.rebuy_cost := 1.00;
  END IF;

  IF NOT v_priced AND NEW.addon_cost IS DISTINCT FROM 1.00 THEN
    v_changed := v_changed || jsonb_build_object('addon_cost',
      jsonb_build_object('from', NEW.addon_cost, 'to', 1.00));
    NEW.addon_cost := 1.00;
  END IF;

  /* A priced Free Buy that forgot its add-on price still gets one: the add-on
     matches the rebuy rather than falling to 1.00 under a 2.00 rebuy, which
     would be a price nobody chose. */
  IF v_priced AND COALESCE(NEW.addon_cost, 0) <= 0 THEN
    v_changed := v_changed || jsonb_build_object('addon_cost',
      jsonb_build_object('from', NEW.addon_cost, 'to', NEW.rebuy_cost));
    NEW.addon_cost := NEW.rebuy_cost;
  END IF;

  IF COALESCE(NEW.rebuy_chips, 0) <= 0 THEN
    v_changed := v_changed || jsonb_build_object('rebuy_chips',
      jsonb_build_object('from', NEW.rebuy_chips, 'to', v_stack));
    NEW.rebuy_chips := v_stack;
  END IF;

  IF COALESCE(NEW.addon_chips, 0) <= 0 THEN
    v_changed := v_changed || jsonb_build_object('addon_chips',
      jsonb_build_object('from', NEW.addon_chips, 'to', v_stack));
    NEW.addon_chips := v_stack;
  END IF;

  IF COALESCE(NEW.rebuy_levels, 0) <= 0 THEN
    v_changed := v_changed || jsonb_build_object('rebuy_levels',
      jsonb_build_object('from', NEW.rebuy_levels, 'to', 4));
    NEW.rebuy_levels := 4;
  END IF;

  IF COALESCE(NEW.addon_levels, 0) <= 0 THEN
    v_changed := v_changed || jsonb_build_object('addon_levels',
      jsonb_build_object('from', NEW.addon_levels, 'to', 1));
    NEW.addon_levels := 1;
  END IF;

  IF NEW.max_rebuys IS NOT NULL AND NEW.max_rebuys <= 0 THEN
    v_changed := v_changed || jsonb_build_object('max_rebuys',
      jsonb_build_object('from', NEW.max_rebuys, 'to', NULL));
    NEW.max_rebuys := NULL;
  END IF;

  IF v_changed <> '{}'::jsonb THEN
    v_op := CASE
      WHEN COALESCE(current_setting('app.freeroll_free_buy_backfill', true), '') = 'on'
        THEN 'BACKFILL'
      ELSE TG_OP
    END;
    BEGIN
      INSERT INTO public.ca_freeroll_free_buy_log
        (tournament_id, tournament_name, op, status, changed)
      VALUES
        (NEW.id, NEW.name, v_op, NEW.status, v_changed);
    EXCEPTION WHEN OTHERS THEN
      -- The log is evidence, not a gate. Never let it block the row.
      RAISE WARNING 'fn_freerolls_are_free_buy: could not log % for %: %',
        v_op, NEW.id, SQLERRM;
    END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_freerolls_are_free_buy() OWNER TO postgres;

--
-- Name: FUNCTION fn_freerolls_are_free_buy(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_freerolls_are_free_buy() IS 'BEFORE INSERT OR UPDATE on tournaments. When fn_is_free_buy_event says the row is a freeroll and it has not started, forces is_rebuy/add_on_available on at 1.00 each, fee 0, chips from starting_chips, windows 4/1, max_rebuys NULL when 0, and logs the diff to ca_freeroll_free_buy_log. It normalises; it never raises (Dan 2026-09-02: a refused scheduler insert would stop freerolls being created).';


