--
-- Name: fn_game_creation_access(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_game_creation_access(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user   uuid := auth.uid();
  v_own    uuid;
  v_member uuid;
  v_union  uuid;
  v_ok     boolean;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'union_id', NULL, 'reason', 'not_signed_in');
  END IF;
  IF p_club_id IS NULL OR NOT EXISTS (SELECT 1 FROM clubs c WHERE c.id = p_club_id) THEN
    RETURN jsonb_build_object('allowed', false, 'union_id', NULL, 'reason', 'unknown_club');
  END IF;

  SELECT own_union_id, member_union_id INTO v_own, v_member
    FROM fn_club_union_context(p_club_id);

  v_ok := fn_can_create_games(p_club_id, v_user);

  SELECT u.id INTO v_union FROM unions u WHERE u.id = COALESCE(v_own, v_member);

  RETURN jsonb_build_object(
    'allowed',  v_ok,
    'union_id', v_union,
    'reason',   CASE WHEN v_ok THEN 'ok'
                     WHEN v_member IS NOT NULL THEN 'union_only'
                     ELSE 'not_owner_or_admin' END
  );
END;
$$;


ALTER FUNCTION public.fn_game_creation_access(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_game_management_color_luminance(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_game_management_color_luminance(p_color text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_red numeric;
  v_green numeric;
  v_blue numeric;
BEGIN
  IF p_color !~ '^#[0-9A-Fa-f]{6}$' THEN
    RETURN NULL;
  END IF;
  v_red := get_byte(decode(substr(p_color, 2, 2), 'hex'), 0) / 255.0;
  v_green := get_byte(decode(substr(p_color, 4, 2), 'hex'), 0) / 255.0;
  v_blue := get_byte(decode(substr(p_color, 6, 2), 'hex'), 0) / 255.0;
  v_red := CASE WHEN v_red <= 0.03928 THEN v_red / 12.92 ELSE power((v_red + 0.055) / 1.055, 2.4) END;
  v_green := CASE WHEN v_green <= 0.03928 THEN v_green / 12.92 ELSE power((v_green + 0.055) / 1.055, 2.4) END;
  v_blue := CASE WHEN v_blue <= 0.03928 THEN v_blue / 12.92 ELSE power((v_blue + 0.055) / 1.055, 2.4) END;
  RETURN 0.2126 * v_red + 0.7152 * v_green + 0.0722 * v_blue;
END $_$;


ALTER FUNCTION public.fn_game_management_color_luminance(p_color text) OWNER TO postgres;

--
-- Name: fn_game_management_contrast_ratio(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_game_management_contrast_ratio(p_foreground text, p_background text) RETURNS numeric
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN public.fn_game_management_color_luminance(p_foreground) IS NULL
      OR public.fn_game_management_color_luminance(p_background) IS NULL THEN NULL
    ELSE
      (GREATEST(
        public.fn_game_management_color_luminance(p_foreground),
        public.fn_game_management_color_luminance(p_background)
      ) + 0.05)
      /
      (LEAST(
        public.fn_game_management_color_luminance(p_foreground),
        public.fn_game_management_color_luminance(p_background)
      ) + 0.05)
  END
$$;


ALTER FUNCTION public.fn_game_management_contrast_ratio(p_foreground text, p_background text) OWNER TO postgres;

--
-- Name: fn_game_management_scope(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_game_management_scope(p_club_id uuid) RETURNS TABLE(scope_kind text, scope_id uuid, union_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN x.union_id IS NULL THEN 'club' ELSE 'union' END,
         COALESCE(x.union_id, p_club_id), x.union_id
  FROM (
    SELECT COALESCE(c.union_id, uc.union_id) AS union_id
    FROM public.clubs c
    LEFT JOIN public.union_clubs uc ON uc.club_id=c.id
    WHERE c.id=p_club_id
    ORDER BY uc.joined_at DESC NULLS LAST
    LIMIT 1
  ) x
$$;


