--
-- Name: fn_generate_all_credit_invoices(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_generate_all_credit_invoices(p_period_end timestamp with time zone DEFAULT date_trunc('week'::text, now())) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_agent record;
  v_debt numeric;
  v_generated int := 0;
  v_duplicate int := 0;
  v_failed int := 0;
  v_skipped int := 0;
  v_period_start timestamptz := p_period_end - interval '7 days';
  v_due_date timestamptz := p_period_end + interval '2 days';
  v_res jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.is_admin()
     AND NOT EXISTS (SELECT 1 FROM public.club_members me
                      WHERE me.user_id = auth.uid()
                        AND me.role IN ('owner','co_owner','admin','manager')))) THEN
    RAISE EXCEPTION 'Not authorised to generate credit invoices';
  END IF;

  -- THE DEBT IS credit_used. It was the unused part of the line, so the less an
  -- agent had borrowed the more they were billed.
  FOR v_agent IN
    SELECT id, credit_used
      FROM agents
     WHERE COALESCE(is_prepaid, false) = false
       AND COALESCE(credit_used, 0) > 0
  LOOP
    v_debt := COALESCE(v_agent.credit_used, 0);
    IF v_debt <= 0 THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;
    v_res := fn_generate_credit_invoice(v_agent.id, v_period_start, p_period_end, v_debt, v_due_date);
    IF COALESCE((v_res->>'success')::boolean, false) THEN
      IF COALESCE((v_res->>'duplicate')::boolean, false)
        THEN v_duplicate := v_duplicate + 1;
        ELSE v_generated := v_generated + 1;
      END IF;
    ELSE
      v_failed := v_failed + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'generated', v_generated,
    'duplicate', v_duplicate, 'failed', v_failed, 'skipped', v_skipped,
    'period_end', p_period_end);
END;
$$;


ALTER FUNCTION public.fn_generate_all_credit_invoices(p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_generate_credit_invoice(uuid, timestamp with time zone, timestamp with time zone, numeric, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_generate_credit_invoice(p_agent_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_debt_owed numeric, p_due_date timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_row public.credit_invoices;
  v_used numeric;
  v_prepaid boolean;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( auth.uid() <> p_agent_id
     AND NOT public.is_admin()
     AND NOT EXISTS (
       SELECT 1 FROM public.club_members me
        WHERE me.user_id = auth.uid()
          AND me.role IN ('owner','co_owner','admin','manager')
          AND me.club_id IN (SELECT club_id FROM public.club_members
                              WHERE user_id = p_agent_id)))) THEN
    RAISE EXCEPTION 'Not authorised to generate an invoice for this agent';
  END IF;

  IF p_agent_id IS NULL OR p_debt_owed IS NULL OR p_debt_owed <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'agent and positive debt required');
  END IF;

  SELECT COALESCE(credit_used, 0), COALESCE(is_prepaid, false)
    INTO v_used, v_prepaid
    FROM public.agents WHERE id = p_agent_id;

  IF v_used IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'agent not found');
  END IF;
  IF v_prepaid THEN
    RETURN jsonb_build_object('success', false,
      'error', 'a prepaid agent borrows nothing and cannot be invoiced');
  END IF;
  IF v_used <= 0 THEN
    RETURN jsonb_build_object('success', false,
      'error', 'this agent has drawn no credit, so there is nothing to invoice',
      'credit_used', v_used);
  END IF;
  IF p_debt_owed > v_used THEN
    RETURN jsonb_build_object('success', false,
      'error', 'an invoice cannot exceed the credit actually drawn',
      'requested', p_debt_owed, 'credit_used', v_used);
  END IF;

  INSERT INTO public.credit_invoices (
    agent_id, period_start, period_end, debt_owed,
    amount_paid, amount_remaining, status, due_date
  ) VALUES (
    p_agent_id, p_period_start, p_period_end, p_debt_owed,
    0, p_debt_owed, 'pending', p_due_date
  )
  ON CONFLICT (agent_id, period_end) DO NOTHING
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    SELECT * INTO v_row FROM public.credit_invoices
    WHERE agent_id = p_agent_id AND period_end = p_period_end;
    RETURN jsonb_build_object('success', true, 'duplicate', true, 'invoice', to_jsonb(v_row));
  END IF;

  RETURN jsonb_build_object('success', true, 'duplicate', false, 'invoice', to_jsonb(v_row));
END;
$$;


ALTER FUNCTION public.fn_generate_credit_invoice(p_agent_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_debt_owed numeric, p_due_date timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_generate_recurring_home_games(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_generate_recurring_home_games() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group       RECORD;
    v_generated   int := 0;
    v_skipped     int := 0;
    v_target_date date;
    v_week        int;
    v_interval    interval;
    v_day_number  int;  -- 0=Sun..6=Sat
    v_weeks_max   int;
    v_new_game_id uuid;
BEGIN
    FOR v_group IN
        SELECT g.*, grp_sp.slug
          FROM commander_home_groups g
          LEFT JOIN social_pages grp_sp ON grp_sp.linked_entity_type='home_group' AND grp_sp.linked_entity_id=g.id::text
         WHERE g.is_active = true
           AND g.auto_generate_games = true
           AND g.frequency IN ('weekly','biweekly','monthly')
           AND g.typical_day IS NOT NULL
           AND g.typical_time IS NOT NULL
           AND g.last_activity_at > NOW() - INTERVAL '60 days'  -- skip dead groups
    LOOP
        -- Map typical_day text to day-number (0=Sunday..6=Saturday)
        v_day_number := CASE lower(v_group.typical_day)
            WHEN 'sunday' THEN 0 WHEN 'sun' THEN 0
            WHEN 'monday' THEN 1 WHEN 'mon' THEN 1
            WHEN 'tuesday' THEN 2 WHEN 'tue' THEN 2 WHEN 'tues' THEN 2
            WHEN 'wednesday' THEN 3 WHEN 'wed' THEN 3
            WHEN 'thursday' THEN 4 WHEN 'thu' THEN 4 WHEN 'thurs' THEN 4
            WHEN 'friday' THEN 5 WHEN 'fri' THEN 5
            WHEN 'saturday' THEN 6 WHEN 'sat' THEN 6
            ELSE NULL END;
        
        IF v_day_number IS NULL THEN 
            v_skipped := v_skipped + 1; 
            CONTINUE; 
        END IF;

        v_interval := CASE v_group.frequency
            WHEN 'weekly'   THEN INTERVAL '7 days'
            WHEN 'biweekly' THEN INTERVAL '14 days'
            WHEN 'monthly'  THEN INTERVAL '28 days'
            ELSE INTERVAL '7 days' END;

        v_weeks_max := COALESCE(v_group.auto_generate_weeks_ahead, 4);

        -- Find first target date: next occurrence of day_number starting tomorrow
        v_target_date := CURRENT_DATE + 1;
        WHILE EXTRACT(DOW FROM v_target_date)::int <> v_day_number LOOP
            v_target_date := v_target_date + 1;
        END LOOP;

        -- Generate for each cycle up to weeks_ahead
        FOR v_week IN 1..v_weeks_max LOOP
            -- Skip if a game already exists for this group on this date
            IF EXISTS (
                SELECT 1 FROM commander_home_games 
                 WHERE group_id = v_group.id 
                   AND scheduled_date = v_target_date
                   AND status NOT IN ('cancelled')
            ) THEN
                v_skipped := v_skipped + 1;
            ELSE
                INSERT INTO commander_home_games (
                    group_id, host_id, title, 
                    game_type, stakes, format,
                    buyin_min, buyin_max,
                    scheduled_date, start_time, 
                    max_players, 
                    status,
                    address_visible_to
                ) VALUES (
                    v_group.id, v_group.owner_id,
                    v_group.name || ' - ' || to_char(v_target_date, 'Mon DD'),
                    v_group.default_game_type, v_group.default_stakes, 'cash',
                    v_group.typical_buyin_min, v_group.typical_buyin_max,
                    v_target_date, v_group.typical_time,
                    COALESCE(v_group.max_players, 9),
                    'scheduled',
                    CASE WHEN v_group.is_private THEN 'members' ELSE 'rsvpd' END
                ) RETURNING id INTO v_new_game_id;

                INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
                VALUES (v_group.id, NULL, 'game', v_new_game_id, 'auto_generated',
                        jsonb_build_object('source','recurring_cron','scheduled_date', v_target_date,'week', v_week));

                v_generated := v_generated + 1;
            END IF;

            v_target_date := v_target_date + v_interval;
        END LOOP;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'generated', v_generated,
        'skipped', v_skipped,
        'run_at', NOW()
    );
END;
$$;


ALTER FUNCTION public.fn_generate_recurring_home_games() OWNER TO postgres;

--
-- Name: fn_generate_venue_slug(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_generate_venue_slug(p_name text, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE v_base text;
BEGIN
    -- Lowercase, strip non-alphanum (except space + hyphen), collapse whitespace/hyphens
    v_base := lower(COALESCE(p_name, ''));
    v_base := regexp_replace(v_base, '[''\u2019\u2018`]', '', 'g');                 -- apostrophes
    v_base := regexp_replace(v_base, '&', ' and ', 'g');                            -- ampersands
    v_base := regexp_replace(v_base, '[^a-z0-9]+', '-', 'g');                       -- anything else → hyphen
    v_base := regexp_replace(v_base, '^-+|-+$', '', 'g');                           -- trim leading/trailing hyphens
    v_base := regexp_replace(v_base, '-{2,}', '-', 'g');                            -- collapse multiple hyphens
    IF length(v_base) < 3 AND p_city IS NOT NULL THEN
        v_base := v_base || '-' || lower(regexp_replace(p_city, '[^a-z0-9]+', '-', 'g'));
        v_base := regexp_replace(v_base, '^-+|-+$', '', 'g');
    END IF;
    IF length(v_base) = 0 THEN v_base := 'poker-venue'; END IF;
    RETURN v_base;
END;
$_$;


ALTER FUNCTION public.fn_generate_venue_slug(p_name text, p_city text, p_state text) OWNER TO postgres;

