-- Name: fn_get_active_player_count(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_active_player_count(p_club_id uuid) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(DISTINCT ts.user_id)
  FROM table_seats ts
  INNER JOIN tables t ON ts.table_id = t.id
  WHERE t.club_id = p_club_id
    AND ts.left_at IS NULL
    AND COALESCE(ts.is_away, false) = false
    AND lower(COALESCE(t.status,'')) NOT IN ('closed','completed','cancelled','finished');
$$;


