--
-- Name: fn_get_agent_commission_summary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_agent_commission_summary(p_agent_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid    uuid;
  v_result jsonb;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    IF COALESCE(auth.role(), 'service_role') = 'service_role' AND p_agent_id IS NOT NULL THEN
      v_uid := p_agent_id;
    ELSE
      RETURN jsonb_build_object('error', 'identity required');
    END IF;
  END IF;
  -- A browser that passes somebody else's id is answered for ITSELF rather than
  -- refused, so a stale client cannot read another agent's book by passing an
  -- id it happens to know.

  SELECT jsonb_build_object(
           'total_earned',   COALESCE(SUM(ac.amount), 0),
           'this_week',      COALESCE(SUM(ac.amount) FILTER (WHERE ac.created_at >= now() - interval '7 days'), 0),
           'this_month',     COALESCE(SUM(ac.amount) FILTER (WHERE ac.created_at >= now() - interval '30 days'), 0),
           'pending_payout', COALESCE(SUM(ac.amount) FILTER (WHERE ac.settled_at IS NULL AND NOT public.fn_agent_commission_paid_by_period(ac.club_id, ac.user_id, ac.created_at)), 0),
           'last_payout',    GREATEST(MAX(ac.settled_at), (SELECT MAX(s.paid_at) FROM public.agent_commission_settlements s WHERE s.user_id = v_uid AND (p_club_id IS NULL OR s.club_id = p_club_id))))
    INTO v_result
    FROM public.agent_commissions ac
   WHERE ac.user_id = v_uid
     AND (p_club_id IS NULL OR ac.club_id = p_club_id);

  RETURN COALESCE(v_result, jsonb_build_object(
    'total_earned', 0, 'this_week', 0, 'this_month', 0,
    'pending_payout', 0, 'last_payout', NULL));
END;
$$;


ALTER FUNCTION public.fn_get_agent_commission_summary(p_agent_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_get_agent_commission_summary(p_agent_id uuid, p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_get_agent_commission_summary(p_agent_id uuid, p_club_id uuid) IS 'Agent commission summary read from agent_commissions. Replaced a stub that returned zeros in bigint columns while the ledger held 408,809.59 chips. pending_payout is what fn_agent_claim_commission would pay; last_payout is when the ledger says they were actually paid.';


--
-- Name: fn_get_all_identity_unread_counts(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_all_identity_unread_counts(p_user_id uuid) RETURNS TABLE(entity_id uuid, unread_total bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.context_entity_id AS entity_id,
         count(m.id)::bigint AS unread_total
    FROM social_conversation_participants p
    JOIN social_messages m ON m.conversation_id = p.conversation_id
   WHERE p.user_id = p_user_id
     AND p.context_entity_id IS NOT NULL
     AND COALESCE(m.is_deleted, false) = false
     AND m.sender_id IS DISTINCT FROM p_user_id
     AND NOT EXISTS (
         SELECT 1 FROM social_message_reads r
          WHERE r.message_id = m.id AND r.user_id = p_user_id
     )
   GROUP BY p.context_entity_id;
$$;


ALTER FUNCTION public.fn_get_all_identity_unread_counts(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_get_available_seats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_available_seats(p_table_id uuid) RETURNS TABLE(seat_number integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max_seats integer;
BEGIN
  SELECT COALESCE(max_players, 9) INTO v_max_seats FROM public.tables WHERE id = p_table_id;
  IF v_max_seats IS NULL THEN RETURN; END IF;
  RETURN QUERY
    SELECT s.seat_number FROM generate_series(1, v_max_seats) AS s(seat_number)
     WHERE s.seat_number NOT IN (
       SELECT ts.seat_number FROM public.table_seats ts
        WHERE ts.table_id = p_table_id AND ts.left_at IS NULL
     )
     ORDER BY s.seat_number;
END $$;


ALTER FUNCTION public.fn_get_available_seats(p_table_id uuid) OWNER TO postgres;

