--
-- Name: fn_get_game_management_health(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_game_management_health(p_scope text, p_scope_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_authorized boolean;
  v_access jsonb;
  v_latest_sequence bigint := 0;
  v_last_event_at timestamptz;
  v_events_last_hour bigint := 0;
  v_commands_last_24h bigint := 0;
  v_rejected_last_24h bigint := 0;
  v_integrity_alerts bigint := 0;
BEGIN
  IF p_scope='club' THEN
    v_access:=public.fn_game_creation_access(p_scope_id);
    v_authorized:=COALESCE((v_access->>'allowed')::boolean,false)
      AND v_access->>'union_id' IS NULL;
  ELSIF p_scope='union' THEN
    v_authorized:=public.fn_is_union_operator(p_scope_id,auth.uid());
  ELSE
    v_authorized:=false;
  END IF;
  IF NOT COALESCE(v_authorized,false) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized');
  END IF;

  SELECT e.sequence, e.created_at
    INTO v_latest_sequence, v_last_event_at
    FROM public.game_management_events e
   WHERE e.scope_kind=p_scope AND e.scope_id=p_scope_id
   ORDER BY e.sequence DESC
   LIMIT 1;

  SELECT
    count(*) FILTER (WHERE e.created_at>=now()-interval '1 hour'),
    count(*) FILTER (WHERE e.event_type LIKE 'game_command_%'),
    count(*) FILTER (WHERE e.event_type='game_command_rejected')
    INTO v_events_last_hour,v_commands_last_24h,v_rejected_last_24h
    FROM public.game_management_events e
   WHERE e.scope_kind=p_scope
     AND e.scope_id=p_scope_id
     AND e.created_at>=now()-interval '24 hours';

  SELECT count(*) INTO v_integrity_alerts
    FROM public.managed_game_command_receipts r
   WHERE (
       (r.status='processing' AND r.created_at<now()-interval '5 minutes')
       OR (r.status='succeeded' AND r.contract_version_after IS NULL)
     )
     AND (
       r.game_kind='table' AND EXISTS (
         SELECT 1 FROM public.tables t WHERE t.id=r.game_id AND (
           (p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
           OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=p_scope_id
             OR EXISTS (SELECT 1 FROM public.union_clubs uc
               WHERE uc.club_id=t.club_id AND uc.union_id=p_scope_id)
             OR EXISTS (SELECT 1 FROM public.clubs c
               WHERE c.id=t.club_id AND c.union_id=p_scope_id)))
         )
       )
       OR r.game_kind='tournament' AND EXISTS (
         SELECT 1 FROM public.tournaments t WHERE t.id=r.game_id AND (
           (p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
           OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=p_scope_id
             OR EXISTS (SELECT 1 FROM public.union_clubs uc
               WHERE uc.club_id=t.club_id AND uc.union_id=p_scope_id)
             OR EXISTS (SELECT 1 FROM public.clubs c
               WHERE c.id=t.club_id AND c.union_id=p_scope_id)))
         )
       )
     );

  RETURN jsonb_build_object(
    'ok',true,
    'latest_event_sequence',COALESCE(v_latest_sequence,0),
    'last_event_at',v_last_event_at,
    'events_last_hour',COALESCE(v_events_last_hour,0),
    'commands_last_24h',COALESCE(v_commands_last_24h,0),
    'rejected_last_24h',COALESCE(v_rejected_last_24h,0),
    'integrity_alerts',COALESCE(v_integrity_alerts,0));
END;
$$;


ALTER FUNCTION public.fn_get_game_management_health(p_scope text, p_scope_id uuid) OWNER TO postgres;

--
-- Name: fn_get_game_management_scale_health(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_game_management_scale_health(p_scope text, p_scope_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_access jsonb; v_authorized boolean; v_scope_clubs uuid[];
BEGIN
  IF p_scope='club' THEN
    v_access:=public.fn_game_creation_access(p_scope_id);
    v_authorized:=COALESCE((v_access->>'allowed')::boolean,false)
      AND v_access->>'union_id' IS NULL;
  ELSIF p_scope='union' THEN
    v_authorized:=public.fn_is_union_operator(p_scope_id,auth.uid());
  ELSE
    v_authorized:=false;
  END IF;
  IF NOT COALESCE(v_authorized,false) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized');
  END IF;
  IF p_scope='union' THEN
    SELECT COALESCE(array_agg(x.club_id),'{}'::uuid[]) INTO v_scope_clubs
    FROM (
      SELECT p_scope_id AS club_id
      UNION SELECT uc.club_id FROM public.union_clubs uc WHERE uc.union_id=p_scope_id
      UNION SELECT c.id FROM public.clubs c WHERE c.union_id=p_scope_id
    ) x;
  END IF;
  RETURN jsonb_build_object('ok',true,
    'scheduled_pending',(SELECT count(*) FROM public.managed_game_schedules s
      WHERE s.status IN ('scheduled','executing') AND (
        (s.game_kind='table' AND EXISTS(SELECT 1 FROM public.tables t WHERE t.id=s.game_id AND
          ((p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
            OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=ANY(v_scope_clubs))))))
        OR (s.game_kind='tournament' AND EXISTS(SELECT 1 FROM public.tournaments t WHERE t.id=s.game_id AND
          ((p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
            OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=ANY(v_scope_clubs))))))
      )),
    'scheduled_rejected_24h',(SELECT count(*) FROM public.managed_game_schedules s
      WHERE s.status='rejected' AND s.completed_at>=now()-interval '24 hours' AND (
        (s.game_kind='table' AND EXISTS(SELECT 1 FROM public.tables t WHERE t.id=s.game_id AND
          ((p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
            OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=ANY(v_scope_clubs))))))
        OR (s.game_kind='tournament' AND EXISTS(SELECT 1 FROM public.tournaments t WHERE t.id=s.game_id AND
          ((p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
            OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=ANY(v_scope_clubs))))))
      )),
    'event_rows',(SELECT count(*) FROM public.game_management_events WHERE scope_kind=p_scope AND scope_id=p_scope_id),
    'oldest_event_at',(SELECT min(created_at) FROM public.game_management_events WHERE scope_kind=p_scope AND scope_id=p_scope_id),
    'retention_days',30,'page_limit',100);
END;
$$;


ALTER FUNCTION public.fn_get_game_management_scale_health(p_scope text, p_scope_id uuid) OWNER TO postgres;

--
-- Name: fn_get_game_ticker_settings(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_game_ticker_settings(p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid:=auth.uid(); v_settings jsonb; v_union uuid:=p_union_id;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  IF v_union IS NULL AND p_club_id IS NOT NULL THEN
    SELECT member_union_id INTO v_union FROM public.fn_club_union_context(p_club_id);
  END IF;
  IF v_union IS NOT NULL THEN
    IF NOT (public.fn_is_union_operator(v_union,v_uid) OR EXISTS(
      SELECT 1 FROM public.union_clubs uc JOIN public.club_members cm ON cm.club_id=uc.club_id
      WHERE uc.union_id=v_union AND cm.user_id=v_uid AND cm.status IN ('active','approved')
    )) THEN RETURN NULL; END IF;
    SELECT settings INTO v_settings FROM public.game_ticker_settings WHERE union_id=v_union;
  ELSE
    IF p_club_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.club_members cm WHERE cm.club_id=p_club_id AND cm.user_id=v_uid AND cm.status IN ('active','approved')) THEN RETURN NULL; END IF;
    SELECT settings INTO v_settings FROM public.game_ticker_settings WHERE club_id=p_club_id;
  END IF;
  RETURN COALESCE(v_settings,'{}'::jsonb);
END $$;


ALTER FUNCTION public.fn_get_game_ticker_settings(p_club_id uuid, p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_get_game_ticker_settings_for_management(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_game_ticker_settings_for_management(p_scope text, p_scope_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_settings jsonb;
  v_revision bigint;
  v_updated_at timestamptz;
  v_access jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;
  IF p_scope NOT IN ('club', 'union') OR p_scope_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_scope');
  END IF;
  IF p_scope = 'club' THEN
    v_access := public.fn_game_creation_access(p_scope_id);
    IF COALESCE((v_access->>'allowed')::boolean, false) = false
      OR v_access->>'union_id' IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
    END IF;
    SELECT settings, revision, updated_at
      INTO v_settings, v_revision, v_updated_at
      FROM public.game_ticker_settings
      WHERE club_id = p_scope_id;
  ELSE
    IF NOT public.fn_is_union_operator(p_scope_id, v_uid) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
    END IF;
    SELECT settings, revision, updated_at
      INTO v_settings, v_revision, v_updated_at
      FROM public.game_ticker_settings
      WHERE union_id = p_scope_id;
  END IF;
  RETURN jsonb_build_object(
    'ok', true,
    'settings', COALESCE(v_settings, '{}'::jsonb),
    'revision', COALESCE(v_revision, 0),
    'updated_at', v_updated_at
  );
END $$;


ALTER FUNCTION public.fn_get_game_ticker_settings_for_management(p_scope text, p_scope_id uuid) OWNER TO postgres;

--
-- Name: fn_get_home_games_onboarding_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_home_games_onboarding_status(p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_profile RECORD;
  v_tos_v   text;
  v_priv_v  text;
  v_cg_v    text;
  v_money_v text;
  v_min_age int;
  v_needs jsonb := '[]'::jsonb;
  v_has_tos   boolean := false;
  v_has_priv  boolean := false;
  v_has_cg    boolean := false;
  v_has_money boolean := false;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED';
  END IF;

  SELECT id, over_18_attested_at, jurisdiction_country,
         jurisdiction_region, jurisdiction_acknowledged_at,
         home_games_onboarded_at
    INTO v_profile
    FROM public.profiles WHERE id = p_caller_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'PROFILE_NOT_FOUND'; END IF;

  SELECT value INTO v_tos_v   FROM public.platform_policies WHERE key = 'home_games.tos.version';
  SELECT value INTO v_priv_v  FROM public.platform_policies WHERE key = 'home_games.privacy.version';
  SELECT value INTO v_cg_v    FROM public.platform_policies WHERE key = 'home_games.community_guidelines.version';
  SELECT value INTO v_money_v FROM public.platform_policies WHERE key = 'home_games.money_policy.version';
  SELECT value::int INTO v_min_age FROM public.platform_policies WHERE key = 'home_games.minimum_age';
  IF v_min_age IS NULL THEN v_min_age := 18; END IF;

  SELECT EXISTS (SELECT 1 FROM public.user_tos_acceptances
                  WHERE user_id=p_caller_user_id AND policy_key='home_games.tos'
                    AND policy_version = v_tos_v) INTO v_has_tos;
  SELECT EXISTS (SELECT 1 FROM public.user_tos_acceptances
                  WHERE user_id=p_caller_user_id AND policy_key='home_games.privacy'
                    AND policy_version = v_priv_v) INTO v_has_priv;
  SELECT EXISTS (SELECT 1 FROM public.user_tos_acceptances
                  WHERE user_id=p_caller_user_id AND policy_key='home_games.community_guidelines'
                    AND policy_version = v_cg_v) INTO v_has_cg;
  SELECT EXISTS (SELECT 1 FROM public.user_tos_acceptances
                  WHERE user_id=p_caller_user_id AND policy_key='home_games.money_policy'
                    AND policy_version = v_money_v) INTO v_has_money;

  IF v_profile.over_18_attested_at IS NULL THEN
    v_needs := v_needs || jsonb_build_array('over_18_attestation');
  END IF;
  IF v_profile.jurisdiction_acknowledged_at IS NULL THEN
    v_needs := v_needs || jsonb_build_array('jurisdiction_acknowledgement');
  END IF;
  IF NOT v_has_tos   THEN v_needs := v_needs || jsonb_build_array('tos_acceptance');                  END IF;
  IF NOT v_has_priv  THEN v_needs := v_needs || jsonb_build_array('privacy_acceptance');              END IF;
  IF NOT v_has_cg    THEN v_needs := v_needs || jsonb_build_array('community_guidelines_acceptance'); END IF;
  IF NOT v_has_money THEN v_needs := v_needs || jsonb_build_array('money_policy_acknowledgement');    END IF;

  IF jsonb_array_length(v_needs) = 0 AND v_profile.home_games_onboarded_at IS NULL THEN
    UPDATE public.profiles SET home_games_onboarded_at = now() WHERE id = p_caller_user_id;
  END IF;

  RETURN jsonb_build_object(
    'success',     true,
    'onboarded',   (jsonb_array_length(v_needs) = 0),
    'needs',       v_needs,
    'versions',    jsonb_build_object(
                     'tos',                  v_tos_v,
                     'privacy',              v_priv_v,
                     'community_guidelines', v_cg_v,
                     'money_policy',         v_money_v
                   ),
    'minimum_age', v_min_age,
    'current_attestations', jsonb_build_object(
       'over_18_at',           v_profile.over_18_attested_at,
       'jurisdiction_country', v_profile.jurisdiction_country,
       'jurisdiction_region',  v_profile.jurisdiction_region,
       'jurisdiction_ack_at',  v_profile.jurisdiction_acknowledged_at
    )
  );
END;
$$;


ALTER FUNCTION public.fn_get_home_games_onboarding_status(p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: fn_get_home_games_onboarding_status_admin(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_home_games_onboarding_status_admin(p_caller_user_id uuid, p_target_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role    text;
  v_profile RECORD;
  v_tos_v   text; v_priv_v text; v_cg_v text; v_money_v text;
  v_min_age int;
  v_needs jsonb := '[]'::jsonb;
  v_has_tos   boolean := false;
  v_has_priv  boolean := false;
  v_has_cg    boolean := false;
  v_has_money boolean := false;
BEGIN
  -- Caller identity + admin role
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_caller_user_id THEN
      RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;
    SELECT role INTO v_role FROM public.profiles WHERE id = p_caller_user_id;
    IF v_role NOT IN ('admin','superadmin','god') THEN
      RAISE EXCEPTION 'FORBIDDEN' USING HINT = 'admin-only lookup';
    END IF;
  END IF;

  SELECT id, over_18_attested_at, jurisdiction_country,
         jurisdiction_region, jurisdiction_acknowledged_at,
         home_games_onboarded_at, role, display_name, username, full_name
    INTO v_profile
    FROM public.profiles WHERE id = p_target_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'TARGET_NOT_FOUND'; END IF;

  SELECT value INTO v_tos_v   FROM public.platform_policies WHERE key='home_games.tos.version';
  SELECT value INTO v_priv_v  FROM public.platform_policies WHERE key='home_games.privacy.version';
  SELECT value INTO v_cg_v    FROM public.platform_policies WHERE key='home_games.community_guidelines.version';
  SELECT value INTO v_money_v FROM public.platform_policies WHERE key='home_games.money_policy.version';
  SELECT value::int INTO v_min_age FROM public.platform_policies WHERE key='home_games.minimum_age';
  IF v_min_age IS NULL THEN v_min_age := 18; END IF;

  SELECT EXISTS (SELECT 1 FROM public.user_tos_acceptances
                  WHERE user_id=p_target_user_id AND policy_key='home_games.tos'
                    AND policy_version = v_tos_v) INTO v_has_tos;
  SELECT EXISTS (SELECT 1 FROM public.user_tos_acceptances
                  WHERE user_id=p_target_user_id AND policy_key='home_games.privacy'
                    AND policy_version = v_priv_v) INTO v_has_priv;
  SELECT EXISTS (SELECT 1 FROM public.user_tos_acceptances
                  WHERE user_id=p_target_user_id AND policy_key='home_games.community_guidelines'
                    AND policy_version = v_cg_v) INTO v_has_cg;
  SELECT EXISTS (SELECT 1 FROM public.user_tos_acceptances
                  WHERE user_id=p_target_user_id AND policy_key='home_games.money_policy'
                    AND policy_version = v_money_v) INTO v_has_money;

  IF v_profile.over_18_attested_at IS NULL           THEN v_needs := v_needs || jsonb_build_array('over_18_attestation');          END IF;
  IF v_profile.jurisdiction_acknowledged_at IS NULL THEN v_needs := v_needs || jsonb_build_array('jurisdiction_acknowledgement'); END IF;
  IF NOT v_has_tos   THEN v_needs := v_needs || jsonb_build_array('tos_acceptance');                  END IF;
  IF NOT v_has_priv  THEN v_needs := v_needs || jsonb_build_array('privacy_acceptance');              END IF;
  IF NOT v_has_cg    THEN v_needs := v_needs || jsonb_build_array('community_guidelines_acceptance'); END IF;
  IF NOT v_has_money THEN v_needs := v_needs || jsonb_build_array('money_policy_acknowledgement');    END IF;

  -- Admin READ does NOT auto-flip home_games_onboarded_at (unlike caller-self fn)

  -- Audit the lookup (PII read)
  INSERT INTO public.commander_home_audit_log
    (group_id, actor_id, target_type, target_id, action, metadata)
  VALUES (NULL, p_caller_user_id, 'user', p_target_user_id, 'admin_onboarding_lookup',
          jsonb_build_object('onboarded', (jsonb_array_length(v_needs) = 0)));

  RETURN jsonb_build_object(
    'success',     true,
    'target_user_id', p_target_user_id,
    'display_name',   COALESCE(v_profile.display_name, v_profile.full_name, v_profile.username, 'Unknown'),
    'role',        v_profile.role,
    'onboarded',   (jsonb_array_length(v_needs) = 0),
    'onboarded_at', v_profile.home_games_onboarded_at,
    'needs',       v_needs,
    'versions',    jsonb_build_object(
                     'tos',                  v_tos_v,
                     'privacy',              v_priv_v,
                     'community_guidelines', v_cg_v,
                     'money_policy',         v_money_v),
    'minimum_age', v_min_age,
    'current_attestations', jsonb_build_object(
       'over_18_at',           v_profile.over_18_attested_at,
       'jurisdiction_country', v_profile.jurisdiction_country,
       'jurisdiction_region',  v_profile.jurisdiction_region,
       'jurisdiction_ack_at',  v_profile.jurisdiction_acknowledged_at)
  );
END;
$$;


ALTER FUNCTION public.fn_get_home_games_onboarding_status_admin(p_caller_user_id uuid, p_target_user_id uuid) OWNER TO postgres;

--
-- Name: fn_get_home_group_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_home_group_dashboard(p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '42501';
  END IF;
  RETURN public.fn_get_home_group_dashboard(p_group_id, v_uid);
END;
$$;


ALTER FUNCTION public.fn_get_home_group_dashboard(p_group_id uuid) OWNER TO postgres;

--
-- Name: fn_get_home_group_dashboard(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_home_group_dashboard(p_group_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_group RECORD; v_is_staff boolean; v_slug text;
  v_next_game_row RECORD; v_recent_game_row RECORD;
  v_pending_reports int; v_pending_join_reqs int; v_open_polls int;
  v_has_template boolean; v_has_first_game boolean; v_has_invite_link boolean;
  v_result jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_caller_user_id THEN
      RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;

  v_is_staff := (v_group.owner_id = p_caller_user_id)
    OR EXISTS (SELECT 1 FROM commander_home_members
                WHERE group_id = p_group_id AND user_id = p_caller_user_id
                  AND role IN ('admin','co_host') AND status = 'approved');
  IF NOT v_is_staff THEN RAISE EXCEPTION 'NOT_GROUP_STAFF' USING ERRCODE = '42501'; END IF;

  SELECT slug INTO v_slug FROM social_pages
   WHERE linked_entity_type='home_group' AND linked_entity_id = p_group_id::text LIMIT 1;

  SELECT gm.id, gm.title,
         (gm.scheduled_date || ' ' || COALESCE(gm.start_time, '19:00:00'::time))::timestamp
           AT TIME ZONE COALESCE(gm.timezone, 'UTC') AS starts_at,
         gm.rsvp_yes, gm.rsvp_maybe, gm.rsvp_no, gm.waitlist_count,
         gm.max_players, gm.stakes, gm.format, gm.address_visible_to, gm.status
    INTO v_next_game_row FROM commander_home_games gm
   WHERE gm.group_id = p_group_id
     AND gm.status IN ('scheduled','confirmed')
     AND gm.scheduled_date >= CURRENT_DATE
   ORDER BY gm.scheduled_date ASC, gm.start_time ASC NULLS LAST LIMIT 1;

  SELECT gm.id, gm.title, gm.scheduled_date, gm.status,
         (SELECT COUNT(*) FROM commander_home_game_reviews r WHERE r.game_id = gm.id) AS review_count
    INTO v_recent_game_row FROM commander_home_games gm
   WHERE gm.group_id = p_group_id AND gm.status IN ('completed','cancelled')
   ORDER BY gm.scheduled_date DESC, gm.start_time DESC NULLS LAST LIMIT 1;

  SELECT COUNT(*)::int INTO v_pending_reports
    FROM commander_home_content_reports r
   WHERE r.status IN ('pending','hidden_pending_review')
     AND (
       (r.reported_type IN ('post','comment')
         AND r.reported_id IN (SELECT p.id FROM commander_home_posts p WHERE p.group_id = p_group_id))
       OR (r.reported_type = 'game'
         AND r.reported_id IN (SELECT g.id FROM commander_home_games g WHERE g.group_id = p_group_id))
       OR (r.reported_type = 'review'
         AND r.reported_id IN (
           SELECT rv.id FROM commander_home_game_reviews rv
           JOIN commander_home_games g ON g.id = rv.game_id WHERE g.group_id = p_group_id))
       OR (r.reported_type = 'member'
         AND r.reported_id IN (SELECT m.id FROM commander_home_members m WHERE m.group_id = p_group_id))
     );

  SELECT COUNT(*)::int INTO v_pending_join_reqs FROM commander_home_members
   WHERE group_id = p_group_id AND status = 'pending';

  -- Fixed table name: commander_home_polls (not *_group_polls)
  SELECT COUNT(*)::int INTO v_open_polls FROM commander_home_polls
   WHERE group_id = p_group_id
     AND (closes_at IS NULL OR closes_at > NOW());

  SELECT EXISTS (SELECT 1 FROM commander_home_game_templates WHERE group_id = p_group_id) INTO v_has_template;
  SELECT EXISTS (SELECT 1 FROM commander_home_games          WHERE group_id = p_group_id) INTO v_has_first_game;
  SELECT EXISTS (SELECT 1 FROM commander_home_invite_tokens
                  WHERE group_id = p_group_id AND is_active = true
                    AND (expires_at IS NULL OR expires_at > NOW())) INTO v_has_invite_link;

  v_result := jsonb_build_object(
    'success', true,
    'group', jsonb_build_object(
      'id', v_group.id, 'name', v_group.name, 'slug', v_slug, 'city', v_group.city,
      'is_private', v_group.is_private, 'is_21_plus', v_group.is_21_plus,
      'member_count', v_group.member_count, 'profile_photo_url', v_group.profile_photo_url,
      'created_at', v_group.created_at,
      'promotion_requested_at', v_group.promotion_requested_at,
      'promoted_to_club_id', v_group.promoted_to_club_id),
    'next_game', CASE WHEN v_next_game_row.id IS NULL THEN NULL ELSE
      jsonb_build_object(
        'id', v_next_game_row.id, 'title', v_next_game_row.title,
        'starts_at', v_next_game_row.starts_at,
        'rsvp_yes', v_next_game_row.rsvp_yes, 'rsvp_maybe', v_next_game_row.rsvp_maybe,
        'rsvp_no', v_next_game_row.rsvp_no, 'waitlist_count', v_next_game_row.waitlist_count,
        'max_players', v_next_game_row.max_players, 'stakes', v_next_game_row.stakes,
        'format', v_next_game_row.format, 'status', v_next_game_row.status,
        'address_visible_to', v_next_game_row.address_visible_to) END,
    'recent_game', CASE WHEN v_recent_game_row.id IS NULL THEN NULL ELSE
      jsonb_build_object(
        'id', v_recent_game_row.id, 'title', v_recent_game_row.title,
        'scheduled_date', v_recent_game_row.scheduled_date,
        'status', v_recent_game_row.status, 'review_count', v_recent_game_row.review_count) END,
    'counters', jsonb_build_object(
      'pending_reports', v_pending_reports,
      'pending_join_requests', v_pending_join_reqs,
      'open_polls', v_open_polls),
    'onboarding_checklist', jsonb_build_object(
      'has_game_template', v_has_template,
      'has_first_game', v_has_first_game,
      'has_invite_link', v_has_invite_link,
      'all_complete', (v_has_template AND v_has_first_game AND v_has_invite_link))
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_get_home_group_dashboard(p_group_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: fn_get_leaderboard_reward_plan(uuid, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_leaderboard_reward_plan(p_club_id uuid, p_period text, p_period_start date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_period_start date := p_period_start;
  v_program public.leaderboard_reward_program_versions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Not Authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_period NOT IN ('weekly', 'monthly') THEN
    RAISE EXCEPTION 'Only Weekly And Monthly Reward Programs Are Supported'
      USING ERRCODE = '22023';
  END IF;
  IF v_period_start IS NULL THEN
    SELECT bounds.start_date INTO v_period_start
      FROM public.fn_leaderboard_period_window(p_period, 0) bounds;
  END IF;
  IF (p_period = 'weekly' AND EXTRACT(DOW FROM v_period_start)::integer <> 0)
     OR (p_period = 'monthly' AND EXTRACT(DAY FROM v_period_start)::integer <> 1) THEN
    RAISE EXCEPTION 'Reward Programs Require A Canonical UTC Period Start'
      USING ERRCODE = '22023';
  END IF;

  SELECT program.* INTO v_program
    FROM public.leaderboard_reward_program_versions program
   WHERE program.club_id = p_club_id
     AND CASE p_period
       WHEN 'weekly' THEN program.weekly_effective_from <= v_period_start
       ELSE program.monthly_effective_from <= v_period_start
     END
   ORDER BY program.version DESC
   LIMIT 1;

  IF v_program.id IS NULL THEN RETURN NULL; END IF;
  RETURN jsonb_build_object(
    'program_id', v_program.id,
    'program_version', v_program.version,
    'program_hash', v_program.program_hash,
    'status', v_program.status,
    'rewards_enabled', v_program.rewards_enabled,
    'period', p_period,
    'period_start', v_period_start,
    'payout_metric', v_program.payout_metric,
    'prizes', CASE p_period
      WHEN 'weekly' THEN v_program.weekly_prizes
      ELSE v_program.monthly_prizes
    END,
    'funding_owner_type', v_program.funding_owner_type,
    'funding_union_id', v_program.funding_union_id,
    'published_at', v_program.published_at
  );
END;
$$;


ALTER FUNCTION public.fn_get_leaderboard_reward_plan(p_club_id uuid, p_period text, p_period_start date) OWNER TO postgres;

--
-- Name: FUNCTION fn_get_leaderboard_reward_plan(p_club_id uuid, p_period text, p_period_start date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_get_leaderboard_reward_plan(p_club_id uuid, p_period text, p_period_start date) IS 'Resolves the immutable published reward program for one canonical weekly or monthly period start.';


--
-- Name: fn_get_leaderboard_reward_setup(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_leaderboard_reward_setup(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_club record;
  v_union_id uuid;
  v_union_name text;
  v_can_manage boolean := false;
  v_is_member boolean := false;
  v_settings public.club_leaderboard_settings%ROWTYPE;
  v_program public.leaderboard_reward_program_versions%ROWTYPE;
  v_program_union_name text;
  v_funding jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not Authenticated' USING ERRCODE = '42501'; END IF;
  SELECT club.id, club.name, club.owner_id INTO v_club
    FROM public.clubs club WHERE club.id = p_club_id;
  IF v_club.id IS NULL THEN RAISE EXCEPTION 'Club Not Found' USING ERRCODE = 'P0002'; END IF;

  v_union_id := public.fn_leaderboard_funding_union_id(p_club_id);
  SELECT EXISTS (
    SELECT 1 FROM public.club_members member WHERE member.club_id = p_club_id
      AND member.user_id = v_actor
      AND COALESCE(member.status, 'active') IN ('active', 'approved')
  ) INTO v_is_member;
  IF v_union_id IS NOT NULL THEN
    v_can_manage := public.fn_union_can_manage_wallets(v_union_id, v_actor);
    SELECT union_row.name INTO v_union_name
      FROM public.unions union_row
     WHERE union_row.id = v_union_id;
  ELSE
    v_can_manage := v_club.owner_id = v_actor OR EXISTS (
      SELECT 1 FROM public.club_members member WHERE member.club_id = p_club_id
        AND member.user_id = v_actor AND member.role IN ('owner', 'co_owner')
        AND COALESCE(member.status, 'active') IN ('active', 'approved')
    );
  END IF;
  IF NOT v_is_member AND NOT v_can_manage THEN
    RAISE EXCEPTION 'Leaderboard Reward Setup Is Not Available For This Club'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_settings FROM public.club_leaderboard_settings settings
   WHERE settings.club_id = p_club_id;
  SELECT * INTO v_program FROM public.leaderboard_reward_program_versions program
   WHERE program.club_id = p_club_id ORDER BY program.version DESC LIMIT 1;
  IF v_program.funding_owner_type = 'union' THEN
    SELECT union_row.name INTO v_program_union_name FROM public.unions union_row
     WHERE union_row.id = v_program.funding_union_id;
  END IF;
  v_funding := public.fn_leaderboard_funding_summary(p_club_id);

  RETURN jsonb_build_object(
    'club_id', p_club_id, 'club_name', v_club.name,
    'union_id', v_union_id, 'union_name', v_union_name,
    'funding_owner_type', CASE WHEN v_union_id IS NULL THEN 'club' ELSE 'union' END,
    'funding_source', CASE WHEN v_union_id IS NULL THEN 'club_promo_balance' ELSE 'union_promo_wallet' END,
    'funding_label', CASE WHEN v_union_id IS NULL THEN v_club.name || ' Promo Wallet' ELSE v_union_name || ' Promo Wallet' END,
    'available_balance', CASE WHEN v_can_manage THEN v_funding -> 'publication_capacity' ELSE NULL END,
    'wallet_balance', CASE WHEN v_can_manage THEN v_funding -> 'wallet_balance' ELSE NULL END,
    'committed_balance', CASE WHEN v_can_manage THEN v_funding -> 'committed_balance' ELSE NULL END,
    'current_program_commitment', CASE WHEN v_can_manage THEN v_funding -> 'current_program_commitment' ELSE NULL END,
    'other_program_commitments', CASE WHEN v_can_manage THEN v_funding -> 'other_program_commitments' ELSE NULL END,
    'available_uncommitted_balance', CASE WHEN v_can_manage THEN v_funding -> 'available_uncommitted_balance' ELSE NULL END,
    'publication_capacity', CASE WHEN v_can_manage THEN v_funding -> 'publication_capacity' ELSE NULL END,
    'committed_club_count', CASE WHEN v_can_manage THEN v_funding -> 'committed_club_count' ELSE NULL END,
    'funding_status', v_funding ->> 'funding_status',
    'can_manage', v_can_manage,
    'setup_complete', v_settings.setup_completed_at IS NOT NULL,
    'rewards_enabled', COALESCE(v_program.rewards_enabled, v_settings.rewards_enabled, false),
    'payout_currency', 'chips',
    'payout_metric', COALESCE(v_program.payout_metric, v_settings.payout_metric, 'profit'),
    'weekly_prizes', COALESCE(v_program.weekly_prizes, v_settings.weekly_prizes, '[]'::jsonb),
    'monthly_prizes', COALESCE(v_program.monthly_prizes, v_settings.monthly_prizes, '[]'::jsonb),
    'suggestion_key', COALESCE(v_program.suggestion_key, v_settings.suggestion_key, 'balanced'),
    'program_version', COALESCE(v_program.version, 0),
    'program_hash', v_program.program_hash,
    'program_status', CASE WHEN v_program.id IS NULL THEN 'not_published' ELSE 'published' END,
    'weekly_effective_from', v_program.weekly_effective_from,
    'monthly_effective_from', v_program.monthly_effective_from,
    'published_at', v_program.published_at,
    'program_funding_owner_type', v_program.funding_owner_type,
    'program_funding_union_id', v_program.funding_union_id,
    'program_funding_label', CASE
      WHEN v_program.id IS NULL THEN NULL
      WHEN v_program.funding_owner_type = 'union'
        THEN COALESCE(v_program_union_name, 'Recorded Union') || ' Promo Wallet'
      ELSE v_club.name || ' Promo Wallet'
    END,
    'setup_completed_at', v_settings.setup_completed_at,
    'updated_at', COALESCE(v_program.published_at, v_settings.updated_at)
  );
END;
$$;


ALTER FUNCTION public.fn_get_leaderboard_reward_setup(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_get_leaderboard_settlement_status(uuid, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_leaderboard_settlement_status(p_club_id uuid, p_period text, p_period_start date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_club record;
  v_is_member boolean := false;
  v_can_manage boolean := false;
  v_is_platform_admin boolean := false;
  v_period_end date;
  v_plan jsonb;
  v_batch public.leaderboard_payout_batches%ROWTYPE;
  v_failure public.leaderboard_payout_failures%ROWTYPE;
  v_receipts jsonb := '[]'::jsonb;
  v_state text;
  v_planned_total numeric(18,2) := 0;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication Required' USING ERRCODE = '42501';
  END IF;
  IF p_period NOT IN ('weekly', 'monthly') OR p_period_start IS NULL THEN
    RAISE EXCEPTION 'A Canonical Weekly Or Monthly Period Is Required' USING ERRCODE = '22023';
  END IF;

  SELECT club.id, club.owner_id, club.union_id
  INTO v_club
  FROM public.clubs club
  WHERE club.id = p_club_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Club Not Found' USING ERRCODE = 'P0002';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.club_members member
    WHERE member.club_id = p_club_id AND member.user_id = v_actor
  ) INTO v_is_member;
  SELECT EXISTS (
    SELECT 1 FROM public.profiles profile
    WHERE profile.id = v_actor AND profile.role IN ('admin', 'superadmin', 'god')
  ) INTO v_is_platform_admin;

  v_can_manage := v_is_platform_admin
    OR v_club.owner_id = v_actor
    OR EXISTS (
      SELECT 1 FROM public.club_members member
      WHERE member.club_id = p_club_id
        AND member.user_id = v_actor
        AND member.role IN ('owner', 'co_owner')
    )
    OR (
      v_club.union_id IS NOT NULL
      AND public.fn_union_can_manage_wallets(v_club.union_id, v_actor)
    );

  IF NOT v_is_member AND NOT v_can_manage THEN
    RAISE EXCEPTION 'Leaderboard Access Denied' USING ERRCODE = '42501';
  END IF;

  v_period_end := CASE p_period
    WHEN 'weekly' THEN p_period_start + 7
    ELSE (p_period_start + interval '1 month')::date
  END;
  IF (p_period = 'weekly' AND EXTRACT(DOW FROM p_period_start) <> 0)
     OR (p_period = 'monthly' AND EXTRACT(DAY FROM p_period_start) <> 1) THEN
    RAISE EXCEPTION 'A Canonical Weekly Or Monthly Period Is Required' USING ERRCODE = '22023';
  END IF;

  v_plan := public.fn_get_leaderboard_reward_plan(p_club_id, p_period, p_period_start);
  IF v_plan IS NOT NULL THEN
    SELECT COALESCE(sum((prize ->> 'amount')::numeric), 0)
    INTO v_planned_total
    FROM jsonb_array_elements(COALESCE(v_plan -> 'prizes', '[]'::jsonb)) prize;
  END IF;

  SELECT batch.* INTO v_batch
  FROM public.leaderboard_payout_batches batch
  WHERE batch.club_id = p_club_id
    AND batch.period = p_period
    AND batch.period_start = p_period_start;

  IF v_batch.id IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', payout.id,
      'batch_id', payout.batch_id,
      'user_id', payout.user_id,
      'rank', payout.rank,
      'payout_amount', payout.payout_amount,
      'payout_currency', payout.payout_currency,
      'awarded_at', payout.awarded_at
    ) ORDER BY payout.rank, payout.user_id), '[]'::jsonb)
    INTO v_receipts
    FROM public.leaderboard_payouts payout
    WHERE payout.batch_id = v_batch.id;
  END IF;

  SELECT failure.* INTO v_failure
  FROM public.leaderboard_payout_failures failure
  WHERE failure.club_id = p_club_id
    AND failure.period = p_period
    AND failure.period_start = p_period_start
    AND failure.resolved_at IS NULL;

  v_state := CASE
    WHEN v_batch.id IS NOT NULL THEN 'paid'
    WHEN v_plan IS NULL THEN 'not_published'
    WHEN NOT COALESCE((v_plan ->> 'rewards_enabled')::boolean, false) THEN 'disabled'
    WHEN v_period_end > (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')::date THEN 'open'
    WHEN v_failure.id IS NOT NULL THEN 'failed'
    ELSE 'pending'
  END;

  RETURN jsonb_build_object(
    'club_id', p_club_id,
    'period', p_period,
    'period_start', p_period_start,
    'period_end', v_period_end,
    'state', v_state,
    'can_manage', v_can_manage,
    'planned_total', round(v_planned_total, 2),
    'program', v_plan,
    'batch', CASE WHEN v_batch.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', v_batch.id,
      'program_id', v_batch.program_id,
      'program_version', v_batch.program_version,
      'program_hash', v_batch.program_hash,
      'metric', v_batch.metric,
      'funding_owner_type', v_batch.funding_owner_type,
      'funding_union_id', v_batch.funding_union_id,
      'total_paid', v_batch.total_paid,
      'seed_funded', v_batch.seed_funded,
      'promo_funded', v_batch.promo_funded,
      'winner_count', v_batch.winner_count,
      'tie_policy', v_batch.tie_policy,
      'settled_at', v_batch.settled_at
    ) END,
    'failure', CASE WHEN v_failure.id IS NULL THEN NULL ELSE jsonb_build_object(
      'error_code', v_failure.error_code,
      'attempt_count', v_failure.attempt_count,
      'first_failed_at', v_failure.first_failed_at,
      'last_failed_at', v_failure.failed_at,
      'automatic_retry', true,
      'owner_message', CASE WHEN v_can_manage THEN CASE v_failure.error_code
        WHEN 'promo_wallet_underfunded' THEN 'Add Promo Chips To Cover The Published Prize Pool. Automatic Retry Is Active.'
        WHEN 'promo_wallet_missing' THEN 'The Recorded Promo Wallet Could Not Be Found. Automatic Retry Is Active.'
        WHEN 'credit_conflict' THEN 'A Payout Receipt Conflict Needs Platform Review. No Duplicate Credit Was Issued.'
        ELSE 'Settlement Needs Platform Review. Automatic Retry Is Active.'
      END ELSE NULL END
    ) END,
    'receipts', v_receipts
  );
END;
$$;


ALTER FUNCTION public.fn_get_leaderboard_settlement_status(p_club_id uuid, p_period text, p_period_start date) OWNER TO postgres;

--
-- Name: FUNCTION fn_get_leaderboard_settlement_status(p_club_id uuid, p_period text, p_period_start date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_get_leaderboard_settlement_status(p_club_id uuid, p_period text, p_period_start date) IS 'Authenticated canonical-period settlement read model. Members see program, state, and receipts; funding owners also receive safe recovery guidance. Moves no chips.';


--
-- Name: fn_get_managed_game_command_receipt(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_managed_game_command_receipt(p_command_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.managed_game_command_receipts%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  SELECT * INTO v_row
    FROM public.managed_game_command_receipts
   WHERE command_id = p_command_id AND actor_id = v_uid;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'found', false);
  END IF;
  RETURN jsonb_build_object(
    'ok', true,
    'found', true,
    'receipt', v_row.result || jsonb_build_object(
      'command_id', v_row.command_id,
      'command_status', v_row.status,
      'created_at', v_row.created_at,
      'completed_at', v_row.completed_at
    )
  );
END;
$$;


ALTER FUNCTION public.fn_get_managed_game_command_receipt(p_command_id uuid) OWNER TO postgres;

--
-- Name: fn_get_managed_game_command_receipts(text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_managed_game_command_receipts(p_kind text, p_game_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_rows jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_kind NOT IN ('table', 'tournament') OR cardinality(p_game_ids) > 500 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request');
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT DISTINCT ON (r.game_id)
             r.game_id, r.command_id, r.command_action, r.status,
             r.contract_version_before, r.contract_version_after,
             CASE
               WHEN r.status = 'processing' THEN 'processing'
               WHEN av.version IS NULL THEN 'version_drift'
               ELSE 'confirmed'
             END AS reconciliation_state,
             r.created_at, r.completed_at
        FROM public.managed_game_command_receipts r
        JOIN public.managed_game_contract_versions v
          ON v.game_kind = r.game_kind
         AND v.game_id = r.game_id
         AND v.version = r.contract_version_before
        LEFT JOIN public.managed_game_contract_versions av
          ON av.game_kind = r.game_kind
         AND av.game_id = r.game_id
         AND av.version = r.contract_version_after
       WHERE r.game_kind = p_kind
         AND r.game_id = ANY(COALESCE(p_game_ids, '{}'::uuid[]))
         AND public.fn_can_create_games(v.club_id, v_uid)
       ORDER BY r.game_id, r.created_at DESC
    ) x;

  RETURN jsonb_build_object('ok', true, 'receipts', v_rows);
END;
$$;


ALTER FUNCTION public.fn_get_managed_game_command_receipts(p_kind text, p_game_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_get_managed_game_contract_history(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_managed_game_contract_history(p_kind text, p_game_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_club uuid;
  v_rows jsonb;
BEGIN
  IF p_kind = 'table' THEN
    SELECT club_id INTO v_club FROM public.tables WHERE id = p_game_id;
  ELSIF p_kind = 'tournament' THEN
    SELECT club_id INTO v_club FROM public.tournaments WHERE id = p_game_id;
  ELSE
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_game_kind');
  END IF;

  IF v_uid IS NULL OR v_club IS NULL OR NOT public.fn_can_create_games(v_club, v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(v) ORDER BY v.version DESC), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT version, contract_hash, contract, published_at, published_by, change_reason
        FROM public.managed_game_contract_versions
       WHERE game_kind = p_kind AND game_id = p_game_id
       ORDER BY version DESC
       LIMIT 50
    ) v;

  RETURN jsonb_build_object('ok', true, 'versions', v_rows);
END;
$$;


ALTER FUNCTION public.fn_get_managed_game_contract_history(p_kind text, p_game_id uuid) OWNER TO postgres;

--
-- Name: fn_get_managed_game_contracts(text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_managed_game_contracts(p_kind text, p_game_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
  v_club uuid;
  v_version record;
  v_locked boolean;
  v_readiness jsonb;
  v_result jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_kind NOT IN ('table', 'tournament') OR cardinality(p_game_ids) > 500 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request');
  END IF;

  FOREACH v_id IN ARRAY COALESCE(p_game_ids, '{}'::uuid[]) LOOP
    v_club := NULL;
    IF p_kind = 'table' THEN
      SELECT club_id INTO v_club FROM public.tables WHERE id = v_id;
      v_locked := EXISTS (
        SELECT 1 FROM public.table_seats ts WHERE ts.table_id = v_id AND ts.left_at IS NULL
      );
      v_readiness := jsonb_build_object(
        'state', 'ready', 'can_start', true, 'contract_locked', v_locked
      );
    ELSE
      SELECT club_id INTO v_club FROM public.tournaments WHERE id = v_id;
      v_readiness := public.fn_tournament_management_readiness(v_id);
      v_locked := COALESCE((v_readiness ->> 'contract_locked')::boolean, false);
    END IF;

    IF v_club IS NULL OR NOT public.fn_can_create_games(v_club, v_uid) THEN
      CONTINUE;
    END IF;

    SELECT version, contract_hash, published_at, published_by, change_reason
      INTO v_version
      FROM public.managed_game_contract_versions
     WHERE game_kind = p_kind AND game_id = v_id
     ORDER BY version DESC
     LIMIT 1;

    IF FOUND THEN
      v_result := v_result || jsonb_build_array(jsonb_build_object(
        'game_id', v_id,
        'version', v_version.version,
        'contract_hash', v_version.contract_hash,
        'published_at', v_version.published_at,
        'published_by', v_version.published_by,
        'change_reason', v_version.change_reason,
        'contract_locked', v_locked,
        'readiness', v_readiness
      ));
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'contracts', v_result);
END;
$$;


ALTER FUNCTION public.fn_get_managed_game_contracts(p_kind text, p_game_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_get_my_guest_invite_code(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_my_guest_invite_code(p_stream_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT s.guest_invite_code
    FROM public.live_streams s
   WHERE s.id = p_stream_id
     AND s.broadcaster_id = auth.uid()
   LIMIT 1;
$$;


ALTER FUNCTION public.fn_get_my_guest_invite_code(p_stream_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_get_my_guest_invite_code(p_stream_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_get_my_guest_invite_code(p_stream_id uuid) IS 'Returns guest_invite_code only when auth.uid() owns the stream. Used by the broadcaster client to obtain their own code for sharing with co-hosts. Defends against the cross-viewer code leak (GUEST-1) by routing through a SECURITY DEFINER scoped RPC instead of a direct column SELECT.';


--
-- Name: fn_get_or_create_conversation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_or_create_conversation(p_user_id uuid, p_other_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_existing_id uuid;
    v_new_id uuid;
BEGIN
    IF p_user_id IS NULL OR p_other_user_id IS NULL OR p_user_id = p_other_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid user pair');
    END IF;

    IF COALESCE(auth.role(), '') <> 'service_role'
       AND (auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_user_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not authorized');
    END IF;

    SELECT c.id INTO v_existing_id
      FROM social_conversations c
      JOIN social_conversation_participants p1
        ON p1.conversation_id = c.id AND p1.user_id = p_user_id
      JOIN social_conversation_participants p2
        ON p2.conversation_id = c.id AND p2.user_id = p_other_user_id
     WHERE c.is_group = false
       AND p1.context_entity_id IS NOT DISTINCT FROM NULL
     LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'conversation_id', v_existing_id, 'created', false);
    END IF;

    INSERT INTO social_conversations (is_group) VALUES (false) RETURNING id INTO v_new_id;
    INSERT INTO social_conversation_participants (conversation_id, user_id)
    VALUES (v_new_id, p_user_id), (v_new_id, p_other_user_id);

    RETURN jsonb_build_object('success', true, 'conversation_id', v_new_id, 'created', true);
END;
$$;


ALTER FUNCTION public.fn_get_or_create_conversation(p_user_id uuid, p_other_user_id uuid) OWNER TO postgres;

--
-- Name: fn_get_or_create_conversation(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_or_create_conversation(p_user_id uuid, p_other_user_id uuid, p_context_entity_id uuid, p_context_entity_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_existing_id uuid;
    v_new_id uuid;
BEGIN
    IF p_user_id IS NULL OR p_other_user_id IS NULL OR p_user_id = p_other_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid user pair');
    END IF;

    -- IDOR guard (2026-08-15) + service_role allowance: a JWT caller may only
    -- act as themselves; service_role has already authenticated upstream.
    IF COALESCE(auth.role(), '') <> 'service_role'
       AND (auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_user_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not authorized');
    END IF;

    SELECT c.id INTO v_existing_id
      FROM social_conversations c
      JOIN social_conversation_participants p1
        ON p1.conversation_id = c.id AND p1.user_id = p_user_id
      JOIN social_conversation_participants p2
        ON p2.conversation_id = c.id AND p2.user_id = p_other_user_id
     WHERE c.is_group = false
       AND p1.context_entity_id IS NOT DISTINCT FROM p_context_entity_id
     LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'conversation_id', v_existing_id, 'created', false);
    END IF;

    INSERT INTO social_conversations (is_group, context_entity_id, context_entity_type)
    VALUES (false, p_context_entity_id, p_context_entity_type)
    RETURNING id INTO v_new_id;

    INSERT INTO social_conversation_participants
        (conversation_id, user_id, context_entity_id, context_entity_type)
    VALUES
        (v_new_id, p_user_id, p_context_entity_id, p_context_entity_type),
        (v_new_id, p_other_user_id, NULL, NULL);

    RETURN jsonb_build_object('success', true, 'conversation_id', v_new_id, 'created', true);
END;
$$;


ALTER FUNCTION public.fn_get_or_create_conversation(p_user_id uuid, p_other_user_id uuid, p_context_entity_id uuid, p_context_entity_type text) OWNER TO postgres;

