--
-- Name: fn_get_reactions_for_messages(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_reactions_for_messages(p_message_ids uuid[]) RETURNS TABLE(message_id uuid, reaction text, user_id uuid, username text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT r.message_id, r.reaction, r.user_id,
         COALESCE(pr.display_name, pr.username) AS username
    FROM message_reactions r
    LEFT JOIN profiles pr ON pr.id = r.user_id
   WHERE r.message_id = ANY(p_message_ids)
     AND EXISTS (
       SELECT 1
         FROM social_messages m
         JOIN social_conversation_participants p
           ON p.conversation_id = m.conversation_id
        WHERE m.id = r.message_id
          AND (COALESCE(auth.role(), '') = 'service_role'
               OR p.user_id = auth.uid())
     )
   ORDER BY r.created_at;
$$;


