--
-- Name: fn_get_social_feed(uuid, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_social_feed(p_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_filter text DEFAULT 'recent'::text) RETURNS TABLE(post_id uuid, author_id uuid, author_username text, author_avatar text, author_level integer, content text, content_type text, media_urls text[], like_count integer, comment_count integer, share_count integer, is_liked boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        sp.id AS post_id,
        sp.author_id,
        COALESCE(p.username, 'Anonymous')::text AS author_username,
        p.avatar_url::text AS author_avatar,
        COALESCE(p.level, 1)::int AS author_level,
        sp.content,
        COALESCE(sp.content_type, 'text')::text AS content_type,
        -- BUG-17b: jsonb → text[] conversion. Defensive for non-array values.
        CASE
          WHEN sp.media_urls IS NULL                     THEN ARRAY[]::text[]
          WHEN jsonb_typeof(sp.media_urls) = 'array'     THEN
            ARRAY(SELECT jsonb_array_elements_text(sp.media_urls))
          ELSE ARRAY[]::text[]
        END AS media_urls,
        COALESCE(sp.like_count, 0)::int AS like_count,
        COALESCE(sp.comment_count, 0)::int AS comment_count,
        COALESCE(sp.share_count, 0)::int AS share_count,
        CASE
            WHEN p_user_id IS NOT NULL THEN
                EXISTS(
                    SELECT 1 FROM social_interactions si
                     WHERE si.post_id = sp.id
                       AND si.user_id = p_user_id
                       AND si.interaction_type = 'like'
                )
            ELSE FALSE
        END AS is_liked,
        sp.created_at
    FROM social_posts sp
    LEFT JOIN profiles p ON p.id = sp.author_id
    WHERE (sp.visibility = 'public' OR sp.visibility IS NULL)
    ORDER BY sp.created_at DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.fn_get_social_feed(p_user_id uuid, p_limit integer, p_offset integer, p_filter text) OWNER TO postgres;

