--
-- Name: fn_get_stories(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_stories(p_viewer_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      s.id,
      s.author_id,
      s.content,
      s.media_url,
      s.media_type,
      s.background_color,
      s.link_url,
      s.created_at,
      s.expires_at,
      s.view_count,
      p.username AS author_username,
      COALESCE(p.full_name, p.username) AS author_fullname,
      p.avatar_url AS author_avatar,
      (s.author_id = p_viewer_id) AS is_own,
      EXISTS (
        SELECT 1 FROM social_story_views sv
        WHERE sv.story_id = s.id AND sv.viewer_id = p_viewer_id
      ) AS is_viewed
    FROM social_stories s
    JOIN profiles p ON p.id = s.author_id
    WHERE
      s.expires_at > now()
      AND (
        -- Own stories
        s.author_id = p_viewer_id

        -- Stories from users the viewer follows
        -- FIX: was 'social_followers' (nonexistent) - correct table is 'social_follows'
        -- FIX: was 'followed_id' - correct column is 'following_id'
        OR EXISTS (
          SELECT 1 FROM social_follows sf
          WHERE sf.follower_id = p_viewer_id AND sf.following_id = s.author_id
        )

        -- Stories from accepted friends (horses use friendships, not social_follows)
        OR EXISTS (
          SELECT 1 FROM friendships f
          WHERE f.status = 'accepted'
            AND (
              (f.user_id = p_viewer_id AND f.friend_id = s.author_id)
              OR (f.friend_id = p_viewer_id AND f.user_id = s.author_id)
            )
        )
      )
    ORDER BY s.created_at DESC
    LIMIT 100
  ) t;

  RETURN COALESCE(v_result, '[]'::jsonb);

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_get_stories error: %', SQLERRM;
  RETURN '[]'::jsonb;
END;
$$;


ALTER FUNCTION public.fn_get_stories(p_viewer_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_get_stories(p_viewer_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_get_stories(p_viewer_id uuid) IS 'Get stories for a viewer — own + social_follows (fixed) + accepted friends. (2026-04-28 bugfix: wrong table name social_followers→social_follows).';


