--
-- Name: fn_get_user_conversations(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_user_conversations(p_user_id uuid, p_context_entity_id uuid DEFAULT NULL::uuid) RETURNS TABLE(conversation_id uuid, title text, is_group boolean, last_message_at timestamp with time zone, unread_count bigint, other_user_id uuid, other_user_username text, other_user_avatar text, context_entity_id uuid, context_entity_type text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Defence in depth. A caller presenting an end-user JWT may only ask for
    -- their own conversations. A caller with no JWT at all is the API route
    -- holding the service-role key, which has already verified identity from
    -- the bearer token before it gets here.
    IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( auth.uid() IS DISTINCT FROM p_user_id)) THEN
        RAISE EXCEPTION 'fn_get_user_conversations: not authorized to read another user''s inbox';
    END IF;

    RETURN QUERY
    SELECT
        c.id AS conversation_id,
        COALESCE(c.group_name, NULL) AS title,
        c.is_group,
        c.last_message_at,
        (
            SELECT COUNT(*)
              FROM social_messages m
             WHERE m.conversation_id = c.id
               AND m.sender_id != p_user_id
               AND COALESCE(m.is_deleted, false) = false
               AND (p.last_read_at IS NULL OR m.created_at > p.last_read_at)
        ) AS unread_count,
        ou.id AS other_user_id,
        COALESCE(ou.display_name, ou.username, ou.full_name) AS other_user_username,
        ou.avatar_url AS other_user_avatar,
        p.context_entity_id,
        p.context_entity_type
    FROM social_conversations c
    JOIN social_conversation_participants p
      ON p.conversation_id = c.id AND p.user_id = p_user_id
    LEFT JOIN social_conversation_participants op
      ON op.conversation_id = c.id AND op.user_id <> p_user_id
    LEFT JOIN profiles ou ON ou.id = op.user_id
    WHERE p.context_entity_id IS NOT DISTINCT FROM p_context_entity_id
    ORDER BY c.last_message_at DESC NULLS LAST;
END;
$$;


ALTER FUNCTION public.fn_get_user_conversations(p_user_id uuid, p_context_entity_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_get_user_conversations(p_user_id uuid, p_context_entity_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_get_user_conversations(p_user_id uuid, p_context_entity_id uuid) IS 'Service-role only. Reads a user inbox by parameter, so EXECUTE must never be granted to anon or authenticated - see 20260819_lock_down_fn_get_user_conversations.sql. The auth.uid() guard in the body is a backstop, not the gate.';


--
-- Name: fn_get_vip_subscription(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_vip_subscription(p_user_id uuid) RETURNS TABLE(tier text, expires_at timestamp with time zone, days_remaining integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    vs.tier,
    vs.current_period_end AS expires_at,
    EXTRACT(DAY FROM (vs.current_period_end - NOW()))::int AS days_remaining
  FROM vip_subscriptions vs
  WHERE vs.user_id = p_user_id
    AND vs.status IN ('active','trialing')
    AND vs.current_period_end > NOW()
  ORDER BY
    CASE vs.tier WHEN 'gold' THEN 3 WHEN 'silver' THEN 2 ELSE 1 END DESC,
    vs.current_period_end DESC
  LIMIT 1;
END;
$$;


ALTER FUNCTION public.fn_get_vip_subscription(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_global_leaderboard_by_dates(text, date, date, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_global_leaderboard_by_dates(p_metric text DEFAULT 'profit'::text, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid, hands_played numeric, total_winnings numeric, total_losses numeric, tournaments_won numeric, total_rake numeric, sum_big_blind numeric, rank_change integer, qualified boolean, rank integer, total_ranked integer, baseline_date date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_today date := (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')::date;
  v_start date := COALESCE(p_start_date, v_today - 7);
  v_end date := COALESCE(p_end_date, v_today);
  v_span integer;
  v_baseline date;
  v_end_snap date;
  v_prev_start date;
  v_use_live boolean;
  v_min_hands integer := 20;
BEGIN
  IF v_end < v_start THEN
    RAISE EXCEPTION 'end date % precedes start date %', v_end, v_start
      USING ERRCODE = '22023';
  END IF;
  v_span := GREATEST(v_end - v_start, 1);

  SELECT max(snapshot_date) INTO v_baseline
    FROM public.player_stats_snapshots
   WHERE snapshot_date <= v_start;

  v_use_live := (v_end > v_today);
  IF NOT v_use_live THEN
    SELECT max(snapshot_date) INTO v_end_snap
      FROM public.player_stats_snapshots
     WHERE snapshot_date <= v_end;
    IF v_end_snap IS NULL OR (v_baseline IS NOT NULL AND v_end_snap <= v_baseline) THEN
      RETURN;
    END IF;
  END IF;

  SELECT max(snapshot_date) INTO v_prev_start
    FROM public.player_stats_snapshots
   WHERE snapshot_date <= v_start - v_span;

  RETURN QUERY
  WITH end_s AS (
    SELECT ps.user_id AS uid, SUM(ps.hands_dealt)::numeric AS h,
           SUM(ps.total_winnings) AS w, SUM(ps.total_losses) AS l,
           SUM(ps.tournaments_won)::numeric AS t, SUM(ps.total_rake) AS rk,
           SUM(ps.sum_big_blind) AS bb
      FROM public.player_stats ps
     WHERE v_use_live
     GROUP BY ps.user_id
    UNION ALL
    SELECT s.user_id, SUM(s.hands_dealt)::numeric, SUM(s.total_winnings),
           SUM(s.total_losses), SUM(s.tournaments_won)::numeric,
           SUM(s.total_rake), SUM(s.sum_big_blind)
      FROM public.player_stats_snapshots s
     WHERE NOT v_use_live AND s.snapshot_date = v_end_snap
     GROUP BY s.user_id
  ),
  base_s AS (
    SELECT s.user_id AS uid, SUM(s.hands_dealt)::numeric AS h,
           SUM(s.total_winnings) AS w, SUM(s.total_losses) AS l,
           SUM(s.tournaments_won)::numeric AS t, SUM(s.total_rake) AS rk,
           SUM(s.sum_big_blind) AS bb
      FROM public.player_stats_snapshots s
     WHERE v_baseline IS NOT NULL AND s.snapshot_date = v_baseline
     GROUP BY s.user_id
  ),
  prev_s AS (
    SELECT s.user_id AS uid, SUM(s.hands_dealt)::numeric AS h,
           SUM(s.total_winnings) AS w, SUM(s.total_losses) AS l,
           SUM(s.tournaments_won)::numeric AS t, SUM(s.sum_big_blind) AS bb
      FROM public.player_stats_snapshots s
     WHERE v_prev_start IS NOT NULL AND s.snapshot_date = v_prev_start
     GROUP BY s.user_id
  ),
  cur AS (
    SELECT e.uid,
           GREATEST(e.h - COALESCE(b.h, 0), 0) AS d_hands,
           e.w - COALESCE(b.w, 0) AS d_win,
           e.l - COALESCE(b.l, 0) AS d_loss,
           GREATEST(e.t - COALESCE(b.t, 0), 0) AS d_twon,
           GREATEST(e.rk - COALESCE(b.rk, 0), 0) AS d_rake,
           GREATEST(e.bb - COALESCE(b.bb, 0), 0) AS d_bb,
           CASE WHEN b.uid IS NULL THEN NULL ELSE GREATEST(b.h - COALESCE(p.h, 0), 0) END AS p_hands,
           CASE WHEN b.uid IS NULL THEN NULL ELSE b.w - COALESCE(p.w, 0) END AS p_win,
           CASE WHEN b.uid IS NULL THEN NULL ELSE b.l - COALESCE(p.l, 0) END AS p_loss,
           CASE WHEN b.uid IS NULL THEN NULL ELSE GREATEST(b.t - COALESCE(p.t, 0), 0) END AS p_twon,
           CASE WHEN b.uid IS NULL THEN NULL ELSE GREATEST(b.bb - COALESCE(p.bb, 0), 0) END AS p_bb
      FROM end_s e
      LEFT JOIN base_s b ON b.uid = e.uid
      LEFT JOIN prev_s p ON p.uid = e.uid
  ),
  scored AS (
    SELECT c.*,
           CASE p_metric
             WHEN 'hands_played' THEN c.d_hands
             WHEN 'tournaments_won' THEN c.d_twon
             WHEN 'roi' THEN CASE WHEN c.d_loss > 0 AND c.d_hands >= v_min_hands
                                  THEN (c.d_win-c.d_loss)/c.d_loss END
             WHEN 'bb100' THEN CASE WHEN c.d_bb > 0 AND c.d_hands >= v_min_hands
                                    THEN 100*(c.d_win-c.d_loss)/c.d_bb END
             ELSE c.d_win-c.d_loss
           END AS score,
           CASE p_metric
             WHEN 'hands_played' THEN c.p_hands
             WHEN 'tournaments_won' THEN c.p_twon
             WHEN 'roi' THEN CASE WHEN c.p_loss > 0 AND c.p_hands >= v_min_hands
                                  THEN (c.p_win-c.p_loss)/c.p_loss END
             WHEN 'bb100' THEN CASE WHEN c.p_bb > 0 AND c.p_hands >= v_min_hands
                                    THEN 100*(c.p_win-c.p_loss)/c.p_bb END
             ELSE c.p_win-c.p_loss
           END AS prev_score
      FROM cur c
  ),
  ranked AS (
    SELECT s.*,
           row_number() OVER (ORDER BY s.score DESC NULLS LAST, s.uid) AS rn_now,
           rank() OVER (ORDER BY s.score DESC NULLS LAST) AS rk_now,
           count(*) OVER () AS total_active,
           CASE WHEN s.prev_score IS NULL THEN NULL
                ELSE rank() OVER (ORDER BY s.prev_score DESC NULLS LAST) END AS rk_old
      FROM scored s
     WHERE (s.d_hands > 0 OR s.d_twon > 0 OR s.d_win <> 0 OR s.d_loss <> 0)
  )
  SELECT r.uid, r.d_hands, r.d_win, r.d_loss, r.d_twon, r.d_rake, r.d_bb,
         COALESCE((r.rk_old - r.rk_now)::integer, 0),
         (p_metric NOT IN ('roi','bb100') OR
          (r.d_hands >= v_min_hands AND
           (CASE WHEN p_metric='roi' THEN r.d_loss ELSE r.d_bb END) > 0)),
         r.rk_now::integer, r.total_active::integer, v_baseline
    FROM ranked r
   ORDER BY r.rn_now
   LIMIT p_limit OFFSET GREATEST(COALESCE(p_offset,0),0);
END;
$$;


ALTER FUNCTION public.fn_global_leaderboard_by_dates(p_metric text, p_start_date date, p_end_date date, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_global_leaderboard_period(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_global_leaderboard_period(p_metric text DEFAULT 'profit'::text, p_period text DEFAULT 'weekly'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid, hands_played numeric, total_winnings numeric, total_losses numeric, tournaments_won numeric, total_rake numeric, sum_big_blind numeric, rank_change integer, qualified boolean, rank integer, total_ranked integer, baseline_date date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_period_start date;
  v_baseline date;
  v_prev_end date;
  v_min_hands integer := 20;
  v_is_all_time boolean := p_period = 'all_time';
BEGIN
  SELECT bounds.start_date INTO v_period_start
    FROM public.fn_leaderboard_period_window(p_period, 0) bounds;

  IF NOT v_is_all_time THEN
    SELECT max(snapshot_date) INTO v_baseline
      FROM public.player_stats_snapshots WHERE snapshot_date <= v_period_start;
    IF v_baseline IS NULL THEN
      SELECT min(snapshot_date) INTO v_baseline FROM public.player_stats_snapshots;
    END IF;
  END IF;
  SELECT max(snapshot_date) INTO v_prev_end
    FROM public.player_stats_snapshots
   WHERE snapshot_date <= (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')::date - 1;
  RETURN QUERY
  WITH cur_ps AS (
    SELECT ps.user_id AS uid, SUM(ps.hands_dealt)::numeric AS s_hands,
           SUM(ps.total_winnings) AS s_win, SUM(ps.total_losses) AS s_loss,
           SUM(ps.tournaments_won)::numeric AS s_twon, SUM(ps.total_rake) AS s_rake,
           SUM(ps.sum_big_blind) AS s_bb
      FROM public.player_stats ps GROUP BY ps.user_id
  ),
  snap AS (
    SELECT s.user_id AS uid, s.snapshot_date AS d, SUM(s.hands_dealt)::numeric AS s_hands,
           SUM(s.total_winnings) AS s_win, SUM(s.total_losses) AS s_loss,
           SUM(s.tournaments_won)::numeric AS s_twon, SUM(s.total_rake) AS s_rake,
           SUM(s.sum_big_blind) AS s_bb
      FROM public.player_stats_snapshots s
     WHERE s.snapshot_date IN (v_baseline, v_prev_end)
     GROUP BY s.user_id, s.snapshot_date
  ),
  cur AS (
    SELECT c.uid,
           (CASE WHEN v_is_all_time THEN c.s_hands ELSE GREATEST(c.s_hands-COALESCE(b.s_hands,0),0) END) AS d_hands,
           (CASE WHEN v_is_all_time THEN c.s_win ELSE c.s_win-COALESCE(b.s_win,0) END) AS d_win,
           (CASE WHEN v_is_all_time THEN c.s_loss ELSE c.s_loss-COALESCE(b.s_loss,0) END) AS d_loss,
           (CASE WHEN v_is_all_time THEN c.s_twon ELSE GREATEST(c.s_twon-COALESCE(b.s_twon,0),0) END) AS d_twon,
           (CASE WHEN v_is_all_time THEN c.s_rake ELSE GREATEST(c.s_rake-COALESCE(b.s_rake,0),0) END) AS d_rake,
           (CASE WHEN v_is_all_time THEN c.s_bb ELSE GREATEST(c.s_bb-COALESCE(b.s_bb,0),0) END) AS d_bb,
           (CASE WHEN pe.uid IS NULL OR (NOT v_is_all_time AND v_prev_end<=v_baseline) THEN NULL ELSE GREATEST(pe.s_hands-COALESCE(b.s_hands,0),0) END) AS p_hands,
           (CASE WHEN pe.uid IS NULL OR (NOT v_is_all_time AND v_prev_end<=v_baseline) THEN NULL ELSE pe.s_win-COALESCE(b.s_win,0) END) AS p_win,
           (CASE WHEN pe.uid IS NULL OR (NOT v_is_all_time AND v_prev_end<=v_baseline) THEN NULL ELSE pe.s_loss-COALESCE(b.s_loss,0) END) AS p_loss,
           (CASE WHEN pe.uid IS NULL OR (NOT v_is_all_time AND v_prev_end<=v_baseline) THEN NULL ELSE GREATEST(pe.s_twon-COALESCE(b.s_twon,0),0) END) AS p_twon,
           (CASE WHEN pe.uid IS NULL OR (NOT v_is_all_time AND v_prev_end<=v_baseline) THEN NULL ELSE GREATEST(pe.s_bb-COALESCE(b.s_bb,0),0) END) AS p_bb
      FROM cur_ps c
      LEFT JOIN snap b ON NOT v_is_all_time AND b.uid=c.uid AND b.d=v_baseline
      LEFT JOIN snap pe ON pe.uid=c.uid AND pe.d=v_prev_end
  ),
  scored AS (
    SELECT c.*,
           (CASE p_metric
              WHEN 'hands_played' THEN c.d_hands
              WHEN 'tournaments_won' THEN c.d_twon
              WHEN 'roi' THEN CASE WHEN c.d_loss>0 AND c.d_hands>=v_min_hands THEN (c.d_win-c.d_loss)/c.d_loss END
              WHEN 'bb100' THEN CASE WHEN c.d_bb>0 AND c.d_hands>=v_min_hands THEN 100*(c.d_win-c.d_loss)/c.d_bb END
              ELSE c.d_win-c.d_loss END) AS score,
           (CASE p_metric
              WHEN 'hands_played' THEN c.p_hands
              WHEN 'tournaments_won' THEN c.p_twon
              WHEN 'roi' THEN CASE WHEN c.p_loss>0 AND c.p_hands>=v_min_hands THEN (c.p_win-c.p_loss)/c.p_loss END
              WHEN 'bb100' THEN CASE WHEN c.p_bb>0 AND c.p_hands>=v_min_hands THEN 100*(c.p_win-c.p_loss)/c.p_bb END
              ELSE c.p_win-c.p_loss END) AS prev_score
      FROM cur c
  ),
  ranked AS (
    SELECT s.*,
           row_number() OVER (ORDER BY s.score DESC NULLS LAST, s.uid) AS rn_now,
           rank() OVER (ORDER BY s.score DESC NULLS LAST) AS rk_now,
           count(*) OVER () AS total_active,
           CASE WHEN s.prev_score IS NULL THEN NULL
                ELSE rank() OVER (ORDER BY s.prev_score DESC NULLS LAST) END AS rk_old
      FROM scored s
     WHERE (s.d_hands > 0 OR s.d_twon > 0 OR s.d_win <> 0 OR s.d_loss <> 0)
  )
  SELECT r.uid, r.d_hands, r.d_win, r.d_loss, r.d_twon, r.d_rake, r.d_bb,
         COALESCE((r.rk_old-r.rk_now)::integer,0),
         (p_metric NOT IN ('roi','bb100') OR
          (r.d_hands>=v_min_hands AND (CASE WHEN p_metric='roi' THEN r.d_loss ELSE r.d_bb END)>0)),
         r.rk_now::integer, r.total_active::integer, v_baseline
    FROM ranked r
   ORDER BY r.rn_now
   LIMIT p_limit OFFSET GREATEST(COALESCE(p_offset,0),0);
END;
$$;


