COMMENT ON FUNCTION public.fn_grant_guard_health() IS 'Single health call for the privileged-grant guard. Every row status=OK means the guard is intact.';


--
-- Name: fn_gto_board_flush_suit(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_gto_board_flush_suit(p_board text) RETURNS smallint
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public'
    AS $$
  with chars as (
    select case substr(lower(p_board), g * 2, 1)
             when 'c' then 0 when 'd' then 1 when 'h' then 2 when 's' then 3
             else null end as suit
    from generate_series(1, coalesce(length(p_board), 0) / 2) g
  ),
  tally as (
    select suit, count(*) as n from chars where suit is not null group by suit
  )
  select coalesce((
    select suit::smallint from tally where n >= 2 order by n desc, suit asc limit 1
  ), (-1)::smallint);
$$;


ALTER FUNCTION public.fn_gto_board_flush_suit(p_board text) OWNER TO postgres;

--
-- Name: FUNCTION fn_gto_board_flush_suit(p_board text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_gto_board_flush_suit(p_board text) IS 'Suit index (c,d,h,s = 0..3) most present on the board, -1 if no suit appears twice, NULL if the board is NULL. The V31 suit bucket counts how many of these a combo holds.';


--
-- Name: fn_gto_texture_class(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_gto_texture_class(p_board text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_ranks integer[] := '{}';
  v_suits text[] := '{}';
  v_ch text; v_r integer; v_i integer;
  v_hi integer; v_high text; v_suitkind text; v_paired boolean;
  v_conn boolean := false;
  v_distinct integer[];
  v_span integer;
begin
  if p_board is null or length(p_board) < 6 then return null; end if;
  for v_i in 0..2 loop
    v_ch := substr(p_board, v_i * 2 + 1, 1);
    v_r := case v_ch
      when 'A' then 14 when 'K' then 13 when 'Q' then 12 when 'J' then 11
      when 'T' then 10 else nullif(v_ch, '')::integer end;
    if v_r is null then return null; end if;
    v_ranks := v_ranks || v_r;
    v_suits := v_suits || substr(p_board, v_i * 2 + 2, 1);
  end loop;

  v_hi := greatest(v_ranks[1], v_ranks[2], v_ranks[3]);
  v_high := case
    when v_hi = 14 then 'A'
    when v_hi >= 12 then 'B'
    when v_hi >= 9  then 'M'
    else 'L' end;

  v_suitkind := case
    when v_suits[1] = v_suits[2] and v_suits[2] = v_suits[3] then 'm'
    when v_suits[1] = v_suits[2] or v_suits[2] = v_suits[3] or v_suits[1] = v_suits[3] then 't'
    else 'r' end;

  v_paired := v_ranks[1] = v_ranks[2] or v_ranks[2] = v_ranks[3] or v_ranks[1] = v_ranks[3];

  select array_agg(distinct r order by r) into v_distinct from unnest(v_ranks) r;
  if array_length(v_distinct, 1) >= 2 then
    v_span := v_distinct[array_length(v_distinct, 1)] - v_distinct[1];
    if v_span <= 4 then v_conn := true; end if;
    if not v_conn and v_distinct[array_length(v_distinct, 1)] = 14 then
      if (v_distinct[array_length(v_distinct, 1) - 1] <= 5) then v_conn := true; end if;
    end if;
  end if;

  return v_high || v_suitkind || case when v_paired then 'p' else 'u' end
         || case when v_conn then 'c' else 'd' end;
end;
$$;


ALTER FUNCTION public.fn_gto_texture_class(p_board text) OWNER TO postgres;

--
-- Name: FUNCTION fn_gto_texture_class(p_board text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_gto_texture_class(p_board text) IS 'V29 flop texture class: high card (A/B/M/L) + suits (m/t/r) + paired (p/u) + connectivity (c/d). MIRRORED in server/src/engine/GtoPostflop.ts textureClass() - the two must classify identically or live lookups land in the wrong cell.';


--
-- Name: fn_gto_texture_class_any(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_gto_texture_class_any(p_board text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_n integer;
  v_ranks integer[] := '{}';
  v_suits text[] := '{}';
  v_ch text; v_r integer; v_i integer;
  v_hi integer := 0; v_high text; v_suitkind text; v_paired boolean := false;
  v_conn boolean := false;
  v_maxsuit integer := 0;
  v_cnt integer;
  v_distinct integer[];
  v_win integer;
begin
  if p_board is null then return null; end if;
  v_n := length(p_board) / 2;
  if v_n < 3 or length(p_board) % 2 <> 0 then return null; end if;
  if v_n = 3 then
    return public.fn_gto_texture_class(p_board);
  end if;
  if v_n > 5 then return null; end if;

  for v_i in 0..(v_n - 1) loop
    v_ch := substr(p_board, v_i * 2 + 1, 1);
    v_r := case v_ch
      when 'A' then 14 when 'K' then 13 when 'Q' then 12 when 'J' then 11
      when 'T' then 10 else nullif(v_ch, '')::integer end;
    if v_r is null then return null; end if;
    v_ranks := v_ranks || v_r;
    v_suits := v_suits || substr(p_board, v_i * 2 + 2, 1);
    if v_r > v_hi then v_hi := v_r; end if;
  end loop;

  v_high := case
    when v_hi = 14 then 'A'
    when v_hi >= 12 then 'B'
    when v_hi >= 9  then 'M'
    else 'L' end;

  select max(c) into v_maxsuit from (
    select count(*) c from unnest(v_suits) s group by s
  ) x;
  v_suitkind := case when v_maxsuit >= 4 then 'm' when v_maxsuit = 3 then 't' else 'r' end;

  select count(*) into v_cnt from (
    select 1 from unnest(v_ranks) r group by r having count(*) >= 2
  ) p;
  v_paired := v_cnt > 0;

  select array_agg(distinct r order by r) into v_distinct from unnest(v_ranks) r;
  for v_win in reverse 14..6 loop
    if (select count(*) from unnest(v_distinct) r
        where r <= v_win and r > v_win - 5
           or (v_win = 5 and r = 14)) >= 3 then
      v_conn := true;
      exit;
    end if;
  end loop;
  if not v_conn then
    if (select count(*) from unnest(v_distinct) r where r <= 5 or r = 14) >= 3 then
      v_conn := true;
    end if;
  end if;

  return v_high || v_suitkind || case when v_paired then 'p' else 'u' end
         || case when v_conn then 'c' else 'd' end;
end;
$$;


ALTER FUNCTION public.fn_gto_texture_class_any(p_board text) OWNER TO postgres;

--
-- Name: FUNCTION fn_gto_texture_class_any(p_board text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_gto_texture_class_any(p_board text) IS 'V30 texture class for 3/4/5-card boards. Three cards delegate to the shipped V29 flop classifier unchanged. MIRRORED by textureClass() in engine/GtoPostflop.ts; shared-example pins guard the contract.';


--
-- Name: fn_guard_club_lifecycle_write(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_guard_club_lifecycle_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_retirement_write boolean :=
    coalesce(current_setting('app.club_retirement_write', true), '') = 'on';
  v_maintenance boolean :=
    auth.uid() IS NULL
    AND coalesce(current_setting('app.club_retirement_maintenance', true), '') = 'on';
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF NOT v_maintenance AND NOT (
      auth.uid() IS NULL
      AND (OLD.name LIKE 'Crest Cert %' OR OLD.name LIKE 'Preset Crest Cert %')
      AND coalesce(current_setting('app.ledger_maintenance', true), '') <> ''
      AND coalesce(current_setting('app.game_management_retention', true), '') = 'on'
    ) THEN
      RAISE EXCEPTION 'CLUB_RECORD_RETAINED: real club records cannot be deleted'
        USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.lifecycle_status = 'retired' AND NOT v_maintenance THEN
    RAISE EXCEPTION 'CLUB_RETIRED: this club is read-only'
      USING ERRCODE = '55000';
  END IF;

  IF (NEW.lifecycle_status, NEW.retired_at, NEW.retired_by, NEW.retirement_reason)
       IS DISTINCT FROM
     (OLD.lifecycle_status, OLD.retired_at, OLD.retired_by, OLD.retirement_reason)
     AND NOT v_retirement_write
     AND NOT v_maintenance THEN
    RAISE EXCEPTION 'CLUB_LIFECYCLE_REQUIRES_RPC: use fn_retire_settled_club'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_guard_club_lifecycle_write() OWNER TO postgres;

