--
-- Name: fn_guard_horse_avatar(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_guard_horse_avatar() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.is_horse IS TRUE
     AND NEW.avatar_url LIKE '/avatars/%'
     AND coalesce(btrim(OLD.avatar_url), '') <> ''
     AND OLD.avatar_url NOT LIKE '/avatars/%' THEN
    NEW.avatar_url := OLD.avatar_url;
  END IF;
  RETURN NEW;
END;
$$;


