--
-- Name: fn_guard_youtube_native_transcode_job(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_guard_youtube_native_transcode_job() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_control_enabled boolean := false;
  v_reel public.social_reels%ROWTYPE;
  v_youtube_id text;
BEGIN
  IF NEW.source_type = 'youtube'
     AND NEW.status IN ('queued', 'processing', 'running')
  THEN
    -- Hold a shared row lock until this write commits. A concurrent disable
    -- therefore either wins first (and this write fails) or acknowledges only
    -- after this already-authorized write is durable.
    SELECT control.enabled
    INTO v_control_enabled
    FROM public.video_reels_pipeline_controls control
    WHERE control.control_key = 'youtube_native_transcode'
    FOR SHARE;

    IF NOT COALESCE(v_control_enabled, false) THEN
      RAISE EXCEPTION USING
        ERRCODE = '55000',
        MESSAGE = 'YouTube native transcode processing is disabled';
    END IF;

    v_youtube_id := public.fn_extract_youtube_video_id(NEW.youtube_url);
    IF v_youtube_id IS NOT NULL THEN
      PERFORM pg_advisory_xact_lock(
        hashtextextended('youtube-embed-failure:' || v_youtube_id, 0)
      );
    END IF;

    -- Serialize authorization changes with enqueue/claim writes. The Reel
    -- revocation trigger updates jobs after taking this row lock, so it either
    -- cancels this durable write or completes before this guard re-attests it.
    SELECT r.*
    INTO v_reel
    FROM public.social_reels r
    WHERE r.id = NEW.reel_id
    FOR SHARE;

    IF NOT FOUND
       OR v_youtube_id IS NULL
       OR public.fn_extract_youtube_video_id(NEW.source_url) IS DISTINCT FROM v_youtube_id
       OR NEW.rights_status NOT IN ('owned', 'licensed')
       OR NEW.user_id IS DISTINCT FROM v_reel.author_id
       OR NEW.rights_status IS DISTINCT FROM v_reel.rights_status
       OR NEW.origin_type IS DISTINCT FROM v_reel.origin_type
       OR NEW.source_asset_id IS DISTINCT FROM v_reel.source_asset_id
       OR NEW.canonical_asset_key IS DISTINCT FROM 'youtube:' || v_youtube_id
       OR v_reel.canonical_asset_key IS DISTINCT FROM NEW.canonical_asset_key
       OR v_reel.youtube_video_id IS DISTINCT FROM v_youtube_id
       OR public.fn_extract_youtube_video_id(v_reel.video_url) IS DISTINCT FROM v_youtube_id
       OR public.fn_extract_youtube_video_id(v_reel.original_youtube_url) IS DISTINCT FROM v_youtube_id
       OR v_reel.source_type IS DISTINCT FROM 'youtube'
       OR v_reel.native_processing_requested IS DISTINCT FROM true
       OR COALESCE(v_reel.is_deleted, false)
       OR v_reel.source_post_id IS NULL
       OR v_reel.origin_type = 'video_library'
       OR NOT (
         EXISTS (
           SELECT 1
           FROM public.video_library_videos verified_asset
           WHERE verified_asset.youtube_video_id = v_youtube_id
             AND verified_asset.availability_status = 'verified'
             AND verified_asset.embeddable IS TRUE
             AND verified_asset.availability_checked_at >= now() - interval '7 days'
             AND verified_asset.availability_checked_at <= now() + interval '5 minutes'
         )
         OR EXISTS (
           SELECT 1
           FROM public.youtube_embed_failures verified_source
           WHERE verified_source.video_id = v_youtube_id
             AND verified_source.verification_status = 'resolved'
             AND verified_source.resolved IS TRUE
             AND verified_source.last_verified_at >= now() - interval '7 days'
             AND verified_source.last_verified_at <= now() + interval '5 minutes'
         )
       )
       OR EXISTS (
         SELECT 1
         FROM public.youtube_embed_failures failed_source
         WHERE failed_source.video_id = v_youtube_id
           AND failed_source.verification_status = 'confirmed'
           AND failed_source.resolved = false
       )
    THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'YouTube native transcode job does not match a rights-cleared Reel';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_guard_youtube_native_transcode_job() OWNER TO postgres;

--
-- Name: fn_hand_history_bloat(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hand_history_bloat() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH c AS (
    SELECT relpages::bigint AS relpages, GREATEST(reltuples, 0)::bigint AS reltuples
      FROM pg_class WHERE oid = 'public.hand_history'::regclass
  ),
  d AS (
    SELECT COALESCE(NULLIF(avg(cnt), 0), 5)::numeric AS per_full_page
      FROM (
        SELECT count(*) AS cnt
          FROM public.hand_history TABLESAMPLE SYSTEM (0.05)
         GROUP BY (ctid::text::point)[0]::bigint
      ) s
  )
  SELECT jsonb_build_object(
    'relpages',            c.relpages,
    'reltuples',           c.reltuples,
    'tuples_per_page_avg', round(c.reltuples::numeric / NULLIF(c.relpages, 0), 3),
    'tuples_per_full_page', round(d.per_full_page, 2),
    'packed_pages_needed', ceil(c.reltuples / GREATEST(d.per_full_page, 1))::bigint,
    'empty_pages_est',     GREATEST(c.relpages - ceil(c.reltuples / GREATEST(d.per_full_page, 1))::bigint, 0),
    'pct_empty_est',       round(100 * GREATEST(c.relpages - ceil(c.reltuples / GREATEST(d.per_full_page, 1)), 0)
                                 / NULLIF(c.relpages, 0), 1),
    'heap',                pg_size_pretty(pg_relation_size('public.hand_history')),
    'indexes',             pg_size_pretty(pg_indexes_size('public.hand_history')),
    'total',               pg_size_pretty(pg_total_relation_size('public.hand_history'))
  )
  FROM c, d;
$$;


ALTER FUNCTION public.fn_hand_history_bloat() OWNER TO postgres;

--
-- Name: fn_hand_history_bloat_report(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hand_history_bloat_report() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'heap_bytes',        pg_relation_size('public.hand_history'),
    'index_bytes',       pg_indexes_size('public.hand_history'),
    'total_bytes',       pg_total_relation_size('public.hand_history'),
    'heap_pages',        pg_relation_size('public.hand_history') / 8192,
    'live_tuples',       (SELECT n_live_tup FROM pg_stat_user_tables
                           WHERE relname = 'hand_history' AND schemaname = 'public'),
    'live_tuples_per_page',
        round( (SELECT n_live_tup FROM pg_stat_user_tables
                 WHERE relname = 'hand_history' AND schemaname = 'public')::numeric
               / greatest(pg_relation_size('public.hand_history') / 8192, 1), 2),
    'measured_at',       now()
  );
$$;


ALTER FUNCTION public.fn_hand_history_bloat_report() OWNER TO postgres;

--
-- Name: FUNCTION fn_hand_history_bloat_report(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_hand_history_bloat_report() IS 'live_tuples_per_page is the number to read. Measured 1.33 on 2026-08-26 against a packed capacity of about 5, i.e. 73% of the heap was free space. Reclaiming it needs VACUUM FULL or partitioning, both of which need a maintenance window - this function exists so that decision is made against a number rather than a guess.';


--
-- Name: fn_hand_history_prune_backlog(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hand_history_prune_backlog() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH pol AS (
    SELECT greatest(coalesce(horse_retention_days, 7), 1) AS days
      FROM public.hand_history_retention_policy LIMIT 1
  ), cap AS (
    SELECT count(*) AS n
      FROM (
        SELECT 1
          FROM public.hand_history
         WHERE created_at < now() - make_interval(days => (SELECT days FROM pol))
           AND has_human IS DISTINCT FROM true
           AND reported IS NOT true
         LIMIT 200000
      ) z
  )
  SELECT jsonb_build_object(
    'retention_days',     (SELECT days FROM pol),
    'prunable_backlog',   (SELECT n FROM cap),
    'backlog_capped_at',  200000,
    'backlog_is_capped',  ((SELECT n FROM cap) >= 200000),
    'oldest_prunable',    (SELECT min(created_at) FROM public.hand_history
                            WHERE created_at < now() - make_interval(days => (SELECT days FROM pol))
                              AND has_human IS DISTINCT FROM true
                              AND reported IS NOT true),
    'measured_at',        now()
  );
$$;


ALTER FUNCTION public.fn_hand_history_prune_backlog() OWNER TO postgres;

--
-- Name: FUNCTION fn_hand_history_prune_backlog(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_hand_history_prune_backlog() IS 'Is the hand_history pruner keeping up? prunable_backlog should sit near zero. A backlog that climbs run over run means the insert rate has passed the prune rate and the table will grow without bound.';


--
-- Name: fn_hand_history_prune_skip_depth(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hand_history_prune_skip_depth(p_sample integer DEFAULT 50000) RETURNS TABLE(sampled bigint, skipped bigint, skip_pct numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH head AS (
    SELECT has_human, reported
      FROM public.hand_history
     WHERE created_at < now() - interval '7 days'
     ORDER BY created_at
     LIMIT p_sample
  )
  SELECT count(*)::bigint,
         count(*) FILTER (WHERE has_human IS TRUE OR reported IS TRUE)::bigint,
         round(100.0 * count(*) FILTER (WHERE has_human IS TRUE OR reported IS TRUE)
               / NULLIF(count(*), 0), 3)
    FROM head;
$$;


ALTER FUNCTION public.fn_hand_history_prune_skip_depth(p_sample integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_hand_history_prune_skip_depth(p_sample integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_hand_history_prune_skip_depth(p_sample integer) IS 'Density of permanently-kept rows (human or reported) at the head of idx_hand_history_created — the rows sp_prune_hand_history must filter past on every pass. Bounded to a sample of the head so it is always cheap. Near 0% is healthy. If it climbs toward 100% the pruner is walking a long dead prefix and the fix is: CREATE INDEX CONCURRENTLY idx_hand_history_unclassified ON hand_history (created_at) WHERE has_human IS NULL. Added 2026-08-20.';


--
-- Name: fn_hand_rake_breakdown(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hand_rake_breakdown(p_hand_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rr record;
  v_players jsonb;
  v_allocated numeric;
  v_caller uuid := auth.uid();
BEGIN
  SELECT * INTO v_rr FROM public.rake_records WHERE hand_id = p_hand_id
   ORDER BY created_at LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  -- The people who may read the club's money may read one hand of it: the
  -- ca_can_view_club_finances gate (owner, co-owner, admin, super agent,
  -- platform admin), a union overseer of the club, or the engine. This used
  -- to admit the owner alone, which left every other reader of the
  -- Financials page a lookup box that answered "not authorised".
  IF NOT public.fn_caller_is_engine() THEN
    IF v_caller IS NULL
       OR (NOT public.ca_can_view_club_finances(v_rr.club_id)
           AND NOT EXISTS (SELECT 1 FROM public.union_clubs uc
                            WHERE uc.club_id = v_rr.club_id
                              AND public.fn_is_union_overseer(uc.union_id, v_caller)))
    THEN
      RETURN jsonb_build_object('found', false, 'error', 'not_authorised');
    END IF;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'player_id', ra.player_id,
           'gross_contribution', ra.gross_contribution,
           'returned_uncalled', ra.returned_uncalled,
           'eligible_contribution', ra.eligible_contribution,
           'contribution_weight', ra.contribution_weight,
           'weighted_rake_credit', ra.weighted_rake_credit,
           'bbj_attributed_contribution', ra.bbj_attributed_contribution
         ) ORDER BY ra.weighted_rake_credit DESC), '[]'::jsonb),
         COALESCE(SUM(ra.weighted_rake_credit), 0)
    INTO v_players, v_allocated
    FROM public.rake_attributions ra WHERE ra.hand_id = p_hand_id;

  RETURN jsonb_build_object(
    'found', true,
    'hand_id', p_hand_id,
    'rake_method', v_rr.rake_method,
    'gross_pot', v_rr.pot_size,
    'regular_rake_collected', v_rr.rake_amount,
    'bbj_drop_collected', v_rr.bbj_contribution,
    'net_pot_paid_to_players',
      CASE WHEN v_rr.pot_size IS NULL THEN NULL
           ELSE v_rr.pot_size - v_rr.rake_amount - COALESCE(v_rr.bbj_contribution, 0) END,
    'total_eligible_contributions', (
      SELECT COALESCE(SUM((e.value)::numeric), 0)
        FROM jsonb_each(COALESCE(v_rr.player_contributions, '{}'::jsonb)) e
       WHERE jsonb_typeof(e.value) = 'number' AND (e.value)::numeric > 0),
    'players', v_players,
    'reconciliation', jsonb_build_object(
      'expected_regular_rake', round(v_rr.rake_amount, 2),
      'allocated_regular_rake', round(v_allocated, 2),
      'difference', round(v_rr.rake_amount - v_allocated, 2),
      'valid', (round(v_allocated, 2) = round(v_rr.rake_amount, 2))
    )
  );
END $$;


ALTER FUNCTION public.fn_hand_rake_breakdown(p_hand_id uuid) OWNER TO postgres;

