--
-- Name: fn_has_fresh_public_youtube_verification(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_has_fresh_public_youtube_verification(p_youtube_video_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
  SELECT p_youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'
    AND (
      EXISTS (
        SELECT 1
        FROM public.video_library_videos verified_asset
        WHERE verified_asset.youtube_video_id = p_youtube_video_id
          AND verified_asset.availability_status = 'verified'
          AND verified_asset.embeddable IS TRUE
          AND verified_asset.availability_checked_at >= now() - interval '7 days'
          AND verified_asset.availability_checked_at <= now() + interval '5 minutes'
      )
      OR EXISTS (
        SELECT 1
        FROM public.youtube_embed_failures verified_source
        WHERE verified_source.video_id = p_youtube_video_id
          AND verified_source.verification_status = 'resolved'
          AND verified_source.resolved IS TRUE
          AND verified_source.last_verified_at >= now() - interval '7 days'
          AND verified_source.last_verified_at <= now() + interval '5 minutes'
      )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.youtube_embed_failures failed_source
      WHERE failed_source.video_id = p_youtube_video_id
        AND failed_source.verification_status = 'confirmed'
        AND failed_source.resolved = false
    )
$_$;


ALTER FUNCTION public.fn_has_fresh_public_youtube_verification(p_youtube_video_id text) OWNER TO postgres;

--
-- Name: fn_has_player_wallet(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_has_player_wallet(p_club_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.club_members cm
      JOIN public.clubs c ON c.id = cm.club_id
     WHERE cm.club_id = p_club_id
       AND cm.user_id = p_user_id
       AND COALESCE(cm.status, 'active') IN ('active', 'approved')
       AND COALESCE(cm.role, 'player') <> 'admin'
       AND NOT COALESCE(c.is_union, false)
  );
$$;


ALTER FUNCTION public.fn_has_player_wallet(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_has_player_wallet(p_club_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_has_player_wallet(p_club_id uuid, p_user_id uuid) IS 'Dan 2026-09-03: owners, co-owners, agents and players hold a player wallet (club_members.chip_balance) in a club; admins never do; unions have no player wallets.';


--
-- Name: fn_heal_seat_provenance(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_heal_seat_provenance() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_seats integer; v_entries integer;
BEGIN
  UPDATE table_seats ts
     SET club_id = public.fn_seat_club_for_user(ts.user_id, ts.table_id, NULL)
   WHERE ts.left_at IS NULL
     AND ts.club_id IS NULL
     AND ts.user_id IS NOT NULL
     AND public.fn_seat_club_for_user(ts.user_id, ts.table_id, NULL) IS NOT NULL;
  GET DIAGNOSTICS v_seats = ROW_COUNT;

  UPDATE tournament_players tp
     SET club_id = public.fn_tournament_club_for_user(tp.user_id, tp.tournament_id, NULL)
    FROM tournaments t
   WHERE t.id = tp.tournament_id
     AND tp.club_id IS NULL
     AND tp.user_id IS NOT NULL
     AND t.status IN ('ANNOUNCED','SCHEDULED','REGISTERING','LATE_REG','RUNNING')
     AND public.fn_tournament_club_for_user(tp.user_id, tp.tournament_id, NULL) IS NOT NULL;
  GET DIAGNOSTICS v_entries = ROW_COUNT;

  RETURN v_seats + v_entries;
END $$;


ALTER FUNCTION public.fn_heal_seat_provenance() OWNER TO postgres;

--
-- Name: fn_heartbeat_live_viewer(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_heartbeat_live_viewer(p_stream_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_rows integer;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'unauthenticated');
  END IF;

  -- Idempotent upsert. The unique constraint on (stream_id, viewer_id)
  -- means INSERT … ON CONFLICT DO UPDATE refreshes last_seen_at on the
  -- existing row. last_seen_at is the only column touched on conflict.
  INSERT INTO public.live_viewers (stream_id, viewer_id, last_seen_at)
       VALUES (p_stream_id, v_user_id, now())
  ON CONFLICT (stream_id, viewer_id)
  DO UPDATE SET last_seen_at = now();

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'rows', v_rows);
END;
$$;


ALTER FUNCTION public.fn_heartbeat_live_viewer(p_stream_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_heartbeat_live_viewer(p_stream_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_heartbeat_live_viewer(p_stream_id uuid) IS 'Viewer self-heartbeat. Idempotent upsert of (stream_id, auth.uid()) with last_seen_at = now(). Used by LiveStreamService to keep the named-viewers list fresh.';


