--
-- Name: fn_hg_clear_ineligible_member_rsvps(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hg_clear_ineligible_member_rsvps() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_group_id uuid;
  v_user_id uuid;
  v_member_id uuid;
  v_previous_claim_sub text := current_setting('request.jwt.claim.sub', true);
  v_previous_claims text := current_setting('request.jwt.claims', true);
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_group_id := OLD.group_id;
    v_user_id := OLD.user_id;
    v_member_id := OLD.id;
  ELSE
    IF NEW.status IN ('approved', 'pending') THEN
      RETURN NEW;
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
      RETURN NEW;
    END IF;
    v_group_id := NEW.group_id;
    v_user_id := NEW.user_id;
    v_member_id := NEW.id;
  END IF;

  -- Existing RSVP permission/deadline triggers correctly block direct user
  -- edits after closure. This nested system correction must still be able to
  -- release a seat, so temporarily clear both auth.uid() claim sources and
  -- restore them before returning to the caller's transaction.
  PERFORM set_config('request.jwt.claim.sub', '', true);
  PERFORM set_config('request.jwt.claims', '', true);

  UPDATE public.commander_home_rsvps r
     SET response = 'no',
         is_confirmed = false,
         seat_number = NULL,
         updated_at = now()
    FROM public.commander_home_games game
    JOIN public.commander_home_groups home_group ON home_group.id = game.group_id
   WHERE game.id = r.game_id
     AND game.group_id = v_group_id
     AND game.status IN ('scheduled', 'confirmed', 'in_progress')
     AND v_user_id IS NOT NULL
     AND r.user_id = v_user_id
     AND r.user_id IS DISTINCT FROM home_group.owner_id
     AND r.user_id IS DISTINCT FROM game.host_id
     AND r.response IN ('yes', 'maybe', 'waitlist');

  -- Roster-only members have no user_id and therefore no RSVP row. Release
  -- their member_id-backed reservations as well as real-user/claimed guest
  -- reservations, and remove any already-materialized live seat first.
  DELETE FROM public.commander_home_seats seat
  USING public.commander_home_seat_reservations reservation,
        public.commander_home_game_tables game_table,
        public.commander_home_games game
   WHERE seat.reservation_id = reservation.id
     AND game_table.id = reservation.table_id
     AND game.id = game_table.game_id
     AND game.group_id = v_group_id
     AND game.status IN ('scheduled', 'confirmed', 'in_progress')
     AND reservation.status IN ('reserved', 'seated')
     AND (
       reservation.member_id = v_member_id
       OR (v_user_id IS NOT NULL AND reservation.user_id = v_user_id)
       OR (v_user_id IS NOT NULL AND reservation.claimed_by_user_id = v_user_id)
     );

  UPDATE public.commander_home_seat_reservations reservation
     SET status = 'released',
         released_at = coalesce(released_at, now()),
         updated_at = now()
    FROM public.commander_home_game_tables game_table,
         public.commander_home_games game
   WHERE game_table.id = reservation.table_id
     AND game.id = game_table.game_id
     AND game.group_id = v_group_id
     AND game.status IN ('scheduled', 'confirmed', 'in_progress')
     AND reservation.status IN ('reserved', 'seated')
     AND (
       reservation.member_id = v_member_id
       OR (v_user_id IS NOT NULL AND reservation.user_id = v_user_id)
       OR (v_user_id IS NOT NULL AND reservation.claimed_by_user_id = v_user_id)
     );

  PERFORM set_config('request.jwt.claim.sub', coalesce(v_previous_claim_sub, ''), true);
  PERFORM set_config('request.jwt.claims', coalesce(v_previous_claims, ''), true);

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_hg_clear_ineligible_member_rsvps() OWNER TO postgres;

--
-- Name: FUNCTION fn_hg_clear_ineligible_member_rsvps(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_hg_clear_ineligible_member_rsvps() IS 'Releases current/upcoming RSVPs, reservations, and materialized seats whenever a non-owner/non-host membership becomes ineligible or is removed, including roster-only members.';


--
-- Name: fn_hg_enforce_quotas_on_write(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hg_enforce_quotas_on_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid; v_count int;
BEGIN
  -- Bypass service_role / no-auth contexts
  v_uid := auth.uid();
  BEGIN
    IF v_uid IS NULL OR auth.role() = 'service_role' THEN RETURN NEW; END IF;
  EXCEPTION WHEN OTHERS THEN RETURN NEW;
  END;

  IF TG_TABLE_NAME = 'commander_home_groups' THEN
    -- Only enforce when caller is actually creating for themselves
    IF NEW.owner_id = v_uid THEN
      SELECT COUNT(*) INTO v_count FROM public.commander_home_groups
       WHERE owner_id = v_uid AND is_active = true;
      IF v_count >= 20 THEN
        RAISE EXCEPTION 'GROUP_QUOTA_EXCEEDED'
              USING HINT = 'max 20 active groups per user';
      END IF;
    END IF;

  ELSIF TG_TABLE_NAME = 'commander_home_invite_tokens' THEN
    IF NEW.created_by = v_uid THEN
      SELECT COUNT(*) INTO v_count FROM public.commander_home_invite_tokens
       WHERE group_id = NEW.group_id
         AND is_active = true
         AND (expires_at IS NULL OR expires_at > NOW());
      IF v_count >= 50 THEN
        RAISE EXCEPTION 'TOKEN_QUOTA_EXCEEDED'
              USING HINT = 'max 50 active unexpired tokens per group';
      END IF;
    END IF;

  ELSIF TG_TABLE_NAME = 'commander_home_games' THEN
    IF NEW.host_id = v_uid THEN
      SELECT COUNT(*) INTO v_count FROM public.commander_home_games
       WHERE group_id = NEW.group_id
         AND status = 'scheduled'
         AND scheduled_date >= CURRENT_DATE;
      IF v_count >= 100 THEN
        RAISE EXCEPTION 'SCHEDULED_GAMES_QUOTA_EXCEEDED'
              USING HINT = 'max 100 future-scheduled games per group';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_hg_enforce_quotas_on_write() OWNER TO postgres;

--
-- Name: fn_hg_enforce_rsvp_capacity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hg_enforce_rsvp_capacity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_max_players integer;
  v_seats_taken integer;
  v_requested_seats integer;
BEGIN
  IF NEW.response <> 'yes' THEN RETURN NEW; END IF;

  SELECT max_players
    INTO v_max_players
    FROM public.commander_home_games
   WHERE id = NEW.game_id
   FOR UPDATE;

  IF NOT FOUND OR v_max_players IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    SELECT coalesce(sum(1 + greatest(coalesce(r.bringing_guests, 0), 0)), 0)::integer
      INTO v_seats_taken
      FROM public.commander_home_rsvps r
     WHERE r.game_id = NEW.game_id
       AND r.response = 'yes'
       AND r.id <> OLD.id;
  ELSE
    SELECT coalesce(sum(1 + greatest(coalesce(r.bringing_guests, 0), 0)), 0)::integer
      INTO v_seats_taken
      FROM public.commander_home_rsvps r
     WHERE r.game_id = NEW.game_id
       AND r.response = 'yes';
  END IF;

  v_requested_seats := 1 + greatest(coalesce(NEW.bringing_guests, 0), 0);
  IF v_seats_taken + v_requested_seats > v_max_players THEN
    NEW.response := 'waitlist';
    NEW.is_confirmed := false;
    NEW.seat_number := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_hg_enforce_rsvp_capacity() OWNER TO postgres;

--
-- Name: FUNCTION fn_hg_enforce_rsvp_capacity(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_hg_enforce_rsvp_capacity() IS 'Serializes RSVP capacity by game and counts each yes response plus guests; update checks exclude the RSVP being replaced.';


--
-- Name: fn_hg_enforce_rsvp_membership_state(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hg_enforce_rsvp_membership_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_group_id uuid;
  v_owner_id uuid;
  v_host_id uuid;
  v_membership_status text;
BEGIN
  SELECT g.group_id, h.owner_id, g.host_id
    INTO v_group_id, v_owner_id, v_host_id
    FROM public.commander_home_games g
    JOIN public.commander_home_groups h ON h.id = g.group_id
   WHERE g.id = NEW.game_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RSVP_GAME_NOT_FOUND' USING ERRCODE = '23503';
  END IF;

  -- Anyone may clear their own stale RSVP; no ineligible user may retain or
  -- create an active yes/maybe/waitlist RSVP.
  IF NEW.response = 'no' THEN
    RETURN NEW;
  END IF;

  IF NEW.user_id = v_owner_id OR NEW.user_id = v_host_id THEN
    RETURN NEW;
  END IF;

  SELECT status INTO v_membership_status
    FROM public.commander_home_members
   WHERE group_id = v_group_id
     AND user_id = NEW.user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RSVP_MEMBERSHIP_REQUIRED' USING ERRCODE = '42501';
  END IF;
  IF v_membership_status = 'banned' THEN
    RAISE EXCEPTION 'RSVP_MEMBERSHIP_BANNED' USING ERRCODE = '42501';
  END IF;
  IF v_membership_status = 'declined' THEN
    RAISE EXCEPTION 'RSVP_MEMBERSHIP_DECLINED' USING ERRCODE = '42501';
  END IF;
  IF v_membership_status NOT IN ('approved', 'pending') THEN
    RAISE EXCEPTION 'RSVP_MEMBERSHIP_INVALID' USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_hg_enforce_rsvp_membership_state() OWNER TO postgres;

--
-- Name: FUNCTION fn_hg_enforce_rsvp_membership_state(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_hg_enforce_rsvp_membership_state() IS 'Rejects active Home Games RSVPs without an approved/pending membership and rejects banned/declined members.';


--
-- Name: fn_hg_require_onboarded_on_write(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hg_require_onboarded_on_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid            uuid;
  v_target_user_id uuid;
  v_onboarded_at   timestamptz;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RETURN NEW; END IF;
  BEGIN
    IF auth.role() = 'service_role' THEN RETURN NEW; END IF;
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  IF    TG_TABLE_NAME = 'commander_home_groups'          THEN v_target_user_id := NEW.owner_id;
  ELSIF TG_TABLE_NAME = 'commander_home_games'           THEN v_target_user_id := NEW.host_id;
  ELSIF TG_TABLE_NAME = 'commander_home_posts'           THEN v_target_user_id := NEW.author_id;
  ELSIF TG_TABLE_NAME = 'commander_home_post_comments'   THEN v_target_user_id := NEW.author_id;
  ELSIF TG_TABLE_NAME = 'commander_home_post_likes'      THEN v_target_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'commander_home_members'         THEN v_target_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'commander_home_rsvps'           THEN v_target_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'commander_home_game_photos'     THEN v_target_user_id := NEW.uploader_id;
  ELSIF TG_TABLE_NAME = 'commander_home_poll_votes'      THEN v_target_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'commander_home_polls'           THEN v_target_user_id := NEW.created_by;
  ELSIF TG_TABLE_NAME = 'commander_home_invite_tokens'   THEN v_target_user_id := NEW.created_by;
  ELSIF TG_TABLE_NAME = 'commander_home_ban_appeals'     THEN v_target_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'commander_home_content_reports' THEN v_target_user_id := NEW.reporter_id;
  ELSIF TG_TABLE_NAME = 'commander_home_game_reviews'    THEN v_target_user_id := NEW.reviewer_id;
  ELSIF TG_TABLE_NAME = 'commander_home_group_follows'   THEN v_target_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'commander_home_game_templates'  THEN v_target_user_id := NEW.created_by;
  ELSE v_target_user_id := NULL;
  END IF;

  IF v_target_user_id IS NULL OR v_target_user_id <> v_uid THEN
    RETURN NEW;
  END IF;

  SELECT home_games_onboarded_at INTO v_onboarded_at
    FROM public.profiles WHERE id = v_uid;
  IF v_onboarded_at IS NOT NULL THEN RETURN NEW; END IF;

  RAISE EXCEPTION 'ONBOARDING_REQUIRED'
    USING HINT = 'Complete the Home Games welcome flow (age, jurisdiction, policy acceptance) before using Home Games.';
END;
$$;


ALTER FUNCTION public.fn_hg_require_onboarded_on_write() OWNER TO postgres;

--
-- Name: FUNCTION fn_hg_require_onboarded_on_write(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_hg_require_onboarded_on_write() IS 'HG commercial-grade onboarding gate. Fires BEFORE INSERT on HG user-write tables. Gates only when caller == row writer AND caller not onboarded. Bypasses service_role and admin-on-behalf-of-user writes.';


--
-- Name: fn_hg_text_writing_functions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hg_text_writing_functions() RETURNS TABLE(proname text, has_cap boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.proname::text,
         -- An UPPER BOUND on a length, in either spelling, or one of the
         -- shared error tokens. `length(x) = 0` is an emptiness test and does
         -- not count - that was the hole that let two RPCs through.
         (pg_get_functiondef(p.oid) ~* '(length|char_length)\s*\([^)]*\)\s*>'
          OR pg_get_functiondef(p.oid) ~* '(TOO_LONG|TOO_MANY)')
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public'
     AND p.prokind = 'f'
     AND p.proname ~ '^(fn_home_|create_home_|record_home_|toggle_home_|broadcast_to_home)'
     AND pg_get_function_identity_arguments(p.oid) ~ '\mtext\M'
     AND pg_get_functiondef(p.oid) ~* '\mINSERT\M|\mUPDATE\M'
     -- An argument validated against a fixed set needs a membership test, not
     -- a length bound. fn_home_set_seat_status is the example.
     AND pg_get_functiondef(p.oid) !~* 'NOT IN \(\s*''[a-z_]+''\s*,';
$$;


ALTER FUNCTION public.fn_hg_text_writing_functions() OWNER TO postgres;

