-- Name: fn_hg_trg_bump_activity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hg_trg_bump_activity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_group_id uuid;
BEGIN
  v_group_id := COALESCE(
    (CASE WHEN TG_OP = 'DELETE' THEN OLD.group_id ELSE NEW.group_id END)
  );
  IF v_group_id IS NOT NULL THEN
    UPDATE public.commander_home_groups
       SET last_activity_at = NOW()
     WHERE id = v_group_id
       AND (last_activity_at IS NULL OR last_activity_at < NOW());
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


