--
-- Name: fn_home_game_unseated_confirmed(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_game_unseated_confirmed(p_game_id uuid) RETURNS TABLE(user_id uuid, display_name text, rsvp_response text, responded_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_caller   uuid := auth.uid();
    v_group_id uuid;
BEGIN
    IF v_caller IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

    SELECT g.group_id INTO v_group_id
    FROM public.commander_home_games g
    WHERE g.id = p_game_id;

    IF v_group_id IS NULL THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;

    IF NOT public.fn_home_is_group_staff(v_caller, v_group_id) THEN
        RAISE EXCEPTION 'NOT_GROUP_STAFF';
    END IF;

    RETURN QUERY
    SELECT r.user_id,
           COALESCE(public.fn_hg_caller_display_name(r.user_id), 'Player') AS display_name,
           r.response,
           r.responded_at
    FROM public.commander_home_rsvps r
    WHERE r.game_id = p_game_id
      AND r.response = 'yes'
      AND r.user_id IS NOT NULL
      -- No active seat anywhere in this game.
      AND NOT EXISTS (
          SELECT 1
          FROM public.commander_home_seat_reservations sr
          JOIN public.commander_home_game_tables t ON t.id = sr.table_id
          WHERE t.game_id = p_game_id
            AND sr.user_id = r.user_id
            AND sr.status IN ('reserved', 'seated')
      )
    ORDER BY r.responded_at NULLS LAST;
END;
$$;


ALTER FUNCTION public.fn_home_game_unseated_confirmed(p_game_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_home_game_unseated_confirmed(p_game_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_home_game_unseated_confirmed(p_game_id uuid) IS 'Players who RSVP''d yes to a game but hold no seat at any of its tables. Staff-only. Intended as a pre-flight warning before rpc_hg_start_table, which deliberately seats ONLY players with a reservation — RSVP and seat assignment are separate steps by design. See migration phase57.';


--
-- Name: fn_home_group_refresh_geog(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_group_refresh_geog() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    IF NEW.latitude IS NOT NULL AND NEW.longitude IS NOT NULL THEN
        NEW.location_geog := ST_SetSRID(ST_MakePoint(NEW.longitude, NEW.latitude), 4326)::geography;
    ELSE
        NEW.location_geog := NULL;
    END IF;
    RETURN NEW;
END;
$$;


