--
-- Name: fn_home_protect_identity_fields(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_protect_identity_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_field text;
  v_old_val text;
  v_new_val text;
BEGIN
  -- No JWT → internal operation (cron, migration, trigger cascade from
  -- another trigger that's already validated). Allow.
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  -- service_role bypass (server-side admin code paths are trusted)
  IF COALESCE(auth.role(), '') = 'service_role' THEN
    RETURN NEW;
  END IF;

  FOREACH v_field IN ARRAY TG_ARGV LOOP
    EXECUTE format('SELECT ($1).%I::text, ($2).%I::text', v_field, v_field)
      INTO v_old_val, v_new_val
      USING OLD, NEW;

    IF v_old_val IS DISTINCT FROM v_new_val THEN
      RAISE EXCEPTION
        'Cannot change %.% after creation (was %, attempted %). '
        'Identity fields are immutable.',
        TG_TABLE_NAME, v_field, COALESCE(v_old_val,'<null>'), COALESCE(v_new_val,'<null>')
        USING ERRCODE = '42501';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_home_protect_identity_fields() OWNER TO postgres;

--
-- Name: FUNCTION fn_home_protect_identity_fields(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_home_protect_identity_fields() IS 'Phase 40: blocks UPDATE of identity fields (passed as TG_ARGV) by any authenticated caller. Skipped for cron/migration (no auth.uid()) and service_role. Used by per-table BEFORE UPDATE triggers.';


--
-- Name: fn_home_protect_row_identity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_protect_row_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := current_user;
BEGIN
  IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                'supabase_auth_admin', 'supabase_storage_admin') THEN
    RETURN NEW;
  END IF;

  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'ROW_IDENTITY_IMMUTABLE'
          USING HINT = 'the primary key (id) of a ' || TG_TABLE_NAME
                     || ' row cannot be changed via direct UPDATE; '
                     || 'delete and recreate the row if needed (was '
                     || OLD.id::text || ', attempted ' || NEW.id::text || ')',
                ERRCODE = '42501';
  END IF;

  IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'CREATED_AT_IMMUTABLE'
          USING HINT = 'created_at on ' || TG_TABLE_NAME
                     || ' is the row origin timestamp and cannot be '
                     || 'modified after insert (was '
                     || OLD.created_at::text || ', attempted '
                     || NEW.created_at::text || ')',
                ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_home_protect_row_identity() OWNER TO postgres;

--
-- Name: FUNCTION fn_home_protect_row_identity(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_home_protect_row_identity() IS 'Pass 47: universal row-identity immutability for home_* tables. Blocks NEW.id <> OLD.id (PK tamper) and NEW.created_at <> OLD.created_at (chronology tamper) for non-service-role callers. Attached as BEFORE UPDATE on every home_* table with a writable RLS UPDATE policy. Seals BK-1/BK-2.';


--
-- Name: fn_home_protect_row_identity_with_ts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_protect_row_identity_with_ts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role     text := current_user;
  v_col      text;
  v_old_val  text;
  v_new_val  text;
BEGIN
  IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                'supabase_auth_admin', 'supabase_storage_admin') THEN
    RETURN NEW;
  END IF;

  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  -- Primary key is always immutable.
  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'ROW_IDENTITY_IMMUTABLE'
          USING HINT = 'the primary key (id) of a ' || TG_TABLE_NAME
                     || ' row cannot be changed via direct UPDATE '
                     || '(was ' || OLD.id::text || ', attempted ' || NEW.id::text || ')',
                ERRCODE = '42501';
  END IF;

  -- Origin timestamp: parameterized via TG_ARGV[0] (responded_at / requested_at / ...).
  IF TG_NARGS >= 1 AND TG_ARGV[0] IS NOT NULL THEN
    v_col := TG_ARGV[0];
    EXECUTE format('SELECT ($1).%I::text, ($2).%I::text', v_col, v_col)
       INTO v_old_val, v_new_val
      USING OLD, NEW;

    IF v_old_val IS DISTINCT FROM v_new_val THEN
      RAISE EXCEPTION 'ORIGIN_TIMESTAMP_IMMUTABLE'
            USING HINT = v_col || ' on ' || TG_TABLE_NAME
                       || ' is the row origin timestamp and cannot be modified '
                       || '(was ' || COALESCE(v_old_val, '<null>')
                       || ', attempted ' || COALESCE(v_new_val, '<null>') || ')',
                  ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_home_protect_row_identity_with_ts() OWNER TO postgres;

--
-- Name: FUNCTION fn_home_protect_row_identity_with_ts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_home_protect_row_identity_with_ts() IS 'Pass 47 follow-up: row-identity immutability for home_* tables that use a non-standard origin-timestamp column (e.g., responded_at on RSVPs). Blocks id tamper + origin-ts tamper (column named via TG_ARGV[0]).';


--
-- Name: fn_home_randomize_seats(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_randomize_seats(p_caller uuid, p_game_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_assigned integer := 0;
BEGIN
    IF auth.role() IS DISTINCT FROM 'service_role' 
       AND (auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_caller) THEN
        RETURN jsonb_build_object('success', false, 'error', 'unauthorized: caller identity mismatch');
    END IF;
    IF NOT fn_home_caller_is_game_staff(p_caller, p_game_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not authorized');
    END IF;
    WITH candidates AS (
        SELECT r.user_id FROM commander_home_rsvps r
         WHERE r.game_id = p_game_id AND r.is_confirmed = true AND r.response = 'yes'
           AND NOT EXISTS (SELECT 1 FROM commander_home_seats s
                            WHERE s.game_id = p_game_id AND s.user_id = r.user_id)
         ORDER BY random()
    ),
    empties AS (SELECT seat_number FROM commander_home_seats
                 WHERE game_id = p_game_id AND user_id IS NULL AND status = 'empty'
                 ORDER BY seat_number),
    pairs AS (SELECT c.user_id, e.seat_number FROM
              (SELECT user_id, ROW_NUMBER() OVER () AS rn FROM candidates) c
              JOIN (SELECT seat_number, ROW_NUMBER() OVER () AS rn FROM empties) e
                ON c.rn = e.rn),
    upd AS (UPDATE commander_home_seats s
               SET user_id = p.user_id, status = 'seated',
                   seated_at = NOW(), updated_at = NOW()
              FROM pairs p
             WHERE s.game_id = p_game_id AND s.seat_number = p.seat_number
            RETURNING 1)
    SELECT COUNT(*) INTO v_assigned FROM upd;
    RETURN jsonb_build_object('success', true, 'game_id', p_game_id, 'assigned', v_assigned);
END;
$$;


ALTER FUNCTION public.fn_home_randomize_seats(p_caller uuid, p_game_id uuid) OWNER TO postgres;

