--
-- Name: fn_horse_decision_latency_add(date, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_decision_latency_add(p_day date, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rows integer := 0;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    return 0;
  end if;

  insert into public.horse_decision_latency as h (day, scope, samples, total_ms, max_ms, buckets, updated_at)
  select p_day,
         r->>'scope',
         coalesce((r->>'samples')::bigint, 0),
         coalesce((r->>'totalMs')::double precision, 0),
         coalesce((r->>'maxMs')::double precision, 0),
         coalesce(
           (select array_agg(coalesce(b::bigint, 0) order by ord)
              from jsonb_array_elements_text(coalesce(r->'buckets', '[]'::jsonb))
                   with ordinality as t(b, ord)),
           '{}'::bigint[]
         ),
         now()
    from jsonb_array_elements(p_rows) r
   where coalesce(r->>'scope', '') <> ''
  on conflict (day, scope) do update
     set samples  = h.samples + excluded.samples,
         total_ms = h.total_ms + excluded.total_ms,
         max_ms   = greatest(h.max_ms, excluded.max_ms),
         buckets  = (
           select array_agg(coalesce(h.buckets[i], 0) + coalesce(excluded.buckets[i], 0) order by i)
             from generate_series(
                    1,
                    greatest(coalesce(array_length(h.buckets, 1), 0),
                             coalesce(array_length(excluded.buckets, 1), 0))
                  ) as i
         ),
         updated_at = now();

  get diagnostics v_rows = row_count;
  return v_rows;
end;
$$;


ALTER FUNCTION public.fn_horse_decision_latency_add(p_day date, p_rows jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_horse_decision_latency_add(p_day date, p_rows jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_horse_decision_latency_add(p_day date, p_rows jsonb) IS 'Additively fold one minute of decision-latency histograms into horse_decision_latency. Additive so a retry after a failed flush is safe; max_ms is a max rather than a sum, because summing two peaks would invent a decision that never happened.';


--
-- Name: fn_horse_frequency_leaks(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_frequency_leaks(p_since date) RETURNS TABLE(horse_user_id uuid, hands bigint, vpip numeric, pfr_of_vpip numeric, three_bet numeric, fold_to_3bet numeric, wwsf numeric, af numeric, leaks text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with agg as (
    select p.horse_user_id,
           sum(p.hands)::bigint              as hands,
           sum(p.vpip)::bigint               as vpip,
           sum(p.pfr)::bigint                as pfr,
           sum(p.three_bets)::bigint         as three_bets,
           sum(p.three_bet_opps)::bigint     as three_bet_opps,
           sum(p.faced_3bets)::bigint        as faced_3bets,
           sum(p.fold_to_3bets)::bigint      as fold_to_3bets,
           sum(p.saw_flop)::bigint           as saw_flop,
           sum(p.won_when_saw_flop)::bigint  as won_when_saw_flop,
           sum(p.post_aggr)::bigint          as post_aggr,
           sum(p.post_passive)::bigint       as post_passive
      from horse_daily_play p
     where p.day >= p_since and p.format in ('cash', 'hu_cash')
       and p.floored = false
     group by 1
    having sum(p.hands) >= 1000
  ),
  rates as (
    select a.horse_user_id, a.hands,
           round(a.vpip::numeric / a.hands, 4) as vpip,
           case when a.vpip > 0 then round(a.pfr::numeric / a.vpip, 4) end as pfr_of_vpip,
           case when a.three_bet_opps >= 100 then round(a.three_bets::numeric / a.three_bet_opps, 4) end as three_bet,
           case when a.faced_3bets >= 30 then round(a.fold_to_3bets::numeric / a.faced_3bets, 4) end as fold_to_3bet,
           case when a.saw_flop >= 150 then round(a.won_when_saw_flop::numeric / a.saw_flop, 4) end as wwsf,
           case when a.post_aggr + a.post_passive >= 100 and a.post_passive >= 25
                then round(a.post_aggr::numeric / a.post_passive, 4) end as af
      from agg a
  )
  select r.horse_user_id, r.hands, r.vpip, r.pfr_of_vpip, r.three_bet, r.fold_to_3bet, r.wwsf, r.af,
         array_remove(array[
           case when r.vpip > 0.32 then 'freq_too_loose' end,
           case when r.vpip < 0.19 then 'freq_too_tight' end,
           case when r.pfr_of_vpip is not null and r.pfr_of_vpip < 0.55 then 'freq_limp' end,
           case when r.three_bet is not null and r.three_bet < 0.03 then 'freq_no_3bet' end,
           case when r.fold_to_3bet is not null and r.fold_to_3bet > 0.62 then 'freq_over_fold_3bet' end,
           case when r.fold_to_3bet is not null and r.fold_to_3bet < 0.35 then 'freq_sticky_vs_3bet' end,
           case when r.wwsf is not null and r.wwsf < 0.40 then 'freq_surrender_flops' end,
           case when r.af is not null and r.af < 1.2 then 'freq_passive_postflop' end,
           case when r.af is not null and r.af > 3.5 then 'freq_spewy_postflop' end
         ], null) as leaks
    from rates r;
$$;


ALTER FUNCTION public.fn_horse_frequency_leaks(p_since date) OWNER TO postgres;

--
-- Name: fn_horse_fund_from_treasury(uuid, uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_fund_from_treasury(p_table_id uuid, p_user_id uuid, p_amount numeric, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_club_id uuid;
  v_request jsonb;
  v_response jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);

  IF p_table_id IS NULL OR p_user_id IS NULL OR p_amount IS NULL OR p_amount <= 0
     OR p_amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'table, user and positive amount required'
    );
  END IF;

  SELECT club_id
    INTO v_club_id
    FROM public.tables
   WHERE id = p_table_id;
  IF v_club_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'table has no club');
  END IF;
  IF NOT public.fn_actor_can_manage_club_treasury(v_club_id) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'not authorized to fund from club treasury'
    );
  END IF;

  v_request := jsonb_build_object(
    'door', 'fn_horse_fund_from_treasury',
    'table_id', p_table_id,
    'user_id', p_user_id,
    'amount', p_amount
  );
  v_response := public.fn_claim_entry_purchase_receipt(
    'horse_funding', p_op_id::text, v_request
  );
  IF NOT COALESCE((v_response->>'claimed')::boolean, false) THEN
    v_response := v_response->'response';
    IF v_response->>'success' IS DISTINCT FROM 'true'
       OR v_response->>'op_id' IS DISTINCT FROM p_op_id::text
       OR v_response->>'table_id' IS DISTINCT FROM p_table_id::text
       OR v_response->>'user_id' IS DISTINCT FROM p_user_id::text
       OR v_response->>'club_id' IS DISTINCT FROM v_club_id::text
       OR (v_response->>'amount')::numeric IS DISTINCT FROM p_amount
       OR jsonb_typeof(v_response->'new_stack') IS DISTINCT FROM 'number'
       OR (v_response->>'new_stack')::numeric < p_amount THEN
      RAISE EXCEPTION
        'HORSE_FUNDING_RECEIPT_INVALID: immutable response does not match the authorized request'
        USING ERRCODE = '55000';
    END IF;
    RETURN v_response || jsonb_build_object('replayed', true);
  END IF;

  IF p_op_id IS NOT NULL AND EXISTS (
    SELECT 1
      FROM public.chip_ledger l
     WHERE l.idempotency_key = 'horse_fund:' || p_op_id::text
  ) THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_RECEIPT_UNBOUND: this historical horse key has no exact response receipt'
      USING ERRCODE = '55000';
  END IF;

  IF public.fn_entry_purchases_frozen() THEN
    PERFORM public.fn_release_entry_purchase_claim(
      'horse_funding', p_op_id::text, v_request
    );
    RETURN jsonb_build_object(
      'success', false,
      'deferred', true,
      'error', 'PLATFORM_FROZEN: scheduled maintenance has deferred this horse rebuy'
    );
  END IF;

  PERFORM public.fn_assert_cash_chip_purchase_table(p_table_id);
  v_response := public.fn_horse_fund_from_treasury_before_maintenance_gate(
    p_table_id, p_user_id, p_amount, p_op_id
  );
  IF NOT COALESCE((v_response->>'success')::boolean, false) THEN
    PERFORM public.fn_release_entry_purchase_claim(
      'horse_funding', p_op_id::text, v_request
    );
    RETURN v_response;
  END IF;

  IF v_response->>'op_id' IS DISTINCT FROM p_op_id::text
     OR v_response->>'table_id' IS DISTINCT FROM p_table_id::text
     OR v_response->>'user_id' IS DISTINCT FROM p_user_id::text
     OR v_response->>'club_id' IS DISTINCT FROM v_club_id::text
     OR (v_response->>'amount')::numeric IS DISTINCT FROM p_amount
     OR jsonb_typeof(v_response->'new_stack') IS DISTINCT FROM 'number'
     OR (v_response->>'new_stack')::numeric < p_amount THEN
    RAISE EXCEPTION
      'HORSE_FUNDING_RECEIPT_INVALID: money core returned a mismatched acknowledgement'
      USING ERRCODE = '55000';
  END IF;

  RETURN public.fn_record_entry_purchase_receipt(
    'horse_funding', p_op_id::text, v_request, v_response
  );
END;
$$;


ALTER FUNCTION public.fn_horse_fund_from_treasury(p_table_id uuid, p_user_id uuid, p_amount numeric, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_horse_fund_from_treasury_before_maintenance_gate(uuid, uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_fund_from_treasury_before_maintenance_gate(p_table_id uuid, p_user_id uuid, p_amount numeric, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_club_id uuid;
  v_treasury numeric;
  v_new_stack numeric;
  v_prior public.chip_ledger;
  v_skip text := COALESCE(current_setting('app.ledger_autoskip_clubs', true), '');
BEGIN
  IF p_table_id IS NULL OR p_user_id IS NULL OR p_amount IS NULL OR p_amount <= 0
     OR p_amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'table, user and positive amount required'
    );
  END IF;

  SELECT club_id
    INTO v_club_id
    FROM public.tables
   WHERE id = p_table_id;
  IF v_club_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'table has no club');
  END IF;

  IF NOT public.fn_actor_can_manage_club_treasury(v_club_id) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'not authorized to fund from club treasury'
    );
  END IF;

  IF p_op_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('horse_fund:' || p_op_id::text, 0)
    );
    SELECT *
      INTO v_prior
      FROM public.chip_ledger
     WHERE idempotency_key = 'horse_fund:' || p_op_id::text;
    IF FOUND THEN
      IF v_prior.table_id IS DISTINCT FROM p_table_id
         OR v_prior.club_id IS DISTINCT FROM v_club_id
         OR v_prior.amount IS DISTINCT FROM p_amount
         OR v_prior.metadata->>'user_id' IS DISTINCT FROM p_user_id::text
         OR v_prior.category IS DISTINCT FROM 'horse_funding'
         OR v_prior.from_type IS DISTINCT FROM 'club_treasury'
         OR v_prior.to_type IS DISTINCT FROM 'table_stack' THEN
        RAISE EXCEPTION 'Horse funding identity reused with different payload'
          USING ERRCODE = '22023';
      END IF;
      RETURN jsonb_build_object(
        'success', true,
        'replayed', true,
        'op_id', p_op_id,
        'table_id', p_table_id,
        'user_id', p_user_id,
        'club_id', v_club_id,
        'amount', p_amount,
        'new_stack', v_prior.metadata->'new_stack',
        'treasury_after', v_prior.metadata->'treasury_after'
      );
    END IF;
  END IF;

  SELECT COALESCE(chip_treasury, 0)
    INTO v_treasury
    FROM public.clubs
   WHERE id = v_club_id
   FOR UPDATE;
  IF v_treasury IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'club not found');
  END IF;
  IF v_treasury < p_amount THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'insufficient club treasury',
      'treasury', v_treasury,
      'needed', p_amount
    );
  END IF;

  UPDATE public.table_seats
     SET stack = COALESCE(stack, 0) + p_amount
   WHERE table_id = p_table_id
     AND user_id = p_user_id
     AND left_at IS NULL
  RETURNING stack INTO v_new_stack;

  IF v_new_stack IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'no active seat for user at table'
    );
  END IF;

  PERFORM public.fn_cash_session_add_baseline(p_user_id, p_table_id, p_amount);

  PERFORM set_config('app.ledger_autoskip_clubs', '1', true);
  UPDATE public.clubs
     SET chip_treasury = COALESCE(chip_treasury, 0) - p_amount,
         updated_at = NOW()
   WHERE id = v_club_id;
  PERFORM set_config('app.ledger_autoskip_clubs', v_skip, true);

  INSERT INTO public.chip_transactions (
    id,
    club_id,
    from_user_id,
    to_user_id,
    amount,
    transaction_type,
    notes,
    balance_after,
    created_at
  ) VALUES (
    gen_random_uuid(),
    v_club_id,
    NULL,
    p_user_id,
    p_amount,
    'horse_treasury_funding',
    'Horse buy-in/rebuy funded from club treasury',
    v_treasury - p_amount,
    NOW()
  );

  BEGIN
    INSERT INTO public.chip_ledger (
      performed_by,
      from_type,
      from_entity_id,
      to_type,
      to_entity_id,
      amount,
      category,
      club_id,
      table_id,
      description,
      idempotency_key,
      metadata
    ) VALUES (
      COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
      'club_treasury',
      v_club_id,
      'table_stack',
      p_table_id,
      p_amount,
      'horse_funding',
      v_club_id,
      p_table_id,
      'Buy-in/rebuy funded from club treasury (fn_horse_fund_from_treasury) for '
        || p_user_id::text,
      CASE
        WHEN p_op_id IS NULL THEN NULL
        ELSE 'horse_fund:' || p_op_id::text
      END,
      jsonb_build_object(
        'user_id', p_user_id,
        'op_id', p_op_id,
        'door', 'fn_horse_fund_from_treasury',
        'new_stack', v_new_stack,
        'treasury_after', v_treasury - p_amount
      )
    );
  EXCEPTION WHEN OTHERS THEN
    -- A journal failure aborts the entire chip movement. Bare RAISE preserves
    -- the original SQLSTATE, DETAIL, HINT and context for the caller's retry.
    RAISE;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'new_stack', v_new_stack,
    'treasury_after', v_treasury - p_amount,
    'op_id', p_op_id,
    'table_id', p_table_id,
    'user_id', p_user_id,
    'club_id', v_club_id,
    'amount', p_amount
  );
END;
$$;


ALTER FUNCTION public.fn_horse_fund_from_treasury_before_maintenance_gate(p_table_id uuid, p_user_id uuid, p_amount numeric, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_horse_hash(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_hash(p_id text) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare h bigint := 0; i int;
begin
  for i in 1..length(p_id) loop
    h := (h * 31 + ascii(substr(p_id, i, 1))) % 4294967296;
  end loop;
  return h;
end $$;


ALTER FUNCTION public.fn_horse_hash(p_id text) OWNER TO postgres;

--
-- Name: fn_horse_hash_fnv(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_hash_fnv(p_id text) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare h bigint := 2166136261; i int;
begin
  for i in 1..length(p_id) loop
    h := (h # ascii(substr(p_id, i, 1)))::bigint;
    h := (h * 16777619) % 4294967296;
  end loop;
  return h;
end $$;


ALTER FUNCTION public.fn_horse_hash_fnv(p_id text) OWNER TO postgres;

--
-- Name: fn_horse_job_health(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_job_health(p_days integer DEFAULT 14) RETURNS TABLE(job text, run_date date, status text, claimed_by text, claimed_at timestamp with time zone, rows_produced bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH days AS (
    SELECT d::date AS run_date
      FROM generate_series(
             (now() AT TIME ZONE 'utc')::date - GREATEST(COALESCE(p_days, 14), 1),
             (now() AT TIME ZONE 'utc')::date - 1,
             interval '1 day') d
  ),
  jobs(job) AS (
    VALUES ('self_tuner'), ('daily_audit'), ('league'), ('league_pm'),
           ('claude_daily_analysis')
  ),
  expected AS (
    SELECT j.job, d.run_date FROM jobs j CROSS JOIN days d
  )
  SELECT e.job,
         e.run_date,
         CASE
           WHEN r.job IS NULL          THEN 'absent'
           WHEN COALESCE(v.n, 0) = 0   THEN 'hollow'
           ELSE 'ok'
         END AS status,
         r.claimed_by,
         r.claimed_at,
         COALESCE(v.n, 0) AS rows_produced
    FROM expected e
    LEFT JOIN public.horse_job_runs r
      ON r.job = e.job AND r.run_date = e.run_date
    LEFT JOIN LATERAL (
      SELECT CASE e.job
        WHEN 'self_tuner' THEN
          (SELECT count(*) FROM public.horse_self_tune_log l WHERE l.run_date = e.run_date)
        WHEN 'daily_audit' THEN
          (SELECT count(*) FROM public.horse_daily_audit a WHERE a.day = e.run_date)
        WHEN 'league' THEN
          (SELECT count(*) FROM public.horse_league_results g WHERE g.run_date = e.run_date)
        WHEN 'league_pm' THEN
          (SELECT count(*) FROM public.horse_league_results g WHERE g.run_date = e.run_date)
        WHEN 'claude_daily_analysis' THEN
          (SELECT count(*) FROM public.horse_daily_audit a
            WHERE a.day = e.run_date AND a.agent_analyzed_at IS NOT NULL)
        ELSE NULL
      END AS n
    ) v ON true
   ORDER BY e.run_date DESC, e.job;
$$;


ALTER FUNCTION public.fn_horse_job_health(p_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_horse_job_health(p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_horse_job_health(p_days integer) IS 'Every expected nightly horse job night, with status ok / hollow (claimed, produced nothing) / absent (never claimed - a dead scheduler, which iterating the claim table cannot see). Read-only; refuses nothing.';


--
-- Name: fn_horse_lane(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_lane(p_id text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when fn_horse_hash(p_id || ':lane') % 100 < 33 then 'events'
              when fn_horse_hash(p_id || ':lane') % 100 < 66 then 'cash'
              else 'both' end;
$$;


ALTER FUNCTION public.fn_horse_lane(p_id text) OWNER TO postgres;

--
-- Name: fn_horse_seat_from_treasury(uuid, uuid, integer, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_seat_from_treasury(p_table_id uuid, p_user_id uuid, p_seat_number integer, p_amount numeric, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_request jsonb;
  v_response jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);

  v_request := jsonb_build_object(
    'door', 'fn_horse_seat_from_treasury',
    'table_id', p_table_id,
    'user_id', p_user_id,
    'seat_number', p_seat_number,
    'amount', p_amount
  );
  v_response := public.fn_claim_entry_purchase_receipt(
    'horse_funding', p_op_id::text, v_request
  );
  IF NOT COALESCE((v_response->>'claimed')::boolean, false) THEN
    RETURN v_response->'response';
  END IF;

  IF p_op_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.chip_ledger l
     WHERE l.idempotency_key = 'horse_fund:' || p_op_id::text
  ) THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_RECEIPT_UNBOUND: this historical horse key has no exact response receipt'
      USING ERRCODE = '55000';
  END IF;

  IF public.fn_entry_purchases_frozen() THEN
    PERFORM public.fn_release_entry_purchase_claim(
      'horse_funding', p_op_id::text, v_request
    );
    RETURN jsonb_build_object(
      'success', false,
      'deferred', true,
      'error', 'PLATFORM_FROZEN: scheduled maintenance has deferred this horse seat'
    );
  END IF;
  PERFORM public.fn_assert_cash_chip_purchase_table(p_table_id);
  v_response := public.fn_horse_seat_from_treasury_before_maintenance_gate(
    p_table_id, p_user_id, p_seat_number, p_amount, p_op_id
  );
  IF NOT COALESCE((v_response->>'success')::boolean, false) THEN
    PERFORM public.fn_release_entry_purchase_claim(
      'horse_funding', p_op_id::text, v_request
    );
    RETURN v_response;
  END IF;
  RETURN public.fn_record_entry_purchase_receipt(
    'horse_funding', p_op_id::text, v_request, v_response
  );
END;
$$;


ALTER FUNCTION public.fn_horse_seat_from_treasury(p_table_id uuid, p_user_id uuid, p_seat_number integer, p_amount numeric, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_horse_seat_from_treasury_before_maintenance_gate(uuid, uuid, integer, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_seat_from_treasury_before_maintenance_gate(p_table_id uuid, p_user_id uuid, p_seat_number integer, p_amount numeric, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_club_id uuid;
  v_treasury numeric;
  v_st text;
  v_msg text;
  v_floor numeric;
  v_min numeric;
  v_max numeric;
  v_eff numeric;
BEGIN
  PERFORM set_config('app.money_path', 'fn_horse_seat_from_treasury', true); -- CHIP STANDARD C2: sanctioned seat creator (trg_ca_guard_seat_creation)
  IF p_table_id IS NULL OR p_user_id IS NULL OR p_seat_number IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'table, user, seat and positive amount required');
  END IF;

  /* A KEYED CALL IS ANSWERED ONCE. The engine funds a rebuy from a bust it
     has already seen; a retry after a lost response must not fund it twice.
     With no key this is the old behaviour exactly. */
  IF p_op_id IS NOT NULL AND EXISTS (
       SELECT 1 FROM public.chip_ledger WHERE idempotency_key = 'horse_fund:' || p_op_id::text) THEN
    RETURN jsonb_build_object('success', true, 'replayed', true, 'op_id', p_op_id);
  END IF;

  SELECT club_id, min_buy_in, max_buy_in INTO v_club_id, v_min, v_max FROM tables WHERE id = p_table_id;
  IF v_club_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'table has no club');
  END IF;

  IF NOT public.fn_actor_can_manage_club_treasury(v_club_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authorized to seat from club treasury');
  END IF;

  -- CHIP CONTINUITY (I7): the same floor a human meets at atomic_table_buyin.
  v_floor := public.fn_cash_rejoin_floor(p_user_id, p_table_id);
  IF v_floor IS NOT NULL THEN
    v_eff := GREATEST(COALESCE(v_min, 0), v_floor);
    IF v_max IS NOT NULL AND v_max > 0 THEN v_eff := LEAST(v_eff, v_max); END IF;
    IF p_amount < v_eff THEN
      RETURN jsonb_build_object('success', false, 'error', 'BUYIN_BELOW_FLOOR', 'required', v_eff);
    END IF;
  END IF;

  SELECT COALESCE(chip_treasury, 0) INTO v_treasury FROM clubs WHERE id = v_club_id FOR UPDATE;
  IF v_treasury IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'club not found');
  END IF;
  IF v_treasury < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient club treasury',
                              'treasury', v_treasury, 'needed', p_amount);
  END IF;

  BEGIN
    INSERT INTO table_seats (table_id, user_id, seat_number, stack, is_sitting_out)
    VALUES (p_table_id, p_user_id, p_seat_number, p_amount, false);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('success', false, 'error', 'seat already taken');
  END;

  -- CHIP CONTINUITY: the session opens with the seat, baseline = this buy-in.
  PERFORM public.fn_cash_session_open(p_user_id, p_table_id, p_amount);

  PERFORM set_config('app.ledger_autoskip_clubs', '1', true);
  UPDATE clubs SET chip_treasury = COALESCE(chip_treasury, 0) - p_amount, updated_at = NOW()
  WHERE id = v_club_id;
  PERFORM set_config('app.ledger_autoskip_clubs', '0', true);

  INSERT INTO chip_transactions (
    id, club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), v_club_id, NULL, p_user_id, p_amount,
    'horse_treasury_funding', 'Horse seated + funded from club treasury',
    v_treasury - p_amount, NOW()
  );

  BEGIN
    /* PHASE 7.2 (2026-09-06): the leg NAMES THE PLAYER and carries the
       caller's key when it has one. Before this a horse funding said only
       that a table was funded: 9,252 legs in seven days, none naming the
       seat, so no per-seat audit could read them and a replay could not be
       told from a second horse buying in for the same amount at the same
       table. The key is optional: without it nothing changes but the name. */
    INSERT INTO public.chip_ledger
      (performed_by, from_type, from_entity_id, to_type, to_entity_id,
       amount, category, club_id, table_id, description, idempotency_key, metadata)
    VALUES (
      COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
      'club_treasury', v_club_id,
      'table_stack',   p_table_id,
      p_amount, 'horse_funding', v_club_id, p_table_id,
      'Seated + funded from club treasury (fn_horse_seat_from_treasury) for ' || p_user_id::text,
      CASE WHEN p_op_id IS NULL THEN NULL ELSE 'horse_fund:' || p_op_id::text END,
      jsonb_build_object('user_id', p_user_id, 'op_id', p_op_id, 'door', 'fn_horse_seat_from_treasury'));
  EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;

  RETURN jsonb_build_object('success', true, 'treasury_after', v_treasury - p_amount);
END;
$$;


ALTER FUNCTION public.fn_horse_seat_from_treasury_before_maintenance_gate(p_table_id uuid, p_user_id uuid, p_seat_number integer, p_amount numeric, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_horse_solver_agreement_add(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_solver_agreement_add(p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r jsonb; n int := 0;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then return 0; end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    insert into horse_solver_agreement as t (run_date, reference, spots, agreement, pure_misses)
    values (
      (r->>'run_date')::date,
      coalesce(r->>'reference', 'gto_charts'),
      coalesce((r->>'spots')::int, 0),
      coalesce((r->>'agreement')::numeric, 0),
      coalesce((r->>'pure_misses')::int, 0)
    )
    on conflict (run_date, reference) do update set
      spots = excluded.spots,
      agreement = excluded.agreement,
      pure_misses = excluded.pure_misses,
      created_at = now();
    n := n + 1;
  end loop;
  return n;
end $$;


ALTER FUNCTION public.fn_horse_solver_agreement_add(p_rows jsonb) OWNER TO postgres;

--
-- Name: fn_horse_tag_ev(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_tag_ev(p_since date) RETURNS TABLE(situation text, mirrored boolean, hands bigint, won_hands bigint, net_bb numeric, bb_per_hand numeric, win_rate numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with flat as (
    select k as tag,
           (r.leak_counts->>k)::bigint               as cnt,
           coalesce((r.leak_net_bb->>k)::numeric, 0) as net
      from horse_review_rollup r, lateral jsonb_object_keys(r.leak_counts) k
     where r.day >= p_since
  ),
  agg as (
    select tag, sum(cnt)::bigint as cnt, sum(net) as net from flat group by tag
  ),
  paired as (
    select
      case
        when a.tag like '%\_won'  then left(a.tag, length(a.tag) - 4)
        when a.tag like '%\_lost' then left(a.tag, length(a.tag) - 5)
        else a.tag
      end                        as situation,
      a.tag like '%\_won'        as is_won,
      a.cnt, a.net
    from agg a
  )
  select p.situation,
         -- The fold family cannot have a mirror. Everything else does, whether
         -- or not it won this week.
         p.situation not in ('big_bet_fold','big_fold_river','big_fold_early','bet_fold_line')
                                                              as mirrored,
         sum(p.cnt)::bigint                                    as hands,
         coalesce(sum(p.cnt) filter (where p.is_won), 0)::bigint as won_hands,
         round(sum(p.net), 1)                                  as net_bb,
         round(sum(p.net) / nullif(sum(p.cnt), 0), 2)          as bb_per_hand,
         round(coalesce(sum(p.cnt) filter (where p.is_won), 0)::numeric
               / nullif(sum(p.cnt), 0), 3)                     as win_rate
    from paired p
   group by p.situation
  having sum(p.cnt) >= 100
   order by 6 asc;
$$;


ALTER FUNCTION public.fn_horse_tag_ev(p_since date) OWNER TO postgres;

--
-- Name: fn_horse_tag_trends(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_tag_trends(p_days integer DEFAULT 7) RETURNS TABLE(day date, tag text, n bigint, hands bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with days as (
    select played_at::date as day, count(*) as hands
    from horse_hand_reviews
    where played_at >= (now() at time zone 'utc')::date - p_days
    group by 1
  ),
  tags as (
    select played_at::date as day, t.tag, count(*) as n
    from horse_hand_reviews, lateral unnest(leak_tags) as t(tag)
    where played_at >= (now() at time zone 'utc')::date - p_days
    group by 1, 2
  )
  select t.day, t.tag, t.n, d.hands
  from tags t
  join days d using (day)
  order by t.day desc, t.n desc
$$;


ALTER FUNCTION public.fn_horse_tag_trends(p_days integer) OWNER TO postgres;

--
-- Name: fn_horse_tournament_daily_compile(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_tournament_daily_compile(p_day date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int;
begin
  with rows_ as (
    select tp.user_id as horse_user_id,
           p_day as day,
           coalesce(t.tournament_type, 'MTT') as tournament_type,
           coalesce(nullif(t.variant, ''), 'nlh') as variant,
           count(*) as entries,
           sum(coalesce(t.buy_in_amount, 0) + coalesce(t.buy_in_fee, 0)
               + coalesce(tp.rebuys, 0) * coalesce(t.rebuy_cost, 0)
               + case when tp.add_on then coalesce(t.addon_cost, 0) else 0 end) as invested,
           sum(coalesce(tp.prize, 0) + coalesce(tp.bounty_winnings, 0) + coalesce(tp.mystery_bounty_value, 0)) as won,
           count(*) filter (where coalesce(tp.prize, 0) + coalesce(tp.bounty_winnings, 0) + coalesce(tp.mystery_bounty_value, 0) > 0) as itm_entries,
           sum(case when tp.position is not null and coalesce(t.current_players, 0) > 1
                    then (tp.position - 1)::numeric / (t.current_players - 1) else 0 end) as finish_pct_sum,
           min(tp.position) as best_finish
      from tournament_players tp
      join tournaments t on t.id = tp.tournament_id
      join profiles p on p.id = tp.user_id and p.is_horse = true
     where t.status = 'COMPLETED'
       and t.ended_at >= p_day and t.ended_at < p_day + 1
       and tp.position is not null
     group by 1, 2, 3, 4
  )
  insert into horse_tournament_daily as h
    (horse_user_id, day, tournament_type, variant, entries, invested, won, itm_entries, finish_pct_sum, best_finish)
  select horse_user_id, day, tournament_type, variant, entries, invested, won, itm_entries, finish_pct_sum, best_finish
    from rows_
  on conflict (horse_user_id, day, tournament_type, variant) do update set
    entries = excluded.entries,
    invested = excluded.invested,
    won = excluded.won,
    itm_entries = excluded.itm_entries,
    finish_pct_sum = excluded.finish_pct_sum,
    best_finish = excluded.best_finish,
    updated_at = now();
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION public.fn_horse_tournament_daily_compile(p_day date) OWNER TO postgres;

--
-- Name: fn_horse_tournament_entry_ticket_hints(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_tournament_entry_ticket_hints(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_split record;
  v_is_bounty boolean;
  v_holder_ids jsonb;
BEGIN
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'tournament id is required' USING ERRCODE='22004';
  END IF;
  SELECT * INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id;
  IF v_t.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_not_found','holder_ids','[]'::jsonb);
  END IF;
  v_is_bounty:=COALESCE(v_t.is_bounty,false)
            OR COALESCE(v_t.is_pko,false)
            OR COALESCE(v_t.is_mystery_bounty,false);
  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_t.buy_in_amount,v_t.buy_in_fee,v_t.bounty_amount,v_is_bounty);
  IF v_split.charge IS NULL OR v_split.prize IS NULL
     OR v_split.bounty IS NULL OR v_split.rake IS NULL
     OR v_split.charge::text IN ('NaN','Infinity','-Infinity')
     OR v_split.prize::text IN ('NaN','Infinity','-Infinity')
     OR v_split.bounty::text IN ('NaN','Infinity','-Infinity')
     OR v_split.rake::text IN ('NaN','Infinity','-Infinity')
     OR v_split.charge<0 OR v_split.prize<0
     OR v_split.bounty<0 OR v_split.rake<0
     OR v_split.charge IS DISTINCT FROM
          round(v_split.prize+v_split.bounty+v_split.rake,2) THEN
    RAISE EXCEPTION 'tournament % has no finite ticket contract',p_tournament_id
      USING ERRCODE='P0404';
  END IF;
  IF v_split.charge=0 THEN
    RETURN jsonb_build_object('ok',true,'holder_ids','[]'::jsonb);
  END IF;

  SELECT COALESCE(jsonb_agg(candidate.holder_id ORDER BY candidate.holder_id),
                  '[]'::jsonb)
    INTO v_holder_ids
    FROM (
      SELECT DISTINCT tk.holder_id
        FROM public.tournament_tickets tk
        JOIN public.profiles p ON p.id=tk.holder_id
       WHERE COALESCE(p.is_horse,false)
         AND tk.status='issued'
         AND tk.redemption_mode='tournament_entry_only'
         AND tk.value=v_split.charge
         AND tk.entry_prize=v_split.prize
         AND tk.entry_bounty=v_split.bounty
         AND tk.entry_fee=v_split.rake
         AND EXISTS(
           SELECT 1 FROM public.club_members m
            WHERE m.club_id=tk.club_id AND m.user_id=tk.holder_id
              AND COALESCE(m.status,'active') IN ('active','approved'))
         AND (v_t.club_id IS NULL OR tk.club_id=v_t.club_id)
         AND (v_t.union_id IS NULL OR EXISTS(
           SELECT 1 FROM public.union_clubs uc
            WHERE uc.union_id=v_t.union_id AND uc.club_id=tk.club_id))
         AND public.fn_tournament_club_for_user(
               tk.holder_id,p_tournament_id,tk.club_id)
               IS NOT DISTINCT FROM tk.club_id
    ) candidate;
  RETURN jsonb_build_object('ok',true,'holder_ids',v_holder_ids);
END;
$$;


ALTER FUNCTION public.fn_horse_tournament_entry_ticket_hints(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_horse_tournament_leaks(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_tournament_leaks(p_since date) RETURNS TABLE(horse_user_id uuid, reviewed bigint, leak_counts jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with rv as (
    select r.horse_user_id, r.leak_tags
      from horse_hand_reviews r
     where r.format = 'tournament' and r.played_at >= p_since
  ),
  per as (
    select rv.horse_user_id, count(*) as reviewed from rv group by 1
  ),
  tags as (
    select rv.horse_user_id, u.tag, count(*) as n
      from rv, lateral unnest(rv.leak_tags) as u(tag)
     group by 1, 2
  )
  select per.horse_user_id, per.reviewed,
         coalesce((select jsonb_object_agg(tags.tag, tags.n) from tags where tags.horse_user_id = per.horse_user_id), '{}'::jsonb)
    from per;
$$;


ALTER FUNCTION public.fn_horse_tournament_leaks(p_since date) OWNER TO postgres;

--
-- Name: fn_horses_not_social_ready(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horses_not_social_ready() RETURNS TABLE(profile_id uuid, username text, missing text[])
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT p.id, p.username,
         array_remove(ARRAY[
           CASE WHEN ca.profile_id IS NULL THEN 'content_authors' END,
           CASE WHEN ca.profile_id IS NOT NULL AND NOT ca.is_active THEN 'is_active' END,
           CASE WHEN COALESCE(ca.voice,'') = '' THEN 'voice' END,
           CASE WHEN ca.personality IS NULL THEN 'personality' END,
           CASE WHEN COALESCE(ca.timezone,'') = '' THEN 'timezone' END,
           CASE WHEN COALESCE(p.bio,'') = '' THEN 'bio' END,
           CASE WHEN NOT COALESCE(p.social_profile_completed,false) THEN 'social_profile_completed' END,
           CASE WHEN p.avatar_url IS NULL THEN 'avatar_url' END
         ], NULL) AS missing
    FROM public.profiles p
    LEFT JOIN public.content_authors ca ON ca.profile_id = p.id
   WHERE p.is_horse
     AND (ca.profile_id IS NULL OR NOT ca.is_active OR COALESCE(ca.voice,'') = ''
          OR ca.personality IS NULL OR COALESCE(ca.timezone,'') = ''
          OR COALESCE(p.bio,'') = '' OR NOT COALESCE(p.social_profile_completed,false)
          OR p.avatar_url IS NULL);
$$;


ALTER FUNCTION public.fn_horses_not_social_ready() OWNER TO postgres;

--
-- Name: FUNCTION fn_horses_not_social_ready(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_horses_not_social_ready() IS 'Drift detector: horses missing any social credential. Expected empty; each row names what is missing.';


--
-- Name: fn_horses_without_social_identity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horses_without_social_identity() RETURNS TABLE(profile_id uuid, display_name text, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT p.id, p.display_name, p.created_at
    FROM public.profiles p
   WHERE p.is_horse
     AND NOT EXISTS (SELECT 1 FROM public.content_authors ca WHERE ca.profile_id = p.id)
   ORDER BY p.created_at DESC;
$$;


ALTER FUNCTION public.fn_horses_without_social_identity() OWNER TO postgres;

--
-- Name: FUNCTION fn_horses_without_social_identity(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_horses_without_social_identity() IS 'Horses that exist as poker players but not on the stable roster. Should always be empty; a non-empty result means a fleet build minted profiles without content_authors rows, which is how the panel read 756 against a fleet of 1,000 on 2026-09-01.';


--
-- Name: fn_hu_shortfall_candidates(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hu_shortfall_candidates(p_limit integer DEFAULT 100) RETURNS TABLE(tournament_id uuid, name text, ended_at timestamp with time zone, delta numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT t.id, t.name, t.ended_at, public.fn_tournament_conservation_delta(t.id)
    FROM public.tournaments t
   WHERE t.status = 'COMPLETED'
     AND COALESCE(t.variant, '') = 'sng'
     AND COALESCE(t.max_players, 0) <= 2
     AND COALESCE(t.guaranteed_prize, 0) = 0
     AND t.ended_at > now() - interval '30 days'
     AND t.ended_at < now() - interval '30 minutes'
     AND NOT EXISTS (
       SELECT 1 FROM public.wallet_transactions w
        WHERE w.related_entity_id = t.id
          AND w.type = 'credit' AND w.category = 'prize'
          AND w.description LIKE 'Heads-Up winner shortfall%')
     AND public.fn_tournament_conservation_delta(t.id) > 0.01
   ORDER BY t.ended_at ASC
   LIMIT GREATEST(COALESCE(p_limit, 100), 1);
$$;


ALTER FUNCTION public.fn_hu_shortfall_candidates(p_limit integer) OWNER TO postgres;

--
-- Name: fn_iap_settle_event(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_iap_settle_event(p_event jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_event_id   text := p_event ->> 'id';
  v_type       text := upper(COALESCE(p_event ->> 'type', ''));
  v_user_id    uuid;
  v_product_id text := p_event ->> 'product_id';
  v_txn        text := COALESCE(p_event ->> 'transaction_id', p_event ->> 'id');
  v_orig_txn   text := COALESCE(p_event ->> 'original_transaction_id', p_event ->> 'transaction_id', p_event ->> 'id');
  v_store      text := p_event ->> 'store';
  v_env        text := upper(COALESCE(p_event ->> 'environment', 'PRODUCTION'));
  v_price      numeric;
  v_expires    timestamptz;
  v_period_start timestamptz;
  v_product    public.iap_products%ROWTYPE;
  v_pkg        public.diamond_packages%ROWTYPE;
  v_purchase_id uuid;
  v_settle     jsonb;
  v_result     jsonb;
  v_profile    record;
  v_tier       text;
  v_effective_tier text;
  v_existing_ms bigint;
  v_new_ms     bigint;
  v_rank_existing int;
  v_rank_new   int;
  v_inserted   boolean := false;
BEGIN
  -- Service role only. This is a webhook consumer, never a browser call:
  -- REVOKEd from anon and authenticated below, and asked here as well so a
  -- future grant cannot quietly open it.
  IF COALESCE(auth.role(), current_user) NOT IN ('service_role', 'postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'fn_iap_settle_event: service role only (caller %)', COALESCE(auth.role(), current_user)
      USING ERRCODE = '42501';
  END IF;
  IF v_event_id IS NULL OR v_event_id = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'missing_event_id');
  END IF;
  -- Idempotency: the event id is the key. A replay returns what it returned.
  INSERT INTO public.iap_events (event_id, event_type, app_user_id, product_id, transaction_id,
                                 original_transaction_id, store, environment, raw)
  VALUES (v_event_id, v_type,
          CASE WHEN (p_event ->> 'app_user_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN (p_event ->> 'app_user_id')::uuid END,
          v_product_id, v_txn, v_orig_txn, v_store, v_env, p_event)
  ON CONFLICT (event_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF NOT v_inserted THEN
    SELECT COALESCE(result, jsonb_build_object('success', true, 'duplicate', true, 'pending', true))
      INTO v_result FROM public.iap_events WHERE event_id = v_event_id;
    RETURN v_result || jsonb_build_object('duplicate', true);
  END IF;
  SELECT app_user_id INTO v_user_id FROM public.iap_events WHERE event_id = v_event_id;
  -- Events that carry no settlement: recorded, acknowledged, nothing moves.
  IF v_type IN ('TEST', 'TRANSFER', 'SUBSCRIBER_ALIAS', 'SUBSCRIPTION_PAUSED', 'SUBSCRIPTION_EXTENDED', 'TEMPORARY_ENTITLEMENT_GRANT') THEN
    v_result := jsonb_build_object('success', true, 'ignored', true, 'reason', 'no_settlement_for_type', 'type', v_type);
    UPDATE public.iap_events SET processed_at = now(), result = v_result WHERE event_id = v_event_id;
    RETURN v_result;
  END IF;
  IF v_user_id IS NULL THEN
    v_result := jsonb_build_object('success', false, 'error', 'unknown_user', 'app_user_id', p_event ->> 'app_user_id');
    UPDATE public.iap_events SET processed_at = now(), result = v_result WHERE event_id = v_event_id;
    RETURN v_result;
  END IF;
  SELECT * INTO v_product FROM public.iap_products WHERE product_id = v_product_id;
  IF NOT FOUND THEN
    v_result := jsonb_build_object('success', false, 'error', 'unknown_product', 'product_id', v_product_id);
    UPDATE public.iap_events SET processed_at = now(), result = v_result WHERE event_id = v_event_id;
    BEGIN
      PERFORM public.fn_ca_diamond_incident('IAP:unknown_product', 'critical', v_user_id, 0,
        'fn_iap_settle_event', jsonb_build_object('event_id', v_event_id, 'product_id', v_product_id, 'type', v_type));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN v_result;
  END IF;
  v_price := COALESCE(NULLIF(p_event ->> 'price', '')::numeric, v_product.price_usd);
  -- Sandbox purchases settle (App Review buys diamonds and must receive them)
  -- and are logged, exactly as a Stripe test-mode session is (DR7, log-only).
  IF v_env <> 'PRODUCTION' THEN
    BEGIN
      PERFORM public.fn_ca_diamond_incident('IAP:sandbox_event_settled', 'warning', v_user_id, v_price,
        'fn_iap_settle_event', jsonb_build_object('event_id', v_event_id, 'environment', v_env,
          'product_id', v_product_id, 'type', v_type, 'store', v_store,
          'note', 'Store sandbox event settled into live balances. Log-only, as DR7 is for Stripe test mode.'));
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;
  -- ═══════════════════════ DIAMONDS (consumable) ═══════════════════════
  IF v_product.kind = 'diamonds' THEN
    IF v_type IN ('NON_RENEWING_PURCHASE', 'INITIAL_PURCHASE') THEN
      SELECT * INTO v_pkg FROM public.diamond_packages WHERE package_key = v_product.package_key;
      -- The purchase row for this transaction, created once.
      SELECT id INTO v_purchase_id FROM public.diamond_purchases
       WHERE metadata ->> 'iap_transaction_id' = v_txn;
      IF v_purchase_id IS NULL THEN
        INSERT INTO public.diamond_purchases (user_id, package_name, diamonds_amount, bonus_diamonds,
                                              price_usd, status, metadata)
        VALUES (v_user_id, v_pkg.display_name, v_pkg.diamonds, v_pkg.bonus_diamonds, v_pkg.price_usd, 'pending',
                jsonb_build_object('provider', 'iap', 'iap_transaction_id', v_txn,
                  'iap_original_transaction_id', v_orig_txn, 'iap_store', v_store,
                  'iap_environment', v_env, 'iap_product_id', v_product_id, 'iap_event_id', v_event_id,
                  'store_price', v_price))
        RETURNING id INTO v_purchase_id;
      END IF;
      -- THE SAME SETTLEMENT A CARD PURCHASE GETS. Idempotent on the purchase
      -- id inside; a replay of the transaction returns duplicate:true.
      v_settle := public.settle_diamond_card_purchase_atomic(v_purchase_id, 'iap:' || v_txn, 'iap:' || v_orig_txn);
      v_result := jsonb_build_object('success', COALESCE((v_settle ->> 'success')::boolean, false),
                                     'kind', 'diamonds', 'purchase_id', v_purchase_id, 'settlement', v_settle);
    ELSIF v_type IN ('CANCELLATION', 'REFUND', 'REFUND_REVERSED') THEN
      -- The store has already refunded the customer. Nothing is taken back
      -- (10.9 rule 3); a human is told.
      SELECT id INTO v_purchase_id FROM public.diamond_purchases WHERE metadata ->> 'iap_transaction_id' = v_txn;
      BEGIN
        PERFORM public.fn_ca_diamond_incident('IAP:diamond_refund_received', 'warning', v_user_id, v_price,
          'fn_iap_settle_event', jsonb_build_object('event_id', v_event_id, 'type', v_type,
            'purchase_id', v_purchase_id, 'transaction_id', v_txn, 'store', v_store,
            'note', 'Store refunded a diamond purchase. Diamonds are not clawed back (10.9 rule 3). Review by hand.'));
      EXCEPTION WHEN OTHERS THEN NULL; END;
      IF v_purchase_id IS NOT NULL THEN
        UPDATE public.diamond_purchases
           SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('iap_refund_event_id', v_event_id,
                 'iap_refund_type', v_type, 'iap_refund_at', now()),
               updated_at = now()
         WHERE id = v_purchase_id;
      END IF;
      v_result := jsonb_build_object('success', true, 'kind', 'diamonds', 'refund_noted', true, 'purchase_id', v_purchase_id);
    ELSE
      v_result := jsonb_build_object('success', true, 'ignored', true, 'kind', 'diamonds', 'reason', 'no_settlement_for_type', 'type', v_type);
    END IF;
  -- ═══════════════════════ VIP (auto-renewing) ═══════════════════════
  ELSE
    v_tier := v_product.vip_tier;   -- 'monthly' | 'yearly'
    v_expires := CASE WHEN (p_event ->> 'expiration_at_ms') ~ '^[0-9]+$'
                      THEN to_timestamp((p_event ->> 'expiration_at_ms')::bigint / 1000.0) END;
    v_period_start := CASE WHEN (p_event ->> 'purchased_at_ms') ~ '^[0-9]+$'
                           THEN to_timestamp((p_event ->> 'purchased_at_ms')::bigint / 1000.0) ELSE now() END;
    SELECT id, vip_tier, vip_expires_at, is_vip INTO v_profile FROM public.profiles WHERE id = v_user_id FOR UPDATE;
    IF NOT FOUND THEN
      v_result := jsonb_build_object('success', false, 'error', 'profile_not_found');
      UPDATE public.iap_events SET processed_at = now(), result = v_result WHERE event_id = v_event_id;
      RETURN v_result;
    END IF;
    IF v_type IN ('INITIAL_PURCHASE', 'RENEWAL', 'UNCANCELLATION', 'PRODUCT_CHANGE', 'NON_RENEWING_PURCHASE') THEN
      IF v_expires IS NULL THEN
        v_expires := v_period_start + CASE WHEN v_tier = 'yearly' THEN interval '1 year' ELSE interval '1 month' END;
      END IF;
      -- The Stripe webhook's rules, verbatim in intent: lifetime is never
      -- downgraded; a longer prepaid expiry on a higher tier is never shortened.
      v_existing_ms := CASE WHEN v_profile.vip_expires_at IS NULL THEN 0
                            ELSE (extract(epoch FROM v_profile.vip_expires_at) * 1000)::bigint END;
      v_new_ms := (extract(epoch FROM v_expires) * 1000)::bigint;
      v_rank_existing := CASE v_profile.vip_tier WHEN 'daily' THEN 1 WHEN 'monthly' THEN 2
                              WHEN 'annual' THEN 3 WHEN 'yearly' THEN 3 WHEN 'lifetime' THEN 4 ELSE 0 END;
      v_rank_new := CASE v_tier WHEN 'monthly' THEN 2 WHEN 'yearly' THEN 3 ELSE 0 END;
      IF v_profile.vip_tier = 'lifetime' THEN
        v_effective_tier := 'lifetime';
        UPDATE public.profiles SET is_vip = true, updated_at = now() WHERE id = v_user_id;
      ELSIF v_existing_ms > v_new_ms AND v_rank_existing > v_rank_new THEN
        v_effective_tier := v_profile.vip_tier;
        UPDATE public.profiles SET is_vip = true, updated_at = now() WHERE id = v_user_id;
      ELSE
        v_effective_tier := v_tier;
        UPDATE public.profiles
           SET is_vip = true, vip_tier = v_tier, vip_expires_at = v_expires, updated_at = now()
         WHERE id = v_user_id;
      END IF;
      INSERT INTO public.vip_subscriptions (user_id, stripe_subscription_id, plan, tier, status, price_usd,
                                            current_period_start, current_period_end, cancel_at_period_end, updated_at)
      VALUES (v_user_id, 'iap:' || v_orig_txn, v_tier, v_tier, 'active', v_price,
              v_period_start, v_expires, false, now())
      ON CONFLICT (user_id) DO UPDATE
        SET stripe_subscription_id = EXCLUDED.stripe_subscription_id, plan = EXCLUDED.plan, tier = EXCLUDED.tier,
            status = 'active', price_usd = EXCLUDED.price_usd,
            current_period_start = EXCLUDED.current_period_start, current_period_end = EXCLUDED.current_period_end,
            cancel_at_period_end = false, canceled_at = NULL, updated_at = now();
      v_result := jsonb_build_object('success', true, 'kind', 'vip', 'tier', v_effective_tier, 'expires_at', v_expires);
    ELSIF v_type = 'CANCELLATION' THEN
      -- Auto-renew turned off. Access runs to the paid-through date.
      UPDATE public.vip_subscriptions
         SET cancel_at_period_end = true, canceled_at = now(),
             cancel_reason = COALESCE(p_event ->> 'cancel_reason', cancel_reason), updated_at = now()
       WHERE user_id = v_user_id AND stripe_subscription_id = 'iap:' || v_orig_txn;
      v_result := jsonb_build_object('success', true, 'kind', 'vip', 'cancel_at_period_end', true);
    ELSIF v_type IN ('EXPIRATION') THEN
      UPDATE public.vip_subscriptions
         SET status = 'canceled', canceled_at = COALESCE(canceled_at, now()), updated_at = now()
       WHERE user_id = v_user_id AND stripe_subscription_id = 'iap:' || v_orig_txn;
      IF v_profile.vip_tier IS DISTINCT FROM 'lifetime'
         AND (v_profile.vip_expires_at IS NULL OR v_profile.vip_expires_at <= now()) THEN
        UPDATE public.profiles SET is_vip = false, updated_at = now() WHERE id = v_user_id;
        v_result := jsonb_build_object('success', true, 'kind', 'vip', 'expired', true, 'is_vip', false);
      ELSE
        v_result := jsonb_build_object('success', true, 'kind', 'vip', 'expired', true, 'is_vip', true,
                                       'reason', 'other_coverage_still_active');
      END IF;
    ELSIF v_type = 'BILLING_ISSUE' THEN
      UPDATE public.vip_subscriptions SET status = 'past_due', updated_at = now()
       WHERE user_id = v_user_id AND stripe_subscription_id = 'iap:' || v_orig_txn;
      v_result := jsonb_build_object('success', true, 'kind', 'vip', 'past_due', true);
    ELSE
      v_result := jsonb_build_object('success', true, 'ignored', true, 'kind', 'vip', 'reason', 'no_settlement_for_type', 'type', v_type);
    END IF;
  END IF;
  UPDATE public.iap_events SET processed_at = now(), result = v_result WHERE event_id = v_event_id;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION public.fn_iap_settle_event(p_event jsonb) OWNER TO postgres;

