COMMENT ON FUNCTION public.fn_iap_settle_event(p_event jsonb) IS 'Store-billing webhook consumer (RevenueCat). Service role only. Diamonds settle through settle_diamond_card_purchase_atomic keyed iap:<transaction>; VIP applies the Stripe webhook''s tier/expiry rules. Idempotent on the event id.';


--
-- Name: fn_idempotency_begin(text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_idempotency_begin(p_key text, p_route text, p_ttl_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row api_idempotency;
BEGIN
  IF p_key IS NULL OR length(p_key) < 8 THEN
    RETURN jsonb_build_object('claimed', false, 'state', 'invalid');
  END IF;

  -- Opportunistic sweep; cheap and keeps the table from growing unbounded.
  DELETE FROM api_idempotency WHERE expires_at < now();

  INSERT INTO api_idempotency (key, route, state, expires_at)
  VALUES (p_key, p_route, 'processing', now() + make_interval(secs => GREATEST(1, p_ttl_seconds)))
  ON CONFLICT (key) DO NOTHING;

  IF FOUND THEN
    RETURN jsonb_build_object('claimed', true);
  END IF;

  SELECT * INTO v_row FROM api_idempotency WHERE key = p_key;

  IF NOT FOUND THEN
    -- Swept between the INSERT and the SELECT; treat as a fresh claim.
    RETURN jsonb_build_object('claimed', true);
  END IF;

  IF v_row.state = 'done' THEN
    RETURN jsonb_build_object('claimed', false, 'state', 'done',
                              'status', v_row.status, 'body', v_row.body);
  END IF;

  RETURN jsonb_build_object('claimed', false, 'state', 'processing');
END;
$$;


ALTER FUNCTION public.fn_idempotency_begin(p_key text, p_route text, p_ttl_seconds integer) OWNER TO postgres;

--
-- Name: fn_idempotency_finish(text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_idempotency_finish(p_key text, p_status integer, p_body jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_key IS NULL THEN RETURN; END IF;

  -- Never cache a 5xx: a transient failure would be replayed as a permanent
  -- one for the whole TTL, over an operation that may well have committed.
  IF p_status >= 500 THEN
    DELETE FROM api_idempotency WHERE key = p_key;
    RETURN;
  END IF;

  UPDATE api_idempotency
     SET state = 'done', status = p_status, body = p_body
   WHERE key = p_key;
END;
$$;


ALTER FUNCTION public.fn_idempotency_finish(p_key text, p_status integer, p_body jsonb) OWNER TO postgres;

--
-- Name: fn_idempotent_credit_wallet(text, uuid, numeric, text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_idempotent_credit_wallet(p_idempotency_key text, p_user_id uuid, p_amount numeric, p_category text, p_description text, p_table_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_related_entity_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claimed BOOLEAN;
  v_cached  JSONB;
  v_status  TEXT;
  v_result  BOOLEAN;
BEGIN
  SELECT claimed, cached_result, cached_status
    INTO v_claimed, v_cached, v_status
    FROM public.claim_idempotency_key(p_idempotency_key, 'atomic_credit_wallet_and_log');

  IF NOT v_claimed THEN
    IF v_status = 'completed' THEN
      RETURN v_cached;
    ELSIF v_status = 'in_flight' THEN
      RAISE EXCEPTION 'idempotency key % already in flight (concurrent duplicate request)', p_idempotency_key;
    ELSE
      RETURN v_cached;  -- errored: return prior error payload
    END IF;
  END IF;

  BEGIN
    v_result := public.atomic_credit_wallet_and_log(
      p_user_id, p_amount, p_category, p_description,
      p_table_id, p_hand_id, p_related_entity_id
    );
    PERFORM public.store_idempotency_result(
      p_idempotency_key,
      jsonb_build_object('ok', v_result, 'rpc', 'atomic_credit_wallet_and_log')
    );
    RETURN jsonb_build_object('ok', v_result, 'rpc', 'atomic_credit_wallet_and_log');
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.store_idempotency_result(
      p_idempotency_key,
      jsonb_build_object('ok', false, 'rpc', 'atomic_credit_wallet_and_log'),
      SQLERRM
    );
    RAISE;
  END;
END;
$$;


