--
-- Name: fn_increment_agent_player_count(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_increment_agent_player_count(p_agent_user_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_increment integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_agent_user_id is null then return; end if;
  update agents
     set total_players = greatest(0, coalesce(total_players, 0) + p_increment),
         active_player_count = greatest(0, coalesce(active_player_count, 0) + p_increment),
         updated_at = now()
   where user_id = p_agent_user_id
     and (p_club_id is null or club_id = p_club_id);
end $$;


ALTER FUNCTION public.fn_increment_agent_player_count(p_agent_user_id uuid, p_club_id uuid, p_increment integer) OWNER TO postgres;

--
-- Name: fn_increment_club_member_count(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_increment_club_member_count(p_club_id uuid DEFAULT NULL::uuid, p_increment integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_club_id IS NULL THEN RETURN; END IF;
  UPDATE public.clubs
     SET member_count = GREATEST(0, COALESCE(member_count,0) + p_increment),
         updated_at = NOW()
   WHERE id = p_club_id;
END $$;


ALTER FUNCTION public.fn_increment_club_member_count(p_club_id uuid, p_increment integer) OWNER TO postgres;

--
-- Name: fn_increment_vip_usage(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_increment_vip_usage(p_user_id uuid, p_feature text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND (auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_user_id) THEN
    RAISE EXCEPTION 'Cannot record VIP usage for another user';
  END IF;

  INSERT INTO public.vip_feature_usage (user_id, feature, usage_count, daily_usage, last_used_at, last_reset_at)
  VALUES (p_user_id, p_feature, 1, 1, now(), (now() AT TIME ZONE 'UTC')::date)
  ON CONFLICT (user_id, feature) DO UPDATE
     SET usage_count  = vip_feature_usage.usage_count + 1,
         daily_usage  = CASE WHEN vip_feature_usage.last_reset_at < (now() AT TIME ZONE 'UTC')::date
                             THEN 1 ELSE vip_feature_usage.daily_usage + 1 END,
         last_reset_at = GREATEST(vip_feature_usage.last_reset_at, (now() AT TIME ZONE 'UTC')::date),
         last_used_at  = now();

  INSERT INTO public.vip_feature_usage_monthly (user_id, feature, month, usage_count, updated_at)
  VALUES (p_user_id, p_feature, to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM'), 1, now())
  ON CONFLICT (user_id, feature, month) DO UPDATE
     SET usage_count = vip_feature_usage_monthly.usage_count + 1,
         updated_at  = now();
END;
$$;


ALTER FUNCTION public.fn_increment_vip_usage(p_user_id uuid, p_feature text) OWNER TO postgres;

--
-- Name: fn_infer_video_topic(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_infer_video_topic(p_metadata jsonb, p_topics text[]) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    -- The content collectors' explicit classifier is the strongest historical
    -- evidence and takes precedence over every source-name fallback.
    WHEN lower(btrim(COALESCE(p_metadata ->> 'clip_type', ''))) = 'poker'
      THEN 'poker'
    WHEN lower(btrim(COALESCE(p_metadata ->> 'clip_type', ''))) = 'sports'
      THEN 'sports'
    WHEN upper(btrim(COALESCE(
      p_metadata ->> 'source',
      p_metadata ->> 'source_id',
      ''
    ))) IN (
      'HCL', 'TCH', 'LATB', 'POKERGO', 'HELLMUTH', 'POLK', 'WOLFGANG',
      'MARIANO', 'JLITTLE', 'NEEME', 'BRAD', 'WPT', 'RAMPAGE', 'LODGE',
      'EPT', 'DANIEL', 'WSOP', 'TRITON'
    ) THEN 'poker'
    WHEN upper(btrim(COALESCE(
      p_metadata ->> 'source',
      p_metadata ->> 'source_id',
      ''
    ))) IN (
      'BLEACHER REPORT NBA', 'WARRIORS', 'LAKERS', 'CELTICS', 'BUCKS',
      'HEAT', 'HOUSE OF HIGHLIGHTS', 'NBA', 'ESPN NBA'
    ) THEN 'sports'
    WHEN EXISTS (
      SELECT 1
      FROM unnest(COALESCE(p_topics, ARRAY[]::text[])) AS supplied_topic(value)
      WHERE lower(supplied_topic.value) IN ('poker', 'cash', 'tournament')
    ) THEN 'poker'
    WHEN EXISTS (
      SELECT 1
      FROM unnest(COALESCE(p_topics, ARRAY[]::text[])) AS supplied_topic(value)
      WHERE lower(supplied_topic.value) = 'sports'
    ) THEN 'sports'
    ELSE 'unknown'
  END
$$;


ALTER FUNCTION public.fn_infer_video_topic(p_metadata jsonb, p_topics text[]) OWNER TO postgres;

--
-- Name: FUNCTION fn_infer_video_topic(p_metadata jsonb, p_topics text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_infer_video_topic(p_metadata jsonb, p_topics text[]) IS 'Conservatively classifies historical video metadata as poker/sports; missing or unrecognized evidence remains unknown.';


--
-- Name: fn_is_agent_ancestor(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_is_agent_ancestor(p_ancestor_user_id uuid, p_descendant_user_id uuid, p_club_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH RECURSIVE up AS (
    SELECT a.id, a.user_id, a.parent_agent_id
      FROM agents a
     WHERE a.user_id = p_descendant_user_id
       AND (p_club_id IS NULL OR a.club_id = p_club_id)
    UNION ALL
    SELECT p.id, p.user_id, p.parent_agent_id
      FROM agents p JOIN up ON up.parent_agent_id = p.id
  )
  SELECT EXISTS (SELECT 1 FROM up WHERE up.user_id = p_ancestor_user_id
                                    AND up.user_id <> p_descendant_user_id);
$$;


ALTER FUNCTION public.fn_is_agent_ancestor(p_ancestor_user_id uuid, p_descendant_user_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_is_agent_of_player(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_is_agent_of_player(p_agent_user_id uuid, p_player_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_agent_user_id IS NOT NULL AND p_player_user_id IS NOT NULL AND (
    EXISTS (SELECT 1 FROM club_members m
             WHERE m.user_id = p_player_user_id AND m.agent_id = p_agent_user_id)
    OR EXISTS (SELECT 1 FROM player_agent_assignments pa
                JOIN agents a ON a.id = pa.agent_id
               WHERE pa.player_id = p_player_user_id AND a.user_id = p_agent_user_id)
    -- super-agent sees the rosters of the agents beneath them
    OR EXISTS (SELECT 1 FROM club_members m
                JOIN agents child ON child.user_id = m.agent_id
                JOIN agents parent ON parent.id = child.parent_agent_id
               WHERE m.user_id = p_player_user_id AND parent.user_id = p_agent_user_id)
  );
$$;


ALTER FUNCTION public.fn_is_agent_of_player(p_agent_user_id uuid, p_player_user_id uuid) OWNER TO postgres;

--
-- Name: fn_is_any_union_overseer(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_is_any_union_overseer(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_user_id IS NOT NULL AND (
       EXISTS (SELECT 1 FROM unions u WHERE u.owner_id = p_user_id)
    OR EXISTS (SELECT 1 FROM union_admins a WHERE a.user_id = p_user_id)
    OR EXISTS (SELECT 1 FROM clubs c
                WHERE COALESCE(c.is_union, false) AND c.owner_id = p_user_id)
    OR EXISTS (SELECT 1 FROM club_members m
                JOIN clubs c2 ON c2.id = m.club_id AND COALESCE(c2.is_union, false)
               WHERE m.user_id = p_user_id AND m.role IN ('owner','co_owner','admin')
                 AND m.status IN ('active','approved'))
  );
$$;


