--
-- Name: fn_is_safe_url(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_is_safe_url(p_url text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
DECLARE
    v_host text;
    v_ip inet;
BEGIN
    -- Null / empty → fine (means "no image")
    IF p_url IS NULL OR p_url = '' THEN
        RETURN true;
    END IF;

    -- Protocol-relative //host/... is ambiguous in email/HTML contexts. Reject.
    IF p_url ~ '^//' THEN
        RETURN false;
    END IF;

    -- Relative absolute path: /foo/bar → Next.js public/ asset, allow
    IF p_url ~ '^/[^/]' THEN
        RETURN true;
    END IF;

    -- Must be https:// (prefer TLS; allow http:// too for dev origins that
    -- also satisfy the host check below - typical prod traffic is https only)
    IF p_url !~* '^https?://' THEN
        RETURN false;
    END IF;

    -- Extract host (everything after scheme://, stopping at /?#:)
    v_host := lower(substring(p_url from '^https?://([^/?#:]+)'));
    IF v_host IS NULL OR v_host = '' THEN
        RETURN false;
    END IF;

    -- Known dangerous / unhelpful hosts
    IF v_host IN ('localhost', '0.0.0.0', '[::1]') THEN
        RETURN false;
    END IF;

    -- IP-literal host: parse as inet and check CIDRs
    BEGIN
        v_ip := v_host::inet;
        IF v_ip <<= '127.0.0.0/8'::inet THEN RETURN false; END IF;
        IF v_ip <<= '10.0.0.0/8'::inet THEN RETURN false; END IF;
        IF v_ip <<= '172.16.0.0/12'::inet THEN RETURN false; END IF;
        IF v_ip <<= '192.168.0.0/16'::inet THEN RETURN false; END IF;
        IF v_ip <<= '169.254.0.0/16'::inet THEN RETURN false; END IF;
        IF v_ip <<= '0.0.0.0/8'::inet THEN RETURN false; END IF;
        IF v_ip <<= '::1/128'::inet THEN RETURN false; END IF;
        IF v_ip <<= 'fc00::/7'::inet THEN RETURN false; END IF;
        IF v_ip <<= 'fe80::/10'::inet THEN RETURN false; END IF;
        -- Public IP literal → allow
        RETURN true;
    EXCEPTION WHEN OTHERS THEN
        -- Not a parseable IP → it's a hostname, fall through to hostname checks
        NULL;
    END;

    -- Hostname must have at least one dot (reject "intranet", "printer", etc.)
    IF position('.' in v_host) = 0 THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$;


ALTER FUNCTION public.fn_is_safe_url(p_url text) OWNER TO postgres;

--
-- Name: FUNCTION fn_is_safe_url(p_url text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_is_safe_url(p_url text) IS 'phase40: validates image/video URLs. Blocks SSRF-friendly schemes (javascript:/data:/file:/about:), private/loopback IPs, and internal hostnames. NULL and empty pass through. Relative /paths pass through. See phase40_url_safety_validator migration.';


--
-- Name: fn_is_service_context(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_is_service_context() RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    v_raw_claims text;
    v_jwt_role   text;
BEGIN
    v_raw_claims := current_setting('request.jwt.claims', true);

    IF v_raw_claims IS NOT NULL
       AND btrim(v_raw_claims) <> ''
       AND btrim(v_raw_claims) <> 'null'
    THEN
        BEGIN
            v_jwt_role := v_raw_claims::jsonb ->> 'role';
        EXCEPTION WHEN others THEN
            -- Unparseable claims: fail CLOSED. A malformed JWT must never be
            -- mistaken for "no JWT".
            RETURN false;
        END;

        RETURN v_jwt_role = 'service_role';
    END IF;

    -- No JWT context.
    IF current_user IN ('anon', 'authenticated') THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$$;


ALTER FUNCTION public.fn_is_service_context() OWNER TO postgres;

--
-- Name: FUNCTION fn_is_service_context(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_is_service_context() IS 'True when the current statement runs with service_role / superuser authority, or with no JWT context at all (migrations, cron). Fails closed on malformed JWT claims.';


