--
-- Name: fn_is_unsafe_url(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_is_unsafe_url(p_url text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_host text;
BEGIN
    -- NULL / empty → safe (means no image set)
    IF p_url IS NULL OR length(btrim(p_url)) = 0 THEN
        RETURN false;
    END IF;

    -- 2 KiB cap to keep logs/queries sane
    IF length(p_url) > 2048 THEN
        RETURN true;
    END IF;

    -- Reject NULs + control chars (incl. \r \n \t \b etc)
    IF p_url ~ '[\x00-\x1F\x7F]' THEN
        RETURN true;
    END IF;

    -- Protocol-relative //host/... is ambiguous outside HTML and not needed.
    -- Reject before the relative-path check below.
    IF p_url ~ '^//' THEN
        RETURN true;
    END IF;

    -- Relative absolute path (e.g. "/smarter-poker-logo.png") is SAFE.
    -- Cannot cause SSRF (not a fetchable URL) and resolves same-origin in <img>.
    IF p_url ~ '^/[^/]' THEN
        RETURN false;
    END IF;

    -- Require http:// or https:// explicitly
    IF NOT (p_url ~* '^https?://') THEN
        RETURN true;
    END IF;

    -- Extract hostname; strip userinfo (user:pass@) if present
    v_host := lower(regexp_replace(p_url, '^https?://(?:[^@/]+@)?([^/?#:]+).*$', '\1', 'i'));

    -- localhost + no-dot hostnames (covers 'localhost', 'admin', 'intranet', etc.)
    IF v_host = 'localhost' OR v_host NOT LIKE '%.%' THEN
        RETURN true;
    END IF;

    -- IPv4 private / reserved ranges
    IF v_host ~ '^(127\.|10\.|0\.|169\.254\.|192\.168\.)' THEN
        RETURN true;
    END IF;
    IF v_host ~ '^172\.(1[6-9]|2[0-9]|3[0-1])\.' THEN
        RETURN true;
    END IF;

    -- IPv6 loopback / unique-local / link-local
    IF v_host ~ '^\[?(::1|::|fc[0-9a-f]{2}:|fd[0-9a-f]{2}:|fe[89ab][0-9a-f]:)' THEN
        RETURN true;
    END IF;

    -- Clean
    RETURN false;
END;
$_$;


ALTER FUNCTION public.fn_is_unsafe_url(p_url text) OWNER TO postgres;

--
-- Name: FUNCTION fn_is_unsafe_url(p_url text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_is_unsafe_url(p_url text) IS 'phase40: URL safety validator used by trg_validate_home_url_fields triggers on profiles + commander_home_* tables. Returns true if URL is unsafe. Rejects: >2KB, control chars, schemes other than http(s):, protocol-relative, localhost, single-label hosts, private/reserved IPv4, IPv6 loopback/ULA/link-local. Allows: NULL/empty, relative /paths, public http(s) hosts.';


--
-- Name: fn_is_user_video_storage_url(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_is_user_video_storage_url(p_url text, p_author_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
  WITH parsed AS (
    SELECT CASE
      WHEN public.fn_is_platform_public_storage_url(p_url)
       AND p_url !~ '[?#]'
      THEN split_part(split_part(
        substring(p_url FROM '^https://[^/]+/storage/v1/object/public/(.*)$'),
        '?', 1
      ), '#', 1)
      ELSE NULL
    END AS object_ref
  ), object_identity AS (
    SELECT split_part(object_ref, '/', 1) AS bucket_id,
           substring(object_ref FROM position('/' IN object_ref) + 1) AS object_name
    FROM parsed
    WHERE object_ref IS NOT NULL
      AND position('/' IN object_ref) > 0
  )
  SELECT p_author_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM object_identity parsed_object
    JOIN storage.objects stored_object
      ON stored_object.bucket_id = parsed_object.bucket_id
     AND stored_object.name = parsed_object.object_name
    WHERE stored_object.archived_at IS NULL
      AND COALESCE(stored_object.is_delete_marker, false) IS FALSE
      AND COALESCE(stored_object.metadata ->> 'mimetype', '') LIKE 'video/%'
      -- Public playback clients intentionally accept exactly one filename
      -- below the author directory. Match that contract here so a nested
      -- object cannot be published successfully and then disappear from every
      -- feed as untrusted. Reject an encoded slash for the same reason.
      AND parsed_object.object_name !~* '%2f'
      AND (
        (
          parsed_object.bucket_id = 'social-media'
          AND (
            parsed_object.object_name ~
              ('^reels/' || p_author_id::text || '/[^/]+$')
            OR parsed_object.object_name ~
              ('^videos/' || p_author_id::text || '/[^/]+$')
          )
        )
        OR (
          parsed_object.bucket_id = 'stories'
          AND parsed_object.object_name ~
            ('^stories/' || p_author_id::text || '/[^/]+$')
        )
        OR (
          parsed_object.bucket_id = 'live-recordings'
          AND parsed_object.object_name ~
            ('^' || p_author_id::text || '/[^/]+$')
        )
      )
  )
$_$;


