--
-- Name: fn_issue_tournament_ticket(uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_issue_tournament_ticket(p_club_id uuid, p_holder_id uuid, p_value numeric, p_note text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    return jsonb_build_object('success',false,'error','Not Authenticated');
  end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null then
    return jsonb_build_object('success',false,'error','A Retry Key Is Required For Every Ticket');
  end if;
  return public.fn_issue_tournament_ticket_phase2_core_20260831(
    p_club_id,p_holder_id,p_value,p_note,p_idempotency_key
  );
end
$$;


ALTER FUNCTION public.fn_issue_tournament_ticket(p_club_id uuid, p_holder_id uuid, p_value numeric, p_note text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: fn_issue_tournament_ticket_phase2_core_20260831(uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_issue_tournament_ticket_phase2_core_20260831(p_club_id uuid, p_holder_id uuid, p_value numeric, p_note text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
  v_role text;
  v_holder_role text;
  v_after numeric;
  v_context jsonb;
  v_setting text;
  v_key text := nullif(btrim(coalesce(p_idempotency_key,'')),'');
  v_note text := nullif(btrim(coalesce(p_note,'')),'');
  v_prior record;
  v_ticket_id uuid;
  v_first uuid;
  v_second uuid;
begin
  if v_me is null then return jsonb_build_object('success',false,'error','Not Authenticated'); end if;
  if p_club_id is null or p_holder_id is null or p_holder_id=v_me then
    return jsonb_build_object('success',false,'error','Choose Another Active Member');
  end if;
  if p_value is null or p_value <= 0 or p_value > 1e9 or p_value <> round(p_value,2) then
    return jsonb_build_object('success',false,'error','Enter A Valid Ticket Value');
  end if;

  perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||p_club_id::text,0));

  if v_key is not null then
    perform pg_advisory_xact_lock(hashtextextended('ticket:'||v_key,0));
    select ct.* into v_prior from public.chip_transactions ct
     where ct.metadata->>'idempotency_key'=v_key limit 1;
    if found then
      if v_prior.transaction_type <> 'tournament_ticket_issue'
         and not (v_prior.transaction_type='peer_transfer'
                  and v_prior.notes ilike 'Tournament ticket issued%') then
        return jsonb_build_object('success',false,'error','That Retry Key Is Already In Use');
      end if;
      if v_prior.club_id is distinct from p_club_id
         or v_prior.from_user_id is distinct from v_me
         or v_prior.to_user_id is distinct from p_holder_id
         or v_prior.amount is distinct from p_value
         or (v_prior.metadata ? 'note'
             and coalesce(v_prior.metadata->>'note','') is distinct from coalesce(v_note,'')) then
        return jsonb_build_object('success',false,'error','That Retry Key Belongs To A Different Ticket');
      end if;
      return jsonb_build_object('success',true,'replayed',true,
        'ticket_id',v_prior.metadata->>'ticket_id',
        'your_balance',(v_prior.metadata->>'issuer_balance_after')::numeric);
    end if;
  end if;

  -- Lock both memberships in deterministic order, then re-check every role and
  -- downline rule while the rows cannot be deleted or reassigned underneath us.
  if v_me < p_holder_id then v_first:=v_me; v_second:=p_holder_id;
  else v_first:=p_holder_id; v_second:=v_me; end if;
  perform 1 from public.club_members where club_id=p_club_id and user_id=v_first for update;
  if not found then return jsonb_build_object('success',false,'error','A Required Membership No Longer Exists'); end if;
  perform 1 from public.club_members where club_id=p_club_id and user_id=v_second for update;
  if not found then return jsonb_build_object('success',false,'error','A Required Membership No Longer Exists'); end if;

  select role into v_role from public.club_members
   where club_id=p_club_id and user_id=v_me and coalesce(status,'active') in ('active','approved');
  select role into v_holder_role from public.club_members
   where club_id=p_club_id and user_id=p_holder_id and coalesce(status,'active') in ('active','approved');
  if v_role is null or v_role not in ('owner','co_owner','admin','super_agent','agent','sub_agent') then
    return jsonb_build_object('success',false,'error','Your Role Cannot Issue Tickets');
  end if;
  if v_holder_role is null then return jsonb_build_object('success',false,'error','Recipient Is Not Active In This Club'); end if;
  if v_role in ('super_agent','agent','sub_agent')
     and not public.fn_club_cashier_can_transact(p_club_id,v_me,p_holder_id) then
    return jsonb_build_object('success',false,'error','Recipient Is Not In Your Downline');
  end if;

  v_ticket_id:=gen_random_uuid();
  select jsonb_object_agg(k,coalesce(current_setting(k,true),'')) into v_context
   from unnest(array['app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_tournament']) settings(k);
  perform set_config('app.ledger_tournament','',true);
  perform set_config('app.ledger_category','ticket_issue',true);
  perform set_config('app.ledger_counterparty','escrow',true);
  perform set_config('app.ledger_counterparty_entity',v_ticket_id::text,true);
  update public.club_members set chip_balance=coalesce(chip_balance,0)-p_value,updated_at=now()
   where club_id=p_club_id and user_id=v_me and coalesce(status,'active') in ('active','approved')
     and coalesce(chip_balance,0)>=p_value returning chip_balance into v_after;
  for v_setting in select jsonb_object_keys(v_context) loop
    perform set_config(v_setting,v_context->>v_setting,true);
  end loop;
  if v_after is null then return jsonb_build_object('success',false,'error','Insufficient Chips'); end if;

  insert into public.tournament_tickets(id,club_id,issued_by,holder_id,value,note)
  values(v_ticket_id,p_club_id,v_me,p_holder_id,p_value,v_note);
  insert into public.chip_transactions
    (club_id,from_user_id,to_user_id,amount,transaction_type,notes,balance_after,metadata)
  values(p_club_id,v_me,p_holder_id,p_value,'tournament_ticket_issue',
    'Tournament Ticket Issued',v_after,
    jsonb_strip_nulls(jsonb_build_object(
      'idempotency_key',v_key,'ticket_id',v_ticket_id,'escrow_entity_id',v_ticket_id,'issuer_id',v_me,
      'holder_id',p_holder_id,'value',p_value,'note',v_note,'issuer_balance_after',v_after)));
  return jsonb_build_object('success',true,'replayed',false,'ticket_id',v_ticket_id,'your_balance',v_after);
end
$$;


ALTER FUNCTION public.fn_issue_tournament_ticket_phase2_core_20260831(p_club_id uuid, p_holder_id uuid, p_value numeric, p_note text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: fn_join_club(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_join_club(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_result jsonb;
  v_row public.club_members%ROWTYPE;
  v_owner uuid;
  v_requires_approval boolean;
  v_lifecycle text;
  v_active_count integer;
  v_previous_source text := coalesce(current_setting('app.club_membership_source', true), '');
  v_previous_lifecycle text := coalesce(current_setting('app.club_membership_lifecycle_write', true), '');
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  PERFORM set_config('app.club_membership_source', 'join_club', true);
  BEGIN
    v_result := public.fn_join_club_membership_impl(p_club_id);

    IF coalesce(v_result ->> 'membership_lifecycle_status', 'active') = 'departed' THEN
      PERFORM pg_advisory_xact_lock(
        hashtextextended('cashier-hierarchy:' || p_club_id::text, 0)
      );
      SELECT c.owner_id, coalesce(c.requires_approval, false),
             coalesce(to_jsonb(c) ->> 'lifecycle_status', 'active')
        INTO v_owner, v_requires_approval, v_lifecycle
        FROM public.clubs c
       WHERE c.id = p_club_id
       FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Club not found'; END IF;
      IF v_lifecycle = 'retired' THEN
        RAISE EXCEPTION 'This Club Is Retired And Cannot Accept Members' USING ERRCODE = '55000';
      END IF;

      SELECT count(*) INTO v_active_count
        FROM public.club_members cm
       WHERE cm.user_id = v_uid
         AND cm.club_id <> p_club_id
         AND cm.membership_lifecycle_status = 'active'
         AND cm.status::text IN ('active', 'approved');
      IF v_uid <> v_owner AND v_active_count >= 10 THEN
        RAISE EXCEPTION 'You can only be a member of up to 10 clubs. Leave a club to join a new one.';
      END IF;

      PERFORM set_config('app.club_membership_lifecycle_write', 'rejoin', true);
      UPDATE public.club_members cm
         SET membership_lifecycle_status = 'active',
             status = CASE
               WHEN v_uid = v_owner OR NOT v_requires_approval THEN 'active'
               ELSE 'pending'
             END,
             is_active = true,
             departed_at = NULL,
             departed_by = NULL,
             departure_reason = NULL,
             updated_at = clock_timestamp()
       WHERE cm.club_id = p_club_id
         AND cm.user_id = v_uid
         AND cm.membership_lifecycle_status = 'departed'
       RETURNING * INTO v_row;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'membership lifecycle changed during rejoin' USING ERRCODE = '40001';
      END IF;
      v_result := to_jsonb(v_row);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.club_membership_source', v_previous_source, true);
    PERFORM set_config('app.club_membership_lifecycle_write', v_previous_lifecycle, true);
    RAISE;
  END;

  PERFORM set_config('app.club_membership_source', v_previous_source, true);
  PERFORM set_config('app.club_membership_lifecycle_write', v_previous_lifecycle, true);
  RETURN v_result;
END
$$;


ALTER FUNCTION public.fn_join_club(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_join_club_atomic(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_join_club_atomic(p_identifier text, p_request_id uuid, p_referral_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_uid uuid := auth.uid(); v_value text := btrim(COALESCE(p_identifier,''));
  v_ref text := NULLIF(btrim(COALESCE(p_referral_code,'')),'');
  v_club record; v_cached jsonb; v_membership jsonb; v_redeem jsonb; v_result jsonb; v_attempts integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000'; END IF;
  IF p_request_id IS NULL THEN RAISE EXCEPTION 'A join request ID is required' USING ERRCODE='22023'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.club_entry_feature_flags f WHERE f.key='join_club'
      AND (NOT f.enabled OR ((hashtextextended(v_uid::text || ':' || f.key,44119) & 9223372036854775807) % 100) >= f.rollout_percent)
  ) THEN RAISE EXCEPTION 'Club joining is temporarily unavailable.' USING ERRCODE='P0001'; END IF;

  SELECT result INTO v_cached FROM public.club_join_idempotency
   WHERE user_id=v_uid AND request_id=p_request_id;
  IF FOUND THEN RETURN v_cached; END IF;

  -- Eight code/invite attempts per rolling ten minutes. Record failed lookups
  -- too, because enumeration is the abuse this protects against.
  SELECT count(*) INTO v_attempts FROM public.rate_limits
   WHERE user_id=v_uid AND action='club_join' AND created_at>now()-interval '10 minutes';
  IF v_attempts>=8 THEN
    RAISE EXCEPTION 'Too many join attempts. Please wait a few minutes.' USING ERRCODE='P0001';
  END IF;
  INSERT INTO public.rate_limits(user_id,action) VALUES(v_uid,'club_join');

  SELECT c.* INTO v_club FROM public.clubs c
   WHERE (v_value ~ '^[0-9]{5,6}$' AND c.club_id=v_value::integer)
      OR (v_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND c.id=v_value::uuid)
      OR lower(COALESCE(c.slug,''))=lower(v_value)
   LIMIT 1;
  IF NOT FOUND THEN
    v_result := jsonb_build_object('success',false,'code','not_found','error','Club not found');
    INSERT INTO public.club_join_idempotency(user_id,request_id,club_id,result)
    VALUES(v_uid,p_request_id,NULL,v_result);
    RETURN v_result;
  END IF;

  -- Serialize every membership-consuming operation for this user, including
  -- creates and simultaneous joins into different clubs. A user+club lock
  -- lets two distinct clubs both observe the fourth slot as available.
  PERFORM pg_advisory_xact_lock(hashtextextended(v_uid::text, 77431));

  SELECT result INTO v_cached FROM public.club_join_idempotency
   WHERE user_id=v_uid AND request_id=p_request_id;
  IF FOUND THEN RETURN v_cached; END IF;

  BEGIN
    -- fn_join_club owns role, approval status, membership limit, zero-balance,
    -- and conflict handling. This exception block is a subtransaction: an
    -- invalid referral rolls its new membership back while preserving the
    -- rate-limit and idempotency records outside the block.
    v_membership := public.fn_join_club(v_club.id);
    IF COALESCE(v_membership->>'status','') NOT IN ('active','approved','pending') THEN
      RAISE EXCEPTION 'This membership cannot be activated' USING ERRCODE='P0004';
    END IF;

    IF v_ref IS NOT NULL THEN
      v_redeem := public.fn_redeem_club_invite_code(v_club.id,v_uid,v_ref);
      IF COALESCE((v_redeem->>'success')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION '%', COALESCE(v_redeem->>'error','Invalid invitation') USING ERRCODE='P0003';
      END IF;
      SELECT to_jsonb(cm) INTO v_membership FROM public.club_members cm
       WHERE cm.club_id=v_club.id AND cm.user_id=v_uid;
    END IF;

    v_result := jsonb_build_object(
      'success',true,
      'club',jsonb_build_object('id',v_club.id,'club_id',v_club.club_id,'slug',v_club.slug,
        'name',v_club.name,'logo_url',COALESCE(v_club.logo_url,v_club.avatar_url)),
      'membership',v_membership,
      'status',v_membership->>'status',
      'invitation_redeemed',v_ref IS NOT NULL
    );
  EXCEPTION
    WHEN SQLSTATE 'P0003' THEN
      v_result := jsonb_build_object('success',false,'code','invalid_invitation',
        'error',COALESCE(v_redeem->>'error','Invalid invitation'));
    WHEN SQLSTATE 'P0004' THEN
      v_result := jsonb_build_object('success',false,'code','membership_blocked',
        'error','This membership cannot be activated');
  END;
  INSERT INTO public.club_join_idempotency(user_id,request_id,club_id,result)
  VALUES(v_uid,p_request_id,v_club.id,v_result);
  RETURN v_result;
END $_$;


ALTER FUNCTION public.fn_join_club_atomic(p_identifier text, p_request_id uuid, p_referral_code text) OWNER TO postgres;

--
-- Name: fn_join_club_membership_impl(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_join_club_membership_impl(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_requires_approval boolean;
  v_active_count int;
  v_role text;
  v_status text;
  v_row club_members%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT owner_id, COALESCE(requires_approval, false)
    INTO v_owner, v_requires_approval
    FROM clubs
    WHERE id = p_club_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Club not found';
  END IF;

  SELECT * INTO v_row FROM club_members
    WHERE club_id = p_club_id AND user_id = v_uid;
  IF FOUND THEN
    RETURN to_jsonb(v_row);
  END IF;

  IF v_uid = v_owner THEN
    v_role := 'owner';
    v_status := 'active';
  ELSE
    SELECT count(*) INTO v_active_count
      FROM club_members
      WHERE user_id = v_uid AND status IN ('active', 'approved');
    IF v_active_count >= 10 THEN
      RAISE EXCEPTION 'You can only be a member of up to 10 clubs. Leave a club to join a new one.';
    END IF;

    v_role := 'player';
    v_status := CASE WHEN v_requires_approval THEN 'pending' ELSE 'active' END;
  END IF;

  -- chip_balance = 0 written EXPLICITLY: the default was 1000 until 2026-08-26.
  INSERT INTO club_members (club_id, user_id, role, status, tier, rank_level, orange_ball_status, chip_balance)
  VALUES (p_club_id, v_uid, v_role, v_status, 'bronze', 0, 'cold', 0)
  ON CONFLICT (club_id, user_id) DO NOTHING
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    SELECT * INTO v_row FROM club_members
      WHERE club_id = p_club_id AND user_id = v_uid;
  END IF;

  RETURN to_jsonb(v_row);
END;
$$;


ALTER FUNCTION public.fn_join_club_membership_impl(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_kyc_resolve_inquiry(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_kyc_resolve_inquiry(p_inquiry_id text, p_outcome text, p_rejection_reason text DEFAULT NULL::text, p_raw_payload jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_prev_status TEXT;
  v_new_status TEXT;
  v_event_type TEXT;
BEGIN
  IF p_inquiry_id IS NULL OR p_outcome IS NULL THEN
    RAISE EXCEPTION 'p_inquiry_id and p_outcome are required';
  END IF;

  v_new_status := CASE lower(p_outcome)
    WHEN 'approved' THEN 'APPROVED'
    WHEN 'rejected' THEN 'REJECTED'
    WHEN 'expired'  THEN 'EXPIRED'
    ELSE NULL
  END;
  IF v_new_status IS NULL THEN
    RAISE EXCEPTION 'Invalid outcome: % (expected approved|rejected|expired)', p_outcome;
  END IF;

  v_event_type := CASE v_new_status
    WHEN 'APPROVED' THEN 'inquiry_approved'
    WHEN 'REJECTED' THEN 'inquiry_rejected'
    WHEN 'EXPIRED'  THEN 'inquiry_expired'
  END;

  SELECT id, kyc_status INTO v_user_id, v_prev_status
    FROM public.profiles
   WHERE kyc_inquiry_id = p_inquiry_id;

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'inquiry_not_found', 'inquiry_id', p_inquiry_id);
  END IF;

  UPDATE public.profiles
     SET kyc_status = v_new_status,
         kyc_completed_at = now(),
         kyc_rejection_reason = CASE WHEN v_new_status = 'REJECTED' THEN p_rejection_reason END
   WHERE id = v_user_id;

  INSERT INTO public.kyc_events (user_id, event_type, inquiry_id,
                                 previous_status, new_status, source, payload)
  VALUES (v_user_id, v_event_type, p_inquiry_id,
          v_prev_status, v_new_status, 'webhook', p_raw_payload);

  RETURN jsonb_build_object(
    'ok', true,
    'user_id', v_user_id,
    'previous_status', v_prev_status,
    'new_status', v_new_status
  );
END;
$$;


ALTER FUNCTION public.fn_kyc_resolve_inquiry(p_inquiry_id text, p_outcome text, p_rejection_reason text, p_raw_payload jsonb) OWNER TO postgres;

--
-- Name: fn_kyc_start_inquiry(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_kyc_start_inquiry(p_user_id uuid, p_provider text DEFAULT 'stub'::text, p_jurisdiction_country text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inquiry_id TEXT;
  v_existing_status TEXT;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required';
  END IF;

  IF p_provider NOT IN ('persona','veriff','jumio','onfido','stub') THEN
    RAISE EXCEPTION 'Unknown KYC provider: %', p_provider;
  END IF;

  SELECT kyc_status INTO v_existing_status FROM public.profiles WHERE id = p_user_id;
  IF v_existing_status = 'APPROVED' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'already_approved',
      'kyc_status', v_existing_status
    );
  END IF;

  -- Generate inquiry ID (stub: prefix with provider name + timestamp)
  v_inquiry_id := p_provider || '_' || to_char(now(), 'YYYYMMDDHH24MISSMS') || '_' ||
                  substr(md5(p_user_id::text || now()::text), 1, 12);

  UPDATE public.profiles
     SET kyc_status           = 'PENDING',
         kyc_provider         = p_provider,
         kyc_inquiry_id       = v_inquiry_id,
         jurisdiction_country = COALESCE(p_jurisdiction_country, jurisdiction_country, country),
         kyc_rejection_reason = NULL,
         kyc_completed_at     = NULL
   WHERE id = p_user_id;

  INSERT INTO public.kyc_events (user_id, event_type, provider, inquiry_id,
                                 previous_status, new_status, source, payload)
  VALUES (p_user_id, 'inquiry_created', p_provider, v_inquiry_id,
          COALESCE(v_existing_status, 'NONE'), 'PENDING', 'user_action',
          jsonb_build_object('stub', p_provider = 'stub'));

  RETURN jsonb_build_object(
    'ok', true,
    'inquiry_id', v_inquiry_id,
    'provider', p_provider,
    'kyc_status', 'PENDING',
    -- Stub: in production, this URL is returned by the provider's API
    'inquiry_url', 'https://stub.kyc.local/inquiry/' || v_inquiry_id,
    'is_stub', p_provider = 'stub'
  );
END;
$$;


ALTER FUNCTION public.fn_kyc_start_inquiry(p_user_id uuid, p_provider text, p_jurisdiction_country text) OWNER TO postgres;

--
-- Name: fn_launch_table_from_template(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_launch_table_from_template(p_template_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_club uuid;
  v_new  uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_launch_table_from_template requires an authenticated caller'
      USING ERRCODE = '28000';
  END IF;

  SELECT t.club_id INTO v_club FROM public.tables t
   WHERE t.id = p_template_id AND COALESCE(t.is_template, false) = true LIMIT 1;
  IF v_club IS NULL AND NOT EXISTS (
    SELECT 1 FROM public.tables t
     WHERE t.id = p_template_id AND COALESCE(t.is_template, false) = true) THEN
    RAISE EXCEPTION 'TEMPLATE_NOT_FOUND: % is not a table template', p_template_id;
  END IF;

  IF NOT (
    EXISTS (SELECT 1 FROM public.club_members cm
             WHERE cm.club_id = v_club AND cm.user_id = v_uid
               AND cm.role IN ('owner', 'co_owner', 'admin', 'manager', 'agent'))
    OR EXISTS (SELECT 1 FROM public.clubs c
                WHERE c.id = v_club AND c.owner_id = v_uid)
  ) THEN
    RAISE EXCEPTION 'NOT_CLUB_STAFF: only club staff may launch a table';
  END IF;

  v_new := public.fn_clone_table_row(p_template_id, NULL);
  UPDATE public.tables SET status = 'active', created_by = v_uid WHERE id = v_new;
  RETURN v_new;
END;
$$;


ALTER FUNCTION public.fn_launch_table_from_template(p_template_id uuid) OWNER TO postgres;

--
-- Name: fn_leaderboard_funding_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_leaderboard_funding_summary(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_union_id uuid;
  v_owner_type text;
  v_balance numeric := 0;
  v_total numeric := 0;
  v_current numeric := 0;
  v_other numeric := 0;
  v_committed_clubs integer := 0;
  v_current_exists boolean := false;
  v_current_enabled boolean := false;
BEGIN
  v_union_id := public.fn_leaderboard_funding_union_id(p_club_id);
  v_owner_type := CASE WHEN v_union_id IS NULL THEN 'club' ELSE 'union' END;

  IF v_owner_type = 'union' THEN
    SELECT COALESCE(wallet.promo_wallet, 0)
      INTO v_balance
      FROM public.union_wallets wallet
     WHERE wallet.union_id = v_union_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Leaderboard Funding Union Has No Promo Wallet'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    SELECT COALESCE(club.promo_balance, 0)
      INTO v_balance
      FROM public.clubs club
     WHERE club.id = p_club_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Club Not Found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  WITH latest AS MATERIALIZED (
    SELECT DISTINCT ON (program.club_id)
      program.club_id,
      program.rewards_enabled,
      program.weekly_prizes,
      program.monthly_prizes,
      program.funding_owner_type,
      program.funding_union_id
    FROM public.leaderboard_reward_program_versions program
    ORDER BY program.club_id, program.version DESC
  ), scoped AS (
    SELECT
      latest.club_id,
      latest.rewards_enabled,
      public.fn_leaderboard_program_commitment(
        latest.rewards_enabled,
        latest.weekly_prizes,
        latest.monthly_prizes
      ) AS commitment
    FROM latest
    WHERE (
      v_owner_type = 'union'
      AND latest.funding_owner_type = 'union'
      AND latest.funding_union_id = v_union_id
    ) OR (
      v_owner_type = 'club'
      AND latest.funding_owner_type = 'club'
      AND latest.club_id = p_club_id
    )
  )
  SELECT
    COALESCE(sum(scoped.commitment), 0),
    COALESCE(sum(scoped.commitment) FILTER (WHERE scoped.club_id = p_club_id), 0),
    count(*) FILTER (WHERE scoped.rewards_enabled),
    COALESCE(bool_or(scoped.club_id = p_club_id), false),
    COALESCE(bool_or(scoped.club_id = p_club_id AND scoped.rewards_enabled), false)
  INTO v_total, v_current, v_committed_clubs, v_current_exists, v_current_enabled
  FROM scoped;

  v_other := GREATEST(v_total - v_current, 0);
  RETURN jsonb_build_object(
    'funding_owner_type', v_owner_type,
    'funding_union_id', v_union_id,
    'wallet_balance', round(v_balance, 2),
    'committed_balance', round(v_total, 2),
    'current_program_commitment', round(v_current, 2),
    'other_program_commitments', round(v_other, 2),
    'publication_capacity', round(GREATEST(v_balance - v_other, 0), 2),
    'available_uncommitted_balance', round(GREATEST(v_balance - v_total, 0), 2),
    'committed_club_count', v_committed_clubs,
    'funding_status', CASE
      WHEN NOT v_current_exists THEN 'not_published'
      WHEN NOT v_current_enabled THEN 'disabled'
      WHEN v_balance >= v_total THEN 'funded'
      ELSE 'underfunded'
    END
  );
END;
$$;


ALTER FUNCTION public.fn_leaderboard_funding_summary(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_leaderboard_funding_summary(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_leaderboard_funding_summary(p_club_id uuid) IS 'Derived rolling leaderboard commitment for the current funding owner. The latest enabled program for each club commits one weekly plus one monthly prize plan; replacement capacity excludes the requested club commitment.';


--
-- Name: fn_leaderboard_funding_union_id(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_leaderboard_funding_union_id(p_club_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_pointer_union_id uuid;
  v_membership_union_id uuid;
  v_membership_count integer;
  v_is_union boolean;
BEGIN
  SELECT club.union_id, COALESCE(club.is_union, false)
    INTO v_pointer_union_id, v_is_union
    FROM public.clubs club
   WHERE club.id = p_club_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Club Not Found' USING ERRCODE = 'P0002';
  END IF;

  -- A union's own house club is its wallet identity. Ordinary member clubs use
  -- union_clubs as the authoritative relationship and only accept the mirror
  -- pointer when it agrees exactly.
  IF v_is_union THEN RETURN p_club_id; END IF;

  SELECT count(DISTINCT membership.union_id),
         (array_agg(DISTINCT membership.union_id))[1]
    INTO v_membership_count, v_membership_union_id
    FROM public.union_clubs membership
   WHERE membership.club_id = p_club_id;

  IF v_membership_count > 1
     OR (v_membership_count = 1
         AND v_pointer_union_id IS DISTINCT FROM v_membership_union_id)
     OR (v_membership_count = 0 AND v_pointer_union_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Conflicting Union Affiliation For Leaderboard Funding'
      USING ERRCODE = '55000';
  END IF;

  RETURN v_membership_union_id;
END;
$$;


ALTER FUNCTION public.fn_leaderboard_funding_union_id(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_leaderboard_funding_union_id(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_leaderboard_funding_union_id(p_club_id uuid) IS 'Fail-closed canonical funding affiliation resolver for leaderboard reward programs.';


--
-- Name: fn_leaderboard_period_window(text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_leaderboard_period_window(p_period text, p_period_offset integer DEFAULT 0, p_reference timestamp with time zone DEFAULT now()) RETURNS TABLE(period text, period_offset integer, timezone text, start_date date, end_date date, start_at timestamp with time zone, end_at timestamp with time zone, is_current boolean, label text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_timezone constant text := 'UTC';
  v_offset integer := COALESCE(p_period_offset, 0);
  v_today date := (COALESCE(p_reference, now()) AT TIME ZONE v_timezone)::date;
  v_current_start date;
  v_start date;
  v_end date;
BEGIN
  IF p_period NOT IN ('daily', 'weekly', 'monthly', 'all_time') THEN
    RAISE EXCEPTION 'Unsupported Leaderboard Period' USING ERRCODE = '22023';
  END IF;
  IF v_offset > 0 THEN
    RAISE EXCEPTION 'Future Leaderboard Periods Are Not Available' USING ERRCODE = '22023';
  END IF;
  IF p_period = 'all_time' AND v_offset <> 0 THEN
    RAISE EXCEPTION 'All-Time Leaderboards Do Not Have Period Offsets' USING ERRCODE = '22023';
  END IF;

  v_current_start := CASE p_period
    WHEN 'daily' THEN v_today
    WHEN 'weekly' THEN v_today - EXTRACT(DOW FROM v_today)::integer
    WHEN 'monthly' THEN date_trunc('month', v_today)::date
    ELSE DATE '1970-01-01'
  END;

  v_start := CASE p_period
    WHEN 'daily' THEN v_current_start + v_offset
    WHEN 'weekly' THEN v_current_start + (v_offset * 7)
    WHEN 'monthly' THEN (v_current_start + make_interval(months => v_offset))::date
    ELSE v_current_start
  END;
  v_end := CASE p_period
    WHEN 'daily' THEN v_start + 1
    WHEN 'weekly' THEN v_start + 7
    WHEN 'monthly' THEN (v_start + interval '1 month')::date
    ELSE v_today + 1
  END;

  RETURN QUERY SELECT
    p_period,
    v_offset,
    v_timezone,
    v_start,
    v_end,
    v_start::timestamp AT TIME ZONE v_timezone,
    v_end::timestamp AT TIME ZONE v_timezone,
    v_offset = 0,
    CASE
      WHEN p_period = 'all_time' THEN 'All Time'
      WHEN p_period = 'daily' THEN to_char(v_start, 'Mon FMDD, YYYY')
      ELSE to_char(v_start, 'Mon FMDD') || ' - ' || to_char(v_end - 1, 'Mon FMDD, YYYY')
    END;
END;
$$;


ALTER FUNCTION public.fn_leaderboard_period_window(p_period text, p_period_offset integer, p_reference timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_leaderboard_period_window(p_period text, p_period_offset integer, p_reference timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_leaderboard_period_window(p_period text, p_period_offset integer, p_reference timestamp with time zone) IS 'Canonical UTC leaderboard window. Boundaries are start-inclusive and end-exclusive; weeks begin Sunday.';


--
-- Name: fn_leaderboard_prizes_are_valid(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_leaderboard_prizes_are_valid(p_prizes jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_prizes jsonb := COALESCE(p_prizes, '[]'::jsonb);
  v_prize jsonb;
  v_rank integer;
  v_amount numeric;
  v_seen_ranks integer[] := ARRAY[]::integer[];
BEGIN
  IF jsonb_typeof(v_prizes) <> 'array' OR jsonb_array_length(v_prizes) > 10 THEN
    RETURN false;
  END IF;

  FOR v_prize IN SELECT value FROM jsonb_array_elements(v_prizes)
  LOOP
    IF jsonb_typeof(v_prize) <> 'object'
       OR (SELECT count(*) FROM jsonb_object_keys(v_prize)) <> 2
       OR NOT (v_prize ? 'rank' AND v_prize ? 'amount')
       OR jsonb_typeof(v_prize -> 'rank') <> 'number'
       OR jsonb_typeof(v_prize -> 'amount') <> 'number' THEN
      RETURN false;
    END IF;
    IF (v_prize ->> 'rank') IS NULL
       OR (v_prize ->> 'amount') IS NULL
       OR (v_prize ->> 'rank') !~ '^[0-9]+$'
       OR length(v_prize ->> 'rank') > 2
       OR (v_prize ->> 'amount') !~ '^[0-9]+([.][0-9]{1,2})?$'
       OR length(v_prize ->> 'amount') > 20 THEN
      RETURN false;
    END IF;

    v_rank := (v_prize ->> 'rank')::integer;
    v_amount := (v_prize ->> 'amount')::numeric;
    IF v_rank NOT BETWEEN 1 AND 10
       OR v_amount <= 0
       OR v_amount > 1000000000
       OR v_rank = ANY(v_seen_ranks) THEN
      RETURN false;
    END IF;
    v_seen_ranks := array_append(v_seen_ranks, v_rank);
  END LOOP;
  RETURN true;
END;
$_$;


ALTER FUNCTION public.fn_leaderboard_prizes_are_valid(p_prizes jsonb) OWNER TO postgres;

--
-- Name: fn_leaderboard_program_commitment(boolean, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_leaderboard_program_commitment(p_rewards_enabled boolean, p_weekly_prizes jsonb, p_monthly_prizes jsonb) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN COALESCE(p_rewards_enabled, false) THEN
    COALESCE((
      SELECT sum((prize ->> 'amount')::numeric)
      FROM jsonb_array_elements(COALESCE(p_weekly_prizes, '[]'::jsonb)) prize
    ), 0)
    + COALESCE((
      SELECT sum((prize ->> 'amount')::numeric)
      FROM jsonb_array_elements(COALESCE(p_monthly_prizes, '[]'::jsonb)) prize
    ), 0)
  ELSE 0 END;
$$;


ALTER FUNCTION public.fn_leaderboard_program_commitment(p_rewards_enabled boolean, p_weekly_prizes jsonb, p_monthly_prizes jsonb) OWNER TO postgres;

--
-- Name: fn_leaderboard_reward_contexts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_leaderboard_reward_contexts() RETURNS TABLE(club_id uuid, club_name text, union_id uuid, union_name text, funding_owner_type text, funding_source text, setup_complete boolean, rewards_enabled boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH manageable_clubs AS MATERIALIZED (
    SELECT
      club.id AS club_id,
      club.name AS club_name
    FROM public.clubs club
    WHERE COALESCE(club.is_union, false) = false
      AND (
        club.owner_id = auth.uid()
        OR EXISTS (
          SELECT 1 FROM public.club_members member
           WHERE member.club_id = club.id
             AND member.user_id = auth.uid()
             AND member.role IN ('owner', 'co_owner')
             AND COALESCE(member.status, 'active') IN ('active', 'approved')
        )
        OR EXISTS (
          SELECT 1 FROM public.union_clubs membership
           WHERE membership.club_id = club.id
             AND public.fn_union_can_manage_wallets(membership.union_id, auth.uid())
        )
      )
  ), candidate AS MATERIALIZED (
    SELECT
      manageable.club_id,
      manageable.club_name,
      public.fn_leaderboard_funding_union_id(manageable.club_id) AS union_id
    FROM manageable_clubs manageable
  )
  SELECT
    candidate.club_id,
    candidate.club_name,
    candidate.union_id,
    union_row.name,
    CASE WHEN candidate.union_id IS NULL THEN 'club' ELSE 'union' END,
    CASE WHEN candidate.union_id IS NULL THEN 'club_promo_balance' ELSE 'union_promo_wallet' END,
    settings.setup_completed_at IS NOT NULL,
    COALESCE(settings.rewards_enabled, false)
  FROM candidate
  LEFT JOIN public.unions union_row ON union_row.id = candidate.union_id
  LEFT JOIN public.club_leaderboard_settings settings ON settings.club_id = candidate.club_id
  WHERE (
    candidate.union_id IS NOT NULL
    AND public.fn_union_can_manage_wallets(candidate.union_id, auth.uid())
  ) OR (
    candidate.union_id IS NULL
    AND (
      EXISTS (
        SELECT 1 FROM public.clubs owned
         WHERE owned.id = candidate.club_id AND owned.owner_id = auth.uid()
      )
      OR EXISTS (
        SELECT 1 FROM public.club_members member
         WHERE member.club_id = candidate.club_id
           AND member.user_id = auth.uid()
           AND member.role IN ('owner', 'co_owner')
           AND COALESCE(member.status, 'active') IN ('active', 'approved')
      )
    )
  )
  ORDER BY union_row.name NULLS LAST, candidate.club_name;
$$;


ALTER FUNCTION public.fn_leaderboard_reward_contexts() OWNER TO postgres;

--
-- Name: fn_leaderboard_snapshot_gaps(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_leaderboard_snapshot_gaps(p_days integer DEFAULT 35) RETURNS TABLE(missing_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT d::date
  FROM generate_series(
         GREATEST((SELECT min(snapshot_date) FROM player_stats_snapshots),
                  CURRENT_DATE - p_days),
         CURRENT_DATE - 1, interval '1 day') d
  WHERE NOT EXISTS (
    SELECT 1 FROM player_stats_snapshots s WHERE s.snapshot_date = d::date
  );
$$;


ALTER FUNCTION public.fn_leaderboard_snapshot_gaps(p_days integer) OWNER TO postgres;

--
-- Name: fn_league_pooled(date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_league_pooled(p_day date, p_days integer DEFAULT 7) RETURNS TABLE(matchup text, runs integer, hands bigint, bb100 numeric, stderr numeric, verdict text, newest_run date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with rows as (
    select r.matchup, r.bb100::numeric b, greatest(r.stderr::numeric, 0.01) s,
           r.hands::bigint h, r.run_date
    from horse_league_results r
    where r.run_date > p_day - greatest(p_days, 1)
      and r.run_date <= p_day + 1
  ), pooled as (
    select rows.matchup,
           count(*)::int runs,
           sum(rows.h) hands,
           sum(rows.b / (rows.s * rows.s)) / nullif(sum(1.0 / (rows.s * rows.s)), 0) bb100,
           sqrt(1.0 / nullif(sum(1.0 / (rows.s * rows.s)), 0)) stderr,
           max(rows.run_date) newest_run
    from rows group by rows.matchup
  )
  select p.matchup, p.runs, p.hands,
         round(p.bb100, 2), round(p.stderr, 2),
         case when abs(p.bb100) > 2 * p.stderr then 'SIGNIFICANT' else 'not resolved' end,
         p.newest_run
  from pooled p
  order by p.bb100 desc;
$$;


ALTER FUNCTION public.fn_league_pooled(p_day date, p_days integer) OWNER TO postgres;

--
-- Name: fn_leave_club_atomic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_leave_club_atomic(p_club_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_role text;
  v_chips numeric;
BEGIN
  SELECT role, COALESCE(chip_balance,0) INTO v_role, v_chips
  FROM club_members
  WHERE club_id = p_club_id AND user_id = p_user_id FOR UPDATE;

  IF v_role IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not a member');
  END IF;

  IF v_role IN ('owner', 'co_owner') THEN
    RETURN jsonb_build_object('success', false, 'error', 'owners must transfer ownership first');
  END IF;

  -- Return chips to club treasury to avoid vaporization
  IF v_chips > 0 THEN
    UPDATE clubs SET chip_treasury = COALESCE(chip_treasury,0) + v_chips, updated_at = NOW()
      WHERE id = p_club_id;
    INSERT INTO chip_transactions (
      id, club_id, from_user_id, amount, transaction_type, notes, balance_after, created_at
    ) VALUES (
      gen_random_uuid(), p_club_id, p_user_id, v_chips,
      'leave_club_chip_return', 'Chips returned on leave', 0, NOW()
    );
  END IF;

  -- Soft-delete membership (set status, don't hard delete for audit)
  UPDATE club_members
  SET status = 'left', is_active = false, updated_at = NOW(), chip_balance = 0
  WHERE club_id = p_club_id AND user_id = p_user_id;

  -- Decrement member count if present
  UPDATE clubs SET member_count = GREATEST(COALESCE(member_count,1)-1, 0), updated_at = NOW()
  WHERE id = p_club_id;

  RETURN jsonb_build_object('success', true, 'chips_returned', v_chips);
END;
$$;


ALTER FUNCTION public.fn_leave_club_atomic(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_leave_club_atomic(p_club_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_leave_club_atomic(p_club_id uuid, p_user_id uuid) IS 'BUG 025: real impl. Returns chips to treasury, soft-deletes membership, decrements member count.';


