-- Name: fn_leave_seat_and_refund(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_leave_seat_and_refund(p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid:=auth.uid();
  v_tournament_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_leave_seat_and_refund requires an authenticated caller'
      USING ERRCODE='28000';
  END IF;
  SELECT tb.tournament_id INTO v_tournament_id FROM public.tables tb
   WHERE tb.id=p_table_id;
  IF v_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','table_not_found');
  END IF;
  RETURN public.fn_ca_unregister_tournament_player_exact(
    v_tournament_id,v_uid,p_table_id,'Tournament seat unregistration refund');
END;
$$;


ALTER FUNCTION public.fn_leave_seat_and_refund(p_table_id uuid) OWNER TO postgres;

