-- Name: social_posts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.social_posts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    author_id uuid NOT NULL,
    content text NOT NULL,
    content_type text DEFAULT 'text'::text,
    media_urls jsonb DEFAULT '[]'::jsonb,
    like_count integer DEFAULT 0,
    comment_count integer DEFAULT 0,
    share_count integer DEFAULT 0,
    view_count integer DEFAULT 0,
    visibility text DEFAULT 'public'::text,
    is_pinned boolean DEFAULT false,
    is_flagged boolean DEFAULT false,
    is_deleted boolean DEFAULT false,
    achievement_data jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    search_vector tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, COALESCE(content, ''::text))) STORED,
    metadata jsonb DEFAULT '{}'::jsonb,
    link_url text,
    link_title text,
    link_description text,
    link_image text,
    link_site_name text,
    thumbnail_url text,
    transcode_status text,
    original_media_url text,
    transcode_error text,
    transcoded_at timestamp with time zone,
    cover_frames text[],
    cover_frame_index integer,
    ai_label boolean DEFAULT false,
    audience_mode text,
    audience_list text[],
    share_to_story boolean DEFAULT false,
    metadata_location jsonb,
    topics text[],
    origin_type text DEFAULT 'user_upload'::text NOT NULL,
    playback_type text DEFAULT 'external_embed'::text NOT NULL,
    topic text DEFAULT 'unknown'::text NOT NULL,
    rights_status text DEFAULT 'unknown'::text NOT NULL,
    source_asset_id uuid,
    youtube_video_id text,
    canonical_asset_key text,
    publication_key text,
    legacy_transition_expires_at timestamp with time zone,
    CONSTRAINT social_posts_comment_count_check CHECK ((comment_count >= 0)),
    CONSTRAINT social_posts_content_check CHECK ((char_length(content) <= 2000)),
    CONSTRAINT social_posts_embed_rights_check CHECK (((rights_status <> 'embed_only'::text) OR (playback_type = 'youtube_embed'::text))),
    CONSTRAINT social_posts_like_count_check CHECK ((like_count >= 0)),
    CONSTRAINT social_posts_managed_library_integrity_check CHECK ((((origin_type <> 'video_library'::text) AND (source_asset_id IS NULL) AND (publication_key IS NULL)) OR ((origin_type = 'video_library'::text) AND (source_asset_id IS NOT NULL) AND (youtube_video_id IS NOT NULL) AND (canonical_asset_key IS NOT NULL) AND (publication_key IS NOT NULL)))),
    CONSTRAINT social_posts_origin_type_check CHECK ((origin_type = ANY (ARRAY['user_upload'::text, 'story'::text, 'social_post'::text, 'video_library'::text, 'horse'::text, 'pokernews'::text, 'generated'::text, 'legacy'::text]))),
    CONSTRAINT social_posts_playback_type_check CHECK ((playback_type = ANY (ARRAY['native'::text, 'youtube_embed'::text, 'external_embed'::text]))),
    CONSTRAINT social_posts_rights_status_check CHECK ((rights_status = ANY (ARRAY['unknown'::text, 'embed_only'::text, 'owned'::text, 'licensed'::text, 'user_authorized'::text, 'restricted'::text]))),
    CONSTRAINT social_posts_share_count_check CHECK ((share_count >= 0)),
    CONSTRAINT social_posts_topic_check CHECK ((topic = ANY (ARRAY['unknown'::text, 'poker'::text, 'cash'::text, 'tournament'::text, 'slots'::text, 'sports'::text, 'other'::text]))),
    CONSTRAINT social_posts_view_count_check CHECK ((view_count >= 0)),
    CONSTRAINT social_posts_visibility_check CHECK ((visibility = ANY (ARRAY['public'::text, 'followers'::text, 'private'::text])))
);


