--
-- Name: fn_list_managed_games(text, uuid, timestamp with time zone, text, uuid, integer, integer, integer, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_list_managed_games(p_scope text, p_scope_id uuid, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_kind text DEFAULT NULL::text, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_cursor_bucket integer DEFAULT NULL::integer, p_bucket integer DEFAULT NULL::integer, p_game_kind text DEFAULT NULL::text, p_game_id uuid DEFAULT NULL::uuid, p_closed_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer := LEAST(100, GREATEST(1, COALESCE(p_limit, 100)));
  v_items jsonb; v_counts jsonb; v_next jsonb; v_access jsonb; v_scope_clubs uuid[];
  v_cur_bucket integer;
  v_bucket integer := CASE WHEN p_bucket IN (0,1,2) THEN p_bucket ELSE NULL END;
  v_one boolean := (p_game_id IS NOT NULL AND p_game_kind IN ('table','tournament'));
  -- NULL means no horizon: 0 or a negative value asks for the whole archive.
  v_since timestamptz := CASE
    WHEN COALESCE(p_closed_days, 7) <= 0 THEN NULL
    ELSE now() - make_interval(days => COALESCE(p_closed_days, 7))
  END;
BEGIN
  IF p_scope NOT IN ('club','union') OR p_scope_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized');
  END IF;
  IF p_scope='club' THEN
    v_access := public.fn_game_creation_access(p_scope_id);
    IF NOT COALESCE((v_access->>'allowed')::boolean,false)
       OR v_access->>'union_id' IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','not_authorized');
    END IF;
  ELSIF NOT public.fn_is_union_operator(p_scope_id,auth.uid()) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized');
  END IF;
  IF p_scope='union' THEN
    SELECT COALESCE(array_agg(x.club_id),'{}'::uuid[]) INTO v_scope_clubs
    FROM (
      SELECT p_scope_id AS club_id
      UNION SELECT uc.club_id FROM public.union_clubs uc WHERE uc.union_id=p_scope_id
      UNION SELECT c.id FROM public.clubs c WHERE c.union_id=p_scope_id
    ) x;
  END IF;

  -- Recover the cursor's bucket from its own row when the caller did not send
  -- one. Same expression as the ordering below; keep the three in step.
  v_cur_bucket := p_cursor_bucket;
  IF v_cur_bucket IS NULL AND p_cursor IS NOT NULL AND p_cursor_id IS NOT NULL THEN
    IF p_cursor_kind = 'table' THEN
      SELECT CASE WHEN lower(t.status) IN ('closed','completed','cancelled','canceled','deleted')
                  THEN 2 ELSE 0 END
        INTO v_cur_bucket FROM public.tables t WHERE t.id = p_cursor_id;
    ELSE
      SELECT CASE WHEN lower(t.status) IN ('closed','completed','cancelled','canceled','deleted') THEN 2
                  WHEN t.start_time > now() THEN 1
                  ELSE 0 END
        INTO v_cur_bucket FROM public.tournaments t WHERE t.id = p_cursor_id;
    END IF;
  END IF;
  v_cur_bucket := COALESCE(v_cur_bucket, COALESCE(v_bucket, 0));

  WITH all_games AS (
    SELECT t.id,'table'::text kind,t.club_id,t.name,t.status,COALESCE(t.game_variant,'NLH') variant,
      COALESCE(t.current_players,0) players,COALESCE(t.max_players,0) max_players,
      NULL::timestamptz start_time,t.created_at sort_at,COALESCE(t.small_blind,0) small_blind,
      COALESCE(t.big_blind,0) big_blind,COALESCE(t.min_buy_in,0) min_buy_in,
      COALESCE(t.max_buy_in,0) max_buy_in,0::numeric buy_in,
      CASE WHEN lower(t.status) IN ('closed','completed','cancelled','canceled','deleted')
           THEN 2 ELSE 0 END AS bucket,
      GREATEST(t.created_at, COALESCE(t.updated_at, t.created_at)) AS touched_at
    FROM public.tables t WHERE t.tournament_id IS NULL AND NOT COALESCE(t.is_deleted,false)
      AND (NOT v_one OR (p_game_kind='table' AND t.id=p_game_id))
      AND ((p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
        OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=ANY(v_scope_clubs))))
    UNION ALL
    SELECT t.id,'tournament',t.club_id,t.name,t.status,COALESCE(t.game_type,t.variant,'MTT'),
      COALESCE(t.current_players,0),COALESCE(t.max_players,0),t.start_time,
      COALESCE(t.start_time,t.created_at),0::numeric,0::numeric,0::numeric,0::numeric,
      COALESCE(t.buy_in_amount,0),
      CASE WHEN lower(t.status) IN ('closed','completed','cancelled','canceled','deleted') THEN 2
           WHEN t.start_time > now() THEN 1
           ELSE 0 END,
      GREATEST(COALESCE(t.start_time, t.created_at), COALESCE(t.updated_at, t.created_at))
    FROM public.tournaments t WHERE
      (NOT v_one OR (p_game_kind='tournament' AND t.id=p_game_id))
      AND ((p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
        OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=ANY(v_scope_clubs))))
  ), visible AS (
    -- The horizon applies ONLY to finished games. A live or scheduled game is
    -- never hidden by age; it is still the operator's problem however old it is.
    SELECT * FROM all_games g
    WHERE v_one OR v_since IS NULL OR g.bucket <> 2 OR g.touched_at >= v_since
  ), page AS (
    SELECT v.* FROM visible v
    WHERE (v_one OR v_bucket IS NULL OR v.bucket = v_bucket)
      AND (v_one OR p_cursor IS NULL
           OR (v.bucket,v.sort_at,v.kind,v.id)>(v_cur_bucket,p_cursor,p_cursor_kind,p_cursor_id))
    ORDER BY v.bucket,v.sort_at,v.kind,v.id LIMIT CASE WHEN v_one THEN 1 ELSE v_limit END
  ), enriched AS (
    SELECT p.*,
      (SELECT to_jsonb(s) FROM (
        SELECT ms.schedule_id,ms.execute_at,ms.status FROM public.managed_game_schedules ms
        WHERE ms.game_kind=p.kind AND ms.game_id=p.id AND ms.status='scheduled'
        ORDER BY ms.created_at DESC LIMIT 1) s) pending_schedule,
      -- The published contract, same projection as fn_get_managed_game_contracts.
      (SELECT jsonb_build_object(
                'game_id', p.id,
                'version', v.version,
                'contract_hash', v.contract_hash,
                'published_at', v.published_at,
                'published_by', v.published_by,
                'change_reason', v.change_reason,
                'contract_locked', r.locked,
                'readiness', r.readiness)
         FROM public.managed_game_contract_versions v
         CROSS JOIN LATERAL (
           SELECT CASE WHEN p.kind='tournament'
                       THEN public.fn_tournament_management_readiness(p.id)
                       ELSE jsonb_build_object('state','ready','can_start',true,
                              'contract_locked', EXISTS (
                                SELECT 1 FROM public.table_seats ts
                                 WHERE ts.table_id=p.id AND ts.left_at IS NULL))
                  END AS readiness
           OFFSET 0
         ) rr
         CROSS JOIN LATERAL (
           SELECT rr.readiness AS readiness,
                  COALESCE((rr.readiness ->> 'contract_locked')::boolean,false) AS locked
           OFFSET 0
         ) r
        WHERE v.game_kind=p.kind AND v.game_id=p.id
        ORDER BY v.version DESC LIMIT 1) contract,
      -- The latest command receipt, same projection and reconciliation rule as
      -- fn_get_managed_game_command_receipts.
      (SELECT to_jsonb(x) FROM (
         SELECT rc.game_id, rc.command_id, rc.command_action, rc.status,
                rc.contract_version_before, rc.contract_version_after,
                CASE WHEN rc.status='processing' THEN 'processing'
                     WHEN av.version IS NULL THEN 'version_drift'
                     ELSE 'confirmed' END AS reconciliation_state,
                rc.created_at, rc.completed_at
           FROM public.managed_game_command_receipts rc
           JOIN public.managed_game_contract_versions bv
             ON bv.game_kind=rc.game_kind AND bv.game_id=rc.game_id
            AND bv.version=rc.contract_version_before
           LEFT JOIN public.managed_game_contract_versions av
             ON av.game_kind=rc.game_kind AND av.game_id=rc.game_id
            AND av.version=rc.contract_version_after
          WHERE rc.game_kind=p.kind AND rc.game_id=p.id
          ORDER BY rc.created_at DESC LIMIT 1) x) last_command
    FROM page p ORDER BY p.bucket,p.sort_at,p.kind,p.id
  ) SELECT COALESCE(jsonb_agg(to_jsonb(enriched) ORDER BY bucket,sort_at,kind,id),'[]'::jsonb)
    INTO v_items FROM enriched;

  -- A single-game read skips both scans. That IS the saving, and it is why
  -- counts and next_cursor come back null: "unchanged", never zero.
  IF v_one THEN
    RETURN jsonb_build_object('ok',true,'items',v_items,'counts',NULL,'next_cursor',NULL);
  END IF;

  -- Counts summarise the WHOLE scope regardless of the open tab, and regardless
  -- of the horizon. closed_within_horizon is what the Closed tab is actually
  -- showing, so the board can tell "no games" from "none this recent".
  --
  -- Only on the FIRST page. Paging cannot change a whole-scope total, and on
  -- Midway Union this scan is 5 of the page's 8 second budget. A paged read
  -- returns counts null, meaning unchanged.
  IF p_cursor IS NULL THEN
    WITH scoped AS (
      SELECT status,'table'::text kind,NULL::timestamptz start_time,
             GREATEST(t.created_at, COALESCE(t.updated_at, t.created_at)) AS touched_at
        FROM public.tables t
      WHERE t.tournament_id IS NULL AND NOT COALESCE(t.is_deleted,false)
        AND ((p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
          OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=ANY(v_scope_clubs))))
      UNION ALL SELECT status,'tournament',t.start_time,
             GREATEST(COALESCE(t.start_time, t.created_at), COALESCE(t.updated_at, t.created_at))
        FROM public.tournaments t WHERE
        (p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
        OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=ANY(v_scope_clubs)))
    ), bucketed AS (
      SELECT CASE
        WHEN lower(status) IN ('closed','completed','cancelled','canceled','deleted') THEN 2
        WHEN kind='tournament' AND start_time > now() THEN 1
        ELSE 0 END AS bucket,
        touched_at
      FROM scoped
    ) SELECT jsonb_build_object(
        'total',count(*),
        'live',count(*) FILTER (WHERE bucket=0),
        'scheduled',count(*) FILTER (WHERE bucket=1),
        'closed',count(*) FILTER (WHERE bucket=2),
        'closed_within_horizon',
          count(*) FILTER (WHERE bucket=2 AND (v_since IS NULL OR touched_at >= v_since)),
        'closed_horizon_days', COALESCE(p_closed_days, 7))
    INTO v_counts FROM bucketed;
  END IF;

  WITH all_games AS (
    SELECT t.id,'table'::text kind,t.created_at sort_at,
      CASE WHEN lower(t.status) IN ('closed','completed','cancelled','canceled','deleted')
           THEN 2 ELSE 0 END AS bucket,
      GREATEST(t.created_at, COALESCE(t.updated_at, t.created_at)) AS touched_at
    FROM public.tables t
    WHERE t.tournament_id IS NULL AND NOT COALESCE(t.is_deleted,false)
      AND ((p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
        OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=ANY(v_scope_clubs))))
    UNION ALL SELECT t.id,'tournament',COALESCE(t.start_time,t.created_at),
      CASE WHEN lower(t.status) IN ('closed','completed','cancelled','canceled','deleted') THEN 2
           WHEN t.start_time > now() THEN 1
           ELSE 0 END,
      GREATEST(COALESCE(t.start_time, t.created_at), COALESCE(t.updated_at, t.created_at))
    FROM public.tournaments t WHERE (p_scope='club' AND t.club_id=p_scope_id AND t.union_id IS NULL)
      OR (p_scope='union' AND (t.union_id=p_scope_id OR t.club_id=ANY(v_scope_clubs)))
  ), eligible AS (
    SELECT * FROM all_games
    WHERE (v_since IS NULL OR bucket <> 2 OR touched_at >= v_since)
      AND (v_bucket IS NULL OR bucket = v_bucket)
      AND (p_cursor IS NULL
           OR (bucket,sort_at,kind,id)>(v_cur_bucket,p_cursor,p_cursor_kind,p_cursor_id))
  ), remaining AS (
    SELECT * FROM eligible ORDER BY bucket,sort_at,kind,id OFFSET v_limit LIMIT 1
  ), last_item AS (
    SELECT * FROM eligible ORDER BY bucket,sort_at,kind,id OFFSET GREATEST(v_limit-1,0) LIMIT 1
  ) SELECT CASE WHEN EXISTS(SELECT 1 FROM remaining) THEN
    (SELECT jsonb_build_object('sort_at',sort_at,'kind',kind,'id',id,'bucket',bucket) FROM last_item)
    ELSE NULL END INTO v_next;

  RETURN jsonb_build_object('ok',true,'items',v_items,'counts',v_counts,'next_cursor',v_next);
END;
$$;


ALTER FUNCTION public.fn_list_managed_games(p_scope text, p_scope_id uuid, p_cursor timestamp with time zone, p_cursor_kind text, p_cursor_id uuid, p_limit integer, p_cursor_bucket integer, p_bucket integer, p_game_kind text, p_game_id uuid, p_closed_days integer) OWNER TO postgres;

--
-- Name: fn_list_my_home_memberships(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_list_my_home_memberships() RETURNS TABLE(kind text, hg_group_id uuid, hg_name text, hg_slug text, hg_role text, hg_status text, is_owner boolean, is_private boolean, is_21_plus boolean, member_count integer, profile_photo_url text, city text, next_game_at timestamp with time zone, unread_posts integer, joined_at timestamp with time zone, last_attended timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM public.fn_list_my_home_memberships(v_uid);
END;
$$;


ALTER FUNCTION public.fn_list_my_home_memberships() OWNER TO postgres;

--
-- Name: fn_list_my_home_memberships(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_list_my_home_memberships(p_caller_user_id uuid) RETURNS TABLE(kind text, hg_group_id uuid, hg_name text, hg_slug text, hg_role text, hg_status text, is_owner boolean, is_private boolean, is_21_plus boolean, member_count integer, profile_photo_url text, city text, next_game_at timestamp with time zone, unread_posts integer, joined_at timestamp with time zone, last_attended timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_caller_user_id THEN
      RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH owned AS (
    SELECT g.id, g.name, g.owner_id, g.is_private, g.is_21_plus,
           g.member_count, g.profile_photo_url, g.city, g.created_at
      FROM commander_home_groups g
     WHERE g.owner_id = p_caller_user_id
  ),
  memberships AS (
    SELECT g.id, g.name, g.owner_id, g.is_private, g.is_21_plus,
           g.member_count, g.profile_photo_url, g.city, g.created_at,
           m.role AS m_role, m.status AS m_status,
           m.joined_at, m.last_attended, m.last_read_posts_at
      FROM commander_home_members m
      JOIN commander_home_groups g ON g.id = m.group_id
     WHERE m.user_id = p_caller_user_id
       AND m.status IN ('approved','pending')
  ),
  union_set AS (
    SELECT o.id AS group_id, o.name, o.owner_id, o.is_private, o.is_21_plus,
           o.member_count, o.profile_photo_url, o.city,
           'owner'::text AS role, 'approved'::text AS status, true AS is_owner,
           o.created_at AS joined_at,
           NULL::timestamptz AS last_attended, NULL::timestamptz AS last_read_posts_at
      FROM owned o
    UNION
    SELECT m.id, m.name, m.owner_id, m.is_private, m.is_21_plus,
           m.member_count, m.profile_photo_url, m.city,
           m.m_role, m.m_status, (m.owner_id = p_caller_user_id),
           m.joined_at, m.last_attended, m.last_read_posts_at
      FROM memberships m
  ),
  games_with_starts AS (
    SELECT gm.group_id,
           CASE
             WHEN gm.scheduled_date IS NOT NULL AND gm.start_time IS NOT NULL THEN
               (gm.scheduled_date || ' ' || gm.start_time)::timestamp
                 AT TIME ZONE COALESCE(gm.timezone, 'UTC')
             WHEN gm.scheduled_date IS NOT NULL THEN
               (gm.scheduled_date || ' 19:00:00')::timestamp
                 AT TIME ZONE COALESCE(gm.timezone, 'UTC')
             ELSE NULL
           END AS starts_at
      FROM commander_home_games gm
     WHERE gm.status IN ('scheduled','confirmed')
  ),
  next_game_per_group AS (
    SELECT DISTINCT ON (gs.group_id) gs.group_id, gs.starts_at AS next_game_at
      FROM games_with_starts gs
     WHERE gs.starts_at IS NOT NULL AND gs.starts_at > NOW()
     ORDER BY gs.group_id, gs.starts_at ASC
  ),
  sp_slug AS (
    SELECT sp.linked_entity_id::uuid AS sp_group_id, sp.slug AS sp_slug_val
      FROM public.social_pages sp
     WHERE sp.linked_entity_type = 'home_group'
  )
  SELECT 'home_group'::text           AS kind,
         u.group_id                   AS hg_group_id,
         u.name::text                 AS hg_name,
         ss.sp_slug_val::text         AS hg_slug,
         u.role                       AS hg_role,
         u.status                     AS hg_status,
         u.is_owner,
         u.is_private,
         u.is_21_plus,
         u.member_count,
         u.profile_photo_url::text,
         u.city::text,
         ng.next_game_at,
         COALESCE(
           (SELECT COUNT(*)::integer FROM commander_home_posts p
             WHERE p.group_id = u.group_id
               AND p.is_hidden = false
               AND p.created_at > COALESCE(u.last_read_posts_at, u.joined_at, 'epoch'::timestamptz)),
           0
         ) AS unread_posts,
         u.joined_at,
         u.last_attended
    FROM union_set u
    LEFT JOIN next_game_per_group ng ON ng.group_id   = u.group_id
    LEFT JOIN sp_slug             ss ON ss.sp_group_id = u.group_id
   ORDER BY u.is_owner DESC, u.name ASC;
END;
$$;


ALTER FUNCTION public.fn_list_my_home_memberships(p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: fn_list_my_post_targets(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_list_my_post_targets() RETURNS TABLE(kind text, target_id uuid, target_name text, target_slug text, target_avatar text, target_role text, social_page_id uuid, sort_order integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT * FROM (
    -- Personal: post as self
    SELECT 'personal'::text AS kind,
           p.id AS target_id,
           COALESCE(p.display_name, p.full_name, p.username, 'Me')::text AS target_name,
           p.username::text AS target_slug,
           p.avatar_url::text AS target_avatar,
           'owner'::text AS target_role,
           NULL::uuid AS social_page_id,
           0 AS sort_order
      FROM public.profiles p
     WHERE p.id = v_uid

    UNION ALL

    -- Clubs: post as Club Page
    SELECT 'club',
           c.id, c.name::text, c.slug::text, c.logo_url::text, cm.role::text,
           (SELECT sp.id FROM public.social_pages sp
             WHERE sp.linked_entity_type='club' AND sp.linked_entity_id = c.id::text LIMIT 1),
           1
      FROM public.club_members cm
      JOIN public.clubs c ON c.id = cm.club_id
     WHERE cm.user_id = v_uid
       AND cm.role IN ('owner','co_owner','admin','operator','manager')
       AND COALESCE(cm.is_active, true) = true

    UNION ALL

    -- Home groups: translate owner→host for UI consistency with rest of HG launch
    SELECT 'home_group',
           g.id, g.name::text, sp.slug::text, g.profile_photo_url::text,
           (CASE
              WHEN g.owner_id = v_uid THEN 'host'
              ELSE m.role
            END)::text,
           sp.id, 2
      FROM public.commander_home_groups g
      LEFT JOIN public.commander_home_members m
             ON m.group_id = g.id AND m.user_id = v_uid
            AND m.status = 'approved' AND m.role IN ('admin','co_host')
      LEFT JOIN public.social_pages sp
             ON sp.linked_entity_type='home_group' AND sp.linked_entity_id = g.id::text
     WHERE (g.owner_id = v_uid OR m.id IS NOT NULL)
  ) t
  ORDER BY t.sort_order ASC, t.target_name ASC;
END;
$$;


ALTER FUNCTION public.fn_list_my_post_targets() OWNER TO postgres;

--
-- Name: fn_list_pending_members(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_list_pending_members(p_club_id uuid) RETURNS TABLE(user_id uuid, role text, status text, created_at timestamp with time zone, username text, display_name text, avatar_url text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF NOT is_club_admin(p_club_id, auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  RETURN QUERY
    SELECT cm.user_id,
           cm.role::text,
           cm.status,
           cm.created_at,
           p.username,
           public.fn_arena_name(p.alias, p.username, p.display_name,
                                p.first_name, p.last_name, p.full_name),
           p.avatar_url
    FROM club_members cm
    LEFT JOIN profiles p ON p.id = cm.user_id
    WHERE cm.club_id = p_club_id AND cm.status = 'pending'
    ORDER BY cm.created_at DESC;
END;
$$;


ALTER FUNCTION public.fn_list_pending_members(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_list_player_reports(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_list_player_reports(p_status text DEFAULT NULL::text, p_club_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, reporter_id uuid, reported_user_id uuid, reason text, details text, status text, admin_notes text, created_at timestamp with time zone, reviewed_at timestamp with time zone, reviewed_by uuid, reporter_username text, reported_username text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_scope uuid[];
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RETURN; END IF;

  -- The club and every club in its union scope, exactly as the cashier, the
  -- vault and the roster read "this club".
  IF p_club_id IS NOT NULL THEN
    v_scope := public.fn_club_scope_ids(p_club_id);
  END IF;

  RETURN QUERY
    SELECT ur.id, ur.reporter_id, ur.reported_user_id, ur.reason, ur.details,
           ur.status, ur.admin_notes, ur.created_at, ur.reviewed_at, ur.reviewed_by,
           rep.username AS reporter_username,
           tgt.username AS reported_username
    FROM user_reports ur
    LEFT JOIN profiles rep ON rep.id = ur.reporter_id
    LEFT JOIN profiles tgt ON tgt.id = ur.reported_user_id
    WHERE public.fn_caller_can_moderate_user(ur.reported_user_id)
      AND (p_status IS NULL OR p_status = 'all'
           OR (p_status = 'pending' AND ur.status = 'pending')
           OR (p_status = 'reviewed' AND ur.status <> 'pending'))
      AND (v_scope IS NULL OR EXISTS (
            SELECT 1 FROM public.club_members cm
             WHERE cm.user_id = ur.reported_user_id
               AND cm.club_id = ANY (v_scope)))
    ORDER BY ur.created_at DESC
    LIMIT 100;
END;
$$;


ALTER FUNCTION public.fn_list_player_reports(p_status text, p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_list_player_reports(p_status text, p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_list_player_reports(p_status text, p_club_id uuid) IS 'Player reports the caller may moderate, narrowed to one club and its union scope when p_club_id is given. The club surface shows per-club counts and used to call the unscoped form, so an operator running four clubs saw one pooled queue under all four headers.';


--
-- Name: fn_list_user_public_home_groups(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_list_user_public_home_groups(p_target_user_id uuid, p_limit integer DEFAULT 20) RETURNS TABLE(group_id uuid, group_name text, group_slug text, relationship text, city text, member_count integer, profile_photo_url text, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  p_limit := GREATEST(1, LEAST(COALESCE(p_limit, 20), 100));

  RETURN QUERY
  SELECT t.u_group_id, t.u_group_name, t.u_group_slug, t.u_relationship,
         t.u_city, t.u_member_count, t.u_profile_photo_url, t.u_created_at
  FROM (
    SELECT g.id                        AS u_group_id,
           g.name::text                AS u_group_name,
           sp.slug::text               AS u_group_slug,
           'owner'::text               AS u_relationship,
           g.city::text                AS u_city,
           g.member_count              AS u_member_count,
           g.profile_photo_url::text   AS u_profile_photo_url,
           g.created_at                AS u_created_at
      FROM public.commander_home_groups g
      LEFT JOIN public.social_pages sp
        ON sp.linked_entity_type='home_group' AND sp.linked_entity_id = g.id::text
     WHERE g.owner_id = p_target_user_id
       AND g.is_private = false
       AND COALESCE(g.is_active, true) = true
    UNION
    SELECT g.id, g.name::text, sp.slug::text, m.role::text,
           g.city::text, g.member_count, g.profile_photo_url::text, g.created_at
      FROM public.commander_home_members m
      JOIN public.commander_home_groups g ON g.id = m.group_id
      LEFT JOIN public.social_pages sp
        ON sp.linked_entity_type='home_group' AND sp.linked_entity_id = g.id::text
     WHERE m.user_id = p_target_user_id
       AND m.status = 'approved'
       AND m.role IN ('admin','co_host')
       AND g.owner_id <> p_target_user_id
       AND g.is_private = false
       AND COALESCE(g.is_active, true) = true
  ) t
  ORDER BY
    CASE t.u_relationship WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END,
    t.u_created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.fn_list_user_public_home_groups(p_target_user_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: fn_live_streams_guard_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_live_streams_guard_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  is_end_user boolean := current_user = 'authenticated';
BEGIN
  -- broadcaster_id immutable for ALL callers
  IF NEW.broadcaster_id IS DISTINCT FROM OLD.broadcaster_id THEN
    RAISE EXCEPTION 'broadcaster_id is immutable'
      USING ERRCODE = '42501';
  END IF;

  -- Metric columns are SERVER-managed only (RPC path with SECURITY DEFINER
  -- runs as the function owner, not 'authenticated', so RPC writes pass).
  -- Direct end-user UPDATEs cannot touch these - they are the clout-fraud
  -- vectors (a broadcaster could otherwise set viewer_count = 1_000_000).
  IF is_end_user THEN
    IF NEW.viewer_count    IS DISTINCT FROM OLD.viewer_count    THEN
      RAISE EXCEPTION 'viewer_count is server-managed (use update_live_metrics RPC)'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.peak_viewers    IS DISTINCT FROM OLD.peak_viewers    THEN
      RAISE EXCEPTION 'peak_viewers is server-managed (use update_live_metrics RPC)'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.reaction_count  IS DISTINCT FROM OLD.reaction_count  THEN
      RAISE EXCEPTION 'reaction_count is server-managed'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- status, ended_at, started_at, livekit_room: ALLOWED from broadcaster.
  -- The RLS UPDATE policy already constrains these to broadcaster_id =
  -- auth.uid(), so a broadcaster can only mutate their own stream.

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_live_streams_guard_update() OWNER TO postgres;

--
-- Name: FUNCTION fn_live_streams_guard_update(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_live_streams_guard_update() IS 'Guards live_streams UPDATEs. broadcaster_id immutable for all callers. End-user authenticated role cannot mutate metric columns (viewer_count, peak_viewers, reaction_count) — those go through update_live_metrics RPC. status/ended_at/started_at/livekit_room remain broadcaster-writable for normal start/end flow.';


--
-- Name: fn_live_table_count(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_live_table_count(p_club_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT count(*)::int
    FROM tables t
   WHERE t.tournament_id IS NULL
     AND t.is_deleted IS NOT TRUE
     AND t.status NOT IN ('closed', 'deleted')
     AND (
       -- the club's own games (private club games included)
       t.club_id = p_club_id
       -- plus the union's games, if this club belongs to one
       OR t.union_id = (SELECT uc.union_id FROM union_clubs uc
                         WHERE uc.club_id = p_club_id LIMIT 1)
       -- the union's own container row: its games are keyed by union_id
       OR t.union_id = p_club_id
     );
$$;


ALTER FUNCTION public.fn_live_table_count(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_lock_daily_mission_user(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lock_daily_mission_user(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'A Daily Missions player is required';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('daily-missions-user:' || p_user_id::text, 0)
  );

  PERFORM 1
  FROM public.profiles
  WHERE id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Daily Missions profile not found for player %', p_user_id;
  END IF;
END;
$$;


ALTER FUNCTION public.fn_lock_daily_mission_user(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_lock_daily_mission_user(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lock_daily_mission_user(p_user_id uuid) IS 'Private transaction-scoped Daily Missions player mutex. It locks profiles before assignment, streak, wallet, and revision rows so every path uses one deadlock-safe order.';


--
-- Name: fn_lock_tournament_launch_proof_parents(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lock_tournament_launch_proof_parents(p_tournament_ids uuid[]) RETURNS TABLE(tournament_id uuid, parent_status text, launch_id uuid, launch_lease_generation uuid, launch_completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ids uuid[];
BEGIN
  SELECT array_agg(DISTINCT requested.id ORDER BY requested.id)
    INTO v_ids
    FROM unnest(p_tournament_ids) AS requested(id)
   WHERE requested.id IS NOT NULL;

  IF v_ids IS NULL THEN
    RETURN;
  END IF;

  /* Do not invert these two blocks.  Launch completion already owns receipt
     -> parent, and every child must join that order. */
  /* A few legacy RPCs entered with the tournament parent already locked.
     Waiting for a receipt owned by completion would make a cycle: completion
     waits for their parent while they wait for its receipt.  Fail that outer
     transaction as retryable instead of waiting; a clean retry enters this
     helper before touching another launch-proof row. */
  BEGIN
    PERFORM 1
      FROM public.tournament_launch_receipts r
     WHERE r.tournament_id = ANY(v_ids)
     ORDER BY r.tournament_id
     FOR UPDATE NOWAIT;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION
      'TOURNAMENT_TRANSITION_BUSY: launch proof receipt is changing'
      USING ERRCODE = '40001';
  END;

  PERFORM 1
    FROM public.tournaments t
   WHERE t.id = ANY(v_ids)
   ORDER BY t.id
   FOR UPDATE;

  IF EXISTS (
    SELECT 1
      FROM unnest(v_ids) AS requested(id)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.tournaments t WHERE t.id = requested.id
     )
  ) THEN
    RAISE EXCEPTION 'tournament launch proof child names a missing parent'
      USING ERRCODE = '23503';
  END IF;

  RETURN QUERY
    SELECT t.id,
           t.status::text,
           r.launch_id,
           r.lease_generation,
           r.completed_at
      FROM public.tournaments t
      LEFT JOIN public.tournament_launch_receipts r
        ON r.tournament_id = t.id
     WHERE t.id = ANY(v_ids)
     ORDER BY t.id;
END;
$$;


ALTER FUNCTION public.fn_lock_tournament_launch_proof_parents(p_tournament_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_log_admin_action(uuid, text, text, text, jsonb, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_log_admin_action(p_admin_user_id uuid, p_action text, p_target_type text DEFAULT NULL::text, p_target_id text DEFAULT NULL::text, p_details jsonb DEFAULT '{}'::jsonb, p_before_state jsonb DEFAULT NULL::jsonb, p_after_state jsonb DEFAULT NULL::jsonb, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_role text;
BEGIN
  IF p_admin_user_id IS NULL THEN
    RAISE EXCEPTION 'admin_user_id required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF p_action IS NULL OR length(trim(p_action)) = 0 THEN
    RAISE EXCEPTION 'action required' USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT role INTO v_role FROM public.profiles WHERE id = p_admin_user_id;

  INSERT INTO public.admin_audit_log (
    admin_user_id, action, target_type, target_id,
    details, before_state, after_state,
    ip_address, user_agent, actor_role, request_id
  ) VALUES (
    p_admin_user_id, p_action, p_target_type, p_target_id,
    COALESCE(p_details, '{}'::jsonb), p_before_state, p_after_state,
    p_ip_address, p_user_agent, v_role, p_request_id
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


