--
-- Name: fn_log_seat_stack_exit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_log_seat_stack_exit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_stack numeric;
  v_kind  text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- A departed seat being tidied up is not an exit: its stack left when
    -- left_at was stamped, and that is already recorded below.
    IF OLD.left_at IS NOT NULL THEN RETURN OLD; END IF;
    v_stack := COALESCE(OLD.stack, 0);
    v_kind  := 'deleted';
  ELSE
    IF OLD.left_at IS NOT NULL OR NEW.left_at IS NULL THEN RETURN NEW; END IF;
    v_stack := COALESCE(OLD.stack, 0);
    v_kind  := 'left';
  END IF;

  IF v_stack <= 0 THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- CASH ONLY. A tournament stack is play money inside the event -- it credits
  -- no wallet when the seat ends, so it cannot be lost in the sense this table
  -- exists to detect. Filtering HERE rather than in the report keeps ~2,000
  -- meaningless rows an hour out of the audit trail entirely.
  IF EXISTS (SELECT 1 FROM public.tables t
              WHERE t.id = OLD.table_id AND t.tournament_id IS NOT NULL) THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  INSERT INTO public.ca_seat_stack_exits
    (seat_id, table_id, user_id, club_id, seat_number, stack, exit_kind, db_role, app_name)
  VALUES (OLD.id, OLD.table_id, OLD.user_id, OLD.club_id, OLD.seat_number,
          v_stack, v_kind, current_user,
          NULLIF(current_setting('application_name', true), ''));

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.fn_log_seat_stack_exit() OWNER TO postgres;

--
-- Name: fn_maintenance_break_state(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_maintenance_break_state() RETURNS TABLE(phase text, break_ends_at timestamp with time zone, remaining_ms integer, reason text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH candidate AS (
    SELECT b.phase,
           CASE
             WHEN b.phase = 'last_hand' THEN b.announced_at + INTERVAL '7 minutes'
             ELSE b.break_ends_at
           END AS effective_end,
           b.announced_at,
           b.reason
      FROM public.engine_maintenance_break b
     WHERE b.enforce_freeze
  )
  SELECT c.phase,
         c.effective_end,
         GREATEST(
           0,
           LEAST(
             15 * 60 * 1000,
             EXTRACT(EPOCH FROM (c.effective_end - NOW())) * 1000
           )
         )::integer,
         c.reason
    FROM candidate c
   WHERE c.effective_end > NOW()
     AND c.effective_end < NOW() + INTERVAL '15 minutes'
     AND (
       c.phase <> 'last_hand'
       OR c.announced_at < NOW() + INTERVAL '30 seconds'
     );
$$;


ALTER FUNCTION public.fn_maintenance_break_state() OWNER TO postgres;

--
-- Name: FUNCTION fn_maintenance_break_state(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_maintenance_break_state() IS 'The live maintenance break and its absolute announcement-anchored end. Last-hand and countdown state self-expire at the same instant used by the engine entry freeze.';


--
-- Name: fn_maintenance_week_report(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_maintenance_week_report(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v JSONB;
BEGIN
  SELECT jsonb_build_object(
    'window_days', p_days,
    'generated_at', NOW(),

    -- The thaw ledger is the authoritative record of armed freezes.
    'freezes', (
      SELECT jsonb_build_object(
        'count', COUNT(*),
        'avg_frozen_seconds', ROUND(AVG(frozen_seconds)::numeric, 1),
        'max_frozen_seconds', MAX(frozen_seconds),
        'min_frozen_seconds', MIN(frozen_seconds),
        -- A healthy freeze is ~300s. Anything past 360 means the countdown
        -- was adopted late or an engine wedged; worth reading the engine log
        -- for that hour.
        'over_360s', COUNT(*) FILTER (WHERE frozen_seconds > 360),
        'total_shifted', (
          SELECT jsonb_object_agg(k, s) FROM (
            SELECT k, SUM((t.shifted ->> k)::bigint) AS s
            FROM public.engine_maintenance_thaws t,
                 LATERAL jsonb_object_keys(t.shifted) k
            WHERE t.thawed_at > NOW() - make_interval(days => p_days)
            GROUP BY k
          ) agg
        )
      )
      FROM public.engine_maintenance_thaws
      WHERE thawed_at > NOW() - make_interval(days => p_days)
    ),

    -- How invisible is the restart really? Compare dealing volume in the
    -- five break minutes against the five minutes either side, averaged over
    -- the window. The break minutes SHOULD be ~zero (that is the freeze);
    -- what matters is minutes :00-:04 recovering to par with :48-:52 - a
    -- slow recovery means rehydration is creeping up.
    'dealing_by_minute', (
      SELECT jsonb_object_agg(bucket, hands) FROM (
        SELECT
          CASE
            WHEN EXTRACT(minute FROM created_at) BETWEEN 48 AND 52 THEN 'before_48_52'
            WHEN EXTRACT(minute FROM created_at) BETWEEN 53 AND 54 THEN 'last_hand_53_54'
            WHEN EXTRACT(minute FROM created_at) >= 55 THEN 'break_55_59'
            WHEN EXTRACT(minute FROM created_at) <= 4 THEN 'after_00_04'
            ELSE NULL
          END AS bucket,
          COUNT(*) AS hands
        FROM public.hand_history
        WHERE created_at > NOW() - make_interval(days => p_days)
        GROUP BY 1
      ) b WHERE bucket IS NOT NULL
    ),

    -- Breaks that were declared but never thawed: an engine died after :55
    -- and nothing called fn_thaw_platform. Should be zero; each one is an
    -- hour whose clocks silently lost their frozen minutes.
    'breaks_without_thaw_note',
      'compare freezes.count against 24*window_days minus deploy-skipped hours; a shortfall beyond dropped cron ticks means end() or the thaw is failing'
  ) INTO v;
  RETURN v;
END;
$$;


ALTER FUNCTION public.fn_maintenance_week_report(p_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_maintenance_week_report(p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_maintenance_week_report(p_days integer) IS 'The maintenance break''s weekly self-report: freeze counts and durations, thaw shift totals, and the hourly dealing dip shape. Read-only; feeds the first-week trend review (club-arena to-do #2563 item 16).';


--
-- Name: fn_manage_club_announcement(text, uuid, uuid, text, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_manage_club_announcement(p_action text, p_club_id uuid, p_announcement_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_content text DEFAULT NULL::text, p_is_pinned boolean DEFAULT false, p_is_active boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid:=auth.uid(); v_id uuid:=p_announcement_id; v_title text; v_content text;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_can_create_games(p_club_id,v_uid) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized');
  END IF;
  IF p_action='delete' THEN
    DELETE FROM public.club_announcements WHERE id=v_id AND club_id=p_club_id;
    RETURN jsonb_build_object('ok',FOUND);
  ELSIF p_action='set_pin' THEN
    UPDATE public.club_announcements SET is_pinned=p_is_pinned,updated_at=now() WHERE id=v_id AND club_id=p_club_id;
    RETURN jsonb_build_object('ok',FOUND);
  ELSIF p_action='set_active' THEN
    UPDATE public.club_announcements SET is_active=p_is_active,updated_at=now() WHERE id=v_id AND club_id=p_club_id;
    RETURN jsonb_build_object('ok',FOUND);
  ELSIF p_action<>'save' THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_action');
  END IF;
  IF char_length(COALESCE(p_title,''))>100 OR char_length(COALESCE(p_content,''))>2000 THEN
    RETURN jsonb_build_object('ok',false,'reason','character_limit');
  END IF;
  v_title:=trim(regexp_replace(COALESCE(p_title,''),'[\r\n\t ]+',' ','g'));
  v_content:=trim(COALESCE(p_content,''));
  IF v_title='' OR v_content='' THEN RETURN jsonb_build_object('ok',false,'reason','message_required'); END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.club_announcements(club_id,author_id,created_by,title,content,message,is_pinned,is_active)
    VALUES(p_club_id,v_uid,v_uid,v_title,v_content,v_content,p_is_pinned,p_is_active) RETURNING id INTO v_id;
  ELSE
    UPDATE public.club_announcements SET title=v_title,content=v_content,message=v_content,is_pinned=p_is_pinned,is_active=p_is_active,updated_at=now()
      WHERE id=v_id AND club_id=p_club_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','announcement_not_found'); END IF;
  END IF;
  RETURN jsonb_build_object('ok',true,'id',v_id);
END $$;


ALTER FUNCTION public.fn_manage_club_announcement(p_action text, p_club_id uuid, p_announcement_id uuid, p_title text, p_content text, p_is_pinned boolean, p_is_active boolean) OWNER TO postgres;

--
-- Name: fn_manage_club_announcement_versioned(text, uuid, uuid, bigint, text, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_manage_club_announcement_versioned(p_action text, p_club_id uuid, p_announcement_id uuid DEFAULT NULL::uuid, p_expected_revision bigint DEFAULT 0, p_title text DEFAULT NULL::text, p_content text DEFAULT NULL::text, p_is_pinned boolean DEFAULT false, p_is_active boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid := p_announcement_id;
  v_current_revision bigint;
  v_title text;
  v_content text;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_can_create_games(p_club_id, v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;
  IF p_action NOT IN ('save', 'delete', 'set_pin', 'set_active') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_action');
  END IF;
  IF v_id IS NOT NULL THEN
    SELECT management_revision INTO v_current_revision
      FROM public.club_announcements
      WHERE id = v_id AND club_id = p_club_id
      FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'announcement_not_found');
    END IF;
    IF v_current_revision <> p_expected_revision THEN
      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'version_conflict',
        'current_revision', v_current_revision
      );
    END IF;
  ELSIF p_action <> 'save' OR p_expected_revision <> 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_payload');
  END IF;

  IF p_action = 'delete' THEN
    DELETE FROM public.club_announcements WHERE id = v_id AND club_id = p_club_id;
    RETURN jsonb_build_object('ok', true, 'id', v_id);
  ELSIF p_action = 'set_pin' THEN
    UPDATE public.club_announcements
      SET is_pinned = p_is_pinned,
          management_revision = management_revision + 1,
          updated_at = now()
      WHERE id = v_id AND club_id = p_club_id
      RETURNING management_revision INTO v_current_revision;
    RETURN jsonb_build_object('ok', true, 'id', v_id, 'revision', v_current_revision);
  ELSIF p_action = 'set_active' THEN
    UPDATE public.club_announcements
      SET is_active = p_is_active,
          management_revision = management_revision + 1,
          updated_at = now()
      WHERE id = v_id AND club_id = p_club_id
      RETURNING management_revision INTO v_current_revision;
    RETURN jsonb_build_object('ok', true, 'id', v_id, 'revision', v_current_revision);
  END IF;

  IF char_length(COALESCE(p_title, '')) > 100
    OR char_length(COALESCE(p_content, '')) > 2000 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'character_limit');
  END IF;
  v_title := trim(regexp_replace(COALESCE(p_title, ''), '[\r\n\t ]+', ' ', 'g'));
  v_content := trim(COALESCE(p_content, ''));
  IF v_title = '' OR v_content = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'message_required');
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.club_announcements(
      club_id, author_id, created_by, title, content, message,
      is_pinned, is_active, management_revision
    ) VALUES (
      p_club_id, v_uid, v_uid, v_title, v_content, v_content,
      p_is_pinned, p_is_active, 1
    ) RETURNING id, management_revision INTO v_id, v_current_revision;
  ELSE
    UPDATE public.club_announcements
      SET title = v_title,
          content = v_content,
          message = v_content,
          is_pinned = p_is_pinned,
          is_active = p_is_active,
          management_revision = management_revision + 1,
          updated_at = now()
      WHERE id = v_id AND club_id = p_club_id
      RETURNING management_revision INTO v_current_revision;
  END IF;
  RETURN jsonb_build_object('ok', true, 'id', v_id, 'revision', v_current_revision);
END $$;


ALTER FUNCTION public.fn_manage_club_announcement_versioned(p_action text, p_club_id uuid, p_announcement_id uuid, p_expected_revision bigint, p_title text, p_content text, p_is_pinned boolean, p_is_active boolean) OWNER TO postgres;

