-- Name: FUNCTION fn_manage_club_announcement_versioned(p_action text, p_club_id uuid, p_announcement_id uuid, p_expected_revision bigint, p_title text, p_content text, p_is_pinned boolean, p_is_active boolean); Type: COMMENT; Schema: public; Owner: postgres
