--
-- Name: fn_mark_feed_post_ended(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mark_feed_post_ended(p_stream_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_post_id uuid;
  v_via_fk boolean := false;
BEGIN
  -- Path 1: direct FK lookup via live_streams.feed_post_id
  SELECT s.feed_post_id
    INTO v_post_id
    FROM public.live_streams s
   WHERE s.id = p_stream_id
   LIMIT 1;

  IF v_post_id IS NOT NULL THEN
    v_via_fk := true;
  ELSE
    -- Path 2: legacy fallback - find by metadata.stream_id JSONB scan
    SELECT sp.id
      INTO v_post_id
      FROM public.social_posts sp
     WHERE sp.content_type = 'live'
       AND sp.metadata @> jsonb_build_object('stream_id', p_stream_id::text)
     LIMIT 1;
  END IF;

  IF v_post_id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'matched', 0);
  END IF;

  -- Atomic JSONB merge: existing metadata wins for every key except `ended`,
  -- which we force to true.
  UPDATE public.social_posts
     SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('ended', true)
   WHERE id = v_post_id;

  RETURN jsonb_build_object('success', true, 'matched', 1, 'via_fk', v_via_fk);
END;
$$;


ALTER FUNCTION public.fn_mark_feed_post_ended(p_stream_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_mark_feed_post_ended(p_stream_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_mark_feed_post_ended(p_stream_id uuid) IS 'Atomically merges {ended: true} into the feed post for a stream. Replaces three separate {fetch, merge, update} call sites in /api/live/end-stream, /api/live/cleanup-stale, /api/cron/cleanup-stale-streams. Fixes CSS-1: those handlers were overwriting metadata with the wrong key (stream_status instead of ended).';


