--
-- Name: fn_mark_table_setting_touched(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mark_table_setting_touched(p_columns text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_valid text[];
BEGIN
  IF v_uid IS NULL OR p_columns IS NULL OR array_length(p_columns, 1) IS NULL THEN
    RETURN;
  END IF;

  SELECT array_agg(DISTINCT c)
    INTO v_valid
    FROM unnest(p_columns) AS c
   WHERE c IN (
     SELECT a.attname::text
       FROM pg_attribute a
      WHERE a.attrelid = 'public.user_table_settings'::regclass
        AND a.attnum > 0
        AND NOT a.attisdropped
        AND a.attname NOT IN ('user_id', 'created_at', 'updated_at', 'settings_touched')
   );

  IF v_valid IS NULL THEN
    RETURN;
  END IF;

  UPDATE public.user_table_settings t
     SET settings_touched = (
           SELECT array_agg(DISTINCT e)
             FROM unnest(t.settings_touched || v_valid) AS e
         )
   WHERE t.user_id = v_uid;
END
$$;


ALTER FUNCTION public.fn_mark_table_setting_touched(p_columns text[]) OWNER TO postgres;

--
-- Name: FUNCTION fn_mark_table_setting_touched(p_columns text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_mark_table_setting_touched(p_columns text[]) IS 'Record that the signed-in user deliberately set these settings columns. Idempotent, whitelisted against the table catalog, and scoped to auth.uid(). Called after a successful per-key upsert from useTableSettings / useUserTableSettings.';


--
-- Name: fn_materialize_satellite_entitlements_locked(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_materialize_satellite_entitlements_locked(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_hint record;
  v_t public.tournaments%ROWTYPE;
  v_target public.tournaments%ROWTYPE;
  v_economics public.tournament_satellite_economic_snapshots%ROWTYPE;
  v_receipt public.tournament_entry_close_receipts%ROWTYPE;
  v_is_satellite boolean;
  v_field integer;
  v_pool numeric;
  v_ticket numeric := 0;
  v_configured integer;
  v_seats integer := 0;
  v_remainder numeric := 0;
  v_remainder_position integer;
  v_expected_depth integer := 0;
  v_existing integer;
  v_bad integer;
  i integer;
BEGIN
  SELECT t.id,t.satellite_target_id,t.variant,t.tournament_type
    INTO v_hint FROM public.tournaments t WHERE t.id=p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  v_is_satellite := lower(COALESCE(v_hint.variant,''))='satellite'
    OR upper(COALESCE(v_hint.tournament_type,''))='SATELLITE'
    OR v_hint.satellite_target_id IS NOT NULL;
  IF NOT v_is_satellite THEN
    RETURN jsonb_build_object('ok',true,'is_satellite',false,'ready',true,
                              'award_depth',0);
  END IF;
  IF v_hint.satellite_target_id=p_tournament_id THEN
    RETURN jsonb_build_object('ok',false,'is_satellite',true,
                              'reason','satellite_targets_itself');
  END IF;

  SELECT * INTO v_economics
    FROM public.tournament_satellite_economic_snapshots e
   WHERE e.tournament_id=p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'is_satellite',true,'ready',false,
                              'reason','start_economics_unproven');
  END IF;

  -- Global lock order: frozen target, then source. FOR UPDATE (not FOR KEY SHARE)
  -- conflicts with every registration and completion writer and avoids a
  -- lock-upgrade deadlock between two lazy materializers/finalizers.
  IF v_economics.target_tournament_id IS NOT NULL THEN
    SELECT * INTO v_target FROM public.tournaments
     WHERE id=v_economics.target_tournament_id FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok',false,'is_satellite',true,'ready',false,
                                'reason','frozen_target_missing');
    END IF;
  END IF;
  SELECT * INTO v_t FROM public.tournaments
   WHERE id=p_tournament_id FOR UPDATE;
  IF v_t.satellite_target_id IS DISTINCT FROM v_economics.target_tournament_id
     OR GREATEST(COALESCE(v_t.satellite_seats,0),0)<>v_economics.configured_seats THEN
    RETURN jsonb_build_object('ok',false,'is_satellite',true,'ready',false,
                              'reason','frozen_source_contract_changed');
  END IF;

  SELECT * INTO v_receipt FROM public.tournament_entry_close_receipts
   WHERE tournament_id=p_tournament_id;
  IF NOT FOUND OR NOT COALESCE(v_t.prize_pool_finalized,false) THEN
    RETURN jsonb_build_object('ok',true,'is_satellite',true,'ready',false,
                              'reason','entry_window_not_finalized');
  END IF;
  v_pool:=round(v_receipt.final_prize_pool,2);
  IF round(COALESCE(v_t.prize_pool,0),2)<>v_pool
     AND NOT EXISTS (SELECT 1 FROM public.tournament_satellite_entitlements e
                      WHERE e.tournament_id=p_tournament_id) THEN
    RETURN jsonb_build_object('ok',false,'is_satellite',true,'ready',false,
                              'reason','final_pool_changed_before_plan');
  END IF;
  SELECT count(*)::integer INTO v_field FROM public.tournament_players
   WHERE tournament_id=p_tournament_id;
  IF v_field<1 THEN
    RETURN jsonb_build_object('ok',false,'is_satellite',true,'ready',false,
                              'reason','final_field_unreadable');
  END IF;
  v_ticket:=v_economics.ticket_value;
  v_configured:=v_economics.configured_seats;
  IF v_ticket>0 THEN
    v_seats:=LEAST(v_field,GREATEST(v_configured,floor(v_pool/v_ticket)::integer));
  END IF;
  IF v_pool+0.005<round(LEAST(v_field,v_configured)*v_ticket,2) THEN
    RETURN jsonb_build_object('ok',false,'is_satellite',true,'ready',false,
                              'reason','frozen_satellite_guarantee_unfunded',
                              'final_pool',v_pool,'promised_minimum',
                              round(LEAST(v_field,v_configured)*v_ticket,2));
  END IF;
  v_remainder:=GREATEST(round(v_pool-v_seats*v_ticket,2),0);
  IF v_seats>0 THEN
    v_remainder_position:=CASE WHEN v_remainder>0
      THEN LEAST(v_seats+1,v_field) ELSE NULL END;
    v_expected_depth:=v_seats+CASE WHEN v_remainder_position>v_seats THEN 1 ELSE 0 END;
  ELSIF v_pool>0 THEN
    v_remainder_position:=1;
    v_expected_depth:=1;
  END IF;

  SELECT count(*)::integer INTO v_existing
    FROM public.tournament_satellite_entitlements e
   WHERE e.tournament_id=p_tournament_id;
  IF v_existing=0 THEN
    IF v_seats>0 THEN
      FOR i IN 1..v_seats LOOP
        INSERT INTO public.tournament_satellite_entitlements(
          tournament_id,position,target_tournament_id,award_kind,ticket_value,
          remainder_value,source_pool,entry_closed_at)
        VALUES (p_tournament_id,i,v_economics.target_tournament_id,'seat_or_cash',v_ticket,
          CASE WHEN v_remainder_position=i THEN v_remainder ELSE 0 END,
          v_pool,v_receipt.entry_closed_at);
      END LOOP;
      IF v_remainder_position>v_seats THEN
        INSERT INTO public.tournament_satellite_entitlements(
          tournament_id,position,target_tournament_id,award_kind,ticket_value,
          remainder_value,source_pool,entry_closed_at)
        VALUES (p_tournament_id,v_remainder_position,NULL,'cash',0,v_remainder,
                v_pool,v_receipt.entry_closed_at);
      END IF;
    ELSIF v_pool>0 THEN
      INSERT INTO public.tournament_satellite_entitlements(
        tournament_id,position,target_tournament_id,award_kind,ticket_value,
        remainder_value,source_pool,entry_closed_at)
      VALUES (p_tournament_id,1,NULL,'cash',0,v_pool,v_pool,
              v_receipt.entry_closed_at);
    END IF;
  END IF;

  SELECT count(*)::integer INTO v_bad
    FROM public.tournament_satellite_entitlements e
   WHERE e.tournament_id=p_tournament_id
     AND (
       e.position>v_expected_depth
       OR e.source_pool<>v_pool
       OR e.entry_closed_at<>v_receipt.entry_closed_at
       OR (e.position<=v_seats AND (
            e.award_kind<>'seat_or_cash'
            OR e.target_tournament_id IS DISTINCT FROM v_economics.target_tournament_id
            OR e.ticket_value<>v_ticket
            OR e.remainder_value<>CASE WHEN e.position=v_remainder_position
                                       THEN v_remainder ELSE 0 END))
       OR (e.position>v_seats AND (
            e.award_kind<>'cash' OR e.target_tournament_id IS NOT NULL
            OR e.ticket_value<>0 OR e.remainder_value<>v_remainder))
     );
  IF v_bad>0
     OR (SELECT count(*) FROM public.tournament_satellite_entitlements e
          WHERE e.tournament_id=p_tournament_id)<>v_expected_depth
     OR (v_expected_depth>0 AND (
          SELECT count(*) FROM generate_series(1,v_expected_depth) expected(position)
           WHERE NOT EXISTS (
             SELECT 1 FROM public.tournament_satellite_entitlements e
              WHERE e.tournament_id=p_tournament_id
                AND e.position=expected.position))>0) THEN
    RETURN jsonb_build_object('ok',false,'is_satellite',true,'ready',false,
                              'reason','frozen_entitlement_plan_conflict');
  END IF;
  RETURN jsonb_build_object(
    'ok',true,'is_satellite',true,'ready',true,'award_depth',v_expected_depth,
    'entitlement_count',v_expected_depth,'ticket_value',v_ticket,
    'source_pool',v_pool,'target_tournament_id',v_economics.target_tournament_id,
    'source_contract_hash',v_economics.source_contract_hash,
    'target_contract_hash',v_economics.target_contract_hash);
END;
$$;


ALTER FUNCTION public.fn_materialize_satellite_entitlements_locked(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_member_fee_lifetime_after_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_member_fee_lifetime_after_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
      FROM deleted_member_fees deleted
     WHERE NOT EXISTS (
       SELECT 1 FROM public.member_fee_lifetime lifetime
        WHERE lifetime.user_id = deleted.user_id
     )
  ) THEN
    RAISE EXCEPTION 'member_fee_lifetime is missing a deleted source user';
  END IF;

  WITH removed AS (
    SELECT r.user_id, sum(r.fees) AS fees, sum(r.hands)::bigint AS hands,
           max(r.updated_at) AS updated_at
    FROM deleted_member_fees r
    GROUP BY r.user_id
  )
  UPDATE public.member_fee_lifetime lifetime
     SET fees = lifetime.fees - removed.fees,
         hands = lifetime.hands - removed.hands,
         updated_at = greatest(lifetime.updated_at, removed.updated_at)
    FROM removed
   WHERE lifetime.user_id = removed.user_id;

  DELETE FROM public.member_fee_lifetime WHERE fees = 0 AND hands = 0;
  RETURN NULL;
END
$$;


ALTER FUNCTION public.fn_member_fee_lifetime_after_delete() OWNER TO postgres;

--
-- Name: fn_member_fee_lifetime_after_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_member_fee_lifetime_after_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.member_fee_lifetime AS lifetime (user_id, fees, hands, updated_at)
  SELECT r.user_id, sum(r.fees), sum(r.hands)::bigint, max(r.updated_at)
    FROM inserted_member_fees r
   GROUP BY r.user_id
  ON CONFLICT (user_id) DO UPDATE
  SET fees = lifetime.fees + EXCLUDED.fees,
      hands = lifetime.hands + EXCLUDED.hands,
      updated_at = greatest(lifetime.updated_at, EXCLUDED.updated_at);
  RETURN NULL;
END
$$;


ALTER FUNCTION public.fn_member_fee_lifetime_after_insert() OWNER TO postgres;

--
-- Name: fn_member_fee_lifetime_after_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_member_fee_lifetime_after_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
      FROM previous_member_fees previous
     WHERE NOT EXISTS (
       SELECT 1 FROM public.member_fee_lifetime lifetime
        WHERE lifetime.user_id = previous.user_id
     )
  ) THEN
    RAISE EXCEPTION 'member_fee_lifetime is missing an updated source user';
  END IF;

  WITH changes AS (
    SELECT r.user_id, r.fees, r.hands, r.updated_at FROM updated_member_fees r
    UNION ALL
    SELECT r.user_id, -r.fees, -r.hands, r.updated_at FROM previous_member_fees r
  ), delta AS (
    SELECT c.user_id,
           sum(c.fees) AS fees,
           sum(c.hands)::bigint AS hands,
           max(c.updated_at) AS updated_at
      FROM changes c
     GROUP BY c.user_id
    HAVING sum(c.fees) <> 0 OR sum(c.hands) <> 0
  )
  UPDATE public.member_fee_lifetime lifetime
     SET fees = lifetime.fees + delta.fees,
         hands = lifetime.hands + delta.hands,
         updated_at = greatest(lifetime.updated_at, delta.updated_at)
    FROM delta
   WHERE lifetime.user_id = delta.user_id;

  -- A key change can introduce a new user. Existing users were adjusted above;
  -- only genuinely new positive rows reach this insert.
  INSERT INTO public.member_fee_lifetime AS lifetime (user_id, fees, hands, updated_at)
  WITH changes AS (
    SELECT r.user_id, r.fees, r.hands, r.updated_at FROM updated_member_fees r
    UNION ALL
    SELECT r.user_id, -r.fees, -r.hands, r.updated_at FROM previous_member_fees r
  ), delta AS (
    SELECT c.user_id,
           sum(c.fees) AS fees,
           sum(c.hands)::bigint AS hands,
           max(c.updated_at) AS updated_at
      FROM changes c
     GROUP BY c.user_id
    HAVING sum(c.fees) <> 0 OR sum(c.hands) <> 0
  )
  SELECT d.user_id, d.fees, d.hands, d.updated_at
    FROM delta d
   WHERE NOT EXISTS (
     SELECT 1 FROM public.member_fee_lifetime existing WHERE existing.user_id = d.user_id
   )
  ON CONFLICT (user_id) DO UPDATE
  SET fees = lifetime.fees + EXCLUDED.fees,
      hands = lifetime.hands + EXCLUDED.hands,
      updated_at = greatest(lifetime.updated_at, EXCLUDED.updated_at);

  DELETE FROM public.member_fee_lifetime WHERE fees = 0 AND hands = 0;
  RETURN NULL;
END
$$;


ALTER FUNCTION public.fn_member_fee_lifetime_after_update() OWNER TO postgres;

--
-- Name: fn_member_leave_to_treasury(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_member_leave_to_treasury(p_club_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_role  text;
  v_chips numeric;
  v_after numeric;
  v_caller uuid := auth.uid();
BEGIN
  IF p_club_id IS NULL OR p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'club and user required');
  END IF;

  -- AUTHZ: service role, the member themselves, or a club treasury manager.
  IF v_caller IS NOT NULL
     AND v_caller <> p_user_id
     AND NOT public.fn_actor_can_manage_club_treasury(p_club_id) THEN
    RETURN jsonb_build_object('success', false,
      'error', 'not authorized to remove another member from this club');
  END IF;

  SELECT role, COALESCE(chip_balance, 0)
    INTO v_role, v_chips
  FROM club_members
  WHERE club_id = p_club_id AND user_id = p_user_id
  FOR UPDATE;

  IF v_role IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not a member');
  END IF;

  IF v_role = 'owner' THEN
    RETURN jsonb_build_object('success', false, 'error', 'owner must transfer ownership first');
  END IF;

  IF v_chips > 0 THEN
    UPDATE clubs
    SET chip_treasury = COALESCE(chip_treasury, 0) + v_chips,
        updated_at = NOW()
    WHERE id = p_club_id
    RETURNING chip_treasury INTO v_after;

    IF v_after IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'club not found');
    END IF;

    INSERT INTO chip_transactions (
      id, club_id, from_user_id, amount, transaction_type, notes, balance_after, created_at
    ) VALUES (
      gen_random_uuid(), p_club_id, p_user_id, v_chips,
      'leave_club_chip_return', 'Chips returned to treasury on club departure',
      v_after, NOW()
    );
  END IF;

  DELETE FROM club_members WHERE club_id = p_club_id AND user_id = p_user_id;

  RETURN jsonb_build_object('success', true, 'chips_returned', COALESCE(v_chips, 0));
END;
$$;


ALTER FUNCTION public.fn_member_leave_to_treasury(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_membership_approval_gate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_membership_approval_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_requires boolean;
  v_owner uuid;
BEGIN
  IF NEW.status NOT IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status IN ('active', 'approved') THEN
    RETURN NEW;
  END IF;

  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  v_uid := auth.uid();

  IF NEW.user_id IS DISTINCT FROM v_uid THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(requires_approval, false), owner_id
    INTO v_requires, v_owner
    FROM clubs WHERE id = NEW.club_id;

  IF NOT FOUND OR NOT v_requires THEN
    RETURN NEW;
  END IF;

  IF v_owner = v_uid OR is_club_admin(NEW.club_id, v_uid) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.status := 'pending';
    RETURN NEW;
  END IF;

  RAISE EXCEPTION
    'This club requires owner approval. Your request is pending review.'
    USING ERRCODE = 'check_violation';
END;
$$;


ALTER FUNCTION public.fn_membership_approval_gate() OWNER TO postgres;

--
-- Name: fn_membership_starts_with_zero_chips(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_membership_starts_with_zero_chips() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(NEW.is_bot, false)
     OR EXISTS (SELECT 1 FROM profiles p WHERE p.id = NEW.user_id AND COALESCE(p.is_horse, false))
  THEN
    RETURN NEW;
  END IF;

  NEW.chip_balance  := 0;
  NEW.held_chips    := 0;
  NEW.locked_chips  := 0;
  NEW.promo_balance := 0;
  NEW.credit_used   := 0;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_membership_starts_with_zero_chips() OWNER TO postgres;

--
-- Name: FUNCTION fn_membership_starts_with_zero_chips(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_membership_starts_with_zero_chips() IS 'Dan 2026-08-26, binding: a new club membership always starts with zero chips. Zeroes chip_balance, held_chips, locked_chips, promo_balance and credit_used on INSERT no matter what the caller passed. Horses (profiles.is_horse / club_members.is_bot) are exempt because the fleet is stocked rather than bought.';


