--
-- Name: fn_merge_messenger_preferences(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_merge_messenger_preferences(p_user_id uuid, p_key text, p_value jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Caller must be the target user (or a service role; service-role bypasses RLS but also bypasses this guard, which is fine).
    IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
        RAISE EXCEPTION 'unauthorized: can only update own preferences';
    END IF;

    UPDATE public.profiles
       SET messenger_preferences = jsonb_set(
             COALESCE(messenger_preferences, '{}'::jsonb),
             ARRAY[p_key],
             p_value,
             true
           )
     WHERE id = p_user_id;
END;
$$;


