--
-- Name: fn_messenger_dispatch_scheduled(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_dispatch_scheduled(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lim   int := GREATEST(LEAST(COALESCE(p_limit, 200), 1000), 1);
  v_sent  int := 0;
  v_failed int := 0;
  r       record;
BEGIN
  FOR r IN
    SELECT s.id, s.conversation_id, s.sender_id, s.text, s.message_type, s.media_url
      FROM messenger_scheduled s
     WHERE s.status = 'pending'
       AND s.scheduled_at <= now()
     ORDER BY s.scheduled_at ASC
     LIMIT v_lim
     FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      -- the sender must still be in the conversation at send time
      IF NOT EXISTS (
        SELECT 1 FROM messenger_participants p
         WHERE p.conversation_id = r.conversation_id
           AND p.user_id = r.sender_id
      ) THEN
        UPDATE messenger_scheduled
           SET status = 'failed', updated_at = now()
         WHERE id = r.id;
        v_failed := v_failed + 1;
        CONTINUE;
      END IF;

      INSERT INTO messenger_messages
        (conversation_id, sender_id, text, message_type, media_url, status)
      VALUES
        (r.conversation_id, r.sender_id, r.text,
         COALESCE(NULLIF(r.message_type, ''), 'text'), r.media_url, 'sent');

      UPDATE messenger_conversations
         SET last_message_text = left(COALESCE(r.text, ''), 200),
             last_message_at   = now(),
             updated_at        = now()
       WHERE id = r.conversation_id;

      UPDATE messenger_scheduled
         SET status = 'sent', updated_at = now()
       WHERE id = r.id;

      v_sent := v_sent + 1;
    EXCEPTION WHEN OTHERS THEN
      -- one bad row must not stop the batch
      UPDATE messenger_scheduled
         SET status = 'failed', updated_at = now()
       WHERE id = r.id;
      v_failed := v_failed + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'sent', v_sent, 'failed', v_failed,
                            'ran_at', now());
END;
$$;


ALTER FUNCTION public.fn_messenger_dispatch_scheduled(p_limit integer) OWNER TO postgres;

--
-- Name: fn_mint_chips_from_diamonds(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mint_chips_from_diamonds(p_club_id uuid, p_diamonds numeric, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_op_id uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior record;
  v_diamonds numeric;
  v_chips numeric;
  v_rate integer;
  v_deduct jsonb;
  v_diamonds_after numeric;
  v_club record;
  v_is_union_minter boolean := false;
  v_pool_after numeric;
  v_union_bank_after numeric;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;
  if p_diamonds is null or p_diamonds <= 0 or p_diamonds <> floor(p_diamonds) then
    return jsonb_build_object('success', false, 'error', 'Diamonds Must Be A Positive Whole Number');
  end if;
  if p_diamonds > 1000000 then
    return jsonb_build_object('success', false, 'error', 'Maximum 1,000,000 Diamonds Per Mint');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_club_id::text || ':' || v_op_id::text, 0));

  select amount, transaction_type, metadata, balance_after into v_prior
    from chip_transactions
   where transaction_type = 'mint'
     and club_id = p_club_id
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object('success', true, 'replayed', true,
      'scope', v_prior.metadata ->> 'scope',
      'chips', v_prior.amount,
      'diamonds_spent', (v_prior.metadata ->> 'diamonds_spent')::numeric,
      'diamonds_after', (select coalesce(diamonds, 0) from profiles where id = v_actor),
      'club_pool_after', case when (v_prior.metadata ->> 'scope') = 'club'
                              then v_prior.balance_after end,
      'union_bank_after', case when (v_prior.metadata ->> 'scope') = 'union'
                               then v_prior.balance_after end);
  end if;

  v_diamonds := p_diamonds;
  -- THE RATE IS A ROW (Dan 2026-09-07: 1 diamond = $0.01, 1 chip = $1.00).
  -- Read from ca_bridge_rate; never a literal in this body again.
  v_rate := public.fn_ca_bridge_rate();
  if v_rate is null or v_rate <= 0 then
    return jsonb_build_object('success', false, 'error', 'The Bridge Rate Is Not Set');
  end if;
  v_chips := round(v_diamonds / v_rate, 2);
  if v_chips <= 0 or v_chips * v_rate <> v_diamonds then
    return jsonb_build_object('success', false,
      'error', format('Diamonds Must Convert To Whole Cents Of Chips At %s Diamonds Per Chip', v_rate));
  end if;

  select id, name, union_id, owner_id into v_club
    from clubs where id = p_club_id for update;
  if v_club.id is null then
    return jsonb_build_object('success', false, 'error', 'That Club Could Not Be Found');
  end if;

  if v_club.union_id is not null then
    if exists (select 1 from unions u where u.id = v_club.union_id and u.owner_id = v_actor)
       or exists (select 1 from union_admins ua where ua.union_id = v_club.union_id and ua.user_id = v_actor) then
      v_is_union_minter := true;
    end if;
    if not v_is_union_minter then
      return jsonb_build_object('success', false,
        'error', 'Chip Mint Is Revoked For Clubs In A Union. Chips Flow From The Union. Ask Your Union Owner');
    end if;

    v_deduct := deduct_diamonds(
      v_actor, v_diamonds::integer,
      'Chip Mint: ' || v_chips::text || ' chips minted to union bank',
      'chip_mint', 'chip_mint',
      jsonb_build_object('club_id', p_club_id, 'union_id', v_club.union_id,
                         'chips', v_chips, 'op_id', v_op_id, 'diamonds_per_chip', v_rate),
      null, 0);
    if coalesce((v_deduct->>'success')::boolean, false) = false then
      return jsonb_build_object('success', false,
        'error', coalesce(v_deduct->>'error', 'That Diamond Deduction Did Not Go Through'));
    end if;
    select coalesce(diamonds, 0) into v_diamonds_after from profiles where id = v_actor;

    /* THE MINT (chip standard 3.1, 2026-09-04): chips bought with diamonds
       are ISSUED. Declared issuance_reserve -> union_bank with the op id as
       the journal key; the register row follows from the leg (deferred
       trigger on chip_ledger). Undeclared, this landed in suspense and the
       register never saw it. */
    perform public.fn_ca_declare_ledger('mint', 'issuance_reserve', null, null,
                                        'diamond-mint:' || v_op_id::text, null);
    insert into union_wallets (union_id, chip_balance)
    values (v_club.union_id, v_chips)
    on conflict (union_id)
    do update set chip_balance = coalesce(union_wallets.chip_balance, 0) + v_chips,
                  updated_at = now();
    perform set_config('app.ledger_category', '', true);
    perform set_config('app.ledger_counterparty', '', true);
    perform set_config('app.ledger_idempotency_key', '', true);
    select chip_balance into v_union_bank_after
      from union_wallets where union_id = v_club.union_id;

    insert into chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
    values (p_club_id, v_actor, null, v_chips, 'mint',
            'Union Chip Mint: ' || v_chips::text || ' chips from ' || v_diamonds::text || ' diamonds at ' || v_rate::text || ' per chip',
            jsonb_build_object('op_id', v_op_id, 'scope', 'union',
                               'diamonds_spent', v_diamonds, 'union_id', v_club.union_id,
                               'diamonds_per_chip', v_rate),
            v_union_bank_after);

    return jsonb_build_object('success', true, 'replayed', false, 'scope', 'union',
      'chips', v_chips, 'diamonds_spent', v_diamonds, 'diamonds_per_chip', v_rate,
      'diamonds_after', v_diamonds_after, 'union_bank_after', v_union_bank_after);
  else
    -- STANDALONE CLUB: owner / co_owner / admin may mint into the club's pool.
    -- BOTH membership words (2026-08-27): status='active' alone refused the
    -- ~98% of production rows still carrying the pre-2026-07-22 'approved'.
    if not (v_club.owner_id = v_actor
            or exists (select 1 from club_members cm
                        where cm.club_id = p_club_id and cm.user_id = v_actor
                          and cm.role in ('owner', 'co_owner', 'admin')
                          and coalesce(cm.status, 'active') in ('active', 'approved'))) then
      return jsonb_build_object('success', false,
        'error', 'Only The Club Owner Or An Admin May Mint Chips');
    end if;

    v_deduct := deduct_diamonds(
      v_actor, v_diamonds::integer,
      'Chip Mint: ' || v_chips::text || ' chips minted to club bank',
      'chip_mint', 'chip_mint',
      jsonb_build_object('club_id', p_club_id, 'chips', v_chips, 'op_id', v_op_id,
                         'diamonds_per_chip', v_rate),
      null, 0);
    if coalesce((v_deduct->>'success')::boolean, false) = false then
      return jsonb_build_object('success', false,
        'error', coalesce(v_deduct->>'error', 'That Diamond Deduction Did Not Go Through'));
    end if;
    select coalesce(diamonds, 0) into v_diamonds_after from profiles where id = v_actor;

    /* THE MINT (chip standard 3.1, 2026-09-04): see the union branch. */
    perform public.fn_ca_declare_ledger('mint', 'issuance_reserve', null, null,
                                        'diamond-mint:' || v_op_id::text, null);
    update clubs set chip_treasury = coalesce(chip_treasury, 0) + v_chips, updated_at = now()
     where id = p_club_id
     returning chip_treasury into v_pool_after;
    perform set_config('app.ledger_category', '', true);
    perform set_config('app.ledger_counterparty', '', true);
    perform set_config('app.ledger_idempotency_key', '', true);

    insert into chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
    values (p_club_id, v_actor, null, v_chips, 'mint',
            'Chip Mint: ' || v_chips::text || ' chips from ' || v_diamonds::text || ' diamonds at ' || v_rate::text || ' per chip',
            jsonb_build_object('op_id', v_op_id, 'scope', 'club',
                               'diamonds_spent', v_diamonds, 'diamonds_per_chip', v_rate),
            v_pool_after);

    return jsonb_build_object('success', true, 'replayed', false, 'scope', 'club',
      'chips', v_chips, 'diamonds_spent', v_diamonds, 'diamonds_per_chip', v_rate,
      'diamonds_after', v_diamonds_after, 'club_pool_after', v_pool_after);
  end if;
end
$_$;


ALTER FUNCTION public.fn_mint_chips_from_diamonds(p_club_id uuid, p_diamonds numeric, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_mint_club_chips(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mint_club_chips(p_club_id uuid, p_amount numeric, p_reason text DEFAULT 'beta top-up'::text, p_op_id text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_prior jsonb;
  v_res numeric;
begin
  /* ZERO-DRIFT phase 3/5: durable op-id claim with actor audit. Callers that
     pass a p_op_id get exactly-once semantics across retries; the claim row
     records who asked. Authorization itself lives in the core. */
  if p_op_id is null then
    return public.fn_mint_club_chips_zd3core(p_club_id, p_amount, p_reason);
  end if;

  select result into v_prior
    from public.ca_op_claims
   where op_id = p_op_id and fn_name = 'fn_mint_club_chips';
  if found and v_prior is not null then
    return (v_prior->>'value')::numeric;  -- replay: treasury after the original mint
  elsif found then
    delete from public.ca_op_claims
     where op_id = p_op_id and fn_name = 'fn_mint_club_chips';
  end if;

  insert into public.ca_op_claims (op_id, fn_name, claimed_by)
  values (p_op_id, 'fn_mint_club_chips', v_actor);

  v_res := public.fn_mint_club_chips_zd3core(p_club_id, p_amount, p_reason);

  update public.ca_op_claims
     set result = jsonb_build_object('value', v_res), finalized_at = now()
   where op_id = p_op_id and fn_name = 'fn_mint_club_chips';

  return v_res;
end $$;


ALTER FUNCTION public.fn_mint_club_chips(p_club_id uuid, p_amount numeric, p_reason text, p_op_id text) OWNER TO postgres;

--
-- Name: fn_mint_club_chips_zd3core(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mint_club_chips_zd3core(p_club_id uuid, p_amount numeric, p_reason text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
    v_actor uuid := auth.uid();
    v_after numeric;
    v_union uuid;
    v_authorised boolean;
begin
    if p_amount is null or p_amount <= 0 then
        raise exception 'mint amount must be positive, got %', p_amount;
    end if;

    select union_id into v_union from clubs where id = p_club_id;
    if not found then
        raise exception 'mint failed: club % not found', p_club_id;
    end if;

    -- Dan 2026-08-22: only unions mint. A club that has joined a union has no
    -- mint of its own - chips are minted in the union and SENT to the club.
    if v_union is not null then
        raise exception 'Chip Mint Is Revoked For Clubs In A Union - Chips Are Minted In The Union And Sent To The Club. Ask Your Union Owner.';
    end if;

    if coalesce(auth.role(), '') <> 'service_role' then
        v_authorised := v_actor is not null and (
            exists (select 1 from clubs c where c.id = p_club_id and c.owner_id = v_actor)
            or exists (
                select 1 from club_members cm
                 where cm.club_id = p_club_id
                   and cm.user_id = v_actor
                   and cm.role in ('owner','co_owner','admin')
                   and cm.status in ('active','approved'))
        );
        if not v_authorised then
            raise exception 'not authorized to mint for this club';
        end if;
    end if;

    /* ZERO-DRIFT round 2 (2026-08-31): duplicate-mint suppression. An
       identical mint (club, amount, reason, actor) inside 20 seconds is a
       retry, not a second intent - return the current treasury unchanged.
       A deliberate second mint just needs a different reason or 20 seconds. */
    if exists (
        select 1 from chip_transactions ct
         where ct.club_id = p_club_id
           and ct.transaction_type = 'treasury_mint'
           and ct.amount = p_amount
           and ct.from_user_id is not distinct from v_actor
           and coalesce(ct.notes,'') = coalesce(p_reason,'')
           and ct.created_at > now() - interval '20 seconds') then
        select coalesce(chip_treasury, 0) into v_after from clubs where id = p_club_id;
        return v_after;
    end if;

    /* Authorized issuance journals against the issuance reserve. */
    perform set_config('app.ledger_category', 'mint', true);
    perform set_config('app.ledger_counterparty', 'issuance_reserve', true);
    perform set_config('app.ledger_counterparty_entity', '', true);

    update public.clubs
       set chip_treasury = coalesce(chip_treasury, 0) + p_amount
     where id = p_club_id
    returning chip_treasury into v_after;

    insert into public.chip_transactions
        (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after)
    values (p_club_id, v_actor, null, p_amount, 'treasury_mint', p_reason, v_after);

    return v_after;
end $$;


ALTER FUNCTION public.fn_mint_club_chips_zd3core(p_club_id uuid, p_amount numeric, p_reason text) OWNER TO postgres;

--
-- Name: fn_mint_social_alias(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mint_social_alias(p_seed text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_w1 text[];
  v_w2 text[];
  v_base text;
  v_cand text;
  v_n integer := 0;
  v_h bigint;
BEGIN
  SELECT array_agg(w ORDER BY w) INTO v_w1
    FROM (SELECT DISTINCT (regexp_match(alias, '^([A-Z][a-z]+)'))[1] AS w
            FROM public.content_authors) s
   WHERE w IS NOT NULL;
  SELECT array_agg(w ORDER BY w) INTO v_w2
    FROM (SELECT DISTINCT (regexp_match(alias, '^[A-Z][a-z]+([A-Z][a-z]+)'))[1] AS w
            FROM public.content_authors) s
   WHERE w IS NOT NULL;

  IF v_w1 IS NULL OR v_w2 IS NULL
     OR COALESCE(array_length(v_w1, 1), 0) = 0
     OR COALESCE(array_length(v_w2, 1), 0) = 0 THEN
    RAISE EXCEPTION 'fn_mint_social_alias: no alias vocabulary to draw from';
  END IF;

  v_h := abs(hashtext(p_seed));

  LOOP
    v_base := v_w1[1 + ((v_h + v_n * 7919) % array_length(v_w1, 1))]
           || v_w2[1 + (((v_h / 17) + v_n * 104729) % array_length(v_w2, 1))];
    -- Pure handles first. Once fifty probes have all collided we are in a
    -- crowded corner of the space, so take the discriminator rather than
    -- probing forever: this is the safety net that 2026-09-01 did not have.
    v_cand := CASE WHEN v_n < 50 THEN v_base ELSE v_base || (v_n - 49)::text END;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.content_authors WHERE alias = v_cand);
    v_n := v_n + 1;
    IF v_n > 100000 THEN
      RAISE EXCEPTION 'fn_mint_social_alias: could not mint a free alias for %', p_seed;
    END IF;
  END LOOP;

  RETURN v_cand;
END;
$$;


ALTER FUNCTION public.fn_mint_social_alias(p_seed text) OWNER TO postgres;

--
-- Name: FUNCTION fn_mint_social_alias(p_seed text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_mint_social_alias(p_seed text) IS 'Mints a free content_authors.alias. Cannot exhaust: probes the full observed vocabulary then falls back to a numeric discriminator. Added 2026-09-02 after a 400-handle generator stranded 253 horses.';


--
-- Name: fn_mirror_notification_to_push_outbox(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mirror_notification_to_push_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tag     text;
  v_pending int;
  c_max_pending CONSTANT int      := 20;
  c_max_age     CONSTANT interval := interval '30 minutes';
BEGIN
  IF NEW.data IS NOT NULL AND (NEW.data ->> '_push') IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.user_id IS NULL OR NEW.title IS NULL OR btrim(NEW.title) = '' THEN
    RETURN NEW;
  END IF;

  IF NEW.created_at IS NOT NULL AND NEW.created_at < (now() - c_max_age) THEN
    RETURN NEW;
  END IF;

  IF NEW.type IN (
    'waitlist_seat_open', 'waitlist_offer_expired',
    'seat_available', 'waitlist_ready', 'table_ready'
  ) THEN
    v_tag := 'seat_offer:' || COALESCE(
      NULLIF(btrim(COALESCE(NEW.data ->> 'table_id', '')), ''),
      NEW.id::text
    );
  ELSIF NEW.type IN (
    'system', 'daily_challenge', 'venue_alert', 'bonus', 'vip',
    'live', 'poker_news', 'diamond', 'achievement'
  ) THEN
    v_tag := NEW.type || ':' || NEW.user_id::text;
  ELSE
    v_tag := NEW.type || ':' || COALESCE(
      NULLIF(btrim(COALESCE(NEW.data ->> 'conversationId', '')), ''),
      NULLIF(btrim(COALESCE(NEW.data ->> 'conversation_id', '')), ''),
      NEW.actor_id::text,
      NEW.id::text
    );
  END IF;

  BEGIN
    SELECT count(*) INTO v_pending
    FROM public.push_outbox
    WHERE recipient_user_id = NEW.user_id
      AND status IN ('pending', 'processing');

    IF v_pending >= c_max_pending THEN
      RETURN NEW;
    END IF;

    INSERT INTO public.push_outbox (
      recipient_user_id, title, body, url, event, tag, status, related_entity_id
    )
    VALUES (
      NEW.user_id,
      left(NEW.title, 120),
      left(COALESCE(NEW.message, NEW.title), 500),
      COALESCE(NULLIF(btrim(NEW.link), ''), NULLIF(btrim(NEW.action_url), ''), '/hub'),
      NEW.type,
      v_tag,
      'pending',
      NEW.id
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'mirror_notification_to_push_outbox failed for notification %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_mirror_notification_to_push_outbox() OWNER TO postgres;

--
-- Name: fn_mirror_profile_into_legacy_users(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mirror_profile_into_legacy_users() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  BEGIN
    INSERT INTO public.users (id, username, email, avatar_url, created_at, updated_at)
    VALUES (
      NEW.id,
      COALESCE(
        NULLIF(btrim(NEW.username), ''),
        NULLIF(split_part(COALESCE(NEW.email, ''), '@', 1), ''),
        'Player' || COALESCE(NEW.player_number, left(replace(NEW.id::text, '-', ''), 10))
      ),
      NULLIF(btrim(COALESCE(NEW.email, '')), ''),
      NULLIF(btrim(COALESCE(NEW.avatar_url, '')), ''),
      now(),
      now()
    )
    ON CONFLICT (id) DO NOTHING;
  EXCEPTION WHEN unique_violation THEN
    BEGIN
      INSERT INTO public.users (id, username, email, avatar_url, created_at, updated_at)
      VALUES (NEW.id, 'u_' || replace(NEW.id::text, '-', ''), NULL,
              NULLIF(btrim(COALESCE(NEW.avatar_url, '')), ''), now(), now())
      ON CONFLICT (id) DO NOTHING;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO public.signup_errors (user_id, email, trigger_name, error_code, error_msg)
      VALUES (NEW.id, NEW.email, 'fn_mirror_profile_into_legacy_users', SQLSTATE, SQLERRM);
    END;
  WHEN OTHERS THEN
    BEGIN
      INSERT INTO public.signup_errors (user_id, email, trigger_name, error_code, error_msg)
      VALUES (NEW.id, NEW.email, 'fn_mirror_profile_into_legacy_users', SQLSTATE, SQLERRM);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_mirror_profile_into_legacy_users() OWNER TO postgres;

--
-- Name: FUNCTION fn_mirror_profile_into_legacy_users(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_mirror_profile_into_legacy_users() IS 'Mirrors each new profile into the legacy public.users table, which nine foreign keys still reference. Added 2026-08-26 after 29 real accounts were found unable to join any club: signup writes profiles only, and club_members_user_id_fkey checks public.users.';


--
-- Name: fn_money_check_health(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_money_check_health(p_stale_multiple numeric DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_mult    numeric := GREATEST(COALESCE(p_stale_multiple, 3), 1);
  v_rows    jsonb   := '[]'::jsonb;
  v_stale   integer := 0;
  v_never   integer := 0;
  v_alerts  integer := 0;
  r         record;
BEGIN
  FOR r IN
    SELECT h.check_name, h.expected_interval_minutes AS every_min, h.last_run_at,
           h.run_count, h.note,
           CASE WHEN h.last_run_at IS NULL THEN NULL
                ELSE round(EXTRACT(epoch FROM (now() - h.last_run_at)) / 60.0, 1)
           END AS age_min
      FROM public.money_check_heartbeat h
     ORDER BY h.check_name
  LOOP
    DECLARE
      v_is_stale boolean := (r.last_run_at IS NULL)
                            OR (r.age_min > r.every_min * v_mult);
    BEGIN
      v_rows := v_rows || jsonb_build_object(
        'check', r.check_name, 'every_minutes', r.every_min,
        'last_run_at', r.last_run_at, 'age_minutes', r.age_min,
        'runs', r.run_count, 'stale', v_is_stale);

      IF v_is_stale THEN
        v_stale := v_stale + 1;
        IF r.last_run_at IS NULL THEN v_never := v_never + 1; END IF;

        PERFORM public.fn_raise_server_financial_alert(
          'critical', 'fn_money_check_health',
          CASE WHEN r.last_run_at IS NULL THEN
            format('%s has never run. It is expected every %s minutes, and until it does its silence means nothing.',
                   r.check_name, r.every_min)
          ELSE
            format('%s last ran %s minutes ago and is expected every %s. A check that stops looks exactly like a check finding nothing.',
                   r.check_name, r.age_min, r.every_min)
          END,
          jsonb_build_object('kind','money_check_stale','check', r.check_name,
            'every_minutes', r.every_min, 'last_run_at', r.last_run_at,
            'age_minutes', r.age_min, 'runs', r.run_count, 'purpose', r.note,
            'detail','no money was moved by this check'),
          r.check_name);
        v_alerts := v_alerts + 1;
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'stale_multiple', v_mult,
    'checks', jsonb_array_length(v_rows),
    'stale', v_stale,
    'never_run', v_never,
    'conditions_alerted', v_alerts,
    'board', v_rows);
END;
$$;


ALTER FUNCTION public.fn_money_check_health(p_stale_multiple numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_money_check_health(p_stale_multiple numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_money_check_health(p_stale_multiple numeric) IS 'The health of every money check in one call: when each last ran, how overdue it is, and a deduped critical for any that has gone quiet. Answers the question none of the individual checks can - whether their zeros mean anything.';


--
-- Name: fn_money_path_reaches_club_scope(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_money_path_reaches_club_scope(p_fn text, p_max_depth integer DEFAULT 4) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH RECURSIVE walk(fn, depth) AS (
    SELECT p_fn::text COLLATE "C", 0
    UNION
    SELECT callee.proname::text COLLATE "C", w.depth + 1
      FROM walk w
      JOIN pg_proc caller
        ON caller.proname::text COLLATE "C" = w.fn
       AND caller.pronamespace = 'public'::regnamespace
      JOIN pg_proc callee
        ON callee.pronamespace = 'public'::regnamespace
       -- A call, not a coincidental substring: the name must be followed by an
       -- open paren. The length floor keeps very short names from matching
       -- half the schema.
       AND length(callee.proname) > 6
       AND callee.proname::text COLLATE "C" <> w.fn
       AND caller.prosrc LIKE '%' || callee.proname || '(%'
     WHERE w.depth < GREATEST(p_max_depth, 1)
  )
  SELECT EXISTS (
    SELECT 1 FROM walk w
      JOIN pg_proc p ON p.proname::text COLLATE "C" = w.fn
                    AND p.pronamespace = 'public'::regnamespace
     WHERE p.prosrc LIKE '%club_members%'
        OR p.prosrc LIKE '%fn_pay_player_chips%');
$$;


ALTER FUNCTION public.fn_money_path_reaches_club_scope(p_fn text, p_max_depth integer) OWNER TO postgres;

--
-- Name: fn_money_rounding_policy(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_money_rounding_policy() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'written', '2026-09-07',
    'unit', 'every stored or paid chip amount is a whole number of cents; numeric scale 2; x = round(x, 2)',
    'shares', 'one amount split among players is split in integer cents by fn_allocate_rake_credits (largest remainder, ties by user id ascending) so the parts sum to the whole exactly; no other function carries a share formula',
    'rates', 'a rate applied to a basis rounds half away from zero to the cent: round(x, 2); the one exception is the union per-(club, game type) club share, truncated to the cent so the remainder stays with the union (Dan 2026-09-03)',
    'sums', 'cents are summed as integers (rakeback_daily_user.cents); a sum of rounded parts is never re-rounded',
    'vip', 'a VIP credit carries four decimals in vip_points_ledger and converts to whole points by floor with a per-user carry (20260831100610); VIP points are not chips',
    'conservation', 'at every settlement boundary in = out to the cent (fn_union_settlement_conservation_assert, fn_settlement_conservation_check)',
    'enforced_by', jsonb_build_array(
      'ck_whole_cents on rake_records, rake_attributions, agent_commissions, union_wallet_transactions, club_wallet_transactions, chip_ledger, rakeback_period_payouts, rakeback_periods, settlement_invoices (rows written from 2026-09-07)',
      'fn_allocate_rake_credits',
      'tests/money-is-whole-cents.law.test.ts')
  );
$$;


ALTER FUNCTION public.fn_money_rounding_policy() OWNER TO postgres;

--
-- Name: fn_move_tournament_player(uuid, uuid, uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_move_tournament_player(p_tournament_id uuid, p_user_id uuid, p_source_table_id uuid, p_destination_table_id uuid, p_destination_seat_number integer, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_tp public.tournament_players%ROWTYPE;
  v_source public.table_seats%ROWTYPE;
  v_destination public.table_seats%ROWTYPE;
  v_destination_id uuid;
  v_token uuid;
  v_moved_at timestamptz;
  v_rows integer;
  v_live_count integer;
  v_result jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'fn_move_tournament_player requires service authority'
      USING ERRCODE='28000';
  END IF;
  IF p_tournament_id IS NULL OR p_user_id IS NULL
     OR p_source_table_id IS NULL OR p_destination_table_id IS NULL
     OR p_request_id IS NULL OR p_source_table_id=p_destination_table_id
     OR p_destination_seat_number NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION 'invalid tournament move identity' USING ERRCODE='22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  PERFORM pg_advisory_xact_lock(
    hashtextextended('table_cap:'||p_user_id::text,0));

  v_result:=public.fn_ca_tournament_seat_move_receipt(p_request_id);
  IF v_result IS NOT NULL THEN
    IF (v_result->>'tournament_id')::uuid IS DISTINCT FROM p_tournament_id
       OR (v_result->>'user_id')::uuid IS DISTINCT FROM p_user_id
       OR (v_result->>'source_table_id')::uuid IS DISTINCT FROM p_source_table_id
       OR (v_result->>'destination_table_id')::uuid
            IS DISTINCT FROM p_destination_table_id
       OR (v_result->>'destination_seat_number')::integer
            IS DISTINCT FROM p_destination_seat_number THEN
      RAISE EXCEPTION 'tournament move request id belongs to another operation'
        USING ERRCODE='23505';
    END IF;
    RETURN v_result||jsonb_build_object('replayed',true);
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist',p_tournament_id
      USING ERRCODE='P0002';
  END IF;
  IF upper(COALESCE(v_t.status,''))<>'RUNNING' THEN
    RAISE EXCEPTION 'tournament % is not RUNNING',p_tournament_id
      USING ERRCODE='55000';
  END IF;

  SELECT * INTO v_tp FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND OR v_tp.status<>'playing'
     OR v_tp.table_id IS DISTINCT FROM p_source_table_id THEN
    RAISE EXCEPTION 'tournament move source roster is not exact'
      USING ERRCODE='P0404';
  END IF;

  PERFORM tb.id FROM public.tables tb
   WHERE tb.id IN (p_source_table_id,p_destination_table_id)
   ORDER BY tb.id FOR UPDATE;
  IF (SELECT count(*) FROM public.tables tb
       WHERE tb.id IN (p_source_table_id,p_destination_table_id)
         AND tb.tournament_id=p_tournament_id)<>2 THEN
    RAISE EXCEPTION 'tournament move tables do not share the event'
      USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tables tb
     WHERE tb.id=p_destination_table_id
       AND (COALESCE(tb.is_deleted,false)
         OR lower(COALESCE(tb.status,''))='closed'
         OR p_destination_seat_number>COALESCE(tb.max_players,9))) THEN
    RAISE EXCEPTION 'tournament move destination is not open'
      USING ERRCODE='55000';
  END IF;

  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
     AND s.left_at IS NULL
   ORDER BY s.id FOR UPDATE OF s;
  SELECT count(*) INTO v_live_count
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
     AND s.left_at IS NULL;
  IF v_live_count<>1 THEN
    RAISE EXCEPTION 'tournament move requires exactly one live source seat'
      USING ERRCODE='P0404';
  END IF;

  SELECT s.* INTO v_source FROM public.table_seats s
   WHERE s.table_id=p_source_table_id AND s.user_id=p_user_id
     AND s.left_at IS NULL FOR UPDATE;
  IF NOT FOUND OR v_source.seat_number IS DISTINCT FROM v_tp.seat_number
     OR v_source.stack IS NULL
     OR v_source.stack::text IN ('NaN','Infinity','-Infinity')
     OR v_source.stack<=0
     OR abs(v_source.stack-v_tp.chips::numeric)>0.5 THEN
    RAISE EXCEPTION 'tournament move source chips or coordinates are not exact'
      USING ERRCODE='P0404';
  END IF;

  SELECT s.* INTO v_destination FROM public.table_seats s
   WHERE s.table_id=p_destination_table_id
     AND s.seat_number=p_destination_seat_number FOR UPDATE;
  IF FOUND AND v_destination.left_at IS NULL THEN
    RAISE EXCEPTION 'tournament move destination seat is occupied'
      USING ERRCODE='23505';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id
       AND tp.user_id<>p_user_id
       AND tp.status IN ('registered','playing')
       AND tp.table_id=p_destination_table_id
       AND tp.seat_number=p_destination_seat_number) THEN
    RAISE EXCEPTION 'tournament move destination roster is occupied'
      USING ERRCODE='23505';
  END IF;

  v_token:=public.fn_ca_open_tournament_seat_exit_authority(
    p_tournament_id,'move',p_user_id);
  v_moved_at:=clock_timestamp();
  BEGIN
    UPDATE public.table_seats s
       SET stack=0,left_at=v_moved_at,status='left',leave_pending=false,
           is_sitting_out=false,is_away=false,sit_out_at=NULL,
           scheduled_leave_hands=NULL
     WHERE s.id=v_source.id AND s.left_at IS NULL
       AND s.stack=v_source.stack;
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN
      RAISE EXCEPTION 'tournament move lost its locked source seat'
        USING ERRCODE='40001';
    END IF;

    IF v_destination.id IS NULL THEN
      INSERT INTO public.table_seats(
        table_id,seat_number,user_id,player_id,member_id,stack,
        is_sitting_out,is_away,joined_at,horse_id,scheduled_leave_hands,
        left_at,status,leave_pending,auto_rebuy,time_bank_remaining,
        time_bank_uses_remaining,sit_out_at,entry_hold,entry_post_agreed)
      VALUES(
        p_destination_table_id,p_destination_seat_number,p_user_id,
        v_source.player_id,v_source.member_id,v_source.stack,
        false,false,v_moved_at,v_source.horse_id,NULL,NULL,'active',false,
        v_source.auto_rebuy,v_source.time_bank_remaining,
        v_source.time_bank_uses_remaining,NULL,NULL,
        v_source.entry_post_agreed)
      RETURNING id INTO v_destination_id;
    ELSE
      UPDATE public.table_seats s
         SET user_id=p_user_id,player_id=v_source.player_id,
             member_id=v_source.member_id,stack=v_source.stack,
             is_sitting_out=false,is_away=false,joined_at=v_moved_at,
             horse_id=v_source.horse_id,scheduled_leave_hands=NULL,
             left_at=NULL,status='active',leave_pending=false,
             auto_rebuy=v_source.auto_rebuy,
             time_bank_remaining=v_source.time_bank_remaining,
             time_bank_uses_remaining=v_source.time_bank_uses_remaining,
             sit_out_at=NULL,entry_hold=NULL,
             entry_post_agreed=v_source.entry_post_agreed
       WHERE s.id=v_destination.id AND s.left_at IS NOT NULL
       RETURNING id INTO v_destination_id;
      IF v_destination_id IS NULL THEN
        RAISE EXCEPTION 'tournament move could not reuse destination seat'
          USING ERRCODE='40001';
      END IF;
    END IF;

    UPDATE public.tournament_players tp
       SET table_id=p_destination_table_id,
           seat_number=p_destination_seat_number
     WHERE tp.id=v_tp.id AND tp.status='playing'
       AND tp.table_id=p_source_table_id
       AND tp.seat_number=v_source.seat_number;
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN
      RAISE EXCEPTION 'tournament move lost its locked roster row'
        USING ERRCODE='40001';
    END IF;

    UPDATE public.tables tb
       SET current_players=(
         SELECT count(*) FROM public.table_seats s
          WHERE s.table_id=tb.id AND s.left_at IS NULL),
           updated_at=now()
     WHERE tb.id IN (p_source_table_id,p_destination_table_id);

    IF (SELECT count(*) FROM public.table_seats s
        JOIN public.tables tb ON tb.id=s.table_id
       WHERE tb.tournament_id=p_tournament_id
         AND s.user_id=p_user_id AND s.left_at IS NULL)<>1
       OR NOT EXISTS (
         SELECT 1 FROM public.table_seats s
          WHERE s.id=v_destination_id
            AND s.table_id=p_destination_table_id
            AND s.seat_number=p_destination_seat_number
            AND s.user_id=p_user_id AND s.left_at IS NULL
            AND s.stack=v_source.stack)
       OR NOT EXISTS (
         SELECT 1 FROM public.table_seats s
          WHERE s.id=v_source.id AND s.left_at=v_moved_at AND s.stack=0)
       OR NOT EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.id=v_tp.id AND tp.status='playing'
            AND tp.table_id=p_destination_table_id
            AND tp.seat_number=p_destination_seat_number) THEN
      RAISE EXCEPTION 'tournament move final proof is not exact'
        USING ERRCODE='P0404';
    END IF;

    INSERT INTO public.tournament_seat_move_receipts(
      request_id,tournament_id,user_id,source_table_id,destination_table_id,
      source_seat_id,destination_seat_id,source_seat_number,
      destination_seat_number,stack,moved_at)
    VALUES(
      p_request_id,p_tournament_id,p_user_id,p_source_table_id,
      p_destination_table_id,v_source.id,v_destination_id,
      v_source.seat_number,p_destination_seat_number,v_source.stack,v_moved_at);

    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
    RAISE;
  END;

  v_result:=public.fn_ca_tournament_seat_move_receipt(p_request_id);
  IF v_result IS NULL THEN
    RAISE EXCEPTION 'tournament move receipt did not persist'
      USING ERRCODE='P0404';
  END IF;
  RETURN v_result||jsonb_build_object('replayed',false);
END;
$$;


ALTER FUNCTION public.fn_move_tournament_player(p_tournament_id uuid, p_user_id uuid, p_source_table_id uuid, p_destination_table_id uuid, p_destination_seat_number integer, p_request_id uuid) OWNER TO postgres;

--
-- Name: fn_mutate_table_studio_preferences(text, boolean, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mutate_table_studio_preferences(p_favorite_key text DEFAULT NULL::text, p_favorite_enabled boolean DEFAULT NULL::boolean, p_loadout_slot integer DEFAULT NULL::integer, p_loadout jsonb DEFAULT NULL::jsonb) RETURNS TABLE(favorites text[], loadouts jsonb, revision bigint, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_is_favorite_mutation boolean := p_favorite_key IS NOT NULL OR p_favorite_enabled IS NOT NULL;
  v_is_loadout_mutation boolean := p_loadout_slot IS NOT NULL;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF v_is_favorite_mutation = v_is_loadout_mutation THEN
    RAISE EXCEPTION 'Exactly one Table Studio mutation is required' USING ERRCODE = '22023';
  END IF;

  IF v_is_favorite_mutation AND (
    p_favorite_key IS NULL OR p_favorite_enabled IS NULL OR
    btrim(p_favorite_key) = '' OR length(p_favorite_key) > 200
  ) THEN
    RAISE EXCEPTION 'Invalid favorite mutation' USING ERRCODE = '22023';
  END IF;

  IF v_is_loadout_mutation THEN
    IF p_loadout_slot < 0 OR p_loadout_slot > 2 THEN
      RAISE EXCEPTION 'Invalid loadout slot' USING ERRCODE = '22023';
    END IF;
    IF p_loadout IS NOT NULL AND (
      jsonb_typeof(p_loadout) <> 'object' OR
      NOT (p_loadout ?& ARRAY['theme_id', 'table_id', 'button_id', 'background_id', 'cards_id']) OR
      jsonb_typeof(p_loadout -> 'theme_id') <> 'string' OR
      jsonb_typeof(p_loadout -> 'table_id') <> 'string' OR
      jsonb_typeof(p_loadout -> 'button_id') <> 'string' OR
      jsonb_typeof(p_loadout -> 'background_id') <> 'string' OR
      jsonb_typeof(p_loadout -> 'cards_id') <> 'string'
    ) THEN
      RAISE EXCEPTION 'Invalid loadout payload' USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.user_table_studio_preferences (user_id)
  VALUES (v_user_id)
  ON CONFLICT (user_id) DO NOTHING;

  RETURN QUERY
  UPDATE public.user_table_studio_preferences AS p
     SET favorites = CASE
       WHEN NOT v_is_favorite_mutation THEN p.favorites
       WHEN p_favorite_enabled THEN
         (ARRAY[p_favorite_key] || array_remove(p.favorites, p_favorite_key))[1:100]
       ELSE array_remove(p.favorites, p_favorite_key)
     END,
         loadouts = CASE
       WHEN NOT v_is_loadout_mutation THEN p.loadouts
       ELSE jsonb_set(
         p.loadouts,
         ARRAY[p_loadout_slot::text],
         COALESCE(p_loadout, 'null'::jsonb),
         false
       )
     END,
         revision = p.revision + 1
   WHERE p.user_id = v_user_id
   RETURNING p.favorites, p.loadouts, p.revision, p.updated_at;
END;
$$;


ALTER FUNCTION public.fn_mutate_table_studio_preferences(p_favorite_key text, p_favorite_enabled boolean, p_loadout_slot integer, p_loadout jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_mutate_table_studio_preferences(p_favorite_key text, p_favorite_enabled boolean, p_loadout_slot integer, p_loadout jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_mutate_table_studio_preferences(p_favorite_key text, p_favorite_enabled boolean, p_loadout_slot integer, p_loadout jsonb) IS 'Atomically applies one favorite or loadout-slot mutation without replacing another device snapshot.';


--
-- Name: fn_my_agent_roles(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_my_agent_roles() RETURNS TABLE(club_id uuid, club_name text, role text, agent_id uuid, is_overseer boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT a.club_id,
         c.name,
         a.role,
         a.id,
         COALESCE(public.fn_is_union_overseer(uc.union_id, auth.uid()), false)
    FROM agents a
    JOIN clubs c ON c.id = a.club_id
    LEFT JOIN union_clubs uc ON uc.club_id = a.club_id
   WHERE a.user_id = auth.uid()
     AND a.status = 'active'
     AND a.role IN ('super_agent','agent','sub_agent')
   ORDER BY c.name;
$$;


