--
-- Name: fn_my_wallet_ledger(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_my_wallet_ledger(p_club_id uuid, p_limit integer DEFAULT 40, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor   uuid := auth.uid();
  v_limit   int := least(greatest(coalesce(p_limit, 40), 1), 200);
  v_offset  int := greatest(coalesce(p_offset, 0), 0);
  v_role    text;
  v_chips   numeric := 0;
  v_agent_wallet numeric := 0;
  v_promo_wallet numeric := 0;
  v_total   bigint;
  v_in      numeric;
  v_out     numeric;
  v_rows    jsonb;
begin
  if v_actor is null then
    return jsonb_build_object('authorized', false, 'error', 'Not Authenticated');
  end if;

  select cm.role, coalesce(cm.chip_balance, 0) into v_role, v_chips
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = v_actor
     and coalesce(cm.status, 'active') in ('active', 'approved')
   limit 1;
  if v_role is null then
    if exists (select 1 from clubs c where c.id = p_club_id and c.owner_id = v_actor) then
      v_role := 'owner';
    else
      return jsonb_build_object('authorized', false,
        'error', 'You Are Not An Active Member Of This Club');
    end if;
  end if;

  select coalesce(a.agent_wallet_balance, 0), coalesce(a.promo_wallet_balance, 0)
    into v_agent_wallet, v_promo_wallet
    from agents a
   where a.club_id = p_club_id and a.user_id = v_actor;

  select count(*),
         coalesce(sum(t.amount) filter (where t.to_user_id = v_actor), 0),
         coalesce(sum(t.amount) filter (where t.from_user_id = v_actor), 0)
    into v_total, v_in, v_out
    from chip_transactions t
   where t.club_id = p_club_id
     and (t.from_user_id = v_actor or t.to_user_id = v_actor);

  select coalesce(jsonb_agg(r order by r->>'created_at' desc), '[]'::jsonb) into v_rows
  from (
    select jsonb_build_object(
             'id', t.id,
             'created_at', t.created_at,
             'amount', round(coalesce(t.amount, 0), 2),
             'transaction_type', t.transaction_type,
             'notes', t.notes,
             'metadata', coalesce(t.metadata, '{}'::jsonb),
             'is_reversed', coalesce(t.is_reversed, false),
             'direction', case when t.to_user_id = v_actor then 'in' else 'out' end,
             'from_name', public.fn_arena_name(pf.alias, pf.username, pf.display_name,
                                               pf.first_name, pf.last_name, pf.full_name),
             'to_name', public.fn_arena_name(pt.alias, pt.username, pt.display_name,
                                             pt.first_name, pt.last_name, pt.full_name)
           ) as r
      from chip_transactions t
      left join profiles pf on pf.id = t.from_user_id
      left join profiles pt on pt.id = t.to_user_id
     where t.club_id = p_club_id
       and (t.from_user_id = v_actor or t.to_user_id = v_actor)
     order by t.created_at desc
     limit v_limit offset v_offset
  ) s;

  return jsonb_build_object(
    'authorized', true,
    'role', v_role,
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'balances', jsonb_build_object(
      'player_wallet', round(v_chips, 2),
      'agent_wallet', round(v_agent_wallet, 2),
      'promo_wallet', round(v_promo_wallet, 2)),
    'totals', jsonb_build_object(
      'received', round(v_in, 2),
      'sent', round(v_out, 2),
      'net', round(v_in - v_out, 2)),
    'rows', v_rows);
end
$$;


ALTER FUNCTION public.fn_my_wallet_ledger(p_club_id uuid, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_mystery_bounty_awards(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_awards(p_tournament_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM public.tournament_bounty_awards
               WHERE tournament_id = p_tournament_id AND status IN ('revealed','paid','completed')),
    'rows', COALESCE((
      SELECT jsonb_agg(row_to_json(r) ORDER BY r.revealed_at DESC NULLS LAST)
        FROM (
          SELECT a.id AS award_id, a.amount_cents, a.tier,
                 a.tier = 'jackpot' AS is_jackpot,
                 a.revealed_at, a.hand_id, a.table_id,
                 jsonb_build_object('user_id', a.eliminated_user_id,
                   'username', COALESCE(tp.username, 'Player')) AS eliminated,
                 COALESCE((
                   SELECT jsonb_agg(jsonb_build_object(
                            'user_id', rc.user_id,
                            'username', COALESCE(tp2.username, 'Player'),
                            'amount_cents', rc.amount_cents)
                          ORDER BY rc.amount_cents DESC)
                     FROM public.tournament_bounty_award_recipients rc
                     LEFT JOIN public.tournament_players tp2
                       ON tp2.tournament_id = a.tournament_id AND tp2.user_id = rc.user_id
                    WHERE rc.award_id = a.id), '[]'::jsonb) AS recipients
            FROM public.tournament_bounty_awards a
            LEFT JOIN public.tournament_players tp
              ON tp.tournament_id = a.tournament_id AND tp.user_id = a.eliminated_user_id
           WHERE a.tournament_id = p_tournament_id
             AND a.status IN ('revealed','paid','completed')
           ORDER BY a.revealed_at DESC NULLS LAST
           LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 50), 200))
          OFFSET GREATEST(0, COALESCE(p_offset, 0))
        ) r
    ), '[]'::jsonb));
$$;


ALTER FUNCTION public.fn_mystery_bounty_awards(p_tournament_id uuid, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_mystery_bounty_inventory(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_inventory(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'pool_cents', COALESCE(t.mystery_bounty_pool_cents, 0),
    'stage', t.mystery_bounty_stage,
    'profile', t.mystery_bounty_profile,
    'activation', t.mystery_bounty_activation,
    'activation_value', t.mystery_bounty_activation_value,
    'activated_players', t.mystery_bounty_activated_players,
    'activated_at', t.mystery_bounty_activated_at,
    'tiers', COALESCE((
      SELECT jsonb_agg(row_to_json(x) ORDER BY x.amount_cents DESC)
        FROM (
          SELECT c.tier,
                 c.amount_cents,
                 count(*)::int AS original,
                 count(*) FILTER (WHERE c.status IN ('reserved','revealed','paid'))::int AS awarded,
                 count(*) FILTER (WHERE c.status = 'available')::int AS remaining
            FROM public.tournament_bounty_chests c
           WHERE c.tournament_id = p_tournament_id
           GROUP BY c.tier, c.amount_cents
        ) x
    ), '[]'::jsonb))
  FROM public.tournaments t WHERE t.id = p_tournament_id;
$$;


ALTER FUNCTION public.fn_mystery_bounty_inventory(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_mystery_bounty_leaderboard(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_leaderboard(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object('rows', COALESCE((
    SELECT jsonb_agg(row_to_json(x) ORDER BY x.earnings_cents DESC, x.username)
      FROM (
        SELECT rc.user_id,
               COALESCE(tp.username, 'Player') AS username,
               count(*)::int AS bounties_won,
               sum(rc.amount_cents)::bigint AS earnings_cents
          FROM public.tournament_bounty_award_recipients rc
          JOIN public.tournament_bounty_awards a ON a.id = rc.award_id
          LEFT JOIN public.tournament_players tp
            ON tp.tournament_id = a.tournament_id AND tp.user_id = rc.user_id
         WHERE a.tournament_id = p_tournament_id
           AND a.status IN ('revealed','paid','completed')
         GROUP BY rc.user_id, tp.username
      ) x
  ), '[]'::jsonb));
$$;


ALTER FUNCTION public.fn_mystery_bounty_leaderboard(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_mystery_bounty_pay(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_pay(p_award_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  SELECT a.tournament_id INTO v_tournament_id
    FROM public.tournament_bounty_awards a WHERE a.id=p_award_id;
  IF v_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','award_not_found');
  END IF;
  PERFORM 1 FROM public.tournaments t WHERE t.id=v_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  -- The unguarded payer owns the exact award before it writes obligation and
  -- wallet evidence. Own every terminal-visible set in the same canonical
  -- tournament -> obligations -> chests -> awards -> recipients order first;
  -- its later row locks are then transaction-local reacquisitions.
  PERFORM 1 FROM public.tournament_obligations o
   WHERE o.tournament_id = v_tournament_id
   ORDER BY o.kind,o.place NULLS LAST,o.user_id,o.id FOR UPDATE;
  PERFORM 1 FROM public.tournament_bounty_chests c
   WHERE c.tournament_id = v_tournament_id ORDER BY c.id FOR UPDATE;
  PERFORM 1 FROM public.tournament_bounty_awards a
   WHERE a.tournament_id = v_tournament_id ORDER BY a.id FOR UPDATE;
  PERFORM 1 FROM public.tournament_bounty_award_recipients r
   JOIN public.tournament_bounty_awards a ON a.id = r.award_id
   WHERE a.tournament_id = v_tournament_id
   ORDER BY r.user_id,r.id FOR UPDATE OF r;
  RETURN public.fn_mystery_bounty_pay_unguarded_20260907(p_award_id);
END;
$$;


ALTER FUNCTION public.fn_mystery_bounty_pay(p_award_id uuid) OWNER TO postgres;

--
-- Name: fn_mystery_bounty_pay_unguarded_20260907(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_pay_unguarded_20260907(p_award_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_a record; v_r record; v_paid bigint := 0; v_credited boolean; v_refused int := 0;
  v_chest_status text;
  v_prior numeric; v_settle jsonb;
BEGIN
  SELECT * INTO v_a FROM public.tournament_bounty_awards WHERE id = p_award_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'award_not_found'); END IF;

  IF v_a.status = 'completed' THEN
    IF v_a.bounty_obligation_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.tournament_bounty_obligations o
       WHERE o.id=v_a.bounty_obligation_id AND o.state='settled'
         AND public.fn_bounty_obligation_has_complete_marker(o.id)
    ) THEN
      RETURN jsonb_build_object('ok',false,'reason','completed_award_marker_incomplete',
                                'award_id',p_award_id);
    END IF;
    RETURN jsonb_build_object('ok', true, 'already', true, 'award_id', p_award_id,
                              'amount_cents', v_a.amount_cents);
  END IF;
  IF v_a.status = 'reserved' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_yet_revealed');
  END IF;

  -- SETTLED IS SETTLED (2026-08-30). fn_mystery_bounty_settle swept this chest
  -- to the champion and voided the award in the same transaction. Paying it
  -- again mints the chest a second time under a different idempotency key.
  IF v_a.status = 'void' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'award_voided_by_settlement',
                              'award_id', p_award_id);
  END IF;

  SELECT status INTO v_chest_status
    FROM public.tournament_bounty_chests WHERE id = v_a.chest_id;
  IF v_chest_status = 'void' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'chest_settled_to_champion',
                              'award_id', p_award_id);
  END IF;

  FOR v_r IN
    SELECT * FROM public.tournament_bounty_award_recipients
     WHERE award_id = p_award_id AND paid_at IS NULL AND amount_cents > 0
     ORDER BY user_id
     FOR UPDATE
  LOOP
    /* ONE PAYER (R3, 2026-09-02). The recipient row (paid_at) is the replay
       guard for this chest; the obligation is the cumulative mystery total for
       this player in this event, so a second chest is a higher total, never a
       denied one. A refusal leaves the recipient unpaid and the award
       incomplete, exactly as a refused fn_credit_and_log did. */
    v_prior := COALESCE((SELECT o.amount_paid FROM public.tournament_obligations o
                          WHERE o.tournament_id = v_a.tournament_id AND o.kind = 'mystery_bounty'
                            AND o.place IS NULL AND o.user_id = v_r.user_id), 0);
    v_settle := public.fn_settle_tournament_obligation(
      v_a.tournament_id, 'mystery_bounty', NULL, v_r.user_id,
      round(v_prior + (v_r.amount_cents / 100.0), 2),
      'fn_mystery_bounty_pay', 'Mystery bounty revealed from eliminated player');
    v_credited := COALESCE((v_settle->>'ok')::boolean, false);

    IF COALESCE(v_credited, false)
       AND round(COALESCE((v_settle->>'paid')::numeric,0),2)
           = round((v_r.amount_cents / 100.0)::numeric,2) THEN
      UPDATE public.tournament_bounty_award_recipients SET paid_at = now() WHERE id = v_r.id;

      v_paid := v_paid + v_r.amount_cents;
      UPDATE public.tournament_players
         SET bounties_collected = COALESCE(bounties_collected, 0) + 1,
             bounty_winnings = round(COALESCE(bounty_winnings, 0) + (v_r.amount_cents / 100.0), 2)
       WHERE tournament_id = v_a.tournament_id AND user_id = v_r.user_id;

      INSERT INTO public.tournament_bounties
        (tournament_id, eliminated_player_id, collector_player_id, bounty_amount,
         is_mystery_revealed, bounty_obligation_id)
      VALUES (v_a.tournament_id, v_a.eliminated_user_id, v_r.user_id,
              (v_r.amount_cents / 100.0)::numeric, true, v_a.bounty_obligation_id)
      ON CONFLICT DO NOTHING;
    ELSE
      RAISE EXCEPTION 'fn_mystery_bounty_pay: recipient % refused for award % (%)',
        v_r.user_id, p_award_id, COALESCE(v_settle->>'refused_reason','unknown')
        USING ERRCODE='check_violation';
    END IF;
  END LOOP;

  IF v_paid > 0 THEN
    UPDATE public.tournaments
       SET bounty_pool_paid = round(COALESCE(bounty_pool_paid, 0) + (v_paid / 100.0), 2)
     WHERE id = v_a.tournament_id;
  END IF;

  -- A zero-cent split is still an explicitly settled recipient,
    -- not a NULL marker that completion can silently ignore.
    UPDATE public.tournament_bounty_award_recipients
       SET paid_at=COALESCE(paid_at,now())
     WHERE award_id=p_award_id AND amount_cents=0;

  IF v_refused = 0 AND NOT EXISTS (
    SELECT 1 FROM public.tournament_bounty_award_recipients
     WHERE award_id=p_award_id AND paid_at IS NULL
  ) THEN
    UPDATE public.tournament_bounty_awards
       SET status = 'completed', paid_at = now() WHERE id = p_award_id;
    UPDATE public.tournament_bounty_chests SET status = 'paid' WHERE id = v_a.chest_id;
  ELSE
    INSERT INTO financial_alerts (severity, source, message, context)
    VALUES ('critical', 'fn_mystery_bounty_pay',
            'Mystery bounty award left incomplete: a recipient credit was refused',
            jsonb_build_object('award_id', p_award_id,
                               'tournament_id', v_a.tournament_id,
                               'refused_recipients', v_refused,
                               'paid_cents', v_paid,
                               'award_cents', v_a.amount_cents,
                               'refused_reason', v_settle->>'refused_reason',
                               'detail', 'the award is NOT marked completed and the chest is NOT marked paid, so it stays retryable'));
  END IF;

  IF v_a.bounty_obligation_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations o
     WHERE o.id=v_a.bounty_obligation_id AND o.state='settled'
       AND public.fn_bounty_obligation_has_complete_marker(o.id)
  ) THEN
    RAISE EXCEPTION 'mystery award % completed without its exact settled marker',p_award_id
      USING ERRCODE='check_violation';
  END IF;

  RETURN jsonb_build_object('ok', true, 'already', false, 'award_id', p_award_id,
    'amount_cents', v_a.amount_cents, 'paid_cents', v_paid,
    'refused_recipients', v_refused,
    'recipients', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('user_id', user_id, 'amount_cents', amount_cents))
        FROM public.tournament_bounty_award_recipients WHERE award_id = p_award_id), '[]'::jsonb));
END;
$$;


ALTER FUNCTION public.fn_mystery_bounty_pay_unguarded_20260907(p_award_id uuid) OWNER TO postgres;

--
-- Name: fn_mystery_bounty_reserve(uuid, uuid, jsonb, uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_reserve(p_tournament_id uuid, p_eliminated_user_id uuid, p_recipients jsonb, p_table_id uuid, p_hand_id text, p_op_id uuid, p_reveal_ms integer DEFAULT 20000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  o public.tournament_bounty_obligations%ROWTYPE;
  v_recipients jsonb;
  v_result jsonb;
  v_op_hex text;
  v_op_id uuid;
  v_prior_context text;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  PERFORM 1 FROM public.tournaments t WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','tournament_not_found'); END IF;
  SELECT * INTO o FROM public.tournament_bounty_obligations bo
   WHERE bo.tournament_id=p_tournament_id
     AND bo.eliminated_user_id=p_eliminated_user_id
     AND bo.mode='mystery_chest'
     AND bo.table_id=p_table_id AND bo.hand_id::text=p_hand_id
   ORDER BY bo.hand_number DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','bounty_obligation_not_ready');
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
           'user_id',e->>'user_id','weight',1,
           'is_designated_revealer',(e->>'user_id')::uuid=o.knocker_user_id)
           ORDER BY e->>'user_id')
    INTO v_recipients FROM jsonb_array_elements(o.claimants) e;
  v_op_hex := md5('mb:'||o.id::text);
  v_op_id := (substr(v_op_hex,1,8)||'-'||substr(v_op_hex,9,4)||'-4'||substr(v_op_hex,14,3)
    ||'-8'||substr(v_op_hex,18,3)||'-'||substr(v_op_hex,21,12))::uuid;
  v_prior_context := current_setting('app.bounty_obligation_id',true);
  PERFORM set_config('app.bounty_obligation_id',o.id::text,true);
  v_result := public.fn_mystery_bounty_reserve_unguarded_20260907(
    o.tournament_id,o.eliminated_user_id,v_recipients,o.table_id,o.hand_id::text,
    v_op_id,p_reveal_ms);
  PERFORM set_config('app.bounty_obligation_id',COALESCE(v_prior_context,''),true);
  IF NOT COALESCE((v_result->>'ok')::boolean,false) THEN RETURN v_result; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tournament_bounty_awards a
     WHERE a.id=(v_result->>'award_id')::uuid AND a.bounty_obligation_id=o.id
       AND NOT EXISTS (
         SELECT 1 FROM jsonb_array_elements(o.claimants) c
          WHERE NOT EXISTS (SELECT 1 FROM public.tournament_bounty_award_recipients r
                             WHERE r.award_id=a.id
                               AND r.user_id=(c->>'user_id')::uuid)
       )
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_bounty_award_recipients r
          WHERE r.award_id=a.id
            AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(o.claimants) c
                             WHERE (c->>'user_id')::uuid=r.user_id)
       )
  ) THEN
    RAISE EXCEPTION 'mystery award recipients do not match obligation %',o.id;
  END IF;
  RETURN v_result || jsonb_build_object('obligation_id',o.id,'recipients_verified',true);
END;
$$;


ALTER FUNCTION public.fn_mystery_bounty_reserve(p_tournament_id uuid, p_eliminated_user_id uuid, p_recipients jsonb, p_table_id uuid, p_hand_id text, p_op_id uuid, p_reveal_ms integer) OWNER TO postgres;

--
-- Name: fn_mystery_bounty_reserve_unguarded_20260907(uuid, uuid, jsonb, uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_reserve_unguarded_20260907(p_tournament_id uuid, p_eliminated_user_id uuid, p_recipients jsonb, p_table_id uuid, p_hand_id text, p_op_id uuid, p_reveal_ms integer DEFAULT 20000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_stage text;
  v_existing record;
  v_chest record;
  v_award_id uuid;
  v_revealer uuid;
  v_idx int; v_total int;
  v_n int;
BEGIN
  IF p_eliminated_user_id IS NULL OR p_op_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'missing_party');
  END IF;

  -- IDEMPOTENCY, TWO WAYS. op_id catches the same call retrying; the
  -- (tournament, eliminated) pair catches the elimination sweep processing the
  -- same bustout twice, which it does after any restart.
  SELECT id, status, table_id INTO v_existing
    FROM public.tournament_bounty_awards
   WHERE op_id = p_op_id
      OR (tournament_id = p_tournament_id AND eliminated_user_id = p_eliminated_user_id
          AND (
            bounty_obligation_id = (SELECT o.id FROM tournament_bounty_obligations o
              WHERE o.tournament_id=p_tournament_id
                AND o.eliminated_user_id=p_eliminated_user_id
                AND o.mode='mystery_chest' AND o.hand_id::text=p_hand_id
              ORDER BY o.created_at DESC LIMIT 1)
            OR (bounty_obligation_id IS NULL AND NOT EXISTS (
              SELECT 1 FROM tournament_bounty_obligations o
               WHERE o.tournament_id=p_tournament_id
                 AND o.eliminated_user_id=p_eliminated_user_id
                 AND o.mode='mystery_chest' AND o.hand_id::text=p_hand_id))
          ))
   LIMIT 1;

  IF FOUND THEN
    SELECT count(*) INTO v_total FROM public.tournament_bounty_awards a
     WHERE a.tournament_id = p_tournament_id
       AND a.table_id IS NOT DISTINCT FROM v_existing.table_id
       AND a.status IN ('reserved','revealed');
    SELECT count(*) INTO v_idx FROM public.tournament_bounty_awards a
     WHERE a.tournament_id = p_tournament_id
       AND a.table_id IS NOT DISTINCT FROM v_existing.table_id
       AND a.status IN ('reserved','revealed')
       AND a.reserved_at <= (SELECT reserved_at FROM public.tournament_bounty_awards WHERE id = v_existing.id);
    SELECT user_id INTO v_revealer FROM public.tournament_bounty_award_recipients
     WHERE award_id = v_existing.id AND is_designated_revealer LIMIT 1;
    RETURN jsonb_build_object('ok', true, 'already', true, 'award_id', v_existing.id,
      'status', v_existing.status, 'queue_index', GREATEST(v_idx, 1), 'queue_total', GREATEST(v_total, 1),
      'designated_revealer', v_revealer,
      'recipient_user_ids', COALESCE((SELECT jsonb_agg(user_id) FROM public.tournament_bounty_award_recipients WHERE award_id = v_existing.id), '[]'::jsonb));
  END IF;

  SELECT mystery_bounty_stage INTO v_stage FROM public.tournaments WHERE id = p_tournament_id;
  IF v_stage IS DISTINCT FROM 'active' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'mystery_phase_not_active', 'stage', v_stage);
  END IF;

  IF p_recipients IS NULL OR jsonb_typeof(p_recipients) <> 'array'
     OR jsonb_array_length(p_recipients) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_recipients');
  END IF;

  -- THE DRAW. SKIP LOCKED means two knockouts landing in the same instant take
  -- two DIFFERENT chests; ORDER BY seq means they take them in the order the
  -- CSPRNG shuffle fixed at seed time.
  UPDATE public.tournament_bounty_chests
     SET status = 'reserved'
   WHERE id = (
     SELECT id FROM public.tournament_bounty_chests
      WHERE tournament_id = p_tournament_id AND status = 'available'
      ORDER BY seq
      LIMIT 1
      FOR UPDATE SKIP LOCKED
   )
  RETURNING id, tier, amount_cents INTO v_chest;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'inventory_exhausted');
  END IF;

  INSERT INTO public.tournament_bounty_awards
    (tournament_id, chest_id, table_id, hand_id, eliminated_user_id,
     amount_cents, tier, status, op_id, reveal_deadline_at)
  VALUES (p_tournament_id, v_chest.id, p_table_id, p_hand_id, p_eliminated_user_id,
          v_chest.amount_cents, v_chest.tier, 'reserved', p_op_id,
          now() + make_interval(secs => GREATEST(1, COALESCE(p_reveal_ms, 20000)) / 1000.0))
  RETURNING id INTO v_award_id;

  UPDATE public.tournament_bounty_chests SET award_id = v_award_id WHERE id = v_chest.id;

  -- THE SPLIT. Largest remainder over the weights, leftover cents to the
  -- largest fractional parts first, so a three-way knockout out of an odd
  -- chest still pays out exactly the chest.
  WITH raw AS (
    SELECT (r->>'user_id')::uuid AS user_id,
           GREATEST(0, COALESCE((r->>'weight')::numeric, 0)) AS weight,
           COALESCE((r->>'is_designated_revealer')::boolean, false) AS flagged
      FROM jsonb_array_elements(p_recipients) r
     WHERE (r->>'user_id') IS NOT NULL
  ),
  dedup AS (
    SELECT user_id, sum(weight) AS weight, bool_or(flagged) AS flagged
      FROM raw GROUP BY user_id
  ),
  norm AS (
    SELECT user_id,
           CASE WHEN (SELECT sum(weight) FROM dedup) > 0 THEN weight ELSE 1 END AS weight,
           flagged
      FROM dedup
  ),
  alloc AS (
    SELECT n.user_id, n.weight,
           floor(v_chest.amount_cents * n.weight / t.w)::bigint AS fl,
           (v_chest.amount_cents * n.weight / t.w)
             - floor(v_chest.amount_cents * n.weight / t.w) AS frac
      FROM norm n CROSS JOIN (SELECT sum(weight) AS w FROM norm) t
  ),
  ranked AS (
    SELECT a.*,
           row_number() OVER (ORDER BY a.frac DESC, a.weight DESC, a.user_id) AS rn,
           (SELECT v_chest.amount_cents - COALESCE(sum(fl), 0) FROM alloc) AS leftover
      FROM alloc a
  )
  INSERT INTO public.tournament_bounty_award_recipients
    (award_id, user_id, amount_cents, is_designated_revealer)
  SELECT v_award_id, user_id, fl + CASE WHEN rn <= leftover THEN 1 ELSE 0 END, false
    FROM ranked
  ON CONFLICT (award_id, user_id) DO NOTHING;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_recipients');
  END IF;

  SELECT user_id INTO v_revealer FROM (
    SELECT (r->>'user_id')::uuid AS user_id,
           GREATEST(0, COALESCE((r->>'weight')::numeric, 0)) AS weight,
           COALESCE((r->>'is_designated_revealer')::boolean, false) AS flagged
      FROM jsonb_array_elements(p_recipients) r
     WHERE (r->>'user_id') IS NOT NULL
  ) q ORDER BY q.flagged DESC, q.weight DESC, q.user_id LIMIT 1;

  UPDATE public.tournament_bounty_award_recipients
     SET is_designated_revealer = (user_id = v_revealer)
   WHERE award_id = v_award_id;

  PERFORM 1 FROM public.tournament_bounty_award_recipients
    WHERE award_id = v_award_id HAVING sum(amount_cents) = v_chest.amount_cents;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'mystery bounty split lost money on award %', v_award_id;
  END IF;

  SELECT count(*) INTO v_total FROM public.tournament_bounty_awards a
   WHERE a.tournament_id = p_tournament_id
     AND a.table_id IS NOT DISTINCT FROM p_table_id
     AND a.status IN ('reserved','revealed');
  v_idx := v_total;

  RETURN jsonb_build_object('ok', true, 'already', false, 'award_id', v_award_id,
    'queue_index', GREATEST(v_idx, 1), 'queue_total', GREATEST(v_total, 1),
    'designated_revealer', v_revealer,
    'reveal_deadline_ms', GREATEST(1, COALESCE(p_reveal_ms, 20000)),
    'recipient_user_ids', COALESCE((SELECT jsonb_agg(user_id) FROM public.tournament_bounty_award_recipients WHERE award_id = v_award_id), '[]'::jsonb));
END;
$$;


ALTER FUNCTION public.fn_mystery_bounty_reserve_unguarded_20260907(p_tournament_id uuid, p_eliminated_user_id uuid, p_recipients jsonb, p_table_id uuid, p_hand_id text, p_op_id uuid, p_reveal_ms integer) OWNER TO postgres;

--
-- Name: fn_mystery_bounty_reveal(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_reveal(p_award_id uuid, p_actor_user_id uuid, p_auto boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_a record;
  v_revealer uuid;
  v_payload jsonb;
  v_is_engine boolean;
  v_auto boolean;
  v_actor uuid;
BEGIN
  -- Who is REALLY calling. Not current_user: SECURITY DEFINER rewrites that to
  -- the owner, so it reports 'postgres' for a browser too.
  v_is_engine := COALESCE(auth.role(), 'service_role') = 'service_role';

  -- A caller-supplied flag can no longer skip the check, and a caller-supplied
  -- id can no longer impersonate the revealer.
  v_auto  := v_is_engine AND COALESCE(p_auto, false);
  v_actor := CASE WHEN v_is_engine THEN p_actor_user_id ELSE auth.uid() END;

  SELECT * INTO v_a FROM public.tournament_bounty_awards WHERE id = p_award_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'award_not_found'); END IF;

  SELECT user_id INTO v_revealer FROM public.tournament_bounty_award_recipients
   WHERE award_id = p_award_id AND is_designated_revealer LIMIT 1;

  -- AUTHORISATION. Anyone can call an RPC, so this is the line that stops a
  -- spectator opening someone else's chest.
  IF NOT v_auto AND (v_actor IS NULL OR v_actor IS DISTINCT FROM v_revealer) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_the_revealer');
  END IF;

  IF v_a.status = 'reserved' THEN
    UPDATE public.tournament_bounty_awards
       SET status = 'revealed', revealed_at = now() WHERE id = p_award_id;
    UPDATE public.tournament_bounty_chests SET status = 'revealed' WHERE id = v_a.chest_id;
  END IF;
  -- Already revealed / paid / completed falls through and returns the same
  -- payload: a double tap, a reconnect replaying the tap, and the deadline
  -- firing just after a real tap must all show the player the same number.

  v_payload := jsonb_build_object(
    'ok', true,
    'award_id', v_a.id,
    'tournament_id', v_a.tournament_id,
    'table_id', v_a.table_id,
    'hand_id', v_a.hand_id,
    'amount_cents', v_a.amount_cents,
    'tier', v_a.tier,
    'is_jackpot', v_a.tier = 'jackpot',
    'eliminated_user_id', v_a.eliminated_user_id,
    'designated_revealer', v_revealer,
    'recipients', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('user_id', user_id, 'amount_cents', amount_cents)
                       ORDER BY amount_cents DESC, user_id)
        FROM public.tournament_bounty_award_recipients WHERE award_id = p_award_id), '[]'::jsonb)
  );
  RETURN v_payload;
END;
$$;


ALTER FUNCTION public.fn_mystery_bounty_reveal(p_award_id uuid, p_actor_user_id uuid, p_auto boolean) OWNER TO postgres;

--
-- Name: FUNCTION fn_mystery_bounty_reveal(p_award_id uuid, p_actor_user_id uuid, p_auto boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_mystery_bounty_reveal(p_award_id uuid, p_actor_user_id uuid, p_auto boolean) IS 'Uncovers a reserved mystery bounty chest. p_auto is honoured only for service_role; every other caller acts as auth.uid() and p_actor_user_id is ignored. Hardened 2026-08-27 after a proven bypass via p_auto => true.';


--
-- Name: fn_mystery_bounty_seed(uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_seed(p_tournament_id uuid, p_players_remaining integer, p_chests jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t record;
  v_pool_cents bigint;
  v_bounty_cents bigint;
  v_m numeric; v_r numeric;
  v_sum bigint; v_count int;
BEGIN
  SELECT id, is_mystery_bounty, prize_pool_finalized, bounty_pool,
         bounty_pool_paid, mystery_bounty_stage,
         mystery_bounty_pool_percent, mystery_bounty_regular_pool_percent,
         mystery_bounty_pool_cents
    INTO v_t FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;

  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found'); END IF;
  IF NOT COALESCE(v_t.is_mystery_bounty, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_mystery_bounty');
  END IF;

  -- IDEMPOTENT. The engine's activation check runs on a five-second sweep and
  -- a restart re-runs it; seeding twice would double the inventory and the
  -- event could never reconcile.
  IF v_t.mystery_bounty_stage <> 'pending' THEN
    SELECT count(*), COALESCE(sum(amount_cents), 0) INTO v_count, v_sum
      FROM public.tournament_bounty_chests WHERE tournament_id = p_tournament_id;
    RETURN jsonb_build_object('ok', true, 'already_seeded', true,
      'stage', v_t.mystery_bounty_stage, 'chests', v_count,
      'pool_cents', COALESCE(v_t.mystery_bounty_pool_cents, v_sum));
  END IF;

  -- ENTRY MUST BE CLOSED. bounty_pool still grows with every late entry,
  -- rebuy and add-on; an inventory built before the close is built from a pool
  -- smaller than the one the event ends up holding.
  IF NOT COALESCE(v_t.prize_pool_finalized, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'entry_still_open');
  END IF;

  IF p_chests IS NULL OR jsonb_typeof(p_chests) <> 'array' OR jsonb_array_length(p_chests) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'chests_required');
  END IF;
  IF jsonb_array_length(p_chests) <> GREATEST(p_players_remaining - 1, 0) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'chest_count_mismatch',
      'chests', jsonb_array_length(p_chests), 'players_remaining', p_players_remaining);
  END IF;

  v_bounty_cents := round(COALESCE(v_t.bounty_pool, 0) * 100)::bigint;
  v_m := GREATEST(0, COALESCE(v_t.mystery_bounty_pool_percent, 50));
  v_r := GREATEST(0, COALESCE(v_t.mystery_bounty_regular_pool_percent, 50));
  IF v_m + v_r <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'pool_split_misconfigured');
  END IF;
  v_pool_cents := floor(v_bounty_cents * v_m / (v_m + v_r))::bigint;

  IF v_pool_cents > v_bounty_cents - round(COALESCE(v_t.bounty_pool_paid, 0) * 100)::bigint THEN
    v_pool_cents := GREATEST(0, v_bounty_cents - round(COALESCE(v_t.bounty_pool_paid, 0) * 100)::bigint);
  END IF;

  IF v_pool_cents <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'empty_pool');
  END IF;

  SELECT COALESCE(sum((c->>'amount_cents')::bigint), 0) INTO v_sum
    FROM jsonb_array_elements(p_chests) c;

  IF v_sum <> v_pool_cents THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'inventory_mismatch',
      'inventory_cents', v_sum, 'pool_cents', v_pool_cents);
  END IF;

  INSERT INTO public.tournament_bounty_chests (tournament_id, seq, tier, amount_cents)
  SELECT p_tournament_id,
         COALESCE((c->>'seq')::int, ord::int),
         c->>'tier',
         (c->>'amount_cents')::bigint
    FROM jsonb_array_elements(p_chests) WITH ORDINALITY AS t(c, ord)
  ON CONFLICT (tournament_id, seq) DO NOTHING;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> jsonb_array_length(p_chests) THEN
    RAISE EXCEPTION 'mystery bounty seed inserted % of % chests', v_count, jsonb_array_length(p_chests);
  END IF;

  UPDATE public.tournaments
     SET mystery_bounty_stage = 'active',
         mystery_bounty_activated_at = now(),
         mystery_bounty_activated_players = p_players_remaining,
         mystery_bounty_pool_cents = v_pool_cents
   WHERE id = p_tournament_id;

  RETURN jsonb_build_object('ok', true, 'already_seeded', false,
    'pool_cents', v_pool_cents, 'chests', v_count, 'stage', 'active');
END;
$$;


ALTER FUNCTION public.fn_mystery_bounty_seed(p_tournament_id uuid, p_players_remaining integer, p_chests jsonb) OWNER TO postgres;

--
-- Name: fn_mystery_bounty_settle(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_settle(p_tournament_id uuid, p_winner_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_step jsonb;
  v_canonical_winner uuid;
  v_winner_count integer;
  v_receipt public.tournament_bounty_completion_receipts%ROWTYPE;
  v_award record;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  -- A completed terminal receipt is the answer even after awards were voided,
  -- the stage changed, or standings were archived.  Those mutable rows cannot
  -- be used to reconstruct a prior result.
  SELECT * INTO v_receipt FROM public.tournament_bounty_completion_receipts
   WHERE tournament_id=p_tournament_id AND mystery_settled_at IS NOT NULL;
  IF FOUND THEN
    IF v_receipt.winner_user_id IS DISTINCT FROM p_winner_user_id
       OR jsonb_typeof(v_receipt.mystery_result) IS DISTINCT FROM 'object' THEN
      RETURN jsonb_build_object('ok',false,'reason','completion_receipt_conflict');
    END IF;
    RETURN v_receipt.mystery_result;
  END IF;
  PERFORM 1 FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','tournament_not_found'); END IF;
  SELECT * INTO v_receipt FROM public.tournament_bounty_completion_receipts
   WHERE tournament_id=p_tournament_id AND mystery_settled_at IS NOT NULL;
  IF FOUND THEN
    IF v_receipt.winner_user_id IS DISTINCT FROM p_winner_user_id
       OR jsonb_typeof(v_receipt.mystery_result) IS DISTINCT FROM 'object' THEN
      RETURN jsonb_build_object('ok',false,'reason','completion_receipt_conflict');
    END IF;
    RETURN v_receipt.mystery_result;
  END IF;
  SELECT count(DISTINCT tp.user_id),(array_agg(tp.user_id ORDER BY tp.user_id))[1]
    INTO v_winner_count,v_canonical_winner
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.status='winner' AND tp.position=1;
  IF v_winner_count<>1 OR p_winner_user_id IS DISTINCT FROM v_canonical_winner THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_tournament_winner');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_bounty_completion_receipts r
              WHERE r.tournament_id=p_tournament_id
                AND r.winner_user_id IS DISTINCT FROM p_winner_user_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','completion_winner_conflict');
  END IF;
  -- Reserved/revealed awards are earned debts, not inventory the champion may
  -- absorb.  Resolve each exact award under the tournament lock before the
  -- historical terminal body calculates the genuinely unclaimed inventory.
  FOR v_award IN
    SELECT a.id,a.status FROM public.tournament_bounty_awards a
     WHERE a.tournament_id=p_tournament_id
       AND a.status IN ('reserved','revealed','paid')
     ORDER BY a.id FOR UPDATE
  LOOP
    IF v_award.status='reserved' THEN
      v_step := public.fn_mystery_bounty_reveal(v_award.id,NULL,true);
      IF NOT COALESCE((v_step->>'ok')::boolean,false) THEN
        RAISE EXCEPTION 'terminal mystery reveal refused for award %: %',
          v_award.id,COALESCE(v_step::text,'null') USING ERRCODE='check_violation';
      END IF;
    END IF;
    v_step := public.fn_mystery_bounty_pay(v_award.id);
    IF NOT COALESCE((v_step->>'ok')::boolean,false)
       OR NOT EXISTS (
         SELECT 1 FROM public.tournament_bounty_awards a
          WHERE a.id=v_award.id AND a.status='completed'
            AND NOT EXISTS (
              SELECT 1 FROM public.tournament_bounty_award_recipients r
               WHERE r.award_id=a.id AND r.paid_at IS NULL
            )
       ) THEN
      RAISE EXCEPTION 'terminal mystery payment incomplete for award %: %',
        v_award.id,COALESCE(v_step::text,'null') USING ERRCODE='check_violation';
    END IF;
  END LOOP;
  IF public.fn_tournament_has_unsettled_bounties(p_tournament_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','pending_bounty_obligations');
  END IF;
  v_result := public.fn_mystery_bounty_settle_unguarded_20260907(
    p_tournament_id,p_winner_user_id);
  IF NOT COALESCE((v_result->>'ok')::boolean,false)
     OR NOT COALESCE((v_result->>'balanced')::boolean,false) THEN
    -- The historical body can already have paid a clamp/residual or voided a
    -- chest before reporting imbalance. A normal RETURN would commit that
    -- partial terminal state. The guarded contract is all-or-nothing.
    RAISE EXCEPTION 'mystery bounty settlement refused or unbalanced: %',v_result
      USING ERRCODE='check_violation';
  END IF;
  INSERT INTO public.tournament_bounty_completion_receipts
    (tournament_id,winner_user_id,mystery_settled_at,mystery_result,updated_at)
  VALUES (p_tournament_id,p_winner_user_id,now(),v_result,now())
  ON CONFLICT (tournament_id) DO UPDATE
    SET mystery_settled_at=COALESCE(public.tournament_bounty_completion_receipts.mystery_settled_at,EXCLUDED.mystery_settled_at),
        mystery_result=COALESCE(public.tournament_bounty_completion_receipts.mystery_result,EXCLUDED.mystery_result),
        winner_user_id=COALESCE(public.tournament_bounty_completion_receipts.winner_user_id,EXCLUDED.winner_user_id),
        updated_at=now();
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_mystery_bounty_settle(p_tournament_id uuid, p_winner_user_id uuid) OWNER TO postgres;

--
-- Name: fn_mystery_bounty_settle_unguarded_20260907(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_settle_unguarded_20260907(p_tournament_id uuid, p_winner_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_pool bigint; v_paid bigint; v_unclaimed bigint; v_stage text;
  v_award record;
  v_funded numeric; v_ledger numeric;
  v_room bigint; v_residual bigint;
  v_prior numeric; v_settle jsonb;
BEGIN
  SELECT mystery_bounty_stage, COALESCE(mystery_bounty_pool_cents, 0), COALESCE(bounty_pool, 0)
    INTO v_stage, v_pool, v_funded
    FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found'); END IF;
  IF v_stage = 'pending' THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'never_activated', 'unclaimed_cents', 0,
                              'pool_cents', 0, 'settled_cents', 0, 'balanced', true, 'variance_cents', 0);
  END IF;

  -- AN OPENED CHEST BELONGS TO WHOEVER OPENED IT (2026-08-30). A reveal that
  -- landed just before the event ended used to leave a live award behind while
  -- the sweep below paid the same chest to the champion. Pay it here, inside
  -- the settlement transaction: that marks the chest 'paid' and takes it out
  -- of the unclaimed set, so the two payers can no longer both see it.
  FOR v_award IN
    SELECT id FROM public.tournament_bounty_awards
     WHERE tournament_id = p_tournament_id AND status = 'revealed'
     ORDER BY id
     FOR UPDATE
  LOOP
    PERFORM public.fn_mystery_bounty_pay(v_award.id);
  END LOOP;

  SELECT COALESCE(sum(r.amount_cents), 0) INTO v_paid
    FROM public.tournament_bounty_award_recipients r
    JOIN public.tournament_bounty_awards a ON a.id = r.award_id
   WHERE a.tournament_id = p_tournament_id AND r.paid_at IS NOT NULL;

  SELECT COALESCE(sum(amount_cents), 0) INTO v_unclaimed
    FROM public.tournament_bounty_chests
   WHERE tournament_id = p_tournament_id AND status IN ('available','reserved','revealed');

  v_residual := v_unclaimed;

  -- THE RESIDUAL CANNOT EXCEED WHAT THE POOL STILL HOLDS. Measured from the
  -- ledger for the same reason fn_finalize_bounty_pool measures from it: the
  -- ledger cannot be stale relative to the money, because it IS the money.
  IF v_residual > 0 AND v_funded > 0 THEN
    SELECT round(COALESCE(SUM(
             CASE WHEN lower(wt.type) = 'debit' THEN -abs(wt.amount) ELSE wt.amount END
           ), 0), 2)
      INTO v_ledger
      FROM wallet_transactions wt
     WHERE wt.related_entity_id = p_tournament_id
       AND wt.category = 'bounty';

    v_room := GREATEST(0, floor((v_funded - COALESCE(v_ledger, 0)) * 100))::bigint;

    IF v_residual > v_room THEN
      INSERT INTO financial_alerts (severity, source, message, context)
      VALUES ('critical', 'fn_mystery_bounty_settle',
              'Champion residual clamped: the unclaimed chests are worth more than the bounty pool still holds',
              jsonb_build_object('tournament_id', p_tournament_id,
                                 'unclaimed_cents', v_unclaimed,
                                 'room_cents', v_room,
                                 'ledger_paid', v_ledger,
                                 'bounty_pool', v_funded,
                                 'detail', 'the clamp is not the bug, it is the seatbelt -- find the payer that already spent the pool'));
      v_residual := v_room;
    END IF;
  END IF;

  IF p_winner_user_id IS NOT NULL THEN
    IF v_residual > 0 THEN
      -- UNCLAIMED CHESTS GO TO THE CHAMPION. The last player standing was never
      -- knocked out, so their own chest - and any chest a broken elimination
      -- left behind - is theirs.
      /* ONE PAYER (R3, 2026-09-02): the champion's cumulative 'mystery_bounty'
         obligation rises by the residual. A refusal RAISES so the chests are
         not voided below with the money unpaid; the settlement stays
         retryable (stage not 'complete'). */
      v_prior := COALESCE((SELECT o.amount_paid FROM public.tournament_obligations o
                            WHERE o.tournament_id = p_tournament_id AND o.kind = 'mystery_bounty'
                              AND o.place IS NULL AND o.user_id = p_winner_user_id), 0);
      v_settle := public.fn_settle_tournament_obligation(
        p_tournament_id, 'mystery_bounty', NULL, p_winner_user_id,
        round(v_prior + (v_residual / 100.0), 2),
        'fn_mystery_bounty_settle', 'Unclaimed mystery bounty chests awarded to champion');
      IF NOT COALESCE((v_settle->>'ok')::boolean, false) THEN
        RAISE EXCEPTION 'fn_mystery_bounty_settle: residual of % cents to % in tournament % refused (%)',
          v_residual, p_winner_user_id, p_tournament_id, COALESCE(v_settle->>'refused_reason', 'unknown');
      END IF;
      UPDATE public.tournament_players
         SET bounty_winnings = round(COALESCE(bounty_winnings, 0) + (v_residual / 100.0), 2)
       WHERE tournament_id = p_tournament_id AND user_id = p_winner_user_id;
      UPDATE public.tournaments
         SET bounty_pool_paid = round(COALESCE(bounty_pool_paid, 0) + (v_residual / 100.0), 2)
       WHERE id = p_tournament_id;
      v_paid := v_paid + v_residual;
    END IF;

    -- NOTHING MAY PAY THESE CHESTS AFTER THIS POINT. The award is voided in the
    -- same transaction as the sweep, and fn_mystery_bounty_pay refuses a voided
    -- award, so a reveal still in flight cannot mint the chest a second time.
    UPDATE public.tournament_bounty_awards a
       SET status = 'void'
     WHERE a.tournament_id = p_tournament_id
       AND a.status <> 'completed'
       AND EXISTS (SELECT 1 FROM public.tournament_bounty_chests c
                    WHERE c.id = a.chest_id
                      AND c.status IN ('available','reserved','revealed'));

    UPDATE public.tournament_bounty_chests SET status = 'void'
     WHERE tournament_id = p_tournament_id AND status IN ('available','reserved','revealed');
  END IF;

  UPDATE public.tournaments SET mystery_bounty_stage = 'complete' WHERE id = p_tournament_id;

  RETURN jsonb_build_object('ok', true,
    'pool_cents', v_pool, 'settled_cents', v_paid, 'unclaimed_cents', v_unclaimed,
    'residual_paid_cents', v_residual,
    'balanced', v_paid = v_pool,
    'variance_cents', v_paid - v_pool);
END;
$$;


ALTER FUNCTION public.fn_mystery_bounty_settle_unguarded_20260907(p_tournament_id uuid, p_winner_user_id uuid) OWNER TO postgres;

--
-- Name: fn_mystery_bounty_table_state(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mystery_bounty_table_state(p_table_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'table_id', p_table_id,
    'open', COALESCE((
      SELECT jsonb_agg(row_to_json(r) ORDER BY r.reserved_at)
        FROM (
          SELECT a.id            AS award_id,
                 a.status,
                 a.tournament_id,
                 a.reserved_at,
                 a.reveal_deadline_at,
                 CASE WHEN a.status = 'reserved' THEN NULL ELSE a.amount_cents END AS amount_cents,
                 CASE WHEN a.status = 'reserved' THEN NULL ELSE a.tier END          AS tier,
                 CASE WHEN a.status = 'reserved' THEN NULL ELSE a.tier = 'jackpot' END AS is_jackpot,
                 jsonb_build_object(
                   'user_id', a.eliminated_user_id,
                   'username', COALESCE(tp.username, 'Player')) AS eliminated,
                 (SELECT rc.user_id
                    FROM public.tournament_bounty_award_recipients rc
                   WHERE rc.award_id = a.id AND rc.is_designated_revealer
                   LIMIT 1) AS designated_revealer,
                 (SELECT COALESCE(tp2.username, 'Player')
                    FROM public.tournament_bounty_award_recipients rc
                    LEFT JOIN public.tournament_players tp2
                      ON tp2.tournament_id = a.tournament_id AND tp2.user_id = rc.user_id
                   WHERE rc.award_id = a.id AND rc.is_designated_revealer
                   LIMIT 1) AS designated_revealer_name,
                 COALESCE((
                   SELECT jsonb_agg(jsonb_build_object(
                            'user_id', rc.user_id,
                            'username', COALESCE(tp3.username, 'Player'),
                            'amount_cents',
                              CASE WHEN a.status = 'reserved' THEN NULL ELSE rc.amount_cents END)
                          ORDER BY rc.amount_cents DESC, rc.user_id)
                     FROM public.tournament_bounty_award_recipients rc
                     LEFT JOIN public.tournament_players tp3
                       ON tp3.tournament_id = a.tournament_id AND tp3.user_id = rc.user_id
                    WHERE rc.award_id = a.id), '[]'::jsonb) AS recipients
            FROM public.tournament_bounty_awards a
            LEFT JOIN public.tournament_players tp
              ON tp.tournament_id = a.tournament_id AND tp.user_id = a.eliminated_user_id
           WHERE a.table_id = p_table_id
             AND a.status IN ('reserved', 'revealed')
           ORDER BY a.reserved_at
           LIMIT 20
        ) r
    ), '[]'::jsonb));
$$;


ALTER FUNCTION public.fn_mystery_bounty_table_state(p_table_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_mystery_bounty_table_state(p_table_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_mystery_bounty_table_state(p_table_id uuid) IS 'Dan section 57 - the mystery bounty awards still open at one table, for a client that reconnected mid-reveal. Withholds amount_cents while the award is still reserved (section 19).';


