--
-- Name: fn_next_invoice_number(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_next_invoice_number(p_union_id uuid, p_at timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_year   int := EXTRACT(year FROM (p_at AT TIME ZONE 'America/Los_Angeles'))::int;
  v_seq    bigint;
  v_prefix text;
BEGIN
  SELECT upper(left(regexp_replace(COALESCE(u.slug, u.name, 'union'), '[^a-zA-Z0-9]', '', 'g'), 6))
    INTO v_prefix
    FROM unions u WHERE u.id = p_union_id;
  IF v_prefix IS NULL OR v_prefix = '' THEN
    RAISE EXCEPTION 'cannot derive an invoice prefix for union %', p_union_id;
  END IF;

  LOOP
    UPDATE union_invoice_counters
       SET next_seq = next_seq + 1, updated_at = now()
     WHERE union_id = p_union_id AND year = v_year
     RETURNING next_seq - 1 INTO v_seq;
    EXIT WHEN FOUND;

    BEGIN
      INSERT INTO union_invoice_counters (union_id, year, next_seq)
      VALUES (p_union_id, v_year, 2);
      v_seq := 1;
      EXIT;
    EXCEPTION WHEN unique_violation THEN
      -- Another session created the row first; go round and take the update path.
    END;
  END LOOP;

  RETURN v_prefix || '-' || v_year::text || '-' || lpad(v_seq::text, 6, '0');
END $$;


ALTER FUNCTION public.fn_next_invoice_number(p_union_id uuid, p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_next_player_number(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_next_player_number() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_candidate bigint;
  v_tries     int := 0;
BEGIN
  LOOP
    v_candidate := nextval('public.player_number_seq');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.profiles WHERE player_number = v_candidate::text
    );
    v_tries := v_tries + 1;
    IF v_tries > 1000 THEN
      RAISE EXCEPTION 'fn_next_player_number: no free player number after 1000 attempts';
    END IF;
  END LOOP;
  RETURN v_candidate::text;
END;
$$;


ALTER FUNCTION public.fn_next_player_number() OWNER TO postgres;

