--
-- Name: FUNCTION fn_notify_achievement_unlocked(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_notify_achievement_unlocked() IS 'Raises the achievement-unlock notification server-side, on the NULL -> non-NULL transition of unlocked_at. Replaces the browser call to the retired pushNotificationService (issue #1498, ninth flow, missed because the call was split across lines). Carries no _push key, so the mirror trigger enqueues it and push-dispatch applies the consent gate. Never fails the write that earned the achievement. Added 2026-08-30.';


--
-- Name: fn_notify_agent_on_cashout(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_agent_on_cashout() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_player_name TEXT;
    v_club_name TEXT;
BEGIN
    -- Get player name
    SELECT display_name INTO v_player_name
    FROM profiles
    WHERE id = NEW.player_id;

    -- Get club name
    SELECT name INTO v_club_name
    FROM clubs
    WHERE id = NEW.club_id;

    -- Create notification for agent
    INSERT INTO notifications (user_id, type, title, message, data, created_at)
    VALUES (
        NEW.agent_id,
        'cashout_request',
        'Cashout Request',
        v_player_name || ' requested a cashout of ' || NEW.amount || ' chips in ' || v_club_name,
        jsonb_build_object(
            'cashout_id', NEW.id,
            'player_id', NEW.player_id,
            'club_id', NEW.club_id,
            'amount', NEW.amount
        ),
        NOW()
    );

    -- Create a club message notification for agent
    INSERT INTO messages (
        conversation_id,
        sender_id,
        receiver_id,
        content,
        is_read,
        created_at
    )
    SELECT 
        c.id,
        NEW.player_id,
        NEW.agent_id,
        'Cashout Request: ' || NEW.amount || ' Chips. Please Review In Your Agent Dashboard.',
        FALSE,
        NOW()
    FROM conversations c
    WHERE c.participant_ids @> ARRAY[NEW.player_id, NEW.agent_id]
      AND c.club_id = NEW.club_id
      AND c.category = 'club'
    LIMIT 1;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_notify_agent_on_cashout() OWNER TO postgres;

--
-- Name: fn_notify_blinding_off(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_blinding_off() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_name text;
  v_stack text := '';
BEGIN
  BEGIN
    -- Only the moment they GO away, never the moment they come back, and never
    -- a repeat while they stay away.
    IF NOT (COALESCE(NEW.is_sitting_out, false) OR COALESCE(NEW.is_away, false)) THEN
      RETURN NEW;
    END IF;
    IF (COALESCE(OLD.is_sitting_out, false) OR COALESCE(OLD.is_away, false)) THEN
      RETURN NEW;
    END IF;
    -- A seat they have already left is not blinding off.
    IF NEW.left_at IS NOT NULL OR NEW.user_id IS NULL THEN
      RETURN NEW;
    END IF;

    -- Tournaments only. A cash seat that sits out simply stops being dealt in;
    -- it is not paying blinds to be absent, so there is nothing urgent to say.
    SELECT t.tournament_id INTO v_tournament_id FROM public.tables t WHERE t.id = NEW.table_id;
    IF v_tournament_id IS NULL THEN
      RETURN NEW;
    END IF;

    SELECT COALESCE(NULLIF(btrim(tn.name), ''), 'Your Tournament')
      INTO v_name FROM public.tournaments tn WHERE tn.id = v_tournament_id;
    v_name := COALESCE(v_name, 'Your Tournament');

    IF COALESCE(NEW.stack, 0) > 0 THEN
      v_stack := ' You have ' || to_char(round(NEW.stack), 'FM999,999,999,990') || ' chips left.';
    END IF;

    -- Copy carried over verbatim from notifyBlindingOff() so the intent that
    -- was already written and reviewed is preserved exactly.
    PERFORM public.fn_raise_notification(
      NEW.user_id,
      'tournament_blinding_off',
      'You Are Being Blinded Off',
      'Your seat in ' || v_name || ' is posting blinds without you.' || v_stack || ' Tap to take your seat.',
      '/table/' || NEW.table_id::text,
      jsonb_build_object('tableId', NEW.table_id, 'tournamentId', v_tournament_id, 'action', 'blinding_off')
    );
  EXCEPTION WHEN OTHERS THEN
    -- Never let a notification interfere with the engine writing a seat.
    RAISE WARNING 'fn_notify_blinding_off failed for seat %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END; $$;


ALTER FUNCTION public.fn_notify_blinding_off() OWNER TO postgres;

--
-- Name: fn_notify_credit_request(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_credit_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  BEGIN
    IF TG_OP = 'INSERT' THEN
      PERFORM public.fn_raise_notification(
        NEW.approver_id, 'credit_request', 'Credit Request',
        public.fn_notify_display_name(NEW.requester_id)
          || ' requested ' || to_char(COALESCE(NEW.requested_amount, 0), 'FM999,999,999,990') || ' chips credit',
        '/agent/credit-requests',
        jsonb_build_object('creditRequestId', NEW.id, 'clubId', NEW.club_id));
    ELSIF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
      IF NEW.status = 'approved' THEN
        PERFORM public.fn_raise_notification(
          NEW.requester_id, 'credit_approved', 'Credit Line Increased',
          'Your credit line was raised to '
            || to_char(COALESCE(NEW.approved_amount, NEW.requested_amount, 0), 'FM999,999,999,990') || ' chips',
          '/wallet', jsonb_build_object('creditRequestId', NEW.id));
      ELSIF NEW.status = 'denied' THEN
        PERFORM public.fn_raise_notification(
          NEW.requester_id, 'credit_denied', 'Credit Request Denied',
          COALESCE(NULLIF(btrim(NEW.reviewer_notes), ''), 'Your credit request was not approved'),
          '/wallet', jsonb_build_object('creditRequestId', NEW.id));
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_notify_credit_request failed for request %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END; $$;


