--
-- Name: fn_notify_friend_request(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_friend_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    sender_name TEXT;
BEGIN
    -- Skip if suppressed by auto-connect trigger
    IF current_setting('app.suppress_friend_notifications', true) = 'true' THEN
        RETURN NEW;
    END IF;

    IF NEW.status = 'pending' THEN
        SELECT COALESCE(full_name, username, 'Someone') INTO sender_name
        FROM public.profiles WHERE id = NEW.user_id;
        
        INSERT INTO public.notifications (user_id, actor_id, type, title, message, data)
        VALUES (
            NEW.friend_id,
            NEW.user_id,
            'friend_request',
            sender_name,
            'sent you a friend request',
            jsonb_build_object(
                'sender_id', NEW.user_id,
                'friendship_id', NEW.id,
                'sender_name', sender_name
            )
        );
    ELSIF NEW.status = 'accepted' THEN
        SELECT COALESCE(full_name, username, 'Someone') INTO sender_name
        FROM public.profiles WHERE id = NEW.user_id;
        
        INSERT INTO public.notifications (user_id, actor_id, type, title, message, data)
        VALUES (
            NEW.friend_id,
            NEW.user_id,
            'friend_accept',
            sender_name,
            'accepted your friend request',
            jsonb_build_object(
                'sender_id', NEW.user_id,
                'friendship_id', NEW.id,
                'sender_name', sender_name
            )
        );
    END IF;
    
    RETURN NEW;
END;
$$;


