--
-- Name: fn_notify_friends_of_home_join(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_friends_of_home_join() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group RECORD; v_slug text; v_joiner_name text; v_friend RECORD;
BEGIN
    IF TG_OP = 'INSERT' AND NEW.status <> 'approved' THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND (OLD.status = 'approved' OR NEW.status <> 'approved') THEN RETURN NEW; END IF;

    BEGIN
        SELECT * INTO v_group FROM commander_home_groups WHERE id = NEW.group_id;
        IF v_group IS NULL OR v_group.is_private THEN RETURN NEW; END IF;

        SELECT sp.slug INTO v_slug FROM social_pages sp
         WHERE sp.linked_entity_type='home_group' AND sp.linked_entity_id=v_group.id::text LIMIT 1;
        SELECT COALESCE(display_name, full_name, username, 'A friend') INTO v_joiner_name
          FROM profiles WHERE id = NEW.user_id;

        FOR v_friend IN
            SELECT DISTINCT CASE WHEN f.user_id = NEW.user_id THEN f.friend_id ELSE f.user_id END AS friend_user_id
              FROM friendships f
             WHERE (f.user_id = NEW.user_id OR f.friend_id = NEW.user_id)
               AND f.status = 'accepted'
        LOOP
            IF v_friend.friend_user_id = NEW.user_id THEN CONTINUE; END IF;
            IF EXISTS (SELECT 1 FROM commander_home_members
                        WHERE group_id = NEW.group_id AND user_id = v_friend.friend_user_id) THEN
                CONTINUE;
            END IF;

            PERFORM public.fn_emit_home_notification(
                v_friend.friend_user_id, 'home_group_friend_joined',
                v_joiner_name || ' joined ' || v_group.name,
                'Your friend is now in ' || v_group.name || ' - check it out',
                '/hub/home-games/' || COALESCE(v_slug, v_group.id::text),
                jsonb_build_object('group_id', v_group.id, 'friend_id', NEW.user_id),
                'friend_activity'
            );
        END LOOP;
    EXCEPTION WHEN OTHERS THEN
        -- Notification side-effects must NEVER block member-add. Log and continue.
        RAISE WARNING 'fn_notify_friends_of_home_join failed for group=% user=%: % (%)',
            NEW.group_id, NEW.user_id, SQLERRM, SQLSTATE;
    END;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_notify_friends_of_home_join() OWNER TO postgres;

--
-- Name: fn_notify_guarantee_bank_short(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_guarantee_bank_short(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_union uuid; v_club_name text; v_union_name text;
  v_bank numeric; v_bank_label text; v_exposure numeric;
  v_recipients uuid[]; v_uid uuid; v_inserted integer := 0;
  v_title text; v_message text;
begin
  select c.union_id, c.name into v_union, v_club_name
    from public.clubs c where c.id = p_club_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'club_not_found');
  end if;

  if v_union is not null then
    select coalesce(uw.chip_balance, 0), u.name
      into v_bank, v_union_name
      from public.unions u
      left join public.union_wallets uw on uw.union_id = u.id
     where u.id = v_union;
    v_bank_label := 'union bank';

    select coalesce(sum(greatest(coalesce(t.guaranteed_prize,0) - coalesce(t.prize_pool,0), 0)), 0)
      into v_exposure
      from public.tournaments t join public.clubs c2 on c2.id = t.club_id
     where c2.union_id = v_union
       and coalesce(t.guaranteed_prize,0) > 0
       and coalesce(t.prize_pool_finalized,false) = false
       and t.status in ('ANNOUNCED','REGISTERING','RUNNING');

    select array_agg(distinct uid) into v_recipients from (
      select u.owner_id as uid from public.unions u where u.id = v_union and u.owner_id is not null
      union
      select c.owner_id from public.clubs c where c.id = p_club_id and c.owner_id is not null
    ) o;
  else
    select coalesce(c.chip_treasury, 0) into v_bank
      from public.clubs c where c.id = p_club_id;
    v_bank_label := 'club bank';

    select coalesce(sum(greatest(coalesce(t.guaranteed_prize,0) - coalesce(t.prize_pool,0), 0)), 0)
      into v_exposure
      from public.tournaments t
     where t.club_id = p_club_id
       and coalesce(t.guaranteed_prize,0) > 0
       and coalesce(t.prize_pool_finalized,false) = false
       and t.status in ('ANNOUNCED','REGISTERING','RUNNING');

    select array_agg(c.owner_id) into v_recipients
      from public.clubs c where c.id = p_club_id and c.owner_id is not null;
  end if;

  v_title := 'More Chips Needed To Cover Guarantees';
  v_message := 'The ' || v_bank_label || ' for '
            || coalesce(case when v_union is not null then v_union_name end, v_club_name, 'your club')
            || ' holds ' || round(v_bank, 2)
            || ' chips against ' || round(v_exposure, 2)
            || ' promised in live guarantees. New guaranteed tournaments cannot start until more chips are added to the bank.';

  foreach v_uid in array coalesce(v_recipients, '{}'::uuid[]) loop
    if not exists (
      select 1 from public.notifications n
       where n.user_id = v_uid
         and n.type = 'guarantee_bank_short'
         and coalesce(n.is_read, false) = false
         and n.data->>'bank_entity_id' = coalesce(v_union, p_club_id)::text
    ) then
      insert into public.notifications (user_id, type, title, message, data, is_read)
      values (v_uid, 'guarantee_bank_short', v_title, v_message,
              jsonb_build_object(
                'bank_type', case when v_union is not null then 'union' else 'club' end,
                'bank_entity_id', coalesce(v_union, p_club_id),
                'club_id', p_club_id, 'union_id', v_union,
                'bank_balance', v_bank, 'live_exposure', v_exposure,
                'short_by', round(greatest(v_exposure - v_bank, 0), 2)),
              false);
      v_inserted := v_inserted + 1;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'notified', v_inserted,
    'bank', v_bank, 'exposure', v_exposure,
    'recipients', coalesce(array_length(v_recipients, 1), 0));
end;
$$;


ALTER FUNCTION public.fn_notify_guarantee_bank_short(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_notify_guarantee_bank_short(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_notify_guarantee_bank_short(p_club_id uuid) IS 'Write the durable owner-facing "More Chips Needed To Cover Guarantees" notification for a club whose funding bank cannot cover its promises. Called by the app AFTER catching the guard''s 55000 refusal (a raising trigger rolls back its own writes). Notifies club owner + union owner; deduped on unread per recipient per bank.';


--
-- Name: fn_notify_home_game_cancelled(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_home_game_cancelled() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group RECORD;
    v_slug  text;
    v_rsvper RECORD;
BEGIN
    -- Only on status change TO cancelled
    IF OLD.status = 'cancelled' OR NEW.status <> 'cancelled' THEN RETURN NEW; END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = NEW.group_id;
    SELECT sp.slug INTO v_slug FROM social_pages sp 
     WHERE sp.linked_entity_type = 'home_group' AND sp.linked_entity_id = v_group.id::text LIMIT 1;

    FOR v_rsvper IN 
        SELECT DISTINCT user_id FROM commander_home_rsvps 
         WHERE game_id = NEW.id 
           AND response IN ('yes','maybe','waitlist')
    LOOP
        PERFORM public.fn_emit_home_notification(
            v_rsvper.user_id, 'home_game_cancelled',
            'Game cancelled: ' || COALESCE(NEW.title, v_group.name),
            COALESCE(NEW.title, 'The game') || ' on ' || NEW.scheduled_date::text || 
                ' has been cancelled' || 
                CASE WHEN NEW.cancellation_reason IS NOT NULL 
                     THEN ' - ' || NEW.cancellation_reason ELSE '' END,
            '/hub/home-games/' || COALESCE(v_slug, v_group.id::text),
            jsonb_build_object(
                'game_id', NEW.id, 'group_id', v_group.id,
                'reason', NEW.cancellation_reason
            ),
            'home_game_cancellations'
        );
    END LOOP;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_notify_home_game_cancelled() OWNER TO postgres;

--
-- Name: fn_notify_home_game_created(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_home_game_created() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group RECORD; v_recipient RECORD; v_slug text;
BEGIN
    SELECT * INTO v_group FROM commander_home_groups WHERE id = NEW.group_id;
    SELECT sp.slug INTO v_slug FROM social_pages sp
     WHERE sp.linked_entity_type='home_group' AND sp.linked_entity_id = NEW.group_id::text LIMIT 1;

    -- Notify approved members (respecting preference)
    FOR v_recipient IN
        SELECT m.user_id
          FROM commander_home_members m
         WHERE m.group_id = NEW.group_id
           AND m.status = 'approved'
           AND m.user_id <> NEW.host_id
           AND COALESCE(m.notify_new_games, true) = true
    LOOP
        PERFORM public.fn_emit_home_notification(
            v_recipient.user_id, 'home_game_new',
            'New game scheduled in ' || v_group.name,
            COALESCE(NEW.title, 'Home game') || ' on ' || to_char(NEW.scheduled_date, 'Dy Mon DD'),
            '/hub/home-games/' || COALESCE(v_slug, NEW.group_id::text) || '/games/' || NEW.id::text,
            jsonb_build_object('game_id', NEW.id, 'group_id', NEW.group_id),
            'home_game_new_game_posted'   -- was 'home_game_notify_new_games' (nonexistent)
        );
    END LOOP;

    -- Notify followers (non-members who opted in)
    FOR v_recipient IN
        SELECT f.user_id
          FROM commander_home_group_follows f
         WHERE f.group_id = NEW.group_id
           AND f.notify_new_games = true
           AND f.user_id <> NEW.host_id
           AND NOT EXISTS (SELECT 1 FROM commander_home_members m
                            WHERE m.group_id = NEW.group_id AND m.user_id = f.user_id)
    LOOP
        PERFORM public.fn_emit_home_notification(
            v_recipient.user_id, 'home_game_new_followed',
            v_group.name || ' has a new game',
            COALESCE(NEW.title, 'Home game') || ' on ' || to_char(NEW.scheduled_date, 'Dy Mon DD'),
            '/hub/home-games/' || COALESCE(v_slug, NEW.group_id::text) || '/games/' || NEW.id::text,
            jsonb_build_object('game_id', NEW.id, 'group_id', NEW.group_id, 'via', 'follow'),
            NULL  -- follower opt-in is in commander_home_group_follows.notify_new_games
        );
    END LOOP;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_notify_home_game_created() OWNER TO postgres;

--
-- Name: fn_notify_home_member_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_home_member_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group RECORD;
    v_slug  text;
    v_member_name text;
BEGIN
    SELECT * INTO v_group FROM commander_home_groups WHERE id = COALESCE(NEW.group_id, OLD.group_id);
    SELECT sp.slug INTO v_slug FROM social_pages sp 
     WHERE sp.linked_entity_type = 'home_group' AND sp.linked_entity_id = v_group.id::text LIMIT 1;
    SELECT COALESCE(display_name, full_name, username, 'New member') INTO v_member_name
      FROM profiles WHERE id = COALESCE(NEW.user_id, OLD.user_id);

    -- NEW pending request - notify host + admins
    IF TG_OP = 'INSERT' AND NEW.status = 'pending' THEN
        PERFORM public.fn_emit_home_notification(
            v_group.owner_id, 'home_group_pending_request',
            v_member_name || ' wants to join',
            v_member_name || ' requested to join ' || v_group.name,
            '/hub/home-games/' || COALESCE(v_slug, v_group.id::text) || '/host',
            jsonb_build_object('group_id', v_group.id, 'user_id', NEW.user_id),
            'home_game_host_requests'
        );

    -- Status changed to approved - notify member
    ELSIF TG_OP = 'UPDATE' AND OLD.status <> 'approved' AND NEW.status = 'approved' THEN
        PERFORM public.fn_emit_home_notification(
            NEW.user_id, 'home_group_approved',
            'Welcome to ' || v_group.name,
            'You''re now a member of ' || v_group.name,
            '/hub/home-games/' || COALESCE(v_slug, v_group.id::text),
            jsonb_build_object('group_id', v_group.id),
            NULL  -- always notify on approval
        );

    -- Status changed to declined - notify member
    ELSIF TG_OP = 'UPDATE' AND OLD.status = 'pending' AND NEW.status = 'declined' THEN
        PERFORM public.fn_emit_home_notification(
            NEW.user_id, 'home_group_declined',
            'Request update',
            'Your request to join ' || v_group.name || ' was not approved',
            '/hub/home-games',
            jsonb_build_object('group_id', v_group.id),
            NULL
        );

    -- Status changed to banned - notify member
    ELSIF TG_OP = 'UPDATE' AND OLD.status <> 'banned' AND NEW.status = 'banned' THEN
        PERFORM public.fn_emit_home_notification(
            NEW.user_id, 'home_group_banned',
            'Removed from ' || v_group.name,
            'You''ve been removed from ' || v_group.name,
            '/hub/home-games',
            jsonb_build_object('group_id', v_group.id),
            NULL
        );

    -- Promoted to admin
    ELSIF TG_OP = 'UPDATE' AND OLD.role = 'member' AND NEW.role = 'admin' THEN
        PERFORM public.fn_emit_home_notification(
            NEW.user_id, 'home_group_promoted',
            'You''re now an admin of ' || v_group.name,
            'You now have admin privileges in ' || v_group.name,
            '/hub/home-games/' || COALESCE(v_slug, v_group.id::text) || '/host',
            jsonb_build_object('group_id', v_group.id, 'new_role', 'admin'),
            NULL
        );
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.fn_notify_home_member_status() OWNER TO postgres;

--
-- Name: fn_notify_home_post_comment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_home_post_comment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_post RECORD; v_commenter_name text; v_group RECORD; v_slug text;
BEGIN
    SELECT * INTO v_post FROM commander_home_posts WHERE id = NEW.post_id;
    IF v_post.author_id = NEW.author_id THEN RETURN NEW; END IF;
    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_post.group_id;
    SELECT sp.slug INTO v_slug FROM social_pages sp
     WHERE sp.linked_entity_type = 'home_group' AND sp.linked_entity_id = v_group.id::text LIMIT 1;
    SELECT COALESCE(display_name, full_name, username, 'Someone') INTO v_commenter_name
      FROM profiles WHERE id = NEW.author_id;

    PERFORM public.fn_emit_home_notification(
        v_post.author_id, 'home_post_comment',
        v_commenter_name || ' commented on your post',
        LEFT(NEW.content, 140),
        '/hub/home-games/' || COALESCE(v_slug, v_group.id::text),
        jsonb_build_object('post_id', v_post.id, 'comment_id', NEW.id, 'commenter_id', NEW.author_id),
        'home_game_post_comments'       -- ★ NEW: respect mute pref
    );
    RETURN NEW;
END;
$$;


