--
-- Name: fn_offer_open_seat(uuid, interval, interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_offer_open_seat(p_table_id uuid, p_offer_ttl interval DEFAULT '00:01:00'::interval, p_entry_ttl interval DEFAULT '24:00:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tbl      record;
  v_next     record;
  v_notif_id uuid;
  v_expired  int := 0;
  v_holds    int := 0;
  v_cap      int := 1;
BEGIN
  SELECT COALESCE(max_concurrent_holds, 1) INTO v_cap FROM public.waitlist_policy WHERE id;
  IF v_cap IS NULL THEN v_cap := 1; END IF;

  SELECT t.id, t.name, t.tournament_id, t.max_players, t.current_players
    INTO v_tbl
    FROM public.tables t
   WHERE t.id = p_table_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;

  IF v_tbl.tournament_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_table');
  END IF;

  IF COALESCE(v_tbl.current_players, 0) >= COALESCE(v_tbl.max_players, 9) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_full');
  END IF;

  WITH dead AS (
    UPDATE public.table_waitlist
       SET status = 'expired'
     WHERE table_id = p_table_id
       AND status = 'notified'
       AND COALESCE(hold_expires_at, notified_at + p_offer_ttl) < now()
    RETURNING user_id
  )
  INSERT INTO public.notifications (user_id, type, title, message, data)
  SELECT d.user_id,
         'waitlist_offer_expired',
         'Seat Offer Expired',
         'Your Seat At ' || COALESCE(v_tbl.name, 'The Table') ||
           ' Went To The Next Player In Line. Join The Waitlist Again To Get Back In.',
         jsonb_build_object('table_id', p_table_id, '_push', 'skip')
    FROM dead d;
  GET DIAGNOSTICS v_expired = ROW_COUNT;

  UPDATE public.table_waitlist
     SET status = 'expired'
   WHERE table_id = p_table_id
     AND status = 'waiting'
     AND created_at < now() - p_entry_ttl;

  UPDATE public.table_waitlist w
     SET status = 'seated'
   WHERE w.table_id = p_table_id
     AND w.status = 'waiting'
     AND EXISTS (
       SELECT 1 FROM public.table_seats s
        WHERE s.table_id = p_table_id
          AND s.left_at IS NULL
          AND s.user_id = w.user_id
     );

  SELECT COUNT(*) INTO v_holds
    FROM public.table_waitlist
   WHERE table_id = p_table_id
     AND status = 'notified'
     AND COALESCE(hold_expires_at, notified_at + p_offer_ttl) > now();

  IF COALESCE(v_tbl.current_players, 0) + v_holds >= COALESCE(v_tbl.max_players, 9) THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'open_seats_already_held', 'offers_expired', v_expired
    );
  END IF;

  -- THE HEAD OF THE QUEUE, LOCKED, AND NOT ALREADY HOLDING A SEAT ELSEWHERE.
  -- A hold is exclusive, so handing one player several at once takes seats
  -- away from everybody behind them. Skipping a capped player leaves their
  -- place in line untouched: they are passed over for THIS seat only.
  --
  -- 2026-08-31 (Dan, binding: horses are never skipped): the is_horse
  -- exclusion that used to sit in this predicate is GONE. Whoever is first in
  -- line is offered the seat. The JOIN to profiles stays: it is no longer read
  -- to exclude anyone, but dropping it would newly qualify waitlist rows whose
  -- user has no profile row at all.
  SELECT w.id, w.user_id, COALESCE(p.is_horse, false) AS is_horse
    INTO v_next
    FROM public.table_waitlist w
    JOIN public.profiles p ON p.id = w.user_id
   WHERE w.table_id = p_table_id
     AND w.status = 'waiting'
     AND (
       v_cap = 0
       OR (
         SELECT count(*) FROM public.table_waitlist h
          WHERE h.user_id = w.user_id
            AND h.status = 'notified'
            AND COALESCE(h.hold_expires_at, h.notified_at + p_offer_ttl) > now()
       ) < v_cap
     )
   ORDER BY w.created_at
     FOR UPDATE OF w SKIP LOCKED
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'nobody_waiting', 'offers_expired', v_expired
    );
  END IF;

  UPDATE public.table_waitlist
     SET status = 'notified',
         notified_at = now(),
         hold_expires_at = now() + p_offer_ttl
   WHERE id = v_next.id;

  -- The notification row is written for every player alike, so the queue's
  -- audit trail is identical. Only the PUSH flag differs: a horse has no
  -- device to push to, which is the sanctioned identification-for-display use,
  -- and it reuses the `_push:skip` marker the expiry notification above
  -- already uses. It decides how a message is delivered, never whether a seat
  -- is offered.
  INSERT INTO public.notifications (user_id, type, title, message, data)
  VALUES (
    v_next.user_id,
    'waitlist_seat_open',
    'Seat Open',
    'A Seat Just Opened At ' || COALESCE(v_tbl.name, 'Your Waitlisted Table') ||
      '. It Is Held For You For 60 Seconds. Sit Down Now To Claim It.',
    CASE WHEN v_next.is_horse
         THEN jsonb_build_object('table_id', p_table_id, '_push', 'skip')
         ELSE jsonb_build_object('table_id', p_table_id)
    END
  )
  RETURNING id INTO v_notif_id;

  RETURN jsonb_build_object(
    'ok', true,
    'user_id', v_next.user_id,
    'table_name', v_tbl.name,
    'notification_id', v_notif_id,
    'hold_expires_in_seconds', EXTRACT(epoch FROM p_offer_ttl)::int,
    'offers_expired', v_expired
  );
END
$$;


ALTER FUNCTION public.fn_offer_open_seat(p_table_id uuid, p_offer_ttl interval, p_entry_ttl interval) OWNER TO postgres;

--
-- Name: FUNCTION fn_offer_open_seat(p_table_id uuid, p_offer_ttl interval, p_entry_ttl interval); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_offer_open_seat(p_table_id uuid, p_offer_ttl interval, p_entry_ttl interval) IS 'Offers an open cash seat to the longest-waiting HUMAN on the table waitlist. Since 2026-08-31 the offer is a 60-second EXCLUSIVE hold (hold_expires_at): atomic_table_buyin refuses everyone else the reserved seat, and no more holds are issued than there are open seats.';


--
-- Name: fn_on_table_status_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_on_table_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_terminal_now  boolean;
    v_terminal_before boolean;
    v_tournament_live boolean := false;
    v_seats int;
BEGIN
    v_terminal_now := lower(coalesce(NEW.status,'')) IN ('closed','completed','cancelled','finished');
    v_terminal_before := lower(coalesce(OLD.status,'')) IN ('closed','completed','cancelled','finished');

    IF NEW.tournament_id IS NOT NULL THEN
        SELECT upper(coalesce(t.status,'')) NOT IN ('COMPLETED','CANCELLED')
          INTO v_tournament_live
          FROM public.tournaments t
         WHERE t.id = NEW.tournament_id;
        v_tournament_live := coalesce(v_tournament_live, false);
    END IF;

    -- A close releases the table's seats, UNLESS its tournament is still live,
    -- in which case the close is somebody else's mistake and the field plays on.
    IF v_terminal_now AND NOT v_terminal_before AND NOT v_tournament_live THEN
        /* PAY BEFORE RELEASING (2026-08-30). This released the seats and kept
           the chips: 1,036 exits worth 432,100.90 chips in a single day, every
           one a cash table. The refund has to happen first - after left_at is
           set the seat is no longer active and the stack cannot be reached.
           No-ops for tournament tables. */
        PERFORM public.fn_cashout_seats_for_closing_table(
                  NEW.id, 'table ' || coalesce(NEW.status,'closed'));

        UPDATE public.table_seats
           SET left_at = coalesce(NEW.updated_at, now())
         WHERE table_id = NEW.id
           AND left_at IS NULL;
    END IF;

    -- LOUD, and now NAMED. Only when the close strands players who are still
    -- seated; ordinary consolidation of an empty table is not an incident.
    IF v_terminal_now AND NOT v_terminal_before AND v_tournament_live THEN
        SELECT count(*)::int INTO v_seats
          FROM public.table_seats s
         WHERE s.table_id = NEW.id AND s.left_at IS NULL;

        IF v_seats > 0 THEN
            BEGIN
                INSERT INTO public.engine_recovery_events (table_id, event, detail, hand_count)
                VALUES (
                    NEW.id,
                    'table_closed_under_live_tournament',
                    jsonb_build_object(
                        'tournament_id',    NEW.tournament_id,
                        'old_status',       OLD.status,
                        'new_status',       NEW.status,
                        'seats_protected',  v_seats,
                        'application_name', coalesce(nullif(current_setting('application_name', true), ''), '(unset)'),
                        'db_role',          current_user,
                        'session_role',     session_user,
                        'client_addr',      coalesce(host(inet_client_addr()), '(local)'),
                        'txid',             txid_current()::text
                    )::text,
                    v_seats
                );
            EXCEPTION WHEN OTHERS THEN
                -- The log is a courtesy. It must never block a write.
                NULL;
            END;
        END IF;
    END IF;

    IF v_terminal_now <> v_terminal_before AND NEW.club_id IS NOT NULL THEN
        PERFORM public.fn_refresh_club_activity_counts(NEW.club_id);
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_on_table_status_change() OWNER TO postgres;

--
-- Name: fn_open_settlement_period(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_open_settlement_period(p_club_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_caller uuid := (SELECT auth.uid());
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM clubs c WHERE c.id = p_club_id AND (
      c.owner_id = v_caller
      OR EXISTS (SELECT 1 FROM club_members cm WHERE cm.club_id = p_club_id
                 AND cm.user_id = v_caller AND cm.role IN ('owner','co_owner','admin'))))
  THEN RAISE EXCEPTION 'not authorized to manage this club''s settlement periods'; END IF;

  IF EXISTS (SELECT 1 FROM settlement_periods WHERE club_id = p_club_id AND status = 'open') THEN
    RAISE EXCEPTION 'an open settlement period already exists for this club';
  END IF;

  INSERT INTO settlement_periods
    (club_id, status, start_at, year, period_number, created_at, updated_at)
  VALUES
    (p_club_id, 'open', now(), EXTRACT(YEAR FROM now())::int,
     COALESCE((SELECT max(period_number) FROM settlement_periods WHERE club_id = p_club_id), 0) + 1,
     now(), now())
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION public.fn_open_settlement_period(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_open_tournament_rebuy_decisions(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_open_tournament_rebuy_decisions(p_tournament_id uuid, p_user_ids uuid[]) RETURNS TABLE(user_id uuid, rebuy_prompt_until timestamp with time zone, decision_open boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_rebuy_cap integer;
BEGIN
  IF p_tournament_id IS NULL OR p_user_ids IS NULL
     OR cardinality(p_user_ids)=0 OR cardinality(p_user_ids)>50
     OR EXISTS (SELECT 1 FROM unnest(p_user_ids) u WHERE u IS NULL) THEN
    RAISE EXCEPTION 'invalid rebuy-decision candidate set'
      USING ERRCODE='invalid_parameter_value';
  END IF;

  SELECT * INTO v_t
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament not found' USING ERRCODE='no_data_found';
  END IF;

  v_rebuy_cap := coalesce(nullif(v_t.rebuy_levels,0),nullif(v_t.late_reg_levels,0),0)
    + CASE WHEN coalesce(v_t.add_on_available,false)
           THEN coalesce(nullif(v_t.addon_levels,0),1) ELSE 0 END;

  RETURN QUERY
  WITH locked AS MATERIALIZED (
    SELECT tp.tournament_id,tp.user_id
      FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id
       AND tp.user_id=ANY(p_user_ids)
       AND tp.status='playing'
       AND coalesce(tp.chips,0)<=0
     ORDER BY tp.user_id
     FOR UPDATE
  ), opened AS (
    UPDATE public.tournament_players tp
       SET rebuy_prompt_until = CASE
         WHEN tp.rebuy_prompt_until IS NULL
          AND v_rebuy_cap>0
          AND coalesce(v_t.current_level,0)<v_rebuy_cap
          AND NOT coalesce(v_t.prize_pool_finalized,false)
          AND (
            (coalesce(v_t.is_rebuy,false)
              AND (v_t.max_rebuys IS NULL OR coalesce(tp.rebuys,0)<v_t.max_rebuys))
            OR
            (coalesce(v_t.is_reentry,false)
              AND (v_t.max_reentries IS NULL OR coalesce(tp.rebuys,0)<v_t.max_reentries))
          )
         THEN v_now+interval '30 seconds'
         ELSE tp.rebuy_prompt_until
       END
      FROM locked l
     WHERE tp.tournament_id=l.tournament_id AND tp.user_id=l.user_id
    RETURNING tp.user_id,tp.rebuy_prompt_until
  )
  SELECT o.user_id,o.rebuy_prompt_until,
         o.rebuy_prompt_until IS NOT NULL AND o.rebuy_prompt_until>v_now
    FROM opened o
   ORDER BY o.user_id;
END;
$$;


ALTER FUNCTION public.fn_open_tournament_rebuy_decisions(p_tournament_id uuid, p_user_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_overlay_at_risk(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_overlay_at_risk(p_union uuid DEFAULT NULL::uuid) RETURNS TABLE(tournament_id uuid, name text, club_id uuid, status text, start_time timestamp with time zone, buy_in numeric, guaranteed_prize numeric, entries_needed integer, current_players integer, shortfall integer, max_players integer, minutes_to_start numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select t.id, t.name, t.club_id, t.status, t.start_time,
         t.buy_in_amount, t.guaranteed_prize,
         ceil(t.guaranteed_prize / nullif(t.buy_in_amount, 0))::int,
         coalesce(t.current_players, 0),
         greatest(
           least(
             ceil(t.guaranteed_prize / nullif(t.buy_in_amount, 0))::int
               - coalesce(t.current_players, 0),
             coalesce(t.max_players, 0) - coalesce(t.current_players, 0)
           ), 0)::int,
         coalesce(t.max_players, 0),
         round(extract(epoch from (t.start_time - now())) / 60.0, 1)
  from tournaments t
  left join clubs c on c.id = t.club_id
  where t.guaranteed_prize > 0
    and t.buy_in_amount > 0
    and upper(t.status) in ('SCHEDULED', 'REGISTERING', 'ANNOUNCED', 'RUNNING')
    and t.start_time > now() - interval '30 minutes'
    and t.start_time < now() + interval '3 hours'
    and (p_union is null or c.union_id = p_union or c.id = p_union)
    and ceil(t.guaranteed_prize / nullif(t.buy_in_amount, 0))::int > coalesce(t.current_players, 0)
  order by t.start_time asc;
$$;


ALTER FUNCTION public.fn_overlay_at_risk(p_union uuid) OWNER TO postgres;

--
-- Name: fn_owner_start_tournament_now(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_owner_start_tournament_now(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_t    record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  SELECT id, club_id, status, start_time, current_players, min_players
    INTO v_t
    FROM tournaments
   WHERE id = p_tournament_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
  END IF;

  IF NOT public.fn_can_create_games(v_t.club_id, v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;

  IF v_t.status NOT IN ('REGISTERING', 'ANNOUNCED') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_startable',
                              'status', v_t.status);
  END IF;

  IF v_t.start_time IS NOT NULL AND v_t.start_time <= now() THEN
    RETURN jsonb_build_object('ok', true, 'already_due', true,
                              'start_time', v_t.start_time);
  END IF;

  UPDATE tournaments
     SET start_time = now()
   WHERE id = p_tournament_id;

  RETURN jsonb_build_object(
    'ok', true,
    'already_due', false,
    'start_time', now(),
    'current_players', COALESCE(v_t.current_players, 0),
    'min_players', COALESCE(v_t.min_players, 3)
  );
END;
$$;


ALTER FUNCTION public.fn_owner_start_tournament_now(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_parse_daily_mission_date(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_parse_daily_mission_date(p_value text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  v_date date;
BEGIN
  IF p_value IS NULL OR p_value !~ '^\d{4}-\d{2}-\d{2}$' THEN
    RETURN NULL;
  END IF;

  BEGIN
    v_date := p_value::date;
  EXCEPTION
    WHEN datetime_field_overflow OR invalid_datetime_format THEN
      RETURN NULL;
  END;

  IF to_char(v_date, 'YYYY-MM-DD') IS DISTINCT FROM p_value THEN
    RETURN NULL;
  END IF;

  RETURN v_date;
END;
$_$;


ALTER FUNCTION public.fn_parse_daily_mission_date(p_value text) OWNER TO postgres;

--
-- Name: FUNCTION fn_parse_daily_mission_date(p_value text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_parse_daily_mission_date(p_value text) IS 'Private canonical YYYY-MM-DD parser for legacy Daily Missions rows. It returns NULL instead of throwing on malformed historical values.';


--
-- Name: fn_pay_credit_invoice_from_wallet(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pay_credit_invoice_from_wallet(p_invoice_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_agent    uuid;
  v_agent_u  uuid;
  v_status   text;
  v_amount   numeric;
  v_apply    jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_pay_credit_invoice_from_wallet requires an authenticated caller'
      USING ERRCODE = '28000';
  END IF;

  v_amount := trunc(COALESCE(p_amount, 0) * 100) / 100;
  IF v_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'non_positive_amount');
  END IF;

  SELECT agent_id, status INTO v_agent, v_status
    FROM public.credit_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invoice_not_found');
  END IF;

  IF v_status = 'void' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invoice_voided');
  END IF;
  IF v_status = 'paid' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_settled');
  END IF;

  SELECT user_id INTO v_agent_u FROM public.agents WHERE id = v_agent;
  IF v_agent_u IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'agent_user_not_found');
  END IF;
  IF v_agent_u <> v_uid THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_your_wallet');
  END IF;

  IF NOT public.atomic_deduct_wallet_and_log(
       v_agent_u, v_amount, 'settlement',
       'Credit invoice payment: ' || p_invoice_id::text,
       NULL, NULL, p_invoice_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'insufficient_balance');
  END IF;

  v_apply := public.fn_apply_credit_payment(p_invoice_id, v_amount, 'wallet');

  IF v_apply IS NULL OR COALESCE((v_apply->>'success')::boolean, false) = false THEN
    RAISE EXCEPTION 'fn_pay_credit_invoice_from_wallet: apply failed for %: %',
      p_invoice_id, COALESCE(v_apply->>'error', 'unknown')
      USING ERRCODE = '25000';
  END IF;

  RETURN jsonb_build_object('ok', true, 'amount', v_amount, 'payment', v_apply->'payment');
END;
$$;


ALTER FUNCTION public.fn_pay_credit_invoice_from_wallet(p_invoice_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_pay_credit_invoice_from_wallet(p_invoice_id uuid, p_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_pay_credit_invoice_from_wallet(p_invoice_id uuid, p_amount numeric) IS 'AUDIT M17: deduct + apply in ONE transaction, so the compensating-credit rollback the client used to carry is unnecessary. Only the wallet owner may call it.';


--
-- Name: fn_pay_player_chips(uuid, numeric, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pay_player_chips(p_user_id uuid, p_amount numeric, p_category text, p_description text, p_club_hint uuid DEFAULT NULL::uuid, p_related_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_club uuid; v_balance numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('paid', false, 'reason', 'non_positive');
  END IF;

  v_club := public.fn_player_home_club(p_user_id, p_club_hint);

  IF v_club IS NULL THEN
    -- CLUB ARENA RULE: there is no shared wallet to fall back to.
    RAISE EXCEPTION 'no club wallet resolves for player % - Club Arena money cannot be paid to a global wallet', p_user_id
      USING HINT = 'Pass an explicit club, or ensure the player holds a club membership.';
  END IF;

  -- A club a player belongs to always has its own wallet; create if absent
  -- rather than redirecting the money anywhere else.
  PERFORM public.fn_ensure_club_wallet(p_user_id, v_club);

  UPDATE club_members
     SET chip_balance = COALESCE(chip_balance,0) + p_amount, updated_at = NOW()
   WHERE user_id = p_user_id AND club_id = v_club
   RETURNING chip_balance INTO v_balance;

  IF v_balance IS NULL THEN
    RAISE EXCEPTION 'club wallet for player % in club % could not be credited', p_user_id, v_club;
  END IF;

  INSERT INTO wallet_transactions
    (user_id, wallet_type, type, amount, category, description, related_entity_id, balance_after)
  VALUES
    (p_user_id, 'PLAYER', 'credit', p_amount, p_category,
     p_description || ' [club wallet]', p_related_id, v_balance);

  RETURN jsonb_build_object('paid', true, 'club_id', v_club,
                            'source', 'club_chips', 'balance_after', v_balance);
END $$;


ALTER FUNCTION public.fn_pay_player_chips(p_user_id uuid, p_amount numeric, p_category text, p_description text, p_club_hint uuid, p_related_id uuid) OWNER TO postgres;

--
-- Name: fn_payout_guarantee_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_payout_guarantee_check(p_since_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_days     integer := LEAST(GREATEST(COALESCE(p_since_days, 7), 1), 400);
  v_since    timestamptz;
  v_vacant   integer := 0;
  v_vac_chips numeric := 0;
  v_short    integer := 0;
  v_short_chips numeric := 0;
  v_gap      integer := 0;
  v_gap_chips numeric := 0;
  v_bounty   integer := 0;
  v_bounty_chips numeric := 0;
  v_alerts   integer := 0;
  v_cleared  integer := 0;
  v_labelled integer := 0;
  v_row      record;
BEGIN
  v_since := now() - make_interval(days => v_days);

  /* ── CLEAR WHAT IS NO LONGER TRUE (2026-09-07) ─────────────────────────────
     This check could raise an earner_not_paid alert and never close one. Two
     of the six open on 2026-09-07 had been paid IN FULL at 04:10, hours after
     the alert, and the row still read critical. An alarm that cannot clear is
     an alarm that gets skimmed, and the one real case in that list - a player
     4.80 short - had been sitting in it for a day.
     An alert clears when either half of its claim stops holding: the player
     has since been credited to within five cents of the place, or the event's
     prize pool has left the escrow to the last chip, in which case there is
     nothing left to pay them with and this is not the alert for it. */
  WITH open_alerts AS (
    SELECT fa.id,
           (fa.context->>'tournament_id')::uuid AS tid,
           (fa.context->>'user_id')::uuid       AS uid,
           (fa.context->>'place_worth')::numeric AS place_worth
      FROM public.financial_alerts fa
     WHERE fa.source = 'fn_payout_guarantee_check'
       AND fa.resolved IS NOT TRUE
       AND fa.context->>'kind' = 'earner_not_paid'
       AND fa.context ? 'tournament_id'
       AND fa.context ? 'user_id'
  ), judged AS (
    SELECT a.id,
           COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                      WHERE w.related_entity_id = a.tid AND w.user_id = a.uid
                        AND w.type = 'credit' AND w.category IN ('prize','bounty')), 0) AS credited,
           a.place_worth,
           COALESCE(t.prize_pool, 0) AS pool,
           COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                      WHERE w.related_entity_id = a.tid
                        AND w.type = 'credit' AND w.category = 'prize'), 0) AS pool_paid
      FROM open_alerts a
      LEFT JOIN public.tournaments t ON t.id = a.tid
  )
  UPDATE public.financial_alerts fa
     SET resolved = true,
         resolved_at = now(),
         resolution = CASE
           WHEN j.credited + 0.05 >= j.place_worth
             THEN format('Cleared by fn_payout_guarantee_check: the player has since been credited %s against a place worth %s.',
                         round(j.credited, 2), round(j.place_worth, 2))
           ELSE format('Cleared by fn_payout_guarantee_check: the event''s prize pool of %s has been distributed in full (%s paid), so there is nothing left to pay this place with. A place that received less than the flat structure share of a fully distributed pool is a labelling, deal or obligation question, not an unpaid player.',
                         round(j.pool, 2), round(j.pool_paid, 2))
         END
    FROM judged j
   WHERE fa.id = j.id
     AND (j.credited + 0.05 >= j.place_worth
          OR (j.pool > 0 AND j.pool_paid + 0.01 >= j.pool));
  GET DIAGNOSTICS v_cleared = ROW_COUNT;

  FOR v_row IN
    WITH ev AS (
      SELECT t.id, t.name, t.club_id, t.tournament_type, t.ended_at,
             COALESCE(t.prize_pool, 0) AS pool,
             (SELECT count(*) FROM public.tournament_players tp
               WHERE tp.tournament_id = t.id) AS entrants,
             t.payout_structure
        FROM public.tournaments t
       WHERE t.status = 'COMPLETED'
         AND t.ended_at >= v_since
         AND COALESCE(t.prize_pool, 0) > 0
         AND COALESCE(t.satellite_seats, 0) = 0
         AND COALESCE(t.variant, '') <> 'satellite'
    ), places AS (
      SELECT ev.*, (elem->>'place')::int AS place, (elem->>'percentage')::numeric AS pct
        FROM ev
        CROSS JOIN LATERAL jsonb_array_elements(
          CASE WHEN jsonb_typeof(ev.payout_structure::jsonb) = 'array'
               THEN ev.payout_structure::jsonb ELSE '[]'::jsonb END) elem
    )
    SELECT p.id, p.name, p.club_id, p.tournament_type, p.ended_at, p.pool, p.entrants,
           array_agg(p.place ORDER BY p.place) AS vacant_places,
           round(sum(p.pool * p.pct / 100), 2) AS chips
      FROM places p
     WHERE p.place <= p.entrants
       AND NOT EXISTS (SELECT 1 FROM public.tournament_players tp
                        WHERE tp.tournament_id = p.id AND tp.position = p.place)
     GROUP BY p.id, p.name, p.club_id, p.tournament_type, p.ended_at, p.pool, p.entrants
  LOOP
    v_vacant := v_vacant + 1;
    v_vac_chips := v_vac_chips + COALESCE(v_row.chips, 0);
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical', 'fn_payout_guarantee_check',
           format('%s ranked a %s-player field but left paid place(s) %s with nobody in them, so %s chips were paid to no one',
                  COALESCE(v_row.name, v_row.id::text), v_row.entrants,
                  array_to_string(v_row.vacant_places, ', '), v_row.chips),
           jsonb_build_object('kind','vacant_paid_place','tournament_id',v_row.id,
             'club_id',v_row.club_id,'tournament_type',v_row.tournament_type,
             'entrants',v_row.entrants,'prize_pool',v_row.pool,
             'vacant_places',to_jsonb(v_row.vacant_places),'chips',v_row.chips,
             'ended_at',v_row.ended_at,
             'detail','whoever finished in those places was mislabelled; no money was moved by this check')
     WHERE NOT EXISTS (SELECT 1 FROM public.financial_alerts fa
                        WHERE fa.source = 'fn_payout_guarantee_check'
                          AND fa.resolved IS NOT TRUE
                          AND fa.context->>'kind' = 'vacant_paid_place'
                          AND fa.context->>'tournament_id' = v_row.id::text);
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END LOOP;

  FOR v_row IN
    WITH ev AS (
      SELECT t.id, t.name, t.club_id, t.tournament_type, t.ended_at,
             COALESCE(t.prize_pool, 0) AS pool, t.payout_structure,
             /* WHAT LEFT THE ESCROW. The discriminator between "a player is
                short and the money is still here" and "the pool is gone and
                this place got less than the flat share". Only the first is an
                unpaid player. */
             COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                        WHERE w.related_entity_id = t.id
                          AND w.type = 'credit' AND w.category = 'prize'), 0) AS pool_paid
        FROM public.tournaments t
       WHERE t.status = 'COMPLETED'
         AND t.ended_at >= v_since
         AND COALESCE(t.prize_pool, 0) > 0
         AND COALESCE(t.satellite_seats, 0) = 0
         AND COALESCE(t.variant, '') <> 'satellite'
    ), owed AS (
      SELECT ev.id, ev.name, ev.club_id, ev.tournament_type, ev.ended_at,
             ev.pool, ev.pool_paid,
             tp.user_id, tp.position,
             round(ev.pool * (elem->>'percentage')::numeric / 100, 2) AS place_worth
        FROM ev
        CROSS JOIN LATERAL jsonb_array_elements(
          CASE WHEN jsonb_typeof(ev.payout_structure::jsonb) = 'array'
               THEN ev.payout_structure::jsonb ELSE '[]'::jsonb END) elem
        JOIN public.tournament_players tp
          ON tp.tournament_id = ev.id AND tp.position = (elem->>'place')::int
    )
    SELECT o.*,
           COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                      WHERE w.related_entity_id = o.id AND w.user_id = o.user_id
                        AND w.type = 'credit'
                        AND w.category IN ('prize','bounty')), 0) AS credited,
           (o.pool_paid + 0.01 >= o.pool) AS pool_distributed
      FROM owed o
     /* FIVE CENTS, NOT ONE (2026-09-01). place_worth here is the flat
        pool * percentage. The engine allocates in whole cents and gives the
        last paid place the remainder, so a place can legitimately land a cent
        or two either side of the flat figure. */
     WHERE COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                      WHERE w.related_entity_id = o.id AND w.user_id = o.user_id
                        AND w.type = 'credit'
                        AND w.category IN ('prize','bounty')), 0) + 0.05 < o.place_worth
  LOOP
    /* THE POOL TEST (2026-09-07). Five of the six alerts open when this was
       written named events whose pool had already left the escrow to the last
       chip - two paid in full hours after the alert, one settled by a
       final_table_deal that replaced the structure, two off by 0.07 and 0.06
       on pools of 14,850 and 1,350. Counted, not alarmed: nothing can be paid
       out of a pool that is gone, and the reconciler reading this as an unpaid
       player tried to top one of them up by 23.75 - a real double payment,
       stopped only by the empty escrow it would have come from. */
    IF v_row.pool_distributed THEN
      v_labelled := v_labelled + 1;
      CONTINUE;
    END IF;

    v_short := v_short + 1;
    v_short_chips := v_short_chips + (v_row.place_worth - v_row.credited);
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical', 'fn_payout_guarantee_check',
           format('%s: the player who finished %s is owed %s and their wallet received %s',
                  COALESCE(v_row.name, v_row.id::text), v_row.position,
                  v_row.place_worth, v_row.credited),
           jsonb_build_object('kind','earner_not_paid','tournament_id',v_row.id,
             'club_id',v_row.club_id,'tournament_type',v_row.tournament_type,
             'user_id',v_row.user_id,'position',v_row.position,
             'place_worth',v_row.place_worth,'credited',v_row.credited,
             'short',round(v_row.place_worth - v_row.credited, 2),
             'prize_pool',v_row.pool,'pool_paid',v_row.pool_paid,
             'ended_at',v_row.ended_at,
             'detail','the prize pool has NOT been fully distributed, so these chips are still in the escrow and this player can be paid. No money was moved by this check')
     WHERE NOT EXISTS (SELECT 1 FROM public.financial_alerts fa
                        WHERE fa.source = 'fn_payout_guarantee_check'
                          AND fa.resolved IS NOT TRUE
                          AND fa.context->>'kind' = 'earner_not_paid'
                          AND fa.context->>'tournament_id' = v_row.id::text
                          AND fa.context->>'user_id' = v_row.user_id::text);
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END LOOP;

  /* THE OTHER POOL (2026-09-01). Everything above reconciles the PRIZE pool,
     and a bounty event funds a SECOND pool out of the same buy-in. */
  FOR v_row IN
    SELECT t.id, t.name, t.club_id, t.ended_at,
           round(COALESCE(t.bounty_pool, 0), 2) AS pool,
           COALESCE((SELECT round(sum(w.amount), 2) FROM public.wallet_transactions w
                      WHERE w.related_entity_id = t.id AND w.type = 'credit'
                        AND w.category = 'bounty'), 0) AS paid
      FROM public.tournaments t
     WHERE t.status = 'COMPLETED'
       AND t.ended_at >= v_since
       AND COALESCE(t.bounty_pool, 0) > 0
  LOOP
    CONTINUE WHEN v_row.paid + 0.01 >= v_row.pool;
    v_bounty := v_bounty + 1;
    v_bounty_chips := v_bounty_chips + (v_row.pool - v_row.paid);
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical', 'fn_payout_guarantee_check',
           format('%s funded a %s bounty pool and paid out %s, so %s chips of it reached no player',
                  COALESCE(v_row.name, v_row.id::text), v_row.pool, v_row.paid,
                  round(v_row.pool - v_row.paid, 2)),
           jsonb_build_object('kind','bounty_pool_retained','tournament_id',v_row.id,
             'club_id',v_row.club_id,'bounty_pool',v_row.pool,'paid',v_row.paid,
             'retained',round(v_row.pool - v_row.paid, 2),'ended_at',v_row.ended_at,
             'detail','the residual settles to the champion; fn_backpay_unfinalised_bounty_pools re-drives it. No money was moved by this check')
     WHERE NOT EXISTS (SELECT 1 FROM public.financial_alerts fa
                        WHERE fa.source = 'fn_payout_guarantee_check'
                          AND fa.resolved IS NOT TRUE
                          AND fa.context->>'kind' = 'bounty_pool_retained'
                          AND fa.context->>'tournament_id' = v_row.id::text);
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END LOOP;

  SELECT count(*), COALESCE(round(sum(gap), 2), 0) INTO v_gap, v_gap_chips
    FROM (
      SELECT t.id,
             COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                        WHERE w.related_entity_id = t.id AND w.type='credit'
                          AND w.category='prize'), 0)
           - COALESCE((SELECT sum(p.amount) FROM public.tournament_payouts p
                        WHERE p.tournament_id = t.id
                          AND p.source NOT IN ('bounty','own_bounty','mystery_bounty_residual')), 0)
             AS gap
        FROM public.tournaments t
       WHERE t.status='COMPLETED' AND t.ended_at >= v_since
         AND COALESCE(t.prize_pool,0) > 0
    ) g
   WHERE g.gap > 0.01;

  IF v_gap > 0 THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'warning', 'fn_payout_guarantee_check',
           format('%s event(s) in the last %s days paid %s chips of prizes that were never written to tournament_payouts; the reconciler reads that record and will treat those chips as still owed',
                  v_gap, v_days, v_gap_chips),
           jsonb_build_object('kind','paid_but_unrecorded','events',v_gap,
             'chips',v_gap_chips,'since_days',v_days,
             'detail','no player is short; this is what arms a double-pay if the pool is ever funded')
     WHERE NOT EXISTS (SELECT 1 FROM public.financial_alerts fa
                        WHERE fa.source='fn_payout_guarantee_check'
                          AND fa.resolved IS NOT TRUE
                          AND fa.context->>'kind' = 'paid_but_unrecorded'
                          AND fa.created_at > now() - interval '20 hours');
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'since_days', v_days,
    'vacant_paid_place_events', v_vacant,
    'vacant_paid_place_chips', round(v_vac_chips, 2),
    'earners_not_paid', v_short,
    'earners_not_paid_chips', round(v_short_chips, 2),
    -- Counted, never alarmed: a place that received less than the flat
    -- structure share of a pool that is already fully distributed. Measured
    -- 2026-09-07 over 76,760 paid places on fully distributed events: median
    -- difference 0.0000, 1,056 over 0.05, 1,051 of those over 1.00.
    'short_of_structure_but_pool_distributed', v_labelled,
    'alerts_cleared', v_cleared,
    'bounty_pool_retained_events', v_bounty,
    'bounty_pool_retained_chips', round(v_bounty_chips, 2),
    'paid_but_unrecorded_events', v_gap,
    'paid_but_unrecorded_chips', v_gap_chips,
    'alerts_raised', v_alerts);
END;
$$;


ALTER FUNCTION public.fn_payout_guarantee_check(p_since_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_payout_guarantee_check(p_since_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_payout_guarantee_check(p_since_days integer) IS 'Raises a critical alert only when a place is short AND the event''s prize pool has not been fully distributed - money still in the escrow and a player who can be paid from it. A place short of the flat structure share of a pool that is already gone (a final_table_deal, a relabelled place, a cent of rounding) is counted, not alarmed. Every run also RESOLVES open earner_not_paid alerts whose condition no longer holds; before 2026-09-07 it could raise one and never close one, and five of the six open were false.';


--
-- Name: fn_payout_leaderboard(uuid, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_payout_leaderboard(p_club_id uuid, p_period text, p_metric text, p_start_date timestamp with time zone, p_end_date timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_start date := (p_start_date AT TIME ZONE 'UTC')::date;
  v_end date := (p_end_date AT TIME ZONE 'UTC')::date;
  v_plan jsonb;
  v_existing public.leaderboard_payout_batches%ROWTYPE;
  v_winners jsonb := '[]'::jsonb;
  v_winner jsonb;
  v_total numeric(18,2) := 0;
  v_promo_available numeric(18,2) := 0;
  v_seed_available numeric(18,2) := 0;
  v_seed_debit numeric(18,2) := 0;
  v_seed_release numeric(18,2) := 0;
  v_promo_debit numeric(18,2) := 0;
  v_union_id uuid;
  v_batch_id uuid;
  v_credited boolean;
BEGIN
  IF p_period NOT IN ('weekly', 'monthly') THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|Only Weekly And Monthly Leaderboards Can Be Settled';
  END IF;
  IF v_start IS NULL OR v_end IS NULL OR v_end <= v_start THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|Leaderboard Settlement Requires A Closed Date Range';
  END IF;
  IF v_end > (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')::date THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|An Open Leaderboard Round Cannot Be Paid';
  END IF;
  IF (p_period = 'weekly' AND (EXTRACT(DOW FROM v_start) <> 0 OR v_end <> v_start + 7))
     OR (p_period = 'monthly' AND (
       EXTRACT(DAY FROM v_start) <> 1
       OR v_end <> (v_start + interval '1 month')::date
     )) THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|Leaderboard Settlement Must Use A Canonical UTC Round';
  END IF;

  SELECT batch.* INTO v_existing
  FROM public.leaderboard_payout_batches batch
  WHERE batch.club_id = p_club_id
    AND batch.period = p_period
    AND batch.period_start = v_start;
  IF v_existing.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_settled', true,
      'batch_id', v_existing.id,
      'total_paid', v_existing.total_paid,
      'seed_funded', v_existing.seed_funded,
      'promo_funded', v_existing.promo_funded,
      'overlay_funded', v_existing.overlay_funded,
      'winner_count', v_existing.winner_count,
      'tie_policy', v_existing.tie_policy
    );
  END IF;

  v_plan := public.fn_get_leaderboard_reward_plan(p_club_id, p_period, v_start);
  IF v_plan IS NULL OR NOT COALESCE((v_plan ->> 'rewards_enabled')::boolean, false) THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|No Paid Leaderboard Program Applies To This Round';
  END IF;
  IF p_metric IS DISTINCT FROM v_plan ->> 'payout_metric' THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|Leaderboard Metric Does Not Match The Published Program';
  END IF;

  WITH board AS MATERIALIZED (
    SELECT ranked.user_id, ranked.rank
    FROM public.fn_club_leaderboard_by_dates(
      p_club_id, p_metric, v_start, v_end, 1000000, 0
    ) ranked
    WHERE ranked.qualified
  ), tied AS MATERIALIZED (
    SELECT
      board.user_id,
      board.rank,
      count(*) OVER (PARTITION BY board.rank)::integer AS tie_count,
      row_number() OVER (PARTITION BY board.rank ORDER BY board.user_id)::integer AS tie_order
    FROM board
  ), prizes AS MATERIALIZED (
    SELECT prize.rank, round(prize.amount, 2) AS amount
    FROM jsonb_to_recordset(COALESCE(v_plan -> 'prizes', '[]'::jsonb))
      AS prize(rank integer, amount numeric)
    WHERE prize.amount > 0
  ), pooled AS MATERIALIZED (
    SELECT
      tied.user_id,
      tied.rank,
      tied.tie_count,
      tied.tie_order,
      COALESCE(sum(prizes.amount), 0)::numeric(18,2) AS pool_amount
    FROM tied
    LEFT JOIN prizes
      ON prizes.rank >= tied.rank
     AND prizes.rank < tied.rank + tied.tie_count
    GROUP BY tied.user_id, tied.rank, tied.tie_count, tied.tie_order
  ), winners AS (
    SELECT
      pooled.user_id,
      pooled.rank,
      (
        trunc(pooled.pool_amount / pooled.tie_count, 2)
        + CASE
            WHEN pooled.tie_order <= mod((pooled.pool_amount * 100)::bigint, pooled.tie_count)
              THEN 0.01
            ELSE 0
          END
      )::numeric(18,2) AS amount
    FROM pooled
    WHERE pooled.pool_amount > 0
  )
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'user_id', winners.user_id,
      'rank', winners.rank,
      'amount', winners.amount
    ) ORDER BY winners.rank, winners.user_id), '[]'::jsonb),
    COALESCE(round(sum(winners.amount), 2), 0)
  INTO v_winners, v_total
  FROM winners;

  IF v_plan ->> 'funding_owner_type' = 'union' THEN
    v_union_id := (v_plan ->> 'funding_union_id')::uuid;
    SELECT COALESCE(wallet.promo_wallet, 0)
    INTO v_promo_available
    FROM public.union_wallets wallet
    WHERE wallet.union_id = v_union_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'LEADERBOARD_PROMO_WALLET_MISSING|Leaderboard Funding Union Has No Promo Wallet';
    END IF;
  ELSE
    SELECT COALESCE(setup.leaderboard_seed_remaining, 0)
    INTO v_seed_available
    FROM public.club_opening_setups setup
    WHERE setup.club_id = p_club_id
    FOR UPDATE;

    SELECT COALESCE(club.promo_balance, 0)
    INTO v_promo_available
    FROM public.clubs club
    WHERE club.id = p_club_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'LEADERBOARD_PROMO_WALLET_MISSING|Leaderboard Club Not Found';
    END IF;
  END IF;

  IF v_seed_available + v_promo_available < v_total THEN
    RAISE EXCEPTION
      'LEADERBOARD_PROMO_UNDERFUNDED|Leaderboard Requires % Promo Chips But The Recorded Promo Wallet Holds %',
      v_total,
      v_seed_available + v_promo_available;
  END IF;

  v_seed_debit := LEAST(v_total, v_seed_available);
  v_seed_release := v_seed_available - v_seed_debit;
  v_promo_debit := v_total - v_seed_debit;

  PERFORM set_config('app.ledger_category', 'leaderboard_payout', true);
  PERFORM set_config('app.ledger_counterparty', 'leaderboard_round', true);
  PERFORM set_config('app.ledger_counterparty_entity', p_club_id::text, true);

  IF v_plan ->> 'funding_owner_type' = 'union' THEN
    UPDATE public.union_wallets
    SET promo_wallet = promo_wallet - v_promo_debit,
        updated_at = now()
    WHERE union_id = v_union_id;
  ELSE
    UPDATE public.clubs
    SET promo_balance = promo_balance - v_promo_debit + v_seed_release,
        updated_at = now()
    WHERE id = p_club_id;

    UPDATE public.club_opening_setups
    SET leaderboard_seed_remaining = 0,
        updated_at = now()
    WHERE club_id = p_club_id AND leaderboard_seed_remaining > 0;
  END IF;

  INSERT INTO public.leaderboard_payout_batches (
    club_id, period, period_start, period_end, metric,
    program_id, program_version, program_hash,
    funding_owner_type, funding_union_id,
    total_paid, seed_funded, promo_funded, overlay_funded, winner_count, tie_policy
  ) VALUES (
    p_club_id, p_period, v_start, v_end, p_metric,
    (v_plan ->> 'program_id')::uuid,
    (v_plan ->> 'program_version')::integer,
    v_plan ->> 'program_hash',
    v_plan ->> 'funding_owner_type', v_union_id,
    v_total, v_seed_debit, v_promo_debit, 0, jsonb_array_length(v_winners),
    'split_occupied_places'
  ) RETURNING id INTO v_batch_id;

  FOR v_winner IN SELECT value FROM jsonb_array_elements(v_winners)
  LOOP
    v_credited := public.fn_credit_and_log(
      (v_winner ->> 'user_id')::uuid,
      (v_winner ->> 'amount')::numeric,
      format('leaderboard:%s:%s:%s:%s', p_club_id, p_period, v_start, v_winner ->> 'user_id'),
      'leaderboard_payout',
      format('%s Leaderboard, Rank %s', initcap(p_period), v_winner ->> 'rank'),
      (v_plan ->> 'program_id')::uuid
    );
    IF NOT v_credited THEN
      RAISE EXCEPTION 'LEADERBOARD_CREDIT_CONFLICT|Leaderboard Credit Key Already Exists Without A Batch Receipt';
    END IF;

    INSERT INTO public.leaderboard_payouts (
      club_id, period, metric, start_date, end_date, user_id, rank,
      payout_amount, payout_currency, awarded_at, batch_id
    ) VALUES (
      p_club_id, p_period, p_metric, v_start, v_end,
      (v_winner ->> 'user_id')::uuid,
      (v_winner ->> 'rank')::integer,
      (v_winner ->> 'amount')::numeric,
      'chips', now(), v_batch_id
    );
  END LOOP;

  UPDATE public.leaderboard_payout_failures
  SET resolved_at = now(),
      resolution = 'Settlement Completed Automatically'
  WHERE club_id = p_club_id
    AND period = p_period
    AND period_start = v_start
    AND resolved_at IS NULL;

  RETURN jsonb_build_object(
    'success', true,
    'already_settled', false,
    'batch_id', v_batch_id,
    'total_paid', v_total,
    'seed_funded', v_seed_debit,
    'promo_funded', v_promo_debit,
    'overlay_funded', 0,
    'winner_count', jsonb_array_length(v_winners),
    'tie_policy', 'split_occupied_places'
  );
END;
$$;


ALTER FUNCTION public.fn_payout_leaderboard(p_club_id uuid, p_period text, p_metric text, p_start_date timestamp with time zone, p_end_date timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_payout_leaderboard(p_club_id uuid, p_period text, p_metric text, p_start_date timestamp with time zone, p_end_date timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_payout_leaderboard(p_club_id uuid, p_period text, p_metric text, p_start_date timestamp with time zone, p_end_date timestamp with time zone) IS 'Atomic service-only leaderboard settlement. Uses only the recorded Promo Wallet and opening Promo reserve, splits occupied prizes across ties exactly, credits winners once, and writes immutable batch-linked receipts.';


--
-- Name: fn_pgrst_reload_watchdog(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pgrst_reload_watchdog() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_breaches jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_result   jsonb;
  v_reloads_1h int;
  v_timeout_raw text;
  v_timeout interval;
  r record;
  c_reloads_per_hour_breach constant int := 60;
  c_reloads_per_hour_warn   constant int := 20;
BEGIN
  SELECT count(*) INTO v_reloads_1h
    FROM public.ca_ddl_events
   WHERE occurred_at > now() - interval '1 hour'
     AND triggers_pgrst_reload;

  IF v_reloads_1h >= c_reloads_per_hour_warn THEN
    FOR r IN
      SELECT coalesce(application_name,'?') AS app, role_name,
             count(*) AS events,
             max(occurred_at) AS last_at
        FROM public.ca_ddl_events
       WHERE occurred_at > now() - interval '1 hour'
         AND triggers_pgrst_reload
       GROUP BY 1, 2 ORDER BY events DESC LIMIT 5
    LOOP
      IF v_reloads_1h >= c_reloads_per_hour_breach THEN
        v_breaches := v_breaches || jsonb_build_object(
          'check','pgrst_reload_storm','reloads_last_hour',v_reloads_1h,
          'application',r.app,'role',r.role_name,'events',r.events,'last_at',r.last_at,
          'why','Each reload-triggering DDL statement makes PostgREST re-read a ~970-relation schema cache (~28s). '
             || 'At this rate reloading is near-continuous - the precursor of the 2026-08-31 PGRST002 503 storm. '
             || 'Batch DDL into single transactions and stop any migration retry loop (CLAUDE.md, Production DDL policy).');
      ELSE
        v_warnings := v_warnings || jsonb_build_object(
          'check','pgrst_reload_rate_elevated','reloads_last_hour',v_reloads_1h,
          'application',r.app,'role',r.role_name,'events',r.events,'last_at',r.last_at);
      END IF;
    END LOOP;
  END IF;

  SELECT split_part(cfg, '=', 2) INTO v_timeout_raw
    FROM pg_roles, unnest(coalesce(rolconfig, '{}'::text[])) AS cfg
   WHERE rolname = 'authenticator' AND cfg LIKE 'statement_timeout=%'
   LIMIT 1;
  BEGIN
    IF v_timeout_raw IS NULL THEN
      v_timeout := NULL;
    ELSIF v_timeout_raw ~ '^[0-9]+$' THEN
      v_timeout := (v_timeout_raw || ' milliseconds')::interval;
    ELSE
      v_timeout := v_timeout_raw::interval;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_timeout := NULL;
  END;
  IF v_timeout IS NOT NULL AND v_timeout < interval '2 minutes' THEN
    v_breaches := v_breaches || jsonb_build_object(
      'check','authenticator_timeout_reverted','statement_timeout',v_timeout_raw,
      'why','PostgREST loads its schema cache as authenticator; the load takes ~28s here. A timeout below 2min '
         || 'kills the load and recreates the 2026-08-31 PGRST002 outage. '
         || 'Restore with: ALTER ROLE authenticator SET statement_timeout = ''5min'' '
         || '(migration fix_pgrst002_schema_cache_timeout), then recycle authenticator backends.');
  END IF;

  FOR r IN
    SELECT expected.evtname AS name, et.evtenabled
      FROM (VALUES ('pgrst_ddl_watch'), ('pgrst_drop_watch'),
                   ('ca_ddl_watchdog_log'), ('ca_ddl_watchdog_drop_log')) AS expected(evtname)
      LEFT JOIN pg_event_trigger et ON et.evtname = expected.evtname
  LOOP
    IF r.evtenabled IS NULL OR r.evtenabled = 'D' THEN
      v_breaches := v_breaches || jsonb_build_object(
        'check','event_trigger_missing_or_disabled','trigger',r.name,
        'why','pgrst_* watches keep PostgREST''s schema cache honest; ca_ddl_watchdog_* feed this watchdog.');
    END IF;
  END LOOP;

  v_result := jsonb_build_object(
    'checked_at', now(),
    'reloads_last_hour', v_reloads_1h,
    'breaches', v_breaches,
    'warnings', v_warnings);

  INSERT INTO public.pgrst_reload_watchdog_log (breach_count, warn_count, result)
  VALUES (jsonb_array_length(v_breaches), jsonb_array_length(v_warnings), v_result);

  -- Retention: watchdog log 30 days; reload-relevant DDL events 14 days;
  -- non-reload DDL noise (runtime GRANT/REVOKE churn, ~45/min) 3 days.
  DELETE FROM public.pgrst_reload_watchdog_log WHERE ran_at < now() - interval '30 days';
  DELETE FROM public.ca_ddl_events
   WHERE (triggers_pgrst_reload AND occurred_at < now() - interval '14 days')
      OR (NOT triggers_pgrst_reload AND occurred_at < now() - interval '3 days');

  IF jsonb_array_length(v_breaches) > 0 THEN
    RAISE WARNING 'pgrst_reload_watchdog: % breach(es): %',
      jsonb_array_length(v_breaches), v_breaches;
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION public.fn_pgrst_reload_watchdog() OWNER TO postgres;

--
-- Name: fn_place_entitlement(numeric, anyelement, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_place_entitlement(p_pool numeric, p_structure anyelement, p_place integer) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_raw jsonb; v_arr jsonb; v_pct numeric;
BEGIN
  IF p_place IS NULL OR COALESCE(p_pool, 0) <= 0 THEN
    RETURN 0;
  END IF;
  BEGIN
    v_raw := to_jsonb(p_structure);
    IF jsonb_typeof(v_raw) = 'string' THEN
      v_arr := (v_raw #>> '{}')::jsonb;
    ELSE
      v_arr := v_raw;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN 0;
  END;
  IF v_arr IS NULL OR jsonb_typeof(v_arr) <> 'array' THEN
    RETURN 0;
  END IF;
  SELECT (el->>'percentage')::numeric INTO v_pct
    FROM jsonb_array_elements(v_arr) el
   WHERE (el->>'place')::int = p_place
   LIMIT 1;
  RETURN round(COALESCE(p_pool, 0) * COALESCE(v_pct, 0) / 100.0, 2);
END;
$$;


ALTER FUNCTION public.fn_place_entitlement(p_pool numeric, p_structure anyelement, p_place integer) OWNER TO postgres;

--
-- Name: fn_platform_frozen(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_platform_frozen() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.engine_maintenance_break b
    WHERE b.phase = 'counting_down'
      AND b.enforce_freeze
      AND b.break_ends_at > NOW()
      AND b.break_ends_at < NOW() + INTERVAL '15 minutes'
  );
$$;


ALTER FUNCTION public.fn_platform_frozen() OWNER TO postgres;

--
-- Name: FUNCTION fn_platform_frozen(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_platform_frozen() IS 'True while the scheduled maintenance freeze is running (counting_down phase only - the last_hand phase still has pots to settle). Self-expiring: a stale row cannot freeze the platform permanently.';


--
-- Name: fn_platform_invariants_health(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_platform_invariants_health() RETURNS TABLE(check_name text, status text, detail text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE n int; n2 int; n3 int;
BEGIN
  RETURN QUERY SELECT g.check_name, g.status, g.detail FROM public.fn_grant_guard_health() g;
  SELECT count(*) INTO n FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace
   WHERE ns.nspname='public' AND p.prokind='f' AND btrim(p.prosrc) ~ '^BEGIN\s+END;?$';
  RETURN QUERY SELECT 'empty_stubs'::text, CASE WHEN n=0 THEN 'OK' ELSE 'STUBS_PRESENT' END, n || ' functions with a BEGIN END; body';
  SELECT count(*) INTO n FROM pg_constraint WHERE conname='wallet_transactions_amount_non_negative';
  SELECT count(*) INTO n2 FROM public.wallet_transactions wt WHERE wt.type='debit' AND wt.amount<0 AND wt.category IN ('buyin','addon','rebuy','tournament_buyin');
  RETURN QUERY SELECT 'debit_sign_convention'::text, CASE WHEN n=1 AND n2=0 THEN 'OK' ELSE 'REGRESSED' END, 'constraint=' || n || ', negative debit rows in fixed categories=' || n2;
  SELECT count(*) INTO n FROM public.daily_challenge_catalog;
  RETURN QUERY SELECT 'challenge_catalog'::text, CASE WHEN n>=18 THEN 'OK' ELSE 'CATALOG_SHRUNK' END, n || ' rows (>=18 expected)';
  SELECT COALESCE(sum(weight),0) INTO n FROM public.lucky_wheel_segments s WHERE s.active;
  RETURN QUERY SELECT 'lucky_wheel_weights'::text, CASE WHEN n=100 THEN 'OK' ELSE 'WEIGHTS_DRIFTED' END, 'active weights sum ' || n;
  SELECT count(*) INTO n FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid
   WHERE (c.relname='clubs' AND p.polname IN ('Authenticated users can create clubs','Owners can update clubs') AND pg_get_expr(p.polwithcheck, p.polrelid) LIKE '%owner_id%')
      OR (c.relname='club_members' AND p.polname='Club staff can read club rosters');
  RETURN QUERY SELECT 'club_rls_trio'::text, CASE WHEN n=3 THEN 'OK' ELSE 'POLICY_MISSING' END, n || ' of 3 policies intact';
  SELECT count(*) INTO n FROM pg_proc WHERE proname='fn_increment_vip_usage' AND prosrc LIKE '%vip_feature_usage_monthly%';
  RETURN QUERY SELECT 'vip_monthly_ledger'::text, CASE WHEN n=1 THEN 'OK' ELSE 'UNWIRED' END, 'fn_increment_vip_usage writes the monthly table: ' || (n=1);
  SELECT count(*) INTO n FROM pg_proc WHERE proname='deduct_diamonds' AND prosrc LIKE '%Cannot deduct diamonds for another user%' AND prosrc LIKE '%positive integer%';
  RETURN QUERY SELECT 'deduct_diamonds_guards'::text, CASE WHEN n=1 THEN 'OK' ELSE 'GUARDS_REMOVED' END, 'identity + positive-amount guards present: ' || (n=1);
  RETURN QUERY SELECT 'engine_recovery_events'::text, CASE WHEN to_regclass('public.engine_recovery_events') IS NOT NULL THEN 'OK' ELSE 'MISSING' END, COALESCE((SELECT count(*) FROM public.engine_recovery_events)::text,'0') || ' recovery events recorded';
  SELECT count(*) INTO n FROM (SELECT bp.union_id FROM public.bbj_pools bp WHERE bp.club_id IS NULL AND bp.union_id IS NOT NULL AND bp.status='active' GROUP BY bp.union_id HAVING count(*) > 1) d;
  SELECT count(*) INTO n2 FROM public.bbj_contributions bc WHERE bc.pool_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.bbj_pools p WHERE p.id = bc.pool_id);
  SELECT count(*) INTO n3 FROM pg_indexes WHERE schemaname='public' AND indexname IN ('uq_bbj_pools_union_active','uq_bbj_pools_club_active');
  RETURN QUERY SELECT 'bbj_pool_integrity'::text, CASE WHEN n=0 AND n2=0 AND n3=2 THEN 'OK' ELSE 'FRAGMENTED' END, 'fragmented unions=' || n || ', orphaned contributions=' || n2 || ', unique indexes=' || n3 || '/2';
  -- BBJ SOLVENCY (Dan 2026-08-18): no live payout exceeded the pool at hit, and only one payer keeps pool write privileges.
  SELECT count(*) INTO n FROM public.bbj_winners w WHERE w.pool_amount_at_hit IS NOT NULL AND w.total_payout > w.pool_amount_at_hit + 0.01;
  SELECT count(*) INTO n2 FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace
   WHERE ns.nspname='public' AND p.proname IN ('award_bbj','bbj_atomic_payout','fn_union_bbj_pool_payout','bbj_promo_payout','fn_bbj_payout')
     AND has_function_privilege('authenticated', p.oid, 'EXECUTE');
  RETURN QUERY SELECT 'bbj_solvency'::text, CASE WHEN n=0 AND n2=0 THEN 'OK' ELSE 'VIOLATED' END, 'payouts exceeding pool=' || n || ', legacy payers authenticated-exec=' || n2;
  -- 2026-08-18: the minting bug lived in the payer's drain arithmetic and
  -- survived the solvency overhaul, because every check asked whether a
  -- payout EXCEEDED the pool, never whether the pool GREW. This runs the
  -- real payer in a rolled-back subtransaction and asserts conservation.
  RETURN QUERY SELECT 'bbj_payout_conservation'::text,
    CASE WHEN t.ok THEN 'OK' ELSE 'VIOLATED' END, t.detail
  FROM public.fn_bbj_selftest_payout_conservation() t;

END;
$_$;


ALTER FUNCTION public.fn_platform_invariants_health() OWNER TO postgres;

--
-- Name: FUNCTION fn_platform_invariants_health(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_platform_invariants_health() IS 'Superset of fn_grant_guard_health: one call asserting every invariant from the 2026-08 audit/build phases. All rows OK = nothing regressed.';


