-- Name: fn_player_display_name(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_player_display_name(p_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.fn_arena_name(p.alias, p.username, p.display_name,
                              p.first_name, p.last_name, p.full_name)
    FROM public.profiles p
   WHERE p.id = p_user_id;
$$;


ALTER FUNCTION public.fn_player_display_name(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_player_home_club(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_player_home_club(p_user_id uuid, p_club_hint uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_club uuid;
BEGIN
  IF p_user_id IS NULL THEN RETURN NULL; END IF;
  IF p_club_hint IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.user_id = p_user_id AND cm.club_id = p_club_hint
       AND cm.status IN ('active','approved')
  ) THEN RETURN p_club_hint; END IF;
  SELECT cm.club_id INTO v_club
    FROM public.club_members cm
   WHERE cm.user_id = p_user_id AND cm.status IN ('active','approved')
   ORDER BY cm.joined_at ASC NULLS LAST, cm.club_id
   LIMIT 1;
  RETURN v_club;
END;
$$;


ALTER FUNCTION public.fn_player_home_club(p_user_id uuid, p_club_hint uuid) OWNER TO postgres;

--
-- Name: fn_player_rakeback_rate(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_player_rakeback_rate(p_user_id uuid, p_club_id uuid, p_volume numeric DEFAULT 0) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal numeric; v_agent_default numeric; v_upline_rate numeric; v_rate numeric; v_cap numeric;
BEGIN
  SELECT COALESCE(cm.player_rakeback_pct, 0),
         COALESCE(a.player_rakeback_rate, 0),
         COALESCE(a.commission_rate, 0)
    INTO v_deal, v_agent_default, v_upline_rate
    FROM club_members cm
    LEFT JOIN agents a ON a.user_id = cm.agent_id AND a.club_id = cm.club_id AND a.status = 'active'
   WHERE cm.user_id = p_user_id AND cm.club_id = p_club_id
   LIMIT 1;

  -- 1. the player's own negotiated deal
  IF COALESCE(v_deal,0) > 0 THEN
    v_rate := v_deal;
  -- 2. their agent's standing offer
  ELSIF COALESCE(v_agent_default,0) > 0 THEN
    v_rate := v_agent_default;
  -- 3. legacy volume ladder (players with no agent)
  ELSE
    v_rate := CASE WHEN p_volume >= 10000 THEN 0.30
                   WHEN p_volume >=  2000 THEN 0.20
                   WHEN p_volume >=   500 THEN 0.15
                   WHEN p_volume >=   100 THEN 0.10
                   ELSE 0.05 END;
  END IF;

  -- Never more than the upline receives, less the ten-point gap.
  IF COALESCE(v_upline_rate,0) > 0 THEN
    v_cap := GREATEST(v_upline_rate - 0.10, 0);
    v_rate := LEAST(v_rate, v_cap);
  END IF;

  RETURN GREATEST(ROUND(COALESCE(v_rate,0), 4), 0);
END $$;


ALTER FUNCTION public.fn_player_rakeback_rate(p_user_id uuid, p_club_id uuid, p_volume numeric) OWNER TO postgres;

--
-- Name: fn_player_spendable_balance(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_player_spendable_balance(p_user_id uuid, p_club_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club uuid := NULL;
  v_balance numeric := 0;
  v_source text := 'club_chips';
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( p_user_id IS DISTINCT FROM auth.uid() AND NOT EXISTS (SELECT 1 FROM club_members cm                   WHERE cm.user_id = p_user_id                     AND cm.agent_id = auth.uid()) AND NOT EXISTS (SELECT 1 FROM club_members cm2                   JOIN union_clubs uc ON uc.club_id = cm2.club_id                   WHERE cm2.user_id = p_user_id                     AND public.fn_is_union_overseer(uc.union_id, auth.uid())))) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('balance', 0, 'source', 'none', 'club_id', NULL);
  END IF;

  IF p_table_id IS NOT NULL THEN
    -- Seated or sitting down: the seat's own club is the wallet that will be
    -- debited by a rebuy or add-on.
    SELECT ts.club_id INTO v_club
      FROM table_seats ts
     WHERE ts.table_id = p_table_id AND ts.user_id = p_user_id AND ts.left_at IS NULL
     LIMIT 1;
    IF v_club IS NULL THEN
      v_club := public.fn_seat_club_for_user(p_user_id, p_table_id, p_club_id);
    END IF;
  ELSIF p_club_id IS NOT NULL THEN
    SELECT m.club_id INTO v_club
      FROM club_members m
     WHERE m.user_id = p_user_id AND m.club_id = p_club_id
     LIMIT 1;
  END IF;

  IF v_club IS NULL THEN
    v_club := public.fn_player_home_club(p_user_id, p_club_hint => NULL);
  END IF;

  IF v_club IS NOT NULL THEN
    SELECT COALESCE(chip_balance, 0) INTO v_balance
      FROM club_members WHERE user_id = p_user_id AND club_id = v_club;
  ELSE
    -- No club anywhere: a pure smarter.poker user, whose only wallet is global.
    SELECT COALESCE(balance, 0) INTO v_balance
      FROM wallets WHERE user_id = p_user_id AND wallet_type = 'PLAYER';
    v_source := 'smarter_poker_wallet';
  END IF;

  RETURN jsonb_build_object(
    'balance', COALESCE(v_balance, 0),
    'source', v_source,
    'club_id', v_club,
    'club_scoped', true
  );
END $$;


ALTER FUNCTION public.fn_player_spendable_balance(p_user_id uuid, p_club_id uuid, p_table_id uuid) OWNER TO postgres;

--
-- Name: fn_plinko_activate_table(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_plinko_activate_table(p_version integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a record;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_ca_caller_is_management() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only Platform Management Activates A Plinko Table');
  END IF;
  SELECT x.* INTO a FROM public.fn_plinko_table_audit(p_version) x;
  IF a.spec_rtp IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Table Does Not Exist');
  END IF;
  IF a.spec_rtp <> 0.800000 THEN
    RETURN jsonb_build_object('ok', false, 'error', format('Return To Player Must Be Exactly 80 Percent, Not %s', a.spec_rtp), 'audit', to_jsonb(a));
  END IF;
  UPDATE public.plinko_tables
     SET spec_rtp = a.spec_rtp, sd_chips = a.sd_chips, hit_rate = a.hit_rate,
         max_multiplier_cents = a.max_multiplier_cents, activated_at = COALESCE(activated_at, now())
   WHERE version = p_version;
  RETURN jsonb_build_object('ok', true, 'version', p_version, 'audit', to_jsonb(a));
END $$;


ALTER FUNCTION public.fn_plinko_activate_table(p_version integer) OWNER TO postgres;

--
-- Name: fn_plinko_drop(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_plinko_drop(p_club_id uuid, p_commit_id uuid, p_client_seed text, p_table_version integer, p_bet_diamonds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  prior public.plinko_drops;
  adm record;
  t public.plinko_tables%ROWTYPE;
  v_id uuid := gen_random_uuid();
  v_hmac bytea; v_path integer := 0; v_slot integer := 0; i integer;
  v_cap integer; v_table_mult integer; v_mult integer; v_payout numeric;
  v_deduct jsonb; v_bank numeric; v_member_after numeric; v_bank_after numeric;
  v_dia_after numeric;
  pool public.diamond_game_pools%ROWTYPE;
  d public.plinko_drops;
BEGIN
  SELECT * INTO prior FROM public.plinko_drops WHERE commit_id = p_commit_id;
  IF prior.id IS NOT NULL THEN
    IF prior.user_id <> v_user THEN
      RETURN jsonb_build_object('ok', false, 'error', 'That Drop Belongs To Another Player');
    END IF;
    RETURN public.fn_plinko_drop_result(prior) || jsonb_build_object('replayed', true);
  END IF;

  SELECT * INTO adm FROM public.fn_diamond_game_admit('plinko', p_club_id, p_commit_id, p_client_seed, p_bet_diamonds);
  IF adm.err IS NOT NULL THEN RETURN adm.err; END IF;

  SELECT * INTO t FROM public.plinko_tables WHERE version = p_table_version AND activated_at IS NOT NULL;
  IF t.version IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Plinko Table Is Not Active');
  END IF;

  -- ── the cap, before the ball drops ─────────────────────────────────────────
  v_cap := public.fn_diamond_game_cap_cents(adm.o_cfg, adm.o_pool, adm.o_bank, adm.o_bet_chips, LEAST(t.max_multiplier_cents, (adm.o_cfg).max_multiplier_cents));
  IF v_cap < 101 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Bank Cannot Cover A Win At That Bet Right Now. Try A Smaller Bet',
                              'cap_cents', v_cap);
  END IF;

  -- ── the roll: sixteen bits, one per row ────────────────────────────────────
  v_hmac := extensions.hmac(convert_to(p_client_seed || ':' || adm.o_nonce::text, 'UTF8'),
                            convert_to((adm.o_commit).server_seed, 'UTF8'), 'sha256');
  FOR i IN 0..15 LOOP
    IF get_bit(v_hmac, i) = 1 THEN
      v_path := v_path | (1 << i);
      v_slot := v_slot + 1;
    END IF;
  END LOOP;
  v_table_mult := t.multipliers_cents[v_slot + 1];
  v_mult := LEAST(v_table_mult, v_cap);
  v_payout := round(adm.o_bet_chips * v_mult / 100, 2);

  -- ── 1. the bet is paid for ─────────────────────────────────────────────────
  v_deduct := public.fn_diamond_game_take_bet(v_user, p_bet_diamonds, (adm.o_cfg).purchased_only, 'plinko_drop',
                format('Diamond Plinko Drop (%s Diamonds, %s)', p_bet_diamonds, t.name),
                'plinko:' || v_id::text,
                jsonb_build_object('drop_id', v_id, 'club_id', p_club_id, 'host_id', adm.o_host,
                                   'commit_id', p_commit_id, 'table_version', t.version));
  IF COALESCE((v_deduct->>'success')::boolean, false) = false THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not Enough Diamonds For That Bet', 'detail', v_deduct->>'error');
  END IF;

  -- ── 2. the host is paid its chip share ─────────────────────────────────────
  v_bank := COALESCE(public.fn_diamond_game_mint_leg(adm.o_host, adm.o_kind, adm.o_mint, 'plinko-mint:' || v_id::text), adm.o_bank);

  -- ── 3. the payout ──────────────────────────────────────────────────────────
  IF v_payout > 0 THEN
    IF v_bank < v_payout THEN
      RAISE EXCEPTION 'fn_plinko_drop: host bank % below the payout % after the cap passed', v_bank, v_payout;
    END IF;
    SELECT x.bank_after, x.member_after INTO v_bank_after, v_member_after
      FROM public.fn_diamond_game_prize_leg('plinko', adm.o_host, adm.o_kind, p_club_id, v_user, v_payout,
             'plinko-prize:' || v_id::text,
             format('Diamond Plinko: %s.%sx on %s', v_mult / 100, lpad((v_mult % 100)::text, 2, '0'), t.name),
             jsonb_build_object('drop_id', v_id, 'host_id', adm.o_host, 'host_kind', adm.o_kind,
                                'table_version', t.version, 'slot', v_slot, 'multiplier_cents', v_mult, 'capped', v_mult < v_table_mult)) x;
  ELSE
    SELECT COALESCE(cm.chip_balance, 0) INTO v_member_after FROM public.club_members cm
     WHERE cm.club_id = p_club_id AND cm.user_id = v_user LIMIT 1;
  END IF;

  -- ── 4. the pool remembers ──────────────────────────────────────────────────
  UPDATE public.diamond_game_pools
     SET rounds = rounds + 1,
         intake_diamonds = intake_diamonds + p_bet_diamonds,
         chips_minted = chips_minted + adm.o_mint,
         chips_paid = chips_paid + v_payout,
         constrained_rounds = constrained_rounds + CASE WHEN v_cap < LEAST(t.max_multiplier_cents, (adm.o_cfg).max_multiplier_cents) THEN 1 ELSE 0 END,
         updated_at = now()
   WHERE host_id = adm.o_host AND game = 'plinko'
   RETURNING * INTO pool;
  IF pool.chips_paid + pool.reserved_chips > pool.chips_minted + (adm.o_cfg).exposure_allowance_chips THEN
    RAISE EXCEPTION 'fn_plinko_drop: chips_paid % would exceed chips_minted % + allowance % - the cap was bypassed',
      pool.chips_paid, pool.chips_minted, (adm.o_cfg).exposure_allowance_chips;
  END IF;

  SELECT COALESCE(p.diamonds, 0) INTO v_dia_after FROM public.profiles p WHERE p.id = v_user;
  UPDATE public.diamond_game_commits SET consumed_by = v_id WHERE id = p_commit_id;

  INSERT INTO public.plinko_drops
    (id, host_id, host_kind, club_id, user_id, table_version, bet_diamonds, bet_chips, diamonds_per_chip,
     commit_id, server_seed_hash, server_seed, client_seed, nonce, hmac_hex, path_bits, slot,
     table_multiplier_cents, cap_multiplier_cents, multiplier_cents, capped, payout_chips, chips_minted,
     pool_chips_minted_after, pool_chips_paid_after, diamonds_after, member_chips_after, is_fixture)
  VALUES
    (v_id, adm.o_host, adm.o_kind, p_club_id, v_user, t.version, p_bet_diamonds, adm.o_bet_chips, adm.o_rate,
     p_commit_id, (adm.o_commit).server_seed_hash, (adm.o_commit).server_seed, p_client_seed, adm.o_nonce, encode(v_hmac, 'hex'), v_path, v_slot,
     v_table_mult, v_cap, v_mult, v_mult < v_table_mult, v_payout, adm.o_mint,
     pool.chips_minted, pool.chips_paid, v_dia_after, v_member_after, adm.o_fixture)
  RETURNING * INTO d;
  RETURN public.fn_plinko_drop_result(d);
END $$;


ALTER FUNCTION public.fn_plinko_drop(p_club_id uuid, p_commit_id uuid, p_client_seed text, p_table_version integer, p_bet_diamonds integer) OWNER TO postgres;

--
-- Name: plinko_drops; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.plinko_drops (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    host_id uuid NOT NULL,
    host_kind text NOT NULL,
    club_id uuid NOT NULL,
    user_id uuid NOT NULL,
    table_version integer NOT NULL,
    bet_diamonds integer NOT NULL,
    bet_chips numeric(14,2) NOT NULL,
    diamonds_per_chip integer NOT NULL,
    commit_id uuid NOT NULL,
    server_seed_hash text NOT NULL,
    server_seed text NOT NULL,
    client_seed text NOT NULL,
    nonce bigint NOT NULL,
    hmac_hex text NOT NULL,
    path_bits integer NOT NULL,
    slot smallint NOT NULL,
    table_multiplier_cents integer NOT NULL,
    cap_multiplier_cents integer NOT NULL,
    multiplier_cents integer NOT NULL,
    capped boolean DEFAULT false NOT NULL,
    payout_chips numeric(14,2) NOT NULL,
    chips_minted numeric(14,2) NOT NULL,
    pool_chips_minted_after numeric(16,2) NOT NULL,
    pool_chips_paid_after numeric(16,2) NOT NULL,
    diamonds_after numeric NOT NULL,
    member_chips_after numeric(14,2),
    is_fixture boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT plinko_drops_slot_check CHECK (((slot >= 0) AND (slot <= 16)))
);


ALTER TABLE public.plinko_drops OWNER TO postgres;

--
-- Name: TABLE plinko_drops; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.plinko_drops IS 'Every Diamond Plinko drop: seeds, the HMAC, the ball''s path (bit i = row i, 1 = right), the slot, the table and capped multipliers, the payout and the pool after. Append-only.';


--
-- Name: fn_plinko_drop_result(public.plinko_drops); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_plinko_drop_result(d public.plinko_drops) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'ok', true, 'game', 'plinko', 'drop_id', d.id, 'club_id', d.club_id, 'host_id', d.host_id,
    'table_version', d.table_version, 'bet_diamonds', d.bet_diamonds, 'bet_chips', d.bet_chips,
    'diamonds_per_chip', d.diamonds_per_chip,
    'outcome', jsonb_build_object(
      'slot', d.slot, 'path_bits', d.path_bits,
      'path', (SELECT jsonb_agg(((d.path_bits >> i) & 1) ORDER BY i) FROM generate_series(0, 15) i),
      'table_multiplier_cents', d.table_multiplier_cents, 'cap_multiplier_cents', d.cap_multiplier_cents,
      'multiplier_cents', d.multiplier_cents, 'capped', d.capped, 'payout_chips', d.payout_chips),
    'fairness', jsonb_build_object('commit_id', d.commit_id, 'server_seed_hash', d.server_seed_hash,
                                   'server_seed', d.server_seed, 'client_seed', d.client_seed,
                                   'nonce', d.nonce, 'hmac_hex', d.hmac_hex),
    'balances', jsonb_build_object('diamonds', d.diamonds_after, 'member_chips', d.member_chips_after),
    'pool', jsonb_build_object('chips_minted', d.pool_chips_minted_after, 'chips_paid', d.pool_chips_paid_after),
    'created_at', d.created_at);
$$;


ALTER FUNCTION public.fn_plinko_drop_result(d public.plinko_drops) OWNER TO postgres;

--
-- Name: fn_plinko_table_audit(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_plinko_table_audit(p_version integer, OUT spec_rtp numeric, OUT sd_chips numeric, OUT hit_rate numeric, OUT max_multiplier_cents integer, OUT slots integer) RETURNS record
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  c constant integer[] := ARRAY[1,16,120,560,1820,4368,8008,11440,12870,11440,8008,4368,1820,560,120,16,1];
  m integer[];
  v_ev numeric := 0; v_e2 numeric := 0; v_hit numeric := 0; i integer;
BEGIN
  SELECT t.multipliers_cents INTO m FROM public.plinko_tables t WHERE t.version = p_version;
  IF m IS NULL THEN RETURN; END IF;
  FOR i IN 1..17 LOOP
    v_ev  := v_ev  + c[i] * m[i];
    v_e2  := v_e2  + c[i] * (m[i]::numeric * m[i]);
    v_hit := v_hit + CASE WHEN m[i] > 0 THEN c[i] ELSE 0 END;
  END LOOP;
  spec_rtp := round(v_ev / (65536 * 100), 6);
  sd_chips := round(sqrt(v_e2 / (65536 * 10000) - power(v_ev / (65536 * 100), 2)), 6);
  hit_rate := round(v_hit / 65536, 6);
  max_multiplier_cents := (SELECT max(x) FROM unnest(m) x);
  slots := 17;
END $$;


ALTER FUNCTION public.fn_plinko_table_audit(p_version integer, OUT spec_rtp numeric, OUT sd_chips numeric, OUT hit_rate numeric, OUT max_multiplier_cents integer, OUT slots integer) OWNER TO postgres;

--
-- Name: fn_poker_arena_context(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_arena_context(p_club_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_club public.clubs%ROWTYPE; v_role text; v_member boolean;
BEGIN
  IF v_uid IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_uid) THEN
    RAISE EXCEPTION 'Authentication Required' USING ERRCODE = '28000';
  END IF;
  SELECT c.* INTO v_club FROM public.clubs c
  WHERE c.id::text = btrim(p_club_key) OR c.club_id::text = btrim(p_club_key)
     OR lower(c.slug) = lower(btrim(p_club_key))
  ORDER BY (c.id::text = btrim(p_club_key)) DESC LIMIT 1;
  IF NOT FOUND OR v_club.lifecycle_status = 'retired' THEN RETURN NULL; END IF;
  IF v_club.asset = 'diamonds' THEN
    IF v_club.is_platform IS DISTINCT FROM true OR v_club.union_id IS NOT NULL
       OR NOT EXISTS (SELECT 1 FROM public.ca_arena_settings WHERE club_id = v_club.id) THEN
      RAISE EXCEPTION 'Invalid Diamond Arena Identity' USING ERRCODE = '23514';
    END IF;
    v_member := true; v_role := 'player';
  ELSIF v_club.asset = 'chips' AND v_club.is_platform = false THEN
    SELECT m.role INTO v_role FROM public.club_members m
      WHERE m.club_id = v_club.id AND m.user_id = v_uid AND m.status IN ('active','approved');
    v_member := FOUND;
  ELSE RAISE EXCEPTION 'Invalid Arena Asset' USING ERRCODE = '23514';
  END IF;
  RETURN jsonb_build_object('arena',jsonb_build_object('id',v_club.id,'asset',v_club.asset,
    'is_platform',v_club.is_platform,'union_id',v_club.union_id), 'member',v_member,'role',v_role);
END $$;


ALTER FUNCTION public.fn_poker_arena_context(p_club_key text) OWNER TO postgres;

--
-- Name: fn_poker_can_read_games(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_can_read_games(p_club_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_club public.clubs%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;
  SELECT * INTO v_club FROM public.clubs WHERE id=p_club_id;
  IF NOT FOUND OR v_club.lifecycle_status = 'retired' THEN RETURN false; END IF;
  IF v_club.asset = 'diamonds' THEN
    RETURN v_club.is_platform AND v_club.union_id IS NULL
      AND EXISTS (SELECT 1 FROM public.ca_arena_settings WHERE club_id=v_club.id)
      AND EXISTS (SELECT 1 FROM public.profiles WHERE id=v_uid);
  END IF;
  IF v_club.asset IS DISTINCT FROM 'chips' OR v_club.is_platform THEN RETURN false; END IF;
  RETURN EXISTS (SELECT 1 FROM public.club_members m
    WHERE m.club_id=ANY(public.fn_club_scope_ids(p_club_id))
      AND m.user_id=v_uid AND m.status IN ('active','approved'))
    OR public.fn_union_oversees_club(p_club_id,v_uid);
END $$;


ALTER FUNCTION public.fn_poker_can_read_games(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_poker_guard_arena_structure(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_guard_arena_structure() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_asset text;
BEGIN
  IF TG_TABLE_NAME='clubs' THEN
    IF TG_OP='UPDATE' AND (NEW.asset,NEW.is_platform) IS DISTINCT FROM (OLD.asset,OLD.is_platform) THEN
      RAISE EXCEPTION 'Arena Asset Is Immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.asset='diamonds' AND auth.uid() IS NOT NULL AND coalesce(auth.jwt()->>'role','') <> 'service_role'
       AND NOT coalesce(public.fn_is_platform_admin(),false) THEN
      RAISE EXCEPTION 'Diamond Arena Requires Platform Operations' USING ERRCODE='42501';
    END IF;
    RETURN NEW;
  END IF;
  SELECT asset INTO v_asset FROM public.clubs WHERE id=NEW.club_id;
  IF TG_TABLE_NAME='club_members' AND TG_OP='UPDATE' AND NEW.club_id IS DISTINCT FROM OLD.club_id
     AND EXISTS (SELECT 1 FROM public.clubs WHERE id=OLD.club_id AND asset='diamonds') THEN
    RAISE EXCEPTION 'Diamond Participation Cannot Become A Chip Membership' USING ERRCODE='23514';
  END IF;
  -- Branch before resolving fields: membership rows do not have union_id.
  IF TG_TABLE_NAME IN ('tables','tournaments') THEN
    IF TG_OP='UPDATE' AND NEW.club_id IS DISTINCT FROM OLD.club_id
       AND (EXISTS (SELECT 1 FROM public.clubs WHERE id=OLD.club_id AND asset IS DISTINCT FROM v_asset)
         OR (OLD.club_id IS NULL AND OLD.union_id IS NOT NULL AND v_asset='diamonds')) THEN
      RAISE EXCEPTION 'Game Asset Is Immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF v_asset='diamonds' THEN
    IF TG_TABLE_NAME='club_members' THEN
      IF TG_OP='INSERT' OR NEW.role IS DISTINCT FROM 'player' OR NEW.status IS DISTINCT FROM 'automatic'
         OR NEW.agent_id IS NOT NULL OR NEW.parent_agent_id IS NOT NULL
         OR coalesce(NEW.chip_balance,0)<>0 OR coalesce(NEW.credit_limit,0)<>0
         OR coalesce(NEW.credit_used,0)<>0 OR coalesce(NEW.promo_balance,0)<>0
         OR coalesce(NEW.held_chips,0)<>0 THEN
        RAISE EXCEPTION 'Diamond Membership Is Automatic And Has No Chip Wallet Or Hierarchy' USING ERRCODE='23514';
      END IF;
    ELSIF TG_TABLE_NAME='union_clubs' THEN
      RAISE EXCEPTION 'Diamond Arena Cannot Join A Union' USING ERRCODE='23514';
    ELSIF auth.uid() IS NOT NULL AND coalesce(auth.jwt()->>'role','') <> 'service_role'
       AND NOT coalesce(public.fn_is_platform_admin(),false) THEN
      RAISE EXCEPTION 'Diamond Games Require Platform Operations' USING ERRCODE='42501';
    ELSIF NEW.union_id IS NOT NULL THEN
      RAISE EXCEPTION 'Diamond Games Cannot Belong To A Union' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_poker_guard_arena_structure() OWNER TO postgres;

--
-- Name: fn_poker_guard_chip_seat(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_guard_chip_seat() RETURNS trigger
    LANGUAGE plpgsql
