--
-- Name: fn_pokeratlas_ingest_venues(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pokeratlas_ingest_venues(p_rows jsonb, p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  r record;
  v_match_count integer;
  v_match_id integer;
begin
  if p_batch_id is null then
    raise exception 'batch id is required' using errcode = '22023';
  end if;
  if jsonb_typeof(p_rows) is distinct from 'array' then
    raise exception 'rows must be a JSON array' using errcode = '22023';
  end if;

  -- Different batches for the same source room must resolve the legacy URL
  -- alias before either can enter the slug-only validated upsert.
  for r in
    select lower(btrim(value ->> 'pokeratlas_slug')) as room_slug
      from jsonb_array_elements(p_rows)
     order by lower(btrim(value ->> 'pokeratlas_slug'))
  loop
    if r.room_slug ~ '^[a-z0-9][a-z0-9-]*$' then
      perform pg_advisory_xact_lock(
        hashtextextended('pokeratlas-room:' || r.room_slug, 0)
      );

      select count(*), min(v.id)
        into v_match_count, v_match_id
        from public.poker_venues v
       where v.canonical_venue_id is null
         and coalesce(v.is_active, true)
         and not coalesce(v.is_suppressed, false)
         and r.room_slug = any (array[
           nullif(lower(btrim(v.pokeratlas_slug)), ''),
           public.pnm_pokeratlas_room_slug(v.pokeratlas_url),
           public.pnm_pokeratlas_room_slug(v.poker_atlas_url),
           public.pnm_pokeratlas_room_slug(v.scrape_url),
           public.pnm_pokeratlas_room_slug(v.schedule_scrape_url)
         ]);

      if v_match_count > 1 then
        raise exception 'ambiguous canonical PokerAtlas room identity: %', r.room_slug
          using errcode = '23505';
      end if;

      if v_match_count = 1 then
        update public.poker_venues
           set pokeratlas_slug = r.room_slug,
               location_integrity_revision = clock_timestamp()
         where id = v_match_id
           and lower(btrim(coalesce(pokeratlas_slug, ''))) is distinct from r.room_slug;
      end if;
    end if;
  end loop;

  -- The renamed v2 function performs the complete payload/provenance checks,
  -- exact audit replay contract, atomic insert, and postcondition verification.
  return public.fn_pokeratlas_ingest_venues_slug_only_v2(p_rows, p_batch_id);
end
$_$;


ALTER FUNCTION public.fn_pokeratlas_ingest_venues(p_rows jsonb, p_batch_id uuid) OWNER TO postgres;

--
-- Name: fn_pokeratlas_ingest_venues_slug_only_v2(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pokeratlas_ingest_venues_slug_only_v2(p_rows jsonb, p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  v_row jsonb;
  v_slug text;
  v_name text;
  v_state text;
  v_country text;
  v_unknown_keys text;
  v_duplicate_input text;
  v_scrape_timestamp timestamptz;
  v_row_batch_id uuid;
  v_latitude double precision;
  v_longitude double precision;
  v_input_count integer;
  v_result_count integer;
  v_input_slugs text[] := ARRAY[]::text[];
  v_input_contract jsonb := '[]'::jsonb;
  v_inserted_slugs text[] := ARRAY[]::text[];
  v_result_rows jsonb := '[]'::jsonb;
BEGIN
  IF p_batch_id IS NULL THEN
    RAISE EXCEPTION 'batch id is required' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'rows must be a JSON array' USING ERRCODE = '22023';
  END IF;

  -- Serialize only exact replays of the same batch. Different batches still
  -- run concurrently and arbitrate shared identities through the unique index.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_batch_id::text, 0));

  v_input_count := jsonb_array_length(p_rows);
  IF v_input_count > 500 THEN
    RAISE EXCEPTION 'at most 500 PokerAtlas venues may be ingested per batch'
      USING ERRCODE = '22023';
  END IF;

  -- Validate the entire payload before the INSERT statement is reached. Any
  -- exception aborts the RPC statement and therefore the whole batch.
  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows) AS e(value) LOOP
    IF jsonb_typeof(v_row) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'every venue row must be a JSON object' USING ERRCODE = '22023';
    END IF;

    SELECT string_agg(k.key, ', ' ORDER BY k.key)
      INTO v_unknown_keys
      FROM jsonb_object_keys(v_row) AS k(key)
     WHERE k.key <> ALL (ARRAY[
       'name', 'address', 'city', 'state', 'country', 'zip', 'phone',
       'website', 'latitude', 'longitude', 'slug', 'pokeratlas_slug',
       'pokeratlas_url', 'data_quality', 'scrape_url', 'scrape_html_hash',
       'scrape_timestamp', 'scrape_source', 'scrape_batch_id', 'scrape_status'
     ]::text[]);
    IF v_unknown_keys IS NOT NULL THEN
      RAISE EXCEPTION 'unsupported PokerAtlas venue fields: %', v_unknown_keys
        USING ERRCODE = '22023';
    END IF;

    v_slug := btrim(coalesce(v_row ->> 'pokeratlas_slug', ''));
    v_name := btrim(coalesce(v_row ->> 'name', ''));
    v_state := upper(btrim(coalesce(v_row ->> 'state', '')));
    v_country := upper(replace(btrim(coalesce(v_row ->> 'country', '')), '.', ''));

    IF v_slug !~ '^[a-z0-9][a-z0-9-]*$' OR v_slug <> lower(v_slug) THEN
      RAISE EXCEPTION 'invalid canonical PokerAtlas slug: %', v_slug
        USING ERRCODE = '22023';
    END IF;
    IF v_row ->> 'slug' IS DISTINCT FROM v_slug THEN
      RAISE EXCEPTION 'directory slug must match PokerAtlas slug: %', v_slug
        USING ERRCODE = '22023';
    END IF;
    IF v_row ->> 'pokeratlas_url' IS DISTINCT FROM
       'https://www.pokeratlas.com/poker-room/' || v_slug THEN
      RAISE EXCEPTION 'PokerAtlas URL does not identify requested room: %', v_slug
        USING ERRCODE = '22023';
    END IF;
    IF v_row ->> 'scrape_url' IS DISTINCT FROM
       'https://www.pokeratlas.com/poker-room/' || v_slug THEN
      RAISE EXCEPTION 'scrape URL does not identify requested room: %', v_slug
        USING ERRCODE = '22023';
    END IF;

    IF char_length(v_name) < 3 OR char_length(v_name) > 300 THEN
      RAISE EXCEPTION 'invalid venue name for PokerAtlas slug %', v_slug
        USING ERRCODE = '22023';
    END IF;
    IF lower(v_name) LIKE ANY (ARRAY[
      '%view live info%', '%wait list registration%', '%waitlist registration%',
      '%register for wait list%', '% favorited %', '% minutes ago%', '% minute ago%'
    ]) THEN
      RAISE EXCEPTION 'activity/navigation copy cannot be a venue name: %', v_name
        USING ERRCODE = '22023';
    END IF;
    IF nullif(btrim(v_row ->> 'address'), '') IS NULL
       OR char_length(btrim(v_row ->> 'address')) > 500
       OR nullif(btrim(v_row ->> 'city'), '') IS NULL
       OR char_length(btrim(v_row ->> 'city')) > 200 THEN
      RAISE EXCEPTION 'verified address and city are required for %', v_slug
        USING ERRCODE = '22023';
    END IF;

    IF v_country NOT IN ('US', 'USA', 'UNITED STATES', 'UNITED STATES OF AMERICA') THEN
      RAISE EXCEPTION 'verified US country is required for %', v_slug
        USING ERRCODE = '22023';
    END IF;
    IF v_state <> ALL (ARRAY[
      'AL','AK','AZ','AR','CA','CO','CT','DE','FL','GA','HI','ID','IL','IN','IA',
      'KS','KY','LA','ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ',
      'NM','NY','NC','ND','OH','OK','OR','PA','RI','SC','SD','TN','TX','UT','VT',
      'VA','WA','WV','WI','WY','DC'
    ]::text[]) THEN
      RAISE EXCEPTION 'canonical two-letter US state is required for %: %', v_slug, v_state
        USING ERRCODE = '22023';
    END IF;

    IF v_row ->> 'data_quality' IS DISTINCT FROM 'scraped_verified'
       OR v_row ->> 'scrape_source' IS DISTINCT FROM 'pokeratlas'
       OR v_row ->> 'scrape_status' IS DISTINCT FROM 'ready' THEN
      RAISE EXCEPTION 'invalid PokerAtlas provenance labels for %', v_slug
        USING ERRCODE = '22023';
    END IF;
    IF coalesce(v_row ->> 'scrape_html_hash', '') !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'valid source HTML hash is required for %', v_slug
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_scrape_timestamp := (v_row ->> 'scrape_timestamp')::timestamptz;
      v_row_batch_id := (v_row ->> 'scrape_batch_id')::uuid;
    EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
      RAISE EXCEPTION 'invalid scrape timestamp or batch id for %', v_slug
        USING ERRCODE = '22023';
    END;
    IF v_scrape_timestamp IS NULL OR v_scrape_timestamp > now() + interval '5 minutes'
       OR v_row_batch_id IS DISTINCT FROM p_batch_id THEN
      RAISE EXCEPTION 'scrape provenance does not match batch for %', v_slug
        USING ERRCODE = '22023';
    END IF;

    IF (v_row ? 'latitude') <> (v_row ? 'longitude') THEN
      RAISE EXCEPTION 'latitude and longitude must be supplied together for %', v_slug
        USING ERRCODE = '22023';
    END IF;
    IF v_row ? 'latitude' THEN
      BEGIN
        v_latitude := (v_row ->> 'latitude')::double precision;
        v_longitude := (v_row ->> 'longitude')::double precision;
      EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RAISE EXCEPTION 'invalid coordinates for %', v_slug USING ERRCODE = '22023';
      END;
      IF v_latitude NOT BETWEEN -90 AND 90 OR v_longitude NOT BETWEEN -180 AND 180 THEN
        RAISE EXCEPTION 'coordinates outside valid range for %', v_slug
          USING ERRCODE = '22023';
      END IF;
    END IF;
  END LOOP;

  SELECT string_agg(d.slug, ', ' ORDER BY d.slug)
    INTO v_duplicate_input
    FROM (
      SELECT lower(btrim(value ->> 'pokeratlas_slug')) AS slug
        FROM jsonb_array_elements(p_rows)
       GROUP BY lower(btrim(value ->> 'pokeratlas_slug'))
      HAVING count(*) > 1
    ) AS d;
  IF v_duplicate_input IS NOT NULL THEN
    RAISE EXCEPTION 'duplicate PokerAtlas slugs in one batch: %', v_duplicate_input
      USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(array_agg(lower(btrim(value ->> 'pokeratlas_slug')) ORDER BY
                            lower(btrim(value ->> 'pokeratlas_slug'))), ARRAY[]::text[])
    INTO v_input_slugs
    FROM jsonb_array_elements(p_rows);

  SELECT coalesce(
           jsonb_agg(value ORDER BY lower(btrim(value ->> 'pokeratlas_slug'))),
           '[]'::jsonb
         )
    INTO v_input_contract
    FROM jsonb_array_elements(p_rows);

  WITH input_rows AS (
    SELECT value AS row
      FROM jsonb_array_elements(p_rows)
  ), inserted AS (
    INSERT INTO public.poker_venues (
      name, address, city, state, country, zip, phone, website,
      latitude, longitude, slug, pokeratlas_slug, pokeratlas_url,
      data_quality, scrape_url, scrape_html_hash, scrape_timestamp,
      scrape_source, scrape_batch_id, scrape_status
    )
    SELECT
      btrim(row ->> 'name'),
      btrim(row ->> 'address'),
      btrim(row ->> 'city'),
      upper(btrim(row ->> 'state')),
      'US',
      nullif(btrim(row ->> 'zip'), ''),
      nullif(btrim(row ->> 'phone'), ''),
      nullif(btrim(row ->> 'website'), ''),
      CASE WHEN row ? 'latitude' THEN (row ->> 'latitude')::double precision END,
      CASE WHEN row ? 'longitude' THEN (row ->> 'longitude')::double precision END,
      row ->> 'slug',
      row ->> 'pokeratlas_slug',
      row ->> 'pokeratlas_url',
      'scraped_verified',
      row ->> 'scrape_url',
      row ->> 'scrape_html_hash',
      (row ->> 'scrape_timestamp')::timestamptz,
      'pokeratlas',
      p_batch_id,
      'ready'
    FROM input_rows
    ON CONFLICT ((lower(btrim(pokeratlas_slug))))
      WHERE nullif(btrim(pokeratlas_slug), '') IS NOT NULL
        AND canonical_venue_id IS NULL
    DO NOTHING
    RETURNING lower(btrim(pokeratlas_slug)) AS normalized_slug
  )
  SELECT coalesce(array_agg(normalized_slug ORDER BY normalized_slug), ARRAY[]::text[])
    INTO v_inserted_slugs
    FROM inserted;

  SELECT count(*)::integer,
         coalesce(
           jsonb_agg(
             jsonb_build_object(
               'id', pv.id,
               'pokeratlas_slug', lower(btrim(pv.pokeratlas_slug)),
               'canonical_venue_id', pv.canonical_venue_id
             ) ORDER BY lower(btrim(pv.pokeratlas_slug))
           ),
           '[]'::jsonb
         )
    INTO v_result_count, v_result_rows
    FROM public.poker_venues AS pv
   WHERE lower(btrim(pv.pokeratlas_slug)) = ANY (v_input_slugs)
     AND pv.canonical_venue_id IS NULL
     AND coalesce(pv.is_active, true)
     AND NOT coalesce(pv.is_suppressed, false);

  IF v_result_count <> v_input_count THEN
    RAISE EXCEPTION 'postcondition failed: only %/% PokerAtlas identities resolved',
      v_result_count, v_input_count USING ERRCODE = 'P0001';
  END IF;

  -- Use the batch UUID as the immutable aggregate-audit ID. Replaying the same
  -- batch cannot create duplicate audit rows; reusing it with different input
  -- is rejected below.
  INSERT INTO public.data_audit_log (
    id, table_name, record_id, action, new_data, scrape_proof,
    batch_id, agent_id, created_at
  ) VALUES (
    p_batch_id,
    'poker_venues',
    'batch:' || p_batch_id::text,
    'INSERT',
    jsonb_build_object(
      'input_count', v_input_count,
      'inserted_count', cardinality(v_inserted_slugs),
      'existing_count', v_input_count - cardinality(v_inserted_slugs),
      'input_slugs', to_jsonb(v_input_slugs),
      'input_rows', v_input_contract
    ),
    jsonb_build_object('source', 'pokeratlas', 'contract', 2),
    p_batch_id,
    'scripts/ingest_missing_pa_venues.py',
    now()
  )
  ON CONFLICT (id) DO NOTHING;

  IF NOT EXISTS (
    SELECT 1
      FROM public.data_audit_log AS a
     WHERE a.id = p_batch_id
       AND a.table_name = 'poker_venues'
       AND a.record_id = 'batch:' || p_batch_id::text
       AND a.batch_id = p_batch_id
       AND a.agent_id = 'scripts/ingest_missing_pa_venues.py'
       AND a.new_data -> 'input_slugs' = to_jsonb(v_input_slugs)
       AND a.new_data -> 'input_rows' = v_input_contract
       AND a.scrape_proof = jsonb_build_object('source', 'pokeratlas', 'contract', 2)
  ) THEN
    RAISE EXCEPTION 'batch id was already used for a different audit contract'
      USING ERRCODE = '23505';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'batch_id', p_batch_id,
    'input_count', v_input_count,
    'inserted_count', cardinality(v_inserted_slugs),
    'existing_count', v_input_count - cardinality(v_inserted_slugs),
    'input_slugs', to_jsonb(v_input_slugs),
    'inserted_slugs', to_jsonb(v_inserted_slugs),
    'venues', v_result_rows
  );
END
$_$;


ALTER FUNCTION public.fn_pokeratlas_ingest_venues_slug_only_v2(p_rows jsonb, p_batch_id uuid) OWNER TO postgres;

--
-- Name: fn_policy_function_grant_gaps(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_policy_function_grant_gaps() RETURNS TABLE(table_name text, policy_name text, fn_name text, fn_args text, role_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  WITH pol AS (
    SELECT p.tablename, p.policyname, p.roles,
           coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '') AS expr
    FROM pg_policies p
    WHERE p.schemaname = 'public'
  ),
  called AS (
    -- Generous on purpose. A false positive costs one line of triage; a false
    -- negative costs another 44-table outage. Anything that is not a real
    -- function in `public` fails to join below and drops out.
    SELECT pol.tablename, pol.policyname, pol.roles, lower(m[1]) AS fn_name
    FROM pol, LATERAL regexp_matches(pol.expr, '([a-zA-Z_][a-zA-Z0-9_]*)\s*\(', 'g') AS m
  ),
  resolved AS (
    SELECT DISTINCT c.tablename, c.policyname, c.roles, c.fn_name,
           pr.oid AS fn_oid,
           pg_get_function_identity_arguments(pr.oid) AS fn_args
    FROM called c
    JOIN pg_proc pr      ON pr.proname = c.fn_name
    JOIN pg_namespace n  ON n.oid = pr.pronamespace AND n.nspname = 'public'
  ),
  expanded AS (
    SELECT r.tablename, r.policyname, r.fn_name, r.fn_args, r.fn_oid,
           unnest(r.roles) AS role_name
    FROM resolved r
  )
  SELECT e.tablename::text, e.policyname::text, e.fn_name::text,
         e.fn_args::text, e.role_name::text
  FROM expanded e
  -- `public` as a policy target means every role, and EXECUTE defaults to
  -- PUBLIC, so it is the case that cannot silently break.
  WHERE e.role_name <> 'public'
    AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = e.role_name)
    AND NOT has_function_privilege(e.role_name, e.fn_oid, 'EXECUTE')
  ORDER BY 1, 2, 3, 5;
$$;


ALTER FUNCTION public.fn_policy_function_grant_gaps() OWNER TO postgres;

--
-- Name: fn_pps_backfill_batch(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pps_backfill_batch(p_batch integer DEFAULT 10000) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_state record;
  v_id uuid; v_ts timestamptz;
  v_n integer := 0;
BEGIN
  IF NOT pg_try_advisory_lock(hashtext('pps-backfill')) THEN
    RETURN -1;
  END IF;

  BEGIN
    SELECT * INTO v_state FROM _pps_backfill_state WHERE id;
    IF v_state.done THEN
      BEGIN
        PERFORM cron.unschedule('pps-backfill');
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
      PERFORM pg_advisory_unlock(hashtext('pps-backfill'));
      RETURN 0;
    END IF;

    FOR v_id, v_ts IN
      SELECT id, created_at FROM hand_history
       WHERE (created_at, id) > (v_state.last_created, v_state.last_id)
         AND created_at < v_state.cutoff
       ORDER BY created_at, id
       LIMIT p_batch
    LOOP
      BEGIN
        PERFORM fn_process_hand_position_stats(v_id);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
      v_n := v_n + 1;
    END LOOP;

    IF v_n = 0 THEN
      UPDATE _pps_backfill_state SET done = true, updated_at = now() WHERE id;
      BEGIN
        PERFORM cron.unschedule('pps-backfill');
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    ELSE
      UPDATE _pps_backfill_state
         SET last_created = v_ts, last_id = v_id, processed = processed + v_n, updated_at = now()
       WHERE id;
    END IF;

    PERFORM pg_advisory_unlock(hashtext('pps-backfill'));
    RETURN v_n;
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_advisory_unlock(hashtext('pps-backfill'));
    RAISE;
  END;
END;
$$;


ALTER FUNCTION public.fn_pps_backfill_batch(p_batch integer) OWNER TO postgres;

--
-- Name: fn_prepare_tournament_place_obligations(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prepare_tournament_place_obligations(p_tournament_id uuid, p_source text DEFAULT 'engine.atomicPlaceSettlement'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_t                    record;
  v_batch                public.tournament_place_settlement_batches%ROWTYPE;
  v_existing             public.tournament_obligations%ROWTYPE;
  v_source               text := COALESCE(NULLIF(btrim(p_source), ''), 'engine.atomicPlaceSettlement');
  v_struct               jsonb := '[]'::jsonb;
  v_trimmed              jsonb := '[]'::jsonb;
  v_plan                 jsonb := '[]'::jsonb;
  v_plan_fingerprint     text;
  v_field_count          integer := 0;
  v_position_count       integer := 0;
  v_distinct_positions   integer := 0;
  v_min_position         integer := 0;
  v_max_position         integer := 0;
  v_winner_count         integer := 0;
  v_winner_place_one     integer := 0;
  v_nonterminal_count    integer := 0;
  v_missing_bust_time    integer := 0;
  v_canonical_mismatches integer := 0;
  v_expected_count       integer := 0;
  v_actual_count         integer := 0;
  v_open_count           integer := 0;
  v_conflicts            integer := 0;
  v_holders              integer := 0;
  v_last_place           integer := 0;
  v_total_bp             bigint := 0;
  v_pool_cents           bigint := 0;
  v_remaining_cents      bigint := 0;
  v_expected_cents       bigint := 0;
  v_expected_total_cents bigint := 0;
  v_player_prize_cents   bigint := 0;
  v_seeded_paid          numeric := 0;
  v_seeded_total_cents   bigint := 0;
  v_required_unpaid_cents bigint := 0;
  v_total_required_unpaid_cents bigint := 0;
  v_escrow_balance       numeric := 0;
  v_escrow_enforced      boolean := false;
  v_escrow_found         boolean := false;
  v_wrong_recipients     integer := 0;
  v_bubble_user          uuid;
  v_bubble_holders       integer := 0;
  v_bubble_obligations   integer := 0;
  v_bubble_matching      integer := 0;
  v_bubble_owed          numeric := 0;
  v_bubble_paid          numeric := 0;
  v_bubble_evidence      numeric := 0;
  v_bubble_evidence_exists boolean := false;
  v_bubble_required      boolean := false;
  v_bubble_contract_required boolean := false;
  v_bubble_obligation_id uuid;
  v_bubble_source        text;
  v_bubble_settled_at    timestamptz;
  v_bubble_unpaid_cents  bigint := 0;
  v_bubble_needs_insert  boolean := false;
  v_actual_total         numeric := 0;
  v_actual_fingerprint   text;
  v_holder               uuid;
  v_holder_club          uuid;
  v_normalized           jsonb;
  v_write_failure        text;
  v_write_state          text;
  r                      record;
BEGIN
  IF p_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_id_required',
                              'retryable', false);
  END IF;

  SELECT t.id, t.name, t.status, round(COALESCE(t.prize_pool, 0), 2) AS prize_pool,
         round(COALESCE(t.guaranteed_prize, 0), 2) AS guaranteed_prize,
         COALESCE(t.prize_pool_finalized, false) AS prize_pool_finalized,
         t.payout_structure, t.variant, t.tournament_type, t.satellite_target_id,
         t.spin_multiplier, COALESCE(t.bubble_protection, false) AS bubble_protection,
         round(COALESCE(t.buy_in_amount, 0), 2) AS buy_in_amount
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found',
                              'retryable', false);
  END IF;
  IF lower(COALESCE(v_t.variant, '')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type, '')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'satellite_has_its_own_settlement',
                              'retryable', false);
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id AND p.source = 'final_table_deal'
  ) OR EXISTS (
    SELECT 1 FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'final_table_deal'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'final_table_deal_has_its_own_settlement',
                              'retryable', false);
  END IF;
  IF COALESCE(v_t.status, '') NOT IN ('COMPLETING', 'COMPLETED') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_completing',
                              'status', v_t.status, 'retryable', false);
  END IF;
  IF NOT v_t.prize_pool_finalized
     OR v_t.prize_pool + 0.005 < v_t.guaranteed_prize THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'prize_pool_is_not_funded_and_finalized',
                              'prize_pool', v_t.prize_pool,
                              'guaranteed_prize', v_t.guaranteed_prize,
                              'prize_pool_finalized', v_t.prize_pool_finalized,
                              'retryable', false);
  END IF;

  /* Normalization is part of the database money door, not merely an engine
     convention. A caller cannot skip the result RPC, publish a contiguous but
     chronologically false ladder, and have the batch freeze/pay it. The nested
     call takes the same tournament/player locks and moves no money. */
  v_normalized := public.fn_normalize_tournament_final_standings(p_tournament_id);
  IF NOT COALESCE((v_normalized->>'ok')::boolean, false) THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'final_standings_normalization_failed',
      'normalization_reason', v_normalized->>'reason',
      'detail', v_normalized->>'detail',
      'retryable', COALESCE((v_normalized->>'retryable')::boolean, false));
  END IF;

  /* Serialize result edits already in flight. New registrations are rejected
     by the tournament lifecycle once status is COMPLETING. */
  PERFORM 1
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
   ORDER BY tp.id
   FOR UPDATE;

  SELECT count(*), count(tp.position), count(DISTINCT tp.position),
         COALESCE(min(tp.position), 0), COALESCE(max(tp.position), 0),
         count(*) FILTER (WHERE tp.status = 'winner'),
         count(*) FILTER (WHERE tp.status = 'winner' AND tp.position = 1),
         count(*) FILTER (WHERE tp.status NOT IN ('winner', 'eliminated')),
         count(*) FILTER (WHERE tp.status = 'eliminated' AND tp.eliminated_at IS NULL)
    INTO v_field_count, v_position_count, v_distinct_positions,
         v_min_position, v_max_position, v_winner_count,
         v_winner_place_one, v_nonterminal_count, v_missing_bust_time
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;

  IF v_field_count = 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_has_no_players',
                              'retryable', false);
  END IF;
  IF v_position_count <> v_field_count OR v_distinct_positions <> v_field_count
     OR v_min_position <> 1 OR v_max_position <> v_field_count
     OR v_winner_count <> 1 OR v_winner_place_one <> 1
     OR v_nonterminal_count <> 0 OR v_missing_bust_time <> 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'standings_are_not_final_unique_and_terminal',
                              'players', v_field_count, 'ranked', v_position_count,
                              'distinct_positions', v_distinct_positions,
                              'min_position', v_min_position,
                              'max_position', v_max_position,
                              'winners', v_winner_count,
                              'winner_at_place_one', v_winner_place_one,
                              'nonterminal_players', v_nonterminal_count,
                              'eliminated_without_time', v_missing_bust_time,
                              'retryable', false);
  END IF;

  WITH eliminated AS (
    SELECT tp.id,
           v_field_count - (row_number() OVER (
             ORDER BY tp.eliminated_at ASC, tp.id ASC
           ))::integer + 1 AS canonical_position
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id AND tp.status = 'eliminated'
  )
  SELECT count(*) INTO v_canonical_mismatches
    FROM eliminated e
    JOIN public.tournament_players tp ON tp.id = e.id
   WHERE tp.position IS DISTINCT FROM e.canonical_position;
  IF v_canonical_mismatches <> 0 THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'standings_are_not_in_canonical_bust_order',
                              'mismatches', v_canonical_mismatches,
                              'retryable', false);
  END IF;

  v_pool_cents := round(v_t.prize_pool * 100)::bigint;

  IF v_pool_cents > 0 THEN
    BEGIN
      /* A Spin's drawn tier outranks its creation-time placeholder. This is
         the same source used by resolvePayoutStructure in the engine. */
      IF lower(COALESCE(v_t.variant, '')) = 'spin'
         OR upper(COALESCE(v_t.tournament_type, '')) = 'SPIN' THEN
        IF v_t.spin_multiplier IS NULL OR v_t.spin_multiplier <= 0 THEN
          RETURN jsonb_build_object('ok', false,
                                    'reason', 'spin_multiplier_is_not_persisted',
                                    'retryable', false);
        END IF;
        SELECT l.structure INTO v_struct
          FROM public.spin_payout_ladder l
         WHERE l.multiplier = v_t.spin_multiplier;
        IF NOT FOUND THEN
          RETURN jsonb_build_object('ok', false,
                                    'reason', 'spin_multiplier_has_no_canonical_ladder',
                                    'spin_multiplier', v_t.spin_multiplier,
                                    'retryable', false);
        END IF;
      ELSE
        v_struct := public.fn_safe_jsonb_array(v_t.payout_structure);
      END IF;
      IF jsonb_array_length(v_struct) = 0 OR EXISTS (
        SELECT 1
          FROM jsonb_array_elements(v_struct) e
         WHERE jsonb_typeof(e) <> 'object'
            OR COALESCE(e->>'place', '') !~ '^[1-9][0-9]*$'
            OR COALESCE(e->>'percentage', '') !~ '^[0-9]+([.][0-9]+)?$'
            OR (e->>'percentage')::numeric < 0
      ) THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'payout_structure_is_invalid',
                                  'retryable', false);
      END IF;

      SELECT COALESCE(jsonb_agg(e ORDER BY (e->>'place')::integer), '[]'::jsonb)
        INTO v_trimmed
        FROM jsonb_array_elements(v_struct) e
       WHERE (e->>'place')::integer <= v_field_count;

      SELECT count(*), count(DISTINCT (e->>'place')::integer),
             COALESCE(min((e->>'place')::integer), 0),
             COALESCE(max((e->>'place')::integer), 0),
             COALESCE(sum(round((e->>'percentage')::numeric * 100)::bigint), 0)
        INTO v_expected_count, v_conflicts, v_position_count, v_last_place, v_total_bp
        FROM jsonb_array_elements(v_trimmed) e;

      IF v_expected_count = 0 OR v_conflicts <> v_expected_count
         OR v_position_count <> 1 OR v_last_place <> v_expected_count
         OR v_total_bp <= 0 THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'payout_places_are_not_contiguous',
                                  'places', v_expected_count, 'last_place', v_last_place,
                                  'retryable', false);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'payout_structure_is_invalid',
                                'detail', SQLERRM, 'retryable', false);
    END;

    v_remaining_cents := v_pool_cents;
    FOR r IN
      SELECT (e->>'place')::integer AS place,
             round((e->>'percentage')::numeric * 100)::bigint AS bp
        FROM jsonb_array_elements(v_trimmed) e
       ORDER BY (e->>'place')::integer
    LOOP
      IF r.place = v_last_place THEN
        v_expected_cents := GREATEST(v_remaining_cents, 0);
      ELSE
        v_expected_cents := GREATEST(
          LEAST(v_remaining_cents, round(v_pool_cents * r.bp::numeric / v_total_bp)::bigint), 0);
      END IF;
      v_remaining_cents := v_remaining_cents - v_expected_cents;

      SELECT count(*), (array_agg(tp.user_id ORDER BY tp.id))[1],
             (array_agg(tp.club_id ORDER BY tp.id))[1],
             COALESCE(max(round(COALESCE(tp.prize, 0) * 100)::bigint), 0)
        INTO v_holders, v_holder, v_holder_club, v_player_prize_cents
        FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id AND tp.position = r.place;

      IF v_holders <> 1 OR v_holder IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'payout_place_has_no_unique_holder',
                                  'place', r.place, 'holders', v_holders,
                                  'retryable', false);
      END IF;
      IF v_player_prize_cents <> v_expected_cents THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'recorded_prize_disagrees_with_structure',
                                  'place', r.place,
                                  'recorded', v_player_prize_cents / 100.0,
                                  'expected', v_expected_cents / 100.0,
                                  'retryable', false);
      END IF;

      v_plan := v_plan || jsonb_build_array(jsonb_build_object(
        'place', r.place, 'user_id', v_holder, 'club_id', v_holder_club,
        'cents', v_expected_cents));
      v_expected_total_cents := v_expected_total_cents + v_expected_cents;
    END LOOP;
  ELSE
    /* A zero-pool event has no place money. It still gets a durable empty
       header so the universal completion gate can distinguish proof from an
       omitted plan. */
    v_expected_count := 0;
    IF EXISTS (
      SELECT 1 FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id
         AND round(COALESCE(tp.prize, 0) * 100)::bigint <> 0
    ) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'zero_pool_has_recorded_prizes',
                                'retryable', false);
    END IF;
  END IF;

  IF v_expected_total_cents <> v_pool_cents THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'structure_does_not_allocate_the_pool',
                              'allocated', v_expected_total_cents / 100.0,
                              'prize_pool', v_pool_cents / 100.0,
                              'retryable', false);
  END IF;

  SELECT count(*) INTO v_conflicts
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND round(COALESCE(tp.prize, 0) * 100)::bigint > 0
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_plan) p
        WHERE (p->>'place')::integer = tp.position
     );
  IF v_conflicts > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'recorded_prize_is_outside_structure',
                              'rows', v_conflicts, 'retryable', false);
  END IF;

  v_plan_fingerprint := md5(v_plan::text);

  SELECT * INTO v_batch
    FROM public.tournament_place_settlement_batches b
   WHERE b.tournament_id = p_tournament_id
   FOR UPDATE;
  IF FOUND AND (
       v_batch.mode <> 'structure'
       OR v_batch.plan_fingerprint <> v_plan_fingerprint
       OR v_batch.place_count <> v_expected_count
       OR round(v_batch.amount_owed * 100)::bigint <> v_expected_total_cents
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'prepared_plan_is_immutable',
                              'existing_fingerprint', v_batch.plan_fingerprint,
                              'proposed_fingerprint', v_plan_fingerprint,
                              'retryable', false);
  END IF;

  FOR r IN
    SELECT (p->>'place')::integer AS place,
           (p->>'user_id')::uuid AS user_id,
           (p->>'cents')::bigint AS cents
      FROM jsonb_array_elements(v_plan) p
     ORDER BY (p->>'place')::integer
  LOOP
    SELECT round(COALESCE(sum(tpo.amount), 0), 2)
      INTO v_seeded_paid
      FROM public.tournament_payouts tpo
     WHERE tpo.tournament_id = p_tournament_id
       AND tpo.position = r.place
       AND tpo.user_id = r.user_id
       AND (tpo.source IN ('structure', 'reconcile', 'hu_shortfall',
                           'late_reg_adjustment', 'clawback', 'spin_backpay',
                           'overlay_backpay')
            OR public.fn_tournament_payout_key_is_place_evidence(
                 tpo.tournament_id, tpo.idempotency_key));

    v_seeded_total_cents := v_seeded_total_cents
                            + round(v_seeded_paid * 100)::bigint;

    SELECT count(*) INTO v_wrong_recipients
      FROM (
        SELECT tpo.user_id
          FROM public.tournament_payouts tpo
         WHERE tpo.tournament_id = p_tournament_id
           AND tpo.position = r.place
           AND tpo.user_id IS DISTINCT FROM r.user_id
           AND (tpo.source IN ('structure', 'reconcile', 'hu_shortfall',
                               'late_reg_adjustment', 'clawback', 'spin_backpay',
                               'overlay_backpay')
                OR public.fn_tournament_payout_key_is_place_evidence(
                     tpo.tournament_id, tpo.idempotency_key))
         GROUP BY tpo.user_id
        HAVING abs(round(sum(tpo.amount), 2)) > 0.005
      ) wrong;

    SELECT * INTO v_existing
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'place' AND o.place = r.place
     FOR UPDATE;

    IF v_wrong_recipients > 0 THEN
      RETURN jsonb_build_object('ok', false,
                                'reason', 'legacy_place_paid_to_wrong_player',
                                'place', r.place, 'expected_user_id', r.user_id,
                                'wrong_recipients', v_wrong_recipients,
                                'retryable', false);
    END IF;

    IF v_seeded_paid < -0.005
       OR v_seeded_paid > r.cents / 100.0 + 0.005
       OR (FOUND AND abs(round(v_existing.amount_paid, 2) - v_seeded_paid) > 0.005)
       OR (FOUND AND v_existing.amount_paid > r.cents / 100.0 + 0.005)
       OR (FOUND AND v_existing.amount_owed > r.cents / 100.0 + 0.005)
       OR (FOUND AND v_existing.amount_paid > 0
                    AND v_existing.user_id IS DISTINCT FROM r.user_id) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'legacy_place_conflicts_with_plan',
                                'place', r.place, 'user_id', r.user_id,
                                'expected', r.cents / 100.0,
                                'payout_rows_paid', v_seeded_paid,
                                'retryable', false);
    END IF;
  END LOOP;

  v_required_unpaid_cents := v_expected_total_cents - v_seeded_total_cents;
  IF v_required_unpaid_cents < 0 THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'legacy_place_payments_exceed_plan',
                              'paid', v_seeded_total_cents / 100.0,
                              'plan', v_expected_total_cents / 100.0,
                              'retryable', false);
  END IF;

  /* Evidence for a paid place that the frozen ladder does not contain is not
     ignorable history: allocating the entire pool again would overpay the
     event. Net a historical positive row against any matching clawback, then
     refuse every non-zero position/user group outside the plan (including a
     NULL position). */
  SELECT count(*) INTO v_conflicts
    FROM (
      SELECT tpo.position, tpo.user_id
        FROM public.tournament_payouts tpo
       WHERE tpo.tournament_id = p_tournament_id
         AND (tpo.source IN ('structure', 'reconcile', 'hu_shortfall',
                             'late_reg_adjustment', 'clawback', 'spin_backpay',
                             'overlay_backpay')
              OR public.fn_tournament_payout_key_is_place_evidence(
                   tpo.tournament_id, tpo.idempotency_key))
         AND NOT EXISTS (
           SELECT 1 FROM jsonb_array_elements(v_plan) p
            WHERE (p->>'place')::integer = tpo.position
         )
       GROUP BY tpo.position, tpo.user_id
      HAVING abs(round(sum(tpo.amount), 2)) > 0.005
    ) unexpected_paid_place;
  IF v_conflicts > 0 THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'legacy_paid_place_is_outside_plan',
                              'rows', v_conflicts, 'retryable', false);
  END IF;

  SELECT count(*) INTO v_conflicts
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_plan) p
        WHERE (p->>'place')::integer = o.place
     );
  IF v_conflicts > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unexpected_legacy_place_obligation',
                              'rows', v_conflicts, 'retryable', false);
  END IF;

  /* Bubble Protection spends the same enforced prize bank. Derive its exact
     holder only after the entry window is closed, the pool/ladder is finalized
     and the full standings have been normalized. The eliminated result is the
     durable event: creating the zero-paid obligation in this same prepare
     transaction closes the old result-write -> HTTP-obligation gap without
     guessing from a provisional open-registration position. */
  SELECT EXISTS (
           SELECT 1 FROM public.tournament_obligations o
            WHERE o.tournament_id = p_tournament_id
              AND o.kind = 'bubble_protection'
         ) OR EXISTS (
           SELECT 1
             FROM public.tournament_payouts p
            WHERE p.tournament_id = p_tournament_id
              AND p.source = 'bubble_protection'
         )
    INTO v_bubble_evidence_exists;
  v_bubble_required := v_t.bubble_protection OR v_bubble_evidence_exists;
  v_bubble_contract_required := v_bubble_required
    AND v_expected_count > 0 AND v_field_count > v_expected_count;

  /* A mutable display flag is not allowed to erase durable money evidence.
     Conversely, a flagged short field in which every entrant is already paid
     has no stone bubble and owes no refund. Evidence with no coherent contract
     is corruption and must be repaired explicitly, never silently ignored. */
  IF (v_bubble_evidence_exists OR v_bubble_contract_required)
     AND v_t.buy_in_amount <= 0 THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'bubble_protection_evidence_has_no_valid_contract',
      'buy_in_amount', v_t.buy_in_amount, 'paid_places', v_expected_count,
      'field_size', v_field_count, 'retryable', false);
  END IF;
  IF v_bubble_evidence_exists AND NOT v_bubble_contract_required THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'bubble_protection_evidence_has_no_valid_contract',
      'buy_in_amount', v_t.buy_in_amount, 'paid_places', v_expected_count,
      'field_size', v_field_count, 'retryable', false);
  END IF;

  IF v_bubble_contract_required THEN
    SELECT count(*), (array_agg(tp.user_id ORDER BY tp.id))[1]
      INTO v_bubble_holders, v_bubble_user
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position = v_expected_count + 1;
    IF v_bubble_holders <> 1 OR v_bubble_user IS NULL THEN
      RETURN jsonb_build_object('ok', false,
                                'reason', 'bubble_protection_holder_is_not_proven',
                                'bubble_place', v_expected_count + 1,
                                'holders', v_bubble_holders,
                                'retryable', false);
    END IF;

    SELECT count(*),
           count(*) FILTER (WHERE o.user_id = v_bubble_user AND o.place IS NULL),
           COALESCE(max(o.amount_owed) FILTER (
             WHERE o.user_id = v_bubble_user AND o.place IS NULL), 0),
           COALESCE(max(o.amount_paid) FILTER (
             WHERE o.user_id = v_bubble_user AND o.place IS NULL), 0)
      INTO v_bubble_obligations, v_bubble_matching, v_bubble_owed, v_bubble_paid
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'bubble_protection';

    SELECT round(COALESCE(sum(p.amount), 0), 2)
      INTO v_bubble_evidence
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.user_id = v_bubble_user AND p.position IS NULL
       AND p.source = 'bubble_protection';

    IF v_bubble_obligations = 0 AND NOT v_bubble_evidence_exists THEN
      v_bubble_obligation_id := gen_random_uuid();
      v_bubble_source := 'engine.atomicPlaceSettlement';
      v_bubble_owed := v_t.buy_in_amount;
      v_bubble_paid := 0;
      v_bubble_settled_at := NULL;
      v_bubble_needs_insert := true;
    ELSIF v_bubble_obligations <> 1 OR v_bubble_matching <> 1 THEN
      RETURN jsonb_build_object('ok', false,
                                'reason', 'bubble_protection_obligation_is_not_exact',
                                'bubble_place', v_expected_count + 1,
                                'user_id', v_bubble_user,
                                'expected', v_t.buy_in_amount,
                                'amount_owed', v_bubble_owed,
                                'amount_paid', v_bubble_paid,
                                'payout_evidence', v_bubble_evidence,
                                'retryable', false);
    END IF;

    IF NOT v_bubble_needs_insert THEN
      SELECT o.id, o.source, o.amount_owed, o.amount_paid, o.settled_at
        INTO v_bubble_obligation_id, v_bubble_source,
             v_bubble_owed, v_bubble_paid, v_bubble_settled_at
        FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'bubble_protection'
         AND o.place IS NULL AND o.user_id = v_bubble_user
       FOR UPDATE;
    END IF;

    IF COALESCE(v_bubble_source, '') NOT IN ('engine.eliminatePlayer', 'engine.atomicPlaceSettlement')
       OR abs(v_bubble_owed - v_t.buy_in_amount) > 0.005
       OR v_bubble_paid < -0.005 OR v_bubble_paid > v_bubble_owed + 0.005
       OR abs(v_bubble_paid - v_bubble_evidence) > 0.005
       OR (v_bubble_paid + 0.005 >= v_bubble_owed
           AND v_bubble_settled_at IS NULL)
       OR (v_bubble_paid + 0.005 < v_bubble_owed
           AND v_bubble_settled_at IS NOT NULL) THEN
      RETURN jsonb_build_object('ok', false,
                                'reason', 'bubble_protection_obligation_is_not_exact',
                                'bubble_place', v_expected_count + 1,
                                'user_id', v_bubble_user,
                                'expected', v_t.buy_in_amount,
                                'amount_owed', v_bubble_owed,
                                'amount_paid', v_bubble_paid,
                                'payout_evidence', v_bubble_evidence,
                                'source', v_bubble_source,
                                'retryable', false);
    END IF;

    SELECT count(*) INTO v_conflicts
      FROM (
        SELECT p.position, p.user_id
          FROM public.tournament_payouts p
         WHERE p.tournament_id = p_tournament_id
           AND p.source = 'bubble_protection'
           AND (p.position IS NOT NULL OR p.user_id IS DISTINCT FROM v_bubble_user)
         GROUP BY p.position, p.user_id
        HAVING abs(round(sum(p.amount), 2)) > 0.005
      ) unexpected_bubble;
    IF v_conflicts > 0 THEN
      RETURN jsonb_build_object('ok', false,
                                'reason', 'bubble_protection_evidence_conflicts',
                                'rows', v_conflicts, 'retryable', false);
    END IF;
    v_bubble_unpaid_cents := round((v_bubble_owed - v_bubble_paid) * 100)::bigint;
  END IF;

  v_total_required_unpaid_cents := v_required_unpaid_cents + v_bubble_unpaid_cents;

  /* The finalized flag is not money. Before freezing any obligation that will
     move chips, lock the enforced tournament escrow and prove that its live
     prize balance covers the complete place + Bubble amount still unpaid. */
  IF v_total_required_unpaid_cents > 0 THEN
    SELECT e.enforced, round(COALESCE(e.prize_balance, 0), 2)
      INTO v_escrow_enforced, v_escrow_balance
      FROM public.tournament_escrow e
     WHERE e.tournament_id = p_tournament_id
     FOR UPDATE;
    v_escrow_found := FOUND;
    IF NOT v_escrow_found OR NOT v_escrow_enforced
       OR round(v_escrow_balance * 100)::bigint < v_total_required_unpaid_cents THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'prize_escrow_is_not_funded',
        'required_unpaid', v_total_required_unpaid_cents / 100.0,
        'place_unpaid', v_required_unpaid_cents / 100.0,
        'bubble_unpaid', v_bubble_unpaid_cents / 100.0,
        'escrow_available', CASE WHEN v_escrow_found THEN v_escrow_balance ELSE NULL END,
        'escrow_enforced', CASE WHEN v_escrow_found THEN v_escrow_enforced ELSE NULL END,
        'retryable', false);
    END IF;
  END IF;

  IF v_batch.tournament_id IS NOT NULL AND (
       v_batch.bubble_contract_required IS DISTINCT FROM v_bubble_contract_required
       OR v_batch.bubble_obligation_id IS DISTINCT FROM v_bubble_obligation_id
       OR v_batch.bubble_user_id IS DISTINCT FROM v_bubble_user
       OR v_batch.bubble_source IS DISTINCT FROM v_bubble_source
       OR abs(v_batch.bubble_amount_owed - v_bubble_owed) > 0.005
       OR v_batch.bubble_amount_paid_before > v_bubble_paid + 0.005
       OR (v_t.status <> 'COMPLETED'
           AND abs(v_batch.bubble_amount_paid_before - v_bubble_paid) > 0.005)
       OR (v_t.status <> 'COMPLETED'
           AND round(v_batch.escrow_required * 100)::bigint
               <> v_total_required_unpaid_cents)
  ) THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'prepared_bubble_contract_is_immutable',
                              'retryable', false);
  END IF;

  /* A prepare replay reads the frozen restart record; it never rewrites place
     rows after the header exists. */
  IF v_batch.tournament_id IS NOT NULL THEN
    SELECT count(*), round(COALESCE(sum(o.amount_owed), 0), 2),
           count(*) FILTER (WHERE o.amount_paid + 0.005 < o.amount_owed),
           md5(COALESCE(jsonb_agg(jsonb_build_object(
             'place', o.place, 'user_id', o.user_id,
             'club_id', tp.club_id,
             'cents', round(o.amount_owed * 100)::bigint)
             ORDER BY o.place), '[]'::jsonb)::text)
      INTO v_actual_count, v_actual_total, v_open_count, v_actual_fingerprint
      FROM public.tournament_obligations o
      JOIN public.tournament_players tp
        ON tp.tournament_id = o.tournament_id
       AND tp.position = o.place AND tp.user_id = o.user_id
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place';

    IF v_actual_count <> v_expected_count
       OR abs(v_actual_total - v_expected_total_cents / 100.0) > 0.005
       OR v_actual_fingerprint <> v_plan_fingerprint THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'prepared_batch_no_longer_matches_plan',
                                'paid', 0, 'retryable', false);
    END IF;
    IF v_batch.escrow_available + 0.005 < v_batch.escrow_required THEN
      RETURN jsonb_build_object('ok', false,
                                'reason', 'prepared_batch_has_no_funding_proof',
                                'retryable', false);
    END IF;
    IF v_t.status = 'COMPLETED' THEN
      IF v_batch.settled_at IS NULL OR v_open_count <> 0
         OR (v_batch.bubble_contract_required
             AND v_bubble_paid + 0.005 < v_bubble_owed) THEN
        RETURN jsonb_build_object('ok', false,
                                  'reason', 'completed_event_has_no_exact_atomic_batch',
                                  'paid', 0, 'retryable', false);
      END IF;
      RETURN jsonb_build_object('ok', true, 'tournament_id', p_tournament_id,
                                'places', v_expected_count, 'amount_owed', v_actual_total,
                                'bubble_obligation_id', v_bubble_obligation_id,
                                'paid', 0, 'already_completed', true,
                                'retryable', false);
    END IF;
    RETURN jsonb_build_object('ok', true, 'tournament_id', p_tournament_id,
                              'places', v_expected_count,
                              'amount_owed', v_expected_total_cents / 100.0,
                              'plan_fingerprint', v_plan_fingerprint,
                              'bubble_obligation_id', v_bubble_obligation_id,
                              'record', 'tournament_obligations',
                              'already_prepared', true, 'retryable', false);
  ELSIF v_t.status = 'COMPLETED' THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'completed_event_has_no_exact_atomic_batch',
                              'paid', 0, 'retryable', false);
  END IF;

  BEGIN
    IF v_bubble_needs_insert THEN
      INSERT INTO public.tournament_obligations
        (id, tournament_id, kind, place, user_id, amount_owed, amount_paid,
         source, settled_at)
      VALUES
        (v_bubble_obligation_id, p_tournament_id, 'bubble_protection', NULL,
         v_bubble_user, v_bubble_owed, 0, v_bubble_source, NULL);
    END IF;

    FOR r IN
      SELECT (p->>'place')::integer AS place,
             (p->>'user_id')::uuid AS user_id,
             (p->>'cents')::bigint AS cents
        FROM jsonb_array_elements(v_plan) p
       ORDER BY (p->>'place')::integer
    LOOP
      SELECT round(COALESCE(sum(tpo.amount), 0), 2)
        INTO v_seeded_paid
        FROM public.tournament_payouts tpo
       WHERE tpo.tournament_id = p_tournament_id
         AND tpo.position = r.place
         AND tpo.user_id = r.user_id
         AND (tpo.source IN ('structure', 'reconcile', 'hu_shortfall',
                             'late_reg_adjustment', 'clawback', 'spin_backpay',
                             'overlay_backpay')
              OR public.fn_tournament_payout_key_is_place_evidence(
                   tpo.tournament_id, tpo.idempotency_key));

      INSERT INTO public.tournament_obligations
        (tournament_id, kind, place, user_id, amount_owed, amount_paid,
         source, settled_at)
      VALUES
        (p_tournament_id, 'place', r.place, r.user_id, r.cents / 100.0,
         v_seeded_paid, v_source,
         CASE WHEN v_seeded_paid + 0.005 >= r.cents / 100.0 THEN now() ELSE NULL END)
      ON CONFLICT (tournament_id, kind, place) WHERE place IS NOT NULL
      DO UPDATE SET
        user_id = CASE
                    WHEN public.tournament_obligations.amount_paid = 0
                      THEN EXCLUDED.user_id
                    ELSE public.tournament_obligations.user_id
                  END,
        amount_owed = EXCLUDED.amount_owed,
        amount_paid = EXCLUDED.amount_paid,
        source = v_source,
        updated_at = now(),
        settled_at = CASE
          WHEN EXCLUDED.amount_paid + 0.005 >= EXCLUDED.amount_owed
            THEN COALESCE(public.tournament_obligations.settled_at, now())
          ELSE NULL
        END;
    END LOOP;

    SELECT count(*), round(COALESCE(sum(o.amount_owed), 0), 2),
           count(*) FILTER (WHERE o.amount_paid + 0.005 < o.amount_owed),
           md5(COALESCE(jsonb_agg(jsonb_build_object(
             'place', o.place, 'user_id', o.user_id,
             'club_id', tp.club_id,
             'cents', round(o.amount_owed * 100)::bigint)
             ORDER BY o.place), '[]'::jsonb)::text)
      INTO v_actual_count, v_actual_total, v_open_count, v_actual_fingerprint
      FROM public.tournament_obligations o
      JOIN public.tournament_players tp
        ON tp.tournament_id = o.tournament_id
       AND tp.position = o.place AND tp.user_id = o.user_id
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place';

    IF v_actual_count <> v_expected_count
       OR abs(v_actual_total - v_expected_total_cents / 100.0) > 0.005
       OR v_actual_fingerprint <> v_plan_fingerprint THEN
      RAISE EXCEPTION USING MESSAGE = 'the written obligation set does not match its frozen plan',
                            ERRCODE = '23514';
    END IF;

    INSERT INTO public.tournament_place_settlement_batches
      (tournament_id, mode, plan_fingerprint, place_count, amount_owed,
       escrow_required, escrow_available,
       bubble_contract_required, bubble_obligation_id, bubble_user_id,
       bubble_source, bubble_amount_owed, bubble_amount_paid_before, source)
    VALUES
      (p_tournament_id, 'structure', v_plan_fingerprint, v_expected_count,
       v_expected_total_cents / 100.0, v_total_required_unpaid_cents / 100.0,
       CASE WHEN v_total_required_unpaid_cents > 0 THEN v_escrow_balance ELSE 0 END,
       v_bubble_contract_required, v_bubble_obligation_id, v_bubble_user,
       v_bubble_source, v_bubble_owed, v_bubble_paid,
       v_source);
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_write_failure = MESSAGE_TEXT,
                            v_write_state = RETURNED_SQLSTATE;
  END;

  IF v_write_failure IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'prepare_write_aborted',
                              'detail', v_write_failure, 'sqlstate', v_write_state,
                              'retryable', v_write_state IN ('40001', '40P01', '55P03'));
  END IF;

  RETURN jsonb_build_object('ok', true, 'tournament_id', p_tournament_id,
                            'places', v_expected_count,
                            'amount_owed', v_expected_total_cents / 100.0,
                            'plan_fingerprint', v_plan_fingerprint,
                            'bubble_obligation_id', v_bubble_obligation_id,
                            'record', 'tournament_obligations',
                            'retryable', false);
END;
$_$;


ALTER FUNCTION public.fn_prepare_tournament_place_obligations(p_tournament_id uuid, p_source text) OWNER TO postgres;

--
-- Name: FUNCTION fn_prepare_tournament_place_obligations(p_tournament_id uuid, p_source text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_prepare_tournament_place_obligations(p_tournament_id uuid, p_source text) IS 'Freezes the complete published place structure into exact, committed obligations plus a completeness fingerprint. Moves no chips.';


--
-- Name: fn_preview_club_join(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_preview_club_join(p_identifier text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_uid uuid := auth.uid(); v_value text := btrim(COALESCE(p_identifier,'')); v_club record; v_status text; v_attempts integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000'; END IF;
  IF v_value='' THEN RAISE EXCEPTION 'A club code is required' USING ERRCODE='22023'; END IF;
  SELECT count(*) INTO v_attempts FROM public.rate_limits
   WHERE user_id=v_uid AND action='club_join_preview' AND created_at>now()-interval '10 minutes';
  IF v_attempts>=30 THEN RAISE EXCEPTION 'Too many code lookups. Please wait a few minutes.'; END IF;
  INSERT INTO public.rate_limits(user_id,action) VALUES(v_uid,'club_join_preview');
  SELECT c.id,c.club_id,c.slug,c.name,c.description,c.logo_url,c.avatar_url,
         COALESCE(c.member_count,0) member_count,COALESCE(c.requires_approval,false) requires_approval
    INTO v_club FROM public.clubs c
     WHERE (v_value ~ '^[0-9]{5,6}$' AND c.club_id=v_value::integer)
      OR (v_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND c.id=v_value::uuid)
      OR lower(COALESCE(c.slug,''))=lower(v_value)
   LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('found',false); END IF;
  SELECT status INTO v_status FROM public.club_members WHERE club_id=v_club.id AND user_id=v_uid;
  RETURN jsonb_build_object(
    'found',true,'id',v_club.id,'club_id',v_club.club_id,'slug',v_club.slug,
    'name',v_club.name,'description',v_club.description,
    'logo_url',COALESCE(v_club.logo_url,v_club.avatar_url),
    'member_count',v_club.member_count,'requires_approval',v_club.requires_approval,
    'membership_status',v_status
  );
END $_$;


ALTER FUNCTION public.fn_preview_club_join(p_identifier text) OWNER TO postgres;

--
-- Name: fn_probe_table_candidate(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_probe_table_candidate(p_viewer uuid) RETURNS TABLE(table_id uuid, table_name text, club_id uuid, hands_10m bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH viewer_clubs AS (
    SELECT m.club_id
    FROM club_members m
    WHERE m.user_id = p_viewer
      AND m.status IN ('active', 'approved')
  ),
  recent AS (
    SELECT h.table_id, count(*) AS hands_10m
    FROM hand_history h
    WHERE h.created_at > now() - interval '10 minutes'
    GROUP BY h.table_id
    HAVING count(*) >= 3
  ),
  seated_humans AS (
    SELECT DISTINCT s.table_id
    FROM table_seats s
    JOIN profiles p ON p.id = s.user_id
    WHERE s.left_at IS NULL
      AND NOT COALESCE(p.is_horse, false)
  )
  SELECT t.id, t.name, t.club_id, r.hands_10m
  FROM tables t
  JOIN recent r ON r.table_id = t.id
  JOIN viewer_clubs vc ON vc.club_id = t.club_id
  WHERE t.status = 'running'
    AND t.tournament_id IS NULL
    AND COALESCE(t.is_deleted, false) = false
    AND COALESCE(t.restrict_observers, false) = false
    AND NOT EXISTS (SELECT 1 FROM seated_humans sh WHERE sh.table_id = t.id)
  ORDER BY random()
  LIMIT 1;
$$;


ALTER FUNCTION public.fn_probe_table_candidate(p_viewer uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_probe_table_candidate(p_viewer uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_probe_table_candidate(p_viewer uuid) IS 'Realtime Phase 6: one running, observer-friendly, human-free cash table in a club the given viewer belongs to, that has dealt at least 3 hands in the last 10 minutes, chosen at random. Every condition mirrors a gate the viewer will meet at the WebSocket upgrade, so a zero result means "nothing to probe" and never "the probe is not allowed in". Used by the table-socket-probe.';


--
-- Name: fn_process_hand_position_stats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_process_hand_position_stats(p_hand_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_h record;
BEGIN
  SELECT players, actions, winners INTO v_h
    FROM public.hand_history WHERE id=p_hand_id;
  IF NOT FOUND THEN RETURN; END IF;
  PERFORM public.fn_process_hand_position_stats(v_h.players,v_h.actions,v_h.winners);
END;
$$;


ALTER FUNCTION public.fn_process_hand_position_stats(p_hand_id uuid) OWNER TO postgres;

--
-- Name: fn_process_hand_position_stats(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_process_hand_position_stats(p_players jsonb, p_actions jsonb, p_winners jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order uuid[] := '{}';
  v_pre jsonb[] := '{}';
  v_uid uuid;
  v_n int;
  v_i int;
  v_pos text;
  v_raises int;
  v_player_raised boolean;
  v_vpip int; v_pfr int; v_3bet int; v_fold3 int;
  v_won int; v_profit numeric;
  a jsonb;
  v_raise_count_before int;
BEGIN
  IF p_players IS NULL OR jsonb_typeof(p_players) <> 'array' THEN
    RETURN;
  END IF;

  IF p_actions IS NOT NULL AND jsonb_typeof(p_actions) = 'array' THEN
    v_pre := ARRAY(
      SELECT e
        FROM jsonb_array_elements(p_actions) e
       WHERE e->>'stage' = 'preflop'
         AND (e->>'userId') IS NOT NULL
    );
  END IF;

  FOREACH a IN ARRAY v_pre LOOP
    v_uid := (a->>'userId')::uuid;
    IF NOT v_uid = ANY(v_order) THEN
      v_order := v_order || v_uid;
    END IF;
  END LOOP;

  v_n := array_length(v_order, 1);
  IF v_n IS NULL OR v_n < 2 THEN RETURN; END IF;

  FOR v_i IN 1..v_n LOOP
    v_uid := v_order[v_i];
    v_pos := CASE v_n - v_i
      WHEN 0 THEN 'BB'
      WHEN 1 THEN 'SB'
      WHEN 2 THEN 'BTN'
      WHEN 3 THEN 'CO'
      WHEN 4 THEN 'MP'
      ELSE 'UTG' END;

    v_vpip := 0; v_pfr := 0; v_3bet := 0; v_fold3 := 0;
    v_raises := 0; v_player_raised := false;

    FOREACH a IN ARRAY v_pre LOOP
      v_raise_count_before := v_raises;
      IF a->>'action' IN ('raise','bet') THEN v_raises := v_raises + 1; END IF;

      IF (a->>'userId')::uuid = v_uid THEN
        IF a->>'action' IN ('call','raise','bet')
           AND COALESCE((a->>'amount')::numeric, 0) > 0 THEN
          v_vpip := 1;
        END IF;
        IF a->>'action' IN ('raise','bet') THEN
          v_pfr := 1;
          IF v_raise_count_before >= 1 THEN v_3bet := 1; END IF;
          v_player_raised := true;
        END IF;
        IF a->>'action' = 'fold' AND v_player_raised
           AND v_raise_count_before >= 2 THEN
          v_fold3 := 1;
        END IF;
      END IF;
    END LOOP;

    SELECT COALESCE(sum((w->>'amount')::numeric), 0) INTO v_profit
      FROM jsonb_array_elements(COALESCE(p_winners, '[]'::jsonb)) w
     WHERE (w->>'userId')::uuid = v_uid;
    v_won := CASE WHEN v_profit > 0 THEN 1 ELSE 0 END;

    v_profit := v_profit - COALESCE((
      SELECT sum(mx) FROM (
        SELECT max(COALESCE((a2->>'amount')::numeric, 0)) AS mx
          FROM jsonb_array_elements(p_actions) a2
         WHERE (a2->>'userId')::uuid = v_uid
           AND a2->>'action' IN ('call','raise','bet')
         GROUP BY a2->>'stage'
      ) s), 0);

    INSERT INTO public.player_position_stats AS pps
      (user_id, position, hands_played, vpip_count, pfr_count, three_bet_count,
       fold_to_three_bet_count, hands_won, total_profit, updated_at)
    VALUES (v_uid, v_pos, 1, v_vpip, v_pfr, v_3bet, v_fold3, v_won,
            round(v_profit, 2), now())
    ON CONFLICT (user_id, position) DO UPDATE SET
      hands_played = pps.hands_played + 1,
      vpip_count = pps.vpip_count + EXCLUDED.vpip_count,
      pfr_count = pps.pfr_count + EXCLUDED.pfr_count,
      three_bet_count = pps.three_bet_count + EXCLUDED.three_bet_count,
      fold_to_three_bet_count = pps.fold_to_three_bet_count + EXCLUDED.fold_to_three_bet_count,
      hands_won = pps.hands_won + EXCLUDED.hands_won,
      total_profit = pps.total_profit + EXCLUDED.total_profit,
      updated_at = now();
  END LOOP;
END;
$$;


ALTER FUNCTION public.fn_process_hand_position_stats(p_players jsonb, p_actions jsonb, p_winners jsonb) OWNER TO postgres;

--
-- Name: fn_profiles_ungranted_client_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_profiles_ungranted_client_columns() RETURNS TABLE(column_name text, data_type text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'information_schema'
    AS $$
    SELECT c.column_name::text, c.data_type::text
    FROM information_schema.columns c
    WHERE c.table_schema = 'public'
      AND c.table_name  = 'profiles'
      -- Deliberately withheld from the browser. Keep this list short and
      -- justified; everything on it is PII, a payment identifier, or an
      -- anti-fraud signal the player must not be able to read about themselves.
      AND c.column_name NOT IN ('email', 'phone', 'stripe_customer_id', 'is_farming_flagged')
      AND NOT has_column_privilege('authenticated', 'public.profiles', c.column_name, 'SELECT')
    ORDER BY 1
$$;


ALTER FUNCTION public.fn_profiles_ungranted_client_columns() OWNER TO postgres;

--
-- Name: FUNCTION fn_profiles_ungranted_client_columns(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_profiles_ungranted_client_columns() IS 'Columns on public.profiles that the authenticated role cannot SELECT and that are not on the deliberate deny-list. Non-empty means a client feature is silently reading null. See supabase/migrations/20260822143000_arena_avatar_url_grants.sql.';


--
-- Name: fn_project_hand_side_effects(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_project_hand_side_effects(p_hand_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_table_id uuid;
  v_hand_number bigint;
  v_history_table_id uuid;
  v_history_hand_number bigint;
  v_commit_table_id uuid;
  v_commit_hand_number bigint;
  v_post_commit jsonb;
BEGIN
  IF NOT (current_user IN ('postgres','service_role')) THEN
    RAISE EXCEPTION 'fn_project_hand_side_effects is engine/service only';
  END IF;

  /* LOCK ORDER 1: read the exact durable scope without claiming the outbox.
     Another worker may finish it after this read; the implementation claim
     below remains the sole authority to apply projections. */
  SELECT o.table_id, o.hand_number
    INTO v_table_id, v_hand_number
    FROM public.hand_projection_outbox o
   WHERE o.hand_id = p_hand_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'not_pending',
      'hand_id', p_hand_id
    );
  END IF;

  SELECT h.table_id, h.hand_number
    INTO v_history_table_id, v_history_hand_number
    FROM public.hand_history h
   WHERE h.id = p_hand_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'pending hand projection has no hand history row: %', p_hand_id;
  END IF;

  SELECT c.table_id, c.hand_number
    INTO v_commit_table_id, v_commit_hand_number
    FROM public.hand_atomic_commits c
   WHERE c.hand_id = p_hand_id;
  IF NOT FOUND
     OR v_history_table_id IS DISTINCT FROM v_table_id
     OR v_history_hand_number IS DISTINCT FROM v_hand_number
     OR v_commit_table_id IS DISTINCT FROM v_table_id
     OR v_commit_hand_number IS DISTINCT FROM v_hand_number THEN
    RAISE EXCEPTION
      'pending hand projection scope disagrees with immutable hand receipt: %',
      p_hand_id;
  END IF;

  /* LOCK ORDER 2: every path that can consume the frozen post-commit envelope
     owns this per-table advisory lock before reaching any player/stat row. */
  PERFORM pg_advisory_xact_lock(
    hashtextextended('hand-post-commit:' || v_table_id::text, 0)
  );

  /* LOCK ORDER 3: consume the exact stored envelope, or leave the outbox row
     untouched. predecessor_pending is returned unchanged so the event-driven
     worker preserves causal order. Any thrown validation/hash error aborts the
     transaction and is intentionally not converted into success. */
  v_post_commit :=
    public.fn_ca_process_hand_post_commit_obligations(p_hand_id);
  IF COALESCE((v_post_commit->>'ok')::boolean, false) IS NOT TRUE
     AND COALESCE(v_post_commit->>'reason', '') <> 'legacy_no_obligations' THEN
    RETURN COALESCE(v_post_commit, '{}'::jsonb) || jsonb_build_object(
      'projection_applied', false,
      'hand_id', p_hand_id
    );
  END IF;

  /* LOCK ORDER 4: projection serialisation comes after post-commit. The
     preserved implementation next claims this exact outbox row FOR UPDATE,
     checks projection predecessors, applies the unchanged projections, and
     deletes through a0_finish_hand_post_commit_obligations. The trigger's
     second processor call is an idempotent completed/legacy assertion while
     this transaction still owns both advisory locks. */
  PERFORM pg_advisory_xact_lock(
    hashtextextended('hand-projection:' || v_table_id::text, 0)
  );

  RETURN public.fn_project_hand_side_effects_after_post_commit_20260908(
    p_hand_id
  );
END;
$$;


ALTER FUNCTION public.fn_project_hand_side_effects(p_hand_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_project_hand_side_effects(p_hand_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_project_hand_side_effects(p_hand_id uuid) IS 'Consumes one accepted-hand post-commit envelope before claiming and applying its ordered hand projections. Lock order is hand-post-commit, hand-projection, exact outbox row.';


--
-- Name: fn_project_hand_side_effects_after_post_commit_20260908(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_project_hand_side_effects_after_post_commit_20260908(p_hand_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_h public.hand_history%ROWTYPE;
  v_club uuid;
  v_date date;
  v_tourney boolean;
  v_bb numeric;
BEGIN
  IF NOT (current_user IN ('postgres','service_role')) THEN
    RAISE EXCEPTION 'fn_project_hand_side_effects is engine/service only';
  END IF;

  -- The durable outbox row is also the claim.  Locking it keeps the additive
  -- projections and its DELETE in one transaction: a crash rolls both back;
  -- a concurrent worker waits, then finds no row and cannot run them twice.
  SELECT h.* INTO v_h
    FROM public.hand_projection_outbox o
    JOIN public.hand_history h ON h.id=o.hand_id
   WHERE o.hand_id=p_hand_id
   FOR UPDATE OF o;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','not_pending','hand_id',p_hand_id);
  END IF;

  -- One table's club-member projection carries prior-stack state.  Serialise
  -- it and refuse to leapfrog an earlier durable hand from that table.
  PERFORM pg_advisory_xact_lock(hashtextextended('hand-projection:'||v_h.table_id::text,0));
  IF EXISTS (
    SELECT 1 FROM public.hand_projection_outbox earlier
     WHERE earlier.table_id=v_h.table_id
       AND earlier.hand_number<v_h.hand_number
  ) THEN
    RETURN jsonb_build_object('ok',false,'reason','predecessor_pending');
  END IF;

  SELECT t.club_id, (t.tournament_id IS NOT NULL)
    INTO v_club, v_tourney
    FROM public.tables t WHERE t.id=v_h.table_id;
  v_tourney := COALESCE(v_tourney,false) OR (v_h.tournament_id IS NOT NULL);
  v_date := (v_h.created_at AT TIME ZONE 'UTC')::date;

  -- Projection 1: club member/table/day state.  This is the current live
  -- trigger body, with NEW replaced by the immutable hand row selected above.
  IF v_club IS NOT NULL THEN
    WITH pl AS (
      SELECT DISTINCT ON (p->>'userId')
             (p->>'userId')::uuid AS uid, (p->>'stack')::numeric AS stack
        FROM jsonb_array_elements(coalesce(v_h.players,'[]'::jsonb)) p
       WHERE (p->>'userId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
         AND (p->>'stack') IS NOT NULL
    ), wn AS (
      SELECT (w->>'userId')::uuid AS uid, sum((w->>'amount')::numeric) AS won
        FROM jsonb_array_elements(coalesce(v_h.winners,'[]'::jsonb)) w
       WHERE (w->>'userId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       GROUP BY 1
    ), base AS (
      SELECT pl.uid, pl.stack, coalesce(wn.won,0) AS won, st.last_stack,
             (st.last_stack IS NOT NULL AND st.last_hand_number IS NOT NULL
              AND v_h.hand_number IS NOT NULL AND NOT EXISTS (
                SELECT 1 FROM public.hand_history h2
                 WHERE h2.table_id=v_h.table_id
                   AND h2.hand_number>st.last_hand_number
                   AND h2.hand_number<v_h.hand_number)) AS adjacent
        FROM pl
        LEFT JOIN wn ON wn.uid=pl.uid
        LEFT JOIN public.club_member_table_state st
          ON st.table_id=v_h.table_id AND st.user_id=pl.uid
    ), agg AS (
      SELECT count(*) AS seated,
             count(*) FILTER (WHERE last_stack IS NOT NULL) AS with_prior,
             coalesce(sum(stack-last_stack) FILTER (WHERE last_stack IS NOT NULL),0) AS dsum
        FROM base
    ), calc AS (
      SELECT b.uid,b.won,
             CASE WHEN b.last_stack IS NOT NULL THEN b.stack-b.last_stack ELSE 0 END AS delta,
             CASE WHEN a.seated=a.with_prior
                  THEN abs(a.dsum+coalesce(v_h.rake_amount,0)+coalesce(v_h.bbj_amount,0))<0.005
                  ELSE b.adjacent AND (b.stack-b.last_stack)<=b.won+0.001 END AS attributable
        FROM base b CROSS JOIN agg a
    )
    INSERT INTO public.club_member_daily_stats AS s
      (club_id,table_id,user_id,stat_date,hands_played,hands_attributed,hands_won,
       total_won,profit,biggest_pot_won,biggest_pot,topup_total)
    SELECT v_club,v_h.table_id,calc.uid,v_date,1,
           CASE WHEN v_tourney THEN 0 WHEN calc.attributable THEN 1 ELSE 0 END,
           CASE WHEN calc.won>0 THEN 1 ELSE 0 END,
           CASE WHEN v_tourney THEN 0 ELSE calc.won END,
           CASE WHEN v_tourney THEN 0 WHEN calc.attributable THEN calc.delta ELSE 0 END,
           CASE WHEN v_tourney THEN 0 ELSE calc.won END,
           CASE WHEN v_tourney THEN 0 ELSE coalesce(v_h.pot_size,0) END,
           CASE WHEN v_tourney THEN 0
                WHEN NOT calc.attributable AND calc.delta>calc.won THEN calc.delta-calc.won
                ELSE 0 END
      FROM calc
    ON CONFLICT (club_id,table_id,user_id,stat_date) DO UPDATE SET
      hands_played=s.hands_played+1,
      hands_attributed=s.hands_attributed+EXCLUDED.hands_attributed,
      hands_won=s.hands_won+EXCLUDED.hands_won,
      total_won=s.total_won+EXCLUDED.total_won,
      profit=s.profit+EXCLUDED.profit,
      biggest_pot_won=greatest(s.biggest_pot_won,EXCLUDED.biggest_pot_won),
      biggest_pot=greatest(s.biggest_pot,EXCLUDED.biggest_pot),
      topup_total=s.topup_total+EXCLUDED.topup_total,
      updated_at=now();

    INSERT INTO public.club_member_table_state AS st
      (table_id,user_id,last_stack,last_hand_number)
    SELECT DISTINCT ON (p->>'userId')
           v_h.table_id,(p->>'userId')::uuid,(p->>'stack')::numeric,v_h.hand_number
      FROM jsonb_array_elements(coalesce(v_h.players,'[]'::jsonb)) p
     WHERE (p->>'userId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       AND (p->>'stack') IS NOT NULL
    ON CONFLICT (table_id,user_id) DO UPDATE SET
      last_stack=EXCLUDED.last_stack,
      last_hand_number=EXCLUDED.last_hand_number,
      updated_at=now();

    INSERT INTO public.club_hand_daily_shard AS d
      (club_id,stat_date,shard,hands,rake,bbj,pot_total)
    VALUES (
      v_club,v_date,(pg_backend_pid()%16)::smallint,1,
      coalesce(v_h.rake_amount,0),coalesce(v_h.bbj_amount,0),coalesce(v_h.pot_size,0))
    ON CONFLICT (club_id,stat_date,shard) DO UPDATE SET
      hands=d.hands+1,
      rake=d.rake+EXCLUDED.rake,
      bbj=d.bbj+EXCLUDED.bbj,
      pot_total=d.pot_total+EXCLUDED.pot_total,
      updated_at=now();
  END IF;

  -- Projection 2: legacy player_stats fold/winnings totals (cash only).
  IF v_h.tournament_id IS NULL
     AND v_club IS NOT NULL
     AND jsonb_typeof(v_h.players)='array'
     AND jsonb_array_length(v_h.players)>0 THEN
    v_bb := greatest(coalesce(v_h.big_blind,0),0);
    WITH seated AS (
      SELECT DISTINCT (pl->>'userId') AS uid
        FROM jsonb_array_elements(v_h.players) pl
       WHERE (pl->>'userId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), won AS (
      SELECT (w->>'userId') AS uid,sum((w->>'amount')::numeric) AS amt
        FROM jsonb_array_elements(
          CASE WHEN jsonb_typeof(v_h.winners)='array' THEN v_h.winners ELSE '[]'::jsonb END) w
       WHERE (w->>'userId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         AND coalesce((w->>'amount')::numeric,0)>0
       GROUP BY 1
    )
    INSERT INTO public.player_stats AS ps
      (id,user_id,club_id,hands_dealt,sum_big_blind,total_winnings,updated_at)
    SELECT gen_random_uuid(),s.uid::uuid,v_club,1,v_bb,coalesce(wo.amt,0),now()
      FROM seated s LEFT JOIN won wo ON wo.uid=s.uid
     WHERE EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=s.uid::uuid)
    ON CONFLICT (user_id,club_id) DO UPDATE SET
      hands_dealt=ps.hands_dealt+EXCLUDED.hands_dealt,
      sum_big_blind=ps.sum_big_blind+EXCLUDED.sum_big_blind,
      total_winnings=ps.total_winnings+EXCLUDED.total_winnings,
      updated_at=now();
  END IF;

  -- Projection 3: positional aggregates.
  PERFORM public.fn_process_hand_position_stats(v_h.players,v_h.actions,v_h.winners);

  -- Projection 4: exact per-hand stats materialisation and player index.
  INSERT INTO public.ca_hand_player_idx(user_id,created_at,hand_id)
  SELECT DISTINCT (pl->>'userId')::uuid,v_h.created_at,v_h.id
    FROM jsonb_array_elements(coalesce(v_h.players,'[]'::jsonb)) pl
   WHERE pl->>'userId' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  ON CONFLICT DO NOTHING;

  INSERT INTO public.ca_hand_player_stat AS hs (
    user_id,hand_id,created_at,is_cash,tournament_id,game_variant,
    big_blind,small_blind,n_players,seat_position,my_blind,won_amt,is_winner,
    invested_actions,aggro_cnt,call_cnt,vpip,pfr,folded,three_bet,
    three_bet_opp,faced_three_bet,folded_to_three_bet,cbet_opp,cbet_made,
    showdown,hand_secs,profit)
  SELECT
    f.user_id,f.hand_id,f.created_at,f.is_cash,f.tournament_id,f.game_variant,
    f.big_blind,f.small_blind,f.n_players,f.seat_position,f.my_blind,f.won_amt,f.is_winner,
    f.invested_actions,f.aggro_cnt,f.call_cnt,f.vpip,f.pfr,f.folded,f.three_bet,
    f.three_bet_opp,f.faced_three_bet,f.folded_to_three_bet,f.cbet_opp,f.cbet_made,
    f.showdown,f.hand_secs,f.profit
    FROM public.ca_hand_player_facts_one(v_h.id,NULL) f
  ON CONFLICT (user_id,hand_id) DO NOTHING;

  -- Daily Mission booking has its own durable outbox. The hand-history
  -- trigger above only inserts those rows; it never takes a player/profile
  -- lock, and this stats projector must not become a second synchronous
  -- consumer. fn_drain_daily_challenge_event_outbox owns booking exactly once.

  DELETE FROM public.hand_projection_outbox o WHERE o.hand_id=v_h.id;

  RETURN jsonb_build_object('ok',true,'hand_id',v_h.id,'hand_number',v_h.hand_number);
END;
$_$;


