--
-- Name: fn_promo_wallet_ledger(text, uuid, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_promo_wallet_ledger(p_scope text, p_scope_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_wallet text DEFAULT 'promo_wallet'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
declare
  v_actor  uuid := auth.uid();
  v_limit  int := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_offset int := greatest(coalesce(p_offset, 0), 0);
  v_entity uuid;
  v_total  bigint;
  v_rows   jsonb;
  v_in     numeric;
  v_out    numeric;
  v_totals jsonb;
  v_cp     record;
begin
  if p_scope = 'union' then
    if coalesce(auth.role(), '') <> 'service_role'
       and not public.fn_union_can_manage_wallets(p_scope_id, v_actor)
       and not exists (select 1 from union_admins ua
                        where ua.union_id = p_scope_id and ua.user_id = v_actor) then
      return jsonb_build_object('authorized', false,
        'error', 'The Union Wallet Ledger Is Restricted To Union Staff');
    end if;
    if p_wallet not in ('chip_balance', 'rake_wallet', 'bbj_wallet', 'promo_wallet',
                        'insurance_wallet', 'spin_reserve_wallet') then
      return jsonb_build_object('authorized', false, 'error', 'Unknown Union Wallet');
    end if;

    if v_offset = 0 then
      select * into v_cp from union_rake_ledger_checkpoint c where c.union_id = p_scope_id;
      if p_wallet = 'rake_wallet' and found then
        select v_cp.rows_seen + count(*),
               v_cp.credits + coalesce(sum(t.amount) filter (where t.direction = 'credit'), 0),
               v_cp.debits  + coalesce(sum(t.amount) filter (where t.direction = 'debit'), 0)
          into v_total, v_in, v_out
          from union_wallet_transactions t
         where t.union_id = p_scope_id and t.wallet = p_wallet and t.created_at > v_cp.as_of;
      else
        select count(*),
               coalesce(sum(t.amount) filter (where t.direction = 'credit'), 0),
               coalesce(sum(t.amount) filter (where t.direction = 'debit'), 0)
          into v_total, v_in, v_out
          from union_wallet_transactions t
         where t.union_id = p_scope_id and t.wallet = p_wallet;
      end if;
      v_totals := jsonb_build_object('in', round(v_in, 2), 'out', round(v_out, 2),
                                     'net', round(v_in - v_out, 2));
    else
      v_total := null;
      v_totals := null;
    end if;

    select coalesce(jsonb_agg(r), '[]'::jsonb) into v_rows
    from (
      select jsonb_build_object(
               'id', t.id,
               'created_at', t.created_at,
               'amount', round(coalesce(t.amount, 0), 2),
               'direction', case when t.direction = 'credit' then 'in' else 'out' end,
               'category', t.tx_type,
               'notes', t.notes,
               'balance_after', t.balance_after,
               'counterparty_type', case when t.club_id is not null then 'club' else null end,
               'counterparty_name', c.name,
               'actor_name', case when t.created_by is null then null else
                               coalesce(public.fn_arena_name(pa.alias, pa.username, pa.display_name,
                                        pa.first_name, pa.last_name, pa.full_name), pa.username) end
             ) as r
        from union_wallet_transactions t
        left join clubs c on c.id = t.club_id
        left join profiles pa on pa.id = t.created_by
       where t.union_id = p_scope_id and t.wallet = p_wallet
       order by t.created_at desc
       limit v_limit offset v_offset
    ) s;

    return jsonb_build_object('authorized', true, 'scope', 'union', 'wallet', p_wallet,
      'total', v_total, 'limit', v_limit, 'offset', v_offset,
      'totals', v_totals,
      'rows', v_rows);
  end if;

  if p_scope = 'club' then
    if not public.fn_can_use_club_bank(p_scope_id) then
      return jsonb_build_object('authorized', false,
        'error', 'The Club Promo Wallet Ledger Is Restricted To Owners, Co Owners, Admins And Super Agents');
    end if;
    v_entity := p_scope_id;
  elsif p_scope = 'agent' then
    if v_actor is null or not exists (
         select 1 from club_members cm
          where cm.club_id = p_scope_id and cm.user_id = v_actor
            and coalesce(cm.status, 'active') in ('active', 'approved')) then
      return jsonb_build_object('authorized', false,
        'error', 'You Do Not Hold A Promo Wallet In This Club');
    end if;
    v_entity := v_actor;
  else
    return jsonb_build_object('authorized', false, 'error', 'Unknown Ledger Scope');
  end if;

  if v_offset = 0 then
    select count(*),
           coalesce(sum(l.amount) filter (where l.to_type = 'promo_wallet' and l.to_entity_id = v_entity), 0),
           coalesce(sum(l.amount) filter (where l.from_type = 'promo_wallet' and l.from_entity_id = v_entity), 0)
      into v_total, v_in, v_out
      from chip_ledger l
     where ((l.to_type = 'promo_wallet' and l.to_entity_id = v_entity)
         or (l.from_type = 'promo_wallet' and l.from_entity_id = v_entity))
       and (p_scope = 'club' or l.club_id = p_scope_id);
    v_totals := jsonb_build_object('in', round(v_in, 2), 'out', round(v_out, 2),
                                   'net', round(v_in - v_out, 2));
  else
    v_total := null;
    v_totals := null;
  end if;

  select coalesce(jsonb_agg(r), '[]'::jsonb) into v_rows
  from (
    select jsonb_build_object(
             'id', l.id,
             'created_at', l.created_at,
             'amount', round(coalesce(l.amount, 0), 2),
             'direction', x.dir,
             'category', l.category,
             'notes', coalesce(l.notes, l.description),
             'balance_after', case when x.dir = 'in' then l.post_to_balance else l.post_from_balance end,
             'counterparty_type', x.cp_type,
             'counterparty_name',
               case
                 when pp.id is not null then coalesce(public.fn_arena_name(pp.alias, pp.username,
                        pp.display_name, pp.first_name, pp.last_name, pp.full_name), pp.username)
                 when cc.id is not null then cc.name
                 when uu.id is not null then uu.name
                 else null
               end,
             'actor_name', case when l.performed_by is null then null else
                             coalesce(public.fn_arena_name(pa.alias, pa.username, pa.display_name,
                                      pa.first_name, pa.last_name, pa.full_name), pa.username) end
           ) as r
      from chip_ledger l
      cross join lateral (
        select case when l.to_type = 'promo_wallet' and l.to_entity_id = v_entity then 'in' else 'out' end as dir,
               case when l.to_type = 'promo_wallet' and l.to_entity_id = v_entity then l.from_type else l.to_type end as cp_type,
               case when l.to_type = 'promo_wallet' and l.to_entity_id = v_entity then l.from_entity_id else l.to_entity_id end as cp_id
      ) x
      left join profiles pp on pp.id = x.cp_id
        and x.cp_type in ('player_wallet', 'agent_wallet', 'promo_wallet')
      left join clubs cc on cc.id = x.cp_id and pp.id is null
      left join unions uu on uu.id = x.cp_id and pp.id is null and cc.id is null
      left join profiles pa on pa.id = l.performed_by
     where ((l.to_type = 'promo_wallet' and l.to_entity_id = v_entity)
         or (l.from_type = 'promo_wallet' and l.from_entity_id = v_entity))
       and (p_scope = 'club' or l.club_id = p_scope_id)
     order by l.created_at desc
     limit v_limit offset v_offset
  ) s;

  return jsonb_build_object('authorized', true, 'scope', p_scope, 'wallet', 'promo_wallet',
    'total', v_total, 'limit', v_limit, 'offset', v_offset,
    'totals', v_totals,
    'rows', v_rows);
end
$$;


ALTER FUNCTION public.fn_promo_wallet_ledger(p_scope text, p_scope_id uuid, p_limit integer, p_offset integer, p_wallet text) OWNER TO postgres;

--
-- Name: FUNCTION fn_promo_wallet_ledger(p_scope text, p_scope_id uuid, p_limit integer, p_offset integer, p_wallet text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_promo_wallet_ledger(p_scope text, p_scope_id uuid, p_limit integer, p_offset integer, p_wallet text) IS 'The transaction ledger attached to a promo wallet. scope=union (any union wallet column via p_wallet), scope=club (clubs.promo_balance), scope=agent (the caller''s agents.promo_wallet_balance in that club). Newest first, paged.';


--
-- Name: fn_promo_wallet_send(uuid, uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_promo_wallet_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text DEFAULT 'player_wallet'::text, p_reason text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor          uuid := auth.uid();
  v_actor_role     text;
  v_dest           text := lower(coalesce(p_destination, 'player_wallet'));
  v_op_id          uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior          record;
  v_sender_id      uuid;
  v_sender_promo   numeric;
  v_sender_after   numeric;
  v_to_role        text;
  v_to_agent_id    uuid;
  v_to_after       numeric;
  v_tx_id          uuid;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null
     or v_actor_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only An Agent Or Club Staff May Send From A Promo Wallet');
  end if;

  select id, amount, metadata into v_prior
    from chip_transactions
   where club_id = p_club_id
     and transaction_type = 'promo_wallet_send'
     and from_user_id = v_actor
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'sender_promo_after', (v_prior.metadata ->> 'sender_promo_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric);
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false,
      'error', 'Chips Move In Hundredths At Most');
  end if;
  if p_amount > 1e9 then
    return jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Send Limit');
  end if;
  if v_dest not in ('player_wallet', 'agent_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Destination Wallet');
  end if;
  if p_to_user_id is null then
    return jsonb_build_object('success', false, 'error', 'Choose A Recipient');
  end if;
  if p_to_user_id = v_actor then
    return jsonb_build_object('success', false, 'error', 'A Promo Wallet Cannot Send To Itself');
  end if;

  if not public.fn_club_cashier_can_transact(p_club_id, v_actor, p_to_user_id) then
    return jsonb_build_object('success', false,
      'error', 'That Member Is Not In Your Downline');
  end if;

  select a.id, coalesce(a.promo_wallet_balance, 0)
    into v_sender_id, v_sender_promo
    from agents a
   where a.club_id = p_club_id and a.user_id = v_actor
   for update;
  if v_sender_id is null then
    return jsonb_build_object('success', false,
      'error', 'You Do Not Hold A Promo Wallet In This Club');
  end if;
  if v_sender_promo < p_amount then
    return jsonb_build_object('success', false, 'error', 'Insufficient Promo Wallet Balance',
      'balance', v_sender_promo, 'requested', p_amount);
  end if;

  select cm.role into v_to_role
    from club_members cm
   where cm.club_id = p_club_id
     and cm.user_id = p_to_user_id
     and coalesce(cm.status, 'active') in ('active', 'approved')
   for update;
  if v_to_role is null then
    return jsonb_build_object('success', false, 'error', 'Recipient Is Not An Active Member Of This Club');
  end if;
  if v_dest = 'agent_wallet'
     and v_to_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false,
      'error', 'Only Staff Or Agents Hold A Promo Wallet');
  end if;

  -- CHIP STANDARD 2.4 (2026-09-03): ONE `promo_send` row from the sender's
  -- promo float to the wallet that receives it, keyed and correlated on the
  -- op. The agents trigger is skipped for both promo writes: a player
  -- recipient's club_members trigger writes the row with the promo float as
  -- counterparty; an agent recipient (both sides in `agents`) gets the row
  -- posted explicitly below. Never a refusal.
  perform public.fn_ca_declare_ledger('promo_send', 'promo_wallet', v_actor, null,
    'promo_send:' || v_op_id::text, array['agents']);
  perform set_config('app.ledger_correlation', v_op_id::text, true);

  update agents
     set promo_wallet_balance = coalesce(promo_wallet_balance, 0) - p_amount,
         updated_at = now()
   where id = v_sender_id
   returning promo_wallet_balance into v_sender_after;

  if v_dest = 'player_wallet' then
    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount,
           updated_at = now()
     where club_id = p_club_id and user_id = p_to_user_id
     returning chip_balance into v_to_after;
  else
    v_to_agent_id := public.fn_ensure_agent_row(p_club_id, p_to_user_id, v_to_role);
    if v_to_agent_id is null then
      raise exception 'could not ensure agents row for % in club %', p_to_user_id, p_club_id;
    end if;
    update agents
       set promo_wallet_balance = coalesce(promo_wallet_balance, 0) + p_amount,
           updated_at = now()
     where id = v_to_agent_id
     returning promo_wallet_balance into v_to_after;
    perform set_config('app.ledger_idempotency_key', '', true);
    perform public.fn_ca_post_leg('promo_send', 'promo_wallet', v_actor, 'promo_wallet', p_to_user_id,
      p_amount, p_club_id, 'promo_send:' || v_op_id::text,
      'Promo wallet send to a downline agent promo wallet (fn_promo_wallet_send)');
  end if;

  perform set_config('app.ledger_autoskip_agents', '', true);

  insert into chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  values
    (p_club_id, v_actor, p_to_user_id, p_amount, 'promo_wallet_send',
     coalesce(nullif(btrim(p_reason), ''), 'Promo Wallet Send'),
     jsonb_build_object(
       'op_id', v_op_id,
       'destination', v_dest,
       'source', 'promo_wallet',
       'actor_role', v_actor_role,
       'recipient_role', v_to_role,
       'sender_promo_after', v_sender_after,
       'recipient_balance_after', v_to_after),
     null)
  returning id into v_tx_id;

  return jsonb_build_object(
    'success', true, 'replayed', false,
    'transaction_id', v_tx_id,
    'op_id', v_op_id,
    'amount', p_amount,
    'destination', v_dest,
    'sender_promo_after', v_sender_after,
    'recipient_balance_after', v_to_after);
exception
  when unique_violation then
    select id, amount, metadata into v_prior
      from chip_transactions
     where club_id = p_club_id
       and transaction_type = 'promo_wallet_send'
       and from_user_id = v_actor
       and metadata ->> 'op_id' = v_op_id::text
     limit 1;
    if v_prior.id is null then
      raise;
    end if;
    return jsonb_build_object(
      'success', true, 'replayed', true,
      'transaction_id', v_prior.id,
      'amount', v_prior.amount,
      'destination', v_prior.metadata ->> 'destination',
      'sender_promo_after', (v_prior.metadata ->> 'sender_promo_after')::numeric,
      'recipient_balance_after', (v_prior.metadata ->> 'recipient_balance_after')::numeric);
end
$$;


ALTER FUNCTION public.fn_promo_wallet_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_promotion_claim_takes_the_promotions_word(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_promotion_claim_takes_the_promotions_word() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_promo record;
BEGIN
  SELECT p.prize_pool, p.max_claims, p.wager_requirement, p.status,
         p.start_date, p.end_date
    INTO v_promo
    FROM public.promotions p
   WHERE p.id = NEW.promotion_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such promotion' USING ERRCODE = 'P0002';
  END IF;

  -- A claim on a promotion that is not running is refused here, not merely in
  -- the client that decided to send it.
  IF coalesce(v_promo.status, '') <> 'active'
     OR (v_promo.start_date IS NOT NULL AND v_promo.start_date > now())
     OR (v_promo.end_date IS NOT NULL AND v_promo.end_date < now()) THEN
    RAISE EXCEPTION 'that promotion is not running' USING ERRCODE = '22023';
  END IF;

  -- The client's numbers are discarded. Same formula it used, decided here.
  NEW.bonus_amount := CASE
    WHEN coalesce(v_promo.prize_pool, 0) > 0
      THEN trunc((v_promo.prize_pool * 100) / GREATEST(coalesce(v_promo.max_claims, 100), 1)) / 100
    ELSE 0
  END;
  NEW.wager_required := coalesce(v_promo.wager_requirement, 0);
  NEW.status := CASE WHEN coalesce(v_promo.wager_requirement, 0) > 0
                     THEN 'active' ELSE 'completed' END;
  NEW.wager_progress := 0;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_promotion_claim_takes_the_promotions_word() OWNER TO postgres;

--
-- Name: fn_protect_default_table(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_protect_default_table() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_other_count int;
BEGIN
  IF OLD.is_default = true THEN
    SELECT count(*) INTO v_other_count
      FROM public.commander_home_game_tables
     WHERE game_id = OLD.game_id AND id <> OLD.id;
    IF v_other_count > 0 THEN
      RAISE EXCEPTION 'CANNOT_DELETE_DEFAULT_TABLE_WITH_SIBLINGS'
        USING HINT = 'promote another table to default before deleting this one';
    END IF;
  END IF;
  RETURN OLD;
END $$;


ALTER FUNCTION public.fn_protect_default_table() OWNER TO postgres;

--
-- Name: fn_protect_profile_username_and_gate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_protect_profile_username_and_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_existing_id uuid;
BEGIN
  -- Trusted callers bypass entirely
  IF current_user IN ('postgres','service_role','supabase_admin','supabase_auth_admin') THEN
    RETURN NEW;
  END IF;

  -- Username validation: fires on INSERT (any non-empty username) or UPDATE
  -- when the username changed. All checks operate on the lowercase form so
  -- case-mixed inputs are validated correctly.
  IF TG_OP = 'INSERT' OR NEW.username IS DISTINCT FROM OLD.username THEN
    IF NEW.username IS NOT NULL AND btrim(NEW.username) <> '' THEN
      -- (1) Format
      IF lower(NEW.username) !~ '^[a-z0-9][a-z0-9_.]{2,19}$' THEN
        RAISE EXCEPTION 'Username Must Be 3-20 Characters Using Letters, Numbers, Underscores, Or Periods (No Spaces Or Special Characters).'
          USING ERRCODE = '22023';
      END IF;
      -- (2) Reserved words
      IF public.is_reserved_username(NEW.username) THEN
        RAISE EXCEPTION 'That Username Is Reserved. Pick A Different One.'
          USING ERRCODE = '22023';
      END IF;
      -- (3) Case-insensitive uniqueness - friendly message before the
      --     unique index can fire its raw 23505 error. Excludes self so a
      --     user resaving their own row (e.g. case-only change to OLD value)
      --     doesn't get rejected.
      SELECT id INTO v_existing_id FROM public.profiles
       WHERE lower(username) = lower(NEW.username)
         AND id <> NEW.id
       LIMIT 1;
      IF v_existing_id IS NOT NULL THEN
        RAISE EXCEPTION 'That Username Is Already Taken. Pick A Different One.'
          USING ERRCODE = '22023';
      END IF;
    END IF;
  END IF;

  -- Gate transition guard: false→true (or INSERT-with-true) requires all fields
  IF NEW.social_profile_completed = true 
     AND (TG_OP = 'INSERT' OR coalesce(OLD.social_profile_completed, false) = false) THEN
    IF coalesce(btrim(NEW.full_name), '') = '' THEN
      RAISE EXCEPTION 'Cannot Mark Profile Complete Without A Full Name.'
        USING ERRCODE = '22023';
    END IF;
    IF coalesce(btrim(NEW.username), '') = '' THEN
      RAISE EXCEPTION 'Cannot Mark Profile Complete Without A Username.'
        USING ERRCODE = '22023';
    END IF;
    IF length(regexp_replace(coalesce(NEW.phone, ''), '[^0-9]', '', 'g')) NOT BETWEEN 7 AND 15 THEN
      RAISE EXCEPTION 'Cannot Mark Profile Complete Without A Valid Phone Number (7-15 Digits).'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_protect_profile_username_and_gate() OWNER TO postgres;

--
-- Name: FUNCTION fn_protect_profile_username_and_gate(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_protect_profile_username_and_gate() IS 'Closes a gate-bypass hole: without this, an authenticated user could call PostgREST UPDATE directly to set social_profile_completed=true with a reserved or malformed username, skipping claim_social_profile validation. SECURITY INVOKER (NOT DEFINER) so current_user correctly identifies the caller.';


--
-- Name: fn_prove_played_spin_launch_recovery(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prove_played_spin_launch_recovery(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET row_security TO 'off'
    SET statement_timeout TO '10s'
    AS $$
WITH contract AS (
  SELECT t.id,
         t.status::text AS status,
         lower(COALESCE(t.variant, '')) AS variant,
         upper(COALESCE(t.tournament_type, '')) AS tournament_type,
         t.max_players,
         t.buy_in_amount AS buy_in,
         t.starting_chips,
         round(t.buy_in_amount * 3 * public.fn_spin_rake_rate(t.buy_in_amount), 2)
           AS expected_house_rake,
         round(t.buy_in_amount * 3
               * (1 - public.fn_spin_rake_rate(t.buy_in_amount)), 2)
           AS expected_reserve_in
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
), roster AS (
  SELECT count(*) AS roster_count,
         count(DISTINCT tp.user_id) AS roster_users,
         count(*) FILTER (WHERE tp.status = 'playing') AS active_players,
         count(*) FILTER (WHERE tp.status = 'playing' AND tp.chips > 0)
           AS positive_active_players,
         count(*) FILTER (WHERE tp.status = 'eliminated') AS eliminated_players,
         count(*) FILTER (WHERE tp.status NOT IN ('playing', 'eliminated')) AS other_players,
         count(*) FILTER (WHERE tp.chips IS NULL OR tp.chips < 0) AS invalid_stacks,
         count(*) FILTER (WHERE tp.status = 'eliminated' AND tp.chips = 0)
           AS zero_stack_eliminations,
         COALESCE(sum(tp.chips), 0) AS roster_chips,
         COALESCE(
           array_agg(tp.user_id ORDER BY tp.user_id)
             FILTER (WHERE tp.user_id IS NOT NULL),
           ARRAY[]::uuid[]
         ) AS original_player_ids,
         COALESCE(
           array_agg(tp.user_id ORDER BY tp.user_id)
             FILTER (WHERE tp.status = 'playing'),
           ARRAY[]::uuid[]
         ) AS active_player_ids
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
), entitlements AS (
  SELECT count(e.id) AS entitlement_count,
         count(DISTINCT e.user_id) AS entitlement_users,
         count(DISTINCT e.user_id) FILTER (
           WHERE EXISTS (
             SELECT 1
               FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.user_id = e.user_id
           )
         ) AS roster_entitlement_users,
         min(e.gross) AS min_gross,
         max(e.gross) AS max_gross,
         round(COALESCE(sum(e.gross), 0), 2) AS gross_total
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id = p_tournament_id
     AND e.entitlement_kind = 'wallet_charge'
     AND e.charge_category = 'tournament_buyin'
), payments AS (
  SELECT count(w.id) AS payment_count,
         count(DISTINCT w.user_id) AS paid_users,
         count(DISTINCT w.user_id) FILTER (
           WHERE EXISTS (
             SELECT 1
               FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.user_id = w.user_id
           )
         ) AS roster_paid_users,
         min(w.amount) AS min_amount,
         max(w.amount) AS max_amount,
         round(COALESCE(sum(w.amount), 0), 2) AS payment_total
    FROM public.wallet_transactions w
   WHERE w.related_entity_id = p_tournament_id
     AND w.type = 'debit'
     AND w.category = 'tournament_buyin'
), charge_evidence AS (
  SELECT count(l.id) AS source_charge_count,
         count(l.id) FILTER (
           WHERE l.tournament_id = e.tournament_id
             AND l.club_id = e.refund_wallet_club_id
             AND l.from_type = 'player_wallet'
             AND l.from_entity_id = e.user_id
             AND l.to_type = 'prize_liability'
             AND l.to_entity_id = e.tournament_id
             AND l.category = e.charge_category
             AND l.amount = e.gross
         ) AS exact_source_charges
    FROM public.tournament_refund_entitlements e
    LEFT JOIN public.chip_ledger l ON l.id = e.source_ledger_id
   WHERE e.tournament_id = p_tournament_id
     AND e.entitlement_kind = 'wallet_charge'
     AND e.charge_category = 'tournament_buyin'
), reserve_evidence AS (
  SELECT count(sr.id) FILTER (WHERE sr.kind = 'contribution') AS contribution_count,
         count(sr.id) FILTER (WHERE sr.kind = 'jackpot_draw') AS draw_count,
         (array_agg(sr.id ORDER BY sr.created_at, sr.id)
           FILTER (WHERE sr.kind = 'contribution'))[1] AS contribution_id,
         (array_agg(sr.id ORDER BY sr.created_at, sr.id)
           FILTER (WHERE sr.kind = 'jackpot_draw'))[1] AS draw_id,
         (array_agg(sr.club_id ORDER BY sr.created_at, sr.id)
           FILTER (WHERE sr.kind = 'contribution'))[1] AS contribution_owner,
         (array_agg(sr.club_id ORDER BY sr.created_at, sr.id)
           FILTER (WHERE sr.kind = 'jackpot_draw'))[1] AS draw_owner,
         min(sr.amount) FILTER (WHERE sr.kind = 'contribution') AS contribution_amount,
         min(sr.buy_in) FILTER (WHERE sr.kind = 'contribution') AS contribution_buy_in,
         min(sr.seats) FILTER (WHERE sr.kind = 'contribution') AS contribution_seats,
         min(sr.house_rake) FILTER (WHERE sr.kind = 'contribution') AS contribution_rake,
         min(sr.balance_after) FILTER (WHERE sr.kind = 'contribution')
           AS contribution_balance,
         min(sr.amount) FILTER (WHERE sr.kind = 'jackpot_draw') AS draw_amount,
         min(sr.buy_in) FILTER (WHERE sr.kind = 'jackpot_draw') AS draw_buy_in,
         min(sr.seats) FILTER (WHERE sr.kind = 'jackpot_draw') AS draw_seats,
         min(sr.multiplier) FILTER (WHERE sr.kind = 'jackpot_draw') AS draw_multiplier,
         min(sr.balance_after) FILTER (WHERE sr.kind = 'jackpot_draw') AS draw_balance,
         min(sr.created_at) FILTER (WHERE sr.kind = 'jackpot_draw') AS draw_created_at
    FROM public.spin_reserve_ledger sr
   WHERE sr.tournament_id = p_tournament_id
     AND sr.kind IN ('contribution', 'jackpot_draw')
), reserve_pool AS (
  SELECT count(p.id) AS pool_count,
         (array_agg(p.id ORDER BY p.id))[1] AS pool_id
    FROM public.spin_bonus_pools p
    CROSS JOIN reserve_evidence r
   WHERE p.club_id = r.draw_owner
), journals AS (
  SELECT count(l.id) FILTER (WHERE l.category = 'spin_entry') AS entry_journal_count,
         count(l.id) FILTER (WHERE l.category = 'spin_prize') AS draw_journal_count,
         count(l.id) FILTER (
           WHERE l.category = 'spin_entry'
             AND l.from_type = 'prize_liability'
             AND l.from_entity_id = p_tournament_id
             AND l.to_type = 'spin_reserve'
             AND l.to_entity_id = p.pool_id
             AND l.amount = c.expected_reserve_in
             AND l.post_to_balance IS NOT DISTINCT FROM r.contribution_balance
         ) AS exact_entry_journals,
         count(l.id) FILTER (
           WHERE l.category = 'spin_prize'
             AND l.from_type = 'spin_reserve'
             AND l.from_entity_id = p.pool_id
             AND l.to_type = 'prize_liability'
             AND l.to_entity_id = p_tournament_id
             AND l.amount = round(-r.draw_amount, 2)
             AND l.post_from_balance IS NOT DISTINCT FROM r.draw_balance
         ) AS exact_draw_journals
    FROM contract c
    CROSS JOIN reserve_evidence r
    CROSS JOIN reserve_pool p
    LEFT JOIN public.chip_ledger l
      ON l.tournament_id = p_tournament_id
     AND l.category IN ('spin_entry', 'spin_prize')
   GROUP BY c.expected_reserve_in, r.contribution_balance, r.draw_amount,
            r.draw_balance, p.pool_id
), table_evidence AS (
  SELECT count(t.id) AS table_count,
         count(t.id) FILTER (WHERE t.status IN ('running', 'waiting')) AS open_tables,
         (array_agg(t.id ORDER BY t.created_at, t.id)
           FILTER (WHERE t.status IN ('running', 'waiting')))[1] AS table_id,
         min(t.current_players) FILTER (WHERE t.status IN ('running', 'waiting'))
           AS current_players,
         min(t.max_players) FILTER (WHERE t.status IN ('running', 'waiting'))
           AS table_capacity
    FROM public.tables t
   WHERE t.tournament_id = p_tournament_id
), live_seats AS (
  SELECT count(s.id) AS live_seats,
         count(DISTINCT s.user_id) AS live_users,
         count(DISTINCT (s.table_id, s.seat_number)) AS live_coordinates,
         count(DISTINCT s.table_id) AS live_tables,
         count(s.id) FILTER (
           WHERE s.stack IS NULL
              OR s.stack::text IN ('NaN', 'Infinity', '-Infinity')
              OR s.stack < 0
         ) AS invalid_live_stacks,
         count(s.id) FILTER (WHERE s.stack > 0) AS positive_live_seats,
         count(s.id) FILTER (
           WHERE EXISTS (
             SELECT 1
               FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.user_id = s.user_id
                AND tp.status = 'playing'
                AND tp.table_id = s.table_id
                AND tp.seat_number = s.seat_number
                AND tp.chips IS NOT DISTINCT FROM s.stack
           )
         ) AS matching_active_seats,
         COALESCE(sum(s.stack), 0) AS seat_chips
    FROM public.table_seats s
    JOIN public.tables t ON t.id = s.table_id
   WHERE t.tournament_id = p_tournament_id
     AND s.left_at IS NULL
), vacated_seat AS (
  SELECT count(DISTINCT tp.user_id) AS vacated_eliminated_players
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status = 'eliminated'
     AND EXISTS (
       SELECT 1
         FROM public.table_seats s
         JOIN public.tables t ON t.id = s.table_id
        WHERE t.tournament_id = p_tournament_id
          AND s.user_id = tp.user_id
          AND s.left_at IS NOT NULL
     )
), hands AS (
  SELECT count(h.id) FILTER (WHERE h.created_at >= r.draw_created_at) AS hand_count
    FROM reserve_evidence r
    LEFT JOIN public.hand_history h
      ON h.tournament_id = p_tournament_id
    LEFT JOIN public.tables t
      ON t.id = h.table_id
     AND t.tournament_id = p_tournament_id
   WHERE h.id IS NULL OR t.id IS NOT NULL
), escrow AS (
  SELECT count(e.tournament_id) AS escrow_count,
         min(e.reserve_out) AS reserve_out,
         min(e.reserve_in) AS escrow_reserve_in,
         min(e.prize_balance) AS prize_balance
    FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id
), facts AS (
  SELECT c.*,
         r.*,
         e.*,
         pay.*,
         charge.*,
         re.*,
         pool.*,
         j.*,
         te.*,
         ls.*,
         vs.*,
         h.*,
         esc.*,
         (c.starting_chips * 3)::numeric AS funding_floor
    FROM (SELECT 1) seed
    LEFT JOIN contract c ON true
    CROSS JOIN roster r
    CROSS JOIN entitlements e
    CROSS JOIN payments pay
    CROSS JOIN charge_evidence charge
    CROSS JOIN reserve_evidence re
    CROSS JOIN reserve_pool pool
    CROSS JOIN journals j
    CROSS JOIN table_evidence te
    CROSS JOIN live_seats ls
    CROSS JOIN vacated_seat vs
    CROSS JOIN hands h
    CROSS JOIN escrow esc
), verdict AS (
  SELECT f.*,
         (f.id IS NOT NULL
          AND f.status = 'REGISTERING'
          AND (f.variant = 'spin' OR f.tournament_type = 'SPIN')
          AND f.variant <> 'sng'
          AND f.tournament_type <> 'SNG'
          AND f.max_players = 3
          AND f.buy_in IS NOT NULL
          AND f.buy_in::text NOT IN ('NaN', 'Infinity', '-Infinity')
          AND f.buy_in > 0
          AND f.starting_chips IS NOT NULL
          AND f.starting_chips > 0
          AND f.roster_count = 3
          AND f.roster_users = 3
          AND f.active_players = 2
          AND f.positive_active_players = 2
          AND f.eliminated_players = 1
          AND f.other_players = 0
          AND f.invalid_stacks = 0
          AND f.zero_stack_eliminations = 1
          AND f.roster_chips = f.funding_floor
          AND f.entitlement_count = 3
          AND f.entitlement_users = 3
          AND f.roster_entitlement_users = 3
          AND f.min_gross = f.buy_in
          AND f.max_gross = f.buy_in
          AND f.gross_total = round(f.buy_in * 3, 2)
          AND f.payment_count = 3
          AND f.paid_users = 3
          AND f.roster_paid_users = 3
          AND f.min_amount = f.buy_in
          AND f.max_amount = f.buy_in
          AND f.payment_total = round(f.buy_in * 3, 2)
          AND f.source_charge_count = 3
          AND f.exact_source_charges = 3
          AND f.contribution_count = 1
          AND f.draw_count = 1
          AND f.contribution_owner IS NOT NULL
          AND f.contribution_owner = f.draw_owner
          AND f.contribution_amount = f.expected_reserve_in
          AND f.contribution_buy_in = f.buy_in
          AND f.contribution_seats = 3
          AND f.contribution_rake = f.expected_house_rake
          AND f.draw_amount IS NOT NULL
          AND round(-f.draw_amount, 2) = round(f.buy_in * f.draw_multiplier, 2)
          AND f.draw_buy_in = f.buy_in
          AND f.draw_seats = 3
          AND f.draw_multiplier > 0
          AND f.pool_count = 1
          AND f.entry_journal_count = 1
          AND f.draw_journal_count = 1
          AND f.exact_entry_journals = 1
          AND f.exact_draw_journals = 1
          AND f.escrow_count = 1
          AND f.reserve_out = f.expected_reserve_in
          AND f.escrow_reserve_in = round(-f.draw_amount, 2)
          AND f.prize_balance = round(-f.draw_amount, 2)
          AND f.table_count = 1
          AND f.open_tables = 1
          AND f.current_players = 2
          AND f.table_capacity = 3
          AND f.live_seats = 2
          AND f.live_users = 2
          AND f.live_coordinates = 2
          AND f.live_tables = 1
          AND f.invalid_live_stacks = 0
          AND f.positive_live_seats = 2
          AND f.matching_active_seats = 2
          AND f.seat_chips = f.funding_floor
          AND f.seat_chips = f.roster_chips
          AND f.vacated_eliminated_players = 1
          AND f.hand_count >= 1) AS ok
    FROM facts f
)
SELECT CASE WHEN v.ok THEN
  jsonb_build_object(
    'ok', true,
    'recovery_mode', 'played_vacated_spin',
    'tournament_id', p_tournament_id,
    'original_field', 3,
    'active_field', 2,
    'eliminated_players', v.eliminated_players,
    'paid_users', v.paid_users,
    'entitlement_users', v.entitlement_users,
    'live_seats', v.live_seats,
    'hand_count', v.hand_count,
    'funding_floor', v.funding_floor,
    'roster_chips', v.roster_chips,
    'seat_chips', v.seat_chips,
    'original_player_ids', to_jsonb(v.original_player_ids),
    'active_player_ids', to_jsonb(v.active_player_ids)
  )
ELSE
  jsonb_build_object(
    'ok', false,
    'reason', 'played_spin_launch_recovery_unproven',
    'tournament_id', p_tournament_id
  )
END
  FROM verdict v;
$$;


ALTER FUNCTION public.fn_prove_played_spin_launch_recovery(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_prove_played_spin_launch_recovery(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_prove_played_spin_launch_recovery(p_tournament_id uuid) IS 'Service-only evidence proof for one already-played 3-max Spin with exactly one busted/vacated original paid seat. Never applies to Heads-Up SNG and moves no state.';


--
-- Name: fn_prune_ad_events(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_ad_events() RETURNS TABLE(deleted bigint, cutoff timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_days   integer;
  v_cutoff timestamptz;
  v_count  bigint;
BEGIN
  SELECT event_retention_days INTO v_days FROM public.ad_event_retention_policy WHERE id;
  IF v_days IS NULL THEN
    RAISE EXCEPTION 'ad_event_retention_policy has no row; refusing to prune';
  END IF;

  v_cutoff := now() - make_interval(days => v_days);

  DELETE FROM public.ad_event WHERE created_at < v_cutoff;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN QUERY SELECT v_count, v_cutoff;
END;
$$;


ALTER FUNCTION public.fn_prune_ad_events() OWNER TO postgres;

--
-- Name: fn_prune_ca_hand_facts(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_ca_hand_facts(p_limit integer DEFAULT 200000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_days    integer;
  v_cutoff  timestamptz;
  v_deleted integer;
  v_lim     integer;
BEGIN
  v_lim := GREATEST(COALESCE(p_limit, 200000), 1);

  SELECT COALESCE(horse_retention_days, 7) INTO v_days
    FROM public.hand_history_retention_policy LIMIT 1;
  v_days := GREATEST(COALESCE(v_days, 7), 1);
  v_cutoff := now() - make_interval(days => v_days);

  WITH doomed AS (
    SELECT f.hand_id, f.user_id
      FROM public.ca_hand_facts f
      JOIN public.profiles p ON p.id = f.user_id
     WHERE COALESCE(p.is_horse, false)
       AND f.played_at < v_cutoff
     LIMIT v_lim
  )
  DELETE FROM public.ca_hand_facts f
   USING doomed d
   WHERE f.hand_id = d.hand_id AND f.user_id = d.user_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'deleted', v_deleted,
    'cutoff', v_cutoff,
    'retention_days', v_days,
    'more', v_deleted >= v_lim
  );
END;
$$;


ALTER FUNCTION public.fn_prune_ca_hand_facts(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_prune_ca_hand_facts(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_prune_ca_hand_facts(p_limit integer) IS 'Ages horse ca_hand_facts rows out on hand_history_retention_policy.horse_retention_days. Human rows are never deleted. Bounded per call; re-run while it answers more=true.';


--
-- Name: fn_prune_cashier_operations(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_cashier_operations(p_keep_days integer DEFAULT 30) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted bigint;
BEGIN
  IF p_keep_days < 7 OR p_keep_days > 180 THEN
    RAISE EXCEPTION 'p_keep_days must be between 7 and 180';
  END IF;
  DELETE FROM public.cashier_operations
  WHERE created_at < now() - make_interval(days => p_keep_days);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION public.fn_prune_cashier_operations(p_keep_days integer) OWNER TO postgres;

--
-- Name: fn_prune_customization_operations(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_customization_operations(p_keep_days integer DEFAULT 30) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted bigint;
BEGIN
  IF p_keep_days < 7 OR p_keep_days > 180 THEN
    RAISE EXCEPTION 'p_keep_days must be between 7 and 180';
  END IF;
  DELETE FROM public.customization_operations
  WHERE created_at < now() - make_interval(days => p_keep_days);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION public.fn_prune_customization_operations(p_keep_days integer) OWNER TO postgres;

--
-- Name: fn_prune_daily_mission_operations(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_daily_mission_operations(p_keep_days integer DEFAULT 30) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_total bigint := 0;
  v_rows bigint;
BEGIN
  IF p_keep_days IS NULL OR p_keep_days < 7 OR p_keep_days > 180 THEN
    RAISE EXCEPTION 'p_keep_days must be between 7 and 180';
  END IF;

  DELETE FROM public.daily_mission_operations
  WHERE created_at < now() - make_interval(days => p_keep_days);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_total := v_total + v_rows;

  DELETE FROM public.daily_challenge_event_outbox
  WHERE dead_lettered_at < now() - interval '180 days';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_total := v_total + v_rows;

  -- Receipts outlive the 35-day accepted event horizon, so a delayed replay
  -- can never become payable again after its immutable dedupe row is pruned.
  DELETE FROM public.daily_challenge_progress_events
  WHERE created_at < now() - make_interval(days => GREATEST(p_keep_days, 45));
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_total := v_total + v_rows;

  DELETE FROM public.daily_challenge_claim_batches
  WHERE created_at < now() - make_interval(days => p_keep_days);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_total := v_total + v_rows;

  RETURN v_total;
END;
$$;


ALTER FUNCTION public.fn_prune_daily_mission_operations(p_keep_days integer) OWNER TO postgres;

--
-- Name: fn_prune_game_management_events(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_game_management_events(p_before timestamp with time zone DEFAULT (now() - '30 days'::interval), p_batch_size integer DEFAULT 5000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deleted integer;
BEGIN
  IF auth.uid() IS NOT NULL AND COALESCE(auth.role(),'')<>'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE='42501';
  END IF;
  IF NOT pg_try_advisory_xact_lock(hashtext('prune-game-management-events')) THEN RETURN 0; END IF;
  PERFORM set_config('app.game_management_retention','on',true);
  WITH candidates AS (
    SELECT sequence FROM public.game_management_events
    WHERE created_at<LEAST(p_before,now()-interval '7 days')
    ORDER BY sequence FOR UPDATE SKIP LOCKED
    LIMIT LEAST(10000,GREATEST(1,COALESCE(p_batch_size,5000)))
  ) DELETE FROM public.game_management_events e USING candidates c WHERE e.sequence=c.sequence;
  GET DIAGNOSTICS v_deleted=ROW_COUNT;
  PERFORM set_config('app.game_management_retention','',true);
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION public.fn_prune_game_management_events(p_before timestamp with time zone, p_batch_size integer) OWNER TO postgres;

--
-- Name: fn_prune_index_usage_snapshots(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_index_usage_snapshots(p_keep_days integer DEFAULT 60) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_deleted integer := 0;
  v_aged    integer := 0;
BEGIN
  WITH bounds AS (
    SELECT postmaster_start, min(taken_at) AS lo, max(taken_at) AS hi
      FROM public.index_usage_snapshots
     WHERE postmaster_start <> (SELECT max(postmaster_start) FROM public.index_usage_snapshots)
     GROUP BY postmaster_start
  )
  DELETE FROM public.index_usage_snapshots s
   USING bounds b
   WHERE s.postmaster_start = b.postmaster_start
     AND s.taken_at <> b.lo
     AND s.taken_at <> b.hi;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  DELETE FROM public.index_usage_snapshots
   WHERE taken_at < now() - make_interval(days => p_keep_days);
  GET DIAGNOSTICS v_aged = ROW_COUNT;

  RETURN v_deleted + v_aged;
END;
$$;


ALTER FUNCTION public.fn_prune_index_usage_snapshots(p_keep_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_prune_index_usage_snapshots(p_keep_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_prune_index_usage_snapshots(p_keep_days integer) IS 'Collapses each FINISHED postmaster epoch to its first and last capture (all a delta needs) and drops captures older than p_keep_days.';


--
-- Name: fn_prune_stale_rate_limits(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_stale_rate_limits() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_deleted int;
BEGIN
  DELETE FROM public.commander_rate_limits
   WHERE last_request_at < NOW() - INTERVAL '7 days'
     AND (is_blocked = false OR blocked_until < NOW());
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION public.fn_prune_stale_rate_limits() OWNER TO postgres;

--
-- Name: fn_publish_leaderboard_reward_program(uuid, boolean, text, jsonb, jsonb, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_publish_leaderboard_reward_program(p_club_id uuid, p_rewards_enabled boolean, p_metric text, p_weekly_prizes jsonb, p_monthly_prizes jsonb, p_suggestion_key text, p_expected_version integer, p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_club record;
  v_union_id uuid;
  v_can_manage boolean := false;
  v_current_version integer;
  v_previous_id uuid;
  v_existing public.leaderboard_reward_program_versions%ROWTYPE;
  v_weekly_effective date;
  v_monthly_effective date;
  v_next_version integer;
  v_hash text;
  v_requested_hash text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not Authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'A Publication Retry Key Is Required' USING ERRCODE = '22023';
  END IF;
  IF p_expected_version IS NULL OR p_expected_version < 0 THEN
    RAISE EXCEPTION 'A Valid Current Program Version Is Required' USING ERRCODE = '22023';
  END IF;

  SELECT club.id, club.owner_id INTO v_club
    FROM public.clubs club WHERE club.id = p_club_id FOR UPDATE;
  IF v_club.id IS NULL THEN
    RAISE EXCEPTION 'Club Not Found' USING ERRCODE = 'P0002';
  END IF;

  v_union_id := public.fn_leaderboard_funding_union_id(p_club_id);
  IF v_union_id IS NOT NULL THEN
    v_can_manage := public.fn_union_can_manage_wallets(v_union_id, v_actor);
  ELSE
    v_can_manage := v_club.owner_id = v_actor OR EXISTS (
      SELECT 1 FROM public.club_members member
       WHERE member.club_id = p_club_id
         AND member.user_id = v_actor
         AND member.role IN ('owner', 'co_owner')
         AND COALESCE(member.status, 'active') IN ('active', 'approved')
    );
  END IF;
  IF NOT v_can_manage THEN
    RAISE EXCEPTION 'Only The Funding Owner Can Manage Leaderboard Rewards'
      USING ERRCODE = '42501';
  END IF;

  IF p_metric NOT IN ('profit', 'hands_played', 'tournaments_won', 'roi') THEN
    RAISE EXCEPTION 'Choose A Supported Prize Metric' USING ERRCODE = '22023';
  END IF;
  IF p_suggestion_key NOT IN ('balanced', 'top_heavy', 'even', 'custom') THEN
    RAISE EXCEPTION 'Choose A Supported Prize Plan' USING ERRCODE = '22023';
  END IF;
  IF NOT public.fn_leaderboard_prizes_are_valid(COALESCE(p_weekly_prizes, '[]'::jsonb))
     OR NOT public.fn_leaderboard_prizes_are_valid(COALESCE(p_monthly_prizes, '[]'::jsonb)) THEN
    RAISE EXCEPTION 'Prize Rows Must Use Unique Ranks 1 Through 10 And Positive Amounts With At Most Two Decimals'
      USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_rewards_enabled, false)
     AND jsonb_array_length(COALESCE(p_weekly_prizes, '[]'::jsonb)) = 0
     AND jsonb_array_length(COALESCE(p_monthly_prizes, '[]'::jsonb)) = 0 THEN
    RAISE EXCEPTION 'Add A Weekly Or Monthly Prize Before Enabling Rewards'
      USING ERRCODE = '22023';
  END IF;

  SELECT existing.* INTO v_existing
    FROM public.leaderboard_reward_program_versions existing
   WHERE existing.club_id = p_club_id
     AND existing.operation_id = p_operation_id;
  IF v_existing.id IS NOT NULL THEN
    v_requested_hash := md5(jsonb_build_object(
      'club_id', p_club_id,
      'version', v_existing.version,
      'rewards_enabled', COALESCE(p_rewards_enabled, false),
      'payout_metric', p_metric,
      'weekly_prizes', COALESCE(p_weekly_prizes, '[]'::jsonb),
      'monthly_prizes', COALESCE(p_monthly_prizes, '[]'::jsonb),
      'funding_owner_type', CASE WHEN v_union_id IS NULL THEN 'club' ELSE 'union' END,
      'funding_union_id', v_union_id,
      'weekly_effective_from', v_existing.weekly_effective_from,
      'monthly_effective_from', v_existing.monthly_effective_from
    )::text);
    IF v_existing.program_hash <> v_requested_hash
       OR v_existing.suggestion_key <> p_suggestion_key
       OR v_existing.version <> p_expected_version + 1 THEN
      RAISE EXCEPTION 'Leaderboard Publication Retry Key Was Reused For Different Prize Rules'
        USING ERRCODE = '22023';
    END IF;
    RETURN public.fn_get_leaderboard_reward_setup(p_club_id) || jsonb_build_object(
      'rewards_enabled', v_existing.rewards_enabled,
      'payout_metric', v_existing.payout_metric,
      'weekly_prizes', v_existing.weekly_prizes,
      'monthly_prizes', v_existing.monthly_prizes,
      'suggestion_key', v_existing.suggestion_key,
      'program_version', v_existing.version,
      'program_hash', v_existing.program_hash,
      'program_status', v_existing.status,
      'weekly_effective_from', v_existing.weekly_effective_from,
      'monthly_effective_from', v_existing.monthly_effective_from,
      'published_at', v_existing.published_at,
      'program_funding_owner_type', v_existing.funding_owner_type,
      'program_funding_union_id', v_existing.funding_union_id,
      'program_funding_label', CASE
        WHEN v_existing.funding_owner_type = 'union' THEN COALESCE(
          (SELECT union_row.name FROM public.unions union_row
            WHERE union_row.id = v_existing.funding_union_id),
          'Recorded Union'
        ) || ' Promo Wallet'
        ELSE (SELECT club.name FROM public.clubs club WHERE club.id = p_club_id)
             || ' Promo Wallet'
      END
    );
  END IF;

  SELECT program.version, program.id INTO v_current_version, v_previous_id
    FROM public.leaderboard_reward_program_versions program
   WHERE program.club_id = p_club_id
   ORDER BY program.version DESC
   LIMIT 1;
  v_current_version := COALESCE(v_current_version, 0);
  IF v_current_version <> p_expected_version THEN
    RAISE EXCEPTION 'Leaderboard Prize Setup Changed In Another Session'
      USING ERRCODE = '40001',
            DETAIL = format('Expected Version %s But Found Version %s',
                            p_expected_version, v_current_version);
  END IF;

  SELECT bounds.end_date INTO v_weekly_effective
    FROM public.fn_leaderboard_period_window('weekly', 0) bounds;
  SELECT bounds.end_date INTO v_monthly_effective
    FROM public.fn_leaderboard_period_window('monthly', 0) bounds;
  v_next_version := v_current_version + 1;
  v_hash := md5(jsonb_build_object(
    'club_id', p_club_id,
    'version', v_next_version,
    'rewards_enabled', COALESCE(p_rewards_enabled, false),
    'payout_metric', p_metric,
    'weekly_prizes', COALESCE(p_weekly_prizes, '[]'::jsonb),
    'monthly_prizes', COALESCE(p_monthly_prizes, '[]'::jsonb),
    'funding_owner_type', CASE WHEN v_union_id IS NULL THEN 'club' ELSE 'union' END,
    'funding_union_id', v_union_id,
    'weekly_effective_from', v_weekly_effective,
    'monthly_effective_from', v_monthly_effective
  )::text);

  INSERT INTO public.leaderboard_reward_program_versions (
    club_id, version, operation_id, rewards_enabled, payout_metric,
    weekly_prizes, monthly_prizes, suggestion_key,
    funding_owner_type, funding_union_id,
    weekly_effective_from, monthly_effective_from,
    published_by, supersedes_program_id, program_hash
  ) VALUES (
    p_club_id, v_next_version, p_operation_id, COALESCE(p_rewards_enabled, false), p_metric,
    COALESCE(p_weekly_prizes, '[]'::jsonb), COALESCE(p_monthly_prizes, '[]'::jsonb),
    p_suggestion_key, CASE WHEN v_union_id IS NULL THEN 'club' ELSE 'union' END, v_union_id,
    v_weekly_effective, v_monthly_effective, v_actor, v_previous_id, v_hash
  );

  INSERT INTO public.club_leaderboard_settings (
    club_id, payout_currency, weekly_prizes, monthly_prizes,
    rewards_enabled, payout_metric, funding_owner_type, funding_union_id,
    suggestion_key, setup_completed_at, setup_completed_by, updated_by, updated_at
  ) VALUES (
    p_club_id, 'chips', COALESCE(p_weekly_prizes, '[]'::jsonb),
    COALESCE(p_monthly_prizes, '[]'::jsonb), COALESCE(p_rewards_enabled, false),
    p_metric, CASE WHEN v_union_id IS NULL THEN 'club' ELSE 'union' END, v_union_id,
    p_suggestion_key, now(), v_actor, v_actor, now()
  )
  ON CONFLICT (club_id) DO UPDATE SET
    payout_currency = EXCLUDED.payout_currency,
    weekly_prizes = EXCLUDED.weekly_prizes,
    monthly_prizes = EXCLUDED.monthly_prizes,
    rewards_enabled = EXCLUDED.rewards_enabled,
    payout_metric = EXCLUDED.payout_metric,
    funding_owner_type = EXCLUDED.funding_owner_type,
    funding_union_id = EXCLUDED.funding_union_id,
    suggestion_key = EXCLUDED.suggestion_key,
    setup_completed_at = COALESCE(public.club_leaderboard_settings.setup_completed_at, now()),
    setup_completed_by = COALESCE(public.club_leaderboard_settings.setup_completed_by, v_actor),
    updated_by = v_actor,
    updated_at = now();

  RETURN public.fn_get_leaderboard_reward_setup(p_club_id);
END;
$$;


ALTER FUNCTION public.fn_publish_leaderboard_reward_program(p_club_id uuid, p_rewards_enabled boolean, p_metric text, p_weekly_prizes jsonb, p_monthly_prizes jsonb, p_suggestion_key text, p_expected_version integer, p_operation_id uuid) OWNER TO postgres;

--
-- Name: fn_purchase_chips(uuid, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_purchase_chips(p_user_id uuid, p_amount numeric, p_diamonds_cost integer DEFAULT 0, p_reference_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_debit jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'user required');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'chip amount must be > 0');
  END IF;
  IF p_diamonds_cost IS NULL OR p_diamonds_cost < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid diamond cost');
  END IF;

  IF p_diamonds_cost > 0 THEN
    v_debit := deduct_diamonds(
      p_user_id, p_diamonds_cost, 'Chip package purchase',
      'purchase', 'chip_purchase', '{}'::jsonb, p_reference_id, 0
    );

    IF COALESCE((v_debit->>'success')::boolean, false) IS NOT TRUE THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', COALESCE(v_debit->>'error', 'diamond debit failed'),
        'balance', v_debit->'balance'
      );
    END IF;
  END IF;

  PERFORM credit_player_wallet(p_user_id, p_amount);

  INSERT INTO wallet_transactions (
    user_id, wallet_type, amount, type, category, description, created_at
  ) VALUES (
    p_user_id, 'PLAYER', p_amount, 'credit', 'deposit',
    format('Chip purchase: %s chips for %s diamonds', p_amount, p_diamonds_cost), NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'chips_credited', p_amount,
    'diamonds_charged', p_diamonds_cost,
    'diamond_balance_after', v_debit->'balance',
    'idempotent', COALESCE((v_debit->>'idempotent')::boolean, false)
  );
END;
$$;


ALTER FUNCTION public.fn_purchase_chips(p_user_id uuid, p_amount numeric, p_diamonds_cost integer, p_reference_id text) OWNER TO postgres;

--
-- Name: fn_purchase_club_chips(uuid, uuid, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_purchase_club_chips(p_user_id uuid, p_club_id uuid, p_amount numeric, p_diamonds_cost integer DEFAULT 0, p_reference_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_debit    jsonb;
  v_credit   jsonb;
  v_is_member boolean;
BEGIN
  IF p_user_id IS NULL OR p_club_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'user and club required');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'chip amount must be > 0');
  END IF;
  IF p_diamonds_cost IS NULL OR p_diamonds_cost < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid diamond cost');
  END IF;

  -- Require an existing membership. fn_credit_chips would happily auto-create
  -- one, which would silently join the buyer to a club they never chose.
  SELECT EXISTS (
    SELECT 1 FROM club_members WHERE club_id = p_club_id AND user_id = p_user_id
  ) INTO v_is_member;

  IF NOT v_is_member THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not a member of this club');
  END IF;

  IF p_diamonds_cost > 0 THEN
    v_debit := deduct_diamonds(
      p_user_id, p_diamonds_cost, 'Club chip package purchase',
      'purchase', 'chip_purchase', jsonb_build_object('club_id', p_club_id),
      p_reference_id, 0
    );

    IF COALESCE((v_debit->>'success')::boolean, false) IS NOT TRUE THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', COALESCE(v_debit->>'error', 'diamond debit failed'),
        'balance', v_debit->'balance'
      );
    END IF;

    -- A replayed reference means the ORIGINAL call already completed (a failed
    -- credit would have rolled back its diamond_transactions row with it), so
    -- crediting again here would double-pay. Report it as idempotent instead.
    IF COALESCE((v_debit->>'idempotent')::boolean, false) IS TRUE THEN
      RETURN jsonb_build_object(
        'success', true,
        'chips_credited', 0,
        'diamonds_charged', 0,
        'diamond_balance_after', v_debit->'balance',
        'club_id', p_club_id,
        'idempotent', true
      );
    END IF;
  END IF;

  v_credit := fn_credit_chips(
    p_club_id, p_user_id, p_amount, 'Chip package purchase',
    jsonb_build_object('transaction_type', 'chip_purchase', 'diamonds_charged', p_diamonds_cost)
  );

  IF COALESCE((v_credit->>'success')::boolean, false) IS NOT TRUE THEN
    -- Abort so the diamond deduction above rolls back with us.
    RAISE EXCEPTION 'club chip credit failed: %', COALESCE(v_credit->>'error', 'unknown');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'chips_credited', p_amount,
    'diamonds_charged', p_diamonds_cost,
    'diamond_balance_after', v_debit->'balance',
    'club_id', p_club_id,
    'club_balance_after', v_credit->'balance_after',
    'idempotent', false
  );
END;
$$;


ALTER FUNCTION public.fn_purchase_club_chips(p_user_id uuid, p_club_id uuid, p_amount numeric, p_diamonds_cost integer, p_reference_id text) OWNER TO postgres;

--
-- Name: fn_purchase_club_shop_item_diamonds(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_purchase_club_shop_item_diamonds(p_club_id uuid, p_user_id uuid, p_item_id uuid, p_charge_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_purchase_id_text text;
  v_expected_price_text text;
  v_expected_price_bigint bigint;
  v_expected_price integer;
  v_availability jsonb;
BEGIN
  IF p_charge_reference LIKE 'card-redemption:%' THEN
    v_purchase_id_text := split_part(p_charge_reference, ':', 2);
    IF v_purchase_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
      SELECT metadata #>> '{redemption_intent,expected_price}'
        INTO v_expected_price_text
        FROM public.diamond_purchases
       WHERE id = v_purchase_id_text::uuid
         AND user_id = p_user_id
         AND metadata #>> '{redemption_intent,club_id}' = p_club_id::text
         AND metadata #>> '{redemption_intent,item_id}' = p_item_id::text;
      IF v_expected_price_text ~ '^[0-9]{1,10}$' THEN
        v_expected_price_bigint := v_expected_price_text::bigint;
        IF v_expected_price_bigint BETWEEN 0 AND 2147483647 THEN
          v_expected_price := v_expected_price_bigint::integer;
        END IF;
      END IF;
    END IF;
  END IF;

  IF v_expected_price IS NULL THEN
    v_availability := public.fn_shop_item_availability(p_club_id, p_user_id, p_item_id);
    IF COALESCE((v_availability ->> 'ok')::boolean, false)
       AND COALESCE(v_availability ->> 'price', '') ~ '^[0-9]{1,10}$' THEN
      v_expected_price_bigint := (v_availability ->> 'price')::bigint;
      IF v_expected_price_bigint BETWEEN 0 AND 2147483647 THEN
        v_expected_price := v_expected_price_bigint::integer;
      END IF;
    END IF;
  END IF;

  RETURN public.fn_purchase_club_shop_item_diamonds_v2(
    p_club_id,
    p_user_id,
    p_item_id,
    p_charge_reference,
    v_expected_price
  );
END;
$_$;


ALTER FUNCTION public.fn_purchase_club_shop_item_diamonds(p_club_id uuid, p_user_id uuid, p_item_id uuid, p_charge_reference text) OWNER TO postgres;

--
-- Name: fn_purchase_club_shop_item_diamonds_v2(uuid, uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_purchase_club_shop_item_diamonds_v2(p_club_id uuid, p_user_id uuid, p_item_id uuid, p_charge_reference text, p_expected_price integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_item public.club_shop_items%ROWTYPE;
  v_existing public.club_shop_purchases%ROWTYPE;
  v_purchase public.club_shop_purchases%ROWTYPE;
  v_avail jsonb;
  v_debit jsonb;
  v_balance integer;
  v_price integer;
  v_stock_claimed boolean := false;
BEGIN
  IF p_charge_reference IS NULL OR length(p_charge_reference) < 16
     OR length(p_charge_reference) > 160 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_reference');
  END IF;

  -- A committed retry is safe to replay. When the retry carries a price, it
  -- must still describe the purchase that owns this durable reference.
  SELECT * INTO v_existing
    FROM public.club_shop_purchases
   WHERE charge_reference = p_charge_reference;
  IF FOUND THEN
    IF v_existing.buyer_id <> p_user_id OR v_existing.club_id <> p_club_id
       OR v_existing.item_id <> p_item_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'reference_conflict');
    END IF;
    IF p_expected_price IS NOT NULL
       AND v_existing.price_paid IS DISTINCT FROM p_expected_price THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'reference_conflict',
        'expected_price', p_expected_price,
        'price', v_existing.price_paid
      );
    END IF;
    SELECT COALESCE(diamonds, 0) INTO v_balance
      FROM public.profiles WHERE id = p_user_id;
    RETURN jsonb_build_object(
      'success', true, 'duplicate', true, 'purchase_id', v_existing.id,
      'price_paid', v_existing.price_paid, 'new_balance', v_balance
    );
  END IF;

  -- New v2 purchases without an explicit confirmation price fail closed. The
  -- rollout wrapper below supplies only a server-authoritative snapshot.
  IF p_expected_price IS NULL OR p_expected_price < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'price_confirmation_required');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.club_members
     WHERE club_id = p_club_id AND user_id = p_user_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_member');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('shop_buy:' || p_user_id::text || ':' || p_item_id::text, 0)
  );

  SELECT * INTO v_item
    FROM public.club_shop_items
   WHERE id = p_item_id AND club_id = p_club_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;

  v_avail := public.fn_shop_item_availability(p_club_id, p_user_id, p_item_id);
  IF NOT COALESCE((v_avail->>'ok')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'error', v_avail->>'reason') || v_avail;
  END IF;

  v_price := COALESCE((v_avail->>'price')::integer, v_item.price, 0);
  IF v_price < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_price');
  END IF;
  IF v_price IS DISTINCT FROM p_expected_price THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'price_changed',
      'expected_price', p_expected_price,
      'price', v_price
    );
  END IF;

  IF v_item.stock IS NOT NULL THEN
    UPDATE public.club_shop_items
       SET stock = stock - 1
     WHERE id = p_item_id AND club_id = p_club_id AND stock > 0;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'sold_out');
    END IF;
    v_stock_claimed := true;
  END IF;

  IF v_price > 0 THEN
    v_debit := public.add_diamonds_to_balance(
      p_user_id, -v_price, 'purchase',
      'Club Shop: ' || COALESCE(v_item.name, p_item_id::text),
      p_charge_reference
    );
    IF COALESCE((v_debit->>'success')::boolean, false) IS NOT TRUE THEN
      IF v_debit->>'error' = 'insufficient_diamonds' THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'insufficient_diamonds';
      END IF;
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = COALESCE(v_debit->>'error', 'diamond_debit_failed');
    END IF;
    v_balance := COALESCE((v_debit->>'new_balance')::integer, 0);
  ELSE
    SELECT COALESCE(diamonds, 0) INTO v_balance
      FROM public.profiles WHERE id = p_user_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'profile_not_found';
    END IF;
  END IF;

  INSERT INTO public.club_shop_purchases (
    club_id, buyer_id, item_id, price_paid, stock_claimed, currency,
    grant_snapshot, charge_reference
  ) VALUES (
    p_club_id, p_user_id, p_item_id, v_price, v_stock_claimed, 'diamonds',
    v_item.grant_spec, p_charge_reference
  ) RETURNING * INTO v_purchase;

  RETURN jsonb_build_object(
    'success', true,
    'purchase_id', v_purchase.id,
    'new_balance', v_balance,
    'price_paid', v_price,
    'stock_claimed', v_stock_claimed,
    'item_name', v_item.name,
    'item_type', v_item.item_type
  );
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_owned');
  WHEN SQLSTATE 'P0001' THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION public.fn_purchase_club_shop_item_diamonds_v2(p_club_id uuid, p_user_id uuid, p_item_id uuid, p_charge_reference text, p_expected_price integer) OWNER TO postgres;

--
-- Name: fn_purchase_feature(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_purchase_feature(p_user_id uuid, p_feature text, p_cost integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication Required');
  END IF;

  RETURN public.fn_purchase_feature_v2(p_user_id, p_feature, gen_random_uuid());
END;
$$;


ALTER FUNCTION public.fn_purchase_feature(p_user_id uuid, p_feature text, p_cost integer) OWNER TO postgres;

--
-- Name: fn_purchase_feature_v2(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_purchase_feature_v2(p_user_id uuid, p_feature text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller            uuid := auth.uid();
  v_price             record;
  v_deduct            jsonb;
  v_expires           timestamptz;
  v_uses              integer;
  v_category          text;
  v_asset_id          text;
  v_is_customization  boolean := false;
  v_lifetime_included boolean := false;
  v_balance           integer;
  v_request_payload   jsonb := jsonb_build_object('feature', p_feature);
  v_cached_kind       text;
  v_cached_payload    jsonb;
  v_cached_result     jsonb;
  v_result            jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication Required');
  END IF;
  IF p_user_id IS DISTINCT FROM v_caller THEN
    RETURN jsonb_build_object('success', false, 'error', 'Purchases Are Limited To Your Own Account');
  END IF;
  IF p_request_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Secure Request Id Required');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'digital_purchase_request:' || v_caller::text || ':' || p_request_id::text,
      0
    )
  );

  SELECT r.purchase_kind, r.request_payload, r.result
    INTO v_cached_kind, v_cached_payload, v_cached_result
    FROM public.digital_purchase_receipts r
   WHERE r.user_id = v_caller
     AND r.request_id = p_request_id;

  IF FOUND THEN
    IF v_cached_kind IS DISTINCT FROM 'feature'
       OR v_cached_payload IS DISTINCT FROM v_request_payload
    THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Request Id Already Used For Another Purchase',
        'code', 'REQUEST_ID_REUSED'
      );
    END IF;

    RETURN v_cached_result || jsonb_build_object(
      'cost', 0,
      'original_cost',
        COALESCE(
          (v_cached_result->>'original_cost')::integer,
          (v_cached_result->>'cost')::integer,
          0
        ),
      'idempotent', true,
      'granted', false
    );
  END IF;

  SELECT feature, diamond_cost, usage_type INTO v_price
    FROM public.feature_pricing
   WHERE feature = p_feature;
  IF v_price.feature IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unknown Feature: ' || p_feature);
  END IF;
  IF v_price.diamond_cost < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Feature Pricing Is Invalid');
  END IF;

  v_lifetime_included := public.sp_is_lifetime_vip(v_caller)
    AND p_feature = ANY(ARRAY[
      'rabbit_hunt',
      'time_bank_seconds',
      'throwable',
      'emoji_pack',
      'tag_pack',
      'show_stack_bb',
      'offline_protection',
      'auto_time_bank'
    ]::text[]);

  IF v_lifetime_included THEN
    SELECT p.diamonds INTO v_balance
      FROM public.profiles p
     WHERE p.id = v_caller;

    v_result := jsonb_build_object(
      'success', true,
      'included', true,
      'unlimited', v_price.usage_type = 'per_use',
      'source', 'lifetime_vip',
      'cost', 0,
      'usage_type', v_price.usage_type,
      'idempotent', false,
      'granted', false,
      'diamonds_remaining', v_balance
    );
    INSERT INTO public.digital_purchase_receipts
      (user_id, request_id, purchase_kind, request_payload, result)
    VALUES
      (v_caller, p_request_id, 'feature', v_request_payload, v_result);
    RETURN v_result;
  END IF;

  IF p_feature LIKE 'studio:%' THEN
    v_category := split_part(p_feature, ':', 2);
    v_asset_id := substring(p_feature from length('studio:' || v_category || ':') + 1);
    v_is_customization := v_category IN (
      'theme_id', 'table_id', 'button_id', 'background_id'
    ) AND COALESCE(v_asset_id, '') <> '';
  ELSIF p_feature LIKE 'card_back_%' THEN
    v_category := 'cards_id';
    v_asset_id := substring(p_feature from length('card_back_') + 1);
    v_is_customization := COALESCE(v_asset_id, '') <> '';
  END IF;

  IF v_is_customization AND v_price.usage_type = 'permanent' THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('fn_purchase_feature:customization:' || v_caller::text, 0)
    );
  ELSE
    PERFORM pg_advisory_xact_lock(
      hashtextextended('fn_purchase_feature:' || v_caller::text || ':' || p_feature, 0)
    );
  END IF;

  IF v_price.usage_type IN ('permanent', 'per_session') THEN
    IF EXISTS (
      SELECT 1
        FROM public.feature_purchases
       WHERE user_id = v_caller
         AND feature = p_feature
         AND (expires_at IS NULL OR expires_at > now())
    ) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'already_owned',
        'already_owned', true,
        'usage_type', v_price.usage_type,
        'ownership_source', 'purchase_receipt'
      );
    END IF;

    IF v_is_customization
       AND public.sp_theme_asset_is_owned(v_caller, v_category, v_asset_id)
    THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'already_owned',
        'already_owned', true,
        'usage_type', v_price.usage_type,
        'ownership_source', 'entitlement'
      );
    END IF;
  END IF;

  IF v_price.diamond_cost > 0 THEN
    v_deduct := public.deduct_diamonds(
      p_user_id          := v_caller,
      p_amount           := v_price.diamond_cost,
      p_description      := 'Feature purchase: ' || p_feature,
      p_transaction_type := 'feature_purchase',
      p_source           := 'feature_purchase',
      p_metadata         := jsonb_build_object('feature', p_feature),
      p_reference_id     := 'feat_' || v_caller::text || '_' || p_request_id::text
    );
    IF COALESCE((v_deduct->>'success')::boolean, false) = false THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', COALESCE(v_deduct->>'error', 'Diamond Charge Failed')
      );
    END IF;

    -- deduct_diamonds deliberately deduplicates a repeated request receipt.
    -- Never turn that one debit into two grants after a response-lost retry.
    IF COALESCE((v_deduct->>'idempotent')::boolean, false) THEN
      v_result := jsonb_build_object(
        'success', true,
        'cost', 0,
        'original_cost', v_price.diamond_cost,
        'usage_type', v_price.usage_type,
        'idempotent', true,
        'granted', false,
        'diamonds_remaining', (v_deduct->>'balance')::integer
      );
      INSERT INTO public.digital_purchase_receipts
        (user_id, request_id, purchase_kind, request_payload, result)
      VALUES
        (v_caller, p_request_id, 'feature', v_request_payload, v_result);
      RETURN v_result;
    END IF;
    v_balance := (v_deduct->>'balance')::integer;
  ELSE
    SELECT p.diamonds INTO v_balance
      FROM public.profiles p
     WHERE p.id = v_caller;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'User Not Found');
    END IF;
  END IF;

  v_uses := CASE v_price.usage_type WHEN 'per_use' THEN 1 ELSE NULL END;
  v_expires := CASE v_price.usage_type
    WHEN 'per_session' THEN now() + interval '8 hours'
    ELSE NULL
  END;

  INSERT INTO public.feature_purchases
    (user_id, feature, cost, usage_type, uses_remaining, expires_at)
  VALUES
    (v_caller, p_feature, v_price.diamond_cost, v_price.usage_type, v_uses, v_expires);

  v_result := jsonb_build_object(
    'success', true,
    'cost', v_price.diamond_cost,
    'usage_type', v_price.usage_type,
    'idempotent', false,
    'granted', true,
    'diamonds_remaining', v_balance
  );
  INSERT INTO public.digital_purchase_receipts
    (user_id, request_id, purchase_kind, request_payload, result)
  VALUES
    (v_caller, p_request_id, 'feature', v_request_payload, v_result);
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_purchase_feature_v2(p_user_id uuid, p_feature text, p_request_id uuid) OWNER TO postgres;

--
-- Name: fn_purchase_time_banks_v2(integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_purchase_time_banks_v2(p_quantity integer, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller         uuid := auth.uid();
  v_unit_cost      integer;
  v_total_cost     integer;
  v_deduct         jsonb;
  v_reference      text;
  v_balance        integer;
  v_request_payload jsonb := jsonb_build_object('quantity', p_quantity);
  v_cached_kind    text;
  v_cached_payload jsonb;
  v_cached_result  jsonb;
  v_result         jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication Required');
  END IF;

  IF p_quantity IS NULL OR p_quantity < 1 OR p_quantity > 500 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Quantity Must Be Between 1 And 500');
  END IF;

  IF p_request_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Secure Request Id Required');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'digital_purchase_request:' || v_caller::text || ':' || p_request_id::text,
      0
    )
  );

  SELECT r.purchase_kind, r.request_payload, r.result
    INTO v_cached_kind, v_cached_payload, v_cached_result
    FROM public.digital_purchase_receipts r
   WHERE r.user_id = v_caller
     AND r.request_id = p_request_id;

  IF FOUND THEN
    IF v_cached_kind IS DISTINCT FROM 'time_bank'
       OR v_cached_payload IS DISTINCT FROM v_request_payload
    THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Request Id Already Used For Another Purchase',
        'code', 'REQUEST_ID_REUSED'
      );
    END IF;

    RETURN v_cached_result || jsonb_build_object(
      'total_cost', 0,
      'original_total_cost',
        COALESCE(
          (v_cached_result->>'original_total_cost')::integer,
          (v_cached_result->>'total_cost')::integer,
          0
        ),
      'idempotent', true,
      'granted', false
    );
  END IF;

  IF public.sp_is_lifetime_vip(v_caller) THEN
    SELECT p.diamonds INTO v_balance
      FROM public.profiles p
     WHERE p.id = v_caller;

    v_result := jsonb_build_object(
      'success', true,
      'included', true,
      'unlimited', true,
      'source', 'lifetime_vip',
      'quantity', p_quantity,
      'unit_cost', 0,
      'total_cost', 0,
      'idempotent', false,
      'granted', false,
      'diamonds_remaining', v_balance
    );
    INSERT INTO public.digital_purchase_receipts
      (user_id, request_id, purchase_kind, request_payload, result)
    VALUES
      (v_caller, p_request_id, 'time_bank', v_request_payload, v_result);
    RETURN v_result;
  END IF;

  SELECT diamond_cost INTO v_unit_cost
    FROM public.feature_pricing
   WHERE feature = 'time_bank_seconds';

  IF v_unit_cost IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Time Bank Pricing Not Configured');
  END IF;
  IF v_unit_cost < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Time Bank Pricing Is Invalid');
  END IF;

  v_total_cost := v_unit_cost * p_quantity;
  v_reference := 'tbank_' || v_caller::text || '_' || p_request_id::text;

  IF v_total_cost > 0 THEN
    v_deduct := public.deduct_diamonds(
      p_user_id          := v_caller,
      p_amount           := v_total_cost,
      p_description      := 'Time Banks x' || p_quantity,
      p_transaction_type := 'feature_purchase',
      p_source           := 'feature_purchase',
      p_metadata         := jsonb_build_object(
                              'feature', 'time_bank_seconds',
                              'quantity', p_quantity,
                              'unit_cost', v_unit_cost,
                              'sink', 'time_bank',
                              'counterparty', 'revenue:feature_purchase',
                              'issuance_class', 'spend'),
      p_reference_id     := v_reference
    );

    IF COALESCE((v_deduct->>'success')::boolean, false) = false THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', COALESCE(v_deduct->>'error', 'Diamond Charge Failed'),
        'required', v_total_cost
      );
    END IF;

    IF COALESCE((v_deduct->>'idempotent')::boolean, false) THEN
      v_result := jsonb_build_object(
        'success', true,
        'quantity', p_quantity,
        'unit_cost', v_unit_cost,
        'total_cost', 0,
        'original_total_cost', v_total_cost,
        'idempotent', true,
        'granted', false,
        'diamonds_remaining', (v_deduct->>'balance')::integer
      );
      INSERT INTO public.digital_purchase_receipts
        (user_id, request_id, purchase_kind, request_payload, result)
      VALUES
        (v_caller, p_request_id, 'time_bank', v_request_payload, v_result);
      RETURN v_result;
    END IF;
    v_balance := (v_deduct->>'balance')::integer;
  ELSE
    SELECT p.diamonds INTO v_balance
      FROM public.profiles p
     WHERE p.id = v_caller;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'User Not Found');
    END IF;
  END IF;

  INSERT INTO public.feature_purchases
    (user_id, feature, cost, usage_type, uses_remaining, expires_at)
  VALUES
    (v_caller, 'time_bank_seconds', v_total_cost, 'per_use', p_quantity, NULL);

  v_result := jsonb_build_object(
    'success', true,
    'quantity', p_quantity,
    'unit_cost', v_unit_cost,
    'total_cost', v_total_cost,
    'idempotent', false,
    'granted', true,
    'diamonds_remaining', v_balance
  );
  INSERT INTO public.digital_purchase_receipts
    (user_id, request_id, purchase_kind, request_payload, result)
  VALUES
    (v_caller, p_request_id, 'time_bank', v_request_payload, v_result);
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_purchase_time_banks_v2(p_quantity integer, p_request_id uuid) OWNER TO postgres;

