--
-- Name: fn_queue_video_transcode(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_queue_video_transcode() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.content_type = 'video'
     AND (NEW.media_urls->>0) IS NOT NULL
     AND (
       (NEW.media_urls->>0) ILIKE '%.mov'
       OR (NEW.media_urls->>0) ILIKE '%.hevc'
       OR (NEW.media_urls->>0) ILIKE '%.heic'
       OR (NEW.media_urls->>0) ILIKE '%.mkv'
       OR (NEW.media_urls->>0) ILIKE '%.avi'
       OR (NEW.media_urls->>0) ILIKE '%.mp4'
       OR (NEW.media_urls->>0) ILIKE '%.m4v'
       OR (NEW.media_urls->>0) ILIKE '%.webm'
       OR (NEW.media_urls->>0) ILIKE '%/live-recordings/%'
     )
     -- Only queue when a thumbnail is actually missing: a client-supplied
     -- poster frame should not trigger a re-encode just for extraction.
     AND (NEW.thumbnail_url IS NULL OR NEW.thumbnail_url = '')
  THEN
    NEW.transcode_status := 'queued';
    NEW.original_media_url := (NEW.media_urls->>0);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_queue_video_transcode() OWNER TO postgres;

--
-- Name: fn_queue_youtube_verification(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_queue_youtube_verification(p_video_id text, p_surface text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_video_id text := public.fn_extract_youtube_video_id(p_video_id);
  v_surface text := left(
    regexp_replace(
      COALESCE(NULLIF(btrim(p_surface), ''), 'youtube_publication'),
      '[[:cntrl:]]',
      '',
      'g'
    ),
    80
  );
BEGIN
  IF v_video_id IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.youtube_embed_failures AS existing (
    video_id,
    error_code,
    surface,
    hit_count,
    first_seen_at,
    last_seen_at,
    resolved,
    verification_status,
    last_verified_at
  ) VALUES (
    v_video_id,
    150,
    v_surface,
    0,
    now(),
    now(),
    true,
    'pending',
    NULL
  )
  ON CONFLICT ON CONSTRAINT youtube_embed_failures_video_id_key DO UPDATE
  SET surface = EXCLUDED.surface,
      last_seen_at = now(),
      resolved = true,
      verification_status = 'pending',
      last_verified_at = NULL
  WHERE NOT (
      existing.verification_status = 'confirmed'
      AND existing.resolved = false
    )
    AND NOT (
      existing.verification_status = 'resolved'
      AND existing.resolved = true
      AND existing.last_verified_at >= now() - interval '6 days'
      AND existing.last_verified_at <= now() + interval '5 minutes'
    );
END
$$;


ALTER FUNCTION public.fn_queue_youtube_verification(p_video_id text, p_surface text) OWNER TO postgres;

--
-- Name: fn_raise_financial_alert(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_raise_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id       uuid;
  v_sev      text;
  v_uid      uuid := auth.uid();
  v_recent   integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required to raise a financial alert'
      USING ERRCODE = '28000';
  END IF;

  v_sev := lower(coalesce(p_severity, 'info'));
  IF v_sev NOT IN ('critical', 'warning', 'info') THEN
    v_sev := 'info';
  END IF;

  -- Flood guard: at most 30 alerts per reporter per minute. Returning NULL
  -- rather than raising keeps the caller's error path clean; the caller still
  -- escalates to its own error reporter when it gets no id back.
  SELECT count(*) INTO v_recent
    FROM public.financial_alerts
   WHERE created_at > now() - interval '1 minute'
     AND context ->> 'reported_by' = v_uid::text;
  IF v_recent >= 30 THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.financial_alerts (severity, source, message, context, resolved)
  VALUES (
    v_sev,
    left(coalesce(nullif(p_source, ''), 'unknown'), 200),
    left(coalesce(nullif(p_message, ''), '(no message)'), 4000),
    coalesce(p_context, '{}'::jsonb)
      || jsonb_build_object('reported_by', v_uid::text, 'channel', 'client_rpc'),
    false
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.fn_raise_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_raise_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_raise_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb) IS 'Audit M7: raise-only entry point for client financial alerts. financial_alerts RLS is service_role-only, so clients must route through this SECURITY DEFINER function. Throttled to 30 alerts/reporter/minute; returns NULL when throttled.';


--
-- Name: fn_raise_notification(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_raise_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_link text DEFAULT NULL::text, p_data jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_title IS NULL OR btrim(p_title) = '' THEN RETURN; END IF;
  INSERT INTO public.notifications (user_id, type, title, message, link, data)
  VALUES (p_user_id, p_type, p_title, p_message, p_link, COALESCE(p_data, '{}'::jsonb));
END; $$;


