--
-- Name: fn_raise_server_financial_alert(text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_raise_server_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb DEFAULT '{}'::jsonb, p_dedupe_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id     uuid;
  v_sev    text;
  v_source text;
  v_key    text;
  v_recent integer;
BEGIN
  v_sev := lower(coalesce(p_severity, 'info'));
  IF v_sev NOT IN ('critical', 'warning', 'info') THEN
    v_sev := 'info';
  END IF;

  v_source := left(coalesce(nullif(p_source, ''), 'unknown'), 200);
  v_key    := left(nullif(btrim(coalesce(p_dedupe_key, '')), ''), 200);

  /* ONE OPEN ALERT PER THING THAT IS WRONG. Not per pass over it. */
  IF v_key IS NOT NULL THEN
    SELECT fa.id INTO v_id
      FROM public.financial_alerts fa
     WHERE fa.source = v_source
       AND fa.resolved IS NOT TRUE
       AND fa.context ->> 'dedupe_key' = v_key
     ORDER BY fa.created_at DESC
     LIMIT 1;
    IF v_id IS NOT NULL THEN
      RETURN v_id;
    END IF;
  END IF;

  SELECT count(*) INTO v_recent
    FROM public.financial_alerts
   WHERE created_at > now() - interval '1 minute'
     AND source = v_source
     AND context ->> 'channel' = 'server_rpc';

  IF v_recent >= 60 THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.financial_alerts (severity, source, message, context, resolved)
  VALUES (
    v_sev,
    v_source,
    left(coalesce(nullif(p_message, ''), '(no message)'), 4000),
    coalesce(p_context, '{}'::jsonb)
      || jsonb_build_object('channel', 'server_rpc')
      || CASE WHEN v_key IS NULL THEN '{}'::jsonb
              ELSE jsonb_build_object('dedupe_key', v_key) END,
    false
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.fn_raise_server_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb, p_dedupe_key text) OWNER TO postgres;

--
-- Name: FUNCTION fn_raise_server_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb, p_dedupe_key text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_raise_server_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb, p_dedupe_key text) IS 'Durable server-side financial alert. Pass p_dedupe_key to get one OPEN alert per thing that is wrong rather than one per pass over it: an unresolved alert from the same source carrying that key is returned instead of a second row being written. Returns the row id (deduped or new), or NULL only when the per-source flood guard fires.';


--
-- Name: fn_rake_attribution_drift(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_attribution_drift(p_hours integer DEFAULT 24) RETURNS TABLE(hand_id uuid, rake_amount numeric, allocated numeric, difference numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT r.hand_id,
         r.rake_amount,
         COALESCE(SUM(ra.weighted_rake_credit), 0) AS allocated,
         round(r.rake_amount - COALESCE(SUM(ra.weighted_rake_credit), 0), 2) AS difference
    FROM public.rake_records r
    LEFT JOIN public.rake_attributions ra ON ra.hand_id = r.hand_id
   WHERE r.rake_method = 'WEIGHTED_CONTRIBUTED'
     AND r.hand_id IS NOT NULL
     AND r.rake_amount > 0
     AND r.player_contributions IS NOT NULL
     AND r.created_at > now() - make_interval(hours => GREATEST(COALESCE(p_hours, 24), 1))
   GROUP BY r.hand_id, r.rake_amount
  HAVING round(r.rake_amount - COALESCE(SUM(ra.weighted_rake_credit), 0), 2) <> 0;
$$;


ALTER FUNCTION public.fn_rake_attribution_drift(p_hours integer) OWNER TO postgres;

--
-- Name: fn_rake_attribution_drift_audit(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_attribution_drift_audit(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_n bigint := 0;
  v_chips numeric := 0;
  v_sample jsonb := '[]'::jsonb;
BEGIN
  SELECT count(*), COALESCE(SUM(difference), 0),
         COALESCE(jsonb_agg(jsonb_build_object('hand', hand_id, 'rake', rake_amount,
                                               'allocated', allocated, 'diff', difference)), '[]'::jsonb)
    INTO v_n, v_chips, v_sample
    FROM (SELECT * FROM public.fn_rake_attribution_drift(p_hours) LIMIT 25) d;

  IF v_n > 0 THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    VALUES ('critical', 'fn_rake_attribution_drift_audit',
            'RAKE_ALLOCATION_MISMATCH (db-side watchdog): ' || v_n ||
              ' weighted hand(s) in the last ' || p_hours || 'h whose per-player ledger does not ' ||
              'sum to the rake collected (net ' || round(v_chips, 2) || ' chips). The allocator ' ||
              'guarantees this by construction, so a hit means a lost ledger write or disagreeing code.',
            jsonb_build_object('hours', p_hours, 'hands', v_n,
                               'net_chips', round(v_chips, 2), 'sample', v_sample));
  END IF;

  RETURN jsonb_build_object('hours', p_hours, 'drift_hands', v_n, 'net_chips', round(v_chips, 2));
END $$;


ALTER FUNCTION public.fn_rake_attribution_drift_audit(p_hours integer) OWNER TO postgres;

--
-- Name: fn_rake_bbj_audit(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_bbj_audit(p_hours integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows jsonb;
  v_total bigint;
  v_money bigint;
  v_meter jsonb;
  v_cleared integer := 0;
BEGIN
  SELECT COALESCE(jsonb_object_agg(check_name, jsonb_build_object('n', violations, 'sample', detail)), '{}'::jsonb),
         COALESCE(SUM(violations), 0),
         COALESCE(SUM(violations) FILTER (WHERE check_name IN
           ('I3_deductions_exceed_pot','I5_drop_not_banked_to_pool','I7_raked_hand_never_banked')), 0)
    INTO v_rows, v_total, v_money
    FROM public.fn_rake_bbj_invariants(p_hours);

  IF v_total > 0 THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    VALUES (CASE WHEN v_money > 0 THEN 'critical' ELSE 'warning' END,
            'fn_rake_bbj_audit',
            'RAKE_BBJ_INVARIANT_VIOLATION: ' || v_total ||
              ' violation(s) in the last ' || p_hours || 'h. The collection law is: drop on every ' ||
              'flop with 3+ dealt; deductions never exceed the pot; every fee banked and attributed.',
            v_rows);
  ELSE
    /* THE NET IS EXPECTED TO FIND NOTHING (10.11 rule 5, added 2026-09-07).
       This raised alerts and could not close one. 24 criticals were open when
       that was noticed, oldest 2026-08-31, every one of them
       I7_raked_hand_never_banked - rake the engine took from a pot and did not
       survive to bank, which fn_rake_repair_unbanked recovers. The invariants
       had been clean for 21 hours and the list still read critical.
       A clean window resolves what this source raised before it. */
    UPDATE public.financial_alerts fa
       SET resolved = true,
           resolved_at = now(),
           resolution = format(
             'Cleared by fn_rake_bbj_audit: every rake/BBJ invariant returned zero over the last %sh, so the condition this alert reported no longer holds. Raked hands that were never banked are recovered by fn_rake_repair_unbanked; if this class returns, a new alert is raised rather than this one staying open.',
             p_hours)
     WHERE fa.source = 'fn_rake_bbj_audit'
       AND fa.resolved IS NOT TRUE
       AND fa.created_at < now();
    GET DIAGNOSTICS v_cleared = ROW_COUNT;
  END IF;

  BEGIN
    v_meter := public.fn_bbj_reconcile_all();
  EXCEPTION WHEN OTHERS THEN
    v_meter := jsonb_build_object('error', SQLERRM);
  END;

  RETURN jsonb_build_object('checked_hours', p_hours, 'violations', v_total,
                            'money_violations', v_money, 'alerts_cleared', v_cleared,
                            'detail', v_rows, 'meter', v_meter);
END $$;


ALTER FUNCTION public.fn_rake_bbj_audit(p_hours integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_rake_bbj_audit(p_hours integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_rake_bbj_audit(p_hours integer) IS 'Rake / BBJ collection invariants over the last p_hours. Raises one alert when anything is violated, and RESOLVES what it raised earlier when the window comes back clean - before 2026-09-07 it could only raise, and 24 criticals stood open over invariants that had returned zero for 21 hours. service_role only.';


--
-- Name: fn_rake_bbj_invariants(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_bbj_invariants(p_hours integer DEFAULT 2) RETURNS TABLE(check_name text, violations bigint, detail jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(hours => GREATEST(COALESCE(p_hours, 2), 1));
  -- Rule checks: settlement is not instant, but nothing heals a broken rule.
  v_grace timestamptz := now() - interval '5 minutes';
  /* Self-healing checks: ASK the healer when it last ran instead of guessing.
     A hand the healer has not yet seen is not a hand the healer failed on, and
     a fifteen-minute literal against an hourly healer is what turned this
     check into 24 critical false alarms in a week. */
  v_bbj_heal   timestamptz;
  v_rake_heal  timestamptz;
  v_bbj_src    text := 'cron';
  v_rake_src   text := 'cron';
  v_min_dealt integer;
  v_inelig text[];
BEGIN
  SELECT r.bbj_min_players_dealt, r.bbj_ineligible_variants INTO v_min_dealt, v_inelig
    FROM public.ca_rake_rules r WHERE r.id = 1;

  BEGIN
    SELECT max(d.end_time) INTO v_bbj_heal
      FROM cron.job_run_details d JOIN cron.job j ON j.jobid = d.jobid
     WHERE j.jobname = 'ca-bbj-repair-unbanked-15m' AND d.status = 'succeeded';
    SELECT max(d.end_time) INTO v_rake_heal
      FROM cron.job_run_details d JOIN cron.job j ON j.jobid = d.jobid
     WHERE j.jobname = 'rake-repair-unbanked-hourly' AND d.status = 'succeeded';
  EXCEPTION WHEN OTHERS THEN
    v_bbj_heal := NULL; v_rake_heal := NULL;
  END;

  IF v_bbj_heal IS NULL THEN
    v_bbj_heal := now() - interval '2 hours'; v_bbj_src := 'fallback';
  ELSE
    v_bbj_heal := v_bbj_heal - interval '10 minutes';
  END IF;
  IF v_rake_heal IS NULL THEN
    v_rake_heal := now() - interval '2 hours'; v_rake_src := 'fallback';
  ELSE
    v_rake_heal := v_rake_heal - interval '10 minutes';
  END IF;

  RETURN QUERY
  WITH scope AS (
    SELECT r.hand_id, r.rake_amount, COALESCE(r.bbj_contribution, 0) AS bbj,
           r.pot_size, r.num_players, r.rake_method, r.player_contributions,
           r.created_at, hh.created_at AS hand_at,
           t.id AS tid, t.small_blind, t.big_blind, t.club_id,
           lower(COALESCE(hh.game_variant, t.game_variant::text)) AS variant,
           COALESCE(array_length(hh.community_cards, 1), 0) AS board
      FROM rake_records r
      JOIN tables t ON t.id = r.table_id
      LEFT JOIN hand_history hh ON hh.id = r.hand_id
     WHERE r.source = 'atomic_distribute_rake'
       AND r.created_at >= v_since AND r.created_at < v_grace
       AND t.tournament_id IS NULL AND r.is_tournament IS NOT TRUE
  )
  SELECT 'I1_drop_under_3_dealt'::text, count(*)::bigint,
         COALESCE(jsonb_agg(jsonb_build_object('hand', hand_id, 'n', num_players)) FILTER (WHERE true), '[]'::jsonb)
    FROM (SELECT hand_id, num_players FROM scope
           WHERE bbj > 0 AND num_players IS NOT NULL AND num_players < v_min_dealt LIMIT 20) x
  UNION ALL
  SELECT 'I2_drop_on_ineligible_variant', count(*)::bigint,
         COALESCE(jsonb_agg(jsonb_build_object('hand', hand_id, 'variant', variant)), '[]'::jsonb)
    FROM (SELECT hand_id, variant FROM scope
           WHERE bbj > 0 AND variant = ANY (v_inelig) LIMIT 20) x
  UNION ALL
  SELECT 'I3_deductions_exceed_pot', count(*)::bigint,
         COALESCE(jsonb_agg(jsonb_build_object('hand', hand_id, 'pot', pot_size, 'take', take)), '[]'::jsonb)
    FROM (SELECT hand_id, pot_size, rake_amount + bbj AS take FROM scope
           WHERE pot_size IS NOT NULL AND pot_size > 0
             AND rake_amount + bbj > pot_size + 0.001 LIMIT 20) x
  UNION ALL
  SELECT 'I4_eligible_flop_no_drop', count(*)::bigint,
         COALESCE(jsonb_agg(jsonb_build_object('hand', hand_id, 'n', num_players, 'board', board, 'expected', expected)), '[]'::jsonb)
    FROM (SELECT s.hand_id, s.num_players, s.board,
                 public.fn_effective_bbj_drop(s.big_blind, s.num_players, s.board >= 3, s.club_id,
                                              s.tid, s.variant, s.small_blind, s.pot_size, s.rake_amount) AS expected
            FROM scope s
           WHERE s.bbj = 0 AND s.board >= 3
             AND public.fn_effective_bbj_drop(s.big_blind, s.num_players, s.board >= 3, s.club_id,
                                              s.tid, s.variant, s.small_blind, s.pot_size, s.rake_amount) > 0
           LIMIT 20) x
  UNION ALL
  SELECT 'I5_drop_not_banked_to_pool', count(*)::bigint,
         jsonb_build_object('grace_until', v_bbj_heal, 'grace_source', v_bbj_src,
                            'healer', 'ca-bbj-repair-unbanked-15m',
                            'hands', COALESCE(jsonb_agg(jsonb_build_object('hand', hand_id, 'bbj', bbj)), '[]'::jsonb))
    FROM (SELECT s.hand_id, s.bbj FROM scope s
           WHERE s.bbj > 0 AND s.hand_id IS NOT NULL
             AND s.created_at < v_bbj_heal
             AND NOT EXISTS (SELECT 1 FROM bbj_contributions b
                              WHERE b.hand_id = s.hand_id
                                AND abs(b.amount - s.bbj) <= 0.01) LIMIT 20) x
  UNION ALL
  SELECT 'I6_ledger_not_reconciled', count(*)::bigint,
         COALESCE(jsonb_agg(jsonb_build_object('hand', hand_id, 'rake', rake_amount, 'alloc', alloc)), '[]'::jsonb)
    FROM (SELECT s.hand_id, s.rake_amount,
                 (SELECT COALESCE(SUM(ra.weighted_rake_credit), 0)
                    FROM rake_attributions ra WHERE ra.hand_id = s.hand_id) AS alloc
            FROM scope s
           WHERE s.rake_method = 'WEIGHTED_CONTRIBUTED' AND s.rake_amount > 0
             AND s.hand_id IS NOT NULL AND s.player_contributions IS NOT NULL
             AND round((SELECT COALESCE(SUM(ra.weighted_rake_credit), 0)
                          FROM rake_attributions ra WHERE ra.hand_id = s.hand_id), 2)
                 <> round(s.rake_amount, 2) LIMIT 20) x
  UNION ALL
  SELECT 'I7_raked_hand_never_banked', count(*)::bigint,
         jsonb_build_object('grace_until', v_rake_heal, 'grace_source', v_rake_src,
                            'healer', 'rake-repair-unbanked-hourly',
                            'means', 'the healer has SEEN these hands and did not fix them - a genuine loss. Hands the healer DID rescue are counted by I8, which is the number that says how often the live path failed.',
                            'hands', COALESCE(jsonb_agg(jsonb_build_object('hand', id, 'rake', rake_amount)), '[]'::jsonb))
    FROM (SELECT hh.id, hh.rake_amount
            FROM hand_history hh
            JOIN tables t ON t.id = hh.table_id
           WHERE hh.tournament_id IS NULL AND t.tournament_id IS NULL
             AND t.club_id IS NOT NULL AND hh.rake_amount > 0
             AND hh.created_at >= v_since
             AND hh.created_at < v_rake_heal
             AND NOT EXISTS (SELECT 1 FROM rake_records rr WHERE rr.hand_id = hh.id)
             AND NOT EXISTS (SELECT 1 FROM rake_records rr2
                              WHERE rr2.table_id = hh.table_id
                                AND rr2.created_at BETWEEN hh.created_at - interval '2 hours'
                                                       AND hh.created_at + interval '12 hours'
                                AND rr2.metadata->>'hand_number' = hh.hand_number::text)
           LIMIT 20) x
  UNION ALL
  /* I8: HOW OFTEN THE LIVE PATH FAILED, which I7 deliberately cannot say.
     Making I7 wait for its healer (20260907165636) was right for alarming and
     wrong for measuring: with the repair job ON, I7 now reads zero while the
     engine drops a hand's whole post-hand tail every few minutes, and
     BAND-AIDS-REGISTER TIER 1 #5 uses I7 returning zero as the criterion for
     deleting the repair job. A zero that only means "the healer got there
     first" is exactly the signal CLAUDE.md 10.86 forbids.
     So the rescue is COUNTED, beside the loss, with its own name. It carries
     violations 0 on purpose: it must never raise on its own (that is the
     hourly critical this phase just removed), and under CLAUDE.md 10.12 every
     one of these is a P0 to be read, not paged on. */
  SELECT 'I8_rake_banked_late_by_a_healer', 0::bigint,
         jsonb_build_object(
           'hands', (SELECT count(*) FROM scope s
                      WHERE s.hand_at IS NOT NULL
                        AND s.created_at - s.hand_at > interval '5 minutes'),
           'chips', (SELECT COALESCE(round(sum(s.rake_amount), 2), 0) FROM scope s
                      WHERE s.hand_at IS NOT NULL
                        AND s.created_at - s.hand_at > interval '5 minutes'),
           'window_hours', p_hours,
           'means', 'rake the engine took from a pot and did not itself bank; a healer wrote the row later, with p_contributions NULL, so these hands earn nobody VIP points, agent commission or rakeback. CLAUDE.md 10.12: a repair job firing is a P0, not a success. Root fix and delete-when: BAND-AIDS-REGISTER TIER 1 #5.',
           'raises', 'never - this is a measurement, not an alarm. I7 is the alarm.');
END $$;


ALTER FUNCTION public.fn_rake_bbj_invariants(p_hours integer) OWNER TO postgres;

--
-- Name: fn_rake_cap_for_dealt(numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_cap_for_dealt(p_full_cap numeric, p_players_dealt integer) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
           WHEN p_players_dealt >= r.short_handed_max_players + 1 THEN p_full_cap
           WHEN p_players_dealt >= r.short_handed_max_players     THEN round(p_full_cap * r.short_handed_cap_factor, 2)
           WHEN p_players_dealt >= 2                              THEN round(p_full_cap * r.heads_up_cap_factor, 2)
           ELSE p_full_cap
         END
    FROM public.ca_rake_rules r
   WHERE r.id = 1;
$$;


ALTER FUNCTION public.fn_rake_cap_for_dealt(p_full_cap numeric, p_players_dealt integer) OWNER TO postgres;

--
-- Name: fn_rake_club_isolation_violations(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_club_isolation_violations() RETURNS TABLE(rake_id uuid, row_club uuid, owner uuid, kind text, amount numeric, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH scoped AS (
    SELECT rr.id, rr.club_id AS row_club, rr.rake_amount, rr.created_at,
           COALESCE(t.club_id, tt.club_id) AS owner,
           CASE WHEN rr.table_id IS NOT NULL THEN 'table' ELSE 'tournament' END AS kind
      FROM public.rake_records rr
      LEFT JOIN public.tables t ON t.id = rr.table_id
      LEFT JOIN public.tournaments tt ON tt.id = rr.tournament_id
     WHERE rr.club_id IS NOT NULL
       AND COALESCE(t.club_id, tt.club_id) IS NOT NULL
  )
  SELECT s.id, s.row_club, s.owner, s.kind, s.rake_amount, s.created_at
    FROM scoped s
   WHERE s.row_club <> s.owner
     -- owner is a union and row_club is a member club: ok
     AND NOT (
       EXISTS (SELECT 1 FROM public.unions u WHERE u.id = s.owner)
       AND EXISTS (SELECT 1 FROM public.clubs c
                    WHERE c.id = s.row_club
                      AND (c.union_id = s.owner
                           OR EXISTS (SELECT 1 FROM public.union_clubs uc
                                       WHERE uc.club_id = c.id AND uc.union_id = s.owner)))
     )
     -- owner is a club in a union and row_club is a sibling in that union: ok
     AND NOT EXISTS (
       SELECT 1 FROM public.clubs oc
        JOIN public.clubs rc ON rc.id = s.row_club
       WHERE oc.id = s.owner AND oc.union_id IS NOT NULL
         AND (rc.union_id = oc.union_id OR rc.id = oc.union_id)
     );
$$;


ALTER FUNCTION public.fn_rake_club_isolation_violations() OWNER TO postgres;

--
-- Name: fn_rake_law_check(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_law_check(p_window interval DEFAULT '02:00:00'::interval) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new integer;
BEGIN
  WITH v AS (
    SELECT * FROM public.fn_rake_law_violations(p_window)
  ), ins AS (
    INSERT INTO public.ledger_reconcile_log
      (run_date, run_ts, entity_type, entity_id, ledger_balance, stored_balance,
       severity, metadata, notes)
    SELECT CURRENT_DATE, now(), 'rake_law', v.table_id,
           v.allowed, v.rake,
           CASE WHEN v.kind IN ('board_not_recorded', 'players_not_recorded', 'bbj_club_switch_ignored')
                THEN 'warn' ELSE 'critical' END,
           jsonb_build_object(
             'kind', v.kind,
             'hand_id', v.hand_id,
             'occurred_at', v.occurred_at,
             'stake', v.small_blind::text || '/' || v.big_blind::text,
             'pot', v.pot,
             'spec_checksum', public.fn_rake_spec_checksum()),
           v.kind || ': took ' || v.rake::text || ' where the spec says ' || v.allowed::text
      FROM v
     WHERE NOT EXISTS (
       SELECT 1 FROM public.ledger_reconcile_log l
        WHERE l.entity_type = 'rake_law'
          AND l.metadata->>'hand_id' = v.hand_id::text
          AND l.metadata->>'kind' = v.kind)
    RETURNING 1
  )
  SELECT count(*) INTO v_new FROM ins;
  RETURN v_new;
END;
$$;


ALTER FUNCTION public.fn_rake_law_check(p_window interval) OWNER TO postgres;

--
-- Name: fn_rake_law_violations(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_law_violations(p_window interval DEFAULT '01:00:00'::interval) RETURNS TABLE(kind text, hand_id uuid, table_id uuid, occurred_at timestamp with time zone, small_blind numeric, big_blind numeric, pot numeric, rake numeric, allowed numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH h AS (
    SELECT hh.id, hh.table_id, hh.created_at,
           COALESCE(hh.rake_amount, 0) AS rake,
           COALESCE(rr.bbj_contribution, hh.bbj_amount, 0) AS bbj,
           hh.pot_size AS pot,
           t.small_blind AS sb, t.big_blind AS bb, t.club_id, t.id AS tid,
           lower(COALESCE(hh.game_variant, t.game_variant::text)) AS variant,
           COALESCE(rr.num_players, jsonb_array_length(CASE WHEN jsonb_typeof(hh.players) = 'array' THEN hh.players END)) AS dealt,
           COALESCE(array_length(hh.community_cards, 1), 0)
             + COALESCE(array_length(hh.community_cards2, 1), 0) AS board_n,
           hh.showdown IS NOT NULL AS has_showdown,
           (SELECT count(*) FROM jsonb_array_elements(COALESCE(hh.actions, '[]'::jsonb)) a
             WHERE a->>'action' IN ('call','raise','bet','allin','all-in')) AS agg,
           CASE WHEN t.rake_percent >= 0 THEN t.rake_percent
                WHEN c.default_rake_percent >= 0 THEN c.default_rake_percent END AS ov_pct,
           CASE WHEN t.rake_cap_bb >= 0 THEN t.rake_cap_bb
                WHEN c.rake_cap >= 0 THEN c.rake_cap END AS ov_cap_bb,
           c.bbj_rake_enabled
      FROM public.hand_history hh
      JOIN public.tables t ON t.id = hh.table_id
      LEFT JOIN public.clubs c ON c.id = t.club_id
      LEFT JOIN public.rake_records rr ON rr.hand_id = hh.id
     WHERE hh.created_at > now() - p_window
       AND hh.created_at < now() - interval '5 minutes'   -- settlement is not instant
       AND t.tournament_id IS NULL
       AND hh.tournament_id IS NULL
  ), f AS (
    -- Hands with a board on record: the spec is checkable.
    SELECT h.*, e.rake AS exp_rake
      FROM h
      CROSS JOIN LATERAL public.fn_effective_rake(h.bb, h.pot, h.dealt, true, h.sb, h.ov_pct, h.ov_cap_bb) e
     WHERE h.board_n >= 3 AND h.dealt IS NOT NULL
  ), fb AS (
    SELECT f.*, public.fn_effective_bbj_drop(f.bb, f.dealt, true, f.club_id, f.tid, f.variant, f.sb, f.pot, f.rake) AS exp_bbj
      FROM f
  ), h0 AS (
    -- The RAKELESS impossible hands: a recorded showdown over fewer than three
    -- board cards is the stale-runout corruption's signature.
    SELECT hh.id, hh.table_id, hh.created_at, hh.pot_size AS pot,
           t.small_blind AS sb, t.big_blind AS bb
      FROM public.hand_history hh
      JOIN public.tables t ON t.id = hh.table_id
     WHERE hh.created_at > now() - p_window
       AND hh.created_at < now() - interval '5 minutes'
       AND t.tournament_id IS NULL
       AND COALESCE(hh.rake_amount, 0) = 0
       AND hh.showdown IS NOT NULL
       AND COALESCE(array_length(hh.community_cards, 1), 0)
             + COALESCE(array_length(hh.community_cards2, 1), 0) < 3
  )
  SELECT 'over_spec', id, table_id, created_at, sb, bb, pot, rake, exp_rake
    FROM fb WHERE rake > exp_rake + 0.005
  UNION ALL
  SELECT 'under_spec', id, table_id, created_at, sb, bb, pot, rake, exp_rake
    FROM fb WHERE rake < exp_rake - 0.005
  UNION ALL
  SELECT 'bbj_over_spec', id, table_id, created_at, sb, bb, pot, bbj, exp_bbj
    FROM fb WHERE bbj > exp_bbj + 0.005
  UNION ALL
  SELECT 'bbj_under_spec', id, table_id, created_at, sb, bb, pot, bbj, exp_bbj
    FROM fb WHERE bbj < exp_bbj - 0.005
  UNION ALL
  SELECT 'bbj_club_switch_ignored', id, table_id, created_at, sb, bb, pot, bbj, 0
    FROM fb WHERE bbj > 0 AND bbj_rake_enabled IS FALSE
  UNION ALL
  SELECT 'players_not_recorded', id, table_id, created_at, sb, bb, pot, rake, rake
    FROM h WHERE board_n >= 3 AND dealt IS NULL AND (rake > 0 OR bbj > 0)
  UNION ALL
  SELECT 'no_flop_no_drop', id, table_id, created_at, sb, bb, pot, rake + bbj, 0
    FROM h WHERE board_n < 3 AND (rake > 0 OR bbj > 0) AND NOT has_showdown AND agg <= 3
  UNION ALL
  SELECT 'board_not_recorded', id, table_id, created_at, sb, bb, pot, rake, rake
    FROM h WHERE board_n < 3 AND (rake > 0 OR bbj > 0) AND (has_showdown OR agg > 3)
  UNION ALL
  SELECT 'impossible_showdown', id, table_id, created_at, sb, bb, pot, 0, 0
    FROM h0;
$$;


ALTER FUNCTION public.fn_rake_law_violations(p_window interval) OWNER TO postgres;

--
-- Name: fn_rake_record_is_ghost_twin(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_record_is_ghost_twin(p_hand_id uuid, p_table_id uuid, p_metadata jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
  /* A null-hand rake_records row is a ghost twin when the same table carries a
     LINKED row for the same GLOBAL hand number. Hand numbers are unique only
     from 1,000,000 up (uq_hand_history_global_hand_number); below that they
     recurred per table before 2026-07-31 and a match proves nothing. */
  SELECT p_hand_id IS NULL
     AND p_table_id IS NOT NULL
     AND COALESCE(p_metadata->>'hand_number', '') ~ '^[0-9]{1,18}$'
     AND (p_metadata->>'hand_number')::bigint >= 1000000
     AND EXISTS (SELECT 1 FROM public.rake_records l
                  WHERE l.table_id = p_table_id AND l.hand_id IS NOT NULL
                    AND l.metadata->>'hand_number' = p_metadata->>'hand_number');
$_$;


ALTER FUNCTION public.fn_rake_record_is_ghost_twin(p_hand_id uuid, p_table_id uuid, p_metadata jsonb) OWNER TO postgres;

--
-- Name: fn_rake_repair_unbanked(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_repair_unbanked(p_since_hours integer DEFAULT 48, p_limit integer DEFAULT 200) RETURNS TABLE(hand_id uuid, club_id uuid, amount numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '540s'
    AS $$
DECLARE
  r record;
  v_repaired int := 0;
  v_chips numeric := 0;
BEGIN
  FOR r IN
    SELECT hh.id AS h_id, hh.table_id, t.club_id AS c_id, hh.hand_number,
           hh.rake_amount, COALESCE(hh.bbj_amount, 0) AS bbj, hh.pot_size,
           hh.created_at AS h_at,
           CASE WHEN hh.created_at >= '2026-08-29 14:41+00'::timestamptz
                THEN 'WEIGHTED_CONTRIBUTED' ELSE 'DEALT_EQUAL' END AS method
      FROM public.hand_history hh
      JOIN public.tables t ON t.id = hh.table_id
     WHERE hh.tournament_id IS NULL
       AND t.tournament_id IS NULL
       AND hh.rake_amount > 0
       AND hh.created_at > now() - make_interval(hours => GREATEST(COALESCE(p_since_hours, 48), 1))
       AND hh.created_at < now() - interval '5 minutes'
       AND t.club_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.rake_records rr WHERE rr.hand_id = hh.id)
       -- time-bounded so the probe rides the created_at index: a hand's rake
       -- row is written within minutes (re-drives within hours) of the hand
       AND NOT EXISTS (SELECT 1 FROM public.rake_records rr2
                        WHERE rr2.table_id = hh.table_id
                          AND rr2.created_at BETWEEN hh.created_at - interval '2 hours'
                                                 AND hh.created_at + interval '12 hours'
                          AND rr2.metadata->>'hand_number' = hh.hand_number::text)
       AND NOT EXISTS (SELECT 1 FROM public.pending_fee_distributions p
                        WHERE p.resolved_at IS NULL AND p.kind = 'rake'
                          AND (p.hand_id = hh.id OR p.hand_number = hh.hand_number))
     ORDER BY hh.created_at
     LIMIT GREATEST(COALESCE(p_limit, 200), 1)
  LOOP
    BEGIN
      PERFORM public.atomic_distribute_rake(
        r.table_id, r.c_id, r.h_id, r.hand_number::integer, r.rake_amount,
        r.bbj, r.pot_size, NULL, NULL, NULL, NULL, r.method);
      v_repaired := v_repaired + 1;
      v_chips := v_chips + r.rake_amount;
      hand_id := r.h_id; club_id := r.c_id; amount := r.rake_amount;
      RETURN NEXT;
    EXCEPTION WHEN others THEN
      NULL; -- next cycle retries; the candidate predicate re-evaluates
    END;
  END LOOP;

  IF v_repaired > 0 THEN
    INSERT INTO public.financial_alerts (severity, source, message, context, resolved, resolved_at)
    VALUES (CASE WHEN v_chips > 50 THEN 'warning' ELSE 'info' END,
            'fn_rake_repair_unbanked',
            'Recovered ' || v_repaired || ' unbanked rake hand(s) totalling ' ||
              round(v_chips, 2) || ' chips (engine did not survive to bank them). ' ||
              'Attribution not invented: contributions were lost with the engine.',
            jsonb_build_object('repaired', v_repaired, 'chips', round(v_chips, 2)),
            (v_chips <= 50), CASE WHEN v_chips <= 50 THEN now() ELSE NULL END);
  END IF;

  RETURN;
END $$;


ALTER FUNCTION public.fn_rake_repair_unbanked(p_since_hours integer, p_limit integer) OWNER TO postgres;

--
-- Name: fn_rake_schedule_drift(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_schedule_drift() RETURNS TABLE(small_blind numeric, big_blind numeric, charged_cap numeric, proposed_cap numeric, charged_cap_bb numeric, hands_48h bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT p.sb, p.bb,
         public.fn_effective_rake_cap(p.sb, p.bb),
         p.rake_cap,
         round(public.fn_effective_rake_cap(p.sb, p.bb) / NULLIF(p.bb, 0), 2),
         (SELECT count(*) FROM public.hand_history h
            JOIN public.tables t ON t.id = h.table_id
           WHERE t.tournament_id IS NULL
             AND t.small_blind = p.sb AND t.big_blind = p.bb
             AND h.created_at > now() - interval '48 hours'
             AND COALESCE(h.rake_amount, 0) > 0)
    FROM public.ca_rake_schedule p
   WHERE p.source = 'proposed'
     AND public.fn_effective_rake_cap(p.sb, p.bb) IS DISTINCT FROM p.rake_cap
   ORDER BY p.bb;
$$;


ALTER FUNCTION public.fn_rake_schedule_drift() OWNER TO postgres;

--
-- Name: fn_rake_shares_for_record(uuid, numeric, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_shares_for_record(p_hand_id uuid, p_rake numeric, p_contributions jsonb, p_method text) RETURNS TABLE(user_id uuid, credit numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT ra.player_id, ra.weighted_rake_credit
    FROM public.rake_attributions ra
   WHERE p_hand_id IS NOT NULL AND ra.hand_id = p_hand_id
  UNION ALL
  SELECT a.user_id, a.credit
    FROM public.fn_allocate_rake_credits(p_rake, p_contributions, p_method) a
   WHERE p_hand_id IS NULL
      OR NOT EXISTS (SELECT 1 FROM public.rake_attributions ra2 WHERE ra2.hand_id = p_hand_id);
$$;


ALTER FUNCTION public.fn_rake_shares_for_record(p_hand_id uuid, p_rake numeric, p_contributions jsonb, p_method text) OWNER TO postgres;

--
-- Name: fn_rake_spec_canonical(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_spec_canonical() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT '{"caps":['
      || COALESCE((SELECT string_agg(
                     format('{"bb":"%s","dealt":%s,"cap":"%s"}',
                            round(c.bb, 2)::text, c.players_dealt, round(c.rake_cap, 2)::text),
                     ',' ORDER BY c.bb, c.players_dealt)
                     FROM public.ca_rake_schedule_caps c), '')
      || '],"rules":'
      || (SELECT format(
            '{"bbj_ineligible_variants":[%s],"bbj_min_players_dealt":%s,"bbj_min_pot_bb":%s,'
            || '"heads_up_cap_factor":"%s","heads_up_percent":"%s","max_rake_cap_bb":"%s",'
            || '"max_rake_percent":"%s","no_flop_no_drop":%s,"short_handed_cap_factor":"%s",'
            || '"short_handed_max_players":%s,"unscheduled_cap_bb":"%s"}',
            COALESCE((SELECT string_agg(to_json(v)::text, ',' ORDER BY v COLLATE "C")
                        FROM unnest(r.bbj_ineligible_variants) AS v), ''),
            r.bbj_min_players_dealt,
            r.bbj_min_pot_bb,
            round(r.heads_up_cap_factor, 2)::text,
            round(r.heads_up_percent, 2)::text,
            round(r.max_rake_cap_bb, 2)::text,
            round(r.max_rake_percent, 2)::text,
            CASE WHEN r.no_flop_no_drop THEN 'true' ELSE 'false' END,
            round(r.short_handed_cap_factor, 2)::text,
            r.short_handed_max_players,
            round(public.fn_unscheduled_cap_bb(), 2)::text)
            FROM public.ca_rake_rules r WHERE r.id = 1)
      || ',"schedule":['
      || COALESCE((SELECT string_agg(
                     format('{"sb":"%s","bb":"%s","rake_percent":"%s","rake_cap":"%s","bbj_fee_bb":"%s"}',
                            round(s.sb, 2)::text, round(s.bb, 2)::text, round(s.rake_percent, 2)::text,
                            round(s.rake_cap, 2)::text, round(s.bbj_fee_bb, 2)::text),
                     ',' ORDER BY s.bb, s.sb)
                     FROM public.ca_rake_schedule s WHERE s.source = 'engine_mirror'), '')
      || '],"tiers":['
      || COALESCE((SELECT string_agg(
                     format('{"label":%s,"min_bb":"%s","max_bb":%s,"rake_percent":"%s","rake_cap":"%s","bbj_fee_bb":"%s"}',
                            to_json(lower(t.label))::text, round(t.min_bb, 2)::text,
                            CASE WHEN t.max_bb IS NULL THEN 'null' ELSE '"' || round(t.max_bb, 2)::text || '"' END,
                            round(t.rake_percent, 2)::text, round(t.rake_cap, 2)::text, round(t.bbj_fee_bb, 2)::text),
                     ',' ORDER BY t.min_bb)
                     FROM public.ca_rake_tier t), '')
      || ']}';
$$;


ALTER FUNCTION public.fn_rake_spec_canonical() OWNER TO postgres;

--
-- Name: fn_rake_spec_checksum(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_spec_checksum() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT md5(public.fn_rake_spec_canonical());
$$;


ALTER FUNCTION public.fn_rake_spec_checksum() OWNER TO postgres;

--
-- Name: FUNCTION fn_rake_spec_checksum(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_rake_spec_checksum() IS 'md5 of fn_rake_spec_canonical(). The engine compares this with rakeSpecChecksum() at boot and every minute; a mismatch raises RakeSpec.drift and holds cash tables at their next hand boundary until the two agree.';


--
-- Name: fn_rake_spec_rebuild_caps(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_spec_rebuild_caps() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_n integer;
BEGIN
  DELETE FROM public.ca_rake_schedule_caps;
  INSERT INTO public.ca_rake_schedule_caps (bb, players_dealt, rake_cap, source)
  SELECT s.bb, d.dealt, public.fn_rake_cap_for_dealt(s.rake_cap, d.dealt), 'schedule'
    FROM public.ca_rake_schedule s
    CROSS JOIN (VALUES (2), (3), (4)) AS d(dealt)
   WHERE s.source = 'engine_mirror';
  INSERT INTO public.ca_rake_schedule_caps (bb, players_dealt, rake_cap, source)
  SELECT x.bb, d.dealt, public.fn_rake_cap_for_dealt(tp.rake_cap, d.dealt), 'tier_fallback'
    FROM public.ca_rake_rules r
    CROSS JOIN LATERAL unnest(r.tier_priced_big_blinds) AS x(bb)
    CROSS JOIN LATERAL public.fn_rake_tier_price(x.bb) tp
    CROSS JOIN (VALUES (2), (3), (4)) AS d(dealt)
   WHERE r.id = 1
     AND NOT EXISTS (SELECT 1 FROM public.ca_rake_schedule s
                      WHERE s.source = 'engine_mirror' AND abs(s.bb - x.bb) < 0.001);
  SELECT count(*) INTO v_n FROM public.ca_rake_schedule_caps;
  RETURN v_n;
END;
$$;


ALTER FUNCTION public.fn_rake_spec_rebuild_caps() OWNER TO postgres;

--
-- Name: fn_rake_spec_self_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_spec_self_check() RETURNS TABLE(bb numeric, players_dealt integer, stored_cap numeric, derived_cap numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT c.bb, c.players_dealt, c.rake_cap,
         public.fn_rake_cap_for_dealt(
           COALESCE((SELECT p.rake_cap FROM public.fn_rake_stake_price(c.bb) p),
                    (SELECT t.rake_cap FROM public.fn_rake_tier_price(c.bb) t)),
           c.players_dealt)
    FROM public.ca_rake_schedule_caps c
   WHERE c.rake_cap IS DISTINCT FROM public.fn_rake_cap_for_dealt(
           COALESCE((SELECT p.rake_cap FROM public.fn_rake_stake_price(c.bb) p),
                    (SELECT t.rake_cap FROM public.fn_rake_tier_price(c.bb) t)),
           c.players_dealt);
$$;


ALTER FUNCTION public.fn_rake_spec_self_check() OWNER TO postgres;

--
-- Name: fn_rake_stake_price(numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_stake_price(p_bb numeric, p_sb numeric DEFAULT NULL::numeric) RETURNS TABLE(rake_percent numeric, rake_cap numeric, bbj_fee_bb numeric, scheduled boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT s.rake_percent, s.rake_cap, s.bbj_fee_bb, true
    FROM public.ca_rake_schedule s
   WHERE s.source = 'engine_mirror'
     AND abs(s.bb - p_bb) < 0.001
     AND (p_sb IS NULL OR abs(s.sb - p_sb) < 0.001)
   ORDER BY s.sb
   LIMIT 1;
$$;


ALTER FUNCTION public.fn_rake_stake_price(p_bb numeric, p_sb numeric) OWNER TO postgres;

--
-- Name: fn_rake_tier_price(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rake_tier_price(p_bb numeric) RETURNS TABLE(rake_percent numeric, rake_cap numeric, bbj_fee_bb numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT t.rake_percent,
         CASE WHEN p_bb > 0
              THEN LEAST(t.rake_cap, round(p_bb * public.fn_unscheduled_cap_bb(), 2))
              ELSE t.rake_cap END,
         t.bbj_fee_bb
    FROM public.ca_rake_tier t
   WHERE t.max_bb IS NULL OR p_bb <= t.max_bb
   ORDER BY t.max_bb ASC NULLS LAST
   LIMIT 1;
$$;


ALTER FUNCTION public.fn_rake_tier_price(p_bb numeric) OWNER TO postgres;

--
-- Name: fn_rakeback_periods_bulk_upsert(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rakeback_periods_bulk_upsert(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '300s'
    AS $$
DECLARE
  it jsonb;
  v_written   integer := 0;
  v_conflict  integer := 0;
  v_failed    integer := 0;
  v_first_err text := NULL;
  v_rows      integer;
BEGIN
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RETURN jsonb_build_object('written', 0, 'conflicts', 0, 'failed', 0,
                              'error', 'p_items must be a jsonb array');
  END IF;

  FOR it IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    BEGIN
      INSERT INTO rakeback_periods (
        user_id, club_id, period_start, period_end,
        rake_generated, rakeback_rate, rakeback_earned, rakeback_amount,
        total_rake_paid, status
      ) VALUES (
        (it->>'user_id')::uuid,
        (it->>'club_id')::uuid,
        (it->>'period_start')::date,
        (it->>'period_end')::date,
        COALESCE((it->>'rake_generated')::numeric, 0),
        COALESCE((it->>'rakeback_rate')::numeric, 0),
        COALESCE((it->>'rakeback_earned')::numeric, 0),
        COALESCE((it->>'rakeback_amount')::numeric, 0),
        COALESCE((it->>'total_rake_paid')::numeric, 0),
        'pending'
      )
      ON CONFLICT (user_id, club_id, period_start, period_end) DO UPDATE
        SET rake_generated  = EXCLUDED.rake_generated,
            rakeback_rate   = EXCLUDED.rakeback_rate,
            rakeback_earned = EXCLUDED.rakeback_earned,
            rakeback_amount = EXCLUDED.rakeback_amount,
            total_rake_paid = EXCLUDED.total_rake_paid
        WHERE rakeback_periods.status = 'pending';

      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows > 0 THEN v_written := v_written + 1; END IF;

    EXCEPTION
      WHEN unique_violation THEN
        -- (user_id, period_start) collision: same player, same week, different
        -- club. Pre-existing behaviour was a 409 counted as a failure.
        v_conflict := v_conflict + 1;
      WHEN OTHERS THEN
        v_failed := v_failed + 1;
        IF v_first_err IS NULL THEN v_first_err := SQLERRM; END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('written', v_written, 'conflicts', v_conflict,
                            'failed', v_failed, 'first_error', v_first_err);
END $$;


ALTER FUNCTION public.fn_rakeback_periods_bulk_upsert(p_items jsonb) OWNER TO postgres;

--
-- Name: fn_rakeback_recompute_all_clubs(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rakeback_recompute_all_clubs(p_period_start date DEFAULT NULL::date, p_period_end date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '600s'
    AS $$
DECLARE
  v_from date := COALESCE(p_period_start, (date_trunc('week', now()) - interval '7 days')::date);
  v_to   date := COALESCE(p_period_end,   (date_trunc('week', now()) - interval '1 day')::date);
  c record;
  v_one jsonb;
  v_written int := 0;
  v_clubs int := 0;
  v_failed int := 0;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_platform_admin())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  -- Every club that belongs to a union. Private club games are excluded from
  -- union numbers elsewhere; rakeback is still owed per club, so the club is
  -- the unit here.
  FOR c IN
    SELECT DISTINCT uc.club_id FROM union_clubs uc
  LOOP
    BEGIN
      v_one := public.fn_rakeback_recompute_periods(c.club_id, v_from, v_to, NULL);
      v_written := v_written + COALESCE((v_one->>'written')::int, 0);
      v_clubs := v_clubs + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      INSERT INTO financial_alerts (severity, source, message, context)
      VALUES ('warning', 'fn_rakeback_recompute_all_clubs',
              'Rakeback recompute failed for a club',
              jsonb_build_object('club_id', c.club_id, 'error', SQLERRM,
                                 'period_start', v_from, 'period_end', v_to));
    END;
  END LOOP;

  -- If the week produced rake but no rakeback rows at all, something upstream
  -- is broken and Round 3 is about to pay nobody. Say so before it happens.
  IF v_written = 0 AND EXISTS (
       SELECT 1 FROM rake_records r
        JOIN union_clubs uc ON uc.club_id = r.club_id
       WHERE r.created_at >= v_from::timestamptz
         AND r.created_at < (v_to + 1)::timestamptz
         AND r.rake_amount > 0
     ) THEN
    INSERT INTO financial_alerts (severity, source, message, context)
    VALUES ('critical', 'fn_rakeback_recompute_all_clubs',
            'Rake was generated this period but no rakeback rows were written - Round 3 will pay nobody',
            jsonb_build_object('period_start', v_from, 'period_end', v_to,
                               'clubs_processed', v_clubs));
  END IF;

  RETURN jsonb_build_object('clubs_processed', v_clubs, 'clubs_failed', v_failed,
                            'rows_written', v_written,
                            'period_start', v_from, 'period_end', v_to, 'ran_at', now());
END $$;


ALTER FUNCTION public.fn_rakeback_recompute_all_clubs(p_period_start date, p_period_end date) OWNER TO postgres;

--
-- Name: fn_rakeback_recompute_day(uuid, date, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rakeback_recompute_day(p_club_id uuid, p_day date, p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '300s'
    AS $$
DECLARE
  v_rows bigint; v_prev bigint; v_written integer := 0;
  v_from timestamptz := p_day::timestamptz;
  v_to   timestamptz := (p_day + 1)::timestamptz;
BEGIN
  IF p_club_id IS NULL OR p_day IS NULL THEN
    RETURN jsonb_build_object('written', 0, 'error', 'missing params');
  END IF;

  SELECT count(*) INTO v_rows
    FROM rake_records r
   WHERE r.club_id = p_club_id
     AND r.created_at >= v_from AND r.created_at < v_to
     AND r.rake_amount > 0 AND r.player_contributions IS NOT NULL
       -- ONE HAND, ONE RECORD: the rule is fn_rake_record_is_ghost_twin (20260908)
       AND NOT public.fn_rake_record_is_ghost_twin(r.hand_id, r.table_id, r.metadata);

  SELECT s.rows_seen INTO v_prev
    FROM rakeback_daily_state s WHERE s.club_id = p_club_id AND s.day = p_day;

  IF NOT p_force AND v_prev IS NOT NULL AND v_prev = v_rows THEN
    RETURN jsonb_build_object('written', 0, 'fresh', true, 'rows_seen', v_rows);
  END IF;

  -- Rebuild the day wholesale: DELETE then INSERT, so a user who no longer
  -- has a share for the day does not linger with a stale one.
  DELETE FROM rakeback_daily_user d
   WHERE d.club_id = p_club_id AND d.day = p_day;

  WITH rr AS (
    SELECT r.hand_id, r.rake_amount, r.player_contributions,
           COALESCE(r.rake_method, 'DEALT_EQUAL') AS method
      FROM rake_records r
     WHERE r.club_id = p_club_id
       AND r.created_at >= v_from AND r.created_at < v_to
       AND r.rake_amount > 0 AND r.player_contributions IS NOT NULL
       -- ONE HAND, ONE RECORD: the rule is fn_rake_record_is_ghost_twin (20260908)
       AND NOT public.fn_rake_record_is_ghost_twin(r.hand_id, r.table_id, r.metadata)
  ),
  -- The attribution ledger, read once as a set instead of once per record.
  att AS (
    SELECT ra.hand_id, ra.player_id AS user_id, ra.weighted_rake_credit AS credit
      FROM rake_attributions ra JOIN rr ON rr.hand_id = ra.hand_id
  ),
  -- The canonical allocator, and ONLY for hands the ledger does not cover.
  -- Same precedence fn_rake_shares_for_record applies, same single source of
  -- the share math (fn_allocate_rake_credits) - never re-derived here.
  alloc AS (
    SELECT a.user_id, a.credit
      FROM rr
      CROSS JOIN LATERAL public.fn_allocate_rake_credits(
        rr.rake_amount, rr.player_contributions, rr.method) a
     WHERE rr.hand_id IS NULL
        OR NOT EXISTS (SELECT 1 FROM att WHERE att.hand_id = rr.hand_id)
  ),
  ins AS (
    INSERT INTO rakeback_daily_user (club_id, day, user_id, cents)
    SELECT p_club_id, p_day, s.user_id, sum(round(s.credit * 100)::bigint)
      FROM (SELECT user_id, credit FROM att
            UNION ALL
            SELECT user_id, credit FROM alloc) s
     WHERE s.user_id IS NOT NULL
     GROUP BY s.user_id
    RETURNING 1
  )
  SELECT count(*) INTO v_written FROM ins;

  INSERT INTO rakeback_daily_state (club_id, day, rows_seen, computed_at)
  VALUES (p_club_id, p_day, v_rows, now())
  ON CONFLICT (club_id, day) DO UPDATE
    SET rows_seen = EXCLUDED.rows_seen, computed_at = now();

  RETURN jsonb_build_object('written', v_written, 'fresh', false, 'rows_seen', v_rows);
END $$;


ALTER FUNCTION public.fn_rakeback_recompute_day(p_club_id uuid, p_day date, p_force boolean) OWNER TO postgres;

--
-- Name: fn_rakeback_recompute_periods(uuid, date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rakeback_recompute_periods(p_club_id uuid, p_period_start date, p_period_end date, p_user_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '300s'
    AS $$
DECLARE
  v_written integer := 0; v_day date; v_days integer := 0; v_rebuilt integer := 0;
  v_res jsonb;
BEGIN
  IF p_club_id IS NULL OR p_period_start IS NULL OR p_period_end IS NULL THEN
    RETURN jsonb_build_object('written', 0, 'error', 'missing params');
  END IF;

  v_day := p_period_start;
  WHILE v_day <= p_period_end LOOP
    v_res := public.fn_rakeback_recompute_day(p_club_id, v_day, false);
    v_days := v_days + 1;
    IF COALESCE((v_res->>'fresh')::boolean, false) IS NOT TRUE THEN
      v_rebuilt := v_rebuilt + 1;
    END IF;
    v_day := v_day + 1;
  END LOOP;

  WITH totals AS (
    SELECT d.user_id, (SUM(d.cents)::numeric / 100) AS total_rake
      FROM rakeback_daily_user d
     WHERE d.club_id = p_club_id
       AND d.day >= p_period_start AND d.day <= p_period_end
       AND (p_user_ids IS NULL OR d.user_id = ANY (p_user_ids))
     GROUP BY d.user_id
  ), eligible AS (
    SELECT t.user_id, t.total_rake,
           public.fn_player_rakeback_rate(t.user_id, p_club_id, t.total_rake) AS rate
      FROM totals t
  ), ins AS (
    INSERT INTO rakeback_periods (
      user_id, club_id, period_start, period_end,
      rake_generated, rakeback_rate, rakeback_earned, rakeback_amount,
      total_rake_paid, status
    )
    SELECT e.user_id, p_club_id, p_period_start, p_period_end,
           round(e.total_rake, 2), e.rate,
           round(e.total_rake * e.rate, 2), round(e.total_rake * e.rate, 2),
           round(e.total_rake, 2), 'pending'
      FROM eligible e
     WHERE e.rate > 0
    ON CONFLICT (user_id, club_id, period_start, period_end) DO UPDATE
      SET period_end      = EXCLUDED.period_end,
          rake_generated  = EXCLUDED.rake_generated,
          rakeback_rate   = EXCLUDED.rakeback_rate,
          rakeback_earned = EXCLUDED.rakeback_earned,
          rakeback_amount = EXCLUDED.rakeback_amount,
          total_rake_paid = EXCLUDED.total_rake_paid
      WHERE rakeback_periods.status = 'pending'
    RETURNING 1
  )
  SELECT count(*) INTO v_written FROM ins;

  RETURN jsonb_build_object('written', v_written, 'days_scanned', v_days,
                            'days_rebuilt', v_rebuilt);
END $$;


ALTER FUNCTION public.fn_rakeback_recompute_periods(p_club_id uuid, p_period_start date, p_period_end date, p_user_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_rakeback_settlement_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rakeback_settlement_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ok boolean;
BEGIN
  v_ok := public.fn_caller_is_engine()
          OR (auth.uid() IS NOT NULL AND EXISTS (
                SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('god','admin')));
  IF NOT v_ok THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'pending_periods', (SELECT count(*) FROM rakeback_periods
                         WHERE status='pending' AND period_end < CURRENT_DATE),
    'pending_clubs', (SELECT count(DISTINCT club_id) FROM rakeback_periods
                       WHERE status='pending' AND period_end < CURRENT_DATE),
    'pending_players', (SELECT count(DISTINCT user_id) FROM rakeback_periods
                         WHERE status='pending' AND period_end < CURRENT_DATE),
    'estimated_owed', (SELECT COALESCE(round(sum(COALESCE(rakeback_amount, rakeback_earned, 0)),2),0)
                        FROM rakeback_periods WHERE status='pending' AND period_end < CURRENT_DATE),
    'oldest_period_end', (SELECT min(period_end) FROM rakeback_periods
                           WHERE status='pending' AND period_end < CURRENT_DATE),
    'last_paid_at', (SELECT max(paid_at) FROM rakeback_periods WHERE status='paid'),
    'by_club', (
      SELECT COALESCE(jsonb_agg(s.x ORDER BY s.owed DESC), '[]'::jsonb) FROM (
        SELECT o.owed,
               jsonb_build_object(
                 'club_id', o.club_id, 'club_name', c.name,
                 'periods', o.periods, 'players', o.players, 'owed', o.owed,
                 'treasury', round(COALESCE(c.chip_treasury,0),2),
                 'fundable', COALESCE(c.chip_treasury,0) >= o.owed,
                 'shortfall', round(GREATEST(o.owed - COALESCE(c.chip_treasury,0), 0),2)) AS x
          FROM (SELECT club_id, count(*) periods, count(DISTINCT user_id) players,
                       round(sum(COALESCE(rakeback_amount, rakeback_earned,0)),2) owed
                  FROM rakeback_periods
                 WHERE status='pending' AND period_end < CURRENT_DATE
                 GROUP BY club_id) o
          JOIN clubs c ON c.id = o.club_id
      ) s),
    'deferrals', (
      SELECT COALESCE(jsonb_object_agg(deferred_reason, n), '{}'::jsonb)
        FROM (SELECT deferred_reason, count(*) n FROM rakeback_periods
               WHERE status='pending' AND deferred_reason IS NOT NULL
               GROUP BY deferred_reason) d),
    'rollup_days_missing', (
      SELECT count(*) FROM (
        SELECT DISTINCT rp.club_id, d::date AS day
          FROM rakeback_periods rp
          CROSS JOIN LATERAL generate_series(rp.period_start, rp.period_end, interval '1 day') d
         WHERE rp.status='pending' AND rp.period_end < CURRENT_DATE) n
       WHERE NOT EXISTS (SELECT 1 FROM rakeback_daily_state s
                          WHERE s.club_id=n.club_id AND s.day=n.day))
  );
END;
$$;


ALTER FUNCTION public.fn_rakeback_settlement_status() OWNER TO postgres;

--
-- Name: fn_rank_survivors(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rank_survivors(p_tournament_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ranked integer := 0;
  v_bound  integer;
BEGIN
  SELECT GREATEST(COUNT(*), COALESCE(MAX(position), 0))
    INTO v_bound
    FROM tournament_players
   WHERE tournament_id = p_tournament_id;

  IF COALESCE(v_bound, 0) = 0 THEN
    RETURN 0;
  END IF;

  WITH taken AS (
    SELECT DISTINCT position
      FROM tournament_players
     WHERE tournament_id = p_tournament_id
       AND position IS NOT NULL
  ),
  survivors AS (
    SELECT id,
           row_number() OVER (
             ORDER BY COALESCE(chips, 0) DESC,
                      COALESCE(chip_count, 0) DESC,
                      registered_at ASC,
                      id ASC
           ) AS rn
      FROM tournament_players
     WHERE tournament_id = p_tournament_id
       AND position IS NULL
  ),
  free AS (
    SELECT g AS pos, row_number() OVER (ORDER BY g) AS rn
      FROM generate_series(1, v_bound) g
     WHERE NOT EXISTS (SELECT 1 FROM taken tk WHERE tk.position = g)
  )
  UPDATE tournament_players tp
     SET position      = f.pos,
         status        = CASE WHEN f.pos = 1 THEN 'winner' ELSE 'eliminated' END,
         eliminated_at = CASE WHEN f.pos = 1 THEN tp.eliminated_at
                              ELSE COALESCE(tp.eliminated_at, now()) END
    FROM survivors s
    JOIN free f ON f.rn = s.rn
   WHERE tp.id = s.id;

  GET DIAGNOSTICS v_ranked = ROW_COUNT;
  RETURN v_ranked;
END;
$$;


ALTER FUNCTION public.fn_rank_survivors(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_rate_limit_blocked(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rate_limit_blocked(p_identifier text, p_endpoint text, p_identifier_type text DEFAULT 'ip'::text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (SELECT GREATEST(1, CEIL(EXTRACT(EPOCH FROM (rl.blocked_until - now())))::int)
       FROM public.commander_rate_limits rl
      WHERE rl.identifier = p_identifier
        AND rl.identifier_type = p_identifier_type
        AND rl.endpoint = p_endpoint
        AND rl.blocked_until IS NOT NULL
        AND rl.blocked_until > now()
      LIMIT 1),
    0);
$$;


ALTER FUNCTION public.fn_rate_limit_blocked(p_identifier text, p_endpoint text, p_identifier_type text) OWNER TO postgres;

--
-- Name: fn_rate_limit_hit(text, text, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rate_limit_hit(p_identifier text, p_endpoint text, p_max_requests integer DEFAULT 5, p_window_minutes integer DEFAULT 1, p_lockout_minutes integer DEFAULT 5, p_identifier_type text DEFAULT 'ip'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r          public.commander_rate_limits;
  v_count    integer;
  v_window   timestamptz;
  v_now      timestamptz := now();
BEGIN
  -- Ensure the counter row exists (starts at 0; the update below does the count).
  INSERT INTO public.commander_rate_limits
        (identifier, identifier_type, endpoint, request_count, window_start,
         window_minutes, max_requests, last_request_at)
  VALUES (p_identifier, p_identifier_type, p_endpoint, 0, v_now,
          p_window_minutes, p_max_requests, v_now)
  ON CONFLICT (identifier, identifier_type, endpoint) DO NOTHING;

  -- Serialise concurrent callers on this counter.
  SELECT * INTO r
    FROM public.commander_rate_limits
   WHERE identifier = p_identifier
     AND identifier_type = p_identifier_type
     AND endpoint = p_endpoint
   FOR UPDATE;

  -- Still inside an active lockout.
  IF r.blocked_until IS NOT NULL AND r.blocked_until > v_now THEN
    UPDATE public.commander_rate_limits
       SET last_request_at = v_now
     WHERE id = r.id;
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'LOCKED_OUT',
      'retry_after', GREATEST(1, CEIL(EXTRACT(EPOCH FROM (r.blocked_until - v_now)))::int)
    );
  END IF;

  -- Roll the window if it has expired, otherwise increment inside it.
  IF r.window_start IS NULL
     OR r.window_start + make_interval(mins => COALESCE(r.window_minutes, p_window_minutes)) <= v_now THEN
    v_count  := 1;
    v_window := v_now;
  ELSE
    v_count  := COALESCE(r.request_count, 0) + 1;
    v_window := r.window_start;
  END IF;

  -- Over the limit: start a lockout.
  IF v_count > p_max_requests THEN
    UPDATE public.commander_rate_limits
       SET request_count   = v_count,
           window_start    = v_window,
           window_minutes  = p_window_minutes,
           max_requests    = p_max_requests,
           is_blocked      = true,
           blocked_until   = v_now + make_interval(mins => p_lockout_minutes),
           block_reason    = 'rate_limit_exceeded',
           last_request_at = v_now
     WHERE id = r.id;
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'RATE_LIMITED',
      'retry_after', p_lockout_minutes * 60
    );
  END IF;

  UPDATE public.commander_rate_limits
     SET request_count   = v_count,
         window_start    = v_window,
         window_minutes  = p_window_minutes,
         max_requests    = p_max_requests,
         is_blocked      = false,
         blocked_until   = NULL,
         block_reason    = NULL,
         last_request_at = v_now
   WHERE id = r.id;

  RETURN jsonb_build_object('allowed', true, 'reason', null, 'retry_after', 0);
END;
$$;


ALTER FUNCTION public.fn_rate_limit_hit(p_identifier text, p_endpoint text, p_max_requests integer, p_window_minutes integer, p_lockout_minutes integer, p_identifier_type text) OWNER TO postgres;

--
-- Name: fn_rebuild_agent_commission_rollup(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rebuild_agent_commission_rollup() RETURNS TABLE(pairs bigint, owed numeric, rows_behind bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (session_user IN ('postgres', 'supabase_admin')
          OR coalesce(auth.role(), '') = 'service_role'
          OR coalesce(fn_is_platform_admin(), false)) THEN
    RAISE EXCEPTION 'rebuild is an operator action' USING ERRCODE = '42501';
  END IF;

  -- Nothing may write the ledger between the count and the commit.
  LOCK TABLE public.agent_commissions IN SHARE ROW EXCLUSIVE MODE;

  -- WHERE true: this is a full rebuild and it means every row, but PostgREST
  -- runs under safeupdate, which refuses an unqualified DELETE outright.
  DELETE FROM public.agent_commission_unsettled_rollup WHERE true;
  INSERT INTO public.agent_commission_unsettled_rollup
         (club_id, user_id, owed, rows_behind, oldest_unsettled, updated_at)
  SELECT ac.club_id, ac.user_id, sum(ac.amount), count(*), min(ac.created_at), now()
    FROM public.agent_commissions_unsettled ac
   WHERE ac.club_id IS NOT NULL AND ac.user_id IS NOT NULL
   GROUP BY ac.club_id, ac.user_id;

  RETURN QUERY
  SELECT count(*)::bigint, coalesce(sum(r.owed), 0), coalesce(sum(r.rows_behind), 0)::bigint
    FROM public.agent_commission_unsettled_rollup r;
END;
$$;


ALTER FUNCTION public.fn_rebuild_agent_commission_rollup() OWNER TO postgres;

--
-- Name: fn_rebuild_ca_club_commission_daily(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rebuild_ca_club_commission_daily() RETURNS TABLE(club_days bigint, amount numeric, rows_counted bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (session_user IN ('postgres', 'supabase_admin')
          OR coalesce(auth.role(), '') = 'service_role'
          OR coalesce(fn_is_platform_admin(), false)) THEN
    RAISE EXCEPTION 'rebuild is an operator action' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('ca_club_commission_daily:rebuild', 42));
  DELETE FROM public.ca_club_commission_daily;
  INSERT INTO public.ca_club_commission_daily AS c
         (club_id, stat_date, amount, rows_counted, updated_at)
  SELECT ac.club_id, (ac.created_at AT TIME ZONE 'UTC')::date, sum(ac.amount), count(*), now()
    FROM agent_commissions ac
   WHERE ac.club_id IS NOT NULL
   GROUP BY ac.club_id, (ac.created_at AT TIME ZONE 'UTC')::date
  ON CONFLICT (club_id, stat_date) DO UPDATE
     SET amount       = c.amount + EXCLUDED.amount,
         rows_counted = c.rows_counted + EXCLUDED.rows_counted,
         updated_at   = now();
  RETURN QUERY
  SELECT count(*)::bigint, coalesce(sum(x.amount), 0), coalesce(sum(x.rows_counted), 0)::bigint
    FROM public.ca_club_commission_daily x;
END;
$$;


ALTER FUNCTION public.fn_rebuild_ca_club_commission_daily() OWNER TO postgres;

--
-- Name: fn_receipt_mystery_activation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_receipt_mystery_activation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_chest_count integer;
  v_pool_cents bigint;
  v_receipt public.tournament_mystery_activation_receipts%ROWTYPE;
BEGIN
  IF NEW.mystery_bounty_stage='active'
     AND OLD.mystery_bounty_stage IS DISTINCT FROM 'active' THEN
    SELECT count(*)::integer,COALESCE(sum(c.amount_cents),0)::bigint
      INTO v_chest_count,v_pool_cents
      FROM public.tournament_bounty_chests c WHERE c.tournament_id=NEW.id;
    IF v_chest_count<=0 OR v_pool_cents<=0
       OR v_pool_cents IS DISTINCT FROM NEW.mystery_bounty_pool_cents THEN
      RAISE EXCEPTION 'mystery activation inventory is missing or does not match its sealed pool'
        USING ERRCODE='check_violation';
    END IF;
    INSERT INTO public.tournament_mystery_activation_receipts
      (tournament_id,activation_generation,activated_at,chest_count,pool_cents)
    VALUES (NEW.id,NEW.mystery_bounty_activation_generation,
            COALESCE(NEW.mystery_bounty_activated_at,now()),v_chest_count,v_pool_cents)
    ON CONFLICT (tournament_id,activation_generation) DO NOTHING;
    SELECT * INTO v_receipt FROM public.tournament_mystery_activation_receipts
     WHERE tournament_id=NEW.id
       AND activation_generation=NEW.mystery_bounty_activation_generation;
    IF NOT FOUND OR v_receipt.chest_count<>v_chest_count
       OR v_receipt.pool_cents<>v_pool_cents THEN
      RAISE EXCEPTION 'mystery activation receipt identity conflict'
        USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_receipt_mystery_activation() OWNER TO postgres;

--
-- Name: fn_receipted_tournament_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_receipted_tournament_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF upper(COALESCE(OLD.status::text,'')) IN
       ('COMPLETED','CANCELLED','CANCELED') THEN
    RAISE EXCEPTION 'terminal tournament % is immutable after closure',OLD.id
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_receipted_tournament_is_immutable() OWNER TO postgres;

--
-- Name: fn_recent_place_collisions(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_recent_place_collisions(p_days integer DEFAULT 7) RETURNS TABLE(out_tournament_id uuid, out_place integer, out_user_id uuid, out_existing_user_id uuid, out_created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.tournament_id, c.place, c.user_id, c.existing_user_id, c.created_at
    FROM tournament_place_collisions c
   WHERE c.created_at > now() - make_interval(days => greatest(least(coalesce(p_days,7), 90), 1))
   ORDER BY c.created_at DESC;
$$;


