--
-- Name: fn_reconcile_club_member_daily_profit(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reconcile_club_member_daily_profit(p_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cutover  date := DATE '2026-08-20';
  v_club     uuid;
  v_check    jsonb;
  v_rows     integer;
  v_applied  integer := 0;
  v_skipped  integer := 0;
  v_total    integer := 0;
  v_report   jsonb := '[]'::jsonb;
BEGIN
  IF p_date IS NULL OR p_date >= CURRENT_DATE THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'day_not_complete', 'date', p_date);
  END IF;
  IF p_date < v_cutover THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'before_exact_ledger_cutover',
                              'date', p_date, 'cutover', v_cutover);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM player_stats_snapshots WHERE snapshot_date = p_date)
     OR NOT EXISTS (SELECT 1 FROM player_stats_snapshots WHERE snapshot_date = p_date + 1) THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'missing_boundary_snapshot', 'date', p_date);
  END IF;

  FOR v_club IN
    SELECT DISTINCT club_id FROM club_member_daily_stats WHERE stat_date = p_date
  LOOP
    v_total := v_total + 1;
    v_check := public.fn_club_profit_conservation(v_club, p_date);
    v_rows  := 0;

    IF (v_check ->> 'conserves')::boolean THEN
      WITH exact AS (
        SELECT b.user_id,
               (a.total_winnings - b.total_winnings) - (a.total_losses - b.total_losses) AS profit
          FROM player_stats_snapshots b
          JOIN player_stats_snapshots a
            ON a.user_id = b.user_id AND a.club_id = b.club_id
           AND a.snapshot_date = p_date + 1
         WHERE b.snapshot_date = p_date AND b.club_id = v_club
      ),
      shares AS (
        SELECT s.club_id, s.user_id, s.table_id, e.profit AS exact_profit,
               GREATEST(COALESCE(s.hands_played, 0), 0) AS w,
               SUM(GREATEST(COALESCE(s.hands_played, 0), 0))
                 OVER (PARTITION BY s.club_id, s.user_id) AS w_total,
               COUNT(*)     OVER (PARTITION BY s.club_id, s.user_id) AS n_rows,
               ROW_NUMBER() OVER (PARTITION BY s.club_id, s.user_id ORDER BY s.table_id) AS rn
          FROM club_member_daily_stats s
          JOIN exact e ON e.user_id = s.user_id
         WHERE s.stat_date = p_date AND s.club_id = v_club
      ),
      alloc AS (
        SELECT club_id, user_id, table_id, exact_profit, rn, n_rows,
               CASE WHEN w_total > 0 THEN round(exact_profit * w / w_total, 2)
                    ELSE round(exact_profit / n_rows, 2) END AS share
          FROM shares
      ),
      fixed AS (
        SELECT a.*, a.exact_profit - SUM(a.share) OVER (PARTITION BY a.club_id, a.user_id) AS remainder
          FROM alloc a
      )
      UPDATE club_member_daily_stats s
         SET profit = f.share + CASE WHEN f.rn = f.n_rows THEN f.remainder ELSE 0 END,
             updated_at = now()
        FROM fixed f
       WHERE s.stat_date = p_date
         AND s.club_id = f.club_id AND s.user_id = f.user_id
         AND s.table_id IS NOT DISTINCT FROM f.table_id;

      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_applied := v_applied + 1;
    ELSE
      v_skipped := v_skipped + 1;
    END IF;

    INSERT INTO public.club_profit_reconcile_log
      (stat_date, club_id, exact_profit_sum, house_cut, exact_drift,
       dashboard_drift_before, tolerance, applied, reason, rows_updated)
    VALUES (p_date, v_club,
            (v_check ->> 'exact_profit_sum')::numeric,
            (v_check ->> 'house_cut')::numeric,
            (v_check ->> 'exact_drift')::numeric,
            (v_check ->> 'dashboard_drift')::numeric,
            (v_check ->> 'tolerance')::numeric,
            (v_check ->> 'conserves')::boolean,
            CASE WHEN (v_check ->> 'conserves')::boolean THEN 'conserves'
                 WHEN NOT (v_check ->> 'has_house_row')::boolean THEN 'no_house_cut_row'
                 ELSE 'fails_chip_conservation' END,
            v_rows);

    v_report := v_report || jsonb_build_array(v_check);
  END LOOP;

  RETURN jsonb_build_object(
    'reconciled', true, 'date', p_date,
    'clubs_seen', v_total, 'clubs_applied', v_applied, 'clubs_skipped', v_skipped,
    'detail', v_report
  );
END;
$$;


ALTER FUNCTION public.fn_reconcile_club_member_daily_profit(p_date date) OWNER TO postgres;

--
-- Name: fn_reconcile_club_table_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reconcile_club_table_counts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_fixed int;
begin
  with drifted as (
    select c.id, fn_live_table_count(c.id) AS truth
      from clubs c
     where c.table_count is distinct from fn_live_table_count(c.id)
  )
  update clubs c set table_count = d.truth
    from drifted d
   where c.id = d.id;
  get diagnostics v_fixed = row_count;
  return v_fixed;
end $$;


ALTER FUNCTION public.fn_reconcile_club_table_counts() OWNER TO postgres;

--
-- Name: FUNCTION fn_reconcile_club_table_counts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_reconcile_club_table_counts() IS 'Nightly backstop for clubs.table_count. Before 2026-08-20 an always-firing trigger re-synced every count on every hand; removing that waste also removed an accidental reconciler, so drift became permanent. Returns the number of clubs corrected — a non-zero result means a drift source is still uncovered and is worth investigating, not just repairing.';


--
-- Name: fn_record_card_slide_usage(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_card_slide_usage(p_started integer DEFAULT 0, p_committed integer DEFAULT 0, p_abandoned integer DEFAULT 0, p_keyboard integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_started integer := LEAST(GREATEST(COALESCE(p_started, 0), 0), 500);
  v_committed integer := LEAST(GREATEST(COALESCE(p_committed, 0), 0), 500);
  v_abandoned integer := LEAST(GREATEST(COALESCE(p_abandoned, 0), 0), 500);
  v_keyboard integer := LEAST(GREATEST(COALESCE(p_keyboard, 0), 0), 500);
BEGIN
  IF v_user IS NULL THEN
    RETURN;
  END IF;
  IF v_started + v_committed + v_abandoned + v_keyboard = 0 THEN
    RETURN;
  END IF;

  INSERT INTO public.card_slide_usage AS c (
    day, user_id, peels_started, peels_committed, peels_abandoned, keyboard_opens
  )
  VALUES (
    (now() AT TIME ZONE 'utc')::date, v_user, v_started, v_committed, v_abandoned, v_keyboard
  )
  ON CONFLICT (day, user_id) DO UPDATE SET
    peels_started = c.peels_started + EXCLUDED.peels_started,
    peels_committed = c.peels_committed + EXCLUDED.peels_committed,
    peels_abandoned = c.peels_abandoned + EXCLUDED.peels_abandoned,
    keyboard_opens = c.keyboard_opens + EXCLUDED.keyboard_opens,
    updated_at = now();
END $$;


ALTER FUNCTION public.fn_record_card_slide_usage(p_started integer, p_committed integer, p_abandoned integer, p_keyboard integer) OWNER TO postgres;

--
-- Name: fn_record_cashier_operation(uuid, text, text, integer, integer, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_cashier_operation(p_club_id uuid, p_event text, p_operation text, p_duration_ms integer DEFAULT NULL::integer, p_item_count integer DEFAULT NULL::integer, p_page_number integer DEFAULT NULL::integer, p_success_count integer DEFAULT NULL::integer, p_failure_count integer DEFAULT NULL::integer, p_reason_code text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_user_id uuid := auth.uid();
  v_scope text;
  v_is_failure boolean;
  v_recent_count integer;
BEGIN
  IF v_user_id IS NULL OR p_club_id IS NULL THEN
    RETURN false;
  END IF;

  -- The Cashier operational feed describes staff/agent workflows. A plain
  -- player or a user with no active membership cannot write a club's signal.
  v_scope := public.fn_club_cashier_scope(p_club_id, v_user_id);
  IF COALESCE(v_scope, 'none') NOT IN ('all', 'downline') THEN
    RETURN false;
  END IF;

  IF p_event IS NULL OR p_operation IS NULL OR p_event NOT IN (
    'roster_page_succeeded', 'roster_page_failed',
    'batch_succeeded', 'batch_partial', 'batch_failed'
  ) OR p_operation NOT IN ('roster', 'send', 'ticket') THEN
    RETURN false;
  END IF;
  IF (p_event LIKE 'roster_page_%' AND p_operation <> 'roster')
     OR (p_event LIKE 'batch_%' AND p_operation NOT IN ('send', 'ticket')) THEN
    RETURN false;
  END IF;

  IF (p_duration_ms IS NOT NULL AND (p_duration_ms < 0 OR p_duration_ms > 300000))
     OR (p_item_count IS NOT NULL AND (p_item_count < 0 OR p_item_count > 1000000))
     OR (p_page_number IS NOT NULL AND (p_page_number < 0 OR p_page_number > 100000))
     OR (p_success_count IS NOT NULL AND (p_success_count < 0 OR p_success_count > 1000000))
     OR (p_failure_count IS NOT NULL AND (p_failure_count < 0 OR p_failure_count > 1000000))
     OR (p_reason_code IS NOT NULL AND p_reason_code !~ '^[a-z0-9:_-]{1,64}$') THEN
    RETURN false;
  END IF;

  -- Bound storage abuse and SLO poisoning by a compromised authenticated
  -- client. The actor is server-derived and the lock closes concurrent races.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('cashier-operation:' || v_user_id::text, 0)
  );
  SELECT COUNT(*)
    INTO v_recent_count
    FROM public.rate_limits
   WHERE user_id = v_user_id
     AND action = 'cashier_operation'
     AND created_at > now() - interval '1 minute';
  IF v_recent_count >= 120 THEN
    RETURN false;
  END IF;
  INSERT INTO public.rate_limits (user_id, action)
  VALUES (v_user_id, 'cashier_operation');

  v_is_failure := p_event IN ('roster_page_failed', 'batch_partial', 'batch_failed');

  INSERT INTO public.cashier_operations (
    user_id,
    club_id,
    event,
    operation,
    duration_ms,
    item_count,
    page_number,
    success_count,
    failure_count,
    reason_code,
    sample_weight
  ) VALUES (
    v_user_id,
    p_club_id,
    p_event,
    p_operation,
    p_duration_ms,
    p_item_count,
    p_page_number,
    p_success_count,
    p_failure_count,
    p_reason_code,
    CASE WHEN v_is_failure THEN 1 ELSE 10 END
  );

  RETURN true;
END
$_$;


ALTER FUNCTION public.fn_record_cashier_operation(p_club_id uuid, p_event text, p_operation text, p_duration_ms integer, p_item_count integer, p_page_number integer, p_success_count integer, p_failure_count integer, p_reason_code text) OWNER TO postgres;

--
-- Name: FUNCTION fn_record_cashier_operation(p_club_id uuid, p_event text, p_operation text, p_duration_ms integer, p_item_count integer, p_page_number integer, p_success_count integer, p_failure_count integer, p_reason_code text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_record_cashier_operation(p_club_id uuid, p_event text, p_operation text, p_duration_ms integer, p_item_count integer, p_page_number integer, p_success_count integer, p_failure_count integer, p_reason_code text) IS 'Records one bounded Cashier SLO event for auth.uid() after validating active club cashier scope. The browser cannot choose user_id or sample_weight.';


--
-- Name: fn_record_entry_purchase_receipt(text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_entry_purchase_receipt(p_key_domain text, p_idempotency_key text, p_request jsonb, p_response jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request jsonb;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 THEN
    RETURN p_response;
  END IF;
  IF p_request IS NULL OR p_response IS NULL THEN
    RAISE EXCEPTION 'entry purchase receipts require a non-null request and response'
      USING ERRCODE = '22004';
  END IF;

  SELECT r.request, r.response
    INTO STRICT v_request, v_response
    FROM public.entry_purchase_idempotency_receipts r
   WHERE r.key_domain = p_key_domain
     AND r.idempotency_key = p_idempotency_key
   FOR UPDATE;
  IF v_request IS DISTINCT FROM p_request THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_KEY_REUSED: % key completed concurrently for a different entry purchase',
      p_key_domain
      USING ERRCODE = '22023';
  END IF;
  IF v_response IS NOT NULL THEN
    RETURN v_response;
  END IF;

  UPDATE public.entry_purchase_idempotency_receipts r
     SET response = p_response,
         completed_at = transaction_timestamp()
   WHERE r.key_domain = p_key_domain
     AND r.idempotency_key = p_idempotency_key
     AND r.request IS NOT DISTINCT FROM p_request
     AND r.response IS NULL
  RETURNING r.response INTO STRICT v_response;
  RETURN v_response;
END;
$$;


ALTER FUNCTION public.fn_record_entry_purchase_receipt(p_key_domain text, p_idempotency_key text, p_request jsonb, p_response jsonb) OWNER TO postgres;

--
-- Name: fn_record_money_check_run(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_money_check_run(p_check text, p_result jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_name text := left(nullif(btrim(coalesce(p_check, '')), ''), 200);
BEGIN
  IF v_name IS NULL THEN RETURN; END IF;

  INSERT INTO public.money_check_heartbeat
    (check_name, expected_interval_minutes, last_run_at, last_result, run_count)
  VALUES (v_name, 60, now(), p_result, 1)
  ON CONFLICT (check_name) DO UPDATE
    SET last_run_at = now(),
        last_result = EXCLUDED.last_result,
        run_count   = public.money_check_heartbeat.run_count + 1;
EXCEPTION WHEN OTHERS THEN
  -- Swallowed on purpose, and this is the ONE place in this audit where that
  -- is right: the caller has just finished a money check and the heartbeat is
  -- bookkeeping about that check, not part of it.
  NULL;
END;
$$;


ALTER FUNCTION public.fn_record_money_check_run(p_check text, p_result jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_record_money_check_run(p_check text, p_result jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_record_money_check_run(p_check text, p_result jsonb) IS 'Records that a money check just ran. Called by the driver, not by the check, because what needs proving is that the engine is executing it on its timer.';


--
-- Name: fn_record_new_club_opening_bank(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_new_club_opening_bank() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_chip_id uuid;
  v_supply numeric;
  v_op text := 'club-opening-grant:' || NEW.id::text;
  v_owner_label text;
BEGIN
  -- The seeder above refuses to set a chip treasury on a non-chip club, so this would return
  -- early on the amount test anyway. It is stated rather than inferred, so that setting the
  -- treasury by hand on a diamond club cannot quietly re-arm a chip mint.
  IF COALESCE(NEW.is_union, false)
     OR COALESCE(NEW.asset, 'chips') <> 'chips'
     OR COALESCE(NEW.chip_treasury, 0) <> 100000 THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.chip_transactions (
    club_id, amount, transaction_type, notes, balance_after, metadata
  ) VALUES (
    NEW.id,
    100000,
    'club_opening_grant',
    'New Club Opening Bank',
    100000,
    jsonb_build_object(
      'source', 'the_mint',
      'destination', 'club_bank',
      'club_owner_id', NEW.owner_id,
      'club_code', NEW.club_id,
      'opening_balance', 100000,
      'mint_op_id', v_op
    )
  );

  /* THE REGISTER (2026-09-03): the row fn_ca_mint would have written. The
     journal row was written by the clubs auto-ledger when the treasury was
     set at INSERT (issuance_reserve -> club_treasury, key = v_op). */
  SELECT id INTO v_chip_id FROM public.chip_ledger
   WHERE idempotency_key = v_op
   ORDER BY created_at DESC LIMIT 1;
  IF v_chip_id IS NULL THEN
    SELECT id INTO v_chip_id FROM public.chip_ledger
     WHERE category = 'mint' AND from_type = 'issuance_reserve'
       AND to_type = 'club_treasury' AND to_entity_id = NEW.id AND amount = 100000
     ORDER BY created_at DESC LIMIT 1;
  END IF;

  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) + 100000
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = 'chips';
  SELECT COALESCE(NULLIF(btrim(p.username), ''), p.full_name, p.id::text)
    INTO v_owner_label FROM public.profiles p WHERE p.id = NEW.owner_id;

  BEGIN
    INSERT INTO public.ca_mint_ledger
      (op_id, action, asset, holder_type, holder_id, holder_label, amount,
       balance_before, balance_after, supply_after, reason,
       performed_by, performed_by_label, chip_ledger_id)
    VALUES
      (v_op, 'mint', 'chips', 'club', NEW.id, NEW.name, 100000,
       0, 100000, v_supply,
       'New Club Opening Bank: 100,000 chips from the Mint on creation, playable inside this club only',
       NEW.owner_id, v_owner_label, v_chip_id);
  EXCEPTION WHEN unique_violation THEN
    NULL;  -- the same club's grant is already on the register
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_record_new_club_opening_bank() OWNER TO postgres;

--
-- Name: FUNCTION fn_record_new_club_opening_bank(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_record_new_club_opening_bank() IS 'Writes the immutable opening Club Bank grant ledger row in the same transaction as club creation.';


--
-- Name: fn_record_tos_acceptance(uuid, text, text, inet, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_tos_acceptance(p_caller_user_id uuid, p_policy_key text, p_policy_version text, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_expected_version text;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED';
  END IF;

  IF p_policy_key NOT IN (
    'home_games.tos',
    'home_games.privacy',
    'home_games.community_guidelines',
    'home_games.money_policy',
    'home_games.jurisdiction'
  ) THEN
    RAISE EXCEPTION 'INVALID_POLICY_KEY';
  END IF;

  -- Verify the version matches the CURRENT version the platform
  -- advertises (prevents clients from submitting stale versions).
  SELECT value INTO v_expected_version
    FROM public.platform_policies
   WHERE key = p_policy_key || '.version';
  IF v_expected_version IS NOT NULL AND v_expected_version <> p_policy_version THEN
    RAISE EXCEPTION 'STALE_POLICY_VERSION'
          USING HINT = 'current version is ' || v_expected_version;
  END IF;

  INSERT INTO public.user_tos_acceptances
    (user_id, policy_key, policy_version, ip_address, user_agent)
  VALUES
    (p_caller_user_id, p_policy_key, p_policy_version, p_ip_address, p_user_agent)
  ON CONFLICT (user_id, policy_key, policy_version) DO NOTHING
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'success',      true,
    'acceptance_id', v_id,
    'policy_key',    p_policy_key,
    'policy_version', p_policy_version
  );
END;
$$;


ALTER FUNCTION public.fn_record_tos_acceptance(p_caller_user_id uuid, p_policy_key text, p_policy_version text, p_ip_address inet, p_user_agent text) OWNER TO postgres;

--
-- Name: fn_redeem_club_invite_code(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_redeem_club_invite_code(p_club_id uuid, p_user_id uuid, p_referral_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_caller            uuid := auth.uid();
  v_code              text := btrim(coalesce(p_referral_code, ''));
  v_inviter           record;
  v_inviter_member    record;
  v_member            record;
  v_effective_agent   uuid;
  v_is_agent          boolean;
  v_agent_name        text;
  v_new_status        text;
BEGIN
  -- ── Authorization ────────────────────────────────────────────────────────
  IF v_caller IS NOT NULL AND v_caller <> p_user_id THEN
    RETURN jsonb_build_object('success', false, 'code', 'not_your_membership',
                              'error', 'You can only redeem an invite for yourself.');
  END IF;

  IF v_code = '' THEN
    RETURN jsonb_build_object('success', false, 'code', 'empty_code',
                              'error', 'No referral code supplied.');
  END IF;

  -- ── 1. Resolve the inviter ───────────────────────────────────────────────
  SELECT p.id, p.username, p.player_number
    INTO v_inviter
    FROM profiles p
   WHERE p.player_number = v_code
      OR (v_code ~ '^[0-9]+$' AND p.player_number ~ '^[0-9]+$'
          AND p.player_number::bigint = v_code::bigint)
      OR (v_code ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND p.id = v_code::uuid)
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'unknown_inviter',
                              'error', 'Invalid referral code.');
  END IF;

  IF v_inviter.id = p_user_id THEN
    RETURN jsonb_build_object('success', false, 'code', 'self_referral',
                              'error', 'You cannot invite yourself.');
  END IF;

  -- ── 2. The inviter must be a settled member of this club ─────────────────
  SELECT * INTO v_inviter_member
    FROM club_members
   WHERE club_id = p_club_id AND user_id = v_inviter.id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'inviter_not_in_club',
                              'error', 'Inviter is not a member of this club.');
  END IF;

  IF v_inviter_member.status NOT IN ('active', 'approved') THEN
    RETURN jsonb_build_object('success', false, 'code', 'inviter_not_settled',
                              'error', 'Inviter is not an active member of this club.');
  END IF;

  -- ── 3. Effective upline ──────────────────────────────────────────────────
  SELECT true INTO v_is_agent
    FROM agents
   WHERE club_id = p_club_id AND user_id = v_inviter.id AND status = 'active';

  IF coalesce(v_is_agent, false) THEN
    v_effective_agent := v_inviter.id;
  ELSE
    v_effective_agent := v_inviter_member.agent_id;
  END IF;

  -- ── 4. The joining user must already have a membership row ───────────────
  SELECT * INTO v_member
    FROM club_members
   WHERE club_id = p_club_id AND user_id = p_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'not_a_member',
                              'error', 'User is not a member of this club.');
  END IF;

  IF v_member.status NOT IN ('active', 'approved', 'pending') THEN
    RETURN jsonb_build_object('success', false, 'code', 'membership_blocked',
                              'error', 'This membership cannot be activated.');
  END IF;

  -- ── 5. Attach and admit ──────────────────────────────────────────────────
  v_new_status := CASE WHEN v_member.status = 'pending' THEN 'active' ELSE v_member.status END;

  UPDATE club_members
     SET agent_id   = coalesce(agent_id, v_effective_agent),
         invited_by = coalesce(invited_by, v_inviter.id),
         status     = v_new_status,
         updated_at = now()
   WHERE club_id = p_club_id AND user_id = p_user_id
  RETURNING * INTO v_member;

  -- ── 6. Re-derive the upline's player counts ──────────────────────────────
  IF v_member.agent_id IS NOT NULL THEN
    UPDATE agents
       SET total_players = (SELECT count(*) FROM club_members
                             WHERE agent_id = v_member.agent_id AND club_id = p_club_id),
           active_player_count = (SELECT count(*) FROM club_members
                                   WHERE agent_id = v_member.agent_id AND club_id = p_club_id
                                     AND status IN ('active', 'approved')),
           updated_at = now()
     WHERE club_id = p_club_id AND user_id = v_member.agent_id;
  END IF;

  SELECT username INTO v_agent_name FROM profiles WHERE id = v_member.agent_id;

  RETURN jsonb_build_object(
    'success',     true,
    'status',      v_member.status,
    'agent_id',    v_member.agent_id,
    'agent_name',  v_agent_name,
    'inviter_id',  v_inviter.id,
    'inviter_name', v_inviter.username
  );
END;
$_$;


ALTER FUNCTION public.fn_redeem_club_invite_code(p_club_id uuid, p_user_id uuid, p_referral_code text) OWNER TO postgres;

--
-- Name: FUNCTION fn_redeem_club_invite_code(p_club_id uuid, p_user_id uuid, p_referral_code text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_redeem_club_invite_code(p_club_id uuid, p_user_id uuid, p_referral_code text) IS 'Redeems a club invite/referral code for the CALLING user: attaches the upline agent (the inviter if they are an active agent, otherwise the inviter''s own agent), records invited_by, and promotes a pending membership to active. Never overwrites an existing agent_id and never changes a settled status. Fixed 2026-08-26: the previous body compared text player_number to an integer and therefore raised 42883 on every call since it was written.';


--
-- Name: fn_redeem_shop_item(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_redeem_shop_item(p_inventory_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.club_shop_inventory%ROWTYPE;
  v_spec jsonb;
  v_type text;
  v_qty integer;
  v_granted jsonb := jsonb_build_object('type', 'none');
BEGIN
  SELECT * INTO v_row FROM public.club_shop_inventory
   WHERE id = p_inventory_id FOR UPDATE;
  IF v_row.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;
  IF v_row.user_id <> auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;
  IF v_row.status = 'redeemed' THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_redeemed');
  END IF;
  IF v_row.status = 'refunded' THEN
    RETURN jsonb_build_object('success', false, 'error', 'refunded');
  END IF;

  v_spec := COALESCE(v_row.grant_snapshot, '{}'::jsonb);
  v_type := COALESCE(v_spec->>'type', 'none');
  v_qty := GREATEST(1, LEAST(1000, COALESCE((v_spec->>'qty')::integer, 1)));

  IF v_type = 'time_bank' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (v_row.user_id, 'time_bank_seconds', 0, 'per_use', v_qty, NULL);
    v_granted := jsonb_build_object('type', 'time_bank', 'uses', v_qty, 'seconds', v_qty * 20);
  ELSIF v_type = 'throwable' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (v_row.user_id, 'throwable', 0, 'per_use', v_qty, NULL);
    v_granted := jsonb_build_object('type', 'throwable', 'uses', v_qty);
  ELSIF v_type = 'emote_pack' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (v_row.user_id, 'emoji_pack', 0, 'permanent', NULL, NULL);
    v_granted := jsonb_build_object('type', 'emote_pack', 'permanent', true);
  ELSIF v_type = 'table_skin' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (v_row.user_id, 'theme_unlock', 0, 'permanent', NULL, NULL);
    v_granted := jsonb_build_object('type', 'table_skin', 'permanent', true,
                                    'theme_id', v_spec->>'theme_id');
  ELSIF v_type = 'avatar' THEN
    INSERT INTO public.avatar_unlocks (user_id, avatar_id, unlock_method)
    VALUES (v_row.user_id, COALESCE(v_spec->>'avatar_id', v_row.item_id::text), 'club_shop')
    ON CONFLICT DO NOTHING;
    v_granted := jsonb_build_object(
      'type', 'avatar', 'avatar_id', COALESCE(v_spec->>'avatar_id', v_row.item_id::text)
    );
  END IF;

  UPDATE public.club_shop_inventory
     SET status = 'redeemed', redeemed_at = now()
   WHERE id = p_inventory_id;

  RETURN jsonb_build_object(
    'success', true, 'item_name', v_row.item_name, 'granted', v_granted
  );
END;
$$;


ALTER FUNCTION public.fn_redeem_shop_item(p_inventory_id uuid) OWNER TO postgres;

--
-- Name: fn_redeem_tournament_ticket(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_redeem_tournament_ticket(p_ticket_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me uuid:=auth.uid();
  v_t public.tournament_tickets%ROWTYPE;
  v_after numeric;
  v_context jsonb;
  v_setting text;
  v_receipt public.chip_transactions%ROWTYPE;
  v_issue public.chip_transactions%ROWTYPE;
  v_escrow_entity uuid;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','Not Authenticated');
  END IF;
  IF p_ticket_id IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','Choose A Ticket');
  END IF;

  SELECT * INTO v_t FROM public.tournament_tickets
   WHERE id=p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success',false,'error','Ticket Not Found');
  END IF;
  IF v_t.redemption_mode='tournament_entry_only' THEN
    RETURN jsonb_build_object(
      'success',false,
      'error','Tournament-Entry Tickets Can Only Be Used To Enter A Tournament');
  END IF;
  IF v_t.holder_id IS DISTINCT FROM v_me THEN
    RETURN jsonb_build_object('success',false,'error','This Ticket Is Not Yours');
  END IF;
  IF v_t.status='redeemed' THEN
    SELECT * INTO v_receipt FROM public.chip_transactions
     WHERE transaction_type='tournament_ticket_redeem'
       AND metadata->>'ticket_id'=p_ticket_id::text LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'success',true,'replayed',true,'value',v_t.value,
        'your_balance',(v_receipt.metadata->>'holder_balance_after')::numeric,
        'transaction_id',v_receipt.id);
    END IF;
  END IF;
  IF v_t.status<>'issued' THEN
    RETURN jsonb_build_object(
      'success',false,'error','Ticket Already '||initcap(v_t.status));
  END IF;

  SELECT * INTO v_issue FROM public.chip_transactions
   WHERE transaction_type='tournament_ticket_issue'
     AND metadata->>'ticket_id'=p_ticket_id::text LIMIT 1;
  IF FOUND AND v_issue.metadata ? 'escrow_entity_id' THEN
    IF v_issue.club_id IS DISTINCT FROM v_t.club_id
       OR v_issue.from_user_id IS DISTINCT FROM v_t.issued_by
       OR v_issue.to_user_id IS DISTINCT FROM v_t.holder_id
       OR v_issue.amount IS DISTINCT FROM v_t.value
       OR v_issue.metadata->>'escrow_entity_id'
            IS DISTINCT FROM p_ticket_id::text THEN
      RAISE EXCEPTION 'Ticket escrow receipt does not match its entitlement'
        USING ERRCODE='22023';
    END IF;
    v_escrow_entity:=p_ticket_id;
  END IF;
  SELECT jsonb_object_agg(k,COALESCE(current_setting(k,true),''))
    INTO v_context
    FROM unnest(ARRAY[
      'app.ledger_category','app.ledger_counterparty',
      'app.ledger_counterparty_entity','app.ledger_tournament']) settings(k);
  PERFORM set_config('app.ledger_tournament','',true);
  PERFORM set_config('app.ledger_category','ticket_redeem',true);
  PERFORM set_config('app.ledger_counterparty','escrow',true);
  PERFORM set_config(
    'app.ledger_counterparty_entity',COALESCE(v_escrow_entity::text,''),true);
  UPDATE public.club_members
     SET chip_balance=COALESCE(chip_balance,0)+v_t.value,updated_at=now()
   WHERE club_id=v_t.club_id AND user_id=v_me
     AND COALESCE(status,'active') IN ('active','approved')
   RETURNING chip_balance INTO v_after;
  FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
    PERFORM set_config(v_setting,v_context->>v_setting,true);
  END LOOP;
  IF v_after IS NULL THEN
    RETURN jsonb_build_object(
      'success',false,'error','You Are No Longer A Member Of That Club');
  END IF;

  UPDATE public.tournament_tickets
     SET status='redeemed',redeemed_at=now()
   WHERE id=p_ticket_id;
  INSERT INTO public.chip_transactions(
    club_id,from_user_id,to_user_id,amount,transaction_type,notes,
    balance_after,metadata)
  VALUES(
    v_t.club_id,NULL,v_me,v_t.value,'tournament_ticket_redeem',
    'Tournament Ticket Redeemed: Escrow Released',v_after,
    jsonb_build_object(
      'ticket_id',p_ticket_id,'issuer_id',v_t.issued_by,
      'holder_id',v_t.holder_id,'escrow_action','release_to_holder',
      'holder_balance_after',v_after))
  RETURNING * INTO v_receipt;

  INSERT INTO public.wallet_transactions(
    user_id,wallet_type,type,amount,category,description,balance_after)
  VALUES(
    v_me,'PLAYER','credit',v_t.value,'transfer',
    'Tournament Ticket Redeemed: Escrow Released',v_after);

  RETURN jsonb_build_object(
    'success',true,'replayed',false,'value',v_t.value,
    'your_balance',v_after,'transaction_id',v_receipt.id);
END;
$$;


ALTER FUNCTION public.fn_redeem_tournament_ticket(p_ticket_id uuid) OWNER TO postgres;

--
-- Name: fn_redeem_vip_points(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_redeem_vip_points(p_cost bigint, p_reason text DEFAULT 'Reward redemption'::text, p_reward_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_bal bigint;
  v_reward record;
  v_cost bigint;
  v_status text := 'pending';
  v_theme_id text;
  v_avatar_id text;
  v_granted jsonb := jsonb_build_object('type', 'none');
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;
  IF p_reward_id IS NOT NULL THEN
    SELECT * INTO v_reward FROM public.vip_reward_catalog WHERE id = p_reward_id AND is_active;
    IF v_reward.id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'unknown_reward');
    END IF;
    v_cost := v_reward.points_cost;
    IF v_reward.grant_type = 'theme' THEN
      v_theme_id := public.sp_resolve_theme_preset(v_reward.grant_ref);
      IF v_theme_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_reward_sku');
      END IF;
    ELSIF v_reward.grant_type = 'avatar' THEN
      v_avatar_id := public.sp_resolve_avatar_entitlement(v_reward.grant_ref);
      IF v_avatar_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_reward_sku');
      END IF;
    END IF;
  ELSE
    v_cost := p_cost;
  END IF;
  IF v_cost IS NULL OR v_cost <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_cost');
  END IF;
  IF p_reward_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('fn_redeem_vip_points:' || v_uid::text || ':' || p_reward_id, 0)
    );
    IF v_reward.stock IS NOT NULL AND v_reward.stock <= 0 THEN
      RETURN jsonb_build_object('success', false, 'error', 'sold_out');
    END IF;
    IF v_reward.grant_type = 'theme' AND EXISTS (
      SELECT 1 FROM public.theme_asset_unlocks
       WHERE user_id = v_uid AND category = 'theme_id' AND asset_id = v_theme_id
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'already_owned', 'already_owned', true);
    END IF;
    IF v_reward.grant_type = 'avatar' AND EXISTS (
      SELECT 1 FROM public.avatar_unlocks WHERE user_id = v_uid AND avatar_id = v_avatar_id
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'already_owned', 'already_owned', true);
    END IF;
  END IF;
  SELECT current_points INTO v_bal FROM public.vip_points WHERE user_id = v_uid FOR UPDATE;
  IF COALESCE(v_bal, 0) < v_cost THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'insufficient_points', 'balance', COALESCE(v_bal, 0)
    );
  END IF;
  PERFORM set_config('app.vip_points_writer', 'fn_redeem_vip_points', true);
  UPDATE public.vip_points SET current_points = current_points - v_cost, updated_at = now() WHERE user_id = v_uid;
  PERFORM set_config('app.vip_points_writer', '', true);
  INSERT INTO public.vip_points_ledger (user_id, points, reason, source_type, source_id)
  VALUES (v_uid, -v_cost, p_reason, 'redeem', gen_random_uuid());
  IF p_reward_id IS NOT NULL THEN
    IF v_reward.grant_type = 'theme' THEN
      PERFORM public.sp_grant_theme_preset(v_uid, v_theme_id, 'vip_points');
      v_status := 'granted';
      v_granted := jsonb_build_object('type', 'theme', 'theme_id', v_theme_id);
    ELSIF v_reward.grant_type = 'avatar' THEN
      INSERT INTO public.avatar_unlocks (user_id, avatar_id, unlock_method)
      VALUES (v_uid, v_avatar_id, 'vip_points')
      ON CONFLICT DO NOTHING;
      v_status := 'granted';
      v_granted := jsonb_build_object('type', 'avatar', 'avatar_id', v_avatar_id);
    END IF;
    IF v_reward.stock IS NOT NULL THEN
      UPDATE public.vip_reward_catalog SET stock = stock - 1 WHERE id = p_reward_id;
    END IF;
    INSERT INTO public.vip_reward_claims (user_id, reward_id, points_spent, status)
    VALUES (v_uid, p_reward_id, v_cost, v_status);
  END IF;
  RETURN jsonb_build_object(
    'success', true,
    'balance', COALESCE(v_bal, 0) - v_cost,
    'charged', v_cost,
    'status', CASE WHEN p_reward_id IS NULL THEN NULL ELSE v_status END,
    'granted', v_granted
  );
END;
$$;


ALTER FUNCTION public.fn_redeem_vip_points(p_cost bigint, p_reason text, p_reward_id text) OWNER TO postgres;

--
-- Name: fn_redrive_unbanked_rake(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_redrive_unbanked_rake(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record; v_hand uuid; v_ok int := 0; v_failed int := 0; v_already int := 0;
BEGIN
  -- CHIP STANDARD (2026-09-05): a sweep that moves money checks the freeze
  -- (CLAUDE.md section 13 rule 5). This runs every minute from pg_cron, which
  -- does not stop for the break; during it every redrive hit the guard on
  -- clubs and burned an attempt. It returns empty and redrives after play
  -- resumes.
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', true, 'frozen', true, 'redriven', 0, 'already_banked', 0, 'failed', 0);
  END IF;
  FOR r IN SELECT p.* FROM public.pending_fee_distributions p
           WHERE p.resolved_at IS NULL AND p.kind = 'rake'
           ORDER BY p.created_at
           LIMIT GREATEST(COALESCE(p_limit, 200), 1)
  LOOP
    v_hand := r.hand_id;
    IF v_hand IS NULL AND r.hand_number >= 1000000 THEN
      SELECT id INTO v_hand FROM public.hand_history WHERE hand_number = r.hand_number LIMIT 1;
    END IF;
    IF v_hand IS NOT NULL AND EXISTS (SELECT 1 FROM public.rake_records rr WHERE rr.hand_id = v_hand) THEN
      UPDATE public.pending_fee_distributions
         SET resolved_at = now(), last_error = COALESCE(last_error, '') || ' [already banked]'
       WHERE id = r.id;
      v_already := v_already + 1;
      CONTINUE;
    END IF;
    BEGIN
      PERFORM public.atomic_distribute_rake(
        r.table_id, r.club_id, v_hand, r.hand_number::integer, r.rake, r.bbj,
        r.pot, r.num_players, r.contributions, r.tournament_id,
        r.returned_uncalled, COALESCE(r.rake_method, 'DEALT_EQUAL'));
      UPDATE public.pending_fee_distributions
         SET resolved_at = now(), attempts = COALESCE(attempts, 0) + 1, last_attempt_at = now()
       WHERE id = r.id;
      v_ok := v_ok + 1;
    EXCEPTION WHEN others THEN
      UPDATE public.pending_fee_distributions
         SET attempts = COALESCE(attempts, 0) + 1, last_attempt_at = now(),
             last_error = left(SQLERRM, 500)
       WHERE id = r.id;
      v_failed := v_failed + 1;
    END;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'redriven', v_ok,
    'already_banked', v_already, 'failed', v_failed);
END $$;


ALTER FUNCTION public.fn_redrive_unbanked_rake(p_limit integer) OWNER TO postgres;

--
-- Name: fn_redundant_dead_indexes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_redundant_dead_indexes() RETURNS TABLE(table_name text, index_name text, size_bytes bigint, covered_by text, coverer_scans bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH idx AS (
    SELECT s.relid, s.relname, s.indexrelname, s.indexrelid, s.idx_scan,
           i.indisunique, i.indisprimary, i.indisexclusion,
           i.indkey::int2[] AS keys, i.indnkeyatts,
           pg_get_expr(i.indpred, i.indrelid) AS pred, am.amname,
           i.indexprs IS NOT NULL AS has_expr,
           pg_relation_size(s.indexrelid) AS sz
    FROM pg_stat_user_indexes s
    JOIN pg_index i  ON i.indexrelid = s.indexrelid
    JOIN pg_class ic ON ic.oid = s.indexrelid
    JOIN pg_am am    ON am.oid = ic.relam
    WHERE s.schemaname = 'public'
  )
  SELECT DISTINCT ON (a.indexrelid)
         a.relname::text, a.indexrelname::text, a.sz,
         b.indexrelname::text, b.idx_scan
  FROM idx a
  JOIN idx b
    ON a.relid = b.relid
   AND a.indexrelid <> b.indexrelid
   AND a.amname = 'btree' AND b.amname = 'btree'
   AND a.pred IS NULL AND b.pred IS NULL
   AND NOT a.has_expr AND NOT b.has_expr
   AND a.indnkeyatts < b.indnkeyatts
   AND b.keys[0:a.indnkeyatts-1] = a.keys[0:a.indnkeyatts-1]
  WHERE a.idx_scan = 0
    AND NOT a.indisunique AND NOT a.indisprimary AND NOT a.indisexclusion
    AND NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conindid = a.indexrelid)
  ORDER BY a.indexrelid, b.idx_scan DESC;
$$;


ALTER FUNCTION public.fn_redundant_dead_indexes() OWNER TO postgres;

--
-- Name: FUNCTION fn_redundant_dead_indexes(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_redundant_dead_indexes() IS 'Indexes never scanned in the lifetime of the database AND whose key columns are a leading prefix of another btree index on the same table. Reports only; it never drops anything. Added 2026-09-01 (Phase 4 index census).';


--
-- Name: fn_reel_falls_back_when_job_dies(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reel_falls_back_when_job_dies() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM 'failed' OR NEW.reel_id IS NULL THEN
    RETURN NEW;
  END IF;

  UPDATE public.social_reels r
  SET video_url = r.original_youtube_url,
      playback_type = 'youtube_embed',
      media_status = 'ready',
      native_processing_requested = false,
      source_type = CASE
        WHEN r.origin_type = 'video_library' THEN 'video_library'
        ELSE 'youtube'
      END
  WHERE r.id = NEW.reel_id
    AND r.media_status IN ('queued', 'processing')
    AND r.original_youtube_url IS NOT NULL
    AND r.youtube_video_id IS NOT NULL;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_reel_falls_back_when_job_dies skipped job % (%)', NEW.id, SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_reel_falls_back_when_job_dies() OWNER TO postgres;

--
-- Name: fn_refresh_active_poker_locations(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_refresh_active_poker_locations() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_count bigint; v_duration interval; v_started timestamptz;
BEGIN
    v_started := clock_timestamp();
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_active_poker_locations;
    v_duration := clock_timestamp() - v_started;
    SELECT COUNT(*) INTO v_count FROM mv_active_poker_locations;
    RETURN jsonb_build_object(
        'success', true, 
        'row_count', v_count,
        'duration_ms', EXTRACT(milliseconds FROM v_duration)
    );
END; $$;


