-- Name: fn_refresh_all_club_table_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_refresh_all_club_table_counts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n integer := 0;
BEGIN
  UPDATE clubs c
     SET table_count = fn_live_table_count(c.id)
   WHERE c.table_count IS DISTINCT FROM fn_live_table_count(c.id);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;


