BEGIN
    FOR v_group IN SELECT id FROM commander_home_groups WHERE is_active = true LOOP
        UPDATE commander_home_groups 
           SET vitality_score = public.compute_group_vitality_score(v_group.id),
               vitality_refreshed_at = NOW()
