--
-- Name: fn_release_phantom_seat_claims(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_release_phantom_seat_claims() RETURNS TABLE(tournament_id uuid, released integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH phantom AS (
    SELECT tp.tournament_id, tp.user_id
      FROM public.tournament_players tp
      JOIN public.tournaments t ON t.id = tp.tournament_id
     WHERE t.status = 'REGISTERING'
       AND (COALESCE(t.variant,'') = 'spin' OR COALESCE(t.max_players,0) <= 2)
       AND tp.table_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.table_seats s
          WHERE s.table_id = tp.table_id
            AND s.user_id  = tp.user_id
            AND s.left_at IS NULL
       )
  ), cleared AS (
    UPDATE public.tournament_players tp
       SET table_id = NULL, seat_number = NULL, status = 'registered'
      FROM phantom p
     WHERE tp.tournament_id = p.tournament_id
       AND tp.user_id       = p.user_id
    RETURNING tp.tournament_id
  )
  SELECT c.tournament_id, COUNT(*)::int FROM cleared c GROUP BY c.tournament_id;
END;
$$;


ALTER FUNCTION public.fn_release_phantom_seat_claims() OWNER TO postgres;

--
-- Name: fn_release_shop_stock(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_release_shop_stock(p_club_id uuid, p_item_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_stock integer;
BEGIN
  SELECT stock INTO v_stock
    FROM club_shop_items
   WHERE id = p_item_id AND club_id = p_club_id
   FOR UPDATE;

  IF NOT FOUND OR v_stock IS NULL THEN
    RETURN; -- unlimited or gone: nothing to give back
  END IF;

  UPDATE club_shop_items
     SET stock = v_stock + 1
   WHERE id = p_item_id AND club_id = p_club_id;
END;
$$;


ALTER FUNCTION public.fn_release_shop_stock(p_club_id uuid, p_item_id uuid) OWNER TO postgres;

--
-- Name: fn_release_tournament_holds(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_release_tournament_holds(p_tournament_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hold record;
  v_new_balance numeric;
BEGIN
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'p_tournament_id required';
  END IF;

  -- Find every active escrow hold for this tournament register flow
  FOR v_hold IN
    SELECT id, user_id, wallet_id, amount
      FROM public.chip_escrow_holds
     WHERE hold_type = 'tournament_register'
       AND related_id = p_tournament_id
       AND status     = 'held'
     FOR UPDATE
  LOOP
    -- Refund chips to user wallet
    UPDATE public.wallets
       SET balance    = balance + v_hold.amount,
           updated_at = NOW()
     WHERE user_id     = v_hold.user_id
       AND wallet_type = 'PLAYER'
    RETURNING balance INTO v_new_balance;

    -- Mark hold released
    UPDATE public.chip_escrow_holds
       SET status          = 'released',
           released_at     = NOW(),
           released_reason = 'tournament_canceled',
           updated_at      = NOW()
     WHERE id = v_hold.id;

    -- Ledger row
    IF v_new_balance IS NOT NULL THEN
      INSERT INTO public.wallet_transactions
        (user_id, wallet_type, type, amount, category, description,
         related_entity_id, balance_after)
      VALUES
        (v_hold.user_id, 'PLAYER', 'credit', v_hold.amount, 'tournament_refund',
         'Tournament Canceled - Escrow Refund',
         v_hold.id, v_new_balance);
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION public.fn_release_tournament_holds(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_relink_rake_record_to_hand(uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_relink_rake_record_to_hand(p_table_id uuid, p_hand_number bigint, p_hand_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_linked int;
  v_row record;
begin
  if p_table_id is null or p_hand_number is null or p_hand_id is null then
    return 0;
  end if;

  -- uq_rake_records_hand_id is UNIQUE on hand_id WHERE hand_id IS NOT NULL, so
  -- refuse rather than error if this hand id is already attached somewhere.
  if exists (select 1 from public.rake_records where hand_id = p_hand_id) then
    return 0;
  end if;

  update public.rake_records r
     set hand_id = p_hand_id
   where r.id = (
           select id
             from public.rake_records
            where table_id = p_table_id
              and hand_id is null
              and metadata->>'hand_number' = p_hand_number::text
            order by created_at, id
            limit 1
            for update skip locked
         )
     and r.hand_id is null
  returning r.* into v_row;

  get diagnostics v_linked = row_count;

  -- WEIGHTED CONTRIBUTED RAKE (2026-08-29): a null-hand banking skipped the
  -- per-player ledger (it keys on hand_id). Now that the hand id exists,
  -- write the ledger the same way atomic_distribute_rake would have.
  if v_linked > 0 and v_row.rake_amount > 0
     and v_row.player_contributions is not null
     and jsonb_typeof(v_row.player_contributions) = 'object' then
    insert into public.rake_attributions (
      hand_id, player_id, rake_amount, rake_record_id, table_id, club_id,
      gross_contribution, returned_uncalled, eligible_contribution,
      contribution_weight, weighted_rake_credit, bbj_attributed_contribution,
      rake_method
    )
    select p_hand_id, a.user_id, a.credit, v_row.id, v_row.table_id, v_row.club_id,
           (v_row.player_contributions ->> a.user_id::text)::numeric
             + coalesce((v_row.returned_uncalled ->> a.user_id::text)::numeric, 0),
           coalesce((v_row.returned_uncalled ->> a.user_id::text)::numeric, 0),
           (v_row.player_contributions ->> a.user_id::text)::numeric,
           a.weight, a.credit, coalesce(b.credit, 0),
           coalesce(v_row.rake_method, 'DEALT_EQUAL')
      from public.fn_allocate_rake_credits(
             v_row.rake_amount, v_row.player_contributions,
             coalesce(v_row.rake_method, 'DEALT_EQUAL')) a
      left join public.fn_allocate_rake_credits(
             coalesce(v_row.bbj_contribution, 0), v_row.player_contributions,
             coalesce(v_row.rake_method, 'DEALT_EQUAL')) b
        on b.user_id = a.user_id
    on conflict (hand_id, player_id) do nothing;
  end if;

  return v_linked;
end;
$$;


ALTER FUNCTION public.fn_relink_rake_record_to_hand(p_table_id uuid, p_hand_number bigint, p_hand_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_relink_rake_record_to_hand(p_table_id uuid, p_hand_number bigint, p_hand_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_relink_rake_record_to_hand(p_table_id uuid, p_hand_number bigint, p_hand_id uuid) IS 'Attach a hand_history row written late (after a transient write outage) to the rake_records row banked for the same hand. Matches on (table_id, metadata->>hand_number). Returns the number of rows ACTUALLY linked (0 or 1) — a caller must not read 0 as failure: a tournament hand, a zero-rake hand, or a hand whose rake row has not been created yet all legitimately return 0. Added 2026-08-20, made single-statement 2026-08-20 after review.';


