-- Name: fn_remove_friend(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_remove_friend(p_user_id uuid, p_friend_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    DELETE FROM friendships WHERE 
        (user_id = p_user_id AND friend_id = p_friend_id) OR
        (user_id = p_friend_id AND friend_id = p_user_id);
END;
$$;


