--
-- Name: fn_remove_member_from_group_conversation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_remove_member_from_group_conversation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_conv_id uuid; v_user_id uuid; v_group_id uuid;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.status = 'banned' AND OLD.status <> 'banned' THEN
        v_user_id := NEW.user_id; v_group_id := NEW.group_id;
    ELSIF TG_OP = 'DELETE' THEN
        v_user_id := OLD.user_id; v_group_id := OLD.group_id;
    ELSE RETURN COALESCE(NEW, OLD);
    END IF;
    SELECT messenger_conversation_id INTO v_conv_id FROM commander_home_groups WHERE id = v_group_id;
    IF v_conv_id IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
    DELETE FROM messenger_participants WHERE conversation_id = v_conv_id AND user_id = v_user_id;
    UPDATE conversations SET participant_ids = array_remove(participant_ids, v_user_id), updated_at = NOW() WHERE id = v_conv_id;
    RETURN COALESCE(NEW, OLD);
END; $$;


ALTER FUNCTION public.fn_remove_member_from_group_conversation() OWNER TO postgres;

--
-- Name: fn_remove_settled_club_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_remove_settled_club_member(p_club_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
DECLARE
  v_me uuid := auth.uid();
  v_owner uuid;
  v_caller_role text;
  v_target public.club_members%ROWTYPE;
  v_changed integer := 0;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication Required');
  END IF;
  IF p_club_id IS NULL OR p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Choose A Club Member');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:' || p_club_id::text, 0));

  SELECT c.owner_id INTO v_owner
    FROM public.clubs c
   WHERE c.id = p_club_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Club Not Found');
  END IF;

  -- Lock caller and target in deterministic order before reading authority.
  -- A concurrent demotion/suspension must finish before this decision, not
  -- revoke the caller one instruction after an unlocked authorization read.
  PERFORM 1 FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id IN (v_me, p_user_id)
   ORDER BY cm.user_id
   FOR UPDATE;

  SELECT cm.role INTO v_caller_role
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id
     AND cm.user_id = v_me
     AND coalesce(cm.status::text, 'active') IN ('active', 'approved');

  IF v_me IS DISTINCT FROM v_owner
     AND coalesce(v_caller_role, '') NOT IN ('owner', 'club_owner', 'co_owner', 'admin', 'club_admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only Club Staff Can Remove A Member');
  END IF;

  SELECT * INTO v_target
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = p_user_id;

  -- A legacy deployment may already have physically removed the row. Staff
  -- authorization was checked before returning the idempotent result.
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', true, 'already_departed', true, 'legacy_absent', true
    );
  END IF;

  IF v_target.membership_lifecycle_status = 'departed' THEN
    RETURN jsonb_build_object(
      'success', true, 'already_departed', true, 'legacy_absent', false,
      'user_id', p_user_id, 'departed_at', v_target.departed_at
    );
  END IF;

  IF p_user_id = v_owner OR v_target.role IN ('owner', 'club_owner') THEN
    RETURN jsonb_build_object('success', false, 'error', 'The Club Owner Cannot Be Removed');
  END IF;
  IF v_target.role IN ('co_owner', 'admin', 'club_admin') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Demote Club Staff To Player Before Marking The Membership Departed'
    );
  END IF;

  IF abs(coalesce(v_target.chip_balance, 0))
       + abs(coalesce(v_target.held_chips, 0))
       + abs(coalesce(v_target.locked_chips, 0))
       + abs(coalesce(v_target.promo_balance, 0))
       + abs(coalesce(v_target.credit_used, 0))
       + abs(coalesce(v_target.diamonds, 0)) <> 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Settle Every Member Balance, Credit Line And Diamond Balance Before Removing Them'
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.agents a
     WHERE a.club_id = p_club_id AND a.user_id = p_user_id
     FOR UPDATE
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Demote And Settle This Agent Wallet Before Removing The Membership'
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.club_id = p_club_id
       AND cm.user_id <> p_user_id
       AND cm.membership_lifecycle_status = 'active'
       AND (
         cm.agent_id IN (p_user_id, v_target.id)
         OR cm.parent_agent_id IN (p_user_id, v_target.id)
       )
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Reassign This Member''s Downline Before Removing Them'
    );
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.table_seats ts
      JOIN public.tables t ON t.id = ts.table_id
     WHERE t.club_id = p_club_id
       AND ts.user_id = p_user_id
       AND ts.left_at IS NULL
     FOR UPDATE OF ts
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Remove This Member From Live Tables First');
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.tournament_players tp
      JOIN public.tournaments tr ON tr.id = tp.tournament_id
     WHERE tr.club_id = p_club_id
       AND tp.user_id = p_user_id
       AND lower(coalesce(tp.status::text, '')) IN ('registered', 'playing')
     FOR UPDATE OF tp
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Settle This Member''s Tournament Entry First');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.cashout_requests cr
     WHERE cr.club_id = p_club_id
       AND (cr.player_id = p_user_id OR cr.agent_id = p_user_id)
       AND cr.status IN ('pending', 'approved')
     FOR UPDATE
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Resolve This Member''s Cashout Requests First');
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.chip_escrow ce
      JOIN public.cashout_requests cr ON cr.id = ce.cashout_request_id
     WHERE cr.club_id = p_club_id
       AND ce.player_id = p_user_id
       AND ce.released_at IS NULL
     FOR UPDATE OF ce
  ) OR EXISTS (
    SELECT 1 FROM public.chip_escrow_holds h
     WHERE h.club_id = p_club_id
       AND h.user_id = p_user_id
       AND h.status = 'held'
     FOR UPDATE
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Release This Member''s Escrow First');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.tournament_tickets tt
     WHERE tt.club_id = p_club_id
       AND tt.holder_id = p_user_id
       AND tt.status = 'issued'
     FOR UPDATE
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Resolve This Member''s Open Tickets First');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.chip_requests r
     WHERE r.club_id = p_club_id
       AND (r.requester_id = p_user_id OR r.approver_id = p_user_id)
       AND r.status = 'pending'
     FOR UPDATE
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Resolve This Member''s Chip Requests First');
  END IF;

  INSERT INTO public.audit_trail(
    actor_id, actor_role, action, target_type, target_id, club_id,
    before_state, after_state, reason
  ) VALUES (
    v_me,
    CASE WHEN v_me = v_owner THEN 'owner'
         WHEN v_caller_role = 'co_owner' THEN 'co_owner'
         ELSE 'host' END,
    'depart_club_member', 'membership', v_target.id, p_club_id,
    jsonb_build_object(
      'user_id', v_target.user_id, 'role', v_target.role,
      'status', v_target.status::text,
      'membership_lifecycle_status', v_target.membership_lifecycle_status
    ),
    jsonb_build_object(
      'departed', true, 'status', 'suspended', 'is_active', false,
      'membership_lifecycle_status', 'departed',
      'user_id', v_target.user_id
    ),
    'Settled Membership Departure'
  );

  PERFORM set_config('app.club_membership_lifecycle_write', 'depart', true);
  UPDATE public.club_members cm
     SET status = 'suspended',
         is_active = false,
         membership_lifecycle_status = 'departed',
         departed_at = clock_timestamp(),
         departed_by = v_me,
         departure_reason = 'Removed By Club Staff',
         updated_at = clock_timestamp()
   WHERE cm.id = v_target.id
     AND cm.club_id = p_club_id
     AND cm.membership_lifecycle_status = 'active';
  GET DIAGNOSTICS v_changed = ROW_COUNT;
  PERFORM set_config('app.club_membership_lifecycle_write', '', true);

  IF v_changed <> 1 THEN
    RAISE EXCEPTION 'membership changed during departure' USING ERRCODE = '40001';
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'already_departed', false, 'user_id', p_user_id,
    'records_retained', true
  );
END
$$;


ALTER FUNCTION public.fn_remove_settled_club_member(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_renumber_duplicate_places(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_renumber_duplicate_places(p_apply boolean DEFAULT false, p_limit integer DEFAULT 100000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t record; v_d record;
  v_taken integer[]; v_pos integer;
  v_moved integer := 0; v_events integer := 0; v_skipped_first integer := 0;
  v_demoted_total integer := 0; v_plan jsonb;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS _renum_plan (
    tournament_id uuid, user_id uuid, old_position integer,
    new_position integer, prize_paid numeric) ON COMMIT DROP;
  DELETE FROM _renum_plan;

  SELECT count(*) INTO v_skipped_first
    FROM (SELECT tournament_id FROM public.tournament_players
           WHERE position = 1 GROUP BY 1 HAVING count(*) > 1) x;

  FOR v_t IN
    SELECT DISTINCT tournament_id FROM (
      SELECT tournament_id, position FROM public.tournament_players
       WHERE position IS NOT NULL GROUP BY 1,2 HAVING count(*) > 1) d
     WHERE tournament_id NOT IN (
       SELECT tournament_id FROM public.tournament_players
        WHERE position = 1 GROUP BY 1 HAVING count(*) > 1)
     LIMIT GREATEST(p_limit, 1)
  LOOP
    v_events := v_events + 1;

    SELECT array_agg(DISTINCT position) INTO v_taken
      FROM public.tournament_players
     WHERE tournament_id = v_t.tournament_id AND position IS NOT NULL;

    FOR v_d IN
      SELECT user_id, old_pos, prize FROM (
        SELECT tp.user_id, tp.position AS old_pos, COALESCE(tp.prize, 0) AS prize,
               row_number() OVER (PARTITION BY tp.position
                 ORDER BY tp.eliminated_at DESC NULLS FIRST,
                          COALESCE(tp.chips, 0) DESC, tp.id) AS grp_rn
          FROM public.tournament_players tp
         WHERE tp.tournament_id = v_t.tournament_id AND tp.position IS NOT NULL) r
       WHERE grp_rn > 1
       ORDER BY old_pos, prize DESC
    LOOP
      v_demoted_total := v_demoted_total + 1;

      -- Smallest place strictly worse than the contested one that nobody holds.
      v_pos := v_d.old_pos + 1;
      WHILE v_pos = ANY (v_taken) LOOP
        v_pos := v_pos + 1;
        IF v_pos > 100000 THEN
          RAISE EXCEPTION 'no free finishing place below % in tournament %',
            v_d.old_pos, v_t.tournament_id;
        END IF;
      END LOOP;

      v_taken := v_taken || v_pos;
      INSERT INTO _renum_plan VALUES
        (v_t.tournament_id, v_d.user_id, v_d.old_pos, v_pos, v_d.prize);
      v_moved := v_moved + 1;
    END LOOP;
  END LOOP;

  -- Nothing may be dropped between "needs a place" and "got a place".
  IF v_moved <> v_demoted_total THEN
    RAISE EXCEPTION 'planned % moves for % demoted rows', v_moved, v_demoted_total;
  END IF;

  IF p_apply THEN
    INSERT INTO public.tournament_place_renumbers
      (tournament_id, user_id, old_position, new_position, prize_paid, reason)
    SELECT tournament_id, user_id, old_position, new_position, prize_paid,
           'duplicate finishing place; later elimination keeps the place'
      FROM _renum_plan
    ON CONFLICT DO NOTHING;

    UPDATE public.tournament_players tp
       SET position = p.new_position
      FROM _renum_plan p
     WHERE tp.tournament_id = p.tournament_id
       AND tp.user_id = p.user_id
       AND tp.position = p.old_position;
  END IF;

  SELECT jsonb_agg(jsonb_build_object('tournament_id', tournament_id,
           'from', old_position, 'to', new_position, 'prize_paid', prize_paid)
           ORDER BY tournament_id, old_position)
    INTO v_plan
    FROM (SELECT * FROM _renum_plan ORDER BY tournament_id, old_position LIMIT 12) s;

  RETURN jsonb_build_object('ok', true, 'applied', p_apply,
    'rows_moved', v_moved, 'tournaments', v_events,
    'events_excluded_contested_first_place', v_skipped_first,
    'sample', COALESCE(v_plan, '[]'::jsonb));
END;
$$;


ALTER FUNCTION public.fn_renumber_duplicate_places(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: fn_repair_tournament_rake_attribution(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_repair_tournament_rake_attribution(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row record; v_att jsonb; v_msg text;
  v_repaired integer := 0; v_failed integer := 0;
  v_before integer; v_after integer;
  v_users integer; v_members integer;
BEGIN
  SELECT count(*) INTO v_before
    FROM public.tournament_rake_settlements
   WHERE attributed_at IS NULL AND settled_at IS NOT NULL AND amount > 0;

  FOR v_row IN
    SELECT tournament_id
      FROM public.tournament_rake_settlements
     WHERE attributed_at IS NULL AND settled_at IS NOT NULL AND amount > 0
     ORDER BY settled_at ASC
     LIMIT GREATEST(p_limit, 1)
  LOOP
    BEGIN
      v_att := public.fn_attribute_tournament_rake(v_row.tournament_id);
      v_users   := COALESCE((v_att->>'attributed_users')::int, 0);
      v_members := COALESCE((v_att->>'members')::int, 0);

      IF COALESCE((v_att->>'ok')::boolean, false) AND (v_users > 0 OR v_members = 0) THEN
        UPDATE public.tournament_rake_settlements
           SET attributed_at = now(), attribution_error = NULL, attributed_users = v_users
         WHERE tournament_id = v_row.tournament_id;
        v_repaired := v_repaired + 1;

        UPDATE public.financial_alerts
           SET resolved = true, resolved_at = now()
         WHERE source = 'fn_settle_tournament_rake'
           AND resolved IS NOT TRUE
           AND message LIKE 'Rake settled but attribution failed%'
           AND (context->>'tournament_id')::uuid = v_row.tournament_id;
      ELSE
        IF v_att->>'reason' = 'no_club' THEN
          UPDATE public.tournament_rake_settlements
             SET attributed_at = now(), attribution_error = 'no_club', attributed_users = 0
           WHERE tournament_id = v_row.tournament_id;
        ELSE
          UPDATE public.tournament_rake_settlements
             SET attribution_error = COALESCE(v_att->>'reason', 'attributed_nobody'),
                 attributed_users = v_users
           WHERE tournament_id = v_row.tournament_id;
          v_failed := v_failed + 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT;
      UPDATE public.tournament_rake_settlements
         SET attribution_error = v_msg
       WHERE tournament_id = v_row.tournament_id;
      v_failed := v_failed + 1;
    END;
  END LOOP;

  SELECT count(*) INTO v_after
    FROM public.tournament_rake_settlements
   WHERE attributed_at IS NULL AND settled_at IS NOT NULL AND amount > 0;

  RETURN jsonb_build_object('ok', true, 'queue_before', v_before,
    'queue_after', v_after, 'repaired', v_repaired, 'still_failing', v_failed);
END;
$$;


ALTER FUNCTION public.fn_repair_tournament_rake_attribution(p_limit integer) OWNER TO postgres;

--
-- Name: fn_repay_unaccounted_seat_exits(interval, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_repay_unaccounted_seat_exits(p_since interval DEFAULT '2 days'::interval, p_max_total numeric DEFAULT 25000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r         record;
  v_balance numeric;
  v_paid    numeric := 0;
  v_repaid  int     := 0;
  v_skipped int     := 0;
  v_ids     bigint[] := '{}';
BEGIN
  IF p_max_total IS NULL OR p_max_total <= 0 THEN
    RAISE EXCEPTION 'fn_repay_unaccounted_seat_exits: p_max_total must be positive';
  END IF;

  PERFORM set_config('app.ledger_counterparty', 'table_stack', true);
  PERFORM set_config('app.ledger_category', 'correction', true);

  FOR r IN
    SELECT e.exit_id, e.user_id, e.table_id, e.club_id, e.stack, e.occurred_at
      FROM public.fn_unaccounted_seat_exits(p_since) e
     WHERE e.stack > 0
     ORDER BY e.occurred_at
  LOOP
    IF v_paid + r.stack > p_max_total THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    UPDATE public.club_members
       SET chip_balance = chip_balance + r.stack
     WHERE club_id = r.club_id
       AND user_id = r.user_id
    RETURNING chip_balance INTO v_balance;

    IF NOT FOUND THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    INSERT INTO public.wallet_transactions
      (user_id, wallet_type, amount, type, category, description, table_id, balance_after)
    VALUES
      (r.user_id, 'PLAYER', r.stack, 'credit', 'cashout',
       'Correction: seat exit ' || r.exit_id
         || ' - stack left the felt with no cash-out',
       r.table_id, v_balance);

    v_paid   := v_paid + r.stack;
    v_repaid := v_repaid + 1;
    v_ids    := v_ids || r.exit_id;
  END LOOP;

  RETURN jsonb_build_object(
    'repaid',   v_repaid,
    'chips',    round(v_paid, 2),
    'skipped',  v_skipped,
    'exit_ids', to_jsonb(v_ids)
  );
END;
$$;


ALTER FUNCTION public.fn_repay_unaccounted_seat_exits(p_since interval, p_max_total numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_repay_unaccounted_seat_exits(p_since interval, p_max_total numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_repay_unaccounted_seat_exits(p_since interval, p_max_total numeric) IS 'Returns stacks that left the felt with no wallet credit, reading fn_unaccounted_seat_exits live so nothing is paid twice. Not scheduled on purpose.';


--
-- Name: fn_replace_licensed_poy_rankings(integer, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_replace_licensed_poy_rankings(p_year integer, p_rows jsonb, p_source_url text, p_source_updated_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  inserted_count integer;
begin
  if (select auth.role()) <> 'service_role' then
    raise exception 'service role required';
  end if;
  if p_year < 2000 or p_year > extract(year from now())::integer + 1 then
    raise exception 'invalid ranking year';
  end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) < 1 or jsonb_array_length(p_rows) > 500 then
    raise exception 'ranking payload must contain 1..500 rows';
  end if;

  delete from public.poy_leaderboard where year = p_year;

  insert into public.poy_leaderboard (
    player_name, external_player_id, points, rank, year, source,
    source_url, source_updated_at, country, team, updated_at
  )
  select
    nullif(trim(row.player_name), ''),
    nullif(trim(row.external_player_id), ''),
    row.points,
    row.rank,
    p_year,
    'gpi_licensed_feed',
    p_source_url,
    p_source_updated_at,
    nullif(trim(row.country), ''),
    nullif(trim(row.team), ''),
    now()
  from jsonb_to_recordset(p_rows) as row(
    player_name text,
    external_player_id text,
    points numeric,
    rank integer,
    country text,
    team text
  )
  where row.player_name is not null
    and row.rank between 1 and 500
    and row.points >= 0;

  get diagnostics inserted_count = row_count;
  if inserted_count = 0 then
    raise exception 'ranking payload produced no valid rows';
  end if;
  return inserted_count;
end;
$$;


ALTER FUNCTION public.fn_replace_licensed_poy_rankings(p_year integer, p_rows jsonb, p_source_url text, p_source_updated_at timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_replication_slot_metrics(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_replication_slot_metrics() RETURNS TABLE(slot_name text, slot_type text, active boolean, restart_lag_bytes bigint, flush_lag_bytes bigint, wal_position_bytes bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT
    s.slot_name::text,
    s.slot_type::text,
    s.active,
    CASE
      WHEN pg_is_in_recovery() OR s.restart_lsn IS NULL THEN NULL
      ELSE (pg_current_wal_lsn() - s.restart_lsn)::bigint
    END,
    CASE
      WHEN pg_is_in_recovery() OR s.confirmed_flush_lsn IS NULL THEN NULL
      ELSE (pg_current_wal_lsn() - s.confirmed_flush_lsn)::bigint
    END,
    CASE
      WHEN pg_is_in_recovery() THEN NULL
      ELSE (pg_current_wal_lsn() - '0/0'::pg_lsn)::bigint
    END
  FROM pg_replication_slots s
$$;


ALTER FUNCTION public.fn_replication_slot_metrics() OWNER TO postgres;

--
-- Name: FUNCTION fn_replication_slot_metrics(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_replication_slot_metrics() IS 'Replication slot lag in bytes, per slot, for the engine''s Prometheus gauges. Read-only; service_role only. NULL rather than 0 when the reading is unavailable (standby, or an inactive slot with no restart_lsn) - a lag of zero is the perfect score and must never be faked. See server/src/services/ReplicationMetrics.ts and infra/monitoring/alert-rules.yml.';


--
-- Name: fn_request_cashout(uuid, uuid, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_request_cashout(p_player_id uuid, p_club_id uuid, p_amount numeric, p_note text DEFAULT NULL::text, p_agent_id uuid DEFAULT NULL::uuid, p_type text DEFAULT 'request'::text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_cashout_id uuid;
  v_resolved_agent_id uuid;
  v_player_balance numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'cashout amount must be > 0';
  END IF;

  v_resolved_agent_id := p_agent_id;
  IF v_resolved_agent_id IS NULL THEN
    SELECT agent_id INTO v_resolved_agent_id
    FROM club_members
    WHERE club_id = p_club_id AND user_id = p_player_id;
  END IF;

  IF v_resolved_agent_id IS NULL THEN
    SELECT owner_id INTO v_resolved_agent_id FROM clubs WHERE id = p_club_id;
  END IF;

  IF v_resolved_agent_id IS NULL THEN
    SELECT user_id INTO v_resolved_agent_id
    FROM club_members
    WHERE club_id = p_club_id AND role IN ('owner', 'co_owner', 'admin', 'super_agent', 'agent')
    ORDER BY CASE role
      WHEN 'owner' THEN 1 WHEN 'co_owner' THEN 2 WHEN 'admin' THEN 3
      WHEN 'super_agent' THEN 4 ELSE 5 END
    LIMIT 1;
  END IF;

  IF v_resolved_agent_id IS NULL THEN
    RAISE EXCEPTION 'no agent/owner available to approve cashout in club %', p_club_id;
  END IF;

  SELECT chip_balance INTO v_player_balance
  FROM club_members
  WHERE club_id = p_club_id AND user_id = p_player_id FOR UPDATE;

  IF v_player_balance IS NULL THEN
    RAISE EXCEPTION 'player is not a member of this club';
  END IF;

  IF v_player_balance < p_amount THEN
    RAISE EXCEPTION 'insufficient chips: have %, requested %', v_player_balance, p_amount;
  END IF;

  UPDATE club_members
  SET chip_balance = COALESCE(chip_balance, 0) - p_amount,
      updated_at = NOW()
  WHERE club_id = p_club_id AND user_id = p_player_id;

  INSERT INTO cashout_requests (
    id, club_id, player_id, agent_id, amount,
    status, player_note, created_at, updated_at
  ) VALUES (
    gen_random_uuid(), p_club_id, p_player_id, v_resolved_agent_id, p_amount,
    'pending', p_note, NOW(), NOW()
  ) RETURNING id INTO v_cashout_id;

  -- THE ESCROW ROW WAS MISSING (2026-08-25). This function debited the player
  -- and opened the request but never wrote the hold, so chip_escrow was empty
  -- for every request the World Hub route created and "held in escrow" was a
  -- sentence in the UI rather than a row anywhere. fn_cashout_approve REQUIRES
  -- the hold before it will release anything, so without this the two doors
  -- into the same flow produced incompatible state.
  INSERT INTO chip_escrow (cashout_request_id, player_id, amount, club_id, locked_at)
  VALUES (v_cashout_id, p_player_id, p_amount, p_club_id, NOW())
  ON CONFLICT (cashout_request_id) DO NOTHING;

  INSERT INTO chip_transactions (
    id, club_id, from_user_id, to_user_id, amount,
    transaction_type, notes, related_cashout_id, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), p_club_id, p_player_id, v_resolved_agent_id, p_amount,
    'cashout_request_escrow', COALESCE(p_note, 'Cash Out Requested. Chips Held In Escrow'),
    v_cashout_id, v_player_balance - p_amount, NOW()
  );

  RETURN v_cashout_id;
END;
$$;


ALTER FUNCTION public.fn_request_cashout(p_player_id uuid, p_club_id uuid, p_amount numeric, p_note text, p_agent_id uuid, p_type text) OWNER TO postgres;

--
-- Name: FUNCTION fn_request_cashout(p_player_id uuid, p_club_id uuid, p_amount numeric, p_note text, p_agent_id uuid, p_type text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_request_cashout(p_player_id uuid, p_club_id uuid, p_amount numeric, p_note text, p_agent_id uuid, p_type text) IS 'BUG 025: real implementation replacing silent-success stub. Atomically debits player chips, resolves agent, inserts cashout_requests with status=pending, writes chip_transactions escrow row. Returns new cashout UUID.';


--
-- Name: fn_request_chips(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_request_chips(p_club_id uuid, p_amount numeric, p_note text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me uuid := auth.uid();
  v_agent uuid;
  v_open integer;
  v_prior public.chip_requests%rowtype;
  v_note text := NULLIF(BTRIM(COALESCE(p_note, '')), '');
  v_id uuid;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not Authenticated');
  END IF;
  IF p_op_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'A Retry Key Is Required');
  END IF;
  IF p_club_id IS NULL OR p_amount IS NULL OR p_amount <= 0 OR p_amount > 1e9 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Enter A Valid Request Amount');
  END IF;
  IF p_amount <> ROUND(p_amount, 2) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Chips Move In Hundredths At Most');
  END IF;
  IF v_note IS NOT NULL AND length(v_note) > 500 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request Note Is Too Long');
  END IF;

  -- One requester/club lock makes both replay and max-three authoritative
  -- under concurrent submissions.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('chip-request:' || p_club_id::text || ':' || v_me::text, 0)
  );

  SELECT *
    INTO v_prior
    FROM public.chip_requests
   WHERE club_id = p_club_id
     AND requester_id = v_me
     AND op_id = p_op_id;
  IF FOUND THEN
    IF v_prior.amount IS DISTINCT FROM p_amount OR v_prior.note IS DISTINCT FROM v_note THEN
      RETURN jsonb_build_object(
        'success', false, 'error', 'That Retry Key Belongs To A Different Request'
      );
    END IF;
    RETURN jsonb_build_object(
      'success', true, 'request_id', v_prior.id, 'replayed', true
    );
  END IF;

  SELECT cm.agent_id
    INTO v_agent
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id
     AND cm.user_id = v_me
     AND COALESCE(cm.status::text, 'active') IN ('active', 'approved')
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'You Are Not An Active Member Of This Club'
    );
  END IF;

  IF v_agent IS NULL THEN
    SELECT owner_id INTO v_agent FROM public.clubs WHERE id = p_club_id;
  END IF;

  SELECT COUNT(*)
    INTO v_open
    FROM public.chip_requests
   WHERE club_id = p_club_id
     AND requester_id = v_me
     AND status = 'pending';
  IF v_open >= 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'You Already Have 3 Open Requests');
  END IF;

  INSERT INTO public.chip_requests (
    club_id, requester_id, approver_id, amount, note, op_id
  ) VALUES (
    p_club_id, v_me, v_agent, p_amount, v_note, p_op_id
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'success', true, 'request_id', v_id, 'replayed', false
  );
END
$$;


ALTER FUNCTION public.fn_request_chips(p_club_id uuid, p_amount numeric, p_note text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_request_manual_bomb_pot(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_request_manual_bomb_pot(p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_club uuid;
  v_enabled boolean;
  v_role text;
  v_is_owner boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  SELECT club_id, bomb_pot_enabled INTO v_club, v_enabled
  FROM public.tables WHERE id = p_table_id;

  IF v_club IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;
  IF v_enabled IS DISTINCT FROM true THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bomb_pots_disabled');
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = v_club AND c.owner_id = v_uid)
    INTO v_is_owner;
  SELECT lower(cm.role) INTO v_role
  FROM public.club_members cm
  WHERE cm.club_id = v_club AND cm.user_id = v_uid
  LIMIT 1;

  IF NOT (v_is_owner OR v_role IN ('owner', 'co_owner', 'admin')) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  UPDATE public.tables SET bomb_pot_manual_pending = true WHERE id = p_table_id;
  INSERT INTO public.bomb_pot_manual_requests (table_id, club_id, requested_by)
  VALUES (p_table_id, v_club, v_uid);

  BEGIN
    PERFORM realtime.send(
      jsonb_build_object('table_id', p_table_id, 'requested_by', v_uid),
      'bomb_pot_manual_requested',
      'engine:bomb-requests',
      false
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_request_manual_bomb_pot: realtime.send failed: %', SQLERRM;
  END;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION public.fn_request_manual_bomb_pot(p_table_id uuid) OWNER TO postgres;

--
-- Name: fn_requeue_unbanked_cash_rake(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_requeue_unbanked_cash_rake(p_since_hours integer DEFAULT 6, p_min_age_minutes integer DEFAULT 10, p_limit integer DEFAULT 200) RETURNS TABLE(hand_id uuid, table_id uuid, rake numeric, bbj numeric, hand_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT h.id, h.table_id, h.hand_number, h.created_at,
           COALESCE(h.rake_amount,0) rake, COALESCE(h.bbj_amount,0) bbj,
           COALESCE(h.pot_size, h.rake_amount) pot,
           h.players, h.big_blind
      FROM public.hand_history h
     WHERE h.tournament_id IS NULL
       AND COALESCE(h.rake_amount,0) > 0
       AND h.created_at > now() - make_interval(hours => GREATEST(COALESCE(p_since_hours,6),1))
       AND h.created_at < now() - make_interval(mins => GREATEST(COALESCE(p_min_age_minutes,10),1))
       AND NOT EXISTS (SELECT 1 FROM public.rake_records rr WHERE rr.hand_id = h.id)
       AND NOT EXISTS (SELECT 1 FROM public.pending_fee_distributions p WHERE p.hand_id = h.id)
     ORDER BY h.created_at
     LIMIT GREATEST(COALESCE(p_limit,200),1)
  LOOP
    INSERT INTO public.pending_fee_distributions (
      id, table_id, club_id, hand_id, hand_number, rake, bbj, pot,
      num_players, contributions, tournament_id, big_blind, kind, rake_method)
    SELECT gen_random_uuid(), r.table_id,
           COALESCE(t.club_id, 'fade0000-0000-0000-0000-000000000001'),
           r.id, r.hand_number, r.rake, r.bbj, r.pot,
           GREATEST(COALESCE(jsonb_array_length(r.players), 2), 1),
           -- Equal weights over the dealt-in players; the DEALT_EQUAL stamp
           -- below is what makes the allocator split equally rather than
           -- weight. hand_history carries ENDING STACKS, never per-street
           -- contribution, so a weighted split cannot be reconstructed here
           -- and pretending otherwise would label a guess as truth.
           COALESCE((SELECT jsonb_object_agg(p->>'userId', 1)
                       FROM jsonb_array_elements(r.players) p
                      WHERE p->>'userId' IS NOT NULL), '{}'::jsonb),
           NULL, r.big_blind, 'rake', 'DEALT_EQUAL'
      FROM public.tables t WHERE t.id = r.table_id;

    IF FOUND THEN
      hand_id := r.id; table_id := r.table_id; rake := r.rake; bbj := r.bbj;
      hand_at := r.created_at;
      RETURN NEXT;
    END IF;
  END LOOP;
END $$;


ALTER FUNCTION public.fn_requeue_unbanked_cash_rake(p_since_hours integer, p_min_age_minutes integer, p_limit integer) OWNER TO postgres;

--
-- Name: fn_requeue_unbanked_fees(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_requeue_unbanked_fees(p_apply boolean DEFAULT false, p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  a record; v_pending uuid; v_accounted boolean;
  v_requeued int := 0; v_already int := 0; v_skipped int := 0;
  v_rake numeric := 0; v_bbj numeric := 0;
  v_open_before int; v_open_after int;
BEGIN
  SELECT count(*) INTO v_open_before FROM public.financial_alerts
   WHERE source = 'FeeReconciler.queue_failed' AND resolved IS NOT TRUE;

  FOR a IN
    SELECT f.id AS alert_id, f.context AS c
      FROM public.financial_alerts f
     WHERE f.source = 'FeeReconciler.queue_failed'
       AND f.resolved IS NOT TRUE
       AND f.context->>'kind' IS NOT NULL
       AND f.context->>'tableId' IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.fee_requeue_log l WHERE l.alert_id = f.id)
     ORDER BY f.created_at ASC
     LIMIT GREATEST(p_limit, 1)
  LOOP
    v_accounted := public.fn_fee_is_accounted_for(
      a.c->>'kind',
      (a.c->>'tableId')::uuid,
      NULLIF(a.c->>'handId', '')::uuid,
      COALESCE((a.c->>'handNumber')::bigint, 0));

    IF v_accounted THEN
      IF p_apply THEN
        INSERT INTO public.fee_requeue_log
          (alert_id, kind, table_id, hand_number, rake, bbj, outcome)
        VALUES (a.alert_id, a.c->>'kind', (a.c->>'tableId')::uuid,
                COALESCE((a.c->>'handNumber')::bigint, 0),
                COALESCE((a.c->>'rake')::numeric, 0),
                COALESCE((a.c->>'bbj')::numeric, 0), 'already_accounted')
        ON CONFLICT (alert_id) DO NOTHING;
        UPDATE public.financial_alerts
           SET resolved = true, resolved_at = now() WHERE id = a.alert_id;
      END IF;
      v_already := v_already + 1;
      CONTINUE;
    END IF;

    IF NOT p_apply THEN
      v_requeued := v_requeued + 1;
      v_rake := v_rake + COALESCE((a.c->>'rake')::numeric, 0);
      v_bbj  := v_bbj  + COALESCE((a.c->>'bbj')::numeric, 0);
      CONTINUE;
    END IF;

    INSERT INTO public.pending_fee_distributions
      (table_id, club_id, hand_id, hand_number, rake, bbj, pot, num_players,
       contributions, tournament_id, big_blind, kind, last_error,
       rake_method, returned_uncalled)
    VALUES (
      (a.c->>'tableId')::uuid,
      NULLIF(a.c->>'clubId', '')::uuid,
      NULLIF(a.c->>'handId', '')::uuid,
      COALESCE((a.c->>'handNumber')::bigint, 0),
      COALESCE((a.c->>'rake')::numeric, 0),
      COALESCE((a.c->>'bbj')::numeric, 0),
      COALESCE((a.c->>'pot')::numeric, 0),
      COALESCE((a.c->>'numPlayers')::int, 0),
      COALESCE(a.c->'contributions', '{}'::jsonb),
      NULLIF(a.c->>'tournamentId', '')::uuid,
      NULLIF(a.c->>'bigBlind', '')::numeric,
      a.c->>'kind',
      'requeued from financial_alerts by fn_requeue_unbanked_fees',
      -- WEIGHTED CONTRIBUTED RAKE (2026-08-29): a re-driven hand keeps the
      -- methodology it was played under. Alerts older than the weighted
      -- engine have no rakeMethod; NULL correctly re-drives as DEALT_EQUAL.
      NULLIF(a.c->>'rakeMethod', ''),
      CASE WHEN jsonb_typeof(a.c->'returnedUncalled') = 'object'
           THEN a.c->'returnedUncalled' ELSE NULL END)
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_pending;

    INSERT INTO public.fee_requeue_log
      (alert_id, pending_id, kind, table_id, hand_number, rake, bbj, outcome)
    VALUES (a.alert_id, v_pending, a.c->>'kind', (a.c->>'tableId')::uuid,
            COALESCE((a.c->>'handNumber')::bigint, 0),
            COALESCE((a.c->>'rake')::numeric, 0),
            COALESCE((a.c->>'bbj')::numeric, 0),
            CASE WHEN v_pending IS NULL THEN 'already_queued' ELSE 'requeued' END)
    ON CONFLICT (alert_id) DO NOTHING;

    UPDATE public.financial_alerts
       SET resolved = true, resolved_at = now() WHERE id = a.alert_id;

    IF v_pending IS NULL THEN
      v_skipped := v_skipped + 1;
    ELSE
      v_requeued := v_requeued + 1;
      v_rake := v_rake + COALESCE((a.c->>'rake')::numeric, 0);
      v_bbj  := v_bbj  + COALESCE((a.c->>'bbj')::numeric, 0);
    END IF;
  END LOOP;

  SELECT count(*) INTO v_open_after FROM public.financial_alerts
   WHERE source = 'FeeReconciler.queue_failed' AND resolved IS NOT TRUE;

  RETURN jsonb_build_object('ok', true, 'applied', p_apply,
    'requeued', v_requeued, 'rake_requeued', round(v_rake, 2),
    'bbj_requeued', round(v_bbj, 2),
    'already_accounted', v_already, 'already_queued', v_skipped,
    'alerts_open_before', v_open_before, 'alerts_open_after', v_open_after);
END;
$$;


ALTER FUNCTION public.fn_requeue_unbanked_fees(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: fn_require_active_home_group(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_require_active_home_group() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text := current_user;
  v_group_id uuid;
  v_active boolean;
BEGIN
  -- Service-role / postgres bypass (cancel flows, admin tools, cron)
  IF v_role IN ('postgres','supabase_admin','service_role',
                'supabase_auth_admin','supabase_storage_admin') THEN
    RETURN NEW;
  END IF;

  -- Nested-trigger bypass (shouldn't hit on INSERT but keep safe)
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  -- Resolve target group_id based on table
  CASE TG_TABLE_NAME
    WHEN 'commander_home_posts',
         'commander_home_games',
         'commander_home_polls' THEN
      v_group_id := NEW.group_id;

    WHEN 'commander_home_post_comments',
         'commander_home_post_likes' THEN
      SELECT p.group_id INTO v_group_id
        FROM public.commander_home_posts p WHERE p.id = NEW.post_id;

    WHEN 'commander_home_rsvps',
         'commander_home_game_photos',
         'commander_home_game_reviews' THEN
      SELECT g.group_id INTO v_group_id
        FROM public.commander_home_games g WHERE g.id = NEW.game_id;

    WHEN 'commander_home_poll_votes' THEN
      SELECT pl.group_id INTO v_group_id
        FROM public.commander_home_polls pl WHERE pl.id = NEW.poll_id;

    WHEN 'commander_home_seat_reservations' THEN
      SELECT g.group_id INTO v_group_id
        FROM public.commander_home_game_tables t
        JOIN public.commander_home_games g ON g.id = t.game_id
       WHERE t.id = NEW.table_id;

    ELSE
      RETURN NEW;
  END CASE;

  IF v_group_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT is_active INTO v_active
    FROM public.commander_home_groups
   WHERE id = v_group_id;

  IF v_active IS FALSE THEN
    RAISE EXCEPTION 'GROUP_INACTIVE'
      USING HINT = 'group is deactivated - no new activity is permitted. '
                || 'Owner must reactivate the group first.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_require_active_home_group() OWNER TO postgres;

--
-- Name: FUNCTION fn_require_active_home_group(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_require_active_home_group() IS 'Pass 40: Blocks INSERT on any user-activity table whose owning group has is_active=false. Applied to posts, games, polls, comments, likes, rsvps, poll_votes, game_photos, game_reviews, seat_reservations. Service-role / postgres bypass preserved for legit RPC paths. Members table intentionally excluded (leave must always work).';


--
-- Name: fn_require_age_verified(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_require_age_verified(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_age_verified BOOLEAN;
BEGIN
  SELECT age_verified INTO v_age_verified FROM public.profiles WHERE id = p_user_id;
  IF v_age_verified IS NULL THEN
    RAISE EXCEPTION 'profile not found for user %', p_user_id USING ERRCODE = 'no_data_found';
  END IF;
  IF NOT v_age_verified THEN
    RAISE EXCEPTION 'Age verification required' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN true;
END;
$$;


ALTER FUNCTION public.fn_require_age_verified(p_user_id uuid) OWNER TO postgres;

