--
-- Name: fn_required_columns_manifest(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_required_columns_manifest() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'information_schema', 'pg_temp'
    AS $$
  SELECT COALESCE(jsonb_object_agg(t.table_name, t.required), '{}'::jsonb)
  FROM (
    SELECT c.table_name,
           jsonb_agg(c.column_name::text ORDER BY c.ordinal_position) AS required
      FROM information_schema.columns c
      JOIN information_schema.tables tt
        ON tt.table_schema = c.table_schema
       AND tt.table_name = c.table_name
       AND tt.table_type = 'BASE TABLE'
     WHERE c.table_schema = 'public'
       AND c.is_nullable = 'NO'
       AND c.column_default IS NULL
       AND c.is_identity = 'NO'
       AND c.is_generated = 'NEVER'
     GROUP BY c.table_name
  ) t;
$$;


ALTER FUNCTION public.fn_required_columns_manifest() OWNER TO postgres;

--
-- Name: FUNCTION fn_required_columns_manifest(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_required_columns_manifest() IS 'Every public base table mapped to the columns an INSERT must supply: NOT NULL, no default, not identity, not generated. Read by scripts/ci/gen-schema-manifest.mjs for the required-column write gate. service_role only.';


--
-- Name: fn_reset_broken_streak_multipliers(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reset_broken_streak_multipliers() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_yesterday DATE := ((now() AT TIME ZONE 'America/Chicago') - INTERVAL '1 day')::DATE;
    v_count     INTEGER;
BEGIN
    WITH stale_users AS (
        SELECT p.id
        FROM public.profiles p
        WHERE COALESCE(p.diamond_multiplier, 1.00) > 1.00
          AND NOT EXISTS (
              SELECT 1 FROM public.share_events se
              WHERE se.user_id = p.id
                AND (se.created_at AT TIME ZONE 'America/Chicago')::DATE >= v_yesterday
          )
    )
    UPDATE public.profiles
    SET diamond_multiplier = 1.00,
        updated_at = now()
    WHERE id IN (SELECT id FROM stale_users);

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION public.fn_reset_broken_streak_multipliers() OWNER TO postgres;

--
-- Name: fn_resolve_ads(text, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_ads(p_slot text, p_club_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 3) RETURNS TABLE(ad_id uuid, ad_key text, category text, headline text, body text, glyph text, target_url text, cta_label text, image_url text, placement_id uuid, advertiser_kind text, advertiser_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_vip  boolean := false;
BEGIN
  IF v_user IS NOT NULL THEN
    SELECT COALESCE(p.is_vip, false) INTO v_vip FROM public.profiles p WHERE p.id = v_user;
  END IF;
  RETURN QUERY
  WITH resolved AS (
    SELECT c.id, c.ad_key, c.category, c.headline, c.body, c.glyph,
           replace(
             replace(
               COALESCE(pl.target_url, c.target_url),
               '{clubId}',  COALESCE(p_club_id::text, '{clubId}')
             ),
             '{club_id}', COALESCE(p_club_id::text, '{club_id}')
           ) AS target_url,
           c.cta_label,
           COALESCE(pl.image_url, c.image_url) AS image_url,
           pl.id AS placement_id,
           COALESCE(adv.kind, 'house')         AS advertiser_kind,
           COALESCE(adv.name, 'smarter.poker') AS advertiser_name,
           c.priority,
           c.weight,
           c.created_at
      FROM public.ad_catalog c
      JOIN public.ad_placement pl ON pl.ad_id = c.id
      LEFT JOIN public.ad_advertiser adv ON adv.id = c.advertiser_id
     WHERE c.is_active
       AND pl.is_active
       AND pl.slot = p_slot
       AND (adv.id IS NULL OR adv.status = 'active')
       AND (c.starts_at IS NULL OR c.starts_at <= now())
       AND (c.ends_at   IS NULL OR c.ends_at   >  now())
       AND (pl.club_id IS NULL OR pl.club_id = p_club_id)
       AND (
             pl.audience IS NULL
          OR pl.audience = 'all'
          OR (pl.audience = 'vip'      AND v_vip)
          OR (pl.audience = 'non_vip'  AND v_user IS NOT NULL AND NOT v_vip)
          OR (pl.audience = 'new_player' AND v_user IS NOT NULL AND EXISTS (
                SELECT 1 FROM public.profiles p
                 WHERE p.id = v_user AND p.created_at > now() - interval '7 days'))
          OR (pl.audience = 'returning'  AND v_user IS NOT NULL AND EXISTS (
                SELECT 1 FROM public.profiles p
                 WHERE p.id = v_user AND p.created_at <= now() - interval '7 days'))
       )
       AND (
             pl.daily_cap IS NULL
          OR v_user IS NULL
          OR (SELECT count(*) FROM public.ad_event e
               WHERE e.user_id = v_user AND e.ad_id = c.id
                 AND e.slot = pl.slot
                 AND e.event_type = 'impression'
                 AND e.created_at > now() - interval '24 hours') < pl.daily_cap
       )
  )
  SELECT r.id, r.ad_key, r.category, r.headline, r.body, r.glyph,
         r.target_url, r.cta_label, r.image_url,
         r.placement_id, r.advertiser_kind, r.advertiser_name
    FROM resolved r
   WHERE r.target_url IS NULL OR r.target_url NOT LIKE '%{%'
   ORDER BY r.priority DESC, random() ^ (1.0 / GREATEST(r.weight, 1)) DESC
   LIMIT GREATEST(0, LEAST(p_limit, 10));
END;
$$;


ALTER FUNCTION public.fn_resolve_ads(p_slot text, p_club_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: fn_resolve_bbj_pool(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_bbj_pool(p_table_id uuid, p_club_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club uuid; v_union uuid; v_pool uuid; v_private boolean := false;
BEGIN
  SELECT t.club_id, t.union_id, COALESCE(t.is_private, false)
    INTO v_club, v_union, v_private
    FROM public.tables t WHERE t.id = p_table_id;
  v_club := COALESCE(v_club, p_club_id);

  -- UNION LAW: a private club game's BBJ never touches the union pool.
  IF v_private THEN
    v_union := NULL;
  ELSIF v_union IS NULL AND v_club IS NOT NULL THEN
    SELECT c.union_id INTO v_union FROM public.clubs c WHERE c.id = v_club;
  END IF;

  IF v_union IS NOT NULL THEN
    SELECT id INTO v_pool FROM public.bbj_pools
     WHERE club_id IS NULL AND union_id = v_union AND status = 'active';
    IF v_pool IS NULL THEN
      INSERT INTO public.bbj_pools (club_id, union_id, pool_amount, main_balance, backup_balance, promo_balance, hands_contributed, status)
      VALUES (NULL, v_union, 0, 0, 0, 0, 0, 'active')
      ON CONFLICT DO NOTHING;
      SELECT id INTO v_pool FROM public.bbj_pools
       WHERE club_id IS NULL AND union_id = v_union AND status = 'active';
    END IF;
  ELSIF v_club IS NOT NULL THEN
    SELECT id INTO v_pool FROM public.bbj_pools
     WHERE club_id = v_club AND status = 'active' ORDER BY created_at LIMIT 1;
    IF v_pool IS NULL THEN
      INSERT INTO public.bbj_pools (club_id, pool_amount, main_balance, backup_balance, promo_balance, hands_contributed, status)
      VALUES (v_club, 0, 0, 0, 0, 0, 'active')
      ON CONFLICT DO NOTHING;
      SELECT id INTO v_pool FROM public.bbj_pools
       WHERE club_id = v_club AND status = 'active' ORDER BY created_at LIMIT 1;
    END IF;
    IF v_pool IS NULL THEN
      -- Club pool exists but was retired when its balance was swept to the
      -- union. Revive it (at its current zero balance) for private-game BBJ.
      UPDATE public.bbj_pools SET status = 'active', updated_at = now()
       WHERE club_id = v_club
      RETURNING id INTO v_pool;
    END IF;
  ELSE
    RAISE EXCEPTION 'BBJ contribution with no resolvable club or union (table %)', p_table_id;
  END IF;

  RETURN v_pool;
END;
$$;


ALTER FUNCTION public.fn_resolve_bbj_pool(p_table_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_resolve_dispute(uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_dispute(p_dispute_id uuid, p_resolution text, p_adjustment_type text DEFAULT 'none'::text, p_adjustment_amount numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_d       public.disputes%ROWTYPE;
  v_amount  numeric;
  v_cap     numeric;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_resolve_dispute requires an authenticated caller'
      USING ERRCODE = '28000';
  END IF;

  IF p_adjustment_type IS NULL OR p_adjustment_type NOT IN ('none', 'credit', 'debit') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_adjustment_type');
  END IF;

  SELECT * INTO v_d FROM public.disputes WHERE id = p_dispute_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;

  IF NOT public.is_club_admin(v_d.club_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  IF v_d.status = 'resolved' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_resolved');
  END IF;

  v_amount := trunc(COALESCE(p_adjustment_amount, 0) * 100) / 100;

  IF p_adjustment_type <> 'none' AND v_amount > 0 THEN
    IF v_d.submitted_by IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'no_submitter_to_adjust');
    END IF;

    v_cap := COALESCE(v_d.amount, 0);
    IF v_cap <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'dispute_has_no_amount');
    END IF;

    IF v_amount > v_cap THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'adjustment_exceeds_disputed_amount',
        'cap', v_cap, 'requested', v_amount);
    END IF;
  END IF;

  UPDATE public.disputes
     SET status = 'resolved',
         resolution = p_resolution,
         resolved_at = now(),
         updated_at = now()
   WHERE id = p_dispute_id AND status <> 'resolved';

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_resolved');
  END IF;

  IF p_adjustment_type = 'credit' AND v_amount > 0 THEN
    IF NOT public.atomic_credit_wallet_and_log(
         v_d.submitted_by, v_amount, 'dispute_resolution',
         'Dispute ' || p_dispute_id::text || ' resolved: ' || COALESCE(p_resolution, ''),
         NULL, NULL, p_dispute_id,
         'dispute:' || p_dispute_id::text
       ) THEN
      RAISE EXCEPTION 'fn_resolve_dispute: credit failed for %', p_dispute_id
        USING ERRCODE = '25000';
    END IF;

  ELSIF p_adjustment_type = 'debit' AND v_amount > 0 THEN
    IF NOT public.atomic_deduct_wallet_and_log(
         v_d.submitted_by, v_amount, 'dispute_resolution',
         'Dispute ' || p_dispute_id::text || ' resolved: ' || COALESCE(p_resolution, ''),
         NULL, NULL, p_dispute_id
       ) THEN
      RAISE EXCEPTION 'fn_resolve_dispute: debit failed for % (insufficient balance?)',
        p_dispute_id
        USING ERRCODE = '25000';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'adjustment_type', p_adjustment_type, 'amount', v_amount);
END;
$$;


ALTER FUNCTION public.fn_resolve_dispute(p_dispute_id uuid, p_resolution text, p_adjustment_type text, p_adjustment_amount numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_resolve_dispute(p_dispute_id uuid, p_resolution text, p_adjustment_type text, p_adjustment_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_resolve_dispute(p_dispute_id uuid, p_resolution text, p_adjustment_type text, p_adjustment_amount numeric) IS 'AUDIT M17: club-admin dispute resolution. The one function in the set with a caller-supplied amount - made safe by club-admin authority plus a hard cap at the disputed amount. Do not remove the cap.';


--
-- Name: fn_resolve_expired_friend_challenges(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_expired_friend_challenges() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  WITH resolved AS (
    UPDATE friend_challenges fc
       SET status = 'completed',
           resolved_at = now(),
           winner_id = CASE
             WHEN COALESCE(fc.challenger_progress,0) > COALESCE(fc.challengee_progress,0) THEN fc.challenger_id
             WHEN COALESCE(fc.challengee_progress,0) > COALESCE(fc.challenger_progress,0) THEN fc.challengee_id
             ELSE NULL END
     WHERE fc.status = 'active' AND fc.expires_at <= now()
     RETURNING 1)
  SELECT count(*) INTO v_count FROM resolved;
  RETURN jsonb_build_object('success', true, 'resolved', v_count);
END; $$;


ALTER FUNCTION public.fn_resolve_expired_friend_challenges() OWNER TO postgres;

--
-- Name: fn_resolve_player_club_for_agent(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_player_club_for_agent(p_user_id uuid, p_club_hint uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_union uuid; v_club uuid;
BEGIN
  -- 1. The club stamped on the player's live seat is the truth: it is the club
  --    whose chips they are playing with.
  IF p_table_id IS NOT NULL THEN
    SELECT ts.club_id INTO v_club
      FROM table_seats ts
     WHERE ts.table_id = p_table_id AND ts.user_id = p_user_id AND ts.left_at IS NULL
       AND ts.club_id IS NOT NULL
     LIMIT 1;
    IF v_club IS NOT NULL THEN RETURN v_club; END IF;
  END IF;

  -- 2. The hint is usable only if it is a real member club for this player
  --    with an agent relationship (the union house club never is).
  IF p_club_hint IS NOT NULL AND EXISTS (
       SELECT 1 FROM club_members m
        WHERE m.user_id = p_user_id AND m.club_id = p_club_hint
          AND m.agent_id IS NOT NULL) THEN
    RETURN p_club_hint;
  END IF;

  -- 3. Otherwise fall back to a member club inside the same union that DOES
  --    carry an agent link.
  IF p_club_hint IS NOT NULL THEN
    SELECT COALESCE(uc.union_id, c.union_id) INTO v_union
      FROM clubs c LEFT JOIN union_clubs uc ON uc.club_id = c.id
     WHERE c.id = p_club_hint LIMIT 1;
  END IF;

  IF v_union IS NOT NULL THEN
    SELECT m.club_id INTO v_club
      FROM club_members m
      JOIN union_clubs uc2 ON uc2.club_id = m.club_id AND uc2.union_id = v_union
     WHERE m.user_id = p_user_id AND m.agent_id IS NOT NULL
     ORDER BY m.joined_at ASC NULLS LAST, m.club_id
     LIMIT 1;
    IF v_club IS NOT NULL THEN RETURN v_club; END IF;
  END IF;

  RETURN p_club_hint;
END $$;


ALTER FUNCTION public.fn_resolve_player_club_for_agent(p_user_id uuid, p_club_hint uuid, p_table_id uuid) OWNER TO postgres;

--
-- Name: fn_resolve_satellite_settlement_outcome(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_satellite_settlement_outcome(p_tournament_id uuid, p_observed_winner_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
DECLARE
  v_t record;
  v_h public.tournament_satellite_settlements%ROWTYPE;
  v_receipt jsonb;
  v_observed_target_id uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  IF p_tournament_id IS NULL OR p_observed_winner_id IS NULL THEN
    RAISE EXCEPTION 'satellite outcome requires tournament and observed winner ids'
      USING ERRCODE = '22004';
  END IF;

  SELECT COALESCE(t.satellite_target_id,t.satellite_target)
    INTO v_observed_target_id
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist',p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  IF v_observed_target_id IS NULL
     OR v_observed_target_id = p_tournament_id THEN
    RAISE EXCEPTION 'satellite % has no distinct target',p_tournament_id
      USING ERRCODE = '23514';
  END IF;

  -- The rolling legacy seat door locks target then source. Use that same
  -- order until stage two removes it, and revalidate the relationship after
  -- both rows are locked. The global lock serializes every new authority;
  -- this order also prevents an old target-first caller from forming a cycle.
  PERFORM 1 FROM public.tournaments t
   WHERE t.id IN (p_tournament_id,v_observed_target_id)
   ORDER BY CASE WHEN t.id = v_observed_target_id THEN 0 ELSE 1 END,t.id
   FOR UPDATE;
  SELECT t.* INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF NOT FOUND
     OR COALESCE(v_t.satellite_target_id,v_t.satellite_target)
          IS DISTINCT FROM v_observed_target_id THEN
    RAISE EXCEPTION 'satellite % target changed while outcome acquired locks',
      p_tournament_id USING ERRCODE = '40001';
  END IF;
  IF lower(COALESCE(v_t.variant::text,'')) <> 'satellite'
     AND upper(COALESCE(v_t.tournament_type::text,'')) <> 'SATELLITE'
     AND v_t.satellite_target_id IS NULL
     AND v_t.satellite_target IS NULL THEN
    RAISE EXCEPTION 'tournament % is not a satellite',p_tournament_id
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_h FROM public.tournament_satellite_settlements h
   WHERE h.tournament_id = p_tournament_id;
  IF FOUND THEN
    IF v_h.winner_id IS DISTINCT FROM p_observed_winner_id THEN
      RAISE EXCEPTION
        'satellite outcome winner disagrees with stored receipt for %',
        p_tournament_id USING ERRCODE = '40001';
    END IF;
    v_receipt := public.fn_ca_satellite_settlement_receipt(
      p_tournament_id,p_observed_winner_id);
    RETURN jsonb_build_object(
      'ok',true,
      'satellite_committed',true,
      'definitively_not_committed',false,
      'status','COMPLETED',
      'tournament_id',p_tournament_id,
      'winner_id',p_observed_winner_id,
      'receipt',v_receipt);
  END IF;

  IF upper(COALESCE(v_t.status::text,'')) = 'COMPLETED' THEN
    RAISE EXCEPTION 'completed satellite % has no atomic settlement receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF upper(COALESCE(v_t.status::text,'')) NOT IN ('RUNNING','COMPLETING') THEN
    RAISE EXCEPTION 'satellite % has non-terminal-outcome status %',
      p_tournament_id,v_t.status USING ERRCODE = '55000';
  END IF;
  RETURN jsonb_build_object(
    'ok',true,
    'satellite_committed',false,
    'definitively_not_committed',true,
    'status',upper(v_t.status::text),
    'tournament_id',p_tournament_id,
    'winner_id',p_observed_winner_id,
    'receipt','null'::jsonb);
END;
$$;


ALTER FUNCTION public.fn_resolve_satellite_settlement_outcome(p_tournament_id uuid, p_observed_winner_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_resolve_satellite_settlement_outcome(p_tournament_id uuid, p_observed_winner_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_resolve_satellite_settlement_outcome(p_tournament_id uuid, p_observed_winner_id uuid) IS 'Service-only serialized transport-outcome resolver. It waits behind the global terminal lock and returns either the verified committed satellite receipt or definitive no-receipt RUNNING/COMPLETING state.';


--
-- Name: fn_resolve_settled_financial_alerts(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_settled_financial_alerts(p_apply boolean DEFAULT false, p_limit integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_paid      integer := 0;
  v_overpaid  integer := 0;
  v_paid_ids  uuid[] := '{}';
  v_over_ids  uuid[] := '{}';
BEGIN
  -- ── CLASS 1: the player was accused of being unpaid and has since been paid.
  -- Proven per alert against wallet_transactions, not assumed from elapsed
  -- time. `short` is what the check said they were owed; `got` is what the
  -- prize path actually credited them for that same event.
  SELECT array_agg(id) INTO v_paid_ids FROM (
    SELECT a.id
      FROM public.financial_alerts a
     WHERE a.resolved IS NOT TRUE
       AND a.source = 'fn_payout_guarantee_check'
       AND a.context->>'kind' = 'earner_not_paid'
       AND a.context->>'user_id' IS NOT NULL
       AND a.context->>'tournament_id' IS NOT NULL
       AND COALESCE((
             SELECT sum(w.amount) FROM public.wallet_transactions w
              WHERE w.related_entity_id = (a.context->>'tournament_id')::uuid
                AND w.user_id           = (a.context->>'user_id')::uuid
                AND w.type = 'credit' AND w.category = 'prize'
           ), 0) >= COALESCE((a.context->>'short')::numeric, 0) - 0.01
     LIMIT p_limit
  ) s;
  v_paid := COALESCE(array_length(v_paid_ids, 1), 0);

  -- ── CLASS 2: every issue on the alert is an overpay, which 10.6 rule 3 says
  -- is absorbed and never clawed back. There is no action left to take, so
  -- "unresolved" is a false state. An alert carrying ANY other issue kind is
  -- deliberately left open.
  SELECT array_agg(id) INTO v_over_ids FROM (
    SELECT a.id
      FROM public.financial_alerts a
     WHERE a.resolved IS NOT TRUE
       AND a.source = 'fn_tournament_payout_reconcile'
       AND jsonb_typeof(a.context->'issues') = 'array'
       AND jsonb_array_length(a.context->'issues') > 0
       AND NOT EXISTS (
             SELECT 1 FROM jsonb_array_elements(a.context->'issues') i
              WHERE i->>'issue' IS DISTINCT FROM 'overpaid')
     LIMIT p_limit
  ) s;
  v_overpaid := COALESCE(array_length(v_over_ids, 1), 0);

  IF p_apply THEN
    UPDATE public.financial_alerts a
       SET resolved = true,
           resolved_at = now(),
           context = COALESCE(a.context, '{}'::jsonb) || jsonb_build_object(
             'resolution', 'settled after the alert was raised; the prize path credited this player for this event',
             'resolved_by_fn', 'fn_resolve_settled_financial_alerts',
             'resolved_on', now(),
             'credited', COALESCE((
               SELECT round(sum(w.amount), 2) FROM public.wallet_transactions w
                WHERE w.related_entity_id = (a.context->>'tournament_id')::uuid
                  AND w.user_id           = (a.context->>'user_id')::uuid
                  AND w.type = 'credit' AND w.category = 'prize'), 0))
     WHERE a.id = ANY(v_paid_ids);

    UPDATE public.financial_alerts a
       SET resolved = true,
           resolved_at = now(),
           context = COALESCE(a.context, '{}'::jsonb) || jsonb_build_object(
             'resolution', 'overpay only; absorbed by the house per CLAUDE.md 10.6 rule 3, never clawed back',
             'resolved_by_fn', 'fn_resolve_settled_financial_alerts',
             'resolved_on', now())
     WHERE a.id = ANY(v_over_ids);
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'applied', p_apply,
    'settled_after_alert', v_paid,
    'overpay_absorbed', v_overpaid,
    'total', v_paid + v_overpaid,
    'still_unresolved', (SELECT count(*) FROM public.financial_alerts WHERE resolved IS NOT TRUE)
  );
END;
$$;


ALTER FUNCTION public.fn_resolve_settled_financial_alerts(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_resolve_settled_financial_alerts(p_apply boolean, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_resolve_settled_financial_alerts(p_apply boolean, p_limit integer) IS 'Closes financial_alerts whose condition is provably no longer true: an accused-unpaid player the prize path has since credited, and reconciler alerts carrying only overpay (10.6 rule 3, never clawed back). Never resolves on age or guess. Added 2026-09-02 after 64 stale alerts nearly caused an 836.79 chip double-pay.';


--
-- Name: fn_resolve_settled_prize_alerts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_settled_prize_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_closed integer := 0;
BEGIN
  WITH provable AS (
    SELECT a.id,
           tp.amount   AS paid_amount,
           tp.paid_at,
           tp.idempotency_key
    FROM public.financial_alerts a
    JOIN public.tournament_payouts tp
      ON tp.tournament_id = (a.context->>'tournament_id')::uuid
     AND tp.user_id       = (a.context->>'user_id')::uuid
    WHERE NOT a.resolved
      AND a.source = 'Tournament.winner_prize_credit_failed'
      AND a.context ? 'tournament_id'
      AND a.context ? 'user_id'
      AND a.context ? 'prize'
      AND tp.paid_at IS NOT NULL
      AND tp.amount = (a.context->>'prize')::numeric
  )
  UPDATE public.financial_alerts a
     SET resolved    = true,
         resolved_at = now(),
         resolution  = format(
           'auto-resolved 2026-09-04: the reconciler paid this. tournament_payouts records %s chips paid at %s under idempotency key %s. The alert was raised by the engine when its direct credit hit the statement timeout, BEFORE the reconciler ran; the assertion that the player was never paid was false when it was written.',
           p.paid_amount, p.paid_at, p.idempotency_key)
    FROM provable p
   WHERE a.id = p.id;

  GET DIAGNOSTICS v_closed = ROW_COUNT;
  RETURN v_closed;
END;
$$;


ALTER FUNCTION public.fn_resolve_settled_prize_alerts() OWNER TO postgres;

--
-- Name: FUNCTION fn_resolve_settled_prize_alerts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_resolve_settled_prize_alerts() IS 'Closes Tournament.winner_prize_credit_failed alerts whose money provably landed - a tournament_payouts row for the same tournament and user, paid_at set, amount equal to the prize the alert named. Nothing else is auto-resolved. Measured 2026-09-04, the reconciler had already paid all five open instances, three of them within 9 seconds.';


--
-- Name: fn_resolve_tournament_blinds(text, integer, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_tournament_blinds(p_blind_structure text, p_current_level integer, p_variant text, p_tournament_type text, p_total_chips numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_levels jsonb;
  v_len integer;
  v_index integer;
  v_level jsonb;
  v_last_index integer;
  v_last jsonb;
  v_is_spin boolean;
  v_tail_count integer;
  v_tail_first numeric;
  v_tail_last numeric;
  v_ratio numeric := 1.4;
  v_factor numeric;
  v_sb numeric;
  v_bb numeric;
  v_ante numeric;
  v_max_bb numeric;
  v_scale numeric;
  v_capped boolean := false;
BEGIN
  v_levels := public.fn_safe_jsonb_array(p_blind_structure);
  v_len := jsonb_array_length(v_levels);
  IF v_len=0 THEN
    RAISE EXCEPTION 'Tournament blind structure is missing' USING ERRCODE='55000';
  END IF;
  v_index := GREATEST(COALESCE(p_current_level,0),0);

  -- A persisted level is authoritative and is never chip-capped in the engine.
  IF v_index<v_len THEN
    v_level := v_levels->v_index;
    v_sb := COALESCE(
      CASE WHEN COALESCE(v_level->>'smallBlind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'smallBlind')::numeric END,
      CASE WHEN COALESCE(v_level->>'small_blind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'small_blind')::numeric END
    );
    v_bb := COALESCE(
      CASE WHEN COALESCE(v_level->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'bigBlind')::numeric END,
      CASE WHEN COALESCE(v_level->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'big_blind')::numeric END
    );
    v_ante := COALESCE(
      CASE WHEN COALESCE(v_level->>'ante','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'ante')::numeric END,
      0
    );
    RETURN jsonb_build_object(
      'small_blind',v_sb,'big_blind',v_bb,'ante',v_ante,
      'level_index',v_index,'source','persisted','blind_capped',false
    );
  END IF;

  v_is_spin := lower(COALESCE(p_variant,''))='spin'
            OR upper(COALESCE(p_tournament_type,''))='SPIN';
  IF v_is_spin THEN
    -- spinBlindsForLevel(index+1), including canonical values when a legacy
    -- persisted array is shorter than today's ten-row Spin ladder.
    v_bb := CASE v_index
      WHEN 0 THEN 20 WHEN 1 THEN 30 WHEN 2 THEN 40 WHEN 3 THEN 60
      WHEN 4 THEN 80 WHEN 5 THEN 100 WHEN 6 THEN 120 WHEN 7 THEN 150
      WHEN 8 THEN 180 WHEN 9 THEN 210
      ELSE round((210::numeric*power(1.4::numeric,v_index-9))/10)*10
    END;
    v_sb := round(v_bb/2);
    RETURN jsonb_build_object(
      'small_blind',v_sb,'big_blind',v_bb,'ante',0,
      'level_index',v_index,'source','spin_overflow','blind_capped',false
    );
  END IF;

  -- Ignore trailing break rows when choosing the overflow anchor.
  v_last_index := v_len-1;
  WHILE v_last_index>0
    AND lower(COALESCE(v_levels->v_last_index->>'isBreak','false'))='true'
  LOOP
    v_last_index := v_last_index-1;
  END LOOP;
  v_last := v_levels->v_last_index;

  -- Geometric mean of the last five positive advertised big-blind steps.
  WITH clean AS (
    SELECT e.ordinality::integer AS ord,
           COALESCE(
             CASE WHEN COALESCE(e.value->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
                  THEN (e.value->>'bigBlind')::numeric END,
             CASE WHEN COALESCE(e.value->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
                  THEN (e.value->>'big_blind')::numeric END
           ) AS bb
      FROM jsonb_array_elements(v_levels) WITH ORDINALITY AS e(value,ordinality)
  ), tail AS (
    SELECT ord,bb FROM clean WHERE bb>0 ORDER BY ord DESC LIMIT 5
  )
  SELECT count(*)::integer,
         (array_agg(bb ORDER BY ord))[1],
         (array_agg(bb ORDER BY ord DESC))[1]
    INTO v_tail_count,v_tail_first,v_tail_last
    FROM tail;
  IF v_tail_count>=2 AND v_tail_first>0 AND v_tail_last>v_tail_first THEN
    v_ratio := power(v_tail_last/v_tail_first,1::numeric/(v_tail_count-1));
    IF v_ratio<=1 THEN v_ratio := 1.4; END IF;
  END IF;
  v_ratio := LEAST(1.6,GREATEST(1.15,v_ratio));
  v_factor := power(
    v_ratio,
    LEAST(GREATEST(1,v_index-v_len+1),40)
  );

  v_sb := LEAST(COALESCE(
    CASE WHEN COALESCE(v_last->>'smallBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'smallBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'small_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'small_blind')::numeric END,
    0
  )*v_factor,10000000);
  v_bb := LEAST(COALESCE(
    CASE WHEN COALESCE(v_last->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'bigBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'big_blind')::numeric END,
    0
  )*v_factor,10000000);
  v_ante := LEAST(COALESCE(
    CASE WHEN COALESCE(v_last->>'ante','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'ante')::numeric END,
    0
  )*v_factor,10000000);

  -- Match capLevelToTournamentChips for generic overflow. The database wrapper
  -- supplies the exact durable chip issuance total; NULL means cap nothing.
  IF p_total_chips>0 THEN
    v_max_bb := p_total_chips/20;
    IF v_bb>v_max_bb AND v_max_bb>=2 THEN
      v_scale := v_max_bb/v_bb;
      v_bb := GREATEST(2,floor(v_bb*v_scale));
      v_sb := GREATEST(1,floor(v_sb*v_scale));
      v_ante := CASE WHEN v_ante>0 THEN GREATEST(1,floor(v_ante*v_scale)) ELSE 0 END;
      v_capped := true;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'small_blind',v_sb,'big_blind',v_bb,'ante',v_ante,
    'level_index',v_index,'source','mtt_overflow',
    'overflow_ratio',v_ratio,'blind_capped',v_capped
  );
END;
$_$;


ALTER FUNCTION public.fn_resolve_tournament_blinds(p_blind_structure text, p_current_level integer, p_variant text, p_tournament_type text, p_total_chips numeric) OWNER TO postgres;

--
-- Name: fn_resolve_tournament_terminal_outcome(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_tournament_terminal_outcome(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
DECLARE
  v_mode text := lower(btrim(COALESCE(p_settlement_mode,'')));
  v_t record;
  v_h public.tournament_terminal_settlements%ROWTYPE;
  v_receipt jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'terminal outcome requires a tournament id'
      USING ERRCODE = '22004';
  END IF;
  IF v_mode NOT IN ('places','final_table_deal') THEN
    RAISE EXCEPTION 'unknown terminal outcome mode %',p_settlement_mode
      USING ERRCODE = '22023';
  END IF;
  SELECT t.* INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist',p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  IF lower(COALESCE(v_t.variant::text,'')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type::text,'')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL
     OR v_t.satellite_target IS NOT NULL THEN
    RAISE EXCEPTION 'tournament % is a satellite',p_tournament_id
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_h FROM public.tournament_terminal_settlements h
   WHERE h.tournament_id = p_tournament_id;
  IF FOUND THEN
    IF v_h.settlement_mode IS DISTINCT FROM v_mode
       OR (p_observed_winner_id IS NOT NULL
           AND v_h.winner_id IS DISTINCT FROM p_observed_winner_id) THEN
      RAISE EXCEPTION 'terminal outcome parameters disagree with stored receipt for %',
        p_tournament_id USING ERRCODE = '40001';
    END IF;
    v_receipt := public.fn_ca_tournament_terminal_receipt(
      p_tournament_id,p_observed_winner_id);
    RETURN jsonb_build_object(
      'ok',true,
      'terminal_committed',true,
      'definitively_not_committed',false,
      'status','COMPLETED',
      'mode',v_mode,
      'tournament_id',p_tournament_id,
      'receipt',v_receipt);
  END IF;

  IF upper(COALESCE(v_t.status::text,'')) = 'COMPLETED' THEN
    RAISE EXCEPTION 'completed tournament % has no atomic terminal receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF upper(COALESCE(v_t.status::text,'')) NOT IN ('RUNNING','COMPLETING') THEN
    RAISE EXCEPTION 'tournament % has non-terminal-outcome status %',
      p_tournament_id,v_t.status USING ERRCODE = '55000';
  END IF;
  RETURN jsonb_build_object(
    'ok',true,
    'terminal_committed',false,
    'definitively_not_committed',true,
    'status',upper(v_t.status::text),
    'mode',v_mode,
    'tournament_id',p_tournament_id,
    'receipt','null'::jsonb);
END;
$$;


ALTER FUNCTION public.fn_resolve_tournament_terminal_outcome(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text) OWNER TO postgres;

--
-- Name: FUNCTION fn_resolve_tournament_terminal_outcome(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_resolve_tournament_terminal_outcome(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text) IS 'Service-only serialized transport-outcome resolver. It waits behind the global terminal transaction lock and returns either the verified committed receipt or definitive no-receipt RUNNING/COMPLETING state.';


--
-- Name: fn_respond_chip_request(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_respond_chip_request(p_request_id uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
  v_req record;
  v_role text;
  v_send jsonb;
  v_op_id uuid;
  v_prior record;
begin
  if v_me is null then return jsonb_build_object('success', false, 'error', 'not authenticated'); end if;
  if p_action not in ('approve','decline','cancel') then
    return jsonb_build_object('success', false, 'error', 'invalid action');
  end if;

  select * into v_req from chip_requests where id = p_request_id for update;
  if not found then return jsonb_build_object('success', false, 'error', 'request not found'); end if;

  -- THE SAME KEY ON EVERY ATTEMPT. Derived from the request, so a retry after
  -- a lost response replays the original send instead of making a new one.
  v_op_id := md5('chip_request_approve:' || p_request_id::text)::uuid;

  if v_req.status <> 'pending' then
    -- A RETRY AFTER A LOST RESPONSE IS NOT A FAILURE. If this caller already
    -- answered this request, say what happened rather than reporting an error
    -- for work that succeeded.
    if v_req.responded_by = v_me then
      if v_req.status = 'approved' then
        -- Only claim a replay against a transaction actually written under
        -- this key. Approvals made before this migration used a random key,
        -- so nothing is found and the honest refusal below stands - re-sending
        -- them is the one outcome that would move money twice.
        select ct.id, ct.amount into v_prior
          from chip_transactions ct
         where ct.club_id = v_req.club_id
           and ct.from_user_id = v_me
           and ct.metadata ->> 'op_id' = v_op_id::text
         limit 1;
        if found then
          return jsonb_build_object('success', true, 'status', 'approved',
                                    'replayed', true, 'transaction_id', v_prior.id,
                                    'amount', v_prior.amount);
        end if;
      else
        return jsonb_build_object('success', true, 'status', v_req.status,
                                  'replayed', true);
      end if;
    end if;
    return jsonb_build_object('success', false, 'error', 'request already ' || v_req.status);
  end if;

  if p_action = 'cancel' then
    if v_req.requester_id <> v_me then
      return jsonb_build_object('success', false, 'error', 'only the requester may cancel');
    end if;
    update chip_requests set status = 'cancelled', responded_by = v_me, responded_at = now()
     where id = p_request_id;
    return jsonb_build_object('success', true, 'status', 'cancelled');
  end if;

  v_role := public.fn_club_bank_role(v_req.club_id);
  if v_role is null or v_role not in ('owner','co_owner','admin','super_agent','agent','sub_agent') then
    return jsonb_build_object('success', false, 'error', 'you cannot answer chip requests here');
  end if;
  if v_role in ('super_agent','agent','sub_agent') and v_req.approver_id is distinct from v_me then
    return jsonb_build_object('success', false, 'error', 'this request is not addressed to you');
  end if;

  if p_action = 'decline' then
    update chip_requests set status = 'declined', responded_by = v_me, responded_at = now()
     where id = p_request_id;
    return jsonb_build_object('success', true, 'status', 'declined');
  end if;

  if v_me = v_req.requester_id then
    return jsonb_build_object('success', false, 'error', 'you cannot approve your own request');
  end if;

  -- Said before the send, so the operator is told WHY rather than reading a
  -- raw trigger message. The guard on chip_transactions is what actually
  -- enforces it; this is the sentence that reaches the screen.
  if public.fn_club_settlement_frozen(v_req.club_id) then
    return jsonb_build_object('success', false,
      'error', 'this club is squaring its books - approvals resume when the settlement freeze lifts');
  end if;

  v_send := public.fn_agent_wallet_send(
    v_req.club_id, v_req.requester_id, v_req.amount,
    'player_wallet', 'Chip Request Approved', v_op_id);
  if not coalesce((v_send ->> 'success')::boolean, false) then
    return jsonb_build_object('success', false,
      'error', coalesce(v_send ->> 'error', 'the send was refused'));
  end if;

  update chip_requests set status = 'approved', responded_by = v_me, responded_at = now()
   where id = p_request_id;

  return jsonb_build_object('success', true, 'status', 'approved',
                            'replayed', coalesce((v_send ->> 'replayed')::boolean, false),
                            'your_balance', (v_send ->> 'agent_wallet_after')::numeric,
                            'their_balance', (v_send ->> 'recipient_balance_after')::numeric);
end $$;


ALTER FUNCTION public.fn_respond_chip_request(p_request_id uuid, p_action text) OWNER TO postgres;

--
-- Name: fn_respond_friend_challenge(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_respond_friend_challenge(p_challenge_id uuid, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row friend_challenges;
BEGIN
  SELECT * INTO v_row FROM friend_challenges WHERE id = p_challenge_id FOR UPDATE;
  IF v_row.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  IF v_row.challengee_id <> auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;
  IF v_row.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_responded');
  END IF;
  UPDATE friend_challenges
     SET status = CASE WHEN p_accept THEN 'active' ELSE 'declined' END
   WHERE id = p_challenge_id;
  RETURN jsonb_build_object('success', true, 'status', CASE WHEN p_accept THEN 'active' ELSE 'declined' END);
END; $$;


ALTER FUNCTION public.fn_respond_friend_challenge(p_challenge_id uuid, p_accept boolean) OWNER TO postgres;

--
-- Name: fn_retire_manager_wakes_after_terminal_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_retire_manager_wakes_after_terminal_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF upper(COALESCE(NEW.status,'')) IN ('COMPLETED','CANCELLED','CANCELED')
     AND NEW.status IS DISTINCT FROM OLD.status THEN
    UPDATE public.tournament_manager_wakes
       SET consumed_at=COALESCE(consumed_at,clock_timestamp())
     WHERE tournament_id=NEW.id AND consumed_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_retire_manager_wakes_after_terminal_status() OWNER TO postgres;

--
-- Name: fn_retire_settled_club(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_retire_settled_club(p_club_id uuid, p_confirm_name text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
DECLARE
  v_me uuid := auth.uid();
  v_club public.clubs%ROWTYPE;
  v_impact jsonb;
  v_reason text;
  v_retired_at timestamptz;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication Required');
  END IF;
  IF p_club_id IS NULL OR nullif(btrim(coalesce(p_confirm_name, '')), '') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Confirm The Club Name');
  END IF;
  IF length(coalesce(p_reason, '')) > 500 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Retirement Reason Is Too Long');
  END IF;
  v_reason := coalesce(nullif(btrim(p_reason), ''), 'Owner Requested Retirement');

  PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:' || p_club_id::text, 0));
  SELECT * INTO v_club FROM public.clubs c WHERE c.id = p_club_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Club Not Found');
  END IF;
  IF v_club.owner_id IS DISTINCT FROM v_me THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only The Club Owner Can Retire This Club');
  END IF;
  IF btrim(p_confirm_name) IS DISTINCT FROM btrim(v_club.name) THEN
    RETURN jsonb_build_object('success', false, 'error', 'The Club Name Confirmation Does Not Match');
  END IF;

  -- Lost-response retry: still owner/name authorised, but no second audit/event.
  IF v_club.lifecycle_status = 'retired' THEN
    RETURN jsonb_build_object(
      'success', true, 'already_retired', true, 'club_id', p_club_id,
      'retired_at', v_club.retired_at
    );
  END IF;

  -- Canonical union resolution uses all three representations. Live estates
  -- have disagreed between the pointer and junction table before, so neither is
  -- accepted as a substitute for the others.
  PERFORM 1 FROM public.unions u WHERE u.id = p_club_id FOR UPDATE;
  PERFORM 1 FROM public.union_clubs uc
   WHERE uc.club_id = p_club_id OR uc.union_id = p_club_id
   ORDER BY uc.id FOR UPDATE;
  IF v_club.union_id IS NOT NULL
     OR coalesce((to_jsonb(v_club) ->> 'is_union')::boolean, false)
     OR EXISTS (SELECT 1 FROM public.unions u WHERE u.id = p_club_id)
     OR EXISTS (SELECT 1 FROM public.union_clubs uc
                 WHERE uc.club_id = p_club_id OR uc.union_id = p_club_id) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Leave The Union Or Retire The Union Estate Through Union Administration First'
    );
  END IF;

  -- Lock parents before their dependent rows, matching game registration/seat
  -- writer order. The club FOR UPDATE also makes a new FK child wait; after this
  -- transaction commits, the retired-row trigger refuses that waiting writer.
  PERFORM 1 FROM public.tables WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1
    FROM public.table_seats ts JOIN public.tables t ON t.id = ts.table_id
   WHERE t.club_id = p_club_id ORDER BY ts.id FOR UPDATE OF ts;
  PERFORM 1 FROM public.tournaments WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1
    FROM public.tournament_escrow te
    JOIN public.tournaments tr ON tr.id = te.tournament_id
   WHERE tr.club_id = p_club_id ORDER BY te.tournament_id FOR UPDATE OF te;
  PERFORM 1
    FROM public.tournament_players tp
    JOIN public.tournaments tr ON tr.id = tp.tournament_id
   WHERE tr.club_id = p_club_id ORDER BY tp.id FOR UPDATE OF tp;
  PERFORM 1 FROM public.club_members WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.agents WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.club_wallets WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.club_diamond_wallets WHERE club_id = p_club_id FOR UPDATE;
  PERFORM 1 FROM public.bbj_pools WHERE club_id = p_club_id FOR UPDATE;
  PERFORM 1 FROM public.spin_bonus_pools WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.club_opening_setups WHERE club_id = p_club_id FOR UPDATE;
  PERFORM 1 FROM public.promo_vault_inventory
   WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.cashout_requests WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.chip_requests WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.chip_escrow_holds WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.tournament_tickets WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.settlement_periods WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1
    FROM public.credit_invoices ci JOIN public.agents a ON a.id = ci.agent_id
   WHERE a.club_id = p_club_id ORDER BY ci.id FOR UPDATE OF ci;
  PERFORM 1
    FROM public.chip_escrow ce
    JOIN public.cashout_requests cr ON cr.id = ce.cashout_request_id
   WHERE cr.club_id = p_club_id ORDER BY ce.id FOR UPDATE OF ce;

  v_impact := public.fn_club_retirement_impact(p_club_id);
  IF coalesce((v_impact ->> 'running_tables')::bigint, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Close Every Running Table Before Retiring This Club', 'impact', v_impact);
  END IF;
  IF coalesce((v_impact ->> 'active_tournaments')::bigint, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Complete Or Cancel Every Tournament Before Retiring This Club', 'impact', v_impact);
  END IF;
  IF coalesce((v_impact ->> 'wallet_chips')::numeric, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Settle Every Club, Member, Agent, Pool, Seat, Escrow And Ticket Balance First', 'impact', v_impact);
  END IF;
  IF coalesce((v_impact ->> 'diamonds')::numeric, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Redeem Or Transfer Every Club And Member Diamond Balance First', 'impact', v_impact);
  END IF;
  IF coalesce((v_impact ->> 'inventory_items')::bigint, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Grant Or Resolve Every Promo Vault Inventory Item First', 'impact', v_impact);
  END IF;
  IF coalesce((v_impact ->> 'open_obligations')::bigint, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Resolve Every Open Game, Cashier, Credit And Settlement Obligation First', 'impact', v_impact);
  END IF;

  v_retired_at := clock_timestamp();
  PERFORM set_config('app.club_retirement_write', 'on', true);
  UPDATE public.clubs
     SET lifecycle_status = 'retired',
         retired_at = v_retired_at,
         retired_by = v_me,
         retirement_reason = v_reason,
         is_public = false,
         requires_approval = true,
         updated_at = v_retired_at
   WHERE id = p_club_id AND lifecycle_status = 'active';
  PERFORM set_config('app.club_retirement_write', '', true);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'club lifecycle changed during retirement' USING ERRCODE = '40001';
  END IF;

  INSERT INTO public.audit_trail(
    actor_id, actor_role, action, target_type, target_id, club_id,
    before_state, after_state, reason
  ) VALUES (
    v_me, 'owner', 'retire_club', 'club', p_club_id, p_club_id,
    jsonb_build_object(
      'lifecycle_status', v_club.lifecycle_status,
      'is_public', v_club.is_public,
      'requires_approval', v_club.requires_approval
    ),
    jsonb_build_object(
      'lifecycle_status', 'retired',
      'retired_at', v_retired_at,
      'records_retained', true,
      'is_public', false,
      'requires_approval', true
    ),
    v_reason
  );

  PERFORM public.fn_emit_game_management_event(
    'club_identity_changed', p_club_id, NULL, NULL, 'club', p_club_id, NULL,
    jsonb_build_object(
      'operation', 'retire', 'lifecycle_status', 'retired',
      'records_retained', true
    )
  );

  RETURN jsonb_build_object(
    'success', true, 'already_retired', false, 'club_id', p_club_id,
    'retired_at', v_retired_at, 'records_retained', true
  );
END
$$;


ALTER FUNCTION public.fn_retire_settled_club(p_club_id uuid, p_confirm_name text, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION fn_retire_settled_club(p_club_id uuid, p_confirm_name text, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_retire_settled_club(p_club_id uuid, p_confirm_name text, p_reason text) IS 'Owner-only, lock-bounded soft retirement for a fully settled standalone club. Preserves every club, membership, game, journal and audit row. Physical deletion remains exclusive to the service-role certification-fixture contract.';


--
-- Name: fn_reveal_rabbit_hunt(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reveal_rabbit_hunt(p_table_id uuid, p_hand_number bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller   uuid := (SELECT auth.uid());
  v_offer    record;
  v_played   boolean := false;
  v_is_vip   boolean := false;
  v_used     integer := 0;
  v_month    text := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM');
  v_free_cap constant integer := 100;
  v_price    integer;
  v_deduct   jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication required');
  END IF;

  SELECT * INTO v_offer FROM public.rabbit_hunt_offers
   WHERE table_id = p_table_id AND hand_number = p_hand_number;
  IF v_offer.table_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'no rabbit hunt available for that hand');
  END IF;

  -- Already revealed this exact hand: free, and no second charge.
  IF EXISTS (SELECT 1 FROM public.rabbit_hunt_reveals r
              WHERE r.user_id = v_caller AND r.table_id = p_table_id
                AND r.hand_number = p_hand_number) THEN
    RETURN jsonb_build_object('success', true, 'charged', 0, 'already_revealed', true,
                              'cards', v_offer.cards, 'board_len', v_offer.board_len);
  END IF;

  -- You may only rabbit hunt a hand you were dealt into.
  SELECT EXISTS (
    SELECT 1 FROM public.hand_history h
     WHERE h.table_id = p_table_id AND h.hand_number = p_hand_number
       AND jsonb_typeof(h.players) = 'array'
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(h.players) pl
                    WHERE pl->>'userId' = v_caller::text)
  ) INTO v_played;

  IF NOT v_played THEN
    -- Settlement may not have written hand_history yet; a live seat counts.
    SELECT EXISTS (
      SELECT 1 FROM public.table_seats s
       WHERE s.table_id = p_table_id AND s.user_id = v_caller
         AND (s.left_at IS NULL OR s.left_at > now() - interval '5 minutes')
    ) INTO v_played;
  END IF;

  IF NOT v_played THEN
    RETURN jsonb_build_object('success', false, 'error', 'you did not play that hand');
  END IF;

  -- An expired VIP is not a VIP.
  SELECT COALESCE(is_vip, false) AND (vip_expires_at IS NULL OR vip_expires_at > now())
    INTO v_is_vip FROM public.profiles WHERE id = v_caller;
  v_is_vip := COALESCE(v_is_vip, false);

  SELECT COALESCE(usage_count, 0) INTO v_used
    FROM public.vip_feature_usage_monthly
   WHERE user_id = v_caller AND feature = 'rabbit_hunt' AND month = v_month;
  v_used := COALESCE(v_used, 0);

  IF v_is_vip AND v_used < v_free_cap THEN
    PERFORM public.fn_increment_vip_usage(v_caller, 'rabbit_hunt');
    INSERT INTO public.rabbit_hunt_reveals (user_id, table_id, hand_number, charged)
    VALUES (v_caller, p_table_id, p_hand_number, 0);
    RETURN jsonb_build_object('success', true, 'charged', 0,
                              'free_remaining', v_free_cap - v_used - 1,
                              'cards', v_offer.cards, 'board_len', v_offer.board_len);
  END IF;

  SELECT diamond_cost INTO v_price FROM public.feature_pricing WHERE feature = 'rabbit_hunt';
  v_price := COALESCE(v_price, 1);

  -- Deterministic reference_id makes the charge idempotent per (hand, user).
  -- Cooldown explicitly 0: consecutive hands are legitimate, rapid hunts.
  v_deduct := public.deduct_diamonds(
    p_user_id          := v_caller,
    p_amount           := v_price,
    p_description      := 'Rabbit hunt',
    p_transaction_type := 'feature_purchase',
    p_source           := 'rabbit_hunt',
    p_metadata         := jsonb_build_object('table_id', p_table_id, 'hand_number', p_hand_number),
    p_reference_id     := 'rabbit_' || p_table_id::text || '_' || p_hand_number::text || '_' || v_caller::text,
    p_cooldown_seconds := 0
  );

  IF COALESCE((v_deduct->>'success')::boolean, false) = false THEN
    RETURN jsonb_build_object('success', false,
      'error', COALESCE(v_deduct->>'error', 'not enough diamonds'),
      'diamond_cost', v_price);
  END IF;

  PERFORM public.fn_increment_vip_usage(v_caller, 'rabbit_hunt');
  INSERT INTO public.rabbit_hunt_reveals (user_id, table_id, hand_number, charged)
  VALUES (v_caller, p_table_id, p_hand_number, v_price);

  RETURN jsonb_build_object('success', true, 'charged', v_price,
                            'cards', v_offer.cards, 'board_len', v_offer.board_len);
END
$$;


ALTER FUNCTION public.fn_reveal_rabbit_hunt(p_table_id uuid, p_hand_number bigint) OWNER TO postgres;

--
-- Name: FUNCTION fn_reveal_rabbit_hunt(p_table_id uuid, p_hand_number bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_reveal_rabbit_hunt(p_table_id uuid, p_hand_number bigint) IS 'Pays for and returns the rabbit-hunt cards for one hand. VIP: first 100 per calendar month free, then 1 diamond. Non-VIP: 1 diamond. Refuses if the caller did not play the hand. Charges at most once per (user, table, hand).';


--
-- Name: fn_review_anti_cheat_flag(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_review_anti_cheat_flag(p_club_id uuid, p_flag_id uuid, p_status text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated integer;
BEGIN
  IF NOT fn_ca_can_review_integrity(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  IF coalesce(p_status, '') NOT IN ('reviewed', 'dismissed', 'actioned') THEN
    RAISE EXCEPTION 'a flag can only be reviewed, dismissed or actioned'
      USING ERRCODE = '22023';
  END IF;

  UPDATE anti_cheat_flags f
     SET status = p_status,
         reviewed_by = auth.uid(),
         reviewed_at = now(),
         review_notes = nullif(btrim(coalesce(p_notes, '')), '')
   WHERE f.id = p_flag_id
     AND (
           f.club_id = p_club_id
           OR (f.club_id IS NULL AND EXISTS (
                 SELECT 1 FROM club_members cm
                  WHERE cm.club_id = p_club_id AND cm.user_id = f.player_id))
         );

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- Zero rows is a failure, not a quiet success. It is the exact shape the old
  -- client UPDATE hid.
  IF v_updated = 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'flag_not_in_this_club', 'updated', 0);
  END IF;

  INSERT INTO anti_cheat_events (club_id, player_id, event_type, details, triggered_by)
  SELECT p_club_id, f.player_id, 'flag_' || p_status,
         jsonb_build_object('flag_id', f.id, 'flag_type', f.flag_type,
                            'severity', f.severity, 'notes', f.review_notes),
         auth.uid()
    FROM anti_cheat_flags f
   WHERE f.id = p_flag_id;

  RETURN jsonb_build_object('ok', true, 'updated', v_updated, 'status', p_status);
END;
$$;


ALTER FUNCTION public.fn_review_anti_cheat_flag(p_club_id uuid, p_flag_id uuid, p_status text, p_notes text) OWNER TO postgres;

--
-- Name: fn_review_join_request(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_review_join_request(p_club_id uuid, p_user_id uuid, p_approve boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_found boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT is_club_admin(p_club_id, v_uid) THEN
    RAISE EXCEPTION 'Not authorized to review join requests for this club';
  END IF;

  IF p_approve THEN
    UPDATE club_members
      SET status = 'active'
      WHERE club_id = p_club_id AND user_id = p_user_id AND status = 'pending';
    GET DIAGNOSTICS v_found = ROW_COUNT;
  ELSE
    DELETE FROM club_members
      WHERE club_id = p_club_id AND user_id = p_user_id AND status = 'pending';
    GET DIAGNOSTICS v_found = ROW_COUNT;
  END IF;

  IF NOT v_found THEN
    RETURN jsonb_build_object('success', false, 'error', 'No pending request found');
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION public.fn_review_join_request(p_club_id uuid, p_user_id uuid, p_approve boolean) OWNER TO postgres;

--
-- Name: fn_rg_check_deposit(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rg_check_deposit(p_user_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limits public.responsible_gaming_limits%ROWTYPE;
  v_now TIMESTAMPTZ := now();
  v_deposited_today NUMERIC;
  v_deposited_week NUMERIC;
  v_deposited_month NUMERIC;
BEGIN
  IF p_user_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_args');
  END IF;

  SELECT * INTO v_limits FROM public.responsible_gaming_limits WHERE user_id = p_user_id;

  -- No limits → allow
  IF v_limits.user_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'no_limits_set');
  END IF;

  -- Self-exclusion
  IF v_limits.self_excluded_until IS NOT NULL AND v_limits.self_excluded_until > v_now THEN
    RETURN jsonb_build_object('ok', false, 'error', 'self_excluded',
      'self_excluded_until', v_limits.self_excluded_until);
  END IF;

  -- Cooling-off (hard block during cooldown)
  IF v_limits.cooling_off_until IS NOT NULL AND v_limits.cooling_off_until > v_now THEN
    RETURN jsonb_build_object('ok', false, 'error', 'cooling_off',
      'cooling_off_until', v_limits.cooling_off_until);
  END IF;

  -- Sum ledger deposit-category rows (category IN ('deposit','deposit_topup','diamond_purchase_bonus'))
  SELECT COALESCE(SUM(amount), 0) INTO v_deposited_today
    FROM public.chip_ledger
   WHERE to_entity_id = p_user_id AND to_type = 'player_wallet'
     AND category IN ('deposit','deposit_topup')
     AND created_at >= date_trunc('day', v_now);
  SELECT COALESCE(SUM(amount), 0) INTO v_deposited_week
    FROM public.chip_ledger
   WHERE to_entity_id = p_user_id AND to_type = 'player_wallet'
     AND category IN ('deposit','deposit_topup')
     AND created_at >= date_trunc('week', v_now);
  SELECT COALESCE(SUM(amount), 0) INTO v_deposited_month
    FROM public.chip_ledger
   WHERE to_entity_id = p_user_id AND to_type = 'player_wallet'
     AND category IN ('deposit','deposit_topup')
     AND created_at >= date_trunc('month', v_now);

  IF v_limits.daily_deposit_limit IS NOT NULL
     AND v_deposited_today + p_amount > v_limits.daily_deposit_limit THEN
    RETURN jsonb_build_object('ok', false, 'error', 'daily_deposit_limit_exceeded',
      'limit', v_limits.daily_deposit_limit, 'already', v_deposited_today, 'attempted', p_amount);
  END IF;
  IF v_limits.weekly_deposit_limit IS NOT NULL
     AND v_deposited_week + p_amount > v_limits.weekly_deposit_limit THEN
    RETURN jsonb_build_object('ok', false, 'error', 'weekly_deposit_limit_exceeded',
      'limit', v_limits.weekly_deposit_limit, 'already', v_deposited_week, 'attempted', p_amount);
  END IF;
  IF v_limits.monthly_deposit_limit IS NOT NULL
     AND v_deposited_month + p_amount > v_limits.monthly_deposit_limit THEN
    RETURN jsonb_build_object('ok', false, 'error', 'monthly_deposit_limit_exceeded',
      'limit', v_limits.monthly_deposit_limit, 'already', v_deposited_month, 'attempted', p_amount);
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION public.fn_rg_check_deposit(p_user_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: fn_rg_end_session(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rg_end_session(p_user_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows INT;
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'p_user_id required'; END IF;
  UPDATE public.responsible_gaming_sessions
     SET ended_at = now(), force_closed_reason = p_reason
   WHERE user_id = p_user_id AND ended_at IS NULL;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'closed_sessions', v_rows);
END;
$$;


ALTER FUNCTION public.fn_rg_end_session(p_user_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: fn_rg_require_not_excluded(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rg_require_not_excluded(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limits public.responsible_gaming_limits%ROWTYPE;
  v_now TIMESTAMPTZ := now();
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'p_user_id required'; END IF;

  SELECT * INTO v_limits FROM public.responsible_gaming_limits WHERE user_id = p_user_id;

  IF v_limits.user_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'no_limits_set');
  END IF;

  IF v_limits.self_excluded_until IS NOT NULL AND v_limits.self_excluded_until > v_now THEN
    RETURN jsonb_build_object('ok', false, 'error', 'self_excluded',
      'self_excluded_until', v_limits.self_excluded_until);
  END IF;
  IF v_limits.cooling_off_until IS NOT NULL AND v_limits.cooling_off_until > v_now THEN
    RETURN jsonb_build_object('ok', false, 'error', 'cooling_off',
      'cooling_off_until', v_limits.cooling_off_until);
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION public.fn_rg_require_not_excluded(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_rg_self_exclude(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rg_self_exclude(p_user_id uuid, p_duration_hours integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now TIMESTAMPTZ := now();
  v_until TIMESTAMPTZ;
  v_existing TIMESTAMPTZ;
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'p_user_id required'; END IF;

  v_until := CASE
    WHEN p_duration_hours IS NULL OR p_duration_hours <= 0 THEN 'infinity'::timestamptz
    ELSE v_now + (p_duration_hours || ' hours')::interval
  END;

  SELECT self_excluded_until INTO v_existing
    FROM public.responsible_gaming_limits WHERE user_id = p_user_id;

  IF v_existing IS NOT NULL AND v_existing > v_until THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'cannot_shorten_exclusion',
      'self_excluded_until', v_existing
    );
  END IF;

  INSERT INTO public.responsible_gaming_limits (user_id, self_excluded_until, updated_at)
  VALUES (p_user_id, v_until, v_now)
  ON CONFLICT (user_id) DO UPDATE SET
    self_excluded_until = v_until,
    updated_at = v_now;

  -- Close any open session
  UPDATE public.responsible_gaming_sessions
     SET ended_at = v_now, force_closed_reason = 'self_exclusion'
   WHERE user_id = p_user_id AND ended_at IS NULL;

  RETURN jsonb_build_object('ok', true, 'self_excluded_until', v_until);
END;
$$;


ALTER FUNCTION public.fn_rg_self_exclude(p_user_id uuid, p_duration_hours integer) OWNER TO postgres;

--
-- Name: fn_rg_set_limits(uuid, numeric, numeric, numeric, numeric, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rg_set_limits(p_user_id uuid, p_daily_deposit_limit numeric DEFAULT NULL::numeric, p_weekly_deposit_limit numeric DEFAULT NULL::numeric, p_monthly_deposit_limit numeric DEFAULT NULL::numeric, p_daily_loss_limit numeric DEFAULT NULL::numeric, p_session_time_limit_minutes integer DEFAULT NULL::integer, p_reality_check_interval_minutes integer DEFAULT NULL::integer, p_is_increase boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now TIMESTAMPTZ := now();
  v_existing public.responsible_gaming_limits%ROWTYPE;
  v_lock_hours INT := 24; -- cooling-off before the next increase takes effect
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'p_user_id required'; END IF;

  SELECT * INTO v_existing FROM public.responsible_gaming_limits WHERE user_id = p_user_id;

  -- If user is trying to INCREASE and they're still locked, reject
  IF p_is_increase AND v_existing.user_id IS NOT NULL
     AND v_now < v_existing.limit_increase_available_at THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'cooling_off',
      'increase_available_at', v_existing.limit_increase_available_at
    );
  END IF;

  INSERT INTO public.responsible_gaming_limits AS rgl (
    user_id,
    daily_deposit_limit,  weekly_deposit_limit, monthly_deposit_limit,
    daily_loss_limit,     session_time_limit_minutes,
    reality_check_interval_minutes,
    limit_increase_available_at,
    updated_at
  ) VALUES (
    p_user_id,
    p_daily_deposit_limit, p_weekly_deposit_limit, p_monthly_deposit_limit,
    p_daily_loss_limit,    p_session_time_limit_minutes,
    COALESCE(p_reality_check_interval_minutes, 30),
    CASE WHEN p_is_increase THEN v_now + (v_lock_hours || ' hours')::interval
         ELSE v_now
    END,
    v_now
  )
  ON CONFLICT (user_id) DO UPDATE SET
    daily_deposit_limit            = COALESCE(EXCLUDED.daily_deposit_limit, rgl.daily_deposit_limit),
    weekly_deposit_limit           = COALESCE(EXCLUDED.weekly_deposit_limit, rgl.weekly_deposit_limit),
    monthly_deposit_limit          = COALESCE(EXCLUDED.monthly_deposit_limit, rgl.monthly_deposit_limit),
    daily_loss_limit               = COALESCE(EXCLUDED.daily_loss_limit, rgl.daily_loss_limit),
    session_time_limit_minutes     = COALESCE(EXCLUDED.session_time_limit_minutes, rgl.session_time_limit_minutes),
    reality_check_interval_minutes = COALESCE(EXCLUDED.reality_check_interval_minutes, rgl.reality_check_interval_minutes),
    limit_increase_available_at    = CASE WHEN p_is_increase
                                          THEN v_now + (v_lock_hours || ' hours')::interval
                                          ELSE rgl.limit_increase_available_at END,
    updated_at                     = v_now;

  RETURN jsonb_build_object('ok', true, 'updated_at', v_now);
END;
$$;


ALTER FUNCTION public.fn_rg_set_limits(p_user_id uuid, p_daily_deposit_limit numeric, p_weekly_deposit_limit numeric, p_monthly_deposit_limit numeric, p_daily_loss_limit numeric, p_session_time_limit_minutes integer, p_reality_check_interval_minutes integer, p_is_increase boolean) OWNER TO postgres;

--
-- Name: fn_rg_should_show_reality_check(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rg_should_show_reality_check(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_interval INT := 30;
  v_started TIMESTAMPTZ;
  v_session_id UUID;
  v_last_shown TIMESTAMPTZ;
  v_session_minutes NUMERIC;
  v_should_show BOOLEAN := false;
  v_time_limit INT;
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'p_user_id required'; END IF;

  SELECT reality_check_interval_minutes, session_time_limit_minutes
    INTO v_interval, v_time_limit
    FROM public.responsible_gaming_limits WHERE user_id = p_user_id;
  v_interval := COALESCE(v_interval, 30);

  SELECT id, started_at,
         (SELECT MAX(t) FROM unnest(reality_check_shown_at) t)
    INTO v_session_id, v_started, v_last_shown
    FROM public.responsible_gaming_sessions
   WHERE user_id = p_user_id AND ended_at IS NULL
   ORDER BY started_at DESC LIMIT 1;

  IF v_session_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'show', false, 'reason', 'no_open_session');
  END IF;

  v_session_minutes := EXTRACT(EPOCH FROM (now() - v_started)) / 60.0;

  -- Hard-cap: session exceeded time limit → force end + show
  IF v_time_limit IS NOT NULL AND v_session_minutes >= v_time_limit THEN
    UPDATE public.responsible_gaming_sessions
       SET ended_at = now(), force_closed_reason = 'session_time_limit'
     WHERE id = v_session_id;
    RETURN jsonb_build_object('ok', true, 'show', true, 'force_logout', true,
      'reason', 'session_time_limit', 'session_minutes', v_session_minutes,
      'limit_minutes', v_time_limit);
  END IF;

  -- Reality-check interval
  IF v_last_shown IS NULL THEN
    v_should_show := v_session_minutes >= v_interval;
  ELSE
    v_should_show := EXTRACT(EPOCH FROM (now() - v_last_shown)) / 60.0 >= v_interval;
  END IF;

  IF v_should_show THEN
    UPDATE public.responsible_gaming_sessions
       SET reality_check_shown_at = reality_check_shown_at || now()
     WHERE id = v_session_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'show', v_should_show,
    'session_id', v_session_id,
    'session_minutes', round(v_session_minutes::numeric, 2),
    'interval_minutes', v_interval,
    'force_logout', false
  );
END;
$$;


ALTER FUNCTION public.fn_rg_should_show_reality_check(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_rg_start_session(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rg_start_session(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session_id UUID;
  v_started TIMESTAMPTZ;
  v_check JSONB;
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'p_user_id required'; END IF;

  v_check := public.fn_rg_require_not_excluded(p_user_id);
  IF (v_check->>'ok')::BOOLEAN IS DISTINCT FROM true THEN
    RETURN v_check;
  END IF;

  SELECT id, started_at INTO v_session_id, v_started
    FROM public.responsible_gaming_sessions
   WHERE user_id = p_user_id AND ended_at IS NULL
   ORDER BY started_at DESC LIMIT 1;

  IF v_session_id IS NULL THEN
    INSERT INTO public.responsible_gaming_sessions (user_id)
      VALUES (p_user_id) RETURNING id, started_at INTO v_session_id, v_started;
  END IF;

  RETURN jsonb_build_object('ok', true, 'session_id', v_session_id, 'started_at', v_started);
END;
$$;


ALTER FUNCTION public.fn_rg_start_session(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_rls_on_new_public_table(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rls_on_new_public_table() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  obj record;
  v_name text;
BEGIN
  -- Deliberate escape hatch, mirroring fn_autorevoke_privileged_anon's
  -- app.allow_privileged_anon_grant. A table that genuinely must ship without
  -- RLS sets this for the session and is then on the record for doing so.
  IF COALESCE(current_setting('app.allow_rls_off_table', true), 'off') = 'on' THEN
    RETURN;
  END IF;

  FOR obj IN
    SELECT * FROM pg_event_trigger_ddl_commands()
     WHERE schema_name = 'public' AND object_type = 'table'
  LOOP
    BEGIN
      SELECT c.relname INTO v_name
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
       WHERE c.oid = obj.objid
         AND n.nspname = 'public'
         AND c.relkind IN ('r', 'p')
         AND NOT c.relrowsecurity;

      IF v_name IS NULL THEN
        CONTINUE;
      END IF;

      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', v_name);
      RAISE NOTICE 'RLS enabled automatically on public.% (no policies yet, so only service_role and the owner can see it). Add a policy if clients need access.', v_name;
    EXCEPTION WHEN OTHERS THEN
      -- This trigger fires on EVERY CREATE TABLE in the estate. It must never
      -- be the reason a migration fails, so a problem here is reported and
      -- swallowed - CHECK 10 remains the backstop.
      RAISE WARNING 'fn_rls_on_new_public_table could not secure %: %', COALESCE(v_name, obj.object_identity), SQLERRM;
    END;
  END LOOP;
END;
$$;


ALTER FUNCTION public.fn_rls_on_new_public_table() OWNER TO postgres;

--
-- Name: FUNCTION fn_rls_on_new_public_table(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_rls_on_new_public_table() IS 'Enables RLS on every newly created table in public. CREATE TABLE here inherits arwdxtm for anon and authenticated from the schema default privileges, so a new table is world-writable until someone notices - which on 2026-08-22 took two separate incidents and blocked every merge in the World Hub twice. Escape hatch: SET app.allow_rls_off_table = on.';


--
-- Name: fn_rls_policies_with_unhoisted_auth(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rls_policies_with_unhoisted_auth() RETURNS TABLE(table_name text, policy_name text, cmd text, roles text, bare_calls integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT p.tablename::text,
         p.policyname::text,
         p.cmd::text,
         p.roles::text,
         (regexp_count(lower(coalesce(p.qual,'') || ' || ' || coalesce(p.with_check,'')),
                       'auth\.(uid|role|jwt|email)\(\)')
          - regexp_count(lower(coalesce(p.qual,'') || ' || ' || coalesce(p.with_check,'')),
                       'select auth\.(uid|role|jwt|email)\(\)'))::int
  FROM pg_policies p
  WHERE p.schemaname = 'public'
    AND regexp_count(lower(coalesce(p.qual,'') || ' || ' || coalesce(p.with_check,'')),
                     'auth\.(uid|role|jwt|email)\(\)')
      > regexp_count(lower(coalesce(p.qual,'') || ' || ' || coalesce(p.with_check,'')),
                     'select auth\.(uid|role|jwt|email)\(\)')
  ORDER BY p.tablename, p.policyname;
$$;


ALTER FUNCTION public.fn_rls_policies_with_unhoisted_auth() OWNER TO postgres;

--
-- Name: FUNCTION fn_rls_policies_with_unhoisted_auth(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_rls_policies_with_unhoisted_auth() IS 'RLS policies that call auth.uid()/auth.role()/auth.jwt()/auth.email() bare rather than as (SELECT auth.uid()). A bare call is re-evaluated once per row; wrapped it becomes an InitPlan evaluated once per query. Must return zero rows. Reports only. Added 2026-09-01 after the seventh sweep of this same lint failed to hold.';


--
-- Name: fn_role_rank(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_role_rank(p_role text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT CASE p_role
           WHEN 'owner'       THEN 7
           WHEN 'co_owner'    THEN 6
           WHEN 'admin'       THEN 5
           WHEN 'super_agent' THEN 4
           WHEN 'agent'       THEN 3
           WHEN 'sub_agent'   THEN 2
           WHEN 'player'      THEN 1
           ELSE 0
         END;
$$;


ALTER FUNCTION public.fn_role_rank(p_role text) OWNER TO postgres;

