-- Name: fn_rotate_guest_invite_code(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rotate_guest_invite_code(p_stream_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_new uuid;
BEGIN
  UPDATE public.live_streams
     SET guest_invite_code = gen_random_uuid()
   WHERE id = p_stream_id
     AND broadcaster_id = auth.uid()
  RETURNING guest_invite_code INTO v_new;
  IF v_new IS NULL THEN
    RAISE EXCEPTION 'Not authorized to rotate invite for this stream';
  END IF;
  RETURN v_new;
END;
$$;


