--
-- Name: fn_satellite_target_contract_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_satellite_target_contract_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(OLD.entry_contract_locked,false)
     AND NEW.entry_contract_locked IS DISTINCT FROM true THEN
    RAISE EXCEPTION
      'tournament % funded-entry contract marker cannot be cleared',OLD.id
      USING ERRCODE = '55000';
  END IF;
  IF (NEW.buy_in_amount,NEW.buy_in_fee,NEW.bounty_amount,
      NEW.rebuy_cost,NEW.addon_cost,
      NEW.is_bounty,NEW.is_pko,NEW.is_mystery_bounty,NEW.is_premium_spin,
      NEW.variant,NEW.tournament_type,NEW.club_id)
       IS NOT DISTINCT FROM
     (OLD.buy_in_amount,OLD.buy_in_fee,OLD.bounty_amount,
      OLD.rebuy_cost,OLD.addon_cost,
      OLD.is_bounty,OLD.is_pko,OLD.is_mystery_bounty,OLD.is_premium_spin,
      OLD.variant,OLD.tournament_type,OLD.club_id) THEN
    RETURN NEW;
  END IF;
  IF COALESCE(OLD.entry_contract_locked,false) THEN
    RAISE EXCEPTION
      'tournament % economic contract is immutable after its first funded entry',
      OLD.id USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.chip_ledger l
     WHERE l.tournament_id = OLD.id
       AND l.from_type = 'player_wallet'
       AND l.to_type = 'prize_liability'
       AND l.to_entity_id = OLD.id
       AND lower(l.category) IN ('tournament_buyin','rebuy','addon')
  ) OR EXISTS (
    SELECT 1
      FROM public.tournament_satellite_settlements h
      JOIN public.tournament_satellite_awards a
        ON a.tournament_id = h.tournament_id
       AND a.delivery_kind = 'seat'
     WHERE h.target_id = OLD.id
  ) THEN
    RAISE EXCEPTION
      'tournament % economic contract is immutable after its first funded entry',
      OLD.id USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_satellite_target_contract_is_immutable() OWNER TO postgres;

--
-- Name: fn_satellite_target_player_provenance_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_satellite_target_player_provenance_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_source_ids uuid[] := ARRAY[]::uuid[];
  v_source_id uuid;
  v_status text;
  v_acquisition_key bigint:=hashtextextended(
    'ca:tournament-terminal-settlement:v1',0);
  v_owns_acquisition_root boolean:=false;
BEGIN
  IF TG_OP = 'UPDATE'
     AND (NEW.id IS DISTINCT FROM OLD.id
       OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.is_satellite_qualifier IS DISTINCT FROM OLD.is_satellite_qualifier
       OR NEW.source_satellite_id IS DISTINCT FROM OLD.source_satellite_id) THEN
    RAISE EXCEPTION 'tournament player ownership and entry provenance are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' AND OLD.source_satellite_id IS NOT NULL THEN
    v_source_ids := array_append(v_source_ids,OLD.source_satellite_id);
  END IF;
  IF TG_OP <> 'DELETE' AND NEW.source_satellite_id IS NOT NULL THEN
    v_source_ids := array_append(v_source_ids,NEW.source_satellite_id);
  END IF;
  IF TG_OP <> 'INSERT' THEN
    SELECT a.tournament_id INTO v_source_id
      FROM public.tournament_satellite_awards a
     WHERE a.registration_id = OLD.id;
    IF v_source_id IS NOT NULL THEN
      v_source_ids := array_append(v_source_ids,v_source_id);
    END IF;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    SELECT a.tournament_id INTO v_source_id
      FROM public.tournament_satellite_awards a
     WHERE a.registration_id = NEW.id;
    IF v_source_id IS NOT NULL THEN
      v_source_ids := array_append(v_source_ids,v_source_id);
    END IF;
  END IF;
  IF TG_OP = 'INSERT' AND NEW.tournament_id IS NOT NULL THEN
    -- The rolling satellite authority owns target before source. Take both
    -- roots in that same order so a direct provenance insert cannot invert
    -- the pair across its specialized and generic guards.
    SELECT upper(COALESCE(t.status::text,'')) INTO v_status
      FROM public.tournaments t
     WHERE t.id = NEW.tournament_id FOR SHARE;
    IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'terminal target tournament cannot gain satellite provenance'
        USING ERRCODE = '55000';
    END IF;
    -- A satellite winner may use a returned tournament-entry ticket only
    -- after its source satellite has completed. That is a legitimate NEW
    -- provenance row, but only inside the canonical registration root that
    -- acquired the terminal-global lock before touching any child row. A raw
    -- insert has no such lock and remains refused.
    SELECT EXISTS(
      SELECT 1 FROM pg_catalog.pg_locks l
       WHERE l.pid=pg_backend_pid()
         AND l.locktype='advisory'
         AND l.database=(
           SELECT d.oid FROM pg_catalog.pg_database d
            WHERE d.datname=current_database())
         AND l.classid=(((v_acquisition_key>>32)&4294967295)::oid)
         AND l.objid=((v_acquisition_key&4294967295)::oid)
         AND l.objsubid=1
         AND l.mode='ExclusiveLock'
         AND l.granted)
      INTO v_owns_acquisition_root;
  END IF;
  IF TG_OP = 'INSERT' THEN
    FOREACH v_source_id IN ARRAY v_source_ids LOOP
      IF v_source_id IS DISTINCT FROM NEW.tournament_id THEN
        SELECT upper(COALESCE(t.status::text,'')) INTO v_status
          FROM public.tournaments t
         WHERE t.id = v_source_id FOR SHARE;
        IF v_status IN ('COMPLETED','CANCELLED','CANCELED')
           AND NOT COALESCE(v_owns_acquisition_root,false) THEN
          RAISE EXCEPTION 'completed satellite target provenance is immutable'
            USING ERRCODE = '55000';
        END IF;
      END IF;
    END LOOP;
  END IF;
  IF NOT (TG_OP='INSERT' AND COALESCE(v_owns_acquisition_root,false))
     AND EXISTS (
    SELECT 1 FROM unnest(v_source_ids) source(id)
     WHERE public.fn_ca_has_committed_tournament_receipt(source.id)
  ) THEN
    RAISE EXCEPTION 'completed satellite target provenance is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_satellite_target_player_provenance_is_immutable() OWNER TO postgres;

--
-- Name: fn_satellite_target_rake_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_satellite_target_rake_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_old_source_id uuid;
  v_new_source_id uuid;
  v_text text;
  v_old_marker timestamptz;
  v_new_marker timestamptz;
  v_status text;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    v_text := OLD.metadata->>'satellite_id';
    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_old_source_id := v_text::uuid;
    END IF;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    v_text := NEW.metadata->>'satellite_id';
    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_new_source_id := v_text::uuid;
    END IF;
  END IF;
  IF TG_OP = 'UPDATE'
     AND (NEW.metadata->>'satellite_id') IS DISTINCT FROM
         (OLD.metadata->>'satellite_id') THEN
    RAISE EXCEPTION 'satellite target rake ownership is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' THEN v_old_marker := OLD.terminal_closed_at; END IF;
  IF TG_OP <> 'DELETE' THEN v_new_marker := NEW.terminal_closed_at; END IF;
  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker
     AND public.fn_ca_terminal_marker_transition_is_exact(
           to_jsonb(OLD),to_jsonb(NEW),OLD.tournament_id) THEN
    RETURN NEW;
  END IF;
  -- A recognized satellite fee row is append-only. Refusing an already-locked
  -- UPDATE/DELETE before any parent lookup removes the child-to-source lock
  -- edge. INSERT locks the target first, then the source, matching the
  -- canonical satellite authority.
  IF TG_OP <> 'INSERT'
     AND COALESCE(v_old_source_id,v_new_source_id) IS NOT NULL THEN
    RAISE EXCEPTION 'satellite target rake rows are append-only'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_status
      FROM public.tournaments t
     WHERE t.id = NEW.tournament_id FOR SHARE;
    IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'terminal target tournament cannot gain satellite rake evidence'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  IF TG_OP = 'INSERT' AND v_new_source_id IS NOT NULL
     AND v_new_source_id IS DISTINCT FROM NEW.tournament_id THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_status
      FROM public.tournaments t
     WHERE t.id = v_new_source_id FOR SHARE;
    IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'completed satellite target rake evidence is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  IF v_new_source_id IS NOT NULL
     AND v_new_source_id IS DISTINCT FROM v_old_source_id THEN
    PERFORM 1 FROM public.tournaments t
     WHERE t.id = v_new_source_id FOR SHARE;
  END IF;
  IF public.fn_ca_has_committed_tournament_receipt(v_old_source_id)
     OR public.fn_ca_has_committed_tournament_receipt(v_new_source_id) THEN
    RAISE EXCEPTION 'completed satellite target rake evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_satellite_target_rake_is_immutable() OWNER TO postgres;

--
-- Name: fn_satellite_transfer_ledger_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_satellite_transfer_ledger_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_source_ids uuid[] := ARRAY[]::uuid[];
  v_source_id uuid;
  v_target_id uuid;
  v_text text;
  v_row jsonb;
  v_status text;
BEGIN
  IF TG_OP = 'UPDATE'
     AND (NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.from_entity_id IS DISTINCT FROM OLD.from_entity_id
       OR NEW.to_entity_id IS DISTINCT FROM OLD.to_entity_id
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR (NEW.metadata->>'satellite_id') IS DISTINCT FROM
          (OLD.metadata->>'satellite_id')) THEN
    RAISE EXCEPTION 'satellite transfer journal ownership is immutable'
      USING ERRCODE = '55000';
  END IF;
  FOREACH v_row IN ARRAY ARRAY[
    CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END,
    CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END
  ] LOOP
    IF v_row IS NULL THEN CONTINUE; END IF;
    v_text := v_row->>'tournament_id';
    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_ids := array_append(v_source_ids,v_text::uuid);
    END IF;
    IF v_row->>'from_type' = 'prize_liability' THEN
      v_text := v_row->>'from_entity_id';
      IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_source_ids := array_append(v_source_ids,v_text::uuid);
      END IF;
    END IF;
    v_text := split_part(COALESCE(v_row->>'idempotency_key',''),':',2);
    IF COALESCE(v_row->>'idempotency_key','') LIKE 'tourney:%:seat:%:pool_transfer'
       AND v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_ids := array_append(v_source_ids,v_text::uuid);
    END IF;
    v_text := v_row->'metadata'->>'satellite_id';
    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_ids := array_append(v_source_ids,v_text::uuid);
    END IF;
  END LOOP;
  IF TG_OP <> 'INSERT' AND cardinality(v_source_ids) > 0 THEN
    RAISE EXCEPTION 'satellite transfer journal is append-only'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.to_type = 'prize_liability' THEN
    SELECT t.id INTO v_target_id FROM public.tournaments t
     WHERE t.id = NEW.to_entity_id;
    IF v_target_id IS NOT NULL THEN
      -- The transfer's AFTER trigger writes target escrow, so own the target
      -- before any source root exactly as fn_settle_satellite_tournament does.
      SELECT upper(COALESCE(t.status::text,'')) INTO v_status
        FROM public.tournaments t
       WHERE t.id = v_target_id FOR SHARE;
      IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
        RAISE EXCEPTION 'terminal target cannot accept a satellite transfer journal'
          USING ERRCODE = '55000';
      END IF;
    END IF;
  END IF;
  FOR v_source_id IN
    SELECT DISTINCT source.id FROM unnest(v_source_ids) source(id)
     WHERE source.id IS NOT NULL ORDER BY source.id
  LOOP
    IF TG_OP = 'INSERT' AND v_source_id IS DISTINCT FROM v_target_id THEN
      SELECT upper(COALESCE(t.status::text,'')) INTO v_status
        FROM public.tournaments t
       WHERE t.id = v_source_id FOR SHARE;
      IF v_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
        RAISE EXCEPTION 'completed satellite transfer journal is immutable'
          USING ERRCODE = '55000';
      END IF;
    END IF;
    IF public.fn_ca_has_committed_tournament_receipt(v_source_id) THEN
      RAISE EXCEPTION 'completed satellite transfer journal is immutable'
        USING ERRCODE = '55000';
    END IF;
  END LOOP;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_satellite_transfer_ledger_is_immutable() OWNER TO postgres;

--
-- Name: fn_save_club_identity_messages(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_save_club_identity_messages(p_club_id uuid, p_tagline text, p_lobby_message text, p_description text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid:=auth.uid(); v_tagline text; v_lobby text; v_description text;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_can_create_games(p_club_id,v_uid) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized');
  END IF;
  IF char_length(COALESCE(p_tagline,''))>72 OR char_length(COALESCE(p_lobby_message,''))>72 OR char_length(COALESCE(p_description,''))>500 THEN
    RETURN jsonb_build_object('ok',false,'reason','character_limit');
  END IF;
  v_tagline:=trim(regexp_replace(COALESCE(p_tagline,''),'[\r\n\t ]+',' ','g'));
  v_lobby:=trim(regexp_replace(COALESCE(p_lobby_message,''),'[\r\n\t ]+',' ','g'));
  v_description:=trim(COALESCE(p_description,''));
  UPDATE public.clubs SET tagline=NULLIF(v_tagline,''),lobby_message=NULLIF(v_lobby,''),description=NULLIF(v_description,''),updated_at=now() WHERE id=p_club_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','club_not_found'); END IF;
  RETURN jsonb_build_object('ok',true);
END $$;


ALTER FUNCTION public.fn_save_club_identity_messages(p_club_id uuid, p_tagline text, p_lobby_message text, p_description text) OWNER TO postgres;

--
-- Name: fn_save_club_identity_messages_versioned(uuid, bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_save_club_identity_messages_versioned(p_club_id uuid, p_expected_revision bigint, p_tagline text, p_lobby_message text, p_description text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_current_revision bigint;
  v_tagline text;
  v_lobby text;
  v_description text;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_can_manage_club_message(p_club_id, v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;
  SELECT message_revision INTO v_current_revision
    FROM public.clubs WHERE id = p_club_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'club_not_found');
  END IF;
  IF v_current_revision <> p_expected_revision THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'version_conflict',
      'current_revision', v_current_revision
    );
  END IF;
  -- 240 for the message, matching the CHECK and fn_set_club_lobby_message;
  -- 72 for the tagline, which is a one-line identity and unchanged.
  IF char_length(COALESCE(p_tagline, '')) > 72
    OR char_length(COALESCE(p_lobby_message, '')) > 240
    OR char_length(COALESCE(p_description, '')) > 500 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'character_limit');
  END IF;
  v_tagline := trim(regexp_replace(COALESCE(p_tagline, ''), '[\r\n\t ]+', ' ', 'g'));
  v_lobby := trim(regexp_replace(COALESCE(p_lobby_message, ''), '[\r\n\t ]+', ' ', 'g'));
  v_description := trim(COALESCE(p_description, ''));
  UPDATE public.clubs
    SET tagline = NULLIF(v_tagline, ''),
        lobby_message = NULLIF(v_lobby, ''),
        description = NULLIF(v_description, ''),
        -- Stamped here too. A message written through this path used to arrive
        -- with no written-at, so nothing downstream could tell how old it was.
        lobby_message_updated_at = CASE
          WHEN NULLIF(v_lobby, '') IS NULL THEN NULL
          WHEN NULLIF(v_lobby, '') IS DISTINCT FROM lobby_message THEN now()
          ELSE lobby_message_updated_at
        END,
        message_revision = message_revision + 1,
        updated_at = now()
    WHERE id = p_club_id
    RETURNING message_revision INTO v_current_revision;
  RETURN jsonb_build_object(
    'ok', true,
    'revision', v_current_revision,
    'identity', jsonb_build_object(
      'tagline', v_tagline,
      'lobby_message', v_lobby,
      'description', v_description
    )
  );
END;
$$;


ALTER FUNCTION public.fn_save_club_identity_messages_versioned(p_club_id uuid, p_expected_revision bigint, p_tagline text, p_lobby_message text, p_description text) OWNER TO postgres;

--
-- Name: FUNCTION fn_save_club_identity_messages_versioned(p_club_id uuid, p_expected_revision bigint, p_tagline text, p_lobby_message text, p_description text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_save_club_identity_messages_versioned(p_club_id uuid, p_expected_revision bigint, p_tagline text, p_lobby_message text, p_description text) IS 'Compare-and-swap command for player-facing club identity messages.';


--
-- Name: fn_save_engine_maintenance_break(text, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_save_engine_maintenance_break(p_phase text, p_announced_at timestamp with time zone, p_break_started_at timestamp with time zone, p_break_ends_at timestamp with time zone, p_reason text, p_declared_by text, p_ownership_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '45s'
    SET lock_timeout TO '40s'
    AS $$
DECLARE
  v_rows integer;
  v_now timestamptz;
BEGIN
  IF p_ownership_token IS NULL THEN
    RAISE EXCEPTION 'MAINTENANCE_OWNERSHIP_TOKEN_REQUIRED'
      USING ERRCODE = '22004';
  END IF;
  PERFORM pg_advisory_xact_lock(530090, 1);
  -- Sample after acquiring the same lock as every maintenance-row writer.
  v_now := clock_timestamp();
  INSERT INTO public.engine_maintenance_break (
    id, phase, announced_at, break_started_at, enforce_freeze,
    break_ends_at, reason, declared_by, ownership_token, updated_at
  ) VALUES (
    true, p_phase, p_announced_at, p_break_started_at, true,
    p_break_ends_at, p_reason, p_declared_by, p_ownership_token, v_now
  )
  ON CONFLICT (id) DO UPDATE SET
    phase = EXCLUDED.phase,
    announced_at = EXCLUDED.announced_at,
    break_started_at = EXCLUDED.break_started_at,
    enforce_freeze = EXCLUDED.enforce_freeze,
    break_ends_at = EXCLUDED.break_ends_at,
    reason = EXCLUDED.reason,
    declared_by = EXCLUDED.declared_by,
    ownership_token = EXCLUDED.ownership_token,
    updated_at = EXCLUDED.updated_at
  WHERE public.engine_maintenance_break.ownership_token = EXCLUDED.ownership_token
     OR (
       -- A delayed countdown/save from the old process is never a new hour.
       EXCLUDED.phase = 'last_hand'
       AND EXCLUDED.break_started_at IS NULL
       AND EXCLUDED.break_ends_at IS NULL
       AND EXCLUDED.announced_at >= v_now - INTERVAL '2 minutes'
       AND EXCLUDED.announced_at <= v_now + INTERVAL '5 seconds'
       AND public.engine_maintenance_break.announced_at < EXCLUDED.announced_at
       -- Match the engine's eight-minute maximum adoption age. Keep an
       -- explicitly later countdown end protected even if its announcement
       -- is older, so renewal cannot shorten a currently recorded break.
       AND public.engine_maintenance_break.announced_at < v_now - INTERVAL '8 minutes'
       AND COALESCE(
         public.engine_maintenance_break.break_ends_at,
         public.engine_maintenance_break.announced_at + INTERVAL '7 minutes'
       ) <= v_now
     );
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'MAINTENANCE_OWNERSHIP_LOST: save refused'
      USING ERRCODE = '40001';
  END IF;
END;
$$;


ALTER FUNCTION public.fn_save_engine_maintenance_break(p_phase text, p_announced_at timestamp with time zone, p_break_started_at timestamp with time zone, p_break_ends_at timestamp with time zone, p_reason text, p_declared_by text, p_ownership_token uuid) OWNER TO postgres;

--
-- Name: fn_save_game_ticker_settings(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_save_game_ticker_settings(p_scope text, p_scope_id uuid, p_settings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_access jsonb;
  v_sanitized jsonb;
  v_font text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000'; END IF;
  IF p_scope NOT IN ('club','union') OR p_scope_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_scope');
  END IF;

  IF p_scope='club' THEN
    v_access := public.fn_game_creation_access(p_scope_id);
    IF COALESCE((v_access->>'allowed')::boolean,false)=false OR v_access->>'union_id' IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','not_authorized');
    END IF;
  ELSIF NOT public.fn_is_union_operator(p_scope_id,v_uid) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized');
  END IF;

  v_font := CASE WHEN p_settings->>'font_family' IN ('Rajdhani','Inter','Roboto Condensed','System')
    THEN p_settings->>'font_family' ELSE 'Rajdhani' END;
  v_sanitized := jsonb_build_object(
    'enabled', COALESCE((p_settings->>'enabled')::boolean,true),
    'speed_seconds', LEAST(60,GREATEST(8,COALESCE((p_settings->>'speed_seconds')::int,24))),
    'background_color', CASE WHEN COALESCE(p_settings->>'background_color','') ~ '^#[0-9A-Fa-f]{6}$' THEN p_settings->>'background_color' ELSE '#0b1a33' END,
    'text_color', CASE WHEN COALESCE(p_settings->>'text_color','') ~ '^#[0-9A-Fa-f]{6}$' THEN p_settings->>'text_color' ELSE '#f5fbff' END,
    'accent_color', CASE WHEN COALESCE(p_settings->>'accent_color','') ~ '^#[0-9A-Fa-f]{6}$' THEN p_settings->>'accent_color' ELSE '#00d4ff' END,
    'font_family', v_font,
    'sources', COALESCE(p_settings->'sources','{}'::jsonb),
    'custom_messages', COALESCE((SELECT jsonb_agg(left(regexp_replace(value,'\s+',' ','g'),160)) FROM jsonb_array_elements_text(COALESCE(p_settings->'custom_messages','[]'::jsonb)) WITH ORDINALITY m(value,ord) WHERE ord<=10),'[]'::jsonb),
    'service_messages', COALESCE((SELECT jsonb_agg(left(regexp_replace(value,'\s+',' ','g'),160)) FROM jsonb_array_elements_text(COALESCE(p_settings->'service_messages','[]'::jsonb)) WITH ORDINALITY m(value,ord) WHERE ord<=5),'[]'::jsonb)
  );

  IF p_scope='club' THEN
    INSERT INTO public.game_ticker_settings(club_id,settings,created_by)
    VALUES(p_scope_id,v_sanitized,v_uid)
    ON CONFLICT (club_id) WHERE club_id IS NOT NULL DO UPDATE SET settings=EXCLUDED.settings,updated_at=now();
  ELSE
    INSERT INTO public.game_ticker_settings(union_id,settings,created_by)
    VALUES(p_scope_id,v_sanitized,v_uid)
    ON CONFLICT (union_id) WHERE union_id IS NOT NULL DO UPDATE SET settings=EXCLUDED.settings,updated_at=now();
  END IF;
  RETURN jsonb_build_object('ok',true,'settings',v_sanitized);
END $_$;


ALTER FUNCTION public.fn_save_game_ticker_settings(p_scope text, p_scope_id uuid, p_settings jsonb) OWNER TO postgres;

--
-- Name: fn_save_game_ticker_settings_versioned(text, uuid, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_save_game_ticker_settings_versioned(p_scope text, p_scope_id uuid, p_expected_revision bigint, p_settings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_access jsonb;
  v_existing_revision bigint;
  v_next_revision bigint;
  v_updated_at timestamptz;
  v_sanitized jsonb;
  v_sources jsonb := '{}'::jsonb;
  v_custom_messages jsonb := '[]'::jsonb;
  v_service_messages jsonb := '[]'::jsonb;
  v_source text;
  v_font text;
  v_speed integer;
  v_background text;
  v_text text;
  v_accent text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;
  IF p_scope NOT IN ('club', 'union') OR p_scope_id IS NULL
    OR COALESCE(p_expected_revision, -1) < 0
    OR jsonb_typeof(p_settings) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_payload');
  END IF;
  IF p_scope = 'club' THEN
    v_access := public.fn_game_creation_access(p_scope_id);
    IF COALESCE((v_access->>'allowed')::boolean, false) = false
      OR v_access->>'union_id' IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
    END IF;
    -- Serialize the first write as well as updates. A row lock cannot protect
    -- two simultaneous inserts when neither transaction can see a row yet.
    PERFORM pg_advisory_xact_lock(hashtextextended('ticker:club:' || p_scope_id::text, 0));
    SELECT revision INTO v_existing_revision
      FROM public.game_ticker_settings WHERE club_id = p_scope_id FOR UPDATE;
  ELSE
    IF NOT public.fn_is_union_operator(p_scope_id, v_uid) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('ticker:union:' || p_scope_id::text, 0));
    SELECT revision INTO v_existing_revision
      FROM public.game_ticker_settings WHERE union_id = p_scope_id FOR UPDATE;
  END IF;

  IF COALESCE(v_existing_revision, 0) <> p_expected_revision THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'version_conflict',
      'current_revision', COALESCE(v_existing_revision, 0)
    );
  END IF;

  IF p_settings ? 'enabled' AND jsonb_typeof(p_settings->'enabled') <> 'boolean' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_payload');
  END IF;
  IF COALESCE(p_settings->>'speed_seconds', '') !~ '^[0-9]{1,3}$' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_payload');
  END IF;
  v_speed := (p_settings->>'speed_seconds')::integer;
  IF v_speed NOT BETWEEN 8 AND 60 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_payload');
  END IF;
  v_background := p_settings->>'background_color';
  v_text := p_settings->>'text_color';
  v_accent := p_settings->>'accent_color';
  IF COALESCE(v_background, '') !~ '^#[0-9A-Fa-f]{6}$'
    OR COALESCE(v_text, '') !~ '^#[0-9A-Fa-f]{6}$'
    OR COALESCE(v_accent, '') !~ '^#[0-9A-Fa-f]{6}$' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_colors');
  END IF;
  IF public.fn_game_management_contrast_ratio(v_text, v_background) < 4.5
    OR public.fn_game_management_contrast_ratio(v_accent, v_background) < 3.0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'inaccessible_colors');
  END IF;
  v_font := p_settings->>'font_family';
  IF v_font NOT IN ('Rajdhani', 'Inter', 'Roboto Condensed', 'System') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_font');
  END IF;
  IF jsonb_typeof(p_settings->'sources') <> 'object'
    OR jsonb_typeof(p_settings->'custom_messages') <> 'array'
    OR jsonb_typeof(p_settings->'service_messages') <> 'array'
    OR jsonb_array_length(p_settings->'custom_messages') > 10
    OR jsonb_array_length(p_settings->'service_messages') > 5 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_payload');
  END IF;

  FOREACH v_source IN ARRAY ARRAY[
    'overlays', 'starting_soon', 'custom_messages', 'registration_closing',
    'guarantees', 'table_openings', 'maintenance', 'winner_results'
  ] LOOP
    IF p_settings->'sources' ? v_source
      AND jsonb_typeof(p_settings->'sources'->v_source) <> 'boolean' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'invalid_payload');
    END IF;
    v_sources := v_sources || jsonb_build_object(
      v_source,
      COALESCE((p_settings->'sources'->>v_source)::boolean, false)
    );
  END LOOP;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_settings->'custom_messages') item
    WHERE jsonb_typeof(item) <> 'string'
  ) OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_settings->'service_messages') item
    WHERE jsonb_typeof(item) <> 'string'
  ) OR EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(p_settings->'custom_messages') item(value)
    WHERE char_length(value) > 160 OR btrim(value) = ''
  ) OR EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(p_settings->'service_messages') item(value)
    WHERE char_length(value) > 160 OR btrim(value) = ''
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_messages');
  END IF;

  SELECT COALESCE(jsonb_agg(regexp_replace(btrim(value), '\s+', ' ', 'g') ORDER BY ord), '[]'::jsonb)
    INTO v_custom_messages
    FROM jsonb_array_elements_text(p_settings->'custom_messages') WITH ORDINALITY item(value, ord);
  SELECT COALESCE(jsonb_agg(regexp_replace(btrim(value), '\s+', ' ', 'g') ORDER BY ord), '[]'::jsonb)
    INTO v_service_messages
    FROM jsonb_array_elements_text(p_settings->'service_messages') WITH ORDINALITY item(value, ord);

  v_sanitized := jsonb_build_object(
    'enabled', COALESCE((p_settings->>'enabled')::boolean, true),
    'speed_seconds', v_speed,
    'background_color', lower(v_background),
    'text_color', lower(v_text),
    'accent_color', lower(v_accent),
    'font_family', v_font,
    'sources', v_sources,
    'custom_messages', v_custom_messages,
    'service_messages', v_service_messages
  );
  v_next_revision := COALESCE(v_existing_revision, 0) + 1;

  IF p_scope = 'club' THEN
    INSERT INTO public.game_ticker_settings(club_id, settings, created_by, revision, updated_at)
    VALUES (p_scope_id, v_sanitized, v_uid, v_next_revision, now())
    ON CONFLICT (club_id) WHERE club_id IS NOT NULL DO UPDATE
      SET settings = EXCLUDED.settings,
          revision = EXCLUDED.revision,
          updated_at = now()
    RETURNING updated_at INTO v_updated_at;
  ELSE
    INSERT INTO public.game_ticker_settings(union_id, settings, created_by, revision, updated_at)
    VALUES (p_scope_id, v_sanitized, v_uid, v_next_revision, now())
    ON CONFLICT (union_id) WHERE union_id IS NOT NULL DO UPDATE
      SET settings = EXCLUDED.settings,
          revision = EXCLUDED.revision,
          updated_at = now()
    RETURNING updated_at INTO v_updated_at;
  END IF;
  RETURN jsonb_build_object(
    'ok', true,
    'settings', v_sanitized,
    'revision', v_next_revision,
    'updated_at', v_updated_at
  );
END $_$;


ALTER FUNCTION public.fn_save_game_ticker_settings_versioned(p_scope text, p_scope_id uuid, p_expected_revision bigint, p_settings jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_save_game_ticker_settings_versioned(p_scope text, p_scope_id uuid, p_expected_revision bigint, p_settings jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_save_game_ticker_settings_versioned(p_scope text, p_scope_id uuid, p_expected_revision bigint, p_settings jsonb) IS 'Versioned, hostile-input-safe Table Management ticker command. Stale operators cannot overwrite newer saves.';


