--
-- Name: fn_save_training_session_v2(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_save_training_session_v2(p_user_id uuid, p_attempt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  attempt_row public.training_attempts%ROWTYPE;
  session_row public.training_sessions%ROWTYPE;
  hand_history jsonb := '[]'::jsonb;
  position_stats jsonb := '{}'::jsonb;
  classification_counts jsonb := '{}'::jsonb;
  total_ev_loss numeric := 0;
  mistake_count integer := 0;
  measured_count integer := 0;
  decision_count integer := 0;
  continuation_decision_count integer := 0;
  avg_frequency_diff numeric := 0;
  inserted boolean := false;
BEGIN
  SELECT * INTO attempt_row
  FROM public.training_attempts
  WHERE id = p_attempt_id
  FOR KEY SHARE;

  IF p_user_id IS NULL OR NOT FOUND OR attempt_row.user_id <> p_user_id THEN
    RETURN jsonb_build_object('success', false, 'status', 404,
      'code', 'TRAINING_ATTEMPT_NOT_FOUND',
      'error', 'The completed Training attempt was not found.');
  END IF;
  IF attempt_row.status <> 'completed' THEN
    RETURN jsonb_build_object('success', false, 'status', 409,
      'code', 'TRAINING_ATTEMPT_NOT_COMPLETED',
      'error', 'Only a completed Training attempt can become an analytics session.');
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'handNumber', answer.hand_ordinal,
      'decisionOrdinal', answer.decision_ordinal,
      'questionId', answer.question_id,
      'snapshotKey', answer.snapshot_key,
      'selectedAnswer', answer.answer_id,
      'isCorrect', answer.is_correct,
      'classification', answer.classification,
      'street', answer.street,
      'heroPosition', answer.hero_position,
      'villainPosition', answer.villain_position,
      'spotType', answer.spot_type,
      'solverVerified', answer.solver_verified,
      'evLossMeasured', answer.ev_loss_measured,
      'evLoss', CASE WHEN answer.ev_loss_measured THEN answer.ev_loss ELSE NULL END,
      'answeredAt', answer.answered_at
    ) ORDER BY answer.hand_ordinal, answer.decision_ordinal), '[]'::jsonb),
    coalesce(sum(answer.ev_loss) FILTER (WHERE answer.ev_loss_measured), 0),
    count(*) FILTER (WHERE NOT answer.is_correct)::integer,
    count(*) FILTER (WHERE answer.ev_loss_measured)::integer,
    count(*)::integer,
    count(*) FILTER (WHERE answer.decision_ordinal > 1)::integer,
    coalesce(avg(abs(answer.optimal_frequency - answer.selected_frequency))
      FILTER (WHERE answer.solver_verified), 0)
  INTO hand_history, total_ev_loss, mistake_count, measured_count,
    decision_count, continuation_decision_count, avg_frequency_diff
  FROM public.training_answers answer
  WHERE answer.attempt_id = attempt_row.id;

  SELECT coalesce(jsonb_object_agg(bucket.position, jsonb_build_object(
      'total', bucket.total,
      'correct', bucket.correct,
      'accuracy', round(bucket.correct::numeric / bucket.total * 100, 2),
      'evLoss', bucket.ev_loss
    )), '{}'::jsonb)
  INTO position_stats
  FROM (
    SELECT coalesce(nullif(hero_position, ''), 'unknown') AS position,
      count(*)::integer AS total,
      count(*) FILTER (WHERE is_correct)::integer AS correct,
      coalesce(sum(ev_loss) FILTER (WHERE ev_loss_measured), 0) AS ev_loss
    FROM public.training_answers
    WHERE attempt_id = attempt_row.id
    GROUP BY coalesce(nullif(hero_position, ''), 'unknown')
  ) bucket;

  SELECT coalesce(jsonb_object_agg(bucket.classification, bucket.total), '{}'::jsonb)
  INTO classification_counts
  FROM (
    SELECT coalesce(nullif(classification, ''), 'unknown') AS classification,
      count(*)::integer AS total
    FROM public.training_answers
    WHERE attempt_id = attempt_row.id
    GROUP BY coalesce(nullif(classification, ''), 'unknown')
  ) bucket;

  INSERT INTO public.training_sessions (
    user_id, game_id, game_name, gtow_score, score_scale, total_ev_loss,
    hands_played, mistake_count, accuracy, correct_count, best_streak,
    level_passed, level, hand_history, position_stats, classification_counts,
    trainer_config, avg_ev_loss_per_hand, avg_ev_loss_per_mistake,
    avg_frequency_diff, attempt_id, created_at
  ) VALUES (
    attempt_row.user_id, attempt_row.game_id, attempt_row.game_id,
    attempt_row.accuracy_percentage * 2 - 100, 2, total_ev_loss,
    attempt_row.answered_hands, mistake_count, attempt_row.accuracy_percentage,
    attempt_row.correct_hands, attempt_row.best_streak, attempt_row.passed,
    attempt_row.level, hand_history, position_stats, classification_counts,
    jsonb_build_object(
      'sessionKind', attempt_row.session_kind,
      'difficulty', attempt_row.difficulty,
      'targetHands', attempt_row.expected_hands,
      'decisionCount', decision_count,
      'continuationDecisionCount', continuation_decision_count,
      'practiceOnly', attempt_row.practice_only,
      'configHash', attempt_row.config_hash
    ),
    CASE WHEN measured_count > 0 THEN round(total_ev_loss / attempt_row.answered_hands, 4) ELSE 0 END,
    CASE WHEN measured_count > 0 AND mistake_count > 0 THEN round(total_ev_loss / mistake_count, 4) ELSE 0 END,
    round(avg_frequency_diff, 4), attempt_row.id, attempt_row.completed_at
  )
  ON CONFLICT (attempt_id) WHERE attempt_id IS NOT NULL DO NOTHING
  RETURNING * INTO session_row;
  inserted := FOUND;

  IF NOT inserted THEN
    SELECT * INTO session_row FROM public.training_sessions
    WHERE attempt_id = attempt_row.id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'newSession', inserted,
    'attemptId', attempt_row.id,
    'practiceOnly', attempt_row.practice_only,
    'session', to_jsonb(session_row),
    'diamondsEarned', 0
  );
END;
$$;


ALTER FUNCTION public.fn_save_training_session_v2(p_user_id uuid, p_attempt_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_save_training_session_v2(p_user_id uuid, p_attempt_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_save_training_session_v2(p_user_id uuid, p_attempt_id uuid) IS 'Creates one immutable analytics projection from a completed Training attempt, including explicit measured-EV flags.';


--
-- Name: fn_schedule_managed_game_close(text, uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_schedule_managed_game_close(p_kind text, p_game_id uuid, p_expected_version integer, p_execute_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_club uuid;
  v_schedule public.managed_game_schedules%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000'; END IF;
  IF p_kind NOT IN ('table','tournament') OR p_expected_version < 1
     OR p_execute_at <= now() + interval '1 minute'
     OR p_execute_at > now() + interval '365 days' THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_schedule');
  END IF;
  IF p_kind='table' THEN
    SELECT club_id INTO v_club FROM public.tables WHERE id=p_game_id;
  ELSE
    SELECT club_id INTO v_club FROM public.tournaments WHERE id=p_game_id;
  END IF;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','game_not_found'); END IF;
  IF NOT public.fn_can_create_games(v_club,v_uid) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.managed_game_contract_versions
    WHERE game_kind=p_kind AND game_id=p_game_id AND version=p_expected_version
  ) THEN RETURN jsonb_build_object('ok',false,'reason','stale_contract_version'); END IF;

  SELECT * INTO v_schedule FROM public.managed_game_schedules
   WHERE game_kind=p_kind AND game_id=p_game_id AND status IN ('scheduled','executing')
   FOR UPDATE;
  IF FOUND AND v_schedule.status='executing' THEN
    RETURN jsonb_build_object('ok',false,'reason','schedule_not_pending');
  ELSIF FOUND THEN
    UPDATE public.managed_game_schedules SET actor_id=v_uid,command_id=gen_random_uuid(),
      expected_version=p_expected_version,execute_at=p_execute_at,result='{}'::jsonb,
      created_at=now()
    WHERE schedule_id=v_schedule.schedule_id RETURNING * INTO v_schedule;
  ELSE
    INSERT INTO public.managed_game_schedules(
      actor_id,game_kind,game_id,expected_version,execute_at
    ) VALUES (v_uid,p_kind,p_game_id,p_expected_version,p_execute_at)
    RETURNING * INTO v_schedule;
  END IF;
  PERFORM public.fn_emit_game_management_event(
    'game_changed',v_club,NULL,NULL,p_kind,p_game_id,NULL,
    jsonb_build_object('operation','close_scheduled','schedule_id',v_schedule.schedule_id)
  );
  RETURN jsonb_build_object('ok',true,'schedule',to_jsonb(v_schedule));
END;
$$;


ALTER FUNCTION public.fn_schedule_managed_game_close(p_kind text, p_game_id uuid, p_expected_version integer, p_execute_at timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_schema_manifest(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_schema_manifest() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'tables', (SELECT coalesce(jsonb_agg(table_name ORDER BY table_name), '[]'::jsonb)
               FROM information_schema.tables
               WHERE table_schema='public' AND table_type IN ('BASE TABLE','VIEW')),
    'functions', (SELECT coalesce(jsonb_agg(DISTINCT proname ORDER BY proname), '[]'::jsonb)
                  FROM pg_proc WHERE pronamespace='public'::regnamespace)
  );
$$;


ALTER FUNCTION public.fn_schema_manifest() OWNER TO postgres;

--
-- Name: fn_score_training_attempt_hand_v2(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_score_training_attempt_hand_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.attempt_id IS NOT NULL AND NEW.decision_ordinal = 1 THEN
    UPDATE public.training_attempt_hands
    SET status = 'scored',
        result_is_correct = NEW.is_correct,
        scored_at = NEW.answered_at
    WHERE attempt_id = NEW.attempt_id
      AND hand_ordinal = NEW.hand_ordinal
      AND status = 'allocated';
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_HAND_ALREADY_SCORED';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_score_training_attempt_hand_v2() OWNER TO postgres;

--
-- Name: fn_search_messages(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_search_messages(p_conversation_id uuid, p_user_id uuid, p_query text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_participant boolean;
  v_query text;
  v_result jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( p_user_id IS DISTINCT FROM auth.uid())) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  IF p_conversation_id IS NULL OR p_user_id IS NULL OR p_query IS NULL OR length(p_query) < 2 THEN
    RETURN '[]'::jsonb;
  END IF;

  BEGIN
    SELECT EXISTS(
      SELECT 1 FROM public.messenger_conversation_participants
      WHERE conversation_id = p_conversation_id AND user_id = p_user_id
    ) INTO v_is_participant;
  EXCEPTION WHEN undefined_table THEN
    SELECT EXISTS(
      SELECT 1 FROM public.messenger_messages
      WHERE conversation_id = p_conversation_id AND sender_id = p_user_id
      LIMIT 1
    ) INTO v_is_participant;
  END;

  IF NOT v_is_participant THEN
    RAISE WARNING 'fn_search_messages: % not participant of %', p_user_id, p_conversation_id;
    RETURN '[]'::jsonb;
  END IF;

  v_query := '%' || lower(p_query) || '%';

  SELECT COALESCE(jsonb_agg(row_to_json(m)::jsonb ORDER BY m.created_at DESC), '[]'::jsonb) INTO v_result
  FROM (
    SELECT
      mm.id,
      mm.conversation_id,
      mm.sender_id,
      mm.text,
      mm.message_type,
      mm.created_at
    FROM public.messenger_messages mm
    WHERE mm.conversation_id = p_conversation_id
      AND COALESCE(mm.is_deleted, false) = false
      AND lower(COALESCE(mm.text, '')) LIKE v_query
    ORDER BY mm.created_at DESC
    LIMIT 100
  ) m;

  RETURN COALESCE(v_result, '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_search_messages failed (conv=%): % %', p_conversation_id, SQLERRM, SQLSTATE;
  RETURN '[]'::jsonb;
END;
$$;


ALTER FUNCTION public.fn_search_messages(p_conversation_id uuid, p_user_id uuid, p_query text) OWNER TO postgres;

--
-- Name: fn_search_players(text, integer, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_search_players(p_query text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_scope text DEFAULT 'all'::text, p_presence text DEFAULT 'all'::text, p_sort text DEFAULT 'relevance'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_query text := lower(btrim(coalesce(p_query, '')));
  v_like text;
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_fuzzy boolean;
  v_min_similarity real := 0.3;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF length(v_query) < 2 OR length(v_query) > 64 THEN
    RAISE EXCEPTION 'Search must be between 2 and 64 characters' USING ERRCODE = '22023';
  END IF;
  IF p_scope NOT IN ('all', 'friends', 'clubs', 'union', 'managed') THEN
    RAISE EXCEPTION 'Invalid search scope' USING ERRCODE = '22023';
  END IF;
  IF p_presence NOT IN ('all', 'online', 'playing') THEN
    RAISE EXCEPTION 'Invalid presence filter' USING ERRCODE = '22023';
  END IF;
  IF p_sort NOT IN ('relevance', 'name') THEN
    RAISE EXCEPTION 'Invalid search sort' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.club_entry_feature_flags f WHERE f.key = 'find_player'
      AND (NOT f.enabled OR ((hashtextextended(v_uid::text || ':' || f.key, 44119)
          & 9223372036854775807) % 100) >= f.rollout_percent)
  ) THEN
    RAISE EXCEPTION 'Player search is temporarily unavailable.' USING ERRCODE = 'P0001';
  END IF;

  v_like := replace(replace(replace(v_query, '\', '\\'), '%', '\%'), '_', '\_');

  v_fuzzy := length(v_query) >= 3;

  WITH RECURSIVE
  viewer_clubs AS MATERIALIZED (
    SELECT cm.club_id
      FROM public.club_members cm
     WHERE cm.user_id = v_uid AND cm.status IN ('active', 'approved')
  ), viewer_unions AS MATERIALIZED (
    SELECT DISTINCT uc.union_id
      FROM public.union_clubs uc JOIN viewer_clubs vc ON vc.club_id = uc.club_id
    UNION SELECT u.id FROM public.unions u WHERE u.owner_id = v_uid
    UNION SELECT ua.union_id FROM public.union_admins ua WHERE ua.user_id = v_uid
  ), friend_ids AS MATERIALIZED (
    SELECT f.friend_id AS user_id FROM public.friendships f WHERE f.user_id = v_uid
    UNION SELECT f.user_id FROM public.friendships f WHERE f.friend_id = v_uid
  ), viewer_seats AS MATERIALIZED (
    SELECT ts.table_id
      FROM public.table_seats ts
     WHERE ts.user_id = v_uid AND ts.left_at IS NULL
  ), matched AS MATERIALIZED (
    SELECT p.id, p.username, p.display_name,
           coalesce(nullif(p.arena_avatar_url, ''), p.avatar_url) AS avatar_url,
           CASE
             WHEN lower(coalesce(p.username, '')) = v_query THEN 0
             WHEN lower(coalesce(p.display_name, '')) = v_query THEN 1
             WHEN lower(coalesce(p.alias, '')) = v_query THEN 2
             WHEN coalesce(p.player_number, '') = v_query THEN 2
             WHEN lower(coalesce(p.username, '')) LIKE v_like || '%' ESCAPE '\' THEN 3
             WHEN lower(coalesce(p.display_name, '')) LIKE v_like || '%' ESCAPE '\' THEN 4
             WHEN lower(coalesce(p.username, '')) LIKE '%' || v_like || '%' ESCAPE '\'
               OR lower(coalesce(p.display_name, '')) LIKE '%' || v_like || '%' ESCAPE '\'
               OR lower(coalesce(p.alias, '')) LIKE '%' || v_like || '%' ESCAPE '\' THEN 5
             ELSE 6
           END AS relevance,
           greatest(
             similarity(lower(coalesce(p.username, '')), v_query),
             similarity(lower(coalesce(p.display_name, '')), v_query),
             similarity(lower(coalesce(p.alias, '')), v_query)
           ) AS match_score,
           coalesce(sp.discoverable, true) AS pref_discoverable,
           coalesce(sp.show_presence, true) AS pref_show_presence,
           coalesce(sp.show_current_table, true) AS pref_show_current_table,
           CASE
             WHEN p.id = v_uid THEN 'self'
             WHEN EXISTS (SELECT 1 FROM friend_ids f WHERE f.user_id = p.id) THEN 'friend'
             WHEN EXISTS (
               SELECT 1 FROM public.club_members target JOIN viewer_clubs vc ON vc.club_id = target.club_id
                WHERE target.user_id = p.id AND target.status IN ('active', 'approved')
             ) THEN 'club'
             WHEN EXISTS (
               SELECT 1 FROM public.club_members target
               JOIN public.union_clubs uc ON uc.club_id = target.club_id
               JOIN viewer_unions vu ON vu.union_id = uc.union_id
                WHERE target.user_id = p.id AND target.status IN ('active', 'approved')
             ) THEN 'union'
             ELSE 'public'
           END AS relationship
      FROM public.profiles p
      LEFT JOIN public.player_search_preferences sp ON sp.user_id = p.id
     WHERE lower(coalesce(p.username, '')) LIKE '%' || v_like || '%' ESCAPE '\'
        OR lower(coalesce(p.display_name, '')) LIKE '%' || v_like || '%' ESCAPE '\'
        OR lower(coalesce(p.alias, '')) LIKE '%' || v_like || '%' ESCAPE '\'
        OR coalesce(p.player_number, '') = v_query
        OR (v_fuzzy AND (
              (lower(p.username) % v_query
                AND similarity(lower(p.username), v_query) >= v_min_similarity)
           OR (lower(p.display_name) % v_query
                AND similarity(lower(p.display_name), v_query) >= v_min_similarity)
           OR (lower(p.alias) % v_query
                AND similarity(lower(p.alias), v_query) >= v_min_similarity)
        ))
  ), managed AS MATERIALIZED (
    SELECT DISTINCT m.id AS user_id
      FROM matched m
      JOIN public.club_members cm ON cm.user_id = m.id AND cm.status IN ('active', 'approved')
     WHERE m.id = v_uid
        OR public.ca_club_roster_access(cm.club_id, m.id) IN ('staff', 'downline', 'service')
  ), scoped AS MATERIALIZED (
    SELECT m.*,
           (m.id = v_uid OR EXISTS (SELECT 1 FROM managed x WHERE x.user_id = m.id))
             AS is_privileged
      FROM matched m
     WHERE (p_scope = 'all'
        OR (p_scope = 'friends' AND m.relationship IN ('self', 'friend'))
        OR (p_scope = 'clubs' AND m.relationship IN ('self', 'club'))
        OR (p_scope = 'union' AND m.relationship IN ('self', 'union'))
        OR (p_scope = 'managed' AND EXISTS (SELECT 1 FROM managed x WHERE x.user_id = m.id)))
       AND (m.pref_discoverable
            OR m.id = v_uid
            OR EXISTS (SELECT 1 FROM managed x WHERE x.user_id = m.id))
  ), presence_rows AS MATERIALIZED (
    SELECT s.*,
           (s.pref_show_presence OR s.is_privileged) AND (
             EXISTS (
               SELECT 1 FROM public.table_seats ts
               JOIN public.tables t ON t.id = ts.table_id
                WHERE ts.user_id = s.id AND ts.left_at IS NULL
                  AND t.status IN ('waiting', 'running') AND coalesce(t.is_deleted, false) = false
             ) OR EXISTS (
               SELECT 1 FROM public.tournament_players tp
               JOIN public.tournaments tr ON tr.id = tp.tournament_id
                WHERE tp.user_id = s.id AND tp.status = 'playing' AND tp.table_id IS NOT NULL
                  AND lower(coalesce(tr.status::text, '')) IN ('running', 'in_progress', 'active')
             )
           ) AS is_playing,
           (s.pref_show_presence OR s.is_privileged)
             AND coalesce(p.is_online, false)
             AND p.last_seen > now() - interval '5 minutes' AS is_online,
           (s.pref_show_current_table OR s.is_privileged) AS can_show_tables
      FROM scoped s JOIN public.profiles p ON p.id = s.id
  ), filtered AS MATERIALIZED (
    SELECT *, count(*) OVER () AS full_count
      FROM presence_rows
     WHERE p_presence = 'all'
        OR (p_presence = 'playing' AND is_playing)
        OR (p_presence = 'online' AND (is_playing OR is_online))
  ), page AS MATERIALIZED (
    SELECT * FROM filtered
     ORDER BY
       CASE WHEN p_sort = 'relevance' THEN relevance END,
       CASE WHEN p_sort = 'relevance' THEN -coalesce(match_score, 0) END,
       CASE WHEN p_sort = 'name' THEN lower(coalesce(display_name, username, '')) END,
       lower(coalesce(username, '')), id
     LIMIT v_limit OFFSET v_offset
  ), live_clubs AS MATERIALIZED (
    SELECT DISTINCT pg.id AS user_id, t.club_id
      FROM page pg
      JOIN public.table_seats ts ON ts.user_id = pg.id AND ts.left_at IS NULL
      JOIN public.tables t ON t.id = ts.table_id AND t.tournament_id IS NULL
     WHERE pg.can_show_tables
       AND t.status IN ('waiting', 'running')
       AND coalesce(t.is_deleted, false) = false
       AND coalesce(t.is_anonymous, false) = false
    UNION
    SELECT DISTINCT pg.id, tr.club_id
      FROM page pg
      JOIN public.tournament_players tp
        ON tp.user_id = pg.id AND tp.status = 'playing' AND tp.table_id IS NOT NULL
      JOIN public.tournaments tr ON tr.id = tp.tournament_id
      JOIN public.tables t ON t.id = tp.table_id
     WHERE pg.can_show_tables
       AND lower(coalesce(tr.status::text, '')) IN ('running', 'in_progress', 'active')
       AND coalesce(t.is_anonymous, false) = false
  ), decorated AS (
    SELECT pg.*,
      CASE WHEN pg.is_playing THEN 'playing' WHEN pg.is_online THEN 'online' ELSE 'offline' END
        AS presence_status,
      coalesce(g.games, '[]'::jsonb) AS tables,
      coalesce(a.accounts, '[]'::jsonb) AS sensitive_accounts,
      jsonb_build_object(
        'clubs', coalesce(af.clubs, '[]'::jsonb),
        'unions', coalesce(af.unions, '[]'::jsonb),
        'has_hidden', coalesce(af.has_hidden, false)
      ) AS affiliations
    FROM page pg
    LEFT JOIN LATERAL (
      SELECT jsonb_agg(game ORDER BY is_tournament, name, table_id) AS games
      FROM (
        SELECT DISTINCT ON (live.table_id) live.table_id,
          jsonb_build_object(
            'id', live.table_id,
            'table_id', live.table_id,
            'tournament_id', live.tournament_id,
            'name', live.name,
            'game_variant', live.game_variant,
            'stakes', live.stakes,
            'club_uuid', live.club_uuid,
            'club_id', live.club_number,
            'club_slug', live.club_slug,
            'club_name', live.club_name,
            'is_tournament', live.is_tournament,
            'membership_status', live.membership_status,
            'can_watch', live.viewer_seated OR live.can_watch,
            'access_action', CASE WHEN live.viewer_seated THEN 'play' ELSE live.access_action END
          ) AS game,
          live.is_tournament,
          live.name
        FROM (
          SELECT t.id AS table_id, NULL::uuid AS tournament_id, t.name::text,
                 coalesce(t.game_variant, t.game_type, 'Poker')::text AS game_variant,
                 concat('$', t.small_blind, '/$', t.big_blind)::text AS stakes,
                 c.id AS club_uuid, c.club_id AS club_number, c.slug AS club_slug,
                 c.name::text AS club_name, false AS is_tournament, cm.status AS membership_status,
                 EXISTS (SELECT 1 FROM viewer_seats vs WHERE vs.table_id = t.id) AS viewer_seated,
                 (cm.status IN ('active', 'approved') AND NOT coalesce(t.restrict_observers, false)) AS can_watch,
                 CASE
                   WHEN cm.status IN ('active', 'approved') AND coalesce(t.restrict_observers, false) THEN 'observers_restricted'
                   WHEN cm.status IN ('active', 'approved') THEN 'watch'
                   WHEN cm.status = 'pending' THEN 'pending'
                   WHEN cm.status IN ('banned', 'suspended', 'rejected', 'left') THEN 'unavailable'
                   WHEN coalesce(c.requires_approval, false) THEN 'request_join' ELSE 'join'
                 END AS access_action
            FROM public.table_seats ts
            JOIN public.tables t ON t.id = ts.table_id AND t.tournament_id IS NULL
            JOIN public.clubs c ON c.id = t.club_id
            LEFT JOIN public.club_members cm ON cm.club_id = c.id AND cm.user_id = v_uid
           WHERE ts.user_id = pg.id AND ts.left_at IS NULL AND pg.can_show_tables
             AND t.status IN ('waiting', 'running') AND coalesce(t.is_deleted, false) = false
             AND coalesce(t.is_anonymous, false) = false
          UNION ALL
          SELECT t.id, tr.id, coalesce(t.name, tr.name)::text,
                 coalesce(tr.variant, tr.game_type, 'MTT')::text,
                 concat('$', coalesce(tr.buy_in_amount, 0), ' Buy-In')::text,
                 c.id, c.club_id, c.slug, c.name::text, true, cm.status,
                 EXISTS (SELECT 1 FROM viewer_seats vs WHERE vs.table_id = t.id),
                 (cm.status IN ('active', 'approved') AND NOT coalesce(t.restrict_observers, false)),
                 CASE
                   WHEN cm.status IN ('active', 'approved') AND coalesce(t.restrict_observers, false) THEN 'observers_restricted'
                   WHEN cm.status IN ('active', 'approved') THEN 'watch'
                   WHEN cm.status = 'pending' THEN 'pending'
                   WHEN cm.status IN ('banned', 'suspended', 'rejected', 'left') THEN 'unavailable'
                   WHEN coalesce(c.requires_approval, false) THEN 'request_join' ELSE 'join'
                 END
            FROM public.tournament_players tp
            JOIN public.tournaments tr ON tr.id = tp.tournament_id
            JOIN public.tables t ON t.id = tp.table_id
            JOIN public.clubs c ON c.id = tr.club_id
            LEFT JOIN public.club_members cm ON cm.club_id = c.id AND cm.user_id = v_uid
           WHERE tp.user_id = pg.id AND tp.status = 'playing' AND tp.table_id IS NOT NULL
             AND pg.can_show_tables
             AND lower(coalesce(tr.status::text, '')) IN ('running', 'in_progress', 'active')
             AND coalesce(t.is_anonymous, false) = false
        ) live
        ORDER BY live.table_id, live.is_tournament DESC
      ) deduped
    ) g ON true
    LEFT JOIN LATERAL (
      SELECT jsonb_agg(jsonb_build_object(
        'club_uuid', details.club_id,
        'club_name', details.club_name,
        'role', details.role,
        'access', details.detail->'capabilities'->>'access',
        'wallets', details.detail->'wallets',
        'downline', details.detail->'downline',
        'stats', details.detail->'stats'
      ) ORDER BY details.club_name) AS accounts
      FROM (
        SELECT DISTINCT ON (cm.club_id) cm.club_id, c.name::text AS club_name, cm.role::text,
               public.ca_club_member_detail(cm.club_id, pg.id, NULL, NULL) AS detail
          FROM public.club_members cm JOIN public.clubs c ON c.id = cm.club_id
         WHERE cm.user_id = pg.id AND cm.status IN ('active', 'approved')
           AND (pg.id = v_uid OR public.ca_club_roster_access(cm.club_id, pg.id)
                IN ('staff', 'downline', 'service'))
         ORDER BY cm.club_id, public.fn_club_role_rank(cm.role) DESC
      ) details
      WHERE details.detail->'wallets' IS NOT NULL
    ) a ON true
    LEFT JOIN LATERAL (
      WITH club_rows AS (
        SELECT c.id AS club_uuid, c.club_id AS club_number, c.slug AS club_slug,
               c.name::text AS club_name, cm.role::text AS role,
               (coalesce(c.requires_approval, false)
                 OR coalesce(c.is_public, true) = false) AS is_gated,
               lower(coalesce(c.status, 'active')) = 'active' AS club_active,
               viewer.status AS viewer_status,
               (
                 pg.id = v_uid
                 OR NOT (coalesce(c.requires_approval, false)
                         OR coalesce(c.is_public, true) = false)
                 OR EXISTS (SELECT 1 FROM viewer_clubs vc WHERE vc.club_id = c.id)
                 OR EXISTS (
                   SELECT 1 FROM public.union_clubs uc
                   JOIN viewer_unions vu ON vu.union_id = uc.union_id
                    WHERE uc.club_id = c.id
                 )
                 OR EXISTS (
                   SELECT 1 FROM live_clubs lc
                    WHERE lc.user_id = pg.id AND lc.club_id = c.id
                 )
               ) AS visible
          FROM public.club_members cm
          JOIN public.clubs c ON c.id = cm.club_id
          LEFT JOIN public.club_members viewer
                 ON viewer.club_id = c.id AND viewer.user_id = v_uid
         WHERE cm.user_id = pg.id
           AND cm.status IN ('active', 'approved')
           AND lower(coalesce(c.status, 'active')) NOT IN ('deleted', 'archived')
      )
      SELECT
        (SELECT jsonb_agg(jsonb_build_object(
            'club_uuid', cr.club_uuid,
            'club_id', cr.club_number,
            'club_slug', cr.club_slug,
            'club_name', cr.club_name,
            'role', cr.role,
            'is_gated', cr.is_gated,
            'viewer_membership_status', cr.viewer_status,
            'viewer_action', CASE
              WHEN cr.viewer_status IN ('active', 'approved') THEN 'member'
              WHEN cr.viewer_status = 'pending' THEN 'pending'
              WHEN cr.viewer_status IN ('banned', 'suspended', 'rejected') THEN 'unavailable'
              WHEN NOT cr.club_active THEN 'unavailable'
              WHEN cr.is_gated THEN 'request_join'
              ELSE 'join'
            END
          ) ORDER BY cr.club_name)
           FROM club_rows cr WHERE cr.visible) AS clubs,
        (SELECT jsonb_agg(DISTINCT jsonb_build_object(
            'union_id', u.id,
            'union_name', u.name::text,
            'union_code', coalesce(u.union_code::text, u.code)
          ))
           FROM club_rows cr
           JOIN public.union_clubs uc ON uc.club_id = cr.club_uuid
           JOIN public.unions u ON u.id = uc.union_id
          WHERE cr.visible
            AND (coalesce(u.is_public, true)
                 OR EXISTS (SELECT 1 FROM viewer_unions vu WHERE vu.union_id = u.id))
        ) AS unions,
        EXISTS (SELECT 1 FROM club_rows cr WHERE NOT cr.visible) AS has_hidden
    ) af ON true
  )
  SELECT jsonb_build_object(
    'items', coalesce(jsonb_agg(jsonb_build_object(
      'id', id,
      'username', coalesce(username, ''),
      'display_name', display_name,
      'avatar_url', avatar_url,
      'relationship', CASE WHEN EXISTS (SELECT 1 FROM managed m WHERE m.user_id = id)
                           AND relationship = 'public' THEN 'managed' ELSE relationship END,
      'presence_status', presence_status,
      'match_score', round(coalesce(match_score, 0)::numeric, 3),
      'tables', tables,
      'affiliations', affiliations,
      'sensitive_accounts', sensitive_accounts
    )), '[]'::jsonb),
    'total', coalesce(max(full_count), 0),
    'limit', v_limit,
    'offset', v_offset,
    'fuzzy', v_fuzzy,
    'has_more', coalesce(max(full_count), 0) > v_offset + v_limit
  ) INTO v_result FROM decorated;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION public.fn_search_players(p_query text, p_limit integer, p_offset integer, p_scope text, p_presence text, p_sort text) OWNER TO postgres;

--
-- Name: FUNCTION fn_search_players(p_query text, p_limit integer, p_offset integer, p_scope text, p_presence text, p_sort text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_search_players(p_query text, p_limit integer, p_offset integer, p_scope text, p_presence text, p_sort text) IS 'Global safe player locator. Trigram fuzzy matching engages at three characters. Returns club/union affiliations under approval-gated disclosure rules, live cash and tournament seats with a membership-aware watch decision, honours player_search_preferences, and includes sensitive account contexts only where canonical club/union/downline authorization permits.';


--
-- Name: fn_seat_change_syncs_seat_first_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seat_change_syncs_seat_first_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_table_id uuid;
  v_tid uuid;
BEGIN
  v_table_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.table_id ELSE NEW.table_id END;
  IF v_table_id IS NULL THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  SELECT tournament_id INTO v_tid
    FROM public.tables
   WHERE id = v_table_id;
  IF v_tid IS NULL THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.tournaments t
     WHERE t.id = v_tid
       AND (lower(COALESCE(t.variant,'')) = 'spin'
            OR COALESCE(t.max_players,0) <= 2)
  ) THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  PERFORM public.fn_sync_seat_first_player_count(v_tid);
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.fn_seat_change_syncs_seat_first_count() OWNER TO postgres;

--
-- Name: FUNCTION fn_seat_change_syncs_seat_first_count(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_seat_change_syncs_seat_first_count() IS 'Strict canonical seat-first AFTER-seat hook. Count and paid-third-seat reserve booking succeed in the seat transaction or the seat mutation rolls back.';


--
-- Name: fn_seat_club_for_user(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seat_club_for_user(p_user_id uuid, p_table_id uuid, p_preferred_club uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_union uuid; v_table_club uuid;
BEGIN
  SELECT t.union_id, t.club_id INTO v_union, v_table_club
    FROM public.tables t WHERE t.id = p_table_id;
  IF v_union IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.club_members cm
       WHERE cm.user_id = p_user_id AND cm.club_id = v_table_club
         AND cm.status IN ('active','approved')
    ) THEN RETURN v_table_club; END IF;
    RETURN public.fn_player_home_club(p_user_id, p_preferred_club);
  END IF;
  RETURN public.fn_seat_club_for_user_membership_unchecked(
    p_user_id, p_table_id, p_preferred_club
  );
END;
$$;


ALTER FUNCTION public.fn_seat_club_for_user(p_user_id uuid, p_table_id uuid, p_preferred_club uuid) OWNER TO postgres;

--
-- Name: fn_seat_club_for_user_membership_unchecked(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seat_club_for_user_membership_unchecked(p_user_id uuid, p_table_id uuid, p_preferred_club uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_union uuid; v_table_club uuid; v_club uuid;
  v_is_horse boolean := false; v_n int; v_idx int;
BEGIN
  SELECT t.union_id, t.club_id INTO v_union, v_table_club
    FROM tables t WHERE t.id = p_table_id;

  IF v_union IS NULL THEN
    RETURN v_table_club;                       -- standalone club game
  END IF;

  -- ONE CLUB AT A TIME (Dan 2026-08-21). If this player is already sitting
  -- somewhere in this union, the club they are already representing wins -
  -- over the preferred club, over the hash, over membership order. Everything
  -- below only decides where a player who is NOT currently seated starts.
  SELECT ts.club_id INTO v_club
    FROM table_seats ts
    JOIN tables t2 ON t2.id = ts.table_id
   WHERE ts.user_id = p_user_id
     AND ts.left_at IS NULL
     AND ts.club_id IS NOT NULL
     AND t2.union_id = v_union
     AND lower(coalesce(t2.status, '')) NOT IN ('closed','completed','cancelled','finished')
   ORDER BY ts.joined_at ASC NULLS LAST
   LIMIT 1;
  IF v_club IS NOT NULL THEN
    RETURN v_club;
  END IF;

  -- Honour the club the player entered through, when they really are a member.
  IF p_preferred_club IS NOT NULL
     AND EXISTS (SELECT 1 FROM club_members m
                  JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
                 WHERE m.user_id = p_user_id AND m.club_id = p_preferred_club
                   AND m.status IN ('active','approved'))
  THEN
    RETURN p_preferred_club;
  END IF;

  SELECT COALESCE(p.is_horse, false) INTO v_is_horse FROM profiles p WHERE p.id = p_user_id;

  IF v_is_horse THEN
    -- Stable home club for a simulated player that is not currently seated:
    -- deterministic from its own id, so horses spread across the union's clubs
    -- instead of all piling into the oldest one.
    SELECT count(*) INTO v_n
      FROM club_members m
      JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
     WHERE m.user_id = p_user_id AND m.status IN ('active','approved');

    IF v_n > 1 THEN
      v_idx := (abs(hashtextextended(p_user_id::text, 0)) % v_n)::int;
      SELECT m.club_id INTO v_club
        FROM club_members m
        JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
       WHERE m.user_id = p_user_id AND m.status IN ('active','approved')
       ORDER BY m.club_id
       OFFSET v_idx LIMIT 1;
      IF v_club IS NOT NULL THEN RETURN v_club; END IF;
    END IF;
  END IF;

  -- Real players: oldest membership.
  SELECT m.club_id INTO v_club
    FROM club_members m
    JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
   WHERE m.user_id = p_user_id AND m.status IN ('active','approved')
   ORDER BY m.joined_at ASC NULLS LAST, m.club_id
   LIMIT 1;

  RETURN v_club;
END $$;


ALTER FUNCTION public.fn_seat_club_for_user_membership_unchecked(p_user_id uuid, p_table_id uuid, p_preferred_club uuid) OWNER TO postgres;

--
-- Name: fn_seat_first_boards_ready(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seat_first_boards_ready() RETURNS TABLE(id uuid, name text, max_players integer, variant text, start_time timestamp with time zone, paid_seats integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT t.id, t.name, t.max_players, t.variant, t.start_time,
         COALESCE(s.paid, 0)::int AS paid_seats
  FROM public.tournaments t
  LEFT JOIN LATERAL (
    SELECT count(*) AS paid
    FROM public.tables tb
    JOIN public.table_seats ts
      ON ts.table_id = tb.id AND ts.left_at IS NULL
    WHERE tb.tournament_id = t.id
      AND tb.status <> 'closed'
  ) s ON true
  WHERE t.status = 'REGISTERING'
    AND (t.variant = 'spin' OR (t.variant = 'sng' AND t.max_players <= 2));
$$;


ALTER FUNCTION public.fn_seat_first_boards_ready() OWNER TO postgres;

--
-- Name: FUNCTION fn_seat_first_boards_ready(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_seat_first_boards_ready() IS 'Which seat-first boards have all their seats paid for, in ONE call. Replaces three sequential PostgREST round trips in GameServer.discoverSeatFirstStarts that measured 5.448 s per pass against 76 ms here, which is why a Spin that filled took eleven to twenty-four seconds to reach its wheel.';


--
-- Name: fn_seat_horse_in_seat_first_game(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seat_horse_in_seat_first_game(p_tournament_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_gate jsonb;
BEGIN
  v_gate:=public.fn_ca_lock_tournament_seat_acquisition(
    p_tournament_id,NULL,p_user_id);
  IF COALESCE((v_gate->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_gate;
  END IF;
  RETURN public.fn_seat_horse_in_seat_first_game_before_terminal_seat_gate(
    p_tournament_id,p_user_id);
END;
$$;


ALTER FUNCTION public.fn_seat_horse_in_seat_first_game(p_tournament_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_seat_horse_in_seat_first_game_before_maintenance_gate(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seat_horse_in_seat_first_game_before_maintenance_gate(p_tournament_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t       record;
  v_table   record;
  v_seat    int;
  v_reg     jsonb;
  v_taken   int;
  v_already boolean;
  v_seated  int;
  v_stack   numeric;
BEGIN
  PERFORM set_config('app.money_path', 'fn_seat_horse_in_seat_first_game', true); -- CHIP STANDARD C2: sanctioned seat creator (trg_ca_guard_seat_creation)

  /* THE PLAYER'S MISSIONS LOCK BEFORE THE GAME ROW (20260906). Seating ends
     with UPDATE tournament_players ... status = 'playing', whose statement
     trigger fn_daily_missions_tournament_registered_updated takes the
     per-player advisory lock 'daily-missions-user:<id>' and the player's
     profiles row. A hand this horse is playing elsewhere writes hand_history
     at the same moment and its trigger takes that same lock FIRST, then waits
     on a row this function holds. Rows-then-lock here, lock-then-rows there:
     12 deadlocks a day, and the victim on the other side was the hand
     record. Take the lock first, in the same order as the hand path; the
     trigger re-takes it later at no cost (advisory xact locks re-enter). */
  PERFORM public.fn_lock_daily_mission_user(p_user_id);

  SELECT id, status, variant, max_players, starting_chips, name
    INTO v_t FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
  END IF;

  IF NOT (COALESCE(v_t.variant,'') = 'spin' OR COALESCE(v_t.max_players,0) <= 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_seat_first_game');
  END IF;

  -- Identical to the human seat. See CLAUDE.md 10.5.
  v_stack := COALESCE(v_t.starting_chips, 0);

  SELECT id, max_players INTO v_table
    FROM public.tables
   WHERE id = public.fn_tournament_primary_table(p_tournament_id);
  IF v_table.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_table');
  END IF;

  IF EXISTS (SELECT 1 FROM public.table_seats
              WHERE table_id = v_table.id AND user_id = p_user_id AND left_at IS NULL) THEN
    RETURN jsonb_build_object('ok', true, 'already_seated', true);
  END IF;

  SELECT s INTO v_seat
    FROM generate_series(1, COALESCE(NULLIF(v_table.max_players,0), v_t.max_players, 3)) s
   WHERE NOT EXISTS (
     SELECT 1 FROM public.table_seats ts
      WHERE ts.table_id = v_table.id AND ts.seat_number = s AND ts.left_at IS NULL
   )
   ORDER BY s LIMIT 1;

  IF v_seat IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_full');
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.tournament_players
                  WHERE tournament_id = p_tournament_id AND user_id = p_user_id)
    INTO v_already;

  IF NOT v_already THEN
    v_reg := public.fn_register_horse_for_tournament(p_tournament_id, p_user_id);
    IF COALESCE((v_reg->>'ok')::boolean, false) IS NOT TRUE
       AND COALESCE(v_reg->>'reason','') <> 'already_registered' THEN
      RETURN jsonb_build_object('ok', false, 'reason', COALESCE(v_reg->>'reason','register_failed'));
    END IF;
  END IF;

  UPDATE public.table_seats
     SET user_id   = p_user_id,
         left_at   = NULL,
         stack     = v_stack,
         joined_at = now()
   WHERE table_id = v_table.id
     AND seat_number = v_seat
     AND left_at IS NOT NULL;
  GET DIAGNOSTICS v_seated = ROW_COUNT;

  IF v_seated = 0 THEN
    BEGIN
      INSERT INTO public.table_seats (table_id, user_id, seat_number, stack)
      VALUES (v_table.id, p_user_id, v_seat, v_stack);
    EXCEPTION WHEN unique_violation THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'seat_taken');
    END;
  END IF;

  UPDATE public.tournament_players
     SET status = 'playing', chips = v_stack, table_id = v_table.id, seat_number = v_seat
   WHERE tournament_id = p_tournament_id AND user_id = p_user_id;

  v_taken := COALESCE(public.fn_sync_seat_first_player_count(p_tournament_id), 0);

  RETURN jsonb_build_object('ok', true, 'table_id', v_table.id, 'seat_number', v_seat,
    'stack', v_stack,
    'seats_taken', v_taken, 'reused_registration', v_already, 'reused_seat', v_seated > 0,
    'seats', COALESCE(NULLIF(v_table.max_players,0), v_t.max_players, 3));
END;
$$;


ALTER FUNCTION public.fn_seat_horse_in_seat_first_game_before_maintenance_gate(p_tournament_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_seat_horse_in_seat_first_game_before_maintenance_gate(p_tournament_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_seat_horse_in_seat_first_game_before_maintenance_gate(p_tournament_id uuid, p_user_id uuid) IS 'Puts a horse in an actual SEAT of a Spin or heads-up table, not just on the registration list. fn_register_horse_for_tournament only writes tournament_players, and a seat-first game starts when every SEAT is sold - so a topped-up Spin looked full on paper, showed three empty seats, could never start, and sold a fourth entry to the next human who sat down.';


--
-- Name: fn_seat_horse_in_seat_first_game_before_terminal_seat_gate(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seat_horse_in_seat_first_game_before_terminal_seat_gate(p_tournament_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'platform_frozen');
  END IF;
  RETURN public.fn_seat_horse_in_seat_first_game_before_maintenance_gate(
    p_tournament_id, p_user_id
  );
END;
$$;


ALTER FUNCTION public.fn_seat_horse_in_seat_first_game_before_terminal_seat_gate(p_tournament_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_seat_insert_cancel_waitlist(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seat_insert_cancel_waitlist() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.table_waitlist
     SET status = 'seated'
   WHERE table_id = NEW.table_id
     AND user_id  = NEW.user_id
     AND status IN ('waiting', 'notified');
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_seat_insert_cancel_waitlist() OWNER TO postgres;

--
-- Name: fn_seat_late_registrant(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seat_late_registrant(p_tournament_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_gate jsonb;
BEGIN
  v_gate:=public.fn_ca_lock_tournament_seat_acquisition(
    p_tournament_id,NULL,p_user_id);
  IF COALESCE((v_gate->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_gate;
  END IF;
  RETURN public.fn_seat_late_registrant_before_terminal_seat_gate(
    p_tournament_id,p_user_id);
END;
$$;


ALTER FUNCTION public.fn_seat_late_registrant(p_tournament_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_seat_late_registrant_before_maintenance_gate(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seat_late_registrant_before_maintenance_gate(p_tournament_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_start_chips integer;
  v_club uuid;
  v_bonus integer;
  v_chips integer;
  v_table uuid;
  v_cap integer;
  v_seat integer;
  v_taken integer;
  v_opened boolean:=false;
  v_sb numeric;
  v_bb numeric;
  v_bs varchar;
  v_tclub uuid;
  v_tno integer;
BEGIN
  PERFORM set_config('app.money_path','fn_seat_late_registrant',true);
  SELECT status,COALESCE(starting_chips,0),club_id
    INTO v_status,v_start_chips,v_club
    FROM public.tournaments WHERE id=p_tournament_id;

  IF v_status IS DISTINCT FROM 'RUNNING' THEN
    RETURN jsonb_build_object('ok',false,'reason','not_running');
  END IF;

  SELECT COALESCE(chips,0) INTO v_bonus
    FROM public.tournament_players
   WHERE tournament_id=p_tournament_id
     AND user_id=p_user_id
     AND table_id IS NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.table_seats s
       JOIN public.tables tb ON tb.id=s.table_id
        WHERE tb.tournament_id=p_tournament_id
          AND s.user_id=p_user_id AND s.left_at IS NULL)
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','already_seated_or_missing');
  END IF;

  v_chips:=v_start_chips+GREATEST(v_bonus,0);

  SELECT tb.id,COALESCE(tb.max_players,9)
    INTO v_table,v_cap
    FROM public.tables tb
   WHERE tb.tournament_id=p_tournament_id
     AND lower(COALESCE(tb.status,'')) IN ('waiting','running','active')
     AND (SELECT count(*) FROM public.table_seats s
           WHERE s.table_id=tb.id AND s.left_at IS NULL)
         <COALESCE(tb.max_players,9)
   ORDER BY (SELECT count(*) FROM public.table_seats s
              WHERE s.table_id=tb.id AND s.left_at IS NULL) DESC,
            tb.created_at ASC
   LIMIT 1
   FOR UPDATE OF tb;

  IF v_table IS NULL THEN
    SELECT COALESCE(tb.max_players,9),tb.small_blind,tb.big_blind,
           tb.blind_structure,COALESCE(tb.club_id,v_club)
      INTO v_cap,v_sb,v_bb,v_bs,v_tclub
      FROM public.tables tb
     WHERE tb.tournament_id=p_tournament_id
     ORDER BY tb.created_at DESC
     LIMIT 1;

    IF NOT FOUND THEN
      SELECT COALESCE(t.table_size,9) INTO v_cap
        FROM public.tournaments t WHERE t.id=p_tournament_id;
      v_sb:=1;
      v_bb:=2;
      v_bs:='standard';
      v_tclub:=v_club;
    END IF;

    IF v_sb IS NULL OR v_bb IS NULL OR v_sb<=0 OR v_bb<v_sb THEN
      RAISE EXCEPTION 'late-registration table has invalid blind authority'
        USING ERRCODE='P0404';
    END IF;

    SELECT count(*)+1 INTO v_tno
      FROM public.tables WHERE tournament_id=p_tournament_id;

    INSERT INTO public.tables(
      name,tournament_id,club_id,max_players,small_blind,big_blind,
      stakes,blind_structure,status,current_players)
    VALUES(
      'Table '||v_tno,p_tournament_id,v_tclub,v_cap,v_sb,v_bb,
      trim_scale(v_sb)::text||'/'||trim_scale(v_bb)::text,
      COALESCE(v_bs,'standard'),'waiting',0)
    RETURNING id INTO v_table;
    v_opened:=true;
  END IF;

  SELECT g.n INTO v_seat
    FROM generate_series(1,v_cap) AS g(n)
   WHERE NOT EXISTS (
     SELECT 1 FROM public.table_seats s
      WHERE s.table_id=v_table AND s.seat_number=g.n
        AND s.left_at IS NULL)
   ORDER BY g.n LIMIT 1;

  IF v_seat IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','no_open_seat');
  END IF;

  UPDATE public.table_seats
     SET user_id=p_user_id,stack=v_chips,left_at=NULL,joined_at=now(),
         is_sitting_out=false,is_away=false,
         club_id=COALESCE(club_id,v_club)
   WHERE table_id=v_table AND seat_number=v_seat AND left_at IS NOT NULL;

  IF NOT FOUND THEN
    BEGIN
      INSERT INTO public.table_seats(
        table_id,user_id,seat_number,stack,club_id)
      VALUES(v_table,p_user_id,v_seat,v_chips,v_club);
    EXCEPTION WHEN unique_violation THEN
      RETURN jsonb_build_object('ok',false,'reason','seat_race');
    END;
  END IF;

  UPDATE public.tournament_players
     SET status='playing',chips=v_chips,table_id=v_table,
         seat_number=v_seat
   WHERE tournament_id=p_tournament_id AND user_id=p_user_id;

  SELECT count(*) INTO v_taken
    FROM public.table_seats
   WHERE table_id=v_table AND left_at IS NULL;
  UPDATE public.tables SET current_players=v_taken WHERE id=v_table;

  RETURN jsonb_build_object(
    'ok',true,'table_id',v_table,'seat_number',v_seat,'chips',v_chips,
    'opened_table',v_opened);
END;
$$;


