--
-- Name: fn_seed_horses_to_floor(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seed_horses_to_floor(p_club_id uuid, p_floor numeric) RETURNS TABLE(horses_funded integer, chips_moved numeric, treasury_after numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_needed  numeric;
    v_count   integer;
    v_before  numeric;
    v_after   numeric;
BEGIN
    IF p_floor IS NULL OR p_floor <= 0 THEN
        RAISE EXCEPTION 'floor must be positive, got %', p_floor;
    END IF;

    SELECT coalesce(chip_treasury, 0) INTO v_before FROM public.clubs WHERE id = p_club_id;
    IF v_before IS NULL THEN
        RAISE EXCEPTION 'club % not found', p_club_id;
    END IF;

    SELECT count(*), coalesce(sum(p_floor - cm.chip_balance), 0)
      INTO v_count, v_needed
      FROM public.club_members cm
      JOIN public.profiles p ON p.id = cm.user_id
     WHERE cm.club_id = p_club_id AND p.is_horse AND cm.chip_balance < p_floor;

    IF v_count = 0 THEN
        RETURN QUERY SELECT 0, 0::numeric, v_before;
        RETURN;
    END IF;

    -- All or nothing. A half-seeded roster is harder to reason about than an
    -- unseeded one, and the caller can always mint first and retry.
    IF v_before < v_needed THEN
        RAISE EXCEPTION 'treasury % cannot cover % for % horses (floor %) - mint first',
              v_before, v_needed, v_count, p_floor;
    END IF;

    INSERT INTO public.chip_transactions
        (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after)
    SELECT p_club_id, NULL, cm.user_id, p_floor - cm.chip_balance, 'horse_treasury_funding',
           'Topped up to the club bankroll floor so the horse can buy into any table',
           p_floor
      FROM public.club_members cm
      JOIN public.profiles p ON p.id = cm.user_id
     WHERE cm.club_id = p_club_id AND p.is_horse AND cm.chip_balance < p_floor;

    UPDATE public.club_members cm
       SET chip_balance = p_floor
      FROM public.profiles p
     WHERE p.id = cm.user_id
       AND cm.club_id = p_club_id AND p.is_horse AND cm.chip_balance < p_floor;

    UPDATE public.clubs SET chip_treasury = chip_treasury - v_needed WHERE id = p_club_id
    RETURNING chip_treasury INTO v_after;

    IF v_after < 0 THEN
        RAISE EXCEPTION 'post-apply failed: treasury went negative (%)', v_after;
    END IF;
    IF (v_before - v_after) <> v_needed THEN
        RAISE EXCEPTION 'post-apply failed: conservation broken - treasury moved %, credited %',
              (v_before - v_after), v_needed;
    END IF;

    RETURN QUERY SELECT v_count, v_needed, v_after;
END;
$$;


ALTER FUNCTION public.fn_seed_horses_to_floor(p_club_id uuid, p_floor numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_seed_horses_to_floor(p_club_id uuid, p_floor numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_seed_horses_to_floor(p_club_id uuid, p_floor numeric) IS 'Tops every horse in a club up to a bankroll floor, moving chips from the club treasury. Never reduces a horse already above the floor. Refuses to run if the treasury cannot cover the whole batch.';


--
-- Name: fn_seed_new_club_opening_bank(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seed_new_club_opening_bank() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF COALESCE(NEW.is_union, false) THEN
    RETURN NEW;
  END IF;

  -- THE OPENING GRANT IS DENOMINATED IN CHIPS. Handing it to a club that plays in another asset
  -- would create a hundred thousand chips inside it, register them against the chip supply, and
  -- put a diamond club in the chip trial balance - none of it asked for by anyone. The platform
  -- club is funded by fn_ca_mint(diamonds, destination = house) instead (standard 3.2).
  IF COALESCE(NEW.asset, 'chips') <> 'chips' THEN
    RETURN NEW;
  END IF;

  -- THE MINT (2026-09-03): the opening grant is issued from the same account
  -- fn_ca_mint issues from, so the journal row reads
  -- issuance_reserve -> club_treasury, category mint, like every other mint.
  NEW.chip_treasury := 100000;
  PERFORM public.fn_ca_declare_ledger(
    'mint', 'issuance_reserve', NULL, NULL,
    'club-opening-grant:' || NEW.id::text);
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_seed_new_club_opening_bank() OWNER TO postgres;

--
-- Name: FUNCTION fn_seed_new_club_opening_bank(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_seed_new_club_opening_bank() IS 'Sets each new standalone Club Bank to 100,000 and labels its canonical chip-ledger source as system_mint.';


--
-- Name: fn_seed_table_studio_preferences(text[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_seed_table_studio_preferences(p_favorites text[], p_loadouts jsonb) RETURNS TABLE(favorites text[], loadouts jsonb, revision bigint, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_favorites text[] := COALESCE(p_favorites, '{}'::text[]);
  v_loadouts jsonb := COALESCE(p_loadouts, '[null,null,null]'::jsonb);
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF cardinality(v_favorites) > 100 OR EXISTS (
    SELECT 1 FROM unnest(v_favorites) AS item
     WHERE item IS NULL OR btrim(item) = '' OR length(item) > 200
  ) THEN
    RAISE EXCEPTION 'Invalid Table Studio favorites' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_loadouts) <> 'array' OR jsonb_array_length(v_loadouts) <> 3 THEN
    RAISE EXCEPTION 'Invalid Table Studio loadouts' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.user_table_studio_preferences (user_id, favorites, loadouts)
  VALUES (v_user_id, v_favorites, v_loadouts)
  ON CONFLICT (user_id) DO NOTHING;

  RETURN QUERY
  SELECT p.favorites, p.loadouts, p.revision, p.updated_at
    FROM public.user_table_studio_preferences p
   WHERE p.user_id = v_user_id;
END;
$$;


ALTER FUNCTION public.fn_seed_table_studio_preferences(p_favorites text[], p_loadouts jsonb) OWNER TO postgres;

--
-- Name: fn_send_home_game_reminders(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_send_home_game_reminders() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_6h_sent int := 0;
    v_1h_sent int := 0;
    v_rsvp    RECORD;
    v_slug    text;
BEGIN
    -- 6-hour reminders: games starting in ~5h45min to ~6h15min from now
    FOR v_rsvp IN
        SELECT 
            r.id AS rsvp_id, r.user_id, r.game_id,
            g.group_id, g.title AS game_title, g.scheduled_date, g.start_time, g.address,
            grp.name AS group_name
          FROM commander_home_rsvps r
          JOIN commander_home_games g ON g.id = r.game_id
          JOIN commander_home_groups grp ON grp.id = g.group_id
         WHERE r.response = 'yes'
           AND r.reminder_6h_sent_at IS NULL
           AND g.status IN ('scheduled','confirmed')
           -- scheduled_datetime between 5h45m and 6h15m from now
           AND (g.scheduled_date + COALESCE(g.start_time, TIME '19:00')) 
               BETWEEN NOW() + INTERVAL '5 hours 45 minutes'
                   AND NOW() + INTERVAL '6 hours 15 minutes'
    LOOP
        SELECT sp.slug INTO v_slug FROM social_pages sp
         WHERE sp.linked_entity_type = 'home_group' AND sp.linked_entity_id = v_rsvp.group_id::text
         LIMIT 1;

        PERFORM public.fn_emit_home_notification(
            v_rsvp.user_id,
            'home_game_reminder_6h',
            COALESCE(v_rsvp.game_title, v_rsvp.group_name) || ' - tonight in 6 hours',
            'See you at ' || COALESCE(v_rsvp.start_time::text, '') || 
                CASE WHEN v_rsvp.address IS NOT NULL 
                     THEN ' - ' || v_rsvp.address ELSE '' END,
            '/hub/home-games/' || COALESCE(v_slug, v_rsvp.group_id::text),
            jsonb_build_object('game_id', v_rsvp.game_id, 'window', '6h'),
            'home_game_reminders'
        );

        UPDATE commander_home_rsvps 
           SET reminder_6h_sent_at = NOW()
         WHERE id = v_rsvp.rsvp_id;

        v_6h_sent := v_6h_sent + 1;
    END LOOP;

    -- 1-hour reminders: games starting in ~45min to ~75min from now
    FOR v_rsvp IN
        SELECT 
            r.id AS rsvp_id, r.user_id, r.game_id,
            g.group_id, g.title AS game_title, g.scheduled_date, g.start_time, g.address,
            grp.name AS group_name
          FROM commander_home_rsvps r
          JOIN commander_home_games g ON g.id = r.game_id
          JOIN commander_home_groups grp ON grp.id = g.group_id
         WHERE r.response = 'yes'
           AND r.reminder_1h_sent_at IS NULL
           AND g.status IN ('scheduled','confirmed')
           AND (g.scheduled_date + COALESCE(g.start_time, TIME '19:00')) 
               BETWEEN NOW() + INTERVAL '45 minutes'
                   AND NOW() + INTERVAL '75 minutes'
    LOOP
        SELECT sp.slug INTO v_slug FROM social_pages sp
         WHERE sp.linked_entity_type = 'home_group' AND sp.linked_entity_id = v_rsvp.group_id::text
         LIMIT 1;

        PERFORM public.fn_emit_home_notification(
            v_rsvp.user_id,
            'home_game_reminder_1h',
            'Starting in 1 hour - ' || COALESCE(v_rsvp.game_title, v_rsvp.group_name),
            'Head out soon. ' || COALESCE(v_rsvp.start_time::text, 'tonight'),
            '/hub/home-games/' || COALESCE(v_slug, v_rsvp.group_id::text),
            jsonb_build_object('game_id', v_rsvp.game_id, 'window', '1h'),
            'home_game_reminders'
        );

        UPDATE commander_home_rsvps 
           SET reminder_1h_sent_at = NOW()
         WHERE id = v_rsvp.rsvp_id;

        v_1h_sent := v_1h_sent + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'sent_6h', v_6h_sent,
        'sent_1h', v_1h_sent,
        'run_at', NOW()
    );
END;
$$;


ALTER FUNCTION public.fn_send_home_game_reminders() OWNER TO postgres;

--
-- Name: fn_send_message(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_send_message(p_conversation_id uuid, p_sender_id uuid, p_content text, p_message_type text DEFAULT 'text'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_message_id uuid;
    v_is_participant boolean;
BEGIN
    -- Verify sender is a participant (belt-and-suspenders, send-message API already checks)
    SELECT EXISTS (
        SELECT 1 FROM public.social_conversation_participants
        WHERE conversation_id = p_conversation_id AND user_id = p_sender_id
    ) INTO v_is_participant;

    IF NOT v_is_participant THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_a_participant');
    END IF;

    -- Insert message with metadata
    INSERT INTO public.social_messages (
        conversation_id,
        sender_id,
        content,
        message_type,
        media_metadata
    ) VALUES (
        p_conversation_id,
        p_sender_id,
        p_content,
        COALESCE(NULLIF(p_message_type, ''), 'text'),
        CASE WHEN p_metadata = '{}'::jsonb OR p_metadata IS NULL THEN NULL ELSE p_metadata END
    )
    RETURNING id INTO v_message_id;

    -- Update conversation last message preview
    UPDATE public.social_conversations
    SET
        last_message_at      = now(),
        last_message_preview = CASE
            WHEN p_message_type = 'shared_post' THEN
                COALESCE((p_metadata->>'preview_title'), 'Shared Post')
            ELSE
                left(p_content, 100)
        END,
        updated_at = now()
    WHERE id = p_conversation_id;

    RETURN jsonb_build_object(
        'success',         true,
        'message_id',      v_message_id,
        'conversation_id', p_conversation_id
    );
END;
$$;


ALTER FUNCTION public.fn_send_message(p_conversation_id uuid, p_sender_id uuid, p_content text, p_message_type text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: fn_sentry_budget_take(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sentry_budget_take(p_fingerprint text, p_daily_limit integer DEFAULT 60, p_fingerprint_limit integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_day      date := (now() AT TIME ZONE 'utc')::date;
    v_fp       text := COALESCE(NULLIF(left(p_fingerprint, 200), ''), 'unknown');
    v_fp_sent  integer;
    v_sent     integer;
BEGIN
    DELETE FROM public.sentry_event_budget       WHERE day < v_day - 14;
    DELETE FROM public.sentry_event_fingerprints WHERE day < v_day - 14;

    INSERT INTO public.sentry_event_budget (day, sent)
        VALUES (v_day, 0) ON CONFLICT (day) DO NOTHING;
    INSERT INTO public.sentry_event_fingerprints (day, fingerprint, sent)
        VALUES (v_day, v_fp, 0) ON CONFLICT (day, fingerprint) DO NOTHING;

    UPDATE public.sentry_event_fingerprints
       SET sent = sent + 1
     WHERE day = v_day AND fingerprint = v_fp AND sent < p_fingerprint_limit
    RETURNING sent INTO v_fp_sent;

    IF v_fp_sent IS NULL THEN
        SELECT sent INTO v_fp_sent FROM public.sentry_event_fingerprints
         WHERE day = v_day AND fingerprint = v_fp;
        SELECT sent INTO v_sent FROM public.sentry_event_budget WHERE day = v_day;
        RETURN jsonb_build_object(
            'allowed', false, 'reason', 'fingerprint_cap',
            'sent', COALESCE(v_sent, 0), 'fingerprint_sent', COALESCE(v_fp_sent, 0));
    END IF;

    UPDATE public.sentry_event_budget
       SET sent = sent + 1
     WHERE day = v_day AND sent < p_daily_limit
    RETURNING sent INTO v_sent;

    IF v_sent IS NULL THEN
        UPDATE public.sentry_event_fingerprints
           SET sent = GREATEST(sent - 1, 0)
         WHERE day = v_day AND fingerprint = v_fp;
        SELECT sent INTO v_sent FROM public.sentry_event_budget WHERE day = v_day;
        RETURN jsonb_build_object(
            'allowed', false, 'reason', 'daily_budget',
            'sent', COALESCE(v_sent, 0), 'fingerprint_sent', GREATEST(v_fp_sent - 1, 0));
    END IF;

    RETURN jsonb_build_object(
        'allowed', true, 'reason', 'ok',
        'sent', v_sent, 'fingerprint_sent', v_fp_sent);
END;
$$;


ALTER FUNCTION public.fn_sentry_budget_take(p_fingerprint text, p_daily_limit integer, p_fingerprint_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_sentry_budget_take(p_fingerprint text, p_daily_limit integer, p_fingerprint_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sentry_budget_take(p_fingerprint text, p_daily_limit integer, p_fingerprint_limit integer) IS 'Take one Sentry event token for today (UTC). Per-fingerprint cap checked first, then the global daily bucket. Returns {allowed, reason, sent, fingerprint_sent}. service_role only.';


--
-- Name: fn_serialize_engine_maintenance_break_write(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_serialize_engine_maintenance_break_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  /* PostgreSQL takes ACCESS EXCLUSIVE before firing a TRUNCATE trigger. Waiting
     for the advisory boundary from there would invert the canonical order
     against an admitted entry that next reads this table. This singleton has
     no legitimate truncate path, so refuse immediately instead of deadlocking. */
  IF TG_OP = 'TRUNCATE' THEN
    RAISE EXCEPTION 'engine_maintenance_break may not be truncated'
      USING ERRCODE = '0A000';
  END IF;
  /* One exclusive writer boundary. The matching entry paths take this key in
     shared mode, so purchases stay concurrent with each other but can never
     straddle a maintenance-row commit. Transaction scope prevents a pooled
     connection from retaining the lock. */
  PERFORM pg_advisory_xact_lock(530090, 1);
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_serialize_engine_maintenance_break_write() OWNER TO postgres;

--
-- Name: fn_serialize_entry_statement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_serialize_entry_statement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  /* This is a backstop for a direct/unwrapped INSERT. A canonical RPC already
     owns the shared lock before touching any rows. An unexpected outer caller
     may already own unrelated rows, so waiting behind a queued maintenance
     writer here could form a soft deadlock. Fail the whole statement
     immediately and transactionally instead; the caller may retry from its
     outer boundary. */
  IF NOT pg_try_advisory_xact_lock_shared(530090, 1) THEN
    RAISE EXCEPTION
      'ENTRY_BOUNDARY_BUSY: maintenance announcement owns the entry boundary'
      USING ERRCODE = '40001';
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_serialize_entry_statement() OWNER TO postgres;

--
-- Name: fn_set_age_verified(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_set_age_verified(p_user_id uuid, p_jurisdiction_country text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required';
  END IF;

  UPDATE public.profiles
     SET age_verified = true,
         age_verified_at = COALESCE(age_verified_at, now()),
         jurisdiction_country = COALESCE(p_jurisdiction_country, jurisdiction_country, country)
   WHERE id = p_user_id;

  INSERT INTO public.kyc_events (user_id, event_type, source, payload)
  VALUES (p_user_id, 'age_gate_passed', 'user_action',
          jsonb_build_object('jurisdiction_country', p_jurisdiction_country));

  RETURN jsonb_build_object('ok', true, 'age_verified', true);
END;
$$;


ALTER FUNCTION public.fn_set_age_verified(p_user_id uuid, p_jurisdiction_country text) OWNER TO postgres;

--
-- Name: fn_set_club_lobby_message(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_set_club_lobby_message(p_club_id uuid, p_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_clean    text;
  v_revision bigint;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  -- FOR UPDATE so a concurrent identity save cannot interleave between the
  -- authorisation read and the write, which is the same lock the versioned
  -- writer takes.
  PERFORM 1 FROM public.clubs c WHERE c.id = p_club_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'club_not_found');
  END IF;

  IF NOT public.fn_can_manage_club_message(p_club_id, v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  -- Collapse whitespace and newlines: this renders as ONE line in a fixed-height
  -- strip, so a pasted paragraph would either blow the row out or be clipped
  -- mid-sentence. 240 characters is the width the modal shows in full.
  v_clean := NULLIF(btrim(regexp_replace(COALESCE(p_message, ''), '\s+', ' ', 'g')), '');
  IF v_clean IS NOT NULL THEN
    v_clean := left(v_clean, 240);
  END IF;

  UPDATE public.clubs
     SET lobby_message = v_clean,
         lobby_message_updated_at = CASE WHEN v_clean IS NULL THEN NULL ELSE now() END,
         message_revision = message_revision + 1
   WHERE id = p_club_id
   RETURNING message_revision INTO v_revision;

  RETURN jsonb_build_object(
    'ok', true,
    'lobby_message', v_clean,
    'revision', v_revision
  );
END;
$$;


ALTER FUNCTION public.fn_set_club_lobby_message(p_club_id uuid, p_message text) OWNER TO postgres;

--
-- Name: fn_set_club_rules(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_set_club_rules(p_club_id uuid, p_rules text) RETURNS TABLE(club_id uuid, rules_text text, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_role  text;
  v_text  text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_club_id IS NULL THEN
    RAISE EXCEPTION 'no club was named' USING ERRCODE = '22004';
  END IF;

  -- Owner, co-owner or admin. The owner is checked separately because a club's
  -- owner is not required to hold a `club_members` row.
  SELECT lower(cm.role) INTO v_role
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = v_uid
     AND coalesce(cm.status, 'approved') NOT IN ('banned', 'rejected', 'left');

  IF NOT (EXISTS (SELECT 1 FROM public.clubs c
                   WHERE c.id = p_club_id AND c.owner_id = v_uid)
          OR v_role IN ('owner', 'co_owner', 'admin')) THEN
    RAISE EXCEPTION 'only an owner, co-owner or admin can change the club rules'
      USING ERRCODE = '42501';
  END IF;

  -- 60,000 characters is the page's own cap. Enforced here as well, because a
  -- limit that lives only in a text area is not a limit.
  v_text := left(coalesce(p_rules, ''), 60000);

  -- ONE KEY. Never a read-modify-write of the whole document: everything else
  -- in `settings` is left exactly as the row holds it at the moment of the
  -- write, so a concurrent buy-in change cannot be rolled back by a rules save.
  UPDATE public.clubs c
     SET settings = jsonb_set(
           coalesce(c.settings, '{}'::jsonb), '{rules_text}', to_jsonb(v_text), true)
   WHERE c.id = p_club_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no club with that id' USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  SELECT c.id, c.settings ->> 'rules_text', c.updated_at
    FROM public.clubs c WHERE c.id = p_club_id;
END;
$$;


ALTER FUNCTION public.fn_set_club_rules(p_club_id uuid, p_rules text) OWNER TO postgres;

--
-- Name: FUNCTION fn_set_club_rules(p_club_id uuid, p_rules text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_set_club_rules(p_club_id uuid, p_rules text) IS 'Writes clubs.settings->>rules_text and nothing else, for an owner, co-owner or admin, and returns what it stored. The page used to read the whole settings document, merge one key into it and write it back with no .select(), so an RLS refusal toasted success and a concurrent buy-in edit was silently reverted.';


--
-- Name: fn_set_interface_theme(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_set_interface_theme(p_theme text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_theme IS NULL OR NOT (p_theme IN ('light', 'dark')) THEN
    RAISE EXCEPTION 'Invalid interface theme' USING ERRCODE = '22023';
  END IF;

  UPDATE public.profiles
     SET settings = jsonb_set(
       CASE
         WHEN jsonb_typeof(settings) = 'object' THEN settings
         ELSE '{}'::jsonb
       END,
       '{theme}',
       to_jsonb(p_theme),
       true
     )
   WHERE id = v_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profile not found' USING ERRCODE = 'P0002';
  END IF;
  RETURN p_theme;
END;
$$;


ALTER FUNCTION public.fn_set_interface_theme(p_theme text) OWNER TO postgres;

--
-- Name: FUNCTION fn_set_interface_theme(p_theme text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_set_interface_theme(p_theme text) IS 'Atomically patches profiles.settings.theme for the authenticated player.';


--
-- Name: fn_set_my_birthday(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_set_my_birthday(p_birthday date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_existing date;
  v_age int;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;
  IF p_birthday IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'missing');
  END IF;
  IF p_birthday > CURRENT_DATE OR p_birthday < DATE '1900-01-01' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'implausible');
  END IF;

  SELECT birthday INTO v_existing FROM public.profiles WHERE id = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'profile_not_found');
  END IF;

  -- Stated once. The same date again is a no-op; a different one is refused.
  IF v_existing IS NOT NULL THEN
    IF v_existing = p_birthday THEN
      RETURN jsonb_build_object('ok', true, 'already_set', true, 'age_verified', true);
    END IF;
    RETURN jsonb_build_object('ok', false, 'reason', 'already_set');
  END IF;

  v_age := date_part('year', age(CURRENT_DATE, p_birthday))::int;
  IF v_age < 18 THEN
    -- Nothing written: refusing is the whole point, and a minor's date of
    -- birth is not something to keep.
    RETURN jsonb_build_object('ok', false, 'reason', 'under_18');
  END IF;

  UPDATE public.profiles
     SET birthday = p_birthday,
         birth_year = COALESCE(birth_year, date_part('year', p_birthday)::int),
         age_verified = true,
         age_verified_at = now(),
         updated_at = now()
   WHERE id = v_uid;

  RETURN jsonb_build_object('ok', true, 'age_verified', true);
END;
$$;


ALTER FUNCTION public.fn_set_my_birthday(p_birthday date) OWNER TO postgres;

--
-- Name: FUNCTION fn_set_my_birthday(p_birthday date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_set_my_birthday(p_birthday date) IS 'The one client path that writes a date of birth: the caller''s own, once, refused under 18 (nothing written), refused if already set to a different date. Sets age_verified.';


--
-- Name: fn_set_player_search_preferences(boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_set_player_search_preferences(p_discoverable boolean, p_show_display_name boolean, p_show_presence boolean, p_show_current_table boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000'; END IF;
  INSERT INTO public.player_search_preferences
    (user_id, discoverable, show_display_name, show_presence, show_current_table, updated_at)
  VALUES
    (v_uid, COALESCE(p_discoverable,true), COALESCE(p_show_display_name,true),
     COALESCE(p_show_presence,true), COALESCE(p_show_current_table,true), now())
  ON CONFLICT (user_id) DO UPDATE SET
    discoverable=EXCLUDED.discoverable,
    show_display_name=EXCLUDED.show_display_name,
    show_presence=EXCLUDED.show_presence,
    show_current_table=EXCLUDED.show_current_table,
    updated_at=now();
  RETURN public.fn_get_player_search_preferences();
END $$;


