--
-- Name: fn_set_user_jurisdiction(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_set_user_jurisdiction(p_caller_user_id uuid, p_country_code text, p_region text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED';
  END IF;
  IF p_country_code IS NULL OR length(trim(p_country_code)) < 2 THEN
    RAISE EXCEPTION 'COUNTRY_CODE_REQUIRED';
  END IF;
  IF length(p_country_code) > 8 THEN
    RAISE EXCEPTION 'COUNTRY_CODE_TOO_LONG';
  END IF;
  IF length(COALESCE(p_region, '')) > 64 THEN
    RAISE EXCEPTION 'REGION_TOO_LONG';
  END IF;

  UPDATE public.profiles
     SET jurisdiction_country       = upper(trim(p_country_code)),
         jurisdiction_region        = NULLIF(trim(COALESCE(p_region, '')), ''),
         jurisdiction_acknowledged_at = now()
   WHERE id = p_caller_user_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION public.fn_set_user_jurisdiction(p_caller_user_id uuid, p_country_code text, p_region text) OWNER TO postgres;

--
-- Name: fn_settle_club_rakeback_batch(uuid, integer, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_club_rakeback_batch(p_club_id uuid, p_max_periods integer DEFAULT 40, p_budget_seconds numeric DEFAULT 4.0, p_max_warm_days integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_started    timestamptz := clock_timestamp();
  v_period     record;
  v_day        record;
  v_res        jsonb;
  v_settled    int := 0;
  v_deferred   int := 0;
  v_errors     int := 0;
  v_retries    int := 0;
  v_warmed     int := 0;
  v_total      numeric := 0;
  v_reasons    jsonb := '{}'::jsonb;
  v_reason     text;
  v_remaining  int;
  v_budget     numeric;
  v_elapsed    numeric;
  v_treasury   numeric;
  v_smallest   numeric;
  v_owed       numeric;
  v_attempt    int;
  v_sqlstate   text;
  v_err        text;
BEGIN
  IF p_club_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'p_club_id required');
  END IF;

  IF NOT public.fn_caller_is_engine()
     AND (auth.uid() IS NULL
          OR (NOT public.fn_is_platform_admin()
              AND NOT EXISTS (SELECT 1 FROM public.clubs c
                               WHERE c.id = p_club_id AND c.owner_id = auth.uid()))) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorised');
  END IF;

  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('success', true, 'club_id', p_club_id,
      'periods_settled', 0, 'total_payout', 0, 'deferred', 0, 'errors', 0,
      'note', 'platform_frozen', 'clock_ran_out', false);
  END IF;

  v_budget := GREATEST(COALESCE(p_budget_seconds, 4.0), 0.5);
  IF p_max_periods IS NULL OR p_max_periods < 1 THEN p_max_periods := 40; END IF;

  SELECT count(*), COALESCE(min(NULLIF(COALESCE(rakeback_amount, rakeback_earned, 0), 0)), 0),
         COALESCE(sum(COALESCE(rakeback_amount, rakeback_earned, 0)), 0)
    INTO v_remaining, v_smallest, v_owed
    FROM public.rakeback_periods
   WHERE club_id = p_club_id AND status = 'pending' AND period_end < CURRENT_DATE;

  IF v_remaining = 0 THEN
    RETURN jsonb_build_object('success', true, 'club_id', p_club_id,
      'periods_settled', 0, 'total_payout', 0, 'deferred', 0, 'errors', 0,
      'periods_remaining', 0, 'note', 'nothing due', 'clock_ran_out', false);
  END IF;

  SELECT COALESCE(chip_treasury, 0) INTO v_treasury FROM public.clubs WHERE id = p_club_id;
  IF v_treasury < v_smallest THEN
    UPDATE public.rakeback_periods
       SET deferred_reason = 'insufficient_club_treasury',
           deferred_at = NOW(), defer_count = defer_count + 1
     WHERE club_id = p_club_id AND status = 'pending' AND period_end < CURRENT_DATE
       AND deferred_reason IS DISTINCT FROM 'insufficient_club_treasury';

    RETURN jsonb_build_object('success', true, 'club_id', p_club_id,
      'periods_settled', 0, 'total_payout', 0, 'errors', 0,
      'deferred', v_remaining,
      'deferred_reasons', jsonb_build_object('insufficient_club_treasury', v_remaining),
      'periods_remaining', v_remaining,
      'treasury', round(v_treasury, 2), 'owed', round(v_owed, 2),
      'shortfall', round(v_owed - v_treasury, 2),
      'note', 'club cannot fund its smallest pending payout',
      'elapsed_seconds', round(extract(epoch FROM (clock_timestamp() - v_started))::numeric, 3),
      'clock_ran_out', false);
  END IF;

  FOR v_day IN
    SELECT DISTINCT d::date AS day
      FROM public.rakeback_periods rp
      CROSS JOIN LATERAL generate_series(rp.period_start, rp.period_end, interval '1 day') d
     WHERE rp.club_id = p_club_id
       AND rp.status = 'pending'
       AND rp.period_end < CURRENT_DATE
       AND NOT EXISTS (SELECT 1 FROM public.rakeback_daily_state s
                        WHERE s.club_id = p_club_id AND s.day = d::date)
     ORDER BY 1
     LIMIT GREATEST(COALESCE(p_max_warm_days, 2), 0)
  LOOP
    EXIT WHEN extract(epoch FROM (clock_timestamp() - v_started)) > v_budget * 0.6;
    BEGIN
      PERFORM public.fn_rakeback_recompute_day(p_club_id, v_day.day, false);
      v_warmed := v_warmed + 1;
    EXCEPTION WHEN OTHERS THEN
      -- A day that will not roll up is not a reason to skip paying the
      -- periods that do. The payer falls back to the direct scan.
      v_errors := v_errors + 1;
    END;
  END LOOP;

  FOR v_period IN
    SELECT id FROM public.rakeback_periods
     WHERE club_id = p_club_id AND status = 'pending'
       AND period_end < CURRENT_DATE
     -- Least-refused first. A deferred period stays pending because the
     -- money is still owed, so ordering by age alone lets a permanently
     -- refusing head of queue starve everything behind it.
     ORDER BY defer_count, period_end, id
     LIMIT p_max_periods
  LOOP
    EXIT WHEN extract(epoch FROM (clock_timestamp() - v_started)) > v_budget;

    v_attempt := 0;
    LOOP
      v_attempt := v_attempt + 1;
      BEGIN
        v_res := public.fn_close_settlement_period(v_period.id);
        EXIT;                                   -- closed, or refused cleanly
      EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_err = MESSAGE_TEXT;
        -- 40P01 deadlock_detected, 55P03 lock_not_available, 40001 serialization
        IF v_sqlstate IN ('40P01','55P03','40001') AND v_attempt < 3 THEN
          v_retries := v_retries + 1;
          PERFORM pg_sleep(0.05 * v_attempt);
          CONTINUE;                              -- the period is untouched; try again
        END IF;
        v_res := jsonb_build_object('success', false,
                   'deferred', 'error_' || v_sqlstate,
                   'detail', left(v_err, 200));
        v_errors := v_errors + 1;
        BEGIN
          UPDATE public.rakeback_periods
             SET deferred_reason = 'error_' || v_sqlstate,
                 deferred_at = NOW(), defer_count = defer_count + 1
           WHERE id = v_period.id;
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        EXIT;
      END;
    END LOOP;

    IF COALESCE((v_res->>'success')::boolean, false) THEN
      v_settled := v_settled + 1;
      v_total   := v_total + COALESCE((v_res->>'payout')::numeric, 0);
    ELSE
      v_deferred := v_deferred + 1;
      v_reason   := COALESCE(v_res->>'deferred', v_res->>'error', 'unknown');
      v_reasons  := jsonb_set(v_reasons, ARRAY[v_reason],
                      to_jsonb(COALESCE((v_reasons->>v_reason)::int, 0) + 1), true);
    END IF;
  END LOOP;

  SELECT count(*) INTO v_remaining FROM public.rakeback_periods
   WHERE club_id = p_club_id AND status = 'pending' AND period_end < CURRENT_DATE;

  v_elapsed := round(extract(epoch FROM (clock_timestamp() - v_started))::numeric, 3);

  RETURN jsonb_build_object('success', true, 'club_id', p_club_id,
    'periods_settled', v_settled, 'total_payout', round(v_total, 2),
    'deferred', v_deferred, 'deferred_reasons', v_reasons,
    'errors', v_errors, 'lock_retries', v_retries,
    'days_warmed', v_warmed, 'periods_remaining', v_remaining,
    'treasury', round(v_treasury, 2),
    'elapsed_seconds', v_elapsed,
    'clock_ran_out', v_elapsed > v_budget);
END;
$$;


ALTER FUNCTION public.fn_settle_club_rakeback_batch(p_club_id uuid, p_max_periods integer, p_budget_seconds numeric, p_max_warm_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_settle_club_rakeback_batch(p_club_id uuid, p_max_periods integer, p_budget_seconds numeric, p_max_warm_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settle_club_rakeback_batch(p_club_id uuid, p_max_periods integer, p_budget_seconds numeric, p_max_warm_days integer) IS 'Settles at most p_max_periods rakeback periods for one club and stops at p_budget_seconds of wall clock, so it always returns inside the 8s statement_timeout every server-side role carries. Refuses cheaply before doing the work: freeze, then club membership, then whether the treasury can cover the period''s own estimate. Warms uncomputed rollup days first. A deadlock or lock timeout on one period is retried twice and then recorded against that period; one bad period never ends the run. Reports what remains and why. Call it again to continue.';


--
-- Name: fn_settle_due_leaderboards(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_due_leaderboards() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_candidate record;
  v_plan jsonb;
  v_result jsonb;
  v_end date;
  v_error_message text;
  v_error_code text;
  v_settled integer := 0;
  v_failed integer := 0;
  v_skipped_disabled integer := 0;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('settle-due-leaderboards')) THEN
    RETURN jsonb_build_object('success', true, 'skipped', 'Already Running');
  END IF;

  FOR v_candidate IN
    WITH latest_closed AS MATERIALIZED (
      SELECT 'weekly'::text AS period, bounds.start_date AS period_start
      FROM public.fn_leaderboard_period_window('weekly', -1) bounds
      UNION ALL
      SELECT 'monthly'::text, bounds.start_date
      FROM public.fn_leaderboard_period_window('monthly', -1) bounds
    ), first_effective AS MATERIALIZED (
      SELECT program.club_id, 'weekly'::text AS period,
             min(program.weekly_effective_from) AS period_start
      FROM public.leaderboard_reward_program_versions program
      GROUP BY program.club_id
      UNION ALL
      SELECT program.club_id, 'monthly'::text,
             min(program.monthly_effective_from)
      FROM public.leaderboard_reward_program_versions program
      GROUP BY program.club_id
    ), due AS (
      SELECT first_effective.club_id, first_effective.period,
             generated.period_start::date AS period_start
      FROM first_effective
      JOIN latest_closed USING (period)
      CROSS JOIN LATERAL generate_series(
        first_effective.period_start::timestamp,
        latest_closed.period_start::timestamp,
        CASE first_effective.period
          WHEN 'weekly' THEN interval '7 days'
          ELSE interval '1 month'
        END
      ) generated(period_start)
    )
    SELECT due.club_id, due.period, due.period_start
    FROM due
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.leaderboard_payout_batches batch
      WHERE batch.club_id = due.club_id
        AND batch.period = due.period
        AND batch.period_start = due.period_start
    )
    ORDER BY due.period_start, due.club_id, due.period
  LOOP
    BEGIN
      v_plan := public.fn_get_leaderboard_reward_plan(
        v_candidate.club_id,
        v_candidate.period,
        v_candidate.period_start
      );

      IF v_plan IS NULL
         OR NOT COALESCE((v_plan ->> 'rewards_enabled')::boolean, false) THEN
        v_skipped_disabled := v_skipped_disabled + 1;
        CONTINUE;
      END IF;

      v_end := CASE v_candidate.period
        WHEN 'weekly' THEN v_candidate.period_start + 7
        ELSE (v_candidate.period_start + interval '1 month')::date
      END;

      v_result := public.fn_payout_leaderboard(
        v_candidate.club_id,
        v_candidate.period,
        v_plan ->> 'payout_metric',
        v_candidate.period_start::timestamp AT TIME ZONE 'UTC',
        v_end::timestamp AT TIME ZONE 'UTC'
      );
      v_settled := v_settled + CASE
        WHEN COALESCE((v_result ->> 'already_settled')::boolean, false) THEN 0
        ELSE 1
      END;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
      v_error_code := CASE
        WHEN v_error_message LIKE 'LEADERBOARD_PROMO_UNDERFUNDED|%' THEN 'promo_wallet_underfunded'
        WHEN v_error_message LIKE 'LEADERBOARD_PROMO_WALLET_MISSING|%' THEN 'promo_wallet_missing'
        WHEN v_error_message LIKE 'LEADERBOARD_PROGRAM_INVALID|%' THEN 'program_invalid'
        WHEN v_error_message LIKE 'LEADERBOARD_CREDIT_CONFLICT|%' THEN 'credit_conflict'
        ELSE 'settlement_error'
      END;
      v_error_message := regexp_replace(v_error_message, '^LEADERBOARD_[A-Z_]+\\|', '');
      v_failed := v_failed + 1;

      INSERT INTO public.leaderboard_payout_failures (
        club_id, period, period_start, error_message, error_code,
        failed_at, first_failed_at, attempt_count, resolved_at, resolution
      ) VALUES (
        v_candidate.club_id, v_candidate.period, v_candidate.period_start,
        left(v_error_message, 500), v_error_code, now(), now(), 1, NULL, NULL
      )
      ON CONFLICT (club_id, period, period_start) DO UPDATE
        SET error_message = EXCLUDED.error_message,
            error_code = EXCLUDED.error_code,
            failed_at = now(),
            attempt_count = public.leaderboard_payout_failures.attempt_count + 1,
            resolved_at = NULL,
            resolution = NULL;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', v_failed = 0,
    'settled', v_settled,
    'failed', v_failed,
    'skipped_disabled', v_skipped_disabled
  );
END;
$$;


ALTER FUNCTION public.fn_settle_due_leaderboards() OWNER TO postgres;

--
-- Name: FUNCTION fn_settle_due_leaderboards(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settle_due_leaderboards() IS 'Service-only catch-up scheduler. Retries every closed unpaid immutable program, records categorized attempt history, and never debits an operating wallet.';


--
-- Name: fn_settle_final_table_deal_atomic(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_final_table_deal_atomic(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_t                       record;
  v_batch                   public.tournament_final_table_deal_batches%ROWTYPE;
  v_check                   jsonb;
  v_struct                  jsonb := '[]'::jsonb;
  v_trimmed                 jsonb := '[]'::jsonb;
  v_place_plan              jsonb := '[]'::jsonb;
  v_deal_shares             jsonb := '[]'::jsonb;
  v_deal_plan               jsonb := '[]'::jsonb;
  v_plan                    jsonb := '[]'::jsonb;
  v_payouts                 jsonb := '[]'::jsonb;
  v_plan_fingerprint        text;
  v_prior_standings_fingerprint text;
  v_live_input_snapshot     jsonb := '[]'::jsonb;
  v_live_input_fingerprint  text;
  v_field_count             integer := 0;
  v_live_count              integer := 0;
  v_deal_table_id           uuid;
  v_seated_active_tables    integer := 0;
  v_all_live_seats          integer := 0;
  v_active_live_seats       integer := 0;
  v_distinct_seat_users     integer := 0;
  v_matching_live_users     integer := 0;
  v_seat_stack_mismatches   integer := 0;
  v_live_missing_registration integer := 0;
  v_other_count             integer := 0;
  v_live_positioned         integer := 0;
  v_eliminated_count        integer := 0;
  v_eliminated_ranked       integer := 0;
  v_eliminated_distinct     integer := 0;
  v_eliminated_min          integer := 0;
  v_eliminated_max          integer := 0;
  v_eliminated_missing_time integer := 0;
  v_eliminated_canonical_mismatches integer := 0;
  v_structure_places        integer := 0;
  v_structure_distinct      integer := 0;
  v_structure_min           integer := 0;
  v_structure_max           integer := 0;
  v_total_bp                bigint := 0;
  v_pool_cents              bigint := 0;
  v_remaining_cents         bigint := 0;
  v_expected_cents          bigint := 0;
  v_place_total_cents       bigint := 0;
  v_prior_place_paid_cents  bigint := 0;
  v_deal_total_cents        bigint := 0;
  v_available_cents         bigint := 0;
  v_unpaid_cents            bigint := 0;
  v_total_unpaid_cents      bigint := 0;
  v_floor_paid_cents        bigint := 0;
  v_remainder_cents         bigint := 0;
  v_total_chips             numeric := 0;
  v_rank                    integer := 0;
  v_share_cents             bigint := 0;
  v_leader                  uuid;
  v_holder                  uuid;
  v_holders                 integer := 0;
  v_seeded_paid             numeric := 0;
  v_wrong_recipients        integer := 0;
  v_conflicts               integer := 0;
  v_existing                public.tournament_obligations%ROWTYPE;
  v_result                  jsonb;
  v_after_paid              numeric := 0;
  v_paid_this_call          numeric := 0;
  v_place_paid_this_call    numeric := 0;
  v_deal_paid_this_call     numeric := 0;
  v_bubble_paid_this_call   numeric := 0;
  v_bubble_user             uuid;
  v_bubble_holders          integer := 0;
  v_bubble_obligations      integer := 0;
  v_bubble_matching         integer := 0;
  v_bubble_owed             numeric := 0;
  v_bubble_paid             numeric := 0;
  v_bubble_evidence         numeric := 0;
  v_bubble_conflicts        integer := 0;
  v_bubble_obligation_id    uuid;
  v_bubble_source           text;
  v_bubble_settled_at       timestamptz;
  v_bubble_row_found        boolean := false;
  v_bubble_needs_insert     boolean := false;
  v_bubble_unpaid_cents     bigint := 0;
  v_after_bubble_paid       numeric := 0;
  v_bubble_obligation_present boolean := false;
  v_bubble_payout_present   boolean := false;
  v_bubble_required         boolean := false;
  v_bubble_shape_valid      boolean := false;
  v_escrow                  public.tournament_escrow%ROWTYPE;
  v_escrow_after            numeric := 0;
  v_failure                 text;
  v_failure_state           text;
  r                         record;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  IF p_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_id_required',
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;

  SELECT t.id, t.name, t.status, round(COALESCE(t.prize_pool, 0), 2) AS prize_pool,
         round(COALESCE(t.guaranteed_prize, 0), 2) AS guaranteed_prize,
         COALESCE(t.prize_pool_finalized, false) AS prize_pool_finalized,
         COALESCE(t.final_table_deal_enabled, false) AS final_table_deal_enabled,
         COALESCE(t.table_size, 9) AS table_size, t.payout_structure,
         t.variant, t.tournament_type, t.satellite_target_id, t.spin_multiplier,
         COALESCE(t.is_bounty, false) AS is_bounty,
         COALESCE(t.is_pko, false) AS is_pko,
         COALESCE(t.is_mystery_bounty, false) AS is_mystery_bounty,
         COALESCE(t.mystery_bounty_stage, 'pending') AS mystery_bounty_stage,
         COALESCE(t.bubble_protection, false) AS bubble_protection,
         round(COALESCE(t.buy_in_amount, 0), 2) AS buy_in_amount
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found',
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;

  SELECT * INTO v_batch
    FROM public.tournament_final_table_deal_batches b
   WHERE b.tournament_id = p_tournament_id
   FOR UPDATE;

  IF v_t.status = 'COMPLETED' THEN
    v_check := public.fn_check_atomic_final_table_deal(p_tournament_id);
    IF COALESCE((v_check->>'ok')::boolean, false) THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'user_id', x.user_id, 'amount', x.cents / 100.0, 'rank', x.rank)
               ORDER BY x.rank), '[]'::jsonb)
        INTO v_payouts
        FROM jsonb_to_recordset(v_batch.plan)
          AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
       WHERE x.kind = 'final_table_deal';
      RETURN jsonb_build_object(
        'ok', true, 'paid', 0, 'place_paid', 0, 'deal_paid', 0, 'bubble_paid', 0,
        'completed', true, 'already_completed', true,
        'players', v_batch.live_count, 'chip_leader', v_batch.chip_leader,
        'deal_table_id', v_batch.deal_table_id,
        'bubble_contract_required', v_batch.bubble_contract_required,
        'bubble_obligation_id', v_batch.bubble_obligation_id,
        'payouts', v_payouts, 'retryable', false);
    END IF;
    RETURN v_check || jsonb_build_object('paid', 0, 'completed', false,
                                         'retryable', false);
  END IF;

  IF v_t.status <> 'RUNNING' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_running',
                              'status', v_t.status, 'paid', 0,
                              'completed', false, 'retryable', false);
  END IF;
  IF NOT v_t.final_table_deal_enabled THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'deal_not_enabled',
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;
  IF lower(COALESCE(v_t.variant, '')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type, '')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'satellite_has_its_own_settlement',
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;
  IF NOT v_t.prize_pool_finalized
     OR v_t.prize_pool + 0.005 < v_t.guaranteed_prize THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'prize_pool_is_not_funded_and_finalized',
                              'prize_pool', v_t.prize_pool,
                              'guaranteed_prize', v_t.guaranteed_prize,
                              'prize_pool_finalized', v_t.prize_pool_finalized,
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;
  IF v_batch.tournament_id IS NOT NULL
     OR EXISTS (SELECT 1 FROM public.tournament_payouts p
                 WHERE p.tournament_id = p_tournament_id
                   AND p.source = 'final_table_deal')
     OR EXISTS (SELECT 1 FROM public.tournament_obligations o
                 WHERE o.tournament_id = p_tournament_id
                   AND o.kind = 'final_table_deal') THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'legacy_or_incomplete_deal_has_no_atomic_replay',
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;

  /* Parent-to-child locks make the physical-table predicate stable through
     COMMIT. A new tournament table needs a foreign-key key-share lock on the
     tournament row; a new seat needs one on its table row. Both parents are
     already FOR UPDATE, while every existing live seat is locked directly. */
  PERFORM 1
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY tb.id
   FOR UPDATE;
  PERFORM 1
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id
     AND ts.left_at IS NULL
   ORDER BY ts.id
   FOR UPDATE OF ts;
  PERFORM 1
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
   ORDER BY tp.id
   FOR UPDATE;
  PERFORM 1
    FROM public.tournament_deal_votes v
   WHERE v.tournament_id = p_tournament_id
   ORDER BY v.user_id
   FOR UPDATE;

  SELECT count(*),
         count(*) FILTER (WHERE tp.status = 'playing' AND tp.eliminated_at IS NULL),
         count(*) FILTER (WHERE tp.status NOT IN ('playing', 'eliminated')),
         count(*) FILTER (WHERE tp.status = 'playing' AND tp.position IS NOT NULL),
         count(*) FILTER (WHERE tp.status = 'eliminated'),
         count(tp.position) FILTER (WHERE tp.status = 'eliminated'),
         count(DISTINCT tp.position) FILTER (WHERE tp.status = 'eliminated'),
         COALESCE(min(tp.position) FILTER (WHERE tp.status = 'eliminated'), 0),
         COALESCE(max(tp.position) FILTER (WHERE tp.status = 'eliminated'), 0),
         count(*) FILTER (
           WHERE tp.status = 'eliminated' AND tp.eliminated_at IS NULL),
         COALESCE(sum(tp.chips) FILTER (
           WHERE tp.status = 'playing' AND tp.eliminated_at IS NULL), 0)
    INTO v_field_count, v_live_count, v_other_count, v_live_positioned,
         v_eliminated_count, v_eliminated_ranked, v_eliminated_distinct,
         v_eliminated_min, v_eliminated_max, v_eliminated_missing_time,
         v_total_chips
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;

  WITH prior AS (
    SELECT tp.id, tp.user_id, tp.position, tp.eliminated_at,
           v_field_count - (row_number() OVER (
             ORDER BY tp.eliminated_at ASC, tp.id ASC
           ))::integer + 1 AS canonical_position
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status = 'eliminated'
  )
  SELECT count(*) FILTER (
           WHERE p.position IS DISTINCT FROM p.canonical_position),
         md5(COALESCE(jsonb_agg(jsonb_build_object(
           'id', p.id, 'user_id', p.user_id, 'position', p.position,
           'eliminated_at_utc', to_char(
             p.eliminated_at AT TIME ZONE 'UTC',
             'YYYY-MM-DD"T"HH24:MI:SS.US'))
           ORDER BY p.position, p.id), '[]'::jsonb)::text)
    INTO v_eliminated_canonical_mismatches,
         v_prior_standings_fingerprint
    FROM prior p;

  IF v_live_count < 2 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_enough_players',
                              'players', v_live_count, 'paid', 0,
                              'completed', false, 'retryable', false);
  END IF;
  IF v_live_count > v_t.table_size THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_at_final_table',
                              'players', v_live_count, 'table_size', v_t.table_size,
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;
  IF v_other_count > 0 OR v_live_positioned > 0
     OR v_live_count + v_eliminated_count <> v_field_count
     OR v_eliminated_ranked <> v_eliminated_count
     OR v_eliminated_distinct <> v_eliminated_count
     OR (v_eliminated_count > 0
         AND (v_eliminated_min <> v_live_count + 1
              OR v_eliminated_max <> v_field_count
              OR v_eliminated_max - v_eliminated_min + 1
                 <> v_eliminated_count)) THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'standings_before_deal_are_not_contiguous',
                              'field', v_field_count, 'live', v_live_count,
                              'other_statuses', v_other_count,
                              'live_with_position', v_live_positioned,
                              'classified_players',
                                v_live_count + v_eliminated_count,
                              'eliminated', v_eliminated_count,
                              'eliminated_ranked', v_eliminated_ranked,
                              'eliminated_distinct', v_eliminated_distinct,
                              'eliminated_range', jsonb_build_array(v_eliminated_min,
                                                                    v_eliminated_max),
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;
  IF v_eliminated_missing_time > 0
     OR v_eliminated_canonical_mismatches > 0 THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'prior_eliminated_standings_are_not_canonical',
      'eliminated_without_time', v_eliminated_missing_time,
      'canonical_mismatches', v_eliminated_canonical_mismatches,
      'rule', 'earliest eliminated_at then id receives the largest position',
      'paid', 0, 'completed', false, 'retryable', false);
  END IF;
  IF v_total_chips <= 0 OR EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status = 'playing' AND tp.eliminated_at IS NULL
       AND COALESCE(tp.chips, 0) <= 0
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'live_chip_totals_are_invalid',
                              'total_chips', v_total_chips, 'paid', 0,
                              'completed', false, 'retryable', false);
  END IF;

  /* "Final table" means one physical occupied table and an exact seat set,
     not merely a live headcount below table_size. Include live-seat residue
     on paused/closed tables in the all-seat count so stale merge residue also
     fails closed. Null-user seats, duplicate seats, eliminated seats, missing
     live players and split tables each make at least one equality fail. */
  SELECT count(DISTINCT tb.id) FILTER (
           WHERE tb.status::text IN ('running', 'waiting') AND ts.id IS NOT NULL),
         count(ts.id),
         count(ts.id) FILTER (
           WHERE tb.status::text IN ('running', 'waiting')),
         count(DISTINCT ts.user_id),
         count(DISTINCT ts.user_id) FILTER (
           WHERE EXISTS (
             SELECT 1
               FROM public.tournament_players live
              WHERE live.tournament_id = p_tournament_id
                AND live.user_id = ts.user_id
                AND live.status = 'playing'
                AND live.eliminated_at IS NULL
           ))
    INTO v_seated_active_tables, v_all_live_seats, v_active_live_seats,
         v_distinct_seat_users, v_matching_live_users
    FROM public.tables tb
    LEFT JOIN public.table_seats ts
      ON ts.table_id = tb.id AND ts.left_at IS NULL
   WHERE tb.tournament_id = p_tournament_id;

  SELECT tb.id INTO v_deal_table_id
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
     AND tb.status::text IN ('running', 'waiting')
     AND EXISTS (
       SELECT 1 FROM public.table_seats ts
        WHERE ts.table_id = tb.id AND ts.left_at IS NULL
     )
   ORDER BY tb.id
   LIMIT 1;

  IF v_seated_active_tables <> 1 OR v_deal_table_id IS NULL
     OR v_all_live_seats <> v_live_count
     OR v_active_live_seats <> v_live_count
     OR v_distinct_seat_users <> v_live_count
     OR v_matching_live_users <> v_live_count THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'physical_final_table_seat_set_is_not_exact',
      'players', v_live_count, 'deal_table_id', v_deal_table_id,
      'seated_active_tables', v_seated_active_tables,
      'all_live_seats', v_all_live_seats,
      'active_live_seats', v_active_live_seats,
      'distinct_seat_users', v_distinct_seat_users,
      'matching_live_users', v_matching_live_users,
      'paid', 0, 'completed', false, 'retryable', false);
  END IF;

  SELECT count(*) FILTER (WHERE tp.registered_at IS NULL),
         count(*) FILTER (WHERE ts.stack IS DISTINCT FROM tp.chips),
         COALESCE(jsonb_agg(jsonb_build_object(
           'player_id', tp.id,
           'user_id', tp.user_id,
           'chips', tp.chips,
           'registered_at_utc', to_char(
             tp.registered_at AT TIME ZONE 'UTC',
             'YYYY-MM-DD"T"HH24:MI:SS.US'),
           'rebuys', COALESCE(tp.rebuys, 0),
           'add_on', COALESCE(tp.add_on, false),
           'seat_id', ts.id,
           'table_id', tb.id,
           'seat_stack', ts.stack)
           ORDER BY tp.chips DESC, tp.registered_at ASC, tp.user_id ASC),
           '[]'::jsonb)
    INTO v_live_missing_registration, v_seat_stack_mismatches,
         v_live_input_snapshot
    FROM public.tournament_players tp
    JOIN public.table_seats ts
      ON ts.user_id = tp.user_id AND ts.left_at IS NULL
    JOIN public.tables tb
      ON tb.id = ts.table_id AND tb.id = v_deal_table_id
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status = 'playing' AND tp.eliminated_at IS NULL;

  IF jsonb_array_length(v_live_input_snapshot) <> v_live_count
     OR v_live_missing_registration > 0
     OR v_seat_stack_mismatches > 0 THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'live_deal_inputs_do_not_match_seat_stacks',
      'players', v_live_count,
      'snapshot_rows', jsonb_array_length(v_live_input_snapshot),
      'missing_registered_at', v_live_missing_registration,
      'seat_stack_mismatches', v_seat_stack_mismatches,
      'paid', 0, 'completed', false, 'retryable', false);
  END IF;
  v_live_input_fingerprint := md5(v_live_input_snapshot::text);

  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status = 'playing' AND tp.eliminated_at IS NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_deal_votes v
          WHERE v.tournament_id = p_tournament_id AND v.user_id = tp.user_id
       )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'deal_vote_is_not_unanimous',
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;

  v_pool_cents := round(v_t.prize_pool * 100)::bigint;
  IF v_pool_cents <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_prize_pool_to_deal',
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;

  BEGIN
    IF lower(COALESCE(v_t.variant, '')) = 'spin'
       OR upper(COALESCE(v_t.tournament_type, '')) = 'SPIN' THEN
      IF v_t.spin_multiplier IS NULL OR v_t.spin_multiplier <= 0 THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'spin_multiplier_is_not_persisted',
                                  'paid', 0, 'completed', false, 'retryable', false);
      END IF;
      SELECT l.structure INTO v_struct
        FROM public.spin_payout_ladder l
       WHERE l.multiplier = v_t.spin_multiplier;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', false,
                                  'reason', 'spin_multiplier_has_no_canonical_ladder',
                                  'spin_multiplier', v_t.spin_multiplier,
                                  'paid', 0, 'completed', false, 'retryable', false);
      END IF;
    ELSE
      v_struct := public.fn_safe_jsonb_array(v_t.payout_structure);
    END IF;

    IF jsonb_array_length(v_struct) = 0 OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_struct) e
       WHERE jsonb_typeof(e) <> 'object'
          OR COALESCE(e->>'place', '') !~ '^[1-9][0-9]*$'
          OR COALESCE(e->>'percentage', '') !~ '^[0-9]+([.][0-9]+)?$'
          OR (e->>'percentage')::numeric < 0
    ) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'payout_structure_is_invalid',
                                'paid', 0, 'completed', false, 'retryable', false);
    END IF;

    SELECT COALESCE(jsonb_agg(e ORDER BY (e->>'place')::integer), '[]'::jsonb)
      INTO v_trimmed
      FROM jsonb_array_elements(v_struct) e
     WHERE (e->>'place')::integer <= v_field_count;

    SELECT count(*), count(DISTINCT (e->>'place')::integer),
           COALESCE(min((e->>'place')::integer), 0),
           COALESCE(max((e->>'place')::integer), 0),
           COALESCE(sum(round((e->>'percentage')::numeric * 100)::bigint), 0)
      INTO v_structure_places, v_structure_distinct,
           v_structure_min, v_structure_max, v_total_bp
      FROM jsonb_array_elements(v_trimmed) e;

    IF v_structure_places = 0 OR v_structure_distinct <> v_structure_places
       OR v_structure_min <> 1 OR v_structure_max <> v_structure_places
       OR v_total_bp <= 0 THEN
      RETURN jsonb_build_object('ok', false,
                                'reason', 'payout_places_are_not_contiguous',
                                'places', v_structure_places,
                                'last_place', v_structure_max,
                                'paid', 0, 'completed', false, 'retryable', false);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'payout_structure_is_invalid',
                              'detail', SQLERRM, 'paid', 0,
                              'completed', false, 'retryable', false);
  END;

  v_remaining_cents := v_pool_cents;
  FOR r IN
    SELECT (e->>'place')::integer AS place,
           round((e->>'percentage')::numeric * 100)::bigint AS bp
      FROM jsonb_array_elements(v_trimmed) e
     ORDER BY (e->>'place')::integer
  LOOP
    IF r.place = v_structure_max THEN
      v_expected_cents := GREATEST(v_remaining_cents, 0);
    ELSE
      v_expected_cents := GREATEST(
        LEAST(v_remaining_cents,
              round(v_pool_cents * r.bp::numeric / v_total_bp)::bigint), 0);
    END IF;
    v_remaining_cents := v_remaining_cents - v_expected_cents;

    IF r.place > v_live_count THEN
      SELECT count(*), (array_agg(tp.user_id ORDER BY tp.id))[1]
        INTO v_holders, v_holder
        FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id AND tp.position = r.place;
      IF v_holders <> 1 OR v_holder IS NULL THEN
        RETURN jsonb_build_object('ok', false,
                                  'reason', 'earned_place_has_no_unique_holder',
                                  'place', r.place, 'holders', v_holders,
                                  'paid', 0, 'completed', false, 'retryable', false);
      END IF;
      v_place_plan := v_place_plan || jsonb_build_array(jsonb_build_object(
        'kind', 'place', 'place', r.place, 'user_id', v_holder,
        'cents', v_expected_cents, 'rank', NULL));
      v_place_total_cents := v_place_total_cents + v_expected_cents;
    END IF;
  END LOOP;

  IF v_remaining_cents <> 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'structure_does_not_allocate_pool',
                              'unallocated_cents', v_remaining_cents,
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;

  /* A positive result cache is an entitlement signal, never evidence that it
     was paid. A stale lower cache is safely promoted to the finalized
     structure below; a cache above or outside that structure would require a
     pricing decision or clawback, so the deal must leave it untouched and
     refuse for review. Live players cannot already hold a place prize. */
  SELECT count(*) INTO v_conflicts
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND round(COALESCE(tp.prize, 0) * 100)::bigint > 0
     AND NOT EXISTS (
       SELECT 1
         FROM jsonb_to_recordset(v_place_plan)
           AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
        WHERE x.place = tp.position AND x.user_id = tp.user_id
          AND round(COALESCE(tp.prize, 0) * 100)::bigint <= x.cents
     );
  IF v_conflicts > 0 THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'recorded_positive_prize_conflicts_with_deal_plan',
                              'rows', v_conflicts, 'paid', 0,
                              'completed', false, 'retryable', false);
  END IF;

  SELECT EXISTS (
           SELECT 1 FROM public.tournament_obligations o
            WHERE o.tournament_id = p_tournament_id
              AND o.kind = 'bubble_protection'
         ), EXISTS (
           SELECT 1 FROM public.tournament_payouts p
            WHERE p.tournament_id = p_tournament_id
              AND p.source = 'bubble_protection'
         )
    INTO v_bubble_obligation_present, v_bubble_payout_present;
  v_bubble_shape_valid := v_t.buy_in_amount > 0
    AND v_structure_places > 0 AND v_field_count > v_structure_places;
  v_bubble_required := (v_t.bubble_protection AND v_bubble_shape_valid)
    OR v_bubble_obligation_present OR v_bubble_payout_present;

  IF v_bubble_required AND NOT v_bubble_shape_valid THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'bubble_protection_contract_shape_is_invalid',
      'buy_in_amount', v_t.buy_in_amount,
      'structure_places', v_structure_places, 'field_count', v_field_count,
      'bubble_obligation_present', v_bubble_obligation_present,
      'bubble_payout_present', v_bubble_payout_present,
      'paid', 0, 'completed', false, 'retryable', false);
  END IF;

  IF v_bubble_required THEN
    /* A deal may be accepted before the natural bubble. In that case the final
       stone-bubble rank belongs to a still-live player and no persisted
       position exists yet. Derive that holder from the exact locked snapshot
       using the same ordering that builds and stamps the deal plan below. If
       the natural bubble already occurred, its durable eliminated position is
       the source of truth. */
    IF v_structure_places + 1 <= v_live_count THEN
      SELECT count(*), (array_agg(ranked.user_id ORDER BY ranked.rank))[1]
        INTO v_bubble_holders, v_bubble_user
        FROM (
          SELECT s.user_id,
                 row_number() OVER (
                   ORDER BY s.chips DESC, s.registered_at_utc ASC, s.user_id ASC
                 )::integer AS rank
            FROM jsonb_to_recordset(v_live_input_snapshot)
              AS s(player_id uuid, user_id uuid, chips numeric,
                   registered_at_utc text, rebuys integer, add_on boolean,
                   seat_id uuid, table_id uuid, seat_stack numeric)
        ) ranked
       WHERE ranked.rank = v_structure_places + 1;
    ELSE
      SELECT count(*), (array_agg(tp.user_id ORDER BY tp.id))[1]
        INTO v_bubble_holders, v_bubble_user
        FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id
         AND tp.position = v_structure_places + 1;
    END IF;

    SELECT count(*),
           count(*) FILTER (WHERE o.user_id = v_bubble_user AND o.place IS NULL),
           COALESCE(max(o.amount_owed) FILTER (
             WHERE o.user_id = v_bubble_user AND o.place IS NULL), 0),
           COALESCE(max(o.amount_paid) FILTER (
             WHERE o.user_id = v_bubble_user AND o.place IS NULL), 0)
      INTO v_bubble_obligations, v_bubble_matching, v_bubble_owed, v_bubble_paid
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'bubble_protection';

    SELECT round(COALESCE(sum(p.amount), 0), 2)
      INTO v_bubble_evidence
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.user_id = v_bubble_user AND p.position IS NULL
       AND p.source = 'bubble_protection';

    SELECT count(*) INTO v_bubble_conflicts
      FROM (
        SELECT p.position, p.user_id
          FROM public.tournament_payouts p
         WHERE p.tournament_id = p_tournament_id
           AND p.source = 'bubble_protection'
           AND (p.position IS NOT NULL OR p.user_id IS DISTINCT FROM v_bubble_user)
         GROUP BY p.position, p.user_id
        HAVING abs(round(sum(p.amount), 2)) > 0.005
      ) unexpected_bubble;

    IF v_bubble_obligations = 0 AND NOT v_bubble_payout_present THEN
      v_bubble_obligation_id := gen_random_uuid();
      v_bubble_source := 'engine.atomicFinalTableDeal';
      v_bubble_owed := v_t.buy_in_amount;
      v_bubble_paid := 0;
      v_bubble_settled_at := NULL;
      v_bubble_needs_insert := true;
    ELSIF v_bubble_obligations = 1 AND v_bubble_matching = 1 THEN
      SELECT o.id, o.source, o.amount_owed, o.amount_paid, o.settled_at
        INTO v_bubble_obligation_id, v_bubble_source, v_bubble_owed,
             v_bubble_paid, v_bubble_settled_at
        FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'bubble_protection'
         AND o.place IS NULL AND o.user_id = v_bubble_user
       FOR UPDATE;
    END IF;

    IF v_bubble_holders <> 1 OR v_bubble_user IS NULL
       OR (NOT v_bubble_needs_insert
           AND (v_bubble_obligations <> 1 OR v_bubble_matching <> 1))
       OR (v_bubble_needs_insert
           AND (v_bubble_obligations <> 0 OR v_bubble_payout_present))
       OR v_bubble_obligation_id IS NULL
       OR COALESCE(v_bubble_source, '') NOT IN ('engine.eliminatePlayer', 'engine.atomicFinalTableDeal')
       OR abs(v_bubble_owed - v_t.buy_in_amount) > 0.005
       OR v_bubble_paid < -0.005 OR v_bubble_paid > v_bubble_owed + 0.005
       OR abs(v_bubble_paid - v_bubble_evidence) > 0.005
       OR (v_bubble_paid + 0.005 >= v_bubble_owed
           AND v_bubble_settled_at IS NULL)
       OR (v_bubble_paid + 0.005 < v_bubble_owed
           AND v_bubble_settled_at IS NOT NULL)
       OR v_bubble_conflicts > 0 THEN
      RETURN jsonb_build_object('ok', false,
                                'reason', 'bubble_protection_obligation_is_not_exact',
                                'bubble_place', v_structure_places + 1,
                                'user_id', v_bubble_user,
                                'expected', v_t.buy_in_amount,
                                'amount_owed', v_bubble_owed,
                                'amount_paid', v_bubble_paid,
                                'payout_evidence', v_bubble_evidence,
                                'conflicts', v_bubble_conflicts,
                                'paid', 0, 'completed', false, 'retryable', false);
    END IF;
    v_bubble_unpaid_cents := round(
      GREATEST(v_bubble_owed - v_bubble_paid, 0) * 100)::bigint;
  END IF;

  FOR r IN
    SELECT (p->>'place')::integer AS place,
           (p->>'user_id')::uuid AS user_id,
           (p->>'cents')::bigint AS cents
      FROM jsonb_array_elements(v_place_plan) p
     ORDER BY (p->>'place')::integer
  LOOP
    SELECT round(COALESCE(sum(p.amount), 0), 2)
      INTO v_seeded_paid
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.position = r.place AND p.user_id = r.user_id
       AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                         'late_reg_adjustment', 'clawback', 'spin_backpay',
                         'overlay_backpay')
            OR EXISTS (
              SELECT 1 FROM public.tournament_obligations eo
               WHERE eo.tournament_id = p_tournament_id
                 AND eo.kind = 'place' AND eo.place = r.place
                 AND eo.user_id = r.user_id
                 AND p.idempotency_key LIKE
                   'tourney:' || p_tournament_id::text || ':obl:' ||
                   eo.id::text || ':%'
            ));

    SELECT count(*) INTO v_wrong_recipients
      FROM (
        SELECT p.user_id
          FROM public.tournament_payouts p
         WHERE p.tournament_id = p_tournament_id AND p.position = r.place
           AND p.user_id IS DISTINCT FROM r.user_id
           AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                             'late_reg_adjustment', 'clawback', 'spin_backpay',
                             'overlay_backpay')
                OR EXISTS (
                  SELECT 1 FROM public.tournament_obligations eo
                   WHERE eo.tournament_id = p_tournament_id
                     AND eo.kind = 'place' AND eo.place = p.position
                     AND eo.user_id = p.user_id
                     AND p.idempotency_key LIKE
                       'tourney:' || p_tournament_id::text || ':obl:' ||
                       eo.id::text || ':%'
                ))
         GROUP BY p.user_id
        HAVING abs(round(sum(p.amount), 2)) > 0.005
      ) wrong;

    SELECT * INTO v_existing
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'place' AND o.place = r.place
     FOR UPDATE;

    IF v_wrong_recipients > 0 OR v_seeded_paid < -0.005
       OR v_seeded_paid > r.cents / 100.0 + 0.005
       OR (FOUND AND abs(round(v_existing.amount_paid, 2) - v_seeded_paid) > 0.005)
       OR (FOUND AND v_existing.amount_owed > r.cents / 100.0 + 0.005)
       OR (FOUND AND v_existing.amount_paid > 0
                    AND v_existing.user_id IS DISTINCT FROM r.user_id) THEN
      RETURN jsonb_build_object('ok', false,
                                'reason', 'earned_place_evidence_conflicts_with_plan',
                                'place', r.place, 'user_id', r.user_id,
                                'expected', r.cents / 100.0,
                                'payout_evidence', v_seeded_paid,
                                'wrong_recipients', v_wrong_recipients,
                                'paid', 0, 'completed', false, 'retryable', false);
    END IF;
    v_prior_place_paid_cents := v_prior_place_paid_cents
      + round(v_seeded_paid * 100)::bigint;
  END LOOP;

  SELECT count(*) INTO v_conflicts
    FROM (
      SELECT p.position, p.user_id
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.position IS NOT NULL
         AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                           'late_reg_adjustment', 'clawback', 'spin_backpay',
                           'overlay_backpay')
              OR EXISTS (
                SELECT 1 FROM public.tournament_obligations eo
                 WHERE eo.tournament_id = p_tournament_id
                   AND eo.kind = 'place' AND eo.place = p.position
                   AND eo.user_id = p.user_id
                   AND p.idempotency_key LIKE
                     'tourney:' || p_tournament_id::text || ':obl:' ||
                     eo.id::text || ':%'
              ))
       GROUP BY p.position, p.user_id
      HAVING abs(round(sum(p.amount), 2)) > 0.005
    ) evidence
   WHERE NOT EXISTS (
     SELECT 1 FROM jsonb_to_recordset(v_place_plan)
       AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
      WHERE x.place = evidence.position AND x.user_id = evidence.user_id
   );
  IF v_conflicts > 0 THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'paid_place_evidence_is_outside_deal_plan',
                              'rows', v_conflicts, 'paid', 0,
                              'completed', false, 'retryable', false);
  END IF;

  SELECT count(*) INTO v_conflicts
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_to_recordset(v_place_plan)
         AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
        WHERE x.place = o.place AND x.user_id = o.user_id
     );
  IF v_conflicts > 0 THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'place_obligation_is_outside_deal_plan',
                              'rows', v_conflicts, 'paid', 0,
                              'completed', false, 'retryable', false);
  END IF;

  v_available_cents := v_pool_cents - v_place_total_cents;
  IF v_available_cents < 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'earned_places_exceed_prize_pool',
                              'earned_place_cents', v_place_total_cents,
                              'pool_cents', v_pool_cents, 'paid', 0,
                              'completed', false, 'retryable', false);
  END IF;

  SELECT sum(s.chips) INTO v_total_chips
    FROM jsonb_to_recordset(v_live_input_snapshot)
      AS s(player_id uuid, user_id uuid, chips numeric,
           registered_at_utc text, rebuys integer, add_on boolean,
           seat_id uuid, table_id uuid, seat_stack numeric);

  SELECT s.user_id INTO v_leader
    FROM jsonb_to_recordset(v_live_input_snapshot)
      AS s(player_id uuid, user_id uuid, chips numeric,
           registered_at_utc text, rebuys integer, add_on boolean,
           seat_id uuid, table_id uuid, seat_stack numeric)
   ORDER BY s.chips DESC, s.registered_at_utc ASC, s.user_id ASC
   LIMIT 1;

  FOR r IN
    SELECT s.user_id, s.chips
      FROM jsonb_to_recordset(v_live_input_snapshot)
        AS s(player_id uuid, user_id uuid, chips numeric,
             registered_at_utc text, rebuys integer, add_on boolean,
             seat_id uuid, table_id uuid, seat_stack numeric)
     ORDER BY s.chips DESC, s.registered_at_utc ASC, s.user_id ASC
  LOOP
    v_rank := v_rank + 1;
    v_share_cents := floor(r.chips / v_total_chips * v_available_cents)::bigint;
    v_floor_paid_cents := v_floor_paid_cents + v_share_cents;
    v_deal_shares := v_deal_shares || jsonb_build_array(jsonb_build_object(
      'user_id', r.user_id, 'cents', v_share_cents, 'rank', v_rank));
  END LOOP;
  v_remainder_cents := v_available_cents - v_floor_paid_cents;

  FOR r IN
    SELECT (p->>'user_id')::uuid AS user_id,
           (p->>'cents')::bigint AS cents,
           (p->>'rank')::integer AS rank
      FROM jsonb_array_elements(v_deal_shares) p
     ORDER BY (p->>'rank')::integer
  LOOP
    v_share_cents := r.cents
      + CASE WHEN r.user_id = v_leader THEN v_remainder_cents ELSE 0 END;
    v_deal_plan := v_deal_plan || jsonb_build_array(jsonb_build_object(
      'kind', 'final_table_deal', 'place', NULL, 'user_id', r.user_id,
      'cents', v_share_cents, 'rank', r.rank));
    v_deal_total_cents := v_deal_total_cents + v_share_cents;
    v_payouts := v_payouts || jsonb_build_array(jsonb_build_object(
      'user_id', r.user_id, 'amount', v_share_cents / 100.0, 'rank', r.rank));
  END LOOP;

  IF v_place_total_cents + v_deal_total_cents <> v_pool_cents THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'deal_plan_does_not_allocate_pool',
                              'places', v_place_total_cents / 100.0,
                              'deal', v_deal_total_cents / 100.0,
                              'pool', v_pool_cents / 100.0, 'paid', 0,
                              'completed', false, 'retryable', false);
  END IF;

  /* A finalized number is not money. Lock the enforced escrow row and prove
     it holds every cent this transaction still needs to move. A manually
     inflated prize_pool/prize_pool_finalized pair therefore cannot authorize
     a deal. Prior place payments backed by exact payout evidence are the only
  subtraction from the required cash. */
  v_unpaid_cents := v_pool_cents - v_prior_place_paid_cents;
  v_total_unpaid_cents := v_unpaid_cents + v_bubble_unpaid_cents;
  SELECT * INTO v_escrow
    FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND OR NOT v_escrow.enforced THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'enforced_escrow_is_required',
                              'required', v_total_unpaid_cents / 100.0,
                              'place_and_deal_required', v_unpaid_cents / 100.0,
                              'bubble_required', v_bubble_unpaid_cents / 100.0,
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;
  IF round(v_escrow.prize_balance * 100)::bigint < v_total_unpaid_cents THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'escrow_cannot_fund_atomic_deal',
                              'required', v_total_unpaid_cents / 100.0,
                              'place_and_deal_required', v_unpaid_cents / 100.0,
                              'bubble_required', v_bubble_unpaid_cents / 100.0,
                              'escrow_prize_balance', v_escrow.prize_balance,
                              'paid', 0, 'completed', false, 'retryable', false);
  END IF;

  v_plan := v_place_plan || v_deal_plan;
  v_plan_fingerprint := md5(jsonb_build_object(
    'bubble_contract_required', v_bubble_required,
    'bubble_obligation_id', v_bubble_obligation_id,
    'bubble_user_id', v_bubble_user,
    'bubble_source', v_bubble_source,
    'bubble_amount_owed', round(COALESCE(v_bubble_owed, 0) * 100)::bigint,
    'bubble_amount_paid_before', round(COALESCE(v_bubble_paid, 0) * 100)::bigint,
    'deal_table_id', v_deal_table_id,
    'live_input_fingerprint', v_live_input_fingerprint,
    'prior_standings_fingerprint', v_prior_standings_fingerprint,
    'plan', v_plan)::text);

  BEGIN
    /* The format-owned transaction claims its terminal work before moving
       any money. This is intentionally inside the exception subtransaction:
       any failed prize, bounty or rake leg restores RUNNING together with
       every balance. It also gives the rake contract the terminal-in-progress
       status it requires without an application-side status writer. */
    PERFORM set_config('app.atomic_final_table_deal_batch', p_tournament_id::text, true);
    UPDATE public.tournaments
       SET status = 'COMPLETING', updated_at = now()
     WHERE id = p_tournament_id AND status = 'RUNNING';
    IF NOT FOUND THEN
      RAISE EXCEPTION USING MESSAGE = 'RUNNING claim was lost before deal settlement',
                            ERRCODE = '40001';
    END IF;

    IF v_bubble_needs_insert THEN
      INSERT INTO public.tournament_obligations
        (id, tournament_id, kind, place, user_id, amount_owed, amount_paid,
         source, settled_at)
      VALUES
        (v_bubble_obligation_id, p_tournament_id, 'bubble_protection', NULL,
         v_bubble_user, v_bubble_owed, 0, v_bubble_source, NULL);
    END IF;

    FOR r IN
      SELECT (p->>'place')::integer AS place,
             (p->>'user_id')::uuid AS user_id,
             (p->>'cents')::bigint AS cents
        FROM jsonb_array_elements(v_place_plan) p
       ORDER BY (p->>'place')::integer
    LOOP
      SELECT round(COALESCE(sum(p.amount), 0), 2)
        INTO v_seeded_paid
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.position = r.place AND p.user_id = r.user_id
         AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                           'late_reg_adjustment', 'clawback', 'spin_backpay',
                           'overlay_backpay')
              OR EXISTS (
                SELECT 1 FROM public.tournament_obligations eo
                 WHERE eo.tournament_id = p_tournament_id
                   AND eo.kind = 'place' AND eo.place = r.place
                   AND eo.user_id = r.user_id
                   AND p.idempotency_key LIKE
                     'tourney:' || p_tournament_id::text || ':obl:' ||
                     eo.id::text || ':%'
              ));

      INSERT INTO public.tournament_obligations
        (tournament_id, kind, place, user_id, amount_owed, amount_paid,
         source, settled_at)
      VALUES
        (p_tournament_id, 'place', r.place, r.user_id, r.cents / 100.0,
         v_seeded_paid, 'engine.atomicFinalTableDeal',
         CASE WHEN v_seeded_paid + 0.005 >= r.cents / 100.0 THEN now() ELSE NULL END)
      ON CONFLICT (tournament_id, kind, place) WHERE place IS NOT NULL
      DO UPDATE SET
        user_id = EXCLUDED.user_id,
        amount_owed = EXCLUDED.amount_owed,
        amount_paid = EXCLUDED.amount_paid,
        source = EXCLUDED.source,
        updated_at = now(),
        settled_at = EXCLUDED.settled_at;
    END LOOP;

    FOR r IN
      SELECT (p->>'user_id')::uuid AS user_id,
             (p->>'cents')::bigint AS cents,
             (p->>'rank')::integer AS rank
        FROM jsonb_array_elements(v_deal_plan) p
       ORDER BY (p->>'rank')::integer
    LOOP
      INSERT INTO public.tournament_obligations
        (tournament_id, kind, place, user_id, amount_owed, amount_paid,
         source, settled_at)
      VALUES
        (p_tournament_id, 'final_table_deal', NULL, r.user_id,
         r.cents / 100.0, 0, 'engine.atomicFinalTableDeal',
         CASE WHEN r.cents = 0 THEN now() ELSE NULL END);
    END LOOP;

    UPDATE public.tournament_players tp
       SET prize = COALESCE((
             SELECT sum(x.cents) / 100.0
               FROM jsonb_to_recordset(v_plan)
                 AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
              WHERE x.user_id = tp.user_id
           ), 0)
     WHERE tp.tournament_id = p_tournament_id;

    FOR r IN
      SELECT (p->>'user_id')::uuid AS user_id,
             (p->>'rank')::integer AS rank
        FROM jsonb_array_elements(v_deal_plan) p
       ORDER BY (p->>'rank')::integer
    LOOP
      UPDATE public.tournament_players
         SET position = r.rank,
             status = CASE WHEN r.rank = 1 THEN 'winner' ELSE 'eliminated' END,
             eliminated_at = CASE
               WHEN r.rank = 1 THEN NULL
               ELSE COALESCE(eliminated_at, clock_timestamp())
             END
       WHERE tournament_id = p_tournament_id AND user_id = r.user_id
         AND status = 'playing' AND eliminated_at IS NULL;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = format(
          'live deal player %s changed before standings were stamped', r.user_id),
          ERRCODE = '40001';
      END IF;
    END LOOP;

    /* Stamping precedes the immutable batch inside this same subtransaction.
       The result-freeze trigger recognizes the batch immediately after this
       insert, without blocking the settler's own legitimate stamps above. */
    INSERT INTO public.tournament_final_table_deal_batches
      (tournament_id, plan_fingerprint, plan, prior_standings_fingerprint,
       live_input_snapshot, live_input_fingerprint,
       field_count, live_count, structure_place_count, place_line_count,
       deal_line_count, place_amount, deal_amount, amount_owed, amount_moved,
       escrow_prize_before, escrow_prize_after, deal_table_id,
       bubble_contract_required, bubble_obligation_id, bubble_user_id,
       bubble_source, bubble_amount_owed, bubble_amount_paid_before,
       chip_leader, source)
    VALUES
      (p_tournament_id, v_plan_fingerprint, v_plan,
       v_prior_standings_fingerprint, v_live_input_snapshot,
       v_live_input_fingerprint, v_field_count, v_live_count,
       v_structure_places, jsonb_array_length(v_place_plan),
       jsonb_array_length(v_deal_plan), v_place_total_cents / 100.0,
       v_deal_total_cents / 100.0, v_pool_cents / 100.0,
       v_total_unpaid_cents / 100.0, v_escrow.prize_balance, NULL, v_deal_table_id,
       v_bubble_required, v_bubble_obligation_id, v_bubble_user,
       v_bubble_source, v_bubble_owed, v_bubble_paid,
       v_leader, 'engine.atomicFinalTableDeal');

    IF v_bubble_required AND v_bubble_unpaid_cents > 0 THEN
      v_result := public.fn_settle_tournament_obligation_before_atomic_batch_gate(
        p_tournament_id, 'bubble_protection', NULL, v_bubble_user,
        v_bubble_owed, v_bubble_source,
        'Bubble protection: buy-in returned to the stone bubble', NULL);
      IF NOT COALESCE((v_result->>'ok')::boolean, false)
         OR NULLIF(v_result->>'obligation_id', '')::uuid
            IS DISTINCT FROM v_bubble_obligation_id THEN
        RAISE EXCEPTION USING MESSAGE = format(
          'atomic final-table-deal Bubble leg refused: %s',
          COALESCE(v_result->>'refused_reason', 'wrong obligation')),
          ERRCODE = '23514';
      END IF;

      SELECT o.amount_paid, o.source, o.amount_owed, o.settled_at
        INTO v_after_bubble_paid, v_bubble_source, v_bubble_owed,
             v_bubble_settled_at
        FROM public.tournament_obligations o
       WHERE o.id = v_bubble_obligation_id
         AND o.tournament_id = p_tournament_id
         AND o.kind = 'bubble_protection'
         AND o.place IS NULL AND o.user_id = v_bubble_user;
      IF NOT FOUND
         OR COALESCE(v_bubble_source, '') NOT IN ('engine.eliminatePlayer', 'engine.atomicFinalTableDeal')
         OR v_after_bubble_paid + 0.005 < v_bubble_owed
         OR v_bubble_settled_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = format(
          'atomic final-table-deal Bubble leg only reached %s of %s',
          COALESCE(v_after_bubble_paid, 0), v_bubble_owed),
          ERRCODE = '23514';
      END IF;
      v_bubble_paid_this_call := round(
        COALESCE((v_result->>'paid')::numeric, 0), 2);
      v_paid_this_call := v_paid_this_call + v_bubble_paid_this_call;
    END IF;

    FOR r IN
      SELECT x.kind, x.place, x.user_id, x.cents, x.rank
        FROM jsonb_to_recordset(v_plan)
          AS x(kind text, place integer, user_id uuid, cents bigint, rank integer)
       ORDER BY CASE WHEN x.kind = 'place' THEN 0 ELSE 1 END,
                x.place NULLS LAST, x.rank NULLS LAST
    LOOP
      v_result := public.fn_settle_tournament_obligation_before_atomic_batch_gate(
        p_tournament_id, r.kind, r.place, r.user_id, r.cents / 100.0,
        'engine.atomicFinalTableDeal',
        CASE WHEN r.kind = 'place'
             THEN format('Tournament prize: position %s', r.place)
             ELSE 'Final table deal (chip-proportional chop)' END);
      IF NOT COALESCE((v_result->>'ok')::boolean, false) THEN
        RAISE EXCEPTION USING MESSAGE = format(
          'atomic final-table-deal leg refused for %s/%s/%s: %s',
          r.kind, COALESCE(r.place::text, '-'), r.user_id,
          COALESCE(v_result->>'refused_reason', 'unknown')),
          ERRCODE = '23514';
      END IF;

      SELECT o.amount_paid INTO v_after_paid
        FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id AND o.kind = r.kind
         AND o.user_id = r.user_id
         AND ((r.kind = 'place' AND o.place = r.place)
              OR (r.kind = 'final_table_deal' AND o.place IS NULL));
      IF NOT FOUND OR abs(round(v_after_paid, 2) - r.cents / 100.0) > 0.005 THEN
        RAISE EXCEPTION USING MESSAGE = format(
          'atomic final-table-deal leg partially settled for %s/%s/%s: expected %s, stored %s',
          r.kind, COALESCE(r.place::text, '-'), r.user_id,
          r.cents / 100.0, COALESCE(v_after_paid, 0)),
          ERRCODE = '23514';
      END IF;

      v_paid_this_call := v_paid_this_call
        + round(COALESCE((v_result->>'paid')::numeric, 0), 2);
      IF r.kind = 'place' THEN
        v_place_paid_this_call := v_place_paid_this_call
          + round(COALESCE((v_result->>'paid')::numeric, 0), 2);
      ELSE
        v_deal_paid_this_call := v_deal_paid_this_call
          + round(COALESCE((v_result->>'paid')::numeric, 0), 2);
      END IF;
    END LOOP;

    IF v_bubble_required THEN
      SELECT o.amount_paid, o.source, o.amount_owed, o.settled_at
        INTO v_after_bubble_paid, v_bubble_source, v_bubble_owed,
             v_bubble_settled_at
        FROM public.tournament_obligations o
       WHERE o.id = v_bubble_obligation_id
         AND o.tournament_id = p_tournament_id
         AND o.kind = 'bubble_protection'
         AND o.place IS NULL AND o.user_id = v_bubble_user;
      v_bubble_row_found := FOUND;
      SELECT round(COALESCE(sum(p.amount), 0), 2)
        INTO v_bubble_evidence
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.user_id = v_bubble_user
         AND p.position IS NULL AND p.source = 'bubble_protection';
      IF NOT v_bubble_row_found
         OR COALESCE(v_bubble_source, '') NOT IN ('engine.eliminatePlayer', 'engine.atomicFinalTableDeal')
         OR v_after_bubble_paid + 0.005 < v_bubble_owed
         OR v_bubble_settled_at IS NULL
         OR abs(v_after_bubble_paid - v_bubble_evidence) > 0.005 THEN
        RAISE EXCEPTION USING MESSAGE =
          'Bubble Protection is not fully settled with exact payout evidence',
          ERRCODE = '23514';
      END IF;
    END IF;

    IF abs(v_paid_this_call - v_total_unpaid_cents / 100.0) > 0.005 THEN
      RAISE EXCEPTION USING MESSAGE = format(
        'atomic final-table-deal payment total was incomplete: expected %s, moved %s',
        v_total_unpaid_cents / 100.0, v_paid_this_call),
        ERRCODE = '23514';
    END IF;

    SELECT round(e.prize_balance, 2) INTO v_escrow_after
      FROM public.tournament_escrow e
     WHERE e.tournament_id = p_tournament_id
     FOR UPDATE;
    IF NOT FOUND
       OR abs(v_escrow.prize_balance - v_paid_this_call - v_escrow_after) > 0.005 THEN
      RAISE EXCEPTION USING MESSAGE = format(
        'escrow did not debit with the atomic deal: before %s, moved %s, after %s',
        v_escrow.prize_balance, v_paid_this_call, COALESCE(v_escrow_after, 0)),
        ERRCODE = '23514';
    END IF;

    UPDATE public.tournament_final_table_deal_batches
       SET settled_at = COALESCE(settled_at, now()),
           escrow_prize_after = v_escrow_after
     WHERE tournament_id = p_tournament_id
       AND plan_fingerprint = v_plan_fingerprint;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING MESSAGE = 'the final-table-deal batch changed before completion',
                            ERRCODE = '40001';
    END IF;

    v_check := public.fn_check_atomic_final_table_deal(p_tournament_id);
    IF NOT COALESCE((v_check->>'ok')::boolean, false) THEN
      RAISE EXCEPTION USING MESSAGE = format(
        'atomic final-table-deal verification refused completion: %s', v_check::text),
        ERRCODE = '23514';
    END IF;

    /* Completion certification requires every financial domain, so the deal
       transaction owns those terminal legs too. Calling the existing guarded
       functions here keeps their immutable receipts and rolls their wallet
       effects back if any later readiness proof fails. */
    IF v_t.is_bounty OR v_t.is_pko OR v_t.is_mystery_bounty THEN
      IF public.fn_tournament_has_unsettled_bounties(p_tournament_id) THEN
        RAISE EXCEPTION USING MESSAGE = 'pending bounty obligations block final-table deal completion',
                              ERRCODE = '23514';
      END IF;
      IF v_t.is_mystery_bounty AND v_t.mystery_bounty_stage <> 'pending' THEN
        v_result := public.fn_mystery_bounty_settle(p_tournament_id, v_leader);
        IF NOT COALESCE((v_result->>'ok')::boolean, false)
           OR NOT COALESCE((v_result->>'balanced')::boolean, false) THEN
          RAISE EXCEPTION USING MESSAGE = format(
            'atomic final-table-deal mystery bounty leg refused: %s', v_result::text),
                                ERRCODE = '23514';
        END IF;
      END IF;
      v_result := public.fn_finalize_bounty_pool(p_tournament_id, v_leader);
      IF NOT COALESCE((v_result->>'ok')::boolean, false) THEN
        RAISE EXCEPTION USING MESSAGE = format(
          'atomic final-table-deal bounty pool leg refused: %s', v_result::text),
                              ERRCODE = '23514';
      END IF;
    END IF;

    v_result := public.fn_settle_tournament_rake(
      p_tournament_id, 'engine.atomicFinalTableDeal');
    IF NOT COALESCE((v_result->>'ok')::boolean, false) THEN
      RAISE EXCEPTION USING MESSAGE = format(
        'atomic final-table-deal rake leg refused: %s', v_result::text),
                            ERRCODE = '23514';
    END IF;

    UPDATE public.tournaments
       SET status = 'COMPLETED', ended_at = COALESCE(ended_at, clock_timestamp()),
           on_break = false, break_ends_at = NULL, updated_at = now()
     WHERE id = p_tournament_id AND status = 'COMPLETING';
    IF NOT FOUND THEN
      RAISE EXCEPTION USING MESSAGE = 'RUNNING claim was lost before deal completion',
                            ERRCODE = '40001';
    END IF;

    /* A committed deal includes its physical table shutdown. The status
       transition releases seats through the database triggers; any failure to
       close or prove the terminal table state aborts every deal payment too. */
    UPDATE public.tables
       SET status = 'closed', current_players = 0
     WHERE tournament_id = p_tournament_id
       AND (status IS DISTINCT FROM 'closed' OR current_players IS DISTINCT FROM 0);
    IF EXISTS (
         SELECT 1 FROM public.tables
          WHERE tournament_id = p_tournament_id
            AND (status IS DISTINCT FROM 'closed' OR current_players IS DISTINCT FROM 0)
       ) OR EXISTS (
         SELECT 1
           FROM public.table_seats s
           JOIN public.tables tb ON tb.id = s.table_id
          WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL
       ) THEN
      RAISE EXCEPTION USING
        MESSAGE = 'completed final-table deal retained a nonterminal table or live seat',
        ERRCODE = '23514';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_failure = MESSAGE_TEXT,
                            v_failure_state = RETURNED_SQLSTATE;
  END;

  PERFORM set_config('app.atomic_final_table_deal_batch', '', true);

  IF v_failure IS NOT NULL THEN
    BEGIN
      PERFORM public.fn_raise_server_financial_alert(
        'critical', 'fn_settle_final_table_deal_atomic',
        format('Atomic final-table deal aborted for %s: %s',
               COALESCE(v_t.name, p_tournament_id::text), v_failure),
        jsonb_build_object('tournament_id', p_tournament_id,
                           'sqlstate', v_failure_state,
                           'reason', v_failure,
                           'field_count', v_field_count,
                           'live_count', v_live_count,
                           'place_amount', v_place_total_cents / 100.0,
                           'deal_amount', v_deal_total_cents / 100.0),
        'atomic-final-table-deal:' || p_tournament_id::text
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'atomic_deal_aborted', 'detail', v_failure,
      'sqlstate', v_failure_state, 'paid', 0, 'completed', false,
      'retryable', v_failure_state IN ('40001', '40P01', '55P03'));
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'paid', round(v_paid_this_call, 2),
    'place_paid', round(v_place_paid_this_call, 2),
    'deal_paid', round(v_deal_paid_this_call, 2),
    'bubble_paid', round(v_bubble_paid_this_call, 2),
    'completed', true, 'already_completed', false,
    'players', v_live_count, 'chip_leader', v_leader,
    'deal_table_id', v_deal_table_id,
    'bubble_contract_required', v_bubble_required,
    'bubble_obligation_id', v_bubble_obligation_id,
    'place_amount', v_place_total_cents / 100.0,
    'deal_amount', v_deal_total_cents / 100.0,
    'payouts', v_payouts, 'retryable', false,
    'record', 'tournament_final_table_deal_batches');
END;
$_$;


ALTER FUNCTION public.fn_settle_final_table_deal_atomic(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_settle_final_table_deal_atomic(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settle_final_table_deal_atomic(p_tournament_id uuid) IS 'Atomically pays exact ledger-backed eliminated place entitlements and every live chip-proportional deal share, stamps standings, and completes the tournament. Any refused or partial leg rolls the whole deal back.';


--
-- Name: fn_settle_round2_club_to_agents(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_round2_club_to_agents(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record; v_club_bal numeric; v_paid numeric := 0;
  v_payees int := 0; v_short int := 0; v_detail jsonb := '[]'::jsonb;
  v_debit jsonb; v_agent_bal numeric; v_pairs jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR NOT public.fn_is_union_overseer(p_union_id, auth.uid())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;
  IF EXISTS (SELECT 1 FROM settlement_locks WHERE lock_type = 'GLOBAL_SETTLEMENT_FREEZE' AND is_active = true) THEN
    RAISE EXCEPTION 'EMERGENCY_PROFIT_DRIFT_LOCK';
  END IF;
  IF p_union_id IS NULL OR p_period_start IS NULL OR p_period_end IS NULL OR p_period_end <= p_period_start THEN
    RETURN jsonb_build_object('round', 2, 'name', 'club_to_agents', 'success', false, 'error', 'bad_params',
                              'payees', 0, 'amount', 0, 'shortfalls', 0, 'detail', '[]'::jsonb);
  END IF;
  /* A row's created_at is its transaction's start. The longest transaction that
     writes agent_commissions is an eight-second engine call; five minutes after
     the period closes, nothing that began inside it is still in flight. Before
     that, a period recorded as paid could swallow a row that landed late. */
  IF p_period_end > now() - interval '5 minutes' THEN
    RETURN jsonb_build_object('round', 2, 'name', 'club_to_agents', 'success', false, 'retryable', true,
                              'error', 'period_too_fresh', 'period_end', p_period_end,
                              'payees', 0, 'amount', 0, 'shortfalls', 0, 'detail', '[]'::jsonb);
  END IF;

  /* What each pair is owed INSIDE this period: unstamped, and not already
     covered by a settlement row. One index scan per pair, no materialised set. */
  FOR r IN
    SELECT ac.club_id, ac.user_id AS agent_user, SUM(ac.amount) AS owed, count(*) AS n
      FROM agent_commissions ac
      JOIN union_clubs uc ON uc.club_id = ac.club_id AND uc.union_id = p_union_id
      JOIN agents a ON a.user_id = ac.user_id AND a.club_id = ac.club_id AND a.status = 'active'
     WHERE ac.created_at >= p_period_start AND ac.created_at < p_period_end
       AND ac.settled_at IS NULL
       AND NOT EXISTS (SELECT 1 FROM agent_commission_settlements s
                        WHERE s.club_id = ac.club_id AND s.user_id = ac.user_id
                          AND ac.created_at >= s.period_start AND ac.created_at < s.period_end)
     GROUP BY ac.club_id, ac.user_id
    HAVING SUM(ac.amount) > 0
     ORDER BY 1, 2
  LOOP
    -- Same pot Round 1 credits (clubs.chip_treasury), not club_wallets.
    SELECT COALESCE(chip_treasury, 0) INTO v_club_bal FROM clubs WHERE id = r.club_id FOR UPDATE;

    IF COALESCE(v_club_bal, 0) < r.owed THEN
      v_short := v_short + 1;
      v_detail := v_detail || jsonb_build_object('club_id', r.club_id, 'agent', r.agent_user,
                    'owed', r.owed, 'club_treasury', COALESCE(v_club_bal, 0), 'skipped', true);
      CONTINUE;
    END IF;

    v_debit := public.fn_debit_treasury(
      r.club_id, r.owed,
      'Round 2: club -> agent commission',
      jsonb_build_object('union_id', p_union_id, 'agent_user_id', r.agent_user,
                         'period_start', p_period_start, 'period_end', p_period_end));
    IF COALESCE((v_debit->>'success')::boolean, false) IS NOT TRUE THEN
      v_short := v_short + 1;
      v_detail := v_detail || jsonb_build_object('club_id', r.club_id, 'agent', r.agent_user,
                    'owed', r.owed, 'error', v_debit, 'skipped', true);
      CONTINUE;
    END IF;

    PERFORM public.fn_ensure_club_wallet(r.agent_user, r.club_id);
    UPDATE club_members
       SET chip_balance = COALESCE(chip_balance, 0) + r.owed, updated_at = now()
     WHERE user_id = r.agent_user AND club_id = r.club_id
     RETURNING chip_balance INTO v_agent_bal;

    /* THE RECORD, instead of two million stamps: one row says this pair's
       rows inside this period are paid. A second call finds no open rows
       inside the period and pays nothing. */
    INSERT INTO public.agent_commission_settlements
      (club_id, user_id, union_id, period_start, period_end, amount, rows_count, paid_at, settlement_ref)
    VALUES (r.club_id, r.agent_user, p_union_id, p_period_start, p_period_end, round(r.owed, 2), r.n, now(),
            'round2:' || p_union_id::text || ':' || to_char(p_period_start at time zone 'UTC', 'YYYY-MM-DD'))
    ON CONFLICT (club_id, user_id, period_start, period_end) DO NOTHING;

    -- Both sides of the entry: club-side debit above, agent credit here.
    INSERT INTO wallet_transactions
      (user_id, wallet_type, type, amount, category, description, balance_after)
    VALUES
      (r.agent_user, 'PLAYER', 'credit', r.owed, 'commission',
       'Round 2: club -> agent commission [club wallet]', v_agent_bal);

    /* CONTROL (phase 8): the same movement as two balanced legs, on the
       journal fn_ca_trial_balance reads. */
    INSERT INTO public.chip_ledger
      (performed_by, from_type, from_entity_id, to_type, to_entity_id,
       amount, category, club_id, union_id, description, idempotency_key, metadata)
    VALUES
      (COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
       'club_treasury', r.club_id, 'player_wallet', r.agent_user,
       round(r.owed, 2), 'commission', r.club_id, p_union_id,
       'Round 2: club -> agent commission (period '
         || to_char(p_period_start, 'YYYY-MM-DD') || '..'
         || to_char(p_period_end, 'YYYY-MM-DD') || ')',
       'round2:' || p_union_id::text || ':'
         || to_char(p_period_start at time zone 'UTC', 'YYYY-MM-DD') || ':'
         || r.club_id::text || ':' || r.agent_user::text,
       jsonb_build_object('period_start', p_period_start, 'period_end', p_period_end,
                          'rows_count', r.n, 'agent_balance_after', v_agent_bal))
    ON CONFLICT DO NOTHING;

    v_pairs := v_pairs || jsonb_build_object('club_id', r.club_id, 'user_id', r.agent_user);
    v_paid := v_paid + r.owed;
    v_payees := v_payees + 1;
  END LOOP;

  IF v_pairs <> '[]'::jsonb THEN
    PERFORM public.fn_agent_commission_rollup_recompute(v_pairs);
  END IF;

  RETURN jsonb_build_object('round', 2, 'name', 'club_to_agents',
    'payees', v_payees, 'amount', round(v_paid, 2), 'shortfalls', v_short, 'detail', v_detail);
END
$$;


ALTER FUNCTION public.fn_settle_round2_club_to_agents(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_settle_round3_agents_to_players(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_round3_agents_to_players(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record; v_agent_bal numeric; v_paid numeric := 0;
  v_payees int := 0; v_short int := 0; v_detail jsonb := '[]'::jsonb;
BEGIN

  IF EXISTS (SELECT 1 FROM settlement_locks WHERE lock_type = 'GLOBAL_SETTLEMENT_FREEZE' AND is_active = true) THEN
    RAISE EXCEPTION 'EMERGENCY_PROFIT_DRIFT_LOCK';
  END IF;
  FOR r IN
    SELECT rp.user_id AS player_id, rp.club_id, cm.agent_id AS agent_user,
           SUM(rp.rakeback_amount) AS owed
      FROM rakeback_periods rp
      JOIN union_clubs uc ON uc.club_id = rp.club_id AND uc.union_id = p_union_id
      JOIN club_members cm ON cm.user_id = rp.user_id AND cm.club_id = rp.club_id
     WHERE rp.status = 'pending'
       AND rp.period_start >= p_period_start::date
       AND rp.period_start <  p_period_end::date + 1
       AND cm.agent_id IS NOT NULL
     GROUP BY rp.user_id, rp.club_id, cm.agent_id
    HAVING SUM(rp.rakeback_amount) > 0
     ORDER BY 2,3,1
  LOOP
    SELECT chip_balance INTO v_agent_bal
      FROM club_members WHERE user_id = r.agent_user AND club_id = r.club_id FOR UPDATE;

    IF COALESCE(v_agent_bal,0) < r.owed THEN
      v_short := v_short + 1;
      v_detail := v_detail || jsonb_build_object('agent', r.agent_user, 'player', r.player_id,
                    'owed', r.owed, 'agent_balance', COALESCE(v_agent_bal,0), 'skipped', true);
      CONTINUE;
    END IF;

    UPDATE club_members SET chip_balance = chip_balance - r.owed, updated_at = now()
     WHERE user_id = r.agent_user AND club_id = r.club_id;

    PERFORM public.fn_ensure_club_wallet(r.player_id, r.club_id);
    UPDATE club_members SET chip_balance = COALESCE(chip_balance,0) + r.owed, updated_at = now()
     WHERE user_id = r.player_id AND club_id = r.club_id;

    UPDATE rakeback_periods
       SET status = 'paid', paid_at = now()
     WHERE user_id = r.player_id AND club_id = r.club_id AND status = 'pending'
       AND period_start >= p_period_start::date AND period_start < p_period_end::date + 1;

    INSERT INTO wallet_transactions
      (user_id, wallet_type, type, amount, category, description, balance_after)
    SELECT r.player_id, 'PLAYER', 'credit', r.owed, 'rakeback',
           'Round 3: agent -> player rakeback [club wallet]', cm.chip_balance
      FROM club_members cm WHERE cm.user_id = r.player_id AND cm.club_id = r.club_id;

    /* CONTROL (phase 8): the same movement as a balanced leg on the journal.
       Both sides are member wallets, so the trial balance nets them to zero
       and cannot see this; fn_ca_ledger_replay is per account owner and can. */
    INSERT INTO public.chip_ledger
      (performed_by, from_type, from_entity_id, to_type, to_entity_id,
       amount, category, club_id, union_id, description, idempotency_key, metadata)
    VALUES
      (COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
       'player_wallet', r.agent_user, 'player_wallet', r.player_id,
       round(r.owed, 2), 'rakeback', r.club_id, p_union_id,
       'Round 3: agent -> player rakeback (period '
         || to_char(p_period_start, 'YYYY-MM-DD') || '..'
         || to_char(p_period_end, 'YYYY-MM-DD') || ')',
       'round3:' || p_union_id::text || ':'
         || to_char(p_period_start at time zone 'UTC', 'YYYY-MM-DD') || ':'
         || r.club_id::text || ':' || r.agent_user::text || ':' || r.player_id::text,
       jsonb_build_object('period_start', p_period_start, 'period_end', p_period_end))
    ON CONFLICT DO NOTHING;

    v_paid := v_paid + r.owed;
    v_payees := v_payees + 1;
  END LOOP;

  RETURN jsonb_build_object('round', 3, 'name', 'agents_to_players',
    'payees', v_payees, 'amount', round(v_paid,2), 'shortfalls', v_short, 'detail', v_detail);
END $$;


ALTER FUNCTION public.fn_settle_round3_agents_to_players(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_settle_satellite_cash_entitlement_exact(uuid, text, integer, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_satellite_cash_entitlement_exact(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_count integer;
  v_id uuid;
BEGIN
  IF round(COALESCE(p_amount,0),2)<=0 THEN RETURN NULL; END IF;
  v_result:=public.fn_settle_tournament_obligation_before_atomic_batch_gate(
    p_tournament_id,p_kind,p_place,p_user_id,round(p_amount,2),p_source,
    CASE WHEN p_kind='satellite_remainder' THEN 'Satellite cash remainder'
         ELSE format('Satellite place %s cash entitlement',p_place) END,NULL);
  SELECT count(*)::integer,(array_agg(o.id ORDER BY o.id))[1] INTO v_count,v_id
    FROM public.tournament_obligations o
   WHERE o.tournament_id=p_tournament_id AND o.kind=p_kind
     AND o.user_id=p_user_id AND o.place IS NOT DISTINCT FROM p_place
     AND round(o.amount_owed,2)=round(p_amount,2)
     AND round(o.amount_paid,2)=round(p_amount,2)
     AND o.settled_at IS NOT NULL;
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE OR v_count<>1 THEN
    RAISE EXCEPTION 'satellite cash entitlement did not settle exactly: %',
      COALESCE(v_result::text,'null') USING ERRCODE='check_violation';
  END IF;
  RETURN v_id;
END;
$$;


ALTER FUNCTION public.fn_settle_satellite_cash_entitlement_exact(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text) OWNER TO postgres;

--
-- Name: fn_settle_satellite_finish_atomic(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_satellite_finish_atomic(p_tournament_id uuid, p_source text DEFAULT 'engine.satellite_finish'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  RETURN public.fn_settle_satellite_finish_atomic_before_maintenance_gate(
    p_tournament_id, p_source
  );
END;
$$;


ALTER FUNCTION public.fn_settle_satellite_finish_atomic(p_tournament_id uuid, p_source text) OWNER TO postgres;

--
-- Name: fn_settle_satellite_finish_atomic_before_maintenance_gate(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_satellite_finish_atomic_before_maintenance_gate(p_tournament_id uuid, p_source text DEFAULT 'engine.satellite_finish'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_plan jsonb;
  v_t public.tournaments%ROWTYPE;
  v_batch public.tournament_satellite_settlement_batches%ROWTYPE;
  v_winner uuid;
  v_player_count integer;
  v_terminal_count integer;
  v_ranked_count integer;
  v_fingerprint text;
  v_count integer;
  v_depth integer;
  v_amount numeric;
  v_delivery jsonb;
  v_ticket_obligation uuid;
  v_remainder_obligation uuid;
  v_outcomes jsonb:='[]'::jsonb;
  v_check jsonb;
  v_rows integer;
  v_rake_expected numeric;
  v_rake_rows integer;
  v_rake_amount numeric;
  v_rake_destination text;
  v_rake_settled_at timestamptz;
  v_rake_attributed_at timestamptz;
  v_bounty public.tournament_bounty_completion_receipts%ROWTYPE;
  e public.tournament_satellite_entitlements%ROWTYPE;
  p public.tournament_players%ROWTYPE;
BEGIN
  v_plan:=public.fn_materialize_satellite_entitlements_locked(p_tournament_id);
  IF COALESCE((v_plan->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_plan->>'is_satellite')::boolean,false) IS NOT TRUE
     OR COALESCE((v_plan->>'ready')::boolean,false) IS NOT TRUE THEN
    RETURN v_plan || jsonb_build_object('settled',false);
  END IF;
  SELECT * INTO v_t FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  SELECT * INTO v_batch FROM public.tournament_satellite_settlement_batches
   WHERE tournament_id=p_tournament_id FOR UPDATE;
  IF FOUND AND v_batch.settled_at IS NOT NULL THEN
    v_check:=public.fn_check_atomic_satellite_finish(p_tournament_id);
    RETURN v_check || jsonb_build_object('settled',true,'already_settled',true,
                                         'rows_updated',0);
  END IF;
  IF v_t.status<>'COMPLETING' THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_not_completing',
                              'status',v_t.status,'settled',false);
  END IF;

  SELECT count(*)::integer,
         count(*) FILTER (WHERE tp.status IN ('winner','eliminated'))::integer,
         count(DISTINCT tp.position)::integer,
         (array_agg(tp.user_id ORDER BY tp.user_id)
           FILTER (WHERE tp.status='winner' AND tp.position=1))[1]
    INTO v_player_count,v_terminal_count,v_ranked_count,v_winner
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id;
  IF v_player_count<1 OR v_terminal_count<>v_player_count
     OR v_ranked_count<>v_player_count OR v_winner IS NULL
     OR (SELECT min(position) FROM public.tournament_players
          WHERE tournament_id=p_tournament_id)<>1
     OR (SELECT max(position) FROM public.tournament_players
          WHERE tournament_id=p_tournament_id)<>v_player_count THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_standings_not_terminal',
      'players',v_player_count,'terminal',v_terminal_count,'ranked',v_ranked_count,
      'settled',false);
  END IF;

  -- Do not even begin the all-or-none payout subtransaction until common
  -- terminal money work is durably complete. The postcondition repeats these
  -- proofs, closing the race between this read and the COMPLETED update.
  SELECT GREATEST(round(COALESCE(sum(rr.rake_amount),0),2),0)
    INTO v_rake_expected
    FROM public.rake_records rr
   WHERE rr.tournament_id=p_tournament_id AND rr.is_tournament;
  SELECT count(*)::integer,(array_agg(rs.amount ORDER BY rs.tournament_id))[1],
         (array_agg(rs.destination ORDER BY rs.tournament_id))[1],
         (array_agg(rs.settled_at ORDER BY rs.tournament_id))[1],
         (array_agg(rs.attributed_at ORDER BY rs.tournament_id))[1]
    INTO v_rake_rows,v_rake_amount,v_rake_destination,
         v_rake_settled_at,v_rake_attributed_at
    FROM public.tournament_rake_settlements rs
   WHERE rs.tournament_id=p_tournament_id;
  IF v_rake_rows<>1 OR v_rake_settled_at IS NULL
     OR v_rake_attributed_at IS NULL OR v_rake_destination='pending'
     OR abs(round(COALESCE(v_rake_amount,0),2)-v_rake_expected)>0.005 THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_rake_not_settled',
      'expected',v_rake_expected,'recorded',v_rake_amount,
      'destination',v_rake_destination,'attributed_at',v_rake_attributed_at,
      'settled',false,'retryable',true);
  END IF;
  IF COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
     OR COALESCE(v_t.is_mystery_bounty,false) THEN
    IF public.fn_tournament_has_unsettled_bounties(p_tournament_id) THEN
      RETURN jsonb_build_object('ok',false,
        'reason','satellite_bounty_obligations_pending','settled',false,'retryable',true);
    END IF;
    SELECT * INTO v_bounty
      FROM public.tournament_bounty_completion_receipts b
     WHERE b.tournament_id=p_tournament_id;
    IF NOT FOUND OR v_bounty.winner_user_id IS DISTINCT FROM v_winner
       OR v_bounty.pool_finalized_at IS NULL
       OR COALESCE((v_bounty.pool_result->>'ok')::boolean,false) IS NOT TRUE
       OR (COALESCE(v_t.is_mystery_bounty,false)
           AND COALESCE(v_t.mystery_bounty_stage,'pending')<>'pending'
           AND (v_bounty.mystery_settled_at IS NULL
                OR COALESCE((v_bounty.mystery_result->>'ok')::boolean,false) IS NOT TRUE
                OR COALESCE((v_bounty.mystery_result->>'balanced')::boolean,false) IS NOT TRUE)) THEN
      RETURN jsonb_build_object('ok',false,'reason','satellite_bounty_not_certified',
                                'settled',false,'retryable',true);
    END IF;
  END IF;

  SELECT count(*)::integer,COALESCE(max(ent.position),0),
         round(COALESCE(sum(ent.ticket_value+ent.remainder_value),0),2),
         md5(COALESCE(string_agg(concat_ws(':',ent.position,ent.award_kind,
           COALESCE(ent.target_tournament_id::text,''),ent.ticket_value,
           ent.remainder_value,ent.source_pool,ent.entry_closed_at::text),
           '|' ORDER BY ent.position),''))
    INTO v_count,v_depth,v_amount,v_fingerprint
    FROM public.tournament_satellite_entitlements ent
   WHERE ent.tournament_id=p_tournament_id;
  INSERT INTO public.tournament_satellite_settlement_batches(
    tournament_id,winner_user_id,target_tournament_id,plan_fingerprint,
    entitlement_count,award_depth,amount_owed,source)
  VALUES (p_tournament_id,v_winner,v_t.satellite_target_id,v_fingerprint,
          v_count,v_depth,v_amount,
          COALESCE(NULLIF(btrim(p_source),''),'engine.satellite_finish'))
  ON CONFLICT (tournament_id) DO NOTHING;
  SELECT * INTO v_batch FROM public.tournament_satellite_settlement_batches
   WHERE tournament_id=p_tournament_id FOR UPDATE;
  IF ROW(v_batch.winner_user_id,v_batch.target_tournament_id,
         v_batch.plan_fingerprint,v_batch.entitlement_count,v_batch.award_depth,
         v_batch.amount_owed)
     IS DISTINCT FROM ROW(v_winner,v_t.satellite_target_id,v_fingerprint,
                          v_count,v_depth,v_amount) THEN
    RETURN jsonb_build_object('ok',false,'reason','satellite_batch_conflict',
                              'settled',false);
  END IF;

  BEGIN
    PERFORM set_config('app.atomic_satellite_settlement',p_tournament_id::text,true);
    FOR e IN SELECT * FROM public.tournament_satellite_entitlements
              WHERE tournament_id=p_tournament_id ORDER BY position LOOP
      SELECT * INTO p FROM public.tournament_players tp
       WHERE tp.tournament_id=p_tournament_id AND tp.position=e.position
       FOR UPDATE;
      IF NOT FOUND OR p.status NOT IN ('winner','eliminated') THEN
        RAISE EXCEPTION 'satellite entitlement position % has no terminal finisher',e.position
          USING ERRCODE='check_violation';
      END IF;
      v_delivery:=NULL;
      v_ticket_obligation:=NULL;
      v_remainder_obligation:=NULL;
      IF e.ticket_value>0 THEN
        v_delivery:=public.fn_deliver_satellite_ticket_exact(
          p_tournament_id,e.target_tournament_id,p.user_id,p.username,
          e.position,e.ticket_value);
        IF v_delivery->>'delivery'='cash' THEN
          v_ticket_obligation:=public.fn_settle_satellite_cash_entitlement_exact(
            p_tournament_id,'place',e.position,p.user_id,e.ticket_value,p_source);
        ELSIF v_delivery->>'delivery'<>'seat' THEN
          RAISE EXCEPTION 'satellite ticket has no exact delivery';
        END IF;
      ELSIF e.award_kind='cash' THEN
        v_delivery:=jsonb_build_object('delivery','cash','reason','whole_pool');
        v_ticket_obligation:=public.fn_settle_satellite_cash_entitlement_exact(
          p_tournament_id,'place',e.position,p.user_id,e.remainder_value,p_source);
      END IF;
      IF e.ticket_value>0 AND e.remainder_value>0 THEN
        v_remainder_obligation:=public.fn_settle_satellite_cash_entitlement_exact(
          p_tournament_id,'satellite_remainder',NULL,p.user_id,
          e.remainder_value,p_source);
      END IF;
      UPDATE public.tournament_players
         SET prize=round(e.ticket_value+e.remainder_value,2)
       WHERE id=p.id;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN
        RAISE EXCEPTION 'satellite prize stamp CAS changed % rows',v_rows
          USING ERRCODE='40001';
      END IF;
      v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object(
        'position',e.position,'user_id',p.user_id,
        'ticket_value',e.ticket_value,'remainder_value',e.remainder_value,
        'ticket_delivery',v_delivery->>'delivery',
        'delivery_reason',v_delivery->>'reason',
        'registration_id',v_delivery->>'registration_id',
        'seat_payout_id',v_delivery->>'payout_id',
        'place_obligation_id',v_ticket_obligation,
        'remainder_obligation_id',v_remainder_obligation));
    END LOOP;

    IF v_t.satellite_target_id IS NOT NULL THEN
      UPDATE public.tournaments target SET current_players=(
        SELECT count(*) FROM public.tournament_players tp
         WHERE tp.tournament_id=target.id)
       WHERE target.id=v_t.satellite_target_id;
    END IF;
    UPDATE public.tournament_satellite_settlement_batches
       SET settled_at=clock_timestamp(),outcomes=v_outcomes
     WHERE tournament_id=p_tournament_id AND settled_at IS NULL;
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN
      RAISE EXCEPTION 'satellite batch settle CAS changed % rows',v_rows
        USING ERRCODE='40001';
    END IF;
    v_check:=public.fn_check_atomic_satellite_finish(p_tournament_id);
    IF COALESCE((v_check->>'ok')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'satellite settlement postcondition failed: %',v_check
        USING ERRCODE='check_violation';
    END IF;
    UPDATE public.tournaments
       SET status='COMPLETED',ended_at=COALESCE(ended_at,clock_timestamp()),
           on_break=false,break_started_at=NULL,break_ends_at=NULL,
           current_players=1
     WHERE id=p_tournament_id AND status='COMPLETING';
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN
      RAISE EXCEPTION 'satellite completion CAS changed % rows',v_rows
        USING ERRCODE='40001';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'reason','atomic_satellite_settlement_failed',
      'sqlstate',SQLSTATE,'detail',SQLERRM,'settled',false,'retryable',
      SQLSTATE IN ('40001','40P01','55P03','57014'));
  END;
  v_check:=public.fn_check_atomic_satellite_finish(p_tournament_id);
  RETURN v_check||jsonb_build_object('settled',true,'already_settled',false,
                                     'rows_updated',1,'outcomes',v_outcomes);
END;
$$;


ALTER FUNCTION public.fn_settle_satellite_finish_atomic_before_maintenance_gate(p_tournament_id uuid, p_source text) OWNER TO postgres;

--
-- Name: fn_settle_satellite_tournament(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_satellite_tournament(p_tournament_id uuid, p_observed_winner_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_token uuid;
  v_result jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'satellite settlement requires service authority'
      USING ERRCODE='28000';
  END IF;
  v_token:=public.fn_ca_open_tournament_seat_exit_authority(
    p_tournament_id,'satellite_finish',NULL);
  BEGIN
    v_result:=public.fn_settle_satellite_tournament_pre_seat_guard(
      p_tournament_id,p_observed_winner_id);
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(
      v_token,COALESCE((v_result->>'ok')::boolean,false));
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
    RAISE;
  END;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_settle_satellite_tournament(p_tournament_id uuid, p_observed_winner_id uuid) OWNER TO postgres;

--
-- Name: fn_settle_satellite_tournament_pre_seat_guard(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_satellite_tournament_pre_seat_guard(p_tournament_id uuid, p_observed_winner_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_source record;
  v_target record;
  v_target_after record;
  v_winner public.tournament_players%ROWTYPE;
  v_finisher public.tournament_players%ROWTYPE;
  v_existing_target public.tournament_players%ROWTYPE;
  v_source_escrow public.tournament_escrow%ROWTYPE;
  v_target_escrow public.tournament_escrow%ROWTYPE;
  v_target_escrow_after public.tournament_escrow%ROWTYPE;
  v_existing_header public.tournament_satellite_settlements%ROWTYPE;
  v_obligation public.tournament_obligations%ROWTYPE;
  v_observed_target_id uuid;
  v_target_id uuid;
  v_target_open boolean := false;
  v_pool numeric;
  v_target_buy_in numeric;
  v_target_fee numeric;
  v_ticket_cost numeric;
  v_advertised_seats integer;
  v_ticket_award_count integer;
  v_seat_count integer := 0;
  v_cash_ticket_count integer := 0;
  v_remainder numeric;
  v_bubble_position integer;
  v_bubble_user_id uuid;
  v_field_size integer;
  v_target_count integer := 0;
  v_target_count_before integer := 0;
  v_target_live_count integer := 0;
  v_target_live_count_before integer := 0;
  v_target_counter_before integer := 0;
  v_target_counter_after integer := 0;
  v_target_slots integer := 0;
  v_live_count integer;
  v_eliminated_count integer;
  v_sequenced_count integer;
  v_distinct_sequence_count integer;
  v_place integer;
  v_rows integer;
  v_registration_id uuid;
  v_payout_id uuid;
  v_pool_before numeric;
  v_rake_result jsonb;
  v_credited boolean;
  v_payout_count integer;
  v_paid numeric;
  v_delivery_kind text;
  v_payout_key text;
  v_plan jsonb := '[]'::jsonb;
  v_plan_item jsonb;
  v_source_table_ids uuid[] := ARRAY[]::uuid[];
  v_source_seat_ids uuid[] := ARRAY[]::uuid[];
  v_released_seat_ids uuid[] := ARRAY[]::uuid[];
  v_source_table_count integer := 0;
  v_source_seat_count integer := 0;
  v_released_seat_count integer := 0;
  v_closeout_at timestamptz := transaction_timestamp();
  v_source_escrow_close_note text :=
    'atomic satellite terminal receipt: exact zero';
BEGIN
  -- Every terminal money authority takes this transaction lock before any
  -- row lock. Cash and satellite finishes can pay the same wallets, so one
  -- shared first lock prevents opposite recipient orders from deadlocking.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));

  IF p_tournament_id IS NULL OR p_observed_winner_id IS NULL THEN
    RAISE EXCEPTION 'satellite settlement requires tournament and observed winner ids'
      USING ERRCODE = '22004';
  END IF;

  -- A committed header wins before target admission is inspected. Replays can
  -- never turn a previously delivered seat into cash because a target closed.
  SELECT * INTO v_existing_header
    FROM public.tournament_satellite_settlements s
   WHERE s.tournament_id = p_tournament_id
   FOR UPDATE;
  IF FOUND THEN
    RETURN public.fn_ca_satellite_settlement_receipt(
      p_tournament_id, p_observed_winner_id);
  END IF;

  SELECT COALESCE(t.satellite_target_id, t.satellite_target)
    INTO v_observed_target_id
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  IF v_observed_target_id IS NULL OR v_observed_target_id = p_tournament_id THEN
    RAISE EXCEPTION 'satellite % has no distinct target', p_tournament_id
      USING ERRCODE = '23514';
  END IF;

  -- During the rolling cutover the legacy seat door still takes target before
  -- source. Match that order until stage two removes it; the global lock also
  -- serializes this authority with every new terminal payer.
  PERFORM 1 FROM public.tournaments t
   WHERE t.id IN (p_tournament_id, v_observed_target_id)
   ORDER BY CASE WHEN t.id = v_observed_target_id THEN 0 ELSE 1 END, t.id
   FOR UPDATE;
  SELECT t.id, t.name, t.club_id, t.status, t.variant, t.tournament_type,
         t.satellite_target_id, t.satellite_target, t.satellite_seats,
         t.prize_pool, t.prize_pool_finalized, t.is_bounty, t.is_pko,
         t.is_mystery_bounty, t.is_premium_spin
    INTO v_source FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF v_source.id IS NULL THEN
    RAISE EXCEPTION 'tournament % disappeared while being locked', p_tournament_id
      USING ERRCODE = '40001';
  END IF;
  IF v_source.satellite_target_id IS NOT NULL
     AND v_source.satellite_target IS NOT NULL
     AND v_source.satellite_target_id IS DISTINCT FROM v_source.satellite_target THEN
    RAISE EXCEPTION 'satellite % has conflicting target columns',
      p_tournament_id USING ERRCODE = '23514';
  END IF;
  v_target_id := COALESCE(v_source.satellite_target_id, v_source.satellite_target);
  IF v_target_id IS DISTINCT FROM v_observed_target_id THEN
    RAISE EXCEPTION 'satellite % target changed while settlement acquired locks',
      p_tournament_id USING ERRCODE = '40001';
  END IF;

  -- A concurrent caller may have committed while this caller waited above.
  SELECT * INTO v_existing_header
    FROM public.tournament_satellite_settlements s
   WHERE s.tournament_id = p_tournament_id
   FOR UPDATE;
  IF FOUND THEN
    RETURN public.fn_ca_satellite_settlement_receipt(
      p_tournament_id, p_observed_winner_id);
  END IF;

  IF lower(COALESCE(v_source.variant, '')) <> 'satellite'
     AND upper(COALESCE(v_source.tournament_type, '')) <> 'SATELLITE'
     AND v_source.satellite_target_id IS NULL
     AND v_source.satellite_target IS NULL THEN
    RAISE EXCEPTION 'tournament % is not a satellite', p_tournament_id
      USING ERRCODE = '22023';
  END IF;
  IF upper(COALESCE(v_source.status, '')) NOT IN ('RUNNING','COMPLETING') THEN
    RAISE EXCEPTION 'satellite % cannot first-settle from status %',
      p_tournament_id, v_source.status USING ERRCODE = '55000';
  END IF;
  IF COALESCE(v_source.prize_pool_finalized, false) IS NOT TRUE THEN
    RAISE EXCEPTION
      'satellite % prize pool is not finalized; guarantee funding is not proven',
      p_tournament_id USING ERRCODE = '55000';
  END IF;
  IF COALESCE(v_source.is_bounty, false)
     OR COALESCE(v_source.is_pko, false)
     OR COALESCE(v_source.is_mystery_bounty, false)
     OR COALESCE(v_source.is_premium_spin, false)
     OR lower(COALESCE(v_source.variant, '')) = 'spin'
     OR upper(COALESCE(v_source.tournament_type, '')) = 'SPIN' THEN
    RAISE EXCEPTION 'satellite % mixes another payout authority', p_tournament_id
      USING ERRCODE = '22023';
  END IF;

  v_pool := v_source.prize_pool;
  v_advertised_seats := COALESCE(v_source.satellite_seats, 0);
  IF v_pool IS NULL OR v_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_pool < 0 OR v_pool IS DISTINCT FROM round(v_pool, 2) THEN
    RAISE EXCEPTION 'satellite % has invalid whole-cent pool %',
      p_tournament_id, v_pool USING ERRCODE = '22003';
  END IF;
  IF v_advertised_seats < 0 THEN
    RAISE EXCEPTION 'satellite % has invalid advertised seat count %',
      p_tournament_id, v_advertised_seats USING ERRCODE = '22003';
  END IF;

  SELECT t.id, t.name, t.club_id, t.status, t.variant, t.tournament_type,
         t.buy_in_amount, t.buy_in_fee, t.is_bounty, t.is_pko,
         t.is_mystery_bounty, t.is_premium_spin,
         t.max_players, t.current_players, t.current_level,
         t.late_reg_levels, t.rebuy_levels, t.prize_pool_finalized,
         t.prize_pool, t.total_rake
    INTO v_target FROM public.tournaments t
   WHERE t.id = v_target_id
   FOR UPDATE;
  IF v_target.id IS NULL THEN
    -- PostgreSQL cannot row-lock an absent target. Refuse the settlement so a
    -- concurrent same-id target insert can never race a cash substitution.
    RAISE EXCEPTION
      'satellite % target % is missing; absence cannot authorize cash substitution',
      p_tournament_id, v_target_id USING ERRCODE = 'P0404';
  END IF;
  v_target_buy_in := v_target.buy_in_amount;
  v_target_fee := COALESCE(v_target.buy_in_fee, 0);
  IF v_target_buy_in IS NULL
     OR v_target_buy_in::text IN ('NaN','Infinity','-Infinity')
     OR v_target_buy_in < 0
     OR v_target_buy_in IS DISTINCT FROM round(v_target_buy_in, 2)
     OR v_target_fee IS NULL
     OR v_target_fee::text IN ('NaN','Infinity','-Infinity')
     OR v_target_fee < 0
     OR v_target_fee IS DISTINCT FROM round(v_target_fee, 2) THEN
    RAISE EXCEPTION 'satellite % target has an invalid whole-cent entry contract',
      p_tournament_id USING ERRCODE = '22003';
  END IF;
  v_ticket_cost := round(v_target_buy_in + v_target_fee, 2);
  IF v_ticket_cost <= 0 THEN
    RAISE EXCEPTION 'satellite % target ticket has no positive value',
      p_tournament_id USING ERRCODE = '23514';
  END IF;
  -- A bounty or Spin target needs a different, fully receipted split across
  -- prize, fee and bounty rails. This authority deliberately refuses that
  -- contract instead of silently classifying the bounty slice as prize.
  IF (
       v_target.is_bounty IS DISTINCT FROM false
       OR v_target.is_pko IS DISTINCT FROM false
       OR v_target.is_mystery_bounty IS DISTINCT FROM false
       OR v_target.is_premium_spin IS DISTINCT FROM false
       OR lower(COALESCE(v_target.variant,'')) = 'spin'
       OR upper(COALESCE(v_target.tournament_type,'')) = 'SPIN'
     ) THEN
    RAISE EXCEPTION
      'satellite % target % uses an unsupported bounty or Spin entry split',
      p_tournament_id, v_target_id USING ERRCODE = '22023';
  END IF;
  IF v_pool < v_advertised_seats * v_ticket_cost THEN
    RAISE EXCEPTION
      'satellite % finalized pool % does not fund its % advertised tickets at % each',
      p_tournament_id, v_pool, v_advertised_seats, v_ticket_cost
      USING ERRCODE = 'P0403';
  END IF;

  -- Open and own only the source escrow before the delivery plan is known. A
  -- cash-only plan must not touch a completed target's immutable escrow merely
  -- to prove that no seat will be delivered there.
  PERFORM public.fn_ca_escrow_apply(
    p_tournament_id, 'atomic satellite settlement source lock');
  PERFORM 1 FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id
   FOR UPDATE;
  SELECT * INTO v_source_escrow FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id;
  IF v_source_escrow.tournament_id IS NULL
     OR COALESCE(v_source_escrow.enforced, false) IS NOT TRUE
     OR v_source_escrow.closed_at IS NOT NULL
     OR v_source_escrow.close_note IS NOT NULL
     OR v_source_escrow.prize_balance IS DISTINCT FROM v_pool
     OR v_source_escrow.bounty_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.bounty_in IS DISTINCT FROM 0::numeric
     OR v_source_escrow.bounty_out IS DISTINCT FROM 0::numeric
     OR v_source_escrow.refund_bounty IS DISTINCT FROM 0::numeric
     OR v_source_escrow.reserve_out IS DISTINCT FROM 0::numeric
     OR v_source_escrow.reserve_in IS DISTINCT FROM 0::numeric
     OR v_source_escrow.fee_balance IS NULL
     OR v_source_escrow.fee_balance::text IN ('NaN','Infinity','-Infinity')
     OR v_source_escrow.fee_balance < 0
     OR v_source_escrow.fee_balance IS DISTINCT FROM round(v_source_escrow.fee_balance, 2)
     OR EXISTS (
       SELECT 1
         FROM unnest(ARRAY[
           'gross_in','fee_entries_in','satellite_fee_in','bounty_in',
           'overlay_in','satellite_in','prize_out','bounty_out','fee_out',
           'refund_prize','refund_bounty','refund_fee',
           'prize_balance','bounty_balance','fee_balance',
           'reserve_out','reserve_in'
         ]::text[]) AS component(name)
         CROSS JOIN LATERAL (
           SELECT (to_jsonb(v_source_escrow)->>component.name)::numeric AS amount
         ) AS persisted
        WHERE persisted.amount IS NULL
           OR CASE
                WHEN persisted.amount::text IN ('NaN','Infinity','-Infinity')
                  THEN true
                ELSE persisted.amount < 0
                  OR persisted.amount IS DISTINCT FROM round(persisted.amount,2)
              END
     ) THEN
    RAISE EXCEPTION
      'satellite % escrow does not hold exactly its locked pool (pool %, prize %, bounty %, fee %)',
      p_tournament_id, v_pool, v_source_escrow.prize_balance,
      v_source_escrow.bounty_balance, v_source_escrow.fee_balance
      USING ERRCODE = 'P0403';
  END IF;
  PERFORM 1 FROM public.tournament_players tp
   WHERE tp.tournament_id IN (p_tournament_id, v_target_id)
   ORDER BY tp.tournament_id, tp.id FOR UPDATE;

  -- Keep the same root lock order used by every terminal authority: tournament,
  -- tournament roster, source tables, then source seats. The identities are
  -- frozen before any payer runs and become part of the immutable header.
  PERFORM 1 FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY tb.id FOR UPDATE;
  PERFORM 1
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY ts.table_id, ts.id FOR UPDATE OF ts;
  SELECT COALESCE(array_agg(tb.id ORDER BY tb.id), ARRAY[]::uuid[])
    INTO v_source_table_ids
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id;
  SELECT COALESCE(array_agg(ts.id ORDER BY ts.table_id, ts.id), ARRAY[]::uuid[]),
         COALESCE(array_agg(ts.id ORDER BY ts.table_id, ts.id)
                    FILTER (WHERE ts.left_at IS NULL), ARRAY[]::uuid[])
    INTO v_source_seat_ids, v_released_seat_ids
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id;
  v_source_table_count := cardinality(v_source_table_ids);
  v_source_seat_count := cardinality(v_source_seat_ids);
  v_released_seat_count := cardinality(v_released_seat_ids);
  IF v_source_table_count < 1 THEN
    RAISE EXCEPTION 'satellite % has no source table to close', p_tournament_id
      USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_field_size FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  SELECT count(*),
         count(*) FILTER (
           WHERE tp.status::text IN ('registered','playing'))
    INTO v_target_count, v_target_live_count
    FROM public.tournament_players tp
   WHERE tp.tournament_id = v_target_id;
  v_target_count_before := v_target_count;
  v_target_live_count_before := v_target_live_count;
  -- Before start, current_players is the live lobby count maintained by the
  -- canonical roster trigger. Once RUNNING, it is the immutable total entrant
  -- count and must not shrink when a player is eliminated.
  v_target_counter_before := CASE
    WHEN upper(COALESCE(v_target.status, '')) IN ('ANNOUNCED','REGISTERING')
      THEN v_target_live_count_before
    ELSE v_target_count_before
  END;
  IF v_field_size < 1 THEN
    RAISE EXCEPTION 'satellite % has no final field', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND (tp.status IS NULL
         OR tp.status::text NOT IN ('playing','winner','eliminated'))
  ) THEN
    RAISE EXCEPTION 'satellite % still has an unresolved roster',
      p_tournament_id USING ERRCODE = '55000';
  END IF;

  -- Apart from the one explicitly adopted historical miss below, a new
  -- settlement must start with no money, target-seat or cache fragments.
  IF EXISTS (SELECT 1 FROM public.tournament_payouts p
              WHERE p.tournament_id = p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_obligations o
                 WHERE o.tournament_id = p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_rake_settlements r
                 WHERE r.tournament_id = p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_players tp
                 WHERE tp.tournament_id = p_tournament_id
                   AND COALESCE(tp.prize, 0) <> 0)
     OR EXISTS (
       SELECT 1 FROM public.chip_ledger l
        WHERE l.from_entity_id = p_tournament_id
          AND l.idempotency_key LIKE 'tourney:' || p_tournament_id::text
                                       || ':seat:%:pool_transfer')
     OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = v_target_id
          AND tp.source_satellite_id = p_tournament_id)
     OR EXISTS (
       SELECT 1 FROM public.rake_records r
        WHERE r.tournament_id = v_target_id
          AND r.source = 'fn_award_satellite_seat'
          AND r.metadata->>'satellite_id' = p_tournament_id::text) THEN
    RAISE EXCEPTION 'satellite % has partial or legacy settlement evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_live_count
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status::text IN ('playing','winner');
  IF v_live_count > 1 THEN
    RAISE EXCEPTION 'satellite % still has % live players',
      p_tournament_id, v_live_count USING ERRCODE = '55000';
  ELSIF v_live_count = 1 THEN
    SELECT * INTO v_winner FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text IN ('playing','winner');
  ELSE
    SELECT * INTO v_winner FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.user_id = p_observed_winner_id
       AND tp.status::text = 'eliminated'
       AND tp.elimination_sequence IS NOT NULL;
    IF FOUND AND EXISTS (
      SELECT 1 FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id
         AND tp.id <> v_winner.id
         AND tp.elimination_sequence = v_winner.elimination_sequence
    ) THEN
      RAISE EXCEPTION
        'satellite % has an ambiguous final elimination witness',
        p_tournament_id USING ERRCODE = '23505';
    END IF;
    IF FOUND AND EXISTS (
      SELECT 1 FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id
         AND tp.status::text = 'eliminated'
         AND (tp.elimination_sequence IS NULL
           OR tp.elimination_sequence > v_winner.elimination_sequence)
    ) THEN
      v_winner := NULL;
    END IF;
  END IF;
  IF v_winner.id IS NULL
     OR v_winner.user_id IS DISTINCT FROM p_observed_winner_id THEN
    RAISE EXCEPTION
      'observed winner % does not match the locked last survivor in satellite %',
      p_observed_winner_id, p_tournament_id USING ERRCODE = '40001';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position = 1 AND tp.user_id IS DISTINCT FROM v_winner.user_id
  ) THEN
    RAISE EXCEPTION 'satellite % assigns first place to another player',
      p_tournament_id USING ERRCODE = '23505';
  END IF;

  UPDATE public.tournament_players
     SET status = 'winner', position = 1,
         eliminated_at = NULL, elimination_sequence = NULL
   WHERE id = v_winner.id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'satellite % could not promote exactly one winner',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*), count(tp.elimination_sequence),
         count(DISTINCT tp.elimination_sequence)
    INTO v_eliminated_count, v_sequenced_count, v_distinct_sequence_count
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status::text = 'eliminated';
  IF v_eliminated_count <> v_field_size - 1
     OR v_sequenced_count <> v_eliminated_count
     OR v_distinct_sequence_count <> v_eliminated_count THEN
    RAISE EXCEPTION
      'satellite % has no complete durable elimination sequence (%/% of %)',
      p_tournament_id, v_sequenced_count, v_distinct_sequence_count,
      v_eliminated_count USING ERRCODE = 'P0404';
  END IF;

  -- No evidence exists, so numeric positions can be rebuilt from the durable
  -- transition order without relabelling a payment.
  UPDATE public.tournament_players tp
     SET position = NULL
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status::text = 'eliminated';
  WITH ranked AS (
    SELECT tp.id,
           row_number() OVER (
             ORDER BY tp.elimination_sequence DESC, tp.id ASC
           )::integer + 1 AS final_position
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text = 'eliminated'
  )
  UPDATE public.tournament_players tp
     SET position = ranked.final_position
    FROM ranked
   WHERE tp.id = ranked.id;

  SELECT count(*), count(DISTINCT tp.position)
    INTO v_rows, v_distinct_sequence_count
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.position BETWEEN 1 AND v_field_size;
  IF v_rows <> v_field_size OR v_distinct_sequence_count <> v_field_size THEN
    RAISE EXCEPTION 'satellite % could not prove contiguous final standings',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  v_ticket_award_count := floor(v_pool / v_ticket_cost)::integer;
  v_remainder := round(v_pool - v_ticket_award_count * v_ticket_cost, 2);
  IF v_remainder < 0 OR v_remainder >= v_ticket_cost THEN
    RAISE EXCEPTION 'satellite % derived invalid residual % below ticket %',
      p_tournament_id, v_remainder, v_ticket_cost USING ERRCODE = '23514';
  END IF;
  IF (v_ticket_award_count
      + CASE WHEN v_remainder > 0 THEN 1 ELSE 0 END) > v_field_size THEN
    RAISE EXCEPTION
      'satellite % pool needs % ticket/remainder finishers but field has %',
      p_tournament_id,
      v_ticket_award_count + CASE WHEN v_remainder > 0 THEN 1 ELSE 0 END,
      v_field_size USING ERRCODE = '23514';
  END IF;
  IF v_remainder > 0 THEN
    v_bubble_position := v_ticket_award_count + 1;
    SELECT tp.user_id INTO v_bubble_user_id
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position = v_bubble_position;
    IF NOT FOUND OR v_bubble_user_id IS NULL THEN
      RAISE EXCEPTION 'satellite % has no single bubble at place %',
        p_tournament_id, v_bubble_position USING ERRCODE = 'P0404';
    END IF;
  END IF;

  -- Decide a complete immutable delivery plan while target and roster locks are
  -- held. Only explicit terminal or full states become cash. Any other
  -- unknown lifecycle state refuses the whole settlement.
  IF COALESCE(v_target.max_players, 0) < 0
     OR v_target.late_reg_levels < 0
     OR v_target.rebuy_levels < 0 THEN
    RAISE EXCEPTION
      'satellite % target % has invalid admission bounds',
      p_tournament_id, v_target_id USING ERRCODE = '22003';
  END IF;
  IF v_target.max_players IS NOT NULL AND v_target.max_players > 0
     AND v_target_count >= v_target.max_players THEN
    v_target_open := false;
  ELSIF COALESCE(v_target.prize_pool_finalized, false) THEN
    v_target_open := false;
  ELSIF upper(COALESCE(v_target.status, '')) IN ('ANNOUNCED','REGISTERING') THEN
    v_target_open := true;
  ELSIF upper(COALESCE(v_target.status, '')) = 'RUNNING' THEN
    IF v_target.current_level < 0 THEN
      RAISE EXCEPTION
        'satellite % target % has invalid RUNNING admission level',
        p_tournament_id, v_target_id USING ERRCODE = '55000';
    END IF;
    -- The target row and both rosters are already locked. Delegate the actual
    -- RUNNING admission decision to the same canonical authority used by every
    -- other late-registration path, including its minutes-based fallback.
    v_target_open :=
      public.fn_tournament_late_registration_open(v_target_id);
  ELSIF upper(COALESCE(v_target.status, '')) IN
        ('COMPLETING','COMPLETED','CANCELLED','CANCELED') THEN
    v_target_open := false;
  ELSE
    RAISE EXCEPTION
      'satellite % target % admission state % is ambiguous',
      p_tournament_id, v_target_id, v_target.status
      USING ERRCODE = '55000';
  END IF;
  IF v_target_open THEN
    v_target_slots := CASE
      WHEN v_target.max_players IS NULL OR v_target.max_players = 0
        THEN v_ticket_award_count
      ELSE GREATEST(v_target.max_players - v_target_count, 0)
    END;
  END IF;

  IF v_ticket_award_count > 0 THEN
    FOR v_place IN 1..v_ticket_award_count LOOP
      SELECT * INTO v_finisher FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id AND tp.position = v_place;
      IF v_finisher.id IS NULL THEN
        RAISE EXCEPTION 'satellite % has no finisher at ticket place %',
          p_tournament_id, v_place USING ERRCODE = 'P0404';
      END IF;

      v_delivery_kind := 'cash';
      SELECT * INTO v_existing_target FROM public.tournament_players tp
       WHERE tp.tournament_id = v_target_id
         AND tp.user_id = v_finisher.user_id;
      IF FOUND THEN
        IF COALESCE(v_existing_target.is_satellite_qualifier, false) IS NOT TRUE THEN
          v_delivery_kind := 'cash';
        ELSIF v_existing_target.source_satellite_id IS NULL THEN
          RAISE EXCEPTION
            'satellite % cannot prove origin of target seat held by place %',
            p_tournament_id, v_place USING ERRCODE = 'P0404';
        ELSIF v_existing_target.source_satellite_id = p_tournament_id THEN
          RAISE EXCEPTION
            'satellite % has an unreceipted target seat already delivered to place %',
            p_tournament_id, v_place USING ERRCODE = 'P0404';
        ELSE
          v_delivery_kind := 'cash';
        END IF;
      ELSIF v_target_open AND v_seat_count < v_target_slots THEN
        v_delivery_kind := 'seat';
      END IF;

      IF v_delivery_kind = 'seat' THEN
        v_seat_count := v_seat_count + 1;
      ELSE
        v_cash_ticket_count := v_cash_ticket_count + 1;
      END IF;
      v_plan := v_plan || jsonb_build_array(jsonb_build_object(
        'place', v_place,
        'user_id', v_finisher.user_id,
        'delivery_kind', v_delivery_kind));
    END LOOP;
  END IF;
  IF v_seat_count + v_cash_ticket_count <> v_ticket_award_count THEN
    RAISE EXCEPTION 'satellite % did not classify every funded ticket',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  -- Closed/full/independently-held tickets are cash substitutions and do not
  -- touch target aggregates. Validate those mutable target banks only when
  -- this exact plan will add at least one real registration.
  IF v_seat_count > 0 THEN
    -- Zero-delta reconstruction is a write when the escrow already exists, so
    -- it belongs after seat classification and only on the actual seat path.
    PERFORM public.fn_ca_escrow_apply(
      v_target_id, 'atomic satellite settlement target seat lock');
    SELECT * INTO v_target_escrow FROM public.tournament_escrow e
     WHERE e.tournament_id = v_target_id
     FOR UPDATE;
  END IF;
  IF v_seat_count > 0 AND (
       v_target.current_players IS NULL
       OR v_target.current_players < 0
       OR v_target.current_players IS DISTINCT FROM v_target_counter_before
       OR v_target.prize_pool IS NULL
       OR v_target.prize_pool::text IN ('NaN','Infinity','-Infinity')
       OR v_target.prize_pool < 0
       OR v_target.prize_pool IS DISTINCT FROM round(v_target.prize_pool, 2)
       OR v_target.total_rake IS NULL
       OR v_target.total_rake::text IN ('NaN','Infinity','-Infinity')
       OR v_target.total_rake < 0
       OR v_target.total_rake IS DISTINCT FROM round(v_target.total_rake, 2)
       OR (v_target_fee > 0 AND v_target.club_id IS NULL)
       OR v_target_escrow.tournament_id IS NULL
       OR v_target_escrow.enforced IS DISTINCT FROM true
       OR v_target_escrow.closed_at IS NOT NULL
       OR v_target_escrow.close_note IS NOT NULL
       OR v_target_escrow.prize_balance IS NULL
       OR v_target_escrow.prize_balance::text IN ('NaN','Infinity','-Infinity')
       OR v_target_escrow.prize_balance < 0
       OR v_target_escrow.prize_balance IS DISTINCT FROM
            round(v_target_escrow.prize_balance, 2)
       OR v_target.prize_pool IS DISTINCT FROM v_target_escrow.prize_balance
       OR v_target_escrow.bounty_balance IS DISTINCT FROM 0::numeric
       OR v_target_escrow.fee_balance IS NULL
       OR v_target_escrow.fee_balance::text IN ('NaN','Infinity','-Infinity')
       OR v_target_escrow.fee_balance < 0
       OR v_target_escrow.fee_balance IS DISTINCT FROM
            round(v_target_escrow.fee_balance, 2)
       OR v_target.total_rake IS DISTINCT FROM v_target_escrow.fee_balance
       OR EXISTS (
         SELECT 1
           FROM unnest(ARRAY[
             'gross_in','fee_entries_in','satellite_fee_in','bounty_in',
             'overlay_in','satellite_in','prize_out','bounty_out','fee_out',
             'refund_prize','refund_bounty','refund_fee',
             'reserve_out','reserve_in'
           ]::text[]) AS component(name)
           CROSS JOIN LATERAL (
             SELECT (to_jsonb(v_target_escrow)->>component.name)::numeric AS amount
           ) AS persisted
          WHERE persisted.amount IS NULL
             OR CASE
                  WHEN persisted.amount::text IN ('NaN','Infinity','-Infinity')
                    THEN true
                  ELSE persisted.amount < 0
                    OR persisted.amount IS DISTINCT FROM round(persisted.amount,2)
                END
       )
     ) THEN
    RAISE EXCEPTION
      'satellite % cannot deliver a target seat against malformed aggregate or escrow state',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  INSERT INTO public.tournament_satellite_settlements
    (tournament_id, target_id, target_was_missing, target_contract_version,
     winner_id, field_size, advertised_seats, pool,
     target_buy_in, target_fee, ticket_cost, ticket_award_count,
     seat_count, cash_ticket_count, remainder, bubble_user_id, bubble_position,
     source_table_count, source_table_ids, source_seat_count, source_seat_ids,
     released_seat_count, released_seat_ids, source_closed_at,
     source_escrow_closed_at, source_escrow_close_note, settled_at)
  VALUES
    (p_tournament_id, v_target_id, false, NULL,
     p_observed_winner_id, v_field_size, v_advertised_seats, v_pool,
     v_target_buy_in, v_target_fee, v_ticket_cost, v_ticket_award_count,
     v_seat_count, v_cash_ticket_count, v_remainder,
     v_bubble_user_id, v_bubble_position,
     v_source_table_count, v_source_table_ids, v_source_seat_count,
     v_source_seat_ids, v_released_seat_count, v_released_seat_ids,
     v_closeout_at, v_closeout_at, v_source_escrow_close_note, v_closeout_at);

  UPDATE public.tournaments
     SET status = 'COMPLETING', updated_at = now()
   WHERE id = p_tournament_id
     AND upper(COALESCE(status, '')) IN ('RUNNING','COMPLETING')
     AND COALESCE(prize_pool_finalized, false);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'satellite % could not claim its atomic settlement',
      p_tournament_id USING ERRCODE = '40001';
  END IF;

  FOR v_plan_item IN SELECT value FROM jsonb_array_elements(v_plan) LOOP
    v_place := (v_plan_item->>'place')::integer;
    v_delivery_kind := v_plan_item->>'delivery_kind';
    SELECT * INTO v_finisher FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position = v_place
       AND tp.user_id = (v_plan_item->>'user_id')::uuid;
    IF v_finisher.id IS NULL THEN
      RAISE EXCEPTION 'satellite % delivery plan lost finisher at place %',
        p_tournament_id, v_place USING ERRCODE = 'P0404';
    END IF;

    IF v_delivery_kind = 'seat' THEN
      INSERT INTO public.tournament_players
        (tournament_id, user_id, username, chips, status,
         is_satellite_qualifier, source_satellite_id)
      VALUES
        (v_target_id, v_finisher.user_id, v_finisher.username, 0, 'registered',
         true, p_tournament_id)
      RETURNING id INTO v_registration_id;
      IF v_registration_id IS NULL THEN
        RAISE EXCEPTION 'satellite % seat % returned no registration receipt',
          p_tournament_id, v_place USING ERRCODE = 'P0404';
      END IF;

      v_pool_before := round(v_pool - (v_place - 1) * v_ticket_cost, 2);
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, tournament_id, idempotency_key,
         settlement_id, actor_service, description, metadata,
         pre_from_balance, post_from_balance)
      VALUES
        (COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
         'prize_liability', p_tournament_id, 'tournaments.prize_pool',
         'prize_liability', v_target_id, 'tournaments.prize_pool+total_rake',
         v_ticket_cost, 'tournament_buyin', v_target.club_id, p_tournament_id,
         'tourney:' || p_tournament_id::text || ':seat:'
            || v_finisher.user_id::text || ':pool_transfer',
         'satellite:' || p_tournament_id::text,
         'fn_settle_satellite_tournament',
         format('Satellite ticket place %s delivered as target seat (%s)',
                v_place, v_ticket_cost),
         jsonb_build_object(
           'kind', 'satellite_seat_pool_transfer',
           'satellite_id', p_tournament_id,
           'satellite_target_id', v_target_id,
           'user_id', v_finisher.user_id,
           'position', v_place,
           'registration_id', v_registration_id,
           'seat_value', v_ticket_cost,
           'moved', v_ticket_cost,
           'unbacked', 0),
         v_pool_before, round(v_pool_before - v_ticket_cost, 2));

      -- The transfer leg puts the complete ticket into target satellite-in.
      -- A positive fee row reclassifies only that fee from target prize to
      -- target fee escrow. A zero-fee target needs no synthetic rake record.
      IF v_target_fee > 0 THEN
        INSERT INTO public.rake_records
          (hand_id, table_id, club_id, rake_amount, pot_size, num_players,
           bbj_contribution, is_tournament, tournament_id, source, metadata)
        VALUES
          (NULL, NULL, v_target.club_id, v_target_fee, v_ticket_cost, 1,
           0, true, v_target_id, 'fn_award_satellite_seat',
           jsonb_build_object(
             'kind', 'satellite_seat_entry_fee',
             'recorded_by', 'fn_settle_satellite_tournament',
             'user_id', v_finisher.user_id,
             'position', v_place,
             'satellite_id', p_tournament_id,
             'registration_id', v_registration_id));
      END IF;

      v_payout_key := 'tourney:' || p_tournament_id::text
                      || ':seat:' || v_finisher.user_id::text;
      INSERT INTO public.tournament_payouts
        (tournament_id, user_id, "position", amount, source, idempotency_key,
         paid_at, tournament_type, field_size, prize_pool, payout_structure,
         recorded_by, metadata)
      VALUES
        (p_tournament_id, v_finisher.user_id, v_place, v_ticket_cost,
         'satellite_seat', v_payout_key, now(), v_source.tournament_type,
         v_field_size, v_pool, NULL, 'fn_settle_satellite_tournament',
         jsonb_build_object(
           'satellite_target_id', v_target_id,
           'target_name', v_target.name,
           'registration_id', v_registration_id,
           'target_buy_in', v_target_buy_in,
           'target_fee', v_target_fee,
           'pool_transfer', v_ticket_cost,
           'unbacked', 0))
      RETURNING id INTO v_payout_id;

      INSERT INTO public.tournament_satellite_awards
        (tournament_id, place, user_id, delivery_kind, amount,
         payout_id, payout_source, idempotency_key, registration_id)
      VALUES
        (p_tournament_id, v_place, v_finisher.user_id, 'seat', v_ticket_cost,
         v_payout_id, 'satellite_seat', v_payout_key, v_registration_id);
    ELSIF v_delivery_kind = 'cash' THEN
      INSERT INTO public.tournament_obligations
        (tournament_id, kind, place, user_id, amount_owed, amount_paid,
         source, settled_at)
      VALUES
        (p_tournament_id, 'seat', v_place, v_finisher.user_id,
         v_ticket_cost, 0, 'engine.fn_settle_satellite_tournament', NULL)
      RETURNING * INTO v_obligation;

      v_payout_key := 'tourney:' || p_tournament_id::text
                      || ':satellite_ticket:place:' || v_place::text;
      v_credited := public.fn_credit_and_log(
        p_user_id => v_finisher.user_id,
        p_amount => v_ticket_cost,
        p_idempotency_key => v_payout_key,
        p_category => 'prize',
        p_description => 'Satellite ticket paid in cash because target admission was definitively unavailable',
        p_related_entity_id => p_tournament_id,
        p_wallet_type => 'PLAYER',
        p_table_id => NULL,
        p_hand_id => NULL,
        p_payout_position => v_place,
        p_payout_source => 'satellite_ticket');
      IF v_credited IS NOT TRUE THEN
        RAISE EXCEPTION 'satellite % cash ticket % was not a new exact credit',
          p_tournament_id, v_place USING ERRCODE = 'P0404';
      END IF;

      UPDATE public.tournament_obligations o
         SET amount_paid = v_ticket_cost, settled_at = now(), updated_at = now()
       WHERE o.id = v_obligation.id
         AND o.amount_owed = v_ticket_cost AND o.amount_paid = 0;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 THEN
        RAISE EXCEPTION 'satellite % could not close cash ticket debt %',
          p_tournament_id, v_place USING ERRCODE = 'P0404';
      END IF;

      SELECT p.id INTO v_payout_id FROM public.tournament_payouts p
       WHERE p.idempotency_key = v_payout_key
         AND p.tournament_id = p_tournament_id
         AND p.user_id = v_finisher.user_id
         AND p."position" = v_place
         AND p.amount = v_ticket_cost
         AND p.source = 'satellite_ticket';
      IF v_payout_id IS NULL THEN
        RAISE EXCEPTION 'satellite % cash ticket % has no payout row',
          p_tournament_id, v_place USING ERRCODE = 'P0404';
      END IF;

      INSERT INTO public.tournament_satellite_awards
        (tournament_id, place, user_id, delivery_kind, amount,
         payout_id, payout_source, idempotency_key,
         obligation_id, obligation_kind)
      VALUES
        (p_tournament_id, v_place, v_finisher.user_id, 'cash', v_ticket_cost,
         v_payout_id, 'satellite_ticket', v_payout_key,
         v_obligation.id, 'seat');
    ELSE
      RAISE EXCEPTION 'satellite % has unknown delivery kind % at place %',
        p_tournament_id, v_delivery_kind, v_place USING ERRCODE = 'P0404';
    END IF;
  END LOOP;

  IF v_seat_count > 0 THEN
    SELECT count(*),
           count(*) FILTER (
             WHERE tp.status::text IN ('registered','playing'))
      INTO v_target_count, v_target_live_count
      FROM public.tournament_players tp
     WHERE tp.tournament_id = v_target_id;
    v_target_counter_after := CASE
      WHEN upper(COALESCE(v_target.status, '')) IN ('ANNOUNCED','REGISTERING')
        THEN v_target_live_count
      ELSE v_target_count
    END;
    IF v_target_count IS DISTINCT FROM v_target_count_before + v_seat_count
       OR v_target_live_count IS DISTINCT FROM
            v_target_live_count_before + v_seat_count
       OR v_target_counter_after IS DISTINCT FROM
            v_target_counter_before + v_seat_count THEN
      RAISE EXCEPTION
        'satellite % target roster changed outside its locked delivery plan',
        p_tournament_id USING ERRCODE = '40001';
    END IF;
    UPDATE public.tournaments
       SET current_players = v_target.current_players + v_seat_count,
           prize_pool = round(COALESCE(prize_pool, 0)
                              + v_seat_count * v_target_buy_in, 2),
           total_rake = round(COALESCE(total_rake, 0)
                             + v_seat_count * v_target_fee, 2),
           updated_at = now()
     WHERE id = v_target_id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'satellite % could not update target aggregate receipt',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;

    SELECT t.id, t.current_players, t.prize_pool, t.total_rake
      INTO v_target_after
      FROM public.tournaments t
     WHERE t.id = v_target_id;
    SELECT * INTO v_target_escrow_after
      FROM public.tournament_escrow e
     WHERE e.tournament_id = v_target_id
     FOR UPDATE;
    IF v_target_after.id IS NULL
       OR v_target_after.current_players IS DISTINCT FROM
            v_target.current_players + v_seat_count
       OR v_target_after.current_players IS DISTINCT FROM v_target_counter_after
       OR v_target_after.prize_pool IS DISTINCT FROM
            round(v_target.prize_pool + v_seat_count * v_target_buy_in, 2)
       OR v_target_after.total_rake IS DISTINCT FROM
            round(v_target.total_rake + v_seat_count * v_target_fee, 2)
       OR v_target_escrow_after.tournament_id IS DISTINCT FROM v_target_id
       OR v_target_escrow_after.enforced IS DISTINCT FROM v_target_escrow.enforced
       OR v_target_escrow_after.gross_in IS DISTINCT FROM v_target_escrow.gross_in
       OR v_target_escrow_after.fee_entries_in IS DISTINCT FROM v_target_escrow.fee_entries_in
       OR v_target_escrow_after.satellite_fee_in IS DISTINCT FROM
            round(v_target_escrow.satellite_fee_in
                  + v_seat_count * v_target_fee, 2)
       OR v_target_escrow_after.bounty_in IS DISTINCT FROM v_target_escrow.bounty_in
       OR v_target_escrow_after.overlay_in IS DISTINCT FROM v_target_escrow.overlay_in
       OR v_target_escrow_after.satellite_in IS DISTINCT FROM
            round(v_target_escrow.satellite_in
                  + v_seat_count * v_target_buy_in, 2)
       OR v_target_escrow_after.prize_out IS DISTINCT FROM v_target_escrow.prize_out
       OR v_target_escrow_after.bounty_out IS DISTINCT FROM v_target_escrow.bounty_out
       OR v_target_escrow_after.fee_out IS DISTINCT FROM v_target_escrow.fee_out
       OR v_target_escrow_after.refund_prize IS DISTINCT FROM v_target_escrow.refund_prize
       OR v_target_escrow_after.refund_bounty IS DISTINCT FROM v_target_escrow.refund_bounty
       OR v_target_escrow_after.refund_fee IS DISTINCT FROM v_target_escrow.refund_fee
       OR v_target_escrow_after.reserve_out IS DISTINCT FROM v_target_escrow.reserve_out
       OR v_target_escrow_after.reserve_in IS DISTINCT FROM v_target_escrow.reserve_in
       OR v_target_escrow_after.prize_balance IS DISTINCT FROM
            round(v_target_escrow.prize_balance
                  + v_seat_count * v_target_buy_in, 2)
       OR v_target_escrow_after.bounty_balance IS DISTINCT FROM v_target_escrow.bounty_balance
       OR v_target_escrow_after.fee_balance IS DISTINCT FROM
            round(v_target_escrow.fee_balance
                  + v_seat_count * v_target_fee, 2)
       OR v_target_escrow_after.opened_at IS DISTINCT FROM v_target_escrow.opened_at
       OR v_target_escrow_after.opened_from IS DISTINCT FROM v_target_escrow.opened_from
       OR v_target_escrow_after.closed_at IS DISTINCT FROM v_target_escrow.closed_at
       OR v_target_escrow_after.close_note IS DISTINCT FROM v_target_escrow.close_note THEN
      RAISE EXCEPTION
        'satellite % target aggregate or escrow delta is not the exact delivered seat value',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  END IF;

  IF v_remainder > 0 THEN
    INSERT INTO public.tournament_obligations
      (tournament_id, kind, place, user_id, amount_owed, amount_paid,
       source, settled_at)
    VALUES
      (p_tournament_id, 'satellite_remainder', v_bubble_position,
       v_bubble_user_id, v_remainder, 0,
       'engine.fn_settle_satellite_tournament', NULL)
    RETURNING * INTO v_obligation;

    v_payout_key := 'tourney:' || p_tournament_id::text
                    || ':satellite_remainder:place:'
                    || v_bubble_position::text;
    v_credited := public.fn_credit_and_log(
      p_user_id => v_bubble_user_id,
      p_amount => v_remainder,
      p_idempotency_key => v_payout_key,
      p_category => 'prize',
      p_description => 'Satellite pool remainder paid to the single bubble',
      p_related_entity_id => p_tournament_id,
      p_wallet_type => 'PLAYER',
      p_table_id => NULL,
      p_hand_id => NULL,
      p_payout_position => v_bubble_position,
      p_payout_source => 'satellite_remainder');
    IF v_credited IS NOT TRUE THEN
      RAISE EXCEPTION 'satellite % remainder credit was not a new exact credit',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;

    UPDATE public.tournament_obligations
       SET amount_paid = v_remainder, settled_at = now(), updated_at = now()
     WHERE id = v_obligation.id
       AND tournament_id = p_tournament_id
       AND kind = 'satellite_remainder' AND place = v_bubble_position
       AND user_id = v_bubble_user_id
       AND amount_owed = v_remainder
       AND amount_paid = 0;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'satellite % could not close one exact remainder debt',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;

    SELECT p.id INTO v_payout_id
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.user_id = v_bubble_user_id
       AND p."position" = v_bubble_position
       AND p.amount = v_remainder
       AND p.source = 'satellite_remainder'
       AND p.idempotency_key = v_payout_key;
    IF v_payout_id IS NULL THEN
      RAISE EXCEPTION 'satellite % remainder has no exact payout row',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;

    INSERT INTO public.tournament_satellite_remainders
      (tournament_id, user_id, place, amount,
       payout_id, payout_source, payout_position, idempotency_key,
       obligation_id, obligation_kind, obligation_place, evidence_kind)
    VALUES
      (p_tournament_id, v_bubble_user_id, v_bubble_position, v_remainder,
       v_payout_id, 'satellite_remainder', v_bubble_position, v_payout_key,
       v_obligation.id, 'satellite_remainder', v_bubble_position, 'atomic');
  END IF;

  UPDATE public.tournament_players SET prize = 0
   WHERE tournament_id = p_tournament_id;
  UPDATE public.tournament_players SET prize = v_ticket_cost
   WHERE tournament_id = p_tournament_id
     AND position BETWEEN 1 AND v_ticket_award_count;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> v_ticket_award_count THEN
    RAISE EXCEPTION 'satellite % stamped % ticket caches, expected %',
      p_tournament_id, v_rows, v_ticket_award_count USING ERRCODE = 'P0404';
  END IF;
  IF v_remainder > 0 THEN
    UPDATE public.tournament_players SET prize = v_remainder
     WHERE tournament_id = p_tournament_id
       AND user_id = v_bubble_user_id AND position = v_bubble_position;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'satellite % could not stamp the single bubble cache',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  END IF;

  SELECT count(*), round(COALESCE(sum(p.amount), 0), 2)
    INTO v_payout_count, v_paid
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id;
  IF v_payout_count <> (v_ticket_award_count
                        + CASE WHEN v_remainder > 0 THEN 1 ELSE 0 END)
     OR v_paid IS DISTINCT FROM v_pool THEN
    RAISE EXCEPTION 'satellite % paid % of locked pool % across % rows',
      p_tournament_id, v_paid, v_pool, v_payout_count
      USING ERRCODE = 'P0404';
  END IF;

  v_rake_result := public.fn_settle_tournament_rake(
    p_tournament_id, 'engine.fn_settle_satellite_tournament');
  IF COALESCE((v_rake_result->>'ok')::boolean, false) IS NOT TRUE
     OR (COALESCE((v_rake_result->>'amount')::numeric, 0) > 0
         AND COALESCE((v_rake_result->>'attributed')::boolean, false) IS NOT TRUE) THEN
    RAISE EXCEPTION 'satellite % rake did not settle and attribute exactly: %',
      p_tournament_id, v_rake_result USING ERRCODE = 'P0404';
  END IF;

  SELECT * INTO v_source_escrow FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id FOR UPDATE;
  IF v_source_escrow.prize_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.bounty_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.fee_balance IS DISTINCT FROM 0::numeric THEN
    RAISE EXCEPTION
      'satellite % settlement leaves escrow prize %, bounty %, fee %',
      p_tournament_id, v_source_escrow.prize_balance,
      v_source_escrow.bounty_balance, v_source_escrow.fee_balance
      USING ERRCODE = 'P0404';
  END IF;

  -- The atomic authority, not the legacy lifecycle observer, owns the escrow
  -- close. Stamp the exact zero proof before publishing COMPLETED so the
  -- receipt remains valid after that observer is retired by the terminal
  -- cutover migration.
  UPDATE public.tournament_escrow
     SET closed_at = v_closeout_at,
         close_note = v_source_escrow_close_note,
         updated_at = now()
   WHERE tournament_id = p_tournament_id
     AND closed_at IS NULL
     AND close_note IS NULL
     AND prize_balance = 0
     AND bounty_balance = 0
     AND fee_balance = 0;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'satellite % could not commit its exact escrow close',
      p_tournament_id USING ERRCODE = '40001';
  END IF;

  -- Source felt closure is part of the money commit. This runs after tickets,
  -- the single Bubble remainder, rake and escrow so any table/seat refusal
  -- rolls all of those effects back. The pre-payer identity arrays prevent a
  -- concurrent table or seat from appearing outside the receipt.
  UPDATE public.table_seats ts
     SET left_at = v_closeout_at,
         status = 'left',
         leave_pending = false,
         is_sitting_out = false,
         is_away = false,
         sit_out_at = NULL,
         scheduled_leave_hands = NULL
   WHERE ts.id = ANY(v_released_seat_ids)
     AND ts.left_at IS NULL;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows IS DISTINCT FROM v_released_seat_count THEN
    RAISE EXCEPTION 'satellite % released % source seats, expected %',
      p_tournament_id, v_rows, v_released_seat_count USING ERRCODE = '40001';
  END IF;

  -- Elimination already gave predeparted seats a durable departure time. Close
  -- only their mutable occupancy flags here; never rewrite that historical time
  -- or fire left_at-specific effects a second time.
  UPDATE public.table_seats ts
     SET status = 'left', leave_pending = false, is_sitting_out = false,
         is_away = false, sit_out_at = NULL, scheduled_leave_hands = NULL
   WHERE ts.id = ANY(v_source_seat_ids)
     AND ts.left_at IS NOT NULL
     AND (ts.status IS DISTINCT FROM 'left'
       OR ts.leave_pending IS DISTINCT FROM false
       OR ts.is_sitting_out IS DISTINCT FROM false
       OR ts.is_away IS DISTINCT FROM false
       OR ts.sit_out_at IS NOT NULL
       OR ts.scheduled_leave_hands IS NOT NULL);

  -- Mark the game terminal only after its seats are released, but before its
  -- tables close. The existing table-status trigger treats a close under a
  -- COMPLETING tournament as an accidental live-game close and files an
  -- incident. COMPLETED is therefore the canonical parent-before-child order.
  -- A later table-close refusal still rolls this status and all money back.
  UPDATE public.tournaments
     SET status = 'COMPLETED', ended_at = now(), prize_pool_finalized = true,
         current_players = 0, on_break = false,
         break_started_at = NULL, break_ends_at = NULL, updated_at = now()
   WHERE id = p_tournament_id AND upper(COALESCE(status, '')) = 'COMPLETING';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'satellite % could not commit COMPLETING to COMPLETED',
      p_tournament_id USING ERRCODE = '40001';
  END IF;

  UPDATE public.tables tb
     SET status = 'closed',
         lifecycle = 'closed',
         current_players = 0,
         terminal_closed_at = v_closeout_at,
         updated_at = now()
   WHERE tb.id = ANY(v_source_table_ids)
     AND tb.tournament_id = p_tournament_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows IS DISTINCT FROM v_source_table_count
     OR EXISTS (
       SELECT 1 FROM public.tables tb
        WHERE tb.tournament_id = p_tournament_id
          AND (lower(COALESCE(tb.status::text, '')) <> 'closed'
            OR lower(COALESCE(tb.lifecycle, '')) <> 'closed'
            OR tb.current_players IS DISTINCT FROM 0)
     ) OR EXISTS (
       SELECT 1
        FROM public.table_seats ts
         JOIN public.tables tb ON tb.id = ts.table_id
        WHERE tb.tournament_id = p_tournament_id
          AND (ts.left_at IS NULL
            OR ts.status IS DISTINCT FROM 'left'
            OR ts.leave_pending IS DISTINCT FROM false
            OR ts.is_sitting_out IS DISTINCT FROM false
            OR ts.is_away IS DISTINCT FROM false
            OR ts.sit_out_at IS NOT NULL
            OR ts.scheduled_leave_hands IS NOT NULL)
     ) THEN
    RAISE EXCEPTION
      'satellite % did not durably release every source seat and close every source table',
      p_tournament_id USING ERRCODE = '40001';
  END IF;

  RETURN public.fn_ca_satellite_settlement_receipt(
    p_tournament_id, p_observed_winner_id);
END;
$$;


ALTER FUNCTION public.fn_settle_satellite_tournament_pre_seat_guard(p_tournament_id uuid, p_observed_winner_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_settle_satellite_tournament_pre_seat_guard(p_tournament_id uuid, p_observed_winner_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settle_satellite_tournament_pre_seat_guard(p_tournament_id uuid, p_observed_winner_id uuid) IS 'Single atomic satellite finish. The finalized pool funds floor(pool/ticket) full ticket awards (actual seat or exact cash substitution), then one next finisher receives all residual; source seats, source tables and lifecycle close in the same transaction. No settlement-time house funding, split or retained dust.';


--
-- Name: fn_settle_tournament_bubble_protection(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_tournament_bubble_protection(p_tournament_id uuid, p_observed_bubble_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t record;
  v_ladder jsonb;
  v_field_size integer;
  v_eliminated_count integer;
  v_sequenced_count integer;
  v_distinct_sequence_count integer;
  v_bubble_place integer;
  v_bubble_user_id uuid;
  v_bubble_amount numeric;
  v_candidate_count integer;
  v_ob public.tournament_obligations%ROWTYPE;
  v_ob_count integer;
  v_payout_count integer;
  v_paid numeric;
  v_result jsonb;
  v_rows integer;
BEGIN
  IF p_tournament_id IS NULL OR p_observed_bubble_user_id IS NULL THEN
    RAISE EXCEPTION 'bubble settlement requires tournament and observed user ids'
      USING ERRCODE = '22004';
  END IF;

  SELECT t.id, t.status, t.variant, t.tournament_type,
         t.satellite_target_id, t.satellite_target, t.bubble_protection,
         t.buy_in_amount,
         t.prize_pool, t.prize_pool_finalized
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  IF upper(COALESCE(v_t.status, '')) NOT IN
       ('RUNNING','COMPLETING','COMPLETED') THEN
    RAISE EXCEPTION 'tournament % cannot settle a bubble from status %',
      p_tournament_id, v_t.status USING ERRCODE = '55000';
  END IF;
  -- Before the pool is finalized, late registration can still enlarge the
  -- roster. An entrant who is the bubble in that transient field may acquire a
  -- different final place. Never move money until the database-owned close
  -- proves the field and its stone-bubble identity are immutable. If guarantee
  -- funding prevented finalization, terminal settlement funds it and settles
  -- the bubble atomically instead.
  IF COALESCE(v_t.prize_pool_finalized, false) IS NOT TRUE THEN
    RAISE EXCEPTION
      'tournament % cannot settle its bubble before the prize pool is finalized',
      p_tournament_id USING ERRCODE = '55000';
  END IF;
  IF lower(COALESCE(v_t.variant, '')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type, '')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL
     OR v_t.satellite_target IS NOT NULL THEN
    RAISE EXCEPTION
      'tournament % is a satellite; its bubble receives the seat-pool remainder',
      p_tournament_id USING ERRCODE = '22023';
  END IF;
  IF COALESCE(v_t.bubble_protection, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'tournament % has no bubble-protection promise',
      p_tournament_id USING ERRCODE = '55000';
  END IF;
  IF v_t.buy_in_amount IS NULL
     OR v_t.buy_in_amount::text IN ('NaN','Infinity','-Infinity')
     OR v_t.buy_in_amount <= 0
     OR v_t.buy_in_amount IS DISTINCT FROM round(v_t.buy_in_amount, 2) THEN
    RAISE EXCEPTION 'tournament % has invalid bubble buy-in %',
      p_tournament_id, v_t.buy_in_amount USING ERRCODE = '22003';
  END IF;
  v_bubble_amount := round(v_t.buy_in_amount, 2);
  IF v_t.prize_pool IS NULL OR v_t.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_t.prize_pool < v_bubble_amount
     OR v_t.prize_pool IS DISTINCT FROM round(v_t.prize_pool, 2) THEN
    RAISE EXCEPTION 'tournament % pool % cannot fund bubble amount %',
      p_tournament_id, v_t.prize_pool, v_bubble_amount USING ERRCODE = '23514';
  END IF;

  PERFORM 1 FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
   ORDER BY tp.id FOR UPDATE;
  SELECT count(*) INTO v_field_size
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text NOT IN ('playing','winner','eliminated')
  ) THEN
    RAISE EXCEPTION 'tournament % still has an unresolved roster',
      p_tournament_id USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'place',a.place,'amount',a.amount) ORDER BY a.place),'[]'::jsonb)
    INTO v_ladder
    FROM public.fn_ca_tournament_place_amounts(p_tournament_id) a;
  SELECT max((a->>'place')::integer) + 1
    INTO v_bubble_place
    FROM jsonb_array_elements(v_ladder) a;
  IF v_bubble_place IS NULL OR v_bubble_place > v_field_size THEN
    RAISE EXCEPTION 'tournament % final field has no stone bubble',
      p_tournament_id USING ERRCODE = '55000';
  END IF;

  SELECT count(*), count(tp.elimination_sequence),
         count(DISTINCT tp.elimination_sequence)
    INTO v_eliminated_count, v_sequenced_count, v_distinct_sequence_count
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status::text = 'eliminated';
  IF v_sequenced_count <> v_eliminated_count
     OR v_distinct_sequence_count <> v_eliminated_count THEN
    RAISE EXCEPTION 'tournament % has no complete durable elimination order',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  WITH ranked AS (
    SELECT tp.user_id, tp.position,
           (v_field_size - row_number() OVER (
             ORDER BY tp.elimination_sequence ASC, tp.id ASC
           ) + 1)::integer AS expected_position
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text = 'eliminated'
  )
  SELECT count(*), min(r.user_id::text)::uuid
    INTO v_candidate_count, v_bubble_user_id
    FROM ranked r
   WHERE r.expected_position = v_bubble_place
     AND r.position = v_bubble_place;
  IF v_candidate_count <> 1
     OR v_bubble_user_id IS DISTINCT FROM p_observed_bubble_user_id THEN
    RAISE EXCEPTION
      'observed bubble user % does not match durable place % in tournament %',
      p_observed_bubble_user_id, v_bubble_place, p_tournament_id
      USING ERRCODE = '40001';
  END IF;

  PERFORM 1 FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
   ORDER BY o.kind, o.place NULLS LAST, o.id FOR UPDATE;
  PERFORM 1 FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id
   ORDER BY p.id FOR SHARE;

  SELECT count(*), COALESCE(sum(p.amount), 0)
    INTO v_payout_count, v_paid
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id
     AND p.source = 'bubble_protection';
  IF v_paid > v_bubble_amount
     OR EXISTS (
       SELECT 1 FROM public.tournament_payouts p
        WHERE p.tournament_id = p_tournament_id
          AND p.source = 'bubble_protection'
          AND (p.user_id IS DISTINCT FROM v_bubble_user_id
            OR p."position" IS NOT NULL
            OR p.amount IS NULL
            OR p.amount::text IN ('NaN','Infinity','-Infinity')
            OR p.amount <= 0
            OR p.amount IS DISTINCT FROM round(p.amount, 2)
            OR p.idempotency_key IS NULL
            OR NOT EXISTS (
              SELECT 1 FROM public.wallet_credit_idempotency k
               WHERE k.key = p.idempotency_key
                 AND k.user_id = p.user_id
                 AND k.amount = p.amount))) THEN
    RAISE EXCEPTION 'tournament % has malformed bubble payout evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_ob_count
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND o.kind = 'bubble_protection';
  SELECT * INTO v_ob
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND o.kind = 'bubble_protection'
     AND o.user_id = v_bubble_user_id;
  IF v_ob_count = 0 THEN
    IF v_payout_count <> 0 OR v_paid <> 0 THEN
      RAISE EXCEPTION 'tournament % has bubble money without its debt record',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    INSERT INTO public.tournament_obligations
      (tournament_id, kind, place, user_id, amount_owed, amount_paid, source)
    VALUES
      (p_tournament_id, 'bubble_protection', NULL, v_bubble_user_id,
       v_bubble_amount, 0, 'engine.fn_settle_tournament_bubble_protection')
    RETURNING * INTO v_ob;
  ELSIF v_ob_count <> 1 OR v_ob.id IS NULL
     OR v_ob.place IS NOT NULL
     OR v_ob.amount_owed IS DISTINCT FROM v_bubble_amount
     OR v_ob.amount_paid IS DISTINCT FROM v_paid
     OR v_ob.amount_paid < 0 OR v_ob.amount_paid > v_ob.amount_owed
     OR (v_ob.amount_paid = v_ob.amount_owed) IS DISTINCT FROM
        (v_ob.settled_at IS NOT NULL) THEN
    RAISE EXCEPTION 'tournament % has malformed bubble obligation evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  v_result := public.fn_ca_settle_tournament_bubble_raw(
    p_tournament_id, v_bubble_user_id, v_bubble_amount);
  UPDATE public.tournament_players
     SET prize = v_bubble_amount
   WHERE tournament_id = p_tournament_id
     AND user_id = v_bubble_user_id
     AND position = v_bubble_place;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION
      'could not stamp one bubble prize cache for tournament %, place %',
      p_tournament_id, v_bubble_place USING ERRCODE = 'P0404';
  END IF;
  RETURN jsonb_build_object(
    'ok', true,
    'fully_settled', true,
    'user_id', v_bubble_user_id,
    'position', v_bubble_place,
    'amount', v_bubble_amount,
    'settlement', v_result);
END;
$$;


ALTER FUNCTION public.fn_settle_tournament_bubble_protection(p_tournament_id uuid, p_observed_bubble_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_settle_tournament_bubble_protection(p_tournament_id uuid, p_observed_bubble_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settle_tournament_bubble_protection(p_tournament_id uuid, p_observed_bubble_user_id uuid) IS 'Service-only immediate bubble door: identity is observed, while locked database state derives the eligible user, place and base buy-in.';


--
-- Name: fn_settle_tournament_final_table_deal(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_tournament_final_table_deal(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t record;
  v_status text;
  v_table_size integer;
  v_field_size integer;
  v_live_count integer;
  v_live_table_count integer;
  v_live_seat_count integer;
  v_live_seated_users integer;
  v_vote_count integer;
  v_total_chips numeric;
  v_pool_cents bigint;
  v_prior_paid_cents bigint;
  v_fixed_entitlement_cents bigint := 0;
  v_fixed_paid_cents bigint := 0;
  v_fixed_shortfall_cents bigint := 0;
  v_fixed_count integer := 0;
  v_ladder_max_place integer;
  v_bubble_place integer;
  v_bubble_user_id uuid;
  v_bubble_amount numeric(15,2) := 0;
  v_bubble_entitlement_cents bigint := 0;
  v_bubble_paid_cents bigint := 0;
  v_bubble_shortfall_cents bigint := 0;
  v_bubble_obligation_count integer := 0;
  v_bubble_candidate_count integer := 0;
  v_has_bubble boolean := false;
  v_bubble_obligation_source text :=
    'engine.fn_settle_tournament_bubble_protection';
  v_undistributed_cents bigint;
  v_distributed_cents bigint := 0;
  v_remainder_cents bigint;
  v_share_cents bigint;
  v_amount numeric(15,2);
  v_rank integer := 0;
  v_rows integer;
  v_now timestamptz := now();
  v_leader uuid;
  v_result jsonb;
  v_guarantee_result jsonb;
  v_ladder jsonb := '[]'::jsonb;
  v_fixed jsonb := '[]'::jsonb;
  v_shares jsonb := '[]'::jsonb;
  v_payouts jsonb := '[]'::jsonb;
  v_winner_amount numeric(15,2) := 0;
  v_row record;
  v_ob public.tournament_obligations%ROWTYPE;
  v_evidence numeric;
  v_evidence_count integer;
  v_not_pool text[] := ARRAY[
    'satellite_seat','bounty','mystery_bounty','bounty_residual',
    'own_bounty','mystery_bounty_residual'
  ];
BEGIN
  -- Share the same first lock as the whole-event terminal authority. Re-entry
  -- from that authority is transaction-local and immediate.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'final-table deal requires a tournament id'
      USING ERRCODE = '22004';
  END IF;

  -- Canonical money lock order: tournament, authoritative guarantee-funding
  -- bank, complete roster, complete obligation set. Every validation and every
  -- amount derivation follows it.
  SELECT t.id, t.status, t.prize_pool, t.final_table_deal_enabled,
         t.table_size, t.variant, t.tournament_type, t.satellite_target_id,
         t.satellite_target, t.bubble_protection, t.buy_in_amount,
         t.guaranteed_prize, t.prize_pool_finalized
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;

  v_status := upper(COALESCE(v_t.status::text, ''));
  IF v_status NOT IN ('RUNNING','COMPLETING','COMPLETED') THEN
    RAISE EXCEPTION 'tournament % cannot execute or replay a deal from status %',
      p_tournament_id, v_t.status USING ERRCODE = '55000';
  END IF;
  IF lower(COALESCE(v_t.variant::text, '')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type::text, '')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL
     OR v_t.satellite_target IS NOT NULL THEN
    RAISE EXCEPTION 'tournament % is a satellite, not a cash final-table deal',
      p_tournament_id USING ERRCODE = '22023';
  END IF;

  -- The chop and any guarantee overlay are one commit. A process-side funding
  -- request can improve the live preview, but it is never settlement evidence:
  -- this locked authority funds again idempotently and proves the refreshed
  -- pool before it derives fixed places or a single deal share.
  IF v_t.prize_pool IS NULL
     OR v_t.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_t.prize_pool < 0
     OR v_t.prize_pool IS DISTINCT FROM round(v_t.prize_pool, 2) THEN
    RAISE EXCEPTION 'tournament % has invalid whole-cent prize pool %',
      p_tournament_id, v_t.prize_pool USING ERRCODE = '22003';
  END IF;
  IF v_t.guaranteed_prize IS NOT NULL
     AND (v_t.guaranteed_prize::text IN ('NaN','Infinity','-Infinity')
       OR v_t.guaranteed_prize < 0
       OR v_t.guaranteed_prize IS DISTINCT FROM round(v_t.guaranteed_prize, 2)) THEN
    RAISE EXCEPTION 'tournament % has invalid whole-cent guarantee %',
      p_tournament_id, v_t.guaranteed_prize USING ERRCODE = '22003';
  END IF;
  v_guarantee_result := public.fn_apply_prize_guarantee(
    p_tournament_id, 'engine.fn_settle_tournament_final_table_deal');
  IF COALESCE((v_guarantee_result->>'ok')::boolean, false) IS NOT TRUE
     OR (COALESCE((v_guarantee_result->>'overlay')::numeric,0) > 0
         AND COALESCE(
           (v_guarantee_result->>'overlay_journaled')::boolean,false)
             IS NOT TRUE) THEN
    RAISE EXCEPTION 'tournament % guarantee funding refused before deal: %',
      p_tournament_id, v_guarantee_result USING ERRCODE = 'P0404';
  END IF;

  SELECT t.id, t.status, t.prize_pool, t.final_table_deal_enabled,
         t.table_size, t.variant, t.tournament_type, t.satellite_target_id,
         t.satellite_target, t.bubble_protection, t.buy_in_amount,
         t.guaranteed_prize, t.prize_pool_finalized
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF COALESCE(v_t.prize_pool_finalized, false) IS NOT TRUE
     OR v_t.prize_pool IS NULL
     OR v_t.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_t.prize_pool IS DISTINCT FROM round(v_t.prize_pool, 2)
     OR v_t.prize_pool < COALESCE(v_t.guaranteed_prize, 0)
     OR v_guarantee_result->>'prize_pool' IS NULL
     OR (v_guarantee_result->>'prize_pool')::numeric IS DISTINCT FROM v_t.prize_pool THEN
    RAISE EXCEPTION
      'tournament % guarantee funding did not produce one finalized locked deal pool: result %, pool %, guarantee %, finalized %',
      p_tournament_id, v_guarantee_result, v_t.prize_pool,
      v_t.guaranteed_prize, v_t.prize_pool_finalized USING ERRCODE = 'P0404';
  END IF;

  PERFORM 1
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
   ORDER BY tp.id
   FOR UPDATE;

  PERFORM 1
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
   ORDER BY o.kind, o.place NULLS LAST, o.id
   FOR UPDATE;

  -- Evidence rows are append-only. Canonical payers hold the tournament lock;
  -- row locks additionally keep an existing receipt stable while it is proved.
  PERFORM 1
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id
   ORDER BY p.id
   FOR SHARE;

  IF v_t.table_size IS NULL OR v_t.table_size < 2 OR v_t.table_size > 10 THEN
    RAISE EXCEPTION 'tournament % has invalid final-table size %',
      p_tournament_id, v_t.table_size USING ERRCODE = '23514';
  END IF;
  v_table_size := v_t.table_size;

  SELECT count(*) INTO v_field_size
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  IF v_field_size < 2 THEN
    RAISE EXCEPTION 'tournament % has fewer than two roster rows', p_tournament_id
      USING ERRCODE = '23514';
  END IF;

  -- Every payout row that consumes the prize pool must be finite, nonnegative,
  -- whole-cent evidence tied to the exact wallet-credit identity. The player
  -- prize column is deliberately absent from this calculation: it is a cache,
  -- never evidence that money moved.
  IF EXISTS (
    SELECT 1
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND NOT (COALESCE(p.source, '') = ANY (v_not_pool))
       AND (
         p.amount IS NULL
         OR p.amount::text IN ('NaN','Infinity','-Infinity')
         OR p.amount <= 0
         OR p.amount IS DISTINCT FROM round(p.amount, 2)
         OR NOT EXISTS (
           SELECT 1
             FROM public.tournament_players tp
            WHERE tp.tournament_id = p_tournament_id
              AND tp.user_id = p.user_id
              AND (p."position" IS NULL OR tp.position = p."position")
         )
         OR (p.amount > 0 AND (
           p.idempotency_key IS NULL
           OR NOT EXISTS (
             SELECT 1
               FROM public.wallet_credit_idempotency k
              WHERE k.key = p.idempotency_key
                AND k.user_id = p.user_id
                AND k.amount = p.amount
           )
         ))
       )
  ) THEN
    RAISE EXCEPTION 'tournament % has malformed or unbacked prize payout evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_t.prize_pool IS NULL
     OR v_t.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_t.prize_pool <= 0
     OR v_t.prize_pool IS DISTINCT FROM round(v_t.prize_pool, 2) THEN
    RAISE EXCEPTION 'tournament % has invalid whole-cent prize pool %',
      p_tournament_id, v_t.prize_pool USING ERRCODE = '22003';
  END IF;
  v_pool_cents := round(v_t.prize_pool * 100)::bigint;

  -- The locked structure fixes every already-eliminated cash entitlement.
  -- Live places are superseded by the unanimous chip chop; places below the
  -- live field remain exact structure debts and reduce the chop residual at
  -- their full entitlement, whether previously unpaid, partly paid or paid.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'place', a.place,
           'amount', a.amount,
           'cents', round(a.amount * 100)::bigint
         ) ORDER BY a.place), '[]'::jsonb)
    INTO v_ladder
    FROM public.fn_ca_tournament_place_amounts(p_tournament_id) a;
  IF jsonb_array_length(v_ladder) = 0 THEN
    RAISE EXCEPTION 'tournament % derived an empty cash structure',
      p_tournament_id USING ERRCODE = '23514';
  END IF;
  SELECT max((e->>'place')::integer)
    INTO v_ladder_max_place
    FROM jsonb_array_elements(v_ladder) e;
  IF v_ladder_max_place IS NULL OR v_ladder_max_place < 1 THEN
    RAISE EXCEPTION 'tournament % derived an invalid cash structure tail',
      p_tournament_id USING ERRCODE = '23514';
  END IF;
  v_bubble_place := v_ladder_max_place + 1;

  IF v_status = 'RUNNING' THEN
    SELECT count(*), COALESCE(sum(tp.chips), 0)
      INTO v_live_count, v_total_chips
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text = 'playing'
       AND tp.eliminated_at IS NULL;
  ELSIF v_status IN ('COMPLETING','COMPLETED') THEN
    SELECT count(DISTINCT p.user_id) INTO v_live_count
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.source = 'final_table_deal';
  ELSE
    RAISE EXCEPTION 'tournament % cannot execute or replay a deal from status %',
      p_tournament_id, v_t.status USING ERRCODE = '55000';
  END IF;

  IF v_live_count < 2 OR v_live_count > v_table_size THEN
    RAISE EXCEPTION 'tournament % has % dealt/live players outside final-table size %',
      p_tournament_id, v_live_count, v_table_size USING ERRCODE = '55000';
  END IF;

  -- Late registration can grow the final field after an early bust already
  -- received a then-correct position. Normalize the locked eliminated tail
  -- before pricing its fixed places. The DB-owned elimination_sequence is the
  -- durable chronology witness: the latest elimination gets live_count+1 and
  -- the earliest gets field_size. Mutable wall clocks and stale place numbers
  -- are never used to reconstruct history. The consolidated predecessor owns
  -- the sequence column, allocator, unique index and transition trigger.
  IF v_status = 'RUNNING' THEN
    IF EXISTS (
      SELECT 1 FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id
         AND (
           (tp.status::text = 'playing' AND tp.eliminated_at IS NULL
             AND (tp.position IS NOT NULL OR tp.elimination_sequence IS NOT NULL))
           OR
           (NOT (tp.status::text = 'playing' AND tp.eliminated_at IS NULL)
             AND (tp.status::text <> 'eliminated'
               OR tp.eliminated_at IS NULL
               OR tp.position IS NULL
               OR tp.position < 2
               OR tp.position > v_field_size
               OR tp.elimination_sequence IS NULL
               OR tp.elimination_sequence <= 0))
         )
    ) OR (SELECT count(DISTINCT tp.elimination_sequence)
            FROM public.tournament_players tp
           WHERE tp.tournament_id = p_tournament_id
             AND tp.status::text = 'eliminated'
             AND tp.eliminated_at IS NOT NULL)
          <> v_field_size - v_live_count
    THEN
      RAISE EXCEPTION
        'tournament % roster lacks complete unique elimination-sequence evidence',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;

    UPDATE public.tournament_players tp
       SET position = NULL
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text = 'eliminated'
       AND tp.eliminated_at IS NOT NULL;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> v_field_size - v_live_count THEN
      RAISE EXCEPTION 'tournament % normalized % of % eliminated standings',
        p_tournament_id, v_rows, v_field_size - v_live_count
        USING ERRCODE = 'P0404';
    END IF;

    WITH ranked AS (
      SELECT tp.id,
             (v_live_count + row_number() OVER (
               ORDER BY tp.elimination_sequence DESC NULLS LAST, tp.id ASC))::integer
               AS normalized_position
        FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id
         AND tp.status::text = 'eliminated'
         AND tp.eliminated_at IS NOT NULL
    )
    UPDATE public.tournament_players tp
       SET position = ranked.normalized_position
      FROM ranked
     WHERE tp.id = ranked.id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> v_field_size - v_live_count THEN
      RAISE EXCEPTION 'tournament % could not finish tail normalization',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  ELSIF EXISTS (
    SELECT 1
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text = 'eliminated'
       AND (tp.eliminated_at IS NULL OR tp.elimination_sequence IS NULL
         OR tp.elimination_sequence <= 0)
  ) OR (SELECT count(DISTINCT tp.elimination_sequence)
          FROM public.tournament_players tp
         WHERE tp.tournament_id = p_tournament_id
           AND tp.status::text = 'eliminated')
        <> (SELECT count(*)
              FROM public.tournament_players tp
             WHERE tp.tournament_id = p_tournament_id
               AND tp.status::text = 'eliminated') THEN
    RAISE EXCEPTION
      'tournament % replay lacks complete unique elimination-sequence evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- Bubble protection is part of the locked tournament prize pool. It exists
  -- only when the durable eliminated tail already contains the one player at
  -- max(cash place)+1. If that place is still among the players making this
  -- deal, nobody bubbled and the full remaining pool is chopped. A completed
  -- bubble is exact prior pool evidence; partial or differently-owned state is
  -- never resumed.
  IF COALESCE(v_t.bubble_protection, false)
     AND v_field_size > v_ladder_max_place THEN
    IF v_t.buy_in_amount IS NULL
       OR v_t.buy_in_amount::text IN ('NaN','Infinity','-Infinity')
       OR v_t.buy_in_amount <= 0
       OR v_t.buy_in_amount IS DISTINCT FROM round(v_t.buy_in_amount, 2) THEN
      RAISE EXCEPTION 'tournament % has an invalid bubble-protection buy-in %',
        p_tournament_id, v_t.buy_in_amount USING ERRCODE = '22003';
    END IF;

    IF v_bubble_place > v_live_count THEN
      SELECT count(*)
        INTO v_bubble_candidate_count
        FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id
         AND tp.position = v_bubble_place
         AND tp.status::text = 'eliminated'
         AND tp.eliminated_at IS NOT NULL
         AND tp.elimination_sequence IS NOT NULL
         AND tp.elimination_sequence > 0;
      SELECT tp.user_id
        INTO v_bubble_user_id
        FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id
         AND tp.position = v_bubble_place
         AND tp.status::text = 'eliminated'
         AND tp.eliminated_at IS NOT NULL
         AND tp.elimination_sequence IS NOT NULL
         AND tp.elimination_sequence > 0
       ORDER BY tp.id
       LIMIT 1;
      IF v_bubble_candidate_count <> 1 OR v_bubble_user_id IS NULL THEN
        RAISE EXCEPTION
          'tournament % lacks one durable stone-bubble finisher at place %',
          p_tournament_id, v_bubble_place USING ERRCODE = 'P0404';
      END IF;
      v_has_bubble := true;
      v_bubble_amount := v_t.buy_in_amount::numeric(15,2);
      v_bubble_entitlement_cents := round(v_bubble_amount * 100)::bigint;
    END IF;
  END IF;

  SELECT count(*)
    INTO v_bubble_obligation_count
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND o.kind = 'bubble_protection';
  SELECT count(*), COALESCE(sum(p.amount), 0)
    INTO v_evidence_count, v_evidence
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id
     AND p.source = 'bubble_protection';

  IF NOT v_has_bubble THEN
    IF v_bubble_obligation_count <> 0 OR v_evidence_count <> 0 THEN
      RAISE EXCEPTION
        'tournament % has bubble state without an eligible eliminated bubble',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  ELSIF v_bubble_obligation_count = 0 AND v_evidence_count = 0 THEN
    v_bubble_paid_cents := 0;
  ELSIF v_bubble_obligation_count = 1 AND v_evidence_count = 0 THEN
    -- A prior atomic attempt may have shaped the canonical debt before any
    -- wallet movement. That state is safe to resume, but only while it is
    -- exactly unpaid and has no orphaned obligation-key credit witness.
    SELECT * INTO v_ob
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'bubble_protection';
    SELECT count(*) INTO v_rows
      FROM public.wallet_credit_idempotency k
     WHERE k.key LIKE
       'tourney:' || p_tournament_id::text || ':obl:' || v_ob.id::text || ':%';
    IF v_ob.id IS NULL
       OR v_ob.place IS NOT NULL
       OR v_ob.user_id IS DISTINCT FROM v_bubble_user_id
       OR v_ob.amount_owed IS DISTINCT FROM v_bubble_amount
       OR v_ob.amount_paid IS DISTINCT FROM 0::numeric
       OR v_ob.source IS DISTINCT FROM v_bubble_obligation_source
       OR v_ob.adjustment_id IS NOT NULL
       OR v_ob.settled_at IS NOT NULL
       OR v_rows <> 0 THEN
      RAISE EXCEPTION
        'tournament % has partial or mismatched unpaid bubble-protection state',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    v_bubble_paid_cents := 0;
  ELSIF v_bubble_obligation_count = 1 AND v_evidence_count = 1 THEN
    SELECT * INTO v_ob
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'bubble_protection';
    SELECT count(*) INTO v_rows
      FROM public.wallet_credit_idempotency k
     WHERE k.key =
       'tourney:' || p_tournament_id::text || ':obl:' || v_ob.id::text || ':0';
    IF v_ob.id IS NULL
       OR v_ob.place IS NOT NULL
       OR v_ob.user_id IS DISTINCT FROM v_bubble_user_id
       OR v_ob.amount_owed IS DISTINCT FROM v_bubble_amount
       OR v_ob.amount_paid IS DISTINCT FROM v_bubble_amount
       OR v_ob.source IS DISTINCT FROM v_bubble_obligation_source
       OR v_ob.adjustment_id IS NOT NULL
       OR v_ob.settled_at IS NULL
       OR v_evidence IS DISTINCT FROM v_bubble_amount
       OR v_rows <> 1
       OR (SELECT count(*)
             FROM public.wallet_credit_idempotency k
            WHERE k.key LIKE
              'tourney:' || p_tournament_id::text || ':obl:' || v_ob.id::text || ':%')
          <> 1
       OR NOT EXISTS (
         SELECT 1
           FROM public.tournament_payouts p
           JOIN public.wallet_credit_idempotency k
             ON k.key = p.idempotency_key
            AND k.user_id = p.user_id
            AND k.amount = p.amount
          WHERE p.tournament_id = p_tournament_id
            AND p.source = 'bubble_protection'
            AND p."position" IS NULL
            AND p.user_id = v_bubble_user_id
            AND p.amount = v_bubble_amount
            AND p.idempotency_key =
              'tourney:' || p_tournament_id::text || ':obl:' || v_ob.id::text || ':0'
       ) THEN
      RAISE EXCEPTION
        'tournament % has partial or mismatched bubble-protection evidence',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    v_bubble_paid_cents := v_bubble_entitlement_cents;
  ELSE
    RAISE EXCEPTION
      'tournament % has incomplete bubble-protection evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  v_bubble_shortfall_cents :=
    v_bubble_entitlement_cents - v_bubble_paid_cents;

  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(v_ladder) e
      LEFT JOIN public.tournament_players tp
        ON tp.tournament_id = p_tournament_id
       AND tp.position = (e->>'place')::integer
     WHERE (e->>'place')::integer > v_live_count
       AND (e->>'cents')::bigint > 0
       AND (tp.id IS NULL OR tp.status::text <> 'eliminated'
         OR tp.eliminated_at IS NULL)
  ) THEN
    RAISE EXCEPTION
      'tournament % has a positive eliminated-place entitlement without its exact finisher',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'place', q.place,
           'user_id', q.user_id,
           'amount', q.amount,
           'cents', q.cents,
           'evidence_cents', q.evidence_cents
         ) ORDER BY q.place), '[]'::jsonb)
    INTO v_fixed
    FROM (
      SELECT (e->>'place')::integer AS place,
             tp.user_id,
             (e->>'amount')::numeric(15,2) AS amount,
             (e->>'cents')::bigint AS cents,
             COALESCE(sum(round(p.amount * 100)::bigint), 0)::bigint
               AS evidence_cents
        FROM jsonb_array_elements(v_ladder) e
        JOIN public.tournament_players tp
          ON tp.tournament_id = p_tournament_id
         AND tp.position = (e->>'place')::integer
        LEFT JOIN public.tournament_payouts p
          ON p.tournament_id = p_tournament_id
         AND p."position" = (e->>'place')::integer
         AND p.user_id = tp.user_id
         AND NOT (COALESCE(p.source, '') = ANY (v_not_pool))
         AND p.source <> 'final_table_deal'
         AND p.source <> 'bubble_protection'
       WHERE (e->>'place')::integer > v_live_count
         AND (e->>'cents')::bigint > 0
       GROUP BY (e->>'place')::integer, tp.user_id,
                (e->>'amount')::numeric(15,2), (e->>'cents')::bigint
    ) q;

  SELECT jsonb_array_length(v_fixed),
         COALESCE(sum((e->>'cents')::bigint), 0)::bigint,
         COALESCE(sum((e->>'evidence_cents')::bigint), 0)::bigint
    INTO v_fixed_count, v_fixed_entitlement_cents, v_fixed_paid_cents
    FROM jsonb_array_elements(v_fixed) e;

  -- Pool evidence before the deal must be exact evidence for one of those
  -- fixed eliminated places. Unpositioned, live-place, non-ITM and wrong-user
  -- rows cannot silently shrink the amount being chopped.
  IF EXISTS (
    SELECT 1
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND NOT (COALESCE(p.source, '') = ANY (v_not_pool))
       AND p.source <> 'final_table_deal'
       AND NOT (
         (p.source = 'bubble_protection'
          AND v_has_bubble
          AND p."position" IS NULL
          AND p.user_id = v_bubble_user_id
          AND p.amount = v_bubble_amount)
         OR EXISTS (
           SELECT 1 FROM jsonb_array_elements(v_fixed) e
            WHERE (e->>'place')::integer = p."position"
              AND (e->>'user_id')::uuid = p.user_id
         )
       )
  ) OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_fixed) e
     WHERE (e->>'evidence_cents')::bigint < 0
        OR (e->>'evidence_cents')::bigint > (e->>'cents')::bigint
  ) THEN
    RAISE EXCEPTION
      'tournament % has payout evidence outside an exact fixed-place entitlement',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT COALESCE(sum(round(p.amount * 100)::bigint), 0)::bigint
    INTO v_prior_paid_cents
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id
     AND NOT (COALESCE(p.source, '') = ANY (v_not_pool))
     AND COALESCE(p.source, '') <> 'final_table_deal';

  IF v_prior_paid_cents < 0 OR v_prior_paid_cents > v_pool_cents
     OR v_prior_paid_cents <>
          v_fixed_paid_cents + v_bubble_paid_cents THEN
    RAISE EXCEPTION 'tournament % records % prior prize cents against a % cent pool',
      p_tournament_id, v_prior_paid_cents, v_pool_cents
      USING ERRCODE = '23514';
  END IF;
  v_fixed_shortfall_cents := v_fixed_entitlement_cents - v_fixed_paid_cents;
  IF v_fixed_shortfall_cents < 0 OR v_bubble_shortfall_cents < 0
     OR v_prior_paid_cents + v_fixed_shortfall_cents
          + v_bubble_shortfall_cents > v_pool_cents THEN
    RAISE EXCEPTION 'tournament % has invalid fixed-place or bubble reserve',
      p_tournament_id USING ERRCODE = '23514';
  END IF;
  v_undistributed_cents :=
    v_pool_cents - v_prior_paid_cents - v_fixed_shortfall_cents
      - v_bubble_shortfall_cents;

  -- COMPLETING/COMPLETED is an evidence-only replay. It cannot infer a deal
  -- from mutable chip counts or silently convert a normal finish into a deal.
  IF v_status IN ('COMPLETING','COMPLETED') THEN
    IF v_has_bubble
       AND v_bubble_paid_cents <> v_bubble_entitlement_cents THEN
      RAISE EXCEPTION
        'tournament % replay lacks its exact pool-funded bubble receipt',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.source = 'final_table_deal'
    ) OR NOT EXISTS (
      SELECT 1 FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'final_table_deal'
    ) THEN
      RAISE EXCEPTION 'tournament % is % without a durable final-table-deal receipt',
        p_tournament_id, v_status USING ERRCODE = '55000';
    END IF;

    IF EXISTS (
      SELECT 1
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.source = 'final_table_deal'
         AND (p."position" IS NOT NULL OR p.amount <= 0)
    ) THEN
      RAISE EXCEPTION 'tournament % has malformed final-table-deal payout rows',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;

    IF EXISTS (
      SELECT 1
        FROM (
          SELECT p.user_id, count(*) AS n, sum(p.amount) AS amount,
                 min(p.idempotency_key) AS idempotency_key
            FROM public.tournament_payouts p
           WHERE p.tournament_id = p_tournament_id
             AND p.source = 'final_table_deal'
           GROUP BY p.user_id
        ) e
        LEFT JOIN public.tournament_players tp
          ON tp.tournament_id = p_tournament_id AND tp.user_id = e.user_id
        LEFT JOIN public.tournament_obligations o
          ON o.tournament_id = p_tournament_id
         AND o.kind = 'final_table_deal'
         AND o.place IS NULL
         AND o.user_id = e.user_id
       WHERE e.n <> 1
          OR tp.id IS NULL
          OR tp.position IS NULL
          OR tp.position < 1
          OR tp.position > v_live_count
          OR tp.prize IS DISTINCT FROM e.amount
          OR (tp.position = 1 AND tp.status::text <> 'winner')
          OR (tp.position > 1 AND tp.status::text <> 'eliminated')
          OR o.id IS NULL
          OR o.amount_owed IS DISTINCT FROM e.amount
          OR o.amount_paid IS DISTINCT FROM e.amount
          OR o.source IS DISTINCT FROM 'final_table_deal'
          OR o.adjustment_id IS NOT NULL
          OR o.settled_at IS NULL
          OR e.idempotency_key IS DISTINCT FROM
             'tourney:' || p_tournament_id::text || ':obl:' || o.id::text || ':0'
          OR (SELECT count(*)
                FROM public.wallet_credit_idempotency k
               WHERE k.key LIKE
                 'tourney:' || p_tournament_id::text || ':obl:' || o.id::text || ':%')
             <> 1
          OR NOT EXISTS (
            SELECT 1
              FROM public.wallet_credit_idempotency k
             WHERE k.key = e.idempotency_key
               AND k.user_id = e.user_id
               AND k.amount = e.amount
          )
    ) OR EXISTS (
      SELECT 1
        FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'final_table_deal'
         AND (o.place IS NOT NULL OR NOT EXISTS (
           SELECT 1 FROM public.tournament_payouts p
            WHERE p.tournament_id = p_tournament_id
              AND p.source = 'final_table_deal'
              AND p.user_id = o.user_id
         ))
    ) THEN
      RAISE EXCEPTION 'tournament % final-table-deal obligations, evidence and standings disagree',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;

    IF (SELECT count(*) FROM public.tournament_obligations o
         WHERE o.tournament_id = p_tournament_id AND o.kind = 'place')
         <> v_fixed_count
       OR EXISTS (
         SELECT 1
           FROM jsonb_array_elements(v_fixed) e
           LEFT JOIN public.tournament_obligations o
             ON o.tournament_id = p_tournament_id
            AND o.kind = 'place'
            AND o.place = (e->>'place')::integer
          WHERE o.id IS NULL
             OR o.user_id IS DISTINCT FROM (e->>'user_id')::uuid
             OR o.amount_owed IS DISTINCT FROM (e->>'amount')::numeric
             OR o.amount_paid IS DISTINCT FROM (e->>'amount')::numeric
             OR o.settled_at IS NULL
             OR (e->>'evidence_cents')::bigint <> (e->>'cents')::bigint
       ) THEN
      RAISE EXCEPTION
        'tournament % fixed-place obligations or evidence are not fully settled',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;

    IF (SELECT count(*) FROM public.tournament_players tp
         WHERE tp.tournament_id = p_tournament_id
           AND tp.position BETWEEN 1 AND v_field_size) <> v_field_size
       OR EXISTS (
         SELECT 1 FROM generate_series(1, v_field_size) g(place)
          WHERE NOT EXISTS (
            SELECT 1 FROM public.tournament_players tp
             WHERE tp.tournament_id = p_tournament_id
               AND tp.position = g.place
          )
       )
       OR EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id
            AND (tp.position IS NULL OR tp.position < 1
              OR tp.position > v_field_size)
       )
       OR NOT EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id
            AND tp.position = 1
            AND tp.status::text = 'winner'
            AND tp.eliminated_at IS NULL
            AND tp.elimination_sequence IS NULL
       )
       OR EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id
            AND tp.position > 1
            AND (tp.status::text <> 'eliminated'
              OR tp.eliminated_at IS NULL
              OR tp.elimination_sequence IS NULL
              OR tp.elimination_sequence <= 0)
       )
       OR EXISTS (
         SELECT 1
           FROM (
             SELECT tp.position,
                    (1 + row_number() OVER (
                      ORDER BY tp.elimination_sequence DESC NULLS LAST, tp.id ASC))::integer
                      AS expected_position
               FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.status::text = 'eliminated'
           ) ranked
          WHERE ranked.position IS DISTINCT FROM ranked.expected_position
       )
       OR EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id
            AND tp.prize IS DISTINCT FROM COALESCE((
              SELECT sum(p.amount)
                FROM public.tournament_payouts p
               WHERE p.tournament_id = p_tournament_id
                 AND p.user_id = tp.user_id
                 AND NOT (COALESCE(p.source, '') = ANY (v_not_pool))
            ), 0)
       ) THEN
      RAISE EXCEPTION 'tournament % replay has incomplete final standings',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;

    SELECT count(*) INTO v_vote_count
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position BETWEEN 1 AND v_live_count
       AND EXISTS (
         SELECT 1 FROM public.tournament_deal_votes v
          WHERE v.tournament_id = p_tournament_id
            AND v.user_id = tp.user_id
       );
    IF v_vote_count <> v_live_count THEN
      RAISE EXCEPTION 'tournament % replay has only % of % durable deal votes',
        p_tournament_id, v_vote_count, v_live_count USING ERRCODE = 'P0404';
    END IF;

    SELECT COALESCE(sum(round(p.amount * 100)::bigint), 0)::bigint
      INTO v_distributed_cents
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.source = 'final_table_deal';
    IF v_prior_paid_cents + v_distributed_cents <> v_pool_cents THEN
      RAISE EXCEPTION 'tournament % replay accounts for % of % prize cents',
        p_tournament_id, v_prior_paid_cents + v_distributed_cents, v_pool_cents
        USING ERRCODE = '23514';
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'place', tp.position,
             'user_id', tp.user_id,
             'amount', p.amount
           ) ORDER BY tp.position), '[]'::jsonb)
      INTO v_payouts
      FROM public.tournament_payouts p
      JOIN public.tournament_players tp
        ON tp.tournament_id = p_tournament_id AND tp.user_id = p.user_id
     WHERE p.tournament_id = p_tournament_id
       AND p.source = 'final_table_deal';

    SELECT p.amount INTO v_winner_amount
      FROM public.tournament_payouts p
      JOIN public.tournament_players tp
        ON tp.tournament_id = p_tournament_id AND tp.user_id = p.user_id
     WHERE p.tournament_id = p_tournament_id
       AND p.source = 'final_table_deal'
       AND tp.position = 1;

    RETURN jsonb_build_object(
      'ok', true,
      'fully_settled', true,
      'status', v_status,
      'payouts', v_payouts,
      'winner_amount', v_winner_amount,
      'money_path', 'fn_settle_tournament_final_table_deal');
  END IF;

  IF v_status <> 'RUNNING' THEN
    RAISE EXCEPTION 'tournament % cannot execute a deal from status %',
      p_tournament_id, v_t.status USING ERRCODE = '55000';
  END IF;
  IF COALESCE(v_t.final_table_deal_enabled, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'tournament % does not have final-table deals enabled',
      p_tournament_id USING ERRCODE = '55000';
  END IF;
  IF v_undistributed_cents <= 0 THEN
    RAISE EXCEPTION 'tournament % has no undistributed prize money',
      p_tournament_id USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id AND p.source = 'final_table_deal'
  ) OR EXISTS (
    SELECT 1 FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'final_table_deal'
  ) THEN
    RAISE EXCEPTION 'RUNNING tournament % already has final-table-deal state',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_total_chips IS NULL
     OR v_total_chips::text IN ('NaN','Infinity','-Infinity')
     OR v_total_chips <= 0
     OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.status::text = 'playing'
          AND tp.eliminated_at IS NULL
          AND (tp.chips IS NULL OR tp.chips < 0)
     ) THEN
    RAISE EXCEPTION 'tournament % has invalid live chip evidence',
      p_tournament_id USING ERRCODE = '22003';
  END IF;

  -- A fresh deal may not omit an unresolved roster row or overwrite an
  -- existing standing. Prior eliminated positions must already occupy exactly
  -- the contiguous tail after the players who are about to chop.
  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND NOT (tp.status::text = 'playing' AND tp.eliminated_at IS NULL)
       AND (tp.status::text <> 'eliminated' OR tp.position IS NULL
         OR tp.eliminated_at IS NULL
         OR tp.position <= v_live_count OR tp.position > v_field_size)
  ) OR EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text = 'playing' AND tp.eliminated_at IS NULL
       AND tp.position IS NOT NULL
  ) OR (SELECT count(*) FROM public.tournament_players tp
         WHERE tp.tournament_id = p_tournament_id
           AND tp.position BETWEEN v_live_count + 1 AND v_field_size)
       <> v_field_size - v_live_count
  THEN
    RAISE EXCEPTION 'tournament % roster does not carry a complete pre-deal standing tail',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- A pre-existing place debt is accepted only when its owner, amount paid
  -- and payout evidence describe one exact fixed entitlement. A historical
  -- smaller amount_owed may be raised to the canonical structure amount below;
  -- paid evidence may never be rewritten or inferred from the prize cache.
  IF EXISTS (
    SELECT 1
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'place'
       AND NOT EXISTS (
         SELECT 1
           FROM jsonb_array_elements(v_fixed) e
          WHERE (e->>'place')::integer = o.place
            AND (e->>'user_id')::uuid = o.user_id
            AND o.amount_owed IS NOT NULL
            AND o.amount_paid IS NOT NULL
            AND o.amount_owed::text NOT IN ('NaN','Infinity','-Infinity')
            AND o.amount_paid::text NOT IN ('NaN','Infinity','-Infinity')
            AND o.amount_owed = round(o.amount_owed, 2)
            AND o.amount_paid = round(o.amount_paid, 2)
            AND o.amount_paid >= 0
            AND o.amount_owed >= o.amount_paid
            AND o.amount_owed <= (e->>'amount')::numeric
            AND round(o.amount_paid * 100)::bigint =
                (e->>'evidence_cents')::bigint
       )
  ) THEN
    RAISE EXCEPTION 'tournament % has an incompatible fixed-place obligation',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.tournament_obligations o
      JOIN public.wallet_credit_idempotency k
        ON k.key LIKE
           'tourney:' || p_tournament_id::text || ':obl:' || o.id::text || ':%'
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'place'
       AND NOT EXISTS (
         SELECT 1
           FROM public.tournament_payouts p
          WHERE p.idempotency_key = k.key
            AND p.tournament_id = p_tournament_id
            AND p.user_id = k.user_id
            AND p.amount = k.amount
            AND p."position" = o.place
       )
  ) THEN
    RAISE EXCEPTION
      'tournament % has a fixed-place wallet key without exact payout evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- An alive player cannot already own prize-bank payout evidence. That would
  -- make the remaining pool valid in aggregate but the recipient debt wrong.
  IF EXISTS (
    SELECT 1
      FROM public.tournament_payouts p
      JOIN public.tournament_players tp
        ON tp.tournament_id = p.tournament_id AND tp.user_id = p.user_id
     WHERE p.tournament_id = p_tournament_id
       AND NOT (COALESCE(p.source, '') = ANY (v_not_pool))
       AND tp.status::text = 'playing' AND tp.eliminated_at IS NULL
       AND p.amount > 0
  ) THEN
    RAISE EXCEPTION 'tournament % has prior prize evidence for a live deal player',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- Lock the current table layout after the three canonical money sets. The
  -- active seats must be exactly the live roster and must all be on one live
  -- tournament table.
  PERFORM 1 FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY tb.id FOR UPDATE;
  PERFORM 1
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY s.id
   FOR UPDATE OF s;

  SELECT count(DISTINCT s.table_id), count(*), count(DISTINCT s.user_id)
    INTO v_live_table_count, v_live_seat_count, v_live_seated_users
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id
     AND lower(tb.status::text) IN ('running','waiting')
     AND s.left_at IS NULL
     AND s.user_id IS NOT NULL;
  IF v_live_table_count <> 1
     OR v_live_seat_count <> v_live_count
     OR v_live_seated_users <> v_live_count
     OR EXISTS (
       (SELECT tp.user_id
          FROM public.tournament_players tp
         WHERE tp.tournament_id = p_tournament_id
           AND tp.status::text = 'playing' AND tp.eliminated_at IS NULL)
       EXCEPT
       (SELECT s.user_id
          FROM public.table_seats s
          JOIN public.tables tb ON tb.id = s.table_id
         WHERE tb.tournament_id = p_tournament_id
           AND lower(tb.status::text) IN ('running','waiting')
           AND s.left_at IS NULL AND s.user_id IS NOT NULL)
     ) OR EXISTS (
       (SELECT s.user_id
          FROM public.table_seats s
          JOIN public.tables tb ON tb.id = s.table_id
         WHERE tb.tournament_id = p_tournament_id
           AND lower(tb.status::text) IN ('running','waiting')
           AND s.left_at IS NULL AND s.user_id IS NOT NULL)
       EXCEPT
       (SELECT tp.user_id
          FROM public.tournament_players tp
         WHERE tp.tournament_id = p_tournament_id
           AND tp.status::text = 'playing' AND tp.eliminated_at IS NULL)
     ) THEN
    RAISE EXCEPTION 'tournament % live roster is not seated together at one final table',
      p_tournament_id USING ERRCODE = '55000';
  END IF;

  PERFORM 1 FROM public.tournament_deal_votes v
   WHERE v.tournament_id = p_tournament_id
   ORDER BY v.user_id FOR SHARE;
  SELECT count(*) INTO v_vote_count
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status::text = 'playing' AND tp.eliminated_at IS NULL
     AND EXISTS (
       SELECT 1 FROM public.tournament_deal_votes v
        WHERE v.tournament_id = p_tournament_id AND v.user_id = tp.user_id
     );
  IF v_vote_count <> v_live_count THEN
    RAISE EXCEPTION 'tournament % has only % of % required live-player votes',
      p_tournament_id, v_vote_count, v_live_count USING ERRCODE = '55000';
  END IF;

  -- Price in integer cents. Each proportional share is floored; the exact
  -- residual goes to the deterministic chip leader (rank 1).
  FOR v_row IN
    SELECT tp.user_id, tp.chips, tp.registered_at
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text = 'playing' AND tp.eliminated_at IS NULL
     ORDER BY tp.chips DESC, tp.registered_at ASC NULLS LAST, tp.user_id ASC
  LOOP
    v_rank := v_rank + 1;
    v_share_cents := floor(
      (v_row.chips::numeric * v_undistributed_cents::numeric) / v_total_chips
    )::bigint;
    IF v_share_cents <= 0 THEN
      RAISE EXCEPTION 'tournament % chip chop gives rank % a nonpositive share',
        p_tournament_id, v_rank USING ERRCODE = '23514';
    END IF;
    v_distributed_cents := v_distributed_cents + v_share_cents;
    v_shares := v_shares || jsonb_build_object(
      'place', v_rank,
      'user_id', v_row.user_id,
      'cents', v_share_cents);
    IF v_rank = 1 THEN v_leader := v_row.user_id; END IF;
  END LOOP;

  v_remainder_cents := v_undistributed_cents - v_distributed_cents;
  IF v_remainder_cents < 0 OR v_leader IS NULL THEN
    RAISE EXCEPTION 'tournament % produced an invalid deal residual of % cents',
      p_tournament_id, v_remainder_cents USING ERRCODE = '23514';
  END IF;

  -- Add the residual before the first write. Every recipient has one final
  -- amount and one obligation settlement.
  SELECT COALESCE(jsonb_agg(
           CASE WHEN e->>'user_id' = v_leader::text
                THEN jsonb_set(e, '{cents}',
                     to_jsonb((e->>'cents')::bigint + v_remainder_cents))
                ELSE e END
           ORDER BY (e->>'place')::integer
         ), '[]'::jsonb)
    INTO v_shares
    FROM jsonb_array_elements(v_shares) e;

  -- A stone-bubble debt, when one already exists, is part of the same complete
  -- transaction shape. It is pool-funded and user-keyed (position NULL).
  -- Complete historical evidence was proved above; only a genuinely absent
  -- row may be created here.
  IF v_has_bubble AND v_bubble_obligation_count = 0 THEN
    INSERT INTO public.tournament_obligations
      (tournament_id, kind, place, user_id, amount_owed, amount_paid,
       source, settled_at)
    VALUES
      (p_tournament_id, 'bubble_protection', NULL, v_bubble_user_id,
       v_bubble_amount, 0, v_bubble_obligation_source, NULL);
  END IF;

  -- Shape every positive fixed-place debt first. Existing evidence seeds
  -- amount_paid exactly; amount_owed becomes the canonical locked entitlement.
  -- No wallet can move until the bubble, this set and every deal share below
  -- all exist.
  FOR v_row IN
    SELECT (e->>'place')::integer AS place,
           (e->>'user_id')::uuid AS user_id,
           (e->>'amount')::numeric(15,2) AS amount,
           ((e->>'evidence_cents')::numeric / 100)::numeric(15,2)
             AS evidence
      FROM jsonb_array_elements(v_fixed) e
     ORDER BY (e->>'place')::integer
  LOOP
    UPDATE public.tournament_obligations o
       SET amount_owed = v_row.amount,
           user_id = v_row.user_id,
           source = COALESCE(o.source, 'engine.fn_settle_tournament_places'),
           updated_at = v_now,
           settled_at = CASE WHEN v_row.evidence = v_row.amount
                             THEN COALESCE(o.settled_at, v_now)
                             ELSE NULL END
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'place'
       AND o.place = v_row.place;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN
      INSERT INTO public.tournament_obligations
        (tournament_id, kind, place, user_id, amount_owed, amount_paid,
         source, settled_at)
      VALUES
        (p_tournament_id, 'place', v_row.place, v_row.user_id, v_row.amount,
         v_row.evidence, 'engine.fn_settle_tournament_places',
         CASE WHEN v_row.evidence = v_row.amount THEN v_now ELSE NULL END);
    ELSIF v_rows <> 1 THEN
      RAISE EXCEPTION 'tournament %, place % matched % fixed obligations',
        p_tournament_id, v_row.place, v_rows USING ERRCODE = '23505';
    END IF;
  END LOOP;

  -- Shape every positive deal share. The full positive fixed-place plus
  -- deal-share debt set is durable in this transaction before the first payer.
  INSERT INTO public.tournament_obligations
    (tournament_id, kind, place, user_id, amount_owed, amount_paid, source)
  SELECT p_tournament_id,
         'final_table_deal',
         NULL,
         (e->>'user_id')::uuid,
         ((e->>'cents')::numeric / 100)::numeric(15,2),
         0,
         'final_table_deal'
    FROM jsonb_array_elements(v_shares) e
   ORDER BY (e->>'place')::integer;

  PERFORM 1
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND o.kind IN ('bubble_protection','place','final_table_deal')
   ORDER BY o.kind, o.place NULLS LAST, o.user_id, o.id
   FOR UPDATE;

  IF (v_has_bubble AND (
        (SELECT count(*) FROM public.tournament_obligations o
          WHERE o.tournament_id = p_tournament_id
            AND o.kind = 'bubble_protection') <> 1
        OR NOT EXISTS (
          SELECT 1 FROM public.tournament_obligations o
           WHERE o.tournament_id = p_tournament_id
             AND o.kind = 'bubble_protection'
             AND o.place IS NULL
             AND o.user_id = v_bubble_user_id
             AND o.amount_owed = v_bubble_amount
             AND o.amount_paid =
                 (v_bubble_paid_cents::numeric / 100)::numeric(15,2)
             AND o.source = v_bubble_obligation_source
             AND o.adjustment_id IS NULL
             AND ((v_bubble_paid_cents = v_bubble_entitlement_cents
                    AND o.settled_at IS NOT NULL)
               OR (v_bubble_paid_cents = 0 AND o.settled_at IS NULL))
        )
      ))
     OR (NOT v_has_bubble AND EXISTS (
       SELECT 1 FROM public.tournament_obligations o
        WHERE o.tournament_id = p_tournament_id
          AND o.kind = 'bubble_protection'
     ))
     OR (SELECT count(*) FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'place') <> v_fixed_count
     OR EXISTS (
       SELECT 1
         FROM public.tournament_obligations o
        WHERE o.tournament_id = p_tournament_id
          AND o.kind = 'place'
          AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(v_fixed) e
             WHERE (e->>'place')::integer = o.place
               AND (e->>'user_id')::uuid = o.user_id
               AND (e->>'amount')::numeric IS NOT DISTINCT FROM o.amount_owed
               AND ((e->>'evidence_cents')::numeric / 100)::numeric(15,2)
                   IS NOT DISTINCT FROM o.amount_paid
               AND ((o.amount_paid = o.amount_owed AND o.settled_at IS NOT NULL)
                 OR (o.amount_paid < o.amount_owed AND o.settled_at IS NULL))
          )
     )
     OR (SELECT count(*) FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'final_table_deal') <> v_live_count
     OR EXISTS (
       SELECT 1
         FROM public.tournament_obligations o
        WHERE o.tournament_id = p_tournament_id
          AND o.kind = 'final_table_deal'
          AND (
            o.place IS NOT NULL
            OR o.amount_paid <> 0
            OR o.source IS DISTINCT FROM 'final_table_deal'
            OR o.settled_at IS NOT NULL
            OR NOT EXISTS (
              SELECT 1 FROM jsonb_array_elements(v_shares) e
               WHERE (e->>'user_id')::uuid = o.user_id
                 AND ((e->>'cents')::numeric / 100)::numeric(15,2)
                     IS NOT DISTINCT FROM o.amount_owed
            )
          )
    ) THEN
    RAISE EXCEPTION
      'tournament % could not shape the complete bubble, fixed-place and deal debt set',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- The complete positive obligation set now exists and is locked. Settle an
  -- eligible pool-funded bubble first, then each fixed place, still inside the
  -- same transaction as the chop. Any later refusal rolls every earlier wallet
  -- credit, payout, obligation and standing back together.
  IF v_has_bubble THEN
    v_result := public.fn_ca_settle_tournament_bubble_raw(
      p_tournament_id, v_bubble_user_id, v_bubble_amount);
    IF COALESCE((v_result->>'ok')::boolean, false) IS NOT TRUE
       OR COALESCE((v_result->>'fully_settled')::boolean, false) IS NOT TRUE
       OR (v_result->>'amount_owed')::numeric IS DISTINCT FROM v_bubble_amount
       OR (v_result->>'amount_paid')::numeric IS DISTINCT FROM v_bubble_amount
       OR COALESCE((v_result->>'remaining')::numeric, v_bubble_amount) <> 0 THEN
      RAISE EXCEPTION 'tournament % bubble protection did not settle in full',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  END IF;

  FOR v_row IN
    SELECT (e->>'place')::integer AS place,
           (e->>'user_id')::uuid AS user_id,
           (e->>'amount')::numeric(15,2) AS amount
      FROM jsonb_array_elements(v_fixed) e
     ORDER BY (e->>'place')::integer
  LOOP
    v_result := public.fn_ca_settle_tournament_place_raw(
      p_tournament_id, v_row.place, v_row.user_id, v_row.amount);
    IF COALESCE((v_result->>'ok')::boolean, false) IS NOT TRUE
       OR COALESCE((v_result->>'fully_settled')::boolean, false) IS NOT TRUE
       OR (v_result->>'amount_owed')::numeric IS DISTINCT FROM v_row.amount
       OR (v_result->>'amount_paid')::numeric IS DISTINCT FROM v_row.amount THEN
      RAISE EXCEPTION 'tournament %, fixed place % did not settle in full',
        p_tournament_id, v_row.place USING ERRCODE = 'P0404';
    END IF;

    SELECT count(*), COALESCE(sum(p.amount), 0)
      INTO v_evidence_count, v_evidence
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.user_id = v_row.user_id
       AND p."position" = v_row.place
       AND NOT (COALESCE(p.source, '') = ANY (v_not_pool))
       AND p.source <> 'final_table_deal';
    IF v_evidence_count < 1 OR v_evidence IS DISTINCT FROM v_row.amount THEN
      RAISE EXCEPTION 'tournament %, fixed place % lacks exact full evidence',
        p_tournament_id, v_row.place USING ERRCODE = 'P0404';
    END IF;
  END LOOP;

  v_distributed_cents := 0;
  FOR v_row IN
    SELECT (e->>'place')::integer AS place,
           (e->>'user_id')::uuid AS user_id,
           (e->>'cents')::bigint AS cents
      FROM jsonb_array_elements(v_shares) e
     ORDER BY (e->>'place')::integer
  LOOP
    v_amount := (v_row.cents::numeric / 100)::numeric(15,2);
    IF v_amount <= 0 OR v_amount IS DISTINCT FROM round(v_amount, 2) THEN
      RAISE EXCEPTION 'tournament % derived invalid deal amount % for rank %',
        p_tournament_id, v_amount, v_row.place USING ERRCODE = '22003';
    END IF;

    v_result := public.fn_ca_settle_final_table_deal_share_raw(
      p_tournament_id, v_row.user_id, v_amount);
    IF COALESCE((v_result->>'ok')::boolean, false) IS NOT TRUE
       OR COALESCE((v_result->>'fully_settled')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'tournament % rank % returned an incomplete deal share',
        p_tournament_id, v_row.place USING ERRCODE = 'P0404';
    END IF;

    SELECT * INTO v_ob
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'final_table_deal'
       AND o.place IS NULL
       AND o.user_id = v_row.user_id;
    SELECT count(*), COALESCE(sum(p.amount), 0)
      INTO v_evidence_count, v_evidence
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.user_id = v_row.user_id
       AND p.source = 'final_table_deal'
       AND p."position" IS NULL;
    IF v_ob.id IS NULL
       OR v_ob.amount_owed IS DISTINCT FROM v_amount
       OR v_ob.amount_paid IS DISTINCT FROM v_amount
       OR v_ob.source IS DISTINCT FROM 'final_table_deal'
       OR v_ob.adjustment_id IS NOT NULL
       OR v_ob.settled_at IS NULL
       OR v_evidence_count <> 1
       OR v_evidence IS DISTINCT FROM v_amount
       OR NOT EXISTS (
         SELECT 1
           FROM public.tournament_payouts p
           JOIN public.wallet_credit_idempotency k
             ON k.key = p.idempotency_key
            AND k.user_id = p.user_id
            AND k.amount = p.amount
          WHERE p.tournament_id = p_tournament_id
            AND p.user_id = v_row.user_id
            AND p.source = 'final_table_deal'
            AND p."position" IS NULL
            AND p.amount = v_amount
            AND p.idempotency_key =
              'tourney:' || p_tournament_id::text || ':obl:' || v_ob.id::text || ':0'
       )
       OR (SELECT count(*)
             FROM public.wallet_credit_idempotency k
            WHERE k.key LIKE
              'tourney:' || p_tournament_id::text || ':obl:' || v_ob.id::text || ':%')
          <> 1 THEN
      RAISE EXCEPTION 'tournament % rank % did not write one exact payout row',
        p_tournament_id, v_row.place USING ERRCODE = 'P0404';
    END IF;

    v_distributed_cents := v_distributed_cents + v_row.cents;
    v_payouts := v_payouts || jsonb_build_object(
      'place', v_row.place,
      'user_id', v_row.user_id,
      'amount', v_amount);
    IF v_row.place = 1 THEN v_winner_amount := v_amount; END IF;
  END LOOP;

  IF v_distributed_cents <> v_undistributed_cents
     OR v_prior_paid_cents + v_fixed_shortfall_cents
        + v_bubble_shortfall_cents + v_distributed_cents <> v_pool_cents
     OR (SELECT COALESCE(sum(round(p.amount * 100)::bigint), 0)::bigint
           FROM public.tournament_payouts p
          WHERE p.tournament_id = p_tournament_id
            AND NOT (COALESCE(p.source, '') = ANY (v_not_pool)))
        <> v_pool_cents THEN
    RAISE EXCEPTION 'tournament % deal distributed % of % remaining cents',
      p_tournament_id, v_distributed_cents, v_undistributed_cents
      USING ERRCODE = '23514';
  END IF;

  -- The final standings and presentation cache commit with the money. Existing
  -- eliminated standings were proved above and are never rebuilt from clocks.
  FOR v_row IN
    SELECT (e->>'place')::integer AS place,
           (e->>'user_id')::uuid AS user_id,
           ((e->>'cents')::numeric / 100)::numeric(15,2) AS amount
      FROM jsonb_array_elements(v_shares) e
     ORDER BY (e->>'place')::integer DESC
  LOOP
    UPDATE public.tournament_players
       SET position = v_row.place,
           prize = v_row.amount,
           status = CASE WHEN v_row.place = 1
                         THEN 'winner'
                         ELSE 'eliminated' END,
           eliminated_at = CASE WHEN v_row.place = 1 THEN NULL ELSE v_now END
     WHERE tournament_id = p_tournament_id
       AND user_id = v_row.user_id
       AND status::text = 'playing'
       AND eliminated_at IS NULL;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'tournament % could not stamp one standing for rank %',
        p_tournament_id, v_row.place USING ERRCODE = 'P0404';
    END IF;
  END LOOP;

  -- Prize is presentation cache, never payment evidence. Every eliminated
  -- tail row starts at zero; positive fixed places then receive their full
  -- locked structure entitlement, not merely the amount that happened to be
  -- paid before this transaction.
  UPDATE public.tournament_players tp
     SET prize = 0
   WHERE tp.tournament_id = p_tournament_id
     AND tp.position > v_live_count;
  FOR v_row IN
    SELECT (e->>'place')::integer AS place,
           (e->>'user_id')::uuid AS user_id,
           (e->>'amount')::numeric(15,2) AS amount
      FROM jsonb_array_elements(v_fixed) e
     ORDER BY (e->>'place')::integer
  LOOP
    UPDATE public.tournament_players tp
       SET prize = v_row.amount
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position = v_row.place
       AND tp.user_id = v_row.user_id
       AND tp.status::text = 'eliminated';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'tournament % could not stamp fixed prize place %',
        p_tournament_id, v_row.place USING ERRCODE = 'P0404';
    END IF;
  END LOOP;

  IF v_has_bubble THEN
    UPDATE public.tournament_players tp
       SET prize = v_bubble_amount
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position = v_bubble_place
       AND tp.user_id = v_bubble_user_id
       AND tp.status::text = 'eliminated'
       AND tp.eliminated_at IS NOT NULL
       AND tp.elimination_sequence IS NOT NULL;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'tournament % could not stamp its stone-bubble prize cache',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  END IF;

  UPDATE public.tournaments
     SET status = 'COMPLETING', updated_at = v_now
   WHERE id = p_tournament_id AND upper(status::text) = 'RUNNING';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'tournament % lost its RUNNING deal claim',
      p_tournament_id USING ERRCODE = '40001';
  END IF;
  v_status := 'COMPLETING';

  -- Prove the exact durable state after every write. Any discrepancy aborts
  -- the statement and therefore every share credited above.
  FOR v_row IN
    SELECT (e->>'place')::integer AS place,
           (e->>'user_id')::uuid AS user_id,
           ((e->>'cents')::numeric / 100)::numeric(15,2) AS amount
      FROM jsonb_array_elements(v_shares) e
     ORDER BY (e->>'place')::integer
  LOOP
    SELECT * INTO v_ob
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'final_table_deal'
       AND o.place IS NULL
       AND o.user_id = v_row.user_id;
    SELECT count(*), COALESCE(sum(p.amount), 0)
      INTO v_evidence_count, v_evidence
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.source = 'final_table_deal'
       AND p."position" IS NULL
       AND p.user_id = v_row.user_id;
    IF v_ob.id IS NULL
       OR v_ob.amount_owed IS DISTINCT FROM v_row.amount
       OR v_ob.amount_paid IS DISTINCT FROM v_row.amount
       OR v_ob.source IS DISTINCT FROM 'final_table_deal'
       OR v_ob.settled_at IS NULL
       OR v_evidence_count <> 1
       OR v_evidence IS DISTINCT FROM v_row.amount
       OR NOT EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id
            AND tp.user_id = v_row.user_id
            AND tp.position = v_row.place
            AND tp.prize IS NOT DISTINCT FROM v_row.amount
            AND tp.status::text = CASE WHEN v_row.place = 1 THEN 'winner' ELSE 'eliminated' END
       ) THEN
      RAISE EXCEPTION 'tournament % failed post-deal proof at rank %',
        p_tournament_id, v_row.place USING ERRCODE = 'P0404';
    END IF;
  END LOOP;

  FOR v_row IN
    SELECT (e->>'place')::integer AS place,
           (e->>'user_id')::uuid AS user_id,
           (e->>'amount')::numeric(15,2) AS amount
      FROM jsonb_array_elements(v_fixed) e
     ORDER BY (e->>'place')::integer
  LOOP
    SELECT * INTO v_ob
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'place'
       AND o.place = v_row.place;
    SELECT count(*), COALESCE(sum(p.amount), 0)
      INTO v_evidence_count, v_evidence
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.user_id = v_row.user_id
       AND p."position" = v_row.place
       AND NOT (COALESCE(p.source, '') = ANY (v_not_pool))
       AND p.source <> 'final_table_deal';
    IF v_ob.id IS NULL
       OR v_ob.user_id IS DISTINCT FROM v_row.user_id
       OR v_ob.amount_owed IS DISTINCT FROM v_row.amount
       OR v_ob.amount_paid IS DISTINCT FROM v_row.amount
       OR v_ob.settled_at IS NULL
       OR v_evidence_count < 1
       OR v_evidence IS DISTINCT FROM v_row.amount
       OR NOT EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id
            AND tp.user_id = v_row.user_id
            AND tp.position = v_row.place
            AND tp.prize IS NOT DISTINCT FROM v_row.amount
            AND tp.status::text = 'eliminated'
            AND tp.eliminated_at IS NOT NULL
       ) THEN
      RAISE EXCEPTION 'tournament % failed fixed-place proof at place %',
        p_tournament_id, v_row.place USING ERRCODE = 'P0404';
    END IF;
  END LOOP;

  IF v_has_bubble THEN
    SELECT count(*) INTO v_bubble_obligation_count
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'bubble_protection';
    SELECT * INTO v_ob
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'bubble_protection'
       AND o.place IS NULL
       AND o.user_id = v_bubble_user_id;
    SELECT count(*), COALESCE(sum(p.amount), 0)
      INTO v_evidence_count, v_evidence
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.source = 'bubble_protection';
    SELECT count(*) INTO v_rows
      FROM public.wallet_credit_idempotency k
     WHERE k.key =
       'tourney:' || p_tournament_id::text || ':obl:' || v_ob.id::text || ':0';
    IF v_bubble_obligation_count <> 1
       OR v_ob.id IS NULL
       OR v_ob.amount_owed IS DISTINCT FROM v_bubble_amount
       OR v_ob.amount_paid IS DISTINCT FROM v_bubble_amount
       OR v_ob.source IS DISTINCT FROM v_bubble_obligation_source
       OR v_ob.adjustment_id IS NOT NULL
       OR v_ob.settled_at IS NULL
       OR v_evidence_count <> 1
       OR v_evidence IS DISTINCT FROM v_bubble_amount
       OR v_rows <> 1
       OR (SELECT count(*)
             FROM public.wallet_credit_idempotency k
            WHERE k.key LIKE
              'tourney:' || p_tournament_id::text || ':obl:' || v_ob.id::text || ':%')
          <> 1
       OR NOT EXISTS (
         SELECT 1
           FROM public.tournament_payouts p
           JOIN public.wallet_credit_idempotency k
             ON k.key = p.idempotency_key
            AND k.user_id = p.user_id
            AND k.amount = p.amount
          WHERE p.tournament_id = p_tournament_id
            AND p.source = 'bubble_protection'
            AND p."position" IS NULL
            AND p.user_id = v_bubble_user_id
            AND p.amount = v_bubble_amount
            AND p.idempotency_key =
              'tourney:' || p_tournament_id::text || ':obl:' || v_ob.id::text || ':0'
       )
       OR NOT EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id
            AND tp.user_id = v_bubble_user_id
            AND tp.position = v_bubble_place
            AND tp.prize IS NOT DISTINCT FROM v_bubble_amount
            AND tp.status::text = 'eliminated'
            AND tp.eliminated_at IS NOT NULL
            AND tp.elimination_sequence IS NOT NULL
       ) THEN
      RAISE EXCEPTION 'tournament % failed pool-funded bubble proof',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  END IF;

  IF (SELECT count(*) FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id AND tp.position IS NOT NULL)
       <> v_field_size
     OR EXISTS (
       SELECT 1 FROM generate_series(1, v_field_size) g(place)
        WHERE NOT EXISTS (
          SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id AND tp.position = g.place
        )
     )
     OR EXISTS (
       SELECT 1
         FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.status::text = 'eliminated'
          AND (tp.eliminated_at IS NULL OR tp.elimination_sequence IS NULL
            OR tp.elimination_sequence <= 0)
     )
     OR EXISTS (
       SELECT 1
         FROM (
           SELECT tp.position,
                  (1 + row_number() OVER (
                    ORDER BY tp.elimination_sequence DESC NULLS LAST, tp.id ASC))::integer
                    AS expected_position
             FROM public.tournament_players tp
            WHERE tp.tournament_id = p_tournament_id
              AND tp.status::text = 'eliminated'
         ) ranked
        WHERE ranked.position IS DISTINCT FROM ranked.expected_position
     )
     OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.prize IS DISTINCT FROM COALESCE((
            SELECT sum(p.amount)
              FROM public.tournament_payouts p
             WHERE p.tournament_id = p_tournament_id
               AND p.user_id = tp.user_id
               AND NOT (COALESCE(p.source, '') = ANY (v_not_pool))
          ), 0)
     ) THEN
    RAISE EXCEPTION 'tournament % did not finish with one standing per roster row',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'fully_settled', true,
    'status', v_status,
    'payouts', v_payouts,
    'winner_amount', v_winner_amount,
    'money_path', 'fn_settle_tournament_final_table_deal');
END;
$$;


ALTER FUNCTION public.fn_settle_tournament_final_table_deal(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_settle_tournament_final_table_deal(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settle_tournament_final_table_deal(p_tournament_id uuid) IS 'Service-only atomic exact-cent final-table deal. Locked roster, votes, table layout and payout evidence derive every share; all shares and standings commit together or not at all.';


--
-- Name: fn_settle_tournament_obligation(uuid, text, integer, uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_tournament_obligation(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text, p_description text DEFAULT NULL::text, p_adjustment_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_kind text := lower(btrim(COALESCE(p_kind, '')));
  v_atomic_kinds CONSTANT text[] := ARRAY[
    'place', 'late_reg_adjustment', 'bubble_protection',
    'final_table_deal', 'satellite_remainder', 'seat'
  ];
BEGIN
  /* Preserve the private core's canonical validation responses for malformed
     calls and non-structure classes. Every valid structure class is private to
     its complete atomic transaction, regardless of tournament format. */
  IF p_tournament_id IS NULL OR p_user_id IS NULL
     OR round(COALESCE(p_amount, 0), 2) < 0
     OR v_kind NOT IN ('place','bounty','bounty_residual','mystery_bounty',
                       'refund','seat','satellite_remainder',
                       'bubble_protection','final_table_deal',
                       'late_reg_adjustment')
     OR (v_kind IN ('place', 'late_reg_adjustment') AND p_place IS NULL)
     OR NOT (v_kind = ANY(v_atomic_kinds)) THEN
    RETURN public.fn_settle_tournament_obligation_before_atomic_batch_gate(
      p_tournament_id, p_kind, p_place, p_user_id, p_amount, p_source,
      p_description, p_adjustment_id);
  END IF;

  RETURN jsonb_build_object(
    'ok', false, 'paid', 0, 'already_paid', 0,
    'refused_reason', 'atomic_batch_required', 'obligation_id', NULL,
    'idempotency_key', NULL,
    'detail', 'prize-pool money, including satellite seats and cash remainder, moves only inside its complete atomic batch');
END;
$$;


ALTER FUNCTION public.fn_settle_tournament_obligation(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text, p_description text, p_adjustment_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_settle_tournament_obligation(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text, p_description text, p_adjustment_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settle_tournament_obligation(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text, p_description text, p_adjustment_id uuid) IS 'Strict Stage-B single-obligation payer for non-pool money. Every prize-pool kind, including satellite seats and cash remainder, is refused for every tournament format; only private cores inside complete atomic batch functions may move that money.';


--
-- Name: fn_settle_tournament_obligation_before_atomic_batch_gate(uuid, text, integer, uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_tournament_obligation_before_atomic_batch_gate(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text, p_description text DEFAULT NULL::text, p_adjustment_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_kind        text := lower(btrim(COALESCE(p_kind, '')));
  v_row_kind    text;
  v_place       integer;
  v_amount      numeric := round(COALESCE(p_amount, 0), 2);
  v_t           record;
  v_ob          public.tournament_obligations%ROWTYPE;
  v_seeded_paid numeric := 0;
  v_owed        numeric;
  v_pay         numeric;
  v_key         text;
  v_category    text;
  v_desc        text;
  v_pool_kinds  text[] := ARRAY['place','late_reg_adjustment','bubble_protection','final_table_deal','satellite_remainder','seat'];
  -- Rows paid from the BOUNTY pool (or recorded on the target by a satellite),
  -- never from the prize pool. Everything else counts against the pool.
  v_not_pool    text[] := ARRAY['satellite_seat','bounty','mystery_bounty','bounty_residual','own_bounty','mystery_bounty_residual'];
  v_paid_pool   numeric := 0;
  v_credited    boolean;
  v_alert_ctx   jsonb;
  v_payout_source text;
  v_adj         public.ca_manual_adjustments%ROWTYPE;
  v_src         text := lower(btrim(COALESCE(p_source, '')));
  v_can         jsonb;
  v_short       numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'missing_ids', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;
  IF v_kind NOT IN ('place','bounty','bounty_residual','mystery_bounty','refund','seat',
                    'satellite_remainder','bubble_protection','final_table_deal','late_reg_adjustment') THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'unknown_kind', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;
  IF p_amount IS NULL OR p_amount::text IN ('NaN','Infinity','-Infinity') THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'invalid_amount', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;
  IF p_amount < 0 THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'negative_amount', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;

  -- A late-registration top-up is the SAME obligation as the place it corrects:
  -- it carries the new total and the difference is what moves.
  v_row_kind := CASE WHEN v_kind = 'late_reg_adjustment' THEN 'place' ELSE v_kind END;
  v_place    := CASE WHEN v_row_kind IN ('place') THEN p_place ELSE NULL END;
  IF v_row_kind = 'place' AND v_place IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'place_required', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;

  IF v_row_kind = 'place' AND v_place <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'invalid_place', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;

  -- Kill switch (Lane E): an open freeze on tournament payouts refuses everything.
  IF to_regclass('public.ca_payout_freeze') IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.ca_payout_freeze f
                WHERE f.scope = 'tournament_payouts' AND f.cleared_at IS NULL) THEN
      RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
        'refused_reason', 'payout_frozen', 'obligation_id', NULL, 'idempotency_key', NULL);
    END IF;
  END IF;

  /* CHIP STANDARD PHASE 6.1 (2026-09-05): A SETTLEMENT FROM OUTSIDE THE
     PLATFORM NEEDS AN APPROVED ADJUSTMENT. The engine, the recovery and the
     registered doors settle under their own names (ca_settle_sources). Any
     other caller - a migration, an operator, an agent under CLAUDE.md 10.9 -
     must name a ca_manual_adjustments row that is approved, for this event,
     this player, at least this amount, in chips; the row is marked settled
     when the chips move and the obligation carries its id. p_adjustment_id
     was accepted and ignored until today. */
  IF NOT (v_src LIKE 'engine.%' OR EXISTS (SELECT 1 FROM public.ca_settle_sources s WHERE s.source = v_src)) THEN
    IF p_adjustment_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
        'refused_reason', 'adjustment_required', 'obligation_id', NULL, 'idempotency_key', NULL,
        'detail', format('source %s is not a platform settle source; name an approved ca_manual_adjustments row (fn_ca_adjustment_under_10_9 writes one)', COALESCE(NULLIF(v_src, ''), '<none>')));
    END IF;
    SELECT * INTO v_adj FROM public.ca_manual_adjustments WHERE id = p_adjustment_id FOR UPDATE;
    IF NOT FOUND OR v_adj.status <> 'approved' OR v_adj.asset <> 'chips'
       OR v_adj.tournament_id IS DISTINCT FROM p_tournament_id
       OR v_adj.target_kind <> 'player_wallet' OR v_adj.target_id IS DISTINCT FROM p_user_id
       OR v_adj.amount < v_amount THEN
      RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
        'refused_reason', 'adjustment_mismatch', 'obligation_id', NULL, 'idempotency_key', NULL,
        'detail', 'the adjustment must be approved, in chips, for this tournament, this player wallet, and at least this amount');
    END IF;
  END IF;

  SELECT t.id, t.name, t.club_id, t.prize_pool, t.bounty_pool, t.bounty_pool_paid, t.status
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', 0,
      'refused_reason', 'tournament_not_found', 'obligation_id', NULL, 'idempotency_key', NULL);
  END IF;

  -- Upsert the obligation. amount_owed only ever rises.
  IF v_place IS NOT NULL THEN
    SELECT * INTO v_ob FROM public.tournament_obligations
     WHERE tournament_id = p_tournament_id AND kind = v_row_kind AND place = v_place
     FOR UPDATE;
  ELSE
    SELECT * INTO v_ob FROM public.tournament_obligations
     WHERE tournament_id = p_tournament_id AND kind = v_row_kind AND place IS NULL AND user_id = p_user_id
     FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    -- Legacy seeding: what did the old key shapes already pay for this obligation?
    IF v_place IS NOT NULL THEN
      SELECT COALESCE(sum(tp.amount), 0) INTO v_seeded_paid
        FROM public.tournament_payouts tp
       WHERE tp.tournament_id = p_tournament_id AND tp."position" = v_place
         AND COALESCE(tp.source, '') NOT IN ('satellite_seat');
    ELSIF v_row_kind = 'refund' THEN
      SELECT COALESCE(sum(w.amount), 0) INTO v_seeded_paid
        FROM public.wallet_transactions w
       WHERE w.related_entity_id = p_tournament_id AND w.user_id = p_user_id
         AND w.type = 'credit' AND lower(w.category) IN ('refund','tournament_refund');
    END IF;
    v_seeded_paid := round(v_seeded_paid, 2);
    v_owed := GREATEST(v_amount, v_seeded_paid);

    INSERT INTO public.tournament_obligations
      (tournament_id, kind, place, user_id, amount_owed, amount_paid, source)
    VALUES (p_tournament_id, v_row_kind, v_place, p_user_id, v_owed, v_seeded_paid, p_source)
    RETURNING * INTO v_ob;
  ELSE
  -- The player on record for a place is whoever was first paid for it; a
  -- different user asking for an already-paid place gets a refusal, not chips.
  IF v_place IS NOT NULL AND v_ob.user_id IS NOT NULL AND v_ob.user_id <> p_user_id AND v_ob.amount_paid > 0 THEN
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', v_ob.amount_paid,
      'refused_reason', 'place_paid_to_another_user', 'obligation_id', v_ob.id, 'idempotency_key', NULL);
  END IF;

    IF v_amount > v_ob.amount_owed THEN
      UPDATE public.tournament_obligations
         SET amount_owed = v_amount, updated_at = now(), user_id = COALESCE(user_id, p_user_id)
       WHERE id = v_ob.id
       RETURNING * INTO v_ob;
    END IF;
  END IF;

  v_pay := round(LEAST(v_amount, v_ob.amount_owed) - v_ob.amount_paid, 2);
  IF v_pay <= 0 THEN
    -- A replay of an older, smaller request can still leave the recorded
    -- obligation unpaid. Report the durable total, not the caller's amount.
    RETURN jsonb_build_object('ok', true, 'paid', 0, 'already_paid', v_ob.amount_paid,
      'amount_owed', v_ob.amount_owed, 'amount_paid', v_ob.amount_paid,
      'remaining', GREATEST(0, v_ob.amount_owed - v_ob.amount_paid),
      'fully_settled', v_ob.amount_paid >= v_ob.amount_owed,
      'refused_reason', NULL, 'obligation_id', v_ob.id, 'idempotency_key', NULL);
  END IF;

  -- R2b: one finisher, one place.
  IF v_row_kind = 'place' THEN
    IF EXISTS (SELECT 1 FROM public.tournament_obligations o
                WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
                  AND o.user_id = p_user_id AND o.place <> v_place AND o.amount_paid > 0) THEN
      v_alert_ctx := jsonb_build_object('kind','second_place_prize_refused','tournament_id',p_tournament_id,
        'user_id',p_user_id,'place',v_place,'amount',v_pay,'source',p_source);
      PERFORM public.fn_raise_server_financial_alert('critical','fn_settle_tournament_obligation',
        format('Refused a second structure place: this player already holds a paid place in tournament %s', p_tournament_id),
        v_alert_ctx, 'obl:second_place:' || p_tournament_id::text || ':' || p_user_id::text);
      RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', v_ob.amount_paid,
        'refused_reason', 'player_already_holds_a_place', 'obligation_id', v_ob.id, 'idempotency_key', NULL);
    END IF;
  END IF;

  /* R1 (chip standard Phase 5.1, 2026-09-04): the ESCROW BALANCE decides.
     tournament_escrow holds what the event holds, per bank; a place is paid
     from the prize bank, a bounty from the bounty bank, a refund from all
     three. When the balance knows the event, the counter cap below is not
     consulted; the escrow trigger refuses again inside the credit if a race
     gets past this read. An event the balance has never seen (opened on its
     first row) keeps the old counter cap for this call. */
  v_can := public.fn_ca_escrow_can_pay(p_tournament_id, v_row_kind, v_pay);

  /* A BANK THAT IS SHORT PAYS WHAT IT HOLDS (2026-09-07). This used to refuse
     the whole payment, so a bank 180.00 short of a 13,441.68 obligation paid
     the winner nothing and froze 13,261.68 - three events were sitting like
     that when this was written. Paying what is there takes nothing from
     anybody: amount_owed is untouched, so the remainder stays owed and
     payable, and the credit is still capped by the bank and refused again by
     the escrow trigger if a race gets past this read. */
  IF (v_can->>'known')::boolean AND NOT (v_can->>'ok')::boolean
     AND COALESCE((v_can->>'available')::numeric, 0) >= 0.01 THEN
    v_short := round(v_pay - (v_can->>'available')::numeric, 2);
    v_pay   := round((v_can->>'available')::numeric, 2);
    v_alert_ctx := jsonb_build_object('kind','escrow_short_paid_what_it_holds',
      'tournament_id',p_tournament_id,'tournament',v_t.name,'user_id',p_user_id,
      'obligation_kind',v_kind,'place',v_place,'paid',v_pay,'still_owed',v_short,
      'prize_balance',(v_can->>'prize_balance')::numeric,
      'bounty_balance',(v_can->>'bounty_balance')::numeric,
      'fee_balance',(v_can->>'fee_balance')::numeric,'source',p_source);
    PERFORM public.fn_raise_server_financial_alert('critical','fn_settle_tournament_obligation',
      format('Paid %s of %s to %s for %s and %s is still owed: the escrow bank was short (%s)',
             v_pay, v_pay + v_short, p_user_id, v_kind, v_short, v_t.name),
      v_alert_ctx, 'obl:escrow_short_partial:' || v_ob.id::text);
    v_can := public.fn_ca_escrow_can_pay(p_tournament_id, v_row_kind, v_pay);
  END IF;

  IF (v_can->>'known')::boolean AND NOT (v_can->>'ok')::boolean THEN
    v_alert_ctx := jsonb_build_object('kind','escrow_short','tournament_id',p_tournament_id,'tournament',v_t.name,
      'user_id',p_user_id,'obligation_kind',v_kind,'place',v_place,'requested',v_pay,
      'escrow_available',(v_can->>'available')::numeric,'prize_balance',(v_can->>'prize_balance')::numeric,
      'bounty_balance',(v_can->>'bounty_balance')::numeric,'fee_balance',(v_can->>'fee_balance')::numeric,'source',p_source);
    PERFORM public.fn_raise_server_financial_alert('critical','fn_settle_tournament_obligation',
      format('Refused %s to %s for %s: the escrow holds %s for that bank (%s)',
             v_pay, p_user_id, v_kind, (v_can->>'available')::numeric, v_t.name),
      v_alert_ctx, 'obl:escrow_short:' || v_ob.id::text);
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', v_ob.amount_paid,
      'refused_reason', 'escrow_short', 'obligation_id', v_ob.id, 'idempotency_key', NULL);
  END IF;

  -- R1-lite (counter cap), only for an event the balance has never seen.
  IF v_row_kind = ANY (v_pool_kinds) AND NOT (v_can->>'known')::boolean THEN
    SELECT COALESCE(sum(tp.amount), 0) INTO v_paid_pool
      FROM public.tournament_payouts tp
     WHERE tp.tournament_id = p_tournament_id
       AND NOT (COALESCE(tp.source, '') = ANY (v_not_pool));
    IF v_paid_pool + v_pay > COALESCE(v_t.prize_pool, 0) + 0.05 THEN
      v_alert_ctx := jsonb_build_object('kind','escrow_short','tournament_id',p_tournament_id,'tournament',v_t.name,
        'user_id',p_user_id,'obligation_kind',v_kind,'place',v_place,'requested',v_pay,
        'paid_from_pool_so_far',v_paid_pool,'prize_pool',v_t.prize_pool,'source',p_source);
      PERFORM public.fn_raise_server_financial_alert('critical','fn_settle_tournament_obligation',
        format('Refused %s to %s for %s: the prize pool of %s has already paid %s (%s)',
               v_pay, p_user_id, v_kind, round(COALESCE(v_t.prize_pool,0),2), v_paid_pool, v_t.name),
        v_alert_ctx, 'obl:escrow_short:' || v_ob.id::text);
      RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', v_ob.amount_paid,
        'refused_reason', 'escrow_short', 'obligation_id', v_ob.id, 'idempotency_key', NULL);
    END IF;
  END IF;

  /* THE KEY NAMES THE TOURNAMENT (Lane A3, 2026-09-02). fn_credit_player_wallet_once
     resolves WHICH club wallet to credit from a 'tourney:<id>:...' key
     (tournament_players.club_id for that entry); any other shape falls back to
     fn_player_home_club, which is the club the player joined FIRST, not the
     club they bought in from. Measured in the rolled-back probe: 3 of 4 places
     landed in the wrong club under the old 'obl:<id>:<n>' shape. No 'obl:' key
     was ever spent in production, so the rename costs nothing. */
  v_key := 'tourney:' || p_tournament_id::text || ':obl:' || v_ob.id::text || ':' || (round(v_ob.amount_paid * 100))::bigint::text;
  v_category := CASE
                  WHEN v_row_kind IN ('bounty','bounty_residual','mystery_bounty') THEN 'bounty'
                  WHEN v_row_kind = 'refund' THEN 'refund'
                  ELSE 'prize'
                END;
  /* THE PAYOUT RECORD KEEPS ITS CLASS (2026-09-02). tournament_payouts.source is
     the CLASS of a payment ('structure', 'reconcile', 'late_reg_adjustment',
     'final_table_deal', ...) and every detector downstream filters on it:
     fn_tournament_guarantee_check and fn_tournament_double_paid_obligations
     whitelist it, fn_payout_guarantee_check blacklists the bounty classes. The
     engine calls this function with its own provenance ('engine.finishTournament'
     and friends), which the first build wrote straight into that column - so
     the moment the engine cut over, the guarantee check would have counted
     every engine-paid place as unpaid. Provenance stays on
     tournament_obligations.source; the payout row gets the class. */
  v_payout_source := CASE
    WHEN lower(COALESCE(p_source, '')) IN ('structure','reconcile','hu_shortfall','spin_backpay',
         'overlay_backpay','late_reg_adjustment','final_table_deal','bubble_protection',
         'satellite_remainder','clawback') THEN lower(p_source)
    WHEN v_kind = 'late_reg_adjustment' THEN 'late_reg_adjustment'
    WHEN v_row_kind IN ('final_table_deal','bubble_protection','satellite_remainder') THEN v_row_kind
    ELSE 'structure'
  END;
  v_desc := COALESCE(NULLIF(btrim(p_description), ''),
              CASE
                WHEN v_row_kind = 'place' THEN format('Tournament prize: position %s', v_place)
                WHEN v_row_kind = 'refund' THEN 'Tournament refund'
                ELSE format('Tournament %s', replace(v_row_kind, '_', ' '))
              END);

  PERFORM set_config('app.money_path', 'fn_settle_tournament_obligation', true);

  -- Guard against a key that was already spent while the obligation says otherwise:
  -- that means the obligation row was rebuilt without its payments, and paying
  -- again would be exactly the bug this function exists to end.
  IF EXISTS (SELECT 1 FROM public.wallet_credit_idempotency k WHERE k.key = v_key) THEN
    RAISE EXCEPTION 'fn_settle_tournament_obligation: key % already spent while obligation % shows paid %; refusing',
      v_key, v_ob.id, v_ob.amount_paid;
  END IF;

  v_credited := public.fn_credit_and_log(
    p_user_id, v_pay, v_key, v_category, v_desc, p_tournament_id,
    'PLAYER', NULL, NULL,
    CASE WHEN v_category = 'prize' THEN v_place ELSE NULL END,
    CASE WHEN v_category = 'prize' THEN v_payout_source ELSE NULL END);

  PERFORM set_config('app.money_path', '', true);

  IF NOT v_credited THEN
    -- fn_credit_and_log returns false only when the key was already spent or a
    -- guard inside it refused; either way no chips moved for THIS call.
    RETURN jsonb_build_object('ok', false, 'paid', 0, 'already_paid', v_ob.amount_paid,
      'refused_reason', 'credit_refused', 'obligation_id', v_ob.id, 'idempotency_key', v_key);
  END IF;

  UPDATE public.tournament_obligations
     SET amount_paid = amount_paid + v_pay,
         user_id     = COALESCE(user_id, p_user_id),
         source      = COALESCE(p_source, source),
         adjustment_id = COALESCE(adjustment_id, p_adjustment_id),
         updated_at  = now(),
         settled_at  = CASE WHEN amount_paid + v_pay >= amount_owed THEN now() ELSE settled_at END
   WHERE id = v_ob.id;
  IF v_adj.id IS NOT NULL THEN
    UPDATE public.ca_manual_adjustments SET status = 'settled' WHERE id = v_adj.id;
  END IF;

  -- ok acknowledges this operation; it is not proof that the entire debt
  -- was paid. v_ob holds the pre-credit row, so include this call's v_pay.
  RETURN jsonb_build_object('ok', true, 'paid', v_pay, 'already_paid', v_ob.amount_paid,
    'amount_owed', v_ob.amount_owed, 'amount_paid', v_ob.amount_paid + v_pay,
    'remaining', GREATEST(0, v_ob.amount_owed - v_ob.amount_paid - v_pay),
    'fully_settled', v_ob.amount_paid + v_pay >= v_ob.amount_owed,
    'refused_reason', NULL, 'obligation_id', v_ob.id, 'idempotency_key', v_key);
END;
$$;


ALTER FUNCTION public.fn_settle_tournament_obligation_before_atomic_batch_gate(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text, p_description text, p_adjustment_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_settle_tournament_obligation_before_atomic_batch_gate(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text, p_description text, p_adjustment_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settle_tournament_obligation_before_atomic_batch_gate(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text, p_description text, p_adjustment_id uuid) IS 'The one function that credits a player from a tournament. Upserts tournament_obligations, pays only what is still owed, refuses a second place for the same finisher and any total beyond the prize pool. Chip Accounting Standard R1-lite/R2.';


--
-- Name: fn_settle_tournament_places(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_tournament_places(p_tournament_id uuid, p_observed_winner_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t record;
  v_ladder jsonb;
  v_payouts jsonb := '[]'::jsonb;
  v_status text;
  v_live_count integer;
  v_field_size integer;
  v_eliminated_count integer;
  v_sequenced_count integer;
  v_bubble_place integer;
  v_bubble_user_id uuid;
  v_bubble_amount numeric := 0;
  v_bubble_payout_count integer := 0;
  v_bubble_paid numeric := 0;
  v_bubble_ob_count integer := 0;
  v_bubble_ob public.tournament_obligations%ROWTYPE;
  v_bubble_result jsonb;
  v_winner public.tournament_players%ROWTYPE;
  v_row record;
  v_place integer;
  v_amount numeric;
  v_user_id uuid;
  v_ob public.tournament_obligations%ROWTYPE;
  v_evidence numeric;
  v_evidence_count integer;
  v_total_expected numeric := 0;
  v_winner_amount numeric := 0;
  v_result jsonb;
  v_guarantee_result jsonb;
  v_rows integer;
BEGIN
  -- Every rolling and terminal money authority enters one transaction lane
  -- before it can own an event, obligation, bank, or recipient row.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  IF p_tournament_id IS NULL OR p_observed_winner_id IS NULL THEN
    RAISE EXCEPTION 'place settlement requires tournament and observed winner ids'
      USING ERRCODE = '22004';
  END IF;

  -- Canonical lock order. Re-locks inside owner-only callees are rows already
  -- owned by this transaction and therefore cannot invert a wait dependency.
  SELECT t.id, t.status, t.variant, t.tournament_type, t.is_premium_spin,
         t.satellite_target_id, t.satellite_target, t.prize_pool,
         t.bubble_protection, t.buy_in_amount, t.guaranteed_prize,
         t.prize_pool_finalized
    INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  v_status := upper(COALESCE(v_t.status,''));
  IF v_status NOT IN ('RUNNING','COMPLETING','COMPLETED') THEN
    RAISE EXCEPTION 'tournament % cannot settle from status %',
      p_tournament_id, v_t.status USING ERRCODE = '55000';
  END IF;
  IF lower(COALESCE(v_t.variant,'')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type,'')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL
     OR v_t.satellite_target IS NOT NULL THEN
    RAISE EXCEPTION 'tournament % is a satellite, not an ordinary cash ladder',
      p_tournament_id USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_payouts p
              WHERE p.tournament_id = p_tournament_id
                AND lower(COALESCE(p.source,'')) = 'final_table_deal')
     OR EXISTS (SELECT 1 FROM public.tournament_obligations o
                 WHERE o.tournament_id = p_tournament_id
                   AND o.kind = 'final_table_deal') THEN
    RAISE EXCEPTION
      'tournament % carries final-table-deal evidence; use the deal authority',
      p_tournament_id USING ERRCODE = '55000';
  END IF;

  -- Funding the advertised guarantee is part of this settlement transaction,
  -- not a best-effort request made by the game process immediately beforehand.
  -- fn_apply_prize_guarantee re-locks the row already owned here and either
  -- debits the event-owned bank plus finalizes the pool, or raises. Prove its
  -- receipt against the refreshed row before deriving even the first place; a
  -- refusal therefore rolls back the overlay, every payout and the finish.
  IF v_t.prize_pool IS NULL
     OR v_t.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_t.prize_pool < 0
     OR v_t.prize_pool IS DISTINCT FROM round(v_t.prize_pool, 2) THEN
    RAISE EXCEPTION 'tournament % has invalid whole-cent prize pool %',
      p_tournament_id, v_t.prize_pool USING ERRCODE = '22003';
  END IF;
  IF v_t.guaranteed_prize IS NOT NULL
     AND (v_t.guaranteed_prize::text IN ('NaN','Infinity','-Infinity')
       OR v_t.guaranteed_prize < 0
       OR v_t.guaranteed_prize IS DISTINCT FROM round(v_t.guaranteed_prize, 2)) THEN
    RAISE EXCEPTION 'tournament % has invalid whole-cent guarantee %',
      p_tournament_id, v_t.guaranteed_prize USING ERRCODE = '22003';
  END IF;
  v_guarantee_result := public.fn_apply_prize_guarantee(
    p_tournament_id, 'engine.fn_settle_tournament_places');
  IF COALESCE((v_guarantee_result->>'ok')::boolean, false) IS NOT TRUE
     OR (COALESCE((v_guarantee_result->>'overlay')::numeric,0) > 0
         AND COALESCE(
           (v_guarantee_result->>'overlay_journaled')::boolean,false)
             IS NOT TRUE) THEN
    RAISE EXCEPTION 'tournament % guarantee funding refused: %',
      p_tournament_id, v_guarantee_result USING ERRCODE = 'P0404';
  END IF;

  SELECT t.id, t.status, t.variant, t.tournament_type, t.is_premium_spin,
         t.satellite_target_id, t.satellite_target, t.prize_pool,
         t.bubble_protection, t.buy_in_amount, t.guaranteed_prize,
         t.prize_pool_finalized
    INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF COALESCE(v_t.prize_pool_finalized, false) IS NOT TRUE
     OR v_t.prize_pool IS NULL
     OR v_t.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR v_t.prize_pool IS DISTINCT FROM round(v_t.prize_pool, 2)
     OR v_t.prize_pool < COALESCE(v_t.guaranteed_prize, 0)
     OR v_guarantee_result->>'prize_pool' IS NULL
     OR (v_guarantee_result->>'prize_pool')::numeric IS DISTINCT FROM v_t.prize_pool THEN
    RAISE EXCEPTION
      'tournament % guarantee funding did not produce one finalized locked pool: result %, pool %, guarantee %, finalized %',
      p_tournament_id, v_guarantee_result, v_t.prize_pool,
      v_t.guaranteed_prize, v_t.prize_pool_finalized USING ERRCODE = 'P0404';
  END IF;

  PERFORM 1 FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
   ORDER BY tp.id FOR UPDATE;
  SELECT count(*) INTO v_field_size
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  IF EXISTS (SELECT 1 FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.status::text = 'registered') THEN
    RAISE EXCEPTION 'tournament % still has a registered unresolved player',
      p_tournament_id USING ERRCODE = '55000';
  END IF;

  -- The helper counts the final field, so derive only after the complete
  -- roster has joined the canonical tournament -> roster lock sequence.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'place',a.place,'amount',a.amount) ORDER BY a.place),'[]'::jsonb)
    INTO v_ladder
    FROM public.fn_ca_tournament_place_amounts(p_tournament_id) a;
  IF jsonb_array_length(v_ladder) = 0 THEN
    RAISE EXCEPTION 'tournament % derived an empty ladder', p_tournament_id
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*) INTO v_live_count FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status::text IN ('playing','winner');
  IF v_live_count > 1 THEN
    RAISE EXCEPTION 'tournament % still has % live players',
      p_tournament_id, v_live_count USING ERRCODE = '55000';
  ELSIF v_live_count = 1 THEN
    SELECT tp.* INTO v_winner FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text IN ('playing','winner');
  ELSE
    -- The observed last survivor may already have crossed through
    -- `eliminated` in an all-in race. The committed transition sequence, not
    -- a wall clock, proves that this row was the final elimination.
    SELECT tp.* INTO v_winner FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.user_id = p_observed_winner_id
       AND tp.status::text = 'eliminated'
       AND tp.elimination_sequence IS NOT NULL;
    IF FOUND AND EXISTS (
      SELECT 1 FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id
         AND tp.id <> v_winner.id
         AND tp.elimination_sequence = v_winner.elimination_sequence
    ) THEN
      RAISE EXCEPTION
        'tournament % has an ambiguous final elimination witness',
        p_tournament_id USING ERRCODE = '23505';
    END IF;
    IF FOUND AND EXISTS (
      SELECT 1 FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id
         AND tp.status::text = 'eliminated'
         AND (tp.elimination_sequence IS NULL
              OR tp.elimination_sequence > v_winner.elimination_sequence)
    ) THEN
      v_winner := NULL;
    END IF;
  END IF;
  IF v_winner.id IS NULL OR v_winner.user_id IS DISTINCT FROM p_observed_winner_id THEN
    RAISE EXCEPTION 'observed winner % does not match locked winner % for tournament %',
      p_observed_winner_id, v_winner.user_id, p_tournament_id
      USING ERRCODE = '40001';
  END IF;

  -- Lock the whole set once, before validation or the ascending-place walk.
  PERFORM 1 FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
   ORDER BY o.kind, o.place NULLS LAST, o.id FOR UPDATE;

  IF EXISTS (
    SELECT 1 FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
       AND (o.place IS NULL OR NOT EXISTS (
         SELECT 1 FROM jsonb_array_elements(v_ladder) a
          WHERE (a->>'place')::integer = o.place))
  ) THEN
    RAISE EXCEPTION
      'tournament % has a place obligation outside its derived ladder',
      p_tournament_id USING ERRCODE = '55000';
  END IF;

  IF v_status = 'COMPLETED' THEN
    IF v_winner.status::text <> 'winner' OR v_winner.position <> 1 THEN
      RAISE EXCEPTION
        'COMPLETED tournament % is not an exact replay: winner is not durable',
        p_tournament_id USING ERRCODE = '55000';
    END IF;
  ELSE
    -- Recorded finish positions are the engine's live witness. Never rebuild
    -- an all-busted field from timestamps. Promotion may fill first place, but
    -- it cannot displace another recorded first or vacate a ladder place.
    IF EXISTS (SELECT 1 FROM public.tournament_players tp
                WHERE tp.tournament_id = p_tournament_id
                  AND tp.position = 1
                  AND tp.user_id <> v_winner.user_id) THEN
      RAISE EXCEPTION 'tournament % assigns first place to another player',
        p_tournament_id USING ERRCODE = '23505';
    END IF;
    IF v_winner.position IS NOT NULL AND v_winner.position <> 1
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_ladder) a
                    WHERE (a->>'place')::integer = v_winner.position) THEN
      RAISE EXCEPTION
        'promoting winner % would vacate cash place % in tournament %',
        v_winner.user_id, v_winner.position, p_tournament_id
        USING ERRCODE = '55000';
    END IF;
    UPDATE public.tournament_players
       SET status = 'winner', position = 1,
           eliminated_at = NULL, elimination_sequence = NULL
     WHERE id = v_winner.id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION
        'tournament % could not promote exactly one winner',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;

    -- Final numeric positions are derived from the transition witness, not
    -- from the field size that happened to exist when each player busted.
    -- This is the root fix for late registration enlarging the field after an
    -- early elimination. Existing money evidence is never relabelled: a
    -- legacy event whose paid place would move fails closed for explicit
    -- adjudication instead of rewriting settled history.
    SELECT count(*), count(tp.elimination_sequence),
           count(DISTINCT tp.elimination_sequence)
      INTO v_eliminated_count, v_sequenced_count, v_rows
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text = 'eliminated';
    IF v_eliminated_count <> v_field_size - 1
       OR v_sequenced_count <> v_eliminated_count
       OR v_rows <> v_eliminated_count THEN
      RAISE EXCEPTION
        'tournament % has no complete durable elimination sequence (%/% of %)',
        p_tournament_id, v_sequenced_count, v_rows, v_eliminated_count
        USING ERRCODE = 'P0404';
    END IF;

    IF EXISTS (
      SELECT 1
        FROM (
          SELECT tp.id, tp.position,
                 row_number() OVER (
                   ORDER BY tp.elimination_sequence DESC, tp.id ASC
                 )::integer + 1 AS expected_position
            FROM public.tournament_players tp
           WHERE tp.tournament_id = p_tournament_id
             AND tp.status::text = 'eliminated'
        ) ranked
       WHERE ranked.position IS DISTINCT FROM ranked.expected_position
    ) THEN
      IF EXISTS (
        SELECT 1 FROM public.tournament_payouts p
         WHERE p.tournament_id = p_tournament_id
           AND p."position" IS NOT NULL
      ) OR EXISTS (
        SELECT 1 FROM public.tournament_obligations o
         WHERE o.tournament_id = p_tournament_id
           AND o.kind = 'place'
      ) THEN
        RAISE EXCEPTION
          'tournament % needs a late-entry position normalization but already carries settled place evidence',
          p_tournament_id USING ERRCODE = 'P0404';
      END IF;

      UPDATE public.tournament_players tp
         SET position = NULL
       WHERE tp.tournament_id = p_tournament_id
         AND tp.status::text = 'eliminated';

      WITH ranked AS (
        SELECT tp.id,
               row_number() OVER (
                 ORDER BY tp.elimination_sequence DESC, tp.id ASC
               )::integer + 1 AS expected_position
          FROM public.tournament_players tp
         WHERE tp.tournament_id = p_tournament_id
           AND tp.status::text = 'eliminated'
      )
      UPDATE public.tournament_players tp
         SET position = ranked.expected_position
        FROM ranked
       WHERE tp.id = ranked.id;
    END IF;
  END IF;

  -- Derive the single pool-funded bubble promise after standings are final.
  -- The percentage helper has already reserved this exact amount from its
  -- ladder. Satellites never enter this authority: their bubble is paid the
  -- residual that cannot buy a full seat by the satellite settle path.
  SELECT max((a->>'place')::integer) + 1
    INTO v_bubble_place
    FROM jsonb_array_elements(v_ladder) a;
  IF COALESCE(v_t.bubble_protection, false)
     AND v_bubble_place IS NOT NULL
     AND v_bubble_place <= v_field_size THEN
    IF v_t.buy_in_amount IS NULL
       OR v_t.buy_in_amount::text IN ('NaN','Infinity','-Infinity')
       OR v_t.buy_in_amount <= 0
       OR v_t.buy_in_amount IS DISTINCT FROM round(v_t.buy_in_amount, 2) THEN
      RAISE EXCEPTION 'tournament % has invalid bubble buy-in %',
        p_tournament_id, v_t.buy_in_amount USING ERRCODE = '22003';
    END IF;
    v_bubble_amount := round(v_t.buy_in_amount, 2);
    IF v_bubble_amount > v_t.prize_pool THEN
      RAISE EXCEPTION 'tournament % bubble amount % exceeds pool %',
        p_tournament_id, v_bubble_amount, v_t.prize_pool
        USING ERRCODE = '23514';
    END IF;

    SELECT count(*), min(tp.user_id::text)::uuid
      INTO v_rows, v_bubble_user_id
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position = v_bubble_place
       AND tp.status::text = 'eliminated';
    IF v_rows <> 1 OR v_bubble_user_id IS NULL THEN
      RAISE EXCEPTION 'tournament % has no single eliminated stone bubble at place %',
        p_tournament_id, v_bubble_place USING ERRCODE = 'P0404';
    END IF;
  END IF;

  SELECT count(*), COALESCE(sum(p.amount), 0)
    INTO v_bubble_payout_count, v_bubble_paid
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id
     AND p.source = 'bubble_protection';
  SELECT count(*) INTO v_bubble_ob_count
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND o.kind = 'bubble_protection';

  IF v_bubble_amount = 0 THEN
    IF v_bubble_payout_count <> 0 OR v_bubble_paid <> 0
       OR v_bubble_ob_count <> 0 THEN
      RAISE EXCEPTION 'tournament % carries bubble evidence but no bubble is due',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
  ELSE
    IF v_bubble_paid > v_bubble_amount
       OR EXISTS (
         SELECT 1 FROM public.tournament_payouts p
          WHERE p.tournament_id = p_tournament_id
            AND p.source = 'bubble_protection'
            AND (p.user_id IS DISTINCT FROM v_bubble_user_id
              OR p."position" IS NOT NULL
              OR p.amount IS NULL
              OR p.amount::text IN ('NaN','Infinity','-Infinity')
              OR p.amount <= 0
              OR p.amount IS DISTINCT FROM round(p.amount, 2)
              OR p.idempotency_key IS NULL
              OR NOT EXISTS (
                SELECT 1 FROM public.wallet_credit_idempotency k
                 WHERE k.key = p.idempotency_key
                   AND k.user_id = p.user_id
                   AND k.amount = p.amount))) THEN
      RAISE EXCEPTION 'tournament % has malformed bubble payout evidence',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;

    SELECT * INTO v_bubble_ob
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'bubble_protection'
       AND o.user_id = v_bubble_user_id;
    IF v_bubble_ob_count > 0
       AND (v_bubble_ob_count <> 1 OR v_bubble_ob.id IS NULL
         OR v_bubble_ob.place IS NOT NULL
         OR v_bubble_ob.amount_owed IS DISTINCT FROM v_bubble_amount
         OR v_bubble_ob.amount_paid IS DISTINCT FROM v_bubble_paid
         OR v_bubble_ob.amount_paid < 0
         OR v_bubble_ob.amount_paid > v_bubble_ob.amount_owed
         OR (v_bubble_ob.amount_paid = v_bubble_ob.amount_owed) IS DISTINCT FROM
            (v_bubble_ob.settled_at IS NOT NULL)) THEN
      RAISE EXCEPTION 'tournament % has malformed bubble obligation evidence',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    IF v_bubble_ob_count = 0
       AND (v_bubble_payout_count <> 0 OR v_bubble_paid <> 0) THEN
      RAISE EXCEPTION 'tournament % has bubble money without its debt record',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    IF v_status = 'COMPLETED'
       AND (v_bubble_ob_count <> 1
         OR v_bubble_paid IS DISTINCT FROM v_bubble_amount
         OR v_bubble_ob.amount_paid IS DISTINCT FROM v_bubble_amount
         OR v_bubble_ob.settled_at IS NULL
         OR NOT EXISTS (
           SELECT 1 FROM public.tournament_players tp
            WHERE tp.tournament_id = p_tournament_id
              AND tp.user_id = v_bubble_user_id
              AND tp.position = v_bubble_place
              AND tp.prize IS NOT DISTINCT FROM v_bubble_amount)) THEN
      RAISE EXCEPTION 'COMPLETED tournament % has no exact bubble replay',
        p_tournament_id USING ERRCODE = '55000';
    END IF;
  END IF;

  -- Anything paid from the prize bank outside the derived ladder makes a full
  -- structure payout unsafe. Bounty/seat sources belong to other authorities.
  IF EXISTS (
    SELECT 1 FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND COALESCE(p.source,'') NOT IN
           ('bounty','own_bounty','mystery_bounty','mystery_bounty_residual',
            'bounty_residual','satellite_seat','bubble_protection')
       AND (p."position" IS NULL OR NOT EXISTS (
         SELECT 1 FROM jsonb_array_elements(v_ladder) a
          WHERE (a->>'place')::integer = p."position"))
  ) THEN
    RAISE EXCEPTION 'tournament % has prize evidence outside its derived ladder',
      p_tournament_id USING ERRCODE = '55000';
  END IF;

  -- Obligation-shaped wallet identity with no exact payout row is mixed
  -- evidence. It is checked globally before any place can move.
  IF EXISTS (
    SELECT 1
      FROM public.tournament_obligations o
      JOIN public.wallet_credit_idempotency k
        ON k.key LIKE 'tourney:' || p_tournament_id::text || ':obl:' || o.id::text || ':%'
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_payouts p
          WHERE p.idempotency_key = k.key
            AND p.tournament_id = p_tournament_id
            AND p.user_id = k.user_id AND p.amount = k.amount)
  ) THEN
    RAISE EXCEPTION
      'tournament % has wallet-credit identity without payout evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- Preflight every place before settling the first one.
  FOR v_row IN
    SELECT (a->>'place')::integer AS place,
           (a->>'amount')::numeric AS amount, tp.user_id,
           tp.prize AS cached_prize
      FROM jsonb_array_elements(v_ladder) a
      LEFT JOIN public.tournament_players tp
        ON tp.tournament_id = p_tournament_id
       AND tp.position = (a->>'place')::integer
     ORDER BY (a->>'place')::integer
  LOOP
    v_place := v_row.place; v_amount := v_row.amount; v_user_id := v_row.user_id;
    IF v_user_id IS NULL THEN
      RAISE EXCEPTION 'tournament % has no finisher for cash place %',
        p_tournament_id, v_place USING ERRCODE = '23502';
    END IF;
    IF v_amount::text IN ('NaN','Infinity','-Infinity') OR v_amount < 0
       OR v_amount IS DISTINCT FROM round(v_amount,2) THEN
      RAISE EXCEPTION 'tournament % derived invalid amount % for place %',
        p_tournament_id, v_amount, v_place USING ERRCODE = '22003';
    END IF;
    v_total_expected := v_total_expected + v_amount;
    IF v_place = 1 THEN v_winner_amount := v_amount; END IF;
    IF v_status = 'COMPLETED'
       AND v_row.cached_prize IS DISTINCT FROM v_amount THEN
      RAISE EXCEPTION
        'COMPLETED tournament %, place % has stale prize cache % (expected %)',
        p_tournament_id, v_place, v_row.cached_prize, v_amount
        USING ERRCODE = '55000';
    END IF;

    -- Each payout row is also required to name an exact wallet-credit identity.
    IF EXISTS (
      SELECT 1 FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id AND p."position" = v_place
         AND (p.user_id IS DISTINCT FROM v_user_id OR p.amount IS NULL
           OR p.amount::text IN ('NaN','Infinity','-Infinity') OR p.amount < 0
           OR p.amount IS DISTINCT FROM round(p.amount,2)
           OR p.idempotency_key IS NULL OR NOT EXISTS (
             SELECT 1 FROM public.wallet_credit_idempotency k
              WHERE k.key = p.idempotency_key AND k.user_id = p.user_id
                AND k.amount = p.amount))
    ) THEN
      RAISE EXCEPTION
        'tournament %, place % has mixed/malformed/wrong-recipient evidence',
        p_tournament_id, v_place USING ERRCODE = 'P0404';
    END IF;
    SELECT count(*), COALESCE(sum(p.amount),0)
      INTO v_evidence_count, v_evidence
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id AND p."position" = v_place;
    v_evidence := round(v_evidence,2);
    IF v_evidence > v_amount THEN
      RAISE EXCEPTION 'tournament %, place % records % above entitlement %',
        p_tournament_id, v_place, v_evidence, v_amount USING ERRCODE = '23514';
    END IF;

    v_ob := NULL;
    SELECT * INTO v_ob FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind = 'place' AND o.place = v_place;
    IF FOUND THEN
      IF v_ob.user_id IS DISTINCT FROM v_user_id OR v_ob.amount_owed IS NULL
         OR v_ob.amount_paid IS NULL
         OR v_ob.amount_owed::text IN ('NaN','Infinity','-Infinity')
         OR v_ob.amount_paid::text IN ('NaN','Infinity','-Infinity')
         OR v_ob.amount_owed IS DISTINCT FROM round(v_ob.amount_owed,2)
         OR v_ob.amount_paid IS DISTINCT FROM round(v_ob.amount_paid,2)
         OR v_ob.amount_owed < 0 OR v_ob.amount_paid < 0
         OR v_ob.amount_paid > v_ob.amount_owed
         OR v_ob.amount_owed > v_amount
         OR v_ob.amount_paid IS DISTINCT FROM v_evidence THEN
        RAISE EXCEPTION 'tournament %, place % has incompatible obligation',
          p_tournament_id, v_place USING ERRCODE = 'P0404';
      END IF;
    END IF;

    IF v_amount = 0 THEN
      -- Zero-valued ladder places are standings, not debts.
      IF v_evidence <> 0 OR (v_ob.id IS NOT NULL
         AND (v_ob.amount_owed <> 0 OR v_ob.amount_paid <> 0)) THEN
        RAISE EXCEPTION 'zero-value place % in tournament % carries money evidence',
          v_place, p_tournament_id USING ERRCODE = '23514';
      END IF;
    ELSIF v_status = 'COMPLETED' THEN
      IF v_ob.id IS NULL OR v_ob.amount_owed IS DISTINCT FROM v_amount
         OR v_ob.amount_paid IS DISTINCT FROM v_amount
         OR v_evidence IS DISTINCT FROM v_amount THEN
        RAISE EXCEPTION 'COMPLETED tournament %, place % is not an exact replay',
          p_tournament_id, v_place USING ERRCODE = '55000';
      END IF;
    END IF;
  END LOOP;

  IF round(v_total_expected + v_bubble_amount, 2)
       IS DISTINCT FROM v_t.prize_pool THEN
    RAISE EXCEPTION
      'tournament % ladder % plus bubble % does not equal locked pool %',
      p_tournament_id, v_total_expected, v_bubble_amount, v_t.prize_pool
      USING ERRCODE = '23514';
  END IF;

  IF v_status <> 'COMPLETED' THEN
    -- Materialize the bubble and the entire positive ladder before the first
    -- wallet credit. The payment walk is driven from one complete locked debt
    -- set, so failure on any recipient rolls every obligation and credit back.
    IF v_bubble_amount > 0 AND v_bubble_ob_count = 0 THEN
      INSERT INTO public.tournament_obligations
        (tournament_id,kind,place,user_id,amount_owed,amount_paid,source,settled_at)
      VALUES
        (p_tournament_id,'bubble_protection',NULL,v_bubble_user_id,
         v_bubble_amount,0,'engine.fn_settle_tournament_places',NULL)
      RETURNING * INTO v_bubble_ob;
      v_bubble_ob_count := 1;
    END IF;

    FOR v_row IN
      SELECT (a->>'place')::integer AS place,
             (a->>'amount')::numeric AS amount, tp.user_id
        FROM jsonb_array_elements(v_ladder) a
        JOIN public.tournament_players tp
          ON tp.tournament_id = p_tournament_id
         AND tp.position = (a->>'place')::integer
       WHERE (a->>'amount')::numeric > 0
       ORDER BY (a->>'place')::integer
    LOOP
      SELECT COALESCE(sum(p.amount),0) INTO v_evidence
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p."position" = v_row.place;

      UPDATE public.tournament_obligations o
         SET amount_owed = v_row.amount,
             source = COALESCE(o.source, 'engine.fn_settle_tournament_places'),
             updated_at = now()
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'place' AND o.place = v_row.place;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows = 0 THEN
        INSERT INTO public.tournament_obligations
          (tournament_id,kind,place,user_id,amount_owed,amount_paid,source,settled_at)
        VALUES
          (p_tournament_id,'place',v_row.place,v_row.user_id,v_row.amount,
           v_evidence,'engine.fn_settle_tournament_places',
           CASE WHEN v_evidence = v_row.amount THEN now() ELSE NULL END);
      ELSIF v_rows <> 1 THEN
        RAISE EXCEPTION 'tournament %, place % matched % obligations',
          p_tournament_id, v_row.place, v_rows USING ERRCODE = '23505';
      END IF;
    END LOOP;

    -- Re-lock/prove the complete set immediately before any raw payer runs.
    PERFORM 1 FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id
       AND o.kind IN ('bubble_protection','place')
     ORDER BY o.kind, o.place NULLS LAST, o.id FOR UPDATE;

    IF v_bubble_amount > 0 THEN
      v_bubble_result := public.fn_ca_settle_tournament_bubble_raw(
        p_tournament_id, v_bubble_user_id, v_bubble_amount);
    END IF;

    FOR v_row IN
      SELECT (a->>'place')::integer AS place,
             (a->>'amount')::numeric AS amount, tp.user_id
        FROM jsonb_array_elements(v_ladder) a
        JOIN public.tournament_players tp
          ON tp.tournament_id = p_tournament_id
         AND tp.position = (a->>'place')::integer
       WHERE (a->>'amount')::numeric > 0
       ORDER BY (a->>'place')::integer
    LOOP
      v_result := public.fn_ca_settle_tournament_place_raw(
        p_tournament_id,v_row.place,v_row.user_id,v_row.amount);
      IF COALESCE((v_result->>'fully_settled')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'tournament %, place % returned a partial settlement',
          p_tournament_id, v_row.place USING ERRCODE = 'P0404';
      END IF;
    END LOOP;

    -- tournament_players.prize is presentation cache, stamped only from the
    -- successfully settled DB ladder and in this same transaction.
    UPDATE public.tournament_players SET prize = 0
     WHERE tournament_id = p_tournament_id;
    FOR v_row IN SELECT (a->>'place')::integer AS place,
                         (a->>'amount')::numeric AS amount
                   FROM jsonb_array_elements(v_ladder) a
    LOOP
      UPDATE public.tournament_players SET prize = v_row.amount
       WHERE tournament_id = p_tournament_id AND position = v_row.place;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 THEN
        RAISE EXCEPTION 'could not stamp one prize cache for tournament %, place %',
          p_tournament_id, v_row.place USING ERRCODE = 'P0404';
      END IF;
    END LOOP;

    IF v_bubble_amount > 0 THEN
      UPDATE public.tournament_players
         SET prize = v_bubble_amount
       WHERE tournament_id = p_tournament_id
         AND user_id = v_bubble_user_id
         AND position = v_bubble_place;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 THEN
        RAISE EXCEPTION
          'could not stamp one bubble prize cache for tournament %, place %',
          p_tournament_id, v_bubble_place USING ERRCODE = 'P0404';
      END IF;
    END IF;

    IF v_status = 'RUNNING' THEN
      UPDATE public.tournaments SET status = 'COMPLETING'
       WHERE id = p_tournament_id AND status = 'RUNNING';
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 THEN
        RAISE EXCEPTION 'tournament % lost its RUNNING finish claim',
          p_tournament_id USING ERRCODE = '40001';
      END IF;
      v_status := 'COMPLETING';
    END IF;
  END IF;

  IF v_bubble_amount > 0 AND v_status = 'COMPLETED' THEN
    -- Exact replay only: the completed preflight above proved this call cannot
    -- move money, while the raw helper proves every durable receipt again.
    v_bubble_result := public.fn_ca_settle_tournament_bubble_raw(
      p_tournament_id, v_bubble_user_id, v_bubble_amount);
  END IF;

  IF v_bubble_amount > 0 AND NOT EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.user_id = v_bubble_user_id
       AND tp.position = v_bubble_place
       AND tp.prize IS NOT DISTINCT FROM v_bubble_amount
  ) THEN
    RAISE EXCEPTION
      'post-settlement bubble prize-cache proof failed for tournament %, place %',
      p_tournament_id, v_bubble_place USING ERRCODE = 'P0404';
  END IF;

  -- Prove the durable end-state and build the presentation-only receipt.
  FOR v_row IN
    SELECT (a->>'place')::integer AS place,
           (a->>'amount')::numeric AS amount, tp.user_id,
           tp.prize AS cached_prize
      FROM jsonb_array_elements(v_ladder) a
      JOIN public.tournament_players tp
        ON tp.tournament_id = p_tournament_id
       AND tp.position = (a->>'place')::integer
     ORDER BY (a->>'place')::integer
  LOOP
    IF v_row.cached_prize IS DISTINCT FROM v_row.amount THEN
      RAISE EXCEPTION 'post-settlement prize-cache proof failed for tournament %, place %',
        p_tournament_id, v_row.place USING ERRCODE = 'P0404';
    END IF;
    IF v_row.amount > 0 THEN
      v_ob := NULL;
      SELECT * INTO v_ob FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'place' AND o.place = v_row.place;
      SELECT COALESCE(sum(p.amount),0) INTO v_evidence
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p."position" = v_row.place AND p.user_id = v_row.user_id;
      IF v_ob.id IS NULL OR v_ob.user_id IS DISTINCT FROM v_row.user_id
         OR v_ob.amount_owed IS DISTINCT FROM v_row.amount
         OR v_ob.amount_paid IS DISTINCT FROM v_row.amount
         OR v_evidence IS DISTINCT FROM v_row.amount THEN
        RAISE EXCEPTION 'post-settlement proof failed for tournament %, place %',
          p_tournament_id, v_row.place USING ERRCODE = 'P0404';
      END IF;
    END IF;
    v_payouts := v_payouts || jsonb_build_object(
      'place',v_row.place,'user_id',v_row.user_id,'amount',v_row.amount);
  END LOOP;

  RETURN jsonb_build_object(
    'ok',true,
    'fully_settled',true,
    'status',v_status,
    'payouts',v_payouts,
    'bubble_protection',CASE WHEN v_bubble_amount > 0 THEN
      jsonb_build_object('user_id',v_bubble_user_id,'position',v_bubble_place,
                         'amount',v_bubble_amount)
      ELSE 'null'::jsonb END,
    'winner_amount',v_winner_amount);
END;
$$;


ALTER FUNCTION public.fn_settle_tournament_places(p_tournament_id uuid, p_observed_winner_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_settle_tournament_places(p_tournament_id uuid, p_observed_winner_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settle_tournament_places(p_tournament_id uuid, p_observed_winner_id uuid) IS 'Service-only atomic cash finish: locked DB state derives the pool-funded bubble, winner, recipients and amounts; bubble, all places, winner standing and RUNNING-to-COMPLETING commit together or not at all.';


--
-- Name: fn_settle_tournament_places_atomic(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_tournament_places_atomic(p_tournament_id uuid, p_source text DEFAULT 'engine.atomicPlaceSettlement'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_t                   record;
  v_batch               public.tournament_place_settlement_batches%ROWTYPE;
  v_source              text := COALESCE(NULLIF(btrim(p_source), ''), 'engine.atomicPlaceSettlement');
  v_obligation_count    integer := 0;
  v_open_count          integer := 0;
  v_result_mismatches   integer := 0;
  v_extra_prize_count   integer := 0;
  v_unranked_count      integer := 0;
  v_distinct_positions integer := 0;
  v_player_count        integer := 0;
  v_min_position        integer := 0;
  v_max_position        integer := 0;
  v_winner_count        integer := 0;
  v_winner_place_one    integer := 0;
  v_nonterminal_count   integer := 0;
  v_missing_bust_time   integer := 0;
  v_canonical_mismatches integer := 0;
  v_payout_evidence_mismatches integer := 0;
  v_unexpected_payout_evidence integer := 0;
  v_bubble_user         uuid;
  v_bubble_holders      integer := 0;
  v_bubble_obligations  integer := 0;
  v_bubble_matching     integer := 0;
  v_bubble_owed         numeric := 0;
  v_bubble_paid         numeric := 0;
  v_bubble_evidence     numeric := 0;
  v_bubble_conflicts    integer := 0;
  v_bubble_evidence_exists boolean := false;
  v_bubble_required     boolean := false;
  v_bubble_contract_required boolean := false;
  v_bubble_invalid      boolean := false;
  v_bubble_obligation_id uuid;
  v_bubble_source       text;
  v_bubble_settled_at   timestamptz;
  v_obligation_total    numeric := 0;
  v_required_unpaid     numeric := 0;
  v_bubble_required_unpaid numeric := 0;
  v_total_required_unpaid numeric := 0;
  v_escrow_balance      numeric := 0;
  v_escrow_before       numeric := 0;
  v_escrow_after        numeric := 0;
  v_escrow_enforced     boolean := false;
  v_escrow_found        boolean := false;
  v_paid_this_call      numeric := 0;
  v_actual_fingerprint text;
  v_result              jsonb;
  v_after_paid          numeric;
  v_after_bubble_paid   numeric;
  v_failure             text;
  v_failure_state       text;
  r                     record;
BEGIN
  IF p_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_id_required',
                              'paid', 0, 'retryable', false);
  END IF;

  SELECT t.id, t.name, t.status, round(COALESCE(t.prize_pool, 0), 2) AS prize_pool,
         round(COALESCE(t.guaranteed_prize, 0), 2) AS guaranteed_prize,
         COALESCE(t.prize_pool_finalized, false) AS prize_pool_finalized,
         t.variant, t.tournament_type, t.satellite_target_id,
         COALESCE(t.bubble_protection, false) AS bubble_protection,
         round(COALESCE(t.buy_in_amount, 0), 2) AS buy_in_amount
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found',
                              'paid', 0, 'retryable', false);
  END IF;
  IF lower(COALESCE(v_t.variant, '')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type, '')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'satellite_has_its_own_settlement',
                              'paid', 0, 'retryable', false);
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id AND p.source = 'final_table_deal'
  ) OR EXISTS (
    SELECT 1 FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'final_table_deal'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'final_table_deal_has_its_own_settlement',
                              'paid', 0, 'retryable', false);
  END IF;
  IF NOT v_t.prize_pool_finalized
     OR v_t.prize_pool + 0.005 < v_t.guaranteed_prize THEN
    RETURN jsonb_build_object('ok', false,
                              'reason', 'prize_pool_is_not_funded_and_finalized',
                              'prize_pool', v_t.prize_pool,
                              'guaranteed_prize', v_t.guaranteed_prize,
                              'prize_pool_finalized', v_t.prize_pool_finalized,
                              'paid', 0, 'retryable', false);
  END IF;

  SELECT * INTO v_batch
    FROM public.tournament_place_settlement_batches b
   WHERE b.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'place_plan_not_prepared',
                              'paid', 0, 'retryable', false);
  END IF;

  PERFORM 1
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
   ORDER BY tp.id
   FOR UPDATE;

  SELECT count(*), round(COALESCE(sum(o.amount_owed), 0), 2),
         count(*) FILTER (WHERE o.amount_paid + 0.005 < o.amount_owed),
         round(COALESCE(sum(GREATEST(o.amount_owed - o.amount_paid, 0)), 0), 2),
         md5(COALESCE(jsonb_agg(jsonb_build_object(
           'place', o.place, 'user_id', o.user_id,
           'club_id', tp.club_id,
           'cents', round(o.amount_owed * 100)::bigint)
           ORDER BY o.place), '[]'::jsonb)::text)
    INTO v_obligation_count, v_obligation_total, v_open_count,
         v_required_unpaid, v_actual_fingerprint
    FROM public.tournament_obligations o
    JOIN public.tournament_players tp
      ON tp.tournament_id = o.tournament_id
     AND tp.position = o.place AND tp.user_id = o.user_id
   WHERE o.tournament_id = p_tournament_id AND o.kind = 'place';

  SELECT count(*), count(*) FILTER (WHERE tp.position IS NULL),
         count(DISTINCT tp.position), COALESCE(min(tp.position), 0),
         COALESCE(max(tp.position), 0),
         count(*) FILTER (WHERE tp.status = 'winner'),
         count(*) FILTER (WHERE tp.status = 'winner' AND tp.position = 1),
         count(*) FILTER (WHERE tp.status NOT IN ('winner', 'eliminated')),
         count(*) FILTER (WHERE tp.status = 'eliminated' AND tp.eliminated_at IS NULL)
    INTO v_player_count, v_unranked_count, v_distinct_positions,
         v_min_position, v_max_position, v_winner_count,
         v_winner_place_one, v_nonterminal_count, v_missing_bust_time
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;

  WITH eliminated AS (
    SELECT tp.id,
           v_player_count - (row_number() OVER (
             ORDER BY tp.eliminated_at ASC, tp.id ASC
           ))::integer + 1 AS canonical_position
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id AND tp.status = 'eliminated'
  )
  SELECT count(*) INTO v_canonical_mismatches
    FROM eliminated e
    JOIN public.tournament_players tp ON tp.id = e.id
   WHERE tp.position IS DISTINCT FROM e.canonical_position;

  SELECT count(*) INTO v_result_mismatches
    FROM public.tournament_obligations o
    LEFT JOIN public.tournament_players tp
      ON tp.tournament_id = o.tournament_id AND tp.position = o.place
   WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
     AND (tp.user_id IS NULL
          OR tp.user_id IS DISTINCT FROM o.user_id
          OR round(COALESCE(tp.prize, 0) * 100)::bigint
             <> round(o.amount_owed * 100)::bigint);

  SELECT count(*) INTO v_extra_prize_count
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND round(COALESCE(tp.prize, 0) * 100)::bigint > 0
     AND NOT EXISTS (
       SELECT 1 FROM public.tournament_obligations o
        WHERE o.tournament_id = tp.tournament_id AND o.kind = 'place'
          AND o.place = tp.position AND o.user_id = tp.user_id
     );

  /* An obligation's paid marker is never authoritative by itself. It must
     equal the net, attributable payout ledger evidence for that exact
     tournament, place and player, and it may not exceed the entitlement. */
  SELECT count(*) INTO v_payout_evidence_mismatches
    FROM public.tournament_obligations o
    CROSS JOIN LATERAL (
      SELECT round(COALESCE(sum(p.amount), 0), 2) AS paid
        FROM public.tournament_payouts p
       WHERE p.tournament_id = o.tournament_id
         AND p.position = o.place
         AND p.user_id = o.user_id
         AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                           'late_reg_adjustment', 'clawback', 'spin_backpay',
                           'overlay_backpay')
              OR public.fn_tournament_payout_key_is_place_evidence(
                   p.tournament_id, p.idempotency_key))
    ) evidence
   WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
     AND (o.amount_paid < -0.005
          OR o.amount_paid > o.amount_owed + 0.005
          OR abs(round(o.amount_paid, 2) - evidence.paid) > 0.005);

  /* Every non-zero place payout group must map back to the frozen obligation
     with the same recipient. This catches extra places and wrong recipients. */
  SELECT count(*) INTO v_unexpected_payout_evidence
    FROM (
      SELECT p.position, p.user_id
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                           'late_reg_adjustment', 'clawback', 'spin_backpay',
                           'overlay_backpay')
              OR public.fn_tournament_payout_key_is_place_evidence(
                   p.tournament_id, p.idempotency_key))
       GROUP BY p.position, p.user_id
      HAVING abs(round(sum(p.amount), 2)) > 0.005
    ) evidence
   WHERE NOT EXISTS (
     SELECT 1 FROM public.tournament_obligations o
      WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
        AND o.place = evidence.position AND o.user_id = evidence.user_id
   );

  /* The batch names the only Bubble obligation this transaction may advance.
     Re-prove its current identity, frozen amount, recipient, source and exact
     ledger evidence before any money moves. */
  SELECT EXISTS (
           SELECT 1 FROM public.tournament_obligations o
            WHERE o.tournament_id = p_tournament_id
              AND o.kind = 'bubble_protection'
         ) OR EXISTS (
           SELECT 1
             FROM public.tournament_payouts p
            WHERE p.tournament_id = p_tournament_id
              AND p.source = 'bubble_protection'
            GROUP BY p.tournament_id
           HAVING abs(round(sum(p.amount), 2)) > 0.005
         )
    INTO v_bubble_evidence_exists;
  v_bubble_required := v_t.bubble_protection OR v_bubble_evidence_exists;
  v_bubble_contract_required := v_bubble_required
    AND v_batch.place_count > 0 AND v_player_count > v_batch.place_count;

  IF (v_bubble_evidence_exists OR v_bubble_contract_required)
     AND v_t.buy_in_amount <= 0 THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'bubble_protection_evidence_has_no_valid_contract',
      'paid', 0, 'buy_in_amount', v_t.buy_in_amount,
      'paid_places', v_batch.place_count, 'field_size', v_player_count,
      'retryable', false);
  END IF;
  IF v_bubble_evidence_exists AND NOT v_bubble_contract_required THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'bubble_protection_evidence_has_no_valid_contract',
      'paid', 0, 'buy_in_amount', v_t.buy_in_amount,
      'paid_places', v_batch.place_count, 'field_size', v_player_count,
      'retryable', false);
  END IF;

  IF v_batch.bubble_contract_required IS DISTINCT FROM v_bubble_contract_required THEN
    v_bubble_invalid := true;
  END IF;

  IF v_bubble_contract_required THEN
    SELECT count(*), (array_agg(tp.user_id ORDER BY tp.id))[1]
      INTO v_bubble_holders, v_bubble_user
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.position = v_batch.place_count + 1;

    SELECT count(*),
           count(*) FILTER (WHERE o.user_id = v_bubble_user AND o.place IS NULL),
           COALESCE(max(o.amount_owed) FILTER (
             WHERE o.user_id = v_bubble_user AND o.place IS NULL), 0),
           COALESCE(max(o.amount_paid) FILTER (
             WHERE o.user_id = v_bubble_user AND o.place IS NULL), 0)
      INTO v_bubble_obligations, v_bubble_matching, v_bubble_owed, v_bubble_paid
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'bubble_protection';

    SELECT round(COALESCE(sum(p.amount), 0), 2)
      INTO v_bubble_evidence
      FROM public.tournament_payouts p
     WHERE p.tournament_id = p_tournament_id
       AND p.user_id = v_bubble_user AND p.position IS NULL
       AND p.source = 'bubble_protection';

    SELECT count(*) INTO v_bubble_conflicts
      FROM (
        SELECT p.position, p.user_id
          FROM public.tournament_payouts p
         WHERE p.tournament_id = p_tournament_id
           AND p.source = 'bubble_protection'
           AND (p.position IS NOT NULL OR p.user_id IS DISTINCT FROM v_bubble_user)
         GROUP BY p.position, p.user_id
        HAVING abs(round(sum(p.amount), 2)) > 0.005
      ) unexpected_bubble;

    IF v_bubble_obligations = 1 AND v_bubble_matching = 1 THEN
      SELECT o.id, o.source, o.amount_owed, o.amount_paid, o.settled_at
        INTO v_bubble_obligation_id, v_bubble_source,
             v_bubble_owed, v_bubble_paid, v_bubble_settled_at
        FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id
         AND o.kind = 'bubble_protection'
         AND o.place IS NULL AND o.user_id = v_bubble_user
       FOR UPDATE;
    END IF;

    v_bubble_invalid := v_bubble_invalid
      OR v_bubble_holders <> 1 OR v_bubble_user IS NULL
      OR v_bubble_obligations <> 1 OR v_bubble_matching <> 1
      OR v_bubble_obligation_id IS DISTINCT FROM v_batch.bubble_obligation_id
      OR v_bubble_user IS DISTINCT FROM v_batch.bubble_user_id
      OR v_bubble_source IS DISTINCT FROM v_batch.bubble_source
      OR COALESCE(v_bubble_source, '') NOT IN ('engine.eliminatePlayer', 'engine.atomicPlaceSettlement')
      OR abs(v_bubble_owed - v_t.buy_in_amount) > 0.005
      OR abs(v_bubble_owed - v_batch.bubble_amount_owed) > 0.005
      OR v_bubble_paid < -0.005 OR v_bubble_paid > v_bubble_owed + 0.005
      OR v_bubble_paid + 0.005 < v_batch.bubble_amount_paid_before
      OR (v_t.status <> 'COMPLETED'
          AND abs(v_bubble_paid - v_batch.bubble_amount_paid_before) > 0.005)
      OR abs(v_bubble_paid - v_bubble_evidence) > 0.005
      OR (v_bubble_paid + 0.005 >= v_bubble_owed
          AND v_bubble_settled_at IS NULL)
      OR (v_bubble_paid + 0.005 < v_bubble_owed
          AND v_bubble_settled_at IS NOT NULL)
      OR v_bubble_conflicts > 0;

    v_bubble_required_unpaid := round(GREATEST(v_bubble_owed - v_bubble_paid, 0), 2);
  ELSE
    v_bubble_invalid := v_bubble_invalid
      OR v_batch.bubble_obligation_id IS NOT NULL
      OR v_batch.bubble_user_id IS NOT NULL
      OR v_batch.bubble_source IS NOT NULL
      OR abs(v_batch.bubble_amount_owed) > 0.005
      OR abs(v_batch.bubble_amount_paid_before) > 0.005;
  END IF;

  v_total_required_unpaid := round(v_required_unpaid + v_bubble_required_unpaid, 2);

  IF v_batch.mode <> 'structure'
     OR v_obligation_count <> v_batch.place_count
     OR abs(v_obligation_total - v_batch.amount_owed) > 0.005
     OR abs(v_batch.amount_owed - v_t.prize_pool) > 0.005
     OR v_batch.escrow_available + 0.005 < v_batch.escrow_required
     OR v_actual_fingerprint <> v_batch.plan_fingerprint
     OR v_result_mismatches > 0
     OR v_extra_prize_count > 0
     OR v_payout_evidence_mismatches > 0
     OR v_unexpected_payout_evidence > 0
     OR v_player_count = 0 OR v_unranked_count > 0
     OR v_distinct_positions <> v_player_count
     OR v_min_position <> 1 OR v_max_position <> v_player_count
     OR v_winner_count <> 1 OR v_winner_place_one <> 1
     OR v_nonterminal_count <> 0 OR v_missing_bust_time <> 0
     OR v_canonical_mismatches <> 0
     OR v_bubble_invalid
     OR (v_t.status <> 'COMPLETED'
         AND abs(v_batch.escrow_required - v_total_required_unpaid) > 0.005) THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'prepared_place_plan_failed_validation', 'paid', 0,
      'places', v_obligation_count, 'expected_places', v_batch.place_count,
      'amount_owed', v_obligation_total, 'expected_amount', v_batch.amount_owed,
      'prize_pool', v_t.prize_pool, 'result_mismatches', v_result_mismatches,
      'extra_prize_rows', v_extra_prize_count,
      'payout_evidence_mismatches', v_payout_evidence_mismatches,
      'unexpected_payout_evidence', v_unexpected_payout_evidence,
      'unranked', v_unranked_count, 'min_position', v_min_position,
      'max_position', v_max_position, 'winners', v_winner_count,
      'winner_at_place_one', v_winner_place_one,
      'nonterminal_players', v_nonterminal_count,
      'eliminated_without_time', v_missing_bust_time,
      'canonical_position_mismatches', v_canonical_mismatches,
      'bubble_holders', v_bubble_holders,
      'bubble_obligations', v_bubble_obligations,
      'bubble_evidence_conflicts', v_bubble_conflicts, 'retryable', false);
  END IF;

  IF v_total_required_unpaid > 0.005 THEN
    SELECT e.enforced, round(COALESCE(e.prize_balance, 0), 2)
      INTO v_escrow_enforced, v_escrow_balance
      FROM public.tournament_escrow e
     WHERE e.tournament_id = p_tournament_id
     FOR UPDATE;
    v_escrow_found := FOUND;
    IF NOT v_escrow_found OR NOT v_escrow_enforced
       OR v_escrow_balance + 0.005 < v_total_required_unpaid THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'prize_escrow_is_not_funded', 'paid', 0,
        'required_unpaid', v_total_required_unpaid,
        'place_unpaid', v_required_unpaid,
        'bubble_unpaid', v_bubble_required_unpaid,
        'escrow_available', CASE WHEN v_escrow_found THEN v_escrow_balance ELSE NULL END,
        'escrow_enforced', CASE WHEN v_escrow_found THEN v_escrow_enforced ELSE NULL END,
        'retryable', false);
    END IF;
    v_escrow_before := v_escrow_balance;
  END IF;

  IF v_t.status = 'COMPLETED' THEN
    IF v_batch.settled_at IS NOT NULL AND v_open_count = 0
       AND (NOT v_batch.bubble_contract_required
            OR v_bubble_paid + 0.005 >= v_bubble_owed) THEN
      RETURN jsonb_build_object('ok', true, 'tournament_id', p_tournament_id,
                                'paid', 0, 'places', v_obligation_count,
                                'bubble_obligation_id', v_bubble_obligation_id,
                                'already_completed', true, 'retryable', false);
    END IF;
    RETURN jsonb_build_object('ok', false, 'reason', 'completed_batch_is_not_fully_settled',
                              'paid', 0, 'open_places', v_open_count,
                              'bubble_paid', v_bubble_paid,
                              'retryable', false);
  END IF;
  IF COALESCE(v_t.status, '') <> 'COMPLETING' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_completing',
                              'status', v_t.status, 'paid', 0, 'retryable', false);
  END IF;

  BEGIN
    PERFORM set_config('app.atomic_tournament_place_batch', p_tournament_id::text, true);

    IF v_batch.bubble_contract_required AND v_bubble_required_unpaid > 0.005 THEN
      v_result := public.fn_settle_tournament_obligation_before_atomic_batch_gate(
        p_tournament_id, 'bubble_protection', NULL, v_batch.bubble_user_id,
        v_batch.bubble_amount_owed, v_batch.bubble_source,
        'Bubble protection: buy-in returned to the stone bubble', NULL
      );
      IF NOT COALESCE((v_result->>'ok')::boolean, false)
         OR NULLIF(v_result->>'obligation_id', '')::uuid
            IS DISTINCT FROM v_batch.bubble_obligation_id THEN
        RAISE EXCEPTION USING
          MESSAGE = format('Bubble Protection refused: %s',
                           COALESCE(v_result->>'refused_reason', 'wrong obligation')),
          ERRCODE = 'P0001';
      END IF;

      SELECT o.amount_paid, o.source, o.amount_owed, o.settled_at
        INTO v_after_bubble_paid, v_bubble_source, v_bubble_owed, v_bubble_settled_at
        FROM public.tournament_obligations o
       WHERE o.id = v_batch.bubble_obligation_id
         AND o.tournament_id = p_tournament_id
         AND o.kind = 'bubble_protection'
         AND o.place IS NULL AND o.user_id = v_batch.bubble_user_id;
      IF NOT FOUND
         OR v_bubble_source IS DISTINCT FROM v_batch.bubble_source
         OR abs(v_bubble_owed - v_batch.bubble_amount_owed) > 0.005
         OR v_after_bubble_paid + 0.005 < v_batch.bubble_amount_owed
         OR v_bubble_settled_at IS NULL THEN
        RAISE EXCEPTION USING
          MESSAGE = format('Bubble Protection only reached %s of %s',
                           COALESCE(v_after_bubble_paid, 0),
                           v_batch.bubble_amount_owed),
          ERRCODE = 'P0001';
      END IF;
      v_paid_this_call := v_paid_this_call
        + round(COALESCE((v_result->>'paid')::numeric, 0), 2);
    END IF;

    FOR r IN
      SELECT o.id, o.place, o.user_id, o.amount_owed
        FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
       ORDER BY o.place DESC
       FOR UPDATE
    LOOP
      v_result := public.fn_settle_tournament_obligation_before_atomic_batch_gate(
        p_tournament_id, 'place', r.place, r.user_id, r.amount_owed,
        v_source, 'Tournament prize: position ' || r.place::text, NULL
      );
      IF NOT COALESCE((v_result->>'ok')::boolean, false) THEN
        RAISE EXCEPTION USING
          MESSAGE = format('place %s refused: %s', r.place,
                           COALESCE(v_result->>'refused_reason', 'unknown')),
          ERRCODE = 'P0001';
      END IF;

      SELECT o.amount_paid INTO v_after_paid
        FROM public.tournament_obligations o WHERE o.id = r.id;
      IF v_after_paid + 0.005 < r.amount_owed THEN
        RAISE EXCEPTION USING
          MESSAGE = format('place %s only reached %s of %s', r.place,
                           v_after_paid, r.amount_owed),
          ERRCODE = 'P0001';
      END IF;
      v_paid_this_call := v_paid_this_call
        + round(COALESCE((v_result->>'paid')::numeric, 0), 2);
    END LOOP;

    SELECT count(*) INTO v_open_count
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
       AND o.amount_paid + 0.005 < o.amount_owed;
    IF v_open_count > 0 THEN
      RAISE EXCEPTION USING
        MESSAGE = format('%s place obligation(s) remain open', v_open_count),
        ERRCODE = 'P0001';
    END IF;

    IF v_batch.bubble_contract_required THEN
      SELECT o.amount_paid, o.source, o.amount_owed, o.settled_at
        INTO v_bubble_paid, v_bubble_source, v_bubble_owed, v_bubble_settled_at
        FROM public.tournament_obligations o
       WHERE o.id = v_batch.bubble_obligation_id
         AND o.tournament_id = p_tournament_id
         AND o.kind = 'bubble_protection'
         AND o.place IS NULL AND o.user_id = v_batch.bubble_user_id;
      IF NOT FOUND
         OR v_bubble_source IS DISTINCT FROM v_batch.bubble_source
         OR abs(v_bubble_owed - v_batch.bubble_amount_owed) > 0.005
         OR v_bubble_paid + 0.005 < v_bubble_owed
         OR v_bubble_settled_at IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'Bubble Protection remains open after settlement',
                              ERRCODE = 'P0001';
      END IF;

      SELECT round(COALESCE(sum(p.amount), 0), 2)
        INTO v_bubble_evidence
        FROM public.tournament_payouts p
       WHERE p.tournament_id = p_tournament_id
         AND p.user_id = v_batch.bubble_user_id
         AND p.position IS NULL AND p.source = 'bubble_protection';
      IF abs(v_bubble_paid - v_bubble_evidence) > 0.005 THEN
        RAISE EXCEPTION USING
          MESSAGE = 'Bubble Protection payout evidence does not equal its paid obligation',
          ERRCODE = '23514';
      END IF;
    END IF;

    /* A wallet credit is not a complete transfer unless the same transaction
       also consumes the prize liability. Prove the exact escrow delta rather
       than trusting the child response or merely checking for non-negativity;
       a missing/disabled escrow trigger would otherwise leave reusable phantom
       funds behind after paying every wallet. */
    IF v_total_required_unpaid > 0.005 THEN
      SELECT round(COALESCE(e.prize_balance, 0), 2)
        INTO v_escrow_after
        FROM public.tournament_escrow e
       WHERE e.tournament_id = p_tournament_id AND e.enforced
       FOR UPDATE;
      IF NOT FOUND
         OR round((v_escrow_before - v_escrow_after) * 100)::bigint
            <> round(v_total_required_unpaid * 100)::bigint
         OR round(v_paid_this_call * 100)::bigint
            <> round(v_total_required_unpaid * 100)::bigint THEN
        RAISE EXCEPTION USING
          MESSAGE = format(
            'prize escrow moved %s and child calls reported %s; exact required payout was %s',
            round(v_escrow_before - v_escrow_after, 2), v_paid_this_call,
            v_total_required_unpaid),
          ERRCODE = '23514';
      END IF;
    END IF;

    /* Re-prove the ledger after the final child call. This rejects an RPC
       response that claims success without writing the exact payout evidence,
       or one that writes evidence for a different place or recipient. */
    SELECT count(*) INTO v_payout_evidence_mismatches
      FROM public.tournament_obligations o
      CROSS JOIN LATERAL (
        SELECT round(COALESCE(sum(p.amount), 0), 2) AS paid
          FROM public.tournament_payouts p
         WHERE p.tournament_id = o.tournament_id
           AND p.position = o.place
           AND p.user_id = o.user_id
           AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                             'late_reg_adjustment', 'clawback', 'spin_backpay',
                             'overlay_backpay')
                OR public.fn_tournament_payout_key_is_place_evidence(
                     p.tournament_id, p.idempotency_key))
      ) evidence
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
       AND (o.amount_paid < -0.005
            OR o.amount_paid > o.amount_owed + 0.005
            OR abs(round(o.amount_paid, 2) - evidence.paid) > 0.005);

    SELECT count(*) INTO v_unexpected_payout_evidence
      FROM (
        SELECT p.position, p.user_id
          FROM public.tournament_payouts p
         WHERE p.tournament_id = p_tournament_id
           AND (p.source IN ('structure', 'reconcile', 'hu_shortfall',
                             'late_reg_adjustment', 'clawback', 'spin_backpay',
                             'overlay_backpay')
                OR public.fn_tournament_payout_key_is_place_evidence(
                     p.tournament_id, p.idempotency_key))
         GROUP BY p.position, p.user_id
        HAVING abs(round(sum(p.amount), 2)) > 0.005
      ) evidence
     WHERE NOT EXISTS (
       SELECT 1 FROM public.tournament_obligations o
        WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
          AND o.place = evidence.position AND o.user_id = evidence.user_id
     );
    IF v_payout_evidence_mismatches > 0 OR v_unexpected_payout_evidence > 0 THEN
      RAISE EXCEPTION USING
        MESSAGE = format(
          'post-settlement payout evidence mismatch: obligations %s, unexpected groups %s',
          v_payout_evidence_mismatches, v_unexpected_payout_evidence),
        ERRCODE = '23514';
    END IF;

    /* The trigger gate is needed only while the child RPC advances frozen
       place rows. Clear it before touching the batch header or tournament and
       again after the subtransaction so the caller can never inherit it. */
    PERFORM set_config('app.atomic_tournament_place_batch', '', true);

    UPDATE public.tournament_place_settlement_batches
       SET settled_at = COALESCE(settled_at, now()), source = v_source
     WHERE tournament_id = p_tournament_id
       AND plan_fingerprint = v_actual_fingerprint
       AND bubble_contract_required = v_bubble_contract_required
       AND bubble_obligation_id IS NOT DISTINCT FROM v_bubble_obligation_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING MESSAGE = 'the prepared batch changed before settlement',
                            ERRCODE = '40001';
    END IF;

    UPDATE public.tournaments
       SET status = 'COMPLETED',
           ended_at = COALESCE(ended_at, clock_timestamp()),
           on_break = false,
           break_ends_at = NULL
     WHERE id = p_tournament_id AND status = 'COMPLETING';
    IF NOT FOUND THEN
      RAISE EXCEPTION USING MESSAGE = 'COMPLETING claim was lost before completion',
                            ERRCODE = '40001';
    END IF;

    /* Durable completion includes the physical tables. The tournament status
       transition above releases live seats through its database triggers; the
       close below is kept in this same exception subtransaction so a table
       trigger or constraint failure rolls every prize and COMPLETED back. */
    UPDATE public.tables
       SET status = 'closed', current_players = 0
     WHERE tournament_id = p_tournament_id
       AND (status IS DISTINCT FROM 'closed' OR current_players IS DISTINCT FROM 0);
    IF EXISTS (
         SELECT 1 FROM public.tables
          WHERE tournament_id = p_tournament_id
            AND (status IS DISTINCT FROM 'closed' OR current_players IS DISTINCT FROM 0)
       ) OR EXISTS (
         SELECT 1
           FROM public.table_seats s
           JOIN public.tables tb ON tb.id = s.table_id
          WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL
       ) THEN
      RAISE EXCEPTION USING
        MESSAGE = 'completed tournament retained a nonterminal table or live seat',
        ERRCODE = '23514';
    END IF;

    SELECT count(*) INTO v_result_mismatches
      FROM public.tournament_obligations o
      LEFT JOIN public.tournament_players tp
        ON tp.tournament_id = o.tournament_id AND tp.position = o.place
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
       AND (tp.user_id IS NULL
            OR tp.user_id IS DISTINCT FROM o.user_id
            OR round(COALESCE(tp.prize, 0) * 100)::bigint
               <> round(o.amount_owed * 100)::bigint);

    SELECT count(*) INTO v_extra_prize_count
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND round(COALESCE(tp.prize, 0) * 100)::bigint > 0
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_obligations o
          WHERE o.tournament_id = tp.tournament_id AND o.kind = 'place'
            AND o.place = tp.position AND o.user_id = tp.user_id
       );
    IF v_result_mismatches > 0 OR v_extra_prize_count > 0 THEN
      RAISE EXCEPTION USING MESSAGE = 'completion trigger changed the frozen place plan',
                            ERRCODE = '23514';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_failure = MESSAGE_TEXT,
                            v_failure_state = RETURNED_SQLSTATE;
  END;

  PERFORM set_config('app.atomic_tournament_place_batch', '', true);

  IF v_failure IS NOT NULL THEN
    BEGIN
      PERFORM public.fn_raise_server_financial_alert(
        'critical', 'fn_settle_tournament_places_atomic',
        format('Atomic place settlement aborted for %s: %s',
               COALESCE(v_t.name, p_tournament_id::text), v_failure),
        jsonb_build_object('tournament_id', p_tournament_id,
                           'sqlstate', v_failure_state, 'reason', v_failure,
                           'places', v_obligation_count,
                           'amount_owed', v_obligation_total,
                           'open_obligations', v_open_count,
                           'bubble_obligation_id', v_bubble_obligation_id,
                           'source', v_source),
        'atomic-place-settle:' || p_tournament_id::text
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'atomic_settlement_aborted',
      'detail', v_failure, 'sqlstate', v_failure_state, 'paid', 0,
      'places', v_obligation_count,
      'bubble_obligation_id', v_bubble_obligation_id,
      'retryable', v_failure_state IN ('40001', '40P01', '55P03'));
  END IF;

  RETURN jsonb_build_object('ok', true, 'tournament_id', p_tournament_id,
                            'paid', round(v_paid_this_call, 2),
                            'places', v_obligation_count,
                            'bubble_obligation_id', v_bubble_obligation_id,
                            'completed', true, 'retryable', false,
                            'record', 'tournament_obligations');
END;
$$;


ALTER FUNCTION public.fn_settle_tournament_places_atomic(p_tournament_id uuid, p_source text) OWNER TO postgres;

--
-- Name: FUNCTION fn_settle_tournament_places_atomic(p_tournament_id uuid, p_source text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settle_tournament_places_atomic(p_tournament_id uuid, p_source text) IS 'Pays the fingerprinted tournament place batch plus its exact frozen Bubble Protection obligation and flips COMPLETING to COMPLETED in one transaction. A refused, partial or failed leg rolls every payment back.';


--
-- Name: fn_settle_tournament_rake(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_tournament_rake(p_tournament_id uuid, p_source text DEFAULT 'engine'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t record; v_union uuid; v_net numeric; v_dest text; v_res jsonb;
  v_claimed integer; v_prior record; v_att jsonb; v_att_ok boolean := false;
  v_att_err text; v_users integer; v_members integer; v_done boolean := false;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  SELECT t.id, t.status, t.club_id, t.name, t.current_players
    INTO v_t FROM public.tournaments t WHERE t.id = p_tournament_id FOR NO KEY UPDATE;
  /* NO KEY UPDATE, not UPDATE (20260906): a cash hand's rake_records row
     references this tournament and takes KEY SHARE on it, which FOR UPDATE
     refused and NO KEY UPDATE admits. Settlement is still serialised against
     itself. */
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;
  IF upper(COALESCE(v_t.status, '')) NOT IN ('COMPLETING', 'COMPLETED', 'CANCELLED', 'CANCELED') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_terminal', 'status', v_t.status);
  END IF;

  INSERT INTO public.tournament_rake_settlements (tournament_id, club_id, amount, destination, source)
  VALUES (p_tournament_id, v_t.club_id, 0, 'pending', COALESCE(p_source, 'engine'))
  ON CONFLICT (tournament_id) DO NOTHING;
  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 0 THEN
    SELECT amount, destination, settled_at INTO v_prior
      FROM public.tournament_rake_settlements WHERE tournament_id = p_tournament_id;
    RETURN jsonb_build_object('ok', true, 'already_settled', true,
      'amount', v_prior.amount, 'destination', v_prior.destination,
      'settled_at', v_prior.settled_at);
  END IF;

  SELECT round(COALESCE(sum(r.rake_amount), 0), 2) INTO v_net
    FROM public.rake_records r
   WHERE r.tournament_id = p_tournament_id AND r.is_tournament;

  IF v_net <= 0 OR v_t.club_id IS NULL THEN
    UPDATE public.tournament_rake_settlements
       SET amount = GREATEST(v_net, 0),
           destination = CASE WHEN v_t.club_id IS NULL THEN 'no_club' ELSE 'none' END,
           settled_at = now(),
           attributed_at = now(),
           attributed_users = 0
     WHERE tournament_id = p_tournament_id;
    RETURN jsonb_build_object('ok', true, 'amount', GREATEST(v_net, 0), 'destination', 'none');
  END IF;

  SELECT c.union_id INTO v_union FROM public.clubs c WHERE c.id = v_t.club_id;

  /* ONE LOCK ORDER WITH atomic_distribute_rake (20260906). The cash path
     locks club_wallets FIRST and then union_wallets or clubs. This function
     credited the union wallet (or the club treasury) first and touched
     club_wallets last - the mirror image - and the two met in the middle 249
     times a day. Taking the club_wallets row here, before either credit, puts
     both writers in the same order: club_wallets -> union_wallets | clubs. */
  PERFORM 1 FROM public.club_wallets WHERE club_id = v_t.club_id FOR NO KEY UPDATE;

  -- ZERO-DRIFT phase 2: banked tournament rake = 'rake' vs the tournament.
  PERFORM set_config('app.ledger_category', 'rake', true);
  PERFORM set_config('app.ledger_counterparty', 'prize_liability', true);
  PERFORM set_config('app.ledger_counterparty_entity', p_tournament_id::text, true);

  IF v_union IS NOT NULL THEN
    v_res := public.increment_union_wallet(
      v_union, v_net, v_t.club_id,
      'Tournament rake: ' || COALESCE(v_t.name, 'tournament')
        || ' (' || COALESCE(v_t.current_players, 0) || ' entries)'
        || ' [tournament ' || p_tournament_id || ']');
    IF COALESCE((v_res->>'success')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'fn_settle_tournament_rake: union wallet credit failed for %: %',
        p_tournament_id, v_res;
    END IF;
    v_dest := 'union:' || v_union;
  ELSE
    PERFORM public.credit_club_rake_to_treasury(v_t.club_id, v_net);
    v_dest := 'club_treasury:' || v_t.club_id;
  END IF;

  UPDATE public.club_wallets
     SET period_rake_collected   = COALESCE(period_rake_collected, 0) + v_net,
         lifetime_rake_collected = COALESCE(lifetime_rake_collected, 0) + v_net,
         updated_at = now()
   WHERE club_id = v_t.club_id;

  BEGIN
    v_att := public.fn_attribute_tournament_rake(p_tournament_id);
    v_att_ok := COALESCE((v_att->>'ok')::boolean, false);
    IF NOT v_att_ok THEN
      v_att_err := COALESCE(v_att->>'reason', 'attribution returned ok=false');
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_att_err := SQLERRM;
    v_att := jsonb_build_object('ok', false, 'reason', v_att_err);
    INSERT INTO public.financial_alerts (severity, source, message, context)
    VALUES ('warning', 'fn_settle_tournament_rake',
            'Rake settled but attribution failed: ' || v_att_err,
            jsonb_build_object('tournament_id', p_tournament_id, 'net', v_net));
  END;

  v_users   := COALESCE((v_att->>'attributed_users')::int, 0);
  v_members := COALESCE((v_att->>'members')::int, 0);

  /* ZERO IS NOT SUCCESS. Banked rake that credited nobody, while there were
     players to credit, is a FAILURE: it stays in the repair queue
     (attributed_at IS NULL) instead of being stamped as done. A settlement
     with no members is terminal - retrying it forever would pin the head of
     that queue, which is the failure mode the Heads-Up back-pay hit. */
  v_done := v_att_ok AND (v_users > 0 OR v_members = 0);
  IF v_att_ok AND v_users = 0 AND v_members > 0 THEN
    v_att_err := 'attributed_nobody';
  END IF;

  UPDATE public.tournament_rake_settlements
     SET amount = v_net, union_id = v_union, destination = v_dest, settled_at = now(),
         attributed_at = CASE WHEN v_done THEN now() ELSE NULL END,
         attributed_users = v_users,
         attribution_error = v_att_err
   WHERE tournament_id = p_tournament_id;

  RETURN jsonb_build_object('ok', true, 'amount', v_net, 'destination', v_dest,
                            'attributed', v_done,
                            'attributed_users', v_users, 'members', v_members);
END;
$$;


ALTER FUNCTION public.fn_settle_tournament_rake(p_tournament_id uuid, p_source text) OWNER TO postgres;

--
-- Name: fn_settle_tournament_refund_exact(uuid, uuid, uuid, numeric, numeric, numeric, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_tournament_refund_exact(p_tournament_id uuid, p_user_id uuid, p_source_wallet_club_id uuid, p_total_owed numeric, p_refund_prize numeric, p_refund_bounty numeric, p_refund_fee numeric, p_source text, p_description text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total numeric := round(COALESCE(p_total_owed,0),2);
  v_prize numeric := round(COALESCE(p_refund_prize,0),2);
  v_bounty numeric := round(COALESCE(p_refund_bounty,0),2);
  v_fee numeric := round(COALESCE(p_refund_fee,0),2);
  v_ob public.tournament_obligations%ROWTYPE;
  v_seeded_paid numeric := 0;
  v_pay numeric;
  v_key text;
  v_rows integer;
  v_token uuid;
  v_source_debits numeric;
  v_source_credits numeric;
  v_balance_before numeric;
  v_balance_after numeric;
  v_credit_ledger_id uuid;
  v_wallet_transaction_id uuid;
  v_prev_category text;
  v_prev_counterparty text;
  v_prev_counterparty_entity text;
  v_prev_tournament text;
  v_prev_tournament_id text;
  v_prev_idempotency text;
  v_entitlement record;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL
     OR p_source_wallet_club_id IS NULL
     OR p_total_owed IS NULL OR p_refund_prize IS NULL
     OR p_refund_bounty IS NULL OR p_refund_fee IS NULL
     OR p_total_owed::text IN ('NaN','Infinity','-Infinity')
     OR p_refund_prize::text IN ('NaN','Infinity','-Infinity')
     OR p_refund_bounty::text IN ('NaN','Infinity','-Infinity')
     OR p_refund_fee::text IN ('NaN','Infinity','-Infinity')
     OR p_total_owed IS DISTINCT FROM v_total
     OR p_refund_prize IS DISTINCT FROM v_prize
     OR p_refund_bounty IS DISTINCT FROM v_bounty
     OR p_refund_fee IS DISTINCT FROM v_fee
     OR v_total <= 0 OR v_prize < 0 OR v_bounty < 0 OR v_fee < 0
     OR p_source IS NULL OR length(btrim(p_source)) = 0
     OR p_description IS NULL OR length(btrim(p_description)) = 0 THEN
    RAISE EXCEPTION 'exact refund payer received an invalid contract'
      USING ERRCODE = '22003';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.ca_settle_sources s
     WHERE s.source = lower(btrim(p_source))) THEN
    RAISE EXCEPTION 'exact refund source % is not a platform authority',p_source
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM public.tournaments t
   WHERE t.id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'exact refund tournament % does not exist',p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  PERFORM public.fn_ca_escrow_apply(
    p_tournament_id,'exact refund escrow prelock');

  SELECT * INTO v_ob FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND o.kind = 'refund' AND o.place IS NULL AND o.user_id = p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    SELECT round(COALESCE(sum(w.amount),0),2) INTO v_seeded_paid
      FROM public.wallet_transactions w
     WHERE w.related_entity_id = p_tournament_id
       AND w.user_id = p_user_id AND w.type = 'credit'
       AND lower(w.category) IN ('refund','tournament_refund');
    IF v_seeded_paid > v_total THEN
      RAISE EXCEPTION 'refund ledger already exceeds exact entitlement'
        USING ERRCODE = 'P0404';
    END IF;
    INSERT INTO public.tournament_obligations(
      tournament_id,kind,place,user_id,amount_owed,amount_paid,source)
    VALUES(
      p_tournament_id,'refund',NULL,p_user_id,v_total,v_seeded_paid,p_source)
    RETURNING * INTO v_ob;
  ELSE
    IF v_ob.amount_owed::text IN ('NaN','Infinity','-Infinity')
       OR v_ob.amount_paid::text IN ('NaN','Infinity','-Infinity')
       OR v_ob.amount_owed < 0 OR v_ob.amount_paid < 0
       OR v_ob.amount_paid > v_ob.amount_owed
       OR v_total < v_ob.amount_owed THEN
      RAISE EXCEPTION 'existing refund obligation is incompatible with exact entitlement'
        USING ERRCODE = 'P0404';
    END IF;
  END IF;

  v_pay := round(v_total - v_ob.amount_paid,2);
  IF v_pay <= 0 OR v_pay IS DISTINCT FROM round(v_prize + v_bounty + v_fee,2) THEN
    RAISE EXCEPTION
      'exact refund components %, %, % do not equal newly owed amount %',
      v_prize,v_bounty,v_fee,v_pay USING ERRCODE = '23514';
  END IF;

  -- The caller cannot choose money. Resolve one deterministic, still-open
  -- immutable entitlement whose stored club and rails exactly match this
  -- tranche. A funded satellite seat is deliberately excluded: that source
  -- can be returned only as another tournament-entry ticket, never as chips.
  SELECT e.* INTO v_entitlement
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND e.refund_wallet_club_id = p_source_wallet_club_id
     AND e.gross = v_pay
     AND e.refund_prize = v_prize
     AND e.refund_bounty = v_bounty
     AND e.refund_fee = v_fee
     AND NOT EXISTS (
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=e.id)
     AND e.entitlement_kind='wallet_charge'
   ORDER BY e.entitlement_kind,e.id
   LIMIT 1;
  IF v_entitlement.id IS NULL THEN
    RAISE EXCEPTION
      'refund source club and component rails do not match one immutable entitlement'
      USING ERRCODE = 'P0404';
  END IF;
  SELECT count(*) INTO v_rows FROM public.chip_ledger l
   WHERE l.id=v_entitlement.source_ledger_id
     AND l.tournament_id=v_entitlement.tournament_id
     AND l.club_id=v_entitlement.refund_wallet_club_id
     AND l.from_type='player_wallet'
     AND l.from_entity_id=v_entitlement.user_id
     AND l.to_type='prize_liability'
     AND l.to_entity_id=v_entitlement.tournament_id
     AND lower(l.category)=v_entitlement.charge_category
     AND l.amount=v_entitlement.gross;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'refund entitlement lost its exact wallet-debit source'
      USING ERRCODE = 'P0404';
  END IF;
  v_key := 'tourney:' || p_tournament_id::text
           || ':refund-entitlement:'
           || v_entitlement.id::text;

  v_token := gen_random_uuid();
  INSERT INTO public.tournament_refund_authorizations(
    token,idempotency_key,tournament_id,obligation_id,user_id,
    source_wallet_club_id,entitlement_id,
    amount_paid_before,amount_paid_now,refund_prize,refund_bounty,refund_fee,
    source,description,created_at)
  VALUES(
    v_token,v_key,p_tournament_id,v_ob.id,p_user_id,
    p_source_wallet_club_id,v_entitlement.id,
    v_ob.amount_paid,v_pay,v_prize,v_bounty,v_fee,
    lower(btrim(p_source)),p_description,transaction_timestamp());
  -- The debit journal is the immutable source-wallet fact. A refund may land
  -- only in that same club wallet, and never through the generic tournament
  -- wallet chooser. Existing credits in that wallet reduce its remaining
  -- capacity, so even an owner-only caller cannot redirect or over-credit it.
  SELECT round(COALESCE(sum(l.amount),0),2) INTO v_source_debits
    FROM public.chip_ledger l
   WHERE l.tournament_id = p_tournament_id
     AND l.club_id = p_source_wallet_club_id
     AND l.from_type = 'player_wallet'
     AND l.from_entity_id = p_user_id
     AND l.to_type = 'prize_liability'
     AND l.to_entity_id = p_tournament_id
     AND l.category IN ('tournament_buyin','rebuy','addon');
  SELECT round(COALESCE(sum(l.amount),0),2) INTO v_source_credits
    FROM public.chip_ledger l
   WHERE l.tournament_id = p_tournament_id
     AND l.club_id = p_source_wallet_club_id
     AND l.from_type = 'prize_liability'
     AND l.from_entity_id = p_tournament_id
     AND l.to_type = 'player_wallet'
     AND l.to_entity_id = p_user_id
     AND l.category IN ('refund','tournament_refund');
  IF v_source_debits IS NULL OR v_source_credits IS NULL
     OR v_source_debits::text IN ('NaN','Infinity','-Infinity')
     OR v_source_credits::text IN ('NaN','Infinity','-Infinity')
     OR v_source_debits < 0 OR v_source_credits < 0
     OR round(v_source_debits-v_source_credits,2) < v_pay THEN
    RAISE EXCEPTION
      'source club % has only % of exact tournament debit left for refund %',
      p_source_wallet_club_id,
      round(v_source_debits-v_source_credits,2),v_pay
      USING ERRCODE = 'P0404';
  END IF;

  SELECT m.chip_balance INTO v_balance_before
    FROM public.club_members m
   WHERE m.user_id = p_user_id AND m.club_id = p_source_wallet_club_id
   FOR UPDATE;
  IF NOT FOUND OR v_balance_before IS NULL
     OR v_balance_before::text IN ('NaN','Infinity','-Infinity')
     OR v_balance_before IS DISTINCT FROM round(v_balance_before,2) THEN
    RAISE EXCEPTION
      'exact source wallet % for player % is absent or invalid',
      p_source_wallet_club_id,p_user_id USING ERRCODE = 'P0404';
  END IF;

  INSERT INTO public.wallet_credit_idempotency(key,user_id,amount)
  VALUES(v_key,p_user_id,v_pay)
  ON CONFLICT(key) DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'exact refund credit key % was already claimed',v_key
      USING ERRCODE = '23505';
  END IF;

  v_prev_category := current_setting('app.ledger_category',true);
  v_prev_counterparty := current_setting('app.ledger_counterparty',true);
  v_prev_counterparty_entity := current_setting(
    'app.ledger_counterparty_entity',true);
  v_prev_tournament := current_setting('app.ledger_tournament',true);
  v_prev_tournament_id := current_setting('app.ledger_tournament_id',true);
  v_prev_idempotency := current_setting('app.ledger_idempotency_key',true);
  PERFORM public.fn_ca_declare_ledger(
    'refund','prize_liability',p_tournament_id,NULL,v_key,NULL);
  PERFORM set_config('app.ledger_tournament',p_tournament_id::text,true);
  PERFORM set_config('app.ledger_tournament_id',p_tournament_id::text,true);
  UPDATE public.club_members
     SET chip_balance = chip_balance + v_pay,updated_at = now()
   WHERE user_id = p_user_id AND club_id = p_source_wallet_club_id
     AND chip_balance IS NOT DISTINCT FROM v_balance_before
  RETURNING chip_balance INTO v_balance_after;
  PERFORM set_config('app.ledger_category',COALESCE(v_prev_category,''),true);
  PERFORM set_config('app.ledger_counterparty',COALESCE(v_prev_counterparty,''),true);
  PERFORM set_config('app.ledger_counterparty_entity',
                     COALESCE(v_prev_counterparty_entity,''),true);
  PERFORM set_config('app.ledger_tournament',COALESCE(v_prev_tournament,''),true);
  PERFORM set_config('app.ledger_tournament_id',COALESCE(v_prev_tournament_id,''),true);
  PERFORM set_config('app.ledger_idempotency_key',COALESCE(v_prev_idempotency,''),true);
  IF v_balance_after IS NULL
     OR v_balance_after IS DISTINCT FROM round(v_balance_before+v_pay,2) THEN
    RAISE EXCEPTION 'exact source wallet changed during refund'
      USING ERRCODE = '40001';
  END IF;
  SELECT count(*),min(l.id::text)::uuid INTO v_rows,v_credit_ledger_id
    FROM public.chip_ledger l
   WHERE l.idempotency_key = v_key
     AND l.tournament_id = p_tournament_id
     AND l.club_id = p_source_wallet_club_id
     AND l.from_type = 'prize_liability'
     AND l.from_entity_id = p_tournament_id
     AND l.to_type = 'player_wallet'
     AND l.to_entity_id = p_user_id
     AND l.category = 'refund' AND l.amount = v_pay;
  IF v_rows <> 1 OR v_credit_ledger_id IS NULL THEN
    RAISE EXCEPTION 'exact source-wallet credit % has no single journal row',v_key
      USING ERRCODE = 'P0404';
  END IF;

  PERFORM set_config('app.ca_exact_refund_token',v_token::text,true);
  INSERT INTO public.wallet_transactions(
    user_id,wallet_type,amount,type,category,description,
    related_entity_id,table_id,hand_id,balance_after)
  VALUES(
    p_user_id,'PLAYER',v_pay,'credit','refund',p_description,
    p_tournament_id,NULL,NULL,v_balance_after)
  RETURNING id INTO v_wallet_transaction_id;
  PERFORM set_config('app.ca_exact_refund_token','',true);
  IF EXISTS (
    SELECT 1 FROM public.tournament_refund_authorizations a
     WHERE a.token = v_token) THEN
    RAISE EXCEPTION 'exact refund authorization % was not consumed',v_token
      USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_rows FROM public.tournament_refund_tranches tr
   WHERE tr.wallet_transaction_id = v_wallet_transaction_id
     AND tr.idempotency_key = v_key
     AND tr.tournament_id = p_tournament_id
     AND tr.obligation_id = v_ob.id AND tr.user_id = p_user_id
     AND tr.source_wallet_club_id = p_source_wallet_club_id
     AND tr.entitlement_id = v_entitlement.id
     AND tr.credit_ledger_id = v_credit_ledger_id
     AND tr.amount_paid_before = v_ob.amount_paid
     AND tr.amount_paid_now = v_pay
     AND tr.refund_prize = v_prize
     AND tr.refund_bounty = v_bounty
     AND tr.refund_fee = v_fee
     AND tr.source = lower(btrim(p_source))
     AND tr.description = p_description;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'exact refund credit % has no single component receipt',v_key
      USING ERRCODE = 'P0404';
  END IF;

  UPDATE public.tournament_obligations
     SET amount_paid = amount_paid + v_pay,
         amount_owed = v_total,
         source = p_source,
         updated_at = now(),settled_at = now()
   WHERE id = v_ob.id AND amount_paid = v_ob.amount_paid
  RETURNING * INTO v_ob;
  IF v_ob.id IS NULL OR v_ob.amount_paid IS DISTINCT FROM v_total THEN
    RAISE EXCEPTION 'exact refund obligation did not close at %',v_total
      USING ERRCODE = '40001';
  END IF;
  RETURN jsonb_build_object(
    'ok',true,'fully_settled',true,'remaining',0,
    'obligation_id',v_ob.id,'idempotency_key',v_key,
    'entitlement_id',v_entitlement.id,
    'entitlement_kind',v_entitlement.entitlement_kind,
    'source_wallet_club_id',p_source_wallet_club_id,
    'credit_ledger_id',v_credit_ledger_id,
    'wallet_transaction_id',v_wallet_transaction_id,
    'already_paid',round(v_total-v_pay,2),'paid',v_pay,
    'amount_owed',v_total,'amount_paid',v_total,
    'refund_prize',v_prize,'refund_bounty',v_bounty,'refund_fee',v_fee);
END;
$$;


ALTER FUNCTION public.fn_settle_tournament_refund_exact(p_tournament_id uuid, p_user_id uuid, p_source_wallet_club_id uuid, p_total_owed numeric, p_refund_prize numeric, p_refund_bounty numeric, p_refund_fee numeric, p_source text, p_description text) OWNER TO postgres;

--
-- Name: fn_settlement_conservation_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settlement_conservation_check() RETURNS TABLE(issue text, severity text, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- 1. A settlement's own recorded totals must match the union ledger rows it
  --    claims to have written.
  SELECT 'pnl_collect_mismatch', 'critical',
         'Settlement ' || s.id || ' recorded total_collected ' || s.total_collected
           || ' but the union ledger shows ' || COALESCE(l.credited, 0)
    FROM union_pnl_settlements s
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(amount), 0) AS credited
        FROM union_wallet_transactions t
       WHERE t.union_id = s.union_id AND t.tx_type = 'player_pnl_collect'
         AND t.created_at >= s.period_start
         AND t.created_at <= COALESCE(s.settled_at, now()) + interval '1 minute'
    ) l ON true
   WHERE s.status = 'settled' AND s.total_collected > 0
     AND abs(s.total_collected - COALESCE(l.credited, 0)) > 0.01

  UNION ALL
  SELECT 'pnl_pay_mismatch', 'critical',
         'Settlement ' || s.id || ' recorded total_paid ' || s.total_paid
           || ' but the union ledger shows ' || COALESCE(l.debited, 0)
    FROM union_pnl_settlements s
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(amount), 0) AS debited
        FROM union_wallet_transactions t
       WHERE t.union_id = s.union_id AND t.tx_type = 'player_pnl_pay'
         AND t.created_at >= s.period_start
         AND t.created_at <= COALESCE(s.settled_at, now()) + interval '1 minute'
    ) l ON true
   WHERE s.status = 'settled' AND s.total_paid > 0
     AND abs(s.total_paid - COALESCE(l.debited, 0)) > 0.01

  UNION ALL
  -- 2. THE BUG THIS EXISTS FOR: a union hold taken from a club treasury must
  --    appear as a credit in the union's wallet. For months it did not, and
  --    those chips simply ceased to exist.
  SELECT 'union_hold_not_credited', 'critical',
         'club ' || ct.club_id || ' was debited ' || ct.amount
           || ' as a union hold on ' || ct.created_at::date
           || ' with no matching union wallet credit'
    FROM chip_transactions ct
   WHERE ct.transaction_type = 'union_hold'
     AND ct.created_at > now() - interval '90 days'
     AND NOT EXISTS (
       SELECT 1 FROM union_wallet_transactions t
        WHERE t.tx_type = 'settlement_hold'
          AND t.club_id = ct.club_id
          AND abs(t.amount - ct.amount) < 0.01
          AND t.created_at BETWEEN ct.created_at - interval '5 minutes'
                               AND ct.created_at + interval '5 minutes')

  UNION ALL
  -- 3. A negative pool is always a bug, never a business state.
  SELECT 'negative_balance', 'critical', pool || ' holds a negative balance: ' || amt
    FROM (
      SELECT 'club treasury ' || id::text AS pool, chip_treasury AS amt
        FROM clubs WHERE chip_treasury < 0
      UNION ALL
      SELECT 'union chip wallet ' || union_id::text, chip_balance
        FROM union_wallets WHERE chip_balance < 0
      UNION ALL
      SELECT 'union rake wallet ' || union_id::text, rake_wallet
        FROM union_wallets WHERE rake_wallet < 0
      UNION ALL
      SELECT 'player wallet ' || user_id::text, balance
        FROM wallets WHERE wallet_type = 'PLAYER' AND balance < 0
    ) neg;
$$;


ALTER FUNCTION public.fn_settlement_conservation_check() OWNER TO postgres;

--
-- Name: fn_settlement_health(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settlement_health(p_window_minutes integer DEFAULT 5) RETURNS TABLE(window_minutes integer, settled bigint, failed bigint, stuck bigint, failure_rate numeric, top_failure text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH w AS (
    SELECT state, error_detail
    FROM public.ca_settlements
    WHERE updated_at > now() - make_interval(mins => greatest(p_window_minutes, 1))
  ),
  agg AS (
    SELECT
      count(*) FILTER (WHERE state = 'final')  AS settled,
      count(*) FILTER (WHERE state = 'failed') AS failed,
      count(*) FILTER (WHERE state NOT IN ('final','failed')) AS stuck
    FROM w
  )
  SELECT
    greatest(p_window_minutes, 1),
    agg.settled,
    agg.failed,
    agg.stuck,
    CASE WHEN agg.settled + agg.failed = 0 THEN NULL
         ELSE round(agg.failed::numeric / (agg.settled + agg.failed), 4)
    END,
    (SELECT regexp_replace(
              left(coalesce(w2.error_detail, ''), 120),
              '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}',
              '<uuid>', 'g')
       FROM w w2
      WHERE w2.state = 'failed' AND w2.error_detail IS NOT NULL
      LIMIT 1)
  FROM agg
$$;


ALTER FUNCTION public.fn_settlement_health(p_window_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_settlement_health(p_window_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settlement_health(p_window_minutes integer) IS 'Hand-settlement health over a short window, for the engine''s Prometheus gauges. A WINDOW, not a lifetime total: on 2026-09-04 the lifetime ratio read 7.7% while the live rate was 44%, because three days of healthy history diluted it - and that dilution is part of why 139,153 failed settlements went unnoticed for thirteen hours. failure_rate is NULL, never 0, when nothing settled in the window: no hands is not the same as no failures. See server/src/services/SettlementMetrics.ts.';


--
-- Name: fn_settlement_lock_hygiene(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settlement_lock_hygiene() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  l record;
  v_raised int := 0;
  v_seen   int := 0;
  v_sev    text;
  v_why    text;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_platform_admin())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  FOR l IN
    SELECT s.id, s.lock_type, s.club_id, s.locked_at, s.unlock_at, s.lock_reason,
           round(EXTRACT(epoch FROM (now() - s.locked_at)) / 3600.0, 1) AS age_hours
      FROM settlement_locks s
     WHERE s.is_active
  LOOP
    v_seen := v_seen + 1;
    v_sev := NULL;

    IF l.lock_type = 'GLOBAL_SETTLEMENT_FREEZE' AND l.age_hours > 12 THEN
      v_sev := 'critical';
      v_why := 'A global settlement freeze has been active for ' || l.age_hours
               || ' hours. Every weekly settlement is being refused while it stands.';
    ELSIF l.unlock_at > now() + interval '30 days' THEN
      v_sev := 'critical';
      v_why := 'Lock ' || l.lock_type || ' has unlock_at ' || l.unlock_at::date
               || ', which is more than 30 days out. A lock with no realistic expiry '
               || 'is a lock nobody will remember to lift.';
    ELSIF l.age_hours > 168 THEN
      v_sev := 'warning';
      v_why := 'Lock ' || l.lock_type || ' has been active for ' || l.age_hours || ' hours.';
    END IF;

    IF v_sev IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM financial_alerts a
                        WHERE a.source = 'fn_settlement_lock_hygiene'
                          AND NOT a.resolved
                          AND a.context->>'lock_id' = l.id::text) THEN
      INSERT INTO financial_alerts (source, severity, message, context)
      VALUES ('fn_settlement_lock_hygiene', v_sev,
              v_why || ' Reason given: ' || COALESCE(l.lock_reason, '(none)'),
              jsonb_build_object('lock_id', l.id, 'lock_type', l.lock_type,
                                 'club_id', l.club_id, 'locked_at', l.locked_at,
                                 'unlock_at', l.unlock_at, 'age_hours', l.age_hours));
      v_raised := v_raised + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('active_locks', v_seen, 'alerts_raised', v_raised, 'ran_at', now());
END $$;


ALTER FUNCTION public.fn_settlement_lock_hygiene() OWNER TO postgres;

--
-- Name: FUNCTION fn_settlement_lock_hygiene(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settlement_lock_hygiene() IS 'Ages active settlement locks and raises one alert per lock: a global freeze over 12h, any lock with unlock_at more than 30 days out, or any other lock over 7 days. Idempotent per lock id. Runs hourly from fn_union_integrity_sweep_all.';


--
-- Name: fn_settler_lag_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settler_lag_check() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cursor timestamptz;
  v_saved  timestamptz;
  v_lag_h  numeric;
  v_stale_h numeric;
  v_backlog bigint;
BEGIN
  SELECT high_water_mark, updated_at INTO v_cursor, v_saved
    FROM daemon_state WHERE daemon = 'rakeback_settler';

  IF v_cursor IS NULL THEN
    RETURN jsonb_build_object('healthy', true, 'note', 'no settler cursor yet');
  END IF;

  v_lag_h   := round(EXTRACT(epoch FROM (now() - v_cursor)) / 3600.0, 2);
  v_stale_h := round(EXTRACT(epoch FROM (now() - v_saved))  / 3600.0, 2);
  SELECT COUNT(*) INTO v_backlog FROM rake_records WHERE created_at > v_cursor;

  RETURN jsonb_build_object(
    'healthy', (v_lag_h <= 6 AND NOT (v_stale_h > 1 AND v_backlog > 1000)),
    'cursor', v_cursor,
    'lag_hours', v_lag_h,
    'last_save_hours_ago', v_stale_h,
    'backlog_rows', v_backlog);
END $$;


ALTER FUNCTION public.fn_settler_lag_check() OWNER TO postgres;

--
-- Name: fn_shop_item_availability(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_shop_item_availability(p_club_id uuid, p_user_id uuid, p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item      public.club_shop_items;
  v_owned     integer;
  v_purchased integer;
  v_price     integer;
  v_type      text;
  v_ref       text;
BEGIN
  SELECT * INTO v_item FROM public.club_shop_items
   WHERE id = p_item_id AND club_id = p_club_id;

  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;
  IF NOT COALESCE(v_item.is_active, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'inactive');
  END IF;
  IF v_item.available_from IS NOT NULL AND now() < v_item.available_from THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'not_yet_available', 'available_from', v_item.available_from
    );
  END IF;
  IF v_item.available_until IS NOT NULL AND now() >= v_item.available_until THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_longer_available');
  END IF;
  IF v_item.stock IS NOT NULL AND v_item.stock <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'sold_out');
  END IF;

  v_type := COALESCE(v_item.grant_spec->>'type', 'none');
  IF v_type = 'table_skin' THEN
    v_ref := public.sp_resolve_theme_preset(v_item.grant_spec->>'theme_id');
    IF EXISTS (
      SELECT 1 FROM public.theme_asset_unlocks
       WHERE user_id = p_user_id AND category = 'theme_id' AND asset_id = v_ref
    ) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'already_owned');
    END IF;
  ELSIF v_type = 'avatar' THEN
    v_ref := public.sp_resolve_avatar_shop_sku(v_item.grant_spec->>'avatar_id');
    IF EXISTS (
      SELECT 1 FROM public.avatar_unlocks WHERE user_id = p_user_id AND avatar_id = v_ref
    ) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'already_owned');
    END IF;
  ELSIF v_type = 'emote_pack' THEN
    IF EXISTS (
      SELECT 1 FROM public.feature_purchases
       WHERE user_id = p_user_id AND feature = 'emoji_pack'
         AND (expires_at IS NULL OR expires_at > now())
    ) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'already_owned');
    END IF;
  END IF;

  IF NOT COALESCE(v_item.stackable, false) THEN
    SELECT count(*) INTO v_owned FROM public.club_shop_inventory
     WHERE club_id = p_club_id AND user_id = p_user_id
       AND item_id = p_item_id AND status = 'owned';
    IF v_owned > 0 THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'already_owned');
    END IF;
  END IF;

  IF v_item.per_user_limit IS NOT NULL THEN
    SELECT count(*) INTO v_purchased FROM public.club_shop_purchases
     WHERE club_id = p_club_id AND buyer_id = p_user_id
       AND item_id = p_item_id AND refunded_at IS NULL;
    IF v_purchased >= v_item.per_user_limit THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'limit_reached', 'limit', v_item.per_user_limit
      );
    END IF;
  END IF;

  v_price := COALESCE(v_item.sale_price, v_item.price);
  RETURN jsonb_build_object(
    'ok', true, 'price', v_price, 'list_price', v_item.price,
    'on_sale', v_item.sale_price IS NOT NULL AND v_item.sale_price < v_item.price,
    'stackable', COALESCE(v_item.stackable, false),
    'stock_limited', v_item.stock IS NOT NULL
  );
END;
$$;


ALTER FUNCTION public.fn_shop_item_availability(p_club_id uuid, p_user_id uuid, p_item_id uuid) OWNER TO postgres;

--
-- Name: fn_short_formats_never_break(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_short_formats_never_break() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF upper(COALESCE(NEW.tournament_type, '')) IN ('SPIN', 'SNG')
     OR lower(COALESCE(NEW.variant, '')) IN ('spin', 'sng')
  THEN
    NEW.synchronized_breaks := false;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_short_formats_never_break() OWNER TO postgres;

--
-- Name: fn_skip_noop_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_skip_noop_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW IS NOT DISTINCT FROM OLD THEN
    UPDATE public.ca_noop_update_stats
       SET suppressed = suppressed + 1
     WHERE tbl = TG_TABLE_NAME;
    RETURN NULL;  -- cancelled: no row version, no WAL, no realtime event
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_skip_noop_update() OWNER TO postgres;

--
-- Name: FUNCTION fn_skip_noop_update(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_skip_noop_update() IS 'DO NOT ATTACH THIS TO table_seats. It was attached there without a migration on 2026-09-03 21:30:32 and the first hand-settlement failure followed 0.65 seconds later; 139,153 hands - 25% to 44% of every hand dealt - failed to settle over the next thirteen hours. Cancelling a no-op UPDATE makes the caller see zero rows affected, and fn_ca_settle_hand_stacks_absolute treats a seat write that did not land as a failure and refuses the whole hand. It saved ~26k redundant row versions an hour and cost a third of all settlements. Detached 2026-09-04.';


--
-- Name: fn_snapshot_chip_supply(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_snapshot_chip_supply() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prev public.chip_supply_snapshots%ROWTYPE; v_new public.chip_supply_snapshots%ROWTYPE;
  v_w numeric; v_l numeric; v_wc integer; v_cash numeric; v_tourney numeric; v_sc integer;
  v_c numeric; v_d numeric; v_cbc jsonb; v_dbc jsonb; v_club numeric;
  v_comparable boolean; v_incremental boolean; v_hold_now numeric; v_hold_prev numeric;
  v_since timestamptz; v_now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO v_prev FROM public.chip_supply_snapshots ORDER BY taken_at DESC LIMIT 1;
  SELECT COALESCE(sum(balance),0), COALESCE(sum(COALESCE(locked_balance,0)),0), count(*) INTO v_w, v_l, v_wc FROM public.wallets;
  -- UNION LAW: per-club player chips are real holdings and must be counted.
  SELECT COALESCE(sum(COALESCE(chip_balance,0)), 0) INTO v_club FROM public.club_members;
  -- Cash seats and tournament seats are different currencies. Keep them apart.
  SELECT COALESCE(sum(ts.stack) FILTER (WHERE t.tournament_id IS NULL), 0), COALESCE(sum(ts.stack) FILTER (WHERE t.tournament_id IS NOT NULL), 0), count(*)
    INTO v_cash, v_tourney, v_sc FROM public.table_seats ts JOIN public.tables t ON t.id = ts.table_id WHERE ts.left_at IS NULL;
  -- INCREMENTAL LEDGER TOTALS: previous snapshot totals + rows since it.
  v_incremental := v_prev.id IS NOT NULL AND v_prev.tx_credits IS NOT NULL AND v_prev.tx_debits IS NOT NULL
                   AND v_prev.credits_by_category IS NOT NULL AND v_prev.debits_by_category IS NOT NULL;
  IF v_incremental THEN
    v_since := v_prev.taken_at;
    WITH agg AS (SELECT type, category, sum(amount) AS total FROM public.wallet_transactions WHERE created_at > v_since AND created_at <= v_now GROUP BY type, category),
    merged_c AS (SELECT key, sum(val) AS total FROM (SELECT key, value::numeric AS val FROM jsonb_each_text(v_prev.credits_by_category) UNION ALL SELECT category, total FROM agg WHERE type='credit') s GROUP BY key),
    merged_d AS (SELECT key, sum(val) AS total FROM (SELECT key, value::numeric AS val FROM jsonb_each_text(v_prev.debits_by_category)  UNION ALL SELECT category, total FROM agg WHERE type='debit')  s GROUP BY key)
    SELECT v_prev.tx_credits + COALESCE((SELECT sum(total) FROM agg WHERE type='credit'),0),
           v_prev.tx_debits  + COALESCE((SELECT sum(total) FROM agg WHERE type='debit'),0),
           COALESCE((SELECT jsonb_object_agg(key, round(total,2)) FROM merged_c),'{}'::jsonb),
           COALESCE((SELECT jsonb_object_agg(key, round(total,2)) FROM merged_d),'{}'::jsonb)
    INTO v_c, v_d, v_cbc, v_dbc;
  ELSE
    WITH agg AS (SELECT type, category, sum(amount) AS total FROM public.wallet_transactions WHERE created_at <= v_now GROUP BY type, category)
    SELECT COALESCE(sum(total) FILTER (WHERE type='credit'),0), COALESCE(sum(total) FILTER (WHERE type='debit'),0),
           COALESCE(jsonb_object_agg(category, round(total,2)) FILTER (WHERE type='credit'),'{}'::jsonb),
           COALESCE(jsonb_object_agg(category, round(total,2)) FILTER (WHERE type='debit'),'{}'::jsonb)
    INTO v_c, v_d, v_cbc, v_dbc FROM agg;
  END IF;
  -- Only difference against a row measured the SAME way.
  v_comparable := v_prev.id IS NOT NULL AND v_prev.tournament_stacks IS NOT NULL AND v_prev.club_wallets_total IS NOT NULL;
  v_hold_now := v_w + v_club + v_cash;
  v_hold_prev := CASE WHEN v_comparable THEN v_prev.wallets_total + v_prev.club_wallets_total + v_prev.table_stacks END;
  INSERT INTO public.chip_supply_snapshots (taken_at, wallets_total, wallets_locked, club_wallets_total, table_stacks, tournament_stacks, tx_credits, tx_debits, wallet_count, seat_count, credits_by_category, debits_by_category, delta_holdings, delta_tx_net, unexplained_delta)
  VALUES (v_now, v_w, v_l, v_club, v_cash, v_tourney, v_c, v_d, v_wc, v_sc, v_cbc, v_dbc,
    CASE WHEN NOT v_comparable THEN NULL ELSE v_hold_now - v_hold_prev END,
    CASE WHEN NOT v_comparable THEN NULL ELSE (v_c - v_d) - (v_prev.tx_credits - v_prev.tx_debits) END,
    CASE WHEN NOT v_comparable THEN NULL ELSE (v_hold_now - v_hold_prev) - ((v_c - v_d) - (v_prev.tx_credits - v_prev.tx_debits)) END)
  RETURNING * INTO v_new;
  RETURN jsonb_build_object('ok', true, 'snapshot_id', v_new.id, 'taken_at', v_new.taken_at, 'holdings', v_hold_now, 'wallets_total', v_w, 'club_wallets_total', v_club, 'cash_table_stacks', v_cash, 'tournament_stacks', v_tourney, 'tx_net', v_c - v_d, 'delta_holdings', v_new.delta_holdings, 'delta_tx_net', v_new.delta_tx_net, 'unexplained_delta', v_new.unexplained_delta, 'is_baseline', NOT v_comparable, 'incremental', v_incremental);
END; $$;


ALTER FUNCTION public.fn_snapshot_chip_supply() OWNER TO postgres;

--
-- Name: FUNCTION fn_snapshot_chip_supply(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_snapshot_chip_supply() IS 'AUDIT M4: records one chip-supply snapshot and its delta against the previous one. service_role ONLY - a client-side caller is RLS-scoped to its own wallet and would produce a per-user number, which is exactly what the browser-side reconciliation was doing for five months. Never grant to authenticated.';


--
-- Name: fn_snapshot_daily_challenge_contract(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_snapshot_daily_challenge_contract() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_replacement_tier text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT c.name, c.description, c.challenge_type, c.tier, c.requirement,
           c.threshold, c.chip_reward, c.diamond_reward
      INTO NEW.challenge_name_snapshot, NEW.challenge_description_snapshot,
           NEW.challenge_type_snapshot, NEW.tier_snapshot, NEW.requirement_snapshot,
           NEW.threshold_snapshot, NEW.chip_reward_snapshot, NEW.diamond_reward_snapshot
      FROM public.daily_challenge_catalog c
     WHERE c.id = NEW.challenge_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Unknown challenge % - cannot snapshot its contract', NEW.challenge_id;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.challenge_id IS DISTINCT FROM OLD.challenge_id THEN
    IF current_setting('app.daily_challenge_reroll', true) IS DISTINCT FROM '1' THEN
      RAISE EXCEPTION 'Assigned daily challenges can only be replaced by the reroll contract';
    END IF;
    IF OLD.completed OR OLD.claimed THEN
      RAISE EXCEPTION 'Completed daily challenge contracts cannot be replaced';
    END IF;
    IF NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.assigned_date IS DISTINCT FROM OLD.assigned_date
       OR NEW.id IS DISTINCT FROM OLD.id
    THEN
      RAISE EXCEPTION 'A reroll cannot move a daily challenge contract';
    END IF;

    SELECT c.name, c.description, c.challenge_type, c.tier, c.requirement,
           c.threshold, c.chip_reward, c.diamond_reward
      INTO NEW.challenge_name_snapshot, NEW.challenge_description_snapshot,
           NEW.challenge_type_snapshot, v_replacement_tier, NEW.requirement_snapshot,
           NEW.threshold_snapshot, NEW.chip_reward_snapshot, NEW.diamond_reward_snapshot
      FROM public.daily_challenge_catalog c
     WHERE c.id = NEW.challenge_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unknown replacement challenge %', NEW.challenge_id; END IF;
    IF v_replacement_tier IS DISTINCT FROM OLD.tier_snapshot THEN
      RAISE EXCEPTION 'A reroll cannot change mission cycle';
    END IF;
    NEW.tier_snapshot := v_replacement_tier;
    RETURN NEW;
  END IF;

  IF NEW.challenge_name_snapshot IS DISTINCT FROM OLD.challenge_name_snapshot
     OR NEW.challenge_description_snapshot IS DISTINCT FROM OLD.challenge_description_snapshot
     OR NEW.challenge_type_snapshot IS DISTINCT FROM OLD.challenge_type_snapshot
     OR NEW.tier_snapshot IS DISTINCT FROM OLD.tier_snapshot
     OR NEW.requirement_snapshot IS DISTINCT FROM OLD.requirement_snapshot
     OR NEW.threshold_snapshot IS DISTINCT FROM OLD.threshold_snapshot
     OR NEW.chip_reward_snapshot IS DISTINCT FROM OLD.chip_reward_snapshot
     OR NEW.diamond_reward_snapshot IS DISTINCT FROM OLD.diamond_reward_snapshot
  THEN
    RAISE EXCEPTION 'Assigned daily challenge contracts are immutable';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_snapshot_daily_challenge_contract() OWNER TO postgres;

--
-- Name: fn_snapshot_health(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_snapshot_health(p_days integer DEFAULT 35) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'today', CURRENT_DATE,
    'today_captured', EXISTS (SELECT 1 FROM player_stats_snapshots WHERE snapshot_date = CURRENT_DATE),
    'latest_snapshot', (SELECT max(snapshot_date) FROM player_stats_snapshots),
    'missing_days', COALESCE(
      (SELECT jsonb_agg(missing_date ORDER BY missing_date)
         FROM fn_leaderboard_snapshot_gaps(p_days)), '[]'::jsonb),
    'missing_count', (SELECT count(*) FROM fn_leaderboard_snapshot_gaps(p_days))
  );
$$;


