--
-- Name: fn_snapshot_index_usage(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_snapshot_index_usage() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_n integer;
BEGIN
  INSERT INTO public.index_usage_snapshots
    (taken_at, postmaster_start, schemaname, relname, indexrelname, idx_scan, index_bytes)
  SELECT now(), pg_postmaster_start_time(), s.schemaname, s.relname, s.indexrelname,
         s.idx_scan, pg_relation_size(s.indexrelid)
    FROM pg_stat_user_indexes s
    JOIN pg_index i ON i.indexrelid = s.indexrelid
   WHERE s.schemaname = 'public'
     AND NOT i.indisunique      -- a unique index is a constraint, not a lookup aid
     AND NOT i.indisprimary
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


ALTER FUNCTION public.fn_snapshot_index_usage() OWNER TO postgres;

--
-- Name: fn_snapshot_player_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_snapshot_player_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  INSERT INTO player_stats_snapshots
    (user_id, club_id, snapshot_date, hands_played, hands_dealt, sum_big_blind,
     total_winnings, total_losses, total_rake, tournaments_played, tournaments_won)
  SELECT user_id, club_id, CURRENT_DATE,
         COALESCE(hands_played,0), COALESCE(hands_dealt,0), COALESCE(sum_big_blind,0),
         COALESCE(total_winnings,0), COALESCE(total_losses,0),
         COALESCE(total_rake,0), COALESCE(tournaments_played,0), COALESCE(tournaments_won,0)
  FROM player_stats WHERE club_id IS NOT NULL
  ON CONFLICT (user_id, club_id, snapshot_date) DO UPDATE SET
    hands_played=EXCLUDED.hands_played, hands_dealt=EXCLUDED.hands_dealt,
    sum_big_blind=EXCLUDED.sum_big_blind,
    total_winnings=EXCLUDED.total_winnings,
    total_losses=EXCLUDED.total_losses, total_rake=EXCLUDED.total_rake,
    tournaments_played=EXCLUDED.tournaments_played, tournaments_won=EXCLUDED.tournaments_won;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'rows', v_count, 'date', CURRENT_DATE);
END; $$;


ALTER FUNCTION public.fn_snapshot_player_stats() OWNER TO postgres;

--
-- Name: fn_snapshot_player_stats_if_missing(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_snapshot_player_stats_if_missing() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_exists boolean; v_res jsonb;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM player_stats_snapshots WHERE snapshot_date = CURRENT_DATE
  ) INTO v_exists;

  IF v_exists THEN
    RETURN jsonb_build_object(
      'healed', false, 'reason', 'snapshot_already_present', 'date', CURRENT_DATE);
  END IF;

  v_res := fn_snapshot_player_stats();
  RETURN jsonb_build_object(
    'healed', true, 'date', CURRENT_DATE, 'capture', v_res);
END; $$;


ALTER FUNCTION public.fn_snapshot_player_stats_if_missing() OWNER TO postgres;

