--
-- Name: fn_social_posts_video_contract_defaults(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_social_posts_video_contract_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_first_url text;
  v_yt_id text;
  v_provenance_yt_id text;
  v_prior_yt_id text;
  v_inferred_topic text;
  v_caller_role text := COALESCE(auth.role()::text, '');
  v_user_storage_video boolean := false;
BEGIN
  IF NEW.content_type IS DISTINCT FROM 'video' THEN
    RETURN NEW;
  END IF;

  v_first_url := NULLIF(NEW.media_urls ->> 0, '');
  v_yt_id := public.fn_extract_youtube_video_id(v_first_url);
  IF TG_OP = 'UPDATE' THEN
    v_prior_yt_id := COALESCE(
      public.fn_extract_youtube_video_id(NULLIF(OLD.media_urls ->> 0, '')),
      public.fn_extract_youtube_video_id(OLD.original_media_url),
      CASE
        WHEN OLD.youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'
          THEN OLD.youtube_video_id
        ELSE NULL
      END
    );
  END IF;
  v_inferred_topic := public.fn_infer_video_topic(NEW.metadata, NEW.topics);

  IF v_inferred_topic <> 'unknown' THEN
    NEW.topic := v_inferred_topic;
  END IF;

  IF NEW.origin_type = 'user_upload' AND EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = NEW.author_id
      AND COALESCE(p.is_horse, false)
  ) THEN
    NEW.origin_type := 'horse';
  END IF;

  IF v_yt_id IS NOT NULL THEN
    PERFORM public.fn_queue_youtube_verification(
      v_yt_id,
      'social_post_write'
    );
    NEW.youtube_video_id := v_yt_id;
    NEW.canonical_asset_key := 'youtube:' || v_yt_id;
    NEW.playback_type := 'youtube_embed';
    IF COALESCE(auth.role()::text, '') <> 'service_role'
       OR NEW.rights_status NOT IN ('owned', 'licensed')
    THEN
      NEW.rights_status := 'embed_only';
    END IF;
  ELSIF public.fn_is_platform_public_storage_url(v_first_url)
  THEN
    NEW.playback_type := 'native';
    v_provenance_yt_id := COALESCE(
      public.fn_extract_youtube_video_id(NEW.original_media_url),
      CASE
        WHEN NEW.youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'
          THEN NEW.youtube_video_id
        ELSE NULL
      END,
      v_prior_yt_id
    );
    -- A service worker may not publish a downloaded YouTube rendition by
    -- directly rewriting the post. The completion RPC first retires the exact
    -- claim, then exposes that completed job id as transaction-local proof for
    -- both the Reel and post updates.
    IF v_provenance_yt_id IS NOT NULL
       AND (
         TG_OP = 'INSERT'
         OR OLD.playback_type IS DISTINCT FROM 'native'
         OR NULLIF(OLD.media_urls ->> 0, '') IS DISTINCT FROM v_first_url
       )
       AND (
         v_caller_role <> 'service_role'
         OR NEW.rights_status NOT IN ('owned', 'licensed')
         OR NOT EXISTS (
           SELECT 1
           FROM public.video_transcode_jobs completion_job
           JOIN public.social_reels completion_reel
             ON completion_reel.id = completion_job.reel_id
           WHERE completion_job.id = current_setting(
                   'app.youtube_native_completion_job_id', true
                 )
             AND completion_job.status = 'completed'
             AND completion_job.reel_id = completion_reel.id
             AND completion_reel.source_post_id = NEW.id
             AND completion_job.user_id IS NOT DISTINCT FROM NEW.author_id
             AND completion_job.rights_status IS NOT DISTINCT FROM NEW.rights_status
             AND completion_job.canonical_asset_key = 'youtube:' || v_provenance_yt_id
             AND completion_job.output_url IS NOT DISTINCT FROM
               split_part(split_part(v_first_url, '?', 1), '#', 1)
         )
       )
    THEN
      RAISE EXCEPTION USING
        ERRCODE = '42501',
        MESSAGE = 'YouTube-derived native posts may only be published by complete_rights_cleared_youtube_transcode';
    END IF;
    -- A rights-cleared worker replaces only the playable URL. Retain the
    -- source identity so the native and embed representations deduplicate.
    IF v_caller_role = 'service_role'
       AND NEW.rights_status IN ('owned', 'licensed')
       AND v_provenance_yt_id IS NOT NULL
    THEN
      NEW.youtube_video_id := v_provenance_yt_id;
      NEW.canonical_asset_key := 'youtube:' || v_provenance_yt_id;
    ELSE
      NEW.youtube_video_id := NULL;
      NEW.canonical_asset_key := 'native:' || md5(v_first_url);
    END IF;
    v_user_storage_video := public.fn_is_user_video_storage_url(
      v_first_url,
      NEW.author_id
    );
    IF v_caller_role = 'authenticated'
       AND auth.uid() = NEW.author_id
       AND v_user_storage_video
    THEN
      NEW.rights_status := 'user_authorized';
    ELSIF v_caller_role = 'service_role'
       AND NEW.rights_status = 'user_authorized'
       AND v_user_storage_video
    THEN
      NEW.rights_status := 'user_authorized';
    ELSIF v_caller_role <> 'service_role'
       OR NEW.rights_status NOT IN ('owned', 'licensed')
    THEN
      NEW.rights_status := 'unknown';
    END IF;
  ELSIF NEW.playback_type = 'youtube_embed'
     OR NEW.youtube_video_id IS NOT NULL
  THEN
    v_provenance_yt_id := public.fn_extract_youtube_video_id(
      NEW.original_media_url
    );
    IF v_provenance_yt_id IS NOT NULL THEN
      NEW.media_urls := CASE
        WHEN jsonb_typeof(NEW.media_urls) = 'array'
          AND jsonb_array_length(NEW.media_urls) > 0
        THEN jsonb_set(
          NEW.media_urls,
          '{0}',
          to_jsonb(NEW.original_media_url),
          false
        )
        ELSE jsonb_build_array(NEW.original_media_url)
      END;
      NEW.youtube_video_id := v_provenance_yt_id;
      NEW.canonical_asset_key := 'youtube:' || v_provenance_yt_id;
      NEW.playback_type := 'youtube_embed';
      IF v_caller_role <> 'service_role'
         OR NEW.rights_status NOT IN ('owned', 'licensed')
      THEN
        NEW.rights_status := 'embed_only';
      END IF;
    ELSE
      NEW.youtube_video_id := NULL;
      NEW.canonical_asset_key := CASE
        WHEN v_first_url IS NOT NULL THEN 'external:' || md5(v_first_url)
        ELSE NULL
      END;
      NEW.playback_type := 'external_embed';
      NEW.rights_status := 'unknown';
    END IF;
  ELSE
    -- Caller-supplied playback/rights labels never turn an arbitrary URL into
    -- native media. Only the exact project Storage branch above can do that.
    NEW.youtube_video_id := NULL;
    NEW.canonical_asset_key := CASE
      WHEN v_first_url IS NOT NULL THEN 'external:' || md5(v_first_url)
      ELSE NULL
    END;
    NEW.playback_type := 'external_embed';
    NEW.rights_status := 'unknown';
  END IF;

  RETURN NEW;
END
$_$;


ALTER FUNCTION public.fn_social_posts_video_contract_defaults() OWNER TO postgres;

--
-- Name: fn_social_posts_video_to_reel_mirror(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_social_posts_video_to_reel_mirror() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_first_url text;
  v_yt_id text;
  v_playback_type text;
  v_rights_status text;
  v_source_type text;
  v_origin_type text;
BEGIN
  IF NEW.content_type IS DISTINCT FROM 'video'
     OR NEW.media_urls IS NULL
     OR jsonb_typeof(NEW.media_urls) <> 'array'
     OR jsonb_array_length(NEW.media_urls) = 0
  THEN
    RETURN NEW;
  END IF;

  v_first_url := NULLIF(NEW.media_urls ->> 0, '');
  IF v_first_url IS NULL THEN
    RETURN NEW;
  END IF;

  v_yt_id := public.fn_extract_youtube_video_id(v_first_url);
  v_playback_type := CASE
    WHEN v_yt_id IS NOT NULL THEN 'youtube_embed'
    ELSE NEW.playback_type
  END;
  v_rights_status := CASE
    WHEN v_yt_id IS NOT NULL
         AND NEW.rights_status NOT IN ('owned', 'licensed') THEN 'embed_only'
    ELSE NEW.rights_status
  END;
  v_source_type := CASE
    WHEN NEW.origin_type = 'video_library' THEN 'video_library'
    WHEN v_playback_type = 'native' THEN 'native'
    WHEN v_yt_id IS NOT NULL THEN 'youtube'
    ELSE 'user'
  END;
  v_origin_type := CASE
    WHEN NEW.origin_type = 'user_upload' THEN 'social_post'
    ELSE NEW.origin_type
  END;

  IF EXISTS (
    SELECT 1 FROM public.social_reels r WHERE r.source_post_id = NEW.id
  ) THEN
    RETURN NEW;
  END IF;

  IF NEW.publication_key IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.social_reels r
    WHERE r.origin_type = 'video_library'
      AND r.publication_key = NEW.publication_key
  ) THEN
    RETURN NEW;
  END IF;

  IF NEW.canonical_asset_key IS NOT NULL AND NEW.origin_type = 'video_library'
     AND EXISTS (
       SELECT 1
       FROM public.social_reels r
       WHERE r.origin_type = 'video_library'
         AND r.canonical_asset_key = NEW.canonical_asset_key
     )
  THEN
    RETURN NEW;
  END IF;

  IF NEW.origin_type <> 'video_library' AND EXISTS (
    SELECT 1
    FROM public.social_reels r
    WHERE r.author_id = NEW.author_id
      AND r.video_url = v_first_url
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.social_reels (
    author_id,
    video_url,
    thumbnail_url,
    caption,
    source_post_id,
    is_public,
    source_type,
    youtube_video_id,
    original_youtube_url,
    media_status,
    origin_type,
    playback_type,
    topic,
    rights_status,
    source_asset_id,
    canonical_asset_key,
    publication_key,
    native_processing_requested
  ) VALUES (
    NEW.author_id,
    v_first_url,
    NEW.thumbnail_url,
    NEW.content,
    NEW.id,
    COALESCE(NEW.visibility = 'public', false),
    v_source_type,
    v_yt_id,
    CASE WHEN v_yt_id IS NOT NULL THEN v_first_url ELSE NULL END,
    'ready',
    v_origin_type,
    v_playback_type,
    NEW.topic,
    v_rights_status,
    NEW.source_asset_id,
    COALESCE(
      NEW.canonical_asset_key,
      CASE WHEN v_yt_id IS NOT NULL THEN 'youtube:' || v_yt_id END
    ),
    NEW.publication_key,
    false
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Managed publication must remain atomic. Legacy user-post behavior keeps its
  -- historical best-effort mirror so an unrelated Reel error cannot lose a post.
  IF NEW.origin_type = 'video_library' THEN
    RAISE;
  END IF;
  RAISE WARNING 'fn_social_posts_video_to_reel_mirror skipped post % (%)', NEW.id, SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_social_posts_video_to_reel_mirror() OWNER TO postgres;

--
-- Name: fn_social_reels_block_too_long(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_social_reels_block_too_long() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_duration_text text;
  v_duration numeric;
BEGIN
  -- Long source embeds remain valid library/social content. The duration guard
  -- applies only to an explicitly authorized native-processing request.
  IF NOT NEW.native_processing_requested
     OR NEW.rights_status NOT IN ('owned', 'licensed')
     OR NEW.source_post_id IS NULL
  THEN
    RETURN NEW;
  END IF;

  SELECT p.metadata ->> 'duration_seconds'
  INTO v_duration_text
  FROM public.social_posts p
  WHERE p.id = NEW.source_post_id;

  IF v_duration_text ~ '^[0-9]+([.][0-9]+)?$' THEN
    v_duration := v_duration_text::numeric;
  END IF;

  IF v_duration IS NOT NULL AND v_duration >= 600 THEN
    RAISE NOTICE '[reels-filter] blocking native processing: post % has duration_seconds=%',
      NEW.source_post_id, v_duration;
    NEW.native_processing_requested := false;
    NEW.media_status := 'ready';
    NEW.playback_type := 'youtube_embed';
    NEW.video_url := COALESCE(NEW.original_youtube_url, NEW.video_url);
    RETURN NEW;
  END IF;

  RETURN NEW;
END
$_$;


ALTER FUNCTION public.fn_social_reels_block_too_long() OWNER TO postgres;

--
-- Name: fn_social_reels_yt_intercept(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_social_reels_yt_intercept() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_yt_id text;
  v_provenance_yt_id text;
  v_prior_yt_id text;
  v_service_role boolean := COALESCE(auth.role()::text, '') = 'service_role';
  v_native_enabled boolean := false;
  v_native_allowed boolean := false;
BEGIN
  -- Intercept only when the URL being played is a YouTube URL. A completed
  -- worker legitimately retains youtube_video_id/original_youtube_url while
  -- changing video_url to native storage; using those provenance fields as the
  -- detector would accidentally undo every successful conversion.
  v_yt_id := public.fn_extract_youtube_video_id(NEW.video_url);

  IF TG_OP = 'UPDATE' THEN
    v_prior_yt_id := COALESCE(
      public.fn_extract_youtube_video_id(OLD.video_url),
      public.fn_extract_youtube_video_id(OLD.original_youtube_url),
      CASE
        WHEN OLD.youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'
          THEN OLD.youtube_video_id
        ELSE NULL
      END
    );
  END IF;

  IF v_yt_id IS NULL THEN
    IF public.fn_is_platform_public_storage_url(NEW.video_url)
    THEN
      NEW.playback_type := 'native';
      NEW.source_type := 'native';
      NEW.native_processing_requested := false;
      v_provenance_yt_id := COALESCE(
        public.fn_extract_youtube_video_id(NEW.original_youtube_url),
        CASE
          WHEN NEW.youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'
            THEN NEW.youtube_video_id
          ELSE NULL
        END,
        v_prior_yt_id
      );
      IF v_provenance_yt_id IS NOT NULL
         AND (
           TG_OP = 'INSERT'
           OR OLD.playback_type IS DISTINCT FROM 'native'
           OR OLD.source_type IS DISTINCT FROM 'native'
           OR OLD.video_url IS DISTINCT FROM NEW.video_url
         )
         AND (
           NOT v_service_role
           OR NEW.rights_status NOT IN ('owned', 'licensed')
           OR NOT EXISTS (
             SELECT 1
             FROM public.video_transcode_jobs completion_job
             WHERE completion_job.id = current_setting(
                     'app.youtube_native_completion_job_id', true
                   )
               AND completion_job.status = 'completed'
               AND completion_job.reel_id = NEW.id
               AND completion_job.user_id IS NOT DISTINCT FROM NEW.author_id
               AND completion_job.rights_status IS NOT DISTINCT FROM NEW.rights_status
               AND completion_job.canonical_asset_key = 'youtube:' || v_provenance_yt_id
               AND completion_job.output_url IS NOT DISTINCT FROM
                 split_part(split_part(NEW.video_url, '?', 1), '#', 1)
           )
         )
      THEN
        RAISE EXCEPTION USING
          ERRCODE = '42501',
          MESSAGE = 'YouTube-derived native Reels may only be published by complete_rights_cleared_youtube_transcode';
      END IF;
      IF v_service_role
         AND NEW.rights_status IN ('owned', 'licensed')
         AND v_provenance_yt_id IS NOT NULL
      THEN
        NEW.youtube_video_id := v_provenance_yt_id;
        NEW.canonical_asset_key := 'youtube:' || v_provenance_yt_id;
      ELSE
        NEW.youtube_video_id := NULL;
        NEW.canonical_asset_key := 'native:' || md5(NEW.video_url);
      END IF;
      IF NOT v_service_role
         AND auth.uid() = NEW.author_id
         AND public.fn_is_user_video_storage_url(NEW.video_url, NEW.author_id)
      THEN
        NEW.rights_status := 'user_authorized';
      ELSIF v_service_role
         AND NEW.rights_status = 'user_authorized'
         AND public.fn_is_user_video_storage_url(NEW.video_url, NEW.author_id)
      THEN
        NEW.rights_status := 'user_authorized';
      ELSIF NEW.rights_status = 'user_authorized'
         OR (NOT v_service_role AND NEW.rights_status IN ('owned', 'licensed'))
      THEN
        NEW.rights_status := 'unknown';
      END IF;
    ELSIF NEW.playback_type = 'native' THEN
      NEW.source_type := 'user';
      NEW.native_processing_requested := false;
      NEW.youtube_video_id := NULL;
      NEW.canonical_asset_key := 'external:' || md5(NEW.video_url);
      NEW.playback_type := 'external_embed';
      NEW.rights_status := 'unknown';
    ELSIF NEW.playback_type = 'youtube_embed'
       OR NEW.youtube_video_id IS NOT NULL
    THEN
      -- A caller cannot pair a synthetic YouTube identity with an arbitrary
      -- external playable URL. A valid original is canonicalized; otherwise
      -- the row is demoted out of the public Reels playback contract.
      v_provenance_yt_id := public.fn_extract_youtube_video_id(
        NEW.original_youtube_url
      );
      IF v_provenance_yt_id IS NOT NULL THEN
        NEW.video_url := NEW.original_youtube_url;
        NEW.youtube_video_id := v_provenance_yt_id;
        NEW.canonical_asset_key := 'youtube:' || v_provenance_yt_id;
        NEW.playback_type := 'youtube_embed';
        NEW.source_type := 'youtube';
        NEW.native_processing_requested := false;
        IF NOT v_service_role OR NEW.rights_status NOT IN ('owned', 'licensed') THEN
          NEW.rights_status := 'embed_only';
        END IF;
      ELSE
        NEW.youtube_video_id := NULL;
        NEW.canonical_asset_key := 'external:' || md5(NEW.video_url);
        NEW.playback_type := 'external_embed';
        NEW.native_processing_requested := false;
        NEW.rights_status := 'unknown';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  PERFORM public.fn_queue_youtube_verification(
    v_yt_id,
    'social_reel_write'
  );

  SELECT c.enabled
  INTO v_native_enabled
  FROM public.video_reels_pipeline_controls c
  WHERE c.control_key = 'youtube_native_transcode';

  v_native_allowed :=
    v_service_role
    AND COALESCE(v_native_enabled, false)
    AND NEW.native_processing_requested
    AND NEW.rights_status IN ('owned', 'licensed')
    -- Phase 1 library publications are canonical embeds. Rights-cleared native
    -- library masters are introduced by the Phase 6 studio and must not be
    -- improvised from a third-party library URL in the meantime.
    AND NEW.origin_type IS DISTINCT FROM 'video_library'
    AND NEW.source_type IS DISTINCT FROM 'video_library';

  NEW.youtube_video_id := v_yt_id;
  -- The playable URL, not caller-supplied identity fields, owns canonical
  -- identity. This also repairs a Reel whose YouTube URL is intentionally
  -- replaced with a different video.
  NEW.canonical_asset_key := 'youtube:' || v_yt_id;
  NEW.original_youtube_url := NEW.video_url;

  IF NEW.origin_type = 'video_library' OR NEW.source_type = 'video_library' THEN
    NEW.source_type := 'video_library';
  ELSE
    NEW.source_type := 'youtube';
  END IF;

  IF v_native_allowed THEN
    NEW.playback_type := 'youtube_embed';
    NEW.media_status := 'queued';
  ELSE
    -- Unknown third-party YouTube rights become embed-only. A client cannot
    -- spoof the new columns to reach the queue because the service-role claim,
    -- explicit request, grant, and kill switch are all required above.
    IF NOT v_service_role OR NEW.rights_status NOT IN ('owned', 'licensed') THEN
      NEW.rights_status := 'embed_only';
    END IF;
    NEW.native_processing_requested := false;
    NEW.playback_type := 'youtube_embed';
    NEW.media_status := 'ready';
    NEW.video_url := COALESCE(NEW.original_youtube_url, NEW.video_url);
  END IF;

  RETURN NEW;
END
$_$;


ALTER FUNCTION public.fn_social_reels_yt_intercept() OWNER TO postgres;

--
-- Name: fn_social_reels_yt_queue_job(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_social_reels_yt_queue_job() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_native_enabled boolean := false;
BEGIN
  IF COALESCE(auth.role()::text, '') <> 'service_role' THEN
    RETURN NEW;
  END IF;

  SELECT c.enabled
  INTO v_native_enabled
  FROM public.video_reels_pipeline_controls c
  WHERE c.control_key = 'youtube_native_transcode';

  IF NOT COALESCE(v_native_enabled, false)
     OR NOT NEW.native_processing_requested
     OR NEW.rights_status NOT IN ('owned', 'licensed')
     OR NEW.media_status <> 'queued'
     OR NEW.youtube_video_id IS NULL
     OR NEW.source_post_id IS NULL
     OR NEW.origin_type = 'video_library'
     OR NEW.source_type = 'video_library'
  THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.youtube_embed_failures f
    WHERE f.video_id = NEW.youtube_video_id
      AND f.verification_status = 'confirmed'
      AND f.resolved = false
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'an active YouTube embed failure blocks native processing';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.video_transcode_jobs j
    WHERE j.reel_id = NEW.id
      AND j.status IN ('queued', 'processing', 'running', 'completed', 'done')
  ) THEN
    RETURN NEW;
  END IF;

  BEGIN
    INSERT INTO public.video_transcode_jobs (
      reel_id,
      user_id,
      source_url,
      youtube_url,
      source_type,
      status,
      target_format,
      target_bitrate,
      origin_type,
      rights_status,
      source_asset_id,
      canonical_asset_key
    ) VALUES (
      NEW.id,
      NEW.author_id,
      NEW.original_youtube_url,
      NEW.original_youtube_url,
      'youtube',
      'queued',
      'h264_1080p',
      2500000,
      NEW.origin_type,
      NEW.rights_status,
      NEW.source_asset_id,
      NEW.canonical_asset_key
    );
  EXCEPTION WHEN unique_violation THEN
    -- The existing live-job indexes are the cross-transaction race guard. A
    -- canonical sibling may use a different URL spelling, so do not strand the
    -- race loser in queued state waiting for an exact-URL broadcast.
    UPDATE public.social_reels r
    SET media_status = 'ready',
        playback_type = 'youtube_embed',
        native_processing_requested = false,
        video_url = r.original_youtube_url
    WHERE r.id = NEW.id;
  END;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_social_reels_yt_queue_job() OWNER TO postgres;

--
-- Name: fn_socialize_all_horses(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_socialize_all_horses() RETURNS TABLE(touched integer, horses integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r record; v_t integer := 0; v_n integer := 0;
BEGIN
  FOR r IN SELECT id FROM public.profiles WHERE is_horse ORDER BY created_at, id LOOP
    v_n := v_n + 1;
    IF public.fn_socialize_horse(r.id) THEN v_t := v_t + 1; END IF;
  END LOOP;
  touched := v_t; horses := v_n;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_socialize_all_horses() OWNER TO postgres;

--
-- Name: FUNCTION fn_socialize_all_horses(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_socialize_all_horses() IS 'Sweep: fn_socialize_horse over every is_horse profile. Safe to run any time; returns (touched, horses).';


--
-- Name: fn_socialize_horse(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_socialize_horse(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  p record; ca record; v_h bigint; v_loc text; v_tz text; v_spec text; v_stakes text; v_alias text; v_voice text; v_arch text; v_cad int; v_bday date; v_touched boolean := false;
  v_locs text[] := ARRAY['Atlantic City, NJ','Austin, TX','Barcelona, ES','Berlin, DE','Brooklyn, NY','Chicago, IL','Dallas, TX','Denver, CO','Dublin, IE','Las Vegas, NV','Lisbon, PT','London, UK','Los Angeles, CA','Manchester, UK','Manila, PH','Melbourne, AU','Miami, FL','Phoenix, AZ','Seattle, WA','Toronto, CA'];
  v_tzs text[] := ARRAY['America/New_York','America/Chicago','Europe/Madrid','Europe/Berlin','America/New_York','America/Chicago','America/Chicago','America/Denver','Europe/Dublin','America/Los_Angeles','Europe/Lisbon','Europe/London','America/Los_Angeles','Europe/London','Asia/Manila','Australia/Melbourne','America/New_York','America/Phoenix','America/Los_Angeles','America/Toronto'];
  v_specs text[] := ARRAY['bounty tournaments','cash games','heads-up','live cash','mixed games','PLO','satellites','short deck','spins','tournaments'];
  v_stk text[] := ARRAY['1/2','1/3','10/25','2/3','2/5','25/50','5/10'];
  v_voices text[] := ARRAY['analytical','blunt','hype','dry','veteran','casual','skeptical','excitable','terse','conversational','community','technical','storyteller','grinder','coach'];
  v_archs text[] := ARRAY['blunt','analytical','hype','dry','veteran','casual','skeptical','excitable','terse','conversational'];
BEGIN
  SELECT * INTO p FROM public.profiles WHERE id = p_id;
  IF NOT FOUND OR NOT COALESCE(p.is_horse, false) THEN RETURN false; END IF;
  v_h := abs(hashtext(p_id::text));
  v_loc := v_locs[1 + (v_h % 20)]; v_tz := v_tzs[1 + (v_h % 20)]; v_spec := v_specs[1 + ((v_h / 7) % 10)]; v_stakes := v_stk[1 + ((v_h / 11) % 7)];
  v_voice := v_voices[1 + ((v_h / 13) % array_length(v_voices, 1))]; v_arch := v_archs[1 + ((v_h / 17) % array_length(v_archs, 1))];
  v_cad := public.fn_fleet_cadence(p_id);
  v_bday := date '1972-01-01' + ((v_h / 23) % (365 * 30))::int;
  SELECT * INTO ca FROM public.content_authors WHERE profile_id = p_id;
  IF NOT FOUND THEN
    v_alias := public.fn_mint_social_alias(p_id::text);
    INSERT INTO public.content_authors (name, alias, location, timezone, specialty, stakes, bio, avatar_seed, avatar_url, profile_id, is_active, voice, birthday, personality)
    VALUES (COALESCE(NULLIF(p.display_name, ''), NULLIF(p.full_name, ''), p.username), v_alias, v_loc, v_tz, v_spec, v_stakes, v_spec || ' regular out of ' || v_loc || '. Mostly ' || v_stakes || '.', lower(v_alias) || '_' || substr(md5(p_id::text), 1, 8), p.avatar_url, p_id, true, v_voice, v_bday, jsonb_build_object('archetype', v_arch, 'cadence_per_week', v_cad, 'seeded_by', 'fn_socialize_horse', 'seeded_at', now()));
    v_touched := true;
    SELECT * INTO ca FROM public.content_authors WHERE profile_id = p_id;
  END IF;
  UPDATE public.content_authors SET is_active = true,
      location = COALESCE(NULLIF(location, ''), v_loc), timezone = COALESCE(NULLIF(timezone, ''), v_tz), specialty = COALESCE(NULLIF(specialty, ''), v_spec), stakes = COALESCE(NULLIF(stakes, ''), v_stakes),
      bio = COALESCE(NULLIF(bio, ''), v_spec || ' regular out of ' || COALESCE(NULLIF(location,''), v_loc) || '. Mostly ' || COALESCE(NULLIF(stakes,''), v_stakes) || '.'),
      voice = COALESCE(NULLIF(voice, ''), v_voice), birthday = COALESCE(birthday, v_bday), avatar_url = COALESCE(avatar_url, p.avatar_url),
      personality = COALESCE(personality, '{}'::jsonb)
                    || CASE WHEN COALESCE(personality, '{}'::jsonb) ? 'archetype' THEN '{}'::jsonb ELSE jsonb_build_object('archetype', v_arch) END
                    || jsonb_build_object('cadence_per_week', v_cad)
                    || CASE WHEN COALESCE(personality, '{}'::jsonb) ? 'seeded_by' THEN '{}'::jsonb ELSE jsonb_build_object('seeded_by', 'fn_socialize_horse', 'seeded_at', now()) END
  WHERE profile_id = p_id
    AND (NOT is_active OR COALESCE(location,'') = '' OR COALESCE(timezone,'') = '' OR COALESCE(specialty,'') = '' OR COALESCE(stakes,'') = '' OR COALESCE(bio,'') = '' OR COALESCE(voice,'') = '' OR birthday IS NULL OR avatar_url IS NULL OR personality IS NULL OR NOT (personality ? 'archetype') OR (personality->>'cadence_per_week') IS DISTINCT FROM v_cad::text);
  IF FOUND THEN v_touched := true; END IF;
  SELECT * INTO ca FROM public.content_authors WHERE profile_id = p_id;
  UPDATE public.profiles SET bio = COALESCE(NULLIF(bio, ''), ca.bio), city = COALESCE(NULLIF(city, ''), split_part(ca.location, ',', 1)), favorite_game = COALESCE(NULLIF(favorite_game, ''), ca.specialty), birth_year = COALESCE(birth_year, EXTRACT(YEAR FROM ca.birthday)::int), social_profile_completed = true, updated_at = now()
  WHERE id = p_id AND (COALESCE(bio,'') = '' OR COALESCE(city,'') = '' OR COALESCE(favorite_game,'') = '' OR birth_year IS NULL OR NOT COALESCE(social_profile_completed, false));
  IF FOUND THEN v_touched := true; END IF;
  RETURN v_touched;
END; $$;


ALTER FUNCTION public.fn_socialize_horse(p_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_socialize_horse(p_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_socialize_horse(p_id uuid) IS 'Idempotent. Gives one horse everything the social content engine needs: content_authors row (alias, city, tz, specialty, stakes, bio, voice, birthday, personality seed) and a completed public profile. Fills only what is empty. Fired by trg_profiles_horse_is_born_social and by fn_socialize_all_horses().';


--
-- Name: fn_solver_v2_progress(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_solver_v2_progress() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_done      bigint;
  v_last24    bigint;
  v_latest    timestamptz;
  v_total_est bigint;
BEGIN
  SELECT count(*), max(solved_v2_at)
    INTO v_done, v_latest
  FROM public.solved_spots_gold
  WHERE solved_v2_at IS NOT NULL;

  SELECT count(*) INTO v_last24
  FROM public.solved_spots_gold
  WHERE solved_v2_at > now() - interval '24 hours';

  SELECT GREATEST(reltuples::bigint, 0) INTO v_total_est
  FROM pg_class WHERE oid = 'public.solved_spots_gold'::regclass;

  RETURN jsonb_build_object(
    'v2_done',              v_done,
    'v2_last_24h',          v_last24,
    'v2_latest',            v_latest,
    'total_spots_estimate', v_total_est,
    'v2_remaining',         GREATEST(v_total_est - v_done, 0)
  );
END;
$$;


ALTER FUNCTION public.fn_solver_v2_progress() OWNER TO postgres;

--
-- Name: fn_spin_absorb_club_pool_into_union(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_absorb_club_pool_into_union(p_club_id uuid, p_union_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bal numeric; v_seed numeric; v_after numeric;
BEGIN
  IF p_club_id IS NULL OR p_union_id IS NULL OR p_club_id = p_union_id THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'nothing_to_absorb');
  END IF;

  SELECT balance, seeded_amount INTO v_bal, v_seed
    FROM public.spin_bonus_pools WHERE club_id = p_club_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'club_had_no_pool');
  END IF;

  IF COALESCE(v_bal,0) > 0 THEN
    v_after := public.fn_spin_move_owner_wallet(p_club_id, 'club', 'chip_treasury', v_bal);
    IF v_after IS NULL THEN
      RAISE EXCEPTION 'cannot return the % Spins balance of club % to its treasury', v_bal, p_club_id;
    END IF;

    INSERT INTO public.spin_reserve_ledger (club_id, kind, amount, balance_after, note)
    VALUES (p_club_id, 'merge', -v_bal, 0,
            format('Spins wallet closed on joining union %s - entire balance (including %s of outstanding seed) paid to the club main bank, to keep or disburse at its own discretion',
                   p_union_id, COALESCE(v_seed,0)));
  END IF;

  UPDATE public.spin_bonus_pools
     SET balance = 0, seeded_amount = 0, required_seed_at_activation = 0,
         seed_source_wallet = NULL, offered_max_stake = 0,
         is_active = false, deactivated_at = now(), updated_at = now()
   WHERE club_id = p_club_id;

  RETURN jsonb_build_object('ok', true, 'club_id', p_club_id, 'union_id', p_union_id,
    'paid_to_main_bank', COALESCE(v_bal,0), 'club_treasury_after', v_after);
END;
$$;


ALTER FUNCTION public.fn_spin_absorb_club_pool_into_union(p_club_id uuid, p_union_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_absorb_club_pool_into_union(p_club_id uuid, p_union_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_absorb_club_pool_into_union(p_club_id uuid, p_union_id uuid) IS 'Closes a club Spins wallet on union join and pays the ENTIRE balance, seed and float alike, into the club main bank.';


--
-- Name: fn_spin_activate(uuid, numeric, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_activate(p_club_id uuid, p_seed_amount numeric, p_offered_max_stake numeric, p_source_wallet text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner uuid; v_kind text; v_required numeric; v_seed numeric;
  v_wallet_after numeric; v_bal numeric; v_active boolean; v_activated timestamptz;
  v_outstanding numeric; v_prev_wallet text; v_still_needed numeric;
BEGIN
  IF COALESCE(p_offered_max_stake,0) <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'max_stake_must_be_positive');
  END IF;

  v_owner    := public.fn_spin_reserve_pool(p_club_id);
  v_kind     := public.fn_spin_owner_kind(v_owner);
  v_required := public.fn_spin_required_seed(p_offered_max_stake);

  IF v_required <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'max_stake_too_small',
      'offered_max_stake', p_offered_max_stake);
  END IF;

  v_seed := round(COALESCE(p_seed_amount, 0), 2);

  SELECT is_active, activated_at, seeded_amount, seed_source_wallet
    INTO v_active, v_activated, v_outstanding, v_prev_wallet
    FROM public.spin_bonus_pools WHERE club_id = v_owner FOR UPDATE;

  IF COALESCE(v_active,false) AND v_activated IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_active', 'owner_id', v_owner);
  END IF;

  IF COALESCE(v_outstanding,0) > 0
     AND v_prev_wallet IS NOT NULL
     AND v_prev_wallet <> p_source_wallet THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seed_outstanding_to_another_wallet',
      'outstanding', v_outstanding, 'owed_to', v_prev_wallet, 'owner_id', v_owner);
  END IF;

  -- An outstanding seed is already IN the pool doing the job the seed exists
  -- to do. Charging for it again is charging twice for the same protection.
  v_still_needed := GREATEST(v_required - COALESCE(v_outstanding, 0), 0);

  IF v_seed < v_still_needed THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seed_below_required',
      'required_seed', v_required, 'already_outstanding', COALESCE(v_outstanding,0),
      'still_needed', v_still_needed, 'offered', v_seed,
      'owner_id', v_owner, 'owner_kind', v_kind);
  END IF;

  -- Zero is a legitimate top-up when the outstanding seed already covers the
  -- bar; skip the wallet move entirely rather than book a no-op transfer.
  IF v_seed > 0 THEN
    v_wallet_after := public.fn_spin_move_owner_wallet(
                        v_owner, v_kind, p_source_wallet, -v_seed);
    IF v_wallet_after IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'insufficient_funds_or_no_wallet',
        'wallet', p_source_wallet, 'owner_id', v_owner, 'owner_kind', v_kind);
    END IF;
  END IF;

  UPDATE public.spin_bonus_pools
     SET balance            = balance + v_seed,
         seeded_amount      = seeded_amount + v_seed,
         seed_source_wallet = p_source_wallet,
         offered_max_stake  = p_offered_max_stake,
         highest_stake      = GREATEST(highest_stake, p_offered_max_stake),
         -- GREATEST only while something is owed. See the reset in settle:
         -- once the seed is repaid this drops to 0 and the next activation
         -- sets it fresh, so a retired 20,000 bar cannot strand a later 200.
         required_seed_at_activation = GREATEST(required_seed_at_activation, v_required),
         ceiling_amount     = 0,
         owner_kind         = v_kind,
         is_active          = true,
         activated_at       = now(),
         activated_by       = p_actor,
         deactivated_at     = NULL,
         updated_at         = now()
   WHERE club_id = v_owner RETURNING balance INTO v_bal;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'spin pool row vanished for owner % after debiting % from %',
      v_owner, v_seed, p_source_wallet;
  END IF;

  IF v_seed > 0 THEN
    INSERT INTO public.spin_reserve_ledger (club_id, kind, amount, balance_after, note)
    VALUES (v_owner, 'seed', v_seed, v_bal,
            format('activation seed from %s %s (repayable at %s%s)',
                   v_kind, p_source_wallet, v_required,
                   CASE WHEN COALESCE(v_outstanding,0) > 0
                        THEN format(', %s already outstanding', v_outstanding)
                        ELSE '' END));
  END IF;

  INSERT INTO public.spin_reserve_ledger (club_id, kind, amount, balance_after, note)
  VALUES (v_owner, 'activation', 0, v_bal,
          format('Spins activated, max stake %s, required seed %s, charged %s',
                 p_offered_max_stake, v_required, v_seed));

  RETURN jsonb_build_object('ok', true, 'owner_id', v_owner, 'owner_kind', v_kind,
    'balance', v_bal, 'seeded_amount', COALESCE(v_outstanding,0) + v_seed,
    'charged', v_seed, 'required_seed', v_required,
    'source_wallet', p_source_wallet, 'source_wallet_after', v_wallet_after,
    'offered_max_stake', p_offered_max_stake);
END;
$$;


ALTER FUNCTION public.fn_spin_activate(p_club_id uuid, p_seed_amount numeric, p_offered_max_stake numeric, p_source_wallet text, p_actor uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_activate(p_club_id uuid, p_seed_amount numeric, p_offered_max_stake numeric, p_source_wallet text, p_actor uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_activate(p_club_id uuid, p_seed_amount numeric, p_offered_max_stake numeric, p_source_wallet text, p_actor uuid) IS 'Owner turns Spins on: debits a wallet they hold for the seed, records it as outstanding, marks the pool active. Refuses below the required seed or without the funds.';


--
-- Name: fn_spin_book_entry(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_book_entry(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t record;
  v_owner uuid;
  v_pool_id uuid;
  v_table_id uuid;
  v_live_seats integer;
  v_seat_users integer;
  v_exact_seat_stacks integer;
  v_roster_users integer;
  v_paid_users integer;
  v_buyin_debits integer;
  v_buyin_total numeric;
  v_collected numeric;
  v_rake_rate numeric;
  v_rake numeric;
  v_reserve_in numeric;
  v_balance numeric;
  v_reserve public.spin_reserve_ledger%ROWTYPE;
  v_reserve_count integer;
  v_journal_id uuid;
  v_journal_count integer;
  v_entry_existed boolean := false;
  v_contrib jsonb;
  v_key text := 'spin:' || p_tournament_id::text || ':entry';
BEGIN
  SELECT t.id, t.club_id, t.buy_in_amount, t.max_players, t.variant,
         t.starting_chips,
         t.tournament_type, t.status
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND
     OR (lower(COALESCE(v_t.variant,'')) <> 'spin'
         AND upper(COALESCE(v_t.tournament_type,'')) <> 'SPIN') THEN
    RETURN jsonb_build_object('ok',false,'reason','not_a_spin');
  END IF;
  IF v_t.club_id IS NULL OR COALESCE(v_t.buy_in_amount,0) <= 0
     OR COALESCE(v_t.max_players,0) <> 3
     OR v_t.starting_chips IS NULL
     OR v_t.starting_chips::text IN ('NaN','Infinity','-Infinity')
     OR v_t.starting_chips <= 0
     OR upper(COALESCE(v_t.status::text,'')) IN ('COMPLETED','CANCELLED','CANCELED') THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_spin_contract');
  END IF;

  v_table_id := public.fn_tournament_primary_table(p_tournament_id);
  SELECT count(*), count(DISTINCT s.user_id),
         count(*) FILTER (
           WHERE s.stack IS NOT DISTINCT FROM v_t.starting_chips
             AND s.stack::text NOT IN ('NaN','Infinity','-Infinity')
             AND s.stack > 0)
    INTO v_live_seats, v_seat_users, v_exact_seat_stacks
    FROM public.table_seats s
   WHERE s.table_id = v_table_id AND s.left_at IS NULL;
  SELECT count(DISTINCT tp.user_id)
    INTO v_roster_users
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  SELECT count(*) INTO v_paid_users
    FROM (
      SELECT tp.user_id
        FROM public.tournament_players tp
        JOIN public.wallet_transactions w
          ON w.related_entity_id = tp.tournament_id
         AND w.user_id = tp.user_id
         AND w.type = 'debit'
         AND w.category = 'tournament_buyin'
       WHERE tp.tournament_id = p_tournament_id
       GROUP BY tp.user_id
      HAVING round(sum(w.amount),2) = round(v_t.buy_in_amount,2)
    ) paid;
  SELECT count(*), round(COALESCE(sum(w.amount),0),2)
    INTO v_buyin_debits,v_buyin_total
    FROM public.wallet_transactions w
   WHERE w.related_entity_id = p_tournament_id
     AND w.type = 'debit'
     AND w.category = 'tournament_buyin';
  SELECT EXISTS (
    SELECT 1 FROM public.spin_reserve_ledger r
     WHERE r.tournament_id = p_tournament_id AND r.kind = 'contribution'
  ) INTO v_entry_existed;

  -- The live-seat distribution is an admission proof, not an immutable
  -- receipt proof. The third-seat transaction must begin with three exact
  -- starting stacks. Once its contribution exists, hands may redistribute or
  -- vacate those stacks; replay proves the three paid identities and the
  -- immutable contribution+journal below without demanding pre-hand state.
  IF (NOT v_entry_existed AND (
       v_table_id IS NULL OR v_live_seats <> 3 OR v_seat_users <> 3
       OR v_exact_seat_stacks <> 3
       OR EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id
            AND NOT EXISTS (
              SELECT 1 FROM public.table_seats s
               WHERE s.table_id = v_table_id AND s.left_at IS NULL
                 AND s.user_id = tp.user_id))))
     OR v_roster_users <> 3 OR v_paid_users <> 3
     OR v_buyin_debits <> 3
     OR v_buyin_total <> round(v_t.buy_in_amount * 3,2) THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','three_paid_seats_required',
      'seats',v_live_seats,'seat_users',v_seat_users,
      'exact_seat_stacks',v_exact_seat_stacks,
      'roster_users',v_roster_users,'paid_users',v_paid_users,
      'buyin_debits',v_buyin_debits,'buyin_total',v_buyin_total);
  END IF;

  -- One lock order for both the seat trigger and the start authority.
  PERFORM 1 FROM public.tournament_escrow
   WHERE tournament_id = p_tournament_id FOR UPDATE;
  PERFORM pg_advisory_xact_lock(
    hashtextextended('spin_entry:' || p_tournament_id::text,0));

  v_owner := public.fn_spin_reserve_pool(v_t.club_id);
  SELECT p.id, p.balance INTO v_pool_id, v_balance
    FROM public.spin_bonus_pools p
   WHERE p.club_id = v_owner
   FOR UPDATE;
  IF v_pool_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','no_pool_row','owner_id',v_owner);
  END IF;

  v_collected := round(v_t.buy_in_amount * 3,2);
  v_rake_rate := public.fn_spin_rake_rate(v_t.buy_in_amount);
  v_rake := round(v_collected * v_rake_rate,2);
  v_reserve_in := round(v_collected - v_rake,2);

  SELECT count(*) INTO v_reserve_count
    FROM public.spin_reserve_ledger r
   WHERE r.tournament_id = p_tournament_id AND r.kind = 'contribution';
  IF v_reserve_count > 0 THEN
    IF v_reserve_count <> 1 THEN
      RAISE EXCEPTION 'Spin % has % contribution rows',
        p_tournament_id,v_reserve_count USING ERRCODE = '23505';
    END IF;
    SELECT * INTO v_reserve
      FROM public.spin_reserve_ledger r
     WHERE r.tournament_id = p_tournament_id AND r.kind = 'contribution'
     FOR SHARE;
    IF v_reserve.club_id IS DISTINCT FROM v_owner
       OR v_reserve.amount IS DISTINCT FROM v_reserve_in
       OR v_reserve.buy_in IS DISTINCT FROM v_t.buy_in_amount
       OR v_reserve.seats IS DISTINCT FROM 3
       OR v_reserve.house_rake IS DISTINCT FROM v_rake THEN
      RAISE EXCEPTION 'Spin % existing contribution disagrees with its paid entry',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    SELECT count(*) INTO v_journal_count
      FROM public.chip_ledger l
     WHERE l.category = 'spin_entry'
       AND l.from_type = 'prize_liability'
       AND l.from_entity_id = p_tournament_id
       AND l.to_type = 'spin_reserve'
       AND l.to_entity_id = v_pool_id
       AND l.tournament_id = p_tournament_id
       AND l.amount = v_reserve_in;
    IF v_journal_count <> 1 THEN
      RAISE EXCEPTION 'Spin % existing contribution has % exact journals',
        p_tournament_id,v_journal_count USING ERRCODE = 'P0404';
    END IF;
    SELECT l.id INTO v_journal_id
      FROM public.chip_ledger l
     WHERE l.category = 'spin_entry'
       AND l.from_type = 'prize_liability'
       AND l.from_entity_id = p_tournament_id
       AND l.to_type = 'spin_reserve'
       AND l.to_entity_id = v_pool_id
       AND l.tournament_id = p_tournament_id
       AND l.amount = v_reserve_in;
    RETURN jsonb_build_object(
      'ok',true,'reason','already_booked','collected',v_collected,
      'house_rake',v_rake,'reserve_in',v_reserve_in,'balance',v_balance,
      'owner_id',v_owner,'pool_id',v_pool_id,'seats',3,'paid_users',3,
      'entry_reserve_id',v_reserve.id,'entry_journal_id',v_journal_id);
  END IF;

  PERFORM public.fn_ca_declare_ledger(
    'spin_entry','prize_liability',p_tournament_id,NULL,v_key,NULL);
  UPDATE public.spin_bonus_pools
     SET balance = balance + v_reserve_in,
         total_deposited = total_deposited + v_reserve_in,
         spin_count = spin_count + 1,
         highest_stake = GREATEST(highest_stake,v_t.buy_in_amount),
         updated_at = now()
   WHERE id = v_pool_id
   RETURNING balance INTO v_balance;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Spin reserve pool % vanished while booking %',
      v_pool_id,p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  INSERT INTO public.spin_reserve_ledger
    (club_id,tournament_id,kind,amount,balance_after,multiplier,
     buy_in,seats,house_rake,note)
  VALUES
    (v_owner,p_tournament_id,'contribution',v_reserve_in,v_balance,NULL,
     v_t.buy_in_amount,3,v_rake,
     CASE WHEN v_owner = v_t.club_id
          THEN 'three exact paid buy-ins less fixed rake'
          ELSE format('three exact paid buy-ins less fixed rake (club %s)',v_t.club_id)
      END)
  RETURNING * INTO v_reserve;

  SELECT count(*), (array_agg(l.id ORDER BY l.created_at,l.id))[1]
    INTO v_journal_count,v_journal_id
    FROM public.chip_ledger l
   WHERE l.idempotency_key = v_key
     AND l.category = 'spin_entry'
     AND l.from_type = 'prize_liability'
     AND l.from_entity_id = p_tournament_id
     AND l.to_type = 'spin_reserve'
     AND l.to_entity_id = v_pool_id
     AND l.tournament_id = p_tournament_id
     AND l.amount = v_reserve_in;
  IF v_journal_count <> 1 THEN
    RAISE EXCEPTION 'Spin % new contribution has % exact keyed journals',
      p_tournament_id,v_journal_count USING ERRCODE = 'P0404';
  END IF;

  SELECT jsonb_object_agg(tp.user_id::text,v_t.buy_in_amount)
    INTO v_contrib
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  IF v_rake > 0 THEN
    INSERT INTO public.rake_records
      (hand_id,table_id,club_id,rake_amount,pot_size,num_players,
       bbj_contribution,is_tournament,tournament_id,source,
       player_contributions,metadata)
    VALUES
      (NULL,NULL,v_t.club_id,v_rake,v_collected,3,0,true,p_tournament_id,
       'fn_spin_book_entry',v_contrib,
       jsonb_build_object(
         'kind','spin_rake','buy_in',v_t.buy_in_amount,
         'rake_rate',v_rake_rate,'booked_at','third_paid_seat',
         'reserve_owner',v_owner,'treasury_credited',false,
         'distributed_by','atomic_distribute_rake',
         'rake_per_player',round(v_rake / 3,4),'seats_attributed',3));
  END IF;

  PERFORM set_config('app.ledger_category','',true);
  PERFORM set_config('app.ledger_counterparty','',true);
  PERFORM set_config('app.ledger_counterparty_entity','',true);
  PERFORM set_config('app.ledger_idempotency_key','',true);

  RETURN jsonb_build_object(
    'ok',true,'reason','booked','collected',v_collected,
    'house_rake',v_rake,'reserve_in',v_reserve_in,'balance',v_balance,
    'owner_id',v_owner,'pool_id',v_pool_id,'seats',3,'paid_users',3,
    'entry_reserve_id',v_reserve.id,'entry_journal_id',v_journal_id);
END;
$$;


ALTER FUNCTION public.fn_spin_book_entry(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_book_entry(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_book_entry(p_tournament_id uuid) IS 'Stage-1 rolling compatibility door and paid-third-seat primitive. Becomes owner-only in post-publish stage 2.';


--
-- Name: fn_spin_chip_conservation_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_chip_conservation_check(p_since_hours integer DEFAULT 6) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_hours     integer := GREATEST(COALESCE(p_since_hours, 6), 1);
  v_since     timestamptz := now() - make_interval(hours => v_hours);
  v_checked   integer := 0;
  v_minted    integer := 0;
  v_destroy   integer := 0;
  v_minted_c  numeric := 0;
  v_destroy_c numeric := 0;
  v_worst     numeric := 0;
  v_worst_id  uuid;
  v_ids       uuid[];
  v_lost_write integer := 0;
  v_in_play    integer := 0;
  v_unclear    integer := 0;
  v_verdict   text := 'pass';
  v_severity  text;
  v_message   text;
  v_context   jsonb;
  v_alerts    integer := 0;
BEGIN
  -- Lane F (2026-09-02): expected = every chip the game issued. Each entrant
  -- was issued starting_chips; each rebuy / re-entry issued
  -- COALESCE(rebuy_chips, starting_chips) and each add-on
  -- COALESCE(addon_chips, starting_chips) - the exact grants
  -- process_tournament_rebuy makes. Rebuy/add-on games used to be excluded.
  WITH g AS (
    SELECT t.id,
           (SELECT count(*) * t.starting_chips
                   + COALESCE(sum(GREATEST(COALESCE(tp.rebuys, 0), 0)), 0)
                     * COALESCE(NULLIF(t.rebuy_chips, 0), t.starting_chips)
                   + (count(*) FILTER (WHERE COALESCE(tp.add_on, false)))
                     * COALESCE(NULLIF(t.addon_chips, 0), t.starting_chips)
              FROM public.tournament_players tp
             WHERE tp.tournament_id = t.id) AS expected,
           (SELECT COALESCE(sum(tp.chips), 0) FROM public.tournament_players tp
             WHERE tp.tournament_id = t.id) AS actual
      FROM public.tournaments t
     WHERE t.status = 'COMPLETED'
       AND t.variant IN ('spin', 'sng')
       AND COALESCE(t.starting_chips, 0) > 0
       AND t.ended_at >= v_since
  ), d AS (
    SELECT id, actual - expected AS delta FROM g
  )
  SELECT count(*),
         count(*) FILTER (WHERE delta > 0),
         count(*) FILTER (WHERE delta < 0),
         COALESCE(sum(delta) FILTER (WHERE delta > 0), 0),
         COALESCE(sum(-delta) FILTER (WHERE delta < 0), 0),
         COALESCE(max(abs(delta)), 0),
         COALESCE((array_agg(id ORDER BY abs(delta) DESC) FILTER (WHERE delta <> 0))[1:20],
                  ARRAY[]::uuid[])
    INTO v_checked, v_minted, v_destroy, v_minted_c, v_destroy_c, v_worst, v_ids
    FROM d;

  v_worst_id := v_ids[1];

  IF array_length(v_ids, 1) > 0 THEN
    WITH s AS (
      SELECT t.id,
             (SELECT count(*) * t.starting_chips
                     + COALESCE(sum(GREATEST(COALESCE(tp.rebuys, 0), 0)), 0)
                       * COALESCE(NULLIF(t.rebuy_chips, 0), t.starting_chips)
                     + (count(*) FILTER (WHERE COALESCE(tp.add_on, false)))
                       * COALESCE(NULLIF(t.addon_chips, 0), t.starting_chips)
                FROM public.tournament_players tp
               WHERE tp.tournament_id = t.id) AS expected,
             (SELECT COALESCE(sum(tp.chips), 0) FROM public.tournament_players tp
               WHERE tp.tournament_id = t.id) AS actual,
             (SELECT COALESCE(sum((p->>'stack')::numeric), 0)
                FROM public.hand_history h,
                     LATERAL jsonb_array_elements(h.players) p
               WHERE h.id = (SELECT h2.id FROM public.hand_history h2
                              WHERE h2.tournament_id = t.id
                              ORDER BY h2.hand_number DESC LIMIT 1)) AS last_hand
        FROM public.tournaments t
       WHERE t.id = ANY(v_ids)
    )
    SELECT count(*) FILTER (WHERE last_hand = expected AND last_hand <> actual),
           count(*) FILTER (WHERE last_hand = actual AND last_hand <> expected),
           count(*) FILTER (WHERE last_hand NOT IN (expected, actual))
      INTO v_lost_write, v_in_play, v_unclear
      FROM s;
  END IF;

  IF v_minted > 0 OR v_destroy > 0 THEN
    v_verdict  := CASE WHEN v_destroy > 0 THEN 'chips_destroyed' ELSE 'chips_minted' END;
    v_severity := 'critical';
    v_message  := format(
      'Chip conservation broken on %s of %s completed spin/sng game(s) in the '
      'last %sh: %s minted %s chips, %s destroyed %s chips. Worst single game '
      'off by %s. Of the %s sampled: %s lost the final write (the engine ended '
      'on the right total, the record did not), %s had chips move in play (the '
      'engine believed the wrong total too - the serious kind, see issue 2406), '
      '%s unclear. The prize does not depend on the chip count, but the WINNER '
      'does.',
      v_minted + v_destroy, v_checked, v_hours,
      v_minted, round(v_minted_c, 0), v_destroy, round(v_destroy_c, 0),
      round(v_worst, 0),
      COALESCE(array_length(v_ids, 1), 0), v_lost_write, v_in_play, v_unclear);
  END IF;

  v_context := jsonb_build_object(
    'window_hours',    v_hours,
    'variants',        jsonb_build_array('spin', 'sng'),
    'games_checked',   v_checked,
    'minted_games',    v_minted,
    'minted_chips',    round(v_minted_c, 2),
    'destroyed_games', v_destroy,
    'destroyed_chips', round(v_destroy_c, 2),
    'worst_abs_delta', round(v_worst, 2),
    'worst_game',      v_worst_id,
    'sample_games',    to_jsonb(v_ids),
    'sample_size',     COALESCE(array_length(v_ids, 1), 0),
    'lost_final_write', v_lost_write,
    'chips_moved_in_play', v_in_play,
    'classification_unclear', v_unclear,
    'verdict',         v_verdict,
    'detail',          'every completed spin/sng game in the window; rebuy/re-entry/'
                       'add-on grants are counted into the expected total (rebuys x '
                       'rebuy_chips, add_on x addon_chips, each defaulting to '
                       'starting_chips) rather than excluding the game; the '
                       'classification compares each sampled game against the stack '
                       'sum in its own last hand; no money was moved by this check');

  IF v_severity IS NOT NULL THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT v_severity, 'fn_spin_chip_conservation_check', v_message, v_context
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'fn_spin_chip_conservation_check'
          AND fa.resolved IS NOT TRUE
          AND fa.context->>'verdict' = v_verdict);
    IF FOUND THEN v_alerts := 1; END IF;
  END IF;

  RETURN v_context || jsonb_build_object('ok', true, 'alerts_raised', v_alerts);
END;
$$;


ALTER FUNCTION public.fn_spin_chip_conservation_check(p_since_hours integer) OWNER TO postgres;

--
-- Name: fn_spin_deactivate(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_deactivate(p_club_id uuid, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner uuid;
  v_kind text;
  v_pool public.spin_bonus_pools%ROWTYPE;
  v_live_games integer := 0;
  v_seed_returned numeric := 0;
  v_wallet_after numeric := NULL;
  v_balance_after numeric := 0;
  v_seed_returned_total numeric := 0;
  v_actor uuid := COALESCE(p_actor, auth.uid(),
    '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);
BEGIN
  v_owner := public.fn_spin_reserve_pool(p_club_id);
  v_kind := public.fn_spin_owner_kind(v_owner);

  SELECT * INTO v_pool
    FROM public.spin_bonus_pools
   WHERE club_id = v_owner
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Spin Reserve Not Found For Owner %', v_owner;
  END IF;

  UPDATE public.spin_bonus_pools
     SET is_active = false,
         deactivated_at = now(),
         updated_at = now()
   WHERE club_id = v_owner;

  SELECT count(*)::integer INTO v_live_games
    FROM public.tournaments t
   WHERE upper(COALESCE(t.tournament_type::text, '')) = 'SPIN'
     AND public.fn_spin_reserve_owner(t.club_id) = v_owner
     AND upper(COALESCE(t.status::text, '')) NOT IN ('COMPLETED', 'CANCELLED');

  IF COALESCE(v_pool.seeded_amount, 0) > 0
     AND v_pool.seed_source_wallet IS NOT NULL
     AND v_live_games = 0
     AND v_pool.balance >= v_pool.seeded_amount
  THEN
    -- This is one transfer represented by two balance-store updates. Suppress
    -- the generic per-store writers and append one explicit journal row, so a
    -- stale pooled-session category can never misclassify a seed return as
    -- rake (and the same transfer is never counted twice).
    PERFORM set_config('app.ledger_autoskip_clubs', '1', true);
    PERFORM set_config('app.ledger_autoskip_union_wallets', '1', true);
    PERFORM set_config('app.ledger_autoskip_spin_bonus_pools', '1', true);

    v_wallet_after := public.fn_spin_move_owner_wallet(
      v_owner,
      v_kind,
      v_pool.seed_source_wallet,
      v_pool.seeded_amount
    );
    IF v_wallet_after IS NULL THEN
      RAISE EXCEPTION 'Spin Seed Could Not Be Returned To % %',
        v_kind, v_pool.seed_source_wallet;
    END IF;

    UPDATE public.spin_bonus_pools
       SET balance = balance - v_pool.seeded_amount,
           seeded_amount = 0,
           seed_returned_amount = seed_returned_amount + v_pool.seeded_amount,
           seed_returned_at = now(),
           updated_at = now()
     WHERE club_id = v_owner
     RETURNING balance INTO v_balance_after;

    v_seed_returned := v_pool.seeded_amount;
    v_seed_returned_total := COALESCE(v_pool.seed_returned_amount, 0) + v_seed_returned;

    INSERT INTO public.chip_ledger
      (performed_by, from_type, from_entity_id, from_label,
       to_type, to_entity_id, to_label, amount, category,
       club_id, union_id, description, idempotency_key,
       pre_from_balance, post_from_balance, pre_to_balance, post_to_balance,
       metadata)
    VALUES
      (v_actor, 'spin_reserve', v_owner, 'spin_bonus_pools.balance',
       CASE WHEN v_kind = 'union' THEN 'union_bank' ELSE 'club_treasury' END,
       v_owner,
       CASE WHEN v_kind = 'union' THEN 'union_wallets.' || v_pool.seed_source_wallet
            ELSE 'clubs.' || v_pool.seed_source_wallet END,
       v_seed_returned, 'reversal',
       CASE WHEN v_kind = 'club' THEN v_owner END,
       CASE WHEN v_kind = 'union' THEN v_owner END,
       'Outstanding Spin Seed Returned After Deactivation And Final Settlement',
       format('spin-deactivation-seed-return:%s:%s', v_owner, v_seed_returned_total),
       v_pool.balance, v_balance_after,
       v_wallet_after - v_seed_returned, v_wallet_after,
       jsonb_build_object('economic_event', 'spin_seed_return',
                          'live_games_at_return', v_live_games,
                          'source_wallet', v_pool.seed_source_wallet));

    INSERT INTO public.spin_reserve_ledger
      (club_id, kind, amount, balance_after, note)
    VALUES
      (v_owner, 'seed_return', -v_seed_returned, v_balance_after,
       format('inactive board seed returned to %s %s after all live Spins settled',
              v_kind, v_pool.seed_source_wallet));
  ELSE
    v_balance_after := v_pool.balance;
  END IF;

  IF v_kind = 'union' THEN
    UPDATE public.clubs
       SET spins_enabled = false,
           spins_preseed_amount = CASE WHEN v_seed_returned > 0 THEN 0
                                       ELSE spins_preseed_amount END,
           updated_at = now()
     WHERE union_id = v_owner;
  ELSE
    UPDATE public.clubs
       SET spins_enabled = false,
           spins_preseed_amount = CASE WHEN v_seed_returned > 0 THEN 0
                                       ELSE spins_preseed_amount END,
           updated_at = now()
     WHERE id = v_owner;
  END IF;

  INSERT INTO public.spin_reserve_ledger (club_id, kind, amount, balance_after, note)
  VALUES (
    v_owner,
    'deactivation',
    0,
    v_balance_after,
    CASE
      WHEN v_seed_returned > 0 THEN
        format('Spins deactivated; %s seed chips returned after all live games settled',
               v_seed_returned)
      WHEN v_live_games > 0 THEN
        format('Spins deactivated; seed remains locked behind %s live games', v_live_games)
      ELSE 'Spins deactivated; no outstanding refundable seed'
    END
  );

  PERFORM set_config('app.ledger_autoskip_clubs', '', true);
  PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);
  PERFORM set_config('app.ledger_autoskip_spin_bonus_pools', '', true);

  RETURN jsonb_build_object(
    'ok', true,
    'owner_id', v_owner,
    'balance', v_balance_after,
    'live_games', v_live_games,
    'seed_returned', v_seed_returned,
    'source_wallet_after', v_wallet_after
  );
END;
$$;


ALTER FUNCTION public.fn_spin_deactivate(p_club_id uuid, p_actor uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_deactivate(p_club_id uuid, p_actor uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_deactivate(p_club_id uuid, p_actor uuid) IS 'Stops new Spins. Returns outstanding seed principal only when no live Spin games remain and the reserve can cover the return; settled net proceeds remain in the reserve.';


--
-- Name: fn_spin_draw_and_settle(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_draw_and_settle(p_tournament_id uuid, p_tiers jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t record;
  v_table_id uuid;
  v_paid_seats integer;
  v_seat_users integer;
  v_exact_seat_stacks integer;
  v_paid_users integer;
  v_roster_users integer;
  v_exact_roster_stacks integer;
  v_buyin_debits integer;
  v_buyin_total numeric;
  v_book jsonb;
  v_settle jsonb;
  v_owner uuid;
  v_pool_id uuid;
  v_available numeric;
  v_highest_stake numeric;
  v_rake_rate numeric;
  v_reserve_in numeric;
  v_tier jsonb;
  v_multiplier numeric;
  v_frequency numeric;
  v_threshold numeric;
  v_prize numeric;
  v_total numeric := 0;
  v_roll numeric;
  v_acc numeric := 0;
  v_pick numeric := NULL;
  v_eligible jsonb := '[]'::jsonb;
  v_locked jsonb := '[]'::jsonb;
  v_seen numeric[] := ARRAY[]::numeric[];
  v_booked_multiplier numeric;
  v_booked_draw numeric;
  v_leg_count integer;
  v_draw_existed boolean := false;
  v_entry_reserve_id uuid;
  v_entry_journal_id uuid;
  v_draw_reserve_id uuid;
  v_draw_journal_id uuid;
  v_escrow_reserve_out numeric;
  v_escrow_reserve_in numeric;
  v_escrow_prize_balance numeric;
  v_row_count integer;
  v_draw_key text := 'spin:' || p_tournament_id::text || ':draw';
  -- Product economics live inside the money authority. The service still
  -- submits its compiled copy during the rolling cutover, but a drifted or
  -- alternate service caller cannot change RTP, the ladder, or reserve gates.
  v_canonical_tiers constant jsonb := '[
    {"multiplier":2,"freq":4809776,"reserveThresholdX":0},
    {"multiplier":3,"freq":3930716,"reserveThresholdX":0},
    {"multiplier":4,"freq":900000,"reserveThresholdX":0},
    {"multiplier":5,"freq":250000,"reserveThresholdX":0},
    {"multiplier":10,"freq":100000,"reserveThresholdX":0},
    {"multiplier":25,"freq":7500,"reserveThresholdX":0},
    {"multiplier":50,"freq":1000,"reserveThresholdX":0},
    {"multiplier":100,"freq":1008,"reserveThresholdX":1.5}
  ]'::jsonb;
BEGIN
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'Spin draw-and-settle requires a tournament'
      USING ERRCODE = '22023';
  END IF;

  SELECT t.id, t.club_id, t.buy_in_amount, t.max_players, t.variant,
         t.tournament_type, t.status, t.spin_multiplier, t.prize_pool,
         t.spin_locked_tiers, t.starting_chips
    INTO v_t
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Spin tournament % does not exist', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  IF lower(COALESCE(v_t.variant,'')) <> 'spin'
     AND upper(COALESCE(v_t.tournament_type,'')) <> 'SPIN' THEN
    RAISE EXCEPTION 'tournament % is not a Spin', p_tournament_id
      USING ERRCODE = '22023';
  END IF;
  IF COALESCE(v_t.club_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = '00000000-0000-0000-0000-000000000000'::uuid
     OR COALESCE(v_t.buy_in_amount,0) <= 0
     OR COALESCE(v_t.max_players,0) <> 3
     OR v_t.starting_chips IS NULL
     OR v_t.starting_chips::text IN ('NaN','Infinity','-Infinity')
     OR v_t.starting_chips <= 0 THEN
    RAISE EXCEPTION 'Spin % has invalid club, buy-in, seat or starting-stack contract',
      p_tournament_id USING ERRCODE = '23514';
  END IF;
  IF upper(COALESCE(v_t.status::text,'')) IN
       ('COMPLETED','CANCELLED','CANCELED') THEN
    RAISE EXCEPTION 'Spin % cannot draw from status %',
      p_tournament_id, v_t.status USING ERRCODE = '55000';
  END IF;

  -- Decide admission versus replay while the tournament row is locked. No
  -- other draw authority can cross that row lock. A committed draw is an
  -- immutable money receipt: its replay must not depend on the live stack
  -- distribution or on a busted player's seat still being occupied.
  SELECT r.club_id, r.multiplier, round(-r.amount,2)
    INTO v_owner, v_booked_multiplier, v_booked_draw
    FROM public.spin_reserve_ledger r
   WHERE r.tournament_id = p_tournament_id AND r.kind = 'jackpot_draw'
   ORDER BY r.created_at, r.id
   LIMIT 1;
  v_draw_existed := v_booked_multiplier IS NOT NULL;

  -- A committed draw replays from immutable evidence and is deliberately
  -- independent of whatever tier payload a newer, older, or recovering
  -- service happens to carry. Only a brand-new money decision authenticates
  -- the caller's compiled copy against the database-owned product contract.
  IF NOT v_draw_existed AND (
       p_tiers IS NULL
       OR jsonb_typeof(p_tiers) <> 'array'
       OR p_tiers IS DISTINCT FROM v_canonical_tiers
     ) THEN
    RAISE EXCEPTION
      'Spin draw-and-settle tier contract does not match canonical economics v2026-09-05'
      USING ERRCODE = '22023';
  END IF;

  v_table_id := public.fn_tournament_primary_table(p_tournament_id);
  SELECT count(*), count(DISTINCT s.user_id),
         count(*) FILTER (
           WHERE s.stack IS NOT DISTINCT FROM v_t.starting_chips
             AND s.stack::text NOT IN ('NaN','Infinity','-Infinity')
             AND s.stack > 0)
    INTO v_paid_seats, v_seat_users, v_exact_seat_stacks
    FROM public.table_seats s
   WHERE s.table_id = v_table_id AND s.left_at IS NULL;
  SELECT count(DISTINCT tp.user_id),
         count(*) FILTER (
           WHERE tp.status = 'playing'
             AND tp.chips IS NOT DISTINCT FROM v_t.starting_chips
             AND tp.chips::text NOT IN ('NaN','Infinity','-Infinity')
             AND tp.chips > 0
             AND s.user_id IS NOT NULL
             AND tp.table_id IS NOT DISTINCT FROM s.table_id
             AND tp.seat_number IS NOT DISTINCT FROM s.seat_number)
    INTO v_roster_users, v_exact_roster_stacks
    FROM public.tournament_players tp
    LEFT JOIN public.table_seats s
      ON s.table_id = v_table_id
     AND s.user_id = tp.user_id
     AND s.left_at IS NULL
   WHERE tp.tournament_id = p_tournament_id;
  SELECT count(*) INTO v_paid_users
    FROM (
      SELECT tp.user_id
        FROM public.tournament_players tp
        JOIN public.wallet_transactions w
          ON w.related_entity_id = tp.tournament_id
         AND w.user_id = tp.user_id
         AND w.type = 'debit'
         AND w.category = 'tournament_buyin'
       WHERE tp.tournament_id = p_tournament_id
       GROUP BY tp.user_id
      HAVING round(sum(w.amount),2) = round(v_t.buy_in_amount,2)
    ) paid;
  SELECT count(*), round(COALESCE(sum(w.amount),0),2)
    INTO v_buyin_debits,v_buyin_total
    FROM public.wallet_transactions w
   WHERE w.related_entity_id = p_tournament_id
     AND w.type = 'debit'
     AND w.category = 'tournament_buyin';
  IF v_roster_users <> 3
     OR v_paid_users <> 3
     OR v_buyin_debits <> 3
     OR v_buyin_total <> round(v_t.buy_in_amount * 3,2) THEN
    RAISE EXCEPTION
      'Spin % does not have exactly three immutable paid identities (% roster users, % paid users, % debits, % total)',
      p_tournament_id,v_roster_users,v_paid_users,v_buyin_debits,v_buyin_total
      USING ERRCODE = '55000';
  END IF;
  IF NOT v_draw_existed
     AND (v_table_id IS NULL OR v_paid_seats <> 3 OR v_seat_users <> 3
       OR v_exact_seat_stacks <> 3
       OR v_exact_roster_stacks <> 3
       OR EXISTS (
         SELECT 1
           FROM public.tournament_players tp
          WHERE tp.tournament_id = p_tournament_id
            AND NOT EXISTS (
              SELECT 1 FROM public.table_seats s
               WHERE s.table_id = v_table_id
                 AND s.left_at IS NULL
                 AND s.user_id = tp.user_id
            )
       )) THEN
    RAISE EXCEPTION
      'Spin % is not exactly three paid rostered starting stacks (% seats, % exact seat stacks, % seat users, % roster users, % exact roster stacks, % paid users, % debits, % total)',
      p_tournament_id, v_paid_seats, v_exact_seat_stacks, v_seat_users,
      v_roster_users, v_exact_roster_stacks, v_paid_users, v_buyin_debits,v_buyin_total
      USING ERRCODE = '55000';
  END IF;

  v_rake_rate := public.fn_spin_rake_rate(v_t.buy_in_amount);
  v_reserve_in := round(v_t.buy_in_amount * 3 * (1 - v_rake_rate), 2);

  IF NOT v_draw_existed THEN
    -- fn_spin_book_entry owns the escrow -> advisory -> reserve lock order.
    -- The outer transaction retains every lock it takes through the new draw.
    v_owner := public.fn_spin_reserve_pool(v_t.club_id);
    v_book := public.fn_spin_book_entry(p_tournament_id);
    IF COALESCE((v_book->>'ok')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Spin % entry booking refused: %', p_tournament_id, v_book
        USING ERRCODE = 'P0404';
    END IF;
    BEGIN
      v_entry_reserve_id := (v_book->>'entry_reserve_id')::uuid;
      v_entry_journal_id := (v_book->>'entry_journal_id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'Spin % entry returned no immutable evidence ids: %',
        p_tournament_id,v_book USING ERRCODE = 'P0404';
    END;
  END IF;

  SELECT p.id, p.balance, GREATEST(p.highest_stake, v_t.buy_in_amount)
    INTO v_pool_id, v_available, v_highest_stake
    FROM public.spin_bonus_pools p
   WHERE p.club_id = v_owner
   FOR UPDATE;
  IF v_pool_id IS NULL THEN
    RAISE EXCEPTION 'Spin % reserve pool is missing', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;

  IF v_draw_existed THEN
    -- Replay is evidence-only. Do not call either lower money primitive after
    -- a draw exists: ownership may have changed since the draw, while the
    -- immutable reserve row and journal still name the exact historical pool.
    SELECT count(*), (array_agg(r.id ORDER BY r.created_at,r.id))[1]
      INTO v_row_count,v_entry_reserve_id
      FROM public.spin_reserve_ledger r
     WHERE r.tournament_id = p_tournament_id
       AND r.kind = 'contribution'
       AND r.club_id = v_owner
       AND r.amount = v_reserve_in
       AND r.buy_in = v_t.buy_in_amount
       AND r.seats = 3
       AND r.house_rake = round(v_t.buy_in_amount * 3 * v_rake_rate,2);
    IF v_row_count <> 1 THEN
      RAISE EXCEPTION 'Spin % replay has % exact entry reserve rows',
        p_tournament_id,v_row_count USING ERRCODE = 'P0404';
    END IF;
    SELECT count(*), (array_agg(l.id ORDER BY l.created_at,l.id))[1]
      INTO v_leg_count,v_entry_journal_id
      FROM public.chip_ledger l
      JOIN public.spin_reserve_ledger r ON r.id = v_entry_reserve_id
     WHERE l.category = 'spin_entry'
       AND l.from_type = 'prize_liability'
       AND l.from_entity_id = p_tournament_id
       AND l.to_type = 'spin_reserve'
       AND l.to_entity_id = v_pool_id
       AND l.tournament_id = p_tournament_id
       AND l.amount = v_reserve_in
       AND l.post_to_balance IS NOT DISTINCT FROM r.balance_after;
    IF v_leg_count <> 1 THEN
      RAISE EXCEPTION 'Spin % replay entry has % exact journal legs',
        p_tournament_id,v_leg_count USING ERRCODE = 'P0404';
    END IF;
  END IF;

  IF NOT EXISTS (
       SELECT 1 FROM public.spin_reserve_ledger r
        WHERE r.tournament_id = p_tournament_id
          AND r.kind = 'contribution'
          AND r.club_id = v_owner
          AND r.amount = v_reserve_in
     )
     OR (SELECT count(*) FROM public.chip_ledger l
          WHERE l.category = 'spin_entry'
            AND l.from_type = 'prize_liability'
            AND l.from_entity_id = p_tournament_id
            AND l.to_type = 'spin_reserve'
            AND l.to_entity_id = v_pool_id
            AND l.amount = v_reserve_in) <> 1 THEN
    RAISE EXCEPTION 'Spin % entry did not produce exact reserve evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_booked_multiplier IS NULL THEN
    IF COALESCE(v_t.spin_multiplier,0) > 0 THEN
      RAISE EXCEPTION
        'Spin % row carries multiplier % without an authoritative reserve draw',
        p_tournament_id, v_t.spin_multiplier USING ERRCODE = 'P0404';
    END IF;

    FOR v_tier IN SELECT value FROM jsonb_array_elements(v_canonical_tiers) LOOP
      BEGIN
        v_multiplier := (v_tier->>'multiplier')::numeric;
        v_frequency := (v_tier->>'freq')::numeric;
        v_threshold := COALESCE((v_tier->>'reserveThresholdX')::numeric,0);
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'Spin % tier is not numeric: %',
          p_tournament_id, v_tier USING ERRCODE = '22023';
      END;
      IF v_multiplier IS NULL OR v_multiplier <= 0
         OR v_frequency IS NULL OR v_frequency < 0
         OR v_threshold < 0
         OR v_multiplier = ANY(v_seen) THEN
        RAISE EXCEPTION 'Spin % tier is invalid or duplicated: %',
          p_tournament_id, v_tier USING ERRCODE = '23514';
      END IF;
      v_seen := array_append(v_seen, v_multiplier);
      v_prize := round(v_t.buy_in_amount * v_multiplier, 2);

      -- v_available already includes this event's contribution. The retired
      -- draw RPC added v_reserve_in a second time whenever entry was booked.
      IF v_available < v_prize THEN
        v_locked := v_locked || jsonb_build_object(
          'multiplier',v_multiplier,'reason','unaffordable',
          'unlocksAt',round(v_prize,2));
      ELSIF v_threshold > 0
            AND v_available < v_multiplier * v_highest_stake * v_threshold THEN
        v_locked := v_locked || jsonb_build_object(
          'multiplier',v_multiplier,'reason','threshold',
          'unlocksAt',round(v_multiplier * v_highest_stake * v_threshold,2));
      ELSE
        v_eligible := v_eligible || v_tier;
        v_total := v_total + v_frequency;
      END IF;
    END LOOP;

    IF v_total <= 0 OR jsonb_array_length(v_eligible) = 0 THEN
      RAISE EXCEPTION 'Spin % has no eligible funded tier at reserve %',
        p_tournament_id, v_available USING ERRCODE = '55000';
    END IF;

    v_roll := (('x' || encode(extensions.gen_random_bytes(6),'hex'))::bit(48)::bigint)::numeric
              / 281474976710656::numeric * v_total;
    FOR v_tier IN SELECT value FROM jsonb_array_elements(v_eligible) LOOP
      v_acc := v_acc + (v_tier->>'freq')::numeric;
      IF v_roll < v_acc THEN
        v_pick := (v_tier->>'multiplier')::numeric;
        EXIT;
      END IF;
    END LOOP;
    IF v_pick IS NULL THEN
      v_pick := (v_eligible -> (jsonb_array_length(v_eligible)-1)
                            ->> 'multiplier')::numeric;
    END IF;

    PERFORM set_config('app.ledger_idempotency_key',v_draw_key,true);
    v_settle := public.fn_spin_settle_game(
      p_tournament_id, v_t.club_id, v_t.buy_in_amount, 3,
      v_pick, v_rake_rate);
    PERFORM set_config('app.ledger_idempotency_key','',true);
    v_booked_multiplier := v_pick;
    v_booked_draw := round(v_t.buy_in_amount * v_pick,2);
  ELSE
    -- The immutable reserve and journal rows are the receipt. Reconstruct only
    -- the return envelope; no lower money function runs on a replay.
    v_settle := jsonb_build_object(
      'ok',true,'reason','already_settled',
      'multiplier',v_booked_multiplier,
      'pool_covered',v_booked_draw,
      'operator_shortfall',0);
    v_locked := COALESCE(v_t.spin_locked_tiers,'[]'::jsonb);
  END IF;

  IF COALESCE((v_settle->>'ok')::boolean,false) IS NOT TRUE
     OR (v_settle->>'multiplier') IS NOT NULL
        AND (v_settle->>'multiplier')::numeric <> v_booked_multiplier
     OR COALESCE((v_settle->>'pool_covered')::numeric,0) <> v_booked_draw
     OR COALESCE((v_settle->>'operator_shortfall')::numeric,0) <> 0 THEN
    RAISE EXCEPTION 'Spin % did not settle its exact funded draw: %',
      p_tournament_id, v_settle USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*), (array_agg(r.id ORDER BY r.created_at,r.id))[1]
    INTO v_row_count,v_draw_reserve_id
    FROM public.spin_reserve_ledger r
   WHERE r.tournament_id = p_tournament_id
     AND r.kind = 'jackpot_draw'
     AND r.club_id = v_owner
     AND r.multiplier = v_booked_multiplier
     AND r.buy_in = v_t.buy_in_amount
     AND r.seats = 3
     AND round(-r.amount,2) = v_booked_draw;
  IF v_row_count <> 1 THEN
    RAISE EXCEPTION 'Spin % draw evidence is not exact after settlement',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*), (array_agg(l.id ORDER BY l.created_at,l.id))[1]
    INTO v_leg_count,v_draw_journal_id
    FROM public.chip_ledger l
    JOIN public.spin_reserve_ledger r ON r.id = v_draw_reserve_id
   WHERE l.category = 'spin_prize'
     AND l.from_type = 'spin_reserve'
     AND l.from_entity_id = v_pool_id
     AND l.to_type = 'prize_liability'
     AND l.to_entity_id = p_tournament_id
     AND l.tournament_id = p_tournament_id
     AND l.amount = v_booked_draw
     AND l.post_from_balance IS NOT DISTINCT FROM r.balance_after
     AND (v_draw_existed OR l.idempotency_key = v_draw_key);
  IF v_leg_count <> 1 THEN
    RAISE EXCEPTION 'Spin % draw has % exact journal legs',
      p_tournament_id,v_leg_count USING ERRCODE = 'P0404';
  END IF;

  IF NOT EXISTS (
       SELECT 1 FROM public.spin_reserve_ledger r
       WHERE r.id = v_entry_reserve_id
          AND r.tournament_id = p_tournament_id
          AND r.kind = 'contribution'
          AND r.club_id = v_owner
          AND r.amount = v_reserve_in
          AND r.buy_in = v_t.buy_in_amount
          AND r.seats = 3
          AND r.house_rake = round(v_t.buy_in_amount * 3 * v_rake_rate,2))
     OR NOT EXISTS (
       SELECT 1 FROM public.chip_ledger l
       JOIN public.spin_reserve_ledger r ON r.id = v_entry_reserve_id
        WHERE l.id = v_entry_journal_id
          AND l.tournament_id = p_tournament_id
          AND l.category = 'spin_entry'
          AND l.from_type = 'prize_liability'
          AND l.from_entity_id = p_tournament_id
          AND l.to_type = 'spin_reserve'
          AND l.to_entity_id = v_pool_id
          AND l.amount = v_reserve_in
          AND l.post_to_balance IS NOT DISTINCT FROM r.balance_after) THEN
    RAISE EXCEPTION 'Spin % entry receipt ids do not resolve to exact evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT e.reserve_out,e.reserve_in,e.prize_balance
    INTO v_escrow_reserve_out,v_escrow_reserve_in,v_escrow_prize_balance
    FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND
     OR v_escrow_reserve_out IS DISTINCT FROM v_reserve_in
     OR v_escrow_reserve_in IS DISTINCT FROM v_booked_draw
     OR v_escrow_prize_balance IS DISTINCT FROM v_booked_draw THEN
    RAISE EXCEPTION
      'Spin % escrow does not equal entry %, draw % (out %, in %, prize %)',
      p_tournament_id,v_reserve_in,v_booked_draw,
      v_escrow_reserve_out,v_escrow_reserve_in,v_escrow_prize_balance
      USING ERRCODE = 'P0404';
  END IF;

  IF COALESCE(v_t.spin_multiplier,0) > 0
     AND v_t.spin_multiplier IS DISTINCT FROM v_booked_multiplier THEN
    RAISE EXCEPTION 'Spin % row multiplier % disagrees with immutable draw %',
      p_tournament_id,v_t.spin_multiplier,v_booked_multiplier
      USING ERRCODE = 'P0404';
  END IF;
  IF COALESCE(v_t.spin_multiplier,0) > 0
     AND v_t.prize_pool IS DISTINCT FROM v_booked_draw THEN
    RAISE EXCEPTION 'Spin % row prize pool % disagrees with immutable draw %',
      p_tournament_id,v_t.prize_pool,v_booked_draw USING ERRCODE = 'P0404';
  END IF;

  -- Stage 2 keys the immutable tournament-contract trigger to this authority.
  -- Stage 1 does not require the marker yet because the still-live old engine
  -- must be able to finish its database-first rolling cutover.
  PERFORM set_config(
    'app.spin_settlement_authority',p_tournament_id::text,true);
  UPDATE public.tournaments
     SET spin_multiplier = v_booked_multiplier,
         prize_pool = v_booked_draw,
         spin_locked_tiers = v_locked
   WHERE id = p_tournament_id;
  GET DIAGNOSTICS v_row_count = ROW_COUNT;
  PERFORM set_config('app.spin_settlement_authority','',true);
  IF v_row_count <> 1 THEN
    RAISE EXCEPTION 'Spin % tournament contract could not be stamped',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF NOT EXISTS (
       SELECT 1 FROM public.tournaments t
        WHERE t.id = p_tournament_id
          AND t.spin_multiplier IS NOT DISTINCT FROM v_booked_multiplier
          AND t.prize_pool IS NOT DISTINCT FROM v_booked_draw
          AND t.spin_locked_tiers IS NOT DISTINCT FROM v_locked
     ) THEN
    RAISE EXCEPTION 'Spin % tournament contract did not read back exactly',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  SELECT p.balance INTO v_available
    FROM public.spin_bonus_pools p WHERE p.id = v_pool_id;

  RETURN v_settle || jsonb_build_object(
    'ok',true,
    'money_path','fn_spin_draw_and_settle',
    'tournament_id',p_tournament_id,
    'seats',3,
    'paid_users',v_paid_users,
    'multiplier',v_booked_multiplier,
    'prize_pool',v_booked_draw,
    'pool_covered',v_booked_draw,
    'operator_shortfall',0,
    'draw_amount',v_booked_draw,
    'entry_amount',v_reserve_in,
    'reserve_in',v_reserve_in,
    'house_rake',round(v_t.buy_in_amount * 3 * v_rake_rate,2),
    'reserve_balance',v_available,
    'pool_id',v_pool_id,
    'entry_reserve_id',v_entry_reserve_id,
    'entry_journal_id',v_entry_journal_id,
    'draw_reserve_id',v_draw_reserve_id,
    'draw_journal_id',v_draw_journal_id,
    'escrow_reserve_out',v_escrow_reserve_out,
    'escrow_reserve_in',v_escrow_reserve_in,
    'escrow_prize_balance',v_escrow_prize_balance,
    'tournament_multiplier',v_booked_multiplier,
    'tournament_prize_pool',v_booked_draw,
    'locked',v_locked,
    'eligible_count',jsonb_array_length(v_eligible),
    'owner_id',v_owner);
END;
$$;


ALTER FUNCTION public.fn_spin_draw_and_settle(p_tournament_id uuid, p_tiers jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_draw_and_settle(p_tournament_id uuid, p_tiers jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_draw_and_settle(p_tournament_id uuid, p_tiers jsonb) IS 'Sole service-role Spin draw/settlement authority. Verifies three paid seats, books entry, draws against the locked real reserve, settles, and proves reserve+journal evidence in one transaction.';


--
-- Name: fn_spin_draw_and_settle_atomic(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_draw_and_settle_atomic(p_tournament_id uuid, p_launch_id uuid, p_lease_generation uuid, p_rule_manifest jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_lease public.engine_tournament_leases%ROWTYPE;
  v_launch public.tournament_launch_receipts%ROWTYPE;
  v_t public.tournaments%ROWTYPE;
  v_saved public.spin_draw_receipts%ROWTYPE;
  v_player record;
  v_entrants jsonb;
  v_paid numeric;
  v_entitled numeric;
  v_escrow public.tournament_escrow%ROWTYPE;
  v_wallet_gross numeric;
  v_manifest jsonb;
  v_hash text;
  v_tier jsonb;
  v_draw jsonb;
  v_settle jsonb;
  v_entry jsonb;
  v_receipt jsonb;
  v_multiplier numeric;
  v_prize numeric;
  v_count bigint;
  v_covered numeric;
  v_provenance text := 'at_draw';
  v_blinds jsonb;
  v_payouts jsonb;
  v_locked jsonb;
  v_freq numeric;
  v_weight numeric;
  v_played_recovery boolean := false;
  v_recovery jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  IF p_tournament_id IS NULL OR p_launch_id IS NULL OR p_lease_generation IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_launch_request');
  END IF;
  SELECT * INTO v_lease FROM public.engine_tournament_leases
   WHERE tournament_id = p_tournament_id FOR UPDATE;
  IF NOT FOUND OR v_lease.protocol_version IS DISTINCT FROM 2
     OR v_lease.lease_generation IS DISTINCT FROM p_lease_generation
     OR v_lease.heartbeat_at IS NULL
     OR v_lease.heartbeat_at < clock_timestamp() - interval '30 seconds' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'launch_lease_lost');
  END IF;

  -- Same receipt -> parent order as registration, launch and cancellation.
  PERFORM * FROM public.fn_lock_tournament_launch_proof_parents(ARRAY[p_tournament_id]);
  SELECT * INTO v_launch FROM public.tournament_launch_receipts
   WHERE tournament_id = p_tournament_id;
  SELECT * INTO v_t FROM public.tournaments WHERE id = p_tournament_id;
  IF v_launch.launch_id IS DISTINCT FROM p_launch_id
     OR v_launch.lease_generation IS DISTINCT FROM p_lease_generation
     OR v_launch.completed_at IS NOT NULL
     OR v_t.status IS DISTINCT FROM 'REGISTERING' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'launch_receipt_state_mismatch');
  END IF;
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'entry_purchases_frozen');
  END IF;
  IF v_t.variant IS DISTINCT FROM 'spin' OR v_t.max_players IS DISTINCT FROM 3
     OR COALESCE(v_t.buy_in_amount, 0) <= 0
     OR COALESCE(v_t.buy_in_fee, 0) <> 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_spin_contract');
  END IF;

  SELECT count(*), jsonb_agg(jsonb_build_object('registration_id', p.id,
           'user_id', p.user_id) ORDER BY p.user_id, p.id)
    INTO v_count, v_entrants
    FROM public.tournament_players p WHERE p.tournament_id = p_tournament_id
     AND p.status IN ('registered', 'playing');

  -- A dealt Spin may have one proven busted/vacated original seat. This does
  -- not lower the fresh-launch field: the proof requires the original three
  -- paid identities, immutable money journals, a persisted hand, two exact
  -- live seats and conservation of all three bought starting stacks.
  IF v_count = 2 THEN
    v_recovery := public.fn_prove_played_spin_launch_recovery(p_tournament_id);
    IF COALESCE((v_recovery->>'ok')::boolean, false) THEN
      v_played_recovery := true;
      SELECT count(*), jsonb_agg(jsonb_build_object('registration_id', p.id,
               'user_id', p.user_id) ORDER BY p.user_id, p.id)
        INTO v_count, v_entrants
        FROM public.tournament_players p
       WHERE p.tournament_id = p_tournament_id
         AND p.status IN ('playing', 'eliminated');
    END IF;
  END IF;

  IF v_count <> 3 OR (SELECT count(DISTINCT p.user_id)
      FROM public.tournament_players p WHERE p.tournament_id = p_tournament_id
       AND (p.status IN ('registered', 'playing')
            OR (v_played_recovery AND p.status = 'eliminated'))) <> 3 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'spin_field_unproven');
  END IF;

  -- Spin admission proves net paid entries directly. The generic refund
  -- planner compares advertised entry fees with escrow.fee_entries_in, but
  -- Spin escrow records its embedded 8% rake there despite buy_in_fee=0.
  -- A payout/refund policy comparison cannot stand in for this payment proof.
  SELECT * INTO v_escrow FROM public.tournament_escrow
   WHERE tournament_id = p_tournament_id FOR UPDATE;
  SELECT COALESCE(sum(w.amount), 0) INTO v_wallet_gross
    FROM public.wallet_transactions w WHERE w.related_entity_id = p_tournament_id
     AND w.type = 'debit' AND lower(w.category) = 'tournament_buyin';
  IF v_escrow.tournament_id IS NULL OR v_escrow.enforced IS DISTINCT FROM true
     OR v_escrow.gross_in IS DISTINCT FROM v_wallet_gross THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'spin_entry_escrow_unproven');
  END IF;
  FOR v_player IN SELECT p.user_id FROM public.tournament_players p
    WHERE p.tournament_id = p_tournament_id
      AND (p.status IN ('registered', 'playing')
           OR (v_played_recovery AND p.status = 'eliminated'))
    ORDER BY p.user_id LOOP
    -- The wallet receipt proves what this player still paid, including any
    -- prior refund. Immutable entitlements independently prove the original
    -- debit's exact wallet -> tournament double-entry leg and its consumption.
    SELECT COALESCE(sum(CASE
      WHEN w.type='debit' AND lower(w.category)='tournament_buyin' THEN w.amount
      WHEN w.type='credit' AND lower(w.category) IN ('refund','tournament_refund') THEN -w.amount
      ELSE 0 END), 0) INTO v_paid
      FROM public.wallet_transactions w
     WHERE w.related_entity_id=p_tournament_id AND w.user_id=v_player.user_id;
    SELECT COALESCE(sum(e.gross), 0) INTO v_entitled
      FROM public.tournament_refund_entitlements e
      JOIN public.chip_ledger l ON l.id=e.source_ledger_id
       AND l.club_id=e.refund_wallet_club_id AND l.amount=e.gross
       AND l.tournament_id=e.tournament_id AND l.from_type='player_wallet'
       AND l.from_entity_id=e.user_id AND l.to_type='prize_liability'
       AND l.to_entity_id=e.tournament_id AND lower(l.category)=e.charge_category
     WHERE e.tournament_id=p_tournament_id AND e.user_id=v_player.user_id
       AND e.entitlement_kind='wallet_charge' AND e.charge_category='tournament_buyin'
       AND e.refund_fee=0 AND e.refund_bounty=0
       AND NOT EXISTS (SELECT 1 FROM public.tournament_refund_tranches tr WHERE tr.entitlement_id=e.id)
       AND NOT EXISTS (SELECT 1 FROM public.tournament_tickets tk WHERE tk.source_refund_entitlement_id=e.id);
    IF v_paid IS DISTINCT FROM v_t.buy_in_amount OR v_entitled IS DISTINCT FROM v_paid THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'spin_paid_entry_unproven');
    END IF;
  END LOOP;

  SELECT * INTO v_saved FROM public.spin_draw_receipts WHERE tournament_id = p_tournament_id;
  IF FOUND THEN
    IF v_saved.launch_id IS DISTINCT FROM p_launch_id
       OR v_saved.entrants IS DISTINCT FROM v_entrants THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'spin_receipt_roster_mismatch');
    END IF;
    -- A new owner or newer rules cannot reroll or rewrite a committed result.
    RETURN v_saved.receipt || jsonb_build_object('replay', true);
  END IF;

  SELECT count(*), min(l.multiplier), min(-l.amount)
    INTO v_count, v_multiplier, v_covered FROM public.spin_reserve_ledger l
   WHERE l.tournament_id = p_tournament_id AND l.kind = 'jackpot_draw';
  IF v_count > 0 THEN
    -- Cutover recovery uses the already projected rules. It does not pretend
    -- that a historical probability snapshot exists or replace it with today's.
    v_prize := round(v_t.buy_in_amount * v_multiplier, 2);
    IF v_count <> 1 OR v_multiplier IS DISTINCT FROM v_t.spin_multiplier
       OR v_covered IS DISTINCT FROM v_prize OR COALESCE(v_multiplier, 0) <= 0
       OR jsonb_typeof(v_t.blind_structure::jsonb) IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_t.blind_structure::jsonb) = 0
       OR jsonb_typeof(v_t.payout_structure::jsonb) IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_t.payout_structure::jsonb) = 0 THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'legacy_spin_rules_unproven');
    END IF;
    v_provenance := 'legacy_projection';
    v_blinds := v_t.blind_structure::jsonb;
    v_payouts := v_t.payout_structure::jsonb;
    v_locked := COALESCE(v_t.spin_locked_tiers::jsonb, '[]'::jsonb);
    v_manifest := jsonb_build_object('version', 1, 'probability_snapshot', NULL,
      'buy_in', v_t.buy_in_amount, 'seats', 3, 'starting_chips', v_t.starting_chips,
      'multiplier', v_multiplier, 'blind_structure', v_blinds, 'payout_structure', v_payouts);
    v_settle := jsonb_build_object('pool_covered', v_covered, 'operator_shortfall', 0);
  ELSE
    IF v_t.spin_multiplier IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'projected_spin_draw_has_no_funding_proof');
    END IF;
    v_manifest := p_rule_manifest;
    IF v_manifest IS NULL OR (v_manifest->>'version')::int IS DISTINCT FROM 1
       OR (v_manifest->>'buy_in')::numeric IS DISTINCT FROM v_t.buy_in_amount
       OR (v_manifest->>'seats')::int IS DISTINCT FROM 3
       OR (v_manifest->>'starting_chips')::int IS DISTINCT FROM v_t.starting_chips
       OR (v_manifest->>'rake_rate')::numeric IS DISTINCT FROM public.fn_spin_rake_rate(v_t.buy_in_amount)
       OR jsonb_typeof(v_manifest->'tiers') IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_manifest->'tiers') = 0 THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'spin_rule_manifest_invalid');
    END IF;
    v_manifest := v_manifest || jsonb_build_object('draw_function_md5',
      md5(pg_get_functiondef('public.fn_spin_draw_multiplier(uuid,numeric,jsonb,numeric,integer)'::regprocedure)));
    v_freq := 0; v_weight := 0;
    FOR v_tier IN SELECT value FROM jsonb_array_elements(v_manifest->'tiers') LOOP
      IF jsonb_typeof(v_tier->'freq') IS DISTINCT FROM 'number'
         OR jsonb_typeof(v_tier->'multiplier') IS DISTINCT FROM 'number'
         OR COALESCE((v_tier->>'freq')::numeric, 0) <= 0
         OR COALESCE((v_tier->>'multiplier')::numeric, 0) <= 0
         OR COALESCE((v_tier->>'reserveThresholdX')::numeric, -1) < 0
         OR jsonb_typeof(v_tier->'blind_structure') IS DISTINCT FROM 'array'
         OR jsonb_array_length(v_tier->'blind_structure') <> 12
         OR (v_tier#>>'{blind_structure,11,spinContinuation,version}')::int IS DISTINCT FROM 1
         OR COALESCE((v_tier#>>'{blind_structure,11,spinContinuation,anchorLevel}')::numeric, 0) <= 0
         OR COALESCE((v_tier#>>'{blind_structure,11,spinContinuation,anchorBigBlind}')::numeric, 0) <= 0
         OR COALESCE((v_tier#>>'{blind_structure,11,spinContinuation,growth}')::numeric, 0) <= 1
         OR COALESCE((v_tier#>>'{blind_structure,11,spinContinuation,roundBigTo}')::numeric, 0) <= 0
         OR jsonb_typeof(v_tier->'payout_structure') IS DISTINCT FROM 'array'
         OR jsonb_array_length(v_tier->'payout_structure') NOT BETWEEN 1 AND 3
         OR EXISTS (
           SELECT 1 FROM jsonb_array_elements(v_tier->'blind_structure') WITH ORDINALITY b(value, ordinal)
            WHERE (b.value->>'level')::numeric IS DISTINCT FROM b.ordinal::numeric
               OR COALESCE((b.value->>'smallBlind')::numeric, 0) <= 0
               OR COALESCE((b.value->>'bigBlind')::numeric, 0) < (b.value->>'smallBlind')::numeric
               OR COALESCE((b.value->>'duration')::numeric, 0) <= 0
               OR (b.value->>'ante')::numeric IS DISTINCT FROM 0::numeric)
         OR EXISTS (
           SELECT 1 FROM jsonb_array_elements(v_tier->'payout_structure') WITH ORDINALITY p(value, ordinal)
            WHERE (p.value->>'place')::numeric IS DISTINCT FROM p.ordinal::numeric
               OR COALESCE((p.value->>'percentage')::numeric, 0) <= 0)
         OR (SELECT sum((x->>'percentage')::numeric)
               FROM jsonb_array_elements(v_tier->'payout_structure') x) IS DISTINCT FROM 100::numeric THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'spin_rule_manifest_invalid');
      END IF;
      v_freq := v_freq + (v_tier->>'freq')::numeric;
      v_weight := v_weight + (v_tier->>'freq')::numeric * (v_tier->>'multiplier')::numeric;
    END LOOP;
    IF v_weight <> v_freq * 3 * (1 - (v_manifest->>'rake_rate')::numeric)
       OR (SELECT count(DISTINCT x->>'multiplier') FROM jsonb_array_elements(v_manifest->'tiers') x)
           <> jsonb_array_length(v_manifest->'tiers') THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'spin_rule_manifest_invalid');
    END IF;

    -- Entry owns escrow -> entry advisory -> reserve locks. Its committed net
    -- contribution must be present before the affordability gate is evaluated.
    v_entry := public.fn_spin_book_entry(p_tournament_id);
    IF NOT COALESCE((v_entry->>'ok')::boolean, false) THEN
      RAISE EXCEPTION 'Spin entry booking failed: %', v_entry USING ERRCODE = 'P0404';
    END IF;
    IF (SELECT count(*) FROM public.spin_reserve_ledger l
         WHERE l.tournament_id=p_tournament_id AND l.kind='contribution') <> 1
       OR NOT EXISTS (SELECT 1 FROM public.spin_reserve_ledger l
         WHERE l.tournament_id=p_tournament_id AND l.kind='contribution'
           AND l.club_id=public.fn_spin_reserve_pool(v_t.club_id)
           AND l.seats=3 AND l.buy_in=v_t.buy_in_amount
           AND l.house_rake=round(3*v_t.buy_in_amount*(v_manifest->>'rake_rate')::numeric, 2)
           AND l.amount=round(3*v_t.buy_in_amount, 2)-l.house_rake) THEN
      RAISE EXCEPTION 'Spin contribution does not prove the three funded entries' USING ERRCODE = 'P0404';
    END IF;
    -- Zero hypothetical seats: all three paid entries are already in balance.
    -- The draw's pool row lock remains held through settlement and the receipt.
    v_draw := public.fn_spin_draw_multiplier(v_t.club_id, v_t.buy_in_amount,
      v_manifest->'tiers', (v_manifest->>'rake_rate')::numeric, 0);
    IF NOT COALESCE((v_draw->>'ok')::boolean, false) THEN
      RAISE EXCEPTION 'Spin funded draw unavailable: %', v_draw USING ERRCODE = 'P0404';
    END IF;
    v_multiplier := (v_draw->>'multiplier')::numeric;
    v_prize := round(v_t.buy_in_amount * v_multiplier, 2);
    SELECT value INTO STRICT v_tier FROM jsonb_array_elements(v_manifest->'tiers')
     WHERE (value->>'multiplier')::numeric = v_multiplier;
    v_blinds := v_tier->'blind_structure';
    v_payouts := v_tier->'payout_structure';
    v_locked := COALESCE(v_draw->'locked', '[]'::jsonb);
    v_settle := public.fn_spin_settle_game(p_tournament_id, v_t.club_id,
      v_t.buy_in_amount, 3, v_multiplier, (v_manifest->>'rake_rate')::numeric);
    IF NOT COALESCE((v_settle->>'ok')::boolean, false)
       OR (v_settle->>'pool_covered')::numeric IS DISTINCT FROM v_prize
       OR COALESCE((v_settle->>'operator_shortfall')::numeric, 0) <> 0
       OR v_settle->>'reason' = 'already_settled' THEN
      -- Raising rolls back entry, draw and any transitive escrow write too.
      RAISE EXCEPTION 'Spin settlement does not prove the selected funded prize: %', v_settle
        USING ERRCODE = 'P0404';
    END IF;
  END IF;

  v_hash := encode(extensions.digest(v_manifest::text, 'sha256'), 'hex');
  v_receipt := v_settle || jsonb_build_object('ok', true, 'replay', false,
    'tournament_id', p_tournament_id, 'launch_id', p_launch_id,
    'multiplier', v_multiplier, 'prize_pool', v_prize, 'buy_in', v_t.buy_in_amount,
    'starting_chips', v_t.starting_chips, 'blind_structure', v_blinds,
    'payout_structure', v_payouts, 'locked', v_locked, 'entrants', v_entrants,
    'rule_manifest', v_manifest, 'rule_sha256', v_hash, 'rule_provenance', v_provenance,
    'draw_inputs', v_draw);
  INSERT INTO public.spin_draw_receipts(tournament_id, launch_id, lease_generation,
    rule_manifest, rule_sha256, entrants, receipt)
  VALUES (p_tournament_id, p_launch_id, p_lease_generation, v_manifest, v_hash, v_entrants, v_receipt);
  RETURN v_receipt;
END;
$$;


ALTER FUNCTION public.fn_spin_draw_and_settle_atomic(p_tournament_id uuid, p_launch_id uuid, p_lease_generation uuid, p_rule_manifest jsonb) OWNER TO postgres;

--
-- Name: fn_spin_draw_multiplier(uuid, numeric, jsonb, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_draw_multiplier(p_club_id uuid, p_buy_in numeric, p_tiers jsonb, p_rake_rate numeric DEFAULT 0.08, p_seats integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_bal numeric := 0; v_stake numeric := 0; v_contrib numeric := 0;
  v_eligible jsonb := '[]'::jsonb; v_tier jsonb;
  v_total numeric := 0; v_roll numeric; v_acc numeric := 0;
  v_pick numeric := NULL; v_locked jsonb := '[]'::jsonb;
  v_prize numeric; v_thr numeric; v_owner uuid;
  v_pending numeric := 0;
BEGIN
  v_owner := public.fn_spin_reserve_pool(p_club_id);

  -- FOR UPDATE: concurrent draws on the same pool serialize here (and with
  -- fn_spin_settle_game, which locks the same row), so two spins can no
  -- longer pass the affordability gate against the same chips.
  SELECT balance, GREATEST(highest_stake, COALESCE(p_buy_in,0))
    INTO v_bal, v_stake FROM public.spin_bonus_pools WHERE club_id = v_owner FOR UPDATE;

  -- Prizes already drawn against this pool but not yet settled: their spin
  -- rows carry a multiplier while no jackpot_draw ledger row exists yet.
  -- Bounded to 24h; anything older is the sweep's business, and the settle
  -- normally follows its draw within milliseconds.
  SELECT COALESCE(sum(round(t.buy_in_amount * t.spin_multiplier, 2)), 0)
    INTO v_pending
    FROM public.tournaments t
   WHERE t.variant = 'spin'
     AND t.spin_multiplier IS NOT NULL
     AND t.created_at > now() - interval '24 hours'
     AND t.status NOT IN ('COMPLETED','CANCELLED','CANCELED')
     AND public.fn_spin_reserve_pool(t.club_id) = v_owner
     AND NOT EXISTS (SELECT 1 FROM public.spin_reserve_ledger l
                     WHERE l.tournament_id = t.id AND l.kind = 'jackpot_draw');
  v_bal := v_bal - v_pending;

  v_contrib := round(COALESCE(p_buy_in,0) * COALESCE(p_seats,3)
                     * (1 - COALESCE(p_rake_rate,0.08)), 2);

  FOR v_tier IN SELECT * FROM jsonb_array_elements(p_tiers) LOOP
    v_prize := (v_tier->>'multiplier')::numeric * COALESCE(p_buy_in,0);
    v_thr   := COALESCE((v_tier->>'reserveThresholdX')::numeric, 0);

    IF (v_bal + v_contrib) < v_prize THEN
      v_locked := v_locked || jsonb_build_object(
        'multiplier', (v_tier->>'multiplier')::numeric,
        'reason', 'unaffordable',
        'unlocksAt', round(v_prize - v_contrib, 2));
    ELSIF v_thr > 0 AND v_bal < (v_tier->>'multiplier')::numeric * v_stake * v_thr THEN
      v_locked := v_locked || jsonb_build_object(
        'multiplier', (v_tier->>'multiplier')::numeric,
        'reason', 'threshold',
        'unlocksAt', round((v_tier->>'multiplier')::numeric * v_stake * v_thr, 2));
    ELSE
      v_eligible := v_eligible || v_tier;
      v_total := v_total + COALESCE((v_tier->>'freq')::numeric, 0);
    END IF;
  END LOOP;

  IF v_total <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_eligible_tiers',
      'reserve_balance', v_bal, 'locked', v_locked, 'owner_id', v_owner);
  END IF;

  v_roll := (('x' || encode(extensions.gen_random_bytes(6),'hex'))::bit(48)::bigint)::numeric
            / 281474976710656::numeric * v_total;

  FOR v_tier IN SELECT * FROM jsonb_array_elements(v_eligible) LOOP
    v_acc := v_acc + COALESCE((v_tier->>'freq')::numeric,0);
    IF v_roll < v_acc THEN v_pick := (v_tier->>'multiplier')::numeric; EXIT; END IF;
  END LOOP;
  IF v_pick IS NULL THEN
    v_pick := (v_eligible -> (jsonb_array_length(v_eligible)-1) ->> 'multiplier')::numeric;
  END IF;

  RETURN jsonb_build_object('ok', true, 'multiplier', v_pick,
    'reserve_balance', v_bal, 'highest_stake', v_stake,
    'contribution', v_contrib, 'locked', v_locked, 'owner_id', v_owner,
    'eligible_count', jsonb_array_length(v_eligible));
END; $$;


ALTER FUNCTION public.fn_spin_draw_multiplier(p_club_id uuid, p_buy_in numeric, p_tiers jsonb, p_rake_rate numeric, p_seats integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_draw_multiplier(p_club_id uuid, p_buy_in numeric, p_tiers jsonb, p_rake_rate numeric, p_seats integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_draw_multiplier(p_club_id uuid, p_buy_in numeric, p_tiers jsonb, p_rake_rate numeric, p_seats integer) IS 'Stage-1 rolling compatibility door for the live old engine. Retired and dropped only by the post-publish stage-2 Spin cleanup.';


--
-- Name: fn_spin_escrow_is_enforced(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_escrow_is_enforced() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.enforced THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tournaments t
     WHERE t.id = NEW.tournament_id
       AND (COALESCE(t.variant, '') = 'spin' OR COALESCE(t.is_premium_spin, false))
  ) THEN
    RETURN NEW;
  END IF;
  /* A row that opens SHORT stays tracked: fn_ca_escrow_apply can open an
     escrow at first sight from the shadow of an event already in flight, and
     an event broken before the escrow saw it must not have its next payment
     refused by a guard switched on afterwards. */
  IF COALESCE(NEW.prize_balance, 0)  < -0.005
     OR COALESCE(NEW.bounty_balance, 0) < -0.005
     OR COALESCE(NEW.fee_balance, 0)    < -0.005 THEN
    RETURN NEW;
  END IF;
  NEW.enforced := true;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_spin_escrow_is_enforced() OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_escrow_is_enforced(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_escrow_is_enforced() IS 'Spins were born tracked-not-enforced (fn_ca_escrow_apply opens them with enforced = NOT is_spin). After a soak showing zero would-refuse across every spin escrow row, they are born enforced - unless the row opens with a bank already negative, which stays tracked.';


--
-- Name: fn_spin_expire_unfilled(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_expire_unfilled(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_minutes integer;
  g record;
  v_result jsonb;
  v_expired integer:=0;
  v_failed integer:=0;
  v_refunded numeric:=0;
  v_ids jsonb:='[]'::jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'fn_spin_expire_unfilled requires service authority'
      USING ERRCODE='28000';
  END IF;
  SELECT unfilled_timeout_minutes INTO v_minutes
    FROM public.spin_fill_policy LIMIT 1;
  v_minutes:=COALESCE(v_minutes,30);
  IF v_minutes<=0 THEN
    RETURN jsonb_build_object('ok',true,'disabled',true,'expired',0);
  END IF;
  FOR g IN
    SELECT t.id
      FROM public.tournaments t
     WHERE t.variant='spin'
       AND t.status IN ('REGISTERING','ANNOUNCED')
       AND t.started_at IS NULL
       AND EXISTS (
         SELECT 1 FROM public.table_seats s
         JOIN public.tables tb ON tb.id=s.table_id
          WHERE tb.tournament_id=t.id AND s.left_at IS NULL
            AND s.joined_at<now()-make_interval(mins=>v_minutes))
       AND (SELECT count(*) FROM public.table_seats s
             JOIN public.tables tb ON tb.id=s.table_id
            WHERE tb.tournament_id=t.id AND s.left_at IS NULL)
           <COALESCE(t.max_players,3)
     ORDER BY t.created_at
     LIMIT GREATEST(COALESCE(p_limit,50),1)
  LOOP
    BEGIN
      v_result:=public.atomic_cancel_tournament(g.id,NULL);
      IF COALESCE((v_result->>'success')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'atomic cancellation returned no success receipt';
      END IF;
      v_expired:=v_expired+1;
      v_refunded:=v_refunded+
        COALESCE((v_result->>'total_refunded')::numeric,0);
      v_ids:=v_ids||to_jsonb(g.id::text);
    EXCEPTION WHEN OTHERS THEN
      v_failed:=v_failed+1;
      RAISE WARNING 'fn_spin_expire_unfilled: could not cancel %: %',g.id,SQLERRM;
    END;
  END LOOP;
  RETURN jsonb_build_object(
    'ok',v_failed=0,'expired',v_expired,'failed',v_failed,
    'chips_refunded',round(v_refunded,2),'timeout_minutes',v_minutes,
    'tournament_ids',v_ids);
END;
$$;


ALTER FUNCTION public.fn_spin_expire_unfilled(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_expire_unfilled(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_expire_unfilled(p_limit integer) IS 'Cancels and refunds Spins whose seats have waited past spin_fill_policy. Idempotent, horse-inclusive, never cancels a full-but-unstarted game.';


--
-- Name: fn_spin_fairness_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_fairness_check(p_since_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_days      integer := GREATEST(COALESCE(p_since_days, 7), 1);
  v_since     timestamptz := now() - make_interval(days => v_days);

  v_n         numeric := 0;
  v_counts    jsonb   := '{}'::jsonb;
  v_off       bigint  := 0;
  v_off_list  jsonb   := '[]'::jsonb;
  v_locked    bigint  := 0;

  v_chi       numeric := 0;
  v_df        integer := 0;
  v_pooled    integer := 0;
  v_crit_01   numeric;
  v_crit_001  numeric;
  v_spec_freq numeric;

  v_ev_spec   numeric;
  v_sd_spec   numeric;
  v_ev_actual numeric;
  v_z         numeric := 0;

  v_verdict   text := 'pass';
  v_severity  text;
  v_message   text;
  v_context   jsonb;
  v_alerts    integer := 0;

  v_cell      record;
  v_acc_e     numeric := 0;
  v_acc_a     numeric := 0;
  v_cells     integer := 0;
BEGIN
  -- Population: variant and nothing else. No is_horse filter (CLAUDE.md 10.5)
  -- -- horses are most of the volume, and excluding them would leave this
  -- measuring a few hundred draws a week.
  SELECT COALESCE(count(*), 0), COALESCE(avg(m), 0)
    INTO v_n, v_ev_actual
    FROM (SELECT t.spin_multiplier::integer AS m
            FROM public.tournaments t
           WHERE t.variant = 'spin'
             AND t.spin_multiplier IS NOT NULL
             AND t.spin_multiplier > 0
             AND t.created_at >= v_since) d;

  SELECT COALESCE(jsonb_object_agg(m::text, c), '{}'::jsonb)
    INTO v_counts
    FROM (SELECT t.spin_multiplier::integer AS m, count(*) AS c
            FROM public.tournaments t
           WHERE t.variant = 'spin'
             AND t.spin_multiplier IS NOT NULL
             AND t.spin_multiplier > 0
             AND t.created_at >= v_since
           GROUP BY 1) d;

  -- Check 1: off-ladder multipliers. Zero tolerance, any volume.
  SELECT COALESCE(sum((kv.value)::text::bigint), 0),
         COALESCE(jsonb_agg(kv.key::integer ORDER BY kv.key::integer), '[]'::jsonb)
    INTO v_off, v_off_list
    FROM jsonb_each(v_counts) kv
   WHERE NOT EXISTS (SELECT 1 FROM public.spin_tier_spec s
                      WHERE s.multiplier = kv.key::integer);

  -- Check 4: did any draw run with a tier locked out?
  SELECT count(*)
    INTO v_locked
    FROM public.tournaments t
   WHERE t.variant = 'spin'
     AND t.created_at >= v_since
     AND t.spin_locked_tiers IS NOT NULL
     AND jsonb_typeof(t.spin_locked_tiers) = 'array'
     AND jsonb_array_length(t.spin_locked_tiers) > 0;

  IF v_n >= 2000 THEN
    SELECT sum(s.freq),
           sum(s.multiplier::numeric * s.freq) / sum(s.freq),
           sqrt(sum((s.multiplier::numeric ^ 2) * s.freq) / sum(s.freq)
                - (sum(s.multiplier::numeric * s.freq) / sum(s.freq)) ^ 2)
      INTO v_spec_freq, v_ev_spec, v_sd_spec
      FROM public.spin_tier_spec s;

    -- Check 3: the house edge, on its own terms. A distribution can pass a
    -- chi-square and still drift the edge if the error concentrates in the
    -- tail, which is where the money is.
    v_z := (v_ev_actual - v_ev_spec) / (v_sd_spec / sqrt(v_n));

    -- Check 2: Pearson chi-square, rare tail pooled. At a week of current
    -- volume 50x and 100x each expect ~2.5 draws, and a cell with expected
    -- under 5 does not follow the chi-square distribution -- it would page
    -- somebody because one player got paid.
    FOR v_cell IN
      SELECT s.multiplier,
             v_n * s.freq / v_spec_freq                              AS e,
             COALESCE((v_counts ->> s.multiplier::text)::numeric, 0)  AS a
        FROM public.spin_tier_spec s
       ORDER BY s.multiplier DESC
    LOOP
      v_acc_e := v_acc_e + v_cell.e;
      v_acc_a := v_acc_a + v_cell.a;

      IF v_acc_e >= 5 THEN
        v_chi   := v_chi + (v_acc_a - v_acc_e) ^ 2 / v_acc_e;
        v_cells := v_cells + 1;
        IF v_acc_e > v_cell.e THEN
          v_pooled := v_pooled + 1;
        END IF;
        v_acc_e := 0;
        v_acc_a := 0;
      END IF;
    END LOOP;

    IF v_acc_e > 0 AND v_cells > 0 THEN
      v_chi := v_chi + (v_acc_a - v_acc_e) ^ 2 / v_acc_e;
    END IF;

    v_df := GREATEST(v_cells - 1, 1);

    -- Upper-tail critical values. Postgres has no chi-square CDF and this
    -- needs no more than a lookup: 8 tiers, so df cannot exceed 7.
    v_crit_01  := (ARRAY[6.635, 9.210, 11.345, 13.277, 15.086,
                         16.812, 18.475, 20.090])[LEAST(v_df, 8)];
    v_crit_001 := (ARRAY[10.828, 13.816, 16.266, 18.467, 20.515,
                         22.458, 24.322, 26.125])[LEAST(v_df, 8)];
  END IF;

  IF v_off > 0 THEN
    v_verdict  := 'off_ladder';
    v_severity := 'critical';
    v_message  := format(
      'Spin dealt %s draw(s) at multipliers that are not on the published '
      'ladder (%s). The engine and spin_tier_spec disagree about what game '
      'this is.', v_off, v_off_list::text);

  ELSIF v_n >= 2000 AND v_chi > v_crit_001 THEN
    v_verdict  := 'distribution_critical';
    v_severity := 'critical';
    v_message  := format(
      'Spin draw distribution does not match the published ladder: '
      'chi-square %s on %s df over %s draws (p < 0.001).',
      round(v_chi, 2), v_df, v_n::bigint);

  ELSIF v_n >= 2000 AND abs(v_z) > 4 THEN
    v_verdict  := 'expectation_drift';
    v_severity := 'critical';
    v_message  := format(
      'Spin expected multiplier has drifted to %s against a published %s '
      '(z = %s over %s draws) -- the house edge is not what the player was told.',
      round(v_ev_actual, 4), round(v_ev_spec, 4), round(v_z, 2), v_n::bigint);

  ELSIF v_locked > 0 THEN
    v_verdict  := 'tiers_locked';
    v_severity := 'warning';
    v_message  := format(
      '%s Spin(s) drew from a reduced ladder in the last %s day(s). The odds '
      'sheet shown at buy-in advertises the full ladder with no availability '
      'qualification.', v_locked, v_days);

  ELSIF v_n >= 2000 AND v_chi > v_crit_01 THEN
    v_verdict  := 'distribution_warning';
    v_severity := 'warning';
    v_message  := format(
      'Spin draw distribution is drifting from the published ladder: '
      'chi-square %s on %s df over %s draws (p < 0.01).',
      round(v_chi, 2), v_df, v_n::bigint);

  ELSIF v_n < 2000 THEN
    v_verdict := 'insufficient_volume';
  END IF;

  v_context := jsonb_build_object(
    'window_days',      v_days,
    'draws',            v_n::bigint,
    'off_ladder',       v_off,
    'off_ladder_mults', v_off_list,
    'locked_draws',     v_locked,
    'chi_square',       round(v_chi, 4),
    'degrees_freedom',  v_df,
    'pooled_cells',     v_pooled,
    'crit_p01',         v_crit_01,
    'crit_p001',        v_crit_001,
    'ev_actual',        round(COALESCE(v_ev_actual, 0), 6),
    'ev_spec',          round(COALESCE(v_ev_spec, 0), 6),
    'z',                round(v_z, 4),
    'verdict',          v_verdict,
    'detail',           'no money was moved by this check; see '
                        'v_spin_draw_distribution_7d for the per-tier counts');

  -- One open alert per verdict at a time: the window slides hourly, so
  -- re-raising an unresolved condition would bury the alert list in a day.
  IF v_severity IS NOT NULL THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT v_severity, 'fn_spin_fairness_check', v_message, v_context
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'fn_spin_fairness_check'
          AND fa.resolved IS NOT TRUE
          AND fa.context->>'verdict' = v_verdict);
    IF FOUND THEN v_alerts := 1; END IF;
  END IF;

  RETURN v_context || jsonb_build_object('ok', true, 'alerts_raised', v_alerts);
END;
$$;


ALTER FUNCTION public.fn_spin_fairness_check(p_since_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_fairness_check(p_since_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_fairness_check(p_since_days integer) IS 'Audits the live Spin draw against the published ladder: off-ladder multipliers, chi-square of the tier distribution, z-test of the expected multiplier, and whether any draw ran with a tier locked out. Raises into financial_alerts, moves no money. Counts horses (CLAUDE.md 10.5).';


--
-- Name: fn_spin_ladder_drift_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_ladder_drift_check(p_since_days integer DEFAULT 7) RETURNS TABLE(tournament_id uuid, multiplier numeric, expected jsonb, actual jsonb, ended_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT t.id, t.spin_multiplier, l.structure,
         NULLIF(btrim(COALESCE(t.payout_structure,'')),'')::jsonb,
         t.ended_at
    FROM public.tournaments t
    JOIN public.spin_payout_ladder l ON l.multiplier = t.spin_multiplier
   WHERE upper(COALESCE(t.tournament_type,'')) = 'SPIN'
     AND t.created_at > now() - make_interval(days => p_since_days)
     AND NULLIF(btrim(COALESCE(t.payout_structure,'')),'')::jsonb IS DISTINCT FROM l.structure
   ORDER BY t.ended_at DESC NULLS LAST;
$$;


ALTER FUNCTION public.fn_spin_ladder_drift_check(p_since_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_ladder_drift_check(p_since_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_ladder_drift_check(p_since_days integer) IS 'Spins whose payout ladder does not match the one their multiplier owes. Should be empty once zzz_spin_ladder_is_the_drawn_one is attached; a non-empty result means something writes the column by a path that bypasses the trigger.';


--
-- Name: fn_spin_ladder_is_the_drawn_one(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_ladder_is_the_drawn_one() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_expected jsonb;
  v_actual   jsonb;
  v_booked jsonb;
BEGIN
  SELECT r.receipt INTO v_booked FROM public.spin_draw_receipts r
   WHERE r.tournament_id=NEW.id;
  IF v_booked IS NOT NULL THEN
    IF NEW.variant IS DISTINCT FROM 'spin'
       OR NEW.buy_in_amount IS DISTINCT FROM (v_booked->>'buy_in')::numeric
       OR NEW.starting_chips IS DISTINCT FROM (v_booked->>'starting_chips')::int THEN
      RAISE EXCEPTION 'A booked Spin keeps its funded entry and board contract' USING ERRCODE='23514';
    END IF;
    -- Do not project the secret before the engine's reveal. Once projected,
    -- clearing or replacing that result cannot detach it from its receipt.
    IF NEW.spin_multiplier IS NULL AND TG_OP='UPDATE' AND OLD.spin_multiplier IS NULL THEN
      RETURN NEW;
    END IF;
    IF NEW.spin_multiplier IS DISTINCT FROM (v_booked->>'multiplier')::numeric THEN
      RAISE EXCEPTION 'A booked Spin keeps its original multiplier' USING ERRCODE='23514';
    END IF;
    v_expected := v_booked->'payout_structure';
    NEW.blind_structure := (v_booked->'blind_structure')::text;
  ELSIF COALESCE(NEW.variant,'') <> 'spin'
     AND upper(COALESCE(NEW.tournament_type,'')) <> 'SPIN' THEN
    RETURN NEW;
  END IF;

  -- Before the wheel is drawn there is no ladder to enforce.
  IF NEW.spin_multiplier IS NULL THEN
    RETURN NEW;
  END IF;

  IF v_booked IS NULL THEN
    SELECT structure INTO v_expected
      FROM public.spin_payout_ladder WHERE multiplier = NEW.spin_multiplier;
  END IF;

  -- An unknown multiplier is a real question, not something to guess at.
  IF v_expected IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_actual := NULLIF(btrim(COALESCE(NEW.payout_structure,'')), '')::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_actual := NULL;
  END;

  IF v_actual IS NOT DISTINCT FROM v_expected THEN
    RETURN NEW;
  END IF;

  NEW.payout_structure := v_expected::text;

  BEGIN
    PERFORM public.fn_raise_server_financial_alert(
      'critical',
      'fn_spin_ladder_is_the_drawn_one',
      format('Spin %s (%sx) had its payout ladder overwritten with %s; the drawn ladder %s was restored before it could underpay anyone.',
             COALESCE(NEW.name, NEW.id::text), NEW.spin_multiplier,
             COALESCE(v_actual::text,'(unreadable)'), v_expected::text),
      jsonb_build_object('kind','spin_ladder_overwritten',
                         'tournament_id', NEW.id,
                         'multiplier', NEW.spin_multiplier,
                         'was', v_actual,
                         'restored_to', v_expected),
      NEW.id::text);
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- the correction matters more than the alarm
  END;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_spin_ladder_is_the_drawn_one() OWNER TO postgres;

--
-- Name: fn_spin_leaderboards(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_leaderboards(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with win as (
    select greatest(coalesce(p_days, 7), 1) as days
  ),
  spins as (
    select t.id                                        as tournament_id,
           coalesce(nullif(tp.username, ''), 'Player') as username,
           coalesce(t.spin_multiplier, 0)              as multiplier,
           coalesce(t.buy_in_amount, 0)                as buy_in,
           coalesce(tp.prize, 0)                       as prize,
           t.ended_at
      from public.tournaments t
      join public.tournament_players tp on tp.tournament_id = t.id
     cross join win
     where t.variant = 'spin'
       and t.status = 'COMPLETED'
       and t.ended_at is not null
       and t.ended_at >= now() - make_interval(days => win.days)
       and tp.user_id is not null
  ),
  /* One paid seat per spin: the largest payout, which is first place. */
  winner_seat as (
    select distinct on (s.tournament_id)
           s.tournament_id, s.username, s.multiplier, s.buy_in, s.prize, s.ended_at
      from spins s
     where s.prize > 0
     order by s.tournament_id, s.prize desc
  ),
  biggest as (
    select w.username, w.multiplier, w.buy_in, w.prize, w.ended_at
      from winner_seat w
     order by w.multiplier desc, w.prize desc, w.ended_at desc
     limit 10
  ),
  most as (
    select s.username, count(*) as spins
      from spins s
     group by s.username
     order by count(*) desc
     limit 10
  ),
  net as (
    select s.username,
           round(sum(s.prize) - sum(s.buy_in), 2) as net,
           count(*)                               as spins
      from spins s
     group by s.username
    having round(sum(s.prize) - sum(s.buy_in), 2) > 0
     order by round(sum(s.prize) - sum(s.buy_in), 2) desc
     limit 10
  )
  select jsonb_build_object(
    'ok', true,
    'days', (select days from win),
    'biggest_hits',
      coalesce((select jsonb_agg(to_jsonb(b) order by b.multiplier desc, b.prize desc, b.ended_at desc)
                  from biggest b), '[]'::jsonb),
    'most_spins',
      coalesce((select jsonb_agg(to_jsonb(m) order by m.spins desc) from most m), '[]'::jsonb),
    'best_net',
      coalesce((select jsonb_agg(to_jsonb(n) order by n.net desc) from net n), '[]'::jsonb)
  );
$$;


ALTER FUNCTION public.fn_spin_leaderboards(p_days integer) OWNER TO postgres;

--
-- Name: fn_spin_metrics(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_metrics(p_lag_window_minutes integer DEFAULT 60) RETURNS TABLE(reveal_spins bigint, reveal_p50_ms numeric, reveal_p90_ms numeric, reveal_p99_ms numeric, reveal_worst_ms integer, reveal_past_lead_in bigint, fairness_draws bigint, fairness_realised_e numeric, fairness_spec_e numeric, fairness_z numeric, fairness_drift boolean, fairness_constrained bigint, attribution_gaps bigint, unpaid_settlements bigint, booking_gaps bigint, unbooked_spins bigint, seconds_since_last_start numeric, open_boards bigint, unfilled_waits bigint, reserve_thin_clubs bigint, reserve_min_balance numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with lag as (
    select
      count(*)::bigint as spins,
      round(percentile_cont(0.5) within group (order by spin_reveal_lag_ms::float8)::numeric) as p50,
      round(percentile_cont(0.9) within group (order by spin_reveal_lag_ms::float8)::numeric) as p90,
      round(percentile_cont(0.99) within group (order by spin_reveal_lag_ms::float8)::numeric) as p99,
      max(spin_reveal_lag_ms) as worst,
      count(*) filter (where spin_reveal_lag_ms > 1000)::bigint as past_lead_in
    from public.tournaments
    where variant = 'spin'
      and spin_reveal_lag_ms is not null
      and started_at > now() - (greatest(p_lag_window_minutes, 1) || ' minutes')::interval
  ),
  fair as (
    select draws, realised_e, spec_e, z, drift, constrained_draws
    from public.v_spin_draw_fairness
    where window_label = '24h'
  ),
  res as (
    select
      count(*) filter (where is_thin)::bigint as thin_clubs,
      min(balance) as min_balance
    from public.v_spin_reserve_health
  ),
  bg as (
    select count(*)::bigint as n
    from public.tournaments t
    where t.variant = 'spin'
      and t.spin_multiplier is not null
      and t.ended_at > now() - interval '24 hours'
      and exists (
        select 1
        from (
          select sum(-l.amount) as drawn
          from public.spin_reserve_ledger l
          where l.tournament_id = t.id and l.kind = 'jackpot_draw'
        ) d,
        (
          select sum(w.amount) as paid
          from public.wallet_transactions w
          where w.related_entity_id = t.id and w.type = 'credit' and w.category = 'prize'
        ) p
        where d.drawn is not null
          and p.paid is not null
          and p.paid > d.drawn
          and p.paid = round(t.buy_in_amount * t.spin_multiplier, 2)
      )
  ),
  ub as (
    select count(*)::bigint as n
    from public.tournaments t
    where t.variant = 'spin'
      and t.status in ('RUNNING','COMPLETED')
      and coalesce(t.buy_in_fee, 0) = 0
      and coalesce(t.spin_multiplier, 0) > 0
      and t.club_id is not null
      and t.started_at > now() - interval '24 hours'
      and exists (select 1 from public.tournament_players tp
                   where tp.tournament_id = t.id)
      and not exists (select 1 from public.spin_reserve_ledger l
                       where l.tournament_id = t.id)
  ),
  /* LIVENESS. Not "are the running games healthy" - "is the fleet producing
     games at all". The 2026-09-01 outage was invisible to every other number
     here because they all measure games that exist. */
  live as (
    select
      round(extract(epoch from now() - max(t.started_at)))::numeric as secs_since_start
    from public.tournaments t
    where t.variant = 'spin'
  ),
  boards as (
    select count(*)::bigint as n
    from public.tournaments t
    where t.variant = 'spin' and t.status = 'REGISTERING'
  ),
  up as (
    select count(*)::bigint as n
    from public.fn_spin_unpaid_settlements(24)
    where chips_short > 0.01
  )
  select
    coalesce(lag.spins, 0),
    lag.p50, lag.p90, lag.p99, lag.worst,
    coalesce(lag.past_lead_in, 0),
    coalesce(fair.draws, 0),
    fair.realised_e,
    fair.spec_e,
    fair.z,
    coalesce(fair.drift, false),
    coalesce(fair.constrained_draws, 0),
    (select count(*)::bigint from public.v_tournament_rake_attribution_gaps),
    up.n,
    bg.n,
    ub.n,
    live.secs_since_start,
    boards.n,
    (select count(*)::bigint from public.v_spin_unfilled_waits),
    coalesce(res.thin_clubs, 0),
    res.min_balance
  from lag
  cross join res
  cross join bg
  cross join ub
  cross join up
  cross join live
  cross join boards
  left join fair on true;
$$;


ALTER FUNCTION public.fn_spin_metrics(p_lag_window_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_metrics(p_lag_window_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_metrics(p_lag_window_minutes integer) IS 'One row of Spin telemetry for the engine scrape. seconds_since_last_start and open_boards exist because on 2026-09-01 every tournament INSERT failed for four hours and every other number here stayed green: they all measure the games that exist, and none could see that no game could be created.';


--
-- Name: fn_spin_move_owner_wallet(uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_move_owner_wallet(p_owner_id uuid, p_owner_kind text, p_wallet text, p_delta numeric) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v_after numeric;
BEGIN
  /* ZERO-DRIFT phase 6: declare the ledger identity of the spin margin flow.
     Positive delta = spin margin landing with the owner (rake, from the spin
     reserve); negative delta = the owner funding the spin pool (overlay). */
  PERFORM public.fn_ca_declare_ledger(
    CASE WHEN p_delta >= 0 THEN 'rake' ELSE 'overlay' END, 'spin_reserve');

  IF p_owner_kind = 'union' THEN
    IF p_wallet NOT IN ('chip_balance','promo_wallet','rake_wallet','spin_reserve_wallet') THEN
      RAISE EXCEPTION 'unknown union wallet %', p_wallet;
    END IF;
    EXECUTE format(
      'UPDATE public.union_wallets SET %I = %I + $1, updated_at = now()
        WHERE union_id = $2 AND %I + $1 >= 0 RETURNING %I',
      p_wallet, p_wallet, p_wallet, p_wallet)
      INTO v_after USING p_delta, p_owner_id;
  ELSE
    IF p_wallet NOT IN ('chip_treasury','promo_balance') THEN
      RAISE EXCEPTION 'unknown club wallet %', p_wallet;
    END IF;
    EXECUTE format(
      'UPDATE public.clubs SET %I = COALESCE(%I,0) + $1
        WHERE id = $2 AND COALESCE(%I,0) + $1 >= 0 RETURNING %I',
      p_wallet, p_wallet, p_wallet, p_wallet)
      INTO v_after USING p_delta, p_owner_id;
  END IF;
  RETURN v_after;
END;
$_$;


ALTER FUNCTION public.fn_spin_move_owner_wallet(p_owner_id uuid, p_owner_kind text, p_wallet text, p_delta numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_move_owner_wallet(p_owner_id uuid, p_owner_kind text, p_wallet text, p_delta numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_move_owner_wallet(p_owner_id uuid, p_owner_kind text, p_wallet text, p_delta numeric) IS 'Signed move against a wallet the Spin pool owner holds: union_wallets for a union, clubs for a club. Returns NULL if the wallet is missing or the move would overdraw it. The column allow-list is what stops this being an arbitrary-column write primitive.';


