CREATE FUNCTION public.fn_spin_pool_follows_union_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.union_id IS NOT NULL AND OLD.union_id IS DISTINCT FROM NEW.union_id THEN
    PERFORM public.fn_close_club_wallets_on_union_join(NEW.id, NEW.union_id);
  END IF;
  RETURN NEW;
END;
$$;


