-- Name: fn_spin_rake_rate(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_rake_rate(p_buy_in numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  -- ONE rate at every stake. The multiplier table is what actually charges
  -- the rake, and its expectation (2.7638 over 3 seats) is 8% and no other
  -- number. See src/config/spinSpec.ts "THE BANDS ARE GONE".
  SELECT 0.08;
$$;


ALTER FUNCTION public.fn_spin_rake_rate(p_buy_in numeric) OWNER TO postgres;

--
-- Name: fn_spin_repair_missing_multiplier(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_repair_missing_multiplier(p_lookback_mins integer DEFAULT 1440) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  -- MIRRORS server/src/config/spinSpec.ts SPIN_TIERS. Pinned by
  -- tests/config/spinNullMultiplierRepair.test.ts.
  v_tiers    numeric[] := ARRAY[2, 3, 4, 5, 10, 25, 50, 100];
  v_t        record;
  v_ratio    numeric;
  v_witness  numeric;
  v_use      numeric;
  v_source   text;
  v_overpaid numeric;
  v_hit      integer;
  v_fixed    integer := 0;
  v_flag     integer := 0;
  v_over     integer := 0;
  v_aged     integer := 0;
  v_raced    integer := 0;
BEGIN
  FOR v_t IN
    SELECT t.id, t.name, t.club_id, t.prize_pool, t.buy_in_amount,
           t.started_at, t.created_at,
           d.multiplier AS witness,
           (COALESCE(t.started_at, t.created_at)
              <= now() - make_interval(mins => GREATEST(p_lookback_mins, 1))) AS outside_window
      FROM public.tournaments t
      LEFT JOIN LATERAL (
        SELECT l.multiplier
          FROM public.spin_reserve_ledger l
         WHERE l.tournament_id = t.id
           AND l.kind = 'jackpot_draw'
           AND COALESCE(l.multiplier, 0) > 0
         ORDER BY l.created_at ASC
         LIMIT 1) d ON true
     WHERE t.variant = 'spin'
       AND t.status IN ('RUNNING', 'COMPLETED')
       AND COALESCE(t.spin_multiplier, 0) <= 0
       -- A spin that never stamped a start is the spin MOST likely to have
       -- lost its draw. Gating on a bare started_at hid exactly the rows this
       -- function exists to repair, for four days.
       AND COALESCE(t.started_at, t.created_at) IS NOT NULL
       AND (
         COALESCE(t.started_at, t.created_at)
           > now() - make_interval(mins => GREATEST(p_lookback_mins, 1))
         -- AT ANY AGE when the reserve ledger already booked a draw: such a row
         -- is broken by definition and the window must not bound it.
         -- Self-draining, so it cannot become an unbounded scan.
         OR d.multiplier IS NOT NULL
       )
  LOOP
    v_witness := v_t.witness;
    IF v_t.outside_window THEN
      v_aged := v_aged + 1;
    END IF;

    v_ratio := NULL;
    IF COALESCE(v_t.buy_in_amount, 0) > 0 AND COALESCE(v_t.prize_pool, 0) > 0 THEN
      v_ratio := round(v_t.prize_pool / v_t.buy_in_amount, 4);
    END IF;

    -- THE WITNESS FIRST. fn_spin_settle_game stamps the multiplier it drew on
    -- the jackpot_draw row at the instant of the draw. The pool ratio equals it
    -- only once the draw has been applied to the pool, which on a spin that
    -- lost its stamp it has not been.
    IF v_witness IS NOT NULL AND v_witness = ANY (v_tiers) THEN
      v_use := v_witness; v_source := 'spin_reserve_ledger.jackpot_draw';
    ELSIF v_ratio IS NOT NULL AND v_ratio = ANY (v_tiers) THEN
      v_use := v_ratio;   v_source := 'prize_pool / buy_in_amount';
    ELSE
      v_use := NULL;      v_source := NULL;
    END IF;

    IF v_use IS NOT NULL THEN
      UPDATE public.tournaments
         SET spin_multiplier  = v_use,
             is_premium_spin  = (v_use >= 100)
       WHERE id = v_t.id
         AND COALESCE(spin_multiplier, 0) <= 0;
      -- A GUARDED UPDATE THAT MATCHES NOTHING IS NOT A REPAIR. Two crons drive
      -- this function under different advisory locks, so the row can be stamped
      -- between the SELECT and here. Counting that as a fix - and filing an
      -- alert for it - is a lie about work that another pass did.
      GET DIAGNOSTICS v_hit = ROW_COUNT;
      IF v_hit = 0 THEN
        v_raced := v_raced + 1;
        CONTINUE;
      END IF;
      v_fixed := v_fixed + 1;

      -- The pool that was PAID, against the draw that was made. A positive gap
      -- is money already in a player's wallet: 10.9 rule 3 keeps it there and
      -- requires it to be reported rather than reversed.
      v_overpaid := round(COALESCE(v_t.prize_pool, 0) - (v_use * COALESCE(v_t.buy_in_amount, 0)), 2);
      IF v_overpaid > 0 THEN
        v_over := v_over + 1;
      END IF;

      INSERT INTO public.financial_alerts (severity, source, message, context)
      VALUES (CASE WHEN v_overpaid > 0 THEN 'warning' ELSE 'info' END,
              'fn_spin_repair_missing_multiplier',
              CASE WHEN v_overpaid > 0
                   THEN 'Spin lost its draw stamp; multiplier restored from the reserve ledger, and '
                        || v_overpaid || ' paid over the draw is absorbed by the house (10.9 rule 3): '
                        || COALESCE(v_t.name, v_t.id::text)
                   ELSE 'Spin lost its draw stamp; multiplier restored from the reserve ledger: '
                        || COALESCE(v_t.name, v_t.id::text) END,
              jsonb_build_object('tournament_id', v_t.id, 'club_id', v_t.club_id,
                                 'buy_in', v_t.buy_in_amount, 'prize_pool', v_t.prize_pool,
                                 'reconstructed_multiplier', v_use,
                                 'reconstructed_from', v_source,
                                 'ledger_witness_multiplier', v_witness,
                                 'pool_ratio', v_ratio,
                                 'paid_over_drawn', v_overpaid,
                                 'clawed_back', false,
                                 'outside_lookback_window', v_t.outside_window,
                                 'started_at', v_t.started_at,
                                 'created_at', v_t.created_at));
    ELSE
      v_flag := v_flag + 1;
      INSERT INTO public.financial_alerts (severity, source, message, context)
      SELECT 'critical', 'fn_spin_repair_missing_multiplier',
             'Spin ran without a draw and the multiplier cannot be reconstructed: '
               || COALESCE(v_t.name, v_t.id::text),
             jsonb_build_object('tournament_id', v_t.id, 'club_id', v_t.club_id,
                                'buy_in', v_t.buy_in_amount, 'prize_pool', v_t.prize_pool,
                                'implied_ratio', v_ratio,
                                'ledger_witness_multiplier', v_witness,
                                'started_at', v_t.started_at, 'created_at', v_t.created_at,
                                'detail', 'needs a human decision; no multiplier was invented')
       WHERE NOT EXISTS (
         SELECT 1 FROM public.financial_alerts
          WHERE source = 'fn_spin_repair_missing_multiplier'
            AND resolved IS NOT TRUE
            AND context->>'tournament_id' = v_t.id::text);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'repaired', v_fixed,
                            'unreconstructable', v_flag,
                            'paid_over_drawn_count', v_over,
                            'repaired_outside_window', v_aged,
                            'lost_the_race', v_raced,
                            'lookback_mins', p_lookback_mins);
END;
$$;


ALTER FUNCTION public.fn_spin_repair_missing_multiplier(p_lookback_mins integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_repair_missing_multiplier(p_lookback_mins integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_repair_missing_multiplier(p_lookback_mins integer) IS 'Restores spin_multiplier on a spin that completed without stamping its draw. Reads the jackpot_draw row in spin_reserve_ledger first (the witness to the draw) and falls back to prize_pool/buy_in only when there is none. A spin with a booked draw and no stamp is in scope at ANY age - the lookback only bounds the ratio fallback. Never claws back a prize already paid.';


--
-- Name: fn_spin_required_seed(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_required_seed(p_offered_max_stake numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT round(GREATEST(COALESCE(p_offered_max_stake, 0), 0) * 100 * 2, 2);
$$;


ALTER FUNCTION public.fn_spin_required_seed(p_offered_max_stake numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_required_seed(p_offered_max_stake numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_required_seed(p_offered_max_stake numeric) IS 'Seed an owner must put up to offer Spins: two top-tier (100x) jackpots at their largest offered stake. Mirrors requiredSeed() in src/config/spinSpec.ts.';


--
-- Name: fn_spin_reserve_owner(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_reserve_owner(p_club_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (SELECT c.union_id FROM public.clubs c WHERE c.id = p_club_id),
    p_club_id
  );
$$;


ALTER FUNCTION public.fn_spin_reserve_owner(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_reserve_owner(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_reserve_owner(p_club_id uuid) IS 'Resolves a playing club to the entity whose Spin reserve pool funds its prizes: the union if affiliated, otherwise the club itself. Added 2026-08-22 - the reserve is a union-level pool per Dan, and clubs only hold their own when standalone.';


--
-- Name: fn_spin_reserve_pool(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_reserve_pool(p_club_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_owner uuid;
BEGIN
  v_owner := public.fn_spin_reserve_owner(p_club_id);

  INSERT INTO public.spin_bonus_pools (club_id, owner_kind)
  VALUES (v_owner,
          CASE WHEN EXISTS (SELECT 1 FROM public.unions u WHERE u.id = v_owner)
               THEN 'union' ELSE 'club' END)
  ON CONFLICT (club_id) DO NOTHING;

  RETURN v_owner;
END; $$;


ALTER FUNCTION public.fn_spin_reserve_pool(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_spin_reserve_receipt_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_reserve_receipt_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.kind IN (
       'contribution','jackpot_draw','draw_reversal',
       'contribution_reversal') THEN
    RAISE EXCEPTION 'Spin reserve receipt % (%) is immutable',OLD.id,OLD.kind
      USING ERRCODE = '55000';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.fn_spin_reserve_receipt_is_immutable() OWNER TO postgres;

--
-- Name: fn_spin_reserve_row_requires_exact_journal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_reserve_row_requires_exact_journal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pool_id uuid;
  v_count integer;
  v_key text;
  v_category text;
  v_from_type text;
  v_from_id uuid;
  v_to_type text;
  v_to_id uuid;
  v_original public.spin_reserve_ledger%ROWTYPE;
BEGIN
  IF NEW.tournament_id IS NULL
     OR NEW.kind NOT IN (
       'contribution','jackpot_draw','draw_reversal',
       'contribution_reversal') THEN
    RETURN NEW;
  END IF;
  IF NEW.amount IS NULL
     OR NEW.amount::text IN ('NaN','Infinity','-Infinity')
     OR NEW.amount IS DISTINCT FROM round(NEW.amount,2)
     OR NEW.balance_after IS NULL
     OR NEW.balance_after::text IN ('NaN','Infinity','-Infinity')
     OR NEW.balance_after IS DISTINCT FROM round(NEW.balance_after,2) THEN
    RAISE EXCEPTION 'Spin reserve evidence has invalid money'
      USING ERRCODE = '23514';
  END IF;
  SELECT p.id INTO v_pool_id FROM public.spin_bonus_pools p
   WHERE p.club_id = NEW.club_id;
  IF v_pool_id IS NULL THEN
    RAISE EXCEPTION 'Spin reserve row has no pool for owner %',NEW.club_id
      USING ERRCODE = 'P0404';
  END IF;

  IF NEW.kind IN ('contribution','jackpot_draw') THEN
    IF NEW.buy_in IS NULL OR NEW.buy_in <= 0
       OR NEW.seats IS DISTINCT FROM 3
       OR (NEW.kind = 'contribution' AND (
            NEW.amount <= 0 OR NEW.house_rake IS NULL OR NEW.house_rake < 0
            OR NEW.amount IS DISTINCT FROM
                 round(NEW.buy_in*3-NEW.house_rake,2)))
       OR (NEW.kind = 'jackpot_draw' AND (
            NEW.amount >= 0 OR NEW.multiplier IS NULL OR NEW.multiplier <= 0
            OR round(-NEW.amount,2) IS DISTINCT FROM
                 round(NEW.buy_in*NEW.multiplier,2))) THEN
      RAISE EXCEPTION 'Spin % violates its exact funded contract',NEW.kind
        USING ERRCODE = '23514';
    END IF;
  ELSE
    SELECT * INTO v_original FROM public.spin_reserve_ledger r
     WHERE r.tournament_id = NEW.tournament_id
       AND r.kind = CASE WHEN NEW.kind = 'draw_reversal'
                         THEN 'jackpot_draw' ELSE 'contribution' END
     FOR SHARE;
    IF v_original.id IS NULL
       OR v_original.club_id IS DISTINCT FROM NEW.club_id
       OR NEW.buy_in IS DISTINCT FROM v_original.buy_in
       OR NEW.seats IS DISTINCT FROM v_original.seats
       OR NEW.house_rake IS DISTINCT FROM v_original.house_rake
       OR NEW.multiplier IS DISTINCT FROM v_original.multiplier
       OR NEW.amount IS DISTINCT FROM -v_original.amount
       OR (NEW.kind = 'draw_reversal' AND NEW.amount <= 0)
       OR (NEW.kind = 'contribution_reversal' AND NEW.amount >= 0) THEN
      RAISE EXCEPTION 'Spin % does not reverse one exact original row',NEW.kind
        USING ERRCODE = 'P0404';
    END IF;
  END IF;

  v_key := 'spin:' || NEW.tournament_id::text || CASE NEW.kind
    WHEN 'contribution' THEN ':entry'
    WHEN 'jackpot_draw' THEN ':draw'
    WHEN 'draw_reversal' THEN ':cancel:draw'
    ELSE ':cancel:entry' END;
  v_category := CASE NEW.kind
    WHEN 'contribution' THEN 'spin_entry'
    WHEN 'jackpot_draw' THEN 'spin_prize'
    ELSE 'reversal' END;
  v_from_type := CASE NEW.kind
    WHEN 'contribution' THEN 'prize_liability'
    WHEN 'draw_reversal' THEN 'prize_liability'
    ELSE 'spin_reserve' END;
  v_from_id := CASE WHEN v_from_type = 'prize_liability'
                    THEN NEW.tournament_id ELSE v_pool_id END;
  v_to_type := CASE WHEN v_from_type = 'prize_liability'
                    THEN 'spin_reserve' ELSE 'prize_liability' END;
  v_to_id := CASE WHEN v_to_type = 'prize_liability'
                  THEN NEW.tournament_id ELSE v_pool_id END;

  SELECT count(*) INTO v_count FROM public.chip_ledger l
   WHERE l.category = v_category
     AND l.from_type = v_from_type AND l.from_entity_id = v_from_id
     AND l.to_type = v_to_type AND l.to_entity_id = v_to_id
     AND l.tournament_id = NEW.tournament_id
     AND (l.idempotency_key = v_key
          OR (NEW.kind = 'jackpot_draw' AND l.idempotency_key IS NULL))
     AND l.amount = abs(NEW.amount)
     AND CASE WHEN NEW.amount > 0
              THEN l.post_to_balance IS NOT DISTINCT FROM NEW.balance_after
              ELSE l.post_from_balance IS NOT DISTINCT FROM NEW.balance_after END;
  IF v_count <> 1 THEN
    RAISE EXCEPTION 'Spin % requires one exact journal leg; found %',
      NEW.kind,v_count USING ERRCODE = 'P0404';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_spin_reserve_row_requires_exact_journal() OWNER TO postgres;

--
-- Name: fn_spin_reserve_seed_from_union(uuid, uuid, numeric, numeric, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_reserve_seed_from_union(p_union_id uuid, p_club_id uuid, p_amount numeric, p_highest_stake numeric DEFAULT NULL::numeric, p_ceiling numeric DEFAULT NULL::numeric, p_wallet text DEFAULT 'spin_reserve_wallet'::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_key text := COALESCE(p_idempotency_key,
                  'spinseed:' || p_union_id::text || ':' || p_club_id::text);
  v_bal numeric; v_after numeric; v_owner uuid; v_pool_bal numeric;
BEGIN
  IF COALESCE(p_amount,0) <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive');
  END IF;
  IF p_wallet NOT IN ('spin_reserve_wallet','promo_wallet','rake_wallet','chip_balance') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unsupported_wallet');
  END IF;

  v_owner := public.fn_spin_reserve_pool(p_club_id);
  IF v_owner <> p_union_id THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'union_does_not_own_this_reserve',
      'owner_id', v_owner);
  END IF;

  IF EXISTS (SELECT 1 FROM public.union_wallet_transactions
             WHERE union_id = p_union_id AND tx_type = 'spin_reserve_seed'
               AND notes LIKE '%' || v_key || '%') THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'already_seeded');
  END IF;

  EXECUTE format('SELECT %I FROM public.union_wallets WHERE union_id = $1 FOR UPDATE', p_wallet)
    INTO v_bal USING p_union_id;

  IF v_bal IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'union_wallet_not_found');
  END IF;
  IF v_bal < p_amount THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'insufficient_union_funds',
      'wallet', p_wallet, 'available', v_bal, 'requested', p_amount);
  END IF;

  EXECUTE format(
    'UPDATE public.union_wallets SET %I = %I - $1, updated_at = now()
      WHERE union_id = $2 RETURNING %I', p_wallet, p_wallet, p_wallet)
    INTO v_after USING p_amount, p_union_id;

  INSERT INTO public.union_wallet_transactions
    (union_id, wallet, direction, amount, balance_after, tx_type, club_id, notes)
  VALUES (p_union_id, p_wallet, 'debit', p_amount, v_after, 'spin_reserve_seed',
          p_club_id,
          format('Spin Reserve Pool seed (operator capital, not player funds) [%s]', v_key));

  UPDATE public.spin_bonus_pools
     SET balance            = balance + p_amount,
         seeded_amount      = seeded_amount + p_amount,
         seed_source_wallet = COALESCE(seed_source_wallet, p_wallet),
         highest_stake      = COALESCE(p_highest_stake, highest_stake),
         offered_max_stake  = GREATEST(offered_max_stake, COALESCE(p_highest_stake, 0)),
         updated_at         = now()
   WHERE club_id = v_owner
   RETURNING balance INTO v_pool_bal;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'spin pool row missing for owner % after debiting the union wallet', v_owner;
  END IF;

  UPDATE public.spin_bonus_pools
     SET required_seed_at_activation =
           GREATEST(required_seed_at_activation,
                    public.fn_spin_required_seed(offered_max_stake))
   WHERE club_id = v_owner;

  INSERT INTO public.spin_reserve_ledger (club_id, kind, amount, balance_after, note)
  VALUES (v_owner, 'seed', p_amount, v_pool_bal,
          format('union seed from %s [%s]', p_wallet, v_key));

  RETURN jsonb_build_object('ok', true, 'wallet', p_wallet,
    'debited', p_amount, 'union_balance_after', v_after,
    'owner_id', v_owner, 'pool_balance', v_pool_bal);
END;
$_$;


ALTER FUNCTION public.fn_spin_reserve_seed_from_union(p_union_id uuid, p_club_id uuid, p_amount numeric, p_highest_stake numeric, p_ceiling numeric, p_wallet text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: fn_spin_reserve_state(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_reserve_state(p_club_id uuid) RETURNS TABLE(balance numeric, seeded_amount numeric, ceiling_amount numeric, highest_stake numeric, total_deposited numeric, total_drawn numeric, spin_count integer, bonus_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_owner uuid;
BEGIN
  v_owner := public.fn_spin_reserve_pool(p_club_id);
  RETURN QUERY
  SELECT p.balance, p.seeded_amount, p.ceiling_amount, p.highest_stake,
         p.total_deposited, p.total_drawn, p.spin_count, p.bonus_count
  FROM public.spin_bonus_pools p WHERE p.club_id = v_owner;
END; $$;


ALTER FUNCTION public.fn_spin_reserve_state(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_spin_reserve_wallet_fund(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_reserve_wallet_fund(p_union_id uuid, p_amount numeric, p_from_wallet text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v_from numeric; v_after numeric; v_res numeric;
BEGIN
  IF COALESCE(p_amount,0) <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive');
  END IF;

  -- NOT ON CONFLICT: union_wallets carries no advertised unique constraint on
  -- union_id, and an ON CONFLICT naming a column without one is a runtime
  -- error rather than a no-op.
  INSERT INTO public.union_wallets (union_id)
  SELECT p_union_id
   WHERE NOT EXISTS (SELECT 1 FROM public.union_wallets w WHERE w.union_id = p_union_id);

  IF p_from_wallet IS NOT NULL THEN
    IF p_from_wallet NOT IN ('promo_wallet','rake_wallet','chip_balance') THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'unsupported_source_wallet');
    END IF;
    EXECUTE format('SELECT %I FROM public.union_wallets WHERE union_id = $1 FOR UPDATE', p_from_wallet)
      INTO v_from USING p_union_id;
    IF COALESCE(v_from,0) < p_amount THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'insufficient_union_funds',
        'wallet', p_from_wallet, 'available', COALESCE(v_from,0), 'requested', p_amount);
    END IF;
    EXECUTE format(
      'UPDATE public.union_wallets SET %I = %I - $1, updated_at = now()
        WHERE union_id = $2 RETURNING %I', p_from_wallet, p_from_wallet, p_from_wallet)
      INTO v_after USING p_amount, p_union_id;
    INSERT INTO public.union_wallet_transactions
      (union_id, wallet, direction, amount, balance_after, tx_type, notes)
    VALUES (p_union_id, p_from_wallet, 'debit', p_amount, v_after,
            'spin_reserve_wallet_fund',
            COALESCE(p_note, 'moved to the Spin reserve wallet'));
  END IF;

  UPDATE public.union_wallets
     SET spin_reserve_wallet = spin_reserve_wallet + p_amount, updated_at = now()
   WHERE union_id = p_union_id RETURNING spin_reserve_wallet INTO v_res;

  INSERT INTO public.union_wallet_transactions
    (union_id, wallet, direction, amount, balance_after, tx_type, notes)
  VALUES (p_union_id, 'spin_reserve_wallet', 'credit', p_amount, v_res,
          'spin_reserve_wallet_fund',
          COALESCE(p_note, CASE WHEN p_from_wallet IS NULL
                                THEN 'operator deposit'
                                ELSE format('from %s', p_from_wallet) END));

  RETURN jsonb_build_object('ok', true, 'spin_reserve_wallet', v_res);
END; $_$;


ALTER FUNCTION public.fn_spin_reserve_wallet_fund(p_union_id uuid, p_amount numeric, p_from_wallet text, p_note text) OWNER TO postgres;

--
-- Name: fn_spin_reserve_wallet_fund_op(uuid, numeric, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_reserve_wallet_fund_op(p_union_id uuid, p_amount numeric, p_from_wallet text, p_note text, p_op_id uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_res     jsonb;
  v_before  uuid[];
  v_target  uuid;
  v_stamped int;
BEGIN
  IF p_op_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'op_id_required');
  END IF;

  IF p_from_wallet IS NULL OR p_from_wallet NOT IN ('promo_wallet', 'rake_wallet', 'chip_balance') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'source_wallet_required',
      'allowed', jsonb_build_array('promo_wallet', 'rake_wallet', 'chip_balance'));
  END IF;

  BEGIN
    SELECT COALESCE(array_agg(id), '{}'::uuid[]) INTO v_before
      FROM public.union_wallet_transactions
     WHERE union_id = p_union_id
       AND tx_type  = 'spin_reserve_wallet_fund'
       AND wallet   = 'spin_reserve_wallet'
       AND period_id IS NULL;

    v_res := public.fn_spin_reserve_wallet_fund(p_union_id, p_amount, p_from_wallet, p_note);

    -- A business refusal moved nothing and claims no op id, so it is returned
    -- as-is and may be retried.
    IF COALESCE((v_res ->> 'ok')::boolean, false) IS NOT TRUE THEN
      RETURN v_res;
    END IF;

    SELECT id INTO v_target
      FROM public.union_wallet_transactions
     WHERE union_id  = p_union_id
       AND tx_type   = 'spin_reserve_wallet_fund'
       AND wallet    = 'spin_reserve_wallet'
       AND direction = 'credit'
       AND period_id IS NULL
       AND NOT (id = ANY (v_before))
     ORDER BY created_at DESC, id DESC
     LIMIT 1;

    IF v_target IS NULL THEN
      RAISE EXCEPTION 'spin reserve fund wrote no credit row for op %', p_op_id;
    END IF;

    UPDATE public.union_wallet_transactions t
       SET period_id  = p_op_id,
           created_by = COALESCE(p_created_by, t.created_by)
     WHERE t.id = v_target;
    GET DIAGNOSTICS v_stamped = ROW_COUNT;

    RETURN v_res || jsonb_build_object('op_id', p_op_id, 'ledger_rows', v_stamped);
  EXCEPTION
    WHEN unique_violation THEN
      -- Everything above, credit and debit included, rolls back to the start
      -- of this block. The original operation still stands.
      RETURN jsonb_build_object('ok', false, 'duplicate', true,
        'reason', 'already_processed', 'op_id', p_op_id);
  END;
END;
$$;


ALTER FUNCTION public.fn_spin_reserve_wallet_fund_op(p_union_id uuid, p_amount numeric, p_from_wallet text, p_note text, p_op_id uuid, p_created_by uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_reserve_wallet_fund_op(p_union_id uuid, p_amount numeric, p_from_wallet text, p_note text, p_op_id uuid, p_created_by uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_reserve_wallet_fund_op(p_union_id uuid, p_amount numeric, p_from_wallet text, p_note text, p_op_id uuid, p_created_by uuid) IS 'Replay-safe entry point for funding a union Spin reserve wallet. Wraps fn_spin_reserve_wallet_fund, claims the op id on the ledger rows via uq_union_wallet_tx_op, and rolls the whole move back on a duplicate. Requires a real source wallet - it will not mint.';


--
-- Name: fn_spin_seed_instalment(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_seed_instalment(p_balance numeric, p_outstanding numeric, p_floor numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN COALESCE(p_outstanding,0) <= 0 OR COALESCE(p_floor,0) <= 0 THEN 0
    WHEN COALESCE(p_balance,0) < p_floor * 1.25 THEN 0
    WHEN (p_balance - p_floor) <= 0 THEN 0
    ELSE (
      SELECT CASE WHEN v >= 1 THEN v ELSE 0 END
      FROM (SELECT round(LEAST(p_outstanding, (p_balance - p_floor) * 0.5), 2) AS v) q
    )
  END;
$$;


ALTER FUNCTION public.fn_spin_seed_instalment(p_balance numeric, p_outstanding numeric, p_floor numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_seed_instalment(p_balance numeric, p_outstanding numeric, p_floor numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_seed_instalment(p_balance numeric, p_outstanding numeric, p_floor numeric) IS 'What the next seed instalment would be: half the surplus above the floor, capped at what is still owed, and only once the balance is 25% clear of the floor. Zero below a 1-chip instalment, which is dust. Mirrors seedInstalmentDue() in src/config/spinSpec.ts.';


--
-- Name: fn_spin_settle_game(uuid, uuid, numeric, integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_settle_game(p_tournament_id uuid, p_club_id uuid, p_buy_in numeric, p_seats integer, p_multiplier numeric, p_rake_rate numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_collected numeric; v_rake numeric; v_reserve_in numeric;
  v_prize numeric; v_bal numeric; v_available numeric;
  v_shortfall numeric := 0; v_drawn numeric;
  v_owner uuid; v_kind text; v_seed numeric; v_wallet text;
  v_floor numeric; v_instalment numeric := 0;
  v_seed_returned numeric := 0; v_wallet_after numeric := NULL;
  v_booked_mult numeric; v_booked_drawn numeric;
  v_entry_booked boolean;
  v_rake_booked boolean;
BEGIN
  IF COALESCE(p_buy_in,0) <= 0 OR COALESCE(p_seats,0) <= 0 OR COALESCE(p_multiplier,0) <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_inputs');
  END IF;

  v_owner := public.fn_spin_reserve_pool(p_club_id);

  SELECT balance INTO v_bal
    FROM public.spin_bonus_pools WHERE club_id = v_owner FOR UPDATE;

  -- THE PRIZE IS WHAT THIS FUNCTION OWNS. A contribution row on its own means
  -- the entry was booked when the last seat was paid and the prize still is
  -- not; only a jackpot_draw row means settled.
  IF EXISTS (SELECT 1 FROM public.spin_reserve_ledger
             WHERE tournament_id = p_tournament_id AND kind = 'jackpot_draw') THEN
    SELECT l.multiplier, -l.amount INTO v_booked_mult, v_booked_drawn
      FROM public.spin_reserve_ledger l
     WHERE l.tournament_id = p_tournament_id AND l.kind = 'jackpot_draw'
     ORDER BY l.created_at ASC LIMIT 1;
    RETURN jsonb_build_object('ok', true, 'reason', 'already_settled',
      'multiplier', v_booked_mult, 'pool_covered', v_booked_drawn);
  END IF;

  v_collected  := round(p_buy_in * p_seats, 2);
  v_rake       := round(v_collected * COALESCE(p_rake_rate, 0.08), 2);
  v_reserve_in := round(v_collected - v_rake, 2);
  v_prize      := round(p_buy_in * p_multiplier, 2);

  v_entry_booked := EXISTS (SELECT 1 FROM public.spin_reserve_ledger
                             WHERE tournament_id = p_tournament_id AND kind = 'contribution');
  v_rake_booked  := EXISTS (SELECT 1 FROM public.rake_records
                             WHERE tournament_id = p_tournament_id
                               AND source IN ('fn_spin_book_entry','fn_spin_settle_game'));

  IF NOT v_entry_booked THEN
    -- ZERO-DRIFT phase 2: reserve intake = spin_entry vs the tournament.
    PERFORM set_config('app.ledger_category', 'spin_entry', true);
    PERFORM set_config('app.ledger_counterparty', 'prize_liability', true);
    PERFORM set_config('app.ledger_counterparty_entity', p_tournament_id::text, true);

    UPDATE public.spin_bonus_pools
       SET balance = balance + v_reserve_in,
           total_deposited = total_deposited + v_reserve_in,
           spin_count = spin_count + 1,
           highest_stake = GREATEST(highest_stake, p_buy_in),
           updated_at = now()
     WHERE club_id = v_owner RETURNING balance INTO v_available;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'spin pool row missing for owner % settling tournament %',
        v_owner, p_tournament_id;
    END IF;

    INSERT INTO public.spin_reserve_ledger
      (club_id, tournament_id, kind, amount, balance_after, multiplier, buy_in, seats, house_rake, note)
    VALUES (v_owner, p_tournament_id, 'contribution', v_reserve_in, v_available,
            p_multiplier, p_buy_in, p_seats, v_rake,
            CASE WHEN v_owner = p_club_id THEN 'buy-ins less fixed rake'
                 ELSE format('buy-ins less fixed rake (club %s)', p_club_id) END);
  ELSE
    -- Already funded at entry. Read where the pool actually stands.
    SELECT balance INTO v_available
      FROM public.spin_bonus_pools WHERE club_id = v_owner;
    IF v_available IS NULL THEN
      RAISE EXCEPTION 'spin pool row missing for owner % settling tournament %',
        v_owner, p_tournament_id;
    END IF;
  END IF;

  -- A claimed operator shortfall has no funding debit. Reject it before
  -- writing a draw or escrow credit. The atomic launch caller excludes such
  -- tiers while holding this same pool lock; this also fences older callers.
  IF v_prize > v_available THEN
    RAISE EXCEPTION 'Spin prize % exceeds funded reserve % for tournament %',
      v_prize, v_available, p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  v_drawn := v_prize;

  -- ZERO-DRIFT phase 2: the draw funds the tournament's prize pool.
  -- CHIP STANDARD 1.3 (2026-09-02): ... and names the tournament it funds. With only
  -- the category set, this leg landed spin_reserve -> settlement_suspense (3,303 rows
  -- / 185,189.00 a day, R9). service_role-only, so the primitive is used.
  PERFORM public.fn_ca_declare_ledger('spin_prize', 'prize_liability', p_tournament_id);

  UPDATE public.spin_bonus_pools
     SET balance = balance - v_drawn,
         total_drawn = total_drawn + v_drawn,
         bonus_count = bonus_count + CASE WHEN p_multiplier >= 10 THEN 1 ELSE 0 END,
         updated_at = now()
   WHERE club_id = v_owner RETURNING balance INTO v_bal;

  INSERT INTO public.spin_reserve_ledger
    (club_id, tournament_id, kind, amount, balance_after, multiplier, buy_in, seats, house_rake, note)
  VALUES (v_owner, p_tournament_id, 'jackpot_draw', -v_drawn, v_bal,
          p_multiplier, p_buy_in, p_seats, v_rake,
          CASE WHEN v_shortfall > 0
               THEN format('prize pool (pool covered %s of %s)', v_drawn, v_prize)
               ELSE 'prize pool' END);

  IF v_shortfall > 0 THEN
    INSERT INTO public.spin_reserve_ledger
      (club_id, tournament_id, kind, amount, balance_after, multiplier, buy_in, seats, note)
    VALUES (v_owner, p_tournament_id, 'adjustment', 0, v_bal,
            p_multiplier, p_buy_in, p_seats,
            format('SHORTFALL %s covered by operator - pool was too thin for a %sx. Seed it.',
                   v_shortfall, p_multiplier));
  END IF;

  IF v_rake > 0 AND p_club_id IS NOT NULL AND NOT v_rake_booked THEN
    INSERT INTO public.rake_records
      (hand_id, table_id, club_id, rake_amount, pot_size, num_players,
       bbj_contribution, is_tournament, tournament_id, source, metadata)
    VALUES (NULL, NULL, p_club_id, v_rake, v_collected, p_seats, 0, true,
            p_tournament_id, 'fn_spin_settle_game',
            jsonb_build_object('kind','spin_rake','multiplier',p_multiplier,
                               'buy_in',p_buy_in,'rake_rate',p_rake_rate,
                               'shortfall',v_shortfall,'reserve_owner',v_owner));
  END IF;

  -- THE REPAYMENT PLAN - one instalment per settle, at most.
  SELECT seeded_amount, seed_source_wallet, owner_kind, required_seed_at_activation
    INTO v_seed, v_wallet, v_kind, v_floor
    FROM public.spin_bonus_pools WHERE club_id = v_owner;

  v_instalment := public.fn_spin_seed_instalment(v_bal, COALESCE(v_seed,0), COALESCE(v_floor,0));

  IF v_instalment > 0 AND v_wallet IS NOT NULL THEN
    PERFORM set_config('app.ledger_category', 'treasury_transfer', true);
    PERFORM set_config('app.ledger_counterparty',
      CASE WHEN v_kind = 'union' THEN 'union_wallet' ELSE 'club_treasury' END, true);
    PERFORM set_config('app.ledger_counterparty_entity', v_owner::text, true);
    PERFORM set_config('app.ledger_autoskip_union_wallets', '1', true);
    PERFORM set_config('app.ledger_autoskip_clubs', '1', true);

    v_wallet_after := public.fn_spin_move_owner_wallet(v_owner, v_kind, v_wallet, v_instalment);

    IF v_wallet_after IS NOT NULL THEN
      UPDATE public.spin_bonus_pools
         SET balance              = balance - v_instalment,
             seeded_amount        = seeded_amount - v_instalment,
             seed_returned_amount = seed_returned_amount + v_instalment,
             seed_returned_at     = now(),
             required_seed_at_activation =
               CASE WHEN seeded_amount - v_instalment <= 0 THEN 0
                    ELSE required_seed_at_activation END,
             updated_at           = now()
       WHERE club_id = v_owner RETURNING balance INTO v_bal;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'spin pool row vanished for owner % after repaying % to %',
          v_owner, v_instalment, v_wallet;
      END IF;

      v_seed_returned := v_instalment;

      INSERT INTO public.spin_reserve_ledger
        (club_id, tournament_id, kind, amount, balance_after, note)
      VALUES (v_owner, p_tournament_id, 'seed_return', -v_instalment, v_bal,
              format('seed instalment to %s %s - 50%% of %s above a floor of %s; %s still owed',
                     v_kind, v_wallet, round(v_bal + v_instalment - v_floor, 2), v_floor,
                     GREATEST(COALESCE(v_seed,0) - v_instalment, 0)));
    END IF;

    PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);
    PERFORM set_config('app.ledger_autoskip_clubs', '', true);
  END IF;

  RETURN jsonb_build_object('ok', true, 'collected', v_collected,
    'house_rake', v_rake, 'reserve_in', v_reserve_in, 'prize_pool', v_prize,
    'pool_covered', v_drawn, 'operator_shortfall', v_shortfall,
    'balance', v_bal, 'seed_returned', v_seed_returned,
    'entry_booked_at_seat', v_entry_booked,
    'seed_outstanding', GREATEST(COALESCE(v_seed,0) - v_seed_returned, 0),
    'owner_id', v_owner, 'source_wallet_after', v_wallet_after);
END;
$$;


ALTER FUNCTION public.fn_spin_settle_game(p_tournament_id uuid, p_club_id uuid, p_buy_in numeric, p_seats integer, p_multiplier numeric, p_rake_rate numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_settle_game(p_tournament_id uuid, p_club_id uuid, p_buy_in numeric, p_seats integer, p_multiplier numeric, p_rake_rate numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_settle_game(p_tournament_id uuid, p_club_id uuid, p_buy_in numeric, p_seats integer, p_multiplier numeric, p_rake_rate numeric) IS 'Stage-1 rolling compatibility door and raw primitive beneath fn_spin_draw_and_settle. Becomes owner-only in post-publish stage 2.';


--
-- Name: fn_spin_shortfall_funds_the_escrow(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_shortfall_funds_the_escrow() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_drawn     numeric;
  v_prize     numeric;
  v_shortfall numeric;
BEGIN
  IF NEW.kind <> 'adjustment' OR NEW.note IS NULL OR NEW.note NOT LIKE 'SHORTFALL %' THEN
    RETURN NULL;
  END IF;
  IF COALESCE(NEW.multiplier, 0) <= 0 OR COALESCE(NEW.buy_in, 0) <= 0 THEN
    RETURN NULL;
  END IF;

  SELECT -l.amount INTO v_drawn
    FROM public.spin_reserve_ledger l
   WHERE l.tournament_id = NEW.tournament_id AND l.kind = 'jackpot_draw'
   ORDER BY l.created_at ASC LIMIT 1;

  v_prize     := round(NEW.multiplier * NEW.buy_in, 2);
  v_shortfall := round(v_prize - COALESCE(v_drawn, 0), 2);
  IF v_shortfall <= 0 THEN
    RETURN NULL;
  END IF;

  PERFORM public.fn_ca_escrow_apply(
    NEW.tournament_id,
    'spin reserve shortfall covered by the operator',
    0, 0, 0, 0, v_shortfall
  );
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_spin_shortfall_funds_the_escrow() OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_shortfall_funds_the_escrow(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_shortfall_funds_the_escrow() IS 'When a spin draws more than its club reserve holds, the operator covers the difference and the players are paid in full. This books that top-up into tournament_escrow as overlay_in, so an enforced spin escrow can never refuse a prize the platform has already decided to pay.';


--
-- Name: fn_spin_sweep_unbooked(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_sweep_unbooked(p_lookback_mins integer DEFAULT 180, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_t record; v_n integer := 0; v_fail integer := 0;
  v_res jsonb; v_repair jsonb; v_failures jsonb := '[]'::jsonb;
  v_limit integer := greatest(1, least(coalesce(p_limit, 25), 500));
  v_remaining integer := 0;
BEGIN
  BEGIN
    v_repair := public.fn_spin_repair_missing_multiplier(p_lookback_mins);
  EXCEPTION WHEN OTHERS THEN
    v_repair := jsonb_build_object('ok', false, 'reason', SQLERRM);
  END;

  FOR v_t IN
    SELECT t.id, t.club_id, t.buy_in_amount, t.spin_multiplier
    FROM public.tournaments t
    WHERE t.variant = 'spin'
      AND t.status IN ('RUNNING','COMPLETED')
      AND COALESCE(t.buy_in_fee, 0) = 0
      AND COALESCE(t.spin_multiplier, 0) > 0
      AND t.club_id IS NOT NULL
      -- Did anybody actually enter? current_players drains to zero, so test the
      -- rows, not the counter. A spin nobody entered has nothing to book.
      AND EXISTS (SELECT 1 FROM public.tournament_players tp
                   WHERE tp.tournament_id = t.id)
      -- COALESCE, not a bare started_at: NULL > now() - interval is NULL, which
      -- is not true, so a spin whose start write was lost was invisible here.
      AND COALESCE(t.started_at, t.created_at) > now() - make_interval(mins => p_lookback_mins)
      AND NOT EXISTS (SELECT 1 FROM public.spin_reserve_ledger l
                      WHERE l.tournament_id = t.id)
    ORDER BY COALESCE(t.started_at, t.created_at)
    LIMIT v_limit
  LOOP
    BEGIN
      v_res := public.fn_spin_settle_game(
        v_t.id, v_t.club_id, v_t.buy_in_amount, 3, v_t.spin_multiplier,
        public.fn_spin_rake_rate(v_t.buy_in_amount));
      IF COALESCE((v_res->>'ok')::boolean, false) THEN
        v_n := v_n + 1;
      ELSE
        v_fail := v_fail + 1;
        v_failures := v_failures || jsonb_build_object(
          'tournament_id', v_t.id, 'reason', COALESCE(v_res->>'reason', 'refused'));
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      v_failures := v_failures || jsonb_build_object(
        'tournament_id', v_t.id, 'sqlstate', SQLSTATE, 'error', SQLERRM);
    END;
  END LOOP;

  SELECT count(*) INTO v_remaining
  FROM public.tournaments t
  WHERE t.variant = 'spin'
    AND t.status IN ('RUNNING','COMPLETED')
    AND COALESCE(t.buy_in_fee, 0) = 0
    AND COALESCE(t.spin_multiplier, 0) > 0
    AND t.club_id IS NOT NULL
    AND EXISTS (SELECT 1 FROM public.tournament_players tp
                 WHERE tp.tournament_id = t.id)
    AND COALESCE(t.started_at, t.created_at) > now() - make_interval(mins => p_lookback_mins)
    AND NOT EXISTS (SELECT 1 FROM public.spin_reserve_ledger l
                    WHERE l.tournament_id = t.id);

  -- `skipped_no_entrants` is GONE, not zero. It was declared, never
  -- incremented, and returned - a field that always read 0 because the entrant
  -- test lives in the WHERE clause now. An absent field is honest; a constant
  -- one is a placeholder an operator can mistake for a measurement.
  RETURN jsonb_build_object('ok', true, 'settled', v_n, 'failed', v_fail,
                            'failures', v_failures,
                            'lookback_mins', p_lookback_mins,
                            'batch_limit', v_limit,
                            'remaining', v_remaining,
                            'multiplier_repair', v_repair);
END;
$$;


ALTER FUNCTION public.fn_spin_sweep_unbooked(p_lookback_mins integer, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_sweep_unbooked(p_lookback_mins integer, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_sweep_unbooked(p_lookback_mins integer, p_limit integer) IS 'Books the reserve leg for a spin the engine settled without writing. Scoped on COALESCE(started_at, created_at): a spin whose start write was lost is the one most likely to be unbooked, and a bare started_at comparison made it invisible.';


--
-- Name: fn_spin_tournament_contract_is_draw(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_tournament_contract_is_draw() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
  v_multiplier numeric;
  v_prize numeric;
  v_old_sealed boolean;
BEGIN
  IF NEW.spin_multiplier IS NOT DISTINCT FROM OLD.spin_multiplier
     AND NEW.prize_pool IS NOT DISTINCT FROM OLD.prize_pool
     AND NEW.spin_locked_tiers IS NOT DISTINCT FROM OLD.spin_locked_tiers THEN
    RETURN NEW;
  END IF;
  IF lower(COALESCE(NEW.variant,'')) <> 'spin'
     AND upper(COALESCE(NEW.tournament_type,'')) <> 'SPIN' THEN
    RETURN NEW;
  END IF;
  IF upper(COALESCE(NEW.status::text,'')) IN ('CANCELLED','CANCELED')
     AND upper(COALESCE(OLD.status::text,'')) NOT IN ('CANCELLED','CANCELED')
     AND NEW.prize_pool IS NOT DISTINCT FROM 0::numeric
     AND NEW.spin_multiplier IS NOT DISTINCT FROM OLD.spin_multiplier
     AND NEW.spin_locked_tiers IS NOT DISTINCT FROM OLD.spin_locked_tiers
     AND (
       (NOT EXISTS (
          SELECT 1 FROM public.spin_reserve_ledger r
           WHERE r.tournament_id = NEW.id
             AND r.kind IN ('contribution','jackpot_draw')))
       OR EXISTS (
          SELECT 1 FROM public.tournament_spin_cancellation_unwinds u
           WHERE u.tournament_id = NEW.id)) THEN
    RETURN NEW;
  END IF;

  SELECT count(*),min(r.multiplier),min(round(-r.amount,2))
    INTO v_count,v_multiplier,v_prize
    FROM public.spin_reserve_ledger r
   WHERE r.tournament_id = NEW.id AND r.kind = 'jackpot_draw';
  IF v_count <> 1
     OR NEW.spin_multiplier IS DISTINCT FROM v_multiplier
     OR NEW.prize_pool IS DISTINCT FROM v_prize THEN
    RAISE EXCEPTION 'Spin % tournament contract must equal its reserve draw',NEW.id
      USING ERRCODE = 'P0404';
  END IF;
  v_old_sealed := OLD.spin_multiplier IS NOT DISTINCT FROM v_multiplier
                  AND OLD.prize_pool IS NOT DISTINCT FROM v_prize
                  AND OLD.spin_locked_tiers IS NOT NULL;
  IF v_old_sealed THEN
    RAISE EXCEPTION 'Spin % published draw contract is immutable',NEW.id
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_spin_tournament_contract_is_draw() OWNER TO postgres;

--
-- Name: fn_spin_unpaid_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_unpaid_check(p_since_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_since       timestamptz := now() - make_interval(days => GREATEST(COALESCE(p_since_days, 30), 1));
  v_unpaid      integer := 0;
  v_short       numeric := 0;
  v_over        integer := 0;
  v_over_amt    numeric := 0;
  v_nobody      integer := 0;
  v_ids         uuid[];
  v_alerts      integer := 0;
  v_row         record;
BEGIN
  SELECT COUNT(*) FILTER (WHERE v.chips_short > 0),
         COALESCE(SUM(v.chips_short) FILTER (WHERE v.chips_short > 0), 0),
         COUNT(*) FILTER (WHERE v.chips_short < 0),
         COALESCE(SUM(-v.chips_short) FILTER (WHERE v.chips_short < 0), 0),
         COUNT(*) FILTER (WHERE v.verdict = 'nobody_paid'),
         COALESCE(array_agg(v.tournament_id ORDER BY v.chips_short DESC)
                  FILTER (WHERE v.chips_short > 0), ARRAY[]::uuid[])
    INTO v_unpaid, v_short, v_over, v_over_amt, v_nobody, v_ids
    FROM public.v_spin_unpaid_settlements v
   WHERE COALESCE(v.drawn_at, v.started_at) >= v_since;

  -- One alert per offending tournament, never a duplicate while unresolved.
  FOR v_row IN
    SELECT v.* FROM public.v_spin_unpaid_settlements v
     WHERE COALESCE(v.drawn_at, v.started_at) >= v_since
       AND v.chips_short > 0
  LOOP
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical', 'fn_spin_unpaid_check',
           format('Spin drew %s from the reserve and credited %s to players: %s',
                  v_row.prize_drawn, v_row.prize_credited,
                  COALESCE(v_row.name, v_row.tournament_id::text)),
           jsonb_build_object('tournament_id', v_row.tournament_id,
                              'club_id',       v_row.club_id,
                              'prize_drawn',   v_row.prize_drawn,
                              'prize_credited',v_row.prize_credited,
                              'chips_short',   v_row.chips_short,
                              'verdict',       v_row.verdict,
                              'seat_shape',    v_row.seat_shape,
                              'unranked_seats',v_row.unranked_seats,
                              'buy_in',        v_row.buy_in_amount,
                              'multiplier',    v_row.spin_multiplier,
                              'drawn_at',      v_row.drawn_at,
                              'detail',        'no money was moved by this check; a human decides the payout')
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'fn_spin_unpaid_check'
          AND fa.resolved IS NOT TRUE
          AND fa.context->>'tournament_id' = v_row.tournament_id::text);
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',                    true,
    'since_days',            GREATEST(COALESCE(p_since_days, 30), 1),
    'unpaid_count',          v_unpaid,
    'nobody_paid_count',     v_nobody,
    'chips_at_risk',         round(v_short, 2),
    'over_paid_count',       v_over,
    'chips_over_paid',       round(v_over_amt, 2),
    'alerts_raised',         v_alerts,
    'tournament_ids',        to_jsonb(v_ids));
END;
$$;


ALTER FUNCTION public.fn_spin_unpaid_check(p_since_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_unpaid_check(p_since_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_unpaid_check(p_since_days integer) IS 'Reverse conservation check for Spins. Returns a count, the total chips at risk and the offending tournament ids, and raises one deduped critical financial_alert per offender. Moves no money by design.';


--
-- Name: fn_spin_unpaid_settlements(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_unpaid_settlements(p_since_hours integer DEFAULT 6) RETURNS TABLE(tournament_id uuid, chips_short numeric, verdict text, seats_at_first bigint, ended_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with candidates as (
    /* Cheap, indexed, and status-filtered BEFORE any per-row lookup. */
    select t.id, t.status, t.ended_at, t.buy_in_amount, t.spin_multiplier
    from public.tournaments t
    where t.variant = 'spin'
      and t.created_at > now() - (greatest(p_since_hours, 1) || ' hours')::interval
      and t.status not in ('RUNNING', 'REGISTERING')
  ),
  money as (
    /* One ledger lookup and one wallet lookup per candidate, both index-only. */
    select
      c.*,
      d.prize_drawn,
      d.drawn_at,
      coalesce(p.prize_credited, 0) as prize_credited
    from candidates c
    cross join lateral (
      select sum(-l.amount) as prize_drawn, max(l.created_at) as drawn_at
      from public.spin_reserve_ledger l
      where l.tournament_id = c.id and l.kind = 'jackpot_draw'
    ) d
    left join lateral (
      select sum(w.amount) as prize_credited
      from public.wallet_transactions w
      where w.related_entity_id = c.id and w.type = 'credit' and w.category = 'prize'
    ) p on true
    where d.prize_drawn is not null
  ),
  shortfall as (
    /* Everything that decides "is money missing" happens here, so the seat
       shape - the most expensive lookup of the three - is only paid for the
       handful of spins that are actually short. */
    select m.*, round(m.prize_drawn - m.prize_credited, 2) as short
    from money m
    where round(m.prize_drawn - m.prize_credited, 2) <> 0
      and (
        (m.status in ('COMPLETED', 'CANCELLED', 'CANCELED')
          and coalesce(m.ended_at, m.drawn_at) < now() - interval '10 minutes')
        or m.drawn_at < now() - interval '2 hours'
      )
      and not (
        m.prize_credited > m.prize_drawn
        and m.spin_multiplier is not null
        and m.prize_credited = round(m.buy_in_amount * m.spin_multiplier, 2)
      )
  )
  select
    f.id,
    f.short,
    case
      when f.prize_credited = 0 then 'nobody_paid'
      when f.prize_credited < f.prize_drawn then 'under_paid'
      else 'over_paid'
    end,
    s.seats_at_first,
    f.ended_at
  from shortfall f
  cross join lateral (
    select
      count(*) filter (where tp.position is null) as unranked_seats,
      count(*) filter (where tp.position = 1)     as seats_at_first
    from public.tournament_players tp
    where tp.tournament_id = f.id
  ) s
  where s.unranked_seats = 0
    and s.seats_at_first = 1;
$$;


ALTER FUNCTION public.fn_spin_unpaid_settlements(p_since_hours integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_spin_unpaid_settlements(p_since_hours integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_unpaid_settlements(p_since_hours integer) IS 'The ranked_but_unpaid rows of v_spin_unpaid_settlements, bounded to spins created in the last p_since_hours and staged so the seat lookup is paid only for spins that are actually short. Same predicate, same verdicts; the view stays the unbounded auditor for humans, this is what a repair running every ten minutes under an 8s statement timeout can afford.';


--
-- Name: fn_staff_pin_taken(text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_staff_pin_taken(p_venue_id text, p_pin text, p_exclude_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.commander_staff s
     WHERE s.venue_id::text = p_venue_id
       AND (p_exclude_id IS NULL OR s.id <> p_exclude_id)
       AND p_pin IS NOT NULL
       AND (
            (s.pin_hash IS NOT NULL AND s.pin_hash = extensions.crypt(p_pin, s.pin_hash))
         OR (s.pin_hash IS NULL     AND s.pin_code = p_pin)
       )
  );
$$;


ALTER FUNCTION public.fn_staff_pin_taken(p_venue_id text, p_pin text, p_exclude_id uuid) OWNER TO postgres;

