--
-- Name: fn_stamp_seat_horse_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_stamp_seat_horse_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.user_id IS NULL THEN
    NEW.horse_id := NULL;
    RETURN NEW;
  END IF;

  SELECT CASE WHEN COALESCE(p.is_horse, false) THEN p.id ELSE NULL END
    INTO NEW.horse_id
    FROM public.profiles p
   WHERE p.id = NEW.user_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_stamp_seat_horse_id() OWNER TO postgres;

--
-- Name: FUNCTION fn_stamp_seat_horse_id(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_stamp_seat_horse_id() IS 'Stamps table_seats.horse_id with the occupant profile id when that profile is a horse, NULL otherwise. The client cannot read profiles.is_horse (a horse is named only to those entitled), so the seat row is how the felt knows. Fires only when user_id is written, so an ordinary stack update costs nothing.';


--
-- Name: fn_stamp_sit_out_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_stamp_sit_out_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.sit_out_at := CASE WHEN COALESCE(NEW.is_sitting_out, false)
                           THEN COALESCE(NEW.sit_out_at, now())
                           ELSE NULL END;
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.is_sitting_out, false) AND NOT COALESCE(OLD.is_sitting_out, false) THEN
    -- Entering sit-out: start the clock.
    NEW.sit_out_at := now();
  ELSIF NOT COALESCE(NEW.is_sitting_out, false) THEN
    -- Not sitting out, by any route (sat back in, seat turned over, evicted).
    NEW.sit_out_at := NULL;
  ELSIF public.fn_freeze_bypass_active()
        AND NEW.sit_out_at IS NOT NULL
        AND NEW.sit_out_at IS DISTINCT FROM OLD.sit_out_at THEN
    -- Still sitting out, and the writer is the THAW (the only transaction
    -- that runs under app.freeze_bypass). It is giving this clock back the
    -- minutes the freeze took; honour the value it supplied.
    NULL;
  ELSE
    -- Still sitting out. HOLD THE ORIGINAL STAMP. An unrelated UPDATE to the
    -- row (a stack change, a time-bank decrement, a status write) must NOT
    -- restart the five minutes.
    NEW.sit_out_at := COALESCE(OLD.sit_out_at, NEW.sit_out_at, now());
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_stamp_sit_out_at() OWNER TO postgres;

--
-- Name: FUNCTION fn_stamp_sit_out_at(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_stamp_sit_out_at() IS 'BEFORE INSERT OR UPDATE on table_seats: stamps sit_out_at on the transition into sitting out, clears it on the way out, and holds the original stamp while sitting out - except for the thaw (app.freeze_bypass), which is entitled to shift it by the frozen duration.';


--
-- Name: fn_stamp_table_union_ownership(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_stamp_table_union_ownership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_union uuid;
BEGIN
  IF COALESCE(NEW.is_private, false) THEN
    NEW.union_id := NULL;               -- private games are never union-visible
    RETURN NEW;
  END IF;

  IF NEW.union_id IS NULL AND NEW.club_id IS NOT NULL THEN
    SELECT uc.union_id INTO v_union FROM union_clubs uc WHERE uc.club_id = NEW.club_id LIMIT 1;
    IF v_union IS NULL THEN
      -- The union's OWN house club is not a union_clubs member; it carries the
      -- union on its clubs row. Without this, house-club games are unstamped
      -- and therefore invisible in every club lobby.
      SELECT c.union_id INTO v_union FROM clubs c WHERE c.id = NEW.club_id;
    END IF;
    IF v_union IS NOT NULL THEN NEW.union_id := v_union; END IF;
  END IF;

  -- A union game belongs to the UNION, not to whichever member club happened to
  -- create it. Point club_id at the union's own container row so every surface
  -- agrees on who runs the game.
  IF NEW.union_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM clubs c WHERE c.id = NEW.union_id) THEN
    NEW.club_id := NEW.union_id;
  END IF;

  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_stamp_table_union_ownership() OWNER TO postgres;

--
-- Name: fn_stamp_tournament_elimination_sequence(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_stamp_tournament_elimination_sequence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status::text = 'eliminated' THEN
      NEW.elimination_sequence := nextval(
        'public.tournament_player_elimination_sequence'::regclass);
    ELSE
      NEW.elimination_sequence := NULL;
    END IF;
  ELSIF OLD.status::text IS DISTINCT FROM 'eliminated'
        AND NEW.status::text = 'eliminated' THEN
    NEW.elimination_sequence := nextval(
      'public.tournament_player_elimination_sequence'::regclass);
  ELSIF OLD.status::text = 'eliminated'
        AND NEW.status::text IS DISTINCT FROM 'eliminated' THEN
    NEW.elimination_sequence := NULL;
  ELSIF NEW.elimination_sequence IS DISTINCT FROM OLD.elimination_sequence THEN
    RAISE EXCEPTION 'elimination_sequence is database-owned'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_stamp_tournament_elimination_sequence() OWNER TO postgres;

--
-- Name: fn_stamp_tournament_terminal_evidence_markers(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_stamp_tournament_terminal_evidence_markers() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_terminal_at timestamptz;
BEGIN
  IF upper(COALESCE(NEW.status::text,'')) NOT IN
       ('COMPLETED','CANCELLED','CANCELED')
     OR (TG_OP = 'UPDATE' AND upper(COALESCE(OLD.status::text,'')) IN
       ('COMPLETED','CANCELLED','CANCELED')) THEN
    RETURN NEW;
  END IF;
  v_terminal_at := NEW.ended_at;
  IF v_terminal_at IS NULL OR NOT isfinite(v_terminal_at) THEN
    RAISE EXCEPTION 'terminal tournament % requires one finite close marker',NEW.id
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.tournament_players
     SET terminal_closed_at = v_terminal_at
   WHERE tournament_id = NEW.id AND terminal_closed_at IS NULL;
  UPDATE public.tournament_obligations
     SET terminal_closed_at = v_terminal_at
   WHERE tournament_id = NEW.id AND terminal_closed_at IS NULL;
  UPDATE public.tournament_payouts
     SET terminal_closed_at = v_terminal_at
   WHERE tournament_id = NEW.id AND terminal_closed_at IS NULL;
  UPDATE public.tournament_rake_settlements
     SET terminal_closed_at = v_terminal_at
   WHERE tournament_id = NEW.id AND terminal_closed_at IS NULL;
  UPDATE public.rake_records
     SET terminal_closed_at = v_terminal_at
   WHERE tournament_id = NEW.id AND terminal_closed_at IS NULL;
  UPDATE public.tournament_bounty_chests
     SET terminal_closed_at = v_terminal_at
   WHERE tournament_id = NEW.id AND terminal_closed_at IS NULL;
  UPDATE public.tournament_bounty_awards
     SET terminal_closed_at = v_terminal_at
   WHERE tournament_id = NEW.id AND terminal_closed_at IS NULL;
  UPDATE public.tournament_guarantee_overlays
     SET terminal_closed_at = v_terminal_at
   WHERE tournament_id = NEW.id AND terminal_closed_at IS NULL;
  UPDATE public.table_seats s
     SET terminal_closed_at = v_terminal_at
    FROM public.tables tb
   WHERE tb.id = s.table_id AND tb.tournament_id = NEW.id
     AND s.terminal_closed_at IS NULL;
  UPDATE public.wallet_transactions
     SET terminal_closed_at = v_terminal_at
   WHERE related_entity_id = NEW.id AND terminal_closed_at IS NULL;
  UPDATE public.tournament_bounty_award_recipients r
     SET terminal_closed_at = v_terminal_at
    FROM public.tournament_bounty_awards a
   WHERE a.id = r.award_id AND a.tournament_id = NEW.id
     AND r.terminal_closed_at IS NULL;
  UPDATE public.tournament_escrow
     SET terminal_closed_at = v_terminal_at
   WHERE tournament_id = NEW.id AND terminal_closed_at IS NULL;
  -- Contribution and jackpot-draw rows already have an unconditional
  -- append-only guard. Cancellation reversal/surplus rows intentionally do
  -- not, so give precisely those mutable Spin rows the terminal tuple marker.
  UPDATE public.spin_reserve_ledger
     SET terminal_closed_at = v_terminal_at
   WHERE tournament_id = NEW.id
     AND kind NOT IN ('contribution','jackpot_draw')
     AND terminal_closed_at IS NULL;

  IF EXISTS (SELECT 1 FROM public.tournament_players x
              WHERE x.tournament_id=NEW.id
                AND x.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (SELECT 1 FROM public.tournament_obligations x
                 WHERE x.tournament_id=NEW.id
                   AND x.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (SELECT 1 FROM public.tournament_payouts x
                 WHERE x.tournament_id=NEW.id
                   AND x.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (SELECT 1 FROM public.tournament_rake_settlements x
                 WHERE x.tournament_id=NEW.id
                   AND x.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (SELECT 1 FROM public.rake_records x
                 WHERE x.tournament_id=NEW.id
                   AND x.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (SELECT 1 FROM public.tournament_bounty_chests x
                 WHERE x.tournament_id=NEW.id
                   AND x.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (SELECT 1 FROM public.tournament_bounty_awards x
                 WHERE x.tournament_id=NEW.id
                   AND x.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (SELECT 1 FROM public.tournament_guarantee_overlays x
                 WHERE x.tournament_id=NEW.id
                   AND x.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (
       SELECT 1 FROM public.table_seats s
       JOIN public.tables tb ON tb.id=s.table_id
        WHERE tb.tournament_id=NEW.id
          AND s.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (SELECT 1 FROM public.wallet_transactions x
                 WHERE x.related_entity_id=NEW.id
                   AND x.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (
       SELECT 1 FROM public.tournament_bounty_award_recipients r
       JOIN public.tournament_bounty_awards a ON a.id=r.award_id
        WHERE a.tournament_id=NEW.id
          AND r.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (SELECT 1 FROM public.tournament_escrow x
                 WHERE x.tournament_id=NEW.id
                   AND x.terminal_closed_at IS DISTINCT FROM v_terminal_at)
     OR EXISTS (SELECT 1 FROM public.spin_reserve_ledger x
                 WHERE x.tournament_id=NEW.id
                   AND x.kind NOT IN ('contribution','jackpot_draw')
                   AND x.terminal_closed_at IS DISTINCT FROM v_terminal_at) THEN
    RAISE EXCEPTION 'terminal tournament % did not stamp every mutable evidence row',
      NEW.id USING ERRCODE = '40001';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_stamp_tournament_terminal_evidence_markers() OWNER TO postgres;

--
-- Name: fn_stamp_tournament_union_ownership(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_stamp_tournament_union_ownership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_union uuid;
BEGIN
  IF COALESCE(NEW.is_private, false) THEN
    NEW.union_id := NULL;
    RETURN NEW;
  END IF;

  IF NEW.union_id IS NULL AND NEW.club_id IS NOT NULL THEN
    SELECT uc.union_id INTO v_union FROM union_clubs uc WHERE uc.club_id = NEW.club_id LIMIT 1;
    IF v_union IS NULL THEN
      SELECT c.union_id INTO v_union FROM clubs c WHERE c.id = NEW.club_id;
    END IF;
    IF v_union IS NOT NULL THEN NEW.union_id := v_union; END IF;
  END IF;

  IF NEW.union_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM clubs c WHERE c.id = NEW.union_id) THEN
    NEW.club_id := NEW.union_id;
  END IF;

  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_stamp_tournament_union_ownership() OWNER TO postgres;

--
-- Name: fn_start_training_attempt_v2(uuid, text, text, integer, text, text, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_start_training_attempt_v2(p_user_id uuid, p_client_nonce text, p_game_id text, p_level integer, p_session_kind text, p_difficulty text, p_expected_hands integer, p_config_hash text, p_parent_attempt_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  normalized_nonce text := btrim(p_client_nonce);
  normalized_game text := btrim(p_game_id);
  normalized_kind text := lower(btrim(p_session_kind));
  normalized_difficulty text := lower(btrim(p_difficulty));
  attempt_row public.training_attempts%ROWTYPE;
  parent_row public.training_attempts%ROWTYPE;
  unlocked_level integer := 1;
  expected_campaign_hands integer;
  today_chicago date := timezone('America/Chicago', now())::date;
  inserted boolean := false;
BEGIN
  IF p_user_id IS NULL
     OR normalized_nonce IS NULL
     OR char_length(normalized_nonce) NOT BETWEEN 1 AND 180
     OR normalized_game IS NULL
     OR char_length(normalized_game) NOT BETWEEN 1 AND 100
     OR p_level IS NULL
     OR p_level NOT BETWEEN 1 AND 12
     OR normalized_kind IS NULL
     OR normalized_kind NOT IN ('campaign', 'custom', 'daily', 'replay')
     OR normalized_difficulty IS NULL
     OR normalized_difficulty NOT IN ('simple', 'grouped', 'exact')
     OR p_expected_hands IS NULL
     OR p_config_hash IS NULL
     OR p_config_hash !~ '^[0-9a-f]{64}$' THEN
    RETURN jsonb_build_object('success', false, 'status', 400,
      'code', 'TRAINING_ATTEMPT_INPUT_INVALID',
      'error', 'The Training attempt contract is invalid.');
  END IF;

  expected_campaign_hands := CASE
    WHEN p_level = 12 THEN 30 WHEN p_level = 11 THEN 25 ELSE 20
  END;
  IF (normalized_kind = 'campaign' AND p_expected_hands <> expected_campaign_hands)
     OR (normalized_kind = 'custom' AND p_expected_hands NOT IN (10, 25, 50, 100))
     OR (normalized_kind = 'daily' AND (
       p_expected_hands <> 1
       OR p_level <> 1
       OR normalized_game <> 'daily-challenge'
       OR normalized_nonce <> 'daily-' || today_chicago::text
       OR p_parent_attempt_id IS NOT NULL
     ))
     OR (normalized_kind = 'replay' AND (p_expected_hands IS NULL OR p_expected_hands NOT BETWEEN 1 AND 100)) THEN
    RETURN jsonb_build_object('success', false, 'status', 400,
      'code', 'TRAINING_ATTEMPT_HAND_COUNT_INVALID',
      'error', 'The hand count does not match the selected session kind and level.');
  END IF;

  IF p_parent_attempt_id IS NOT NULL THEN
    SELECT * INTO parent_row
    FROM public.training_attempts
    WHERE id = p_parent_attempt_id
    FOR KEY SHARE;
    IF NOT FOUND
       OR parent_row.user_id <> p_user_id
       OR parent_row.game_id <> normalized_game
       OR parent_row.level <> p_level
       OR parent_row.status <> 'completed' THEN
      RETURN jsonb_build_object('success', false, 'status', 409,
        'code', 'TRAINING_ATTEMPT_PARENT_INVALID',
        'error', 'The retry or replay source attempt is not eligible.');
    END IF;
  ELSIF normalized_kind = 'replay' THEN
    RETURN jsonb_build_object('success', false, 'status', 400,
      'code', 'TRAINING_ATTEMPT_REPLAY_PARENT_REQUIRED',
      'error', 'Mistake replay must reference a completed attempt.');
  ELSE
    SELECT greatest(1, coalesce(progress.authority_level, 1))
    INTO unlocked_level
    FROM public.training_progress progress
    WHERE progress.user_id = p_user_id
      AND progress.game_id = normalized_game;
    unlocked_level := coalesce(unlocked_level, 1);
    IF p_level > unlocked_level THEN
      RETURN jsonb_build_object('success', false, 'status', 403,
        'code', 'TRAINING_ATTEMPT_LEVEL_LOCKED',
        'error', 'This Training level has not been unlocked.');
    END IF;
  END IF;

  INSERT INTO public.training_attempts (
    user_id, client_nonce, game_id, level, session_kind, difficulty,
    expected_hands, config_hash, parent_attempt_id, practice_only
  ) VALUES (
    p_user_id, normalized_nonce, normalized_game, p_level, normalized_kind,
    normalized_difficulty, p_expected_hands, p_config_hash,
    p_parent_attempt_id, normalized_kind = 'replay'
  )
  ON CONFLICT (user_id, client_nonce, game_id, level, session_kind) DO NOTHING
  RETURNING * INTO attempt_row;
  inserted := FOUND;

  IF NOT inserted THEN
    SELECT * INTO attempt_row
    FROM public.training_attempts
    WHERE user_id = p_user_id
      AND client_nonce = normalized_nonce
      AND game_id = normalized_game
      AND level = p_level
      AND session_kind = normalized_kind
    FOR UPDATE;

    IF NOT FOUND
       OR attempt_row.game_id <> normalized_game
       OR attempt_row.level <> p_level
       OR attempt_row.session_kind <> normalized_kind
       OR attempt_row.difficulty <> normalized_difficulty
       OR attempt_row.expected_hands <> p_expected_hands
       OR attempt_row.config_hash <> p_config_hash
       OR attempt_row.parent_attempt_id IS DISTINCT FROM p_parent_attempt_id THEN
      RETURN jsonb_build_object('success', false, 'status', 409,
        'code', 'TRAINING_ATTEMPT_NONCE_CONFLICT',
        'error', 'This client session id already belongs to a different Training attempt.');
    END IF;

    IF attempt_row.status = 'open' AND attempt_row.expires_at <= now() THEN
      UPDATE public.training_attempts
      SET status = 'expired', updated_at = now()
      WHERE id = attempt_row.id;
      RETURN jsonb_build_object('success', false, 'status', 409,
        'code', 'TRAINING_ATTEMPT_EXPIRED',
        'error', 'This Training attempt expired. Start a fresh session.');
    END IF;

    IF attempt_row.status = 'expired' THEN
      RETURN jsonb_build_object('success', false, 'status', 409,
        'code', 'TRAINING_ATTEMPT_EXPIRED',
        'error', 'This Training attempt expired. Start a fresh session.');
    END IF;

    IF attempt_row.status <> 'open' THEN
      RETURN jsonb_build_object('success', false, 'status', 409,
        'code', 'TRAINING_ATTEMPT_NOT_OPEN',
        'error', 'This Training attempt is already closed. Start a fresh session.');
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'newAttempt', inserted, 'attemptId', attempt_row.id,
    'clientSessionId', attempt_row.client_nonce, 'gameId', attempt_row.game_id,
    'level', attempt_row.level, 'sessionKind', attempt_row.session_kind,
    'difficulty', attempt_row.difficulty, 'targetHands', attempt_row.expected_hands,
    'practiceOnly', attempt_row.practice_only, 'status', attempt_row.status,
    'expiresAt', attempt_row.expires_at
  );
END;
$_$;


ALTER FUNCTION public.fn_start_training_attempt_v2(p_user_id uuid, p_client_nonce text, p_game_id text, p_level integer, p_session_kind text, p_difficulty text, p_expected_hands integer, p_config_hash text, p_parent_attempt_id uuid) OWNER TO postgres;

--
-- Name: fn_strip_client_writes_from_new_views(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_strip_client_writes_from_new_views() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  cmd record;
begin
  for cmd in select * from pg_event_trigger_ddl_commands() loop
    -- Only views and materialised views, only in public. Everything else in
    -- the estate - tables above all - keeps the grants it was given.
    if cmd.object_type in ('view', 'materialized view')
       and cmd.schema_name = 'public' then
      execute format(
        'revoke insert, update, delete, truncate on %s from anon, authenticated',
        cmd.object_identity
      );
    end if;
  end loop;
end;
$$;


ALTER FUNCTION public.fn_strip_client_writes_from_new_views() OWNER TO postgres;

--
-- Name: FUNCTION fn_strip_client_writes_from_new_views(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_strip_client_writes_from_new_views() IS 'Event trigger body. The default ACL on schema public grants anon and authenticated INSERT/UPDATE/DELETE on every new relation, views included; this takes those back the moment a view is created, so CHECK 10 no_client_writable_views cannot be tripped by a view whose author never wrote a GRANT. Tables are untouched: their protection is RLS.';


--
-- Name: fn_submit_bug_report_to_admin(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_submit_bug_report_to_admin(p_sender_id uuid, p_subject text, p_description text, p_priority text, p_current_page text, p_user_agent text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_admin_id UUID;
    v_conversation_id UUID := NULL;
    v_conversation_json JSONB;
    v_message_id UUID := NULL;
    v_message_json JSONB;
    v_ticket_id UUID;
    v_content TEXT;
BEGIN
    -- 1. Find Support user ID by exact email or username
    SELECT id INTO v_admin_id FROM auth.users WHERE email ILIKE 'support@smarter.poker' LIMIT 1;
    
    -- Fallback to searching profiles if auth lookup fails
    IF v_admin_id IS NULL THEN
        SELECT id INTO v_admin_id FROM public.profiles WHERE username ILIKE 'support' LIMIT 1;
    END IF;

    -- 2. Prevent race conditions: create the core ticket completely first.
    INSERT INTO public.live_help_tickets (
        user_id, subject, description, priority, status
    ) VALUES (
        p_sender_id,
        '[BUG] ' || p_subject,
        p_description || E'\n\n---\nPage: ' || COALESCE(p_current_page, 'unknown') || E'\nUser Agent: ' || COALESCE(p_user_agent, 'unknown') || E'\nReported: ' || now()::text,
        COALESCE(p_priority, 'medium'),
        'open'
    ) RETURNING id INTO v_ticket_id;

    -- 3. Only attempt real-time DM insertion if we have both users.
    IF p_sender_id IS NOT NULL AND v_admin_id IS NOT NULL AND p_sender_id != v_admin_id THEN
        
        -- Retrieve or provision a safe P2P direct message room
        v_conversation_json := public.fn_get_or_create_conversation(p_sender_id, v_admin_id);
        
        IF (v_conversation_json->>'success')::boolean = true THEN
            v_conversation_id := (v_conversation_json->>'conversation_id')::uuid;
            
            -- Build formatted message content to look beautiful in the Messenger UI
            v_content := '🚨 **BUG REPORT** [' || upper(p_priority) || ']' || E'\n' ||
                         '**Subject:** ' || p_subject || E'\n' ||
                         '**Ticket:** BUG-' || upper(substr(v_ticket_id::text, 1, 8)) || E'\n\n' ||
                         p_description;

            -- Send via messaging system, which natively triggers the real-time pipeline event
            v_message_json := public.fn_send_message(v_conversation_id, p_sender_id, v_content);
            IF (v_message_json->>'success')::boolean = true THEN
                v_message_id := (v_message_json->>'message_id')::uuid;
                
                -- Update the ticket with the newly established conversation ID
                UPDATE public.live_help_tickets
                SET conversation_id = v_conversation_id
                WHERE id = v_ticket_id;
            END IF;
        END IF;
    END IF;

    RETURN json_build_object(
        'success', true,
        'ticket_id', v_ticket_id,
        'message_id', v_message_id,
        'conversation_id', v_conversation_id,
        'support_id', v_admin_id
    );
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION public.fn_submit_bug_report_to_admin(p_sender_id uuid, p_subject text, p_description text, p_priority text, p_current_page text, p_user_agent text) OWNER TO postgres;

--
-- Name: fn_survival_progress_monotonic(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_survival_progress_monotonic() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    NEW.highest_level := GREATEST(COALESCE(NEW.highest_level, 0), COALESCE(OLD.highest_level, 0));
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_survival_progress_monotonic() OWNER TO postgres;

--
-- Name: fn_sweep_bbj_promo(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sweep_bbj_promo(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_promo numeric; v_pool_id uuid; v_union_id uuid; v_dest text; v_after numeric;
BEGIN
  SELECT c.union_id INTO v_union_id FROM clubs c WHERE c.id = p_club_id;

  SELECT bp.id, COALESCE(bp.promo_balance, 0) INTO v_pool_id, v_promo
    FROM bbj_pools bp
   WHERE bp.status = 'active'
     AND ((v_union_id IS NOT NULL AND bp.union_id = v_union_id)
       OR (v_union_id IS NULL AND bp.club_id = p_club_id))
   ORDER BY (bp.union_id IS NOT NULL) DESC
   LIMIT 1
   FOR UPDATE;

  IF v_pool_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'no bbj pool for club');
  END IF;
  IF v_promo <= 0 THEN
    RETURN jsonb_build_object('success', true, 'swept', 0, 'note', 'nothing to sweep');
  END IF;

  -- CHIP STANDARD 1.3 (2026-09-02): THE SWEEP JOURNALS BOTH SIDES IN ONE ROW.
  -- The pool debit below is journaled by the bbj_pools autoledger as
  -- promo bbj_pool -> union_wallet (the union's promo_wallet) or -> promo_wallet
  -- (the club's promo_balance). The credit side is autoskipped so the same move is
  -- not journaled a second time through settlement_suspense (R9); the skip is
  -- cleared right after the credit. A failure branch that puts the balance back is
  -- journaled by the same declaration, in reverse.
  PERFORM public.fn_ca_declare_ledger('promo',
    CASE WHEN v_union_id IS NOT NULL THEN 'union_wallet' ELSE 'promo_wallet' END,
    COALESCE(v_union_id, p_club_id), NULL, NULL, ARRAY['union_wallets', 'clubs']);
  UPDATE bbj_pools SET promo_balance = 0, updated_at = NOW() WHERE id = v_pool_id;

  IF v_union_id IS NOT NULL THEN
    INSERT INTO union_wallets (union_id, promo_wallet)
    VALUES (v_union_id, v_promo)
    ON CONFLICT (union_id) DO UPDATE
      SET promo_wallet = COALESCE(union_wallets.promo_wallet, 0) + EXCLUDED.promo_wallet
    RETURNING promo_wallet INTO v_after;
    PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);
    PERFORM set_config('app.ledger_autoskip_clubs', '', true);

    IF v_after IS NULL THEN
      UPDATE bbj_pools SET promo_balance = v_promo WHERE id = v_pool_id;
      RETURN jsonb_build_object('success', false, 'error', 'union wallet credit failed');
    END IF;

    UPDATE unions
       SET promo_funded_from_bbj = COALESCE(promo_funded_from_bbj, 0) + v_promo,
           updated_at = NOW()
     WHERE id = v_union_id;

    INSERT INTO union_wallet_transactions
      (union_id, club_id, wallet, direction, amount, balance_after, tx_type, notes)
    VALUES
      (v_union_id, p_club_id, 'promo_wallet', 'credit', v_promo, v_after,
       'bbj_promo_sweep', 'BBJ promo slice swept from pool (single-club sweep)');

    v_dest := 'union';
  ELSE
    UPDATE clubs
       SET promo_balance = COALESCE(promo_balance, 0) + v_promo, updated_at = NOW()
     WHERE id = p_club_id
    RETURNING promo_balance INTO v_after;
    PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);
    PERFORM set_config('app.ledger_autoskip_clubs', '', true);
    v_dest := 'club';

    INSERT INTO chip_transactions (
      id, club_id, from_user_id, to_user_id, amount,
      transaction_type, notes, balance_after, created_at
    ) VALUES (
      gen_random_uuid(), p_club_id, NULL, NULL, v_promo,
      'bbj_promo_sweep',
      'BBJ promo slice swept to club promo wallet (club has no union)',
      v_after, NOW()
    );
  END IF;

  RETURN jsonb_build_object('success', true, 'swept', v_promo,
                            'destination', v_dest, 'balance_after', v_after);
END $$;


ALTER FUNCTION public.fn_sweep_bbj_promo(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_sweep_bbj_promo(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sweep_bbj_promo(p_club_id uuid) IS 'Sweeps a pool promo slice to union_wallets.promo_wallet (the destination the union dashboard reads and fn_sweep_bbj_promo_all uses), or to clubs.promo_balance for a club with no union. Resolves union pools correctly - the old club_id-only lookup could never find one.';


--
-- Name: fn_sweep_bbj_promo_all(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sweep_bbj_promo_all() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  r record; v_promo numeric; v_union_id uuid; v_after numeric;
  v_swept numeric := 0; v_pools int := 0; v_to_union int := 0; v_to_club int := 0; v_err int := 0;
BEGIN
  FOR r IN SELECT id, club_id, union_id FROM bbj_pools
            WHERE COALESCE(promo_balance,0) > 0 ORDER BY id
  LOOP
    BEGIN
      SELECT COALESCE(promo_balance,0) INTO v_promo FROM bbj_pools WHERE id=r.id FOR UPDATE;
      IF v_promo <= 0 THEN CONTINUE; END IF;

      v_union_id := r.union_id;
      IF v_union_id IS NULL AND r.club_id IS NOT NULL THEN
        SELECT union_id INTO v_union_id FROM clubs WHERE id = r.club_id;
      END IF;

      -- CHIP STANDARD 1.3 (2026-09-02): one declared row per sweep, both sides named
      -- (see fn_sweep_bbj_promo). Inside the per-pool sub-transaction: an exception
      -- reverts the settings along with the writes.
      PERFORM public.fn_ca_declare_ledger('promo',
        CASE WHEN v_union_id IS NOT NULL THEN 'union_wallet' ELSE 'promo_wallet' END,
        COALESCE(v_union_id, r.club_id), NULL, NULL, ARRAY['union_wallets', 'clubs']);
      UPDATE bbj_pools SET promo_balance = 0, updated_at = NOW() WHERE id = r.id;

      IF v_union_id IS NOT NULL THEN
        INSERT INTO union_wallets (union_id, promo_wallet) VALUES (v_union_id, v_promo)
        ON CONFLICT (union_id) DO UPDATE
          SET promo_wallet = COALESCE(union_wallets.promo_wallet,0) + EXCLUDED.promo_wallet
        RETURNING promo_wallet INTO v_after;
        PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);
        PERFORM set_config('app.ledger_autoskip_clubs', '', true);

        IF v_after IS NULL THEN
          UPDATE bbj_pools SET promo_balance = v_promo WHERE id = r.id;
          v_err := v_err + 1; CONTINUE;
        END IF;

        UPDATE unions SET promo_funded_from_bbj = COALESCE(promo_funded_from_bbj,0) + v_promo,
                          updated_at = NOW()
         WHERE id = v_union_id;

        INSERT INTO union_wallet_transactions
          (id, union_id, wallet, direction, amount, balance_after, tx_type, club_id, notes, created_at)
        VALUES (gen_random_uuid(), v_union_id, 'promo_wallet', 'credit', v_promo, v_after,
                'bbj_promo_sweep', r.club_id,
                'BBJ promo slice (25% of contribution) swept from pool', NOW());
        v_to_union := v_to_union + 1;

      ELSIF r.club_id IS NOT NULL THEN
        UPDATE clubs SET promo_balance = COALESCE(promo_balance,0) + v_promo, updated_at = NOW()
         WHERE id = r.club_id RETURNING promo_balance INTO v_after;
        PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);
        PERFORM set_config('app.ledger_autoskip_clubs', '', true);
        IF v_after IS NULL THEN
          UPDATE bbj_pools SET promo_balance = v_promo WHERE id = r.id;
          v_err := v_err + 1; CONTINUE;
        END IF;
        INSERT INTO chip_transactions (id, club_id, from_user_id, to_user_id, amount,
                                       transaction_type, notes, balance_after, created_at)
        VALUES (gen_random_uuid(), r.club_id, NULL, NULL, v_promo, 'bbj_promo_sweep',
                'BBJ promo slice swept to club promo wallet (club has no union)', v_after, NOW());
        v_to_club := v_to_club + 1;
      ELSE
        UPDATE bbj_pools SET promo_balance = v_promo WHERE id = r.id;
        v_err := v_err + 1; CONTINUE;
      END IF;

      v_swept := v_swept + v_promo; v_pools := v_pools + 1;
    EXCEPTION WHEN OTHERS THEN v_err := v_err + 1;
    END;
  END LOOP;
  PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);
  PERFORM set_config('app.ledger_autoskip_clubs', '', true);

  RETURN jsonb_build_object('success', true, 'pools_swept', v_pools, 'total_swept', v_swept,
                            'to_union', v_to_union, 'to_club', v_to_club, 'errors', v_err);
END;
$$;


ALTER FUNCTION public.fn_sweep_bbj_promo_all() OWNER TO postgres;

--
-- Name: FUNCTION fn_sweep_bbj_promo_all(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sweep_bbj_promo_all() IS 'Sweeps the BBJ promo slice from every pool to its union promo wallet (or the club wallet for unionless clubs). Schedule this; it is idempotent - a second run with nothing accrued sweeps 0.';


--
-- Name: fn_sweep_pending_tournament_bounties(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sweep_pending_tournament_bounties(p_tournament_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  o public.tournament_bounty_obligations%ROWTYPE;
  candidate record;
  v_result jsonb;
  v_reserved jsonb;
  v_award_id uuid;
  v_processed integer := 0;
  v_settled integer := 0;
  v_failed integer := 0;
  v_settled_tournament_ids uuid[] := ARRAY[]::uuid[];
  v_recipients jsonb;
  v_op_hex text;
  v_op_id uuid;
  v_limit integer := GREATEST(1,LEAST(COALESCE(p_limit,20),100));
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  FOR candidate IN
    SELECT bo.id, bo.tournament_id FROM public.tournament_bounty_obligations bo
     WHERE bo.state = 'pending'
       AND bo.next_attempt_at <= now()
       AND (p_tournament_id IS NULL OR bo.tournament_id = p_tournament_id)
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_bounty_obligations prior
          WHERE prior.tournament_id=bo.tournament_id AND prior.state='pending'
            AND prior.mode='pko'
            AND (prior.hand_number < bo.hand_number
                 OR (prior.hand_number=bo.hand_number
                     AND prior.eliminated_user_id::text < bo.eliminated_user_id::text))
       )
     ORDER BY bo.next_attempt_at, bo.tournament_id, bo.hand_number,
              bo.eliminated_user_id
     LIMIT v_limit
  LOOP
    BEGIN
      -- One lock order everywhere: tournament then obligation. Direct manager
      -- collection also locks tournament before its ledger trigger touches the
      -- outbox, so the global lane cannot deadlock it outbox->tournament.
      PERFORM 1 FROM public.tournaments t WHERE t.id=candidate.tournament_id FOR UPDATE;
      SELECT * INTO o FROM public.tournament_bounty_obligations bo
       WHERE bo.id=candidate.id AND bo.state='pending' AND bo.next_attempt_at<=now()
       FOR UPDATE SKIP LOCKED;
      IF NOT FOUND THEN CONTINUE; END IF;
      -- The candidate query ran before these locks. Re-prove ordering after the
      -- tournament and exact obligation are locked so a predecessor committed
      -- in that window cannot be skipped.
      IF o.mode='pko' AND EXISTS (
        SELECT 1 FROM public.tournament_bounty_obligations prior
         WHERE prior.tournament_id=o.tournament_id AND prior.mode='pko'
           AND prior.state='pending'
           AND (prior.hand_number<o.hand_number
                OR (prior.hand_number=o.hand_number
                    AND prior.eliminated_user_id::text<o.eliminated_user_id::text))
      ) THEN
        CONTINUE;
      END IF;
      v_processed := v_processed + 1;

      -- Response-loss reconciliation before another call.
      IF o.mode <> 'mystery_chest'
         AND public.fn_bounty_obligation_has_complete_marker(o.id) THEN
        UPDATE public.tournament_bounty_obligations SET state='settled', settled_at=now(), last_error=NULL
         WHERE id=o.id;
        v_settled := v_settled + 1;
        IF NOT o.tournament_id=ANY(v_settled_tournament_ids) THEN
          v_settled_tournament_ids := array_append(v_settled_tournament_ids,o.tournament_id);
        END IF;
        CONTINUE;
      ELSIF o.mode = 'mystery_chest'
         AND public.fn_bounty_obligation_has_complete_marker(o.id) THEN
        UPDATE public.tournament_bounty_obligations SET state='settled', settled_at=now(), last_error=NULL
         WHERE id=o.id;
        v_settled := v_settled + 1;
        IF NOT o.tournament_id=ANY(v_settled_tournament_ids) THEN
          v_settled_tournament_ids := array_append(v_settled_tournament_ids,o.tournament_id);
        END IF;
        CONTINUE;
      END IF;

      IF o.mode = 'mystery_chest' THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
          'user_id', x.user_id, 'weight', x.weight,
          'is_designated_revealer', x.user_id = o.knocker_user_id
        )), '[]'::jsonb)
        INTO v_recipients
        FROM (
          SELECT (e->>'user_id')::uuid AS user_id,
                 GREATEST(COALESCE((e->>'weight')::numeric, 0), 0) AS weight
            FROM jsonb_array_elements(o.claimants) e
           WHERE NULLIF(e->>'user_id','') IS NOT NULL
        ) x;
        v_op_hex := md5('mb:' || o.id::text);
        v_op_id := (substr(v_op_hex,1,8)||'-'||substr(v_op_hex,9,4)||'-4'||substr(v_op_hex,14,3)
          ||'-8'||substr(v_op_hex,18,3)||'-'||substr(v_op_hex,21,12))::uuid;
        v_reserved := public.fn_mystery_bounty_reserve(
          o.tournament_id, o.eliminated_user_id, v_recipients, o.table_id,
          o.hand_id::text, v_op_id, 1);
        IF NOT COALESCE((v_reserved->>'ok')::boolean, false) THEN
          RAISE EXCEPTION 'reserve refused: %', COALESCE(v_reserved->>'reason','unknown');
        END IF;
        v_award_id := (v_reserved->>'award_id')::uuid;
        IF COALESCE(v_reserved->>'status','') <> 'completed' THEN
          v_result := public.fn_mystery_bounty_reveal(v_award_id, NULL, true);
          IF NOT COALESCE((v_result->>'ok')::boolean, false) THEN
            RAISE EXCEPTION 'reveal refused';
          END IF;
          v_result := public.fn_mystery_bounty_pay(v_award_id);
          IF NOT COALESCE((v_result->>'ok')::boolean, false)
             OR COALESCE((v_result->>'refused_recipients')::integer,0) > 0 THEN
            RAISE EXCEPTION 'pay refused or incomplete';
          END IF;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM public.tournament_bounty_awards a
                        WHERE a.bounty_obligation_id=o.id AND a.status='completed') THEN
          RAISE EXCEPTION 'mystery payout has no completed award marker';
        END IF;
      ELSE
        v_result := public.fn_collect_bounty_obligation(o.id);
        IF NOT COALESCE((v_result->>'ok')::boolean, false)
           AND COALESCE(v_result->>'reason','') <> 'already_collected' THEN
          RAISE EXCEPTION 'collect refused: %', COALESCE(v_result->>'reason','unknown');
        END IF;
        IF NOT public.fn_bounty_obligation_has_complete_marker(o.id) THEN
          RAISE EXCEPTION 'fixed/PKO payout markers do not conserve the full generation head';
        END IF;
      END IF;

      -- Triggers settle only after every canonical claimant (or the completed
      -- award) is durable. Never infer success from an RPC transport response.
      IF NOT EXISTS (SELECT 1 FROM public.tournament_bounty_obligations x
                      WHERE x.id=o.id AND x.state='settled') THEN
        RAISE EXCEPTION 'payout marker did not acknowledge obligation';
      END IF;
      UPDATE public.tournament_bounty_obligations
         SET last_error=NULL, attempt_count=attempt_count+1
       WHERE id=o.id;
      v_settled := v_settled + 1;
      IF NOT o.tournament_id=ANY(v_settled_tournament_ids) THEN
        v_settled_tournament_ids := array_append(v_settled_tournament_ids,o.tournament_id);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.tournament_bounty_obligations
       SET attempt_count=attempt_count+1, last_error=left(SQLERRM,1000),
             next_attempt_at=clock_timestamp()
               + make_interval(secs => LEAST(60, 5 * (attempt_count + 1)))
       WHERE id=candidate.id;
      v_failed := v_failed + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'processed', v_processed,
    'settled', v_settled, 'failed', v_failed,
    'settled_tournament_ids',to_jsonb(v_settled_tournament_ids),
    'pending', (SELECT count(*) FROM public.tournament_bounty_obligations
      WHERE state='pending' AND (p_tournament_id IS NULL OR tournament_id=p_tournament_id)),
    -- Return a DATABASE-CLOCK RELATIVE delay for the first order-eligible
    -- head. A later PKO row can have due=now while an earlier generation is
    -- backed off; using the raw minimum would spin the engine until the head
    -- became due. A host timestamp would repeat that bug under clock skew.
    'retry_after_ms',(
      SELECT CASE WHEN due_at IS NULL THEN NULL ELSE
        GREATEST(0,ceil(extract(epoch FROM (due_at-clock_timestamp()))*1000)::bigint)
      END
      FROM (
        SELECT min(bo.next_attempt_at) AS due_at
          FROM public.tournament_bounty_obligations bo
         WHERE bo.state='pending'
           AND (p_tournament_id IS NULL OR bo.tournament_id=p_tournament_id)
           AND NOT EXISTS (
             SELECT 1 FROM public.tournament_bounty_obligations prior
              WHERE prior.tournament_id=bo.tournament_id AND prior.state='pending'
                AND prior.mode='pko'
                AND (prior.hand_number<bo.hand_number
                     OR (prior.hand_number=bo.hand_number
                         AND prior.eliminated_user_id::text<bo.eliminated_user_id::text))
           )
      ) eligible_head
    ));
END;
$$;


ALTER FUNCTION public.fn_sweep_pending_tournament_bounties(p_tournament_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: fn_sweep_stale_waitlists(interval, interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sweep_stale_waitlists(p_offer_ttl interval DEFAULT '00:01:00'::interval, p_entry_ttl interval DEFAULT '24:00:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_offers_expired  int := 0;
  v_entries_expired int := 0;
  v_seated_retired  int := 0;
  v_reoffered       int := 0;
  v_tables          uuid[] := '{}';
  v_tid             uuid;
  v_res             jsonb;
BEGIN
  -- 1. LAPSED OFFERS. Judged by the row's own hold_expires_at, falling back to
  --    notified_at + TTL for rows written before the hold column existed.
  WITH dead AS (
    UPDATE public.table_waitlist w
       SET status = 'expired'
     WHERE w.status = 'notified'
       AND COALESCE(w.hold_expires_at, w.notified_at + p_offer_ttl) < now()
    RETURNING w.user_id, w.table_id
  ), ins AS (
    INSERT INTO public.notifications (user_id, type, title, message, data)
    SELECT d.user_id,
           'waitlist_offer_expired',
           'Seat Offer Expired',
           'Your Seat At ' || COALESCE(t.name, 'The Table') ||
             ' Went To The Next Player In Line. Join The Waitlist Again To Get Back In.',
           jsonb_build_object('table_id', d.table_id, '_push', 'skip')
      FROM dead d
      LEFT JOIN public.tables t ON t.id = d.table_id
    RETURNING 1
  )
  SELECT (SELECT count(*) FROM ins),
         COALESCE((SELECT array_agg(DISTINCT d.table_id) FROM dead d), '{}')
    INTO v_offers_expired, v_tables;

  -- 2. ABANDONED PLACES IN LINE.
  UPDATE public.table_waitlist
     SET status = 'expired'
   WHERE status = 'waiting'
     AND created_at < now() - p_entry_ttl;
  GET DIAGNOSTICS v_entries_expired = ROW_COUNT;

  -- 3. ALREADY SITTING.
  UPDATE public.table_waitlist w
     SET status = 'seated'
   WHERE w.status = 'waiting'
     AND EXISTS (
       SELECT 1 FROM public.table_seats s
        WHERE s.table_id = w.table_id
          AND s.left_at IS NULL
          AND s.user_id = w.user_id
     );
  GET DIAGNOSTICS v_seated_retired = ROW_COUNT;

  -- 4. STALLED QUEUES. Any table with people waiting and no live hold is a
  --    queue that is not moving. Include the tables we just expired an offer
  --    on, so the "went to the next player" notification is true.
  SELECT COALESCE(array_agg(DISTINCT tid), '{}')
    INTO v_tables
    FROM (
      SELECT unnest(v_tables) AS tid
      UNION
      SELECT w.table_id
        FROM public.table_waitlist w
       WHERE w.status = 'waiting'
         AND NOT EXISTS (
           SELECT 1 FROM public.table_waitlist h
            WHERE h.table_id = w.table_id
              AND h.status = 'notified'
              AND COALESCE(h.hold_expires_at, h.notified_at + p_offer_ttl) > now()
         )
       LIMIT 200
    ) s;

  -- 5. ADVANCE THE QUEUE through the ONE function that makes an offer.
  FOREACH v_tid IN ARRAY v_tables LOOP
    v_res := public.fn_offer_open_seat(v_tid, p_offer_ttl, p_entry_ttl);
    IF COALESCE((v_res ->> 'ok')::boolean, false) THEN
      v_reoffered := v_reoffered + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'offers_expired', v_offers_expired,
    'entries_expired', v_entries_expired,
    'seated_retired', v_seated_retired,
    'seats_reoffered', v_reoffered,
    'tables_scanned', COALESCE(array_length(v_tables, 1), 0)
  );
END
$$;


ALTER FUNCTION public.fn_sweep_stale_waitlists(p_offer_ttl interval, p_entry_ttl interval) OWNER TO postgres;

--
-- Name: FUNCTION fn_sweep_stale_waitlists(p_offer_ttl interval, p_entry_ttl interval); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sweep_stale_waitlists(p_offer_ttl interval, p_entry_ttl interval) IS 'Recurring half of the waitlist TTLs. Since 2026-08-31 it expires offers by hold_expires_at (60s default, matching fn_offer_open_seat) and then CALLS fn_offer_open_seat for every table it touched plus every table with a waiting queue and no live hold - so a lapsed offer actually moves to the next player instead of stalling the queue until someone cashes out.';


--
-- Name: fn_sweep_test_account(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sweep_test_account(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_email text;
  v_is_horse boolean;
  v_chips numeric;
  v_audit_count integer;
  v_archived_count integer;
  v_result jsonb;
BEGIN
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'platform_is_frozen');
  END IF;

  SELECT u.email, COALESCE(p.is_horse, false)
    INTO v_email, v_is_horse
    FROM auth.users u
    LEFT JOIN public.profiles p ON p.id = u.id
   WHERE u.id = p_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'already_removed');
  END IF;

  -- Repeat every safety gate that precedes the old audit refusal. Archiving
  -- must never become a side effect of a sweep the original body would deny.
  IF NOT (
       v_email ILIKE '%@probe.smarter.poker'
    OR v_email ILIKE '%@smarter-poker.invalid'
    OR v_email ILIKE '%@example.invalid'
    OR v_email ILIKE '%@yopmail.com'
    OR v_email ILIKE 'club-arena-%e2e%@smarter.poker'
    OR v_email ~ '^tester_[0-9a-f-]{36}@test\.com$'
    OR v_email ~ '^god_[0-9a-f-]{36}@test\.com$'
    OR v_email ~ '^logotest_[0-9_]+@example\.com$'
    OR v_email IN ('test@example.com', 'jetski_test_123@example.com')
  ) THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'address_is_not_a_test_pattern');
  END IF;
  IF v_is_horse THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'is_a_horse');
  END IF;
  SELECT COALESCE(sum(chip_balance), 0) INTO v_chips
    FROM public.club_members WHERE user_id = p_user_id;
  IF v_chips > 0 THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'holds_club_chips', 'chips', v_chips);
  END IF;
  IF EXISTS (SELECT 1 FROM public.table_seats WHERE user_id = p_user_id) THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'is_seated');
  END IF;
  IF EXISTS (SELECT 1 FROM public.clubs WHERE owner_id = p_user_id) THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'owns_a_club');
  END IF;
  IF EXISTS (SELECT 1 FROM public.diamond_purchases WHERE user_id = p_user_id) THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'bought_something_with_a_card');
  END IF;
  IF EXISTS (SELECT 1 FROM public.chip_ledger WHERE performed_by = p_user_id) THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'acted_on_the_chip_ledger');
  END IF;

  SELECT count(*) INTO v_audit_count
    FROM public.audit_trail WHERE actor_id = p_user_id;

  INSERT INTO public.ca_test_account_audit_archive
    (audit_id, actor_id, actor_email, audit_row)
  SELECT a.id, p_user_id, v_email, to_jsonb(a)
    FROM public.audit_trail a
   WHERE a.actor_id = p_user_id
  ON CONFLICT (audit_id) DO NOTHING;

  SELECT count(*) INTO v_archived_count
    FROM public.ca_test_account_audit_archive x
   WHERE x.audit_id IN (
     SELECT a.id FROM public.audit_trail a WHERE a.actor_id = p_user_id
   );
  IF v_archived_count <> v_audit_count THEN
    RAISE EXCEPTION
      'Refusing test-account deletion: archived % of % audit rows for %',
      v_archived_count, v_audit_count, p_user_id;
  END IF;

  DELETE FROM public.audit_trail WHERE actor_id = p_user_id;

  v_result := public.fn_sweep_test_account_after_audit_archive(p_user_id);
  IF COALESCE((v_result->>'swept')::boolean, false) IS NOT TRUE
     AND v_result->>'reason' <> 'already_removed' THEN
    RAISE EXCEPTION 'Guarded account deletion failed after audit archive: %', v_result;
  END IF;

  RETURN v_result || jsonb_build_object('audit_rows_archived', v_audit_count);
END;
$_$;


ALTER FUNCTION public.fn_sweep_test_account(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_sweep_test_account(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sweep_test_account(p_user_id uuid) IS 'Deletes one fully guarded machine-generated account. Audit rows are copied whole into ca_test_account_audit_archive and verified before deletion; all value, seat, ownership, purchase, horse and chip-ledger refusals remain.';


--
-- Name: fn_sweep_test_account_after_audit_archive(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sweep_test_account_after_audit_archive(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_email    text;
  v_profile  public.profiles%ROWTYPE;
  v_chips    numeric;
  v_pattern  text;
BEGIN
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'platform_is_frozen');
  END IF;

  SELECT email INTO v_email FROM auth.users WHERE id = p_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'already_removed');
  END IF;

  SELECT * INTO v_profile FROM public.profiles WHERE id = p_user_id FOR UPDATE;

  v_pattern := CASE
    WHEN v_email ILIKE '%@probe.smarter.poker'            THEN 'probe.smarter.poker'
    WHEN v_email ILIKE '%@smarter-poker.invalid'          THEN 'smarter-poker.invalid'
    WHEN v_email ILIKE '%@example.invalid'                THEN 'example.invalid'
    WHEN v_email ILIKE '%@yopmail.com'                    THEN 'yopmail.com'
    WHEN v_email ILIKE 'club-arena-%e2e%@smarter.poker'   THEN 'club-arena e2e'
    WHEN v_email ~ '^tester_[0-9a-f-]{36}@test\.com$'     THEN 'tester_<uuid>'
    WHEN v_email ~ '^god_[0-9a-f-]{36}@test\.com$'        THEN 'god_<uuid>'
    WHEN v_email ~ '^logotest_[0-9_]+@example\.com$'      THEN 'logotest_<n>'
    WHEN v_email IN ('test@example.com','jetski_test_123@example.com') THEN 'named fixture'
    ELSE NULL END;
  IF v_pattern IS NULL THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'address_is_not_a_test_pattern',
                              'email', v_email);
  END IF;

  IF COALESCE(v_profile.is_horse, false) THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'is_a_horse', 'email', v_email);
  END IF;

  SELECT COALESCE(sum(chip_balance), 0) INTO v_chips
    FROM public.club_members WHERE user_id = p_user_id;
  IF v_chips > 0 THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'holds_club_chips', 'chips', v_chips);
  END IF;
  IF EXISTS (SELECT 1 FROM public.table_seats WHERE user_id = p_user_id) THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'is_seated');
  END IF;
  IF EXISTS (SELECT 1 FROM public.clubs WHERE owner_id = p_user_id) THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'owns_a_club');
  END IF;
  IF EXISTS (SELECT 1 FROM public.diamond_purchases WHERE user_id = p_user_id) THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'bought_something_with_a_card');
  END IF;

  IF EXISTS (SELECT 1 FROM public.chip_ledger WHERE performed_by = p_user_id) THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'acted_on_the_chip_ledger');
  END IF;
  IF EXISTS (SELECT 1 FROM public.audit_trail WHERE actor_id = p_user_id) THEN
    RETURN jsonb_build_object('swept', false, 'reason', 'appears_in_the_audit_trail');
  END IF;

  PERFORM set_config('app.ledger_maintenance',
                     'test-account-sweep:20260905174801:' || p_user_id::text, true);
  PERFORM set_config('app.game_management_retention', 'on', true);

  DELETE FROM public.user_daily_challenges  WHERE user_id = p_user_id;
  DELETE FROM public.challenge_streak_state WHERE user_id = p_user_id;
  DELETE FROM public.club_members           WHERE user_id = p_user_id;

  DELETE FROM public.table_waitlist WHERE user_id  = p_user_id;
  DELETE FROM public.notifications  WHERE actor_id = p_user_id;

  DELETE FROM auth.users WHERE id = p_user_id;

  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'Profile % survived the delete of its auth user', p_user_id;
  END IF;

  RETURN jsonb_build_object('swept', true, 'email', v_email, 'pattern', v_pattern);
END;
$_$;


ALTER FUNCTION public.fn_sweep_test_account_after_audit_archive(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_sweep_test_account_after_audit_archive(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sweep_test_account_after_audit_archive(p_user_id uuid) IS 'Removes ONE machine-generated test account, refusing a horse, a chip or seat holder, a club owner, a card buyer, anyone on chip_ledger or audit_trail, any address outside the known fixture patterns, and any call made while the platform is frozen. Declares app.ledger_maintenance so the diamond journal is archived rather than refused. Idempotent. The profile BEFORE DELETE trigger writes the permanent record; this function is the gate in front of it.';


--
-- Name: fn_sweep_unsettled_tournament_rake(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sweep_unsettled_tournament_rake(p_since_days integer DEFAULT 45, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row record; v_res jsonb;
  v_settled integer := 0; v_chips numeric := 0; v_scanned integer := 0; v_failed integer := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  FOR v_row IN
    SELECT t.id
      FROM public.tournaments t
     WHERE upper(COALESCE(t.status, '')) IN ('COMPLETED', 'CANCELLED', 'CANCELED')
       AND t.ended_at IS NOT NULL
       AND t.ended_at > now() - make_interval(days => GREATEST(p_since_days, 1))
       AND t.ended_at < now() - interval '10 minutes'   -- never race a live finish
       AND EXISTS (SELECT 1 FROM public.rake_records r
                    WHERE r.tournament_id = t.id AND r.is_tournament)
       AND NOT EXISTS (SELECT 1 FROM public.tournament_rake_settlements s
                        WHERE s.tournament_id = t.id)
     ORDER BY t.ended_at ASC
     LIMIT GREATEST(p_limit, 1)
  LOOP
    v_scanned := v_scanned + 1;
    BEGIN
      v_res := public.fn_settle_tournament_rake(v_row.id, 'sweep');
      IF COALESCE((v_res->>'ok')::boolean, false)
         AND NOT COALESCE((v_res->>'already_settled')::boolean, false) THEN
        v_settled := v_settled + 1;
        v_chips := v_chips + COALESCE((v_res->>'amount')::numeric, 0);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      INSERT INTO public.financial_alerts (severity, source, message, context)
      VALUES ('warning', 'fn_sweep_unsettled_tournament_rake',
              'Sweep could not settle tournament rake: ' || SQLERRM,
              jsonb_build_object('tournament_id', v_row.id));
    END;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'scanned', v_scanned,
    'settled', v_settled, 'chips', round(v_chips, 2), 'failed', v_failed);
END;
$$;


ALTER FUNCTION public.fn_sweep_unsettled_tournament_rake(p_since_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: fn_sync_agent_player_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_agent_player_counts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF (TG_OP = 'UPDATE' OR TG_OP = 'DELETE') AND OLD.agent_id IS NOT NULL THEN
    UPDATE agents a SET
      total_players = (SELECT count(*) FROM club_members cm
                       WHERE cm.agent_id = OLD.agent_id AND cm.club_id = OLD.club_id),
      active_player_count = (SELECT count(*) FROM club_members cm
                       WHERE cm.agent_id = OLD.agent_id AND cm.club_id = OLD.club_id AND cm.is_active IS TRUE)
    WHERE a.user_id = OLD.agent_id AND a.club_id = OLD.club_id;
  END IF;

  IF (TG_OP = 'INSERT' OR TG_OP = 'UPDATE') AND NEW.agent_id IS NOT NULL THEN
    UPDATE agents a SET
      total_players = (SELECT count(*) FROM club_members cm
                       WHERE cm.agent_id = NEW.agent_id AND cm.club_id = NEW.club_id),
      active_player_count = (SELECT count(*) FROM club_members cm
                       WHERE cm.agent_id = NEW.agent_id AND cm.club_id = NEW.club_id AND cm.is_active IS TRUE)
    WHERE a.user_id = NEW.agent_id AND a.club_id = NEW.club_id;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_sync_agent_player_counts() OWNER TO postgres;

--
-- Name: fn_sync_club_announcement_message(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_club_announcement_message() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    NEW.content:=COALESCE(NEW.content,NEW.message,'');
    NEW.message:=NEW.content;
  ELSIF NEW.content IS DISTINCT FROM OLD.content THEN
    NEW.message:=NEW.content;
  ELSIF NEW.message IS DISTINCT FROM OLD.message THEN
    NEW.content:=COALESCE(NEW.message,'');
  END IF;
  IF char_length(NEW.title)>100 OR char_length(NEW.content)>2000 THEN
    RAISE EXCEPTION 'Club announcement exceeds its display character limit' USING ERRCODE='22001';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_sync_club_announcement_message() OWNER TO postgres;

--
-- Name: fn_sync_club_member_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_club_member_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_club uuid; v_union uuid;
BEGIN
  FOR v_club IN
    SELECT DISTINCT x FROM unnest(ARRAY[
      CASE WHEN TG_OP <> 'DELETE' THEN NEW.club_id END,
      CASE WHEN TG_OP <> 'INSERT' THEN OLD.club_id END
    ]) AS t(x) WHERE x IS NOT NULL
  LOOP
    PERFORM public.fn_apply_club_ladder(v_club);
    FOR v_union IN
      SELECT uc.union_id FROM public.union_clubs uc WHERE uc.club_id = v_club
    LOOP
      PERFORM public.fn_apply_union_ladder(v_union);
    END LOOP;
  END LOOP;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.fn_sync_club_member_count() OWNER TO postgres;

--
-- Name: FUNCTION fn_sync_club_member_count(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sync_club_member_count() IS 'Keeps clubs.member_count equal to the number of active/approved club_members rows. Added 2026-08-26: ClubsService had claimed this trigger existed since before it was written, and the counter had drifted upward on every club because only one of three join paths incremented it and nothing decremented it.';


--
-- Name: fn_sync_club_table_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_club_table_counts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_clubs uuid[];
  v_unions uuid[];
BEGIN
  -- Both sides, so a table MOVING between clubs or unions fixes the club it
  -- left as well as the one it joined.
  v_clubs := array_remove(ARRAY[
    CASE WHEN TG_OP <> 'DELETE' THEN NEW.club_id END,
    CASE WHEN TG_OP <> 'INSERT' THEN OLD.club_id END
  ], NULL);
  v_unions := array_remove(ARRAY[
    CASE WHEN TG_OP <> 'DELETE' THEN NEW.union_id END,
    CASE WHEN TG_OP <> 'INSERT' THEN OLD.union_id END
  ], NULL);

  IF cardinality(v_clubs) > 0 THEN
    UPDATE clubs SET table_count = fn_live_table_count(id) WHERE id = ANY(v_clubs);
  END IF;

  -- Every club that can see a touched union's tables (members + the union row).
  IF cardinality(v_unions) > 0 THEN
    UPDATE clubs SET table_count = fn_live_table_count(id)
     WHERE id = ANY(v_unions)
        OR id IN (SELECT club_id FROM union_clubs WHERE union_id = ANY(v_unions));
  END IF;

  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_sync_club_table_counts() OWNER TO postgres;

--
-- Name: FUNCTION fn_sync_club_table_counts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sync_club_table_counts() IS 'Recomputes clubs.table_count. Reached by three triggers on public.tables (ins/del/upd) and one on public.union_clubs. The UPDATE one carries an IS DISTINCT FROM guard: `AFTER UPDATE OF status` fires whenever status is in the SET list, and the engine writes status alongside current_players once per hand, which made this trigger 40% of all database time on 2026-08-20. Do not merge these back into one trigger. fn_reconcile_club_table_counts() is the nightly backstop for anything these miss.';


--
-- Name: fn_sync_club_union_mirror(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_club_union_mirror() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE clubs
       SET union_id = NEW.union_id,
           club_commission_rate = COALESCE(NEW.club_commission_rate, club_commission_rate)
     WHERE id = NEW.club_id;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE clubs SET union_id = NULL
     WHERE id = OLD.club_id AND union_id = OLD.union_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_sync_club_union_mirror() OWNER TO postgres;

--
-- Name: fn_sync_home_game_vouch_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_home_game_vouch_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE public.commander_home_groups
           SET vouch_count = vouch_count + 1
         WHERE id = NEW.group_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE public.commander_home_groups
           SET vouch_count = GREATEST(0, vouch_count - 1)
         WHERE id = OLD.group_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_sync_home_game_vouch_count() OWNER TO postgres;

--
-- Name: fn_sync_mfa_required_on_club_owner(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_mfa_required_on_club_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF NEW.owner_id IS NOT NULL THEN
        UPDATE public.profiles
           SET mfa_required = TRUE
         WHERE id = NEW.owner_id
           AND mfa_required = FALSE;
    END IF;
    RETURN NEW;
END;
$$;


