--
-- Name: FUNCTION fn_sync_mfa_required_on_club_owner(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sync_mfa_required_on_club_owner() IS 'Phase 6.1.28: when a club owner is assigned (insert) or changed (UPDATE owner_id), flip the new owner''s profiles.mfa_required=TRUE.';


--
-- Name: fn_sync_mfa_required_on_club_role(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_mfa_required_on_club_role() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF NEW.role IN ('owner', 'co_owner', 'admin', 'manager', 'agent') THEN
        UPDATE public.profiles
           SET mfa_required = TRUE
         WHERE id = NEW.user_id
           AND mfa_required = FALSE;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_sync_mfa_required_on_club_role() OWNER TO postgres;

--
-- Name: FUNCTION fn_sync_mfa_required_on_club_role(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sync_mfa_required_on_club_role() IS 'Phase 6.1.28: when a user gains a cashout-capable role on a club, flip profiles.mfa_required=TRUE. Never flips back — an explicit admin UPDATE is required to un-set.';


--
-- Name: fn_sync_mfa_required_on_role_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_mfa_required_on_role_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF (NEW.role = 'admin' OR NEW.is_vip = TRUE) AND NOT NEW.mfa_required THEN
        -- Only force the login challenge if the user can actually pass it.
        IF EXISTS (
            SELECT 1 FROM public.user_mfa_factors
            WHERE user_id = NEW.id AND enabled = TRUE
        ) THEN
            NEW.mfa_required := TRUE;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_sync_mfa_required_on_role_change() OWNER TO postgres;

--
-- Name: fn_sync_profile_total_hands(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_profile_total_hands() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := COALESCE(NEW.user_id, OLD.user_id);
BEGIN
  IF v_user IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  /* Recomputed from the table rather than incremented. An increment has to be
     right on every path - insert, update, delete, and the upsert the
     achievement engine uses - and being wrong once is permanent. A SUM over a
     handful of club rows for one player is cheap and cannot drift. */
  UPDATE public.profiles p
     SET total_hands_played = COALESCE((
           SELECT sum(s.hands_played) FROM public.player_stats s WHERE s.user_id = v_user
         ), 0)
   WHERE p.id = v_user;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.fn_sync_profile_total_hands() OWNER TO postgres;

--
-- Name: FUNCTION fn_sync_profile_total_hands(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sync_profile_total_hands() IS 'Keeps profiles.total_hands_played equal to SUM(player_stats.hands_played) for that player. Recomputes rather than increments: an increment must be correct on every path and is permanent when it is not.';


--
-- Name: fn_sync_profile_vip_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_profile_vip_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_is_vip     boolean;
  v_vip_tier   text;
  v_expires_at timestamptz;
BEGIN
  SELECT vs.tier, vs.current_period_end
    INTO v_vip_tier, v_expires_at
    FROM vip_subscriptions vs
   WHERE vs.user_id = NEW.user_id
     AND vs.status IN ('active', 'trialing')
     AND vs.current_period_end > NOW()
   ORDER BY CASE vs.tier
              WHEN 'gold'   THEN 3
              WHEN 'silver' THEN 2
              ELSE 1
            END DESC
   LIMIT 1;

  v_is_vip := v_vip_tier IS NOT NULL;

  UPDATE profiles
     SET is_vip         = v_is_vip,
         vip_tier       = COALESCE(v_vip_tier, 'none'),
         vip_expires_at = v_expires_at
   WHERE id = NEW.user_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_sync_profile_vip_status() OWNER TO postgres;

