--
-- Name: fn_sync_seat_first_player_count(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_seat_first_player_count(p_tournament_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_table      uuid;
  v_seats      integer := 0;
  v_seat_first boolean := false;
  v_is_spin    boolean := false;
  v_cap        integer := 0;
  v_variant    text := '';
  v_book       jsonb;
BEGIN
  -- This is an AFTER-seat helper. It must never acquire a new global lock
  -- after PostgreSQL already owns the changed seat row. Every legitimate
  -- create/revive root pre-acquires terminal -> mission -> launch -> tournament,
  -- and the earliest BEFORE trigger refuses a raw writer that did not.
  SELECT (lower(COALESCE(t.variant, '')) = 'spin'
          OR COALESCE(t.max_players, 0) <= 2),
         lower(COALESCE(t.variant, '')) = 'spin',
         COALESCE(t.max_players, 0),
         COALESCE(t.variant, '')
    INTO v_seat_first, v_is_spin, v_cap, v_variant
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Freeze the complete table/seat set before choosing the occupied table.
  -- UUID order is deterministic across every transaction using this owner.
  PERFORM tb.id
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
     AND lower(COALESCE(tb.status, '')) <> 'closed'
   ORDER BY tb.id
   FOR UPDATE;

  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id
     AND lower(COALESCE(tb.status, '')) <> 'closed'
     AND s.left_at IS NULL
   ORDER BY s.table_id, s.seat_number, s.id
   FOR UPDATE OF s;

  v_table := public.fn_tournament_primary_table(p_tournament_id);

  IF v_table IS NULL THEN
    IF COALESCE(v_seat_first, false) THEN
      SELECT count(*) INTO v_seats
        FROM public.table_seats s
        JOIN public.tables tb ON tb.id = s.table_id
       WHERE tb.tournament_id = p_tournament_id
         AND s.left_at IS NULL;
      UPDATE public.tournaments SET current_players = v_seats
       WHERE id = p_tournament_id
         AND current_players IS DISTINCT FROM v_seats;
      RETURN v_seats;
    END IF;
    RETURN NULL;
  END IF;

  SELECT count(*) INTO v_seats
    FROM public.table_seats
   WHERE table_id = v_table AND left_at IS NULL;

  UPDATE public.tables SET current_players = v_seats
   WHERE id = v_table
     AND current_players IS DISTINCT FROM v_seats;

  IF COALESCE(v_seat_first, false) THEN
    UPDATE public.tournaments SET current_players = v_seats
     WHERE id = p_tournament_id
       AND current_players IS DISTINCT FROM v_seats;
  END IF;

  IF v_is_spin AND v_cap > 0 AND v_seats >= v_cap THEN
    v_book := public.fn_spin_book_entry(p_tournament_id);
    IF COALESCE((v_book->>'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'paid third seat could not book Spin %: %',
        p_tournament_id,v_book USING ERRCODE = 'P0404';
    END IF;
  END IF;

  IF COALESCE(v_seat_first, false)
     AND v_cap > 0 AND v_seats >= v_cap THEN
    BEGIN
      PERFORM realtime.send(
        jsonb_build_object(
          'tournament_id', p_tournament_id,
          'variant', v_variant,
          'max_players', v_cap,
          'paid_seats', v_seats,
          'filled_at', now()
        ),
        'seat_first_ready',
        'seat_first',
        false
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING
        'fn_sync_seat_first_player_count: realtime.send failed for %: %',
        p_tournament_id, SQLERRM;
    END;
  END IF;

  RETURN v_seats;
END;
$$;


ALTER FUNCTION public.fn_sync_seat_first_player_count(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_sync_seat_first_player_count(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sync_seat_first_player_count(p_tournament_id uuid) IS 'Owner-only AFTER-seat invariant. The true seat root owns terminal/mission/launch/tournament locks before row DML; this helper never acquires a late global lock. Paid-third-seat booking refusal propagates.';


--
-- Name: fn_sync_share_streak_multiplier(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_share_streak_multiplier(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_today         DATE         := (now() AT TIME ZONE 'America/Chicago')::DATE;
    v_yesterday     DATE         := v_today - 1;
    v_streak_days   INTEGER      := 0;
    v_multiplier    DECIMAL(4,2) := 1.00;
    v_has_active    BOOLEAN      := false;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM public.share_events
        WHERE user_id = p_user_id
          AND (created_at AT TIME ZONE 'America/Chicago')::DATE >= v_yesterday
    ) INTO v_has_active;

    IF v_has_active THEN
        WITH daily_shares AS (
            SELECT date_trunc('day', created_at AT TIME ZONE 'America/Chicago')::DATE AS share_day
            FROM public.share_events
            WHERE user_id = p_user_id
            GROUP BY share_day
        ),
        numbered AS (
            SELECT
                share_day,
                share_day - (ROW_NUMBER() OVER (ORDER BY share_day DESC) * INTERVAL '1 day')::DATE AS grp
            FROM daily_shares
            WHERE share_day <= v_today
        ),
        current_streak AS (
            SELECT COUNT(*) AS streak_days
            FROM numbered
            WHERE grp = (
                SELECT grp FROM numbered
                WHERE share_day >= v_yesterday
                ORDER BY share_day DESC
                LIMIT 1
            )
        )
        SELECT streak_days INTO v_streak_days FROM current_streak;
    END IF;

    IF v_streak_days >= 30 THEN v_multiplier := 2.00;
    ELSIF v_streak_days >= 14 THEN v_multiplier := 1.75;
    ELSIF v_streak_days >= 7 THEN v_multiplier := 1.50;
    ELSIF v_streak_days >= 3 THEN v_multiplier := 1.20;
    ELSE v_multiplier := 1.00;
    END IF;

    UPDATE public.profiles
    SET diamond_multiplier = v_multiplier,
        updated_at = now()
    WHERE id = p_user_id
      AND COALESCE(diamond_multiplier, 1.00) != v_multiplier;
END;
$$;


ALTER FUNCTION public.fn_sync_share_streak_multiplier(p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_sync_tournament_current_players(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_tournament_current_players() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tid uuid;
  v_count integer;
BEGIN
  v_tid := COALESCE(NEW.tournament_id, OLD.tournament_id);
  IF v_tid IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT count(*) INTO v_count
  FROM public.tournament_players
  WHERE tournament_id = v_tid
    AND status IN ('registered', 'playing');

  UPDATE public.tournaments
     SET current_players = v_count
   WHERE id = v_tid
     AND status IN ('ANNOUNCED', 'REGISTERING')
     AND current_players IS DISTINCT FROM v_count;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.fn_sync_tournament_current_players() OWNER TO postgres;

--
-- Name: FUNCTION fn_sync_tournament_current_players(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sync_tournament_current_players() IS 'Recomputes tournaments.current_players from tournament_players rows while the game is pre-start. Added 2026-08-23: the hand-maintained counter drifted, which both invited a fourth entrant into a three-handed Spin and left full games unable to start.';


--
-- Name: fn_sync_union_membership_table_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_union_membership_table_counts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_unions uuid[]; v_clubs uuid[];
BEGIN
  v_unions := array_remove(ARRAY[
    CASE WHEN TG_OP <> 'DELETE' THEN NEW.union_id END,
    CASE WHEN TG_OP <> 'INSERT' THEN OLD.union_id END
  ], NULL);
  v_clubs := array_remove(ARRAY[
    CASE WHEN TG_OP <> 'DELETE' THEN NEW.club_id END,
    CASE WHEN TG_OP <> 'INSERT' THEN OLD.club_id END
  ], NULL);

  UPDATE clubs SET table_count = fn_live_table_count(id)
   WHERE id = ANY(v_clubs)
      OR id = ANY(v_unions)
      OR id IN (SELECT club_id FROM union_clubs WHERE union_id = ANY(v_unions));
  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_sync_union_membership_table_counts() OWNER TO postgres;

--
-- Name: fn_table_chat_is_silenced(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_table_chat_is_silenced(p_table_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    COALESCE((
      SELECT true
        FROM public.tables t
        LEFT JOIN public.tournaments tr ON tr.id = t.tournament_id
       WHERE t.id = p_table_id
         AND (t.ban_chat IS TRUE OR tr.ban_chat IS TRUE)
       LIMIT 1
    ), false)
    OR
    COALESCE((
      SELECT true
        FROM public.table_chat_mutes m
       WHERE m.table_id = p_table_id
         AND m.user_id = auth.uid()
         AND m.expires_at > now()
       LIMIT 1
    ), false);
$$;


ALTER FUNCTION public.fn_table_chat_is_silenced(p_table_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_table_chat_is_silenced(p_table_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_table_chat_is_silenced(p_table_id uuid) IS 'True when the caller may not post in this table chat: the table has ban_chat, its parent tournament has ban_chat, or the caller holds an unexpired table_chat_mutes row. SECURITY DEFINER because table_chat_mutes is admin-read-only, so an inline RLS subquery would be blind to exactly the people it must stop. Answers about the caller only.';


--
-- Name: fn_table_lifecycle_pass(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_table_lifecycle_pass() RETURNS TABLE(action text, table_id uuid, table_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r      record;
  v_new  uuid;
  v_n    integer;
  v_name text;
BEGIN
  -- ── AUTO RESTART: reopen a closed table whose host asked for it ──────────
  -- Never a tournament table (those close on purpose, at the end of a game),
  -- never a deleted one, never a template, and never (H1, 2026-09-04) the
  -- Main 1 of a cash game its host has closed.
  FOR r IN
    SELECT t.id, t.name FROM public.tables t
     WHERE COALESCE(t.auto_restart, false)
       AND t.status = 'closed'
       AND t.tournament_id IS NULL
       AND COALESCE(t.is_deleted, false) = false
       AND COALESCE(t.is_template, false) = false
       AND NOT EXISTS (SELECT 1 FROM public.cash_games g
                        WHERE g.id = t.cluster_id AND NOT g.enabled)
     LIMIT 50
  LOOP
    UPDATE public.tables
       SET status = 'waiting', current_players = 0, updated_at = now()
     WHERE id = r.id AND status = 'closed';
    action := 'restarted'; table_id := r.id; table_name := r.name; RETURN NEXT;
  END LOOP;

  -- ── AUTO CREATE TABLE: a sibling when this one is within a seat of full ──
  -- Capped at 3 in a family, the same ceiling spawnOverflowTables uses, so a
  -- busy night cannot fill the lobby with clones. The name is suffixed rather
  -- than duplicated, so the family is recognisable on the board.
  FOR r IN
    SELECT t.id, t.name, t.club_id, t.max_players,
           (SELECT count(*) FROM public.table_seats s
             WHERE s.table_id = t.id AND s.left_at IS NULL) AS taken
      FROM public.tables t
     WHERE COALESCE(t.auto_create_table, false)
       AND t.tournament_id IS NULL
       AND COALESCE(t.is_deleted, false) = false
       AND COALESCE(t.is_template, false) = false
       AND t.status IN ('active', 'waiting', 'running')
       AND COALESCE(t.max_players, 0) > 0
     LIMIT 50
  LOOP
    CONTINUE WHEN r.taken < GREATEST(r.max_players - 1, 1);

    -- The family is this table and anything already spawned from it.
    SELECT count(*)::int INTO v_n FROM public.tables f
     WHERE f.club_id = r.club_id
       AND COALESCE(f.is_deleted, false) = false
       AND f.status IN ('active', 'waiting', 'running')
       AND (f.name = split_part(r.name, ' #', 1)
            OR f.name LIKE split_part(r.name, ' #', 1) || ' #%');
    CONTINUE WHEN v_n >= 3;

    -- Only spawn when EVERY table in the family is near full. One quiet
    -- sibling means the demand is already served.
    IF EXISTS (
      SELECT 1 FROM public.tables f
       WHERE f.club_id = r.club_id
         AND COALESCE(f.is_deleted, false) = false
         AND f.status IN ('active', 'waiting', 'running')
         AND (f.name = split_part(r.name, ' #', 1)
              OR f.name LIKE split_part(r.name, ' #', 1) || ' #%')
         AND (SELECT count(*) FROM public.table_seats s
               WHERE s.table_id = f.id AND s.left_at IS NULL)
             < GREATEST(COALESCE(f.max_players, 0) - 1, 1)
    ) THEN
      CONTINUE;
    END IF;

    v_name := split_part(r.name, ' #', 1) || ' #' || (v_n + 1)::text;
    BEGIN
      v_new := public.fn_clone_table_row(r.id, v_name);
      UPDATE public.tables SET status = 'waiting' WHERE id = v_new;
      action := 'created'; table_id := v_new; table_name := v_name; RETURN NEXT;
    EXCEPTION WHEN unique_violation THEN
      -- Two cycles racing for the same name is expected and harmless.
      NULL;
    END;
  END LOOP;
END;
$$;


ALTER FUNCTION public.fn_table_lifecycle_pass() OWNER TO postgres;

--
-- Name: fn_tables_autostart_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tables_autostart_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.tournament_id IS NULL
     AND NEW.auto_start_players IS NOT NULL
     AND NEW.max_players IS NOT NULL
     AND NEW.auto_start_players > NEW.max_players THEN
    RAISE EXCEPTION
      'auto_start_players (%) cannot exceed max_players (%) - the table would never deal',
      NEW.auto_start_players, NEW.max_players;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_tables_autostart_guard() OWNER TO postgres;

--
-- Name: fn_tables_creation_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tables_creation_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_variant text := lower(coalesce(NEW.game_variant, 'nlh'));
  v_cap integer;
  v_name text;
BEGIN
  -- ── name hygiene ──
  v_name := btrim(coalesce(NEW.name, ''));
  v_name := replace(replace(v_name, '<', ''), '>', '');
  IF length(v_name) = 0 THEN
    RAISE EXCEPTION 'table name is required';
  END IF;
  IF length(v_name) > 60 THEN
    v_name := left(v_name, 60);
  END IF;
  NEW.name := v_name;

  -- ── action time ──
  IF NEW.action_time_seconds IS NOT NULL
     AND (NEW.action_time_seconds < 10 OR NEW.action_time_seconds > 120) THEN
    RAISE EXCEPTION 'action_time_seconds must be between 10 and 120 (got %)', NEW.action_time_seconds;
  END IF;

  IF coalesce(NEW.game_type, '') = 'cash' THEN
    -- ── seat law ──
    v_cap := CASE v_variant
               WHEN 'plo6' THEN 6
               WHEN 'plo5' THEN 7
               WHEN 'plo4' THEN 8
               WHEN 'plo8' THEN 8
               WHEN 'flo8' THEN 8
               ELSE 9
             END;
    IF coalesce(NEW.max_players, 0) < 2 THEN
      RAISE EXCEPTION 'a cash table needs at least 2 seats (got %)', NEW.max_players;
    END IF;
    IF NEW.max_players > v_cap THEN
      RAISE EXCEPTION 'seat law: % allows at most % seats (got %) - the deck cannot fund three run-it boards above that',
        v_variant, v_cap, NEW.max_players;
    END IF;

    -- ── blinds ──
    IF coalesce(NEW.small_blind, 0) <= 0 OR coalesce(NEW.big_blind, 0) <= 0 THEN
      RAISE EXCEPTION 'blinds must be positive (sb=%, bb=%)', NEW.small_blind, NEW.big_blind;
    END IF;
    IF NEW.big_blind <= NEW.small_blind THEN
      RAISE EXCEPTION 'big blind must exceed small blind (sb=%, bb=%)', NEW.small_blind, NEW.big_blind;
    END IF;

    -- ── buy-in order ──
    IF NEW.min_buy_in IS NOT NULL AND NEW.max_buy_in IS NOT NULL
       AND NEW.min_buy_in > NEW.max_buy_in THEN
      RAISE EXCEPTION 'min_buy_in (%) cannot exceed max_buy_in (%)', NEW.min_buy_in, NEW.max_buy_in;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_tables_creation_guard() OWNER TO postgres;

--
-- Name: fn_tables_sync_rit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tables_sync_rit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  -- If only one was provided, mirror to the other. If both differ, prefer
  -- whichever was just changed: when run_it_twice changed, copy to enabled;
  -- otherwise copy enabled → run_it_twice.
  IF TG_OP = 'INSERT' THEN
    IF NEW.run_it_twice_enabled IS NULL AND NEW.run_it_twice IS NOT NULL THEN
      NEW.run_it_twice_enabled := NEW.run_it_twice;
    ELSIF NEW.run_it_twice IS NULL AND NEW.run_it_twice_enabled IS NOT NULL THEN
      NEW.run_it_twice := NEW.run_it_twice_enabled;
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    -- Detect which side changed and mirror to the other.
    IF NEW.run_it_twice IS DISTINCT FROM OLD.run_it_twice
       AND NEW.run_it_twice_enabled IS NOT DISTINCT FROM OLD.run_it_twice_enabled THEN
      NEW.run_it_twice_enabled := NEW.run_it_twice;
    ELSIF NEW.run_it_twice_enabled IS DISTINCT FROM OLD.run_it_twice_enabled
          AND NEW.run_it_twice IS NOT DISTINCT FROM OLD.run_it_twice THEN
      NEW.run_it_twice := NEW.run_it_twice_enabled;
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_tables_sync_rit() OWNER TO postgres;

--
-- Name: fn_take_seat_and_buy_in(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_take_seat_and_buy_in(p_table_id uuid, p_seat_number integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_gate jsonb;
BEGIN
  v_gate:=public.fn_ca_lock_tournament_seat_acquisition(
    NULL,p_table_id,auth.uid());
  IF COALESCE((v_gate->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_gate;
  END IF;
  RETURN public.fn_take_seat_and_buy_in_before_terminal_seat_gate(
    p_table_id,p_seat_number);
END;
$$;


ALTER FUNCTION public.fn_take_seat_and_buy_in(p_table_id uuid, p_seat_number integer) OWNER TO postgres;

--
-- Name: fn_take_seat_and_buy_in_before_maintenance_announcement_gate(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_take_seat_and_buy_in_before_maintenance_announcement_gate(p_table_id uuid, p_seat_number integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_tbl        record;
  v_t          record;
  v_reg        jsonb;
  v_seat_cap   integer;
  v_taken      integer;
  v_mine       integer;
  v_stack      numeric;
  v_err        text;
BEGIN
  PERFORM set_config('app.money_path', 'fn_take_seat_and_buy_in', true); -- CHIP STANDARD C2: sanctioned seat creator (trg_ca_guard_seat_creation)
  -- ── A DEAD SESSION MOVES NO MONEY (Dan 2026-09-03) ────────────────────
  -- "I WAS LOGGED OUT, BUT SOMEHOW ABLE TO SIT DOWN AND BUY CHIPS AND GET
  -- DEALT A HAND. THAT CAN NEVER HAPPEN." It could, because this project
  -- issues SEVEN-DAY access tokens and PostgREST verifies a JWT locally -
  -- signature and exp only. It never asks GoTrue whether the session behind
  -- that token still exists, so signing out left a bearer token that kept
  -- spending real chips as its owner for the rest of the week. The engine
  -- was never fooled (it verifies through auth.getUser, which checks the
  -- session), only the database was. fn_caller_session_is_live closes that
  -- gap at the money door itself.
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'SESSION_REVOKED: this session is signed out - sign in again'
      USING ERRCODE = '28000';
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_take_seat_and_buy_in requires an authenticated caller'
      USING ERRCODE = '28000';
  END IF;

  SELECT id, tournament_id, max_players, status
    INTO v_tbl FROM public.tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;
  IF v_tbl.tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_game_table');
  END IF;
  IF v_tbl.status = 'closed' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_closed');
  END IF;

  SELECT id, status, variant, max_players, starting_chips, name
    INTO v_t FROM public.tournaments WHERE id = v_tbl.tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'game_not_found');
  END IF;

  IF NOT (COALESCE(v_t.variant, '') = 'spin' OR COALESCE(v_t.max_players, 0) <= 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_seat_first_game');
  END IF;

  -- The chips this seat is buying. Known now, because the board decides it.
  v_stack := COALESCE(v_t.starting_chips, 0);

  v_seat_cap := COALESCE(NULLIF(v_tbl.max_players, 0), v_t.max_players, 3);

  IF p_seat_number IS NULL OR p_seat_number < 1 OR p_seat_number > v_seat_cap THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_seat');
  END IF;

  SELECT seat_number INTO v_mine
    FROM public.table_seats
   WHERE table_id = p_table_id AND user_id = v_uid AND left_at IS NULL LIMIT 1;
  IF v_mine IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'already_seated', true,
      'table_id', p_table_id, 'seat_number', v_mine);
  END IF;

  IF v_t.status NOT IN ('ANNOUNCED', 'REGISTERING') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'game_already_started');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.table_seats
     WHERE table_id = p_table_id AND seat_number = p_seat_number AND left_at IS NULL
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seat_taken');
  END IF;

  PERFORM public.fn_sync_seat_first_player_count(v_t.id);

  v_reg := public.fn_register_for_tournament(v_t.id, true);
  IF COALESCE((v_reg->>'ok')::boolean, false) IS NOT TRUE
     AND COALESCE(v_reg->>'reason', '') <> 'already_registered' THEN
    RETURN jsonb_build_object('ok', false,
      'reason', COALESCE(v_reg->>'reason', 'buy_in_failed'));
  END IF;

  UPDATE public.tournament_players
     SET status = 'playing', chips = v_stack, table_id = p_table_id, seat_number = p_seat_number
   WHERE tournament_id = v_t.id AND user_id = v_uid;

  UPDATE public.table_seats
     SET user_id = v_uid, stack = v_stack, left_at = NULL, joined_at = now(), is_sitting_out = false
   WHERE table_id = p_table_id AND seat_number = p_seat_number AND left_at IS NOT NULL;

  IF NOT FOUND THEN
    BEGIN
      INSERT INTO public.table_seats (table_id, user_id, seat_number, stack)
      VALUES (p_table_id, v_uid, p_seat_number, v_stack);
    EXCEPTION WHEN unique_violation THEN
      RAISE EXCEPTION 'seat_taken' USING ERRCODE = '55000';
    END;
  END IF;

  v_taken := COALESCE(public.fn_sync_seat_first_player_count(v_t.id), 0);
  IF v_taken = 0 THEN
    SELECT count(*) INTO v_taken FROM public.table_seats
     WHERE table_id = p_table_id AND left_at IS NULL;
  END IF;

  RETURN jsonb_build_object('ok', true, 'table_id', p_table_id,
    'seat_number', p_seat_number, 'stack', v_stack, 'seat_reserved', true,
    'seats_taken', v_taken, 'seats_needed', v_seat_cap,
    'starts_now', v_taken >= v_seat_cap,
    'cost', COALESCE((v_reg->>'cost')::numeric, 0));

EXCEPTION
  WHEN sqlstate '55000' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seat_taken');
  WHEN sqlstate '23514' THEN
    GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
    IF v_err LIKE '%FOUR TABLE LIMIT%' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'table_limit_reached',
        'limit', 4);
    END IF;
    RAISE;
END;
$$;


ALTER FUNCTION public.fn_take_seat_and_buy_in_before_maintenance_announcement_gate(p_table_id uuid, p_seat_number integer) OWNER TO postgres;

--
-- Name: fn_take_seat_and_buy_in_before_terminal_seat_gate(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_take_seat_and_buy_in_before_terminal_seat_gate(p_table_id uuid, p_seat_number integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    SET statement_timeout TO '30s'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'platform_frozen');
  END IF;
  RETURN public.fn_take_seat_and_buy_in_before_maintenance_announcement_gate(
    p_table_id, p_seat_number
  );
END;
$$;


ALTER FUNCTION public.fn_take_seat_and_buy_in_before_terminal_seat_gate(p_table_id uuid, p_seat_number integer) OWNER TO postgres;

--
-- Name: fn_terminal_bounty_recipient_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_terminal_bounty_recipient_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_old_marker timestamptz;
  v_new_marker timestamptz;
  v_new_status text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.award_id IS DISTINCT FROM OLD.award_id THEN
    RAISE EXCEPTION 'bounty recipient award ownership is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' THEN
    SELECT a.tournament_id INTO v_old_tournament_id
      FROM public.tournament_bounty_awards a WHERE a.id = OLD.award_id;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    SELECT a.tournament_id INTO v_new_tournament_id
      FROM public.tournament_bounty_awards a WHERE a.id = NEW.award_id;
  END IF;
  IF TG_OP <> 'INSERT' THEN v_old_marker := OLD.terminal_closed_at; END IF;
  IF TG_OP <> 'DELETE' THEN v_new_marker := NEW.terminal_closed_at; END IF;
  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN
    RAISE EXCEPTION 'new bounty recipient cannot supply a terminal marker'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN
    RAISE EXCEPTION 'terminal bounty recipient evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN
    IF public.fn_ca_terminal_marker_transition_is_exact(
         to_jsonb(OLD),to_jsonb(NEW),v_old_tournament_id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'bounty recipient terminal marker transition is not canonical'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND v_new_tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_new_status
      FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
    IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'terminal bounty recipient evidence is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  IF public.fn_ca_has_committed_tournament_receipt(v_old_tournament_id)
     OR public.fn_ca_has_committed_tournament_receipt(v_new_tournament_id) THEN
    RAISE EXCEPTION 'terminal bounty recipient evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_terminal_bounty_recipient_is_immutable() OWNER TO postgres;

--
-- Name: fn_terminal_credit_key_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_terminal_credit_key_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_new_status text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.key IS DISTINCT FROM OLD.key THEN
    RAISE EXCEPTION 'wallet credit idempotency keys are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' THEN
    v_old_tournament_id := public.fn_ca_tournament_id_from_credit_key(OLD.key);
  END IF;
  IF TG_OP <> 'DELETE' THEN
    v_new_tournament_id := public.fn_ca_tournament_id_from_credit_key(NEW.key);
  END IF;
  -- Recognized payout claims are append-only financial evidence. An existing
  -- row is already locked before this row trigger runs, so UPDATE/DELETE must
  -- refuse immediately instead of reversing the terminal root lock order.
  IF TG_OP <> 'INSERT'
     AND COALESCE(v_old_tournament_id,v_new_tournament_id) IS NOT NULL THEN
    RAISE EXCEPTION 'tournament wallet credit claims are append-only'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND v_new_tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_new_status
      FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
    IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'terminal wallet credit key evidence is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  IF v_new_tournament_id IS NOT NULL
     AND v_new_tournament_id IS DISTINCT FROM v_old_tournament_id THEN
    PERFORM 1 FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
  END IF;
  IF public.fn_ca_has_committed_tournament_receipt(v_old_tournament_id)
     OR public.fn_ca_has_committed_tournament_receipt(v_new_tournament_id) THEN
    RAISE EXCEPTION 'terminal wallet credit key evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


