COMMENT ON FUNCTION public.fn_tournament_atomic_register(p_user_id uuid, p_club_id uuid, p_tournament_id uuid, p_buy_in numeric) IS 'X7 — refactored to write canonical tournaments table (not club_tournaments). Column: current_players replaces registered_count.';


