--
-- Name: fn_tournament_chip_conservation_check(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_chip_conservation_check(p_tolerance_per_player numeric DEFAULT 1) RETURNS TABLE(tournament_id uuid, name text, players bigint, expected_chips numeric, actual_chips numeric, drift numeric, drift_per_player numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH live AS (
    SELECT t.id,
           t.name,
           COALESCE(t.starting_chips, 0) AS starting_chips,
           COALESCE(t.rebuy_chips, 0)    AS rebuy_chips,
           COALESCE(t.addon_chips, 0)    AS addon_chips,
           (SELECT count(*) FROM tournament_players tp
             WHERE tp.tournament_id = t.id) AS players,
           (SELECT COALESCE(sum(tp.rebuys), 0) FROM tournament_players tp
             WHERE tp.tournament_id = t.id) AS rebuys,
           (SELECT count(*) FROM tournament_players tp
             WHERE tp.tournament_id = t.id AND tp.add_on) AS addons,
           (SELECT COALESCE(sum(ts.stack), 0)
              FROM table_seats ts
              JOIN tables tb ON tb.id = ts.table_id
             WHERE tb.tournament_id = t.id AND ts.left_at IS NULL) AS seat_stacks
      FROM tournaments t
     WHERE t.status = 'RUNNING'
  ),
  calc AS (
    SELECT l.id, l.name, l.players,
           (l.players * l.starting_chips)
             + (l.rebuys * l.rebuy_chips)
             + (l.addons * l.addon_chips) AS expected_chips,
           l.seat_stacks AS actual_chips
      FROM live l
  )
  SELECT c.id, c.name, c.players,
         round(c.expected_chips, 2),
         round(c.actual_chips, 2),
         round(c.actual_chips - c.expected_chips, 2),
         round((c.actual_chips - c.expected_chips) / NULLIF(c.players, 0), 3)
    FROM calc c
   WHERE c.players > 0
     AND abs(c.actual_chips - c.expected_chips)
         > (GREATEST(p_tolerance_per_player, 0) * c.players)
   ORDER BY abs(c.actual_chips - c.expected_chips) DESC;
$$;


ALTER FUNCTION public.fn_tournament_chip_conservation_check(p_tolerance_per_player numeric) OWNER TO postgres;

--
-- Name: fn_tournament_club_for_user(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_club_for_user(p_user_id uuid, p_tournament_id uuid, p_preferred_club uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_union uuid; v_t_club uuid; v_club uuid;
  v_is_horse boolean := false; v_n int; v_idx int;
BEGIN
  SELECT t.union_id, t.club_id INTO v_union, v_t_club
    FROM tournaments t WHERE t.id = p_tournament_id;

  IF v_union IS NULL THEN
    RETURN v_t_club;                       -- standalone club tournament
  END IF;

  IF p_preferred_club IS NOT NULL
     AND EXISTS (SELECT 1 FROM club_members m
                  JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
                 WHERE m.user_id = p_user_id AND m.club_id = p_preferred_club
                   AND m.status IN ('active','approved'))
  THEN
    RETURN p_preferred_club;
  END IF;

  SELECT COALESCE(p.is_horse, false) INTO v_is_horse FROM profiles p WHERE p.id = p_user_id;

  IF v_is_horse THEN
    -- Same stable home club a horse uses for cash play, so a horse's tournament
    -- and cash activity always belong to the same club.
    SELECT count(*) INTO v_n
      FROM club_members m
      JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
     WHERE m.user_id = p_user_id AND m.status IN ('active','approved');
    IF v_n > 1 THEN
      v_idx := (abs(hashtextextended(p_user_id::text, 0)) % v_n)::int;
      SELECT m.club_id INTO v_club
        FROM club_members m
        JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
       WHERE m.user_id = p_user_id AND m.status IN ('active','approved')
       ORDER BY m.club_id OFFSET v_idx LIMIT 1;
      IF v_club IS NOT NULL THEN RETURN v_club; END IF;
    END IF;
  END IF;

  SELECT m.club_id INTO v_club
    FROM club_members m
    JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
   WHERE m.user_id = p_user_id AND m.status IN ('active','approved')
   ORDER BY m.joined_at ASC NULLS LAST, m.club_id
   LIMIT 1;

  RETURN v_club;
END $$;


ALTER FUNCTION public.fn_tournament_club_for_user(p_user_id uuid, p_tournament_id uuid, p_preferred_club uuid) OWNER TO postgres;

--
-- Name: fn_tournament_conservation_delta(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_conservation_delta(p_tournament_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH m AS (
    SELECT t.id, t.ended_at,
      COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
         WHERE w.related_entity_id = t.id AND w.type = 'debit'
           AND w.category IN ('tournament_buyin','rebuy','addon')), 0) AS money_in,
      COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
         WHERE w.related_entity_id = t.id AND w.type = 'credit'
           AND w.category = 'refund'), 0) AS refunds,
      COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
         WHERE w.related_entity_id = t.id AND w.type = 'credit'
           AND w.category = 'prize'), 0) AS prizes,
      COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
         WHERE w.related_entity_id = t.id AND w.type = 'credit'
           AND w.category = 'bounty'), 0) AS bounties,
      COALESCE((SELECT sum(r.rake_amount) FROM public.rake_records r
         WHERE r.tournament_id = t.id AND r.is_tournament), 0) AS rake,

      -- THE OVERLAY, FROM THE JOURNAL FIRST (2026-09-06). Two paths fund a
      -- guarantee and they keep different books: fn_apply_prize_guarantee
      -- writes a tournament_guarantee_overlays row, and the lock trigger
      -- fn_ca_fund_overlay_on_lock writes a chip_ledger leg
      -- (union_bank|club_treasury -> prize_liability, category 'overlay').
      -- The journal is the record of truth, so it is read first; the side
      -- table carries the 227 events older than the leg. GREATEST, never the
      -- sum: no event in the whole history has both, and if one ever does,
      -- they are two records of ONE funding, not two fundings.
      GREATEST(
        COALESCE((SELECT sum(l.amount) FROM public.chip_ledger l
           WHERE l.tournament_id = t.id
             AND l.category = 'overlay'
             AND l.to_type = 'prize_liability'), 0),
        COALESCE((SELECT o.amount FROM public.tournament_guarantee_overlays o
           WHERE o.tournament_id = t.id), 0)
      ) AS funded_overlay,

      -- ACKNOWLEDGED PRE-FUNDING MINTING. Replaces the 2026-08-27T12:00:00Z
      -- date literal that used to live here: same intent, but one auditable row
      -- per event carrying the exact amount instead of a comparison that
      -- silently forgave whatever fell the right side of it. An event with no
      -- baseline row is offset by nothing.
      COALESCE((SELECT b.amount FROM public.tournament_conservation_baseline b
         WHERE b.tournament_id = t.id), 0) AS acknowledged,

      -- A SEAT ARRIVING. The target's pool and rake were both credited by
      -- fn_award_satellite_seat with no wallet debit anywhere, so without this
      -- term the target is charged for a prize it was funded to pay. The seat
      -- names its target in metadata because the payout row belongs to the
      -- SATELLITE that paid it.
      COALESCE((SELECT sum(sp.amount) FROM public.tournament_payouts sp
         WHERE sp.source = 'satellite_seat'
           AND sp.metadata->>'satellite_target_id' = t.id::text), 0) AS seat_income,

      -- A SEAT LEAVING. The satellite really did pay this out; it simply paid
      -- it in a seat rather than in chips, so no 'prize' credit exists to find.
      COALESCE((SELECT sum(sp.amount) FROM public.tournament_payouts sp
         WHERE sp.source = 'satellite_seat'
           AND sp.tournament_id = t.id), 0) AS seat_paid_out
    FROM public.tournaments t WHERE t.id = p_tournament_id
  )
  SELECT round(
      m.money_in - m.refunds - m.rake - m.prizes - m.bounties
    + m.funded_overlay
    + m.acknowledged
    + m.seat_income
    - m.seat_paid_out
  , 2)
  FROM m;
$$;


ALTER FUNCTION public.fn_tournament_conservation_delta(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_tournament_conservation_delta(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_tournament_conservation_delta(p_tournament_id uuid) IS 'True money-conservation delta for one tournament: money_in - refunds - rake - prizes - bounties + funded_overlay. Negative = paid out money never collected. Positive = retained money never paid out. The pre-2026-08-27 amnesty term that faked unfunded guarantee overlays back into the result was removed 2026-08-28 (migration watchdog_remove_conservation_delta_amnesty). Do not re-add it: if a guarantee was genuinely funded, book a row in tournament_guarantee_overlays instead.';


--
-- Name: fn_tournament_current_blinds(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_current_blinds(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_entrants bigint;
  v_rebuys bigint;
  v_addons bigint;
  v_total_chips numeric := NULL;
BEGIN
  SELECT * INTO v_t
    FROM public.tournaments t
   WHERE t.id=p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found' USING ERRCODE='P0002';
  END IF;

  SELECT count(*) INTO v_entrants
    FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id;
  SELECT count(*) INTO v_rebuys
    FROM public.wallet_transactions wt
   WHERE wt.related_entity_id=p_tournament_id AND wt.category='rebuy';
  SELECT count(*) INTO v_addons
    FROM public.wallet_transactions wt
   WHERE wt.related_entity_id=p_tournament_id AND wt.category='addon';
  IF COALESCE(v_t.starting_chips,0)>0 AND v_entrants>0 THEN
    v_total_chips := v_t.starting_chips*v_entrants
      +COALESCE(NULLIF(v_t.rebuy_chips,0),v_t.starting_chips)*v_rebuys
      +COALESCE(NULLIF(v_t.addon_chips,0),v_t.starting_chips)*v_addons;
  END IF;

  RETURN public.fn_resolve_tournament_blinds(
    v_t.blind_structure::text,
    COALESCE(v_t.current_level,0),
    v_t.variant,
    v_t.tournament_type,
    v_total_chips
  );
END;
$$;


ALTER FUNCTION public.fn_tournament_current_blinds(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_tournament_double_paid_obligations(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_double_paid_obligations(p_hours integer DEFAULT 24) RETURNS TABLE(tournament_id uuid, tournament_name text, player_id uuid, finish_position integer, amount numeric, payments bigint, sources text, excess_chips numeric, last_paid_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH prize_side AS (
    -- The prize ladder and the three paths that top it up. Bounty sources are
    -- deliberately absent: repeated equal bounty payments are correct.
    SELECT p.tournament_id, p.user_id, p.position, p.amount, p.source, p.paid_at
      FROM public.tournament_payouts p
      JOIN public.tournaments t ON t.id = p.tournament_id
     WHERE p.source IN ('structure', 'reconcile', 'overlay_backpay', 'spin_backpay')
       AND p.user_id IS NOT NULL
       AND t.ended_at > now() - make_interval(hours => GREATEST(COALESCE(p_hours, 24), 1))
  )
  SELECT ps.tournament_id,
         t.name,
         ps.user_id,
         ps.position,
         ps.amount,
         count(*)                                              AS payments,
         string_agg(DISTINCT ps.source, '+' ORDER BY ps.source) AS sources,
         round(ps.amount * (count(*) - 1), 2)                  AS excess_chips,
         max(ps.paid_at)                                       AS last_paid_at
    FROM prize_side ps
    JOIN public.tournaments t ON t.id = ps.tournament_id
   GROUP BY ps.tournament_id, t.name, ps.user_id, ps.position, ps.amount
  HAVING count(*) > 1
     -- More than one DISTINCT source is what makes it two repairers rather
     -- than one path legitimately paying an amount that happens to repeat.
     AND count(DISTINCT ps.source) > 1
   ORDER BY 8 DESC;
$$;


ALTER FUNCTION public.fn_tournament_double_paid_obligations(p_hours integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_tournament_double_paid_obligations(p_hours integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_tournament_double_paid_obligations(p_hours integer) IS 'Prize obligations paid by two different repair paths (structure/reconcile/overlay_backpay/spin_backpay). Each row is one debt settled more than once because the idempotency key is namespaced by the repairer, not by the debt. Bounty sources excluded - repeated equal bounty payments are correct.';


--
-- Name: fn_tournament_entry_cap_reached(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_entry_cap_reached(p_tournament_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cap      integer;
  v_counter  integer;
  v_entries  integer;
BEGIN
  SELECT t.max_players, COALESCE(t.current_players, 0)
    INTO v_cap, v_counter
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;

  IF NOT FOUND OR v_cap IS NULL OR v_cap <= 0 THEN
    RETURN false;                      -- uncapped: this function never refuses
  END IF;

  SELECT count(*) INTO v_entries
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;

  /* GREATEST, never the entry count alone: this can only ever be stricter than
     the counter test it replaces, never looser. */
  RETURN GREATEST(v_counter, COALESCE(v_entries, 0)) >= v_cap;
END;
$$;


ALTER FUNCTION public.fn_tournament_entry_cap_reached(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_tournament_entry_cap_reached(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_tournament_entry_cap_reached(p_tournament_id uuid) IS 'True when a capped tournament already holds max_players ENTRIES. Counts tournament_players, because current_players is overwritten with the live seated count on every seat-first event and cannot answer this question. Takes the greater of the two, so it is never looser than the counter test it replaced. A polite pre-check: fn_enforce_tournament_capacity is the authority.';


--
-- Name: fn_tournament_entry_split(numeric, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_entry_split(p_buy_in numeric, p_fee numeric, p_bounty numeric, p_is_bounty boolean) RETURNS TABLE(charge numeric, rake numeric, bounty numeric, prize numeric)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_charge numeric; v_rake numeric; v_bounty numeric; v_prize numeric;
BEGIN
  IF NOT COALESCE(p_is_bounty, false) THEN
    -- Non-bounty: unchanged - fee charged on top of the buy-in portion.
    v_charge := round(COALESCE(p_buy_in,0),2) + round(COALESCE(p_fee,0),2);
    v_rake   := round(COALESCE(p_fee,0),2);
    v_bounty := 0;
    v_prize  := round(COALESCE(p_buy_in,0),2);
  ELSE
    -- Bounty event: the rake is exactly the fee. A zero fee is a legitimate
    -- outcome of the whole-number floor rule (totals under 10 take no rake)
    -- and must NEVER be replaced with a percentage default.
    v_charge := round(COALESCE(p_buy_in,0),2) + round(COALESCE(p_fee,0),2);
    v_rake   := round(COALESCE(p_fee,0),2);
    v_bounty := round(COALESCE(p_bounty,0), 2);
    v_prize  := round(v_charge - v_rake - v_bounty, 2);  -- = buy_in - bounty
  END IF;
  RETURN QUERY SELECT v_charge, v_rake, v_bounty, v_prize;
END;
$$;


ALTER FUNCTION public.fn_tournament_entry_split(p_buy_in numeric, p_fee numeric, p_bounty numeric, p_is_bounty boolean) OWNER TO postgres;

--
-- Name: fn_tournament_fee_names_its_player(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_fee_names_its_player() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid text := NEW.metadata->>'user_id';
  v_pc  jsonb;
BEGIN
  /* Only a tournament row that arrives with no contributions and positive
     rake. Reversal rows (negative) and rows that already name their players
     (spin books) pass untouched. The VALUE is a weight: the allocator splits
     the rake equally under DEALT_EQUAL, so the amount stored is immaterial;
     rake_amount is used so a reader sees a fee, not a pot. */
  IF v_uid ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    NEW.player_contributions := jsonb_build_object(v_uid, NEW.rake_amount);
  ELSIF NEW.tournament_id IS NOT NULL THEN
    SELECT jsonb_object_agg(tp.user_id::text, NEW.rake_amount) INTO v_pc
      FROM public.tournament_players tp
     WHERE tp.tournament_id = NEW.tournament_id AND tp.user_id IS NOT NULL;
    IF v_pc IS NOT NULL THEN
      NEW.player_contributions := v_pc;
    END IF;
  END IF;
  IF NEW.player_contributions IS NOT NULL THEN
    NEW.rake_method := COALESCE(NEW.rake_method, 'DEALT_EQUAL');
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_tournament_fee_names_its_player() OWNER TO postgres;

--
-- Name: fn_tournament_finish_kind(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_finish_kind(p_tournament_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN EXISTS (
      SELECT 1 FROM public.tournament_final_table_deal_batches d
       WHERE d.tournament_id = p_tournament_id
    ) THEN 'final_table_deal'
    WHEN lower(COALESCE(t.variant,'')) = 'satellite'
      OR upper(COALESCE(t.tournament_type,'')) = 'SATELLITE'
      OR t.satellite_target_id IS NOT NULL THEN 'satellite'
    ELSE 'normal'
  END
  FROM public.tournaments t
  WHERE t.id = p_tournament_id;
$$;


ALTER FUNCTION public.fn_tournament_finish_kind(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_tournament_finish_readiness(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_finish_readiness(p_tournament_id uuid, p_winner_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_finish public.tournament_finish_receipts%ROWTYPE;
  v_kind text;
  v_failures jsonb := '[]'::jsonb;
  v_winner_count integer := 0;
  v_position_one_count integer := 0;
  v_canonical_winner uuid;
  v_position_one_winner uuid;
  v_open_players integer := 0;
  v_unranked integer := 0;
  v_duplicate_positions integer := 0;
  v_unsettled_obligations integer := 0;
  v_bad_place_evidence integer := 0;
  v_bad_player_prizes integer := 0;
  v_place_owed numeric := 0;
  v_escrow public.tournament_escrow%ROWTYPE;
  v_escrow_found boolean := false;
  v_rake_expected numeric := 0;
  v_rake_recorded numeric;
  v_rake_destination text;
  v_rake_settled_at timestamptz;
  v_rake_attributed_at timestamptz;
  v_rake_found boolean := false;
  v_bounty public.tournament_bounty_completion_receipts%ROWTYPE;
  v_place_batch public.tournament_place_settlement_batches%ROWTYPE;
  v_deal public.tournament_final_table_deal_batches%ROWTYPE;
  v_satellite public.tournament_satellite_settlement_batches%ROWTYPE;
  v_domain_check jsonb;
  v_bad_satellite_seats integer := 0;
  v_bad_satellite_outcomes integer := 0;
  v_satellite_award_gaps integer := 0;
BEGIN
  SELECT * INTO v_t FROM public.tournaments WHERE id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found',
      'failures',jsonb_build_array(jsonb_build_object('code','tournament_not_found')));
  END IF;
  v_kind := public.fn_tournament_finish_kind(p_tournament_id);

  SELECT * INTO v_finish FROM public.tournament_finish_receipts
   WHERE tournament_id = p_tournament_id;
  IF NOT FOUND THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','finish_claim_missing'));
  ELSIF v_finish.winner_user_id IS DISTINCT FROM p_winner_user_id
     OR v_finish.finish_kind IS DISTINCT FROM v_kind THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','finish_claim_conflict','claimed_winner',v_finish.winner_user_id,
      'claimed_kind',v_finish.finish_kind,'observed_kind',v_kind));
  END IF;

  SELECT count(*), (array_agg(tp.user_id ORDER BY tp.user_id))[1]
    INTO v_winner_count, v_canonical_winner
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status = 'winner' AND tp.position = 1;
  SELECT count(*), (array_agg(tp.user_id ORDER BY tp.user_id))[1]
    INTO v_position_one_count, v_position_one_winner
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id AND tp.position = 1;
  IF v_winner_count <> 1 OR v_position_one_count <> 1
     OR v_canonical_winner IS DISTINCT FROM p_winner_user_id
     OR v_position_one_winner IS DISTINCT FROM p_winner_user_id THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','canonical_winner_not_proven','winner_rows',v_winner_count,
      'position_one_rows',v_position_one_count,'observed_winner',v_canonical_winner,
      'requested_winner',p_winner_user_id));
  END IF;

  SELECT count(*) FILTER (WHERE tp.status IN ('registered','playing')),
         count(*) FILTER (WHERE tp.position IS NULL)
    INTO v_open_players, v_unranked
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  SELECT count(*) INTO v_duplicate_positions
    FROM (
      SELECT tp.position FROM public.tournament_players tp
       WHERE tp.tournament_id = p_tournament_id AND tp.position IS NOT NULL
       GROUP BY tp.position HAVING count(*) <> 1
    ) duplicates;
  IF v_open_players <> 0 OR v_unranked <> 0 OR v_duplicate_positions <> 0 THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','standings_not_terminal','open_players',v_open_players,
      'unranked_players',v_unranked,'duplicate_positions',v_duplicate_positions));
  END IF;
  IF COALESCE(v_t.on_break,false) THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','terminal_break_flag_set'));
  END IF;

  SELECT count(*) INTO v_unsettled_obligations
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND abs(round(COALESCE(o.amount_paid,0),2)
           - round(COALESCE(o.amount_owed,0),2)) > 0.005;
  IF v_unsettled_obligations <> 0 THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','unsettled_obligations','count',v_unsettled_obligations));
  END IF;

  -- Satellite prize history is one combined entitlement row (ticket value plus
  -- an optional cash remainder). Its format checker proves both constituent
  -- receipts exactly; comparing that cache to either receipt alone would
  -- falsely reject a short-field last-seat winner. The generic relation stays
  -- an independent certificate for every other format.
  IF v_kind <> 'satellite' THEN
    SELECT count(*) INTO v_bad_place_evidence
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
       AND o.amount_owed > 0
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id = o.tournament_id
            AND tp.position = o.place AND tp.user_id = o.user_id
            AND abs(round(COALESCE(tp.prize,0),2) - round(o.amount_owed,2)) <= 0.005
       );
    SELECT count(*) INTO v_bad_player_prizes
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id AND round(COALESCE(tp.prize,0),2) > 0
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_obligations o
          WHERE o.tournament_id = tp.tournament_id AND o.kind = 'place'
            AND o.place = tp.position AND o.user_id = tp.user_id
            AND abs(round(o.amount_paid,2) - round(COALESCE(tp.prize,0),2)) <= 0.005
            AND abs(round(o.amount_owed,2) - round(o.amount_paid,2)) <= 0.005
       )
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_obligations o
          WHERE o.tournament_id = tp.tournament_id AND o.kind = 'final_table_deal'
            AND o.user_id = tp.user_id
            AND abs(round(o.amount_paid,2) - round(COALESCE(tp.prize,0),2)) <= 0.005
            AND abs(round(o.amount_owed,2) - round(o.amount_paid,2)) <= 0.005
       );
  END IF;
  IF v_bad_place_evidence <> 0 OR v_bad_player_prizes <> 0 THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','prize_evidence_mismatch','place_obligations',v_bad_place_evidence,
      'player_prizes',v_bad_player_prizes));
  END IF;

  IF v_kind = 'normal' THEN
    SELECT * INTO v_place_batch
      FROM public.tournament_place_settlement_batches b
     WHERE b.tournament_id = p_tournament_id;
    IF NOT FOUND OR v_place_batch.settled_at IS NULL THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','atomic_place_batch_not_settled'));
    END IF;

    SELECT round(COALESCE(sum(o.amount_owed),0),2) INTO v_place_owed
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place';
    IF abs(v_place_owed - round(COALESCE(v_t.prize_pool,0),2)) > 0.005 THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','prize_pool_not_fully_obligated','prize_pool',v_t.prize_pool,
        'place_obligations',v_place_owed));
    END IF;
    IF round(COALESCE(v_t.guaranteed_prize,0),2)
         > round(COALESCE(v_t.prize_pool,0),2) + 0.005 THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','guarantee_not_funded','guarantee',v_t.guaranteed_prize,
        'prize_pool',v_t.prize_pool));
    END IF;
  END IF;

  SELECT * INTO v_escrow FROM public.tournament_escrow
   WHERE tournament_id = p_tournament_id;
  v_escrow_found := FOUND;
  IF NOT v_escrow_found THEN
    IF COALESCE(v_t.prize_pool,0) <> 0 OR COALESCE(v_t.bounty_pool,0) <> 0
       OR COALESCE(v_t.total_rake,0) <> 0
       OR EXISTS (SELECT 1 FROM public.tournament_payouts po
                   WHERE po.tournament_id = p_tournament_id) THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','escrow_evidence_missing'));
    END IF;
  ELSIF abs(round(v_escrow.prize_balance,2)) > 0.005
     OR abs(round(v_escrow.bounty_balance,2)) > 0.005
     OR abs(round(v_escrow.fee_balance,2)) > 0.005 THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','escrow_not_zero','prize_balance',v_escrow.prize_balance,
      'bounty_balance',v_escrow.bounty_balance,'fee_balance',v_escrow.fee_balance));
  END IF;

  SELECT GREATEST(round(COALESCE(sum(rr.rake_amount),0),2),0) INTO v_rake_expected
    FROM public.rake_records rr
   WHERE rr.tournament_id = p_tournament_id AND rr.is_tournament;
  SELECT amount,destination,settled_at,attributed_at
    INTO v_rake_recorded,v_rake_destination,v_rake_settled_at,v_rake_attributed_at
    FROM public.tournament_rake_settlements rs
   WHERE rs.tournament_id = p_tournament_id;
  v_rake_found := FOUND;
  IF NOT v_rake_found OR v_rake_settled_at IS NULL
     OR v_rake_attributed_at IS NULL OR v_rake_destination = 'pending'
     OR abs(round(COALESCE(v_rake_recorded,0),2) - v_rake_expected) > 0.005 THEN
    v_failures := v_failures || jsonb_build_array(jsonb_build_object(
      'code','rake_not_settled','expected',v_rake_expected,
      'recorded',CASE WHEN v_rake_found THEN v_rake_recorded ELSE NULL END,
      'destination',CASE WHEN v_rake_found THEN v_rake_destination ELSE NULL END,
      'attributed_at',CASE WHEN v_rake_found THEN v_rake_attributed_at ELSE NULL END));
  END IF;

  IF COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
     OR COALESCE(v_t.is_mystery_bounty,false) THEN
    IF public.fn_tournament_has_unsettled_bounties(p_tournament_id) THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','pending_bounty_obligations'));
    END IF;
    SELECT * INTO v_bounty FROM public.tournament_bounty_completion_receipts
     WHERE tournament_id = p_tournament_id;
    IF NOT FOUND OR v_bounty.winner_user_id IS DISTINCT FROM p_winner_user_id
       OR v_bounty.pool_finalized_at IS NULL
       OR COALESCE((v_bounty.pool_result->>'ok')::boolean,false) IS NOT TRUE THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','bounty_pool_not_certified'));
    END IF;
    IF COALESCE(v_t.is_mystery_bounty,false)
       AND COALESCE(v_t.mystery_bounty_stage,'pending') <> 'pending'
       AND (v_bounty.mystery_settled_at IS NULL
            OR COALESCE((v_bounty.mystery_result->>'ok')::boolean,false) IS NOT TRUE
            OR COALESCE((v_bounty.mystery_result->>'balanced')::boolean,false) IS NOT TRUE) THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','mystery_bounty_not_certified'));
    END IF;
  END IF;

  IF v_kind = 'final_table_deal' THEN
    SELECT * INTO v_deal FROM public.tournament_final_table_deal_batches
     WHERE tournament_id = p_tournament_id;
    IF NOT FOUND OR v_deal.chip_leader IS DISTINCT FROM p_winner_user_id
       OR v_deal.settled_at IS NULL OR v_deal.escrow_prize_after IS NULL THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','atomic_final_table_deal_batch_not_settled'));
    ELSE
      v_domain_check := public.fn_check_atomic_final_table_deal(p_tournament_id);
      IF COALESCE((v_domain_check->>'ok')::boolean,false) IS NOT TRUE THEN
        v_failures := v_failures || jsonb_build_array(jsonb_build_object(
          'code','atomic_final_table_deal_not_proven','detail',v_domain_check));
      END IF;
    END IF;
  END IF;

  IF v_kind = 'satellite' THEN
    SELECT * INTO v_satellite
      FROM public.tournament_satellite_settlement_batches b
     WHERE b.tournament_id = p_tournament_id;
    IF NOT FOUND OR v_satellite.winner_user_id IS DISTINCT FROM p_winner_user_id
       OR v_satellite.settled_at IS NULL THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','atomic_satellite_batch_not_settled'));
    ELSE
      v_domain_check := public.fn_check_atomic_satellite_finish(p_tournament_id);
      IF COALESCE((v_domain_check->>'ok')::boolean,false) IS NOT TRUE THEN
        v_failures := v_failures || jsonb_build_array(jsonb_build_object(
          'code','atomic_satellite_finish_not_proven','detail',v_domain_check));
      END IF;
    END IF;

    SELECT count(*) INTO v_bad_satellite_seats
      FROM public.tournament_players target_seat
     WHERE target_seat.source_satellite_id = p_tournament_id
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_payouts po
          WHERE po.tournament_id = p_tournament_id
            AND po.source = 'satellite_seat'
            AND po.user_id = target_seat.user_id
            AND po.metadata->>'registration_id' = target_seat.id::text
       );
    IF v_bad_satellite_seats <> 0 THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','satellite_seat_evidence_missing','count',v_bad_satellite_seats));
    END IF;

    -- Every in-kind payout names the original finisher/place and the exact
    -- target registration it funded. A payout row by itself is not a seat,
    -- and a target seat by itself is not a durable payout record.
    SELECT count(*) INTO v_bad_satellite_outcomes
      FROM public.tournament_payouts po
     WHERE po.tournament_id = p_tournament_id AND po.source = 'satellite_seat'
       AND (po."position" IS NULL
            OR NOT EXISTS (
              SELECT 1 FROM public.tournament_players finisher
               WHERE finisher.tournament_id = p_tournament_id
                 AND finisher.user_id = po.user_id
                 AND finisher.position = po."position"
            )
            OR NOT EXISTS (
              SELECT 1 FROM public.tournament_players target_seat
               WHERE target_seat.id::text = po.metadata->>'registration_id'
                 AND target_seat.user_id = po.user_id
                 AND target_seat.source_satellite_id = p_tournament_id
            ));

    -- Seat awards and cash ticket fallbacks form a top-finisher prefix. A gap
    -- means a lower place was paid while a higher promised place was skipped.
    WITH awarded_positions AS (
      SELECT po."position" AS place
        FROM public.tournament_payouts po
       WHERE po.tournament_id = p_tournament_id
         AND po.source = 'satellite_seat' AND po."position" IS NOT NULL
      UNION
      SELECT o.place
        FROM public.tournament_obligations o
       WHERE o.tournament_id = p_tournament_id AND o.kind = 'place'
         AND o.place IS NOT NULL AND round(o.amount_paid,2) > 0
         AND abs(round(o.amount_paid,2)-round(o.amount_owed,2)) <= 0.005
    ), bounds AS (SELECT max(place) AS max_place FROM awarded_positions)
    SELECT count(*) INTO v_satellite_award_gaps
      FROM bounds b
      CROSS JOIN LATERAL generate_series(1,b.max_place) expected(place)
     WHERE b.max_place IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM awarded_positions a WHERE a.place=expected.place);

    IF v_bad_satellite_outcomes <> 0 OR v_satellite_award_gaps <> 0
       OR EXISTS (
         SELECT 1 FROM public.tournament_obligations o
          WHERE o.tournament_id = p_tournament_id
            AND o.kind = 'satellite_remainder'
            AND NOT EXISTS (
              SELECT 1 FROM public.tournament_players tp
               WHERE tp.tournament_id=p_tournament_id AND tp.user_id=o.user_id
            )
       ) THEN
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'code','satellite_awards_not_certified',
        'invalid_outcomes',v_bad_satellite_outcomes,
        'award_gaps',v_satellite_award_gaps));
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok',jsonb_array_length(v_failures) = 0,
    'reason',CASE WHEN jsonb_array_length(v_failures) = 0 THEN NULL
                  ELSE v_failures->0->>'code' END,
    'tournament_id',p_tournament_id,'winner_user_id',p_winner_user_id,
    'finish_kind',v_kind,'failures',v_failures,
    'financials',jsonb_build_object(
      'unsettled_obligations',v_unsettled_obligations,
      'place_obligations',v_place_owed,
      'rake_expected',v_rake_expected,
      'prize_balance',CASE WHEN v_escrow_found THEN v_escrow.prize_balance ELSE NULL END,
      'bounty_balance',CASE WHEN v_escrow_found THEN v_escrow.bounty_balance ELSE NULL END,
      'fee_balance',CASE WHEN v_escrow_found THEN v_escrow.fee_balance ELSE NULL END));
END;
$$;


ALTER FUNCTION public.fn_tournament_finish_readiness(p_tournament_id uuid, p_winner_user_id uuid) OWNER TO postgres;

--
-- Name: fn_tournament_guarantee_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_guarantee_check(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_checked   integer := 0;
  v_short     integer := 0;
  v_unpaid    integer := 0;
  v_chips     numeric := 0;
  v_raised    integer := 0;
  r           record;
BEGIN
  FOR r IN
    WITH scope AS (
      SELECT t.id, t.name, t.club_id, t.guaranteed_prize,
             COALESCE(t.prize_pool, 0) AS pool,
             COALESCE((
               SELECT sum(p.amount) FROM public.tournament_payouts p
                WHERE p.tournament_id = t.id
                  AND p.source IN ('structure','reconcile','hu_shortfall',
                                   'late_reg_adjustment','final_table_deal',
                                   'spin_backpay')
             ), 0) AS paid,
             EXISTS (SELECT 1 FROM public.tournament_guarantee_overlays o
                      WHERE o.tournament_id = t.id) AS overlay_funded,
             t.ended_at
        FROM public.tournaments t
       WHERE COALESCE(t.guaranteed_prize, 0) > 0
         AND t.status = 'COMPLETED'
         AND t.ended_at > now() - make_interval(hours => GREATEST(p_hours, 1))
         AND COALESCE(t.variant, '') <> 'satellite'
         AND UPPER(COALESCE(t.tournament_type, '')) <> 'SATELLITE'
    )
    SELECT * FROM scope
  LOOP
    v_checked := v_checked + 1;

    -- Rounded to the cent before comparing: the payout structure distributes
    -- in basis points with the residual on the last paid place, so an exact
    -- equality test would report a phantom shortfall of a fraction of a chip.
    CONTINUE WHEN round(r.paid, 2) >= round(r.guaranteed_prize, 2);

    v_short := v_short + 1;
    v_chips := v_chips + (r.guaranteed_prize - r.paid);
    IF r.paid = 0 THEN v_unpaid := v_unpaid + 1; END IF;

    -- One alert per event, ever. Re-running this hourly must not manufacture
    -- a new critical for the same settled tournament.
    IF NOT EXISTS (
      SELECT 1 FROM public.financial_alerts a
       WHERE a.source = 'Tournament.guarantee_not_met'
         AND a.context ->> 'tournament_id' = r.id::text
    ) THEN
      INSERT INTO public.financial_alerts (severity, source, message, context)
      VALUES (
        CASE WHEN r.paid = 0 THEN 'critical' ELSE 'warning' END,
        'Tournament.guarantee_not_met',
        CASE WHEN r.paid = 0
          THEN 'A tournament advertised a guaranteed prize, crowned its field, and paid nobody anything.'
          ELSE 'A tournament paid out less than its advertised guaranteed prize.'
        END,
        jsonb_build_object(
          'tournament_id',    r.id,
          'tournament_name',  r.name,
          'club_id',          r.club_id,
          'guaranteed_prize', r.guaranteed_prize,
          'prize_pool',       r.pool,
          'actually_paid',    r.paid,
          'shortfall',        round(r.guaranteed_prize - r.paid, 2),
          'overlay_funded',   r.overlay_funded,
          'ended_at',         r.ended_at
        )
      );
      v_raised := v_raised + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'window_hours', GREATEST(p_hours, 1),
    'checked', v_checked,
    'short_of_guarantee', v_short,
    'paid_nothing', v_unpaid,
    'chips_short', round(v_chips, 2),
    'alerts_raised', v_raised
  );
END;
$$;


ALTER FUNCTION public.fn_tournament_guarantee_check(p_hours integer) OWNER TO postgres;

--
-- Name: fn_tournament_has_unsettled_bounties(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_has_unsettled_bounties(p_tournament_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    EXISTS (
      SELECT 1 FROM public.tournament_bounty_obligations o
       WHERE o.tournament_id=p_tournament_id AND o.state='pending'
    )
    OR EXISTS (
      -- `settled` is only a cache of the marker trigger's last verdict. The
      -- canonical ledger/award can never be allowed to drift underneath it:
      -- finalisation re-proves the complete generation marker every time.
      SELECT 1 FROM public.tournament_bounty_obligations o
       WHERE o.tournament_id=p_tournament_id AND o.state='settled'
         AND NOT public.fn_bounty_obligation_has_complete_marker(o.id)
    )
    OR EXISTS (
      SELECT 1 FROM public.tournament_bounty_awards a
       WHERE a.tournament_id=p_tournament_id AND a.status IN ('reserved','revealed','paid')
    );
$$;


ALTER FUNCTION public.fn_tournament_has_unsettled_bounties(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_tournament_late_registration_open(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_late_registration_open(p_tournament_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE((
    SELECT t.status='RUNNING'
       AND NOT COALESCE(t.prize_pool_finalized,false)
       AND COALESCE(t.current_level,0)>=0
       AND COALESCE(t.late_reg_levels,0)>=0
       AND COALESCE(t.rebuy_levels,0)>=0
       AND COALESCE(t.late_reg_mins,0)>=0
       AND (
         CASE
           WHEN COALESCE(t.late_reg_levels,t.rebuy_levels,0)>0
             THEN COALESCE(t.current_level,0)
                    <COALESCE(t.late_reg_levels,t.rebuy_levels,0)
           WHEN COALESCE(t.late_reg_mins,0)>0
             THEN t.started_at IS NOT NULL
              AND clock_timestamp()
                    <t.started_at+make_interval(mins=>t.late_reg_mins)
           ELSE false
         END
       )
       AND (
         t.max_players IS NULL OR t.max_players<=0 OR (
           SELECT count(*) FROM public.tournament_players tp
            WHERE tp.tournament_id=t.id
         )<t.max_players
       )
      FROM public.tournaments t
     WHERE t.id=p_tournament_id
  ),false);
$$;


ALTER FUNCTION public.fn_tournament_late_registration_open(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_tournament_live_seat_acquisition_requires_authority(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_live_seat_acquisition_requires_authority() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_tournament_status text;
  v_key bigint:=hashtextextended(
    'ca:tournament-terminal-settlement:v1',0);
  v_owns_global boolean;
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.left_at IS NOT NULL OR NEW.user_id IS NULL THEN
      RETURN NEW;
    END IF;
  ELSE
    IF NEW.left_at IS NOT NULL OR NEW.user_id IS NULL
       OR (OLD.left_at IS NULL
         AND OLD.user_id IS NOT DISTINCT FROM NEW.user_id
         AND OLD.table_id IS NOT DISTINCT FROM NEW.table_id
         AND OLD.seat_number IS NOT DISTINCT FROM NEW.seat_number) THEN
      RETURN NEW;
    END IF;
  END IF;

  SELECT tb.tournament_id,upper(COALESCE(t.status::text,''))
    INTO v_tournament_id,v_tournament_status
    FROM public.tables tb
    LEFT JOIN public.tournaments t ON t.id=tb.tournament_id
   WHERE tb.id=NEW.table_id;
  IF v_tournament_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM pg_catalog.pg_locks l
     WHERE l.pid=pg_backend_pid()
       AND l.locktype='advisory'
       AND l.database=(
         SELECT d.oid FROM pg_catalog.pg_database d
          WHERE d.datname=current_database())
       AND l.classid=(((v_key>>32)&4294967295)::oid)
       AND l.objid=((v_key&4294967295)::oid)
       AND l.objsubid=1
       AND l.mode='ExclusiveLock'
       AND l.granted)
    INTO v_owns_global;
  IF NOT COALESCE(v_owns_global,false) THEN
    RAISE EXCEPTION
      'TOURNAMENT_SEAT_ACQUISITION_REQUIRES_TERMINAL_AUTHORITY'
      USING ERRCODE='55000',
            HINT='Use a canonical tournament seat purchase, registration, move, or assignment RPC.';
  END IF;
  IF v_tournament_status NOT IN ('ANNOUNCED','REGISTERING','RUNNING') THEN
    RAISE EXCEPTION
      'TOURNAMENT_SEAT_ACQUISITION_CLOSED: tournament %, status %',
      v_tournament_id,v_tournament_status
      USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_tournament_live_seat_acquisition_requires_authority() OWNER TO postgres;

--
-- Name: FUNCTION fn_tournament_live_seat_acquisition_requires_authority(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_tournament_live_seat_acquisition_requires_authority() IS 'Earliest BEFORE-seat fail-closed guard. A tournament seat create/revive or live identity/table change must enter with the terminal global transaction lock already held; raw service-role DML cannot bypass it.';


--
-- Name: fn_tournament_live_seat_exit_requires_authority(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_live_seat_exit_requires_authority() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_token uuid;
  v_operation text:=COALESCE(
    current_setting('app.tournament_seat_exit_operation',true),'');
  v_authorized integer;
  v_exit boolean:=false;
BEGIN
  IF OLD.left_at IS NOT NULL THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF TG_OP='DELETE' THEN
    v_exit:=true;
  ELSE
    v_exit:=NEW.left_at IS NOT NULL
      OR lower(COALESCE(NEW.status,''))='left'
      OR NEW.table_id IS DISTINCT FROM OLD.table_id
      OR NEW.user_id IS DISTINCT FROM OLD.user_id
      OR NEW.seat_number IS DISTINCT FROM OLD.seat_number;
  END IF;
  IF NOT v_exit THEN
    RETURN NEW;
  END IF;

  SELECT tb.tournament_id
    INTO v_tournament_id
    FROM public.tables tb
   WHERE tb.id=OLD.table_id;
  IF v_tournament_id IS NULL THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  BEGIN
    v_token:=NULLIF(
      current_setting('app.tournament_seat_exit_token',true),'')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_token:=NULL;
  END;
  IF v_token IS NULL OR v_operation='' THEN
    RAISE EXCEPTION
      'TOURNAMENT_SEAT_EXIT_REQUIRES_TOURNAMENT_AUTHORITY'
      USING ERRCODE='55000';
  END IF;

  DELETE FROM public.tournament_seat_exit_authorizations a
   WHERE a.token=v_token
     AND a.seat_id=OLD.id
     AND a.tournament_id=v_tournament_id
     AND a.user_id=OLD.user_id
     AND a.operation=v_operation;
  GET DIAGNOSTICS v_authorized=ROW_COUNT;
  IF v_authorized<>1 THEN
    RAISE EXCEPTION
      'TOURNAMENT_SEAT_EXIT_REQUIRES_TOURNAMENT_AUTHORITY'
      USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_tournament_live_seat_exit_requires_authority() OWNER TO postgres;

--
-- Name: fn_tournament_management_readiness(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_management_readiness(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row jsonb;
BEGIN
  SELECT to_jsonb(t)
    INTO v_row
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('state', 'missing', 'can_start', false);
  END IF;

  RETURN public.fn_tournament_management_readiness_for_row(v_row);
END;
$$;


ALTER FUNCTION public.fn_tournament_management_readiness(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_tournament_management_readiness_for_row(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_management_readiness_for_row(p_row jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid := NULLIF(p_row ->> 'id', '')::uuid;
  v_club uuid := NULLIF(p_row ->> 'club_id', '')::uuid;
  v_row_union uuid := NULLIF(p_row ->> 'union_id', '')::uuid;
  v_union uuid;
  v_private boolean := COALESCE((p_row ->> 'is_private')::boolean, false);
  v_enforce boolean;
  v_floor numeric;
  v_bank numeric;
  v_bank_type text;
  v_exposure numeric;
  v_guaranteed numeric := COALESCE(NULLIF(p_row ->> 'guaranteed_prize', '')::numeric, 0);
  v_pool numeric := COALESCE(NULLIF(p_row ->> 'prize_pool', '')::numeric, 0);
  v_effective_guarantee numeric;
  v_seat_guarantee numeric := 0;
  v_required numeric;
  v_short numeric;
  v_locked boolean;
  v_complete boolean;
  v_status text := upper(COALESCE(p_row ->> 'status', ''));
  v_variant text := lower(COALESCE(p_row ->> 'variant', ''));
  v_tournament_type text := upper(COALESCE(p_row ->> 'tournament_type', ''));
  v_target uuid := COALESCE(
    NULLIF(p_row ->> 'satellite_target_id', ''),
    NULLIF(p_row ->> 'satellite_target', '')
  )::uuid;
  v_satellite_seats integer := COALESCE(
    NULLIF(p_row ->> 'satellite_seats', '')::integer,
    0
  );
  v_is_satellite boolean := v_variant = 'satellite'
    OR v_tournament_type = 'SATELLITE'
    OR v_target IS NOT NULL;
  v_target_found boolean := false;
  v_blinds jsonb;
  v_payouts jsonb;
BEGIN
  IF v_id IS NULL OR v_club IS NULL THEN
    RETURN jsonb_build_object('state', 'missing', 'can_start', false);
  END IF;

  SELECT COALESCE(c.guarantee_enforcement_enabled, true),
         COALESCE(c.guarantee_treasury_floor, 0)
    INTO v_enforce, v_floor
    FROM public.clubs c
   WHERE c.id = v_club;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('state', 'missing', 'can_start', false);
  END IF;

  v_union := CASE WHEN v_private THEN NULL ELSE v_row_union END;

  IF v_is_satellite AND v_satellite_seats > 0 AND v_target IS NOT NULL THEN
    SELECT round(
             (COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0))
             * v_satellite_seats,
             2
           )
      INTO v_seat_guarantee
      FROM public.tournaments t
     WHERE t.id = v_target;
    v_target_found := FOUND;
    v_seat_guarantee := COALESCE(v_seat_guarantee, 0);
  END IF;

  v_effective_guarantee := greatest(v_guaranteed, v_seat_guarantee);

  IF v_union IS NOT NULL THEN
    v_bank_type := 'union';
    v_floor := 0;
    SELECT COALESCE(uw.chip_balance, 0)
      INTO v_bank
      FROM public.union_wallets uw
     WHERE uw.union_id = v_union;
    v_bank := COALESCE(v_bank, 0);

    SELECT COALESCE(sum(greatest(
             greatest(
               COALESCE(t.guaranteed_prize, 0),
               CASE
                 WHEN COALESCE(t.satellite_seats, 0) > 0
                      AND (
                        lower(COALESCE(t.variant, '')) = 'satellite'
                        OR upper(COALESCE(t.tournament_type, '')) = 'SATELLITE'
                        OR COALESCE(t.satellite_target_id, t.satellite_target) IS NOT NULL
                      )
                 THEN COALESCE(
                   (COALESCE(target.buy_in_amount, 0) + COALESCE(target.buy_in_fee, 0))
                   * t.satellite_seats,
                   0
                 )
                 ELSE 0
               END
             ) - COALESCE(t.prize_pool, 0),
             0
           )), 0)
      INTO v_exposure
      FROM public.tournaments t
      LEFT JOIN public.tournaments target
        ON target.id = COALESCE(t.satellite_target_id, t.satellite_target)
     WHERE t.union_id = v_union
       AND NOT COALESCE(t.is_private, false)
       AND t.id <> v_id
       AND NOT COALESCE(t.prize_pool_finalized, false)
       AND upper(t.status::text) IN ('ANNOUNCED', 'REGISTERING', 'RUNNING');
  ELSE
    v_bank_type := 'club';
    SELECT COALESCE(c.chip_treasury, 0)
      INTO v_bank
      FROM public.clubs c
     WHERE c.id = v_club;
    v_bank := COALESCE(v_bank, 0);

    SELECT COALESCE(sum(greatest(
             greatest(
               COALESCE(t.guaranteed_prize, 0),
               CASE
                 WHEN COALESCE(t.satellite_seats, 0) > 0
                      AND (
                        lower(COALESCE(t.variant, '')) = 'satellite'
                        OR upper(COALESCE(t.tournament_type, '')) = 'SATELLITE'
                        OR COALESCE(t.satellite_target_id, t.satellite_target) IS NOT NULL
                      )
                 THEN COALESCE(
                   (COALESCE(target.buy_in_amount, 0) + COALESCE(target.buy_in_fee, 0))
                   * t.satellite_seats,
                   0
                 )
                 ELSE 0
               END
             ) - COALESCE(t.prize_pool, 0),
             0
           )), 0)
      INTO v_exposure
      FROM public.tournaments t
      LEFT JOIN public.tournaments target
        ON target.id = COALESCE(t.satellite_target_id, t.satellite_target)
     WHERE t.club_id = v_club
       AND (COALESCE(t.is_private, false) OR t.union_id IS NULL)
       AND t.id <> v_id
       AND NOT COALESCE(t.prize_pool_finalized, false)
       AND upper(t.status::text) IN ('ANNOUNCED', 'REGISTERING', 'RUNNING');
  END IF;

  v_required := greatest(v_effective_guarantee - v_pool, 0);
  v_short := greatest(
    COALESCE(v_floor, 0) + COALESCE(v_exposure, 0) + v_required - v_bank,
    0
  );
  v_locked := EXISTS (
    SELECT 1
      FROM public.tournament_players tp
     WHERE tp.tournament_id = v_id
  );

  v_blinds := CASE
    WHEN jsonb_typeof(p_row -> 'blind_structure') = 'array'
      THEN p_row -> 'blind_structure'
    ELSE public.fn_safe_jsonb_array(p_row ->> 'blind_structure')
  END;
  v_payouts := CASE
    WHEN jsonb_typeof(p_row -> 'payout_structure') = 'array'
      THEN p_row -> 'payout_structure'
    ELSE public.fn_safe_jsonb_array(p_row ->> 'payout_structure')
  END;

  v_complete := NULLIF(trim(COALESCE(p_row ->> 'name', '')), '') IS NOT NULL
    AND (
      NULLIF(p_row ->> 'start_time', '') IS NOT NULL
      OR v_tournament_type IN ('SNG', 'SPIN')
      OR v_variant IN ('sng', 'spin')
    )
    AND COALESCE(NULLIF(p_row ->> 'starting_chips', '')::numeric, 0) > 0
    AND COALESCE(NULLIF(p_row ->> 'max_players', '')::integer, 0) >= 2
    AND COALESCE(NULLIF(p_row ->> 'buy_in_amount', '')::numeric, 0) >= 0
    AND jsonb_array_length(v_blinds) > 0
    AND (
      jsonb_array_length(v_payouts) > 0
      OR v_tournament_type = 'SPIN'
      OR v_variant = 'spin'
    )
    AND (
      NOT v_is_satellite
      OR (v_satellite_seats > 0 AND v_target IS NOT NULL AND v_target_found)
    );

  RETURN jsonb_build_object(
    'state', CASE
      WHEN v_status IN ('COMPLETED', 'CANCELLED', 'CANCELED') THEN 'closed'
      WHEN NOT v_complete THEN 'incomplete'
      WHEN v_enforce AND v_short > 0 THEN 'funding_blocked'
      ELSE 'ready'
    END,
    'can_start', v_status NOT IN ('COMPLETED', 'CANCELLED', 'CANCELED')
      AND v_complete
      AND (NOT v_enforce OR v_short = 0),
    'contract_locked', v_locked,
    'guarantee_enforced', v_enforce,
    'guaranteed_prize', v_guaranteed,
    'satellite_seat_guarantee', v_seat_guarantee,
    'effective_guarantee', v_effective_guarantee,
    'current_prize_pool', v_pool,
    'overlay_required', v_required,
    'bank_type', v_bank_type,
    'bank_balance', v_bank,
    'bank_floor', COALESCE(v_floor, 0),
    'other_live_exposure', COALESCE(v_exposure, 0),
    'short_by', v_short
  );
END;
$$;


ALTER FUNCTION public.fn_tournament_management_readiness_for_row(p_row jsonb) OWNER TO postgres;

--
-- Name: fn_tournament_metrics(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_metrics(p_overdue_minutes integer DEFAULT 10, p_completing_minutes integer DEFAULT 10, p_unpaid_hours integer DEFAULT 6) RETURNS TABLE(running integer, registering integer, overdue_start integer, stuck_completing integer, seatless_phantoms integer, unpaid_completed integer, seat_first_waiting integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    (SELECT count(*) FROM tournaments WHERE status = 'RUNNING')::int,
    (SELECT count(*) FROM tournaments WHERE status = 'REGISTERING')::int,
    (SELECT count(*) FROM tournaments
      WHERE status IN ('REGISTERING','ANNOUNCED')
        AND tournament_type = 'MTT'
        AND start_time < now() - make_interval(mins => GREATEST(p_overdue_minutes, 0)))::int,
    (SELECT count(*) FROM tournaments
      WHERE status = 'COMPLETING'
        AND updated_at < now() - make_interval(mins => GREATEST(p_completing_minutes, 0)))::int,
    (SELECT count(*) FROM tournament_players tp
       JOIN tournaments t ON t.id = tp.tournament_id AND t.status = 'RUNNING'
      WHERE tp.status = 'playing'
        AND tp.chips > 0
        AND NOT EXISTS (
          SELECT 1 FROM table_seats s
            JOIN tables tb ON tb.id = s.table_id
           WHERE tb.tournament_id = tp.tournament_id
             AND s.user_id = tp.user_id
             AND s.left_at IS NULL))::int,
    (SELECT count(*) FROM tournaments t
      WHERE t.status = 'COMPLETED'
        AND t.ended_at > now() - make_interval(hours => GREATEST(p_unpaid_hours, 0))
        AND COALESCE(t.prize_pool, 0) > 0
        AND NOT EXISTS (
          SELECT 1 FROM wallet_transactions w
           WHERE w.related_entity_id = t.id AND w.category = 'prize'))::int,
    (SELECT count(*) FROM tournaments
      WHERE status IN ('REGISTERING','ANNOUNCED')
        AND tournament_type <> 'MTT'
        AND start_time < now() - make_interval(mins => GREATEST(p_overdue_minutes, 0)))::int;
$$;


ALTER FUNCTION public.fn_tournament_metrics(p_overdue_minutes integer, p_completing_minutes integer, p_unpaid_hours integer) OWNER TO postgres;

--
-- Name: fn_tournament_money_conservation(integer, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_money_conservation(p_since_days integer DEFAULT 7, p_tolerance numeric DEFAULT 0.05, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row       record;
  v_flagged   integer := 0;
  v_scanned   integer := 0;
  v_reported  integer := 0;
  v_resolved  integer := 0;
  v_retained  numeric := 0;
  v_unfunded  numeric := 0;
  v_worst     numeric := 0;
  v_delta     numeric;
  v_ins       integer;
  v_tol       numeric := GREATEST(p_tolerance, 0);
  v_days      integer := GREATEST(p_since_days, 1);
  v_cap       integer := GREATEST(p_limit, 1);
  v_started   timestamptz := clock_timestamp();
BEGIN
  ---------------------------------------------------------------------------
  -- Pass 1: auto-resolve open alerts that have come back inside tolerance.
  -- Unchanged from the original.
  ---------------------------------------------------------------------------
  FOR v_row IN
    SELECT fa.id, (fa.context->>'tournament_id')::uuid AS tid
      FROM public.financial_alerts fa
     WHERE fa.source = 'fn_tournament_money_conservation'
       AND fa.resolved IS NOT TRUE
       AND fa.context->>'tournament_id' IS NOT NULL
     ORDER BY fa.created_at ASC
     LIMIT 1000
  LOOP
    v_delta := public.fn_tournament_conservation_delta(v_row.tid);
    IF v_delta IS NOT NULL AND abs(v_delta) <= v_tol THEN
      UPDATE public.financial_alerts
         SET resolved = true, resolved_at = now()
       WHERE id = v_row.id;
      v_resolved := v_resolved + 1;
    END IF;
  END LOOP;

  ---------------------------------------------------------------------------
  -- Pass 2: scan the FULL p_since_days window. No LIMIT here -- that was the
  -- defect. Deltas are computed once in the CTE and the offenders are visited
  -- worst-first so that a report truncated by p_limit is still the top of the
  -- problem.
  --
  -- SATELLITES ARE IN THE SCAN NOW (2026-09-02, Phase 4). They were excluded
  -- because they could never balance, which is circular: they could never
  -- balance only because the seat a satellite pays was invisible to the delta.
  -- 'spin' stays out - its pool is funded by the Reserve Pool rather than by
  -- its own collections, and it has its own check.
  ---------------------------------------------------------------------------
  FOR v_row IN
    WITH scan AS (
      SELECT t.id, t.name, t.variant, t.ended_at,
             public.fn_tournament_conservation_delta(t.id) AS delta
        FROM public.tournaments t
       WHERE t.status IN ('COMPLETED','CANCELLED')
         AND t.ended_at > now() - make_interval(days => v_days)
         AND t.ended_at < now() - interval '30 minutes'
         AND COALESCE(t.variant, '') NOT IN ('spin')
         AND COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0) > 0
    )
    SELECT s.id, s.name, s.variant, s.delta
      FROM scan s
     ORDER BY abs(s.delta) DESC NULLS LAST, s.ended_at DESC
  LOOP
    v_scanned := v_scanned + 1;
    v_delta := v_row.delta;

    IF v_delta IS NULL OR abs(v_delta) <= v_tol THEN CONTINUE; END IF;

    IF v_delta > 0 THEN v_retained := v_retained + v_delta;
    ELSE                v_unfunded := v_unfunded - v_delta; END IF;
    v_flagged := v_flagged + 1;
    v_worst := GREATEST(v_worst, abs(v_delta));

    -- p_limit caps how many NEW alerts one run may raise. Detection above is
    -- already complete and unconditional; this only throttles the write side.
    IF v_reported < v_cap THEN
      INSERT INTO public.financial_alerts (severity, source, message, context)
      SELECT 'warning', 'fn_tournament_money_conservation',
             CASE WHEN v_delta > 0
                  THEN 'Tournament retained money it never paid out: '
                  ELSE 'Tournament paid out money it never collected: ' END
               || COALESCE(v_row.name, v_row.id::text),
             jsonb_build_object('tournament_id', v_row.id, 'variant', v_row.variant,
                                'delta', v_delta)
       WHERE NOT EXISTS (
         SELECT 1 FROM public.financial_alerts
          WHERE source = 'fn_tournament_money_conservation'
            AND resolved IS NOT TRUE
            AND context->>'tournament_id' = v_row.id::text);
      GET DIAGNOSTICS v_ins = ROW_COUNT;
      v_reported := v_reported + v_ins;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',               (v_flagged = 0),
    'check_ran',        true,
    'scanned',          v_scanned,
    'flagged',          v_flagged,
    'reported',         v_reported,
    'report_truncated', (v_reported >= v_cap AND v_flagged > v_reported),
    'window_days',      v_days,
    'tolerance',        v_tol,
    'report_limit',     v_cap,
    'auto_resolved',    v_resolved,
    'retained_chips',   round(v_retained, 2),
    'unfunded_chips',   round(v_unfunded, 2),
    'worst_abs_delta',  round(v_worst, 2),
    'duration_ms',      round(extract(epoch FROM clock_timestamp() - v_started) * 1000)
  );
END;
$$;


ALTER FUNCTION public.fn_tournament_money_conservation(p_since_days integer, p_tolerance numeric, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_tournament_money_conservation(p_since_days integer, p_tolerance numeric, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_tournament_money_conservation(p_since_days integer, p_tolerance numeric, p_limit integer) IS 'Tournament money-conservation watchdog. Scans EVERY qualifying event in the p_since_days window (previously the scan was silently capped at p_limit rows ordered newest-first, so a 30-day request only ever examined the newest 500 events - roughly 26 hours of coverage). p_limit now caps only how many NEW financial_alerts rows a single run may raise; offenders are visited worst-first. ''ok'' now means (flagged = 0), not "the procedure ran" - use ''check_ran'' for the latter. Expensive: one full 30-day scan is ~13.6k delta evaluations, ~8s. Schedule it, do not poll it.';


--
-- Name: fn_tournament_obligation_paid_so_far(uuid, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_obligation_paid_so_far(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_kind text := lower(btrim(COALESCE(p_kind, '')));
  v_row_kind text;
  v_paid numeric;
BEGIN
  v_row_kind := CASE WHEN v_kind = 'late_reg_adjustment' THEN 'place' ELSE v_kind END;

  IF v_row_kind = 'place' THEN
    SELECT o.amount_paid INTO v_paid
      FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place' AND o.place = p_place;
    IF FOUND THEN RETURN round(COALESCE(v_paid, 0), 2); END IF;

    SELECT COALESCE(sum(tp.amount), 0) INTO v_paid
      FROM public.tournament_payouts tp
     WHERE tp.tournament_id = p_tournament_id AND tp."position" = p_place
       AND COALESCE(tp.source, '') NOT IN ('satellite_seat');
    RETURN round(COALESCE(v_paid, 0), 2);
  END IF;

  SELECT o.amount_paid INTO v_paid
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id AND o.kind = v_row_kind
     AND o.place IS NULL AND o.user_id = p_user_id;
  IF FOUND THEN RETURN round(COALESCE(v_paid, 0), 2); END IF;

  IF v_row_kind = 'refund' THEN
    SELECT COALESCE(sum(w.amount), 0) INTO v_paid
      FROM public.wallet_transactions w
     WHERE w.related_entity_id = p_tournament_id AND w.user_id = p_user_id
       AND w.type = 'credit' AND lower(w.category) IN ('refund','tournament_refund');
    RETURN round(COALESCE(v_paid, 0), 2);
  END IF;

  RETURN 0;
END;
$$;


ALTER FUNCTION public.fn_tournament_obligation_paid_so_far(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_tournament_obligation_paid_so_far(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_tournament_obligation_paid_so_far(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid) IS 'Read-only. The amount fn_settle_tournament_obligation will treat as already paid for this obligation (the obligation row, else its legacy seed). A caller that knows a shortfall passes paid_so_far + shortfall as the TOTAL. Lane A3, 2026-09-02.';


