--
-- Name: fn_tournament_payouts_are_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_payouts_are_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_terminal_key bigint := hashtextextended(
    'ca:tournament-terminal-settlement:v1',0);
  v_owns_terminal_root boolean := false;
BEGIN
  IF session_user = 'postgres'
     AND COALESCE(current_setting('app.payout_record_correction', true), '') =
         'i_am_correcting_the_record' THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF TG_OP = 'UPDATE' AND pg_trigger_depth() >= 2 THEN
    SELECT EXISTS(
      SELECT 1 FROM pg_catalog.pg_locks l
       WHERE l.pid = pg_backend_pid()
         AND l.locktype = 'advisory'
         AND l.database = (
           SELECT d.oid FROM pg_catalog.pg_database d
            WHERE d.datname = current_database())
         AND l.classid = (((v_terminal_key >> 32) & 4294967295)::oid)
         AND l.objid = ((v_terminal_key & 4294967295)::oid)
         AND l.objsubid = 1
         AND l.mode = 'ExclusiveLock'
         AND l.granted)
      INTO v_owns_terminal_root;

    IF v_owns_terminal_root
       AND public.fn_ca_terminal_marker_transition_is_exact(
         to_jsonb(OLD),to_jsonb(NEW),OLD.tournament_id) THEN
      RETURN NEW;
    END IF;
  END IF;

  RAISE EXCEPTION
    'tournament_payouts is an append-only payout record; % is refused (tournament %, user %, position %)',
    TG_OP, OLD.tournament_id, OLD.user_id, OLD."position"
    USING ERRCODE = 'restrict_violation',
          HINT = 'A DBA correcting a bad row must SET LOCAL app.payout_record_correction = ''i_am_correcting_the_record'' in the same transaction, from a migration that says why.';
END;
$$;


ALTER FUNCTION public.fn_tournament_payouts_are_append_only() OWNER TO postgres;

--
-- Name: fn_tournament_place_prize_exact(numeric, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_place_prize_exact(p_pool numeric, p_structure text, p_place integer) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_arr jsonb := public.fn_safe_jsonb_array(p_structure);
  v_pool_cents numeric := GREATEST(round(COALESCE(p_pool,0)*100),0);
  v_total_bp numeric;
  v_last_place integer;
  v_remaining numeric;
  v_share numeric;
  r record;
BEGIN
  IF p_place IS NULL OR v_pool_cents<=0 OR jsonb_array_length(v_arr)=0 THEN
    RETURN 0;
  END IF;

  WITH numbered AS (
    SELECT e.value,e.ordinality,
           CASE WHEN COALESCE(e.value->>'place','') ~ '^[0-9]+$'
                THEN (e.value->>'place')::integer END AS place,
           CASE WHEN COALESCE(e.value->>'percentage','') ~ '^[0-9]+([.][0-9]+)?$'
                THEN GREATEST((e.value->>'percentage')::numeric,0) ELSE 0 END AS pct
      FROM jsonb_array_elements(v_arr) WITH ORDINALITY e(value,ordinality)
  ), clean AS (
    SELECT DISTINCT ON (place) place,round(pct*100) AS bp
      FROM numbered
     WHERE place>0
     ORDER BY place,ordinality
  )
  SELECT COALESCE(sum(bp),0),max(place)
    INTO v_total_bp,v_last_place
    FROM clean;
  IF v_total_bp<=0 OR v_last_place IS NULL THEN RETURN 0; END IF;

  v_remaining := v_pool_cents;
  FOR r IN
    WITH numbered AS (
      SELECT e.value,e.ordinality,
             CASE WHEN COALESCE(e.value->>'place','') ~ '^[0-9]+$'
                  THEN (e.value->>'place')::integer END AS place,
             CASE WHEN COALESCE(e.value->>'percentage','') ~ '^[0-9]+([.][0-9]+)?$'
                  THEN GREATEST((e.value->>'percentage')::numeric,0) ELSE 0 END AS pct
        FROM jsonb_array_elements(v_arr) WITH ORDINALITY e(value,ordinality)
    )
    SELECT DISTINCT ON (place) place,round(pct*100) AS bp
      FROM numbered
     WHERE place>0
     ORDER BY place,ordinality
  LOOP
    IF r.place=v_last_place THEN
      v_share := GREATEST(v_remaining,0);
    ELSE
      v_share := GREATEST(
        LEAST(v_remaining,round(v_pool_cents*r.bp/v_total_bp)),0);
    END IF;
    v_remaining := v_remaining-v_share;
    IF r.place=p_place THEN RETURN v_share/100; END IF;
  END LOOP;
  RETURN 0;
END;
$_$;


ALTER FUNCTION public.fn_tournament_place_prize_exact(p_pool numeric, p_structure text, p_place integer) OWNER TO postgres;

--
-- Name: fn_tournament_primary_table(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_primary_table(p_tournament_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT tb.id
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
     AND lower(COALESCE(tb.status, '')) <> 'closed'
   ORDER BY (
       SELECT count(*) FROM public.table_seats s
        WHERE s.table_id = tb.id AND s.left_at IS NULL
     ) DESC,
     tb.created_at ASC
   LIMIT 1;
$$;


ALTER FUNCTION public.fn_tournament_primary_table(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: fn_tournament_prize_disbursement_audit(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_prize_disbursement_audit(p_hours integer DEFAULT 24) RETURNS TABLE(tournament_id uuid, name text, variant text, prize_pool numeric, disbursed numeric, acknowledged numeric, excess numeric, ended_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH t AS (
    SELECT x.id, x.name, x.variant,
           -- A Spin promises buy_in x multiplier, paid from the spin reserve;
           -- its prize_pool column is the buy-ins and is not what it owes.
           CASE WHEN x.variant = 'spin' AND COALESCE(x.spin_multiplier, 0) > 0
                THEN GREATEST(x.prize_pool::numeric, round(COALESCE(x.buy_in_amount,0) * x.spin_multiplier, 2))
                ELSE x.prize_pool::numeric END AS pool,
           x.ended_at
      FROM public.tournaments x
     WHERE x.status = 'COMPLETED'
       AND x.ended_at > now() - make_interval(hours => GREATEST(COALESCE(p_hours,24),1))
       AND COALESCE(x.prize_pool,0) > 0
  ), paid AS (
    SELECT w.related_entity_id tid, round(sum(w.amount),2) amt
      FROM public.wallet_transactions w
      JOIN t ON t.id = w.related_entity_id
     WHERE w.type = 'credit' AND w.category = 'prize'
     GROUP BY 1
  )
  SELECT t.id, t.name, t.variant, t.pool,
         COALESCE(p.amt,0),
         COALESCE(b.amount,0),
         round(COALESCE(p.amt,0) - t.pool - COALESCE(b.amount,0), 2),
         t.ended_at
    FROM t
    LEFT JOIN paid p ON p.tid = t.id
    LEFT JOIN public.tournament_conservation_baseline b ON b.tournament_id = t.id
   WHERE round(COALESCE(p.amt,0) - t.pool - COALESCE(b.amount,0), 2) > 0.005;
$$;


ALTER FUNCTION public.fn_tournament_prize_disbursement_audit(p_hours integer) OWNER TO postgres;

--
-- Name: fn_tournament_rake_settlement_check(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_rake_settlement_check(p_grace_minutes integer DEFAULT 30, p_since_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_grace    integer := GREATEST(COALESCE(p_grace_minutes, 30), 1);
  v_days     integer := GREATEST(COALESCE(p_since_days, 7), 1);
  v_missing  integer := 0;
  v_owed     numeric := 0;
  v_oldest   timestamptz;
  v_ids      uuid[];
  v_verdict  text := 'pass';
  v_severity text;
  v_message  text;
  v_context  jsonb;
  v_alerts   integer := 0;
BEGIN
  WITH unsettled AS (
    SELECT t.id,
           t.ended_at,
           (SELECT COALESCE(sum(r.rake_amount), 0) FROM public.rake_records r
             WHERE r.tournament_id = t.id AND r.is_tournament) AS banked
      FROM public.tournaments t
     WHERE upper(COALESCE(t.status, '')) IN ('COMPLETED', 'CANCELLED', 'CANCELED')
       AND t.ended_at IS NOT NULL
       AND t.ended_at > now() - make_interval(days => v_days)
       AND t.ended_at < now() - make_interval(mins => v_grace)
       AND EXISTS (SELECT 1 FROM public.rake_records r
                    WHERE r.tournament_id = t.id AND r.is_tournament)
       AND NOT EXISTS (SELECT 1 FROM public.tournament_rake_settlements s
                        WHERE s.tournament_id = t.id)
  )
  SELECT count(*),
         COALESCE(sum(banked), 0),
         min(ended_at),
         COALESCE((array_agg(id ORDER BY ended_at))[1:20], ARRAY[]::uuid[])
    INTO v_missing, v_owed, v_oldest, v_ids
    FROM unsettled;

  IF v_missing > 0 THEN
    v_verdict  := 'rake_never_settled';
    v_severity := CASE WHEN v_missing >= 5 OR v_owed >= 50 THEN 'critical' ELSE 'warning' END;
    v_message  := format(
      '%s terminal tournament(s) have banked rake and no settlement row after '
      '%s minutes, holding %s in rake the union has not been paid. Oldest '
      'finished %s. The attribution view cannot see these: it starts from the '
      'settlements table, and these have no row to start from.',
      v_missing, v_grace, round(v_owed, 2), v_oldest);
  END IF;

  v_context := jsonb_build_object(
    'grace_minutes',  v_grace,
    'window_days',    v_days,
    'missing_count',  v_missing,
    'rake_unpaid',    round(v_owed, 2),
    'oldest_ended_at', v_oldest,
    'sample_games',   to_jsonb(v_ids),
    'verdict',        v_verdict,
    'detail',         'the sweep settles these; this check only reports them, '
                      'so a broken sweep cannot be masked by its own watcher');

  IF v_severity IS NOT NULL THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT v_severity, 'fn_tournament_rake_settlement_check', v_message, v_context
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'fn_tournament_rake_settlement_check'
          AND fa.resolved IS NOT TRUE
          AND fa.context->>'verdict' = v_verdict);
    IF FOUND THEN v_alerts := 1; END IF;
  END IF;

  RETURN v_context || jsonb_build_object('ok', true, 'alerts_raised', v_alerts);
END;
$$;


ALTER FUNCTION public.fn_tournament_rake_settlement_check(p_grace_minutes integer, p_since_days integer) OWNER TO postgres;

--
-- Name: fn_tournament_register_counter(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_register_counter(p_tournament_id uuid, p_buy_in numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_new_count INT;
  v_new_pool NUMERIC;
  v_max INT;
BEGIN
  UPDATE public.club_tournaments
  SET registered_count = registered_count + 1,
      prize_pool = COALESCE(prize_pool, 0) + p_buy_in
  WHERE id = p_tournament_id
  RETURNING registered_count, prize_pool, max_players
  INTO v_new_count, v_new_pool, v_max;

  IF v_new_count IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tournament not found');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'registered_count', v_new_count,
    'prize_pool', v_new_pool,
    'max_players', v_max
  );
END;
$$;


ALTER FUNCTION public.fn_tournament_register_counter(p_tournament_id uuid, p_buy_in numeric) OWNER TO postgres;

--
-- Name: fn_tournament_seat_move_receipts_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_seat_move_receipts_append_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'tournament seat move receipts are append-only'
    USING ERRCODE='55000';
END;
$$;


ALTER FUNCTION public.fn_tournament_seat_move_receipts_append_only() OWNER TO postgres;

--
-- Name: fn_tournament_table_terminal_close_is_irreversible(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_table_terminal_close_is_irreversible() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new_status text;
  v_ended_at timestamptz;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- Tournament tables are durable event evidence. They close; they are never
    -- deleted. This unconditional rule needs no parent lock after PostgreSQL
    -- has already acquired the child row, so it cannot reverse terminal's
    -- tournament -> table order.
    IF OLD.tournament_id IS NOT NULL THEN
      RAISE EXCEPTION 'tournament table % is durable and cannot be deleted',OLD.id
        USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.terminal_closed_at IS NOT NULL THEN
      RAISE EXCEPTION 'new table % cannot supply a terminal marker',NEW.id
        USING ERRCODE = '55000';
    END IF;
    IF NEW.tournament_id IS NOT NULL THEN
      -- INSERT has no child row to lock yet, so taking the parent first is
      -- deadlock-safe. If terminal owns it, this waits and then sees COMPLETED;
      -- if expansion owns it first, terminal waits and includes the new table.
      SELECT upper(COALESCE(t.status::text,'')) INTO v_new_status
        FROM public.tournaments t
       WHERE t.id = NEW.tournament_id
       FOR SHARE;
      IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
        RAISE EXCEPTION 'cannot add table % to terminal tournament %',
          NEW.id,NEW.tournament_id USING ERRCODE = '55000';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'table identity % is immutable',OLD.id
      USING ERRCODE = '55000';
  END IF;

  -- Reassociation would be a child-row-first parent transition and would also
  -- change the immutable event table set. Tournament membership never moves.
  IF NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
     AND (NEW.tournament_id IS NOT NULL OR OLD.tournament_id IS NOT NULL) THEN
    RAISE EXCEPTION 'table % tournament association is immutable',OLD.id
      USING ERRCODE = '55000';
  END IF;

  IF OLD.terminal_closed_at IS NOT NULL THEN
    IF NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.terminal_closed_at IS DISTINCT FROM OLD.terminal_closed_at
       OR lower(COALESCE(NEW.status::text,'')) <> 'closed'
       OR lower(COALESCE(NEW.lifecycle,'')) <> 'closed'
       OR NEW.current_players IS DISTINCT FROM 0 THEN
      RAISE EXCEPTION 'terminal tournament table % cannot reopen or move',OLD.id
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')),t.ended_at
      INTO v_new_status,v_ended_at
      FROM public.tournaments t WHERE t.id = NEW.tournament_id;
    IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      IF NEW.current_players IS DISTINCT FROM 0 THEN
        RAISE EXCEPTION 'table % cannot reopen terminal tournament %',
          NEW.id,NEW.tournament_id USING ERRCODE = '55000';
      END IF;
      -- The existing game-end hook first clears current_players while leaving
      -- status unchanged. Coerce that one-way zero-player write directly to
      -- the terminal shape; delayed waiting/running writes can never reopen it.
      NEW.status := 'closed';
      NEW.lifecycle := 'closed';
      NEW.terminal_closed_at := COALESCE(v_ended_at,transaction_timestamp());
    ELSIF NEW.terminal_closed_at IS NOT NULL THEN
      RAISE EXCEPTION 'live tournament table % cannot supply a terminal marker',NEW.id
        USING ERRCODE = '55000';
    END IF;
  ELSIF NEW.terminal_closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'unscoped table % cannot supply a terminal marker',NEW.id
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_tournament_table_terminal_close_is_irreversible() OWNER TO postgres;

