--
-- Name: fn_tournaments_creation_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournaments_creation_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_paid int;
BEGIN
  IF COALESCE(NEW.max_players, 0) <= 0 THEN
    RAISE EXCEPTION
      'tournament guard: max_players must be positive (got %) - a tournament with no seats can never start',
      NEW.max_players
      USING ERRCODE = '23514';
  END IF;

  IF NEW.payout_structure IS NOT NULL
     AND jsonb_typeof(NEW.payout_structure::jsonb) = 'array' THEN
    v_paid := jsonb_array_length(NEW.payout_structure::jsonb);
    IF v_paid > NEW.max_players THEN
      RAISE EXCEPTION
        'tournament guard: % paid places for % seats - more places than players who can enter',
        v_paid, NEW.max_players
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_tournaments_creation_guard() OWNER TO postgres;

--
-- Name: fn_tournaments_refuse_unbuilt_multi_day(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournaments_refuse_unbuilt_multi_day() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_field text := NULL;
BEGIN
  /* THE BADGE COLUMNS - what the lobby reads. These were already refused. */
  IF COALESCE(NEW.is_multi_day, false) IS TRUE THEN
    v_field := 'is_multi_day';
  ELSIF COALESCE(NEW.total_days, 1) > 1 THEN
    v_field := 'total_days';

  /* THE STRUCTURE COLUMNS - what would actually make a flight, and what was
     open until 2026-09-02. A row carrying these has no badge, so nothing warns
     anybody, and nothing on the platform advances a survivor or moves a pool
     between days. It would also switch on the day-2 exemption inside
     fn_uncollected_entry_check, excusing seats from the was-this-paid-for
     question on the strength of a Day 2 that does not exist. */
  ELSIF COALESCE(NEW.day_number, 1) > 1 THEN
    v_field := 'day_number';
  ELSIF NEW.parent_tournament_id IS NOT NULL THEN
    v_field := 'parent_tournament_id';
  ELSIF NEW.survivors_advance_to IS NOT NULL THEN
    v_field := 'survivors_advance_to';
  ELSIF NEW.flight_number IS NOT NULL THEN
    v_field := 'flight_number';
  ELSIF NEW.flight_end_chips_snapshot IS NOT NULL THEN
    v_field := 'flight_end_chips_snapshot';
  END IF;

  IF v_field IS NOT NULL THEN
    RAISE EXCEPTION
      'Multi day tournaments are not built yet (refused on %). There is no day '
      'end, no Day 2 resume and no flight merge, so this event would play down '
      'to a single winner in one session while the lobby promised otherwise, '
      'and a half built flight would excuse its seats from the uncollected '
      'entry check. Leave multi day off. Drop this trigger in the commit that '
      'implements Day 2.', v_field
      USING ERRCODE = '0A000';
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_tournaments_refuse_unbuilt_multi_day() OWNER TO postgres;

--
-- Name: FUNCTION fn_tournaments_refuse_unbuilt_multi_day(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_tournaments_refuse_unbuilt_multi_day() IS 'Refuses every column that would badge OR structure a multi-day event, until Day 2 is built. Widened 2026-09-02: the original covered is_multi_day and total_days only, leaving day_number, parent_tournament_id, survivors_advance_to, flight_number and flight_end_chips_snapshot open.';


--
-- Name: fn_track_club_entry_event(uuid, text, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_track_club_entry_event(p_session_id uuid, p_flow text, p_event_name text, p_outcome text DEFAULT NULL::text, p_duration_ms integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid:=auth.uid(); v_metadata jsonb;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;
  IF p_flow NOT IN ('create','find','join','action_bar') THEN RETURN; END IF;
  IF p_event_name NOT IN (
    'opened','closed','submitted','completed','previewed','searched','loaded_more',
    'privacy_saved','draft_restored','logo_generated','qr_imported','recovered'
  ) THEN RETURN; END IF;
  IF p_outcome IS NOT NULL AND p_outcome NOT IN ('started','succeeded','failed','cancelled','viewed') THEN RETURN; END IF;
  -- Only low-cardinality operational fields survive. Names, queries, codes,
  -- referral IDs, descriptions, and image URLs can never enter analytics.
  v_metadata := jsonb_strip_nulls(jsonb_build_object(
    'source',p_metadata->>'source','status',p_metadata->>'status',
    'error_code',p_metadata->>'error_code','result_count',p_metadata->'result_count',
    'feature_variant',p_metadata->>'feature_variant'
  ));
  INSERT INTO public.club_entry_events(actor_id,session_id,flow,event_name,outcome,duration_ms,metadata)
  VALUES(v_uid,p_session_id,p_flow,p_event_name,p_outcome,
    LEAST(GREATEST(COALESCE(p_duration_ms,0),0),3600000),v_metadata);
END $$;


ALTER FUNCTION public.fn_track_club_entry_event(p_session_id uuid, p_flow text, p_event_name text, p_outcome text, p_duration_ms integer, p_metadata jsonb) OWNER TO postgres;

--
-- Name: fn_track_flake_strike(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_track_flake_strike() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_game        RECORD;
    v_group       RECORD;
    v_strikes     int;
    v_threshold   int;
BEGIN
    -- Only fire on transitions TO flaked=true
    IF NOT (NEW.flaked = true AND (OLD.flaked IS DISTINCT FROM true)) THEN 
        RETURN NEW; 
    END IF;

    SELECT * INTO v_game FROM commander_home_games WHERE id = NEW.game_id;
    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;

    -- Increment the member's strike count for this group
    UPDATE commander_home_members 
       SET flake_strikes = flake_strikes + 1
     WHERE group_id = v_game.group_id AND user_id = NEW.user_id
    RETURNING flake_strikes INTO v_strikes;

    v_threshold := v_group.auto_ban_after_flakes;
    IF v_threshold IS NOT NULL AND v_strikes IS NOT NULL AND v_strikes >= v_threshold THEN
        -- Auto-ban
        UPDATE commander_home_members
           SET status = 'banned'
         WHERE group_id = v_game.group_id AND user_id = NEW.user_id
           AND status <> 'banned';

        INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
        VALUES (v_game.group_id, NULL, 'member', NEW.user_id, 'auto_banned_flakes',
                jsonb_build_object('strikes', v_strikes, 'threshold', v_threshold, 
                                    'source_game_id', v_game.id));
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_track_flake_strike() OWNER TO postgres;

