--
-- Name: fn_training_attempt_record_served_batch_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_attempt_record_served_batch_v1(p_attempt_id uuid, p_user_id uuid, p_deliveries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_delivery jsonb;
  v_attempt public.training_attempts%ROWTYPE;
  v_hand integer;
  v_decision integer;
  v_snapshot_key text;
  v_question_id text;
  v_checksum text;
  v_difficulty text;
  v_rng_rolls jsonb;
  v_expected_snapshot text;
  v_snapshot public.training_question_snapshots%ROWTYPE;
  v_existing public.training_question_events%ROWTYPE;
  v_event_key text;
  v_count integer := 0;
  v_slots text[] := ARRAY[]::text[];
BEGIN
  IF p_attempt_id IS NULL
     OR p_user_id IS NULL
     OR coalesce(jsonb_typeof(p_deliveries), '') <> 'array' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TRAINING_ATTEMPT_SERVE_AUDIT_INVALID';
  END IF;
  IF jsonb_array_length(p_deliveries) NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TRAINING_ATTEMPT_SERVE_AUDIT_INVALID';
  END IF;
  SELECT * INTO v_attempt FROM public.training_attempts a
  WHERE a.id = p_attempt_id FOR UPDATE;
  IF NOT FOUND OR v_attempt.user_id IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_SERVE_OWNER_MISMATCH';
  END IF;
  IF v_attempt.status <> 'open' OR v_attempt.expires_at <= now() THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_NOT_OPEN';
  END IF;

  FOR v_delivery IN SELECT value FROM jsonb_array_elements(p_deliveries)
  LOOP
    v_hand := (v_delivery ->> 'handOrdinal')::integer;
    v_decision := (v_delivery ->> 'decisionOrdinal')::integer;
    v_snapshot_key := v_delivery ->> 'snapshotKey';
    v_question_id := v_delivery ->> 'questionId';
    v_checksum := lower(v_delivery ->> 'policyChecksum');
    v_difficulty := lower(v_delivery ->> 'difficultyMode');
    v_rng_rolls := v_delivery -> 'rngRolls';
    IF coalesce(v_hand, 0) NOT BETWEEN 1 AND 100
       OR coalesce(v_decision, 0) NOT BETWEEN 1 AND 8
       OR coalesce(v_snapshot_key, '') !~ '^[0-9a-f]{64}$'
       OR nullif(btrim(v_question_id), '') IS NULL
       OR coalesce(v_checksum, '') !~ '^[0-9a-f]{64}$'
       OR v_difficulty IS DISTINCT FROM v_attempt.difficulty
       OR jsonb_typeof(v_rng_rolls) <> 'object'
       OR (SELECT count(*) FROM jsonb_object_keys(v_rng_rolls)) <> 2
       OR NOT (v_rng_rolls ?& ARRAY['low', 'high'])
       OR jsonb_typeof(v_rng_rolls -> 'low') <> 'number'
       OR jsonb_typeof(v_rng_rolls -> 'high') <> 'number'
       OR trunc((v_rng_rolls ->> 'low')::numeric) <> (v_rng_rolls ->> 'low')::numeric
       OR trunc((v_rng_rolls ->> 'high')::numeric) <> (v_rng_rolls ->> 'high')::numeric
       OR (v_rng_rolls ->> 'low')::integer NOT BETWEEN 1 AND 100
       OR (v_rng_rolls ->> 'high')::integer NOT BETWEEN 1 AND 100
       OR (v_hand::text || ':' || v_decision::text) = ANY(v_slots) THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TRAINING_ATTEMPT_SERVE_AUDIT_INVALID';
    END IF;
    v_slots := array_append(v_slots, v_hand::text || ':' || v_decision::text);

    IF EXISTS (
      SELECT 1 FROM public.training_answers answer
      WHERE answer.attempt_id = p_attempt_id
        AND answer.hand_ordinal = v_hand
        AND answer.decision_ordinal = v_decision
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_DECISION_ALREADY_ANSWERED';
    END IF;

    IF v_decision = 1 THEN
      SELECT h.snapshot_key INTO v_expected_snapshot FROM public.training_attempt_hands h
      WHERE h.attempt_id = p_attempt_id AND h.hand_ordinal = v_hand;
    ELSE
      SELECT s.snapshot_key INTO v_expected_snapshot FROM public.training_attempt_decision_slots s
      WHERE s.attempt_id = p_attempt_id
        AND s.hand_ordinal = v_hand AND s.decision_ordinal = v_decision;
    END IF;
    IF v_expected_snapshot IS NULL OR v_expected_snapshot <> v_snapshot_key THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_SERVE_SLOT_MISMATCH';
    END IF;

    SELECT * INTO v_snapshot FROM public.training_question_snapshots
    WHERE snapshot_key = v_snapshot_key;
    IF NOT FOUND
       OR v_snapshot.source_question_id <> v_question_id
       OR lower(coalesce(v_snapshot.question_data ->> 'policyChecksum', '')) <> v_checksum THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_SERVE_SNAPSHOT_MISMATCH';
    END IF;

    v_event_key := 'training-attempt:' || p_attempt_id::text
      || ':hand:' || v_hand::text || ':decision:' || v_decision::text;
    SELECT * INTO v_existing FROM public.training_question_events e
    WHERE e.event_type = 'served' AND e.event_key = v_event_key;
    IF FOUND AND (
      v_existing.question_id <> v_question_id
      OR v_existing.user_id IS DISTINCT FROM p_user_id
      OR v_existing.policy_checksum <> v_checksum
      OR v_existing.metadata ->> 'snapshotKey' IS DISTINCT FROM v_snapshot_key
      OR v_existing.metadata ->> 'attemptId' IS DISTINCT FROM p_attempt_id::text
      OR v_existing.metadata ->> 'handOrdinal' IS DISTINCT FROM v_hand::text
      OR v_existing.metadata ->> 'decisionOrdinal' IS DISTINCT FROM v_decision::text
      OR (
        v_existing.metadata ? 'difficultyMode'
        AND v_existing.metadata ->> 'difficultyMode' IS DISTINCT FROM v_difficulty
      )
      OR (
        v_existing.metadata ? 'rngRolls'
        AND v_existing.metadata -> 'rngRolls' IS DISTINCT FROM v_rng_rolls
      )
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_SERVE_EVENT_MISMATCH';
    END IF;

    -- A pre-upgrade stable receipt is already immutable. Return it without
    -- asking the later full-metadata event RPC to rewrite its shape. Such a
    -- receipt can grade ordinary decisions from attempt.difficulty, but it
    -- cannot authorize RNG grading because it has no pre-answer RNG rolls.
    IF FOUND THEN
      v_count := v_count + 1;
      CONTINUE;
    END IF;

    PERFORM public.fn_training_cache_record_event(
      'served', v_event_key, v_question_id, p_user_id, NULL,
      jsonb_build_object(
        'attemptId', p_attempt_id,
        'handOrdinal', v_hand,
        'decisionOrdinal', v_decision,
        'snapshotKey', v_snapshot_key,
        'difficultyMode', v_difficulty,
        'rngRolls', v_rng_rolls
      ),
      now(), v_checksum
    );
    v_count := v_count + 1;
  END LOOP;
  INSERT INTO public.training_delivery_authority_attestations (
    contract_version, first_attested_at, evidence_event_key, evidence_kind
  ) VALUES (
    'training-attempt-decision-authority-v1', clock_timestamp(),
    v_event_key, 'attempt_scoped_serve'
  ) ON CONFLICT (contract_version) DO NOTHING;
  RETURN jsonb_build_object('questionCount', v_count);
END;
$_$;


ALTER FUNCTION public.fn_training_attempt_record_served_batch_v1(p_attempt_id uuid, p_user_id uuid, p_deliveries jsonb) OWNER TO postgres;

--
-- Name: fn_training_authority_snapshot_immutable_v2(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_authority_snapshot_immutable_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (
    NEW.legacy_authority_snapshot IS DISTINCT FROM OLD.legacy_authority_snapshot
    OR NEW.authority_epoch IS DISTINCT FROM OLD.authority_epoch
    OR NEW.authority_version IS DISTINCT FROM OLD.authority_version
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'TRAINING_LEGACY_AUTHORITY_SNAPSHOT_IMMUTABLE';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.fn_training_authority_snapshot_immutable_v2() OWNER TO postgres;

--
-- Name: fn_training_authorize_attempt_decision_v1(uuid, uuid, integer, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_authorize_attempt_decision_v1(p_attempt_id uuid, p_user_id uuid, p_hand_ordinal integer, p_decision_ordinal integer, p_snapshot_key text, p_question_id text, p_policy_checksum text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_expected_snapshot text;
  v_snapshot public.training_question_snapshots%ROWTYPE;
  v_event public.training_question_events%ROWTYPE;
  v_event_key text;
BEGIN
  IF p_attempt_id IS NULL
     OR p_user_id IS NULL
     OR coalesce(p_hand_ordinal, 0) NOT BETWEEN 1 AND 100
     OR coalesce(p_decision_ordinal, 0) NOT BETWEEN 1 AND 8
     OR coalesce(p_snapshot_key, '') !~ '^[0-9a-f]{64}$'
     OR nullif(btrim(p_question_id), '') IS NULL
     OR coalesce(p_policy_checksum, '') !~ '^[0-9a-f]{64}$' THEN
    RETURN jsonb_build_object('authorized', false, 'code', 'TRAINING_DECISION_AUTHORITY_INPUT_INVALID');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.training_attempts a
    WHERE a.id = p_attempt_id
      AND a.user_id = p_user_id
      AND a.status = 'open'
      AND a.expires_at > now()
  ) THEN
    RETURN jsonb_build_object('authorized', false, 'code', 'TRAINING_DECISION_ATTEMPT_MISMATCH');
  END IF;

  IF p_decision_ordinal = 1 THEN
    SELECT h.snapshot_key INTO v_expected_snapshot
    FROM public.training_attempt_hands h
    WHERE h.attempt_id = p_attempt_id AND h.hand_ordinal = p_hand_ordinal;
  ELSE
    SELECT s.snapshot_key INTO v_expected_snapshot
    FROM public.training_attempt_decision_slots s
    WHERE s.attempt_id = p_attempt_id
      AND s.hand_ordinal = p_hand_ordinal
      AND s.decision_ordinal = p_decision_ordinal;
  END IF;
  IF v_expected_snapshot IS NULL OR v_expected_snapshot <> p_snapshot_key THEN
    RETURN jsonb_build_object('authorized', false, 'code', 'TRAINING_DECISION_SLOT_MISMATCH');
  END IF;

  SELECT * INTO v_snapshot FROM public.training_question_snapshots
  WHERE snapshot_key = p_snapshot_key;
  IF NOT FOUND
     OR v_snapshot.source_question_id <> p_question_id
     OR lower(coalesce(v_snapshot.question_data ->> 'policyChecksum', '')) <> lower(p_policy_checksum) THEN
    RETURN jsonb_build_object('authorized', false, 'code', 'TRAINING_DECISION_SNAPSHOT_MISMATCH');
  END IF;

  v_event_key := 'training-attempt:' || p_attempt_id::text
    || ':hand:' || p_hand_ordinal::text || ':decision:' || p_decision_ordinal::text;
  SELECT * INTO v_event FROM public.training_question_events e
  WHERE e.event_type = 'served' AND e.event_key = v_event_key;
  IF NOT FOUND
     OR v_event.question_id <> p_question_id
     OR v_event.user_id IS DISTINCT FROM p_user_id
     OR v_event.policy_checksum <> lower(p_policy_checksum)
     OR v_event.metadata ->> 'snapshotKey' IS DISTINCT FROM p_snapshot_key
     OR v_event.metadata ->> 'attemptId' IS DISTINCT FROM p_attempt_id::text
     OR v_event.metadata ->> 'handOrdinal' IS DISTINCT FROM p_hand_ordinal::text
     OR v_event.metadata ->> 'decisionOrdinal' IS DISTINCT FROM p_decision_ordinal::text THEN
    RETURN jsonb_build_object('authorized', false, 'code', 'TRAINING_DECISION_NOT_SERVED');
  END IF;
  RETURN jsonb_build_object('authorized', true, 'eventKey', v_event_key);
END;
$_$;


ALTER FUNCTION public.fn_training_authorize_attempt_decision_v1(p_attempt_id uuid, p_user_id uuid, p_hand_ordinal integer, p_decision_ordinal integer, p_snapshot_key text, p_question_id text, p_policy_checksum text) OWNER TO postgres;

--
-- Name: fn_training_cache_attested_classification(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_attested_classification(p_question_kind text, p_question jsonb, p_policy jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT CASE
        WHEN lower(coalesce(p_policy ->> 'kind', '')) = 'heuristic'
         AND (
            upper(coalesce(p_question ->> 'source', ''))
                IN ('MODEL_DISTILLED', 'DISTILLED_MODEL')
            OR upper(coalesce(p_question ->> 'dataQuality', '')) = 'MODEL_DISTILLED'
            OR upper(coalesce(p_question ->> 'sourceClassification', ''))
                = 'MODEL_DISTILLED'
         ) THEN 'MODEL_DISTILLED'
        WHEN upper(coalesce(p_policy ->> 'qualitySeal', '')) IN (
            'SOLVER_EXACT', 'SOLVER_AGGREGATED', 'SOLVER_DERIVED_RESPONSE',
            'CHART_AUDITED', 'CURATED', 'HEURISTIC', 'LEGACY_UNVERIFIED'
        ) THEN upper(p_policy ->> 'qualitySeal')
        WHEN upper(coalesce(p_question ->> 'source', ''))
                IN ('MODEL_DISTILLED', 'DISTILLED_MODEL')
          OR upper(coalesce(p_question ->> 'dataQuality', '')) = 'MODEL_DISTILLED'
          OR upper(coalesce(p_question ->> 'sourceClassification', ''))
                = 'MODEL_DISTILLED' THEN 'MODEL_DISTILLED'
        WHEN upper(coalesce(p_question ->> 'dataQuality', '')) = 'SIMULATED'
          OR upper(coalesce(p_question ->> 'source', ''))
                IN ('POSTFLOP_ENGINE', 'HEURISTIC')
          OR upper(coalesce(p_question ->> 'sourceClassification', ''))
                = 'HEURISTIC' THEN 'HEURISTIC'
        WHEN upper(coalesce(p_question ->> 'source', '')) ~ '(CURATED|SCENARIO|PSYCHOLOGY)'
          OR upper(coalesce(p_question ->> 'type', '')) = 'SCENARIO'
          OR (
              upper(coalesce(p_question_kind, '')) = 'SCENARIO'
              AND upper(coalesce(p_question ->> 'source', ''))
                    NOT IN ('DETERMINISTIC_SOLVER', 'PIO_DATABASE', 'PIO')
          )
          OR upper(coalesce(p_question ->> 'sourceClassification', ''))
                = 'CURATED' THEN 'CURATED'
        ELSE 'LEGACY_UNVERIFIED'
    END
$$;


ALTER FUNCTION public.fn_training_cache_attested_classification(p_question_kind text, p_question jsonb, p_policy jsonb) OWNER TO postgres;

--
-- Name: fn_training_cache_derive_classification(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_derive_classification(p_question_kind text, p_question jsonb, p_policy jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_source text := upper(coalesce(p_question ->> 'source', ''));
    v_type text := upper(coalesce(p_question ->> 'type', ''));
    v_quality text := upper(coalesce(p_question ->> 'dataQuality', ''));
    v_declared text := upper(coalesce(p_question ->> 'sourceClassification', ''));
    v_seal text := upper(coalesce(p_policy ->> 'qualitySeal', ''));
    v_kind text := lower(coalesce(p_policy ->> 'kind', ''));
    v_policy_valid boolean := public.fn_training_cache_policy_seal_is_valid(p_policy);
BEGIN
    IF v_policy_valid THEN
        IF v_kind = 'heuristic'
           AND (v_source IN ('MODEL_DISTILLED', 'DISTILLED_MODEL')
                OR v_quality = 'MODEL_DISTILLED'
                OR v_declared = 'MODEL_DISTILLED') THEN
            RETURN 'MODEL_DISTILLED';
        END IF;
        IF v_seal IN (
            'SOLVER_EXACT', 'SOLVER_AGGREGATED', 'SOLVER_DERIVED_RESPONSE',
            'CHART_AUDITED', 'CURATED', 'HEURISTIC', 'LEGACY_UNVERIFIED'
        ) THEN
            RETURN v_seal;
        END IF;
    END IF;

    IF v_source IN ('MODEL_DISTILLED', 'DISTILLED_MODEL')
       OR v_quality = 'MODEL_DISTILLED'
       OR v_declared = 'MODEL_DISTILLED' THEN
        RETURN 'MODEL_DISTILLED';
    END IF;
    IF v_quality = 'SIMULATED'
       OR v_source IN ('POSTFLOP_ENGINE', 'HEURISTIC')
       OR v_declared = 'HEURISTIC' THEN
        RETURN 'HEURISTIC';
    END IF;
    -- A CHART label plus percentages is not an audit receipt. CHART_AUDITED
    -- is reachable only through a valid canonical chart policy above. Raw
    -- LOCAL_SOLVER_RANGES rows are restored as CURATED by the backfill because
    -- that archive has no immutable chart id to prove which source row it used.
    IF v_source ~ '(CURATED|SCENARIO|PSYCHOLOGY)'
       OR v_type = 'SCENARIO'
       OR (upper(coalesce(p_question_kind, '')) = 'SCENARIO'
           AND v_source NOT IN ('DETERMINISTIC_SOLVER', 'PIO_DATABASE', 'PIO'))
       OR v_declared = 'CURATED' THEN
        RETURN 'CURATED';
    END IF;
    RETURN 'LEGACY_UNVERIFIED';
END;
$$;


ALTER FUNCTION public.fn_training_cache_derive_classification(p_question_kind text, p_question jsonb, p_policy jsonb) OWNER TO postgres;

--
-- Name: fn_training_cache_grade(jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_grade(p_policy jsonb, p_answer_id text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_answer text := lower(nullif(btrim(p_answer_id), ''));
    v_selected numeric;
    v_optimal numeric;
    v_optimal_action text;
    v_nonzero integer;
    v_classification text;
    v_is_correct boolean;
    v_solver_verified boolean;
    v_selected_ev numeric;
    v_optimal_ev numeric;
    v_ev_measured boolean := false;
    v_ev_loss numeric;
BEGIN
    IF NOT public.fn_training_cache_policy_seal_is_valid(p_policy)
       OR v_answer IS NULL
       OR jsonb_typeof(p_policy -> 'distribution' -> v_answer) <> 'number' THEN
        RETURN jsonb_build_object('valid', false);
    END IF;

    v_selected := (p_policy -> 'distribution' ->> v_answer)::numeric;
    SELECT
        (entry.value #>> '{}')::numeric,
        entry.key
    INTO v_optimal, v_optimal_action
    FROM jsonb_each(p_policy -> 'distribution') AS entry(key, value)
    ORDER BY (entry.value #>> '{}')::numeric DESC, entry.key ASC
    LIMIT 1;
    SELECT count(*)::integer INTO v_nonzero
    FROM jsonb_each(p_policy -> 'distribution') AS entry(key, value)
    WHERE (entry.value #>> '{}')::numeric > 0;

    v_classification := CASE
        WHEN v_selected >= v_optimal - 0.000000001 THEN 'best'
        WHEN v_selected >= 0.20 THEN 'best'
        WHEN v_selected >= 0.05 THEN 'correct'
        WHEN v_selected >= 0.01 THEN 'inaccuracy'
        WHEN v_optimal >= 0.80 OR v_nonzero <= 1 THEN 'blunder'
        ELSE 'wrong'
    END;
    v_is_correct := v_classification IN ('best', 'correct');
    v_solver_verified := upper(p_policy ->> 'qualitySeal') IN (
        'SOLVER_EXACT', 'SOLVER_AGGREGATED',
        'SOLVER_DERIVED_RESPONSE', 'CHART_AUDITED'
    );

    IF p_policy #>> '{chipEv,measuredByAction}' = 'true'
       AND NOT EXISTS (
           SELECT 1
           FROM jsonb_object_keys(p_policy -> 'distribution') AS action_id(id)
           WHERE jsonb_typeof(p_policy #> ARRAY['chipEv', 'byAction', action_id.id]) <> 'number'
       ) THEN
        v_selected_ev := (p_policy #>> ARRAY['chipEv', 'byAction', v_answer])::numeric;
        SELECT max((entry.value #>> '{}')::numeric) INTO v_optimal_ev
        FROM jsonb_each(p_policy #> '{chipEv,byAction}') AS entry(key, value);
        v_ev_measured := v_selected_ev IS NOT NULL AND v_optimal_ev IS NOT NULL;
        IF v_ev_measured THEN
            v_ev_loss := greatest(0, v_optimal_ev - v_selected_ev);
        END IF;
    END IF;

    RETURN jsonb_build_object(
        'valid', true,
        'classification', v_classification,
        'isCorrect', v_is_correct,
        'solverVerified', v_solver_verified,
        'selectedFrequency', round(v_selected * 100, 2),
        'optimalFrequency', round(v_optimal * 100, 2),
        'optimalAction', v_optimal_action,
        'evLossMeasured', v_ev_measured,
        'evLoss', CASE WHEN v_ev_measured THEN round(v_ev_loss, 3) ELSE NULL END,
        'policyVersion', p_policy ->> 'policyVersion',
        'solverSource', p_policy #>> '{sourceArtifact,system}',
        'sourceChecksum', p_policy #>> '{sourceArtifact,sourceArtifactChecksum}'
    );
END;
$$;


ALTER FUNCTION public.fn_training_cache_grade(p_policy jsonb, p_answer_id text) OWNER TO postgres;

--
-- Name: fn_training_cache_has_distribution(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_has_distribution(p_question jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_entry record;
BEGIN
    IF jsonb_typeof(p_question) <> 'object' THEN RETURN false; END IF;
    IF jsonb_typeof(p_question -> 'gtoFrequencies') = 'object' THEN
        FOR v_entry IN SELECT * FROM jsonb_each(p_question -> 'gtoFrequencies') LOOP
            IF jsonb_typeof(v_entry.value) = 'number'
               AND (v_entry.value #>> '{}')::numeric > 0 THEN
                RETURN true;
            END IF;
        END LOOP;
    END IF;
    IF jsonb_typeof(p_question -> 'options') = 'array' THEN
        FOR v_entry IN SELECT value FROM jsonb_array_elements(p_question -> 'options') LOOP
            IF jsonb_typeof(v_entry.value -> 'frequency') = 'number'
               AND (v_entry.value ->> 'frequency')::numeric > 0 THEN
                RETURN true;
            END IF;
        END LOOP;
    END IF;
    RETURN false;
END;
$$;


ALTER FUNCTION public.fn_training_cache_has_distribution(p_question jsonb) OWNER TO postgres;

--
-- Name: fn_training_cache_jsonb_has_exact_keys(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_jsonb_has_exact_keys(p_value jsonb, p_keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT jsonb_typeof(p_value) = 'object'
       AND NOT EXISTS (
            SELECT 1 FROM unnest(p_keys) AS required(key)
            WHERE NOT p_value ? required.key
       )
       AND (SELECT count(*) FROM jsonb_object_keys(p_value)) = cardinality(p_keys)
$$;


ALTER FUNCTION public.fn_training_cache_jsonb_has_exact_keys(p_value jsonb, p_keys text[]) OWNER TO postgres;

--
-- Name: fn_training_cache_mark_contract_dirty(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_mark_contract_dirty() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    NEW.contract_stamped_at := clock_timestamp();
    NEW.contract_audited_at := NULL;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_training_cache_mark_contract_dirty() OWNER TO postgres;

--
-- Name: fn_training_cache_policy_seal_is_valid(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_policy_seal_is_valid(p_policy jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_action jsonb;
    v_distribution record;
    v_action_ids text[] := ARRAY[]::text[];
    v_action_id text;
    v_frequency numeric;
    v_distribution_frequency numeric;
    v_sum numeric := 0;
    v_distribution_count integer := 0;
    v_expected_board_count integer;
    v_expected_holding_count integer;
BEGIN
    IF NOT public.fn_training_cache_policy_shape_is_valid(p_policy)
       OR jsonb_typeof(p_policy) <> 'object'
       OR p_policy ->> 'contractVersion' <> 'smarter-poker.solver-policy.v1'
       OR nullif(p_policy ->> 'policyVersion', '') IS NULL
       OR jsonb_typeof(p_policy -> 'key') <> 'object'
       OR jsonb_typeof(p_policy -> 'node') <> 'object'
       OR jsonb_typeof(p_policy -> 'actions') <> 'array'
       OR jsonb_typeof(p_policy -> 'distribution') <> 'object'
       OR jsonb_typeof(p_policy -> 'legalSizes') <> 'array'
       OR jsonb_typeof(p_policy -> 'chipEv') <> 'object'
       OR jsonb_typeof(p_policy -> 'tournamentUtilityEv') <> 'object'
       OR jsonb_typeof(p_policy -> 'sourceArtifact') <> 'object'
       OR jsonb_typeof(p_policy -> 'validDomain') <> 'object'
       OR jsonb_typeof(p_policy -> 'confidence') <> 'object' THEN
        RETURN false;
    END IF;
    IF jsonb_array_length(p_policy -> 'actions') = 0 THEN RETURN false; END IF;
    IF NOT (CASE p_policy ->> 'kind'
        WHEN 'exact' THEN p_policy ->> 'qualitySeal' = 'SOLVER_EXACT'
        WHEN 'aggregated' THEN p_policy ->> 'qualitySeal' = 'SOLVER_AGGREGATED'
        WHEN 'derived' THEN p_policy ->> 'qualitySeal'
            IN ('SOLVER_DERIVED_RESPONSE', 'LEGACY_UNVERIFIED')
        WHEN 'chart' THEN p_policy ->> 'qualitySeal' = 'CHART_AUDITED'
        WHEN 'curated' THEN p_policy ->> 'qualitySeal' = 'CURATED'
        WHEN 'heuristic' THEN p_policy ->> 'qualitySeal' = 'HEURISTIC'
        ELSE false
    END) THEN
        RETURN false;
    END IF;

    FOR v_action IN SELECT value FROM jsonb_array_elements(p_policy -> 'actions') LOOP
        v_action_id := nullif(btrim(v_action ->> 'id'), '');
        IF jsonb_typeof(v_action) <> 'object'
           OR v_action_id IS NULL
           OR v_action_id = ANY(v_action_ids)
           OR jsonb_typeof(v_action -> 'frequency') <> 'number'
           OR jsonb_typeof(v_action -> 'legal') <> 'boolean'
           OR jsonb_typeof(v_action -> 'size') <> 'object' THEN
            RETURN false;
        END IF;
        v_frequency := (v_action ->> 'frequency')::numeric;
        IF v_frequency < 0 OR v_frequency > 1 THEN RETURN false; END IF;
        IF jsonb_typeof(p_policy -> 'distribution' -> v_action_id) <> 'number' THEN
            RETURN false;
        END IF;
        v_distribution_frequency := (p_policy -> 'distribution' ->> v_action_id)::numeric;
        IF abs(v_distribution_frequency - v_frequency) > 0.000000001 THEN
            RETURN false;
        END IF;
        v_action_ids := array_append(v_action_ids, v_action_id);
        v_sum := v_sum + v_frequency;
    END LOOP;

    FOR v_distribution IN SELECT * FROM jsonb_each(p_policy -> 'distribution') LOOP
        IF NOT (v_distribution.key = ANY(v_action_ids))
           OR jsonb_typeof(v_distribution.value) <> 'number' THEN
            RETURN false;
        END IF;
        v_distribution_count := v_distribution_count + 1;
    END LOOP;
    IF v_distribution_count <> coalesce(array_length(v_action_ids, 1), 0)
       OR abs(v_sum - 1) > 0.000001 THEN
        RETURN false;
    END IF;

    IF p_policy ->> 'kind' = 'exact' THEN
        v_expected_board_count := CASE p_policy #>> '{key,street}'
            WHEN 'preflop' THEN 0 WHEN 'flop' THEN 3 WHEN 'turn' THEN 4
            WHEN 'river' THEN 5 ELSE NULL END;
        v_expected_holding_count := CASE p_policy #>> '{key,variant}'
            WHEN 'nlh' THEN 2 WHEN 'short_deck' THEN 2 WHEN 'pineapple' THEN 3
            WHEN 'plo4' THEN 4 WHEN 'plo5' THEN 5 WHEN 'plo6' THEN 6
            WHEN 'plo8' THEN 4 ELSE NULL END;
        IF v_expected_board_count IS NULL OR v_expected_holding_count IS NULL
           OR p_policy #>> '{sourceArtifact,provenanceComplete}' <> 'true'
           OR lower(coalesce(p_policy #>> '{sourceArtifact,system}', '')) IN ('', 'none')
           OR nullif(p_policy #>> '{sourceArtifact,artifactId}', '') IS NULL
           OR nullif(p_policy #>> '{sourceArtifact,scenarioHash}', '') IS NULL
           OR nullif(p_policy #>> '{sourceArtifact,solverVersion}', '') IS NULL
           OR coalesce(p_policy #>> '{sourceArtifact,solverBinaryChecksum}', '')
                !~ '^[0-9a-fA-F]{64}$'
           OR nullif(p_policy #>> '{sourceArtifact,machineId}', '') IS NULL
           OR coalesce(p_policy #>> '{sourceArtifact,pipelineCommit}', '')
                !~ '^[0-9a-fA-F]{40}$'
           OR nullif(p_policy #>> '{sourceArtifact,manifestVersion}', '') IS NULL
           OR coalesce(p_policy #>> '{sourceArtifact,manifestChecksum}', '')
                !~ '^[0-9a-fA-F]{64}$'
           OR coalesce(p_policy #>> '{sourceArtifact,sourceArtifactChecksum}', '')
                !~ '^[0-9a-fA-F]{64}$'
           OR lower(coalesce(p_policy #>> '{sourceArtifact,qualityStatus}', '')) <> 'validated'
           OR public.fn_training_cache_try_timestamptz(
                p_policy #>> '{sourceArtifact,auditedAt}'
              ) IS NULL
           OR p_policy #>> '{validDomain,completeKey}' <> 'true'
           OR p_policy -> 'validDomain' -> 'exactMatchDimensions' <> '["all"]'::jsonb
           OR p_policy -> 'validDomain' -> 'approximatedDimensions' <> '[]'::jsonb
           OR p_policy -> 'validDomain' -> 'exclusions' <> '[]'::jsonb
           OR coalesce(p_policy -> 'fallbackReason', '"missing"'::jsonb) <> 'null'::jsonb
           OR p_policy #>> '{key,contractVersion}' <> 'smarter-poker.solver-policy.v1'
           OR coalesce(p_policy #>> '{key,bettingStructure}', 'unknown') = 'unknown'
           OR coalesce(p_policy #>> '{key,tableSize}', '') !~ '^[2-9][0-9]*$'
           OR coalesce(p_policy #>> '{key,positions,hero}', 'UNKNOWN') = 'UNKNOWN'
           OR coalesce(p_policy #>> '{key,positions,button}', 'UNKNOWN') = 'UNKNOWN'
           OR coalesce(p_policy #>> '{key,positions,smallBlind}', 'UNKNOWN') = 'UNKNOWN'
           OR coalesce(p_policy #>> '{key,positions,bigBlind}', 'UNKNOWN') = 'UNKNOWN'
           OR jsonb_typeof(p_policy #> '{key,positions,villains}') <> 'array'
           OR jsonb_array_length(p_policy #> '{key,positions,villains}') < 1
           OR jsonb_typeof(p_policy #> '{key,stackVector}') <> 'array'
           OR jsonb_array_length(p_policy #> '{key,stackVector}')
                <> (p_policy #>> '{key,tableSize}')::integer
           OR p_policy #>> '{key,blinds,complete}' <> 'true'
           OR jsonb_typeof(p_policy #> '{key,blinds,bigBlind}') <> 'number'
           OR (p_policy #>> '{key,blinds,bigBlind}')::numeric <= 0
           OR p_policy #>> '{key,rake,complete}' <> 'true'
           OR p_policy #>> '{key,tournamentUtility,complete}' <> 'true'
           OR jsonb_typeof(p_policy #> '{key,board}') <> 'array'
           OR jsonb_array_length(p_policy #> '{key,board}') <> v_expected_board_count
           OR jsonb_typeof(p_policy #> '{key,holding}') <> 'array'
           OR jsonb_array_length(p_policy #> '{key,holding}') <> v_expected_holding_count
           OR p_policy #>> '{key,publicActionHistory,complete}' <> 'true'
           OR (v_expected_board_count > 0
               AND jsonb_array_length(p_policy #> '{key,publicActionHistory,actions}') = 0)
           OR jsonb_typeof(p_policy #> '{key,legalActions}') <> 'array'
           OR jsonb_array_length(p_policy #> '{key,legalActions}') = 0
           OR p_policy #>> '{key,sidePotEligibility,complete}' <> 'true'
           OR jsonb_typeof(p_policy #> '{key,payouts}') <> 'array'
           OR jsonb_typeof(p_policy #> '{key,bounties}') <> 'array'
           OR (p_policy #>> '{key,tournamentUtility,mode}' <> 'cash'
               AND jsonb_array_length(p_policy #> '{key,payouts}') = 0)
           OR EXISTS (
                SELECT 1
                FROM (
                    SELECT value #>> '{}' AS card
                    FROM jsonb_array_elements(p_policy #> '{key,board}')
                    UNION ALL
                    SELECT value #>> '{}'
                    FROM jsonb_array_elements(p_policy #> '{key,holding}')
                ) AS cards
                WHERE card !~ '^[2-9TJQKA][cdhs]$'
           )
           OR (
                SELECT count(*) <> count(DISTINCT card)
                FROM (
                    SELECT value #>> '{}' AS card
                    FROM jsonb_array_elements(p_policy #> '{key,board}')
                    UNION ALL
                    SELECT value #>> '{}'
                    FROM jsonb_array_elements(p_policy #> '{key,holding}')
                ) AS cards
           ) THEN
            RETURN false;
        END IF;

        FOR v_action IN SELECT value FROM jsonb_array_elements(p_policy -> 'actions') LOOP
            IF v_action ->> 'legal' <> 'true'
               OR nullif(v_action ->> 'family', '') IS NULL
               OR jsonb_typeof(v_action -> 'size') <> 'object'
               OR NOT EXISTS (
                    SELECT 1
                    FROM jsonb_array_elements(p_policy #> '{key,legalActions}') AS legal(value)
                    WHERE legal.value ->> 'action' = v_action ->> 'family'
                       OR ((v_action ->> 'family') = 'all_in'
                           AND legal.value ->> 'allIn' = 'true')
               ) THEN
                RETURN false;
            END IF;
            IF v_action ->> 'family' IN ('bet', 'raise', 'all_in') THEN
                IF v_action #>> '{size,exact}' <> 'true'
                   OR jsonb_typeof(v_action #> '{size,chips}') <> 'number'
                   OR jsonb_typeof(v_action #> '{size,bigBlinds}') <> 'number'
                   OR jsonb_typeof(v_action #> '{size,potFraction}') <> 'number'
                   OR (v_action #>> '{size,chips}')::numeric < 0
                   OR (v_action #>> '{size,bigBlinds}')::numeric < 0
                   OR (v_action #>> '{size,potFraction}')::numeric < 0
                   OR abs(
                        (v_action #>> '{size,chips}')::numeric
                        / (p_policy #>> '{key,blinds,bigBlind}')::numeric
                        - (v_action #>> '{size,bigBlinds}')::numeric
                      ) > 0.000001
                   OR jsonb_typeof(p_policy #> '{node,potBb}') <> 'number'
                   OR (p_policy #>> '{node,potBb}')::numeric <= 0
                   OR abs(
                        (v_action #>> '{size,bigBlinds}')::numeric
                        / (p_policy #>> '{node,potBb}')::numeric
                        - (v_action #>> '{size,potFraction}')::numeric
                      ) > 0.000001 THEN
                    RETURN false;
                END IF;
            ELSIF v_action ->> 'family' IN ('fold', 'check', 'call') THEN
                IF v_action #>> '{size,unit}' <> 'none'
                   OR v_action #>> '{size,exact}' <> 'false'
                   OR v_action #> '{size,chips}' <> 'null'::jsonb
                   OR v_action #> '{size,bigBlinds}' <> 'null'::jsonb
                   OR v_action #> '{size,potFraction}' <> 'null'::jsonb THEN
                    RETURN false;
                END IF;
            ELSE
                RETURN false;
            END IF;
        END LOOP;
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION public.fn_training_cache_policy_seal_is_valid(p_policy jsonb) OWNER TO postgres;

--
-- Name: fn_training_cache_policy_shape_is_valid(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_policy_shape_is_valid(p_policy jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_item jsonb;
    v_action jsonb;
    v_action_ids text[] := ARRAY[]::text[];
    v_action_id text;
    v_distribution record;
    v_sum numeric := 0;
    v_previous_sequence integer := -1;
    v_score numeric;
    v_expected_confidence text;
    v_mix record;
    v_mix_sum numeric;
    v_expected_board_count integer;
    v_expected_holding_count integer;
    v_key_complete boolean;
BEGIN
    IF NOT public.fn_training_cache_jsonb_has_exact_keys(p_policy, ARRAY[
            'contractVersion', 'policyVersion', 'key', 'kind', 'node',
            'actions', 'distribution', 'legalSizes', 'chipEv',
            'tournamentUtilityEv', 'sourceArtifact', 'qualitySeal',
            'validDomain', 'confidence', 'fallbackReason', 'rangeDistribution'
       ])
       OR p_policy ->> 'contractVersion' <> 'smarter-poker.solver-policy.v1'
       OR jsonb_typeof(p_policy -> 'policyVersion') <> 'string'
       OR nullif(p_policy ->> 'policyVersion', '') IS NULL
       OR jsonb_typeof(p_policy -> 'kind') <> 'string'
       OR jsonb_typeof(p_policy -> 'qualitySeal') <> 'string'
       OR jsonb_typeof(p_policy -> 'actions') <> 'array'
       OR jsonb_typeof(p_policy -> 'distribution') <> 'object'
       OR jsonb_typeof(p_policy -> 'legalSizes') <> 'array'
       OR jsonb_typeof(p_policy -> 'fallbackReason') NOT IN ('null', 'string')
       OR jsonb_typeof(p_policy -> 'rangeDistribution') NOT IN ('null', 'object') THEN
        RETURN false;
    END IF;

    IF NOT public.fn_training_cache_jsonb_has_exact_keys(p_policy -> 'node', ARRAY[
            'semantics', 'sourceNode', 'actor', 'potBb', 'facingBetBb'
       ])
       OR coalesce(p_policy #>> '{node,semantics}', '') NOT IN (
            'check_or_bet', 'facing_wager', 'preflop_unopened',
            'preflop_facing_wager', 'terminal', 'unknown'
       )
       OR jsonb_typeof(p_policy #> '{node,sourceNode}') NOT IN ('null', 'string')
       OR jsonb_typeof(p_policy #> '{node,actor}') <> 'string'
       OR jsonb_typeof(p_policy #> '{node,potBb}') NOT IN ('null', 'number')
       OR jsonb_typeof(p_policy #> '{node,facingBetBb}') NOT IN ('null', 'number')
       OR (jsonb_typeof(p_policy #> '{node,potBb}') = 'number'
           AND (p_policy #>> '{node,potBb}')::numeric < 0)
       OR (jsonb_typeof(p_policy #> '{node,facingBetBb}') = 'number'
           AND (p_policy #>> '{node,facingBetBb}')::numeric < 0) THEN
        RETURN false;
    END IF;

    IF NOT public.fn_training_cache_jsonb_has_exact_keys(
            p_policy -> 'sourceArtifact', ARRAY[
              'system', 'artifactId', 'scenarioHash', 'solverVersion',
              'solverBinaryChecksum', 'machineId', 'pipelineCommit',
              'manifestVersion', 'manifestChecksum', 'sourceArtifactChecksum',
              'qualityStatus', 'auditedAt', 'provenanceComplete'
            ]
       )
       OR jsonb_typeof(p_policy #> '{sourceArtifact,system}') <> 'string'
       OR EXISTS (
            SELECT 1
            FROM unnest(ARRAY[
              'artifactId', 'scenarioHash', 'solverVersion',
              'solverBinaryChecksum', 'machineId', 'pipelineCommit',
              'manifestVersion', 'manifestChecksum', 'sourceArtifactChecksum',
              'qualityStatus', 'auditedAt'
            ]) AS field(name)
            WHERE jsonb_typeof(p_policy -> 'sourceArtifact' -> field.name)
                NOT IN ('null', 'string')
       )
       OR jsonb_typeof(p_policy #> '{sourceArtifact,provenanceComplete}') <> 'boolean' THEN
        RETURN false;
    END IF;

    IF NOT public.fn_training_cache_jsonb_has_exact_keys(
            p_policy -> 'validDomain', ARRAY[
              'completeKey', 'missingKeyDimensions', 'exactMatchDimensions',
              'approximatedDimensions', 'exclusions'
            ]
       )
       OR jsonb_typeof(p_policy #> '{validDomain,completeKey}') <> 'boolean'
       OR EXISTS (
            SELECT 1
            FROM unnest(ARRAY[
              'missingKeyDimensions', 'exactMatchDimensions',
              'approximatedDimensions', 'exclusions'
            ]) AS field(name)
            WHERE jsonb_typeof(p_policy -> 'validDomain' -> field.name) <> 'array'
               OR EXISTS (
                    SELECT 1
                    FROM jsonb_array_elements(
                        p_policy -> 'validDomain' -> field.name
                    ) AS element(value)
                    WHERE jsonb_typeof(element.value) <> 'string'
               )
       ) THEN
        RETURN false;
    END IF;

    IF NOT public.fn_training_cache_jsonb_has_exact_keys(
            p_policy -> 'confidence', ARRAY['score', 'level']
       )
       OR jsonb_typeof(p_policy #> '{confidence,score}') <> 'number'
       OR jsonb_typeof(p_policy #> '{confidence,level}') <> 'string' THEN
        RETURN false;
    END IF;
    v_score := (p_policy #>> '{confidence,score}')::numeric;
    v_expected_confidence := CASE
        WHEN v_score >= 0.9 THEN 'high'
        WHEN v_score >= 0.6 THEN 'medium'
        WHEN v_score > 0 THEN 'low'
        ELSE 'none'
    END;
    IF v_score < 0 OR v_score > 1
       OR p_policy #>> '{confidence,level}' <> v_expected_confidence THEN
        RETURN false;
    END IF;

    IF NOT public.fn_training_cache_jsonb_has_exact_keys(p_policy -> 'key', ARRAY[
            'contractVersion', 'variant', 'bettingStructure', 'tableSize',
            'positions', 'stackVector', 'blinds', 'rake',
            'tournamentUtility', 'payouts', 'bounties', 'street', 'board',
            'holding', 'publicActionHistory', 'legalActions',
            'sidePotEligibility'
       ])
       OR p_policy #>> '{key,contractVersion}' <> 'smarter-poker.solver-policy.v1'
       OR jsonb_typeof(p_policy #> '{key,variant}') <> 'string'
       OR jsonb_typeof(p_policy #> '{key,bettingStructure}') <> 'string'
       OR jsonb_typeof(p_policy #> '{key,tableSize}') NOT IN ('null', 'number')
       OR (jsonb_typeof(p_policy #> '{key,tableSize}') = 'number' AND (
            (p_policy #>> '{key,tableSize}')::numeric < 2
            OR trunc((p_policy #>> '{key,tableSize}')::numeric)
                <> (p_policy #>> '{key,tableSize}')::numeric
       ))
       OR coalesce(p_policy #>> '{key,street}', '') NOT IN (
            'preflop', 'flop', 'turn', 'river'
       )
       OR jsonb_typeof(p_policy #> '{key,board}') <> 'array'
       OR jsonb_typeof(p_policy #> '{key,holding}') <> 'array'
       OR jsonb_typeof(p_policy #> '{key,stackVector}') <> 'array'
       OR jsonb_typeof(p_policy #> '{key,payouts}') <> 'array'
       OR jsonb_typeof(p_policy #> '{key,bounties}') <> 'array'
       OR jsonb_typeof(p_policy #> '{key,legalActions}') <> 'array' THEN
        RETURN false;
    END IF;

    IF NOT public.fn_training_cache_jsonb_has_exact_keys(
            p_policy #> '{key,positions}',
            ARRAY['hero', 'villains', 'button', 'smallBlind', 'bigBlind']
       )
       OR jsonb_typeof(p_policy #> '{key,positions,hero}') <> 'string'
       OR jsonb_typeof(p_policy #> '{key,positions,villains}') <> 'array'
       OR jsonb_typeof(p_policy #> '{key,positions,button}') <> 'string'
       OR jsonb_typeof(p_policy #> '{key,positions,smallBlind}') <> 'string'
       OR jsonb_typeof(p_policy #> '{key,positions,bigBlind}') <> 'string'
       OR EXISTS (
            SELECT 1 FROM jsonb_array_elements(
                p_policy #> '{key,positions,villains}'
            ) AS element(value)
            WHERE jsonb_typeof(element.value) <> 'string'
       ) THEN
        RETURN false;
    END IF;

    IF NOT public.fn_training_cache_jsonb_has_exact_keys(
            p_policy #> '{key,blinds}', ARRAY[
              'smallBlind', 'bigBlind', 'ante', 'bigBlindAnte', 'straddles',
              'complete'
            ]
       )
       OR jsonb_typeof(p_policy #> '{key,blinds,smallBlind}') NOT IN ('null', 'number')
       OR jsonb_typeof(p_policy #> '{key,blinds,bigBlind}') NOT IN ('null', 'number')
       OR jsonb_typeof(p_policy #> '{key,blinds,ante}') <> 'number'
       OR jsonb_typeof(p_policy #> '{key,blinds,bigBlindAnte}') <> 'number'
       OR jsonb_typeof(p_policy #> '{key,blinds,straddles}') <> 'array'
       OR jsonb_typeof(p_policy #> '{key,blinds,complete}') <> 'boolean'
       OR (p_policy #>> '{key,blinds,ante}')::numeric < 0
       OR (p_policy #>> '{key,blinds,bigBlindAnte}')::numeric < 0 THEN
        RETURN false;
    END IF;
    FOR v_item IN SELECT value FROM jsonb_array_elements(p_policy #> '{key,blinds,straddles}') LOOP
        IF NOT public.fn_training_cache_jsonb_has_exact_keys(v_item, ARRAY['seat', 'amount'])
           OR jsonb_typeof(v_item -> 'seat') <> 'number'
           OR trunc((v_item ->> 'seat')::numeric) <> (v_item ->> 'seat')::numeric
           OR (v_item ->> 'seat')::numeric < 0
           OR jsonb_typeof(v_item -> 'amount') NOT IN ('null', 'number') THEN
            RETURN false;
        END IF;
    END LOOP;

    IF NOT public.fn_training_cache_jsonb_has_exact_keys(
            p_policy #> '{key,rake}',
            ARRAY['percent', 'capChips', 'capBb', 'noFlopNoDrop', 'complete']
       )
       OR jsonb_typeof(p_policy #> '{key,rake,percent}') NOT IN ('null', 'number')
       OR jsonb_typeof(p_policy #> '{key,rake,capChips}') NOT IN ('null', 'number')
       OR jsonb_typeof(p_policy #> '{key,rake,capBb}') NOT IN ('null', 'number')
       OR jsonb_typeof(p_policy #> '{key,rake,noFlopNoDrop}') <> 'boolean'
       OR jsonb_typeof(p_policy #> '{key,rake,complete}') <> 'boolean' THEN
        RETURN false;
    END IF;

    IF NOT public.fn_training_cache_jsonb_has_exact_keys(
            p_policy #> '{key,tournamentUtility}', ARRAY[
              'mode', 'model', 'playersRemaining', 'entrants', 'handForHand',
              'complete'
            ]
       )
       OR jsonb_typeof(p_policy #> '{key,tournamentUtility,mode}') <> 'string'
       OR jsonb_typeof(p_policy #> '{key,tournamentUtility,model}') NOT IN ('null', 'string')
       OR jsonb_typeof(p_policy #> '{key,tournamentUtility,playersRemaining}') NOT IN ('null', 'number')
       OR jsonb_typeof(p_policy #> '{key,tournamentUtility,entrants}') NOT IN ('null', 'number')
       OR jsonb_typeof(p_policy #> '{key,tournamentUtility,handForHand}') <> 'boolean'
       OR jsonb_typeof(p_policy #> '{key,tournamentUtility,complete}') <> 'boolean' THEN
        RETURN false;
    END IF;

    IF NOT public.fn_training_cache_jsonb_has_exact_keys(
            p_policy #> '{key,publicActionHistory}', ARRAY['complete', 'actions']
       )
       OR jsonb_typeof(p_policy #> '{key,publicActionHistory,complete}') <> 'boolean'
       OR jsonb_typeof(p_policy #> '{key,publicActionHistory,actions}') <> 'array'
       OR NOT public.fn_training_cache_jsonb_has_exact_keys(
            p_policy #> '{key,sidePotEligibility}', ARRAY['complete', 'pots']
       )
       OR jsonb_typeof(p_policy #> '{key,sidePotEligibility,complete}') <> 'boolean'
       OR jsonb_typeof(p_policy #> '{key,sidePotEligibility,pots}') <> 'array' THEN
        RETURN false;
    END IF;

    IF EXISTS (
        SELECT 1 FROM (
            SELECT value FROM jsonb_array_elements(p_policy #> '{key,board}')
            UNION ALL
            SELECT value FROM jsonb_array_elements(p_policy #> '{key,holding}')
        ) AS card(value)
        WHERE jsonb_typeof(card.value) <> 'string'
           OR card.value #>> '{}' !~ '^[2-9TJQKA][cdhs]$'
    ) OR (
        SELECT count(*) <> count(DISTINCT value #>> '{}')
        FROM (
            SELECT value FROM jsonb_array_elements(p_policy #> '{key,board}')
            UNION ALL
            SELECT value FROM jsonb_array_elements(p_policy #> '{key,holding}')
        ) AS card(value)
    ) THEN
        RETURN false;
    END IF;

    v_expected_board_count := CASE p_policy #>> '{key,street}'
        WHEN 'preflop' THEN 0 WHEN 'flop' THEN 3 WHEN 'turn' THEN 4
        WHEN 'river' THEN 5 ELSE NULL END;
    v_expected_holding_count := CASE p_policy #>> '{key,variant}'
        WHEN 'nlh' THEN 2 WHEN 'short_deck' THEN 2 WHEN 'pineapple' THEN 3
        WHEN 'plo4' THEN 4 WHEN 'plo5' THEN 5 WHEN 'plo6' THEN 6
        WHEN 'plo8' THEN 4 ELSE NULL END;
    v_key_complete :=
        coalesce(p_policy #>> '{key,variant}', 'unknown') <> 'unknown'
        AND coalesce(p_policy #>> '{key,bettingStructure}', 'unknown') <> 'unknown'
        AND jsonb_typeof(p_policy #> '{key,tableSize}') = 'number'
        AND coalesce(p_policy #>> '{key,positions,hero}', 'UNKNOWN') <> 'UNKNOWN'
        AND coalesce(p_policy #>> '{key,positions,button}', 'UNKNOWN') <> 'UNKNOWN'
        AND coalesce(p_policy #>> '{key,positions,smallBlind}', 'UNKNOWN') <> 'UNKNOWN'
        AND coalesce(p_policy #>> '{key,positions,bigBlind}', 'UNKNOWN') <> 'UNKNOWN'
        AND jsonb_array_length(p_policy #> '{key,positions,villains}') > 0
        AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(
                p_policy #> '{key,positions,villains}'
            ) AS villain(position)
            WHERE villain.position = 'UNKNOWN'
        )
        AND jsonb_array_length(p_policy #> '{key,stackVector}') >= 2
        AND jsonb_array_length(p_policy #> '{key,stackVector}')
            = (p_policy #>> '{key,tableSize}')::integer
        AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(
                p_policy #> '{key,stackVector}'
            ) AS stack(value)
            WHERE NOT (
                (jsonb_typeof(stack.value -> 'stackChips') = 'number'
                    AND (stack.value ->> 'stackChips')::numeric >= 0)
                OR (jsonb_typeof(stack.value -> 'stackBb') = 'number'
                    AND (stack.value ->> 'stackBb')::numeric >= 0)
            )
        )
        AND p_policy #>> '{key,blinds,complete}' = 'true'
        AND jsonb_typeof(p_policy #> '{key,blinds,bigBlind}') = 'number'
        AND (p_policy #>> '{key,blinds,bigBlind}')::numeric > 0
        AND p_policy #>> '{key,rake,complete}' = 'true'
        AND v_expected_board_count IS NOT NULL
        AND jsonb_array_length(p_policy #> '{key,board}') = v_expected_board_count
        AND v_expected_holding_count IS NOT NULL
        AND jsonb_array_length(p_policy #> '{key,holding}') = v_expected_holding_count
        AND p_policy #>> '{key,publicActionHistory,complete}' = 'true'
        AND (
            p_policy #>> '{key,street}' = 'preflop'
            OR jsonb_array_length(p_policy #> '{key,publicActionHistory,actions}') > 0
        )
        AND jsonb_array_length(p_policy #> '{key,legalActions}') > 0
        AND p_policy #>> '{key,sidePotEligibility,complete}' = 'true'
        AND p_policy #>> '{key,tournamentUtility,complete}' = 'true'
        AND (
            p_policy #>> '{key,tournamentUtility,mode}' = 'cash'
            OR jsonb_array_length(p_policy #> '{key,payouts}') > 0
        );
    IF (p_policy #>> '{validDomain,completeKey}')::boolean IS DISTINCT FROM v_key_complete
       OR (v_key_complete AND p_policy #> '{validDomain,missingKeyDimensions}' <> '[]'::jsonb)
       OR (NOT v_key_complete
           AND jsonb_array_length(p_policy #> '{validDomain,missingKeyDimensions}') = 0) THEN
        RETURN false;
    END IF;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_policy #> '{key,stackVector}') LOOP
        IF NOT public.fn_training_cache_jsonb_has_exact_keys(v_item, ARRAY[
              'seat', 'position', 'stackChips', 'stackBb', 'committedChips',
              'active', 'allIn'
           ])
           OR jsonb_typeof(v_item -> 'seat') <> 'number'
           OR trunc((v_item ->> 'seat')::numeric) <> (v_item ->> 'seat')::numeric
           OR (v_item ->> 'seat')::numeric < 0
           OR jsonb_typeof(v_item -> 'position') <> 'string'
           OR jsonb_typeof(v_item -> 'stackChips') NOT IN ('null', 'number')
           OR jsonb_typeof(v_item -> 'stackBb') NOT IN ('null', 'number')
           OR jsonb_typeof(v_item -> 'committedChips') <> 'number'
           OR (v_item ->> 'committedChips')::numeric < 0
           OR jsonb_typeof(v_item -> 'active') <> 'boolean'
           OR jsonb_typeof(v_item -> 'allIn') <> 'boolean' THEN
            RETURN false;
        END IF;
    END LOOP;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_policy #> '{key,publicActionHistory,actions}') LOOP
        IF NOT public.fn_training_cache_jsonb_has_exact_keys(v_item, ARRAY[
              'sequence', 'street', 'actor', 'action', 'amountChips',
              'amountBb', 'allIn'
           ])
           OR jsonb_typeof(v_item -> 'sequence') <> 'number'
           OR trunc((v_item ->> 'sequence')::numeric) <> (v_item ->> 'sequence')::numeric
           OR (v_item ->> 'sequence')::integer <= v_previous_sequence
           OR coalesce(v_item ->> 'street', '') NOT IN ('preflop', 'flop', 'turn', 'river')
           OR jsonb_typeof(v_item -> 'actor') <> 'string'
           OR jsonb_typeof(v_item -> 'action') <> 'string'
           OR jsonb_typeof(v_item -> 'amountChips') NOT IN ('null', 'number')
           OR jsonb_typeof(v_item -> 'amountBb') NOT IN ('null', 'number')
           OR jsonb_typeof(v_item -> 'allIn') <> 'boolean' THEN
            RETURN false;
        END IF;
        v_previous_sequence := (v_item ->> 'sequence')::integer;
    END LOOP;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_policy #> '{key,legalActions}') LOOP
        IF NOT public.fn_training_cache_jsonb_has_exact_keys(v_item, ARRAY[
              'action', 'minChips', 'maxChips', 'exactChips', 'allIn'
           ])
           OR jsonb_typeof(v_item -> 'action') <> 'string'
           OR jsonb_typeof(v_item -> 'minChips') NOT IN ('null', 'number')
           OR jsonb_typeof(v_item -> 'maxChips') NOT IN ('null', 'number')
           OR jsonb_typeof(v_item -> 'exactChips') NOT IN ('null', 'number')
           OR jsonb_typeof(v_item -> 'allIn') <> 'boolean'
           OR (jsonb_typeof(v_item -> 'minChips') = 'number'
               AND jsonb_typeof(v_item -> 'maxChips') = 'number'
               AND (v_item ->> 'minChips')::numeric > (v_item ->> 'maxChips')::numeric) THEN
            RETURN false;
        END IF;
    END LOOP;

    FOR v_item IN
        SELECT value FROM jsonb_array_elements(p_policy #> '{key,payouts}')
        UNION ALL
        SELECT value FROM jsonb_array_elements(p_policy #> '{key,bounties}')
    LOOP
        IF NOT public.fn_training_cache_jsonb_has_exact_keys(
                v_item, ARRAY['place', 'amount', 'type']
           )
           OR jsonb_typeof(v_item -> 'place') <> 'number'
           OR trunc((v_item ->> 'place')::numeric) <> (v_item ->> 'place')::numeric
           OR (v_item ->> 'place')::numeric < 1
           OR jsonb_typeof(v_item -> 'amount') NOT IN ('null', 'number')
           OR jsonb_typeof(v_item -> 'type') <> 'string' THEN
            RETURN false;
        END IF;
    END LOOP;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_policy #> '{key,sidePotEligibility,pots}') LOOP
        IF NOT public.fn_training_cache_jsonb_has_exact_keys(v_item, ARRAY[
              'id', 'amountChips', 'eligibleSeats', 'heroEligible'
           ])
           OR jsonb_typeof(v_item -> 'id') <> 'string'
           OR jsonb_typeof(v_item -> 'amountChips') NOT IN ('null', 'number')
           OR jsonb_typeof(v_item -> 'eligibleSeats') <> 'array'
           OR jsonb_typeof(v_item -> 'heroEligible') <> 'boolean'
           OR EXISTS (
              SELECT 1 FROM jsonb_array_elements(v_item -> 'eligibleSeats') AS seat(value)
              WHERE jsonb_typeof(seat.value) <> 'number'
                 OR trunc((seat.value #>> '{}')::numeric) <> (seat.value #>> '{}')::numeric
                 OR (seat.value #>> '{}')::numeric < 0
           ) THEN
            RETURN false;
        END IF;
    END LOOP;

    FOR v_action IN SELECT value FROM jsonb_array_elements(p_policy -> 'actions') LOOP
        v_action_id := nullif(btrim(v_action ->> 'id'), '');
        IF NOT public.fn_training_cache_jsonb_has_exact_keys(v_action, ARRAY[
              'id', 'sourceCode', 'family', 'label', 'frequency', 'legal',
              'size', 'chipEvBb', 'tournamentUtilityEv'
           ])
           OR v_action_id IS NULL
           OR v_action_id <> lower(v_action_id)
           OR v_action_id = ANY(v_action_ids)
           OR jsonb_typeof(v_action -> 'sourceCode') NOT IN ('null', 'string')
           OR jsonb_typeof(v_action -> 'family') <> 'string'
           OR nullif(v_action ->> 'family', '') IS NULL
           OR jsonb_typeof(v_action -> 'label') <> 'string'
           OR nullif(v_action ->> 'label', '') IS NULL
           OR jsonb_typeof(v_action -> 'frequency') <> 'number'
           OR jsonb_typeof(v_action -> 'legal') <> 'boolean'
           OR jsonb_typeof(v_action -> 'chipEvBb') NOT IN ('null', 'number')
           OR jsonb_typeof(v_action -> 'tournamentUtilityEv') NOT IN ('null', 'number')
           OR NOT public.fn_training_cache_jsonb_has_exact_keys(
                v_action -> 'size',
                ARRAY['unit', 'chips', 'bigBlinds', 'potFraction', 'exact']
              )
           OR coalesce(v_action #>> '{size,unit}', '') NOT IN (
                'none', 'unknown', 'chips', 'big_blinds', 'pot_fraction', 'all_in'
              )
           OR jsonb_typeof(v_action #> '{size,chips}') NOT IN ('null', 'number')
           OR jsonb_typeof(v_action #> '{size,bigBlinds}') NOT IN ('null', 'number')
           OR jsonb_typeof(v_action #> '{size,potFraction}') NOT IN ('null', 'number')
           OR jsonb_typeof(v_action #> '{size,exact}') <> 'boolean' THEN
            RETURN false;
        END IF;
        IF (v_action ->> 'frequency')::numeric < 0
           OR (v_action ->> 'frequency')::numeric > 1 THEN RETURN false; END IF;
        IF jsonb_typeof(p_policy -> 'distribution' -> v_action_id) <> 'number'
           OR abs(
              (p_policy -> 'distribution' ->> v_action_id)::numeric
              - (v_action ->> 'frequency')::numeric
           ) > 0.000000001 THEN
            RETURN false;
        END IF;
        v_action_ids := array_append(v_action_ids, v_action_id);
        v_sum := v_sum + (v_action ->> 'frequency')::numeric;
    END LOOP;
    IF array_length(v_action_ids, 1) IS NULL OR abs(v_sum - 1) > 0.000001 THEN
        RETURN false;
    END IF;
    FOR v_distribution IN SELECT * FROM jsonb_each(p_policy -> 'distribution') LOOP
        IF NOT (v_distribution.key = ANY(v_action_ids))
           OR jsonb_typeof(v_distribution.value) <> 'number' THEN
            RETURN false;
        END IF;
    END LOOP;
    IF (SELECT count(*) FROM jsonb_each(p_policy -> 'distribution'))
        <> array_length(v_action_ids, 1) THEN
        RETURN false;
    END IF;

    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_policy -> 'legalSizes') AS size_row(value)
        WHERE NOT public.fn_training_cache_jsonb_has_exact_keys(size_row.value, ARRAY[
                'actionId', 'unit', 'chips', 'bigBlinds', 'potFraction', 'exact'
              ])
           OR jsonb_typeof(size_row.value -> 'actionId') <> 'string'
           OR NOT (size_row.value ->> 'actionId' = ANY(v_action_ids))
           OR jsonb_typeof(size_row.value -> 'unit') <> 'string'
           OR jsonb_typeof(size_row.value -> 'chips') NOT IN ('null', 'number')
           OR jsonb_typeof(size_row.value -> 'bigBlinds') NOT IN ('null', 'number')
           OR jsonb_typeof(size_row.value -> 'potFraction') NOT IN ('null', 'number')
           OR jsonb_typeof(size_row.value -> 'exact') <> 'boolean'
    ) OR EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_policy -> 'actions') AS action_row(value)
        WHERE action_row.value ->> 'legal' = 'true'
          AND action_row.value #>> '{size,unit}' <> 'none'
          AND NOT EXISTS (
              SELECT 1 FROM jsonb_array_elements(p_policy -> 'legalSizes') AS size_row(value)
              WHERE size_row.value ->> 'actionId' = action_row.value ->> 'id'
                AND size_row.value - 'actionId' = action_row.value -> 'size'
          )
    ) OR EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_policy -> 'legalSizes') AS size_row(value)
        WHERE NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(p_policy -> 'actions') AS action_row(value)
            WHERE action_row.value ->> 'id' = size_row.value ->> 'actionId'
              AND action_row.value ->> 'legal' = 'true'
              AND action_row.value #>> '{size,unit}' <> 'none'
              AND size_row.value - 'actionId' = action_row.value -> 'size'
        )
    ) THEN
        RETURN false;
    END IF;

    FOR v_item IN
        SELECT p_policy -> 'chipEv'
        UNION ALL
        SELECT p_policy -> 'tournamentUtilityEv'
    LOOP
        IF NOT public.fn_training_cache_jsonb_has_exact_keys(
                v_item, ARRAY['unit', 'policy', 'byAction', 'measuredByAction']
           )
           OR jsonb_typeof(v_item -> 'unit') <> 'string'
           OR jsonb_typeof(v_item -> 'policy') NOT IN ('null', 'number')
           OR jsonb_typeof(v_item -> 'byAction') <> 'object'
           OR jsonb_typeof(v_item -> 'measuredByAction') <> 'boolean'
           OR EXISTS (
              SELECT 1 FROM jsonb_each(v_item -> 'byAction') AS ev(key, value)
              WHERE NOT (ev.key = ANY(v_action_ids))
                 OR jsonb_typeof(ev.value) NOT IN ('null', 'number')
           )
           OR EXISTS (
              SELECT 1 FROM unnest(v_action_ids) AS action_id(id)
              WHERE NOT (v_item -> 'byAction' ? action_id.id)
           ) THEN
            RETURN false;
        END IF;
    END LOOP;

    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_policy -> 'actions') AS action_row(value)
        WHERE p_policy #> ARRAY['chipEv', 'byAction', action_row.value ->> 'id']
                IS DISTINCT FROM action_row.value -> 'chipEvBb'
           OR p_policy #> ARRAY[
                'tournamentUtilityEv', 'byAction', action_row.value ->> 'id'
              ] IS DISTINCT FROM action_row.value -> 'tournamentUtilityEv'
           OR (
                p_policy #>> '{chipEv,measuredByAction}' = 'true'
                AND jsonb_typeof(action_row.value -> 'chipEvBb') <> 'number'
           )
           OR (
                p_policy #>> '{chipEv,measuredByAction}' = 'false'
                AND jsonb_typeof(action_row.value -> 'chipEvBb') <> 'null'
           )
           OR (
                p_policy #>> '{tournamentUtilityEv,measuredByAction}' = 'true'
                AND jsonb_typeof(action_row.value -> 'tournamentUtilityEv') <> 'number'
           )
           OR (
                p_policy #>> '{tournamentUtilityEv,measuredByAction}' = 'false'
                AND jsonb_typeof(action_row.value -> 'tournamentUtilityEv') <> 'null'
           )
    ) THEN
        RETURN false;
    END IF;

    IF jsonb_typeof(p_policy -> 'rangeDistribution') = 'object' THEN
        FOR v_mix IN SELECT * FROM jsonb_each(p_policy -> 'rangeDistribution') LOOP
            IF jsonb_typeof(v_mix.value) <> 'object' THEN RETURN false; END IF;
            SELECT coalesce(sum((entry.value #>> '{}')::numeric), 0)
            INTO v_mix_sum
            FROM jsonb_each(v_mix.value) AS entry(key, value)
            WHERE jsonb_typeof(entry.value) = 'number';
            IF EXISTS (
                SELECT 1 FROM jsonb_each(v_mix.value) AS entry(key, value)
                WHERE NOT (entry.key = ANY(v_action_ids))
                   OR jsonb_typeof(entry.value) <> 'number'
                   OR (entry.value #>> '{}')::numeric < 0
                   OR (entry.value #>> '{}')::numeric > 1
            ) OR abs(v_mix_sum - 1) > 0.000001 THEN
                RETURN false;
            END IF;
        END LOOP;
    END IF;

    RETURN true;
END;
$_$;


ALTER FUNCTION public.fn_training_cache_policy_shape_is_valid(p_policy jsonb) OWNER TO postgres;

--
-- Name: fn_training_cache_quarantine_invalid(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_quarantine_invalid() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_count integer;
BEGIN
    WITH moved AS (
        INSERT INTO public.training_question_cache_quarantine (
            original_id, question_id, game_id, source_classification,
            quarantine_reason, original_row, quarantined_at
        )
        SELECT
            c.id,
            c.question_id,
            c.game_id,
            c.source_classification,
            CASE WHEN c.quality_status = 'drifted' THEN 'source_or_cache_drift'
                ELSE public.fn_training_cache_quarantine_reason(
                    c.source_classification, c.question_data, c.canonical_policy
                ) END,
            to_jsonb(c),
            now()
        FROM public.training_question_cache c
        WHERE c.quality_status IN ('quarantined', 'drifted')
        ON CONFLICT (original_id) DO UPDATE
        SET quarantine_reason = EXCLUDED.quarantine_reason,
            original_row = EXCLUDED.original_row,
            quarantined_at = EXCLUDED.quarantined_at
        RETURNING original_id
    ), deleted AS (
        DELETE FROM public.training_question_cache c
        USING moved m
        WHERE c.id = m.original_id
        RETURNING c.id
    )
    SELECT count(*)::integer INTO v_count FROM deleted;
    RETURN coalesce(v_count, 0);
END;
$$;


ALTER FUNCTION public.fn_training_cache_quarantine_invalid() OWNER TO postgres;

--
-- Name: fn_training_cache_quarantine_reason(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_quarantine_reason(p_classification text, p_question jsonb, p_policy jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT CASE
        WHEN jsonb_typeof(p_question) <> 'object' THEN 'question_payload_not_object'
        WHEN jsonb_typeof(p_question -> 'options') <> 'array' THEN 'missing_legal_options'
        WHEN jsonb_array_length(p_question -> 'options') < 2 THEN 'missing_legal_options'
        WHEN nullif(p_question ->> 'correctAnswer', '') IS NULL THEN 'missing_answer_key'
        WHEN NOT public.fn_training_cache_policy_seal_is_valid(p_policy)
          THEN 'invalid_canonical_policy'
        WHEN p_classification = 'LEGACY_UNVERIFIED'
          AND upper(coalesce(p_question ->> 'source', '')) IN
            ('DETERMINISTIC_SOLVER', 'PIO_DATABASE', 'PIO')
          THEN 'unsealed_warehouse_provenance'
        WHEN p_classification = 'CHART_AUDITED'
          AND NOT public.fn_training_cache_has_distribution(p_question)
          THEN 'audited_chart_missing_distribution'
        ELSE 'source_contract_incomplete'
    END;
$$;


ALTER FUNCTION public.fn_training_cache_quarantine_reason(p_classification text, p_question jsonb, p_policy jsonb) OWNER TO postgres;

--
-- Name: fn_training_cache_record_event(text, text, text, uuid, boolean, jsonb, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_record_event(p_event_type text, p_event_key text, p_question_id text, p_user_id uuid DEFAULT NULL::uuid, p_is_correct boolean DEFAULT NULL::boolean, p_metadata jsonb DEFAULT '{}'::jsonb, p_occurred_at timestamp with time zone DEFAULT now(), p_expected_policy_checksum text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_inserted boolean := false;
    v_rows integer := 0;
    v_occurred_at timestamptz := coalesce(p_occurred_at, now());
    v_existing public.training_question_events%ROWTYPE;
    v_cache public.training_question_cache%ROWTYPE;
BEGIN
    IF p_event_type NOT IN ('served', 'answered', 'completed') THEN
        RAISE EXCEPTION 'invalid_training_cache_event_type';
    END IF;
    IF nullif(btrim(p_event_key), '') IS NULL OR length(p_event_key) > 320 THEN
        RAISE EXCEPTION 'invalid_training_cache_event_key';
    END IF;
    IF nullif(btrim(p_question_id), '') IS NULL OR length(p_question_id) > 180 THEN
        RAISE EXCEPTION 'invalid_training_cache_question_id';
    END IF;
    IF (p_event_type = 'answered') <> (p_is_correct IS NOT NULL) THEN
        RAISE EXCEPTION 'answered_event_requires_is_correct';
    END IF;
    IF p_metadata IS NOT NULL AND jsonb_typeof(p_metadata) <> 'object' THEN
        RAISE EXCEPTION 'invalid_training_cache_event_metadata';
    END IF;

    -- Retry the immutable receipt before consulting mutable cache state. This
    -- is the recovery path: an old delivery remains idempotent even after its
    -- source cache row is no longer active. Any changed binding fails closed.
    SELECT * INTO v_existing
    FROM public.training_question_events e
    WHERE e.event_type = p_event_type
      AND e.event_key = p_event_key;
    IF FOUND THEN
        IF v_existing.question_id <> p_question_id
           OR v_existing.user_id IS DISTINCT FROM p_user_id
           OR v_existing.is_correct IS DISTINCT FROM p_is_correct
           OR (p_expected_policy_checksum IS NOT NULL
               AND v_existing.policy_checksum <> lower(p_expected_policy_checksum)) THEN
            RAISE EXCEPTION 'training_cache_event_binding_mismatch';
        END IF;
        RETURN jsonb_build_object(
            'inserted', false,
            'questionId', v_existing.question_id,
            'cacheRowFound', false,
            'policyChecksum', v_existing.policy_checksum,
            'served', 0,
            'answered', 0,
            'correct', 0,
            'completed', 0
        );
    END IF;

    -- Only a genuinely new receipt may depend on mutable cache state. The row
    -- lock serializes its event insertion with all four counter mirrors.
    SELECT * INTO v_cache
    FROM public.training_question_cache c
    WHERE c.question_id = p_question_id
      AND c.quality_status IN ('active', 'active_fallback')
    FOR UPDATE;
    IF v_cache.id IS NULL THEN
        RAISE EXCEPTION 'training_cache_event_question_not_active';
    END IF;
    IF p_expected_policy_checksum IS NOT NULL
       AND lower(p_expected_policy_checksum) <> v_cache.policy_checksum THEN
        RAISE EXCEPTION 'training_cache_event_stale_policy';
    END IF;

    INSERT INTO public.training_question_events (
        event_type, event_key, question_id, user_id, is_correct, policy_checksum,
        metadata, occurred_at
    ) VALUES (
        p_event_type, p_event_key, p_question_id, p_user_id, p_is_correct,
        v_cache.policy_checksum, coalesce(p_metadata, '{}'::jsonb), v_occurred_at
    )
    ON CONFLICT (event_type, event_key) DO NOTHING;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_inserted := v_rows = 1;

    IF NOT v_inserted THEN
        -- A concurrent request may have won after the first read. Re-read and
        -- enforce the same immutable binding before returning idempotently.
        SELECT * INTO v_existing
        FROM public.training_question_events e
        WHERE e.event_type = p_event_type AND e.event_key = p_event_key;
        IF v_existing.id IS NULL
           OR v_existing.question_id <> p_question_id
           OR v_existing.user_id IS DISTINCT FROM p_user_id
           OR v_existing.is_correct IS DISTINCT FROM p_is_correct
           OR (p_expected_policy_checksum IS NOT NULL
               AND v_existing.policy_checksum <> lower(p_expected_policy_checksum)) THEN
            RAISE EXCEPTION 'training_cache_event_binding_mismatch';
        END IF;
    ELSE
        UPDATE public.training_question_cache c
        SET served_count = coalesce(c.served_count, 0)
                + CASE WHEN p_event_type = 'served' THEN 1 ELSE 0 END,
            answered_count = coalesce(c.answered_count, 0)
                + CASE WHEN p_event_type = 'answered' THEN 1 ELSE 0 END,
            correct_count = coalesce(c.correct_count, 0)
                + CASE WHEN p_event_type = 'answered' AND p_is_correct THEN 1 ELSE 0 END,
            completed_count = coalesce(c.completed_count, 0)
                + CASE WHEN p_event_type = 'completed' THEN 1 ELSE 0 END,
            times_used = LEAST(
                2147483647,
                coalesce(c.times_used, 0)
                    + CASE WHEN p_event_type = 'served' THEN 1 ELSE 0 END
            ),
            last_served_at = CASE WHEN p_event_type = 'served'
                THEN greatest(coalesce(c.last_served_at, '-infinity'::timestamptz), v_occurred_at)
                ELSE c.last_served_at END,
            last_answered_at = CASE WHEN p_event_type = 'answered'
                THEN greatest(coalesce(c.last_answered_at, '-infinity'::timestamptz), v_occurred_at)
                ELSE c.last_answered_at END,
            last_completed_at = CASE WHEN p_event_type = 'completed'
                THEN greatest(coalesce(c.last_completed_at, '-infinity'::timestamptz), v_occurred_at)
                ELSE c.last_completed_at END
        WHERE c.question_id = p_question_id
        RETURNING c.* INTO v_cache;
    END IF;

    RETURN jsonb_build_object(
        'inserted', v_inserted,
        'questionId', p_question_id,
        'cacheRowFound', v_cache.id IS NOT NULL,
        'policyChecksum', coalesce(v_existing.policy_checksum, v_cache.policy_checksum),
        'served', coalesce(v_cache.served_count, 0),
        'answered', coalesce(v_cache.answered_count, 0),
        'correct', coalesce(v_cache.correct_count, 0),
        'completed', coalesce(v_cache.completed_count, 0)
    );
END;
$$;


ALTER FUNCTION public.fn_training_cache_record_event(p_event_type text, p_event_key text, p_question_id text, p_user_id uuid, p_is_correct boolean, p_metadata jsonb, p_occurred_at timestamp with time zone, p_expected_policy_checksum text) OWNER TO postgres;

--
-- Name: fn_training_cache_record_served_batch(text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_record_served_batch(p_request_key text, p_question_receipts jsonb, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_receipt record;
    v_result jsonb;
    v_inserted integer := 0;
    v_requested integer := 0;
    v_raw_count integer := 0;
BEGIN
    IF nullif(btrim(p_request_key), '') IS NULL OR length(p_request_key) > 180 THEN
        RAISE EXCEPTION 'invalid_training_cache_request_key';
    END IF;
    IF jsonb_typeof(p_question_receipts) <> 'array' THEN
        RAISE EXCEPTION 'invalid_training_cache_question_batch';
    END IF;
    v_raw_count := jsonb_array_length(p_question_receipts);
    IF v_raw_count < 1 OR v_raw_count > 50 THEN
        RAISE EXCEPTION 'invalid_training_cache_question_batch';
    END IF;
    SELECT count(DISTINCT btrim(item ->> 'questionId'))::integer INTO v_requested
    FROM jsonb_array_elements(p_question_receipts) AS receipts(item)
    WHERE jsonb_typeof(item) = 'object'
      AND nullif(btrim(item ->> 'questionId'), '') IS NOT NULL
      AND length(btrim(item ->> 'questionId')) <= 180
      AND lower(coalesce(item ->> 'policyChecksum', '')) ~ '^[0-9a-f]{64}$';
    IF v_requested <> v_raw_count THEN
        RAISE EXCEPTION 'invalid_training_cache_question_receipts';
    END IF;

    FOR v_receipt IN
        SELECT
            btrim(item ->> 'questionId') AS question_id,
            lower(item ->> 'policyChecksum') AS policy_checksum
        FROM jsonb_array_elements(p_question_receipts) AS receipts(item)
        ORDER BY btrim(item ->> 'questionId')
    LOOP
        v_result := public.fn_training_cache_record_event(
            'served',
            p_request_key || ':' || encode(extensions.digest(v_receipt.question_id, 'sha256'), 'hex'),
            v_receipt.question_id,
            p_user_id,
            NULL,
            jsonb_build_object(
                'requestKey', p_request_key,
                'policyChecksum', v_receipt.policy_checksum
            ),
            now(),
            v_receipt.policy_checksum
        );
        IF coalesce((v_result ->> 'inserted')::boolean, false) THEN
            v_inserted := v_inserted + 1;
        END IF;
    END LOOP;
    RETURN jsonb_build_object(
        'requestKey', p_request_key,
        'questionCount', v_requested,
        'inserted', v_inserted,
        'duplicates', v_requested - v_inserted
    );
END;
$_$;


ALTER FUNCTION public.fn_training_cache_record_served_batch(p_request_key text, p_question_receipts jsonb, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_training_cache_reject_invalid_write(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_reject_invalid_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
BEGIN
    IF NEW.quality_status NOT IN ('active', 'active_fallback') THEN
        RAISE EXCEPTION 'training_cache_write_failed_truth_contract';
    END IF;
    IF NEW.source_classification IN (
        'SOLVER_EXACT', 'SOLVER_AGGREGATED', 'SOLVER_DERIVED_RESPONSE'
    ) AND NOT EXISTS (
        SELECT 1
        FROM public.solved_spots_gold s
        WHERE s.scenario_hash = NEW.scenario_hash
          AND s.source_artifact_checksum = NEW.source_checksum
    ) THEN
        RAISE EXCEPTION 'training_cache_write_missing_solver_artifact';
    END IF;
    IF NEW.source_classification = 'CHART_AUDITED'
       AND (
          NEW.canonical_policy #>> '{sourceArtifact,system}' <> 'memory_charts_gold'
          OR coalesce(NEW.canonical_policy #>> '{sourceArtifact,artifactId}', '')
                !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
          OR NOT EXISTS (
              SELECT 1
              FROM public.memory_charts_gold m
              WHERE m.chart_id::text = lower(
                  NEW.canonical_policy #>> '{sourceArtifact,artifactId}'
              )
          )
       ) THEN
        RAISE EXCEPTION 'training_cache_write_missing_chart_artifact';
    END IF;
    RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_training_cache_reject_invalid_write() OWNER TO postgres;

--
-- Name: fn_training_cache_release_restored(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_release_restored(p_original_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_count integer := 0;
BEGIN
    IF coalesce(array_length(p_original_ids, 1), 0) < 1
       OR array_length(p_original_ids, 1) > 500 THEN
        RAISE EXCEPTION 'invalid_training_cache_restore_batch';
    END IF;

    -- Rebuild the legacy usage ledger only after the replacement row has
    -- passed the canonical policy validator. Historical answer correctness is
    -- regraded from that replacement policy; the old cached answer key is
    -- never copied into the new counters.
    INSERT INTO public.training_question_events (
        event_type, event_key, question_id, is_correct, policy_checksum,
        metadata, occurred_at
    )
    SELECT
        'served',
        'legacy-served:' || q.original_id::text || ':' || n::text,
        c.question_id,
        NULL,
        c.policy_checksum,
        jsonb_build_object(
            'backfill', true,
            'legacyColumn', 'times_used',
            'policyChecksum', c.policy_checksum
        ),
        coalesce(
            public.fn_training_cache_try_timestamptz(q.original_row ->> 'generated_at'),
            c.generated_at,
            now()
        )
    FROM public.training_question_cache_quarantine q
    JOIN public.training_question_cache c
      ON c.id = q.original_id AND c.question_id = q.question_id
    CROSS JOIN LATERAL generate_series(
        1,
        CASE WHEN coalesce(q.original_row ->> 'times_used', '') ~ '^[0-9]+$'
            THEN least((q.original_row ->> 'times_used')::integer, 2147483647)
            ELSE 0 END
    ) AS n
    WHERE q.original_id = ANY(p_original_ids)
      AND c.quality_status IN ('active', 'active_fallback')
    ON CONFLICT (event_type, event_key) DO NOTHING;

    INSERT INTO public.training_question_events (
        event_type, event_key, question_id, user_id, is_correct,
        policy_checksum, metadata, occurred_at
    )
    SELECT
        'answered',
        'training-answer:' || a.id::text,
        c.question_id,
        a.user_id,
        (
            (c.canonical_policy -> 'distribution' ->> lower(a.answer_id))::numeric >= 0.05
            OR (c.canonical_policy -> 'distribution' ->> lower(a.answer_id))::numeric >= (
                SELECT max((frequency.value #>> '{}')::numeric)
                FROM jsonb_each(c.canonical_policy -> 'distribution') AS frequency(key, value)
            )
        ),
        c.policy_checksum,
        jsonb_build_object(
            'backfill', true,
            'historicalAnswerRegraded', true,
            'answerId', a.id,
            'policyChecksum', c.policy_checksum
        ),
        coalesce(a.answered_at, now())
    FROM public.training_question_cache_quarantine q
    JOIN public.training_question_cache c
      ON c.id = q.original_id AND c.question_id = q.question_id
    JOIN public.training_answers a ON a.question_id = c.question_id
    WHERE q.original_id = ANY(p_original_ids)
      AND c.quality_status IN ('active', 'active_fallback')
      AND jsonb_typeof(
          c.canonical_policy -> 'distribution' -> lower(a.answer_id)
      ) = 'number'
    ON CONFLICT (event_type, event_key) DO NOTHING;

    WITH expected AS (
        SELECT
            c.id,
            count(e.id) FILTER (WHERE e.event_type = 'served')::bigint AS served,
            count(e.id) FILTER (WHERE e.event_type = 'answered')::bigint AS answered,
            count(e.id) FILTER (
                WHERE e.event_type = 'answered' AND e.is_correct
            )::bigint AS correct,
            count(e.id) FILTER (WHERE e.event_type = 'completed')::bigint AS completed,
            max(e.occurred_at) FILTER (WHERE e.event_type = 'served') AS last_served,
            max(e.occurred_at) FILTER (WHERE e.event_type = 'answered') AS last_answered,
            max(e.occurred_at) FILTER (WHERE e.event_type = 'completed') AS last_completed
        FROM public.training_question_cache c
        LEFT JOIN public.training_question_events e ON e.question_id = c.question_id
        WHERE c.id = ANY(p_original_ids)
        GROUP BY c.id
    )
    UPDATE public.training_question_cache c
    SET served_count = expected.served,
        answered_count = expected.answered,
        correct_count = expected.correct,
        completed_count = expected.completed,
        times_used = least(2147483647, expected.served)::integer,
        last_served_at = expected.last_served,
        last_answered_at = expected.last_answered,
        last_completed_at = expected.last_completed
    FROM expected
    WHERE c.id = expected.id;

    WITH released AS (
        DELETE FROM public.training_question_cache_quarantine q
        USING public.training_question_cache c
        WHERE q.original_id = ANY(p_original_ids)
          AND c.id = q.original_id
          AND c.question_id = q.question_id
          AND c.quality_status IN ('active', 'active_fallback')
          AND public.fn_training_cache_row_is_valid(
              c.source_classification, c.question_data, c.canonical_policy,
              c.scenario_hash, c.exact_node, c.public_action_history,
              c.policy_version, c.solver_version, c.solver_binary_checksum,
              c.manifest_checksum, c.source_checksum, c.pipeline_commit, c.machine_id
          )
        RETURNING q.original_id
    )
    SELECT count(*)::integer INTO v_count FROM released;
    RETURN v_count;
END;
$_$;


ALTER FUNCTION public.fn_training_cache_release_restored(p_original_ids uuid[]) OWNER TO postgres;

--
-- Name: fn_training_cache_row_is_valid(text, jsonb, jsonb, text, jsonb, jsonb, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_row_is_valid(p_classification text, p_question jsonb, p_policy jsonb, p_scenario_hash text, p_exact_node jsonb, p_public_action_history jsonb, p_policy_version text, p_solver_version text, p_solver_binary_checksum text, p_manifest_checksum text, p_source_checksum text, p_pipeline_commit text, p_machine_id text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_base boolean;
    v_source text := upper(coalesce(p_question ->> 'source', ''));
    v_quality text := upper(coalesce(p_question ->> 'dataQuality', ''));
    v_declared text := upper(coalesce(p_question ->> 'sourceClassification', ''));
    v_policy_valid boolean := public.fn_training_cache_policy_seal_is_valid(p_policy);
    v_policy_kind text := lower(coalesce(p_policy ->> 'kind', ''));
    v_policy_seal text := upper(coalesce(p_policy ->> 'qualitySeal', ''));
    v_correct_answer text := lower(coalesce(p_question ->> 'correctAnswer', ''));
BEGIN
    IF jsonb_typeof(p_question) <> 'object'
       OR jsonb_typeof(p_question -> 'options') <> 'array' THEN
        RETURN false;
    END IF;
    v_base := jsonb_array_length(p_question -> 'options') >= 2
        AND nullif(v_correct_answer, '') IS NOT NULL
        AND v_policy_valid
        AND p_question -> 'solverPolicy' = p_policy
        AND p_question ->> 'sourceClassification' = p_classification
        AND p_question ->> 'dataQuality' = p_classification
        AND p_policy_version = p_policy ->> 'policyVersion'
        AND p_exact_node = p_policy -> 'node'
        AND p_public_action_history = p_policy #> '{key,publicActionHistory}';
    IF NOT v_base THEN RETURN false; END IF;

    -- The player-facing option set and answer hint must describe the immutable
    -- grading policy even though neither field is itself grading authority.
    IF EXISTS (
        SELECT 1
        FROM jsonb_object_keys(p_policy -> 'distribution') AS policy_action(action_id)
        WHERE NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements(p_question -> 'options') AS option_row(value)
            WHERE lower(option_row.value ->> 'id') = lower(policy_action.action_id)
        )
    ) OR (
        SELECT count(*) <> count(DISTINCT lower(option_row.value ->> 'id'))
        FROM jsonb_array_elements(p_question -> 'options') AS option_row(value)
    ) OR EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_question -> 'options') AS option_row(value)
        WHERE jsonb_typeof(option_row.value) <> 'object'
           OR nullif(lower(option_row.value ->> 'id'), '') IS NULL
           OR NOT (p_policy -> 'distribution' ? lower(option_row.value ->> 'id'))
    ) OR NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_question -> 'options') AS option_row(value)
        WHERE lower(option_row.value ->> 'id') = v_correct_answer
    ) OR jsonb_typeof(p_policy -> 'distribution' -> v_correct_answer) <> 'number'
       OR (p_policy -> 'distribution' ->> v_correct_answer)::numeric < (
            SELECT max((entry.value #>> '{}')::numeric)
            FROM jsonb_each(p_policy -> 'distribution') AS entry(key, value)
       ) THEN
        RETURN false;
    END IF;

    CASE p_classification
        WHEN 'SOLVER_EXACT' THEN
            RETURN v_policy_kind = 'exact'
                AND v_policy_seal = 'SOLVER_EXACT'
                AND p_policy #>> '{sourceArtifact,provenanceComplete}' = 'true'
                AND p_policy #>> '{sourceArtifact,scenarioHash}' = p_scenario_hash
                AND p_policy #>> '{sourceArtifact,solverVersion}' = p_solver_version
                AND lower(p_policy #>> '{sourceArtifact,solverBinaryChecksum}')
                    = lower(p_solver_binary_checksum)
                AND lower(p_policy #>> '{sourceArtifact,manifestChecksum}')
                    = lower(p_manifest_checksum)
                AND lower(p_policy #>> '{sourceArtifact,sourceArtifactChecksum}')
                    = lower(p_source_checksum)
                AND lower(p_policy #>> '{sourceArtifact,pipelineCommit}')
                    = lower(p_pipeline_commit)
                AND p_policy #>> '{sourceArtifact,machineId}' = p_machine_id
                AND p_policy #>> '{validDomain,completeKey}' = 'true'
                AND nullif(p_scenario_hash, '') IS NOT NULL
                AND jsonb_typeof(p_exact_node) = 'object'
                AND p_public_action_history #>> '{complete}' = 'true'
                AND nullif(p_policy_version, '') IS NOT NULL
                AND nullif(p_solver_version, '') IS NOT NULL
                AND coalesce(p_solver_binary_checksum, '') ~ '^[0-9a-fA-F]{64}$'
                AND coalesce(p_manifest_checksum, '') ~ '^[0-9a-fA-F]{64}$'
                AND coalesce(p_source_checksum, '') ~ '^[0-9a-fA-F]{64}$'
                AND coalesce(p_pipeline_commit, '') ~ '^[0-9a-fA-F]{40}$'
                AND nullif(p_machine_id, '') IS NOT NULL;
        WHEN 'SOLVER_AGGREGATED' THEN
            RETURN v_policy_kind = 'aggregated'
                AND v_policy_seal = 'SOLVER_AGGREGATED'
                AND nullif(p_policy_version, '') IS NOT NULL
                AND nullif(p_scenario_hash, '') IS NOT NULL
                AND coalesce(p_source_checksum, '') ~ '^[0-9a-fA-F]{64}$'
                AND lower(p_policy #>> '{sourceArtifact,sourceArtifactChecksum}')
                    = lower(p_source_checksum)
                AND p_policy #>> '{sourceArtifact,scenarioHash}' = p_scenario_hash;
        WHEN 'SOLVER_DERIVED_RESPONSE' THEN
            RETURN v_policy_kind = 'derived'
                AND v_policy_seal = 'SOLVER_DERIVED_RESPONSE'
                AND nullif(p_policy_version, '') IS NOT NULL
                AND nullif(p_scenario_hash, '') IS NOT NULL
                AND coalesce(p_source_checksum, '') ~ '^[0-9a-fA-F]{64}$'
                AND lower(p_policy #>> '{sourceArtifact,sourceArtifactChecksum}')
                    = lower(p_source_checksum)
                AND p_policy #>> '{sourceArtifact,scenarioHash}' = p_scenario_hash;
        WHEN 'CHART_AUDITED' THEN
            RETURN v_policy_kind = 'chart'
                AND v_policy_seal = 'CHART_AUDITED'
                AND public.fn_training_cache_has_distribution(p_question)
                AND p_policy #>> '{sourceArtifact,system}' = 'memory_charts_gold'
                AND nullif(p_policy #>> '{sourceArtifact,artifactId}', '') IS NOT NULL
                AND v_source IN ('CHART', 'LOCAL_SOLVER_RANGES');
        WHEN 'MODEL_DISTILLED' THEN
            RETURN v_policy_kind = 'heuristic'
                AND v_policy_seal = 'HEURISTIC'
                AND (v_source IN ('MODEL_DISTILLED', 'DISTILLED_MODEL')
                    OR v_quality = 'MODEL_DISTILLED'
                    OR v_declared = 'MODEL_DISTILLED');
        WHEN 'CURATED' THEN
            RETURN v_policy_kind = 'curated' AND v_policy_seal = 'CURATED';
        WHEN 'HEURISTIC' THEN
            RETURN v_policy_kind = 'heuristic' AND v_policy_seal = 'HEURISTIC';
        WHEN 'LEGACY_UNVERIFIED' THEN
            RETURN v_policy_kind = 'derived'
                AND v_policy_seal = 'LEGACY_UNVERIFIED'
                AND v_source = 'LEGACY_STRATEGY_ARCHIVE'
                AND upper(coalesce(p_question ->> 'dataQuality', '')) = 'LEGACY_UNVERIFIED'
                AND p_question #>> '{solverProvenance,verified}' = 'false'
                AND p_question #>> '{questionContract,valid}' = 'true'
                AND p_question ->> 'evidenceDisclosure'
                    = 'Legacy strategy archive; writer provenance is unavailable.';
        ELSE
            RETURN false;
    END CASE;
END;
$_$;


ALTER FUNCTION public.fn_training_cache_row_is_valid(p_classification text, p_question jsonb, p_policy jsonb, p_scenario_hash text, p_exact_node jsonb, p_public_action_history jsonb, p_policy_version text, p_solver_version text, p_solver_binary_checksum text, p_manifest_checksum text, p_source_checksum text, p_pipeline_commit text, p_machine_id text) OWNER TO postgres;

--
-- Name: fn_training_cache_run_drift_audit(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_run_drift_audit(p_run_date date DEFAULT ((now() AT TIME ZONE 'utc'::text))::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_started timestamptz := clock_timestamp();
    v_shard smallint := mod((p_run_date - DATE '2000-01-01')::integer, 32)::smallint;
    v_storage_shard smallint := mod(v_shard, 16)::smallint;
    v_shard_half smallint := (v_shard / 16)::smallint;
    v_inspected integer := 0;
    v_counter_inspected integer := 0;
    v_content_drift integer := 0;
    v_policy_drift integer := 0;
    v_classification_drift integer := 0;
    v_source_drift integer := 0;
    v_chart_source_missing integer := 0;
    v_lineage_gaps integer := 0;
    v_counter_drift integer := 0;
    v_counter_repaired integer := 0;
    v_quarantined integer := 0;
    v_active integer := 0;
    v_fallback integer := 0;
    v_status text;
    v_metrics jsonb;
    v_findings jsonb := '[]'::jsonb;
    v_result jsonb;
BEGIN
    IF p_run_date IS NULL THEN
        RAISE EXCEPTION 'training_cache_audit_run_date_required';
    END IF;

    -- Remove previously held rows first. They already have immutable recovery
    -- snapshots and must not consume the bounded checksum budget.
    v_quarantined := public.fn_training_cache_quarantine_invalid();

    WITH inspected AS MATERIALIZED (
        SELECT
            c.id,
            c.question_id,
            (
                c.contract_audited_at IS NULL
                OR c.contract_stamped_at > c.contract_audited_at
            ) AS is_dirty,
            c.content_checksum
                <> encode(extensions.digest(c.question_data::text, 'sha256'), 'hex')
                AS content_drift,
            c.policy_checksum
                <> encode(extensions.digest(c.canonical_policy::text, 'sha256'), 'hex')
                AS policy_drift,
            c.source_classification
                <> public.fn_training_cache_attested_classification(
                    c.question_kind, c.question_data, c.canonical_policy
                ) AS classification_drift,
            c.source_classification IN (
                'SOLVER_EXACT', 'SOLVER_AGGREGATED', 'SOLVER_DERIVED_RESPONSE'
            ) AND (
                c.source_checksum IS NULL
                OR c.scenario_hash IS NULL
                OR NOT EXISTS (
                    SELECT 1 FROM public.solved_spots_gold s
                    WHERE s.scenario_hash = c.scenario_hash
                      AND s.source_artifact_checksum = c.source_checksum
                )
            ) AS source_drift,
            c.source_classification = 'CHART_AUDITED'
            AND (
                c.canonical_policy #>> '{sourceArtifact,system}'
                    <> 'memory_charts_gold'
                OR NOT EXISTS (
                    SELECT 1 FROM public.memory_charts_gold m
                    WHERE m.chart_id::text
                        = c.canonical_policy #>> '{sourceArtifact,artifactId}'
                )
            ) AS chart_source_missing,
            (
                c.canonical_policy IS NULL
                OR c.policy_version IS NULL
                OR c.generator_version IS NULL
                OR c.source_created_at IS NULL
                OR jsonb_typeof(c.lineage) IS DISTINCT FROM 'object'
                OR c.lineage ->> 'contractVersion'
                    IS DISTINCT FROM 'smarter-poker.training-cache-lineage.v1'
                OR c.lineage ->> 'sourceClassification'
                    IS DISTINCT FROM c.source_classification
                OR c.question_data -> 'solverPolicy'
                    IS DISTINCT FROM c.canonical_policy
                OR c.question_data ->> 'sourceClassification'
                    IS DISTINCT FROM c.source_classification
                OR c.question_data ->> 'dataQuality'
                    IS DISTINCT FROM c.source_classification
                OR c.policy_version
                    IS DISTINCT FROM c.canonical_policy ->> 'policyVersion'
                OR c.exact_node IS DISTINCT FROM c.canonical_policy -> 'node'
                OR c.public_action_history
                    IS DISTINCT FROM c.canonical_policy #> '{key,publicActionHistory}'
                OR c.canonical_policy ->> 'contractVersion'
                    IS DISTINCT FROM 'smarter-poker.solver-policy.v1'
                OR jsonb_typeof(c.canonical_policy -> 'actions') IS DISTINCT FROM 'array'
                OR CASE
                    WHEN jsonb_typeof(c.canonical_policy -> 'actions') = 'array'
                    THEN jsonb_array_length(c.canonical_policy -> 'actions') < 1
                    ELSE true
                END
                OR jsonb_typeof(c.canonical_policy -> 'distribution')
                    IS DISTINCT FROM 'object'
                OR NOT coalesce(
                    c.canonical_policy -> 'distribution'
                    ? lower(coalesce(c.question_data ->> 'correctAnswer', '')),
                    false
                )
                OR (
                    c.source_classification = 'SOLVER_EXACT'
                    AND (
                        c.scenario_hash IS NULL
                        OR c.exact_node IS NULL
                        OR c.public_action_history #>> '{complete}' <> 'true'
                        OR c.solver_version IS NULL
                        OR c.solver_binary_checksum IS NULL
                        OR c.manifest_checksum IS NULL
                        OR c.source_checksum IS NULL
                        OR c.pipeline_commit IS NULL
                        OR c.machine_id IS NULL
                    )
                )
            ) AS lineage_gap
        FROM public.training_question_cache c
        WHERE c.quality_status IN ('active', 'active_fallback')
          AND (
              c.contract_audited_at IS NULL
              OR c.contract_stamped_at > c.contract_audited_at
              OR c.contract_audited_at >= v_started
              OR (
                  c.audit_shard = v_storage_shard
                  AND mod(
                      get_byte(decode(md5(c.question_id), 'hex'), 1),
                      2
                  ) = v_shard_half
              )
              OR c.source_classification IN (
                  'SOLVER_EXACT', 'SOLVER_AGGREGATED',
                  'SOLVER_DERIVED_RESPONSE', 'CHART_AUDITED'
              )
          )
    ), marked AS (
        UPDATE public.training_question_cache c
        SET quality_status = 'drifted'
        FROM inspected i
        WHERE c.id = i.id
          AND (
              i.content_drift OR i.policy_drift OR i.classification_drift
              OR i.source_drift OR i.chart_source_missing OR i.lineage_gap
          )
        RETURNING c.id
    ), audited AS (
        UPDATE public.training_question_cache c
        SET contract_audited_at = clock_timestamp()
        FROM inspected i
        WHERE c.id = i.id
          AND i.is_dirty
          AND NOT (
              i.content_drift OR i.policy_drift OR i.classification_drift
              OR i.source_drift OR i.chart_source_missing OR i.lineage_gap
          )
        RETURNING c.id
    )
    SELECT
        count(*)::integer,
        count(*) FILTER (WHERE content_drift)::integer,
        count(*) FILTER (WHERE policy_drift)::integer,
        count(*) FILTER (WHERE classification_drift)::integer,
        count(*) FILTER (WHERE source_drift)::integer,
        count(*) FILTER (WHERE chart_source_missing)::integer,
        count(*) FILTER (WHERE lineage_gap)::integer
    INTO
        v_inspected, v_content_drift, v_policy_drift,
        v_classification_drift, v_source_drift,
        v_chart_source_missing, v_lineage_gaps
    FROM inspected
    CROSS JOIN (SELECT count(*) FROM marked) AS force_marked
    CROSS JOIN (SELECT count(*) FROM audited) AS force_audited;

    v_quarantined := v_quarantined
        + public.fn_training_cache_quarantine_invalid();

    WITH due AS MATERIALIZED (
        SELECT c.question_id
        FROM public.training_question_cache c
        WHERE c.quality_status IN ('active', 'active_fallback')
          AND (
              c.contract_audited_at IS NULL
              OR c.contract_stamped_at > c.contract_audited_at
              OR c.contract_audited_at >= v_started
              OR (
                  c.audit_shard = v_storage_shard
                  AND mod(
                      get_byte(decode(md5(c.question_id), 'hex'), 1),
                      2
                  ) = v_shard_half
              )
          )
    ), expected AS MATERIALIZED (
        SELECT
            c.question_id,
            count(e.id) FILTER (WHERE e.event_type = 'served')::bigint AS served,
            count(e.id) FILTER (WHERE e.event_type = 'answered')::bigint AS answered,
            count(e.id) FILTER (
                WHERE e.event_type = 'answered' AND e.is_correct
            )::bigint AS correct,
            count(e.id) FILTER (WHERE e.event_type = 'completed')::bigint AS completed,
            max(e.occurred_at) FILTER (WHERE e.event_type = 'served') AS last_served,
            max(e.occurred_at) FILTER (WHERE e.event_type = 'answered') AS last_answered,
            max(e.occurred_at) FILTER (WHERE e.event_type = 'completed') AS last_completed
        FROM due d
        JOIN public.training_question_cache c USING (question_id)
        LEFT JOIN public.training_question_events e ON e.question_id = c.question_id
        GROUP BY c.question_id
    ), drift AS MATERIALIZED (
        SELECT c.question_id
        FROM public.training_question_cache c
        JOIN expected x USING (question_id)
        WHERE (c.served_count, c.answered_count, c.correct_count, c.completed_count)
            IS DISTINCT FROM (x.served, x.answered, x.correct, x.completed)
    ), repaired AS (
        UPDATE public.training_question_cache c
        SET served_count = x.served,
            answered_count = x.answered,
            correct_count = x.correct,
            completed_count = x.completed,
            times_used = least(2147483647, x.served)::integer,
            last_served_at = x.last_served,
            last_answered_at = x.last_answered,
            last_completed_at = x.last_completed
        FROM expected x
        WHERE x.question_id = c.question_id
          AND EXISTS (
              SELECT 1 FROM drift d WHERE d.question_id = c.question_id
          )
        RETURNING c.id
    )
    SELECT
        (SELECT count(*)::integer FROM due),
        (SELECT count(*)::integer FROM drift),
        (SELECT count(*)::integer FROM repaired)
    INTO v_counter_inspected, v_counter_drift, v_counter_repaired;

    SELECT count(*) FILTER (WHERE quality_status = 'active'),
           count(*) FILTER (WHERE quality_status = 'active_fallback')
    INTO v_active, v_fallback
    FROM public.training_question_cache;

    IF v_content_drift + v_policy_drift + v_classification_drift + v_source_drift
       + v_chart_source_missing + v_lineage_gaps > 0 THEN
        v_status := 'critical';
    ELSIF v_counter_drift > 0 OR v_quarantined > 0 THEN
        v_status := 'warning';
    ELSE
        v_status := 'healthy';
    END IF;

    v_metrics := jsonb_build_object(
        'activeRows', v_active,
        'fallbackRows', v_fallback,
        'rowsInspected', v_inspected,
        'auditShard', v_shard,
        'auditShardCount', 32,
        'contentDriftRows', v_content_drift,
        'policyDriftRows', v_policy_drift,
        'classificationDriftRows', v_classification_drift,
        'sourceDriftRows', v_source_drift,
        'missingChartSourceRows', v_chart_source_missing,
        'lineageGapRows', v_lineage_gaps,
        'counterRowsInspected', v_counter_inspected,
        'counterDriftRows', v_counter_drift,
        'counterRowsRepaired', v_counter_repaired,
        'rowsQuarantined', v_quarantined
    );
    IF v_content_drift > 0 THEN
        v_findings := v_findings || jsonb_build_array(jsonb_build_object(
            'severity', 'critical', 'code', 'content_checksum_drift',
            'count', v_content_drift
        ));
    END IF;
    IF v_policy_drift > 0 THEN
        v_findings := v_findings || jsonb_build_array(jsonb_build_object(
            'severity', 'critical', 'code', 'policy_checksum_drift',
            'count', v_policy_drift
        ));
    END IF;
    IF v_classification_drift > 0 THEN
        v_findings := v_findings || jsonb_build_array(jsonb_build_object(
            'severity', 'critical', 'code', 'classification_drift',
            'count', v_classification_drift
        ));
    END IF;
    IF v_source_drift + v_chart_source_missing > 0 THEN
        v_findings := v_findings || jsonb_build_array(jsonb_build_object(
            'severity', 'critical', 'code', 'source_artifact_drift',
            'count', v_source_drift + v_chart_source_missing
        ));
    END IF;
    IF v_lineage_gaps > 0 THEN
        v_findings := v_findings || jsonb_build_array(jsonb_build_object(
            'severity', 'critical', 'code', 'lineage_incomplete',
            'count', v_lineage_gaps
        ));
    END IF;
    IF v_counter_drift > 0 THEN
        v_findings := v_findings || jsonb_build_array(jsonb_build_object(
            'severity', 'warning', 'code', 'counter_reconciled',
            'count', v_counter_drift
        ));
    END IF;

    INSERT INTO public.training_cache_audit_runs (
        run_date, status, metrics, findings, run_count, started_at, completed_at
    ) VALUES (
        p_run_date, v_status, v_metrics, v_findings, 1, v_started, clock_timestamp()
    )
    ON CONFLICT (run_date) DO UPDATE
    SET status = EXCLUDED.status,
        metrics = EXCLUDED.metrics,
        findings = EXCLUDED.findings,
        run_count = public.training_cache_audit_runs.run_count + 1,
        started_at = EXCLUDED.started_at,
        completed_at = EXCLUDED.completed_at
    RETURNING jsonb_build_object(
        'runDate', run_date,
        'status', status,
        'metrics', metrics,
        'findings', findings,
        'runCount', run_count,
        'startedAt', started_at,
        'completedAt', completed_at
    ) INTO v_result;
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_training_cache_run_drift_audit(p_run_date date) OWNER TO postgres;

--
-- Name: fn_training_cache_stamp_row(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_stamp_row() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_policy jsonb;
    v_source jsonb;
    v_provenance jsonb;
    v_scenario jsonb;
    v_classification text;
BEGIN
    NEW.question_data := coalesce(NEW.question_data, '{}'::jsonb);
    NEW.question_data := jsonb_set(
        NEW.question_data, '{id}', to_jsonb(NEW.question_id), true
    );
    NEW.question_kind := coalesce(nullif(NEW.question_kind, ''), NEW.engine_type);
    v_policy := coalesce(
        CASE WHEN jsonb_typeof(NEW.canonical_policy) = 'object' THEN NEW.canonical_policy END,
        CASE WHEN jsonb_typeof(NEW.question_data -> 'solverPolicy') = 'object'
            THEN NEW.question_data -> 'solverPolicy' END
    );
    NEW.canonical_policy := v_policy;
    IF jsonb_typeof(v_policy) = 'object' THEN
        -- canonical_policy is the database grading authority. Keep the embedded
        -- response envelope byte-identical so APIs cannot serve one policy
        -- while counters and answers bind to another.
        NEW.question_data := jsonb_set(
            NEW.question_data, '{solverPolicy}', v_policy, true
        );
    END IF;
    v_source := coalesce(v_policy -> 'sourceArtifact', '{}'::jsonb);
    v_provenance := coalesce(NEW.question_data -> 'solverProvenance', '{}'::jsonb);
    v_scenario := coalesce(NEW.question_data -> 'scenario', '{}'::jsonb);

    v_classification := public.fn_training_cache_derive_classification(
        NEW.question_kind, NEW.question_data, v_policy
    );
    NEW.source_classification := v_classification;
    NEW.question_data := jsonb_set(
        jsonb_set(NEW.question_data, '{sourceClassification}', to_jsonb(v_classification), true),
        '{dataQuality}', to_jsonb(v_classification), true
    );

    NEW.scenario_hash := coalesce(
        nullif(v_source ->> 'scenarioHash', ''),
        nullif(v_provenance ->> 'scenarioHash', ''),
        nullif(v_scenario ->> 'scenarioHash', ''),
        nullif(NEW.question_data ->> 'scenarioHash', '')
    );
    NEW.exact_node := CASE WHEN jsonb_typeof(v_policy -> 'node') = 'object'
        THEN v_policy -> 'node' END;
    NEW.public_action_history := CASE
        WHEN jsonb_typeof(v_policy #> '{key,publicActionHistory}') = 'object'
            THEN v_policy #> '{key,publicActionHistory}'
        ELSE NULL
    END;
    NEW.policy_version := nullif(v_policy ->> 'policyVersion', '');
    NEW.solver_version := coalesce(
        nullif(v_source ->> 'solverVersion', ''),
        nullif(v_provenance ->> 'solverVersion', ''),
        NULL
    );
    NEW.solver_binary_checksum := coalesce(
        nullif(v_source ->> 'solverBinaryChecksum', ''),
        nullif(v_provenance ->> 'solverBinaryChecksum', ''),
        NULL
    );
    NEW.manifest_version := coalesce(
        nullif(v_source ->> 'manifestVersion', ''),
        nullif(v_provenance ->> 'manifestVersion', ''),
        NULL
    );
    NEW.manifest_checksum := coalesce(
        nullif(v_source ->> 'manifestChecksum', ''),
        nullif(v_provenance ->> 'manifestChecksum', ''),
        NULL
    );
    NEW.source_checksum := coalesce(
        nullif(v_source ->> 'sourceArtifactChecksum', ''),
        nullif(v_provenance ->> 'sourceArtifactChecksum', ''),
        NULL
    );
    NEW.pipeline_commit := coalesce(
        nullif(v_source ->> 'pipelineCommit', ''),
        nullif(v_provenance ->> 'pipelineCommit', ''),
        NULL
    );
    NEW.machine_id := coalesce(
        nullif(v_source ->> 'machineId', ''),
        nullif(v_provenance ->> 'machineId', ''),
        NULL
    );
    NEW.source_created_at := coalesce(NEW.source_created_at, NEW.generated_at, now());
    NEW.source_audited_at := coalesce(
        public.fn_training_cache_try_timestamptz(v_source ->> 'auditedAt'),
        public.fn_training_cache_try_timestamptz(v_provenance ->> 'auditedAt'),
        NULL
    );
    NEW.generator_version := coalesce(
        nullif(NEW.question_data ->> 'generatorVersion', ''),
        nullif(NEW.question_data ->> 'engineVersion', ''),
        NEW.generator_version,
        'training-cache-contract.1:' || lower(v_classification)
    );
    NEW.lineage := jsonb_strip_nulls(jsonb_build_object(
        'contractVersion', 'smarter-poker.training-cache-lineage.v1',
        'sourceClassification', v_classification,
        'policyVersion', NEW.policy_version,
        'scenarioHash', NEW.scenario_hash,
        'exactNode', NEW.exact_node,
        'publicActionHistory', NEW.public_action_history,
        'sourceArtifact', v_source,
        'sourceCreatedAt', NEW.source_created_at,
        'sourceAuditedAt', NEW.source_audited_at,
        'generatorVersion', NEW.generator_version
    ));
    NEW.content_checksum := encode(extensions.digest(NEW.question_data::text, 'sha256'), 'hex');
    NEW.policy_checksum := CASE
        WHEN jsonb_typeof(NEW.canonical_policy) = 'object'
            THEN encode(extensions.digest(NEW.canonical_policy::text, 'sha256'), 'hex')
        ELSE NULL
    END;
    IF NEW.served_count = 0 AND coalesce(NEW.times_used, 0) > 0 THEN
        NEW.served_count := NEW.times_used;
    END IF;
    NEW.quality_status := CASE
        WHEN public.fn_training_cache_row_is_valid(
            v_classification, NEW.question_data, v_policy, NEW.scenario_hash,
            NEW.exact_node, NEW.public_action_history, NEW.policy_version,
            NEW.solver_version, NEW.solver_binary_checksum, NEW.manifest_checksum,
            NEW.source_checksum, NEW.pipeline_commit, NEW.machine_id
        ) THEN CASE WHEN v_classification = 'LEGACY_UNVERIFIED'
            THEN 'active_fallback' ELSE 'active' END
        ELSE 'quarantined'
    END;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_training_cache_stamp_row() OWNER TO postgres;

--
-- Name: fn_training_cache_try_timestamptz(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_cache_try_timestamptz(p_value text) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    IF nullif(btrim(p_value), '') IS NULL THEN RETURN NULL; END IF;
    RETURN p_value::timestamptz;
EXCEPTION WHEN others THEN
    RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_training_cache_try_timestamptz(p_value text) OWNER TO postgres;

--
-- Name: fn_training_canonical_jsonb_text_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_canonical_jsonb_text_v1(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_result text;
BEGIN
  CASE jsonb_typeof(p_value)
    WHEN 'object' THEN
      SELECT '{' || coalesce(string_agg(
        to_jsonb(entry.key)::text || ':'
          || public.fn_training_canonical_jsonb_text_v1(entry.value),
        ',' ORDER BY entry.key COLLATE "C"
      ), '') || '}'
      INTO v_result
      FROM jsonb_each(p_value) AS entry;
    WHEN 'array' THEN
      SELECT '[' || coalesce(string_agg(
        public.fn_training_canonical_jsonb_text_v1(entry.value),
        ',' ORDER BY entry.ordinality
      ), '') || ']'
      INTO v_result
      FROM jsonb_array_elements(p_value) WITH ORDINALITY AS entry(value, ordinality);
    ELSE
      v_result := p_value::text;
  END CASE;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_training_canonical_jsonb_text_v1(p_value jsonb) OWNER TO postgres;

--
-- Name: fn_training_capture_streak_activity_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_capture_streak_activity_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_activity_date date;
  v_summary jsonb;
BEGIN
  IF NEW.status IS DISTINCT FROM 'completed'
     OR NEW.practice_only
     OR (
       TG_OP = 'UPDATE'
       AND OLD.status IS NOT DISTINCT FROM 'completed'
     ) THEN
    RETURN NEW;
  END IF;
  IF NEW.session_kind = 'daily'
     AND NOT public.fn_training_daily_attempt_matches_start_v1(
       NEW.client_nonce,
       NEW.started_at
     ) THEN
    RETURN NEW;
  END IF;

  v_activity_date := CASE
    WHEN NEW.session_kind = 'daily'
      THEN timezone('America/Chicago', NEW.started_at)::date
    ELSE timezone('America/Chicago', NEW.completed_at)::date
  END;
  IF v_activity_date IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.training_streaks AS streaks (
    user_id, current_streak, longest_streak, last_training_date,
    streak_start_date, milestones_claimed,
    authority_current_streak, authority_longest_streak,
    authority_last_training_date, authority_streak_start_date,
    authority_milestones_claimed, created_at, updated_at
  ) VALUES (
    NEW.user_id, 1, 1, v_activity_date,
    v_activity_date, '[]'::jsonb,
    1, 1, v_activity_date, v_activity_date, '[]'::jsonb, now(), now()
  )
  ON CONFLICT (user_id) DO NOTHING;

  PERFORM 1
  FROM public.training_streaks streaks
  WHERE streaks.user_id = NEW.user_id
  FOR UPDATE;

  INSERT INTO public.training_streak_activity_days (
    user_id, activity_date, first_attempt_id
  ) VALUES (
    NEW.user_id, v_activity_date, NEW.id
  )
  ON CONFLICT (user_id, activity_date) DO NOTHING;

  v_summary := public.fn_training_streak_summary_v1(NEW.user_id);
  UPDATE public.training_streaks AS streaks
  SET
    authority_current_streak = (v_summary ->> 'current')::integer,
    authority_longest_streak = greatest(
      streaks.authority_longest_streak,
      (v_summary ->> 'longest')::integer
    ),
    authority_last_training_date = (v_summary ->> 'lastDate')::date,
    authority_streak_start_date = (v_summary ->> 'startDate')::date,
    current_streak = (v_summary ->> 'current')::integer,
    longest_streak = greatest(
      streaks.authority_longest_streak,
      (v_summary ->> 'longest')::integer
    ),
    last_training_date = (v_summary ->> 'lastDate')::date,
    streak_start_date = (v_summary ->> 'startDate')::date,
    milestones_claimed = streaks.authority_milestones_claimed,
    updated_at = now()
  WHERE streaks.user_id = NEW.user_id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_training_capture_streak_activity_v1() OWNER TO postgres;

--
-- Name: fn_training_daily_attempt_hand_seal_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_daily_attempt_hand_seal_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  attempt_row public.training_attempts%ROWTYPE;
  snapshot_row public.training_question_snapshots%ROWTYPE;
  seal_row public.training_daily_question_seals%ROWTYPE;
  policy_checksum text;
BEGIN
  SELECT * INTO attempt_row
  FROM public.training_attempts
  WHERE id = NEW.attempt_id;

  IF NOT FOUND OR attempt_row.session_kind <> 'daily' THEN
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.training_daily_question_conflicts conflicts
    WHERE conflicts.daily_id = attempt_row.client_nonce
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TRAINING_DAILY_QUESTION_SEAL_CONFLICT';
  END IF;
  IF attempt_row.client_nonce !~ '^daily-[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     OR attempt_row.game_id <> 'daily-challenge'
     OR attempt_row.level <> 1
     OR NEW.hand_ordinal <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TRAINING_DAILY_ATTEMPT_CONTRACT_INVALID';
  END IF;

  SELECT * INTO snapshot_row
  FROM public.training_question_snapshots
  WHERE snapshot_key = NEW.snapshot_key;
  policy_checksum := lower(snapshot_row.question_data ->> 'policyChecksum');
  IF NOT FOUND
     OR snapshot_row.game_id <> 'daily-challenge'
     OR snapshot_row.level <> 1
     OR snapshot_row.source_question_id IS DISTINCT FROM (snapshot_row.question_data ->> 'id')
     OR coalesce(policy_checksum, '') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TRAINING_DAILY_SNAPSHOT_CONTRACT_INVALID';
  END IF;

  INSERT INTO public.training_daily_question_seals (
    daily_id,
    snapshot_key,
    source_question_id,
    source_policy_checksum
  ) VALUES (
    attempt_row.client_nonce,
    snapshot_row.snapshot_key,
    snapshot_row.source_question_id,
    policy_checksum
  )
  ON CONFLICT (daily_id) DO NOTHING;

  SELECT * INTO seal_row
  FROM public.training_daily_question_seals
  WHERE daily_id = attempt_row.client_nonce;
  IF NOT FOUND
     OR seal_row.snapshot_key <> snapshot_row.snapshot_key
     OR seal_row.source_question_id <> snapshot_row.source_question_id
     OR seal_row.source_policy_checksum <> policy_checksum THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TRAINING_DAILY_SNAPSHOT_BINDING_MISMATCH';
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_training_daily_attempt_hand_seal_v1() OWNER TO postgres;

--
-- Name: fn_training_daily_attempt_matches_start_v1(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_daily_attempt_matches_start_v1(p_client_nonce text, p_started_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT p_client_nonce = (
    'daily-' || timezone('America/Chicago', p_started_at)::date::text
  );
$$;


ALTER FUNCTION public.fn_training_daily_attempt_matches_start_v1(p_client_nonce text, p_started_at timestamp with time zone) OWNER TO postgres;

