-- Name: fn_training_daily_question_seal_immutable_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_daily_question_seal_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  RAISE EXCEPTION USING
    ERRCODE = '23514',
    MESSAGE = 'TRAINING_DAILY_QUESTION_SEAL_IMMUTABLE';
