-- Name: FUNCTION fn_trivia_award_diamonds(p_user_id uuid, p_amount integer, p_type text, p_description text, p_reference_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_trivia_award_diamonds(p_user_id uuid, p_amount integer, p_type text, p_description text, p_reference_id text) IS 'Phase 80 — the hardened trivia diamond path. service_role only; validates the award type against trivia_diamond_award_limits, clamps the magnitude, requires a stable reference_id, then delegates to add_diamonds_to_balance. Returns the same {success, new_balance, error} shape the diamondRpc() wrapper in pages/hub/trivia/pvp.js already checks.';


--
-- Name: fn_trivia_consume_item(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trivia_consume_item(p_item_type text, p_amount integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_user uuid := (SELECT auth.uid());
    v_n    integer := LEAST(GREATEST(COALESCE(p_amount, 1), 1), 100);
    v_qty  integer;
BEGIN
    IF v_user IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;

    UPDATE public.trivia_user_items
       SET quantity = quantity - v_n, updated_at = now()
     WHERE user_id = v_user
       AND item_type = p_item_type
       AND quantity >= v_n
     RETURNING quantity INTO v_qty;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'insufficient_items');
    END IF;
    RETURN jsonb_build_object('success', true, 'item_type', p_item_type, 'quantity', v_qty);
END;
$$;


ALTER FUNCTION public.fn_trivia_consume_item(p_item_type text, p_amount integer) OWNER TO postgres;

--
-- Name: fn_trivia_grade_answer(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trivia_grade_answer(p_question_id uuid, p_selected integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_user      uuid := (SELECT auth.uid());
    v_service   boolean := ((SELECT auth.role()) = 'service_role');
    v_correct   integer;
    v_expl      text;
    v_opts      integer;
BEGIN
    IF v_user IS NULL AND NOT v_service THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;

    SELECT q.correct_index,
           q.explanation,
           CASE WHEN jsonb_typeof(q.options) = 'array' THEN jsonb_array_length(q.options) ELSE 0 END
      INTO v_correct, v_expl, v_opts
      FROM public.trivia_questions q
     WHERE q.id = p_question_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'question_not_found');
    END IF;

    -- No commitment, no reveal.
    IF p_selected IS NULL OR p_selected < 0 OR (v_opts > 0 AND p_selected >= v_opts) THEN
        RETURN jsonb_build_object('success', false, 'error', 'answer_required');
    END IF;

    IF v_user IS NOT NULL THEN
        -- FIRST answer wins: ON CONFLICT DO NOTHING leaves an existing
        -- commitment (and its was_correct verdict) untouched, so a second call
        -- cannot rewrite history to claim a question was answered correctly.
        INSERT INTO public.trivia_user_question_history (user_id, question_id, was_correct, seen_at)
        VALUES (v_user, p_question_id, (p_selected = v_correct), now())
        ON CONFLICT (user_id, question_id) DO NOTHING;
    END IF;

    RETURN jsonb_build_object(
        'success',       true,
        'was_correct',   (p_selected = v_correct),
        'correct_index', v_correct,
        'explanation',   v_expl
    );
END;
$$;


ALTER FUNCTION public.fn_trivia_grade_answer(p_question_id uuid, p_selected integer) OWNER TO postgres;

