--
-- Name: fn_trivia_prize_wheel_spin(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trivia_prize_wheel_spin(p_score_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_user uuid:=(SELECT auth.uid());
    v_score record;
    v_existing public.trivia_prize_wheel_spins%ROWTYPE;
    v_roll int; v_prize_id text; v_type text; v_base int;
    v_streak int:=0; v_mult numeric(4,2):=1; v_amount int;
    v_credit jsonb; v_item_qty int;
BEGIN
    IF (SELECT auth.role())='service_role' THEN
        SELECT user_id INTO v_user FROM public.trivia_scores WHERE id=p_score_id;
    END IF;
    IF v_user IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_authenticated'); END IF;
    SELECT s.id,s.user_id,s.correct_count,s.total_questions,s.created_at,s.session_id,s.server_verified
      INTO v_score FROM public.trivia_scores s WHERE s.id=p_score_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','score_not_found'); END IF;
    IF v_score.user_id IS DISTINCT FROM v_user THEN RETURN jsonb_build_object('success',false,'error','not_your_score'); END IF;
    IF v_score.server_verified IS NOT TRUE OR v_score.session_id IS NULL OR NOT EXISTS(
        SELECT 1 FROM public.trivia_sessions ts WHERE ts.id=v_score.session_id
         AND ts.user_id=v_user AND ts.status='submitted' AND ts.correct_count=v_score.correct_count
    ) THEN RETURN jsonb_build_object('success',false,'error','score_not_server_verified'); END IF;
    IF COALESCE(v_score.total_questions,0)<5 OR v_score.correct_count IS DISTINCT FROM v_score.total_questions THEN
        RETURN jsonb_build_object('success',false,'error','not_a_perfect_game');
    END IF;
    IF v_score.created_at<now()-interval '30 minutes' THEN RETURN jsonb_build_object('success',false,'error','spin_window_expired'); END IF;
    SELECT * INTO v_existing FROM public.trivia_prize_wheel_spins WHERE score_id=p_score_id;
    IF FOUND THEN RETURN jsonb_build_object('success',true,'deduped',true,'prize_id',v_existing.prize_id,
        'prize_type',v_existing.prize_type,'prize_amount',v_existing.prize_amount,'multiplier',v_existing.multiplier); END IF;
    v_roll:=floor(random()*100)::int;
    IF v_roll<30 THEN v_prize_id:='diamond_5';v_type:='diamonds';v_base:=5;
    ELSIF v_roll<55 THEN v_prize_id:='diamond_10';v_type:='diamonds';v_base:=10;
    ELSIF v_roll<70 THEN v_prize_id:='diamond_25';v_type:='diamonds';v_base:=25;
    ELSIF v_roll<80 THEN v_prize_id:='diamond_50';v_type:='diamonds';v_base:=50;
    ELSIF v_roll<85 THEN v_prize_id:='diamond_100';v_type:='diamonds';v_base:=100;
    ELSIF v_roll<93 THEN v_prize_id:='streak_shield';v_type:='streak_shield';v_base:=1;
    ELSIF v_roll<98 THEN v_prize_id:='free_entry';v_type:='arcade_ticket';v_base:=1;
    ELSE v_prize_id:='mystery';v_type:='diamonds';v_base:=15; END IF;
    SELECT COALESCE(current_streak,0) INTO v_streak FROM public.trivia_streaks WHERE user_id=v_user;
    v_mult:=CASE WHEN v_streak>=100 THEN 5 WHEN v_streak>=30 THEN 3 WHEN v_streak>=14 THEN 2.5 WHEN v_streak>=7 THEN 2 ELSE 1 END;
    IF v_type='diamonds' THEN v_amount:=floor(v_base*v_mult)::int; ELSE v_amount:=v_base;v_mult:=1; END IF;
    INSERT INTO public.trivia_prize_wheel_spins(user_id,score_id,prize_id,prize_type,prize_amount,multiplier)
    VALUES(v_user,p_score_id,v_prize_id,v_type,v_amount,v_mult);
    IF v_type='diamonds' THEN
        SELECT public.add_diamonds_to_balance(v_user,v_amount,'trivia_prize_wheel',
            'Prize Wheel - '||v_prize_id,'trivia_wheel_'||p_score_id::text) INTO v_credit;
        IF COALESCE((v_credit->>'success')::boolean,false) IS NOT TRUE
           AND COALESCE((v_credit->>'duplicate')::boolean,false) IS NOT TRUE THEN
            RAISE EXCEPTION 'wheel credit rejected: %',COALESCE(v_credit->>'error','unknown');
        END IF;
    ELSE
        INSERT INTO public.trivia_user_items AS i(user_id,item_type,quantity,created_at,updated_at)
        VALUES(v_user,v_type,v_amount,now(),now()) ON CONFLICT(user_id,item_type)
        DO UPDATE SET quantity=i.quantity+v_amount,updated_at=now() RETURNING quantity INTO v_item_qty;
        INSERT INTO public.trivia_item_transactions(user_id,item_type,amount,balance_after,
            transaction_type,reference_id,metadata)
        VALUES(v_user,v_type,v_amount,v_item_qty,'prize_wheel','trivia_wheel_item_'||p_score_id::text,
            jsonb_build_object('score_id',p_score_id,'prize_id',v_prize_id));
    END IF;
    RETURN jsonb_build_object('success',true,'deduped',false,'prize_id',v_prize_id,
        'prize_type',v_type,'prize_amount',v_amount,'multiplier',v_mult,'credit',v_credit);
END;
$$;


ALTER FUNCTION public.fn_trivia_prize_wheel_spin(p_score_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_trivia_prize_wheel_spin(p_score_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_trivia_prize_wheel_spin(p_score_id uuid) IS 'Phase 80 — the prize wheel''s authority. Verifies the caller owns a recent PERFECT trivia_scores row, rolls the weighted prize server-side, applies the streak multiplier read from trivia_streaks, credits diamonds (or inventory) atomically and returns { prize_id, prize_amount } for PrizeWheel.jsx''s prizeId / prizeAmount props. One spin per score row, enforced by UNIQUE(score_id); a retry replays the same prize.';


--
-- Name: fn_trivia_pvp_match_sync_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trivia_pvp_match_sync_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.player1_score IS NOT NULL AND NEW.challenger_score IS NOT NULL
           AND NEW.player1_score IS DISTINCT FROM NEW.challenger_score THEN
            RAISE EXCEPTION 'conflicting player-1 score aliases';
        END IF;
        IF NEW.player2_score IS NOT NULL AND NEW.opponent_score IS NOT NULL
           AND NEW.player2_score IS DISTINCT FROM NEW.opponent_score THEN
            RAISE EXCEPTION 'conflicting player-2 score aliases';
        END IF;
        NEW.player1_score    := COALESCE(NEW.player1_score, NEW.challenger_score);
        NEW.challenger_score := COALESCE(NEW.challenger_score, NEW.player1_score);
        NEW.player2_score    := COALESCE(NEW.player2_score, NEW.opponent_score);
        NEW.opponent_score   := COALESCE(NEW.opponent_score, NEW.player2_score);
        RETURN NEW;
    END IF;

    IF NEW.player1_score IS DISTINCT FROM OLD.player1_score
       AND NEW.challenger_score IS DISTINCT FROM OLD.challenger_score
       AND NEW.player1_score IS DISTINCT FROM NEW.challenger_score THEN
        RAISE EXCEPTION 'conflicting player-1 score alias update';
    END IF;
    IF NEW.player2_score IS DISTINCT FROM OLD.player2_score
       AND NEW.opponent_score IS DISTINCT FROM OLD.opponent_score
       AND NEW.player2_score IS DISTINCT FROM NEW.opponent_score THEN
        RAISE EXCEPTION 'conflicting player-2 score alias update';
    END IF;

    IF NEW.player1_score IS DISTINCT FROM OLD.player1_score THEN
        NEW.challenger_score := NEW.player1_score;
    ELSIF NEW.challenger_score IS DISTINCT FROM OLD.challenger_score THEN
        NEW.player1_score := NEW.challenger_score;
    END IF;
    IF NEW.player2_score IS DISTINCT FROM OLD.player2_score THEN
        NEW.opponent_score := NEW.player2_score;
    ELSIF NEW.opponent_score IS DISTINCT FROM OLD.opponent_score THEN
        NEW.player2_score := NEW.opponent_score;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_trivia_pvp_match_sync_columns() OWNER TO postgres;

--
-- Name: fn_trivia_pvp_record_result(text, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trivia_pvp_record_result(p_outcome text, p_diamonds integer DEFAULT 0, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_user uuid;
    v_d    integer := LEAST(GREATEST(COALESCE(p_diamonds, 0), 0), 100000);
    v_row  public.trivia_pvp_stats%ROWTYPE;
BEGIN
    IF (SELECT auth.role()) = 'service_role' THEN
        v_user := COALESCE(p_user_id, (SELECT auth.uid()));
    ELSE
        -- A client may only record ITS OWN result, whatever it passes.
        v_user := (SELECT auth.uid());
    END IF;
    IF v_user IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF p_outcome IS NULL OR p_outcome NOT IN ('win', 'loss', 'tie') THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_outcome');
    END IF;

    INSERT INTO public.trivia_pvp_stats AS s (
        user_id, wins, losses, ties, win_streak, best_streak,
        total_diamonds_won, total_diamonds_lost, updated_at
    )
    VALUES (
        v_user,
        CASE WHEN p_outcome = 'win'  THEN 1 ELSE 0 END,
        CASE WHEN p_outcome = 'loss' THEN 1 ELSE 0 END,
        CASE WHEN p_outcome = 'tie'  THEN 1 ELSE 0 END,
        CASE WHEN p_outcome = 'win'  THEN 1 ELSE 0 END,
        CASE WHEN p_outcome = 'win'  THEN 1 ELSE 0 END,
        CASE WHEN p_outcome = 'win'  THEN v_d ELSE 0 END,
        CASE WHEN p_outcome = 'loss' THEN v_d ELSE 0 END,
        now()
    )
    ON CONFLICT (user_id) DO UPDATE SET
        wins       = s.wins   + CASE WHEN p_outcome = 'win'  THEN 1 ELSE 0 END,
        losses     = s.losses + CASE WHEN p_outcome = 'loss' THEN 1 ELSE 0 END,
        ties       = s.ties   + CASE WHEN p_outcome = 'tie'  THEN 1 ELSE 0 END,
        -- A tie continues the streak; a loss resets it.
        win_streak = CASE
                        WHEN p_outcome = 'win'  THEN s.win_streak + 1
                        WHEN p_outcome = 'loss' THEN 0
                        ELSE s.win_streak
                     END,
        best_streak = GREATEST(
                        s.best_streak,
                        CASE WHEN p_outcome = 'win' THEN s.win_streak + 1 ELSE s.win_streak END
                      ),
        total_diamonds_won  = s.total_diamonds_won  + CASE WHEN p_outcome = 'win'  THEN v_d ELSE 0 END,
        total_diamonds_lost = s.total_diamonds_lost + CASE WHEN p_outcome = 'loss' THEN v_d ELSE 0 END,
        updated_at = now()
    RETURNING * INTO v_row;

    RETURN jsonb_build_object(
        'success', true,
        'wins', v_row.wins, 'losses', v_row.losses, 'ties', v_row.ties,
        'win_streak', v_row.win_streak, 'best_streak', v_row.best_streak
    );
END;
$$;


ALTER FUNCTION public.fn_trivia_pvp_record_result(p_outcome text, p_diamonds integer, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_trivia_pvp_record_result(p_outcome text, p_diamonds integer, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_trivia_pvp_record_result(p_outcome text, p_diamonds integer, p_user_id uuid) IS 'Phase 80 — atomic, non-forgeable PvP stat increment. Replaces the read-then-upsert in pages/hub/trivia/pvp.js updatePvpStats(): call it as supabase.rpc(''fn_trivia_pvp_record_result'', { p_outcome, p_diamonds }). A client cannot choose the magnitude of the change, only report one match.';


--
-- Name: fn_trivia_round_set_matchup_score(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trivia_round_set_matchup_score(p_round_id uuid, p_user_id uuid, p_score integer, p_time integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_matchups  jsonb;
    v_status    text;
    v_len       integer;
    v_idx       integer := -1;
    v_m         jsonb;
    v_is_p1     boolean;
    v_my_score  text;
    v_my_time   text;
    v_opp_score_key text;
    v_opp_time_key  text;
    v_opp_id_key    text;
    v_opp_id    text;
    v_opp_score numeric;
    v_opp_time  numeric;
    v_winner    text;
    v_decided   boolean := false;
    v_score     integer := GREATEST(COALESCE(p_score, 0), 0);
    v_time      integer := GREATEST(COALESCE(p_time, 0), 0);
    i           integer;
BEGIN
    -- Only the server may write a score. Every caller is /api/trivia/
    -- tournament-submit-round, which holds the service-role key.
    IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'service_role required';
    END IF;
    IF p_round_id IS NULL OR p_user_id IS NULL THEN
        RETURN jsonb_build_object('applied', false, 'error', 'bad_arguments', 'matchup', NULL);
    END IF;

    -- ── THE LOCK ────────────────────────────────────────────────────────
    SELECT r.matchups, r.status
      INTO v_matchups, v_status
      FROM public.trivia_tournament_rounds r
     WHERE r.id = p_round_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('applied', false, 'error', 'round_not_found', 'matchup', NULL);
    END IF;
    IF v_status IS DISTINCT FROM 'active' THEN
        RETURN jsonb_build_object('applied', false, 'error', 'round_not_active', 'matchup', NULL);
    END IF;
    IF v_matchups IS NULL OR jsonb_typeof(v_matchups) <> 'array' THEN
        RETURN jsonb_build_object('applied', false, 'error', 'no_matchups', 'matchup', NULL);
    END IF;

    -- ── LOCATE THIS PLAYER'S MATCHUP ────────────────────────────────────
    v_len := jsonb_array_length(v_matchups);
    FOR i IN 0 .. GREATEST(v_len - 1, 0) LOOP
        v_m := v_matchups -> i;
        IF v_m IS NOT NULL
           AND ( (v_m ->> 'player1_id') = p_user_id::text
              OR (v_m ->> 'player2_id') = p_user_id::text ) THEN
            v_idx := i;
            EXIT;
        END IF;
    END LOOP;

    IF v_idx < 0 THEN
        RETURN jsonb_build_object('applied', false, 'error', 'not_in_round', 'matchup', NULL);
    END IF;
    IF COALESCE((v_m ->> 'is_bye')::boolean, false) THEN
        RETURN jsonb_build_object('applied', false, 'error', 'bye_round', 'matchup', v_m);
    END IF;

    v_is_p1 := ((v_m ->> 'player1_id') = p_user_id::text);
    IF v_is_p1 THEN
        v_my_score := 'player1_score'; v_my_time := 'player1_time';
        v_opp_score_key := 'player2_score'; v_opp_time_key := 'player2_time'; v_opp_id_key := 'player2_id';
    ELSE
        v_my_score := 'player2_score'; v_my_time := 'player2_time';
        v_opp_score_key := 'player1_score'; v_opp_time_key := 'player1_time'; v_opp_id_key := 'player1_id';
    END IF;

    -- ── ALREADY CLAIMED? (idempotent resubmit) ──────────────────────────
    -- A missing key yields SQL NULL; an explicit JSON null yields 'null'.
    -- Both mean "not yet played"; anything else means the slot is filled.
    IF COALESCE(jsonb_typeof(v_m -> v_my_score), 'null') <> 'null' THEN
        RETURN jsonb_build_object('applied', false, 'error', 'already_submitted', 'matchup', v_m);
    END IF;

    -- ── WRITE THE SLOT ──────────────────────────────────────────────────
    v_m := jsonb_set(v_m, ARRAY[v_my_score], to_jsonb(v_score), true);
    v_m := jsonb_set(v_m, ARRAY[v_my_time],  to_jsonb(v_time),  true);

    -- ── DECIDE THE WINNER WHEN BOTH SCORES ARE IN ───────────────────────
    v_opp_id := v_m ->> v_opp_id_key;
    IF v_opp_id IS NOT NULL
       AND COALESCE(jsonb_typeof(v_m -> v_opp_score_key), 'null') <> 'null' THEN

        v_opp_score := (v_m ->> v_opp_score_key)::numeric;
        BEGIN
            v_opp_time := (v_m ->> v_opp_time_key)::numeric;
        EXCEPTION WHEN others THEN
            v_opp_time := NULL;
        END;

        IF v_score > v_opp_score THEN
            v_winner := p_user_id::text;
        ELSIF v_opp_score > v_score THEN
            v_winner := v_opp_id;
        ELSIF v_opp_time IS NOT NULL AND v_time <> v_opp_time THEN
            v_winner := CASE WHEN v_time < v_opp_time THEN p_user_id::text ELSE v_opp_id END;
        ELSE
            -- Exact tie. Deterministic AND slot-independent: the ids are sorted
            -- first, so the outcome cannot depend on which slot a player landed
            -- in (always awarding player2 was a real, diamond-bearing bias).
            v_winner := CASE
                WHEN (get_byte(
                        decode(md5(LEAST(p_user_id::text, v_opp_id) || '|' ||
                                   GREATEST(p_user_id::text, v_opp_id) || '|' ||
                                   p_round_id::text), 'hex'), 0) % 2) = 0
                THEN LEAST(p_user_id::text, v_opp_id)
                ELSE GREATEST(p_user_id::text, v_opp_id)
            END;
        END IF;

        v_m := jsonb_set(v_m, ARRAY['winner_id'], to_jsonb(v_winner), true);
        v_decided := true;
    END IF;

    UPDATE public.trivia_tournament_rounds
       SET matchups = jsonb_set(v_matchups, ARRAY[v_idx::text], v_m, true)
     WHERE id = p_round_id;

    RETURN jsonb_build_object(
        'applied',        true,
        'matchup',        v_m,
        'match_index',    v_idx,
        'winner_decided', v_decided
    );
END;
$$;


ALTER FUNCTION public.fn_trivia_round_set_matchup_score(p_round_id uuid, p_user_id uuid, p_score integer, p_time integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_trivia_round_set_matchup_score(p_round_id uuid, p_user_id uuid, p_score integer, p_time integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_trivia_round_set_matchup_score(p_round_id uuid, p_user_id uuid, p_score integer, p_time integer) IS 'Phase 80 — race-free tournament round submission. Locks the round row (SELECT ... FOR UPDATE), patches exactly one element of the matchups JSONB array, and derives winner_id when both slots are filled. Returns {applied, matchup, match_index, winner_decided}; applied=false with a matchup means the slot was already claimed (idempotent resubmit). Consumed by pages/api/trivia/tournament-submit-round.js.';


--
-- Name: fn_trivia_round_submit_verified_v3(uuid, uuid, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trivia_round_submit_verified_v3(p_round_id uuid, p_user_id uuid, p_score integer, p_time integer, p_results jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_claim jsonb;
    v_stats jsonb;
    v_entry_score integer;
    v_entry_time integer;
BEGIN
    IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'service_role required';
    END IF;

    SELECT public.fn_trivia_round_set_matchup_score(
        p_round_id, p_user_id, p_score, p_time
    ) INTO v_claim;

    IF COALESCE((v_claim->>'applied')::boolean, false) IS NOT TRUE THEN
        RETURN v_claim;
    END IF;

    SELECT public.record_trivia_tournament_question_results_v3(
        p_user_id, p_round_id, p_results
    ) INTO v_stats;
    IF COALESCE((v_stats->>'success')::boolean, false) IS NOT TRUE THEN
        RAISE EXCEPTION 'tournament stats rejected: %',
            COALESCE(v_stats->>'error', 'unknown');
    END IF;

    UPDATE public.trivia_tournament_entries AS e
       SET score = COALESCE(e.score, 0) + GREATEST(COALESCE(p_score, 0), 0),
           time_spent = COALESCE(e.time_spent, 0) + GREATEST(COALESCE(p_time, 0), 0),
           completed_at = now()
      FROM public.trivia_tournament_rounds AS r
     WHERE r.id = p_round_id
       AND e.tournament_id = r.tournament_id
       AND e.user_id = p_user_id
    RETURNING e.score, e.time_spent INTO v_entry_score, v_entry_time;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'tournament entry missing for round submission';
    END IF;

    RETURN v_claim || jsonb_build_object(
        'stats', v_stats,
        'entry_score', v_entry_score,
        'entry_time', v_entry_time
    );
END;
$$;


ALTER FUNCTION public.fn_trivia_round_submit_verified_v3(p_round_id uuid, p_user_id uuid, p_score integer, p_time integer, p_results jsonb) OWNER TO postgres;

--
-- Name: fn_trivia_tournament_add_entry_score(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trivia_tournament_add_entry_score(p_entry_id uuid, p_score integer, p_time integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_score integer;
    v_time  integer;
BEGIN
    IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'service_role required';
    END IF;

    UPDATE public.trivia_tournament_entries
       SET score        = COALESCE(score, 0)      + GREATEST(COALESCE(p_score, 0), 0),
           time_spent   = COALESCE(time_spent, 0) + GREATEST(COALESCE(p_time, 0), 0),
           completed_at = now()
     WHERE id = p_entry_id
     RETURNING score, time_spent INTO v_score, v_time;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'entry_not_found');
    END IF;

    RETURN jsonb_build_object('success', true, 'score', v_score, 'time_spent', v_time);
END;
$$;


ALTER FUNCTION public.fn_trivia_tournament_add_entry_score(p_entry_id uuid, p_score integer, p_time integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_trivia_tournament_add_entry_score(p_entry_id uuid, p_score integer, p_time integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_trivia_tournament_add_entry_score(p_entry_id uuid, p_score integer, p_time integer) IS 'Phase 80 — atomic cumulative score/time accumulation for a tournament entry. Replaces the read-modify-write fallback in pages/api/trivia/tournament-submit-round.js addEntryTotals().';


--
-- Name: fn_trivia_tournament_increment_prize_pool(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trivia_tournament_increment_prize_pool(p_tournament_id uuid, p_amount integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_new_pool integer;
BEGIN
    -- Service-role only (callers are server-side handlers using service role)
    IF (SELECT auth.role()) <> 'service_role' THEN
        RAISE EXCEPTION 'service_role required';
    END IF;
    IF p_amount IS NULL OR p_amount < 0 THEN
        RAISE EXCEPTION 'invalid amount';
    END IF;

    UPDATE public.trivia_tournaments
       SET prize_pool = COALESCE(prize_pool, 0) + p_amount
     WHERE id = p_tournament_id
     RETURNING prize_pool INTO v_new_pool;

    IF v_new_pool IS NULL THEN
        RAISE EXCEPTION 'tournament_not_found';
    END IF;

    RETURN v_new_pool;
END;
$$;


ALTER FUNCTION public.fn_trivia_tournament_increment_prize_pool(p_tournament_id uuid, p_amount integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_trivia_tournament_increment_prize_pool(p_tournament_id uuid, p_amount integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_trivia_tournament_increment_prize_pool(p_tournament_id uuid, p_amount integer) IS 'Atomic prize-pool increment for trivia tournaments. Phase 47 — closes the read-modify-write race in /api/trivia/tournament-enter.';


--
-- Name: fn_trivia_tournament_payout(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trivia_tournament_payout(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_status   text;
    v_pool     integer;
    v_name     text;
    v_n        integer;
    v_pcts     integer[];
    v_paid     integer := 0;
    v_rows     jsonb   := '[]'::jsonb;
    v_amount   integer;
    v_remain   integer;
    r          record;
    v_res      jsonb;
    v_has_rpc  boolean;
BEGIN
    IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'service_role required';
    END IF;

    SELECT t.status, COALESCE(t.prize_pool, 0), t.name
      INTO v_status, v_pool, v_name
      FROM public.trivia_tournaments t
     WHERE t.id = p_tournament_id
       FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'tournament_not_found');
    END IF;
    IF v_status NOT IN ('active', 'complete', 'completed') THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_payable', 'status', v_status);
    END IF;

    -- TRUE idempotency. A settled tournament has its pool drained (either by
    -- this function or by finalizeTournament() in tournament-lifecycle.js) and
    -- its standings recorded. Re-running from here would recompute every payout
    -- against a ZERO pool and then overwrite entries.rank / entries.payout and
    -- trivia_tournaments.winners with all-zero rows - destroying the settlement
    -- record while the diamonds stay (correctly) deduped by reference_id.
    -- Report the recorded standings instead of rewriting them.
    IF v_status IN ('complete', 'completed') THEN
        SELECT COALESCE(t.winners, '[]'::jsonb) INTO v_rows
          FROM public.trivia_tournaments t WHERE t.id = p_tournament_id;
        RETURN jsonb_build_object(
            'success', true, 'deduped', true, 'status', v_status,
            'prize_pool', v_pool, 'paid', 0, 'standings', v_rows
        );
    END IF;

    SELECT COUNT(*)::int INTO v_n
      FROM public.trivia_tournament_entries e WHERE e.tournament_id = p_tournament_id;
    IF v_n = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_entrants');
    END IF;

    -- Must mirror prizeSchedule() in pages/api/trivia/tournament-lifecycle.js.
    v_pcts := CASE
        WHEN v_n <= 2  THEN ARRAY[100]
        WHEN v_n <= 3  THEN ARRAY[70,30]
        WHEN v_n <= 7  THEN ARRAY[55,30,15]
        WHEN v_n <= 15 THEN ARRAY[45,25,16,14]
        WHEN v_n <= 31 THEN ARRAY[38,22,14,10,9,7]
        ELSE                ARRAY[32,20,13,10,8,7,5,5]
    END;

    v_has_rpc := EXISTS (
        SELECT 1 FROM pg_proc p
          JOIN pg_namespace n ON n.oid = p.pronamespace
         WHERE n.nspname = 'public' AND p.proname = 'add_diamonds_to_balance'
    );

    v_remain := v_pool;
    FOR r IN
        SELECT e.id, e.user_id,
               row_number() OVER (
                   ORDER BY COALESCE(e.eliminated_round, 2147483647) DESC,
                            COALESCE(e.score, 0) DESC,
                            COALESCE(e.time_spent, 0) ASC,
                            e.user_id
               )::int AS rnk
          FROM public.trivia_tournament_entries e
         WHERE e.tournament_id = p_tournament_id
    LOOP
        v_amount := CASE
            WHEN r.rnk <= array_length(v_pcts, 1)
            THEN (v_pool * v_pcts[r.rnk]) / 100
            ELSE 0
        END;
        -- Any rounding remainder goes to first place so the pool balances
        -- exactly: never over-pays, never leaks diamonds.
        IF r.rnk = 1 THEN
            v_amount := v_amount + (v_pool - (
                SELECT COALESCE(SUM((v_pool * p) / 100), 0)
                  FROM unnest(v_pcts) AS p
            ));
        END IF;

        UPDATE public.trivia_tournament_entries
           SET rank = r.rnk, payout = v_amount
         WHERE id = r.id;

        IF v_amount > 0 AND v_has_rpc THEN
            EXECUTE 'SELECT public.add_diamonds_to_balance($1,$2,$3,$4,$5)'
               INTO v_res
              USING r.user_id, v_amount, 'tournament_prize',
                    'Tournament prize - ' || COALESCE(v_name, 'trivia tournament') || ' (rank ' || r.rnk || ')',
                    'trivia_tourn_payout_' || p_tournament_id::text || '_' || r.user_id::text;
            IF COALESCE((v_res ->> 'success')::boolean, false) THEN
                v_paid := v_paid + v_amount;
            END IF;
        END IF;

        v_rows := v_rows || jsonb_build_object('rank', r.rnk, 'user_id', r.user_id, 'payout', v_amount);
    END LOOP;

    UPDATE public.trivia_tournaments
       SET status       = 'completed',
           completed_at = COALESCE(completed_at, now()),
           winners      = v_rows,
           prize_pool   = 0
     WHERE id = p_tournament_id;

    RETURN jsonb_build_object(
        'success', true, 'entrants', v_n, 'prize_pool', v_pool,
        'paid', v_paid, 'standings', v_rows
    );
END;
$_$;


ALTER FUNCTION public.fn_trivia_tournament_payout(p_tournament_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_trivia_tournament_payout(p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_trivia_tournament_payout(p_tournament_id uuid) IS 'Phase 80 — single-transaction tournament settlement: locks the tournament, ranks entries (deepest run, then score DESC, then time ASC), writes rank/payout, credits winners through add_diamonds_to_balance with a stable reference_id (so a re-run cannot double-pay), zeroes prize_pool and marks the tournament completed. Ops safety net for pages/api/trivia/tournament-lifecycle.js finalizeTournament().';


--
-- Name: fn_trivia_tournament_sync_player_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trivia_tournament_sync_player_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE public.trivia_tournaments
           SET current_players = COALESCE(current_players, 0) + 1
         WHERE id = NEW.tournament_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE public.trivia_tournaments
           SET current_players = GREATEST(COALESCE(current_players, 1) - 1, 0)
         WHERE id = OLD.tournament_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_trivia_tournament_sync_player_count() OWNER TO postgres;

--
-- Name: fn_truly_unused_indexes(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_truly_unused_indexes(p_min_days integer DEFAULT 7) RETURNS TABLE(relname text, indexrelname text, index_bytes bigint, pretty_size text, scans_in_window bigint, window_days numeric, epochs_observed integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  WITH per_epoch AS (
    SELECT s.schemaname,
           s.relname       AS tbl,
           s.indexrelname  AS idx,
           s.postmaster_start,
           max(s.idx_scan) - min(s.idx_scan)                       AS scans,
           extract(epoch FROM (max(s.taken_at) - min(s.taken_at))) AS span_seconds,
           max(s.index_bytes)                                      AS bytes
      FROM public.index_usage_snapshots s
     GROUP BY s.schemaname, s.relname, s.indexrelname, s.postmaster_start
  ),
  totalled AS (
    SELECT p.tbl,
           p.idx,
           max(p.bytes)::bigint          AS bytes,
           sum(p.scans)::bigint          AS total_scans,
           sum(p.span_seconds) / 86400.0 AS observed_days,
           count(*)::integer             AS epochs
      FROM per_epoch p
     GROUP BY p.tbl, p.idx
  )
  SELECT t.tbl, t.idx, t.bytes, pg_size_pretty(t.bytes),
         t.total_scans, round(t.observed_days, 2)::numeric, t.epochs
    FROM totalled t
   WHERE t.total_scans = 0
     AND t.observed_days >= p_min_days
   ORDER BY t.bytes DESC;
END;
$$;


ALTER FUNCTION public.fn_truly_unused_indexes(p_min_days integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_truly_unused_indexes(p_min_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_truly_unused_indexes(p_min_days integer) IS 'Indexes with ZERO scans across every observed postmaster epoch, where observed time totals at least p_min_days. Sums per-epoch deltas because a restart resets idx_scan.';


--
-- Name: fn_try_consume_home_rate_limit(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_try_consume_home_rate_limit(p_actor_id uuid, p_endpoint text, p_max_requests integer, p_window_minutes integer DEFAULT 60) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row RECORD;
  v_now timestamptz := now();
  v_window_start_cutoff timestamptz := v_now - (p_window_minutes || ' minutes')::interval;
  v_lock_key bigint;
BEGIN
  IF p_actor_id IS NULL OR p_endpoint IS NULL THEN
    RETURN true;
  END IF;

  -- Advisory lock serializes concurrent consumes for the same (actor, endpoint)
  -- Key = hash64( actor_uuid_bytes || endpoint )
  v_lock_key := hashtextextended(p_actor_id::text || '|' || p_endpoint, 0);
  PERFORM pg_advisory_xact_lock(v_lock_key);

  SELECT * INTO v_row
  FROM commander_rate_limits
  WHERE identifier = p_actor_id::text
    AND identifier_type = 'user'
    AND endpoint = p_endpoint
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO commander_rate_limits (
      identifier, identifier_type, endpoint,
      request_count, window_start, window_minutes, max_requests,
      last_request_at
    ) VALUES (
      p_actor_id::text, 'user', p_endpoint,
      1, v_now, p_window_minutes, p_max_requests,
      v_now
    );
    RETURN true;
  END IF;

  -- If window has rolled over, reset
  IF v_row.window_start < v_window_start_cutoff THEN
    UPDATE commander_rate_limits
       SET request_count = 1,
           window_start  = v_now,
           window_minutes = p_window_minutes,
           max_requests  = p_max_requests,
           last_request_at = v_now,
           is_blocked = false,
           blocked_until = NULL,
           block_reason = NULL
     WHERE id = v_row.id;
    RETURN true;
  END IF;

  -- Still within window - check remaining quota
  IF v_row.request_count < p_max_requests THEN
    UPDATE commander_rate_limits
       SET request_count = v_row.request_count + 1,
           last_request_at = v_now
     WHERE id = v_row.id;
    RETURN true;
  END IF;

  -- Quota exhausted
  UPDATE commander_rate_limits
     SET is_blocked = true,
         blocked_until = v_row.window_start + (p_window_minutes || ' minutes')::interval,
         block_reason = 'Quota exhausted for endpoint ' || p_endpoint
   WHERE id = v_row.id;
  RETURN false;
END;
$$;


ALTER FUNCTION public.fn_try_consume_home_rate_limit(p_actor_id uuid, p_endpoint text, p_max_requests integer, p_window_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_try_consume_home_rate_limit(p_actor_id uuid, p_endpoint text, p_max_requests integer, p_window_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_try_consume_home_rate_limit(p_actor_id uuid, p_endpoint text, p_max_requests integer, p_window_minutes integer) IS 'Pass 46.1: Atomic check-and-increment rate limiter backed by commander_rate_limits. Returns true if the actor still has quota for the endpoint in the current window (and consumes one), false if exhausted. Use for RPCs with fan-out cost (broadcasts, invites).';


--
-- Name: fn_try_cron_lock(text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_try_cron_lock(p_lock_name text, p_ttl_seconds integer DEFAULT 300, p_owner_id text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acquired boolean := false;
BEGIN
  IF p_lock_name IS NULL OR length(p_lock_name) = 0 THEN
    RETURN false;
  END IF;

  -- Try to claim. Either we INSERT a new row (success), or we
  -- UPDATE-claim if the existing one is past its TTL.
  WITH ins AS (
    INSERT INTO public.cron_locks AS cl (lock_name, acquired_at, expires_at, owner_id)
    VALUES (
      p_lock_name,
      now(),
      now() + make_interval(secs => GREATEST(1, COALESCE(p_ttl_seconds, 300))),
      p_owner_id
    )
    ON CONFLICT (lock_name) DO UPDATE
      SET acquired_at = now(),
          expires_at = now() + make_interval(secs => GREATEST(1, COALESCE(p_ttl_seconds, 300))),
          owner_id = p_owner_id
      WHERE cl.expires_at < now()
    RETURNING 1
  )
  SELECT EXISTS(SELECT 1 FROM ins) INTO v_acquired;

  RETURN v_acquired;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_try_cron_lock failed (%): % %', p_lock_name, SQLERRM, SQLSTATE;
  RETURN false;
END;
$$;


ALTER FUNCTION public.fn_try_cron_lock(p_lock_name text, p_ttl_seconds integer, p_owner_id text) OWNER TO postgres;

--
-- Name: fn_unaccounted_seat_exits(interval, interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_unaccounted_seat_exits(p_since interval DEFAULT '7 days'::interval, p_grace interval DEFAULT '00:10:00'::interval) RETURNS TABLE(exit_id bigint, occurred_at timestamp with time zone, user_id uuid, table_id uuid, club_id uuid, stack numeric, exit_kind text, db_role text, app_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- MATERIALIZED on purpose. Inlined, the planner is free to re-run this once
  -- per candidate row, which is the sequential scan this migration exists to
  -- delete. There are ~1,040 rows in here; collecting them once is the point.
  with corrected as materialized (
    select distinct
           nullif(substring(wt.description from 'Correction: seat exit ([0-9]+)'), '')::bigint as exit_id
      from public.wallet_transactions wt
     where wt.type = 'credit'
       and wt.description like 'Correction: seat exit %'
  )
  SELECT e.id, e.occurred_at, e.user_id, e.table_id, e.club_id,
         e.stack, e.exit_kind, e.db_role, e.app_name
  FROM public.ca_seat_stack_exits e
  WHERE e.occurred_at >= now() - p_since
    AND e.occurred_at <= now() - p_grace
    AND NOT EXISTS (
      SELECT 1 FROM public.tables t
       WHERE t.id = e.table_id AND t.tournament_id IS NOT NULL
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.wallet_transactions wt
       WHERE wt.user_id = e.user_id
         AND wt.type = 'credit'
         AND wt.created_at BETWEEN e.occurred_at - GREATEST(p_grace, interval '15 minutes')
                               AND e.occurred_at + p_grace
         AND wt.amount >= e.stack - 0.01
    )
    -- Was an unindexable per-row ILIKE on a concatenated prefix. Same
    -- intention, asked once, and it cannot forgive exit 5 for a correction
    -- written to exit 51.
    AND NOT EXISTS (
      SELECT 1 FROM corrected c WHERE c.exit_id = e.id
    )
  ORDER BY e.occurred_at DESC;
$$;


ALTER FUNCTION public.fn_unaccounted_seat_exits(p_since interval, p_grace interval) OWNER TO postgres;

--
-- Name: fn_uncollected_entry_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_uncollected_entry_check(p_since_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  /* 48h ceiling: double what the engine asks for (hourly, 24h). */
  v_hours   integer := LEAST(GREATEST(COALESCE(p_since_hours, 24), 1), 48);
  v_since   timestamptz;

  /* THE DAY THE EVIDENCE STARTS. log_wallet_transaction was wired into the
     tournament register path on 2026-08-19; the first `tournament_buyin` row
     in wallet_transactions is 2026-08-19 and there are none before it. An
     absent debit dated earlier than this proves the LOGGER was absent, not
     the payment - 22,981 perfectly healthy seats sit behind that date. The
     48-hour cap already makes this unreachable. It is asserted rather than
     assumed because caps get raised by people who did not read the comment. */
  c_evidence_start constant timestamptz := timestamptz '2026-08-19 00:00:00+00';

  /* ONE BUFFER, USED BY BOTH EVIDENCE CTEs, so they cannot drift apart. It
     absorbs clock skew and the edge of the window and nothing else: the wallet
     debit and the satellite award are each written in the SAME TRANSACTION as
     the seat they pay for, so neither can legitimately fall outside it.

     The awards CTE looked back a MONTH when this function first shipped, on
     the mistaken reasoning that a seat might be awarded long before its target
     event runs - which confuses the target's START with the seat's CREATION.
     rake_records has no index on `source`, so that clause walked the created_at
     index discarding 644,620 rows to find 23: 231,267 shared buffers for the
     whole check against 90,202 with this. Measured and corrected 2026-09-02.
     Verified on all 23 awards: rake_records.created_at equals
     tournament_players.registered_at exactly, worst gap 0.000000 seconds. */
  c_evidence_buffer constant interval := interval '6 hours';

  v_seats   bigint  := 0;
  v_bad     bigint  := 0;
  v_events  bigint  := 0;
  v_chips   numeric := 0;
  v_alerts  integer := 0;
  v_worst   jsonb   := '[]'::jsonb;
BEGIN
  v_since := now() - make_interval(hours => v_hours);

  IF v_since < c_evidence_start THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'window_predates_the_evidence',
      'detail', 'wallet_transactions has only carried tournament_buyin since '
                || c_evidence_start::text || '; an absent debit before that date '
                || 'means the logger did not exist, not that nobody paid',
      'since_hours', v_hours);
  END IF;

  WITH seats AS (
    SELECT tp.tournament_id, tp.user_id,
           COALESCE(tp.is_satellite_qualifier, false) AS sat_flag,
           tp.source_satellite_id,
           t.name,
           round(COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0), 2) AS charge,
           /* A LATER DAY IS day_number OR parent_tournament_id, AND NOTHING
              ELSE. This used to also read the union flag, which is set from
              schedule.union_id and means UNION event, not multi-day - 815 live
              rows carry it. is_multi_day and total_days paint the lobby badge;
              these two are what a Day 2 would actually BE. */
           (COALESCE(t.day_number, 1) > 1 OR t.parent_tournament_id IS NOT NULL) AS later_day
      FROM public.tournament_players tp
      JOIN public.tournaments t ON t.id = tp.tournament_id
     WHERE tp.registered_at >= v_since
       -- EXEMPTION 4: a freeroll owes no entry.
       AND COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0) > 0
  ),
  -- EXEMPTION 1: the ordinary door, human or horse. Written in the same
  -- transaction as the seat; the buffer only absorbs the edge of the window.
  funded AS (
    SELECT DISTINCT w.related_entity_id AS tournament_id, w.user_id
      FROM public.wallet_transactions w
     WHERE w.related_entity_id IS NOT NULL
       AND w.category = 'tournament_buyin'
       AND w.type = 'debit'
       AND w.created_at >= v_since - c_evidence_buffer
  ),
  -- EXEMPTION 2: the seat IS the prize. The rake row is the durable witness
  -- that fn_award_satellite_seat ran; the two roster columns are the witness
  -- on the seat itself, and either one alone is enough. All three are kept
  -- because each has a birthday: is_satellite_qualifier has only been written
  -- since 2026-08-27 and source_satellite_id since 2026-08-30, while a
  -- zero-fee target writes no rake row at all.
  --
  -- SAME BUFFER AS `funded`, AND FOR THE SAME REASON. The award cannot fall
  -- outside the seat's own window because it is the statement that creates
  -- the seat.
  awards AS (
    SELECT DISTINCT r.tournament_id, (r.metadata->>'user_id')::uuid AS user_id
      FROM public.rake_records r
     WHERE r.source = 'fn_award_satellite_seat'
       AND r.created_at >= v_since - c_evidence_buffer
       AND r.metadata ? 'user_id'
  ),
  bad AS (
    SELECT s.*
      FROM seats s
      LEFT JOIN funded f ON f.tournament_id = s.tournament_id AND f.user_id = s.user_id
      LEFT JOIN awards a ON a.tournament_id = s.tournament_id AND a.user_id = s.user_id
     WHERE f.user_id IS NULL
       AND a.user_id IS NULL
       AND NOT s.sat_flag
       AND s.source_satellite_id IS NULL
       /* EXEMPTION 3: a day past the first is bought by surviving day one.
          UNREACHABLE BY CONSTRUCTION as of 20260902052302, which made
          trg_tournaments_refuse_unbuilt_multi_day refuse day_number and
          parent_tournament_id along with the five other multi-day columns. It
          is kept because it is the CORRECT rule for the day Day 2 is built,
          and deleting it would leave whoever builds it needing to remember.
          Delete this note in that commit; the exemption becomes live. */
       AND NOT s.later_day
  )
  SELECT (SELECT count(*) FROM seats),
         (SELECT count(*) FROM bad),
         (SELECT count(DISTINCT tournament_id) FROM bad),
         (SELECT COALESCE(round(sum(charge), 2), 0) FROM bad),
         (SELECT COALESCE(jsonb_agg(x), '[]'::jsonb) FROM (
            SELECT jsonb_build_object('tournament_id', tournament_id, 'name', max(name),
                                      'seats', count(*), 'chips', round(sum(charge), 2)) AS x
              FROM bad GROUP BY tournament_id
             ORDER BY sum(charge) DESC LIMIT 10) y)
    INTO v_seats, v_bad, v_events, v_chips, v_worst;

  /* One OPEN alert for the condition, not one per seat. On the two days this
     actually happened a per-seat alert would have filed 464 rows and buried
     itself, which is the failure the dedupe key exists to stop. */
  IF v_bad > 0 THEN
    PERFORM public.fn_raise_server_financial_alert(
      'critical', 'fn_uncollected_entry_check',
      format('%s seat(s) across %s event(s) in the last %sh hold a place in a paid tournament with no auditable record that the entry was paid: %s chips of entry',
             v_bad, v_events, v_hours, v_chips),
      jsonb_build_object('kind', 'uncollected_entry', 'seats', v_bad,
        'events', v_events, 'chips', v_chips, 'since_hours', v_hours,
        'seats_checked', v_seats, 'worst', v_worst,
        'exempt', 'wallet debit, satellite seat award, day-2 advancement, freeroll',
        'detail', 'no money was moved by this check',
        'known_blind_spot', 'atomic_tournament_register debits club_members.chip_balance '
          || 'directly and writes no chip_transactions and no wallet_transactions row, so a '
          || 'seat it created would appear here despite the player having paid. It has had no '
          || 'caller since 2026-08-15 (fn_register_for_tournament replaced it) and it sits on '
          || 'the fn_union_law_check watch list, so retiring it belongs to that workstream.'),
      'uncollected_entry');
    v_alerts := v_alerts + 1;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'since_hours', v_hours,
    'seats_checked', v_seats,
    'uncollected_entries', v_bad,
    'events', v_events,
    'chips', v_chips,
    'worst', v_worst,
    -- NOT "alerts_raised": the dedupe path returns an existing row's id, so a
    -- standing condition reports itself every pass without a new row being
    -- written. This counts CONDITIONS.
    'conditions_alerted', v_alerts);
END;
$$;


ALTER FUNCTION public.fn_uncollected_entry_check(p_since_hours integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_uncollected_entry_check(p_since_hours integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_uncollected_entry_check(p_since_hours integer) IS 'Phase 2 of the MTT payout audit. Reports seats in paid events with no auditable record that the entry was paid. Exempts the four legitimate funding sources by name. Moves no money. Bounded at 48h and refuses any window predating 2026-08-19. The day-2 exemption reads day_number and parent_tournament_id only: the union flag means UNION event, not multi-day.';


--
-- Name: fn_undeclared_money_triggers(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_undeclared_money_triggers() RETURNS TABLE(table_name text, trigger_name text, function_name text, trigger_def text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT c.relname::text,
         t.tgname::text,
         p.proname::text,
         pg_get_triggerdef(t.oid)
  FROM pg_trigger t
  JOIN pg_class c ON c.oid = t.tgrelid
  JOIN pg_proc  p ON p.oid = t.tgfoid
  WHERE NOT t.tgisinternal
    AND c.relnamespace = 'public'::regnamespace
    AND c.relname IN ('table_seats','club_members','club_wallets','union_wallets',
                      'wallets','chip_ledger','tournaments','tournament_players',
                      'ca_settlements')
    AND NOT EXISTS (
      SELECT 1 FROM public.ca_declared_money_triggers d
      WHERE d.table_name = c.relname::text
        AND d.trigger_name = t.tgname::text
    )
  ORDER BY 1, 2
$$;


ALTER FUNCTION public.fn_undeclared_money_triggers() OWNER TO postgres;

--
-- Name: FUNCTION fn_undeclared_money_triggers(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_undeclared_money_triggers() IS 'Triggers live on a money or seat table with no row in ca_declared_money_triggers. Any result is an unreviewed schema change on a path that moves chips - which is how aaa_skip_noop_update broke 139,153 hand settlements on 2026-09-03 without anybody being told. Reports; never blocks.';


--
-- Name: fn_ungated_money_rpcs(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ungated_money_rpcs() RETURNS TABLE(fn text, args text, reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT p.proname::text,
         pg_get_function_identity_arguments(p.oid),
         'SECURITY DEFINER, executable by authenticated, writes to a money table, '
         || 'and never establishes who is asking'
    FROM pg_proc p
   WHERE p.pronamespace = 'public'::regnamespace
     AND p.prosecdef
     AND p.prokind = 'f'
     -- A trigger function has no API caller and no caller to authorize.
     AND p.prorettype <> 'pg_catalog.trigger'::regtype
     AND has_function_privilege('authenticated', p.oid, 'EXECUTE')
     AND p.prosrc ~* '(club_members|union_wallets|club_wallets|chip_treasury|wallet_transactions|chip_transactions|rake_records|spin_bonus_pools|bbj_)'
     AND p.prosrc ~* '(INSERT[[:space:]]+INTO|UPDATE[[:space:]]+|DELETE[[:space:]]+FROM)'
     AND p.prosrc !~* '(is_admin|is_club_admin|fn_has_club_role|fn_is_platform_admin|fn_is_union_overseer|fn_union_oversees_club|fn_actor_can_manage|fn_caller_is_engine|fn_is_horse_admin|auth\.uid)'
   ORDER BY 1;
$$;


ALTER FUNCTION public.fn_ungated_money_rpcs() OWNER TO postgres;

