--
-- Name: fn_union_age_invoices(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_age_invoices(p_union_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r            record;
  v_gate_open  boolean;
  v_d1 int; v_d2 int; v_d3 int;
  v_days       numeric;
  v_level_due  int;
  v_marked     int := 0;
  v_reminded   int := 0;
  v_escalated  int := 0;
  v_owed_total numeric := 0;
  v_union_name text;
  v_body       text;
  v_msg        jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_platform_admin())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  v_gate_open := public.fn_union_setting(p_union_id, 'weekly_invoices_enabled', 1) = 1;
  v_d1 := COALESCE(public.fn_union_setting(p_union_id, 'dunning_days_1', 0), 0)::int;
  v_d2 := COALESCE(public.fn_union_setting(p_union_id, 'dunning_days_2', 3), 3)::int;
  v_d3 := COALESCE(public.fn_union_setting(p_union_id, 'dunning_days_3', 7), 7)::int;
  SELECT u.name INTO v_union_name FROM unions u WHERE u.id = p_union_id;

  FOR r IN
    SELECT si.id, si.invoice_number, si.club_id, si.due_at, si.status,
           si.reminders_sent, si.breakdown->>'club_name' AS club_name,
           public.fn_union_invoice_outstanding(si.id) AS outstanding
      FROM settlement_invoices si
     WHERE si.invoice_type = 'union_weekly_squareup'
       AND (si.breakdown->>'union_id')::uuid = p_union_id
       AND si.status IN ('generated','overdue')     -- never a disputed, paid or cancelled one
       AND si.from_entity_type = 'club'             -- only what the CLUB owes
       AND si.due_at IS NOT NULL
       AND si.due_at < now()
     ORDER BY si.due_at
  LOOP
    CONTINUE WHEN COALESCE(r.outstanding, 0) <= 0.005;   -- credited to zero is settled

    v_owed_total := v_owed_total + r.outstanding;
    v_days := round(EXTRACT(epoch FROM (now() - r.due_at)) / 86400.0, 2);

    IF r.status <> 'overdue' THEN
      UPDATE settlement_invoices
         SET status = 'overdue', overdue_at = COALESCE(overdue_at, now()), updated_at = now()
       WHERE id = r.id;
      v_marked := v_marked + 1;
    END IF;

    -- Which reminder is owed. One message per run, never a burst.
    v_level_due := CASE WHEN v_days >= v_d3 THEN 3
                        WHEN v_days >= v_d2 THEN 2
                        WHEN v_days >= v_d1 THEN 1
                        ELSE 0 END;

    IF v_gate_open AND v_level_due > COALESCE(r.reminders_sent, 0) THEN
      IF v_level_due >= 3 THEN
        -- Past the last reminder: a person is told, not the club again.
        IF NOT EXISTS (SELECT 1 FROM financial_alerts a
                        WHERE a.source = 'fn_union_age_invoices' AND NOT a.resolved
                          AND a.context->>'invoice_id' = r.id::text) THEN
          INSERT INTO financial_alerts (source, severity, message, context)
          VALUES ('fn_union_age_invoices', 'critical',
                  COALESCE(r.club_name,'A club') || ' has not settled statement '
                  || COALESCE(r.invoice_number, r.id::text) || ': '
                  || to_char(r.outstanding, 'FM999,999,999,990.00') || ' is '
                  || v_days || ' days past due.',
                  jsonb_build_object('invoice_id', r.id, 'invoice_number', r.invoice_number,
                                     'union_id', p_union_id, 'club_id', r.club_id,
                                     'outstanding', r.outstanding, 'days_past_due', v_days));
          v_escalated := v_escalated + 1;
        END IF;
      END IF;

      v_body :=
        COALESCE(v_union_name,'Union') || ' payment reminder' || E'\n'
        || 'Statement ' || COALESCE(r.invoice_number, r.id::text) || E'\n\n'
        || 'Amount outstanding  ' || to_char(r.outstanding, 'FM999,999,999,990.00') || E'\n'
        || 'Due                 ' || to_char(r.due_at, 'YYYY-MM-DD') || E'\n'
        || 'Days past due       ' || v_days || E'\n\n'
        || CASE WHEN v_level_due >= 3
                THEN 'This is the final reminder. The union has been notified.'
                ELSE 'Please settle this statement.' END
        || E'\n\n'
        || 'If you believe this statement is wrong, contest it rather than ignore it.';

      v_msg := fn_union_send_club_message(
        p_union_id, r.club_id, v_body,
        jsonb_build_object('kind', 'union_payment_reminder',
                           'invoice_id', r.id, 'invoice_number', r.invoice_number,
                           'outstanding', r.outstanding, 'days_past_due', v_days,
                           'reminder_level', v_level_due),
        'invoice');

      UPDATE settlement_invoices
         SET reminders_sent = v_level_due, last_reminder_at = now(), updated_at = now()
       WHERE id = r.id;
      v_reminded := v_reminded + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('union_id', p_union_id,
    'newly_overdue', v_marked, 'reminders_sent', v_reminded, 'escalated', v_escalated,
    'total_outstanding_past_due', round(v_owed_total, 2),
    'dunning_gated', NOT v_gate_open, 'ran_at', now());
END $$;


ALTER FUNCTION public.fn_union_age_invoices(p_union_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_union_age_invoices(p_union_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_age_invoices(p_union_id uuid) IS 'Marks a delivered, club-owed, uncredited statement overdue once due_at passes, and chases it at 0/3/7 days with one message per run, escalating to a critical alert past the last reminder. A disputed statement never ages. Reminders and overdue-driven suspension both respect the weekly_invoices_enabled gate. Runs hourly from fn_union_integrity_sweep_all.';


--
-- Name: fn_union_agent_coverage(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_agent_coverage(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_required boolean;
  v_players bigint; v_players_with bigint;
  v_supers bigint; v_agents bigint; v_subs bigint;
  v_agents_linked bigint; v_subs_linked bigint;
  v_agents_with_subs bigint; v_out_of_band bigint;
  v_deals bigint; v_gap_breaches bigint;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_union_overseer(p_union_id, auth.uid()))) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  SELECT COALESCE((settings->>'require_agent_for_players')::boolean, false)
    INTO v_required FROM unions WHERE id = p_union_id;

  SELECT count(*) FILTER (WHERE m.role = 'player'),
         count(*) FILTER (WHERE m.role = 'player' AND m.agent_id IS NOT NULL)
    INTO v_players, v_players_with
    FROM club_members m
    JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = p_union_id;

  SELECT count(*) FILTER (WHERE a.role='super_agent'),
         count(*) FILTER (WHERE a.role='agent'),
         count(*) FILTER (WHERE a.role='sub_agent'),
         count(*) FILTER (WHERE a.role='agent'     AND a.parent_agent_id IS NOT NULL),
         count(*) FILTER (WHERE a.role='sub_agent' AND a.parent_agent_id IS NOT NULL)
    INTO v_supers, v_agents, v_subs, v_agents_linked, v_subs_linked
    FROM agents a
    JOIN union_clubs uc ON uc.club_id = a.club_id AND uc.union_id = p_union_id
   WHERE a.status = 'active';

  SELECT count(*) INTO v_agents_with_subs
    FROM agents a
    JOIN union_clubs uc ON uc.club_id = a.club_id AND uc.union_id = p_union_id
   WHERE a.status='active' AND a.role='agent'
     AND EXISTS (SELECT 1 FROM agents s WHERE s.parent_agent_id = a.id AND s.status='active');

  SELECT count(*) INTO v_out_of_band
    FROM agents a
    JOIN union_clubs uc ON uc.club_id = a.club_id AND uc.union_id = p_union_id
   WHERE a.status='active' AND a.commission_rate IS NOT NULL
     AND (CASE WHEN a.commission_rate > 1 THEN a.commission_rate/100.0 ELSE a.commission_rate END)
         NOT BETWEEN public.fn_union_setting(p_union_id,'min_agent_commission',0)
                 AND public.fn_union_setting(p_union_id,'max_agent_commission',1);

  SELECT count(*) FILTER (WHERE COALESCE(m.player_rakeback_pct,0) > 0),
         count(*) FILTER (WHERE COALESCE(m.player_rakeback_pct,0) > 0
                            AND m.player_rakeback_pct * 100 > floor((a.commission_rate*100) - 10))
    INTO v_deals, v_gap_breaches
    FROM club_members m
    JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = p_union_id
    JOIN agents a ON a.user_id = m.agent_id AND a.club_id = m.club_id AND a.status='active'
   WHERE m.role = 'player';

  RETURN jsonb_build_object(
    'require_agent_for_players', v_required,
    'players_total', v_players,
    'players_with_agent', v_players_with,
    'players_without_agent', v_players - v_players_with,
    'player_coverage_pct', CASE WHEN v_players > 0
                                THEN round(100.0*v_players_with/v_players, 1) ELSE 100 END,
    'super_agents', v_supers,
    'agents', v_agents,
    'sub_agents', v_subs,
    'agents_under_a_super_agent', v_agents_linked,
    'agents_orphaned', v_agents - v_agents_linked,
    'sub_agents_under_an_agent', v_subs_linked,
    'sub_agents_orphaned', v_subs - v_subs_linked,
    'agents_that_have_sub_agents', v_agents_with_subs,
    'commission_rates_out_of_policy', v_out_of_band,
    'player_rakeback_deals', v_deals,
    'player_rakeback_gap_breaches', v_gap_breaches,
    'policy_band', jsonb_build_object(
      'min', public.fn_union_setting(p_union_id,'min_agent_commission',0),
      'max', public.fn_union_setting(p_union_id,'max_agent_commission',1))
  );
END $$;


ALTER FUNCTION public.fn_union_agent_coverage(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_union_agent_risk_report(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_agent_risk_report(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(agent_user_id uuid, agent_name text, club_name text, role text, players integer, seated_now integer, rake_generated numeric, player_net numeric, commission_accrued numeric, credit_extended numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_from timestamptz := COALESCE(p_since, public.fn_union_week_start(now()));
BEGIN
  IF NOT public.fn_is_any_union_overseer(auth.uid()) AND NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  RETURN QUERY
  WITH union_clubs_all AS (
    SELECT uc.club_id FROM union_clubs uc WHERE uc.union_id = p_union_id
    UNION SELECT p_union_id
  ),
  roster AS (
    SELECT m.agent_id AS agent_user_id, m.user_id AS player_id, m.club_id,
           COALESCE(m.credit_used,0) AS credit_used
      FROM club_members m
      JOIN union_clubs_all u ON u.club_id = m.club_id
     WHERE m.agent_id IS NOT NULL
  ),
  rake AS (
    SELECT (e.key)::uuid AS player_id,
           SUM(rr.rake_amount * (e.value::numeric) / NULLIF(c.total,0)) AS rake_generated
      FROM rake_records rr
      CROSS JOIN LATERAL (SELECT SUM(t.value::numeric) AS total
                            FROM jsonb_each_text(rr.player_contributions) t(key,value)) c
      CROSS JOIN LATERAL jsonb_each_text(rr.player_contributions) e(key,value)
     WHERE rr.created_at >= v_from
       AND rr.player_contributions IS NOT NULL AND c.total > 0
     GROUP BY 1
  ),
  flows AS (
    SELECT wt.user_id AS player_id,
           SUM(CASE WHEN wt.type='credit' AND wt.category='cashout' THEN wt.amount ELSE 0 END)
         - SUM(CASE WHEN wt.type='debit'  AND wt.category IN ('buyin','rebuy','addon') THEN wt.amount ELSE 0 END) AS net
      FROM wallet_transactions wt
     WHERE wt.created_at >= v_from
     GROUP BY 1
  ),
  comm AS (
    SELECT ac.user_id AS agent_user_id, SUM(ac.amount) AS amt
      FROM agent_commissions ac
     WHERE ac.created_at >= v_from
     GROUP BY 1
  )
  SELECT r.agent_user_id,
         pr.username,
         cl.name,
         COALESCE(a.role,'agent'),
         COUNT(DISTINCT r.player_id)::int,
         COUNT(DISTINCT r.player_id) FILTER (
           WHERE EXISTS (SELECT 1 FROM table_seats ts
                          WHERE ts.user_id = r.player_id AND ts.left_at IS NULL))::int,
         ROUND(COALESCE(SUM(rk.rake_generated),0),2),
         ROUND(COALESCE(SUM(fl.net),0),2),
         ROUND(COALESCE(MAX(cm2.amt),0),2),
         ROUND(COALESCE(SUM(r.credit_used),0),2)
    FROM roster r
    LEFT JOIN profiles pr ON pr.id = r.agent_user_id
    LEFT JOIN clubs cl ON cl.id = r.club_id
    LEFT JOIN agents a ON a.user_id = r.agent_user_id AND a.club_id = r.club_id
    LEFT JOIN rake rk ON rk.player_id = r.player_id
    LEFT JOIN flows fl ON fl.player_id = r.player_id
    LEFT JOIN comm cm2 ON cm2.agent_user_id = r.agent_user_id
   GROUP BY r.agent_user_id, pr.username, cl.name, a.role
   ORDER BY 8 DESC NULLS LAST;
END $$;


ALTER FUNCTION public.fn_union_agent_risk_report(p_union_id uuid, p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_apply_presettlements(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_apply_presettlements(p_union_id uuid, p_settlement_id uuid, p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_period_start timestamptz;
  v_period_end   timestamptz;
  v_rows int;
  v_total numeric;
BEGIN
  IF v_caller IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM unions u WHERE u.id = p_union_id AND u.owner_id = v_caller)
     AND NOT EXISTS (SELECT 1 FROM union_admins ua
                      WHERE ua.union_id = p_union_id AND ua.user_id = v_caller) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authorized');
  END IF;

  SELECT s.period_start, s.period_end INTO v_period_start, v_period_end
    FROM union_pnl_settlements s
   WHERE s.id = p_settlement_id AND s.union_id = p_union_id;

  IF v_period_start IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'settlement not found for this union');
  END IF;

  WITH upd AS (
    UPDATE union_presettlements p
       SET applied_settlement_id = p_settlement_id
     WHERE p.union_id = p_union_id
       AND p.applied_settlement_id IS NULL
       AND p.received_at < v_period_end
       AND (p_club_id IS NULL OR p.club_id = p_club_id)
    RETURNING p.amount
  )
  SELECT count(*), COALESCE(round(SUM(amount), 2), 0) INTO v_rows, v_total FROM upd;

  RETURN jsonb_build_object('success', true, 'settlement_id', p_settlement_id,
                            'presettlements_applied', v_rows, 'total_applied', v_total,
                            'period_start', v_period_start, 'period_end', v_period_end);
END;
$$;


ALTER FUNCTION public.fn_union_apply_presettlements(p_union_id uuid, p_settlement_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_union_bbj_backup_transfer(uuid, numeric, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_bbj_backup_transfer(p_union_id uuid, p_amount numeric, p_destination text, p_op_id uuid, p_created_by uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_amt     numeric := round(COALESCE(p_amount, 0), 2);
  v_pool_id uuid;
  v_backup  numeric;
  v_main    numeric;
  v_promo_after numeric;
  v_res jsonb;
BEGIN
  IF v_amt <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;
  IF p_destination NOT IN ('main', 'promo') THEN
    RETURN jsonb_build_object('success', false, 'error', 'destination must be main or promo');
  END IF;
  IF p_op_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'op_id_required');
  END IF;

  SELECT id, COALESCE(backup_balance,0), COALESCE(main_balance,0)
    INTO v_pool_id, v_backup, v_main
    FROM bbj_pools
   WHERE union_id = p_union_id AND status = 'active'
   FOR UPDATE;

  IF v_pool_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'no active BBJ pool for this union');
  END IF;
  IF v_backup-public.fn_bbj_parked_reserve(v_pool_id,'backup') < v_amt THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient backup balance',
                              'available', v_backup-public.fn_bbj_parked_reserve(v_pool_id,'backup'), 'requested', v_amt);
  END IF;

  IF p_destination = 'main' THEN
    -- A bank move inside the pool: declared, recorded, idempotent on the op id.
    v_res := public.fn_bbj_move_between_banks(v_pool_id, 'backup', 'main', v_amt,
               COALESCE(NULLIF(p_notes, ''), 'union owner: BBJ backup -> main jackpot'),
               'union-backup-transfer:' || p_op_id::text);
    IF (v_res->>'ok')::boolean IS DISTINCT FROM true THEN
      RETURN jsonb_build_object('success', false, 'error', COALESCE(v_res->>'reason', 'move refused'));
    END IF;
    IF (v_res->>'replayed')::boolean THEN
      RETURN jsonb_build_object('success', false, 'duplicate', true, 'error', 'operation already processed');
    END IF;

    -- 'bbj_wallet', not 'bbj_pool': the CHECK constraint on this table lists
    -- six wallet names and bbj_pool is not one of them. The chips never left
    -- the BBJ system, they changed bank inside it.
    INSERT INTO union_wallet_transactions
      (union_id, wallet, direction, amount, balance_after, tx_type, period_id, notes, created_by)
    VALUES
      (p_union_id, 'bbj_wallet', 'debit', v_amt, v_main + v_amt, 'bbj_backup_to_main', p_op_id,
       COALESCE(NULLIF(p_notes, ''), 'BBJ backup -> main jackpot'), p_created_by);

    RETURN jsonb_build_object('success', true, 'destination', 'main', 'amount', v_amt,
                              'pool_id', v_pool_id,
                              'backup_after', v_backup - v_amt,
                              'main_after', v_main + v_amt);
  END IF;

  /* DECLARED (Phase 4.3): the reserve leaves the pool for the union's promo
     wallet. The pool debit is journalled bbj_pool -> union_wallet; the wallet
     credit is autoskipped so the one move is one leg. */
  PERFORM public.fn_ca_declare_ledger('promo', 'union_wallet', p_union_id, NULL,
                                      'bbj_backup_to_promo:' || p_op_id::text, ARRAY['union_wallets']);
  UPDATE bbj_pools
     SET backup_balance = COALESCE(backup_balance,0) - v_amt, updated_at = now()
   WHERE id = v_pool_id;
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_idempotency_key', '', true);

  INSERT INTO union_wallets (union_id, promo_wallet)
  VALUES (p_union_id, v_amt)
  ON CONFLICT (union_id) DO UPDATE
    SET promo_wallet = COALESCE(union_wallets.promo_wallet, 0) + EXCLUDED.promo_wallet,
        updated_at = now()
  RETURNING promo_wallet INTO v_promo_after;
  PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);

  IF v_promo_after IS NULL THEN
    RAISE EXCEPTION 'promo wallet credit failed for union %', p_union_id;
  END IF;

  INSERT INTO union_wallet_transactions
    (union_id, wallet, direction, amount, balance_after, tx_type, period_id, notes, created_by)
  VALUES
    (p_union_id, 'promo_wallet', 'credit', v_amt, v_promo_after, 'bbj_backup_to_promo', p_op_id,
     COALESCE(NULLIF(p_notes, ''), 'BBJ backup -> promo wallet'), p_created_by);

  RETURN jsonb_build_object('success', true, 'destination', 'promo', 'amount', v_amt,
                            'pool_id', v_pool_id,
                            'backup_after', v_backup - v_amt,
                            'promo_after', v_promo_after);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('success', false, 'duplicate', true,
                            'error', 'operation already processed');
END;
$$;


ALTER FUNCTION public.fn_union_bbj_backup_transfer(p_union_id uuid, p_amount numeric, p_destination text, p_op_id uuid, p_created_by uuid, p_notes text) OWNER TO postgres;

