--
-- Name: fn_union_can_manage_wallets(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_can_manage_wallets(p_union_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_union_id IS NULL OR p_user_id IS NULL THEN RETURN false; END IF;
  RETURN public.fn_is_union_overseer(p_union_id, p_user_id)
      OR EXISTS (
        SELECT 1 FROM public.club_members member
         WHERE member.club_id = p_union_id
           AND member.user_id = p_user_id
           AND member.role = 'co_owner'
           AND member.status IN ('active', 'approved')
      )
      OR EXISTS (
        SELECT 1 FROM public.union_admins admin
         WHERE admin.union_id = p_union_id
           AND admin.user_id = p_user_id
           AND COALESCE(admin.role, '') IN ('co_owner', 'admin', 'owner')
      );
END;
$$;


ALTER FUNCTION public.fn_union_can_manage_wallets(p_union_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: fn_union_chip_integrity_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_chip_integrity_check() RETURNS TABLE(invariant text, offenders bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 'negative_club_balance', count(*),
         'club_members.chip_balance below zero - a debit path lost its balance guard'
    FROM club_members WHERE chip_balance < 0
  HAVING count(*) > 0

  UNION ALL
  SELECT 'orphan_stamped_seat', count(*),
         'active seat stamped to a club the player does not belong to - cash-out cannot land'
    FROM table_seats ts
   WHERE ts.left_at IS NULL AND ts.club_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM club_members m
                      WHERE m.user_id = ts.user_id AND m.club_id = ts.club_id)
  HAVING count(*) > 0

  UNION ALL
  SELECT 'orphan_stamped_entry', count(*),
         'live tournament entry stamped to a club the player does not belong to'
    FROM tournament_players tp
    JOIN tournaments t ON t.id = tp.tournament_id
   WHERE tp.club_id IS NOT NULL
     AND t.status IN ('ANNOUNCED','SCHEDULED','REGISTERING','LATE_REG','RUNNING')
     AND NOT EXISTS (SELECT 1 FROM club_members m
                      WHERE m.user_id = tp.user_id AND m.club_id = tp.club_id)
  HAVING count(*) > 0

  UNION ALL
  SELECT 'seat_stamped_outside_union', count(*),
         'union game seat stamped to a club outside that union - cross-union contamination'
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
   WHERE ts.left_at IS NULL AND ts.club_id IS NOT NULL AND t.union_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM union_clubs uc
                      WHERE uc.club_id = ts.club_id AND uc.union_id = t.union_id)
  HAVING count(*) > 0;
$$;


ALTER FUNCTION public.fn_union_chip_integrity_check() OWNER TO postgres;

--
-- Name: fn_union_clawback_from_club(uuid, uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_clawback_from_club(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_lead boolean;
  v_treasury numeric;
  v_after numeric;
  v_floor numeric := 0;
  v_now numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authenticated');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM union_admins ua
     WHERE ua.union_id = p_union_id AND ua.user_id = v_uid AND ua.role = 'union_lead'
  ) OR EXISTS (
    SELECT 1 FROM unions u WHERE u.id = p_union_id AND u.owner_id = v_uid
  ) INTO v_is_lead;
  IF NOT v_is_lead THEN
    RETURN jsonb_build_object('success', false, 'error', 'union lead access required');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM union_clubs uc WHERE uc.union_id = p_union_id AND uc.club_id = p_club_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'club is not in this union');
  END IF;

  /* THE OPENING GRANT STAYS IN THE CLUB (Dan, 2026-09-03). A club that
     received the 100,000 opening bank keeps it: a clawback may take the
     treasury down to that floor and no further. Chips the club earned or was
     minted later are above the floor and remain reachable. */
  IF EXISTS (SELECT 1 FROM chip_transactions t
              WHERE t.club_id = p_club_id AND t.transaction_type = 'club_opening_grant') THEN
    v_floor := 100000;
  END IF;
  SELECT COALESCE(chip_treasury, 0) INTO v_now FROM clubs WHERE id = p_club_id;
  IF v_now - p_amount < v_floor THEN
    RETURN jsonb_build_object('success', false, 'error',
      'the opening grant stays in the club: a clawback may not take the treasury below ' || v_floor::text,
      'club_treasury', v_now, 'floor', v_floor, 'max_clawback', GREATEST(0, v_now - v_floor));
  END IF;

  -- CHIP STANDARD 2.4 (2026-09-03): a clawback is ONE `union_settlement` row
  -- from the club bank to the union bank, keyed and correlated on the op when
  -- one is given. The union_wallets trigger is skipped; the clubs trigger
  -- writes the row with the union bank as its counterparty. Never a refusal.
  PERFORM public.fn_ca_declare_ledger('union_settlement', 'union_bank', p_union_id, NULL,
    CASE WHEN p_op_id IS NOT NULL THEN 'union_clawback:' || p_op_id::text END, ARRAY['union_wallets']);
  IF p_op_id IS NOT NULL THEN
    PERFORM set_config('app.ledger_correlation', p_op_id::text, true);
  END IF;

  UPDATE clubs SET chip_treasury = COALESCE(chip_treasury, 0) - p_amount
   WHERE id = p_club_id AND COALESCE(chip_treasury, 0) >= p_amount
  RETURNING chip_treasury INTO v_treasury;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient club treasury balance');
  END IF;

  INSERT INTO union_wallets (union_id, chip_balance)
  VALUES (p_union_id, p_amount)
  ON CONFLICT (union_id) DO UPDATE
    SET chip_balance = COALESCE(union_wallets.chip_balance, 0) + p_amount,
        updated_at = NOW()
  RETURNING chip_balance INTO v_after;
  PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);

  INSERT INTO union_wallet_transactions (
    union_id, wallet, direction, amount, balance_after, tx_type, club_id, period_id, notes, created_by
  ) VALUES (
    p_union_id, 'chip_balance', 'credit', p_amount, v_after, 'clawback',
    p_club_id, p_op_id, COALESCE(NULLIF(p_notes, ''), 'Clawback from club treasury'), v_uid
  );

  INSERT INTO chip_transactions (club_id, amount, transaction_type, notes)
  VALUES (p_club_id, p_amount, 'union_clawback',
          COALESCE(NULLIF(p_notes, ''), 'Union clawback from club treasury'));

  RETURN jsonb_build_object(
    'success', true, 'amount', p_amount,
    'club_treasury', v_treasury, 'union_balance', v_after
  );
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('success', false, 'duplicate', true,
                            'error', 'operation already processed');
END;
$$;


ALTER FUNCTION public.fn_union_clawback_from_club(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_union_clawback_promo_from_club(uuid, uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_clawback_promo_from_club(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid       uuid := auth.uid();
  v_amt       numeric := round(COALESCE(p_amount, 0), 2);
  v_op        uuid := COALESCE(p_op_id, gen_random_uuid());
  v_is_lead   boolean;
  v_club_name text;
  v_pot_after numeric;
  v_after     numeric;
  v_note      text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authenticated');
  END IF;
  IF v_amt <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;
  IF v_amt > 1e9 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Amount Exceeds The Single Send Limit');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM union_admins ua
     WHERE ua.union_id = p_union_id AND ua.user_id = v_uid AND ua.role = 'union_lead'
  ) OR EXISTS (
    SELECT 1 FROM unions u WHERE u.id = p_union_id AND u.owner_id = v_uid
  ) INTO v_is_lead;
  IF NOT v_is_lead THEN
    RETURN jsonb_build_object('success', false, 'error', 'union lead access required');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM union_clubs uc WHERE uc.union_id = p_union_id AND uc.club_id = p_club_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'club is not in this union');
  END IF;

  PERFORM 1 FROM union_wallets WHERE union_id = p_union_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'union wallet not found');
  END IF;
  SELECT c.name INTO v_club_name FROM clubs c WHERE c.id = p_club_id FOR UPDATE;
  IF v_club_name IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'club not found');
  END IF;
  v_note := COALESCE(NULLIF(btrim(p_notes), ''),
                     'Promo Pulled Back From ' || v_club_name || ' Promo Wallet');

  PERFORM public.fn_ca_declare_ledger('promo', 'union_wallet', p_union_id, NULL,
    'union_promo_clawback:' || v_op::text, ARRAY['union_wallets']);
  PERFORM set_config('app.ledger_correlation', v_op::text, true);

  UPDATE clubs
     SET promo_balance = COALESCE(promo_balance, 0) - v_amt, updated_at = now()
   WHERE id = p_club_id AND COALESCE(promo_balance, 0) >= v_amt
   RETURNING promo_balance INTO v_pot_after;
  IF NOT FOUND THEN
    PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);
    RETURN jsonb_build_object('success', false, 'error', 'insufficient club promo wallet balance',
      'club_promo', (SELECT COALESCE(promo_balance, 0) FROM clubs WHERE id = p_club_id),
      'requested', v_amt);
  END IF;

  UPDATE union_wallets
     SET promo_wallet = COALESCE(promo_wallet, 0) + v_amt, updated_at = now()
   WHERE union_id = p_union_id
   RETURNING promo_wallet INTO v_after;
  PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);

  INSERT INTO union_wallet_transactions
    (union_id, club_id, wallet, direction, amount, balance_after, tx_type, period_id, notes, created_by)
  VALUES
    (p_union_id, p_club_id, 'promo_wallet', 'credit', v_amt, v_after, 'promo_clawback', v_op,
     v_note, v_uid);

  INSERT INTO chip_transactions
    (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after, metadata)
  VALUES
    (p_club_id, v_uid, NULL, v_amt, 'union_promo_clawback', v_note, v_pot_after,
     jsonb_build_object('union_id', p_union_id, 'op_id', v_op,
                        'source', 'club_promo_wallet',
                        'club_promo_after', v_pot_after,
                        'union_promo_after', v_after));

  RETURN jsonb_build_object('success', true, 'amount', v_amt, 'op_id', v_op,
                            'club_promo_after', v_pot_after, 'promo_after', v_after);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('success', false, 'duplicate', true,
                            'error', 'operation already processed');
END;
$$;


ALTER FUNCTION public.fn_union_clawback_promo_from_club(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text, p_op_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_union_clawback_promo_from_club(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text, p_op_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_clawback_promo_from_club(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text, p_op_id uuid) IS 'The inverse of fn_union_promo_send(club): pulls promo back from clubs.promo_balance into union_wallets.promo_wallet. Union owner or union_lead. Op-keyed via (union_id, tx_type, period_id).';


--
-- Name: fn_union_close_club_tables_for_join(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_close_club_tables_for_join(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
  v_tables int := 0;
  v_seats int := 0;
  v_refunded numeric := 0;
  v_live_tourneys int;
  v_closed jsonb := '[]'::jsonb;
BEGIN
  IF p_club_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'missing_club_id');
  END IF;

  -- Live NON-PRIVATE tournaments cannot be auto-migrated: they must finish or
  -- be cancelled by a human before the club can join.
  SELECT count(*) INTO v_live_tourneys
    FROM tournaments
   WHERE club_id = p_club_id
     AND COALESCE(is_private, false) = false
     AND status IN ('ANNOUNCED','SCHEDULED','REGISTERING','LATE_REG','RUNNING');

  IF v_live_tourneys > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'live_tournaments',
                              'live_tournaments', v_live_tourneys);
  END IF;

  -- Refund every seated player from their ACTUAL stack, then vacate, then
  -- close. All inside this function's single transaction.
  FOR r IN
    SELECT t.id AS table_id, t.name
      FROM tables t
     WHERE t.club_id = p_club_id
       AND t.tournament_id IS NULL
       AND COALESCE(t.is_private, false) = false   -- private club games are kept
       AND COALESCE(t.is_deleted, false) = false
       AND t.status NOT IN ('closed','deleted')
     FOR UPDATE
  LOOP
    FOR r IN
      SELECT ts.id AS seat_id, ts.user_id, ts.stack, ts.table_id
        FROM table_seats ts
       WHERE ts.table_id = r.table_id AND ts.left_at IS NULL AND ts.stack > 0
       FOR UPDATE
    LOOP
      PERFORM atomic_credit_wallet_and_log(
        r.user_id, r.stack, 'cashout',
        'Table closed: club joined a union',
        r.table_id, NULL, r.seat_id, 'cashout:' || r.seat_id::text
      );
      v_seats := v_seats + 1;
      v_refunded := v_refunded + r.stack;
    END LOOP;
  END LOOP;

  UPDATE table_seats ts
     SET left_at = now()
    FROM tables t
   WHERE t.id = ts.table_id
     AND t.club_id = p_club_id
     AND t.tournament_id IS NULL
     AND COALESCE(t.is_private, false) = false
     AND COALESCE(t.is_deleted, false) = false
     AND t.status NOT IN ('closed','deleted')
     AND ts.left_at IS NULL;

  -- is_deleted is what makes the closure survive the engine boot sweep and
  -- the fleet name-match reactivation.
  WITH closed AS (
    UPDATE tables
       SET status = 'closed', current_players = 0, is_deleted = true
     WHERE club_id = p_club_id
       AND tournament_id IS NULL
       AND COALESCE(is_private, false) = false
       AND COALESCE(is_deleted, false) = false
       AND status NOT IN ('closed','deleted')
    RETURNING id, name
  )
  SELECT count(*), COALESCE(jsonb_agg(jsonb_build_object('id', id, 'name', name)), '[]'::jsonb)
    INTO v_tables, v_closed FROM closed;

  RETURN jsonb_build_object(
    'success', true,
    'tables_closed', v_tables,
    'seats_refunded', v_seats,
    'chips_refunded', v_refunded,
    'tables', v_closed
  );
END $$;


ALTER FUNCTION public.fn_union_close_club_tables_for_join(p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_union_club_exit_blockers(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_club_exit_blockers(p_union_id uuid, p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_seated bigint; v_entries bigint; v_unsettled numeric; v_credit numeric;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_union_overseer(p_union_id, auth.uid()))) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  SELECT count(*) INTO v_seated
    FROM table_seats ts JOIN tables t ON t.id = ts.table_id
   WHERE ts.left_at IS NULL AND ts.club_id = p_club_id AND t.union_id = p_union_id;

  SELECT count(*) INTO v_entries
    FROM tournament_players tp JOIN tournaments t ON t.id = tp.tournament_id
   WHERE tp.club_id = p_club_id AND t.union_id = p_union_id
     AND t.status IN ('ANNOUNCED','SCHEDULED','REGISTERING','LATE_REG','RUNNING');

  SELECT COALESCE(SUM(amount),0) INTO v_unsettled
    FROM union_wallet_transactions
   WHERE union_id = p_union_id AND club_id = p_club_id
     AND wallet = 'rake_wallet' AND direction = 'credit' AND tx_type = 'rake'
     AND created_at >= public.fn_union_week_start(now());

  SELECT COALESCE(SUM(credit_used),0) INTO v_credit
    FROM agents WHERE club_id = p_club_id AND status = 'active';

  RETURN jsonb_build_object(
    'players_seated_in_union_games', v_seated,
    'live_tournament_entries', v_entries,
    'unsettled_rake_this_period', round(v_unsettled,2),
    'agent_credit_outstanding', round(v_credit,2),
    'clear_to_exit', (v_seated = 0 AND v_entries = 0 AND v_unsettled = 0 AND v_credit = 0)
  );
END $$;


ALTER FUNCTION public.fn_union_club_exit_blockers(p_union_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- Name: fn_union_club_exposure(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_club_exposure(p_union_id uuid, p_week_start timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, week_start timestamp with time zone, running_net numeric, presettled numeric, exposure numeric, security_deposit numeric, stop_loss_limit numeric, headroom numeric, breached boolean, terms_on_file boolean, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start timestamptz := COALESCE(p_week_start, fn_union_week_start());
BEGIN
  RETURN QUERY
  WITH rep AS (
    -- inherits the reconciliation report's own authorization check
    SELECT r.club_id, r.club_name, r.settle_net
      FROM fn_union_reconciliation_report(p_union_id, v_start, now()) r
  ),
  pre AS (
    -- Unapplied cash the club has already handed over. Closed out by
    -- applied_settlement_id, never by age: money paid during a week that did
    -- not settle still offsets exposure.
    SELECT p.club_id, COALESCE(SUM(p.amount), 0) AS amt
      FROM union_presettlements p
     WHERE p.union_id = p_union_id
       AND p.applied_settlement_id IS NULL
     GROUP BY p.club_id
  )
  SELECT rep.club_id,
         rep.club_name,
         v_start,
         rep.settle_net,
         COALESCE(pre.amt, 0),
         GREATEST(0, round(-rep.settle_net - COALESCE(pre.amt, 0), 2)) AS exposure,
         COALESCE(t.security_deposit, 0),
         t.stop_loss_limit,
         CASE WHEN t.stop_loss_limit IS NULL THEN NULL
              ELSE round(t.stop_loss_limit
                         - GREATEST(0, -rep.settle_net - COALESCE(pre.amt, 0)), 2) END,
         CASE WHEN t.stop_loss_limit IS NULL THEN false
              ELSE GREATEST(0, -rep.settle_net - COALESCE(pre.amt, 0)) > t.stop_loss_limit END,
         (t.club_id IS NOT NULL),
         COALESCE(t.status, 'no_terms')
    FROM rep
    LEFT JOIN pre ON pre.club_id = rep.club_id
    LEFT JOIN union_club_terms t
           ON t.union_id = p_union_id AND t.club_id = rep.club_id
   ORDER BY exposure DESC;
END;
$$;


ALTER FUNCTION public.fn_union_club_exposure(p_union_id uuid, p_week_start timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_club_invoice(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_club_invoice(p_union_id uuid, p_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, period_start timestamp with time zone, period_end timestamp with time zone, rake_generated numeric, union_fee_kept numeric, rakeback_due numeric, players_won numeric, player_pnl_net numeric, eco_amount numeric, eco_enabled boolean, presettled numeric, settled_in_chips numeric, outstanding numeric, net_position numeric, direction text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start timestamptz := COALESCE(p_start, fn_union_week_start());
  v_end   timestamptz := COALESCE(p_end, now());
BEGIN
  RETURN QUERY
  WITH eco AS (
    SELECT e.club_id, e.club_name, e.players_won, e.rake_generated,
           e.rake_earned, e.eco_base, e.eco_amount, e.eco_enabled
      FROM fn_union_eco_adjustment(p_union_id, v_start, v_end) e
  ),
  pre AS (
    -- Unapplied cash held against the running balance. Closed out by
    -- applied_settlement_id, never by age: a payment made during a week that
    -- did not settle must still reach the club's next statement.
    SELECT p.club_id, COALESCE(SUM(p.amount), 0) AS amt
      FROM union_presettlements p
     WHERE p.union_id = p_union_id
       AND p.received_at < v_end
       AND p.applied_settlement_id IS NULL
     GROUP BY p.club_id
  ),
  calc AS (
    /* Phase 6 (20260907): rakeback_due IS round 1's payout for the club - the
       same fn_union_club_rake_basis rows, per game type, truncated to the
       cent - not a flat rate applied to a different rake total. */
    SELECT eco.club_id, eco.club_name,
           eco.rake_generated,
           round(eco.rake_generated - eco.rake_earned, 2) AS union_fee_kept,
           eco.rake_earned                                AS rakeback_due,
           eco.players_won,
           round(eco.players_won + eco.rake_generated, 2) AS player_pnl_net,
           CASE WHEN eco.eco_enabled THEN eco.eco_amount ELSE 0 END AS eco_amount,
           eco.eco_enabled,
           COALESCE(pre.amt, 0) AS presettled
      FROM eco
      LEFT JOIN pre   ON pre.club_id = eco.club_id
  )
  SELECT calc.club_id, calc.club_name, v_start, v_end,
         calc.rake_generated, calc.union_fee_kept, calc.rakeback_due,
         calc.players_won, calc.player_pnl_net,
         calc.eco_amount, calc.eco_enabled, calc.presettled,
         round(calc.player_pnl_net + calc.rakeback_due, 2) AS settled_in_chips,
         round(calc.eco_amount + calc.presettled, 2)       AS outstanding,
         round(calc.player_pnl_net + calc.rakeback_due
               + calc.eco_amount + calc.presettled, 2)     AS net_position,
         CASE WHEN round(calc.eco_amount + calc.presettled, 2) > 0
                THEN 'union owes club'
              WHEN round(calc.eco_amount + calc.presettled, 2) < 0
                THEN 'club owes union'
              ELSE 'square' END::text
    FROM calc
   ORDER BY calc.club_name;
END;
$$;


ALTER FUNCTION public.fn_union_club_invoice(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_club_performance(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_club_performance(p_union_id uuid, p_weeks integer DEFAULT 4) RETURNS TABLE(club_id uuid, club_name text, weeks_measured integer, winning_weeks integer, losing_weeks integer, total_net numeric, avg_weekly_net numeric, crushing boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_weeks integer := GREATEST(1, LEAST(COALESCE(p_weeks, 4), 12));
  v_from  timestamptz := fn_union_week_start() - (v_weeks - 1) * interval '7 days';
  v_cur   timestamptz := date_trunc('week', (fn_union_week_start() AT TIME ZONE 'UTC'));
BEGIN
  RETURN QUERY
  WITH settled AS (
    -- one row per club per settled period, straight from what was invoiced
    SELECT date_trunc('week', (s.period_start AT TIME ZONE 'UTC')) AS wk,
           (e->>'club_id')::uuid AS cid,
           (e->>'net')::numeric  AS net_amt
      FROM union_pnl_settlements s
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(s.club_results, '[]'::jsonb)) e
     WHERE s.union_id = p_union_id
       AND s.status = 'settled'
       AND s.period_start >= v_from
       AND (e->>'club_id') IS NOT NULL
  ),
  settled_wk AS (
    -- collapse multiple settlements inside one week into that week's total
    SELECT settled.wk, settled.cid, SUM(settled.net_amt) AS net_amt
      FROM settled GROUP BY settled.wk, settled.cid
  ),
  open_wk AS (
    -- the current week only, computed live (inherits the report's authz)
    SELECT v_cur AS wk, rep.club_id AS cid, rep.settle_net AS net_amt
      FROM fn_union_reconciliation_report(p_union_id, fn_union_week_start(), now()) rep
     WHERE NOT EXISTS (
       SELECT 1 FROM settled_wk sw
        WHERE sw.cid = rep.club_id AND sw.wk = v_cur)
  ),
  allwk AS (
    SELECT settled_wk.wk, settled_wk.cid, settled_wk.net_amt FROM settled_wk
    UNION ALL
    SELECT open_wk.wk, open_wk.cid, open_wk.net_amt FROM open_wk
  ),
  agg AS (
    SELECT a.cid,
           count(*)::int AS wks,
           count(*) FILTER (WHERE a.net_amt > 0)::int AS wins,
           count(*) FILTER (WHERE a.net_amt < 0)::int AS losses,
           round(SUM(a.net_amt), 2) AS net_total
      FROM allwk a GROUP BY a.cid
  )
  SELECT agg.cid, c.name::text, agg.wks, agg.wins, agg.losses, agg.net_total,
         round(agg.net_total / NULLIF(agg.wks, 0), 2),
         -- "consistently finishes with a positive win ratio": up overall AND
         -- winning in more weeks than it loses
         (agg.net_total > 0 AND agg.wins > agg.losses)
    FROM agg LEFT JOIN clubs c ON c.id = agg.cid
   ORDER BY agg.net_total DESC;
END;
$$;


ALTER FUNCTION public.fn_union_club_performance(p_union_id uuid, p_weeks integer) OWNER TO postgres;

--
-- Name: fn_union_club_player_pnl(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_club_player_pnl(p_club_id uuid, p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT jsonb_build_object(
       'buyins', r.buyins, 'cashouts', r.cashouts, 'realized_net', r.realized_net,
       'winnings', r.winnings, 'losses', r.losses, 'players', r.players,
       'seated_stack', r.seated_stack)
       FROM fn_union_pnl_all_clubs(p_union_id, p_start, p_end, true) r
      WHERE r.club_id = p_club_id),
    jsonb_build_object('buyins',0,'cashouts',0,'realized_net',0,'winnings',0,
                       'losses',0,'players',0,'seated_stack',0));
$$;


ALTER FUNCTION public.fn_union_club_player_pnl(p_club_id uuid, p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_club_rake_basis(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_club_rake_basis(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_live boolean DEFAULT false) RETURNS TABLE(club_id uuid, game_type text, rake_in numeric, rate numeric, payout numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sref text;
BEGIN
  IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR p_end <= p_start THEN
    RETURN;
  END IF;

  /* THE WITNESS FIRST. A period that has been closed stored the rows it was
     paid from; a statement for that period describes THAT, never a
     recomputation over attribution tables that may since have moved. */
  v_sref := p_union_id::text || ':'
    || to_char(p_start at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
    || to_char(p_end   at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  IF EXISTS (SELECT 1 FROM public.ca_settlements s
              WHERE s.settlement_type = 'union_rakeback_close' AND s.union_id = p_union_id
                AND s.state = 'final' AND s.external_ref = v_sref
                AND s.totals ? 'basis_detail') THEN
    RETURN QUERY
      SELECT (d->>'club_id')::uuid, d->>'game_type',
             (d->>'rake_in')::numeric, (d->>'rate')::numeric, (d->>'payout')::numeric
        FROM public.ca_settlements s
        CROSS JOIN LATERAL jsonb_array_elements(s.totals->'basis_detail') d
       WHERE s.settlement_type = 'union_rakeback_close' AND s.union_id = p_union_id
         AND s.state = 'final' AND s.external_ref = v_sref;
    RETURN;
  END IF;

  /* THE SNAPSHOT SECOND (Phase 6 verification, 20260908). An OPEN window is
     served from the hourly snapshot when its start matches and its end is at
     or after the snapshot's 'through' - a reader with an eight-second budget
     gets the same rows the sweep computed within the hour. Round 1 passes
     p_live and never reads this: it computes at close time and stores the
     witness above. */
  IF NOT p_live THEN
    IF EXISTS (SELECT 1 FROM public.union_rake_basis_snapshot s
                WHERE s.union_id = p_union_id AND s.period_start = p_start
                  AND p_end >= s.through AND p_end <= s.period_end
                  AND s.computed_at > now() - interval '3 hours') THEN
      RETURN QUERY
        SELECT (d->>'club_id')::uuid, d->>'game_type',
               (d->>'rake_in')::numeric, (d->>'rate')::numeric, (d->>'payout')::numeric
          FROM public.union_rake_basis_snapshot s
          CROSS JOIN LATERAL jsonb_array_elements(s.detail) d
         WHERE s.union_id = p_union_id AND s.period_start = p_start
           AND p_end >= s.through AND p_end <= s.period_end
           AND s.computed_at > now() - interval '3 hours';
      RETURN;
    END IF;
  END IF;

  /* THE BASIS (Dan, 2026-09-03): each member club's share is the rake ITS
     PLAYERS generated at the union's tables - cash from
     ca_union_rake_attribution (the seat the player sat through, captured
     hourly), tournaments / SNGs / spins from tournament_players (each
     treasury credit that names a tournament, split by entries: 1 + rebuys +
     add-on). The union's own house club and anything unattributed stay
     with the union.

     THE RATE (Dan, 2026-09-03): resolved per game type per club, falling back
     to club_commission_rate and then to 0.90. Truncated to the cent per
     (club, game type) so a remainder stays with the union.

     Same arithmetic as the block round 1 paid from between 20260903 and
     20260907 (proven row-identical below); the tournament split now groups
     the credits per tournament BEFORE joining tournaments and
     tournament_players, which is the same sum in far fewer rows. */
  RETURN QUERY
  WITH raw AS (
    SELECT t.amount,
           substring(t.notes from '\[tournament ([0-9a-f-]+)\]')::uuid AS tournament_id
      FROM public.union_wallet_transactions t
     WHERE t.union_id = p_union_id
       AND t.wallet = 'rake_wallet' AND t.direction = 'credit' AND t.tx_type = 'rake'
       AND t.created_at >= p_start AND t.created_at < p_end
  ), tsum AS (
    SELECT r.tournament_id, sum(r.amount) AS amt
      FROM raw r WHERE r.tournament_id IS NOT NULL GROUP BY r.tournament_id
  ), tgame AS (
    SELECT s.tournament_id, s.amt, COALESCE(lower(tr.tournament_type), 'other') AS game_type
      FROM tsum s LEFT JOIN public.tournaments tr ON tr.id = s.tournament_id
  ), cash AS (
    SELECT a.club_id, 'cash'::text AS game_type, sum(a.rake_share) AS rake
      FROM public.ca_union_rake_attribution a
     WHERE a.union_id = p_union_id
       AND a.played_at >= p_start AND a.played_at < p_end
       AND a.club_id IS NOT NULL
     GROUP BY a.club_id
  ), tw AS (
    SELECT tp.tournament_id, tp.club_id,
           sum(1 + COALESCE(tp.rebuys, 0) + CASE WHEN tp.add_on THEN 1 ELSE 0 END)::numeric AS w
      FROM public.tournament_players tp
      JOIN tsum s ON s.tournament_id = tp.tournament_id
     GROUP BY tp.tournament_id, tp.club_id
  ), tt AS (
    SELECT tw.tournament_id, sum(tw.w) AS total FROM tw GROUP BY tw.tournament_id
  ), tourney AS (
    SELECT tw.club_id, g.game_type, sum(g.amt * tw.w / NULLIF(tt.total, 0)) AS rake
      FROM tgame g
      JOIN tw ON tw.tournament_id = g.tournament_id
      JOIN tt ON tt.tournament_id = g.tournament_id
     WHERE tw.club_id IS NOT NULL
     GROUP BY tw.club_id, g.game_type
  ), basis AS (
    SELECT x.club_id, x.game_type, sum(x.rake) AS rake_in FROM (
      SELECT cash.club_id, cash.game_type, cash.rake FROM cash
      UNION ALL
      SELECT tourney.club_id, tourney.game_type, tourney.rake FROM tourney) x
     GROUP BY x.club_id, x.game_type
  )
  SELECT b.club_id,
         b.game_type,
         round(b.rake_in, 2) AS rake_in,
         COALESCE(
           CASE b.game_type
             WHEN 'cash'      THEN uc.rate_cash
             WHEN 'mtt'       THEN uc.rate_mtt
             WHEN 'sng'       THEN uc.rate_sng
             WHEN 'spin'      THEN uc.rate_spin
             WHEN 'satellite' THEN uc.rate_satellite
             ELSE NULL
           END,
           uc.club_commission_rate,
           0.90) AS rate,
         trunc(round(b.rake_in, 2)
               * COALESCE(
                   CASE b.game_type
                     WHEN 'cash'      THEN uc.rate_cash
                     WHEN 'mtt'       THEN uc.rate_mtt
                     WHEN 'sng'       THEN uc.rate_sng
                     WHEN 'spin'      THEN uc.rate_spin
                     WHEN 'satellite' THEN uc.rate_satellite
                     ELSE NULL
                   END,
                   uc.club_commission_rate,
                   0.90)
               * 100) / 100 AS payout
    FROM basis b
    JOIN public.union_clubs uc ON uc.union_id = p_union_id AND uc.club_id = b.club_id
   WHERE b.club_id <> p_union_id;
END;
$$;


ALTER FUNCTION public.fn_union_club_rake_basis(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_live boolean) OWNER TO postgres;

