-- Name: fn_union_club_scope(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_club_scope(p_union_id uuid) RETURNS TABLE(club_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT uc.club_id FROM union_clubs uc WHERE uc.union_id = p_union_id
  UNION
  SELECT p_union_id;
$$;


ALTER FUNCTION public.fn_union_club_scope(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_union_club_statement_of_account(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_club_statement_of_account(p_union_id uuid, p_club_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(entry_at timestamp with time zone, entry_type text, reference text, description text, amount numeric, running_balance numeric, status text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH entries AS (
    -- Weekly square-ups and the credit notes that adjust them. Positive means
    -- the club owes the union, so the direction of the document decides sign,
    -- and a credit note reverses that direction and therefore the sign.
    SELECT si.created_at AS entry_at,
           CASE WHEN si.invoice_type = 'union_weekly_credit_note'
                THEN 'credit_note' ELSE 'statement' END AS entry_type,
           COALESCE(si.invoice_number, si.id::text) AS reference,
           CASE WHEN si.invoice_type = 'union_weekly_credit_note'
                THEN 'Credit note against ' || COALESCE(si.breakdown->>'credit_note_for', '(unknown)')
                     || COALESCE(' - ' || (si.breakdown->>'reason'), '')
                ELSE 'Weekly statement '
                     || COALESCE(to_char((si.breakdown->>'period_start')::timestamptz, 'YYYY-MM-DD'), '?')
                     || ' to '
                     || COALESCE(to_char((si.breakdown->>'period_end')::timestamptz, 'YYYY-MM-DD'), '?')
                END AS description,
           CASE WHEN si.from_entity_type = 'club'
                THEN  si.net_amount
                ELSE -si.net_amount END AS amount,
           si.status, si.id AS entry_id
      FROM settlement_invoices si
     WHERE si.club_id = p_club_id
       AND si.invoice_type IN ('union_weekly_squareup', 'union_weekly_credit_note')
       AND (si.breakdown->>'union_id')::uuid = p_union_id

    UNION ALL

    -- Money the club has actually handed over reduces what it owes.
    SELECT p.received_at,
           'payment',
           COALESCE(p.reference, p.id::text),
           'Payment received'
             || COALESCE(' by ' || p.method, '')
             || CASE WHEN p.applied_settlement_id IS NULL THEN ' (unapplied)' ELSE '' END,
           -p.amount,
           CASE WHEN p.applied_settlement_id IS NULL THEN 'unapplied' ELSE 'applied' END, p.id
      FROM union_presettlements p
     WHERE p.union_id = p_union_id
       AND p.club_id = p_club_id
  )
  SELECT b.entry_at, b.entry_type, b.reference, b.description,
         b.amount, b.running_balance, b.status
    FROM (
      SELECT e.entry_at, e.entry_type, e.reference, e.description,
             round(e.amount, 2) AS amount,
             round(SUM(e.amount) OVER (ORDER BY e.entry_at, e.reference, e.entry_type, e.entry_id
                      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), 2) AS running_balance,
             e.status, e.entry_id
        FROM entries e
    ) b
   -- Filter the display only after computing the complete account balance.
   WHERE (p_since IS NULL OR b.entry_at >= p_since)
     AND (COALESCE(public.ca_can_view_club_finances(p_club_id), false)
          OR COALESCE(public.ca_can_oversee_union(p_union_id), false)
          OR COALESCE(public.fn_is_platform_admin(), false))
   ORDER BY b.entry_at, b.reference, b.entry_type, b.entry_id;
$$;


ALTER FUNCTION public.fn_union_club_statement_of_account(p_union_id uuid, p_club_id uuid, p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_union_club_statement_of_account(p_union_id uuid, p_club_id uuid, p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_club_statement_of_account(p_union_id uuid, p_club_id uuid, p_since timestamp with time zone) IS 'One ordered ledger of a club position with the union: weekly statements, credit notes and payments received, with a running balance. Positive means the club owes the union.';


--
-- Name: fn_union_commingling_report(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_commingling_report(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_buyin_uses_club_wallet boolean;
  v_seats_total bigint; v_seats_stamped bigint;
  v_multi_club bigint; v_club_chips jsonb;
BEGIN
  v_buyin_uses_club_wallet := EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname='public' AND p.proname='atomic_table_buyin'
       AND p.prosrc LIKE '%club_members%');

  SELECT count(*), count(*) FILTER (WHERE ts.club_id IS NOT NULL)
    INTO v_seats_total, v_seats_stamped
    FROM table_seats ts JOIN tables t ON t.id = ts.table_id
   WHERE ts.left_at IS NULL AND t.union_id = p_union_id;

  SELECT count(*) INTO v_multi_club FROM (
    SELECT cm.user_id
      FROM club_members cm
      JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = p_union_id
     GROUP BY cm.user_id HAVING count(DISTINCT cm.club_id) > 1) m;

  SELECT jsonb_object_agg(c.name, round(x.total))
    INTO v_club_chips
    FROM (SELECT cm.club_id, SUM(COALESCE(cm.chip_balance,0)) AS total
            FROM club_members cm
            JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = p_union_id
           GROUP BY cm.club_id) x
    JOIN clubs c ON c.id = x.club_id;

  RETURN jsonb_build_object(
    'buyin_debits_club_wallet', v_buyin_uses_club_wallet,
    'commingled', NOT v_buyin_uses_club_wallet,
    'active_union_seats', v_seats_total,
    'seats_with_club_provenance', v_seats_stamped,
    'players_in_multiple_clubs', v_multi_club,
    'club_chip_balances', v_club_chips,
    'note', CASE WHEN v_buyin_uses_club_wallet
                 THEN 'Buy-ins draw on the club wallet - provenance is real.'
                 ELSE 'Buy-ins still debit the single global player wallet, so club '
                      'wallets are commingled and rake attribution falls back to '
                      'first-joined. Club-scoped buy-in rollout required.' END
  );
END $$;


ALTER FUNCTION public.fn_union_commingling_report(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_union_credit_risk_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_credit_risk_check() RETURNS TABLE(invariant text, severity text, offenders bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 'union_club_no_terms', 'warning', count(*),
         'Member clubs with no union_club_terms row: no security deposit and '
         || 'no stop loss on file, so their losses are carried unsecured'
    FROM union_clubs uc
   WHERE NOT EXISTS (SELECT 1 FROM union_club_terms t
                      WHERE t.union_id = uc.union_id AND t.club_id = uc.club_id)
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_club_stop_loss_breached', 'critical', count(*),
         'Clubs past their weekly stop loss and still active: '
         || COALESCE(string_agg(x.club_name || ' (exposure ' || x.exposure || ' vs limit '
                                || x.stop_loss_limit || ')', '; '), '')
    FROM (
      SELECT e.club_name, e.exposure, e.stop_loss_limit
        FROM (SELECT DISTINCT t.union_id
                FROM union_club_terms t
               WHERE t.stop_loss_limit IS NOT NULL
                 AND t.status <> 'suspended') u
        CROSS JOIN LATERAL fn_union_club_exposure(u.union_id) e
       WHERE e.breached AND e.status <> 'suspended'
    ) x
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_eco_not_recorded', 'warning', count(*),
         'Unions with ECO enabled and no union_eco_ledger row for the current '
         || 'settlement week: this week''s win tax / loss rebate is not reproducible'
    FROM unions un
   WHERE COALESCE((un.settings->>'eco_enabled')::boolean, false)
     AND EXISTS (SELECT 1 FROM union_clubs uc WHERE uc.union_id = un.id)
     AND NOT EXISTS (SELECT 1 FROM union_eco_ledger l
                      WHERE l.union_id = un.id
                        AND l.period_start >= fn_union_week_start())
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_club_stakes_above_cap', 'warning', count(*),
         'Live tables above the club''s agreed stakes cap: '
         || COALESCE(string_agg(y.club_name || ' bb=' || y.big_blind
                                || ' cap=' || y.stakes_cap_bb, '; '), '')
    FROM (
      SELECT c.name AS club_name, tb.big_blind, t.stakes_cap_bb
        FROM union_club_terms t
        JOIN clubs c ON c.id = t.club_id
        JOIN tables tb ON tb.club_id = t.club_id
       WHERE t.stakes_cap_bb IS NOT NULL
         AND tb.big_blind > t.stakes_cap_bb
         AND COALESCE(tb.is_deleted, false) = false
         AND tb.status NOT IN ('closed','deleted')
    ) y
  HAVING count(*) > 0

  UNION ALL
  SELECT * FROM fn_anon_exposure_check();
$$;


ALTER FUNCTION public.fn_union_credit_risk_check() OWNER TO postgres;

--
-- Name: fn_union_credit_wallet(uuid, text, numeric, text, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_credit_wallet(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text DEFAULT NULL::text, p_club_id uuid DEFAULT NULL::uuid, p_period_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_op_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_prior jsonb;
  v_res jsonb;
BEGIN
  IF p_op_id IS NULL THEN
    RETURN public.fn_union_credit_wallet_zd3core(
      p_union_id, p_wallet, p_amount, p_tx_type, p_club_id, p_period_id, p_notes, p_created_by);
  END IF;

  SELECT result INTO v_prior
    FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_union_credit_wallet';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true, 'op_id', p_op_id);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_union_credit_wallet';
  END IF;

  INSERT INTO public.ca_op_claims (op_id, fn_name)
  VALUES (p_op_id, 'fn_union_credit_wallet');

  v_res := public.fn_union_credit_wallet_zd3core(
    p_union_id, p_wallet, p_amount, p_tx_type, p_club_id, p_period_id, p_notes, p_created_by);

  IF COALESCE(v_res->>'success', '') = 'true' THEN
    UPDATE public.ca_op_claims
       SET result = v_res, finalized_at = now()
     WHERE op_id = p_op_id AND fn_name = 'fn_union_credit_wallet';
  ELSE
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_union_credit_wallet';
  END IF;

  RETURN v_res;
END;
$$;


ALTER FUNCTION public.fn_union_credit_wallet(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid, p_op_id text) OWNER TO postgres;

--
-- Name: fn_union_credit_wallet_zd3core(uuid, text, numeric, text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_credit_wallet_zd3core(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_wallet_column text;
  v_before numeric;
  v_after numeric;
  v_sql text;
  v_cat text;
  v_cp text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  v_wallet_column := CASE lower(p_wallet)
    WHEN 'chip' THEN 'chip_balance'
    WHEN 'chip_balance' THEN 'chip_balance'
    WHEN 'rake' THEN 'rake_wallet'
    WHEN 'rake_wallet' THEN 'rake_wallet'
    WHEN 'bbj' THEN 'bbj_wallet'
    WHEN 'bbj_wallet' THEN 'bbj_wallet'
    WHEN 'promo' THEN 'promo_wallet'
    WHEN 'promo_wallet' THEN 'promo_wallet'
    WHEN 'insurance' THEN 'insurance_wallet'
    WHEN 'insurance_wallet' THEN 'insurance_wallet'
    ELSE NULL
  END;

  IF v_wallet_column IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown wallet: ' || p_wallet);
  END IF;

  -- Ensure wallet row exists
  INSERT INTO union_wallets (union_id, created_at, updated_at)
  VALUES (p_union_id, NOW(), NOW())
  ON CONFLICT (union_id) DO NOTHING;

  -- Read + lock before
  v_sql := format('SELECT COALESCE(%I,0) FROM union_wallets WHERE union_id = $1 FOR UPDATE', v_wallet_column);
  EXECUTE v_sql INTO v_before USING p_union_id;

  /* SAY WHERE THE CHIPS CAME FROM (2026-09-01). Declared immediately before
     the write and cleared immediately after, so it cannot leak onto an
     unrelated autoledger write later in the same transaction. An unmapped
     tx_type declares nothing and stays on settlement_suspense. */
  SELECT category, counterparty INTO v_cat, v_cp
    FROM public.fn_ca_union_wallet_ledger_shape(p_tx_type);
  IF v_cp IS NOT NULL THEN
    PERFORM public.fn_ca_declare_ledger(v_cat, v_cp);
  END IF;

  -- Update
  v_sql := format('UPDATE union_wallets SET %I = COALESCE(%I,0) + $1, updated_at = NOW() WHERE union_id = $2 RETURNING %I',
                  v_wallet_column, v_wallet_column, v_wallet_column);
  EXECUTE v_sql INTO v_after USING p_amount, p_union_id;

  IF v_cp IS NOT NULL THEN
    PERFORM set_config('app.ledger_counterparty', '', true);
    PERFORM set_config('app.ledger_category', '', true);
    PERFORM set_config('app.ledger_counterparty_entity', '', true);
  END IF;

  -- Audit
  INSERT INTO union_wallet_transactions (
    id, union_id, wallet, direction, amount, balance_after,
    tx_type, club_id, period_id, notes, created_by, created_at
  ) VALUES (
    gen_random_uuid(), p_union_id, v_wallet_column, 'credit', p_amount, v_after,
    COALESCE(p_tx_type, 'credit'), p_club_id, p_period_id, p_notes, p_created_by, NOW()
  );

  RETURN jsonb_build_object(
    'success', true, 'amount', p_amount,
    'wallet', v_wallet_column,
    'balance_before', v_before, 'balance_after', v_after
  );
END;
$_$;


ALTER FUNCTION public.fn_union_credit_wallet_zd3core(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid) OWNER TO postgres;

