--
-- Name: fn_union_debit_wallet_zd3core(uuid, text, numeric, text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_debit_wallet_zd3core(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_wallet_column text;
  v_before numeric;
  v_after numeric;
  v_sql text;
  v_cat text;
  v_cp text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  v_wallet_column := CASE lower(p_wallet)
    WHEN 'chip' THEN 'chip_balance'
    WHEN 'chip_balance' THEN 'chip_balance'
    WHEN 'rake' THEN 'rake_wallet'
    WHEN 'rake_wallet' THEN 'rake_wallet'
    WHEN 'bbj' THEN 'bbj_wallet'
    WHEN 'bbj_wallet' THEN 'bbj_wallet'
    WHEN 'promo' THEN 'promo_wallet'
    WHEN 'promo_wallet' THEN 'promo_wallet'
    WHEN 'insurance' THEN 'insurance_wallet'
    WHEN 'insurance_wallet' THEN 'insurance_wallet'
    ELSE NULL
  END;

  IF v_wallet_column IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown wallet: ' || p_wallet);
  END IF;

  v_sql := format('SELECT COALESCE(%I,0) FROM union_wallets WHERE union_id = $1 FOR UPDATE', v_wallet_column);
  EXECUTE v_sql INTO v_before USING p_union_id;

  IF v_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'union wallet not found');
  END IF;

  IF v_before < p_amount THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'insufficient balance',
      'wallet', v_wallet_column, 'balance', v_before, 'requested', p_amount
    );
  END IF;

  SELECT category, counterparty INTO v_cat, v_cp
    FROM public.fn_ca_union_wallet_ledger_shape(p_tx_type);
  IF v_cp IS NOT NULL THEN
    PERFORM public.fn_ca_declare_ledger(v_cat, v_cp);
  END IF;

  v_sql := format('UPDATE union_wallets SET %I = %I - $1, updated_at = NOW() WHERE union_id = $2 RETURNING %I',
                  v_wallet_column, v_wallet_column, v_wallet_column);
  EXECUTE v_sql INTO v_after USING p_amount, p_union_id;

  IF v_cp IS NOT NULL THEN
    PERFORM set_config('app.ledger_counterparty', '', true);
    PERFORM set_config('app.ledger_category', '', true);
    PERFORM set_config('app.ledger_counterparty_entity', '', true);
  END IF;

  INSERT INTO union_wallet_transactions (
    id, union_id, wallet, direction, amount, balance_after,
    tx_type, club_id, period_id, notes, created_by, created_at
  ) VALUES (
    gen_random_uuid(), p_union_id, v_wallet_column, 'debit', p_amount, v_after,
    COALESCE(p_tx_type, 'debit'), p_club_id, p_period_id, p_notes, p_created_by, NOW()
  );

  RETURN jsonb_build_object(
    'success', true, 'amount', p_amount,
    'wallet', v_wallet_column,
    'balance_before', v_before, 'balance_after', v_after
  );
END;
$_$;


ALTER FUNCTION public.fn_union_debit_wallet_zd3core(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid) OWNER TO postgres;

--
-- Name: fn_union_deposit_from_wallet(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_deposit_from_wallet(p_union_id uuid, p_amount numeric, p_notes text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_lead boolean;
  v_balance numeric;
  v_after numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authenticated');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM union_admins ua
     WHERE ua.union_id = p_union_id AND ua.user_id = v_uid AND ua.role = 'union_lead'
  ) OR EXISTS (
    SELECT 1 FROM unions u WHERE u.id = p_union_id AND u.owner_id = v_uid
  ) INTO v_is_lead;
  IF NOT v_is_lead THEN
    RETURN jsonb_build_object('success', false, 'error', 'union lead access required');
  END IF;

  SELECT balance INTO v_balance FROM wallets
   WHERE user_id = v_uid AND wallet_type = 'PLAYER' FOR UPDATE;
  IF v_balance IS NULL OR v_balance < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient wallet balance');
  END IF;
  UPDATE wallets SET balance = balance - p_amount, updated_at = NOW()
   WHERE user_id = v_uid AND wallet_type = 'PLAYER';

  INSERT INTO union_wallets (union_id, chip_balance)
  VALUES (p_union_id, p_amount)
  ON CONFLICT (union_id) DO UPDATE
    SET chip_balance = COALESCE(union_wallets.chip_balance, 0) + p_amount,
        updated_at = NOW()
  RETURNING chip_balance INTO v_after;

  INSERT INTO union_wallet_transactions (
    union_id, wallet, direction, amount, balance_after, tx_type, period_id, notes, created_by
  ) VALUES (
    p_union_id, 'chip_balance', 'credit', p_amount, v_after, 'owner_deposit',
    p_op_id, COALESCE(NULLIF(p_notes, ''), 'Union bank deposit from owner wallet'), v_uid
  );

  RETURN jsonb_build_object('success', true, 'amount', p_amount, 'union_balance', v_after);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('success', false, 'duplicate', true,
                            'error', 'operation already processed');
END;
$$;


ALTER FUNCTION public.fn_union_deposit_from_wallet(p_union_id uuid, p_amount numeric, p_notes text, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_union_dispute_invoice(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_dispute_invoice(p_invoice_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inv       settlement_invoices%ROWTYPE;
  v_union_id  uuid;
  v_period    settlement_periods%ROWTYPE;
  v_caller    uuid := auth.uid();
  v_period_marked boolean := false;
BEGIN
  SELECT * INTO v_inv FROM settlement_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF v_inv.id IS NULL THEN
    RAISE EXCEPTION 'invoice not found';
  END IF;

  v_union_id := (v_inv.breakdown->>'union_id')::uuid;

  -- WHO IS CALLING, before anything that would describe the document.
  IF v_caller IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM clubs c WHERE c.id = v_inv.club_id AND c.owner_id = v_caller)
     AND NOT EXISTS (SELECT 1 FROM club_members cm
                      WHERE cm.club_id = v_inv.club_id AND cm.user_id = v_caller
                        AND cm.role IN ('owner','co_owner','admin')
                        AND COALESCE(cm.status,'active') NOT IN ('banned','suspended'))
     AND NOT EXISTS (SELECT 1 FROM unions u WHERE u.id = v_union_id AND u.owner_id = v_caller)
     AND NOT EXISTS (SELECT 1 FROM union_admins ua WHERE ua.union_id = v_union_id AND ua.user_id = v_caller)
     AND NOT COALESCE(public.fn_is_platform_admin(), false) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  IF COALESCE(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'a dispute must carry a reason';
  END IF;
  IF v_inv.invoice_type <> 'union_weekly_squareup' THEN
    RAISE EXCEPTION 'only a weekly square-up can be disputed, this is %', v_inv.invoice_type;
  END IF;
  IF v_inv.status = 'disputed' THEN
    RETURN jsonb_build_object('success', true, 'already_disputed', true,
                              'invoice', COALESCE(v_inv.invoice_number, v_inv.id::text));
  END IF;

  UPDATE settlement_invoices
     SET status = 'disputed',
         notes = COALESCE(notes, '') || E'\nDISPUTED ' || to_char(now(), 'YYYY-MM-DD HH24:MI')
                 || ': ' || p_reason,
         updated_at = now()
   WHERE id = p_invoice_id;

  SELECT * INTO v_period FROM settlement_periods WHERE id = v_inv.period_id;
  IF v_period.id IS NOT NULL AND v_period.status NOT IN ('closed', 'disputed') THEN
    UPDATE settlement_periods SET status = 'disputed', updated_at = now()
     WHERE id = v_inv.period_id;
    v_period_marked := true;
  END IF;

  INSERT INTO notifications (user_id, type, title, message, data, read)
  SELECT DISTINCT uid, 'union_invoice_disputed',
         'Statement ' || COALESCE(v_inv.invoice_number, '') || ' disputed',
         COALESCE((v_inv.breakdown->>'club_name'), 'A club')
           || ' has disputed statement ' || COALESCE(v_inv.invoice_number, v_inv.id::text)
           || ': ' || p_reason,
         jsonb_build_object('invoice_id', v_inv.id, 'invoice_number', v_inv.invoice_number,
                            'club_id', v_inv.club_id, 'union_id', v_union_id,
                            'reason', p_reason, 'source', 'club_arena'),
         false
    FROM (
      SELECT u.owner_id AS uid FROM unions u WHERE u.id = v_union_id AND u.owner_id IS NOT NULL
      UNION
      SELECT ua.user_id FROM union_admins ua WHERE ua.union_id = v_union_id
    ) x WHERE uid IS NOT NULL;

  RETURN jsonb_build_object(
    'success', true,
    'invoice', COALESCE(v_inv.invoice_number, v_inv.id::text),
    'invoice_id', v_inv.id,
    'period_marked_disputed', v_period_marked,
    'period_status', COALESCE(v_period.status, '(none)'),
    'note', CASE WHEN v_period.status = 'closed'
                 THEN 'The period is closed and was not reopened. Resolve with a credit note.'
                 ELSE 'The period is marked disputed and will not be closed until resolved.' END);
END $$;


ALTER FUNCTION public.fn_union_dispute_invoice(p_invoice_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: fn_union_distribute_promo(uuid, text, uuid, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_distribute_promo(p_union_id uuid, p_target_kind text, p_target_id uuid, p_amount numeric, p_agent_club_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid; v_before numeric; v_after numeric; v_club uuid;
  v_role text; v_agent_row uuid;
begin
  v_actor := auth.uid();
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'amount must be > 0');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false, 'error', 'chips move in hundredths at most');
  end if;
  if p_target_kind not in ('club','agent') then
    return jsonb_build_object('success', false, 'error', 'target must be club or agent');
  end if;

  if coalesce(auth.role(),'') <> 'service_role' then
    if v_actor is null or not exists (select 1 from unions where id=p_union_id and owner_id=v_actor) then
      return jsonb_build_object('success', false, 'error', 'only the union owner may distribute promo');
    end if;
  end if;

  select coalesce(promo_wallet,0) into v_before
    from union_wallets where union_id = p_union_id for update;
  if v_before is null then
    return jsonb_build_object('success', false, 'error', 'union wallet not found');
  end if;
  if v_before < p_amount then
    return jsonb_build_object('success', false, 'error', 'insufficient union promo balance',
                              'balance', v_before, 'requested', p_amount);
  end if;

  if p_target_kind = 'club' then
    if not exists (select 1 from clubs where id=p_target_id and union_id=p_union_id) then
      return jsonb_build_object('success', false, 'error', 'club is not in this union');
    end if;
    v_club := p_target_id;
    update clubs set promo_balance = coalesce(promo_balance,0) + p_amount, updated_at = now()
     where id = p_target_id returning promo_balance into v_after;
  else
    if p_agent_club_id is null then
      return jsonb_build_object('success', false, 'error', 'p_agent_club_id required for agent target');
    end if;
    if not exists (select 1 from clubs where id=p_agent_club_id and union_id=p_union_id) then
      return jsonb_build_object('success', false, 'error', 'agent club is not in this union');
    end if;
    select role into v_role from club_members
     where club_id=p_agent_club_id and user_id=p_target_id
       and role in ('agent','super_agent','sub_agent','owner','co_owner','admin')
       and coalesce(status,'active') in ('active','approved')
     limit 1;
    if v_role is null then
      return jsonb_build_object('success', false, 'error', 'target is not an agent in that club');
    end if;
    v_club := p_agent_club_id;
    v_agent_row := public.fn_ensure_agent_row(p_agent_club_id, p_target_id, v_role);
    if v_agent_row is null then
      raise exception 'could not ensure agents row for % in club %', p_target_id, p_agent_club_id;
    end if;
    update agents set promo_wallet_balance = coalesce(promo_wallet_balance,0) + p_amount,
                      updated_at = now()
     where id = v_agent_row returning promo_wallet_balance into v_after;
  end if;

  update union_wallets set promo_wallet = promo_wallet - p_amount where union_id = p_union_id;

  insert into union_wallet_transactions
    (id, union_id, wallet, direction, amount, balance_after, tx_type, club_id, notes, created_by, created_at)
  values (gen_random_uuid(), p_union_id, 'promo_wallet', 'debit', p_amount, v_before - p_amount,
          'promo_union_to_' || p_target_kind, v_club,
          coalesce(p_note, format('Union promo distribution to %s', p_target_kind)), v_actor, now());

  return jsonb_build_object('success', true, 'amount', p_amount, 'target_kind', p_target_kind,
                            'union_balance_after', v_before - p_amount, 'target_balance_after', v_after);
end;
$$;


ALTER FUNCTION public.fn_union_distribute_promo(p_union_id uuid, p_target_kind text, p_target_id uuid, p_amount numeric, p_agent_club_id uuid, p_note text) OWNER TO postgres;

--
-- Name: fn_union_distribution_check(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_distribution_check(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from timestamptz := COALESCE(p_since, public.fn_union_week_start(now()));
  v_rake numeric; v_comm numeric; v_rb numeric;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_union_overseer(p_union_id, auth.uid()))) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  SELECT COALESCE(SUM(rr.rake_amount),0) INTO v_rake
    FROM rake_records rr
    JOIN union_clubs uc ON uc.club_id = rr.club_id AND uc.union_id = p_union_id
   WHERE rr.created_at >= v_from;

  SELECT COALESCE(SUM(ac.amount),0) INTO v_comm
    FROM agent_commissions ac
    JOIN union_clubs uc ON uc.club_id = ac.club_id AND uc.union_id = p_union_id
   WHERE ac.created_at >= v_from;

  SELECT COALESCE(SUM(rp.rakeback_amount),0) INTO v_rb
    FROM rakeback_periods rp
    JOIN union_clubs uc ON uc.club_id = rp.club_id AND uc.union_id = p_union_id
   WHERE rp.period_start >= v_from::date;

  RETURN jsonb_build_object(
    'period_start', v_from,
    'rake_collected', round(v_rake,2),
    'agent_commissions', round(v_comm,2),
    'player_rakeback', round(v_rb,2),
    'total_distributed', round(v_comm + v_rb, 2),
    'over_distributed_by', round(GREATEST((v_comm + v_rb) - v_rake, 0), 2),
    'healthy', (v_comm + v_rb) <= v_rake * 1.001,
    'note', 'Player rakeback is funded from the agent''s commission, so '
            || 'commissions + rakeback must not exceed the rake collected.'
  );
END $$;


ALTER FUNCTION public.fn_union_distribution_check(p_union_id uuid, p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_eco_adjustment(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_eco_adjustment(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, players_won numeric, rake_generated numeric, cash_players_won numeric, cash_rake numeric, tournament_rake numeric, total_rake_generated numeric, club_commission_rate numeric, rake_earned numeric, eco_base numeric, eco_rate numeric, eco_amount numeric, direction text, union_net_eco numeric, eco_base_mode text, baseline_cash_exact boolean, include_horses boolean, eco_enabled boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rate  numeric := fn_union_eco_rate(p_union_id);
  v_on    boolean := fn_union_eco_enabled(p_union_id);
  v_mode  text    := fn_union_eco_base_mode(p_union_id);
  v_horse boolean := fn_union_eco_include_horses(p_union_id);
  v_prev  jsonb   := fn_union_pnl_baseline(p_union_id, p_start);
  v_exact boolean;
BEGIN
  IF v_mode NOT IN ('club_cash_profit','net_invoice_position',
                    'winnings_plus_rake','winnings_only') THEN
    RAISE EXCEPTION 'unknown eco_base_mode: %', v_mode USING ERRCODE = '22023';
  END IF;

  v_exact := (v_prev IS NULL)
             OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_prev) e
                             WHERE NOT (e ? 'seated_end_cash'));

  RETURN QUERY
  WITH rep AS (
    SELECT r.club_id, r.club_name, r.settle_net, r.rake_paid
      FROM fn_union_reconciliation_report(p_union_id, p_start, p_end) r
  ),
  cash AS (
    SELECT c.club_id, c.realized_net, c.seated_stack
      FROM fn_union_pnl_cash_by_club(p_union_id, p_start, p_end, v_horse) c
  ),
  /* Phase 6 (20260907): ONE basis. The same rows round 1 pays on, per club,
     split by game type; rake_earned is the payout round 1 makes (per game
     type, truncated to the cent), not a rate applied to a different total. */
  basis AS (
    SELECT b.club_id,
           round(sum(b.rake_in), 2)                                          AS rake,
           round(COALESCE(sum(b.rake_in) FILTER (WHERE b.game_type = 'cash'), 0), 2)  AS cash_rake,
           round(COALESCE(sum(b.rake_in) FILTER (WHERE b.game_type <> 'cash'), 0), 2) AS tournament_rake,
           round(sum(b.payout), 2)                                           AS payout
      FROM fn_union_club_rake_basis(p_union_id, p_start, p_end) b
     GROUP BY b.club_id
  ),
  cash_base AS (
    SELECT (e->>'club_id')::uuid AS club_id,
           COALESCE((e->>'seated_end_cash')::numeric, (e->>'seated_end')::numeric)
             AS seated_start
      FROM jsonb_array_elements(COALESCE(v_prev, '[]'::jsonb)) e
  ),
  rb AS (
    SELECT uc.club_id, COALESCE(uc.club_commission_rate, 0.90) AS rate
      FROM union_clubs uc WHERE uc.union_id = p_union_id
  ),
  calc AS (
    SELECT rep.club_id, rep.club_name,
           round(rep.settle_net - rep.rake_paid, 2) AS players_won,
           COALESCE(bs.rake, 0)                     AS rake_generated,
           round(COALESCE(cash.realized_net, 0)
                 + (COALESCE(cash.seated_stack, 0)
                    - COALESCE(cb.seated_start, COALESCE(cash.seated_stack, 0))), 2)
             AS cash_players_won,
           COALESCE(bs.cash_rake, 0)                AS cash_rake,
           COALESCE(bs.tournament_rake, 0)          AS tournament_rake,
           COALESCE(bs.rake, 0)                     AS total_rake_generated,
           COALESCE(rb.rate, 0.90)                  AS club_commission_rate,
           COALESCE(bs.payout, 0)                   AS rake_earned
      FROM rep
      LEFT JOIN cash      ON cash.club_id = rep.club_id
      LEFT JOIN basis bs  ON bs.club_id = rep.club_id
      LEFT JOIN cash_base cb ON cb.club_id = rep.club_id
      LEFT JOIN rb        ON rb.club_id = rep.club_id
  ),
  based AS (
    SELECT calc.*,
           round(CASE v_mode
             WHEN 'club_cash_profit' THEN
               calc.rake_earned - calc.cash_players_won
             WHEN 'net_invoice_position' THEN
               calc.players_won + calc.rake_generated + calc.rake_earned
             WHEN 'winnings_plus_rake' THEN
               calc.players_won + calc.rake_generated
             ELSE
               calc.players_won
           END, 2) AS eco_base
      FROM calc
  ),
  amt AS (
    SELECT based.*, round(-v_rate * based.eco_base, 2) AS eco_amount FROM based
  ),
  agg AS (SELECT round(SUM(-amt.eco_amount), 2) AS union_net FROM amt)
  SELECT amt.club_id, amt.club_name, amt.players_won, amt.rake_generated,
         amt.cash_players_won, amt.cash_rake, amt.tournament_rake,
         amt.total_rake_generated, amt.club_commission_rate, amt.rake_earned,
         amt.eco_base, v_rate, amt.eco_amount,
         CASE WHEN amt.eco_amount < 0 THEN 'club pays union (profitable week)'
              WHEN amt.eco_amount > 0 THEN 'union pays club (losing week)'
              ELSE 'square' END::text,
         agg.union_net, v_mode, v_exact, v_horse, v_on
    FROM amt CROSS JOIN agg
   ORDER BY amt.eco_amount;
END;
$$;


