--
-- Name: fn_union_eco_record(uuid, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_eco_record(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_settlement_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_rows int;
  v_mode text := fn_union_eco_base_mode(p_union_id);
BEGIN
  IF v_caller IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM unions u WHERE u.id = p_union_id AND u.owner_id = v_caller)
     AND NOT EXISTS (SELECT 1 FROM union_admins ua
                      WHERE ua.union_id = p_union_id AND ua.user_id = v_caller) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authorized');
  END IF;

  INSERT INTO union_eco_ledger (union_id, club_id, period_start, period_end,
                                eco_base, eco_rate, eco_amount, eco_base_mode,
                                cash_players_won, total_rake_generated,
                                rake_earned, club_commission_rate, include_horses,
                                settlement_id)
  SELECT p_union_id, e.club_id, p_start, p_end, e.eco_base, e.eco_rate,
         e.eco_amount, v_mode, e.cash_players_won, e.total_rake_generated,
         e.rake_earned, e.club_commission_rate, e.include_horses, p_settlement_id
    FROM fn_union_eco_adjustment(p_union_id, p_start, p_end) e
  ON CONFLICT (union_id, club_id, period_start) DO UPDATE
    SET period_end            = EXCLUDED.period_end,
        eco_base              = EXCLUDED.eco_base,
        eco_rate              = EXCLUDED.eco_rate,
        eco_amount            = EXCLUDED.eco_amount,
        eco_base_mode         = EXCLUDED.eco_base_mode,
        cash_players_won      = EXCLUDED.cash_players_won,
        total_rake_generated  = EXCLUDED.total_rake_generated,
        rake_earned           = EXCLUDED.rake_earned,
        club_commission_rate  = EXCLUDED.club_commission_rate,
        include_horses        = EXCLUDED.include_horses,
        settlement_id         = COALESCE(EXCLUDED.settlement_id, union_eco_ledger.settlement_id),
        computed_at           = now();
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  RETURN jsonb_build_object('success', true, 'clubs', v_rows, 'eco_base_mode', v_mode,
                            'period_start', p_start, 'period_end', p_end);
END;
$$;


ALTER FUNCTION public.fn_union_eco_record(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_settlement_id uuid) OWNER TO postgres;

--
-- Name: fn_union_eco_record_current_week(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_eco_record_current_week(p_union_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  u record;
  v_start timestamptz := fn_union_week_start();
  v_out jsonb := '[]'::jsonb;
  v_res jsonb;
BEGIN
  FOR u IN
    SELECT un.id FROM unions un
     WHERE (p_union_id IS NULL OR un.id = p_union_id)
       AND COALESCE((un.settings->>'eco_enabled')::boolean, false)
       AND EXISTS (SELECT 1 FROM union_clubs uc WHERE uc.union_id = un.id)
  LOOP
    BEGIN
      v_res := fn_union_eco_record(u.id, v_start, now(), NULL);
      v_out := v_out || jsonb_build_array(v_res);
    EXCEPTION WHEN OTHERS THEN
      v_out := v_out || jsonb_build_array(
        jsonb_build_object('union_id', u.id, 'success', false, 'error', SQLERRM));
    END;
  END LOOP;

  RETURN jsonb_build_object('week_start', v_start, 'unions', v_out);
END;
$$;


ALTER FUNCTION public.fn_union_eco_record_current_week(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_union_enforce_stop_loss(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_enforce_stop_loss(p_union_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r           record;
  v_suspended int := 0;
  v_restored  int := 0;
  v_out       jsonb := '[]'::jsonb;
  v_gate_open boolean;
  v_grace     int;
  v_overdue   numeric;
  v_reason    text;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_platform_admin())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  v_gate_open := public.fn_union_setting(p_union_id, 'weekly_invoices_enabled', 1) = 1;
  v_grace     := COALESCE(public.fn_union_setting(p_union_id, 'suspend_after_days_overdue', 7), 7)::int;

  FOR r IN
    SELECT * FROM public.fn_union_club_exposure(p_union_id) e WHERE e.terms_on_file
  LOOP
    -- What this club owes on statements that are past due plus grace, net of
    -- credit notes. Only counted while the union is actually issuing statements.
    SELECT COALESCE(SUM(public.fn_union_invoice_outstanding(si.id)), 0)
      INTO v_overdue
      FROM settlement_invoices si
     WHERE si.invoice_type = 'union_weekly_squareup'
       AND si.club_id = r.club_id
       AND (si.breakdown->>'union_id')::uuid = p_union_id
       AND si.status = 'overdue'
       AND si.due_at < now() - make_interval(days => v_grace);

    v_reason := NULL;
    IF r.breached THEN
      v_reason := 'stop_loss_breached: exposure '
                  || to_char(r.exposure, 'FM999,999,999,990.00')
                  || ' over limit ' || to_char(r.stop_loss_limit, 'FM999,999,999,990.00');
    ELSIF v_gate_open AND v_overdue > 0.005 THEN
      v_reason := 'stop_loss_breached: ' || to_char(v_overdue, 'FM999,999,999,990.00')
                  || ' unpaid more than ' || v_grace || ' days past due';
    END IF;

    IF v_reason IS NOT NULL AND r.status = 'active' THEN
      UPDATE union_club_terms t
         SET status = 'suspended', suspended_at = now(),
             suspended_reason = v_reason, updated_at = now()
       WHERE t.union_id = p_union_id AND t.club_id = r.club_id;

      INSERT INTO financial_alerts (source, severity, message, context)
      VALUES ('fn_union_enforce_stop_loss', 'critical',
              r.club_name || ' suspended: ' || v_reason
              || '. It resumes automatically once the position is back inside the limit '
              || 'and nothing is past due.',
              jsonb_build_object('union_id', p_union_id, 'club_id', r.club_id,
                                 'club_name', r.club_name, 'exposure', r.exposure,
                                 'stop_loss_limit', r.stop_loss_limit,
                                 'overdue_past_grace', v_overdue,
                                 'security_deposit', r.security_deposit,
                                 'presettled', r.presettled));
      v_suspended := v_suspended + 1;
      v_out := v_out || jsonb_build_array(jsonb_build_object(
        'club_id', r.club_id, 'club_name', r.club_name, 'action', 'suspended',
        'reason', v_reason));

    ELSIF v_reason IS NULL AND r.status = 'suspended' THEN
      UPDATE union_club_terms t
         SET status = 'active', suspended_at = NULL, suspended_reason = NULL, updated_at = now()
       WHERE t.union_id = p_union_id AND t.club_id = r.club_id
         AND t.suspended_reason LIKE 'stop_loss_breached:%';

      IF FOUND THEN
        v_restored := v_restored + 1;
        v_out := v_out || jsonb_build_array(jsonb_build_object(
          'club_id', r.club_id, 'club_name', r.club_name, 'action', 'restored'));
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('union_id', p_union_id,
    'suspended', v_suspended, 'restored', v_restored,
    'dunning_gated', NOT v_gate_open,
    'detail', v_out, 'ran_at', now());
END $$;


ALTER FUNCTION public.fn_union_enforce_stop_loss(p_union_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_union_enforce_stop_loss(p_union_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_enforce_stop_loss(p_union_id uuid) IS 'Suspends a member club whose weekly exposure passes its stop_loss_limit and restores it when the exposure comes back inside. No-op for any club with no union_club_terms row. Runs hourly from fn_union_integrity_sweep_all.';


--
-- Name: fn_union_expel_club(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_expel_club(p_union_id uuid, p_club_id uuid, p_reason text DEFAULT NULL::text, p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_blockers jsonb; v_is_member boolean;
BEGIN
  IF NOT public.fn_is_union_overseer(p_union_id, auth.uid()) AND NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  SELECT EXISTS (SELECT 1 FROM union_clubs WHERE union_id = p_union_id AND club_id = p_club_id)
    INTO v_is_member;
  IF NOT v_is_member THEN
    RETURN jsonb_build_object('success', false, 'error', 'club_not_in_union');
  END IF;

  v_blockers := public.fn_union_club_exit_blockers(p_union_id, p_club_id);

  IF NOT (v_blockers->>'clear_to_exit')::boolean AND NOT p_force THEN
    RETURN jsonb_build_object('success', false, 'error', 'club_not_quiet',
                              'blockers', v_blockers,
                              'hint', 'settle and empty the club, or call with p_force => true');
  END IF;

  DELETE FROM union_clubs WHERE union_id = p_union_id AND club_id = p_club_id;
  UPDATE clubs SET union_id = NULL, updated_at = now()
   WHERE id = p_club_id AND union_id = p_union_id;

  -- The club stops hosting union games; its own private games are unaffected.
  UPDATE tables SET union_id = NULL, updated_at = now()
   WHERE club_id = p_club_id AND union_id = p_union_id;
  UPDATE tournaments SET union_id = NULL, updated_at = now()
   WHERE club_id = p_club_id AND union_id = p_union_id;

  UPDATE unions SET club_count = GREATEST(COALESCE(club_count,1) - 1, 0), updated_at = now()
   WHERE id = p_union_id;

  INSERT INTO audit_trail (actor_id, actor_role, action, target_type, target_id, reason)
  VALUES (auth.uid(), 'union_owner', 'expel_club_from_union', 'club', p_club_id,
          COALESCE(p_reason,'no reason given')
            || CASE WHEN p_force THEN ' [FORCED over blockers: ' || v_blockers::text || ']' ELSE '' END);

  INSERT INTO financial_alerts (severity, source, message, context)
  VALUES (CASE WHEN p_force THEN 'critical' ELSE 'warning' END,
          'fn_union_expel_club',
          'Club removed from union' || CASE WHEN p_force THEN ' (FORCED)' ELSE '' END,
          jsonb_build_object('union_id', p_union_id, 'club_id', p_club_id,
                             'reason', p_reason, 'blockers', v_blockers));

  RETURN jsonb_build_object('success', true, 'club_id', p_club_id,
                            'forced', p_force, 'blockers_at_exit', v_blockers);
END $$;


ALTER FUNCTION public.fn_union_expel_club(p_union_id uuid, p_club_id uuid, p_reason text, p_force boolean) OWNER TO postgres;

--
-- Name: fn_union_fund_bbj_pool(uuid, numeric, numeric, numeric, numeric, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_fund_bbj_pool(p_union_id uuid, p_amount numeric, p_main_pct numeric DEFAULT 50, p_backup_pct numeric DEFAULT 25, p_promo_pct numeric DEFAULT 25, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_balance numeric;
  v_after numeric;
  v_pool_id uuid;
  v_main numeric;
  v_backup numeric;
  v_promo numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0, to two decimals');
  END IF;
  IF ROUND(COALESCE(p_main_pct,0) + COALESCE(p_backup_pct,0) + COALESCE(p_promo_pct,0)) <> 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'split percentages must total 100');
  END IF;

  SELECT id INTO v_pool_id FROM bbj_pools WHERE union_id = p_union_id AND status = 'active' FOR UPDATE;
  IF v_pool_id IS NULL THEN
    RAISE EXCEPTION 'no active BBJ pool for union %', p_union_id;
  END IF;

  SELECT chip_balance INTO v_balance FROM union_wallets
   WHERE union_id = p_union_id FOR UPDATE;
  IF v_balance IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'union wallet not found');
  END IF;
  IF v_balance < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient union chip balance',
                              'balance', v_balance, 'requested', p_amount);
  END IF;

  /* DECLARED (Phase 4.3): one move, union bank -> the pool's banks. The
     union-side write is autoskipped; the pool-side writes are journalled as
     union_wallet -> bbj_pool, one leg per bank, which is what the per-bank
     reconcile reads. */
  PERFORM set_config('app.ledger_autoskip_union_wallets', '1', true);
  UPDATE union_wallets
     SET chip_balance = chip_balance - p_amount, updated_at = NOW()
   WHERE union_id = p_union_id
   RETURNING chip_balance INTO v_after;
  PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);

  v_main   := ROUND(p_amount * p_main_pct / 100.0, 2);
  v_backup := ROUND(p_amount * p_backup_pct / 100.0, 2);
  v_promo  := ROUND(p_amount - v_main - v_backup, 2);
  PERFORM public.fn_ca_declare_ledger('transfer', 'union_wallet', p_union_id, NULL,
                                      CASE WHEN p_op_id IS NULL THEN NULL ELSE 'bbj_fund:' || p_op_id::text END, NULL);
  UPDATE bbj_pools
     SET main_balance      = COALESCE(main_balance, 0) + v_main,
         backup_balance    = COALESCE(backup_balance, 0) + v_backup,
         promo_balance     = COALESCE(promo_balance, 0) + v_promo,
         total_contributed = COALESCE(total_contributed, 0) + p_amount,
         updated_at        = NOW()
   WHERE id = v_pool_id;
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_idempotency_key', '', true);

  INSERT INTO union_wallet_transactions (
    union_id, wallet, direction, amount, balance_after, tx_type, period_id, notes, created_by
  ) VALUES (
    p_union_id, 'chip_balance', 'debit', p_amount, v_after, 'bbj_fund',
    p_op_id, COALESCE(NULLIF(p_notes, ''), 'Union bank -> shared BBJ pool'), p_created_by
  );

  RETURN jsonb_build_object(
    'success', true, 'amount', p_amount, 'pool_id', v_pool_id,
    'main', v_main, 'backup', v_backup, 'promo', v_promo,
    'union_balance_after', v_after
  );
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('success', false, 'duplicate', true,
                            'error', 'operation already processed');
END;
$$;


ALTER FUNCTION public.fn_union_fund_bbj_pool(p_union_id uuid, p_amount numeric, p_main_pct numeric, p_backup_pct numeric, p_promo_pct numeric, p_notes text, p_created_by uuid, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_union_fund_promo_from_bank(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_fund_promo_from_bank(p_union_id uuid, p_amount numeric, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid; v_bank numeric; v_promo numeric;
BEGIN
  v_actor := auth.uid();
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  IF COALESCE(auth.role(),'') <> 'service_role' THEN
    IF v_actor IS NULL OR NOT EXISTS (SELECT 1 FROM unions WHERE id=p_union_id AND owner_id=v_actor) THEN
      RETURN jsonb_build_object('success', false, 'error', 'only the union owner may fund the promo wallet');
    END IF;
  END IF;

  SELECT COALESCE(chip_balance,0), COALESCE(promo_wallet,0) INTO v_bank, v_promo
    FROM union_wallets WHERE union_id = p_union_id FOR UPDATE;
  IF v_bank IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'union wallet not found');
  END IF;
  IF v_bank < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient union bank balance',
                              'bank_balance', v_bank, 'requested', p_amount);
  END IF;

  UPDATE union_wallets
     SET chip_balance = chip_balance - p_amount,
         promo_wallet = COALESCE(promo_wallet,0) + p_amount
   WHERE union_id = p_union_id;

  UPDATE unions SET promo_funded_from_bank = COALESCE(promo_funded_from_bank,0) + p_amount,
                    updated_at = NOW()
   WHERE id = p_union_id;

  INSERT INTO union_wallet_transactions
    (id, union_id, wallet, direction, amount, balance_after, tx_type, notes, created_by, created_at)
  VALUES
    (gen_random_uuid(), p_union_id, 'chip_balance', 'debit',  p_amount, v_bank - p_amount,
     'promo_bank_topup', COALESCE(p_note,'Owner funded promo wallet from main bank'), v_actor, NOW()),
    (gen_random_uuid(), p_union_id, 'promo_wallet', 'credit', p_amount, v_promo + p_amount,
     'promo_bank_topup', COALESCE(p_note,'Owner funded promo wallet from main bank'), v_actor, NOW());

  RETURN jsonb_build_object('success', true, 'amount', p_amount,
                            'bank_after', v_bank - p_amount, 'promo_after', v_promo + p_amount);
END;
$$;


ALTER FUNCTION public.fn_union_fund_promo_from_bank(p_union_id uuid, p_amount numeric, p_note text) OWNER TO postgres;

--
-- Name: fn_union_governance_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_governance_check() RETURNS TABLE(invariant text, severity text, offenders bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 'club_owned_cash_table_in_union', 'critical', count(*),
         'Open cash tables under a union club with no union_id and not private'
    FROM tables t JOIN union_clubs uc ON uc.club_id = t.club_id
   WHERE t.union_id IS NULL AND COALESCE(t.is_private,false) = false
     AND t.tournament_id IS NULL AND COALESCE(t.is_deleted,false) = false
     AND t.status NOT IN ('closed','deleted')
  HAVING count(*) > 0

  UNION ALL
  SELECT 'club_owned_tournament_in_union', 'critical', count(*),
         'Live non-private tournaments under a union club with no union_id'
    FROM tournaments t JOIN union_clubs uc ON uc.club_id = t.club_id
   WHERE t.union_id IS NULL AND COALESCE(t.is_private,false) = false
     AND t.status IN ('ANNOUNCED','SCHEDULED','REGISTERING','LATE_REG','RUNNING')
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_game_not_owned_by_union', 'critical', count(*),
         'Live union games whose club_id names a member club instead of the union '
         || '(cash/MTT/SNG/Spin)'
    FROM (
      SELECT id FROM tables
       WHERE union_id IS NOT NULL AND COALESCE(is_private,false) = false
         AND club_id IS DISTINCT FROM union_id
         AND COALESCE(is_deleted,false) = false AND status NOT IN ('closed','deleted')
      UNION ALL
      SELECT id FROM tournaments
       WHERE union_id IS NOT NULL AND COALESCE(is_private,false) = false
         AND club_id IS DISTINCT FROM union_id
         AND status IN ('ANNOUNCED','SCHEDULED','REGISTERING','LATE_REG','RUNNING')
    ) x
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_lost_a_member_club', 'critical', count(*),
         'Clubs expected in Midway Union that are no longer members'
    FROM (
      SELECT c.id FROM clubs c
       WHERE c.id IN ('a0000000-0000-0000-0000-000000000001',
                      'a41434bb-8d0c-400a-8f0d-e8b3d65afed4')
         AND NOT EXISTS (SELECT 1 FROM union_clubs uc
                          WHERE uc.club_id = c.id
                            AND uc.union_id = 'fade0000-0000-0000-0000-000000000001')
    ) m
  HAVING count(*) > 0

  UNION ALL
  SELECT 'clubs_union_id_mirror_drift', 'critical', count(*),
         'clubs.union_id disagrees with union_clubs'
    FROM union_clubs uc JOIN clubs c ON c.id = uc.club_id
   WHERE c.union_id IS DISTINCT FROM uc.union_id
  HAVING count(*) > 0

  UNION ALL
  SELECT 'private_game_union_visible', 'critical', count(*),
         'Rows flagged private that still carry a union_id'
    FROM (
      SELECT id FROM tables WHERE COALESCE(is_private,false) AND union_id IS NOT NULL
      UNION ALL
      SELECT id FROM tournaments WHERE COALESCE(is_private,false) AND union_id IS NOT NULL
    ) x
  HAVING count(*) > 0

  UNION ALL
  SELECT 'ownership_triggers_missing', 'critical', 5 - count(*),
         'Expected 5 union ownership/mirror triggers'
    FROM pg_trigger
   WHERE tgname IN ('trg_tables_union_ownership','trg_tournaments_union_ownership',
                    'trg_union_clubs_sync_mirror','trg_tables_union_ownership_upd',
                    'trg_tournaments_union_ownership_upd')
  HAVING count(*) < 5

  UNION ALL
  SELECT 'tables_rls_not_private_aware', 'critical', 1,
         'tables SELECT policy no longer considers is_private'
   WHERE NOT EXISTS (
     SELECT 1 FROM pg_policy
      WHERE polrelid = 'public.tables'::regclass AND polcmd = 'r'
        AND pg_get_expr(polqual, polrelid) LIKE '%is_private%')

  UNION ALL
  SELECT 'union_clubs_unreadable_by_members', 'critical', 1,
         'A club member can no longer discover their own union (union_clubs RLS)'
   WHERE NOT EXISTS (
     SELECT 1 FROM pg_policy
      WHERE polrelid = 'public.union_clubs'::regclass AND polcmd = 'r'
        AND pg_get_expr(polqual, polrelid) LIKE '%club_members%')

  UNION ALL
  SELECT 'union_rake_wallet_stale', 'warning', count(*),
         'Union rake wallets holding a balance with no rakeback in 14 days'
    FROM union_wallets uw
   WHERE uw.rake_wallet > 0
     AND NOT EXISTS (
       SELECT 1 FROM union_wallet_transactions t
        WHERE t.union_id = uw.union_id AND t.wallet = 'rake_wallet'
          AND t.direction = 'debit' AND t.created_at > now() - interval '14 days')
  HAVING count(*) > 0

  UNION ALL
  SELECT 'settlement_needs_review', 'warning', count(*),
         'Player P&L periods parked for review and never re-settled'
    FROM union_pnl_settlements WHERE status = 'needs_review'
  HAVING count(*) > 0

  UNION ALL
  SELECT 'settlement_period_overdue_open', 'warning', count(*),
         'settlement_periods still open/processing more than 24h past end_at'
    FROM settlement_periods
   WHERE status IN ('open','processing') AND end_at < now() - interval '24 hours'
  HAVING count(*) > 0

  UNION ALL
  SELECT 'settlement_period_orphan', 'critical', count(*),
         'settlement_periods with NULL club_id AND NULL union_id'
    FROM settlement_periods
   WHERE club_id IS NULL AND union_id IS NULL
  HAVING count(*) > 0

  UNION ALL
  -- 2026-08-20: the rake rollup is a speed cache only (a stale day is
  -- recomputed live), so this is a WARNING, not a correctness alarm: it means
  -- the settlement will do that work inline while holding treasury locks.
  SELECT 'union_rake_rollup_unmaintained', 'warning', count(*),
         'Unions with 3+ missing rake rollup days in the last week - the '
         || 'weekly settlement would recompute them while holding treasury locks'
    FROM (
      SELECT un.id,
             (SELECT count(*)
                FROM generate_series((now() AT TIME ZONE 'UTC')::date - 7,
                                     (now() AT TIME ZONE 'UTC')::date - 1,
                                     interval '1 day') gs
               WHERE NOT EXISTS (SELECT 1 FROM union_rake_rollup_days rd
                                  WHERE rd.union_id = un.id
                                    AND rd.day = gs::date)) AS stale_days
        FROM unions un
       WHERE EXISTS (SELECT 1 FROM union_clubs uc WHERE uc.union_id = un.id)
    ) s
   WHERE s.stale_days >= 3
  HAVING count(*) > 0

  UNION ALL
  SELECT * FROM fn_union_credit_risk_check()
$$;


ALTER FUNCTION public.fn_union_governance_check() OWNER TO postgres;

--
-- Name: fn_union_hierarchy_warnings(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_hierarchy_warnings() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_c jsonb; v_d jsonb; v_out jsonb := '[]'::jsonb;
BEGIN
  v_c := public.fn_union_agent_coverage();

  IF (v_c->>'players_without_agent')::bigint > 0 THEN
    v_out := v_out || jsonb_build_object('check','players_without_agent',
      'count', (v_c->>'players_without_agent')::bigint);
  END IF;
  IF (v_c->>'agents_orphaned')::bigint > 0 THEN
    v_out := v_out || jsonb_build_object('check','agents_without_super_agent',
      'count', (v_c->>'agents_orphaned')::bigint);
  END IF;
  IF (v_c->>'sub_agents_orphaned')::bigint > 0 THEN
    v_out := v_out || jsonb_build_object('check','sub_agents_without_agent',
      'count', (v_c->>'sub_agents_orphaned')::bigint);
  END IF;
  IF (v_c->>'player_rakeback_gap_breaches')::bigint > 0 THEN
    v_out := v_out || jsonb_build_object('check','player_rakeback_exceeds_upline',
      'count', (v_c->>'player_rakeback_gap_breaches')::bigint);
  END IF;
  IF (v_c->>'commission_rates_out_of_policy')::bigint > 0 THEN
    v_out := v_out || jsonb_build_object('check','commission_rate_out_of_policy',
      'count', (v_c->>'commission_rates_out_of_policy')::bigint);
  END IF;

  v_d := public.fn_union_distribution_check();
  IF NOT (v_d->>'healthy')::boolean THEN
    v_out := v_out || jsonb_build_object('check','distribution_exceeds_rake',
      'over_distributed_by', (v_d->>'over_distributed_by')::numeric,
      'rake_collected', (v_d->>'rake_collected')::numeric,
      'total_distributed', (v_d->>'total_distributed')::numeric);
  END IF;

  RETURN v_out;
END $$;


ALTER FUNCTION public.fn_union_hierarchy_warnings() OWNER TO postgres;

--
-- Name: fn_union_house_club_stamp_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_house_club_stamp_check() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT count(*)
    FROM (
      SELECT t.id FROM tables t JOIN clubs c ON c.id = t.club_id
       WHERE COALESCE(c.is_union,false) AND c.union_id IS NOT NULL
         AND t.union_id IS NULL AND COALESCE(t.is_private,false) = false
         AND COALESCE(t.is_deleted,false) = false
         AND t.status NOT IN ('closed','deleted')
      UNION ALL
      SELECT tr.id FROM tournaments tr JOIN clubs c ON c.id = tr.club_id
       WHERE COALESCE(c.is_union,false) AND c.union_id IS NOT NULL
         AND tr.union_id IS NULL AND COALESCE(tr.is_private,false) = false
         AND tr.status IN ('ANNOUNCED','SCHEDULED','REGISTERING','LATE_REG','RUNNING')
    ) x;
$$;


ALTER FUNCTION public.fn_union_house_club_stamp_check() OWNER TO postgres;

--
-- Name: fn_union_integrity_sweep(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_integrity_sweep(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid, p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from timestamptz := now() - make_interval(hours => GREATEST(p_hours,1));
  v_agent_flags jsonb := '[]'::jsonb;
  v_dump_flags jsonb := '[]'::jsonb;
  v_coseat_flags jsonb := '[]'::jsonb;
  v_total int := 0;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_union_overseer(p_union_id, auth.uid()))) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  WITH roster AS (
    SELECT m.agent_id, m.user_id AS player_id
      FROM club_members m
      JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = p_union_id
     WHERE m.agent_id IS NOT NULL
  ),
  net AS (
    SELECT r.agent_id,
           SUM(CASE WHEN wt.type='credit' AND wt.category IN ('cashout','prize','bounty') THEN wt.amount ELSE 0 END)
         - SUM(CASE WHEN wt.type='debit'  AND wt.category IN ('buyin','rebuy','addon','tournament_buyin') THEN wt.amount ELSE 0 END) AS player_net,
           COUNT(DISTINCT r.player_id) AS players
      FROM roster r
      JOIN wallet_transactions wt ON wt.user_id = r.player_id AND wt.created_at >= v_from
     GROUP BY r.agent_id
  ),
  rake AS (
    SELECT r.agent_id,
           SUM(rr.rake_amount * (e.value::numeric) / NULLIF(c.total,0)) AS rake
      FROM rake_records rr
      CROSS JOIN LATERAL (SELECT SUM(t.value::numeric) AS total
                            FROM jsonb_each_text(rr.player_contributions) t(key,value)) c
      CROSS JOIN LATERAL jsonb_each_text(rr.player_contributions) e(key,value)
      JOIN roster r ON r.player_id = (e.key)::uuid
     WHERE rr.created_at >= v_from AND rr.player_contributions IS NOT NULL AND c.total > 0
     GROUP BY r.agent_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'agent_user_id', n.agent_id, 'players', n.players,
           'player_net', round(n.player_net,2), 'rake_generated', round(COALESCE(k.rake,0),2),
           'win_to_rake_ratio', round(n.player_net / NULLIF(COALESCE(k.rake,0),0), 2))), '[]'::jsonb)
    INTO v_agent_flags
    FROM net n LEFT JOIN rake k ON k.agent_id = n.agent_id
   WHERE n.player_net > 0
     AND n.player_net > 10 * GREATEST(COALESCE(k.rake,0), 1);

  SELECT COALESCE(jsonb_agg(x), '[]'::jsonb) INTO v_dump_flags FROM (
    SELECT jsonb_build_object(
             'from_user', ct.from_user_id, 'to_user', ct.to_user_id,
             'transfers', count(*), 'total', round(sum(ct.amount),2)) AS x
      FROM chip_transactions ct
     WHERE ct.created_at >= v_from
       AND ct.from_user_id IS NOT NULL AND ct.to_user_id IS NOT NULL
       AND ct.transaction_type NOT IN ('agent_to_player_transfer','rakeback','buyin','cashout')
       AND NOT EXISTS (SELECT 1 FROM agents a WHERE a.user_id = ct.from_user_id)
     GROUP BY ct.from_user_id, ct.to_user_id
    HAVING sum(ct.amount) > 0
  ) s;

  -- Co-seating, excluding horse-vs-horse (simulated players always co-seat).
  SELECT COALESCE(jsonb_agg(y), '[]'::jsonb) INTO v_coseat_flags FROM (
    SELECT jsonb_build_object('player_a', a.user_id, 'player_b', b.user_id,
                              'shared_tables', count(DISTINCT a.table_id)) AS y
      FROM table_seats a
      JOIN table_seats b ON b.table_id = a.table_id AND b.user_id > a.user_id
      JOIN tables t ON t.id = a.table_id AND t.union_id = p_union_id
      LEFT JOIN profiles pa ON pa.id = a.user_id
      LEFT JOIN profiles pb ON pb.id = b.user_id
     WHERE a.joined_at >= v_from AND b.joined_at >= v_from
       AND NOT (COALESCE(pa.is_horse,false) AND COALESCE(pb.is_horse,false))
     GROUP BY a.user_id, b.user_id
    HAVING count(DISTINCT a.table_id) >= 8
     ORDER BY count(DISTINCT a.table_id) DESC
     LIMIT 20
  ) s2;

  v_total := jsonb_array_length(v_agent_flags)
           + jsonb_array_length(v_dump_flags)
           + jsonb_array_length(v_coseat_flags);

  IF v_total > 0
     AND NOT EXISTS (SELECT 1 FROM financial_alerts
                      WHERE source = 'fn_union_integrity_sweep'
                        AND created_at > now() - interval '20 hours') THEN
    INSERT INTO financial_alerts (severity, source, message, context)
    VALUES ('warning', 'fn_union_integrity_sweep',
            'Union integrity sweep raised ' || v_total || ' signal(s) - review by agent',
            jsonb_build_object('union_id', p_union_id, 'window_hours', p_hours,
                               'agent_roster_winning', v_agent_flags,
                               'direct_chip_transfer', v_dump_flags,
                               'co_seating', v_coseat_flags));
  END IF;

  RETURN jsonb_build_object(
    'union_id', p_union_id, 'window_hours', p_hours, 'signals', v_total,
    'agent_roster_winning', v_agent_flags,
    'direct_chip_transfer', v_dump_flags,
    'co_seating', v_coseat_flags);
END $$;


ALTER FUNCTION public.fn_union_integrity_sweep(p_union_id uuid, p_hours integer) OWNER TO postgres;

--
-- Name: fn_union_integrity_sweep_all(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_integrity_sweep_all(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  u record; v_one jsonb; v_signals int := 0; v_unions int := 0; v_failed int := 0;
  v_suspended int := 0; v_restored int := 0; v_sl jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_platform_admin())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  FOR u IN SELECT id FROM unions LOOP
    BEGIN
      v_one := public.fn_union_integrity_sweep(u.id, p_hours);
      v_signals := v_signals + COALESCE((v_one->>'signals')::int, 0);
      v_unions := v_unions + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
    END;

    -- The open week's rake basis, snapshotted so every reader with an
    -- eight-second budget gets the rows the one function computed within
    -- the hour (Phase 6 verification, 20260908). Never stops the sweep.
    BEGIN
      PERFORM public.fn_union_rake_basis_refresh(u.id, public.fn_union_week_start(now()),
                                                 public.fn_union_week_start(now()) + interval '7 days');
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO financial_alerts (source, severity, message, context)
      VALUES ('fn_union_rake_basis_refresh', 'warning',
              'Refreshing the open-week rake basis snapshot failed for a union',
              jsonb_build_object('union_id', u.id, 'error', SQLERRM));
    END;

    -- Age and chase what is past due, before enforcement reads it.
    BEGIN
      PERFORM public.fn_union_age_invoices(u.id);
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO financial_alerts (source, severity, message, context)
      VALUES ('fn_union_age_invoices', 'warning',
              'Ageing unpaid statements failed for a union',
              jsonb_build_object('union_id', u.id, 'error', SQLERRM));
    END;

    -- Stop-loss enforcement rides the sweep rather than taking a schedule of
    -- its own (World Hub CLAUDE.md 11.3). It must never be able to stop the
    -- integrity sweep from finishing.
    BEGIN
      v_sl := public.fn_union_enforce_stop_loss(u.id);
      v_suspended := v_suspended + COALESCE((v_sl->>'suspended')::int, 0);
      v_restored  := v_restored  + COALESCE((v_sl->>'restored')::int, 0);
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO financial_alerts (source, severity, message, context)
      VALUES ('fn_union_enforce_stop_loss', 'warning',
              'Stop-loss enforcement failed for a union', 
              jsonb_build_object('union_id', u.id, 'error', SQLERRM));
    END;
  END LOOP;

  -- Expire locks whose time has passed. expire_settlement_locks() has
  -- existed since long before this and was called by nothing at all.
  BEGIN
    PERFORM public.expire_settlement_locks();
    PERFORM public.fn_settlement_lock_hygiene();
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO financial_alerts (source, severity, message, context)
    VALUES ('fn_settlement_lock_hygiene', 'warning',
            'Settlement lock hygiene failed',
            jsonb_build_object('error', SQLERRM));
  END;

  -- Close what is due. Never allowed to stop the sweep finishing.
  BEGIN
    PERFORM public.fn_close_due_settlement_periods();
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO financial_alerts (source, severity, message, context)
    VALUES ('fn_close_due_settlement_periods', 'warning',
            'Closing due settlement periods failed',
            jsonb_build_object('error', SQLERRM));
  END;

  RETURN jsonb_build_object('unions_swept', v_unions, 'unions_failed', v_failed,
                            'signals', v_signals,
                            'clubs_suspended', v_suspended, 'clubs_restored', v_restored,
                            'window_hours', p_hours, 'ran_at', now());
END $$;


ALTER FUNCTION public.fn_union_integrity_sweep_all(p_hours integer) OWNER TO postgres;

--
-- Name: fn_union_invoice_outstanding(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_invoice_outstanding(p_invoice_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT round(si.net_amount - COALESCE((
           SELECT SUM(cn.net_amount) FROM settlement_invoices cn
            WHERE cn.adjusts_invoice_id = si.id
              AND cn.invoice_type = 'union_weekly_credit_note'), 0), 2)
    FROM settlement_invoices si WHERE si.id = p_invoice_id;
$$;


ALTER FUNCTION public.fn_union_invoice_outstanding(p_invoice_id uuid) OWNER TO postgres;

--
-- Name: fn_union_issue_credit_note(uuid, numeric, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_issue_credit_note(p_invoice_id uuid, p_amount numeric, p_reason text, p_notify boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_orig      settlement_invoices%ROWTYPE;
  v_union_id  uuid;
  v_union_name text;
  v_club_name text;
  v_credited  numeric;
  v_remaining numeric;
  v_number    text;
  v_new_id    uuid;
  v_msg       jsonb;
  v_body      text;
BEGIN
  SELECT * INTO v_orig FROM settlement_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF v_orig.id IS NULL THEN
    RAISE EXCEPTION 'invoice not found';
  END IF;

  v_union_id := (v_orig.breakdown->>'union_id')::uuid;

  -- WHO IS CALLING, before anything that would describe the document.
  IF auth.uid() IS NOT NULL
     AND (v_union_id IS NULL
          OR (NOT EXISTS (SELECT 1 FROM unions u WHERE u.id = v_union_id AND u.owner_id = auth.uid())
              AND NOT EXISTS (SELECT 1 FROM union_admins ua WHERE ua.union_id = v_union_id AND ua.user_id = auth.uid())
              AND NOT COALESCE(public.fn_is_platform_admin(), false))) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'a credit note must be for a positive amount, got %', p_amount;
  END IF;
  IF COALESCE(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'a credit note must carry a reason';
  END IF;
  IF v_orig.invoice_type <> 'union_weekly_squareup' THEN
    RAISE EXCEPTION 'only a weekly square-up can be credited, this is %', v_orig.invoice_type;
  END IF;
  IF v_union_id IS NULL THEN
    RAISE EXCEPTION 'invoice % carries no union_id in its breakdown', p_invoice_id;
  END IF;

  SELECT COALESCE(SUM(net_amount), 0) INTO v_credited
    FROM settlement_invoices
   WHERE adjusts_invoice_id = p_invoice_id
     AND invoice_type = 'union_weekly_credit_note';

  v_remaining := round(v_orig.net_amount - v_credited, 2);
  IF p_amount > v_remaining + 0.005 THEN
    RAISE EXCEPTION
      'credit note of % exceeds what is left on invoice % (net %, already credited %, remaining %)',
      p_amount, COALESCE(v_orig.invoice_number, v_orig.id::text),
      v_orig.net_amount, v_credited, v_remaining;
  END IF;

  SELECT u.name INTO v_union_name FROM unions u WHERE u.id = v_union_id;
  SELECT c.name INTO v_club_name FROM clubs c WHERE c.id = v_orig.club_id;
  v_number := public.fn_next_invoice_number(v_union_id, now());

  INSERT INTO settlement_invoices (
    club_id, period_id, invoice_type, invoice_number, adjusts_invoice_id,
    from_entity_type, from_entity_id, to_entity_type, to_entity_id,
    gross_amount, net_amount, deductions, breakdown, status,
    chips_transferred, due_at, notes)
  VALUES (
    v_orig.club_id, v_orig.period_id, 'union_weekly_credit_note', v_number, v_orig.id,
    v_orig.to_entity_type,   v_orig.to_entity_id,
    v_orig.from_entity_type, v_orig.from_entity_id,
    p_amount, p_amount, 0,
    jsonb_build_object(
      'union_id', v_union_id, 'union_name', v_union_name,
      'club_id', v_orig.club_id, 'club_name', v_club_name,
      'credit_note_for', COALESCE(v_orig.invoice_number, v_orig.id::text),
      'original_invoice_id', v_orig.id,
      'original_net_amount', v_orig.net_amount,
      'previously_credited', v_credited,
      'remaining_before_this', v_remaining,
      'reason', p_reason,
      'period_start', v_orig.breakdown->>'period_start',
      'period_end', v_orig.breakdown->>'period_end',
      'issued_at', now()),
    'generated', false, v_orig.due_at,
    'Credit note against ' || COALESCE(v_orig.invoice_number, v_orig.id::text) || '. ' || p_reason)
  RETURNING id INTO v_new_id;

  IF p_notify THEN
    v_body :=
      COALESCE(v_union_name, 'Union') || ' credit note ' || v_number || E'\n'
      || 'Against statement ' || COALESCE(v_orig.invoice_number, v_orig.id::text) || E'\n\n'
      || 'Credit amount       ' || to_char(p_amount, 'FM999,999,999,990.00') || E'\n'
      || 'Original statement  ' || to_char(v_orig.net_amount, 'FM999,999,999,990.00') || E'\n'
      || CASE WHEN v_credited > 0
              THEN 'Previously credited ' || to_char(v_credited, 'FM999,999,999,990.00') || E'\n'
              ELSE '' END
      || 'Remaining after     ' || to_char(round(v_remaining - p_amount, 2), 'FM999,999,999,990.00')
      || E'\n\n'
      || 'Reason: ' || p_reason || E'\n\n'
      || 'The original statement is unchanged. This credit note adjusts it.';

    v_msg := fn_union_send_club_message(
      v_union_id, v_orig.club_id, v_body,
      jsonb_build_object(
        'kind', 'union_credit_note',
        'credit_note_id', v_new_id,
        'credit_note_number', v_number,
        'adjusts_invoice_id', v_orig.id,
        'adjusts_invoice_number', v_orig.invoice_number,
        'amount', p_amount,
        'reason', p_reason),
      'invoice');

    IF COALESCE((v_msg->>'delivered')::int, 0) > 0 THEN
      UPDATE settlement_invoices
         SET message_sent = true, message_sent_at = now()
       WHERE id = v_new_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'credit_note_id', v_new_id,
    'credit_note_number', v_number,
    'adjusts', COALESCE(v_orig.invoice_number, v_orig.id::text),
    'amount', p_amount,
    'original_net', v_orig.net_amount,
    'total_credited_now', round(v_credited + p_amount, 2),
    'remaining_after', round(v_remaining - p_amount, 2),
    'delivered', COALESCE((v_msg->>'delivered')::int, 0));
END $$;


ALTER FUNCTION public.fn_union_issue_credit_note(p_invoice_id uuid, p_amount numeric, p_reason text, p_notify boolean) OWNER TO postgres;

--
-- Name: FUNCTION fn_union_issue_credit_note(p_invoice_id uuid, p_amount numeric, p_reason text, p_notify boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_issue_credit_note(p_invoice_id uuid, p_amount numeric, p_reason text, p_notify boolean) IS 'Issues a credit note against a delivered weekly square-up. The original is never modified - a delivered invoice is immutable - and the two documents net. Refuses to over-credit, to credit a credit note, or to issue without a reason.';


--
-- Name: fn_union_issue_weekly_invoices(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_issue_weekly_invoices(p_union_id uuid, p_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notify boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_from timestamptz := COALESCE(p_start, public.fn_union_prev_week_start(now()));
  v_to   timestamptz := COALESCE(p_end,   public.fn_union_week_start(now()));
  v_due  timestamptz;
  v_union_name text;
  r record;
  v_period_id uuid;
  v_invoice_id uuid;
  v_already_sent boolean;
  v_issued int := 0;
  v_notified int := 0;
  v_notified_batch int := 0;
  v_messaged int := 0;
  v_basis_exact boolean;
  v_msg jsonb;
  v_body text;
  v_number text;
  v_out jsonb := '[]'::jsonb;
BEGIN
  IF v_caller IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM unions u WHERE u.id = p_union_id AND u.owner_id = v_caller)
     AND NOT EXISTS (SELECT 1 FROM union_admins ua
                      WHERE ua.union_id = p_union_id AND ua.user_id = v_caller) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authorized');
  END IF;

  /* THE GUARDS LIVE HERE, NOT ONLY IN THE CASCADE (Phase 6 verification,
     20260908). The Open Claw safety net calls this function directly. */
  IF EXISTS (SELECT 1 FROM public.union_settlement_floor f
              WHERE f.union_id = p_union_id AND v_from < f.earliest_period_start) THEN
    RETURN jsonb_build_object('success', false, 'error', 'before_settlement_floor',
                              'period_start', v_from, 'period_end', v_to);
  END IF;
  IF public.fn_union_setting(p_union_id, 'weekly_invoices_enabled', 1) <> 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'weekly_invoices_disabled',
                              'period_start', v_from, 'period_end', v_to);
  END IF;
  -- A statement says "rakeback already moved in chips". It is issued only for a
  -- period whose round 1 is final, and then it reads that round's own rows.
  IF NOT EXISTS (SELECT 1 FROM public.ca_settlements s
                  WHERE s.settlement_type = 'union_rakeback_close' AND s.union_id = p_union_id
                    AND s.state = 'final'
                    AND s.external_ref = p_union_id::text || ':'
                      || to_char(v_from at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
                      || to_char(v_to   at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'period_not_closed',
                              'period_start', v_from, 'period_end', v_to);
  END IF;

  v_due := v_to + interval '3 days';
  SELECT u.name INTO v_union_name FROM unions u WHERE u.id = p_union_id;

  -- Is the seated-stack baseline this week's ECO rests on an exact one?
  SELECT bool_and(COALESCE(e.baseline_cash_exact, false))
    INTO v_basis_exact
    FROM fn_union_eco_adjustment(p_union_id, v_from, v_to) e;
  v_basis_exact := COALESCE(v_basis_exact, false);

  FOR r IN SELECT * FROM fn_union_club_invoice(p_union_id, v_from, v_to) LOOP
    v_msg := NULL;
    v_invoice_id := NULL;
    v_already_sent := false;

    SELECT sp.id INTO v_period_id
      FROM settlement_periods sp
     WHERE sp.club_id = r.club_id AND sp.union_id = p_union_id
       AND sp.start_at = v_from AND sp.end_at = v_to
     ORDER BY sp.created_at DESC LIMIT 1;

    IF v_period_id IS NULL THEN
      INSERT INTO settlement_periods (club_id, union_id, period_number, year,
                                      start_at, end_at, status)
      VALUES (r.club_id, p_union_id,
              EXTRACT(week FROM v_from)::int, EXTRACT(isoyear FROM v_from)::int,
              v_from, v_to, 'processing')
      RETURNING id INTO v_period_id;
    END IF;

    -- Reuse the number this document already carries. Take a new one ONLY
    -- when there is no document yet: the upsert below may take the ON
    -- CONFLICT path, and a number taken and not used is a gap in the series.
    SELECT si.invoice_number INTO v_number
      FROM settlement_invoices si
     WHERE si.club_id = r.club_id AND si.period_id = v_period_id
       AND si.invoice_type = 'union_weekly_squareup';
    IF NOT FOUND THEN
      v_number := public.fn_next_invoice_number(p_union_id, now());
    END IF;

    INSERT INTO settlement_invoices (
      club_id, period_id, invoice_type, invoice_number,
      from_entity_type, from_entity_id, to_entity_type, to_entity_id,
      gross_amount, net_amount, deductions, breakdown, status,
      chips_transferred, due_at, notes)
    VALUES (
      r.club_id, v_period_id, 'union_weekly_squareup', v_number,
      CASE WHEN r.outstanding >= 0 THEN 'union' ELSE 'club' END,
      CASE WHEN r.outstanding >= 0 THEN p_union_id::text ELSE r.club_id::text END,
      CASE WHEN r.outstanding >= 0 THEN 'club'  ELSE 'union' END,
      CASE WHEN r.outstanding >= 0 THEN r.club_id::text ELSE p_union_id::text END,
      abs(r.outstanding), abs(r.outstanding), 0,
      jsonb_build_object(
        'union_id', p_union_id, 'union_name', v_union_name,
        'club_id', r.club_id, 'club_name', r.club_name,
        'period_start', r.period_start, 'period_end', r.period_end,
        'rake_generated', r.rake_generated,
        'union_fee_kept', r.union_fee_kept,
        'rakeback_due',   r.rakeback_due,
        'players_won',    r.players_won,
        'player_pnl_net', r.player_pnl_net,
        'eco_amount',     r.eco_amount,
        'eco_enabled',    r.eco_enabled,
        'presettled',     r.presettled,
        'settled_in_chips', r.settled_in_chips,
        'outstanding',    r.outstanding,
        'net_position',   r.net_position,
        'direction',      r.direction,
        'baseline_cash_exact', v_basis_exact,
        'computed_at',    now()),
      'generated', false, v_due,
      'Weekly union square-up. settled_in_chips already moved during the week; '
      || 'outstanding is the amount to settle.')
    ON CONFLICT (club_id, period_id, invoice_type)
      WHERE invoice_type = 'union_weekly_squareup'
    DO UPDATE SET
      from_entity_type = EXCLUDED.from_entity_type,
      from_entity_id   = EXCLUDED.from_entity_id,
      to_entity_type   = EXCLUDED.to_entity_type,
      to_entity_id     = EXCLUDED.to_entity_id,
      gross_amount     = EXCLUDED.gross_amount,
      net_amount       = EXCLUDED.net_amount,
      invoice_number   = COALESCE(settlement_invoices.invoice_number, EXCLUDED.invoice_number),
      breakdown        = EXCLUDED.breakdown,
      due_at           = EXCLUDED.due_at,
      updated_at       = now()
    WHERE COALESCE(settlement_invoices.message_sent, false) = false
    RETURNING id, COALESCE(message_sent, false) INTO v_invoice_id, v_already_sent;

    -- The upsert returns nothing when the guard above refused to restate an
    -- already-delivered invoice. That row is the record; read it as it stands.
    IF v_invoice_id IS NULL THEN
      SELECT si.id, COALESCE(si.message_sent, false)
        INTO v_invoice_id, v_already_sent
        FROM settlement_invoices si
       WHERE si.club_id = r.club_id
         AND si.period_id = v_period_id
         AND si.invoice_type = 'union_weekly_squareup';
    END IF;

    v_issued := v_issued + 1;

    IF p_notify AND NOT v_already_sent THEN
      INSERT INTO notifications (user_id, type, title, message, data, read)
      SELECT DISTINCT u.uid, 'union_invoice',
             v_union_name || ' weekly statement',
             CASE
               WHEN r.outstanding > 0 THEN
                 v_union_name || ' owes ' || r.club_name || ' '
                 || to_char(abs(r.outstanding), 'FM999,999,999,990.00') || ' for the week.'
               WHEN r.outstanding < 0 THEN
                 r.club_name || ' owes ' || v_union_name || ' '
                 || to_char(abs(r.outstanding), 'FM999,999,999,990.00') || ' for the week.'
               ELSE
                 r.club_name || ' is square with ' || v_union_name || ' for the week.'
             END,
             jsonb_build_object('invoice_id', v_invoice_id, 'club_id', r.club_id,
                                'union_id', p_union_id,
                                'period_start', r.period_start, 'period_end', r.period_end,
                                'outstanding', r.outstanding, 'due_at', v_due,
                                'source', 'club_arena'),
             false
        FROM (
          SELECT c.owner_id AS uid FROM clubs c WHERE c.id = r.club_id AND c.owner_id IS NOT NULL
          UNION
          SELECT cm.user_id FROM club_members cm
           WHERE cm.club_id = r.club_id AND cm.role IN ('owner','co_owner','admin')
             AND COALESCE(cm.status,'active') NOT IN ('banned','suspended')
        ) u
       WHERE u.uid IS NOT NULL;
      GET DIAGNOSTICS v_notified_batch = ROW_COUNT;
      v_notified := v_notified + v_notified_batch;
    END IF;

    -- CLUB MESSENGER. Only once per invoice: message_sent is the guard.
    IF NOT v_already_sent THEN
      v_body :=
        v_union_name || ' weekly statement' || E'\n'
        || to_char(r.period_start, 'YYYY-MM-DD') || ' to ' || to_char(r.period_end, 'YYYY-MM-DD')
        || E'\n\n'
        || 'Rake generated       ' || to_char(r.rake_generated,   'FM999,999,999,990.00') || E'\n'
        || 'Your rakeback (90%)  ' || to_char(r.rakeback_due,     'FM999,999,999,990.00') || E'\n'
        || 'Union fee kept       ' || to_char(r.union_fee_kept,   'FM999,999,999,990.00') || E'\n'
        || 'Player win/loss      ' || to_char(r.players_won,      'FM999,999,999,990.00') || E'\n'
        || 'Settled in chips     ' || to_char(r.settled_in_chips, 'FM999,999,999,990.00') || E'\n'
        || CASE WHEN r.eco_enabled
                THEN 'ECO adjustment       ' || to_char(r.eco_amount, 'FM999,999,999,990.00') || E'\n'
                ELSE '' END
        || CASE WHEN COALESCE(r.presettled, 0) <> 0
                THEN 'Payments received    ' || to_char(r.presettled, 'FM999,999,999,990.00') || E'\n'
                ELSE '' END
        || E'\n'
        || CASE
             WHEN r.outstanding < 0 THEN 'AMOUNT DUE ' || to_char(abs(r.outstanding), 'FM999,999,999,990.00')
             WHEN r.outstanding > 0 THEN 'OWED TO YOU ' || to_char(abs(r.outstanding), 'FM999,999,999,990.00')
             ELSE 'SQUARE FOR THE WEEK'
           END
        || CASE WHEN r.outstanding <> 0
                THEN E'\n' || 'Due ' || to_char(v_due, 'YYYY-MM-DD')
                ELSE '' END
        || E'\n\n'
        || 'Player win/loss and rakeback already moved in chips during the week. '
        || 'The amount above is what is left to square up.'
        || CASE WHEN r.eco_enabled AND NOT v_basis_exact
                THEN E'\n\n'
                     || 'PROVISIONAL. The ECO adjustment on this statement was '
                     || 'calculated without an exact opening seated-stack figure '
                     || 'for the period, so it is subject to correction. Raise it '
                     || 'with the union if it looks wrong.'
                ELSE '' END;

      v_msg := fn_union_send_club_message(
        p_union_id, r.club_id, v_body,
        jsonb_build_object(
          'kind', 'union_invoice',
          'invoice_id', v_invoice_id,
          'union_id', p_union_id,
          'club_id', r.club_id,
          'period_start', r.period_start,
          'period_end', r.period_end,
          'due_at', v_due,
          'outstanding', r.outstanding,
          'direction', r.direction,
          'baseline_cash_exact', v_basis_exact,
          'lines', jsonb_build_object(
            'rake_generated', r.rake_generated,
            'rakeback_due', r.rakeback_due,
            'union_fee_kept', r.union_fee_kept,
            'players_won', r.players_won,
            'settled_in_chips', r.settled_in_chips,
            'eco_amount', r.eco_amount,
            'eco_enabled', r.eco_enabled,
            'presettled', r.presettled)),
        'invoice');

      IF COALESCE((v_msg->>'delivered')::int, 0) > 0 THEN
        v_messaged := v_messaged + (v_msg->>'delivered')::int;
        UPDATE settlement_invoices
           SET message_sent = true, message_sent_at = now()
         WHERE id = v_invoice_id;
      END IF;
    END IF;

    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'club_id', r.club_id, 'club_name', r.club_name,
      'invoice_id', v_invoice_id, 'outstanding', r.outstanding,
      'direction', r.direction, 'due_at', v_due,
      'messaged', COALESCE((v_msg->>'delivered')::int, 0),
      'already_sent', v_already_sent));
  END LOOP;

  RETURN jsonb_build_object('success', true, 'union_id', p_union_id,
    'period_start', v_from, 'period_end', v_to, 'due_at', v_due,
    'baseline_cash_exact', v_basis_exact,
    'invoices', v_issued, 'notified', v_notified, 'messenger_deliveries', v_messaged,
    'detail', v_out);
END;
$$;


ALTER FUNCTION public.fn_union_issue_weekly_invoices(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_notify boolean) OWNER TO postgres;

--
-- Name: fn_union_law_extra_breaches(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_law_extra_breaches() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_out jsonb := '[]'::jsonb; v_dupes text[]; v_type text; v_globals text[]; v_roles text[];
BEGIN
  SELECT array_agg(fn || ' x' || signatures) INTO v_dupes
    FROM public.fn_union_overload_check();
  IF v_dupes IS NOT NULL THEN
    v_out := v_out || jsonb_build_object('check','money_path_duplicate_signatures',
                                         'functions', to_jsonb(v_dupes));
  END IF;

  SELECT data_type INTO v_type FROM information_schema.columns
   WHERE table_schema='public' AND table_name='club_members' AND column_name='chip_balance';
  IF v_type IS DISTINCT FROM 'numeric' THEN
    v_out := v_out || jsonb_build_object('check','club_chip_balance_not_numeric',
                                         'actual_type', COALESCE(v_type,'missing'));
  END IF;

  -- OWNER RULE: the Club Arena has no global wallet.
  SELECT array_agg(fn ORDER BY fn) INTO v_globals
    FROM public.fn_club_arena_global_wallet_check();
  IF v_globals IS NOT NULL THEN
    v_out := v_out || jsonb_build_object('check','club_arena_uses_global_wallet',
                                         'functions', to_jsonb(v_globals));
  END IF;

  -- OWNER RULE: exactly six roles.
  SELECT array_agg(DISTINCT role) INTO v_roles
    FROM club_members
   WHERE role IS NULL
      OR role NOT IN ('owner','co_owner','admin','super_agent','agent','sub_agent','player');
  IF v_roles IS NOT NULL THEN
    v_out := v_out || jsonb_build_object('check','non_canonical_club_role',
                                         'roles', to_jsonb(v_roles));
  END IF;

  RETURN v_out;
END $$;


ALTER FUNCTION public.fn_union_law_extra_breaches() OWNER TO postgres;

--
-- Name: fn_union_law_integrity_breaches(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_law_integrity_breaches() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'check', invariant, 'count', offenders, 'detail', detail)), '[]'::jsonb)
    FROM public.fn_union_chip_integrity_check();
$$;


ALTER FUNCTION public.fn_union_law_integrity_breaches() OWNER TO postgres;

--
-- Name: fn_union_law_selftest(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_law_selftest() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_breaches jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_n bigint; v_missing text[]; v_integrity jsonb; v_extra jsonb; v_hier jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_platform_admin() AND NOT EXISTS (SELECT 1 FROM unions u WHERE public.fn_is_union_overseer(u.id, auth.uid())))) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                  WHERE n.nspname='public' AND p.proname='atomic_distribute_rake'
                    AND p.prosrc LIKE '%UNION LAW%' AND p.prosrc LIKE '%v_is_private%') THEN
    v_breaches := v_breaches || jsonb_build_object('check','atomic_distribute_rake_law_missing');
  END IF;
  IF EXISTS (SELECT 1 FROM (VALUES ('fn_register_for_tournament'),('fn_register_horse_for_tournament')) AS r(fn)
              WHERE NOT EXISTS (
                WITH RECURSIVE chain(proname, prosrc, depth) AS (
                  SELECT p.proname, p.prosrc, 0
                    FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                   WHERE n.nspname='public' AND p.proname=r.fn
                  UNION
                  SELECT p2.proname, p2.prosrc, c.depth+1
                    FROM chain c
                    JOIN pg_proc p2 ON p2.proname LIKE r.fn || '%'
                                   AND position('public.'||p2.proname||'(' in c.prosrc) > 0
                    JOIN pg_namespace n2 ON n2.oid=p2.pronamespace AND n2.nspname='public'
                   WHERE c.depth < 8
                )
                SELECT 1 FROM chain
                 WHERE prosrc LIKE '%rake_records%'
                   AND prosrc LIKE '%fn_tournament_entry_split%')) THEN
    v_breaches := v_breaches || jsonb_build_object('check','tournament_buyin_rake_not_club_scoped');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                  WHERE n.nspname='public' AND p.proname='fn_resolve_bbj_pool'
                    AND p.prosrc LIKE '%is_private%') THEN
    v_breaches := v_breaches || jsonb_build_object('check','fn_resolve_bbj_pool_law_missing');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                  WHERE n.nspname='public' AND p.proname='record_rake'
                    AND p.prosrc LIKE '%atomic_distribute_rake%') THEN
    v_breaches := v_breaches || jsonb_build_object('check','record_rake_delegation_missing');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                  WHERE n.nspname='public' AND p.proname='fn_stamp_table_union_ownership'
                    AND p.prosrc LIKE '%FROM clubs c WHERE c.id = NEW.club_id%') THEN
    v_breaches := v_breaches || jsonb_build_object('check','table_stamp_house_club_fallback_missing');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                  WHERE n.nspname='public' AND p.proname='fn_stamp_tournament_union_ownership'
                    AND p.prosrc LIKE '%FROM clubs c WHERE c.id = NEW.club_id%') THEN
    v_breaches := v_breaches || jsonb_build_object('check','tournament_stamp_house_club_fallback_missing');
  END IF;

  v_n := public.fn_union_house_club_stamp_check();
  IF v_n > 0 THEN
    v_breaches := v_breaches || jsonb_build_object('check','house_club_games_unstamped','count',v_n);
  END IF;

  SELECT array_agg(fn ORDER BY fn) INTO v_missing FROM public.fn_union_money_path_check();
  IF v_missing IS NOT NULL THEN
    v_breaches := v_breaches || jsonb_build_object('check','money_path_not_club_scoped','functions',to_jsonb(v_missing));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                  WHERE n.nspname='public' AND p.proname='fn_snapshot_chip_supply'
                    AND p.prosrc LIKE '%club_members%') THEN
    v_breaches := v_breaches || jsonb_build_object('check','chip_supply_monitor_blind_to_club_wallets');
  END IF;

  v_extra := public.fn_union_law_extra_breaches();
  IF jsonb_array_length(v_extra) > 0 THEN v_breaches := v_breaches || v_extra; END IF;

  v_integrity := public.fn_union_law_integrity_breaches();
  IF jsonb_array_length(v_integrity) > 0 THEN v_breaches := v_breaches || v_integrity; END IF;

  SELECT count(*) INTO v_n FROM pg_trigger
   WHERE tgname IN ('trg_tables_union_ownership','trg_tournaments_union_ownership',
                    'trg_tables_block_deleted_revival','trg_table_seats_stamp_club',
                    'trg_tournament_players_stamp_club');
  IF v_n < 5 THEN
    v_breaches := v_breaches || jsonb_build_object('check','required_trigger_missing','found',v_n);
  END IF;

  SELECT count(*) INTO v_n FROM cron.job
   WHERE jobname IN ('union-weekly-rakeback-close','union-law-selftest',
                     'union-seat-provenance-heal','union-integrity-sweep')
     AND active;
  IF v_n < 4 THEN
    v_breaches := v_breaches || jsonb_build_object('check','required_cron_missing','active',v_n);
  END IF;

  SELECT array_agg(t ORDER BY t) INTO v_missing
    FROM unnest(public.fn_union_oversight_tables() || ARRAY['table_seats']) AS t
   WHERE EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
                  WHERE n.nspname='public' AND c.relname=t AND c.relkind='r')
     AND NOT EXISTS (SELECT 1 FROM pg_policies p
                      WHERE p.schemaname='public' AND p.tablename=t AND p.policyname='union_overseer_read');
  IF v_missing IS NOT NULL THEN
    v_breaches := v_breaches || jsonb_build_object('check','oversight_policy_missing','tables',to_jsonb(v_missing));
  END IF;

  SELECT array_agg(t ORDER BY t) INTO v_missing
    FROM unnest(public.fn_union_oversight_tables()) AS t
   WHERE EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
                  WHERE n.nspname='public' AND c.relname=t AND c.relkind='r' AND c.relrowsecurity=false);
  IF v_missing IS NOT NULL THEN
    v_breaches := v_breaches || jsonb_build_object('check','club_table_rls_disabled','tables',to_jsonb(v_missing));
  END IF;

  SELECT array_agg(c.relname ORDER BY c.relname) INTO v_missing
    FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname='public' AND c.relkind='v' AND c.relname IN ('club_agents','club_daily_stats')
     AND COALESCE(array_to_string(c.reloptions,','),'') NOT LIKE '%security_invoker=true%';
  IF v_missing IS NOT NULL THEN
    v_breaches := v_breaches || jsonb_build_object('check','club_view_not_security_invoker','views',to_jsonb(v_missing));
  END IF;

  SELECT count(*) INTO v_n FROM tables t JOIN union_clubs uc ON uc.club_id=t.club_id
   WHERE COALESCE(t.is_private,false)=false AND COALESCE(t.is_deleted,false)=false
     AND t.status IN ('running','waiting','active','open');
  IF v_n > 0 THEN
    v_breaches := v_breaches || jsonb_build_object('check','live_games_in_member_club_lobby','count',v_n);
  END IF;

  SELECT count(*) INTO v_n FROM (
    SELECT id FROM tables WHERE COALESCE(is_private,false) AND union_id IS NOT NULL
    UNION ALL SELECT id FROM tournaments WHERE COALESCE(is_private,false) AND union_id IS NOT NULL) x;
  IF v_n > 0 THEN
    v_breaches := v_breaches || jsonb_build_object('check','private_rows_union_stamped','count',v_n);
  END IF;

  -- WARNINGS
  SELECT count(*) INTO v_n FROM table_seats WHERE left_at IS NULL AND club_id IS NULL;
  IF v_n > 0 THEN
    v_warnings := v_warnings || jsonb_build_object('check','seats_without_provenance','count',v_n);
  END IF;

  v_hier := public.fn_union_hierarchy_warnings();
  IF jsonb_array_length(v_hier) > 0 THEN v_warnings := v_warnings || v_hier; END IF;

  IF jsonb_array_length(v_breaches) > 0
     AND NOT EXISTS (SELECT 1 FROM financial_alerts
                      WHERE source='fn_union_law_selftest' AND created_at > now() - interval '20 hours') THEN
    INSERT INTO financial_alerts (severity, source, message, context)
    VALUES ('critical','fn_union_law_selftest',
            'UNION LAW self-test failed - the law has been clobbered or breached',
            jsonb_build_object('breaches', v_breaches));
  END IF;

  RETURN jsonb_build_object('healthy', jsonb_array_length(v_breaches)=0,
                            'breaches', v_breaches, 'warnings', v_warnings);
END $$;


ALTER FUNCTION public.fn_union_law_selftest() OWNER TO postgres;

--
-- Name: fn_union_leaderboard_period(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_leaderboard_period(p_union_id uuid, p_metric text DEFAULT 'profit'::text, p_period text DEFAULT 'weekly'::text, p_limit integer DEFAULT 20) RETURNS TABLE(user_id uuid, hands_played numeric, total_winnings numeric, total_losses numeric, tournaments_won numeric, total_rake numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_days integer; v_target date;
BEGIN
  v_days := CASE p_period WHEN 'daily' THEN 1 WHEN 'weekly' THEN 7 WHEN 'monthly' THEN 30 ELSE 0 END;
  IF v_days = 0 THEN
    RETURN QUERY
      SELECT ps.user_id, sum(ps.hands_played)::numeric, sum(ps.total_winnings)::numeric,
             sum(ps.total_losses)::numeric, sum(ps.tournaments_won)::numeric, sum(ps.total_rake)::numeric
      FROM player_stats ps
      WHERE ps.club_id IN (SELECT club_id FROM union_clubs WHERE union_id = p_union_id)
      GROUP BY ps.user_id
      ORDER BY (CASE p_metric WHEN 'hands_played' THEN sum(ps.hands_played)
                              WHEN 'tournaments_won' THEN sum(ps.tournaments_won)
                              ELSE sum(ps.total_winnings - ps.total_losses) END) DESC
      LIMIT p_limit;
    RETURN;
  END IF;

  v_target := CURRENT_DATE - v_days;
  RETURN QUERY
    WITH club_ids AS (SELECT club_id FROM union_clubs WHERE union_id = p_union_id),
    baselines AS (
      SELECT ci.club_id,
             COALESCE(
               (SELECT max(s.snapshot_date) FROM player_stats_snapshots s WHERE s.club_id = ci.club_id AND s.snapshot_date <= v_target),
               (SELECT min(s.snapshot_date) FROM player_stats_snapshots s WHERE s.club_id = ci.club_id)
             ) AS baseline_date
      FROM club_ids ci
    ),
    deltas AS (
      SELECT ps.user_id,
             GREATEST(ps.hands_played - COALESCE(sn.hands_played,0),0) AS d_hands,
             (ps.total_winnings - COALESCE(sn.total_winnings,0)) AS d_win,
             (ps.total_losses - COALESCE(sn.total_losses,0)) AS d_loss,
             GREATEST(ps.tournaments_won - COALESCE(sn.tournaments_won,0),0) AS d_tw,
             GREATEST(ps.total_rake - COALESCE(sn.total_rake,0),0) AS d_rake
      FROM player_stats ps
      JOIN baselines b ON b.club_id = ps.club_id
      LEFT JOIN player_stats_snapshots sn
        ON sn.user_id = ps.user_id AND sn.club_id = ps.club_id AND sn.snapshot_date = b.baseline_date
      WHERE ps.club_id IN (SELECT club_id FROM club_ids)
    )
    SELECT d.user_id, sum(d.d_hands)::numeric, sum(d.d_win)::numeric, sum(d.d_loss)::numeric,
           sum(d.d_tw)::numeric, sum(d.d_rake)::numeric
    FROM deltas d GROUP BY d.user_id
    ORDER BY (CASE p_metric WHEN 'hands_played' THEN sum(d.d_hands)
                            WHEN 'tournaments_won' THEN sum(d.d_tw)
                            ELSE sum(d.d_win - d.d_loss) END) DESC
    LIMIT p_limit;
END; $$;


ALTER FUNCTION public.fn_union_leaderboard_period(p_union_id uuid, p_metric text, p_period text, p_limit integer) OWNER TO postgres;

--
-- Name: fn_union_leaderboard_period_v2(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_leaderboard_period_v2(p_union_id uuid, p_metric text DEFAULT 'profit'::text, p_period text DEFAULT 'weekly'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid, hands_played numeric, total_winnings numeric, total_losses numeric, tournaments_won numeric, total_rake numeric, sum_big_blind numeric, rank_change integer, qualified boolean, rank integer, total_ranked integer, baseline_date date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_period_start date;
  v_baseline date;
  v_prev_end date;
  v_min_hands integer := 20;
  v_is_all_time boolean := p_period = 'all_time';
BEGIN
  SELECT bounds.start_date INTO v_period_start
    FROM public.fn_leaderboard_period_window(p_period, 0) bounds;
  IF NOT v_is_all_time THEN
    SELECT max(snapshot_date) INTO v_baseline
      FROM public.player_stats_snapshots WHERE snapshot_date <= v_period_start;
    IF v_baseline IS NULL THEN
      SELECT min(snapshot_date) INTO v_baseline FROM public.player_stats_snapshots;
    END IF;
  END IF;
  SELECT max(snapshot_date) INTO v_prev_end
    FROM public.player_stats_snapshots
   WHERE snapshot_date <= (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')::date - 1;

  RETURN QUERY
  WITH club_ids AS (
    SELECT uc.club_id FROM public.union_clubs uc WHERE uc.union_id=p_union_id
  ),
  cur_ps AS (
    SELECT ps.user_id AS uid, SUM(ps.hands_dealt)::numeric AS s_hands,
           SUM(ps.total_winnings) AS s_win, SUM(ps.total_losses) AS s_loss,
           SUM(ps.tournaments_won)::numeric AS s_twon, SUM(ps.total_rake) AS s_rake,
           SUM(ps.sum_big_blind) AS s_bb
      FROM public.player_stats ps
     WHERE ps.club_id IN (SELECT club_id FROM club_ids)
     GROUP BY ps.user_id
  ),
  snap AS (
    SELECT s.user_id AS uid, s.snapshot_date AS d, SUM(s.hands_dealt)::numeric AS s_hands,
           SUM(s.total_winnings) AS s_win, SUM(s.total_losses) AS s_loss,
           SUM(s.tournaments_won)::numeric AS s_twon, SUM(s.total_rake) AS s_rake,
           SUM(s.sum_big_blind) AS s_bb
      FROM public.player_stats_snapshots s
     WHERE s.club_id IN (SELECT club_id FROM club_ids)
       AND s.snapshot_date IN (v_baseline,v_prev_end)
     GROUP BY s.user_id,s.snapshot_date
  ),
  cur AS (
    SELECT c.uid,
           (CASE WHEN v_is_all_time THEN c.s_hands ELSE GREATEST(c.s_hands-COALESCE(b.s_hands,0),0) END) AS d_hands,
           (CASE WHEN v_is_all_time THEN c.s_win ELSE c.s_win-COALESCE(b.s_win,0) END) AS d_win,
           (CASE WHEN v_is_all_time THEN c.s_loss ELSE c.s_loss-COALESCE(b.s_loss,0) END) AS d_loss,
           (CASE WHEN v_is_all_time THEN c.s_twon ELSE GREATEST(c.s_twon-COALESCE(b.s_twon,0),0) END) AS d_twon,
           (CASE WHEN v_is_all_time THEN c.s_rake ELSE GREATEST(c.s_rake-COALESCE(b.s_rake,0),0) END) AS d_rake,
           (CASE WHEN v_is_all_time THEN c.s_bb ELSE GREATEST(c.s_bb-COALESCE(b.s_bb,0),0) END) AS d_bb,
           (CASE WHEN pe.uid IS NULL OR (NOT v_is_all_time AND v_prev_end<=v_baseline) THEN NULL ELSE GREATEST(pe.s_hands-COALESCE(b.s_hands,0),0) END) AS p_hands,
           (CASE WHEN pe.uid IS NULL OR (NOT v_is_all_time AND v_prev_end<=v_baseline) THEN NULL ELSE pe.s_win-COALESCE(b.s_win,0) END) AS p_win,
           (CASE WHEN pe.uid IS NULL OR (NOT v_is_all_time AND v_prev_end<=v_baseline) THEN NULL ELSE pe.s_loss-COALESCE(b.s_loss,0) END) AS p_loss,
           (CASE WHEN pe.uid IS NULL OR (NOT v_is_all_time AND v_prev_end<=v_baseline) THEN NULL ELSE GREATEST(pe.s_twon-COALESCE(b.s_twon,0),0) END) AS p_twon,
           (CASE WHEN pe.uid IS NULL OR (NOT v_is_all_time AND v_prev_end<=v_baseline) THEN NULL ELSE GREATEST(pe.s_bb-COALESCE(b.s_bb,0),0) END) AS p_bb
      FROM cur_ps c
      LEFT JOIN snap b ON NOT v_is_all_time AND b.uid=c.uid AND b.d=v_baseline
      LEFT JOIN snap pe ON pe.uid=c.uid AND pe.d=v_prev_end
  ),
  scored AS (
    SELECT c.*,
           (CASE p_metric
              WHEN 'hands_played' THEN c.d_hands
              WHEN 'tournaments_won' THEN c.d_twon
              WHEN 'roi' THEN CASE WHEN c.d_loss>0 AND c.d_hands>=v_min_hands THEN (c.d_win-c.d_loss)/c.d_loss END
              WHEN 'bb100' THEN CASE WHEN c.d_bb>0 AND c.d_hands>=v_min_hands THEN 100*(c.d_win-c.d_loss)/c.d_bb END
              ELSE c.d_win-c.d_loss END) AS score,
           (CASE p_metric
              WHEN 'hands_played' THEN c.p_hands
              WHEN 'tournaments_won' THEN c.p_twon
              WHEN 'roi' THEN CASE WHEN c.p_loss>0 AND c.p_hands>=v_min_hands THEN (c.p_win-c.p_loss)/c.p_loss END
              WHEN 'bb100' THEN CASE WHEN c.p_bb>0 AND c.p_hands>=v_min_hands THEN 100*(c.p_win-c.p_loss)/c.p_bb END
              ELSE c.p_win-c.p_loss END) AS prev_score
      FROM cur c
  ),
  ranked AS (
    SELECT s.*,
           row_number() OVER (ORDER BY s.score DESC NULLS LAST,s.uid) AS rn_now,
           rank() OVER (ORDER BY s.score DESC NULLS LAST) AS rk_now,
           count(*) OVER () AS total_active,
           CASE WHEN s.prev_score IS NULL THEN NULL
                ELSE rank() OVER (ORDER BY s.prev_score DESC NULLS LAST) END AS rk_old
      FROM scored s
     WHERE (s.d_hands > 0 OR s.d_twon > 0 OR s.d_win <> 0 OR s.d_loss <> 0)
  )
  SELECT r.uid,r.d_hands,r.d_win,r.d_loss,r.d_twon,r.d_rake,r.d_bb,
         COALESCE((r.rk_old-r.rk_now)::integer,0),
         (p_metric NOT IN ('roi','bb100') OR
          (r.d_hands>=v_min_hands AND (CASE WHEN p_metric='roi' THEN r.d_loss ELSE r.d_bb END)>0)),
         r.rk_now::integer,r.total_active::integer,v_baseline
    FROM ranked r
   ORDER BY r.rn_now
   LIMIT p_limit OFFSET GREATEST(COALESCE(p_offset,0),0);
END;
$$;


ALTER FUNCTION public.fn_union_leaderboard_period_v2(p_union_id uuid, p_metric text, p_period text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fn_union_mark_period_settled(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_mark_period_settled(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows int := 0;
BEGIN
  INSERT INTO settlement_periods (club_id, union_id, period_number, year,
                                  start_at, end_at, status, settled_at)
  SELECT uc.club_id, p_union_id,
         EXTRACT(week FROM p_from)::int, EXTRACT(isoyear FROM p_from)::int,
         p_from, p_to, 'settled', now()
    FROM union_clubs uc
   WHERE uc.union_id = p_union_id
  ON CONFLICT (club_id, union_id, start_at, end_at) DO UPDATE
     SET status     = CASE WHEN settlement_periods.status IN ('closed','disputed')
                           THEN settlement_periods.status ELSE 'settled' END,
         settled_at = COALESCE(settlement_periods.settled_at, now()),
         updated_at = now();

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN jsonb_build_object('periods_marked_settled', v_rows,
                            'period_start', p_from, 'period_end', p_to);
END $$;


ALTER FUNCTION public.fn_union_mark_period_settled(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_money_path_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_money_path_check() RETURNS TABLE(fn text, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT x.fn,
         'money path no longer reaches club scope (directly or through any '
         || 'function it calls, to 4 levels) - club wallets would be commingled'
    FROM (VALUES
            ('atomic_table_buyin'),('atomic_table_cashout'),
            ('atomic_table_rebuy'),('atomic_table_addon'),
            ('atomic_tournament_register'),
            ('process_tournament_rebuy'),
            ('credit_player_wallet'),('atomic_cancel_tournament'),
            ('fn_pay_player_chips'),
            ('atomic_pay_player_rakeback'),('credit_player_rakeback')
            -- transfer_chips_agent_to_player was here. It is dropped: it
            -- debited the agent's PLAYER wallet, its only caller was an unused
            -- World Hub route, and fn_agent_wallet_send is the path.
            --
            -- atomic_pay_agent_settlement was here until phase 7, and is
            -- dropped for the same shape of reason: staff paying an agent out
            -- of a column nothing maintained, against Dan's ruling that agents
            -- claim their own. What replaces it, fn_agent_claim_commission, is
            -- club-scoped by construction - it takes p_club_id, locks that
            -- club's row and debits that club's treasury - so there is nothing
            -- here for this check to discover about it.
         ) AS x(fn)
   -- A function that has been deleted outright is still a breach; one that
   -- exists but cannot reach club scope is the breach this was written for.
   WHERE NOT EXISTS (
           SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
            WHERE n.nspname='public' AND p.proname=x.fn)
      OR NOT public.fn_money_path_reaches_club_scope(x.fn,4);
$$;


ALTER FUNCTION public.fn_union_money_path_check() OWNER TO postgres;

--
-- Name: fn_union_money_report(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_money_report(p_union_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_union_id uuid;
  v_w record;
  v_week_start timestamptz := public.fn_union_week_start(now());
  v_this_week numeric;
  v_pool record;
  v_clubs jsonb;
  v_closes jsonb;
  v_alerts jsonb;
BEGIN
  v_union_id := COALESCE(p_union_id, (SELECT id FROM unions
    WHERE public.fn_union_report_caller_ok(id) OR public.ca_can_oversee_union(id)
    ORDER BY created_at LIMIT 1));
  IF v_union_id IS NOT NULL AND NOT (
    public.fn_union_report_caller_ok(v_union_id) OR public.ca_can_oversee_union(v_union_id)
  ) THEN
    RAISE EXCEPTION 'not authorized for this union' USING ERRCODE = '42501';
  END IF;
  IF v_union_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'no_union');
  END IF;

  SELECT round(chip_balance,2) chip_balance, round(rake_wallet,2) rake_wallet,
         round(promo_wallet,2) promo_wallet, round(total_rake_collected,2) total_rake_collected,
         round(total_settlements,2) total_settlements
    INTO v_w FROM union_wallets WHERE union_id = v_union_id;

  SELECT COALESCE(SUM(amount),0) INTO v_this_week
    FROM union_wallet_transactions
   WHERE union_id = v_union_id AND wallet='rake_wallet' AND direction='credit'
     AND tx_type='rake' AND created_at >= v_week_start;

  SELECT round(main_balance,2) main_balance, round(backup_balance,2) backup_balance,
         round(promo_balance,2) promo_balance, hands_contributed, hit_count,
         round(total_contributed,2) total_contributed, round(total_paid_out,2) total_paid_out
    INTO v_pool FROM bbj_pools
   WHERE union_id = v_union_id AND status='active' LIMIT 1;

  -- Per-club rake this week + what each is owed at the next close.
  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'club_name'), '[]'::jsonb) INTO v_clubs FROM (
    SELECT jsonb_build_object(
             'club_id', c.id, 'club_name', c.name,
             'rate', COALESCE(uc.club_commission_rate, 0.90),
             'rake_this_week', round(COALESCE(t.amt,0),2),
             'projected_rakeback', round(COALESCE(t.pay,0),2),
             'treasury', round(COALESCE(c.chip_treasury,0),2)) AS x
      FROM clubs c
      LEFT JOIN union_clubs uc ON uc.union_id = v_union_id AND uc.club_id = c.id
      LEFT JOIN (
        -- Phase 6 (20260908): the one basis - the rows the next close pays on,
        -- by the club of the PLAYER, per game type - from the hourly snapshot.
        SELECT b.club_id, SUM(b.rake_in) amt, SUM(b.payout) pay
          FROM public.fn_union_club_rake_basis(v_union_id, v_week_start, now()) b
         GROUP BY b.club_id) t ON t.club_id = c.id
     WHERE c.union_id = v_union_id AND c.id <> v_union_id
  ) s;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'period_start', period_start, 'period_end', period_end,
           'total_rakeback', round(total_rakeback,2), 'executed_at', executed_at)
         ORDER BY period_start DESC), '[]'::jsonb) INTO v_closes
    FROM (SELECT * FROM union_rakeback_log WHERE union_id = v_union_id
           ORDER BY period_start DESC LIMIT 12) l;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'severity', severity, 'source', source, 'message', message, 'created_at', created_at)
         ORDER BY created_at DESC), '[]'::jsonb) INTO v_alerts
    FROM (SELECT * FROM financial_alerts WHERE resolved IS NOT TRUE
           AND context->>'union_id' = v_union_id::text
           ORDER BY created_at DESC LIMIT 10) a;

  RETURN jsonb_build_object(
    'success', true,
    'union_id', v_union_id,
    'generated_at', now(),
    'week_start', v_week_start,
    'wallet', jsonb_build_object(
      'union_bank', v_w.chip_balance, 'rake_treasury', v_w.rake_wallet,
      'promo_wallet', v_w.promo_wallet, 'lifetime_rake', v_w.total_rake_collected,
      'lifetime_rakeback_paid', v_w.total_settlements),
    'rake_this_week', round(v_this_week,2),
    'projected_close', jsonb_build_object(
      'clubs_share', trunc(v_this_week * 0.90 * 100)/100,
      'union_share', round(v_this_week - trunc(v_this_week * 0.90 * 100)/100, 2),
      'next_close_after', v_week_start + interval '7 days'),
    'bbj', jsonb_build_object(
      'main', v_pool.main_balance, 'backup', v_pool.backup_balance,
      'promo_in_pool', v_pool.promo_balance,
      'hands_contributed', v_pool.hands_contributed, 'hits', v_pool.hit_count,
      'lifetime_contributed', v_pool.total_contributed,
      'lifetime_paid_out', v_pool.total_paid_out,
      'split', '50/25/25 main/backup/promo (30/40/30 above 100k main)'),
    'clubs', v_clubs,
    'recent_closes', v_closes,
    'open_alerts', v_alerts,
    -- Reporting must not execute a global checkpoint/alert writer or expose
    -- other unions' diagnostics. The existing engine owns that self-test.
    'selftest', jsonb_build_object('checked', false, 'healthy', NULL,
      'reason', 'Global diagnostics run separately; open_alerts contains this union only'));
END $$;


ALTER FUNCTION public.fn_union_money_report(p_union_id uuid) OWNER TO postgres;

