-- Name: fn_union_move_rake_to_chips_atomic(uuid, numeric, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_move_rake_to_chips_atomic(p_union_id uuid, p_amount numeric, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN jsonb_build_object(
    'success', false,
    'error', 'retired_rake_is_held_in_trust',
    'detail', 'The Rake Treasury holds the member clubs'' rake until the weekly '
           || 'close, which returns 90% to the clubs and moves the union''s '
           || 'retained share into the Union Bank automatically. Moving rake '
           || 'into the bank by hand would spend money that belongs to the clubs.'
  );
END $$;


