--
-- Name: fn_union_player_directory(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_player_directory(p_union_id uuid) RETURNS TABLE(user_id uuid, username text, display_name text, avatar_url text, club_id uuid, club_name text, member_role text, member_status text, joined_at timestamp with time zone, currently_seated boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.fn_is_union_overseer(p_union_id, auth.uid()) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  RETURN QUERY
  WITH union_scope AS (
    SELECT uc.club_id AS id FROM union_clubs uc WHERE uc.union_id = p_union_id
    UNION
    SELECT c.id FROM clubs c WHERE c.id = p_union_id AND COALESCE(c.is_union, false)
  )
  SELECT cm.user_id,
         pr.username,
         public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                              pr.first_name, pr.last_name, pr.full_name),
         pr.avatar_url,
         cm.club_id,
         c.name,
         cm.role,
         cm.status,
         cm.joined_at,
         EXISTS (
           SELECT 1 FROM table_seats ts
             JOIN tables t ON t.id = ts.table_id
            WHERE ts.user_id = cm.user_id AND ts.left_at IS NULL
              AND t.union_id = p_union_id
         )
    FROM club_members cm
    JOIN union_scope us ON us.id = cm.club_id
    JOIN clubs c ON c.id = cm.club_id
    LEFT JOIN profiles pr ON pr.id = cm.user_id
   ORDER BY c.name, pr.username NULLS LAST;
END $$;


ALTER FUNCTION public.fn_union_player_directory(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_union_pnl_all_clubs(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_all_clubs(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean DEFAULT true) RETURNS TABLE(club_id uuid, buyins numeric, cashouts numeric, realized_net numeric, winnings numeric, losses numeric, players integer, seated_stack numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH attributed AS (
    SELECT DISTINCT ON (cm.user_id) cm.user_id, cm.club_id
      FROM club_members cm
      JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = p_union_id
      JOIN profiles p ON p.id = cm.user_id
     WHERE p_include_horses OR COALESCE(p.is_horse, false) = false
     ORDER BY cm.user_id, cm.joined_at ASC NULLS LAST, cm.club_id
  ),
  union_tables AS (
    SELECT id FROM tables WHERE union_id = p_union_id AND tournament_id IS NULL
  ),
  union_tourneys AS (SELECT id FROM tournaments WHERE union_id = p_union_id),
  live_tourneys AS (
    SELECT id FROM tournaments
     WHERE union_id = p_union_id AND status IN ('REGISTERING','RUNNING')
  ),
  wallet_flows AS (
    SELECT a.club_id, wt.user_id,
           SUM(CASE WHEN wt.type = 'debit'  THEN wt.amount ELSE 0 END) AS buyins,
           SUM(CASE WHEN wt.type = 'credit' THEN wt.amount ELSE 0 END) AS cashouts
      FROM wallet_transactions wt
      JOIN attributed a ON a.user_id = wt.user_id
     WHERE wt.created_at >= p_start AND wt.created_at < p_end
       AND (
         (wt.category IN ('buyin','cashout')
            AND wt.table_id IN (SELECT id FROM union_tables))
         OR
         (wt.category IN ('tournament_buyin','prize','bounty')
            AND wt.related_entity_id IN (SELECT id FROM union_tourneys))
       )
     GROUP BY a.club_id, wt.user_id
  ),
  chip_flows AS (
    -- Historical leg: cash-outs written to chip_transactions ONLY, before
    -- the 2026-08-20 P1-1 unification. Post-unification rows carry
    -- metadata.mirrored_to_wallet and are counted in wallet_flows instead.
    SELECT a.club_id, ct.to_user_id AS user_id, SUM(ct.amount) AS cashouts
      FROM chip_transactions ct
      JOIN union_tables ut ON ut.id = ct.table_id
      JOIN attributed a ON a.user_id = ct.to_user_id
     WHERE ct.transaction_type = 'cashout'
       AND ct.created_at >= p_start AND ct.created_at < p_end
       AND NOT COALESCE((ct.metadata->>'mirrored_to_wallet')::boolean, false)
     GROUP BY a.club_id, ct.to_user_id
  ),
  flows AS (
    SELECT COALESCE(w.club_id, c.club_id) AS club_id,
           COALESCE(w.user_id, c.user_id) AS user_id,
           COALESCE(w.buyins, 0) AS buyins,
           COALESCE(w.cashouts, 0) + COALESCE(c.cashouts, 0) AS cashouts
      FROM wallet_flows w
      FULL OUTER JOIN chip_flows c ON c.user_id = w.user_id AND c.club_id = w.club_id
  ),
  per_club AS (
    SELECT f.club_id, SUM(f.buyins) AS buyins, SUM(f.cashouts) AS cashouts,
           SUM(GREATEST(f.cashouts - f.buyins, 0)) AS winnings,
           SUM(GREATEST(f.buyins - f.cashouts, 0)) AS losses,
           COUNT(*)::int AS players
      FROM flows f GROUP BY f.club_id
  ),
  seated AS (
    SELECT a.club_id, SUM(ts.stack) AS seated_stack
      FROM table_seats ts
      JOIN union_tables ut ON ut.id = ts.table_id
      JOIN attributed a ON a.user_id = ts.user_id
     WHERE ts.left_at IS NULL
     GROUP BY a.club_id
  ),
  tourney_equity AS (
    SELECT a.club_id,
           SUM(CASE WHEN wt.category = 'tournament_buyin' THEN wt.amount
                    ELSE -wt.amount END) AS equity
      FROM wallet_transactions wt
      JOIN attributed a ON a.user_id = wt.user_id
     WHERE wt.category IN ('tournament_buyin','prize','bounty')
       AND wt.related_entity_id IN (SELECT id FROM live_tourneys)
     GROUP BY a.club_id
  )
  SELECT uc.club_id,
         COALESCE(pc.buyins, 0), COALESCE(pc.cashouts, 0),
         COALESCE(pc.cashouts, 0) - COALESCE(pc.buyins, 0),
         COALESCE(pc.winnings, 0), COALESCE(pc.losses, 0),
         COALESCE(pc.players, 0),
         COALESCE(s.seated_stack, 0) + COALESCE(te.equity, 0)
    FROM union_clubs uc
    LEFT JOIN per_club pc ON pc.club_id = uc.club_id
    LEFT JOIN seated s ON s.club_id = uc.club_id
    LEFT JOIN tourney_equity te ON te.club_id = uc.club_id
   WHERE uc.union_id = p_union_id;
$$;


ALTER FUNCTION public.fn_union_pnl_all_clubs(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean) OWNER TO postgres;

--
-- Name: fn_union_pnl_baseline(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_baseline(p_union_id uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT club_results
    FROM union_pnl_settlements
   WHERE union_id = p_union_id
     AND status IN ('settled','baseline')
     AND period_start < p_at
   ORDER BY period_start DESC
   LIMIT 1;
$$;


ALTER FUNCTION public.fn_union_pnl_baseline(p_union_id uuid, p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_pnl_bootstrap(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_bootstrap(p_union_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_results jsonb; v_id uuid; v_now timestamptz := now();
BEGIN
  SELECT jsonb_agg(jsonb_build_object(
           'club_id', r.club_id, 'seated_end', r.seated_stack,
           'seated_end_cash', COALESCE(cc.seated_stack, 0),
           'net', 0, 'bootstrap', true))
    INTO v_results
    FROM fn_union_pnl_all_clubs(p_union_id, v_now - interval '1 second', v_now, true) r
    LEFT JOIN fn_union_pnl_cash_by_club(p_union_id, v_now - interval '1 second', v_now, true) cc
      ON cc.club_id = r.club_id;

  INSERT INTO union_pnl_settlements (union_id, period_start, period_end, status,
                                     total_collected, total_paid, total_unpaid, club_results)
  VALUES (p_union_id, v_now, v_now + interval '1 second', 'baseline', 0, 0, 0,
          COALESCE(v_results, '[]'::jsonb))
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('success', true, 'bootstrap_id', v_id,
                            'baseline_at', v_now, 'clubs', COALESCE(v_results, '[]'::jsonb));
END $$;


ALTER FUNCTION public.fn_union_pnl_bootstrap(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_union_pnl_cash_by_club(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_cash_by_club(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean DEFAULT true) RETURNS TABLE(club_id uuid, buyins numeric, cashouts numeric, realized_net numeric, players integer, seated_stack numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH attributed AS (
    SELECT DISTINCT ON (cm.user_id) cm.user_id, cm.club_id
      FROM club_members cm
      JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = p_union_id
      JOIN profiles p ON p.id = cm.user_id
     WHERE p_include_horses OR COALESCE(p.is_horse, false) = false
     ORDER BY cm.user_id, cm.joined_at ASC NULLS LAST, cm.club_id
  ),
  union_tables AS (
    SELECT id FROM tables WHERE union_id = p_union_id AND tournament_id IS NULL
  ),
  wallet_flows AS (
    SELECT a.club_id, wt.user_id,
           SUM(CASE WHEN wt.type = 'debit'  THEN wt.amount ELSE 0 END) AS buyins,
           SUM(CASE WHEN wt.type = 'credit' THEN wt.amount ELSE 0 END) AS cashouts
      FROM wallet_transactions wt
      JOIN attributed a ON a.user_id = wt.user_id
     WHERE wt.created_at >= p_start AND wt.created_at < p_end
       AND wt.category IN ('buyin','cashout')
       AND wt.table_id IN (SELECT id FROM union_tables)
     GROUP BY a.club_id, wt.user_id
  ),
  chip_flows AS (
    SELECT a.club_id, ct.to_user_id AS user_id, SUM(ct.amount) AS cashouts
      FROM chip_transactions ct
      JOIN union_tables ut ON ut.id = ct.table_id
      JOIN attributed a ON a.user_id = ct.to_user_id
     WHERE ct.transaction_type = 'cashout'
       AND ct.created_at >= p_start AND ct.created_at < p_end
       AND NOT COALESCE((ct.metadata->>'mirrored_to_wallet')::boolean, false)
     GROUP BY a.club_id, ct.to_user_id
  ),
  flows AS (
    SELECT COALESCE(w.club_id, c.club_id) AS club_id,
           COALESCE(w.user_id, c.user_id) AS user_id,
           COALESCE(w.buyins, 0) AS buyins,
           COALESCE(w.cashouts, 0) + COALESCE(c.cashouts, 0) AS cashouts
      FROM wallet_flows w
      FULL OUTER JOIN chip_flows c ON c.user_id = w.user_id AND c.club_id = w.club_id
  ),
  per_club AS (
    SELECT f.club_id, SUM(f.buyins) AS buyins, SUM(f.cashouts) AS cashouts,
           COUNT(*)::int AS players
      FROM flows f GROUP BY f.club_id
  ),
  seated AS (
    SELECT a.club_id, SUM(ts.stack) AS seated_stack
      FROM table_seats ts
      JOIN union_tables ut ON ut.id = ts.table_id
      JOIN attributed a ON a.user_id = ts.user_id
     WHERE ts.left_at IS NULL
     GROUP BY a.club_id
  )
  SELECT uc.club_id,
         COALESCE(pc.buyins, 0), COALESCE(pc.cashouts, 0),
         COALESCE(pc.cashouts, 0) - COALESCE(pc.buyins, 0),
         COALESCE(pc.players, 0),
         COALESCE(s.seated_stack, 0)
    FROM union_clubs uc
    LEFT JOIN per_club pc ON pc.club_id = uc.club_id
    LEFT JOIN seated s ON s.club_id = uc.club_id
   WHERE uc.union_id = p_union_id;
$$;


ALTER FUNCTION public.fn_union_pnl_cash_by_club(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean) OWNER TO postgres;

--
-- Name: fn_union_prev_week_start(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_prev_week_start(p_at timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT (date_trunc('week', (p_at AT TIME ZONE 'America/Los_Angeles')) - interval '7 days')
           AT TIME ZONE 'America/Los_Angeles';
$$;


ALTER FUNCTION public.fn_union_prev_week_start(p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_union_prev_week_start(p_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_prev_week_start(p_at timestamp with time zone) IS 'Start of the union week BEFORE the one containing p_at. Subtracts on the local timestamp so a DST week is still one calendar week.';


--
-- Name: fn_union_promo_send(uuid, numeric, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_promo_send(p_union_id uuid, p_amount numeric, p_destination text, p_club_id uuid, p_op_id uuid, p_created_by uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_amt        numeric := round(COALESCE(p_amount, 0), 2);
  v_actor      uuid := COALESCE(p_created_by, auth.uid());
  v_promo      numeric;
  v_after      numeric;
  v_club_after numeric;
  v_pool_id    uuid;
  v_club_name  text;
  v_note       text;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND NOT public.fn_union_can_manage_wallets(p_union_id, auth.uid()) THEN
    RETURN jsonb_build_object('success', false,
      'error', 'Only the union owner, co-owner or an admin can send from union wallets.');
  END IF;
  IF v_amt <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;
  IF p_destination NOT IN ('club', 'bbj_main') THEN
    RETURN jsonb_build_object('success', false, 'error', 'destination must be club or bbj_main');
  END IF;
  IF p_op_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'op_id_required');
  END IF;

  SELECT COALESCE(promo_wallet, 0) INTO v_promo
    FROM union_wallets WHERE union_id = p_union_id FOR UPDATE;
  IF v_promo IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'union wallet not found');
  END IF;
  IF v_promo < v_amt THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient promo balance',
                              'available', v_promo, 'requested', v_amt);
  END IF;

  IF p_destination = 'club' THEN
    IF p_club_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'club_id required');
    END IF;
    -- A union may only fund ITS OWN clubs. Without this a promo transfer is a
    -- chip mint into any club in the database.
    IF NOT EXISTS (SELECT 1 FROM union_clubs uc
                    WHERE uc.union_id = p_union_id AND uc.club_id = p_club_id) THEN
      RETURN jsonb_build_object('success', false, 'error', 'club is not in this union');
    END IF;
    SELECT c.name INTO v_club_name FROM clubs c WHERE c.id = p_club_id FOR UPDATE;
    IF v_club_name IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'club not found');
    END IF;
    v_note := COALESCE(NULLIF(btrim(p_notes), ''), 'Union Promo Wallet To ' || v_club_name || ' Promo Wallet');

    -- CHIP STANDARD 2.4: ONE journal row, union_wallet -> promo_wallet(club).
    -- The union_wallets trigger is skipped; the clubs trigger writes the row
    -- with the union wallet as its counterparty.
    PERFORM public.fn_ca_declare_ledger('promo_send', 'union_wallet', p_union_id, NULL,
      'union_promo_to_club:' || p_op_id::text, ARRAY['union_wallets']);
    PERFORM set_config('app.ledger_correlation', p_op_id::text, true);

    UPDATE union_wallets SET promo_wallet = promo_wallet - v_amt, updated_at = now()
     WHERE union_id = p_union_id RETURNING promo_wallet INTO v_after;

    -- THE CLUB'S PROMO WALLET. Not chip_treasury: that is the Club Bank, and
    -- a promo send that lands there is a promo send nobody can find.
    UPDATE clubs SET promo_balance = COALESCE(promo_balance, 0) + v_amt, updated_at = now()
     WHERE id = p_club_id RETURNING promo_balance INTO v_club_after;

    PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);

    INSERT INTO union_wallet_transactions
      (union_id, club_id, wallet, direction, amount, balance_after, tx_type, period_id, notes, created_by)
    VALUES
      (p_union_id, p_club_id, 'promo_wallet', 'debit', v_amt, v_after, 'promo_to_club', p_op_id,
       v_note, v_actor);

    INSERT INTO chip_transactions
      (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after, metadata)
    VALUES
      (p_club_id, v_actor, NULL, v_amt, 'union_promo_to_club', v_note, v_club_after,
       jsonb_build_object('union_id', p_union_id, 'op_id', p_op_id,
                          'destination', 'club_promo_wallet',
                          'union_promo_after', v_after,
                          'club_promo_after', v_club_after));

    RETURN jsonb_build_object('success', true, 'destination', 'club', 'amount', v_amt,
                              'promo_after', v_after,
                              'club_promo_after', v_club_after,
                              'club_treasury_after', NULL);
  END IF;

  -- destination = 'bbj_main'
  -- CHIP STANDARD (2026-09-05): this branch is a jackpot door and declares
  -- itself like every other one (Phase 4.3). ONE journal row,
  -- union_wallet -> bbj_pool (bbj_pools.main_balance), keyed on the
  -- operation, so the BBJ meter sees the seed and nothing lands in suspense.
  PERFORM public.fn_ca_declare_ledger('promo_send', 'union_wallet', p_union_id, NULL,
    'union_promo_to_bbj:' || p_op_id::text, ARRAY['union_wallets']);
  PERFORM set_config('app.ledger_correlation', p_op_id::text, true);

  UPDATE union_wallets SET promo_wallet = promo_wallet - v_amt, updated_at = now()
   WHERE union_id = p_union_id RETURNING promo_wallet INTO v_after;

  UPDATE bbj_pools
     SET main_balance = COALESCE(main_balance,0) + v_amt,
         pool_amount  = COALESCE(pool_amount,0)  + v_amt,
         updated_at   = now()
   WHERE union_id = p_union_id AND status = 'active'
   RETURNING id INTO v_pool_id;
  IF v_pool_id IS NULL THEN
    RAISE EXCEPTION 'no active BBJ pool for union %', p_union_id;
  END IF;
  PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);

  INSERT INTO union_wallet_transactions
    (union_id, wallet, direction, amount, balance_after, tx_type, period_id, notes, created_by)
  VALUES
    (p_union_id, 'promo_wallet', 'debit', v_amt, v_after, 'promo_to_bbj_main', p_op_id,
     COALESCE(NULLIF(p_notes, ''), 'Promo wallet -> main jackpot'), v_actor);

  RETURN jsonb_build_object('success', true, 'destination', 'bbj_main', 'amount', v_amt,
                            'promo_after', v_after, 'pool_id', v_pool_id);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('success', false, 'duplicate', true,
                            'error', 'operation already processed');
END;
$$;


ALTER FUNCTION public.fn_union_promo_send(p_union_id uuid, p_amount numeric, p_destination text, p_club_id uuid, p_op_id uuid, p_created_by uuid, p_notes text) OWNER TO postgres;

--
-- Name: FUNCTION fn_union_promo_send(p_union_id uuid, p_amount numeric, p_destination text, p_club_id uuid, p_op_id uuid, p_created_by uuid, p_notes text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_promo_send(p_union_id uuid, p_amount numeric, p_destination text, p_club_id uuid, p_op_id uuid, p_created_by uuid, p_notes text) IS 'Spends union_wallets.promo_wallet. destination=club credits clubs.promo_balance (the club Promo Wallet, NOT chip_treasury) - 2026-09-05. destination=bbj_main tops up the live jackpot.';


--
-- Name: fn_union_rake_basis_by_club(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_basis_by_club(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(club_id uuid, rake_share numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH legacy AS (
    SELECT DISTINCT ON (cm.user_id) cm.user_id, cm.club_id
      FROM club_members cm
      JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = p_union_id
     ORDER BY cm.user_id, cm.joined_at ASC NULLS LAST, cm.club_id
  ),
  ut AS (SELECT id FROM tables WHERE union_id = p_union_id AND tournament_id IS NULL),
  cash AS (
    SELECT
      COALESCE(
        (SELECT ts.club_id
           FROM table_seats ts
          WHERE ts.table_id = r.table_id
            AND ts.user_id = (e.key)::uuid
            AND ts.club_id IS NOT NULL
            AND ts.joined_at <= r.created_at
            AND (ts.left_at IS NULL OR ts.left_at >= r.created_at)
          ORDER BY ts.joined_at DESC
          LIMIT 1),
        l.club_id
      ) AS club_id,
      SUM(r.rake_amount * (e.value::numeric) / c.total) AS rake
      FROM rake_records r
      JOIN ut ON ut.id = r.table_id
      CROSS JOIN LATERAL (
        SELECT SUM(t.value::numeric) AS total
          FROM jsonb_each_text(r.player_contributions) AS t(key, value)
      ) c
      CROSS JOIN LATERAL jsonb_each_text(r.player_contributions) AS e(key, value)
      LEFT JOIN legacy l ON l.user_id = (e.key)::uuid
     WHERE r.created_at >= p_start AND r.created_at < p_end
       AND r.player_contributions IS NOT NULL AND r.rake_amount > 0
       AND c.total > 0
     GROUP BY 1
  ),
  -- UNION LAW: the club that paid the entry owns the entry fee. Previously
  -- re-derived from tournaments.buy_in_fee x registrations, which read zero
  -- for every spin and every rebuy and skipped tournaments missing union_id.
  -- Now the fee that was actually collected on the rake_records row.
  tourney AS (
    SELECT l.club_id, SUM(u.rake_amount) AS rake
      FROM fn_union_tournament_rake_by_user(p_union_id, p_start, p_end) u
      LEFT JOIN legacy l ON l.user_id = u.user_id
     GROUP BY l.club_id
  )
  SELECT club_id, round(SUM(rake), 2) AS rake_share
    FROM (SELECT club_id, rake FROM cash
          UNION ALL
          SELECT club_id, rake FROM tourney) x
   WHERE club_id IS NOT NULL
   GROUP BY club_id;
$$;


ALTER FUNCTION public.fn_union_rake_basis_by_club(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_rake_basis_refresh(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_basis_refresh(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_through timestamptz; v_t0 timestamptz := clock_timestamp(); v_detail jsonb; v_n int;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR NOT public.fn_is_platform_admin()) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;
  IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR p_end <= p_start THEN
    RETURN jsonb_build_object('success', false, 'error', 'bad_params');
  END IF;
  v_through := LEAST(p_end, now());
  IF v_through <= p_start THEN
    RETURN jsonb_build_object('success', false, 'error', 'window_not_open_yet');
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('club_id', b.club_id, 'game_type', b.game_type,
                                               'rake_in', b.rake_in, 'rate', b.rate, 'payout', b.payout)
                            ORDER BY b.club_id, b.game_type), '[]'::jsonb), count(*)
    INTO v_detail, v_n
    FROM public.fn_union_club_rake_basis(p_union_id, p_start, v_through, true) b;

  INSERT INTO public.union_rake_basis_snapshot (union_id, period_start, period_end, through, computed_at, compute_ms, detail)
  VALUES (p_union_id, p_start, p_end, v_through, now(),
          (extract(epoch from clock_timestamp() - v_t0) * 1000)::int, v_detail)
  ON CONFLICT (union_id, period_start, period_end) DO UPDATE
    SET through = EXCLUDED.through, computed_at = EXCLUDED.computed_at,
        compute_ms = EXCLUDED.compute_ms, detail = EXCLUDED.detail;

  RETURN jsonb_build_object('success', true, 'union_id', p_union_id, 'period_start', p_start,
                            'period_end', p_end, 'through', v_through, 'rows', v_n,
                            'compute_ms', (extract(epoch from clock_timestamp() - v_t0) * 1000)::int);
END;
$$;


ALTER FUNCTION public.fn_union_rake_basis_refresh(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_rake_by_club(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_by_club(p_union_id uuid, p_days integer DEFAULT 30) RETURNS TABLE(club_id uuid, club_name text, rake numeric, players bigint, player_hands bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT d.club_id,
         COALESCE(c.name, 'Union Tables')::text,
         SUM(d.rake_amount)::numeric,
         COUNT(DISTINCT d.user_id)::bigint,
         SUM(d.hands)::bigint
    FROM club_rake_daily_user d
    JOIN fn_union_club_scope(p_union_id) s ON s.club_id = d.club_id
    LEFT JOIN clubs c ON c.id = d.club_id
   WHERE public.fn_union_report_caller_ok(p_union_id)
     AND d.day >= (CURRENT_DATE - GREATEST(COALESCE(p_days, 30), 1))
   GROUP BY d.club_id, c.name
   ORDER BY 3 DESC;
$$;


ALTER FUNCTION public.fn_union_rake_by_club(p_union_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: fn_union_rake_by_day(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_by_day(p_union_id uuid, p_days integer DEFAULT 30) RETURNS TABLE(day date, rake numeric, players bigint, player_hands bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT d.day,
         SUM(d.rake_amount)::numeric,
         COUNT(DISTINCT d.user_id)::bigint,
         SUM(d.hands)::bigint
    FROM club_rake_daily_user d
    JOIN fn_union_club_scope(p_union_id) s ON s.club_id = d.club_id
   WHERE public.fn_union_report_caller_ok(p_union_id)
     AND d.day >= (CURRENT_DATE - GREATEST(COALESCE(p_days, 30), 1))
   GROUP BY d.day
   ORDER BY d.day DESC;
$$;


ALTER FUNCTION public.fn_union_rake_by_day(p_union_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: fn_union_rake_day_is_fresh(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_day_is_fresh(p_union_id uuid, p_day date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM union_rake_rollup_days d
     WHERE d.union_id = p_union_id AND d.day = p_day
       AND d.records_seen =
             (SELECT count(*)
                FROM rake_records r
                JOIN tables t ON t.id = r.table_id AND t.union_id = p_union_id
               WHERE r.created_at >= (p_day::timestamp AT TIME ZONE 'UTC')
                 AND r.created_at <  ((p_day + 1)::timestamp AT TIME ZONE 'UTC')
                 AND r.player_contributions IS NOT NULL AND r.rake_amount > 0)
           + (SELECT count(*)
                FROM rake_records r
               WHERE r.is_tournament
                 AND r.created_at >= (p_day::timestamp AT TIME ZONE 'UTC')
                 AND r.created_at <  ((p_day + 1)::timestamp AT TIME ZONE 'UTC')
                 AND r.rake_amount <> 0
                 AND (r.club_id = p_union_id
                      OR EXISTS (SELECT 1 FROM union_clubs uc
                                  WHERE uc.union_id = p_union_id AND uc.club_id = r.club_id))));
$$;


ALTER FUNCTION public.fn_union_rake_day_is_fresh(p_union_id uuid, p_day date) OWNER TO postgres;

--
-- Name: fn_union_rake_ledger_checkpoint_verify(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_ledger_checkpoint_verify(p_union_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target   timestamptz := now() - interval '1 hour';
  v_cr       numeric; v_db numeric; v_rows bigint;
  v_old_cr   numeric; v_old_db numeric; v_old_as_of timestamptz;
  v_tail_cr  numeric; v_tail_db numeric;
  v_believed numeric; v_truth numeric; v_drift numeric;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('union_rake_ledger_cp:' || p_union_id::text, 42));

  SELECT c.credits, c.debits, c.as_of
    INTO v_old_cr, v_old_db, v_old_as_of
    FROM union_rake_ledger_checkpoint c WHERE c.union_id = p_union_id;

  SELECT COALESCE(SUM(t.amount) FILTER (WHERE t.direction = 'credit'), 0),
         COALESCE(SUM(t.amount) FILTER (WHERE t.direction = 'debit'), 0),
         COUNT(*)
    INTO v_cr, v_db, v_rows
    FROM union_wallet_transactions t
   WHERE t.union_id = p_union_id AND t.wallet = 'rake_wallet'
     AND t.created_at < v_target;
  v_truth := v_cr - v_db;

  IF v_old_as_of IS NOT NULL THEN
    SELECT COALESCE(SUM(t.amount) FILTER (WHERE t.direction = 'credit'), 0),
           COALESCE(SUM(t.amount) FILTER (WHERE t.direction = 'debit'), 0)
      INTO v_tail_cr, v_tail_db
      FROM union_wallet_transactions t
     WHERE t.union_id = p_union_id AND t.wallet = 'rake_wallet'
       AND t.created_at >= v_old_as_of AND t.created_at < v_target;
    v_believed := (v_old_cr + v_tail_cr) - (v_old_db + v_tail_db);
    v_drift    := round(v_believed - v_truth, 2);
  END IF;

  INSERT INTO union_rake_ledger_checkpoint
        (union_id, as_of, credits, debits, rows_seen, last_verified_at, updated_at)
  VALUES (p_union_id, v_target, v_cr, v_db, v_rows, now(), now())
  ON CONFLICT (union_id) DO UPDATE
    SET as_of            = EXCLUDED.as_of,
        credits          = EXCLUDED.credits,
        debits           = EXCLUDED.debits,
        rows_seen        = EXCLUDED.rows_seen,
        last_verified_at = now(),
        updated_at       = now();

  IF COALESCE(v_drift, 0) <> 0 THEN
    INSERT INTO financial_alerts (severity, source, message, context)
    SELECT 'critical', 'fn_union_rake_ledger_checkpoint_verify',
           'Union rake ledger checkpoint drifted from recomputed truth',
           jsonb_build_object('union_id', p_union_id, 'drift', v_drift,
                              'believed', v_believed, 'truth', v_truth)
     WHERE NOT EXISTS (
       SELECT 1 FROM financial_alerts
        WHERE source = 'fn_union_rake_ledger_checkpoint_verify'
          AND resolved IS NOT TRUE
          AND context->>'union_id' = p_union_id::text);
  END IF;

  RETURN jsonb_build_object(
    'union_id', p_union_id, 'as_of', v_target,
    'credits', v_cr, 'debits', v_db, 'rows_seen', v_rows,
    'net', v_truth, 'drift', COALESCE(v_drift, 0));
END;
$$;


ALTER FUNCTION public.fn_union_rake_ledger_checkpoint_verify(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_union_rake_ledger_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_ledger_summary(p_union_id uuid) RETURNS TABLE(credits numeric, debits numeric, net numeric, rows_seen bigint, as_of timestamp with time zone, last_verified_at timestamp with time zone, through_day date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT
    COALESCE(cp.credits, 0)::numeric,
    COALESCE(cp.debits, 0)::numeric,
    (COALESCE(cp.credits, 0) - COALESCE(cp.debits, 0))::numeric,
    COALESCE(cp.rows_seen, 0)::bigint,
    cp.as_of,
    cp.last_verified_at,
    (SELECT max(d.day)
       FROM club_rake_daily_user d
       JOIN fn_union_club_scope(p_union_id) s ON s.club_id = d.club_id)
  FROM union_rake_ledger_checkpoint cp
  WHERE cp.union_id = p_union_id
    AND public.fn_union_report_caller_ok(p_union_id);
$$;


ALTER FUNCTION public.fn_union_rake_ledger_summary(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_union_rake_ledger_totals(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_ledger_totals(p_union_id uuid) RETURNS TABLE(total_credits numeric, total_debits numeric, total_rows bigint, checkpoint_as_of timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_as_of  timestamptz;
  v_cr     numeric;
  v_db     numeric;
  v_rows   bigint;
  v_target timestamptz := now() - interval '1 hour';
  d_cr     numeric;
  d_db     numeric;
  d_rows   bigint;
BEGIN
  SELECT c.as_of, c.credits, c.debits, c.rows_seen
    INTO v_as_of, v_cr, v_db, v_rows
    FROM union_rake_ledger_checkpoint c WHERE c.union_id = p_union_id;
  IF NOT FOUND THEN
    v_as_of := '-infinity'::timestamptz; v_cr := 0; v_db := 0; v_rows := 0;
  END IF;

  IF v_target > v_as_of THEN
    -- Advancing the checkpoint is a pure optimization: if it fails (read-only
    -- context, lock trouble) the totals below are still exact, just computed
    -- over a longer tail.
    BEGIN
      PERFORM pg_advisory_xact_lock(
        hashtextextended('union_rake_ledger_cp:' || p_union_id::text, 42));

      -- Re-read under the lock; a concurrent caller may have advanced it.
      SELECT c.as_of, c.credits, c.debits, c.rows_seen
        INTO v_as_of, v_cr, v_db, v_rows
        FROM union_rake_ledger_checkpoint c WHERE c.union_id = p_union_id;
      IF NOT FOUND THEN
        v_as_of := '-infinity'::timestamptz; v_cr := 0; v_db := 0; v_rows := 0;
      END IF;

      IF v_target > v_as_of THEN
        SELECT COALESCE(SUM(t.amount) FILTER (WHERE t.direction = 'credit'), 0),
               COALESCE(SUM(t.amount) FILTER (WHERE t.direction = 'debit'), 0),
               COUNT(*)
          INTO d_cr, d_db, d_rows
          FROM union_wallet_transactions t
         WHERE t.union_id = p_union_id AND t.wallet = 'rake_wallet'
           AND t.created_at >= v_as_of AND t.created_at < v_target;

        INSERT INTO union_rake_ledger_checkpoint
              (union_id, as_of, credits, debits, rows_seen, last_verified_at, updated_at)
        VALUES (p_union_id, v_target, v_cr + d_cr, v_db + d_db, v_rows + d_rows, now(), now())
        ON CONFLICT (union_id) DO UPDATE
          SET as_of     = EXCLUDED.as_of,
              credits   = EXCLUDED.credits,
              debits    = EXCLUDED.debits,
              rows_seen = EXCLUDED.rows_seen,
              updated_at = now();

        -- Only adopt the advanced values after the write succeeded.
        v_as_of := v_target;
        v_cr    := v_cr + d_cr;
        v_db    := v_db + d_db;
        v_rows  := v_rows + d_rows;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;  -- best effort; fall through with the un-advanced checkpoint
    END;
  END IF;

  RETURN QUERY
  SELECT v_cr   + COALESCE(SUM(t.amount) FILTER (WHERE t.direction = 'credit'), 0),
         v_db   + COALESCE(SUM(t.amount) FILTER (WHERE t.direction = 'debit'), 0),
         v_rows + COUNT(t.*),
         v_as_of
    FROM union_wallet_transactions t
   WHERE t.union_id = p_union_id AND t.wallet = 'rake_wallet'
     AND t.created_at >= v_as_of;
END;
$$;


ALTER FUNCTION public.fn_union_rake_ledger_totals(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_union_rake_paid_by_club(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_paid_by_club(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean DEFAULT true) RETURNS TABLE(club_id uuid, rake_paid numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_first_day date;
  v_end_day   date;
  v_today     date := (now() AT TIME ZONE 'UTC')::date;
  d           date;
BEGIN
  v_first_day := (p_start AT TIME ZONE 'UTC')::date;
  IF (v_first_day::timestamp AT TIME ZONE 'UTC') < p_start THEN
    v_first_day := v_first_day + 1;
  END IF;
  v_end_day := (p_end AT TIME ZONE 'UTC')::date;
  IF v_end_day > v_today THEN
    v_end_day := v_today;
  END IF;

  IF v_first_day < v_end_day THEN
    FOR d IN
      SELECT gs::date
        FROM generate_series(v_first_day, v_end_day - 1, interval '1 day') gs
       WHERE NOT fn_union_rake_day_is_fresh(p_union_id, gs::date)
    LOOP
      BEGIN
        PERFORM fn_union_rake_rollup_refresh_day(p_union_id, d);
      EXCEPTION WHEN OTHERS THEN
        NULL;  -- reader computes this single day live; bounded either way
      END;
    END LOOP;
  END IF;

  RETURN QUERY
    SELECT r.club_id, r.rake_paid
      FROM fn_union_rake_paid_readonly(p_union_id, p_start, p_end, p_include_horses) r;
END;
$$;


ALTER FUNCTION public.fn_union_rake_paid_by_club(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean) OWNER TO postgres;

--
-- Name: fn_union_rake_paid_live(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_paid_live(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean DEFAULT true) RETURNS TABLE(club_id uuid, rake_paid numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH attributed AS (
    SELECT DISTINCT ON (cm.user_id) cm.user_id, cm.club_id
      FROM club_members cm
      JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = p_union_id
      JOIN profiles p ON p.id = cm.user_id
     WHERE p_include_horses OR COALESCE(p.is_horse, false) = false
     ORDER BY cm.user_id, cm.joined_at ASC NULLS LAST, cm.club_id
  ),
  expanded AS (
    SELECT r.id, r.rake_amount, e.key, (e.value)::numeric AS contrib,
           SUM((e.value)::numeric) OVER (PARTITION BY r.id) AS total_contrib
      FROM rake_records r
      JOIN tables t ON t.id = r.table_id AND t.union_id = p_union_id
      CROSS JOIN LATERAL jsonb_each_text(r.player_contributions) e(key, value)
     WHERE r.created_at >= p_start AND r.created_at < p_end
       AND r.player_contributions IS NOT NULL AND r.rake_amount > 0
  ),
  cash AS (
    SELECT a.club_id, SUM(expanded.rake_amount * expanded.contrib / expanded.total_contrib) AS rake
      FROM expanded JOIN attributed a ON a.user_id = (expanded.key)::uuid
     WHERE expanded.total_contrib > 0
     GROUP BY a.club_id
  ),
  -- MTT / SNG / SPIN buy-in and rebuy fees. These rake_records carry
  -- table_id NULL, so the join above cannot see them; before 2026-08-20 they
  -- were dropped entirely.
  tourney AS (
    SELECT a.club_id, SUM(u.rake_amount) AS rake
      FROM fn_union_tournament_rake_by_user(p_union_id, p_start, p_end) u
      JOIN attributed a ON a.user_id = u.user_id
     GROUP BY a.club_id
  )
  SELECT x.club_id, SUM(x.rake)
    FROM (SELECT * FROM cash UNION ALL SELECT * FROM tourney) x
   GROUP BY x.club_id;
$$;


ALTER FUNCTION public.fn_union_rake_paid_live(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean) OWNER TO postgres;

--
-- Name: fn_union_rake_paid_readonly(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_paid_readonly(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean DEFAULT true) RETURNS TABLE(club_id uuid, rake_paid numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_first_day date;
  v_end_day   date;
  v_today     date := (now() AT TIME ZONE 'UTC')::date;
BEGIN
  v_first_day := (p_start AT TIME ZONE 'UTC')::date;
  IF (v_first_day::timestamp AT TIME ZONE 'UTC') < p_start THEN
    v_first_day := v_first_day + 1;
  END IF;
  v_end_day := (p_end AT TIME ZONE 'UTC')::date;
  IF v_end_day > v_today THEN
    v_end_day := v_today;
  END IF;

  IF v_first_day >= v_end_day THEN
    RETURN QUERY
      SELECT l.club_id, round(l.rake_paid, 2)
        FROM fn_union_rake_paid_live(p_union_id, p_start, p_end, p_include_horses) l;
    RETURN;
  END IF;

  RETURN QUERY
  WITH attributed AS (
    SELECT DISTINCT ON (cm.user_id) cm.user_id, cm.club_id
      FROM club_members cm
      JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = p_union_id
      JOIN profiles p ON p.id = cm.user_id
     WHERE p_include_horses OR COALESCE(p.is_horse, false) = false
     ORDER BY cm.user_id, cm.joined_at ASC NULLS LAST, cm.club_id
  ),
  days AS (
    SELECT gs::date AS d
      FROM generate_series(v_first_day, v_end_day - 1, interval '1 day') gs
  ),
  -- A day counts as usable only if its cached record count still matches
  -- reality; otherwise it is recomputed live below.
  fresh_days AS (
    SELECT days.d FROM days WHERE fn_union_rake_day_is_fresh(p_union_id, days.d)
  ),
  stale_days AS (
    SELECT days.d FROM days
     WHERE NOT EXISTS (SELECT 1 FROM fresh_days f WHERE f.d = days.d)
  ),
  rolled AS (
    SELECT a.club_id AS cid, u.rake_amount AS s
      FROM union_rake_paid_daily_user u
      JOIN fresh_days f ON f.d = u.day
      JOIN attributed a ON a.user_id = u.user_id
     WHERE u.union_id = p_union_id
  ),
  live_days AS (
    SELECT l.club_id AS cid, l.rake_paid AS s
      FROM stale_days m
      CROSS JOIN LATERAL fn_union_rake_paid_live(
        p_union_id,
        (m.d::timestamp AT TIME ZONE 'UTC'),
        ((m.d + 1)::timestamp AT TIME ZONE 'UTC'),
        p_include_horses) l
  ),
  edges AS (
    SELECT l.club_id AS cid, l.rake_paid AS s
      FROM fn_union_rake_paid_live(
        p_union_id, p_start, (v_first_day::timestamp AT TIME ZONE 'UTC'), p_include_horses) l
    UNION ALL
    SELECT l.club_id, l.rake_paid
      FROM fn_union_rake_paid_live(
        p_union_id, (v_end_day::timestamp AT TIME ZONE 'UTC'), p_end, p_include_horses) l
  ),
  combined AS (
    SELECT x.cid, SUM(x.s) AS s
      FROM (SELECT * FROM rolled
            UNION ALL SELECT * FROM live_days
            UNION ALL SELECT * FROM edges) x
     GROUP BY x.cid
  )
  SELECT c.cid, round(c.s, 2) FROM combined c WHERE c.s IS NOT NULL;
END;
$$;


ALTER FUNCTION public.fn_union_rake_paid_readonly(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean) OWNER TO postgres;

--
-- Name: fn_union_rake_rollup_catchup(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_rollup_catchup(p_union_id uuid, p_max_days integer DEFAULT 3, p_lookback_days integer DEFAULT 4) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  d date;
  v_stale date[];
  v_done text[] := '{}';
  v_failed text[] := '{}';
  v_rolled int := 0;
BEGIN
  -- ONE scan for the whole window. This used to call
  -- fn_union_rake_day_is_fresh once per day to pick the stale days and then
  -- AGAIN once per day to count what was left -- about 20 separate full-day
  -- counts over rake_records for the old 10-day lookback, each joining ~100k
  -- rows to tables. That reliably exceeded the 8s statement timeout, so the
  -- catch-up aborted on every settler cycle and the rollup was only ever kept
  -- current by its lazy readers.
  v_stale := ARRAY(
    SELECT s FROM fn_union_rake_stale_days(p_union_id, v_today - p_lookback_days, v_today) s
  );

  FOREACH d IN ARRAY v_stale LOOP
    EXIT WHEN v_rolled >= GREATEST(p_max_days, 0);
    BEGIN
      PERFORM fn_union_rake_rollup_refresh_day(p_union_id, d);
      v_done := v_done || d::text;
      v_rolled := v_rolled + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed || (d::text || ':' || SQLERRM);
      v_rolled := v_rolled + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'union_id', p_union_id,
    'rolled', to_jsonb(v_done),
    'failed', to_jsonb(v_failed),
    -- Everything we did not get to this cycle. Derived from the single scan
    -- above rather than re-counting, so reporting cannot itself time out.
    'stale_remaining', GREATEST(COALESCE(array_length(v_stale, 1), 0) - v_rolled, 0));
END;
$$;


ALTER FUNCTION public.fn_union_rake_rollup_catchup(p_union_id uuid, p_max_days integer, p_lookback_days integer) OWNER TO postgres;

--
-- Name: fn_union_rake_rollup_catchup_all(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_rollup_catchup_all(p_max_days integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  u record;
  v_out jsonb := '[]'::jsonb;
BEGIN
  FOR u IN
    SELECT DISTINCT un.id
      FROM unions un
     WHERE EXISTS (SELECT 1 FROM tables t WHERE t.union_id = un.id)
        OR EXISTS (SELECT 1 FROM union_clubs uc WHERE uc.union_id = un.id)
  LOOP
    v_out := v_out || jsonb_build_array(fn_union_rake_rollup_catchup(u.id, p_max_days));
  END LOOP;
  RETURN jsonb_build_object('unions', v_out);
END;
$$;


ALTER FUNCTION public.fn_union_rake_rollup_catchup_all(p_max_days integer) OWNER TO postgres;

--
-- Name: fn_union_rake_rollup_refresh_day(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_rollup_refresh_day(p_union_id uuid, p_day date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start timestamptz := (p_day::timestamp AT TIME ZONE 'UTC');
  v_end   timestamptz := ((p_day + 1)::timestamp AT TIME ZONE 'UTC');
  v_records integer;
BEGIN
  IF v_end > now() THEN
    RAISE EXCEPTION 'union rake rollup: day % is not complete (UTC); refusing to finalize', p_day;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('union_rake_rollup:' || p_union_id::text || ':' || p_day::text, 42));

  DELETE FROM union_rake_rollup_days
   WHERE union_id = p_union_id AND day = p_day;  -- cascades to detail

  -- counts BOTH legs, so the freshness test below can detect a cash-only day
  SELECT (SELECT count(*)
            FROM rake_records r
            JOIN tables t ON t.id = r.table_id AND t.union_id = p_union_id
           WHERE r.created_at >= v_start AND r.created_at < v_end
             AND r.player_contributions IS NOT NULL AND r.rake_amount > 0)
       + (SELECT count(*)
            FROM rake_records r
           WHERE r.is_tournament
             AND r.created_at >= v_start AND r.created_at < v_end
             AND r.rake_amount <> 0
             AND (r.club_id = p_union_id
                  OR EXISTS (SELECT 1 FROM union_clubs uc
                              WHERE uc.union_id = p_union_id AND uc.club_id = r.club_id)))
    INTO v_records;

  INSERT INTO union_rake_rollup_days (union_id, day, records_seen)
  VALUES (p_union_id, p_day, v_records);

  INSERT INTO union_rake_paid_daily_user (union_id, day, user_id, rake_amount)
  WITH expanded AS (
    SELECT (e.key)::uuid AS user_id,
           r.rake_amount * (e.value)::numeric
             / NULLIF(SUM((e.value)::numeric) OVER (PARTITION BY r.id), 0) AS share
      FROM rake_records r
      JOIN tables t ON t.id = r.table_id AND t.union_id = p_union_id
      CROSS JOIN LATERAL jsonb_each_text(r.player_contributions) e(key, value)
     WHERE r.created_at >= v_start AND r.created_at < v_end
       AND r.player_contributions IS NOT NULL AND r.rake_amount > 0
  ),
  all_legs AS (
    SELECT expanded.user_id, expanded.share FROM expanded WHERE expanded.share IS NOT NULL
    UNION ALL
    SELECT u.user_id, u.rake_amount
      FROM fn_union_tournament_rake_by_user(p_union_id, v_start, v_end) u
  )
  SELECT p_union_id, p_day, all_legs.user_id, SUM(all_legs.share)
    FROM all_legs
   GROUP BY all_legs.user_id;
END;
$$;


ALTER FUNCTION public.fn_union_rake_rollup_refresh_day(p_union_id uuid, p_day date) OWNER TO postgres;

--
-- Name: fn_union_rake_stale_days(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_stale_days(p_union_id uuid, p_from date, p_to_exclusive date) RETURNS SETOF date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
  WITH live AS (
    SELECT (r.created_at AT TIME ZONE 'UTC')::date AS day, count(*) AS n
      FROM rake_records r
      JOIN tables t ON t.id = r.table_id AND t.union_id = p_union_id
     WHERE r.created_at >= (p_from::timestamp AT TIME ZONE 'UTC')
       AND r.created_at <  (p_to_exclusive::timestamp AT TIME ZONE 'UTC')
       AND r.player_contributions IS NOT NULL AND r.rake_amount > 0
     GROUP BY 1
  ),
  days AS (
    SELECT gs::date AS day
      FROM generate_series(p_from, p_to_exclusive - 1, interval '1 day') gs
  )
  SELECT d.day
    FROM days d
    LEFT JOIN live l ON l.day = d.day
    LEFT JOIN union_rake_rollup_days u
      ON u.union_id = p_union_id AND u.day = d.day
   WHERE u.day IS NULL
      OR u.records_seen IS DISTINCT FROM COALESCE(l.n, 0)
   ORDER BY d.day;
$$;


ALTER FUNCTION public.fn_union_rake_stale_days(p_union_id uuid, p_from date, p_to_exclusive date) OWNER TO postgres;

--
-- Name: fn_union_rake_weekly_verify(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_weekly_verify() RETURNS TABLE(union_id uuid, club_id uuid, week_start date, ledger numeric, rollup numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH ledger AS (
    SELECT t.union_id, t.club_id, date_trunc('week', t.created_at)::date AS week_start,
           SUM(t.amount) AS amt
      FROM public.union_wallet_transactions t
     WHERE t.wallet='rake_wallet' AND t.direction='credit' AND t.tx_type='rake'
       AND t.union_id IS NOT NULL
     GROUP BY 1,2,3
  )
  SELECT COALESCE(l.union_id, r.union_id),
         COALESCE(l.club_id,  r.club_id),
         COALESCE(l.week_start, r.week_start),
         COALESCE(l.amt, 0), COALESCE(r.rake_total, 0)
    FROM ledger l
    FULL JOIN public.union_rake_weekly r
      ON r.union_id = l.union_id
     AND r.week_start = l.week_start
     AND r.club_id IS NOT DISTINCT FROM l.club_id
   WHERE COALESCE(l.amt, 0) <> COALESCE(r.rake_total, 0);
$$;


ALTER FUNCTION public.fn_union_rake_weekly_verify() OWNER TO postgres;

--
-- Name: fn_union_reconciliation_report(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_reconciliation_report(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, buyins numeric, cashouts numeric, realized_net numeric, seated_start numeric, seated_end numeric, stack_delta numeric, rake_paid numeric, settle_net numeric, direction text, turnover numeric, house_residual numeric, tolerance numeric, within_tolerance boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prev jsonb;
  v_caller uuid := auth.uid();
BEGIN
  -- Authorization. auth.uid() IS NULL means the service role (no JWT), which
  -- is how the workers, the engine and the API routes call this.
  IF v_caller IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM unions u
                      WHERE u.id = p_union_id AND u.owner_id = v_caller)
     AND NOT EXISTS (SELECT 1 FROM union_admins ua
                      WHERE ua.union_id = p_union_id AND ua.user_id = v_caller)
     AND NOT EXISTS (SELECT 1
                       FROM union_clubs uc
                       JOIN club_members cm ON cm.club_id = uc.club_id
                      WHERE uc.union_id = p_union_id
                        AND cm.user_id = v_caller
                        AND cm.role IN ('owner','co_owner','admin','super_agent'))
  THEN
    RAISE EXCEPTION 'not authorized to read union reconciliation'
      USING ERRCODE = '42501';
  END IF;

  v_prev := fn_union_pnl_baseline(p_union_id, p_start);

  RETURN QUERY
  WITH pnl AS (
    SELECT c.club_id, c.buyins, c.cashouts, c.realized_net, c.seated_stack
      FROM fn_union_pnl_all_clubs(p_union_id, p_start, p_end, true) c
  ),
  rk AS (
    -- Phase 6 (20260907): the one basis, the same rows round 1 pays on.
    SELECT b.club_id, round(sum(b.rake_in), 2) AS rake_paid
      FROM public.fn_union_club_rake_basis(p_union_id, p_start, p_end) b
     GROUP BY b.club_id
  ),
  base AS (
    SELECT (e->>'club_id')::uuid AS club_id, (e->>'seated_end')::numeric AS seated_start
      FROM jsonb_array_elements(COALESCE(v_prev, '[]'::jsonb)) e
  ),
  rows AS (
    SELECT p.club_id,
           cl.name::text AS club_name,
           p.buyins, p.cashouts, p.realized_net,
           COALESCE(b.seated_start, p.seated_stack) AS seated_start,
           p.seated_stack AS seated_end,
           round(p.seated_stack - COALESCE(b.seated_start, p.seated_stack), 2) AS stack_delta,
           COALESCE(k.rake_paid, 0) AS rake_paid,
           round(p.realized_net
                 + (p.seated_stack - COALESCE(b.seated_start, p.seated_stack))
                 + COALESCE(k.rake_paid, 0), 2) AS settle_net,
           (p.buyins + p.cashouts) AS turnover
      FROM pnl p
      LEFT JOIN clubs cl ON cl.id = p.club_id
      LEFT JOIN rk k ON k.club_id = p.club_id
      LEFT JOIN base b ON b.club_id = p.club_id
  ),
  agg AS (
    SELECT round(SUM(r.settle_net), 2) AS residual,
           round(SUM(r.turnover), 2) AS total_turnover
      FROM rows r
  )
  SELECT r.club_id, r.club_name, r.buyins, r.cashouts, r.realized_net,
         r.seated_start, r.seated_end, r.stack_delta, r.rake_paid, r.settle_net,
         CASE WHEN r.settle_net < 0 THEN 'club pays union'
              WHEN r.settle_net > 0 THEN 'union pays club'
              ELSE 'square' END::text,
         r.turnover,
         a.residual,
         GREATEST(100, round(a.total_turnover * 0.01, 2)),
         abs(a.residual) <= GREATEST(100, round(a.total_turnover * 0.01, 2))
    FROM rows r CROSS JOIN agg a
   ORDER BY r.settle_net;
END;
$$;


ALTER FUNCTION public.fn_union_reconciliation_report(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_record_presettlement(uuid, uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_record_presettlement(p_union_id uuid, p_club_id uuid, p_amount numeric, p_method text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_id uuid;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'positive amount required');
  END IF;

  -- Only the service role, the union owner, or a union admin may record money.
  IF v_caller IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM unions u WHERE u.id = p_union_id AND u.owner_id = v_caller)
     AND NOT EXISTS (SELECT 1 FROM union_admins ua
                      WHERE ua.union_id = p_union_id AND ua.user_id = v_caller) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authorized');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM union_clubs uc
                  WHERE uc.union_id = p_union_id AND uc.club_id = p_club_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'club is not a member of this union');
  END IF;

  INSERT INTO union_presettlements (union_id, club_id, amount, method, reference, note, recorded_by)
  VALUES (p_union_id, p_club_id, p_amount, p_method, p_reference, p_note, v_caller)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('success', true, 'presettlement_id', v_id, 'amount', p_amount);
END;
$$;


ALTER FUNCTION public.fn_union_record_presettlement(p_union_id uuid, p_club_id uuid, p_amount numeric, p_method text, p_reference text, p_note text) OWNER TO postgres;

--
-- Name: fn_union_report_caller_ok(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_report_caller_ok(p_union_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT p_union_id IS NOT NULL AND (
    COALESCE(
      NULLIF(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
      ''
    ) = 'service_role'
    OR (
      auth.uid() IS NOT NULL AND (
        EXISTS (SELECT 1 FROM unions u
                 WHERE u.id = p_union_id AND u.owner_id = auth.uid())
        OR EXISTS (SELECT 1 FROM union_admins ua
                    WHERE ua.union_id = p_union_id AND ua.user_id = auth.uid())
      )
    )
  );
$$;


ALTER FUNCTION public.fn_union_report_caller_ok(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_union_resolve_invoice_dispute(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_resolve_invoice_dispute(p_invoice_id uuid, p_resolution text, p_new_status text DEFAULT 'generated'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inv      settlement_invoices%ROWTYPE;
  v_union_id uuid;
  v_open     int;
BEGIN
  SELECT * INTO v_inv FROM settlement_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF v_inv.id IS NULL THEN RAISE EXCEPTION 'invoice not found'; END IF;

  v_union_id := (v_inv.breakdown->>'union_id')::uuid;

  -- WHO IS CALLING, before anything that would describe the document.
  IF auth.uid() IS NOT NULL
     AND (v_union_id IS NULL
          OR (NOT EXISTS (SELECT 1 FROM unions u WHERE u.id = v_union_id AND u.owner_id = auth.uid())
              AND NOT EXISTS (SELECT 1 FROM union_admins ua WHERE ua.union_id = v_union_id AND ua.user_id = auth.uid())
              AND NOT COALESCE(public.fn_is_platform_admin(), false))) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  IF COALESCE(btrim(p_resolution), '') = '' THEN
    RAISE EXCEPTION 'a resolution must say what was decided';
  END IF;
  IF p_new_status NOT IN ('generated','paid','cancelled') THEN
    RAISE EXCEPTION 'a resolved dispute must land on generated, paid or cancelled, not %', p_new_status;
  END IF;
  IF v_inv.status <> 'disputed' THEN
    RAISE EXCEPTION 'invoice % is not disputed (status %)',
      COALESCE(v_inv.invoice_number, v_inv.id::text), v_inv.status;
  END IF;

  UPDATE settlement_invoices
     SET status = p_new_status,
         notes = COALESCE(notes, '') || E'\nRESOLVED ' || to_char(now(), 'YYYY-MM-DD HH24:MI')
                 || ': ' || p_resolution,
         updated_at = now()
   WHERE id = p_invoice_id;

  SELECT count(*) INTO v_open
    FROM settlement_invoices
   WHERE period_id = v_inv.period_id AND status = 'disputed';

  IF v_open = 0 THEN
    UPDATE settlement_periods
       SET status = 'settled', updated_at = now()
     WHERE id = v_inv.period_id AND status = 'disputed';
  END IF;

  RETURN jsonb_build_object('success', true,
    'invoice', COALESCE(v_inv.invoice_number, v_inv.id::text),
    'new_status', p_new_status,
    'disputes_still_open_on_period', v_open,
    'period_returned_to_settled', (v_open = 0));
END $$;


ALTER FUNCTION public.fn_union_resolve_invoice_dispute(p_invoice_id uuid, p_resolution text, p_new_status text) OWNER TO postgres;

--
-- Name: fn_union_send_chips_to_club(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_send_chips_to_club(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_union_balance NUMERIC;
  v_owner_user_id UUID;
BEGIN
  -- 1. Validate amount
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Transfer amount must be positive';
  END IF;

  -- 2. Lock + check union wallet balance
  SELECT chip_balance INTO v_union_balance
    FROM public.union_wallets WHERE union_id = p_union_id FOR UPDATE;
  IF v_union_balance IS NULL THEN
    RAISE EXCEPTION 'Union wallet not found for union %', p_union_id;
  END IF;
  IF v_union_balance < p_amount THEN
    RAISE EXCEPTION 'Insufficient union chip balance. Available: %, Requested: %',
      v_union_balance, p_amount;
  END IF;

  -- 3. Find club owner
  SELECT user_id INTO v_owner_user_id
    FROM public.club_members WHERE club_id = p_club_id AND role = 'owner' LIMIT 1;
  IF v_owner_user_id IS NULL THEN
    RAISE EXCEPTION 'Club owner not found for club %', p_club_id;
  END IF;

  -- 4. Atomic: debit union wallet
  UPDATE public.union_wallets
    SET chip_balance = chip_balance - p_amount, updated_at = NOW()
    WHERE union_id = p_union_id;

  -- 5. Atomic: credit club owner's chip balance
  UPDATE public.club_members
    SET chip_balance = COALESCE(chip_balance, 0) + p_amount
    WHERE club_id = p_club_id AND role = 'owner';

  -- 6. Atomic: log audit row in CORRECT table (BUG 011 FIX - was union_transactions)
  INSERT INTO public.union_wallet_transactions (
    union_id, wallet, direction, amount, balance_after, tx_type, club_id, notes
  ) VALUES (
    p_union_id, 'main', 'debit', p_amount, v_union_balance - p_amount, 'send_to_club',
    p_club_id, COALESCE(p_notes, 'Union chip distribution')
  );

  RETURN TRUE;
END;
$$;


ALTER FUNCTION public.fn_union_send_chips_to_club(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text) OWNER TO postgres;

--
-- Name: FUNCTION fn_union_send_chips_to_club(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_send_chips_to_club(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text) IS 'BUG 011 FIX 2026-04-15 — replaced INSERT INTO union_transactions (non-existent) with correct INSERT INTO union_wallet_transactions. Every prior call raised 42P01.';


--
-- Name: fn_union_send_club_message(uuid, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_send_club_message(p_union_id uuid, p_club_id uuid, p_content text, p_metadata jsonb DEFAULT '{}'::jsonb, p_message_type text DEFAULT 'text'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sender      uuid;
  v_union_name  text;
  v_union_page  uuid;
  v_club_page   uuid;
  v_conv        uuid;
  v_title       text;
  v_msg_id      uuid;
  v_recipients  int := 0;
  r             record;
BEGIN
  SELECT u.owner_id, u.name INTO v_sender, v_union_name
    FROM unions u WHERE u.id = p_union_id;
  IF v_sender IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'union has no owner to send as');
  END IF;

  SELECT sp.id INTO v_union_page FROM social_pages sp
   WHERE sp.linked_entity_id = p_union_id::text AND sp.linked_entity_type = 'club' LIMIT 1;
  SELECT sp.id INTO v_club_page FROM social_pages sp
   WHERE sp.linked_entity_id = p_club_id::text AND sp.linked_entity_type = 'club' LIMIT 1;

  v_title := COALESCE(v_union_name, 'Union') || ' Statements';

  SELECT c.id INTO v_conv
    FROM social_conversations c
   WHERE c.is_group = true
     AND c.group_name = v_title
     AND c.context_entity_id IS NOT DISTINCT FROM v_club_page
   ORDER BY c.created_at ASC
   LIMIT 1;

  IF v_conv IS NULL THEN
    INSERT INTO social_conversations (is_group, group_name, context_entity_id, context_entity_type)
    VALUES (true, v_title, v_club_page, CASE WHEN v_club_page IS NULL THEN NULL ELSE 'club' END)
    RETURNING id INTO v_conv;
  END IF;

  -- RECIPIENTS FIRST, seated under the CLUB identity.
  FOR r IN
    SELECT DISTINCT x.uid
      FROM (
        SELECT c.owner_id AS uid FROM clubs c
         WHERE c.id = p_club_id AND c.owner_id IS NOT NULL
        UNION
        SELECT cm.user_id FROM club_members cm
         WHERE cm.club_id = p_club_id
           AND cm.role IN ('owner','co_owner','admin')
           AND COALESCE(cm.status,'active') NOT IN ('banned','suspended')
      ) x
     WHERE x.uid IS NOT NULL
       AND EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = x.uid)
  LOOP
    INSERT INTO social_conversation_participants
      (conversation_id, user_id, context_entity_id, context_entity_type)
    VALUES (v_conv, r.uid, v_club_page,
            CASE WHEN v_club_page IS NULL THEN NULL ELSE 'club' END)
    ON CONFLICT (conversation_id, user_id) DO NOTHING;
    v_recipients := v_recipients + 1;
  END LOOP;

  IF v_recipients = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'club has no owner or admin with a profile',
                              'conversation_id', v_conv);
  END IF;

  -- The union owner joins under the UNION identity only if they are not
  -- already seated as a club recipient (one row per user is enforced).
  INSERT INTO social_conversation_participants
    (conversation_id, user_id, context_entity_id, context_entity_type)
  VALUES (v_conv, v_sender, v_union_page,
          CASE WHEN v_union_page IS NULL THEN NULL ELSE 'club' END)
  ON CONFLICT (conversation_id, user_id) DO NOTHING;

  INSERT INTO social_messages (conversation_id, sender_id, content, message_type, media_metadata)
  VALUES (v_conv, v_sender, p_content,
          COALESCE(NULLIF(p_message_type, ''), 'text'),
          CASE WHEN p_metadata = '{}'::jsonb OR p_metadata IS NULL THEN NULL ELSE p_metadata END)
  RETURNING id INTO v_msg_id;

  UPDATE social_conversations
     SET last_message_at = now(),
         last_message_preview = left(regexp_replace(p_content, E'\\s+', ' ', 'g'), 100),
         updated_at = now()
   WHERE id = v_conv;

  RETURN jsonb_build_object('success', true, 'delivered', v_recipients,
                            'conversation_id', v_conv, 'message_id', v_msg_id,
                            'club_page', v_club_page, 'union_page', v_union_page);
END;
$$;


ALTER FUNCTION public.fn_union_send_club_message(p_union_id uuid, p_club_id uuid, p_content text, p_metadata jsonb, p_message_type text) OWNER TO postgres;

--
-- Name: fn_union_send_to_club_atomic(uuid, uuid, numeric, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_send_to_club_atomic(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_balance numeric;
  v_after numeric;
  v_op uuid := COALESCE(p_op_id, gen_random_uuid());
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM union_clubs uc WHERE uc.union_id = p_union_id AND uc.club_id = p_club_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'club is not in this union');
  END IF;

  SELECT chip_balance INTO v_balance FROM union_wallets
   WHERE union_id = p_union_id FOR UPDATE;
  IF v_balance IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'union wallet not found');
  END IF;
  IF v_balance < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient union balance',
                              'balance', v_balance, 'requested', p_amount);
  END IF;

  -- CHIP STANDARD (2026-09-05): the Club Bank route declares itself. ONE
  -- journal row, union_bank -> club_treasury, keyed on the operation. Until
  -- today both halves of this send landed in settlement_suspense as two
  -- unrelated adjustments, which is how the 02:51 UTC sends were found.
  PERFORM public.fn_ca_declare_ledger('union_send', 'union_bank', p_union_id, NULL,
    'union_send_to_club:' || v_op::text, ARRAY['union_wallets']);
  PERFORM set_config('app.ledger_correlation', v_op::text, true);

  UPDATE union_wallets
     SET chip_balance = chip_balance - p_amount, updated_at = NOW()
   WHERE union_id = p_union_id
   RETURNING chip_balance INTO v_after;

  UPDATE clubs SET chip_treasury = COALESCE(chip_treasury, 0) + p_amount
   WHERE id = p_club_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'club % not found', p_club_id;
  END IF;
  PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);

  INSERT INTO union_wallet_transactions (
    union_id, wallet, direction, amount, balance_after, tx_type, club_id, period_id, notes, created_by
  ) VALUES (
    p_union_id, 'chip_balance', 'debit', p_amount, v_after, 'manual_transfer',
    p_club_id, p_op_id, COALESCE(NULLIF(p_notes, ''), 'Union transfer to club'), p_created_by
  );
  INSERT INTO chip_transactions (club_id, amount, transaction_type, notes)
  VALUES (p_club_id, p_amount, 'union_transfer',
          COALESCE(NULLIF(p_notes, ''), 'Union chip distribution'));

  RETURN jsonb_build_object('success', true, 'amount', p_amount, 'union_balance_after', v_after);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('success', false, 'duplicate', true,
                            'error', 'operation already processed');
END;
$$;


ALTER FUNCTION public.fn_union_send_to_club_atomic(p_union_id uuid, p_club_id uuid, p_amount numeric, p_notes text, p_created_by uuid, p_op_id uuid) OWNER TO postgres;

--
-- Name: fn_union_send_to_member(uuid, uuid, text, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_send_to_member(p_union_id uuid, p_target_user_id uuid, p_kind text, p_amount numeric, p_source_wallet text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_op_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_prior jsonb;
  v_res jsonb;
begin
  /* ZERO-DRIFT phase 3/5: durable op-id claim with actor audit (see
     ca_op_claims). Authorization itself lives in the core. */
  if p_op_id is null then
    return public.fn_union_send_to_member_zd3core(
      p_union_id, p_target_user_id, p_kind, p_amount, p_source_wallet, p_note);
  end if;

  select result into v_prior
    from public.ca_op_claims
   where op_id = p_op_id and fn_name = 'fn_union_send_to_member';
  if found and v_prior is not null then
    return v_prior || jsonb_build_object('replayed', true, 'op_id', p_op_id);
  elsif found then
    delete from public.ca_op_claims
     where op_id = p_op_id and fn_name = 'fn_union_send_to_member';
  end if;

  insert into public.ca_op_claims (op_id, fn_name, claimed_by)
  values (p_op_id, 'fn_union_send_to_member', v_actor);

  v_res := public.fn_union_send_to_member_zd3core(
    p_union_id, p_target_user_id, p_kind, p_amount, p_source_wallet, p_note);

  if coalesce(v_res->>'success', '') = 'true' then
    update public.ca_op_claims
       set result = v_res, finalized_at = now()
     where op_id = p_op_id and fn_name = 'fn_union_send_to_member';
  else
    delete from public.ca_op_claims
     where op_id = p_op_id and fn_name = 'fn_union_send_to_member';
  end if;

  return v_res;
end $$;


ALTER FUNCTION public.fn_union_send_to_member(p_union_id uuid, p_target_user_id uuid, p_kind text, p_amount numeric, p_source_wallet text, p_note text, p_op_id text) OWNER TO postgres;

--
-- Name: fn_union_send_to_member_zd3core(uuid, uuid, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_send_to_member_zd3core(p_union_id uuid, p_target_user_id uuid, p_kind text, p_amount numeric, p_source_wallet text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor      uuid := auth.uid();
  v_source     text;
  v_after      numeric;
  v_dia_after  numeric;
  v_club       uuid;
  v_role       text;
  v_is_club    boolean;
  v_agent_row  uuid;
  v_to_after   numeric;
  v_dest       text;
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    if not public.fn_union_can_manage_wallets(p_union_id, v_actor) then
      return jsonb_build_object('success', false, 'error', 'Only the union owner, co-owner or an admin can send from union wallets.');
    end if;
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'amount must be > 0');
  end if;
  if p_amount <> round(p_amount, 2) then
    return jsonb_build_object('success', false, 'error', 'chips move in hundredths at most');
  end if;
  -- 2026-09-07 (Diamond Accounting Standard DR2, ruling): a union send of diamonds credited a player with
  -- no debit anywhere - a mint of up to 100,000 per call outside the Mint. Diamonds are issued only by
  -- fn_ca_mint. The diamonds branch below is unreachable and kept only as history.
  if p_kind not in ('chips','promo') then
    return jsonb_build_object('success', false, 'error', 'kind must be chips or promo. Diamonds are issued only by the Mint (Diamond Accounting Standard DR2).');
  end if;

  /* ZERO-DRIFT round 2 (2026-08-31): duplicate-send suppression. An identical
     union send (union, recipient, kind, amount, actor) inside 20 seconds is a
     retry, not a second intent. */
  if p_kind in ('chips','promo') and exists (
      select 1 from union_wallet_transactions t
       where t.union_id = p_union_id
         and t.direction = 'debit'
         and t.amount = p_amount
         and t.tx_type in ('member_send','promo_member_send')
         and t.created_by is not distinct from v_actor
         and t.created_at > now() - interval '20 seconds') then
    return jsonb_build_object('success', true, 'duplicate_suppressed', true,
      'note', 'an identical send was recorded seconds ago; nothing moved twice');
  end if;

  select cm.club_id into v_club
    from club_members cm
   where cm.user_id = p_target_user_id
     and coalesce(cm.status, 'active') in ('active','approved')
     and cm.club_id = public.fn_player_home_club(p_target_user_id, null)
     and cm.club_id in (select uc.club_id from union_clubs uc where uc.union_id = p_union_id)
   limit 1;
  if v_club is null then
    select cm.club_id into v_club
      from club_members cm
     where cm.user_id = p_target_user_id
       and coalesce(cm.status, 'active') in ('active','approved')
       and cm.club_id in (select uc.club_id from union_clubs uc where uc.union_id = p_union_id)
     order by coalesce(cm.chip_balance, 0) desc, cm.club_id
     limit 1;
  end if;
  if v_club is null then
    select cm.club_id into v_club
      from club_members cm
     where cm.user_id = p_target_user_id
       and coalesce(cm.status, 'active') in ('active','approved')
       and cm.club_id = p_union_id
     limit 1;
  end if;
  if v_club is null then
    return jsonb_build_object('success', false, 'error', 'That player is not a member of this union.');
  end if;
  v_is_club := exists (select 1 from clubs c where c.id = v_club);
  select cm.role into v_role from club_members cm
   where cm.club_id = v_club and cm.user_id = p_target_user_id
     and coalesce(cm.status, 'active') in ('active','approved')
   limit 1;

  if p_kind = 'diamonds' then
    if p_amount <> floor(p_amount) then
      return jsonb_build_object('success', false, 'error', 'diamonds must be a whole number');
    end if;
    if p_amount > 100000 then
      return jsonb_build_object('success', false, 'error', 'maximum 100,000 diamonds per send');
    end if;
    /* DR2, LOG-ONLY (2026-09-03). This credit has no debit: no union diamond wallet is
       decremented, nothing is drawn from the Mint, and no budget is consumed. It creates
       diamonds out of nothing, up to 100,000 per call. It is RECORDED and allowed to
       proceed; refusing a live grant is Dan's call (decision 6.6, fund it or remove it). */
    perform public.fn_ca_diamond_incident(
      'DR2:union_diamond_grant_unfunded', 'warning', p_target_user_id, p_amount,
      'fn_union_send_to_member_zd3core',
      jsonb_build_object('union_id', p_union_id,
                         'source_wallet', p_source_wallet,
                         'club_id', v_club,
                         'actor', v_actor,
                         'note', 'diamonds credited with no debit on any wallet and no mint row; unfunded issuance'));
    update profiles set diamonds = coalesce(diamonds, 0) + p_amount
     where id = p_target_user_id
    returning diamonds into v_dia_after;
    if v_dia_after is null then
      return jsonb_build_object('success', false, 'error', 'player profile not found');
    end if;
    insert into diamond_transactions (user_id, type, amount, balance_after, description, transaction_type, source, metadata, counterparty, issuance_class)
    values (p_target_user_id, 'credit', p_amount, v_dia_after,
            coalesce(p_note, 'Union grant'), 'union_grant', 'union',
            jsonb_build_object('union_id', p_union_id, 'granted_by', v_actor),
            'union:' || p_union_id::text, 'promotional');
    return jsonb_build_object('success', true, 'kind', 'diamonds', 'balance_after', v_dia_after);
  end if;

  /* ZERO-DRIFT round 2: the recipient-side credit journals ONE clean ledger
     row (union_wallet -> player/agent wallet); the union-side debit is
     autoskipped because union_wallet_transactions already records it and a
     second ledger row would double-post the flow. */
  perform set_config('app.ledger_category',
                     case when p_kind = 'promo' then 'promo_send' else 'union_send' end, true);
  perform set_config('app.ledger_counterparty', 'union_wallet', true);
  perform set_config('app.ledger_counterparty_entity', p_union_id::text, true);
  perform set_config('app.ledger_autoskip_union_wallets', '1', true);

  if p_kind = 'promo' then
    update union_wallets
       set promo_wallet = promo_wallet - p_amount, updated_at = now()
     where union_id = p_union_id and coalesce(promo_wallet, 0) >= p_amount
    returning promo_wallet into v_after;
    if v_after is null then
      return jsonb_build_object('success', false, 'error', 'Insufficient promo wallet balance.');
    end if;

    if v_is_club and v_role in ('owner','co_owner','admin','super_agent','agent','sub_agent') then
      v_dest := 'promo_float';
      v_agent_row := public.fn_ensure_agent_row(v_club, p_target_user_id, v_role);
      if v_agent_row is null then
        raise exception 'could not ensure agents row for % in club %', p_target_user_id, v_club;
      end if;
      update agents
         set promo_wallet_balance = coalesce(promo_wallet_balance, 0) + p_amount,
             updated_at = now()
       where id = v_agent_row
       returning promo_wallet_balance into v_to_after;
    else
      v_dest := 'player_wallet';
      update club_members
         set chip_balance = coalesce(chip_balance, 0) + p_amount,
             updated_at = now()
       where club_id = v_club and user_id = p_target_user_id
       returning chip_balance into v_to_after;
    end if;
    if v_to_after is null then
      raise exception 'union promo credit landed nowhere for % in %', p_target_user_id, v_club;
    end if;

    insert into union_wallet_transactions
      (union_id, club_id, wallet, direction, amount, balance_after, tx_type, notes, created_by)
    values
      (p_union_id, case when v_is_club then v_club else null end,
       'promo_wallet', 'debit', p_amount, v_after, 'promo_member_send',
       coalesce(p_note, 'Union promo to member'), v_actor);
    if v_is_club then
      insert into chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after,
                                     metadata)
      values (v_club, v_actor, p_target_user_id, p_amount, 'union_promo_send',
              coalesce(p_note, 'Union promo to member'), v_to_after,
              jsonb_build_object('union_id', p_union_id, 'destination', v_dest));
    end if;
    return jsonb_build_object('success', true, 'kind', 'promo', 'wallet_after', v_after,
                              'destination', v_dest, 'recipient_balance_after', v_to_after);
  end if;

  v_source := coalesce(p_source_wallet, 'chips');
  if v_source not in ('chips','rake','promo') then
    return jsonb_build_object('success', false, 'error', 'source wallet must be chips, rake or promo');
  end if;

  if v_source = 'chips' then
    update union_wallets set chip_balance = chip_balance - p_amount, updated_at = now()
     where union_id = p_union_id and coalesce(chip_balance, 0) >= p_amount
    returning chip_balance into v_after;
  elsif v_source = 'rake' then
    update union_wallets set rake_wallet = rake_wallet - p_amount, updated_at = now()
     where union_id = p_union_id and coalesce(rake_wallet, 0) >= p_amount
    returning rake_wallet into v_after;
  else
    update union_wallets set promo_wallet = promo_wallet - p_amount, updated_at = now()
     where union_id = p_union_id and coalesce(promo_wallet, 0) >= p_amount
    returning promo_wallet into v_after;
  end if;

  if v_after is null then
    return jsonb_build_object('success', false, 'error', 'Insufficient balance in the selected union wallet.');
  end if;

  if v_is_club and v_role in ('owner','co_owner','admin','super_agent','agent','sub_agent') then
    v_dest := 'agent_wallet';
    v_agent_row := public.fn_ensure_agent_row(v_club, p_target_user_id, v_role);
    if v_agent_row is null then
      raise exception 'could not ensure agents row for % in club %', p_target_user_id, v_club;
    end if;
    update agents
       set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + p_amount,
           updated_at = now()
     where id = v_agent_row
     returning agent_wallet_balance into v_to_after;
  else
    v_dest := 'player_wallet';
    update club_members
       set chip_balance = coalesce(chip_balance, 0) + p_amount,
           updated_at = now()
     where club_id = v_club and user_id = p_target_user_id
     returning chip_balance into v_to_after;
  end if;
  if v_to_after is null then
    raise exception 'union chip credit landed nowhere for % in %', p_target_user_id, v_club;
  end if;

  insert into union_wallet_transactions
    (union_id, club_id, wallet, direction, amount, balance_after, tx_type, notes, created_by)
  values
    (p_union_id, case when v_is_club then v_club else null end,
     case v_source when 'chips' then 'chip_balance' when 'rake' then 'rake_wallet' else 'promo_wallet' end,
     'debit', p_amount, v_after, 'member_send',
     coalesce(p_note, 'Union chips to member (' || v_source || ' wallet)'), v_actor);
  if v_is_club then
    insert into chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after,
                                   metadata)
    values (v_club, v_actor, p_target_user_id, p_amount, 'union_member_send',
            coalesce(p_note, 'Union chips to member (' || v_source || ' wallet)'), v_to_after,
            jsonb_build_object('union_id', p_union_id, 'source_wallet', v_source, 'destination', v_dest));
  end if;

  return jsonb_build_object('success', true, 'kind', 'chips', 'source', v_source,
                            'wallet_after', v_after,
                            'destination', v_dest, 'recipient_balance_after', v_to_after);
end $$;


ALTER FUNCTION public.fn_union_send_to_member_zd3core(p_union_id uuid, p_target_user_id uuid, p_kind text, p_amount numeric, p_source_wallet text, p_note text) OWNER TO postgres;

--
-- Name: fn_union_setting(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_setting(p_union_id uuid, p_key text, p_default numeric) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((settings ->> p_key)::numeric, p_default)
    FROM unions WHERE id = p_union_id;
$$;


ALTER FUNCTION public.fn_union_setting(p_union_id uuid, p_key text, p_default numeric) OWNER TO postgres;

--
-- Name: fn_union_settle_player_pnl(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_settle_player_pnl(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_settlement_id uuid; v_prev jsonb; r record;
  v_results jsonb := '[]'::jsonb;
  v_collect_total numeric := 0; v_pay_total numeric := 0; v_unpaid_total numeric := 0;
  v_treasury numeric; v_take numeric; v_union_balance numeric; v_pay numeric; v_owed numeric;
  v_period_id uuid; v_scale numeric := 1; v_winners_total numeric := 0; v_residual numeric := 0;
  v_ca_id uuid; v_ca_state text; v_walk boolean := false;
  v_expected_balance numeric; v_err text;
BEGIN
  IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'missing_arguments');
  END IF;
  IF p_end <= p_start THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_period');
  END IF;

  -- (A) FIX: baseline at the OPENING of the window.
  v_prev := fn_union_pnl_baseline(p_union_id, p_start);

  CREATE TEMP TABLE IF NOT EXISTS _pnl_tmp (
    club_id uuid, net numeric, seated numeric, detail jsonb) ON COMMIT DROP;
  DELETE FROM _pnl_tmp;

  INSERT INTO _pnl_tmp (club_id, net, seated, detail)
  SELECT c.club_id,
         round(c.realized_net + (c.seated_stack - base.seated_start) + COALESCE(rk.rake_paid, 0), 2),
         c.seated_stack,
         jsonb_build_object(
           'club_id', c.club_id, 'buyins', c.buyins, 'cashouts', c.cashouts,
           'realized_net', c.realized_net, 'winnings', c.winnings, 'losses', c.losses,
           'players', c.players,
           'seated_start', base.seated_start, 'seated_end', c.seated_stack,
           'seated_end_cash', COALESCE(cc.seated_stack, 0),
           'stack_delta', round(c.seated_stack - base.seated_start, 2),
           'rake_paid', COALESCE(rk.rake_paid, 0),
           'net', round(c.realized_net + (c.seated_stack - base.seated_start) + COALESCE(rk.rake_paid, 0), 2))
    FROM fn_union_pnl_all_clubs(p_union_id, p_start, p_end, true) c
    -- (B) same population as the P&L above: horses included.
    LEFT JOIN fn_union_rake_paid_by_club(p_union_id, p_start, p_end, true) rk ON rk.club_id = c.club_id
    LEFT JOIN fn_union_pnl_cash_by_club(p_union_id, p_start, p_end, true) cc ON cc.club_id = c.club_id
    CROSS JOIN LATERAL (
      SELECT COALESCE(
        (SELECT (e->>'seated_end')::numeric FROM jsonb_array_elements(COALESCE(v_prev,'[]'::jsonb)) e
          WHERE (e->>'club_id') = c.club_id::text LIMIT 1),
        c.seated_stack) AS seated_start
    ) base;

  SELECT COALESCE(round(SUM(net), 2), 0) INTO v_residual FROM _pnl_tmp;

  IF p_dry_run THEN
    SELECT jsonb_agg(detail ORDER BY club_id) INTO v_results FROM _pnl_tmp;
    RETURN jsonb_build_object('success', true, 'dry_run', true, 'union_id', p_union_id,
      'house_residual', v_residual, 'imbalance', v_residual,
      'clubs', COALESCE(v_results, '[]'::jsonb));
  END IF;

  UPDATE union_pnl_settlements SET status = 'superseded'
   WHERE union_id = p_union_id AND period_start = p_start AND status = 'needs_review';

  BEGIN
    INSERT INTO union_pnl_settlements (union_id, period_start, period_end, status)
    VALUES (p_union_id, p_start, p_end, 'in_progress') RETURNING id INTO v_settlement_id;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('success', true, 'already_settled', true,
                              'union_id', p_union_id, 'period_start', p_start);
  END;

  -- ZERO-DRIFT phase 3: register on the settlement state machine (resume a
  -- prior failed run; leave an unexpected 'final' row untouched).
  INSERT INTO public.ca_settlements (settlement_type, external_ref, state, union_id, idempotency_key)
  VALUES ('union_player_pnl', p_union_id::text || ':' || to_char(p_start, 'YYYY-MM-DD"T"HH24:MI:SSOF'),
          'open', p_union_id, 'pnl:' || p_union_id::text || ':' || extract(epoch from p_start)::bigint)
  ON CONFLICT (settlement_type, external_ref) DO NOTHING
  RETURNING id INTO v_ca_id;
  IF v_ca_id IS NULL THEN
    SELECT id, state INTO v_ca_id, v_ca_state FROM public.ca_settlements
     WHERE settlement_type = 'union_player_pnl'
       AND external_ref = p_union_id::text || ':' || to_char(p_start, 'YYYY-MM-DD"T"HH24:MI:SSOF');
    IF v_ca_state = 'failed' THEN
      UPDATE public.ca_settlements SET state = 'open', error_detail = NULL WHERE id = v_ca_id;
      v_walk := true;
    ELSIF v_ca_state = 'open' THEN
      v_walk := true;
    END IF; -- any later state: leave the machine alone, evidence stands
  ELSE
    v_walk := true;
  END IF;

  -- (C) FIX: every club in the settlement gets a period row for THIS window.
  INSERT INTO settlement_periods (club_id, union_id, period_number, year, start_at, end_at, status)
  SELECT t.club_id, p_union_id,
         EXTRACT(week FROM p_start)::int, EXTRACT(isoyear FROM p_start)::int,
         p_start, p_end, 'processing'
    FROM _pnl_tmp t
   WHERE NOT EXISTS (
     SELECT 1 FROM settlement_periods sp
      WHERE sp.club_id = t.club_id AND sp.union_id = p_union_id
        AND sp.start_at = p_start AND sp.end_at = p_end);

  -- ═══ GUARDED MONEY SECTION: any error rolls all chip movements back ═══
  BEGIN
    IF v_walk THEN
      UPDATE public.ca_settlements SET state = 'locked_for_calculation' WHERE id = v_ca_id;
      UPDATE public.ca_settlements SET state = 'calculated',
        totals = jsonb_build_object('house_residual', v_residual,
                                    'clubs', (SELECT count(*) FROM _pnl_tmp))
        WHERE id = v_ca_id;
    END IF;

    SELECT chip_balance INTO v_union_balance FROM union_wallets WHERE union_id = p_union_id FOR UPDATE;
    IF v_union_balance IS NULL THEN
      INSERT INTO union_wallets (union_id, chip_balance) VALUES (p_union_id, 0)
        ON CONFLICT (union_id) DO NOTHING;
      SELECT chip_balance INTO v_union_balance FROM union_wallets WHERE union_id = p_union_id FOR UPDATE;
      v_union_balance := COALESCE(v_union_balance, 0);
    END IF;

    -- ZERO-DRIFT phase 3 validation before any chips move.
    SELECT COALESCE(SUM(net), 0) INTO v_winners_total FROM _pnl_tmp WHERE net > 0;
    IF v_winners_total < 0 THEN
      RAISE EXCEPTION 'pnl validation: winners_total negative (%)', v_winners_total;
    END IF;
    IF v_walk THEN
      UPDATE public.ca_settlements SET state = 'validated' WHERE id = v_ca_id;
    END IF;

    -- ZERO-DRIFT phase 3: P&L legs journal as pnl_settlement vs the union
    -- wallet, single-posted from the club-treasury side.
    PERFORM set_config('app.ledger_category', 'pnl_settlement', true);
    PERFORM set_config('app.ledger_counterparty', 'union_wallet', true);
    PERFORM set_config('app.ledger_counterparty_entity', p_union_id::text, true);
    PERFORM set_config('app.ledger_settlement', COALESCE(v_ca_id::text, ''), true);
    PERFORM set_config('app.ledger_autoskip_union_wallets', '1', true);

    FOR r IN SELECT * FROM _pnl_tmp WHERE net < 0 ORDER BY club_id LOOP
      v_owed := round(-r.net, 2);
      SELECT chip_treasury INTO v_treasury FROM clubs WHERE id = r.club_id FOR UPDATE;
      v_take := LEAST(v_owed, GREATEST(COALESCE(v_treasury, 0), 0));
      IF v_take > v_owed OR v_take < 0 THEN
        RAISE EXCEPTION 'pnl validation: collect leg out of bounds (take % owed %)', v_take, v_owed;
      END IF;
      IF v_take > 0 THEN
        UPDATE clubs SET chip_treasury = chip_treasury - v_take WHERE id = r.club_id;
        v_union_balance := v_union_balance + v_take;
        UPDATE union_wallets SET chip_balance = v_union_balance WHERE union_id = p_union_id;
        v_collect_total := v_collect_total + v_take;
        INSERT INTO union_wallet_transactions (union_id, wallet, direction, amount, balance_after, tx_type, club_id, notes)
        VALUES (p_union_id, 'chip_balance', 'credit', v_take, v_union_balance, 'player_pnl_collect', r.club_id,
                'Weekly player P&L: collected from club (owed ' || v_owed || ')');
        INSERT INTO chip_transactions (club_id, amount, transaction_type, notes, metadata)
        VALUES (r.club_id, v_take, 'union_pnl_collect',
                'Weekly union player P&L settlement: club owed ' || v_owed,
                jsonb_build_object('union_id', p_union_id, 'settlement_id', v_settlement_id,
                                   'period_start', p_start, 'net', r.net));
      END IF;

      SELECT id INTO v_period_id FROM settlement_periods
        WHERE club_id = r.club_id AND union_id = p_union_id
          AND start_at = p_start AND end_at = p_end
        ORDER BY created_at DESC LIMIT 1;
      IF v_period_id IS NULL THEN
        RAISE EXCEPTION 'settlement period row missing for club % in window % .. %', r.club_id, p_start, p_end;
      END IF;
      INSERT INTO settlement_invoices (club_id, period_id, invoice_type, from_entity_type, from_entity_id,
        to_entity_type, to_entity_id, gross_amount, net_amount, deductions, breakdown, status,
        chips_transferred, transferred_at, notes)
      VALUES (r.club_id, v_period_id, 'union_club_pnl', 'club', r.club_id::text, 'union', p_union_id::text,
        v_owed, v_take, round(v_owed - v_take, 2),
        r.detail || jsonb_build_object('direction','club_owes_union','collected',v_take,
                                       'shortfall', round(v_owed - v_take, 2)),
        CASE WHEN v_take >= v_owed THEN 'paid' ELSE 'pending' END,
        v_take > 0, CASE WHEN v_take > 0 THEN now() ELSE NULL END,
        CASE WHEN v_take < v_owed THEN 'Partial: club treasury short by ' || round(v_owed - v_take, 2) ELSE NULL END);
      v_unpaid_total := v_unpaid_total + round(v_owed - v_take, 2);
    END LOOP;

    IF v_winners_total > 0 AND v_union_balance < v_winners_total THEN
      v_scale := GREATEST(v_union_balance, 0) / v_winners_total;
    END IF;
    IF v_scale < 0 OR v_scale > 1 THEN
      RAISE EXCEPTION 'pnl validation: pay scale out of bounds (%)', v_scale;
    END IF;

    FOR r IN SELECT * FROM _pnl_tmp WHERE net > 0 ORDER BY club_id LOOP
      v_owed := round(r.net, 2);
      v_pay := LEAST(round(v_owed * v_scale, 2), GREATEST(v_union_balance, 0));
      IF v_pay > v_owed OR v_pay < 0 THEN
        RAISE EXCEPTION 'pnl validation: pay leg out of bounds (pay % owed %)', v_pay, v_owed;
      END IF;
      IF v_pay > 0 THEN
        UPDATE clubs SET chip_treasury = COALESCE(chip_treasury, 0) + v_pay WHERE id = r.club_id;
        v_union_balance := v_union_balance - v_pay;
        UPDATE union_wallets SET chip_balance = v_union_balance WHERE union_id = p_union_id;
        v_pay_total := v_pay_total + v_pay;
        INSERT INTO union_wallet_transactions (union_id, wallet, direction, amount, balance_after, tx_type, club_id, notes)
        VALUES (p_union_id, 'chip_balance', 'debit', v_pay, v_union_balance, 'player_pnl_pay', r.club_id,
                'Weekly player P&L: paid to club (owed ' || v_owed || ')');
        INSERT INTO chip_transactions (club_id, amount, transaction_type, notes, metadata)
        VALUES (r.club_id, v_pay, 'union_pnl_payout',
                'Weekly union player P&L settlement: union owed ' || v_owed,
                jsonb_build_object('union_id', p_union_id, 'settlement_id', v_settlement_id,
                                   'period_start', p_start, 'net', r.net));
      END IF;

      SELECT id INTO v_period_id FROM settlement_periods
        WHERE club_id = r.club_id AND union_id = p_union_id
          AND start_at = p_start AND end_at = p_end
        ORDER BY created_at DESC LIMIT 1;
      IF v_period_id IS NULL THEN
        RAISE EXCEPTION 'settlement period row missing for club % in window % .. %', r.club_id, p_start, p_end;
      END IF;
      INSERT INTO settlement_invoices (club_id, period_id, invoice_type, from_entity_type, from_entity_id,
        to_entity_type, to_entity_id, gross_amount, net_amount, deductions, breakdown, status,
        chips_transferred, transferred_at, notes)
      VALUES (r.club_id, v_period_id, 'union_club_pnl', 'union', p_union_id::text, 'club', r.club_id::text,
        v_owed, v_pay, round(v_owed - v_pay, 2),
        r.detail || jsonb_build_object('direction','union_owes_club','paid',v_pay,
                                       'shortfall', round(v_owed - v_pay, 2)),
        CASE WHEN v_pay >= v_owed THEN 'paid' ELSE 'pending' END,
        v_pay > 0, CASE WHEN v_pay > 0 THEN now() ELSE NULL END,
        CASE WHEN v_pay < v_owed THEN 'Partial: union chip wallet short by ' || round(v_owed - v_pay, 2) ELSE NULL END);
      v_unpaid_total := v_unpaid_total + round(v_owed - v_pay, 2);
    END LOOP;

    PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);

    IF abs(v_residual) >= 0.01 THEN
      INSERT INTO union_wallet_transactions (union_id, wallet, direction, amount, balance_after, tx_type, notes)
      VALUES (p_union_id, 'chip_balance',
              CASE WHEN v_residual < 0 THEN 'credit' ELSE 'debit' END,
              abs(v_residual), v_union_balance, 'player_pnl_house_residual',
              'Net real-player vs house-horse flow for the period, absorbed by the union '
              || 'as clearing house (settlement ' || v_settlement_id || ')');
    END IF;

    IF v_walk THEN
      UPDATE public.ca_settlements SET state = 'ledger_posted' WHERE id = v_ca_id;
    END IF;

    UPDATE settlement_periods sp
       SET total_player_winnings = COALESCE((t.detail->>'winnings')::numeric, 0),
           total_player_losses   = COALESCE((t.detail->>'losses')::numeric, 0),
           seated_stack_snapshot = t.seated,
           status = 'settled',
           settled_at = now()
      FROM _pnl_tmp t
     WHERE sp.club_id = t.club_id AND sp.union_id = p_union_id
       AND sp.start_at = p_start AND sp.end_at = p_end;

    -- Post-commit verification: the wallet must hold exactly what the legs say.
    SELECT chip_balance INTO v_expected_balance FROM union_wallets WHERE union_id = p_union_id;
    IF round(COALESCE(v_expected_balance, 0), 2) <> round(v_union_balance, 2) THEN
      RAISE EXCEPTION 'pnl post-commit verify: wallet % but legs say %', v_expected_balance, v_union_balance;
    END IF;
    IF v_walk THEN
      UPDATE public.ca_settlements SET state = 'post_commit_verified' WHERE id = v_ca_id;
      UPDATE public.ca_settlements SET state = 'final',
        totals = COALESCE(totals, '{}'::jsonb) || jsonb_build_object(
          'collected', v_collect_total, 'paid', v_pay_total,
          'unpaid', v_unpaid_total, 'house_residual', v_residual)
        WHERE id = v_ca_id;
    END IF;

    SELECT jsonb_agg(detail ORDER BY club_id) INTO v_results FROM _pnl_tmp;
    UPDATE union_pnl_settlements
       SET status='settled', total_collected=v_collect_total, total_paid=v_pay_total,
           total_unpaid=v_unpaid_total, house_residual=v_residual,
           club_results=COALESCE(v_results,'[]'::jsonb), settled_at=now()
     WHERE id = v_settlement_id;

  EXCEPTION WHEN OTHERS THEN
    -- Every chip movement above is rolled back to the block savepoint here.
    v_err := SQLERRM;
    UPDATE union_pnl_settlements SET status = 'failed' WHERE id = v_settlement_id;
    UPDATE public.ca_settlements SET state = 'failed', error_detail = left(v_err, 2000)
     WHERE id = v_ca_id;
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_union_settle_player_pnl', 'settlement_error', 'critical',
      'pnl-settle-failed:' || p_union_id::text || ':' || extract(epoch from p_start)::bigint,
      0, NULL, NULL, 'settlement', 'union_pnl_settlements',
      v_settlement_id, NULL, p_union_id, NULL, NULL, NULL, v_ca_id::text, NULL, NULL,
      'Weekly player P&L settlement failed and was fully rolled back (no chips moved): ' || left(v_err, 300)
        || ' - fix the cause and re-run; the failed claim does not block a retry',
      false, jsonb_build_object('period_start', p_start, 'period_end', p_end, 'error', left(v_err, 500)));
    RETURN jsonb_build_object('success', false, 'error', v_err, 'rolled_back', true,
      'settlement_id', v_settlement_id, 'union_id', p_union_id, 'period_start', p_start);
  END;

  RETURN jsonb_build_object('success', true, 'settlement_id', v_settlement_id, 'union_id', p_union_id,
    'period_start', p_start, 'period_end', p_end, 'house_residual', v_residual,
    'total_collected', v_collect_total, 'total_paid', v_pay_total, 'total_unpaid', v_unpaid_total,
    'union_balance_after', v_union_balance, 'clubs', COALESCE(v_results, '[]'::jsonb));
END $$;


ALTER FUNCTION public.fn_union_settle_player_pnl(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_dry_run boolean) OWNER TO postgres;

--
-- Name: fn_union_settle_player_pnl_guarded(uuid, timestamp with time zone, timestamp with time zone, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_settle_player_pnl_guarded(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_tolerance numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_preview jsonb; v_bad int := 0; v_detail jsonb; v_id uuid;
  v_residual numeric; v_turnover numeric; v_tol numeric;
BEGIN
  v_preview := fn_union_settle_player_pnl(p_union_id, p_start, p_end, true);
  IF NOT COALESCE((v_preview->>'success')::boolean, false) THEN
    RETURN v_preview;
  END IF;

  SELECT count(*), jsonb_agg(e) INTO v_bad, v_detail
    FROM jsonb_array_elements(v_preview->'clubs') e
   WHERE abs(COALESCE((e->>'net')::numeric, 0)) > 1
     AND COALESCE((e->>'buyins')::numeric, 0) = 0
     AND COALESCE((e->>'cashouts')::numeric, 0) = 0
     AND COALESCE((e->>'stack_delta')::numeric, 0) = 0;

  IF v_bad > 0 THEN
    INSERT INTO union_pnl_settlements (union_id, period_start, period_end, status,
                                       total_collected, total_paid, total_unpaid, club_results)
    VALUES (p_union_id, p_start, p_end, 'needs_review', 0, 0, 0,
            COALESCE(v_preview->'clubs', '[]'::jsonb))
    ON CONFLICT DO NOTHING RETURNING id INTO v_id;
    RETURN jsonb_build_object('success', false, 'needs_review', true,
      'reason', 'net_without_activity', 'clubs_affected', v_bad, 'settlement_id', v_id,
      'message', 'One or more clubs show a balance owed with no buy-ins, cash-outs or '
                 || 'stack movement behind it. The inputs are wrong, so no chips were moved.',
      'detail', v_detail);
  END IF;

  v_residual := COALESCE((v_preview->>'house_residual')::numeric, 0);
  SELECT COALESCE(SUM(COALESCE((e->>'buyins')::numeric,0)
                    + COALESCE((e->>'cashouts')::numeric,0)), 0)
    INTO v_turnover FROM jsonb_array_elements(v_preview->'clubs') e;
  v_tol := COALESCE(p_tolerance, GREATEST(100, round(v_turnover * 0.01, 2)));

  IF abs(v_residual) > v_tol THEN
    INSERT INTO union_pnl_settlements (union_id, period_start, period_end, status,
                                       total_collected, total_paid, total_unpaid, club_results)
    VALUES (p_union_id, p_start, p_end, 'needs_review', 0, 0, 0,
            COALESCE(v_preview->'clubs', '[]'::jsonb))
    ON CONFLICT DO NOTHING RETURNING id INTO v_id;
    RETURN jsonb_build_object('success', false, 'needs_review', true,
      'reason', 'does_not_reconcile', 'residual', v_residual, 'tolerance', v_tol,
      'turnover', v_turnover, 'settlement_id', v_id,
      'message', 'Club win/loss did not net out across the union, so the basis is not '
                 || 'trustworthy and NO chips were moved. Weekly 90% rakeback is unaffected '
                 || 'and pays normally - it is computed from rake contributions, not from '
                 || 'this identity.');
  END IF;

  RETURN fn_union_settle_player_pnl(p_union_id, p_start, p_end, false);
END $$;


ALTER FUNCTION public.fn_union_settle_player_pnl_guarded(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_tolerance numeric) OWNER TO postgres;

--
-- Name: fn_union_settle_player_pnl_weekly(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_settle_player_pnl_weekly(p_union_id uuid, p_min_hours numeric DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_start timestamptz; v_end timestamptz := now();
BEGIN
  SELECT period_end INTO v_start
    FROM union_pnl_settlements
   WHERE union_id = p_union_id AND status IN ('settled','baseline')
   ORDER BY period_start DESC LIMIT 1;

  IF v_start IS NULL THEN v_start := v_end - interval '7 days'; END IF;

  IF EXTRACT(EPOCH FROM (v_end - v_start)) / 3600.0 < p_min_hours THEN
    RETURN jsonb_build_object('success', true, 'skipped', true,
      'reason', 'period_too_short',
      'hours', round((EXTRACT(EPOCH FROM (v_end - v_start)) / 3600.0)::numeric, 2),
      'period_start', v_start, 'period_end', v_end);
  END IF;

  RETURN fn_union_settle_player_pnl_guarded(p_union_id, v_start, v_end);
END $$;


ALTER FUNCTION public.fn_union_settle_player_pnl_weekly(p_union_id uuid, p_min_hours numeric) OWNER TO postgres;

--
-- Name: fn_union_settlement_cascade(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_settlement_cascade(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid, p_period_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from timestamptz := COALESCE(p_period_start, public.fn_union_prev_week_start(now()));
  v_to   timestamptz := COALESCE(p_period_end,   public.fn_union_week_start(now()));
  v_r1 jsonb; v_r2 jsonb; v_r3 jsonb; v_eco jsonb; v_inv jsonb;
  v_floor timestamptz;
  v_sqlstate text; v_msg text; v_detail text; v_context text;

BEGIN
  IF EXISTS (SELECT 1 FROM settlement_locks WHERE lock_type = 'GLOBAL_SETTLEMENT_FREEZE' AND is_active = true) THEN
    RAISE EXCEPTION 'EMERGENCY_PROFIT_DRIFT_LOCK';
  END IF;

  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_union_overseer(p_union_id, auth.uid()))) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  -- THE FLOOR, checked before anything moves. Round 1 has always honoured it;
  -- nothing above round 1 did, so three further rounds ran on a floored week.
  SELECT f.earliest_period_start INTO v_floor
    FROM union_settlement_floor f WHERE f.union_id = p_union_id;

  IF v_floor IS NOT NULL AND v_from < v_floor THEN
    RETURN jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'before_settlement_floor',
      'period_start', v_from, 'period_end', v_to,
      'settlement_floor', v_floor,
      'note', 'This period is below the union settlement floor and must not be '
              || 'settled. No round was run.');
  END IF;

  -- ROUND 1 - union rake treasury pays the clubs their 90%.
  v_r1 := public.fn_union_weekly_rakeback_close(p_union_id, v_from, v_to);
  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payers, payees, amount, detail)
  VALUES (p_union_id, v_from, v_to, 1, 'union_to_clubs', 1,
          COALESCE((v_r1->>'clubs_paid')::int,0),
          COALESCE((v_r1->>'total_rakeback')::numeric,0), v_r1)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO NOTHING;

  IF COALESCE((v_r1->>'success')::boolean, false) IS NOT TRUE
     AND COALESCE(v_r1->>'error','') <> 'already_executed' THEN
    RETURN jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round1_failed: ' || COALESCE(v_r1->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1,
      'note', 'Rounds 2, 3 and 4 were not run. A club is not asked to pay its '
              || 'agents out of a treasury the union has not funded.');
  END IF;

  -- ROUND 2 - clubs pay their super agents and agents.
  v_r2 := public.fn_settle_round2_club_to_agents(p_union_id, v_from, v_to);
  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payees, amount, shortfalls, detail)
  VALUES (p_union_id, v_from, v_to, 2, 'club_to_agents',
          COALESCE((v_r2->>'payees')::int,0), COALESCE((v_r2->>'amount')::numeric,0),
          COALESCE((v_r2->>'shortfalls')::int,0), v_r2)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO UPDATE
    SET detail=union_settlement_rounds.detail || jsonb_build_object('latest_attempt',EXCLUDED.detail);

  -- Round 2 carries no 'success' key: it raises on error and returns
  -- {round,name,payees,amount,shortfalls,detail} otherwise, so a test for
  -- 'success' would be unreachable. Assert the CONTRACT instead - a round that
  -- stops reporting an amount must stop the cascade, not record 0 and carry on.
  IF (v_r2->>'amount') IS NULL OR (v_r2->>'payees') IS NULL
     OR (v_r2->>'shortfalls') IS NULL
     OR jsonb_typeof(v_r2->'shortfalls') IS DISTINCT FROM 'number'
     OR (v_r2 ? 'success' AND COALESCE((v_r2->>'success')::boolean, true) IS FALSE
         AND COALESCE(v_r2->>'error','') <> 'already_executed') THEN
    RETURN jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round2_contract_violated_or_failed: ' || COALESCE(v_r2->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
      'note', 'Rounds 3 and 4 were not run.');
  END IF;

  -- ROUND 3 - agents pay their players.
  v_r3 := public.fn_settle_round3_agents_to_players(p_union_id, v_from, v_to);
  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payees, amount, shortfalls, detail)
  VALUES (p_union_id, v_from, v_to, 3, 'agents_to_players',
          COALESCE((v_r3->>'payees')::int,0), COALESCE((v_r3->>'amount')::numeric,0),
          COALESCE((v_r3->>'shortfalls')::int,0), v_r3)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO UPDATE
    SET detail=union_settlement_rounds.detail || jsonb_build_object('latest_attempt',EXCLUDED.detail);

  -- Same contract assertion for round 3.
  IF (v_r3->>'amount') IS NULL OR (v_r3->>'payees') IS NULL
     OR (v_r3->>'shortfalls') IS NULL
     OR jsonb_typeof(v_r3->'shortfalls') IS DISTINCT FROM 'number'
     OR (v_r3 ? 'success' AND COALESCE((v_r3->>'success')::boolean, true) IS FALSE
         AND COALESCE(v_r3->>'error','') <> 'already_executed') THEN
    RETURN jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round3_contract_violated_or_failed: ' || COALESCE(v_r3->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
      'round3_agents_to_players', v_r3,
      'note', 'Round 4 was not run; no statement is issued for a settlement '
              || 'that did not complete.');
  END IF;

  -- A round can post funded recipients while reporting others still unpaid.
  -- Keep that durable progress, but do not mark the period settled or issue
  -- completion statements until every reported shortfall is zero.
  IF (v_r2->>'shortfalls')::numeric <> 0
     OR (v_r3->>'shortfalls')::numeric <> 0 THEN
    RETURN jsonb_build_object('success',false,'union_id',p_union_id,
      'error','recipient_shortfalls_remaining','period_start',v_from,'period_end',v_to,
      'round1_union_to_clubs',v_r1,'round2_club_to_agents',v_r2,
      'round3_agents_to_players',v_r3);
  END IF;

  -- CONSERVATION, asserted before anything else is written. Raises on a
  -- breach, which rolls this union's whole settlement back.
  PERFORM public.fn_union_settlement_conservation_assert(
            p_union_id, v_from, v_to, v_r1, v_r2, v_r3);

  -- The period is an accounting object, not a by-product of invoicing.
  PERFORM public.fn_union_mark_period_settled(p_union_id, v_from, v_to);

  IF public.fn_union_eco_enabled(p_union_id) THEN
    BEGIN
      v_eco := public.fn_union_eco_record(p_union_id, v_from, v_to, NULL);
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT,
                              v_detail = PG_EXCEPTION_DETAIL, v_context = PG_EXCEPTION_CONTEXT;
      v_eco := jsonb_build_object('success', false, 'error', v_msg, 'sqlstate', v_sqlstate,
                                  'exception_detail', v_detail, 'exception_context', v_context);
    END;
  ELSE
    v_eco := jsonb_build_object('skipped', true, 'reason', 'eco_disabled');
  END IF;

  IF public.fn_union_setting(p_union_id, 'weekly_invoices_enabled', 1) <> 1 THEN
    v_inv := jsonb_build_object(
      'success', true, 'skipped', true, 'invoices', 0,
      'reason', 'weekly_invoices_disabled: the union setting weekly_invoices_enabled is 0. '
                || 'Since Phase 6 (20260907) the statement reads the same fn_union_club_rake_basis '
                || 'rows round 1 pays on; switching statements back on is a setting, not a fix.');
  ELSE
    BEGIN
      v_inv := public.fn_union_issue_weekly_invoices(p_union_id, v_from, v_to, true);
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT,
                              v_detail = PG_EXCEPTION_DETAIL, v_context = PG_EXCEPTION_CONTEXT;
      v_inv := jsonb_build_object('success', false, 'error', v_msg, 'sqlstate', v_sqlstate,
                                  'exception_detail', v_detail, 'exception_context', v_context);
    END;
  END IF;

  INSERT INTO union_settlement_rounds (union_id, period_start, period_end, round_no, round_name,
                                       payees, amount, detail)
  VALUES (p_union_id, v_from, v_to, 4, 'union_invoices_issued',
          COALESCE((v_inv->>'invoices')::int, 0), 0, v_inv)
  ON CONFLICT (union_id, period_start, period_end, round_no) DO UPDATE
    SET detail=EXCLUDED.detail,payees=EXCLUDED.payees;

  IF COALESCE((v_inv->>'success')::boolean, false) IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'union_id', p_union_id,
      'error', 'round4_invoices_failed: ' || COALESCE(v_inv->>'error','unknown'),
      'period_start', v_from, 'period_end', v_to,
      'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
      'round3_agents_to_players', v_r3, 'eco_recorded', v_eco,
      'round4_invoices', v_inv);
  END IF;

  RETURN jsonb_build_object('success', true, 'union_id', p_union_id,
    'period_start', v_from, 'period_end', v_to,
    'round1_union_to_clubs', v_r1, 'round2_club_to_agents', v_r2,
    'round3_agents_to_players', v_r3, 'eco_recorded', v_eco,
    'round4_invoices', v_inv);
END $$;


ALTER FUNCTION public.fn_union_settlement_cascade(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_settlement_cascade_all(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_settlement_cascade_all(p_period_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_union   record;
  v_one     jsonb;
  v_results jsonb := '[]'::jsonb;
  v_unions  int := 0;
  v_failed  int := 0;
  v_retries int := 0;
  v_from    timestamptz := COALESCE(p_period_start, public.fn_union_prev_week_start(now()));
  v_to      timestamptz := COALESCE(p_period_end,   public.fn_union_week_start(now()));
  v_r1 numeric := 0; v_r2 numeric := 0; v_r3 numeric := 0;
  v_attempt  int;
  v_sqlstate text; v_msg text; v_detail text; v_context text;
  v_max_attempts constant int := 3;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_platform_admin())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  FOR v_union IN SELECT u.id FROM unions u LOOP
    v_attempt := 0;

    <<attempts>>
    LOOP
      v_attempt := v_attempt + 1;
      BEGIN
        v_one := public.fn_union_settlement_cascade(v_union.id, v_from, v_to);
        IF v_attempt > 1 THEN
          v_one := v_one || jsonb_build_object('attempts', v_attempt);
        END IF;
        EXIT attempts;

      EXCEPTION
        WHEN deadlock_detected OR serialization_failure THEN
          GET STACKED DIAGNOSTICS
            v_sqlstate = RETURNED_SQLSTATE,
            v_msg      = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_context  = PG_EXCEPTION_CONTEXT;

          -- Out of attempts, or no longer safe to start another one.
          IF v_attempt >= v_max_attempts
             OR public.fn_platform_frozen()
             OR EXTRACT(minute FROM now()) >= 45 THEN
            v_one := jsonb_build_object(
              'union_id', v_union.id, 'success', false,
              'error', v_msg, 'sqlstate', v_sqlstate, 'retryable', true,
              'attempts', v_attempt,
              'gave_up_because',
                CASE WHEN v_attempt >= v_max_attempts THEN 'attempts_exhausted'
                     WHEN public.fn_platform_frozen() THEN 'platform_frozen'
                     ELSE 'too_close_to_maintenance_break' END,
              'exception_detail', v_detail,
              'exception_context', v_context);
            EXIT attempts;
          END IF;

          v_retries := v_retries + 1;
          PERFORM pg_sleep(CASE v_attempt WHEN 1 THEN 3 ELSE 7 END);

        WHEN OTHERS THEN
          GET STACKED DIAGNOSTICS
            v_sqlstate = RETURNED_SQLSTATE,
            v_msg      = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_context  = PG_EXCEPTION_CONTEXT;
          v_one := jsonb_build_object(
            'union_id', v_union.id, 'success', false,
            'error', v_msg, 'sqlstate', v_sqlstate, 'retryable', false,
            'attempts', v_attempt,
            'exception_detail', v_detail,
            'exception_context', v_context);
          EXIT attempts;
      END;
    END LOOP attempts;

    IF COALESCE((v_one->>'success')::boolean, false) THEN
      v_unions := v_unions + 1;
      v_r1 := v_r1 + COALESCE((v_one->'round1_union_to_clubs'->>'total_rakeback')::numeric, 0);
      v_r2 := v_r2 + COALESCE((v_one->'round2_club_to_agents'->>'amount')::numeric, 0);
      v_r3 := v_r3 + COALESCE((v_one->'round3_agents_to_players'->>'amount')::numeric, 0);
    ELSE
      v_failed := v_failed + 1;
    END IF;
    v_results := v_results || jsonb_build_array(v_one);
  END LOOP;

  IF v_failed > 0 THEN
    INSERT INTO financial_alerts (source, severity, message, context)
    VALUES ('fn_union_settlement_cascade_all', 'critical',
            v_failed || ' of ' || (v_failed + v_unions) ||
            ' unions failed weekly settlement for ' ||
            to_char(v_from, 'YYYY-MM-DD') || ' to ' || to_char(v_to, 'YYYY-MM-DD') ||
            '. No rakeback moved and no invoices issued for those unions.' ||
            CASE WHEN v_retries > 0 THEN ' Retried ' || v_retries || ' time(s).' ELSE '' END,
            jsonb_build_object('period_start', v_from, 'period_end', v_to,
                               'unions_failed', v_failed, 'unions_settled', v_unions,
                               'retries', v_retries,
                               'detail', v_results));
  END IF;

  RETURN jsonb_build_object(
    'success', (v_failed = 0),
    'unions_settled', v_unions,
    'unions_failed', v_failed,
    'retries', v_retries,
    'period_start', v_from,
    'period_end', v_to,
    'round1_union_to_clubs', v_r1,
    'round2_club_to_agents', v_r2,
    'round3_agents_to_players', v_r3,
    'ran_at', now(),
    'detail', v_results
  );
END $$;


ALTER FUNCTION public.fn_union_settlement_cascade_all(p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_settlement_cascade_due(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_settlement_cascade_due() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_to    timestamptz := public.fn_union_week_start(now());
  v_from  timestamptz := public.fn_union_prev_week_start(now());
  v_total int;
  v_done  int;
  v_eligible int;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_platform_admin())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('success', true, 'skipped', true,
      'reason', 'platform_frozen', 'period_start', v_from, 'period_end', v_to);
  END IF;

  IF EXTRACT(minute FROM now()) >= 45 THEN
    RETURN jsonb_build_object('success', true, 'skipped', true,
      'reason', 'too_close_to_maintenance_break', 'period_start', v_from, 'period_end', v_to);
  END IF;

  IF v_to < now() - interval '3 days' THEN
    RETURN jsonb_build_object('success', true, 'skipped', true,
      'reason', 'period_closed_more_than_three_days_ago',
      'period_start', v_from, 'period_end', v_to, 'now', now());
  END IF;

  -- THE FLOOR. A period below every union's floor is not "due" at all.
  SELECT count(*) INTO v_eligible
    FROM unions u
    LEFT JOIN union_settlement_floor f ON f.union_id = u.id
   WHERE f.earliest_period_start IS NULL OR v_from >= f.earliest_period_start;

  IF v_eligible = 0 THEN
    RETURN jsonb_build_object('success', true, 'skipped', true,
      'reason', 'before_settlement_floor',
      'period_start', v_from, 'period_end', v_to,
      'note', 'Every union floors this period. Nothing was run.');
  END IF;

  -- Count completion for each eligible union, not the presence of Round 1.
  v_total := v_eligible;
  SELECT count(*) INTO v_done FROM public.unions u
  LEFT JOIN public.union_settlement_floor f ON f.union_id=u.id
  WHERE (f.earliest_period_start IS NULL OR v_from>=f.earliest_period_start)
    AND EXISTS (SELECT 1 FROM public.union_settlement_rounds r
      WHERE r.union_id=u.id AND r.period_start=v_from AND r.period_end=v_to AND r.round_no=4
        AND r.detail->>'success'='true' AND COALESCE(r.detail->>'skipped','false')<>'true')
    AND NOT EXISTS (SELECT 1 FROM generate_series(2,3) n
      WHERE NOT EXISTS (SELECT 1 FROM public.union_settlement_rounds r
        WHERE r.union_id=u.id AND r.period_start=v_from AND r.period_end=v_to AND r.round_no=n
          AND COALESCE(r.detail->'latest_attempt',r.detail)->>'amount' IS NOT NULL
          AND COALESCE(r.detail->'latest_attempt',r.detail)->>'payees' IS NOT NULL
          AND (COALESCE(r.detail->'latest_attempt',r.detail)->'shortfalls')='0'::jsonb
          AND COALESCE(COALESCE(r.detail->'latest_attempt',r.detail)->>'success','true')<>'false'));

  IF v_total > 0 AND v_done >= v_total THEN
    RETURN jsonb_build_object('success', true, 'skipped', true,
      'reason', 'already_settled', 'period_start', v_from, 'period_end', v_to);
  END IF;

  RETURN public.fn_union_settlement_cascade_all(v_from, v_to);
END $$;


ALTER FUNCTION public.fn_union_settlement_cascade_due() OWNER TO postgres;

--
-- Name: FUNCTION fn_union_settlement_cascade_due(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_settlement_cascade_due() IS 'Settles the union week that has just closed, once. Refuses while the platform is frozen, after :45, and for any period that closed more than three days ago. Safe on any schedule; a missed day heals on the next tick.';


--
-- Name: fn_union_settlement_conservation_assert(uuid, timestamp with time zone, timestamp with time zone, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_settlement_conservation_assert(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_r1 jsonb, p_r2 jsonb, p_r3 jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rake     numeric := (p_r1->>'period_rake')::numeric;
  v_paid     numeric := (p_r1->>'total_rakeback')::numeric;
  v_retained numeric := (p_r1->>'union_retained')::numeric;
  v_r2_amt   numeric := (p_r2->>'amount')::numeric;
  v_r3_amt   numeric := (p_r3->>'amount')::numeric;
  v_neg      text;
  v_checked  int := 0; v_totals jsonb;
BEGIN
  -- Idempotent Round 1 replies omit totals. Recover its immutable finalized
  -- settlement record for this exact union/period before asserting arithmetic.
  IF (v_rake IS NULL OR v_paid IS NULL OR v_retained IS NULL)
     AND p_r1->>'error'='already_executed' THEN
    SELECT c.totals INTO v_totals FROM public.ca_settlements c
    WHERE c.settlement_type='union_rakeback_close' AND c.union_id=p_union_id AND c.state='final'
      AND c.external_ref=p_union_id::text || ':'
        || to_char(p_from at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
        || to_char(p_to at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"');
    v_rake := (v_totals->>'period_rake')::numeric;
    v_paid := (v_totals->>'payout_total')::numeric;
    v_retained := (v_totals->>'retained')::numeric;
  END IF;
  IF v_rake IS NULL OR v_paid IS NULL OR v_retained IS NULL OR v_r2_amt IS NULL OR v_r3_amt IS NULL THEN
    RAISE EXCEPTION 'CONSERVATION_UNVERIFIED: settlement totals are missing';
  END IF;
  IF EXISTS(SELECT 1 FROM unnest(ARRAY[v_rake,v_paid,v_retained,v_r2_amt,v_r3_amt]) n
    WHERE n::text IN ('NaN','Infinity','-Infinity') OR n<0 OR n<>round(n,2)) THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH: settlement totals must be finite nonnegative whole cents';
  END IF;
  IF v_rake <> v_paid+v_retained THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH round1_arithmetic: rake % <> paid % + retained %',v_rake,v_paid,v_retained;
  END IF;
  IF v_paid>v_rake THEN RAISE EXCEPTION 'CONSERVATION_BREACH round1_overpay'; END IF;
  v_checked := v_checked+2;

  -- 6. Rounds 2 and 3 never move a negative amount.
  IF COALESCE(v_r2_amt, 0) < 0 THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH round2_negative_amount: %', v_r2_amt;
  END IF;
  IF COALESCE(v_r3_amt, 0) < 0 THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH round3_negative_amount: %', v_r3_amt;
  END IF;
  v_checked := v_checked + 2;

  -- 3 + 4 + 5. Nothing this union touches may be negative afterwards.
  SELECT string_agg(x.pool || ' = ' || COALESCE(x.amt::text,'NULL'), '; ') INTO v_neg
    FROM (
      SELECT 'union chip wallet' AS pool, w.chip_balance AS amt
        FROM union_wallets w
       WHERE w.union_id = p_union_id AND (w.chip_balance < 0 OR w.chip_balance IS NULL)
      UNION ALL
      SELECT 'union rake wallet', w.rake_wallet
        FROM union_wallets w
       WHERE w.union_id = p_union_id AND (w.rake_wallet < 0 OR w.rake_wallet IS NULL)
      UNION ALL
      SELECT 'club treasury ' || c.name, c.chip_treasury
        FROM clubs c
        JOIN union_clubs uc ON uc.club_id = c.id
       WHERE uc.union_id = p_union_id AND (c.chip_treasury < 0 OR c.chip_treasury IS NULL)
      UNION ALL
      SELECT 'member wallet ' || cm.user_id::text, cm.chip_balance
        FROM club_members cm
        JOIN union_clubs uc ON uc.club_id = cm.club_id
       WHERE uc.union_id = p_union_id AND (cm.chip_balance < 0 OR cm.chip_balance IS NULL)
    ) x;

  IF v_neg IS NOT NULL THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH negative_pool after settlement: %', left(v_neg, 400);
  END IF;
  v_checked := v_checked + 3;

  RETURN jsonb_build_object(
    'conservation', 'asserted',
    'checks', v_checked,
    'period_start', p_from, 'period_end', p_to,
    'round1_rake', v_rake, 'round1_paid', v_paid, 'round1_retained', v_retained,
    'round2_amount', v_r2_amt, 'round3_amount', v_r3_amt);
END $$;


ALTER FUNCTION public.fn_union_settlement_conservation_assert(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_r1 jsonb, p_r2 jsonb, p_r3 jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_union_settlement_conservation_assert(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_r1 jsonb, p_r2 jsonb, p_r3 jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_settlement_conservation_assert(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_r1 jsonb, p_r2 jsonb, p_r3 jsonb) IS 'Raises CONSERVATION_BREACH if a union settlement does not balance. Called inside fn_union_settlement_cascade before it commits, so a breach rolls the settlement back rather than reporting it afterwards.';


--
-- Name: fn_union_settlement_preview(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_settlement_preview(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid, p_period_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from timestamptz := COALESCE(p_period_start, public.fn_union_prev_week_start(now()));
  v_to   timestamptz := COALESCE(p_period_end,   public.fn_union_week_start(now()));
  v_r1_done boolean;
  v_rake_wallet numeric;
  v_r2_total numeric := 0; v_r2_payees int := 0;
  v_r3_total numeric := 0; v_r3_payees int := 0;
  v_r2_short jsonb := '[]'::jsonb;
  v_r3_short jsonb := '[]'::jsonb;
  v_r2_short_amt numeric := 0; v_r3_short_amt numeric := 0;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_union_overseer(p_union_id, auth.uid()))) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  SELECT EXISTS (SELECT 1 FROM union_rakeback_log
                  WHERE union_id = p_union_id
                    AND period_start = v_from AND period_end = v_to)
    INTO v_r1_done;

  SELECT COALESCE(rake_wallet,0) INTO v_rake_wallet
    FROM union_wallets WHERE union_id = p_union_id;

  -- ROUND 2 - unsettled agent commission, and whether the club treasury covers it.
  WITH owed AS (
    SELECT ac.club_id, ac.user_id, SUM(ac.amount) AS amt
      FROM agent_commissions ac
      JOIN union_clubs uc ON uc.club_id = ac.club_id AND uc.union_id = p_union_id
      JOIN agents a ON a.user_id = ac.user_id AND a.club_id = ac.club_id AND a.status='active'
     WHERE ac.created_at >= v_from AND ac.created_at < v_to
       AND ac.settled_at IS NULL AND NOT public.fn_agent_commission_paid_by_period(ac.club_id, ac.user_id, ac.created_at)
     GROUP BY ac.club_id, ac.user_id
    HAVING SUM(ac.amount) > 0
  ), byclub AS (
    SELECT o.club_id, SUM(o.amt) AS club_owed,
           COALESCE(c.chip_treasury,0) AS treasury, c.name
      FROM owed o JOIN clubs c ON c.id = o.club_id
     GROUP BY o.club_id, c.chip_treasury, c.name
  )
  SELECT COALESCE(SUM(o.amt),0), COUNT(*)::int
    INTO v_r2_total, v_r2_payees FROM owed o;

  WITH owed AS (
    SELECT ac.club_id, SUM(ac.amount) AS amt
      FROM agent_commissions ac
      JOIN union_clubs uc ON uc.club_id = ac.club_id AND uc.union_id = p_union_id
      JOIN agents a ON a.user_id = ac.user_id AND a.club_id = ac.club_id AND a.status='active'
     WHERE ac.created_at >= v_from AND ac.created_at < v_to AND ac.settled_at IS NULL AND NOT public.fn_agent_commission_paid_by_period(ac.club_id, ac.user_id, ac.created_at)
     GROUP BY ac.club_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'club_id', o.club_id, 'club', c.name,
           'owed', o.amt, 'treasury', COALESCE(c.chip_treasury,0),
           'short_by', round(o.amt - COALESCE(c.chip_treasury,0), 2))), '[]'::jsonb),
         COALESCE(SUM(o.amt - COALESCE(c.chip_treasury,0)), 0)
    INTO v_r2_short, v_r2_short_amt
    FROM owed o JOIN clubs c ON c.id = o.club_id
   WHERE COALESCE(c.chip_treasury,0) < o.amt;

  -- ROUND 3 - pending player rakeback, and whether the paying agent covers it.
  WITH owed AS (
    SELECT rp.user_id AS player_id, rp.club_id, cm.agent_id AS agent_user,
           SUM(rp.rakeback_amount) AS amt
      FROM rakeback_periods rp
      JOIN union_clubs uc ON uc.club_id = rp.club_id AND uc.union_id = p_union_id
      JOIN club_members cm ON cm.user_id = rp.user_id AND cm.club_id = rp.club_id
     WHERE rp.status = 'pending'
       AND rp.period_start >= v_from::date
       AND rp.period_start <  v_to::date + 1
       AND cm.agent_id IS NOT NULL
     GROUP BY rp.user_id, rp.club_id, cm.agent_id
    HAVING SUM(rp.rakeback_amount) > 0
  )
  SELECT COALESCE(SUM(amt),0), COUNT(*)::int INTO v_r3_total, v_r3_payees FROM owed;

  WITH owed AS (
    SELECT rp.club_id, cm.agent_id AS agent_user, SUM(rp.rakeback_amount) AS amt
      FROM rakeback_periods rp
      JOIN union_clubs uc ON uc.club_id = rp.club_id AND uc.union_id = p_union_id
      JOIN club_members cm ON cm.user_id = rp.user_id AND cm.club_id = rp.club_id
     WHERE rp.status = 'pending'
       AND rp.period_start >= v_from::date AND rp.period_start < v_to::date + 1
       AND cm.agent_id IS NOT NULL
     GROUP BY rp.club_id, cm.agent_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'agent_user_id', o.agent_user,
           'agent', COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), pr.username),
           'club_id', o.club_id, 'owed', o.amt,
           'agent_balance', COALESCE(am.chip_balance,0),
           'short_by', round(o.amt - COALESCE(am.chip_balance,0), 2))), '[]'::jsonb),
         COALESCE(SUM(o.amt - COALESCE(am.chip_balance,0)), 0)
    INTO v_r3_short, v_r3_short_amt
    FROM owed o
    LEFT JOIN club_members am ON am.user_id = o.agent_user AND am.club_id = o.club_id
    LEFT JOIN profiles pr ON pr.id = o.agent_user
   WHERE COALESCE(am.chip_balance,0) < o.amt;

  RETURN jsonb_build_object(
    'union_id', p_union_id,
    'period_start', v_from, 'period_end', v_to,
    'round1', jsonb_build_object(
      'already_executed', v_r1_done,
      'rake_treasury_available', v_rake_wallet),
    'round2', jsonb_build_object(
      'payees', v_r2_payees, 'amount', round(v_r2_total,2),
      'clubs_short', jsonb_array_length(v_r2_short),
      'short_by', round(v_r2_short_amt,2), 'detail', v_r2_short),
    'round3', jsonb_build_object(
      'payees', v_r3_payees, 'amount', round(v_r3_total,2),
      'agents_short', jsonb_array_length(v_r3_short),
      'short_by', round(v_r3_short_amt,2), 'detail', v_r3_short),
    'total_to_move', round(v_r2_total + v_r3_total, 2),
    'has_blockers', (jsonb_array_length(v_r2_short) + jsonb_array_length(v_r3_short)) > 0
  );
END $$;


ALTER FUNCTION public.fn_union_settlement_preview(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_shared_cost_allocation(uuid, numeric, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_shared_cost_allocation(p_union_id uuid, p_total_cost numeric, p_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, club_rake numeric, union_rake numeric, rake_share numeric, allocated_cost numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start timestamptz := COALESCE(p_start, fn_union_week_start());
  v_end   timestamptz := COALESCE(p_end, now());
  v_total numeric;
BEGIN
  IF p_total_cost IS NULL OR p_total_cost < 0 THEN
    RAISE EXCEPTION 'p_total_cost must be >= 0' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH r AS (
    -- inherits the reconciliation report's authorization check
    SELECT rep.club_id, rep.club_name, rep.rake_paid
      FROM fn_union_reconciliation_report(p_union_id, v_start, v_end) rep
  ),
  tot AS (SELECT NULLIF(SUM(r.rake_paid), 0) AS all_rake FROM r)
  SELECT r.club_id, r.club_name, r.rake_paid,
         COALESCE(tot.all_rake, 0),
         CASE WHEN tot.all_rake IS NULL THEN 0
              ELSE round(r.rake_paid / tot.all_rake, 6) END,
         CASE WHEN tot.all_rake IS NULL THEN 0
              ELSE round(p_total_cost * (r.rake_paid / tot.all_rake), 2) END
    FROM r CROSS JOIN tot
   ORDER BY r.rake_paid DESC;
END;
$$;


ALTER FUNCTION public.fn_union_shared_cost_allocation(p_union_id uuid, p_total_cost numeric, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_slugify(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_slugify(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT NULLIF(
    trim(BOTH '-' FROM regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', '-', 'g')),
    ''
  );
$$;


ALTER FUNCTION public.fn_union_slugify(p_name text) OWNER TO postgres;

--
-- Name: fn_union_totals_follow_club_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_totals_follow_club_counts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT DISTINCT uc.union_id
      FROM newrows n
      JOIN oldrows o ON o.id = n.id
      JOIN union_clubs uc ON uc.club_id = n.id
     WHERE COALESCE(n.member_count, 0)      IS DISTINCT FROM COALESCE(o.member_count, 0)
        OR COALESCE(n.admin_count, 0)       IS DISTINCT FROM COALESCE(o.admin_count, 0)
        OR COALESCE(n.super_agent_count, 0) IS DISTINCT FROM COALESCE(o.super_agent_count, 0)
        OR COALESCE(n.agent_count, 0)       IS DISTINCT FROM COALESCE(o.agent_count, 0)
  LOOP
    PERFORM public.recompute_union_levels(r.union_id, true);
  END LOOP;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_union_totals_follow_club_counts() OWNER TO postgres;

--
-- Name: fn_union_tournament_rake_by_club(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_tournament_rake_by_club(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean DEFAULT true) RETURNS TABLE(club_id uuid, rake_paid numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH attributed AS (
    SELECT DISTINCT ON (cm.user_id) cm.user_id, cm.club_id
      FROM club_members cm
      JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = p_union_id
      JOIN profiles p ON p.id = cm.user_id
     WHERE p_include_horses OR COALESCE(p.is_horse, false) = false
     ORDER BY cm.user_id, cm.joined_at ASC NULLS LAST, cm.club_id
  )
  SELECT a.club_id, round(SUM(u.rake_amount), 2)
    FROM fn_union_tournament_rake_by_user(p_union_id, p_start, p_end) u
    JOIN attributed a ON a.user_id = u.user_id
   GROUP BY a.club_id;
$$;


ALTER FUNCTION public.fn_union_tournament_rake_by_club(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean) OWNER TO postgres;

--
-- Name: fn_union_tournament_rake_by_user(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_tournament_rake_by_user(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(user_id uuid, rake_amount numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  WITH rr AS (
    SELECT r.id, r.tournament_id, r.rake_amount,
           CASE WHEN r.metadata->>'user_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                THEN (r.metadata->>'user_id')::uuid END AS payer
      FROM rake_records r
     WHERE r.is_tournament
       AND r.created_at >= p_start AND r.created_at < p_end
       AND r.rake_amount <> 0
       AND (r.club_id = p_union_id
            OR EXISTS (SELECT 1 FROM union_clubs uc
                        WHERE uc.union_id = p_union_id AND uc.club_id = r.club_id))
  ),
  direct AS (
    SELECT rr.payer AS uid, SUM(rr.rake_amount) AS amt
      FROM rr WHERE rr.payer IS NOT NULL GROUP BY 1
  ),
  split AS (
    SELECT tp.user_id AS uid, SUM(rr.rake_amount / n.cnt) AS amt
      FROM rr
      JOIN LATERAL (SELECT count(*)::numeric AS cnt
                      FROM tournament_players tp0
                     WHERE tp0.tournament_id = rr.tournament_id) n ON n.cnt > 0
      JOIN tournament_players tp ON tp.tournament_id = rr.tournament_id
     WHERE rr.payer IS NULL AND rr.tournament_id IS NOT NULL
     GROUP BY 1
  )
  SELECT x.uid, round(SUM(x.amt), 4)
    FROM (SELECT * FROM direct UNION ALL SELECT * FROM split) x
   WHERE x.uid IS NOT NULL
   GROUP BY x.uid;
$_$;


ALTER FUNCTION public.fn_union_tournament_rake_by_user(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_treasury_selftest(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_treasury_selftest() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_u record; v_breaches jsonb := '[]'::jsonb;
  v_credits numeric; v_debits numeric; v_expected numeric; v_drift numeric;
  v_dups integer; v_retired_bal numeric; v_lapsed_unclosed boolean;
  v_tolerance numeric := 150; v_cons jsonb; v_lag jsonb; b jsonb;
BEGIN
  FOR v_u IN SELECT uw.union_id, uw.chip_balance, uw.rake_wallet, uw.promo_wallet FROM union_wallets uw
  LOOP
    IF v_u.chip_balance < 0 OR v_u.rake_wallet < 0 OR v_u.promo_wallet < 0 THEN
      v_breaches := v_breaches || jsonb_build_object('union_id', v_u.union_id,
        'check', 'non_negative_wallets', 'chip', v_u.chip_balance,
        'rake', v_u.rake_wallet, 'promo', v_u.promo_wallet);
    END IF;

    -- CHECKPOINTED 2026-08-20: was an unbounded SUM over every rake_wallet
    -- row ever written (609k rows, +69k/day, no index) which had crossed
    -- the statement timeout and was aborting this whole sentinel every
    -- cycle. The full recompute now runs at most once per 24h and alerts
    -- if the incremental total ever disagrees with it.
    IF NOT EXISTS (SELECT 1 FROM union_rake_ledger_checkpoint c
                    WHERE c.union_id = v_u.union_id
                      AND c.last_verified_at > now() - interval '24 hours') THEN
      PERFORM fn_union_rake_ledger_checkpoint_verify(v_u.union_id);
    END IF;

    SELECT g.total_credits, g.total_debits
      INTO v_credits, v_debits
      FROM fn_union_rake_ledger_totals(v_u.union_id) g;

    v_expected := v_credits - v_debits;
    v_drift := round(v_u.rake_wallet - v_expected, 2);
    IF abs(v_drift) > v_tolerance THEN
      v_breaches := v_breaches || jsonb_build_object('union_id', v_u.union_id,
        'check', 'rake_wallet_ledger_reconciliation',
        'wallet', v_u.rake_wallet, 'ledger_expected', v_expected, 'drift', v_drift);
    END IF;

    SELECT (MAX(period_end) IS NOT NULL AND MAX(period_end) < public.fn_union_week_start(now()))
      INTO v_lapsed_unclosed FROM union_rakeback_log WHERE union_id = v_u.union_id;
    IF COALESCE(v_lapsed_unclosed, false)
       AND EXISTS (SELECT 1 FROM union_wallet_transactions
                    WHERE union_id = v_u.union_id AND wallet='rake_wallet'
                      AND tx_type='rake' AND direction='credit'
                      AND created_at < public.fn_union_week_start(now())
                      AND created_at >= (SELECT MAX(period_end) FROM union_rakeback_log WHERE union_id = v_u.union_id)) THEN
      v_breaches := v_breaches || jsonb_build_object('union_id', v_u.union_id, 'check', 'lapsed_week_unclosed');
    END IF;
  END LOOP;

  -- BOUNDED 2026-08-20: was an unbounded GROUP BY over all of
  -- bbj_contributions, which timed out and killed the whole sentinel.
  SELECT COUNT(*) INTO v_dups FROM (
    SELECT 1 FROM bbj_contributions
     WHERE hand_id IS NOT NULL
       AND created_at > now() - interval '7 days'
     GROUP BY pool_id, hand_id HAVING COUNT(*) > 1) d;
  IF v_dups > 0 THEN
    v_breaches := v_breaches || jsonb_build_object('check', 'bbj_duplicate_hand_contributions', 'groups', v_dups);
  END IF;

  SELECT COALESCE(SUM(main_balance + backup_balance + promo_balance), 0) INTO v_retired_bal
    FROM bbj_pools WHERE status = 'retired';
  IF v_retired_bal <> 0 THEN
    v_breaches := v_breaches || jsonb_build_object('check', 'retired_pools_hold_money', 'total', v_retired_bal);
  END IF;

  IF EXISTS (SELECT 1 FROM bbj_pools WHERE main_balance < 0 OR backup_balance < 0 OR promo_balance < 0) THEN
    v_breaches := v_breaches || jsonb_build_object('check', 'negative_bbj_pool_balance');
  END IF;

  -- 2026-08-20: fn_bbj_conservation_check is STABLE and therefore cannot
  -- maintain its own checkpoint. This VOLATILE caller does it: fold the
  -- tail forward every cycle, and recompute against truth once per 24h.
  PERFORM fn_bbj_contributions_total_advance();
  IF NOT EXISTS (SELECT 1 FROM money_flow_checkpoint c
                  WHERE c.metric_key = 'bbj_contributions_inflow'
                    AND c.last_verified_at > now() - interval '24 hours') THEN
    PERFORM fn_bbj_contributions_total_verify();
  END IF;

  v_cons := fn_bbj_conservation_check();
  IF (v_cons->>'healthy')::boolean IS NOT TRUE THEN
    v_breaches := v_breaches || jsonb_build_object('check', 'bbj_pool_conservation_drift',
      'drift_from_baseline', v_cons->>'drift_from_baseline');
  END IF;

  v_lag := fn_settler_lag_check();
  IF (v_lag->>'healthy')::boolean IS NOT TRUE THEN
    v_breaches := v_breaches || jsonb_build_object('check', 'rakeback_settler_lagging',
      'lag_hours', v_lag->>'lag_hours', 'backlog_rows', v_lag->>'backlog_rows');
  END IF;

  FOR b IN SELECT * FROM jsonb_array_elements(v_breaches)
  LOOP
    IF NOT EXISTS (SELECT 1 FROM financial_alerts
                    WHERE source = 'fn_union_treasury_selftest' AND resolved IS NOT TRUE
                      AND context->>'check' = b->>'check'
                      AND COALESCE(context->>'union_id','') = COALESCE(b->>'union_id','')) THEN
      INSERT INTO financial_alerts (severity, source, message, context)
      VALUES ('critical', 'fn_union_treasury_selftest',
              'Union treasury conservation breach: ' || (b->>'check'), b);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'healthy', jsonb_array_length(v_breaches) = 0,
    'breaches', v_breaches, 'bbj_conservation', v_cons, 'settler_lag', v_lag);
END
$$;


ALTER FUNCTION public.fn_union_treasury_selftest() OWNER TO postgres;

--
-- Name: fn_union_week_start(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_week_start(p_at timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT date_trunc('week', (p_at AT TIME ZONE 'America/Los_Angeles'))
           AT TIME ZONE 'America/Los_Angeles';
$$;


ALTER FUNCTION public.fn_union_week_start(p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_union_week_start(p_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_week_start(p_at timestamp with time zone) IS 'Start of the union week containing p_at: midnight America/Los_Angeles on Monday. Dan 2026-09-07: the week cannot end until the West Coast hits 11:59:59.';


--
-- Name: fn_union_weekly_agent_statements(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_weekly_agent_statements(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid, p_period_start timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(agent_user_id uuid, agent_name text, club_name text, statement jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.fn_is_any_union_overseer(auth.uid()) AND NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  RETURN QUERY
  SELECT a.user_id, pr.username, c.name,
         public.fn_agent_weekly_statement(a.user_id, COALESCE(p_period_start, public.fn_union_week_start(now())), now())
    FROM agents a
    JOIN union_clubs uc ON uc.club_id = a.club_id AND uc.union_id = p_union_id
    LEFT JOIN profiles pr ON pr.id = a.user_id
    LEFT JOIN clubs c ON c.id = a.club_id
   WHERE a.status = 'active'
   ORDER BY pr.username NULLS LAST;
END $$;


ALTER FUNCTION public.fn_union_weekly_agent_statements(p_union_id uuid, p_period_start timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_weekly_rakeback_close(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_weekly_rakeback_close(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_wallet       public.union_wallets%ROWTYPE;
  v_period_total numeric := 0;
  v_payout_total numeric := 0;
  v_retained     numeric := 0;
  v_clubs_paid   integer := 0;
  v_club         record;
  v_new_rw       numeric;
  v_new_cb       numeric;
  v_rw_before    numeric;
  v_cb_before    numeric;
  v_clubs_before numeric := 0;
  v_clubs_after  numeric := 0;
  v_credit       jsonb;
  v_sref         text;
  v_sid          uuid;
  v_sstate       text;
  v_actor        uuid;
BEGIN
  -- EMERGENCY SETTLEMENT LOCK CHECK
  IF EXISTS (SELECT 1 FROM settlement_locks WHERE lock_type = 'GLOBAL_SETTLEMENT_FREEZE' AND is_active = true) THEN
    RAISE EXCEPTION 'EMERGENCY_PROFIT_DRIFT_LOCK';
  END IF;

  IF p_union_id IS NULL OR p_period_start IS NULL OR p_period_end IS NULL
     OR p_period_end <= p_period_start OR NOT isfinite(p_period_start) OR NOT isfinite(p_period_end) THEN
    RETURN jsonb_build_object('success', false, 'error', 'bad_params');
  END IF;

  IF EXISTS (SELECT 1 FROM public.union_settlement_floor f
              WHERE f.union_id = p_union_id
                AND p_period_start < f.earliest_period_start) THEN
    RETURN jsonb_build_object('success', false, 'error', 'before_settlement_floor');
  END IF;

  -- Every entry point uses the union's calendar, including DST boundaries.
  IF p_period_start <> public.fn_union_week_start(p_period_start)
     OR p_period_end <> public.fn_union_week_start(p_period_end)
     OR p_period_end > public.fn_union_week_start(now()) THEN
    RETURN jsonb_build_object('success', false, 'error', 'period_not_closed_union_weeks');
  END IF;

  IF EXISTS (
    SELECT 1 FROM union_rakeback_log
     WHERE union_id = p_union_id
       AND period_start = p_period_start AND period_end = p_period_end
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_executed');
  END IF;

  -- settlement walk: one row per (union, period), resumable after 'failed'
  v_sref := p_union_id::text || ':'
    || to_char(p_period_start at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
    || to_char(p_period_end   at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  SELECT id, state INTO v_sid, v_sstate
    FROM ca_settlements
   WHERE settlement_type = 'union_rakeback_close' AND external_ref = v_sref
   FOR UPDATE;
  IF v_sid IS NULL THEN
    INSERT INTO ca_settlements (id, settlement_type, external_ref, state, union_id, totals)
    VALUES (gen_random_uuid(), 'union_rakeback_close', v_sref, 'open', p_union_id, '{}'::jsonb)
    RETURNING id INTO v_sid;
  ELSIF v_sstate = 'final' THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_executed', 'settlement_id', v_sid);
  ELSIF v_sstate = 'failed' THEN
    UPDATE ca_settlements SET state = 'open', error_detail = NULL WHERE id = v_sid;  -- resume
  ELSE
    -- intermediate states never persist (single transaction), so anything
    -- else here is a concurrent close of the same period. Refuse loudly.
    RETURN jsonb_build_object('success', false, 'error', 'close_already_in_state_' || v_sstate,
                              'settlement_id', v_sid);
  END IF;

  UPDATE ca_settlements SET state = 'locked_for_calculation' WHERE id = v_sid;

  SELECT * INTO v_wallet FROM union_wallets WHERE union_id = p_union_id FOR UPDATE;
  IF v_wallet.union_id IS NULL THEN
    UPDATE ca_settlements SET state = 'failed', error_detail = 'no_wallet' WHERE id = v_sid;
    RETURN jsonb_build_object('success', false, 'error', 'no_wallet', 'settlement_id', v_sid);
  END IF;

  -- Recheck after the union wallet lock: concurrent overlapping closes cannot
  -- both consume the same rake credits under different period identities.
  IF EXISTS (SELECT 1 FROM public.union_rakeback_log l
              WHERE l.union_id = p_union_id
                AND l.period_start < p_period_end AND l.period_end > p_period_start) THEN
    UPDATE public.ca_settlements SET state = 'failed', error_detail = 'overlapping_closed_period' WHERE id = v_sid;
    RETURN jsonb_build_object('success', false, 'error', 'overlapping_closed_period', 'settlement_id', v_sid);
  END IF;

  /* THE PERIOD (unchanged): everything the rake treasury received. Each credit
     now also carries the GAME TYPE it came from: the named tournament's
     tournament_type, or cash when it names none. */
  DROP TABLE IF EXISTS _uwrb_credits;
  CREATE TEMP TABLE _uwrb_credits ON COMMIT DROP AS
  WITH raw AS (
    SELECT t.id, t.amount, t.notes, t.created_at,
           substring(t.notes from '\[tournament ([0-9a-f-]+)\]')::uuid AS tournament_id
      FROM union_wallet_transactions t
     WHERE t.union_id = p_union_id
       AND t.wallet = 'rake_wallet' AND t.direction = 'credit' AND t.tx_type = 'rake'
       AND t.created_at >= p_period_start AND t.created_at < p_period_end
  )
  SELECT r.id, r.amount, r.notes, r.created_at, r.tournament_id,
         CASE WHEN r.tournament_id IS NULL THEN 'cash'
              ELSE COALESCE(lower(tr.tournament_type), 'other') END AS game_type
    FROM raw r
    LEFT JOIN tournaments tr ON tr.id = r.tournament_id;

  DROP TABLE IF EXISTS _uwrb_by_type;
  /* THE BASIS (Dan, 2026-09-03) lives in fn_union_club_rake_basis since
     Phase 6 (20260907): the statement and the reconciliation report read
     the same function, so what is paid and what is described cannot
     diverge. The block that used to be here is that function, verbatim. */
  CREATE TEMP TABLE _uwrb_by_type ON COMMIT DROP AS
  SELECT b.club_id, b.game_type, b.rake_in, b.rate, b.payout
    FROM public.fn_union_club_rake_basis(p_union_id, p_period_start, p_period_end, true) b;

  /* The per-club roll-up the money section pays from. */
  DROP TABLE IF EXISTS _uwrb;
  CREATE TEMP TABLE _uwrb ON COMMIT DROP AS
  SELECT club_id,
         round(sum(rake_in), 2) AS rake_in,
         round(sum(payout), 2)  AS payout
    FROM _uwrb_by_type
   GROUP BY club_id;

  SELECT round(COALESCE(SUM(amount), 0), 2) INTO v_period_total FROM _uwrb_credits;
  SELECT round(COALESCE(SUM(payout), 0), 2) INTO v_payout_total
    FROM _uwrb WHERE club_id IS NOT NULL AND club_id <> p_union_id;
  v_retained := round(v_period_total - v_payout_total, 2);

  /* a share can never exceed what the treasury received: the attribution is
     a view of the same credits, so this only trips on a data fault */
  IF v_payout_total > v_period_total THEN
    UPDATE ca_settlements SET state = 'failed', error_detail = 'attribution_exceeds_treasury' WHERE id = v_sid;
    RETURN jsonb_build_object('success', false, 'error', 'attribution_exceeds_treasury',
      'period_rake', v_period_total, 'payout', v_payout_total, 'settlement_id', v_sid);
  END IF;

  UPDATE ca_settlements
     SET state = 'calculated',
         totals = jsonb_build_object('period_rake', v_period_total, 'payout_total', v_payout_total,
                                     'retained', v_retained,
                                     'basis', 'players_of_the_club_at_union_tables',
                                     'rate_model', 'per_game_type',
                                     'basis_by_club', (SELECT COALESCE(jsonb_object_agg(club_id::text, rake_in), '{}'::jsonb) FROM _uwrb),
                                     'payout_by_club', (SELECT COALESCE(jsonb_object_agg(club_id::text, payout), '{}'::jsonb) FROM _uwrb),
                                     'basis_detail', (SELECT COALESCE(jsonb_agg(jsonb_build_object('club_id', club_id, 'game_type', game_type, 'rake_in', rake_in, 'rate', rate, 'payout', payout) ORDER BY club_id, game_type), '[]'::jsonb) FROM _uwrb_by_type),
                                     'basis_by_game_type', (SELECT COALESCE(jsonb_object_agg(game_type, x), '{}'::jsonb)
                                                              FROM (SELECT game_type,
                                                                           jsonb_build_object('basis', round(sum(rake_in), 2),
                                                                                              'payout', round(sum(payout), 2)) AS x
                                                                      FROM _uwrb_by_type GROUP BY game_type) g),
                                     'rates', (SELECT COALESCE(jsonb_object_agg(club_id::text || ':' || game_type, rate), '{}'::jsonb)
                                                 FROM _uwrb_by_type))
   WHERE id = v_sid;

  IF v_period_total <= 0 THEN
    INSERT INTO union_rakeback_log (union_id, period_start, period_end, total_rakeback, executed_at)
    VALUES (p_union_id, p_period_start, p_period_end, 0, now());
    UPDATE ca_settlements SET state = 'validated' WHERE id = v_sid;
    UPDATE ca_settlements SET state = 'ledger_posted' WHERE id = v_sid;
    UPDATE ca_settlements SET state = 'post_commit_verified' WHERE id = v_sid;
    UPDATE ca_settlements SET state = 'final' WHERE id = v_sid;
    RETURN jsonb_build_object('success', true, 'clubs_paid', 0,
      'period_rake', 0, 'total_rakeback', 0, 'union_retained', 0, 'note', 'no_rake',
      'settlement_id', v_sid);
  END IF;

  /* SEPARATE POTS (Phase 2.1). The rake treasury owes the whole period: the
     clubs' share leaves it as rakeback, the union's share leaves it for the
     general bank. The general bank is never a source. A treasury that cannot
     cover the period refuses the close whole - never partial, never from the
     bank - and says so. Who eats a short treasury is Dan's ruling
     (roadmap decision 4). */
  IF v_period_total > COALESCE(v_wallet.rake_wallet, 0) THEN
    UPDATE ca_settlements SET state = 'failed', error_detail = 'insufficient_rake_treasury' WHERE id = v_sid;
    PERFORM public.fn_ca_raise_drift_incident(
      'rakeback_close', 'incorrect_rakeback', 'critical',
      'rakeback-insufficient:' || p_union_id::text || ':' || to_char(p_period_start, 'YYYY-MM-DD'),
      v_period_total - COALESCE(v_wallet.rake_wallet, 0),
      v_period_total,
      COALESCE(v_wallet.rake_wallet, 0),
      'settlement', 'union', p_union_id, NULL, p_union_id,
      NULL, NULL, NULL, v_sid::text, NULL, NULL,
      'union rake treasury cannot cover the period it owes; close refused before any movement (the general bank is never a source)',
      true,
      jsonb_build_object('rake_wallet', v_wallet.rake_wallet,
                         'chip_balance', v_wallet.chip_balance,
                         'period_total', v_period_total,
                         'payout', v_payout_total, 'retained', v_retained,
                         'period_start', p_period_start, 'period_end', p_period_end));
    RETURN jsonb_build_object('success', false, 'error', 'insufficient_rake_treasury', 'retryable', true,
      'period_rake', v_period_total, 'payout', v_payout_total,
      'rake_wallet', v_wallet.rake_wallet, 'chip_balance', v_wallet.chip_balance,
      'settlement_id', v_sid);
  END IF;

  UPDATE ca_settlements SET state = 'validated' WHERE id = v_sid;

  -- guarded money section: all of it lands, or none of it does
  BEGIN
    /* One declaration for every balance write below. The union_wallets
       auto-ledger is skipped: the union side of each club credit is the
       from-leg of the club's own row, and the retained share is written
       explicitly. */
    PERFORM public.fn_ca_declare_ledger('rakeback', 'union_wallet', p_union_id, v_sid, NULL,
                                        ARRAY['union_wallets']);
    v_actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

    v_rw_before := round(COALESCE(v_wallet.rake_wallet, 0), 2);
    v_cb_before := round(COALESCE(v_wallet.chip_balance, 0), 2);
    SELECT round(COALESCE(SUM(c.chip_treasury), 0), 2) INTO v_clubs_before
      FROM clubs c
     WHERE c.id IN (SELECT club_id FROM _uwrb
                     WHERE club_id IS NOT NULL AND club_id <> p_union_id AND payout > 0);

    FOR v_club IN
      SELECT club_id, rake_in, payout FROM _uwrb
       WHERE club_id IS NOT NULL AND club_id <> p_union_id AND payout > 0
    LOOP
      v_credit := fn_credit_treasury(
        v_club.club_id, v_club.payout,
        'Union weekly rakeback ' || to_char(p_period_start, 'YYYY-MM-DD')
          || '..' || to_char(p_period_end, 'YYYY-MM-DD'),
        jsonb_build_object('union_id', p_union_id,
                           'period_start', p_period_start, 'period_end', p_period_end,
                           'rake_basis', v_club.rake_in, 'rate', 'per_game_type',
                           'by_game_type', (SELECT COALESCE(jsonb_object_agg(game_type,
                                                     jsonb_build_object('basis', rake_in, 'rate', rate, 'payout', payout)), '{}'::jsonb)
                                              FROM _uwrb_by_type g WHERE g.club_id = v_club.club_id),
                           'settlement_id', v_sid),
        'union_close:' || v_sid::text || ':' || v_club.club_id::text
      );
      IF COALESCE((v_credit->>'success')::boolean, false) IS NOT TRUE THEN
        RAISE EXCEPTION 'treasury credit failed for club %: %', v_club.club_id, v_credit;
      END IF;
      v_clubs_paid := v_clubs_paid + 1;
    END LOOP;

    -- one debit per pot: the treasury pays the whole period; the retained
    -- share moves to the general bank
    UPDATE union_wallets
       SET rake_wallet       = rake_wallet - v_period_total,
           chip_balance      = chip_balance + v_retained,
           total_settlements = COALESCE(total_settlements, 0) + v_payout_total,
           updated_at        = now()
     WHERE union_id = p_union_id
     RETURNING round(rake_wallet, 2), round(chip_balance, 2) INTO v_new_rw, v_new_cb;

    INSERT INTO union_wallet_transactions
      (union_id, club_id, amount, tx_type, wallet, direction, balance_after, notes)
    SELECT p_union_id, club_id, payout, 'rakeback', 'rake_wallet', 'debit', v_new_rw,
           'Weekly rakeback to club at the per-game-type rate (period '
             || to_char(p_period_start, 'YYYY-MM-DD') || '..'
             || to_char(p_period_end, 'YYYY-MM-DD') || ')'
      FROM _uwrb
     WHERE club_id IS NOT NULL AND club_id <> p_union_id AND payout > 0;

    IF v_retained > 0 THEN
      INSERT INTO union_wallet_transactions
        (union_id, amount, tx_type, wallet, direction, balance_after, notes)
      VALUES
        (p_union_id, v_retained, 'rake_hold', 'rake_wallet', 'debit', v_new_rw,
         'Union retained share + self-club rake, out of the rake treasury (period '
           || to_char(p_period_start, 'YYYY-MM-DD') || '..'
           || to_char(p_period_end, 'YYYY-MM-DD') || ')'),
        (p_union_id, v_retained, 'rake_hold', 'chip_balance', 'credit', v_new_cb,
         'Union retained share + self-club rake, into the general bank (period '
           || to_char(p_period_start, 'YYYY-MM-DD') || '..'
           || to_char(p_period_end, 'YYYY-MM-DD') || ')');

      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, to_type, to_entity_id,
         amount, category, union_id, description, idempotency_key, metadata)
      VALUES
        (v_actor, 'union_wallet', p_union_id, 'union_bank', p_union_id,
         v_retained, 'treasury_transfer', p_union_id,
         'Weekly union close ' || to_char(p_period_start, 'YYYY-MM-DD') || '..'
           || to_char(p_period_end, 'YYYY-MM-DD')
           || ': retained share ' || v_retained || ' of period rake ' || v_period_total
           || ' moves from the rake treasury to the general bank (clubs paid '
           || v_payout_total || ')',
         'union_close:' || v_sid::text || ':retained',
         jsonb_build_object('settlement_id', v_sid, 'period_start', p_period_start,
                            'period_end', p_period_end, 'period_rake', v_period_total,
                            'payout_total', v_payout_total, 'clubs_paid', v_clubs_paid));
    END IF;

    /* CONSERVATION, ASSERTED ON THE BALANCES THEMSELVES (not on the plan).
       What left the treasury must equal what the clubs and the bank received,
       to the cent, or none of it lands. */
    SELECT round(COALESCE(SUM(c.chip_treasury), 0), 2) INTO v_clubs_after
      FROM clubs c
     WHERE c.id IN (SELECT club_id FROM _uwrb
                     WHERE club_id IS NOT NULL AND club_id <> p_union_id AND payout > 0);

    IF round((v_new_rw - v_rw_before) + (v_new_cb - v_cb_before) + (v_clubs_after - v_clubs_before), 2) <> 0
       OR round(v_new_rw - v_rw_before, 2) <> round(-v_period_total, 2)
       OR round(v_clubs_after - v_clubs_before, 2) <> round(v_payout_total, 2)
       OR round(v_new_cb - v_cb_before, 2) <> round(v_retained, 2) THEN
      RAISE EXCEPTION 'conservation violation in the weekly union close: treasury % -> %, bank % -> %, clubs % -> %, period % payout % retained %',
        v_rw_before, v_new_rw, v_cb_before, v_new_cb, v_clubs_before, v_clubs_after,
        v_period_total, v_payout_total, v_retained;
    END IF;

    UPDATE ca_settlements
       SET state = 'ledger_posted',
           totals = totals || jsonb_build_object('clubs_paid', v_clubs_paid,
                                                 'retained', v_retained,
                                                 'rw_debit', v_period_total,
                                                 'conservation', 'asserted')
     WHERE id = v_sid;

    INSERT INTO union_rakeback_log (union_id, period_start, period_end, total_rakeback, executed_at)
    VALUES (p_union_id, p_period_start, p_period_end, v_payout_total, now());

  EXCEPTION WHEN OTHERS THEN
    -- every money movement above just rolled back to the section start
    UPDATE ca_settlements
       SET state = 'failed', error_detail = left(SQLERRM, 2000)
     WHERE id = v_sid;
    PERFORM public.fn_ca_raise_drift_incident(
      'rakeback_close', 'incorrect_rakeback', 'critical',
      'rakeback-close-failed:' || p_union_id::text || ':' || to_char(p_period_start, 'YYYY-MM-DD'),
      0, NULL, NULL,
      'settlement', 'union', p_union_id, NULL, p_union_id,
      NULL, NULL, NULL, v_sid::text, NULL, NULL,
      left('weekly rakeback close aborted mid-flight and rolled back cleanly: ' || SQLERRM, 500),
      true,
      jsonb_build_object('sqlstate', SQLSTATE,
                         'period_start', p_period_start, 'period_end', p_period_end,
                         'clubs_paid_before_abort', v_clubs_paid));
    RETURN jsonb_build_object('success', false, 'error', 'close_failed', 'retryable', true,
      'detail', SQLERRM, 'settlement_id', v_sid);
  END;

  UPDATE ca_settlements SET state = 'post_commit_verified' WHERE id = v_sid;
  UPDATE ca_settlements SET state = 'final' WHERE id = v_sid;

  RETURN jsonb_build_object('success', true,
    'clubs_paid', v_clubs_paid,
    'period_rake', v_period_total,
    'total_rakeback', v_payout_total,
    'union_retained', v_retained,
    'retained_to_bank', v_retained,
    'rake_wallet_after', v_new_rw,
    'chip_balance_after', v_new_cb,
    'conservation', 'asserted',
    'settlement_id', v_sid);
END
$$;


ALTER FUNCTION public.fn_union_weekly_rakeback_close(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_union_weekly_rakeback_close_all(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_weekly_rakeback_close_all(p_union_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_union        record;
  v_cursor       timestamptz;
  v_current_week timestamptz := public.fn_union_week_start(now());
  v_result       jsonb;
  v_next         timestamptz;
  v_boundary     timestamptz;
  v_results      jsonb := '[]'::jsonb;
  v_guard        integer;
BEGIN
  FOR v_union IN
    SELECT id FROM unions WHERE p_union_id IS NULL OR id = p_union_id
  LOOP
    SELECT MAX(period_end) INTO v_cursor
      FROM union_rakeback_log WHERE union_id = v_union.id;
    IF v_cursor IS NULL THEN
      SELECT MIN(created_at) INTO v_cursor
        FROM union_wallet_transactions
       WHERE union_id = v_union.id
         AND wallet = 'rake_wallet' AND direction = 'credit' AND tx_type = 'rake';
      IF v_cursor IS NULL THEN CONTINUE; END IF;
      v_cursor := public.fn_union_week_start(v_cursor);

    END IF;

    -- Never resume before the union's settlement floor. GREATEST ignores
    -- NULLs, so a union with no floor row is unaffected.
    v_cursor := GREATEST(v_cursor, (SELECT f.earliest_period_start
                                      FROM public.union_settlement_floor f
                                     WHERE f.union_id = v_union.id));

    -- The reset floor and legacy cursor may be UTC-midnight timestamps.
    -- Round UP once to a real union Monday, after applying the floor.
    v_boundary := public.fn_union_week_start(v_cursor);
    IF v_boundary < v_cursor THEN
      v_boundary := public.fn_union_week_start(v_boundary + interval '8 days');
    END IF;
    v_cursor := v_boundary;

    v_guard := 0;
    v_next := public.fn_union_week_start(v_cursor + interval '8 days');
    WHILE v_next <= v_current_week AND v_guard < 60 LOOP
      v_result := fn_union_weekly_rakeback_close(
        v_union.id, v_cursor, v_next);
      IF COALESCE(v_result->>'error', '') NOT IN ('', 'already_executed') THEN
        v_results := v_results || jsonb_build_object(
          'union_id', v_union.id, 'period_start', v_cursor, 'result', v_result);
        EXIT;
      END IF;
      IF (v_result->>'success')::boolean IS TRUE THEN
        v_results := v_results || jsonb_build_object(
          'union_id', v_union.id, 'period_start', v_cursor, 'result', v_result);
      END IF;
      v_cursor := v_next;
      v_next := public.fn_union_week_start(v_cursor + interval '8 days');
      v_guard := v_guard + 1;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'closes', v_results);
END $$;


ALTER FUNCTION public.fn_union_weekly_rakeback_close_all(p_union_id uuid) OWNER TO postgres;

--
-- Name: fn_union_weekly_statement(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_weekly_statement(p_union_id uuid, p_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, rake_generated numeric, commission_rate numeric, rakeback_owed numeric, player_won numeric, player_lost numeric, player_net numeric, pay_or_collect numeric, direction text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_start timestamptz;
  v_end   timestamptz;
BEGIN
  -- Default to the week that the next Monday close will settle.
  v_end   := COALESCE(p_end, now());
  v_start := COALESCE(p_start, v_end - interval '7 days');

  RETURN QUERY
  WITH basis AS (
    SELECT b.club_id, b.rake_share
      FROM fn_union_rake_basis_by_club(p_union_id, v_start, v_end) b
  ),
  pnl AS (
    SELECT p.club_id, p.realized_net, p.seated_stack, p.winnings, p.losses
      FROM fn_union_pnl_all_clubs(p_union_id, v_start, v_end) p
  ),
  baseline AS (
    SELECT (e->>'club_id')::uuid AS club_id, (e->>'seated_end')::numeric AS seated_start
      FROM jsonb_array_elements(
             COALESCE(fn_union_pnl_baseline(p_union_id, v_end), '[]'::jsonb)) e
  )
  SELECT
    uc.club_id,
    c.name::text,
    COALESCE(bs.rake_share, 0),
    COALESCE(uc.club_commission_rate, 0.90),
    round(COALESCE(bs.rake_share, 0) * COALESCE(uc.club_commission_rate, 0.90), 2),
    COALESCE(pn.winnings, 0),
    COALESCE(pn.losses, 0),
    -- what the club's players actually netted, felt included
    round(COALESCE(pn.realized_net, 0)
          + (COALESCE(pn.seated_stack, 0) - COALESCE(bl.seated_start, pn.seated_stack, 0)), 2),
    -- Dan's formula: total lost, less the rakeback returned
    round(
      -(COALESCE(pn.realized_net, 0)
        + (COALESCE(pn.seated_stack, 0) - COALESCE(bl.seated_start, pn.seated_stack, 0)))
      - COALESCE(bs.rake_share, 0) * COALESCE(uc.club_commission_rate, 0.90), 2),
    CASE
      WHEN round(
             -(COALESCE(pn.realized_net, 0)
               + (COALESCE(pn.seated_stack, 0) - COALESCE(bl.seated_start, pn.seated_stack, 0)))
             - COALESCE(bs.rake_share, 0) * COALESCE(uc.club_commission_rate, 0.90), 2) > 0
        THEN 'club pays union'
      WHEN round(
             -(COALESCE(pn.realized_net, 0)
               + (COALESCE(pn.seated_stack, 0) - COALESCE(bl.seated_start, pn.seated_stack, 0)))
             - COALESCE(bs.rake_share, 0) * COALESCE(uc.club_commission_rate, 0.90), 2) < 0
        THEN 'union pays club'
      ELSE 'square'
    END::text
  FROM union_clubs uc
  JOIN clubs c ON c.id = uc.club_id
  LEFT JOIN basis bs ON bs.club_id = uc.club_id
  LEFT JOIN pnl   pn ON pn.club_id = uc.club_id
  LEFT JOIN baseline bl ON bl.club_id = uc.club_id
  WHERE uc.union_id = p_union_id
  ORDER BY 9 DESC;
END $$;


ALTER FUNCTION public.fn_union_weekly_statement(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_unions_set_slug(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_unions_set_slug() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_base text;
  v_slug text;
  v_n    integer := 1;
BEGIN
  v_base := public.fn_union_slugify(COALESCE(NULLIF(NEW.slug, ''), NEW.name));
  IF v_base IS NULL THEN
    v_base := 'union';
  END IF;
  -- A slug that parses as a UUID, or that is a route word, would be
  -- indistinguishable from the thing it stands beside.
  IF v_base ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR v_base IN ('create') THEN
    v_base := v_base || '-union';
  END IF;
  v_slug := v_base;
  WHILE EXISTS (SELECT 1 FROM public.unions u WHERE u.slug = v_slug AND u.id <> NEW.id) LOOP
    v_n := v_n + 1;
    v_slug := v_base || '-' || v_n;
  END LOOP;
  NEW.slug := v_slug;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_unions_set_slug() OWNER TO postgres;

--
-- Name: fn_unpriced_tournaments(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_unpriced_tournaments(p_since interval DEFAULT '7 days'::interval) RETURNS TABLE(tournament_id uuid, name text, tournament_type text, buy_in_amount numeric, buy_in_fee numeric, entrants integer, uncollected numeric, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT t.id, t.name, t.tournament_type, t.buy_in_amount, coalesce(t.buy_in_fee, 0),
         coalesce(t.current_players, 0),
         round((t.buy_in_amount * 0.10 * coalesce(t.current_players, 0))::numeric, 2),
         t.created_at
  FROM public.tournaments t
  WHERE t.buy_in_amount > 0
    AND coalesce(t.current_players, 0) > 0            -- nobody entered, nothing lost
    AND t.created_at > now() - p_since
    /* Only a FINISHED event can be judged. REGISTERING and RUNNING have not
       earned yet; CANCELLED refunds its entries, so earning nothing is right. */
    AND upper(coalesce(t.status, '')) = 'COMPLETED'
    /* Satellites award a seat rather than a prize pool and legitimately carry
       no fee of their own; the target event charges it. */
    AND t.satellite_target_id IS NULL
    AND coalesce(t.satellite_seats, 0) = 0
    /* THE ACTUAL TEST: did it earn anything at all? Asking the rake ledger
       instead of the buy_in_fee column is the difference between 566 real
       findings and 5,230 false ones. */
    AND NOT EXISTS (
      SELECT 1 FROM public.rake_records r
       WHERE r.tournament_id = t.id AND r.is_tournament AND r.rake_amount > 0
    )
  ORDER BY t.created_at DESC;
$$;


ALTER FUNCTION public.fn_unpriced_tournaments(p_since interval) OWNER TO postgres;

--
-- Name: FUNCTION fn_unpriced_tournaments(p_since interval); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_unpriced_tournaments(p_since interval) IS 'COMPLETED tournaments that took a buy-in, had entrants, and earned NO rake of any kind. Added 2026-08-27 after 140 MTTs and 426 SNGs ran free between 08-21 and 08-25 with nothing noticing. Tests the rake_records ledger rather than buy_in_fee, because spins legitimately carry a zero fee and price themselves via fn_spin_settle_game. Excludes satellites, empty events, and anything not finished.';


