--
-- Name: fn_update_comment_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_update_comment_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE social_posts SET comment_count = COALESCE(comment_count, 0) + 1 WHERE id = NEW.post_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE social_posts SET comment_count = GREATEST(0, COALESCE(comment_count, 0) - 1) WHERE id = OLD.post_id;
    END IF;
    RETURN NULL;
END;
$$;


