    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$ BEGIN IF TG_OP = 'INSERT' THEN UPDATE social_posts SET comment_count = comment_count + 1, updated_at = NOW() WHERE id = NEW.post_id; RETURN NEW; ELSIF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND NEW.is_deleted = TRUE AND OLD.is_deleted = FALSE) THEN UPDATE social_posts SET comment_count = GREATEST(0, comment_count - 1), updated_at = NOW() WHERE id = COALESCE(NEW.post_id, OLD.post_id); RETURN COALESCE(NEW, OLD); END IF; RETURN NULL; END; $$;


