--
-- Name: fn_upsert_tournament_schedule(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_upsert_tournament_schedule(p_schedule jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid       uuid := auth.uid();
  v_id        uuid;
  v_union_id  uuid;
  v_club_id   uuid;
  v_name      text;
  v_days      integer[];
  v_times     text[];
  v_interval  integer;
  v_config    jsonb;
  v_active    boolean;
  v_d         integer;
  v_tm        text;
  v_existing  record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'not_authenticated');
  END IF;
  IF p_schedule IS NULL OR jsonb_typeof(p_schedule) <> 'object' THEN
    RETURN jsonb_build_object('error', 'schedule_must_be_object');
  END IF;

  v_id       := NULLIF(p_schedule->>'id', '')::uuid;
  v_union_id := NULLIF(p_schedule->>'unionId', '')::uuid;
  v_club_id  := NULLIF(p_schedule->>'clubId', '')::uuid;
  v_name     := NULLIF(trim(p_schedule->>'name'), '');
  v_interval := NULLIF(p_schedule->>'intervalMinutes', '')::integer;
  v_config   := p_schedule->'config';
  v_active   := COALESCE((p_schedule->>'active')::boolean, true);

  SELECT COALESCE(array_agg(value::integer), '{}')
    INTO v_days FROM jsonb_array_elements_text(COALESCE(p_schedule->'daysOfWeek', '[]'::jsonb));
  SELECT COALESCE(array_agg(value), '{}')
    INTO v_times FROM jsonb_array_elements_text(COALESCE(p_schedule->'startTimesUtc', '[]'::jsonb));

  IF v_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.tournament_schedules WHERE id = v_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('error', 'schedule_not_found');
    END IF;
    IF NOT public.fn_can_manage_tournament_schedule(v_existing.union_id, v_existing.club_id, v_uid) THEN
      RETURN jsonb_build_object('error', 'not_authorised');
    END IF;
    v_union_id := COALESCE(v_union_id, v_existing.union_id);
    v_club_id  := COALESCE(v_club_id,  v_existing.club_id);
    v_name     := COALESCE(v_name,     v_existing.name);
    v_config   := COALESCE(v_config,   v_existing.config);
    IF p_schedule->'daysOfWeek' IS NULL THEN v_days := v_existing.days_of_week; END IF;
    IF p_schedule->'startTimesUtc' IS NULL THEN v_times := v_existing.start_times_utc; END IF;
    IF p_schedule->'intervalMinutes' IS NULL THEN v_interval := v_existing.interval_minutes; END IF;
  END IF;

  IF v_club_id IS NULL THEN
    RETURN jsonb_build_object('error', 'club_id_required');
  END IF;
  IF v_name IS NULL THEN
    RETURN jsonb_build_object('error', 'name_required');
  END IF;
  IF v_config IS NULL OR jsonb_typeof(v_config) <> 'object' THEN
    RETURN jsonb_build_object('error', 'config_must_be_object');
  END IF;
  IF array_length(v_days, 1) IS NULL THEN
    RETURN jsonb_build_object('error', 'days_of_week_required');
  END IF;
  FOREACH v_d IN ARRAY v_days LOOP
    IF v_d < 0 OR v_d > 6 THEN
      RETURN jsonb_build_object('error', 'days_of_week_out_of_range', 'detail', v_d);
    END IF;
  END LOOP;
  FOREACH v_tm IN ARRAY v_times LOOP
    IF v_tm !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN
      RETURN jsonb_build_object('error', 'start_time_format_invalid', 'detail', v_tm);
    END IF;
  END LOOP;
  IF array_length(v_times, 1) IS NULL AND v_interval IS NULL THEN
    RETURN jsonb_build_object('error', 'start_times_or_interval_required');
  END IF;
  IF v_interval IS NOT NULL AND (v_interval < 5 OR v_interval > 1440) THEN
    RETURN jsonb_build_object('error', 'interval_minutes_out_of_range');
  END IF;

  IF v_id IS NULL THEN
    IF NOT public.fn_can_manage_tournament_schedule(v_union_id, v_club_id, v_uid) THEN
      RETURN jsonb_build_object('error', 'not_authorised');
    END IF;
    INSERT INTO public.tournament_schedules
      (union_id, club_id, name, description, active, days_of_week,
       start_times_utc, interval_minutes, config, created_by)
    VALUES
      (v_union_id, v_club_id, v_name, p_schedule->>'description', v_active, v_days,
       v_times, v_interval, v_config, v_uid)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.tournament_schedules
       SET union_id         = v_union_id,
           club_id          = v_club_id,
           name             = v_name,
           description      = COALESCE(p_schedule->>'description', description),
           active           = v_active,
           days_of_week     = v_days,
           start_times_utc  = v_times,
           interval_minutes = v_interval,
           config           = v_config,
           updated_at       = now()
     WHERE id = v_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'schedule_id', v_id);
END; $_$;


ALTER FUNCTION public.fn_upsert_tournament_schedule(p_schedule jsonb) OWNER TO postgres;

--
-- Name: fn_url_encode_segment(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_url_encode_segment(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
    SELECT CASE WHEN p IS NULL THEN NULL ELSE COALESCE((
        SELECT string_agg(
            CASE WHEN s.c ~ '^[A-Za-z0-9._~-]$' THEN s.c
                 ELSE (SELECT string_agg('%' || upper(lpad(to_hex(get_byte(convert_to(s.c,'UTF8'), i)), 2, '0')), '')
                       FROM generate_series(0, octet_length(convert_to(s.c,'UTF8')) - 1) AS i)
            END, '' ORDER BY s.ord)
        FROM regexp_split_to_table(p, '') WITH ORDINALITY AS s(c, ord)
    ), '') END;
$_$;


ALTER FUNCTION public.fn_url_encode_segment(p text) OWNER TO postgres;

--
-- Name: FUNCTION fn_url_encode_segment(p text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_url_encode_segment(p text) IS 'Percent-encode one URL path segment (RFC 3986 unreserved kept). Used by fn_notification_action_url because 26% of usernames contain spaces, apostrophes, @ or non-ASCII.';


--
-- Name: fn_use_throwable(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_use_throwable(p_throwable_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
  END IF;

  RETURN public.fn_use_throwable_v2(p_throwable_id, gen_random_uuid());
END;
$$;


ALTER FUNCTION public.fn_use_throwable(p_throwable_id text) OWNER TO postgres;

--
-- Name: FUNCTION fn_use_throwable(p_throwable_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_use_throwable(p_throwable_id text) IS 'Atomic throwable use: VIP free allowance (500/UTC-month, advisory-locked against races) or a 1-diamond charge and the usage record in one transaction. Replaces the client check-then-act flow.';


--
-- Name: fn_use_throwable_v2(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_use_throwable_v2(p_throwable_id text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid         uuid := auth.uid();
  v_vip         boolean;
  v_lifetime    boolean;
  v_used        integer;
  v_free        constant integer := 500;
  v_member_free constant integer := 30;
  v_limit       integer;
  v_credit      uuid;
  v_left        integer;
  v_res         jsonb;
  v_result      jsonb;
  v_cached_id   text;
  v_cached      jsonb;
  v_month_start timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication Required');
  END IF;
  IF p_throwable_id IS NULL OR length(p_throwable_id) = 0 OR length(p_throwable_id) > 64 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid Throwable');
  END IF;
  IF p_request_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Secure Request Id Required');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('throwable:request:' || v_uid::text || ':' || p_request_id::text, 0)
  );

  SELECT r.throwable_id, r.result
    INTO v_cached_id, v_cached
    FROM public.throwable_use_receipts r
   WHERE r.user_id = v_uid
     AND r.request_id = p_request_id;

  IF v_cached IS NOT NULL THEN
    IF v_cached_id IS DISTINCT FROM p_throwable_id THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Request Id Already Used For Another Throwable'
      );
    END IF;
    RETURN v_cached || jsonb_build_object(
      'diamonds_spent', 0,
      'original_diamonds_spent',
        COALESCE(
          (v_cached->>'original_diamonds_spent')::integer,
          (v_cached->>'diamonds_spent')::integer,
          0
        ),
      'idempotent', true,
      'consumed', false
    );
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('throwable:' || v_uid::text, 0));

  v_month_start := date_trunc('month', clock_timestamp() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';

  SELECT
    COALESCE(p.is_vip, false)
      AND (p.vip_tier IS NOT DISTINCT FROM 'lifetime' OR p.vip_expires_at IS NULL OR p.vip_expires_at > clock_timestamp()),
    COALESCE(p.is_vip, false) AND p.vip_tier IS NOT DISTINCT FROM 'lifetime'
    INTO v_vip, v_lifetime
    FROM public.profiles p
   WHERE p.id = v_uid;

  IF v_vip IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unknown User');
  END IF;

  -- Unlimited means no inventory meter, not unlimited write throughput. The
  -- visible selector already has the same 1.5-second animation cooldown; pin it
  -- here under the per-account advisory lock so a crafted browser client cannot
  -- turn the Lifetime audit trail into an unbounded database-write endpoint.
  IF EXISTS (
    SELECT 1
      FROM public.throw_usage tu
     WHERE tu.user_id = v_uid
       AND tu.created_at > clock_timestamp() - interval '1500 milliseconds'
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Please Wait Before Sending Another Throwable',
      'code', 'RATE_LIMITED',
      'retry_after_ms', 1500
    );
  END IF;

  IF v_lifetime THEN
    INSERT INTO public.throw_usage (user_id, throwable_id, paid_diamonds, created_at)
    VALUES (v_uid, p_throwable_id, false, clock_timestamp());

    v_result := jsonb_build_object(
      'success', true,
      'paid', false,
      'source', 'lifetime_vip',
      'unlimited', true,
      'diamonds_spent', 0,
      'idempotent', false,
      'consumed', true
    );
    INSERT INTO public.throwable_use_receipts (user_id, request_id, throwable_id, result)
    VALUES (v_uid, p_request_id, p_throwable_id, v_result);
    RETURN v_result;
  END IF;

  v_limit := CASE WHEN v_vip THEN v_free ELSE v_member_free END;
  IF v_limit > 0 THEN
    SELECT count(*) INTO v_used
      FROM public.throw_usage
     WHERE user_id = v_uid
       AND created_at >= v_month_start;

    IF v_used < v_limit THEN
      INSERT INTO public.throw_usage (user_id, throwable_id, paid_diamonds, created_at)
      VALUES (v_uid, p_throwable_id, false, clock_timestamp());

      v_result := jsonb_build_object(
        'success', true,
        'paid', false,
        'source', CASE WHEN v_vip THEN 'vip_monthly' ELSE 'member_monthly' END,
        'free_remaining', v_limit - v_used - 1,
        'diamonds_spent', 0,
        'idempotent', false,
        'consumed', true
      );
      INSERT INTO public.throwable_use_receipts (user_id, request_id, throwable_id, result)
      VALUES (v_uid, p_request_id, p_throwable_id, v_result);
      RETURN v_result;
    END IF;
  END IF;

  LOOP
    SELECT id INTO v_credit
      FROM public.feature_purchases
     WHERE user_id = v_uid
       AND feature = 'throwable'
       AND COALESCE(uses_remaining, 0) > 0
       AND (expires_at IS NULL OR expires_at > clock_timestamp())
     ORDER BY created_at ASC
     LIMIT 1
     FOR UPDATE;

    EXIT WHEN v_credit IS NULL;
    -- A selected credit may expire while its row lock is awaited. Recheck
    -- at consumption, then select the next valid pack before charging diamonds.
    UPDATE public.feature_purchases
       SET uses_remaining = uses_remaining - 1
     WHERE id = v_credit
       AND user_id = v_uid
       AND COALESCE(uses_remaining, 0) > 0
       AND (expires_at IS NULL OR expires_at > clock_timestamp())
     RETURNING uses_remaining INTO v_left;
    EXIT WHEN FOUND;
  END LOOP;

  IF v_credit IS NOT NULL THEN

    INSERT INTO public.throw_usage (user_id, throwable_id, paid_diamonds, created_at)
    VALUES (v_uid, p_throwable_id, false, clock_timestamp());

    v_result := jsonb_build_object(
      'success', true,
      'paid', false,
      'source', 'purchased',
      'from_pack', true,
      'pack_remaining', v_left,
      'diamonds_spent', 0,
      'idempotent', false,
      'consumed', true
    );
    INSERT INTO public.throwable_use_receipts (user_id, request_id, throwable_id, result)
    VALUES (v_uid, p_request_id, p_throwable_id, v_result);
    RETURN v_result;
  END IF;

  v_res := public.deduct_diamonds(
    v_uid,
    1,
    'Throwable: ' || p_throwable_id,
    'throwable'
  );

  IF COALESCE((v_res->>'success')::boolean, false) IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', COALESCE(v_res->>'error', 'Diamond Charge Failed')
    );
  END IF;

  INSERT INTO public.throw_usage (user_id, throwable_id, paid_diamonds, created_at)
  VALUES (v_uid, p_throwable_id, true, clock_timestamp());

  v_result := jsonb_build_object(
    'success', true,
    'paid', true,
    'source', 'diamonds',
    'diamonds_spent', 1,
    'balance', (v_res->>'balance')::numeric,
    'idempotent', false,
    'consumed', true
  );
  INSERT INTO public.throwable_use_receipts (user_id, request_id, throwable_id, result)
  VALUES (v_uid, p_request_id, p_throwable_id, v_result);
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_use_throwable_v2(p_throwable_id text, p_request_id uuid) OWNER TO postgres;

