--
-- Name: fn_valid_prize_table(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_valid_prize_table(p jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  SELECT jsonb_typeof(p) = 'array'
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(p) e
        WHERE jsonb_typeof(e) <> 'object'
           OR (e->>'rank')   IS NULL OR (e->>'amount') IS NULL
           OR (e->>'rank')   !~ '^[0-9]+$'
           OR (e->>'amount') !~ '^[0-9]+(\.[0-9]+)?$'
           OR (e->>'rank')::int < 1)
     AND (SELECT count(DISTINCT (e->>'rank')::int) = count(*)
            FROM jsonb_array_elements(p) e);
$_$;


ALTER FUNCTION public.fn_valid_prize_table(p jsonb) OWNER TO postgres;

--
-- Name: fn_validate_home_game_timezone(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_validate_home_game_timezone() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.timezone IS NOT NULL AND NEW.timezone <> '' THEN
    IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = NEW.timezone) THEN
      RAISE EXCEPTION 'INVALID_TIMEZONE'
        USING HINT = 'timezone "' || NEW.timezone || '" is not a recognized IANA timezone name';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_validate_home_game_timezone() OWNER TO postgres;

--
-- Name: fn_validate_home_group_timezone(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_validate_home_group_timezone() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.timezone IS NULL OR NEW.timezone = '' THEN
    NEW.timezone := 'America/New_York';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = NEW.timezone) THEN
    RAISE EXCEPTION 'INVALID_TIMEZONE'
      USING HINT = 'timezone "' || NEW.timezone || '" is not a recognized IANA timezone name';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_validate_home_group_timezone() OWNER TO postgres;

--
-- Name: fn_validate_home_url_fields(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_validate_home_url_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_arr_element text;
BEGIN
    -- Service role bypass
    IF auth.role() = 'service_role' THEN
        RETURN NEW;
    END IF;

    -- Route by table
    IF TG_TABLE_NAME = 'commander_home_games' THEN
        IF TG_OP = 'INSERT'
           OR NEW.cover_photo_url IS DISTINCT FROM OLD.cover_photo_url THEN
            IF public.fn_is_unsafe_url(NEW.cover_photo_url) THEN
                RAISE EXCEPTION 'unsafe cover_photo_url rejected: %', NEW.cover_photo_url
                      USING ERRCODE = '22023';
            END IF;
        END IF;

    ELSIF TG_TABLE_NAME = 'commander_home_game_photos' THEN
        IF TG_OP = 'INSERT'
           OR NEW.photo_url IS DISTINCT FROM OLD.photo_url THEN
            IF public.fn_is_unsafe_url(NEW.photo_url) THEN
                RAISE EXCEPTION 'unsafe photo_url rejected: %', NEW.photo_url
                      USING ERRCODE = '22023';
            END IF;
        END IF;

    ELSIF TG_TABLE_NAME = 'commander_home_groups' THEN
        IF TG_OP = 'INSERT'
           OR NEW.cover_photo_url IS DISTINCT FROM OLD.cover_photo_url THEN
            IF public.fn_is_unsafe_url(NEW.cover_photo_url) THEN
                RAISE EXCEPTION 'unsafe cover_photo_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
        IF TG_OP = 'INSERT'
           OR NEW.profile_photo_url IS DISTINCT FROM OLD.profile_photo_url THEN
            IF public.fn_is_unsafe_url(NEW.profile_photo_url) THEN
                RAISE EXCEPTION 'unsafe profile_photo_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
        IF TG_OP = 'INSERT'
           OR NEW.qr_code_url IS DISTINCT FROM OLD.qr_code_url THEN
            IF public.fn_is_unsafe_url(NEW.qr_code_url) THEN
                RAISE EXCEPTION 'unsafe qr_code_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;

    ELSIF TG_TABLE_NAME = 'commander_home_posts' THEN
        IF TG_OP = 'INSERT'
           OR NEW.video_url IS DISTINCT FROM OLD.video_url THEN
            IF public.fn_is_unsafe_url(NEW.video_url) THEN
                RAISE EXCEPTION 'unsafe video_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
        -- image_urls is text[] - iterate on change.
        IF TG_OP = 'INSERT'
           OR NEW.image_urls IS DISTINCT FROM OLD.image_urls THEN
            IF NEW.image_urls IS NOT NULL THEN
                IF array_length(NEW.image_urls, 1) > 20 THEN
                    RAISE EXCEPTION 'too many image_urls (max 20)'
                          USING ERRCODE = '22023';
                END IF;
                FOREACH v_arr_element IN ARRAY NEW.image_urls LOOP
                    IF public.fn_is_unsafe_url(v_arr_element) THEN
                        RAISE EXCEPTION 'unsafe image_urls element rejected'
                              USING ERRCODE = '22023';
                    END IF;
                END LOOP;
            END IF;
        END IF;

    ELSIF TG_TABLE_NAME = 'profiles' THEN
        IF TG_OP = 'INSERT'
           OR NEW.avatar_url IS DISTINCT FROM OLD.avatar_url THEN
            IF public.fn_is_unsafe_url(NEW.avatar_url) THEN
                RAISE EXCEPTION 'unsafe avatar_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
        IF TG_OP = 'INSERT'
           OR NEW.cover_photo_url IS DISTINCT FROM OLD.cover_photo_url THEN
            IF public.fn_is_unsafe_url(NEW.cover_photo_url) THEN
                RAISE EXCEPTION 'unsafe cover_photo_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
        IF TG_OP = 'INSERT'
           OR NEW.hendon_url IS DISTINCT FROM OLD.hendon_url THEN
            IF public.fn_is_unsafe_url(NEW.hendon_url) THEN
                RAISE EXCEPTION 'unsafe hendon_url rejected'
                      USING ERRCODE = '22023';
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_validate_home_url_fields() OWNER TO postgres;

--
-- Name: fn_validate_training_answer_v2(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_validate_training_answer_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  attempt_row public.training_attempts%ROWTYPE;
  hand_row public.training_attempt_hands%ROWTYPE;
  snapshot_row public.training_question_snapshots%ROWTYPE;
  exact_replay_exists boolean := false;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.attempt_id IS NULL AND NEW.attempt_id IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_LEGACY_ANSWER_CANNOT_BE_REBOUND';
    END IF;
    IF OLD.attempt_id IS NOT NULL AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_ANSWER_IMMUTABLE';
    END IF;
    RETURN NEW;
  END IF;

  -- Nullable v2 columns preserve legacy rows during the staged API rollout.
  IF NEW.attempt_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Let an exact receipt replay reach the unique constraint even after the
  -- attempt completed; the API then returns the already-persisted answer.
  SELECT EXISTS (
    SELECT 1
    FROM public.training_answers existing
    WHERE existing.user_id = NEW.user_id
      AND existing.submission_id = NEW.submission_id
      AND existing.attempt_id = NEW.attempt_id
      AND existing.hand_ordinal = NEW.hand_ordinal
      AND existing.decision_ordinal = NEW.decision_ordinal
      AND existing.snapshot_key = NEW.snapshot_key
      AND existing.question_id = NEW.question_id
      AND lower(existing.answer_id) = lower(NEW.answer_id)
  ) INTO exact_replay_exists;
  IF exact_replay_exists THEN
    RETURN NEW;
  END IF;

  SELECT * INTO attempt_row
  FROM public.training_attempts
  WHERE id = NEW.attempt_id
  FOR KEY SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'TRAINING_ATTEMPT_NOT_FOUND';
  END IF;
  IF attempt_row.status <> 'open' OR attempt_row.expires_at <= now() THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_NOT_OPEN';
  END IF;
  IF NEW.user_id <> attempt_row.user_id
     OR NEW.game_id <> attempt_row.game_id
     OR NEW.level <> attempt_row.level
     OR NEW.session_id <> attempt_row.client_nonce THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_ANSWER_OWNER_MISMATCH';
  END IF;
  IF coalesce(NEW.evidence_metadata ->> 'difficultyMode', '') <> attempt_row.difficulty THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_DIFFICULTY_MISMATCH';
  END IF;

  SELECT * INTO hand_row
  FROM public.training_attempt_hands
  WHERE attempt_id = NEW.attempt_id
    AND hand_ordinal = NEW.hand_ordinal;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_HAND_MISMATCH';
  END IF;
  IF NEW.decision_ordinal = 1 AND hand_row.snapshot_key <> NEW.snapshot_key THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_INITIAL_SNAPSHOT_MISMATCH';
  END IF;
  IF NEW.decision_ordinal > 1 AND NOT EXISTS (
    SELECT 1
    FROM public.training_answers prior
    WHERE prior.attempt_id = NEW.attempt_id
      AND prior.hand_ordinal = NEW.hand_ordinal
      AND prior.decision_ordinal = NEW.decision_ordinal - 1
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_DECISION_SEQUENCE_GAP';
  END IF;

  SELECT * INTO snapshot_row
  FROM public.training_question_snapshots
  WHERE snapshot_key = NEW.snapshot_key;
  IF NOT FOUND
     OR snapshot_row.game_id <> NEW.game_id
     OR snapshot_row.level <> NEW.level
     OR NOT (
       snapshot_row.source_question_id = NEW.question_id
       OR snapshot_row.question_data ->> 'id' = NEW.question_id
     ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_QUESTION_MISMATCH';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_validate_training_answer_v2() OWNER TO postgres;

--
-- Name: fn_validate_training_attempt_hand_v2(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_validate_training_attempt_hand_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  attempt_row public.training_attempts%ROWTYPE;
  snapshot_row public.training_question_snapshots%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.attempt_id IS DISTINCT FROM OLD.attempt_id
       OR NEW.hand_ordinal IS DISTINCT FROM OLD.hand_ordinal
       OR NEW.snapshot_key IS DISTINCT FROM OLD.snapshot_key
       OR NEW.scoring_rule IS DISTINCT FROM OLD.scoring_rule
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'TRAINING_ATTEMPT_HAND_IDENTITY_IMMUTABLE';
    END IF;
    IF OLD.status = 'scored'
       AND (
         NEW.status IS DISTINCT FROM OLD.status
         OR NEW.result_is_correct IS DISTINCT FROM OLD.result_is_correct
         OR NEW.scored_at IS DISTINCT FROM OLD.scored_at
       ) THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'TRAINING_ATTEMPT_HAND_RESULT_IMMUTABLE';
    END IF;
  END IF;

  SELECT * INTO attempt_row
  FROM public.training_attempts
  WHERE id = NEW.attempt_id
  FOR KEY SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'TRAINING_ATTEMPT_NOT_FOUND';
  END IF;
  IF attempt_row.status <> 'open' OR attempt_row.expires_at <= now() THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_NOT_OPEN';
  END IF;
  IF NEW.hand_ordinal > attempt_row.expected_hands THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_HAND_OUT_OF_RANGE';
  END IF;

  SELECT * INTO snapshot_row
  FROM public.training_question_snapshots
  WHERE snapshot_key = NEW.snapshot_key;

  IF NOT FOUND
     OR snapshot_row.game_id <> attempt_row.game_id
     OR snapshot_row.level <> attempt_row.level THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TRAINING_ATTEMPT_SNAPSHOT_MISMATCH';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_validate_training_attempt_hand_v2() OWNER TO postgres;

--
-- Name: fn_verify_privileged_lock(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_verify_privileged_lock() RETURNS TABLE(function_signature text, anon_exec boolean, public_exec boolean, missing boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT l.function_signature,
         CASE WHEN to_regprocedure(l.function_signature) IS NULL THEN NULL
              ELSE has_function_privilege('anon', to_regprocedure(l.function_signature)::oid, 'EXECUTE') END,
         CASE WHEN to_regprocedure(l.function_signature) IS NULL THEN NULL
              ELSE has_function_privilege('public', to_regprocedure(l.function_signature)::oid, 'EXECUTE') END,
         to_regprocedure(l.function_signature) IS NULL
    FROM public.privileged_function_lock l
   WHERE to_regprocedure(l.function_signature) IS NULL
      OR has_function_privilege('anon',   to_regprocedure(l.function_signature)::oid, 'EXECUTE')
      OR has_function_privilege('public', to_regprocedure(l.function_signature)::oid, 'EXECUTE')
   ORDER BY 1;
$$;


ALTER FUNCTION public.fn_verify_privileged_lock() OWNER TO postgres;

--
-- Name: FUNCTION fn_verify_privileged_lock(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_verify_privileged_lock() IS 'Detective check: returns zero rows when every reviewed privileged function is still anon/PUBLIC denied. Non-zero rows = a grant regression or a dropped/renamed function.';


--
-- Name: fn_verify_staff_pin(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_verify_staff_pin(p_venue_id text, p_pin text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT s.id
    FROM public.commander_staff s
   WHERE s.venue_id::text = p_venue_id
     AND s.is_active
     AND p_pin IS NOT NULL
     AND s.pin_hash IS NOT NULL
     AND s.pin_hash = extensions.crypt(p_pin, s.pin_hash)
   LIMIT 1;
$$;


