--
-- Name: fn_view_story(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_view_story(p_story_id uuid DEFAULT NULL::uuid, p_viewer_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text;
  v_caller_uid uuid;
  v_inserted_id uuid;
BEGIN
  IF p_story_id IS NULL OR p_viewer_id IS NULL THEN
    RETURN;
  END IF;

  v_caller_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '');
  v_caller_uid := auth.uid();

  IF v_caller_role = 'authenticated' THEN
    IF v_caller_uid IS NULL OR p_viewer_id <> v_caller_uid THEN
      RAISE WARNING 'fn_view_story: spoof attempt by % targeting %', v_caller_uid, p_viewer_id;
      RETURN;
    END IF;
  ELSIF v_caller_role = 'anon' OR v_caller_role = '' THEN
    RETURN;
  END IF;
  -- service_role: bypass

  INSERT INTO social_story_views (story_id, viewer_id, viewed_at)
  VALUES (p_story_id, p_viewer_id, now())
  ON CONFLICT (story_id, viewer_id) DO NOTHING
  RETURNING id INTO v_inserted_id;

  IF FOUND THEN
    UPDATE social_stories
    SET view_count = COALESCE(view_count, 0) + 1
    WHERE id = p_story_id;
  END IF;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_view_story failed (story=%, viewer=%): % %',
    p_story_id, p_viewer_id, SQLERRM, SQLSTATE;
END;
$$;


ALTER FUNCTION public.fn_view_story(p_story_id uuid, p_viewer_id uuid) OWNER TO postgres;

--
-- Name: fn_vip_points_move_only_with_a_leg(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_vip_points_move_only_with_a_leg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_writer text := NULLIF(current_setting('app.vip_points_writer', true), '');
BEGIN
  IF NEW.current_points < 0 THEN
    RAISE EXCEPTION 'vip_points.current_points cannot go negative (% for %)', NEW.current_points, NEW.user_id
      USING ERRCODE = 'P0403';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF (NEW.current_points <> 0 OR NEW.lifetime_points <> 0) AND v_writer IS NULL THEN
      RAISE EXCEPTION 'a vip_points row is born at zero unless a ledger writer (fn_award_vip_credit) creates it with its first leg'
        USING ERRCODE = 'P0403';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.lifetime_points < OLD.lifetime_points THEN
    RAISE EXCEPTION 'vip_points.lifetime_points cannot shrink (% -> % for %)', OLD.lifetime_points, NEW.lifetime_points, NEW.user_id
      USING ERRCODE = 'P0403';
  END IF;
  IF (NEW.current_points IS DISTINCT FROM OLD.current_points OR NEW.lifetime_points IS DISTINCT FROM OLD.lifetime_points)
     AND v_writer IS NULL THEN
    RAISE EXCEPTION
      'vip_points for % moves only through fn_award_vip_credit or fn_redeem_vip_points, which write the leg in the same transaction. A balance with no leg is the defect this guard exists for.',
      NEW.user_id USING ERRCODE = 'P0403';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_vip_points_move_only_with_a_leg() OWNER TO postgres;

--
-- Name: fn_wallet_claim_back(uuid, uuid, numeric, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wallet_claim_back(p_club_id uuid, p_from_user_id uuid, p_amount numeric, p_target_wallet text, p_source_wallet text DEFAULT 'player_wallet'::text, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor        uuid := auth.uid();
  v_actor_role   text;
  v_from_role    text;
  v_amount       numeric := round(p_amount, 2);
  v_source       text := lower(coalesce(p_source_wallet, 'player_wallet'));
  v_target       text := lower(coalesce(p_target_wallet, 'club_bank'));
  v_from_agent   uuid;
  v_from_before  numeric;
  v_from_after   numeric;
  v_target_after numeric;
  v_first uuid;
  v_second uuid;
  v_union uuid;
  v_min_comm numeric;
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_prior jsonb;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;
  if v_amount is null or v_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount Must Be Greater Than Zero');
  end if;
  if v_target not in ('club_bank', 'promo_wallet', 'agent_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Target Wallet');
  end if;
  if v_source not in ('agent_wallet', 'promo_wallet', 'player_wallet') then
    return jsonb_build_object('success', false, 'error', 'Unknown Source Wallet');
  end if;
  if p_from_user_id is null or p_from_user_id = v_actor then
    return jsonb_build_object('success', false, 'error', 'Invalid User');
  end if;

  v_actor_role := public.fn_club_bank_role(p_club_id);
  if v_actor_role is null or btrim(v_actor_role) = '' then
    return jsonb_build_object('success', false, 'error', 'You Are Not A Member Of This Club');
  end if;

  if v_key is not null then
    select ct.metadata into v_prior from chip_transactions ct
     where ct.metadata->>'idempotency_key' = v_key limit 1;
    if v_prior is not null then
      return jsonb_build_object('success', true,
        'balance_after', (v_prior->>'target_balance_after')::numeric, 'replayed', true);
    end if;
  end if;

  if v_target = 'club_bank' then
    if coalesce(v_actor_role, '') not in ('owner', 'co_owner', 'admin', 'super_agent') then
      return jsonb_build_object('success', false, 'error', 'Your Role Cannot Claim Back Into The Club Bank');
    end if;
    if coalesce(v_actor_role, '') = 'super_agent'
       and not public.fn_club_is_in_downline(p_club_id, v_actor, p_from_user_id) then
      return jsonb_build_object('success', false, 'error', 'Player Is Not In Your Downline');
    end if;
  elsif v_target in ('agent_wallet', 'promo_wallet') then
    if coalesce(v_actor_role, '') not in ('super_agent', 'agent', 'sub_agent', 'owner', 'co_owner', 'admin') then
      return jsonb_build_object('success', false, 'error', 'Your Role Cannot Claim Back Into An Agent Wallet');
    end if;
  end if;

  select role, agent_id into v_from_role, v_from_agent
    from club_members
   where club_id = p_club_id and user_id = p_from_user_id
     and coalesce(status, 'active') in ('active', 'approved');

  if v_from_role is null then
    return jsonb_build_object('success', false, 'error', 'User Is Not An Active Member');
  end if;

  if v_source in ('agent_wallet', 'promo_wallet')
     and v_from_role not in ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent') then
    return jsonb_build_object('success', false, 'error', 'User Does Not Have That Wallet');
  end if;

  if v_target in ('agent_wallet', 'promo_wallet') and coalesce(v_actor_role, '') in ('super_agent', 'agent', 'sub_agent') then
    if not public.fn_club_is_in_downline(p_club_id, v_actor, p_from_user_id) then
      return jsonb_build_object('success', false, 'error', 'User Is Not In Your Downline');
    end if;
  end if;

  if v_actor < p_from_user_id then
    v_first := v_actor; v_second := p_from_user_id;
  else
    v_first := p_from_user_id; v_second := v_actor;
  end if;

  perform 1 from club_members where club_id = p_club_id and user_id = v_first for update;
  perform 1 from club_members where club_id = p_club_id and user_id = v_second for update;

  if v_target = 'club_bank' then
    perform 1 from clubs where id = p_club_id for update;
  end if;

  select coalesce(uc.union_id, c.union_id) into v_union
    from clubs c left join union_clubs uc on uc.club_id = c.id
   where c.id = p_club_id limit 1;
  v_min_comm := case when v_union is null then 0
                     else public.fn_union_setting(v_union, 'min_agent_commission', 0) end;

  if v_target in ('agent_wallet', 'promo_wallet') then
    insert into agents (user_id, club_id, role, status, commission_rate, player_rakeback_rate)
      values (v_actor, p_club_id, v_actor_role, 'active', v_min_comm, 0)
      on conflict (user_id, club_id) do nothing;
  end if;

  if v_source in ('agent_wallet', 'promo_wallet') then
    insert into agents (user_id, club_id, role, status, commission_rate, player_rakeback_rate)
      values (p_from_user_id, p_club_id, v_from_role, 'active', v_min_comm, 0)
      on conflict (user_id, club_id) do nothing;
  end if;

  perform 1 from agents where club_id = p_club_id and user_id = v_first for update;
  perform 1 from agents where club_id = p_club_id and user_id = v_second for update;

  if v_source = 'player_wallet' then
    select coalesce(chip_balance, 0) into v_from_before from club_members where club_id = p_club_id and user_id = p_from_user_id;
  elsif v_source = 'agent_wallet' then
    select coalesce(agent_wallet_balance, 0) into v_from_before from agents where club_id = p_club_id and user_id = p_from_user_id;
  elsif v_source = 'promo_wallet' then
    select coalesce(promo_wallet_balance, 0) into v_from_before from agents where club_id = p_club_id and user_id = p_from_user_id;
  end if;

  if coalesce(v_from_before, 0) < v_amount then
    return jsonb_build_object('success', false, 'error', 'Insufficient Chips', 'balance', coalesce(v_from_before, 0));
  end if;

  if v_source = 'player_wallet' then
    update club_members set chip_balance = chip_balance - v_amount, updated_at = now()
     where club_id = p_club_id and user_id = p_from_user_id returning chip_balance into v_from_after;
  elsif v_source = 'agent_wallet' then
    update agents set agent_wallet_balance = agent_wallet_balance - v_amount, updated_at = now()
     where club_id = p_club_id and user_id = p_from_user_id returning agent_wallet_balance into v_from_after;
  elsif v_source = 'promo_wallet' then
    update agents set promo_wallet_balance = promo_wallet_balance - v_amount, updated_at = now()
     where club_id = p_club_id and user_id = p_from_user_id returning promo_wallet_balance into v_from_after;
  end if;

  if v_target = 'club_bank' then
    update clubs set chip_treasury = coalesce(chip_treasury, 0) + v_amount, updated_at = now()
     where id = p_club_id returning chip_treasury into v_target_after;
  elsif v_target = 'agent_wallet' then
    update agents set agent_wallet_balance = coalesce(agent_wallet_balance, 0) + v_amount, updated_at = now()
     where club_id = p_club_id and user_id = v_actor returning agent_wallet_balance into v_target_after;
  elsif v_target = 'promo_wallet' then
    update agents set promo_wallet_balance = coalesce(promo_wallet_balance, 0) + v_amount, updated_at = now()
     where club_id = p_club_id and user_id = v_actor returning promo_wallet_balance into v_target_after;
  end if;

  insert into chip_transactions (
    club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after, metadata
  ) values (
    p_club_id, p_from_user_id, v_actor, v_amount,
    case when v_target = 'club_bank' then 'club_bank_claim'
         when v_target = 'promo_wallet' then 'promo_claim'
         else 'agent_claim' end,
    p_reason,
    v_target_after,
    jsonb_build_object(
      'source_wallet', v_source,
      'target_wallet', v_target,
      'from_balance_after', v_from_after,
      'target_balance_after', v_target_after
    ) || case when v_key is null then '{}'::jsonb
              else jsonb_build_object('idempotency_key', v_key) end
  );

  return jsonb_build_object('success', true, 'balance_after', v_target_after);
exception
  when unique_violation then
    if v_key is null then
      raise;
    end if;
    select ct.metadata into v_prior from chip_transactions ct
     where ct.metadata->>'idempotency_key' = v_key limit 1;
    if v_prior is null then
      raise;
    end if;
    return jsonb_build_object('success', true,
      'balance_after', (v_prior->>'target_balance_after')::numeric, 'replayed', true);
end
$$;


ALTER FUNCTION public.fn_wallet_claim_back(p_club_id uuid, p_from_user_id uuid, p_amount numeric, p_target_wallet text, p_source_wallet text, p_reason text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: fn_wallet_type_transfer(uuid, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wallet_type_transfer(p_user_id uuid, p_from_wallet text, p_to_wallet text, p_amount numeric, p_note text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := (SELECT auth.uid());
  v_from_balance numeric;
  v_to_balance numeric;
  v_desc text;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication required');
  END IF;
  IF p_user_id IS DISTINCT FROM v_caller THEN
    RETURN jsonb_build_object('success', false, 'error', 'can only move your own funds');
  END IF;
  IF p_from_wallet NOT IN ('BUSINESS','PLAYER','PROMO')
     OR p_to_wallet NOT IN ('BUSINESS','PLAYER','PROMO') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid wallet type');
  END IF;
  IF p_from_wallet = p_to_wallet THEN
    RETURN jsonb_build_object('success', false, 'error', 'source and destination wallets are the same');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be positive');
  END IF;

  SELECT balance INTO v_from_balance
    FROM wallets WHERE user_id = p_user_id AND wallet_type = p_from_wallet
    FOR UPDATE;
  IF v_from_balance IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'source wallet not found');
  END IF;
  IF v_from_balance < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient balance', 'balance', v_from_balance);
  END IF;

  v_desc := COALESCE(NULLIF(p_note, ''), 'Internal transfer ' || p_from_wallet || ' -> ' || p_to_wallet);

  UPDATE wallets SET balance = balance - p_amount, updated_at = now()
   WHERE user_id = p_user_id AND wallet_type = p_from_wallet;

  INSERT INTO wallets (user_id, wallet_type, balance)
       VALUES (p_user_id, p_to_wallet, p_amount)
  ON CONFLICT (user_id, wallet_type)
  DO UPDATE SET balance = wallets.balance + p_amount, updated_at = now()
  RETURNING balance INTO v_to_balance;

  -- category must be one of the wallet_transactions CHECK values; 'transfer' is canonical
  INSERT INTO wallet_transactions (user_id, wallet_type, type, amount, category, description, balance_after)
  VALUES
    (p_user_id, p_from_wallet, 'debit',  p_amount, 'transfer', v_desc, v_from_balance - p_amount),
    (p_user_id, p_to_wallet,   'credit', p_amount, 'transfer', v_desc, v_to_balance);

  RETURN jsonb_build_object('success', true, 'from', p_from_wallet, 'to', p_to_wallet,
                            'amount', p_amount, 'from_balance', v_from_balance - p_amount,
                            'to_balance', v_to_balance);
END;
$$;


ALTER FUNCTION public.fn_wallet_type_transfer(p_user_id uuid, p_from_wallet text, p_to_wallet text, p_amount numeric, p_note text) OWNER TO postgres;

--
-- Name: fn_warn_promotion_has_no_payout_path(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_warn_promotion_has_no_payout_path() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Only the types that have no settler. deposit_match and refer_friend DO
  -- have a payout path (PromotionService.applyDepositBonus / processReferral),
  -- and tournament-backed types are paid by the engine.
  IF COALESCE(NEW.type, '') NOT IN ('leaderboard', 'high_hand', 'rake_race') THEN
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.status, '') <> 'active' OR COALESCE(NEW.prize_pool, 0) <= 0 THEN
    RETURN NEW;
  END IF;

  INSERT INTO financial_alerts (severity, source, message, context)
  SELECT 'warning', 'promotions.no_payout_path',
         'A promotion is advertising a prize pool that nothing can pay out',
         jsonb_build_object(
           'promotion_id', NEW.id,
           'club_id', NEW.club_id,
           'name', NEW.name,
           'type', NEW.type,
           'prize_pool', NEW.prize_pool,
           'detail', 'promotion_leaderboards.prize is read and rendered but nothing writes it; '
                  || 'updateLeaderboardScore writes score only and recalculate_leaderboard_ranks '
                  || 'writes rank only, and there is no high-hand scorer, rake-race settler or '
                  || 'leaderboard payout job. Players can enter and qualify; nobody can be paid.')
   WHERE NOT EXISTS (
     SELECT 1 FROM financial_alerts
      WHERE source = 'promotions.no_payout_path'
        AND resolved IS NOT TRUE
        AND context->>'promotion_id' = NEW.id::text);

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_warn_promotion_has_no_payout_path() OWNER TO postgres;

--
-- Name: fn_welcome_new_approved_member(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_welcome_new_approved_member() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group RECORD;
    v_member_name text;
    v_welcome_exists boolean;
BEGIN
    -- Only fire for transitions into 'approved'
    IF TG_OP = 'INSERT' AND NEW.status <> 'approved' THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND (OLD.status = 'approved' OR NEW.status <> 'approved') THEN
      RETURN NEW;
    END IF;

    -- Entire block is defensive: if ANYTHING goes wrong generating the
    -- welcome post, we swallow the error and return NEW so the underlying
    -- member approval still commits. Bug #8 would have become invisible
    -- with this shape regardless of the column existing.
    BEGIN
      SELECT * INTO v_group FROM commander_home_groups WHERE id = NEW.group_id;
      IF v_group.owner_id = NEW.user_id THEN RETURN NEW; END IF;

      SELECT COALESCE(display_name, full_name, username, 'a new member') INTO v_member_name
        FROM profiles WHERE id = NEW.user_id;

      -- Dedup: don't post twice for same user in same group
      SELECT EXISTS(
        SELECT 1 FROM commander_home_posts
          WHERE group_id = NEW.group_id
            AND post_type = 'announcement'
            AND data->>'welcome_user_id' = NEW.user_id::text
      ) INTO v_welcome_exists;
      IF v_welcome_exists THEN RETURN NEW; END IF;

      INSERT INTO commander_home_posts (
        group_id, author_id, post_type, visible_to,
        content, data, is_published, is_pinned
      ) VALUES (
        NEW.group_id, v_group.owner_id, 'announcement', 'members',
        'Everyone Welcome ' || v_member_name || ' To ' || v_group.name || '!',
        jsonb_build_object('welcome_user_id', NEW.user_id, 'auto_generated', true),
        true, false
      );
    EXCEPTION
      WHEN OTHERS THEN
        -- Log but do not propagate - approval is the important event
        RAISE WARNING 'fn_welcome_new_approved_member swallowed error for '
          'group=% user=%: % (%)',
          NEW.group_id, NEW.user_id, SQLERRM, SQLSTATE;
    END;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_welcome_new_approved_member() OWNER TO postgres;

--
-- Name: FUNCTION fn_welcome_new_approved_member(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_welcome_new_approved_member() IS 'Phase 40: fires when a non-owner member''s status becomes approved. Posts a welcome announcement in the group. Entire work is wrapped in EXCEPTION so a failure NEVER blocks member approval — welcome posts are nice-to-have, approvals are critical-path.';


--
-- Name: fn_wheel_activate_segments(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_activate_segments(p_version integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a record;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_ca_caller_is_management() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only Platform Management Activates A Prize Table');
  END IF;
  SELECT x.* INTO a FROM public.fn_wheel_segments_audit(p_version) x;
  IF a.weight_total IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Prize Table Does Not Exist');
  END IF;
  IF a.weight_total <> 100000 THEN
    RETURN jsonb_build_object('ok', false, 'error', format('Weights Must Sum To 100,000, Not %s', a.weight_total), 'audit', to_jsonb(a));
  END IF;
  IF a.spec_rtp <> 0.800000 THEN
    RETURN jsonb_build_object('ok', false, 'error', format('Return To Player Must Be Exactly 80 Percent, Not %s', a.spec_rtp), 'audit', to_jsonb(a));
  END IF;
  UPDATE public.wheel_segment_versions
     SET spec_rtp = a.spec_rtp, chip_share = a.chip_share, diamond_share = a.diamond_share,
         house_share = a.house_share, sd_chips = a.sd_chips, activated_at = COALESCE(activated_at, now())
   WHERE version = p_version;
  RETURN jsonb_build_object('ok', true, 'version', p_version, 'audit', to_jsonb(a));
END $$;


ALTER FUNCTION public.fn_wheel_activate_segments(p_version integer) OWNER TO postgres;

--
-- Name: fn_wheel_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NULLIF(current_setting('app.ledger_maintenance', true), '') IS NOT NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  RAISE EXCEPTION '% is append-only: a spin is a fact and is never edited or deleted', TG_TABLE_NAME
    USING ERRCODE = 'integrity_constraint_violation';
END $$;


ALTER FUNCTION public.fn_wheel_append_only() OWNER TO postgres;

--
-- Name: fn_wheel_can_operate(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_can_operate(p_host_id uuid, p_host_kind text, p_user uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_user IS NULL THEN RETURN false; END IF;
  IF COALESCE(auth.role(), '') = 'service_role' THEN RETURN true; END IF;
  IF public.fn_ca_caller_is_management() THEN RETURN true; END IF;
  IF p_host_kind = 'union' THEN
    RETURN public.fn_union_can_manage_wallets(p_host_id, p_user);
  END IF;
  RETURN EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = p_host_id AND c.owner_id = p_user)
      OR EXISTS (SELECT 1 FROM public.club_members cm
                  WHERE cm.club_id = p_host_id AND cm.user_id = p_user
                    AND cm.role IN ('owner', 'co_owner', 'admin')
                    AND COALESCE(cm.status, 'active') IN ('active', 'approved'));
END $$;


ALTER FUNCTION public.fn_wheel_can_operate(p_host_id uuid, p_host_kind text, p_user uuid) OWNER TO postgres;

--
-- Name: fn_wheel_commit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_commit() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_seed text;
  v_hash text;
  v_id uuid;
  v_exp timestamptz;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In To Spin');
  END IF;
  -- One open commit per player: a fresh one replaces any unspent older ones,
  -- so a stale hash on a stale tab can never be spun.
  DELETE FROM public.wheel_seed_commits WHERE user_id = v_user AND consumed_by IS NULL;
  v_seed := encode(extensions.gen_random_bytes(32), 'hex');
  v_hash := encode(extensions.digest(v_seed, 'sha256'), 'hex');
  INSERT INTO public.wheel_seed_commits (user_id, server_seed, server_seed_hash)
  VALUES (v_user, v_seed, v_hash) RETURNING id, expires_at INTO v_id, v_exp;
  RETURN jsonb_build_object('ok', true, 'commit_id', v_id, 'server_seed_hash', v_hash, 'expires_at', v_exp);
END $$;


ALTER FUNCTION public.fn_wheel_commit() OWNER TO postgres;

