CREATE FUNCTION public.get_active_hand_snapshot(p_table_id uuid) RETURNS TABLE(hand_number integer, state_json jsonb, config_json jsonb, dealer_seat integer, players_json jsonb, stage text, updated_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    hss.hand_number,
    hss.state_json,
    hss.config_json,
    hss.dealer_seat,
    hss.players_json,
    hss.stage,
    hss.updated_at
  FROM hand_state_snapshots hss
  WHERE hss.table_id = p_table_id
    AND hss.is_complete = FALSE
  LIMIT 1;
END;
$$;


