--
-- Name: get_available_rotation(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_available_rotation(p_user_id uuid, p_file_id text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    used_rotations TEXT[];
BEGIN
    SELECT ARRAY_AGG(variant_hash) INTO used_rotations FROM god_mode_hand_history WHERE user_id = p_user_id AND source_file_id = p_file_id;
    IF used_rotations IS NULL OR NOT ('0' = ANY(used_rotations)) THEN RETURN '0';
    ELSIF NOT ('1' = ANY(used_rotations)) THEN RETURN '1';
    ELSIF NOT ('2' = ANY(used_rotations)) THEN RETURN '2';
    ELSIF NOT ('3' = ANY(used_rotations)) THEN RETURN '3';
    ELSE RETURN NULL;
    END IF;
END;
$$;


ALTER FUNCTION public.get_available_rotation(p_user_id uuid, p_file_id text) OWNER TO postgres;

