--
-- Name: get_commander_access_details(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_commander_access_details(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role text := coalesce(current_setting('request.jwt.claims', true)::jsonb->>'role', '');
  v_uid  uuid := auth.uid();
  v_target uuid := p_user_id;
  v_result jsonb;
begin
  if v_role <> 'service_role' then
    if v_uid is null then
      return jsonb_build_object('hasAccess', false, 'isClubOwner', false,
        'hasSubscription', false, 'isVenueStaffOwner', false, 'isVenueStaffManager', false,
        'isHomeGroupOwner', false, 'venueIds', '[]'::jsonb, 'subscriptionVenueIds', '[]'::jsonb,
        'clubs', '[]'::jsonb, 'homeGroups', '[]'::jsonb);
    end if;
    v_target := v_uid;
  end if;

  with
    cs as (
      select venue_id, role from commander_staff
      where (user_id = v_target or linked_user_id = v_target) and venue_id is not null
    ),
    sub as (select venue_id from commander_subscriptions where owner_id = v_target),
    cl  as (select id, club_id, name from clubs where owner_id = v_target),
    hg  as (select id, name from commander_home_groups where owner_id = v_target)
  select jsonb_build_object(
    'hasAccess', (exists(select 1 from cl) or exists(select 1 from sub)
                  or exists(select 1 from cs where role in ('owner','manager'))
                  or exists(select 1 from hg)),
    'isClubOwner',          exists(select 1 from cl),
    'hasSubscription',      exists(select 1 from sub),
    'isVenueStaffOwner',    exists(select 1 from cs where role = 'owner'),
    'isVenueStaffManager',  exists(select 1 from cs where role = 'manager'),
    'isHomeGroupOwner',     exists(select 1 from hg),
    'venueIds',             coalesce((select jsonb_agg(distinct venue_id) from cs), '[]'::jsonb),
    'subscriptionVenueIds', coalesce((select jsonb_agg(venue_id) from sub), '[]'::jsonb),
    'clubs',                coalesce((select jsonb_agg(jsonb_build_object('id', id, 'club_id', club_id, 'name', name)) from cl), '[]'::jsonb),
    'homeGroups',           coalesce((select jsonb_agg(jsonb_build_object('id', id, 'name', name)) from hg), '[]'::jsonb)
  ) into v_result;

  return v_result;
end
$$;


ALTER FUNCTION public.get_commander_access_details(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_commander_access_details(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_commander_access_details(p_user_id uuid) IS 'Bug-fix 2026-05-10: companion to has_commander_access() that returns full identity context. Use from /api/check-access to return a richer payload that lets the client decide where to route the user (venue dashboard, home group, register flow, etc.) instead of a binary yes/no.';


--
-- Name: get_current_settlement_period(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_current_settlement_period() RETURNS TABLE(id uuid, period_start timestamp with time zone, period_end timestamp with time zone, status text, total_rake numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_now timestamptz := now();
  v_start timestamptz;
  v_end timestamptz;
  v_union uuid;
  v_union_count int;
BEGIN
  -- Existing open period wins.
  RETURN QUERY SELECT sp.id, sp.start_at, sp.end_at, sp.status::text,
                      COALESCE(sp.total_rake_collected, 0)
    FROM settlement_periods sp WHERE sp.status = 'open'
   ORDER BY sp.start_at DESC LIMIT 1;
  IF FOUND THEN RETURN; END IF;

  -- None open: create one, WITH AN OWNER. A period belonging to nobody can
  -- never be settled and poisons the lookup above for everybody.
  SELECT count(*) INTO v_union_count FROM unions;
  IF v_union_count <> 1 THEN
    RETURN;  -- no single obvious owner; create nothing rather than guess
  END IF;
  SELECT u.id INTO v_union FROM unions u LIMIT 1;

  v_start := date_trunc('week', v_now) - interval '1 day';
  v_end := v_start + interval '7 days';
  INSERT INTO settlement_periods (id, union_id, start_at, end_at, status,
                                  total_rake_collected, period_number, year)
  VALUES (gen_random_uuid(), v_union, v_start, v_end, 'open', 0,
          EXTRACT(week FROM v_start)::int, EXTRACT(isoyear FROM v_start)::int)
  ON CONFLICT DO NOTHING;

  -- Re-select (works whether our insert won or a concurrent one did).
  RETURN QUERY SELECT sp.id, sp.start_at, sp.end_at, sp.status::text,
                      COALESCE(sp.total_rake_collected, 0)
    FROM settlement_periods sp WHERE sp.status = 'open'
   ORDER BY sp.start_at DESC LIMIT 1;
END;
$$;


ALTER FUNCTION public.get_current_settlement_period() OWNER TO postgres;

--
-- Name: get_current_settlement_period(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_current_settlement_period(p_club_id uuid) RETURNS TABLE(id uuid, club_id uuid, union_id uuid, scope text, period_number integer, year integer, period_start timestamp with time zone, period_end timestamp with time zone, status text, total_rake numeric, total_bbj numeric, total_player_winnings numeric, total_player_losses numeric, total_hands_dealt bigint, settled_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_union uuid;
BEGIN
  IF p_club_id IS NULL THEN
    RETURN;
  END IF;
  -- Any member may see which period their club is in; the money inside it is
  -- gated by the reads that return it, not by this lookup.
  IF NOT public.ca_can_view_club(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  SELECT c.union_id INTO v_union FROM clubs c WHERE c.id = p_club_id;

  RETURN QUERY
  WITH candidates AS (
    SELECT sp.*,
           CASE
             WHEN sp.club_id = p_club_id AND sp.status = 'open'                   THEN 1
             WHEN sp.club_id = p_club_id AND sp.status IN ('processing','disputed') THEN 2
             WHEN sp.club_id IS NULL AND v_union IS NOT NULL
                  AND sp.union_id = v_union AND sp.status = 'open'                THEN 3
             WHEN sp.club_id = p_club_id                                          THEN 4
           END AS rank
      FROM settlement_periods sp
     WHERE sp.club_id = p_club_id
        OR (sp.club_id IS NULL AND v_union IS NOT NULL AND sp.union_id = v_union
            AND sp.status = 'open')
  )
  SELECT c.id, c.club_id, c.union_id,
         CASE WHEN c.club_id = p_club_id THEN 'club' ELSE 'union' END,
         c.period_number, c.year, c.start_at, c.end_at, c.status::text,
         COALESCE(c.total_rake_collected, 0),
         COALESCE(c.total_bbj_contributions, 0),
         COALESCE(c.total_player_winnings, 0),
         COALESCE(c.total_player_losses, 0),
         COALESCE(c.total_hands_dealt, 0)::bigint,
         c.settled_at
    FROM candidates c
   WHERE c.rank IS NOT NULL
   ORDER BY c.rank, c.start_at DESC
   LIMIT 1;
END;
$$;


ALTER FUNCTION public.get_current_settlement_period(p_club_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_current_settlement_period(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_current_settlement_period(p_club_id uuid) IS 'The settlement period THIS club is in, with every figure the row actually carries. The no-argument overload returns the newest open period on the platform regardless of club, which is what the club settlement page used to head itself with.';


--
-- Name: get_daily_challenge(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_challenge() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_challenge RECORD;
    v_user_completed BOOLEAN;
BEGIN
    SELECT * INTO v_challenge
    FROM memory_daily_challenges
    WHERE challenge_date = CURRENT_DATE;
    
    IF NOT public.fn_caller_is_engine() THEN
        SELECT EXISTS(
            SELECT 1 FROM memory_challenge_completions
            WHERE user_id = auth.uid()
            AND challenge_id = v_challenge.id
        ) INTO v_user_completed;
    ELSE
        v_user_completed := false;
    END IF;
    
    IF v_challenge IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'No challenge for today'
        );
    END IF;
    
    RETURN jsonb_build_object(
        'success', true,
        'challenge', row_to_json(v_challenge),
        'completed', v_user_completed
    );
END;
$$;


ALTER FUNCTION public.get_daily_challenge() OWNER TO postgres;

--
-- Name: get_daily_challenge_dashboard(text, text[], text, text[], text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_challenge_dashboard(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  PERFORM public.fn_lock_daily_mission_user(v_uid);
  RETURN public.get_daily_challenge_dashboard_serialized_body(
    p_daily_key,
    p_daily_ids,
    p_weekly_key,
    p_weekly_ids,
    p_monthly_key,
    p_monthly_ids
  );
END;
$$;


ALTER FUNCTION public.get_daily_challenge_dashboard(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) OWNER TO postgres;

--
-- Name: get_daily_challenge_dashboard_serialized_body(text, text[], text, text[], text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_challenge_dashboard_serialized_body(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_missions jsonb := '[]'::jsonb;
  v_streak_receipt jsonb;
  v_streak integer := 0;
  v_total_completed bigint := 0;
  v_total_claimed bigint := 0;
  v_total_diamonds bigint := 0;
  v_vault_count bigint := 0;
  v_vault_diamonds bigint := 0;
  v_vault_items jsonb := '[]'::jsonb;
  v_diamond_balance integer := 0;
  v_previous_milestone integer := 0;
  v_next_milestone integer;
  v_milestone_reward numeric;
  v_max_milestone integer;
  v_milestone_progress numeric := 0;
  VAULT_PAGE_SIZE constant integer := 100;
  POST_CENTURY_INTERVAL constant integer := 30;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(m)), '[]'::jsonb)
    INTO v_missions
    FROM public.get_or_assign_challenges(
      p_daily_key, p_daily_ids, p_weekly_key, p_weekly_ids, p_monthly_key, p_monthly_ids
    ) m;

  v_streak_receipt := public.get_challenge_streak(v_uid);
  v_streak := COALESCE((v_streak_receipt->>'streak')::integer, 0);

  SELECT count(*) FILTER (WHERE completed),
         count(*) FILTER (WHERE claimed),
         COALESCE(sum(diamond_reward_snapshot) FILTER (WHERE claimed), 0)
    INTO v_total_completed, v_total_claimed, v_total_diamonds
    FROM public.user_daily_challenges
   WHERE user_id = v_uid;

  SELECT count(*), COALESCE(sum(diamond_reward_snapshot), 0)
    INTO v_vault_count, v_vault_diamonds
    FROM public.user_daily_challenges
   WHERE user_id = v_uid AND completed = true AND claimed = false
     AND expired_at IS NULL AND completed_at >= now() - interval '7 days';

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'id', vault.id,
             'challenge_id', vault.challenge_id,
             'assigned_date', vault.assigned_date,
             'progress', vault.progress,
             'completed', vault.completed,
             'claimed', vault.claimed,
             'completed_at', vault.completed_at,
             'name', vault.challenge_name_snapshot,
             'description', vault.challenge_description_snapshot,
             'challenge_type', vault.challenge_type_snapshot,
             'requirement', vault.requirement_snapshot,
             'chip_reward', 0,
             'diamond_reward', vault.diamond_reward_snapshot,
             'tier', vault.tier_snapshot
           )
           ORDER BY vault.completed_at DESC NULLS LAST, vault.id
         ), '[]'::jsonb)
    INTO v_vault_items
    FROM (
      SELECT *
      FROM public.user_daily_challenges
      WHERE user_id = v_uid AND completed = true AND claimed = false
        AND expired_at IS NULL AND completed_at >= now() - interval '7 days'
      ORDER BY completed_at DESC NULLS LAST, created_at DESC, id
      LIMIT VAULT_PAGE_SIZE
    ) vault;

  SELECT COALESCE(diamonds, 0) INTO v_diamond_balance FROM public.profiles WHERE id = v_uid;
  v_diamond_balance := COALESCE(v_diamond_balance, 0);

  SELECT max(days) INTO v_max_milestone FROM public.daily_challenge_milestones;

  IF v_streak >= v_max_milestone THEN
    v_previous_milestone := v_max_milestone
      + ((v_streak - v_max_milestone) / POST_CENTURY_INTERVAL) * POST_CENTURY_INTERVAL;
    v_next_milestone := v_previous_milestone + POST_CENTURY_INTERVAL;
    SELECT reward_diamonds INTO v_milestone_reward
    FROM public.daily_challenge_milestones
    WHERE days = v_max_milestone;
  ELSE
    SELECT COALESCE(max(days), 0)
      INTO v_previous_milestone
      FROM public.daily_challenge_milestones
     WHERE days <= v_streak;

    SELECT days, reward_diamonds
      INTO v_next_milestone, v_milestone_reward
      FROM public.daily_challenge_milestones
     WHERE days > v_streak
     ORDER BY days
     LIMIT 1;
  END IF;

  IF v_next_milestone > v_previous_milestone THEN
    v_milestone_progress := round(
      ((v_streak - v_previous_milestone)::numeric
        / (v_next_milestone - v_previous_milestone)::numeric) * 100,
      2
    );
  END IF;

  RETURN jsonb_build_object(
    'missions', v_missions,
    'stats', jsonb_build_object(
      'totalCompleted', v_total_completed,
      'totalClaimed', v_total_claimed,
      'currentStreak', v_streak,
      'totalChipsEarned', 0,
      'totalDiamondsEarned', v_total_diamonds,
      'milestoneStart', v_previous_milestone,
      'nextMilestone', v_next_milestone,
      -- Diamonds since 2026-09-05. The key keeps its name so the client
      -- contract is unchanged; `milestoneRewardCurrency` says so out loud.
      'milestoneReward', v_milestone_reward,
      'milestoneRewardCurrency', 'diamonds',
      'milestoneProgressPercent', v_milestone_progress,
      'daysToMilestone', GREATEST(v_next_milestone - v_streak, 0)
    ),
    'streak', v_streak_receipt,
    'diamondBalance', v_diamond_balance,
    'vault', jsonb_build_object(
      'count', v_vault_count,
      'chips', 0,
      'diamonds', v_vault_diamonds,
      'items', v_vault_items,
      'pageSize', VAULT_PAGE_SIZE,
      'hasMore', v_vault_count > VAULT_PAGE_SIZE
    ),
    'syncedAt', to_char(clock_timestamp() AT TIME ZONE 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  );
END;
$$;


ALTER FUNCTION public.get_daily_challenge_dashboard_serialized_body(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) OWNER TO postgres;

--
-- Name: FUNCTION get_daily_challenge_dashboard_serialized_body(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_daily_challenge_dashboard_serialized_body(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) IS 'Daily Missions dashboard. Reads daily_challenge_milestones.reward_diamonds (renamed from reward_chips 2026-09-05) and reports every chip figure as a literal 0 - a mission reward is diamonds.';


--
-- Name: get_daily_challenge_dashboard_v2(text, text[], text, text[], text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_challenge_dashboard_v2(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  PERFORM public.fn_lock_daily_mission_user(v_uid);
  RETURN public.get_daily_challenge_dashboard_v2_serialized_body(
    p_daily_key,
    p_daily_ids,
    p_weekly_key,
    p_weekly_ids,
    p_monthly_key,
    p_monthly_ids
  );
END;
$$;


ALTER FUNCTION public.get_daily_challenge_dashboard_v2(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) OWNER TO postgres;

--
-- Name: get_daily_challenge_dashboard_v2_serialized_body(text, text[], text, text[], text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_challenge_dashboard_v2_serialized_body(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_dashboard jsonb;
  v_revision bigint;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  PERFORM public.assign_user_challenges(p_daily_key, p_daily_ids);
  PERFORM public.assign_user_challenges(p_weekly_key, p_weekly_ids);
  PERFORM public.assign_user_challenges(p_monthly_key, p_monthly_ids);

  INSERT INTO public.daily_challenge_dashboard_revisions (user_id, revision, updated_at)
  VALUES (v_uid, 1, clock_timestamp())
  ON CONFLICT (user_id) DO NOTHING;

  PERFORM 1
  FROM public.daily_challenge_dashboard_revisions
  WHERE user_id = v_uid
  FOR UPDATE;

  v_dashboard := public.get_daily_challenge_dashboard(
    p_daily_key,
    p_daily_ids,
    p_weekly_key,
    p_weekly_ids,
    p_monthly_key,
    p_monthly_ids
  );

  SELECT revision
    INTO v_revision
    FROM public.daily_challenge_dashboard_revisions
   WHERE user_id = v_uid;

  RETURN v_dashboard || jsonb_build_object('revision', COALESCE(v_revision, 1));
END;
$$;


ALTER FUNCTION public.get_daily_challenge_dashboard_v2_serialized_body(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) OWNER TO postgres;

--
-- Name: FUNCTION get_daily_challenge_dashboard_v2_serialized_body(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_daily_challenge_dashboard_v2_serialized_body(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) IS 'Atomic Daily Missions dashboard plus its locked per-user revision cursor.';


--
-- Name: get_daily_challenge_dashboard_v3(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_challenge_dashboard_v3() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_now timestamptz := transaction_timestamp();
  v_daily_key text;
  v_weekly_key text;
  v_monthly_key text;
  v_dashboard jsonb;
  v_total_challenge_diamonds numeric := 0;
  v_total_milestone_diamonds numeric := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  v_daily_key := to_char((v_now AT TIME ZONE 'utc')::date, 'YYYY-MM-DD');
  v_weekly_key := 'W' || to_char(
    date_trunc('week', v_now AT TIME ZONE 'utc')::date,
    'YYYY-MM-DD'
  );
  v_monthly_key := 'M' || to_char(v_now AT TIME ZONE 'utc', 'YYYY-MM');

  v_dashboard := public.get_daily_challenge_dashboard_v2(
    v_daily_key,
    ARRAY[]::text[],
    v_weekly_key,
    ARRAY[]::text[],
    v_monthly_key,
    ARRAY[]::text[]
  );

  -- v2 already calculated the immutable challenge-only lifetime total in this
  -- same snapshot. Reuse it instead of rescanning the player's entire mission
  -- history on every dashboard load.
  v_total_challenge_diamonds := COALESCE(
    (v_dashboard #>> '{stats,totalDiamondsEarned}')::numeric,
    0
  );

  SELECT COALESCE(sum(amount), 0)
  INTO v_total_milestone_diamonds
  FROM public.diamond_transactions
  WHERE user_id = v_uid
    AND transaction_type = 'daily_mission_milestone';

  v_dashboard := jsonb_set(
    v_dashboard,
    '{stats,totalDiamondsEarned}',
    to_jsonb(v_total_challenge_diamonds + v_total_milestone_diamonds),
    true
  );

  RETURN v_dashboard || jsonb_build_object(
    'syncedAt', to_char(
      v_now AT TIME ZONE 'utc',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    ),
    'periodKeys', jsonb_build_object(
      'daily', v_daily_key,
      'weekly', v_weekly_key,
      'monthly', v_monthly_key
    )
  );
END;
$$;


ALTER FUNCTION public.get_daily_challenge_dashboard_v3() OWNER TO postgres;

--
-- Name: FUNCTION get_daily_challenge_dashboard_v3(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_daily_challenge_dashboard_v3() IS 'Atomic Daily Missions dashboard whose UTC period keys and syncedAt value derive from one captured transaction timestamp.';


--
-- Name: get_daily_chip_summary(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_chip_summary(p_club_id uuid, p_type text, p_days integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_result jsonb;
BEGIN
    SELECT jsonb_object_agg(day_str, total_amount) INTO v_result
    FROM (
        SELECT to_char(created_at, 'YYYY-MM-DD') AS day_str, COALESCE(SUM(amount), 0) AS total_amount
        FROM public.chip_transactions
        WHERE club_id = p_club_id AND transaction_type = p_type AND created_at >= NOW() - (p_days || ' days')::interval
        GROUP BY day_str
    ) sub;
    RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


ALTER FUNCTION public.get_daily_chip_summary(p_club_id uuid, p_type text, p_days integer) OWNER TO postgres;

--
-- Name: get_daily_commission_summary(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_commission_summary(p_club_id uuid, p_agent_id uuid, p_days integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid    uuid;
  v_result jsonb;
BEGIN
  v_uid := p_agent_id;
  IF NOT EXISTS (SELECT 1 FROM public.agent_commissions ac WHERE ac.user_id = v_uid) THEN
    SELECT a.user_id INTO v_uid FROM public.agents a WHERE a.id = p_agent_id;
    v_uid := COALESCE(v_uid, p_agent_id);
  END IF;

  SELECT jsonb_object_agg(day_str, total_amount) INTO v_result
    FROM (
      SELECT to_char(ac.created_at, 'YYYY-MM-DD') AS day_str,
             COALESCE(SUM(ac.amount), 0) AS total_amount
        FROM public.agent_commissions ac
       WHERE ac.club_id = p_club_id
         AND ac.user_id = v_uid
         AND ac.created_at >= now() - ((p_days)::text || ' days')::interval
       GROUP BY 1
    ) sub;

  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


ALTER FUNCTION public.get_daily_commission_summary(p_club_id uuid, p_agent_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: get_daily_tournaments_unified(date, text, text, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_tournaments_unified(p_target_date date, p_state text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_include_home_games boolean DEFAULT true, p_inactivity_days integer DEFAULT 45, p_limit integer DEFAULT 500) RETURNS TABLE(source text, tournament_id text, venue_id text, venue_name text, venue_slug text, venue_type text, venue_city text, venue_state text, venue_lat numeric, venue_lng numeric, tournament_name text, event_date date, start_time text, buy_in integer, rebuy_addon text, starting_stack integer, blind_levels text, level_duration_min integer, guaranteed integer, game_type text, format text, late_registration text, notes text, max_entries integer, is_special_event boolean, series_name text, source_url text, is_active boolean, is_private boolean, rsvp_yes_count integer, max_players integer, host_id uuid, home_group_id uuid, requires_rsvp boolean)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_day_of_week  text;
BEGIN
    -- Map target date to day-of-week text
    v_day_of_week := lower(to_char(p_target_date, 'FMDay'));  -- 'monday','tuesday',...

    RETURN QUERY
    -- ═══════════════════════════════════════════════════════════════════
    -- Branch 1: Venue tournaments
    -- Pull from venue_daily_tournaments + recurring day-of-week matches
    -- ═══════════════════════════════════════════════════════════════════
    SELECT 
        'venue'::text AS source,
        t.id::text AS tournament_id,
        COALESCE(pv.id::text, t.venue_id::text) AS venue_id,
        COALESCE(pv.name, t.venue_name) AS venue_name,
        pv.slug AS venue_slug,
        COALESCE(pv.venue_type, 'poker_room') AS venue_type,
        pv.city AS venue_city,
        pv.state AS venue_state,
        COALESCE(pv.lat, pv.latitude) AS venue_lat,
        COALESCE(pv.lng, pv.longitude) AS venue_lng,
        t.tournament_name,
        COALESCE(t.event_date, p_target_date) AS event_date,
        t.start_time,
        t.buy_in,
        t.rebuy_addon,
        t.starting_stack,
        t.blind_levels,
        t.level_duration_minutes,
        t.guaranteed,
        t.game_type,
        t.format,
        t.late_registration,
        t.notes,
        t.max_entries,
        COALESCE(t.is_special_event, false),
        t.series_name,
        t.source_url,
        COALESCE(t.is_active, true),
        -- Home-game-only extras default to NULL/0 for venues
        NULL::boolean AS is_private,
        NULL::integer AS rsvp_yes_count,
        NULL::integer AS max_players,
        NULL::uuid    AS host_id,
        NULL::uuid    AS home_group_id,
        false         AS requires_rsvp
      FROM venue_daily_tournaments t
      LEFT JOIN poker_venues pv ON pv.id = t.venue_id
     WHERE COALESCE(t.is_active, true) = true
       AND COALESCE(t.is_suppressed, false) = false
       AND (
           -- Recurring weekly match: day_of_week matches target date
           (t.is_recurring = true AND lower(t.day_of_week) = v_day_of_week
            AND (t.event_date IS NULL OR t.event_date <= p_target_date))
           OR
           -- Specific event_date match (one-off event)
           (t.event_date = p_target_date)
       )
       AND (p_state IS NULL OR pv.state = p_state)
       AND (p_city IS NULL OR pv.city ILIKE p_city)

    UNION ALL

    -- ═══════════════════════════════════════════════════════════════════
    -- Branch 2: Home-game tournaments (public groups only)
    -- ═══════════════════════════════════════════════════════════════════
    SELECT 
        'home_game'::text AS source,
        g.id::text AS tournament_id,
        grp.id::text AS venue_id,
        grp.name AS venue_name,
        sp.slug AS venue_slug,
        'home_game'::text AS venue_type,
        grp.city AS venue_city,
        grp.state AS venue_state,
        grp.latitude AS venue_lat,
        grp.longitude AS venue_lng,
        COALESCE(g.title, grp.name || ' Home Tournament') AS tournament_name,
        g.scheduled_date AS event_date,
        CASE WHEN g.start_time IS NOT NULL 
             THEN to_char(g.start_time, 'HH24:MI')
             ELSE NULL END AS start_time,
        (g.buyin_min)::integer AS buy_in,
        NULL::text AS rebuy_addon,
        NULL::integer AS starting_stack,
        NULL::text AS blind_levels,
        NULL::integer AS level_duration_min,
        NULL::integer AS guaranteed,
        g.game_type,
        g.format,
        NULL::text AS late_registration,
        g.description AS notes,
        g.max_players AS max_entries,
        false AS is_special_event,
        NULL::text AS series_name,
        ('/hub/home-games/' || COALESCE(sp.slug, grp.id::text) || '/games/' || g.id::text)::text AS source_url,
        true AS is_active,
        -- Home-game extras
        grp.is_private,
        COALESCE(g.rsvp_yes, 0) AS rsvp_yes_count,
        g.max_players,
        g.host_id,
        grp.id AS home_group_id,
        true AS requires_rsvp
      FROM commander_home_games g
      JOIN commander_home_groups grp ON grp.id = g.group_id
      LEFT JOIN social_pages sp ON sp.linked_entity_type='home_group' AND sp.linked_entity_id = grp.id::text
     WHERE p_include_home_games = true
       AND g.scheduled_date = p_target_date
       AND g.status IN ('scheduled','confirmed','in_progress')
       AND g.format = 'tournament'
       AND grp.is_active = true
       AND grp.is_private = false  -- only public home groups show in daily feed
       AND grp.profile_photo_url IS NOT NULL  -- Phase 17 logo enforcement
       AND grp.last_activity_at > NOW() - (p_inactivity_days || ' days')::interval
       AND (p_state IS NULL OR grp.state = p_state)
       AND (p_city IS NULL OR grp.city ILIKE p_city)

     ORDER BY start_time NULLS LAST, tournament_name
     LIMIT GREATEST(1, LEAST(p_limit, 1000));
END;
$$;


ALTER FUNCTION public.get_daily_tournaments_unified(p_target_date date, p_state text, p_city text, p_include_home_games boolean, p_inactivity_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION get_daily_tournaments_unified(p_target_date date, p_state text, p_city text, p_include_home_games boolean, p_inactivity_days integer, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_daily_tournaments_unified(p_target_date date, p_state text, p_city text, p_include_home_games boolean, p_inactivity_days integer, p_limit integer) IS 'Phase 25/A: Primary entry point for /hub/daily-tournaments page. Merges venue + home-game tournaments. Fixes P0.1/P6.1/P6.2.';


--
-- Name: get_diamond_balance(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_diamond_balance(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_balance integer;
BEGIN
  SELECT COALESCE(diamonds, 0) INTO v_balance
    FROM profiles WHERE id = p_user_id;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  RETURN v_balance;
END;
$$;


