--
-- Name: get_host_onboarding_checklist(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_host_onboarding_checklist(p_group_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group        RECORD;
    v_member_count int;
    v_game_count   int;
    v_post_count   int;
    v_invite_count int;
    v_items        jsonb := '[]'::jsonb;
    v_completed    int := 0;
    v_total        int := 0;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;
    IF v_group.owner_id <> p_caller_user_id 
       AND NOT EXISTS (SELECT 1 FROM commander_home_members 
                        WHERE group_id = p_group_id AND user_id = p_caller_user_id
                          AND role = 'admin' AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_A_HOST'; END IF;

    SELECT COUNT(*) INTO v_member_count FROM commander_home_members 
     WHERE group_id = p_group_id AND status='approved';
    SELECT COUNT(*) INTO v_game_count FROM commander_home_games WHERE group_id = p_group_id;
    SELECT COUNT(*) INTO v_post_count FROM commander_home_posts WHERE group_id = p_group_id;
    SELECT COUNT(*) INTO v_invite_count FROM commander_home_invite_tokens WHERE group_id = p_group_id;

    v_items := jsonb_build_array(
        jsonb_build_object('id','logo','label','Upload a group logo',
                           'done', v_group.profile_photo_url IS NOT NULL,
                           'cta_link','/hub/home-games/' || p_group_id::text || '/host/settings',
                           'weight', 10),
        jsonb_build_object('id','description','label','Write a group description',
                           'done', v_group.description IS NOT NULL AND length(v_group.description) > 20,
                           'cta_link','/hub/home-games/' || p_group_id::text || '/host/settings',
                           'weight', 5),
        jsonb_build_object('id','location','label','Set your city and state',
                           'done', v_group.city IS NOT NULL AND v_group.state IS NOT NULL,
                           'cta_link','/hub/home-games/' || p_group_id::text || '/host/settings',
                           'weight', 7),
        jsonb_build_object('id','stakes','label','Set default game type and stakes',
                           'done', v_group.default_game_type IS NOT NULL AND v_group.default_stakes IS NOT NULL,
                           'cta_link','/hub/home-games/' || p_group_id::text || '/host/settings',
                           'weight', 5),
        jsonb_build_object('id','schedule','label','Set typical day and time',
                           'done', v_group.typical_day IS NOT NULL AND v_group.typical_time IS NOT NULL,
                           'cta_link','/hub/home-games/' || p_group_id::text || '/host/settings',
                           'weight', 5),
        jsonb_build_object('id','first_game','label','Schedule your first game',
                           'done', v_game_count > 0,
                           'cta_link','/hub/home-games/' || p_group_id::text || '/host/games/new',
                           'weight', 15),
        jsonb_build_object('id','invite_members','label','Invite at least 3 members',
                           'done', v_member_count >= 3,
                           'current', v_member_count, 'target', 3,
                           'cta_link','/hub/home-games/' || p_group_id::text || '/host/invite',
                           'weight', 12),
        jsonb_build_object('id','first_post','label','Post an announcement',
                           'done', v_post_count > 0,
                           'cta_link','/hub/home-games/' || p_group_id::text || '/host',
                           'weight', 5),
        jsonb_build_object('id','share_link','label','Create a shareable invite link',
                           'done', v_invite_count > 0,
                           'cta_link','/hub/home-games/' || p_group_id::text || '/host/invite',
                           'weight', 8),
        jsonb_build_object('id','tags','label','Add discovery tags',
                           'done', array_length(v_group.tags, 1) IS NOT NULL AND array_length(v_group.tags, 1) > 0,
                           'cta_link','/hub/home-games/' || p_group_id::text || '/host/settings',
                           'weight', 3)
    );

    -- Compute completion percentage
    SELECT SUM((item->>'weight')::int) FILTER (WHERE (item->>'done')::boolean),
           SUM((item->>'weight')::int)
      INTO v_completed, v_total
      FROM jsonb_array_elements(v_items) item;

    RETURN jsonb_build_object(
        'success', true,
        'group_id', p_group_id,
        'items', v_items,
        'completion_pct', ROUND(100.0 * COALESCE(v_completed, 0)::numeric / NULLIF(v_total, 0), 1),
        'items_done', (SELECT COUNT(*) FROM jsonb_array_elements(v_items) WHERE (value->>'done')::boolean),
        'items_total', jsonb_array_length(v_items)
    );
END;
$$;


ALTER FUNCTION public.get_host_onboarding_checklist(p_group_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: get_host_reputation(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_host_reputation(p_host_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    v_stats jsonb;
BEGIN
    SELECT jsonb_build_object(
        'host_user_id', p_host_user_id,
        'groups_owned', (SELECT COUNT(*) FROM commander_home_groups WHERE owner_id = p_host_user_id),
        'total_games_hosted', COALESCE((
            SELECT SUM(games_hosted) FROM commander_home_groups WHERE owner_id = p_host_user_id
        ), 0),
        'review_count', (
            SELECT COUNT(*) FROM commander_home_game_reviews r
             JOIN commander_home_games g ON g.id = r.game_id
             JOIN commander_home_groups grp ON grp.id = g.group_id
             WHERE grp.owner_id = p_host_user_id OR g.host_id = p_host_user_id
        ),
        'avg_rating', COALESCE((
            SELECT ROUND(AVG(r.rating)::numeric, 2) FROM commander_home_game_reviews r
             JOIN commander_home_games g ON g.id = r.game_id
             JOIN commander_home_groups grp ON grp.id = g.group_id
             WHERE grp.owner_id = p_host_user_id OR g.host_id = p_host_user_id
        ), 0),
        'total_attendees', COALESCE((
            SELECT SUM(COALESCE(rsvp_yes, 0)) FROM commander_home_games g
             JOIN commander_home_groups grp ON grp.id = g.group_id
             WHERE (grp.owner_id = p_host_user_id OR g.host_id = p_host_user_id)
               AND g.status = 'completed'
        ), 0),
        'completion_rate_pct', COALESCE((
            SELECT CASE WHEN COUNT(*) = 0 THEN 0
                   ELSE ROUND(100.0 * SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END)::numeric / COUNT(*), 1) END
              FROM commander_home_games g
              JOIN commander_home_groups grp ON grp.id = g.group_id
             WHERE (grp.owner_id = p_host_user_id OR g.host_id = p_host_user_id)
               AND g.status IN ('completed','cancelled')
        ), 0)
    ) INTO v_stats;

    RETURN v_stats;
END;
$$;


ALTER FUNCTION public.get_host_reputation(p_host_user_id uuid) OWNER TO postgres;

--
-- Name: get_host_weekly_digest_payload(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_host_weekly_digest_payload(p_host_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_week_start timestamptz;
    v_week_prev_start timestamptz;
    v_result jsonb;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    IF p_caller_user_id <> p_host_id THEN RAISE EXCEPTION 'CAN_ONLY_REQUEST_OWN_DIGEST'; END IF;

    v_week_start := date_trunc('week', NOW());
    v_week_prev_start := v_week_start - INTERVAL '7 days';

    WITH my_groups AS (
        SELECT g.id, g.name,
               (SELECT sp.slug FROM social_pages sp 
                 WHERE sp.linked_entity_type='home_group' 
                   AND sp.linked_entity_id = g.id::text LIMIT 1) AS slug
          FROM commander_home_groups g
         WHERE g.owner_id = p_host_id AND g.is_active = true
    )
    SELECT jsonb_build_object(
        'generated_at', NOW(),
        'host_id', p_host_id,
        'week_start', v_week_start,
        'prev_week_start', v_week_prev_start,
        'groups', (SELECT jsonb_agg(jsonb_build_object(
            'group_id', mg.id, 'group_name', mg.name, 'group_slug', mg.slug,
            'this_week', jsonb_build_object(
                'games_completed', (SELECT COUNT(*) FROM commander_home_games 
                                      WHERE group_id = mg.id AND status='completed' 
                                        AND scheduled_date >= v_week_start),
                'games_upcoming', (SELECT COUNT(*) FROM commander_home_games 
                                     WHERE group_id = mg.id AND status IN ('scheduled','confirmed') 
                                       AND scheduled_date >= NOW()),
                'new_members', (SELECT COUNT(*) FROM commander_home_members 
                                  WHERE group_id = mg.id AND created_at >= v_week_start),
                'rsvps_received', (SELECT COUNT(*) FROM commander_home_rsvps r 
                                     JOIN commander_home_games g ON g.id = r.game_id
                                    WHERE g.group_id = mg.id AND r.responded_at >= v_week_start),
                'checkins', (SELECT COUNT(*) FROM commander_home_rsvps r 
                               JOIN commander_home_games g ON g.id = r.game_id
                              WHERE g.group_id = mg.id AND r.checked_in_at >= v_week_start),
                'posts', (SELECT COUNT(*) FROM commander_home_posts 
                           WHERE group_id = mg.id AND created_at >= v_week_start)
            ),
            'last_week', jsonb_build_object(
                'games_completed', (SELECT COUNT(*) FROM commander_home_games 
                                      WHERE group_id = mg.id AND status='completed' 
                                        AND scheduled_date BETWEEN v_week_prev_start AND v_week_start),
                'new_members', (SELECT COUNT(*) FROM commander_home_members 
                                  WHERE group_id = mg.id 
                                    AND created_at BETWEEN v_week_prev_start AND v_week_start),
                'rsvps_received', (SELECT COUNT(*) FROM commander_home_rsvps r 
                                     JOIN commander_home_games g ON g.id = r.game_id
                                    WHERE g.group_id = mg.id 
                                      AND r.responded_at BETWEEN v_week_prev_start AND v_week_start),
                'checkins', (SELECT COUNT(*) FROM commander_home_rsvps r 
                               JOIN commander_home_games g ON g.id = r.game_id
                              WHERE g.group_id = mg.id 
                                AND r.checked_in_at BETWEEN v_week_prev_start AND v_week_start)
            ),
            'scores', jsonb_build_object(
                'quality', (SELECT quality_score FROM commander_home_groups WHERE id = mg.id),
                'vitality', (SELECT vitality_score FROM commander_home_groups WHERE id = mg.id)
            ),
            'pending_approvals', (SELECT COUNT(*) FROM commander_home_members 
                                    WHERE group_id = mg.id AND status='pending'),
            'dormant_member_count', (SELECT COUNT(*) FROM commander_home_members m
                                       WHERE m.group_id = mg.id AND m.status='approved'
                                         AND (m.last_attended IS NULL 
                                              OR m.last_attended < NOW() - INTERVAL '60 days'))
        )) FROM my_groups mg)
    ) INTO v_result;

    RETURN v_result;
END; $$;


