--
-- Name: get_live_home_game_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_live_home_game_state(p_game_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_game  RECORD;
    v_group RECORD;
    v_is_host boolean;
    v_seated jsonb;
    v_away   jsonb;
    v_enroute jsonb;
    v_waitlist jsonb;
    v_no_response jsonb;
    v_flakes jsonb;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;

    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;

    v_is_host := (v_game.host_id = p_caller_user_id)
              OR (v_group.owner_id = p_caller_user_id)
              OR EXISTS (SELECT 1 FROM commander_home_members
                          WHERE group_id = v_game.group_id AND user_id = p_caller_user_id
                            AND role = 'admin' AND status = 'approved');
    IF NOT v_is_host THEN RAISE EXCEPTION 'NOT_A_HOST'; END IF;

    -- BUG-7 fix: 'seated' is the Home Games enum for an occupied seat.
    -- 'occupied' is the Club Arena enum (commander_seats, different table).
    SELECT jsonb_agg(jsonb_build_object(
        'seat_number', s.seat_number, 'user_id', s.user_id,
        'player_name', COALESCE(s.player_name, p.display_name, p.full_name, 'Player'),
        'avatar_url', p.avatar_url,
        'seated_at', s.seated_at,
        'checked_in_at', r.checked_in_at
    ) ORDER BY s.seat_number)
    INTO v_seated
    FROM commander_home_seats s
    LEFT JOIN profiles p ON p.id = s.user_id
    LEFT JOIN commander_home_rsvps r ON r.game_id = s.game_id AND r.user_id = s.user_id
    WHERE s.game_id = p_game_id AND s.status = 'seated';

    SELECT jsonb_agg(jsonb_build_object(
        'seat_number', s.seat_number, 'user_id', s.user_id,
        'player_name', COALESCE(s.player_name, p.display_name, p.full_name, 'Player'),
        'avatar_url', p.avatar_url,
        'away_since', s.away_since
    ) ORDER BY s.seat_number)
    INTO v_away
    FROM commander_home_seats s
    LEFT JOIN profiles p ON p.id = s.user_id
    WHERE s.game_id = p_game_id AND s.status = 'away';

    -- BUG-7 fix (second site): en_route exclusion must match the seated/away
    -- enum. Previously 'occupied' here never matched, so seated-and-in-person
    -- players were misreported as en_route (haven't arrived yet).
    SELECT jsonb_agg(jsonb_build_object(
        'user_id', r.user_id,
        'player_name', COALESCE(p.display_name, p.full_name, 'Player'),
        'avatar_url', p.avatar_url,
        'bringing_guests', r.bringing_guests
    ))
    INTO v_enroute
    FROM commander_home_rsvps r
    LEFT JOIN profiles p ON p.id = r.user_id
    WHERE r.game_id = p_game_id
      AND r.response = 'yes'
      AND r.checked_in_at IS NULL
      AND NOT EXISTS (SELECT 1 FROM commander_home_seats s
                       WHERE s.game_id = p_game_id AND s.user_id = r.user_id
                         AND s.status IN ('seated','away'));

    SELECT jsonb_agg(jsonb_build_object(
        'user_id', r.user_id,
        'player_name', COALESCE(p.display_name, p.full_name, 'Player'),
        'avatar_url', p.avatar_url,
        'joined_waitlist_at', r.responded_at
    ) ORDER BY r.responded_at)
    INTO v_waitlist
    FROM commander_home_rsvps r
    LEFT JOIN profiles p ON p.id = r.user_id
    WHERE r.game_id = p_game_id AND r.response = 'waitlist';

    SELECT jsonb_agg(jsonb_build_object(
        'user_id', m.user_id,
        'player_name', COALESCE(p.display_name, p.full_name, 'Member'),
        'avatar_url', p.avatar_url
    ))
    INTO v_no_response
    FROM commander_home_members m
    LEFT JOIN profiles p ON p.id = m.user_id
    WHERE m.group_id = v_game.group_id
      AND m.status = 'approved'
      AND NOT EXISTS (SELECT 1 FROM commander_home_rsvps r
                       WHERE r.game_id = p_game_id AND r.user_id = m.user_id);

    SELECT jsonb_agg(jsonb_build_object(
        'user_id', r.user_id,
        'player_name', COALESCE(p.display_name, p.full_name, 'Player'),
        'avatar_url', p.avatar_url
    ))
    INTO v_flakes
    FROM commander_home_rsvps r
    LEFT JOIN profiles p ON p.id = r.user_id
    WHERE r.game_id = p_game_id AND r.flaked = true;

    RETURN jsonb_build_object(
        'success', true,
        'game', jsonb_build_object(
            'id', v_game.id, 'title', v_game.title,
            'status', v_game.status,
            'scheduled_date', v_game.scheduled_date,
            'start_time', v_game.start_time,
            'max_players', COALESCE(v_game.max_players, 9),
            'rsvp_yes', v_game.rsvp_yes, 'rsvp_maybe', v_game.rsvp_maybe,
            'rsvp_no', v_game.rsvp_no, 'waitlist_count', v_game.waitlist_count
        ),
        'seated', COALESCE(v_seated, '[]'::jsonb),
        'seated_count', jsonb_array_length(COALESCE(v_seated, '[]'::jsonb)),
        'away', COALESCE(v_away, '[]'::jsonb),
        'en_route', COALESCE(v_enroute, '[]'::jsonb),
        'en_route_count', jsonb_array_length(COALESCE(v_enroute, '[]'::jsonb)),
        'waitlist', COALESCE(v_waitlist, '[]'::jsonb),
        'no_response', COALESCE(v_no_response, '[]'::jsonb),
        'flakes', COALESCE(v_flakes, '[]'::jsonb)
    );
END;
$$;


ALTER FUNCTION public.get_live_home_game_state(p_game_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: get_max_player_number(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_max_player_number() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
    SELECT MAX(player_number::BIGINT)
    FROM public.profiles
    WHERE player_number IS NOT NULL
      AND player_number ~ '^\d+$'
$_$;


ALTER FUNCTION public.get_max_player_number() OWNER TO postgres;

--
-- Name: get_member_lifecycle_segments(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_member_lifecycle_segments(p_group_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_is_authorized boolean; v_result jsonb;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    SELECT EXISTS (SELECT 1 FROM commander_home_groups 
                    WHERE id = p_group_id AND owner_id = p_caller_user_id)
        OR EXISTS (SELECT 1 FROM commander_home_members 
                    WHERE group_id = p_group_id AND user_id = p_caller_user_id 
                      AND role IN ('owner','admin') AND status='approved')
      INTO v_is_authorized;
    IF NOT v_is_authorized THEN RAISE EXCEPTION 'NOT_HOST_OR_ADMIN'; END IF;

    WITH member_activity AS (
        SELECT 
            m.user_id,
            m.created_at AS joined_at,
            m.is_regular,
            m.flake_strikes,
            m.games_attended,
            m.last_attended,
            -- games attended in last 30 / 60 / 90 days
            (SELECT COUNT(*) FROM commander_home_rsvps r 
              JOIN commander_home_games g ON g.id = r.game_id
             WHERE r.user_id = m.user_id AND g.group_id = p_group_id
               AND r.checked_in_at > NOW() - INTERVAL '30 days') AS attended_30d,
            (SELECT COUNT(*) FROM commander_home_rsvps r 
              JOIN commander_home_games g ON g.id = r.game_id
             WHERE r.user_id = m.user_id AND g.group_id = p_group_id
               AND r.checked_in_at > NOW() - INTERVAL '90 days') AS attended_90d,
            EXTRACT(day FROM (NOW() - m.created_at))::int AS days_since_join,
            EXTRACT(day FROM (NOW() - COALESCE(m.last_attended, m.created_at)))::int AS days_since_last_attended
          FROM commander_home_members m
         WHERE m.group_id = p_group_id AND m.status = 'approved'
    ),
    segmented AS (
        SELECT *, 
            CASE
                WHEN days_since_join <= 14 AND games_attended = 0 THEN 'new_never_attended'
                WHEN days_since_join <= 14 THEN 'new'
                WHEN attended_30d >= 3 THEN 'core'
                WHEN attended_30d >= 1 THEN 'active'
                WHEN attended_90d >= 1 AND days_since_last_attended <= 60 THEN 'drifting'
                WHEN days_since_last_attended BETWEEN 61 AND 120 THEN 'dormant'
                WHEN games_attended = 0 AND days_since_join > 60 THEN 'never_attended'
                ELSE 'churned'
            END AS segment
          FROM member_activity
    )
    SELECT jsonb_build_object(
        'generated_at', NOW(),
        'segment_counts', (SELECT jsonb_object_agg(segment, cnt) FROM (
             SELECT segment, COUNT(*) AS cnt FROM segmented GROUP BY segment
           ) t),
        'members', jsonb_agg(jsonb_build_object(
            'user_id', user_id, 
            'segment', segment,
            'joined_at', joined_at,
            'games_attended_total', games_attended,
            'attended_30d', attended_30d,
            'attended_90d', attended_90d,
            'days_since_last_attended', days_since_last_attended,
            'is_regular', is_regular,
            'flake_strikes', flake_strikes
        ) ORDER BY attended_30d DESC, attended_90d DESC)
    ) INTO v_result
      FROM segmented;

    RETURN v_result;
END; $$;


ALTER FUNCTION public.get_member_lifecycle_segments(p_group_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_member_lifecycle_segments(p_group_id uuid, p_caller_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_member_lifecycle_segments(p_group_id uuid, p_caller_user_id uuid) IS 'Phase 26 redux/A: Member segmentation for host re-engagement. Read-only, no money involved.';


--
-- Name: get_message_reactions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_message_reactions(p_message_id uuid) RETURNS TABLE(reaction text, count integer, user_reacted boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT r.reaction,
         count(*)::integer,
         bool_or(r.user_id = auth.uid())
    FROM public.message_reactions r
   WHERE r.message_id = p_message_id
   GROUP BY r.reaction
   ORDER BY count(*) DESC, r.reaction;
$$;


ALTER FUNCTION public.get_message_reactions(p_message_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_message_reactions(p_message_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_message_reactions(p_message_id uuid) IS 'Reaction summary for one message. SECURITY INVOKER on purpose - RLS on message_reactions decides what the caller may see.';


--
-- Name: get_mutual_friends(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_mutual_friends(p_other_user_id uuid) RETURNS TABLE(id uuid, username text, avatar_url text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH mine AS (
    SELECT CASE WHEN user_id = auth.uid() THEN friend_id ELSE user_id END AS friend_id
    FROM public.friendships
    WHERE status = 'accepted' AND auth.uid() IN (user_id, friend_id)
  ), theirs AS (
    SELECT CASE WHEN user_id = p_other_user_id THEN friend_id ELSE user_id END AS friend_id
    FROM public.friendships
    WHERE status = 'accepted' AND p_other_user_id IN (user_id, friend_id)
  )
  SELECT
    p.id,
    public.fn_arena_name(
      p.alias, p.username, p.display_name, p.first_name, p.last_name, p.full_name
    ) AS username,
    COALESCE(NULLIF(btrim(p.arena_avatar_url), ''), p.avatar_url) AS avatar_url
  FROM mine JOIN theirs USING (friend_id)
  JOIN public.profiles p ON p.id = mine.friend_id
  WHERE auth.uid() IS NOT NULL AND p_other_user_id IS NOT NULL
  ORDER BY public.fn_arena_name(
    p.alias, p.username, p.display_name, p.first_name, p.last_name, p.full_name
  ), p.id
  LIMIT 100
$$;


ALTER FUNCTION public.get_mutual_friends(p_other_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_mutual_friends(p_other_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_mutual_friends(p_other_user_id uuid) IS 'Mutual friends of the caller and p_other_user_id. The `username` column carries the ARENA name (fn_arena_name), never the raw username, and `avatar_url` carries the arena portrait. Club Arena surfaces must never render a raw profiles.username: it skips the alias, which is the poker name.';


--
-- Name: get_my_followed_home_groups(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_followed_home_groups(p_caller_user_id uuid) RETURNS TABLE(group_id uuid, name text, slug text, profile_photo_url text, city text, state text, member_count integer, games_hosted integer, followed_at timestamp with time zone, notify_new_games boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    RETURN QUERY
    SELECT g.id, g.name, sp.slug, g.profile_photo_url, g.city, g.state, 
           g.member_count, g.games_hosted,
           f.created_at, f.notify_new_games
      FROM commander_home_group_follows f
      JOIN commander_home_groups g ON g.id = f.group_id
      LEFT JOIN social_pages sp ON sp.linked_entity_type='home_group' AND sp.linked_entity_id = g.id::text
     WHERE f.user_id = p_caller_user_id
     ORDER BY f.created_at DESC;
END; $$;


ALTER FUNCTION public.get_my_followed_home_groups(p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: get_my_followed_venues(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_followed_venues(p_caller_user_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    p_limit := LEAST(GREATEST(p_limit, 1), 100);
    p_offset := GREATEST(p_offset, 0);

    WITH followed AS (
      SELECT f.id AS follow_id, f.venue_id, f.followed_at,
             f.notify_posts, f.notify_events, f.notify_promotions, f.notify_tournaments,
             v.name, v.slug, v.city, v.state, v.venue_type, v.trust_score, v.is_claimed, v.follower_count
        FROM commander_venue_followers f
        JOIN poker_venues v ON v.id = f.venue_id
       WHERE f.user_id = p_caller_user_id 
         AND COALESCE(v.is_active, true) AND NOT COALESCE(v.is_suppressed, false)
       ORDER BY f.followed_at DESC
       LIMIT p_limit OFFSET p_offset
    )
    SELECT jsonb_build_object(
      'generated_at', NOW(),
      'total_follows', (SELECT COUNT(*) FROM commander_venue_followers WHERE user_id = p_caller_user_id),
      'returned', (SELECT COUNT(*) FROM followed),
      'venues', COALESCE((SELECT jsonb_agg(row_to_json(followed)) FROM followed), '[]'::jsonb)
    ) INTO v_result;
    RETURN v_result;
END; $$;


ALTER FUNCTION public.get_my_followed_venues(p_caller_user_id uuid, p_limit integer, p_offset integer) OWNER TO postgres;

