--
-- Name: get_or_assign_challenges(text, text[], text, text[], text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_or_assign_challenges(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) RETURNS TABLE(id uuid, challenge_id text, assigned_date text, progress integer, completed boolean, claimed boolean, completed_at timestamp with time zone, name text, description text, challenge_type text, requirement integer, chip_reward numeric, diamond_reward integer, tier text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  PERFORM public.assign_user_challenges(p_daily_key, p_daily_ids);
  PERFORM public.assign_user_challenges(p_weekly_key, p_weekly_ids);
  PERFORM public.assign_user_challenges(p_monthly_key, p_monthly_ids);

  RETURN QUERY
  SELECT u.id,
         u.challenge_id,
         u.assigned_date,
         u.progress,
         u.completed,
         u.claimed,
         u.completed_at,
         u.challenge_name_snapshot,
         u.challenge_description_snapshot,
         u.challenge_type_snapshot,
         u.requirement_snapshot,
         u.chip_reward_snapshot,
         u.diamond_reward_snapshot,
         u.tier_snapshot
  FROM public.user_daily_challenges u
  WHERE u.user_id = v_uid
    AND u.assigned_date IN (p_daily_key, p_weekly_key, p_monthly_key)
  ORDER BY CASE u.tier_snapshot WHEN 'daily' THEN 1 WHEN 'weekly' THEN 2 ELSE 3 END,
           u.created_at,
           u.id;
END;
$$;


ALTER FUNCTION public.get_or_assign_challenges(p_daily_key text, p_daily_ids text[], p_weekly_key text, p_weekly_ids text[], p_monthly_key text, p_monthly_ids text[]) OWNER TO postgres;

--
-- Name: get_pending_celebrations(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_pending_celebrations(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text;
  v_caller_uid uuid;
  v_result jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  v_caller_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '');
  v_caller_uid := auth.uid();
  IF v_caller_role = 'authenticated' THEN
    IF v_caller_uid IS NULL OR p_user_id <> v_caller_uid THEN
      RAISE WARNING 'get_pending_celebrations: spoof attempt by % targeting %', v_caller_uid, p_user_id;
      RETURN '[]'::jsonb;
    END IF;
  ELSIF v_caller_role = 'anon' OR v_caller_role = '' THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.created_at ASC), '[]'::jsonb)
  INTO v_result
  FROM public.celebration_queue c
  WHERE c.user_id = p_user_id
    AND COALESCE(c.dismissed, false) = false
  LIMIT 50;

  RETURN COALESCE(v_result, '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'get_pending_celebrations failed for %: % %', p_user_id, SQLERRM, SQLSTATE;
  RETURN '[]'::jsonb;
END;
$$;


ALTER FUNCTION public.get_pending_celebrations(p_user_id uuid) OWNER TO postgres;

--
-- Name: get_personal_assistant_leak_stats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_personal_assistant_leak_stats(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_active bigint := 0;
  v_resolved bigint := 0;
  v_training_active bigint := 0;
  v_training_resolved bigint := 0;
  v_avg_ev numeric := 0;
  v_measured bigint := 0;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'user_id_required');
  END IF;

  SELECT
    count(*) FILTER (
      WHERE status IS DISTINCT FROM 'resolved'
        AND source_system IS DISTINCT FROM 'user_reported'
    ),
    count(*) FILTER (
      WHERE status = 'resolved'
        AND source_system IS DISTINCT FROM 'user_reported'
    ),
    COALESCE(avg(abs(avg_ev_loss_bb)) FILTER (
      WHERE status IS DISTINCT FROM 'resolved'
        AND ev_loss_measured = true
        AND avg_ev_loss_bb IS NOT NULL
        AND avg_ev_loss_bb <> 0
    ), 0),
    count(*) FILTER (
      WHERE status IS DISTINCT FROM 'resolved'
        AND ev_loss_measured = true
        AND avg_ev_loss_bb IS NOT NULL
        AND avg_ev_loss_bb <> 0
    )
  INTO v_active, v_resolved, v_avg_ev, v_measured
  FROM public.user_leaks
  WHERE user_id = p_user_id;

  SELECT
    count(*) FILTER (WHERE fixed_at IS NULL),
    count(*) FILTER (WHERE fixed_at IS NOT NULL)
  INTO v_training_active, v_training_resolved
  FROM public.user_training_leaks
  WHERE user_id = p_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'active_leaks', v_active + v_training_active,
    'resolved_leaks', v_resolved + v_training_resolved,
    'avg_ev_loss', round(v_avg_ev, 2),
    'measured_leak_count', v_measured
  );
END;
$$;


ALTER FUNCTION public.get_personal_assistant_leak_stats(p_user_id uuid) OWNER TO postgres;

--
-- Name: get_platform_integrity_report(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_platform_integrity_report(p_admin_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_admin_role text; 
    v_total_groups int; v_groups_with_sp int;
    v_total_claimed int; v_claimed_with_sp int; v_claimed_with_cmd int;
    v_total_clubs int; v_clubs_with_sp int;
    v_archived_claimed int;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_admin_user_id THEN 
        RAISE EXCEPTION 'UNAUTHORIZED'; 
    END IF;
    SELECT role INTO v_admin_role FROM profiles WHERE id = p_admin_user_id;
    IF v_admin_role NOT IN ('admin','superadmin','moderator') THEN
        RAISE EXCEPTION 'NOT_ADMIN';
    END IF;

    SELECT COUNT(*) INTO v_total_groups FROM commander_home_groups;
    SELECT COUNT(*) INTO v_groups_with_sp FROM commander_home_groups g
       WHERE EXISTS(SELECT 1 FROM social_pages sp 
                    WHERE sp.linked_entity_type='home_group' AND sp.linked_entity_id = g.id::text);

    -- Active claimed venues only
    SELECT COUNT(*) INTO v_total_claimed FROM poker_venues 
     WHERE is_claimed = true 
       AND COALESCE(is_active, true) 
       AND NOT COALESCE(is_suppressed, false);
    SELECT COUNT(*) INTO v_claimed_with_sp FROM poker_venues v 
     WHERE v.is_claimed = true
       AND COALESCE(v.is_active, true) 
       AND NOT COALESCE(v.is_suppressed, false)
       AND EXISTS(SELECT 1 FROM social_pages sp 
                   WHERE sp.linked_entity_type='venue' AND sp.linked_entity_id = v.id::text);
    SELECT COUNT(*) INTO v_claimed_with_cmd FROM poker_venues 
     WHERE is_claimed = true AND commander_enabled = true
       AND COALESCE(is_active, true) 
       AND NOT COALESCE(is_suppressed, false);
    SELECT COUNT(*) INTO v_archived_claimed FROM poker_venues 
     WHERE is_claimed = true AND (COALESCE(is_active, true) = false OR COALESCE(is_suppressed, false) = true);
    
    SELECT COUNT(*) INTO v_total_clubs FROM clubs;
    SELECT COUNT(*) INTO v_clubs_with_sp FROM clubs c
     WHERE EXISTS(SELECT 1 FROM social_pages sp 
                   WHERE sp.linked_entity_type='club' AND sp.linked_entity_id = c.id::text);

    RETURN jsonb_build_object(
        'generated_at', now(),
        'identity', jsonb_build_object(
            'real_users', (SELECT COUNT(*) FROM auth.users WHERE email NOT LIKE '%@hydra.bot'),
            'profiles_for_real_users', (SELECT COUNT(*) FROM profiles p
                                WHERE EXISTS(SELECT 1 FROM auth.users u 
                                              WHERE u.id = p.id 
                                                AND u.email NOT LIKE '%@hydra.bot')),
            'real_users_without_profile', (
                SELECT COUNT(*) FROM auth.users u 
                 WHERE NOT EXISTS(SELECT 1 FROM profiles p WHERE p.id = u.id)
                   AND u.email NOT LIKE '%@hydra.bot')
        ),
        'wiring_coverage', jsonb_build_object(
            'home_groups', jsonb_build_object(
                'total', v_total_groups, 
                'with_social_page', v_groups_with_sp,
                'coverage_pct', CASE WHEN v_total_groups > 0 
                  THEN ROUND(v_groups_with_sp::numeric / v_total_groups * 100, 1) ELSE 100 END),
            'claimed_venues_active', jsonb_build_object(
                'total', v_total_claimed,
                'with_social_page', v_claimed_with_sp,
                'with_commander_enabled', v_claimed_with_cmd,
                'social_coverage_pct', CASE WHEN v_total_claimed > 0 
                  THEN ROUND(v_claimed_with_sp::numeric / v_total_claimed * 100, 1) ELSE 100 END,
                'commander_coverage_pct', CASE WHEN v_total_claimed > 0 
                  THEN ROUND(v_claimed_with_cmd::numeric / v_total_claimed * 100, 1) ELSE 100 END,
                'archived_or_suppressed', v_archived_claimed),
            'clubs', jsonb_build_object(
                'total', v_total_clubs,
                'with_social_page', v_clubs_with_sp,
                'coverage_pct', CASE WHEN v_total_clubs > 0 
                  THEN ROUND(v_clubs_with_sp::numeric / v_total_clubs * 100, 1) ELSE 100 END)
        ),
        'triggers_installed', (SELECT jsonb_agg(tgname ORDER BY tgname)
          FROM pg_trigger 
         WHERE NOT tgisinternal 
           AND tgname IN ('trg_autocreate_home_group_social_page',
                          'trg_venue_claim_wiring',
                          'trg_autocreate_club_social_page',
                          'trg_emit_claim_notification')),
        'foreign_keys_established', jsonb_build_object(
            'fk_commander_home_groups_owner_profile', 
                EXISTS(SELECT 1 FROM pg_constraint WHERE conname = 'fk_commander_home_groups_owner_profile'),
            'fk_venue_managers_user_profile',
                EXISTS(SELECT 1 FROM pg_constraint WHERE conname = 'fk_venue_managers_user_profile'),
            'fk_social_pages_owner_profile',
                EXISTS(SELECT 1 FROM pg_constraint WHERE conname = 'fk_social_pages_owner_profile'),
            'fk_venue_claims_user_profile',
                EXISTS(SELECT 1 FROM pg_constraint WHERE conname = 'fk_venue_claims_user_profile')
        ),
        'operational', jsonb_build_object(
            'pending_claims_queue_depth', 
                (SELECT COUNT(*) FROM venue_claims WHERE status IN ('pending','under_review')),
            'active_venue_managers', (SELECT COUNT(*) FROM venue_managers WHERE is_active = true),
            'unread_notifications_system_wide', (SELECT COUNT(*) FROM notifications 
                                                  WHERE COALESCE(read, false) = false)
        ),
        'verdict', CASE 
            WHEN (v_total_groups = 0 OR v_total_groups = v_groups_with_sp) 
             AND (v_total_claimed = 0 OR v_total_claimed = v_claimed_with_sp)
             AND (v_total_claimed = 0 OR v_total_claimed = v_claimed_with_cmd)
             AND (v_total_clubs = 0 OR v_total_clubs = v_clubs_with_sp)
            THEN 'FULLY_WIRED'
            ELSE 'GAPS_EXIST'
        END
    );
END; $$;


ALTER FUNCTION public.get_platform_integrity_report(p_admin_user_id uuid) OWNER TO postgres;

