--
-- Name: get_pnm_index_sitemap_entries(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_pnm_index_sitemap_entries() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
    WITH state_entries AS (
        SELECT DISTINCT state, COUNT(*) AS venue_count, MAX(last_scraped_at) AS last_updated
          FROM poker_venues 
         WHERE state IS NOT NULL AND COALESCE(is_active,true) AND NOT COALESCE(is_suppressed,false)
         GROUP BY state
    ),
    city_entries AS (
        SELECT DISTINCT state, city, COUNT(*) AS venue_count, MAX(last_scraped_at) AS last_updated
          FROM poker_venues 
         WHERE state IS NOT NULL AND city IS NOT NULL 
           AND COALESCE(is_active,true) AND NOT COALESCE(is_suppressed,false)
         GROUP BY state, city
        HAVING COUNT(*) >= 1
    )
    SELECT jsonb_build_object(
        'generated_at', NOW(),
        'state_count', (SELECT COUNT(*) FROM state_entries),
        'city_count', (SELECT COUNT(*) FROM city_entries),
        'state_entries', (SELECT jsonb_agg(jsonb_build_object(
            'state', state, 'venue_count', venue_count, 'last_updated', last_updated,
            'url_path', '/poker-near-me/' || lower(state)
          ) ORDER BY state) FROM state_entries),
        'city_entries', (SELECT jsonb_agg(jsonb_build_object(
            'state', state, 'city', city, 'venue_count', venue_count, 'last_updated', last_updated,
            'url_path', '/poker-near-me/' || lower(state) || '/' || 
                        regexp_replace(lower(city), '[^a-z0-9]+', '-', 'g')
          ) ORDER BY state, city) FROM city_entries)
    ) INTO v_result;
    RETURN v_result;
END; $$;


ALTER FUNCTION public.get_pnm_index_sitemap_entries() OWNER TO postgres;

--
-- Name: get_poker_locations_by_state(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_poker_locations_by_state(p_state text, p_limit integer DEFAULT 100) RETURNS TABLE(source text, entity_id text, name text, slug text, venue_type text, city text, lat numeric, lng numeric, photo_url text, tagline text, activity_score numeric, has_tournaments boolean, is_verified boolean, poker_tables integer, stakes_cash text, games_offered text, member_count integer, games_hosted integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
    SELECT 
        source, entity_id, name, slug, venue_type,
        city, lat, lng,
        photo_url, tagline, activity_score,
        has_tournaments, is_verified,
        poker_tables, stakes_cash, games_offered,
        member_count, games_hosted
    FROM mv_active_poker_locations
    WHERE state = p_state
    ORDER BY activity_score DESC NULLS LAST, name
    LIMIT GREATEST(1, LEAST(p_limit, 500));
$$;


