--
-- Name: FUNCTION get_poker_near_me_unified(p_lat numeric, p_lng numeric, p_radius_miles numeric, p_include_venues boolean, p_include_home_games boolean, p_state_filter text, p_inactivity_days integer, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
