--
-- Name: personas; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.personas (
    id integer NOT NULL,
    player_id integer NOT NULL,
    name text NOT NULL,
    avatar_url text,
    location text,
    bio text,
    archetype text NOT NULL,
    poker_specialty text,
    slang_level integer DEFAULT 5 NOT NULL,
    technicality integer DEFAULT 5 NOT NULL,
    aggression integer DEFAULT 5 NOT NULL,
    humor integer DEFAULT 5 NOT NULL,
    post_frequency text DEFAULT 'MEDIUM'::text,
    preferred_topics text[],
    scrape_sources text[],
    last_post_at timestamp with time zone,
    posts_today integer DEFAULT 0,
    seen_content_hashes text[] DEFAULT '{}'::text[],
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT personas_aggression_check CHECK (((aggression >= 1) AND (aggression <= 10))),
    CONSTRAINT personas_humor_check CHECK (((humor >= 1) AND (humor <= 10))),
    CONSTRAINT personas_player_id_check CHECK (((player_id >= 101) AND (player_id <= 1249))),
    CONSTRAINT personas_slang_level_check CHECK (((slang_level >= 1) AND (slang_level <= 10))),
    CONSTRAINT personas_technicality_check CHECK (((technicality >= 1) AND (technicality <= 10)))
);


