--
-- Name: get_random_clip(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_random_clip(p_category text DEFAULT NULL::text, p_exclude_horse_id integer DEFAULT NULL::integer) RETURNS TABLE(id uuid, source_url text, processed_url text, start_time integer, duration integer, category text, description text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        cl.id,
        cl.source_url,
        cl.processed_url,
        cl.start_time,
        cl.duration,
        cl.category,
        cl.description
    FROM clip_library cl
    WHERE cl.status = 'ready'
      AND (p_category IS NULL OR cl.category = p_category)
      -- Don't reuse clips this horse used in last 7 days
      AND NOT EXISTS (
          SELECT 1 FROM clip_usage_log cul
          WHERE cul.clip_id = cl.id
            AND cul.horse_id = p_exclude_horse_id
            AND cul.created_at > NOW() - INTERVAL '7 days'
      )
    ORDER BY cl.used_count ASC, RANDOM()
    LIMIT 1;
END;
$$;


