--
-- Name: get_tournament_details(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_tournament_details(p_tournament_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_tourn RECORD;
  v_reg RECORD;
  v_registrations JSONB;
BEGIN
  SELECT * INTO v_tourn FROM club_tournaments WHERE id = p_tournament_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Tournament not found'); END IF;

  IF p_user_id IS NOT NULL THEN
    SELECT * INTO v_reg
      FROM tournament_registrations
     WHERE tournament_id = p_tournament_id
       AND user_id = p_user_id
       AND status = 'registered';
  END IF;

  SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'user_id',         tr.user_id,
               'status',          tr.status,
               'registered_at',   tr.registered_at,
               -- BUG-11 fix: finish_position -> finish_rank
               'finish_position', tr.finish_rank,
               -- BUG-11 fix: payout_amount  -> prize_amount
               'payout_amount',   tr.prize_amount
             )
             ORDER BY tr.registered_at
           ),
           '[]'::jsonb
         )
    INTO v_registrations
    FROM tournament_registrations tr
   WHERE tr.tournament_id = p_tournament_id
     AND tr.status IN ('registered', 'playing', 'eliminated');

  RETURN jsonb_build_object(
    'success', true,
    'tournament', jsonb_build_object(
      'id',               v_tourn.id,
      'club_id',          v_tourn.club_id,
      'name',             v_tourn.name,
      'type',             v_tourn.type,
      'variant',          v_tourn.variant,
      'buy_in',           v_tourn.buy_in,
      'starting_chips',   v_tourn.starting_chips,
      'max_players',      v_tourn.max_players,
      'status',           v_tourn.status,
      'registered_count', v_tourn.registered_count,
      'current_level',    v_tourn.current_level,
      'results',          v_tourn.results
    ),
    'is_registered', v_reg.id IS NOT NULL,
    'registrations', v_registrations
  );
END;
$$;


ALTER FUNCTION public.get_tournament_details(p_tournament_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: get_trending_home_groups(integer, numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_trending_home_groups(p_limit integer DEFAULT 12, p_near_lat numeric DEFAULT NULL::numeric, p_near_lng numeric DEFAULT NULL::numeric, p_radius_miles integer DEFAULT NULL::integer) RETURNS TABLE(group_id uuid, name text, city text, state text, profile_photo_url text, is_private boolean, member_count integer, recent_rsvps_30d bigint, trending_score numeric, distance_miles numeric, tags text[])
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_point geography;
BEGIN
    IF p_near_lat IS NOT NULL AND p_near_lng IS NOT NULL THEN
        v_point := ST_SetSRID(ST_MakePoint(p_near_lng, p_near_lat), 4326)::geography;
    END IF;

    RETURN QUERY
    SELECT 
        mv.group_id, mv.name, mv.city, mv.state, mv.profile_photo_url, 
        mv.is_private, mv.member_count, mv.recent_rsvps_30d, mv.trending_score,
        CASE WHEN v_point IS NOT NULL AND mv.location_geog IS NOT NULL
             THEN ROUND((ST_Distance(mv.location_geog, v_point) / 1609.344)::numeric, 1)
             ELSE NULL END AS distance_miles,
        mv.tags
      FROM mv_home_groups_trending mv
     WHERE (v_point IS NULL OR p_radius_miles IS NULL OR mv.location_geog IS NULL
            OR ST_DWithin(mv.location_geog, v_point, p_radius_miles * 1609.344))
     ORDER BY mv.trending_score DESC
     LIMIT GREATEST(1, LEAST(p_limit, 50));
END;
$$;


ALTER FUNCTION public.get_trending_home_groups(p_limit integer, p_near_lat numeric, p_near_lng numeric, p_radius_miles integer) OWNER TO postgres;

--
-- Name: get_unified_user_activity(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unified_user_activity(p_user_id uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN 
        RAISE EXCEPTION 'UNAUTHORIZED'; 
    END IF;
    p_limit := LEAST(GREATEST(p_limit, 1), 200);

    WITH activity AS (
        SELECT 'home_game_rsvp' AS kind, r.responded_at AS ts,
               jsonb_build_object(
                   'game_id', r.game_id, 'game_title', g.title,
                   'game_type', g.game_type, 'format', g.format,
                   'group_id', g.group_id, 'group_name', hg.name,
                   'response', r.response, 'checked_in', r.checked_in_at IS NOT NULL
               ) AS payload
          FROM commander_home_rsvps r
          JOIN commander_home_games g ON g.id = r.game_id
          JOIN commander_home_groups hg ON hg.id = g.group_id
         WHERE r.user_id = p_user_id

        UNION ALL
        SELECT 'home_group_joined', m.joined_at,
               jsonb_build_object('group_id', g.id, 'group_name', g.name, 'role', m.role)
          FROM commander_home_members m
          JOIN commander_home_groups g ON g.id = m.group_id
         WHERE m.user_id = p_user_id AND m.status = 'approved'

        UNION ALL
        SELECT 'venue_followed', f.followed_at,
               jsonb_build_object('venue_id', v.id, 'name', v.name,
                                  'slug', v.slug, 'city', v.city, 'state', v.state)
          FROM commander_venue_followers f
          JOIN poker_venues v ON v.id = f.venue_id
         WHERE f.user_id = p_user_id

        UNION ALL
        SELECT 'venue_review_written', created_at,
               jsonb_build_object('venue_id', venue_id, 'rating', overall_rating, 'title', title)
          FROM commander_venue_reviews
         WHERE reviewer_id = p_user_id AND is_published = true

        UNION ALL
        SELECT 'venue_post_published', created_at,
               jsonb_build_object('venue_id', venue_id, 'post_type', post_type,
                                  'content', substr(content, 1, 120))
          FROM commander_venue_posts
         WHERE author_id = p_user_id AND is_published = true

        UNION ALL
        SELECT 'venue_photo_uploaded', created_at,
               jsonb_build_object('venue_id', venue_id, 'url', url,
                                  'caption', caption, 'is_cover_photo', is_cover_photo)
          FROM commander_venue_photos WHERE uploaded_by = p_user_id

        UNION ALL
        SELECT 'venue_checkin', c.created_at,
               jsonb_build_object('venue_id', c.venue_id, 'message', c.message)
          FROM venue_checkins c WHERE c.user_id = p_user_id

        UNION ALL
        SELECT 'social_page_followed', f.created_at,
               jsonb_build_object('page_id', f.page_id, 'page_name', sp.name,
                                  'page_type', sp.page_type, 'page_slug', sp.slug)
          FROM social_page_followers f
          JOIN social_pages sp ON sp.id = f.page_id
         WHERE f.user_id = p_user_id

        UNION ALL
        SELECT 'diamonds_awarded', created_at,
               jsonb_build_object('amount', amount, 'source', source, 'metadata', metadata)
          FROM diamond_transactions
         WHERE user_id = p_user_id AND amount > 0

        UNION ALL
        SELECT 'venue_claim_submitted', created_at,
               jsonb_build_object('claim_id', id, 'venue_id', venue_id, 'status', status)
          FROM venue_claims WHERE user_id = p_user_id
    )
    SELECT jsonb_build_object(
        'generated_at', now(),
        'user_id', p_user_id,
        'count', (SELECT COUNT(*) FROM activity),
        'items', (SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) 
                    FROM (SELECT kind, ts, payload FROM activity 
                           WHERE ts IS NOT NULL
                           ORDER BY ts DESC LIMIT p_limit) t)
    ) INTO v_result;
    RETURN v_result;
END; $$;


ALTER FUNCTION public.get_unified_user_activity(p_user_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION get_unified_user_activity(p_user_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_unified_user_activity(p_user_id uuid, p_limit integer) IS 'Phase 29/C: Chronological activity timeline across all products. Self-only.';


--
-- Name: get_unified_user_profile(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unified_user_profile(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_profile RECORD; 
    v_is_self boolean := (auth.uid() = p_user_id);
    v_result jsonb;
BEGIN
    SELECT id, display_name, full_name, username, avatar_url, city, state,
           email_verified, phone_verified, diamonds, created_at
      INTO v_profile FROM profiles WHERE id = p_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'PROFILE_NOT_FOUND'; END IF;

    SELECT jsonb_build_object(
      'profile', jsonb_build_object(
          'id', v_profile.id,
          'display_name', v_profile.display_name,
          'full_name', CASE WHEN v_is_self THEN v_profile.full_name ELSE NULL END,
          'username', v_profile.username, 'avatar_url', v_profile.avatar_url,
          'city', v_profile.city, 'state', v_profile.state,
          'email_verified', CASE WHEN v_is_self THEN v_profile.email_verified ELSE NULL END,
          'phone_verified', CASE WHEN v_is_self THEN v_profile.phone_verified ELSE NULL END,
          'diamonds', CASE WHEN v_is_self THEN v_profile.diamonds ELSE NULL END,
          'member_since', v_profile.created_at
      ),
      'home_games', jsonb_build_object(
          'groups_owned', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'id', g.id, 'name', g.name,
                'slug', (SELECT sp.slug FROM social_pages sp 
                          WHERE sp.linked_entity_type='home_group' 
                            AND sp.linked_entity_id = g.id::text LIMIT 1),
                'city', g.city, 'state', g.state,
                'quality_score', g.quality_score, 'vitality_score', g.vitality_score,
                'is_private', g.is_private, 'created_at', g.created_at
              ) ORDER BY g.created_at DESC), '[]'::jsonb)
              FROM commander_home_groups g WHERE g.owner_id = p_user_id),
          'groups_joined', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'group_id', g.id, 'group_name', g.name,
                'role', m.role, 'status', m.status, 'joined_at', m.joined_at
              ) ORDER BY m.joined_at DESC), '[]'::jsonb)
              FROM commander_home_members m
              JOIN commander_home_groups g ON g.id = m.group_id
             WHERE m.user_id = p_user_id AND m.status = 'approved'),
          'games_attended', (
            SELECT COUNT(*) FROM commander_home_rsvps 
             WHERE user_id = p_user_id AND response = 'yes' AND checked_in_at IS NOT NULL),
          'games_rsvpd_yes', (
            SELECT COUNT(*) FROM commander_home_rsvps 
             WHERE user_id = p_user_id AND response = 'yes')
      ),
      'poker_near_me', jsonb_build_object(
          'venues_followed', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'venue_id', v.id, 'name', v.name, 'slug', v.slug,
                'city', v.city, 'state', v.state, 'followed_at', f.followed_at
              ) ORDER BY f.followed_at DESC), '[]'::jsonb)
              FROM commander_venue_followers f
              JOIN poker_venues v ON v.id = f.venue_id
             WHERE f.user_id = p_user_id),
          'venues_managed', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'venue_id', v.id, 'name', v.name, 'slug', v.slug, 'role', m.role,
                'commander_enabled', v.commander_enabled,
                'can_post_updates', m.can_post_updates,
                'can_respond_reviews', m.can_respond_reviews
              ) ORDER BY v.name), '[]'::jsonb)
              FROM venue_managers m
              JOIN poker_venues v ON v.id = m.venue_id
             WHERE m.user_id = p_user_id AND m.is_active = true),
          'venues_claimed_as_owner', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'venue_id', id, 'name', name, 'slug', slug,
                'commander_enabled', commander_enabled, 'claimed_at', claimed_at
              ) ORDER BY claimed_at DESC), '[]'::jsonb)
              FROM poker_venues WHERE claimed_by = p_user_id),
          'pending_claims', CASE WHEN v_is_self THEN (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'claim_id', c.id, 'venue_id', c.venue_id, 'venue_name', v.name,
                'status', c.status, 'verification_method', c.verification_method, 
                'created_at', c.created_at
              ) ORDER BY c.created_at DESC), '[]'::jsonb)
              FROM venue_claims c JOIN poker_venues v ON v.id = c.venue_id
             WHERE c.user_id = p_user_id AND c.status IN ('pending','under_review')
          ) ELSE NULL END,
          'reviews_written_count', (
            SELECT COUNT(*) FROM commander_venue_reviews 
             WHERE reviewer_id = p_user_id AND is_published = true),
          'posts_authored_count', (
            SELECT COUNT(*) FROM commander_venue_posts 
             WHERE author_id = p_user_id AND is_published = true),
          'photos_uploaded_count', (
            SELECT COUNT(*) FROM commander_venue_photos WHERE uploaded_by = p_user_id),
          'checkins_count', (
            SELECT COUNT(*) FROM venue_checkins WHERE user_id = p_user_id)
      ),
      'club_commander', jsonb_build_object(
          'has_commander_access', EXISTS(
            SELECT 1 FROM poker_venues v
             WHERE v.commander_enabled = true
               AND (v.claimed_by = p_user_id 
                    OR v.id IN (SELECT venue_id FROM venue_managers 
                                 WHERE user_id = p_user_id AND is_active = true))),
          'commander_venue_count', (
            SELECT COUNT(*) FROM poker_venues v
             WHERE v.commander_enabled = true
               AND (v.claimed_by = p_user_id
                    OR v.id IN (SELECT venue_id FROM venue_managers 
                                 WHERE user_id = p_user_id AND is_active = true)))
      ),
      'clubs', jsonb_build_object(
          'memberships', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'club_id', c.id, 'club_name', c.name, 'role', m.role, 'status', m.status
              ) ORDER BY c.name), '[]'::jsonb)
              FROM club_members m JOIN clubs c ON c.id = m.club_id
             WHERE m.user_id = p_user_id)
      ),
      'social_pages', jsonb_build_object(
          'pages_owned', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'id', id, 'page_type', page_type, 'name', name, 'slug', slug,
                'linked_entity_type', linked_entity_type,
                'follower_count', follower_count
              ) ORDER BY name), '[]'::jsonb)
              FROM social_pages WHERE owner_id = p_user_id),
          'pages_followed_count', (
            SELECT COUNT(*) FROM social_page_followers WHERE user_id = p_user_id),
          'pages_followed_preview', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'page_id', sp.id, 'name', sp.name, 'slug', sp.slug, 'page_type', sp.page_type
              ) ORDER BY f.created_at DESC), '[]'::jsonb)
              FROM (SELECT * FROM social_page_followers 
                     WHERE user_id = p_user_id ORDER BY created_at DESC LIMIT 5) f
              JOIN social_pages sp ON sp.id = f.page_id)
      ),
      'connections', jsonb_build_object(
          'friends_count', (
            SELECT COUNT(*) FROM friendships 
             WHERE (user_id = p_user_id OR friend_id = p_user_id) AND status = 'accepted'),
          'friends_preview', CASE WHEN v_is_self THEN (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'id', p.id, 'display_name', p.display_name, 'username', p.username,
                'avatar_url', p.avatar_url
              ) ORDER BY p.display_name), '[]'::jsonb)
              FROM (SELECT CASE WHEN user_id = p_user_id THEN friend_id ELSE user_id END AS friend_uid
                      FROM friendships 
                     WHERE (user_id = p_user_id OR friend_id = p_user_id) 
                       AND status = 'accepted' LIMIT 5) f
              JOIN profiles p ON p.id = f.friend_uid
          ) ELSE NULL END
      ),
      'engagement', CASE WHEN v_is_self THEN jsonb_build_object(
          'unread_notifications', 
              (SELECT COUNT(*) FROM notifications 
                WHERE user_id = p_user_id AND COALESCE(read, false) = false),
          'recent_notifications', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'id', id, 'type', type, 'title', title, 'message', message,
                'read', read, 'link', link, 'action_url', action_url,
                'created_at', created_at
              ) ORDER BY created_at DESC), '[]'::jsonb)
              FROM (SELECT * FROM notifications 
                     WHERE user_id = p_user_id 
                     ORDER BY created_at DESC LIMIT 5) n
          ),
          'diamond_balance', v_profile.diamonds,
          'last_home_game_checkin', 
              (SELECT MAX(checked_in_at) FROM commander_home_rsvps 
                WHERE user_id = p_user_id)
        ) ELSE NULL END,
      'generated_at', now(),
      'viewer_is_self', v_is_self
    ) INTO v_result;
    RETURN v_result;
END; $$;


ALTER FUNCTION public.get_unified_user_profile(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_unified_user_profile(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_unified_user_profile(p_user_id uuid) IS 'Phase 29/C: Single RPC returning a user''s complete footprint across home games, Poker Near Me, Commander, clubs, and social pages. Proof that the platform is ONE system.';


--
-- Name: get_union_bbj_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_union_bbj_status(p_union_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE v_p record;
BEGIN
  SELECT main_balance, backup_balance, promo_balance, status, hands_contributed
    INTO v_p FROM bbj_pools
   WHERE union_id = p_union_id AND status = 'active' LIMIT 1;
  IF v_p IS NULL THEN
    RETURN jsonb_build_object('balance', 0, 'active', false, 'note', 'no active union pool');
  END IF;
  RETURN jsonb_build_object(
    'balance', round(v_p.main_balance, 2), 'active', true,
    'main_balance', round(v_p.main_balance, 2),
    'backup_balance', round(v_p.backup_balance, 2),
    'promo_balance', round(v_p.promo_balance, 2),
    'hands_contributed', v_p.hands_contributed);
END $$;


ALTER FUNCTION public.get_union_bbj_status(p_union_id uuid) OWNER TO postgres;

--
-- Name: get_union_rake_for_period(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_union_rake_for_period(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, rake_amount numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT c.id, c.name, COALESCE(SUM(rr.rake_amount), 0)
    FROM clubs c
    LEFT JOIN rake_records rr
      ON rr.club_id = c.id
     AND rr.created_at >= p_start AND rr.created_at < p_end
     AND (
           (rr.table_id IS NOT NULL AND EXISTS (
              SELECT 1 FROM tables t
               WHERE t.id = rr.table_id AND t.union_id = p_union_id))
        OR (rr.tournament_id IS NOT NULL AND EXISTS (
              SELECT 1 FROM tournaments tr
               WHERE tr.id = rr.tournament_id AND tr.union_id = p_union_id))
         )
   WHERE c.union_id = p_union_id
   GROUP BY c.id, c.name;
END;
$$;


ALTER FUNCTION public.get_union_rake_for_period(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: get_unique_players_24h(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unique_players_24h(p_club_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_count bigint;
BEGIN
    SELECT COUNT(DISTINCT player_id) INTO v_count FROM (
        SELECT from_user_id AS player_id FROM public.chip_transactions
        WHERE club_id = p_club_id AND transaction_type IN ('table_win', 'table_loss', 'rake')
          AND created_at >= NOW() - INTERVAL '24 hours' AND from_user_id IS NOT NULL
        UNION
        SELECT to_user_id AS player_id FROM public.chip_transactions
        WHERE club_id = p_club_id AND transaction_type IN ('table_win', 'table_loss', 'rake')
          AND created_at >= NOW() - INTERVAL '24 hours' AND to_user_id IS NOT NULL
    ) sub;
    RETURN v_count;
END;
$$;


ALTER FUNCTION public.get_unique_players_24h(p_club_id uuid) OWNER TO postgres;

--
-- Name: get_unread_leak_alerts(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unread_leak_alerts(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text;
  v_caller_uid uuid;
  v_result jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  v_caller_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '');
  v_caller_uid := auth.uid();
  IF v_caller_role = 'authenticated' THEN
    IF v_caller_uid IS NULL OR p_user_id <> v_caller_uid THEN
      RAISE WARNING 'get_unread_leak_alerts: spoof attempt by % targeting %', v_caller_uid, p_user_id;
      RETURN '[]'::jsonb;
    END IF;
  ELSIF v_caller_role = 'anon' OR v_caller_role = '' THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(a)::jsonb ORDER BY a.created_at DESC), '[]'::jsonb)
  INTO v_result
  FROM public.jarvis_leak_alerts a
  WHERE a.user_id = p_user_id
    AND COALESCE(a.read, false) = false
    AND COALESCE(a.dismissed, false) = false
  LIMIT 100;

  RETURN COALESCE(v_result, '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'get_unread_leak_alerts failed for %: % %', p_user_id, SQLERRM, SQLSTATE;
  RETURN '[]'::jsonb;
END;
$$;


ALTER FUNCTION public.get_unread_leak_alerts(p_user_id uuid) OWNER TO postgres;

--
-- Name: get_user_achievements(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_achievements(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text;
  v_caller_uid uuid;
  v_result jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  v_caller_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '');
  v_caller_uid := auth.uid();
  IF v_caller_role = 'authenticated' THEN
    IF v_caller_uid IS NULL OR p_user_id <> v_caller_uid THEN
      RAISE WARNING 'get_user_achievements: spoof attempt by % targeting %', v_caller_uid, p_user_id;
      RETURN '[]'::jsonb;
    END IF;
  ELSIF v_caller_role = 'anon' OR v_caller_role = '' THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.unlocked DESC, t.unlocked_at DESC NULLS LAST), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      tua.id,
      tua.achievement_id,
      tua.achievement_key,
      tua.progress,
      tua.target,
      tua.unlocked,
      tua.unlocked_at,
      ta.name,
      ta.description,
      ta.icon,
      ta.category,
      ta.tier,
      ta.diamond_reward
    FROM public.training_user_achievements tua
    LEFT JOIN public.training_achievements ta ON ta.id = tua.achievement_id
    WHERE tua.user_id = p_user_id
  ) t;

  RETURN COALESCE(v_result, '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'get_user_achievements failed for %: % %', p_user_id, SQLERRM, SQLSTATE;
  RETURN '[]'::jsonb;
END;
$$;


ALTER FUNCTION public.get_user_achievements(p_user_id uuid) OWNER TO postgres;

--
-- Name: get_user_cross_product_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_cross_product_summary(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN 
        RAISE EXCEPTION 'UNAUTHORIZED'; 
    END IF;
    RETURN jsonb_build_object(
        'home_groups_owned', (SELECT COUNT(*) FROM commander_home_groups WHERE owner_id = p_user_id),
        'home_groups_joined', (SELECT COUNT(*) FROM commander_home_members 
                                WHERE user_id = p_user_id AND status = 'approved'),
        'venues_followed', (SELECT COUNT(*) FROM commander_venue_followers WHERE user_id = p_user_id),
        'venues_managed', (SELECT COUNT(*) FROM venue_managers 
                            WHERE user_id = p_user_id AND is_active = true),
        'venues_claimed_as_owner', (SELECT COUNT(*) FROM poker_venues WHERE claimed_by = p_user_id),
        'clubs_joined', (SELECT COUNT(*) FROM club_members WHERE user_id = p_user_id),
        'social_pages_owned', (SELECT COUNT(*) FROM social_pages WHERE owner_id = p_user_id),
        'social_pages_followed', (SELECT COUNT(*) FROM social_page_followers WHERE user_id = p_user_id),
        'unread_notifications', (SELECT COUNT(*) FROM notifications 
                                   WHERE user_id = p_user_id AND COALESCE(read, false) = false),
        'diamonds', (SELECT diamonds FROM profiles WHERE id = p_user_id),
        'has_commander_access', EXISTS(
            SELECT 1 FROM poker_venues 
             WHERE (claimed_by = p_user_id OR id IN (
                    SELECT venue_id FROM venue_managers 
                     WHERE user_id = p_user_id AND is_active = true))
               AND commander_enabled = true
        ),
        'generated_at', now()
    );
END; $$;


