--
-- Name: get_user_level_stats(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_level_stats(p_user_id uuid, p_level_id integer) RETURNS TABLE(total_questions bigint, correct_answers bigint, accuracy numeric, avg_ev_loss numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
      SELECT
        count(*)::bigint,
        count(*) FILTER (WHERE a.is_correct)::bigint,
        CASE WHEN count(*) = 0 THEN 0::numeric
             ELSE round(100.0 * count(*) FILTER (WHERE a.is_correct) / count(*), 2) END,
        COALESCE(round(avg(a.ev_loss)::numeric, 4), 0)
      FROM public.training_answers a
      WHERE a.user_id = p_user_id
        AND a.level = p_level_id;
    $$;


