COMMENT ON FUNCTION public.get_venue_public_detail(p_venue_slug text, p_venue_id integer, p_caller_user_id uuid) IS 'Phase 27/A: Single-call public venue page data. Safe for anon. Used by /poker-near-me/[slug].';


--
-- Name: get_venue_sitemap_data(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_venue_sitemap_data(p_limit integer DEFAULT 1000, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE v_result jsonb; v_total int;
BEGIN
    p_limit := LEAST(GREATEST(p_limit, 1), 5000);
    p_offset := GREATEST(p_offset, 0);
    SELECT COUNT(*) INTO v_total FROM poker_venues 
     WHERE slug IS NOT NULL AND COALESCE(is_active,true) AND NOT COALESCE(is_suppressed,false);

    SELECT jsonb_build_object(
        'generated_at', NOW(),
        'total', v_total,
        'offset', p_offset, 'limit', p_limit,
        'has_more', p_offset + p_limit < v_total,
        'venues', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'slug', slug, 'state', state, 'city', city,
                'name', name, 'last_modified', last_scraped_at,
                'url_path', '/poker-near-me/' || 
                            lower(COALESCE(state, 'us')) || '/' ||
                            COALESCE(regexp_replace(lower(city), '[^a-z0-9]+', '-', 'g'), 'city') || '/' ||
                            slug
            ) ORDER BY last_scraped_at DESC NULLS LAST, id)
              FROM (SELECT id, slug, state, city, name, last_scraped_at
                      FROM poker_venues 
                     WHERE slug IS NOT NULL 
                       AND COALESCE(is_active,true) AND NOT COALESCE(is_suppressed,false)
                     ORDER BY last_scraped_at DESC NULLS LAST, id
                     LIMIT p_limit OFFSET p_offset) t
        ), '[]'::jsonb)
    ) INTO v_result;
    RETURN v_result;
END; $$;


ALTER FUNCTION public.get_venue_sitemap_data(p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: get_visible_live_comments(uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_visible_live_comments(p_stream_id uuid, p_limit integer DEFAULT 50, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(id uuid, stream_id uuid, user_id uuid, author_name text, text text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT lc.id, lc.stream_id, lc.user_id, lc.author_name, lc.text, lc.created_at
  FROM public.live_comments lc
  WHERE lc.stream_id = p_stream_id
    AND (p_before IS NULL OR lc.created_at < p_before)
    AND (
      auth.uid() IS NULL
      OR (
        NOT EXISTS (
          SELECT 1 FROM public.blocked_users b
          WHERE b.blocker_id = auth.uid() AND b.blocked_id = lc.user_id
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.blocked_users b
          WHERE b.blocker_id = lc.user_id AND b.blocked_id = auth.uid()
        )
      )
    )
  ORDER BY lc.created_at DESC
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 50), 500));
$$;


