--
-- Name: get_visible_live_streams(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_visible_live_streams() RETURNS TABLE(id uuid, broadcaster_id uuid, title text, description text, thumbnail_url text, preview_clip_url text, preview_updated_at timestamp with time zone, status text, viewer_count integer, peak_viewers integer, reaction_count integer, category text, started_at timestamp with time zone, livekit_room text, broadcaster_username text, broadcaster_full_name text, broadcaster_avatar text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    s.id, s.broadcaster_id, s.title, s.description, s.thumbnail_url,
    s.preview_clip_url, s.preview_updated_at, s.status, s.viewer_count,
    s.peak_viewers, s.reaction_count, s.category, s.started_at, s.livekit_room,
    p.username, p.full_name, p.avatar_url
  FROM public.live_streams s
  LEFT JOIN public.profiles p ON p.id = s.broadcaster_id
  WHERE s.status = 'live'
    AND (
      auth.uid() IS NULL
      OR (
        -- Caller has not blocked the broadcaster
        NOT EXISTS (
          SELECT 1 FROM public.blocked_users b
          WHERE b.blocker_id = auth.uid() AND b.blocked_id = s.broadcaster_id
        )
        -- And the broadcaster has not blocked the caller
        AND NOT EXISTS (
          SELECT 1 FROM public.blocked_users b
          WHERE b.blocker_id = s.broadcaster_id AND b.blocked_id = auth.uid()
        )
      )
    )
  ORDER BY s.started_at DESC;
$$;


ALTER FUNCTION public.get_visible_live_streams() OWNER TO postgres;

--
-- Name: FUNCTION get_visible_live_streams(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_visible_live_streams() IS 'Live-feed list excluding mutually-blocked broadcaster/viewer pairs. Replaces LiveStreamService.getLiveStreams direct SELECT. Anonymous (auth.uid() IS NULL) callers get the unfiltered list to preserve existing public-read behaviour.';


--
-- Name: get_waitlist_position(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_waitlist_position(p_table_id uuid, p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_pos integer;
BEGIN
  SELECT position INTO v_pos
  FROM table_waitlist
  WHERE table_id = p_table_id AND user_id = p_user_id
    AND status IN ('waiting', 'notified')
  LIMIT 1;
  RETURN COALESCE(v_pos, 0);
END;
$$;


