--
-- Name: has_commander_access(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.has_commander_access(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role text := coalesce(current_setting('request.jwt.claims', true)::jsonb->>'role', '');
  v_uid  uuid := auth.uid();
  v_target uuid := p_user_id;
begin
  if v_role <> 'service_role' then
    if v_uid is null then return false; end if;   -- anon: nothing to see
    v_target := v_uid;                            -- callers may only ask about themselves
  end if;

  return
    exists (select 1 from clubs where owner_id = v_target) or
    exists (select 1 from commander_subscriptions where owner_id = v_target) or
    exists (
      select 1 from commander_staff
      where (user_id = v_target or linked_user_id = v_target)
        and role in ('owner','manager')
        and venue_id is not null
    ) or
    exists (select 1 from commander_home_groups where owner_id = v_target);
end
$$;


ALTER FUNCTION public.has_commander_access(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION has_commander_access(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.has_commander_access(p_user_id uuid) IS 'Bug-fix 2026-05-10: canonical Commander access check used by /api/check-access. Returns true if user owns clubs, owns commander_subscriptions, is staff with owner/manager role (matched on user_id OR linked_user_id to handle multi-account users), or owns a home group. Replaces the previous narrow check that only looked at clubs.owner_id and missed users like Dan Bekavac who own venues via commander_staff with a separate billing-email auth identity.';


