--
-- Name: increment_bonus_progress(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.increment_bonus_progress(p_bonus_id uuid, p_user_id uuid, p_amount integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_new integer;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND (auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_user_id) THEN
    RAISE EXCEPTION 'Cannot update bonus progress for another user';
  END IF;
  IF COALESCE(p_amount, 0) <= 0 OR p_amount > 1000 THEN
    RAISE EXCEPTION 'Invalid progress amount %', p_amount;
  END IF;

  INSERT INTO public.user_bonus_progress (user_id, bonus_id, progress, updated_at)
  VALUES (p_user_id, p_bonus_id, p_amount, now())
  ON CONFLICT (user_id, bonus_id)
  DO UPDATE SET progress = user_bonus_progress.progress + EXCLUDED.progress, updated_at = now()
  RETURNING progress INTO v_new;
  RETURN v_new;
END;
$$;


