    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('success', 'failed') AND (OLD.status IS NULL OR OLD.status != NEW.status) THEN
    NEW.run_count = COALESCE(OLD.run_count, 0) + 1;
  END IF;
  RETURN NEW;
END;
$$;


