--
-- Name: increment_column(text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.increment_column(table_name text, column_name text, row_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
BEGIN
  /* Before 2026-09-07 this was `UPDATE public.%I SET %I = %I + 1` on ANY
     table and column, with every error swallowed. It is a door onto every
     balance column on the platform that names no table in its source, so the
     register's drift scan could not see it. The allowlist is the declaration;
     widening it is a registry note, not a code edit. */
  IF row_id IS NULL THEN
    RAISE EXCEPTION 'increment_column: row_id is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM (VALUES ('table_templates', 'use_count')) v(t, f)
     WHERE v.t = table_name AND v.f = column_name
  ) THEN
    RAISE EXCEPTION 'increment_column: %.% is not on the allowlist (table_templates.use_count). A balance column is never reached through a generic door.',
      table_name, column_name USING ERRCODE = 'P0403';
  END IF;
  EXECUTE format('UPDATE public.%I SET %I = COALESCE(%I, 0) + 1 WHERE id = $1', table_name, column_name, column_name)
    USING row_id;
END $_$;


ALTER FUNCTION public.increment_column(table_name text, column_name text, row_id uuid) OWNER TO postgres;

--
-- Name: increment_home_game_stats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.increment_home_game_stats(p_game_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_group_id uuid;
  v_host_id uuid;
begin
  select group_id, host_id into v_group_id, v_host_id
    from commander_home_games where id = p_game_id;
  if v_group_id is null then
    return;
  end if;

  -- Attendance for confirmed yes-RSVPs
  update commander_home_members m
     set games_attended = coalesce(m.games_attended,0) + 1,
         last_attended = now()
   where m.group_id = v_group_id
     and m.user_id in (
       select r.user_id from commander_home_rsvps r
        where r.game_id = p_game_id and r.response = 'yes'
     );

  -- Host credit
  update commander_home_members m
     set games_hosted = coalesce(m.games_hosted,0) + 1
   where m.group_id = v_group_id and m.user_id = v_host_id;

  update commander_home_groups g
     set games_hosted = coalesce(g.games_hosted,0) + 1,
         last_activity_at = now()
   where g.id = v_group_id;
end;
$$;


