--
-- Name: increment_post_count(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.increment_post_count(p_post_id uuid, p_field text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  _allowed_fields text[] := ARRAY[
    'like_count', 'comment_count', 'share_count', 'view_count'
  ];
BEGIN
  -- Allowlist guard: reject arbitrary column names
  IF NOT (p_field = ANY(_allowed_fields)) THEN
    RAISE EXCEPTION 'increment_post_count: invalid field %', p_field;
  END IF;

  EXECUTE format(
    'UPDATE public.social_posts SET %I = GREATEST(COALESCE(%I, 0) + 1, 0) WHERE id = $1',
    p_field, p_field
  ) USING p_post_id;
END;
$_$;


