--
-- Name: increment_union_chip_balance(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.increment_union_chip_balance(p_union_id uuid, p_amount numeric) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new_balance NUMERIC;
BEGIN
  -- Atomic increment - no read-then-write race condition
  UPDATE union_wallets
  SET chip_balance = chip_balance + p_amount
  WHERE union_id = p_union_id
  RETURNING chip_balance INTO v_new_balance;

  -- If union_wallets row doesn't exist, try the unions table as fallback
  IF NOT FOUND THEN
    UPDATE unions
    SET chip_balance = COALESCE(chip_balance, 0) + p_amount
    WHERE id = p_union_id
    RETURNING chip_balance INTO v_new_balance;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Union % not found in union_wallets or unions', p_union_id;
    END IF;
  END IF;

  RETURN v_new_balance;
END;
$$;


ALTER FUNCTION public.increment_union_chip_balance(p_union_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: FUNCTION increment_union_chip_balance(p_union_id uuid, p_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.increment_union_chip_balance(p_union_id uuid, p_amount numeric) IS 'DEPRECATED 2026-08-19 - DO NOT USE. Moves chips WITHOUT writing any transaction record, so the movement never reaches the transaction reports. Verified dead: 0 app callers, 0 triggers, 0 SQL callers, service_role-only. Use the audited equivalents instead: fn_credit_chips / fn_debit_chips / fn_transfer_chips / distribute_chips / fn_union_send_chips_to_club / transfer_chips_agent_to_player - all log, lock FOR UPDATE and guard balances.';


