--
-- Name: initialize_player_profile(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_player_profile(p_user_id uuid, p_full_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_username text DEFAULT NULL::text) RETURNS TABLE(player_number bigint, success boolean, message text)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_player_number TEXT;
    v_is_restricted BOOLEAN;
    v_access_tier TEXT;
    v_is_employee BOOLEAN;
    v_first_name TEXT;
    v_last_name TEXT;
BEGIN
    -- Split full_name into first/last
    v_first_name := split_part(COALESCE(p_full_name, ''), ' ', 1);
    v_last_name := CASE
      WHEN position(' ' in COALESCE(p_full_name, '')) > 0
      THEN substring(COALESCE(p_full_name, '') from position(' ' in COALESCE(p_full_name, '')) + 1)
      ELSE ''
    END;

    -- Check if this is an employee
    v_is_employee := (COALESCE(p_email, '') ILIKE '%@smarter.poker');

    -- Assign player number (cast NEXTVAL to TEXT to match column type)
    IF v_is_employee THEN
        DECLARE v_tries int := 0;
        BEGIN
            LOOP
                v_player_number := NEXTVAL('employee_number_seq')::TEXT;
                EXIT WHEN NOT EXISTS (
                    SELECT 1 FROM public.profiles WHERE player_number = v_player_number
                );
                v_tries := v_tries + 1;
                IF v_tries > 1000 THEN
                    RAISE EXCEPTION 'initialize_player_profile: no free employee number after 1000 attempts';
                END IF;
            END LOOP;
        END;
    ELSE
        v_player_number := public.fn_next_player_number();
    END IF;

    -- Check restricted states
    v_is_restricted := COALESCE(p_state, '') IN ('WA', 'ID', 'MI', 'NV', 'CA');
    v_access_tier := CASE WHEN v_is_restricted THEN 'Restricted_Tier' ELSE 'Full_Access' END;

    -- Insert or update profile
    INSERT INTO profiles (
        id, player_number, full_name, first_name, last_name,
        email, phone, city, state, username,
        diamonds, diamond_balance, diamond_multiplier, streak_count,
        skill_tier, access_tier, email_verified, phone_verified,
        is_vip, vip_tier, vip_expires_at,
        created_at, last_login
    ) VALUES (
        p_user_id, v_player_number, p_full_name, v_first_name, v_last_name,
        p_email, p_phone, p_city, p_state, p_username,
        0, 0, 1.0, 0,
        'Newcomer', v_access_tier, false, false,
        true, 'monthly', NOW() + INTERVAL '30 days',
        NOW(), NOW()
    )
    ON CONFLICT (id) DO UPDATE SET
        full_name = EXCLUDED.full_name,
        first_name = EXCLUDED.first_name,
        last_name = EXCLUDED.last_name,
        email = EXCLUDED.email,
        phone = EXCLUDED.phone,
        city = EXCLUDED.city,
        state = EXCLUDED.state,
        username = EXCLUDED.username,
        access_tier = EXCLUDED.access_tier,
        last_login = NOW(),
        player_number = COALESCE(profiles.player_number, EXCLUDED.player_number),
        -- Only grant VIP if user doesn't already have it
        is_vip = CASE
            WHEN profiles.is_vip IS NULL OR profiles.is_vip = false THEN true
            ELSE profiles.is_vip
        END,
        vip_tier = CASE
            WHEN profiles.vip_tier IS NULL THEN 'monthly'
            ELSE profiles.vip_tier
        END,
        vip_expires_at = CASE
            WHEN profiles.vip_expires_at IS NULL THEN NOW() + INTERVAL '30 days'
            ELSE profiles.vip_expires_at
        END;

    -- The welcome 500 are issued by the Mint under signup:<id> (DIAMOND-RULINGS 17), never
    -- inserted into the row. Idempotent: a register row under signup: or seed: means the
    -- grant was already made by another door.
    IF NOT EXISTS (SELECT 1 FROM public.ca_mint_ledger m
                    WHERE m.op_id IN ('signup:' || p_user_id::text, 'seed:' || p_user_id::text)) THEN
        PERFORM public.fn_ca_mint('diamonds', 'player', p_user_id, 500, 'signup grant',
                                  'signup:' || p_user_id::text, 'promotional');
    END IF;

    -- Get the actual player_number (cast TEXT to BIGINT for return type)
    RETURN QUERY
        SELECT p.player_number::BIGINT, true::BOOLEAN, 'Profile initialized'::TEXT
        FROM profiles p
        WHERE p.id = p_user_id;

EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT 0::BIGINT, false::BOOLEAN, SQLERRM::TEXT;
END;
$$;


ALTER FUNCTION public.initialize_player_profile(p_user_id uuid, p_full_name text, p_email text, p_phone text, p_city text, p_state text, p_username text) OWNER TO postgres;

