--
-- Name: initialize_user_diamonds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_user_diamonds() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    /* 2026-09-07: this wrote (100, 100) into a MIRROR of profiles.diamonds.
       The canonical store defaults to 0 and no profile in fourteen days held a
       canonical 100, so the number was never a balance - it was a mirror
       disagreeing with the thing it mirrors. It reads the canonical store now;
       at signup there is usually no profile row yet, which reads 0, and
       trg_diamond_side_tables_follow_profiles writes the true figure the
       moment the profile is created. */
    INSERT INTO public.user_diamonds (user_id, balance, lifetime_earned)
    VALUES (NEW.id,
            COALESCE((SELECT GREATEST(COALESCE(p.diamonds, 0), 0)
                        FROM public.profiles p WHERE p.id = NEW.id), 0),
            0)
    ON CONFLICT (user_id) DO NOTHING;

    INSERT INTO public.user_daily_streaks (user_id)
    VALUES (NEW.id)
    ON CONFLICT (user_id) DO NOTHING;

    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    BEGIN
      INSERT INTO public.signup_errors (user_id, email, trigger_name, error_code, error_msg)
      VALUES (NEW.id, NEW.email, 'initialize_user_diamonds', SQLSTATE, SQLERRM);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.initialize_user_diamonds() OWNER TO postgres;

--
-- Name: FUNCTION initialize_user_diamonds(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.initialize_user_diamonds() IS 'Signup trigger on auth.users. Creates the user_diamonds mirror row and the daily-streak row. It reads the canonical store for the balance and never invents one: it seeded 100 until 2026-09-07, which no account ever held in profiles.diamonds and which the supply meter never counted.';


--
-- Name: insert_hole_cards(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_hole_cards(p_table_id uuid, p_hand_number integer, p_cards text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cards    JSONB;
  v_record   JSONB;
  v_user_id  UUID;
BEGIN
  -- Parse the JSON string argument (server sends JSON.stringify'd array)
  v_cards := p_cards::JSONB;

  -- Clean up rows from hands earlier than this one (keep table lean)
  DELETE FROM public.table_hole_cards
  WHERE table_id = p_table_id
    AND hand_number < p_hand_number;

  -- Upsert each player's hole card row
  FOR v_record IN SELECT * FROM jsonb_array_elements(v_cards)
  LOOP
    BEGIN
      v_user_id := (v_record->>'user_id')::UUID;

      INSERT INTO public.table_hole_cards (
        table_id,
        hand_number,
        user_id,
        seat_number,
        cards
      ) VALUES (
        p_table_id,
        p_hand_number,
        v_user_id,
        (v_record->>'seat_number')::INTEGER,
        v_record->'cards'
      )
      ON CONFLICT (table_id, hand_number, user_id)
      DO UPDATE SET
        cards       = EXCLUDED.cards,
        seat_number = EXCLUDED.seat_number,
        created_at  = NOW();

    EXCEPTION WHEN invalid_text_representation THEN
      RAISE WARNING '[insert_hole_cards] Skipped row with invalid user_id: %', v_record->>'user_id';
    END;
  END LOOP;
END;
$$;


ALTER FUNCTION public.insert_hole_cards(p_table_id uuid, p_hand_number integer, p_cards text) OWNER TO postgres;

--
-- Name: insert_live_comment_with_slowmode(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_live_comment_with_slowmode(p_stream_id uuid, p_user_id uuid, p_text text, p_author_name text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_slow_mode boolean;
  v_last_comment timestamptz;
  v_broadcaster_id uuid;
BEGIN
  -- Check if slow mode is on for this stream
  SELECT slow_mode, broadcaster_id INTO v_slow_mode, v_broadcaster_id
  FROM live_streams WHERE id = p_stream_id;

  -- Broadcaster is exempt from slow mode
  IF v_slow_mode AND p_user_id != v_broadcaster_id THEN
    SELECT MAX(created_at) INTO v_last_comment
    FROM live_comments WHERE stream_id = p_stream_id AND user_id = p_user_id;
    
    IF v_last_comment IS NOT NULL AND v_last_comment > NOW() - INTERVAL '10 seconds' THEN
      RETURN jsonb_build_object('success', false, 'error', 'Slow mode: wait 10 seconds between comments');
    END IF;
  END IF;

  -- Check if user is banned
  IF EXISTS (SELECT 1 FROM live_bans WHERE stream_id = p_stream_id AND banned_user_id = p_user_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'You are banned from this stream');
  END IF;

  INSERT INTO live_comments (stream_id, user_id, text, author_name)
  VALUES (p_stream_id, p_user_id, p_text, p_author_name);

  RETURN jsonb_build_object('success', true);
END; $$;


ALTER FUNCTION public.insert_live_comment_with_slowmode(p_stream_id uuid, p_user_id uuid, p_text text, p_author_name text) OWNER TO postgres;

--
-- Name: is_admin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.role IN ('admin','god')); $$;


