--
-- Name: issue_manual_comp(integer, uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_manual_comp(p_venue_id integer, p_player_id uuid, p_amount numeric, p_description text, p_staff_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_balance commander_comp_balances%rowtype;
  v_before numeric := 0;
  v_after numeric := 0;
  v_txn_id uuid;
begin
  if p_amount = 0 then
    raise exception 'Amount must be non-zero';
  end if;

  select * into v_balance
    from commander_comp_balances
   where venue_id = p_venue_id and player_id = p_player_id
   for update;

  if found then
    if v_balance.is_frozen then
      raise exception 'Player comp balance is frozen';
    end if;
    v_before := coalesce(v_balance.current_balance, 0);
    v_after := v_before + p_amount;
    if v_after < 0 then
      raise exception 'Insufficient comp balance for adjustment';
    end if;
    update commander_comp_balances
       set current_balance = v_after,
           lifetime_earned = coalesce(lifetime_earned,0) + greatest(p_amount, 0),
           lifetime_adjusted = coalesce(lifetime_adjusted,0) + least(p_amount, 0),
           last_earned_at = case when p_amount > 0 then now() else last_earned_at end,
           updated_at = now()
     where id = v_balance.id;
  else
    if p_amount < 0 then
      raise exception 'Insufficient comp balance for adjustment';
    end if;
    v_before := 0;
    v_after := p_amount;
    insert into commander_comp_balances (venue_id, player_id, current_balance, lifetime_earned, last_earned_at, updated_at)
    values (p_venue_id, p_player_id, p_amount, p_amount, now(), now())
    returning * into v_balance;
  end if;

  insert into commander_comp_transactions
    (venue_id, player_id, balance_id, transaction_type, amount, balance_before, balance_after,
     source_type, approved_by, description, created_at)
  values
    (p_venue_id, p_player_id, v_balance.id,
     case when p_amount >= 0 then 'manual' else 'adjustment' end,
     p_amount, v_before, v_after, 'manual', p_staff_id, p_description, now())
  returning id into v_txn_id;

  return v_txn_id;
end;
$$;


ALTER FUNCTION public.issue_manual_comp(p_venue_id integer, p_player_id uuid, p_amount numeric, p_description text, p_staff_id uuid) OWNER TO postgres;

--
-- Name: join_flash_pool(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.join_flash_pool(p_pool_id uuid, p_user_id uuid, p_buy_in numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pool record; v_ok boolean; v_bal numeric;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND (auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_user_id) THEN
    RAISE EXCEPTION 'Cannot join a pool for another user';
  END IF;

  SELECT * INTO v_pool FROM public.flash_pools
   WHERE id = p_pool_id AND status IN ('active','waiting') FOR UPDATE;
  IF v_pool.id IS NULL THEN RAISE EXCEPTION 'Pool not found or closed'; END IF;

  IF p_buy_in IS NULL
     OR p_buy_in < COALESCE(v_pool.buy_in_min, v_pool.big_blind * 40)
     OR p_buy_in > COALESCE(v_pool.buy_in_max, v_pool.big_blind * 200) THEN
    RAISE EXCEPTION 'Buy-in outside the allowed range';
  END IF;

  IF EXISTS (SELECT 1 FROM public.flash_pool_players
              WHERE pool_id = p_pool_id AND user_id = p_user_id AND status <> 'left') THEN
    RAISE EXCEPTION 'Already in this pool';
  END IF;

  -- Debit through the whitelisted, ledger-logged path. The Phase 4.1.6a guard
  -- rejects any direct wallets UPDATE from this function (probe-proven in v1
  -- of this migration), which is exactly the intended design.
  v_ok := public.atomic_deduct_wallet_and_log(
            p_user_id, p_buy_in, 'buyin',
            'Flash pool buy-in ' || v_pool.small_blind || '/' || v_pool.big_blind,
            NULL, NULL, p_pool_id);
  IF NOT COALESCE(v_ok, false) THEN
    RAISE EXCEPTION 'Insufficient chips for this buy-in';
  END IF;

  SELECT balance INTO v_bal FROM public.wallets
   WHERE user_id = p_user_id AND wallet_type = 'PLAYER';

  INSERT INTO public.flash_pool_players (pool_id, user_id, buy_in)
  VALUES (p_pool_id, p_user_id, p_buy_in)
  ON CONFLICT (pool_id, user_id)
  DO UPDATE SET buy_in = EXCLUDED.buy_in, status = 'waiting', joined_at = now(), left_at = NULL;

  UPDATE public.flash_pools
     SET active_players = (SELECT count(*) FROM public.flash_pool_players
                            WHERE pool_id = p_pool_id AND status <> 'left')
   WHERE id = p_pool_id;

  RETURN jsonb_build_object('ok', true, 'pool_id', p_pool_id, 'buy_in', p_buy_in, 'balance_after', v_bal);
END;
$$;


ALTER FUNCTION public.join_flash_pool(p_pool_id uuid, p_user_id uuid, p_buy_in numeric) OWNER TO postgres;

--
-- Name: join_home_group(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.join_home_group(p_group_id uuid, p_caller_user_id uuid, p_invite_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_group public.commander_home_groups%ROWTYPE;
  v_existing public.commander_home_members%ROWTYPE;
  v_new_status text;
  v_new_id uuid;
  v_failed_attempts integer;
  v_submitted_code text;
  v_code_kind text;
  v_allow_declined_re_request boolean;
BEGIN
  IF auth.uid() IS NULL
     OR p_caller_user_id IS NULL
     OR auth.uid() <> p_caller_user_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED';
  END IF;

  IF p_group_id IS NULL THEN
    RAISE EXCEPTION 'GROUP_NOT_FOUND';
  END IF;

  -- Serialize the same user's membership transition. The group-row lock below
  -- also pins the invite/privacy/owner configuration for the decision; joins
  -- to one group therefore serialize briefly while unrelated groups proceed.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext(p_group_id::text),
    pg_catalog.hashtext(p_caller_user_id::text)
  );

  SELECT * INTO v_group
    FROM public.commander_home_groups
   WHERE id = p_group_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;
  IF NOT coalesce(v_group.is_active, false) THEN RAISE EXCEPTION 'GROUP_INACTIVE'; END IF;
  IF v_group.owner_id = p_caller_user_id THEN RAISE EXCEPTION 'ALREADY_OWNER'; END IF;

  v_submitted_code := upper(btrim(p_invite_code));

  IF coalesce(v_group.is_private, true) THEN
    IF nullif(v_submitted_code, '') IS NULL THEN
      RAISE EXCEPTION 'INVITE_CODE_REQUIRED';
    END IF;

    SELECT count(*) INTO v_failed_attempts
      FROM public.commander_home_join_attempts
     WHERE user_id = p_caller_user_id
       AND succeeded = false
       AND attempted_at > now() - interval '1 hour';

    IF v_failed_attempts >= 10 THEN
      INSERT INTO public.commander_home_join_attempts(user_id, group_id, succeeded)
      VALUES (p_caller_user_id, p_group_id, false);
      RETURN jsonb_build_object(
        'success', false,
        'error', 'RATE_LIMITED',
        'hint', 'Too many failed invite-code attempts. Try again in 1 hour.'
      );
    END IF;

    v_code_kind := CASE
      WHEN v_group.invite_code IS NOT NULL
       AND upper(btrim(v_group.invite_code)) = v_submitted_code THEN 'invite'
      WHEN v_group.club_code IS NOT NULL
       AND upper(btrim(v_group.club_code)) = v_submitted_code THEN 'share'
      ELSE NULL
    END;

    IF v_code_kind IS NULL THEN
      INSERT INTO public.commander_home_join_attempts(user_id, group_id, succeeded)
      VALUES (p_caller_user_id, p_group_id, false);
      RETURN jsonb_build_object('success', false, 'error', 'INVALID_INVITE_CODE');
    END IF;
  END IF;

  SELECT * INTO v_existing
    FROM public.commander_home_members
   WHERE group_id = p_group_id
     AND user_id = p_caller_user_id
   FOR UPDATE;

  IF FOUND THEN
    CASE v_existing.status
      WHEN 'approved' THEN
        INSERT INTO public.commander_home_join_attempts(user_id, group_id, succeeded)
        VALUES (p_caller_user_id, p_group_id, true);
        RETURN jsonb_build_object(
          'success', true,
          'already_member', true,
          'status', 'approved',
          'role', v_existing.role,
          'member_id', v_existing.id
        );
      WHEN 'pending' THEN
        INSERT INTO public.commander_home_join_attempts(user_id, group_id, succeeded)
        VALUES (p_caller_user_id, p_group_id, true);
        RETURN jsonb_build_object(
          'success', true,
          'already_pending', true,
          'status', 'pending',
          'role', v_existing.role,
          'member_id', v_existing.id
        );
      WHEN 'banned' THEN
        INSERT INTO public.commander_home_join_attempts(user_id, group_id, succeeded)
        VALUES (p_caller_user_id, p_group_id, false);
        RETURN jsonb_build_object(
          'success', false,
          'error', 'BANNED',
          'hint', 'user is banned from this group'
        );
      WHEN 'declined' THEN
        -- Exact JSON boolean only. The string "true" is not an opt-in.
        v_allow_declined_re_request := coalesce(
          v_group.settings -> 'allow_declined_re_request' = 'true'::jsonb,
          false
        );
        IF NOT v_allow_declined_re_request THEN
          INSERT INTO public.commander_home_join_attempts(user_id, group_id, succeeded)
          VALUES (p_caller_user_id, p_group_id, false);
          RETURN jsonb_build_object(
            'success', false,
            'error', 'DECLINED',
            'hint', 'the host has not enabled a new membership request'
          );
        END IF;

        UPDATE public.commander_home_members
           SET status = 'pending',
               joined_at = NULL
         WHERE id = v_existing.id;
        INSERT INTO public.commander_home_join_attempts(user_id, group_id, succeeded)
        VALUES (p_caller_user_id, p_group_id, true);
        RETURN jsonb_build_object(
          'success', true,
          're_requested', true,
          'status', 'pending',
          'role', v_existing.role,
          'member_id', v_existing.id,
          'requires_approval', true
        );
      ELSE
        RAISE EXCEPTION 'MEMBERSHIP_STATE_INVALID';
    END CASE;
  END IF;

  -- Public share identifiers never approve a private membership. Only a
  -- secret invite can qualify, and the group's approval setting still wins.
  v_new_status := CASE
    WHEN coalesce(v_group.requires_approval, true) THEN 'pending'
    WHEN coalesce(v_group.is_private, true) AND v_code_kind = 'share' THEN 'pending'
    ELSE 'approved'
  END;

  INSERT INTO public.commander_home_members
    (group_id, user_id, role, status, joined_at, created_at)
  VALUES
    (p_group_id, p_caller_user_id, 'member', v_new_status,
     CASE WHEN v_new_status = 'approved' THEN now() ELSE NULL END,
     now())
  ON CONFLICT (group_id, user_id) WHERE user_id IS NOT NULL DO NOTHING
  RETURNING id INTO v_new_id;

  -- A concurrent legacy/direct insert can still win without participating in
  -- the advisory lock. Treat that as an idempotent replay and return the
  -- canonical stored state rather than leaking SQLSTATE 23505.
  IF v_new_id IS NULL THEN
    SELECT * INTO v_existing
      FROM public.commander_home_members
     WHERE group_id = p_group_id
       AND user_id = p_caller_user_id
     FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'MEMBERSHIP_CONFLICT';
    END IF;

    INSERT INTO public.commander_home_join_attempts(user_id, group_id, succeeded)
    VALUES (
      p_caller_user_id,
      p_group_id,
      v_existing.status IN ('approved', 'pending')
    );

    IF v_existing.status = 'approved' THEN
      RETURN jsonb_build_object(
        'success', true,
        'already_member', true,
        'concurrent_replay', true,
        'status', 'approved',
        'role', v_existing.role,
        'member_id', v_existing.id,
        'requires_approval', false
      );
    END IF;

    IF v_existing.status = 'pending' THEN
      RETURN jsonb_build_object(
        'success', true,
        'already_pending', true,
        'concurrent_replay', true,
        'status', 'pending',
        'role', v_existing.role,
        'member_id', v_existing.id,
        'requires_approval', true
      );
    END IF;

    IF v_existing.status = 'banned' THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'BANNED',
        'hint', 'user is banned from this group'
      );
    END IF;

    IF v_existing.status = 'declined' THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'DECLINED',
        'hint', 'the membership changed while this join was being processed'
      );
    END IF;

    RAISE EXCEPTION 'MEMBERSHIP_STATE_INVALID';
  END IF;

  INSERT INTO public.commander_home_join_attempts(user_id, group_id, succeeded)
  VALUES (p_caller_user_id, p_group_id, true);

  RETURN jsonb_build_object(
    'success', true,
    'status', v_new_status,
    'role', 'member',
    'member_id', v_new_id,
    'requires_approval', v_new_status = 'pending'
  );
END;
$$;


ALTER FUNCTION public.join_home_group(p_group_id uuid, p_caller_user_id uuid, p_invite_code text) OWNER TO postgres;

--
-- Name: FUNCTION join_home_group(p_group_id uuid, p_caller_user_id uuid, p_invite_code text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.join_home_group(p_group_id uuid, p_caller_user_id uuid, p_invite_code text) IS 'Home Games emergency gate: club_code is public/share-only, invite_code is secret, declined retries require an exact host opt-in, and concurrent joins return one canonical membership.';


--
-- Name: join_training_study_group(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.join_training_study_group(p_group_id uuid, p_user_id uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_owner_id uuid;
  v_max_members integer;
  v_member_count integer;
BEGIN
  SELECT owner_id, max_members
  INTO v_owner_id, v_max_members
  FROM public.training_study_groups
  WHERE id = p_group_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN 'not_found';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.training_study_group_members
    WHERE group_id = p_group_id AND user_id = p_user_id
  ) THEN
    RETURN 'joined';
  END IF;

  SELECT count(*)::integer
  INTO v_member_count
  FROM public.training_study_group_members
  WHERE group_id = p_group_id;

  IF v_member_count >= v_max_members THEN
    RETURN 'full';
  END IF;

  INSERT INTO public.training_study_group_members (group_id, user_id, role)
  VALUES (
    p_group_id,
    p_user_id,
    CASE WHEN p_user_id = v_owner_id THEN 'owner' ELSE 'member' END
  );

  RETURN 'joined';
END;
$$;


ALTER FUNCTION public.join_training_study_group(p_group_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: join_waitlist(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.join_waitlist(p_table_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_existing uuid;
  v_pos integer;
  v_new_id uuid;
BEGIN
  -- Idempotent: check for active entry
  SELECT id INTO v_existing FROM table_waitlist
  WHERE table_id = p_table_id AND user_id = p_user_id
    AND status IN ('waiting', 'notified');
  IF v_existing IS NOT NULL THEN
    SELECT COALESCE(position, 0) INTO v_pos FROM table_waitlist WHERE id = v_existing;
    RETURN jsonb_build_object('success', true, 'already_on_waitlist', true, 'position', v_pos);
  END IF;

  -- Calculate next position
  SELECT COALESCE(MAX(position), 0) + 1 INTO v_pos
  FROM table_waitlist
  WHERE table_id = p_table_id AND status IN ('waiting', 'notified');

  INSERT INTO table_waitlist (id, table_id, user_id, position, status, created_at)
  VALUES (gen_random_uuid(), p_table_id, p_user_id, v_pos, 'waiting', NOW())
  RETURNING id INTO v_new_id;

  RETURN jsonb_build_object('success', true, 'position', v_pos, 'entry_id', v_new_id);
END;
$$;


ALTER FUNCTION public.join_waitlist(p_table_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION join_waitlist(p_table_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.join_waitlist(p_table_id uuid, p_user_id uuid) IS 'BUG 026: fixed table name from non-existent `waitlist` to real `table_waitlist`. Now idempotent, assigns position, returns jsonb.';


