--
-- Name: leave_home_group(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.leave_home_group(p_group_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group       RECORD;
    v_member      RECORD;
    v_existed     boolean := false;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;

    -- Owner cannot leave - must transfer ownership first
    IF v_group.owner_id = p_caller_user_id THEN
        RAISE EXCEPTION 'OWNER_CANNOT_LEAVE'
              USING HINT = 'transfer ownership first, then leave';
    END IF;

    -- Pass 36: banned users cannot self-leave (ban-evasion prevention)
    SELECT * INTO v_member FROM commander_home_members
      WHERE group_id = p_group_id AND user_id = p_caller_user_id;

    IF FOUND AND v_member.status = 'banned' THEN
        RAISE EXCEPTION 'BANNED_CANNOT_LEAVE'
              USING HINT = 'banned members cannot leave to erase the ban record';
    END IF;

    DELETE FROM commander_home_members
     WHERE group_id = p_group_id
       AND user_id = p_caller_user_id
    RETURNING true INTO v_existed;

    RETURN jsonb_build_object(
        'success', true,
        'group_id', p_group_id,
        'already_gone', COALESCE(NOT v_existed, true)
    );
END;
$$;


ALTER FUNCTION public.leave_home_group(p_group_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION leave_home_group(p_group_id uuid, p_caller_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.leave_home_group(p_group_id uuid, p_caller_user_id uuid) IS 'Self-leave a home group. Pass 36: explicitly refuses if caller is banned (defense in depth — trigger also blocks).';


--
-- Name: legacy_transition_eligible(public.social_posts); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.legacy_transition_eligible(p_post public.social_posts) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
  SELECT (p_post).content_type = 'video'
    AND COALESCE((p_post).is_deleted, false) = false
    AND (p_post).visibility IS DISTINCT FROM 'private'
    AND (p_post).playback_type = 'youtube_embed'
    AND (p_post).rights_status IN ('embed_only', 'owned', 'licensed')
    AND (p_post).youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'
    AND (p_post).youtube_video_id NOT LIKE 'FAKE%'
    AND (p_post).canonical_asset_key =
      'youtube:' || (p_post).youtube_video_id
    AND public.fn_extract_youtube_video_id(
          NULLIF((p_post).media_urls ->> 0, '')
        ) = (p_post).youtube_video_id
    AND EXISTS (
      SELECT 1
      FROM public.video_reels_legacy_transition_rows transition_row
      JOIN public.video_reels_legacy_transition_state transition_state
        ON transition_state.transition_key = 'phase1-public-youtube'
       AND transition_state.captured_at = transition_row.captured_at
       AND transition_state.expires_at = transition_row.expires_at
      WHERE transition_row.surface = 'social_posts'
        AND transition_row.row_id = (p_post).id
        AND transition_row.youtube_video_id = (p_post).youtube_video_id
        AND transition_row.row_snapshot =
          public.fn_legacy_youtube_post_transition_snapshot(p_post)
        AND transition_row.expires_at =
          (p_post).legacy_transition_expires_at
        AND transition_row.captured_at <= now() + interval '5 minutes'
        AND transition_row.expires_at =
          transition_row.captured_at + interval '7 days'
        AND transition_row.expires_at > now()
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.youtube_embed_failures failure
      WHERE failure.video_id = (p_post).youtube_video_id
        AND failure.verification_status = 'confirmed'
        AND failure.resolved = false
    )
$_$;


ALTER FUNCTION public.legacy_transition_eligible(p_post public.social_posts) OWNER TO postgres;

--
-- Name: FUNCTION legacy_transition_eligible(p_post public.social_posts); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.legacy_transition_eligible(p_post public.social_posts) IS 'Computed field for the exact immutable pre-Phase-1 YouTube post snapshot; expires seven days after the one-time capture and never overrides a confirmed failure.';


--
-- Name: legacy_transition_eligible(public.social_reels); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.legacy_transition_eligible(p_reel public.social_reels) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
  SELECT COALESCE((p_reel).is_deleted, false) = false
    AND (p_reel).is_public = true
    AND (p_reel).playback_type = 'youtube_embed'
    AND (p_reel).rights_status IN ('embed_only', 'owned', 'licensed')
    AND (p_reel).youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'
    AND (p_reel).youtube_video_id NOT LIKE 'FAKE%'
    AND (p_reel).canonical_asset_key =
      'youtube:' || (p_reel).youtube_video_id
    AND public.fn_extract_youtube_video_id((p_reel).video_url) =
      (p_reel).youtube_video_id
    AND EXISTS (
      SELECT 1
      FROM public.video_reels_legacy_transition_rows transition_row
      JOIN public.video_reels_legacy_transition_state transition_state
        ON transition_state.transition_key = 'phase1-public-youtube'
       AND transition_state.captured_at = transition_row.captured_at
       AND transition_state.expires_at = transition_row.expires_at
      WHERE transition_row.surface = 'social_reels'
        AND transition_row.row_id = (p_reel).id
        AND transition_row.youtube_video_id = (p_reel).youtube_video_id
        AND transition_row.row_snapshot =
          public.fn_legacy_youtube_reel_transition_snapshot(p_reel)
        AND transition_row.expires_at =
          (p_reel).legacy_transition_expires_at
        AND transition_row.captured_at <= now() + interval '5 minutes'
        AND transition_row.expires_at =
          transition_row.captured_at + interval '7 days'
        AND transition_row.expires_at > now()
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.youtube_embed_failures failure
      WHERE failure.video_id = (p_reel).youtube_video_id
        AND failure.verification_status = 'confirmed'
        AND failure.resolved = false
    )
$_$;


ALTER FUNCTION public.legacy_transition_eligible(p_reel public.social_reels) OWNER TO postgres;

--
-- Name: FUNCTION legacy_transition_eligible(p_reel public.social_reels); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.legacy_transition_eligible(p_reel public.social_reels) IS 'Computed field for the exact immutable pre-Phase-1 YouTube Reel snapshot; expires seven days after the one-time capture and never overrides a confirmed failure.';


