--
-- Name: list_home_ban_appeals_admin(uuid, text, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_home_ban_appeals_admin(p_caller_user_id uuid, p_status text DEFAULT NULL::text, p_group_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(out_appeal_id uuid, out_group_id uuid, out_group_name text, out_user_id uuid, out_user_display text, out_user_avatar text, out_ban_reason text, out_appeal_text text, out_status text, out_reviewed_by uuid, out_reviewer_note text, out_created_at timestamp with time zone, out_reviewed_at timestamp with time zone, out_days_pending integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller_role text;
BEGIN
  IF p_caller_user_id IS NULL THEN
    RAISE EXCEPTION 'CALLER_REQUIRED' USING ERRCODE = '42501';
  END IF;

  -- IDENTITY. Added 2026-08-26 with SECURITY DEFINER. Without this, the role
  -- check below is a check on a caller-supplied parameter, and a definer-rights
  -- function would let any signed-in user read every ban appeal by passing an
  -- admin's uuid. Same guard the other six moderation RPCs carry.
  IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
  END IF;

  -- Require admin/superadmin/god
  SELECT role INTO v_caller_role FROM public.profiles WHERE id = p_caller_user_id;
  IF v_caller_role IS NULL OR v_caller_role NOT IN ('admin','superadmin','god') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  p_limit  := GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
  p_offset := GREATEST(0, COALESCE(p_offset, 0));

  RETURN QUERY
  SELECT a.id,
         a.group_id,
         g.name::text,
         a.user_id,
         COALESCE(p.display_name, p.full_name, p.username, 'Member')::text,
         p.avatar_url::text,
         m.ban_reason::text,
         a.appeal_text,
         a.status,
         a.reviewed_by,
         a.reviewer_note,
         a.created_at,
         a.reviewed_at,
         EXTRACT(DAY FROM (NOW() - a.created_at))::integer
    FROM public.commander_home_ban_appeals a
    JOIN public.commander_home_groups g ON g.id = a.group_id
    LEFT JOIN public.profiles p              ON p.id = a.user_id
    LEFT JOIN public.commander_home_members m ON m.group_id = a.group_id AND m.user_id = a.user_id
   WHERE (p_group_id IS NULL OR a.group_id = p_group_id)
     AND (p_status IS NULL OR p_status = '' OR a.status = p_status)
   ORDER BY CASE WHEN a.status='pending' THEN 0 ELSE 1 END, a.created_at ASC
   LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.list_home_ban_appeals_admin(p_caller_user_id uuid, p_status text, p_group_id uuid, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: list_home_ban_appeals_for_host(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_home_ban_appeals_for_host(p_group_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'pending'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(out_appeal_id uuid, out_group_id uuid, out_group_name text, out_user_id uuid, out_user_display text, out_user_avatar text, out_ban_reason text, out_appeal_text text, out_status text, out_reviewed_by uuid, out_reviewer_note text, out_created_at timestamp with time zone, out_reviewed_at timestamp with time zone, out_days_pending integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_staff_group_ids uuid[];
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE='42501'; END IF;

  SELECT array_agg(gid) INTO v_staff_group_ids FROM (
    SELECT id AS gid FROM public.commander_home_groups WHERE owner_id = v_uid
    UNION
    SELECT group_id FROM public.commander_home_members
     WHERE user_id = v_uid AND role IN ('admin','co_host') AND status='approved'
  ) s;

  IF v_staff_group_ids IS NULL OR array_length(v_staff_group_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  IF p_group_id IS NOT NULL AND NOT (p_group_id = ANY(v_staff_group_ids)) THEN
    RAISE EXCEPTION 'NOT_GROUP_STAFF' USING ERRCODE='42501';
  END IF;

  p_limit  := GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
  p_offset := GREATEST(0, COALESCE(p_offset, 0));

  RETURN QUERY
  SELECT a.id,
         a.group_id,
         g.name::text,
         a.user_id,
         COALESCE(p.display_name, p.full_name, p.username, 'Member')::text,
         p.avatar_url::text,
         m.ban_reason::text,
         a.appeal_text,
         a.status,
         a.reviewed_by, a.reviewer_note,
         a.created_at, a.reviewed_at,
         EXTRACT(DAY FROM (NOW() - a.created_at))::integer
    FROM public.commander_home_ban_appeals a
    JOIN public.commander_home_groups g ON g.id = a.group_id
    LEFT JOIN public.profiles p              ON p.id = a.user_id
    LEFT JOIN public.commander_home_members m ON m.group_id = a.group_id AND m.user_id = a.user_id
   WHERE a.group_id = ANY(v_staff_group_ids)
     AND (p_group_id IS NULL OR a.group_id = p_group_id)
     AND (p_status IS NULL OR a.status = p_status)
   ORDER BY CASE WHEN a.status='pending' THEN 0 ELSE 1 END, a.created_at ASC
   LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.list_home_ban_appeals_for_host(p_group_id uuid, p_status text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: list_home_content_reports(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_home_content_reports(p_caller_user_id uuid, p_status text DEFAULT NULL::text, p_reported_type text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_rows jsonb;
  v_total int;
  v_safe_limit int;
  v_safe_offset int;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED';
  END IF;
  SELECT role INTO v_role FROM public.profiles WHERE id = p_caller_user_id;
  IF v_role NOT IN ('admin','superadmin','god') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING HINT = 'moderation queue is admin-only';
  END IF;

  v_safe_limit  := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
  v_safe_offset := GREATEST(COALESCE(p_offset, 0), 0);

  SELECT COUNT(*) INTO v_total
    FROM public.commander_home_content_reports r
   WHERE (p_status IS NULL OR r.status = p_status)
     AND (p_reported_type IS NULL OR r.reported_type = p_reported_type);

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'id',                  r.id,
             'reporter_id',         r.reporter_id,
             'reporter_name',       COALESCE(p_reporter.display_name, p_reporter.username, 'Unknown'),
             'reported_type',       r.reported_type,
             'reported_id',         r.reported_id,
             'content_author_id',   r.content_author_id,
             'content_author_name', COALESCE(p_author.display_name, p_author.username, 'Unknown'),
             'reason_category',     r.reason_category,
             'reason_text',         r.reason_text,
             'status',              r.status,
             'content_hidden_at',   r.content_hidden_at,
             'reviewed_by',         r.reviewed_by,
             'reviewed_at',         r.reviewed_at,
             'moderator_note',      r.moderator_note,
             'action_taken',        r.action_taken,
             'created_at',          r.created_at
           )
           ORDER BY r.created_at DESC
         ), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT *
        FROM public.commander_home_content_reports
       WHERE (p_status IS NULL OR status = p_status)
         AND (p_reported_type IS NULL OR reported_type = p_reported_type)
       ORDER BY created_at DESC
       LIMIT v_safe_limit OFFSET v_safe_offset
    ) r
    LEFT JOIN public.profiles p_reporter ON p_reporter.id = r.reporter_id
    LEFT JOIN public.profiles p_author   ON p_author.id   = r.content_author_id;

  RETURN jsonb_build_object(
    'success', true,
    'total',   v_total,
    'limit',   v_safe_limit,
    'offset',  v_safe_offset,
    'reports', v_rows
  );
END;
$$;


ALTER FUNCTION public.list_home_content_reports(p_caller_user_id uuid, p_status text, p_reported_type text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: list_home_group_reports_for_host(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_home_group_reports_for_host(p_group_id uuid, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_staff boolean;
  v_rows jsonb;
  v_total int;
  v_safe_limit int;
  v_safe_offset int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE='42501'; END IF;

  v_is_staff := EXISTS (SELECT 1 FROM public.commander_home_groups
       WHERE id = p_group_id AND owner_id = v_uid)
    OR EXISTS (SELECT 1 FROM public.commander_home_members
       WHERE group_id = p_group_id AND user_id = v_uid
         AND role IN ('admin','co_host') AND status='approved');
  IF NOT v_is_staff THEN RAISE EXCEPTION 'NOT_GROUP_STAFF' USING ERRCODE='42501'; END IF;

  v_safe_limit  := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
  v_safe_offset := GREATEST(COALESCE(p_offset, 0), 0);

  SELECT COUNT(*) INTO v_total
    FROM public.commander_home_content_reports r
   WHERE r.reason_category NOT IN ('illegal','self_harm','doxxing')
     AND r.content_author_id <> (SELECT owner_id FROM public.commander_home_groups WHERE id = p_group_id)
     AND (p_status IS NULL OR r.status = p_status)
     AND (
       (r.reported_type IN ('post','comment')
         AND r.reported_id IN (SELECT p.id FROM public.commander_home_posts p WHERE p.group_id = p_group_id))
       OR (r.reported_type = 'game'
         AND r.reported_id IN (SELECT g.id FROM public.commander_home_games g WHERE g.group_id = p_group_id))
       OR (r.reported_type = 'review'
         AND r.reported_id IN (SELECT rv.id FROM public.commander_home_game_reviews rv
           JOIN public.commander_home_games g ON g.id = rv.game_id WHERE g.group_id = p_group_id))
       OR (r.reported_type = 'member'
         AND r.reported_id IN (SELECT m.id FROM public.commander_home_members m WHERE m.group_id = p_group_id))
     );

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'id',                  r.id,
             'reporter_id',         r.reporter_id,
             'reporter_name',       COALESCE(p_rep.display_name, p_rep.username, 'Unknown'),
             'reported_type',       r.reported_type,
             'reported_id',         r.reported_id,
             'content_author_id',   r.content_author_id,
             'content_author_name', COALESCE(p_auth.display_name, p_auth.username, 'Unknown'),
             'author_display',      COALESCE(p_auth.display_name, p_auth.username, 'Unknown'),
             'author_name',         COALESCE(p_auth.display_name, p_auth.username, 'Unknown'),
             'reason_category',     r.reason_category,
             'reason_text',         r.reason_text,
             'content',             COALESCE(content_snippet.snippet, '(content unavailable)'),
             'text',                COALESCE(content_snippet.snippet, '(content unavailable)'),
             'status',              r.status,
             'created_at',          r.created_at,
             'reviewed_at',         r.reviewed_at,
             'action_taken',        r.action_taken
           ) ORDER BY r.created_at DESC
         ), '[]'::jsonb) INTO v_rows
    FROM (
      SELECT * FROM public.commander_home_content_reports r
       WHERE r.reason_category NOT IN ('illegal','self_harm','doxxing')
         AND r.content_author_id <> (SELECT owner_id FROM public.commander_home_groups WHERE id = p_group_id)
         AND (p_status IS NULL OR r.status = p_status)
         AND (
           (r.reported_type IN ('post','comment')
             AND r.reported_id IN (SELECT p.id FROM public.commander_home_posts p WHERE p.group_id = p_group_id))
           OR (r.reported_type = 'game'
             AND r.reported_id IN (SELECT g.id FROM public.commander_home_games g WHERE g.group_id = p_group_id))
           OR (r.reported_type = 'review'
             AND r.reported_id IN (SELECT rv.id FROM public.commander_home_game_reviews rv
               JOIN public.commander_home_games g ON g.id = rv.game_id WHERE g.group_id = p_group_id))
           OR (r.reported_type = 'member'
             AND r.reported_id IN (SELECT m.id FROM public.commander_home_members m WHERE m.group_id = p_group_id))
         )
       ORDER BY r.created_at DESC
       LIMIT v_safe_limit OFFSET v_safe_offset
    ) r
    LEFT JOIN public.profiles p_rep  ON p_rep.id  = r.reporter_id
    LEFT JOIN public.profiles p_auth ON p_auth.id = r.content_author_id
    LEFT JOIN LATERAL (
      SELECT CASE r.reported_type
        WHEN 'post'    THEN (SELECT LEFT(content, 500) FROM public.commander_home_posts WHERE id = r.reported_id)
        WHEN 'comment' THEN (SELECT LEFT(content, 500) FROM public.commander_home_post_comments WHERE id = r.reported_id)
        WHEN 'review'  THEN (SELECT LEFT(COALESCE(review_text, ''), 500) FROM public.commander_home_game_reviews WHERE id = r.reported_id)
        WHEN 'game'    THEN (SELECT LEFT(COALESCE(title, '') || COALESCE(' - ' || description, ''), 500) FROM public.commander_home_games WHERE id = r.reported_id)
        WHEN 'member'  THEN '(member report - see profile)'
        ELSE NULL
      END AS snippet
    ) content_snippet ON TRUE;

  RETURN jsonb_build_object('success', true, 'total', v_total,
    'limit', v_safe_limit, 'offset', v_safe_offset, 'reports', v_rows);
END;
$$;


ALTER FUNCTION public.list_home_group_reports_for_host(p_group_id uuid, p_status text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: lock_chips_for_table(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_chips_for_table(p_club_id uuid, p_user_id uuid, p_table_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_balance_before numeric;
  v_balance_after numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  SELECT COALESCE(chip_balance, 0) INTO v_balance_before
  FROM club_members
  WHERE club_id = p_club_id AND user_id = p_user_id
  FOR UPDATE;

  IF v_balance_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not a member of this club');
  END IF;

  IF v_balance_before < p_amount THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'insufficient chips',
      'balance', v_balance_before,
      'requested', p_amount
    );
  END IF;

  UPDATE club_members
  SET chip_balance = chip_balance - p_amount::integer,
      updated_at = NOW()
  WHERE club_id = p_club_id AND user_id = p_user_id;
  v_balance_after := v_balance_before - p_amount;

  RETURN jsonb_build_object(
    'success', true,
    'locked', p_amount,
    'balance', v_balance_before,
    'balance_after', v_balance_after
  );
END;
$$;


ALTER FUNCTION public.lock_chips_for_table(p_club_id uuid, p_user_id uuid, p_table_id uuid, p_amount numeric) OWNER TO postgres;

