--
-- Name: lock_club_cashier_hierarchy_mutation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_club_cashier_hierarchy_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_old_club uuid := case when tg_op in ('UPDATE','DELETE') then old.club_id else null end;
  v_new_club uuid := case when tg_op in ('INSERT','UPDATE') then new.club_id else null end;
begin
  if v_old_club is not null and (v_new_club is null or v_old_club::text <= v_new_club::text) then
    perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||v_old_club::text,0));
  end if;
  if v_new_club is not null and v_new_club is distinct from v_old_club then
    perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||v_new_club::text,0));
  end if;
  if v_old_club is not null and v_new_club is not null and v_old_club::text > v_new_club::text then
    perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||v_old_club::text,0));
  end if;
  return case when tg_op='DELETE' then old else new end;
end
$$;


ALTER FUNCTION public.lock_club_cashier_hierarchy_mutation() OWNER TO postgres;

--
-- Name: log_audit_event(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_audit_event(p_user_id uuid DEFAULT NULL::uuid, p_action text DEFAULT ''::text, p_details jsonb DEFAULT '{}'::jsonb, p_ip_address text DEFAULT ''::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  INSERT INTO system_logs (log_level, source, message, details, created_at)
  VALUES ('audit', 'audit', p_action, jsonb_build_object('user_id', p_user_id, 'details', p_details, 'ip', p_ip_address), now())
  ON CONFLICT DO NOTHING;
EXCEPTION WHEN undefined_table THEN NULL;
END; $$;


ALTER FUNCTION public.log_audit_event(p_user_id uuid, p_action text, p_details jsonb, p_ip_address text) OWNER TO postgres;

--
-- Name: log_audit_event(integer, uuid, uuid, text, text, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_audit_event(p_venue_id integer, p_user_id uuid, p_staff_id uuid, p_actor_type text, p_action text, p_action_category text, p_target_type text, p_target_id text, p_changes jsonb, p_metadata jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_id uuid;
  v_ip inet;
BEGIN
  -- ip arrives inside metadata (helper packs it there); tolerate garbage
  BEGIN
    v_ip := NULLIF(p_metadata->>'ip_address', '')::inet;
  EXCEPTION WHEN OTHERS THEN
    v_ip := NULL;
  END;

  INSERT INTO public.commander_audit_logs (
    venue_id, user_id, staff_id, actor_type, action, action_category,
    target_type, target_id, changes, metadata,
    ip_address, user_agent, request_id, status, created_at
  ) VALUES (
    p_venue_id, p_user_id, p_staff_id, COALESCE(p_actor_type, 'user'),
    p_action, COALESCE(p_action_category, 'general'),
    p_target_type, p_target_id, p_changes,
    (COALESCE(p_metadata, '{}'::jsonb)) - 'ip_address' - 'user_agent' - 'request_id',
    v_ip,
    p_metadata->>'user_agent',
    p_metadata->>'request_id',
    'success',
    now()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.log_audit_event(p_venue_id integer, p_user_id uuid, p_staff_id uuid, p_actor_type text, p_action text, p_action_category text, p_target_type text, p_target_id text, p_changes jsonb, p_metadata jsonb) OWNER TO postgres;

--
-- Name: log_wallet_transaction(uuid, text, numeric, text, text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_wallet_transaction(p_user_id uuid, p_wallet_type text, p_amount numeric, p_type text, p_category text, p_description text, p_table_id uuid DEFAULT NULL::uuid, p_hand_id uuid DEFAULT NULL::uuid, p_related_entity_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_bal NUMERIC; v_club uuid;
BEGIN
  /* ZERO-DRIFT (2026-08-31): club members' live balance is
     club_members.chip_balance; public.wallets has been frozen since
     2026-08-21, so reading it stamped a stale balance_after on every row. */
  IF p_wallet_type = 'PLAYER' THEN
    v_club := public.fn_player_home_club(p_user_id, NULL);
    IF v_club IS NOT NULL THEN
      SELECT chip_balance INTO v_bal FROM club_members
       WHERE user_id = p_user_id AND club_id = v_club;
    END IF;
  END IF;
  IF v_bal IS NULL THEN
    SELECT balance INTO v_bal FROM wallets WHERE user_id = p_user_id AND wallet_type = p_wallet_type;
  END IF;
  INSERT INTO wallet_transactions (user_id, wallet_type, amount, type, category, description, table_id, hand_id, related_entity_id, balance_after, created_at)
  VALUES (p_user_id, p_wallet_type, p_amount, p_type, p_category, p_description, p_table_id, p_hand_id, p_related_entity_id, COALESCE(v_bal, 0), NOW());
END;
$$;


ALTER FUNCTION public.log_wallet_transaction(p_user_id uuid, p_wallet_type text, p_amount numeric, p_type text, p_category text, p_description text, p_table_id uuid, p_hand_id uuid, p_related_entity_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION log_wallet_transaction(p_user_id uuid, p_wallet_type text, p_amount numeric, p_type text, p_category text, p_description text, p_table_id uuid, p_hand_id uuid, p_related_entity_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.log_wallet_transaction(p_user_id uuid, p_wallet_type text, p_amount numeric, p_type text, p_category text, p_description text, p_table_id uuid, p_hand_id uuid, p_related_entity_id uuid) IS 'BUG 018 FIX 2026-04-15 — now reads wallets.balance and writes balance_after so audit rows are reconcilable. Caller should mutate wallets BEFORE calling this.';


--
-- Name: manage_home_group_member(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_home_group_member(p_group_id uuid, p_member_user_id uuid, p_action text, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_group public.commander_home_groups%ROWTYPE;
  v_target public.commander_home_members%ROWTYPE;
  v_caller_role text;
  v_valid_actions text[] := ARRAY[
    'invite',
    'approve',
    'decline',
    'ban',
    'unban',
    'promote_admin',
    'demote_member',
    'grant_host',
    'revoke_host',
    'remove'
  ];
  v_active_games integer;
  v_before jsonb;
  v_after jsonb;
  v_audit_action text;
BEGIN
  IF auth.uid() IS NULL
     OR p_caller_user_id IS NULL
     OR auth.uid() <> p_caller_user_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED';
  END IF;

  IF p_group_id IS NULL OR p_member_user_id IS NULL THEN
    RAISE EXCEPTION 'MISSING_PARAMS';
  END IF;

  IF p_action IS NULL OR NOT (p_action = ANY(v_valid_actions)) THEN
    RAISE EXCEPTION 'INVALID_ACTION'
      USING HINT = 'action must be invite, approve, decline, ban, unban, promote_admin, demote_member, grant_host, revoke_host, or remove';
  END IF;

  -- Take the shared join/invite identity lock before the group-row lock. Both
  -- RPCs use this order, preventing a join-vs-invite lock inversion.
  IF p_action = 'invite' THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtext(p_group_id::text),
      pg_catalog.hashtext(p_member_user_id::text)
    );
  END IF;

  SELECT * INTO v_group
    FROM public.commander_home_groups
   WHERE id = p_group_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'GROUP_NOT_FOUND';
  END IF;

  IF v_group.owner_id = p_caller_user_id THEN
    v_caller_role := 'owner';
  ELSE
    SELECT role INTO v_caller_role
      FROM public.commander_home_members
     WHERE group_id = p_group_id
       AND user_id = p_caller_user_id
       AND status = 'approved'
       AND role = 'admin'
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'NOT_A_HOST';
    END IF;
  END IF;

  -- Admin invitations are membership mutations too. Keep creation and its
  -- audit record in this caller-authenticated transaction instead of allowing
  -- API routes to insert approved memberships through the service role.
  IF p_action = 'invite' THEN
    IF p_member_user_id = p_caller_user_id THEN
      RAISE EXCEPTION 'CANNOT_SELF_MANAGE'
        USING HINT = 'use join_home_group for self-join';
    END IF;

    IF EXISTS (
      SELECT 1
        FROM public.commander_home_members
       WHERE group_id = p_group_id
         AND user_id = p_member_user_id
    ) THEN
      RAISE EXCEPTION 'ALREADY_MEMBER' USING ERRCODE = '23505';
    END IF;

    INSERT INTO public.commander_home_members (
      group_id,
      user_id,
      role,
      status,
      invited_by,
      joined_at
    ) VALUES (
      p_group_id,
      p_member_user_id,
      'member',
      'approved',
      p_caller_user_id,
      now()
    )
    ON CONFLICT (group_id, user_id) WHERE user_id IS NOT NULL DO NOTHING
    RETURNING * INTO v_target;

    IF v_target.id IS NULL THEN
      RAISE EXCEPTION 'ALREADY_MEMBER' USING ERRCODE = '23505';
    END IF;

    v_after := jsonb_build_object(
      'status', v_target.status,
      'role', v_target.role,
      'can_host', coalesce(v_target.can_host, false),
      'joined_at', v_target.joined_at
    );

    INSERT INTO public.commander_home_audit_log
      (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (
      p_group_id,
      p_caller_user_id,
      'member',
      v_target.id,
      'member_invited',
      jsonb_build_object(
        'requested_action', p_action,
        'member_id', v_target.id,
        'member_user_id', v_target.user_id,
        'is_roster_only', false,
        'before', NULL,
        'after', v_after
      )
    );

    RETURN jsonb_build_object(
      'success', true,
      'action', p_action,
      'member_id', v_target.id,
      'member_user_id', v_target.user_id,
      'new_state', v_after
    );
  END IF;

  -- The registered identity wins in the vanishingly unlikely event that a
  -- user's UUID equals a roster-only membership UUID in the same group.
  SELECT m.* INTO v_target
    FROM public.commander_home_members m
   WHERE m.group_id = p_group_id
     AND (
       m.user_id = p_member_user_id
       OR (m.user_id IS NULL AND m.id = p_member_user_id)
     )
   ORDER BY CASE WHEN m.user_id = p_member_user_id THEN 0 ELSE 1 END
   LIMIT 1
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'MEMBER_NOT_FOUND';
  END IF;

  IF v_target.user_id = p_caller_user_id THEN
    RAISE EXCEPTION 'CANNOT_SELF_MANAGE'
      USING HINT = 'use leave_home_group for self-exit';
  END IF;

  -- No member-management action can mutate the canonical owner row.
  IF v_target.user_id = v_group.owner_id OR v_target.role = 'owner' THEN
    RAISE EXCEPTION 'CANNOT_MODIFY_OWNER'
      USING HINT = 'use transfer_home_group_ownership to change the owner';
  END IF;

  IF v_caller_role = 'admin' THEN
    IF v_target.role = 'admin' THEN
      RAISE EXCEPTION 'ADMIN_CANNOT_MODIFY_PEER';
    END IF;
    IF p_action IN ('promote_admin', 'demote_member') THEN
      RAISE EXCEPTION 'OWNER_ONLY_ACTION'
        USING HINT = 'promote_admin and demote_member require owner';
    END IF;
  END IF;

  IF p_action IN ('grant_host', 'revoke_host')
     AND (v_target.status <> 'approved' OR v_target.role <> 'member') THEN
    RAISE EXCEPTION 'TARGET_NOT_APPROVED'
      USING HINT = 'hosting permission applies only to ordinary approved members';
  END IF;

  IF p_action = 'remove' AND v_target.user_id IS NOT NULL THEN
    SELECT count(*) INTO v_active_games
      FROM public.commander_home_games
     WHERE group_id = p_group_id
       AND host_id = v_target.user_id
       AND status IN ('scheduled', 'confirmed', 'in_progress');
    IF v_active_games > 0 THEN
      RAISE EXCEPTION 'MEMBER_IS_ACTIVE_GAME_HOST'
        USING HINT = 'member hosts ' || v_active_games
          || ' active game(s); cancel or reassign them before removing';
    END IF;
  END IF;

  v_before := jsonb_build_object(
    'status', v_target.status,
    'role', v_target.role,
    'can_host', coalesce(v_target.can_host, false),
    'joined_at', v_target.joined_at
  );

  CASE p_action
    WHEN 'approve' THEN
      IF v_target.status <> 'pending' THEN
        RAISE EXCEPTION 'TARGET_NOT_PENDING'
          USING HINT = 'current status is ' || v_target.status;
      END IF;
      UPDATE public.commander_home_members
         SET status = 'approved',
             joined_at = coalesce(joined_at, now())
       WHERE id = v_target.id;
      v_audit_action := 'member_approved';

    WHEN 'decline' THEN
      IF v_target.status <> 'pending' THEN
        RAISE EXCEPTION 'TARGET_NOT_PENDING'
          USING HINT = 'current status is ' || v_target.status;
      END IF;
      UPDATE public.commander_home_members
         SET status = 'declined', can_host = false
       WHERE id = v_target.id;
      v_audit_action := 'member_declined';

    WHEN 'ban' THEN
      UPDATE public.commander_home_members
         SET status = 'banned', role = 'member', can_host = false
       WHERE id = v_target.id;
      v_audit_action := 'member_banned';

    WHEN 'unban' THEN
      IF v_target.status <> 'banned' THEN
        RAISE EXCEPTION 'TARGET_NOT_BANNED';
      END IF;
      UPDATE public.commander_home_members
         SET status = 'approved', can_host = false
       WHERE id = v_target.id;
      v_audit_action := 'member_unbanned';

    WHEN 'promote_admin' THEN
      IF v_target.status <> 'approved' THEN
        RAISE EXCEPTION 'TARGET_NOT_APPROVED';
      END IF;
      IF v_target.role = 'admin' THEN
        RAISE EXCEPTION 'ALREADY_ADMIN';
      END IF;
      UPDATE public.commander_home_members
         SET role = 'admin'
       WHERE id = v_target.id;
      v_audit_action := 'member_promoted_admin';

    WHEN 'demote_member' THEN
      IF v_target.role <> 'admin' THEN
        RAISE EXCEPTION 'TARGET_NOT_ADMIN';
      END IF;
      UPDATE public.commander_home_members
         SET role = 'member'
       WHERE id = v_target.id;
      v_audit_action := 'member_demoted';

    WHEN 'grant_host' THEN
      UPDATE public.commander_home_members
         SET can_host = true
       WHERE id = v_target.id;
      v_audit_action := 'member_host_granted';

    WHEN 'revoke_host' THEN
      UPDATE public.commander_home_members
         SET can_host = false
       WHERE id = v_target.id;
      v_audit_action := 'member_host_revoked';

    WHEN 'remove' THEN
      PERFORM set_config('app.hg_member_remove_allowed', '1', true);
      DELETE FROM public.commander_home_members WHERE id = v_target.id;
      PERFORM set_config('app.hg_member_remove_allowed', '', true);
      v_audit_action := 'member_removed';
  END CASE;

  IF p_action = 'remove' THEN
    v_after := jsonb_build_object('removed', true);
  ELSE
    SELECT jsonb_build_object(
      'status', status,
      'role', role,
      'can_host', coalesce(can_host, false),
      'joined_at', joined_at
    )
      INTO v_after
      FROM public.commander_home_members
     WHERE id = v_target.id;
  END IF;

  -- This insert is intentionally in the same transaction as the mutation.
  -- Audit failure therefore fails closed and rolls the member change back.
  INSERT INTO public.commander_home_audit_log
    (group_id, actor_id, target_type, target_id, action, metadata)
  VALUES (
    p_group_id,
    p_caller_user_id,
    'member',
    v_target.id,
    v_audit_action,
    jsonb_build_object(
      'requested_action', p_action,
      'member_id', v_target.id,
      'member_user_id', v_target.user_id,
      'is_roster_only', coalesce(v_target.is_roster_only, false),
      'before', v_before,
      'after', v_after
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'action', p_action,
    'member_id', v_target.id,
    'member_user_id', v_target.user_id,
    'new_state', v_after
  );
END;
$$;


