-- Name: mark_clip_used(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_clip_used(p_clip_id uuid, p_horse_id integer, p_post_id uuid, p_caption text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    -- Update clip stats
    UPDATE clip_library
    SET used_count = used_count + 1,
        last_used_at = NOW(),
        last_used_by = auth.uid()
    WHERE id = p_clip_id;
    
    -- Log usage
    INSERT INTO clip_usage_log (clip_id, horse_id, post_id, caption_used)
    VALUES (p_clip_id, p_horse_id, p_post_id, p_caption);
END;
$$;


