--
-- Name: mark_home_game_seat_away(uuid, integer, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_home_game_seat_away(p_game_id uuid, p_seat_number integer, p_is_away boolean, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_game RECORD; v_group RECORD;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
      RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;
    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;

    IF v_game.host_id <> p_caller_user_id AND v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members
                        WHERE group_id = v_game.group_id AND user_id = p_caller_user_id
                          AND role = 'admin' AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;

    UPDATE commander_home_seats
       SET status = CASE WHEN p_is_away THEN 'away' ELSE 'seated' END,
           away_since = CASE WHEN p_is_away THEN NOW() ELSE NULL END,
           updated_at = NOW()
     WHERE game_id = p_game_id AND seat_number = p_seat_number;

    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION public.mark_home_game_seat_away(p_game_id uuid, p_seat_number integer, p_is_away boolean, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: marketplace_phase7_vip_acquisition_mutex_version(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.marketplace_phase7_vip_acquisition_mutex_version() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN pg_catalog.obj_description(
      pg_catalog.to_regprocedure(
        'public.claim_vip_subscription_checkout(uuid,text,text,integer)'
      ),
      'pg_proc'
    ) = 'marketplace_phase7_vip_acquisition_mutex:v1'
    AND pg_catalog.obj_description(
      pg_catalog.to_regprocedure(
        'public.purchase_vip_with_diamonds_atomic_v3(uuid,integer,integer,text,text,text,text)'
      ),
      'pg_proc'
    ) = 'marketplace_phase7_vip_acquisition_mutex:v1'
    AND pg_catalog.obj_description(
      pg_catalog.to_regprocedure(
        'public.admit_vip_subscription_checkout(uuid,text,text,text,text)'
      ),
      'pg_proc'
    ) = 'marketplace_phase7_vip_acquisition_mutex:v1'
    AND pg_catalog.obj_description(
      pg_catalog.to_regprocedure(
        'public.apply_vip_subscription_projection(uuid,text,text,text,text,text,text,numeric,timestamp with time zone,timestamp with time zone,boolean,timestamp with time zone)'
      ),
      'pg_proc'
    ) = 'marketplace_phase7_vip_acquisition_mutex:v1'
    AND pg_catalog.obj_description(
      pg_catalog.to_regprocedure(
        'public.complete_vip_subscription_checkout(uuid,text,text,text,timestamp with time zone)'
      ),
      'pg_proc'
    ) = 'marketplace_phase7_vip_acquisition_mutex:v1'
    AND pg_catalog.obj_description(
      pg_catalog.to_regprocedure(
        'public.release_vip_subscription_checkout(uuid,text)'
      ),
      'pg_proc'
    ) = 'marketplace_phase7_vip_acquisition_mutex:v1'
    AND pg_catalog.obj_description(
      pg_catalog.to_regprocedure(
        'public.finalize_vip_subscription_admission(uuid,text,text,text)'
      ),
      'pg_proc'
    ) = 'marketplace_phase7_vip_acquisition_mutex:v1'
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.claim_vip_subscription_checkout(uuid,text,text,integer)'
      )),
      'vip_entitlement_active'
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.claim_vip_subscription_checkout(uuid,text,text,integer)'
      )),
      'state <> ''admitting'''
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.purchase_vip_with_diamonds_atomic_v3(uuid,integer,integer,text,text,text,text)'
      )),
      'card_checkout_exists'
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.purchase_vip_with_diamonds_atomic_v3(uuid,integer,integer,text,text,text,text)'
      )),
      'active_card_subscription'
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.admit_vip_subscription_checkout(uuid,text,text,text,text)'
      )),
      'claim_conflict'
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.admit_vip_subscription_checkout(uuid,text,text,text,text)'
      )),
      'SET state = ''admitting'''
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.admit_vip_subscription_checkout(uuid,text,text,text,text)'
      )),
      'SET stripe_subscription_id = p_stripe_subscription_id'
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.apply_vip_subscription_projection(uuid,text,text,text,text,text,text,numeric,timestamp with time zone,timestamp with time zone,boolean,timestamp with time zone)'
      )),
      'reactivation_entitlement_conflict'
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.apply_vip_subscription_projection(uuid,text,text,text,text,text,text,numeric,timestamp with time zone,timestamp with time zone,boolean,timestamp with time zone)'
      )),
      'v_profile.vip_expires_at > v_subscription.current_period_end'
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.apply_vip_subscription_projection(uuid,text,text,text,text,text,text,numeric,timestamp with time zone,timestamp with time zone,boolean,timestamp with time zone)'
      )),
      'state'', ''claim_conflict'''
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.apply_vip_subscription_projection(uuid,text,text,text,text,text,text,numeric,timestamp with time zone,timestamp with time zone,boolean,timestamp with time zone)'
      )),
      'INSERT INTO public.vip_subscriptions'
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.apply_vip_subscription_projection(uuid,text,text,text,text,text,text,numeric,timestamp with time zone,timestamp with time zone,boolean,timestamp with time zone)'
      )),
      'UPDATE public.profiles'
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.complete_vip_subscription_checkout(uuid,text,text,text,timestamp with time zone)'
      )),
      'state <> ''admitting'''
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.release_vip_subscription_checkout(uuid,text)'
      )),
      'state <> ''admitting'''
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.finalize_vip_subscription_admission(uuid,text,text,text)'
      )),
      'state = ''admitting'''
    ) > 0
    AND pg_catalog.strpos(
      pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure(
        'public.finalize_vip_subscription_admission(uuid,text,text,text)'
      )),
      'subscription_missing'
    ) > 0
    AND EXISTS (
      SELECT 1
        FROM pg_catalog.pg_constraint constraint_record
       WHERE constraint_record.conrelid = pg_catalog.to_regclass(
               'public.vip_subscription_checkout_claims'
             )
         AND constraint_record.conname = 'vip_subscription_checkout_claims_state_check'
         AND pg_catalog.obj_description(
               constraint_record.oid,
               'pg_constraint'
             ) = 'marketplace_phase7_vip_acquisition_mutex:v1'
         AND pg_catalog.strpos(
               pg_catalog.pg_get_constraintdef(constraint_record.oid),
               'admitting'
             ) > 0
    )
    AND EXISTS (
      SELECT 1
        FROM pg_catalog.pg_constraint constraint_record
       WHERE constraint_record.conrelid = pg_catalog.to_regclass(
               'public.vip_subscriptions'
             )
         AND constraint_record.conname = 'vip_subscriptions_status_check'
         AND pg_catalog.obj_description(
               constraint_record.oid,
               'pg_constraint'
             ) = 'marketplace_phase7_vip_acquisition_mutex:v1'
         AND pg_catalog.strpos(
               pg_catalog.pg_get_constraintdef(constraint_record.oid),
               'incomplete'
             ) > 0
         AND pg_catalog.strpos(
               pg_catalog.pg_get_constraintdef(constraint_record.oid),
               'paused'
             ) > 0
         AND pg_catalog.strpos(
               pg_catalog.pg_get_constraintdef(constraint_record.oid),
               'incomplete_expired'
             ) > 0
    )
    AND NOT EXISTS (
      SELECT 1
        FROM pg_catalog.pg_trigger trigger_record
       WHERE trigger_record.tgrelid = pg_catalog.to_regclass(
               'public.vip_subscriptions'
             )
         AND trigger_record.tgname = 'trg_sync_profile_vip'
         AND NOT trigger_record.tgisinternal
    )
    AND EXISTS (
      SELECT 1
        FROM pg_catalog.pg_constraint constraint_record
       WHERE constraint_record.conrelid = pg_catalog.to_regclass(
               'public.vip_subscriptions'
             )
         AND constraint_record.conname = 'vip_subscriptions_user_id_key'
         AND constraint_record.contype = 'u'
    )
    THEN 'marketplace_phase7_vip_acquisition_mutex:v1'
    ELSE NULL
  END
$$;


ALTER FUNCTION public.marketplace_phase7_vip_acquisition_mutex_version() OWNER TO postgres;

