--
-- Name: mass_fund_horses(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mass_fund_horses(p_club_id uuid DEFAULT NULL::uuid, p_amount numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_horse_count integer;
  v_per_horse numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  -- Count eligible horses (users marked as bots in club_members)
  SELECT COUNT(*) INTO v_horse_count
  FROM club_members
  WHERE (p_club_id IS NULL OR club_id = p_club_id)
    AND is_bot = true
    AND is_active = true;

  IF v_horse_count = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'no active horses found');
  END IF;

  v_per_horse := FLOOR(p_amount / v_horse_count);

  UPDATE club_members
  SET chip_balance = COALESCE(chip_balance, 0) + v_per_horse::integer, updated_at = NOW()
  WHERE (p_club_id IS NULL OR club_id = p_club_id)
    AND is_bot = true
    AND is_active = true;

  RETURN jsonb_build_object(
    'success', true,
    'horses_funded', v_horse_count,
    'per_horse', v_per_horse,
    'total_distributed', v_per_horse * v_horse_count
  );
END;
$$;


