--
-- Name: mint_club_chips(uuid, numeric, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mint_club_chips(p_club_id uuid, p_amount numeric, p_minted_by uuid DEFAULT NULL::uuid, p_diamonds_cost numeric DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_pool_before numeric;
  v_pool_after numeric;
  v_club_name text;
  v_union uuid;
begin
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'amount must be > 0');
  end if;
  if p_minted_by is null then
    return jsonb_build_object('success', false, 'error', 'minter identity required');
  end if;

  select coalesce(chip_pool, 0), name, union_id
    into v_pool_before, v_club_name, v_union
  from clubs where id = p_club_id for update;

  if v_club_name is null then
    return jsonb_build_object('success', false, 'error', 'club not found');
  end if;

  -- Dan 2026-08-22: chips are minted IN THE UNION ONLY and sent to the clubs.
  -- Even the union owner may not mint straight into a member club's pool -
  -- that path would put minted chips outside the union ledger. Mint to the
  -- union (fn_mint_chips_from_diamonds / fn_union_mint_chips) and transfer
  -- with fn_union_send_chips_to_club instead.
  if v_union is not null then
    return jsonb_build_object('success', false,
      'error', 'This Club Is In A Union - Chips Are Minted In The Union And Sent To The Club, Never Minted In The Club.');
  end if;

  if not exists (
    select 1 from clubs c
    where c.id = p_club_id
      and (
        c.owner_id = p_minted_by
        or exists (
          select 1 from club_members cm
          where cm.club_id = p_club_id
            and cm.user_id = p_minted_by
            and cm.role in ('owner', 'co_owner', 'admin')
        )
      )
  ) then
    return jsonb_build_object('success', false, 'error', 'not authorized to mint for this club');
  end if;

  update clubs
  set chip_pool = coalesce(chip_pool, 0) + p_amount,
      updated_at = now()
  where id = p_club_id;
  v_pool_after := v_pool_before + p_amount;

  insert into chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after)
  values (p_club_id, p_minted_by, null, p_amount, 'mint',
          coalesce(p_notes, 'Minted ' || p_amount::text || ' chips'), v_pool_after);

  return jsonb_build_object('success', true, 'club_id', p_club_id,
    'pool_before', v_pool_before, 'pool_after', v_pool_after);
end $$;


