--
-- Name: patch_video_library_preferences(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.patch_video_library_preferences(p_expected_user_id uuid, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_preferences jsonb;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_expected_user_id THEN
    RAISE EXCEPTION 'Unauthorized: User ID mismatch';
  END IF;
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' THEN
    RAISE EXCEPTION 'Preference patch must be a JSON object';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_object_keys(p_patch) AS keys(key)
    WHERE key NOT IN ('autoplay', 'captions')
  ) THEN
    RAISE EXCEPTION 'Invalid video-library preference key';
  END IF;

  UPDATE public.profiles
     SET video_library_preferences =
           COALESCE(video_library_preferences, '{}'::jsonb) || p_patch,
         updated_at = now()
   WHERE id = p_expected_user_id
   RETURNING video_library_preferences INTO v_preferences;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profile not found';
  END IF;
  RETURN v_preferences;
END;
$$;


ALTER FUNCTION public.patch_video_library_preferences(p_expected_user_id uuid, p_patch jsonb) OWNER TO postgres;

--
-- Name: pb_end_session(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pb_end_session(p_session_id uuid, p_final_stack numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.pb_sessions
    set ended_at = now(),
        final_stack = coalesce(p_final_stack, final_stack),
        notes = coalesce(p_notes, notes)
    where id = p_session_id and user_id = auth.uid();

  insert into public.pb_stats (user_id, total_sessions, last_played_at)
    values (auth.uid(), 1, now())
  on conflict (user_id) do update
    set total_sessions = public.pb_stats.total_sessions + 1,
        last_played_at = now(),
        updated_at = now();
end $$;


