--
-- Name: pb_log_hand(uuid, integer, text, text[], text[], text, numeric, numeric, numeric, numeric, numeric, text, numeric, numeric, text, boolean, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pb_log_hand(p_session_id uuid, p_hand_number integer, p_position text, p_hole_cards text[], p_board text[], p_game_type text, p_pot_size numeric, p_bet_to_call numeric, p_stack_size numeric, p_equity numeric, p_pot_odds numeric, p_decision text, p_raise_amount numeric, p_confidence numeric, p_reasoning text, p_detected_auto boolean DEFAULT false, p_street_decisions jsonb DEFAULT NULL::jsonb, p_engine_suggestion text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_uid uuid := auth.uid();
begin
  -- Established 2026-08-26: this is SECURITY DEFINER and reachable by anon, so
  -- without this an unauthenticated caller writes rows owned by nobody.
  -- Raising, not returning NULL: the function returns the new hand id, and a
  -- caller silently handed NULL cannot tell "not logged in" from "logged
  -- nothing".
  if v_uid is null then
    raise exception 'pb_log_hand requires an authenticated caller' using errcode = '28000';
  end if;

  insert into public.pb_hands (
    session_id, user_id, hand_number, position, hole_cards, board, game_type,
    pot_size, bet_to_call, stack_size, equity, pot_odds, decision, raise_amount,
    confidence, reasoning, detected_auto, street_decisions, engine_suggestion
  ) values (
    p_session_id, v_uid, p_hand_number, p_position, p_hole_cards, p_board,
    p_game_type, p_pot_size, p_bet_to_call, p_stack_size, p_equity, p_pot_odds,
    p_decision, p_raise_amount, p_confidence, p_reasoning, p_detected_auto,
    p_street_decisions, p_engine_suggestion
  ) returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION public.pb_log_hand(p_session_id uuid, p_hand_number integer, p_position text, p_hole_cards text[], p_board text[], p_game_type text, p_pot_size numeric, p_bet_to_call numeric, p_stack_size numeric, p_equity numeric, p_pot_odds numeric, p_decision text, p_raise_amount numeric, p_confidence numeric, p_reasoning text, p_detected_auto boolean, p_street_decisions jsonb, p_engine_suggestion text) OWNER TO postgres;

--
-- Name: pb_save_profile(text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pb_save_profile(p_name text, p_slug text, p_regions jsonb, p_video_size jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  insert into public.pb_profiles (user_id, name, slug, regions, video_size)
  values (auth.uid(), p_name, p_slug, p_regions, p_video_size)
  on conflict (user_id, slug) do update
    set name = excluded.name,
        regions = excluded.regions,
        video_size = excluded.video_size,
        updated_at = now()
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION public.pb_save_profile(p_name text, p_slug text, p_regions jsonb, p_video_size jsonb) OWNER TO postgres;

