--
-- Name: player_leave_table(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.player_leave_table(p_table_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_tournament_id uuid;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'player_leave_table requires service authority'
      USING ERRCODE='28000';
  END IF;
  SELECT tb.tournament_id INTO v_tournament_id
    FROM public.tables tb WHERE tb.id=p_table_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_tournament_id IS NOT NULL THEN
    RAISE EXCEPTION 'TOURNAMENT_SEAT_EXIT_REQUIRES_TOURNAMENT_AUTHORITY'
      USING ERRCODE='55000';
  END IF;
  PERFORM public.player_leave_table_pre_tournament_guard(p_table_id,p_user_id);
END;
$$;


ALTER FUNCTION public.player_leave_table(p_table_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: player_leave_table_pre_tournament_guard(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.player_leave_table_pre_tournament_guard(p_table_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_seat_number   integer;
  v_tournament_id uuid;
BEGIN
  SELECT seat_number
    INTO v_seat_number
    FROM table_seats
   WHERE table_id = p_table_id AND user_id = p_user_id AND left_at IS NULL
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT tournament_id INTO v_tournament_id FROM tables WHERE id = p_table_id;

  IF v_tournament_id IS NULL THEN
    PERFORM public.fn_ca_declare_ledger('table_cashout', 'table_stack', p_table_id);
  END IF;

  -- CHIP CONTINUITY: this is the cron eviction / seat-expiry path (EXECUTE is
  -- service_role only). A system exit, never the player's choice.
  PERFORM public.atomic_seat_cashout_locked(p_user_id, p_table_id, v_seat_number, 'forced');
END;
$$;


ALTER FUNCTION public.player_leave_table_pre_tournament_guard(p_table_id uuid, p_user_id uuid) OWNER TO postgres;

