--
-- Name: pnm_basic_location_status(public.poker_venues); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pnm_basic_location_status(p_row public.poker_venues) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_row.venue_type = 'home_game' THEN 'approximate'
    WHEN coalesce(p_row.latitude, p_row.lat) IS NULL
      OR coalesce(p_row.longitude, p_row.lng) IS NULL THEN 'missing'
    WHEN coalesce(p_row.latitude, p_row.lat)::double precision NOT BETWEEN -90 AND 90
      OR coalesce(p_row.longitude, p_row.lng)::double precision NOT BETWEEN -180 AND 180 THEN 'conflict'
    ELSE 'unverified'
  END;
$$;


ALTER FUNCTION public.pnm_basic_location_status(p_row public.poker_venues) OWNER TO postgres;

--
-- Name: pnm_bump_venue_directory_revision(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pnm_bump_venue_directory_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.location_integrity_revision IS NOT DISTINCT FROM OLD.location_integrity_revision THEN
    NEW.location_integrity_revision := clock_timestamp();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.pnm_bump_venue_directory_revision() OWNER TO postgres;

--
-- Name: pnm_freshness_invariants(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pnm_freshness_invariants() RETURNS TABLE(check_name text, ok boolean, detail text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  with daily_candidates as materialized (
    select d.venue_id, d.event_date, d.scrape_timestamp
      from public.venue_daily_tournaments d
     where d.pnm_reader_static_servable
       and d.scrape_timestamp <= now()
       and (
         not d.pnm_verified_morning_evidence
         or coalesce(d.last_scraped, d.scrape_timestamp) <= now()
       )
       and (
         not (
           d.is_recurring is true
           or coalesce(d.flags, '[]'::jsonb) ? 'pnm_recurring_projection'
           or d.event_date is null
           or d.event_date = date '1970-01-01'
         )
         or coalesce(d.last_scraped, d.scrape_timestamp)
              between now() - interval '30 days' and now()
       )
  ),
  servable_daily as materialized (
    select * from daily_candidates
  ),
  servable_tours as materialized (
    select *
      from public.tour_stop_events
     where data_quality in (
       'scraped_verified', 'scraped_inferred', 'manual_research'
     )
       and scrape_timestamp <= now()
       and btrim(coalesce(tour_code, '')) <> ''
       and btrim(coalesce(stop_name, '')) <> ''
       and btrim(coalesce(event_name, '')) <> ''
       and stop_name ~ '[A-Za-z0-9]'
       and event_name ~ '[A-Za-z0-9]'
       and stop_name !~* '&(#[x]?[0-9a-f]+|[a-z][a-z0-9]+);'
       and event_name !~* '&(#[x]?[0-9a-f]+|[a-z][a-z0-9]+);'
       and left(ltrim(event_name), 1) not in ('@', '{', '[')
       and left(ltrim(stop_name), 1) not in ('@', '{', '[')
       and event_name !~* '(<|>|-->|(^|[[:space:]])(class|href|src|style|charset|content|data-[a-z0-9_-]+)[[:space:]]*=)'
       and stop_name !~* '(<|>|-->|(^|[[:space:]])(class|href|src|style|charset|content|data-[a-z0-9_-]+)[[:space:]]*=)'
       and event_name !~* '&(#[x]?[0-9a-f]+|[a-z][a-z0-9]+)[[:space:]]*$'
       and stop_name !~* '&(#[x]?[0-9a-f]+|[a-z][a-z0-9]+)[[:space:]]*$'
       and (start_date is not null or stop_start_date is not null)
       and (
         stop_start_date is null
         or stop_end_date is null
         or stop_end_date >= stop_start_date
       )
       and (
         start_date is null
         or stop_start_date is null
         or start_date >= stop_start_date
       )
       and (
         start_date is null
         or stop_end_date is null
         or start_date <= stop_end_date
       )
  ),
  servable_series as materialized (
    select *
      from public.poker_series
     where data_quality in (
       'scraped_verified', 'scraped_inferred', 'manual_research'
     )
       and is_suppressed is not true
       and scrape_timestamp is not null
       and scrape_timestamp <= now() + interval '5 minutes'
       and (
         case
           when source_url is not null and source_url <> ''
             then btrim(source_url)
           else btrim(scrape_url)
         end
       ) ~* '^https?://[a-z0-9]([a-z0-9._-]*[a-z0-9])?([:][0-9]{1,4})?([/?#][^[:space:]]*)?$'
       and (
         case
           when source_url is not null and source_url <> ''
             then btrim(source_url)
           else btrim(scrape_url)
         end
       ) ~* '^https?://[a-z0-9._-]*[a-z]'
       and (
         data_quality = 'manual_research'
         or (
           scrape_html_hash ~ '^[0-9A-Fa-f]{64}$'
           and scrape_html_hash !~ '^0{64}$'
           and scrape_batch_id is not null
         )
       )
  ),
  servable_live as materialized (
    select *
      from public.venue_live_tables
     where scrape_timestamp <= now()
       and (
         (
           observation_kind = 'observed'
           and data_quality = 'scraped_verified'
           and lower(regexp_replace(
             btrim(coalesce(source, '')), '[[:space:]-]+', '_', 'g'
           )) in (
             'bravo', 'bravo_scrape', 'community_verified',
             'manual_verified', 'operator', 'operator_feed', 'venue_reported'
           )
         )
         or (observation_kind = 'modeled' and data_quality = 'simulated')
         or (observation_kind = 'catalog' and data_quality = 'catalog_verified')
       )
  )
  select 'daily_tournaments_written_36h'::text,
         coalesce(max(scrape_timestamp) >= now() - interval '36 hours', false),
         'servable venue_daily_tournaments newest scrape: '
           || coalesce(max(scrape_timestamp)::text, 'never')
    from servable_daily

  union all

  select 'daily_tournaments_breadth_36h',
         count(distinct venue_id) >= 25,
         count(distinct venue_id)::text
           || ' distinct venues scraped in last 36h (floor 25)'
    from servable_daily
   where scrape_timestamp >= now() - interval '36 hours'

  union all

  select 'charity_rows_written_8d',
         coalesce(max(d.scrape_timestamp) >= now() - interval '8 days', false),
         'newest charity-venue scrape: '
           || coalesce(max(d.scrape_timestamp)::text, 'never')
    from servable_daily d
    join public.poker_venues v on v.id = d.venue_id
   where lower(coalesce(v.venue_type, '')) like '%charity%'
     and v.is_active is not false
     and v.is_suppressed is not true

  union all

  select 'tour_stops_scraped_4d',
         coalesce(max(scrape_timestamp) >= now() - interval '4 days', false),
         'servable tour_stop_events newest scrape: '
           || coalesce(max(scrape_timestamp)::text, 'never')
    from servable_tours

  union all

  select 'series_scraped_4d',
         coalesce(max(scrape_timestamp) >= now() - interval '4 days', false),
         'servable poker_series newest scrape: '
           || coalesce(max(scrape_timestamp)::text, 'never')
    from servable_series

  union all

  select 'live_tables_written_3h',
         coalesce(max(scrape_timestamp) >= now() - interval '3 hours', false),
         'servable observed, modeled or catalog venue_live_tables newest: '
           || coalesce(max(scrape_timestamp)::text, 'never')
    from servable_live

  union all

  select 'calendar_inventory_floor',
         count(*) >= 1000,
         count(*)::text || ' servable future daily rows (floor 1000)'
    from servable_daily
   where event_date >= current_date

  union all

  select 'no_sim_rows_claiming_scraped',
         count(*) = 0,
         count(*)::text || ' sim-batch rows labeled scraped_verified'
    from public.venue_live_tables
   where scrape_batch_id like 'sim-%'
     and data_quality = 'scraped_verified';
$_$;


ALTER FUNCTION public.pnm_freshness_invariants() OWNER TO postgres;

