--
-- Name: prevent_competitive_evidence_mutation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_competitive_evidence_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_entity_type text;
    v_entity_id uuid;
    v_new_entity_id uuid;
BEGIN
    IF TG_TABLE_NAME IN ('competitive_quarantine', 'trivia_pvp_settlement_decisions') THEN
        RAISE EXCEPTION '% evidence is immutable', TG_TABLE_NAME;
    ELSIF TG_TABLE_NAME = 'trivia_pvp_matches' THEN
        v_entity_type := 'trivia_pvp_match';
        v_entity_id := OLD.id;
    ELSIF TG_TABLE_NAME = 'trivia_tournaments' THEN
        v_entity_type := 'trivia_tournament';
        v_entity_id := OLD.id;
    ELSIF TG_TABLE_NAME IN ('trivia_tournament_entries', 'trivia_tournament_rounds') THEN
        v_entity_type := 'trivia_tournament';
        IF TG_OP <> 'INSERT' THEN
            v_entity_id := NULLIF(to_jsonb(OLD) ->> 'tournament_id', '')::uuid;
        END IF;
        IF TG_OP <> 'DELETE' THEN
            v_new_entity_id := NULLIF(to_jsonb(NEW) ->> 'tournament_id', '')::uuid;
        END IF;
    END IF;

    IF v_entity_id IS NOT NULL AND EXISTS (
        SELECT 1
          FROM public.competitive_quarantine AS quarantine
         WHERE quarantine.entity_type = v_entity_type
           AND quarantine.entity_id = v_entity_id
    ) THEN
        RAISE EXCEPTION 'quarantined competitive record is immutable: % %',
            v_entity_type, v_entity_id;
    END IF;
    IF v_new_entity_id IS NOT NULL AND EXISTS (
        SELECT 1
          FROM public.competitive_quarantine AS quarantine
         WHERE quarantine.entity_type = v_entity_type
           AND quarantine.entity_id = v_new_entity_id
    ) THEN
        RAISE EXCEPTION 'quarantined competitive record is immutable: % %',
            v_entity_type, v_new_entity_id;
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.prevent_competitive_evidence_mutation() OWNER TO postgres;

--
-- Name: prevent_linked_trivia_pvp_identity_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_linked_trivia_pvp_identity_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_decision public.trivia_pvp_settlement_decisions%ROWTYPE;
    v_has_link boolean;
    v_has_funding boolean;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status NOT IN ('pending', 'active')
           OR NEW.winner_id IS NOT NULL OR NEW.settlement_kind IS NOT NULL THEN
            RAISE EXCEPTION 'new PvP match must start pending/active and unsettled';
        END IF;
        RETURN NEW;
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM public.trivia_pvp_session_links WHERE match_id = OLD.id
    ) INTO v_has_link;
    IF (v_has_link OR OLD.status <> 'pending') AND (
        NEW.player1_id IS DISTINCT FROM OLD.player1_id
        OR NEW.player2_id IS DISTINCT FROM OLD.player2_id
        OR NEW.stake_amount IS DISTINCT FROM OLD.stake_amount
        OR NEW.questions IS DISTINCT FROM OLD.questions
    ) THEN
        RAISE EXCEPTION 'linked PvP match identity is immutable';
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
        (OLD.status = 'pending' AND NEW.status IN ('active', 'cancelled', 'expired', 'abandoned'))
        OR (OLD.status = 'active' AND NEW.status IN ('settling', 'cancelled', 'expired', 'abandoned'))
        OR (OLD.status = 'settling' AND NEW.status IN ('complete', 'completed'))
    ) THEN
        RAISE EXCEPTION 'invalid PvP match transition: % -> %', OLD.status, NEW.status;
    END IF;

    IF OLD.status = 'active'
       AND NEW.status IN ('cancelled', 'expired', 'abandoned') THEN
        SELECT v_has_link OR EXISTS (
            SELECT 1
              FROM public.diamond_transactions AS d
             WHERE d.reference_id IN (
                 'pvp_stake_' || OLD.id::text || '_' || OLD.player1_id::text,
                 'pvp_stake_' || OLD.id::text || '_' || OLD.player2_id::text
             )
        ) INTO v_has_funding;
        IF v_has_funding THEN
            RAISE EXCEPTION 'funded PvP match must pass through an immutable settlement decision';
        END IF;
    END IF;

    IF OLD.status IN ('complete', 'completed', 'cancelled', 'expired', 'abandoned')
       AND (
           NEW.winner_id IS DISTINCT FROM OLD.winner_id
           OR NEW.player1_score IS DISTINCT FROM OLD.player1_score
           OR NEW.player2_score IS DISTINCT FROM OLD.player2_score
           OR NEW.challenger_score IS DISTINCT FROM OLD.challenger_score
           OR NEW.opponent_score IS DISTINCT FROM OLD.opponent_score
           OR NEW.settlement_kind IS DISTINCT FROM OLD.settlement_kind
           OR NEW.completed_at IS DISTINCT FROM OLD.completed_at
       ) THEN
        RAISE EXCEPTION 'terminal PvP outcome is immutable';
    END IF;

    SELECT * INTO v_decision
      FROM public.trivia_pvp_settlement_decisions
     WHERE match_id = OLD.id;
    IF FOUND THEN
        IF NEW.winner_id IS DISTINCT FROM v_decision.winner_id
           OR NEW.player1_score IS DISTINCT FROM v_decision.player1_score
           OR NEW.player2_score IS DISTINCT FROM v_decision.player2_score
           OR NEW.settlement_kind IS DISTINCT FROM v_decision.decision_kind THEN
            RAISE EXCEPTION 'PvP match outcome differs from immutable settlement decision';
        END IF;
    ELSIF NEW.status IS DISTINCT FROM OLD.status
          AND NEW.status IN ('settling', 'complete', 'completed') THEN
        RAISE EXCEPTION 'PvP settlement decision is required before claiming/finalizing';
    END IF;

    IF NEW.status IN ('complete', 'completed') AND NEW.completed_at IS NULL THEN
        RAISE EXCEPTION 'completed PvP match requires completed_at';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.prevent_linked_trivia_pvp_identity_change() OWNER TO postgres;

--
-- Name: prevent_linked_trivia_session_identity_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_linked_trivia_session_identity_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_link public.trivia_pvp_session_links%ROWTYPE;
    v_match_created_at timestamptz;
BEGIN
    SELECT * INTO v_link
      FROM public.trivia_pvp_session_links
     WHERE session_id = OLD.id;
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    IF (
        NEW.user_id IS DISTINCT FROM OLD.user_id
        OR NEW.mode IS DISTINCT FROM OLD.mode
        OR NEW.question_ids IS DISTINCT FROM OLD.question_ids
        OR NEW.permutations IS DISTINCT FROM OLD.permutations
        OR NEW.entry_cost IS DISTINCT FROM OLD.entry_cost
        OR NEW.entry_state IS DISTINCT FROM OLD.entry_state
        OR NEW.created_at IS DISTINCT FROM OLD.created_at
        OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
    ) THEN
        RAISE EXCEPTION 'linked PvP session identity is immutable';
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
        OLD.status = 'open' AND NEW.status IN ('submitted', 'expired')
    ) THEN
        RAISE EXCEPTION 'invalid linked PvP session transition: % -> %', OLD.status, NEW.status;
    END IF;

    IF OLD.status = 'submitted' AND (
        NEW.answers IS DISTINCT FROM OLD.answers
        OR NEW.correct_count IS DISTINCT FROM OLD.correct_count
        OR NEW.score IS DISTINCT FROM OLD.score
        OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
        OR NEW.diamonds_awarded IS DISTINCT FROM OLD.diamonds_awarded
        OR (
            OLD.settlement_result IS NOT NULL
            AND NEW.settlement_result IS DISTINCT FROM OLD.settlement_result
        )
    ) THEN
        RAISE EXCEPTION 'submitted linked PvP session result is immutable';
    END IF;
    IF OLD.status = 'expired' AND (
        NEW.answers IS DISTINCT FROM OLD.answers
        OR NEW.correct_count IS DISTINCT FROM OLD.correct_count
        OR NEW.score IS DISTINCT FROM OLD.score
        OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
        OR NEW.diamonds_awarded IS DISTINCT FROM OLD.diamonds_awarded
        OR NEW.settlement_result IS DISTINCT FROM OLD.settlement_result
    ) THEN
        RAISE EXCEPTION 'expired linked PvP session result is immutable';
    END IF;

    SELECT created_at INTO v_match_created_at
      FROM public.trivia_pvp_matches
     WHERE id = v_link.match_id;
    IF (
        NEW.status IS NULL
        OR NEW.status NOT IN ('open', 'submitted', 'expired')
        OR (
            NEW.status = 'submitted'
            AND (
                NEW.submitted_at IS NULL
                OR NEW.expires_at IS NULL
                OR NEW.submitted_at > NEW.expires_at
                OR NEW.submitted_at > v_match_created_at + interval '30 minutes'
                OR NEW.correct_count IS NULL
                OR NEW.correct_count < 0
                OR NEW.correct_count > 20
            )
        )
    ) THEN
        RAISE EXCEPTION 'linked PvP session result is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.prevent_linked_trivia_session_identity_change() OWNER TO postgres;

--
-- Name: process_tournament_rebuy(uuid, uuid, text, numeric, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_tournament_rebuy(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer DEFAULT NULL::integer, p_client_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_receipt_key text;
  v_request jsonb;
  v_response jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(530090, 1);

  IF NOT (COALESCE(auth.role(), 'service_role') = 'service_role')
     AND (auth.uid() IS NULL OR auth.uid() <> p_user_id) THEN
    RAISE EXCEPTION 'process_tournament_rebuy: caller may only transact for themselves'
      USING ERRCODE = '42501';
  END IF;

  v_receipt_key := CASE
    WHEN p_rebuy_type = 'addon'
      THEN 'tourney:' || p_tournament_id::text || ':addon:' || p_user_id::text
    WHEN p_client_token IS NOT NULL AND length(btrim(p_client_token)) > 0
      THEN 'tourney:' || p_tournament_id::text || ':' || p_rebuy_type || ':' ||
           p_user_id::text || ':tok:' || btrim(p_client_token)
    ELSE NULL
  END;
  v_request := jsonb_build_object(
    'tournament_id', p_tournament_id,
    'user_id', p_user_id,
    'rebuy_type', p_rebuy_type,
    'cost', p_cost,
    'chips', p_chips,
    'current_level', p_current_level,
    'client_token', CASE WHEN p_client_token IS NULL THEN NULL ELSE btrim(p_client_token) END
  );
  v_response := public.fn_claim_entry_purchase_receipt(
    'tournament_chip_purchase', v_receipt_key, v_request
  );
  IF NOT COALESCE((v_response->>'claimed')::boolean, false) THEN
    RETURN v_response->'response';
  END IF;

  /* A historical key has no response/argument receipt. It cannot truthfully
     answer a post-boundary retry, so refuse instead of guessing success from
     a key that binds only user and amount. Every call committed through this
     wrapper carries the complete receipt above in the same transaction. */
  IF v_receipt_key IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.wallet_credit_idempotency k WHERE k.key = v_receipt_key
  ) THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_RECEIPT_UNBOUND: this historical tournament purchase key has no exact response receipt'
      USING ERRCODE = '55000';
  END IF;

  IF public.fn_entry_purchases_frozen() THEN
    RAISE EXCEPTION
      'PLATFORM_FROZEN: scheduled maintenance has closed rebuys and add-ons; no chips moved'
      USING ERRCODE = '55006',
            HINT = 'Retry after the maintenance break has ended.';
  END IF;

  v_response := public.process_tournament_rebuy_before_maintenance_announcement_gate(
    p_tournament_id,
    p_user_id,
    p_rebuy_type,
    p_cost,
    p_chips,
    p_current_level,
    p_client_token
  );
  RETURN public.fn_record_entry_purchase_receipt(
    'tournament_chip_purchase', v_receipt_key, v_request, v_response
  );
END;
$$;


ALTER FUNCTION public.process_tournament_rebuy(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer, p_client_token text) OWNER TO postgres;

--
-- Name: process_tournament_rebuy_before_atomic_live_seat_lock(uuid, uuid, text, numeric, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_tournament_rebuy_before_atomic_live_seat_lock(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer, p_client_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t record; v_p record; v_balance numeric; v_ratio numeric;
  v_is_bounty boolean; v_bounty_head numeric;
  v_base numeric; v_fee numeric; v_total numeric;
  v_add integer; v_new_chips integer; v_seat record;
  v_key text; v_inserted integer; v_cap integer; v_level integer; v_cat text;
  v_club uuid; v_legacy_ratio numeric; v_legacy_total numeric;
  v_stack_after numeric; v_expected numeric; v_fee_ratio numeric;
  v_led_cat text; v_led_cp text; v_led_ent text; v_led_tid text; -- CHIP STANDARD 1.2 2026-09-02
BEGIN
  IF NOT (COALESCE(auth.role(), 'service_role') = 'service_role')
     AND (auth.uid() IS NULL OR auth.uid() <> p_user_id) THEN
    RAISE EXCEPTION 'process_tournament_rebuy: caller may only transact for themselves'
      USING ERRCODE = '42501';
  END IF;
  IF p_rebuy_type NOT IN ('rebuy','reentry','addon') THEN
    RAISE EXCEPTION 'Invalid rebuy type: %', p_rebuy_type;
  END IF;

  SELECT id, name, club_id, status, buy_in_amount, buy_in_fee, starting_chips,
         is_rebuy, is_reentry, add_on_available, addon_period_triggered,
         rebuy_cost, rebuy_chips, rebuy_levels, late_reg_levels, max_rebuys,
         max_reentries, addon_cost, addon_chips, addon_levels, current_level, prize_pool,
         is_bounty, is_pko, is_mystery_bounty, bounty_amount
    INTO v_t FROM tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tournament not found'; END IF;
  IF v_t.status NOT IN ('RUNNING','REGISTERING','ANNOUNCED') THEN
    RAISE EXCEPTION 'Tournament is not accepting chip purchases (status %)', v_t.status;
  END IF;

  SELECT id, chips, status, prize, rebuys, add_on, table_id, club_id INTO v_p
    FROM tournament_players
   WHERE tournament_id = p_tournament_id AND user_id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Player not registered in this tournament'; END IF;
  IF v_p.status = 'eliminated' AND COALESCE(v_p.prize, 0) > 0 THEN
    RAISE EXCEPTION 'Finishing Place Already Paid - A Rebuy Cannot Resurrect A Settled Result';
  END IF;
  v_club := COALESCE(v_p.club_id, public.fn_player_home_club(p_user_id, NULL));
  IF v_club IS NULL THEN
    RAISE EXCEPTION 'No club wallet resolves for this tournament purchase';
  END IF;

  v_level := COALESCE(v_t.current_level, COALESCE(p_current_level, 0));
  v_cat   := CASE WHEN p_rebuy_type = 'addon' THEN 'addon' ELSE 'rebuy' END;

  -- Only an ADD-ON demands a live seat (a mid-play purchase by definition).
  -- A rebuy without a seat is now the normal race-recovery shape: the chips
  -- land on the player row and the seating sweep places them.
  IF p_rebuy_type = 'addon' THEN
    PERFORM 1 FROM table_seats s
      JOIN tables tb ON tb.id = s.table_id
     WHERE s.user_id = p_user_id AND s.left_at IS NULL
       AND tb.tournament_id = p_tournament_id
     LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'No Live Seat For This % - Refusing To Charge For Chips That Would Be Overwritten By The Seat Sync', p_rebuy_type;
    END IF;
  END IF;

  IF p_rebuy_type = 'addon' THEN
    v_key := 'tourney:' || p_tournament_id || ':addon:' || p_user_id;
  ELSIF p_client_token IS NOT NULL AND length(btrim(p_client_token)) > 0 THEN
    v_key := 'tourney:' || p_tournament_id || ':' || p_rebuy_type || ':'
             || p_user_id || ':tok:' || btrim(p_client_token);
  ELSE
    v_key := 'tourney:' || p_tournament_id || ':' || p_rebuy_type || ':'
             || p_user_id || ':#' || COALESCE(v_p.rebuys, 0);
  END IF;

  IF p_rebuy_type <> 'addon' AND p_client_token IS NULL AND EXISTS (
      SELECT 1 FROM wallet_transactions w
       WHERE w.user_id = p_user_id AND w.related_entity_id = p_tournament_id
         AND w.category = v_cat
         AND w.created_at > now() - interval '1500 milliseconds') THEN
    RETURN jsonb_build_object('success', true, 'idempotent', true,
                              'reason', 'double_submit_collapsed',
                              'new_stack', v_p.chips, 'rebuy_type', p_rebuy_type);
  END IF;

  INSERT INTO wallet_credit_idempotency (key, user_id, amount)
  VALUES (v_key, p_user_id, COALESCE(p_cost, 0)) ON CONFLICT (key) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 0 THEN
    RETURN jsonb_build_object('success', true, 'idempotent', true,
                              'new_stack', v_p.chips, 'rebuy_type', p_rebuy_type);
  END IF;

  IF p_rebuy_type = 'addon' THEN
    IF NOT COALESCE(v_t.add_on_available,false) THEN
      RAISE EXCEPTION 'Add-ons are not offered in this tournament'; END IF;
    IF COALESCE(v_p.add_on,false) THEN RAISE EXCEPTION 'Add-on already taken'; END IF;
    v_cap := COALESCE(NULLIF(v_t.late_reg_levels,0), NULLIF(v_t.rebuy_levels,0), 0)
             + COALESCE(v_t.addon_levels,1);
    IF v_cap > 0 AND v_level >= v_cap THEN
      RAISE EXCEPTION 'Add-on period has closed (level % of %)', v_level, v_cap; END IF;
    v_base := COALESCE(NULLIF(v_t.addon_cost,0), v_t.buy_in_amount, 0);
    v_add  := COALESCE(NULLIF(v_t.addon_chips,0), v_t.starting_chips, 0)::integer;
  ELSE
    IF p_rebuy_type='rebuy' AND NOT COALESCE(v_t.is_rebuy,false) THEN
      RAISE EXCEPTION 'Rebuys are not offered in this tournament'; END IF;
    IF p_rebuy_type='reentry' AND NOT COALESCE(v_t.is_reentry,false) THEN
      RAISE EXCEPTION 'Re-entries are not offered in this tournament'; END IF;
    v_cap := COALESCE(NULLIF(v_t.rebuy_levels,0), NULLIF(v_t.late_reg_levels,0), 0);
    IF v_cap > 0 AND COALESCE(v_t.add_on_available,false) THEN
      v_cap := v_cap + COALESCE(NULLIF(v_t.addon_levels,0),1); END IF;
    IF v_cap > 0 AND v_level >= v_cap THEN
      RAISE EXCEPTION 'Rebuy period has closed (level % of %)', v_level, v_cap; END IF;
    IF p_rebuy_type='rebuy' AND v_t.max_rebuys IS NOT NULL
       AND COALESCE(v_p.rebuys,0) >= v_t.max_rebuys THEN
      RAISE EXCEPTION 'Rebuy limit reached (% of %)', v_p.rebuys, v_t.max_rebuys; END IF;
    IF p_rebuy_type='reentry' AND v_t.max_reentries IS NOT NULL
       AND COALESCE(v_p.rebuys,0) >= v_t.max_reentries THEN
      RAISE EXCEPTION 'Re-entry limit reached (% of %)', v_p.rebuys, v_t.max_reentries; END IF;
    IF p_rebuy_type='rebuy' AND COALESCE(v_p.chips,0) > COALESCE(v_t.starting_chips,0) THEN
      RAISE EXCEPTION 'Stack too high for a rebuy'; END IF;
    v_base := COALESCE(NULLIF(v_t.rebuy_cost,0), v_t.buy_in_amount, 0);
    v_add  := COALESCE(NULLIF(v_t.rebuy_chips,0), v_t.starting_chips, 0)::integer;
  END IF;

  v_legacy_ratio := CASE WHEN COALESCE(v_t.buy_in_amount,0) > 0 AND COALESCE(v_t.buy_in_fee,0) > 0
                         THEN v_t.buy_in_fee / v_t.buy_in_amount ELSE 0.1 END;
  v_fee_ratio := CASE WHEN COALESCE(v_t.buy_in_amount,0) + COALESCE(v_t.buy_in_fee,0) > 0
                           AND COALESCE(v_t.buy_in_fee,0) > 0
                      THEN v_t.buy_in_fee / (v_t.buy_in_amount + v_t.buy_in_fee)
                      ELSE 0.1 END;
  v_ratio := CASE WHEN p_rebuy_type = 'addon' THEN 0 ELSE v_fee_ratio END;

  v_total := round(v_base::numeric);
  v_fee := CASE WHEN v_ratio > 0 AND v_total > 0
                THEN LEAST(trunc(v_total * v_ratio * 100 + 0.000001) / 100,
                           trunc(v_total * 0.1 * 100 + 0.000001) / 100)
                ELSE 0 END;
  v_base := round(v_total - v_fee, 2);
  v_is_bounty := COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
                 OR COALESCE(v_t.is_mystery_bounty,false);
  IF v_is_bounty AND p_rebuy_type <> 'addon' THEN
    v_bounty_head := LEAST(GREATEST(0, round(COALESCE(v_t.bounty_amount,0))), v_base);
    v_base := v_base - v_bounty_head;
  ELSE
    v_bounty_head := 0;
  END IF;

  IF p_cost IS NOT NULL AND abs(p_cost - v_total) > 0.01 THEN
    v_legacy_total := v_total + round(v_total * v_legacy_ratio, 2);
    IF abs(p_cost - v_legacy_total) > 0.01 THEN
      RAISE EXCEPTION 'Price mismatch: client quoted %, server computed % (base % + fee %)',
        p_cost, v_total, v_base, v_fee;
    END IF;
  END IF;

  PERFORM public.fn_ensure_club_wallet(p_user_id, v_club);
  SELECT chip_balance INTO v_balance FROM club_members
   WHERE user_id = p_user_id AND club_id = v_club FOR UPDATE;
  IF v_balance IS NULL OR v_balance < v_total THEN
    RAISE EXCEPTION 'Insufficient club chips: need % (incl. % fee), have %',
      v_total, v_fee, COALESCE(v_balance,0);
  END IF;
  -- CHIP STANDARD 1.2 (2026-09-02): the rebuy / re-entry / add-on debit names its
  -- counterparty (v_cat is 'rebuy' or 'addon', both ledger words) and stamps the
  -- tournament. set_config, not fn_ca_declare_ledger, so a vocabulary miss can never
  -- refuse the purchase. Restored right after the write.
  v_led_cat := current_setting('app.ledger_category', true);
  v_led_cp  := current_setting('app.ledger_counterparty', true);
  v_led_ent := current_setting('app.ledger_counterparty_entity', true);
  v_led_tid := current_setting('app.ledger_tournament', true);
  PERFORM set_config('app.ledger_category', v_cat, true);
  PERFORM set_config('app.ledger_counterparty', 'prize_liability', true);
  PERFORM set_config('app.ledger_counterparty_entity', p_tournament_id::text, true);
  PERFORM set_config('app.ledger_tournament', p_tournament_id::text, true);
  UPDATE club_members SET chip_balance = chip_balance - v_total, updated_at = now()
   WHERE user_id = p_user_id AND club_id = v_club;
  PERFORM set_config('app.ledger_category', COALESCE(v_led_cat, ''), true);
  PERFORM set_config('app.ledger_counterparty', COALESCE(v_led_cp, ''), true);
  PERFORM set_config('app.ledger_counterparty_entity', COALESCE(v_led_ent, ''), true);
  PERFORM set_config('app.ledger_tournament', COALESCE(v_led_tid, ''), true);

  IF p_rebuy_type='reentry' THEN
    UPDATE tournament_players SET chips=v_add, status='playing', eliminated_at=NULL,
           position=NULL, rebuys=COALESCE(rebuys,0)+1
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id RETURNING chips INTO v_new_chips;
  ELSIF p_rebuy_type='addon' THEN
    UPDATE tournament_players SET chips=COALESCE(chips,0)+v_add, add_on=true
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id RETURNING chips INTO v_new_chips;
  ELSE
    -- 2026-08-30: a rebuy also clears an elimination stamp the bust sweep may
    -- have raced onto the row (guarded above: never with a paid prize).
    UPDATE tournament_players SET chips=COALESCE(chips,0)+v_add, status='playing',
           eliminated_at=NULL, position=NULL,
           rebuys=COALESCE(rebuys,0)+1
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id RETURNING chips INTO v_new_chips;
  END IF;

  IF v_bounty_head > 0 THEN
    UPDATE tournament_players
       SET current_bounty = CASE WHEN p_rebuy_type = 'reentry' THEN v_bounty_head
                                 ELSE COALESCE(current_bounty, 0) + v_bounty_head END
     WHERE tournament_id = p_tournament_id AND user_id = p_user_id;
  END IF;

  SELECT s.id, s.stack INTO v_seat
    FROM table_seats s JOIN tables tb ON tb.id=s.table_id
   WHERE s.user_id=p_user_id AND s.left_at IS NULL AND tb.tournament_id=p_tournament_id
   ORDER BY (tb.status IS DISTINCT FROM 'closed') DESC, s.joined_at DESC NULLS LAST, s.id DESC
   LIMIT 1;
  IF FOUND THEN
    UPDATE table_seats
       SET stack = CASE WHEN p_rebuy_type='reentry' THEN v_add ELSE COALESCE(stack,0)+v_add END
     WHERE id=v_seat.id
    RETURNING stack INTO v_stack_after;

    v_expected := CASE WHEN p_rebuy_type='reentry' THEN v_add
                       ELSE COALESCE(v_seat.stack,0) + v_add END;
    IF v_stack_after IS NULL OR v_stack_after <> v_expected THEN
      RAISE EXCEPTION
        'Chip Grant Did Not Land: % Expected Stack % (% + %), Seat % Holds % - Aborting So No Charge Is Made',
        p_rebuy_type, v_expected, COALESCE(v_seat.stack,0), v_add, v_seat.id, v_stack_after;
    END IF;

    UPDATE tournament_players
       SET chips=(SELECT stack FROM table_seats WHERE id=v_seat.id)::integer
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id RETURNING chips INTO v_new_chips;
  ELSIF p_rebuy_type = 'addon' THEN
    RAISE EXCEPTION 'Seat Disappeared During % - Aborting So No Charge Is Made', p_rebuy_type;
  END IF;
  -- 'rebuy'/'reentry' with no seat: the chips stand on the player row and
  -- ensureLateRegSeated seats them at the table that most needs a player.

  UPDATE tournaments
     SET prize_pool  = COALESCE(prize_pool, 0) + v_base,
         bounty_pool = COALESCE(bounty_pool, 0) + v_bounty_head
   WHERE id = p_tournament_id;

  IF v_fee > 0 AND v_t.club_id IS NOT NULL THEN
    INSERT INTO rake_records (hand_id, table_id, club_id, rake_amount, pot_size, num_players,
      bbj_contribution, is_tournament, tournament_id, source, metadata)
    VALUES (NULL,NULL,v_t.club_id,v_fee,v_fee,1,0,true,p_tournament_id,'process_tournament_rebuy',
      jsonb_build_object('kind','tournament_'||p_rebuy_type||'_fee','user_id',p_user_id,
                         'entry_club_id', v_club));
    UPDATE tournaments SET total_rake=COALESCE(total_rake,0)+v_fee WHERE id=p_tournament_id;
  END IF;

  INSERT INTO wallet_transactions (user_id, wallet_type, type, amount, category, description,
    related_entity_id, balance_after)
  VALUES (p_user_id,'PLAYER','debit',v_total,v_cat,
    'Tournament '||p_rebuy_type||': '||COALESCE(v_t.name,'tournament')
      ||' ('||v_base||' + '||v_fee||' fee) [club wallet]',
    p_tournament_id, v_balance-v_total);

  RETURN jsonb_build_object('success', true, 'new_stack', v_new_chips,
    'rebuy_type', p_rebuy_type, 'chips_added', v_add, 'cost', v_total, 'fee', v_fee,
    'seated', FOUND, 'bounty_head_funded', v_bounty_head);
END;
$$;


ALTER FUNCTION public.process_tournament_rebuy_before_atomic_live_seat_lock(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer, p_client_token text) OWNER TO postgres;

--
-- Name: process_tournament_rebuy_before_atomic_pool_gate(uuid, uuid, text, numeric, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_tournament_rebuy_before_atomic_pool_gate(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer DEFAULT NULL::integer, p_client_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_player public.tournament_players%ROWTYPE;
  v_latest_joined_at timestamptz;
  v_result jsonb;
BEGIN
  SELECT * INTO v_t FROM public.tournaments
   WHERE id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tournament not found'; END IF;

  SELECT * INTO v_player FROM public.tournament_players
   WHERE tournament_id=p_tournament_id AND user_id=p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Player not registered in this tournament'; END IF;

  IF p_rebuy_type IN ('rebuy','reentry','addon')
     AND (COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
          OR COALESCE(v_t.is_mystery_bounty,false))
     AND COALESCE(v_player.chips,0) <= 0 THEN
    SELECT s.joined_at INTO v_latest_joined_at
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
     ORDER BY s.joined_at DESC NULLS LAST,s.id DESC
     LIMIT 1;

    IF v_latest_joined_at IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.tournament_bounty_obligations o
       WHERE o.tournament_id=p_tournament_id
         AND o.eliminated_user_id=p_user_id
         AND o.seat_joined_at=v_latest_joined_at
         AND o.state='settled'
         AND public.fn_bounty_obligation_has_complete_marker(o.id)
    ) THEN
      RAISE EXCEPTION
        'Bounty Settlement Pending - Rebuy Or Re-Entry Cannot Replace This Entry Generation Yet'
        USING ERRCODE='55000';
    END IF;
  END IF;

  IF p_rebuy_type='addon' THEN
    IF COALESCE(v_t.prize_pool_finalized,false)
       OR v_t.addon_period_started_at IS NULL
       OR v_t.addon_period_ends_at IS NULL
       OR clock_timestamp()<v_t.addon_period_started_at
       OR clock_timestamp()>=v_t.addon_period_ends_at THEN
      RAISE EXCEPTION 'Add-On Period Is Closed Or The Prize Pool Is Already Finalized'
        USING ERRCODE='55000';
    END IF;
    -- A zero is a knockout generation, not an add-on target. Waiting for an
    -- outbox is insufficient because the stack/history/claim transaction can
    -- still be between commits; categorically refuse until a rebuy/re-entry
    -- establishes a new positive generation.
    IF COALESCE(v_player.chips,0)<=0 THEN
      RAISE EXCEPTION 'A Zero-Stack Bounty Entry Cannot Take An Add-On'
        USING ERRCODE='55000';
    END IF;
  END IF;

  -- A stone-bubble result is terminal even though its structure prize is
  -- zero. The old core used prize>0 as the terminal proxy and could resurrect
  -- this player immediately after the atomic refund committed.
  IF p_rebuy_type IN ('rebuy','reentry')
     AND v_player.status='eliminated'
     AND EXISTS (
       SELECT 1 FROM public.tournament_obligations o
        WHERE o.tournament_id=p_tournament_id AND o.kind='bubble_protection'
          AND o.user_id=p_user_id AND o.amount_paid=o.amount_owed
          AND o.amount_paid>0 AND o.settled_at IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'Bubble Protection Already Paid - This Result Cannot Be Resurrected'
      USING ERRCODE='55000';
  END IF;

  v_result := public.process_tournament_rebuy_before_bounty_guard_20260907(
    p_tournament_id,p_user_id,p_rebuy_type,p_cost,p_chips,p_current_level,p_client_token);
  IF COALESCE((v_result->>'success')::boolean,false)
     AND p_rebuy_type IN ('rebuy','reentry') THEN
    PERFORM public.fn_after_tournament_rebuy(p_tournament_id,p_user_id,p_rebuy_type);
  END IF;
  IF COALESCE((v_result->>'success')::boolean,false)
     AND p_rebuy_type IN ('rebuy','reentry','addon') THEN
    PERFORM public.fn_emit_tournament_manager_wake(p_tournament_id,p_rebuy_type);
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.process_tournament_rebuy_before_atomic_pool_gate(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer, p_client_token text) OWNER TO postgres;

--
-- Name: process_tournament_rebuy_before_bounty_guard_20260907(uuid, uuid, text, numeric, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_tournament_rebuy_before_bounty_guard_20260907(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer DEFAULT NULL::integer, p_client_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_cutoff integer;
BEGIN
  SELECT * INTO v_t
  FROM public.tournaments
  WHERE id = p_tournament_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tournament not found'; END IF;

  v_cutoff := COALESCE(NULLIF(v_t.late_reg_levels, 0), NULLIF(v_t.rebuy_levels, 0), 0);

  IF p_rebuy_type = 'addon' THEN
    IF v_t.addon_period_started_at IS NULL OR v_t.addon_period_ends_at IS NULL THEN
      RAISE EXCEPTION 'Add-on period has not begun';
    END IF;
    IF clock_timestamp() < v_t.addon_period_started_at THEN
      RAISE EXCEPTION 'Add-on period has not begun';
    END IF;
    IF clock_timestamp() >= v_t.addon_period_ends_at THEN
      RAISE EXCEPTION 'Add-on period has closed';
    END IF;
  ELSIF p_rebuy_type IN ('rebuy', 'reentry')
        AND v_cutoff > 0
        AND COALESCE(p_current_level, v_t.current_level, 0) >= v_cutoff THEN
    RAISE EXCEPTION 'Rebuy period has closed';
  END IF;

  RETURN public.process_tournament_rebuy_before_one_minute_addon(
    p_tournament_id, p_user_id, p_rebuy_type, p_cost, p_chips, p_current_level,
    p_client_token
  );
END;
$$;


ALTER FUNCTION public.process_tournament_rebuy_before_bounty_guard_20260907(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer, p_client_token text) OWNER TO postgres;

--
-- Name: process_tournament_rebuy_before_maintenance_announcement_gate(uuid, uuid, text, numeric, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_tournament_rebuy_before_maintenance_announcement_gate(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer DEFAULT NULL::integer, p_client_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_player public.tournament_players%ROWTYPE;
  v_level_cap integer;
  v_addon_open boolean;
BEGIN
  SELECT * INTO v_t FROM public.tournaments
   WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tournament not found'; END IF;
  IF COALESCE(v_t.prize_pool_finalized, false) THEN
    RAISE EXCEPTION 'Tournament prize pool is finalized; chip purchases are closed';
  END IF;
  v_addon_open := COALESCE(v_t.add_on_available, false)
                  AND COALESCE(v_t.addon_period_triggered, false)
                  AND v_t.addon_period_started_at IS NOT NULL
                  AND v_t.addon_period_ends_at IS NOT NULL
                  AND clock_timestamp() >= v_t.addon_period_started_at
                  AND clock_timestamp() < v_t.addon_period_ends_at;
  IF p_rebuy_type = 'addon' THEN
    IF v_t.status NOT IN ('REGISTERING', 'RUNNING') THEN
      RAISE EXCEPTION 'Tournament is not accepting add-ons (status %)', v_t.status;
    END IF;
    IF NOT v_addon_open THEN
      RAISE EXCEPTION 'Add-on period is not open';
    END IF;
    /* Parent first, then the exact roster row: the money core must never sell
       an add-on to a spectator, a busted player, or a player who has already
       consumed the one add-on. Keep this lock through the delegated wallet,
       stack, ledger and pool transaction so elimination and duplicate-click
       races have only one durable winner. */
    SELECT * INTO v_player
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.user_id = p_user_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Tournament player not found for add-on';
    END IF;
    IF v_player.status IS DISTINCT FROM 'playing' THEN
      RAISE EXCEPTION 'Only a playing tournament player may buy an add-on';
    END IF;
    IF COALESCE(v_player.add_on, false) THEN
      RAISE EXCEPTION 'Tournament player has already purchased an add-on';
    END IF;
  ELSIF p_rebuy_type IN ('rebuy', 'reentry') THEN
    IF v_t.status <> 'RUNNING' THEN
      RAISE EXCEPTION 'Tournament is not accepting rebuys or re-entries (status %)', v_t.status;
    END IF;
    v_level_cap := COALESCE(NULLIF(v_t.rebuy_levels, 0),
                            NULLIF(v_t.late_reg_levels, 0), 0);
    /* The caller's level is display data, not authority. A stale or forged low
       p_current_level must not hold a purchase window open after the persisted
       tournament level has closed it. */
    IF v_level_cap > 0 AND v_t.current_level IS NULL AND NOT v_addon_open THEN
      RAISE EXCEPTION 'Current tournament level is unknown; rebuy refused';
    END IF;
    IF v_level_cap > 0 AND v_t.current_level >= v_level_cap
       AND NOT v_addon_open THEN
      RAISE EXCEPTION 'Rebuy period has closed';
    END IF;
    IF v_level_cap <= 0 AND COALESCE(v_t.late_reg_mins, 0) > 0
       AND (v_t.started_at IS NULL OR clock_timestamp()
            >= v_t.started_at + make_interval(mins => v_t.late_reg_mins))
       AND NOT v_addon_open THEN
      RAISE EXCEPTION 'Timed rebuy period has closed';
    END IF;
    IF v_level_cap <= 0 AND COALESCE(v_t.late_reg_mins, 0) <= 0
       AND NOT v_addon_open THEN
      RAISE EXCEPTION 'Tournament has no bounded rebuy period';
    END IF;
  ELSE
    RAISE EXCEPTION 'Invalid rebuy type: %', p_rebuy_type;
  END IF;

  /* Call the audited money core directly. The superseded one-minute wrapper
     is retained under its historical name but had closed rebuys at the base
     level even during the add-on clock. This wrapper owns the authoritative
     lifecycle/clock gate above, then delegates wallet, stack, ledger and pool
     mutations to the locked core. */
  RETURN public.process_tournament_rebuy_before_one_minute_addon(
    p_tournament_id, p_user_id, p_rebuy_type, p_cost, p_chips,
    v_t.current_level, p_client_token);
END;
$$;


ALTER FUNCTION public.process_tournament_rebuy_before_maintenance_announcement_gate(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer, p_client_token text) OWNER TO postgres;

--
-- Name: process_tournament_rebuy_before_one_minute_addon(uuid, uuid, text, numeric, numeric, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_tournament_rebuy_before_one_minute_addon(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer DEFAULT NULL::integer, p_client_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_player public.tournament_players%ROWTYPE;
  v_player_after public.tournament_players%ROWTYPE;
  v_seat record;
  v_stack_after numeric;
  v_result jsonb;
BEGIN
  SELECT t.id INTO v_tournament_id
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found';
  END IF;

  SELECT * INTO v_player
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.user_id = p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Player not registered in this tournament';
  END IF;

  IF p_rebuy_type = 'addon' THEN
    IF v_player.status IS DISTINCT FROM 'playing' THEN
      RAISE EXCEPTION 'Only a playing tournament player may buy an add-on';
    END IF;
    IF COALESCE(v_player.add_on, false) THEN
      RAISE EXCEPTION 'Tournament player has already purchased an add-on';
    END IF;

    SELECT s.id, s.stack INTO v_seat
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id = s.table_id
     WHERE s.user_id = p_user_id
       AND s.left_at IS NULL
       AND tb.tournament_id = p_tournament_id
     ORDER BY (tb.status IS DISTINCT FROM 'closed') DESC,
              s.joined_at DESC NULLS LAST, s.id DESC
     LIMIT 1
     FOR UPDATE OF s;
    IF NOT FOUND THEN
      RAISE EXCEPTION
        'No Live Seat For This addon - Refusing To Charge For Chips That Would Be Overwritten By The Seat Sync';
    END IF;
  END IF;

  v_result := public.process_tournament_rebuy_before_atomic_live_seat_lock(
    p_tournament_id, p_user_id, p_rebuy_type, p_cost, p_chips,
    p_current_level, p_client_token);

  IF p_rebuy_type = 'addon' THEN
    SELECT * INTO v_player_after
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.user_id = p_user_id;
    IF NOT FOUND OR NOT COALESCE(v_player_after.add_on, false) THEN
      RAISE EXCEPTION
        'Add-on money core returned without recording the player add-on; transaction aborted';
    END IF;

    /* This guarded final write is also the durable row-count proof. Because
       the exact seat has been locked since before the money core ran, a leave
       cannot interleave between eligibility, stack grant and this assertion. */
    UPDATE public.table_seats s
       SET stack = v_player_after.chips
     WHERE s.id = v_seat.id
       AND s.left_at IS NULL
       AND s.stack IS NOT DISTINCT FROM v_player_after.chips
    RETURNING s.stack INTO v_stack_after;
    IF NOT FOUND OR v_stack_after IS DISTINCT FROM v_player_after.chips THEN
      RAISE EXCEPTION
        'Live add-on seat changed before its exact stack could be committed; transaction aborted';
    END IF;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.process_tournament_rebuy_before_one_minute_addon(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer, p_client_token text) OWNER TO postgres;

--
-- Name: promo_apply_playthrough(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.promo_apply_playthrough(p_club_id uuid, p_user_id uuid, p_wagered numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_promo    numeric;
  v_required numeric;
  v_wagered  numeric;
  v_released numeric := 0;
  v_caller   text := COALESCE(auth.role(), '');
BEGIN
  /* ZERO-DRIFT (2026-08-31): the wager figure is engine truth. Only the
     engine (service_role) or trusted admin context may apply playthrough -
     an authenticated user could previously release ANY member's locked promo
     by claiming an arbitrary wager. Fail closed. */
  IF NOT (v_caller = 'service_role'
          OR (v_caller = '' AND current_user IN ('postgres', 'supabase_admin'))) THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'engine_only');
  END IF;

  IF p_wagered IS NULL OR p_wagered <= 0 THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'no_wager');
  END IF;

  BEGIN
    INSERT INTO player_stats (id, user_id, club_id, total_losses, updated_at)
    VALUES (gen_random_uuid(), p_user_id, p_club_id, p_wagered, now())
    ON CONFLICT (user_id, club_id) DO UPDATE
       SET total_losses = player_stats.total_losses + EXCLUDED.total_losses,
           updated_at   = now();
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  SELECT COALESCE(promo_balance, 0), COALESCE(promo_playthrough_required, 0), COALESCE(promo_wagered, 0)
    INTO v_promo, v_required, v_wagered
    FROM club_members
   WHERE club_id = p_club_id AND user_id = p_user_id
   FOR UPDATE;

  IF v_promo IS NULL OR v_promo <= 0 OR v_required <= 0 THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'no_outstanding_promo');
  END IF;

  v_wagered := v_wagered + p_wagered;

  IF v_wagered >= v_required THEN
    /* Exact release - the old v_promo::integer truncated fractions into
       nothing while promo_balance was zeroed in full. */
    v_released := round(v_promo, 2);

    PERFORM set_config('app.ledger_category', 'promo_release', true);
    PERFORM set_config('app.ledger_counterparty', 'promo_wallet', true);
    PERFORM set_config('app.ledger_counterparty_entity', p_user_id::text, true);
    PERFORM set_config('app.ledger_autoskip_club_members', '1', true);
    UPDATE club_members
       SET chip_balance               = COALESCE(chip_balance, 0) + v_released,
           promo_balance              = 0,
           promo_playthrough_required = 0,
           promo_wagered              = 0,
           updated_at                 = NOW()
     WHERE club_id = p_club_id AND user_id = p_user_id;
    PERFORM set_config('app.ledger_autoskip_club_members', '0', true);

    INSERT INTO chip_transactions (id, club_id, to_user_id, amount, transaction_type, notes, created_at)
    VALUES (gen_random_uuid(), p_club_id, p_user_id, v_released, 'promo_released',
            'Promo bonus released to cashable balance after playthrough met', NOW());
  ELSE
    UPDATE club_members
       SET promo_wagered = v_wagered, updated_at = NOW()
     WHERE club_id = p_club_id AND user_id = p_user_id;
  END IF;

  RETURN jsonb_build_object('applied', true, 'released', v_released,
                            'wagered', v_wagered, 'required', v_required);
END;
$$;


ALTER FUNCTION public.promo_apply_playthrough(p_club_id uuid, p_user_id uuid, p_wagered numeric) OWNER TO postgres;

--
-- Name: promote_home_game_waitlist(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.promote_home_game_waitlist(p_game_id uuid, p_caller_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_game RECORD; v_group RECORD;
    v_seats_open int; v_promoted_ids uuid[] := ARRAY[]::uuid[];
    v_rsvp RECORD; v_is_trigger_call boolean; v_is_service_role boolean;
    v_uid uuid;
BEGIN
    v_is_trigger_call := (current_setting('app.hg_waitlist_auto_promote', true) = '1');
    v_is_service_role := (auth.role() = 'service_role');

    IF v_is_trigger_call OR v_is_service_role THEN NULL;
    ELSE
        IF p_caller_user_id IS NULL THEN
            RAISE EXCEPTION 'UNAUTHORIZED' USING HINT = 'promote_home_game_waitlist requires p_caller_user_id';
        END IF;
        IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN
            RAISE EXCEPTION 'UNAUTHORIZED' USING HINT = 'auth.uid() must match p_caller_user_id';
        END IF;
    END IF;

    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
    IF v_game.status NOT IN ('scheduled','confirmed') THEN RAISE EXCEPTION 'GAME_NOT_OPEN'; END IF;

    IF NOT v_is_trigger_call AND NOT v_is_service_role THEN
        SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;
        IF v_game.host_id <> p_caller_user_id
           AND v_group.owner_id <> p_caller_user_id
           AND NOT EXISTS (SELECT 1 FROM commander_home_members
                            WHERE group_id = v_game.group_id AND user_id = p_caller_user_id
                              AND role = 'admin' AND status = 'approved')
        THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;
    END IF;

    v_seats_open := GREATEST(0,
        COALESCE(v_game.max_players, 9) - COALESCE(v_game.rsvp_yes, 0));
    IF v_seats_open = 0 THEN
        RETURN jsonb_build_object('success', true, 'promoted_count', 0, 'seats_full', true);
    END IF;

    FOR v_rsvp IN
        SELECT id, user_id FROM commander_home_rsvps
         WHERE game_id = p_game_id AND response = 'waitlist'
         ORDER BY responded_at LIMIT v_seats_open FOR UPDATE SKIP LOCKED
    LOOP
        UPDATE commander_home_rsvps
           SET response = 'yes', updated_at = NOW()
         WHERE id = v_rsvp.id;
        v_promoted_ids := array_append(v_promoted_ids, v_rsvp.user_id);
    END LOOP;

    IF array_length(v_promoted_ids, 1) > 0 THEN
      FOREACH v_uid IN ARRAY v_promoted_ids LOOP
        BEGIN
          PERFORM public.fn_emit_home_notification(
            p_user_id => v_uid, p_type => 'home_game_waitlist_promoted',
            p_title => 'You''re off the waitlist!',
            p_message => 'A seat opened up and you''re in for the game.',
            p_link => '/hub/home-games/' || p_game_id::text,
            p_data => jsonb_build_object('game_id', p_game_id, 'group_id', v_game.group_id),
            p_pref_column => NULL);
        EXCEPTION WHEN OTHERS THEN
          RAISE WARNING 'promote notify failed for user %: %', v_uid, SQLERRM;
        END;
      END LOOP;

      -- ★ NEW: audit log the promotion batch
      INSERT INTO public.commander_home_audit_log
        (group_id, actor_id, target_type, target_id, action, metadata)
      VALUES (
        v_game.group_id,
        COALESCE(p_caller_user_id,
                 CASE WHEN v_is_trigger_call THEN NULL
                      WHEN v_is_service_role THEN NULL
                      ELSE auth.uid() END),
        'game', p_game_id,
        CASE WHEN v_is_trigger_call THEN 'waitlist.auto_promoted'
             ELSE 'waitlist.promoted' END,
        jsonb_build_object(
          'promoted_count', array_length(v_promoted_ids, 1),
          'promoted_user_ids', v_promoted_ids));
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'promoted_count', COALESCE(array_length(v_promoted_ids, 1), 0),
        'promoted_user_ids', v_promoted_ids);
END;
$$;


ALTER FUNCTION public.promote_home_game_waitlist(p_game_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: promote_member(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.promote_member(p_club_id uuid, p_target_user_id uuid, p_new_role text, p_promoted_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text := p_new_role;
BEGIN
  -- Old vocabulary in, new vocabulary out. 'member', 'manager' and 'guest'
  -- were all ways of saying "not staff", which is what player means now.
  IF v_role IN ('member','manager','guest') THEN v_role := 'player'; END IF;
  RETURN fn_club_set_member_role(p_club_id, p_target_user_id, v_role, p_promoted_by);
END;
$$;


ALTER FUNCTION public.promote_member(p_club_id uuid, p_target_user_id uuid, p_new_role text, p_promoted_by uuid) OWNER TO postgres;

--
-- Name: protect_home_group_owner_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.protect_home_group_owner_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := current_user;
BEGIN
  IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                  'supabase_auth_admin', 'supabase_storage_admin') THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'DIRECT_OWNER_TRANSFER_FORBIDDEN'
      USING ERRCODE = '42501',
            HINT = 'use the transfer_home_group_ownership RPC; direct UPDATE of '
                || 'owner_id bypasses member-role promotion/demotion and audit logging';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.protect_home_group_owner_id() OWNER TO postgres;

--
-- Name: protect_home_group_owner_membership(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.protect_home_group_owner_membership() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner_id uuid;
  v_row      commander_home_members%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_row := OLD;
  ELSE
    v_row := NEW;
  END IF;

  SELECT owner_id INTO v_owner_id
  FROM commander_home_groups WHERE id = v_row.group_id;

  IF v_owner_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  IF v_row.user_id IS DISTINCT FROM v_owner_id THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Cannot remove the current owner from their home group. '
      'Transfer ownership first (transfer_home_group_ownership RPC).'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.role IS DISTINCT FROM OLD.role THEN
    IF NEW.role <> 'owner' THEN
      RAISE EXCEPTION 'Cannot change role of the current group owner. '
        'Transfer ownership first (transfer_home_group_ownership RPC).'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status <> 'approved' THEN
      RAISE EXCEPTION 'Cannot change status of the current group owner to %. '
        'The owner is always an approved member.', NEW.status
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.protect_home_group_owner_membership() OWNER TO postgres;

--
-- Name: prune_old_notifications(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prune_old_notifications() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count int;
BEGIN
  DELETE FROM public.notifications WHERE created_at < now() - INTERVAL '90 days';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  DELETE FROM public.push_outbox WHERE created_at < now() - INTERVAL '30 days' AND status IN ('sent','skipped','failed');
  RETURN v_count;
END; $$;


ALTER FUNCTION public.prune_old_notifications() OWNER TO postgres;

