--
-- Name: publish_user_video_reel(text, text, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_user_video_reel(p_video_url text, p_topic text, p_topic_confirmed boolean, p_caption text DEFAULT NULL::text, p_thumbnail_url text DEFAULT NULL::text, p_visibility text DEFAULT 'public'::text) RETURNS TABLE(social_post_id uuid, social_reel_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_author_id uuid := auth.uid();
  v_role text := COALESCE(auth.role()::text, '');
  v_video_url text := btrim(COALESCE(p_video_url, ''));
  v_youtube_id text;
  v_topic text := lower(btrim(COALESCE(p_topic, '')));
  v_visibility text := lower(btrim(COALESCE(p_visibility, 'public')));
  v_playback_type text;
  v_rights_status text;
  v_canonical_key text;
  v_author_is_horse boolean := false;
  v_post public.social_posts%ROWTYPE;
  v_post_id uuid;
  v_reel_id uuid;
BEGIN
  IF v_role <> 'authenticated' OR v_author_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'publish_user_video_reel requires an authenticated user';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = v_author_id) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23503',
      MESSAGE = 'a valid author profile is required';
  END IF;

  -- The post contract trigger changes a horse profile's user_upload origin
  -- to horse. Retrying after a lost response must therefore look for that
  -- trigger-produced origin too, but only for the authenticated horse owner.
  SELECT COALESCE(p.is_horse, false)
  INTO v_author_is_horse
  FROM public.profiles p
  WHERE p.id = v_author_id;

  IF p_topic_confirmed IS DISTINCT FROM true
     OR v_topic NOT IN ('poker', 'cash', 'tournament')
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'an explicit poker topic confirmation is required';
  END IF;

  IF v_visibility NOT IN ('public', 'private') THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'visibility must be public or private';
  END IF;

  IF octet_length(v_video_url) = 0 OR octet_length(v_video_url) > 4096 THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'a valid video URL is required';
  END IF;

  v_youtube_id := public.fn_extract_youtube_video_id(v_video_url);
  IF v_youtube_id IS NOT NULL AND v_video_url ~* '^https://' THEN
    v_video_url := 'https://www.youtube.com/watch?v=' || v_youtube_id;
    v_playback_type := 'youtube_embed';
    v_rights_status := 'embed_only';
    v_canonical_key := 'youtube:' || v_youtube_id;
    -- The post remains owner-visible but public RLS keeps it pending until the
    -- trusted verifier proves it public, embeddable, and subscription-free.
    PERFORM public.fn_queue_youtube_verification(
      v_youtube_id,
      'user_reel_publication'
    );
  ELSIF public.fn_is_user_video_storage_url(v_video_url, v_author_id) THEN
    -- The proof helper already rejects query/fragment variants and accepts an
    -- exact public object URL only. Normalize defensively before hashing so
    -- the persisted canonical identity always uses the bare object URL.
    v_video_url := split_part(split_part(v_video_url, '?', 1), '#', 1);
    v_playback_type := 'native';
    v_rights_status := 'user_authorized';
    v_canonical_key := 'native:' || md5(v_video_url);
  ELSE
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'video URL must be a YouTube embed or an uploaded video from your Smarter.Poker Storage namespace';
  END IF;

  -- A response can be lost after COMMIT, and multiple tabs can submit the
  -- same asset concurrently. Serialize on the caller-owned canonical identity
  -- before looking for prior work so every retry observes the first commit.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'publish-user-video-reel:' || v_author_id::text || ':' || v_canonical_key,
      0
    )
  );

  SELECT p.*
  INTO v_post
  FROM public.social_posts p
  WHERE p.author_id = v_author_id
    AND (
      p.origin_type = 'user_upload'
      OR (v_author_is_horse AND p.origin_type = 'horse')
    )
    AND p.content_type = 'video'
    AND COALESCE(p.is_deleted, false) = false
    AND p.canonical_asset_key = v_canonical_key
    AND (
      (
        v_youtube_id IS NOT NULL
        AND public.fn_extract_youtube_video_id(
          NULLIF(p.media_urls ->> 0, '')
        ) = v_youtube_id
      )
      OR (
        v_youtube_id IS NULL
        AND NULLIF(p.media_urls ->> 0, '') = v_video_url
      )
    )
  ORDER BY p.created_at ASC NULLS LAST, p.id ASC
  LIMIT 1
  FOR UPDATE;

  IF v_post.id IS NULL THEN
    INSERT INTO public.social_posts (
      author_id,
      content,
      content_type,
      media_urls,
      visibility,
      audience_mode,
      thumbnail_url,
      metadata,
      topics,
      origin_type,
      playback_type,
      topic,
      rights_status,
      youtube_video_id,
      canonical_asset_key
    ) VALUES (
      v_author_id,
      COALESCE(p_caption, ''),
      'video',
      jsonb_build_array(v_video_url),
      v_visibility,
      CASE WHEN v_visibility = 'private' THEN 'only_me' ELSE 'public' END,
      NULLIF(btrim(p_thumbnail_url), ''),
      jsonb_build_object(
        'topic_attested', true,
        'topic_attested_by', v_author_id,
        'topic_attested_at', now()
      ),
      ARRAY[v_topic]::text[],
      'user_upload',
      v_playback_type,
      v_topic,
      v_rights_status,
      v_youtube_id,
      v_canonical_key
    )
    RETURNING * INTO v_post;
  ELSIF lower(COALESCE(v_post.visibility, 'public')) IS DISTINCT FROM v_visibility
     OR COALESCE(
          v_post.audience_mode,
          CASE WHEN lower(COALESCE(v_post.visibility, 'public')) = 'private'
            THEN 'only_me' ELSE 'public' END
        ) IS DISTINCT FROM (
          CASE WHEN v_visibility = 'private' THEN 'only_me' ELSE 'public' END
        )
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'an existing publication has different visibility; refusing to change privacy on retry';
  END IF;

  v_post_id := v_post.id;

  SELECT r.id
  INTO v_reel_id
  FROM public.social_reels r
  WHERE r.source_post_id = v_post_id
    AND r.author_id = v_author_id
    AND COALESCE(r.is_deleted, false) = false
  ORDER BY r.created_at ASC NULLS LAST, r.id ASC
  LIMIT 1
  FOR UPDATE;

  IF v_reel_id IS NULL THEN
    INSERT INTO public.social_reels (
      author_id,
      video_url,
      thumbnail_url,
      caption,
      source_post_id,
      is_public,
      source_type,
      youtube_video_id,
      original_youtube_url,
      media_status,
      origin_type,
      playback_type,
      topic,
      rights_status,
      canonical_asset_key,
      native_processing_requested
    ) VALUES (
      v_post.author_id,
      NULLIF(v_post.media_urls ->> 0, ''),
      v_post.thumbnail_url,
      v_post.content,
      v_post_id,
      v_post.visibility = 'public',
      CASE
        WHEN v_post.playback_type = 'native' THEN 'native'
        WHEN v_post.youtube_video_id IS NOT NULL THEN 'youtube'
        ELSE 'user'
      END,
      v_post.youtube_video_id,
      CASE
        WHEN v_post.youtube_video_id IS NOT NULL
          THEN NULLIF(v_post.media_urls ->> 0, '')
        ELSE NULL
      END,
      'ready',
      'social_post',
      v_post.playback_type,
      v_post.topic,
      v_post.rights_status,
      v_post.canonical_asset_key,
      false
    )
    RETURNING id INTO v_reel_id;
  END IF;

  IF v_reel_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'atomic user Reel publication did not create a linked Reel';
  END IF;

  -- The deep link is publication state, not optional client decoration. Keep
  -- it in this transaction so a lost response can never leave a successfully
  -- published post without a route to its Reel. Avoid a no-op replay update so
  -- legacy updated_at triggers retain the original publication timestamp.
  UPDATE public.social_posts p
  SET link_url = '/hub/reels?id=' || v_reel_id::text
  WHERE p.id = v_post_id
    AND p.author_id = v_author_id
    AND p.link_url IS DISTINCT FROM '/hub/reels?id=' || v_reel_id::text;

  RETURN QUERY SELECT v_post_id, v_reel_id;
END
$$;


ALTER FUNCTION public.publish_user_video_reel(p_video_url text, p_topic text, p_topic_confirmed boolean, p_caption text, p_thumbnail_url text, p_visibility text) OWNER TO postgres;

--
-- Name: publish_video_library_reel(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_video_library_reel(p_video_id text, p_author_id uuid, p_caption text DEFAULT NULL::text) RETURNS TABLE(social_post_id uuid, social_reel_id uuid, was_created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_asset public.video_library_videos%ROWTYPE;
  v_post_id uuid;
  v_reel_id uuid;
  v_post_created boolean := false;
  v_reel_created boolean := false;
  v_canonical_key text;
  v_publication_key text;
  v_caption text;
  v_video_url text;
BEGIN
  IF COALESCE(auth.role()::text, '') <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'publish_video_library_reel requires the service role';
  END IF;

  IF (
    SELECT count(*)
    FROM public.video_reels_pipeline_controls c
    WHERE c.control_key IN (
      'video_library_reel_creation',
      'video_library_reel_publication'
    )
      AND c.enabled
  ) <> 2 THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'video library Reel publication is disabled';
  END IF;

  IF p_author_id IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM public.video_reels_pipeline_config config
       JOIN public.profiles p
         ON p.id = config.video_library_publisher_profile_id
       WHERE config.singleton_key = 'video_library'
         AND config.video_library_publisher_profile_id = p_author_id
     )
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '23503',
      MESSAGE = 'the configured live video-library publisher profile is required';
  END IF;

  SELECT v.*
  INTO v_asset
  FROM public.video_library_videos v
  WHERE v.youtube_video_id = btrim(p_video_id)
     OR v.id::text = btrim(p_video_id)
  ORDER BY CASE WHEN v.youtube_video_id = btrim(p_video_id) THEN 0 ELSE 1 END
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0002',
      MESSAGE = 'video library asset was not found';
  END IF;

  -- Serialize all publication attempts for the same source asset, including
  -- requests using different textual identifiers.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('video-library:' || v_asset.id::text, 0)
  );

  IF v_asset.type NOT IN ('cash', 'tournament') THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'only cash and tournament poker videos may be published as library Reels';
  END IF;

  IF v_asset.availability_status <> 'verified'
     OR v_asset.embeddable IS DISTINCT FROM true
     OR v_asset.availability_checked_at IS NULL
     OR v_asset.availability_checked_at < now() - interval '7 days'
     OR v_asset.availability_checked_at > now() + interval '5 minutes'
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'video library asset must have a fresh verified embeddable result';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.youtube_embed_failures f
    WHERE f.video_id = v_asset.youtube_video_id
      AND f.verification_status = 'confirmed'
      AND f.resolved = false
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'video library asset has an active embed failure';
  END IF;

  IF public.fn_extract_youtube_video_id(v_asset.youtube_video_id) IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'video library asset has an invalid YouTube video id';
  END IF;

  v_canonical_key := 'youtube:' || v_asset.youtube_video_id;
  v_publication_key := 'video-library:' || v_asset.id::text;
  v_caption := COALESCE(NULLIF(btrim(p_caption), ''), v_asset.title);
  v_video_url := 'https://www.youtube.com/watch?v=' || v_asset.youtube_video_id;

  -- The visibility guards require this transaction-local proof that all
  -- checks above ran inside the sole supported publication path.
  PERFORM set_config(
    'app.video_library_publish_asset_id',
    v_asset.id::text,
    true
  );

  SELECT p.id
  INTO v_post_id
  FROM public.social_posts p
  WHERE p.origin_type = 'video_library'
    AND (
      p.source_asset_id = v_asset.id
      OR p.publication_key = v_publication_key
      OR p.canonical_asset_key = v_canonical_key
    )
  ORDER BY p.created_at ASC NULLS LAST, p.id ASC
  LIMIT 1
  FOR UPDATE;

  SELECT r.id
  INTO v_reel_id
  FROM public.social_reels r
  WHERE r.origin_type = 'video_library'
    AND (
      r.source_asset_id = v_asset.id
      OR r.publication_key = v_publication_key
      OR r.canonical_asset_key = v_canonical_key
    )
  ORDER BY r.created_at ASC NULLS LAST, r.id ASC
  LIMIT 1
  FOR UPDATE;

  IF v_post_id IS NULL THEN
    INSERT INTO public.social_posts (
      author_id,
      content,
      content_type,
      media_urls,
      visibility,
      audience_mode,
      thumbnail_url,
      link_url,
      link_title,
      metadata,
      topics,
      origin_type,
      playback_type,
      topic,
      rights_status,
      source_asset_id,
      youtube_video_id,
      canonical_asset_key,
      publication_key
    ) VALUES (
      p_author_id,
      v_caption,
      'video',
      jsonb_build_array(v_video_url),
      'public',
      'public',
      v_asset.thumbnail_url,
      v_video_url,
      v_asset.title,
      jsonb_build_object(
        'video_library_id', v_asset.id,
        'youtube_video_id', v_asset.youtube_video_id,
        'source_id', v_asset.source_id,
        'source_name', v_asset.source_name,
        'video_type', v_asset.type,
        'duration', v_asset.duration,
        'availability_checked_at', v_asset.availability_checked_at
      ),
      ARRAY['poker', v_asset.type]::text[],
      'video_library',
      'youtube_embed',
      'poker',
      'embed_only',
      v_asset.id,
      v_asset.youtube_video_id,
      v_canonical_key,
      v_publication_key
    )
    RETURNING id INTO v_post_id;
    v_post_created := true;
  END IF;

  -- The explicit mirror normally creates the Reel with the post. It
  -- intentionally skips when an older managed Reel already owns the canonical
  -- key, so re-read before deciding whether a direct insert is necessary.
  IF v_reel_id IS NULL THEN
    SELECT r.id
    INTO v_reel_id
    FROM public.social_reels r
    WHERE r.source_post_id = v_post_id
       OR (
         r.origin_type = 'video_library'
         AND r.canonical_asset_key = v_canonical_key
       )
    ORDER BY
      CASE WHEN r.source_post_id = v_post_id THEN 0 ELSE 1 END,
      r.created_at ASC NULLS LAST,
      r.id ASC
    LIMIT 1
    FOR UPDATE;
  END IF;

  IF v_reel_id IS NULL THEN
    INSERT INTO public.social_reels (
      author_id,
      video_url,
      thumbnail_url,
      caption,
      source_post_id,
      is_public,
      source_type,
      youtube_video_id,
      media_status,
      original_youtube_url,
      origin_type,
      playback_type,
      topic,
      rights_status,
      source_asset_id,
      canonical_asset_key,
      publication_key,
      native_processing_requested
    ) VALUES (
      p_author_id,
      v_video_url,
      v_asset.thumbnail_url,
      v_caption,
      v_post_id,
      true,
      'video_library',
      v_asset.youtube_video_id,
      'ready',
      v_video_url,
      'video_library',
      'youtube_embed',
      'poker',
      'embed_only',
      v_asset.id,
      v_canonical_key,
      v_publication_key,
      false
    )
    RETURNING id INTO v_reel_id;
    v_reel_created := true;
  ELSE
    -- Upgrade a pre-foundation library Reel in place so its ID, likes, saves,
    -- views, comments, and shares all survive.
    UPDATE public.social_reels r
    SET author_id = p_author_id,
        video_url = v_video_url,
        thumbnail_url = COALESCE(v_asset.thumbnail_url, r.thumbnail_url),
        caption = v_caption,
        source_post_id = v_post_id,
        is_public = true,
        source_type = 'video_library',
        youtube_video_id = v_asset.youtube_video_id,
        media_status = 'ready',
        original_youtube_url = v_video_url,
        origin_type = 'video_library',
        playback_type = 'youtube_embed',
        topic = 'poker',
        rights_status = 'embed_only',
        source_asset_id = v_asset.id,
        canonical_asset_key = v_canonical_key,
        publication_key = v_publication_key,
        native_processing_requested = false
    WHERE r.id = v_reel_id;
  END IF;

  UPDATE public.social_posts p
  SET author_id = p_author_id,
      content = v_caption,
      content_type = 'video',
      media_urls = jsonb_build_array(v_video_url),
      visibility = 'public',
      audience_mode = 'public',
      thumbnail_url = COALESCE(v_asset.thumbnail_url, p.thumbnail_url),
      link_url = '/hub/reels?id=' || v_reel_id::text,
      link_title = v_asset.title,
      metadata = COALESCE(p.metadata, '{}'::jsonb)
        || jsonb_build_object(
          'video_library_id', v_asset.id,
          'youtube_video_id', v_asset.youtube_video_id,
          'social_reel_id', v_reel_id,
          'source_id', v_asset.source_id,
          'source_name', v_asset.source_name,
          'video_type', v_asset.type,
          'availability_checked_at', v_asset.availability_checked_at
        ),
      topics = ARRAY['poker', v_asset.type]::text[],
      origin_type = 'video_library',
      playback_type = 'youtube_embed',
      topic = 'poker',
      rights_status = 'embed_only',
      source_asset_id = v_asset.id,
      youtube_video_id = v_asset.youtube_video_id,
      canonical_asset_key = v_canonical_key,
      publication_key = v_publication_key
  WHERE p.id = v_post_id;

  RETURN QUERY
  SELECT v_post_id, v_reel_id, (v_post_created OR v_reel_created);
END
$$;


ALTER FUNCTION public.publish_video_library_reel(p_video_id text, p_author_id uuid, p_caption text) OWNER TO postgres;

--
-- Name: FUNCTION publish_video_library_reel(p_video_id text, p_author_id uuid, p_caption text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.publish_video_library_reel(p_video_id text, p_author_id uuid, p_caption text) IS 'Service-only atomic/idempotent publisher for fresh verified poker library embeds. Preserves and links a legacy managed Reel when one exists.';


--
-- Name: purchase_merch_with_diamonds_atomic(uuid, jsonb, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purchase_merch_with_diamonds_atomic(p_user_id uuid, p_items jsonb, p_purchase_reference text, p_request_hash text, p_shipping_address jsonb DEFAULT NULL::jsonb, p_fulfillment_mode text DEFAULT 'none'::text, p_catalog_provider text DEFAULT 'manual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_existing public.merchandise_orders%ROWTYPE;
  v_order public.merchandise_orders%ROWTYPE;
  v_reserve jsonb;
  v_wallet jsonb;
  v_lines jsonb;
  v_order_items jsonb;
  v_total_usd numeric;
  v_total_diamonds integer;
  v_status text;
  v_metadata jsonb;
  v_business_error jsonb;
  v_made_to_order_lines jsonb;
  v_line_count integer;
  v_distinct_count integer;
BEGIN
  IF p_user_id IS NULL
     OR p_purchase_reference IS NULL
     OR length(p_purchase_reference) < 16
     OR length(p_purchase_reference) > 180
     OR p_request_hash IS NULL
     OR p_request_hash !~ '^[a-f0-9]{64}$'
     OR p_items IS NULL
     OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) < 1
     OR jsonb_array_length(p_items) > 50
     OR p_fulfillment_mode NOT IN ('none', 'manual', 'automatic')
     OR p_catalog_provider IS NULL
     OR length(p_catalog_provider) > 80 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
  END IF;

  IF p_shipping_address IS NOT NULL AND jsonb_typeof(p_shipping_address) <> 'object' THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_shipping_address');
  END IF;

  -- The reference lock serializes retries even when they land on different
  -- serverless instances. It is held through the order commit.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('merch_diamond:' || p_purchase_reference, 0)
  );

  SELECT * INTO v_existing
    FROM public.merchandise_orders
   WHERE purchase_reference = p_purchase_reference
      OR (purchase_reference IS NULL AND metadata ->> 'purchase_reference' = p_purchase_reference)
   ORDER BY created_at DESC
   LIMIT 1;
  IF FOUND THEN
    IF v_existing.user_id <> p_user_id
       OR v_existing.payment_method <> 'diamonds'
       OR (
         v_existing.metadata ? 'request_hash'
         AND v_existing.metadata ->> 'request_hash' <> p_request_hash
       ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'reference_conflict');
    END IF;
    IF v_existing.purchase_reference IS NULL THEN
      UPDATE public.merchandise_orders
         SET purchase_reference = p_purchase_reference
       WHERE id = v_existing.id AND purchase_reference IS NULL;
    END IF;
    RETURN jsonb_build_object(
      'success', true,
      'duplicate', true,
      'order_id', v_existing.id,
      'items', v_existing.items,
      'total_usd', v_existing.total_usd,
      'diamonds_spent', v_existing.diamonds_spent,
      'new_balance', COALESCE((SELECT diamonds FROM public.profiles WHERE id = p_user_id), 0),
      'status', v_existing.status,
      'fulfillment_status', v_existing.metadata ->> 'fulfillment_status',
      'fulfillment_mode', v_existing.metadata ->> 'fulfillment_mode'
    );
  END IF;

  -- Duplicate item/variant lines make stock validation ambiguous (two lines
  -- can each pass against the same pre-decrement stock). Reject them instead
  -- of allowing a constraint failure or an accidental over-reservation.
  SELECT count(*), count(DISTINCT concat_ws(
      ':',
      COALESCE(line ->> 'id', ''),
      COALESCE(line ->> 'variant_id', '')
    ))
    INTO v_line_count, v_distinct_count
    FROM jsonb_array_elements(p_items) AS line;
  IF v_line_count <> v_distinct_count THEN
    RETURN jsonb_build_object('success', false, 'error', 'duplicate_lines');
  END IF;

  -- This nested block is a subtransaction. Raising a business exception after
  -- stock reservation rolls back stock, wallet, ledger, and order together;
  -- the exception handler then returns an actionable JSON response.
  BEGIN
    v_reserve := public.reserve_merch_order(p_items, false);
    IF COALESCE((v_reserve ->> 'success')::boolean, false) IS NOT TRUE THEN
      RETURN v_reserve;
    END IF;

    v_lines := v_reserve -> 'lines';
    v_total_usd := COALESCE((v_reserve ->> 'total_usd')::numeric, 0);
    v_total_diamonds := COALESCE((v_reserve ->> 'total_diamonds')::integer, 0);

    IF v_total_usd <= 0 OR v_total_usd > 2000
       OR v_total_diamonds <= 0 OR v_total_diamonds > 20000000 THEN
      v_business_error := jsonb_build_object('success', false, 'error', 'invalid_order_total');
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'invalid_order_total';
    END IF;

    IF EXISTS (
      SELECT 1
        FROM jsonb_array_elements(v_lines) AS line
       WHERE (line ->> 'price_usd')::numeric < 0.50
          OR (line ->> 'price_usd')::numeric > 500
          OR COALESCE(NULLIF(line ->> 'price_diamonds', 'null')::integer,
                      CEIL((line ->> 'price_usd')::numeric * 100)::integer) < 1
          OR COALESCE(NULLIF(line ->> 'price_diamonds', 'null')::integer,
                      CEIL((line ->> 'price_usd')::numeric * 100)::integer) > 100000
    ) THEN
      v_business_error := jsonb_build_object('success', false, 'error', 'invalid_item_price');
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'invalid_item_price';
    END IF;

    -- Made-to-order rows use catalog stock only as an availability flag. They
    -- are not warehouse units, so restore those reservations inside this same
    -- transaction while retaining real stock decrements for local goods.
    SELECT jsonb_agg(line)
      INTO v_made_to_order_lines
      FROM jsonb_array_elements(v_lines) AS line
      JOIN public.merchandise_items item ON item.id = line ->> 'id'
     WHERE COALESCE((item.metadata ->> 'made_to_order')::boolean, false)
        OR item.metadata ->> 'fulfillment_provider' IN ('printful', 'provider_pending');
    IF v_made_to_order_lines IS NOT NULL THEN
      PERFORM public.release_merch_order(v_made_to_order_lines);
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', line ->> 'id',
      'variantId', NULLIF(line ->> 'variant_id', 'null'),
      'name', line ->> 'name',
      'priceUsd', (line ->> 'price_usd')::numeric,
      'diamondPrice', CASE
        WHEN NULLIF(line ->> 'price_diamonds', 'null') IS NULL THEN NULL
        ELSE (line ->> 'price_diamonds')::integer
      END,
      'quantity', (line ->> 'qty')::integer,
      'fulfillmentProvider', COALESCE(item.metadata ->> 'fulfillment_provider', 'manual'),
      'madeToOrder', COALESCE((item.metadata ->> 'made_to_order')::boolean, false)
        OR item.metadata ->> 'fulfillment_provider' IN ('printful', 'provider_pending')
    )), '[]'::jsonb)
      INTO v_order_items
      FROM jsonb_array_elements(v_lines) AS line
      JOIN public.merchandise_items item ON item.id = line ->> 'id';

    v_wallet := public.add_diamonds_to_balance(
      p_user_id,
      -v_total_diamonds,
      'purchase',
      'Merchandise order paid with Diamonds',
      p_purchase_reference
    );
    IF COALESCE((v_wallet ->> 'success')::boolean, false) IS NOT TRUE THEN
      v_business_error := COALESCE(v_wallet, jsonb_build_object(
        'success', false, 'error', 'diamond_debit_failed'
      )) || jsonb_build_object('required_diamonds', v_total_diamonds);
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'diamond_debit_failed';
    END IF;

    v_status := CASE p_fulfillment_mode
      WHEN 'automatic' THEN 'processing'
      WHEN 'manual' THEN 'paid'
      ELSE 'completed'
    END;
    v_metadata := jsonb_build_object(
      'purchase_reference', p_purchase_reference,
      'request_hash', p_request_hash,
      'catalog_provider', p_catalog_provider
    );
    IF p_fulfillment_mode = 'automatic' THEN
      v_metadata := v_metadata || jsonb_build_object(
        'fulfillment_provider', p_catalog_provider,
        'fulfillment_mode', 'automatic',
        'fulfillment_status', 'submitting',
        'needs_review', false
      );
    ELSIF p_fulfillment_mode = 'manual' THEN
      v_metadata := v_metadata || jsonb_build_object(
        'fulfillment_provider', 'manual',
        'catalog_provider', p_catalog_provider,
        'fulfillment_mode', 'manual',
        'fulfillment_status', 'awaiting_manual_fulfillment',
        'needs_review', true,
        'reason', 'automatic_fulfillment_deferred'
      );
    END IF;

    INSERT INTO public.merchandise_orders (
      user_id, items, total_usd, diamonds_spent, payment_method, status,
      shipping_address, metadata, purchase_reference
    ) VALUES (
      p_user_id, v_order_items, v_total_usd, v_total_diamonds, 'diamonds', v_status,
      p_shipping_address, v_metadata, p_purchase_reference
    ) RETURNING * INTO v_order;

    RETURN jsonb_build_object(
      'success', true,
      'duplicate', false,
      'order_id', v_order.id,
      'items', v_order.items,
      'total_usd', v_order.total_usd,
      'diamonds_spent', v_order.diamonds_spent,
      'new_balance', v_wallet -> 'new_balance',
      'status', v_order.status,
      'fulfillment_status', v_order.metadata ->> 'fulfillment_status',
      'fulfillment_mode', v_order.metadata ->> 'fulfillment_mode'
    );
  EXCEPTION
    WHEN SQLSTATE 'P0001' THEN
      RETURN COALESCE(v_business_error, jsonb_build_object(
        'success', false, 'error', SQLERRM
      ));
    WHEN unique_violation THEN
      -- A pre-existing ledger reference without its matching order is not a
      -- safe replay. The subtransaction has already rolled back this attempt.
      SELECT * INTO v_existing
        FROM public.merchandise_orders
       WHERE purchase_reference = p_purchase_reference;
      IF FOUND AND v_existing.user_id = p_user_id
         AND v_existing.payment_method = 'diamonds'
         AND v_existing.metadata ->> 'request_hash' = p_request_hash THEN
        RETURN jsonb_build_object(
          'success', true,
          'duplicate', true,
          'order_id', v_existing.id,
          'items', v_existing.items,
          'total_usd', v_existing.total_usd,
          'diamonds_spent', v_existing.diamonds_spent,
          'new_balance', COALESCE((SELECT diamonds FROM public.profiles WHERE id = p_user_id), 0),
          'status', v_existing.status,
          'fulfillment_status', v_existing.metadata ->> 'fulfillment_status',
          'fulfillment_mode', v_existing.metadata ->> 'fulfillment_mode'
        );
      END IF;
      RETURN jsonb_build_object('success', false, 'error', 'reference_conflict');
  END;
END;
$_$;


ALTER FUNCTION public.purchase_merch_with_diamonds_atomic(p_user_id uuid, p_items jsonb, p_purchase_reference text, p_request_hash text, p_shipping_address jsonb, p_fulfillment_mode text, p_catalog_provider text) OWNER TO postgres;

--
-- Name: purchase_vip_with_diamonds_atomic(uuid, integer, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purchase_vip_with_diamonds_atomic(p_user_id uuid, p_cost integer, p_days integer, p_plan text, p_reference_id text, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_profile public.profiles%ROWTYPE;
    v_wallet jsonb;
    v_now timestamptz := now();
    v_base timestamptz;
    v_expires timestamptz;
    v_tier text;
    v_existing_rank integer;
    v_requested_rank integer;
    v_lifetime boolean := (p_plan = 'lifetime');
BEGIN
    /* THE THREE TERMS. Was ('daily','monthly','annual') until 2026-09-05.
       `p_days` is required for the two timed plans and IGNORED for lifetime,
       which has no end to compute - the old guard demanded p_days > 0 from
       every caller, so a lifetime purchase had no way to say "forever". */
    IF p_cost IS NULL OR p_cost <= 0
       OR p_reference_id IS NULL OR p_reference_id = ''
       OR p_plan NOT IN ('monthly', 'yearly', 'lifetime')
       OR (NOT v_lifetime AND (p_days IS NULL OR p_days <= 0)) THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;

    -- Serialize every debit + extension for this profile. The nested wallet
    -- function takes the same row lock and writes the ledger in this transaction.
    PERFORM 1
      FROM public.profiles
     WHERE id = p_user_id
     FOR UPDATE;

    SELECT * INTO v_profile FROM public.profiles WHERE id = p_user_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'profile_not_found');
    END IF;

    v_wallet := public.add_diamonds_to_balance(
        p_user_id,
        -p_cost,
        'vip_membership',
        p_description,
        p_reference_id
    );

    IF COALESCE((v_wallet ->> 'success')::boolean, false) IS NOT TRUE THEN
        IF COALESCE((v_wallet ->> 'duplicate')::boolean, false) THEN
            SELECT * INTO v_profile FROM public.profiles WHERE id = p_user_id;
            RETURN jsonb_build_object(
                'success', true,
                'duplicate', true,
                'new_balance', COALESCE(v_profile.diamonds, 0),
                'is_vip', COALESCE(v_profile.is_vip, false),
                'tier', v_profile.vip_tier,
                'expires_at', v_profile.vip_expires_at
            );
        END IF;
        RETURN v_wallet;
    END IF;

    IF v_lifetime THEN
        /* NO EXPIRY AT ALL, not a distant one. expire_lapsed_vip is guarded
           twice - `vip_expires_at IS NOT NULL` and `vip_tier <> 'lifetime'` -
           and a NULL satisfies the first guard on its own. 692 existing
           lifetime rows carry a 2099-12-31 sentinel and 329 carry NULL;
           `resolveVipStatus` reads both correctly, and NULL is the one that
           cannot be misread as a date that has passed. */
        v_tier := 'lifetime';
        v_expires := NULL;
    ELSE
        v_base := CASE
            WHEN v_profile.vip_expires_at IS NOT NULL AND v_profile.vip_expires_at > v_now
                THEN v_profile.vip_expires_at
            ELSE v_now
        END;
        v_expires := v_base + make_interval(days => p_days);

        /* A shorter plan bought on top of a longer one EXTENDS it and keeps the
           better term. 'daily' is gone from the ranking and 'annual' is now
           'yearly'; lifetime sits above both and is unreachable here because
           v2 refuses a purchase by anyone who already holds it. */
        v_existing_rank := CASE v_profile.vip_tier
            WHEN 'lifetime' THEN 3 WHEN 'yearly' THEN 2 WHEN 'monthly' THEN 1 ELSE 0 END;
        v_requested_rank := CASE p_plan
            WHEN 'lifetime' THEN 3 WHEN 'yearly' THEN 2 WHEN 'monthly' THEN 1 ELSE 0 END;
        v_tier := CASE
            WHEN v_profile.vip_expires_at > v_now AND v_existing_rank > v_requested_rank
                THEN v_profile.vip_tier
            ELSE p_plan
        END;
    END IF;

    UPDATE public.profiles
       SET is_vip = true,
           vip_tier = v_tier,
           vip_expires_at = v_expires,
           updated_at = v_now
     WHERE id = p_user_id;

    RETURN jsonb_build_object(
        'success', true,
        'duplicate', false,
        'new_balance', v_wallet -> 'new_balance',
        'is_vip', true,
        'tier', v_tier,
        'expires_at', v_expires
    );
END;
$$;


ALTER FUNCTION public.purchase_vip_with_diamonds_atomic(p_user_id uuid, p_cost integer, p_days integer, p_plan text, p_reference_id text, p_description text) OWNER TO postgres;

--
-- Name: FUNCTION purchase_vip_with_diamonds_atomic(p_user_id uuid, p_cost integer, p_days integer, p_plan text, p_reference_id text, p_description text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.purchase_vip_with_diamonds_atomic(p_user_id uuid, p_cost integer, p_days integer, p_plan text, p_reference_id text, p_description text) IS 'Buys VIP with diamonds. Plans are monthly | yearly | lifetime (Dan 2026-09-05); daily and annual were retired the same day, unsold. A lifetime purchase writes vip_tier = lifetime with a NULL expiry and ignores p_days.';


--
-- Name: purchase_vip_with_diamonds_atomic_v2(uuid, integer, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purchase_vip_with_diamonds_atomic_v2(p_user_id uuid, p_cost integer, p_days integer, p_plan text, p_reference_id text, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_profile public.profiles%ROWTYPE;
BEGIN
  SELECT * INTO v_profile
    FROM public.profiles
   WHERE id = p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'profile_not_found');
  END IF;
  IF v_profile.vip_tier = 'lifetime' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'already_lifetime',
      'new_balance', COALESCE(v_profile.diamonds, 0),
      'is_vip', true,
      'tier', 'lifetime',
      'expires_at', v_profile.vip_expires_at
    );
  END IF;
  RETURN public.purchase_vip_with_diamonds_atomic(
    p_user_id, p_cost, p_days, p_plan, p_reference_id, p_description
  );
END;
$$;


ALTER FUNCTION public.purchase_vip_with_diamonds_atomic_v2(p_user_id uuid, p_cost integer, p_days integer, p_plan text, p_reference_id text, p_description text) OWNER TO postgres;

--
-- Name: purchase_vip_with_diamonds_atomic_v3(uuid, integer, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purchase_vip_with_diamonds_atomic_v3(p_user_id uuid, p_cost integer, p_days integer, p_plan text, p_reference_id text, p_request_hash text, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_request public.vip_diamond_purchase_requests%ROWTYPE;
  v_claim public.vip_subscription_checkout_claims%ROWTYPE;
  v_result jsonb;
BEGIN
  IF p_reference_id IS NULL OR btrim(p_reference_id) = ''
     OR p_request_hash IS NULL OR p_request_hash !~ '^[a-f0-9]{64}$' THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_reference_id, 0));

  -- Durable replay intentionally precedes every current-state eligibility
  -- check. A completed request remains a success even if the member later
  -- opens a Card checkout or changes subscription state.
  SELECT * INTO v_request
    FROM public.vip_diamond_purchase_requests
   WHERE reference_id = p_reference_id;
  IF FOUND THEN
    IF v_request.user_id <> p_user_id OR v_request.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('success', false, 'error', 'reference_conflict');
    END IF;
    RETURN v_request.response || jsonb_build_object('duplicate', true);
  END IF;

  -- This is the same lock used by claim_vip_subscription_checkout. It closes
  -- the read-then-write window between the two payment methods without
  -- widening or changing the settlement transaction below.
  PERFORM 1
    FROM public.profiles
   WHERE id = p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'profile_not_found');
  END IF;

  SELECT * INTO v_claim
    FROM public.vip_subscription_checkout_claims
   WHERE user_id = p_user_id
   FOR UPDATE;
  IF FOUND AND (
    v_claim.state = 'admitting'
    OR v_claim.expires_at > now()
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'card_checkout_exists');
  END IF;
  IF FOUND THEN
    DELETE FROM public.vip_subscription_checkout_claims
     WHERE user_id = p_user_id
       AND state <> 'admitting';
  END IF;

  -- Make the database the final authority immediately before debit. The API
  -- intentionally enters this RPC before current-state eligibility so an
  -- already completed durable request can replay first.
  IF EXISTS (
    SELECT 1
      FROM public.vip_subscriptions subscription
     WHERE subscription.user_id = p_user_id
       AND subscription.status IN (
         'active', 'trialing', 'past_due', 'unpaid', 'incomplete', 'paused'
       )
       AND subscription.stripe_subscription_id IS NOT NULL
       AND left(subscription.stripe_subscription_id, 8) <> 'diamond_'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'active_card_subscription');
  END IF;

  v_result := public.purchase_vip_with_diamonds_atomic_v2(
    p_user_id, p_cost, p_days, p_plan, p_reference_id, p_description
  );
  IF COALESCE((v_result ->> 'success')::boolean, false) IS TRUE THEN
    INSERT INTO public.vip_diamond_purchase_requests(
      reference_id, user_id, request_hash, response
    ) VALUES (
      p_reference_id, p_user_id, p_request_hash, v_result
    );
  END IF;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION public.purchase_vip_with_diamonds_atomic_v3(p_user_id uuid, p_cost integer, p_days integer, p_plan text, p_reference_id text, p_request_hash text, p_description text) OWNER TO postgres;

