-- Name: FUNCTION purchase_vip_with_diamonds_atomic_v3(p_user_id uuid, p_cost integer, p_days integer, p_plan text, p_reference_id text, p_request_hash text, p_description text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.purchase_vip_with_diamonds_atomic_v3(p_user_id uuid, p_cost integer, p_days integer, p_plan text, p_reference_id text, p_request_hash text, p_description text) IS 'marketplace_phase7_vip_acquisition_mutex:v1';


--
-- Name: purge_idempotency_keys(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purge_idempotency_keys() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted INT;
BEGIN
  DELETE FROM public.idempotency_keys
  WHERE created_at < NOW() - INTERVAL '7 days';
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION public.purge_idempotency_keys() OWNER TO postgres;

--
-- Name: FUNCTION purge_idempotency_keys(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.purge_idempotency_keys() IS 'Phase 4.1.3: nightly purge of idempotency keys older than 7 days. Called by /api/cron/purge-idempotency-keys.';


--
-- Name: purge_personal_assistant_data(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purge_personal_assistant_data(p_user_id uuid, p_scope text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_counts jsonb := '{}'::jsonb;
  v_count integer := 0;
  v_leak_ids uuid[] := '{}'::uuid[];
  v_session_ids uuid[] := '{}'::uuid[];
  v_receipt_id uuid;
  v_fingerprint text;
BEGIN
  IF p_user_id IS NULL OR p_scope NOT IN ('coaching', 'analysis', 'sandbox', 'all') THEN
    RAISE EXCEPTION 'invalid personal assistant purge request';
  END IF;

  IF p_scope IN ('coaching', 'all') THEN
    DELETE FROM public.pa_coach_feedback WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('coach_feedback', v_count);
    DELETE FROM public.pa_coaching_goals WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('coaching_goals', v_count);
    DELETE FROM public.pa_coaching_preferences WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('preferences', v_count);
  END IF;

  IF p_scope IN ('analysis', 'all') THEN
    SELECT coalesce(array_agg(id), '{}'::uuid[]) INTO v_leak_ids
    FROM public.user_leaks WHERE user_id = p_user_id;

    DELETE FROM public.leak_hand_examples WHERE leak_id = ANY(v_leak_ids);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('hand_examples', v_count);
    DELETE FROM public.leak_drill_answers WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('drill_answers', v_count);
    DELETE FROM public.leak_drill_attempts WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('drill_attempts', v_count);
    DELETE FROM public.leak_drill_sessions WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('drill_sessions', v_count);
    DELETE FROM public.leak_review_state WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('review_states', v_count);
    DELETE FROM public.hand_audit_decisions WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('audit_decisions', v_count);
    DELETE FROM public.pa_leak_audit_jobs WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('audit_jobs', v_count);
    DELETE FROM public.user_leaks WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('leaks', v_count);
  END IF;

  IF p_scope IN ('sandbox', 'all') THEN
    SELECT coalesce(array_agg(id), '{}'::uuid[]) INTO v_session_ids
    FROM public.sandbox_sessions WHERE user_id = p_user_id;
    DELETE FROM public.sandbox_coach_results WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_coach_results', v_count);
    DELETE FROM public.sandbox_equity_history WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_equity_history', v_count);
    DELETE FROM public.sandbox_results WHERE session_id = ANY(v_session_ids);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_results', v_count);
    DELETE FROM public.sandbox_sessions WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_sessions', v_count);
    DELETE FROM public.sandbox_saved_hands WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('saved_hands', v_count);
    DELETE FROM public.sandbox_analytics WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_analytics', v_count);
    DELETE FROM public.sandbox_quiz_results WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_quiz_results', v_count);
    DELETE FROM public.sandbox_bookmarks WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_bookmarks', v_count);
    DELETE FROM public.sandbox_templates WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_templates', v_count);
    DELETE FROM public.sandbox_shared_scenarios WHERE creator_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_shared_scenarios', v_count);
    DELETE FROM public.solution_bookmarks WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('solution_bookmarks', v_count);
  END IF;

  v_fingerprint := md5(p_user_id::text || ':' || p_scope || ':' || v_counts::text || ':' || clock_timestamp()::text || ':' || gen_random_uuid()::text);
  INSERT INTO public.pa_data_lifecycle_receipts (user_id, action, scope, item_counts, receipt_fingerprint)
  VALUES (p_user_id, 'delete', p_scope, v_counts, v_fingerprint)
  RETURNING id INTO v_receipt_id;

  RETURN jsonb_build_object('receipt_id', v_receipt_id, 'fingerprint', v_fingerprint, 'counts', v_counts);
END;
$$;


ALTER FUNCTION public.purge_personal_assistant_data(p_user_id uuid, p_scope text) OWNER TO postgres;

--
-- Name: reap_dead_engine_leases(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reap_dead_engine_leases(p_stale_seconds integer DEFAULT 3600) RETURNS TABLE(table_leases_deleted integer, tournament_leases_deleted integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cutoff timestamptz;
  v_tables integer;
  v_tourneys integer;
begin
  if coalesce(p_stale_seconds, 0) < 600 then
    raise exception 'reap_dead_engine_leases refuses a cutoff under 600s (asked for %)', p_stale_seconds;
  end if;

  v_cutoff := now() - make_interval(secs => p_stale_seconds);

  delete from public.engine_table_leases where heartbeat_at < v_cutoff;
  get diagnostics v_tables = row_count;

  delete from public.engine_tournament_leases where heartbeat_at < v_cutoff;
  get diagnostics v_tourneys = row_count;

  return query select v_tables, v_tourneys;
end;
$$;


ALTER FUNCTION public.reap_dead_engine_leases(p_stale_seconds integer) OWNER TO postgres;

--
-- Name: FUNCTION reap_dead_engine_leases(p_stale_seconds integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reap_dead_engine_leases(p_stale_seconds integer) IS 'Delete lease rows nobody has renewed for p_stale_seconds (default 1h, floor 10m). release_*_leases only runs on a graceful shutdown, so every hard-killed container leaks a full set of rows; the boot-time 7-day prune could not keep up with the deploy rate. Cannot race a live engine: a lease unrenewed for an hour has already lost every claim to the 30-second staleness rule.';


--
-- Name: recalculate_leaderboard_ranks(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recalculate_leaderboard_ranks(p_promotion_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE public.promotion_leaderboards pl
     SET rank = r.new_rank
    FROM (SELECT id, dense_rank() OVER (ORDER BY score DESC, updated_at ASC) AS new_rank
            FROM public.promotion_leaderboards
           WHERE promotion_id = p_promotion_id) r
   WHERE pl.id = r.id AND pl.rank IS DISTINCT FROM r.new_rank;
$$;


ALTER FUNCTION public.recalculate_leaderboard_ranks(p_promotion_id uuid) OWNER TO postgres;

--
-- Name: recalculate_venue_trust_score(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recalculate_venue_trust_score(p_venue_id text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_avg   numeric;
  v_count integer;
  v_vid   integer;
BEGIN
  -- Reject if the caller passed a non-integer string (defensive)
  BEGIN
    v_vid := p_venue_id::integer;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION 'INVALID_VENUE_ID'
          USING HINT = 'p_venue_id must parse as integer';
  END;

  SELECT AVG(rating)::numeric(3,2), COUNT(*)
    INTO v_avg, v_count
    FROM public.venue_reviews
   WHERE venue_id = v_vid;

  -- Only update if there are reviews (preserve old trust_score for zero-review venues)
  IF v_count > 0 THEN
    UPDATE public.poker_venues
       SET trust_score = v_avg
     WHERE id = v_vid;
  END IF;
END;
$$;


ALTER FUNCTION public.recalculate_venue_trust_score(p_venue_id text) OWNER TO postgres;

--
-- Name: recalculate_waitlist_positions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recalculate_waitlist_positions() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF (TG_OP = 'UPDATE' AND NEW.status IN ('seated', 'removed', 'passed') AND OLD.status = 'waiting') OR
     (TG_OP = 'DELETE' AND OLD.status = 'waiting') THEN
    WITH ranked AS (
      SELECT id, ROW_NUMBER() OVER (ORDER BY created_at) as new_position
      FROM commander_waitlist
      WHERE venue_id = COALESCE(NEW.venue_id, OLD.venue_id)
        AND game_type = COALESCE(NEW.game_type, OLD.game_type)
        AND stakes = COALESCE(NEW.stakes, OLD.stakes)
        AND status = 'waiting'
    )
    UPDATE commander_waitlist w
    SET position = r.new_position
    FROM ranked r
    WHERE w.id = r.id;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.recalculate_waitlist_positions() OWNER TO postgres;

--
-- Name: recompute_club_levels(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recompute_club_levels(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row public.clubs%ROWTYPE;
BEGIN
  IF current_setting('request.jwt.claims', true)::jsonb->>'role' = 'service_role'
     OR current_role IN ('postgres', 'service_role') THEN
    NULL;
  ELSIF NOT EXISTS (
      SELECT 1 FROM public.club_members
       WHERE club_id = p_club_id AND user_id = auth.uid()
         AND role IN ('owner','co_owner','admin','manager')
    ) AND NOT EXISTS (
      SELECT 1 FROM public.clubs WHERE id = p_club_id AND owner_id = auth.uid()
    ) THEN
    RETURN jsonb_build_object('success', false,
      'error', 'Unauthorized: Only club owners and admins can trigger level recalculation.');
  END IF;

  PERFORM public.fn_apply_club_ladder(p_club_id);
  SELECT * INTO v_row FROM public.clubs WHERE id = p_club_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Club not found.');
  END IF;
  RETURN jsonb_build_object('success', true, 'club_id', p_club_id,
    'level', v_row.level, 'member_count', v_row.member_count,
    'player_threshold_current', v_row.player_threshold_current,
    'player_threshold_next', v_row.player_threshold_next);
END;
$$;


ALTER FUNCTION public.recompute_club_levels(p_club_id uuid) OWNER TO postgres;

--
-- Name: recompute_club_levels_silent(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recompute_club_levels_silent(p_club_id uuid DEFAULT NULL::uuid, p_force boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  FOR v_id IN SELECT id FROM public.clubs WHERE p_club_id IS NULL OR id = p_club_id LOOP
    PERFORM public.fn_apply_club_ladder(v_id);
  END LOOP;
END;
$$;


ALTER FUNCTION public.recompute_club_levels_silent(p_club_id uuid, p_force boolean) OWNER TO postgres;

