-- Name: record_arena_audit_log(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_arena_audit_log(p_club_id uuid DEFAULT NULL::uuid, p_user_id uuid DEFAULT NULL::uuid, p_action text DEFAULT ''::text, p_details jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  INSERT INTO system_logs (log_level, source, message, details, created_at)
  VALUES ('audit', 'arena', p_action, jsonb_build_object('club_id', p_club_id, 'user_id', p_user_id, 'details', p_details), now())
  ON CONFLICT DO NOTHING;
EXCEPTION WHEN undefined_table THEN NULL;
END; $$;


