CREATE FUNCTION public.record_health_metric(p_venue_id integer, p_metric_type text, p_metric_value numeric, p_metric_unit text DEFAULT 'count'::text, p_endpoint text DEFAULT NULL::text, p_details jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into commander_system_health (venue_id, metric_type, metric_value, metric_unit, endpoint, details, recorded_at)
  values (p_venue_id, p_metric_type, p_metric_value, p_metric_unit, p_endpoint, p_details, now());
$$;


ALTER FUNCTION public.record_health_metric(p_venue_id integer, p_metric_type text, p_metric_value numeric, p_metric_unit text, p_endpoint text, p_details jsonb) OWNER TO postgres;

--
-- Name: record_home_game_photo(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_home_game_photo(p_game_id uuid, p_caller_user_id uuid, p_photo_url text, p_caption text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_game RECORD; v_group RECORD; v_new_id uuid;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;
    IF NOT public.fn_try_consume_home_rate_limit(
         p_caller_user_id, 'home_game_photo_upload', 40, 60) THEN
      RAISE EXCEPTION 'RATE_LIMIT_EXCEEDED' USING HINT = 'photo uploads: 40 per 60 min.';
    END IF;
    IF p_photo_url IS NULL OR length(trim(p_photo_url)) = 0 THEN
        RAISE EXCEPTION 'MISSING_URL';
    END IF;
    IF p_caption IS NOT NULL AND length(p_caption) > 500 THEN
        RAISE EXCEPTION 'CAPTION_TOO_LONG' USING HINT = 'max 500 chars';
    END IF;

    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;

    IF v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members
                        WHERE group_id = v_game.group_id AND user_id = p_caller_user_id
                          AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_A_MEMBER'; END IF;

    INSERT INTO commander_home_game_photos (game_id, uploader_id, photo_url, caption)
    VALUES (p_game_id, p_caller_user_id, p_photo_url, p_caption)
    RETURNING id INTO v_new_id;

    RETURN jsonb_build_object('success', true, 'photo_id', v_new_id);
END;
$$;


ALTER FUNCTION public.record_home_game_photo(p_game_id uuid, p_caller_user_id uuid, p_photo_url text, p_caption text) OWNER TO postgres;

