-- Name: record_promo_wagering(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_promo_wagering(p_club_id uuid, p_player_user_id uuid, p_amount_wagered numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_player_user_id is null or p_amount_wagered is null or p_amount_wagered <= 0 then
    return;
  end if;
  insert into promo_wagering_ledger (club_id, player_user_id, amount_wagered)
  values (p_club_id, p_player_user_id, p_amount_wagered);
end $$;


