    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$ BEGIN INSERT INTO table_cashout_history (table_id, user_id, cashout_amount) VALUES (p_table_id, p_user_id, p_cashout_amount); END; $$;


