--
-- Name: record_tournament_elimination(uuid, uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_tournament_elimination(p_tournament_id uuid, p_entry_id uuid, p_finish_position integer, p_payout_amount integer DEFAULT 0, p_eliminated_by uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  UPDATE commander_tournament_entries SET
    status = 'eliminated', finish_position = p_finish_position, payout_amount = p_payout_amount,
    eliminated_at = now(), eliminated_by = p_eliminated_by, current_chips = 0
  WHERE id = p_entry_id AND tournament_id = p_tournament_id;
  UPDATE commander_tournaments SET
    players_remaining = (SELECT count(*) FROM commander_tournament_entries WHERE tournament_id = p_tournament_id AND status = 'active'),
    updated_at = now()
  WHERE id = p_tournament_id;
END;
$$;


