--
-- Name: record_trivia_pvp_stats_v2(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_trivia_pvp_stats_v2(p_match_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_match public.trivia_pvp_matches%ROWTYPE;
    v_decision public.trivia_pvp_settlement_decisions%ROWTYPE;
    v_side record;
    v_outcome text;
    v_stake integer;
    v_net_win integer;
BEGIN
    IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'service_role required';
    END IF;
    SELECT * INTO v_match
      FROM public.trivia_pvp_matches
     WHERE id = p_match_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'match_not_found');
    END IF;
    IF v_match.status NOT IN ('complete', 'completed') THEN
        RETURN jsonb_build_object('success', false, 'error', 'match_not_complete');
    END IF;
    IF v_match.stats_recorded_at IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'deduped', true);
    END IF;
    SELECT * INTO v_decision
      FROM public.trivia_pvp_settlement_decisions
     WHERE match_id = p_match_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'settlement_decision_missing');
    END IF;

    v_stake := v_match.stake_amount;
    v_net_win := GREATEST(
        (v_stake * 2 - floor(v_stake * 2 * 0.10)::integer) - v_stake,
        0
    );
    UPDATE public.trivia_pvp_matches
       SET stats_recorded_at = clock_timestamp()
     WHERE id = p_match_id;

    IF v_decision.decision_kind IN ('win', 'tie') THEN
        FOR v_side IN
            SELECT (side.value ->> 'user_id')::uuid AS user_id
              FROM jsonb_array_elements(v_decision.side_state) AS side(value)
             WHERE COALESCE((side.value ->> 'charged')::boolean, false)
        LOOP
            v_outcome := CASE
                WHEN v_decision.decision_kind = 'tie' THEN 'tie'
                WHEN v_decision.winner_id = v_side.user_id THEN 'win'
                ELSE 'loss'
            END;
            INSERT INTO public.trivia_pvp_stats AS stats (
                user_id, wins, losses, ties, win_streak, best_streak,
                total_diamonds_won, total_diamonds_lost, updated_at
            ) VALUES (
                v_side.user_id,
                CASE WHEN v_outcome = 'win' THEN 1 ELSE 0 END,
                CASE WHEN v_outcome = 'loss' THEN 1 ELSE 0 END,
                CASE WHEN v_outcome = 'tie' THEN 1 ELSE 0 END,
                CASE WHEN v_outcome = 'win' THEN 1 ELSE 0 END,
                CASE WHEN v_outcome = 'win' THEN 1 ELSE 0 END,
                CASE WHEN v_outcome = 'win' THEN v_net_win ELSE 0 END,
                CASE WHEN v_outcome = 'loss' THEN v_stake ELSE 0 END,
                clock_timestamp()
            ) ON CONFLICT (user_id) DO UPDATE SET
                wins = stats.wins + CASE WHEN v_outcome = 'win' THEN 1 ELSE 0 END,
                losses = stats.losses + CASE WHEN v_outcome = 'loss' THEN 1 ELSE 0 END,
                ties = stats.ties + CASE WHEN v_outcome = 'tie' THEN 1 ELSE 0 END,
                win_streak = CASE
                    WHEN v_outcome = 'win' THEN stats.win_streak + 1
                    WHEN v_outcome = 'loss' THEN 0
                    ELSE stats.win_streak
                END,
                best_streak = GREATEST(
                    stats.best_streak,
                    CASE WHEN v_outcome = 'win' THEN stats.win_streak + 1 ELSE stats.win_streak END
                ),
                total_diamonds_won = stats.total_diamonds_won
                    + CASE WHEN v_outcome = 'win' THEN v_net_win ELSE 0 END,
                total_diamonds_lost = stats.total_diamonds_lost
                    + CASE WHEN v_outcome = 'loss' THEN v_stake ELSE 0 END,
                updated_at = clock_timestamp();
        END LOOP;
    END IF;
    RETURN jsonb_build_object('success', true, 'deduped', false);
END;
$$;


ALTER FUNCTION public.record_trivia_pvp_stats_v2(p_match_id uuid) OWNER TO postgres;

--
-- Name: record_trivia_session_answer(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_trivia_session_answer(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_display_index integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_session public.trivia_sessions%ROWTYPE;
    v_key text := p_question_id::text;
    v_stored jsonb;
BEGIN
    IF p_session_id IS NULL OR p_user_id IS NULL OR p_question_id IS NULL THEN
        RETURN jsonb_build_object('success',false,'error','missing_arguments');
    END IF;
    UPDATE public.trivia_sessions
       SET answers = answers || jsonb_build_object(
           v_key, jsonb_build_object(
               'd',GREATEST(-1,COALESCE(p_display_index,-1)),
               'n',(SELECT count(*) FROM jsonb_object_keys(answers)),
               'at',now()
           ))
     WHERE id=p_session_id AND user_id=p_user_id AND status='open'
       AND (expires_at IS NULL OR now() <= expires_at)
       AND question_ids @> ARRAY[p_question_id] AND NOT (answers ? v_key)
    RETURNING * INTO v_session;
    IF FOUND THEN
        RETURN jsonb_build_object('success',true,'stored',v_session.answers->v_key,'fresh',true);
    END IF;
    SELECT * INTO v_session FROM public.trivia_sessions
     WHERE id=p_session_id AND user_id=p_user_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','session_not_found'); END IF;
    IF v_session.status<>'open' THEN RETURN jsonb_build_object('success',false,'error','session_closed'); END IF;
    IF v_session.expires_at IS NOT NULL AND now()>v_session.expires_at THEN
        RETURN jsonb_build_object('success',false,'error','session_expired','expires_at',v_session.expires_at);
    END IF;
    IF NOT (v_session.question_ids @> ARRAY[p_question_id]) THEN
        RETURN jsonb_build_object('success',false,'error','question_not_in_session');
    END IF;
    v_stored:=v_session.answers->v_key;
    IF v_stored IS NOT NULL THEN
        RETURN jsonb_build_object('success',true,'stored',v_stored,'fresh',false);
    END IF;
    RETURN jsonb_build_object('success',false,'error','not_recorded');
END;
$$;


ALTER FUNCTION public.record_trivia_session_answer(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_display_index integer) OWNER TO postgres;

--
-- Name: record_trivia_tournament_question_results_v3(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_trivia_tournament_question_results_v3(p_user_id uuid, p_round_id uuid, p_results jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_row jsonb;
    v_question_id uuid;
    v_category text;
    v_display integer;
    v_original integer;
    v_correct boolean;
    v_skipped boolean;
    v_event_id uuid;
    v_inserted integer := 0;
BEGIN
    IF p_user_id IS NULL OR p_round_id IS NULL OR jsonb_typeof(p_results) <> 'array' THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    IF jsonb_array_length(p_results) > 500 THEN
        RETURN jsonb_build_object('success', false, 'error', 'too_many_results');
    END IF;

    FOR v_row IN SELECT value FROM jsonb_array_elements(p_results)
    LOOP
        BEGIN
            v_question_id := (v_row->>'question_id')::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            CONTINUE;
        END;
        SELECT category INTO v_category
          FROM public.trivia_questions
         WHERE id = v_question_id;
        IF NOT FOUND THEN CONTINUE; END IF;

        v_display := CASE WHEN (v_row->>'display_index') ~ '^-?[0-9]+$'
            THEN (v_row->>'display_index')::integer ELSE NULL END;
        v_original := CASE WHEN (v_row->>'original_index') ~ '^[0-9]+$'
            THEN (v_row->>'original_index')::integer ELSE NULL END;
        v_correct := CASE WHEN jsonb_typeof(v_row->'was_correct') = 'boolean'
            THEN (v_row->>'was_correct')::boolean ELSE NULL END;
        v_skipped := COALESCE((v_row->>'was_skipped')::boolean, false);

        v_event_id := NULL;
        INSERT INTO public.trivia_question_result_events
            (user_id, question_id, mode, source_type, source_id,
             display_index, original_index, was_correct, was_skipped)
        VALUES
            (p_user_id, v_question_id, 'tournaments', 'tournament_round', p_round_id,
             v_display, v_original, v_correct, v_skipped)
        ON CONFLICT (source_type, source_id, user_id, question_id) DO NOTHING
        RETURNING id INTO v_event_id;
        IF v_event_id IS NULL THEN CONTINUE; END IF;
        v_inserted := v_inserted + 1;

        INSERT INTO public.trivia_user_question_history AS h
            (user_id, question_id, seen_at, was_correct, mode)
        VALUES (p_user_id, v_question_id, now(), v_correct, 'tournaments')
        ON CONFLICT (user_id, question_id) DO UPDATE SET
            seen_at = EXCLUDED.seen_at,
            was_correct = EXCLUDED.was_correct,
            mode = EXCLUDED.mode;

        IF v_skipped THEN
            UPDATE public.trivia_questions
               SET skipped_count = COALESCE(skipped_count, 0) + 1
             WHERE id = v_question_id;
        END IF;
        IF v_correct IS TRUE THEN
            UPDATE public.trivia_questions
               SET times_correct = COALESCE(times_correct, 0) + 1
             WHERE id = v_question_id;
        END IF;
        IF v_original IS NOT NULL THEN
            INSERT INTO public.trivia_category_mastery AS m
                (user_id, category, total_answered, correct_count, mastery_level, updated_at)
            VALUES
                (p_user_id, COALESCE(v_category, 'general'), 1,
                 CASE WHEN v_correct IS TRUE THEN 1 ELSE 0 END,
                 CASE WHEN v_correct IS TRUE THEN 10 ELSE 1 END, now())
            ON CONFLICT (user_id, category) DO UPDATE SET
                total_answered = m.total_answered + 1,
                correct_count = m.correct_count + EXCLUDED.correct_count,
                mastery_level = LEAST(10, GREATEST(1,
                    floor(((m.correct_count + EXCLUDED.correct_count)::numeric
                        / NULLIF(m.total_answered + 1, 0)) * 10)::integer + 1)),
                updated_at = now();
        END IF;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'inserted', v_inserted,
        'deduped', v_inserted = 0);
END;
$_$;


ALTER FUNCTION public.record_trivia_tournament_question_results_v3(p_user_id uuid, p_round_id uuid, p_results jsonb) OWNER TO postgres;

--
-- Name: record_verified_leak_drill_answer(uuid, text, uuid, text, text, text, boolean, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_verified_leak_drill_answer(p_user_id uuid, p_leak_id text, p_batch_id uuid, p_question_id text, p_selected_answer text, p_correct_answer text, p_correct boolean, p_timed_out boolean, p_explanation text, p_solver_source text, p_classification text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_answer public.leak_drill_answers%ROWTYPE;
  v_session public.leak_drill_sessions%ROWTYPE;
  v_legacy_attempts integer := 0;
  v_attempt integer;
BEGIN
  IF p_user_id IS NULL OR p_batch_id IS NULL OR length(COALESCE(p_question_id, '')) NOT BETWEEN 1 AND 180
     OR length(COALESCE(p_correct_answer, '')) NOT BETWEEN 1 AND 100
     OR length(COALESCE(p_selected_answer, '')) > 100 OR length(COALESCE(p_explanation, '')) > 2000
     OR length(COALESCE(p_solver_source, '')) NOT BETWEEN 1 AND 100
     OR length(COALESCE(p_classification, '')) NOT BETWEEN 1 AND 40 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_payload');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('leak_drill_user:' || p_user_id::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('leak_drill:' || p_user_id::text || ':' || p_leak_id, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('leak_drill_answer:' || p_user_id::text || ':' || p_batch_id::text || ':' || p_question_id, 0));
  SELECT * INTO v_answer FROM public.leak_drill_answers
    WHERE user_id = p_user_id AND batch_id = p_batch_id AND question_id = p_question_id;
  IF FOUND THEN RETURN jsonb_build_object('success', true, 'idempotent', true, 'answer', to_jsonb(v_answer)); END IF;

  SELECT * INTO v_session FROM public.leak_drill_sessions
    WHERE batch_id = p_batch_id AND user_id = p_user_id AND leak_id = p_leak_id
      AND completed_at IS NULL AND question_ids ? p_question_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_session'); END IF;

  IF v_session.attempt_number IS NULL THEN
    -- The private operation ledger is the authoritative pre-feature history;
    -- unlike leak_review_state it was never client-writable.
    SELECT count(*)::integer INTO v_legacy_attempts
      FROM public.leak_review_operations WHERE user_id = p_user_id AND leak_id = p_leak_id;
    SELECT GREATEST(COALESCE(max(attempt_number), 0), COALESCE(v_legacy_attempts, 0)) + 1 INTO v_attempt
      FROM public.leak_drill_sessions WHERE user_id = p_user_id AND leak_id = p_leak_id;
    UPDATE public.leak_drill_sessions SET attempt_number = v_attempt
      WHERE batch_id = p_batch_id RETURNING * INTO v_session;
  END IF;

  INSERT INTO public.leak_drill_answers(batch_id, user_id, leak_id, question_id, selected_answer,
    correct_answer, correct, timed_out, explanation, solver_source, classification)
  VALUES (p_batch_id, p_user_id, p_leak_id, p_question_id, NULLIF(p_selected_answer, ''),
    p_correct_answer, p_correct, COALESCE(p_timed_out, false), p_explanation, p_solver_source, p_classification)
  RETURNING * INTO v_answer;
  RETURN jsonb_build_object('success', true, 'idempotent', false, 'answer', to_jsonb(v_answer));
END;
$$;


ALTER FUNCTION public.record_verified_leak_drill_answer(p_user_id uuid, p_leak_id text, p_batch_id uuid, p_question_id text, p_selected_answer text, p_correct_answer text, p_correct boolean, p_timed_out boolean, p_explanation text, p_solver_source text, p_classification text) OWNER TO postgres;

--
-- Name: record_verified_leak_drill_attempt(uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_verified_leak_drill_attempt(p_user_id uuid, p_leak_id text, p_review_id text, p_batch_id uuid, p_question_ids jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_existing public.leak_drill_attempts%ROWTYPE;
  v_session public.leak_drill_sessions%ROWTYPE;
  v_total integer;
  v_correct integer;
  v_accuracy numeric;
  v_passed boolean;
  v_evidence jsonb;
BEGIN
  IF p_user_id IS NULL OR p_batch_id IS NULL
     OR p_leak_id !~ '^[A-Za-z0-9][A-Za-z0-9_:.-]{0,63}$'
     OR p_review_id !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{7,95}$'
     OR jsonb_typeof(COALESCE(p_question_ids, 'null'::jsonb)) <> 'array'
     OR jsonb_array_length(p_question_ids) NOT BETWEEN 5 AND 20 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_payload');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('leak_drill_user:' || p_user_id::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('leak_drill:' || p_user_id::text || ':' || p_leak_id, 0));

  SELECT * INTO v_existing FROM public.leak_drill_attempts WHERE batch_id = p_batch_id;
  IF FOUND THEN
    IF v_existing.user_id <> p_user_id OR v_existing.leak_id <> p_leak_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'invalid_session');
    END IF;
    RETURN jsonb_build_object('success', true, 'idempotent', true, 'attempt', to_jsonb(v_existing));
  END IF;
  IF EXISTS (SELECT 1 FROM public.leak_drill_attempts
      WHERE user_id = p_user_id AND leak_id = p_leak_id AND review_id = p_review_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'review_id_reused');
  END IF;

  SELECT * INTO v_session FROM public.leak_drill_sessions
    WHERE batch_id = p_batch_id AND user_id = p_user_id AND leak_id = p_leak_id FOR UPDATE;
  IF NOT FOUND OR v_session.completed_at IS NOT NULL OR v_session.attempt_number IS NULL
     OR v_session.question_ids <> p_question_ids THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_or_consumed_session');
  END IF;

  SELECT count(*)::integer, count(*) FILTER (WHERE correct)::integer,
    jsonb_agg(jsonb_build_object('questionId', question_id, 'selectedAnswer', selected_answer,
      'timedOut', timed_out, 'correct', correct) ORDER BY answered_at, question_id)
    INTO v_total, v_correct, v_evidence
    FROM public.leak_drill_answers
    WHERE user_id = p_user_id AND leak_id = p_leak_id AND batch_id = p_batch_id
      AND question_id IN (SELECT value FROM jsonb_array_elements_text(p_question_ids));
  IF v_total <> jsonb_array_length(p_question_ids) THEN
    RETURN jsonb_build_object('success', false, 'error', 'incomplete_drill');
  END IF;

  -- Revalidate provenance at completion. Drill mastery is coaching state; the
  -- deterministic detector alone resolves empirical leak truth after new play.
  PERFORM 1 FROM public.user_leaks WHERE user_id = p_user_id AND id::text = p_leak_id
    AND detector_managed = true AND source_system = 'solver_engine'
    AND leak_type ~ '^solver_(training|club_arena)_' FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'ineligible_leak'); END IF;

  v_accuracy := round(v_correct::numeric / v_total::numeric, 4);
  v_passed := v_accuracy >= 0.8;
  UPDATE public.leak_drill_sessions SET completed_at = now() WHERE batch_id = p_batch_id;
  INSERT INTO public.leak_drill_attempts(batch_id, user_id, leak_id, review_id, attempt_number,
    total_questions, correct_answers, accuracy, passed, first_attempt, remediation_mastered, evidence)
  VALUES (p_batch_id, p_user_id, p_leak_id, p_review_id, v_session.attempt_number,
    v_total, v_correct, v_accuracy, v_passed, v_session.attempt_number = 1, v_passed, v_evidence)
  RETURNING * INTO v_existing;
  RETURN jsonb_build_object('success', true, 'idempotent', false, 'attempt', to_jsonb(v_existing));
END;
$_$;


ALTER FUNCTION public.record_verified_leak_drill_attempt(p_user_id uuid, p_leak_id text, p_review_id text, p_batch_id uuid, p_question_ids jsonb) OWNER TO postgres;

--
-- Name: record_video_watch_session(uuid, text, integer, integer, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_video_watch_session(p_expected_user_id uuid, p_video_id text, p_additional_seconds integer, p_progress_seconds integer DEFAULT NULL::integer, p_video_title text DEFAULT NULL::text, p_thumbnail_url text DEFAULT NULL::text, p_duration_seconds integer DEFAULT NULL::integer) RETURNS TABLE(canonical_video_id text, previous_watch_duration_seconds integer, watch_duration_seconds integer, progress_seconds integer, credited_seconds integer, watch_started_at timestamp with time zone, last_heartbeat_at timestamp with time zone, watched_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_now timestamptz := clock_timestamp();
  v_requested integer := LEAST(GREATEST(COALESCE(p_additional_seconds, 0), 0), 20);
  v_credited integer := 0;
  v_previous integer := 0;
  v_last_heartbeat timestamptz;
  v_started_at timestamptz;
  v_catalog_title text;
  v_catalog_thumbnail text;
  v_existing boolean := false;
BEGIN
  IF v_user_id IS NULL OR v_user_id <> p_expected_user_id THEN
    RAISE EXCEPTION 'Unauthorized: User ID mismatch';
  END IF;
  IF p_video_id IS NULL OR btrim(p_video_id) = '' THEN
    RAISE EXCEPTION 'Video ID is required';
  END IF;

  SELECT v.title, v.thumbnail_url
    INTO v_catalog_title, v_catalog_thumbnail
    FROM public.video_library_videos v
   WHERE v.youtube_video_id = btrim(p_video_id);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unknown video ID';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_user_id::text || ':' || btrim(p_video_id), 0));

  SELECT COALESCE(h.watch_duration_seconds, 0), h.last_heartbeat_at, h.watch_started_at, true
    INTO v_previous, v_last_heartbeat, v_started_at, v_existing
    FROM public.video_watch_history h
   WHERE h.user_id = v_user_id AND h.video_id = btrim(p_video_id)
   FOR UPDATE;

  -- A fresh proof window starts for legacy rows because their existing totals
  -- may have come from the retired direct-write path.
  IF NOT v_existing OR v_started_at IS NULL THEN
    v_previous := 0;
    v_started_at := v_now;
    v_credited := v_requested;
  ELSIF v_last_heartbeat IS NOT NULL
        AND v_now - v_last_heartbeat >= interval '5 seconds' THEN
    v_credited := LEAST(
      v_requested,
      GREATEST(0, floor(extract(epoch FROM (v_now - v_last_heartbeat)))::integer + 2)
    );
  END IF;

  INSERT INTO public.video_watch_history (
    user_id, video_id, video_title, thumbnail_url,
    watch_duration_seconds, progress_seconds, duration_seconds,
    watch_started_at, last_heartbeat_at, watched_at
  ) VALUES (
    v_user_id, btrim(p_video_id), COALESCE(v_catalog_title, p_video_title),
    COALESCE(v_catalog_thumbnail, p_thumbnail_url), v_credited,
    GREATEST(0, COALESCE(p_progress_seconds, 0)),
    NULLIF(LEAST(GREATEST(COALESCE(p_duration_seconds, 0), 0), 86400), 0),
    v_started_at, v_now, v_now
  )
  ON CONFLICT (user_id, video_id) DO UPDATE SET
    video_title = COALESCE(v_catalog_title, video_watch_history.video_title),
    thumbnail_url = COALESCE(v_catalog_thumbnail, video_watch_history.thumbnail_url),
    watch_duration_seconds = CASE
      WHEN video_watch_history.watch_started_at IS NULL THEN v_credited
      ELSE COALESCE(video_watch_history.watch_duration_seconds, 0) + v_credited
    END,
    progress_seconds = CASE
      WHEN COALESCE(EXCLUDED.duration_seconds, video_watch_history.duration_seconds, 0) > 0
        THEN LEAST(
          COALESCE(EXCLUDED.duration_seconds, video_watch_history.duration_seconds),
          GREATEST(0, COALESCE(p_progress_seconds, video_watch_history.progress_seconds, 0))
        )
      ELSE GREATEST(0, COALESCE(p_progress_seconds, video_watch_history.progress_seconds, 0))
    END,
    duration_seconds = COALESCE(EXCLUDED.duration_seconds, video_watch_history.duration_seconds),
    watch_started_at = COALESCE(video_watch_history.watch_started_at, v_started_at),
    last_heartbeat_at = v_now,
    watched_at = v_now;

  RETURN QUERY
  SELECT btrim(p_video_id), v_previous,
         COALESCE(h.watch_duration_seconds, 0), COALESCE(h.progress_seconds, 0),
         v_credited, h.watch_started_at, h.last_heartbeat_at, h.watched_at
    FROM public.video_watch_history h
   WHERE h.user_id = v_user_id AND h.video_id = btrim(p_video_id);
END;
$$;


ALTER FUNCTION public.record_video_watch_session(p_expected_user_id uuid, p_video_id text, p_additional_seconds integer, p_progress_seconds integer, p_video_title text, p_thumbnail_url text, p_duration_seconds integer) OWNER TO postgres;

--
-- Name: record_youtube_embed_failure_report(text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_youtube_embed_failure_report(p_video_id text, p_error_code integer DEFAULT 150, p_surface text DEFAULT 'Unknown'::text) RETURNS TABLE(video_id text, hit_count integer, verification_status text, resolved boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_video_id text := public.fn_extract_youtube_video_id(p_video_id);
  v_error_code integer;
  v_surface text;
BEGIN
  IF COALESCE(auth.role()::text, '') <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'record_youtube_embed_failure_report requires the service role';
  END IF;

  IF v_video_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'a valid YouTube video id is required';
  END IF;

  v_error_code := CASE
    WHEN p_error_code IN (2, 5, 100, 101, 150) THEN p_error_code
    ELSE 150
  END;
  v_surface := left(
    regexp_replace(
      COALESCE(NULLIF(btrim(p_surface), ''), 'Unknown'),
      '[[:cntrl:]]',
      '',
      'g'
    ),
    80
  );

  PERFORM pg_advisory_xact_lock(
    hashtextextended('youtube-embed-failure:' || v_video_id, 0)
  );

  RETURN QUERY
  INSERT INTO public.youtube_embed_failures AS existing (
    video_id,
    error_code,
    surface,
    hit_count,
    first_seen_at,
    last_seen_at,
    resolved,
    verification_status,
    last_verified_at
  ) VALUES (
    v_video_id,
    v_error_code,
    v_surface,
    1,
    now(),
    now(),
    true,
    'pending',
    NULL
  )
  ON CONFLICT ON CONSTRAINT youtube_embed_failures_video_id_key DO UPDATE
  SET error_code = EXCLUDED.error_code,
      surface = EXCLUDED.surface,
      hit_count = GREATEST(COALESCE(existing.hit_count, 0), 0) + 1,
      last_seen_at = now(),
      resolved = CASE
        WHEN existing.verification_status = 'confirmed'
         AND existing.resolved = false THEN false
        ELSE true
      END,
      verification_status = CASE
        WHEN existing.verification_status = 'confirmed'
         AND existing.resolved = false THEN 'confirmed'
        ELSE 'pending'
      END,
      last_verified_at = CASE
        WHEN existing.verification_status = 'confirmed'
         AND existing.resolved = false THEN existing.last_verified_at
        ELSE NULL
      END
  RETURNING
    existing.video_id,
    existing.hit_count,
    existing.verification_status,
    existing.resolved;
END
$$;


ALTER FUNCTION public.record_youtube_embed_failure_report(p_video_id text, p_error_code integer, p_surface text) OWNER TO postgres;

--
-- Name: record_youtube_embed_failure_verdict(text, text, integer, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_youtube_embed_failure_verdict(p_video_id text, p_verdict text, p_error_code integer DEFAULT NULL::integer, p_surface text DEFAULT 'verification_worker'::text, p_verification_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(video_id text, hit_count integer, verification_status text, resolved boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_video_id text := public.fn_extract_youtube_video_id(p_video_id);
  v_verdict text := replace(lower(btrim(COALESCE(p_verdict, ''))), '-', '_');
  v_verification_status text;
  v_resolved boolean;
  v_error_code integer;
  v_surface text;
  v_existing public.youtube_embed_failures%ROWTYPE;
BEGIN
  IF COALESCE(auth.role()::text, '') <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'record_youtube_embed_failure_verdict requires the service role';
  END IF;

  IF v_video_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'a valid YouTube video id is required';
  END IF;

  IF v_verdict = 'verified' THEN
    v_verification_status := 'resolved';
    v_resolved := true;
  ELSIF v_verdict IN ('unavailable', 'private', 'restricted', 'embed_disabled') THEN
    v_verification_status := 'confirmed';
    v_resolved := false;
  ELSIF v_verdict IN ('error', 'network_error') THEN
    v_verification_status := 'error';
    v_resolved := true;
  ELSE
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'verdict must be verified, unavailable, private, restricted, embed_disabled, error, or network_error';
  END IF;

  v_error_code := CASE
    WHEN p_error_code IN (2, 5, 100, 101, 150) THEN p_error_code
    WHEN v_verdict IN ('unavailable', 'private') THEN 100
    WHEN v_verdict IN ('restricted', 'embed_disabled') THEN 150
    ELSE 150
  END;
  v_surface := left(
    regexp_replace(
      COALESCE(NULLIF(btrim(p_surface), ''), 'verification_worker'),
      '[[:cntrl:]]',
      '',
      'g'
    ),
    80
  );

  PERFORM pg_advisory_xact_lock(
    hashtextextended('youtube-embed-failure:' || v_video_id, 0)
  );

  SELECT f.*
  INTO v_existing
  FROM public.youtube_embed_failures f
  WHERE f.video_id = v_video_id
  FOR UPDATE;

  -- A report arriving after verification began belongs to the next verifier
  -- pass. Do not erase that newer evidence with an older in-flight verdict.
  IF FOUND
     AND p_verification_started_at IS NOT NULL
     AND v_existing.last_seen_at > p_verification_started_at
  THEN
    RETURN QUERY SELECT
      v_existing.video_id,
      v_existing.hit_count,
      v_existing.verification_status,
      v_existing.resolved;
    RETURN;
  END IF;

  RETURN QUERY
  INSERT INTO public.youtube_embed_failures AS existing (
    video_id,
    error_code,
    surface,
    hit_count,
    first_seen_at,
    last_seen_at,
    resolved,
    verification_status,
    last_verified_at
  ) VALUES (
    v_video_id,
    v_error_code,
    v_surface,
    0,
    now(),
    now(),
    v_resolved,
    v_verification_status,
    now()
  )
  ON CONFLICT ON CONSTRAINT youtube_embed_failures_video_id_key DO UPDATE
  SET error_code = EXCLUDED.error_code,
      surface = EXCLUDED.surface,
      resolved = CASE
        WHEN v_verification_status = 'error'
         AND existing.verification_status = 'confirmed'
         AND existing.resolved = false THEN false
        ELSE v_resolved
      END,
      verification_status = CASE
        WHEN v_verification_status = 'error'
         AND existing.verification_status = 'confirmed'
         AND existing.resolved = false THEN 'confirmed'
        ELSE v_verification_status
      END,
      last_verified_at = CASE
        WHEN v_verification_status = 'error'
         AND existing.verification_status = 'confirmed'
         AND existing.resolved = false THEN existing.last_verified_at
        ELSE now()
      END
  RETURNING
    existing.video_id,
    existing.hit_count,
    existing.verification_status,
    existing.resolved;

  SELECT f.*
  INTO v_existing
  FROM public.youtube_embed_failures f
  WHERE f.video_id = v_video_id;

  -- A confirmed trusted verdict revokes the proof used by every live native
  -- job for this source. Do this in the same transaction as the verdict so a
  -- worker can never observe the confirmed block while still claiming or
  -- completing work authorized by the older positive result. The job guard
  -- takes the same advisory lock, which closes the enqueue-versus-verdict race:
  -- whichever transaction wins is followed by either rejection or cancellation.
  IF v_existing.verification_status = 'confirmed'
     AND v_existing.resolved = false
  THEN
    UPDATE public.video_transcode_jobs j
    SET status = 'cancelled',
        completed_at = now(),
        error_message = 'youtube_verification_authorization_revoked',
        worker_id = NULL,
        claim_token = NULL,
        locked_at = NULL,
        heartbeat_at = now()
    WHERE j.source_type = 'youtube'
      AND j.status IN ('queued', 'processing', 'running')
      AND j.canonical_asset_key = 'youtube:' || v_video_id;

    UPDATE public.social_reels r
    SET video_url = r.original_youtube_url,
        playback_type = 'youtube_embed',
        media_status = 'ready',
        native_processing_requested = false,
        source_type = CASE
          WHEN r.origin_type = 'video_library' THEN 'video_library'
          ELSE 'youtube'
        END
    WHERE r.youtube_video_id = v_video_id
      AND r.original_youtube_url IS NOT NULL
      AND (
        r.native_processing_requested
        OR r.media_status IN ('queued', 'processing')
      );
  END IF;

  -- Keep the catalog verdict and failure verdict in this same transaction. A
  -- transient verifier error never overrides a previously confirmed block.
  IF NOT (
    v_verification_status = 'error'
    AND v_existing.verification_status = 'confirmed'
    AND v_existing.resolved = false
  ) THEN
    UPDATE public.video_library_videos v
    SET availability_status = CASE v_verdict
          WHEN 'verified' THEN 'verified'
          WHEN 'unavailable' THEN 'unavailable'
          WHEN 'private' THEN 'private'
          WHEN 'restricted' THEN 'restricted'
          WHEN 'embed_disabled' THEN 'embed_disabled'
          ELSE 'error'
        END,
        embeddable = (v_verdict = 'verified'),
        availability_checked_at = now(),
        availability_failure_reason = CASE
          WHEN v_verdict = 'verified' THEN NULL
          ELSE left(v_verdict || ':' || v_surface, 255)
        END,
        availability_source = 'youtube_embed_verifier'
    WHERE v.youtube_video_id = v_video_id;
  END IF;
END
$$;


ALTER FUNCTION public.record_youtube_embed_failure_verdict(p_video_id text, p_verdict text, p_error_code integer, p_surface text, p_verification_started_at timestamp with time zone) OWNER TO postgres;

--
-- Name: redeem_comps(integer, uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.redeem_comps(p_venue_id integer, p_player_id uuid, p_amount numeric, p_redemption_type text, p_description text, p_staff_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_balance commander_comp_balances%rowtype;
  v_before numeric;
  v_after numeric;
  v_txn_id uuid;
  v_redemption_id uuid;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;

  select * into v_balance
    from commander_comp_balances
   where venue_id = p_venue_id and player_id = p_player_id
   for update;

  if not found then
    raise exception 'Insufficient comp balance';
  end if;
  if v_balance.is_frozen then
    raise exception 'Player comp balance is frozen';
  end if;
  v_before := coalesce(v_balance.current_balance, 0);
  if v_before < p_amount then
    raise exception 'Insufficient comp balance (available: %)', v_before;
  end if;
  v_after := v_before - p_amount;

  update commander_comp_balances
     set current_balance = v_after,
         lifetime_redeemed = coalesce(lifetime_redeemed,0) + p_amount,
         last_redeemed_at = now(),
         updated_at = now()
   where id = v_balance.id;

  insert into commander_comp_transactions
    (venue_id, player_id, balance_id, transaction_type, amount, balance_before, balance_after,
     source_type, approved_by, description, created_at)
  values
    (p_venue_id, p_player_id, v_balance.id, 'redemption', -p_amount, v_before, v_after,
     'redemption', p_staff_id, p_description, now())
  returning id into v_txn_id;

  insert into commander_comp_redemptions
    (transaction_id, venue_id, player_id, redemption_type, comp_amount, cash_value,
     description, processed_by, processed_at, status, created_at)
  values
    (v_txn_id, p_venue_id, p_player_id, p_redemption_type, p_amount, p_amount,
     p_description, p_staff_id, now(), 'completed', now())
  returning id into v_redemption_id;

  return v_redemption_id;
end;
$$;


ALTER FUNCTION public.redeem_comps(p_venue_id integer, p_player_id uuid, p_amount numeric, p_redemption_type text, p_description text, p_staff_id uuid) OWNER TO postgres;

--
-- Name: redeem_home_group_invite_token(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.redeem_home_group_invite_token(p_token text, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
    v_token         RECORD;
    v_group         RECORD;
    v_existing      RECORD;
    v_was_new       boolean := false;
    v_already_state text;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    SELECT * INTO v_token FROM commander_home_invite_tokens
     WHERE token = p_token AND is_active = true
     FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_TOKEN'; END IF;
    IF v_token.expires_at IS NOT NULL AND v_token.expires_at < NOW() THEN
        RAISE EXCEPTION 'TOKEN_EXPIRED';
    END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_token.group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;
    IF NOT v_group.is_active THEN RAISE EXCEPTION 'GROUP_INACTIVE'; END IF;

    IF v_group.owner_id = p_caller_user_id THEN
        RETURN jsonb_build_object(
            'success', true, 'via_token', v_token.id,
            'group_id', v_token.group_id, 'already_owner', true
        );
    END IF;

    SELECT * INTO v_existing
      FROM commander_home_members
     WHERE group_id = v_token.group_id AND user_id = p_caller_user_id;

    IF FOUND THEN
        IF v_existing.status = 'banned' THEN
            RAISE EXCEPTION 'BANNED' USING HINT = 'you are banned from this group';
        ELSIF v_existing.status = 'approved' THEN
            RETURN jsonb_build_object(
                'success', true, 'via_token', v_token.id,
                'group_id', v_token.group_id,
                'already_member', true, 'member_status', 'approved'
            );
        ELSIF v_existing.status IN ('pending', 'declined') THEN
            IF v_token.max_uses IS NOT NULL
               AND COALESCE(v_token.use_count, 0) >= v_token.max_uses THEN
                RAISE EXCEPTION 'TOKEN_EXHAUSTED';
            END IF;
            v_already_state := v_existing.status;
            PERFORM set_config('app.hg_token_redeem_allowed', '1', true);
            UPDATE commander_home_members
               SET status = 'approved', joined_at = NOW()
             WHERE id = v_existing.id;
            PERFORM set_config('app.hg_token_redeem_allowed', '', true);
            v_was_new := true;
        ELSE
            v_already_state := v_existing.status;
            v_was_new := false;
        END IF;
    ELSE
        IF v_token.max_uses IS NOT NULL
           AND COALESCE(v_token.use_count, 0) >= v_token.max_uses THEN
            RAISE EXCEPTION 'TOKEN_EXHAUSTED';
        END IF;
        PERFORM set_config('app.hg_token_redeem_allowed', '1', true);
        INSERT INTO commander_home_members
            (group_id, user_id, role, status, joined_at, created_at)
        VALUES
            (v_token.group_id, p_caller_user_id, 'member', 'approved', NOW(), NOW());
        PERFORM set_config('app.hg_token_redeem_allowed', '', true);
        v_was_new := true;
    END IF;

    IF v_was_new THEN
        UPDATE commander_home_invite_tokens
           SET use_count    = COALESCE(use_count, 0) + 1,
               last_used_at = NOW()
         WHERE id = v_token.id;

        -- ★ NEW: notify the token creator (if not themselves redeeming)
        IF v_token.created_by IS NOT NULL
           AND v_token.created_by <> p_caller_user_id THEN
            BEGIN
              PERFORM public.fn_emit_home_notification(
                p_user_id     => v_token.created_by,
                p_type        => 'home_invite_redeemed',
                p_title       => 'Your invite was used',
                p_message     => 'Someone joined ' ||
                                 COALESCE(v_group.name, 'your group') ||
                                 ' with your invite link.',
                p_link        => '/hub/home-games/group/' || v_group.id::text,
                p_data        => jsonb_build_object(
                                   'group_id', v_group.id,
                                   'token_id', v_token.id,
                                   'token_label', v_token.label,
                                   'redeemed_by', p_caller_user_id),
                p_pref_column => NULL
              );
            EXCEPTION WHEN OTHERS THEN
              RAISE WARNING 'redeem notify failed: %', SQLERRM;
            END;
        END IF;
    END IF;

    INSERT INTO commander_home_audit_log
        (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES
        (v_token.group_id, p_caller_user_id, 'member', p_caller_user_id,
         'joined_via_token',
         jsonb_build_object('token_id', v_token.id, 'was_new', v_was_new,
                            'prior_status', v_already_state));

    RETURN jsonb_build_object(
        'success', true, 'via_token', v_token.id,
        'group_id', v_token.group_id, 'member_status', 'approved',
        'was_new', v_was_new, 'prior_status', v_already_state
    );
END;
$$;


ALTER FUNCTION public.redeem_home_group_invite_token(p_token text, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION redeem_home_group_invite_token(p_token text, p_caller_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.redeem_home_group_invite_token(p_token text, p_caller_user_id uuid) IS 'Phase 40: fixed — no longer routes through join_home_group (which rejects private groups without an invite_code). A valid unexpired unexhausted token is itself proof of invitation and auto-approves the caller.';


--
-- Name: redeem_promo_to_chips(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.redeem_promo_to_chips(p_club_id uuid, p_player_user_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_promo NUMERIC; v_new_promo NUMERIC; v_new_chips NUMERIC;
BEGIN
  IF p_amount <= 0 THEN RETURN jsonb_build_object('success', false, 'error', 'Amount must be positive'); END IF;
  SELECT COALESCE(promo_balance, 0) INTO v_promo FROM club_members WHERE club_id = p_club_id AND user_id = p_player_user_id FOR UPDATE;
  IF v_promo IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Player not found'); END IF;
  IF v_promo < p_amount THEN RETURN jsonb_build_object('success', false, 'error', 'Insufficient promo balance'); END IF;
  UPDATE club_members SET promo_balance = promo_balance - p_amount, chip_balance = COALESCE(chip_balance, 0) + p_amount WHERE club_id = p_club_id AND user_id = p_player_user_id RETURNING promo_balance, chip_balance INTO v_new_promo, v_new_chips;
  RETURN jsonb_build_object('success', true, 'amount', p_amount, 'promo_after', v_new_promo, 'chips_after', v_new_chips);
END;
$$;


ALTER FUNCTION public.redeem_promo_to_chips(p_club_id uuid, p_player_user_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: redeem_referral_code(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.redeem_referral_code(p_referee_id uuid, p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := (SELECT auth.uid());
  v_code record;
  -- DIAMONDS. Dan's to set; the mechanism around them is what this asserts.
  v_award_referrer integer := 100;
  v_award_referee  integer := 100;
  v_credit jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication required');
  END IF;
  IF p_referee_id IS DISTINCT FROM v_caller THEN
    RETURN jsonb_build_object('success', false, 'error', 'can only redeem for your own account');
  END IF;

  SELECT * INTO v_code FROM referral_codes WHERE upper(code) = upper(trim(p_code));
  IF v_code.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid referral code');
  END IF;
  IF v_code.user_id = p_referee_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'cannot redeem your own code');
  END IF;
  IF v_code.max_uses IS NOT NULL AND v_code.uses >= v_code.max_uses THEN
    RETURN jsonb_build_object('success', false, 'error', 'code has reached its maximum uses');
  END IF;
  IF EXISTS (SELECT 1 FROM referral_redemptions WHERE referee_id = p_referee_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'referral already redeemed for this account');
  END IF;

  INSERT INTO referral_redemptions
    (code_id, referrer_id, referee_id, diamonds_awarded_referrer, diamonds_awarded_referee)
  VALUES (v_code.id, v_code.user_id, p_referee_id, v_award_referrer, v_award_referee);

  UPDATE referral_codes SET uses = uses + 1 WHERE id = v_code.id;

  -- Diamonds, idempotent on reference_id, audited into diamond_transactions.
  -- A refused credit unwinds the redemption rather than recording a payout
  -- that never happened.
  v_credit := public.add_diamonds_to_balance(
    p_referee_id, v_award_referee, 'referral_bonus',
    'Referral signup bonus (code ' || v_code.code || ')',
    'referral_signup:' || p_referee_id::text);
  IF COALESCE((v_credit->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'referral signup bonus could not be credited: %',
      COALESCE(v_credit->>'error', 'unknown');
  END IF;

  v_credit := public.add_diamonds_to_balance(
    v_code.user_id, v_award_referrer, 'referral_bonus',
    'Referral reward (code ' || v_code.code || ')',
    'referral_reward:' || v_code.id::text || ':' || p_referee_id::text);
  IF COALESCE((v_credit->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'referral reward could not be credited: %',
      COALESCE(v_credit->>'error', 'unknown');
  END IF;

  RETURN jsonb_build_object('success', true, 'awarded', v_award_referee, 'currency', 'diamonds');
END;
$$;


ALTER FUNCTION public.redeem_referral_code(p_referee_id uuid, p_code text) OWNER TO postgres;

--
-- Name: FUNCTION redeem_referral_code(p_referee_id uuid, p_code text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.redeem_referral_code(p_referee_id uuid, p_code text) IS 'Redeems a referral code and pays DIAMONDS to both sides (never chips - Dan 2026-09-05). Idempotent per side via add_diamonds_to_balance reference_id; a failed credit rolls back the redemption.';


--
-- Name: refresh_player_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_player_stats() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
    DECLARE v_count INTEGER := 0;
    BEGIN
      INSERT INTO player_stats (user_id, club_id, hands_played, total_winnings, total_losses)
      SELECT hp.user_id, t.club_id, COUNT(*)::INTEGER as hands_played,
        COALESCE(SUM(hp.chips_won), 0) as total_winnings, COALESCE(SUM(hp.chips_lost), 0) as total_losses
      FROM hand_players hp JOIN hands h ON h.id = hp.hand_id JOIN tables t ON t.id = h.table_id
      WHERE t.club_id IS NOT NULL GROUP BY hp.user_id, t.club_id
      ON CONFLICT (user_id, club_id) DO UPDATE SET
        hands_played = EXCLUDED.hands_played, total_winnings = EXCLUDED.total_winnings,
        total_losses = EXCLUDED.total_losses, updated_at = NOW();
      GET DIAGNOSTICS v_count = ROW_COUNT;
      RETURN v_count;
    END; $$;


ALTER FUNCTION public.refresh_player_stats() OWNER TO postgres;

--
-- Name: refund_diamond_merch_order_atomic(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refund_diamond_merch_order_atomic(p_order_id uuid, p_actor_id uuid, p_reference_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_order public.merchandise_orders%ROWTYPE;
  v_from_status text;
  v_refund integer;
  v_wallet jsonb;
  v_stock_lines jsonb;
BEGIN
  IF p_reference_id IS NULL OR length(p_reference_id) < 16 OR length(p_reference_id) > 180 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_reference');
  END IF;

  SELECT * INTO v_order
    FROM public.merchandise_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_not_found');
  END IF;
  IF v_order.payment_method <> 'diamonds' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_diamond_order');
  END IF;
  IF v_order.status IN ('shipped', 'delivered') THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_fulfilled');
  END IF;
  IF COALESCE(v_order.metadata ->> 'fulfillment_mode', '') = 'automatic'
     OR NULLIF(v_order.metadata ->> 'printful_order_id', '') IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'provider_cancellation_required'
    );
  END IF;
  v_from_status := v_order.status;

  v_refund := GREATEST(0, v_order.diamonds_spent - v_order.refunded_diamonds);
  IF v_refund = 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'duplicate', true,
      'order_id', v_order.id,
      'refunded_diamonds', v_order.refunded_diamonds
    );
  END IF;

  v_wallet := public.add_diamonds_to_balance(
    v_order.user_id,
    v_refund,
    'refund',
    'Refund - Diamond merchandise order ' || v_order.id::text,
    p_reference_id
  );
  IF COALESCE((v_wallet ->> 'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Diamond merchandise refund wallet credit failed: %',
      COALESCE(v_wallet ->> 'error', 'unknown_error');
  END IF;

  IF NOT v_order.stock_restored THEN
    SELECT jsonb_agg(jsonb_build_object(
      'id', item ->> 'id',
      'variant_id', item ->> 'variantId',
      'qty', (item ->> 'quantity')::integer
    )) INTO v_stock_lines
      FROM jsonb_array_elements(v_order.items) AS item
     WHERE COALESCE((item ->> 'madeToOrder')::boolean, false) IS NOT TRUE;
    IF v_stock_lines IS NOT NULL THEN
      PERFORM public.release_merch_order(v_stock_lines);
    END IF;
  END IF;

  UPDATE public.merchandise_orders
     SET status = 'refunded',
         refunded_diamonds = diamonds_spent,
         refunded_at = now(),
         stock_restored = true,
         fulfillment_version = fulfillment_version + 1,
         metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
           'fulfillment_status', 'refunded',
           'needs_review', false,
           'refunded_by', p_actor_id,
           'refunded_at', now()
         ),
         updated_at = now()
   WHERE id = v_order.id
   RETURNING * INTO v_order;

  INSERT INTO public.merchandise_order_events(
    order_id, actor_id, action, from_status, to_status, details
  ) VALUES (
    v_order.id, p_actor_id, 'refund', v_from_status, 'refunded',
    jsonb_build_object('diamonds', v_refund, 'reference_id', p_reference_id)
  );

  RETURN jsonb_build_object(
    'success', true,
    'duplicate', false,
    'order_id', v_order.id,
    'refunded_diamonds', v_refund,
    'new_balance', v_wallet -> 'new_balance',
    'fulfillment_version', v_order.fulfillment_version
  );
END;
$$;


ALTER FUNCTION public.refund_diamond_merch_order_atomic(p_order_id uuid, p_actor_id uuid, p_reference_id text) OWNER TO postgres;

--
-- Name: refund_diamond_merch_order_atomic_v2(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refund_diamond_merch_order_atomic_v2(p_order_id uuid, p_actor_id uuid, p_expected_version integer, p_reference_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_order public.merchandise_orders%ROWTYPE;
  v_from_status text;
  v_refund integer;
  v_wallet jsonb;
  v_stock_lines jsonb;
BEGIN
  IF p_expected_version IS NULL OR p_expected_version < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_version');
  END IF;
  IF p_reference_id IS NULL OR length(p_reference_id) < 16 OR length(p_reference_id) > 180 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_reference');
  END IF;

  SELECT * INTO v_order
    FROM public.merchandise_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_not_found');
  END IF;
  IF v_order.payment_method <> 'diamonds' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_diamond_order');
  END IF;

  v_refund := GREATEST(0, v_order.diamonds_spent - v_order.refunded_diamonds);
  IF v_refund = 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'duplicate', true,
      'order_id', v_order.id,
      'refunded_diamonds', v_order.refunded_diamonds,
      'fulfillment_version', v_order.fulfillment_version
    );
  END IF;

  IF v_order.fulfillment_version IS DISTINCT FROM p_expected_version THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'version_conflict',
      'fulfillment_version', v_order.fulfillment_version
    );
  END IF;
  IF v_order.status IN ('shipped', 'delivered') THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_fulfilled');
  END IF;
  IF COALESCE(v_order.metadata ->> 'fulfillment_mode', '') = 'automatic'
     OR NULLIF(v_order.metadata ->> 'printful_order_id', '') IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'provider_cancellation_required'
    );
  END IF;
  v_from_status := v_order.status;

  v_wallet := public.add_diamonds_to_balance(
    v_order.user_id,
    v_refund,
    'refund',
    'Refund - Diamond merchandise order ' || v_order.id::text,
    p_reference_id
  );
  IF COALESCE((v_wallet ->> 'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Diamond merchandise refund wallet credit failed: %',
      COALESCE(v_wallet ->> 'error', 'unknown_error');
  END IF;

  IF NOT v_order.stock_restored THEN
    SELECT jsonb_agg(jsonb_build_object(
      'id', item ->> 'id',
      'variant_id', item ->> 'variantId',
      'qty', (item ->> 'quantity')::integer
    )) INTO v_stock_lines
      FROM jsonb_array_elements(v_order.items) AS item
     WHERE COALESCE((item ->> 'madeToOrder')::boolean, false) IS NOT TRUE;
    IF v_stock_lines IS NOT NULL THEN
      PERFORM public.release_merch_order(v_stock_lines);
    END IF;
  END IF;

  UPDATE public.merchandise_orders
     SET status = 'refunded',
         refunded_diamonds = diamonds_spent,
         refunded_at = now(),
         stock_restored = true,
         fulfillment_version = fulfillment_version + 1,
         metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
           'fulfillment_status', 'refunded',
           'needs_review', false,
           'refunded_by', p_actor_id,
           'refunded_at', now()
         ),
         updated_at = now()
   WHERE id = v_order.id
   RETURNING * INTO v_order;

  INSERT INTO public.merchandise_order_events(
    order_id, actor_id, action, from_status, to_status, details
  ) VALUES (
    v_order.id, p_actor_id, 'refund', v_from_status, 'refunded',
    jsonb_build_object('diamonds', v_refund, 'reference_id', p_reference_id)
  );

  RETURN jsonb_build_object(
    'success', true,
    'duplicate', false,
    'order_id', v_order.id,
    'refunded_diamonds', v_refund,
    'new_balance', v_wallet -> 'new_balance',
    'fulfillment_version', v_order.fulfillment_version
  );
END;
$$;


ALTER FUNCTION public.refund_diamond_merch_order_atomic_v2(p_order_id uuid, p_actor_id uuid, p_expected_version integer, p_reference_id text) OWNER TO postgres;

--
-- Name: reject_venue_claim(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reject_venue_claim(p_claim_id uuid, p_admin_user_id uuid, p_rejection_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_claim RECORD; v_admin_role text;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_admin_user_id THEN 
        RAISE EXCEPTION 'UNAUTHORIZED'; 
    END IF;
    SELECT role INTO v_admin_role FROM profiles WHERE id = p_admin_user_id;
    IF v_admin_role NOT IN ('admin','superadmin','moderator') THEN
        RAISE EXCEPTION 'NOT_ADMIN';
    END IF;
    SELECT id, status INTO v_claim FROM venue_claims WHERE id = p_claim_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'CLAIM_NOT_FOUND'; END IF;
    IF v_claim.status NOT IN ('pending','under_review') THEN
        RAISE EXCEPTION 'CLAIM_NOT_ACTIONABLE';
    END IF;

    UPDATE venue_claims 
       SET status = 'rejected', rejection_reason = p_rejection_reason,
           verified_by = p_admin_user_id, updated_at = now()
     WHERE id = p_claim_id;

    RETURN jsonb_build_object('success', true, 'claim_id', p_claim_id, 'status', 'rejected');
END; $$;


