--
-- Name: release_table_leases_v2(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_table_leases_v2(p_instance_id text, p_claims jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  IF length(btrim(COALESCE(p_instance_id, ''))) = 0
     OR p_claims IS NULL
     OR jsonb_typeof(p_claims) <> 'array' THEN
    RAISE EXCEPTION 'release_table_leases_v2 requires instance_id and a JSON claim array'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_claims) item
     WHERE jsonb_typeof(item) <> 'object'
        OR length(btrim(COALESCE(item ->> 'table_id', ''))) = 0
        OR length(btrim(COALESCE(item ->> 'lease_generation', ''))) = 0
  ) THEN
    RAISE EXCEPTION 'release_table_leases_v2 requires one exact generation per claim'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    WITH asked AS (
      SELECT (item ->> 'table_id')::uuid AS id
        FROM jsonb_array_elements(p_claims) item
    )
    SELECT 1 FROM asked GROUP BY id HAVING count(*) <> 1
  ) THEN
    RAISE EXCEPTION 'release_table_leases_v2 refuses duplicate tables'
      USING ERRCODE = '22023';
  END IF;

  WITH asked AS MATERIALIZED (
    SELECT (item ->> 'table_id')::uuid AS table_id,
           (item ->> 'lease_generation')::uuid AS lease_generation
      FROM jsonb_array_elements(p_claims) item
  )
  DELETE FROM public.engine_table_leases l
   USING asked a
   WHERE l.table_id = a.table_id
     AND l.instance_id = p_instance_id
     AND l.protocol_version = 2
     AND l.lease_generation = a.lease_generation;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION public.release_table_leases_v2(p_instance_id text, p_claims jsonb) OWNER TO postgres;

--
-- Name: FUNCTION release_table_leases_v2(p_instance_id text, p_claims jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.release_table_leases_v2(p_instance_id text, p_claims jsonb) IS 'Releases only exact protocol-2 table generations. A stale same-instance dealer cannot delete its successor lease.';


--
-- Name: release_tournament_leases_v2(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_tournament_leases_v2(p_instance_id text, p_claims jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  IF length(btrim(COALESCE(p_instance_id, ''))) = 0
     OR p_claims IS NULL
     OR jsonb_typeof(p_claims) <> 'array' THEN
    RAISE EXCEPTION 'release_tournament_leases_v2 requires instance_id and a JSON claim array'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_claims) item
     WHERE jsonb_typeof(item) <> 'object'
        OR length(btrim(COALESCE(item ->> 'tournament_id', ''))) = 0
        OR length(btrim(COALESCE(item ->> 'lease_generation', ''))) = 0
  ) THEN
    RAISE EXCEPTION 'release_tournament_leases_v2 requires one exact generation per claim'
      USING ERRCODE = '22023';
  END IF;

  /* A duplicate is a malformed authority request, not a claim to silently
     omit. Fail the transaction before deleting anything. */
  IF EXISTS (
    WITH asked AS (
      SELECT (item ->> 'tournament_id')::uuid AS tournament_id
        FROM jsonb_array_elements(p_claims) item
    )
    SELECT 1
      FROM asked
     GROUP BY tournament_id
    HAVING count(*) <> 1
  ) THEN
    RAISE EXCEPTION 'release_tournament_leases_v2 refuses duplicate tournaments'
      USING ERRCODE = '22023';
  END IF;

  WITH asked AS MATERIALIZED (
    SELECT (item ->> 'tournament_id')::uuid AS tournament_id,
           (item ->> 'lease_generation')::uuid AS lease_generation
      FROM jsonb_array_elements(p_claims) item
  )
  DELETE FROM public.engine_tournament_leases l
   USING asked a
   WHERE l.tournament_id = a.tournament_id
     AND l.instance_id = p_instance_id
     AND l.protocol_version = 2
     AND l.lease_generation = a.lease_generation;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION public.release_tournament_leases_v2(p_instance_id text, p_claims jsonb) OWNER TO postgres;

