--
-- Name: replace_hand_audit_decisions(uuid, text[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.replace_hand_audit_decisions(p_user_id uuid, p_hand_ids text[], p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hand_id text;
  v_upserted integer := 0;
  v_removed integer := 0;
BEGIN
  IF p_user_id IS NULL OR p_hand_ids IS NULL
     OR COALESCE(array_length(p_hand_ids, 1), 0) > 100
     OR jsonb_typeof(COALESCE(p_rows, '[]'::jsonb)) <> 'array'
     OR jsonb_array_length(COALESCE(p_rows, '[]'::jsonb)) > 1200 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_payload');
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(COALESCE(p_rows, '[]'::jsonb)) AS r
     WHERE NULLIF(r->>'hand_external_id', '') IS NULL
        OR NOT ((r->>'hand_external_id') = ANY(p_hand_ids))
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'row_hand_mismatch');
  END IF;

  -- Always lock in sorted order so overlapping multi-hand audits cannot
  -- deadlock. Locks live until both the upsert and stale-key delete commit.
  FOR v_hand_id IN
    SELECT DISTINCT h FROM unnest(p_hand_ids) AS h
     WHERE h IS NOT NULL AND length(h) BETWEEN 1 AND 180
     ORDER BY h
  LOOP
    PERFORM pg_advisory_xact_lock(
      hashtextextended('hand_audit:' || p_user_id::text || ':' || v_hand_id, 0)
    );
  END LOOP;

  WITH incoming AS (
    SELECT *
      FROM jsonb_to_recordset(COALESCE(p_rows, '[]'::jsonb)) AS x(
        hand_external_id text,
        decision_key text,
        question_id text,
        game_id text,
        street text,
        hero_position text,
        villain_position text,
        spot_type text,
        hero_hand text,
        board_cards jsonb,
        player_action text,
        solver_action text,
        selected_frequency numeric,
        optimal_frequency numeric,
        classification text,
        ev_loss numeric,
        ev_loss_measured boolean,
        solver_verified boolean,
        solver_source text,
        match_tier integer,
        audited_at timestamptz,
        updated_at timestamptz
      )
  ), written AS (
    INSERT INTO public.hand_audit_decisions (
      user_id, hand_external_id, decision_key, question_id, game_id, street,
      hero_position, villain_position, spot_type, hero_hand, board_cards,
      player_action, solver_action, selected_frequency, optimal_frequency,
      classification, ev_loss, ev_loss_measured, solver_verified,
      solver_source, match_tier, audited_at, updated_at
    )
    SELECT
      p_user_id, hand_external_id, decision_key, question_id, game_id, street,
      hero_position, villain_position, spot_type, hero_hand,
      COALESCE(board_cards, '[]'::jsonb), player_action, solver_action,
      selected_frequency, optimal_frequency, classification, ev_loss,
      COALESCE(ev_loss_measured, false), COALESCE(solver_verified, false),
      solver_source, match_tier, COALESCE(audited_at, now()), COALESCE(updated_at, now())
    FROM incoming
    ON CONFLICT (user_id, hand_external_id, decision_key) DO UPDATE SET
      question_id = EXCLUDED.question_id,
      game_id = EXCLUDED.game_id,
      street = EXCLUDED.street,
      hero_position = EXCLUDED.hero_position,
      villain_position = EXCLUDED.villain_position,
      spot_type = EXCLUDED.spot_type,
      hero_hand = EXCLUDED.hero_hand,
      board_cards = EXCLUDED.board_cards,
      player_action = EXCLUDED.player_action,
      solver_action = EXCLUDED.solver_action,
      selected_frequency = EXCLUDED.selected_frequency,
      optimal_frequency = EXCLUDED.optimal_frequency,
      classification = EXCLUDED.classification,
      ev_loss = EXCLUDED.ev_loss,
      ev_loss_measured = EXCLUDED.ev_loss_measured,
      solver_verified = EXCLUDED.solver_verified,
      solver_source = EXCLUDED.solver_source,
      match_tier = EXCLUDED.match_tier,
      audited_at = EXCLUDED.audited_at,
      updated_at = EXCLUDED.updated_at
    RETURNING 1
  ) SELECT count(*)::integer INTO v_upserted FROM written;

  DELETE FROM public.hand_audit_decisions d
   WHERE d.user_id = p_user_id
     AND d.hand_external_id = ANY(p_hand_ids)
     AND NOT EXISTS (
       SELECT 1
         FROM jsonb_array_elements(COALESCE(p_rows, '[]'::jsonb)) AS r
        WHERE r->>'hand_external_id' = d.hand_external_id
          AND r->>'decision_key' = d.decision_key
     );
  GET DIAGNOSTICS v_removed = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'upserted', v_upserted,
    'removed', v_removed
  );
END;
$$;


ALTER FUNCTION public.replace_hand_audit_decisions(p_user_id uuid, p_hand_ids text[], p_rows jsonb) OWNER TO postgres;

--
-- Name: report_home_content(text, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.report_home_content(p_reported_type text, p_reported_id uuid, p_reason_category text, p_reason_text text, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_new_id       uuid;
    v_valid_types  text[] := ARRAY['post','comment','group','member','game','review'];
    v_valid_cats   text[] := ARRAY['spam','harassment','hate_speech','nudity','violence','illegal',
                                   'fake_game','self_harm','doxxing','other'];
    v_recent_count int;
    v_target_exists boolean;
    v_target_author uuid;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;
    IF NOT (p_reported_type = ANY (v_valid_types)) THEN
        RAISE EXCEPTION 'INVALID_REPORT_TYPE';
    END IF;
    IF NOT (p_reason_category = ANY (v_valid_cats)) THEN
        RAISE EXCEPTION 'INVALID_REASON';
    END IF;
    IF p_reason_text IS NOT NULL AND length(p_reason_text) > 2000 THEN
        RAISE EXCEPTION 'REASON_TOO_LONG';
    END IF;

    -- (a) Existence check + (b) capture author for self-report detection
    CASE p_reported_type
      WHEN 'post' THEN
        SELECT true, author_id INTO v_target_exists, v_target_author
          FROM commander_home_posts WHERE id = p_reported_id;
      WHEN 'comment' THEN
        SELECT true, author_id INTO v_target_exists, v_target_author
          FROM commander_home_post_comments WHERE id = p_reported_id;
      WHEN 'group' THEN
        SELECT true, owner_id INTO v_target_exists, v_target_author
          FROM commander_home_groups WHERE id = p_reported_id;
      WHEN 'member' THEN
        -- For member reports, target_id is the profile id being reported
        SELECT true, p_reported_id INTO v_target_exists, v_target_author
          FROM profiles WHERE id = p_reported_id;
      WHEN 'game' THEN
        SELECT true, host_id INTO v_target_exists, v_target_author
          FROM commander_home_games WHERE id = p_reported_id;
      WHEN 'review' THEN
        SELECT true, reviewer_id INTO v_target_exists, v_target_author
          FROM commander_home_game_reviews WHERE id = p_reported_id;
    END CASE;

    IF NOT COALESCE(v_target_exists, false) THEN
        RAISE EXCEPTION 'REPORTED_TARGET_NOT_FOUND'
              USING HINT = 'the reported ' || p_reported_type || ' does not exist';
    END IF;

    -- (b) Block self-reports
    IF v_target_author = p_caller_user_id THEN
        RAISE EXCEPTION 'CANNOT_SELF_REPORT'
              USING HINT = 'you cannot report your own content';
    END IF;

    -- Rate limit: max 5 reports/hour/user to prevent spam
    SELECT COUNT(*) INTO v_recent_count
      FROM commander_home_content_reports
     WHERE reporter_id = p_caller_user_id
       AND created_at > NOW() - INTERVAL '1 hour';
    IF v_recent_count >= 5 THEN
        RAISE EXCEPTION 'RATE_LIMITED'
              USING HINT = 'max 5 reports per hour';
    END IF;

    -- (c) Block duplicates regardless of status. Rationale: once a moderator
    -- has reviewed a target and either dismissed or acted on it, reopening
    -- the case should go through moderator channels, not a fresh report
    -- ticket from the same user. Legitimate second-offense reports on the
    -- same target can come from different users.
    IF EXISTS (
        SELECT 1 FROM commander_home_content_reports
         WHERE reporter_id = p_caller_user_id
           AND reported_type = p_reported_type
           AND reported_id = p_reported_id
    ) THEN
        RAISE EXCEPTION 'ALREADY_REPORTED'
              USING HINT = 'you have already reported this target';
    END IF;

    INSERT INTO commander_home_content_reports
        (reporter_id, reported_type, reported_id, reason_category, reason_text)
    VALUES
        (p_caller_user_id, p_reported_type, p_reported_id, p_reason_category, p_reason_text)
    RETURNING id INTO v_new_id;

    RETURN jsonb_build_object(
        'success', true,
        'report_id', v_new_id,
        'status', 'pending'
    );
END;
$$;


ALTER FUNCTION public.report_home_content(p_reported_type text, p_reported_id uuid, p_reason_category text, p_reason_text text, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION report_home_content(p_reported_type text, p_reported_id uuid, p_reason_category text, p_reason_text text, p_caller_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.report_home_content(p_reported_type text, p_reported_id uuid, p_reason_category text, p_reason_text text, p_caller_user_id uuid) IS 'Phase 40 Bug 51: added existence check on reported_id, self-report block, and dedupe across all statuses (was only blocking within status=pending).';


--
-- Name: report_live_game(integer, uuid, text, text, integer, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.report_live_game(p_venue_id integer DEFAULT NULL::integer, p_user_id uuid DEFAULT NULL::uuid, p_game_type text DEFAULT NULL::text, p_stakes text DEFAULT NULL::text, p_seats_open integer DEFAULT NULL::integer, p_waitlist_size integer DEFAULT NULL::integer, p_table_count integer DEFAULT 1, p_notes text DEFAULT NULL::text, p_game_quality text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text;
  v_caller_uid uuid;
  v_game_id uuid;
  v_wait_time integer;
BEGIN
  v_caller_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '');
  v_caller_uid := auth.uid();

  IF v_caller_role = 'authenticated' THEN
    IF v_caller_uid IS NULL OR p_user_id <> v_caller_uid THEN
      RAISE WARNING 'report_live_game: spoof attempt by % targeting %', v_caller_uid, p_user_id;
      RETURN NULL;
    END IF;
  ELSIF v_caller_role = 'anon' OR v_caller_role = '' THEN
    RETURN NULL;
  END IF;

  IF p_venue_id IS NULL OR p_user_id IS NULL OR p_game_type IS NULL OR p_stakes IS NULL THEN
    RAISE WARNING 'report_live_game: missing required field';
    RETURN NULL;
  END IF;

  v_wait_time := CASE
    WHEN COALESCE(p_waitlist_size, 0) <= 0 THEN 0
    WHEN COALESCE(p_table_count, 1) <= 0 THEN 60
    ELSE LEAST(180, (COALESCE(p_waitlist_size, 0) * 10) / GREATEST(1, COALESCE(p_table_count, 1)))
  END;

  INSERT INTO public.live_games (
    venue_id, user_id, game_type, stakes,
    table_count, wait_time, notes, game_quality,
    is_active, confirmation_count, created_at, expires_at
  ) VALUES (
    p_venue_id, p_user_id, p_game_type, p_stakes,
    GREATEST(1, COALESCE(p_table_count, 1)),
    v_wait_time,
    p_notes, p_game_quality,
    true, 1, now(), now() + interval '4 hours'
  )
  RETURNING id INTO v_game_id;

  RETURN v_game_id;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'report_live_game failed for user % venue %: % %', p_user_id, p_venue_id, SQLERRM, SQLSTATE;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.report_live_game(p_venue_id integer, p_user_id uuid, p_game_type text, p_stakes text, p_seats_open integer, p_waitlist_size integer, p_table_count integer, p_notes text, p_game_quality text) OWNER TO postgres;

--
-- Name: request_home_group_promotion(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_home_group_promotion(p_group_id uuid, p_caller_user_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_group RECORD; v_new_id uuid;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
      RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    IF p_reason IS NOT NULL AND length(p_reason) > 2000 THEN
      RAISE EXCEPTION 'REASON_TOO_LONG' USING HINT = 'max 2000 chars'; END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;
    IF v_group.owner_id <> p_caller_user_id THEN RAISE EXCEPTION 'OWNER_ONLY_ACTION'; END IF;
    IF v_group.promoted_to_club_id IS NOT NULL THEN RAISE EXCEPTION 'ALREADY_PROMOTED'; END IF;

    IF COALESCE(v_group.games_hosted, 0) < 3 THEN
        RAISE EXCEPTION 'NEED_MIN_GAMES' USING HINT='requires at least 3 completed games';
    END IF;
    IF COALESCE(v_group.member_count, 0) < 5 THEN
        RAISE EXCEPTION 'NEED_MIN_MEMBERS' USING HINT='requires at least 5 members';
    END IF;

    INSERT INTO commander_home_group_promotion_requests (group_id, requested_by, reason)
    VALUES (p_group_id, p_caller_user_id, p_reason)
    ON CONFLICT (group_id) DO UPDATE
        SET status = 'pending', reason = EXCLUDED.reason,
            requested_at = NOW(), reviewer_id = NULL, reviewer_note = NULL
    RETURNING id INTO v_new_id;

    UPDATE commander_home_groups SET promotion_requested_at = NOW() WHERE id = p_group_id;

    INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (p_group_id, p_caller_user_id, 'group', p_group_id, 'promotion_requested',
            jsonb_build_object('reason', p_reason));

    RETURN jsonb_build_object('success', true, 'request_id', v_new_id, 'status', 'pending');
END;
$$;


ALTER FUNCTION public.request_home_group_promotion(p_group_id uuid, p_caller_user_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: request_public_home_game_seat(uuid, uuid, uuid, integer, text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_public_home_game_seat(p_group_id uuid, p_game_id uuid, p_caller_user_id uuid, p_bringing_guests integer DEFAULT 0, p_guest_names text[] DEFAULT ARRAY[]::text[], p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_group public.commander_home_groups%ROWTYPE;
  v_game public.commander_home_games%ROWTYPE;
  v_member public.commander_home_members%ROWTYPE;
  v_prior_rsvp public.commander_home_rsvps%ROWTYPE;
  v_rsvp public.commander_home_rsvps%ROWTYPE;
  v_public_page_id uuid;
  v_member_is_new boolean := false;
  v_member_reopened boolean := false;
  v_membership_status text;
  v_bringing_guests integer;
  v_guest_names text[];
  v_message text;
  v_requested_seats integer;
  v_prior_seats integer := 0;
  v_preserve_confirmation boolean := false;
  v_has_prior_rsvp boolean := false;
  v_game_start_at timestamptz;
  v_previous_claim_sub text := current_setting('request.jwt.claim.sub', true);
  v_previous_claims text := current_setting('request.jwt.claims', true);
BEGIN
  IF auth.uid() IS NULL
     OR p_caller_user_id IS NULL
     OR auth.uid() <> p_caller_user_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
  END IF;
  IF p_group_id IS NULL OR p_game_id IS NULL THEN
    RAISE EXCEPTION 'MISSING_PARAMS';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext(p_group_id::text),
    pg_catalog.hashtext(p_caller_user_id::text)
  );

  SELECT * INTO v_group
    FROM public.commander_home_groups
   WHERE id = p_group_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;
  IF NOT coalesce(v_group.is_active, false) THEN
    RAISE EXCEPTION 'GROUP_INACTIVE';
  END IF;

  -- Pin the page's publication/linkage state until commit. Calling the RPC
  -- directly cannot manufacture a public group/event association.
  SELECT page.id INTO v_public_page_id
    FROM public.social_pages page
   WHERE page.page_type = 'home_game'
     AND page.is_public IS TRUE
     AND page.linked_entity_type = 'home_group'
     AND page.linked_entity_id = p_group_id::text
   ORDER BY page.id
   LIMIT 1
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PUBLIC_HOME_GAME_NOT_FOUND' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_game
    FROM public.commander_home_games
   WHERE id = p_game_id
     AND group_id = p_group_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
  IF v_game.status NOT IN ('scheduled', 'confirmed')
     OR v_game.cancelled_at IS NOT NULL THEN
    RAISE EXCEPTION 'GAME_NOT_OPEN_FOR_RSVP';
  END IF;
  IF coalesce(v_game.rsvps_closed, false) THEN
    RAISE EXCEPTION 'RSVPS_CLOSED';
  END IF;
  IF v_game.rsvp_closes_at IS NOT NULL AND v_game.rsvp_closes_at <= now() THEN
    RAISE EXCEPTION 'RSVP_DEADLINE_PASSED';
  END IF;

  v_game_start_at := (v_game.scheduled_date + v_game.start_time)
    AT TIME ZONE coalesce(nullif(v_game.timezone, ''), v_group.timezone, 'America/New_York');
  IF v_game_start_at <= now() THEN
    RAISE EXCEPTION 'GAME_ALREADY_STARTED';
  END IF;

  v_bringing_guests := least(greatest(coalesce(p_bringing_guests, 0), 0), 10);
  IF NOT coalesce(v_game.allow_guests, false) THEN
    v_bringing_guests := 0;
  ELSIF v_game.guest_limit IS NOT NULL THEN
    v_bringing_guests := least(v_bringing_guests, greatest(v_game.guest_limit, 0));
  END IF;

  SELECT coalesce(
           array_agg(left(btrim(candidate.name), 80) ORDER BY candidate.ordinality),
           ARRAY[]::text[]
         )
    INTO v_guest_names
    FROM unnest(coalesce(p_guest_names, ARRAY[]::text[]))
      WITH ORDINALITY AS candidate(name, ordinality)
   WHERE candidate.ordinality <= v_bringing_guests
     AND nullif(btrim(candidate.name), '') IS NOT NULL;
  v_message := nullif(left(btrim(coalesce(p_message, '')), 500), '');

  IF p_caller_user_id = v_group.owner_id OR p_caller_user_id = v_game.host_id THEN
    v_membership_status := CASE
      WHEN p_caller_user_id = v_group.owner_id THEN 'owner'
      ELSE 'host'
    END;
  ELSE
    SELECT * INTO v_member
      FROM public.commander_home_members
     WHERE group_id = p_group_id
       AND user_id = p_caller_user_id
     FOR UPDATE;

    IF NOT FOUND THEN
      v_member := NULL;
      INSERT INTO public.commander_home_members
        (group_id, user_id, role, status, joined_at, created_at)
      VALUES
        (p_group_id, p_caller_user_id, 'member', 'pending', NULL, now())
      ON CONFLICT (group_id, user_id) WHERE user_id IS NOT NULL DO NOTHING
      RETURNING * INTO v_member;

      IF v_member.id IS NULL THEN
        SELECT * INTO v_member
          FROM public.commander_home_members
         WHERE group_id = p_group_id
           AND user_id = p_caller_user_id
         FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'MEMBERSHIP_CONFLICT'; END IF;
      ELSE
        v_member_is_new := true;
      END IF;
    END IF;

    IF v_member.status = 'banned' THEN
      RAISE EXCEPTION 'MEMBERSHIP_BANNED' USING ERRCODE = '42501';
    ELSIF v_member.status = 'declined' THEN
      IF NOT coalesce(
        v_group.settings -> 'allow_declined_re_request' = 'true'::jsonb,
        false
      ) THEN
        RAISE EXCEPTION 'MEMBERSHIP_DECLINED' USING ERRCODE = '42501';
      END IF;

      -- The existing direct-write guard correctly forbids self-promotion.
      -- This purpose-scoped SECURITY DEFINER transition has already locked and
      -- authenticated the canonical identity, so suppress only nested auth
      -- detection for this one declined -> pending update.
      PERFORM set_config('request.jwt.claim.sub', '', true);
      PERFORM set_config('request.jwt.claims', '', true);
      UPDATE public.commander_home_members
         SET status = 'pending', joined_at = NULL
       WHERE id = v_member.id
         AND status = 'declined'
      RETURNING * INTO v_member;
      PERFORM set_config('request.jwt.claim.sub', coalesce(v_previous_claim_sub, ''), true);
      PERFORM set_config('request.jwt.claims', coalesce(v_previous_claims, ''), true);
      IF v_member.id IS NULL THEN RAISE EXCEPTION 'MEMBERSHIP_CHANGED'; END IF;
      v_member_reopened := true;
    ELSIF v_member.status NOT IN ('approved', 'pending') THEN
      RAISE EXCEPTION 'MEMBERSHIP_STATE_INVALID';
    END IF;

    v_membership_status := v_member.status;
    IF v_member_is_new OR v_member_reopened THEN
      INSERT INTO public.commander_home_audit_log
        (group_id, actor_id, target_type, target_id, action, metadata)
      VALUES (
        p_group_id,
        p_caller_user_id,
        'member',
        v_member.id,
        CASE WHEN v_member_is_new THEN 'member_requested' ELSE 'member_re_requested' END,
        jsonb_build_object(
          'source', 'public_home_game_seat_request',
          'game_id', p_game_id,
          'member_id', v_member.id,
          'member_user_id', v_member.user_id,
          'status', v_member.status
        )
      );
    END IF;
  END IF;

  SELECT * INTO v_prior_rsvp
    FROM public.commander_home_rsvps
   WHERE game_id = p_game_id
     AND user_id = p_caller_user_id
   FOR UPDATE;
  v_has_prior_rsvp := FOUND;

  v_requested_seats := 1 + v_bringing_guests;
  IF v_has_prior_rsvp AND v_prior_rsvp.response = 'yes' THEN
    v_prior_seats := 1 + greatest(coalesce(v_prior_rsvp.bringing_guests, 0), 0);
    v_preserve_confirmation := v_requested_seats <= v_prior_seats;
  END IF;

  -- The legacy RSVP permission trigger rejects caller-supplied updated_at and
  -- some system-maintained transitions. This purpose-scoped RPC has already
  -- authenticated, locked, and validated the caller/game/member, so suppress
  -- nested auth detection only for the atomic upsert and restore it before
  -- returning. The new membership/capacity triggers remain auth-independent.
  PERFORM set_config('request.jwt.claim.sub', '', true);
  PERFORM set_config('request.jwt.claims', '', true);
  INSERT INTO public.commander_home_rsvps AS current_rsvp
    (game_id, user_id, response, bringing_guests, guest_names, message,
     is_confirmed, responded_at, updated_at)
  VALUES
    (p_game_id, p_caller_user_id, 'yes', v_bringing_guests, v_guest_names,
     v_message, false, now(), now())
  ON CONFLICT (game_id, user_id) DO UPDATE
    SET response = 'yes',
        bringing_guests = EXCLUDED.bringing_guests,
        guest_names = EXCLUDED.guest_names,
        message = EXCLUDED.message,
        is_confirmed = CASE
          WHEN v_preserve_confirmation THEN current_rsvp.is_confirmed
          ELSE false
        END,
        seat_number = CASE
          WHEN v_preserve_confirmation THEN current_rsvp.seat_number
          ELSE NULL
        END,
        updated_at = now()
  RETURNING * INTO v_rsvp;
  PERFORM set_config('request.jwt.claim.sub', coalesce(v_previous_claim_sub, ''), true);
  PERFORM set_config('request.jwt.claims', coalesce(v_previous_claims, ''), true);

  RETURN jsonb_build_object(
    'success', true,
    'rsvp', jsonb_build_object(
      'id', v_rsvp.id,
      'response', v_rsvp.response,
      'is_confirmed', coalesce(v_rsvp.is_confirmed, false),
      'bringing_guests', coalesce(v_rsvp.bringing_guests, 0),
      'guest_names', coalesce(v_rsvp.guest_names, ARRAY[]::text[]),
      'message', v_rsvp.message,
      'responded_at', v_rsvp.responded_at,
      'updated_at', v_rsvp.updated_at
    ),
    'membership', jsonb_build_object(
      'id', v_member.id,
      'status', v_membership_status,
      'is_new', v_member_is_new,
      're_requested', v_member_reopened
    ),
    'wait_for_host_approval', NOT coalesce(v_rsvp.is_confirmed, false)
  );
END;
$$;


ALTER FUNCTION public.request_public_home_game_seat(p_group_id uuid, p_game_id uuid, p_caller_user_id uuid, p_bringing_guests integer, p_guest_names text[], p_message text) OWNER TO postgres;

--
-- Name: FUNCTION request_public_home_game_seat(p_group_id uuid, p_game_id uuid, p_caller_user_id uuid, p_bringing_guests integer, p_guest_names text[], p_message text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.request_public_home_game_seat(p_group_id uuid, p_game_id uuid, p_caller_user_id uuid, p_bringing_guests integer, p_guest_names text[], p_message text) IS 'Atomic authenticated seat request for a published Home Games social page: locks group/game/member, audits membership creation or re-request, and returns the trigger-authoritative RSVP.';


--
-- Name: requeue_stuck_push_outbox(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.requeue_stuck_push_outbox(p_stale_minutes integer DEFAULT 15) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int;
BEGIN
  UPDATE public.push_outbox
     SET status = 'pending'
   WHERE status = 'processing'
     AND sent_at IS NULL
     AND COALESCE(claimed_at, created_at) < now() - make_interval(mins => p_stale_minutes);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.requeue_stuck_push_outbox(p_stale_minutes integer) OWNER TO postgres;

--
-- Name: reroll_daily_challenge(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reroll_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_current_challenge_id text;
  v_has_replay_proof boolean := false;
BEGIN
  IF v_uid IS NULL AND public.fn_caller_is_engine() THEN
    v_uid := p_user_id;
  END IF;
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authenticated');
  END IF;
  IF p_user_id IS NULL OR p_user_id <> v_uid THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'cannot reroll another player''s challenge'
    );
  END IF;
  IF p_cost IS NULL OR p_cost NOT IN (1, 10) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'reroll price changed; refresh and try again'
    );
  END IF;

  PERFORM public.fn_lock_daily_mission_user(v_uid);

  SELECT challenge_id INTO v_current_challenge_id
  FROM public.user_daily_challenges
  WHERE id = p_challenge_row_id
    AND user_id = v_uid
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'challenge not found');
  END IF;

  -- Proof is checked even when the row currently carries the expected ID.
  -- Catalog assignments can cycle A -> B -> A; equality alone cannot prove a
  -- UUID-less compatibility request is new after a settled earlier A reroll.
  SELECT
    EXISTS (
      SELECT 1
      FROM public.daily_challenge_reroll_receipts receipt
      WHERE receipt.user_id = v_uid
        AND receipt.challenge_row_id = p_challenge_row_id
        AND receipt.expected_challenge_id = p_expected_challenge_id
        AND receipt.cost = p_cost
    )
    OR EXISTS (
      SELECT 1
      FROM public.diamond_transactions journal
      WHERE journal.user_id = v_uid
        AND journal.reference_id =
          'challenge_reroll:' || p_challenge_row_id::text || ':' || p_expected_challenge_id
        AND journal.amount = -p_cost
        AND journal.transaction_type = 'daily_challenge_reroll'
        AND journal.type = 'daily_challenge_reroll'
        AND journal.metadata ->> 'challenge_row_id' = p_challenge_row_id::text
        AND journal.metadata ->> 'from_challenge_id' = p_expected_challenge_id
    )
  INTO v_has_replay_proof;

  IF v_has_replay_proof THEN
    -- Force the already-settled branch in the private compatibility body. It
    -- returns the current row and balance without creating a UUID or debit.
    RETURN public.reroll_daily_challenge_compatibility_unverified_body(
      p_user_id,
      p_challenge_row_id,
      NULL::text,
      p_cost
    );
  END IF;

  IF v_current_challenge_id IS DISTINCT FROM p_expected_challenge_id THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'challenge changed; refresh and try again'
    );
  END IF;

  RETURN public.reroll_daily_challenge_compatibility_unverified_body(
    p_user_id,
    p_challenge_row_id,
    p_expected_challenge_id,
    p_cost
  );
END;
$$;


ALTER FUNCTION public.reroll_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer) OWNER TO postgres;

--
-- Name: FUNCTION reroll_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reroll_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer) IS 'Compatibility Daily Mission reroll gateway. A settled request replays only when an exact receipt or historical Diamond journal proves settlement, including after an assignment ID cycles.';


--
-- Name: reroll_daily_challenge(uuid, uuid, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reroll_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_uid IS NULL AND public.fn_caller_is_engine() THEN
    v_uid := p_user_id;
  END IF;
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authenticated');
  END IF;
  IF p_user_id IS NULL OR p_user_id <> v_uid THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'cannot reroll another player''s challenge'
    );
  END IF;

  v_result := public.reroll_daily_challenge_one_diamond_receipted_body(
    p_user_id,
    p_challenge_row_id,
    p_expected_challenge_id,
    p_cost,
    p_request_id
  );

  IF COALESCE((v_result ->> 'success')::boolean, false)
     AND COALESCE((v_result ->> 'alreadyRerolled')::boolean, false)
  THEN
    RETURN jsonb_build_object(
      'success', true,
      'requestId', p_request_id,
      'alreadyRerolled', true,
      'diamondsSpent', 0,
      'refreshRequired', true
    );
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.reroll_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer, p_request_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION reroll_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer, p_request_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reroll_daily_challenge(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer, p_request_id uuid) IS 'One-Diamond Daily Mission reroll gateway. Replays acknowledge the durable receipt without returning a stale assignment or wallet projection.';


--
-- Name: reroll_daily_challenge_compatibility_unverified_body(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reroll_daily_challenge_compatibility_unverified_body(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  REROLL_COST constant integer := 1;
  v_uid uuid := auth.uid();
  v_row public.user_daily_challenges%ROWTYPE;
  v_balance integer;
BEGIN
  IF v_uid IS NULL AND public.fn_caller_is_engine() THEN
    v_uid := p_user_id;
  END IF;
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authenticated');
  END IF;
  IF p_user_id IS NULL OR p_user_id <> v_uid THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'cannot reroll another player''s challenge'
    );
  END IF;

  PERFORM public.fn_lock_daily_mission_user(v_uid);

  SELECT * INTO v_row
  FROM public.user_daily_challenges
  WHERE id = p_challenge_row_id
    AND user_id = v_uid
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'challenge not found');
  END IF;

  -- A committed legacy reroll changes this assignment before its response can
  -- be lost. Replay that settled result before rejecting the former price.
  IF v_row.challenge_id IS DISTINCT FROM p_expected_challenge_id THEN
    SELECT COALESCE(diamonds, 0)::integer INTO v_balance
    FROM public.profiles
    WHERE id = v_uid;

    RETURN jsonb_build_object(
      'success', true,
      'alreadyRerolled', true,
      'challengeId', v_row.challenge_id,
      'diamondBalance', COALESCE(v_balance, 0),
      'diamondsSpent', 0,
      'challenge', jsonb_build_object(
        'id', v_row.id,
        'challenge_id', v_row.challenge_id,
        'assigned_date', v_row.assigned_date,
        'progress', v_row.progress,
        'completed', v_row.completed,
        'claimed', v_row.claimed,
        'completed_at', v_row.completed_at,
        'name', v_row.challenge_name_snapshot,
        'description', v_row.challenge_description_snapshot,
        'challenge_type', v_row.challenge_type_snapshot,
        'requirement', v_row.requirement_snapshot,
        'chip_reward', 0,
        'diamond_reward', v_row.diamond_reward_snapshot,
        'tier', v_row.tier_snapshot
      )
    );
  END IF;

  IF p_cost IS DISTINCT FROM REROLL_COST THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'reroll price changed; refresh and try again'
    );
  END IF;

  RETURN public.reroll_daily_challenge(
    p_user_id,
    p_challenge_row_id,
    p_expected_challenge_id,
    p_cost,
    gen_random_uuid()
  );
END;
$$;


ALTER FUNCTION public.reroll_daily_challenge_compatibility_unverified_body(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer) OWNER TO postgres;

--
-- Name: FUNCTION reroll_daily_challenge_compatibility_unverified_body(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reroll_daily_challenge_compatibility_unverified_body(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer) IS 'Private compatibility implementation. Callable only after the public gateway verifies replay evidence.';


--
-- Name: reroll_daily_challenge_one_diamond_receipted_body(uuid, uuid, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reroll_daily_challenge_one_diamond_receipted_body(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  REROLL_COST constant integer := 1;
  v_uid uuid := auth.uid();
  v_row public.user_daily_challenges%ROWTYPE;
  v_receipt public.daily_challenge_reroll_receipts%ROWTYPE;
  v_replacement text;
  v_deduct jsonb;
  v_balance integer;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL AND public.fn_caller_is_engine() THEN
    v_uid := p_user_id;
  END IF;
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authenticated');
  END IF;
  IF p_user_id IS NULL OR p_user_id <> v_uid THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'cannot reroll another player''s challenge'
    );
  END IF;
  IF p_request_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'a reroll request id is required');
  END IF;

  PERFORM public.fn_lock_daily_mission_user(v_uid);

  -- Receipt replay precedes the current-price guard deliberately. A request
  -- settled under the former price is financial history and must remain
  -- replayable with zero new spend after this price change.
  SELECT * INTO v_receipt
  FROM public.daily_challenge_reroll_receipts
  WHERE user_id = v_uid
    AND request_id = p_request_id
  FOR UPDATE;

  IF FOUND THEN
    IF v_receipt.challenge_row_id IS DISTINCT FROM p_challenge_row_id
       OR v_receipt.expected_challenge_id IS DISTINCT FROM p_expected_challenge_id
       OR v_receipt.cost IS DISTINCT FROM p_cost
    THEN
      RETURN jsonb_build_object(
        'success', false,
        'requestId', p_request_id,
        'error', 'reroll request id is already bound to another request'
      );
    END IF;

    RETURN v_receipt.result || jsonb_build_object(
      'requestId', p_request_id,
      'alreadyRerolled', true,
      'diamondsSpent', 0
    );
  END IF;

  IF p_cost IS DISTINCT FROM REROLL_COST THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'reroll price changed; refresh and try again'
    );
  END IF;

  SELECT * INTO v_row
  FROM public.user_daily_challenges
  WHERE id = p_challenge_row_id
    AND user_id = v_uid
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'challenge not found');
  END IF;
  IF v_row.challenge_id IS DISTINCT FROM p_expected_challenge_id THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'challenge changed; refresh and try again'
    );
  END IF;
  IF v_row.completed OR v_row.claimed THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'completed challenges cannot be rerolled'
    );
  END IF;

  SELECT c.id INTO v_replacement
  FROM public.daily_challenge_catalog c
  WHERE c.tier = v_row.tier_snapshot
    AND c.is_active
    AND c.id <> v_row.challenge_id
    AND NOT EXISTS (
      SELECT 1
      FROM public.user_daily_challenges active
      WHERE active.user_id = v_uid
        AND active.assigned_date = v_row.assigned_date
        AND active.challenge_id = c.id
    )
  ORDER BY random()
  LIMIT 1;

  IF v_replacement IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'no replacement challenge is available'
    );
  END IF;

  v_deduct := public.deduct_diamonds(
    p_user_id          := v_uid,
    p_amount           := REROLL_COST,
    p_description      := 'Daily challenge reroll',
    p_transaction_type := 'challenge_reroll',
    p_source           := 'daily_challenge_reroll',
    p_metadata         := jsonb_build_object(
                            'request_id', p_request_id,
                            'challenge_row_id', v_row.id,
                            'from_challenge_id', v_row.challenge_id,
                            'to_challenge_id', v_replacement,
                            'tier', v_row.tier_snapshot
                          ),
    p_reference_id     := 'challenge_reroll:' || p_request_id::text,
    p_cooldown_seconds := 0
  );

  IF COALESCE((v_deduct ->> 'success')::boolean, false) IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', COALESCE(v_deduct ->> 'error', 'not enough diamonds')
    );
  END IF;
  IF COALESCE((v_deduct ->> 'idempotent')::boolean, false) THEN
    RAISE EXCEPTION 'A reroll debit exists without its bound action receipt';
  END IF;

  PERFORM set_config('app.daily_challenge_reroll', '1', true);
  UPDATE public.user_daily_challenges
  SET challenge_id = v_replacement,
      progress = 0,
      completed = false,
      claimed = false,
      completed_at = NULL,
      claimed_at = NULL
  WHERE id = v_row.id
    AND user_id = v_uid
  RETURNING * INTO v_row;

  SELECT COALESCE(diamonds, 0)::integer INTO v_balance
  FROM public.profiles
  WHERE id = v_uid;

  v_result := jsonb_build_object(
    'success', true,
    'requestId', p_request_id,
    'alreadyRerolled', false,
    'challengeId', v_row.challenge_id,
    'diamondBalance', COALESCE(v_balance, 0),
    'diamondsSpent', REROLL_COST,
    'challenge', jsonb_build_object(
      'id', v_row.id,
      'challenge_id', v_row.challenge_id,
      'assigned_date', v_row.assigned_date,
      'progress', v_row.progress,
      'completed', v_row.completed,
      'claimed', v_row.claimed,
      'completed_at', v_row.completed_at,
      'name', v_row.challenge_name_snapshot,
      'description', v_row.challenge_description_snapshot,
      'challenge_type', v_row.challenge_type_snapshot,
      'requirement', v_row.requirement_snapshot,
      'chip_reward', 0,
      'diamond_reward', v_row.diamond_reward_snapshot,
      'tier', v_row.tier_snapshot
    )
  );

  INSERT INTO public.daily_challenge_reroll_receipts (
    user_id,
    request_id,
    challenge_row_id,
    expected_challenge_id,
    cost,
    result
  ) VALUES (
    v_uid,
    p_request_id,
    p_challenge_row_id,
    p_expected_challenge_id,
    p_cost,
    v_result
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.reroll_daily_challenge_one_diamond_receipted_body(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer, p_request_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION reroll_daily_challenge_one_diamond_receipted_body(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer, p_request_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reroll_daily_challenge_one_diamond_receipted_body(p_user_id uuid, p_challenge_row_id uuid, p_expected_challenge_id text, p_cost integer, p_request_id uuid) IS 'Private receipt-bearing Daily Mission reroll implementation. Callable only through the projection-safe public gateway.';


--
-- Name: reserve_clip(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_clip(p_video_id text, p_source_url text, p_clip_source text, p_horse_id uuid) RETURNS TABLE(success boolean, clip_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF p_video_id IS NULL OR length(p_video_id) = 0 THEN
    RETURN QUERY SELECT false, NULL::uuid;
    RETURN;
  END IF;

  INSERT INTO public.posted_clips (video_id, source_url, clip_source, posted_by, posted_at)
  VALUES (p_video_id, p_source_url, p_clip_source, p_horse_id, now())
  ON CONFLICT (video_id) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RETURN QUERY SELECT false, NULL::uuid;
  ELSE
    RETURN QUERY SELECT true, v_id;
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'reserve_clip failed (video=%): % %', p_video_id, SQLERRM, SQLSTATE;
  RETURN QUERY SELECT false, NULL::uuid;
END;
$$;


ALTER FUNCTION public.reserve_clip(p_video_id text, p_source_url text, p_clip_source text, p_horse_id uuid) OWNER TO postgres;

--
-- Name: reserve_merch_order(jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_merch_order(p_items jsonb, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_line        jsonb;
    v_id          text;
    v_variant_id  uuid;
    v_qty         integer;
    v_item        public.merchandise_items%ROWTYPE;
    v_variant     public.merchandise_item_variants%ROWTYPE;
    v_price_usd   numeric;
    v_price_dias  integer;
    v_lines       jsonb := '[]'::jsonb;
    v_total_usd   numeric := 0;
    v_total_dias  integer := 0;
BEGIN
    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_items');
    END IF;
    IF jsonb_array_length(p_items) > 50 THEN
        RETURN jsonb_build_object('success', false, 'error', 'too_many_lines');
    END IF;

    -- ── PASS 1: lock, validate, price ─────────────────────────────────────
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_items) LOOP
        v_id  := v_line ->> 'id';
        v_qty := COALESCE((v_line ->> 'qty')::int, 0);

        BEGIN
            v_variant_id := NULLIF(v_line ->> 'variant_id', '')::uuid;
        EXCEPTION WHEN others THEN
            RETURN jsonb_build_object('success', false, 'error', 'bad_variant_id', 'item', v_id);
        END;

        IF v_id IS NULL OR v_qty < 1 OR v_qty > 10 THEN
            RETURN jsonb_build_object('success', false, 'error', 'bad_line', 'item', v_id);
        END IF;

        SELECT * INTO v_item FROM public.merchandise_items
         WHERE id = v_id AND is_active FOR UPDATE;
        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'error', 'item_unavailable', 'item', v_id);
        END IF;

        IF COALESCE(v_item.has_variants, false) THEN
            IF v_variant_id IS NULL THEN
                RETURN jsonb_build_object('success', false, 'error', 'variant_required', 'item', v_id);
            END IF;

            SELECT * INTO v_variant FROM public.merchandise_item_variants
             WHERE id = v_variant_id AND item_id = v_id AND COALESCE(is_active, true)
             FOR UPDATE;
            IF NOT FOUND THEN
                RETURN jsonb_build_object('success', false, 'error', 'variant_unavailable', 'item', v_id);
            END IF;

            IF v_variant.stock IS NOT NULL AND v_variant.stock < v_qty THEN
                RETURN jsonb_build_object('success', false, 'error', 'insufficient_stock',
                                          'item', v_id, 'available', v_variant.stock);
            END IF;

            v_price_usd  := COALESCE(v_variant.price_usd, v_item.price_usd);
            v_price_dias := COALESCE(NULLIF(v_variant.price_diamonds, 0),
                                     NULLIF(v_item.price_diamonds, 0));
        ELSE
            IF v_variant_id IS NOT NULL THEN
                RETURN jsonb_build_object('success', false, 'error', 'variant_not_applicable', 'item', v_id);
            END IF;
            IF v_item.stock IS NOT NULL AND v_item.stock < v_qty THEN
                RETURN jsonb_build_object('success', false, 'error', 'insufficient_stock',
                                          'item', v_id, 'available', v_item.stock);
            END IF;
            v_price_usd  := v_item.price_usd;
            v_price_dias := NULLIF(v_item.price_diamonds, 0);
        END IF;

        IF v_price_usd IS NULL OR v_price_usd <= 0 THEN
            RETURN jsonb_build_object('success', false, 'error', 'unpriced_item', 'item', v_id);
        END IF;

        v_lines := v_lines || jsonb_build_object(
            'id', v_id,
            'variant_id', v_variant_id,
            'name', v_item.name,
            'qty', v_qty,
            'price_usd', v_price_usd,
            'price_diamonds', v_price_dias
        );
        v_total_usd  := v_total_usd + (v_price_usd * v_qty);
        v_total_dias := v_total_dias
                      + (COALESCE(v_price_dias, CEIL(v_price_usd * 100)::int) * v_qty);
    END LOOP;

    -- ── PASS 2: decrement, unless this is only a validation ───────────────
    IF NOT p_dry_run THEN
        FOR v_line IN SELECT * FROM jsonb_array_elements(v_lines) LOOP
            v_id         := v_line ->> 'id';
            v_qty        := (v_line ->> 'qty')::int;
            v_variant_id := NULLIF(v_line ->> 'variant_id', 'null')::uuid;

            IF v_variant_id IS NOT NULL THEN
                UPDATE public.merchandise_item_variants
                   SET stock = stock - v_qty, updated_at = now()
                 WHERE id = v_variant_id AND stock IS NOT NULL;
            ELSE
                UPDATE public.merchandise_items
                   SET stock = stock - v_qty, updated_at = now()
                 WHERE id = v_id AND stock IS NOT NULL;
            END IF;
        END LOOP;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'dry_run', p_dry_run,
        'lines', v_lines,
        'total_usd', v_total_usd,
        'total_diamonds', v_total_dias
    );
END;
$$;


ALTER FUNCTION public.reserve_merch_order(p_items jsonb, p_dry_run boolean) OWNER TO postgres;

--
-- Name: FUNCTION reserve_merch_order(p_items jsonb, p_dry_run boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reserve_merch_order(p_items jsonb, p_dry_run boolean) IS 'Validates and prices merchandise using the locked reservation path. When p_dry_run is true, inventory is restored before the transaction returns.';


--
-- Name: reserve_sports_clip(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reserve_sports_clip(p_video_id text, p_source_url text, p_clip_source text, p_horse_id uuid) RETURNS TABLE(success boolean, clip_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF p_video_id IS NULL OR length(p_video_id) = 0 THEN
    RETURN QUERY SELECT false, NULL::uuid;
    RETURN;
  END IF;

  INSERT INTO public.sports_clips (video_id, source_url, source, channel_handle, created_at)
  VALUES (p_video_id, p_source_url, p_clip_source, p_horse_id::text, now())
  ON CONFLICT (video_id) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RETURN QUERY SELECT false, NULL::uuid;
  ELSE
    RETURN QUERY SELECT true, v_id;
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'reserve_sports_clip failed (video=%): % %', p_video_id, SQLERRM, SQLSTATE;
  RETURN QUERY SELECT false, NULL::uuid;
END;
$$;


