--
-- Name: reset_home_member_strikes(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reset_home_member_strikes(p_group_id uuid, p_member_user_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_group RECORD;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;

    IF v_group.owner_id <> p_caller_user_id 
       AND NOT EXISTS (SELECT 1 FROM commander_home_members 
                        WHERE group_id = p_group_id AND user_id = p_caller_user_id
                          AND role = 'admin' AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_A_HOST'; END IF;

    UPDATE commander_home_members 
       SET flake_strikes = 0
     WHERE group_id = p_group_id AND user_id = p_member_user_id;

    INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (p_group_id, p_caller_user_id, 'member', p_member_user_id, 'strikes_reset', '{}'::jsonb);

    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION public.reset_home_member_strikes(p_group_id uuid, p_member_user_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: resolve_home_content_report(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_home_content_report(p_report_id uuid, p_action text, p_moderator_note text, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_report RECORD; v_group_id uuid; v_notice text;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
  IF p_moderator_note IS NOT NULL AND length(p_moderator_note) > 2000 THEN
    RAISE EXCEPTION 'MODERATOR_NOTE_TOO_LONG' USING HINT = 'max 2000 chars';
  END IF;

  SELECT role INTO v_role FROM public.profiles WHERE id = p_caller_user_id;
  IF v_role NOT IN ('admin','superadmin','god') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF p_action NOT IN ('dismiss','hide_content','delete_content','warn_author','strike_author','ban_author') THEN
    RAISE EXCEPTION 'INVALID_ACTION';
  END IF;

  SELECT * INTO v_report FROM public.commander_home_content_reports WHERE id = p_report_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REPORT_NOT_FOUND'; END IF;
  IF v_report.status IN ('reviewed','actioned','dismissed') THEN
    RAISE EXCEPTION 'REPORT_ALREADY_RESOLVED' USING HINT = 'status is ' || v_report.status;
  END IF;

  CASE v_report.reported_type
    WHEN 'post' THEN
      SELECT group_id INTO v_group_id FROM public.commander_home_posts WHERE id = v_report.reported_id;
    WHEN 'comment' THEN
      SELECT p.group_id INTO v_group_id FROM public.commander_home_post_comments c
        JOIN public.commander_home_posts p ON p.id = c.post_id WHERE c.id = v_report.reported_id;
    WHEN 'review' THEN
      SELECT g.group_id INTO v_group_id FROM public.commander_home_game_reviews r
        JOIN public.commander_home_games g ON g.id = r.game_id WHERE r.id = v_report.reported_id;
    WHEN 'game' THEN
      SELECT group_id INTO v_group_id FROM public.commander_home_games WHERE id = v_report.reported_id;
    WHEN 'group' THEN v_group_id := v_report.reported_id;
    WHEN 'member' THEN
      SELECT group_id INTO v_group_id FROM public.commander_home_members WHERE id = v_report.reported_id;
  END CASE;

  IF p_action = 'dismiss' THEN v_notice := NULL;
  ELSIF p_action = 'hide_content' THEN
    CASE v_report.reported_type
      WHEN 'post' THEN UPDATE public.commander_home_posts
           SET is_hidden=true, hidden_at=now(), hidden_by=p_caller_user_id,
               hidden_reason = COALESCE(p_moderator_note, 'policy_violation')
         WHERE id = v_report.reported_id;
      WHEN 'comment' THEN UPDATE public.commander_home_post_comments
           SET is_hidden=true, hidden_at=now(), hidden_by=p_caller_user_id,
               hidden_reason = COALESCE(p_moderator_note, 'policy_violation')
         WHERE id = v_report.reported_id;
      WHEN 'review' THEN UPDATE public.commander_home_game_reviews
           SET is_hidden=true, hidden_at=now(), hidden_by=p_caller_user_id,
               hidden_reason = COALESCE(p_moderator_note, 'policy_violation')
         WHERE id = v_report.reported_id;
      WHEN 'game' THEN UPDATE public.commander_home_games
           SET status='cancelled', cancelled_at=now(), cancelled_by=p_caller_user_id,
               cancellation_reason = COALESCE(p_moderator_note, 'moderation_action')
         WHERE id = v_report.reported_id AND status NOT IN ('completed','cancelled');
      WHEN 'group' THEN UPDATE public.commander_home_groups SET is_active=false WHERE id = v_report.reported_id;
      ELSE NULL;
    END CASE;
    v_notice := 'Your ' || v_report.reported_type || ' was hidden for violating community policy.';
  ELSIF p_action = 'delete_content' THEN
    CASE v_report.reported_type
      WHEN 'post'    THEN DELETE FROM public.commander_home_posts         WHERE id = v_report.reported_id;
      WHEN 'comment' THEN DELETE FROM public.commander_home_post_comments WHERE id = v_report.reported_id;
      WHEN 'review'  THEN DELETE FROM public.commander_home_game_reviews  WHERE id = v_report.reported_id;
      WHEN 'game'    THEN UPDATE public.commander_home_games
           SET status='cancelled', cancelled_at=now(), cancelled_by=p_caller_user_id,
               cancellation_reason = COALESCE(p_moderator_note, 'moderation_delete')
         WHERE id = v_report.reported_id AND status NOT IN ('completed','cancelled');
      ELSE NULL;
    END CASE;
    v_notice := 'Your ' || v_report.reported_type || ' was removed for violating community policy.';
  ELSIF p_action = 'warn_author' THEN
    v_notice := 'A moderator reviewed a report on your ' || v_report.reported_type ||
                ' and issued a warning. Please review the community guidelines.';
  ELSIF p_action = 'strike_author' THEN
    IF v_group_id IS NOT NULL AND v_report.content_author_id IS NOT NULL THEN
      UPDATE public.commander_home_members
         SET flake_strikes = COALESCE(flake_strikes, 0) + 1, last_strike_at = now()
       WHERE group_id = v_group_id AND user_id = v_report.content_author_id;
    END IF;
    v_notice := 'Your account received a strike for a community policy violation.';
  ELSIF p_action = 'ban_author' THEN
    IF v_group_id IS NOT NULL AND v_report.content_author_id IS NOT NULL THEN
      UPDATE public.commander_home_members
         SET status='banned', banned_at=now(), banned_by=p_caller_user_id,
             ban_reason = COALESCE(p_moderator_note, 'policy_violation')
       WHERE group_id = v_group_id AND user_id = v_report.content_author_id;
    END IF;
    v_notice := 'You have been banned from this group for a policy violation.';
  END IF;

  UPDATE public.commander_home_content_reports
     SET status = CASE WHEN p_action='dismiss' THEN 'dismissed' ELSE 'actioned' END,
         reviewed_by = p_caller_user_id, reviewed_at = now(),
         moderator_note = p_moderator_note, action_taken = p_action,
         content_hidden_at = CASE WHEN p_action IN ('hide_content','delete_content') THEN now()
                                  ELSE content_hidden_at END
   WHERE id = p_report_id;

  IF v_notice IS NOT NULL AND v_report.content_author_id IS NOT NULL THEN
    PERFORM public.fn_emit_home_notification(
      p_user_id => v_report.content_author_id, p_type => 'moderation_action',
      p_title => 'Moderation action', p_message => v_notice, p_link => NULL,
      p_data => jsonb_build_object('report_id', p_report_id,
                                   'reported_type', v_report.reported_type,
                                   'action', p_action),
      p_pref_column => NULL);
  END IF;

  IF v_group_id IS NOT NULL THEN
    INSERT INTO public.commander_home_audit_log(group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (v_group_id, p_caller_user_id, v_report.reported_type, v_report.reported_id,
            'moderation.' || p_action,
            jsonb_build_object('report_id', p_report_id, 'note', p_moderator_note));
  END IF;

  RETURN jsonb_build_object('success', true, 'report_id', p_report_id,
    'action', p_action, 'group_id_resolved', v_group_id IS NOT NULL);
END;
$$;


ALTER FUNCTION public.resolve_home_content_report(p_report_id uuid, p_action text, p_moderator_note text, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: resolve_home_report_as_host(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_home_report_as_host(p_report_id uuid, p_group_id uuid, p_action text, p_moderator_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_staff boolean;
  v_report RECORD;
  v_owner_id uuid;
  v_report_group_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE='42501'; END IF;
  IF p_moderator_note IS NOT NULL AND length(p_moderator_note) > 2000 THEN
    RAISE EXCEPTION 'MODERATOR_NOTE_TOO_LONG' USING HINT='max 2000 chars'; END IF;
  IF p_action NOT IN ('dismiss','hide_content','warn_author') THEN
    RAISE EXCEPTION 'INVALID_ACTION'
      USING HINT='host actions: dismiss|hide_content|warn_author. For ban/strike/delete, escalate to platform.';
  END IF;

  SELECT owner_id INTO v_owner_id FROM public.commander_home_groups WHERE id = p_group_id;
  IF v_owner_id IS NULL THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;
  v_is_staff := (v_owner_id = v_uid) OR EXISTS (
      SELECT 1 FROM public.commander_home_members
       WHERE group_id = p_group_id AND user_id = v_uid
         AND role IN ('admin','co_host') AND status='approved');
  IF NOT v_is_staff THEN RAISE EXCEPTION 'NOT_GROUP_STAFF' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_report FROM public.commander_home_content_reports
   WHERE id = p_report_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REPORT_NOT_FOUND'; END IF;
  IF v_report.status IN ('reviewed','actioned','dismissed') THEN
    RAISE EXCEPTION 'REPORT_ALREADY_RESOLVED' USING HINT='status is ' || v_report.status;
  END IF;
  IF v_report.reason_category IN ('illegal','self_harm','doxxing') THEN
    RAISE EXCEPTION 'ESCALATION_REQUIRED'
      USING HINT='category ' || v_report.reason_category || ' must be resolved by platform staff';
  END IF;
  IF v_report.content_author_id = v_owner_id THEN
    RAISE EXCEPTION 'CONFLICT_OF_INTEREST'
      USING HINT='host cannot resolve reports against their own content';
  END IF;

  CASE v_report.reported_type
    WHEN 'post' THEN
      SELECT group_id INTO v_report_group_id FROM public.commander_home_posts WHERE id = v_report.reported_id;
    WHEN 'comment' THEN
      SELECT p.group_id INTO v_report_group_id FROM public.commander_home_post_comments c
        JOIN public.commander_home_posts p ON p.id = c.post_id WHERE c.id = v_report.reported_id;
    WHEN 'review' THEN
      SELECT g.group_id INTO v_report_group_id FROM public.commander_home_game_reviews r
        JOIN public.commander_home_games g ON g.id = r.game_id WHERE r.id = v_report.reported_id;
    WHEN 'game' THEN
      SELECT group_id INTO v_report_group_id FROM public.commander_home_games WHERE id = v_report.reported_id;
    WHEN 'member' THEN
      SELECT group_id INTO v_report_group_id FROM public.commander_home_members WHERE id = v_report.reported_id;
    ELSE v_report_group_id := NULL;
  END CASE;
  IF v_report_group_id IS DISTINCT FROM p_group_id THEN
    RAISE EXCEPTION 'REPORT_NOT_IN_GROUP' USING HINT='report does not belong to the specified group';
  END IF;

  IF p_action = 'dismiss' THEN
    UPDATE public.commander_home_content_reports
       SET status='dismissed', reviewed_at=NOW(), reviewed_by=v_uid,
           moderator_note=p_moderator_note, action_taken='dismissed'
     WHERE id=p_report_id;
  ELSIF p_action = 'hide_content' THEN
    CASE v_report.reported_type
      WHEN 'post' THEN
        UPDATE public.commander_home_posts SET is_hidden=true, hidden_at=NOW(),
          hidden_reason = COALESCE(hidden_reason, 'host_moderation')
         WHERE id = v_report.reported_id;
      WHEN 'comment' THEN
        UPDATE public.commander_home_post_comments SET is_hidden=true, hidden_at=NOW(),
          hidden_reason = COALESCE(hidden_reason, 'host_moderation')
         WHERE id = v_report.reported_id;
      WHEN 'review' THEN
        UPDATE public.commander_home_game_reviews SET is_hidden=true, hidden_at=NOW(),
          hidden_reason = COALESCE(hidden_reason, 'host_moderation')
         WHERE id = v_report.reported_id;
      ELSE NULL;
    END CASE;
    UPDATE public.commander_home_content_reports
       SET status='actioned', reviewed_at=NOW(), reviewed_by=v_uid,
           moderator_note=p_moderator_note, action_taken='hide_content',
           content_hidden_at=NOW()
     WHERE id=p_report_id;
  ELSIF p_action = 'warn_author' THEN
    PERFORM public.fn_emit_home_notification(
      v_report.content_author_id, 'home_host_warning',
      'A host reviewed a report about your content',
      COALESCE(p_moderator_note,
        'A host reviewed a report and issued a warning. Please review the group rules.'),
      NULL, jsonb_build_object('group_id', p_group_id, 'report_id', p_report_id), NULL);
    UPDATE public.commander_home_content_reports
       SET status='reviewed', reviewed_at=NOW(), reviewed_by=v_uid,
           moderator_note=p_moderator_note, action_taken='warn_author'
     WHERE id=p_report_id;
  END IF;

  INSERT INTO public.commander_home_audit_log
    (group_id, actor_id, target_type, target_id, action, metadata)
  VALUES (p_group_id, v_uid, v_report.reported_type::text,
          v_report.reported_id, 'host.resolve_report',
          jsonb_build_object(
            'report_id', p_report_id,
            'action', p_action,
            'note_preview', LEFT(COALESCE(p_moderator_note,''), 200)));

  RETURN jsonb_build_object('success', true, 'action', p_action, 'report_id', p_report_id);
END;
$$;


ALTER FUNCTION public.resolve_home_report_as_host(p_report_id uuid, p_group_id uuid, p_action text, p_moderator_note text) OWNER TO postgres;

--
-- Name: resolve_pending_addon(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_pending_addon(p_pending_id uuid, p_max_buy_in numeric DEFAULT NULL::numeric) RETURNS TABLE(applied numeric, refunded numeric, was_resolved boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row        table_pending_addons%ROWTYPE;
  v_stack      numeric;
  v_headroom   numeric;
  v_applied    numeric := 0;
  v_refunded   numeric := 0;
BEGIN
  SELECT * INTO v_row
    FROM table_pending_addons
   WHERE id = p_pending_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pending add-on % not found', p_pending_id;
  END IF;

  IF v_row.resolved_at IS NOT NULL THEN
    applied      := COALESCE(v_row.applied_to_stack, 0);
    refunded     := COALESCE(v_row.refunded, 0);
    was_resolved := false;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT stack INTO v_stack
    FROM table_seats
   WHERE table_id = v_row.table_id
     AND user_id  = v_row.user_id
     AND left_at IS NULL
   FOR UPDATE;

  IF NOT FOUND THEN
    v_applied  := 0;
    v_refunded := v_row.amount;
  ELSE
    IF p_max_buy_in IS NULL THEN
      v_applied := v_row.amount;
    ELSE
      v_headroom := GREATEST(p_max_buy_in - COALESCE(v_stack, 0), 0);
      v_applied  := LEAST(v_row.amount, v_headroom);
    END IF;
    v_refunded := ROUND(v_row.amount - v_applied, 2);
    v_applied  := ROUND(v_applied, 2);

    IF v_applied > 0 THEN
      UPDATE table_seats
         SET stack = COALESCE(stack, 0) + v_applied
       WHERE table_id = v_row.table_id
         AND user_id  = v_row.user_id
         AND left_at IS NULL;
      -- CHIP CONTINUITY (I10): a reload in place is not a leave; the baseline
      -- rises by what was delivered, never by what was refunded.
      PERFORM public.fn_cash_session_add_baseline(v_row.user_id, v_row.table_id, v_applied);
    END IF;
  END IF;

  IF v_refunded > 0 THEN
    PERFORM atomic_credit_wallet_and_log(
      v_row.user_id,
      v_refunded,
      'addon_refund',
      'Add-on refund (exceeds max buy-in or seat vacated)',
      v_row.table_id,
      NULL::uuid,
      NULL::uuid,
      'addon_refund:' || v_row.id::text
    );
  END IF;

  UPDATE table_pending_addons
     SET resolved_at      = now(),
         applied_to_stack = v_applied,
         refunded         = v_refunded
   WHERE id = v_row.id;

  applied      := v_applied;
  refunded     := v_refunded;
  was_resolved := true;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.resolve_pending_addon(p_pending_id uuid, p_max_buy_in numeric) OWNER TO postgres;

--
-- Name: resolve_review_flag(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_review_flag(p_flag_id uuid, p_reviewer_id uuid, p_action text, p_reviewer_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_flag RECORD;
BEGIN
    IF p_action NOT IN ('uphold','dismiss') THEN RAISE EXCEPTION 'INVALID_ACTION'; END IF;
    SELECT * INTO v_flag FROM commander_venue_review_flags WHERE id = p_flag_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'FLAG_NOT_FOUND'; END IF;
    IF v_flag.status <> 'pending' THEN RAISE EXCEPTION 'ALREADY_RESOLVED'; END IF;

    UPDATE commander_venue_review_flags 
       SET status = CASE p_action WHEN 'uphold' THEN 'upheld' ELSE 'dismissed' END,
           reviewer_id = p_reviewer_id, reviewer_note = p_reviewer_note, reviewed_at = NOW()
     WHERE id = p_flag_id;

    IF p_action = 'uphold' THEN
        UPDATE commander_venue_reviews SET is_published = false WHERE id = v_flag.review_id;
    ELSIF p_action = 'dismiss' THEN
        -- If no other pending flags on this review, restore publication
        IF NOT EXISTS(SELECT 1 FROM commander_venue_review_flags 
                       WHERE review_id = v_flag.review_id AND status = 'pending' AND id <> p_flag_id)
        THEN UPDATE commander_venue_reviews SET is_published = true WHERE id = v_flag.review_id;
        END IF;
    END IF;

    RETURN jsonb_build_object('success', true, 'action', p_action);
END; $$;


ALTER FUNCTION public.resolve_review_flag(p_flag_id uuid, p_reviewer_id uuid, p_action text, p_reviewer_note text) OWNER TO postgres;

--
-- Name: resolve_user_leaks_if_unchanged(uuid, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_user_leaks_if_unchanged(p_user_id uuid, p_candidates jsonb, p_resolved_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_requested integer := 0;
  v_resolved integer := 0;
BEGIN
  IF p_user_id IS NULL
     OR jsonb_typeof(COALESCE(p_candidates, '[]'::jsonb)) <> 'array'
     OR jsonb_array_length(COALESCE(p_candidates, '[]'::jsonb)) > 10000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_payload');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('leak_detection:' || p_user_id::text, 0));
  v_requested := jsonb_array_length(COALESCE(p_candidates, '[]'::jsonb));

  WITH candidates AS (
    SELECT *
    FROM jsonb_to_recordset(COALESCE(p_candidates, '[]'::jsonb)) AS x(
      id uuid,
      expected_updated_at timestamptz
    )
  ), resolved AS (
    UPDATE public.user_leaks AS leak
    SET status = 'resolved',
        resolved_at = COALESCE(p_resolved_at, now()),
        remediation_completed_at = COALESCE(p_resolved_at, now()),
        resolution_source = 'detector',
        is_active = false,
        updated_at = COALESCE(p_resolved_at, now())
    FROM candidates AS candidate
    WHERE leak.id = candidate.id
      AND leak.user_id = p_user_id
      AND leak.source_system IN ('live_play', 'solver_engine', 'training_solver')
      AND leak.detector_managed = true
      AND leak.status IS DISTINCT FROM 'resolved'
      AND leak.updated_at IS NOT DISTINCT FROM candidate.expected_updated_at
    RETURNING 1
  )
  SELECT count(*)::integer INTO v_resolved FROM resolved;

  RETURN jsonb_build_object(
    'success', true,
    'requested', v_requested,
    'resolved', v_resolved,
    'conflicts', v_requested - v_resolved
  );
END;
$$;


ALTER FUNCTION public.resolve_user_leaks_if_unchanged(p_user_id uuid, p_candidates jsonb, p_resolved_at timestamp with time zone) OWNER TO postgres;

--
-- Name: resolve_venue_location_integrity(integer, timestamp with time zone, text, text, text, double precision, double precision, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_venue_location_integrity(p_venue_id integer, p_expected_updated_at timestamp with time zone, p_address text, p_city text, p_state text, p_latitude double precision, p_longitude double precision, p_reason text, p_actor_id uuid, p_integrity_status text, p_integrity_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_before public.poker_venues%ROWTYPE;
  v_after public.poker_venues%ROWTYPE;
  v_actor_role text;
BEGIN
  SELECT p.role::text INTO v_actor_role
  FROM public.profiles p
  WHERE p.id = p_actor_id;

  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'superadmin', 'god') THEN
    RAISE EXCEPTION 'platform admin role required' USING ERRCODE = '42501';
  END IF;
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'expected venue revision required' USING ERRCODE = '22023';
  END IF;
  IF char_length(trim(coalesce(p_reason, ''))) < 12 OR char_length(trim(p_reason)) > 500 THEN
    RAISE EXCEPTION 'audit reason must contain 12 to 500 characters' USING ERRCODE = '22023';
  END IF;
  IF p_integrity_status NOT IN ('verified', 'border') THEN
    RAISE EXCEPTION 'only verified or border corrections may be applied' USING ERRCODE = '22023';
  END IF;
  IF p_latitude IS NULL OR p_longitude IS NULL
     OR p_latitude < -90 OR p_latitude > 90
     OR p_longitude < -180 OR p_longitude > 180 THEN
    RAISE EXCEPTION 'coordinates outside valid range' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_before
  FROM public.poker_venues
  WHERE id = p_venue_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'venue not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_before.location_integrity_revision IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'venue revision changed' USING ERRCODE = '40001';
  END IF;

  UPDATE public.poker_venues
  SET address = nullif(trim(p_address), ''),
      city = trim(p_city),
      state = upper(trim(p_state)),
      latitude = p_latitude,
      longitude = p_longitude,
      lat = p_latitude,
      lng = p_longitude,
      last_verified_at = now(),
      location_integrity_revision = clock_timestamp()
  WHERE id = p_venue_id
  RETURNING * INTO v_after;

  INSERT INTO public.venue_location_integrity_log (
    venue_id,
    actor_id,
    reason,
    integrity_status,
    integrity_reason,
    before_record,
    after_record
  ) VALUES (
    p_venue_id,
    p_actor_id,
    trim(p_reason),
    p_integrity_status,
    p_integrity_reason,
    jsonb_build_object(
      'address', v_before.address,
      'city', v_before.city,
      'state', v_before.state,
      'latitude', coalesce(v_before.latitude, v_before.lat),
      'longitude', coalesce(v_before.longitude, v_before.lng),
      'location_integrity_revision', v_before.location_integrity_revision
    ),
    jsonb_build_object(
      'address', v_after.address,
      'city', v_after.city,
      'state', v_after.state,
      'latitude', coalesce(v_after.latitude, v_after.lat),
      'longitude', coalesce(v_after.longitude, v_after.lng),
      'location_integrity_revision', v_after.location_integrity_revision
    )
  );

  RETURN jsonb_build_object(
    'venue_id', v_after.id,
    'name', v_after.name,
    'location_integrity_revision', v_after.location_integrity_revision,
    'integrity_status', p_integrity_status
  );
END;
$$;


ALTER FUNCTION public.resolve_venue_location_integrity(p_venue_id integer, p_expected_updated_at timestamp with time zone, p_address text, p_city text, p_state text, p_latitude double precision, p_longitude double precision, p_reason text, p_actor_id uuid, p_integrity_status text, p_integrity_reason text) OWNER TO postgres;

--
-- Name: FUNCTION resolve_venue_location_integrity(p_venue_id integer, p_expected_updated_at timestamp with time zone, p_address text, p_city text, p_state text, p_latitude double precision, p_longitude double precision, p_reason text, p_actor_id uuid, p_integrity_status text, p_integrity_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.resolve_venue_location_integrity(p_venue_id integer, p_expected_updated_at timestamp with time zone, p_address text, p_city text, p_state text, p_latitude double precision, p_longitude double precision, p_reason text, p_actor_id uuid, p_integrity_status text, p_integrity_reason text) IS 'Atomically corrects venue coordinates with admin-role validation, optimistic concurrency, and before/after audit evidence.';


--
-- Name: respond_to_venue_review(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.respond_to_venue_review(p_review_id uuid, p_caller_user_id uuid, p_response text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_review RECORD; v_is_manager boolean;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    IF length(trim(p_response)) < 2 OR length(p_response) > 2000 THEN RAISE EXCEPTION 'INVALID_RESPONSE'; END IF;
    SELECT * INTO v_review FROM commander_venue_reviews WHERE id = p_review_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'REVIEW_NOT_FOUND'; END IF;

    v_is_manager := public.is_venue_manager(p_caller_user_id, v_review.venue_id);
    IF NOT v_is_manager THEN RAISE EXCEPTION 'NOT_VENUE_MANAGER'; END IF;

    UPDATE commander_venue_reviews 
       SET venue_response = p_response, venue_responded_at = NOW(), updated_at = NOW()
     WHERE id = p_review_id;

    RETURN jsonb_build_object('success', true, 'review_id', p_review_id);
END; $$;


ALTER FUNCTION public.respond_to_venue_review(p_review_id uuid, p_caller_user_id uuid, p_response text) OWNER TO postgres;

--
-- Name: FUNCTION respond_to_venue_review(p_review_id uuid, p_caller_user_id uuid, p_response text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.respond_to_venue_review(p_review_id uuid, p_caller_user_id uuid, p_response text) IS 'Phase 27/B: Manager posts official venue response to a review.';


--
-- Name: retire_duplicate_poker_venue(integer, integer, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.retire_duplicate_poker_venue(p_venue_id integer, p_canonical_venue_id integer, p_expected_revision timestamp with time zone, p_reason text, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_source public.poker_venues%ROWTYPE;
  v_target public.poker_venues%ROWTYPE;
  v_actor_role text;
  v_source_identity text;
  v_target_identity text;
BEGIN
  SELECT role::text INTO v_actor_role FROM public.profiles WHERE id = p_actor_id;
  IF v_actor_role IS NULL OR v_actor_role NOT IN ('admin', 'superadmin', 'god') THEN
    RAISE EXCEPTION 'platform admin role required' USING ERRCODE = '42501';
  END IF;
  IF p_venue_id = p_canonical_venue_id THEN
    RAISE EXCEPTION 'canonical venue must differ from retired venue' USING ERRCODE = '22023';
  END IF;
  IF char_length(trim(coalesce(p_reason, ''))) < 12 OR char_length(trim(p_reason)) > 500 THEN
    RAISE EXCEPTION 'audit reason must contain 12 to 500 characters' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_source FROM public.poker_venues WHERE id = p_venue_id FOR UPDATE;
  SELECT * INTO v_target FROM public.poker_venues WHERE id = p_canonical_venue_id FOR UPDATE;
  IF v_source.id IS NULL OR v_target.id IS NULL THEN
    RAISE EXCEPTION 'source or canonical venue not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_source.location_integrity_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'venue revision changed' USING ERRCODE = '40001';
  END IF;
  IF coalesce(v_target.is_active, true) IS NOT TRUE OR coalesce(v_target.is_suppressed, false) IS TRUE THEN
    RAISE EXCEPTION 'canonical venue must be active and public' USING ERRCODE = '22023';
  END IF;

  v_source_identity := lower(regexp_replace(coalesce(v_source.name, ''), '[^a-zA-Z0-9]+', '', 'g'))
    || '|' || lower(trim(coalesce(v_source.city, ''))) || '|' || upper(trim(coalesce(v_source.state, '')));
  v_target_identity := lower(regexp_replace(coalesce(v_target.name, ''), '[^a-zA-Z0-9]+', '', 'g'))
    || '|' || lower(trim(coalesce(v_target.city, ''))) || '|' || upper(trim(coalesce(v_target.state, '')));
  IF v_source_identity IS DISTINCT FROM v_target_identity THEN
    RAISE EXCEPTION 'venues do not share the same normalized identity' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.venue_duplicate_retirement_log (
    retired_venue_id, canonical_venue_id, actor_id, reason, before_record
  ) VALUES (
    v_source.id, v_target.id, p_actor_id, trim(p_reason),
    jsonb_build_object(
      'name', v_source.name,
      'city', v_source.city,
      'state', v_source.state,
      'is_active', v_source.is_active,
      'is_suppressed', v_source.is_suppressed,
      'revision', v_source.location_integrity_revision
    )
  );

  UPDATE public.poker_venues
  SET canonical_venue_id = v_target.id,
      is_active = false,
      is_suppressed = true,
      retired_at = now(),
      retired_by = p_actor_id,
      retired_reason = trim(p_reason),
      location_integrity_revision = clock_timestamp()
  WHERE id = v_source.id;

  RETURN jsonb_build_object(
    'retired_venue_id', v_source.id,
    'canonical_venue_id', v_target.id,
    'canonical_name', v_target.name
  );
END;
$$;


ALTER FUNCTION public.retire_duplicate_poker_venue(p_venue_id integer, p_canonical_venue_id integer, p_expected_revision timestamp with time zone, p_reason text, p_actor_id uuid) OWNER TO postgres;

--
-- Name: review_home_ban_appeal(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.review_home_ban_appeal(p_appeal_id uuid, p_decision text, p_reviewer_note text, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_appeal RECORD;
  v_is_group_staff boolean;
  v_is_platform_staff boolean;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
  IF p_decision NOT IN ('approved','denied') THEN RAISE EXCEPTION 'INVALID_DECISION'; END IF;
  IF p_reviewer_note IS NOT NULL AND length(p_reviewer_note) > 2000 THEN
    RAISE EXCEPTION 'REVIEWER_NOTE_TOO_LONG' USING HINT = 'max 2000 chars';
  END IF;

  SELECT * INTO v_appeal FROM public.commander_home_ban_appeals WHERE id = p_appeal_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'APPEAL_NOT_FOUND'; END IF;
  IF v_appeal.status <> 'pending' THEN
    RAISE EXCEPTION 'APPEAL_ALREADY_REVIEWED' USING HINT = 'status is ' || v_appeal.status;
  END IF;

  SELECT (
    EXISTS (SELECT 1 FROM public.commander_home_groups
             WHERE id = v_appeal.group_id AND owner_id = p_caller_user_id)
    OR EXISTS (SELECT 1 FROM public.commander_home_members
                WHERE group_id = v_appeal.group_id AND user_id = p_caller_user_id
                  AND role IN ('owner','admin') AND status = 'approved')
  ) INTO v_is_group_staff;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = p_caller_user_id AND role IN ('admin','superadmin','god')
  ) INTO v_is_platform_staff;

  IF NOT (v_is_group_staff OR v_is_platform_staff) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING HINT = 'only group owner/admin or platform staff can review appeals';
  END IF;

  UPDATE public.commander_home_ban_appeals
     SET status = p_decision, reviewed_by = p_caller_user_id,
         reviewed_at = now(), reviewer_note = p_reviewer_note
   WHERE id = p_appeal_id;

  IF p_decision = 'approved' THEN
    UPDATE public.commander_home_members
       SET status='approved', banned_at=NULL, banned_by=NULL, ban_reason=NULL,
           flake_strikes=0, last_strike_at=NULL
     WHERE id = v_appeal.member_id;

    PERFORM public.fn_emit_home_notification(
      p_user_id => v_appeal.user_id, p_type => 'ban_appeal_approved',
      p_title => 'Ban appeal approved',
      p_message => 'Your ban appeal was approved. You can rejoin this group.',
      p_link => NULL,
      p_data => jsonb_build_object('group_id', v_appeal.group_id),
      p_pref_column => NULL);
  ELSE
    PERFORM public.fn_emit_home_notification(
      p_user_id => v_appeal.user_id, p_type => 'ban_appeal_denied',
      p_title => 'Ban appeal denied',
      p_message => COALESCE('Your ban appeal was denied. Reviewer note: ' || p_reviewer_note,
                            'Your ban appeal was denied.'),
      p_link => NULL,
      p_data => jsonb_build_object('group_id', v_appeal.group_id),
      p_pref_column => NULL);
  END IF;

  INSERT INTO public.commander_home_audit_log(group_id, actor_id, target_type, target_id, action, metadata)
  VALUES (v_appeal.group_id, p_caller_user_id, 'member', v_appeal.member_id,
          'ban_appeal.' || p_decision,
          jsonb_build_object(
            'appeal_id', p_appeal_id,
            'note', p_reviewer_note,
            'reviewed_as', CASE WHEN v_is_group_staff THEN 'group_staff' ELSE 'platform_staff' END));

  RETURN jsonb_build_object('success', true, 'appeal_id', p_appeal_id, 'decision', p_decision);
END;
$$;


ALTER FUNCTION public.review_home_ban_appeal(p_appeal_id uuid, p_decision text, p_reviewer_note text, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: revive_home_group(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.revive_home_group(p_group_id uuid, p_caller_user_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE g_owner_id uuid; g_is_active boolean; new_ts timestamptz;
BEGIN
    IF auth.role() IS DISTINCT FROM 'service_role'
       AND (auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_caller_user_id) THEN
        RAISE EXCEPTION 'revive_home_group: caller identity mismatch' USING ERRCODE = '42501';
    END IF;
    IF p_group_id IS NULL OR p_caller_user_id IS NULL THEN
        RAISE EXCEPTION 'revive_home_group: both p_group_id and p_caller_user_id are required'
          USING ERRCODE = '22004';
    END IF;
    SELECT owner_id, is_active INTO g_owner_id, g_is_active
      FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'revive_home_group: home group % not found', p_group_id USING ERRCODE = 'P0002';
    END IF;
    IF NOT g_is_active THEN
        RAISE EXCEPTION 'revive_home_group: group is deactivated and cannot be revived by host' USING ERRCODE = '22023';
    END IF;
    IF p_caller_user_id <> g_owner_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members m
                        WHERE m.group_id = p_group_id AND m.user_id = p_caller_user_id
                          AND m.status = 'approved' AND m.role = 'admin') THEN
        RAISE EXCEPTION 'revive_home_group: caller is not authorized for this group' USING ERRCODE = '42501';
    END IF;
    UPDATE commander_home_groups
       SET last_activity_at = NOW(), updated_at = NOW()
     WHERE id = p_group_id
     RETURNING last_activity_at INTO new_ts;

    -- ★ NEW: audit log
    INSERT INTO public.commander_home_audit_log
      (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (p_group_id, p_caller_user_id, 'group', p_group_id, 'revived',
            jsonb_build_object('new_last_activity_at', new_ts));

    RETURN new_ts;
END;
$$;


ALTER FUNCTION public.revive_home_group(p_group_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION revive_home_group(p_group_id uuid, p_caller_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.revive_home_group(p_group_id uuid, p_caller_user_id uuid) IS 'Phase 22. Owner/admin-gated "keep my group visible" action. API handler pre-authenticates the caller and passes the verified user_id; this function re-verifies ownership as defense-in-depth before bumping last_activity_at=NOW(). Used by the host dashboard "Revive Group" button. Raises 42501 on auth failure.';


--
-- Name: rpc_hg_change_seat(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_change_seat(p_reservation_id uuid, p_new_seat_number integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_preview  RECORD;
  v_updated  RECORD;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  SELECT r.id, r.seat_number, r.status, r.user_id, r.claimed_by_user_id,
         r.table_id, r.is_guest, r.member_id,
         t.max_seats, t.game_id,
         g.status AS game_status
    INTO v_preview
    FROM public.commander_home_seat_reservations r
    JOIN public.commander_home_game_tables t ON t.id = r.table_id
    JOIN public.commander_home_games g       ON g.id = t.game_id
   WHERE r.id = p_reservation_id;
  IF v_preview.id IS NULL THEN RAISE EXCEPTION 'RESERVATION_NOT_FOUND'; END IF;

  -- FIX 1: parent game must still be live. Table status is intentionally NOT
  -- gated - moving seats on a running table is supported (see BUG-1 below).
  IF v_preview.game_status IS NOT NULL
     AND v_preview.game_status IN ('cancelled','completed') THEN
    RAISE EXCEPTION 'GAME_NOT_ACTIVE' USING HINT = v_preview.game_status;
  END IF;

  IF v_preview.user_id IS DISTINCT FROM v_user_id
     AND v_preview.claimed_by_user_id IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'NOT_YOUR_RESERVATION';
  END IF;

  IF v_preview.status NOT IN ('reserved','seated') THEN
    RAISE EXCEPTION 'RESERVATION_INACTIVE';
  END IF;

  IF p_new_seat_number < 1 OR p_new_seat_number > v_preview.max_seats THEN
    RAISE EXCEPTION 'SEAT_OUT_OF_BOUNDS';
  END IF;

  IF p_new_seat_number = v_preview.seat_number THEN
    RETURN p_reservation_id;
  END IF;

  -- FIX 3: map the seat-lock race to a domain error.
  BEGIN
    UPDATE public.commander_home_seat_reservations
       SET seat_number = p_new_seat_number,
           updated_at  = now()
     WHERE id = p_reservation_id
       AND status IN ('reserved','seated')
       AND (user_id = v_user_id OR claimed_by_user_id = v_user_id)
    RETURNING id, table_id, seat_number, user_id, is_guest, status
         INTO v_updated;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'SEAT_TAKEN';
  END;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESERVATION_INACTIVE'
      USING HINT = 'reservation was just released or reassigned';
  END IF;

  -- BUG-1 fix: if reservation was 'seated' (table running), sync the
  -- live seat map too. commander_home_seats has its own (table_id,
  -- seat_number) unique-index so this will error cleanly if the target
  -- seat is already occupied there - which in practice cannot happen
  -- because the reservations unique-index already blocked it.
  --
  -- FIX 2: also bump updated_at. Without it, realtime subscribers that
  -- order or diff on updated_at never observe a seat move and the
  -- Commander tablet view shows the player in their old seat.
  IF v_updated.status = 'seated' THEN
    BEGIN
      UPDATE public.commander_home_seats
         SET seat_number = p_new_seat_number,
             updated_at  = now()
       WHERE reservation_id = p_reservation_id;
    EXCEPTION WHEN unique_violation THEN
      RAISE EXCEPTION 'SEAT_TAKEN';
    END;
  END IF;

  -- Shadow-write to rsvps: only if it was pointing at the OLD seat.
  IF v_updated.is_guest = false AND v_updated.user_id IS NOT NULL THEN
    UPDATE public.commander_home_rsvps
       SET seat_number = v_updated.seat_number,
           updated_at  = now()
     WHERE game_id    = v_preview.game_id
       AND user_id    = v_updated.user_id
       AND seat_number IS NOT DISTINCT FROM v_preview.seat_number;
  END IF;

  RETURN p_reservation_id;
END $$;


ALTER FUNCTION public.rpc_hg_change_seat(p_reservation_id uuid, p_new_seat_number integer) OWNER TO postgres;

--
-- Name: FUNCTION rpc_hg_change_seat(p_reservation_id uuid, p_new_seat_number integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rpc_hg_change_seat(p_reservation_id uuid, p_new_seat_number integer) IS 'Phase B Pass: BUG-1 fix. If reservation status was "seated" (table running), the live commander_home_seats row is also updated so the Commander tablet view reflects the seat change immediately.';


--
-- Name: rpc_hg_claim_seat(uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_claim_seat(p_table_id uuid, p_seat_number integer, p_is_guest boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id        uuid := auth.uid();
  v_table          RECORD;
  v_group_id       uuid;
  v_reservation_id uuid;
  v_caller_name    text;
  v_guest_name     text;
  v_existing_rsvp  text;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  -- Pull the parent game's status and capacity alongside the table.
  SELECT t.id, t.game_id, t.status, t.max_seats,
         g.group_id, g.status AS game_status
    INTO v_table
    FROM public.commander_home_game_tables t
    JOIN public.commander_home_games g ON g.id = t.game_id
   WHERE t.id = p_table_id;

  IF v_table.id IS NULL THEN RAISE EXCEPTION 'TABLE_NOT_FOUND'; END IF;

  -- FIX 1: the parent game must still be live. Table status alone is not
  -- sufficient - the two are independent enums with no cascade.
  IF v_table.game_status IS NOT NULL
     AND v_table.game_status IN ('cancelled','completed') THEN
    RAISE EXCEPTION 'GAME_NOT_ACTIVE' USING HINT = v_table.game_status;
  END IF;

  IF v_table.status <> 'open_for_rsvp' THEN
    RAISE EXCEPTION 'TABLE_NOT_OPEN' USING HINT = v_table.status;
  END IF;
  IF p_seat_number < 1 OR p_seat_number > v_table.max_seats THEN
    RAISE EXCEPTION 'SEAT_OUT_OF_BOUNDS';
  END IF;

  v_group_id := v_table.group_id;

  IF NOT EXISTS (
    SELECT 1 FROM public.commander_home_members
     WHERE group_id = v_group_id AND user_id = v_user_id AND status = 'approved'
  ) AND NOT EXISTS (
    SELECT 1 FROM public.commander_home_groups
     WHERE id = v_group_id AND owner_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'NOT_A_MEMBER';
  END IF;

  -- FIX 2: never let a seat claim overwrite a host-set waitlist/decline.
  SELECT response INTO v_existing_rsvp
    FROM public.commander_home_rsvps
   WHERE game_id = v_table.game_id AND user_id = v_user_id;

  IF v_existing_rsvp IN ('waitlist','no') THEN
    RAISE EXCEPTION 'WAITLISTED_CANNOT_SELF_SEAT' USING HINT = v_existing_rsvp;
  END IF;

  IF p_is_guest THEN
    -- BUG-2 fix: truncate caller display name so "{name} + Guest" never
    -- exceeds the 120-char guest_name CHECK constraint. 112 = 120 - 8
    -- (length of " + Guest").
    v_caller_name := LEFT(public.fn_hg_caller_display_name(v_user_id), 112);
    v_guest_name := v_caller_name || ' + Guest';
    BEGIN
      INSERT INTO public.commander_home_seat_reservations
        (table_id, seat_number, user_id, guest_name, is_guest, claimed_by_user_id, status)
      VALUES (p_table_id, p_seat_number, NULL, v_guest_name, true, v_user_id, 'reserved')
      RETURNING id INTO v_reservation_id;
    EXCEPTION WHEN unique_violation THEN
      -- FIX 3: map the storage-layer guards to domain errors.
      IF SQLERRM LIKE '%one_guest_per_user_per_table%' THEN
        RAISE EXCEPTION 'GUEST_ALREADY_CLAIMED';
      ELSE
        RAISE EXCEPTION 'SEAT_TAKEN';
      END IF;
    END;
  ELSE
    BEGIN
      INSERT INTO public.commander_home_seat_reservations
        (table_id, seat_number, user_id, is_guest, claimed_by_user_id, status)
      VALUES (p_table_id, p_seat_number, v_user_id, false, v_user_id, 'reserved')
      RETURNING id INTO v_reservation_id;
    EXCEPTION WHEN unique_violation THEN
      IF SQLERRM LIKE '%user_table_active%' THEN
        RAISE EXCEPTION 'ALREADY_AT_TABLE';
      ELSE
        RAISE EXCEPTION 'SEAT_TAKEN';
      END IF;
    END;

    INSERT INTO public.commander_home_rsvps
      (game_id, user_id, response, seat_number, is_confirmed, responded_at)
    VALUES (v_table.game_id, v_user_id, 'yes', p_seat_number, false, now())
    ON CONFLICT (game_id, user_id) DO UPDATE
      SET response = 'yes',
          seat_number = EXCLUDED.seat_number,
          responded_at = now(),
          updated_at = now()
      -- Belt-and-braces on FIX 2: even under a concurrent host update, never
      -- flip a waitlist/decline to 'yes' via this path.
      WHERE public.commander_home_rsvps.response NOT IN ('waitlist','no');
  END IF;

  RETURN v_reservation_id;
END $$;


ALTER FUNCTION public.rpc_hg_claim_seat(p_table_id uuid, p_seat_number integer, p_is_guest boolean) OWNER TO postgres;

--
-- Name: FUNCTION rpc_hg_claim_seat(p_table_id uuid, p_seat_number integer, p_is_guest boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rpc_hg_claim_seat(p_table_id uuid, p_seat_number integer, p_is_guest boolean) IS 'Claim a seat at a home game table. Guards: auth, parent game not cancelled/completed, table open_for_rsvp, seat in bounds, approved member or group owner, and refusal to self-promote off a host-set waitlist. Unique-index races are mapped to SEAT_TAKEN / ALREADY_AT_TABLE / GUEST_ALREADY_CLAIMED. See migration phase53.';


--
-- Name: rpc_hg_create_table(uuid, text, text, text, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_create_table(p_game_id uuid, p_game_type text, p_stakes text, p_format text DEFAULT 'cash'::text, p_buyin_min integer DEFAULT NULL::integer, p_buyin_max integer DEFAULT NULL::integer, p_max_seats integer DEFAULT 9, p_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_game    RECORD;
  v_next    int;
  v_id      uuid;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  SELECT id, group_id, host_id, cancelled_at, scheduled_date, start_time, status
    INTO v_game
    FROM public.commander_home_games
   WHERE id = p_game_id;
  IF v_game.id IS NULL THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
  IF v_game.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'GAME_CANCELLED'; END IF;

  IF NOT public.fn_home_is_group_staff(v_user_id, v_game.group_id)
     AND v_game.host_id <> v_user_id
     AND NOT EXISTS (SELECT 1 FROM public.commander_home_groups
                      WHERE id = v_game.group_id AND owner_id = v_user_id)
  THEN
    RAISE EXCEPTION 'NOT_GROUP_STAFF';
  END IF;

  IF p_max_seats IS NULL OR p_max_seats < 2 OR p_max_seats > 10 THEN
    RAISE EXCEPTION 'MAX_SEATS_OUT_OF_BOUNDS';
  END IF;

  SELECT COALESCE(MAX(table_number), 0) + 1 INTO v_next
    FROM public.commander_home_game_tables WHERE game_id = p_game_id;

  INSERT INTO public.commander_home_game_tables
    (game_id, table_number, name, game_type, stakes, format,
     buyin_min, buyin_max, max_seats, status, is_default, created_by)
  VALUES
    (p_game_id, v_next, NULLIF(trim(p_name),''),
     COALESCE(NULLIF(trim(p_game_type),''),'NLH'),
     NULLIF(trim(p_stakes),''),
     CASE WHEN p_format IN ('cash','tournament','sitngo','mixed') THEN p_format ELSE 'cash' END,
     p_buyin_min, p_buyin_max, p_max_seats,
     'open_for_rsvp', false, v_user_id)
  RETURNING id INTO v_id;

  RETURN v_id;
END $$;


ALTER FUNCTION public.rpc_hg_create_table(p_game_id uuid, p_game_type text, p_stakes text, p_format text, p_buyin_min integer, p_buyin_max integer, p_max_seats integer, p_name text) OWNER TO postgres;

--
-- Name: rpc_hg_create_tournament(uuid, text, integer, integer, text, date, time without time zone, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_create_tournament(p_group_id uuid, p_name text, p_buy_in integer, p_starting_stack integer, p_structure text, p_scheduled_date date, p_scheduled_time time without time zone, p_entries_cap integer DEFAULT NULL::integer, p_description text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_address_visible_to text DEFAULT 'rsvp'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller     uuid := auth.uid();
  v_clean_name text;
  v_game_id    uuid;
  v_is_active  boolean;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  v_clean_name := NULLIF(trim(p_name), '');
  IF v_clean_name IS NULL                   THEN RAISE EXCEPTION 'NAME_REQUIRED'; END IF;
  IF char_length(v_clean_name) > 120        THEN RAISE EXCEPTION 'NAME_TOO_LONG'; END IF;

  IF p_buy_in IS NULL OR p_buy_in < 0       THEN RAISE EXCEPTION 'INVALID_BUY_IN'; END IF;
  IF p_buy_in > 1000000                     THEN RAISE EXCEPTION 'BUY_IN_TOO_LARGE'; END IF;

  IF p_starting_stack IS NOT NULL
     AND (p_starting_stack < 0 OR p_starting_stack > 100000000) THEN
    RAISE EXCEPTION 'INVALID_STARTING_STACK';
  END IF;

  IF p_structure IS NOT NULL
     AND p_structure NOT IN ('turbo','standard','deep','bounty','rebuy') THEN
    RAISE EXCEPTION 'INVALID_STRUCTURE';
  END IF;

  IF p_scheduled_date IS NULL OR p_scheduled_time IS NULL THEN
    RAISE EXCEPTION 'SCHEDULE_REQUIRED';
  END IF;
  IF p_scheduled_date < CURRENT_DATE THEN
    RAISE EXCEPTION 'PAST_DATE';
  END IF;

  IF p_entries_cap IS NOT NULL AND (p_entries_cap < 2 OR p_entries_cap > 10000) THEN
    RAISE EXCEPTION 'INVALID_ENTRIES_CAP';
  END IF;

  IF p_address_visible_to NOT IN ('public','rsvp','members') THEN
    RAISE EXCEPTION 'INVALID_ADDRESS_VISIBILITY';
  END IF;

  SELECT is_active INTO v_is_active
    FROM commander_home_groups WHERE id = p_group_id;
  IF NOT FOUND      THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;
  IF NOT v_is_active THEN RAISE EXCEPTION 'GROUP_NOT_ACTIVE'; END IF;

  IF NOT public.fn_home_is_group_staff(v_caller, p_group_id) THEN
    RAISE EXCEPTION 'NOT_GROUP_STAFF';
  END IF;

  INSERT INTO commander_home_games (
    group_id, host_id, title, description,
    format, game_type,
    buyin_min, buyin_max, starting_stack, structure,
    scheduled_date, start_time,
    max_players, status,
    address, address_visible_to
  ) VALUES (
    p_group_id, v_caller, v_clean_name, NULLIF(trim(p_description), ''),
    'tournament', 'nlhe',
    p_buy_in, p_buy_in, p_starting_stack, p_structure,
    p_scheduled_date, p_scheduled_time,
    p_entries_cap, 'scheduled',
    NULLIF(trim(p_address), ''), p_address_visible_to
  ) RETURNING id INTO v_game_id;

  INSERT INTO commander_home_audit_log
    (group_id, actor_id, target_type, target_id, action, metadata)
  VALUES (
    p_group_id, v_caller, 'tournament', v_game_id, 'created',
    jsonb_build_object(
      'name', v_clean_name, 'buy_in', p_buy_in,
      'starting_stack', p_starting_stack, 'structure', p_structure,
      'date', p_scheduled_date, 'time', p_scheduled_time,
      'entries_cap', p_entries_cap
    )
  );

  RETURN v_game_id;
END;
$$;


ALTER FUNCTION public.rpc_hg_create_tournament(p_group_id uuid, p_name text, p_buy_in integer, p_starting_stack integer, p_structure text, p_scheduled_date date, p_scheduled_time time without time zone, p_entries_cap integer, p_description text, p_address text, p_address_visible_to text) OWNER TO postgres;

--
-- Name: rpc_hg_host_add_roster_member(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_host_add_roster_member(p_group_id uuid, p_display_name text, p_phone text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_member_id uuid;
  v_clean_name text;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  v_clean_name := NULLIF(trim(p_display_name), '');
  IF v_clean_name IS NULL OR char_length(v_clean_name) > 120 THEN
    RAISE EXCEPTION 'DISPLAY_NAME_INVALID';
  END IF;

  IF NOT public.fn_home_is_group_staff(v_user_id, p_group_id)
     AND NOT EXISTS (SELECT 1 FROM public.commander_home_groups
                      WHERE id = p_group_id AND owner_id = v_user_id)
  THEN
    RAISE EXCEPTION 'NOT_GROUP_STAFF';
  END IF;

  -- De-dupe by name within the group's roster (idempotent add)
  SELECT id INTO v_member_id
    FROM public.commander_home_members
   WHERE group_id = p_group_id
     AND is_roster_only = true
     AND lower(display_name) = lower(v_clean_name)
   LIMIT 1;

  IF v_member_id IS NOT NULL THEN
    -- Update phone if newly provided
    IF p_phone IS NOT NULL THEN
      UPDATE public.commander_home_members SET phone = p_phone WHERE id = v_member_id;
    END IF;
    RETURN v_member_id;
  END IF;

  INSERT INTO public.commander_home_members
    (group_id, user_id, display_name, phone, role, status,
     is_roster_only, added_by_user_id, joined_at)
  VALUES
    (p_group_id, NULL, v_clean_name, p_phone, 'member', 'approved',
     true, v_user_id, now())
  RETURNING id INTO v_member_id;

  RETURN v_member_id;
END $$;


ALTER FUNCTION public.rpc_hg_host_add_roster_member(p_group_id uuid, p_display_name text, p_phone text) OWNER TO postgres;

--
-- Name: rpc_hg_host_claim_for_member(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_host_claim_for_member(p_table_id uuid, p_seat_number integer, p_member_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_table record;
  v_member record;
  v_reservation_id uuid;
  v_name_for_guest text;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  SELECT t.id, t.game_id, t.status, t.max_seats, g.group_id, h.owner_id
    INTO v_table
    FROM public.commander_home_game_tables t
    JOIN public.commander_home_games g ON g.id = t.game_id
    JOIN public.commander_home_groups h ON h.id = g.group_id
   WHERE t.id = p_table_id
   FOR UPDATE OF t, h;
  IF v_table.id IS NULL THEN RAISE EXCEPTION 'TABLE_NOT_FOUND'; END IF;
  IF v_table.status NOT IN ('open_for_rsvp', 'running') THEN
    RAISE EXCEPTION 'TABLE_NOT_CLAIMABLE';
  END IF;
  IF p_seat_number < 1 OR p_seat_number > v_table.max_seats THEN
    RAISE EXCEPTION 'SEAT_OUT_OF_BOUNDS';
  END IF;

  IF NOT public.fn_home_is_group_staff(v_user_id, v_table.group_id)
     AND v_table.owner_id <> v_user_id THEN
    RAISE EXCEPTION 'NOT_GROUP_STAFF';
  END IF;

  SELECT id, group_id, user_id, display_name, is_roster_only, status
    INTO v_member
    FROM public.commander_home_members
   WHERE id = p_member_id
   FOR UPDATE;
  IF v_member.id IS NULL THEN RAISE EXCEPTION 'MEMBER_NOT_FOUND'; END IF;
  IF v_member.group_id <> v_table.group_id THEN
    RAISE EXCEPTION 'MEMBER_WRONG_GROUP';
  END IF;
  IF v_member.status IS DISTINCT FROM 'approved' THEN
    RAISE EXCEPTION 'MEMBER_NOT_APPROVED'
      USING ERRCODE = '42501',
            HINT = 'current membership status is ' || coalesce(v_member.status, 'NULL');
  END IF;

  IF coalesce(v_member.is_roster_only, false) THEN
    IF v_member.user_id IS NOT NULL THEN
      RAISE EXCEPTION 'ROSTER_MEMBER_IDENTITY_INVALID';
    END IF;

    v_name_for_guest := v_member.display_name;
    INSERT INTO public.commander_home_seat_reservations
      (table_id, seat_number, user_id, member_id, guest_name,
       is_guest, claimed_by_user_id, status)
    VALUES (p_table_id, p_seat_number, NULL, p_member_id, v_name_for_guest,
            false, v_user_id, 'reserved')
    RETURNING id INTO v_reservation_id;
  ELSE
    IF v_member.user_id IS NULL THEN
      RAISE EXCEPTION 'REGISTERED_MEMBER_IDENTITY_REQUIRED';
    END IF;

    INSERT INTO public.commander_home_seat_reservations
      (table_id, seat_number, user_id, member_id,
       is_guest, claimed_by_user_id, status)
    VALUES (p_table_id, p_seat_number, v_member.user_id, p_member_id,
            false, v_user_id, 'reserved')
    RETURNING id INTO v_reservation_id;

    INSERT INTO public.commander_home_rsvps
      (game_id, user_id, response, seat_number, is_confirmed, responded_at)
    VALUES (v_table.game_id, v_member.user_id, 'yes', p_seat_number, true, now())
    ON CONFLICT (game_id, user_id) DO UPDATE
      SET response = 'yes', seat_number = EXCLUDED.seat_number,
          is_confirmed = true, responded_at = now(), updated_at = now();
  END IF;

  RETURN v_reservation_id;
END;
$$;


ALTER FUNCTION public.rpc_hg_host_claim_for_member(p_table_id uuid, p_seat_number integer, p_member_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION rpc_hg_host_claim_for_member(p_table_id uuid, p_seat_number integer, p_member_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rpc_hg_host_claim_for_member(p_table_id uuid, p_seat_number integer, p_member_id uuid) IS 'Host seat claim for one approved Home Games member. Locks membership state before atomically creating a reservation and, for registered members, an RSVP.';


--
-- Name: rpc_hg_list_public_tournaments(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_list_public_tournaments(p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  -- Group must exist and be active
  IF NOT EXISTS (
    SELECT 1 FROM commander_home_groups
    WHERE id = p_group_id AND is_active = true
  ) THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(sub.j ORDER BY sub.scheduled_date, sub.start_time), '[]'::jsonb) INTO v_result
  FROM (
    SELECT
      jsonb_build_object(
        'id', g.id,
        'name', g.title,
        'description', g.description,
        'buy_in', g.buyin_min,
        'starting_stack', g.starting_stack,
        'structure', g.structure,
        'scheduled_date', g.scheduled_date,
        'start_time', g.start_time,
        'entries_cap', g.max_players,
        'rsvp_yes', g.rsvp_yes,
        'address', CASE WHEN g.address_visible_to = 'public' THEN g.address ELSE NULL END,
        'neighborhood', g.neighborhood,
        'scheduled_at_iso',
          (g.scheduled_date::text || 'T' || to_char(g.start_time, 'HH24:MI:SS') || 'Z')
      ) AS j,
      g.scheduled_date,
      g.start_time
    FROM commander_home_games g
    WHERE g.group_id = p_group_id
      AND g.format = 'tournament'
      AND g.status = 'scheduled'
      AND g.scheduled_date >= CURRENT_DATE
  ) sub;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.rpc_hg_list_public_tournaments(p_group_id uuid) OWNER TO postgres;

--
-- Name: rpc_hg_list_roster(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_list_roster(p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_result  jsonb;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  IF NOT public.fn_home_is_group_staff(v_user_id, p_group_id)
     AND NOT EXISTS (SELECT 1 FROM public.commander_home_groups
                      WHERE id = p_group_id AND owner_id = v_user_id)
  THEN
    RAISE EXCEPTION 'NOT_GROUP_STAFF';
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', m.id,
      'user_id', m.user_id,
      'is_roster_only', m.is_roster_only,
      'display_name', COALESCE(
        m.display_name,
        public.fn_hg_caller_display_name(m.user_id),
        'Member'
      ),
      'phone', m.phone,
      'games_attended', m.games_attended,
      'last_attended', m.last_attended
    ) ORDER BY
      -- roster-only first? no - users first (most commonly seated), then roster by name
      CASE WHEN m.is_roster_only THEN 1 ELSE 0 END,
      COALESCE(m.display_name, public.fn_hg_caller_display_name(m.user_id), 'Member')
  ), '[]'::jsonb) INTO v_result
  FROM public.commander_home_members m
  WHERE m.group_id = p_group_id AND m.status = 'approved';

  RETURN v_result;
END $$;


ALTER FUNCTION public.rpc_hg_list_roster(p_group_id uuid) OWNER TO postgres;

--
-- Name: rpc_hg_list_tables_and_reservations(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_list_tables_and_reservations(p_game_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_group_id uuid;
  v_is_member boolean;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;

  SELECT group_id INTO v_group_id FROM public.commander_home_games WHERE id = p_game_id;
  IF v_group_id IS NULL THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.commander_home_members
     WHERE group_id = v_group_id AND user_id = auth.uid() AND status = 'approved'
  ) OR EXISTS (
    SELECT 1 FROM public.commander_home_groups
     WHERE id = v_group_id AND owner_id = auth.uid()
  ) OR EXISTS (
    SELECT 1 FROM public.commander_home_group_follows
     WHERE group_id = v_group_id AND user_id = auth.uid()
  ) INTO v_is_member;

  IF NOT v_is_member THEN RAISE EXCEPTION 'NOT_A_MEMBER'; END IF;

  SELECT jsonb_build_object(
    'game_id', p_game_id,
    'tables', COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', t.id,
        'table_number', t.table_number,
        'name', t.name,
        'game_type', t.game_type,
        'stakes', t.stakes,
        'format', t.format,
        'buyin_min', t.buyin_min,
        'buyin_max', t.buyin_max,
        'max_seats', t.max_seats,
        'status', t.status,
        'is_default', t.is_default,
        'started_at', t.started_at,
        'ended_at', t.ended_at,
        'reservations', (
          SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
              'id', r.id,
              'seat_number', r.seat_number,
              'user_id', r.user_id,
              'member_id', r.member_id,
              'is_guest', r.is_guest,
              'guest_name', r.guest_name,
              'status', r.status,
              'claimed_by_user_id', r.claimed_by_user_id,
              'claimed_at', r.claimed_at,
              'display_name', COALESCE(
                r.guest_name,
                public.fn_hg_caller_display_name(r.user_id),
                'Player'
              ),
              'is_self', (r.user_id = auth.uid() OR r.claimed_by_user_id = auth.uid())
            ) ORDER BY r.seat_number
          ), '[]'::jsonb)
          FROM public.commander_home_seat_reservations r
          WHERE r.table_id = t.id AND r.status IN ('reserved','seated')
        )
      ) ORDER BY t.table_number
    ), '[]'::jsonb)
  ) INTO v_result
  FROM public.commander_home_game_tables t
  WHERE t.game_id = p_game_id;

  RETURN v_result;
END $$;


ALTER FUNCTION public.rpc_hg_list_tables_and_reservations(p_game_id uuid) OWNER TO postgres;

--
-- Name: rpc_hg_list_tournaments(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_list_tournaments(p_group_id uuid, p_include_past boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF NOT public.fn_home_is_group_staff(v_caller, p_group_id) THEN
    RAISE EXCEPTION 'NOT_GROUP_STAFF';
  END IF;

  SELECT COALESCE(jsonb_agg(sub.j ORDER BY sub.scheduled_date, sub.start_time), '[]'::jsonb) INTO v_result
  FROM (
    SELECT
      jsonb_build_object(
        'id', g.id,
        'group_id', g.group_id,
        'name', g.title,
        'description', g.description,
        'buy_in', g.buyin_min,
        'starting_stack', g.starting_stack,
        'structure', g.structure,
        'scheduled_date', g.scheduled_date,
        'start_time', g.start_time,
        'entries_cap', g.max_players,
        'status', g.status,
        'rsvp_yes', g.rsvp_yes,
        'rsvp_maybe', g.rsvp_maybe,
        'created_at', g.created_at,
        'cancelled_at', g.cancelled_at,
        'cancellation_reason', g.cancellation_reason,
        'scheduled_at_iso',
          (g.scheduled_date::text || 'T' || to_char(g.start_time, 'HH24:MI:SS') || 'Z')
      ) AS j,
      g.scheduled_date,
      g.start_time
    FROM commander_home_games g
    WHERE g.group_id = p_group_id
      AND g.format = 'tournament'
      AND (p_include_past OR g.scheduled_date >= CURRENT_DATE)
  ) sub;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.rpc_hg_list_tournaments(p_group_id uuid, p_include_past boolean) OWNER TO postgres;

--
-- Name: rpc_hg_release_seat(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_release_seat(p_reservation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id       uuid := auth.uid();
  v_res           RECORD;
  v_fallback_seat integer;
  v_updated_count int;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  SELECT r.*, t.game_id, t.status AS table_status
    INTO v_res
    FROM public.commander_home_seat_reservations r
    JOIN public.commander_home_game_tables t ON t.id = r.table_id
   WHERE r.id = p_reservation_id;
  IF v_res.id IS NULL THEN RAISE EXCEPTION 'RESERVATION_NOT_FOUND'; END IF;

  IF v_res.user_id IS DISTINCT FROM v_user_id
     AND v_res.claimed_by_user_id IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'NOT_YOUR_RESERVATION';
  END IF;

  IF v_res.status NOT IN ('reserved','seated') THEN
    RAISE EXCEPTION 'RESERVATION_ALREADY_INACTIVE' USING HINT = v_res.status;
  END IF;

  -- BUG-4 fix: status-guarded UPDATE (TOCTOU-safe).
  UPDATE public.commander_home_seat_reservations
     SET status = 'released', released_at = now()
   WHERE id = p_reservation_id
     AND status IN ('reserved','seated');
  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count = 0 THEN
    RAISE EXCEPTION 'RESERVATION_ALREADY_INACTIVE'
      USING HINT = 'reservation was just released by another path';
  END IF;

  -- BUG-1 fix: if table is running (reservation was 'seated'), the
  -- live seat must also be cleared or the Commander tablet view shows
  -- the released player still at the table.
  IF v_res.status = 'seated' THEN
    DELETE FROM public.commander_home_seats
     WHERE reservation_id = p_reservation_id;
  END IF;

  -- Shadow-write only for real-user (non-guest) seats.
  IF v_res.is_guest = false AND v_res.user_id IS NOT NULL THEN
    SELECT r2.seat_number
      INTO v_fallback_seat
      FROM public.commander_home_seat_reservations r2
      JOIN public.commander_home_game_tables t2 ON t2.id = r2.table_id
     WHERE t2.game_id = v_res.game_id
       AND r2.user_id = v_res.user_id
       AND r2.status IN ('reserved','seated')
       AND r2.id <> p_reservation_id
     ORDER BY r2.created_at ASC
     LIMIT 1;

    IF v_fallback_seat IS NOT NULL THEN
      UPDATE public.commander_home_rsvps
         SET seat_number = v_fallback_seat,
             updated_at  = now()
       WHERE game_id = v_res.game_id
         AND user_id = v_res.user_id;
    ELSE
      UPDATE public.commander_home_rsvps
         SET response     = 'no',
             seat_number  = NULL,
             updated_at   = now()
       WHERE game_id = v_res.game_id
         AND user_id = v_res.user_id;
    END IF;
  END IF;
END $$;


ALTER FUNCTION public.rpc_hg_release_seat(p_reservation_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION rpc_hg_release_seat(p_reservation_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rpc_hg_release_seat(p_reservation_id uuid) IS 'Phase B Pass: BUG-1 + BUG-4 fix. Status-guarded UPDATE prevents TOCTOU double-release. If reservation was in status=seated (table running), the corresponding commander_home_seats row is DELETEd so the Commander tablet view reflects the release immediately.';


--
-- Name: rpc_hg_start_table(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_start_table(p_table_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_table   RECORD;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  -- BUG-3: lock the table row so concurrent starts serialize.
  SELECT t.id, t.status, t.game_id, g.group_id, g.host_id
    INTO v_table
    FROM public.commander_home_game_tables t
    JOIN public.commander_home_games g ON g.id = t.game_id
   WHERE t.id = p_table_id
   FOR UPDATE OF t;
  IF v_table.id IS NULL THEN RAISE EXCEPTION 'TABLE_NOT_FOUND'; END IF;

  IF NOT public.fn_home_is_group_staff(v_user_id, v_table.group_id)
     AND v_table.host_id <> v_user_id
     AND NOT EXISTS (SELECT 1 FROM public.commander_home_groups
                      WHERE id = v_table.group_id AND owner_id = v_user_id)
  THEN
    RAISE EXCEPTION 'NOT_GROUP_STAFF';
  END IF;

  IF v_table.status <> 'open_for_rsvp' THEN
    RAISE EXCEPTION 'TABLE_NOT_IN_OPEN_STATE' USING HINT = v_table.status;
  END IF;

  -- BUG-3: status-guarded UPDATE. Belt-and-suspenders with FOR UPDATE.
  UPDATE public.commander_home_game_tables
     SET status = 'running', started_at = now()
   WHERE id = p_table_id
     AND status = 'open_for_rsvp';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_STATE_CHANGED'
      USING HINT = 'another caller transitioned the table first';
  END IF;

  INSERT INTO public.commander_home_seats
    (game_id, table_id, seat_number, user_id, player_name,
     status, seated_at, reservation_id)
  SELECT
    v_table.game_id,
    r.table_id,
    r.seat_number,
    r.user_id,
    COALESCE(
      LEFT(r.guest_name, 120),
      LEFT(public.fn_hg_caller_display_name(r.user_id), 120),
      'Player'
    ),
    'seated',
    now(),
    r.id
  FROM public.commander_home_seat_reservations r
  WHERE r.table_id = p_table_id AND r.status = 'reserved';

  UPDATE public.commander_home_seat_reservations
     SET status = 'seated', seated_at = now()
   WHERE table_id = p_table_id AND status = 'reserved';
END $$;


ALTER FUNCTION public.rpc_hg_start_table(p_table_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION rpc_hg_start_table(p_table_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rpc_hg_start_table(p_table_id uuid) IS 'Phase B Pass: BUG-3 fix — added FOR UPDATE row lock on the table SELECT + status-guarded UPDATE to serialize concurrent "Start" clicks. Player name hydration also LEFT-truncated to 120 chars to prevent chk_seat_player_name_len violations on edge-case long display names.';


--
-- Name: rpc_hg_update_tournament(uuid, text, integer, integer, text, date, time without time zone, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_hg_update_tournament(p_tournament_id uuid, p_name text DEFAULT NULL::text, p_buy_in integer DEFAULT NULL::integer, p_starting_stack integer DEFAULT NULL::integer, p_structure text DEFAULT NULL::text, p_scheduled_date date DEFAULT NULL::date, p_scheduled_time time without time zone DEFAULT NULL::time without time zone, p_entries_cap integer DEFAULT NULL::integer, p_description text DEFAULT NULL::text, p_clear_entries_cap boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller   uuid := auth.uid();
  v_game     RECORD;
  v_changes  jsonb := '{}'::jsonb;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  SELECT * INTO v_game FROM commander_home_games WHERE id = p_tournament_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'TOURNAMENT_NOT_FOUND'; END IF;
  IF v_game.format <> 'tournament' THEN RAISE EXCEPTION 'NOT_A_TOURNAMENT'; END IF;
  IF v_game.status IN ('completed','cancelled','in_progress') THEN
    RAISE EXCEPTION 'TOURNAMENT_FINAL' USING HINT = 'cannot edit a tournament with status ' || v_game.status;
  END IF;

  IF NOT public.fn_home_is_group_staff(v_caller, v_game.group_id) THEN
    RAISE EXCEPTION 'NOT_GROUP_STAFF';
  END IF;

  -- Field-by-field validation + apply
  IF p_name IS NOT NULL THEN
    p_name := trim(p_name);
    IF char_length(p_name) = 0 OR char_length(p_name) > 120 THEN
      RAISE EXCEPTION 'INVALID_NAME';
    END IF;
    v_changes := v_changes || jsonb_build_object('name', p_name);
  END IF;

  IF p_buy_in IS NOT NULL THEN
    IF p_buy_in < 0 OR p_buy_in > 1000000 THEN RAISE EXCEPTION 'INVALID_BUY_IN'; END IF;
    v_changes := v_changes || jsonb_build_object('buy_in', p_buy_in);
  END IF;

  IF p_starting_stack IS NOT NULL THEN
    IF p_starting_stack < 0 OR p_starting_stack > 100000000 THEN
      RAISE EXCEPTION 'INVALID_STARTING_STACK';
    END IF;
    v_changes := v_changes || jsonb_build_object('starting_stack', p_starting_stack);
  END IF;

  IF p_structure IS NOT NULL THEN
    IF p_structure NOT IN ('turbo','standard','deep','bounty','rebuy') THEN
      RAISE EXCEPTION 'INVALID_STRUCTURE';
    END IF;
    v_changes := v_changes || jsonb_build_object('structure', p_structure);
  END IF;

  IF p_scheduled_date IS NOT NULL THEN
    IF p_scheduled_date < CURRENT_DATE THEN RAISE EXCEPTION 'PAST_DATE'; END IF;
    v_changes := v_changes || jsonb_build_object('scheduled_date', p_scheduled_date);
  END IF;

  IF p_scheduled_time IS NOT NULL THEN
    v_changes := v_changes || jsonb_build_object('scheduled_time', p_scheduled_time);
  END IF;

  IF p_entries_cap IS NOT NULL THEN
    IF p_entries_cap < 2 OR p_entries_cap > 10000 THEN RAISE EXCEPTION 'INVALID_ENTRIES_CAP'; END IF;
    v_changes := v_changes || jsonb_build_object('entries_cap', p_entries_cap);
  END IF;

  UPDATE commander_home_games SET
    title              = COALESCE(p_name,                title),
    description        = CASE WHEN p_description IS NOT NULL THEN NULLIF(trim(p_description),'') ELSE description END,
    buyin_min          = COALESCE(p_buy_in,              buyin_min),
    buyin_max          = COALESCE(p_buy_in,              buyin_max),
    starting_stack     = COALESCE(p_starting_stack,      starting_stack),
    structure          = COALESCE(p_structure,           structure),
    scheduled_date     = COALESCE(p_scheduled_date,      scheduled_date),
    start_time         = COALESCE(p_scheduled_time,      start_time),
    max_players        = CASE
      WHEN p_clear_entries_cap THEN NULL
      WHEN p_entries_cap IS NOT NULL THEN p_entries_cap
      ELSE max_players
    END,
    updated_at         = NOW()
   WHERE id = p_tournament_id;

  INSERT INTO commander_home_audit_log
    (group_id, actor_id, target_type, target_id, action, metadata)
  VALUES (
    v_game.group_id, v_caller, 'tournament', p_tournament_id, 'updated', v_changes
  );

  RETURN jsonb_build_object('success', true, 'tournament_id', p_tournament_id, 'changes', v_changes);
END;
$$;


ALTER FUNCTION public.rpc_hg_update_tournament(p_tournament_id uuid, p_name text, p_buy_in integer, p_starting_stack integer, p_structure text, p_scheduled_date date, p_scheduled_time time without time zone, p_entries_cap integer, p_description text, p_clear_entries_cap boolean) OWNER TO postgres;

--
-- Name: rpc_memory_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_memory_dashboard(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  this_week_start  timestamptz := date_trunc('week', now());
  last_week_start  timestamptz := date_trunc('week', now()) - interval '7 days';
  last_week_end    timestamptz := date_trunc('week', now());
  rolling_30_start timestamptz := now() - interval '30 days';

  this_sessions  int := 0;
  this_avg_acc   numeric := 0;
  this_diamonds  int := 0;
  last_sessions  int := 0;
  last_avg_acc   numeric := 0;

  rolling_avg_acc numeric := 0;
  rolling_n       int := 0;
  cur_grade       text;
  next_grade      text;

  -- Don't init these to 0 - SELECT INTO with no matching user_daily_streaks
  -- row would otherwise overwrite them to NULL. Keep typed but unset, then
  -- coalesce after the SELECT INTO below.
  cur_streak  int;
  best_streak int;
  total_days  int;

  per_mode    jsonb := '[]'::jsonb;
  per_level   jsonb := '[]'::jsonb;
  mastered_count int := 0;

  dc_row       record;
  dc_completed boolean := false;

  result jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id required';
  END IF;
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( auth.uid() <> p_user_id)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT
    coalesce(count(*), 0)::int,
    coalesce(avg(accuracy), 0)::numeric,
    coalesce(sum(diamonds_earned), 0)::int
  INTO this_sessions, this_avg_acc, this_diamonds
  FROM memory_game_sessions
  WHERE user_id = p_user_id
    AND created_at >= this_week_start;

  SELECT
    coalesce(count(*), 0)::int,
    coalesce(avg(accuracy), 0)::numeric
  INTO last_sessions, last_avg_acc
  FROM memory_game_sessions
  WHERE user_id = p_user_id
    AND created_at >= last_week_start
    AND created_at <  last_week_end;

  SELECT
    coalesce(avg(accuracy), 0)::numeric,
    coalesce(count(*), 0)::int
  INTO rolling_avg_acc, rolling_n
  FROM memory_game_sessions
  WHERE user_id = p_user_id
    AND created_at >= rolling_30_start;

  cur_grade := CASE
    WHEN rolling_avg_acc * 100 >= 95 THEN 'A+'
    WHEN rolling_avg_acc * 100 >= 90 THEN 'A'
    WHEN rolling_avg_acc * 100 >= 85 THEN 'B+'
    WHEN rolling_avg_acc * 100 >= 80 THEN 'B'
    WHEN rolling_avg_acc * 100 >= 75 THEN 'C+'
    WHEN rolling_avg_acc * 100 >= 70 THEN 'C'
    WHEN rolling_avg_acc * 100 >= 65 THEN 'D+'
    WHEN rolling_avg_acc * 100 >= 60 THEN 'D'
    ELSE 'F'
  END;
  next_grade := CASE
    WHEN rolling_avg_acc * 100 >= 95 THEN NULL
    WHEN rolling_avg_acc * 100 >= 90 THEN 'A+'
    WHEN rolling_avg_acc * 100 >= 85 THEN 'A'
    WHEN rolling_avg_acc * 100 >= 80 THEN 'B+'
    WHEN rolling_avg_acc * 100 >= 75 THEN 'B'
    WHEN rolling_avg_acc * 100 >= 70 THEN 'C+'
    WHEN rolling_avg_acc * 100 >= 65 THEN 'C'
    WHEN rolling_avg_acc * 100 >= 60 THEN 'D+'
    ELSE 'D'
  END;

  -- streak: SELECT INTO returns NULL when no matching row; coalesce after.
  SELECT
    uds.current_streak,
    uds.longest_streak,
    uds.total_days_played
  INTO cur_streak, best_streak, total_days
  FROM user_daily_streaks uds
  WHERE uds.user_id = p_user_id;

  cur_streak  := coalesce(cur_streak, 0);
  best_streak := coalesce(best_streak, 0);
  total_days  := coalesce(total_days, 0);

  WITH best_per_mode AS (
    SELECT
      game_mode,
      max(score)        AS best_score,
      max(accuracy)     AS best_accuracy,
      bool_or(perfect_game) AS has_perfect,
      max(created_at)   AS last_played
    FROM memory_leaderboards
    WHERE user_id = p_user_id
    GROUP BY game_mode
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'game_mode',     game_mode,
    'best_score',    best_score,
    'best_accuracy', round(best_accuracy * 100, 1),
    'has_perfect',   has_perfect,
    'last_played',   last_played
  ) ORDER BY best_score DESC), '[]'::jsonb)
  INTO per_mode
  FROM best_per_mode;

  WITH best_per_level AS (
    SELECT
      level,
      max(score)        AS best_score,
      max(accuracy)     AS best_accuracy,
      count(*)          AS attempts,
      max(created_at)   AS last_played
    FROM memory_leaderboards
    WHERE user_id = p_user_id
    GROUP BY level
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'level',         level,
    'best_score',    best_score,
    'best_accuracy', round(best_accuracy * 100, 1),
    'attempts',      attempts,
    'last_played',   last_played,
    'mastered',      best_accuracy >= 0.85
  ) ORDER BY level), '[]'::jsonb)
  INTO per_level
  FROM best_per_level;

  SELECT count(DISTINCT level)
  INTO mastered_count
  FROM memory_leaderboards
  WHERE user_id = p_user_id
    AND accuracy >= 0.85;

  SELECT *
  INTO dc_row
  FROM memory_daily_challenges
  WHERE challenge_date = current_date
  ORDER BY created_at DESC
  LIMIT 1;

  IF dc_row.id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM memory_challenge_completions
      WHERE user_id = p_user_id
        AND challenge_id = dc_row.id
    ) INTO dc_completed;
  END IF;

  result := jsonb_build_object(
    'sessions_this_week',         this_sessions,
    'avg_accuracy_this_week_pct', round(this_avg_acc * 100, 1),
    'diamonds_earned_this_week',  this_diamonds,
    'sessions_last_week',         last_sessions,
    'avg_accuracy_last_week_pct', round(last_avg_acc * 100, 1),
    'rolling_30d_sessions',       rolling_n,
    'rolling_accuracy_pct',       round(rolling_avg_acc * 100, 1),
    'current_grade',              cur_grade,
    'next_grade',                 next_grade,
    'current_streak_days',        cur_streak,
    'longest_streak_days',        best_streak,
    'total_days_played',          total_days,
    'per_mode_best',              per_mode,
    'per_level_mastery',          per_level,
    'mastered_levels_count',      coalesce(mastered_count, 0),
    'daily_challenge',            CASE WHEN dc_row.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id',              dc_row.id,
      'challenge_date',  dc_row.challenge_date,
      'game_mode',       dc_row.game_mode,
      'level',           dc_row.level,
      'scenario_id',     dc_row.scenario_id,
      'target_accuracy', dc_row.target_accuracy,
      'target_time',     dc_row.target_time,
      'diamond_reward',  dc_row.diamond_reward,
      'bonus_reward',    dc_row.bonus_reward
    ) END,
    'daily_challenge_completed',  dc_completed,
    'computed_at',                now()
  );

  RETURN result;
END;
$$;


ALTER FUNCTION public.rpc_memory_dashboard(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION rpc_memory_dashboard(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rpc_memory_dashboard(p_user_id uuid) IS 'Aggregated dashboard payload for /hub/memory-games (preflop charts) landing surface. Returns this/last week + rolling 30d grade + streak + per-mode best + per-level mastery + today daily challenge state. Read-only. Used by /api/memory/dashboard.';


--
-- Name: rpc_training_weekly_stats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_training_weekly_stats(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  this_week_start timestamptz := date_trunc('week', now());
  last_week_start timestamptz := date_trunc('week', now()) - interval '7 days';
  last_week_end timestamptz := date_trunc('week', now());
  rolling_30_start timestamptz := now() - interval '30 days';

  this_hands_played integer := 0;
  this_correct_count integer := 0;
  this_total_answers integer := 0;
  this_ev_loss numeric := 0;
  last_hands_played integer := 0;
  last_correct_count integer := 0;
  last_total_answers integer := 0;
  last_ev_loss numeric := 0;
  cur_streak_days integer := 0;
  best_streak_days integer := 0;
  rolling_correct integer := 0;
  rolling_total integer := 0;
  rolling_accuracy numeric := 0;
  cur_grade text;
  next_grade text;
  next_grade_floor numeric;
  delta_correct integer;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id required';
  END IF;

  -- A JWT-bearing browser can request only itself. The service-role API client
  -- remains compatible through the established engine-caller guard; a NULL
  -- auth.uid() alone is never treated as sufficient browser authorization.
  IF NOT public.fn_caller_is_engine()
     AND ((SELECT auth.uid()) IS NULL OR (SELECT auth.uid()) <> p_user_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- training_sessions is an analytics projection, not independent grading
  -- truth. Every aggregate row must bind to its same-user completed attempt,
  -- and replay/practice attempts must never influence Hub performance.
  SELECT
    coalesce(sum(attempt.answered_hands) FILTER (
      WHERE attempt.completed_at >= this_week_start
    ), 0)::integer,
    coalesce(sum(attempt.correct_hands) FILTER (
      WHERE attempt.completed_at >= this_week_start
    ), 0)::integer,
    coalesce(sum(attempt.answered_hands) FILTER (
      WHERE attempt.completed_at >= this_week_start
    ), 0)::integer,
    coalesce(sum(session.total_ev_loss) FILTER (
      WHERE attempt.completed_at >= this_week_start
    ), 0)::numeric,
    coalesce(sum(attempt.answered_hands) FILTER (
      WHERE attempt.completed_at >= last_week_start
        AND attempt.completed_at < last_week_end
    ), 0)::integer,
    coalesce(sum(attempt.correct_hands) FILTER (
      WHERE attempt.completed_at >= last_week_start
        AND attempt.completed_at < last_week_end
    ), 0)::integer,
    coalesce(sum(attempt.answered_hands) FILTER (
      WHERE attempt.completed_at >= last_week_start
        AND attempt.completed_at < last_week_end
    ), 0)::integer,
    coalesce(sum(session.total_ev_loss) FILTER (
      WHERE attempt.completed_at >= last_week_start
        AND attempt.completed_at < last_week_end
    ), 0)::numeric,
    coalesce(sum(attempt.correct_hands) FILTER (
      WHERE attempt.completed_at >= rolling_30_start
    ), 0)::integer,
    coalesce(sum(attempt.answered_hands) FILTER (
      WHERE attempt.completed_at >= rolling_30_start
    ), 0)::integer
  INTO
    this_hands_played,
    this_correct_count,
    this_total_answers,
    this_ev_loss,
    last_hands_played,
    last_correct_count,
    last_total_answers,
    last_ev_loss,
    rolling_correct,
    rolling_total
  FROM public.training_sessions session
  JOIN public.training_attempts attempt
    ON attempt.id = session.attempt_id
   AND attempt.user_id = session.user_id
  WHERE attempt.user_id = p_user_id
    AND attempt.status = 'completed'
    AND attempt.practice_only IS FALSE
    AND attempt.completed_at IS NOT NULL;

  -- Use only the post-cutover server-authority streak columns. The legacy
  -- columns intentionally remain display snapshots and cannot drive this API.
  SELECT
    coalesce(max(streak.authority_current_streak), 0)::integer,
    coalesce(max(streak.authority_longest_streak), 0)::integer
  INTO cur_streak_days, best_streak_days
  FROM public.training_streaks streak
  WHERE streak.user_id = p_user_id;

  rolling_accuracy := CASE
    WHEN rolling_total > 0
      THEN (rolling_correct::numeric / rolling_total) * 100.0
    ELSE 0
  END;

  cur_grade := CASE
    WHEN rolling_accuracy >= 95 THEN 'A+'
    WHEN rolling_accuracy >= 90 THEN 'A'
    WHEN rolling_accuracy >= 85 THEN 'B+'
    WHEN rolling_accuracy >= 80 THEN 'B'
    WHEN rolling_accuracy >= 75 THEN 'C+'
    WHEN rolling_accuracy >= 70 THEN 'C'
    WHEN rolling_accuracy >= 65 THEN 'D+'
    WHEN rolling_accuracy >= 60 THEN 'D'
    ELSE 'F'
  END;

  next_grade := CASE
    WHEN rolling_accuracy >= 95 THEN NULL
    WHEN rolling_accuracy >= 90 THEN 'A+'
    WHEN rolling_accuracy >= 85 THEN 'A'
    WHEN rolling_accuracy >= 80 THEN 'B+'
    WHEN rolling_accuracy >= 75 THEN 'B'
    WHEN rolling_accuracy >= 70 THEN 'C+'
    WHEN rolling_accuracy >= 65 THEN 'C'
    WHEN rolling_accuracy >= 60 THEN 'D+'
    ELSE 'D'
  END;

  next_grade_floor := CASE
    WHEN rolling_accuracy >= 95 THEN NULL
    WHEN rolling_accuracy >= 90 THEN 95
    WHEN rolling_accuracy >= 85 THEN 90
    WHEN rolling_accuracy >= 80 THEN 85
    WHEN rolling_accuracy >= 75 THEN 80
    WHEN rolling_accuracy >= 70 THEN 75
    WHEN rolling_accuracy >= 65 THEN 70
    WHEN rolling_accuracy >= 60 THEN 65
    ELSE 60
  END;

  delta_correct := CASE
    WHEN next_grade_floor IS NULL OR rolling_total <= 0 THEN NULL
    ELSE greatest(
      ceil((next_grade_floor / 100.0) * rolling_total - rolling_correct)::integer,
      1
    )
  END;

  RETURN jsonb_build_object(
    'hands_this_week', this_hands_played,
    'correct_this_week', this_correct_count,
    'total_this_week', this_total_answers,
    'ev_loss_this_week', this_ev_loss,
    'accuracy_this_week_pct', CASE WHEN this_total_answers > 0
      THEN round(this_correct_count::numeric / this_total_answers * 100, 1)
      ELSE 0 END,
    'ev_saved_this_week_bb', round(-this_ev_loss, 1),
    'hands_last_week', last_hands_played,
    'correct_last_week', last_correct_count,
    'total_last_week', last_total_answers,
    'ev_loss_last_week', last_ev_loss,
    'accuracy_last_week_pct', CASE WHEN last_total_answers > 0
      THEN round(last_correct_count::numeric / last_total_answers * 100, 1)
      ELSE 0 END,
    'ev_saved_last_week_bb', round(-last_ev_loss, 1),
    'current_streak_days', cur_streak_days,
    'personal_best_streak_days', best_streak_days,
    'rolling_accuracy_pct', round(rolling_accuracy, 1),
    'rolling_correct', rolling_correct,
    'rolling_total', rolling_total,
    'current_grade', cur_grade,
    'next_grade', next_grade,
    'delta_correct_to_next', delta_correct,
    'window_this_week_start', this_week_start,
    'window_last_week_start', last_week_start,
    'computed_at', now()
  );
END;
$$;


ALTER FUNCTION public.rpc_training_weekly_stats(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION rpc_training_weekly_stats(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rpc_training_weekly_stats(p_user_id uuid) IS 'Self-only weekly Training Hub projection. Aggregates only same-user completed, non-practice server attempts and server-authority streak columns.';


--
-- Name: rsvp_to_home_game(uuid, text, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rsvp_to_home_game(p_game_id uuid, p_response text, p_caller_user_id uuid, p_bringing_guests integer DEFAULT 0, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_game RECORD; v_group RECORD; v_host_profile RECORD;
    v_is_member boolean := false; v_is_banned boolean := false;
    v_rsvp_id uuid; v_updated_game RECORD;
    v_game_start_ts timestamptz; v_effective_tz text;
    v_dm_result jsonb; v_conv_id uuid;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED'
              USING HINT = 'rsvp_to_home_game requires auth.uid() = p_caller_user_id';
    END IF;
    IF p_response NOT IN ('yes','maybe','no','waitlist') THEN
        RAISE EXCEPTION 'INVALID_RESPONSE'
              USING HINT = 'response must be one of: yes, maybe, no, waitlist';
    END IF;
    IF p_message IS NOT NULL AND length(p_message) > 500 THEN
        RAISE EXCEPTION 'MESSAGE_TOO_LONG' USING HINT = 'max 500 chars';
    END IF;
    IF p_bringing_guests IS NULL OR p_bringing_guests < 0 THEN p_bringing_guests := 0; END IF;

    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
    IF v_game.status = 'cancelled' THEN
      RAISE EXCEPTION 'GAME_NOT_OPEN_FOR_RSVP' USING HINT = 'game status is cancelled';
    END IF;
    IF v_game.status NOT IN ('scheduled','confirmed','in_progress','completed') THEN
        RAISE EXCEPTION 'GAME_NOT_OPEN_FOR_RSVP'
              USING HINT = 'game status is ' || COALESCE(v_game.status,'NULL');
    END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;

    SELECT EXISTS (SELECT 1 FROM commander_home_members
       WHERE group_id = v_game.group_id AND user_id = p_caller_user_id AND status = 'banned')
     INTO v_is_banned;
    IF v_is_banned THEN RAISE EXCEPTION 'BANNED'; END IF;

    SELECT EXISTS (SELECT 1 FROM commander_home_groups
         WHERE id = v_game.group_id AND owner_id = p_caller_user_id)
    OR EXISTS (SELECT 1 FROM commander_home_members
         WHERE group_id = v_game.group_id AND user_id = p_caller_user_id AND status = 'approved')
     INTO v_is_member;

    IF v_group.is_private AND NOT v_is_member THEN
        RAISE EXCEPTION 'NOT_A_MEMBER'
              USING HINT = 'private group RSVP requires approved membership';
    END IF;

    v_effective_tz := COALESCE(
                        NULLIF(v_game.timezone, ''),
                        NULLIF(v_group.timezone, ''),
                        'America/New_York');
    v_game_start_ts := (v_game.scheduled_date + v_game.start_time) AT TIME ZONE v_effective_tz;

    IF v_game.status = 'completed' OR v_game.status = 'in_progress'
       OR v_game_start_ts <= NOW()
    THEN
        IF p_caller_user_id = v_game.host_id THEN
            RAISE EXCEPTION 'HOST_CANNOT_RSVP_TO_OWN_GAME';
        END IF;
        v_dm_result := public.fn_get_or_create_conversation(
            p_caller_user_id, v_game.host_id, 'direct');
        IF COALESCE((v_dm_result->>'success')::boolean, false) THEN
            v_conv_id := (v_dm_result->>'conversation_id')::uuid;
        ELSE v_conv_id := NULL; END IF;

        SELECT p.id, p.username, p.display_name, p.full_name, p.avatar_url
          INTO v_host_profile FROM profiles p WHERE p.id = v_game.host_id;

        RETURN jsonb_build_object(
            'success', false, 'error', 'GAME_STARTED',
            'message', 'This game has already started. Message the host directly.',
            'game', jsonb_build_object(
                'id', v_game.id, 'scheduled_date', v_game.scheduled_date,
                'start_time', v_game.start_time, 'timezone', v_effective_tz,
                'status', v_game.status),
            'host', jsonb_build_object(
                'id', v_host_profile.id, 'username', v_host_profile.username,
                'display_name', COALESCE(v_host_profile.display_name,
                                         v_host_profile.full_name, v_host_profile.username),
                'avatar_url', v_host_profile.avatar_url),
            'conversation_id', v_conv_id,
            'dm_url', CASE WHEN v_conv_id IS NOT NULL
                           THEN '/hub/messenger/' || v_conv_id::text
                           ELSE NULL END);
    END IF;

    IF NOT v_game.allow_guests AND p_bringing_guests > 0 THEN
        RAISE EXCEPTION 'GUESTS_NOT_ALLOWED';
    END IF;
    IF v_game.allow_guests AND v_game.guest_limit IS NOT NULL
       AND p_bringing_guests > v_game.guest_limit THEN
        RAISE EXCEPTION 'GUEST_LIMIT_EXCEEDED'
              USING HINT = 'maximum ' || v_game.guest_limit || ' guests per player';
    END IF;

    INSERT INTO commander_home_rsvps AS r
        (game_id, user_id, response, bringing_guests, message, responded_at, updated_at)
    VALUES
        (p_game_id, p_caller_user_id, p_response, p_bringing_guests, p_message, NOW(), NOW())
    ON CONFLICT (game_id, user_id) DO UPDATE
        SET response=EXCLUDED.response, bringing_guests=EXCLUDED.bringing_guests,
            message=EXCLUDED.message, updated_at=NOW()
    RETURNING id INTO v_rsvp_id;

    SELECT id, rsvp_yes, rsvp_maybe, rsvp_no, waitlist_count INTO v_updated_game
      FROM commander_home_games WHERE id = p_game_id;

    RETURN jsonb_build_object(
        'success', true, 'rsvp_id', v_rsvp_id, 'game_id', p_game_id, 'response', p_response,
        'counts', jsonb_build_object('yes', v_updated_game.rsvp_yes,
            'maybe', v_updated_game.rsvp_maybe, 'no', v_updated_game.rsvp_no,
            'waitlist', v_updated_game.waitlist_count));
END;
$$;


ALTER FUNCTION public.rsvp_to_home_game(p_game_id uuid, p_response text, p_caller_user_id uuid, p_bringing_guests integer, p_message text) OWNER TO postgres;

--
-- Name: FUNCTION rsvp_to_home_game(p_game_id uuid, p_response text, p_caller_user_id uuid, p_bringing_guests integer, p_message text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rsvp_to_home_game(p_game_id uuid, p_response text, p_caller_user_id uuid, p_bringing_guests integer, p_message text) IS 'RSVP to a home game. After the scheduled start time (or once status moves to in_progress/completed), the function returns {success:false, error:GAME_STARTED, host, conversation_id, dm_url} so the frontend can route the user to a DM thread with the host instead of recording a stale RSVP. Consistent with bug #29 join_home_group shape.';


