--
-- Name: run_trivia_economy_audit_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.run_trivia_economy_audit_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_missing_session_awards integer;
    v_mismatched_session_awards integer;
    v_missing_wheel_credits integer;
    v_mismatched_wheel_credits integer;
    v_missing_wheel_items integer;
    v_missing_exact_refs integer;
    v_duplicate_refs integer;
    v_total integer;
    v_findings jsonb;
    v_run_id uuid;
BEGIN
    SELECT count(*) INTO v_missing_session_awards
      FROM public.trivia_sessions s
     WHERE s.status = 'submitted'
       AND COALESCE(s.diamonds_awarded, 0) > 0
       AND NOT EXISTS (
           SELECT 1 FROM public.diamond_transactions d
            WHERE d.user_id = s.user_id
              AND d.reference_id = 'trivia_session_' || s.id::text
       );

    SELECT count(*) INTO v_mismatched_session_awards
      FROM public.trivia_sessions s
      JOIN public.diamond_transactions d
        ON d.user_id = s.user_id
       AND d.reference_id = 'trivia_session_' || s.id::text
     WHERE s.status = 'submitted'
       AND d.amount IS DISTINCT FROM s.diamonds_awarded;

    SELECT count(*) INTO v_missing_wheel_credits
      FROM public.trivia_prize_wheel_spins w
     WHERE w.prize_type = 'diamonds'
       AND NOT EXISTS (
           SELECT 1 FROM public.diamond_transactions d
            WHERE d.user_id = w.user_id
              AND d.reference_id = 'trivia_wheel_' || w.score_id::text
       );

    SELECT count(*) INTO v_mismatched_wheel_credits
      FROM public.trivia_prize_wheel_spins w
      JOIN public.diamond_transactions d
        ON d.user_id = w.user_id
       AND d.reference_id = 'trivia_wheel_' || w.score_id::text
     WHERE w.prize_type = 'diamonds'
       AND d.amount IS DISTINCT FROM w.prize_amount;

    SELECT count(*) INTO v_missing_wheel_items
      FROM public.trivia_prize_wheel_spins w
     WHERE w.prize_type <> 'diamonds'
       AND NOT EXISTS (
           SELECT 1 FROM public.trivia_item_transactions i
            WHERE i.user_id = w.user_id
              AND i.reference_id = 'trivia_wheel_item_' || w.score_id::text
       );

    SELECT count(*) INTO v_missing_exact_refs
      FROM public.diamond_transactions d
     WHERE d.created_at >= now() - interval '30 days'
       AND d.transaction_type IN (
           'trivia_run', 'trivia_daily_bonus', 'trivia_prize_wheel',
           'pvp_stake', 'pvp_refund', 'pvp_win',
           'tournament_entry', 'tournament_entry_refund',
           'tournament_cancel_refund', 'tournament_prize'
       )
       AND NULLIF(btrim(d.reference_id), '') IS NULL;

    SELECT count(*) INTO v_duplicate_refs
      FROM (
          SELECT user_id, reference_id
            FROM public.diamond_transactions
           WHERE reference_id IS NOT NULL
             AND created_at >= now() - interval '30 days'
           GROUP BY user_id, reference_id
          HAVING count(*) > 1
      ) duplicate_group;

    v_total := v_missing_session_awards + v_mismatched_session_awards
        + v_missing_wheel_credits + v_mismatched_wheel_credits
        + v_missing_wheel_items + v_missing_exact_refs + v_duplicate_refs;
    v_findings := jsonb_build_object(
        'missing_session_awards', v_missing_session_awards,
        'mismatched_session_awards', v_mismatched_session_awards,
        'missing_wheel_credits', v_missing_wheel_credits,
        'mismatched_wheel_credits', v_mismatched_wheel_credits,
        'missing_wheel_items', v_missing_wheel_items,
        'missing_exact_references_30d', v_missing_exact_refs,
        'duplicate_user_references_30d', v_duplicate_refs
    );

    INSERT INTO public.trivia_economy_audit_runs(status, exception_count, findings)
    VALUES (CASE WHEN v_total = 0 THEN 'healthy' ELSE 'exceptions' END, v_total, v_findings)
    RETURNING id INTO v_run_id;

    RETURN jsonb_build_object(
        'success', true,
        'healthy', v_total = 0,
        'run_id', v_run_id,
        'exception_count', v_total,
        'findings', v_findings
    );
END;
$$;


ALTER FUNCTION public.run_trivia_economy_audit_v1() OWNER TO postgres;

--
-- Name: save_hand_state_snapshot(uuid, integer, jsonb, jsonb, integer, jsonb, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_hand_state_snapshot(p_table_id uuid, p_hand_number integer, p_state_json jsonb, p_config_json jsonb, p_dealer_seat integer, p_players_json jsonb, p_stage text, p_pending_deadlines jsonb DEFAULT NULL::jsonb, p_disconnect_states jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO hand_state_snapshots (
    table_id, hand_number, state_json, config_json, dealer_seat, players_json,
    stage, pending_deadlines, disconnect_states, updated_at
  ) VALUES (
    p_table_id, p_hand_number, p_state_json, p_config_json, p_dealer_seat,
    p_players_json, p_stage,
    COALESCE(p_pending_deadlines, '[]'::jsonb),
    COALESCE(p_disconnect_states, '{}'::jsonb),
    NOW()
  )
  ON CONFLICT (table_id) WHERE is_complete = FALSE
  DO UPDATE SET
    hand_number       = EXCLUDED.hand_number,
    state_json        = EXCLUDED.state_json,
    config_json       = EXCLUDED.config_json,
    dealer_seat       = EXCLUDED.dealer_seat,
    players_json      = EXCLUDED.players_json,
    stage             = EXCLUDED.stage,
    pending_deadlines = EXCLUDED.pending_deadlines,
    disconnect_states = EXCLUDED.disconnect_states,
    updated_at        = NOW();
END;
$$;


ALTER FUNCTION public.save_hand_state_snapshot(p_table_id uuid, p_hand_number integer, p_state_json jsonb, p_config_json jsonb, p_dealer_seat integer, p_players_json jsonb, p_stage text, p_pending_deadlines jsonb, p_disconnect_states jsonb) OWNER TO postgres;

--
-- Name: FUNCTION save_hand_state_snapshot(p_table_id uuid, p_hand_number integer, p_state_json jsonb, p_config_json jsonb, p_dealer_seat integer, p_players_json jsonb, p_stage text, p_pending_deadlines jsonb, p_disconnect_states jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.save_hand_state_snapshot(p_table_id uuid, p_hand_number integer, p_state_json jsonb, p_config_json jsonb, p_dealer_seat integer, p_players_json jsonb, p_stage text, p_pending_deadlines jsonb, p_disconnect_states jsonb) IS 'Writes the one live snapshot row for a table. The two trailing arguments were folded in on 2026-09-04: the engine used to INSERT and then immediately UPDATE the row it had just inserted, which cost ~1.2M extra row versions per stats window on the largest table in the database. They default to NULL so an engine that has not shipped yet keeps working unchanged.';


--
-- Name: schedule_horse_leave(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.schedule_horse_leave(p_table_id uuid, p_horse_id uuid, p_leave_after_hands integer DEFAULT 10) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE table_seats
     SET scheduled_leave_hands = p_leave_after_hands,
         leave_pending         = true
   WHERE table_id = p_table_id
     AND horse_id = p_horse_id
     AND left_at IS NULL;
END;
$$;


