--
-- Name: search_home_groups(text, text, text, text, text, double precision, double precision, numeric, boolean, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_home_groups(p_search_text text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_game_type text DEFAULT NULL::text, p_stakes text DEFAULT NULL::text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_radius_miles numeric DEFAULT NULL::numeric, p_exclude_joined boolean DEFAULT true, p_viewer_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_inactivity_days integer DEFAULT 45) RETURNS TABLE(group_id uuid, slug text, name text, tagline text, profile_photo_url text, city text, state text, default_game_type text, default_stakes text, typical_buyin_min integer, typical_buyin_max integer, max_players integer, frequency text, member_count integer, last_activity_at timestamp with time zone, distance_miles numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Phase 40: prevent viewer_id impersonation / membership enumeration
    IF p_viewer_user_id IS NOT NULL THEN
      IF COALESCE(auth.role(), '') <> 'service_role' THEN
        IF auth.uid() IS NULL OR auth.uid() <> p_viewer_user_id THEN
          RAISE EXCEPTION 'VIEWER_ID_MISMATCH'
                USING ERRCODE = '42501',
                      HINT = 'p_viewer_user_id must equal auth.uid() or be null';
        END IF;
      END IF;
    END IF;

    p_limit := LEAST(COALESCE(p_limit, 50), 100);

    RETURN QUERY
    WITH base AS (
        SELECT g.*,
               sp.slug,
               CASE
                 WHEN p_lat IS NULL OR p_lng IS NULL
                      OR g.latitude IS NULL OR g.longitude IS NULL
                 THEN NULL::numeric
                 ELSE ROUND((
                    3959 * acos(
                        LEAST(1,
                            cos(radians(p_lat)) * cos(radians(g.latitude)) *
                            cos(radians(g.longitude) - radians(p_lng)) +
                            sin(radians(p_lat)) * sin(radians(g.latitude))
                        )
                    )
                 )::numeric, 1)
               END AS dist
          FROM commander_home_groups g
          LEFT JOIN social_pages sp
            ON sp.linked_entity_type = 'home_group'
           AND sp.linked_entity_id = g.id::text
         WHERE g.is_private = false
           AND g.is_active  = true
           AND (
               (g.visibility_override_until IS NOT NULL AND g.visibility_override_until > NOW())
            OR (g.last_activity_at IS NOT NULL
                AND g.last_activity_at >= NOW() - (p_inactivity_days || ' days')::interval)
           )
    )
    SELECT
        b.id, b.slug::text, b.name::text, b.tagline::text,
        b.profile_photo_url::text,
        b.city::text, b.state::text,
        b.default_game_type::text, b.default_stakes::text,
        b.typical_buyin_min, b.typical_buyin_max, b.max_players,
        b.frequency::text, b.member_count, b.last_activity_at,
        b.dist
      FROM base b
     WHERE (p_search_text IS NULL
            OR b.name        ILIKE '%' || p_search_text || '%'
            OR b.tagline     ILIKE '%' || p_search_text || '%'
            OR b.description ILIKE '%' || p_search_text || '%'
            OR b.city        ILIKE '%' || p_search_text || '%')
       AND (p_city      IS NULL OR b.city ILIKE p_city)
       AND (p_state     IS NULL OR UPPER(b.state) = UPPER(p_state))
       AND (p_game_type IS NULL OR b.default_game_type ILIKE p_game_type)
       AND (p_stakes    IS NULL OR b.default_stakes ILIKE '%' || p_stakes || '%')
       AND (p_radius_miles IS NULL OR b.dist IS NULL OR b.dist <= p_radius_miles)
       AND (
           p_exclude_joined = false
           OR p_viewer_user_id IS NULL
           OR NOT EXISTS (
               SELECT 1 FROM commander_home_members m
                WHERE m.group_id = b.id
                  AND m.user_id = p_viewer_user_id
                  AND m.status IN ('approved','pending')
           )
           AND b.owner_id <> p_viewer_user_id
       )
     ORDER BY
        CASE WHEN p_lat IS NULL THEN 1 ELSE 0 END,
        b.dist NULLS LAST,
        b.last_activity_at DESC NULLS LAST
     LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.search_home_groups(p_search_text text, p_city text, p_state text, p_game_type text, p_stakes text, p_lat double precision, p_lng double precision, p_radius_miles numeric, p_exclude_joined boolean, p_viewer_user_id uuid, p_limit integer, p_inactivity_days integer) OWNER TO postgres;

--
-- Name: FUNCTION search_home_groups(p_search_text text, p_city text, p_state text, p_game_type text, p_stakes text, p_lat double precision, p_lng double precision, p_radius_miles numeric, p_exclude_joined boolean, p_viewer_user_id uuid, p_limit integer, p_inactivity_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.search_home_groups(p_search_text text, p_city text, p_state text, p_game_type text, p_stakes text, p_lat double precision, p_lng double precision, p_radius_miles numeric, p_exclude_joined boolean, p_viewer_user_id uuid, p_limit integer, p_inactivity_days integer) IS 'Phase 40: validates p_viewer_user_id = auth.uid() to prevent membership enumeration via exclude_joined diff. service_role bypass for cron.';


--
-- Name: search_home_groups_v2(text, text, text, text, text, text[], numeric, numeric, integer, boolean, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_home_groups_v2(p_search_text text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_game_type text DEFAULT NULL::text, p_stakes text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[], p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric, p_radius_miles integer DEFAULT NULL::integer, p_exclude_joined boolean DEFAULT false, p_viewer_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_inactivity_days integer DEFAULT 45) RETURNS TABLE(group_id uuid, name text, slug text, tagline text, description text, city text, state text, profile_photo_url text, cover_photo_url text, is_private boolean, member_count integer, games_hosted integer, distance_miles numeric, tags text[], relevance_score real, recent_rsvps_30d bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_point   geography;
    v_tsquery tsquery;
BEGIN
    -- Phase 40: if a viewer_user_id is passed, verify it matches the caller.
    -- Prevents membership-enumeration via (exclude_joined=true vs false) diffing.
    -- Anonymous callers (auth.uid() IS NULL) may not supply p_viewer_user_id.
    IF p_viewer_user_id IS NOT NULL THEN
      IF COALESCE(auth.role(), '') <> 'service_role' THEN
        IF auth.uid() IS NULL OR auth.uid() <> p_viewer_user_id THEN
          RAISE EXCEPTION 'VIEWER_ID_MISMATCH'
                USING ERRCODE = '42501',
                      HINT = 'p_viewer_user_id must equal auth.uid() or be null';
        END IF;
      END IF;
    END IF;

    IF p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
        v_point := ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography;
    END IF;

    IF p_search_text IS NOT NULL AND length(trim(p_search_text)) > 0 THEN
        v_tsquery := plainto_tsquery('english', p_search_text);
    END IF;

    RETURN QUERY
    SELECT
        g.id, g.name,
        sp.slug,
        g.tagline, g.description,
        g.city, g.state, g.profile_photo_url, g.cover_photo_url,
        g.is_private,
        COALESCE(g.member_count, 0),
        COALESCE(g.games_hosted, 0),
        CASE WHEN v_point IS NOT NULL AND g.location_geog IS NOT NULL
             THEN ROUND((ST_Distance(g.location_geog, v_point) / 1609.344)::numeric, 1)
             ELSE NULL END,
        g.tags,
        CASE WHEN v_tsquery IS NOT NULL
             THEN ts_rank(g.search_vector, v_tsquery)
             ELSE 0::real END,
        COALESCE((
            SELECT COUNT(*) FROM commander_home_rsvps r
            JOIN commander_home_games hg ON hg.id = r.game_id
            WHERE hg.group_id = g.id AND r.response='yes'
              AND r.responded_at > NOW() - INTERVAL '30 days'
        ), 0)
      FROM commander_home_groups g
      LEFT JOIN social_pages sp ON sp.linked_entity_type='home_group' AND sp.linked_entity_id = g.id::text
     WHERE g.is_active = true
       AND NOT g.is_private
       AND g.profile_photo_url IS NOT NULL
       AND g.last_activity_at > NOW() - (p_inactivity_days || ' days')::interval
       AND (v_tsquery IS NULL OR g.search_vector @@ v_tsquery)
       AND (p_city  IS NULL OR g.city  ILIKE '%' || p_city  || '%')
       AND (p_state IS NULL OR g.state ILIKE '%' || p_state || '%')
       AND (p_game_type IS NULL OR g.default_game_type = p_game_type)
       AND (p_stakes    IS NULL OR g.default_stakes    = p_stakes)
       AND (p_tags IS NULL OR g.tags && p_tags)
       AND (v_point IS NULL OR p_radius_miles IS NULL OR g.location_geog IS NULL
            OR ST_DWithin(g.location_geog, v_point, p_radius_miles * 1609.344))
       AND (NOT p_exclude_joined OR p_viewer_user_id IS NULL OR NOT EXISTS (
              SELECT 1 FROM commander_home_members m
               WHERE m.group_id = g.id AND m.user_id = p_viewer_user_id
                 AND m.status IN ('approved','pending')))
     ORDER BY
        CASE WHEN v_tsquery IS NOT NULL THEN ts_rank(g.search_vector, v_tsquery) ELSE 0::real END DESC,
        CASE WHEN v_point IS NOT NULL AND g.location_geog IS NOT NULL
             THEN ST_Distance(g.location_geog, v_point)
             ELSE 999999999 END ASC,
        g.last_activity_at DESC
     LIMIT GREATEST(1, LEAST(p_limit, 100));
END;
$$;


ALTER FUNCTION public.search_home_groups_v2(p_search_text text, p_city text, p_state text, p_game_type text, p_stakes text, p_tags text[], p_lat numeric, p_lng numeric, p_radius_miles integer, p_exclude_joined boolean, p_viewer_user_id uuid, p_limit integer, p_inactivity_days integer) OWNER TO postgres;

--
-- Name: FUNCTION search_home_groups_v2(p_search_text text, p_city text, p_state text, p_game_type text, p_stakes text, p_tags text[], p_lat numeric, p_lng numeric, p_radius_miles integer, p_exclude_joined boolean, p_viewer_user_id uuid, p_limit integer, p_inactivity_days integer); Type: COMMENT; Schema: public; Owner: postgres
