--
-- Name: set_active_avatar(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_active_avatar(p_user_id uuid, p_avatar_type text, p_preset_avatar_id text DEFAULT NULL::text, p_custom_image_url text DEFAULT NULL::text, p_custom_prompt text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_avatar_id uuid;
  v_display_url text;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( auth.uid() <> p_user_id)) THEN
    RAISE EXCEPTION 'not allowed: cannot set another user''s avatar';
  END IF;

  IF p_avatar_type NOT IN ('preset', 'custom') THEN
    RAISE EXCEPTION 'invalid avatar type: %', p_avatar_type;
  END IF;

  INSERT INTO user_avatars (
    user_id, avatar_type, preset_avatar_id, custom_image_url,
    custom_prompt, generation_timestamp, is_active, updated_at
  ) VALUES (
    p_user_id, p_avatar_type, p_preset_avatar_id, p_custom_image_url,
    p_custom_prompt,
    CASE WHEN p_avatar_type = 'custom' THEN NOW() ELSE NULL END,
    true, NOW()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    avatar_type = EXCLUDED.avatar_type,
    preset_avatar_id = EXCLUDED.preset_avatar_id,
    custom_image_url = EXCLUDED.custom_image_url,
    custom_prompt = EXCLUDED.custom_prompt,
    generation_timestamp = EXCLUDED.generation_timestamp,
    is_active = true,
    updated_at = NOW()
  RETURNING id INTO v_avatar_id;

  v_display_url := COALESCE(p_image_url, p_custom_image_url);
  IF v_display_url IS NOT NULL THEN
    UPDATE profiles SET avatar_url = v_display_url WHERE id = p_user_id;
  END IF;

  RETURN v_avatar_id;
END;
$$;


ALTER FUNCTION public.set_active_avatar(p_user_id uuid, p_avatar_type text, p_preset_avatar_id text, p_custom_image_url text, p_custom_prompt text, p_image_url text) OWNER TO postgres;

