-- Name: set_commander_admin_pin(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_commander_admin_pin(p_user_id uuid, p_pin_hash text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_user_id is null or p_pin_hash is null or length(p_pin_hash) < 32 then
    raise exception 'invalid arguments';
  end if;
  insert into commander_admin_pins (user_id, pin_hash)
  values (p_user_id, p_pin_hash)
  on conflict (user_id)
  do update set pin_hash = excluded.pin_hash, fail_count = 0, locked_until = null, updated_at = now();
end;
$$;


ALTER FUNCTION public.set_commander_admin_pin(p_user_id uuid, p_pin_hash text) OWNER TO postgres;

--
-- Name: set_home_member_private_note(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_home_member_private_note(p_group_id uuid, p_member_user_id uuid, p_note text, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_group RECORD;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    IF p_note IS NOT NULL AND length(p_note) > 1000 THEN RAISE EXCEPTION 'NOTE_TOO_LONG'; END IF;
    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;
    IF v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members
                        WHERE group_id=p_group_id AND user_id=p_caller_user_id
                          AND role='admin' AND status='approved')
    THEN RAISE EXCEPTION 'NOT_A_HOST'; END IF;

    UPDATE commander_home_members SET host_private_note = p_note
     WHERE group_id = p_group_id AND user_id = p_member_user_id;

    -- ★ NEW: audit log (store only presence - not content, for privacy)
    INSERT INTO public.commander_home_audit_log
      (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (p_group_id, p_caller_user_id, 'member', p_member_user_id, 'private_note_set',
            jsonb_build_object('note_present', (p_note IS NOT NULL AND length(p_note) > 0),
                               'note_length',  COALESCE(length(p_note), 0)));

    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION public.set_home_member_private_note(p_group_id uuid, p_member_user_id uuid, p_note text, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: set_home_member_regular(uuid, uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_home_member_regular(p_group_id uuid, p_member_user_id uuid, p_is_regular boolean, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_group RECORD;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;
    IF v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members
                        WHERE group_id=p_group_id AND user_id=p_caller_user_id
                          AND role='admin' AND status='approved')
    THEN RAISE EXCEPTION 'NOT_A_HOST'; END IF;

    UPDATE commander_home_members SET is_regular = p_is_regular
     WHERE group_id = p_group_id AND user_id = p_member_user_id;

    -- ★ NEW: audit log
    INSERT INTO public.commander_home_audit_log
      (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (p_group_id, p_caller_user_id, 'member', p_member_user_id,
            CASE WHEN p_is_regular THEN 'regular_flag_set' ELSE 'regular_flag_unset' END,
            jsonb_build_object('is_regular', p_is_regular));

    RETURN jsonb_build_object('success', true, 'is_regular', p_is_regular);
END;
$$;


ALTER FUNCTION public.set_home_member_regular(p_group_id uuid, p_member_user_id uuid, p_is_regular boolean, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: set_profile_picture(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_profile_picture(p_media_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_url text;
    v_user_id uuid;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Get URL from media library
    SELECT url INTO v_url FROM social_media_library
    WHERE id = p_media_id AND user_id = v_user_id;

    IF v_url IS NULL THEN
        RAISE EXCEPTION 'Media not found or not owned by user';
    END IF;

    -- Clear old is_current flag
    UPDATE social_media_library SET is_current_profile_picture = false
    WHERE user_id = v_user_id AND is_current_profile_picture = true;

    -- Set new
    UPDATE social_media_library SET is_current_profile_picture = true, updated_at = now()
    WHERE id = p_media_id;

    -- Update profile
    UPDATE profiles SET avatar_url = v_url, updated_at = now()
    WHERE id = v_user_id;

    -- Record in history
    INSERT INTO profile_picture_history (user_id, url, media_id, created_at)
    VALUES (v_user_id, v_url, p_media_id, now());
END;
$$;


ALTER FUNCTION public.set_profile_picture(p_media_id uuid) OWNER TO postgres;

--
-- Name: set_push_type_pref(text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_push_type_pref(p_key text, p_enabled boolean, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_next jsonb;
BEGIN
  IF v_uid IS NULL THEN
    v_uid := p_user_id;  -- trusted server context only (see header)
  END IF;

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_key IS NULL OR length(p_key) = 0 OR length(p_key) > 64 THEN
    RAISE EXCEPTION 'Invalid preference key';
  END IF;

  INSERT INTO public.notification_preferences (user_id, push_type_prefs)
  VALUES (v_uid, CASE WHEN p_enabled THEN '{}'::jsonb
                      ELSE jsonb_build_object(p_key, false) END)
  ON CONFLICT (user_id) DO UPDATE
    SET push_type_prefs = CASE
          -- DEFAULT-ON model: enabling DELETES the key rather than storing true,
          -- so a type added to the catalog later is on for everyone.
          WHEN p_enabled THEN COALESCE(public.notification_preferences.push_type_prefs, '{}'::jsonb) - p_key
          ELSE COALESCE(public.notification_preferences.push_type_prefs, '{}'::jsonb)
               || jsonb_build_object(p_key, false)
        END,
        updated_at = now()
  RETURNING push_type_prefs INTO v_next;

  RETURN v_next;
END;
$$;


ALTER FUNCTION public.set_push_type_pref(p_key text, p_enabled boolean, p_user_id uuid) OWNER TO postgres;

--
-- Name: set_subscription_tier_features(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_subscription_tier_features() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  CASE NEW.tier
    WHEN 'club', 'enterprise' THEN
      NEW.max_tables := 999;
      NEW.max_staff := 999;
      NEW.max_sms_per_month := 99999;
      NEW.monthly_price := COALESCE(NEW.monthly_price, 399.00);
      NEW.features := '{"club_page":true,"waitlist":true,"tournaments":true,"members_free":true,"basic_analytics":true,"floor_map":true,"dealers":true,"kiosk":true,"comps":true,"promotions":true,"staff_schedule":true,"tv_displays":true,"reports":true,"advanced_analytics":true,"paid_memberships":true,"time_billing":true,"membership_plans":true}'::jsonb;
    WHEN 'charity', 'professional' THEN
      NEW.max_tables := 15;
      NEW.max_staff := 10;
      NEW.max_sms_per_month := 500;
      NEW.monthly_price := COALESCE(NEW.monthly_price, 199.00);
      NEW.features := '{"club_page":true,"waitlist":true,"tournaments":true,"members_free":true,"basic_analytics":true,"floor_map":true,"dealers":true,"kiosk":true,"comps":true,"promotions":true,"staff_schedule":true,"tv_displays":true,"reports":true,"advanced_analytics":true,"paid_memberships":false,"time_billing":false,"membership_plans":false}'::jsonb;
    WHEN 'home_game', 'starter' THEN
      NEW.max_tables := 5;
      NEW.max_staff := 3;
      NEW.max_sms_per_month := 100;
      NEW.monthly_price := COALESCE(NEW.monthly_price, 99.00);
      NEW.features := '{"club_page":true,"waitlist":true,"tournaments":true,"members_free":true,"basic_analytics":true,"floor_map":false,"dealers":false,"kiosk":false,"comps":false,"promotions":false,"staff_schedule":false,"tv_displays":false,"reports":false,"advanced_analytics":false,"paid_memberships":false,"time_billing":false,"membership_plans":false}'::jsonb;
    ELSE
      RAISE NOTICE 'Unknown tier: %, skipping feature assignment', NEW.tier;
  END CASE;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_subscription_tier_features() OWNER TO postgres;

--
-- Name: set_venue_cover_photo(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_venue_cover_photo(p_photo_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_photo RECORD; v_is_manager boolean;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    SELECT * INTO v_photo FROM commander_venue_photos WHERE id = p_photo_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'PHOTO_NOT_FOUND'; END IF;
    v_is_manager := public.is_venue_manager(p_caller_user_id, v_photo.venue_id);
    IF NOT v_is_manager THEN RAISE EXCEPTION 'NOT_VENUE_MANAGER'; END IF;

    UPDATE commander_venue_photos SET is_cover_photo = false WHERE venue_id = v_photo.venue_id;
    UPDATE commander_venue_photos SET is_cover_photo = true WHERE id = p_photo_id;
    RETURN jsonb_build_object('success', true, 'venue_id', v_photo.venue_id);
END; $$;


ALTER FUNCTION public.set_venue_cover_photo(p_photo_id uuid, p_caller_user_id uuid) OWNER TO postgres;

