-- Name: FUNCTION settle_club_rakeback(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.settle_club_rakeback(p_club_id uuid) IS 'One bounded pass of rakeback settlement for a club - see fn_settle_club_rakeback_batch. Bounded since 2026-09-07: the unbounded version could not finish a 1,769-period backlog inside the 8s service_role timeout and had settled nothing since 2026-08-20. Callers drain by calling it until periods_remaining is 0.';


--
-- Name: settle_diamond_card_purchase_atomic(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.settle_diamond_card_purchase_atomic(p_purchase_id uuid, p_session_id text, p_payment_intent_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_purchase public.diamond_purchases%ROWTYPE; v_credit jsonb; v_redemption jsonb;
  v_intent jsonb; v_total integer; v_new_balance integer; v_kind text;
  v_pkg public.diamond_packages%ROWTYPE; v_pkg_found boolean := false;
  v_refuse text;
BEGIN
  SELECT * INTO v_purchase FROM public.diamond_purchases WHERE id = p_purchase_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'purchase_not_found'); END IF;

  IF v_purchase.status = 'completed' THEN
    IF v_purchase.stripe_checkout_session_id IS DISTINCT FROM p_session_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'settlement_conflict');
    END IF;
    RETURN jsonb_build_object('success', true, 'duplicate', true, 'purchase_id', v_purchase.id,
      'redemption_status', v_purchase.metadata ->> 'redemption_status');
  END IF;

  -- A charge fully refunded before checkout.completed never credited this
  -- package. Acknowledge the later event as terminal success, bind its Stripe
  -- identities, and never call the wallet credit path.
  IF v_purchase.status = 'refunded'
     AND COALESCE((v_purchase.metadata ->> 'refund_before_settlement')::boolean, false) THEN
    IF v_purchase.stripe_checkout_session_id IS NOT NULL
       AND v_purchase.stripe_checkout_session_id IS DISTINCT FROM p_session_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'settlement_conflict');
    END IF;
    IF v_purchase.stripe_payment_intent_id IS NOT NULL
       AND v_purchase.stripe_payment_intent_id IS DISTINCT FROM p_payment_intent_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'settlement_conflict');
    END IF;
    UPDATE public.diamond_purchases
       SET stripe_checkout_session_id = COALESCE(stripe_checkout_session_id, p_session_id),
           stripe_payment_intent_id = COALESCE(stripe_payment_intent_id, p_payment_intent_id),
           metadata = COALESCE(metadata, '{}'::jsonb)
             || jsonb_build_object('terminal_settlement_acknowledged_at', now()),
           updated_at = now()
     WHERE id = v_purchase.id;
    RETURN jsonb_build_object('success', true, 'duplicate', true, 'terminal_refund', true,
      'purchase_id', v_purchase.id, 'redemption_status', 'not_requested');
  END IF;
  IF v_purchase.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'purchase_not_pending');
  END IF;

  v_total := COALESCE(v_purchase.diamonds_amount, 0) + COALESCE(v_purchase.bonus_diamonds, 0);

  -- === DR7, LOG-ONLY ======================================================
  -- A Stripe TEST-mode session settling into live balances. One such purchase
  -- already exists (fe35f19d, 2026-02-12, 100 diamonds). Whether it is
  -- reversed is Dan decision 6.11. This records it; it does not refuse it,
  -- because refusing a settle strands a charge Stripe has already taken.
  BEGIN
    IF p_session_id IS NOT NULL AND left(p_session_id, 8) = 'cs_test_' THEN
      PERFORM public.fn_ca_diamond_incident(
        'DR7:test_mode_session_settled', 'warning', v_purchase.user_id, v_total,
        'settle_diamond_card_purchase_atomic',
        jsonb_build_object('purchase_id', v_purchase.id, 'session_id', p_session_id,
          'package_name', v_purchase.package_name, 'price_usd', v_purchase.price_usd,
          'note', 'Stripe test-mode session credited real diamonds. Log-only by Dan risk rule 12.'));
      -- DIAMOND-RULINGS 20: once flipped, a cs_test_ session never settles live diamonds.
      IF public.fn_ca_diamond_rule_mode('DR7:test_mode_session_settled') = 'refuse' THEN
        v_refuse := 'DR20:test_mode_session';
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL; -- a warning that cannot be written must never fail a paid settle
  END;

  -- === DR8, LOG-ONLY ======================================================
  -- The purchase row is the price oracle at settle time; diamond_packages is
  -- the oracle at checkout time. They must agree. They are compared, never
  -- enforced: a package renamed or repriced between checkout and settle is a
  -- reason to look, not a reason to refuse a paid charge.
  BEGIN
    SELECT * INTO v_pkg FROM public.diamond_packages
     WHERE package_key = lower(COALESCE(v_purchase.package_name, ''))
        OR lower(display_name) = lower(COALESCE(v_purchase.package_name, ''))
     ORDER BY sort LIMIT 1;
    v_pkg_found := FOUND;

    IF NOT v_pkg_found THEN
      IF public.fn_ca_diamond_rule_mode('DR8:purchase_price_disagrees_with_package') = 'refuse' THEN
        v_refuse := COALESCE(v_refuse, 'DR8:purchase_price_disagrees_with_package');
      END IF;
      PERFORM public.fn_ca_diamond_incident(
        'DR8:purchase_price_disagrees_with_package', 'warning', v_purchase.user_id, v_total,
        'settle_diamond_card_purchase_atomic',
        jsonb_build_object('purchase_id', v_purchase.id, 'reason', 'unknown_package',
          'package_name', v_purchase.package_name,
          'row', jsonb_build_object('diamonds', v_purchase.diamonds_amount,
            'bonus', v_purchase.bonus_diamonds, 'price_usd', v_purchase.price_usd)));
    ELSIF COALESCE(v_purchase.diamonds_amount, -1) <> v_pkg.diamonds
       OR COALESCE(v_purchase.bonus_diamonds, -1) <> v_pkg.bonus_diamonds
       OR COALESCE(v_purchase.price_usd, -1) <> v_pkg.price_usd THEN
      IF public.fn_ca_diamond_rule_mode('DR8:purchase_price_disagrees_with_package') = 'refuse' THEN
        v_refuse := COALESCE(v_refuse, 'DR8:purchase_price_disagrees_with_package');
      END IF;
      PERFORM public.fn_ca_diamond_incident(
        'DR8:purchase_price_disagrees_with_package', 'warning', v_purchase.user_id, v_total,
        'settle_diamond_card_purchase_atomic',
        jsonb_build_object('purchase_id', v_purchase.id, 'reason', 'value_mismatch',
          'package_key', v_pkg.package_key,
          'row', jsonb_build_object('diamonds', v_purchase.diamonds_amount,
            'bonus', v_purchase.bonus_diamonds, 'price_usd', v_purchase.price_usd),
          'package', jsonb_build_object('diamonds', v_pkg.diamonds,
            'bonus', v_pkg.bonus_diamonds, 'price_usd', v_pkg.price_usd)));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL; -- same bias: never fail a paid settle over a comparison
  END;

  -- DIAMOND-RULINGS 17: a flipped DR8 or DR20 refuses the settlement. The purchase row keeps
  -- its status and records the refusal; no diamonds move; the webhook acknowledges the event
  -- so Stripe does not retry a decision that will not change, and a human sees the row.
  IF v_refuse IS NOT NULL THEN
    UPDATE public.diamond_purchases
       SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
             'settlement_refused_at', now(), 'settlement_refused_by', v_refuse,
             'settlement_refused_session', p_session_id,
             'settlement_refused_payment_intent', p_payment_intent_id),
           updated_at = now()
     WHERE id = v_purchase.id;
    RETURN jsonb_build_object('success', false, 'error', 'settlement_refused', 'refused_by', v_refuse,
      'purchase_id', v_purchase.id, 'diamonds', v_total);
  END IF;

  v_credit := public.add_diamonds_to_balance(v_purchase.user_id, v_total, 'purchase',
    'Purchased ' || COALESCE(v_purchase.package_name, 'Diamond package') || ' (' || v_total || ' diamonds)',
    v_purchase.id::text);
  IF COALESCE((v_credit ->> 'success')::boolean, false) IS NOT TRUE
     AND COALESCE((v_credit ->> 'duplicate')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'diamond_credit_failed:%', COALESCE(v_credit ->> 'error', 'unknown');
  END IF;

  -- === DR9: the purchase lot, and DR3 on the journal row it produced ======
  -- The lot is the sub-ledger that makes a refund able to know what it is
  -- reversing. ON CONFLICT DO NOTHING makes a replay a no-op. A failure here
  -- files a critical incident rather than rolling back a settled purchase:
  -- the player keeps their diamonds and a human is told the sub-ledger is
  -- short a row.
  BEGIN
    INSERT INTO public.diamond_purchase_lots (user_id, purchase_id, issued, settled_at)
    VALUES (v_purchase.user_id, v_purchase.id, v_total, now())
    ON CONFLICT (purchase_id) DO NOTHING;

    UPDATE public.diamond_transactions
       SET counterparty = 'purchase_clearing', issuance_class = 'purchased'
     WHERE reference_id = v_purchase.id::text
       AND user_id = v_purchase.user_id
       AND counterparty IS NULL;
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      PERFORM public.fn_ca_diamond_incident(
        'DR9:purchase_lot_write_failed', 'critical', v_purchase.user_id, v_total,
        'settle_diamond_card_purchase_atomic',
        jsonb_build_object('purchase_id', v_purchase.id, 'sqlstate', SQLSTATE, 'message', SQLERRM));
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END;

  v_intent := COALESCE(v_purchase.metadata -> 'redemption_intent', '{}'::jsonb);
  v_kind := v_intent ->> 'kind';
  IF v_kind = 'club_shop' THEN
    v_redemption := public.fn_purchase_club_shop_item_diamonds(
      (v_intent ->> 'club_id')::uuid, v_purchase.user_id, (v_intent ->> 'item_id')::uuid,
      'card-redemption:' || v_purchase.id::text);
  ELSIF v_kind = 'vip_daily' THEN
    v_redemption := public.purchase_vip_with_diamonds_atomic_v2(
      v_purchase.user_id, 150, 1, 'daily', 'card-redemption:' || v_purchase.id::text,
      'VIP Daily Pass (Card Funded)');
  ELSE
    v_redemption := jsonb_build_object('success', true, 'skipped', true);
  END IF;

  SELECT COALESCE(diamonds, 0) INTO v_new_balance FROM public.profiles WHERE id = v_purchase.user_id;
  UPDATE public.diamond_purchases
     SET status = 'completed', stripe_checkout_session_id = p_session_id,
         stripe_payment_intent_id = p_payment_intent_id, completed_at = now(),
         metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
           'redemption_status', CASE WHEN v_kind IS NULL THEN 'not_requested'
             WHEN COALESCE((v_redemption ->> 'success')::boolean, false) THEN 'completed'
             ELSE 'needs_review' END,
           'redemption_error', CASE WHEN COALESCE((v_redemption ->> 'success')::boolean, false)
             THEN NULL ELSE v_redemption ->> 'error' END,
           'redemption_result', v_redemption, 'settled_at', now())
   WHERE id = v_purchase.id;
  RETURN jsonb_build_object('success', true, 'duplicate', false, 'purchase_id', v_purchase.id,
    'new_balance', v_new_balance,
    'redemption_status', CASE WHEN v_kind IS NULL THEN 'not_requested'
      WHEN COALESCE((v_redemption ->> 'success')::boolean, false) THEN 'completed'
      ELSE 'needs_review' END,
    'redemption', v_redemption);
END;
$$;


ALTER FUNCTION public.settle_diamond_card_purchase_atomic(p_purchase_id uuid, p_session_id text, p_payment_intent_id text) OWNER TO postgres;

--
-- Name: settle_hand_atomically(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.settle_hand_atomically(p_table_id uuid, p_hand_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing public.settlement_idempotency_keys%ROWTYPE;
  v_rake_result jsonb;
  v_commission_results jsonb := '[]'::jsonb;
  v_player record;
  v_individual_result jsonb;
  v_final_result jsonb;
BEGIN
  SELECT * INTO v_existing
    FROM public.settlement_idempotency_keys
   WHERE table_id = p_table_id AND hand_id = p_hand_id;

  IF FOUND THEN
    IF v_existing.status = 'succeeded' THEN
      RETURN v_existing.result;
    ELSIF v_existing.status = 'in_flight' THEN
      UPDATE public.settlement_idempotency_keys
         SET attempt_count = attempt_count + 1,
             last_attempt_at = NOW()
       WHERE table_id = p_table_id AND hand_id = p_hand_id;
      RAISE EXCEPTION 'settlement already in flight for table=% hand=%', p_table_id, p_hand_id;
    END IF;
  ELSE
    INSERT INTO public.settlement_idempotency_keys
      (table_id, hand_id, status)
    VALUES (p_table_id, p_hand_id, 'in_flight');
  END IF;

  BEGIN
    v_rake_result := public.record_rake(
      p_hand_id        := p_hand_id,
      p_club_id        := (p_payload->>'club_id')::uuid,
      p_table_id       := p_table_id,
      p_rake_amount    := COALESCE((p_payload->>'rake')::numeric, 0),
      p_pot_size       := COALESCE((p_payload->>'pot')::numeric, 0),
      p_num_players    := COALESCE((p_payload->>'num_players')::int, 0),
      p_player_contributions := p_payload->'player_contributions',
      p_is_tournament  := COALESCE((p_payload->>'is_tournament')::boolean, FALSE),
      p_tournament_id  := NULLIF(p_payload->>'tournament_id','')::uuid,
      p_bbj_pct        := COALESCE((p_payload->>'bbj_pct')::numeric, 0.05)
    );

    FOR v_player IN
      SELECT key::uuid AS user_id, value::numeric AS rake_share
        FROM jsonb_each_text(COALESCE(p_payload->'player_contributions', '{}'::jsonb))
       WHERE value::numeric > 0
    LOOP
      v_individual_result := public.calculate_cascading_commission(
        p_hand_id        := p_hand_id,
        p_club_id        := (p_payload->>'club_id')::uuid,
        p_player_user_id := v_player.user_id,
        p_rake_amount    := v_player.rake_share,
        p_rake_record_id := (v_rake_result->>'rake_record_id')::uuid
      );
      v_commission_results := v_commission_results || jsonb_build_array(v_individual_result);
    END LOOP;

    v_final_result := jsonb_build_object(
      'success', true,
      'table_id', p_table_id,
      'hand_id', p_hand_id,
      'rake', v_rake_result,
      'commissions', v_commission_results
    );

    UPDATE public.settlement_idempotency_keys
       SET status = 'succeeded',
           result = v_final_result,
           completed_at = NOW(),
           last_attempt_at = NOW()
     WHERE table_id = p_table_id AND hand_id = p_hand_id;

    RETURN v_final_result;
  EXCEPTION WHEN OTHERS THEN
    UPDATE public.settlement_idempotency_keys
       SET status = 'failed',
           error  = SQLERRM,
           last_attempt_at = NOW()
     WHERE table_id = p_table_id AND hand_id = p_hand_id;
    RAISE;
  END;
END;
$$;


ALTER FUNCTION public.settle_hand_atomically(p_table_id uuid, p_hand_id uuid, p_payload jsonb) OWNER TO postgres;

--
-- Name: settle_paid_merch_order_atomic(uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.settle_paid_merch_order_atomic(p_order_id uuid, p_session_id text, p_payment_intent_id text, p_shipping_address jsonb, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_order public.merchandise_orders%ROWTYPE;
  v_stock_lines jsonb;
  v_reservation jsonb := jsonb_build_object('success', true);
  v_stock_taken boolean := true;
  v_mode text;
  v_status text;
  v_metadata jsonb;
BEGIN
  IF p_session_id IS NULL OR btrim(p_session_id) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_session');
  END IF;

  SELECT * INTO v_order
    FROM public.merchandise_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_not_found');
  END IF;
  IF v_order.payment_method = 'diamonds' THEN
    RETURN jsonb_build_object('success', false, 'error', 'wrong_payment_method');
  END IF;

  IF v_order.status <> 'pending' THEN
    IF v_order.stripe_checkout_session_id = p_session_id THEN
      RETURN jsonb_build_object(
        'success', true,
        'duplicate', true,
        'order_id', v_order.id,
        'status', v_order.status,
        'stock_taken', COALESCE((v_order.metadata ->> 'stock_reserved')::boolean, false),
        'metadata', v_order.metadata
      );
    END IF;
    RETURN jsonb_build_object('success', false, 'error', 'settlement_conflict');
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', COALESCE(line ->> 'id', line ->> 'catalogId'),
    'variant_id', COALESCE(line ->> 'variantId', line ->> 'variant_id'),
    'qty', LEAST(GREATEST(COALESCE((line ->> 'quantity')::integer, 1), 1), 10)
  )), '[]'::jsonb)
    INTO v_stock_lines
    FROM jsonb_array_elements(COALESCE(v_order.items, '[]'::jsonb)) line
   WHERE COALESCE((line ->> 'madeToOrder')::boolean, false) IS NOT TRUE;

  IF jsonb_array_length(v_stock_lines) > 0 THEN
    v_reservation := public.reserve_merch_order(v_stock_lines);
    v_stock_taken := COALESCE((v_reservation ->> 'success')::boolean, false);
  END IF;

  v_mode := CASE WHEN COALESCE(p_metadata ->> 'fulfillment_mode', '') = 'automatic'
    THEN 'automatic' ELSE 'manual' END;
  v_status := CASE WHEN v_stock_taken AND v_mode = 'automatic' THEN 'processing' ELSE 'paid' END;
  v_metadata := COALESCE(v_order.metadata, '{}'::jsonb)
    || COALESCE(p_metadata, '{}'::jsonb)
    || jsonb_build_object(
      'stock_reserved', v_stock_taken,
      'settled_at', now()
    );
  IF NOT v_stock_taken THEN
    v_metadata := v_metadata || jsonb_build_object(
      'needs_review', true,
      'reason', 'stock_unavailable_at_payment',
      'fulfillment_status', 'blocked',
      'stock_error', v_reservation ->> 'error',
      'flagged_at', now()
    );
  END IF;

  UPDATE public.merchandise_orders
     SET status = v_status,
         stripe_checkout_session_id = p_session_id,
         stripe_payment_intent_id = p_payment_intent_id,
         shipping_address = COALESCE(p_shipping_address, shipping_address),
         metadata = v_metadata,
         updated_at = now()
   WHERE id = v_order.id
   RETURNING * INTO v_order;

  RETURN jsonb_build_object(
    'success', true,
    'duplicate', false,
    'order_id', v_order.id,
    'status', v_order.status,
    'stock_taken', v_stock_taken,
    'metadata', v_order.metadata
  );
END;
$$;


ALTER FUNCTION public.settle_paid_merch_order_atomic(p_order_id uuid, p_session_id text, p_payment_intent_id text, p_shipping_address jsonb, p_metadata jsonb) OWNER TO postgres;

--
-- Name: settle_vip_lifetime_card_purchase_atomic(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.settle_vip_lifetime_card_purchase_atomic(p_purchase_id uuid, p_session_id text, p_payment_intent_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_purchase public.vip_lifetime_purchases%ROWTYPE;
  v_profile  public.profiles%ROWTYPE;
BEGIN
  SELECT * INTO v_purchase
    FROM public.vip_lifetime_purchases
   WHERE id = p_purchase_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'purchase_not_found');
  END IF;

  /* A replay of the SAME session is success, not a second grant. A different
     session pointing at this row is a conflict and must not be settled: two
     charges for one purchase row is the shape that pays a membership twice. */
  IF v_purchase.status = 'completed' THEN
    IF v_purchase.stripe_checkout_session_id IS DISTINCT FROM p_session_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'settlement_conflict');
    END IF;
    RETURN jsonb_build_object('success', true, 'duplicate', true,
                              'purchase_id', v_purchase.id, 'tier', 'lifetime');
  END IF;

  IF v_purchase.status = 'refunded' THEN
    /* Refunded before the completion event arrived. Acknowledge it as terminal
       so Stripe stops retrying, and never grant. */
    RETURN jsonb_build_object('success', true, 'duplicate', true,
                              'terminal_refund', true, 'purchase_id', v_purchase.id);
  END IF;

  IF v_purchase.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'purchase_not_pending');
  END IF;

  SELECT * INTO v_profile FROM public.profiles WHERE id = v_purchase.user_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'profile_not_found');
  END IF;

  /* NULL expiry, not a distant one. expire_lapsed_vip is guarded on
     `vip_expires_at IS NOT NULL` as well as on the tier, and a NULL satisfies
     the first guard on its own. */
  UPDATE public.profiles
     SET is_vip = true,
         vip_tier = 'lifetime',
         vip_expires_at = NULL,
         updated_at = now()
   WHERE id = v_purchase.user_id;

  UPDATE public.vip_lifetime_purchases
     SET status = 'completed',
         stripe_checkout_session_id = p_session_id,
         stripe_payment_intent_id = COALESCE(p_payment_intent_id, stripe_payment_intent_id),
         completed_at = now()
   WHERE id = p_purchase_id;

  RETURN jsonb_build_object(
    'success', true,
    'duplicate', false,
    'purchase_id', v_purchase.id,
    'user_id', v_purchase.user_id,
    'tier', 'lifetime',
    'previous_tier', v_profile.vip_tier
  );
END;
$$;


ALTER FUNCTION public.settle_vip_lifetime_card_purchase_atomic(p_purchase_id uuid, p_session_id text, p_payment_intent_id text) OWNER TO postgres;

--
-- Name: FUNCTION settle_vip_lifetime_card_purchase_atomic(p_purchase_id uuid, p_session_id text, p_payment_intent_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.settle_vip_lifetime_card_purchase_atomic(p_purchase_id uuid, p_session_id text, p_payment_intent_id text) IS 'Settles one Lifetime VIP card purchase exactly once: sets is_vip, vip_tier = lifetime and a NULL vip_expires_at, and marks the pending row completed. A replay of the same session returns duplicate:true; a different session on the same row is refused as settlement_conflict.';


--
-- Name: signup_audit_check(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.signup_audit_check(check_name text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    result boolean;
BEGIN
    CASE check_name
        WHEN 'three_triggers_on_auth_users' THEN
            SELECT count(*) = 3 INTO result
            FROM pg_trigger
            WHERE tgrelid = 'auth.users'::regclass AND NOT tgisinternal;

        WHEN 'handle_new_user_function_exists_nonempty' THEN
            SELECT length(prosrc) > 1000 INTO result
            FROM pg_proc WHERE proname = 'handle_new_user';

        WHEN 'handle_new_user_logs_to_signup_errors' THEN
            SELECT prosrc ~ 'INSERT INTO public.signup_errors' INTO result
            FROM pg_proc WHERE proname = 'handle_new_user';

        WHEN 'wallet_trigger_function_exists' THEN
            SELECT length(prosrc) > 100 INTO result
            FROM pg_proc WHERE proname = 'handle_new_user_v2_create_wallet';

        WHEN 'diamonds_trigger_function_exists' THEN
            SELECT length(prosrc) > 100 INTO result
            FROM pg_proc WHERE proname = 'initialize_user_diamonds';

        WHEN 'profiles_table_exists' THEN
            SELECT to_regclass('public.profiles') IS NOT NULL INTO result;
        WHEN 'wallets_table_exists' THEN
            SELECT to_regclass('public.wallets') IS NOT NULL INTO result;
        WHEN 'user_diamonds_table_exists' THEN
            SELECT to_regclass('public.user_diamonds') IS NOT NULL INTO result;
        WHEN 'signup_errors_table_exists' THEN
            SELECT to_regclass('public.signup_errors') IS NOT NULL INTO result;
        WHEN 'probe_heartbeats_table_exists' THEN
            SELECT to_regclass('public.probe_heartbeats') IS NOT NULL INTO result;
        WHEN 'signup_health_view_exists' THEN
            SELECT to_regclass('public.signup_health_view') IS NOT NULL INTO result;
        WHEN 'player_number_sequence_exists' THEN
            SELECT to_regclass('public.profiles_player_number_seq') IS NOT NULL INTO result;

        WHEN 'wallets_unique_index_exists' THEN
            SELECT EXISTS (
                SELECT 1 FROM pg_indexes
                WHERE tablename = 'wallets'
                  AND schemaname = 'public'
                  AND indexname = 'wallets_user_id_wallet_type_key'
            ) INTO result;

        ELSE
            -- Unknown check name - treat as failure (do not silently pass)
            RETURN FALSE;
    END CASE;

    RETURN COALESCE(result, FALSE);
END;
$$;


ALTER FUNCTION public.signup_audit_check(check_name text) OWNER TO postgres;

--
-- Name: FUNCTION signup_audit_check(check_name text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.signup_audit_check(check_name text) IS 'Backs /api/cron/trigger-audit. Pass a check_name from the hardcoded list; returns boolean. Centralizes audit SQL so the handler can not ship arbitrary queries. Adding a new check requires a new migration (audit trail).';


--
-- Name: slugify_home_game(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.slugify_home_game(input text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE s text;
BEGIN
  s := lower(coalesce(input, ''));
  s := regexp_replace(s, '[^a-z0-9]+', '-', 'g');
  s := regexp_replace(s, '^-+|-+$', '', 'g');
  IF s IS NULL OR length(s) = 0 THEN s := 'home-game'; END IF;
  RETURN s;
END; $_$;


ALTER FUNCTION public.slugify_home_game(input text) OWNER TO postgres;

--
-- Name: sp_backfill_matrix_batch(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_backfill_matrix_batch(n integer DEFAULT 1500) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare done int;
begin
  with b as (
    select ctid from solved_spots_gold
     where strategy_matrix_v2 is not null
       and (strategy_matrix->>'source') is distinct from 'pio_v2'
     limit n
  ), u as (
    update solved_spots_gold t
       set strategy_matrix = sp_v2_to_app_matrix(t.strategy_matrix_v2)
      from b where t.ctid = b.ctid
    returning 1
  )
  select count(*) into done from u;

  if done = 0 then
    begin
      perform cron.unschedule('sp_backfill_matrix');
    exception when others then null;
    end;
  end if;
  return done;
end $$;


ALTER FUNCTION public.sp_backfill_matrix_batch(n integer) OWNER TO postgres;

--
-- Name: sp_backfill_member_fee_rollup(integer, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_backfill_member_fee_rollup(IN p_seconds integer DEFAULT 120, IN p_batch integer DEFAULT 4000)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_res     jsonb;
  v_started timestamptz := clock_timestamp();
  v_total   bigint := 0;
BEGIN
  LOOP
    v_res := public.fn_refresh_member_fee_rollup(p_batch);
    v_total := v_total + coalesce((v_res->>'processed')::bigint, 0);
    COMMIT;
    EXIT WHEN (v_res->>'caught_up')::boolean IS TRUE;
    EXIT WHEN clock_timestamp() - v_started > make_interval(secs => p_seconds);
  END LOOP;
  RAISE NOTICE 'sp_backfill_member_fee_rollup: % hands in %', v_total, clock_timestamp() - v_started;
END;
$$;


ALTER PROCEDURE public.sp_backfill_member_fee_rollup(IN p_seconds integer, IN p_batch integer) OWNER TO postgres;

--
-- Name: PROCEDURE sp_backfill_member_fee_rollup(IN p_seconds integer, IN p_batch integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON PROCEDURE public.sp_backfill_member_fee_rollup(IN p_seconds integer, IN p_batch integer) IS 'Catches member_fee_rollup up to the present, committing after each batch so a client timeout never discards progress. Safe to CALL repeatedly; it resumes from the watermark.';


--
-- Name: sp_compact_hand_history(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_compact_hand_history(p_budget_seconds integer DEFAULT 15, p_batch integer DEFAULT 300, p_window_pages integer DEFAULT 4000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_enabled   boolean;
  v_headroom  numeric;
  v_resume    bigint;
  v_deadline  timestamptz;
  v_relpages  bigint;
  v_live      bigint;
  v_per_page  numeric;
  v_target    bigint;
  v_hi        bigint;
  v_lo        bigint;
  v_ctids     tid[];
  v_moved     bigint := 0;
  v_round     integer;
  v_stop      text := 'budget_spent';
BEGIN
  -- GUARD 1: the kill switch.
  SELECT enabled, COALESCE(headroom_factor, 1.25), resume_page
    INTO v_enabled, v_headroom, v_resume
    FROM public.hand_history_compaction_policy
   LIMIT 1;

  IF NOT COALESCE(v_enabled, false) THEN
    RETURN jsonb_build_object('compacted', false, 'reason', 'disabled');
  END IF;

  -- GUARD 2: an UPDATE here is only invisible while every trigger on
  -- hand_history is INSERT-only. If one ever fires on UPDATE, moving a row
  -- would re-run the club stats trigger and double-count somebody's profit.
  IF EXISTS (
    SELECT 1 FROM pg_trigger t
     WHERE t.tgrelid = 'public.hand_history'::regclass
       AND NOT t.tgisinternal
       AND (t.tgtype & 16) <> 0
  ) THEN
    RETURN jsonb_build_object('compacted', false, 'reason', 'update_trigger_present');
  END IF;

  -- GUARD 3: an UPDATE on a replicated table is a broadcast.
  IF EXISTS (
    SELECT 1 FROM pg_publication_rel pr
      JOIN pg_publication p ON p.oid = pr.prpubid
     WHERE pr.prrelid = 'public.hand_history'::regclass AND p.pubupdate
  ) OR EXISTS (SELECT 1 FROM pg_publication WHERE puballtables AND pubupdate) THEN
    RETURN jsonb_build_object('compacted', false, 'reason', 'table_is_published');
  END IF;

  v_deadline := clock_timestamp() + make_interval(secs => GREATEST(p_budget_seconds, 1));

  SELECT relpages::bigint, GREATEST(reltuples, 0)::bigint
    INTO v_relpages, v_live
    FROM pg_class WHERE oid = 'public.hand_history'::regclass;

  SELECT COALESCE(NULLIF(avg(cnt), 0), 5)::numeric
    INTO v_per_page
    FROM (
      SELECT count(*) AS cnt
        FROM public.hand_history TABLESAMPLE SYSTEM (0.05)
       GROUP BY (ctid::text::point)[0]::bigint
    ) s;

  v_target := ceil((v_live / GREATEST(v_per_page, 1)) * GREATEST(v_headroom, 1.05))::bigint;

  -- GUARD 4: already packed -- never churn for no space.
  IF v_relpages <= v_target THEN
    UPDATE public.hand_history_compaction_policy
       SET resume_page = NULL, updated_at = now();
    RETURN jsonb_build_object('compacted', false, 'reason', 'already_compact',
                              'relpages', v_relpages, 'target_pages', v_target);
  END IF;

  -- Resume where the last run stopped. Never above the current relpages (the
  -- file may have been truncated since), never at or below the target (that
  -- means a full sweep finished and the next one starts from the tail).
  v_hi := LEAST(COALESCE(v_resume, v_relpages), v_relpages);
  IF v_hi <= v_target THEN
    v_hi := v_relpages;
  END IF;

  <<work>>
  LOOP
    v_ctids := NULL;

    WHILE v_hi > v_target AND v_ctids IS NULL LOOP
      v_lo := GREATEST(v_target, v_hi - GREATEST(p_window_pages, 1));

      SELECT array_agg(ctid)
        INTO v_ctids
        FROM (
          SELECT ctid
            FROM public.hand_history
           WHERE ctid >= ('(' || v_lo || ',0)')::tid
             AND ctid <  ('(' || v_hi || ',0)')::tid
           LIMIT GREATEST(p_batch, 1)
        ) s;

      IF v_ctids IS NULL THEN
        v_hi := v_lo;
      END IF;

      IF clock_timestamp() >= v_deadline THEN
        EXIT work;
      END IF;
    END LOOP;

    IF v_ctids IS NULL THEN
      v_stop := 'tail_reached_target';
      EXIT work;
    END IF;

    -- The no-op: every column keeps its value. The row is rewritten only so
    -- the free space map can place it in one of the empty low pages.
    UPDATE public.hand_history
       SET reported = reported
     WHERE ctid = ANY (v_ctids);

    GET DIAGNOSTICS v_round = ROW_COUNT;
    v_moved := v_moved + v_round;

    -- GUARD 5: a batch that moves nothing means we are spinning.
    IF v_round = 0 THEN
      v_stop := 'no_progress';
      EXIT work;
    END IF;

    EXIT work WHEN clock_timestamp() >= v_deadline;
  END LOOP work;

  UPDATE public.hand_history_compaction_policy
     SET resume_page = CASE WHEN v_hi <= v_target THEN NULL ELSE v_hi END,
         updated_at  = now();

  RETURN jsonb_build_object(
    'compacted',    true,
    'rows_moved',   v_moved,
    'relpages',     v_relpages,
    'target_pages', v_target,
    'resumed_from', LEAST(COALESCE(v_resume, v_relpages), v_relpages),
    'lowest_page_worked', v_hi,
    'stopped',      v_stop
  );
END;
$$;


ALTER FUNCTION public.sp_compact_hand_history(p_budget_seconds integer, p_batch integer, p_window_pages integer) OWNER TO postgres;

--
-- Name: sp_cosmetic_is_owned(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_cosmetic_is_owned(p_user uuid, p_token text, p_kind text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_token    text := public.sp_normalize_cosmetic_token(p_token);
  v_is_vip   boolean;
  v_free     text[] := ARRAY[
    'frame_slate', 'frame_ivory', 'frame_copper',
    'aura_mist',   'aura_dusk',   'aura_moss'
  ];
  v_catalog  text[] := ARRAY[
    'frame_gold', 'frame_diamond', 'frame_cyber', 'frame_hellfire',
    'aura_fire',  'aura_glitch',
    'frame_slate', 'frame_ivory', 'frame_copper',
    'aura_mist',   'aura_dusk',   'aura_moss'
  ];
BEGIN
  IF v_token = '' THEN
    RETURN true;
  END IF;

  IF NOT (v_token = ANY (v_catalog)) THEN
    RETURN false;
  END IF;

  IF p_kind IS NOT NULL AND v_token NOT LIKE (p_kind || '\_%') THEN
    RETURN false;
  END IF;

  -- FREE TIER: no user, no VIP, no ledger row required.
  IF v_token = ANY (v_free) THEN
    RETURN true;
  END IF;

  IF p_user IS NULL THEN
    RETURN false;
  END IF;

  SELECT p.is_vip INTO v_is_vip FROM public.profiles p WHERE p.id = p_user;
  IF coalesce(v_is_vip, false) THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.avatar_unlocks au
    WHERE au.user_id = p_user
      AND public.sp_normalize_cosmetic_token(au.avatar_id) = v_token
  );
END;
$$;


ALTER FUNCTION public.sp_cosmetic_is_owned(p_user uuid, p_token text, p_kind text) OWNER TO postgres;

--
-- Name: FUNCTION sp_cosmetic_is_owned(p_user uuid, p_token text, p_kind text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sp_cosmetic_is_owned(p_user uuid, p_token text, p_kind text) IS 'Avatar cosmetics ownership. Catalog mirrors src/cosmetics/avatarCosmetics.ts; keep the six tokens in sync with both apps.';


--
-- Name: sp_grant_shop_item(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_grant_shop_item(p_user_id uuid, p_item_id uuid, p_unlock_method text DEFAULT 'club_shop_purchase'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_spec    jsonb;
  v_type    text;
  v_qty     integer;
  v_ref     text;
BEGIN
  SELECT grant_spec INTO v_spec FROM public.club_shop_items WHERE id = p_item_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'item_gone');
  END IF;

  v_type := COALESCE(v_spec->>'type', 'none');
  BEGIN
    v_qty := GREATEST(1, LEAST(1000, COALESCE((v_spec->>'qty')::integer, 1)));
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_grant_quantity');
  END;

  IF v_type = 'time_bank' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (p_user_id, 'time_bank_seconds', 0, 'per_use', v_qty, NULL);
    RETURN jsonb_build_object(
      'success', true, 'type', v_type, 'uses', v_qty, 'seconds', v_qty * 20,
      'permanent', false
    );
  ELSIF v_type = 'throwable' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (p_user_id, 'throwable', 0, 'per_use', v_qty, NULL);
    RETURN jsonb_build_object(
      'success', true, 'type', v_type, 'uses', v_qty, 'permanent', false
    );
  ELSIF v_type = 'emote_pack' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.feature_purchases
       WHERE user_id = p_user_id AND feature = 'emoji_pack'
         AND (expires_at IS NULL OR expires_at > now())
    ) THEN
      INSERT INTO public.feature_purchases
        (user_id, feature, cost, usage_type, uses_remaining, expires_at)
      VALUES (p_user_id, 'emoji_pack', 0, 'permanent', NULL, NULL);
    END IF;
    RETURN jsonb_build_object('success', true, 'type', v_type, 'permanent', true);
  ELSIF v_type = 'table_skin' THEN
    v_ref := public.sp_resolve_theme_preset(v_spec->>'theme_id');
    IF v_ref IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'invalid_theme_sku');
    END IF;
    PERFORM public.sp_grant_theme_preset(p_user_id, v_ref, p_unlock_method);
    RETURN jsonb_build_object(
      'success', true, 'type', v_type, 'theme_id', v_ref, 'permanent', true
    );
  ELSIF v_type = 'avatar' THEN
    v_ref := public.sp_resolve_avatar_shop_sku(v_spec->>'avatar_id');
    IF v_ref IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'invalid_avatar_sku');
    END IF;
    INSERT INTO public.avatar_unlocks (user_id, avatar_id, unlock_method)
    VALUES (p_user_id, v_ref, p_unlock_method) ON CONFLICT DO NOTHING;
    RETURN jsonb_build_object(
      'success', true, 'type', v_type, 'avatar_id', v_ref, 'permanent', true
    );
  END IF;

  RETURN jsonb_build_object('success', false, 'error', 'unfulfillable_item');
END;
$$;


ALTER FUNCTION public.sp_grant_shop_item(p_user_id uuid, p_item_id uuid, p_unlock_method text) OWNER TO postgres;

--
-- Name: sp_grant_theme_preset(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_grant_theme_preset(p_user_id uuid, p_theme_id text, p_unlock_method text DEFAULT 'grant'::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_preset public.theme_preset_catalog%ROWTYPE;
BEGIN
  SELECT p.* INTO v_preset
    FROM public.theme_preset_catalog p
   WHERE p.theme_id = public.sp_resolve_theme_preset(p_theme_id);
  IF v_preset.theme_id IS NULL THEN RETURN NULL; END IF;

  INSERT INTO public.theme_asset_unlocks (user_id, category, asset_id, unlock_method)
  VALUES
    (p_user_id, 'theme_id',      v_preset.theme_id,      p_unlock_method),
    (p_user_id, 'table_id',      v_preset.table_id,      p_unlock_method),
    (p_user_id, 'button_id',     v_preset.button_id,     p_unlock_method),
    (p_user_id, 'background_id', v_preset.background_id, p_unlock_method),
    (p_user_id, 'cards_id',      v_preset.cards_id,      p_unlock_method)
  ON CONFLICT DO NOTHING;

  -- Compatibility receipt for older World Hub readers. Table Studio and the
  -- entitlement guard use theme_asset_unlocks above.
  INSERT INTO public.theme_unlocks (user_id, theme_id, unlock_method)
  VALUES (p_user_id, v_preset.theme_id, p_unlock_method)
  ON CONFLICT (user_id, theme_id) DO NOTHING;

  RETURN v_preset.theme_id;
END;
$$;


ALTER FUNCTION public.sp_grant_theme_preset(p_user_id uuid, p_theme_id text, p_unlock_method text) OWNER TO postgres;

--
-- Name: sp_guard_avatar_cosmetics(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_guard_avatar_cosmetics() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner uuid;
BEGIN
  IF TG_TABLE_NAME = 'profiles' THEN
    v_owner := NEW.id;
  ELSE
    v_owner := NEW.user_id;
  END IF;

  IF NEW.equipped_frame IS DISTINCT FROM (CASE WHEN TG_OP = 'UPDATE' THEN OLD.equipped_frame ELSE NULL END)
     AND NEW.equipped_frame IS NOT NULL THEN
    IF NOT public.sp_cosmetic_is_owned(v_owner, NEW.equipped_frame, 'frame') THEN
      RAISE EXCEPTION
        'equipped_frame % is not owned by % (or is not a known frame)',
        NEW.equipped_frame, v_owner
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.equipped_aura IS DISTINCT FROM (CASE WHEN TG_OP = 'UPDATE' THEN OLD.equipped_aura ELSE NULL END)
     AND NEW.equipped_aura IS NOT NULL THEN
    IF NOT public.sp_cosmetic_is_owned(v_owner, NEW.equipped_aura, 'aura') THEN
      RAISE EXCEPTION
        'equipped_aura % is not owned by % (or is not a known aura)',
        NEW.equipped_aura, v_owner
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sp_guard_avatar_cosmetics() OWNER TO postgres;

--
-- Name: sp_is_lifetime_vip(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_is_lifetime_vip(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE((
    SELECT COALESCE(p.is_vip, false) AND p.vip_tier = 'lifetime'
      FROM public.profiles p
     WHERE p.id = p_user_id
  ), false);
$$;


ALTER FUNCTION public.sp_is_lifetime_vip(p_user_id uuid) OWNER TO postgres;

--
-- Name: sp_normalize_cosmetic_token(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_normalize_cosmetic_token(p_raw text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT regexp_replace(lower(btrim(coalesce(p_raw, ''))), '[[:space:]-]+', '_', 'g');
$$;


ALTER FUNCTION public.sp_normalize_cosmetic_token(p_raw text) OWNER TO postgres;

--
-- Name: sp_pending_boards(text, integer, text, text[], boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_pending_boards(p_gt text, p_stack integer, p_prefix text DEFAULT ''::text, p_positions text[] DEFAULT '{}'::text[], p_turn boolean DEFAULT false, p_limit integer DEFAULT 20000) RETURNS TABLE(board text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
 declare 
   _street text;
   _streets text[];
   _pats text[];
 begin
   -- Deduce the primary street from p_prefix (e.g. 'flop_')
   if p_prefix = 'flop_' then
     _streets := array['flop'];
   elsif p_prefix = 'turn_' then
     _streets := array['turn'];
   elsif p_prefix = 'river_' then
     _streets := array['river'];
   else
     -- Fallback if prefix is empty or unexpected
     _streets := array['flop', 'turn', 'river', 'preflop'];
   end if;

   if p_turn then
     _streets := array_append(_streets, 'turn');
   end if;
   
   -- Build the LIKE patterns as before
   select array_agg(coalesce(p_prefix,'') || p_gt || '_' || x || '_' || p_stack || 'bb_%')     
     into _pats from unnest(p_positions) x;                                                     
   
   if p_turn then                                                                              
     _pats := _pats || (select array_agg('turn_' || p_gt || '_' || x || '_' || p_stack || 'bb_%')
                        from unnest(p_positions) x);                                           
   end if;                                                                                     
   
   if _pats is null then return; end if;                                                        

   return query                                                                                
     select distinct substr(regexp_replace(g.scenario_hash, '^.*_', ''), 1, 6)                 
       from unnest(_pats) as pat
       cross join lateral (
         select scenario_hash 
         from solved_spots_gold g                                                                
         where g.game_type = p_gt                                                                 
           and g.stack_depth = p_stack                                                            
           and g.street = any(_streets)
           and g.strategy_matrix_v2 is null                                                       
           and g.scenario_hash >= replace(pat, '%', '')
           and g.scenario_hash < replace(pat, '%', '') || '~'
           and g.scenario_hash like pat
         limit p_limit
       ) g
      order by 1                                                                               
      limit p_limit;                                                                           
 end;
$$;


ALTER FUNCTION public.sp_pending_boards(p_gt text, p_stack integer, p_prefix text, p_positions text[], p_turn boolean, p_limit integer) OWNER TO postgres;

--
-- Name: sp_pending_family_apply_delta(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_pending_family_apply_delta(_d jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- _d is [{game_type, stack_depth, d}] - the net change per family.
  insert into sp_pending_family_cache (game_type, stack_depth, n, refreshed_at)
  select (e->>'game_type')::text, (e->>'stack_depth')::int, (e->>'d')::bigint, now()
    from jsonb_array_elements(_d) e
   where (e->>'d')::bigint <> 0
  on conflict (game_type, stack_depth) do update
    set n = greatest(0, sp_pending_family_cache.n + excluded.n),
        refreshed_at = now();

  -- A family that drops to zero pending is no longer a pending family.
  delete from sp_pending_family_cache where n <= 0;
end $$;


ALTER FUNCTION public.sp_pending_family_apply_delta(_d jsonb) OWNER TO postgres;

--
-- Name: sp_pending_family_tg(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_pending_family_tg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare _delta jsonb;
begin
  if TG_OP = 'INSERT' then
    select coalesce(jsonb_agg(jsonb_build_object(
             'game_type', game_type, 'stack_depth', stack_depth, 'd', c)), '[]'::jsonb)
      into _delta
      from (select game_type, stack_depth, count(*)::bigint as c
              from new_rows
             where strategy_matrix_v2 is null
               and game_type is not null and stack_depth is not null
             group by 1,2) a;

  elsif TG_OP = 'DELETE' then
    select coalesce(jsonb_agg(jsonb_build_object(
             'game_type', game_type, 'stack_depth', stack_depth, 'd', -c)), '[]'::jsonb)
      into _delta
      from (select game_type, stack_depth, count(*)::bigint as c
              from old_rows
             where strategy_matrix_v2 is null
               and game_type is not null and stack_depth is not null
             group by 1,2) r;

  else -- UPDATE: net of rows that became pending minus rows that stopped being
    with removed as (
      select game_type, stack_depth, count(*)::bigint as c
        from old_rows
       where strategy_matrix_v2 is null and game_type is not null and stack_depth is not null
       group by 1,2),
    added as (
      select game_type, stack_depth, count(*)::bigint as c
        from new_rows
       where strategy_matrix_v2 is null and game_type is not null and stack_depth is not null
       group by 1,2)
    select coalesce(jsonb_agg(jsonb_build_object(
             'game_type', game_type, 'stack_depth', stack_depth, 'd', d)), '[]'::jsonb)
      into _delta
      from (select coalesce(a.game_type, r.game_type)     as game_type,
                   coalesce(a.stack_depth, r.stack_depth) as stack_depth,
                   coalesce(a.c,0) - coalesce(r.c,0)      as d
              from added a full outer join removed r
                on a.game_type = r.game_type and a.stack_depth = r.stack_depth) x
     where d <> 0;
  end if;

  if _delta is not null and _delta <> '[]'::jsonb then
    perform sp_pending_family_apply_delta(_delta);
  end if;
  return null;
exception when others then
  -- Never block a write to solved_spots_gold over a dashboard counter.
  return null;
end $$;


ALTER FUNCTION public.sp_pending_family_tg() OWNER TO postgres;

--
-- Name: FUNCTION sp_pending_family_tg(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sp_pending_family_tg() IS 'Incrementally maintains sp_pending_family_cache so the 62GB solved_spots_gold table never needs a periodic full scan. Statement-level with transition tables; exception-guarded so it can never block a solver write. See migration 2026-08-15.';


--
-- Name: sp_prune_ca_settlements(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_prune_ca_settlements(p_batch integer DEFAULT 5000, p_retain_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted integer := 0;
  v_cutoff  timestamptz;
BEGIN
  IF p_batch IS NULL OR p_batch <= 0 THEN
    RAISE EXCEPTION 'sp_prune_ca_settlements: p_batch must be positive, got %', p_batch;
  END IF;

  IF p_retain_days IS NULL OR p_retain_days < 7 THEN
    RAISE EXCEPTION
      'sp_prune_ca_settlements: refusing a retention window of % days. Settlement history is evidence; if you really mean to shorten it, change the default here in a migration that says why.',
      p_retain_days;
  END IF;

  IF public.fn_platform_frozen() THEN
    RETURN 0;
  END IF;

  v_cutoff := now() - make_interval(days => p_retain_days);

  WITH doomed AS (
    SELECT ctid
    FROM public.ca_settlements
    WHERE state = 'final'
      AND updated_at < v_cutoff
    ORDER BY updated_at
    LIMIT p_batch
  )
  DELETE FROM public.ca_settlements s
  USING doomed d
  WHERE s.ctid = d.ctid;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION public.sp_prune_ca_settlements(p_batch integer, p_retain_days integer) OWNER TO postgres;

--
-- Name: FUNCTION sp_prune_ca_settlements(p_batch integer, p_retain_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sp_prune_ca_settlements(p_batch integer, p_retain_days integer) IS 'Batched retention prune for ca_settlements, which had no prune at all and was growing ~430 MB/day forever. Deletes only state = ''final'' rows older than p_retain_days (default 30). NEVER deletes ''failed'' rows - those are evidence of the 7.7% settlement failure rate - and never a row still walking its state machine. Runs outside the settlement transaction and skips the maintenance freeze.';


--
-- Name: sp_prune_hand_discards(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_prune_hand_discards(p_limit integer DEFAULT 5000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  WITH doomed AS (
    SELECT d.id
    FROM public.hand_discards d
    WHERE d.created_at < now() - interval '1 day'
      AND NOT EXISTS (
        SELECT 1 FROM public.hand_history h
        WHERE h.table_id = d.table_id AND h.hand_number = d.hand_number
      )
    ORDER BY d.created_at
    LIMIT GREATEST(p_limit, 0)
  )
  DELETE FROM public.hand_discards d
  USING doomed WHERE d.id = doomed.id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


ALTER FUNCTION public.sp_prune_hand_discards(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION sp_prune_hand_discards(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sp_prune_hand_discards(p_limit integer) IS 'Deletes hand_discards rows whose hand is no longer in hand_history, after a one-day grace window so a discard written mid-hand is never pruned before its own hand row is written.';


--
-- Name: sp_prune_hand_history(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_prune_hand_history(p_batch integer DEFAULT 2500) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_budget constant interval := interval '20 seconds';
  v_deadline timestamptz := clock_timestamp()+v_budget;
  v_days integer;
  v_window interval;
  v_doomed uuid[];
  v_keepers uuid[];
  v_deleted integer := 0;
  v_round integer;
BEGIN
  SELECT greatest(coalesce(horse_retention_days,7),1)
    INTO v_days FROM public.hand_history_retention_policy LIMIT 1;
  IF v_days IS NULL THEN v_days := 7; END IF;
  v_window := make_interval(days=>v_days);

  LOOP
    v_doomed := NULL;
    v_keepers := NULL;
    WITH candidates AS (
      SELECT hh.id,hh.players
        FROM public.hand_history hh
       WHERE hh.has_human IS DISTINCT FROM true
         AND hh.reported IS NOT true
         AND hh.created_at<now()-v_window
         AND NOT EXISTS (
           SELECT 1 FROM public.bbj_payouts bp
            WHERE bp.table_id=hh.table_id AND bp.hand_number=hh.hand_number)
         AND NOT EXISTS (
           SELECT 1 FROM public.hand_projection_outbox o WHERE o.hand_id=hh.id)
         AND NOT EXISTS (
           SELECT 1 FROM public.tournament_knockout_candidates c
            WHERE c.hand_id=hh.id AND c.state='pending')
       ORDER BY hh.created_at
       LIMIT p_batch
       FOR UPDATE SKIP LOCKED
    ), classified AS (
      SELECT c.id,
        CASE
          WHEN jsonb_typeof(c.players) IS DISTINCT FROM 'array' THEN true
          WHEN jsonb_array_length(c.players)=0 THEN true
          ELSE EXISTS (
            SELECT 1
              FROM jsonb_array_elements(c.players) e
              LEFT JOIN public.profiles p ON p.id=(CASE
                WHEN length(e.value->>'userId')=36
                 AND (e.value->>'userId') ~
                   '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                THEN (e.value->>'userId')::uuid END)
             WHERE p.id IS NULL OR p.is_horse IS NOT true)
        END AS is_human
        FROM candidates c
    )
    SELECT array_agg(id) FILTER (WHERE is_human IS false),
           array_agg(id) FILTER (WHERE is_human IS DISTINCT FROM false)
      INTO v_doomed,v_keepers FROM classified;

    EXIT WHEN v_doomed IS NULL AND v_keepers IS NULL;
    IF v_keepers IS NOT NULL AND cardinality(v_keepers)>0 THEN
      UPDATE public.hand_history SET has_human=true WHERE id=ANY(v_keepers);
    END IF;
    IF v_doomed IS NOT NULL AND cardinality(v_doomed)>0 THEN
      DELETE FROM public.rake_attributions WHERE hand_id=ANY(v_doomed);
      DELETE FROM public.ca_hand_player_idx WHERE hand_id=ANY(v_doomed);
      DELETE FROM public.hand_atomic_commits WHERE hand_id=ANY(v_doomed);
      DELETE FROM public.hand_history WHERE id=ANY(v_doomed);
      GET DIAGNOSTICS v_round=ROW_COUNT;
      v_deleted := v_deleted+v_round;
    END IF;
    EXIT WHEN clock_timestamp()>=v_deadline;
  END LOOP;
  RETURN v_deleted;
END;
$_$;


ALTER FUNCTION public.sp_prune_hand_history(p_batch integer) OWNER TO postgres;

--
-- Name: FUNCTION sp_prune_hand_history(p_batch integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sp_prune_hand_history(p_batch integer) IS 'Retention for hand_history. A hand with any human seat is kept FOREVER; horse-only hands are deleted after 7 days; reported hands are never classified and never auto-deleted. One pass classifies the oldest unresolved batch and deletes the horse-only ones by primary key. Policy set by Dan 2026-08-20, replacing a flat 90 days that spent ~99.97% of its storage on horse-vs-horse hands while deleting real players history at 90 days.';


--
-- Name: sp_prune_hand_state_snapshots(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_prune_hand_state_snapshots(p_batch integer DEFAULT 5000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  -- A time budget, like sp_prune_hand_history: the cron gives this call a 30s
  -- statement_timeout, and a single 10,000-row delete measured 19-30s under
  -- load (2026-09-07). One over-budget statement rolls back WHOLE and deletes
  -- nothing, so the backlog would never drain. Rounds of 2,000 (~4-6s each)
  -- until 20s have passed keep the WHOLE call inside the cron's 30s, so it
  -- is never cut off - the rounds share one transaction; the budget is what
  -- protects it.
  v_budget   constant interval := interval '20 seconds';
  v_round    constant integer  := 2000;
  v_deadline timestamptz := clock_timestamp() + v_budget;
  v_deleted  int := 0;
  v_n        int;
begin
  loop
    with doomed as (
      select id from public.hand_state_snapshots
       where (is_complete = true  and created_at < now() - interval '6 hours')
          or (is_complete = false and created_at < now() - interval '30 days')
       order by created_at
       limit least(v_round, greatest(p_batch, 1))
    )
    delete from public.hand_state_snapshots h using doomed d where h.id = d.id;
    get diagnostics v_n = row_count;
    v_deleted := v_deleted + v_n;
    exit when v_n = 0 or clock_timestamp() >= v_deadline;
  end loop;
  return v_deleted;
end
$$;


ALTER FUNCTION public.sp_prune_hand_state_snapshots(p_batch integer) OWNER TO postgres;

--
-- Name: FUNCTION sp_prune_hand_state_snapshots(p_batch integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sp_prune_hand_state_snapshots(p_batch integer) IS 'Every 2 minutes (sp_prune_hand_state_snapshots_2m): deletes completed hand snapshots older than 6 hours and incomplete ones older than 30 days, oldest first, in rounds of up to 2,000 until a 20s budget is spent, which keeps the call inside the cron''s 30s statement_timeout. Nothing reads a completed snapshot; the hand lives in hand_history.';


--
-- Name: sp_prune_horse_hand_reviews(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_prune_horse_hand_reviews() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int; m int; k int; j int;
begin
  delete from horse_hand_reviews where created_at < now() - interval '30 days';
  get diagnostics n = row_count;
  delete from horse_daily_nets where day < current_date - 180;
  get diagnostics m = row_count;
  delete from horse_daily_play where day < current_date - 180;
  get diagnostics k = row_count;
  delete from horse_tournament_daily where day < current_date - 180;
  get diagnostics j = row_count;
  return n + m + k + j;
end $$;


ALTER FUNCTION public.sp_prune_horse_hand_reviews() OWNER TO postgres;

