--
-- Name: sp_resolve_theme_preset(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_resolve_theme_preset(p_theme_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (SELECT p.theme_id FROM public.theme_preset_catalog p WHERE p.theme_id = p_theme_id),
    (SELECT a.theme_id FROM public.theme_preset_aliases a WHERE a.alias = p_theme_id)
  );
$$;


