--
-- Name: sp_sweep_ca_hand_player_idx_orphans(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_sweep_ca_hand_player_idx_orphans(p_batch integer DEFAULT 50000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_budget   constant interval := interval '25 seconds';
  v_deadline timestamptz := clock_timestamp() + v_budget;
  v_deleted  integer := 0;
  v_round    integer;
begin
  loop
    with doomed as (
      select i.ctid
        from public.ca_hand_player_idx i
       where i.created_at < now() - interval '14 days'
         and not exists (select 1 from public.hand_history h where h.id = i.hand_id)
       limit p_batch
    )
    delete from public.ca_hand_player_idx i using doomed d where i.ctid = d.ctid;
    get diagnostics v_round = row_count;
    v_deleted := v_deleted + v_round;
    exit when v_round = 0 or clock_timestamp() >= v_deadline;
  end loop;
  return v_deleted;
end
$$;


ALTER FUNCTION public.sp_sweep_ca_hand_player_idx_orphans(p_batch integer) OWNER TO postgres;

--
-- Name: sp_sync_matrix(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_sync_matrix() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  conv jsonb;
begin
  if new.strategy_matrix_v2 is not null
     and (tg_op = 'INSERT' or new.strategy_matrix_v2 is distinct from old.strategy_matrix_v2) then
    begin
      conv := sp_v2_to_app_matrix(new.strategy_matrix_v2);
      if conv is not null then
        new.strategy_matrix := conv;
      end if;
    exception when others then
      null;   -- never block a solver write because of a conversion problem
    end;
  end if;
  return new;
end
$$;


ALTER FUNCTION public.sp_sync_matrix() OWNER TO postgres;

--
-- Name: sp_theme_asset_is_owned(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_theme_asset_is_owned(p_user_id uuid, p_category text, p_asset_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tier text;
  v_is_vip boolean;
BEGIN
  SELECT tier INTO v_tier
    FROM public.cosmetic_catalog
   WHERE category = p_category AND asset_id = p_asset_id;

  IF v_tier IS NULL THEN RETURN false; END IF;
  IF v_tier = 'free' THEN RETURN true; END IF;

  SELECT COALESCE(p.is_vip, false)
         AND (p.vip_tier = 'lifetime' OR p.vip_expires_at IS NULL OR p.vip_expires_at > now())
    INTO v_is_vip
    FROM public.profiles p
   WHERE p.id = p_user_id;

  IF COALESCE(v_is_vip, false) THEN RETURN true; END IF;

  IF p_category = 'cards_id' AND EXISTS (
    SELECT 1
      FROM public.feature_purchases fp
     WHERE fp.user_id = p_user_id
       AND fp.feature = 'card_back_' || p_asset_id
  ) THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
      FROM public.theme_asset_unlocks u
     WHERE u.user_id = p_user_id
       AND u.category = p_category
       AND u.asset_id = p_asset_id
  );
END;
$$;


ALTER FUNCTION public.sp_theme_asset_is_owned(p_user_id uuid, p_category text, p_asset_id text) OWNER TO postgres;

--
-- Name: sp_v2_to_app_matrix(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_v2_to_app_matrix(v2 jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  codes text[];
  res   jsonb;
begin
  if v2 is null or jsonb_typeof(v2->'frequencies') <> 'object' then
    return null;
  end if;

  if jsonb_typeof(v2->'actions') = 'array' and jsonb_array_length(v2->'actions') > 0 then
    select array_agg(case when jsonb_typeof(e) = 'string' then e #>> '{}' else e->>'code' end order by ord)
      into codes
      from jsonb_array_elements(v2->'actions') with ordinality t(e, ord);
  else
    select array_agg(k order by k) into codes
      from jsonb_object_keys(v2->'frequencies') k;
  end if;

  codes := array_remove(codes, null);
  if codes is null or array_length(codes, 1) is null then
    return null;
  end if;

  with per as (
    select c.code,
           g.idx,
           coalesce((v2->'frequencies'->c.code->g.idx)::text::numeric, 0) as v
      from unnest(codes) c(code)
      cross join generate_series(0, 1325) g(idx)
  ),
  live as (
    select idx from per group by idx having sum(v) > 0.001
  ),
  agg as (
    select m.cls, p.code, sum(p.v) as sv
      from per p
      join live l on l.idx = p.idx
      join sp_combo_class m on m.idx = p.idx
     group by m.cls, p.code
  ),
  tot as (
    select cls, sum(sv) as s from agg group by cls
  ),
  freq as (
    select jsonb_object_agg(code, obj) as f
      from (select a.code, jsonb_object_agg(a.cls, round(a.sv / nullif(t.s, 0), 6)) as obj
              from agg a join tot t on t.cls = a.cls
             group by a.code) z
  ),
  evs as (
    select m.cls, avg(e.val::numeric) as ev
      from jsonb_array_elements_text(
             case when jsonb_typeof(v2->'hand_evs_bb') = 'array' then v2->'hand_evs_bb' else '[]'::jsonb end
           ) with ordinality e(val, ord)
      join sp_combo_class m on m.idx = e.ord - 1
      join live l on l.idx = m.idx
     where e.val is not null
     group by m.cls
  )
  select jsonb_build_object(
           'actions',        to_jsonb(codes),
           'frequencies',    coalesce((select f from freq), '{}'::jsonb),
           'hand_evs',       coalesce((select jsonb_object_agg(cls, round(ev, 6)) from evs), '{}'::jsonb),
           'ev_ip',          v2->'ev_ip_bb',
           'ev_oop',         v2->'ev_oop_bb',
           'exploitability', v2->'exploitability_pct',
           'board',          v2->'board',
           'node',           v2->'node',
           'street',         v2->'street',
           'source',         to_jsonb('pio_v2'::text),
           '__sanitized',    to_jsonb(true)
         )
    into res;

  return res;
end
$$;


ALTER FUNCTION public.sp_v2_to_app_matrix(v2 jsonb) OWNER TO postgres;

--
-- Name: spin_pool_deposit(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.spin_pool_deposit(p_club_id uuid, p_amount numeric) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO spin_bonus_pools (club_id, balance, total_deposited, spin_count)
  VALUES (p_club_id, p_amount, p_amount, 1)
  ON CONFLICT (club_id) DO UPDATE SET
    balance = spin_bonus_pools.balance + p_amount,
    total_deposited = spin_bonus_pools.total_deposited + p_amount,
    spin_count = spin_bonus_pools.spin_count + 1,
    updated_at = NOW();
END;
$$;


ALTER FUNCTION public.spin_pool_deposit(p_club_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: spin_pool_draw(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.spin_pool_draw(p_club_id uuid, p_amount numeric) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$ DECLARE v_balance numeric; v_actual_draw numeric; v_max_negative numeric := -500; BEGIN SELECT balance INTO v_balance FROM spin_bonus_pools WHERE club_id = p_club_id FOR UPDATE; IF NOT FOUND THEN RETURN 0; END IF; v_actual_draw := LEAST(p_amount, v_balance - v_max_negative); IF v_actual_draw <= 0 THEN RETURN 0; END IF; UPDATE spin_bonus_pools SET balance = balance - v_actual_draw, total_drawn = total_drawn + v_actual_draw, bonus_count = bonus_count + 1, updated_at = now() WHERE club_id = p_club_id; RETURN v_actual_draw; END; $$;


ALTER FUNCTION public.spin_pool_draw(p_club_id uuid, p_amount numeric) OWNER TO postgres;

--
-- Name: start_home_game_player_dm(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_home_game_player_dm(p_game_id uuid, p_from_user_id uuid, p_to_user_id uuid, p_initial_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
    v_caller uuid := auth.uid();
    v_role text := auth.role();
    v_group_id uuid;
    v_game_host uuid;
    v_from_member record;
    v_to_member record;
    v_from_in_game boolean;
    v_to_in_game boolean;
    v_conv jsonb;
    v_conv_id uuid;
    v_msg jsonb;
    v_trim text;
BEGIN
    -- 1. Input sanity
    IF p_game_id IS NULL OR p_from_user_id IS NULL OR p_to_user_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'MISSING_PARAMS');
    END IF;

    IF p_from_user_id = p_to_user_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'SELF_DM');
    END IF;

    -- 2. Auth: caller must match p_from_user_id (service_role bypasses)
    IF v_role IS DISTINCT FROM 'service_role' THEN
      IF v_caller IS NULL OR v_caller <> p_from_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'AUTH_MISMATCH');
      END IF;
    END IF;

    -- 3. Look up game + host
    SELECT group_id, host_id
      INTO v_group_id, v_game_host
      FROM commander_home_games
     WHERE id = p_game_id;

    IF v_group_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'GAME_NOT_FOUND');
    END IF;

    -- 4. Verify both users are approved, non-banned members of this group
    SELECT role, status INTO v_from_member
      FROM commander_home_members
     WHERE group_id = v_group_id AND user_id = p_from_user_id;

    SELECT role, status INTO v_to_member
      FROM commander_home_members
     WHERE group_id = v_group_id AND user_id = p_to_user_id;

    IF v_from_member IS NULL OR v_from_member.status <> 'approved' THEN
      RETURN jsonb_build_object('success', false, 'error', 'FROM_NOT_APPROVED_MEMBER');
    END IF;

    IF v_to_member IS NULL OR v_to_member.status <> 'approved' THEN
      RETURN jsonb_build_object('success', false, 'error', 'TO_NOT_APPROVED_MEMBER');
    END IF;

    IF v_from_member.status = 'banned' OR v_to_member.status = 'banned' THEN
      RETURN jsonb_build_object('success', false, 'error', 'BANNED');
    END IF;

    -- 5. Require game-context: at least one party must be tied to this game.
    v_from_in_game := (
      v_game_host = p_from_user_id
      OR EXISTS (SELECT 1 FROM commander_home_rsvps
                  WHERE game_id = p_game_id AND user_id = p_from_user_id
                    AND response = 'yes')
      OR EXISTS (SELECT 1 FROM commander_home_seats
                  WHERE game_id = p_game_id AND user_id = p_from_user_id
                    AND status <> 'empty')
    );

    v_to_in_game := (
      v_game_host = p_to_user_id
      OR EXISTS (SELECT 1 FROM commander_home_rsvps
                  WHERE game_id = p_game_id AND user_id = p_to_user_id
                    AND response = 'yes')
      OR EXISTS (SELECT 1 FROM commander_home_seats
                  WHERE game_id = p_game_id AND user_id = p_to_user_id
                    AND status <> 'empty')
    );

    IF NOT (v_from_in_game OR v_to_in_game) THEN
      RETURN jsonb_build_object('success', false, 'error', 'NO_GAME_RELATIONSHIP');
    END IF;

    -- 6. Get or create the 1:1 conversation via existing helper
    v_conv := public.fn_get_or_create_conversation(p_from_user_id, p_to_user_id);
    IF NOT COALESCE((v_conv->>'success')::boolean, false) THEN
      RETURN jsonb_build_object('success', false,
                                'error', 'CONVERSATION_FAILED',
                                'detail', v_conv);
    END IF;
    v_conv_id := (v_conv->>'conversation_id')::uuid;

    -- 7. Seed with initial message if caller provided one
    v_trim := NULLIF(TRIM(COALESCE(p_initial_message, '')), '');
    IF v_trim IS NOT NULL THEN
      IF length(v_trim) > 4000 THEN
        RETURN jsonb_build_object('success', false, 'error', 'MESSAGE_TOO_LONG');
      END IF;
      v_msg := public.fn_send_message(v_conv_id, p_from_user_id, v_trim, 'text');
      IF NOT COALESCE((v_msg->>'success')::boolean, false) THEN
        -- conversation exists but message failed - still useful, tell caller
        RETURN jsonb_build_object(
          'success', true,
          'conversation_id', v_conv_id,
          'created', COALESCE((v_conv->>'created')::boolean, false),
          'message_sent', false,
          'message_error', v_msg
        );
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'conversation_id', v_conv_id,
      'created', COALESCE((v_conv->>'created')::boolean, false),
      'message_sent', v_trim IS NOT NULL,
      'context_game_id', p_game_id
    );
END;
$$;


ALTER FUNCTION public.start_home_game_player_dm(p_game_id uuid, p_from_user_id uuid, p_to_user_id uuid, p_initial_message text) OWNER TO postgres;

--
-- Name: FUNCTION start_home_game_player_dm(p_game_id uuid, p_from_user_id uuid, p_to_user_id uuid, p_initial_message text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.start_home_game_player_dm(p_game_id uuid, p_from_user_id uuid, p_to_user_id uuid, p_initial_message text) IS 'Phase 40: one-call DM opener for the game manage / seating UI. Verifies caller identity, group-approved-member status on both sides, and requires at least one party to be host/yes-RSVP/seat-holder of the specified game so the feature can''t be abused as a free member directory.';


--
-- Name: start_home_group_roster_dm(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_home_group_roster_dm(p_group_id uuid, p_from_user_id uuid, p_to_user_id uuid, p_initial_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
    v_caller  uuid := auth.uid();
    v_role    text := auth.role();
    v_is_staff boolean;
    v_to_is_member boolean;
    v_to_is_follower boolean;
    v_to_banned boolean;
    v_conv jsonb; v_conv_id uuid;
    v_msg jsonb; v_trim text;
BEGIN
    IF p_group_id IS NULL OR p_from_user_id IS NULL OR p_to_user_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'MISSING_PARAMS');
    END IF;
    IF p_from_user_id = p_to_user_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'SELF_DM');
    END IF;

    IF v_role IS DISTINCT FROM 'service_role' THEN
      IF v_caller IS NULL OR v_caller <> p_from_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'AUTH_MISMATCH');
      END IF;
    END IF;

    -- Caller must be host/owner/admin of the group
    v_is_staff := EXISTS (
      SELECT 1 FROM commander_home_groups
       WHERE id = p_group_id AND owner_id = p_from_user_id
    ) OR EXISTS (
      SELECT 1 FROM commander_home_members
       WHERE group_id = p_group_id AND user_id = p_from_user_id
         AND role = 'admin' AND status = 'approved'
    );

    IF NOT v_is_staff THEN
      RETURN jsonb_build_object('success', false, 'error', 'NOT_GROUP_STAFF');
    END IF;

    -- Target must be an approved member OR follower; not banned
    v_to_banned := EXISTS (
      SELECT 1 FROM commander_home_members
       WHERE group_id = p_group_id AND user_id = p_to_user_id AND status = 'banned'
    );
    IF v_to_banned THEN
      RETURN jsonb_build_object('success', false, 'error', 'TARGET_BANNED');
    END IF;

    v_to_is_member := EXISTS (
      SELECT 1 FROM commander_home_members
       WHERE group_id = p_group_id AND user_id = p_to_user_id AND status = 'approved'
    );
    v_to_is_follower := EXISTS (
      SELECT 1 FROM commander_home_group_follows
       WHERE group_id = p_group_id AND user_id = p_to_user_id
    );

    IF NOT (v_to_is_member OR v_to_is_follower) THEN
      RETURN jsonb_build_object('success', false, 'error', 'TARGET_NOT_IN_ROSTER');
    END IF;

    -- Validate initial message length up-front
    v_trim := NULLIF(TRIM(COALESCE(p_initial_message, '')), '');
    IF v_trim IS NOT NULL AND length(v_trim) > 4000 THEN
      RETURN jsonb_build_object('success', false, 'error', 'MESSAGE_TOO_LONG');
    END IF;

    -- Get/create conversation
    v_conv := public.fn_get_or_create_conversation(p_from_user_id, p_to_user_id);
    IF NOT COALESCE((v_conv->>'success')::boolean, false) THEN
      RETURN jsonb_build_object('success', false,
                                'error', 'CONVERSATION_FAILED',
                                'detail', v_conv);
    END IF;
    v_conv_id := (v_conv->>'conversation_id')::uuid;

    -- Seed message if provided
    IF v_trim IS NOT NULL THEN
      v_msg := public.fn_send_message(v_conv_id, p_from_user_id, v_trim, 'text');
      IF NOT COALESCE((v_msg->>'success')::boolean, false) THEN
        RETURN jsonb_build_object(
          'success', true,
          'conversation_id', v_conv_id,
          'created', COALESCE((v_conv->>'created')::boolean, false),
          'message_sent', false,
          'target_relationship',
            CASE WHEN v_to_is_member AND v_to_is_follower THEN 'both'
                 WHEN v_to_is_member THEN 'member'
                 ELSE 'follower' END,
          'message_error', v_msg
        );
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'conversation_id', v_conv_id,
      'created', COALESCE((v_conv->>'created')::boolean, false),
      'message_sent', v_trim IS NOT NULL,
      'target_relationship',
        CASE WHEN v_to_is_member AND v_to_is_follower THEN 'both'
             WHEN v_to_is_member THEN 'member'
             ELSE 'follower' END,
      'context_group_id', p_group_id
    );
END;
$$;


ALTER FUNCTION public.start_home_group_roster_dm(p_group_id uuid, p_from_user_id uuid, p_to_user_id uuid, p_initial_message text) OWNER TO postgres;

--
-- Name: FUNCTION start_home_group_roster_dm(p_group_id uuid, p_from_user_id uuid, p_to_user_id uuid, p_initial_message text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.start_home_group_roster_dm(p_group_id uuid, p_from_user_id uuid, p_to_user_id uuid, p_initial_message text) IS 'Phase 40: host opens/reuses a DM with any roster member (approved member or follower). Bidirectional — follower replies via social_messages RLS.';


--
-- Name: start_or_resume_pa_leak_audit_job(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_or_resume_pa_leak_audit_job(p_user_id uuid) RETURNS SETOF public.pa_leak_audit_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_job public.pa_leak_audit_jobs%ROWTYPE;
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'user_id required'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('pa_leak_audit:' || p_user_id::text, 0));

  SELECT * INTO v_job
    FROM public.pa_leak_audit_jobs
   WHERE user_id = p_user_id AND status IN ('queued', 'running')
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE;

  IF FOUND THEN
    IF v_job.status = 'running' AND COALESCE(v_job.lease_expires_at, '-infinity'::timestamptz) <= now() THEN
      UPDATE public.pa_leak_audit_jobs
         SET status = 'queued', stage = 'recovering', worker_token = NULL,
             lease_expires_at = NULL, queued_at = now(), updated_at = now()
       WHERE id = v_job.id
       RETURNING * INTO v_job;
    END IF;
    RETURN NEXT v_job;
    RETURN;
  END IF;

  -- A failed job with a valid persisted checkpoint resumes idempotently.
  SELECT * INTO v_job
    FROM public.pa_leak_audit_jobs
   WHERE user_id = p_user_id
     AND status = 'failed'
     AND audit_cursor IS NOT NULL
     AND updated_at >= now() - interval '7 days'
   ORDER BY updated_at DESC
   LIMIT 1
   FOR UPDATE;

  IF FOUND THEN
    UPDATE public.pa_leak_audit_jobs
       SET status = 'queued', stage = 'recovering', worker_token = NULL,
           lease_expires_at = NULL, error_code = NULL, error_message = NULL,
           queued_at = now(), completed_at = NULL, updated_at = now()
     WHERE id = v_job.id
     RETURNING * INTO v_job;
    RETURN NEXT v_job;
    RETURN;
  END IF;

  INSERT INTO public.pa_leak_audit_jobs(user_id)
  VALUES (p_user_id)
  RETURNING * INTO v_job;
  RETURN NEXT v_job;
END;
$$;


ALTER FUNCTION public.start_or_resume_pa_leak_audit_job(p_user_id uuid) OWNER TO postgres;

--
-- Name: start_verified_leak_drill(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.start_verified_leak_drill(p_user_id uuid, p_leak_id text, p_batch_id uuid, p_question_ids jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_session public.leak_drill_sessions%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_batch_id IS NULL
     OR p_leak_id !~ '^[A-Za-z0-9][A-Za-z0-9_:.-]{0,63}$'
     OR jsonb_typeof(COALESCE(p_question_ids, 'null'::jsonb)) <> 'array'
     OR jsonb_array_length(p_question_ids) NOT BETWEEN 5 AND 20
     OR (SELECT count(*) FROM jsonb_array_elements_text(p_question_ids))
        <> (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(p_question_ids)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_payload');
  END IF;

  -- Global quota and per-leak numbering use a consistent lock order.
  PERFORM pg_advisory_xact_lock(hashtextextended('leak_drill_user:' || p_user_id::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('leak_drill:' || p_user_id::text || ':' || p_leak_id, 0));

  SELECT * INTO v_session FROM public.leak_drill_sessions WHERE batch_id = p_batch_id;
  IF FOUND THEN
    RETURN jsonb_build_object('success', v_session.user_id = p_user_id AND v_session.leak_id = p_leak_id,
      'idempotent', true, 'session', to_jsonb(v_session));
  END IF;
  IF (SELECT count(*) FROM public.leak_drill_sessions WHERE user_id = p_user_id) >= 5000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'session_quota_reached');
  END IF;

  -- Only deterministic, server-owned solver signals can start a verified run.
  PERFORM 1 FROM public.user_leaks
   WHERE user_id = p_user_id AND id::text = p_leak_id
     AND detector_managed = true AND source_system = 'solver_engine'
     AND leak_type ~ '^solver_(training|club_arena)_' AND status IS DISTINCT FROM 'resolved'
     AND is_active IS DISTINCT FROM false FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'ineligible_leak'); END IF;

  -- Merely loading or abandoning a drill does not consume an attempt. The
  -- number is reserved atomically with the first locked answer below.
  INSERT INTO public.leak_drill_sessions(batch_id, user_id, leak_id, question_ids)
    VALUES (p_batch_id, p_user_id, p_leak_id, p_question_ids) RETURNING * INTO v_session;
  RETURN jsonb_build_object('success', true, 'idempotent', false, 'session', to_jsonb(v_session));
END;
$_$;


ALTER FUNCTION public.start_verified_leak_drill(p_user_id uuid, p_leak_id text, p_batch_id uuid, p_question_ids jsonb) OWNER TO postgres;

--
-- Name: store_idempotency_result(text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.store_idempotency_result(p_key text, p_result jsonb, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.idempotency_keys
  SET
    status       = CASE WHEN p_error IS NULL THEN 'completed' ELSE 'errored' END,
    result       = p_result,
    error        = p_error,
    completed_at = NOW()
  WHERE key = p_key AND status = 'in_flight';
END;
$$;


ALTER FUNCTION public.store_idempotency_result(p_key text, p_result jsonb, p_error text) OWNER TO postgres;

--
-- Name: FUNCTION store_idempotency_result(p_key text, p_result jsonb, p_error text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.store_idempotency_result(p_key text, p_result jsonb, p_error text) IS 'Phase 4.1.3: persist final result for an in-flight idempotency key.';


--
-- Name: submit_home_ban_appeal(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_home_ban_appeal(p_group_id uuid, p_appeal_text text, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_member RECORD;
  v_id uuid;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED';
  END IF;
  IF p_appeal_text IS NULL OR length(trim(p_appeal_text)) < 1 THEN
    RAISE EXCEPTION 'APPEAL_TEXT_REQUIRED';
  END IF;
  IF length(p_appeal_text) > 2000 THEN
    RAISE EXCEPTION 'APPEAL_TEXT_TOO_LONG' USING HINT = 'max 2000 chars';
  END IF;

  SELECT * INTO v_member FROM public.commander_home_members
   WHERE group_id = p_group_id AND user_id = p_caller_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_A_MEMBER'; END IF;
  IF v_member.status <> 'banned' THEN
    RAISE EXCEPTION 'NOT_BANNED' USING HINT = 'only banned members can appeal';
  END IF;

  INSERT INTO public.commander_home_ban_appeals
    (group_id, member_id, user_id, appeal_text)
  VALUES
    (p_group_id, v_member.id, p_caller_user_id, trim(p_appeal_text))
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('success', true, 'appeal_id', v_id);
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'APPEAL_ALREADY_PENDING';
END;
$$;


ALTER FUNCTION public.submit_home_ban_appeal(p_group_id uuid, p_appeal_text text, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: submit_venue_claim_request(integer, uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_venue_claim_request(p_venue_id integer, p_caller_user_id uuid, p_verification_method text, p_claimant_name text, p_claimant_title text, p_claimant_email text, p_claimant_phone text DEFAULT NULL::text, p_claimant_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_venue RECORD; v_existing_claim RECORD; v_claim_id uuid; v_verification_code text;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN 
        RAISE EXCEPTION 'UNAUTHORIZED'; 
    END IF;
    IF p_verification_method NOT IN ('email_domain','phone_match','document','business_license','admin_review') THEN
        RAISE EXCEPTION 'INVALID_VERIFICATION_METHOD';
    END IF;
    IF p_claimant_name IS NULL OR length(trim(p_claimant_name)) = 0 THEN 
        RAISE EXCEPTION 'CLAIMANT_NAME_REQUIRED'; 
    END IF;
    IF p_claimant_email IS NULL OR p_claimant_email !~ '^[^@]+@[^@]+\.[^@]+$' THEN
        RAISE EXCEPTION 'INVALID_EMAIL';
    END IF;

    SELECT id, name, is_claimed, claimed_by INTO v_venue 
      FROM poker_venues WHERE id = p_venue_id 
       AND COALESCE(is_active, true) AND NOT COALESCE(is_suppressed, false);
    IF NOT FOUND THEN RAISE EXCEPTION 'VENUE_NOT_FOUND'; END IF;
    IF v_venue.is_claimed = true AND v_venue.claimed_by <> p_caller_user_id THEN
        RAISE EXCEPTION 'VENUE_ALREADY_CLAIMED';
    END IF;

    SELECT id, status INTO v_existing_claim FROM venue_claims
     WHERE venue_id = p_venue_id AND user_id = p_caller_user_id
       AND status IN ('pending','under_review')
     LIMIT 1;
    IF FOUND THEN
        RETURN jsonb_build_object(
            'success', false, 'error', 'DUPLICATE_PENDING_CLAIM',
            'claim_id', v_existing_claim.id, 'status', v_existing_claim.status
        );
    END IF;

    -- Generate 8-char hex verification code using md5 (always available)
    v_verification_code := upper(substring(md5(random()::text || clock_timestamp()::text), 1, 8));

    INSERT INTO venue_claims (
        venue_id, user_id, status, verification_method,
        claimant_name, claimant_title, claimant_email, claimant_phone,
        verification_code, verification_attempts, claimant_notes
    ) VALUES (
        p_venue_id, p_caller_user_id, 'pending', p_verification_method,
        p_claimant_name, p_claimant_title, p_claimant_email, p_claimant_phone,
        v_verification_code, 0, p_claimant_notes
    ) RETURNING id INTO v_claim_id;

    RETURN jsonb_build_object(
        'success', true, 'claim_id', v_claim_id, 'venue_id', p_venue_id,
        'venue_name', v_venue.name, 'status', 'pending',
        'verification_method', p_verification_method,
        'verification_code', v_verification_code,
        'message', 'Claim submitted. Admin will review and contact you at ' || p_claimant_email
    );
END; $_$;


ALTER FUNCTION public.submit_venue_claim_request(p_venue_id integer, p_caller_user_id uuid, p_verification_method text, p_claimant_name text, p_claimant_title text, p_claimant_email text, p_claimant_phone text, p_claimant_notes text) OWNER TO postgres;

--
-- Name: FUNCTION submit_venue_claim_request(p_venue_id integer, p_caller_user_id uuid, p_verification_method text, p_claimant_name text, p_claimant_title text, p_claimant_email text, p_claimant_phone text, p_claimant_notes text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.submit_venue_claim_request(p_venue_id integer, p_caller_user_id uuid, p_verification_method text, p_claimant_name text, p_claimant_title text, p_claimant_email text, p_claimant_phone text, p_claimant_notes text) IS 'Phase 29/D: Submit a claim to manage a venue page. No money. Admin approval required.';


--
-- Name: submit_venue_review(integer, uuid, integer, text, text, integer, integer, integer, integer, date, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_venue_review(p_venue_id integer, p_caller_user_id uuid, p_overall_rating integer, p_title text DEFAULT NULL::text, p_content text DEFAULT NULL::text, p_game_selection_rating integer DEFAULT NULL::integer, p_staff_rating integer DEFAULT NULL::integer, p_atmosphere_rating integer DEFAULT NULL::integer, p_food_rating integer DEFAULT NULL::integer, p_visit_date date DEFAULT NULL::date, p_games_played text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE 
    v_venue RECORD; v_id uuid; v_visited boolean; v_recent_count int; v_existing uuid;
    v_tmp_rating int;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    IF p_overall_rating NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'INVALID_OVERALL_RATING'; END IF;
    FOREACH v_tmp_rating IN ARRAY ARRAY[p_game_selection_rating, p_staff_rating, p_atmosphere_rating, p_food_rating] LOOP
        IF v_tmp_rating IS NOT NULL AND v_tmp_rating NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'INVALID_SUBRATING'; END IF;
    END LOOP;
    IF p_content IS NOT NULL AND length(p_content) > 5000 THEN RAISE EXCEPTION 'CONTENT_TOO_LONG'; END IF;

    SELECT id, name INTO v_venue FROM poker_venues WHERE id = p_venue_id 
       AND COALESCE(is_active,true) AND NOT COALESCE(is_suppressed,false);
    IF NOT FOUND THEN RAISE EXCEPTION 'VENUE_NOT_FOUND'; END IF;

    SELECT id INTO v_existing FROM commander_venue_reviews 
     WHERE venue_id = p_venue_id AND reviewer_id = p_caller_user_id;

    SELECT COUNT(*) INTO v_recent_count FROM commander_venue_reviews 
     WHERE reviewer_id = p_caller_user_id AND created_at > NOW() - INTERVAL '24 hours';
    IF v_recent_count >= 10 THEN RAISE EXCEPTION 'RATE_LIMITED'; END IF;

    -- Phase 31D: venue_id and user_id are both now typed correctly; no casts.
    SELECT EXISTS(SELECT 1 FROM venue_checkins 
                   WHERE venue_id = p_venue_id AND user_id = p_caller_user_id) INTO v_visited;

    IF v_existing IS NOT NULL THEN
        UPDATE commander_venue_reviews 
           SET overall_rating = p_overall_rating, title = COALESCE(p_title, title),
               content = COALESCE(p_content, content),
               game_selection_rating = COALESCE(p_game_selection_rating, game_selection_rating),
               staff_rating = COALESCE(p_staff_rating, staff_rating),
               atmosphere_rating = COALESCE(p_atmosphere_rating, atmosphere_rating),
               food_rating = COALESCE(p_food_rating, food_rating),
               visit_date = COALESCE(p_visit_date, visit_date),
               games_played = COALESCE(p_games_played, games_played),
               is_verified = v_visited, updated_at = NOW()
         WHERE id = v_existing;
        RETURN jsonb_build_object('success', true, 'review_id', v_existing, 'updated', true);
    END IF;

    INSERT INTO commander_venue_reviews (
        venue_id, reviewer_id, overall_rating, title, content,
        game_selection_rating, staff_rating, atmosphere_rating, food_rating,
        visit_date, games_played, is_verified, is_published
    ) VALUES (
        p_venue_id, p_caller_user_id, p_overall_rating, p_title, p_content,
        p_game_selection_rating, p_staff_rating, p_atmosphere_rating, p_food_rating,
        p_visit_date, p_games_played, v_visited, true
    ) RETURNING id INTO v_id;

    RETURN jsonb_build_object('success', true, 'review_id', v_id, 'is_verified', v_visited);
END; $$;


ALTER FUNCTION public.submit_venue_review(p_venue_id integer, p_caller_user_id uuid, p_overall_rating integer, p_title text, p_content text, p_game_selection_rating integer, p_staff_rating integer, p_atmosphere_rating integer, p_food_rating integer, p_visit_date date, p_games_played text[]) OWNER TO postgres;

--
-- Name: sum_agent_volume(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sum_agent_volume(p_club_id uuid, p_agent_id uuid, p_start timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_total bigint;
BEGIN
    SELECT COALESCE(SUM(ABS(amount)), 0) INTO v_total
    FROM public.action_audit_logs
    WHERE club_id = p_club_id AND user_id = p_agent_id AND created_at >= p_start;
    RETURN v_total;
END;
$$;


ALTER FUNCTION public.sum_agent_volume(p_club_id uuid, p_agent_id uuid, p_start timestamp with time zone) OWNER TO postgres;

