--
-- Name: sum_chip_transactions(uuid, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sum_chip_transactions(p_club_id uuid, p_type text, p_start timestamp with time zone, p_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_total bigint;
BEGIN
    IF p_end IS NOT NULL THEN
        SELECT COALESCE(SUM(amount), 0) INTO v_total
        FROM public.chip_transactions
        WHERE club_id = p_club_id AND transaction_type = p_type
          AND created_at >= p_start AND created_at < p_end;
    ELSE
        SELECT COALESCE(SUM(amount), 0) INTO v_total
        FROM public.chip_transactions
        WHERE club_id = p_club_id AND transaction_type = p_type AND created_at >= p_start;
    END IF;
    RETURN v_total;
END;
$$;


