--
-- Name: sync_agent_wallet_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_agent_wallet_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$ BEGIN IF NEW.agent_wallet_balance IS DISTINCT FROM OLD.agent_wallet_balance THEN NEW.business_balance := NEW.agent_wallet_balance; ELSIF NEW.business_balance IS DISTINCT FROM OLD.business_balance THEN NEW.agent_wallet_balance := NEW.business_balance; END IF; IF NEW.player_wallet_balance IS DISTINCT FROM OLD.player_wallet_balance THEN NEW.player_balance := NEW.player_wallet_balance; ELSIF NEW.player_balance IS DISTINCT FROM OLD.player_balance THEN NEW.player_wallet_balance := NEW.player_balance; END IF; IF NEW.promo_wallet_balance IS DISTINCT FROM OLD.promo_wallet_balance THEN NEW.promo_balance := NEW.promo_wallet_balance; ELSIF NEW.promo_balance IS DISTINCT FROM OLD.promo_balance THEN NEW.promo_wallet_balance := NEW.promo_balance; END IF; RETURN NEW; END; $$;


ALTER FUNCTION public.sync_agent_wallet_columns() OWNER TO postgres;

--
-- Name: sync_home_group_to_social_page(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_home_group_to_social_page() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.social_pages sp
  SET owner_id      = NEW.owner_id,   -- Phase 40: keep owner in step
      name          = NEW.name,
      description   = coalesce(NEW.description, NEW.tagline, sp.description),
      avatar_url    = coalesce(NEW.profile_photo_url, sp.avatar_url),
      cover_url     = coalesce(NEW.cover_photo_url, sp.cover_url),
      location_city = NEW.city,
      location_state= NEW.state,
      is_public     = (coalesce(NEW.is_active, true) AND NOT coalesce(NEW.is_private, false)),
      metadata      = coalesce(sp.metadata, '{}'::jsonb) || jsonb_build_object(
        'home_group_id', NEW.id,
        'invite_code', NEW.invite_code,
        'club_code', NEW.club_code,
        'default_game_type', NEW.default_game_type,
        'default_stakes', NEW.default_stakes,
        'frequency', NEW.frequency
      ),
      updated_at    = now()
  WHERE sp.linked_entity_type = 'home_group'
    AND sp.linked_entity_id = NEW.id::text;

  IF NOT FOUND THEN
    INSERT INTO public.social_pages (
      owner_id, page_type, name, slug, description,
      avatar_url, cover_url, category,
      location_city, location_state, location_country,
      linked_entity_type, linked_entity_id,
      is_public, allow_member_posts, require_post_approval, metadata
    ) VALUES (
      NEW.owner_id, 'home_game', NEW.name,
      public.unique_home_game_slug(NEW.name),
      coalesce(NEW.description, NEW.tagline, ''),
      NEW.profile_photo_url, NEW.cover_photo_url, 'home game',
      NEW.city, NEW.state, 'US',
      'home_group', NEW.id::text,
      (coalesce(NEW.is_active, true) AND NOT coalesce(NEW.is_private, false)),
      true, false,
      jsonb_build_object(
        'home_group_id', NEW.id,
        'invite_code', NEW.invite_code,
        'club_code', NEW.club_code,
        'default_game_type', NEW.default_game_type,
        'default_stakes', NEW.default_stakes,
        'frequency', NEW.frequency
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_home_group_to_social_page() OWNER TO postgres;

--
-- Name: sync_notification_read_state(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_notification_read_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_read boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_read := COALESCE(NEW.read_at IS NOT NULL, false) OR COALESCE(NEW.is_read, false) OR COALESCE(NEW.read, false);
  ELSE
    IF (NEW.read_at IS DISTINCT FROM OLD.read_at) THEN v_read := NEW.read_at IS NOT NULL;
    ELSIF (NEW.is_read IS DISTINCT FROM OLD.is_read) THEN v_read := COALESCE(NEW.is_read, false);
    ELSIF (NEW.read IS DISTINCT FROM OLD.read) THEN v_read := COALESCE(NEW.read, false);
    ELSE v_read := COALESCE(NEW.read_at IS NOT NULL, false) OR COALESCE(NEW.is_read, false) OR COALESCE(NEW.read, false);
    END IF;
  END IF;
  NEW.is_read := v_read; NEW.read := v_read;
  IF v_read THEN NEW.read_at := COALESCE(NEW.read_at, now()); ELSE NEW.read_at := NULL; END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION public.sync_notification_read_state() OWNER TO postgres;

