-- Name: sync_tournament_chips(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_tournament_chips(p_tournament_id uuid, p_chip_data jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE rec jsonb;
BEGIN
  FOR rec IN SELECT * FROM jsonb_array_elements(p_chip_data) LOOP
    UPDATE commander_tournament_entries SET
      current_chips = (rec->>'chips')::integer,
      table_number = (rec->>'table_number')::integer,
      seat_number = (rec->>'seat_number')::integer,
      last_chip_count_at = now()
    WHERE id = (rec->>'entry_id')::uuid AND tournament_id = p_tournament_id AND status = 'active';
  END LOOP;
END;
$$;


