CREATE FUNCTION public.sync_tournament_state(p_tournament_id uuid, p_status text, p_current_level integer, p_players_remaining integer, p_current_entries integer, p_average_stack integer, p_total_chips_in_play integer, p_actual_prizepool integer, p_hands_played integer, p_tables_remaining integer, p_level_time_remaining integer, p_late_reg_open boolean) RETURNS void
