--
-- Name: sync_trivia_pvp_active_seats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_trivia_pvp_active_seats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    IF TG_OP IN ('UPDATE', 'DELETE') THEN
        DELETE FROM public.trivia_pvp_active_seats WHERE match_id = OLD.id;
    END IF;
    IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.status IN ('active', 'settling') THEN
        INSERT INTO public.trivia_pvp_active_seats (match_id, side, user_id)
        SELECT NEW.id, candidate.side, candidate.user_id
          FROM (VALUES (1::smallint, NEW.player1_id),
                       (2::smallint, NEW.player2_id)) AS candidate(side, user_id)
          JOIN public.profiles AS profile ON profile.id = candidate.user_id;
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.sync_trivia_pvp_active_seats() OWNER TO postgres;

--
-- Name: test_merch_reservation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.test_merch_reservation() RETURNS TABLE(test_name text, ok boolean, detail text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_item      text;
    v_variant   uuid;
    v_res       jsonb;
    v_before    integer;
    v_after     integer;
    v_ok        boolean;
    v_detail    text;
BEGIN
    -- A plain (non-variant) item with finite stock, and a variant, to test on.
    SELECT id INTO v_item FROM public.merchandise_items
     WHERE is_active AND NOT COALESCE(has_variants, false) AND stock IS NOT NULL
     ORDER BY id LIMIT 1;
    SELECT v.id INTO v_variant FROM public.merchandise_item_variants v
      JOIN public.merchandise_items i ON i.id = v.item_id
     WHERE i.is_active AND v.stock IS NOT NULL ORDER BY v.id LIMIT 1;

    IF v_item IS NULL THEN
        test_name := 'fixtures_available'; ok := false;
        detail := 'no active non-variant item with finite stock to test against';
        RETURN NEXT; RETURN;
    END IF;

    -- ── 1. A purchase decrements stock by exactly the quantity ────────────
    BEGIN
        v_ok := false; v_detail := '';
        BEGIN
            SELECT stock INTO v_before FROM public.merchandise_items WHERE id = v_item;
            v_res := public.reserve_merch_order(
                jsonb_build_array(jsonb_build_object('id', v_item, 'qty', 2)));
            SELECT stock INTO v_after FROM public.merchandise_items WHERE id = v_item;
            v_ok := (v_res->>'success')::boolean AND (v_before - v_after) = 2;
            v_detail := format('stock %s -> %s (expected -2)', v_before, v_after);
            RAISE EXCEPTION 'rollback_probe';
        EXCEPTION WHEN others THEN
            IF SQLERRM <> 'rollback_probe' THEN v_ok := false; v_detail := SQLERRM; END IF;
        END;
        test_name := 'purchase_decrements_stock'; ok := v_ok; detail := v_detail;
        RETURN NEXT;
    END;

    -- ── 2. Overselling is refused and reports availability ────────────────
    BEGIN
        v_ok := false; v_detail := '';
        BEGIN
            UPDATE public.merchandise_items SET stock = 1 WHERE id = v_item;
            v_res := public.reserve_merch_order(
                jsonb_build_array(jsonb_build_object('id', v_item, 'qty', 5)));
            SELECT stock INTO v_after FROM public.merchandise_items WHERE id = v_item;
            v_ok := (v_res->>'success')::boolean IS NOT TRUE
                AND v_res->>'error' = 'insufficient_stock'
                AND v_after = 1;   -- refused AND nothing taken
            v_detail := format('error=%s stock_after=%s', v_res->>'error', v_after);
            RAISE EXCEPTION 'rollback_probe';
        EXCEPTION WHEN others THEN
            IF SQLERRM <> 'rollback_probe' THEN v_ok := false; v_detail := SQLERRM; END IF;
        END;
        test_name := 'oversell_refused'; ok := v_ok; detail := v_detail;
        RETURN NEXT;
    END;

    -- ── 3. All-or-nothing: one bad line decrements NOTHING ────────────────
    BEGIN
        v_ok := false; v_detail := '';
        BEGIN
            UPDATE public.merchandise_items SET stock = 1 WHERE id = v_item;
            SELECT stock INTO v_before FROM public.merchandise_items WHERE id = v_item;
            v_res := public.reserve_merch_order(jsonb_build_array(
                jsonb_build_object('id', v_item, 'qty', 1),
                jsonb_build_object('id', 'definitely-not-a-real-item', 'qty', 1)));
            SELECT stock INTO v_after FROM public.merchandise_items WHERE id = v_item;
            v_ok := (v_res->>'success')::boolean IS NOT TRUE AND v_before = v_after;
            v_detail := format('error=%s stock %s -> %s (must be unchanged)',
                               v_res->>'error', v_before, v_after);
            RAISE EXCEPTION 'rollback_probe';
        EXCEPTION WHEN others THEN
            IF SQLERRM <> 'rollback_probe' THEN v_ok := false; v_detail := SQLERRM; END IF;
        END;
        test_name := 'partial_failure_takes_nothing'; ok := v_ok; detail := v_detail;
        RETURN NEXT;
    END;

    -- ── 4. Dry run prices WITHOUT taking stock (the card path) ────────────
    BEGIN
        v_ok := false; v_detail := '';
        BEGIN
            SELECT stock INTO v_before FROM public.merchandise_items WHERE id = v_item;
            v_res := public.reserve_merch_order(
                jsonb_build_array(jsonb_build_object('id', v_item, 'qty', 1)), true);
            SELECT stock INTO v_after FROM public.merchandise_items WHERE id = v_item;
            v_ok := (v_res->>'success')::boolean
                AND (v_res->>'dry_run')::boolean
                AND v_before = v_after
                AND (v_res->>'total_usd')::numeric > 0;
            v_detail := format('dry_run=%s stock %s -> %s total=%s',
                               v_res->>'dry_run', v_before, v_after, v_res->>'total_usd');
            RAISE EXCEPTION 'rollback_probe';
        EXCEPTION WHEN others THEN
            IF SQLERRM <> 'rollback_probe' THEN v_ok := false; v_detail := SQLERRM; END IF;
        END;
        test_name := 'dry_run_takes_no_stock'; ok := v_ok; detail := v_detail;
        RETURN NEXT;
    END;

    -- ── 5. Release hands the stock back (refund / failure compensation) ───
    BEGIN
        v_ok := false; v_detail := '';
        BEGIN
            SELECT stock INTO v_before FROM public.merchandise_items WHERE id = v_item;
            v_res := public.reserve_merch_order(
                jsonb_build_array(jsonb_build_object('id', v_item, 'qty', 3)));
            PERFORM public.release_merch_order(v_res->'lines');
            SELECT stock INTO v_after FROM public.merchandise_items WHERE id = v_item;
            v_ok := v_before = v_after;
            v_detail := format('stock %s -> %s after reserve+release (must match)', v_before, v_after);
            RAISE EXCEPTION 'rollback_probe';
        EXCEPTION WHEN others THEN
            IF SQLERRM <> 'rollback_probe' THEN v_ok := false; v_detail := SQLERRM; END IF;
        END;
        test_name := 'release_restores_stock'; ok := v_ok; detail := v_detail;
        RETURN NEXT;
    END;

    -- ── 6. An item with variants REFUSES a line with no variant_id ────────
    -- Apparel carries item-level stock = NULL, so without this guard exactly
    -- the size-based products would read as infinitely available.
    IF v_variant IS NOT NULL THEN
        BEGIN
            v_ok := false; v_detail := '';
            SELECT item_id INTO v_item FROM public.merchandise_item_variants WHERE id = v_variant;
            v_res := public.reserve_merch_order(
                jsonb_build_array(jsonb_build_object('id', v_item, 'qty', 1)));
            v_ok := (v_res->>'success')::boolean IS NOT TRUE
                AND v_res->>'error' = 'variant_required';
            v_detail := format('error=%s (expected variant_required)', v_res->>'error');
            test_name := 'variant_required_for_apparel'; ok := v_ok; detail := v_detail;
            RETURN NEXT;
        END;

        -- ── 7. A variant purchase decrements the VARIANT's stock ──────────
        BEGIN
            v_ok := false; v_detail := '';
            BEGIN
                SELECT stock INTO v_before FROM public.merchandise_item_variants WHERE id = v_variant;
                v_res := public.reserve_merch_order(jsonb_build_array(
                    jsonb_build_object('id', v_item, 'variant_id', v_variant, 'qty', 1)));
                SELECT stock INTO v_after FROM public.merchandise_item_variants WHERE id = v_variant;
                v_ok := (v_res->>'success')::boolean AND (v_before - v_after) = 1;
                v_detail := format('variant stock %s -> %s (expected -1)', v_before, v_after);
                RAISE EXCEPTION 'rollback_probe';
            EXCEPTION WHEN others THEN
                IF SQLERRM <> 'rollback_probe' THEN v_ok := false; v_detail := SQLERRM; END IF;
            END;
            test_name := 'variant_purchase_decrements_variant'; ok := v_ok; detail := v_detail;
            RETURN NEXT;
        END;
    END IF;

    RETURN;
END;
$$;


ALTER FUNCTION public.test_merch_reservation() OWNER TO postgres;

--
-- Name: FUNCTION test_merch_reservation(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.test_merch_reservation() IS 'Regression tests for reserve/release_merch_order. Each test mutates inside a subtransaction and rolls back, so it is safe to run against production. Called by scripts/check-economy-invariants.mjs in CI.';


--
-- Name: toggle_home_group_follow(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.toggle_home_group_follow(p_group_id uuid, p_caller_user_id uuid, p_follow boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE 
    v_group      RECORD;
    v_existing   RECORD;
    v_new_state  boolean;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    
    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;
    IF v_group.is_private THEN RAISE EXCEPTION 'CANNOT_FOLLOW_PRIVATE_GROUP'; END IF;

    -- Members don't need to follow; they already get notifications
    IF EXISTS (SELECT 1 FROM commander_home_members 
                WHERE group_id = p_group_id AND user_id = p_caller_user_id AND status='approved')
    THEN RAISE EXCEPTION 'ALREADY_MEMBER' USING HINT='members already receive notifications'; END IF;

    SELECT * INTO v_existing FROM commander_home_group_follows 
     WHERE group_id = p_group_id AND user_id = p_caller_user_id;

    v_new_state := CASE 
        WHEN p_follow IS NOT NULL THEN p_follow
        WHEN v_existing IS NULL THEN true
        ELSE false END;

    IF v_new_state THEN
        INSERT INTO commander_home_group_follows (group_id, user_id)
        VALUES (p_group_id, p_caller_user_id)
        ON CONFLICT (group_id, user_id) DO NOTHING;
    ELSE
        DELETE FROM commander_home_group_follows 
         WHERE group_id = p_group_id AND user_id = p_caller_user_id;
    END IF;

    RETURN jsonb_build_object('success', true, 'following', v_new_state);
END;
$$;


ALTER FUNCTION public.toggle_home_group_follow(p_group_id uuid, p_caller_user_id uuid, p_follow boolean) OWNER TO postgres;

--
-- Name: toggle_home_post_like(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.toggle_home_post_like(p_post_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_post        RECORD;
    v_group       RECORD;
    v_existing_id uuid;
    v_action      text;
    v_new_count   int;
    v_is_banned   boolean;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    IF NOT public.fn_try_consume_home_rate_limit(
         p_caller_user_id, 'home_post_like_toggle', 200, 60) THEN
      RAISE EXCEPTION 'RATE_LIMIT_EXCEEDED'
            USING HINT = 'like/unlike: 200 per 60 min.';
    END IF;

    SELECT * INTO v_post FROM commander_home_posts WHERE id = p_post_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'POST_NOT_FOUND'; END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_post.group_id;

    SELECT EXISTS (
      SELECT 1 FROM commander_home_members
       WHERE group_id = v_post.group_id AND user_id = p_caller_user_id AND status = 'banned'
    ) INTO v_is_banned;
    IF v_is_banned THEN RAISE EXCEPTION 'BANNED'; END IF;

    IF v_group.is_private
       AND v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members
                        WHERE group_id = v_post.group_id AND user_id = p_caller_user_id
                          AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;

    SELECT id INTO v_existing_id FROM commander_home_post_likes
     WHERE post_id = p_post_id AND user_id = p_caller_user_id;

    IF FOUND THEN
        DELETE FROM commander_home_post_likes WHERE id = v_existing_id;
        v_action := 'unliked';
    ELSE
        INSERT INTO commander_home_post_likes (post_id, user_id)
        VALUES (p_post_id, p_caller_user_id);
        v_action := 'liked';
    END IF;

    SELECT likes_count INTO v_new_count FROM commander_home_posts WHERE id = p_post_id;

    RETURN jsonb_build_object('success', true, 'action', v_action, 'likes_count', v_new_count);
END;
$$;


ALTER FUNCTION public.toggle_home_post_like(p_post_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION toggle_home_post_like(p_post_id uuid, p_caller_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.toggle_home_post_like(p_post_id uuid, p_caller_user_id uuid) IS 'Phase 40: explicit BANNED check. Banned users of public groups cannot like.';


--
-- Name: toggle_venue_post_pin(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.toggle_venue_post_pin(p_post_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_post RECORD; v_is_manager boolean;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    SELECT * INTO v_post FROM commander_venue_posts WHERE id = p_post_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'POST_NOT_FOUND'; END IF;
    v_is_manager := public.is_venue_manager(p_caller_user_id, v_post.venue_id);
    IF NOT v_is_manager THEN RAISE EXCEPTION 'NOT_VENUE_MANAGER'; END IF;
    UPDATE commander_venue_posts SET is_pinned = NOT is_pinned, updated_at = NOW() WHERE id = p_post_id;
    RETURN jsonb_build_object('success', true, 'is_pinned', NOT v_post.is_pinned);
END; $$;


ALTER FUNCTION public.toggle_venue_post_pin(p_post_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: toggle_venue_review_helpful(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.toggle_venue_review_helpful(p_review_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_exists boolean; v_count int; v_review_exists boolean;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    SELECT EXISTS(SELECT 1 FROM commander_venue_reviews WHERE id = p_review_id) INTO v_review_exists;
    IF NOT v_review_exists THEN RAISE EXCEPTION 'REVIEW_NOT_FOUND'; END IF;

    SELECT EXISTS(SELECT 1 FROM commander_venue_review_helpful 
                   WHERE review_id = p_review_id AND user_id = p_caller_user_id) INTO v_exists;

    IF v_exists THEN
        DELETE FROM commander_venue_review_helpful 
         WHERE review_id = p_review_id AND user_id = p_caller_user_id;
    ELSE
        INSERT INTO commander_venue_review_helpful (review_id, user_id, is_helpful)
        VALUES (p_review_id, p_caller_user_id, true);
    END IF;

    SELECT helpful_count INTO v_count FROM commander_venue_reviews WHERE id = p_review_id;
    RETURN jsonb_build_object('success', true, 'now_marked_helpful', NOT v_exists, 'helpful_count', v_count);
END; $$;


ALTER FUNCTION public.toggle_venue_review_helpful(p_review_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION toggle_venue_review_helpful(p_review_id uuid, p_caller_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.toggle_venue_review_helpful(p_review_id uuid, p_caller_user_id uuid) IS 'Phase 27/C: Idempotent helpful vote. Upsert/delete tracked per-user in commander_venue_review_helpful.';


