--
-- Name: track_home_group_share_click(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.track_home_group_share_click(p_group_id uuid, p_token_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_uid uuid := auth.uid();
    v_anon_recent int;
BEGIN
    -- Validate group exists
    IF NOT EXISTS (SELECT 1 FROM commander_home_groups WHERE id = p_group_id) THEN
        RETURN;
    END IF;

    IF v_uid IS NOT NULL THEN
        -- Authenticated: 1 bump per (group, token, user) per hour
        IF EXISTS (
            SELECT 1 FROM commander_home_group_share_log
             WHERE group_id   = p_group_id
               AND caller_uid = v_uid
               AND COALESCE(token_id::text, '') = COALESCE(p_token_id::text, '')
               AND inserted_at > NOW() - INTERVAL '1 hour'
        ) THEN
            RETURN;
        END IF;
    ELSE
        -- Anonymous: global cap of 100 per group per hour
        SELECT COUNT(*) INTO v_anon_recent
          FROM commander_home_group_share_log
         WHERE group_id   = p_group_id
           AND caller_uid IS NULL
           AND inserted_at > NOW() - INTERVAL '1 hour';
        IF v_anon_recent >= 100 THEN
            RETURN;
        END IF;
    END IF;

    INSERT INTO commander_home_group_share_log (group_id, token_id, caller_uid)
         VALUES (p_group_id, p_token_id, v_uid);

    UPDATE commander_home_groups
       SET share_click_count = COALESCE(share_click_count, 0) + 1
     WHERE id = p_group_id;

    IF p_token_id IS NOT NULL THEN
        UPDATE commander_home_invite_tokens
           SET click_count = COALESCE(click_count, 0) + 1
         WHERE id = p_token_id AND group_id = p_group_id;
    END IF;
END;
$$;


ALTER FUNCTION public.track_home_group_share_click(p_group_id uuid, p_token_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION track_home_group_share_click(p_group_id uuid, p_token_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.track_home_group_share_click(p_group_id uuid, p_token_id uuid) IS 'Frontend analytics tracker — increments share_click_count and optionally the invite token click_count.';


--
-- Name: track_home_group_view(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.track_home_group_view(p_group_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_uid uuid := auth.uid();
    v_anon_recent int;
BEGIN
    -- Validate group exists (no-op silently if not - don't leak existence to anon)
    IF NOT EXISTS (SELECT 1 FROM commander_home_groups WHERE id = p_group_id) THEN
        RETURN;
    END IF;

    IF v_uid IS NOT NULL THEN
        -- Authenticated: 1 bump per (group, user) per hour
        IF EXISTS (
            SELECT 1 FROM commander_home_group_view_log
             WHERE group_id   = p_group_id
               AND caller_uid = v_uid
               AND inserted_at > NOW() - INTERVAL '1 hour'
        ) THEN
            RETURN;
        END IF;
    ELSE
        -- Anonymous: global cap of 60 bumps per group per hour
        SELECT COUNT(*) INTO v_anon_recent
          FROM commander_home_group_view_log
         WHERE group_id   = p_group_id
           AND caller_uid IS NULL
           AND inserted_at > NOW() - INTERVAL '1 hour';
        IF v_anon_recent >= 60 THEN
            RETURN;
        END IF;
    END IF;

    INSERT INTO commander_home_group_view_log (group_id, caller_uid)
         VALUES (p_group_id, v_uid);

    UPDATE commander_home_groups
       SET view_count = COALESCE(view_count, 0) + 1
     WHERE id = p_group_id;
END;
$$;


ALTER FUNCTION public.track_home_group_view(p_group_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION track_home_group_view(p_group_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.track_home_group_view(p_group_id uuid) IS 'Frontend analytics tracker — anyone can call to increment view_count on public group pages.';


--
-- Name: track_training_action(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.track_training_action(p_user_id uuid, p_action_type text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text;
  v_caller_uid uuid;
  v_event_id uuid;
BEGIN
  IF p_user_id IS NULL OR p_action_type IS NULL OR length(p_action_type) = 0 THEN
    RETURN jsonb_build_object('rewards', '[]'::jsonb);
  END IF;
  v_caller_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '');
  v_caller_uid := auth.uid();
  IF v_caller_role = 'authenticated' THEN
    IF v_caller_uid IS NULL OR p_user_id <> v_caller_uid THEN
      RAISE WARNING 'track_training_action: spoof attempt by % targeting %', v_caller_uid, p_user_id;
      RETURN jsonb_build_object('rewards', '[]'::jsonb);
    END IF;
  ELSIF v_caller_role = 'anon' OR v_caller_role = '' THEN
    RETURN jsonb_build_object('rewards', '[]'::jsonb);
  END IF;
  INSERT INTO public.training_events (user_id, event_type, event_data, created_at)
  VALUES (p_user_id, LEFT(p_action_type, 100), COALESCE(p_metadata, '{}'::jsonb), now())
  RETURNING id INTO v_event_id;
  RETURN jsonb_build_object('rewards', '[]'::jsonb, 'event_id', v_event_id);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'track_training_action failed for user %: % %', p_user_id, SQLERRM, SQLSTATE;
  RETURN jsonb_build_object('rewards', '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.track_training_action(p_user_id uuid, p_action_type text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: training_claim_solver_worker_request_v1(text, text, text, text, text, text, uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.training_claim_solver_worker_request_v1(p_machine_id text, p_solver_version text, p_solver_binary_checksum text, p_pipeline_commit text, p_manifest_version text, p_manifest_checksum text, p_nonce uuid, p_operation text, p_signed_at timestamp with time zone, p_body_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_inserted integer;
BEGIN
  IF p_machine_id NOT IN ('M1', 'M2')
     OR p_operation NOT IN ('row_states', 'board_page', 'heartbeat')
     OR p_nonce IS NULL
     OR p_signed_at IS NULL
     OR abs(extract(epoch FROM (clock_timestamp() - p_signed_at))) > 300
     OR coalesce(p_body_sha256, '') !~ '^[0-9a-f]{64}$'
     OR NOT EXISTS (
       SELECT 1
       FROM public.training_solver_provenance_authority authority
       WHERE authority.machine_id = p_machine_id
         AND authority.solver_version = p_solver_version
         AND authority.solver_binary_checksum = p_solver_binary_checksum
         AND authority.pipeline_commit = p_pipeline_commit
         AND authority.manifest_version = p_manifest_version
         AND authority.manifest_checksum = p_manifest_checksum
         AND authority.retired_at IS NULL
     ) THEN
    RETURN false;
  END IF;

  -- A signature older than five minutes can never be accepted again. Retain
  -- receipts for 24 hours for incident evidence and prune only a bounded batch
  -- so heartbeat/poll nonces cannot grow this private ledger without limit.
  WITH stale_candidates AS MATERIALIZED (
    SELECT candidate.machine_id, candidate.request_nonce
    FROM public.training_solver_worker_receipts candidate
    WHERE candidate.received_at < clock_timestamp() - interval '24 hours'
    ORDER BY candidate.received_at, candidate.machine_id
    FOR UPDATE SKIP LOCKED
    LIMIT 100
  )
  DELETE FROM public.training_solver_worker_receipts stale
  USING stale_candidates candidate
  WHERE stale.machine_id = candidate.machine_id
    AND stale.request_nonce = candidate.request_nonce;

  INSERT INTO public.training_solver_worker_receipts (
    machine_id, request_nonce, operation, signed_at, body_sha256,
    solver_version, solver_binary_checksum, pipeline_commit,
    manifest_version, manifest_checksum
  ) VALUES (
    p_machine_id, p_nonce, p_operation, p_signed_at, p_body_sha256,
    p_solver_version, p_solver_binary_checksum, p_pipeline_commit,
    p_manifest_version, p_manifest_checksum
  ) ON CONFLICT (machine_id, request_nonce) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted = 1;
END;
$_$;


ALTER FUNCTION public.training_claim_solver_worker_request_v1(p_machine_id text, p_solver_version text, p_solver_binary_checksum text, p_pipeline_commit text, p_manifest_version text, p_manifest_checksum text, p_nonce uuid, p_operation text, p_signed_at timestamp with time zone, p_body_sha256 text) OWNER TO postgres;

--
-- Name: training_dashboard_30day_stats(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.training_dashboard_30day_stats(p_user_id uuid, p_game_id text) RETURNS TABLE(avg_score numeric, sessions_count bigint, hands_played bigint, best_score numeric, total_ev_loss numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'unauthorized: can only query your own stats'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  WITH scoped AS (
    SELECT session.*
    FROM public.training_sessions session
    JOIN public.training_attempts attempt
      ON attempt.id = session.attempt_id
     AND attempt.user_id = session.user_id
     AND attempt.practice_only IS FALSE
     AND attempt.status = 'completed'
    WHERE session.user_id = p_user_id
      AND session.game_id = p_game_id
      AND session.created_at >= now() - interval '30 days'
      AND session.hands_played > 0
      AND session.correct_count BETWEEN 0 AND session.hands_played
  ), measured AS (
    SELECT count(*)::bigint AS decisions, sum(answer.ev_loss)::numeric AS loss
    FROM public.training_answers answer
    JOIN scoped session ON session.attempt_id = answer.attempt_id
    WHERE answer.solver_verified IS TRUE
      AND answer.ev_loss_measured IS TRUE
  )
  SELECT
    round(100 * sum(scoped.correct_count)::numeric / nullif(sum(scoped.hands_played), 0), 2),
    count(*)::bigint,
    coalesce(sum(scoped.hands_played), 0)::bigint,
    round(max(100 * scoped.correct_count::numeric / scoped.hands_played), 2),
    CASE WHEN measured.decisions > 0 THEN round(measured.loss, 2) ELSE NULL END
  FROM scoped
  CROSS JOIN measured
  GROUP BY measured.decisions, measured.loss;
END;
$$;


ALTER FUNCTION public.training_dashboard_30day_stats(p_user_id uuid, p_game_id text) OWNER TO postgres;

--
-- Name: FUNCTION training_dashboard_30day_stats(p_user_id uuid, p_game_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.training_dashboard_30day_stats(p_user_id uuid, p_game_id text) IS 'Verified non-practice weighted accuracy, volume, and explicitly measured EV for Session Setup.';


--
-- Name: training_dashboard_last_session(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.training_dashboard_last_session(p_user_id uuid, p_game_id text) RETURNS TABLE(session_id uuid, gtow_score numeric, accuracy numeric, hands_played integer, level integer, level_passed boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'unauthorized: can only query your own stats'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT
    session.id,
    CASE WHEN session.score_scale = 2 AND session.gtow_score BETWEEN -100 AND 100
      THEN session.gtow_score ELSE NULL END,
    round(100 * session.correct_count::numeric / session.hands_played, 2),
    session.hands_played,
    session.level,
    session.level_passed,
    session.created_at
  FROM public.training_sessions session
  JOIN public.training_attempts attempt
    ON attempt.id = session.attempt_id
   AND attempt.user_id = session.user_id
   AND attempt.practice_only IS FALSE
   AND attempt.status = 'completed'
  WHERE session.user_id = p_user_id
    AND session.game_id = p_game_id
    AND session.hands_played > 0
    AND session.correct_count BETWEEN 0 AND session.hands_played
  ORDER BY session.created_at DESC
  LIMIT 1;
END;
$$;


ALTER FUNCTION public.training_dashboard_last_session(p_user_id uuid, p_game_id text) OWNER TO postgres;

--
-- Name: FUNCTION training_dashboard_last_session(p_user_id uuid, p_game_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.training_dashboard_last_session(p_user_id uuid, p_game_id text) IS 'Most recent verified non-practice Training session with count-derived accuracy.';


--
-- Name: training_dashboard_lifetime_stats(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.training_dashboard_lifetime_stats(p_user_id uuid, p_game_id text) RETURNS TABLE(total_sessions bigint, total_hands bigint, best_score numeric, avg_score numeric, highest_level_passed integer, total_diamonds_est bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'unauthorized: can only query your own stats'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  WITH scoped AS (
    SELECT session.*, attempt.reward_diamonds
    FROM public.training_sessions session
    JOIN public.training_attempts attempt
      ON attempt.id = session.attempt_id
     AND attempt.user_id = session.user_id
     AND attempt.practice_only IS FALSE
     AND attempt.status = 'completed'
    WHERE session.user_id = p_user_id
      AND session.game_id = p_game_id
      AND session.hands_played > 0
      AND session.correct_count BETWEEN 0 AND session.hands_played
  )
  SELECT
    count(*)::bigint,
    coalesce(sum(scoped.hands_played), 0)::bigint,
    round(max(100 * scoped.correct_count::numeric / scoped.hands_played), 2),
    round(100 * sum(scoped.correct_count)::numeric / nullif(sum(scoped.hands_played), 0), 2),
    coalesce(max(scoped.level) FILTER (WHERE scoped.level_passed), 0)::integer,
    coalesce(sum(scoped.reward_diamonds), 0)::bigint
  FROM scoped;
END;
$$;


ALTER FUNCTION public.training_dashboard_lifetime_stats(p_user_id uuid, p_game_id text) OWNER TO postgres;

--
-- Name: FUNCTION training_dashboard_lifetime_stats(p_user_id uuid, p_game_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.training_dashboard_lifetime_stats(p_user_id uuid, p_game_id text) IS 'Verified non-practice lifetime accuracy and actual attempt reward totals.';


