--
-- Name: training_solver_spot_candidates_v1(jsonb, text, uuid, uuid, uuid, integer, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.training_solver_spot_candidates_v1(p_family_stacks jsonb, p_position text DEFAULT NULL::text, p_lower_inclusive uuid DEFAULT NULL::uuid, p_lower_exclusive uuid DEFAULT NULL::uuid, p_upper_exclusive uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 12, p_artifact_id uuid DEFAULT NULL::uuid, p_scenario_hash text DEFAULT NULL::text, p_street text DEFAULT NULL::text, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, scenario_hash text, game_type text, stack_depth integer, street text, strategy_matrix_v2 jsonb, solver_version text, solver_binary_checksum text, machine_id text, pipeline_commit text, manifest_version text, manifest_checksum text, source_artifact_checksum text, quality_status text, audited_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 128
    SET search_path TO 'pg_catalog'
    AS $_$
  WITH requested AS MATERIALIZED (
    SELECT DISTINCT
      request_item.value ->> 'game_type' AS game_type,
      CASE
        WHEN request_item.value ->> 'stack_depth' ~ '^[1-9][0-9]{0,3}$'
        THEN (request_item.value ->> 'stack_depth')::integer
        ELSE NULL
      END AS stack_depth
    FROM jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(p_family_stacks) = 'array'
        THEN CASE
          WHEN jsonb_array_length(p_family_stacks) BETWEEN 1 AND 32
          THEN p_family_stacks
          ELSE '[]'::jsonb
        END
        ELSE '[]'::jsonb
      END
    ) AS request_item(value)
  ), allowed AS MATERIALIZED (
    SELECT request.game_type, request.stack_depth
    FROM requested request
    WHERE
      (request.game_type = 'hu_cash' AND request.stack_depth IN (40, 100, 200))
      OR (request.game_type = 'mtt_3max_chipev' AND request.stack_depth = 20)
      OR (request.game_type = 'mtt_6max_chipev' AND request.stack_depth IN (10, 20, 40, 100))
      OR (request.game_type = 'mtt_9max_chipev' AND request.stack_depth IN (20, 40, 80, 100))
      OR (request.game_type = 'mtt_hu_chipev' AND request.stack_depth = 40)
      OR (request.game_type = 'postflop_complete' AND request.stack_depth = 100)
      OR (request.game_type = 'spin_3max_chipev' AND request.stack_depth IN (20, 25))
      OR (request.game_type = 'spin_hu_chipev' AND request.stack_depth IN (10, 20))
  ), candidates AS MATERIALIZED (
    SELECT candidate.*
    FROM allowed request
    CROSS JOIN LATERAL (
      SELECT
        artifact.id,
        artifact.scenario_hash,
        artifact.game_type,
        artifact.stack_depth,
        artifact.street,
        artifact.strategy_matrix_v2,
        artifact.solver_version,
        artifact.solver_binary_checksum,
        artifact.machine_id,
        artifact.pipeline_commit,
        artifact.manifest_version,
        artifact.manifest_checksum,
        artifact.source_artifact_checksum,
        artifact.quality_status,
        artifact.audited_at
      FROM public.training_solver_artifact_catalog catalog
      JOIN public.solved_spots_gold artifact
        ON artifact.id = catalog.artifact_id
       AND artifact.scenario_hash = catalog.scenario_hash
       AND artifact.game_type = catalog.game_type
       AND artifact.stack_depth = catalog.stack_depth
       AND artifact.street = catalog.street
       AND artifact.strategy_matrix_v2 ->> 'position' = catalog.hero_position
      JOIN public.training_solver_provenance_authority authority
        ON authority.machine_id = artifact.machine_id
       AND authority.solver_version = artifact.solver_version
       AND authority.solver_binary_checksum = artifact.solver_binary_checksum
       AND authority.pipeline_commit = artifact.pipeline_commit
       AND authority.manifest_version = artifact.manifest_version
       AND authority.manifest_checksum = artifact.manifest_checksum
       AND authority.source_combo_order_sha256 =
         artifact.strategy_matrix_v2 ->> 'source_combo_order_sha256'
       AND authority.training_game_contracts_sha256 =
         artifact.strategy_matrix_v2 ->> 'training_game_contracts_sha256'
       AND authority.retired_at IS NULL
      WHERE catalog.game_type = request.game_type
        AND catalog.stack_depth = request.stack_depth
        AND (p_position IS NULL OR catalog.hero_position = p_position)
        AND (p_artifact_id IS NULL OR catalog.artifact_id = p_artifact_id)
        AND (p_scenario_hash IS NULL OR catalog.scenario_hash = p_scenario_hash)
        AND (p_street IS NULL OR catalog.street = p_street)
        AND (p_lower_inclusive IS NULL OR catalog.artifact_id >= p_lower_inclusive)
        AND (p_lower_exclusive IS NULL OR catalog.artifact_id > p_lower_exclusive)
        AND (p_upper_exclusive IS NULL OR catalog.artifact_id < p_upper_exclusive)
      ORDER BY catalog.artifact_id
      LIMIT greatest(1, least(128, coalesce(p_limit, 12)))
      OFFSET greatest(0, least(4096, coalesce(p_offset, 0)))
    ) candidate
    WHERE coalesce(p_offset, 0) = 0
       OR (SELECT count(*) FROM allowed) = 1
  )
  SELECT candidate.*
  FROM candidates candidate
  ORDER BY candidate.id
  LIMIT greatest(1, least(128, coalesce(p_limit, 12)))
$_$;


ALTER FUNCTION public.training_solver_spot_candidates_v1(p_family_stacks jsonb, p_position text, p_lower_inclusive uuid, p_lower_exclusive uuid, p_upper_exclusive uuid, p_limit integer, p_artifact_id uuid, p_scenario_hash text, p_street text, p_offset integer) OWNER TO postgres;

--
-- Name: training_solver_worker_board_page_v1(text, integer, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.training_solver_worker_board_page_v1(p_game_type text, p_stack_depth integer, p_street text, p_position text, p_after_scenario text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS TABLE(scenario_hash text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER ROWS 500
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_prefix text;
  v_upper_bound text;
BEGIN
  IF NOT (
       (p_game_type = 'hu_cash' AND p_stack_depth IN (40, 100, 200))
       OR (p_game_type = 'mtt_3max_chipev' AND p_stack_depth = 20)
       OR (p_game_type = 'mtt_6max_chipev' AND p_stack_depth IN (10, 20, 40, 100))
       OR (p_game_type = 'mtt_9max_chipev' AND p_stack_depth IN (20, 40, 80, 100))
       OR (p_game_type = 'mtt_hu_chipev' AND p_stack_depth = 40)
       OR (p_game_type = 'postflop_complete' AND p_stack_depth = 100)
       OR (p_game_type = 'spin_3max_chipev' AND p_stack_depth IN (20, 25))
       OR (p_game_type = 'spin_hu_chipev' AND p_stack_depth IN (10, 20))
     )
     OR p_street IS DISTINCT FROM 'flop'
     OR coalesce(p_position, '') !~
       '^(UTG|UTG\+1|UTG\+2|UTG1|UTG2|MP|MP\+1|MP\+2|MP1|MP2|LJ|HJ|CO|BTN|SB|BB)$'
     OR p_limit IS NULL
     OR p_limit NOT BETWEEN 1 AND 500 THEN
    RETURN;
  END IF;

  v_prefix := p_game_type || '_' || p_position || '_'
    || p_stack_depth::text || 'bb_';
  -- Canonical suffixes begin with one of 2-9/T/J/Q/K/A. Z is therefore a
  -- strict upper bound in both C and the production en_US.UTF-8 collation.
  -- DEL is not safe here: locale-aware collations can sort printable board
  -- text after DEL and silently turn the page into an empty range.
  v_upper_bound := v_prefix || 'Z';
  IF p_after_scenario IS NOT NULL
     AND (
       NOT starts_with(p_after_scenario, v_prefix)
       OR substring(p_after_scenario FROM char_length(v_prefix) + 1)
          !~ '^([2-9TJQKA][cdhs]){3}$'
     ) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT DISTINCT artifact.scenario_hash
  FROM public.solved_spots_gold artifact
  WHERE artifact.game_type = p_game_type
    AND artifact.stack_depth = p_stack_depth
    AND artifact.street = p_street
    AND artifact.scenario_hash >= v_prefix
    AND artifact.scenario_hash < v_upper_bound
    AND (p_after_scenario IS NULL OR artifact.scenario_hash > p_after_scenario)
  ORDER BY artifact.scenario_hash
  LIMIT p_limit;
END;
$_$;


ALTER FUNCTION public.training_solver_worker_board_page_v1(p_game_type text, p_stack_depth integer, p_street text, p_position text, p_after_scenario text, p_limit integer) OWNER TO postgres;

--
-- Name: training_solver_worker_row_states_v1(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.training_solver_worker_row_states_v1(p_scenario_hashes text[]) RETURNS TABLE(id uuid, scenario_hash text, game_type text, stack_depth integer, street text, solved_v2_at timestamp with time zone, quality_status text, solver_version text, solver_binary_checksum text, machine_id text, pipeline_commit text, manifest_version text, manifest_checksum text, source_artifact_checksum text, audited_at timestamp with time zone, admitted boolean)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 150
    SET search_path TO 'pg_catalog'
    AS $$
  WITH requested AS MATERIALIZED (
    SELECT DISTINCT requested_hash.value AS scenario_hash
    FROM unnest(
      CASE
        WHEN cardinality(p_scenario_hashes) BETWEEN 1 AND 75
        THEN p_scenario_hashes
        ELSE ARRAY[]::text[]
      END
    ) AS requested_hash(value)
    WHERE char_length(requested_hash.value) BETWEEN 1 AND 512
  )
  SELECT
    artifact.id,
    artifact.scenario_hash,
    artifact.game_type,
    artifact.stack_depth,
    artifact.street,
    artifact.solved_v2_at,
    artifact.quality_status,
    artifact.solver_version,
    artifact.solver_binary_checksum,
    artifact.machine_id,
    artifact.pipeline_commit,
    artifact.manifest_version,
    artifact.manifest_checksum,
    artifact.source_artifact_checksum,
    artifact.audited_at,
    EXISTS (
      SELECT 1
      FROM public.training_solver_artifact_catalog catalog
      JOIN public.training_solver_provenance_authority authority
        ON authority.machine_id = artifact.machine_id
       AND authority.solver_version = artifact.solver_version
       AND authority.solver_binary_checksum = artifact.solver_binary_checksum
       AND authority.pipeline_commit = artifact.pipeline_commit
       AND authority.manifest_version = artifact.manifest_version
       AND authority.manifest_checksum = artifact.manifest_checksum
       AND authority.source_combo_order_sha256 =
         artifact.strategy_matrix_v2 ->> 'source_combo_order_sha256'
       AND authority.training_game_contracts_sha256 =
         artifact.strategy_matrix_v2 ->> 'training_game_contracts_sha256'
       AND authority.retired_at IS NULL
      WHERE catalog.artifact_id = artifact.id
        AND catalog.scenario_hash = artifact.scenario_hash
        AND catalog.game_type = artifact.game_type
        AND catalog.stack_depth = artifact.stack_depth
        AND catalog.street = artifact.street
        AND catalog.hero_position = artifact.strategy_matrix_v2 ->> 'position'
    ) AS admitted
  FROM requested
  JOIN public.solved_spots_gold artifact
    ON artifact.scenario_hash = requested.scenario_hash
  ORDER BY artifact.scenario_hash, artifact.id
  LIMIT 150
$$;


ALTER FUNCTION public.training_solver_worker_row_states_v1(p_scenario_hashes text[]) OWNER TO postgres;

--
-- Name: transfer_club_ownership(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_club_ownership(p_club_id uuid, p_new_owner_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_old UUID;
  v_actor UUID;
  v_club_name text;
BEGIN
  v_actor := auth.uid();

  SELECT owner_id, name INTO v_old, v_club_name FROM clubs WHERE id = p_club_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Club not found';
  END IF;

  -- A JWT caller must BE the current owner. service_role callers (auth.uid()
  -- NULL) are trusted to have authorized upstream.
  IF v_actor IS NOT NULL AND v_actor <> v_old THEN
    RAISE EXCEPTION 'Only the current club owner can transfer ownership';
  END IF;

  IF p_new_owner_id = v_old THEN
    RAISE EXCEPTION 'That user already owns this club';
  END IF;

  -- Recipient must be an active member of this club.
  IF NOT EXISTS (
    SELECT 1 FROM club_members
     WHERE club_id = p_club_id AND user_id = p_new_owner_id
       AND status IN ('active','approved')
  ) THEN
    RAISE EXCEPTION 'New owner must be an active member of this club';
  END IF;

  UPDATE clubs SET owner_id = p_new_owner_id, updated_at = NOW() WHERE id = p_club_id;
  UPDATE club_members SET role = 'admin', updated_at = NOW()
   WHERE club_id = p_club_id AND user_id = v_old;
  UPDATE club_members SET role = 'owner', updated_at = NOW()
   WHERE club_id = p_club_id AND user_id = p_new_owner_id;

  -- THE RECORD. This used to insert a role_changes row with member_id NULL -
  -- the column that says WHO - inside EXCEPTION WHEN OTHERS THEN NULL, so a
  -- failed insert meant a club changed hands leaving no trace. Both rows are
  -- complete now, and neither is swallowed: a handover that cannot be recorded
  -- does not happen.
  INSERT INTO role_changes (member_id, old_role, new_role, changed_by, reason)
  VALUES (p_new_owner_id, 'admin', 'owner', COALESCE(v_actor, v_old),
          'Club ownership transferred');
  INSERT INTO role_changes (member_id, old_role, new_role, changed_by, reason)
  VALUES (v_old, 'owner', 'admin', COALESCE(v_actor, v_old),
          'Club ownership transferred');

  INSERT INTO audit_trail (actor_id, actor_role, action, target_type, target_id,
                           club_id, before_state, after_state, reason)
  VALUES (COALESCE(v_actor, v_old), 'owner', 'transfer_club_ownership',
          'club', p_club_id, p_club_id,
          jsonb_build_object('owner_id', v_old),
          jsonb_build_object('owner_id', p_new_owner_id, 'previous_owner_role', 'admin'),
          'Club ownership transferred');

  -- Both people are told. The outgoing owner is no longer an owner, which is
  -- the kind of thing somebody should hear from the club rather than notice.
  BEGIN
    PERFORM public.fn_raise_notification(
      p_new_owner_id, 'club_ownership_transferred',
      'You Now Own ' || COALESCE(v_club_name, 'A Club'),
      'Ownership Was Transferred To You. You Now Hold Every Permission In This Club.',
      '/clubs/' || p_club_id::text,
      jsonb_build_object('club_id', p_club_id, 'previous_owner', v_old));
    PERFORM public.fn_raise_notification(
      v_old, 'club_ownership_transferred',
      'You Handed Over ' || COALESCE(v_club_name, 'Your Club'),
      'Ownership Has Moved To Another Member. You Are Now An Admin Of This Club.',
      '/clubs/' || p_club_id::text,
      jsonb_build_object('club_id', p_club_id, 'new_owner', p_new_owner_id));
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- the handover is done and recorded; the notice is a courtesy
  END;
END;
$$;


ALTER FUNCTION public.transfer_club_ownership(p_club_id uuid, p_new_owner_id uuid) OWNER TO postgres;

--
-- Name: transfer_home_group_ownership(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_home_group_ownership(p_group_id uuid, p_new_owner_user_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group          RECORD;
    v_target_member  RECORD;
    v_old_owner      uuid;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;

    IF v_group.owner_id <> p_caller_user_id THEN
        RAISE EXCEPTION 'OWNER_ONLY_ACTION';
    END IF;
    IF v_group.owner_id = p_new_owner_user_id THEN
        RAISE EXCEPTION 'ALREADY_OWNER';
    END IF;

    SELECT * INTO v_target_member
      FROM commander_home_members
     WHERE group_id = p_group_id AND user_id = p_new_owner_user_id;

    IF NOT FOUND THEN RAISE EXCEPTION 'TARGET_NOT_MEMBER'; END IF;
    IF v_target_member.status <> 'approved' THEN RAISE EXCEPTION 'TARGET_NOT_APPROVED'; END IF;
    IF v_target_member.role <> 'admin' THEN
        RAISE EXCEPTION 'TARGET_NOT_ADMIN'
              USING HINT = 'promote to admin first, then transfer';
    END IF;

    v_old_owner := v_group.owner_id;

    UPDATE commander_home_groups
       SET owner_id = p_new_owner_user_id, updated_at = NOW()
     WHERE id = p_group_id;

    UPDATE commander_home_members
       SET role = 'admin'
     WHERE group_id = p_group_id AND user_id = v_old_owner;

    UPDATE commander_home_members
       SET role = 'owner'
     WHERE group_id = p_group_id AND user_id = p_new_owner_user_id;

    INSERT INTO commander_home_audit_log
      (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (p_group_id, p_caller_user_id, 'group', p_group_id, 'ownership_transferred',
            jsonb_build_object('from_user', v_old_owner, 'to_user', p_new_owner_user_id));

    -- ★ NEW: notify the new owner
    BEGIN
      PERFORM public.fn_emit_home_notification(
        p_user_id     => p_new_owner_user_id,
        p_type        => 'home_group_ownership_transferred',
        p_title       => 'You''re the new owner',
        p_message     => 'Ownership of ' || COALESCE(v_group.name, 'a group') ||
                         ' was transferred to you.',
        p_link        => '/hub/home-games/group/' || p_group_id::text,
        p_data        => jsonb_build_object(
                           'group_id',        p_group_id,
                           'previous_owner',  v_old_owner),
        p_pref_column => NULL
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'ownership-transfer notify failed: %', SQLERRM;
    END;

    RETURN jsonb_build_object(
        'success', true,
        'group_id', p_group_id,
        'previous_owner', v_old_owner,
        'new_owner', p_new_owner_user_id
    );
END;
$$;


ALTER FUNCTION public.transfer_home_group_ownership(p_group_id uuid, p_new_owner_user_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- Name: transfer_promo_agent_to_player(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_promo_agent_to_player(p_club_id uuid, p_agent_user_id uuid, p_player_user_id uuid, p_amount numeric, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_agent_before numeric;
  v_playthrough_mult numeric := 3;  -- Bible V8: 3x playthrough before promo converts to cashable
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  -- Lock + debit the agent's PROMO balance (not chip_balance).
  SELECT COALESCE(promo_balance, 0) INTO v_agent_before
    FROM club_members WHERE club_id = p_club_id AND user_id = p_agent_user_id FOR UPDATE;
  IF v_agent_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'agent is not a member of this club');
  END IF;
  IF v_agent_before < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient agent promo balance',
                              'balance', v_agent_before, 'requested', p_amount);
  END IF;

  UPDATE club_members
     SET promo_balance = promo_balance - p_amount, updated_at = NOW()
   WHERE club_id = p_club_id AND user_id = p_agent_user_id;

  -- Credit the player's PROMO balance + set playthrough requirement.
  UPDATE club_members
     SET promo_balance = COALESCE(promo_balance, 0) + p_amount,
         promo_received_total = COALESCE(promo_received_total, 0) + p_amount,
         promo_playthrough_required = COALESCE(promo_playthrough_required, 0) + (p_amount * v_playthrough_mult),
         updated_at = NOW()
   WHERE club_id = p_club_id AND user_id = p_player_user_id;

  IF NOT FOUND THEN
    -- player not a member: roll back by re-crediting the agent (single txn would
    -- normally auto-rollback on RAISE; be explicit for clarity)
    RAISE EXCEPTION 'player is not a member of this club';
  END IF;

  INSERT INTO chip_transactions (
    id, club_id, from_user_id, to_user_id, amount,
    transaction_type, notes, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), p_club_id, p_agent_user_id, p_player_user_id, p_amount,
    'promo_agent_to_player', COALESCE(p_note, 'Promo grant agent->player (promo ledger, 3x playthrough)'),
    v_agent_before - p_amount, NOW()
  );

  RETURN jsonb_build_object('success', true, 'amount', p_amount,
                            'playthrough_required', p_amount * v_playthrough_mult);
END;
$$;


ALTER FUNCTION public.transfer_promo_agent_to_player(p_club_id uuid, p_agent_user_id uuid, p_player_user_id uuid, p_amount numeric, p_note text) OWNER TO postgres;

