--
-- Name: transition_merchandise_fulfillment(uuid, uuid, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transition_merchandise_fulfillment(p_order_id uuid, p_actor_id uuid, p_expected_version integer, p_action text, p_tracking_number text DEFAULT NULL::text, p_tracking_url text DEFAULT NULL::text, p_carrier text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_order public.merchandise_orders%ROWTYPE;
  v_next_status text;
  v_next_fulfillment text;
  v_from_status text;
BEGIN
  SELECT * INTO v_order FROM public.merchandise_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'order_not_found'); END IF;
  IF p_expected_version IS NULL OR p_expected_version <> v_order.fulfillment_version THEN
    RETURN jsonb_build_object('success', false, 'error', 'version_conflict', 'current_version', v_order.fulfillment_version);
  END IF;
  IF v_order.status IN ('refunded', 'canceled', 'cancelled') THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_terminal');
  END IF;
  IF COALESCE(v_order.metadata ->> 'fulfillment_mode', '') <> 'manual' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_manual_order');
  END IF;
  IF COALESCE(v_order.metadata ->> 'reason', '') = 'shipping_address_incomplete'
     OR v_order.shipping_address IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'shipping_address_required');
  END IF;
  v_from_status := v_order.status;
  IF p_action = 'mark_processing' AND v_order.status = 'paid' THEN
    v_next_status := 'processing'; v_next_fulfillment := 'processing';
  ELSIF p_action = 'mark_shipped' AND v_order.status IN ('paid', 'processing') THEN
    IF p_tracking_number IS NULL OR btrim(p_tracking_number) = '' THEN
      RETURN jsonb_build_object('success', false, 'error', 'tracking_required');
    END IF;
    v_next_status := 'shipped'; v_next_fulfillment := 'shipped';
  ELSIF p_action = 'mark_delivered' AND v_order.status = 'shipped' THEN
    v_next_status := 'delivered'; v_next_fulfillment := 'delivered';
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'invalid_transition');
  END IF;
  UPDATE public.merchandise_orders
     SET status = v_next_status,
         tracking_number = CASE WHEN p_action = 'mark_shipped' THEN left(p_tracking_number, 160) ELSE tracking_number END,
         tracking_url = CASE WHEN p_action = 'mark_shipped' THEN left(p_tracking_url, 500) ELSE tracking_url END,
         carrier = CASE WHEN p_action = 'mark_shipped' THEN left(p_carrier, 100) ELSE carrier END,
         shipped_at = CASE WHEN p_action = 'mark_shipped' THEN COALESCE(shipped_at, now()) ELSE shipped_at END,
         delivered_at = CASE WHEN p_action = 'mark_delivered' THEN COALESCE(delivered_at, now()) ELSE delivered_at END,
         fulfillment_version = fulfillment_version + 1,
         metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
           'fulfillment_status', v_next_fulfillment, 'needs_review', false,
           'last_operator_id', p_actor_id, 'last_transition_at', now()),
         updated_at = now()
   WHERE id = v_order.id RETURNING * INTO v_order;
  INSERT INTO public.merchandise_order_events(order_id, actor_id, action, from_status, to_status, details)
  VALUES (v_order.id, p_actor_id, p_action, v_from_status, v_next_status,
    jsonb_build_object('tracking_number', p_tracking_number, 'tracking_url', p_tracking_url, 'carrier', p_carrier));
  RETURN jsonb_build_object('success', true, 'order_id', v_order.id, 'status', v_order.status,
    'fulfillment_version', v_order.fulfillment_version);
END;
$$;


ALTER FUNCTION public.transition_merchandise_fulfillment(p_order_id uuid, p_actor_id uuid, p_expected_version integer, p_action text, p_tracking_number text, p_tracking_url text, p_carrier text) OWNER TO postgres;

--
-- Name: trg_agent_commission_rollup_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_agent_commission_rollup_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pairs jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Transition tables cannot be combined with a column list on the
    -- trigger, so the trigger fires on every UPDATE and the filter is here:
    -- only rows whose outstanding amount, settlement or ownership changed
    -- name a pair to recompute. A notes-only update names none.
    SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('club_id', x.club_id, 'user_id', x.user_id)), '[]'::jsonb)
      INTO v_pairs
      FROM (
        SELECT o.club_id, o.user_id
          FROM old_rows o JOIN new_rows n ON n.id = o.id
         WHERE o.settled_at IS DISTINCT FROM n.settled_at
            OR o.amount IS DISTINCT FROM n.amount
            OR o.club_id IS DISTINCT FROM n.club_id
            OR o.user_id IS DISTINCT FROM n.user_id
        UNION
        SELECT n.club_id, n.user_id
          FROM old_rows o JOIN new_rows n ON n.id = o.id
         WHERE o.settled_at IS DISTINCT FROM n.settled_at
            OR o.amount IS DISTINCT FROM n.amount
            OR o.club_id IS DISTINCT FROM n.club_id
            OR o.user_id IS DISTINCT FROM n.user_id
      ) x;

    -- Phase 6: the day total moves only when amount, club or day moved.
    -- Subtract the old row, add the new one; a settlement changes neither.
    INSERT INTO public.ca_club_commission_daily AS c
           (club_id, stat_date, amount, rows_counted, updated_at)
    SELECT x.club_id, x.d, sum(x.amount), sum(x.n), now()
      FROM (
        SELECT o.club_id, (o.created_at AT TIME ZONE 'UTC')::date AS d, -o.amount AS amount, -1 AS n
          FROM old_rows o JOIN new_rows n ON n.id = o.id
         WHERE o.amount IS DISTINCT FROM n.amount
            OR o.club_id IS DISTINCT FROM n.club_id
            OR o.created_at IS DISTINCT FROM n.created_at
        UNION ALL
        SELECT n.club_id, (n.created_at AT TIME ZONE 'UTC')::date, n.amount, 1
          FROM old_rows o JOIN new_rows n ON n.id = o.id
         WHERE o.amount IS DISTINCT FROM n.amount
            OR o.club_id IS DISTINCT FROM n.club_id
            OR o.created_at IS DISTINCT FROM n.created_at
      ) x
     WHERE x.club_id IS NOT NULL
     GROUP BY x.club_id, x.d
    ON CONFLICT (club_id, stat_date) DO UPDATE
       SET amount       = c.amount + EXCLUDED.amount,
           rows_counted = c.rows_counted + EXCLUDED.rows_counted,
           updated_at   = now();
  ELSE
    SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('club_id', o.club_id, 'user_id', o.user_id)), '[]'::jsonb)
      INTO v_pairs
      FROM old_rows o;

    INSERT INTO public.ca_club_commission_daily AS c
           (club_id, stat_date, amount, rows_counted, updated_at)
    SELECT o.club_id, (o.created_at AT TIME ZONE 'UTC')::date, -sum(o.amount), -count(*), now()
      FROM old_rows o
     WHERE o.club_id IS NOT NULL
     GROUP BY o.club_id, (o.created_at AT TIME ZONE 'UTC')::date
    ON CONFLICT (club_id, stat_date) DO UPDATE
       SET amount       = c.amount + EXCLUDED.amount,
           rows_counted = c.rows_counted + EXCLUDED.rows_counted,
           updated_at   = now();
  END IF;
  IF v_pairs <> '[]'::jsonb THEN
    PERFORM public.fn_agent_commission_rollup_recompute(v_pairs);
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.trg_agent_commission_rollup_change() OWNER TO postgres;

--
-- Name: trg_agent_commission_rollup_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_agent_commission_rollup_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.agent_commission_unsettled_rollup AS r
         (club_id, user_id, owed, rows_behind, oldest_unsettled, updated_at)
  SELECT n.club_id, n.user_id,
         sum(n.amount), count(*), min(n.created_at), now()
    FROM new_rows n
   WHERE n.settled_at IS NULL AND n.club_id IS NOT NULL AND n.user_id IS NOT NULL
     AND NOT public.fn_agent_commission_paid_by_period(n.club_id, n.user_id, n.created_at)
   GROUP BY n.club_id, n.user_id
  ON CONFLICT (club_id, user_id) DO UPDATE
     SET owed             = r.owed + EXCLUDED.owed,
         rows_behind      = r.rows_behind + EXCLUDED.rows_behind,
         oldest_unsettled = least(r.oldest_unsettled, EXCLUDED.oldest_unsettled),
         updated_at       = now();

  -- Phase 6: the per-day total the Financials page reads.
  INSERT INTO public.ca_club_commission_daily AS c
         (club_id, stat_date, amount, rows_counted, updated_at)
  SELECT n.club_id, (n.created_at AT TIME ZONE 'UTC')::date, sum(n.amount), count(*), now()
    FROM new_rows n
   WHERE n.club_id IS NOT NULL
   GROUP BY n.club_id, (n.created_at AT TIME ZONE 'UTC')::date
  ON CONFLICT (club_id, stat_date) DO UPDATE
     SET amount       = c.amount + EXCLUDED.amount,
         rows_counted = c.rows_counted + EXCLUDED.rows_counted,
         updated_at   = now();
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.trg_agent_commission_rollup_insert() OWNER TO postgres;

--
-- Name: trg_assert_live_tournament_seat_has_roster(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_assert_live_tournament_seat_has_roster() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_user_id uuid;
  v_parent_status text;
BEGIN
  IF TG_TABLE_NAME = 'table_seats' THEN
    IF TG_OP = 'DELETE' OR NEW.left_at IS NOT NULL OR NEW.user_id IS NULL THEN
      RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
    END IF;
    SELECT t.tournament_id INTO v_tournament_id
      FROM public.tables t
     WHERE t.id = NEW.table_id;
    v_user_id := NEW.user_id;
  ELSE
    IF TG_OP = 'INSERT' THEN
      RETURN NEW;
    END IF;
    v_tournament_id := OLD.tournament_id;
    v_user_id := OLD.user_id;
  END IF;

  IF v_tournament_id IS NOT NULL THEN
    SELECT t.status::text INTO v_parent_status
      FROM public.tournaments t
     WHERE t.id = v_tournament_id;
  END IF;

  /* Terminal cleanup may intentionally close the roster and seats in
     separate idempotent requests.  The invariant is strict while the event
     is joinable or playable; finished/cancelled tables are separately barred
     from acquiring new live seats and may drain without being wedged. */
  IF v_tournament_id IS NOT NULL
     AND upper(COALESCE(v_parent_status, '')) IN ('REGISTERING', 'RUNNING')
     AND EXISTS (
       SELECT 1
         FROM public.table_seats s
         JOIN public.tables t ON t.id = s.table_id
        WHERE t.tournament_id = v_tournament_id
          AND s.user_id = v_user_id
          AND s.left_at IS NULL
     )
     AND NOT EXISTS (
       SELECT 1
         FROM public.tournament_players p
        WHERE p.tournament_id = v_tournament_id
          AND p.user_id = v_user_id
          AND p.status IN ('registered', 'playing')
     ) THEN
    RAISE EXCEPTION
      'TOURNAMENT_SEAT_ROSTER_REQUIRED: live seat user % has no active roster in tournament % at commit',
      v_user_id, v_tournament_id
      USING ERRCODE = '23514';
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.trg_assert_live_tournament_seat_has_roster() OWNER TO postgres;

--
-- Name: trg_atomic_final_table_deal_completion_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_atomic_final_table_deal_completion_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_check jsonb;
BEGIN
  IF NOT EXISTS (
       SELECT 1 FROM public.tournament_final_table_deal_batches b
        WHERE b.tournament_id = NEW.id
     ) AND NOT EXISTS (
       SELECT 1 FROM public.tournament_obligations o
        WHERE o.tournament_id = NEW.id AND o.kind = 'final_table_deal'
     ) AND NOT EXISTS (
       SELECT 1 FROM public.tournament_payouts p
        WHERE p.tournament_id = NEW.id AND p.source = 'final_table_deal'
     ) THEN
    RETURN NEW;
  END IF;

  v_check := public.fn_check_atomic_final_table_deal(NEW.id);
  IF NOT COALESCE((v_check->>'ok')::boolean, false) THEN
    RAISE EXCEPTION
      'final-table-deal tournament % cannot complete: %', NEW.id, v_check::text
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_atomic_final_table_deal_completion_guard() OWNER TO postgres;

--
-- Name: trg_auto_cashout_on_table_close(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_auto_cashout_on_table_close() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  r RECORD;
BEGIN
  IF NEW.tournament_id IS NOT NULL THEN
    RETURN NEW; -- tournament tables settle via prizes, not seat cashout
  END IF;

  FOR r IN
    SELECT ts.user_id, ts.seat_number
    FROM table_seats ts
    WHERE ts.table_id = NEW.id
      AND ts.left_at IS NULL
      /* `AND ts.horse_id IS NULL` was here until 2026-09-05. It read as "do
         not cash out horses", it never fired (the column was never written),
         and the moment the column WAS written it would have stranded every
         horse's chips on every closing table. CLAUDE.md 10.5: a horse is paid
         everything a human is paid. Every seat holding chips is cashed out. */
      AND COALESCE(ts.stack,0) > 0
  LOOP
    BEGIN
      PERFORM public.atomic_table_cashout(r.user_id, NEW.id, r.seat_number);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'auto-cashout failed for user % on table %: %', r.user_id, NEW.id, SQLERRM;
    END;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_auto_cashout_on_table_close() OWNER TO postgres;

