-- Name: trg_profiles_assign_player_number(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_profiles_assign_player_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.player_number IS NULL OR btrim(NEW.player_number) = '' THEN
    NEW.player_number := public.fn_next_player_number();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_profiles_assign_player_number() OWNER TO postgres;

--
-- Name: trg_protect_club_level_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_protect_club_level_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Allow writes from privileged system roles (postgres, service_role)
    -- These are used by SECURITY DEFINER RPCs and the autonomous trigger chain.
    -- Block writes from regular users (authenticated, anon) who attempt
    -- direct UPDATE on the clubs table.
    IF current_user NOT IN ('postgres', 'supabase_admin', 'service_role') THEN
        -- Revert ALL protected level columns to their previous (OLD) values
        NEW.level := OLD.level;
        NEW.player_level := OLD.player_level;
        NEW.hierarchy_level := OLD.hierarchy_level;
        NEW.hierarchy_units := OLD.hierarchy_units;
        NEW.hierarchy_units_rounded_up := OLD.hierarchy_units_rounded_up;
        NEW.player_threshold_current := OLD.player_threshold_current;
        NEW.player_threshold_next := OLD.player_threshold_next;
        NEW.hierarchy_threshold_current := OLD.hierarchy_threshold_current;
        NEW.hierarchy_threshold_next := OLD.hierarchy_threshold_next;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_protect_club_level_columns() OWNER TO postgres;

--
-- Name: trg_refuse_finalized_tournament_entry(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_refuse_finalized_tournament_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_finalized boolean;
BEGIN
  SELECT COALESCE(t.prize_pool_finalized, false)
    INTO v_finalized
    FROM public.tournaments t
   WHERE t.id = NEW.tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist', NEW.tournament_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_finalized THEN
    RAISE EXCEPTION 'registration is closed because tournament % prize pool is finalized',
      NEW.tournament_id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_refuse_finalized_tournament_entry() OWNER TO postgres;

--
-- Name: trg_refuse_live_seat_on_closed_tournament_table(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_refuse_live_seat_on_closed_tournament_table() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_table_status text;
  v_is_deleted boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.left_at IS NOT NULL OR NEW.user_id IS NULL THEN
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.left_at IS NOT NULL
       OR NEW.user_id IS NULL
       OR (
         OLD.left_at IS NULL
         AND OLD.user_id IS NOT DISTINCT FROM NEW.user_id
         AND OLD.table_id IS NOT DISTINCT FROM NEW.table_id
       ) THEN
      RETURN NEW;
    END IF;
  ELSE
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  SELECT lower(t.status::text), COALESCE(t.is_deleted, false)
    INTO v_table_status, v_is_deleted
    FROM public.tables t
   WHERE t.id = NEW.table_id
     AND t.tournament_id IS NOT NULL
   FOR SHARE;

  IF FOUND AND (v_table_status = 'closed' OR v_is_deleted) THEN
    RAISE EXCEPTION
      'TOURNAMENT_TABLE_CLOSED: table % cannot acquire a live seat', NEW.table_id
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_refuse_live_seat_on_closed_tournament_table() OWNER TO postgres;

--
-- Name: trg_refuse_normal_tournament_completed_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_refuse_normal_tournament_completed_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF lower(COALESCE(NEW.variant, '')) = 'satellite'
     OR upper(COALESCE(NEW.tournament_type, '')) = 'SATELLITE'
     OR NEW.satellite_target_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION
    'normal tournament % cannot be inserted already completed; use the atomic settlement transition',
    NEW.id USING ERRCODE = 'check_violation';
END;
$$;


ALTER FUNCTION public.trg_refuse_normal_tournament_completed_insert() OWNER TO postgres;

--
-- Name: FUNCTION trg_refuse_normal_tournament_completed_insert(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.trg_refuse_normal_tournament_completed_insert() IS 'Rejects a newly forged normal COMPLETED tournament. Normal completion is an UPDATE performed inside the fully paid atomic place or final-table-deal transaction.';


--
-- Name: trg_require_satellite_economics_at_entry_close(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_require_satellite_economics_at_entry_close() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.tournaments t
     WHERE t.id=NEW.tournament_id
       AND (lower(COALESCE(t.variant,''))='satellite'
         OR upper(COALESCE(t.tournament_type,''))='SATELLITE'
         OR t.satellite_target_id IS NOT NULL)
  ) AND NOT EXISTS (
    SELECT 1 FROM public.tournament_satellite_economic_snapshots s
     WHERE s.tournament_id=NEW.tournament_id
  ) THEN
    RAISE EXCEPTION 'satellite entry close has no provable start-time economics'
      USING ERRCODE='check_violation';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_require_satellite_economics_at_entry_close() OWNER TO postgres;

--
-- Name: trg_seed_bounty_head(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_seed_bounty_head() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t record; v_head numeric;
BEGIN
  -- Already seeded by fn_register_for_tournament / fn_register_horse_for_tournament.
  IF COALESCE(NEW.current_bounty, 0) > 0 THEN
    RETURN NEW;
  END IF;

  SELECT is_bounty, is_pko, is_mystery_bounty, bounty_amount
    INTO v_t FROM tournaments WHERE id = NEW.tournament_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  IF NOT (COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
          OR COALESCE(v_t.is_mystery_bounty,false)) THEN
    RETURN NEW;
  END IF;

  v_head := round(COALESCE(v_t.bounty_amount, 0), 2);
  IF v_head <= 0 THEN RETURN NEW; END IF;

  -- EVERY bounty format, mystery included, puts the FLAT bounty on the head.
  -- The mystery value is drawn from the funded chest inventory at the knockout
  -- (fn_mystery_bounty_reserve), not from a PRNG at the till. mystery_bounty_value
  -- is deliberately left alone here: it is set by the reveal, from the chest.
  UPDATE tournament_players
     SET current_bounty = v_head
   WHERE id = NEW.id;

  -- Fund the pool by this entrant's bounty contribution.
  UPDATE tournaments
     SET bounty_pool = round(COALESCE(bounty_pool, 0) + v_head, 2)
   WHERE id = NEW.tournament_id;

  /**
   * REACHING THIS LINE MEANS NOBODY PAID FOR THIS HEAD (2026-08-29).
   *
   * The early return above catches every entrant who arrived through a
   * register RPC, because those pre-set the head from the collected buy-in
   * split. So the pool was just increased by an entrant with no recorded
   * contribution -- a satellite seat award, a ticket redemption, a backfill,
   * or a path that does not exist yet.
   *
   * Not blocked: see the migration header. Made loud, once per tournament, so
   * the question can be answered from evidence instead of assumption.
   */
  INSERT INTO financial_alerts (severity, source, message, context)
  SELECT 'warning', 'trg_seed_bounty_head',
         'Bounty pool funded for an entrant with no collected buy-in split',
         jsonb_build_object(
           'tournament_id', NEW.tournament_id,
           'head', v_head,
           'detail', 'this entrant did not arrive through a register RPC, so no bounty '
                  || 'contribution was collected for the head just added to bounty_pool; '
                  || 'fn_finalize_bounty_pool pays any unclaimed remainder to the champion')
   WHERE NOT EXISTS (
     SELECT 1 FROM financial_alerts
      WHERE source = 'trg_seed_bounty_head'
        AND resolved IS NOT TRUE
        AND context->>'tournament_id' = NEW.tournament_id::text);

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_seed_bounty_head() OWNER TO postgres;

--
-- Name: FUNCTION trg_seed_bounty_head(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.trg_seed_bounty_head() IS 'Seeds a bounty entrant''s head with the FLAT tournaments.bounty_amount and funds bounty_pool by the same figure. Never rolls a multiplier: the mystery value comes from the funded chest inventory at the knockout (fn_mystery_bounty_reserve). See migration 20260827_bounty_heads_are_funded_not_rolled.';


--
-- Name: trg_spin_completed_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_spin_completed_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_unranked integer;
BEGIN
  IF COALESCE(NEW.variant, '') <> 'spin' THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*) INTO v_unranked
    FROM public.tournament_players tp
   WHERE tp.tournament_id = NEW.id
     AND tp.position IS NULL;

  IF v_unranked > 0 THEN
    RAISE EXCEPTION
      'refusing to complete Spin %: % seat(s) still have a null position after ranking. '
      'public.fn_rank_survivors should have filled these; check whether '
      'tournaments_rank_before_complete is still enabled.',
      NEW.id, v_unranked
      USING ERRCODE = 'check_violation';
  END IF;

  -- The money invariant is NOT knowable here: the prize credit lands up to
  -- ~87s after this flip (measured over 744 spins). Asking now produces a
  -- false critical on every slow credit. fn_spin_unpaid_check owns it.
  RETURN NEW;
END $$;


ALTER FUNCTION public.trg_spin_completed_guard() OWNER TO postgres;

--
-- Name: FUNCTION trg_spin_completed_guard(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.trg_spin_completed_guard() IS 'Spin-only companion to trg_tournaments_rank_before_complete. Blocks a COMPLETED flip that still has null-position seats (a tripwire: the rank trigger makes this unreachable), and raises a financial_alert when the reserve was drawn but players were not credited. Never blocks on money.';


