--
-- Name: trg_tournaments_guarantee_affordable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_tournaments_guarantee_affordable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_union uuid; v_enforce boolean; v_club_name text;
  v_bank numeric; v_floor numeric; v_bank_label text;
  v_exposure numeric; v_this numeric; v_headroom numeric;
begin
  if coalesce(new.guaranteed_prize, 0) <= 0 or new.club_id is null then
    return new;
  end if;

  select c.union_id, coalesce(c.guarantee_enforcement_enabled, true), c.name,
         coalesce(c.guarantee_treasury_floor, 0)
    into v_union, v_enforce, v_club_name, v_floor
    from public.clubs c where c.id = new.club_id;
  if not found then return new; end if;

  if v_union is not null then
    select coalesce(uw.chip_balance, 0) into v_bank
      from public.union_wallets uw where uw.union_id = v_union;
    v_bank := coalesce(v_bank, 0);
    v_bank_label := 'union bank';
    v_floor := 0;

    select coalesce(sum(greatest(coalesce(t.guaranteed_prize,0) - coalesce(t.prize_pool,0), 0)), 0)
      into v_exposure
      from public.tournaments t
      join public.clubs c2 on c2.id = t.club_id
     where c2.union_id = v_union
       and t.id <> new.id
       and coalesce(t.guaranteed_prize, 0) > 0
       and coalesce(t.prize_pool_finalized, false) = false
       and t.status in ('ANNOUNCED','REGISTERING','RUNNING');
  else
    select coalesce(c.chip_treasury, 0) into v_bank
      from public.clubs c where c.id = new.club_id;
    v_bank_label := 'club bank';

    select coalesce(sum(greatest(coalesce(t.guaranteed_prize,0) - coalesce(t.prize_pool,0), 0)), 0)
      into v_exposure
      from public.tournaments t
     where t.club_id = new.club_id
       and t.id <> new.id
       and coalesce(t.guaranteed_prize, 0) > 0
       and coalesce(t.prize_pool_finalized, false) = false
       and t.status in ('ANNOUNCED','REGISTERING','RUNNING');
  end if;

  v_this     := greatest(coalesce(new.guaranteed_prize,0) - coalesce(new.prize_pool,0), 0);
  v_headroom := v_bank - v_floor - v_exposure - v_this;

  if v_headroom < 0 then
    if v_enforce then
      raise exception
        'Club % cannot guarantee % chips: % holds %, floor %, already promised % on live events - short by %. Add chips to the bank to cover the guarantee.',
        coalesce(v_club_name, new.club_id::text), new.guaranteed_prize,
        v_bank_label, round(v_bank,2), round(v_floor,2), round(v_exposure,2), round(-v_headroom,2)
        using errcode = '55000';
    else
      insert into public.financial_alerts (severity, source, message, context)
      values ('critical', 'trg_tournaments_guarantee_affordable',
              'Guaranteed tournament announced that the ' || v_bank_label || ' cannot cover: '
                || coalesce(v_club_name, new.club_id::text),
              jsonb_build_object('club_id', new.club_id, 'union_id', v_union,
                                 'tournament_id', new.id,
                                 'guaranteed_prize', new.guaranteed_prize,
                                 'bank', v_bank, 'bank_label', v_bank_label,
                                 'floor', v_floor,
                                 'live_exposure', v_exposure, 'short_by', -v_headroom,
                                 'note', 'enforcement disabled for this club; no money was blocked'));
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.trg_tournaments_guarantee_affordable() OWNER TO postgres;

--
-- Name: FUNCTION trg_tournaments_guarantee_affordable(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.trg_tournaments_guarantee_affordable() IS 'Refuse a guaranteed tournament only when the bank that actually FUNDS overlays cannot cover it: the union bank for a union-affiliated club (exposure summed across every club sharing it), the club treasury for a standalone club.';


--
-- Name: trg_tournaments_rank_before_complete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_tournaments_rank_before_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ranked integer;
BEGIN
  v_ranked := public.fn_rank_survivors(NEW.id);

  IF NEW.ended_at IS NULL THEN
    NEW.ended_at := now();
  END IF;

  IF COALESCE(v_ranked, 0) > 0 THEN
    RAISE LOG 'tournament % completed with % unranked survivor(s); ranked by chips before the status flip',
      NEW.id, v_ranked;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_tournaments_rank_before_complete() OWNER TO postgres;

--
-- Name: trg_union_rake_weekly(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_union_rake_weekly() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.union_id IS NOT NULL
     AND NEW.wallet = 'rake_wallet'
     AND NEW.direction = 'credit'
     AND NEW.tx_type = 'rake' THEN
    INSERT INTO public.union_rake_weekly (union_id, club_id, week_start, rake_total, updated_at)
    VALUES (NEW.union_id, NEW.club_id, date_trunc('week', NEW.created_at)::date,
            COALESCE(NEW.amount, 0), now())
    ON CONFLICT ON CONSTRAINT union_rake_weekly_key DO UPDATE
      SET rake_total = public.union_rake_weekly.rake_total + EXCLUDED.rake_total,
          updated_at = now();
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  -- Never let a display rollup block the engine banking rake. A failure here
  -- costs a stale panel; the function's fallback still reads the ledger.
  RAISE WARNING 'union_rake_weekly maintenance failed for tx %: %', NEW.id, SQLERRM;
  RETURN NULL;
END
$$;


ALTER FUNCTION public.trg_union_rake_weekly() OWNER TO postgres;

--
-- Name: trg_user_theme_settings_entitlement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_user_theme_settings_entitlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='INSERT' OR NEW.theme_id IS DISTINCT FROM OLD.theme_id THEN
    IF NOT public.sp_theme_asset_is_owned(NEW.user_id,'theme_id',NEW.theme_id) THEN
      RAISE EXCEPTION 'Theme "%" is VIP only', NEW.theme_id USING ERRCODE='42501'; END IF; END IF;
  IF TG_OP='INSERT' OR NEW.table_id IS DISTINCT FROM OLD.table_id THEN
    IF NOT public.sp_theme_asset_is_owned(NEW.user_id,'table_id',NEW.table_id) THEN
      RAISE EXCEPTION 'Table felt "%" is VIP only', NEW.table_id USING ERRCODE='42501'; END IF; END IF;
  IF TG_OP='INSERT' OR NEW.button_id IS DISTINCT FROM OLD.button_id THEN
    IF NOT public.sp_theme_asset_is_owned(NEW.user_id,'button_id',NEW.button_id) THEN
      RAISE EXCEPTION 'Dealer button "%" is VIP only', NEW.button_id USING ERRCODE='42501'; END IF; END IF;
  IF TG_OP='INSERT' OR NEW.background_id IS DISTINCT FROM OLD.background_id THEN
    IF NOT public.sp_theme_asset_is_owned(NEW.user_id,'background_id',NEW.background_id) THEN
      RAISE EXCEPTION 'Background "%" is VIP only', NEW.background_id USING ERRCODE='42501'; END IF; END IF;
  IF TG_OP='INSERT' OR NEW.cards_id IS DISTINCT FROM OLD.cards_id THEN
    IF NOT public.sp_theme_asset_is_owned(NEW.user_id,'cards_id',NEW.cards_id) THEN
      RAISE EXCEPTION 'Card back "%" is VIP only', NEW.cards_id USING ERRCODE='42501'; END IF; END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION public.trg_user_theme_settings_entitlement() OWNER TO postgres;

--
-- Name: trg_validate_shop_theme_preset(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_validate_shop_theme_preset() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_type       text := COALESCE(NEW.grant_spec->>'type', 'none');
  v_expected   text;
  v_theme_id   text;
  v_avatar_id  text;
  v_qty        integer;
BEGIN
  v_expected := CASE NEW.category
    WHEN 'Time Banks' THEN 'time_bank'
    WHEN 'Table Skins' THEN 'table_skin'
    WHEN 'Throwables' THEN 'throwable'
    WHEN 'Emotes' THEN 'emote_pack'
    WHEN 'Avatars' THEN 'avatar'
    ELSE NULL
  END;

  IF COALESCE(NEW.is_active, false) THEN
    IF v_type NOT IN ('time_bank', 'throwable', 'emote_pack', 'table_skin', 'avatar') THEN
      RAISE EXCEPTION 'Active shop item has no executable grant'
        USING ERRCODE = '23514';
    END IF;
    IF v_expected IS NULL OR v_type <> v_expected THEN
      RAISE EXCEPTION 'Shop category "%" cannot deliver grant type "%"', NEW.category, v_type
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_type IN ('time_bank', 'throwable') THEN
    BEGIN
      v_qty := COALESCE((NEW.grant_spec->>'qty')::integer, 1);
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'Invalid shop grant quantity' USING ERRCODE = '23514';
    END;
    IF v_qty < 1 OR v_qty > 1000 THEN
      RAISE EXCEPTION 'Shop grant quantity must be between 1 and 1000'
        USING ERRCODE = '23514';
    END IF;
    NEW.grant_spec := jsonb_set(NEW.grant_spec, '{qty}', to_jsonb(v_qty), true);
  ELSIF v_type = 'table_skin' THEN
    v_theme_id := public.sp_resolve_theme_preset(NEW.grant_spec->>'theme_id');
    IF v_theme_id IS NULL THEN
      RAISE EXCEPTION 'Unknown Table Studio theme "%"', NEW.grant_spec->>'theme_id'
        USING ERRCODE = '23514';
    END IF;
    NEW.grant_spec := jsonb_set(NEW.grant_spec, '{theme_id}', to_jsonb(v_theme_id), true);
    NEW.stackable := false;
  ELSIF v_type = 'avatar' THEN
    v_avatar_id := public.sp_resolve_avatar_shop_sku(NEW.grant_spec->>'avatar_id');
    IF v_avatar_id IS NULL THEN
      RAISE EXCEPTION 'Unknown avatar-library SKU "%"', NEW.grant_spec->>'avatar_id'
        USING ERRCODE = '23514';
    END IF;
    NEW.grant_spec := jsonb_set(NEW.grant_spec, '{avatar_id}', to_jsonb(v_avatar_id), true);
    NEW.stackable := false;
  ELSIF v_type = 'emote_pack' THEN
    NEW.stackable := false;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_validate_shop_theme_preset() OWNER TO postgres;

--
-- Name: trg_validate_tournament_table_origin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_validate_tournament_table_origin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_parent_status text;
BEGIN
  SELECT t.status::text INTO v_parent_status
    FROM public.tournaments t
   WHERE t.id = NEW.tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament table origin lost parent tournament %', NEW.tournament_id
      USING ERRCODE = '23503';
  END IF;

  IF NEW.origin_kind = 'capacity' THEN
    IF upper(v_parent_status) <> 'RUNNING'
       OR NOT EXISTS (
         SELECT 1
           FROM public.tournament_capacity_table_receipts c
          WHERE c.table_id = NEW.table_id
            AND c.tournament_id = NEW.tournament_id
       ) THEN
      RAISE EXCEPTION
        'TOURNAMENT_CAPACITY_RECEIPT_REQUIRED: RUNNING table % must create its canonical capacity receipt in the same transaction',
        NEW.table_id
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.origin_kind = 'launch' THEN
    IF upper(v_parent_status) <> 'REGISTERING'
       OR NOT EXISTS (
         SELECT 1
           FROM public.tournament_launch_receipts r
          WHERE r.tournament_id = NEW.tournament_id
            AND r.launch_id = NEW.launch_id
            AND r.lease_generation = NEW.launch_lease_generation
            AND r.completed_at IS NULL
       ) THEN
      RAISE EXCEPTION
        'STALE_TOURNAMENT_LAUNCH_TABLE: table % does not belong to the exact incomplete launch receipt',
        NEW.table_id
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.origin_kind = 'prelaunch' THEN
    IF upper(v_parent_status) = 'RUNNING'
       OR EXISTS (
         SELECT 1
           FROM public.tournament_launch_receipts r
          WHERE r.tournament_id = NEW.tournament_id
       ) THEN
      RAISE EXCEPTION
        'TOURNAMENT_PRELAUNCH_ORIGIN_STALE: table % crossed a launch boundary in its birth transaction',
        NEW.table_id
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.origin_kind = 'legacy' THEN
    RETURN NEW;
  ELSE
    RAISE EXCEPTION 'unknown tournament table origin %', NEW.origin_kind
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_validate_tournament_table_origin() OWNER TO postgres;

--
-- Name: trig_sync_like_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trig_sync_like_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- Update social_posts (for post likes - most common case)
        UPDATE social_posts SET like_count = GREATEST(0, COALESCE(like_count, 0) + 1) WHERE id = NEW.post_id;
        -- Update social_reels (for native reels and video_library reels)
        UPDATE social_reels SET like_count = GREATEST(0, COALESCE(like_count, 0) + 1) WHERE id = NEW.post_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE social_posts SET like_count = GREATEST(0, COALESCE(like_count, 0) - 1) WHERE id = OLD.post_id;
        UPDATE social_reels SET like_count = GREATEST(0, COALESCE(like_count, 0) - 1) WHERE id = OLD.post_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION public.trig_sync_like_count() OWNER TO postgres;

--
-- Name: tup_apply_session(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tup_apply_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := NEW.user_id;
  v_qa   integer := COALESCE(NEW.questions_answered, 0);
  v_qc   integer := COALESCE(NEW.questions_correct, 0);
  v_streak integer := COALESCE(NEW.streak, 0);
BEGIN
  INSERT INTO public.training_user_progress AS p (
    user_id, total_sessions, total_questions, total_correct,
    best_streak, current_streak, last_session_at, updated_at
  )
  VALUES (
    v_user, 1, v_qa, v_qc,
    v_streak, v_streak, COALESCE(NEW.session_timestamp, NEW.created_at, now()), now()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    total_sessions   = p.total_sessions  + 1,
    total_questions  = p.total_questions + v_qa,
    total_correct    = p.total_correct   + v_qc,
    best_streak      = GREATEST(p.best_streak, v_streak),
    current_streak   = v_streak,
    last_session_at  = COALESCE(NEW.session_timestamp, NEW.created_at, now()),
    updated_at       = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.tup_apply_session() OWNER TO postgres;

--
-- Name: tup_revert_session(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tup_revert_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := OLD.user_id;
  v_qa   integer := COALESCE(OLD.questions_answered, 0);
  v_qc   integer := COALESCE(OLD.questions_correct, 0);
BEGIN
  IF v_user IS NULL THEN RETURN OLD; END IF;
  -- Decrement counters; clamp at zero so a partial state never becomes
  -- invalid even if the rollup row was previously zeroed.
  UPDATE public.training_user_progress AS p SET
    total_sessions  = GREATEST(0, p.total_sessions  - 1),
    total_questions = GREATEST(0, p.total_questions - v_qa),
    total_correct   = GREATEST(0, p.total_correct   - v_qc),
    updated_at      = now()
  WHERE p.user_id = v_user;
  RETURN OLD;
END;
$$;


ALTER FUNCTION public.tup_revert_session() OWNER TO postgres;

--
-- Name: unblock_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.unblock_user(p_blocked_user_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    DELETE FROM user_blocks 
     WHERE blocker_id = p_caller_user_id AND blocked_id = p_blocked_user_id;

    RETURN jsonb_build_object('success', true, 'unblocked_user_id', p_blocked_user_id);
END;
$$;


