--
-- Name: unique_home_game_slug(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.unique_home_game_slug(base text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  s text := public.slugify_home_game(base);
  candidate text := s;
  n int := 2;
BEGIN
  WHILE EXISTS (SELECT 1 FROM public.social_pages WHERE slug = candidate) LOOP
    candidate := s || '-' || n::text;
    n := n + 1;
    IF n > 500 THEN
      candidate := s || '-' || substr(md5(random()::text), 1, 6);
      EXIT;
    END IF;
  END LOOP;
  RETURN candidate;
END; $$;


ALTER FUNCTION public.unique_home_game_slug(base text) OWNER TO postgres;

