--
-- Name: unlock_chips_from_table(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.unlock_chips_from_table(p_club_id uuid, p_user_id uuid, p_table_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_balance_before numeric;
  v_balance_after numeric;
  v_credit numeric;
BEGIN
  v_credit := COALESCE(p_amount, 0);
  IF v_credit < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount cannot be negative');
  END IF;

  SELECT COALESCE(chip_balance, 0) INTO v_balance_before
  FROM club_members
  WHERE club_id = p_club_id AND user_id = p_user_id
  FOR UPDATE;

  IF v_balance_before IS NULL THEN
    -- Not a member: insert a membership row so the credit isn't lost
    INSERT INTO club_members (club_id, user_id, role, chip_balance, joined_at, created_at, updated_at, status, is_active)
    VALUES (p_club_id, p_user_id, 'player', v_credit::integer, NOW(), NOW(), NOW(), 'active', true)
    ON CONFLICT (club_id, user_id) DO UPDATE
      SET chip_balance = COALESCE(club_members.chip_balance, 0) + EXCLUDED.chip_balance,
          updated_at = NOW();
    v_balance_before := 0;
    v_balance_after := v_credit;
  ELSE
    UPDATE club_members
    SET chip_balance = COALESCE(chip_balance, 0) + v_credit::integer,
        updated_at = NOW()
    WHERE club_id = p_club_id AND user_id = p_user_id;
    v_balance_after := v_balance_before + v_credit;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'unlocked', v_credit,
    'balance', v_balance_before,
    'balance_after', v_balance_after
  );
END;
$$;


ALTER FUNCTION public.unlock_chips_from_table(p_club_id uuid, p_user_id uuid, p_table_id uuid, p_amount numeric) OWNER TO postgres;

