--
-- Name: update_leaderboard(uuid, text, integer, integer, numeric, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_leaderboard(p_user_id uuid, p_game_mode text, p_level integer, p_score integer, p_accuracy numeric, p_time_taken integer, p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_current_score INTEGER;
    v_perfect_game BOOLEAN;
BEGIN
    v_perfect_game := (p_accuracy >= 100.00);
    
    SELECT score INTO v_current_score
    FROM memory_leaderboards
    WHERE user_id = p_user_id
    AND game_mode = p_game_mode
    AND (level = p_level OR (level IS NULL AND p_level IS NULL));
    
    IF v_current_score IS NULL OR p_score > v_current_score THEN
        INSERT INTO memory_leaderboards (
            user_id, game_mode, level, score, accuracy, time_taken, perfect_game, session_id
        ) VALUES (
            p_user_id, p_game_mode, p_level, p_score, p_accuracy, p_time_taken, v_perfect_game, p_session_id
        )
        ON CONFLICT (user_id, game_mode, level)
        DO UPDATE SET
            score = EXCLUDED.score,
            accuracy = EXCLUDED.accuracy,
            time_taken = EXCLUDED.time_taken,
            perfect_game = EXCLUDED.perfect_game,
            session_id = EXCLUDED.session_id,
            created_at = NOW();
        
        RETURN jsonb_build_object(
            'success', true,
            'new_record', true,
            'score', p_score
        );
    ELSE
        RETURN jsonb_build_object(
            'success', true,
            'new_record', false,
            'score', v_current_score
        );
    END IF;
END;
$$;


ALTER FUNCTION public.update_leaderboard(p_user_id uuid, p_game_mode text, p_level integer, p_score integer, p_accuracy numeric, p_time_taken integer, p_session_id uuid) OWNER TO postgres;

