--
-- Name: update_live_metrics(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_live_metrics(p_stream_id uuid, p_viewer_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller     uuid := auth.uid();
  v_broadcaster uuid;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  IF p_viewer_count IS NULL OR p_viewer_count < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid viewer_count');
  END IF;

  -- Only the broadcaster of the stream can update these metrics.
  -- (The client code only calls this from the broadcaster path anyway, but
  -- defense in depth.)
  SELECT broadcaster_id INTO v_broadcaster 
  FROM live_streams WHERE id = p_stream_id;

  IF v_broadcaster IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Stream not found');
  END IF;
  IF v_broadcaster <> v_caller THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not the broadcaster');
  END IF;

  -- Atomic dual-update: viewer_count = current, peak_viewers = max(prev, current)
  UPDATE live_streams
     SET viewer_count = p_viewer_count,
         peak_viewers = GREATEST(COALESCE(peak_viewers, 0), p_viewer_count)
   WHERE id = p_stream_id;

  RETURN jsonb_build_object('success', true, 'viewer_count', p_viewer_count);
END;
$$;


ALTER FUNCTION public.update_live_metrics(p_stream_id uuid, p_viewer_count integer) OWNER TO postgres;

--
-- Name: FUNCTION update_live_metrics(p_stream_id uuid, p_viewer_count integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.update_live_metrics(p_stream_id uuid, p_viewer_count integer) IS 'Atomic viewer_count + peak_viewers update for the broadcaster. SECURITY DEFINER bypasses the live_streams metric-column guard trigger. Replaces two separate UPDATEs in LiveStreamService._updateViewerCount.';


