--
-- Name: update_page_preferences(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_page_preferences(p_user_id uuid, p_column_name text, p_preferences jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_preferences jsonb;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Unauthorized: User ID mismatch';
  END IF;
  IF p_column_name NOT IN ('bankroll_preferences','trivia_preferences','video_preferences',
    'video_library_preferences','news_preferences','memory_games_preferences',
    'diamond_arcade_preferences','diamond_arena_preferences','poker_near_me_preferences') THEN
    RAISE EXCEPTION 'Invalid preference column: %', p_column_name;
  END IF;
  EXECUTE format(
    'UPDATE profiles SET %I = $1, updated_at = now() WHERE id = $2 RETURNING %I',
    p_column_name, p_column_name
  ) INTO v_preferences USING p_preferences, p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profile not found';
  END IF;
  RETURN v_preferences;
END; $_$;


ALTER FUNCTION public.update_page_preferences(p_user_id uuid, p_column_name text, p_preferences jsonb) OWNER TO postgres;

--
-- Name: update_player_hand_stats(uuid, numeric, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_player_hand_stats(p_user_id uuid, p_profit numeric DEFAULT 0, p_is_voluntary boolean DEFAULT false, p_is_preflop_raise boolean DEFAULT false, p_went_to_showdown boolean DEFAULT false, p_won_at_showdown boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  -- NAME IS MISLEADING - READ BEFORE USING (documented 2026-08-19).
  -- This function increments profiles.total_hands_played and NOTHING ELSE.
  -- p_profit, p_is_voluntary, p_is_preflop_raise, p_went_to_showdown and
  -- p_won_at_showdown are accepted for call-site compatibility and DISCARDED.
  -- It has never written player_stats. Believing otherwise is why every profit
  -- and ROI leaderboard read 0.00 until 2026-08-19.
  --
  -- Real stat sources:
  --   winnings / hands_dealt / sum_big_blind -> hand_history_fold_stats trigger
  --   losses (contributions)                 -> promo_apply_playthrough
  -- Do not add stat writes here; add them to the trigger, which sees every hand.
  UPDATE profiles
  SET total_hands_played = COALESCE(total_hands_played, 0) + 1,
      updated_at = now()
  WHERE id = p_user_id;
END; $$;


ALTER FUNCTION public.update_player_hand_stats(p_user_id uuid, p_profit numeric, p_is_voluntary boolean, p_is_preflop_raise boolean, p_went_to_showdown boolean, p_won_at_showdown boolean) OWNER TO postgres;

--
-- Name: FUNCTION update_player_hand_stats(p_user_id uuid, p_profit numeric, p_is_voluntary boolean, p_is_preflop_raise boolean, p_went_to_showdown boolean, p_won_at_showdown boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.update_player_hand_stats(p_user_id uuid, p_profit numeric, p_is_voluntary boolean, p_is_preflop_raise boolean, p_went_to_showdown boolean, p_won_at_showdown boolean) IS 'Increments profiles.total_hands_played ONLY. All other arguments are discarded. Does not touch player_stats - see the trigger hand_history_fold_stats and promo_apply_playthrough for the real counters.';


--
-- Name: update_player_stats_from_session(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_player_stats_from_session() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  session_hours DECIMAL(6,2);
BEGIN
  IF NEW.status != 'completed' OR NEW.total_time_minutes IS NULL THEN
    RETURN NEW;
  END IF;
  session_hours := NEW.total_time_minutes / 60.0;
  INSERT INTO commander_player_stats (
    venue_id, player_id, first_visit, last_visit, total_visits,
    total_hours, total_buyin, total_cashout
  )
  VALUES (
    NEW.venue_id, NEW.player_id, CURRENT_DATE, CURRENT_DATE, 1, session_hours,
    COALESCE(NEW.total_buyin, 0),
    0  -- BUG-21 fix: commander_player_sessions has no total_cashout column
  )
  ON CONFLICT (venue_id, player_id) DO UPDATE SET
    last_visit   = CURRENT_DATE,
    total_visits = commander_player_stats.total_visits + 1,
    total_hours  = commander_player_stats.total_hours + session_hours,
    total_buyin  = commander_player_stats.total_buyin + COALESCE(NEW.total_buyin, 0),
    -- total_cashout stays at its accumulated value (no session delta)
    avg_session_hours     = (commander_player_stats.total_hours + session_hours)
                            / (commander_player_stats.total_visits + 1),
    longest_session_hours = GREATEST(commander_player_stats.longest_session_hours, session_hours),
    updated_at            = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_player_stats_from_session() OWNER TO postgres;

