--
-- Name: update_profile_vip_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_profile_vip_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    IF NEW.status = 'active' OR NEW.status = 'trialing' THEN
        UPDATE profiles
        SET 
            is_vip = true,
            vip_tier = NEW.tier,
            vip_expires_at = NEW.current_period_end,
            vip_canceled_at = NULL
        WHERE id = NEW.user_id;
    ELSIF NEW.status = 'canceled' THEN
        UPDATE profiles
        SET 
            is_vip = false,
            vip_tier = NULL,
            vip_canceled_at = NEW.canceled_at
        WHERE id = NEW.user_id;
    ELSIF NEW.status IN ('past_due', 'unpaid') THEN
        -- Keep VIP active during grace period
        UPDATE profiles
        SET vip_tier = NEW.tier
        WHERE id = NEW.user_id;
    END IF;
    
    RETURN NEW;
END;
$$;


