CREATE FUNCTION public.update_union_venue_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  -- Note: unions table may need to be renamed to commander_unions
  IF TG_OP = 'INSERT' THEN
    UPDATE commander_unions SET venue_count = venue_count + 1, updated_at = now() WHERE id = NEW.union_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE commander_unions SET venue_count = venue_count - 1, updated_at = now() WHERE id = OLD.union_id;
  END IF;
  RETURN NULL;
END;
$$;


