--
-- Name: update_venue_follower_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_venue_follower_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venue_id integer;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_venue_id := NEW.venue_id;
  ELSIF TG_OP = 'DELETE' THEN
    v_venue_id := OLD.venue_id;
  ELSE
    -- UPDATE: handle both old + new venue_id in case of re-target
    IF NEW.venue_id IS DISTINCT FROM OLD.venue_id THEN
      UPDATE public.poker_venues
      SET follower_count = (
        SELECT COUNT(*) FROM public.commander_venue_followers
        WHERE venue_id = OLD.venue_id
      )
      WHERE id = OLD.venue_id;
    END IF;
    v_venue_id := NEW.venue_id;
  END IF;

  IF v_venue_id IS NOT NULL THEN
    UPDATE public.poker_venues
    SET follower_count = (
      SELECT COUNT(*) FROM public.commander_venue_followers
      WHERE venue_id = v_venue_id
    )
    WHERE id = v_venue_id;
  END IF;

  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'update_venue_follower_count failed: % %', SQLERRM, SQLSTATE;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.update_venue_follower_count() OWNER TO postgres;

--
-- Name: upload_venue_photo(integer, uuid, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upload_venue_photo(p_venue_id integer, p_caller_user_id uuid, p_url text, p_thumbnail_url text DEFAULT NULL::text, p_caption text DEFAULT NULL::text, p_category text DEFAULT 'interior'::text, p_is_featured boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_is_manager boolean; v_id uuid; v_next_order int;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    IF p_url IS NULL OR length(p_url) < 10 THEN RAISE EXCEPTION 'INVALID_URL'; END IF;
    v_is_manager := public.is_venue_manager(p_caller_user_id, p_venue_id);
    IF NOT v_is_manager THEN RAISE EXCEPTION 'NOT_VENUE_MANAGER'; END IF;

    SELECT COALESCE(MAX(display_order), 0) + 1 INTO v_next_order 
      FROM commander_venue_photos WHERE venue_id = p_venue_id;

    INSERT INTO commander_venue_photos (
        venue_id, uploaded_by, url, thumbnail_url, caption, category, 
        is_featured, display_order
    ) VALUES (
        p_venue_id, p_caller_user_id, p_url, p_thumbnail_url, p_caption, p_category,
        p_is_featured, v_next_order
    ) RETURNING id INTO v_id;

    RETURN jsonb_build_object('success', true, 'photo_id', v_id);
END; $$;


ALTER FUNCTION public.upload_venue_photo(p_venue_id integer, p_caller_user_id uuid, p_url text, p_thumbnail_url text, p_caption text, p_category text, p_is_featured boolean) OWNER TO postgres;

--
-- Name: upsert_horse_mind_pairs(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_horse_mind_pairs(rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  n integer := 0;
  r jsonb;
BEGIN
  IF rows IS NULL OR jsonb_typeof(rows) <> 'array' THEN
    RETURN 0;
  END IF;
  FOR r IN SELECT * FROM jsonb_array_elements(rows) LOOP
    CONTINUE WHEN r->>'attacker_id' IS NULL OR length(r->>'attacker_id') = 0 OR length(r->>'attacker_id') > 128;
    CONTINUE WHEN r->>'victim_id' IS NULL OR length(r->>'victim_id') = 0 OR length(r->>'victim_id') > 128;
    INSERT INTO public.horse_mind_pairs AS t
      (attacker_id, victim_id, n3, opp3, n_r, opp_r, updated_at)
    VALUES
      (r->>'attacker_id',
       r->>'victim_id',
       COALESCE((r->>'n3')::integer, 0),
       COALESCE((r->>'opp3')::integer, 0),
       COALESCE((r->>'n_r')::integer, 0),
       COALESCE((r->>'opp_r')::integer, 0),
       now())
    ON CONFLICT (attacker_id, victim_id) DO UPDATE SET
      n3         = GREATEST(t.n3, EXCLUDED.n3),
      opp3       = GREATEST(t.opp3, EXCLUDED.opp3),
      n_r        = GREATEST(t.n_r, EXCLUDED.n_r),
      opp_r      = GREATEST(t.opp_r, EXCLUDED.opp_r),
      updated_at = now();
    n := n + 1;
  END LOOP;
  RETURN n;
END
$$;


ALTER FUNCTION public.upsert_horse_mind_pairs(rows jsonb) OWNER TO postgres;

--
-- Name: upsert_horse_mind_stats(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_horse_mind_stats(rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  n integer := 0;
  r jsonb;
BEGIN
  IF rows IS NULL OR jsonb_typeof(rows) <> 'array' THEN
    RETURN 0;
  END IF;
  FOR r IN SELECT * FROM jsonb_array_elements(rows) LOOP
    CONTINUE WHEN r->>'user_id' IS NULL OR length(r->>'user_id') = 0 OR length(r->>'user_id') > 128;
    INSERT INTO public.horse_mind_stats AS t
      (user_id, hands, vpip, pfr, three_bet, aggr, passive, folds, faced_aggr,
       cbet_opps, cbet_folds, f3b_opps, f3b_folds, bigbet_sd, bigbet_sd_strong,
       post_aggr, post_passive, river_bet_opps, river_bet_folds, checks,
       snap_bet_sd, snap_bet_sd_strong, tank_bet_sd, tank_bet_sd_strong,
       r_hands, r_folds, r_faced_aggr, r_aggr, r_passive, r_checks, updated_at)
    VALUES
      (r->>'user_id',
       COALESCE((r->>'hands')::integer, 0),
       COALESCE((r->>'vpip')::integer, 0),
       COALESCE((r->>'pfr')::integer, 0),
       COALESCE((r->>'three_bet')::integer, 0),
       COALESCE((r->>'aggr')::integer, 0),
       COALESCE((r->>'passive')::integer, 0),
       COALESCE((r->>'folds')::integer, 0),
       COALESCE((r->>'faced_aggr')::integer, 0),
       COALESCE((r->>'cbet_opps')::integer, 0),
       COALESCE((r->>'cbet_folds')::integer, 0),
       COALESCE((r->>'f3b_opps')::integer, 0),
       COALESCE((r->>'f3b_folds')::integer, 0),
       COALESCE((r->>'bigbet_sd')::integer, 0),
       COALESCE((r->>'bigbet_sd_strong')::integer, 0),
       COALESCE((r->>'post_aggr')::integer, 0),
       COALESCE((r->>'post_passive')::integer, 0),
       COALESCE((r->>'river_bet_opps')::integer, 0),
       COALESCE((r->>'river_bet_folds')::integer, 0),
       COALESCE((r->>'checks')::integer, 0),
       COALESCE((r->>'snap_bet_sd')::integer, 0),
       COALESCE((r->>'snap_bet_sd_strong')::integer, 0),
       COALESCE((r->>'tank_bet_sd')::integer, 0),
       COALESCE((r->>'tank_bet_sd_strong')::integer, 0),
       COALESCE((r->>'r_hands')::real, 0),
       COALESCE((r->>'r_folds')::real, 0),
       COALESCE((r->>'r_faced_aggr')::real, 0),
       COALESCE((r->>'r_aggr')::real, 0),
       COALESCE((r->>'r_passive')::real, 0),
       COALESCE((r->>'r_checks')::real, 0),
       now())
    ON CONFLICT (user_id) DO UPDATE SET
      hands            = GREATEST(t.hands, EXCLUDED.hands),
      vpip             = GREATEST(t.vpip, EXCLUDED.vpip),
      pfr              = GREATEST(t.pfr, EXCLUDED.pfr),
      three_bet        = GREATEST(t.three_bet, EXCLUDED.three_bet),
      aggr             = GREATEST(t.aggr, EXCLUDED.aggr),
      passive          = GREATEST(t.passive, EXCLUDED.passive),
      folds            = GREATEST(t.folds, EXCLUDED.folds),
      faced_aggr       = GREATEST(t.faced_aggr, EXCLUDED.faced_aggr),
      cbet_opps        = GREATEST(t.cbet_opps, EXCLUDED.cbet_opps),
      cbet_folds       = GREATEST(t.cbet_folds, EXCLUDED.cbet_folds),
      f3b_opps         = GREATEST(t.f3b_opps, EXCLUDED.f3b_opps),
      f3b_folds        = GREATEST(t.f3b_folds, EXCLUDED.f3b_folds),
      bigbet_sd        = GREATEST(t.bigbet_sd, EXCLUDED.bigbet_sd),
      bigbet_sd_strong = GREATEST(t.bigbet_sd_strong, EXCLUDED.bigbet_sd_strong),
      post_aggr        = GREATEST(t.post_aggr, EXCLUDED.post_aggr),
      post_passive     = GREATEST(t.post_passive, EXCLUDED.post_passive),
      river_bet_opps   = GREATEST(t.river_bet_opps, EXCLUDED.river_bet_opps),
      river_bet_folds  = GREATEST(t.river_bet_folds, EXCLUDED.river_bet_folds),
      checks           = GREATEST(t.checks, EXCLUDED.checks),
      snap_bet_sd        = GREATEST(t.snap_bet_sd, EXCLUDED.snap_bet_sd),
      snap_bet_sd_strong = GREATEST(t.snap_bet_sd_strong, EXCLUDED.snap_bet_sd_strong),
      tank_bet_sd        = GREATEST(t.tank_bet_sd, EXCLUDED.tank_bet_sd),
      tank_bet_sd_strong = GREATEST(t.tank_bet_sd_strong, EXCLUDED.tank_bet_sd_strong),
      r_hands      = EXCLUDED.r_hands,
      r_folds      = EXCLUDED.r_folds,
      r_faced_aggr = EXCLUDED.r_faced_aggr,
      r_aggr       = EXCLUDED.r_aggr,
      r_passive    = EXCLUDED.r_passive,
      r_checks     = EXCLUDED.r_checks,
      updated_at   = now();
    n := n + 1;
  END LOOP;
  RETURN n;
END
$$;


ALTER FUNCTION public.upsert_horse_mind_stats(rows jsonb) OWNER TO postgres;

--
-- Name: upsert_horse_mind_stats_scoped(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_horse_mind_stats_scoped(rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare n integer := 0; r jsonb;
begin
  if rows is null or jsonb_typeof(rows) <> 'array' then return 0; end if;
  for r in select * from jsonb_array_elements(rows) loop
    continue when r->>'user_id' is null or length(r->>'user_id') = 0 or length(r->>'user_id') > 128;
    continue when r->>'scope' is null or (r->>'scope') !~ '^(holdem|omaha|sixplus):(hu|short|full)$';
    insert into public.horse_mind_stats_scoped as t
      (user_id, scope, hands, vpip, pfr, three_bet, aggr, passive, folds, faced_aggr,
       cbet_opps, cbet_folds, f3b_opps, f3b_folds, bigbet_sd, bigbet_sd_strong,
       river_bet_opps, river_bet_folds, checks, post_aggr, post_passive,
       snap_bet_sd, snap_bet_sd_strong, tank_bet_sd, tank_bet_sd_strong, updated_at)
    values
      (r->>'user_id', r->>'scope',
       coalesce((r->>'hands')::integer, 0),
       coalesce((r->>'vpip')::integer, 0),
       coalesce((r->>'pfr')::integer, 0),
       coalesce((r->>'three_bet')::integer, 0),
       coalesce((r->>'aggr')::integer, 0),
       coalesce((r->>'passive')::integer, 0),
       coalesce((r->>'folds')::integer, 0),
       coalesce((r->>'faced_aggr')::integer, 0),
       coalesce((r->>'cbet_opps')::integer, 0),
       coalesce((r->>'cbet_folds')::integer, 0),
       coalesce((r->>'f3b_opps')::integer, 0),
       coalesce((r->>'f3b_folds')::integer, 0),
       coalesce((r->>'bigbet_sd')::integer, 0),
       coalesce((r->>'bigbet_sd_strong')::integer, 0),
       coalesce((r->>'river_bet_opps')::integer, 0),
       coalesce((r->>'river_bet_folds')::integer, 0),
       coalesce((r->>'checks')::integer, 0),
       coalesce((r->>'post_aggr')::integer, 0),
       coalesce((r->>'post_passive')::integer, 0),
       coalesce((r->>'snap_bet_sd')::integer, 0),
       coalesce((r->>'snap_bet_sd_strong')::integer, 0),
       coalesce((r->>'tank_bet_sd')::integer, 0),
       coalesce((r->>'tank_bet_sd_strong')::integer, 0),
       now())
    on conflict (user_id, scope) do update set
      hands = greatest(t.hands, excluded.hands),
      vpip = greatest(t.vpip, excluded.vpip),
      pfr = greatest(t.pfr, excluded.pfr),
      three_bet = greatest(t.three_bet, excluded.three_bet),
      aggr = greatest(t.aggr, excluded.aggr),
      passive = greatest(t.passive, excluded.passive),
      folds = greatest(t.folds, excluded.folds),
      faced_aggr = greatest(t.faced_aggr, excluded.faced_aggr),
      cbet_opps = greatest(t.cbet_opps, excluded.cbet_opps),
      cbet_folds = greatest(t.cbet_folds, excluded.cbet_folds),
      f3b_opps = greatest(t.f3b_opps, excluded.f3b_opps),
      f3b_folds = greatest(t.f3b_folds, excluded.f3b_folds),
      bigbet_sd = greatest(t.bigbet_sd, excluded.bigbet_sd),
      bigbet_sd_strong = greatest(t.bigbet_sd_strong, excluded.bigbet_sd_strong),
      river_bet_opps = greatest(t.river_bet_opps, excluded.river_bet_opps),
      river_bet_folds = greatest(t.river_bet_folds, excluded.river_bet_folds),
      checks = greatest(t.checks, excluded.checks),
      post_aggr = greatest(t.post_aggr, excluded.post_aggr),
      post_passive = greatest(t.post_passive, excluded.post_passive),
      snap_bet_sd = greatest(t.snap_bet_sd, excluded.snap_bet_sd),
      snap_bet_sd_strong = greatest(t.snap_bet_sd_strong, excluded.snap_bet_sd_strong),
      tank_bet_sd = greatest(t.tank_bet_sd, excluded.tank_bet_sd),
      tank_bet_sd_strong = greatest(t.tank_bet_sd_strong, excluded.tank_bet_sd_strong),
      updated_at = now();
    n := n + 1;
  end loop;
  return n;
end $_$;


ALTER FUNCTION public.upsert_horse_mind_stats_scoped(rows jsonb) OWNER TO postgres;

--
-- Name: validate_home_game_social_page_link(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_home_game_social_page_link() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  sp_type text;
  sp_linked_group text;
BEGIN
  IF NEW.social_page_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT page_type, linked_entity_id
    INTO sp_type, sp_linked_group
  FROM public.social_pages
  WHERE id = NEW.social_page_id;

  IF sp_type IS NULL THEN
    -- FK will catch this; belt + suspenders.
    RAISE EXCEPTION 'social_page_id % does not exist', NEW.social_page_id;
  END IF;

  IF sp_type <> 'home_game' THEN
    RAISE EXCEPTION 'commander_home_games.social_page_id must reference a social_page of page_type=home_game, got %', sp_type;
  END IF;

  -- The event's group MUST match the social page's linked group.
  IF NEW.group_id IS NOT NULL AND sp_linked_group IS DISTINCT FROM NEW.group_id::text THEN
    RAISE EXCEPTION 'commander_home_games event (group_id=%) cannot point at social_page linked to different group (linked_entity_id=%)',
      NEW.group_id, sp_linked_group;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.validate_home_game_social_page_link() OWNER TO postgres;

--
-- Name: validate_mentions_post_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_mentions_post_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.post_id IS NULL THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.social_posts WHERE id = NEW.post_id) THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.social_reels WHERE id = NEW.post_id) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'mentions.post_id % not found in social_posts or social_reels', NEW.post_id;
END;
$$;


ALTER FUNCTION public.validate_mentions_post_id() OWNER TO postgres;

--
-- Name: validate_social_comment_post_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_social_comment_post_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Allow NULL post_id (legacy rows)
  IF NEW.post_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Check social_posts first (most common case)
  IF EXISTS (SELECT 1 FROM public.social_posts WHERE id = NEW.post_id) THEN
    NEW.post_source := 'social_posts';
    RETURN NEW;
  END IF;

  -- Fall back to social_reels
  IF EXISTS (SELECT 1 FROM public.social_reels WHERE id = NEW.post_id) THEN
    NEW.post_source := 'social_reels';
    RETURN NEW;
  END IF;

  -- Neither table has the referenced ID
  RAISE EXCEPTION 'social_comments.post_id % not found in social_posts or social_reels', NEW.post_id;
END;
$$;


ALTER FUNCTION public.validate_social_comment_post_id() OWNER TO postgres;

