--
-- Name: validate_trivia_pvp_session_link(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_trivia_pvp_session_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_match public.trivia_pvp_matches%ROWTYPE;
    v_session public.trivia_sessions%ROWTYPE;
    v_reference text;
    v_transaction_count integer;
    v_exact_transaction_count integer;
BEGIN
    SELECT * INTO v_match FROM public.trivia_pvp_matches WHERE id = NEW.match_id;
    SELECT * INTO v_session FROM public.trivia_sessions WHERE id = NEW.session_id;

    IF v_match.id IS NULL THEN
        RAISE EXCEPTION 'pvp session link: match not found';
    END IF;
    IF v_session.id IS NULL THEN
        RAISE EXCEPTION 'pvp session link: session not found';
    END IF;
    IF (NEW.side = 1 AND NEW.user_id IS DISTINCT FROM v_match.player1_id)
       OR (NEW.side = 2 AND NEW.user_id IS DISTINCT FROM v_match.player2_id) THEN
        RAISE EXCEPTION 'pvp session link: participant mismatch';
    END IF;
    IF v_match.status IS NULL
       OR v_match.status NOT IN ('active', 'settling', 'complete', 'completed') THEN
        RAISE EXCEPTION 'pvp session link: match state mismatch';
    END IF;
    IF v_session.user_id IS DISTINCT FROM NEW.user_id
       OR v_session.mode IS DISTINCT FROM 'pvp' THEN
        RAISE EXCEPTION 'pvp session link: session owner/mode mismatch';
    END IF;
    IF v_session.status IS NULL
       OR v_session.status NOT IN ('open', 'submitted', 'expired') THEN
        RAISE EXCEPTION 'pvp session link: session state mismatch';
    END IF;
    IF v_session.entry_state IS DISTINCT FROM 'charged'
       OR v_session.entry_cost IS DISTINCT FROM v_match.stake_amount THEN
        RAISE EXCEPTION 'pvp session link: escrow mismatch';
    END IF;
    IF jsonb_typeof(v_match.questions) IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_match.questions) <> 20
       OR array_ndims(v_session.question_ids) IS DISTINCT FROM 1
       OR cardinality(v_session.question_ids) <> 20
       OR array_position(v_session.question_ids, NULL::uuid) IS NOT NULL
       OR (SELECT count(DISTINCT question_id) FROM unnest(v_session.question_ids) AS question_id) <> 20
       OR v_match.questions IS DISTINCT FROM to_jsonb(v_session.question_ids) THEN
        RAISE EXCEPTION 'pvp session link: roster mismatch';
    END IF;
    IF v_session.created_at IS NULL
       OR v_match.created_at IS NULL
       OR v_session.created_at < v_match.created_at - interval '1 second'
       OR v_session.created_at > v_match.created_at + interval '30 minutes' THEN
        RAISE EXCEPTION 'pvp session link: time mismatch';
    END IF;
    IF v_session.expires_at IS NULL
       OR v_session.expires_at < v_session.created_at
       OR v_session.expires_at > v_match.created_at + interval '30 minutes'
       OR NEW.created_at IS NULL
       OR NEW.created_at < v_session.created_at - interval '1 second'
       OR NEW.created_at > v_match.created_at + interval '30 minutes' THEN
        RAISE EXCEPTION 'pvp session link: deadline mismatch';
    END IF;
    IF v_session.status = 'submitted' AND (
        v_session.submitted_at IS NULL
        OR v_session.submitted_at > v_session.expires_at
        OR v_session.submitted_at > v_match.created_at + interval '30 minutes'
        OR v_session.correct_count IS NULL
        OR v_session.correct_count NOT BETWEEN 0 AND 20
    ) THEN
        RAISE EXCEPTION 'pvp session link: submitted result mismatch';
    END IF;

    v_reference := 'pvp_stake_' || NEW.match_id::text || '_' || NEW.user_id::text;
    SELECT count(*),
           count(*) FILTER (
               WHERE d.user_id = NEW.user_id
                 AND d.amount = -v_match.stake_amount
                 AND COALESCE(
                     NULLIF(BTRIM(d.transaction_type), ''),
                     NULLIF(BTRIM(d.type), '')
                 ) = 'pvp_stake'
           )
      INTO v_transaction_count, v_exact_transaction_count
      FROM public.diamond_transactions AS d
     WHERE d.reference_id = v_reference;
    IF v_transaction_count <> 1 OR v_exact_transaction_count <> 1 THEN
        RAISE EXCEPTION 'pvp session link: exact stake transaction missing';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.validate_trivia_pvp_session_link() OWNER TO postgres;

--
-- Name: venues_in_radius(numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.venues_in_radius(search_lat numeric, search_lng numeric, radius_miles integer) RETURNS TABLE(id integer, name text, venue_type text, city text, state text, lat numeric, lng numeric, poker_tables integer, is_featured boolean, distance_miles numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    pv.id,
    pv.name,
    pv.venue_type,
    pv.city,
    pv.state,
    pv.lat,
    pv.lng,
    pv.poker_tables,
    pv.is_featured,
    ROUND(
      (3959 * acos(
        cos(radians(search_lat)) * cos(radians(pv.lat)) *
        cos(radians(pv.lng) - radians(search_lng)) +
        sin(radians(search_lat)) * sin(radians(pv.lat))
      ))::numeric,
      2
    ) AS distance_miles
  FROM poker_venues pv
  WHERE pv.lat IS NOT NULL 
    AND pv.lng IS NOT NULL
    AND (
      3959 * acos(
        cos(radians(search_lat)) * cos(radians(pv.lat)) *
        cos(radians(pv.lng) - radians(search_lng)) +
        sin(radians(search_lat)) * sin(radians(pv.lat))
      )
    ) <= radius_miles
  ORDER BY distance_miles;
END;
$$;


ALTER FUNCTION public.venues_in_radius(search_lat numeric, search_lng numeric, radius_miles integer) OWNER TO postgres;

--
-- Name: verify_and_log_union_rakeback(uuid, timestamp with time zone, timestamp with time zone, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_and_log_union_rakeback(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_total_rakeback numeric) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$ DECLARE v_exists boolean; BEGIN SELECT EXISTS(SELECT 1 FROM union_rakeback_log WHERE union_id = p_union_id AND period_start = p_period_start AND period_end = p_period_end) INTO v_exists; IF v_exists THEN RETURN false; END IF; INSERT INTO union_rakeback_log (union_id, period_start, period_end, total_rakeback, executed_at) VALUES (p_union_id, p_period_start, p_period_end, p_total_rakeback, now()) ON CONFLICT DO NOTHING; RETURN true; END; $$;


ALTER FUNCTION public.verify_and_log_union_rakeback(p_union_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_total_rakeback numeric) OWNER TO postgres;

--
-- Name: verify_commander_admin_pin(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_commander_admin_pin(p_user_id uuid, p_pin_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row commander_admin_pins%rowtype;
begin
  select * into v_row from commander_admin_pins where user_id = p_user_id;
  if not found then
    return jsonb_build_object('pin_set', false, 'valid', false, 'locked', false);
  end if;
  if v_row.locked_until is not null and v_row.locked_until > now() then
    return jsonb_build_object('pin_set', true, 'valid', false, 'locked', true,
                              'locked_until', v_row.locked_until);
  end if;
  if v_row.pin_hash = p_pin_hash then
    update commander_admin_pins set fail_count = 0, locked_until = null, updated_at = now()
     where user_id = p_user_id;
    return jsonb_build_object('pin_set', true, 'valid', true, 'locked', false);
  end if;
  update commander_admin_pins
     set fail_count = fail_count + 1,
         locked_until = case when fail_count + 1 >= 10 then now() + interval '15 minutes' else locked_until end,
         updated_at = now()
   where user_id = p_user_id;
  return jsonb_build_object('pin_set', true, 'valid', false, 'locked', false);
end;
$$;


ALTER FUNCTION public.verify_commander_admin_pin(p_user_id uuid, p_pin_hash text) OWNER TO postgres;

--
-- Name: verify_home_games_health(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_home_games_health() RETURNS TABLE(category text, check_name text, status text, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.category, c.check_name, c.status, c.detail
    FROM verify_home_games_health_core() c
   WHERE c.check_name NOT IN (
     'length caps present on 10 user-facing text RPCs',
     'platform policies seeded',
     '5 spam-vector RPCs use fn_try_consume_home_rate_limit',
     'admin-action audit log coverage'
   )
  UNION ALL
  SELECT a.category, a.check_name, a.status, a.detail
    FROM verify_home_games_health_addendum() a;
$$;


ALTER FUNCTION public.verify_home_games_health() OWNER TO postgres;

--
-- Name: verify_home_games_health_addendum(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_home_games_health_addendum() RETURNS TABLE(category text, check_name text, status text, detail text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 'compliance'::text, 'length caps on every text-writing home RPC'::text,
         (SELECT count(*) FILTER (WHERE has_cap)::text || ' / ' || count(*)::text
            FROM fn_hg_text_writing_functions()),
         'derived from the schema, not a hard-coded list of names'
  UNION ALL
  SELECT 'compliance', 'platform policies seeded',
         CASE WHEN (SELECT count(*) FROM platform_policies pp
                     WHERE pp.key IN ('home_games.tos.version',
                                      'home_games.privacy.version',
                                      'home_games.community_guidelines.version',
                                      'home_games.money_policy.version')) = 4
              THEN '✓' ELSE '✗' END,
         'tos / privacy / community guidelines / money policy versions'
  UNION ALL
  SELECT 'rate_limit', '5 spam-vector RPCs use fn_try_consume_home_rate_limit',
         (SELECT count(*)::text || ' / 5' FROM pg_proc p
            JOIN pg_namespace n ON n.oid = p.pronamespace
           WHERE n.nspname = 'public'
             AND p.proname IN ('create_home_group_post','create_home_post_comment',
                               'create_home_group_invite_token','record_home_game_photo',
                               'toggle_home_post_like')
             AND pg_get_functiondef(p.oid) ILIKE '%fn_try_consume_home_rate_limit%'),
         'post / comment / invite / photo / like'
  UNION ALL
  SELECT 'auth', 'staff-authority tables write an audit row',
         (SELECT count(DISTINCT c.relname)::text || ' / 3'
            FROM pg_trigger tg
            JOIN pg_class c ON c.oid = tg.tgrelid
            JOIN pg_proc p ON p.oid = tg.tgfoid
           WHERE NOT tg.tgisinternal
             AND p.proname = 'fn_home_audit_privileged_write'
             AND c.relname IN ('commander_home_seats',
                               'commander_home_game_templates',
                               'commander_home_invite_tokens')),
         'seats, game templates, invite tokens - every write, not just the RPCs';
END;
$$;


ALTER FUNCTION public.verify_home_games_health_addendum() OWNER TO postgres;

--
-- Name: verify_home_games_health_core(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_home_games_health_core() RETURNS TABLE(category text, check_name text, status text, detail text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
    RETURN QUERY

    SELECT 'regulatory'::text, 'diamond_transactions CHECK no_home_games_source'::text,
           CASE WHEN EXISTS (SELECT 1 FROM pg_constraint c
                  JOIN pg_class cl ON cl.oid=c.conrelid
                  WHERE cl.relname='diamond_transactions' AND c.conname='no_home_games_source')
                THEN '✓' ELSE '✗ MISSING' END,
           'CHECK (source <> ''home_games'')'
    UNION ALL
    SELECT 'regulatory', 'zero diamond_transactions with source=home_games',
           CASE WHEN (SELECT COUNT(*) FROM diamond_transactions dt
                       WHERE dt.source='home_games')=0 THEN '✓' ELSE '✗' END,
           (SELECT COUNT(*)::text FROM diamond_transactions dt
             WHERE dt.source='home_games') || ' rows'
    UNION ALL
    SELECT 'regulatory', 'zero triggers on home tables minting value',
           CASE WHEN (SELECT COUNT(*) FROM pg_trigger t
                       JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_proc p ON p.oid=t.tgfoid
                      WHERE NOT t.tgisinternal AND c.relname LIKE 'commander_home_%'
                        AND pg_get_functiondef(p.oid) ~*
                            '(award_diamonds|add_diamonds|credit_diamonds|diamond_ledger|diamond_transactions)')=0
                THEN '✓' ELSE '✗' END,
           'trigger handlers scanned for value-minting refs'
    UNION ALL
    SELECT 'regulatory', 'zero dropped reward fns still exist',
           CASE WHEN (SELECT COUNT(*) FROM pg_proc p
                       JOIN pg_namespace n ON n.oid=p.pronamespace
                      WHERE n.nspname='public' AND p.prokind='f'
                        AND p.proname IN ('fn_grant_host_diamonds_on_complete',
                                          'fn_award_badges_on_game_complete',
                                          'award_home_games_badges',
                                          '_award_home_badge_if_new',
                                          'get_home_games_diamond_history',
                                          'get_home_games_leaderboards',
                                          'get_user_home_games_badges'))=0
                THEN '✓' ELSE '✗' END, 'Phase 36 dropped fns must stay gone'
    UNION ALL
    SELECT 'regulatory', 'XP absolute purge + DDL guard active',
           CASE WHEN EXISTS (SELECT 1 FROM pg_event_trigger
                              WHERE evtname='xp_ban_guard' AND evtenabled='O')
                AND (SELECT COUNT(*) FROM information_schema.columns
                      WHERE table_schema='public'
                        AND column_name ~* '(^xp$|_xp$|^xp_|^reputation_xp$|^total_xp$|^xp_total$|^xp_earned$|^xp_reward$|^bonus_xp_)')=0
                THEN '✓' ELSE '✗' END,
           'zero XP columns + event trigger enforcing permanent ban'

    UNION ALL
    SELECT 'privacy', 'host_private_note not readable by authenticated',
           CASE WHEN NOT has_column_privilege('authenticated',
                  'public.commander_home_members', 'host_private_note', 'SELECT')
                THEN '✓' ELSE '✗' END,
           'column-level grant gates access via SECURITY DEFINER fns only'
    UNION ALL
    SELECT 'privacy', 'host_private_note not readable by anon',
           CASE WHEN NOT has_column_privilege('anon',
                  'public.commander_home_members', 'host_private_note', 'SELECT')
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'privacy', 'fn_home_list_seats has auth guard',
           CASE WHEN EXISTS (SELECT 1 FROM pg_proc p
                  JOIN pg_namespace n ON n.oid=p.pronamespace
                  WHERE n.nspname='public' AND p.proname='fn_home_list_seats'
                    AND pg_get_functiondef(p.oid) ILIKE '%NOT_A_GROUP_MEMBER%')
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'privacy', 'fn_home_list_seats not anon-callable',
           CASE WHEN NOT has_function_privilege('anon',
                  'public.fn_home_list_seats(uuid)', 'EXECUTE')
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'privacy', 'home_members_host_sees_group policy non-recursive',
           CASE WHEN EXISTS (SELECT 1 FROM pg_policy pol
                  JOIN pg_class cl ON cl.oid=pol.polrelid
                  WHERE cl.relname='commander_home_members'
                    AND pol.polname='home_members_host_sees_group'
                    -- Any SECURITY DEFINER helper breaks the recursion: RLS is
                    -- not re-applied inside a function owned by the table's
                    -- owner. Resolve whichever one the policy actually calls
                    -- rather than pinning a single name.
                    AND EXISTS (
                      SELECT 1 FROM pg_proc hp
                        JOIN pg_namespace hn ON hn.oid = hp.pronamespace
                       WHERE hn.nspname = 'public'
                         AND hp.prosecdef
                         AND pg_get_expr(pol.polqual, pol.polrelid)
                             ILIKE '%' || hp.proname || '%'))
                THEN '✓' ELSE '✗' END,
           'policy uses SECURITY DEFINER helper to avoid self-recursion'
    UNION ALL
    SELECT 'privacy', 'GDPR content scrubber available for HG',
           CASE WHEN EXISTS (SELECT 1 FROM pg_proc p
                  JOIN pg_namespace n ON n.oid=p.pronamespace
                  WHERE n.nspname='public' AND p.proname='fn_anonymize_hg_user_content')
                THEN '✓' ELSE '✗' END,
           'fn_anonymize_hg_user_content(user_id, requested_by) scrubs HG content bodies'

    UNION ALL
    SELECT 'compliance', 'onboarding gate trigger registered on HG write tables',
           (SELECT COUNT(*)::text FROM pg_trigger tg
              JOIN pg_proc p ON p.oid=tg.tgfoid
             WHERE p.proname='fn_hg_require_onboarded_on_write'
               AND NOT tg.tgisinternal)
              || ' tables gated',
           'BEFORE INSERT gates writes to HG tables when caller not onboarded'
    UNION ALL
    SELECT 'compliance', 'resource quota trigger registered on HG write tables',
           (SELECT COUNT(*)::text FROM pg_trigger tg
              JOIN pg_proc p ON p.oid=tg.tgfoid
             WHERE p.proname='fn_hg_enforce_quotas_on_write'
               AND NOT tg.tgisinternal)
              || ' tables gated',
           'groups (20/user), invite tokens (50/group), scheduled games (100/group)'
    UNION ALL
    SELECT 'compliance', 'platform policies seeded',
           CASE WHEN (SELECT COUNT(*) FROM platform_policies pp
                       WHERE pp.key IN ('home_games.tos.version',
                                     'home_games.privacy.version',
                                     'home_games.house_rules.version',
                                     'home_games.content_policy.version',
                                     'home_games.data_retention.version'))=5
                THEN '✓' ELSE '✗' END, '5 required platform_policies keys'
    UNION ALL
    SELECT 'compliance', 'length caps present on 10 user-facing text RPCs',
           (SELECT COUNT(*)::text FROM pg_proc p
              JOIN pg_namespace n ON n.oid=p.pronamespace
             WHERE n.nspname='public'
               AND p.proname IN ('fn_home_create_post','fn_home_add_comment',
                 'fn_home_create_group','fn_home_update_group','create_home_group',
                 'fn_home_create_poll','fn_home_rsvp','fn_home_set_seat_status',
                 'fn_home_invite_member','fn_home_report_content')
               AND pg_get_functiondef(p.oid) ~*
                   '(CONTENT_TOO_LONG|MESSAGE_TOO_LONG|TOO_MANY_OPTIONS|NAME_TOO_LONG|NOTE_TOO_LONG|REASON_TOO_LONG)')
              || ' / 10',
           'CONTENT_TOO_LONG / MESSAGE_TOO_LONG / TOO_MANY_OPTIONS / etc.'
    UNION ALL
    SELECT 'compliance', 'notification preference columns complete',
           CASE WHEN (SELECT COUNT(*) FROM information_schema.columns
                       WHERE table_schema='public' AND table_name='user_notification_preferences'
                         AND column_name IN ('home_game_post_likes','home_game_post_comments',
                           'home_game_rsvp_confirmations','home_game_reminders',
                           'home_game_announcements','home_game_new_game_posted',
                           'home_game_cancellations','home_game_host_requests',
                           'home_game_review_prompts')) = 9
                THEN '✓' ELSE '✗' END,
           '9 HG-specific notification mute toggles'

    UNION ALL
    SELECT 'auth', '7 fn_home_* seat RPCs have defense-in-depth guard',
           (SELECT COUNT(*)::text || ' / 7' FROM pg_proc p
              JOIN pg_namespace n ON n.oid=p.pronamespace
             WHERE n.nspname='public'
               AND p.proname IN ('fn_home_assign_seat','fn_home_init_seats',
                                 'fn_home_move_seat','fn_home_randomize_seats',
                                 'fn_home_set_seat_status','fn_home_vacate_seat',
                                 'revive_home_group')
               -- IS DISTINCT FROM is the null-safe form and is what all seven
               -- use; `<>` yields NULL for a NULL auth.role() and silently
               -- disables the guard. Accept either, prefer neither.
               AND (pg_get_functiondef(p.oid) ILIKE '%auth.role() <> ''service_role''%'
                 OR pg_get_functiondef(p.oid) ILIKE '%auth.role() IS DISTINCT FROM ''service_role''%')
               AND pg_get_functiondef(p.oid) ILIKE '%auth.uid() IS DISTINCT FROM%'),
           CASE WHEN (SELECT COUNT(*) FROM pg_proc p
                        JOIN pg_namespace n ON n.oid=p.pronamespace
                       WHERE n.nspname='public'
                         AND p.proname IN ('fn_home_assign_seat','fn_home_init_seats',
                                           'fn_home_move_seat','fn_home_randomize_seats',
                                           'fn_home_set_seat_status','fn_home_vacate_seat',
                                           'revive_home_group')
                         AND (pg_get_functiondef(p.oid) ILIKE '%auth.role() <> ''service_role''%'
                           OR pg_get_functiondef(p.oid) ILIKE '%auth.role() IS DISTINCT FROM ''service_role''%')
                         AND pg_get_functiondef(p.oid) ILIKE '%auth.uid() IS DISTINCT FROM%') = 7
                THEN '✓' ELSE 'expected 7' END
    UNION ALL
    SELECT 'auth', 'atomic_chip_transfer has all 5 guards',
           CASE WHEN (SELECT COUNT(*) FROM pg_proc p
                       JOIN pg_namespace n ON n.oid=p.pronamespace
                      WHERE n.nspname='public' AND p.proname='atomic_chip_transfer'
                        AND pg_get_functiondef(p.oid) ILIKE '%auth.uid()%')>0
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'auth', 'admin-action audit log coverage',
           (SELECT COUNT(*)::text FROM pg_proc p
              JOIN pg_namespace n ON n.oid=p.pronamespace
             WHERE n.nspname='public'
               AND p.proname ~ '^(fn_home_|revive_home|create_home)'
               AND pg_get_functiondef(p.oid) ILIKE '%commander_audit_logs%')
              || ' / 18',
           'every privileged state change leaves an audit trail'

    UNION ALL
    SELECT 'rate_limit', 'track_home_group_view has dedupe logic',
           CASE WHEN EXISTS (SELECT 1 FROM pg_proc p
                  JOIN pg_namespace n ON n.oid=p.pronamespace
                  WHERE n.nspname='public' AND p.proname='track_home_group_view'
                    AND pg_get_functiondef(p.oid) ILIKE '%INTERVAL%')
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'rate_limit', 'track_home_group_share_click has dedupe logic',
           CASE WHEN EXISTS (SELECT 1 FROM pg_proc p
                  JOIN pg_namespace n ON n.oid=p.pronamespace
                  WHERE n.nspname='public' AND p.proname='track_home_group_share_click'
                    AND pg_get_functiondef(p.oid) ILIKE '%INTERVAL%')
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'rate_limit', 'home-view-log-prune cron scheduled',
           CASE WHEN EXISTS (SELECT 1 FROM cron.job WHERE jobname='home-view-log-prune')
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'rate_limit', '5 spam-vector RPCs use fn_try_consume_home_rate_limit',
           (SELECT COUNT(*)::text FROM pg_proc p
              JOIN pg_namespace n ON n.oid=p.pronamespace
             WHERE n.nspname='public'
               AND p.proname IN ('fn_home_create_post','fn_home_add_comment',
                 'fn_home_invite_member','fn_home_add_photo','fn_home_like_post')
               AND pg_get_functiondef(p.oid) ILIKE '%fn_try_consume_home_rate_limit%')
              || ' / 5', 'post / comment / invite / photo / like'

    UNION ALL
    SELECT 'infra', 'all home game tables have RLS enabled',
           (SELECT COUNT(*)::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
             WHERE n.nspname='public' AND c.relname LIKE 'commander_home_%'
               AND c.relkind='r' AND c.relrowsecurity)
           || ' / ' ||
           (SELECT COUNT(*)::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
             WHERE n.nspname='public' AND c.relname LIKE 'commander_home_%' AND c.relkind='r'), ''
    UNION ALL
    SELECT 'infra', 'all home game tables FORCE RLS',
           (SELECT COUNT(*)::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
             WHERE n.nspname='public' AND c.relname LIKE 'commander_home_%'
               AND c.relkind='r' AND c.relforcerowsecurity)
           || ' / ' ||
           (SELECT COUNT(*)::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
             WHERE n.nspname='public' AND c.relname LIKE 'commander_home_%' AND c.relkind='r'), ''
    UNION ALL
    SELECT 'infra', 'all home game tables have at least one RLS policy',
           CASE WHEN (SELECT COUNT(*) FROM pg_class c
                        JOIN pg_namespace n ON n.oid=c.relnamespace
                       WHERE n.nspname='public' AND c.relname LIKE 'commander_home_%'
                         AND c.relkind='r'
                         AND c.relname NOT IN ('commander_home_group_view_log',
                                               'commander_home_share_clicks',
                                               'commander_home_rate_limits')
                         AND NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid=c.oid))=0
                THEN '✓' ELSE '✗' END, 'exempts 3 deny-all server-log tables'
    UNION ALL
    SELECT 'infra', 'composite index idx_commander_home_games_group_scheduled exists',
           CASE WHEN EXISTS (SELECT 1 FROM pg_indexes
                  WHERE schemaname='public'
                    AND indexname='idx_commander_home_games_group_scheduled')
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'infra', 'all home game triggers enabled',
           (SELECT COUNT(*)::text FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid
             WHERE c.relname LIKE 'commander_home_%' AND NOT t.tgisinternal
               AND t.tgenabled='O')
           || ' / ' ||
           (SELECT COUNT(*)::text FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid
             WHERE c.relname LIKE 'commander_home_%' AND NOT t.tgisinternal)
           || ' enabled', ''
    UNION ALL
    SELECT 'infra', 'home cron jobs scheduled',
           (SELECT COUNT(*)::text FROM cron.job WHERE jobname LIKE 'home-%'), 
           'reminders, auto-complete, trending, stale sweep, recurring gen, quality, vitality, nudge, recap, snapshots, view-log prune, strike-decay'
    UNION ALL
    SELECT 'infra', 'realtime publication for HG tables',
           (SELECT COUNT(*)::text FROM pg_publication_tables
             WHERE pubname='supabase_realtime' AND tablename LIKE 'commander_home_%')
              || ' tables',
           'games, groups, members, rsvps, seats, seat reservations'

    UNION ALL
    SELECT 'integrity', 'zero orphan RSVPs',
           CASE WHEN (SELECT COUNT(*) FROM commander_home_rsvps r
                       WHERE NOT EXISTS (SELECT 1 FROM commander_home_games g
                                          WHERE g.id=r.game_id))=0
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'integrity', 'zero orphan seats',
           CASE WHEN (SELECT COUNT(*) FROM commander_home_seats s
                       WHERE NOT EXISTS (SELECT 1 FROM commander_home_games g
                                          WHERE g.id=s.game_id))=0
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'integrity', 'zero orphan posts',
           CASE WHEN (SELECT COUNT(*) FROM commander_home_posts p
                       WHERE NOT EXISTS (SELECT 1 FROM commander_home_groups g
                                          WHERE g.id=p.group_id))=0
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'integrity', 'zero expired active invite tokens',
           CASE WHEN (SELECT COUNT(*) FROM commander_home_invite_tokens t
                       WHERE t.is_active AND t.expires_at < NOW())=0
                THEN '✓' ELSE '✗' END, ''
    UNION ALL
    SELECT 'integrity', 'zero banned members w/o banned_at',
           CASE WHEN (SELECT COUNT(*) FROM commander_home_members m
                       WHERE m.status='banned' AND m.banned_at IS NULL)=0
                THEN '✓' ELSE '✗' END, ''
    ;
END;
$_$;


ALTER FUNCTION public.verify_home_games_health_core() OWNER TO postgres;

--
-- Name: FUNCTION verify_home_games_health_core(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.verify_home_games_health_core() IS 'Home games health check. Returns one row per invariant enforced in Phases 32–38. Safe to run any time (read-only). Call from CI, nightly monitoring, or before/after deploys. Any non-✓ status indicates a regression that needs investigation.';


--
-- Name: verify_home_games_invariants(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_home_games_invariants() RETURNS TABLE(invariant text, ok boolean, detail text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- 1/2. The two RLS helpers must stay SECURITY DEFINER with RLS off.
    --      SECURITY INVOKER + row_security=off is illegal without BYPASSRLS
    --      and raises 42501 for every authenticated caller.
    RETURN QUERY
    SELECT
        'helper_' || p.proname,
        (p.prosecdef AND COALESCE(p.proconfig, ARRAY[]::text[]) && ARRAY['row_security=off']),
        format('prosecdef=%s config=%s', p.prosecdef, COALESCE(p.proconfig, ARRAY[]::text[])::text)
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname IN ('fn_home_is_group_staff', 'fn_home_is_approved_member');

    -- 3. Roster SELECT must be staff-aware, not the dashboard's self-only default.
    RETURN QUERY
    SELECT
        'policy_home_members_host_sees_group',
        EXISTS (
            SELECT 1 FROM pg_policies
            WHERE schemaname='public' AND tablename='commander_home_members'
              AND cmd='SELECT' AND qual LIKE '%fn_home_is_group_staff%'
        ),
        COALESCE((
            SELECT string_agg(policyname, ', ')
            FROM pg_policies
            WHERE schemaname='public' AND tablename='commander_home_members' AND cmd='SELECT'
        ), '(no SELECT policy at all)');

    -- 4. Double-booking guard.
    RETURN QUERY
    SELECT
        'index_one_active_game_per_group_per_date',
        EXISTS (
            SELECT 1 FROM pg_indexes
            WHERE schemaname='public'
              AND indexname='uq_commander_home_games_one_active_per_group_per_date'
        ),
        'partial unique index on (group_id, scheduled_date) WHERE status <> cancelled';

    -- 5. No blanket USING(true) SELECT policies on the social/home surface.
    RETURN QUERY
    SELECT
        'no_blanket_select_policies',
        NOT EXISTS (
            SELECT 1 FROM pg_policies
            WHERE schemaname='public' AND cmd='SELECT' AND qual='true'
              AND tablename IN ('social_pages','social_page_posts','social_page_reviews',
                                'home_game_vouches','commander_post_comments',
                                'commander_venue_followers','commander_home_posts')
        ),
        COALESCE((
            SELECT string_agg(tablename || '.' || policyname, ', ')
            FROM pg_policies
            WHERE schemaname='public' AND cmd='SELECT' AND qual='true'
              AND tablename IN ('social_pages','social_page_posts','social_page_reviews',
                                'home_game_vouches','commander_post_comments',
                                'commander_venue_followers','commander_home_posts')
        ), 'none');

    -- 6. Client roles must not hold privileges RLS cannot mediate.
    --    TRUNCATE in particular is NOT filtered by row security.
    RETURN QUERY
    SELECT
        'no_rls_bypassing_grants_to_client_roles',
        NOT EXISTS (
            SELECT 1 FROM information_schema.role_table_grants
            WHERE table_schema='public'
              AND grantee IN ('anon','authenticated')
              AND privilege_type IN ('TRUNCATE','TRIGGER','REFERENCES')
              AND (table_name LIKE 'commander_home%' OR table_name LIKE 'home\_%')
        ),
        COALESCE((
            SELECT count(*)::text || ' offending grants'
            FROM information_schema.role_table_grants
            WHERE table_schema='public'
              AND grantee IN ('anon','authenticated')
              AND privilege_type IN ('TRUNCATE','TRIGGER','REFERENCES')
              AND (table_name LIKE 'commander_home%' OR table_name LIKE 'home\_%')
        ), '0');

    -- 7. Seat claiming must refuse cancelled games and waitlist self-promotion.
    RETURN QUERY
    SELECT
        'rpc_hg_claim_seat_guards',
        (SELECT p.prosrc LIKE '%GAME_NOT_ACTIVE%'
                AND p.prosrc LIKE '%WAITLISTED_CANNOT_SELF_SEAT%'
         FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
         WHERE n.nspname='public' AND p.proname='rpc_hg_claim_seat' LIMIT 1),
        'claim_seat must check parent game status and refuse to overwrite a host-set waitlist';

    -- 8. Every SECURITY DEFINER home function must pin search_path.
    --    An unpinned SECDEF function is a privilege-escalation vector.
    RETURN QUERY
    SELECT
        'secdef_home_functions_pin_search_path',
        NOT EXISTS (
            SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
            WHERE n.nspname='public' AND p.prosecdef
              AND (p.proname LIKE 'rpc_hg\_%' OR p.proname LIKE 'fn_home\_%' OR p.proname LIKE 'fn_hg\_%')
              AND NOT EXISTS (
                  SELECT 1 FROM unnest(COALESCE(p.proconfig, ARRAY[]::text[])) c
                  WHERE c LIKE 'search_path=%'
              )
        ),
        COALESCE((
            SELECT string_agg(p.proname, ', ')
            FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
            WHERE n.nspname='public' AND p.prosecdef
              AND (p.proname LIKE 'rpc_hg\_%' OR p.proname LIKE 'fn_home\_%' OR p.proname LIKE 'fn_hg\_%')
              AND NOT EXISTS (
                  SELECT 1 FROM unnest(COALESCE(p.proconfig, ARRAY[]::text[])) c
                  WHERE c LIKE 'search_path=%'
              )
        ), 'all pinned');
END;
$$;


ALTER FUNCTION public.verify_home_games_invariants() OWNER TO postgres;

--
-- Name: FUNCTION verify_home_games_invariants(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.verify_home_games_invariants() IS 'Security-posture assertions for Home Games. Returns one row per invariant; any row with ok=false is a regression. Exists because three hardening migrations were reverted out-of-band in production without detection (audit 2026-08-12). Run: SELECT * FROM verify_home_games_invariants() WHERE NOT ok;';


--
-- Name: verify_home_group_owner_consistency(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_home_group_owner_consistency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner_id uuid;
  v_owner_member_user_id uuid;
BEGIN
  SELECT owner_id INTO v_owner_id
  FROM commander_home_groups
  WHERE id = COALESCE(NEW.group_id, OLD.group_id);

  IF v_owner_id IS NULL THEN RETURN NULL; END IF;

  SELECT user_id INTO v_owner_member_user_id
  FROM commander_home_members
  WHERE group_id = COALESCE(NEW.group_id, OLD.group_id)
    AND role = 'owner';

  IF v_owner_member_user_id IS NULL THEN
    RAISE EXCEPTION 'Home group % has no owner-member row. The creator '
      'must always be seated as role=owner.',
      COALESCE(NEW.group_id, OLD.group_id)
      USING ERRCODE = '23514';
  END IF;

  IF v_owner_member_user_id <> v_owner_id THEN
    RAISE EXCEPTION 'Home group % has mismatched ownership: owner_id=% but '
      'the role=owner member row belongs to user %.',
      COALESCE(NEW.group_id, OLD.group_id), v_owner_id, v_owner_member_user_id
      USING ERRCODE = '23514';
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION public.verify_home_group_owner_consistency() OWNER TO postgres;

--
-- Name: verify_ledger_totals(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_ledger_totals() RETURNS TABLE(total_minted numeric, total_in_wallets numeric, total_locked numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean := false;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'verify_ledger_totals requires an authenticated caller';
    END IF;
    SELECT COALESCE(pr.is_admin, false) OR COALESCE(pr.role, '') IN ('admin', 'superadmin', 'staff')
      INTO v_is_admin
      FROM public.profiles pr
     WHERE pr.id = auth.uid();
    IF NOT COALESCE(v_is_admin, false) THEN
      RAISE EXCEPTION 'verify_ledger_totals is restricted to platform administrators';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    COALESCE((SELECT sum(wt.amount)
                FROM public.wallet_transactions wt
               WHERE wt.type = 'credit' AND wt.category = 'mint'), 0)::numeric,
    COALESCE((SELECT sum(w.balance)        FROM public.wallets w), 0)::numeric,
    COALESCE((SELECT sum(w.locked_balance) FROM public.wallets w), 0)::numeric;
END;
$$;


ALTER FUNCTION public.verify_ledger_totals() OWNER TO postgres;

--
-- Name: FUNCTION verify_ledger_totals(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.verify_ledger_totals() IS 'Platform-wide chip ledger totals for ChipFlowService.verifyLedger(). SECURITY DEFINER so it sees every wallet row - the previous client-side fallback was RLS-trimmed and therefore wrong. Admins and service_role only.';


--
-- Name: video_library_remove_dead(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.video_library_remove_dead(dead_video_ids text[]) RETURNS TABLE(deleted_id text, deleted_title text)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    DELETE FROM video_library_videos
    WHERE youtube_video_id = ANY(dead_video_ids)
    RETURNING youtube_video_id, title;
END;
$$;


ALTER FUNCTION public.video_library_remove_dead(dead_video_ids text[]) OWNER TO postgres;

--
-- Name: vote_home_group_poll(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.vote_home_group_poll(p_poll_id uuid, p_caller_user_id uuid, p_option_ids text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_poll RECORD; v_group RECORD;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;
    IF array_length(p_option_ids, 1) IS NULL OR array_length(p_option_ids, 1) = 0 THEN
        RAISE EXCEPTION 'NO_OPTIONS_SELECTED';
    END IF;
    IF array_length(p_option_ids, 1) > 50 THEN
        RAISE EXCEPTION 'TOO_MANY_OPTIONS' USING HINT = 'max 50 options per vote';
    END IF;

    SELECT * INTO v_poll FROM commander_home_polls WHERE id = p_poll_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'POLL_NOT_FOUND'; END IF;
    IF v_poll.is_closed OR (v_poll.closes_at IS NOT NULL AND v_poll.closes_at < NOW()) THEN
        RAISE EXCEPTION 'POLL_CLOSED';
    END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_poll.group_id;

    IF v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members
                        WHERE group_id = v_poll.group_id AND user_id = p_caller_user_id
                          AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_A_MEMBER'; END IF;

    IF v_poll.poll_type = 'single_choice' AND array_length(p_option_ids, 1) > 1 THEN
        RAISE EXCEPTION 'SINGLE_CHOICE_ONE_ALLOWED';
    END IF;

    INSERT INTO commander_home_poll_votes (poll_id, user_id, option_ids)
    VALUES (p_poll_id, p_caller_user_id, p_option_ids)
    ON CONFLICT (poll_id, user_id) DO UPDATE
        SET option_ids = EXCLUDED.option_ids, updated_at = NOW();

    RETURN jsonb_build_object('success', true, 'poll_id', p_poll_id);
END;
$$;


ALTER FUNCTION public.vote_home_group_poll(p_poll_id uuid, p_caller_user_id uuid, p_option_ids text[]) OWNER TO postgres;

--
-- Name: wallet_internal_transfer(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.wallet_internal_transfer(p_from_user_id uuid, p_to_user_id uuid, p_amount numeric, p_description text DEFAULT 'Internal transfer'::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_balance DECIMAL;
BEGIN
    SELECT balance INTO v_balance FROM wallets WHERE user_id = p_from_user_id AND wallet_type = 'PLAYER';
    IF v_balance IS NULL OR v_balance < p_amount THEN RAISE EXCEPTION 'Insufficient balance for transfer'; END IF;
    UPDATE wallets SET balance = balance - p_amount, updated_at = NOW() WHERE user_id = p_from_user_id AND wallet_type = 'PLAYER';
    UPDATE wallets SET balance = balance + p_amount, updated_at = NOW() WHERE user_id = p_to_user_id AND wallet_type = 'PLAYER';
    IF NOT FOUND THEN INSERT INTO wallets (user_id, wallet_type, balance, locked_balance, created_at, updated_at) VALUES (p_to_user_id, 'PLAYER', p_amount, 0, NOW(), NOW()); END IF;
    INSERT INTO wallet_transactions (user_id, wallet_type, amount, type, category, description, created_at) VALUES (p_from_user_id, 'PLAYER', p_amount, 'debit', 'transfer', p_description, NOW());
    INSERT INTO wallet_transactions (user_id, wallet_type, amount, type, category, description, created_at) VALUES (p_to_user_id, 'PLAYER', p_amount, 'credit', 'transfer', p_description, NOW());
END;
$$;


ALTER FUNCTION public.wallet_internal_transfer(p_from_user_id uuid, p_to_user_id uuid, p_amount numeric, p_description text) OWNER TO postgres;

