)
WITH (autovacuum_enabled='true', autovacuum_vacuum_scale_factor='0.0', autovacuum_vacuum_threshold='2000', autovacuum_analyze_scale_factor='0.0', autovacuum_analyze_threshold='2000', autovacuum_vacuum_insert_threshold='10000', autovacuum_vacuum_insert_scale_factor='0.0', autovacuum_vacuum_cost_delay='2', autovacuum_vacuum_cost_limit='2000');


ALTER TABLE public.hand_history OWNER TO postgres;

--
-- Name: COLUMN hand_history.hole_cards; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hand_history.hole_cards IS 'Showdown-revealed holdings only, keyed by user id: {"<uuid>": [{"rank","suit"}]}. Cards that were MUCKED are deliberately never stored -- everything in here was already shown face-up to the whole table, so a hand participant reading this column learns nothing they did not already see.';


--
-- Name: COLUMN hand_history.button_seat; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hand_history.button_seat IS 'Dealer/button seat for this hand (1-9). Lets analysis derive each seat''s position (UTG/MP/CO/BTN/SB/BB) from players[].seat. Populated by the engine from currentHandDealerSeat at settlement. NULL for hands written before 2026-08-16.';


--
-- Name: COLUMN hand_history.has_human; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hand_history.has_human IS 'True if at least one seat in this hand belonged to a person rather than a horse. NULL means not classified yet — sp_prune_hand_history fills it lazily once the row is older than the horse retention window, so this costs nothing on the write path. Anything not positively identifiable as a horse counts as human, so the flag can only over-keep. Added 2026-08-20.';


--
-- Name: COLUMN hand_history.pots; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hand_history.pots IS 'Pot-level settlement for this hand: [{index, amount, eligible[]}] in pot order (0 = main). Written by ServerTableEngineSettlement from the engine''s own calculatePots() snapshot. NULL on rows written before 2026-08-25. Read by attributeKnockout() to credit a knockout to the winner(s) of the pot that held the busted player''s last chips (Dan section 29).';


--
-- Name: COLUMN hand_history.showdown; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hand_history.showdown IS 'Showdown reveal record: [{user_id, seat, reveal_order, mucked, hand_name?, hand_description?}]. Mucked entries carry no hand identity. NULL = no showdown or predates 2026-08-25.';


--
-- Name: COLUMN hand_history.rit_boards; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hand_history.rit_boards IS 'Run It Twice boards 2..N in run order (JSONB array of arrays of engine card strings, e.g. [["Ahearts","Kdiamonds",...],[...]]). NULL on single-run hands. Board 1 remains community_cards. Added 2026-08-26; boards 2..N also exist as rit_board_N: pseudo-actions in `actions` for rows that predate this column.';


--
-- Name: COLUMN hand_history.winners_by_board; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hand_history.winners_by_board IS 'Multi-board hands only (run it twice/three times, double/triple-board bomb pots): [{board, userId, amount, handName}] - who won each board, with what, for what pre-rake share. NULL on single-board hands. The paid totals are in winners.';


--
-- Name: bomb_pot_award_gaps; Type: VIEW; Schema: ops; Owner: postgres
--

CREATE VIEW ops.bomb_pot_award_gaps AS
 SELECT id AS hand_history_id,
    table_id,
    hand_number,
    created_at,
    jsonb_array_length(COALESCE(winners, '[]'::jsonb)) AS winner_count,
    pot_size,
    rake_amount,
    bbj_amount
   FROM public.hand_history h
  WHERE ((bomb_pot IS NOT NULL) AND (jsonb_array_length(COALESCE(winners, '[]'::jsonb)) > 1) AND (COALESCE(pot_size, (0)::numeric) > (0)::numeric) AND (NOT (EXISTS ( SELECT 1
           FROM public.bomb_pot_award_units a
          WHERE (a.hand_history_id = h.id)))));


ALTER VIEW ops.bomb_pot_award_gaps OWNER TO postgres;

--
-- Name: VIEW bomb_pot_award_gaps; Type: COMMENT; Schema: ops; Owner: postgres
--

COMMENT ON VIEW ops.bomb_pot_award_gaps IS 'Multi-winner bomb pot hands missing award units. Expected to be empty: the live settlement path writes units 0.15-2.8s after the hand. Non-empty means the live path missed one - run fn_backfill_bomb_multi_winner_units(500,false).';


--
-- Name: incident_triage; Type: VIEW; Schema: ops; Owner: postgres
--

CREATE VIEW ops.incident_triage AS
 WITH canon AS (
         SELECT ca_drift_incidents.classification,
            ca_drift_incidents.severity,
            regexp_replace(regexp_replace(regexp_replace(regexp_replace(ca_drift_incidents.dedupe_key, '^(reconcile|lrl|qr|fa|ca|drift):'::text, ''::text), ':?\d{4}-\d{2}-\d{2}$'::text, ''::text), '_pool(:|$)'::text, '\1'::text), '(:global|:-|:)$'::text, ''::text) AS canon_key,
            round(COALESCE(ca_drift_incidents.discrepancy_amount, (0)::numeric)) AS amount,
            ca_drift_incidents.occurrences,
            ca_drift_incidents.past_target,
            ca_drift_incidents.detected_at,
            ca_drift_incidents.last_seen_at,
            ca_drift_incidents.id,
            ca_drift_incidents.source,
            ca_drift_incidents.suspected_cause
           FROM public.ca_drift_incidents
          WHERE (ca_drift_incidents.status = 'open'::text)
        )
 SELECT classification,
    severity,
    canon_key,
    amount,
    count(*) AS duplicate_incident_rows,
    sum(occurrences) AS total_occurrences,
    bool_or(past_target) AS past_deadline,
    min(detected_at) AS first_seen,
    max(last_seen_at) AS last_seen,
    count(DISTINCT source) AS detectors_reporting,
    (array_agg(suspected_cause ORDER BY last_seen_at DESC) FILTER (WHERE (suspected_cause IS NOT NULL)))[1] AS cause,
    array_agg(id ORDER BY detected_at) AS incident_ids
   FROM canon
  GROUP BY classification, severity, canon_key, amount;


ALTER VIEW ops.incident_triage OWNER TO postgres;

--
-- Name: incident_worklist; Type: VIEW; Schema: ops; Owner: postgres
--

CREATE VIEW ops.incident_worklist AS
 SELECT row_number() OVER (ORDER BY (severity = 'critical'::text) DESC, (abs(amount)) DESC, total_occurrences DESC) AS rank,
    classification,
    severity,
    canon_key,
    amount,
    duplicate_incident_rows,
    total_occurrences,
    past_deadline,
    (first_seen)::date AS since,
    last_seen,
    cause
   FROM ops.incident_triage
  WHERE (severity = ANY (ARRAY['critical'::text, 'warning'::text]))
  ORDER BY (row_number() OVER (ORDER BY (severity = 'critical'::text) DESC, (abs(amount)) DESC, total_occurrences DESC));


ALTER VIEW ops.incident_worklist OWNER TO postgres;

