--

CREATE TABLE public.agent_commissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    club_id uuid NOT NULL,
    user_id uuid NOT NULL,
    amount numeric DEFAULT 0,
    commission_rate numeric DEFAULT 0.1,
    source_type text DEFAULT 'rake'::text,
    source_id uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    settled_at timestamp with time zone,
    CONSTRAINT chk_amount_is_two_decimal_places CHECK (((amount IS NULL) OR (amount = round(amount, 2))))
)
WITH (autovacuum_enabled='true', autovacuum_analyze_scale_factor='0.0', autovacuum_analyze_threshold='1000', autovacuum_vacuum_scale_factor='0.0', autovacuum_vacuum_threshold='1000', autovacuum_vacuum_cost_delay='2', autovacuum_vacuum_cost_limit='2000');


ALTER TABLE public.agent_commissions OWNER TO postgres;

--
-- Name: COLUMN agent_commissions.settled_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.agent_commissions.settled_at IS 'Set by fn_settle_round2_club_to_agents when this commission has been paid out to the agent. NULL means still owed. Makes Round 2 idempotent.';


--
-- Name: agent_commissions_unsettled; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.agent_commissions_unsettled WITH (security_invoker='true') AS
 SELECT id,
    club_id,
    user_id,
    amount,
    commission_rate,
    source_type,
    source_id,
    notes,
    created_at,
    settled_at
   FROM public.agent_commissions ac
  WHERE ((settled_at IS NULL) AND (NOT (EXISTS ( SELECT 1
           FROM public.agent_commission_settlements s
          WHERE ((s.club_id = ac.club_id) AND (s.user_id = ac.user_id) AND (ac.created_at >= s.period_start) AND (ac.created_at < s.period_end))))));


ALTER VIEW public.agent_commissions_unsettled OWNER TO postgres;

