--
-- Name: signup_health_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.signup_health_view WITH (security_invoker='false') AS
 WITH real_users AS (
         SELECT users.created_at
           FROM auth.users
          WHERE (((users.email)::text !~~ 'probe-%@probe.smarter.poker'::text) AND ((users.email)::text !~~ 'probe-%@probe.smarter.local'::text))
        )
 SELECT ( SELECT count(*) AS count
           FROM real_users
          WHERE (real_users.created_at > (now() - '00:15:00'::interval))) AS new_users_15m,
    ( SELECT count(*) AS count
           FROM real_users
          WHERE (real_users.created_at > (now() - '01:00:00'::interval))) AS new_users_1h,
    ( SELECT count(*) AS count
           FROM real_users
          WHERE (real_users.created_at > (now() - '24:00:00'::interval))) AS new_users_24h,
    ( SELECT max(real_users.created_at) AS max
           FROM real_users) AS last_signup_at,
    ( SELECT count(*) AS count
           FROM public.probe_heartbeats
          WHERE (probe_heartbeats.occurred_at > (now() - '00:15:00'::interval))) AS probe_runs_15m,
    ( SELECT count(*) AS count
           FROM public.probe_heartbeats
          WHERE (probe_heartbeats.occurred_at > (now() - '01:00:00'::interval))) AS probe_runs_1h,
    ( SELECT count(*) AS count
           FROM public.probe_heartbeats
          WHERE ((probe_heartbeats.occurred_at > (now() - '00:15:00'::interval)) AND (probe_heartbeats.status = 'ok'::text))) AS probe_ok_15m,
    ( SELECT count(*) AS count
           FROM public.probe_heartbeats
          WHERE ((probe_heartbeats.occurred_at > (now() - '01:00:00'::interval)) AND (probe_heartbeats.status = 'failed'::text))) AS probe_failed_1h,
    ( SELECT max(probe_heartbeats.occurred_at) AS max
           FROM public.probe_heartbeats) AS last_probe_at,
    ( SELECT count(*) AS count
           FROM public.signup_errors
          WHERE (signup_errors.occurred_at > (now() - '01:00:00'::interval))) AS errors_1h,
    ( SELECT count(*) AS count
           FROM public.signup_errors
          WHERE (signup_errors.occurred_at > (now() - '24:00:00'::interval))) AS errors_24h,
    ( SELECT max(signup_errors.occurred_at) AS max
           FROM public.signup_errors) AS last_error_at;


ALTER VIEW public.signup_health_view OWNER TO postgres;

--
-- Name: auth_health_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.auth_health_view WITH (security_invoker='true') AS
 WITH probe_counts AS (
         SELECT probe_heartbeats.probe_name,
            count(*) FILTER (WHERE (probe_heartbeats.occurred_at > (now() - '00:15:00'::interval))) AS runs_15m,
            count(*) FILTER (WHERE (probe_heartbeats.occurred_at > (now() - '01:00:00'::interval))) AS runs_1h,
            count(*) FILTER (WHERE (probe_heartbeats.occurred_at > (now() - '24:00:00'::interval))) AS runs_24h,
            count(*) FILTER (WHERE ((probe_heartbeats.occurred_at > (now() - '00:15:00'::interval)) AND (probe_heartbeats.status = 'ok'::text))) AS ok_15m,
            count(*) FILTER (WHERE ((probe_heartbeats.occurred_at > (now() - '01:00:00'::interval)) AND (probe_heartbeats.status = 'failed'::text))) AS failed_1h,
            max(probe_heartbeats.occurred_at) AS last_run_at
           FROM public.probe_heartbeats
          GROUP BY probe_heartbeats.probe_name
        )
 SELECT COALESCE(( SELECT probe_counts.runs_15m
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'signup-probe'::text)), (0)::bigint) AS signup_runs_15m,
    COALESCE(( SELECT probe_counts.ok_15m
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'signup-probe'::text)), (0)::bigint) AS signup_ok_15m,
    COALESCE(( SELECT probe_counts.failed_1h
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'signup-probe'::text)), (0)::bigint) AS signup_failed_1h,
    ( SELECT probe_counts.last_run_at
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'signup-probe'::text)) AS signup_last_run,
    COALESCE(( SELECT probe_counts.runs_15m
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'login-probe'::text)), (0)::bigint) AS login_runs_15m,
    COALESCE(( SELECT probe_counts.ok_15m
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'login-probe'::text)), (0)::bigint) AS login_ok_15m,
    COALESCE(( SELECT probe_counts.failed_1h
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'login-probe'::text)), (0)::bigint) AS login_failed_1h,
    ( SELECT probe_counts.last_run_at
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'login-probe'::text)) AS login_last_run,
    COALESCE(( SELECT probe_counts.runs_15m
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'recovery-probe'::text)), (0)::bigint) AS recovery_runs_15m,
    COALESCE(( SELECT probe_counts.ok_15m
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'recovery-probe'::text)), (0)::bigint) AS recovery_ok_15m,
    COALESCE(( SELECT probe_counts.failed_1h
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'recovery-probe'::text)), (0)::bigint) AS recovery_failed_1h,
    ( SELECT probe_counts.last_run_at
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'recovery-probe'::text)) AS recovery_last_run,
    COALESCE(( SELECT probe_counts.runs_24h
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'auth-integrity-audit'::text)), (0)::bigint) AS integrity_runs_24h,
    COALESCE(( SELECT probe_counts.failed_1h
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'auth-integrity-audit'::text)), (0)::bigint) AS integrity_failed_1h,
    ( SELECT probe_counts.last_run_at
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'auth-integrity-audit'::text)) AS integrity_last_run,
    COALESCE(( SELECT probe_counts.runs_24h
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'email-deliverability'::text)), (0)::bigint) AS email_runs_24h,
    COALESCE(( SELECT probe_counts.failed_1h
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'email-deliverability'::text)), (0)::bigint) AS email_failed_1h,
    ( SELECT probe_counts.last_run_at
           FROM probe_counts
          WHERE (probe_counts.probe_name = 'email-deliverability'::text)) AS email_last_run,
    ( SELECT signup_health_view.new_users_24h
           FROM public.signup_health_view) AS real_signups_24h,
    ( SELECT signup_health_view.new_users_1h
           FROM public.signup_health_view) AS real_signups_1h,
    ( SELECT signup_health_view.errors_1h
           FROM public.signup_health_view) AS trigger_errors_1h,
    now() AS computed_at;


ALTER VIEW public.auth_health_view OWNER TO postgres;

--
-- Name: autofix_attempts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.autofix_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    repo text NOT NULL,
    sentry_issue_id text,
    sentry_project_slug text,
    short_id text,
    fingerprint text,
    title text,
    level text,
    status text DEFAULT 'queued'::text NOT NULL,
    run_id text,
    fix_branch text,
    fix_pr_url text,
    fix_pr_number integer,
    changed_files text[],
    claude_confidence text,
    claude_tokens_in integer,
    claude_tokens_out integer,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    next_retry_at timestamp with time zone,
    source text,
    deployment_id text,
    commit_sha text,
    strategy text,
    confidence text,
    branch_name text,
    pr_number integer,
    pr_opened_at timestamp with time zone,
    reviewed_at timestamp with time zone,
    merged_at timestamp with time zone,
    reverted_at timestamp with time zone,
    build_verified_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT autofix_attempts_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'pr_opened'::text, 'merged'::text, 'rejected'::text, 'errored'::text, 'skipped_unfixable'::text])))
);


ALTER TABLE public.autofix_attempts OWNER TO postgres;

--
-- Name: TABLE autofix_attempts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.autofix_attempts IS 'Phase 5.2.0 — Sentry→Claude autofix loop audit + dedup';


--
-- Name: COLUMN autofix_attempts.status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.autofix_attempts.status IS 'queued|running|pr_opened|merged|rejected|errored';


--
-- Name: COLUMN autofix_attempts.retry_count; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.autofix_attempts.retry_count IS 'Number of previous rejected/errored attempts for this Sentry issue. Poller uses this to cap retries and set next_retry_at.';


--
-- Name: COLUMN autofix_attempts.next_retry_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.autofix_attempts.next_retry_at IS 'If status in (rejected,errored), earliest wall-clock time the poller is allowed to re-dispatch. NULL = never retry.';


--
-- Name: COLUMN autofix_attempts.source; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.autofix_attempts.source IS 'Origin of the failure: ''sentry'' (runtime error) or ''vercel'' (build failure).';


--
-- Name: COLUMN autofix_attempts.pr_opened_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.autofix_attempts.pr_opened_at IS 'When the draft PR was opened by open-pr.mjs.';


--
-- Name: COLUMN autofix_attempts.merged_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.autofix_attempts.merged_at IS 'When a human (or future automation) merged the PR.';


--
-- Name: COLUMN autofix_attempts.reverted_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.autofix_attempts.reverted_at IS 'When the merge was reverted because the next deploy also failed (Phase B).';


--
-- Name: COLUMN autofix_attempts.build_verified_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.autofix_attempts.build_verified_at IS 'When the post-merge deploy succeeded (Phase B closes the loop here).';


--
-- Name: COLUMN autofix_attempts.metadata; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.autofix_attempts.metadata IS 'Schema-free breadcrumb blob: { snippet, dryRun, postMergeSha, verifyStartedAt, revertPrUrl, ... } written by poll.mjs + phase-b-verify.mjs.';


--
-- Name: autofix_attempts_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.autofix_attempts_summary WITH (security_invoker='true') AS
 SELECT date_trunc('hour'::text, created_at) AS hour,
    sentry_project_slug AS project,
    status,
    count(*) AS attempts,
    sum(claude_tokens_in) AS tokens_in,
    sum(claude_tokens_out) AS tokens_out
   FROM public.autofix_attempts
  GROUP BY (date_trunc('hour'::text, created_at)), sentry_project_slug, status
  ORDER BY (date_trunc('hour'::text, created_at)) DESC, sentry_project_slug, status;


ALTER VIEW public.autofix_attempts_summary OWNER TO postgres;

--
-- Name: VIEW autofix_attempts_summary; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.autofix_attempts_summary IS 'Hourly autofix attempt rollup. Recreated 2026-04-22 as SECURITY INVOKER — RLS on autofix_attempts is now fully enforced for all callers.';


