    CONSTRAINT ca_bbj_policy_pivot_threshold_check CHECK ((pivot_threshold > (0)::numeric)),
    CONSTRAINT ca_bbj_policy_standard_backup_check CHECK (((standard_backup >= (0)::numeric) AND (standard_backup <= (1)::numeric))),
    CONSTRAINT ca_bbj_policy_standard_main_check CHECK (((standard_main >= (0)::numeric) AND (standard_main <= (1)::numeric)))
);


