    last_scanned_hands integer,
    last_findings integer,
    last_budget_hit boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    unscanned_from timestamp with time zone,
    unscanned_to timestamp with time zone,
    unscanned_note text,
    CONSTRAINT ca_collusion_scan_state_singleton CHECK (id)
);


ALTER TABLE public.ca_collusion_scan_state OWNER TO postgres;

--
-- Name: TABLE ca_collusion_scan_state; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_collusion_scan_state IS 'Where the collusion detector got to. The scan reads from last_window_end forward, so its cost is proportional to the platform''s hand RATE rather than to a fixed rolling window re-read every 30 minutes. last_success_at is the liveness signal an integrity console renders.';


--
-- Name: COLUMN ca_collusion_scan_state.unscanned_from; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ca_collusion_scan_state.unscanned_from IS 'Start of a window no scan ever examined. While this is set, health refuses to report stale:false - a hole in the record is not health. Clear it only when the window has actually been rescanned (?since=&until=), never to tidy the dashboard.';


