    detail jsonb DEFAULT '{}'::jsonb NOT NULL
);


ALTER TABLE public.ca_collusion_signals OWNER TO postgres;

--
-- Name: TABLE ca_collusion_signals; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_collusion_signals IS 'Zero-drift phase 4: v1 collusion signals. A row means the pair''s chip flow over the window was large, frequent, and one-directional - a signal for human review, never an automatic action.';


