    from_type text NOT NULL,
    from_entity_id uuid,
    from_label text,
    to_type text NOT NULL,
    to_entity_id uuid,
    to_label text,
    amount numeric(15,2) NOT NULL,
    category text DEFAULT 'transfer'::text NOT NULL,
    description text,
    notes text,
    club_id uuid,
    union_id uuid,
    table_id uuid,
    hand_id uuid,
    tournament_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    idempotency_key text,
    correlation_id uuid,
    causation_id uuid,
    settlement_id text,
    epoch_id integer,
    actor_service text,
    db_role text,
    pre_from_balance numeric,
    post_from_balance numeric,
    pre_to_balance numeric,
    post_to_balance numeric,
    status text DEFAULT 'posted'::text NOT NULL,
    metadata jsonb,
    chain_seq bigint,
    prev_hash text,
    row_hash text,
    CONSTRAINT chip_ledger_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT chip_ledger_no_diamond_category_check CHECK (((category !~* '^diamond'::text) AND (category !~* '_diamond'::text))),
    CONSTRAINT chip_ledger_positive_amount CHECK ((amount > (0)::numeric)),
    CONSTRAINT chip_ledger_status_check CHECK ((status = ANY (ARRAY['posted'::text, 'correction'::text, 'reversal'::text]))),
    CONSTRAINT chk_post_from_balance_is_two_decimal_places CHECK (((post_from_balance IS NULL) OR (post_from_balance = round(post_from_balance, 2)))),
    CONSTRAINT chk_post_to_balance_is_two_decimal_places CHECK (((post_to_balance IS NULL) OR (post_to_balance = round(post_to_balance, 2)))),
    CONSTRAINT chk_pre_from_balance_is_two_decimal_places CHECK (((pre_from_balance IS NULL) OR (pre_from_balance = round(pre_from_balance, 2)))),
    CONSTRAINT chk_pre_to_balance_is_two_decimal_places CHECK (((pre_to_balance IS NULL) OR (pre_to_balance = round(pre_to_balance, 2))))
)
WITH (autovacuum_enabled='true', autovacuum_analyze_scale_factor='0.0', autovacuum_analyze_threshold='1000', autovacuum_vacuum_scale_factor='0.0', autovacuum_vacuum_threshold='1000', autovacuum_vacuum_cost_delay='2', autovacuum_vacuum_cost_limit='2000');


ALTER TABLE public.chip_ledger OWNER TO postgres;

--
-- Name: ca_direct_balance_writes; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ca_direct_balance_writes WITH (security_invoker='true') AS
 SELECT created_at AS at,
    'club_members'::text AS table_name,
        CASE
            WHEN (to_type = 'player_wallet'::text) THEN to_entity_id
            ELSE from_entity_id
        END AS user_id,
        CASE
            WHEN (to_type = 'player_wallet'::text) THEN amount
            ELSE (- amount)
        END AS delta,
    actor_service AS application_name,
    db_role,
    club_id,
    tournament_id,
    id AS ledger_id,
    description
   FROM public.chip_ledger l
  WHERE ((category = 'adjustment'::text) AND (description ~~ 'auto-audited club_members.chip_balance delta%'::text) AND (description !~~ '%rejected)'::text));


ALTER VIEW public.ca_direct_balance_writes OWNER TO postgres;

--
-- Name: VIEW ca_direct_balance_writes; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.ca_direct_balance_writes IS 'R10 log-only: every club_members.chip_balance write that reached fn_club_members_ledger_writer with no app.ledger_category declared (journaled as adjustment). application_name and db_role come from fn_ca_chip_ledger_enrich. Not observable here: app.money_path, session_user. Refuses nothing. Lane E, 2026-09-02.';


