--

CREATE TABLE public.ca_hand_facts (
    hand_id uuid NOT NULL,
    user_id uuid NOT NULL,
    club_id uuid,
    table_id uuid,
    tournament_id uuid,
    played_at timestamp with time zone NOT NULL,
    game_variant text NOT NULL,
    big_blind numeric NOT NULL,
    seat smallint,
    "position" text NOT NULL,
    players_dealt smallint NOT NULL,
    hole_cards jsonb,
    hand_class text,
    invested numeric NOT NULL,
    returned numeric NOT NULL,
    net numeric NOT NULL,
    net_bb numeric NOT NULL,
    rake_paid numeric DEFAULT 0 NOT NULL,
    vpip boolean DEFAULT false NOT NULL,
    pfr boolean DEFAULT false NOT NULL,
    three_bet boolean DEFAULT false NOT NULL,
    faced_three_bet boolean DEFAULT false NOT NULL,
    folded_to_three_bet boolean DEFAULT false NOT NULL,
    had_cbet_flop_opp boolean DEFAULT false NOT NULL,
    cbet_flop boolean DEFAULT false NOT NULL,
    saw_flop boolean DEFAULT false NOT NULL,
    went_to_showdown boolean DEFAULT false NOT NULL,
    won_at_showdown boolean DEFAULT false NOT NULL,
    aggressive_actions smallint DEFAULT 0 NOT NULL,
    passive_actions smallint DEFAULT 0 NOT NULL,
    was_all_in boolean DEFAULT false NOT NULL,
    all_in_street text,
    all_in_at_risk numeric,
    all_in_equity numeric,
    ev_returned numeric,
    ev_net numeric NOT NULL,
    ev_net_bb numeric NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    opponent_ids uuid[],
    four_bet boolean DEFAULT false NOT NULL,
    CONSTRAINT ca_hand_facts_equity_range CHECK (((all_in_equity IS NULL) OR ((all_in_equity >= (0)::numeric) AND (all_in_equity <= (1)::numeric))))
);


ALTER TABLE public.ca_hand_facts OWNER TO postgres;

--
-- Name: TABLE ca_hand_facts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_hand_facts IS 'Private per-user Club Arena hand facts. hole_cards are protected by owner-only RLS; writes are service-role only.';


--
-- Name: COLUMN ca_hand_facts.invested; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ca_hand_facts.invested IS 'Exact chips committed, INCLUDING blinds/antes/straddles, net of returned uncalled bet. From engine currentHandContributions, not reconstructed from actions JSON.';


--
-- Name: COLUMN ca_hand_facts.rake_paid; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ca_hand_facts.rake_paid IS 'Contribution-weighted share of the hand rake, matching how atomic_distribute_rake apportions it. Hardcoded 0 before 2026-08-21 - rows written earlier understate rake.';


--
-- Name: COLUMN ca_hand_facts.faced_three_bet; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ca_hand_facts.faced_three_bet IS 'Player OPENED (first voluntary raise) and was then 3-bet. Deliberately excludes facing a 4-bet after 3-betting, and excludes cold-callers facing a squeeze, to match the standard tracker definition.';


--
-- Name: COLUMN ca_hand_facts.was_all_in; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ca_hand_facts.was_all_in IS 'True when the player was all-in, INCLUDING getting there by calling. The action log records a stack-consuming call as action=call, so this also derives from presence in the all-in equity runout.';


--
-- Name: COLUMN ca_hand_facts.ev_net; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ca_hand_facts.ev_net IS 'All-in-adjusted net. Equals net on hands with no all-in. Basis of the EV vs actual luck graph.';


--
-- Name: COLUMN ca_hand_facts.opponent_ids; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ca_hand_facts.opponent_ids IS 'Every other user dealt into this hand. Enables an honest hands-played-together count for Nemesis, which transfers alone cannot give.';


--
-- Name: COLUMN ca_hand_facts.four_bet; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ca_hand_facts.four_bet IS 'Player made the third voluntary preflop raise (the 4-bet). Blinds are not in the action log, so the open is raise index 0, the 3-bet index 1 and the 4-bet index 2.';


