CREATE TABLE public.ca_horse_fleet_policy (
    scope text NOT NULL,
    scope_id uuid,
    scope_key uuid GENERATED ALWAYS AS (COALESCE(scope_id, '00000000-0000-0000-0000-000000000000'::uuid)) STORED NOT NULL,
    enabled boolean DEFAULT true,
    pause_new_seatings boolean DEFAULT false,
    max_horses integer,
    max_per_table integer,
    occupancy_bias numeric DEFAULT 1.0,
