    CONSTRAINT ca_horse_fleet_policy_bias_sane CHECK (((occupancy_bias IS NULL) OR ((occupancy_bias > (0)::numeric) AND (occupancy_bias <= (10)::numeric)))),
    CONSTRAINT ca_horse_fleet_policy_caps_not_negative CHECK (((COALESCE(max_horses, 0) >= 0) AND (COALESCE(max_per_table, 0) >= 0))),
    CONSTRAINT ca_horse_fleet_policy_global_is_unscoped CHECK (((scope = 'global'::text) = (scope_id IS NULL))),
    CONSTRAINT ca_horse_fleet_policy_min_humans_sane CHECK (((min_humans_to_seat IS NULL) OR ((min_humans_to_seat >= 0) AND (min_humans_to_seat <= 10)))),
    CONSTRAINT ca_horse_fleet_policy_scope_known CHECK ((scope = ANY (ARRAY['global'::text, 'club'::text, 'union'::text])))
);


ALTER TABLE public.ca_horse_fleet_policy OWNER TO postgres;

