);


ALTER TABLE public.ca_incident_recipients OWNER TO postgres;

--
-- Name: ca_integrity_case_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_integrity_case_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    case_id uuid NOT NULL,
    item_type text NOT NULL,
    item_ref text,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    snapshot_hash text NOT NULL,
    added_by uuid NOT NULL,
    added_at timestamp with time zone DEFAULT now() NOT NULL,
    op_id text NOT NULL,
    payload_hash text NOT NULL,
    retracts_item_id uuid,
    retraction_reason text,
    CONSTRAINT ca_integrity_case_items_detail_bounded CHECK ((octet_length((detail)::text) <= 524288)),
    CONSTRAINT ca_integrity_case_items_op_bounded CHECK (((length(btrim(op_id)) >= 8) AND (length(btrim(op_id)) <= 200))),
    CONSTRAINT ca_integrity_case_items_ref_shape CHECK ((((item_type = ANY (ARRAY['note'::text, 'pair_snapshot'::text, 'assignment'::text, 'decision'::text, 'closure'::text, 'sanction'::text])) AND (item_ref IS NULL)) OR ((item_type = ANY (ARRAY['collusion_row'::text, 'collusion_signal'::text, 'flag'::text, 'hand'::text, 'restriction'::text, 'observation'::text])) AND (item_ref IS NOT NULL)) OR ((item_type = 'retraction'::text) AND (item_ref IS NOT NULL)))),
    CONSTRAINT ca_integrity_case_items_retraction_shape CHECK ((((item_type = 'retraction'::text) AND (retracts_item_id IS NOT NULL) AND (retraction_reason IS NOT NULL) AND ((length(retraction_reason) >= 1) AND (length(retraction_reason) <= 2000))) OR ((item_type <> 'retraction'::text) AND (retracts_item_id IS NULL) AND (retraction_reason IS NULL)))),
    CONSTRAINT ca_integrity_case_items_type_known CHECK ((item_type = ANY (ARRAY['collusion_row'::text, 'collusion_signal'::text, 'flag'::text, 'hand'::text, 'restriction'::text, 'note'::text, 'observation'::text, 'pair_snapshot'::text, 'retraction'::text, 'assignment'::text, 'decision'::text, 'closure'::text, 'sanction'::text])))
);


ALTER TABLE public.ca_integrity_case_items OWNER TO postgres;

--
-- Name: TABLE ca_integrity_case_items; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_integrity_case_items IS 'Immutable case evidence and case-history events. A correction is a new retraction row; UPDATE and DELETE are rejected.';


--
-- Name: ca_integrity_cases; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_integrity_cases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subject_ids uuid[] NOT NULL,
    kind text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    severity text DEFAULT 'medium'::text NOT NULL,
    opened_by uuid NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    assigned_to uuid,
    decision text,
    decision_note text,
    decided_by uuid,
    decided_at timestamp with time zone,
    closed_by uuid,
    closed_at timestamp with time zone,
    close_note text,
    open_op_id text NOT NULL,
    open_payload_hash text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ca_integrity_cases_close_complete CHECK ((((status <> 'closed'::text) AND (closed_by IS NULL) AND (closed_at IS NULL) AND (close_note IS NULL)) OR ((status = 'closed'::text) AND (closed_by IS NOT NULL) AND (closed_at IS NOT NULL) AND (close_note IS NOT NULL)))),
    CONSTRAINT ca_integrity_cases_close_note_bounded CHECK (((close_note IS NULL) OR ((length(close_note) >= 1) AND (length(close_note) <= 4000)))),
    CONSTRAINT ca_integrity_cases_decision_complete CHECK ((((decision IS NULL) AND (decision_note IS NULL) AND (decided_by IS NULL) AND (decided_at IS NULL)) OR ((decision IS NOT NULL) AND (decision_note IS NOT NULL) AND (decided_by IS NOT NULL) AND (decided_at IS NOT NULL)))),
    CONSTRAINT ca_integrity_cases_decision_known CHECK (((decision IS NULL) OR (decision = ANY (ARRAY['no_action'::text, 'warned'::text, 'restricted'::text, 'confiscated'::text])))),
    CONSTRAINT ca_integrity_cases_decision_note_bounded CHECK (((decision_note IS NULL) OR ((length(decision_note) >= 1) AND (length(decision_note) <= 4000)))),
    CONSTRAINT ca_integrity_cases_kind_known CHECK ((kind = ANY (ARRAY['collusion'::text, 'chip_dumping'::text, 'multi_accounting'::text, 'bot_or_rta'::text, 'abuse'::text, 'other'::text]))),
    CONSTRAINT ca_integrity_cases_open_op_bounded CHECK (((length(btrim(open_op_id)) >= 8) AND (length(btrim(open_op_id)) <= 200))),
    CONSTRAINT ca_integrity_cases_severity_known CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text]))),
    CONSTRAINT ca_integrity_cases_status_known CHECK ((status = ANY (ARRAY['open'::text, 'investigating'::text, 'decided'::text, 'closed'::text]))),
    CONSTRAINT ca_integrity_cases_status_matches_decision CHECK ((((status = ANY (ARRAY['open'::text, 'investigating'::text])) AND (decision IS NULL)) OR ((status = ANY (ARRAY['decided'::text, 'closed'::text])) AND (decision IS NOT NULL)))),
    CONSTRAINT ca_integrity_cases_subjects_bounded CHECK (((cardinality(subject_ids) >= 1) AND (cardinality(subject_ids) <= 32) AND (subject_ids = public.fn_ca_integrity_normalize_subjects(subject_ids)))),
    CONSTRAINT ca_integrity_cases_version_positive CHECK ((version > 0))
);


ALTER TABLE public.ca_integrity_cases OWNER TO postgres;

--
-- Name: TABLE ca_integrity_cases; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_integrity_cases IS 'Stable Admin Phase 5 cases. A detector never opens or decides one. subject_ids includes horses and humans under the same rules.';


--
-- Name: ca_integrity_sanctions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_integrity_sanctions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    case_id uuid NOT NULL,
    subject_id uuid NOT NULL,
    kind text NOT NULL,
    state text NOT NULL,
    amount numeric(20,2),
    asset text,
    restriction_id uuid,
    approval_id uuid,
    money_operation_id text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    payload_hash text NOT NULL,
    proposed_by uuid NOT NULL,
    proposed_at timestamp with time zone DEFAULT now() NOT NULL,
    applied_by uuid,
    applied_at timestamp with time zone,
    reversed_by uuid,
    reversed_at timestamp with time zone,
    reversal_reason text,
    note text,
    op_id text NOT NULL,
    CONSTRAINT ca_integrity_sanctions_applied_shape CHECK ((((state = ANY (ARRAY['applied'::text, 'reversed'::text])) AND (applied_by IS NOT NULL) AND (applied_at IS NOT NULL)) OR ((state <> ALL (ARRAY['applied'::text, 'reversed'::text])) AND (applied_by IS NULL) AND (applied_at IS NULL)))),
    CONSTRAINT ca_integrity_sanctions_approval_shape CHECK (((kind <> 'confiscation'::text) OR (approval_id IS NOT NULL))),
    CONSTRAINT ca_integrity_sanctions_kind_known CHECK ((kind = ANY (ARRAY['warning'::text, 'restriction'::text, 'confiscation'::text]))),
    CONSTRAINT ca_integrity_sanctions_money_shape CHECK ((((kind = 'confiscation'::text) AND (amount IS NOT NULL) AND (amount > (0)::numeric) AND (asset IS NOT NULL)) OR ((kind <> 'confiscation'::text) AND (amount IS NULL) AND (asset IS NULL)))),
    CONSTRAINT ca_integrity_sanctions_note_bounded CHECK (((note IS NULL) OR ((length(note) >= 1) AND (length(note) <= 4000)))),
    CONSTRAINT ca_integrity_sanctions_op_bounded CHECK (((length(btrim(op_id)) >= 8) AND (length(btrim(op_id)) <= 200))),
    CONSTRAINT ca_integrity_sanctions_restriction_shape CHECK ((((kind = 'restriction'::text) AND (restriction_id IS NOT NULL)) OR ((kind <> 'restriction'::text) AND (restriction_id IS NULL)))),
    CONSTRAINT ca_integrity_sanctions_reversal_shape CHECK ((((state = 'reversed'::text) AND (reversed_by IS NOT NULL) AND (reversed_at IS NOT NULL) AND (reversal_reason IS NOT NULL)) OR ((state <> 'reversed'::text) AND (reversed_by IS NULL) AND (reversed_at IS NULL) AND (reversal_reason IS NULL)))),
    CONSTRAINT ca_integrity_sanctions_state_known CHECK ((state = ANY (ARRAY['proposed'::text, 'pending_approval'::text, 'approved'::text, 'applied'::text, 'reversed'::text, 'failed'::text])))
);


