    CONSTRAINT ca_rake_rules_bbj_min_pot_bb_check CHECK ((bbj_min_pot_bb >= 0)),
    CONSTRAINT ca_rake_rules_heads_up_cap_factor_check CHECK (((heads_up_cap_factor >= (0)::numeric) AND (heads_up_cap_factor <= (1)::numeric))),
    CONSTRAINT ca_rake_rules_heads_up_percent_check CHECK ((heads_up_percent >= (0)::numeric)),
    CONSTRAINT ca_rake_rules_id_check CHECK ((id = 1)),
    CONSTRAINT ca_rake_rules_max_rake_cap_bb_check CHECK ((max_rake_cap_bb >= (0)::numeric)),
    CONSTRAINT ca_rake_rules_max_rake_percent_check CHECK ((max_rake_percent >= (0)::numeric)),
    CONSTRAINT ca_rake_rules_short_handed_cap_factor_check CHECK (((short_handed_cap_factor >= (0)::numeric) AND (short_handed_cap_factor <= (1)::numeric))),
    CONSTRAINT ca_rake_rules_short_handed_max_players_check CHECK ((short_handed_max_players >= 3))
);


ALTER TABLE public.ca_rake_rules OWNER TO postgres;

--
-- Name: TABLE ca_rake_rules; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_rake_rules IS 'One row. Every rake/BBJ rule constant the engine compiles in (server/src/config/rakeSpec.ts). Part of fn_rake_spec_checksum(); change it and the engine holds cash tables until it is redeployed to match.';


--
-- Name: ca_rake_schedule; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_rake_schedule (
    sb numeric NOT NULL,
    bb numeric NOT NULL,
    rake_percent numeric NOT NULL,
    rake_cap numeric NOT NULL,
    bbj_fee_bb numeric NOT NULL,
    source text DEFAULT 'engine_mirror'::text NOT NULL,
    CONSTRAINT ca_rake_schedule_bb_exceeds_sb CHECK ((bb > sb)),
    CONSTRAINT ca_rake_schedule_source_check CHECK ((source = ANY (ARRAY['engine_mirror'::text, 'proposed'::text])))
);


ALTER TABLE public.ca_rake_schedule OWNER TO postgres;

--
-- Name: TABLE ca_rake_schedule; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_rake_schedule IS 'Mirror of RAKE_SCHEDULE in src/config/RakeConfig.ts. rake_cap is an absolute amount. Read only by the rake-law alarm; the engine uses its own copy.';


--
-- Name: COLUMN ca_rake_schedule.source; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ca_rake_schedule.source IS 'engine_mirror: this row exists in RAKE_SCHEDULE in src/config/RakeConfig.ts and is what the engine charges. proposed: a stake somebody thinks SHOULD be scheduled; never used to resolve a cap, only reported by fn_rake_schedule_drift().';


--
-- Name: CONSTRAINT ca_rake_schedule_bb_exceeds_sb ON ca_rake_schedule; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON CONSTRAINT ca_rake_schedule_bb_exceeds_sb ON public.ca_rake_schedule IS 'Cash tables require big blind > small blind (fn_tables_creation_guard). A schedule row that breaks it can never price a hand, so it is a typo by definition. Added 2026-09-01 with the deletion of the 5/5 row.';


--
-- Name: ca_rake_schedule_caps; Type: TABLE; Schema: public; Owner: postgres
