    source text DEFAULT 'schedule'::text NOT NULL,
    CONSTRAINT ca_rake_schedule_caps_bb_check CHECK ((bb > (0)::numeric)),
    CONSTRAINT ca_rake_schedule_caps_players_dealt_check CHECK ((players_dealt = ANY (ARRAY[2, 3, 4]))),
    CONSTRAINT ca_rake_schedule_caps_rake_cap_check CHECK ((rake_cap >= (0)::numeric)),
    CONSTRAINT ca_rake_schedule_caps_source_check CHECK ((source = ANY (ARRAY['schedule'::text, 'tier_fallback'::text])))
);


ALTER TABLE public.ca_rake_schedule_caps OWNER TO postgres;

--
-- Name: TABLE ca_rake_schedule_caps; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_rake_schedule_caps IS 'Rake cap by big blind and players dealt: the engine''s playerCountCaps materialised for every stake it deals. Rebuilt by fn_rake_spec_rebuild_caps(); part of fn_rake_spec_checksum().';


