-- Name: club_agents; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.club_agents WITH (security_invoker='true') AS
 SELECT id,
    user_id,
    club_id,
    membership_id,
    role,
    status,
    parent_agent_id,
    commission_rate,
    player_rakeback_rate,
    credit_limit,
    credit_used,
    is_prepaid,
    COALESCE(agent_wallet_balance, business_balance, (0)::numeric) AS agent_wallet_balance,
    COALESCE(player_wallet_balance, player_balance, (0)::numeric) AS player_wallet_balance,
    COALESCE(promo_wallet_balance, promo_balance, (0)::numeric) AS promo_wallet_balance,
    COALESCE(agent_wallet_balance, business_balance, (0)::numeric) AS business_balance,
    COALESCE(player_wallet_balance, player_balance, (0)::numeric) AS player_balance,
    COALESCE(promo_wallet_balance, promo_balance, (0)::numeric) AS promo_balance,
    total_players,
    active_player_count,
    sub_agent_count,
    COALESCE(weekly_rake_generated, (0)::numeric) AS weekly_rake_generated,
    COALESCE(lifetime_rake_generated, (0)::numeric) AS lifetime_rake_generated,
    created_at,
    updated_at
   FROM public.agents;


