    stock integer,
    stackable boolean DEFAULT false NOT NULL,
    per_user_limit integer,
    sale_price integer,
    available_from timestamp with time zone,
    available_until timestamp with time zone,
    sort_order integer DEFAULT 0 NOT NULL,
    CONSTRAINT club_shop_items_grant_spec_valid CHECK (((grant_spec IS NULL) OR ((jsonb_typeof(grant_spec) = 'object'::text) AND ((grant_spec ->> 'type'::text) = ANY (ARRAY['time_bank'::text, 'throwable'::text, 'emote_pack'::text, 'table_skin'::text, 'avatar'::text, 'none'::text])) AND (((grant_spec -> 'qty'::text) IS NULL) OR ((jsonb_typeof((grant_spec -> 'qty'::text)) = 'number'::text) AND (((grant_spec ->> 'qty'::text))::numeric > (0)::numeric) AND (((grant_spec ->> 'qty'::text))::numeric <= (1000)::numeric) AND (((grant_spec ->> 'qty'::text))::numeric = floor(((grant_spec ->> 'qty'::text))::numeric))))))),
    CONSTRAINT club_shop_items_per_user_limit_pos CHECK (((per_user_limit IS NULL) OR (per_user_limit > 0))),
    CONSTRAINT club_shop_items_sale_price_valid CHECK (((sale_price IS NULL) OR ((sale_price >= 0) AND (sale_price <= price)))),
    CONSTRAINT club_shop_items_stock_nonneg CHECK (((stock IS NULL) OR (stock >= 0))),
    CONSTRAINT club_shop_items_window_valid CHECK (((available_from IS NULL) OR (available_until IS NULL) OR (available_until > available_from)))
);


