--

CREATE TABLE public.commander_home_members (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    group_id uuid NOT NULL,
    user_id uuid,
    role text DEFAULT 'member'::text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    games_attended integer DEFAULT 0,
    games_hosted integer DEFAULT 0,
    last_attended timestamp with time zone,
    can_host boolean DEFAULT false,
    notifications_enabled boolean DEFAULT true,
    notify_announcements boolean DEFAULT true,
    notify_new_games boolean DEFAULT true,
    notify_game_reminders boolean DEFAULT true,
    notify_rsvp_updates boolean DEFAULT true,
    invited_by uuid,
    joined_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    pending_nudge_sent_at timestamp with time zone,
    last_read_posts_at timestamp with time zone,
    is_regular boolean DEFAULT false,
    flake_strikes integer DEFAULT 0 NOT NULL,
    host_private_note text,
    probation_until timestamp with time zone,
    display_name text,
    phone text,
    added_by_user_id uuid,
    is_roster_only boolean DEFAULT false NOT NULL,
    last_strike_at timestamp with time zone,
    banned_at timestamp with time zone,
    banned_by uuid,
    ban_reason text,
    CONSTRAINT chk_home_members_flake_strikes CHECK (((flake_strikes IS NULL) OR (flake_strikes >= 0))),
    CONSTRAINT chk_member_phone_len CHECK (((phone IS NULL) OR (length(phone) <= 50))),
    CONSTRAINT chk_member_private_note_len CHECK (((host_private_note IS NULL) OR (length(host_private_note) <= 2000))),
    CONSTRAINT commander_home_members_games_hosted_nonneg CHECK (((games_hosted IS NULL) OR (games_hosted >= 0))),
    CONSTRAINT commander_home_members_identity_check CHECK (((user_id IS NOT NULL) OR ((is_roster_only = true) AND (display_name IS NOT NULL) AND ((char_length(TRIM(BOTH FROM display_name)) >= 1) AND (char_length(TRIM(BOTH FROM display_name)) <= 120))))),
    CONSTRAINT commander_home_members_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'admin'::text, 'member'::text]))),
    CONSTRAINT commander_home_members_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'declined'::text, 'banned'::text])))
);

ALTER TABLE ONLY public.commander_home_members FORCE ROW LEVEL SECURITY;


ALTER TABLE public.commander_home_members OWNER TO postgres;

--
-- Name: TABLE commander_home_members; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.commander_home_members IS 'Home group roster. SELECT is governed by home_members_host_sees_group (self OR group staff), matching the INSERT/UPDATE/DELETE policies. Do NOT replace this with the Supabase dashboard default "Enable users to view their own data only" - doing so makes hosts unable to read a roster they can still write to. See migration phase50b.';


--
-- Name: COLUMN commander_home_members.group_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commander_home_members.group_id IS 'Phase 40: NOT NULL. A member row must belong to a group. FK to commander_home_groups ON DELETE CASCADE.';


--
-- Name: COLUMN commander_home_members.user_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commander_home_members.user_id IS 'Phase 40: NOT NULL. A member row must belong to a real profile. FK to profiles ON DELETE CASCADE.';


--
-- Name: COLUMN commander_home_members.is_regular; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commander_home_members.is_regular IS 'Phase 24: host-flagged "regular" status. Used for host dashboard sorting.';


--
-- Name: COLUMN commander_home_members.flake_strikes; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commander_home_members.flake_strikes IS 'Phase 24: auto-incremented each time the member flakes. Host may auto-ban after N strikes.';


--
-- Name: COLUMN commander_home_members.host_private_note; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commander_home_members.host_private_note IS 'Owner/admin-only notes about members. Table-level SELECT revoked from anon/authenticated (Phase 37); re-granted for every column except this one. Access only via SECURITY DEFINER fns like get_home_group_member_engagement which gate on owner/admin role.';


--
-- Name: COLUMN commander_home_members.display_name; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commander_home_members.display_name IS 'Name shown for this member. Required when is_roster_only = true.';


--
-- Name: COLUMN commander_home_members.added_by_user_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commander_home_members.added_by_user_id IS 'Host/member who added this roster-only entry.';


--
-- Name: COLUMN commander_home_members.is_roster_only; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commander_home_members.is_roster_only IS 'Phase 41: true when this row represents a non-Smarter.Poker person the host has added by name (user_id stays NULL, display_name required).';


