    CONSTRAINT commander_tournament_entries_payment_method_chk CHECK (((payment_method IS NULL) OR (payment_method = ANY (ARRAY['cash'::text, 'card'::text, 'credit'::text, 'comp'::text, 'chips'::text, 'transfer'::text, 'marker'::text, 'other'::text])))),
    CONSTRAINT commander_tournament_entries_payout_amount_nonneg CHECK (((payout_amount IS NULL) OR (payout_amount >= (0)::numeric))),
