    CONSTRAINT diamond_packages_diamonds_check CHECK ((diamonds > 0)),
    CONSTRAINT diamond_packages_key_format_chk CHECK (((length(package_key) >= 1) AND (length(package_key) <= 64) AND (package_key ~ '^[A-Za-z0-9][A-Za-z0-9_-]*$'::text))),
    CONSTRAINT diamond_packages_price_usd_check CHECK ((price_usd > (0)::numeric)),
    CONSTRAINT diamond_packages_stripe_price_chk CHECK (((price_usd >= 0.50) AND (price_usd <= 999999.99) AND (price_usd = trunc(price_usd, 2))))
);


ALTER TABLE public.diamond_packages OWNER TO postgres;

--
-- Name: TABLE diamond_packages; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.diamond_packages IS 'DR8 / D16. The diamond store price oracle. Seeded from VALID_DIAMOND_PACKAGES in Smarter-Poker-World-Hub pages/api/store/create-checkout-session.js. The checkout route reads this table and falls back to the constant if it is unreachable; settle_diamond_card_purchase_atomic compares the purchase row to it and files a DR8 warning incident on a mismatch. It never refuses a settle.';


