    completed_at timestamp with time zone,
    refunded_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    refunded_amount_cents integer DEFAULT 0 NOT NULL,
    refunded_diamonds integer DEFAULT 0 NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT diamond_purchases_refund_progress_nonnegative CHECK (((refunded_amount_cents >= 0) AND (refunded_diamonds >= 0))),
    CONSTRAINT diamond_purchases_status_known CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text, 'refunded'::text, 'failed'::text, 'expired'::text])))
);


