    program_hash text NOT NULL,
    funding_owner_type text NOT NULL,
    funding_union_id uuid,
    total_paid numeric(18,2) NOT NULL,
    seed_funded numeric(18,2) NOT NULL,
    promo_funded numeric(18,2) NOT NULL,
    overlay_funded numeric(18,2) NOT NULL,
    winner_count integer NOT NULL,
    settled_at timestamp with time zone DEFAULT now() NOT NULL,
    tie_policy text DEFAULT 'split_occupied_places'::text NOT NULL,
    CONSTRAINT leaderboard_payout_batches_check CHECK ((total_paid = ((seed_funded + promo_funded) + overlay_funded))),
    CONSTRAINT leaderboard_payout_batches_check1 CHECK ((((funding_owner_type = 'club'::text) AND (funding_union_id IS NULL)) OR ((funding_owner_type = 'union'::text) AND (funding_union_id IS NOT NULL)))),
    CONSTRAINT leaderboard_payout_batches_funding_owner_type_check CHECK ((funding_owner_type = ANY (ARRAY['club'::text, 'union'::text]))),
    CONSTRAINT leaderboard_payout_batches_overlay_funded_check CHECK ((overlay_funded >= (0)::numeric)),
    CONSTRAINT leaderboard_payout_batches_period_check CHECK ((period = ANY (ARRAY['weekly'::text, 'monthly'::text]))),
    CONSTRAINT leaderboard_payout_batches_promo_funded_check CHECK ((promo_funded >= (0)::numeric)),
    CONSTRAINT leaderboard_payout_batches_promo_only_check CHECK (((overlay_funded = (0)::numeric) AND (total_paid = (seed_funded + promo_funded)))),
    CONSTRAINT leaderboard_payout_batches_seed_funded_check CHECK ((seed_funded >= (0)::numeric)),
    CONSTRAINT leaderboard_payout_batches_tie_policy_check CHECK ((tie_policy = 'split_occupied_places'::text)),
    CONSTRAINT leaderboard_payout_batches_total_paid_check CHECK ((total_paid >= (0)::numeric)),
    CONSTRAINT leaderboard_payout_batches_winner_count_check CHECK ((winner_count >= 0))
);


