-- Name: leaderboard_reward_program_versions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.leaderboard_reward_program_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    club_id uuid NOT NULL,
    version integer NOT NULL,
    operation_id uuid NOT NULL,
    status text DEFAULT 'published'::text NOT NULL,
    rewards_enabled boolean NOT NULL,
    payout_currency text DEFAULT 'chips'::text NOT NULL,
    payout_metric text NOT NULL,
    weekly_prizes jsonb DEFAULT '[]'::jsonb NOT NULL,
    monthly_prizes jsonb DEFAULT '[]'::jsonb NOT NULL,
    suggestion_key text NOT NULL,
    funding_owner_type text NOT NULL,
    funding_union_id uuid,
    weekly_effective_from date NOT NULL,
    monthly_effective_from date NOT NULL,
    published_at timestamp with time zone DEFAULT now() NOT NULL,
    published_by uuid,
    supersedes_program_id uuid,
    program_hash text NOT NULL,
    CONSTRAINT leaderboard_reward_program_enabled_prizes CHECK (((NOT rewards_enabled) OR (jsonb_array_length(weekly_prizes) > 0) OR (jsonb_array_length(monthly_prizes) > 0))),
    CONSTRAINT leaderboard_reward_program_funding_scope CHECK ((((funding_owner_type = 'union'::text) AND (funding_union_id IS NOT NULL)) OR ((funding_owner_type = 'club'::text) AND (funding_union_id IS NULL)))),
    CONSTRAINT leaderboard_reward_program_versions_funding_owner_type_check CHECK ((funding_owner_type = ANY (ARRAY['union'::text, 'club'::text]))),
    CONSTRAINT leaderboard_reward_program_versions_monthly_prizes_check CHECK (public.fn_leaderboard_prizes_are_valid(monthly_prizes)),
    CONSTRAINT leaderboard_reward_program_versions_payout_currency_check CHECK ((payout_currency = 'chips'::text)),
    CONSTRAINT leaderboard_reward_program_versions_payout_metric_check CHECK ((payout_metric = ANY (ARRAY['profit'::text, 'hands_played'::text, 'tournaments_won'::text, 'roi'::text]))),
    CONSTRAINT leaderboard_reward_program_versions_program_hash_check CHECK ((program_hash ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT leaderboard_reward_program_versions_status_check CHECK ((status = 'published'::text)),
    CONSTRAINT leaderboard_reward_program_versions_suggestion_key_check CHECK ((suggestion_key = ANY (ARRAY['balanced'::text, 'top_heavy'::text, 'even'::text, 'custom'::text]))),
    CONSTRAINT leaderboard_reward_program_versions_version_check CHECK ((version > 0)),
