    correct boolean NOT NULL,
    timed_out boolean DEFAULT false NOT NULL,
    explanation text,
    solver_source text NOT NULL,
    classification text NOT NULL,
    answered_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT leak_drill_answers_text_bound CHECK (((length(question_id) >= 1) AND (length(question_id) <= 180) AND (length(COALESCE(selected_answer, ''::text)) <= 100) AND ((length(correct_answer) >= 1) AND (length(correct_answer) <= 100)) AND (length(COALESCE(explanation, ''::text)) <= 2000)))
);


