--
-- Name: leak_drill_attempts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.leak_drill_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    batch_id uuid NOT NULL,
    user_id uuid NOT NULL,
    leak_id text NOT NULL,
    review_id text NOT NULL,
    source_table text DEFAULT 'user_leaks'::text NOT NULL,
    attempt_number integer NOT NULL,
    total_questions smallint NOT NULL,
    correct_answers smallint NOT NULL,
    accuracy numeric(5,4) NOT NULL,
    passed boolean NOT NULL,
    first_attempt boolean NOT NULL,
    remediation_mastered boolean NOT NULL,
    server_verified boolean DEFAULT true NOT NULL,
    evidence jsonb DEFAULT '[]'::jsonb NOT NULL,
    completed_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT leak_drill_attempts_accuracy_check CHECK (((accuracy >= (0)::numeric) AND (accuracy <= (1)::numeric))),
    CONSTRAINT leak_drill_attempts_attempt_number_check CHECK (((attempt_number >= 1) AND (attempt_number <= 100000))),
    CONSTRAINT leak_drill_attempts_check CHECK (((correct_answers >= 0) AND (correct_answers <= total_questions))),
    CONSTRAINT leak_drill_attempts_evidence_bound CHECK (((jsonb_typeof(evidence) = 'array'::text) AND (jsonb_array_length(evidence) = total_questions) AND (octet_length((evidence)::text) <= 65536))),
    CONSTRAINT leak_drill_attempts_source_table_check CHECK ((source_table = 'user_leaks'::text)),
    CONSTRAINT leak_drill_attempts_total_questions_check CHECK (((total_questions >= 5) AND (total_questions <= 20)))
);


ALTER TABLE public.leak_drill_attempts OWNER TO postgres;

