--
-- Name: live_stream_analytics; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.live_stream_analytics WITH (security_invoker='true') AS
 SELECT id,
    broadcaster_id,
    title,
    category,
    started_at,
    ended_at,
    peak_viewers,
    viewer_count,
    COALESCE(( SELECT (count(*))::integer AS count
           FROM public.live_reactions lr
          WHERE (lr.stream_id = ls.id)), 0) AS reaction_count,
    (EXTRACT(epoch FROM (ended_at - started_at)))::integer AS duration_seconds,
    ( SELECT count(*) AS count
           FROM public.live_comments lc
          WHERE (lc.stream_id = ls.id)) AS comment_count,
    ( SELECT COALESCE(sum(lg.amount), (0)::bigint) AS "coalesce"
           FROM public.live_gifts lg
          WHERE (lg.stream_id = ls.id)) AS total_gifts_received
   FROM public.live_streams ls;


ALTER VIEW public.live_stream_analytics OWNER TO postgres;

