--
-- Name: managed_game_command_receipts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.managed_game_command_receipts (
    command_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    game_kind text NOT NULL,
    game_id uuid NOT NULL,
    command_action text NOT NULL,
    expected_version integer NOT NULL,
    request_hash text NOT NULL,
    status text NOT NULL,
    result jsonb DEFAULT '{}'::jsonb NOT NULL,
    contract_version_before integer,
    contract_version_after integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT managed_game_command_receipt_evidence_consistent CHECK ((((status = 'processing'::text) AND (result = '{}'::jsonb) AND (contract_version_after IS NULL)) OR ((status = ANY (ARRAY['succeeded'::text, 'rejected'::text])) AND (contract_version_before > 0) AND (contract_version_after > 0) AND (result @> jsonb_build_object('ok', (status = 'succeeded'::text), 'command_id', command_id, 'command_status', status, 'expected_version', expected_version, 'current_version', contract_version_after, 'version_before', contract_version_before, 'version_after', contract_version_after))))),
    CONSTRAINT managed_game_command_receipts_check CHECK ((((status = 'processing'::text) AND (completed_at IS NULL)) OR ((status = ANY (ARRAY['succeeded'::text, 'rejected'::text])) AND (completed_at IS NOT NULL)))),
    CONSTRAINT managed_game_command_receipts_command_action_check CHECK ((command_action = ANY (ARRAY['update'::text, 'close'::text]))),
    CONSTRAINT managed_game_command_receipts_expected_version_check CHECK ((expected_version > 0)),
    CONSTRAINT managed_game_command_receipts_game_kind_check CHECK ((game_kind = ANY (ARRAY['table'::text, 'tournament'::text]))),
    CONSTRAINT managed_game_command_receipts_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT managed_game_command_receipts_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'succeeded'::text, 'rejected'::text])))
);


ALTER TABLE public.managed_game_command_receipts OWNER TO postgres;

--
-- Name: TABLE managed_game_command_receipts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.managed_game_command_receipts IS 'One immutable operator receipt per client command UUID. The receipt and its table or tournament mutation commit atomically.';


