    CONSTRAINT managed_game_schedules_command_action_check CHECK ((command_action = 'close'::text)),
    CONSTRAINT managed_game_schedules_expected_version_check CHECK ((expected_version > 0)),
    CONSTRAINT managed_game_schedules_game_kind_check CHECK ((game_kind = ANY (ARRAY['table'::text, 'tournament'::text]))),
    CONSTRAINT managed_game_schedules_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'executing'::text, 'succeeded'::text, 'rejected'::text, 'cancelled'::text])))
);


