    CONSTRAINT newsletter_campaigns_failed_count_check CHECK ((failed_count >= 0)),
    CONSTRAINT newsletter_campaigns_lookback_days_check CHECK (((lookback_days >= 1) AND (lookback_days <= 30))),
    CONSTRAINT newsletter_campaigns_recipient_count_check CHECK ((recipient_count >= 0)),
    CONSTRAINT newsletter_campaigns_sent_count_check CHECK ((sent_count >= 0)),
