ALTER TABLE public.pending_fee_distributions OWNER TO postgres;

--
-- Name: TABLE pending_fee_distributions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.pending_fee_distributions IS 'A5: fees already removed from a pot whose banking RPC exhausted its retries. Drained by the FeeReconciler. Re-driving is safe because atomic_distribute_rake is hand-gated and idempotent.';


--
-- Name: CONSTRAINT pending_fee_distributions_kind_chk ON pending_fee_distributions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON CONSTRAINT pending_fee_distributions_kind_chk ON public.pending_fee_distributions IS 'rake / bbj_contribution: a fee that left a pot and could not be banked. bbj_payout (2026-09-05): a jackpot the engine detected and could not pay; its parameters are in contributions and FeeReconciler re-drives bbj_atomic_payout_v2, which is idempotent.';


