--
-- Name: pipeline_stats; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pipeline_stats WITH (security_invoker='true') AS
 SELECT date(started_at) AS run_date,
    count(*) AS runs,
    sum(text_posts_created) AS total_posts,
    sum(videos_created) AS total_videos,
    sum(errors) AS total_errors,
    avg(duration_seconds) AS avg_duration_seconds
   FROM public.pipeline_runs
  WHERE (completed_at IS NOT NULL)
  GROUP BY (date(started_at))
  ORDER BY (date(started_at)) DESC
 LIMIT 30;


ALTER VIEW public.pipeline_stats OWNER TO postgres;

