--
-- Name: sandbox_coach_accuracy; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.sandbox_coach_accuracy WITH (security_invoker='true') AS
 SELECT user_id,
    count(*) AS total_hands,
    sum(
        CASE
            WHEN is_correct THEN 1
            ELSE 0
        END) AS correct_count,
    sum(
        CASE
            WHEN (NOT is_correct) THEN 1
            ELSE 0
        END) AS incorrect_count,
    round((((sum(
        CASE
            WHEN is_correct THEN 1
            ELSE 0
        END))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 2) AS accuracy_pct,
    round(avg(
        CASE
            WHEN (NOT is_correct) THEN ev_delta
            ELSE (0)::numeric
        END), 2) AS avg_leak_ev
   FROM public.sandbox_coach_results
  GROUP BY user_id;


ALTER VIEW public.sandbox_coach_accuracy OWNER TO postgres;

