--
-- Name: scraper_metrics; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.scraper_metrics (
    id bigint NOT NULL,
    source text NOT NULL,
    cycle_start timestamp with time zone NOT NULL,
    duration_seconds integer,
    venues_scraped integer,
    venues_with_data integer,
    errors integer DEFAULT 0,
    records_saved integer,
    created_at timestamp with time zone DEFAULT now(),
    run_status text DEFAULT 'legacy'::text NOT NULL,
    records_attempted integer,
    records_rejected integer DEFAULT 0 NOT NULL,
    status_reason text,
    CONSTRAINT scraper_metrics_record_counts_check CHECK ((((run_status = 'legacy'::text) AND (records_attempted IS NULL) AND (COALESCE(records_saved, 0) >= 0) AND (records_rejected = 0) AND (COALESCE(errors, 0) >= 0)) OR ((run_status <> 'legacy'::text) AND (records_attempted IS NOT NULL) AND (records_saved IS NOT NULL) AND (errors IS NOT NULL) AND (NULLIF(btrim(status_reason), ''::text) IS NOT NULL) AND (records_attempted >= 0) AND (records_saved >= 0) AND (records_rejected >= 0) AND (errors >= 0) AND (records_attempted = (records_saved + records_rejected)) AND (((run_status = 'success'::text) AND (records_attempted > 0) AND (records_saved = records_attempted) AND (records_rejected = 0) AND (errors = 0)) OR ((run_status = ANY (ARRAY['valid_empty'::text, 'progress'::text, 'maintenance'::text])) AND (records_attempted = 0) AND (records_saved = 0) AND (records_rejected = 0) AND (errors = 0)) OR ((run_status = 'partial'::text) AND (records_saved > 0) AND ((records_rejected > 0) OR (errors > 0))) OR ((run_status = 'failed'::text) AND (records_saved = 0) AND (errors > 0)))))),
    CONSTRAINT scraper_metrics_run_status_check CHECK ((run_status = ANY (ARRAY['success'::text, 'valid_empty'::text, 'progress'::text, 'maintenance'::text, 'partial'::text, 'failed'::text, 'legacy'::text])))
);


ALTER TABLE public.scraper_metrics OWNER TO postgres;

--
-- Name: COLUMN scraper_metrics.run_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.scraper_metrics.run_status IS 'success requires persisted rows; valid_empty is a completed empty sweep; progress/maintenance are healthy zero-write checkpoints; partial/failed are unhealthy.';


--
-- Name: COLUMN scraper_metrics.records_attempted; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.scraper_metrics.records_attempted IS 'Rows submitted or otherwise requiring persistence in this run; NULL only on pre-migration legacy metrics.';


--
-- Name: COLUMN scraper_metrics.records_rejected; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.scraper_metrics.records_rejected IS 'Attempted rows not confirmed persisted. A positive value prevents a success classification.';


