--

COMMENT ON COLUMN public.solved_spots_gold.solver_binary_checksum IS 'SHA-256 of the exact approved PioSOLVER executable bytes.';


--
-- Name: COLUMN solved_spots_gold.machine_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.solved_spots_gold.machine_id IS 'Canonical supervised solver host identifier, currently M1 or M2.';


--
-- Name: COLUMN solved_spots_gold.pipeline_commit; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.solved_spots_gold.pipeline_commit IS 'Exact protected repository commit from which the worker code was fetched.';


--
-- Name: COLUMN solved_spots_gold.manifest_checksum; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.solved_spots_gold.manifest_checksum IS 'SHA-256 of the exact manifest bytes used to assign the solve.';


--
-- Name: COLUMN solved_spots_gold.source_artifact_checksum; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.solved_spots_gold.source_artifact_checksum IS 'SHA-256 of the canonical JSON strategy_matrix_v2 payload.';


--
-- Name: COLUMN solved_spots_gold.quality_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.solved_spots_gold.quality_status IS 'Validated v2, explicitly legacy-sanitized, or quarantined; null means unaudited legacy.';


