--
-- Name: stable_hand_horse_state; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.stable_hand_horse_state (
    horse_id uuid NOT NULL,
    rest_weekday smallint NOT NULL,
    daily_cap_minutes integer NOT NULL,
    active_club_id uuid,
    active_host_id uuid,
    active_seat_count smallint DEFAULT 0 NOT NULL,
    active_table_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    minutes_played_today integer DEFAULT 0 NOT NULL,
    session_plan jsonb DEFAULT '{}'::jsonb NOT NULL,
    session_start_balance numeric,
    cash_sits_today jsonb DEFAULT '{}'::jsonb NOT NULL,
    two_hour_window jsonb DEFAULT '{}'::jsonb NOT NULL,
    mtt_bullets_by_event jsonb DEFAULT '{}'::jsonb NOT NULL,
    mtt_addon_taken jsonb DEFAULT '{}'::jsonb NOT NULL,
    counters_reset_on date,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sh_idle_is_fully_idle CHECK ((((active_seat_count > 0) AND (active_club_id IS NOT NULL) AND (active_host_id IS NOT NULL)) OR ((active_seat_count = 0) AND (active_club_id IS NULL) AND (active_host_id IS NULL)))),
    CONSTRAINT sh_seat_count_matches_ids CHECK ((active_seat_count = cardinality(active_table_ids))),
    CONSTRAINT stable_hand_horse_state_active_seat_count_check CHECK (((active_seat_count >= 0) AND (active_seat_count <= 4))),
    CONSTRAINT stable_hand_horse_state_daily_cap_minutes_check CHECK (((daily_cap_minutes >= 0) AND (daily_cap_minutes <= 1440))),
    CONSTRAINT stable_hand_horse_state_rest_weekday_check CHECK (((rest_weekday >= 0) AND (rest_weekday <= 6)))
);


ALTER TABLE public.stable_hand_horse_state OWNER TO postgres;

--
-- Name: TABLE stable_hand_horse_state; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.stable_hand_horse_state IS 'Operation Stable Hand Section 11: per BODY state. Occupancy is capped per HOST, not per club - JAQK is a strict subset of Shark (580 of 580 measured 2026-09-04), so per-club caps would count one body twice and deliver 80% peak where 40% was asked for.';


--
-- Name: stable_hand_membership_tags; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.stable_hand_membership_tags (
    horse_id uuid NOT NULL,
    club_id uuid NOT NULL,
    mode text NOT NULL,
    cash_freeroll boolean DEFAULT false NOT NULL,
    persona_cash text,
    persona_mtt text,
    variants text[] DEFAULT '{}'::text[] NOT NULL,
    preferred_stakes numeric[] DEFAULT '{}'::numeric[] NOT NULL,
    max_tables smallint DEFAULT 1 NOT NULL,
    tagged_at timestamp with time zone DEFAULT now() NOT NULL,
    tag_seed text NOT NULL,
    CONSTRAINT sh_cash_persona_presence CHECK ((((mode = 'tourney'::text) AND (persona_cash IS NULL)) OR ((mode <> 'tourney'::text) AND (persona_cash IS NOT NULL)))),
    CONSTRAINT sh_freeroll_is_cash_only CHECK (((NOT cash_freeroll) OR (mode = 'cash'::text))),
    CONSTRAINT sh_tourney_only_one_table CHECK (((mode <> 'tourney'::text) OR (max_tables = 1))),
    CONSTRAINT stable_hand_membership_tags_max_tables_check CHECK (((max_tables >= 0) AND (max_tables <= 4))),
    CONSTRAINT stable_hand_membership_tags_mode_check CHECK ((mode = ANY (ARRAY['cash'::text, 'tourney'::text, 'both'::text]))),
    CONSTRAINT stable_hand_membership_tags_persona_cash_check CHECK ((persona_cash = ANY (ARRAY['grinder'::text, 'regular'::text, 'mixer'::text, 'night_owl'::text, 'weekend_heavy'::text]))),
    CONSTRAINT stable_hand_membership_tags_persona_mtt_check CHECK ((persona_mtt = ANY (ARRAY['mtt_grinder'::text, 'mtt_regular'::text, 'mtt_late_reg'::text])))
);


ALTER TABLE public.stable_hand_membership_tags OWNER TO postgres;

--
-- Name: TABLE stable_hand_membership_tags; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.stable_hand_membership_tags IS 'Operation Stable Hand Section 7: per (horse, club) tags. One row per WALLET, so a body with both a JAQK and a Shark wallet has two rows and one identity in stable_hand_horse_state.';


