--
-- Name: TABLE table_pending_addons; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.table_pending_addons IS 'Durable ledger of mid-hand add-ons: wallet already debited, chips not yet delivered. Resolved by resolve_pending_addon(). Intentionally has no FK to tables so the money survives a table delete.';


--
-- Name: COLUMN table_pending_addons.kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.table_pending_addons.kind IS 'addon = mid-hand top-up (atomic_table_addon, apply_to_seat=false); rebuy = bust rebuy (atomic_table_rebuy). Both are debited at insert and delivered to the seat only by resolve_pending_addon, so an absolute stack write from engine memory can never erase them.';


--
-- Name: table_seats; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.table_seats (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    table_id uuid NOT NULL,
    seat_number integer NOT NULL,
    user_id uuid,
    player_id integer,
    member_id uuid,
    stack numeric(15,2) DEFAULT 0,
    is_sitting_out boolean DEFAULT false,
    is_away boolean DEFAULT false,
    joined_at timestamp with time zone DEFAULT now(),
    horse_id uuid,
    scheduled_leave_hands integer,
    left_at timestamp with time zone,
    status text DEFAULT 'active'::text,
    leave_pending boolean DEFAULT false,
    auto_rebuy boolean DEFAULT false,
    time_bank_remaining integer DEFAULT 30,
    time_bank_uses_remaining integer DEFAULT 4,
    club_id uuid,
    sit_out_at timestamp with time zone,
    entry_hold text,
    entry_post_agreed boolean DEFAULT false NOT NULL,
    terminal_closed_at timestamp with time zone,
    CONSTRAINT table_seats_entry_hold_check CHECK (((entry_hold IS NULL) OR (entry_hold = ANY (ARRAY['waiting'::text, 'posting'::text, 'moved'::text])))),
    CONSTRAINT table_seats_seat_number_check CHECK (((seat_number >= 1) AND (seat_number <= 10))),
    CONSTRAINT table_seats_stack_nonneg CHECK ((stack >= (0)::numeric))
)
WITH (autovacuum_vacuum_scale_factor='0.02', autovacuum_analyze_scale_factor='0.02', autovacuum_vacuum_cost_delay='2', autovacuum_vacuum_cost_limit='1000');


