--
-- Name: training_attempts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.training_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    client_nonce text NOT NULL,
    game_id text NOT NULL,
    level integer NOT NULL,
    session_kind text NOT NULL,
    difficulty text NOT NULL,
    expected_hands integer NOT NULL,
    config_hash text NOT NULL,
    parent_attempt_id uuid,
    practice_only boolean NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval) NOT NULL,
    completed_at timestamp with time zone,
    answered_hands integer,
    correct_hands integer,
    accuracy_percentage integer,
    passed boolean,
    best_streak integer,
    reward_diamonds integer,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT training_attempts_config_hash_format CHECK ((config_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT training_attempts_difficulty_check CHECK ((difficulty = ANY (ARRAY['simple'::text, 'grouped'::text, 'exact'::text]))),
    CONSTRAINT training_attempts_expiry_check CHECK ((expires_at > started_at)),
    CONSTRAINT training_attempts_game_length CHECK (((char_length(game_id) >= 1) AND (char_length(game_id) <= 100))),
    CONSTRAINT training_attempts_hand_contract_check CHECK ((((session_kind = 'campaign'::text) AND (expected_hands =
CASE
    WHEN (level = 12) THEN 30
    WHEN (level = 11) THEN 25
    ELSE 20
END)) OR ((session_kind = 'custom'::text) AND (expected_hands = ANY (ARRAY[10, 25, 50, 100]))) OR ((session_kind = 'daily'::text) AND (expected_hands = 1) AND (level = 1)) OR ((session_kind = 'replay'::text) AND ((expected_hands >= 1) AND (expected_hands <= 100))))),
    CONSTRAINT training_attempts_kind_check CHECK ((session_kind = ANY (ARRAY['campaign'::text, 'custom'::text, 'daily'::text, 'replay'::text]))),
    CONSTRAINT training_attempts_level_check CHECK (((level >= 1) AND (level <= 12))),
    CONSTRAINT training_attempts_nonce_length CHECK (((char_length(client_nonce) >= 1) AND (char_length(client_nonce) <= 180))),
    CONSTRAINT training_attempts_practice_kind_check CHECK ((practice_only = (session_kind = 'replay'::text))),
    CONSTRAINT training_attempts_result_check CHECK ((((status = 'completed'::text) AND (completed_at IS NOT NULL) AND (answered_hands IS NOT NULL) AND (correct_hands IS NOT NULL) AND (accuracy_percentage IS NOT NULL) AND (passed IS NOT NULL) AND (best_streak IS NOT NULL) AND (reward_diamonds IS NOT NULL)) OR ((status <> 'completed'::text) AND (completed_at IS NULL) AND (answered_hands IS NULL) AND (correct_hands IS NULL) AND (accuracy_percentage IS NULL) AND (passed IS NULL) AND (best_streak IS NULL) AND (reward_diamonds IS NULL)))),
    CONSTRAINT training_attempts_result_range_check CHECK (((answered_hands IS NULL) OR ((answered_hands = expected_hands) AND ((correct_hands >= 0) AND (correct_hands <= answered_hands)) AND ((accuracy_percentage >= 0) AND (accuracy_percentage <= 100)) AND ((best_streak >= 0) AND (best_streak <= answered_hands)) AND (reward_diamonds >= 0)))),
    CONSTRAINT training_attempts_status_check CHECK ((status = ANY (ARRAY['open'::text, 'completed'::text, 'abandoned'::text, 'expired'::text])))
);


