--
-- Name: training_leaderboard_top; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.training_leaderboard_top AS
 SELECT row_number() OVER (ORDER BY accuracy DESC, total_correct DESC, user_id) AS rank,
    user_id,
    accuracy,
    total_correct,
    total_questions,
    total_sessions,
    best_streak,
    last_session_at
   FROM public.training_user_progress p
  WHERE (total_questions >= 25)
  ORDER BY accuracy DESC, total_correct DESC
 LIMIT 500
  WITH NO DATA;


