    generated_at timestamp with time zone DEFAULT now(),
    times_used integer DEFAULT 0,
    question_kind text DEFAULT 'PIO'::text NOT NULL,
    source_classification text DEFAULT 'LEGACY_UNVERIFIED'::text NOT NULL,
    canonical_policy jsonb NOT NULL,
    scenario_hash text,
    exact_node jsonb,
    public_action_history jsonb,
    policy_version text,
    solver_version text,
    solver_binary_checksum text,
    manifest_version text,
    manifest_checksum text,
    source_checksum text,
    pipeline_commit text,
    machine_id text,
    quality_status text DEFAULT 'quarantined'::text NOT NULL,
    source_created_at timestamp with time zone,
    source_audited_at timestamp with time zone,
    generator_version text DEFAULT 'training-cache-contract.1:legacy_unverified'::text NOT NULL,
    lineage jsonb DEFAULT '{}'::jsonb NOT NULL,
    content_checksum text NOT NULL,
    policy_checksum text NOT NULL,
    served_count bigint DEFAULT 0 NOT NULL,
    answered_count bigint DEFAULT 0 NOT NULL,
    correct_count bigint DEFAULT 0 NOT NULL,
    completed_count bigint DEFAULT 0 NOT NULL,
    last_served_at timestamp with time zone,
    last_answered_at timestamp with time zone,
    last_completed_at timestamp with time zone,
    contract_stamped_at timestamp with time zone DEFAULT now() NOT NULL,
    contract_audited_at timestamp with time zone,
    audit_shard smallint GENERATED ALWAYS AS (((get_byte(decode(md5(question_id), 'hex'::text), 0) % 16))::smallint) STORED,
    CONSTRAINT training_question_cache_audit_shard_check CHECK (((audit_shard >= 0) AND (audit_shard <= 15))),
    CONSTRAINT training_question_cache_content_checksum_check CHECK ((content_checksum ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT training_question_cache_counters_check CHECK (((served_count >= 0) AND (answered_count >= 0) AND (correct_count >= 0) AND (completed_count >= 0) AND (correct_count <= answered_count))),
    CONSTRAINT training_question_cache_kind_check CHECK ((question_kind = ANY (ARRAY['PIO'::text, 'CHART'::text, 'SCENARIO'::text]))),
    CONSTRAINT training_question_cache_lineage_object_check CHECK ((jsonb_typeof(lineage) = 'object'::text)),
    CONSTRAINT training_question_cache_policy_checksum_check CHECK ((policy_checksum ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT training_question_cache_policy_object_check CHECK (((canonical_policy IS NULL) OR (jsonb_typeof(canonical_policy) = 'object'::text))),
    CONSTRAINT training_question_cache_quality_status_check CHECK ((quality_status = ANY (ARRAY['active'::text, 'active_fallback'::text, 'quarantined'::text, 'drifted'::text]))),
    CONSTRAINT training_question_cache_source_classification_check CHECK ((source_classification = ANY (ARRAY['SOLVER_EXACT'::text, 'SOLVER_AGGREGATED'::text, 'SOLVER_DERIVED_RESPONSE'::text, 'CHART_AUDITED'::text, 'MODEL_DISTILLED'::text, 'CURATED'::text, 'HEURISTIC'::text, 'LEGACY_UNVERIFIED'::text]))),
    CONSTRAINT valid_engine_type CHECK ((engine_type = ANY (ARRAY['PIO'::text, 'CHART'::text, 'SCENARIO'::text]))),
    CONSTRAINT valid_game_type CHECK ((game_type = ANY (ARRAY['cash'::text, 'tournament'::text, 'sng'::text]))),
    CONSTRAINT valid_level CHECK (((level >= 1) AND (level <= 12)))
);


