--
-- Name: training_question_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.training_question_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_type text NOT NULL,
    event_key text NOT NULL,
    question_id text NOT NULL,
    user_id uuid,
    is_correct boolean,
    policy_checksum text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    binding_status text DEFAULT 'CHECKSUM_BOUND'::text NOT NULL,
    CONSTRAINT training_question_events_answer_check CHECK ((((event_type = 'answered'::text) AND (is_correct IS NOT NULL)) OR ((event_type <> 'answered'::text) AND (is_correct IS NULL)))),
    CONSTRAINT training_question_events_binding_metadata_check CHECK ((((binding_status = 'HISTORICAL_UNBOUND'::text) AND (metadata @> '{"historicalPolicyBinding": false}'::jsonb)) OR ((binding_status = 'CHECKSUM_BOUND'::text) AND (NOT (metadata @> '{"historicalPolicyBinding": false}'::jsonb))))),
    CONSTRAINT training_question_events_binding_status_check CHECK ((binding_status = ANY (ARRAY['CHECKSUM_BOUND'::text, 'HISTORICAL_UNBOUND'::text]))),
    CONSTRAINT training_question_events_key_length_check CHECK (((length(event_key) >= 1) AND (length(event_key) <= 320) AND ((length(question_id) >= 1) AND (length(question_id) <= 180)))),
    CONSTRAINT training_question_events_policy_checksum_check CHECK ((policy_checksum ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT training_question_events_type_check CHECK ((event_type = ANY (ARRAY['served'::text, 'answered'::text, 'completed'::text])))
);


ALTER TABLE public.training_question_events OWNER TO postgres;

--
-- Name: COLUMN training_question_events.binding_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.training_question_events.binding_status IS 'CHECKSUM_BOUND means the caller supplied the exact served policy checksum and selected action. HISTORICAL_UNBOUND preserves pre-enforcement telemetry without presenting it as policy evidence.';


