--
-- Name: training_solver_artifact_catalog; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.training_solver_artifact_catalog (
    artifact_id uuid NOT NULL,
    scenario_hash text NOT NULL,
    game_type text NOT NULL,
    stack_depth integer NOT NULL,
    street text NOT NULL,
    hero_position text NOT NULL,
    registered_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT training_solver_artifact_catalog_contract_check CHECK ((((game_type = 'hu_cash'::text) AND (stack_depth = ANY (ARRAY[40, 100, 200]))) OR ((game_type = 'mtt_3max_chipev'::text) AND (stack_depth = 20)) OR ((game_type = 'mtt_6max_chipev'::text) AND (stack_depth = ANY (ARRAY[10, 20, 40, 100]))) OR ((game_type = 'mtt_6max_icm'::text) AND (stack_depth = ANY (ARRAY[20, 40]))) OR ((game_type = 'mtt_9max_chipev'::text) AND (stack_depth = ANY (ARRAY[20, 40, 80, 100]))) OR ((game_type = 'mtt_9max_icm'::text) AND (stack_depth = ANY (ARRAY[40, 60]))) OR ((game_type = 'mtt_hu_chipev'::text) AND (stack_depth = 40)) OR ((game_type = 'postflop_complete'::text) AND (stack_depth = 100)) OR ((game_type = 'spin_3max_chipev'::text) AND (stack_depth = ANY (ARRAY[20, 25]))) OR ((game_type = 'spin_3max_icm'::text) AND (stack_depth = ANY (ARRAY[20, 25]))) OR ((game_type = 'spin_hu_chipev'::text) AND (stack_depth = ANY (ARRAY[10, 20]))) OR ((game_type = 'spin_hu_icm'::text) AND (stack_depth = 10)))),
    CONSTRAINT training_solver_artifact_catalog_position_check CHECK ((hero_position = ANY (ARRAY['UTG'::text, 'UTG+1'::text, 'UTG+2'::text, 'UTG1'::text, 'UTG2'::text, 'MP'::text, 'MP+1'::text, 'MP+2'::text, 'MP1'::text, 'MP2'::text, 'LJ'::text, 'HJ'::text, 'CO'::text, 'BTN'::text, 'SB'::text, 'BB'::text]))),
    CONSTRAINT training_solver_artifact_catalog_scenario_check CHECK (((char_length(scenario_hash) >= 1) AND (char_length(scenario_hash) <= 512))),
    CONSTRAINT training_solver_artifact_catalog_stack_check CHECK ((stack_depth > 0)),
    CONSTRAINT training_solver_artifact_catalog_street_check CHECK ((street = ANY (ARRAY['flop'::text, 'turn'::text, 'river'::text])))
);


ALTER TABLE public.training_solver_artifact_catalog OWNER TO postgres;

--
-- Name: TABLE training_solver_artifact_catalog; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.training_solver_artifact_catalog IS 'Small request-path registry of provenance-complete validated solver artifacts. Historical warehouse rows are deliberately not scanned or inferred.';


--
-- Name: training_solver_provenance_authority; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.training_solver_provenance_authority (
    machine_id text NOT NULL,
    solver_version text NOT NULL,
    solver_binary_checksum text NOT NULL,
    pipeline_commit text NOT NULL,
    manifest_version text NOT NULL,
    manifest_checksum text NOT NULL,
    source_combo_order_sha256 text NOT NULL,
    training_game_contracts_sha256 text NOT NULL,
    manifest_contracts jsonb NOT NULL,
    approved_at timestamp with time zone DEFAULT now() NOT NULL,
    approved_by text NOT NULL,
    retired_at timestamp with time zone,
    CONSTRAINT training_solver_provenance_authority_contracts_check CHECK (
CASE
    WHEN (jsonb_typeof(manifest_contracts) = 'array'::text) THEN ((jsonb_array_length(manifest_contracts) >= 1) AND (jsonb_array_length(manifest_contracts) <= 64))
    ELSE false
END),
    CONSTRAINT training_solver_provenance_authority_game_scope_check CHECK (((training_game_contracts_sha256 ~ '^[0-9a-f]{64}$'::text) AND (training_game_contracts_sha256 <> repeat('0'::text, 64)))),
    CONSTRAINT training_solver_provenance_authority_labels_check CHECK (((char_length(btrim(solver_version)) >= 1) AND (char_length(btrim(solver_version)) <= 120) AND ((char_length(btrim(manifest_version)) >= 1) AND (char_length(btrim(manifest_version)) <= 160)) AND ((char_length(btrim(approved_by)) >= 3) AND (char_length(btrim(approved_by)) <= 200)))),
    CONSTRAINT training_solver_provenance_authority_machine_check CHECK ((machine_id = ANY (ARRAY['M1'::text, 'M2'::text]))),
    CONSTRAINT training_solver_provenance_authority_manifest_checksum_check CHECK ((manifest_checksum ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT training_solver_provenance_authority_pipeline_check CHECK ((pipeline_commit ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT training_solver_provenance_authority_retirement_check CHECK (((retired_at IS NULL) OR (retired_at >= approved_at))),
    CONSTRAINT training_solver_provenance_authority_solver_checksum_check CHECK ((solver_binary_checksum ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT training_solver_provenance_authority_source_order_check CHECK (((source_combo_order_sha256 ~ '^[0-9a-f]{64}$'::text) AND (source_combo_order_sha256 <> repeat('0'::text, 64))))
);


ALTER TABLE public.training_solver_provenance_authority OWNER TO postgres;

--
-- Name: TABLE training_solver_provenance_authority; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.training_solver_provenance_authority IS 'Migration-administered allowlist of exact solver binary, pipeline, manifest, and machine tuples eligible for Training catalog admission. Empty is deliberately fail-closed.';


--
-- Name: training_solver_worker_receipts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.training_solver_worker_receipts (
    machine_id text NOT NULL,
    request_nonce uuid NOT NULL,
    operation text NOT NULL,
    signed_at timestamp with time zone NOT NULL,
    body_sha256 text NOT NULL,
    solver_version text NOT NULL,
    solver_binary_checksum text NOT NULL,
    pipeline_commit text NOT NULL,
    manifest_version text NOT NULL,
    manifest_checksum text NOT NULL,
    artifact_id uuid,
    scenario_hash text,
    source_artifact_checksum text,
    received_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT training_solver_worker_receipts_artifact_check CHECK (((operation = 'ingest_artifact'::text) = ((artifact_id IS NOT NULL) AND (scenario_hash IS NOT NULL) AND ((char_length(scenario_hash) >= 1) AND (char_length(scenario_hash) <= 512)) AND (source_artifact_checksum ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT training_solver_worker_receipts_body_check CHECK ((body_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT training_solver_worker_receipts_machine_check CHECK ((machine_id = ANY (ARRAY['M1'::text, 'M2'::text]))),
    CONSTRAINT training_solver_worker_receipts_operation_check CHECK ((operation = ANY (ARRAY['ingest_artifact'::text, 'row_states'::text, 'board_page'::text, 'heartbeat'::text]))),
    CONSTRAINT training_solver_worker_receipts_provenance_check CHECK (((char_length(btrim(solver_version)) >= 1) AND (char_length(btrim(solver_version)) <= 120) AND (solver_binary_checksum ~ '^[0-9a-f]{64}$'::text) AND (pipeline_commit ~ '^[0-9a-f]{40}$'::text) AND ((char_length(btrim(manifest_version)) >= 1) AND (char_length(btrim(manifest_version)) <= 160)) AND (manifest_checksum ~ '^[0-9a-f]{64}$'::text)))
);


ALTER TABLE public.training_solver_worker_receipts OWNER TO postgres;

