--
-- Name: training_verified_leaderboard; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.training_verified_leaderboard (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    period_type text NOT NULL,
    period_key text NOT NULL,
    dimension_type text NOT NULL,
    dimension_key text NOT NULL,
    game_id text,
    category text,
    sessions_completed integer DEFAULT 0 NOT NULL,
    questions_answered integer DEFAULT 0 NOT NULL,
    questions_correct integer DEFAULT 0 NOT NULL,
    accuracy numeric(5,2) DEFAULT 0 NOT NULL,
    perfect_rounds integer DEFAULT 0 NOT NULL,
    best_streak integer DEFAULT 0 NOT NULL,
    gtow_score_avg numeric,
    gtow_score_sum numeric DEFAULT 0 NOT NULL,
    gtow_score_samples integer DEFAULT 0 NOT NULL,
    ev_loss_total numeric DEFAULT 0 NOT NULL,
    score_scale smallint DEFAULT 2 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT training_verified_leaderboard_dimension_check CHECK ((((dimension_type = 'overall'::text) AND (dimension_key = 'overall'::text) AND (game_id IS NULL) AND (category IS NULL)) OR ((dimension_type = 'game'::text) AND (dimension_key = game_id) AND ((char_length(game_id) >= 1) AND (char_length(game_id) <= 100)) AND (category IS NULL)) OR ((dimension_type = 'category'::text) AND (dimension_key = category) AND (game_id IS NULL) AND (category = ANY (ARRAY['mtt'::text, 'cash'::text, 'spins'::text, 'psychology'::text, 'advanced'::text]))))),
    CONSTRAINT training_verified_leaderboard_period_check CHECK ((period_type = ANY (ARRAY['daily'::text, 'weekly'::text, 'monthly'::text, 'alltime'::text]))),
    CONSTRAINT training_verified_leaderboard_period_key_length CHECK (((char_length(period_key) >= 1) AND (char_length(period_key) <= 32))),
    CONSTRAINT training_verified_leaderboard_score_samples_check CHECK (((gtow_score_samples >= 0) AND (gtow_score_samples <= sessions_completed) AND (((gtow_score_samples = 0) AND (gtow_score_avg IS NULL) AND (gtow_score_sum = (0)::numeric)) OR ((gtow_score_samples > 0) AND (gtow_score_avg IS NOT NULL))))),
    CONSTRAINT training_verified_leaderboard_totals_check CHECK (((sessions_completed >= 0) AND (questions_answered >= 0) AND ((questions_correct >= 0) AND (questions_correct <= questions_answered)) AND ((accuracy >= (0)::numeric) AND (accuracy <= (100)::numeric)) AND ((perfect_rounds >= 0) AND (perfect_rounds <= sessions_completed)) AND (best_streak >= 0) AND (score_scale = 2)))
);


ALTER TABLE public.training_verified_leaderboard OWNER TO postgres;

