    winner_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    completed_at timestamp with time zone,
    challenger_id uuid,
    opponent_id uuid,
    challenger_score integer,
    opponent_score integer,
    category text,
    settlement_kind text,
    stats_recorded_at timestamp with time zone,
    CONSTRAINT trivia_pvp_matches_allowed_stake_check CHECK (((stake_amount IS NOT NULL) AND (stake_amount = ANY (ARRAY[10, 25, 50, 100])))),
    CONSTRAINT trivia_pvp_matches_distinct_players_check CHECK (((player1_id IS NULL) OR (player2_id IS NULL) OR (player1_id <> player2_id))),
    CONSTRAINT trivia_pvp_matches_score_aliases_check CHECK (((NOT (player1_score IS DISTINCT FROM challenger_score)) AND (NOT (player2_score IS DISTINCT FROM opponent_score)))),
    CONSTRAINT trivia_pvp_matches_score_bounds_check CHECK ((((player1_score IS NULL) OR ((player1_score >= 0) AND (player1_score <= 20))) AND ((player2_score IS NULL) OR ((player2_score >= 0) AND (player2_score <= 20))) AND ((challenger_score IS NULL) OR ((challenger_score >= 0) AND (challenger_score <= 20))) AND ((opponent_score IS NULL) OR ((opponent_score >= 0) AND (opponent_score <= 20))))),
    CONSTRAINT trivia_pvp_matches_settlement_kind_check CHECK (((settlement_kind IS NULL) OR (settlement_kind = ANY (ARRAY['win'::text, 'tie'::text, 'refund'::text, 'void'::text])))),
    CONSTRAINT trivia_pvp_matches_status_check CHECK (((status IS NOT NULL) AND (status = ANY (ARRAY['pending'::text, 'active'::text, 'settling'::text, 'complete'::text, 'completed'::text, 'cancelled'::text, 'expired'::text, 'abandoned'::text])))),
    CONSTRAINT trivia_pvp_matches_winner_participant_check CHECK (((winner_id IS NULL) OR (NOT (winner_id IS DISTINCT FROM player1_id)) OR (NOT (winner_id IS DISTINCT FROM player2_id))))
);


