    CONSTRAINT trivia_pvp_settlement_decisions_side_state_check CHECK (((jsonb_typeof(side_state) = 'array'::text) AND (jsonb_array_length(side_state) = 2))),
    CONSTRAINT trivia_pvp_settlement_decisions_winner_check CHECK ((((decision_kind = 'win'::text) AND (winner_id IS NOT NULL)) OR ((decision_kind <> 'win'::text) AND (winner_id IS NULL))))
);


