--
-- Name: venue_daily_tournaments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.venue_daily_tournaments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    venue_id integer,
    venue_name text NOT NULL,
    day_of_week text NOT NULL,
    start_time text NOT NULL,
    tournament_name text,
    buy_in integer,
    rebuy_addon text,
    starting_stack integer,
    blind_levels text,
    guaranteed integer,
    game_type text DEFAULT 'NLH'::text,
    format text,
    source_url text,
    last_scraped timestamp with time zone DEFAULT now(),
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    data_quality text NOT NULL,
    scrape_html_hash text NOT NULL,
    scrape_timestamp timestamp with time zone NOT NULL,
    scrape_confidence text DEFAULT 'unverified'::text,
    scrape_batch_id uuid,
    event_date date,
    late_registration text,
    notes text,
    max_entries integer,
    level_duration_minutes integer,
    bounty_amount integer,
    satellite_to text,
    min_players_to_run integer,
    registration_opens text,
    online_registration_url text,
    structure_sheet_url text,
    number_of_levels integer,
    payout_levels text,
    age_requirement integer,
    timezone text,
    is_special_event boolean DEFAULT false,
    series_name text,
    series_event_number text,
    scrape_completeness_score integer DEFAULT 0,
    best_scrape_url text,
    scrape_fail_count integer DEFAULT 0,
    flags jsonb DEFAULT '[]'::jsonb,
    human_verified boolean DEFAULT false,
    is_recurring boolean DEFAULT true,
    parent_tournament_id uuid,
    is_suppressed boolean DEFAULT false,
    scrape_source text,
    pnm_verified_morning_evidence boolean GENERATED ALWAYS AS (((start_time ~* '^0?[89](?::[0-5][0-9](?::[0-5][0-9])?)?[[:space:]]*AM$'::text) AND (data_quality = 'scraped_verified'::text) AND (scrape_source = 'pokeratlas'::text) AND (btrim(source_url) ~* '^https://(www\.)?pokeratlas\.com/poker-room/[^/?#[:space:]]+/tournaments/?([?#][^[:space:]]*)?$'::text) AND (scrape_html_hash ~ '^[0-9A-Fa-f]{64}$'::text) AND (scrape_html_hash !~ '^0{64}$'::text) AND ((scrape_batch_id)::text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text) AND ((buy_in >= 20) AND (buy_in <= 100000)))) STORED,
    pnm_reader_static_servable boolean GENERATED ALWAYS AS ((is_active AND (is_suppressed IS NOT TRUE) AND (data_quality = ANY (ARRAY['scraped_verified'::text, 'scraped_inferred'::text, 'manual_research'::text])) AND (btrim(COALESCE(tournament_name, ''::text)) <> ''::text) AND (btrim(COALESCE(venue_name, ''::text)) <> ''::text) AND ("left"(ltrim(tournament_name), 1) <> ALL (ARRAY['@'::text, '{'::text, '['::text])) AND ("left"(ltrim(venue_name), 1) <> ALL (ARRAY['@'::text, '{'::text, '['::text])) AND (tournament_name !~* '(<|>|-->|(^|[[:space:]])(class|href|src|style|charset|content|data-[a-z0-9_-]+)[[:space:]]*=)'::text) AND (venue_name !~* '(<|>|-->|(^|[[:space:]])(class|href|src|style|charset|content|data-[a-z0-9_-]+)[[:space:]]*=)'::text) AND (tournament_name !~* '&(#[x]?[0-9a-f]+|[a-z][a-z0-9]+)[[:space:]]*$'::text) AND (venue_name !~* '&(#[x]?[0-9a-f]+|[a-z][a-z0-9]+)[[:space:]]*$'::text) AND (NOT (COALESCE(flags, '[]'::jsonb) ?| ARRAY['pnm_public_text_quarantine_20260907'::text, 'quarantined'::text, 'suppressed'::text])) AND ((btrim(COALESCE(start_time, ''::text)) = ''::text) OR (lower(btrim(start_time)) = ANY (ARRAY['tbd'::text, 'unknown'::text, 'to be announced'::text])) OR (btrim(start_time) ~* '^(?:(?:10|11)(?::[0-5][0-9](?::[0-5][0-9])?)?[[:space:]]*AM|(?:0?[1-9]|1[0-2])(?::[0-5][0-9](?::[0-5][0-9])?)?[[:space:]]*PM|(?:1[0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?)$'::text) OR ((start_time ~* '^0?[89](?::[0-5][0-9](?::[0-5][0-9])?)?[[:space:]]*AM$'::text) AND (data_quality = 'scraped_verified'::text) AND (scrape_source = 'pokeratlas'::text) AND (btrim(source_url) ~* '^https://(www\.)?pokeratlas\.com/poker-room/[^/?#[:space:]]+/tournaments/?([?#][^[:space:]]*)?$'::text) AND (scrape_html_hash ~ '^[0-9A-Fa-f]{64}$'::text) AND (scrape_html_hash !~ '^0{64}$'::text) AND ((scrape_batch_id)::text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text) AND ((buy_in >= 20) AND (buy_in <= 100000)))))) STORED,
    CONSTRAINT venue_daily_tournaments_data_quality_truth_check CHECK ((data_quality = ANY (ARRAY['scraped_verified'::text, 'scraped_inferred'::text, 'manual_research'::text, 'stale'::text, 'expired'::text, 'pending'::text])))
);


ALTER TABLE public.venue_daily_tournaments OWNER TO postgres;

--
-- Name: TABLE venue_daily_tournaments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.venue_daily_tournaments IS 'Daily recurring tournament schedules scraped from venue/charity websites. Unique index on (venue_name, day_of_week, start_time, game_type, buy_in) prevents duplicate scraper runs. buy_in=0 means Free Entry; buy_in IS NULL means unknown.';


--
-- Name: COLUMN venue_daily_tournaments.scrape_source; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.venue_daily_tournaments.scrape_source IS 'Exact parser/source discriminator persisted by the tournament schedule writer; NULL means legacy provenance is not proven.';


--
-- Name: COLUMN venue_daily_tournaments.pnm_verified_morning_evidence; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.venue_daily_tournaments.pnm_verified_morning_evidence IS 'Immutable source/time/provenance portion of the verified 8:00-9:59 AM public-reader contract.';


--
-- Name: COLUMN venue_daily_tournaments.pnm_reader_static_servable; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.venue_daily_tournaments.pnm_reader_static_servable IS 'Immutable daily public-reader predicates; timestamp and recurrence freshness remain request-time checks.';


--
-- Name: unified_events_calendar; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.unified_events_calendar WITH (security_invoker='true') AS
 SELECT 'daily'::text AS source,
    (vdt.id)::text AS native_id,
    vdt.venue_name,
    (vdt.venue_id)::text AS venue_id,
    NULL::text AS series_id,
    NULL::text AS tour_event_id,
    NULL::text AS tour_code,
    vdt.tournament_name AS event_name,
    vdt.start_time,
    (vdt.buy_in)::numeric AS buy_in,
    vdt.game_type,
    (vdt.guaranteed)::numeric AS guaranteed,
    vdt.format,
    (vdt.starting_stack)::text AS starting_stack,
    vdt.day_of_week,
    (vdt.event_date)::text AS specific_date,
    vdt.is_recurring,
    vdt.is_suppressed,
    vdt.is_active,
    v.city,
    v.state,
    (v.latitude)::numeric AS latitude,
    (v.longitude)::numeric AS longitude,
    NULL::text AS logo_url
   FROM (public.venue_daily_tournaments vdt
     LEFT JOIN public.poker_venues v ON ((v.id = vdt.venue_id)))
UNION ALL
 SELECT 'series'::text AS source,
    (ps.id)::text AS native_id,
    ps.venue_name,
    (ps.venue_id)::text AS venue_id,
    (ps.id)::text AS series_id,
    NULL::text AS tour_event_id,
    ps.tour_code,
    COALESCE(ps.series_name, ps.short_name) AS event_name,
    NULL::text AS start_time,
    (COALESCE(ps.main_event_buyin, ps.buy_in_min))::numeric AS buy_in,
    COALESCE(ps.series_type, 'NLH'::text) AS game_type,
    (COALESCE(ps.total_guaranteed, ps.main_event_guaranteed))::numeric AS guaranteed,
    NULL::text AS format,
    NULL::text AS starting_stack,
    NULL::text AS day_of_week,
    (ps.start_date)::text AS specific_date,
    false AS is_recurring,
    ps.is_suppressed,
    true AS is_active,
    COALESCE(ps.city, v.city) AS city,
    COALESCE(ps.state, v.state) AS state,
    (v.latitude)::numeric AS latitude,
    (v.longitude)::numeric AS longitude,
    ps.logo_url
   FROM (public.poker_series ps
     LEFT JOIN public.poker_venues v ON ((v.id = ps.venue_id)))
UNION ALL
 SELECT 'tour'::text AS source,
    (tse.id)::text AS native_id,
    tse.stop_venue AS venue_name,
    NULL::text AS venue_id,
    NULL::text AS series_id,
    (tse.id)::text AS tour_event_id,
    tse.tour_code,
    COALESCE(tse.event_name, tse.stop_name) AS event_name,
    tse.start_time,
    (tse.buy_in)::numeric AS buy_in,
    tse.game_type,
    (tse.guarantee)::numeric AS guaranteed,
    NULL::text AS format,
    NULL::text AS starting_stack,
    NULL::text AS day_of_week,
    (tse.start_date)::text AS specific_date,
    false AS is_recurring,
    false AS is_suppressed,
    true AS is_active,
    tse.stop_city AS city,
    tse.stop_state AS state,
    NULL::numeric AS latitude,
    NULL::numeric AS longitude,
    NULL::text AS logo_url
   FROM public.tour_stop_events tse;


ALTER VIEW public.unified_events_calendar OWNER TO postgres;

--
-- Name: VIEW unified_events_calendar; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.unified_events_calendar IS 'Unified calendar: daily tournaments + series + tour stops. Recreated 2026-04-22 as SECURITY INVOKER — RLS on all source tables is now enforced per-caller. Previously had SECURITY DEFINER (risk).';


