-- Name: user_leaks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.user_leaks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    leak_category text NOT NULL,
    leak_name text NOT NULL,
    error_rate numeric(5,4) DEFAULT 1.0 NOT NULL,
    confidence numeric(5,4) DEFAULT 0.25 NOT NULL,
    total_samples integer DEFAULT 1 NOT NULL,
    mistake_count integer DEFAULT 1 NOT NULL,
    detected_at timestamp with time zone DEFAULT now(),
    clinic_id text,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    leak_type text,
    situation_class text,
    status text DEFAULT 'emerging'::text,
    avg_ev_loss_bb numeric(5,4),
    occurrence_count integer DEFAULT 0,
    optimal_frequency numeric(5,2),
    current_frequency numeric(5,2),
    first_detected_at timestamp with time zone,
    last_detected_at timestamp with time zone,
    trend_data jsonb DEFAULT '[]'::jsonb,
    explanation text,
    why_leaking_ev text,
    recommended_drill text,
    source_system text DEFAULT 'live'::text,
    resolved_at timestamp with time zone,
    suggested_fix text,
    notes text,
    remediation_completed_at timestamp with time zone,
    ev_loss_measured boolean DEFAULT false NOT NULL,
    detector_managed boolean DEFAULT false NOT NULL,
    resolution_source text,
    CONSTRAINT user_leaks_payload_bounds_check CHECK (((char_length(leak_category) <= 80) AND (char_length(leak_name) <= 240) AND ((leak_type IS NULL) OR ((char_length(leak_type) <= 180) AND (leak_type ~ '^[a-z0-9_]+$'::text))) AND ((situation_class IS NULL) OR (char_length(situation_class) <= 240)) AND ((explanation IS NULL) OR (char_length(explanation) <= 4000)) AND ((why_leaking_ev IS NULL) OR (char_length(why_leaking_ev) <= 4000)) AND ((notes IS NULL) OR (char_length(notes) <= 4000)) AND (octet_length((COALESCE(trend_data, '[]'::jsonb))::text) <= 65536))),
    CONSTRAINT user_leaks_resolution_source_check CHECK (((resolution_source IS NULL) OR (resolution_source = ANY (ARRAY['manual'::text, 'detector'::text]))))
);


ALTER TABLE public.user_leaks OWNER TO postgres;

