CREATE VIEW public.v_ca_suspense_balance WITH (security_invoker='true') AS
 SELECT (COALESCE(sum(
        CASE
            WHEN (to_type = 'settlement_suspense'::text) THEN amount
            ELSE (0)::numeric
        END), (0)::numeric) - COALESCE(sum(
        CASE
            WHEN (from_type = 'settlement_suspense'::text) THEN amount
            ELSE (0)::numeric
        END), (0)::numeric)) AS suspense_net,
    count(*) FILTER (WHERE ((to_type = 'settlement_suspense'::text) OR (from_type = 'settlement_suspense'::text))) AS suspense_rows
   FROM public.chip_ledger
  WHERE (created_at > (now() - '30 days'::interval));


