--
-- Name: v_cashier_health_hourly; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_cashier_health_hourly WITH (security_invoker='true') AS
 SELECT date_trunc('hour'::text, created_at) AS hour,
    operation,
    sum(sample_weight) AS estimated_events,
    count(*) FILTER (WHERE (event = ANY (ARRAY['roster_page_failed'::text, 'batch_partial'::text, 'batch_failed'::text]))) AS failures,
    round(((100.0 * (count(*) FILTER (WHERE (event = ANY (ARRAY['roster_page_failed'::text, 'batch_partial'::text, 'batch_failed'::text]))))::numeric) / (NULLIF(sum(sample_weight), 0))::numeric), 2) AS failure_pct,
    percentile_disc((0.50)::double precision) WITHIN GROUP (ORDER BY duration_ms) FILTER (WHERE ((duration_ms IS NOT NULL) AND (event = ANY (ARRAY['roster_page_succeeded'::text, 'batch_succeeded'::text])))) AS success_p50_ms,
    percentile_disc((0.95)::double precision) WITHIN GROUP (ORDER BY duration_ms) FILTER (WHERE ((duration_ms IS NOT NULL) AND (event = ANY (ARRAY['roster_page_succeeded'::text, 'batch_succeeded'::text])))) AS success_p95_ms,
    sum(COALESCE(item_count, 0)) AS observed_items,
    sum(COALESCE(success_count, 0)) AS observed_successes,
    sum(COALESCE(failure_count, 0)) AS observed_failures
   FROM public.cashier_operations
  GROUP BY (date_trunc('hour'::text, created_at)), operation
  ORDER BY (date_trunc('hour'::text, created_at)) DESC, operation;


