--
-- Name: wallet_transactions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.wallet_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    wallet_type text NOT NULL,
    amount numeric(15,2) NOT NULL,
    type text NOT NULL,
    category text NOT NULL,
    description text,
    related_entity_id uuid,
    table_id uuid,
    hand_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    balance_after numeric,
    terminal_closed_at timestamp with time zone,
    CONSTRAINT wallet_transactions_type_check CHECK ((type = ANY (ARRAY['credit'::text, 'debit'::text]))),
    CONSTRAINT wallet_transactions_wallet_type_check CHECK ((wallet_type = ANY (ARRAY['PLAYER'::text, 'BUSINESS'::text, 'PROMO'::text, 'CLUB'::text, 'UNION'::text, 'PLATFORM'::text])))
)
WITH (autovacuum_enabled='true', autovacuum_analyze_scale_factor='0.0', autovacuum_analyze_threshold='1000', autovacuum_vacuum_scale_factor='0.0', autovacuum_vacuum_threshold='1000', autovacuum_vacuum_cost_delay='2', autovacuum_vacuum_cost_limit='2000');


ALTER TABLE public.wallet_transactions OWNER TO postgres;

--
-- Name: v_chip_ledger; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_chip_ledger WITH (security_invoker='on') AS
 SELECT wt.id,
    'wallet_transactions'::text AS source_ledger,
    wt.created_at,
    wt.user_id AS subject_user_id,
    NULL::uuid AS counterparty_user_id,
    NULL::uuid AS club_id,
    wt.table_id,
    wt.category AS kind,
    wt.amount,
        CASE
            WHEN (wt.type = 'credit'::text) THEN wt.amount
            ELSE (- wt.amount)
        END AS signed_amount,
    wt.type AS direction,
    wt.description AS notes,
    NULL::jsonb AS metadata
   FROM public.wallet_transactions wt
UNION ALL
 SELECT ct.id,
    'chip_transactions'::text AS source_ledger,
    ct.created_at,
    COALESCE(ct.to_user_id, ct.from_user_id) AS subject_user_id,
        CASE
            WHEN (ct.to_user_id IS NOT NULL) THEN ct.from_user_id
            ELSE ct.to_user_id
        END AS counterparty_user_id,
    ct.club_id,
    ct.table_id,
    ct.transaction_type AS kind,
    ct.amount,
        CASE
            WHEN (ct.to_user_id IS NOT NULL) THEN ct.amount
            ELSE (- ct.amount)
        END AS signed_amount,
        CASE
            WHEN (ct.to_user_id IS NOT NULL) THEN 'credit'::text
            ELSE 'debit'::text
        END AS direction,
    ct.notes,
    ct.metadata
   FROM public.chip_transactions ct;


ALTER VIEW public.v_chip_ledger OWNER TO postgres;

--
-- Name: VIEW v_chip_ledger; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_chip_ledger IS 'One read surface over BOTH chip ledgers (wallet_transactions + chip_transactions). A table cash-out appears in both via different paths and the sets do not overlap, so reading only one ledger gives a wrong answer — the union P&L had to FULL OUTER JOIN them. Prefer this view for new readers. signed_amount is positive when chips move TO subject_user_id. Read-only; writers still target the physical tables.';


