    percentile_disc((0.50)::double precision) WITHIN GROUP (ORDER BY duration_ms) FILTER (WHERE ((event = 'appearance_saved'::text) AND (duration_ms IS NOT NULL))) AS apply_p50_ms,
    percentile_disc((0.95)::double precision) WITHIN GROUP (ORDER BY duration_ms) FILTER (WHERE ((event = 'appearance_saved'::text) AND (duration_ms IS NOT NULL))) AS apply_p95_ms,
    sum(sample_weight) FILTER (WHERE (event = ANY (ARRAY['purchase_succeeded'::text, 'purchase_failed'::text]))) AS purchase_estimated_attempts,
    count(*) FILTER (WHERE (event = 'purchase_failed'::text)) AS purchase_failures,
    count(*) FILTER (WHERE (event = 'realtime_failed'::text)) AS realtime_failures,
    count(*) FILTER (WHERE (event = 'realtime_recovered'::text)) AS realtime_recoveries,
    count(*) FILTER (WHERE (event = 'conflict_suppressed'::text)) AS conflicts_suppressed
   FROM public.customization_operations
  GROUP BY (date_trunc('hour'::text, created_at))
  ORDER BY (date_trunc('hour'::text, created_at)) DESC;


