-- Name: VIEW v_spin_unpaid_settlements; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_spin_unpaid_settlements IS 'Operator diagnostic: spin settlements whose credited prize does not match what was drawn. service_role only - it was readable by anon until 2026-08-31 (SECURITY DEFINER view + default anon grant).';


--
-- Name: v_tournament_rake_attribution_gaps; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_tournament_rake_attribution_gaps WITH (security_invoker='true') AS
 SELECT r.tournament_id,
    r.club_id,
    r.amount,
    r.source,
    r.settled_at,
    r.attributed_at,
    r.attributed_users,
    r.attribution_error,
    t.tournament_type,
    t.variant,
    t.name,
    t.buy_in_amount,
        CASE
            WHEN (r.attributed_users IS NULL) THEN 'never_measured'::text
            WHEN (r.attributed_users = '-1'::integer) THEN 'attribution_threw'::text
            WHEN (r.attributed_users = 0) THEN 'credited_nobody'::text
            ELSE 'ok'::text
        END AS verdict
   FROM (public.tournament_rake_settlements r
     LEFT JOIN public.tournaments t ON ((t.id = r.tournament_id)))
  WHERE ((r.settled_at IS NOT NULL) AND (r.amount > (0)::numeric) AND ((r.attributed_users IS NULL) OR (r.attributed_users <= 0)));


ALTER VIEW public.v_tournament_rake_attribution_gaps OWNER TO postgres;

--
-- Name: VIEW v_tournament_rake_attribution_gaps; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_tournament_rake_attribution_gaps IS 'Settled rake that reached nobody. Before 2026-08-31 this shape was invisible: fn_settle_tournament_rake stamped attributed_at whenever attribution returned ok, including when it credited zero players, so the repair sweep (which selects attributed_at IS NULL) could never see it.';


--
-- Name: video_transcode_jobs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.video_transcode_jobs (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    post_id uuid,
    reel_id uuid,
    user_id uuid,
    source_url text,
    youtube_url text,
    source_type text DEFAULT 'user'::text,
    status text DEFAULT 'queued'::text NOT NULL,
    target_format text,
    target_bitrate integer,
    progress numeric,
    output_url text,
    error_message text,
    worker_id text,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    attempts integer DEFAULT 0 NOT NULL,
    locked_at timestamp with time zone,
    origin_type text DEFAULT 'legacy'::text NOT NULL,
    rights_status text DEFAULT 'unknown'::text NOT NULL,
    source_asset_id uuid,
    canonical_asset_key text,
    claim_token uuid,
    heartbeat_at timestamp with time zone,
    CONSTRAINT video_transcode_jobs_claim_lease_check CHECK (((source_type <> 'youtube'::text) OR (status <> 'processing'::text) OR ((claim_token IS NOT NULL) AND (worker_id IS NOT NULL) AND (btrim(worker_id) <> ''::text) AND (locked_at IS NOT NULL) AND (heartbeat_at IS NOT NULL)))),
    CONSTRAINT video_transcode_jobs_native_rights_check CHECK (((source_type <> 'youtube'::text) OR (status <> ALL (ARRAY['queued'::text, 'processing'::text, 'running'::text])) OR (rights_status = ANY (ARRAY['owned'::text, 'licensed'::text])))),
    CONSTRAINT video_transcode_jobs_origin_type_check CHECK ((origin_type = ANY (ARRAY['user_upload'::text, 'story'::text, 'social_post'::text, 'video_library'::text, 'horse'::text, 'pokernews'::text, 'generated'::text, 'legacy'::text]))),
    CONSTRAINT video_transcode_jobs_rights_status_check CHECK ((rights_status = ANY (ARRAY['unknown'::text, 'embed_only'::text, 'owned'::text, 'licensed'::text, 'user_authorized'::text, 'restricted'::text]))),
    CONSTRAINT video_transcode_jobs_source_type_check CHECK ((source_type = ANY (ARRAY['user'::text, 'youtube'::text, 'native'::text, 'video_library'::text]))),
    CONSTRAINT video_transcode_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'running'::text, 'completed'::text, 'done'::text, 'failed'::text, 'cancelled'::text])))
);


ALTER TABLE public.video_transcode_jobs OWNER TO postgres;

