    CONSTRAINT venue_live_tables_observation_kind_check CHECK ((observation_kind = ANY (ARRAY['observed'::text, 'catalog'::text, 'modeled'::text]))),
    CONSTRAINT venue_live_tables_provenance_consistency_check CHECK (((((COALESCE(scrape_batch_id, ''::text) ~~ 'sim-%'::text) OR (lower(COALESCE(source, ''::text)) = ANY (ARRAY['bravo-simulator'::text, 'bravo_simulator'::text, 'modeled_cash_game'::text]))) = (observation_kind = 'modeled'::text)) AND ((lower(COALESCE(source, ''::text)) = 'pokeratlas'::text) = (observation_kind = 'catalog'::text))))
);


