    CONSTRAINT venue_location_integrity_state_primary_issue_check CHECK (((primary_issue IS NULL) OR (primary_issue = ANY (ARRAY['conflict'::text, 'missing'::text, 'duplicate'::text, 'unverified'::text, 'incomplete'::text, 'stale'::text]))))
);


