--
-- Name: COLUMN video_library_videos.type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.video_library_videos.type IS 'Content vertical: cash | tournament | slots. Deliberately a CHECK rather than free text - on 2026-09-04 a scraper change started writing an unlisted value and this constraint refused every row, which is how the mistake was found within minutes instead of shipping a category nothing renders.';


--
-- Name: video_library_health; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.video_library_health WITH (security_invoker='true') AS
 SELECT source_id,
    count(*) AS total_videos,
    count(*) FILTER (WHERE (duration IS NULL)) AS missing_duration,
    count(*) FILTER (WHERE ((views_count = 0) OR (views_count IS NULL))) AS zero_views,
    count(*) FILTER (WHERE ((published_at)::date = CURRENT_DATE)) AS fake_dates,
    max(scraped_at) AS last_scraped,
    min(published_at) AS oldest_video,
    max(published_at) AS newest_video
   FROM public.video_library_videos
  GROUP BY source_id
  ORDER BY (count(*)) DESC;


ALTER VIEW public.video_library_health OWNER TO postgres;

--
-- Name: VIEW video_library_health; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.video_library_health IS 'Per-creator health metrics for the video library. Check fake_dates to monitor backfill progress.';


--
-- Name: video_library_public_catalog; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.video_library_public_catalog WITH (security_barrier='true', security_invoker='true') AS
 SELECT youtube_video_id,
    source_id,
    source_name,
    type,
    title,
    thumbnail_url,
    views_text,
    views_count,
    duration,
    published_at,
    scraped_at,
    tags,
    availability_status,
    embeddable,
    availability_checked_at
   FROM public.video_library_videos v
  WHERE public.fn_is_video_library_asset_eligible(id);


ALTER VIEW public.video_library_public_catalog OWNER TO postgres;

