    chips_minted numeric(16,2) DEFAULT 0 NOT NULL,
    mint_carry numeric(10,6) DEFAULT 0 NOT NULL,
    chips_paid numeric(16,2) DEFAULT 0 NOT NULL,
    diamond_float numeric(16,4) DEFAULT 0 NOT NULL,
    diamonds_paid numeric(18,0) DEFAULT 0 NOT NULL,
    constrained_spins bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    diamond_seed numeric(16,4) DEFAULT 0 NOT NULL,
    CONSTRAINT wheel_pools_diamond_float_check CHECK ((diamond_float >= (0)::numeric)),
    CONSTRAINT wheel_pools_diamond_seed_check CHECK ((diamond_seed >= (0)::numeric)),
    CONSTRAINT wheel_pools_mint_carry_check CHECK (((mint_carry >= (0)::numeric) AND (mint_carry < 0.01)))
);


ALTER TABLE public.wheel_pools OWNER TO postgres;

--
-- Name: TABLE wheel_pools; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.wheel_pools IS 'Diamond Wheel economics per host. Invariant, checked on every spin and by fn_wheel_metrics: chips_paid <= chips_minted + exposure_allowance_chips, and diamond_float >= 0. chips_minted is the chip share of intake; diamond_float is the diamond share less diamond prizes; the rest is the house.';


--
-- Name: COLUMN wheel_pools.diamond_seed; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.wheel_pools.diamond_seed IS 'The seed included in diamond_float. Accrued diamond share = diamond_float - diamond_seed + diamonds_paid.';


