--
-- Name: cron_health_log Admin access to cron health; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admin access to cron health" ON public.cron_health_log USING ((EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND (profiles.role = 'admin'::text)))));


--
-- Name: messenger_admin_messages Admins can manage all admin messages; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can manage all admin messages" ON public.messenger_admin_messages USING ((EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND (profiles.role = ANY (ARRAY['admin'::text, 'god'::text, 'super_admin'::text]))))));


--
-- Name: trivia_question_reports Admins can manage all reports; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can manage all reports" ON public.trivia_question_reports TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND (profiles.is_admin = true))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND (profiles.is_admin = true)))));


--
-- Name: messenger_participants Admins can manage participants; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins can manage participants" ON public.messenger_participants FOR DELETE USING (public.fn_user_is_conversation_admin(conversation_id));


