CREATE POLICY "Admins manage video queue" ON public.video_generation_queue USING ((((( SELECT auth.jwt() AS jwt) ->> 'role'::text) = 'admin'::text) OR ((( SELECT auth.jwt() AS jwt) ->> 'email'::text) = 'admin@smarter.poker'::text)));


