--
-- Name: blacklists blacklists_delete; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY blacklists_delete ON public.blacklists FOR DELETE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.club_members cm
  WHERE ((cm.club_id = blacklists.club_id) AND (cm.user_id = ( SELECT auth.uid() AS uid)) AND (cm.role = ANY (ARRAY['owner'::text, 'co_owner'::text, 'admin'::text, 'super_agent'::text]))))));


