   FROM public.club_members cm
  WHERE ((cm.club_id = blacklists.club_id) AND (cm.user_id = ( SELECT auth.uid() AS uid)) AND (cm.role = ANY (ARRAY['owner'::text, 'co_owner'::text, 'admin'::text, 'super_agent'::text])))))));


--
-- Name: blacklists blacklists_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY blacklists_select ON public.blacklists FOR SELECT USING (((EXISTS ( SELECT 1
   FROM public.club_members cm
  WHERE ((cm.club_id = blacklists.club_id) AND (cm.user_id = ( SELECT auth.uid() AS uid)) AND (cm.role = ANY (ARRAY['owner'::text, 'co_owner'::text, 'admin'::text]))))) OR (EXISTS ( SELECT 1
   FROM public.agents a
  WHERE ((a.club_id = blacklists.club_id) AND (a.user_id = ( SELECT auth.uid() AS uid)) AND (a.status = 'active'::text))))));


