--
-- Name: ca_hand_flags ca_hand_flags_select_staff; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY ca_hand_flags_select_staff ON public.ca_hand_flags FOR SELECT TO authenticated USING (((EXISTS ( SELECT 1
   FROM public.club_members m
  WHERE ((m.club_id = ca_hand_flags.club_id) AND (m.user_id = ( SELECT auth.uid() AS uid)) AND COALESCE(m.is_active, true) AND (COALESCE(m.status, 'active'::text) = ANY (ARRAY['active'::text, 'approved'::text])) AND (m.role = ANY (ARRAY['owner'::text, 'co_owner'::text, 'admin'::text, 'manager'::text, 'super_agent'::text, 'agent'::text]))))) OR (EXISTS ( SELECT 1
   FROM public.clubs c
  WHERE ((c.id = ca_hand_flags.club_id) AND (c.owner_id = ( SELECT auth.uid() AS uid)))))));


