--
-- Name: commander_comp_balances comp_balances_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY comp_balances_select ON public.commander_comp_balances FOR SELECT USING (((player_id = ( SELECT auth.uid() AS uid)) OR (venue_id IN ( SELECT commander_staff.venue_id
   FROM public.commander_staff
  WHERE ((commander_staff.user_id = ( SELECT auth.uid() AS uid)) AND (commander_staff.is_active = true))))));


--
-- Name: commander_comp_rates comp_rates_insert; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY comp_rates_insert ON public.commander_comp_rates FOR INSERT WITH CHECK ((venue_id IN ( SELECT commander_staff.venue_id
   FROM public.commander_staff
  WHERE ((commander_staff.user_id = ( SELECT auth.uid() AS uid)) AND (commander_staff.role = ANY (ARRAY['owner'::text, 'manager'::text])) AND (commander_staff.is_active = true)))));


--
-- Name: commander_comp_rates comp_rates_select; Type: POLICY; Schema: public; Owner: postgres
