--
-- Name: commander_home_seat_reservations home_seat_reservations_insert; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY home_seat_reservations_insert ON public.commander_home_seat_reservations FOR INSERT WITH CHECK (((claimed_by_user_id = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM (public.commander_home_game_tables t
     JOIN public.commander_home_games g ON ((g.id = t.game_id)))
  WHERE ((t.id = commander_home_seat_reservations.table_id) AND (public.fn_home_is_group_staff(( SELECT auth.uid() AS uid), g.group_id) OR (g.host_id = ( SELECT auth.uid() AS uid)) OR ((EXISTS ( SELECT 1
           FROM public.commander_home_members m
          WHERE ((m.group_id = g.group_id) AND (m.user_id = ( SELECT auth.uid() AS uid)) AND (m.status = 'approved'::text)))) AND (((commander_home_seat_reservations.is_guest = false) AND (commander_home_seat_reservations.user_id = ( SELECT auth.uid() AS uid))) OR ((commander_home_seat_reservations.is_guest = true) AND (commander_home_seat_reservations.user_id IS NULL) AND (commander_home_seat_reservations.guest_name IS NOT NULL))))))))));


--
-- Name: commander_home_seat_reservations home_seat_reservations_update; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY home_seat_reservations_update ON public.commander_home_seat_reservations FOR UPDATE USING (((( SELECT auth.uid() AS uid) = claimed_by_user_id) OR (( SELECT auth.uid() AS uid) = user_id) OR (EXISTS ( SELECT 1
   FROM (public.commander_home_game_tables t
     JOIN public.commander_home_games g ON ((g.id = t.game_id)))
  WHERE ((t.id = commander_home_seat_reservations.table_id) AND ((g.host_id = ( SELECT auth.uid() AS uid)) OR public.fn_home_is_group_staff(( SELECT auth.uid() AS uid), g.group_id)))))));


