--
-- Name: live_bans lb_sel; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY lb_sel ON public.live_bans FOR SELECT USING (((( SELECT auth.uid() AS uid) = banned_user_id) OR (EXISTS ( SELECT 1
   FROM public.live_streams s
  WHERE ((s.id = live_bans.stream_id) AND (s.broadcaster_id = ( SELECT auth.uid() AS uid)))))));


--
-- Name: POLICY lb_sel ON live_bans; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON POLICY lb_sel ON public.live_bans IS 'A5b fix: ban list is private. Only the banned user (so realtime ban subscription in viewer works) and the broadcaster (for moderation UI) can read. Service-role moderate.js bypass intact for cross-cutting moderation operations.';


--
-- Name: live_comments lc_del; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY lc_del ON public.live_comments FOR DELETE USING (((( SELECT auth.uid() AS uid) = user_id) OR (( SELECT auth.uid() AS uid) IN ( SELECT live_streams.broadcaster_id
   FROM public.live_streams
  WHERE (live_streams.id = live_comments.stream_id)))));


--
-- Name: live_comments lc_sel; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY lc_sel ON public.live_comments FOR SELECT USING (((( SELECT auth.uid() AS uid) IS NULL) OR (( SELECT auth.uid() AS uid) = user_id) OR (EXISTS ( SELECT 1
   FROM public.live_streams s
  WHERE ((s.id = live_comments.stream_id) AND (s.broadcaster_id = ( SELECT auth.uid() AS uid))))) OR ((NOT (EXISTS ( SELECT 1
   FROM public.blocked_users b
  WHERE ((b.blocker_id = ( SELECT auth.uid() AS uid)) AND (b.blocked_id = live_comments.user_id))))) AND (NOT (EXISTS ( SELECT 1
   FROM public.blocked_users b
  WHERE ((b.blocker_id = live_comments.user_id) AND (b.blocked_id = ( SELECT auth.uid() AS uid)))))))));


--
-- Name: POLICY lc_sel ON live_comments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON POLICY lc_sel ON public.live_comments IS 'A5 fix: mutual-block filter enforced at RLS layer so Realtime postgres_changes payloads also respect blocks. Broadcaster sees all comments in their own stream (for moderation). Service-role bypass intact for server-side moderation paths.';


