--
-- Name: live_sessions live_sessions_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY live_sessions_select ON public.live_sessions FOR SELECT USING (((privacy = 'public'::text) OR (user_id = ( SELECT auth.uid() AS uid)) OR ((privacy = 'friends'::text) AND (user_id IN ( SELECT
        CASE
            WHEN (friendships.user_id = ( SELECT auth.uid() AS uid)) THEN friendships.friend_id
            ELSE friendships.user_id
        END AS user_id
   FROM public.friendships
  WHERE ((friendships.status = 'accepted'::text) AND ((friendships.user_id = ( SELECT auth.uid() AS uid)) OR (friendships.friend_id = ( SELECT auth.uid() AS uid)))))))));


