--
-- Name: message_reactions message_reactions_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY message_reactions_select ON public.message_reactions FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.messages m
  WHERE ((m.id = message_reactions.message_id) AND ((m.sender_id = ( SELECT auth.uid() AS uid)) OR (m.recipient_id = ( SELECT auth.uid() AS uid)) OR (m.receiver_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
           FROM public.messages m2
          WHERE ((m2.conversation_id = m.conversation_id) AND ((m2.sender_id = ( SELECT auth.uid() AS uid)) OR (m2.recipient_id = ( SELECT auth.uid() AS uid)) OR (m2.receiver_id = ( SELECT auth.uid() AS uid)))))))))));


