--
-- Name: session_history session_history_select_own; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY session_history_select_own ON public.session_history FOR SELECT TO authenticated USING (((user_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM (public.tables t
     JOIN public.clubs c ON ((c.id = t.club_id)))
  WHERE ((t.id = session_history.table_id) AND ((c.owner_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
           FROM public.club_members cm
          WHERE ((cm.club_id = c.id) AND (cm.user_id = ( SELECT auth.uid() AS uid)) AND (cm.role = ANY (ARRAY['owner'::text, 'co_owner'::text, 'admin'::text])))))))))));


