--
-- Name: social_posts video_posts_public_select_guard; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY video_posts_public_select_guard ON public.social_posts AS RESTRICTIVE FOR SELECT TO anon, authenticated USING (((COALESCE(is_deleted, false) = false) AND ((author_id = ( SELECT auth.uid() AS uid)) OR (visibility IS DISTINCT FROM 'private'::text)) AND public.fn_can_view_post(author_id, COALESCE(audience_mode, NULLIF(visibility, 'public'::text), 'public'::text), audience_list) AND ((content_type IS DISTINCT FROM 'video'::text) OR (author_id = ( SELECT auth.uid() AS uid)) OR public.legacy_transition_eligible(social_posts.*) OR public.fn_is_public_video_playback_eligible(playback_type, rights_status, NULLIF((media_urls ->> 0), ''::text), author_id, youtube_video_id, canonical_asset_key)) AND (public.legacy_transition_eligible(social_posts.*) OR (origin_type <> 'video_library'::text) OR public.fn_is_video_library_lineage_eligible(source_asset_id, youtube_video_id, canonical_asset_key, publication_key, NULLIF((media_urls ->> 0), ''::text)))));


