--
-- Name: social_reels video_reels_public_select_guard; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY video_reels_public_select_guard ON public.social_reels AS RESTRICTIVE FOR SELECT TO anon, authenticated USING (((COALESCE(is_deleted, false) = false) AND ((author_id = ( SELECT auth.uid() AS uid)) OR ((is_public = true) AND (public.legacy_transition_eligible(social_reels.*) OR public.fn_is_public_video_playback_eligible(playback_type, rights_status, video_url, author_id, youtube_video_id, canonical_asset_key)))) AND (public.legacy_transition_eligible(social_reels.*) OR ((origin_type <> 'video_library'::text) AND (source_type IS DISTINCT FROM 'video_library'::text)) OR ((origin_type = 'video_library'::text) AND (source_type = 'video_library'::text) AND public.fn_is_video_library_lineage_eligible(source_asset_id, youtube_video_id, canonical_asset_key, publication_key, video_url))) AND ((source_post_id IS NULL) OR (EXISTS ( SELECT 1
   FROM public.social_posts linked_post
  WHERE (linked_post.id = social_reels.source_post_id))))));


